UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신전 중앙으로 가서 자연 격노의 뿔피리를 사용하십시오!', `MaleText_loc4`='进入神庙中心，使用元素愤怒号角！', `MaleText_loc5`='在神殿的中央吹響元素烈怒號角!', `MaleText_loc7`='¡Ve al centro del templo y usa el cuerno de Furia Elemental!' WHERE `ID`=36207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 늑대인간 천지였어... 내가 죽었어야 했는데...', `MaleText_loc4`='这里到处都是狼人……那本应该是我……', `MaleText_loc5`='到處都是狼人...本來應該是我...', `MaleText_loc7`='Había huargen por todas partes... Debí haber sido yo.' WHERE `ID`=36208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스는 곧 포세이큰에게 함락될 것이다!', `MaleText_loc4`='吉尔尼斯很快就将落入被遗忘者手中！', `MaleText_loc5`='吉爾尼斯很快將歸被遺忘者所有!', `MaleText_loc7`='¡Gilneas pronto pertenecerá a los Renegados!', `FemaleText_loc1`='길니아스는 곧 포세이큰에게 함락될 것이다!', `FemaleText_loc4`='吉尔尼斯很快就将落入被遗忘者手中！', `FemaleText_loc5`='吉爾尼斯很快將歸被遺忘者所有!', `FemaleText_loc7`='¡Gilneas pronto pertenecerá a los Renegados!' WHERE `ID`=36209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 찾는 자들은 연금술 실험실에 있네. 학자 허버트 핼시, 학자 마쉬라고 하지. 그들을 만날 땐 뒤를 조심하게.', `MaleText_loc4`='你可以在炼金区找到他们。你可以叫他们赫伯特·哈尔希医生和马尔什医生。要小心。', `MaleText_loc5`='你可以在鍊金房找到他們。名字是赫伯特·哈爾希醫生和馬許醫生。自己當心吧。', `MaleText_loc7`='Los encontrarás en El Apothecarium. Sus nombres son doctor Herbert Halsey y doctor Marsh. Vigila tus espaldas.', `FemaleText_loc1`='자네가 찾는 자들은 연금술 실험실에 있네. 학자 허버트 핼시, 학자 마쉬라고 하지. 그들을 만날 땐 뒤를 조심하게.', `FemaleText_loc4`='你可以在炼金区找到他们。你可以叫他们赫伯特·哈尔希医生和马尔什医生。要小心。', `FemaleText_loc5`='你可以在鍊金房找到他們。名字是赫伯特·哈爾希醫生和馬許醫生。自己當心吧。', `FemaleText_loc7`='Los encontrarás en El Apothecarium. Sus nombres son doctor Herbert Halsey y doctor Marsh. Vigila tus espaldas.' WHERE `ID`=36210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학자 허버트 핼시가 바로 자네가 찾는 사람일세. 하지만 그와 농담을 주고받을 생각은 말게. 그자가 역병이 어쩌고저쩌고하며 떠들면 손이 저절로 도끼로 향할 테니.', `MaleText_loc4`='赫伯特·哈尔希医生就是你要找的人。别干傻事。再搞那种无聊的瘟疫，你的脑袋就得搬家。', `MaleText_loc5`='赫伯特·哈爾希醫生正是你需要的人選。只不過別亂胡鬧。任何愚蠢的舉動，你就會發現有把斧頭砍會在一個你非常不舒服的位置上。', `MaleText_loc7`='Buscas al doctor Herbert Halsey. Pero no hagas nada raro. Cualquier tontería de esas de la peste y te encontrarás con un hacha clavada en lugares incómodos.', `FemaleText_loc1`='학자 허버트 핼시가 바로 자네가 찾는 사람일세. 하지만 그와 농담을 주고받을 생각은 말게. 그자가 역병이 어쩌고저쩌고하며 떠들면 손이 저절로 도끼로 향할 테니.', `FemaleText_loc4`='赫伯特·哈尔希医生就是你要找的人。别干傻事。再搞那种无聊的瘟疫，你的脑袋就得搬家。', `FemaleText_loc5`='赫伯特·哈爾希醫生正是你需要的人選。只不過別亂胡鬧。任何愚蠢的舉動，你就會發現有把斧頭砍會在一個你非常不舒服的位置上。', `FemaleText_loc7`='Buscas al doctor Herbert Halsey. Pero no hagas nada raro. Cualquier tontería de esas de la peste y te encontrarás con un hacha clavada en lugares incómodos.' WHERE `ID`=36211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕실에 있는 그리즐 하프메인이 자네가 찾는 오크일세.', `MaleText_loc4`='皇家区的兽人格里兹尔就是你要找的人。', `MaleText_loc5`='皇家區的格里茲爾·半鬃就是你要找的獸人。', `MaleText_loc7`='El orco al que buscas es Grizzle Mediamelena, en el Barrio Real.', `FemaleText_loc1`='왕실에 있는 그리즐 하프메인이 자네가 찾는 오크일세.', `FemaleText_loc4`='皇家区的兽人格里兹尔就是你要找的人。', `FemaleText_loc5`='皇家區的格里茲爾·半鬃就是你要找的獸人。', `FemaleText_loc7`='El orco al que buscas es Grizzle Mediamelena, en el Barrio Real.' WHERE `ID`=36212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티에서 복무하는 전투모병관은 그리즐 하프메인이라고 하네. 한창땐 무시무시한 전사였지. 왕실로 가보게.', `MaleText_loc4`='格里兹尔是幽暗城的战场军官，他是那个年代最勇猛的战士。你可以在皇家区找到他。', `MaleText_loc5`='幽暗城的戰場軍官是格里茲爾·半鬃 - 年輕的時候可是個勇猛的戰士。他就在皇家區。', `MaleText_loc7`='El maestro de batalla que se encarga de Entrañas es Grizzle Mediamelena, un feroz luchador. Se encuentra en el Barrio Real.', `FemaleText_loc1`='언더시티에서 복무하는 전투모병관은 그리즐 하프메인이라고 하네. 한창땐 무시무시한 전사였지. 왕실로 가보게.', `FemaleText_loc4`='格里兹尔是幽暗城的战场军官，他是那个年代最勇猛的战士。你可以在皇家区找到他。', `FemaleText_loc5`='幽暗城的戰場軍官是格里茲爾·半鬃 - 年輕的時候可是個勇猛的戰士。他就在皇家區。', `FemaleText_loc7`='El maestro de batalla que se encarga de Entrañas es Grizzle Mediamelena, un feroz luchador. Se encuentra en el Barrio Real.' WHERE `ID`=36213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말로리 휠러 경을 찾는구먼. 그는 다른 전투모병관들과 함께 왕실에 있네.', `MaleText_loc4`='你可以去找玛洛维尔爵士。他和其他战场军官一样，都呆在皇家区。', `MaleText_loc5`='你要找瑪洛維爾爵士。他就在皇家區跟其他的戰場軍官一起。', `MaleText_loc7`='Buscas a Sir Malory Wheeler. Se encuentra en el Barrio Real, con los demás maestros de batalla.', `FemaleText_loc1`='말로리 휠러 경을 찾는구먼. 그는 다른 전투모병관들과 함께 왕실에 있네.', `FemaleText_loc4`='你可以去找玛洛维尔爵士。他和其他战场军官一样，都呆在皇家区。', `FemaleText_loc5`='你要找瑪洛維爾爵士。他就在皇家區跟其他的戰場軍官一起。', `FemaleText_loc7`='Buscas a Sir Malory Wheeler. Se encuentra en el Barrio Real, con los demás maestros de batalla.' WHERE `ID`=36214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸단을 돕고 싶은가? 왕실로 가서 말로리 휠러 경과 얘기하게. 그가 안내해 줄 걸세.', `MaleText_loc4`='你想帮助污染者吗？同皇家区的玛洛维尔爵士谈一谈。他是你要找的人。', `MaleText_loc5`='你想協助污染者?前往皇家區，去跟瑪洛維爾爵士談談吧。他就是你要找的人。', `MaleText_loc7`='¿Quieres ayudar a los Rapiñadores? Dirígete al Barrio Real y habla con Sir Malory Wheeler. Él es tu hombre.', `FemaleText_loc1`='파멸단을 돕고 싶은가? 왕실로 가서 말로리 휠러 경과 얘기하게. 그가 안내해 줄 걸세.', `FemaleText_loc4`='你想帮助污染者吗？同皇家区的玛洛维尔爵士谈一谈。他是你要找的人。', `FemaleText_loc5`='你想協助污染者?前往皇家區，去跟瑪洛維爾爵士談談吧。他就是你要找的人。', `FemaleText_loc7`='¿Quieres ayudar a los Rapiñadores? Dirígete al Barrio Real y habla con Sir Malory Wheeler. Él es tu hombre.' WHERE `ID`=36215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 중앙에 있는 원 쪽으로 가보게. 거기에 경매인들이 서 있지.', `MaleText_loc4`='所有的拍卖师都在中央区域。', `MaleText_loc5`='前往中環區，你會找到駐紮在那邊的拍賣師。', `MaleText_loc7`='Dirígete al anillo central. Allí encontrarás a todos los subastadores.', `FemaleText_loc1`='도시 중앙에 있는 원 쪽으로 가보게. 거기에 경매인들이 서 있지.', `FemaleText_loc4`='所有的拍卖师都在中央区域。', `FemaleText_loc5`='前往中環區，你會找到駐紮在那邊的拍賣師。', `FemaleText_loc7`='Dirígete al anillo central. Allí encontrarás a todos los subastadores.' WHERE `ID`=36216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매에 참여하고 싶거든 도시 중앙에 있는 원 쪽으로 가보게.', `MaleText_loc4`='如果你想看看这里的市场，那么就到中央区域去吧。', `MaleText_loc5`='如果你想進入此處的市場，就去本城的中環區吧。', `MaleText_loc7`='Si quieres acceder al mercado aquí, ve al anillo central de la ciudad.', `FemaleText_loc1`='경매에 참여하고 싶거든 도시 중앙에 있는 원 쪽으로 가보게.', `FemaleText_loc4`='如果你想看看这里的市场，那么就到中央区域去吧。', `FemaleText_loc5`='如果你想進入此處的市場，就去本城的中環區吧。', `FemaleText_loc7`='Si quieres acceder al mercado aquí, ve al anillo central de la ciudad.' WHERE `ID`=36217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카우피? 기억의 물약? 하! 이건 기억 물약이 아냐.', `MaleText_loc4`='卡啡？记忆药水？哈！这可不是记忆药水。', `MaleText_loc5`='咖灰?記憶藥水?哈!這不是記憶藥水。', `MaleText_loc7`='¿Kawphi? ¿Poción de memoria? ¡Ja! ¡Esto no es una poción de memoria!' WHERE `ID`=36218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행 말인가? 상업 지구 정중앙에 있네.', `MaleText_loc4`='银行？就在贸易区中间的塔里。', `MaleText_loc5`='銀行?貿易區中央的那座塔就是了。', `MaleText_loc7`='¿El banco? Es esa torre en el centro del Barrio del Comercio.', `FemaleText_loc1`='은행 말인가? 상업 지구 정중앙에 있네.', `FemaleText_loc4`='银行？就在贸易区中间的塔里。', `FemaleText_loc5`='銀行?貿易區中央的那座塔就是了。', `FemaleText_loc7`='¿El banco? Es esa torre en el centro del Barrio del Comercio.' WHERE `ID`=36219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억 물약에 필요한 건 그것이 전부입니까, 어글?', `MaleText_loc4`='那么，厄格尔罗，这些就是你的记忆药水所需要的全部东西么？', `MaleText_loc5`='所以厄爾勾，這就是做出你的記憶藥水所需要的全部材料嗎?\\', `MaleText_loc7`='Ergll, ¿entonces eso era todo lo que necesitabas para tu poción de memoria?', `FemaleText_loc1`='기억 물약에 필요한 건 그것이 전부입니까, 어글?', `FemaleText_loc4`='那么，厄格尔罗，这些就是你的记忆药水所需要的全部东西么？', `FemaleText_loc5`='所以厄爾勾，這就是做出你的記憶藥水所需要的全部材料嗎?\\', `FemaleText_loc7`='Ergll, ¿entonces eso era todo lo que necesitabas para tu poción de memoria?' WHERE `ID`=36220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 무엇인가요?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Entonces qué?', `FemaleText_loc1`='그럼 무엇인가요?', `FemaleText_loc4`='这是什么？', `FemaleText_loc5`='那是什麼?', `FemaleText_loc7`='¿Entonces qué?' WHERE `ID`=36221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아침엔 혼자 일어나야 해. 햇빛 때문에 피곤해. 생각이 잘 안 나.', `MaleText_loc4`='早晨，我让自己醒来时。太阳总是让我觉得很累，难以思考。', `MaleText_loc5`='它一大早就把我叫起來。太陽讓我感到疲倦，難以思考。', `MaleText_loc7`='Yo levantarme por las mañanas. Sol fatigarme. Difícil pensar.' WHERE `ID`=36222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 모두 잠에서 깨는 데 필요한 물건인가요? 그런 용도라면 확실한 효과가 있는 무기가 몇 가지 있습니다만.', `MaleText_loc4`='所有这些只是为了叫醒你？我相信我有好几种武器都能做到这一点。', `MaleText_loc5`='就為了把你叫起來?我相信我有一些武器可以有效地解決這個問題。', `MaleText_loc7`='¿Todo eso solo para despertarte? Estoy seguro de que tenemos varias armas que podrían haberlo conseguido.', `FemaleText_loc1`='그게 모두 잠에서 깨는 데 필요한 물건인가요? 그런 용도라면 확실한 효과가 있는 무기가 몇 가지 있습니다만.', `FemaleText_loc4`='所有这些只是为了叫醒你？我相信我有好几种武器都能做到这一点。', `FemaleText_loc5`='就為了把你叫起來?我相信我有一些武器可以有效地解決這個問題。', `FemaleText_loc7`='¿Todo eso solo para despertarte? Estoy segura de que tenemos varias armas que podrían haberlo conseguido.' WHERE `ID`=36223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각에 더 믿을 만한 방법이 있어.', `MaleText_loc4`='我相信这个方式会更可靠。', `MaleText_loc5`='我想這樣應該更可靠。', `MaleText_loc7`='Creo que así es más fiable.' WHERE `ID`=36224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼...아주어고스는 어디에 있습니까, 어글?', `MaleText_loc4`='那么……厄格尔罗，我能在哪里找到艾索雷葛斯？', `MaleText_loc5`='那...厄爾勾，我在哪可以找到艾索雷葛斯?', `MaleText_loc7`='Bueno... ¿Dónde puedo encontrar a Azuregos, Ergll?', `FemaleText_loc1`='그럼...아주어고스는 어디에 있습니까, 어글?', `FemaleText_loc4`='那么……厄格尔罗，我能在哪里找到艾索雷葛斯？', `FemaleText_loc5`='那...厄爾勾，我在哪可以找到艾索雷葛斯?', `FemaleText_loc7`='Bueno... ¿Dónde puedo encontrar a Azuregos, Ergll?' WHERE `ID`=36225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주어고스! 기억나. 크고 파랗고 송곳니가 커. 화만 내지 않는다면 아주 멋진 친구지. 요 몇 주간 보지 못했는데.', `MaleText_loc4`='艾索雷葛斯！我记得他。又高又蓝，大牙齿。真是个好家伙，虽然有点怪癖。有几个星期没见他了。', `MaleText_loc5`='艾索雷葛斯?我還記得他。又高又藍，還有大大的尖牙。看起來不錯，但就是有點瘋瘋癲癲的。我已經好幾週沒有看到他了。', `MaleText_loc7`='¡Azuregos! Lo recuerdo. Alto, azul, colmillos grandes. Bastante majo, pero un poco descabellado. Hace semanas que no le veo.' WHERE `ID`=36226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시의 정중앙에 있지. 바퀴의 축이라고나 할까.', `MaleText_loc4`='就在城的正中央。中心区的小房间。', `MaleText_loc5`='就在城市的中央。輪子中的輪軸。', `MaleText_loc7`='Está justo en el centro de la ciudad. El centro de la rueda.', `FemaleText_loc1`='도시의 정중앙에 있지. 바퀴의 축이라고나 할까.', `FemaleText_loc4`='就在城的正中央。中心区的小房间。', `FemaleText_loc5`='就在城市的中央。輪子中的輪軸。', `FemaleText_loc7`='Está justo en el centro de la ciudad. El centro de la rueda.' WHERE `ID`=36227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈니크가 이 지역 미용사일세. 상업 지구 꼭대기 층에 그가 낸 상점이 있지.', `MaleText_loc4`='纳兹尼克是这里的理发师。他的理发店就开在贸易区的上层区域。', `MaleText_loc5`='那茲尼克的本地美容沙龍。店就開在貿易區的最上層。', `MaleText_loc7`='Naznik es el peluquero local. Ha montado un negocio en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='나즈니크가 이 지역 미용사일세. 상업 지구 꼭대기 층에 그가 낸 상점이 있지.', `FemaleText_loc4`='纳兹尼克是这里的理发师。他的理发店就开在贸易区的上层区域。', `FemaleText_loc5`='那茲尼克的本地美容沙龍。店就開在貿易區的最上層。', `FemaleText_loc7`='Naznik es el peluquero local. Ha montado un negocio en el anillo superior del Barrio del Comercio.' WHERE `ID`=36228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마이클 가레트가 언더시티 박쥐들을 돌보지. 상업 지구 위층에 가보게.', `MaleText_loc4`='迈克尔·加勒特是幽暗城的蝙蝠管理员。他就在贸易区的上层区域。', `MaleText_loc5`='麥可·加勒特負責幽暗城的蝙蝠。他就在貿易區的上層。', `MaleText_loc7`='Michael Garrett se encarga de los murciélagos de Entrañas. Se encuentra en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='마이클 가레트가 언더시티 박쥐들을 돌보지. 상업 지구 위층에 가보게.', `FemaleText_loc4`='迈克尔·加勒特是幽暗城的蝙蝠管理员。他就在贸易区的上层区域。', `FemaleText_loc5`='麥可·加勒特負責幽暗城的蝙蝠。他就在貿易區的上層。', `FemaleText_loc7`='Michael Garrett se encarga de los murciélagos de Entrañas. Se encuentra en el anillo superior del Barrio del Comercio.' WHERE `ID`=36229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 위층에 박쥐 조련사가 홰를 세웠지. 냄새가 지독하니 금방 찾을 수 있을 걸세.', `MaleText_loc4`='蝙蝠管理员的架子就搭在贸易区的上层区域。远远的就会闻到那股味儿的。', `MaleText_loc5`='蝙蝠管理員把他的棲棚設在貿易區的上層。你不可能會誤認那個味道。', `MaleText_loc7`='El cuidador de murciélagos tiene su percha en el anillo superior del Barrio del Comercio. El olor no se te pasará por alto.', `FemaleText_loc1`='상업 지구 위층에 박쥐 조련사가 홰를 세웠지. 냄새가 지독하니 금방 찾을 수 있을 걸세.', `FemaleText_loc4`='蝙蝠管理员的架子就搭在贸易区的上层区域。远远的就会闻到那股味儿的。', `FemaleText_loc5`='蝙蝠管理員把他的棲棚設在貿易區的上層。你不可能會誤認那個味道。', `FemaleText_loc7`='El cuidador de murciélagos tiene su percha en el anillo superior del Barrio del Comercio. El olor no se te pasará por alto.' WHERE `ID`=36230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투모병관은 왕실에 있지. 알현실 벽 쪽을 돌아가며 찾아보게.', `MaleText_loc4`='战场军官都在皇家区内；你可以在王座厅四周找到他们。', `MaleText_loc5`='戰場軍官駐在皇家區，你可以在王座廳周圍找到他們。', `MaleText_loc7`='Los maestros de batalla se encuentran en el Barrio Real, los encontrarás alrededor de la Sala del Trono.', `FemaleText_loc1`='전투모병관은 왕실에 있지. 알현실 벽 쪽을 돌아가며 찾아보게.', `FemaleText_loc4`='战场军官都在皇家区内；你可以在王座厅四周找到他们。', `FemaleText_loc5`='戰場軍官駐在皇家區，你可以在王座廳周圍找到他們。', `FemaleText_loc7`='Los maestros de batalla se encuentran en el Barrio Real, los encontrarás alrededor de la Sala del Trono.' WHERE `ID`=36231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 전장에 가려고 하나?', `MaleText_loc4`='你要前往哪个战场？', `MaleText_loc5`='你受到那個戰場的號召?', `MaleText_loc7`='¿Qué campo de batalla te llama?', `FemaleText_loc1`='어느 전장에 가려고 하나?', `FemaleText_loc4`='你要前往哪个战场？', `FemaleText_loc5`='你受到那個戰場的號召?', `FemaleText_loc7`='¿Qué campo de batalla te llama?' WHERE `ID`=36232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구에서 제임스 반 브런트가 괜찮은 가열로를 관리하고 있지. 군사 지구 내곽으로 가보게.', `MaleText_loc4`='詹姆斯·范·布朗特的锻造生意一直不错，就在军事区的内环区域。', `MaleText_loc5`='詹姆士·凡·布朗特在軍事區經營一間正派的鐵匠舖。就在內環。', `MaleText_loc7`='James Van Brunt dirige una forja bastante decente en el Barrio de la Guerra. Se encuentra en el anillo interior.', `FemaleText_loc1`='군사 지구에서 제임스 반 브런트가 괜찮은 가열로를 관리하고 있지. 군사 지구 내곽으로 가보게.', `FemaleText_loc4`='詹姆斯·范·布朗特的锻造生意一直不错，就在军事区的内环区域。', `FemaleText_loc5`='詹姆士·凡·布朗特在軍事區經營一間正派的鐵匠舖。就在內環。', `FemaleText_loc7`='James Van Brunt dirige una forja bastante decente en el Barrio de la Guerra. Se encuentra en el anillo interior.' WHERE `ID`=36233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 대장장이는 무기 수요가 가장 많은 군사 지구에서 일하더군. 군사 지구 내곽으로 가보게.', `MaleText_loc4`='铁匠在军事区干活，买了他们武器的人马上就可以在旁边试上一试。铁匠就在那里的内环区域。', `MaleText_loc5`='此地的鐵匠舖在軍事區，就近可以讓他的武器有地方可用。就在內環。', `MaleText_loc7`='El herrero de aquí trabaja en el Barrio de la Guerra, cerca del lugar donde se pondrán en uso sus armas. Está en el anillo interior.', `FemaleText_loc1`='여기 대장장이는 무기 수요가 가장 많은 군사 지구에서 일하더군. 군사 지구 내곽으로 가보게.', `FemaleText_loc4`='铁匠在军事区干活，买了他们武器的人马上就可以在旁边试上一试。铁匠就在那里的内环区域。', `FemaleText_loc5`='此地的鐵匠舖在軍事區，就近可以讓他的武器有地方可用。就在內環。', `FemaleText_loc7`='El herrero de aquí trabaja en el Barrio de la Guerra, cerca del lugar donde se pondrán en uso sus armas. Está en el anillo interior.' WHERE `ID`=36234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 중간층에서 유니스 버치가... 여기서 "음식"이라고 부르는 걸 만들더군. 뭐, 자네가 먹는 거지 내가 먹는 건 아니니까.', `MaleText_loc4`='贸易区的尤奈斯·伯奇是这里的厨师。是你的肚子在叫，不是我的。', `MaleText_loc5`='尤奈斯·伯奇在貿易區把所有能吃的都拿來煮。那是你自己的胃，可不干我的事。', `MaleText_loc7`='Eunice Burch cocina en el Barrio del Comercio lo que aquí llamamos comida. Es tu estómago, no el mío.', `FemaleText_loc1`='상업 지구 중간층에서 유니스 버치가... 여기서 "음식"이라고 부르는 걸 만들더군. 뭐, 자네가 먹는 거지 내가 먹는 건 아니니까.', `FemaleText_loc4`='贸易区的尤奈斯·伯奇是这里的厨师。是你的肚子在叫，不是我的。', `FemaleText_loc5`='尤奈斯·伯奇在貿易區把所有能吃的都拿來煮。那是你自己的胃，可不干我的事。', `FemaleText_loc7`='Eunice Burch cocina en el Barrio del Comercio lo que aquí llamamos comida. Es tu estómago, no el mío.' WHERE `ID`=36235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 요리사는 상업 지구에 있네. 이름은 유니스 버치라고 하더군.', `MaleText_loc4`='这里的厨师是尤奈斯·伯奇，你可以在贸易区找到她。', `MaleText_loc5`='此地的廚師就在貿易區。他的名字叫做尤奈斯·伯奇。', `MaleText_loc7`='La cocinera de aquí se encuentra en el Barrio del Comercio. Se llama Eunice Burch.', `FemaleText_loc1`='여기 요리사는 상업 지구에 있네. 이름은 유니스 버치라고 하더군.', `FemaleText_loc4`='这里的厨师是尤奈斯·伯奇，你可以在贸易区找到她。', `FemaleText_loc5`='此地的廚師就在貿易區。他的名字叫做尤奈斯·伯奇。', `FemaleText_loc7`='La cocinera de aquí se encuentra en el Barrio del Comercio. Se llama Eunice Burch.' WHERE `ID`=36236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라비니아 크로가 이 지역 마법부여사일세. 연금술 실험실 내곽에 그녀의 상점이 있지.', `MaleText_loc4`='拉文尼亚·克洛文是这里的附魔师。他的店就开在炼金区的内环区域。', `MaleText_loc5`='拉玟妮雅·克洛威是此地的附魔師。她的店就開在鍊金房內環。', `MaleText_loc7`='Lavinia Crowe es la encantadora local. Ha montado una tienda en el anillo interior de El Apothecarium.', `FemaleText_loc1`='라비니아 크로가 이 지역 마법부여사일세. 연금술 실험실 내곽에 그녀의 상점이 있지.', `FemaleText_loc4`='拉文尼亚·克洛文是这里的附魔师。他的店就开在炼金区的内环区域。', `FemaleText_loc5`='拉玟妮雅·克洛威是此地的附魔師。她的店就開在鍊金房內環。', `FemaleText_loc7`='Lavinia Crowe es la encantadora local. Ha montado una tienda en el anillo interior de El Apothecarium.' WHERE `ID`=36237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여 기술을 배우고 싶거든, 연금술 실험실 내곽의 라비니아 크로를 찾아가게.', `MaleText_loc4`='炼金区内环区域的拉文尼亚·克洛文可以教你有关附魔的知识。', `MaleText_loc5`='如果你想學附魔，就去找鍊金房內環的拉玟妮雅·克洛威。', `MaleText_loc7`='Si quieres aprender encantamiento, busca a Lavinia Crowe en el anillo interior de El Apothecarium.', `FemaleText_loc1`='마법부여 기술을 배우고 싶거든, 연금술 실험실 내곽의 라비니아 크로를 찾아가게.', `FemaleText_loc4`='炼金区内环区域的拉文尼亚·克洛文可以教你有关附魔的知识。', `FemaleText_loc5`='如果你想學附魔，就去找鍊金房內環的拉玟妮雅·克洛威。', `FemaleText_loc7`='Si quieres aprender encantamiento, busca a Lavinia Crowe en el anillo interior de El Apothecarium.' WHERE `ID`=36238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 기술자 이름은 프랭클린 로이드라고 하네. 도적 지구 외곽에서 뭔가 만지작거리고 있더군.', `MaleText_loc4`='弗兰克林·洛伊德是这里的工程师。他平时都在盗贼区外环区域修修补补。', `MaleText_loc5`='此地的工程師叫做富蘭克林·洛伊德。他的工坊就設在盜賊區外環。', `MaleText_loc7`='El ingeniero de aquí se llama Franklin Lloyd. Hace ajustes en el Barrio de los Pícaros, en el anillo exterior.', `FemaleText_loc1`='여기 기술자 이름은 프랭클린 로이드라고 하네. 도적 지구 외곽에서 뭔가 만지작거리고 있더군.', `FemaleText_loc4`='弗兰克林·洛伊德是这里的工程师。他平时都在盗贼区外环区域修修补补。', `FemaleText_loc5`='此地的工程師叫做富蘭克林·洛伊德。他的工坊就設在盜賊區外環。', `FemaleText_loc7`='El ingeniero de aquí se llama Franklin Lloyd. Hace ajustes en el Barrio de los Pícaros, en el anillo exterior.' WHERE `ID`=36239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적 지구 외곽으로 가면 기술자를 만날 수 있네. 목숨이 아깝지 않거든 맘대로 하게.', `MaleText_loc4`='听着，如果你要去见盗贼区外环区域的那些工程师，那就看好标记。', `MaleText_loc5`='聽著，如果你打算去跟盜賊區外環的工程師談談，那是你的自由。', `MaleText_loc7`='Mira, si quieres ir a hablar con esos ingenieros del anillo exterior del Barrio de los Pícaros, es tu pellejo.', `FemaleText_loc1`='도적 지구 외곽으로 가면 기술자를 만날 수 있네. 목숨이 아깝지 않거든 맘대로 하게.', `FemaleText_loc4`='听着，如果你要去见盗贼区外环区域的那些工程师，那就看好标记。', `FemaleText_loc5`='聽著，如果你打算去跟盜賊區外環的工程師談談，那是你的自由。', `FemaleText_loc7`='Mira, si quieres ir a hablar con esos ingenieros del anillo exterior del Barrio de los Pícaros, es tu pellejo.' WHERE `ID`=36240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메리 에드라스가 자네가 찾는 사람일세. 도적 지구 내곽에 있지.', `MaleText_loc4`='你可以找玛丽·艾塔斯谈一谈。她就呆在盗贼区的内环区域。', `MaleText_loc5`='瑪麗·艾塔斯就是你要找的人。她就在盜賊區的內環。', `MaleText_loc7`='Tú buscas a Mary Edras. Se ha instalado en el anillo interior del Barrio de los Pícaros.', `FemaleText_loc1`='메리 에드라스가 자네가 찾는 사람일세. 도적 지구 내곽에 있지.', `FemaleText_loc4`='你可以找玛丽·艾塔斯谈一谈。她就呆在盗贼区的内环区域。', `FemaleText_loc5`='瑪麗·艾塔斯就是你要找的人。她就在盜賊區的內環。', `FemaleText_loc7`='Tú buscas a Mary Edras. Se ha instalado en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=36241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니까? 몇 주요? 좀 더 확실한 정보는 없습니까?', `MaleText_loc4`='真的？几个星期？你就不能告诉我一些好事么？', `MaleText_loc5`='什麼?好幾週?你真的有那麼無聊嗎?', `MaleText_loc7`='¿En serio? ¿Semanas? ¿No tienes nada mejor?', `FemaleText_loc1`='정말입니까? 몇 주요? 좀 더 확실한 정보는 없습니까?', `FemaleText_loc4`='真的？几个星期？你就不能告诉我一些好事么？', `FemaleText_loc5`='什麼?好幾週?你真的有那麼無聊嗎?', `FemaleText_loc7`='¿En serio? ¿Semanas? ¿No tienes nada mejor?' WHERE `ID`=36242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 친군 항상 이런저런 마법 유물을 찾고 있다고 지껄여댔어. 아즈샤라에 아주 가득 차 있다고 했지. 아무래도 집착이 강했던 것 같아.$B$B최근에 듣기로는 대마법사 뭐시기 실렘이든가? 실렘이 오래된 마법 물품을 발견했다고 말했었어.
', `MaleText_loc4`='他总是嘟囔着要去找到这个或者那个魔法宝物。他说艾萨拉到处都有这种宝物。要我说，他大概是有些强迫症的迹象。$B$B最近我听说他正在和那个叫克希雷姆的大法师交朋友。他说克希雷姆已经找到了一些很强大的魔法物品。', `MaleText_loc5`='他總是在說一些在這神器或那魔器所發現了什麼的廢話，還說艾薩拉這什麼都有。如果你問我，我會說他的占有慾有點強。$B$B我最後一次聽到跟他有關的是他想跟那什麼大法師作朋友。叫克希雷姆吧?他說克希雷姆找到了一些古老的魔法道具。', `MaleText_loc7`='Siempre estaba cotorreando acerca de encontrar tal o cual artefacto mágico. Dijo que Azshara estaba llena de ellos, sí. Estaba un poco obsesionado, si me permites decirlo.$B$BLo último que escuché es que estaba intentando hacerse amigo de ese tal archimago. ¿Xylem? Dijo que Xylem había encontrado algún grandioso objeto antiguo.' WHERE `ID`=36243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 실렘이요? 그 대마법사는 어디에 있습니까, 어글?', `MaleText_loc4`='大法师克希雷姆？厄格尔罗，我在哪里能找到这位大法师？', `MaleText_loc5`='大法師克希雷姆?我在哪可以找到這個大法師?', `MaleText_loc7`='¿El archimago Xylem? ¿Dónde puedo encontrar a ese archimago, Ergll?', `FemaleText_loc1`='대마법사 실렘이요? 그 대마법사는 어디에 있습니까, 어글?', `FemaleText_loc4`='大法师克希雷姆？厄格尔罗，我在哪里能找到这位大法师？', `FemaleText_loc5`='大法師克希雷姆?我在哪可以找到這個大法師?', `FemaleText_loc7`='¿El archimago Xylem? ¿Dónde puedo encontrar a ese archimago, Ergll?' WHERE `ID`=36244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실렘은 사회성이 좀 부족해. 자기 제자한테 얘기하는 거 말고는 항상 혼잣말만 한다고. 다른 사람은 모두 무시하고 말이야.$B$B나보고 제자로 안 받겠대. 너무 들러붙는다나. 내 마음이 마법이건 뭐건 모두 망쳐버리기 때문에 연구에 전혀 도움이 되지 않는다고 했어.
', `MaleText_loc4`='克希雷姆似乎有一点社交恐惧症。大多数时间里，他只是自言自语，偶尔才会和他的学徒说上几句话。对于其他人，他总是视而不见。$B$B他说太笨拙，不能作他的学徒。他还说我的脑子根本学不了魔法，只能被魔法弄得乱七八糟。', `MaleText_loc5`='克希雷姆有點不太喜歡社交。他偶爾會和他的學生說話，但大多時間都是在自言自語，不跟任何以外的人交流。$B$B他不願收我為學生，說我太愛拍馬屁，還說我的腦筋完全不適合放進那些亂七八糟的魔法知識。', `MaleText_loc7`='Xylem no está muy puesto en la vida social. Habla un poco con sus aprendices, pero más que nada se habla a sí mismo. Tiende a ignorar a todos los demás.$B$BNo me quiso como aprendiz, dijo que era demasiado viscoso. Dijo que mi mente no servía para estudiar por estar manchada por la magia y esas cosas.' WHERE `ID`=36245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그에게 질문해서 답을 들을 수 있는 방법이 없을까요?', `MaleText_loc4`='有什么办法能让他回答我的问题？', `MaleText_loc5`='我想讓他回答我一些問題，有什麼建議嗎?', `MaleText_loc7`='¿Sabes cómo puedo hacer que responda a algunas preguntas?', `FemaleText_loc1`='그에게 질문해서 답을 들을 수 있는 방법이 없을까요?', `FemaleText_loc4`='有什么办法能让他回答我的问题？', `FemaleText_loc5`='我想讓他回答我一些問題，有什麼建議嗎?', `FemaleText_loc7`='¿Sabes cómo puedo hacer que responda a algunas preguntas?' WHERE `ID`=36246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 제자가 되는 게 좋아. 근데 그만두는 사람이 엄청 많아.$B$B낙오된 수습생을 지난달에만 벌써 열 명을 넘게 봤으니까. 실렘 때문에 상처를 입고 다들 왔다가 가는 거야. 대마법사의 일에는 선택의 여지가 별로 없나 봐.$B$B오늘도 또 한 명 만났지. 서쪽에 아직 완성되지 않은 큰 기둥으로 가더군.', `MaleText_loc4`='成为大法师的学徒，我猜，大概是件很费周折的事。$B$B光是上个月，我就遇上了十多个被淘汰的学徒。尽管那些气馁的学徒满身伤痕，但却总是会不停地回来继续尝试。我猜，成为大法师的机会并没那么多。$B$B今天我刚刚又遇到一名学徒，他去往了西边，到那座正在建造的巨大石柱那儿去了。', `MaleText_loc5`='成為他的學生吧，我想，他那的流動率還蠻高的。$B$B我光上個月就看到了十幾個被淘汰的學生，他給他們留下了創傷，可是學生還是一直來。我猜，想進入大法師這一行的選項實在不多。$B$B我今天剛好碰到他另一個學生，他往西邊走去了，就是許多懸崖豎立的那裡。', `MaleText_loc7`='Supongo que volverse aprendiz. Un cambio muy grande, la verdad.$B$BSolo este mes, he conocido una docena de aprendices inútiles. Él los deja hechos polvo, aunque continúan viniendo. Supongo que no hay muchas opciones en el negocio de los archimagos.$B$BJusto hoy he conocido a otro. Se dirigía hacia el oeste, a esa enorme columna que están construyendo.' WHERE `ID`=36247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시작이군요. 고마워요, 어글.', `MaleText_loc4`='这是个好的开始。谢谢，厄格尔罗。', `MaleText_loc5`='是個開始。謝啦，厄爾勾。', `MaleText_loc7`='Algo es algo. Gracias, Ergll.', `FemaleText_loc1`='이제 시작이군요. 고마워요, 어글.', `FemaleText_loc4`='这是个好的开始。谢谢，厄格尔罗。', `FemaleText_loc5`='是個開始。謝啦，厄爾勾。', `FemaleText_loc7`='Algo es algo. Gracias, Ergll.' WHERE `ID`=36248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래그래! 만나거든 나 대신 안부 전해줘.', `MaleText_loc4`='是啊，是啊！如果你找到他，代我向他问好。', `MaleText_loc5`='嗯嗯!找到他幫我跟他打個招呼。', `MaleText_loc7`='¡Sí, sí! Salúdale de mi parte si lo encuentras.' WHERE `ID`=36249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 친구. 난 비린내 안 나는 친구가 좋더라.', `MaleText_loc4`='你好！终于见到一个身上没有臭鱼味的人了。我喜欢。', `MaleText_loc5`='哈囉!聞起來不像魚的人，我喜歡。', `MaleText_loc7`='¡Hola! Alguien que no huele a pescado. Me gusta.' WHERE `ID`=36250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸어 다니는 시체도 때로 수선해 줘야지. 메리 에드라스가 그쪽 일을 담당하네. 도적 지구 내곽으로 가보게.', `MaleText_loc4`='即使是行尸走肉也需要维护自己的身体。玛丽·艾塔斯精通此道。她就在盗贼区的内环区域。', `MaleText_loc5`='就算是活死人也需要修補。瑪麗·艾塔斯在此負責這件事情。他就在盜賊區的內環。', `MaleText_loc7`='Incluso los muertos andantes necesitan arreglarse. Mary Edras se encarga de eso. Está en el Barrio de los Pícaros, en el anillo interior.', `FemaleText_loc1`='걸어 다니는 시체도 때로 수선해 줘야지. 메리 에드라스가 그쪽 일을 담당하네. 도적 지구 내곽으로 가보게.', `FemaleText_loc4`='即使是行尸走肉也需要维护自己的身体。玛丽·艾塔斯精通此道。她就在盗贼区的内环区域。', `FemaleText_loc5`='就算是活死人也需要修補。瑪麗·艾塔斯在此負責這件事情。他就在盜賊區的內環。', `FemaleText_loc7`='Incluso los muertos andantes necesitan arreglarse. Mary Edras se encarga de eso. Está en el Barrio de los Pícaros, en el anillo interior.' WHERE `ID`=36251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구 부두에 정신 나간 낚시꾼이 하나 있네.', `MaleText_loc4`='疯狂的渔夫就在魔法区的港口那。', `MaleText_loc5`='瘋狂漁夫就在魔法區的碼頭上。', `MaleText_loc7`='El pescador loco está en el muelle del Barrio de la Magia.', `FemaleText_loc1`='마법 지구 부두에 정신 나간 낚시꾼이 하나 있네.', `FemaleText_loc4`='疯狂的渔夫就在魔法区的港口那。', `FemaleText_loc5`='瘋狂漁夫就在魔法區的碼頭上。', `FemaleText_loc7`='El pescador loco está en el muelle del Barrio de la Magia.' WHERE `ID`=36252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구여.$b$b숲에서 즐거운 시간을 보내고 있다고 믿소만?', `MaleText_loc4`='你好，朋友。$b$b相信你很喜欢这个地方吧？', `MaleText_loc5`='你好，朋友。$b$b我相信你喜歡這片林地，對吧?', `MaleText_loc7`='Saludos, camarada.$b$b¿Disfrutando del claro?' WHERE `ID`=36253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기서 대체 뭐가 잡히는진 모르겠지만, 하여튼 마법 지구 부두에서 알만드 크롬웰이 낚시를 하고 있네.', `MaleText_loc4`='我不知道阿曼德·克伦威尔在试图追赶什么，不过他已经到了魔法区的码头。', `MaleText_loc5`='我不知道他打算在這裡釣什麼，但阿曼德·克倫威爾就在魔法區的碼頭上。', `MaleText_loc7`='No sé qué está intentando atrapar allí, pero Armand Cromwell está en el muelle del Barrio de la Magia.', `FemaleText_loc1`='거기서 대체 뭐가 잡히는진 모르겠지만, 하여튼 마법 지구 부두에서 알만드 크롬웰이 낚시를 하고 있네.', `FemaleText_loc4`='我不知道阿曼德·克伦威尔在试图追赶什么，不过他已经到了魔法区的码头。', `FemaleText_loc5`='我不知道他打算在這裡釣什麼，但阿曼德·克倫威爾就在魔法區的碼頭上。', `FemaleText_loc7`='No sé qué está intentando atrapar allí, pero Armand Cromwell está en el muelle del Barrio de la Magia.' WHERE `ID`=36257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 사무관의 이름은 크리스토퍼 드라쿨이라고 하지. 상업 지구 동쪽 단에 있네.', `MaleText_loc4`='克里斯托弗·德库尔是这里的公会注册员。他的办公区设在贸易区东侧平台。', `MaleText_loc5`='公會註冊員是克里斯多夫·德庫爾。他在貿易區的東邊平臺上。', `MaleText_loc7`='El maestro de hermandad es Christopher Drakul. Se encuentra en la plataforma este en el Barrio del Comercio.', `FemaleText_loc1`='길드 사무관의 이름은 크리스토퍼 드라쿨이라고 하지. 상업 지구 동쪽 단에 있네.', `FemaleText_loc4`='克里斯托弗·德库尔是这里的公会注册员。他的办公区设在贸易区东侧平台。', `FemaleText_loc5`='公會註冊員是克里斯多夫·德庫爾。他在貿易區的東邊平臺上。', `FemaleText_loc7`='El maestro de hermandad es Christopher Drakul. Se encuentra en la plataforma este en el Barrio del Comercio.' WHERE `ID`=36258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 사무관은 상업 지구에서 일을 처리하지. 상업 지구 동쪽 단으로 가보게.', `MaleText_loc4`='公会注册员在贸易区办公。你可以在东侧平台找到他。', `MaleText_loc5`='公會註冊員在貿易區處理他的業務。他就在東邊的平臺。', `MaleText_loc7`='El maestro de hermandad lleva a cabo sus negocios en el Barrio del Comercio. Se encuentra en la plataforma este.', `FemaleText_loc1`='길드 사무관은 상업 지구에서 일을 처리하지. 상업 지구 동쪽 단으로 가보게.', `FemaleText_loc4`='公会注册员在贸易区办公。你可以在东侧平台找到他。', `FemaleText_loc5`='公會註冊員在貿易區處理他的業務。他就在東邊的平臺。', `FemaleText_loc7`='El maestro de hermandad lleva a cabo sus negocios en el Barrio del Comercio. Se encuentra en la plataforma este.' WHERE `ID`=36259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 약초채집사 이름은 마사 알리스타라고 하더군. 연금술 실험실 내곽으로 가보게.', `MaleText_loc4`='马尔萨·奥列斯塔是这里的草药学家。你可以在炼金区的内环区域找到她。', `MaleText_loc5`='這裡的草藥師是瑪莎·奧列斯塔。她就在鍊金房的內環。', `MaleText_loc7`='La herborista por aquí es Martha Alliestar. Se encuentra en el anillo interior de El Apothecarium.', `FemaleText_loc1`='여기 약초채집사 이름은 마사 알리스타라고 하더군. 연금술 실험실 내곽으로 가보게.', `FemaleText_loc4`='马尔萨·奥列斯塔是这里的草药学家。你可以在炼金区的内环区域找到她。', `FemaleText_loc5`='這裡的草藥師是瑪莎·奧列斯塔。她就在鍊金房的內環。', `FemaleText_loc7`='La herborista por aquí es Martha Alliestar. Se encuentra en el anillo interior de El Apothecarium.' WHERE `ID`=36260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술 지구 내곽으로 가보게. 거기 있는 마사 알리스타가 약초채집을 가르쳐 줄 걸세.', `MaleText_loc4`='去炼金区的内环区域，那里的马尔萨·奥列斯塔可以教你有关草药学的知识。', `MaleText_loc5`='前往鍊金房的內環。瑪莎·奧列斯塔就在那邊，她可以指導你草藥學的知識。', `MaleText_loc7`='Dirígete al anillo interior de El Apothecarium. Martha Alliestar se encuentra allí y te instruirá en herboristería.', `FemaleText_loc1`='연금술 지구 내곽으로 가보게. 거기 있는 마사 알리스타가 약초채집을 가르쳐 줄 걸세.', `FemaleText_loc4`='去炼金区的内环区域，那里的马尔萨·奥列斯塔可以教你有关草药学的知识。', `FemaleText_loc5`='前往鍊金房的內環。瑪莎·奧列斯塔就在那邊，她可以指導你草藥學的知識', `FemaleText_loc7`='Dirígete al anillo interior de El Apothecarium. Martha Alliestar se encuentra allí y te instruirá en herboristería.' WHERE `ID`=36261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 여관이라고 할 수 있는진 모르겠지만... 어쨌든 상업 지구 위층으로 가보게. 침대도 하나 없는 곳이지.', `MaleText_loc4`='旅馆——如果算得上的话——在贸易区的上层区域。那里连床铺都没有。', `MaleText_loc5`='旅店 - 如果你要那樣稱呼它的話 - 就在貿易區的上層。但它們那裡甚至沒有床。', `MaleText_loc7`='La posada, si se puede llamar así, está en el anillo superior del Barrio del Comercio. Ni siquiera tienen camas.', `FemaleText_loc1`='그걸 여관이라고 할 수 있는진 모르겠지만... 어쨌든 상업 지구 위층으로 가보게. 침대도 하나 없는 곳이지.', `FemaleText_loc4`='旅馆——如果算得上的话——在贸易区的上层区域。那里连床铺都没有。', `FemaleText_loc5`='旅店 - 如果你要那樣稱呼它的話 - 就在貿易區的上層。但它們那裡甚至沒有床。', `FemaleText_loc7`='La posada, si se puede llamar así, está en el anillo superior del Barrio del Comercio. Ni siquiera tienen camas.' WHERE `ID`=36262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 위층으로 가보게. 여관주인 노먼이 소위 "여관"이라는 먼지투성이 공간을 관리하더군.', `MaleText_loc4`='贸易区上层区域的诺曼是这里的旅店老板，他的店只不过是几面满是灰尘和裂缝的墙壁。', `MaleText_loc5`='旅店老闆諾曼有著一間牆上裂縫滿是灰塵而且自稱是旅店的地方，就在貿易區的上層。', `MaleText_loc7`='El tabernero Norman lleva una polvorienta grieta en la pared a la que llama posada en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='상업 지구 위층으로 가보게. 여관주인 노먼이 소위 "여관"이라는 먼지투성이 공간을 관리하더군.', `FemaleText_loc4`='贸易区上层区域的诺曼是这里的旅店老板，他的店只不过是几面满是灰尘和裂缝的墙壁。', `FemaleText_loc5`='旅店老闆諾曼有著一間牆上裂縫滿是灰塵而且自稱是旅店的地方，就在貿易區的上層。', `FemaleText_loc7`='El tabernero Norman lleva una polvorienta grieta en la pared a la que llama posada en el anillo superior del Barrio del Comercio.' WHERE `ID`=36263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시의 각인사는 연금술 실험실에 있지. 마고 파슐리라는 이름일세.', `MaleText_loc4`='这里的抄写员在炼金区，他的名字叫玛尔迦丝·帕克雷。', `MaleText_loc5`='城裡的雕銘師就在鍊金房，一個叫做瑪苟·帕切里的人。', `MaleText_loc7`='La escriba de la ciudad está en El Apothecarium, alguien llamada Margaux Pastoseco.', `FemaleText_loc1`='이 도시의 각인사는 연금술 실험실에 있지. 마고 파슐리라는 이름일세.', `FemaleText_loc4`='这里的抄写员在炼金区，他的名字叫玛尔迦丝·帕克雷。', `FemaleText_loc5`='城裡的雕銘師就在鍊金房，一個叫做瑪苟·帕切里的人。', `FemaleText_loc7`='La escriba de la ciudad está en El Apothecarium, alguien llamada Margaux Pastoseco.' WHERE `ID`=36264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시의 가죽세공인은 도적 지구 내곽에 있네.', `MaleText_loc4`='城里的皮匠在盗贼区的内环区域。', `MaleText_loc5`='城裡的製皮師就在盜賊區的內環。', `MaleText_loc7`='El peletero de la ciudad se encuentra en el anillo interior del Barrio de los Pícaros.', `FemaleText_loc1`='이 도시의 가죽세공인은 도적 지구 내곽에 있네.', `FemaleText_loc4`='城里的皮匠在盗贼区的内环区域。', `FemaleText_loc5`='城裡的製皮師就在盜賊區的內環。', `FemaleText_loc7`='El peletero de la ciudad se encuentra en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=36265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서 무어라는 자가 가죽세공인일세. 도적 지구 내곽에서 수습생들을 가르치지.', `MaleText_loc4`='亚瑟·摩尔是这里的皮匠。他在盗贼区的内环区域传授制皮技能。', `MaleText_loc5`='亞瑟·摩爾是製皮師。他在盜賊區內環訓練那些徒弟。', `MaleText_loc7`='Arthur Moore es el peletero. Atiende a los practicantes en el Barrio de los Pícaros, en el anillo interior.', `FemaleText_loc1`='아서 무어라는 자가 가죽세공인일세. 도적 지구 내곽에서 수습생들을 가르치지.', `FemaleText_loc4`='亚瑟·摩尔是这里的皮匠。他在盗贼区的内环区域传授制皮技能。', `FemaleText_loc5`='亞瑟·摩爾是製皮師。他在盜賊區內環訓練那些徒弟。', `FemaleText_loc7`='Arthur Moore es el peletero. Atiende a los practicantes en el Barrio de los Pícaros, en el anillo interior.' WHERE `ID`=36266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠가 필요하거든 도적 지구의 월터 소레프에게 가보게. 몸조심하고.', `MaleText_loc4`='如果要钥匙，你可以找盗贼区的沃特尔·索雷夫谈一谈，不过要小心。', `MaleText_loc5`='如果你需要鑰匙的話，去和盜賊區的華特·索瑞夫談談，但自己當心。', `MaleText_loc7`='Si necesitas llaves, habla con Walter Soref en el Barrio de los Pícaros, pero ten cuidado.', `FemaleText_loc1`='열쇠가 필요하거든 도적 지구의 월터 소레프에게 가보게. 몸조심하고.', `FemaleText_loc4`='如果要钥匙，你可以找盗贼区的沃特尔·索雷夫谈一谈，不过要小心。', `FemaleText_loc5`='如果你需要鑰匙的話，去和盜賊區的華特·索瑞夫談談，但自己當心。', `FemaleText_loc7`='Si necesitas llaves, habla con Walter Soref en el Barrio de los Pícaros, pero ten cuidado.' WHERE `ID`=36267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사? 마법 지구 중앙 건물에 있지. 그 정도야 자네도 알아서 찾아낼 줄 알았네만.', `MaleText_loc4`='法师？他们都在魔法区的中央建筑中。你得机灵点儿才能找得到。', `MaleText_loc5`='法師?他們都在魔法區，中間的那棟建築。希望你夠聰明能辨認得出來。', `MaleText_loc7`='¿Magos? Están en el Barrio de la Magia, en el edificio central. Pensé que ya habrías sido capaz de llegar a esa conclusión.', `FemaleText_loc1`='마법사? 마법 지구 중앙 건물에 있지. 그 정도야 자네도 알아서 찾아낼 줄 알았네만.', `FemaleText_loc4`='法师？他们都在魔法区的中央建筑中。你得机灵点儿才能找得到。', `FemaleText_loc5`='法師?他們都在魔法區，中間的那棟建築。希望你夠聰明能辨認得出來。', `FemaleText_loc7`='¿Magos? Están en el Barrio de la Magia, en el edificio central. Pensé que ya habrías sido capaz de llegar a esa conclusión.' WHERE `ID`=36268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구 외곽에 계단이 많은 커다란 건물이 있지. 거기가 마법사들이 숨은 곳일세.', `MaleText_loc4`='在魔法区的外环区域你能找到一座大型、阶梯式的建筑。法师们都在那里。', `MaleText_loc5`='在魔法區的外環，你可以找到一棟大型，有階梯的建築。那就是法師的藏身之處。', `MaleText_loc7`='En el anillo exterior del Barrio de la Magia encontrarás un gran edificio escalonado. Ahí es donde se esconden los magos.', `FemaleText_loc1`='마법 지구 외곽에 계단이 많은 커다란 건물이 있지. 거기가 마법사들이 숨은 곳일세.', `FemaleText_loc4`='在魔法区的外环区域你能找到一座大型、阶梯式的建筑。法师们都在那里。', `FemaleText_loc5`='在魔法區的外環，你可以找到一棟大型，有階梯的建築。那就是法師的藏身之處。', `FemaleText_loc7`='En el anillo exterior del Barrio de la Magia encontrarás un gran edificio escalonado. Ahí es donde se esconden los magos.' WHERE `ID`=36269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 주민들은 상업 지구에 관을 쌓아 놓고는 거길 여관이라고 부르더군. 우체통은 그 옆에 있네.', `MaleText_loc4`='邮箱在贸易区的棺材铺前面，也有人管那里叫旅馆。', `MaleText_loc5`='郵箱在貿易區的旅社外頭，就是那個活像棺材店的地方。', `MaleText_loc7`='El buzón está en el Barrio del Comercio, junto a ese almacén de ataúdes al que llaman posada.', `FemaleText_loc1`='여기 주민들은 상업 지구에 관을 쌓아 놓고는 거길 여관이라고 부르더군. 우체통은 그 옆에 있네.', `FemaleText_loc4`='邮箱在贸易区的棺材铺前面，也有人管那里叫旅馆。', `FemaleText_loc5`='郵箱在貿易區的旅社外頭，就是那個活像棺材店的地方。', `FemaleText_loc7`='El buzón está en el Barrio del Comercio, junto a ese almacén de ataúdes al que llaman posada.' WHERE `ID`=36270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통? 도시 중앙 상업 지구 위층에 있는 여관으로 가야겠군. 거기에 우체통이 있지.', `MaleText_loc4`='邮箱吗？你可以到城中央上层区域的旅店看看，那里有邮箱。', `MaleText_loc5`='郵箱?你要先到城市中央上層的旅店。郵箱就在那裡。', `MaleText_loc7`='¿Buzón? Debes dirigirte a la posada en el centro del anillo superior de la ciudad. Está justo allí.', `FemaleText_loc1`='우체통? 도시 중앙 상업 지구 위층에 있는 여관으로 가야겠군. 거기에 우체통이 있지.', `FemaleText_loc4`='邮箱吗？你可以到城中央上层区域的旅店看看，那里有邮箱。', `FemaleText_loc5`='郵箱?你要先到城市中央上層的旅店。郵箱就在那裡。', `FemaleText_loc7`='¿Buzón? Debes dirigirte a la posada en el centro del anillo superior de la ciudad. Está justo allí.' WHERE `ID`=36271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광하는 법을 배우고 싶거든, 군사 지구 내곽의 브롬 킬리안과 의논하게.', `MaleText_loc4`='和军事区内环区域的布罗姆·基里安谈一谈，他可以教你如何采矿。', `MaleText_loc5`='如果你想學怎麼採礦，去和軍事區內環的布羅姆·基里安談談。', `MaleText_loc7`='Si quieres aprender minería, habla con Brom Killian en el anillo interior del Barrio de la Guerra.', `FemaleText_loc1`='채광하는 법을 배우고 싶거든, 군사 지구 내곽의 브롬 킬리안과 의논하게.', `FemaleText_loc4`='和军事区内环区域的布罗姆·基里安谈一谈，他可以教你如何采矿。', `FemaleText_loc5`='如果你想學怎麼採礦，去和軍事區內環的布羅姆·基里安談談。', `FemaleText_loc7`='Si quieres aprender minería, habla con Brom Killian en el anillo interior del Barrio de la Guerra.' WHERE `ID`=36272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 광부는 군사 지구 내곽에서 일하지. 이름은 브롬 킬리안이라고 하네.', `MaleText_loc4`='这里的采矿训练师在军事区的内环区域工作。他的名字叫布罗姆·基里安。', `MaleText_loc5`='此地的礦工就在軍事區的內環。他的名字叫做布羅姆·基里安。', `MaleText_loc7`='El minero de aquí trabaja en el Barrio de la Guerra, en el anillo interior. Se llama Brom Killian.', `FemaleText_loc1`='여기 광부는 군사 지구 내곽에서 일하지. 이름은 브롬 킬리안이라고 하네.', `FemaleText_loc4`='这里的采矿训练师在军事区的内环区域工作。他的名字叫布罗姆·基里安。', `FemaleText_loc5`='此地的礦工就在軍事區的內環。他的名字叫做布羅姆·基里安。', `FemaleText_loc7`='El minero de aquí trabaja en el Barrio de la Guerra, en el anillo interior. Se llama Brom Killian.' WHERE `ID`=36273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사를 만나려거든 왕실로 가봐야 할 걸세. 자넬 가르쳐줄 수 있는 엘프가 몇 명 있지.', `MaleText_loc4`='找圣骑士你得去皇家区。那些有几个精灵可以教你。', `MaleText_loc5`='如果你想找個聖騎士，你得要去皇家區。那裡有個精靈能指導你。', `MaleText_loc7`='Si quieres encontrar a un paladín, tendrás que ir al Barrio Real. Allí hay un elfo que te puede instruir.', `FemaleText_loc1`='성기사를 만나려거든 왕실로 가봐야 할 걸세. 자넬 가르쳐줄 수 있는 엘프가 몇 명 있지.', `FemaleText_loc4`='找圣骑士你得去皇家区。那些有几个精灵可以教你。', `FemaleText_loc5`='如果你想找個聖騎士，你得要去皇家區。那裡有個精靈能指導你。', `FemaleText_loc7`='Si quieres encontrar a un paladín, tendrás que ir al Barrio Real. Allí hay un elfo que te puede instruir.' WHERE `ID`=36274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사제들은 군사 지구 외곽에 자리 잡고 있네.', `MaleText_loc4`='牧师们都在军事区的外环区域。', `MaleText_loc5`='牧師們就在軍事區的外環。', `MaleText_loc7`='Los sacerdotes se encuentran en el anillo exterior del Barrio de la Guerra.', `FemaleText_loc1`='사제들은 군사 지구 외곽에 자리 잡고 있네.', `FemaleText_loc4`='牧师们都在军事区的外环区域。', `FemaleText_loc5`='牧師們就在軍事區的外環。', `FemaleText_loc7`='Los sacerdotes se encuentran en el anillo exterior del Barrio de la Guerra.' WHERE `ID`=36275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구로 가보게. 거기서 사제들이 사지가 제대로 붙어 있는지 봐주지.', `MaleText_loc4`='去军事区外环区域看看吧。那里的牧师努力确保没有哪个断掉的肋骨长时间得不到修复。', `MaleText_loc5`='去軍事區吧，牧師們就在那裡的外環。記得確定你沒有斷手少腳的。', `MaleText_loc7`='Dirígete al Barrio de la Guerra. Los sacerdotes están allí, en el anillo exterior, asegurándose de que no queden miembros sueltos durante demasiado tiempo.', `FemaleText_loc1`='군사 지구로 가보게. 거기서 사제들이 사지가 제대로 붙어 있는지 봐주지.', `FemaleText_loc4`='去军事区外环区域看看吧。那里的牧师努力确保没有哪个断掉的肋骨长时间得不到修复。', `FemaleText_loc5`='去軍事區吧，牧師們就在那裡的外環。記得確定你沒有斷手少腳的。', `FemaleText_loc7`='Dirígete al Barrio de la Guerra. Los sacerdotes están allí, en el anillo exterior, asegurándose de que no queden miembros sueltos durante demasiado tiempo.' WHERE `ID`=36276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적들은 도적 지구에 있네. 간단하지? 도적 지구 외곽 쪽에서 찾아보게.', `MaleText_loc4`='盗贼们都呆在盗贼区。就这么简单。你可以在外环区域找到他们。', `MaleText_loc5`='盜賊都在盜賊區，正如其名。你可以在那邊的外環找到他們。', `MaleText_loc7`='Los pícaros están en el Barrio de los Pícaros. Así de simple. Búscalos en el anillo exterior.', `FemaleText_loc1`='도적들은 도적 지구에 있네. 간단하지? 도적 지구 외곽 쪽에서 찾아보게.', `FemaleText_loc4`='盗贼们都呆在盗贼区。就这么简单。你可以在外环区域找到他们。', `FemaleText_loc5`='盜賊都在盜賊區，正如其名。你可以在那邊的外環找到他們。', `FemaleText_loc7`='Los pícaros están en el Barrio de los Pícaros. Así de simple. Búscalos en el anillo exterior.' WHERE `ID`=36277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도적을 만나려거든 도적 지구 외곽으로 가보게.', `MaleText_loc4`='你可以在盗贼区外环区域找到那些潜行者。', `MaleText_loc5`='如果你想找那些盜賊的話，就去盜賊區的外環吧。', `MaleText_loc7`='Ve al anillo exterior del Barrio de los Pícaros si quieres encontrar pícaros.', `FemaleText_loc1`='도적을 만나려거든 도적 지구 외곽으로 가보게.', `FemaleText_loc4`='你可以在盗贼区外环区域找到那些潜行者。', `FemaleText_loc5`='如果你想找那些盜賊的話，就去盜賊區的外環吧。', `FemaleText_loc7`='Ve al anillo exterior del Barrio de los Pícaros si quieres encontrar pícaros.' WHERE `ID`=36278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 무두장이는 킬리안 헤이지라고 하지. 도적 지구 내곽에서 일하네.', `MaleText_loc4`='基里安·哈根是这里的剥皮训练师。他就在盗贼区的内环区域。', `MaleText_loc5`='此地剝皮師的名字叫做基里安·哈根。他的工作地點就在盜賊區的內環。', `MaleText_loc7`='El desollador de aquí se llama Killian Hagey. Trabaja en el Barrio de los Pícaros. En el anillo central.', `FemaleText_loc1`='여기 무두장이는 킬리안 헤이지라고 하지. 도적 지구 내곽에서 일하네.', `FemaleText_loc4`='基里安·哈根是这里的剥皮训练师。他就在盗贼区的内环区域。', `FemaleText_loc5`='此地剝皮師的名字叫做基里安·哈根。他的工作地點就在盜賊區的內環。', `FemaleText_loc7`='El desollador de aquí se llama Killian Hagey. Trabaja en el Barrio de los Pícaros. En el anillo central.' WHERE `ID`=36279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 벗기는 법을 배우고 싶거든 도적 지구로 가보게. 내곽 쪽에 무두장이가 있지.', `MaleText_loc4`='如果你想学习剥皮，就要前往盗贼区。剥皮训练师的铺位就在内环区域。', `MaleText_loc5`='如果你想學如何剝皮，就去盜賊區吧。剝皮師的店就在那邊的內環。', `MaleText_loc7`='Si quieres aprender a desollar cosas, dirígete al Barrio de los Pícaros. El desollador tiene su puesto en el anillo interior.', `FemaleText_loc1`='가죽 벗기는 법을 배우고 싶거든 도적 지구로 가보게. 내곽 쪽에 무두장이가 있지.', `FemaleText_loc4`='我们的剥皮钩子是从基里安·哈根那拿来的，他教过我们如何剥下被杀死的动物的皮。你的皮肤不错。你可以在盗贼区的内圈找到他。', `FemaleText_loc5`='如果你想學如何剝皮，就去盜賊區吧。剝皮師的店就在那邊的內環。', `FemaleText_loc7`='Nosotros tener gancho desollador. Nos dio Killian Hagey que nos enseña a desollar. Tú tener piel bonita. Lo encontrarás en el anillo interior del Barrio de los Pícaros.' WHERE `ID`=36281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드에게 야수를 맡겨도 상관없다면, 상업 지구 위층의 여관에 있는 안야 마울레이와 얘기해 보게.', `MaleText_loc4`='如果你真的想把宠物委托给某个亡灵，那你可以和安雅·玛尔雷谈谈，他就呆在贸易区上层的旅馆里。', `MaleText_loc5`='你要是真的信得過把寵物交給不死生物的話，你可以跟貿易區上層旅店的安雅·瑪爾雷談談。', `MaleText_loc7`='Si realmente confiarías a tus mascotas a algún no-muerto, puedes hablar con Anya Maulray en la posada, en el anillo superior del Barrio del Comercio.', `FemaleText_loc1`='언데드에게 야수를 맡겨도 상관없다면, 상업 지구 위층의 여관에 있는 안야 마울레이와 얘기해 보게.', `FemaleText_loc4`='如果你真的想把宠物委托给某个亡灵，那你可以和安雅·玛尔雷谈谈，他就呆在贸易区上层的旅馆里。', `FemaleText_loc5`='你要是真的信得過把寵物交給不死生物的話，你可以跟貿易區上層旅店的安雅·瑪爾雷談談。', `FemaleText_loc7`='Si realmente confiarías a tus mascotas a algún no-muerto, puedes hablar con Anya Maulray en la posada, en el anillo superior del Barrio del Comercio.' WHERE `ID`=36282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구 위층의 여관 옆에 있는 안야 마울레이를 찾아가게. 나라면 안 그러겠지만, 자네 야수니 뭐.', `MaleText_loc4`='你可以同安雅·玛尔雷谈一谈，他就在贸易区上层的旅店旁边。我并不建议你这样做，不过它们毕竟是你的宠物。', `MaleText_loc5`='你可以跟貿易區上層旅店的安雅·瑪爾雷談談。我並不推薦，但牠們是你的寵物。', `MaleText_loc7`='Puedes hablar con Anya Maulray en la posada, en el anillo superior del Barrio del Comercio. Yo no te lo recomendaría, pero son tus mascotas.', `FemaleText_loc1`='상업 지구 위층의 여관 옆에 있는 안야 마울레이를 찾아가게. 나라면 안 그러겠지만, 자네 야수니 뭐.', `FemaleText_loc4`='你可以同安雅·玛尔雷谈一谈，他就在贸易区上层的旅店旁边。我并不建议你这样做，不过它们毕竟是你的宠物。', `FemaleText_loc5`='你可以跟貿易區上層旅店的安雅·瑪爾雷談談。我並不推薦，但牠們是你的寵物。', `FemaleText_loc7`='Puedes hablar con Anya Maulray en la posada, en el anillo superior del Barrio del Comercio. Yo no te lo recomendaría, pero son tus mascotas.' WHERE `ID`=36283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 재봉사는 조셉 그레고리안이라고 하지. 마법 지구 내곽에 있네.', `MaleText_loc4`='这里的裁缝叫乔瑟夫·格里高利。他就在魔法区的内环区域。', `MaleText_loc5`='本地的裁縫是喬瑟夫·格里高利。他就在魔法區的內環。', `MaleText_loc7`='El sastre de aquí es Josef Gregorian. Se encuentra en el Barrio de la Magia, en el anillo interior.', `FemaleText_loc1`='여기 재봉사는 조셉 그레고리안이라고 하지. 마법 지구 내곽에 있네.', `FemaleText_loc4`='这里的裁缝叫乔瑟夫·格里高利。他就在魔法区的内环区域。', `FemaleText_loc5`='本地的裁縫是喬瑟夫·格里高利。他就在魔法區的內環。', `FemaleText_loc7`='El sastre de aquí es Josef Gregorian. Se encuentra en el Barrio de la Magia, en el anillo interior.' WHERE `ID`=36284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구 내곽을 돌아보게. 거기 재봉사가 있네.', `MaleText_loc4`='先到魔法区，然后朝内环区域走，裁缝店就在那里。', `MaleText_loc5`='前往魔法區的內環，裁縫就在那邊。', `MaleText_loc7`='Ve al Barrio de la Magia y dirígete al anillo interior. El sastre está allí.', `FemaleText_loc1`='마법 지구 내곽을 돌아보게. 거기 재봉사가 있네.', `FemaleText_loc4`='先到魔法区，然后朝内环区域走，裁缝店就在那里。', `FemaleText_loc5`='前往魔法區的內環，裁縫就在那邊。', `FemaleText_loc7`='Ve al Barrio de la Magia y dirígete al anillo interior. El sastre está allí.' WHERE `ID`=36285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사에 대해 내게 묻다니, 간 하나는 크군. 마법 지구 외곽으로 가면 되네. 이제 내 눈앞에서 썩 물러가게.', `MaleText_loc4`='你竟然有胆量问我有关术士的事。到魔法区的外环区域看看吧，现在给我消失。', `MaleText_loc5`='你還真有種來問我術士的事情。去魔法區的外環，然後滾出我的視線範圍。', `MaleText_loc7`='Tienes muchas agallas al preguntarme acerca de los brujos. Ve al anillo exterior del Barrio de la Magia y desaparece de mi vista.', `FemaleText_loc1`='흑마법사에 대해 내게 묻다니, 간 하나는 크군. 마법 지구 외곽으로 가면 되네. 이제 내 눈앞에서 썩 물러가게.', `FemaleText_loc4`='你竟然有胆量问我有关术士的事。到魔法区的外环区域看看吧，现在给我消失。', `FemaleText_loc5`='你還真有種來問我術士的事情。去魔法區的外環，然後滾出我的視線範圍。', `FemaleText_loc7`='Tienes muchas agallas al preguntarme acerca de los brujos. Ve al anillo exterior del Barrio de la Magia y desaparece de mi vista.' WHERE `ID`=36286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지구 주 건물 안에 흑마법사들이 있네. 가서 문제를 일으키지는 않아 줬으면 좋겠군.', `MaleText_loc4`='你可以在魔法区的主建筑区域找到那些术士，我希望告诉你这些不会引起什么麻烦。', `MaleText_loc5`='你會在魔法區的主建築找到術士的蹤影，但最後好別讓我聽見那邊出了任何麻煩。', `MaleText_loc7`='Encontrarás a los brujos en el edificio principal del Barrio de la Magia, pero más vale que no me entere de que esto genera algún problema.', `FemaleText_loc1`='마법 지구 주 건물 안에 흑마법사들이 있네. 가서 문제를 일으키지는 않아 줬으면 좋겠군.', `FemaleText_loc4`='你可以在魔法区的主建筑区域找到那些术士，我希望告诉你这些不会引起什么麻烦。', `FemaleText_loc5`='你會在魔法區的主建築找到術士的蹤影，但最後好別讓我聽見那邊出了任何麻煩。', `FemaleText_loc7`='Encontrarás a los brujos en el edificio principal del Barrio de la Magia, pero más vale que no me entere de que esto genera algún problema.' WHERE `ID`=36287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들은 군사 지구 외곽에서 훈련 중일세.', `MaleText_loc4`='战士都在军事区外环区域进行操练。', `MaleText_loc5`='戰士都在軍事區，在外環的地方練習。', `MaleText_loc7`='Los guerreros están en el Barrio de la Guerra, practicando en el anillo exterior.', `FemaleText_loc1`='전사들은 군사 지구 외곽에서 훈련 중일세.', `FemaleText_loc4`='战士都在军事区外环区域进行操练。', `FemaleText_loc5`='戰士都在軍事區，在外環的地方練習。', `FemaleText_loc7`='Los guerreros están en el Barrio de la Guerra, practicando en el anillo exterior.' WHERE `ID`=36288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구에서 전사들을 찾을 수 있네. 외곽 쪽을 찾아보게.', `MaleText_loc4`='你可以在军事区的外环区域找到那些战士。', `MaleText_loc5`='你可以在軍事區找到那些戰士，就在外環的地方。', `MaleText_loc7`='En el Barrio de la Guerra es donde encontrarás a los guerreros. Dirígete al anillo exterior allí.', `FemaleText_loc1`='군사 지구에서 전사들을 찾을 수 있네. 외곽 쪽을 찾아보게.', `FemaleText_loc4`='你可以在军事区的外环区域找到那些战士。', `FemaleText_loc5`='你可以在軍事區找到那些戰士，就在外環的地方。', `FemaleText_loc7`='En el Barrio de la Guerra es donde encontrarás a los guerreros. Dirígete al anillo exterior allí.' WHERE `ID`=36289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 다루는 법을 알고 싶거든, 군사 지구 내곽에 있는 아키발드에게 가보게.', `MaleText_loc4`='到军事区内环区域找到阿基巴德，他可以教你如何某些使用武器。', `MaleText_loc5`='如果你打算學習如何使用武器，那就去軍事區的內環找阿基巴德。', `MaleText_loc7`='Si quieres aprender a blandir armas, ve a ver a Archibald al anillo interior del Barrio de la Guerra.', `FemaleText_loc1`='무기 다루는 법을 알고 싶거든, 군사 지구 내곽에 있는 아키발드에게 가보게.', `FemaleText_loc4`='到军事区内环区域找到阿基巴德，他可以教你如何某些使用武器。', `FemaleText_loc5`='如果你打算學習如何使用武器，那就去軍事區的內環找阿基巴德。', `FemaleText_loc7`='Si quieres aprender a blandir armas, ve a ver a Archibald al anillo interior del Barrio de la Guerra.' WHERE `ID`=36290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 유용한 걸 배우려는 이를 만나니 기분이 좋군. 군사 지구 내곽에 있는 아키발드에게 가보게.', `MaleText_loc4`='很高兴有人愿意学点儿真正有用的东西。到军事区的内环区域去找阿基巴德吧。', `MaleText_loc5`='真高興看到有人想學點有用的東西。去軍事區的內環找阿基巴德。', `MaleText_loc7`='Me alegra ver que alguien quiere aprender algo útil. Ve a ver a Archibald en el anillo interior del Barrio de la Guerra.', `FemaleText_loc1`='뭔가 유용한 걸 배우려는 이를 만나니 기분이 좋군. 군사 지구 내곽에 있는 아키발드에게 가보게.', `FemaleText_loc4`='很高兴有人愿意学点儿真正有用的东西。到军事区的内环区域去找阿基巴德吧。', `FemaleText_loc5`='真高興看到有人想學點有用的東西。去軍事區的內環找阿基巴德。', `FemaleText_loc7`='Me alegra ver que alguien quiere aprender algo útil. Ve a ver a Archibald en el anillo interior del Barrio de la Guerra.' WHERE `ID`=36291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 벗어나고 싶은 심정 이해하네. 꼭대기까지 올라가 지상으로 나가서, 폐허 북쪽으로 향하게. 거기 있는 두 개의 탑에서 비행선을 탈 수 있지.', `MaleText_loc4`='你想离开这，这我不怪你。先到最顶层，然后朝废墟的北面走。坐上两座塔那的地精飞艇就可以离开了。', `MaleText_loc5`='我不怪你想要離開這裡。走到最上層之後，就在遺跡的北邊。飛艇會從那兩座塔離開。', `MaleText_loc7`='No te culpo por querer salir aquí. Sube y dirígete hacia el norte de las ruinas. Los zepelines salen desde las dos torres de allí.', `FemaleText_loc1`='여길 벗어나고 싶은 심정 이해하네. 꼭대기까지 올라가 지상으로 나가서, 폐허 북쪽으로 향하게. 거기 있는 두 개의 탑에서 비행선을 탈 수 있지.', `FemaleText_loc4`='你想离开这，这我不怪你。先到最顶层，然后朝废墟的北面走。坐上两座塔那的地精飞艇就可以离开了。', `FemaleText_loc5`='我不怪你想要離開這裡。走到最上層之後，就在遺跡的北邊。飛艇會從那兩座塔離開。', `FemaleText_loc7`='No te culpo por querer salir aquí. Sube y dirígete hacia el norte de las ruinas. Los zepelines salen desde las dos torres de allí.' WHERE `ID`=36292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선 탑승장은 언더시티 바로 북쪽에 있네.', `MaleText_loc4`='飞艇塔就在幽暗城的北面。', `MaleText_loc5`='飛艇塔就在幽暗城的北邊。', `MaleText_loc7`='Las torres de zepelín están justo al norte de Entrañas.', `FemaleText_loc1`='비행선 탑승장은 언더시티 바로 북쪽에 있네.', `FemaleText_loc4`='飞艇塔就在幽暗城的北面。', `FemaleText_loc5`='飛艇塔就在幽暗城的北邊。', `FemaleText_loc7`='Las torres de zepelín están justo al norte de Entrañas.' WHERE `ID`=36293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오크가 있는 게 놀라운가? 그럴 것 없네.$b$b우리는 포세이큰을 감시해야만 해. 애초에 주의를 늦추지 않았더라면, 분노의 관문 사건은 없었을지도 모르지.', `MaleText_loc4`='在这看到兽人感到意外吧？用不着这样。$b$b需要有人看着那些被遗忘者。如果从一开始我们就好好盯着，或许天谴之门的事根本就不会发生。', `MaleText_loc5`='很意外在這裡看見一個獸人?別在意。$b$b必須有人看著被遺忘者。如果我們從一開始就提高注意，憤怒之門的事情可能根本不會發生。', `MaleText_loc7`='¿Te sorprende ver a un orco aquí? No es necesario.$B$BLos renegados necesitan vigilancia. Si hubiéramos prestado más atención desde el principio, quizá los acontecimientos de la Puerta de Cólera no hubieran sucedido.', `FemaleText_loc1`='여기 오크가 있는 게 놀라운가? 그럴 것 없네.$b$b우리는 포세이큰을 감시해야만 해. 애초에 주의를 늦추지 않았더라면, 분노의 관문 사건은 없었을지도 모르지.', `FemaleText_loc4`='在这看到兽人感到意外吧？用不着这样。$b$b需要有人看着那些被遗忘者。如果从一开始我们就好好盯着，或许天谴之门的事根本就不会发生。', `FemaleText_loc5`='很意外在這裡看見一個獸人?別在意。$b$b必須有人看著被遺忘者。如果我們從一開始就提高注意，憤怒之門的事情可能根本不會發生。', `FemaleText_loc7`='¿Te sorprende ver a un orco aquí? No es necesario.$B$BLos renegados necesitan vigilancia. Si hubiéramos prestado más atención desde el principio, quizá los acontecimientos de la Puerta de Cólera no hubieran sucedido.' WHERE `ID`=36294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누더기골렘을 찾는 건 아니겠지? 연금술사들을 믿어선 안 되네. 그러니 놈들의 작품이 돌아다니며 경비를 서게 둬서도 안 되지. 우리는 안전을 유지하러 여기 왔네.', `MaleText_loc4`='希望你要找的不是那些憎恶。炼金师没有一个靠得住，他们造出来的那些在大厅里巡逻的东西也一样。真正保卫这里安全的是我们。', `MaleText_loc5`='希望你不是在找那些憎惡體。藥劑師無法信任，這也表示不能任由他們的小小造物四處遊蕩。我們必須要確保安全。', `MaleText_loc7`='Espero que no estés buscando a esas abominaciones. No se puede confiar en los boticarios y eso incluye a sus pequeños ensamblajes que patrullan los pasillos. Estamos aquí para mantener esto a salvo.', `FemaleText_loc1`='누더기골렘을 찾는 건 아니겠지? 연금술사들은 믿을 수가 없네. 그들의 작품이 돌아다니며 경비를 서는 것도 마찬가지고. 우리는 안전을 유지하러 여기 왔네.', `FemaleText_loc4`='希望你要找的不是那些憎恶。炼金师没有一个靠得住，他们造出来的那些在大厅里巡逻的东西也一样。真正保卫这里安全的是我们。', `FemaleText_loc5`='希望你不是在找那些憎惡體。藥劑師無法信任，這也表示不能任由他們的小小造物四處遊蕩。我們必須要確保安全。', `FemaleText_loc7`='Espero que no estés buscando a esas abominaciones. No se puede confiar en los boticarios y eso incluye a sus pequeños ensamblajes que patrullan los pasillos. Estamos aquí para mantener esto a salvo.' WHERE `ID`=36295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르. 여기선 주의를 끄는 행동은 자제하게. 호드의 일원이 되길 원한다면, 이 언데드 녀석들은 항상 우리가 지켜보고 있다는 걸 마음에 새겨야 할 게야.', `MaleText_loc4`='Lok''tar。不要在这里做出任何可疑的行为。如果那些亡灵打算加入部落，他们就得接受我们的监视。', `MaleText_loc5`='為了部落。別在這裡做什麼引人懷疑的事情。如果這些不死生物是部落的一份子，在我們的監視之下他們得更加注意自己的行為。', `MaleText_loc7`='Lok''tar. No intentes nada sospechoso aquí. Si estos no-muertos van a ser parte de la Horda, tendrán que comportarse bajo nuestra vigilancia.', `FemaleText_loc1`='록타르. 여기선 주의를 끄는 행동은 자제하게. 호드의 일원이 되길 원한다면, 이 언데드 녀석들은 항상 우리가 지켜보고 있다는 걸 마음에 새겨야 할 게야.', `FemaleText_loc4`='Lok''tar。不要在这里做出任何可疑的行为。如果那些亡灵打算加入部落，他们就得接受我们的监视。', `FemaleText_loc5`='為了部落。別在這裡做什麼引人懷疑的事情。如果這些不死生物是部落的一份子，在我們的監視之下他們得更加注意自己的行為。', `FemaleText_loc7`='Lok''tar. No intentes nada sospechoso aquí. Si estos no-muertos van a ser parte de la Horda, tendrán que comportarse bajo nuestra vigilancia.' WHERE `ID`=36296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지, 뼈다귀 씨? 누군가 딴 사람을 찾고 있나? 여기서 질문에 대답해 줄 이라곤 나뿐이니, 알고 싶은 게 있거든 빨리 끝내게.', `MaleText_loc4`='怎么了？骨头堆。在找人吗？这里只有我，要买东西就快点儿。', `MaleText_loc5`='這是不對的，皮包骨?找別人嗎?現在你只能找我了，所以如果你想要點什麼，快點說。', `MaleText_loc7`='¿Qué ocurre, saco de huesos? ¿Buscabas a otra persona? Yo soy lo único que tienes, así que si quieres algo, que sea deprisa.', `FemaleText_loc1`='무슨 일이지, 뼈다귀 씨? 누군가 딴 사람을 찾고 있나? 여기서 질문에 대답해 줄 이라곤 나뿐이니, 알고 싶은 게 있거든 빨리 끝내게.', `FemaleText_loc4`='怎么了？骨头堆。在找人吗？这里只有我，要买东西就快点儿。', `FemaleText_loc5`='這是不對的，皮包骨?找別人嗎?現在你只能找我了，所以如果你想要點什麼，快點說。', `FemaleText_loc7`='¿Qué ocurre, saco de huesos? ¿Buscabas a otra persona? Yo soy lo único que tienes, así que si quieres algo, que sea deprisa.' WHERE `ID`=36297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 말이 있거든 빨리 하게, $r.', `MaleText_loc4`='速度要快，$r。', `MaleText_loc5`='快一點，$r。', `MaleText_loc7`='Date prisa, $r.' WHERE `ID`=36298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지켜보고 있단 걸 명심하시오, 파라넬.', `MaleText_loc4`='我会盯着你的，法拉尼尔。', `MaleText_loc5`='我會盯著你，法拉尼爾。', `MaleText_loc7`='Tengo el ojo puesto en ti, Faranell.' WHERE `ID`=36299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 지켜 주는 누더기골렘은 이제 없어. 비밀스러운 수작도, 어둠 속에서 책략을 꾸미는 것도 끝이야.', `MaleText_loc4`='没有憎恶保护你。没有秘密。没有私下密谋。', `MaleText_loc5`='沒有憎惡體保護你。沒有秘密。沒有暗處的陰謀。', `MaleText_loc7`='Sin abominaciones que te protejan. Sin secretismos. Sin conspirar en la oscuridad.' WHERE `ID`=36300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 허락 없이 손끝 하나라도 까딱하면, 이 연구실을 폐쇄하겠소. 강제로.', `MaleText_loc4`='这里完全不欢迎随地吐痰的人。', `MaleText_loc5`='要是未經我的允許，你再繼續胡說八道的話，我就要強制關閉這個地方。', `MaleText_loc7`='Si escupes sin mi permiso este lugar quedará cerrado. Por la fuerza.' WHERE `ID`=36301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 보장하오, 감독관이여. 왕립 연금술 학회는 많은 이의 목숨을 앗은 그 비극적인 사태에 대해 진심으로 보상하고 싶어하오.', `MaleText_loc4`='我向您保证，监工，皇家药剂师协会愿意为这场导致了大量死亡的悲剧事故做出补偿。', `MaleText_loc5`='我向你保證，監督者，皇家藥劑師學會誠摯地希望能彌補那些因為悲劇性錯誤指示所造成的生命損失。', `MaleText_loc7`='Te aseguro, supervisor, que la Sociedad Real de Boticarios desea fervientemente compensar la trágica equivocación que acabó con tantas vidas.' WHERE `ID`=36302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제를 일으킬 생각은 전혀 없소. 단지 평화롭게 연구를 계속하고 싶을 뿐이오.', `MaleText_loc4`='我们不会给你惹麻烦的。我们只想安安静静地继续我们的研究。', `MaleText_loc5`='我們絕對不會給您添麻煩的。我們只想要和平地繼續我們的研究。', `MaleText_loc7`='No te causaremos problemas. Solo queremos continuar con nuestra investigación en paz.' WHERE `ID`=36303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 보면 알겠지.', `MaleText_loc4`='我们会搞清楚的。', `MaleText_loc5`='我們等著瞧。', `MaleText_loc7`='Ya lo veremos.' WHERE `ID`=36304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 썩어 문드러진 놈이 입 닥치게 해라!', `MaleText_loc4`='让那个死脑筋把嘴闭上！', `MaleText_loc5`='叫那些腐爛的傻瓜去關掉他的陷阱!', `MaleText_loc7`='¡Haz que ese loco podrido cierre la bocaza!' WHERE `ID`=36305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중얼거리지 말고 닥쳐! 이 얼간아!', `MaleText_loc4`='闭嘴，叽里呱啦的蠢货！', `MaleText_loc5`='關你個頭，你這語無倫次的蠢蛋!', `MaleText_loc7`='¡Cierra la boca, estúpido farfullador!', `FemaleText_loc1`='중얼거리지 말고 닥쳐! 이 얼간아!', `FemaleText_loc4`='闭嘴，叽里呱啦的蠢货！', `FemaleText_loc5`='關你個頭，你這語無倫次的蠢蛋!', `FemaleText_loc7`='¡Cierra la boca, estúpido farfullador!' WHERE `ID`=36306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 관문에선 아주 의기양양했겠지, 안 그런가? 하지만 좋은 시절은 다 갔네. 우리가 와 있으니 쓸데없는 짓은 꿈도 꾸지 말라고.', `MaleText_loc4`='我敢说你们这些无赖一定觉得自己在天谴之门干得很漂亮，对吧？游戏结束了。我们来就是要阻止你们的一切行为。', `MaleText_loc5`='我賭你們這些爛貨認為自己在憤怒之門表現得很聰明，對不對?玩樂時間已經結束啦。我們在這裡就是要確保你們什麼也不做。', `MaleText_loc7`='Apuesto a que ustedes, podridos, pensaron que fueron muy listos en la Puerta de Cólera, ¿verdad? Se acabaron los juegos. Estamos aquí para asegurarnos de que no intentan nada.', `FemaleText_loc1`='분노의 관문에선 아주 의기양양했겠지, 안 그런가? 하지만 좋은 시절은 다 갔네. 우리가 와 있으니 쓸데없는 짓은 꿈도 꾸지 말라고.', `FemaleText_loc4`='我敢说你们这些无赖一定觉得自己在天谴之门干得很漂亮，对吧？游戏结束了。我们来就是要阻止你们的一切行为。', `FemaleText_loc5`='我賭你們這些爛貨認為自己在憤怒之門表現得很聰明，對不對?玩樂時間已經結束啦。我們在這裡就是要確保你們什麼也不做。', `FemaleText_loc7`='Apuesto a que ustedes, podridos, pensaron que fueron muy listos en la Puerta de Cólera, ¿verdad? Se acabaron los juegos. Estamos aquí para asegurarnos de que no intentan nada.' WHERE `ID`=36307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문에 대답해 주는 건 내 의무지만, 그 일을 좋아할 의무 따윈 없네. 우리가 너희 종족을 지켜보고 있다는 걸 잊지 말라고.', `MaleText_loc4`='我会告诉你都该知道些什么，但这并不表示我有多么愿意。我们一直在监视着你和你的同类。', `MaleText_loc5`='我會告訴你需要知道的事，但這並不代表我喜歡這麼做。我們得要看緊你和你的同伴。', `MaleText_loc7`='Te diré lo que necesites saber, pero no tiene por qué gustarme. Os estamos vigilando a ti y a los tuyos.', `FemaleText_loc1`='질문에 대답해 주는 건 내 의무지만, 그 일을 좋아할 의무 따윈 없네. 우리가 너희 종족을 지켜보고 있다는 걸 잊지 말라고.', `FemaleText_loc4`='我会告诉你都该知道些什么，但这并不表示我有多么愿意。我们一直在监视着你和你的同类。', `FemaleText_loc5`='我會告訴你需要知道的事，但這並不代表我喜歡這麼做。我們得要看緊你和你的同伴。', `FemaleText_loc7`='Te diré lo que necesites saber, pero no tiene por qué gustarme. Os estamos vigilando a ti y a los tuyos.' WHERE `ID`=36308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 냄새 나는 구덩이에서 뱀 같은 놈들한테 둘러싸여 있는 것도 다 임무를 위해서요.$b$b퓨트리스가 분노의 관문에서 끔찍한 짓을 벌인 이래, 대족장님께서는 이 족속을 믿지 않으시오. 놈들을 내팽개쳐 버릴 수도 있을 정도지. 그래서 우리가 여기 있는 거요. 이제 연금술사들은 내 허락 없인 아무것도 할 수 없소.', `MaleText_loc4`='坑里臭气熏天，还有一群蛇围着我。不过我来这是有事要做的。$b$b自从普特雷斯在天谴之门上演了一出好戏，酋长便不再信任那些人，而是离他们远远的。这就是为什么我们会在这里。那些药剂师离了我什么都做不了。', `MaleText_loc5`='這個鬼地方臭斃了，而且被一堆毒蛇包圍著，但我必須完成我的工作。$b$b自從普崔司在憤怒之門搞出那些花樣之後，大酋長根本就信不過這些人。這也是為什麼我們在這裡。那些藥劑師做什麼事情都得要經過我的同意。', `MaleText_loc7`='Este pozo apesta y estoy rodeado de serpientes, pero he venido a trabajar.$B$BDesde que Putress montó su numerito en la Puerta de Cólera, el Jefe de Guerra no se fía un pelo de esta gente. Por eso estamos aquí. Los boticarios no pueden hacer nada sin mí.' WHERE `ID`=36309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아!!!! 이 안에서는 안 보여!', `MaleText_loc4`='啊！！！！我在这儿看不到！！！！', `MaleText_loc5`='嘎!!!!我在這裡看不到!!!!', `MaleText_loc7`='¡AHHH! NO VEO AQUÍ.' WHERE `ID`=36310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화약 냄새 나는 통이다...', `MaleText_loc4`='桶子闻起来像火药……', `MaleText_loc5`='桶子聞起來像火藥...', `MaleText_loc7`='Barril oler a pólvora...' WHERE `ID`=36311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 기분인데...', `MaleText_loc4`='这不太好…', `MaleText_loc5`='這不太妙...', `MaleText_loc7`='Esto no bueno…' WHERE `ID`=36312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어... 이거 꽤 아프겠다...', `MaleText_loc4`='阿噢……这会伤到我……', `MaleText_loc5`='喔噢...這會很痛...', `MaleText_loc7`='¡Uy, me va dole''!' WHERE `ID`=36313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느낌이 안 좋다...', `MaleText_loc4`='我感觉不好…', `MaleText_loc5`='我感覺不妙...', `MaleText_loc7`='No me ''usta na''…' WHERE `ID`=36314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어... 이리 와! 없애버릴 거야!', `MaleText_loc4`='滚回去！我打烂你！', `MaleText_loc5`='快回來這!我打爛你!', `MaleText_loc7`='¡Vuelve aquí! ¡Que te aplasto!' WHERE `ID`=36315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 내가 제공하는 서비스를 사용하려면 자격증이 필요하오.', `MaleText_loc4`='[DND] 要使用我的服务，你必须先取得对应的许可。', `MaleText_loc5`='[DND]你需要適當的證明才能使用我的服務。', `MaleText_loc7`='[DND] To use my services you must have the proper certification.', `FemaleText_loc1`='[DND] 내가 제공하는 서비스를 사용하려면 자격증이 필요하오.', `FemaleText_loc4`='[DND] 要使用我的服务，你必须先取得对应的许可。', `FemaleText_loc5`='[DND]你需要適當的證明才能使用我的服務。', `FemaleText_loc7`='[DND] To use my services you must have the proper certification.' WHERE `ID`=36316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 전 은행 이용권이 있습니다.', `MaleText_loc4`='[DND] 我已经取得了银行的使用许可。', `MaleText_loc5`='[DND]我有使用銀行的適當證明。', `MaleText_loc7`='[DND] I have the proper certification to use the bank.', `FemaleText_loc1`='[DND] 전 은행 이용권이 있어요.', `FemaleText_loc4`='[DND] 我已经取得了银行的使用许可。', `FemaleText_loc5`='[DND]我有使用銀行的適當證明。', `FemaleText_loc7`='[DND] I have the proper certification to use the bank.' WHERE `ID`=36317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 은행 이용을 위한 서류를 작성하시고, 요금을 지불하셨습니까?', `MaleText_loc4`='[DND] 使用银行所需的许可和费用你都办好了吗？', `MaleText_loc5`='[DND]文件填寫正確嗎?使用銀行的費用付過了嗎?', `MaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?', `FemaleText_loc1`='[DND] 은행 이용을 위한 서류를 작성하시고, 요금을 지불하셨습니까?', `FemaleText_loc4`='[DND] 使用银行所需的许可和费用你都办好了吗？', `FemaleText_loc5`='[DND]文件填寫正確嗎?使用銀行的費用付過了嗎?', `FemaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?' WHERE `ID`=36318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스 시의 주민들을 지켜내지 못했었소. 그렇지만 아무래도 운명이 나에게 두 번째 기회를 준 것 같소, $n. 이제는 절대 실패하지 않을 것이오!', `MaleText_loc4`='我没有能在吉尔尼斯城保护我的人民。但命运似乎是要给我第二次机会，$n。我不会再失败了！', `MaleText_loc5`='我在吉爾尼斯城沒能保護好我的人民。看來命運給了我第二次機會，$n。我這次不會再失敗了!', `MaleText_loc7`='Fracasé en mi intento de proteger la Ciudad de Gilneas y a mi pueblo. Pero parece que el destino me ha dado una segunda oportunidad, $n. ¡No fracasaré de nuevo!' WHERE `ID`=36319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 경매장 이용을 위한 서류를 작성하시고, 요금을 지불하셨습니까?', `MaleText_loc4`='[DND] 使用拍卖行所需的许可和费用你都办好了吗？', `MaleText_loc5`='[DND]文件填寫正確嗎?使用拍賣場的費用付過了嗎?', `MaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?', `FemaleText_loc1`='[DND] 경매장 이용을 위한 서류를 작성하시고, 요금을 지불하셨습니까?', `FemaleText_loc4`='[DND] 使用拍卖行所需的许可和费用你都办好了吗？', `FemaleText_loc5`='[DND]文件填寫正確嗎?使用拍賣場的費用付過了嗎?', `FemaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?' WHERE `ID`=36320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 나타난 이... 손님들이 우리 일을 제한하고 있는 건 사실이나, 수많은 목숨을 앗은 사건이 있었으니 의심이 많아지는 것도 당연하오. 퓨트리스는 예외적인 경우라는 걸 시간이 지나면 그들도 알아줄 거요. 그러면 우리가 조용히 연구를 계속하게 해주겠지.', `MaleText_loc4`='我们的新…客人对我们的工作的确有些拖累，不过在从事种族灭绝工作中保持机警是没错的。也许，在适当的时候他们会认识到普特雷斯就是个倒霉的异类，并且允许我们安安稳稳地继续我们的工作。', `MaleText_loc5`='我們的新客人確實...在某種程度上限制了我們的工作，但在跟屠殺事件有關時，謹慎是必然的。或許一段時間之後，他們會相信普崔斯是個不幸的特例，並讓我們平靜地繼續工作。', `MaleText_loc7`='Es verdad que nuestros nuevos... invitados están limitando un poco nuestro trabajo, pero es normal no fiarse cuando ha habido un intento de genocidio. Quizá con el tiempo se convenzan de que Putress fue una desafortunada anomalía y nos permitan continuar con nuestro trabajo en paz.' WHERE `ID`=36321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 은행 이용권이 있습니다.', `MaleText_loc4`='[DND] 我已经取得了银行的使用许可。', `MaleText_loc5`='我有使用銀行的適當證明。', `MaleText_loc7`='Tengo la certificación adecuada para usar el banco.', `FemaleText_loc1`='전 은행 이용권이 있어요.', `FemaleText_loc4`='[DND] 我已经取得了银行的使用许可。', `FemaleText_loc5`='我有使用銀行的適當證明。', `FemaleText_loc7`='Tengo la certificación adecuada para usar el banco.' WHERE `ID`=36322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마비 독에 감염되었습니다!', `MaleText_loc4`='你已经被麻痹毒素感染了！', `MaleText_loc5`='你受到痲痺劇毒的感染!', `MaleText_loc7`='¡Te han infectado con una toxina paralizadora!', `FemaleText_loc1`='마비 독에 감염되었습니다!', `FemaleText_loc4`='你已经被麻痹毒素感染了！', `FemaleText_loc5`='你受到痲痺劇毒的感染!', `FemaleText_loc7`='¡Te han infectado con una toxina paralizadora!' WHERE `ID`=36323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해치지 마세요! 여동생을 찾고 있었어요! 애쉴리가 이 집 안에 있었던 것 같단 말이에요!', `MaleText_loc4`='不要伤害我！我只是在寻找我的姐妹！我想阿什莉就在这幢房子里！', `MaleText_loc5`='別傷害我!我只是在找我的姐妹!我想艾西莉在那房子裡面!', `MaleText_loc7`='¡No me hagas daño! ¡Tan solo estaba buscando a mis hermanas! ¡Creo que Ashley está dentro de esa casa!' WHERE `ID`=36324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 무서워요! 엄마가 보고 싶어요!', `FemaleText_loc4`='你真可怕！我只想要妈妈！', `FemaleText_loc5`='你好恐怖!我要媽媽!', `FemaleText_loc7`='¡Me das miedo! ¡Yo quiero a mi mamá!' WHERE `ID`=36325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='착한 늑대인간이 맞죠? 혹시 밖의 헛간에서 신시아를 보셨어요?', `FemaleText_loc4`='你是那种好狼人吗，$g先生:女士;？你有没有见到藏在外面棚屋里的辛西娅？', `FemaleText_loc5`='你是其中一個好狼人嗎，$g先生:女士;?你有看到辛西雅躲在外面的小屋中嗎?', `FemaleText_loc7`='¿Formas parte de los huargen buenos, $gseñor:señora;? ¿Has visto a Cynthia escondida en esas cabañas de ahí fuera?' WHERE `ID`=36326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅급 보석 도안을 좀 살펴볼 수 있을까요?', `MaleText_loc4`='我能看看你的史诗宝石配方么？', `MaleText_loc5`='我能看看你的史詩寶石設計圖嗎?', `MaleText_loc7`='¿Puedo ver tus recetas de gemas épicas?', `FemaleText_loc1`='영웅급 보석 도안을 좀 살펴볼 수 있을까요?', `FemaleText_loc4`='我能看看你的史诗宝石配方么？', `FemaleText_loc5`='我能看看你的史詩寶石設計圖嗎?', `FemaleText_loc7`='¿Puedo ver tus recetas de gemas épicas?' WHERE `ID`=36327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니가 옆집 지하실에서 기다리고 있단다. 어서 그곳으로 가거라!', `MaleText_loc4`='你的妈妈就在旁边那道门后的地下室里。现在就去找她吧！', `MaleText_loc5`='你媽在隔壁的地下室裡。快去她那吧!', `MaleText_loc7`='Tu madre está en el sótano de al lado. ¡Ve con ella ahora!', `FemaleText_loc1`='어머니가 옆집 지하실에서 기다리고 있단다. 어서 그곳으로 가렴!', `FemaleText_loc4`='你的妈妈就在旁边那道门后的地下室里。现在就去找她吧！', `FemaleText_loc5`='你媽在隔壁的地下室裡。快去她那吧!', `FemaleText_loc7`='Tu madre está en el sótano de al lado. ¡Ve con ella ahora!' WHERE `ID`=36328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 안전하지 않아. 알렌의 지하실로 가거라.', `MaleText_loc4`='这里不安全，到艾伦家的地下室去。', `MaleText_loc5`='這裡並不安全。快躲到艾倫的地窖去。', `MaleText_loc7`='Este lugar no es seguro. Ve al sótano de Allen.', `FemaleText_loc1`='이곳은 안전하지 않단다. 알렌의 지하실로 가렴.', `FemaleText_loc4`='这里不安全，到艾伦家的地下室去。', `FemaleText_loc5`='這裡並不安全。快躲到艾倫的地窖去。', `FemaleText_loc7`='Este lugar no es seguro. Ve al sótano de Allen.' WHERE `ID`=36329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가, $c? 이제 악마들이 물러갔으니 처리해야 할 일이 많네. 누군가는 사무 업무를 돌보며 퓨트리스같은 작자가 다시 나타나지 않도록 해야 하지.$b$b내 운은 왜 이런지.', `MaleText_loc4`='这是什么，$c？恶魔不在了，这里有很多东西我要看。总得有人来整理这些文书，确保普特雷斯的事不再发生。$b$b我真是走运。', `MaleText_loc5`='那是什麼，$c?自從惡魔走了之後我有一大堆東西給看。有人弄亂了公文作業，而我們得確保不會再出現像普崔斯那樣的問題。$b$b祝我好運吧。', `MaleText_loc7`='¿Qué ocurre, $c? Tengo muchas cosas que hacer por aquí ahora que se ha marchado ese demonio. Alguien tiene que encargarse del papeleo y asegurarse de que no vemos otro episodio como el de Putress.$b$bQué suerte la mía.' WHERE `ID`=36330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옆집 지하실에 있는 다른 사람들에게로 가거라! 어서 서둘러!', `MaleText_loc4`='去旁边那道门后的地下室里去找其他人，和他们待在一起。快！', `MaleText_loc5`='到隔壁的地下室加入大家。快!', `MaleText_loc7`='Reúnete con los demás en el sótano de al lado. ¡Rápido!', `FemaleText_loc1`='옆집 지하실에 있는 다른 사람들에게로 가렴! 어서 서둘러!', `FemaleText_loc4`='去旁边那道门后的地下室里去找其他人，和他们待在一起。快！', `FemaleText_loc5`='到隔壁的地下室加入大家。快!', `FemaleText_loc7`='Reúnete con los demás en el sótano de al lado. ¡Rápido!' WHERE `ID`=36331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 주위를 둘러보세요!$b$b모든 것이 아름답지 않나요?', `FemaleText_loc4`='看看你周围，$c！$b$b这里难道不是非常美丽吗？', `FemaleText_loc5`='看看你的四周，$c!$b$b是不是很漂亮啊?', `FemaleText_loc7`='¡Mira a tu alrededor, $c!$b$b¿Acaso no es hermoso?' WHERE `ID`=36332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 네가 맞지, 그렇지? 눈빛이 아주 익숙해.', `FemaleText_loc4`='真的是你？我还记得这双眼睛。', `FemaleText_loc5`='那真的是你，是你對吧?我認得那雙眼睛。', `FemaleText_loc7`='Eres tú, ¿verdad? Recuerdo esos ojos.' WHERE `ID`=36333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $g젊은 친구:아가씨;?', `MaleText_loc4`='你还好吗，$g小伙子:姑娘;？', `MaleText_loc5`='你好嗎，$g小伙子:小姑娘;?', `MaleText_loc7`='¿Qué tal te va, $gmuchacho:muchacha;?' WHERE `ID`=36334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장난하지 마세요! $n|1이;가; 우리들을 위해 한 일들을 다 잊었단 말인가요? 그분이 남아있었단 말이에요... 바로 우리를 위해서요!', `FemaleText_loc4`='你不会是认真的吧！难道你忘记了$n为我们做的一切？$g他:她;留下来……都是为了我们！', `FemaleText_loc5`='你是在開玩笑嗎!你忘了$n為我們所做的一切嗎?$g他:她;留下來...是為了我們!', `FemaleText_loc7`='¡No hablas en serio! ¿Es que has olvidado todo lo que $n ha hecho por nosotros? $gÉl:Ella; se ha quedado atrás... ¡por nosotros!' WHERE `ID`=36335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하게, 크레난. 이제 이자를 처리할 때야. 규칙대로 하자고.', `MaleText_loc4`='放弃吧，克雷南。该处决它了。这是“既定程序”。', `MaleText_loc5`='放棄吧，卡瑞南。該殺掉這一隻了。這是規矩。', `MaleText_loc7`='Ríndete, Krennan. Hora de sacrificarlo. Es protocolo.' WHERE `ID`=36336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미사용', `MaleText_loc4`='DEPRECATED', `MaleText_loc5`='DEPRECATED', `MaleText_loc7`='DEPRECATED' WHERE `ID`=36337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미사용', `MaleText_loc4`='我必须再试一次！这么长时间以来，我还没有对付过任何真正陷入狂野的家伙。只要有足够的时间，我一定能发现正确的配方。', `MaleText_loc5`='DEPRECATED', `MaleText_loc7`='DEPRECATED' WHERE `ID`=36338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미사용', `MaleText_loc4`='你疯了吗，高弗雷？协议？！', `MaleText_loc5`='DEPRECATED', `MaleText_loc7`='DEPRECATED' WHERE `ID`=36339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보게, 고드프리. 우리를 살리려고 길니아스 시에서 사투를 벌인 사람들은, 규칙을 따라 그리한 건가?', `MaleText_loc4`='告诉我，高弗雷。那些留在吉尔尼斯城中，让我们能够活下来的人。他们的死也是“既定程序”？', `MaleText_loc5`='告訴我，高佛雷。那些留在吉爾尼斯城裡斷後的人。他們也是照規矩來嗎?', `MaleText_loc7`='Dime, Godfrey. Los que se quedaron en Ciudad Gilneas por nosotros. ¿Seguían el protocolo?' WHERE `ID`=36340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그렇게 생각하지 않네. 물약을 이리 주게, 크레난... 그리고 투여량을 두 배로 늘리게.', `MaleText_loc4`='我可不这样想。把那个药剂给我，克雷南……我要双倍剂量。', `MaleText_loc5`='我不這麼認為。現在把藥水給我，卡瑞南...然後把劑量加倍。', `MaleText_loc7`='Me pareció que no. Dame esa poción, Krennan... y duplica la dosis.' WHERE `ID`=36341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='DEPRECATED.', `MaleText_loc4`='真的是你？我会尽量帮助你。', `MaleText_loc5`='DEPRECATED.', `MaleText_loc7`='DEPRECATED.' WHERE `ID`=36342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담하지 마십시오! $n|1이;가; 우리를 위해 한 일을 다 잊은 겁니까?', `MaleText_loc4`='你不会是认真的吧！难道你忘记了$n为我们做的一切？', `MaleText_loc5`='你在開玩笑嗎?你忘了$n為我們所做的一切了嗎?', `MaleText_loc7`='¡No hablas en serio! ¿Es que has olvidado todo lo que $n ha hecho por nosotros?' WHERE `ID`=36343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 당신을 포기하지 않을 겁니다. 저주를 완전히 풀 방법은 없어도 증상을 완화시킬 순 있습니다. 제정신을 찾으실 거예요.', `MaleText_loc4`='我不会放弃你。虽然我还不能治愈诅咒，但……我有方法能够让你重获理智。', `MaleText_loc5`='我不會放棄你的。我現在還找不到解除詛咒的方法...但一定會有的。你會好起來的。', `MaleText_loc7`='No te abandonaré. Aún no tengo una cura para la Maldición... pero hay tratamientos. Recuperarás el control.' WHERE `ID`=36344;
