UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타론토 보쉬!', `MaleText_loc4`='Taronto bosch！', `MaleText_loc5`='它倫脫播須!', `MaleText_loc7`='¡Taronto bosch!' WHERE `ID`=36348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음케이, 음네 타 우르!', `MaleText_loc4`='Mkay, m''ne ta oor！', `MaleText_loc5`='米課，迷逆它烏兒!', `MaleText_loc7`='¡Mkay, m''ne ta oor!' WHERE `ID`=36349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<발 디딘 땅이 흔들리고 귀가 아플 정도로 깊고 우렁찬 목소리로 말하는 고르문간>$B$B안녕, 말랑한 친구.$B$B너흰 항상 가만있질 못하고 이리저리 뛰어다니는군. 이리 와서 잠깐 쉬지그래.', `MaleText_loc4`='<格蒙刚的声音发出隆隆的回音，让你感到耳鼓震痛，脚下的地面也在一阵阵颤抖。>$B$B你好，小软人。$B$B你们总是喜欢四处乱窜。来，和我休息一会儿吧。', `MaleText_loc5`='<戈穆恩甘的聲音轟隆轟隆的發了出來，讓你的雙耳感到刺痛，並且在你腳下的土地迴響。>$B$B你好，弱小的人。$B$B你們這個種族喜歡竄進竄出，跑來跑去，永遠都不知道停。跟我一起休息一下。', `MaleText_loc7`='<La voz de Gormungan retumba en las profundidades, daña tus oídos y reverbera en el suelo bajo tus pies.>$B$BHola, blandengue.$B$BTu gente siempre tiene prisa, corre de acá para allá y nunca se detiene. Descansa conmigo un rato.' WHERE `ID`=36350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹을 것을 좀 가져왔어요.', `MaleText_loc4`='我给你带来些吃的。', `MaleText_loc5`='我帶了點東西給你吃。', `MaleText_loc7`='Te he traído algo de comer.', `FemaleText_loc1`='먹을 것을 좀 가져왔어요.', `FemaleText_loc4`='我给你带来些吃的。', `FemaleText_loc5`='我帶了點東西給你吃。', `FemaleText_loc7`='Te he traído algo de comer.' WHERE `ID`=36351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하 하룸! 먹을 것? 우린 부드러운 건 몸에 나빠서 먹지 않아, 친구. 바위와 돌과 대지를 먹지. 아삭거리는 뼈다귀는 가끔 양념으로 맛있게 먹지만 말이야.$B$B<거대한 한쪽 손으로 바위를 들어 올려 당신이 가져온 시체를 내리치고 기쁜 듯이 우르렁대는 고르문간.>', `MaleText_loc4`='哈——啊哈！食物？我们可不吃这种有汁水的东西，朋友，除非他们来伤害我们。我们吃的是岩石、石块和沙砾。不过有时候我也觉得嚼嚼小骨头是一种不错的调剂。$B$B<格蒙刚用一只巨大的手举起一块巨石。将你带来的尸体摁在上面，就好象在蛋糕上放一块水果。然后在一阵宏亮的“嘎吱”声中，他把那块石头嚼碎，咽下了肚。>', `MaleText_loc5`='哈啊啊!嗯?食物?我們不吃壓扁的小東西，除非他們惹毛了我們。我們吃的是石頭、岩石和土地。嗯...雖然我有時候覺得骨頭脆脆的口感是不錯的佐料。$B$B<戈穆恩甘舉起了一塊巨礫，用他巨大的手將你給他的屍體砸在巨礫上，就像是把糖霜塗在蛋糕上一樣。他嘎吱嘎吱地嚼著他的點心，發出了高興的聲音。>', `MaleText_loc7`='¡Ja... jarrrrum! ¿Comida? ¿Nosotros no comemos debiluchos, camarada, a no ser que nos ofendan, claro. Comemos rocas, piedras y tierra. Aunque a veces el crujido de los huesos les da un toque delicioso.$B$B<Gormungan levanta una roca y, con una mano gigantesca, aplasta en ella los cadáveres que le has traído como quien echa azúcar glaseado encima del bizcocho. Después saborea su manjar, feliz y con gusto.>' WHERE `ID`=36352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤리트에 대해 뭔가 알고 있는 것이 있습니까?', `MaleText_loc4`='你知道艾萨莱特水晶的情况吗？', `MaleText_loc5`='你知道任何與艾薩拉水晶有關的事嗎?', `MaleText_loc7`='¿Sabes algo sobre la azsharita?', `FemaleText_loc1`='아즈샤리트에 대해 뭔가 알고 있는 것이 있습니까?', `FemaleText_loc4`='你知道艾萨莱特水晶的情况吗？', `FemaleText_loc5`='你知道任何與艾薩拉水晶有關的事嗎?', `FemaleText_loc7`='¿Sabes algo sobre la azsharita?' WHERE `ID`=36353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤리트? 너희 말랑한 친구들은 뭐든지 새 이름을 붙여대는군. 아즈샤리트가 대체 뭐지?', `MaleText_loc4`='艾萨莱特水晶？你们这些软弱的家伙倒是喜欢乱起新名字。这个“艾萨莱特水晶”又是什么？', `MaleText_loc5`='艾薩拉水晶?你們這些軟綿綿的傢伙就愛取新名字。這個「艾薩拉水晶」是什麼?', `MaleText_loc7`='¿Azsharita? Ustedes, blanditos, tienen nombres para todo. ¿Qué es "azsharita"?' WHERE `ID`=36354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅 위에 보이는 푸르스름한 수정 덩어리 말입니다.', `MaleText_loc4`='就是我们在这里找到的这堆蓝水晶。', `MaleText_loc5`='我們在地面上找到的那堆藍色水晶。', `MaleText_loc7`='Esos montones de cristales azulados que hay en el suelo.', `FemaleText_loc1`='땅 위에 보이는 푸르스름한 수정 덩어리 말입니다.', `FemaleText_loc4`='就是我们在这里找到的这堆蓝水晶。', `FemaleText_loc5`='我們在地面上找到的那堆藍色水晶。', `FemaleText_loc7`='Esos montones de cristales azulados que hay en el suelo.' WHERE `ID`=36355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<땅이 울리고 멀리 있는 바위가 굴러떨어질 정도로 깊고 길게 웃는 고르문간>$B$B아, 하! 하루 하 하룸! 미안해, 작은 친구. 우린 너희처럼 흘린 걸 깨끗이 치우지 못해.', `MaleText_loc4`='<格蒙刚的笑声浑厚而悠长。大地也随着他的声音在颤抖，远处细碎的砾石在不住地滑动。>$B$B哦……哈！哈！哈！小朋友，我很抱歉。我想，我们一族的行为方式和你总会有些区别。', `MaleText_loc5`='<戈穆恩甘發出了深沉的長笑聲，使大地震動和遠方的岩石崩落。>$B$B噢...哈!啊哈哈哈啊!我們巨人族是不像你們那麼的...愛乾淨。', `MaleText_loc7`='<La risa de Gormungan, grave y duradera, retumba en la tierra y causa lejanos corrimientos de tierra.>$b$b¡Oh, ja! ¡Jaaaarjarr... jarrrruuum! Mi insignificante camarada, lo siento mucho. Supongo que los de mi raza no recogen sus desperdicios igual que hacen ustedes.' WHERE `ID`=36356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 거인들이 아즈샤리트를 흘리고 다니는 겁니까? 하지만 어디에서 그것이 나오나요?', `MaleText_loc4`='巨人的身上一直在掉下艾萨莱特水晶？但它到底是从巨人身上的什么地方出来的呢？', `MaleText_loc5`='所以艾薩拉水晶是你們巨人亂丟的東西?那麼它又是從哪裡來的?', `MaleText_loc7`='¿Así que los gigantes habéis estado tirando la azsharita? Pero, ¿de dónde procede?', `FemaleText_loc1`='그럼 거인들이 아즈샤리트를 흘리고 다니는 겁니까? 하지만 어디에서 그것이 나오나요?', `FemaleText_loc4`='巨人的身上一直在掉下艾萨莱特水晶？但它到底是从巨人身上的什么地方出来的呢？', `FemaleText_loc5`='所以艾薩拉水晶是你們巨人亂丟的東西?那麼它又是從哪裡來的?', `FemaleText_loc7`='¿Así que los gigantes habéis estado tirando la azsharita? Pero, ¿de dónde procede?' WHERE `ID`=36357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 말이지, 하룸. 너희 말로 뭐라고 하더라? 하룸. 그러니까 우린 화장실이 따로 없거든. 무슨 말인지 알겠어?', `MaleText_loc4`='它来自——嗯——你们的语言是怎样说的？嗯。我要说，我们一族可是没有厕所的。你明白吗？', `MaleText_loc5`='它們是...哈啊啊...你們是怎麼說的?哈嗯...我們是沒有廁所的，這樣說你懂嗎?', `MaleText_loc7`='Procede de... Grrroar... ¿Cómo lo llaman ustedes? Grrrrer. Digamos que mi raza no tiene retretes. ¿Entiendes?' WHERE `ID`=36358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 똥이라고요!? 그걸 고블린들이 뛰어다니면서 주워담은 겁니까?', `MaleText_loc4`='这是……你拉出来的？！而地精们一直在忙着收集这些东西？', `MaleText_loc5`='是...是你們的排泄物!?哥布林卻把它們當成寶到處在撿?', `MaleText_loc7`='¡¿Son... tus excrementos?! ¿Y los goblins andan de acá para allá recogiéndolos como locos?', `FemaleText_loc1`='그게... 똥이라고요!? 그걸 고블린들이 뛰어다니면서 주워담은 겁니까?', `FemaleText_loc4`='这是……你拉出来的？！而地精们一直在忙着收集这些东西？', `FemaleText_loc5`='是...是你們的排泄物!?哥布林卻把它們當成寶到處在撿?', `FemaleText_loc7`='¡¿Son... tus excrementos?! ¿Y los goblins andan de acá para allá recogiéndolos como locos?' WHERE `ID`=36359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 것 같군. 너희와 친구들은 언제든지 와서 가져가도 좋아. 아마 꽤 단단할 거야. 자주 나오는 건 아니거든.', `MaleText_loc4`='看起来是这样。你和你的朋友们可以随意收集这些东西。我想，它可能是有些用处。我们可不是经常会有这些东西的。', `MaleText_loc5`='看起來是這樣。你和你朋友們想拿多少都可以。我想它們濃度一定很高吧，我們並不是很常需要出來。', `MaleText_loc7`='Eso parece. Tú y tus amigos podéis llevaros todo lo que queráis. Supongo que es muy potente. No necesitamos aliviarnos tan a menudo.' WHERE `ID`=36360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 자주, 음, 일을 봅니까?', `MaleText_loc4`='那你，呃，多长时间会“有”一些这种东西呢？', `MaleText_loc5`='你們大概多久...呃...「出來」一次?', `MaleText_loc7`='¿Cada cuánto os, eh, "aliviáis"?', `FemaleText_loc1`='얼마나 자주, 음, 일을 봅니까?', `FemaleText_loc4`='那你，呃，多长时间会“有”一些这种东西呢？', `FemaleText_loc5`='你們大概多久...呃...「出來」一次?', `FemaleText_loc7`='¿Cada cuánto os, eh, "aliviáis"?' WHERE `ID`=36361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 너희처럼 수명이 짧지 않아, 말랑한 친구. 건강한 거인은 10년에 세제곱미터만큼 먹지. 뭐, 난 2년 정도에 한 번씩은 간식도 먹지만 말이야. 화장실은 배탈이 났을 때 빼고는 아마 15년이나 25년에 한 번 갈 거야.', `MaleText_loc4`='我们的生命进程不像你们那样快，我柔软的朋友！一个健康的巨人每十年会吃三顿饭。不过我每两年会吃一次小点心。我们每15到25年会上一次厕所……拉肚子除外。', `MaleText_loc5`='我們的生命不像你們的那麼短，我柔弱的朋友。一個健康的巨人每十年要吃三頓正餐，但我自己每幾年會放縱一下吃些點心。除非拉肚子...不然我們差不多每15到25年才會上一次廁所。', `MaleText_loc7`='No vivimos nuestras vidas a tanta velocidad como ustedes viven las suyas, mi blandengue camarada. Un gigante saludable toma tres comidas en una década, aunque yo, la verdad, a veces picoteo cada dos años o así. Vamos al baño cada 15 o 25 años... a no ser que tengas un problema de estómago.' WHERE `ID`=36362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='15년에서 25년이요? 조수 그릴리가 반길 이야기는 아니군요!', `MaleText_loc4`='15到25年？助手格瑞里可不会喜欢听到这种消息！', `MaleText_loc5`='15到25年?助理格里利聽到這答案一定會很不開心!', `MaleText_loc7`='¿Cada 15 o 25 años? ¡Eso no le hará ninguna gracia al ayudante Greely!', `FemaleText_loc1`='15년에서 25년이요? 조수 그릴리가 반길 이야기는 아니군요!', `FemaleText_loc4`='15到25年？助手格瑞里可不会喜欢听到这种消息！', `FemaleText_loc5`='15到25年?助理格里利聽到這答案一定會很不開心!', `FemaleText_loc7`='¿Cada 15 o 25 años? ¡Eso no le hará ninguna gracia al ayudante Greely!' WHERE `ID`=36363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<재미있다는 듯 코웃음을 치는 고르문간>$B$B하룸! 생활 습관을 이렇게 자세히 생각해본 건 난생처음인걸. 너흰 정말 봐도 봐도 놀라운 종족이야. 잘 가라, 친구. 그리고 조사 중인 그거... 잘 되길 바란다.', `MaleText_loc4`='<格蒙刚和善地喷了一下鼻息。>$B$B 哈！我还没有这样细致地考虑过自己的个人习惯呢。你们总是让我感到吃惊。再见，朋友，祝你好运……无论你要找的是什么。', `MaleText_loc5`='<戈穆恩甘溫和地哼了一聲。>$B$B哈啊啊!從來都沒有人批評過我的個人習慣。你們這些人不斷地帶給我驚喜。再見了，朋友，祝你們...不管你們在做什麼...都一切順利。', `MaleText_loc7`='<Gormungan ríe de buena gana.>$b$b¡Jaaaar... grrrroar! Nunca nadie había examinado mis hábitos personales con tanta minuciosidad. Tu gente nunca deja de sorprenderme. Adiós, camarada, y buena suerte con... lo que sea que te traigas entre manos.' WHERE `ID`=36364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤리트에 대해 다시 한 번 이야기해주시겠습니까?', `MaleText_loc4`='能再告诉我一下关于艾萨莱特水晶的事情么？', `MaleText_loc5`='能再跟我說一下與艾薩拉水晶有關的事嗎?', `MaleText_loc7`='Háblame otra vez sobre la azsharita.', `FemaleText_loc1`='아즈샤리트에 대해 다시 한 번 이야기해주시겠습니까?', `FemaleText_loc4`='能再告诉我一下关于艾萨莱特水晶的事情么？', `FemaleText_loc5`='能再跟我說一下與艾薩拉水晶有關的事嗎?', `FemaleText_loc7`='Háblame otra vez sobre la azsharita.' WHERE `ID`=36365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡았다!', `MaleText_loc4`='找到了一个！', `MaleText_loc5`='逮到一個!', `MaleText_loc7`='¡Tengo uno!', `FemaleText_loc1`='여기요!', `FemaleText_loc4`='这边！', `FemaleText_loc5`='在這裡!', `FemaleText_loc7`='¡Allí!' WHERE `ID`=36366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 잡았다!', `MaleText_loc4`='抓住一个！', `MaleText_loc5`='絆倒一個!', `MaleText_loc7`='¡He atrapado uno!', `FemaleText_loc1`='쓰러뜨렸어!', `FemaleText_loc4`='搞定！', `FemaleText_loc5`='解決他!', `FemaleText_loc7`='¡Derríbalos!' WHERE `ID`=36367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해치워라!', `MaleText_loc4`='打败他们！', `MaleText_loc5`='殺死他們!', `MaleText_loc7`='¡Blanco!', `FemaleText_loc1`='해치워!', `FemaleText_loc4`='打败他们！', `FemaleText_loc5`='殺死他們!', `FemaleText_loc7`='¡Blanco!' WHERE `ID`=36368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기분 나쁘게 하려는 건 아니지만, 칩은 제 남자 친구고 저는 지금 무역왕님을 위해 일하거든요.$B$B비켜주지 않겠어요? 당신 때문에 앞이 잘 안 보이네요.', `FemaleText_loc4`='无意冒犯，宝贝儿，但我的男朋友是奇普，而且现在我要听贸易大王的。$B$B赶快走吧，你挡住我的视线了。', `FemaleText_loc5`='我沒惡意，寶貝，但奇普是我男友而且我現在跟貿易親王是同一國的了。$B$B可以讓開嗎?你擋住我的視線了。', `FemaleText_loc7`='No te lo tomes a mal, cielín, pero Locko es mi novio ahora.$B$BMuévete, ¿quieres? Me tapas la vista.' WHERE `ID`=36369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네? 뭘 원하죠?', `FemaleText_loc4`='什么？你想要什么？', `FemaleText_loc5`='嗯?你要什麼?', `FemaleText_loc7`='¿Sí? ¿Qué quieres?' WHERE `ID`=36370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 $n, 내 말 좀 들어봐. 당신이랑 말하는 걸 누가 보면 안 돼. 당신은 무역왕의 명단에서 딱히 상위에 속하지는 않는 데다 난 장래를 생각해야 하거든.$B$B내 말 알아듣겠지, 귀염둥이? 그리고 난 지금 캔디랑 사귄다고.', `MaleText_loc4`='听着，$n，我不能让别人看见我在和你说话。你不再是贸易大王眼中的红人了，而我则需要为我的未来考虑。$B$B你明白我的意思，对吧，宝贝儿？另外，我现在和小甜甜在一起了。', `MaleText_loc5`='聽著，$n，我不能被別人看到跟你說話。貿易親王並沒有特別喜歡你，而我也必須考慮我自己的事業。$B$B你可以瞭解的對吧，寶貝?還有，我現在跟凱蒂在一起了。', `MaleText_loc7`='Escucha, $n, no pueden verme hablar contigo. Actualmente no estás precisamente en lo más alto de la lista de amigos del Príncipe mercante y tengo que pensar en mi futuro.$B$B¿Lo entiendes, verdad, cielín? Además, ahora estoy con Cara.' WHERE `ID`=36371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이자고, 친구.', `MaleText_loc4`='走开，小子。', `MaleText_loc5`='快走啊，小子。', `MaleText_loc7`='Muévete, rapaz.' WHERE `ID`=36372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리집이야!', `MaleText_loc4`='我的房子！', `MaleText_loc5`='我的房子!', `MaleText_loc7`='¡Mi casa!' WHERE `ID`=36373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<목소리를 낮춰 거의 안 들릴 지경으로 속삭이는 무역왕>$B$B한순간도 내가 너를 얼마나 싫어했는지 잊어버렸다고는 생각하지 마, $n. 나를 구해줬건 아니건 말이야.$B$B네 그 $g단순한:예쁘장하기만 한; 머리는 걱정하지 마. 곧 복수할 테니까. 이 말 명심해 두라고!$B$B내가 부리는 노예보다 훨씬 나쁜 대가를 치르게 해 주지. 이번에는 도망갈 수 없을 거야.', `MaleText_loc4`='<贸易大王用低微的耳语说道。>$B$B不管你是否能逃掉，绝不要以为我会忘记你这个卑微的家伙，$n。$B$B不必再为你那颗$g简单:漂亮;的脑袋而担心了。记住，我很快就会进行复仇！$B$B到时候，你将羡慕那些能成为我的奴隶的人。你逃不出我的手心。', `MaleText_loc5`='<貿易親王將他的聲音降到像是說悄悄話一樣。>$B$B我一分一秒都沒忘記我有多厭惡你，$n，不管有沒有被救出來。$B$B你這$g豬腦:花瓶;不用擔心，過不了多久我就可以享受復仇的快感，給我記住!$B$B你到時會比成為我的奴隸還要慘一千萬倍，到時讓你叫天天不應，叫地地不靈。', `MaleText_loc7`='<El Príncipe mercante baja la voz hasta hablar casi en un susurro.>$b$bNo creas ni por un momento que he olvidado lo mucho que te desprecio, $n, con rescate o sin él.$B$BNo te preocupes cabecita $gsimple:bonita;. ¡Pronto tendré mi venganza, recuerda mis palabras!$B$BPuedes estar todavía peor que siendo mi $gesclavo:esclava;. Esta vez no tendrás escape.' WHERE `ID`=36374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살짝 긁힌 것뿐이로군요! 잘하셨습니다!', `FemaleText_loc4`='你身上连个刮痕都没有！干得好！', `FemaleText_loc5`='你竟然沒受什麼傷!太厲害了!', `FemaleText_loc7`='¡Apenas tienes un rasguño! ¡Bien hecho!' WHERE `ID`=36375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하군! 불이 잔뜩 붙은 고양이보다 더 빠르게 뛰어가는구나. 아주 적절해!', `MaleText_loc4`='真是不可思议！你向前蹦的速度简直比被火烧了尾巴的小猫更快。实在是太合适了！', `MaleText_loc5`='棒呆了!你往前衝的速度比著火的貓咪還快。的確很適合!', `MaleText_loc7`='¡Maravilloso! Has salido corriendo más rápido que un gatito en llamas. ¡Muy apropiado, desde luego!' WHERE `ID`=36376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 누구 때문에 이런 꼴이 됐는지 말 안 해도 잘 알고 있겠지! 걱정할 것 없다! 반드시 놈들이 제대로 대가를 치르게 해 주겠어!', `MaleText_loc4`='哦，我想我们全都知道，到底是谁该为现在这种一团糟的局面负责！不必担心，我保证$n会得到应有的教训！', `MaleText_loc5`='噢，我想我們都知道會陷入這種狀況是誰的責任!別擔心，我保證$n會受到$g他:她;應得的報應!', `MaleText_loc7`='¡Yo creo que todos sabemos quién es el responsable de todo este lío! ¡No se preocupen, yo me haré que reciban lo que se merecen!' WHERE `ID`=36377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 당황하지 마라! 반드시 이 끔찍한 섬을 떠나게 해주지. 조금만 기다려라... 나한테 다 계획이 있다!', `MaleText_loc4`='不要惊慌！我会让所有人都离开这座糟糕的岛屿。看着吧……我早已经计划好了！', `MaleText_loc5`='所有人冷靜! 我一定會讓大家都離開這個糟糕的島嶼。看著好了...我已經都計畫好了!', `MaleText_loc7`='¡Todos tranquilos! Yo nos sacaré de esta isla deplorable. Ya verán... ¡Tengo todo planeado!' WHERE `ID`=36379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워하지 마라. 무역왕 갤리윅스 님이 여기 있다! 우리는 새로운 고향, 아즈샤라로 눈 깜짝할 사이에 떠날 것이다! 우릴 이렇게 만든 그 누군가가 방해해도 아무 소용없어!', `MaleText_loc4`='不要害怕，贸易大王加里维克斯就在这里。我们立马就要出发前往我们在艾萨拉的新家了！就算是某个人继续在那儿捣乱也没用。', `MaleText_loc5`='用不著害怕，貿易親王加里維克斯在此。我們一眨眼就會上路前往我們在艾薩拉的新家! 就算是$n在那裡自以為是的攪局也一樣。', `MaleText_loc7`='No teman, el príncipe mercante Gallywix llegó. ¡Muy pronto estaremos rumbo a nuestro nuevo hogar en Azshara! A pesar de la torpe interferencia de ya sabes quién.' WHERE `ID`=36380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누군가가 케잔에서 쓸데없는 짓만 안 했다면 우리는 지금쯤 아즈샤라에 무사히 도착해 있으리란 생각을 머릿속에서 지울 수가 없군.', `MaleText_loc4`='我禁不住会想，如果不是$n在科赞捣乱，我们现在早已安全到达艾萨拉，过上好日子了。', `MaleText_loc5`='我沒辦法不去想，如果在凱贊時不是$n在多管閒事，我們現在早就已經安全抵達艾薩拉了。', `MaleText_loc7`='No puedo dejar de pensar en que si no fuera por la intromisión de cierta persona en Kezan, ya estaríamos a salvo en Azshara.' WHERE `ID`=36381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 널 지켜본다는 걸 명심해라. 우리 둘 중 하나만 이 섬을 떠날 수 있을 것이다. 그리고 그 고블린은, 바로 무역왕 님이시다!', `MaleText_loc4`='我一直都在注意你，$n。如果我们之中只有一个能够离开这座岛，那么这个地精的名字就是贸易大王！', `MaleText_loc5`='我注意你很久了，$n。這樣說吧，我們之間只有一個會離開這座島，就是名字裡有提到貿易親王的那個哥布林!', `MaleText_loc7`='Te estoy observando. ¡Digamos que sólo uno saldrá de esta isla, y el nombre de ese goblin empieza con Príncipe Mercante!' WHERE `ID`=36382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케잔에서 내 자리를 차지할 수 있을 줄 알았나? 건방진 놈! 넌 내 덕에 그만큼이라도 됐던 거야... 그것도 이젠 옛날 일이지. 지금의 넌 아무것도 아니다! 아무것도!', `MaleText_loc4`='你想要取代我在科赞的位置，$n？痴心妄想！别忘了，是我给了你今天的地位。现在你什么都不是了！不是了！！', `MaleText_loc5`='你想要在凱贊取代我的位置，$n?你太過火了，讓你曾經風光的人是我...曾經是關鍵字。你現在什麼都不是。什麼都不是!', `MaleText_loc7`='¿Quisiste tomar mi lugar en Kezan? ¡Qué ambicioso! Yo te hice lo que eras... Notarás que dije "eras". Ahora no eres nada. ¡Nada!' WHERE `ID`=36383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 잘 들어라... 날 따르지 않는 놈들은 전부 새로운 직장을 찾아야 할 거야!', `MaleText_loc4`='我要你们都好好听着……任何不跟从我的人现在就可以去找一个新的工作！', `MaleText_loc5`='我要你們全部人聽好...任何不站在我這一邊的人都可以開始找新工作了!', `MaleText_loc7`='Escuchen todos con atención... ¡el que no esté conmigo, que empiece a buscar otro trabajo!' WHERE `ID`=36384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 걱정 마라. 새로운 고향으로 가는 도중에 잠깐 휴식을 즐기고 있다고 생각하면 된다.', `MaleText_loc4`='大家不必担心，这只是前往我们新家园途中的一次短暂的休整。', `MaleText_loc5`='大家不用擔心，這裡只是我們前往新家園的中途站而已。', `MaleText_loc7`='No se preocupen, esto es sólo una parada en el camino a nuestro nuevo hogar.' WHERE `ID`=36385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차마 갚기도 어려울 만큼 엄청난 빚을 졌네, $n.', `MaleText_loc4`='我们欠你的永远都还不清，$n。', `MaleText_loc5`='我們欠了你一個很難歸還的人情，$n。', `MaleText_loc7`='Te debemos un favor que resultará difícil de devolver, $n.' WHERE `ID`=36386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄 님을 구해줘서 고맙습니다, $n 님. 행방불명이셨거든요.$B$B<대족장을 올려다보는 아그라>', `FemaleText_loc4`='$n，谢谢你救了萨尔。我们一直都找不到他。$B$B<阿格娜关切的看着酋长。>', `FemaleText_loc5`='謝謝你救出了索爾，$n，大家都很想念他。$B$B<阿格拉看著大酋長。>', `FemaleText_loc7`='Gracias por liberar a Thrall, $n. Le hemos echado de menos.$B$B<Aggra mira al Jefe de Guerra.>' WHERE `ID`=36387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼크토카르 전투 현장으로 돌아가지 않으면 켄타우로스들에게 버림받을 것입니다!', `MaleText_loc4`='返回夏克索卡的战场，否则半人马就会抛弃你！', `MaleText_loc5`='回到修克托卡的戰場上，不然半人馬將會遺棄你!', `MaleText_loc7`='¡Regresa a la batalla en Shok''Thokar o los centauros te abandonarán!' WHERE `ID`=36388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜로 이 줄이 안 움직인다고!', `MaleText_loc4`='我发誓这排的队压根儿就没动过！', `MaleText_loc5`='我發誓這條線動都沒動!', `MaleText_loc7`='¡Te juro que esta cola no se mueve!', `FemaleText_loc1`='진짜로 이 줄이 안 움직인다고요!', `FemaleText_loc4`='我发誓这排的队压根儿就没动过！', `FemaleText_loc5`='我發誓這條線動都沒動!', `FemaleText_loc7`='¡Te juro que esta cola no se mueve!' WHERE `ID`=36389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐에 걸렸지?', `MaleText_loc4`='出了什么事？', `MaleText_loc5`='到底在拖什麼?', `MaleText_loc7`='¿Qué te detiene?', `FemaleText_loc1`='뭐에 걸렸나?', `FemaleText_loc4`='出了什么事？', `FemaleText_loc5`='到底在拖什麼?', `FemaleText_loc7`='¿Qué te detiene?' WHERE `ID`=36390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 금이라고, 친구!', `MaleText_loc4`='时间就是金钱，朋友！', `MaleText_loc5`='時間就是金錢，朋友!', `MaleText_loc7`='¡El tiempo es oro, colega!', `FemaleText_loc1`='시간은 금이라고요, 친구!', `FemaleText_loc4`='时间就是金钱，朋友！', `FemaleText_loc5`='時間就是金錢，朋友!', `FemaleText_loc7`='¡El tiempo es oro, colega!' WHERE `ID`=36391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 섬에도 화산이 있어?', `MaleText_loc4`='另外那座岛上是有一座火山吗？', `MaleText_loc5`='那座島上的那個是座火山嗎?', `MaleText_loc7`='¿Eso de la otra isla es un volcán?', `FemaleText_loc1`='다른 섬에도 화산이 있나요?', `FemaleText_loc4`='另外那座岛上是有一座火山吗？', `FemaleText_loc5`='那座島上的那個是座火山嗎?', `FemaleText_loc7`='¿Eso de la otra isla es un volcán?' WHERE `ID`=36392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 기준으로도 저 로켓은 안전한 것 같지 않단 말이야!', `MaleText_loc4`='即使以我们的标准来看，那个火箭也不安全！', `MaleText_loc5`='就算以我們的標準來看，那火箭也不算安全!', `MaleText_loc7`='¡Este cohete parece poco seguro incluso para nuestros estándares!', `FemaleText_loc1`='우리 기준으로도 저 로켓은 안전한 것 같지 않아요!', `FemaleText_loc4`='即使以我们的标准来看，那个火箭也不安全！', `FemaleText_loc5`='就算以我們的標準來看，那火箭也不算安全!', `FemaleText_loc7`='¡Este cohete parece poco seguro incluso para nuestros estándares!' WHERE `ID`=36393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리가 화산이 있는 섬으로 로켓을 타고 가야 하지? 케잔에서 이 계획대로 했다가 목숨이 간당간당했었잖아?', `MaleText_loc4`='为什么我们要向一座有火山的岛发射火箭？我们不是刚刚在科赞的行动中幸存下来吗？', `MaleText_loc5`='我們為什麼要飛到另一座有火山的島上?我們就是因為火山才千辛萬苦地從凱贊逃出來，不是嗎?', `MaleText_loc7`='¿Por qué vamos a sobrevolar con el cohete una isla que tiene un volcán? ¿No es cierto que en Kezan sobrevivimos de milagro a una situación similar?', `FemaleText_loc1`='왜 우리가 화산이 있는 섬으로 로켓을 타고 가야 하죠? 케잔에서 이 계획대로 했다가 목숨이 간당간당했었잖아요?', `FemaleText_loc4`='为什么我们要向一座有火山的岛发射火箭？我们不是刚刚在科赞的行动中幸存下来吗？', `FemaleText_loc5`='我們為什麼要飛到另一座有火山的島上?我們就是因為火山才千辛萬苦地從凱贊逃出來，不是嗎?', `FemaleText_loc7`='¿Por qué vamos a sobrevolar con el cohete una isla que tiene un volcán? ¿No es cierto que en Kezan sobrevivimos de milagro a una situación similar?' WHERE `ID`=36394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생긴 걸 보니, 차라리 상어떼 사이로 헤엄쳐가고 말겠어!', `MaleText_loc4`='看这东西的样子，我宁可试着和鲨鱼一起游泳！', `MaleText_loc5`='看到那個東西，我或許寧願冒險跟鯊魚一起游泳!', `MaleText_loc7`='Viendo el aspecto de esa cosa, puede que me juegue el pellejo nadando con los tiburones.', `FemaleText_loc1`='생긴 걸 보니, 차라리 상어떼 사이로 헤엄쳐가고 말겠어요!', `FemaleText_loc4`='看这东西的样子，我宁可试着和鲨鱼一起游泳！', `FemaleText_loc5`='看到那個東西，我或許寧願冒險跟鯊魚一起游泳!', `FemaleText_loc7`='Viendo el aspecto de esa cosa, puede que me juegue el pellejo nadando con los tiburones.' WHERE `ID`=36395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='접는 의자가 필요할 거 같더니만.', `MaleText_loc4`='我就知道，应该把我的折叠椅带来。', `MaleText_loc5`='我就知道我應該帶上我的摺疊椅的。', `MaleText_loc7`='Sabía que tenía que haber traído mi silla plegable.', `FemaleText_loc1`='접는 의자가 필요할 줄 알았어요.', `FemaleText_loc4`='我就知道，应该把我的折叠椅带来。', `FemaleText_loc5`='我就知道我應該帶上我的摺疊椅的。', `FemaleText_loc7`='Sabía que tenía que haber traído mi silla plegable.' WHERE `ID`=36396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만났군, 작고 말랑한 친구. 뭘 가지고 온 거야?', `MaleText_loc4`='又见到你了，柔软的小朋友。这次你要做什么？', `MaleText_loc5`='嗨，又見面了，可愛的小朋友。你有什麼事嗎?', `MaleText_loc7`='Hola de nuevo, pequeño amigo blandito. ¿Qué tienes ahí?' WHERE `ID`=36397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $g젊은이:아가씨;. 로켓처럼 달려보자고! 아싸!', `MaleText_loc4`='嗨，$g兄弟:小姐;。乘坐火箭吧！耶！', `MaleText_loc5`='嘿，$g老兄:小姐;。火箭時間!爽啊!', `MaleText_loc7`='Oye, $ghermano: hermana;. ¡Ahora de volar en cohete! ¡Sí!' WHERE `ID`=36398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 좀 드셔 보세요. 특별한 초콜릿 바위예요.', `MaleText_loc4`='给，把这个吃了！这是一种特殊的巧克力石头。', `MaleText_loc5`='喏，吃這個!這是特製的巧克力石頭。', `MaleText_loc7`='¡Toma, come esto! Es una roca especial de chocolate.', `FemaleText_loc1`='이것 좀 드셔 보세요. 특별한 초콜릿 바위예요.', `FemaleText_loc4`='给，把这个吃了！这是一种特殊的巧克力石头。', `FemaleText_loc5`='喏，吃這個!這是特製的巧克力石頭。', `FemaleText_loc7`='¡Toma, come esto! Es una roca especial de chocolate.' WHERE `ID`=36399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, $n 님. 저희를 또다시 구해 주셨군요! 우리가 당하기 전에 사악한 인간들을 처치해 주셔서 감사해요!', `FemaleText_loc4`='哦，$n，你又救了我们！感谢你为我们消灭了那些恶棍！', `FemaleText_loc5`='噢，$n，你再次救了我們!謝謝你在那些人類對我們做出什麼前把他們給解決了!', `FemaleText_loc7`='¡Oh, $n, nos has salvado de nuevo! ¡Gracias por ayudarnos a eliminar a esos malvados humanos antes de que nos atraparan!' WHERE `ID`=36400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<설사제를 의심스럽게 바라보며 코를 킁킁대더니, 화난 표정을 짓고 설사제를 뭉개 고블린 모양으로 만드는 고르문간>$B$B네 작은 녹색 친구들이 네게 소용없는 짓을 시켰구나. 우리 거인은 녀석들의 장난에 놀아나지 않는다고 설명해줘라.$B$B<자신의 뜻을 보여주기 위해 초콜릿 고블린 조각의 머리를 비틀어버린 후 돌려주는 고르문간>', `MaleText_loc4`='<格蒙刚带着怀疑的神情看着这团软软的东西，然后又嗅了嗅它，便气恼地将它捏塑成一只地精的样子。>$B$B我怀疑你那些小绿人朋友没想让你做好事儿。去告诉他们，我们巨人可不是任人玩弄的。$B$B<为了表达他的意思，格蒙刚在把他刚做成的地精雕像交给你的时候，又用力拧断了它的脑袋。>', `MaleText_loc5`='<戈穆恩甘懷疑地看著泄藥，然後嗅了嗅它。他臉上明顯的出現了噁心的表情，將泄藥捏成了一個哥布林的形狀。>$B$B我懷疑你小隻的綠色朋友出賣了你。請跟他們說我們這些巨人不笨，沒那麼好騙。$B$B<為了讓你更加瞭解，戈穆恩甘將哥布林巧克力的頭扭了下來，然後把它還給了你。>', `MaleText_loc7`='<Gormungan mira el laxante receloso, después lo huele. Evidentemente irritado, comienza a aplastar y moldear el laxante para darle forma de goblin.>$B$BSospecho que tus amiguitos verdes no te llevan por el buen camino. Explícales que con los gigantes no se juega.$B$B<Para hacer hincapié en esto, Gormungan retuerce la cabeza de su estatua de goblin antes de volver a entregártela.>' WHERE `ID`=36401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펜티가스트! 새로 온 $r에게 상황을 알려주겠나?', `MaleText_loc4`='本迪加斯！让这个新$r先了解一下情况，好吗？', `MaleText_loc5`='潘迪加斯!快把新的那個$r帶過來，可以嗎?', `MaleText_loc7`='¡Pentigast! Pon $gal nuevo:a la nueva; $r al día, ¿quieres?' WHERE `ID`=36402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼 때마다 반가워, 친구!', `MaleText_loc4`='很高兴见到你，朋友！', `MaleText_loc5`='一如以往，很高興看到你，朋友!', `MaleText_loc7`='¡Siempre me alegro de verte, $gamigo:amiga;!' WHERE `ID`=36403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래플해머 박사님께선 절 믿고 모든 일을 맡기셨어요. 그분은 방해받지 않고 연구에 몰두하셔야 하니까요.', `FemaleText_loc4`='钩锤相信我能把事情做好。不能让这些琐碎的事情干扰他。', `FemaleText_loc5`='繫錘信任我可以將事情處理好。他不應該為這些小事操心。', `FemaleText_loc7`='Martillazos confía en mí para que me encargue de que se hagan las cosas. Una mente como la suya necesita estar libre de distracciones.' WHERE `ID`=36404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작아질 준비가 되셨나요? 약간 따끔하고 뜨거울 거예요. 고통과 경련은 금방 사라질 테니 걱정 마시고요.', `FemaleText_loc4`='你准备好被缩小了吗？这也许有一点痛，还有一点烧灼感。不过疼痛和抽搐很快就会过去的。', `FemaleText_loc5`='你準備好要被縮小了嗎?這可能會有點刺痛和灼痛。但痛苦和痙攣很快就會消失的。', `FemaleText_loc7`='¿Ahora dejarás que te encoja? Quizá sientas una picazón. Y una quemazón. Pero la agonía y las convulsiones pasarán rápido.' WHERE `ID`=36405;
