UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신중하라, 친구여... $b$b앞으로 몇 시간이면 우리 부족의 운명이 결정된다.', `MaleText_loc4`='镇定，朋友……$b$b随后的几个小时将决定我们部族的命运。', `MaleText_loc5`='保持冷靜，朋友...$b$b接下來這幾個小時將決定我們氏族的命運。', `MaleText_loc7`='Tranquilízate, $gamigo:amiga;... $b$bLas próximas horas determinarán el destino de nuestros clanes.' WHERE `ID`=36413;
