UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*숨을 헐떡이며* 고맙습니다. 덕분에 목숨을 건졌습니다.', `MaleText_loc4`='谢谢你……*喘息声*是你救了我一命。', `MaleText_loc5`='謝謝你...<喘氣>我欠你一命。', `MaleText_loc7`='Gracias... *suspiro*. Te debo mi vida.', `FemaleText_loc1`='*숨을 헐떡이며* 고마워요. 덕분에 목숨을 건졌어요.', `FemaleText_loc4`='谢谢你……*喘息声*是你救了我一命。', `FemaleText_loc5`='謝謝你...<喘氣>我欠你一命。', `FemaleText_loc7`='Gracias... *suspiro*. Te debo mi vida.' WHERE `ID`=36417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장이라고 생각했습니다. 정말 감사합니다.', `MaleText_loc4`='我……我还以为自己死定了。谢谢。', `MaleText_loc5`='我...我以為我死定了。謝謝你。', `MaleText_loc7`='Creía... Creía que iba a morir. Gracias.', `FemaleText_loc1`='끝이라고 생각했어요. 정말 고마워요.', `FemaleText_loc4`='我……我还以为自己死定了。谢谢。', `FemaleText_loc5`='我...我以為我死定了。謝謝你。', `FemaleText_loc7`='Creía... Creía que iba a morir. Gracias.' WHERE `ID`=36418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 발아래로 꺼졌습니다... 정말 죽는 줄로만 알았는데 덕분에 목숨을 건졌습니다.', `MaleText_loc4`='我们脚下的地面在坍塌……我还以为我已经死了。我欠你一份情。', `MaleText_loc5`='大地在我們的腳下裂了開來...我以為我死定了。我欠你一命。', `MaleText_loc7`='La tierra cedió bajo nuestros pies... Creía que estaba muerto. Te debo una.', `FemaleText_loc1`='땅이 발아래로 꺼졌어요... 정말 죽는 줄로만 알았는데 덕분에 목숨을 건졌어요', `FemaleText_loc4`='我们脚下的地面在坍塌……我还以为我已经死了。我欠你一份情。', `FemaleText_loc5`='大地在我們的腳下裂了開來...我以為我死定了。我欠你一命。', `FemaleText_loc7`='La tierra cedió bajo nuestros pies... Creía que estaba muerta. Te debo una.' WHERE `ID`=36419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고양이를 데려가야겠군. 아주 완벽한 미끼가 될 거야. 이제 죽을 준비나 해라, 멍청아!', `MaleText_loc4`='我会接管这只猫。它看上去能够成为完美的诱饵。准备好去死吧，傻瓜！', `MaleText_loc5`='這隻貓我要了，牠看起來可以作為完美的誘餌。準備去死吧，蠢貨!', `MaleText_loc7`='Me llevo este gato. Parece que es el cebo perfecto. Ahora, ¡prepárate a morir, idiota!' WHERE `ID`=36420;
