UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<다음과 같이 손으로 쓴 글씨가 적혀 있습니다.>$B$B          비밀 실험실 보관소$B     X. 니즐벡스 - 실험실장$B$B$B도움이 필요하면 초인종을 누르시오.', `MaleText_loc4`='<这是一段手写的文字：>$B$B          秘密实验室档案馆$B     X.尼泽柏克，实验室主管$B$B$B请按蜂鸣器呼叫服务。', `MaleText_loc5`='<標示牌上手寫的字跡寫著:>$B$B          秘密實驗室檔案庫$B     X·尼姿爾貝克斯，實驗室負責人$B$B$B如需服務請按鈴。', `MaleText_loc7`='<Un cartel escrito a mano dice:>$b$b          Archivo del Laboratorio Secreto$B      X. Nizzlebex. Director del laboratorio$b$b$BLlamad al timbre para ser atendidos.' WHERE `ID`=36426;
