UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘에 대한 유혹이 너무 강렬했소. 실수를 저지른 게지.', `MaleText_loc4`='能量的诱惑很难抗拒。错误已然铸成。', `MaleText_loc5`='來自力量的引誘是很強大的，而錯誤已然造成。', `MaleText_loc7`='La atracción del poder es grande. Se cometieron errores.' WHERE `ID`=36430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이야기를 들어주기 전까지는 갈 수 없소. 너무 많은 것이 달린 일이니까.', `MaleText_loc4`='不召见我我是不会走的。形势已经非常危险了。', `MaleText_loc5`='除非我親耳聽見，否則我不回去。太多事情仍存有變數。', `MaleText_loc7`='No regresaré hasta que se me haya escuchado. Hay demasiado en juego.' WHERE `ID`=36431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변화의 바람이 불고 있고, 우린 그것을 무시할 수 없소. 나는 협정을 맺고자 과거의 수치와 타락을 떨치고 여기까지 왔소.', `MaleText_loc4`='我从风中感到了变化，我们不能不闻不问。我带着诚意走过尘灰漫天、满目疮痍的过去，为得就是能让我们尽弃前嫌。', `MaleText_loc5`='風中帶來了變化，我們不能忽略它。我從動盪破敗的過去而來就是為了能達成協議。', `MaleText_loc7`='Los vientos están cambiando y no podemos ignorarlos. He viajado desde el polvo y las ruinas del pasado para llegar a un acuerdo.' WHERE `ID`=36432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼도레이가 우리의 지식과 기술을 필요로 할 때가 곧 올 수도 있소.', `MaleText_loc4`='卡多雷族人恐怕很快就会需要我们的知识与技艺。', `MaleText_loc5`='或許時候即將到來，卡多雷需要我們所提供的知識與技藝之時。', `MaleText_loc7`='Pronto llegará la hora en la que los kaldorei necesitarán el conocimiento y las habilidades que podemos ofrecer.' WHERE `ID`=36433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리겠소, 파수꾼이여... 하지만 난 반드시 티란데를 만나겠소.', `MaleText_loc4`='我可以等，卫兵……但请一定要召见我。', `MaleText_loc5`='我會等待，哨兵...但我一定要見她。', `MaleText_loc7`='Esperaré, centinela... pero obtendré mi audiencia.' WHERE `ID`=36434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시오, 파수꾼이여. 그 힘을 탐낸 것이 아니오. 그저... 되새기고 있었소.', `MaleText_loc4`='冷静，卫兵。我不是要试图使用它。我只是……在记忆。', `MaleText_loc5`='冷靜點，哨兵。我並沒有打算要使用它。我只不過...在回憶。', `MaleText_loc7`='Cálmate, centinela. No quiero usarlo. Solo estoy... recordando.' WHERE `ID`=36435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하시오. 나는 참으로 오랫동안 여기서 떨어져 있었소. 이 신전 안의 달샘은 단순히 영원의 샘의 희미한 그림자일지 모르나, 여전히 그 안엔 아름다움이... 순수함이 담겨 있소.', `MaleText_loc4`='够了。几百年来我一直与它相隔天涯。这座神庙中的月亮井也许是永恒之井枯竭的影照，但它仍然是那么……美丽。纯净。', `MaleText_loc5`='夠了。我已經有數個世紀不曾和這些事情有關。這神殿中的水井或許只是永恆之井的蒼白幽靈，但它依舊有著同樣的...美麗。純淨。', `MaleText_loc7`='Basta. Llevo siglos alejado de esto. El pozo que hay dentro de este templo puede no ser más que un pálido reflejo del Pozo de la Eternidad, pero contiene la misma... belleza. Pureza.' WHERE `ID`=36436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잊고 있었던...', `MaleText_loc4`='我已经忘记了。', `MaleText_loc5`='我所遺忘的。', `MaleText_loc7`='Lo había olvidado.' WHERE `ID`=36437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감탄하는 눈길, 동경하는 마음이 사회적 규범에 어긋난다고 생각하지는 않소.', `MaleText_loc4`='我不相信赞美与怀旧的思想会与这个社会相抵触。', `MaleText_loc5`='我不認為欽佩讚揚和深思熟慮會妨礙社會規範。', `MaleText_loc7`='No creo que la admiración y los pensamientos melancólicos vayan en contra de las normas de la sociedad.' WHERE `ID`=36438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단지 바라보았다는 이유로 그대가 먼저 날 나무라지 않았소. 어쨌든 난 아직 티란데와의 접견을 기다리고 있소.', `MaleText_loc4`='你就是那个不明就里的家伙。我坚持要等泰兰德召见我。', `MaleText_loc5`='你光只是看到我就想向我挑戰。我依舊在等待覲見泰蘭妲。', `MaleText_loc7`='Tú eres la que me ha retado solo por mirar. Todavía espero mi audiencia con Tyrande.' WHERE `ID`=36439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 달샘을 바라보며 한숨을 내쉽니다.', `MaleText_loc4`='%s注视着月亮之井，轻轻的叹了口气。', `MaleText_loc5`='%s看著月井發出一聲嘆息。', `MaleText_loc7`='%s mira hacia la Poza de la Luna suspirando.' WHERE `ID`=36440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 덕분에 우리 세나리온의 자손이 하나로 뭉쳤다.$b$b$n, 우리 부족이 살아 있는 한 네 업적은 두고두고 회자될 것이다!', `MaleText_loc4`='作为塞纳里奥之子，我们团结在一起。感谢你。$b$b只要我们部族还存在，你在这里的事迹就不会被遗忘，$n！', `MaleText_loc5`='多虧了你，讓我們以塞納里奧之子的身分齊聚一堂。$b$b$n，只要我們的氏族還存在的一天，你在這的功績就會一直流傳下去!', `MaleText_loc7`='Gracias a ti seguimos unidos como hijos de Cenarion.$B$B¡Tus hazañas en este lugar pervivirán mientras nuestros clanes aún respiren, $n!' WHERE `ID`=36441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 서로 편을 갈라 싸우지 않으리라.$b$b세나리온의 아이들은 영원하리라!', `MaleText_loc4`='我们绝不会再让我们之间的差异分裂我们。$b$b塞纳里奥之子万岁！', `MaleText_loc5`='我們永遠不再因為彼此的不同而被分裂。$b$b塞納里奧的孩子們將永垂不朽!', `MaleText_loc7`='Nunca más permitiremos que nos dividan nuestras diferencias.$b$b¡Larga vida a los hijos de Cenarion!' WHERE `ID`=36442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온의 축복이 이 땅과 마찬가지로 네게도 내리길, $r.', `MaleText_loc4`='愿塞纳里奥的祝福倾洒在你的身上，就如同他曾经对这片土地的赐福，$r。', `MaleText_loc5`='$r，願塞納里奧的祝福之雨降在你的身上，就像這片大地一樣。', `MaleText_loc7`='Que la bendición de Cenarion caiga sobre ti como ha caído sobre esta tierra, $r.' WHERE `ID`=36443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 파리, 가프로스트 지겹다. 이제 너 뼛속까지 얼어붙는다!', `MaleText_loc4`='加弗斯特厌倦了这些凡人。刺骨的寒风刮起来！', `MaleText_loc5`='加弗羅斯厭倦了弱小的凡人!現在要凍結你們的骨頭!', `MaleText_loc7`='Gargelus cansado de débiles mortales. ¡Ahora sus huesos helarse!' WHERE `ID`=36444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼 너무 약하다. 가프로스트 고쳐서... 너... 뭉갠다.', `MaleText_loc4`='斧子太弱了。看我弄好他，然后……然后砸扁你。', `MaleText_loc5`='斧頭太弱了。加弗羅斯要做得更好，然後把你粉碎!', `MaleText_loc7`='Hacha floja. Gargelus hacer mejor y... y...  APLASTARTE.' WHERE `ID`=36445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='접견을 기다리시오.', `FemaleText_loc4`='你必须要等候召见。', `FemaleText_loc5`='你必須等候覲見。', `FemaleText_loc7`='Debes esperar para conseguir una audiencia.' WHERE `ID`=36446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='텔드랏실에 발을 들이다니 뻔뻔하군, 명가의 일원이여. 그대의 족속은 여기서 환영받지 못하오. 우리는 고대의 전쟁도, 누구 때문에 그 일이 벌어졌는지도 기억하고 있소.', `FemaleText_loc4`='敢来泰达希尔证明你还有些许勇气，上层精灵。但这里不欢迎你。上古之战的伤痛和那些战争背后的企图让我们铭心刻骨。', `FemaleText_loc5`='到泰達希爾來讓你看起來有些緊張，精靈貴族。你的族類在此不受歡迎。我們未曾遺忘先祖之戰或是其後的策劃者。', `FemaleText_loc7`='Tienes mucha cara al venir a Teldrassil, Altonato. Tu gente no es bienvenida aquí. No hemos olvidado la Guerra de los Ancestros ni a las mentes que la planearon.' WHERE `ID`=36447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 그 실수가 되풀이되는 꼴은 보지 않겠소. 돌아가시오.', `FemaleText_loc4`='我们不应该再次犯错。回到你的流亡族人中去吧。', `FemaleText_loc5`='而我們也不會任由這些覆轍被重蹈。滾回你被流放的地方吧。', `FemaleText_loc7`='Y no queremos volver a ver esos errores repetidos. Regresa a tu exilio.' WHERE `ID`=36448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달샘을 그렇게 바라보지 마시오, 추방자여. 그 안에 담긴 힘은 당신을 위한 게 아니오.', `FemaleText_loc4`='不要死盯着这月亮井，流亡者。井水中的能量不属于你们。', `FemaleText_loc5`='少盯著月井看，被流放者。其中的力量不是你們配使用的。', `FemaleText_loc7`='Aparta la vista de la Poza de la Luna, exiliado. No puedes utilizar el poder que hay en su interior.' WHERE `ID`=36449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 배신을 되새겼소?', `FemaleText_loc4`='在回想你们的背叛吗？', `FemaleText_loc5`='回憶你們的背叛嗎?', `FemaleText_loc7`='¿Te recuerda tu traición?' WHERE `ID`=36450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋대로 떠들지 마시오, 명가의 일원이여.', `FemaleText_loc4`='小心点，上层精灵。', `FemaleText_loc5`='你最好安分點，精靈貴族。', `FemaleText_loc7`='Compórtate, Altonato.' WHERE `ID`=36451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 기다리시오.', `FemaleText_loc4`='等时机成熟吧。', `FemaleText_loc5`='剛好。', `FemaleText_loc7`='Cuando llegue el momento.' WHERE `ID`=36452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 거기 $n. 알아, 별것 없다는 거. 지금은 무역왕의 난파선이 집인 셈이니까.', `MaleText_loc4`='嗨，$n。我知道这挺糟的，但贸易大王的船骸暂时就是我们的家了。', `MaleText_loc5`='嗨，$n。我知道看起來不怎麼樣，但目前也只能將貿易親王的遊艇殘骸暫時當成家了。', `MaleText_loc7`='Hola, $n. Ya sé que no es mucho, pero los restos del Príncipe mercante son nuestro hogar por el momento.' WHERE `ID`=36453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $r님. 너무 놀라진 마세요. 당신의 언어로 이야기하고 있는 것 맞아요.$B$B평범한 랩터와 다름없던 제 지능은 여러 번의 실험을 거치면서 증폭되었습니다. 절 창조한 자들이 제게 붙인 "9번 실험체"란 이름으로 부르셔도 좋아요. 그들은 지금쯤 경황이 없거나 죽었겠죠. 혹시 절 좀 도와주실 수 있을까요?', `FemaleText_loc4`='你好，$r。请不要太惊讶。我确实是在用你的语言与你交谈。$B$B虽然身为迅猛龙，但我的智力已经通过一系列试验得到了大幅增强。你可以称我为“九号实验品”，这是我的创造者们不久以前给我取的名字。不过现在他们要么消失要么挂掉了。也许你能帮我个忙？', `FemaleText_loc5`='你好，$r。請不要大驚小怪，我是在用你們的語言在跟你說話。$B$B我原本的所擁有的迅猛龍智慧已經被一連串的實驗給增幅了。你可以稱我為「實驗體九號」，這是創造我的人最近贈與我的稱號，不過他現在不是在忙就是已經死了。或許你可以提供我一些幫助?', `FemaleText_loc7`='Saludos, $r. Por favor, no te alarmes. Es cierto que estoy hablándote en tu lengua nativa.$B$BMi considerable inteligencia de raptor ha sido aumentada gracias a una serie de experimentos. Puedes dirigirte a mí como "Sujeto Nueve", una identidad que recientemente me han otorgado mis creadores quienes, en estos momentos, están ocupados o fallecidos. Quizá puedas prestarme tu ayuda.' WHERE `ID`=36454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='향상된 인지 능력 덕분에, 전 제 종족 구성원들을 새로운 눈으로 바라볼 수 있게 됐어요. 그들은 자신의 힘을 대부분 신선한 먹이를 사냥하는 데 소모하고 있어요. 그래서 생각했죠. 왜 우리는 그 시간에 가축우리를 만들어 식량 공급 문제를 해결하지 않았을까?$B$B그러다 보니 자연스럽게 인간을 훌륭한 식자재로 쓸 수 있겠다는 생각에 이르렀어요. 빨리 자라는데다 살도 잘 찌고, 훈련을 시키면 수확 시기가 될 때까지 잡일을 시킬 수도 있을 텐데요. 흠...', `FemaleText_loc4`='随着我认知能力的增强，我开始审视我们这个种族。我们的大部分精力都被用于捕捉猎物。我在想，为什么我们不能用这些时间驯服并圈养这些猎物，让它们成为我们稳定的食物供给？$B$B我认为人类是很好的食物来源——很快就能被养肥，而且味道鲜美，还能够进行训练，代替我们完成畜牧工作。嗯……', `FemaleText_loc5`='我增長的認知能帶給了我智慧，讓我能為我們種族想出新的策略。我們大部份的精力都用在獵殺新鮮的食物，但我在想，我們為什麼不能將力氣花在研發馴養一批生物直接作為我們的食物補給呢?$B$B我很自然地想到人類一定是最適合作為糧食的生物。他們繁殖能力強，很簡單就能養胖，還可以在宰殺前訓練作為奴隸使用。嗯嗯。', `FemaleText_loc7`='Gracias al beneficio de mi capacidad cognitiva aumentada, puedo mirar con nuevos ojos al resto de mi raza. La mayor parte de nuestras energías se invertían en cazar presas nuevas. ¿Por qué, me pregunto, no hemos invertido ese tiempo en desarrollar un sistema para acumular animales domesticados a partir de los cual podríamos alimentarnos?' WHERE `ID`=36455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 차가운 접대가 그리 놀랍지는 않습니다. 우리는 오랫동안 숨어 지냈고, 그 탓에 동족과 오랜 시간 떨어져 있었죠.$b$b그런 시절은, 이제 지나갔습니다. 이 어린 나무의 주민들이 우리를 받아들이건 그렇지 않건, 명가는 다시 빛 속으로 돌아오고 있습니다. 그리고 우리는 자신이 누구인지 부정하지 않을 것입니다.', `MaleText_loc4`='我早知道我会受到这种冷遇。长久以来我们一直在隐居，因为我们必须要与族人分离。$b$b那段时间已经过去。不管这颗幼树之荫下的居民是否会接受我们，上层精灵们都要摒弃过去的身份，从黑暗中返回光明。', `MaleText_loc5`='我想我不應該對這樣冷淡的回應感到訝異。我們長久的躲藏並遠離自己的同胞是必要之舉。$b$b過去的那件事情，已成定局。不管這棵年輕樹木的居民是否接受我們，精靈貴族已經回到光明這一邊，而我們也不會否認自己的身分。', `MaleText_loc7`='Supongo que la fría bienvenida no debería sorprenderme. Llevamos tiempo escondiéndonos y la separación de nuestros hermanos fue necesaria.$B$BDe todos modos, ese tiempo ha pasado. Tanto si los habitantes de este joven árbol nos aceptan o no, los Altonato regresamos a la luz y no daremos la espalda a lo que somos.' WHERE `ID`=36456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 괜찮은 생각일까요?', `MaleText_loc4`='这真的是个好主意吗？', `MaleText_loc5`='這真的是個好主意嗎?', `MaleText_loc7`='¿Seguro que esto es una buena idea?' WHERE `ID`=36457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높이 높이 날아라!', `MaleText_loc4`='爬升，爬升，火箭分离！', `MaleText_loc5`='衝，衝，衝向蒼穹!', `MaleText_loc7`='¡A volar!', `FemaleText_loc1`='높이 높이 날아라!', `FemaleText_loc4`='爬升，爬升，火箭分离！', `FemaleText_loc5`='衝，衝，衝向蒼穹!', `FemaleText_loc7`='¡A volar!' WHERE `ID`=36458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 형제들이 길니아스 북부로 가는데 며칠이면 될 겁니다. 배만 고칠 수 있다면 말이죠.', `MaleText_loc4`='我的兄弟和我乘船几天时间就能到达北吉尔尼斯。当然，我们得先完成修理工作。', `MaleText_loc5`='我和我的兄弟們可以幾天內就搭船抵達北吉爾尼斯。但要等我們修理完畢。', `MaleText_loc7`='En cuestión de días mis hermanos y yo podremos llegar al norte de Gilneas en barco. En cuanto terminemos las reparaciones, claro.' WHERE `ID`=36459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 아주 대단한 고블린 같지? 모두를 구해내고 야만스러운 오크 놈들과 친해졌다고 말이야!', `MaleText_loc4`='你以为你是个超级英雄，能拯救所有人，还能和那些野蛮的兽人交朋友？', `MaleText_loc5`='你以為你很行，拯救了每個人，還跟這些野蠻的獸人交了朋友?', `MaleText_loc7`='¡¿Te crees mucho por salvar a todos y hacerte amigo de esos orcos salvajes?!' WHERE `ID`=36460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 뭉개버리겠어! 나는 무역왕이다! 바로 내가 무역왕이라고! 난 반드시 이 섬을 벗어나 아즈샤라의 왕이 되고 말겠어!', `MaleText_loc4`='我要毁掉你！我是贸易大王！我有个计划能让我离开这个岛，并成为艾萨拉之王！', `MaleText_loc5`='我會殺了你! 我是貿易親王!我! 我的計畫能讓我離開這個島，讓我成為艾薩拉之王!', `MaleText_loc7`='¡Te aplastaré! ¡Yo soy el Príncipe Mercante! ¡Yo! ¡Tengo un plan que me sacará de esta isla y me hará rey de Azshara!' WHERE `ID`=36461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑똑히 기억하라고! 곧 널 혼내 줄 테다! 너희 모두 혼내 줄 거야! 저리 비켜!', `MaleText_loc4`='记住我的话！我要干掉你，$n！我要把你们全都干掉！别挡我的道！', `MaleText_loc5`='記得我說的話!我會找上你的，$n!我會找上你們全部人! 別擋我的路!', `MaleText_loc7`='¡Recuérdalo! ¡Me vengaré! ¡De todos! ¡Fuera de mi camino!' WHERE `ID`=36462;
