UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 전쟁', `MaleText_loc4`='天灾战争', `MaleText_loc5`='天譴戰爭', `MaleText_loc7`='Guerra de la Plaga', `FemaleText_loc1`='스컬지 전쟁', `FemaleText_loc4`='天灾战争', `FemaleText_loc5`='天譴戰爭', `FemaleText_loc7`='Guerra de la Plaga' WHERE `ID`=36467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 내게 신경 쓸 것 없네. 난 그저 전령일 뿐이니까. 죽음추적자 무리의 지도자라면 이렇게 눈에 띄는 곳에 우두커니 서서 날 잡아 드슈 하고 있을 리가 없잖나. 굳이 역사를 반복할 필요는 없지.', `MaleText_loc4`='哦，别盯着我不放。我只是个传话儿的。死亡猎手的领袖当然不会蠢到亲自到这来送死。历史不会重演的。', `MaleText_loc5`='喔，別注意我。我只是個信差。亡靈哨兵的領袖肯定不會蠢到站在這個講台上等著傷心難過。不需要讓歷史重演。', `MaleText_loc7`='Oh, no me prestes atención. Solo soy el mensajero. El líder de los mortacechadores no sería tan estúpido como para estar aquí en el estrado esperando a que le destripen. No es necesario que esta historia se vuelva a repetir.' WHERE `ID`=36468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈수록 태산이군. 안 그래, $n?', `MaleText_loc4`='刚出油锅，又入烈火，是吗，$n？', `MaleText_loc5`='一波未平一波又起，對吧，$n?', `MaleText_loc7`='De mal en peor, ¿eh, $n?' WHERE `ID`=36469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈수록 태산이군. 안 그래, $n? 훈련이라도 필요해?', `MaleText_loc4`='刚出油锅又入烈火，是吗，$n？需要训练吗？', `MaleText_loc5`='一波未平一波又起，對吧，$n?需要任何的訓練嗎?', `MaleText_loc7`='De mal en peor, ¿eh, $n? ¿Necesitas instrucción?' WHERE `ID`=36470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지는 참고 기다렸어. 하지만, 그 로켓 투척기를 빨리 정상적으로 움직이게 하지 않으면 누군가에게 어둠의 화살을 날릴 거야!', `MaleText_loc4`='我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！', `MaleText_loc5`='我已經很有耐心了，但如果他們再不把那彈弓火箭弄好，我就要用暗影箭射人了!', `MaleText_loc7`='He sido paciente hasta ahora, ¡pero si no consiguen que ese lanzador de cohetes funcione pronto, voy a lanzarle una descarga de las sombras a alguien!' WHERE `ID`=36471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지는 참고 기다렸어. 하지만, 그 로켓 투척기를 빨리 정상적으로 움직이게 하지 않으면 누군가에게 어둠의 화살을 날릴 거야!$B$B$n, 훈련해야 한다고?', `MaleText_loc4`='我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！$B$B需要训练吗，$n？', `MaleText_loc5`='我已經很有耐心了，但如果他們再不把那彈弓火箭弄好，我就要用暗影箭射人了!$B$B需要訓練嗎，$n?', `MaleText_loc7`='He sido paciente hasta ahora, ¡pero si no consiguen que ese lanzador de cohetes funcione pronto, voy a lanzarle una descarga de las sombras a alguien!$B$B¿Necesitas instrucción, $n?' WHERE `ID`=36472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='댐윅이 그걸 타고 건너가는 걸 봤지. 나 같으면 저속 낙하 마법을 썼을 거야, 아직 하는 법은 모르지만.', `MaleText_loc4`='我看见戴姆维克骑过这东西。所以我宁可使用缓落术。不过我还不知道这法术该怎么用。', `MaleText_loc5`='我看到唐威克騎著那個東西過去。我寧願使用緩落術，但我還沒學會。', `MaleText_loc7`='Vi a Mechamojada montado en esa cosa. Me gustaría utilizar un hechizo de Caída lenta, pero no lo conozco todavía.' WHERE `ID`=36473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='댐윅이 그걸 타고 건너가는 걸 봤지. 나 같으면 저속 낙하 마법을 썼을 거야, 아직 하는 법은 모르지만.$B$B훈련을 받고 싶다고, $n?', `MaleText_loc4`='我看见戴姆维克骑过这东西。所以我宁可使用缓落术。不过我还不知道这法术该怎么用。$B$B想要训练吗，$n？', `MaleText_loc5`='我看到唐威克騎著那個東西過去。我寧願使用緩落術，但我還沒學會。$B$B需要些訓練嗎，$n?', `MaleText_loc7`='Vi a Mechamojada montado en esa cosa. Me gustaría utilizar un hechizo de Caída lenta, pero no lo conozco todavía.$B$B¿Quieres instrucción, $n?' WHERE `ID`=36474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어, $n! 전부 다 재미있지? 다음 섬에서는 어떤 일이 일어날지 궁금하다니까?', `MaleText_loc4`='干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？', `MaleText_loc5`='幹得好，$n!這一切真是太令人興奮了!我在想下一座島會是什麼樣子?', `MaleText_loc7`='¡Buen trabajo, $n! ¿No te parece emocionante? Me pregunto cómo será la siguiente isla.' WHERE `ID`=36475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어, $n! 전부 다 재미있지? 다음 섬에서는 어떤 일이 일어날지 궁금하다니까?$B$B무언가 새로운 거 가르쳐줄까?', `MaleText_loc4`='干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？$B$B我能教你些新东西吗？', `MaleText_loc5`='幹得好，$n!這一切真是太令人興奮了!我在想下一座島會是什麼樣子?$B$B你需要我教你什麼新花招嗎?', `MaleText_loc7`='¡Buen trabajo, $n! ¿No te parece emocionante? Me pregunto cómo será la siguiente isla.$B$B¿Puedo enseñarte algo nuevo?' WHERE `ID`=36476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄청난 모험을 하고 오셨나 봐요, $n 님. 저 얼라이언스 놈들은 돈이 엄청나게 많을 거예요.', `FemaleText_loc4`='看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。', `FemaleText_loc5`='聽起來你經歷了一場大冒險，$n。那些聯盟蟲子身上一定有不少的金幣。', `FemaleText_loc7`='Parece que has vivido toda una aventura, $n. Esos pánfilos de la Alianza debían de traer los bolsillos llenos de pasta.' WHERE `ID`=36477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄청난 모험을 하고 오셨나 봐요, $n 님. 저 얼라이언스 놈들은 돈이 엄청나게 많을 거예요.$B$B돈을 약간 내고 훈련을 받고 싶지는 않으세요?', `FemaleText_loc4`='看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。$B$B想要进行训练吗？', `FemaleText_loc5`='聽起來你經歷了一場大冒險，$n。那些聯盟蟲子身上一定有不少的金幣。$B$B想付錢接受一些訓練嗎?', `FemaleText_loc7`='Parece que has vivido toda una aventura, $n. Esos pánfilos de la Alianza debían de traer los bolsillos llenos de pasta.$b$b¿Quieres comprar algo de instrucción?' WHERE `ID`=36478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 거기 $n 님. 제가 말이에요. 그 지긋지긋한 원숭이를 떼어낼 수 있어서 얼마나 기쁜지 몰라요!', `FemaleText_loc4`='嗨，$n。我很高兴能远离那些该死的猴子！', `FemaleText_loc5`='你好，$n。我自己非常高興能遠離那些猴子。', `FemaleText_loc7`='Hola, $n. No sé tú, ¡pero yo me alegro de estar lejos de esos malditos monos!' WHERE `ID`=36479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 거기 $n 님. 제가 말이에요. 그 지긋지긋한 원숭이를 떼어낼 수 있어서 얼마나 기쁜지 몰라요!$B$B그러니까, 훈련을 조금 받아서 기술을 연마하고 싶다 이거죠?', `FemaleText_loc4`='嗨，$n。我很高兴能远离那些该死的猴子！$B$B那么，想要对你的技艺进行一些磨砺么？', `FemaleText_loc5`='呦，$n。我自己對於能夠擺脫那些死猴子非常的高興!$B$B所以，你想要接受一下訓練來磨練自己的技術嗎?', `FemaleText_loc7`='Hola, $n. No sé tú, ¡pero yo me alegro de estar lejos de esos malditos monos!$b$bQué, ¿quieres mejorar tus habilidades con un poco de instrucción?' WHERE `ID`=36480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01은 현재 미작동 상태입니다.', `MaleText_loc4`='全能战士NX-01型当前处于离线状态。', `MaleText_loc5`='自動戰士NX-01目前離線中。', `MaleText_loc7`='Guerreromática NX-01 desconectada.' WHERE `ID`=36481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01 작동 개시.$B$B훈련을 받으려면 동전을 넣어 주십시오.', `MaleText_loc4`='全能战士NX-01型在线。$B$B请塞入硬币，接受训练。', `MaleText_loc5`='自動戰士NX-01已上線。$B$B請投幣進行訓練。', `MaleText_loc7`='Guerreromática NX-01 conectada.$B$BPor favor, inserte monedas para recibir instrucción.' WHERE `ID`=36482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어설픈 $r 녀석의 소환인가? 믿을 수 없군. 갈 데까지 갔거나 바보인 게지. 이것이 네 마지막 실수가 될 거다.', `MaleText_loc4`='我被一个$r给召唤出来了？真是难以置信。无论是出于绝望还是愚蠢，这都将是你最后的错误。', `MaleText_loc5`='不小心被一個$r召喚出來的?難以相信。不管是愚蠢還是太過於心急，這都將會是你最後一次犯錯。', `MaleText_loc7`='¿Invocado por un torpe $r? Increíble. Bien estés desesperado o seas idiota este será tu último error.' WHERE `ID`=36483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 맥주를 마시더니 잠시 주체할 수 없다는 듯 몸을 부르르 떱니다.', `MaleText_loc4`='%s喝了一口他酿的酒，禁不住打了几个哆嗦。', `MaleText_loc5`='%s喝了一口酒後失去控制地顫抖了一會。', `MaleText_loc7`='%s se toma una bebida de su propia cosecha y tiembla incontrolablemente durante unos segundos.' WHERE `ID`=36484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이거야! 잠이 확 깼어. 맛있군!', `MaleText_loc4`='我要的就是这个！现在我完全清醒了！太美味了！', `MaleText_loc5`='就是這樣!完全清醒了，真好喝!', `MaleText_loc7`='¡Esto sí que está bueno! Ahora estoy despierto del todo. ¡Sabroso!' WHERE `ID`=36485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 협력 관계가 지속적으로 발전하는 게 얼마나 기쁜지 모르겠어요, $n 님. 제 인지 능력이 놀라울 정도로 발달한 뒤 몇 주가 지나자, 고블린 후원자들은 그들을 뛰어넘는 제 지능에 대해 불안해했고, 명백하게 불신하는 듯한 태도까지 보였거든요.$B$B제 창조자들이 최근의 이러한 점진적인 산업 재해를 막을 수 없었다는 사실이 무척 안타깝군요. 덕분에 제가 아무 방해 없이 움직일 수 있잖아요...', `FemaleText_loc4`='我要再重申一次，$n，我们之间工作关系的发展实在是令我感到高兴。在我的心智得到大幅度提升之后的几个星期里，我的地精恩人们开始了解到我的智力已经超越了他们。虽然他们仍然对此深表怀疑。$B$B很遗憾，正是由于我的祖先没能阻止最近这一系列的工业化“事件”，现在的我才能变得如此无所不能……', `FemaleText_loc5`='我想要再次重申我對我們工作上持續發展的合作關係感到非常的高興，$n。在我驚人的認知能力強化後的幾週，或許是因為我的智慧成長已經超越了他們，我的恩人哥布林們開始遠離我，對我產生不了信任感。$B$B真可惜，創造我的人無法阻止最近這一連串的工業「危機」讓我現在可以毫無阻礙的活動...', `FemaleText_loc7`='Me gustaría reiterar mi satisfacción con el desarrollo de nuestra relación de trabajo, $n. Durante las semanas posteriores a mi apabullante crecimiento cognitivo, mis benefactores goblin se volvieron recelosos, quizá incluso desconfiados, a medida que mi intelecto eclipsaba el suyo.$b$bQué lástima que mis progenitores fueran incapaces de prevenir esta reciente oleada de "accidentes" industriales gracias a la cual puedo actuar ahora con tanta impunidad...' WHERE `ID`=36486;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예쁘고 사랑스러운 내 아이들!', `FemaleText_loc4`='我的心肝宝贝！', `FemaleText_loc5`='我迷人，可愛的後代!', `FemaleText_loc7`='¡Mi dulce y adorable progenie!' WHERE `ID`=36487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 상처가 치유되기 시작합니다.', `MaleText_loc4`='%s的伤口开始愈合了。', `MaleText_loc5`='%s的傷口開始癒合。', `MaleText_loc7`='Las heridas de %s comienzan a sanar.' WHERE `ID`=36488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 아제로스. 저는 대격변으로 파괴되고 쓰레기로 뒤덮인 이 세상을 떠나렵니다.', `FemaleText_loc4`='永别了，艾泽拉斯。我离开了一个在大灾变中被污损毁坏的世界。', `FemaleText_loc5`='再見了，艾澤拉斯，我將離開這個受到污染和大災變侵蝕的世界。', `FemaleText_loc7`='Adiós, Azeroth. Dejo atrás un mundo impuro y sacudido por un cataclismo.' WHERE `ID`=36489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 불을 붙일 시간이에요!', `FemaleText_loc4`='让我们点亮这根蜡烛！', `FemaleText_loc5`='讓我們點燃這根蠟燭!', `FemaleText_loc7`='¡Vamos a encender esta vela!' WHERE `ID`=36490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 네 머리가 이 우월한 발톱의 상대가 될 것 같으냐!', `MaleText_loc4`='你渺小的智力根本无法和我超强的爪子相比！', `MaleText_loc5`='你低下的智慧不是我高等利爪的對手!', `MaleText_loc7`='¡Tu minúsculo intelecto no tiene nada que hacer contra mis garras superiores!' WHERE `ID`=36491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 영양식이군!', `MaleText_loc4`='啊，新鲜的食物！', `MaleText_loc5`='啊，新鮮的食物!', `MaleText_loc7`='¡Ah, sustento fresco!' WHERE `ID`=36492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r... 오늘은 너를, 내일은 세상을 엎어버리겠다!', `MaleText_loc4`='首先是你，$r。明天就是整个世界！', `MaleText_loc5`='先是你，$r，明天就是整個世界!', `MaleText_loc7`='Primero tú, $r. Mañana: ¡el mundo!' WHERE `ID`=36493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 들었겠죠, 클럽니크? 멘나르 호수를 지키다 전사한 이들은 영웅입니다. 그들의 이타적인 행동이 세상을 구했다고요! 그분들을 위해 비석을 세워야 해요.', `FemaleText_loc4`='克拉伯尼克，你听到了吗？那些在门纳尔湖保卫战中牺牲的战士都是英雄。他们的无私也许拯救了全世界！我们应当郑重地纪念他们。', `FemaleText_loc5`='你聽到了嗎，棒柄?那些犧牲了自己保護門納爾湖的人們是英雄。他們無私的舉動甚至可能可能救了這整個世界!這是我們不可忘記的壯舉。', `FemaleText_loc7`='¿Has oído, Clubnik? Aquellos que murieron defendiendo el Lago Mennar son héroes. ¡Sus acciones desinteresadas podrían haber salvado el mundo entero! Debería construirse un monumento.' WHERE `ID`=36494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='클럽니크? 그냥 불 구덩이에 빠져 죽어버려요.', `FemaleText_loc4`='克拉伯尼克？我希望你死了。被烈火烧成灰烬。', `FemaleText_loc5`='棒柄?我希望你會不得好死。', `FemaleText_loc7`='¿Clubnik? Espero que te mueras. En un incendio.' WHERE `ID`=36495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몰론 다 들었다고.', `MaleText_loc4`='我听到你说话了。', `MaleText_loc5`='當然，我聽到了。', `MaleText_loc7`='Claro, estoy de acuerdo.' WHERE `ID`=36496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 연료 보급소 기념비는 어때?', `MaleText_loc4`='用一座燃料仓库……纪念他们……如何？', `MaleText_loc5`='不然來建一個...紀念性的燃料儲藏所怎樣?', `MaleText_loc7`='¿Qué tal... una gasolinera conmemorativa?' WHERE `ID`=36497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 멋지잖아!', `MaleText_loc4`='那一定非常不错！', `MaleText_loc5`='會很棒的!', `MaleText_loc7`='¡Tendrá mucha clase!' WHERE `ID`=36498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 바보 같으니!', `MaleText_loc4`='沉默吧，蠢货！', `MaleText_loc5`='安靜，蠢蛋!', `MaleText_loc7`='¡Cállate, loco!' WHERE `ID`=36499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 바보 같으니!', `MaleText_loc4`='我同情愚者！', `MaleText_loc5`='我同情蠢蛋!', `MaleText_loc7`='¡He dicho que yo ahí no subo!' WHERE `ID`=36500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 화나게 하지 마라!', `MaleText_loc4`='不要激怒我！', `MaleText_loc5`='別惹我生氣!', `MaleText_loc7`='¡No me enfades!' WHERE `ID`=36501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소라타의 옷에 코를 대고 냄새를 맡으며 킁킁댑니다.', `MaleText_loc4`='%s嗅着索拉塔的衣服，发出沉重的鼻息声。', `MaleText_loc5`='%s聞了索拉塔的衣服後用力的吐了口氣。', `MaleText_loc7`='%s gruñe ruidosamente mientras olisquea y mordisquea la ropa de Sorata.' WHERE `ID`=36502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛에 찬양을, $n $g형제:자매;! 어디 보자...', `MaleText_loc4`='赞美圣光，$n$g兄弟:姐妹;！让我们好好看看……', `MaleText_loc5`='讚揚聖光，$n$g兄弟:姐妹; !讓我們看一下這裡...', `MaleText_loc7`='¡Alabada sea la Luz, $ghermano:hermana; $n! Echemos un vistazo...' WHERE `ID`=36503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 바로 저게 문제구먼! 기계 안에 유령이 씌어 있어.', `MaleText_loc4`='嗯，找到问题了！这部机器里有个被我们称为鬼魂的家伙需要你对付。', `MaleText_loc5`='嗯，那是你的問題!你有我們稱之為機械中的鬼魂的東西。', `MaleText_loc7`='¡Bueno, ahí está tu problema! Tienes lo que solemos llamar un fantasma en la máquina.' WHERE `ID`=36504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전통적인 퇴마 의식이 필요해! 유령이 날뛸 수도 있으니 날 좀 도와주겠어?', `MaleText_loc4`='这需要一场老式的推土机驱魔仪式！如果她不服从管束，就请帮我一下，可以吗？', `MaleText_loc5`='需要的是一個傳統的推土機驅邪儀式!如果她太興奮的話就幫我一把，可以嗎?', `MaleText_loc7`='¡Esto requiere un exorcismo de bulldozer de los de toda la vida! Si se pone chula, échame una mano, ¿vale?' WHERE `ID`=36505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 여기 살아 있는 게 하나 있군!', `MaleText_loc4`='喔！我们搞到了一个活的！', `MaleText_loc5`='哇!我們這裡有活著的!', `MaleText_loc7`='¡Guau! ¡Aquí hay uno vivo!' WHERE `ID`=36506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라질 것을 명하노니! 부정한 영혼이여, 물러가라!', `MaleText_loc4`='我将驱逐你！不洁的灵魂……离开这里！', `MaleText_loc5`='被淨化吧!污穢的靈魂，消失吧!', `MaleText_loc7`='¡Yo te expulso! ¡Espíritu impuro! ¡Fuera!' WHERE `ID`=36507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 기계에 굴복할지어다! 강력한 기계에 굴복할지어다!', `MaleText_loc4`='强大的工具压迫你！强大的工具压迫你！', `MaleText_loc5`='能量工具將驅散你!能量工具將驅散你!', `MaleText_loc7`='¡Las herramientas de poder te lo ordenan! ¡Las herramientas de poder te lo ordenan!' WHERE `ID`=36508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 불꽃으로 널 정화하노라!', `MaleText_loc4`='神圣之火将净化你！', `MaleText_loc5`='我以神聖之火將你淨化!', `MaleText_loc7`='¡Yo te purifico con fuego bendito!' WHERE `ID`=36509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 고블린!', `MaleText_loc4`='死吧，地精！', `MaleText_loc5`='死吧，哥布林!', `MaleText_loc7`='¡Muere, goblin!', `FemaleText_loc1`='죽어라, 고블린!', `FemaleText_loc4`='死吧，地精！', `FemaleText_loc5`='死吧，哥布林!', `FemaleText_loc7`='¡Muere, goblin!' WHERE `ID`=36510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 아주 깔끔하게 잘 처리됐군.', `MaleText_loc4`='干得好！一切顺利。', `MaleText_loc5`='太棒了!它被驅逐地一乾二淨了。', `MaleText_loc7`='¡Estupendo! Todo ha salido a pedir de boca.' WHERE `ID`=36511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클럽니크에게 사제회가 청구서를 발송할 거라고 전해줘. 성스러운 빛을 위하여!', `MaleText_loc4`='让克拉伯尼克知道，牧师教会的账单随后就到。为了圣光！', `MaleText_loc5`='讓棒柄知道教團將會寄給他一份帳單。為了聖光!', `MaleText_loc7`='Dile a Clubnik que el sacerdocio le enviará la factura. ¡Por la Luz!' WHERE `ID`=36512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 내가 누구고 여기서 뭘 하고 있는지 또 잊어버렸어. 필요한 일이 생기면 날 부르라고.', `MaleText_loc4`='嗯，我又一次忘记了自己是谁，正在这里做什么。如果出了什么事，就来叫我吧。', `MaleText_loc5`='嗯...我又再次的忘了我是誰和在這做什麼了。如果發生什麼事就叫我回來。', `MaleText_loc7`='Mmmm, una vez más he olvidado quién soy y qué hago aquí. Llámame si descubres algo.' WHERE `ID`=36513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 나 좀 도와주지 않겠어?', `MaleText_loc4`='唔……有人能帮帮我吗？', `MaleText_loc5`='我...呃...需要一點幫忙?', `MaleText_loc7`='Yo, eh, me vendría bien una mano aquí.' WHERE `ID`=36514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험용 텍스트', `MaleText_loc4`='啊，这是个测试。', `MaleText_loc5`='<喘氣>這是一項測驗!', `MaleText_loc7`='GASP, THIS IS A TEST' WHERE `ID`=36515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티에서 찾아봐야 할 걸세. 여기 남쪽에 있는 로데론의 폐허에 가면, 아래로 내려가는 승강기가 있지. 일단 거기 간 다음, 언더시티 수호병에게 다시 한 번 길을 묻게.', `MaleText_loc4`='你会想看看幽暗城的模样。它就坐落在南边的旧洛丹伦废墟，你会找到一个下行的升降梯。等你到了，幽暗城的卫兵会给你更详细的指引。', `MaleText_loc5`='你會想看看幽暗城的。在此地的南方，羅德隆廢墟，你會找到一個往下的升降梯。一旦你到了那邊，你可以詢問幽暗城守護者進一步的方位。', `MaleText_loc7`='Deberías buscar en Entrañas. En las antiguas ruinas de Lordaeron, al sur de este lugar, encontrarás un elevador que baja. Cuando estés allí, pide a un guardián de Entrañas que te diga cómo llegar.', `FemaleText_loc1`='언더시티에서 찾아봐야 할 걸세. 여기 남쪽에 있는 로데론의 폐허에 가면, 아래로 내려가는 승강기가 있지. 일단 거기 간 다음, 언더시티 수호병에게 다시 한 번 길을 묻게.', `FemaleText_loc4`='你会想看看幽暗城的模样。它就坐落在南边的旧洛丹伦废墟，你会找到一个下行的升降梯。等你到了，幽暗城的卫兵会给你更详细的指引。', `FemaleText_loc5`='你會想看看幽暗城的。在此地的南方，羅德隆廢墟，你會找到一個往下的升降梯。一旦你到了那邊，你可以詢問幽暗城守護者進一步的方位。', `FemaleText_loc7`='Deberías buscar en Entrañas. En las antiguas ruinas de Lordaeron, al sur de este lugar, encontrarás un elevador que baja. Cuando estés allí, pide a un guardián de Entrañas que te diga cómo llegar.' WHERE `ID`=36516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적외선 열 초점기를 써야 합니다!', `MaleText_loc4`='使用你的红外感温眼镜！', `MaleText_loc5`='使用你的紅外線熱能聚焦裝置!', `MaleText_loc7`='¡Utiliza tus lentes focales infrarrojas!' WHERE `ID`=36517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 절벽으로 가서 정찰병 브락스를 만나게.', `MaleText_loc4`='你需要到那片悬崖去，找到斥候布拉克斯，$n。', `MaleText_loc5`='你必須到懸崖和斥候布拉克斯那去，$n。', `MaleText_loc7`='Tiene que ir a los acantilados a ver al explorador Brax, $n.' WHERE `ID`=36518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬라그, 절벽으로 갈 수 있게 길들인 정글표범을 빌려주십시오.', `MaleText_loc4`='我需要借你驯服的丛林豹去悬崖，基拉格。', `MaleText_loc5`='我需要借你馴服好的叢林山貓到懸崖那去，奇拉格。', `MaleText_loc7`='Kilag, necesito llevarme prestada tu gata selvática domesticada para llegar a los acantilados.', `FemaleText_loc1`='킬라그, 절벽으로 갈 수 있게 길들인 정글표범을 빌려주세요.', `FemaleText_loc4`='我需要借你驯服的丛林豹去悬崖，基拉格。', `FemaleText_loc5`='我需要借你馴服好的叢林山貓到懸崖那去，奇拉格。', `FemaleText_loc7`='Kilag, necesito llevarme prestada tu gata selvática domesticada para llegar a los acantilados.' WHERE `ID`=36519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자마이트에 관해 전부 생각나게 해 주십시오.', `MaleText_loc4`='帮我回忆一下有关卡亚矿的知识。', `MaleText_loc5`='再跟我說一下跟卡迦邁有關所有的事。', `MaleText_loc7`='Refréscame la memoria sobre todo eso de la kaja''mita.', `FemaleText_loc1`='카자마이트에 관해 전부 생각나게 해 주세요.', `FemaleText_loc4`='帮我回忆一下有关卡亚矿的知识。', `FemaleText_loc5`='再跟我說一下跟卡迦邁有關所有的事。', `FemaleText_loc7`='Refréscame la memoria sobre todo eso de la kaja''mita.' WHERE `ID`=36520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자마이트란... 알겠지만, 전설 속의 그 물건 덕분에 고블린 종족 전체가 연금술과 기계공학 분야에서 궁극의 대가로 발전할 수 있었다지?!$B$B그 때문에 우리는 압제하던 정글 트롤을 거꾸러뜨리고 케잔을 다스릴 수 있었어. 케잔이 영원히 평안하길. 존재하는 모든 것 중에 가장 값진 광석이란 말이야!$B$B이봐, 이 원숭이들에게 어떤 영향이 있는 것 같지 않아? 안 그래?', `MaleText_loc4`='卡亚矿……你是否知道，就是这种传说中的玩意儿，帮助地精全族成为了炼金术和工程学的究极大师？！$B$B正是这种材料帮助我们推翻了压迫我们的丛林巨魔，控制了科赞——愿她得到安息——它是最珍贵的矿石！$B$B嗨，你不会是认为卡亚矿石对那些猴子也起了作用吧？', `MaleText_loc5`='卡迦邁...那個傳說中幫助哥布林這個種族進化成為鍊金術和工程學大師的東西?!$B$B是它幫助我們脫離了叢林食人妖的統治，占領凱贊<願她安祥>，還是世界上最有價值的礦石!$B$B喂，你該不會認為那些猴子也受到影響了吧?', `MaleText_loc7`='Kaja''mita... Ya sabes, la materia que dicen las leyendas que ayudó a toda la raza goblin a evolucionar hasta convertirla en cuna de maestros de la alquimia y la ingeniería.$B$B¡Es la materia que nos ayudó a derrocar a nuestros opresores trols de la jungla, a tomar el control de Kezan, que descanse en paz; y es el mineral más valioso de toda la existencia!$B$BOye, ¿no crees que también está surtiendo algún tipo de efecto en esos monos?' WHERE `ID`=36521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역에 흩어진 폐허는 한때 번영했던 나이트 엘프 문명의 유물입니다. 비전 마법을 연구하는 자들에겐 귀중한 정보가 담긴 보물이지요.$B$B그래서 가장 비범한 나이트 엘프 마법사 무리가 관심을 보이기 시작했습니다. 맞아요, $r. 나이트 엘프는 자신들의 마법 유산을 되찾으려 합니다! 그들이 여기서 값진 물건을 찾아낼 끔찍한 가능성만 없더라도 재미있게 지켜볼 수 있을 텐데 말이죠.', `MaleText_loc4`='散布在这一地区的废墟是暗夜精灵文明发展到顶峰时期留下的遗迹。对于研究奥术的人来说，它们是蕴含着无数珍贵信息的宝藏。$B$B看样子，一队最不同寻常的暗夜精灵法师已经注意到了它们。是的，听我说，$r——暗夜精灵要取回他们的魔法遗产！如果他们在这里发现了有价值的东西，很可能会导致可怕的后果。除此之外，我倒是觉得他们的举动很有些意思。', `MaleText_loc5`='散佈於此區的廢墟是夜精靈文明達到最高峰時的遺蹟。它們對那些研究秘法奧秘的人們來說是知識的寶庫。$B$B看來它現在也吸引了一群稀有的夜精法師。你沒聽錯，$r，夜精靈想要拿回他們的魔法遺產!我非常好奇他們能在這找到什麼有價值的東西，但也對那所帶來的潛在危機感到擔憂。', `MaleText_loc7`='Las ruinas diseminadas por esta zona son restos de la civilización de los elfos de la noche, de su época de mayor esplendor. Son una fuente de información de valor incalculable para aquellos que estudian lo arcano.$B$BY, al parecer, han atraído la atención de una serie de extraños grupos de elfos de la noche magos. Sí, me has oído bien, $r, ¡los elfos de la noche están intentando recuperar su pasado como magos! Lo encontraría muy gracioso si no fuera por las terribles consecuencias que acarrearía si encontraran algo valioso ahí.' WHERE `ID`=36522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프 마법사라니, 푸하!', `MaleText_loc4`='暗夜精灵法师，呸！', `MaleText_loc5`='夜精靈法師。呿!', `MaleText_loc7`='Magos elfos de la noche. Bah.' WHERE `ID`=36523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 더할 영혼이 또 오셨군요!', `MaleText_loc4`='需要更多的灵魂为引擎提供能量！', `MaleText_loc5`='更多的靈魂來替引擎充能!', `MaleText_loc7`='¡Más almas para alimentar el motor!' WHERE `ID`=36524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 영혼을 당신께 바칩니다, 주인님.', `MaleText_loc4`='我的灵魂属于您，主人。', `MaleText_loc5`='我的靈魂獻給你，主人。', `MaleText_loc7`='Mi alma por ti, maestro.' WHERE `ID`=36525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 소용돌이가 손짓하지 않습니까?', `MaleText_loc4`='死亡的漩涡在召唤你！', `MaleText_loc5`='獲取靈魂的漩渦召喚你!', `MaleText_loc7`='¡El vórtice de la destrucción te llama!' WHERE `ID`=36526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<피조물의 목소리가 주변 공기로부터 뿜어져 나오며 귀에서 울려 온몸에 소름이 돋는 듯합니다. 피조물은 당신이 이해할 수 없는 언어로, 마치 여러 사람이 한 번에 말하는 듯한 목소리로 이야기합니다.>', `MaleText_loc4`='<奥术构造体的“声音”似乎在你周围四面八方同时响起，撕扯你的耳膜，让你寒毛倒竖。这个构造体在用一种你听不懂的语言和你说话。就好象有多个话音叠加在一起，同时传入你的耳朵。>', `MaleText_loc5`='<傀儡的「聲音」似乎是從周圍的空氣所發出來的，聲音傳到你的耳中使你手臂上的汗毛豎立。傀儡使用了你不懂的語言與你交談，聽起來就像是多個聲音同時在說話。>', `MaleText_loc7`='<La "voz" del ensamblaje parece emanar del aire que te rodea y zumba en tus oídos mientras los pelos se te ponen de punta. El ensamblaje te habla en una lengua que no puedes comprender, con palabras que suenan como múltiples voces hablando a la vez.>' WHERE `ID`=36527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음...알테스...락 톨가르? 라고 했나.', `MaleText_loc4`='Um... Al''teth ... la c''tolgar？还是其它什么。', `MaleText_loc5`='嗯...歐鐵斯...拉托加爾?之類的。', `MaleText_loc7`='Ehm... ¿Al''teth ... la c''tolgar? O algo.', `FemaleText_loc1`='음...알테스...락 톨가르? 라고 했나.', `FemaleText_loc4`='Um... Al''teth ... la c''tolgar？还是其它什么。', `FemaleText_loc5`='嗯...歐鐵斯...拉托加爾?之類的。', `FemaleText_loc7`='Ehm... ¿Al''teth ... la c''tolgar? O algo.' WHERE `ID`=36528;
