UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주체할 수 없는 비전 마력으로 소용돌이칩니다.', `MaleText_loc4`='%s体内充满了无法控制的魔法能量。', `MaleText_loc5`='%s充斥著失控的秘法能量。', `MaleText_loc7`='El %s crece con energías arcanas incontroladas.' WHERE `ID`=36535;
