UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 $r|1은;는; 여기서 뭘 하는 거지?', `MaleText_loc4`='那个$r在这里干什么？', `MaleText_loc5`='那個$r在這做什麼!?', `MaleText_loc7`='¿Qué está haciendo ese $r aquí?', `FemaleText_loc1`='저 $r|1은;는; 여기서 뭘 하는 거지?', `FemaleText_loc4`='那个$r在这里干什么？', `FemaleText_loc5`='那個$r在這做什麼!?', `FemaleText_loc7`='¿Qué está haciendo ese $r aquí?' WHERE `ID`=36540;
