UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기즈모, 거기 멍하니 앉아서 뭐 하는 거야? 옆에 누워있는 게 누군지 모르겠어?!', `MaleText_loc4`='发明家，你干嘛楞在那儿？难道你不知道身边的是谁吗？', `MaleText_loc5`='齒輪，你坐在那邊做什麼?你認不出來是誰躺在你旁邊嗎?', `MaleText_loc7`='Trasto, ¿qué haces ahí sentado? ¡¿Es que no ves quién yace a tu lado?!' WHERE `ID`=36543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그 $n|1이야;야;! 우리가 케잔에서 바삭바삭 튀겨지지 않고 아직 숨이 붙어 있는 건 다 $n 덕분이라고.', `MaleText_loc4`='那是$n！正是因为$G他:她;，我们才能继续在这里呼吸，而不是在科赞变成碎片。', `MaleText_loc5`='那是$n!多虧了$G他:她;，我們現在還能呼吸，沒在凱贊被炸成脆餅。', `MaleText_loc7`='¡Es $n! ¡$GÉl:Ella; es la razón de que en Kezan sigamos respirando y no seamos un puñado de bichos bien fritos!' WHERE `ID`=36544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서, 전기충격을 줘서 되살려 볼 테니! 점퍼 케이블이 젖어서 우리까지 감전사하지만 않길 바랄 뿐이야!', `MaleText_loc4`='后退，我要让$g他:她;活过来！希望浸水的起搏器不会把我们都杀死！', `MaleText_loc5`='後退點，我要給$G他:她;施行心肺電擊術!希望這些濕掉的起搏器不會把我們全都烤焦!', `MaleText_loc7`='¡Atrás, voy a $gresucitarlo:resucitarla;! ¡Espero que estos desfibriladores mojados no nos maten a todos!' WHERE `ID`=36545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간다! 실시!', `MaleText_loc4`='拜托！快醒过来！', `MaleText_loc5`='可以了!開始!', `MaleText_loc7`='¡Venga! ¡Despeja!' WHERE `ID`=36546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 할 수 있는 일은 다 했어. 이제 $n에게 달렸지. 내 말 들려, $n? 정신 차려! 빛을 따라가지는 말라고!', `MaleText_loc4`='我能做的都做了。现在就要看$g他:她;自己了。听到我的话了吗，$n？来吧，振作起来！现在还不是去见圣光的时候！', `MaleText_loc5`='我盡力了，現在就要看$g他:她;自己了。聽的到嗎，$n?振作一點!別走進光裡!', `MaleText_loc7`='Eso es todo lo que puedo hacer. Ahora todo depende de $gél:ella;. ¿Me has oído, $n? ¡Venga, despierta! ¡No vayas hacia la luz!' WHERE `ID`=36547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올바른 선택을 한 거야. 우리 모두 자네한테 엄청난 신세를 졌어, $n. 여기서 까딱하다가는 죽을 수 있으니 조심하라고.', `MaleText_loc4`='你做出了正确的选择。我们全都深深地感谢你，$n。但不要让自己的生命遭受危险。', `MaleText_loc5`='你的選擇是正確的。我們全都欠了你一個大人情，$n。好好注意自己的安全啊!', `MaleText_loc7`='Has hecho la elección correcta. Te debemos mucho, $n. Intenta que no te maten.' WHERE `ID`=36548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌봐야 할 생존자가 더 있어. 해변에서 보자고.', `MaleText_loc4`='还有许多幸存者需要救治。我们海滩上再见吧。', `MaleText_loc5`='還有更多的生還者需要幫助，待會兒岸上見。', `MaleText_loc7`='Tengo que atender a más supervivientes. Te veré en la orilla.' WHERE `ID`=36549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빠른 속도로 지뢰를 만들어냅니다!', `MaleText_loc4`='%s开始不断召唤出炸雷！', `MaleText_loc5`='%s開始迅速地召喚爆裂地雷!', `MaleText_loc7`='¡%s comienza a invocar minas explosivas!' WHERE `ID`=36550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이봐!$B$B''손바닥 열 치료법''을 전수받고 싶은가?$B$B아니라고? 붕대는 어때? 붕대 감는 법은 배우고 싶지 않아?', `MaleText_loc4`='$n，我的孩子！$B$B你想要学习我的手掌热疗技术吗？$B$B不？绷带技术？你想要学习绷带技术？', `MaleText_loc5`='$n!$B$B想要學學我獨門的熱掌治療技術嗎?$B$B不要?那繃帶呢?你想學繃帶急救術嗎?', `MaleText_loc7`='¡$n, $gmuchacho:muchacha;!$B$B¿Quieres que te enseñe mis técnicas de curación por palmas termales?$B$B¿No? ¿Y vendajes? ¿Quieres aprender algo sobre vendajes?' WHERE `ID`=36551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 더 못생겨진 것 같은데, $n!', `MaleText_loc4`='哈！$n，你看上去比以往更丑了！', `MaleText_loc5`='哈!$n，你比平常看起來還要醜!', `MaleText_loc7`='¡Agh! ¡Pareces más $gfeo:fea; que de costumbre, $n!' WHERE `ID`=36552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 소용돌이치는 뼈 폭풍을 일으킵니다!', `MaleText_loc4`='%s发动了一场白骨风暴！', `MaleText_loc5`='%s造出了一道高速迴旋的骸骨風暴!', `MaleText_loc7`='¡%s crea una tormenta ósea giratoria!' WHERE `ID`=36553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈 폭풍을 받아라!', `MaleText_loc4`='白骨风暴！', `MaleText_loc5`='骸骨風暴!', `MaleText_loc7`='¡TORMENTA DE HUESOS!' WHERE `ID`=36554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 간단한 변장이지만 충분할 겁니다, $r.', `MaleText_loc4`='这是个原始的伪装法术，$r，但它应该有用。', `MaleText_loc5`='這只是最基本的偽裝法術，$r，但應該足夠了。', `MaleText_loc7`='Es un hechizo primitivo de disfraz, $r, pero debería bastar.' WHERE `ID`=36555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 나쁜 뜻은 아닙니다만, 당신은 야성에 눈뜬 전쟁 기계일지도 모릅니다. 하지만 지금은 우리 편인 것 같군요.', `MaleText_loc4`='请不要见怪，$n。也许你的确是一台狂野的杀戮机器，不过你现在至少还是我们这一边的。', `MaleText_loc5`='別想太多，$n。你或許是個狂野的殺人機器，但你現在是跟我們在一起。', `MaleText_loc7`='Sin rencores, $n. Puede que seas una salvaje máquina de matar, pero parece que, por el momento, estás con nosotros.' WHERE `ID`=36556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신당했다!', `MaleText_loc4`='我们被出卖了！', `MaleText_loc5`='我們被出賣了!', `MaleText_loc7`='¡Nos han traicionado!' WHERE `ID`=36557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위쪽에서 만나자. 날 자유롭게 해 줘서 정말 고맙다!', `MaleText_loc4`='我们在甲板上见，$n。再次感谢你解救了我。', `MaleText_loc5`='我們在上頭再見，$n。再次為我的自由感謝你。', `MaleText_loc7`='Nos vemos en la cima, $n. ¡Gracias por mi libertad!' WHERE `ID`=36558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈앞에서 사라져라, $r! 네놈은 검은아귀에게 아무 쓸모도 없다.', `MaleText_loc4`='滚远点！黑喉部族不想和你打交道，$r。', `MaleText_loc5`='滾出我的視線!黑喉不想跟你扯上任何關係，$r。', `MaleText_loc7`='¡Fuera de mi vista! Los Faucenegra no quieren tener nada que ver contigo, $r.' WHERE `ID`=36559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오시오, 친구. 이야기할 것이 아주 많소.$B$B호드라 불리는 야수들이 이 숲을 황폐하게 만들었소. 끔찍한 돌칼로 땅 전체를 절단 내고 우리가 사냥하는 동물들을 쫓아내, 공기는 소음과 잿더미로 가득하오.$B$B말해주시오, 친구. 우리 검은아귀가 당신네 얼라이언스와 함께할 방법은 없겠소?', `MaleText_loc4`='欢迎你，朋友。我们有许多事要谈。$B$B被你称作“部落”的那些野兽正在这片森林中横行作恶。他们可怕的岩石条带切开了我们的土地，吓跑了我们捕猎的动物，让空气中充满了噪音和灰尘。$B$B告诉我，朋友。我们黑喉部族该怎样加入你们的“联盟”？', `MaleText_loc5`='歡迎你，盟友，我們有很多事情必須討論。$B$B你稱之為「部落」的野獸們摧殘著這片森林。他們可怕的石軌道切過我們的大地，將我們要狩獵的動物都嚇跑，讓空氣中充滿了噪音和塵土。$B$B跟我說，朋友，我們黑喉要如何加入你口中的這個「聯盟」?', `MaleText_loc7`='$gBienvenido, aliado:Bienvenida, aliada;. Tenemos mucho de lo que hablar.$b$bLas bestias que llamas "Horda" asolan estos bosques. Su horrible cinta de piedra corta nuestra tierra, asusta a los animales que cazamos y llena el aire de ruido y ceniza.$b$bDime, $gamigo mío:amiga mía;, ¿cómo podemos los Faucenegra unirnos a esta "Alianza" de la que hablas?' WHERE `ID`=36560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장은 안 되겠소, 털북숭이 양반. 먼저 발을 좀 문지르고 싶은데.', `MaleText_loc4`='别着急，熊脸丑八怪。首先，我需要来次足浴。', `MaleText_loc5`='先別急，熊頭。首先，先給我來個腳底按摩。', `MaleText_loc7`='No tengas tanta prisa, osezno. Primero necesito un masaje de pies.', `FemaleText_loc1`='당장은 안 되겠소, 털북숭이 양반. 먼저 발을 좀 문지르고 싶은데.', `FemaleText_loc4`='别着急，熊脸丑八怪。首先，我需要来次足浴。', `FemaleText_loc5`='先別急，熊頭。首先，先給我來個腳底按摩。', `FemaleText_loc7`='No tengas tanta prisa, barbotas. Primero necesito un masaje de pies.' WHERE `ID`=36561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 집에 들어와 갑자기 정신 나간 요구를 하는 저의가 뭔가?', `MaleText_loc4`='你闯进我的家园，向我的人民这样颐指气使，你到底想干什么？', `MaleText_loc5`='你的策略就是來到我們的地盤對我的族人發號司令嗎?', `MaleText_loc7`='¿Qué tipo de táctica es esta en la que entras en mi casa y empiezas a ladrar órdenes a mi gente?' WHERE `ID`=36562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 냄새는 뭐지? 당신인가? 정말 심하구만.', `MaleText_loc4`='这是什么臭味？是你身上的？我可没开玩笑。', `MaleText_loc5`='那是什麼味道?是你身上的嗎?拜託。', `MaleText_loc7`='¿A qué huele? ¿Eres tú? En serio.', `FemaleText_loc1`='이 냄새는 뭐지? 당신인가? 정말 심하구만.', `FemaleText_loc4`='这是什么臭味？是你身上的？我可没开玩笑。', `FemaleText_loc5`='那是什麼味道?是你身上的嗎?拜託。', `FemaleText_loc7`='¿A qué huele? ¿Eres tú? En serio.' WHERE `ID`=36563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 당신을 좋게 믿고 협상하는 내게 모욕을 주는 건가?', `MaleText_loc4`='什么？我们带着良好的愿望来参加谈判，而你却只是来侮辱我们？', `MaleText_loc5`='什麼?我們誠心要與你們協商，你卻來這污辱我?', `MaleText_loc7`='¿Qué? ¿Nosotros negociamos de buena fe y tú nos vienes con insultos?' WHERE `ID`=36564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초승달이 뜰 때마다 우리 얼라이언스의 조산원으로 갓난 아기를 하나씩 데려와라.', `MaleText_loc4`='联盟要求你们在每个新月时把新生儿送进我们的童工劳动营。', `MaleText_loc5`='聯盟要求每當新月到來時，你們必須貢獻一個新生寶寶到我們的嬰兒奴隸營。', `MaleText_loc7`='Con cada luna nueva la Alianza exige un envío de nuevos bebés para nuestros campos infantiles de trabajos forzados.', `FemaleText_loc1`='초승달이 뜰 때마다 우리 얼라이언스의 조산원으로 갓난 아기를 하나씩 데려와라.', `FemaleText_loc4`='联盟要求你们在每个新月时把新生儿送进我们的童工劳动营。', `FemaleText_loc5`='聯盟要求每當新月到來時，你們必須貢獻一個新生寶寶到我們的嬰兒奴隸營。', `FemaleText_loc7`='Con cada luna nueva la Alianza exige un envío de nuevos bebés para nuestros campos infantiles de trabajos forzados.' WHERE `ID`=36565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하그룸은 검은아귀 요새로 잠입하겠다는 야심찬 계획을 세웠습니다. 하지만 오크에겐 꽤나 벅찬 일일 텐데요. 그곳으로 순간이동하기 전에 마법의 위장복을 착용하십시오.', `MaleText_loc4`='哈格鲁姆渗透进黑喉要塞的计划实在是极具野心。对于一个兽人来说，这已经可以说是诡诈透顶了。在我把你传送过去之前先把这身魔法伪装服穿好。', `MaleText_loc5`='哈格魯姆想要滲透進入黑喉要塞的計畫相當大膽。不過，以一個獸人來說，這招還蠻陰險的。在我將你傳送進去前把附了魔的偽裝穿上。', `MaleText_loc7`='El plan de Haggrum para infiltrarse en el Bastión Faucenegra es ambicioso. De hecho, es bastante astuto para un orco. Ponte un disfraz encantado antes de que te teletransporte allí.' WHERE `ID`=36566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변장 마법은 몇 분이 지나면 풀립니다. 족장과 즉시 협상에 들어갈 수 있도록 검은아귀 요새 중심부로 곧바로 이동시켜 드리죠... 나오는 길에 있을 전투 준비도 잊지 마십시오.', `MaleText_loc4`='这身魔法伪装只能持续几分钟。我将把你直接传送到黑喉要塞的核心位置。然后你要立刻和他们酋长谈判……并准备好一路冲杀出来。', `MaleText_loc5`='附在偽裝上的魔法大概只能維持幾分鐘。我會直接把你傳送到黑喉要塞的內部。一到裡面，必須馬上與他們的酋長談話...然後做好準備，殺出一條血路逃離該地。', `MaleText_loc7`='La magia que hace posible ese disfraz aguantará tan solo unos minutos. Te teletransportaré directamente al corazón del Bastión Faucenegra. Ponte a negociar con el jefe inmediatamente... Y prepárate para salir de allí peleando.' WHERE `ID`=36567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 검은아귀 요새로 보내 주십시오.', `MaleText_loc4`='我准备好了，把我传送到黑喉要塞去吧。', `MaleText_loc5`='我準備好了。將我傳送到黑喉要塞裡面。', `MaleText_loc7`='Ya estoy listo. Teletranspórtame al Bastión Faucenegra.', `FemaleText_loc1`='준비됐습니다. 검은아귀 요새로 보내 주십시오.', `FemaleText_loc4`='我准备好了，把我传送到黑喉要塞去吧。', `FemaleText_loc5`='我準備好了。將我傳送到黑喉要塞裡面。', `FemaleText_loc7`='Ya estoy listo. Teletranspórtame al Bastión Faucenegra.' WHERE `ID`=36568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 $n. $g그:그녀;를 자살 행위와 같은 임무로 내몰았군요, 하그룸.', `MaleText_loc4`='可怜的$n。你这是送$g他:她;去完成一个自杀任务，哈格鲁姆。', `MaleText_loc5`='可憐的$n。這是一個自殺任務，哈格魯姆。', `MaleText_loc7`='Pobre $n. Le has enviado a un misión suicida, Haggrum.' WHERE `ID`=36569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현실을 받아들이는 게 좋아, 돼지 육포같은 녀석. 너희는 얼라이언스의 애완동물이나 마찬가지라고. 재주는 좀 부릴 줄 아나?', `MaleText_loc4`='你们最好赶紧习惯这种待遇，硬肉干。联盟只不过把你们当作宠物。你们明白吗？', `MaleText_loc5`='你們最好要習慣，下等動物。你們在聯盟的眼中不過是寵物罷了。你會耍雜技嗎?', `MaleText_loc7`='Será mejor que os acostumbréis, atontados. La Alianza os ve como mascotas. ¿Sabéis hacer trucos?', `FemaleText_loc1`='현실을 받아들이는 게 좋아, 돼지 육포같은 녀석. 너희는 얼라이언스의 애완동물이나 마찬가지라고. 재주는 좀 부릴 줄 아나?', `FemaleText_loc4`='你们最好赶紧习惯这种待遇，硬肉干。联盟只不过把你们当作宠物。你们明白吗？', `FemaleText_loc5`='你們最好要習慣，下等動物。你們在聯盟的眼中不過是寵物罷了。你會耍雜技嗎?', `FemaleText_loc7`='Será mejor que os acostumbréis, atontados. La Alianza os ve como mascotas. ¿Sabéis hacer trucos?' WHERE `ID`=36570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시끄럽군, 구역질나는 털뭉치 같으니! 곧 노움 군주를 맞을 준비나 해라!!', `MaleText_loc4`='闭嘴，长毛的呕吐物！很快你们就要学会向你们的侏儒统治者屈服了！！', `MaleText_loc5`='閉嘴，髒東西!你很快就會臣服於你的地精領主!', `MaleText_loc7`='¡Silencio, comemocos! ¡Pronto aprenderás a someterte a tus señores gnomos!', `FemaleText_loc1`='시끄럽군, 구역질나는 털뭉치 같으니! 곧 노움 군주를 맞을 준비나 해라!!', `FemaleText_loc4`='闭嘴，长毛的呕吐物！很快你们就要学会向你们的侏儒统治者屈服了！！', `FemaleText_loc5`='閉嘴，髒東西!你很快就會臣服於你的地精領主!', `FemaleText_loc7`='¡Silencio, comemocos! ¡Pronto aprenderás a someterte a tus señores gnomos!' WHERE `ID`=36571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말투가 심하게 거슬리는군, 이방인. 소위 얼라이언스라는 놈들이 그런 식으로밖에 나오지 못한다면 더는 그 무리에 끼지 않겠다!', `MaleText_loc4`='你的话激怒了我，外来者。如果这就是你们所谓的“联盟”能给我们的，我们绝对不会加入！', `MaleText_loc5`='你說的話讓我非常憤怒，陌生人。如果你代表的就是你所謂的「聯盟」，我們沒有興趣!', `MaleText_loc7`='Tu tono me enfurece, $gforastero:forastera;. Si esto es lo que podemos esperar de tu famosa "Alianza", ¡no queremos saber nada!' WHERE `ID`=36572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 부족이 얼라이언스의 잔혹한 군사 지배를 받는 노예가 되어 봐야 정신을 차리겠구나!', `MaleText_loc4`='当你的族人成为联盟铁腕下的奴隶时，你们将别无选择！', `MaleText_loc5`='當你們全被聯盟好戰的死亡小隊奴役時你根本沒有選擇的機會!', `MaleText_loc7`='No tendrás opción cuando tu pueblo sea esclavizado por los tiranos escuadrones de la muerte de la Alianza.', `FemaleText_loc1`='네 부족이 얼라이언스의 잔혹한 군사 지배를 받는 노예가 되어 봐야 정신을 차리겠구나!', `FemaleText_loc4`='当你的族人成为联盟铁腕下的奴隶时，你们将别无选择！', `FemaleText_loc5`='當你們全被聯盟好戰的死亡小隊奴役時你根本沒有選擇的機會!', `FemaleText_loc7`='No tendrás opción cuando tu pueblo sea esclavizado por los tiranos escuadrones de la muerte de la Alianza.' WHERE `ID`=36573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 지껄여 보시지. 그래봤자 내 귀엔 너희 부족이 쓰레기통에서 목욕한다는 소리만 들리는걸.', `MaleText_loc4`='你说了这么多，我听到的却只是“呱啦呱啦，我们熊怪用自己的粪便洗澡。”', `MaleText_loc5`='你話很多嘛，但我聽到的不就是「機哩呱拉我們全都喜歡在爛泥裡洗澡。」', `MaleText_loc7`='Sigues hablando, pero todo lo que escucho es "Bla, bla, mi pueblo se baña en nuestra propia mugre."', `FemaleText_loc1`='계속 지껄여 보시지. 그래봤자 내 귀엔 너희 부족이 쓰레기통에서 목욕한다는 소리만 들리는걸.', `FemaleText_loc4`='你说了这么多，我听到的却只是“呱啦呱啦，我们熊怪用自己的粪便洗澡。”', `FemaleText_loc5`='你話很多嘛，但我聽到的不就是「機哩呱拉我們全都喜歡在爛泥裡洗澡。」', `FemaleText_loc7`='Sigues hablando, pero todo lo que escucho es "Bla, bla, mi pueblo se baña en nuestra propia mugre."' WHERE `ID`=36574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<배꼽찌를 홱 잡아당깁니다.>', `MaleText_loc4`='<扯掉他的脐环。>', `MaleText_loc5`='<把他的肚環拔起來。>', `MaleText_loc7`='<Arranca de un tirón su piercing del ombligo.>', `FemaleText_loc1`='<배꼽찌를 홱 잡아당깁니다.>', `FemaleText_loc4`='<扯掉他的脐环。>', `FemaleText_loc5`='<把他的肚環拔起來。>', `FemaleText_loc7`='<Arranca de un tirón su piercing del ombligo.>' WHERE `ID`=36575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이여, 얼라이언스의 쓰레기가 우리를 배신했다! 모두 처단하라!', `MaleText_loc4`='战士们——联盟渣滓背叛了我们！消灭他们！', `MaleText_loc5`='戰士們!聯盟的雜碎背叛了我們!殺死他們!', `MaleText_loc7`='¡Guerreros! ¡La infame Alianza nos ha traicionado! ¡Matadlos!' WHERE `ID`=36576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 $n|1이라고;라고;요?! 죄송합니다, 선생님. 저는 $n|1이;가; 죽었다고 생각했거든요!', `MaleText_loc4`='是$n？！抱歉，医生，我还以为$g他:她;死了！', `MaleText_loc5`='那是$n?!抱歉醫生，我以為$g他:她;已經死了!', `MaleText_loc7`='¿$GEse:Esa; $n? ¡Lo siento, doctor, pensaba que estaba $gmuerto:muerta;!' WHERE `ID`=36577;
