UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들에게 저주를 옮기고 다니는 것을 가만두고 볼 수만은 없습니다. 옳지 않단 말입니다.', `MaleText_loc4`='我们不应该任由那些背负着诅咒的人再出现在我们中间。这样不对。', `MaleText_loc5`='我們不應該讓帶有詛咒的人加入我們。感覺就是不對。', `MaleText_loc7`='No debimos dejar que los portadores de la maldición caminen entre nosotros. No está bien.' WHERE `ID`=36590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, $n. 당신이 크레난의 부하가 아니었다면 이미 오래전에 죽었을 것입니다.', `MaleText_loc4`='小心，$n。如果你不是克雷南的宠物，那你早就应该死了。', `MaleText_loc5`='小心點，$n。如果你不是卡瑞南的寵物你老早就死了。', `MaleText_loc7`='Vigila tu espalda, $n. Si no fueras el perrito faldero de Krennan habrías muerto hace ya mucho tiempo.' WHERE `ID`=36591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 부모님도 늑대인간에게 당했습니다, $n. 조심하십시오.', `MaleText_loc4`='狼人杀了我的双亲，$n。你一定要小心。', `MaleText_loc5`='狼人殺死了我的父母，$n。你自己小心。', `MaleText_loc7`='Los huargen mataron a mis padres, $n. Ten cuidado.' WHERE `ID`=36592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나서 정말 반갑군, $n. 그 북슬북슬한 털도 말이야.', `FemaleText_loc4`='真高兴能再看到你，$n。而且一根毛都不缺。', `FemaleText_loc5`='很高興再次看到你，$n。毫髮無傷。', `FemaleText_loc7`='Es maravilloso volver a verte, $n. Con pelaje y todo.' WHERE `ID`=36593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $r. 자기 종족의 존속에 대한 그대의 인내와 헌신이 친구들과 동료에게 본보기가 되었네. 이 보상으로 그대에게 감사할 수 있도록 해 주게나. 손을 들어 상을 받게나, $n!', `MaleText_loc4`='谢谢，$r。你的坚持和为了保卫你们一族所做的贡献激励了你的人民和朋友。请让我用这份礼物表达我的谢意。伸出你的手，接受你的奖励吧，$n！', `MaleText_loc5`='謝謝你，$r。你對你們種族的忠誠和保護激勵了你的族人和朋友們。請讓我將你的獎勵呈現在你的面前。$n，舉起你的手接受這個禮物吧!', `MaleText_loc7`='Gracias, $r. Tu resistencia y dedicación para preservar a tu raza ha inspirado a tu pueblo y a tus amigos. Permíteme que te de las gracias con esta recompensa. ¡Alza la mano y toma tu premio, $n!' WHERE `ID`=36594;
