UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 이놈의 땅. 이제 이곳에는 머물 수 없습니다.', `MaleText_loc4`='诅咒这片土地，我们不能留在这里。', `MaleText_loc5`='這片該死的大地。我們無法待在這。', `MaleText_loc7`='¡Maldita sea esta tierra! No podemos quedarnos aquí.', `FemaleText_loc1`='이 땅이 저주스러워요. 이제 이곳에는 머물 수 없어요.', `FemaleText_loc4`='诅咒这片土地，我们不能留在这里。', `FemaleText_loc5`='這片該死的大地。我們無法待在這。', `FemaleText_loc7`='¡Maldita sea esta tierra! No podemos quedarnos aquí.' WHERE `ID`=36611;
