UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g그:그녀;가 그냥 지나가도록 보고만 있어야 합니까?', `MaleText_loc4`='我们要让$g他:她;过去吗？', `MaleText_loc5`='我們就這樣讓$g他:她;通過嗎?', `MaleText_loc7`='¿Vamos a dejarle pasar y ya está?' WHERE `ID`=36613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g그:그녀;는 크레난의 부하 중 하나입니다. 왕께서 내린 명령이지요. 그건 그렇고, 더 큰 문제가 다가오고 있습니다.', `MaleText_loc4`='$g他:她;已经是克雷南的人了。这是国王的命令。而且，看样子我们还有更大的问题要处理。', `MaleText_loc5`='$g他:她;是卡瑞南...不...是國王親衛隊的其中一員。此外，我們前面還有更麻煩的問題要面對。', `MaleText_loc7`='$gÉl:Ella; está con Krennan, órdenes del Rey. Además, por lo que veo dentro de poco vamos a tener problemas mayores.' WHERE `ID`=36614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크레난, 이 물약이 잘 듣더라도... 늑대인간이 마을을 배회하도록 할 수는 없습니다.', `MaleText_loc4`='即使这瓶药能起作用……我们也不能让狼人在我们的城里乱跑，克雷南。', `MaleText_loc5`='就算這個藥水有用...我們也不能就讓狼人在我們的城鎮中走來走去，卡瑞南。', `MaleText_loc7`='Aunque esa poción funcione... no podemos permitir que los huargen anden sueltos por nuestra ciudad, Krennan.' WHERE `ID`=36615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물약이 효과가 있더라도... 마을에 늑대인간이 미쳐 날뛰게 할 수는 없습니다, 크레난.', `MaleText_loc4`='即使这瓶药能起作用……我们也不能让狼人在我们的城里乱跑，克雷南。', `MaleText_loc5`='就算這個解藥有用...我們也不能就讓狼人在我們鎮上走來走去啊，卡瑞南。', `MaleText_loc7`='Aunque esa poción funcione... no podemos permitir que los huargen anden sueltos creando el caos por nuestra ciudad, Krennan.' WHERE `ID`=36616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 조심해야 합니다. 지금 당장 다른 사람이 당신을 집으로 초대할 것이라고는 기대하지 마십시오. 그렇지만 적어도 대놓고 당신에게 총을 쏘거나 하지는 않을 겁니다.', `MaleText_loc4`='一定要万分小心。没人会邀请你去他们家里。但至少他们也不会公开向你射击。', `MaleText_loc5`='提高警戒。別期待現在會有任何人請你到他家做客。不過他們至少不會看到你就開槍。', `MaleText_loc7`='No abandones la precaución. No esperes que vayan a invitarte a sus casas. Pero por lo menos no te pegarán un tiro en cuanto te vean.' WHERE `ID`=36617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 돌아오셨어요, $n. 당신은 정말 행운아예요. 크레난의 처방이 당신과 같이 오랫동안 저주에 빠져있던 사람에게 언제나 잘 듣는 것은 아니거든요.', `FemaleText_loc4`='欢迎回来，$n。你很幸运。对于像你这样受到诅咒的人，克雷南的治疗方法并不总是有效的。', `FemaleText_loc5`='歡迎回來，$n。你的運氣很好。卡瑞南的藥水一般在像你這種擁有詛咒那麼久的人身上起不了什麼作用。', `FemaleText_loc7`='Te doy la bienvenida de nuevo, $n. Has tenido suerte. El tratamiento de Krennan no suele funcionar tan bien con gente que lleva tanto tiempo bajo la influencia de la Maldición como tú.' WHERE `ID`=36618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린치고는 나쁘지 않군.', `MaleText_loc4`='对于地精来说，还不算糟。', `MaleText_loc5`='對於一個哥布林來說還不賴。', `MaleText_loc7`='No está mal para un goblin.' WHERE `ID`=36619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸울 때 자네가 썼던 $c 기술은 뭐였나?', `MaleText_loc4`='在战斗中，那个$c是怎么骗的你？', `MaleText_loc5`='你剛在戰鬥中的那個$c特技是什麼?', `MaleText_loc7`='¿Qué es ese truco de $c que has utilizado durante la pelea?' WHERE `ID`=36620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간은 다 겁쟁이군. 내 말 들리나, 인간? 나와서 명예롭게 싸워라!', `MaleText_loc4`='人类都是懦夫。听到我的话了吗，人类？出来，带着荣誉大战一场！', `MaleText_loc5`='這些人類是懦夫。聽到了嗎你們這些人類?出來光榮地戰鬥!', `MaleText_loc7`='Esos humanos son unos cobardes. ¿Me oís HUMANOS? ¡Venid aquí y luchad con honor!' WHERE `ID`=36621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린은 장신구나 팔면서 허풍만 떤다고 생각하네.', `MaleText_loc4`='我还以为地精只会卖卖东西，吹吹牛呢。', `MaleText_loc5`='我以為哥布林只擅長賣飾品和把自己炸飛。', `MaleText_loc7`='Creía que los goblins tan solo servían para vender baratijas y saltar por los aires con sus inventos.' WHERE `ID`=36622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리 들었나? $n, 우리를 엿보는 자가 없는지 주변을 좀 살펴보게.', `MaleText_loc4`='你听到了什么吗？注意周围的动静，$n，小心有人偷袭我们。', `MaleText_loc5`='你聽到了嗎?看看四周，$n，看有沒有想要偷襲我們的人。', `MaleText_loc7`='¿Has oído eso? Mira a tu alrededor, $n, para ver si alguno intenta acercarse a nosotros sin ser visto.' WHERE `ID`=36623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린, 말해 보게. 왜 그쪽 노예선은 우리가 싸우는 근처에서 어슬렁거렸나?', `MaleText_loc4`='告诉我，地精，为什么你们的奴隶船会开进我们的战场？', `MaleText_loc5`='跟我說，哥布林，為什麼你的奴隸船會進入到我們的戰區?', `MaleText_loc7`='Y dime, goblin, ¿por qué tu barco de esclavos acabó en medio de nuestra batalla?' WHERE `ID`=36624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 쓰러뜨리려고 했나, 하찮은 인간 주제에? 한심한 네놈 종족 전체를 합해도 이 작은 고블린 하나보다 더 용기가 없을 거다!', `MaleText_loc4`='你想过要杀我，小人类？这个小地精比起可怜的你们更有勇气！', `MaleText_loc5`='弱小的人類，你想要殺我?這個小個子哥布林比人類這個可悲的種族擁有更多的勇氣!', `MaleText_loc7`='¿Creíste que podías matarme, humano enclenque? ¡Este pequeño goblin tiene más valor que toda tu patética raza junta!' WHERE `ID`=36625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 허리띠 안에 또 뭐가 들었나?', `MaleText_loc4`='你那条腰带里还有什么？', `MaleText_loc5`='你那條腰帶裡還有什麼其他的東西?', `MaleText_loc7`='Bueno, ¿y qué más llevas en ese cinturón?' WHERE `ID`=36626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하! 이게 아주 마음에 들 거예요!', `MaleText_loc4`='啊哈哈！你会喜欢上这个的！', `MaleText_loc5`='啊哈哈!你一定會喜歡這個的!', `MaleText_loc7`='¡Jajaja! ¡Esto os va a encantar!' WHERE `ID`=36627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 울부짖자 어둠의 힘이 쇄도합니다!', `MaleText_loc4`='%s发出怒吼，在黑暗力量的作用下开始膨胀！', `MaleText_loc5`='%s吼叫著，並且因為黑暗之力而膨脹!', `MaleText_loc7`='¡%s gruñe y se hincha con poder oscuro!' WHERE `ID`=36628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 변화가 일어나고 있다네, 젊은이. 뭔가 이상한 걸 보더라도 놀라지 말게나... 바로 나 같은 것 말이지. 음매.', `MaleText_loc4`='这里发生了许多变化，年轻人。不管看到什么奇怪的东西都不要惊慌……比如我。哞。', `MaleText_loc5`='這裡發生了許多的變化，年輕人。看到突兀的東西別感到太驚訝...就像看到我。哞。', `MaleText_loc7`='Por aquí están ocurriendo muchos cambios, joven. No tengas miedo si ves algo fuera de lugar... Como yo. Buuu.' WHERE `ID`=36629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님을 보호해라!', `MaleText_loc4`='保护船长！', `MaleText_loc5`='保護隊長!', `MaleText_loc7`='¡Proteged al Capitán!' WHERE `ID`=36630;
