UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 위치를 사수하라!', `MaleText_loc4`='坚守战线，弟兄们！', `MaleText_loc5`='堅守崗位，士兵們。', `MaleText_loc7`='¡Mantengan su posición!' WHERE `ID`=36632;
