UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 타십시오! 저 녀석이 탈출하게 놔둘 순 없습니다!', `MaleText_loc4`='加快速度！我们不能让那条龙跑了！', `MaleText_loc5`='上來，快點!我們不能讓那飛龍跑了!', `MaleText_loc7`='¡Monta, deprisa! ¡No podemos dejar que ese draco escape!' WHERE `ID`=36634;
