UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 검에 대해 무언가 아십니까?', `MaleText_loc4`='你知道些什么有关古剑的事？', `MaleText_loc5`='你對上古之劍瞭解多少?', `MaleText_loc7`='¿Qué sabes acerca de antiguas espadas?', `FemaleText_loc1`='고대 검에 대해 무언가 아시나요?', `FemaleText_loc4`='你知道些什么有关古剑的事？', `FemaleText_loc5`='你對上古之劍瞭解多少?', `FemaleText_loc7`='¿Qué sabes acerca de antiguas espadas?' WHERE `ID`=36637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잃어버린 섬을 거닐다가 새 동맹인 고블린이 만든 작품들을 보았네. 하지만 아직은 저들의 재주를 시험하는 중이라네. 여기서는 적의 요새를 제압해야 하는 상황이지.', `MaleText_loc4`='当我在失落群岛上束手无策的时候，我见识了我们新地精盟友的能力。但现在，我们要测试他们的才华了：我们要在敌人的要塞中与他们作战。', `MaleText_loc5`='我被困在失落群島時見證了我們新盟友哥布林的手藝。現在就是測驗他們的聰明才智的時候了:我們現在正在我們敵人的地盤上與他們對抗。', `MaleText_loc7`='Presencié el trabajo de nuestros nuevos aliados goblins cuando naufragué en Las Islas Perdidas. Pero ahora pondremos a prueba su ingenuidad: ahora nos enfrentaremos a nuestros enemigos en su propia fortaleza.' WHERE `ID`=36638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설적인 나이트 엘프 모호크의 존재를 믿지 않는 이들이 있소.$B$B한심한 바보 녀석들 같으니.', `MaleText_loc4`='有人不相信传说中的暗夜精灵莫霍克。$B$B真为他们悲哀。', `MaleText_loc5`='有些人就是不相信傳說中的夜精靈怪頭。$B$B我同情這些蠢蛋。', `MaleText_loc7`='Hay quienes no creen en los legendarios elfos de la noche mohicanos.$B$BEstán como una maraca.' WHERE `ID`=36639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 모호크의 존재를 믿습니다.', `MaleText_loc4`='我相信你。', `MaleText_loc5`='我相信你。', `MaleText_loc7`='Yo creo en ti.', `FemaleText_loc1`='저는 모호크의 존재를 믿어요.', `FemaleText_loc4`='我相信你。', `FemaleText_loc5`='我相信你。', `FemaleText_loc7`='Yo creo en ti.' WHERE `ID`=36640;
