UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, 모호크 $G형제:자매;여.', `MaleText_loc4`='幸会，莫霍克的好$G兄弟:姐妹;。', `MaleText_loc5`='很高興見到你，怪頭$G老兄:大姐;。', `MaleText_loc7`='$gBienvenido:Bienvenida;, $ghermano mohicano:hermana mohicana;.' WHERE `ID`=36642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 우리가 있는 곳을 알면 안 돼요, $n! 탑에는 호위병들이 득실댄다고요.', `FemaleText_loc4`='不要暴露了我们的位置，$n！那座塔里塞满了保镖。', `FemaleText_loc5`='別把我們的位置曝露給敵人，$n!那座塔上到處都是守衛。', `FemaleText_loc7`='¡No abandones tu posición, $n! Esa torre está abarrotada de guardaespaldas.' WHERE `ID`=36643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 슬링키. 일을 시작하죠.', `MaleText_loc4`='我准备好了，史莉琪。我们行动吧。', `MaleText_loc5`='我準備好了，史琳琪。我們上吧。', `MaleText_loc7`='Estoy listo, Finta. Hagámoslo.', `FemaleText_loc1`='준비됐습니다, 슬링키. 일을 시작하죠.', `FemaleText_loc4`='我准备好了，史莉琪。我们行动吧。', `FemaleText_loc5`='我準備好了，史琳琪。我們上吧。', `FemaleText_loc7`='Estoy lista, Finta. Hagámoslo.' WHERE `ID`=36644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대장의 머리카락을 가져오세요. 전 폭발물을 설치할게요.', `FemaleText_loc4`='抓好队长的头，我正在安装炸药。', `FemaleText_loc5`='把那隊長的頭抓住，我正在安裝炸藥。', `FemaleText_loc7`='Coge la cabeza del capitán, estoy armando los explosivos.' WHERE `ID`=36645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='됐어요. 이제 이곳을 날려버릴 준비는 끝났어요. 여길 뜨자고요!', `FemaleText_loc4`='好了，这个地方就要爆炸了。我们赶快离开这里！', `FemaleText_loc5`='好了，這個地方馬上就要被炸爛了。我們快閃!', `FemaleText_loc7`='Vale, este lugar está a punto de explotar. ¡Salgamos de aquí!' WHERE `ID`=36646;
