UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 탑 아래쪽에 수상한 놈들이 있다. 저들을 막아!', `MaleText_loc4`='卫兵！他们在塔底搞鬼，快阻止他们！', `MaleText_loc5`='守衛!他們不知道在塔的底端做什麼。阻止他們!', `MaleText_loc7`='¡Guardias! ¡Están planeando algo en la base de la torre! ¡Detenlos!' WHERE `ID`=36656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 하지만, 허례허식은 건너뛰고 바로 전투를 시작했으면 합니다.', `MaleText_loc4`='我准备好了。但是，我倒是愿意不参加这庆典。', `MaleText_loc5`='我準備好了。但我想略過這場盛會。', `MaleText_loc7`='Estoy preparado, pero me gustaría saltarme las ostentaciones', `FemaleText_loc1`='준비됐어요. 하지만, 허례허식은 건너뛰고 바로 전투를 시작했으면 합니다.', `FemaleText_loc4`='我准备好了。但是，我倒是愿意不参加这庆典。', `FemaleText_loc5`='我準備好了。但我想略過這場盛會。', `FemaleText_loc7`='Estoy preparada, pero me gustaría saltarme las ostentaciones' WHERE `ID`=36657;
