UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스가 이 세계의 존속 너머의 힘으로부터 공격받았다...', `MaleText_loc4`='艾泽拉斯遭到了进攻，而入侵者来自于现实位面以外的空间……', `MaleText_loc5`='艾澤拉斯已被不屬於這個世界的力量所攻擊了。', `MaleText_loc7`='Azeroth ha sido atacado por fuerzas provenientes de más allá de este plano de existencia...' WHERE `ID`=36660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 깊은 곳에서부터 도움의 손길을 갈구하고 있으나, 갈구의 소리를 들을 수 있는 이는 거의 없도다.', `MaleText_loc4`='她拼命呼喊着，寻求帮助，但几乎没人能听到她的哀求。', `MaleText_loc5`='她的哭喊從地底深淵傳了出來，但只有少數人能聽到她求助的聲音。', `MaleText_loc7`='Desde su interior grita pidiendo ayuda, pero muy pocos pueden escuchar sus ruegos.' WHERE `ID`=36661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그 소리를 들을 수 있다, $r. 그 소리를 말로 옮겨보겠다..', `MaleText_loc4`='我能听懂他们说话， $r。请让我翻译……', `MaleText_loc5`='我聽的到，$r。請讓我翻譯...', `MaleText_loc7`='Los oigo, $r. Permíteme que traduzca...' WHERE `ID`=36662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 들어 우리 세계의 적을 처치하라.', `MaleText_loc4`='拿起剑，击败我们世界的敌人。', `MaleText_loc5`='將劍舉起來，擊敗這個世界的敵人。', `MaleText_loc7`='Coge la espada y derrota al enemigo de nuestro mundo.' WHERE `ID`=36663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 존재들이여, 그렇게 한심하게 불평해봤자 리치 왕의 뜻 앞에서는 아무 의미도 없다. 너희는 리치 왕을 섬기리라, 죽어서까지 말이다!', `MaleText_loc4`='[ph] 愚蠢的生物们，你们那点牢骚面对巫妖王的意愿根本不值一提。你们会变成他的奴仆，生生世世！', `MaleText_loc5`='[ph]愚蠢的生物，你們可悲的埋怨在巫妖王的意志前沒有任何意義。你們得要服侍他，就算是死後也得服侍他!', `MaleText_loc7`='[ph] Foolish creatures, your pithy complaints mean nothing before the will of the Lich King. You will serve him, even beyond death!' WHERE `ID`=36664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구질구질한 불평은 충분히 들었다. 너는 그대로 살아가야 하리라. 이 미천한 생명들은 리치 왕을 섬겨야 하리라. 죽어서까지 말이다!', `MaleText_loc4`='[ph] 收起你们那些可悲的牢骚吧。你们会继续下去的。这些像狗一样可怜的家伙全都要侍奉巫妖王，生生世世！', `MaleText_loc5`='[ph]你們可悲的抱怨已經夠多了。你們『要』繼續工作。這些可悲的狗就算在死後也得服侍巫妖王!', `MaleText_loc7`='[ph] Enough of your miserable complaints. You WILL carry on. These miserable dogs shall serve the Lich King, even beyond death!' WHERE `ID`=36665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송장이 되어서까지 영원히 일하리라... 잠깐... 침입자라고? 여기에?! 당장 처리하라!', `MaleText_loc4`='[ph] 从现在开始，你的每一根骨头都要承担永远的劳作…等等…入侵者？在这里？！马上解决掉他们！', `MaleText_loc5`='[ph]現在你的骷髏將會工作直到永遠...等等...入侵者?這裡?!立刻解決他們!', `MaleText_loc7`='[ph] Now your skeletons shall labor for all of eternity... wait... intruders? Here?! Dispose of them immediately!' WHERE `ID`=36666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만요. 더는 일을 못하겠습니다! 잠시만 쉴 틈을 주십시오!', `MaleText_loc4`='[ph] 求你了，我没法再干更多的活儿了！请让我们稍微休息一会儿吧！', `MaleText_loc5`='[ph]拜託，我沒辦法繼續工作了!讓我休息幾分鐘就好!', `MaleText_loc7`='[ph] Please, I cannot labor any longer! Spare us for just a few minutes!', `FemaleText_loc1`='잠시만요. 더는 일을 못하겠어요! 잠시만 쉴 틈을 주세요!', `FemaleText_loc4`='[ph] 求你了，我没法再干更多的活儿了！请让我们稍微休息一会儿吧！', `FemaleText_loc5`='[ph]拜託，我沒辦法繼續工作了!讓我休息幾分鐘就好!', `FemaleText_loc7`='[ph] Please, I cannot labor any longer! Spare us for just a few minutes!' WHERE `ID`=36667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하면 아제로스는 멸망할 것이니 우리가 아제로스를 지켜야 한다!', `MaleText_loc4`='如果失败，世界就会毁灭，我们也将一同灭亡！', `MaleText_loc5`='失敗將會伴隨她的毀滅，而我們也將一起陪葬!', `MaleText_loc7`='Fracasa y ella morirá... ¡Y nosotros con ella!' WHERE `ID`=36668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성실한 $r|1이여;여;, 큰 축복이 그대에게 내리길.', `FemaleText_loc4`='你将得到强大的祝福，好$r。', `FemaleText_loc5`='偉大的祝福伴隨你，$r。', `FemaleText_loc7`='Que las grandes bendiciones caigan sobre ti, amable $r.' WHERE `ID`=36669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 도전에 임하려면 은빛십자군 전투검은늑대에 올라야 합니다. 이 원형경기장의 벽을 따라 서 있는 전투검은늑대가 보이실 겁니다.$b$b자, 전투검은늑대에 오르세요. 그리고 제게 말을 거시면 도전을 진행할 수 있습니다.', `MaleText_loc4`='第一场挑战要求你骑上一头银色战狼。你会在演武场的墙边找到这些坐骑，骑着它们来找我，然后我们继续。', `MaleText_loc5`='第一項挑戰就需要騎上一隻銀白作戰座狼。你可以在大競技場的牆邊找到那些坐騎。$b$b請騎上那些作戰座狼，然後再來找我，讓我們可以繼續進行下去。', `MaleText_loc7`='El primer reto requiere que estés $gmontado:montada; sobre un huargo de batalla Argenta. Encontrarás estas monturas a lo largo de los muros del Coliseo.$b$bMonta en el huargo y habla conmigo para que podamos continuar.' WHERE `ID`=36670;
