UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 유물에 대해서는 피상적으로 아는 수준을 벗어난 정도이고, 푸른용군단은 내부의 걱정거리만으로도 충분합니다.$B$B도서관 안에는 우리가 필멸의 동맹을 위해 벼려낸 검에 대해 쓴 책이 있지만, 이미 선리버 대표에게 빌려주어서 유감이군요. $n 님, 그 고대의 검에 관하여 정보를 구하러 온 건 당신이 처음이 아니랍니다.', `MaleText_loc4`='我对魔法器物有一点粗浅的认识，蓝龙自己的麻烦已经够多的了。$B$B图书馆里曾有一本书介绍了我们为凡人盟友打造的那些剑，不过恐怕我已经把这本书借给了夺日者的使者。$n，你并不是第一个来这打探那些古剑消息的人。', `MaleText_loc5`='我對魔法神器也只有一點粗略的知識，而藍龍軍團自己也有夠多麻煩了。$B$B圖書館中曾有一本書記載了關於我們替那些凡人盟友鑄造兵器的事情，但我怕我已經把書借給了一位奪日者的代表。$n，你不是第一個來詢問那些古劍的人。', `MaleText_loc7`='No poseo más que un conocimiento superficial sobre artefactos mágicos y el Vuelo Azul ya tiene bastantes problemas.$B$BEn la biblioteca había un libro acerca de las hojas que forjamos para nuestros aliados mortales, pero me temo que ya se lo he prestado a un representante de los Atracasol. No eres $gel primero:la primera; que viene buscando información acerca de esas antiguas espadas, $n.' WHERE `ID`=36704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 유물에 대해서는 피상적으로 아는 수준을 벗어난 정도이고, 푸른용군단은 내부의 걱정거리만으로도 충분합니다.$B$B도서관 안에는 우리가 필멸의 동맹을 위해 벼려낸 검에 대해 쓴 책이 있지만, 이미 은빛 서약단 대표에게 빌려주어서 유감이군요. 그 고대의 검에 관하여 정보를 구하러 온 건 당신이 처음이 아니랍니다, $n.', `MaleText_loc4`='我对魔法器物有一点粗浅的认识，蓝龙自己的麻烦已经够多的了。$B$B图书馆里曾有一本书介绍了我们为凡人盟友打造的那些剑，不过恐怕我已经把这本书借给了银色盟约的使者。$n，你并不是第一个来这打探那些古剑消息的人。', `MaleText_loc5`='我對魔法神器也只有一點粗略的知識，而藍龍軍團自己也有夠多麻煩了。$B$B圖書館中曾有一本書記載了關於我們替那些凡人盟友鑄造兵器的事情，但我怕我已經把書借給了一位白銀誓盟的代表。$n，你不是第一個來詢問那些古劍的人。', `MaleText_loc7`='No poseo más que un conocimiento superficial sobre artefactos mágicos y el Vuelo Azul ya tiene bastantes problemas.$B$BEn la biblioteca había un libro acerca de las hojas que forjamos para nuestros aliados mortales, pero me temo que ya se lo he prestado a un representante de El Pacto de Plata. No eres $gel primero:la primera; que viene buscando información acerca de esas antiguas espadas, $n.' WHERE `ID`=36705;
