UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF7F00자극적인 파멸의 역병|r을 시전합니다!', `MaleText_loc4`='%s开始施放|cFFFF7F00刺鼻毒气！|r', `MaleText_loc5`='%s開始施展|cFFFF7F00刺鼻荒疫!|r', `MaleText_loc7`='%s comienza a lanzar |cFFFF7F00¡Añublo acre!|r' WHERE `ID`=36707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추격해도 소용없다, 침입자들아. 리치 왕께서 언데드 군대를 내게 주셨다! 똑똑히 보아라!', `MaleText_loc4`='你们的努力是徒劳的，入侵者。巫妖王让我统率的可是一支亡灵大军！小心了！', `MaleText_loc5`='你們所追求的終歸是一場空，入侵者，因為巫妖王已經派了一支不死大軍歸我指揮!看著吧!', `MaleText_loc7`='¡Su búsqueda será en vano, intrusos, pues el Rey Exánime ha puesto un ejército de no-muertos a mis órdenes! ¡Observen!', `FemaleText_loc1`='추격해도 소용없다, 침입자들아. 리치 왕께서 언데드 군대를 내게 주셨다! 똑똑히 보아라!', `FemaleText_loc4`='你们的努力是徒劳的，入侵者。巫妖王让我统率的可是一支亡灵大军！小心了！', `FemaleText_loc5`='你們所追求的終歸是一場空，入侵者，因為巫妖王已經派了一支不死大軍歸我指揮!看著吧!', `FemaleText_loc7`='¡Su búsqueda será en vano, intrusos, pues el Rey Exánime ha puesto un ejército de no-muertos a mis órdenes! ¡Observen!' WHERE `ID`=36708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끈질긴 놈들! 주인님 계신 근처도 못 갈 것이다. 병사들아, 저놈들을 해치워라!', `MaleText_loc4`='固执的家伙！你们根本到不了主人的密室！士兵们，消灭他们！', `MaleText_loc5`='頑抗的小蟲!你們到不了我主的巢穴!士兵們，毀滅他們!', `MaleText_loc7`='¡Gusanos persistentes! ¡No alcanzarán la entrada de la guarida de mi señor! ¡Soldados, destrúyanlos!', `FemaleText_loc1`='끈질긴 놈들! 주인님 계신 근처도 못 갈 것이다. 병사들아, 저놈들을 해치워라!', `FemaleText_loc4`='固执的家伙！你们根本到不了主人的密室！士兵们，消灭他们！', `FemaleText_loc5`='頑抗的小蟲!你們到不了我主的巢穴!士兵們，毀滅他們!', `FemaleText_loc7`='¡Gusanos persistentes! ¡No alcanzarán la entrada de la guarida de mi señor! ¡Soldados, destrúyanlos!' WHERE `ID`=36709;
