UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서릿발송곳니, 굴 안으로 몰아라! 산 채로 묻어버려라!', `MaleText_loc4`='霜牙，把他们困在隧道里！统统给我埋了！', `MaleText_loc5`='霜牙，把他們困在通道裡!活埋他們!', `MaleText_loc7`='Dientefrío, ¡atrápalos en el túnel! ¡ENTIÉRRALOS VIVOS!', `FemaleText_loc1`='서릿발송곳니, 굴 안으로 몰아라! 산 채로 묻어버려라!', `FemaleText_loc4`='霜牙，把他们困在隧道里！统统给我埋了！', `FemaleText_loc5`='霜牙，把他們困在通道裡!活埋他們!', `FemaleText_loc7`='Dientefrío, ¡atrápalos en el túnel! ¡ENTIÉRRALOS VIVOS!' WHERE `ID`=36714;
