UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽입니다! 이제 스컬지군주가 있는 곳을 공격하겠습니다!', `MaleText_loc4`='走这边！我们就要对天灾领主的领地发动袭击了！', `MaleText_loc5`='這邊!我們可以對天譴領主的位置發動突襲了!', `MaleText_loc7`='¡Por aquí! ¡Iniciaremos un asalto a la ubicación del Señor de la Plaga!', `FemaleText_loc1`='이쪽이에요! 이제 스컬지군주가 있는 곳을 공격하겠어요!', `FemaleText_loc4`='走这边！我们就要对天灾领主的领地发动袭击了！', `FemaleText_loc5`='這邊!我們可以對天譴領主的位置發動突襲了!', `FemaleText_loc7`='¡Por aquí! ¡Iniciaremos un asalto a la ubicación del Señor de la Plaga!' WHERE `ID`=36718;
