UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만날 날을 기다리고 있었어요, $n 님.', `FemaleText_loc4`='很想知道我们什么时候能够再见，$n。', `FemaleText_loc5`='我還在想我什麼時候才可以再看到你，$n。', `FemaleText_loc7`='Me estaba preguntando cuándo te vería de nuevo, $n.' WHERE `ID`=36726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단한 건 아니지만 당신의 녹색 피부가 상하지 않게 해 줄 거예요.', `FemaleText_loc4`='这不算很厉害，但它也许刚好能保护到你的绿皮肤。', `FemaleText_loc5`='沒很多，但足夠讓你的綠皮保持完好。', `FemaleText_loc7`='No es mucho, pero puede que mantenga intacta tu piel verde.' WHERE `ID`=36727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두가 당신을 믿고 있어요!', `FemaleText_loc4`='只想让你知道，我们全都在指望你呢！', `FemaleText_loc5`='只是要讓你知道我們全都靠你了!', `FemaleText_loc7`='¡Solo quería decirte que todos contamos contigo!' WHERE `ID`=36728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<앞에 있는 오크의 얼굴은 진한 녹색을 띄고 있습니다.>$B$B$C 양반, 고블린들이 해안에 "해산물 무한 제공 식당"을 열었소. 마치... *우욱* 내 뱃속에 대격변이 일어난 것 같구려.', `MaleText_loc4`='<你面前的兽人看上去比以往更绿了。>$B$B$C，那些地精已经把“所有人都能吃的海产”带了过来。但这些东西……*呃*，也在我的胃里引起了一场大灾变。', `MaleText_loc5`='<你眼前的獸人看起來比平常更綠。>$B$B$C，哥布林帶了「你能吃多少就吃多少的海鮮大餐」到我們的海岸。這真是...<嘔>...我肚子裡的大災變。', `MaleText_loc7`='<El orco que hay ante ti está más verde de lo normal.>$b$b$C, los goblins han traído a nuestras orillas "todo el marisco que puedas comer". Es como...*urp* ... un cataclismo en mi estómago.' WHERE `ID`=36729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*우욱!*', `MaleText_loc4`='*啊！*', `MaleText_loc5`='<嘔!>', `MaleText_loc7`='*¡Urp!*' WHERE `ID`=36730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조개는...먹지 말았어야 했는데...', `MaleText_loc4`='不应该要……蛤蚌……', `MaleText_loc5`='不應該吃那...蛤蜊的...', `MaleText_loc7`='No debería haber tomado... las almejas...' WHERE `ID`=36731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조개가...문제였어.', `MaleText_loc4`='就是……这种杂烩。', `MaleText_loc5`='是那...蚌肉雜燴。', `MaleText_loc7`='Ha sido... la sopa de pescado.' WHERE `ID`=36732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"무한 제공"이라더니. *구엑*', `MaleText_loc4`='“这些都是能吃的，”他说。*打嗝*', `MaleText_loc5`='「能吃多少就吃多少」他說。<嗝>', `MaleText_loc7`='"Todo lo que puedas comer" dice. *Erupto*' WHERE `ID`=36733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조개...튀김...', `MaleText_loc4`='这个……蚌肉……', `MaleText_loc5`='那些...蛤蜊...會自己脫殼...', `MaleText_loc7`='Las... almejas fritas...' WHERE `ID`=36734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비스크 안에 대체 뭐가 들어 있던 거야?', `MaleText_loc4`='这个“浓汤”里都有些什么？', `MaleText_loc5`='那個「濃湯」裡面是什麼?', `MaleText_loc7`='¿Qué lleva esa "sopa"?' WHERE `ID`=36735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발! 그만요. 더는 견딜 수가 없습니다!', `MaleText_loc4`='求你了！我真的……我真的受不了了！', `MaleText_loc5`='拜託!住手。我受不了了!', `MaleText_loc7`='¡Por favor! Basta. ¡No puedo soportarlo más!', `FemaleText_loc1`='제발! 그만요. 더는 견딜 수가 없습니다!', `FemaleText_loc4`='求你了！我真的……我真的受不了了！', `FemaleText_loc5`='拜託!住手。我受不了了!', `FemaleText_loc7`='¡Por favor! Basta. ¡No puedo soportarlo más!' WHERE `ID`=36736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프는 이미 만 년 전에 이곳을 잃었습니다. 지금 우리 손으로 추방하는 건 의례적인 절차일 뿐이죠.', `MaleText_loc4`='要让我说的话，暗夜精灵在一万年以前就已经丢掉了这个地方。今天他们被我们驱逐只不过是一个形式上的事情。', `MaleText_loc5`='如果你問我，我會說那些夜精靈一萬年前失去了這個地方，而我們現在不過是依照歷史再把他們趕走一次。', `MaleText_loc7`='Si quieres saber lo que pienso, los elfos de la noche perdieron esta zona hace miles de años. Que nosotros les expulsemos ahora no es más que una mera formalidad.' WHERE `ID`=36737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 돌에 비전 마력이 집중되어 희미하게 빛나고 있습니다.', `MaleText_loc4`='这块巨大的石头闪烁着聚焦的奥术能量。', `MaleText_loc5`='巨大的石頭因為灌注了秘法能量而閃閃發亮。', `MaleText_loc7`='La enorme roca titila a causa de una concentración de energía arcana.' WHERE `ID`=36738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<돌을 사용해 발로르모크로 다시 순간이동>', `MaleText_loc4`='<使用这块石头传送回瓦罗莫克。>', `MaleText_loc5`='<使用石頭來傳送回瓦羅莫克。>', `MaleText_loc7`='<Utiliza la roca para teletransportarte a Valormok.>', `FemaleText_loc1`='<돌을 사용해 발로르모크로 다시 순간이동>', `FemaleText_loc4`='<使用这块石头传送回瓦罗莫克。>', `FemaleText_loc5`='<使用石頭來傳送回瓦羅莫克。>', `FemaleText_loc7`='<Utiliza la roca para teletransportarte a Valormok.>' WHERE `ID`=36739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 돌에 비전 마력이 집중되어 희미하게 빛나고 있습니다.$B$B안도렐이 말한 바가 사실이라면, 돌의 기운을 쉽게 다른 방향으로 돌릴 수 있을 것입니다.', `MaleText_loc4`='这块巨大的石头闪烁着集中起来的奥术能量。$B$B如果安多瑞尔的指示是可信的，它就应该能轻易地重新集中这块石头的能量。', `MaleText_loc5`='巨大的石頭因為灌注了秘法能而閃閃發亮。$B$B如果安多雷爾所說的沒錯，應該很簡單就可以為石頭重新充能。', `MaleText_loc7`='La enorme roca titila a causa de una concentración de energía arcana.$B$BSi aceptamos las instrucciones de Andorel, debería resultar sencillo reenfocar las energías de la roca.' WHERE `ID`=36740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다, $n! 이제 부대를 모아 볼까요...', `MaleText_loc4`='干得好，$n！那么，让我集结队伍……', `MaleText_loc5`='幹得好，$n!現在呢，讓我把大家召集起來...', `MaleText_loc7`='¡Bien hecho, $n! Ahora reunamos al grupo...' WHERE `ID`=36741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋습니다. 제까짓 것들이 용을 써 봤자지요...', `MaleText_loc4`='很好。无论你们想干什么……都努力去做。', `MaleText_loc5`='很好。不管你們這群傢伙要做什麼...盡量做。', `MaleText_loc7`='Muy bien. Sea lo que sea lo que hagan ustedes... haganlo muchas veces.' WHERE `ID`=36742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이제 소환의 돌을 사용해 제가 있는 발로르모크로 다시 순간이동하실 수 있습니다. 기억해 두십시오!', `MaleText_loc4`='$n，不要忘记，现在你就能使用召唤石将自己传送回我在瓦罗莫克的所在地了。', `MaleText_loc5`='$n，別忘了你現在可以使用召喚石隨時將你自己傳送回我在瓦羅莫克的位置!', `MaleText_loc7`='¡No lo olvides, $n, ahora puedes utilizar la roca de invocación para teletransportarte de vuelta a mi posición en Valormok!' WHERE `ID`=36743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 구원받을 기회가 왔어, 자다르. 이번 마상시합으로 우리는 영웅이 될 수 있다고!', `MaleText_loc4`='咸鱼翻身的时刻到了，亚达尔。这场比赛会让我们从此扬名立万！', `MaleText_loc5`='現在是我們洗刷污名的機會了，賈達。我們會在這場聯賽中成為英雄的!', `MaleText_loc7`='Aquí llega nuestra oportunidad de redimirnos, Jadaar. ¡Con este torneo podríamos convertirnos en héroes!' WHERE `ID`=36744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 모르겠어. 이게 영웅이 되는 올바른 방법인지 확신이 안 서.', `MaleText_loc4`='我不知道。我不确定这坐骑能带我们走向辉煌。', `MaleText_loc5`='我不知道。我不確定這是否真會引領我們邁向英雄之路。', `MaleText_loc7`='No sé. No estoy seguro de que este sea el vehículo adecuado para alcanzar el heroísmo.' WHERE `ID`=36745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 때문에 주저하는 거야? 너는 건강하고 씩씩한데... 눈은 하나 없지만, 그렇다고 경기에 참가하지 말라는 법은 없잖아!', `MaleText_loc4`='你为什么退缩了？你这么矍铄、健壮……当然，你少了一只眼睛，但这绝不能让你临阵退缩！', `MaleText_loc5`='你為何退縮了呢?你的身子仍如此的硬朗，且熱衷於競技...或許少了隻眼睛，但你不該讓它阻止你參賽!', `MaleText_loc7`='¿Qué podría impedírtelo? Estás como un roble, bueno, te falta un ojo, pero eso no debería ser motivo para que no compitas.' WHERE `ID`=36746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 엘레크가 싫어. 정말로.', `MaleText_loc4`='我讨厌雷象，非常讨厌。', `MaleText_loc5`='我不喜歡伊萊克。非常不喜歡。', `MaleText_loc7`='Odio a los elekks. Con toda mi alma.' WHERE `ID`=36747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아. 그건 좀 문제네.', `MaleText_loc4`='呃，这倒是个问题。', `MaleText_loc5`='噢，那可能就是個問題了。', `MaleText_loc7`='Ah. Eso podría ser un problema.' WHERE `ID`=36748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 왜 경기에 안 나가?', `MaleText_loc4`='你为什么不去比赛？', `MaleText_loc5`='你為何不參賽了呢?', `MaleText_loc7`='¿Por qué no estás compitiendo?' WHERE `ID`=36749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 어... 여기 선리버를 이끄는 사람들하고 예전에 문제가 좀 있었거든. 그러니까 의견 충돌이랄까, 뭐 그런 거.', `MaleText_loc4`='我……曾和一个人有点不愉快，那家伙现在是夺日者的头目了。其实就吵了一架，换你你也会的。', `MaleText_loc5`='不久之前，我與奪日者高層之一的人起了一點...小衝突，最後不歡而散。', `MaleText_loc7`='Hace algún tiempo tuve un problemilla con uno de los individuos que ahora lideran a los Atracasol. Una discusión, si quieres llamarlo así.' WHERE `ID`=36750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으레 그렇듯이, 내가 막사로 들어갔을 때 말다툼이 일어났어.', `MaleText_loc4`='不用说了，那天我走进大帐，里面在吵架。', `MaleText_loc5`='不用再說了，當我走進亭閣的時候，我目睹了你們的爭論。', `MaleText_loc7`='No hace falta mencionar que cuando entré en el pabellón hubo un altercado.' WHERE `ID`=36751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 안 가르치겠대?', `MaleText_loc4`='他们拒绝训练你？', `MaleText_loc5`='他們拒絕訓練你嗎?', `MaleText_loc7`='¿Se negaron a entrenarte?' WHERE `ID`=36752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그것보다 창으로 뭔가를 하라잖아. 그런 천박한 일을 반복하는 건 내가 할 일이 아니야.', `MaleText_loc4`='他建议我拿着长矛去做点别的事。他说那里不是我进行粗野行为的地方。', `MaleText_loc5`='他建議我放下長槍，過點別的生活。這種粗俗的競技已不再適合我了。', `MaleText_loc7`='Me sugirió que usara la lanza para otra cosa. Repetir groserías no es lo mío.' WHERE `ID`=36753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 너도 알겠지만, 마상시합에 출전하면 서로 창으로 싸워야만 한다고.', `MaleText_loc4`='没错，这就对了，如果我们都参加这场锦标赛，那么最终的结果很可能是我们在沙场上一决胜负。', `MaleText_loc5`='你應該也明白，如果在聯賽中對上了，我們就必須把對方當做活生生的槍靶子。', `MaleText_loc7`='Supongo que te das cuenta de que es probable que tengamos que luchar entre nosotros si tomamos parte en el torneo.' WHERE `ID`=36754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 진다는 데에는 의심의 여지가 없어. 빠르고 재치있는 공격은 언제나 무식하게 힘으로 밀어붙이는 공격보다 우세하거든.', `MaleText_loc4`='在我看来你输定了。蛮力和武勇永远赢不了速度和智慧。', `MaleText_loc5`='我肯定你一定會落敗。在場上，速度與臨場反應凌駕於蠻力與頑強之上。', `MaleText_loc7`='No tengo duda alguna de que perderías. La velocidad y la inteligencia siempre triunfan sobre la fuerza bruta y la cabezonería.' WHERE `ID`=36755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 모두 정렬! 움직이는 게 있으면 쏜다. 쏘는 게 있으면... 움직인다!', `MaleText_loc4`='听好了，列队！看到会跑的东西就开枪。如果对面也开枪……就快跑吧！', `MaleText_loc5`='好，整隊!碰到動的東西，射了它。碰到會射的東西，就快閃!', `MaleText_loc7`='¡Muy bien, a formar! ¡Si se mueve, le pegáis un tiro! Si dispara... ¡movedlo!' WHERE `ID`=36756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출동 준비 완료.', `MaleText_loc4`='好了，该行动了。', `MaleText_loc5`='裝滿瓦斯準備上路。', `MaleText_loc7`='Con el tanque lleno y listo.' WHERE `ID`=36757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형님 나가신다!', `MaleText_loc4`='炸啊，宝贝儿！', `MaleText_loc5`='碰!寶貝!', `MaleText_loc7`='¡Bum, nena!' WHERE `ID`=36758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 여기에 있어서 놀라셨나요? 누구나 빨래는 해야 하죠. 그리고 물의 정령보다 더 좋은 빨래 방법이 있을까요?$B$B빨랫감과 아주 적은 요금만 가져오시면, 눈 깜짝할 사이에 전부 새 옷처럼 말끔해져 있을 거예요!', `MaleText_loc4`='在这见到我吃惊吗？每个人都需要干净衣服，除了找你的水元素帮忙，还有更好的办法吗？$B$B只需把你的衣服拿来，象征性的付点钱，不知不觉中你的衣服又变得清爽、干净！', `MaleText_loc5`='你看到我在這會感到驚訝嗎?每個人都需要乾淨的衣物，除了用自己的水元素來洗淨衣物之外，你還有更好的方法嗎?$B$B只要把你的髒衣服拿來，付上一筆小額的費用，轉眼之間你的衣物就變得乾淨又整潔了!', `MaleText_loc7`='¿Te sorprende verme aquí? Todo el mundo necesita ropa limpia y ¿qué mejor manera de lavarla que con tu propio elemental de agua?$B$BTan solo trae tu colada, paga una tarifa simbólica y antes de que te des cuenta, todo estará limpio.' WHERE `ID`=36759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비술사 티발린 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라더군요.', `MaleText_loc4`='奥术师泰拜林说你会借我一件战袍。', `MaleText_loc5`='秘法師泰巴林告訴我你可以借我一件特殊的外袍。', `MaleText_loc7`='El arcanista Tybalin dijo que podrías prestarme cierto tabardo.', `FemaleText_loc1`='신비술사 티발린 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라던데요.', `FemaleText_loc4`='奥术师泰拜林说你会借我一件战袍。', `FemaleText_loc5`='秘法師泰巴林告訴我你可以借我一件特殊的外袍。', `FemaleText_loc7`='El arcanista Tybalin dijo que podrías prestarme cierto tabardo.' WHERE `ID`=36760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋으시네요. 필요하시다는 그걸 막 빨랫감으로 받았거든요.', `MaleText_loc4`='你很走运。我刚装了些你需要的，正准备拿去洗。', `MaleText_loc5`='你的運氣真好。我要清洗的這堆衣物中正好有你要的。', `MaleText_loc7`='Tienes suerte. Tengo justo lo que necesitas en la tanda que voy a lavar ahora.' WHERE `ID`=36761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 빨랫감이랑 물동이 보이시죠? 뭐가 필요한지 부를 테니, 찾아서 빨래통 안에 넣어 주세요. 준비되셨죠?', `MaleText_loc4`='看到大堆的衣服和那桶水了吧？我会大声喊需要什么，你就把需要的扔进盆里。准备好了吗？', `MaleText_loc5`='看到水池旁的髒衣服還有水桶了嗎?我會講出接下來我所需要的東西，你就負責把它放進洗衣盆裡。準備好了嗎?', `MaleText_loc7`='¿Ves los montones de colada y el cubo de agua? Diré qué necesito a continuación y tú lo pones en la tina.' WHERE `ID`=36762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아니죠! 그렇게 하면 안 되죠. 처음부터 전부 다시 세탁하게 지금 가서 세제를 더 가져와야겠어요!', `MaleText_loc4`='哦，不！不应该这样的。现在我们不得不再弄些清洁剂重新开始了！', `MaleText_loc5`='噢，不!那個東西不對。現在我去找清潔劑，好讓我們可以重頭來過!', `MaleText_loc7`='¡Oh, no! Está mal. ¡Ahora tendré que conseguir más detergente para empezar de nuevo!' WHERE `ID`=36763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇죠! 바로 그거예요!', `MaleText_loc4`='干得好！', `MaleText_loc5`='做得好!', `MaleText_loc7`='¡Bien hecho!' WHERE `ID`=36764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 존재가 그를 대신하리라. 시간 낭비 마라.', `MaleText_loc4`='别人会取代他。你是在浪费时间。', `MaleText_loc5`='另一個會取代他的位置。你在浪費你的時間。', `MaleText_loc7`='Otro ocupará su lugar. Pierden el tiempo.' WHERE `ID`=36765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱한 노움 같으니. 그가 없었다면 저 짐승은 더 잘 싸웠으리라.', `MaleText_loc4`='[ph] 真是个倒霉的侏儒。要不是有他在，那只怪兽肯定打得更好。', `MaleText_loc5`='[ph]真可悲的地精。那隻野獸少了他反而會更強。', `MaleText_loc7`='[ph] What a miserable gnome. That beast would have better off fighting without him.' WHERE `ID`=36766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 벌목기는 아즈샤라에서만 작동하도록 프로그램되어 있습니다.', `MaleText_loc4`='警告：伐木机设计程式仅能在艾萨拉使用。', `MaleText_loc5`='警告:伐木機被設計成只有在艾薩拉時才會運作。', `MaleText_loc7`='Alerta: la trituradora está programada para funcionar solo en Azshara.' WHERE `ID`=36767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런.', `MaleText_loc4`='啊呀。', `MaleText_loc5`='啊。', `MaleText_loc7`='Ups.', `FemaleText_loc1`='이런.', `FemaleText_loc4`='啊呀。', `FemaleText_loc5`='啊。', `FemaleText_loc7`='Ups.' WHERE `ID`=36768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무식하게 힘이 뭐 어째? 내가 뚝심이 있는 덕에 우리가 여기까지 올 수 있었던 거라고, 뺀질아. 나랑 싸우면 너는 5초도 못 버틸걸.', `MaleText_loc4`='武勇？没有我的坚持不懈，咱们能有今天吗，你这种绣花枕头上去5秒就得趴下。', `MaleText_loc5`='頑強?若非我的毅力支持著我們，你以為我們能闖出今日這番名堂嗎，你這花拳繡腿的小子。你在場上根本撐不過五秒鐘。', `MaleText_loc7`='¿Cabezonería? Es mi perseverancia lo que nos ha traído hasta aquí, dandi. Tú no durarías ni cinco segundos.' WHERE `ID`=36769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈의 지겨운 허풍. 하지만, 마구간은 멀리 있고 괜찮은 음료는 가까이 있으니...', `MaleText_loc4`='你就胡诌吧。不管怎样，到马厩还有一段路，咱们带的酒还够。', `MaleText_loc5`='別再吹噓了。事實上，獸欄已離我們越來越遠，只有這兒的酒依然香醇。', `MaleText_loc7`='Típica chulería sin fundamento. Pero los establos están relativamente lejos y la bebida aquí es bastante decente.' WHERE `ID`=36770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기에 사용하는 창 말이야, 퍽 대충 만들었다고 들었는데... 난 손에 가시 박히는 거 싫다고.', `MaleText_loc4`='我听说那些长矛都是粗制的，我可不想扎的满手都是刺儿。', `MaleText_loc5`='我聽說比賽用的長槍也都磨鈍了。我可沒興趣拿些破銅爛鐵來比賽。', `MaleText_loc7`='También he oído que esas lanzas son rústicas. No me gustan las astillas.' WHERE `ID`=36771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 잘됐네.', `MaleText_loc4`='谁不是呢？', `MaleText_loc5`='這樣也好。', `MaleText_loc7`='Lo mismo digo.' WHERE `ID`=36772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기서 성공하면... 그담에 어떻게 되는지 알고 있겠지.', `MaleText_loc4`='嘿，要是我们成功了，你猜接下来会怎么样。', `MaleText_loc5`='如果我們成功了，你應該知道接下來會怎樣吧。', `MaleText_loc7`='Si lo conseguimos, ¿te das cuenta de qué vendría a continuación?' WHERE `ID`=36773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성채로 가지? 리치 왕의 가장 강력한 부하들하고 한판 벌이러 말이야.', `MaleText_loc4`='你说那冻冰的堡垒？当然是面对巫妖王最强大的爪牙。', `MaleText_loc5`='進軍城塞是吧?面對巫妖王麾下最強大的爪牙。', `MaleText_loc7`='La Ciudadela, ¿verdad? Enfrentarnos a los esbirros más poderosos del Rey Exánime.' WHERE `ID`=36774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 둘이서 새카맣게 몰려오는 언데드에 맞서는 거야.', `MaleText_loc4`='我们两个对阵茫茫的亡灵大军。', `MaleText_loc5`='咱們兩人對抗數之不盡的不死大軍。', `MaleText_loc7`='Nosotros dos contra la gran marea de no-muertos.' WHERE `ID`=36775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지.', `MaleText_loc4`='是啊。', `MaleText_loc5`='沒錯。', `MaleText_loc7`='Claro.' WHERE `ID`=36776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 좀 덜 위험하게 팔자 고칠 방법을 찾는 게 좋지 않을까?', `MaleText_loc4`='……也许我们应该去找个不那么危险的地方混口饭吃。', `MaleText_loc5`='...也許咱們該去別的地方碰碰運氣，至少不會令人喪命的那種。', `MaleText_loc7`='... Quizá deberíamos buscar nuestra fortuna en un lugar que sea menos... mortal.' WHERE `ID`=36777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 진짜 용기란 신중함을 기반으로 하는 법이니까.', `MaleText_loc4`='毕竟，慎重比勇气更重要。', `MaleText_loc5`='畢竟，懂得放手才是真英雄。', `MaleText_loc7`='Al fin y al cabo, la discreción es la mejor parte del valor.' WHERE `ID`=36778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 그냥 아무나 좀 이겨버려. 우린 여기 돈을 벌기 위해 있는 거니까!', `MaleText_loc4`='你们之中的某一个能不能快点把对方干掉？我们可是急着要拿钱呐！', `MaleText_loc5`='你們其中一個能趕快把另一個解決掉嗎?我們還急著要賺錢呢!', `MaleText_loc7`='¿Alguno de ustedes va a darse prisa en acabar con el otro? Aquí estamos intentando hacer un poco de pasta, ¿me oyen?' WHERE `ID`=36779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 두 바보 중에서 누가 이길지 내기를 걸고 있지.', `MaleText_loc4`='有人要赌赌这两个白痴谁会打赢么？', `MaleText_loc5`='接受所有人的下注，賭這兩個白癡誰能贏。', `MaleText_loc7`='Acepto apuestas sobre cuál de estos dos idiotas va a ganar.' WHERE `ID`=36780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들 둘 그만들 하라고! 누가 왔는지 좀 봐!', `MaleText_loc4`='你们两个白痴能消停下么，老板来了！', `MaleText_loc5`='你們這兩個蠢蛋給我住手。老大來了!', `MaleText_loc7`='Escondedlo, estúpidos. ¡Ha llegado el jefe!' WHERE `ID`=36781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑과 화염이라... 촌스럽기도 하지. 번개 맛 좀 보여줄까!', `MaleText_loc4`='暗影对火焰，你们可真复古。吃一记闪电！', `MaleText_loc5`='影和火，多奇特啊。騎上閃電!', `MaleText_loc7`='Sombra y fuego, qué pintoresco. ¡Cabalga sobre el relámpago!' WHERE `ID`=36782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음엔 꼭 맞춰주겠어!', `MaleText_loc4`='下一次我可不会打偏了！', `MaleText_loc5`='我下一次不會失誤!', `MaleText_loc7`='¡La próxima vez, no fallaré!' WHERE `ID`=36783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사술을 빨리 배워서 너희 둘을 평생 개구리로 만들어줄 테다!', `MaleText_loc4`='我正急着要学习妖术呐。你们俩可怜的后半生就只能以青蛙的模样度过了。', `MaleText_loc5`='我等不及要學妖術了。你們兩個將會變成青蛙度過你們可悲的一生!', `MaleText_loc7`='No puedo esperar a aprender a lanzar maleficios. ¡A ustedes dos los convertiré en ranas para el resto de sus vidas!' WHERE `ID`=36784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 두 사람은 어떻게 임원까지 올라간 거지?', `MaleText_loc4`='你们俩是怎么混到主管级的？', `MaleText_loc5`='你們兩個是怎麼被升到決策階層的?', `MaleText_loc7`='¿Cómo se las arreglaron para llegar a nivel de ejecutivo?' WHERE `ID`=36785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 영양가 없는 일을 참아줄 만큼 내 월급이 많지 않다고!', `MaleText_loc4`='要让我做这种无利可图的事，他们付的酬劳显然不够！', `MaleText_loc5`='如果要我做這種沒利潤的工作，他們付給我的錢遠遠不夠!', `MaleText_loc7`='¡No me pagan lo suficiente como para aguantar este comportamiento que aporta tan pocos beneficios!' WHERE `ID`=36786;
