UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여럿이 함께 일하니 정말 빠르죠? 깨끗한 빨래 중에 필요한 걸 가져가세요. 볼일이 끝나면 돌려주는 거 잊지 마시고요.', `MaleText_loc4`='看到人多好办事了吧？尽管从干净的里面挑你需要的吧，不过别忘了穿完了再送回来。', `MaleText_loc5`='看到分工合作之後，事情變得多輕鬆了嗎?直接從乾淨的衣物中拿你要的就可以了，但用完後記得要歸還。', `MaleText_loc7`='¿Ves qué fácil es cuando todo el mundo trabaja unido? Coge lo que necesites de la ropa limpia, pero no olvides devolverlo cuando hayas terminado.' WHERE `ID`=36791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 제가 뭔가 또 부탁할 거예요.', `MaleText_loc4`='一会儿我还有点别的事要你做。', `MaleText_loc5`='待會我有別的事情需要你的幫忙。', `MaleText_loc7`='En seguida voy a necesitar que hagas algo más.' WHERE `ID`=36792;
