UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 벌써 3번째야, 친구. 다음부터는 요금이 오른다고.', `MaleText_loc4`='事不过三，朋友。再多的话，我的费用就要增长了。', `MaleText_loc5`='已經三次了，老兄。再一次我就要收更多的錢了。', `MaleText_loc7`='Ya son 3 colega. Uno más y la tarifa sube.' WHERE `ID`=36807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 위험 수당이 청구될 거야, 친구.', `MaleText_loc4`='为了这个，你可是要付给我风险酬金的，朋友。', `MaleText_loc5`='老兄，這個我必須跟你收額外的安全費用。', `MaleText_loc7`='Voy a cobrarte un plus de peligrosidad por esto, colega.' WHERE `ID`=36808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저번에는 6미터도 더 못 가지 않았어?', `MaleText_loc4`='这次你甚至没有跑出去20尺。', `MaleText_loc5`='你上次連再多20英尺都做不到。', `MaleText_loc7`='Esta vez ni siquiera has mejorado 20 metros.' WHERE `ID`=36809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<다음과 같이 손으로 쓴 글씨가 적혀 있습니다.>$B$B          비밀 실험실 보관소$B     X. 니즐벡스 - 실험실장$B$B$B<안에는 아무도 없는 것 같습니다. 나중에 다시 와야 할지도 모르겠습니다.>', `MaleText_loc4`='<这是一段手写的文字：>$B$B          秘密实验室档案馆$B     X.尼泽柏克，实验室主管$B$B$B<看样子，现在没有人在家。也许你应该稍后再来？>', `MaleText_loc5`='<A hand-lettered sign reads:>$B$B          秘密實驗室檔案庫$B    X·尼姿爾貝克斯，實驗室負責人$B$B$B<看來現在好像沒人在家。或許晚點再回來看看?>', `MaleText_loc7`='<Un cartel escrito a mano dice:>$b$b          Archivo del Laboratorio Secreto$B      X. Nizzlebex. Director del laboratorio$B$B$B<Parece que ahora mismo no hay nadie. ¿Quizá deberías volver más tarde?>' WHERE `ID`=36810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적이라? 금시초문인데!$B$B제발 살려줘, 이렇게 죽기엔 난 아직 어리다고!!!', `MaleText_loc4`='海盗？不许提起海盗！！！$B$B别让他们抓住我，老板。我还年轻，还不想死！！！', `MaleText_loc5`='海賊?!不准任何人提到海賊!$B$B別讓他們抓到我，老大，我不該那麼年輕就死掉!!!', `MaleText_loc7`='¿Piratas? ¡¡¡Nadie dijo nada de piratas!!!$B$BNo dejes que me cojan, $gjefe:jefa;. ¡¡¡Soy demasiado joven para morir!!!' WHERE `ID`=36811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 거참 무겁겠는데.', `MaleText_loc4`='哇噢，你可装了不少。', `MaleText_loc5`='我的天，這還真是多啊。', `MaleText_loc7`='Vaya, menudo cargamento llevas.' WHERE `ID`=36812;
