UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입에서 축축한 맛이 나!', `MaleText_loc4`='我的嘴巴湿透了！', `MaleText_loc5`='我的嘴巴裡好像有血!', `MaleText_loc7`='¡Mi boca sabe mojada!' WHERE `ID`=36815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거... 마시는 건가?', `MaleText_loc4`='……是喝酒时间么？', `MaleText_loc5`='...痛飲時間?', `MaleText_loc7`='¿... Es hora de beber?' WHERE `ID`=36816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쿠아노스, 빨랫감을 그렇게 높이 던지면 안 돼! 자기 바지가 분수대에 들어간 걸 보면 에이타스 선리버가 무슨 표정을 짓겠어?!', `MaleText_loc4`='阿夸诺斯，别把衣服扔那么高了！我知道你不用看艾萨斯·夺日者在喷泉找到自己裤子时的脸色！', `MaleText_loc5`='阿夸諾斯，別再把衣服拋得那麼高了!當埃薩·奪日者看到他的褲子被扔到附近的水池裡，你或許不用面對他失望的表情，但我可要!', `MaleText_loc7`='¡Aquanos, deja de lanzar la ropa tan alto! ¡Tú no tuviste que ver la cara de Aethas Atracasol cuando encontró sus pantalones en la fuente!' WHERE `ID`=36817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 건강을 위해... 이 허풍쟁이야.', `MaleText_loc4`='干杯吧，话痨。', `MaleText_loc5`='為你的健康乾一杯，吹牛大王。', `MaleText_loc7`='¡A tu salud, charlatán!' WHERE `ID`=36818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 위해서도... 꼬맹아.', `MaleText_loc4`='干，小鬼。', `MaleText_loc5`='乾杯，臭小子。', `MaleText_loc7`='¡Y a la tuya, mocoso!' WHERE `ID`=36819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해적들은 제 계약에 없다고요!', `FemaleText_loc4`='海盗不在我的合同之内！', `FemaleText_loc5`='海賊這兩個字沒有出現在我的合約中!', `FemaleText_loc7`='¡Los piratas NO están en mi contrato!' WHERE `ID`=36820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 너무 강하군요. 당장 여길 떠나야 해요! 내 마법으로는 그를 잠깐만 저지할 수 있어요. 영웅들이여, 서두르세요!', `FemaleText_loc4`='太强大了。我们必须马上离开！我的魔法只能暂时拖住他。快来，英雄们！', `FemaleText_loc5`='他太強大了!我們必須立刻離開這裡!我的魔法只能困住他一小段時間。快來吧，英雄們!', `FemaleText_loc7`='Es demasiado poderoso. ¡Debemos abandonar este lugar ahora mismo! Mi magia podrá inmovilizarlo brevemente. ¡Vamos rápido, héroes!' WHERE `ID`=36821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 볼일이십니까, $c님?', `MaleText_loc4`='你来这要干什么，$c？', `MaleText_loc5`='你來這裡做什麼，$c?', `MaleText_loc7`='¿Qué haces aquí, $c?' WHERE `ID`=36822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 드디어 오셨군요. 이 고서를 최대한 빨리 얼음왕관으로 가져가야 합니다.', `MaleText_loc4`='你终于来了。我们必须尽快把这本宝典带到冰冠冰川。', `MaleText_loc5`='你終於到了。我們要盡快把這本書帶到寒冰皇冠去。', `MaleText_loc7`='Al fin has llegado. Tenemos que llevar este escrito a Corona de Hielo tan rápido como podamos.' WHERE `ID`=36823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고서를 가져갈 준비가 됐습니다, 마법학자 하소렐 님.', `MaleText_loc4`='魔导师哈瑟尔，我已经做好递送宝典的准备了。', `MaleText_loc5`='我已經準備好運送那本書了，博學者哈索瑞爾。', `MaleText_loc7`='Estoy listo para entregar el escrito, magister Hathorel.', `FemaleText_loc1`='고서를 가져갈 준비가 됐어요, 마법학자 하소렐 님.', `FemaleText_loc4`='魔导师哈瑟尔，我已经做好递送宝典的准备了。', `FemaleText_loc5`='我已經準備好運送那本書了，博學者哈索瑞爾。', `FemaleText_loc7`='Estoy lista para entregar el escrito, magister Hathorel.' WHERE `ID`=36824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버 놈들을 믿지 마십시오. 은빛십자군 앞에서 우리를 깎아내리고 싶어 혈안이 된 놈들입니다.', `MaleText_loc4`='永远不要相信那些夺日者。他们不遗余力的破坏我们和银色北伐军盟友的关系。', `MaleText_loc5`='永遠別相信奪日者。他們致力於暗中破壞我們在銀白十字軍盟友眼中的形象。', `MaleText_loc7`='No te fíes de los Atracasol. Están trabajando muy duro para desautorizarnos ante los ojos de nuestros aliados de la Cruzada Argenta.' WHERE `ID`=36825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 그만하세요! 아주 잠깐만 쉬게 해주세요!', `MaleText_loc4`='请停下来吧！我只是需要休息一会儿！', `MaleText_loc5`='拜託，快停止!我只需要休息一下!', `MaleText_loc7`='¡Por favor! ¡Basta! ¡Solo necesito descansar un momento!', `FemaleText_loc1`='제발, 그만하세요! 아주 잠깐만 쉬게 해주세요!', `FemaleText_loc4`='请停下来吧！我只是需要休息一会儿！', `FemaleText_loc5`='拜託，快停止!我只需要休息一下!', `FemaleText_loc7`='¡Por favor! ¡Basta! ¡Solo necesito descansar un momento!' WHERE `ID`=36826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧... 다시... 일을... 시작하겠습니다... 약속합니다.', `MaleText_loc4`='我会…回…去…工作…的…我…保证。', `MaleText_loc5`='我會...回...去...工作...我...保證。', `MaleText_loc7`='Volveré... al... trabajo... Lo... prometo.', `FemaleText_loc1`='곧... 다시... 일을... 시작하겠습니다... 약속해요.', `FemaleText_loc4`='我会…回…去…工作…的…我…保证。', `FemaleText_loc5`='我會...回...去...工作...我...保證。', `FemaleText_loc7`='Volveré... al... trabajo... Lo... prometo.' WHERE `ID`=36827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오셨군요! 선리버 놈들한테 당한 건 아닌가 걱정하던 참이었습니다. 얼음왕관에 있는 우리 대표자에게 고서를 가져갈 준비는 되셨습니까?', `MaleText_loc4`='找到你了！我几乎以为你已经被逐日者劫走了。你准备好把宝典递送给冰冠冰川的使者了吗？', `MaleText_loc5`='原來你在這裡!我還以為奪日者把你給截住了。你準備好要把這本書送到我們在寒冰皇冠的代表手上嗎?', `MaleText_loc7`='¡Ahí estás! Empezaba a pensar que te habían interceptado los Atracasol. ¿Estás $gpreparado:preparada; para entregar el escrito a nuestros representantes en Corona de Hielo?' WHERE `ID`=36828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관에 있는 연락책에게 고서를 가져가겠습니다, 신비술사여.', `MaleText_loc4`='我会把宝典交给我们在冰冠冰川的联系人的，奥法师。', `MaleText_loc5`='我會把這本書送到我們在寒冰皇冠的聯絡人手上，秘法師。', `MaleText_loc7`='Entregaré el tomo a nuestros contactos en Corona de Hielo, arcanista.', `FemaleText_loc1`='얼음왕관에 있는 연락책에게 고서를 가져가겠습니다, 신비술사여.', `FemaleText_loc4`='我会把宝典交给我们在冰冠冰川的联系人的，奥法师。', `FemaleText_loc5`='我會把這本書送到我們在寒冰皇冠的聯絡人手上，秘法師。', `FemaleText_loc7`='Entregaré el tomo a nuestros contactos en Corona de Hielo, arcanista.' WHERE `ID`=36829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버의 일원으로 다시 변장시켜 주시겠습니까?', `MaleText_loc4`='你能为我准备一套新的夺日者伪装吗？', `MaleText_loc5`='你可以恢復我的奪日者偽裝嗎?', `MaleText_loc7`='¿Podrías renovar mi disfraz de Atracasol?', `FemaleText_loc1`='선리버의 일원으로 다시 변장시켜 주시겠어요?', `FemaleText_loc4`='你能为我准备一套新的夺日者伪装吗？', `FemaleText_loc5`='你可以恢復我的奪日者偽裝嗎?', `FemaleText_loc7`='¿Podrías renovar mi disfraz de Atracasol?' WHERE `ID`=36830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험용', `MaleText_loc4`='THIS IS A TEST', `MaleText_loc5`='這是個測試', `MaleText_loc7`='ESTO ES UNA PRUEBA' WHERE `ID`=36831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 서약단으로 다시 변장시켜 주시겠습니까, 마법학자 하소렐 님?', `MaleText_loc4`='魔导师哈瑟尔，你能为我准备一套新的银色盟约伪装吗？', `MaleText_loc5`='你可以恢復我的白銀誓盟偽裝嗎，博學者哈索瑞爾?', `MaleText_loc7`='¿Podrías renovar mi disfraz de El Pacto de Plata, magister Hathorel?', `FemaleText_loc1`='은빛 서약단으로 다시 변장시켜 주시겠어요, 마법학자 하소렐 님?', `FemaleText_loc4`='魔导师哈瑟尔，你能为我准备一套新的银色盟约伪装吗？', `FemaleText_loc5`='你可以恢復我的白銀誓盟偽裝嗎，博學者哈索瑞爾?', `FemaleText_loc7`='¿Podrías renovar mi disfraz de El Pacto de Plata, magister Hathorel?' WHERE `ID`=36832;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신을 바라보며 으르렁대는 랩터의 입에서 침이 흘러내립니다.>$B$B<9번 실험체는 그간의 행적을 은폐하고자 지능이 증폭되지 않은 자신의 복제 생명체를 남기고 간 것 같습니다. 영리한 친구 같으니! 당신은 우주로 내보낸 존재에 대해 다시금 깊은 생각에 잠깁니다...>', `FemaleText_loc4`='<这头恐龙紧盯着你，大声咆哮着，嘴里不停地流出口水。>$B$B<看样子，九号实验品留下了一个她的克隆品，只是这个克隆品的智力没有像她一样得到强化。她这样做大概是为了隐藏自己的行迹。聪明的女孩！你在考虑你给这个宇宙带来了什么……>', `FemaleText_loc5`='<迅猛龍盯著你看，發出低吼，口水流得到處都是。>$B$B<看起來實驗體九號留了一隻智商未受到增幅的自我複製體來掩飾她的足跡。真是個聰明的女孩!你思考著你到底為這世界創造了一種什麼樣的生物...>', `FemaleText_loc7`='<El raptor te mira, gruñe y babea.>$b$b<Parece que Sujeto Nueve ha dejado atrás un clon no mejorado para cubrir su rastro. ¡Chica lista! Te preguntas qué has liberado exactamente en el cosmos...>' WHERE `ID`=36833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 한때 아서스를 존경했다니 믿을 수가 없군.', `MaleText_loc4`='我曾经遵从阿尔萨斯，这真让人难以置信。', `MaleText_loc5`='真不敢相信我曾經還很尊敬阿薩斯。', `MaleText_loc7`='Es duro creer que hubo un tiempo en el que respetaba a Arthas.', `FemaleText_loc1`='내가 한때 아서스를 존경했다니 믿을 수가 없어.', `FemaleText_loc4`='我曾经遵从阿尔萨斯，这真让人难以置信。', `FemaleText_loc5`='真不敢相信我曾經還很尊敬阿薩斯。', `FemaleText_loc7`='Es duro creer que hubo un tiempo en el que respetaba a Arthas.' WHERE `ID`=36834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자의 노예가 돼서, 죽은 자보다 더 못한 취급을 받고 있다니.', `MaleText_loc4`='我们都是王子的奴隶，我们的境遇生不如死。', `MaleText_loc5`='被我們自己的王子所奴役，我們受到的對待比死人還差。', `MaleText_loc7`='Esclavos de nuestro propio Príncipe, nos trata peor vivos que muertos.', `FemaleText_loc1`='왕자의 노예가 돼서, 죽은 자보다 더 못한 취급을 받고 있다니.', `FemaleText_loc4`='我们都是王子的奴隶，我们的境遇生不如死。', `FemaleText_loc5`='被我們自己的王子所奴役，我們受到的對待比死人還差。', `FemaleText_loc7`='Esclavos de nuestro propio Príncipe, nos trata peor vivos que muertos.' WHERE `ID`=36835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째 무기만 가져가고 옷은 안 벗겨갔나 몰라...', `MaleText_loc4`='我真感到吃惊，他们没把我们的穿戴和武器一块儿拿走…', `MaleText_loc5`='我很驚訝他們沒有在把我們的武器收走時，把衣服也一起扒光...', `MaleText_loc7`='Me sorprende que no nos quitaran la ropa con nuestras armas...', `FemaleText_loc1`='어째 무기만 가져가고 옷은 안 벗겨갔나 몰라...', `FemaleText_loc4`='我真感到吃惊，他们没把我们的穿戴和武器一块儿拿走…', `FemaleText_loc5`='我很驚訝他們沒有在把我們的武器收走時，把衣服也一起扒光...', `FemaleText_loc7`='Me sorprende que no nos quitaran la ropa con nuestras armas...' WHERE `ID`=36836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕한테 살아 있는 노예가 대체 왜 필요한 거지? 왜 우릴 다 죽이지 않는 거야?', `MaleText_loc4`='巫妖王为什么需要活着的仆人？他为什么不干脆把我们都杀了？', `MaleText_loc5`='為什麼巫妖王會需要活著的僕人?為什麼他不乾脆把我們全殺了?', `MaleText_loc7`='¿Para qué necesita sirvientes vivos el Rey Exánime? ¿Por qué no nos mata a todos?', `FemaleText_loc1`='리치 왕한테 살아 있는 노예가 대체 왜 필요한 거지? 왜 우릴 다 죽이지 않는 거야?', `FemaleText_loc4`='巫妖王为什么需要活着的仆人？他为什么不干脆把我们都杀了？', `FemaleText_loc5`='為什麼巫妖王會需要活著的僕人?為什麼他不乾脆把我們全殺了?', `FemaleText_loc7`='¿Para qué necesita sirvientes vivos el Rey Exánime? ¿Por qué no nos mata a todos?' WHERE `ID`=36837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사하러 왔을 뿐인데, 멕카토크 왕의 왕좌에 손댄 노움 마냥 붙잡히다니.', `MaleText_loc4`='我们是来这进行调查的时候被捕的，当时的样子就像个侏儒把手搭在梅卡托克国王的王座上。', `MaleText_loc5`='我們前來調查，然後就像是一個地精把手放在國王梅卡托克的王座上一樣被逮住。', `MaleText_loc7`='Vinimos aquí para investigar y nos atraparon como a un gnomo con las manos en el trono del rey Mekkatorque.', `FemaleText_loc1`='조사하러 왔을 뿐인데, 멕카토크 왕의 왕좌에 손댄 노움 마냥 붙잡히다니.', `FemaleText_loc4`='我们是来这进行调查的时候被捕的，当时的样子就像个侏儒把手搭在梅卡托克国王的王座上。', `FemaleText_loc5`='我們前來調查，然後就像是一個地精把手放在國王梅卡托克的王座上一樣被逮住。', `FemaleText_loc7`='Vinimos aquí para investigar y nos atraparon como a un gnomo con las manos en el trono del rey Mekkatorque.' WHERE `ID`=36838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관의 개 같으니. 머지않아 네놈은 종말을 맞을 게다.', `MaleText_loc4`='那头座狼是工头。他早晚会注意到即将发生的事。', `MaleText_loc5`='那隻監工的座狼。牠逮到靠近牠的東西只是時間的問題。', `MaleText_loc7`='El huargo de un capataz. Solo es cuestión de tiempo que reciba su merecido.', `FemaleText_loc1`='감독관의 개 같으니. 머지않아 네놈은 종말을 맞을 게다.', `FemaleText_loc4`='那头座狼是工头。他早晚会注意到即将发生的事。', `FemaleText_loc5`='那隻監工的座狼。牠逮到靠近牠的東西只是時間的問題。', `FemaleText_loc7`='El huargo de un capataz. Solo es cuestión de tiempo que reciba su merecido.' WHERE `ID`=36839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 구원군이 늦는군... 팔다리가... 떨어져 나갈 것 같아...', `MaleText_loc4`='呃…这么久…我的肋骨…撑不住了…', `MaleText_loc5`='啊...太久了...我的腿...撐不下去了...', `MaleText_loc7`='Argh... lleva mucho tiempo... Mis extremidades... no pueden seguir...', `FemaleText_loc1`='으으... 구원군이 늦는군... 팔다리가... 떨어져 나갈 것 같아...', `FemaleText_loc4`='呃…这么久…我的肋骨…撑不住了…', `FemaleText_loc5`='啊...太久了...我的腿...撐不下去了...', `FemaleText_loc7`='Argh... lleva mucho tiempo... mis extremidades... no pueden seguir...' WHERE `ID`=36840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 멈춰! 제발, 죽이지 마! 다 얘기할게!', `MaleText_loc4`='等等！停！别杀我！我把一切都告诉你！', `MaleText_loc5`='等等!停!別殺我，拜託!我什麼都告訴你!', `MaleText_loc7`='¡Esperen! ¡Paren! No me maten, por favor. ¡Les diré todo!' WHERE `ID`=36841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 찾는 건 주인님의 보금자리에 있지만, 들어가려면 티라누스를 이겨야 할 거야. 투영의 전당에서 서리한을 찾을 수 있어. 거기... 거기에 진실이 있어.', `MaleText_loc4`='你要找的就在主人的巢穴里，但要先干掉泰兰努斯才能进去。霜之哀伤就在映像大厅里……你们……你们能在它那里找到真相。', `MaleText_loc5`='你要找的東西就在主人的巢穴，但是你一定得摧毀提朗紐斯才有辦法進去。在倒影大廳中，你會找到霜之哀傷。它...它是真相所在。', `MaleText_loc7`='Lo que buscan se encuentra en la guarida del amo, pero deben acabar con Tyrannus para que puedan entrar. Dentro de las Cámaras de Reflexión encontrarán a la Agonía de Escarcha. Ella... guarda la verdad.' WHERE `ID`=36842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜야. 진짜야. 맹세해! 제발, 죽이지 마!!', `MaleText_loc4`='我发誓我没说谎！求你了！别杀我！', `MaleText_loc5`='我發誓那是真的!拜託，別殺我!!', `MaleText_loc7`='¡Les juro que es verdad! ¡¡No me maten, por favor!!' WHERE `ID`=36843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어억.. 안 돼!!', `MaleText_loc4`='啊…不！！', `MaleText_loc5`='噢...不!!', `MaleText_loc7`='Urgh... ¡No!' WHERE `ID`=36844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보잘것없는 네 목숨을 이 밴시 여왕이 왜 살려주어야 하지?', `FemaleText_loc4`='为什么女妖之王要饶恕你的小命？', `FemaleText_loc5`='為什麼女妖之王要饒過你可悲的性命?', `FemaleText_loc7`='¿Por qué debería perdonar tu miserable vida la Reina Alma en Pena?' WHERE `ID`=36845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리한이라고? 리치 왕은 절대 자기 검을 떼놓지 않는다. 만약 거짓말이라면...', `FemaleText_loc4`='霜之哀伤？巫妖王从不离开他的佩剑。如果你撒谎……', `FemaleText_loc5`='霜之哀傷?巫妖王向來劍不離身。如果你膽敢騙我...', `FemaleText_loc7`='¿La Agonía de Escarcha? El Rey Exánime nunca deja su espada. Si me mientes...' WHERE `ID`=36846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배신자다운 최후구나... 가자, 노예들을 해방하고 리치 왕의 방에 무엇이 있는지 직접 확인해야 한다.', `FemaleText_loc4`='叛徒就是这种下场。来吧，我们必须解救那些奴隶，再看看巫妖王的密室中都有什么。', `FemaleText_loc5`='最適合叛徒的下場。來吧，我們一定要釋放那些奴隸，看看阿薩斯的房間裡有些什麼。', `FemaleText_loc7`='Un final propio para un traidor. Vamos, debemos liberar a los esclavos y ver qué hay en la cámara del Rey Exánime.' WHERE `ID`=36847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 달아납니다!', `MaleText_loc4`='%s逃跑了！', `MaleText_loc5`='%s逃跑了!', `MaleText_loc7`='¡%s huye!' WHERE `ID`=36848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블랜드에서는 모집 전단을 눈여겨보세요. 작전을 진행할 땐 당신 같은 친구가 다시 와줬으면 하거든요.', `MaleText_loc4`='一定要注意一下哥布兰的征兵布告。一旦我们的行动顺利展开，很希望你能再次加入我们。', `MaleText_loc5`='注意在哥布島的徵人海報。一旦運作開始順利進行，我們非常希望看到你重回崗位。', `MaleText_loc7`='No te olvides de prestar atención a los carteles de reclutamiento que hay por la zona. Cuando pongamos la operación en marcha nos gustaría volver a contar contigo.' WHERE `ID`=36849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반가워요, $n.', `MaleText_loc4`='很高兴又见到你了，$n。', `MaleText_loc5`='很高興再次看到你，$n。', `MaleText_loc7`='Me legro de volver a verte, $n.' WHERE `ID`=36850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 이리 좀 와봐. 그 뭐랄까... "특별 계획"에 자네 도움이 필요해.', `MaleText_loc4`='$n!到这里来。我有一个“特别项目”，需要你来帮个忙。', `MaleText_loc5`='$n!過來過來。我有一項...「特殊計畫」需要你的協助。', `MaleText_loc7`='¡$n! Ven aquí. Necesito tu ayuda con un... "proyecto especial".' WHERE `ID`=36851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 놈! 네겐 죽음뿐이다!', `MaleText_loc4`='没用的虫子！死亡正等待着你！', `MaleText_loc5`='無用的小蟲!死亡是你唯一的下場!', `MaleText_loc7`='¡Mosquito inútil! ¡La muerte es todo lo que te espera!' WHERE `ID`=36852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 계신 성소에 그렇게 쉽게 들여보내리라고는 생각지 마라. 용기가 있다면 쫓아와 봐라.', `MaleText_loc4`='不要以为我会那么容易让你进入主人的密室。有本事放马过来吧。', `MaleText_loc5`='別以為我會輕易讓你進入主人的聖所。有種就來找我。', `MaleText_loc7`='No crean que les voy a permitir la entrada al sagrario de mi amo tan fácilmente. Síganme, si se atreven.' WHERE `ID`=36853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목숨을 구걸하는 너를 믿을 정도로 순진하지는 않지만, 들어는 보겠다.', `FemaleText_loc4`='我不会因为你的可怜而手下留情，有话快说吧。', `FemaleText_loc5`='我沒那麼天真，在相信你的哀求之前，我會先聽聽看。', `FemaleText_loc7`='No soy tan ingenua como para creerte cuando pides clemencia, pero te escucharé.' WHERE `ID`=36854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼마나 끔찍한 최후인가. 영웅들이여, 갑시다. 그 노움의 말이 진실인지 확인해야 해요. 아서스와 서리한을 떼어놓을 수 있다면, 그를 막을 기회가 있을지도 몰라요.', `FemaleText_loc4`='恶有恶报。来吧，英雄们。去看看那个侏儒说的是真是假。如果阿尔萨斯没了霜之哀伤，我们也许有机会阻止他。', `FemaleText_loc5`='多殘酷的結局。來吧，英雄們。我們一定要看看地精的故事是不是真的。如果我們能把阿薩斯與霜之哀傷分開，我們或許有機會阻止他。', `FemaleText_loc7`='Qué final tan cruel. Vamos, héroes. Veamos si la historia del gnomo es cierta. Si separamos a Arthas de la Agonía de Escarcha, quizás logremos detenerlo.' WHERE `ID`=36855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리한이 무방비로 놓여 있다니? 그럴 리가!', `FemaleText_loc4`='霜之哀伤无人守卫？不可能！', `FemaleText_loc5`='沒人看守霜之哀傷?不可能!', `FemaleText_loc7`='¿La Agonía de Escarcha está sin vigilancia? ¡Imposible!' WHERE `ID`=36856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼렉이 절 보냈습니다...', `MaleText_loc4`='卡雷派我来的……', `MaleText_loc5`='卡雷克派我過來...', `MaleText_loc7`='Me envía Kalec...', `FemaleText_loc1`='칼렉이 절 보냈습니다...', `FemaleText_loc4`='卡雷派我来的……', `FemaleText_loc5`='卡雷克派我過來...', `FemaleText_loc7`='Me envía Kalec...' WHERE `ID`=36857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼렉고스?! 네가 내세우는 게 그건가?$B$B어디 한번 잘 해보거라.', `MaleText_loc4`='卡雷苟斯？！这就是你来找我的好理由？$B$B那就祝你好运吧，伙计。', `MaleText_loc5`='卡雷苟斯?!你認為這會讓大家喜歡你?$B$B嘿，祝你好運，老兄。', `MaleText_loc7`='¡¿Kalecgos?! ¿Esa es tu mejor baza?$B$BPues buena suerte, colega.' WHERE `ID`=36858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 아닙니다. 이해를 못하시는군요. 당신을 도우려고 왔습니다.', `MaleText_loc4`='不，不，不，你不明白。我是来帮忙的。', `MaleText_loc5`='不是不是，你不懂。我是來這幫忙的。', `MaleText_loc7`='No, no, no. No lo entiendes. Estoy aquí para ayudar.', `FemaleText_loc1`='아니요, 아닙니다. 이해를 못하시는군요. 당신을 도우려고 왔습니다.', `FemaleText_loc4`='不，不，不，你不明白。我是来帮忙的。', `FemaleText_loc5`='不是不是，你不懂。我是來這幫忙的。', `FemaleText_loc7`='No, no, no. No lo entiendes. Estoy aquí para ayudar.' WHERE `ID`=36859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그렇겠지. 마법 유물에 사로잡혀 영혼의 세계에서 시간을 허비하고 있는 커다랗고 푸른 용을 구하러 말이야. 하지만 칼렉은 내가 마음을 바꾼 사실을 알지 못해.$B$B누군가를 만났거든.', `MaleText_loc4`='哈，你当然是来帮忙的，来拯救这个蓝色的大家伙，现在他已经彻底沉陷在灵魂世界里，完全被魔法物品迷住了。但卡雷苟斯并不明白，我已经翻开了新的一页。$B$B我与“某人”相遇了。', `MaleText_loc5`='你當然是來幫忙的，來這幫那隻大藍龍進行自我救贖。他把所有時間都花在靈魂世界，迷戀著那些魔法神器。卡雷不知道的是...我已經開始了新的生活了。$B$B我遇見了某人。', `MaleText_loc7`='Claro que sí. Has venido para salvar a ese enorme azul de sí mismo, que se pasa toda la vida en el mundo espiritual, obsesionándose con artefactos mágicos. Aunque Kalec no lo entienda, yo he pasado página.$B$BHe conocido a alguien.' WHERE `ID`=36860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가를 만났다고요? 이곳에 또 다른 용이 있는 줄은 몰랐습니다.', `MaleText_loc4`='与“某人”相遇？我还不知道这里有其它的龙。', `MaleText_loc5`='遇見了某人?我以為這裡已經沒有其他的龍族了。', `MaleText_loc7`='¿Has conocido a alguien? No sabía que hubiera otros dragones por ahí.', `FemaleText_loc1`='누군가를 만났다고요? 이곳에 또 다른 용이 있는 줄은 몰랐습니다.', `FemaleText_loc4`='与“某人”相遇了？我还不知道这里有其它的龙。', `FemaleText_loc5`='遇見了某人?我以為這裡已經沒有其他的龍族了。', `FemaleText_loc7`='¿Has conocido a alguien? No sabía que hubiera otros dragones por ahí.' WHERE `ID`=36861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용? 하! 웃기지 말거라.$B$B$r, 참으로 무례하기 그지없도다. 그녀가 바로 여기에 있지 않느냐!', `MaleText_loc4`='一头龙？哈！别说胡话了。$B$B你真是个无礼的$r，她就在这里！', `MaleText_loc5`='龍族?哈!別傻了。$B$B你知道你這樣很失禮嗎，$r。她就站在這裡!', `MaleText_loc7`='¿Un dragón? ¡Ja! No digas tonterías.$B$BSabes, $r, que no tienes ni pizca de educación. ¡Ella está ahí mismo!' WHERE `ID`=36862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...영혼의 치유사?
', `MaleText_loc4`='……那位灵魂医者？', `MaleText_loc5`='...靈魂醫者?', `MaleText_loc7`='¿... El ángel de la Resurrección?', `FemaleText_loc1`='...영혼의 치유사?
', `FemaleText_loc4`='……那位灵魂医者？', `FemaleText_loc5`='...靈魂醫者?', `FemaleText_loc7`='¿... El ángel de la Resurrección?' WHERE `ID`=36863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀에겐 "아나라"라는 엄연한 이름이 있다. 그녀에게 걸맞은 존경을 표해라.$B$B아나라와 자매들이 몇 번이나 널 죽음의 손아귀에서 구해주었는지 생각해 보았느냐? 너 역시 사려 깊지 못한 자들 중 하나로구나.', `MaleText_loc4`='她有名字。她的名字是安娜拉。你应该对她保持应有的尊敬。$B$B她和她的姐妹们有多少次将你从死亡的利爪中拯救出来？你这种人真是从来不懂得尊重他人，不是吗？', `MaleText_loc5`='她是有名字的，叫安娜拉。你最好給她應有的尊重。$B$B她和她的姊妹們幫助你從鬼門關走回來幾次?你們把這一切都當成理所當然，啊?', `MaleText_loc7`='Tiene nombre, sabes, es Anara. Más te vale que la trates con el respeto que se merece.$B$B¿Cuántas veces te han traído ella y sus hermanas de más allá de la muerte? Sois todos unos desconsiderados.' WHERE `ID`=36864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다. 무례하게 굴 생각은 없었습니다, 단지...', `MaleText_loc4`='很抱歉，我并不是要这样无礼，我只是……', `MaleText_loc5`='抱歉，我不是故意要表現的失禮的，我只是...', `MaleText_loc7`='Lo siento, no quería ser molestarte, solo...', `FemaleText_loc1`='미안합니다. 무례하게 굴 생각은 없었습니다, 단지...', `FemaleText_loc4`='很抱歉，我并不是要这样无礼，我只是……', `FemaleText_loc5`='抱歉，我不是故意要表現的失禮的，我只是...', `FemaleText_loc7`='Lo siento, no quería ser molestarte, solo...' WHERE `ID`=36865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안다, 알아. 우리는 안 된다는 거지? 용과 영혼의 치유사... 서로 다른 세계의 존재. 신체적인 건 말할 것도 없겠지!$B$B하지만 네가 틀렸다. 우리는 훨씬 더 깊은 교감을 나누니까. 아나라와 나는, 아주 친밀한 사이가 되었다.$B$B게다가 난 여기가 마음에 든다. 모험가라는 것들이 와서 이리저리 찔러대며 날 화나게 하는 일이 없거든.', `MaleText_loc4`='我知道。我知道。我们永远也不可能，对吗？龙和灵魂医者……两个完全不同的世界！更别提生理方面的问题了。$B$B但你错了。我们有着一种更深刻的联系。安娜拉和我，我们相爱了。$B$B而且我很喜欢这里。这里没有那些惹人讨厌，让我发怒的冒险者。', `MaleText_loc5`='我知道。我知道。我們永遠都無法在一起，對吧?龍族和靈魂醫者...我們在兩個不同的世界!更別提肉體上面的問題了。$B$B但你錯了，我們是以更深度的層次在進行交流。安娜拉和我是一體的。$B$B何況我也蠻喜歡這的。沒有無聊的冒險者會來對我挑釁和激怒我。', `MaleText_loc7`='Lo sé. LO SÉ. Lo nuestro no puede ser, ¿verdad? Un dragón y un ángel de la Resurrección... ¡Dos mundos diferentes! Por no hablar de los problemas psicológicos.$B$BPero no tienes razón. Nuestra conexión es mucho más profunda. Anara y yo estamos enamorados.$B$BAdemás, me gusta este sitio. No hay aventureros que vengan a molestarme y a pelear conmigo sin mediar provocación alguna.' WHERE `ID`=36866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 그 얘기를 하러 온 것이 아닙니다.', `MaleText_loc4`='这根本就不是我想说的。', `MaleText_loc5`='那跟我說的完全沒關係。', `MaleText_loc7`='Eso no es lo que yo he dicho.', `FemaleText_loc1`='저는 그 얘기를 하러 온 것이 아닙니다.', `FemaleText_loc4`='这根本就不是我想说的。', `FemaleText_loc5`='那跟我說的完全沒關係。', `FemaleText_loc7`='Eso no es lo que yo he dicho.' WHERE `ID`=36867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 계속해 보아라. 불필요한 화제로 이야기를 돌리려 하는구나.', `MaleText_loc4`='好吧，让我们回到正题。要知道，这些无谓的话题都是你搞出来的。', `MaleText_loc5`='那快說啊。是你把話題扯到這些無關緊要的事情上面。', `MaleText_loc7`='Bueno, pues acéptalo. Tú eres el que está dándole vueltas a todos estos temas innecesarios.' WHERE `ID`=36868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 그냥... 잊으십시오. 검은용군단이 당신을 사냥하러 여기에 왔다고 경고하러 왔습니다.', `MaleText_loc4`='我是……得了吧。我到这里来是为了警告你，黑龙正在这里捕杀你。', `MaleText_loc5`='我是...算了。我是來這警告你黑龍軍團已經來到這要獵殺你。', `MaleText_loc7`='Yo soy... Olvídalo. He venido para prevenirte de que el Vuelo Negro te busca.', `FemaleText_loc1`='전 그냥... 잊으십시오. 검은용군단이 당신을 사냥하러 여기에 왔다고 경고하러 왔습니다.', `FemaleText_loc4`='我是……得了吧。我到这里来是为了警告你，黑龙正在这里捕杀你。', `FemaleText_loc5`='我是...算了。我是來這警告你黑龍軍團已經來到這要獵殺你。', `FemaleText_loc7`='Yo soy... Olvídalo. He venido para prevenirte de que el Vuelo Negro te busca.' WHERE `ID`=36869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그거? 초토화된 땅과 무분별한 살육에 눈먼 자들을 눈치채지 못했을까 봐? 내가 그 정도로 늙진 않았다.', `MaleText_loc4`='哦，是吗？你以为我没有注意到被烧焦的土地和那些无意义的杀戮吗？无论他们到哪里，都会留下这些痕迹。我还没有老糊涂呢。', `MaleText_loc5`='噢，那個啊?你以為我沒注意到大地被灼傷和那些被濫殺無辜的生命嗎?我還沒老成那樣!', `MaleText_loc7`='Oh, ¿eso? ¿Crees que no me había dado cuenta de la tierra abrasada y toda esas masacres que son marca de la casa? No soy TAN viejo.' WHERE `ID`=36870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 알고 계셨다고요? 왜 저들을 막으러 가지 않습니까?', `MaleText_loc4`='你已经知道了？那为什么你不阻止他们？', `MaleText_loc5`='你早就知道了?那你為什麼不阻止他們?', `MaleText_loc7`='¿Ya lo sabías? ¿Por qué vas a detenerlos?', `FemaleText_loc1`='이미 알고 계셨다고요? 왜 저들을 막으러 가지 않습니까?', `FemaleText_loc4`='你已经知道了？那为什么你不阻止他们？', `FemaleText_loc5`='你早就知道了?那你為什麼不阻止他們?', `FemaleText_loc7`='¿Ya lo sabías? ¿Por qué vas a detenerlos?' WHERE `ID`=36871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 그래야 하지? 그들은 내가 어디에 있는지 전혀 감도 못 잡고 있지 않느냐. 이곳에서 이미 발견한 유물에는 어떠한 해도 끼치지 못할 것이다.$B$B사악함과 파괴가 놀랍도록 편리한 점은, 결국 자기네들끼리 물어뜯는다는 점이지.', `MaleText_loc4`='干嘛要自找烦恼？他们绝不可能知道我在哪里。他们也不会损害这里已经被发现的古物。$B$B而且呢，邪恶和毁灭有一个有趣的共同点，那就是它们最终会把自己摧毁。', `MaleText_loc5`='幹麻要那麼麻煩?他們根本對我人在哪一點頭緒都沒有。他們無法對這四周已經被尋獲的神器造成任何傷害。$B$B有趣的是，邪惡和毀滅常常在最後會互相爭鬥而兩敗俱傷。', `MaleText_loc7`='¿Para qué molestarse? En realidad no tienen ni idea de dónde estoy. No van a dañar los artefactos ya encontrados que hay por aquí.$B$BDe todas maneras, una de las cosas más divertidas del mal y la destrucción que es que al final, llega un momento en el que tienden a destruirse maléficamente los unos a los otros.' WHERE `ID`=36872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 칼렉고스는 그들을 멈추고자 애쓰고 있습니다. 당신의 도움이 필요해요.', `MaleText_loc4`='但卡雷苟斯正竭尽全力要阻止他们。他需要你的帮助。', `MaleText_loc5`='但卡雷苟斯已經在奮力對抗他們了。他需要你的幫忙。', `MaleText_loc7`='Pero Kalecgos ya ha salido para intentar detenerlos. Necesita tu ayuda.', `FemaleText_loc1`='하지만 칼렉고스는 그들을 멈추고자 애쓰고 있습니다. 당신의 도움이 필요해요.', `FemaleText_loc4`='但卡雷苟斯正竭尽全力要阻止他们。他需要你的帮助。', `FemaleText_loc5`='但卡雷苟斯已經在奮力對抗他們了。他需要你的幫忙。', `FemaleText_loc7`='Pero Kalecgos ya ha salido para intentar detenerlos. Necesita tu ayuda.' WHERE `ID`=36873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 쫓고 있단 말이냐? 그리고 널 보내 도움을 요청했단 말이지? 간절히 빌더냐? 눈물을 흘리더냐?$B$B<먼 곳을 바라보며 이를 드러내고 싱긋 웃음을 짓는 아주어고스>$B$B그게 말이다, 그를 구하려 든다 해도 이미 만회할 방법이 없느니라. 날 태양샘에 있는 작은 여자아이처럼 만들어 부릴 수는 있겠지.$B$B네 기분을 상하게 할 의도는 없다, 아나라.', `MaleText_loc4`='他正在对付黑龙？而且派你来向我寻求帮助？他有没有跪求？有没有泪流满面？$B$B<艾索雷葛斯向远处望去，一脸露齿的坏笑。>$B$B你知道，要是我去替他解了围，他可就欠了我一辈子的人情。也许他得帮我也做一个太阳井妹子什么的来还这人情。$B$B没冒犯的意思，安娜拉。', `MaleText_loc5`='他行動了?而且還讓你來尋求我的協助?他有求我嗎?有流淚嗎?$B$B<艾索雷葛斯向遠方望去，臉上出現了露出利牙的詭異笑容。>$B$B你知道嗎，如果他被我所救，他會一輩子都活在自悲之中。或許他會幫我用太陽之井做隻小女朋友，就像他那隻一樣?$B$B別在意啊，安娜拉。', `MaleText_loc7`='¿Va tras ellos? ¿Y te ha enviado para pedirme ayuda? ¿Suplicó? ¿Lloró?$B$B<Azuregos mira fijamente a lo lejos mientras una sonrisa llena de dientes se abre paso en su rostro.>$B$BSabes, si acudo a su rescate, nunca superará la vergüenza. Quizá consiga que me haga una pequeña chica de esas de La Fuente del Sol para mí solo.$B$BNo te ofendas, Anara.' WHERE `ID`=36874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 오실 겁니까?', `MaleText_loc4`='你会来吗？', `MaleText_loc5`='那你是願意去囉?', `MaleText_loc7`='¿Entonces acudirás?', `FemaleText_loc1`='그럼 오실 겁니까?', `FemaleText_loc4`='你会来吗？', `FemaleText_loc5`='那你是願意去囉?', `FemaleText_loc7`='¿Entonces acudirás?' WHERE `ID`=36875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠다, 알겠어. 그를 구하러 가마.$B$B허나 그 자기중심적인 영웅 행세에 휘말려 들진 마라! 그저 관심 받길 좋아하는 것뿐이니. 보나마나 다음 위상이 되리라 기대하고 있는 게다. 우습기도 하지.', `MaleText_loc4`='是的，是的，我会去救他。$B$B不过你可别被他的救世英雄的小故事迷惑了！他只是想引起别人的注意。我发誓，他一定想成为下一个守护巨龙。这真可笑。', `MaleText_loc5`='好吧好吧，我會去救他的。$B$B不過你不要被他那自以為是的英雄主義給騙了!他只是喜歡吸引大家的注意罷了。我敢說，他甚至認為他會成為下一任的巨龍守護。真好笑。', `MaleText_loc7`='Sí, sí, acudiré a su rescate.$B$B¡Pero no te dejes engañar por su pose de héroe egocéntrico! Le gusta llamar la atención. Te juro que cree que va a ser el próximo Aspecto. De risa.' WHERE `ID`=36876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그에게 바로 알리겠습니다. 검은담비 마루에서 만나죠.', `MaleText_loc4`='我这就去让他知道。我们在漆黑山脊见面吧。', `MaleText_loc5`='我馬上讓他知道。我們在黑角嶺見。', `MaleText_loc7`='Voy a avisarle inmediatamente. Reúnete con nosotros en Cumbre Cebellina.', `FemaleText_loc1`='그에게 바로 알리겠습니다. 검은담비 마루에서 만나죠.', `FemaleText_loc4`='我这就去让他知道。我们在漆黑山脊见面吧。', `FemaleText_loc5`='我馬上讓他知道。我們在黑角嶺見。', `FemaleText_loc7`='Voy a avisarle inmediatamente. Reúnete con nosotros en Cumbre Cebellina.' WHERE `ID`=36877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 곧 갈 테니 안달복달하지 말거라.', `MaleText_loc4`='好了，好了，别催我。', `MaleText_loc5`='好好，我馬上就出發了。別像個老人一樣囉哩囉唆的。', `MaleText_loc7`='Sí, sí. Voy de camino. No te pongas de los nervios, ¿eh?' WHERE `ID`=36878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발 장치 조립이라고? 이것들 봐, 이건 장난감이 아냐.', `MaleText_loc4`='你管这个叫触发装置？这可不是玩具！', `MaleText_loc5`='你們說那是個手動工具?仔細聽好了，這不是個玩具!', `MaleText_loc7`='¿Llamáis a esto un montaje de gatillo? ¡Esto no es un juguete, tíos!' WHERE `ID`=36879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 강화해 봐, 호르빅. 너도, 글리닉스! 그래플해머는 완벽한 게 아니면 인정하지 않는다고!', `MaleText_loc4`='再用心一些，霍维奇。你也是，格伦尼克斯！钩锤只需要绝对的完美。', `MaleText_loc5`='把它組裝好，賀維克。你也是，葛尼克斯!繫錘是個完美主義者。', `MaleText_loc7`='Espabila, Horvik. ¡Tú también Gleenix! Martillazos no va a conformarse con menos que la perfección.' WHERE `ID`=36880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐야? 차단된 노리쇠에 쓸 계단 모양 나사산이 필요하다고 했잖아! 전체 구동 장치를 완전히 다시 설계해야 해!', `MaleText_loc4`='这是什么？我告诉过你，我要把螺纹压在阻断螺栓上！我们现在只能重新制作整个装载系统了！', `MaleText_loc5`='這是什麼?我跟你說過中斷閉鎖機上面必須使用分段鋼絲!我們必須全部重新設計整個工程結構!', `MaleText_loc7`='¿Qué es esto? ¡Te dije que quería roscas reforzadas en el pasador del martillo! ¡Vamos a tener que rediseñar todo el sistema del cargador!' WHERE `ID`=36881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블래즈코위즈, 거기 반동 실린더에 기름칠이나 해. 똑바로 안 하면 기름진 네 면상을 직접 문지를 테니.', `MaleText_loc4`='布拉科维兹，你最好给这些反冲设备涂好油，否则我就把油涂到你的脸上。', `MaleText_loc5`='布雷克維茲，你最好幫那緩衝缸上點油，不然我會拿你的臉幫它上油。', `MaleText_loc7`='Blazcowiz, será mejor que engrases bien esos cilindros de retroceso. O lo engrasaré con tu CARA.' WHERE `ID`=36882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플링크, 수공 반동 연결장치의 압축 자료는 아직 수집하지 못했나? 빨리빨리 해!', `MaleText_loc4`='弗林克，你还没有为液压反弹起重器编译好压缩数据？赶快，赶快！', `MaleText_loc5`='芬利克，你把液壓氣動後座機的資料壓縮整理好了沒?快點快點!', `MaleText_loc7`='Flink, ¿ya has recopilado los datos sobre la compresión del gato de retroceso hidroneumático? Venga, ya, ya.' WHERE `ID`=36883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 그 역반동 복구 실린더인가? 쓰레기라고 하는 게 맞겠는데. 다시 만들어!', `MaleText_loc4`='这就是复位减震桶吗？在我看来就是垃圾。重新制造！', `MaleText_loc5`='這應該是一個反後座恢復缸嗎?我稱它為「反恢缸」。再做一個出來!', `MaleText_loc7`='¿Se supone que esto es un cilindro de recuperación de contrarretroceso? Más bien di que es un BODRIO. ¡Constrúyelo de nuevo!' WHERE `ID`=36884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저흰 준비됐습니다! 가시죠!', `MaleText_loc4`='我们准备好了！出发！', `MaleText_loc5`='我們準備好了!出發吧!', `MaleText_loc7`='¡Estamos listos! ¡Vámonos!', `FemaleText_loc1`='저흰 준비됐어요! 가시죠!', `FemaleText_loc4`='我们准备好了！出发！', `FemaleText_loc5`='我們準備好了!出發吧!', `FemaleText_loc7`='¡Estamos listos! ¡Vámonos!' WHERE `ID`=36885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그를 오랫동안 막을 순 없어요! 어서 떠나야 합니다!', `FemaleText_loc4`='我没办法阻挡他太久，我们必须马上离开！', `FemaleText_loc5`='我沒辦法困住他太久!我們一定要立刻離開!', `FemaleText_loc7`='No puedo retenerlo mucho tiempo, ¡debemos marcharnos!' WHERE `ID`=36886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 이곳에서 무슨 일이 일어나고 있는 겁니까?!?!', `MaleText_loc4`='这里到底发生了什么事？！？！', `MaleText_loc5`='這裡到底發生了什麼事?!?!', `MaleText_loc7`='¡¡¿Qué diablos pasa aquí?!!' WHERE `ID`=36887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행기는 원래 몇 번 떨어져 봐야 제대로 길들일 수 있지.$B$B정신 멀쩡한 고블린이라면 흠집 하나 없는 비행기는 몰지 않아.', `MaleText_loc4`='只有几次漂亮的坠毁才能真正“磨砺”一台飞行器。$B$B任何头脑正常的地精都不会只安心于安全的飞行。', `MaleText_loc5`='必須要墜個幾次機才能駕馭好飛行器。$B$B沒有哥布林生下來就會開。', `MaleText_loc7`='Para tener una máquina voladora "curtida" de verdad, hace falta estrellarse con ella unas cuantas veces.$B$BNingún goblin en su sano juicio pilotaría una máquina inmaculada.' WHERE `ID`=36888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래플해머가 뭘 원한다고? 나보고 자기가 만든 폭탄을 들고 항만을 가로지르라고? 완전히 미쳤구만!$B$B자넬 위해 여기 있는 자이로콥터에 자동조종장치를 장착해 놨어. 행운을 빈다고!$B$B난 집에 가 있을게.', `MaleText_loc4`='钩锤想要我做什么？他终于完成了他的炸弹，然后他想让我把它投到海湾的那头去？不行！$B$B听着，我会帮你把我的一架直升机设定为自动驾驶状态。然后我还会祝你好运！$B$B接着我就要到掩体里去了。', `MaleText_loc5`='繫錘要我幹什麼?他總算完成了他的炸藥然後要我幫他把它們飛過港口?長官，我還是不了!$B$B我會把我其中一台旋翼機設定為自動操作。祝你好運!$B$B我?我會去躲起來。', `MaleText_loc7`='¿Martillazos quiere que haga QUÉ? Por fin ha terminado su bomba, ¿y ahora quiere que YO la haga volar sobre el puerto? ¡Ni hablar!$B$BMira, te prepararé unos de mis girocópteros con el piloto automático puesto. ¡Buena suerte!$B$BYo estaré en el refugio.' WHERE `ID`=36889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이로콥터를 주십시오, 프리즈.', `MaleText_loc4`='费利兹，把直升机给我。', `MaleText_loc5`='佛利茲，把旋翼機給我就好了。', `MaleText_loc7`='Tú dame el girocóptero, Friz.', `FemaleText_loc1`='자이로콥터를 주십시오, 프리즈.', `FemaleText_loc4`='费利兹，把直升机给我。', `FemaleText_loc5`='佛利茲，把旋翼機給我就好了。', `FemaleText_loc7`='Tú dame el girocóptero, Friz.' WHERE `ID`=36890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스텐! 이건 전부 다 당신 때문입니다!', `MaleText_loc4`='这全都是你的错，斯登！', `MaleText_loc5`='這都是你的錯，史特登!', `MaleText_loc7`='¡Todo esto es culpa TUYA, Sten!' WHERE `ID`=36891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주어고스를 찾고 있나? 시련의 산마루의 공포, 폭풍의 만에 군림하는 재앙을? 아즈샤라의 모든 마법의 지배자를?$B$B그렇다면 제대로 찾아왔구나.$B$B<희미한 미소를 짓는 아주어고스>', `MaleText_loc4`='你在找艾索雷葛斯？痛苦海岸灾星？风暴海湾之祸？艾萨拉的魔法之主？$B$B好吧，你找到他了。$B$B<艾索雷葛斯似乎是在微笑。>', `MaleText_loc5`='你在找艾索雷葛斯?那個痛苦海岸的惡夢?風暴海灣的天譴?艾薩拉一切法力的主人?$B$B嗯，你已經找到他了。$B$B<艾索雷葛斯看起來正在微笑。>', `MaleText_loc7`='¿Buscas a Azuregos? ¿Pesadilla de la Costa Amarga? ¿Azote de la Bahía de la Tempestad? ¿Señor de toda la magia de Azshara?$B$BBien, le has encontrado.$B$B<Parece que Azuregos sonríe.>' WHERE `ID`=36892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 놀음도 이제 지겹군!', `MaleText_loc4`='我受够了！', `MaleText_loc5`='我受夠了!', `MaleText_loc7`='¡Ya he tenido suficiente!' WHERE `ID`=36893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 그렇다, 그림토템.', `MaleText_loc4`='我也一样，恐怖图腾。', `MaleText_loc5`='我也是，恐怖圖騰。', `MaleText_loc7`='Yo también, Tótem Siniestro.' WHERE `ID`=36894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 말아요, 젊은 친구. 우리가 영원히 함께할 수 없다는 것... 이미 알고 있었어요. 전 괜찮아요.$B$B하지만 당신은 이곳에 있어선 안 돼요. 아직 때가 되지 않았어요. 산 자들의 세계로 돌아갈 수 있도록 도와줄게요.$B$B이 일은 내게 맡겨요.', `FemaleText_loc4`='不必担心，年轻人。我知道我们的安排只是……暂时性的。我会没事的。$B$B但是你，你不属于这里。现在你的时候还没有到。我会帮助你返回生命世界。$B$B这是我的责任。', `FemaleText_loc5`='別擔心，年輕人。我知道我們的安排只是...暫時性的。我不會有事的。$B$B你呢，卻不屬於這裡。你的時候還沒到。我會幫助你回到活人的國度。$B$B這是我的責任。', `FemaleText_loc7`='No te preocupes, joven. Sabía que nuestro arreglo era... Temporal. Estaré bien.$B$BTú, sin embargo, no deberías estar aquí. Todavía no ha llegado tu hora. Te ayudaré en tu viaje de regreso al reino de los vivos.$B$BYo invito.' WHERE `ID`=36895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바인! 네놈이 나타나다니! 붙잡아라!', `MaleText_loc4`='贝恩！你暴露了！去干掉他！', `MaleText_loc5`='貝恩!你終於出現了!抓住他!', `MaleText_loc7`='¡Baine! ¡Has aparecido! ¡A POR ÉL!' WHERE `ID`=36896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주어고스를 구했는지는 모르나, $r, 네 목숨은 여기서 끝이다.', `MaleText_loc4`='你也许拯救了艾索雷葛斯，$r，但你的生命也将在这里结束。', `MaleText_loc5`='你或許救了艾索雷葛斯一命，$r，但你的命將在此終結。', `MaleText_loc7`='Puede que hayas salvado a Azuregos, $r, pero tu vida termina aquí.' WHERE `ID`=36897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생각이 틀렸다, 도마뱀 같은 녀석.', `MaleText_loc4`='我不这样想，小蜥蜴。', `MaleText_loc5`='我可不這樣認為，小龍。', `MaleText_loc7`='No lo creo, pequeña vermis.' WHERE `ID`=36898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 네 아비처럼 치욕스러운 죽음을 맞아라.', `MaleText_loc4`='你会带着羞耻死去，就像你可怜的父亲一样。', `MaleText_loc5`='你會和你那可悲的父親一樣在恥辱中死去。', `MaleText_loc7`='Morirás cubierto de vergüenza como tu padre.' WHERE `ID`=36899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 겁쟁이의 독과 헬스크림의 분노에 기대 우리 아버지를 꺾었지.', `MaleText_loc4`='杀死我父亲的不仅仅是地狱咆哮的狂怒，还有懦夫的毒药。', `MaleText_loc5`='我父親是被孬種下了毒，加上地獄吼的憤怒才被擊敗的', `MaleText_loc7`='Para matar a mi padre hicieron falta el veneno de un cobarde y la furia de Grito Infernal.' WHERE `ID`=36900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 어쩔 테냐?', `MaleText_loc4`='你们有机会吗？！', `MaleText_loc5`='你們以為有機會嗎?!', `MaleText_loc7`='¿CREES QUE TIENES ALGUNA POSIBILIDAD?' WHERE `ID`=36901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 뜻을 방해하게 둘 것 같으냐!', `MaleText_loc4`='[PH] 不要企图违抗主人的意愿！', `MaleText_loc5`='[PH]別想違背主人的意志!', `MaleText_loc7`='[PH] Do not think to defy the master''s will!' WHERE `ID`=36902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집 물어내!', `MaleText_loc4`='为什么你要破坏我们的家园？！', `MaleText_loc5`='你為什麼要弄壞我們的家?!', `MaleText_loc7`='¿Por qué tú romper nuestra casa?' WHERE `ID`=36903;
