UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 저희는 폭탄 터트리고 총 쏘는 게 적성에 맞습니다. 수신호 따윈 필요 없다고요.', `MaleText_loc4`='长官，爆炸和枪炮的声音应该已经让我们暴露了。你不必再打手语了。', `MaleText_loc5`='長官，我認為炸藥和火藥已經曝露我們的位置了，你不需要使用手語暗號。', `MaleText_loc7`='Señor, creo que las explosiones y los disparos ya nos han delatado. No creo que haga falta que haga señales con las manos.' WHERE `ID`=36935;
