UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이 당신과 함께합니다. 그들에게 무엇을 바라십니까?', `MaleText_loc4`='元素在眷顾你。你要向它们要求什么？', `MaleText_loc5`='元素喜歡你。你對它們有什麼要求?', `MaleText_loc7`='Los elementos te favorecen. ¿Qué les pedirás?', `FemaleText_loc1`='정령이 당신과 함께합니다. 그들에게 무엇을 바라십니까?', `FemaleText_loc4`='元素在眷顾你。你要向它们要求什么？', `FemaleText_loc5`='元素喜歡你。你對它們有什麼要求?', `FemaleText_loc7`='Los elementos te favorecen. ¿Qué les pedirás?' WHERE `ID`=36938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령은 변덕과 편파가 심합니다. 미안하지만 당신에게는 아무런 도움도 줄 수 없군요.', `MaleText_loc4`='元素变幻莫测，没有受过训练的双手很难控制它们。很抱歉，我并不需要你。', `MaleText_loc5`='元素不是忠誠的，最好別讓沒受過訓練的人來跟它們打交道。很抱歉，我不需要你的幫忙。', `MaleText_loc7`='Los elementos son veleidosos y es mejor mantenerlos alejados de manos no entrenadas. Lo siento, pero no necesito las tuyas.', `FemaleText_loc1`='정령은 변덕과 편파가 심합니다. 미안하지만 당신에게는 아무런 도움도 줄 수 없군요.', `FemaleText_loc4`='元素变幻莫测，没有受过训练的双手很难控制它们。很抱歉，我并不需要你。', `FemaleText_loc5`='元素不是忠誠的，最好別讓沒受過訓練的人來跟它們打交道。很抱歉，我不需要你的幫忙。', `FemaleText_loc7`='Los elementos son veleidosos y es mejor mantenerlos alejados de manos no entrenadas. Lo siento, pero no necesito las tuyas.' WHERE `ID`=36939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우...! 매력적인데!', `MaleText_loc4`='哦……看上去很性感！', `MaleText_loc5`='噢噢噢...看起來很性感!', `MaleText_loc7`='Ooooh... ¡es sexy!' WHERE `ID`=36940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충직하고 성실한 수습생이 이렇게 많으니, 전 정말 복 받은 사람입니다. 제 연구 업적도 충분한 실험 대상 없이는 불가능했을 겁니다.', `MaleText_loc4`='能拥有如此众多忠诚而具有献身精神的学徒，这是我的幸运。如果没有这些测试样品，我的工作也不可能进行。', `MaleText_loc5`='能有那麼多忠誠的學生是我三生有幸。如果沒有那麼多的實驗體，我的研究便不可以進行下去。', `MaleText_loc7`='Realmente es una bendición que tenga tantos aprendices leales y dedicados. Mi trabajo no sería posible si no tuviera sujetos para someterlos a pruebas.' WHERE `ID`=36941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 실렘 님, 탑으로 가는 차원문을 열어주시겠습니까?', `MaleText_loc4`='大法师克希雷姆，你能为我打开一个前往你的高塔的传送门吗？', `MaleText_loc5`='大法師克希雷姆，你可以為我打開一個到你塔中的傳送門嗎?', `MaleText_loc7`='¿Puedes abrirme un portal hacia tu torre, archimago Xylem?', `FemaleText_loc1`='대마법사 실렘 님, 탑으로 가는 차원문을 열어주시겠습니까?', `FemaleText_loc4`='大法师克希雷姆，你能为我打开一个前往你的高塔的传送门吗？', `FemaleText_loc5`='大法師克希雷姆，你可以為我打開一個到你塔中的傳送門嗎?', `FemaleText_loc7`='¿Puedes abrirme un portal hacia tu torre, archimago Xylem?' WHERE `ID`=36942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신처로 통하는 차원문을 열어두었으니 가서 좀 쉬십시오. 아침에 연구를 계속하려면 빠르고 쥐방울만한 친구가 필요하니 그때까지 살아 있어야 합니다.', `MaleText_loc4`='我已经打开了通向我的休养之地的传送门。去休息一下吧。当我们的研究在早晨重新开始的时候，我需要你保持充沛的活力，机敏的小东西。', `MaleText_loc5`='我已經打開一個到我修行所的傳送門了。快去休息吧，我明天一早還需要活潑的你才能繼續我的研究，你這靈活的小東西。', `MaleText_loc7`='He abierto el portal a mi lugar de retiro. Ve y descansa. Necesito que estés bien vivo cuando retomemos nuestros estudios por la mañana, pequeña y astuta cosita.' WHERE `ID`=36943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 지불하는 작전 경비로 이익 분배금을 두둑이 챙길 수 있겠어요. 다시는 우릴 속이지 않는 게 좋을 걸요.', `MaleText_loc4`='他们已经接受了这次行动的酬金价格。我希望能够在这次行动中得到一笔丰厚的利润。他们最好不要再骗我们了。', `MaleText_loc5`='他們這項計畫的價錢既然那麼高，我希望我拿到的分紅會很高。他們最好不要又一次的壓榨我們。', `MaleText_loc7`='Con lo que van a sacar con esta operación espero recibir un buen cheque cuando toque el reparto de beneficios. Espero que nos timen de nuevo.' WHERE `ID`=36944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛십자군 형제들이여, 전투를 준비하시오. 브리쿨 놈들은 목숨 걸고 서리 여왕을 보호할 것이오.', `MaleText_loc4`='准备战斗，北伐军的弟兄们。维库人会用他们的生命保护冰霜女王。', `MaleText_loc5`='握好你們的武器，銀白十字軍的兄弟們!維酷人會以生命保護冰霜之后!', `MaleText_loc7`='¡Preparen las armas, hermanos Argenta! Los vrykul protegerán a la Reina de Escarcha con sus vidas.' WHERE `ID`=36945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡담은 그만하시오! 용사들이 도착했소. 전당을 돌파하는 동안 그들을 지원하시오!', `MaleText_loc4`='都给我严肃点！我们的勇士已经到了，我们要奋勇战斗，支援他们！', `MaleText_loc5`='沒時間閒聊說笑了!我們的勇士已經抵達了 - 支援他們並往大廳推進!', `MaleText_loc7`='¡Basta de tonterías! Han llegado nuestros campeones. ¡Ayúdalos mientras atravesamos el salón!' WHERE `ID`=36946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 이 $r 놈을 쇠사슬로 꽁꽁 묶어버려!', `MaleText_loc4`='卫兵！把这个$r用链子锁住！', `MaleText_loc5`='守衛!我要這個$r被鍊條鎖起來!', `MaleText_loc7`='¡Guardias! ¡Quiero a $gese:esa; $r $gcargado:cargada; de cadenas!' WHERE `ID`=36947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 미친 핑클스타인에게 하루 더 재료를 모아다 주느니 차라리 여기서 죽겠어.', `MaleText_loc4`='我宁愿死在这里，也不要为那个疯子芬克斯坦收集材料。', `MaleText_loc5`='死在這裡都比替那個瘋子芬克斯坦收集材料好。', `MaleText_loc7`='Incluso morir aquí es mejor que pasar otro día recolectando componentes para ese loco de Finklestein.' WHERE `ID`=36948;
