UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 더욱 불안정해집니다!', `MaleText_loc4`='%s变得更加不稳定了！', `MaleText_loc5`='%s變得更不穩定了!', `MaleText_loc7`='¡%s se vuelve más inestable!' WHERE `ID`=36950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때리지 마시오! 피케한테는 부디 잘 이야기해주시오.', `MaleText_loc4`='不要打我！告诉匹克，我变好了。', `MaleText_loc5`='別打我!跟皮克隊長說我很乖。', `MaleText_loc7`='¡No pegarme! ¡Decir a Peake que he sido bueno!' WHERE `ID`=36951;
