UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음엔 저 불덩어리 괴물이 나타나더니 이제는 $r 녀석까지! 짜증나는 것들! 없애버리겠어!', `MaleText_loc4`='先是大火，现在又是$r！你死定了！', `MaleText_loc5`='先是火，現在是$r!你去死吧!', `MaleText_loc7`='¡Primero e'' fuego y ahora $gel:la; $r! ¡Va'' a morir!' WHERE `ID`=36953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 공격해. 난 잠깐 기다릴 테니.', `MaleText_loc4`='朋友，你先去打他。我还没打他呢。', `MaleText_loc5`='老兄，你先去打他。我還沒準備好。', `MaleText_loc7`='Ataca tú primero, colega. Yo iré luego.' WHERE `ID`=36954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 불구덩이에서 죽고 싶진 않아.', `MaleText_loc4`='我不想死在火里，朋友。', `MaleText_loc5`='老兄，我不想被火燒死。', `MaleText_loc7`='No quiero mori'' quemado, colega.' WHERE `ID`=36955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 형체를 유지하기도 어려운 상태가 되었습니다!', `MaleText_loc4`='%s几乎无法维持当前的形态！', `MaleText_loc5`='%s只能勉強維持它的形態!', `MaleText_loc7`='¡%s apenas puede mantener su forma!' WHERE `ID`=36956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 뭘 하느냐고요? 기다려야죠.', `FemaleText_loc4`='你问我们要干什么？我们在等待。', `FemaleText_loc5`='你問我們現在要做什麼?等。', `FemaleText_loc7`='¿Preguntas qué haremo'' ahora? Eh''peraremos.' WHERE `ID`=36957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 우리를 왜 이렇게 거부하는지 알 수가 없군요.', `FemaleText_loc4`='真不知道那些灵魂为什么要如此排斥我们。', `FemaleText_loc5`='我不知道精靈為什麼要拒絕我們。', `FemaleText_loc7`='No sé por qué los eh''píritus no'' rechazan de esa forma.' WHERE `ID`=36958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 그리크니르 님께서 도와주실 거예요.', `FemaleText_loc4`='孩子，别担心。格瑞克尼尔会帮助我们。', `FemaleText_loc5`='別擔心，孩子。格瑞克尼爾會幫助我們度過難關的。', `FemaleText_loc7`='No te preocupes, joven. Grik''nir no'' ayudará a salir de eh''ta.' WHERE `ID`=36959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리크니르 님께서 그 정령이 우리 편이 될 수 있도록 설득하겠다고 말씀하셨어요.', `FemaleText_loc4`='格瑞克尼尔说他会和这个元素谈谈，让它帮助我们作战。', `FemaleText_loc5`='格瑞克尼爾說他會跟精靈溝通，讓它們與我們一起戰鬥。', `FemaleText_loc7`='Grik''nir dice que hablará con el elemental, pa'' que luche de nueh''tro lado.' WHERE `ID`=36960;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머지않아 우리가 이 계곡을 차지하게 될 거예요. 이제 금방이라고요.', `FemaleText_loc4`='我们很快就会占领这座山谷。', `FemaleText_loc5`='我們很快就會占領這座山谷。很快。', `FemaleText_loc7`='Pronto conquih''taremos eh''te valle. Muy pronto.' WHERE `ID`=36961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 우리에게 화가 나 있어요.', `FemaleText_loc4`='那些灵魂痛恨我们。', `FemaleText_loc5`='精靈在跟我們生氣。', `FemaleText_loc7`='Los eh''píritus están enfada''os con nosotros.' WHERE `ID`=36962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 땅은 얼음과 눈의 땅이에요.', `FemaleText_loc4`='我们的世界是一片冰雪之地。', `FemaleText_loc5`='我們的大地將被冰雪覆蓋。', `FemaleText_loc7`='Que nueh''tra tierra sea una tierra de hielo y nieve.' WHERE `ID`=36963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 이 땅 아래에서는 항상 화염이 불타고 있답니다.', `FemaleText_loc4`='但孩子，在那片大地之下，燃烧着永恒的烈火。', `FemaleText_loc5`='孩子，但在大地之下，一定會有火焰。', `FemaleText_loc7`='Pero bajo la tierra, joven, siemp''e habrá fuego.' WHERE `ID`=36964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 정령은 그리크니르 님을 만나러 깊은 땅속에서 나왔어요.', `FemaleText_loc4`='来自于深渊彼方的灵魂正在同格瑞克尼尔交谈。', `FemaleText_loc5`='從地底深處的精靈在與格瑞克尼爾交談。', `FemaleText_loc7`='El eh''píritu viene de lo más profundo pa'' hablar con Grik''nir.' WHERE `ID`=36965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 그런트는 다시 한 번 창의 방벽으로 돌진하라는 명령을 받았지만 그러지 못했소, $c. 손에서 무기가 미끄러지고 발걸음이 떨어지질 않았지.$B$B정말 굴욕적이오.', `MaleText_loc4`='我们得到命令，要再次进行冲锋。而迎击我们的是一片长矛组成的壁垒。我做不到，$c。我的武器滑出了双手，两条腿也无法动弹。$B$B我玷污了自己的荣誉。', `MaleText_loc5`='我們蠻兵被下令必須再次衝鋒...衝進矛牆裡。我無法做到，$c。我的武器從手中滑了下來，雙腿動也動不了。$B$B我的榮譽感已經消失。', `MaleText_loc7`='A los brutos nos ordenaron que cargáramos una vez más contra un muro lleno de picas. Y yo no pude hacerlo, $c. Se me cayó el arma de las manos y mis piernas no quisieron moverse.$B$BEstoy deshonrado.' WHERE `ID`=36966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님은 눈앞에서 끔찍하게 죽임을 당했고 주변에는 형제들이 모두 죽어있었소. 더는 싸울 수가 없었지. 복수하지 못한 것이 너무나 부끄럽소, $c.', `MaleText_loc4`='我的指挥官就在我的眼前被杀害了，兄弟们不断地在我身边倒下。我无法继续战斗下去。我没有能为他们报仇，$c，我让他们蒙受了羞耻。', `MaleText_loc5`='我的指揮官在我眼前被屠殺了，兄弟們的屍體圍著我到處都是，我無法繼續戰鬥。我太丟臉了，$c，我沒有為他們報仇。', `MaleText_loc7`='Masacraron a mi comandante delante de mis ojos, mis hermanos cayeron a mi alrededor, y no pude luchar. Estoy tan avergonzado, $c. No les vengué.' WHERE `ID`=36967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 보지 마시오, $r. 호드의 명예에 먹칠을 했으니 이제 끝이오.', `MaleText_loc4`='不要看我，$r，我让部落蒙羞，我彻底完蛋了。', `MaleText_loc5`='別看著我，$r。我丟了部落的臉，我已經完了。', `MaleText_loc7`='No me mires, $r. He traído el deshonor a la Horda. Estoy acabado.' WHERE `ID`=36968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 오크도 나처럼 전투에서 도망쳐서는 안 되오. 결코 씻어낼 수 없는 불명예를 지고 말았소. 이 탑에서 죽음을 맞이하면 좋겠지만 선조께서 겁쟁이인 날 어떻게 여기실지 두렵소.', `MaleText_loc4`='任何兽人都不应该像我一样逃离战场。别理我，让我单独咀嚼自己的耻辱吧。我不害怕死在这座塔里，却害怕知道我的祖先会如何看待我的懦弱。', `MaleText_loc5`='獸人永遠都不應該像我這樣逃離戰場。讓我自己在這承受恥辱吧。我應該要死在這座塔，但我害怕我的祖先會如何看待我這種膽小的行為。', `MaleText_loc7`='Ningún orco debe huir jamás de la batalla como hice yo. Abandóname en mi desgracia. Podría morir en esta torre, pero temo lo que mis ancestros pensarán de mi cobardía.' WHERE `ID`=36969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 일할 시간이에요!', `FemaleText_loc4`='去工作，孩子们！', `FemaleText_loc5`='大夥快回去工作!', `FemaleText_loc7`='¡A trabajar, muchachos!' WHERE `ID`=36970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 걱정하지 마세요. 곧 여기서 나갈 테니까요.', `FemaleText_loc4`='不要着急，我们很快就能出去。', `FemaleText_loc5`='別焦慮，我們很快就能離開這。', `FemaleText_loc7`='No temáis, pronto saldremos de aquí.' WHERE `ID`=36971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 불이 계속 꺼지지 않도록 하자고요, 드워프들!', `FemaleText_loc4`='我们要保持这股火继续燃烧，矮人们！', `FemaleText_loc5`='矮人們，讓我們繼續堅持下去!', `FemaleText_loc7`='¡Mantengamos vivo el fuego, enanos!' WHERE `ID`=36972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데 조렌은 밖에서 뭘 하는 거죠?', `FemaleText_loc4`='乔恩在那里干什么？', `FemaleText_loc5`='那喬連在那幹什麼?', `FemaleText_loc7`='¿Qué hace Joren ahí fuera?' WHERE `ID`=36973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요르문가르는 눈 속에 숨어 있을 때만 움직일 수 있으며, 그 상태로는 적을 공격할 수 없습니다. 지상으로 나온 요르문가르는 강력한 독 공격으로 무쇠 거대괴수의 외피를 녹일 수 있지요. 무쇠 거대괴수의 가장 강력한 공격을 피할 수 있도록, 항상 땅속 숨기를 할 준비를 하고 계세요.', `MaleText_loc4`='只有当你潜入雪层时，你的冰虫才能够移动，但潜入后你的冰虫无法攻击。浮出雪层的冰虫可以使用它强大的酸性攻击穿透钢铁巨像的护甲。要做好随时下潜的准备以躲避钢铁巨像最具毁灭性的攻击。', `MaleText_loc5`='你的蟄猛巨蟲只能在鑽到雪中時移動，而鑽地時無法攻擊。一旦你的蟄猛巨蟲鑽出來，它就能使用強大的酸液攻擊來穿透鐵巨像的鎧甲。要記得隨時準備鑽地來避開鐵巨像最致命的攻擊。', `MaleText_loc7`='Tu jormungar puede moverse si te has sumergido en la nieve, pero así no puede atacar. Cuando emerge, puede utilizar su poderoso ataque ácido para atravesar la armadura del coloso férreo. Prepárate para sumergirte para escapar de los demoledores ataques del coloso.' WHERE `ID`=36974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 방어구와 무기를 되찾아왔습니다. 승리가 아니면 죽음을!', `MaleText_loc4`='我拿回了你的盔甲和武器。我们不胜即死！', `MaleText_loc5`='我拿回你的護甲和武器了。不勝即亡!', `MaleText_loc7`='He recuperado tu armadura y tus armas. ¡Victoria o muerte!', `FemaleText_loc1`='당신의 방어구와 무기를 되찾아왔습니다. 승리가 아니면 죽음을!', `FemaleText_loc4`='我拿回了你的盔甲和武器。我们不胜即死！', `FemaleText_loc5`='我拿回你的護甲和武器了。不勝即亡!', `FemaleText_loc7`='He recuperado tu armadura y tus armas. ¡Victoria o muerte!' WHERE `ID`=36975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 와 주셔서 참으로 다행입니다. 오그림의 망치호는 이미 떠났습니다. 서둘러 하늘파괴자호로 가십시오. 급히 떠나면 따라잡을 수 있을 겁니다.', `MaleText_loc4`='谢天谢地，你们终于来了，英雄们。奥格瑞姆之锤号已经离开了。赶快到破天号去！也许你们还能乘上那艘船。', `MaleText_loc5`='感謝老天你終於到了，英雄們。奧格林之錘已經離開。現在快去破天者號!如果你動作夠快，還有機會趕上他們。', `MaleText_loc7`='Menos mal que llegaron en ese momento, héroes. El Martillo de Orgrim ya ha partido. Rápido, ¡al Rompecielos! Si parten pronto, quizá puedan alcanzarlos.' WHERE `ID`=36976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르!', `MaleText_loc4`='为了部落的荣耀！', `MaleText_loc5`='(獸人語)不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar!' WHERE `ID`=36977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수하리라...', `MaleText_loc4`='复仇……', `MaleText_loc5`='復仇...', `MaleText_loc7`='Venganza...' WHERE `ID`=36978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 열세를 뒤집은 팀은 없었지!', `MaleText_loc4`='还没有哪支队伍能够把这么不利的局势扳回来！', `MaleText_loc5`='沒有隊能在落後那麼多還追的回來過!', `MaleText_loc7`='¡Ningún equipo ha llegado nunca tan lejos!' WHERE `ID`=36979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독님, 다시 시합에 출전시켜 주세요!', `MaleText_loc4`='教练，让我重新开始比赛吧！', `MaleText_loc5`='教練，讓我回去比賽!', `MaleText_loc7`='¡Entrenador, méteme de nuevo en el juego!', `FemaleText_loc1`='감독님, 다시 시합에 출전시켜 주세요!', `FemaleText_loc4`='教练，让我重新开始比赛吧！', `FemaleText_loc5`='教練，讓我回去比賽!', `FemaleText_loc7`='¡Entrenador, méteme de nuevo en el juego!' WHERE `ID`=36980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 될 거예요!', `MaleText_loc4`='这应该能管用！', `MaleText_loc5`='這樣就行了!', `MaleText_loc7`='¡Esto ayudará!', `FemaleText_loc1`='도움이 될 거예요!', `FemaleText_loc4`='这应该能管用！', `FemaleText_loc5`='這樣就行了!', `FemaleText_loc7`='¡Esto ayudará!' WHERE `ID`=36981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 이곳부터는 혼자 갈 수 있습니다.', `MaleText_loc4`='谢谢！从这里开始，我自己就能搞定了。', `MaleText_loc5`='謝了!我之後可以靠我自己。', `MaleText_loc7`='¡Gracias! Desde aquí puedo seguir yo.', `FemaleText_loc1`='감사해요! 이곳부터는 혼자 갈 수 있겠어요.', `FemaleText_loc4`='谢谢！从这里开始，我自己就能搞定了。', `FemaleText_loc5`='謝了!我之後可以靠我自己。', `FemaleText_loc7`='¡Gracias! Desde aquí puedo seguir yo.' WHERE `ID`=36982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 생명의 은인입니다! 아이언포지를 위하여!', `MaleText_loc4`='你是大救星！为了铁炉堡！', `MaleText_loc5`='你是個救星!為了鐵爐堡!', `MaleText_loc7`='¡Me has salvado la vida! ¡Por Forjaz!', `FemaleText_loc1`='당신은 제 생명의 은인이에요! 아이언포지를 위하여!', `FemaleText_loc4`='你是大救星！为了铁炉堡！', `FemaleText_loc5`='你是個救星!為了鐵爐堡!', `FemaleText_loc7`='¡Me has salvado la vida! ¡Por Forjaz!' WHERE `ID`=36983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이제 좀 나아졌군요. 당신께 빚을 졌습니다.', `MaleText_loc4`='啊，这下好多了。我欠你一个人情。', `MaleText_loc5`='啊，好多了。我欠你一次。', `MaleText_loc7`='Ah, mucho mejor. Te debo una.', `FemaleText_loc1`='아... 이제 좀 나아졌군요. 당신께 빚을 졌네요.', `FemaleText_loc4`='啊，这下好多了。我欠你一个人情。', `FemaleText_loc5`='啊，好多了。我欠你一次。', `FemaleText_loc7`='Ah, mucho mejor. Te debo una.' WHERE `ID`=36984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스팀휘들 상어 선수들을 향해 축구탄을 날려야 합니다!', `MaleText_loc4`='朝着热沙港大鲨鱼队的队员掷出你的足球炸弹！', `MaleText_loc5`='將你們的足球炸彈丟向熱砂鯊魚隊員們!', `MaleText_loc7`='¡Lanza tu bombalón a los Tiburones Bonvapor!' WHERE `ID`=36985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 장치를 잃어버렸다고? 가방은 뒤져 봤나?', `MaleText_loc4`='火箭背包不见了？看看在不在背包里。', `MaleText_loc5`='弄丟了你的火箭包?你檢查過你的袋子了嗎?', `MaleText_loc7`='¿Has perdido tu paquete de cohetes? ¿Has mirado en tu bolsa?' WHERE `ID`=36986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빌어먹을 역겨운 우리...', `MaleText_loc4`='诅咒这个肮脏的笼子……', `MaleText_loc5`='這該死的籠子...', `MaleText_loc7`='Maldigo esta apestosa jaula...', `FemaleText_loc1`='이 빌어먹을 역겨운 우리...', `FemaleText_loc4`='诅咒这个肮脏的笼子……', `FemaleText_loc5`='這該死的籠子...', `FemaleText_loc7`='Maldigo esta apestosa jaula...' WHERE `ID`=36987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 마침내 저 역겨운 우리에서 해방되었군요...', `MaleText_loc4`='啊，终于摆脱了牢笼……', `MaleText_loc5`='啊，終於脫離了那個籠子...', `MaleText_loc7`='Ah, por fin libre fuera de esa jaula...', `FemaleText_loc1`='아, 마침내 저 역겨운 우리에서 해방되었어요...', `FemaleText_loc4`='啊，终于摆脱了牢笼……', `FemaleText_loc5`='啊，終於脫離了那個籠子...', `FemaleText_loc7`='Ah, por fin libre fuera de esa jaula...' WHERE `ID`=36988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我希望接受訓練。', `MaleText_loc7`='Me gustaría recibir instrucción.', `FemaleText_loc1`='훈련을 받고 싶어요.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我希望接受訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción.' WHERE `ID`=36989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅들이여, 용서하세요. 우서 경의 말을 들었어야 했는데. 직접... 확인해야만 했어요. 마지막으로 그의 눈을 들여다보고 싶었어요. 미안해요.', `FemaleText_loc4`='原谅我，英雄们。我应该听乌瑟尔的。我……我只是希望能够，能够看他最后一眼。对不起。', `FemaleText_loc5`='原諒我，英雄們。我早該要聽烏瑟的。我...我就是得自己親眼看看。最後一次注視他的雙眼。我很抱歉。', `FemaleText_loc7`='Perdónenme, héroes. Debí escuchar a Uther. Tenía que… verlo por mí misma. Poder mirarlo a los ojos una última vez. Lo siento.' WHERE `ID`=36990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 뭘 해야 하는지 알아요. 이 소식을 바리안 폐하와 폴드링 대영주님께 전하겠어요.', `FemaleText_loc4`='我们知道该怎么做了。我会把这个消息带给瓦里安国王和弗丁大人。', `FemaleText_loc5`='我們現在知道什麼是首要之舉。我會把這些消息通知瓦里安王和大領主弗丁。', `FemaleText_loc7`='Ahora sabemos qué debemos hacer. Les daré estas noticias al rey Varian y al alto señor Vadín.' WHERE `ID`=36991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런... 막다른 곳이군요. 이제 싸울 수밖에 없어요. 영웅들이여, 마음을 단단히 먹어요. 최후의 싸움일 테니까!', `FemaleText_loc4`='这……这是死路！我们别无选择，只能战斗。准备迎战，英雄们，这是我们最后的阵地。', `FemaleText_loc5`='沒...沒有退路了。我們別無選擇只能奮力一戰。拿起你的武器，英雄們，我們將在此背水一戰!', `FemaleText_loc7`='No... no hay salida. No tenemos más opción que luchar. Ármense de valor, héroes, pues es nuestra última batalla.' WHERE `ID`=36992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사! 발사!', `MaleText_loc4`='开火！开火！', `MaleText_loc5`='開火!開火!', `MaleText_loc7`='¡FUEGO! ¡FUEGO!' WHERE `ID`=36993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 곳은 없다... 너는 이제 나의 것이다!', `MaleText_loc4`='穷途末路……变成我的奴仆吧！', `MaleText_loc5`='無路可逃...你們現在是我的了!', `MaleText_loc7`='No hay escapatoria... ¡Son míos!' WHERE `ID`=36994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다. 여러분이 오시기 전에는 수적으로 열세였습니다.', `MaleText_loc4`='真是非常感谢。你的到来帮了我们大忙。', `MaleText_loc5`='我由衷感謝你們。在你們抵達之前我們只能孤軍奮戰。', `MaleText_loc7`='Les doy las gracias. Nos superaban en número hasta que llegaron. ', `FemaleText_loc1`='정말 감사합니다. 여러분이 오시기 전에는 수적으로 열세였습니다.', `FemaleText_loc4`='真是非常感谢。你的到来帮了我们大忙。', `FemaleText_loc5`='我由衷感謝你們。在你們抵達之前我們只能孤軍奮戰。', `FemaleText_loc7`='Les doy las gracias. Nos superaban en número hasta que llegaron. ' WHERE `ID`=36995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘파괴자호에서 무라딘 선장님이 기다리십니다. 이륙하실 준비가 될 때까지 이곳을 지키겠습니다.', `MaleText_loc4`='穆拉丁大人正在破天号上等着呢。我们会守住这里，等你起飞。', `MaleText_loc5`='穆拉丁船長正準備登上破天者號。我們會確保此地的安全直到你們準備起飛。', `MaleText_loc7`='El capitán Muradin está en El Rompecielos. Mantendremos segura la zona hasta que estén listos.', `FemaleText_loc1`='하늘파괴자호에서 무라딘 선장님이 기다리십니다. 이륙하실 준비가 될 때까지 이곳을 지키겠습니다.', `FemaleText_loc4`='穆拉丁大人正在破天号上等着呢。我们会守住这里，等你起飞。', `FemaleText_loc5`='穆拉丁船長正準備登上破天者號。我們會確保此地的安全直到你們準備起飛。', `FemaleText_loc7`='El capitán Muradin está en El Rompecielos. Mantendremos segura la zona hasta que estén listos.' WHERE `ID`=36996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 승선하라! 여기에서 늑장부려서는 안 된다! 이쪽 산 전체가 언제 무너질지 아무도 모른다.', `MaleText_loc4`='快！立刻上船！此地不可久留，山壁随时都有可能全面塌陷。', `MaleText_loc5`='快點，快爬上來!我們不能在此耽擱了!誰知道這片山坡什麼時候會崩塌。', `MaleText_loc7`='¡Rápido, a bordo! ¡No debemos entretenernos! La ladera de la montaña se derrumbará en cualquier momento.' WHERE `ID`=36997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 앞에 길이 있어요. 어서 가세요!', `FemaleText_loc4`='前面有个出口，赶快！', `FemaleText_loc5`='前面有個缺口。就是現在!', `FemaleText_loc7`='Hay una salida ahí delante. ¡VAMOS!' WHERE `ID`=36998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 언덕과 작은 길들은 제집과도 같아요. 수년간 사냥을 하면서 지나다녔죠.$B$B전쟁에 쓰이게 될 줄은 생각도 못했네요.', `FemaleText_loc4`='那些山丘和隐秘的小路就是我的家。许多年以来，我一直利用它们进行狩猎。$B$B但我从没有想过会利用它们进行一场战争。', `FemaleText_loc5`='這些山丘和小路就是我的家。多年來我一直利用它們打獵。$B$B我從沒想過會要利用它們來打仗。', `FemaleText_loc7`='Esas colinas y senderos ocultos son mi hogar. He cazado allí durante años.$B$BNunca pensé que los utilizaría para librar una guerra.' WHERE `ID`=36999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘파괴자호 병사들, 위치를 사수하라!', `MaleText_loc4`='破天号的兄弟们，给我顶住！', `MaleText_loc5`='破天者號步兵，堅守崗位!', `MaleText_loc7`='¡Infantería del Rompecielos, mantengan su posición!', `FemaleText_loc1`='하늘파괴자호 병사들, 위치를 사수하라!', `FemaleText_loc4`='破天号的兄弟们，给我顶住！', `FemaleText_loc5`='破天者號步兵，堅守崗位!', `FemaleText_loc7`='¡Infantería del Rompecielos, mantengan su posición!' WHERE `ID`=37000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네!', `MaleText_loc4`='好啊，好啊！', `MaleText_loc5`='是!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='네!', `FemaleText_loc4`='好啊，好啊！', `FemaleText_loc5`='是!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=37001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년 전, 그림토템 부족이 우리 마을을 침략했네. 고통과 노여움, 상실감이 아직도 내 마음을 짓누르고 있네.$B$B지금은 흉포한 공격으로 마을을 잃은 다른 이들에게 위안과 도움을 주고자 노력한다네.', `MaleText_loc4`='几年以前，恐怖图腾袭击了我的村庄。直至今日，痛苦、愤怒和失落仍然沉重地压在我的心上。$B$B现在，我自己却在安慰和帮助其他失去了自己村庄的人。', `MaleText_loc5`='多年前，恐怖圖騰部族掠奪了我的村莊。那種痛苦，憤怒和失落一直迴盪於我的心中。$B$B現在，我發現我自己在幫助和安慰那些村子受到惡徒侵略的人們。', `MaleText_loc7`='Hace años, los Tótem Siniestro arrasaron mi poblado. El dolor, la ira, la pérdida... todavía pesan en mi corazón.$B$BY ahora me encuentro reconfortando y ayudando a otros que han perdido su poblado ante un ataque salvaje.' WHERE `ID`=37002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 이제 이 터널을 그냥 지나가기만 하시면 어어어어어...?', `MaleText_loc4`='那么，你打算钻进这条隧道……？', `MaleText_loc5`='好，所以你不過是要穿過這個隧道...什麼????', `MaleText_loc7`='Vale, así que vas a atravesar ese túnel ¿y hacer quéééé...?' WHERE `ID`=37003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앤빌마로 돌아가시는 게 좋겠어요, $n... 어서 가세요! 놈리건 비행단에 신호를 보낼게요.', `MaleText_loc4`='我建议你去找安威玛尔，$n……而且要尽快去！我会向诺莫瑞根空军发出信号。', `MaleText_loc5`='$n，我建議你回到安威瑪，快點!我會對諾姆瑞根飛行員送出訊號。', `MaleText_loc7`='Te recomiendo que vuelvas a Yunquemar, $n... ¡Rápido! Haré una señal a los aviadores de Gnomeregan.' WHERE `ID`=37004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숨겨진 통로 쪽에서 아래쪽의 적에게 기습 공격을 퍼부을 수 있소.$B$B기습 작전에 정의 따위는 없지만 훌륭한 전사라면 적의 허를 찌를 줄도 알아야 하는 법이오.', `MaleText_loc4`='借助这些隐秘的路径，我们能够对下面的敌人发动猛烈的进攻。$B$B游击战算不上是荣誉的行动，但一名优秀的战士明白该如何让他的敌人措手不及。', `MaleText_loc5`='從這些隱藏小路我們可以讓恐怖降臨於下面的敵人身上。$B$B打帶跑的戰術沒有什麼榮譽可言，但一個好的戰士知道如何攻擊他的敵人個出奇不意。', `MaleText_loc7`='Desde estos senderos ocultos podemos desatar el terror entre nuestros enemigos de abajo.$B$BNo hay ningún honor en atacar y salir corriendo después, pero un buen guerrero sabe cómo desequilibrar al enemigo.' WHERE `ID`=37005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마일로 기어트윈지라는 사람을 찾아보세요. 저는 여기서 무너진 터널을 어찌해야 할지 알아볼게요.', `MaleText_loc4`='寻找一个名叫米罗·齿针的家伙。看来我能在这件事上帮些忙。', `MaleText_loc5`='去找一個叫米羅·輪擰的人。我想我會想辦法處理這處塌地。', `MaleText_loc7`='Busca a un tipo que se llama Milo Tocamotores. Veré lo que puedo hacer con ese derrumbe.' WHERE `ID`=37006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 꺼져라, 이 더러운 짐승 놈아!', `MaleText_loc4`='滚回去，你这个肮脏的怪物！', `MaleText_loc5`='回去，你這骯髒的野獸!', `MaleText_loc7`='¡Vuelve, bestia repugnante!' WHERE `ID`=37007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프의 총알을 맛봐라!', `MaleText_loc4`='来尝尝矮人的枪子儿吧！', `MaleText_loc5`='嘗嘗矮人之怒!', `MaleText_loc7`='¡Muerde plomo enano!' WHERE `ID`=37008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지를 위하여!', `MaleText_loc4`='为了铁炉堡！', `MaleText_loc5`='為了鐵爐堡!', `MaleText_loc7`='¡Por Forjaz!' WHERE `ID`=37009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받아라, 이 개만도 못한 동굴 짐승 녀석아!$b$b아... 무엇을 도와드릴까요, $n?', `MaleText_loc4`='你这个躲在洞里的怪物，吃我一记！$b$b啊……我能帮你做些什么，$n？', `MaleText_loc5`='吃這個，你這寄居洞穴的無賴!$b$b啊...我能幫你什麼，$n?', `MaleText_loc7`='¡Toma esa, chucho cavernario!$b$bAaaah... ¿cómo puedo ayudarte, $n?' WHERE `ID`=37010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요, $c님?', `FemaleText_loc4`='$c，你想要什么？', `FemaleText_loc5`='你想要什麼，$c?', `FemaleText_loc7`='¿Qué quieres, $c?' WHERE `ID`=37011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤들의 행동이 이상합니다, $n. 마음에 들지 않아요. 정말로 마음에 들지 않아요.', `MaleText_loc4`='$n，那些巨魔可真奇怪。我不喜欢这样，一点也不喜欢。', `MaleText_loc5`='食人妖的行為看起來怪怪的，$n。我不喜歡這樣，一點都不喜歡。', `MaleText_loc7`='Los trols actúan de forma extraña, $n. No me gusta. No me gusta ni un pelo.' WHERE `ID`=37012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 우리 쪽으로 유인하시오. 지원하겠소.', `MaleText_loc4`='把他们引到这里来。我们会支援你。', `MaleText_loc5`='把他們引到這來，我們會協助你。', `MaleText_loc7`='Tráiganlos hasta nosotros y los ayudaremos.' WHERE `ID`=37013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀어붙이시오!', `MaleText_loc4`='前进！', `MaleText_loc5`='向前推進!', `MaleText_loc7`='¡Sigan adelante!' WHERE `ID`=37014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 공격하시오!', `MaleText_loc4`='快！推进！', `MaleText_loc5`='快，加把勁!', `MaleText_loc7`='¡Rápido, sigan adelante!' WHERE `ID`=37015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스발나를 도울 지원군이 곧 올 거요. 신속히 처치해야 하오!', `MaleText_loc4`='她的援兵就要到了！我们必须迅速消灭她！', `MaleText_loc5`='她的援軍很快就會到了，我們一定要盡快解決她!', `MaleText_loc7`='Pronto llegarán sus refuerzos. ¡Debemos acabar con ella rápido!' WHERE `ID`=37016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 주의를 끌어 보겠소. 형제들을 무덤으로 돌려보내고 나서, 나를 도와주시오.', `MaleText_loc4`='我来挡住她。让我的兄弟回到坟墓中去，然后帮我消灭她！', `MaleText_loc5`='我去吸引她的攻擊。把我們的兄弟送回他們的墓地裡，然後幫我解決她!', `MaleText_loc7`='Atraeré sus ataques. ¡Devuelvan a nuestros hermanos a sus tumbas y después ayúdenme a derrotarla!' WHERE `ID`=37017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 남아서 티리온 경에게 상황을 보고하겠소. 계속 나아가 신드라고사를 쓰러뜨리시오. 용사들이여, 록타르!', `MaleText_loc4`='我会留下来，告诉提里奥我们的进展。你们必须继续前进，击败辛达苟萨。勇士们，Lok’tar！', `MaleText_loc5`='我會留下並且向提里奧報告我們的進展。你們一定要加把勁，解決辛德拉苟莎。為了部落，勇士們!', `MaleText_loc7`='Me quedaré e informaré a Tirion de nuestros avances. Ustedes sigan y derroten a Sindragosa. ¡Lok''tar, campeones!' WHERE `ID`=37018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령계의 힘 앞에 무릎을 꿇어라!', `MaleText_loc4`='我来自于元素位面！！', `MaleText_loc5`='我從元素界域而來!', `MaleText_loc7`='¡VENGO DEL PLANO ELEMENTAL!' WHERE `ID`=37019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 크록. 우리 군대를 키워 주려고 사람들을 모아 왔군. 일어나라, 은빛십자군 용사들이여. 죽은 몸으로 리치 왕을 섬겨라!', `FemaleText_loc4`='愚蠢的科罗克。你带来了我的援军。银色勇士们，用你们的死来效忠巫妖王吧！', `FemaleText_loc5`='愚蠢的克羅科。你帶著我的援軍來了。甦醒吧，銀白勇士們，以死亡之軀服侍巫妖王吧!', `FemaleText_loc7`='Tonto Crok. Me has traído refuerzos. ¡Levántense, campeones Argenta y sirvan al Rey Exánime en la muerte!' WHERE `ID`=37020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르게! 발키르에게 당하기 전에!', `MaleText_loc4`='快，在那个瓦格里干掉我们之前！', `MaleText_loc5`='快!在華爾琪抓走我們之前!', `MaleText_loc7`='¡Rápido, antes de que nos liquide esa val''kyr!' WHERE `ID`=37021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크록, 네놈이 한때는 내 전우였지만, 지금은 그저 배신자일 뿐이다. 오너라. 두 번째 죽음을 맞이해라!', `FemaleText_loc4`='你也许曾和我并肩作战，科罗克，但现在你只不过是一个叛徒。接受你的第二次死亡吧！', `FemaleText_loc5`='你或許曾和我並肩作戰，克羅科，但你現在不過是個叛徒。來吧，你的第二次死亡就在眼前!', `FemaleText_loc7`='Quizá una vez lucharas a mi lado, Crok, pero ahora no eres más que un traidor. ¡Ven, tu segunda muerte se acerca!' WHERE `ID`=37022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크록, 네놈이 한때는 내 전우였지만, 지금은 그저 배신자일 뿐이다. 오너라. 두 번째 죽음을 맞이해라!', `FemaleText_loc4`='你也许曾和我并肩作战，科罗克，但现在你只不过是一个叛徒。接受你的第二次死亡吧！', `FemaleText_loc5`='你或許曾和我並肩作戰，克羅科，但你現在不過是個叛徒。來吧，你的第二次死亡就在眼前!', `FemaleText_loc7`='Quizá una vez lucharas a mi lado, Crok, pero ahora no eres más que un traidor. ¡Ven, tu segunda muerte se acerca!' WHERE `ID`=37024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야, 딱 내가 찾던 $C|1이잖아;잖아;! 난 요새 로켓으로 작동하는 새로운 탈것을 시험하는 중이라고!

이 멜빵을 방어구 아래 입으라고. 그리고 옆에 있는 단추만 누르면, 슈웅! 바로 출발이지.

그렇다고 내 작품을 훔칠 생각은 꿈에도 마. 그 장비들은 모두 바로 내 손안에 있는 무선 장치 8000랑 연결되어 있다고. 자네가 내게서 너무 멀리 떨어지면 무선 장치로 주 로켓을 작동 정지시킬 거고, 그럼 자네는 내 곁으로 돌아올 때까지 거기서 내릴 수 없다고.

자, 내가 실험 동의서를 어디 뒀더라?', `MaleText_loc4`='你就是我要找的$c！我正在测试一种新的火箭助推飞行器，我需要你的帮助！

拿上一个控制器放到你的护甲里。按下侧面的按钮，砰，你就飞起来了。

不过你别想把它私吞了。每个飞行器都装有推进器8000，并且和我手里这个相连接。如果你飞得太远，推进器就会关闭主引擎，你便无法起飞，除非回到我这里。

我把那些责任书放哪了？', `MaleText_loc5`='沒想到你剛好就是我一直要找的$c!我正在測試一具火箭動力的飛行裝置，而我需要你的幫忙!

就拿一件這種背心然後穿在你的護甲外頭。按下旁邊的按鈕，然後「轟」，你就飛天啦。

這每一件寶貝都和我手上這個傳輸器8000連線，就不要試著想偷走我的作品了。如果你離傳輸器太遠，它就會關閉主要火箭，讓你無法起飛直到你回到我這裡來。

然後，我把切結書放在哪兒了?', `MaleText_loc7`='¡Pero si eres $gel:la:c; $c que estaba buscando! Estoy probando un nuevo dispositivo volador propulsado por cohetes y necesito tu ayuda.

Coge uno de estos arneses y colócalo bajo tu armadura. Pulsa el botón del lado, y BUM, ¡allá vas!

No intentes robarme el trabajo, ¿eh? Estas bellezas tienen integrado un transponstador 8000 vinculado al de mi mano. Si te alejas demasiado, se desactivará el cohete principal y no podrás despegar hasta que vuelvas.

Veamos, ¿dónde he metido los contratos de responsabilidad?' WHERE `ID`=37025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 당신이 안전을 제일 중요하게 생각한단 거 압니다. 로켓 장치나 주십시오.', `MaleText_loc4`='没错，你最看重的是安全。给我个火箭背包。', `MaleText_loc5`='當然，我知道安全是你的首要考量。拿一件火箭背包給我。', `MaleText_loc7`='Sí, estoy seguro de que la seguridad es tu máxima prioridad. Dame un paquete de cohetes.', `FemaleText_loc1`='네, 당신이 안전을 제일 중요하게 생각한단 거 압니다. 로켓 장치나 주시죠.', `FemaleText_loc4`='没错，你最看重的是安全。给我个火箭背包。', `FemaleText_loc5`='當然，我知道安全是你的首要考量。拿一件火箭背包給我。', `FemaleText_loc7`='Sí, estoy segura de que la seguridad es tu máxima prioridad. Dame un paquete de cohetes.' WHERE `ID`=37026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 순간이 왔다. 여기에서 일어나는 일은 세대를 거듭하여 전해지리라. 결과가 어떻든간에 우리가 명예롭게 싸웠음을 알리라. 자유와 우리 백성을 위해 싸웠음을!', `MaleText_loc4`='这是我们最后的阵地。今天的一切都将千古流传。无论是生是死，我们都是为了荣誉而战。我们都是为了自由和人民而战！', `MaleText_loc5`='這是我們的最後一戰。這一切將會流傳千古。不管結果如何，他們都將知道我們是懷著榮譽，為了自由與同胞的安危而戰!', `MaleText_loc7`='Esta es nuestra batalla final. El paso del tiempo se hará eco de lo que aquí ocurra. Sin importar el resultado, sabrán que luchamos con honor. ¡Que luchamos por la libertad y la seguridad de nuestro pueblo!' WHERE `ID`=37027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하게. 공포는 이 저주받은 전당에서 가장 위험한 적이네. 마음을 굳게 하면 그대들의 영혼은 천 개의 태양보다 더 밝게 빛날 걸세. 적들은 그대들 앞에 기가 꺾이겠지. 정의의 빛이 감쌀 때 모두 쓰러질 걸세!', `MaleText_loc4`='记住，英雄们，在这邪恶之地，恐惧是你们最大的敌人。勇气将让你们的灵魂比千颗太阳还要明亮。敌人会在你们面前溃不成军。正义的光芒将彻底摧毁他们！', `MaleText_loc5`='記得，英雄們，在這污穢的殿堂之中，恐懼就是你最大的敵人。武裝你的心靈與靈魂，它們將會比千顆太陽更加閃爍。敵人會因你而顫抖。他們終將倒下而正義之光普照萬物!', `MaleText_loc7`='Recuerden, héroes: el miedo es el mayor enemigo en estos salones infectos. Fortalezcan su corazón y su alma brillará más que mil soles. El enemigo vacilará al verlos. ¡Caerá en cuanto la luz de la rectitud lo envuelva!' WHERE `ID`=37028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음왕관 성채 공격을 지금 시작한다!', `MaleText_loc4`='现在，我们向冰冠堡垒进军！', `MaleText_loc5`='冰冠城塞的遠征現在正式展開!', `MaleText_loc7`='¡Nuestra marcha hacia la Ciudadela de Corona de Hielo comienza ahora!' WHERE `ID`=37029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 지금 스컬지의 신성한 땅 위에 서 있다. 성기사여, 여기서는 빛도 너를 보호하지 못한다. 그 무엇도 널 보호하지 못해...', `MaleText_loc4`='这是天灾军团的“神圣”土地。圣光在这里毫无用处，圣骑士。你将孤立无援……', `MaleText_loc5`='你現在站在天譴軍團的聖地。聖光在這裡沒辦法保護你，聖騎士。沒有東西能保護你...', `MaleText_loc7`='Ahora estás sobre el suelo sacro de la Plaga. La Luz no te protegerá aquí, paladín. Nada te protegerá…' WHERE `ID`=37030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스! 네놈과 스컬지의 최후를 보겠다고 맹세했다! 희망의 빛 예배당에서 시작했던 일을 이제 끝내겠다!', `MaleText_loc4`='阿尔萨斯！我发誓会彻底消灭你和天灾军团！昔日的恩怨会在今天做个了断！', `MaleText_loc5`='阿薩斯!我發誓要看到你的死亡還有天譴軍團的崩解!讓我們來了結聖光之願的未完之戰!', `MaleText_loc7`='¡ARTHAS! ¡Juré que te vería muerto y a la Plaga desmantelada! ¡Voy a acabar lo que comencé en la Esperanza de la Luz!' WHERE `ID`=37031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 넌 나의 가장 위대한 용사가 될 수도 있었다. 어둠의 힘으로 이 세계를 쓸어버리고 투쟁의 새로운 시대를 여는 용사 말이다.', `MaleText_loc4`='弗丁，你本应是我最强大的战士，你的黑暗力量将清洗这个世界，开启一个新的世代。', `MaleText_loc5`='你原可以成為我最強大的勇士，弗丁: 一支黑暗大軍將橫掃整個世界，然後帶來新的爭鬥紀元。', `MaleText_loc7`='Podrías haber sido el mejor de mis campeones, Vadín: una fuerza oscura que asolaría el mundo y lo llevaría a una nueva era de conflictos.' WHERE `ID`=37032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그러한 명예는 네 몫이 아니다. 곧, 새로운 용사가 나타난다.', `MaleText_loc4`='不过这份荣誉已经不再属于你。很快，我就会拥有一名新的勇士。', `MaleText_loc5`='但這樣的殊榮已經不再屬於你了。很快，我將會擁有一位新的勇士。', `MaleText_loc7`='Pero ese honor ya no te pertenece. Pronto, tendré un nuevo campeón.' WHERE `ID`=37033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 정신을 굴복시키는 일은 꽤 힘들었다. 그 영혼을 잔인하게 괴롭혔지... 오랫동안 저항했지만, 머지않아 자신이 섬길 왕 앞에 무릎 꿇고 말리라.', `MaleText_loc4`='我为这个灵魂耗费了巨大的力量，让他承受了无数痛苦……他抵抗了那么长时间，但用不了多久就会屈服了。', `MaleText_loc5`='要破壞這個人的意志並不容易。我對他的靈魂反覆蹂躪。然而他抵抗了如此之久，但很快地，他將會在他的王跟前屈膝。', `MaleText_loc7`=' El adiestramiento ha sido agotador. Las atrocidades que he cometido sobre su alma... Ha resistido por mucho tiempo, pero pronto se arrodillará ante su Rey.' WHERE `ID`=37034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로! 네놈 따위는... 섬기지... 않는다...', `MaleText_loc4`='绝不！我……绝不……服从你。', `MaleText_loc5`='絕不!我...我絕對不會...服侍...你...', `MaleText_loc7`='¡NUNCA! Nunca... te... serviré…' WHERE `ID`=37035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국에는, 나만을 섬기리라.', `MaleText_loc4`='你们最终都要臣服于我。', `MaleText_loc5`='到最後，你們全都將服侍我。', `MaleText_loc7`='Al final, todos me servirán.' WHERE `ID`=37036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링 경, 볼바르가 살았을 수 있겠소? 그렇다면 얼라이언스와 호드 사이에도 평화가 찾아올지 모르오. 이 저주받은 곳 꼭대기로 가서 그 성기사를 풀어줘야겠소!', `MaleText_loc4`='弗丁领主，这是真的？如果伯瓦尔还活着，也许联盟和部落之间还有和平的希望。我们必须冲到堡垒顶层，救出圣骑士！', `MaleText_loc5`='真的嗎，弗丁大人?如果伯瓦爾還活著，這或許是聯盟與部落恢復和平的希望。我們一定要到達詛咒之地的頂端，釋放偉大的聖騎士!', `MaleText_loc7`='¿Será posible, Lord Vadín? Si Bolvar está vivo, tal vez haya esperanza para la paz entre la Alianza y la Horda. ¡Tenemos que alcanzar la cima de este maldito lugar y liberar al paladín!' WHERE `ID`=37037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 힘으로, 그래야만 하오!', `MaleText_loc4`='圣光在上，胜利属于我们！', `MaleText_loc5`='以聖光之名，必然如此!', `MaleText_loc7`='¡Por la Luz, que así sea!' WHERE `ID`=37038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 주인님의 영역에 들어왔다. 경보를 울려라!', `MaleText_loc4`='入侵者进入了主人的领地。拉响警报！', `MaleText_loc5`='入侵者已經闖入了主人的領域。敲響警鐘!', `MaleText_loc7`='Han entrado intrusos en el dominio del maestro. ¡Sonad la alarma!' WHERE `ID`=37039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 별볼일없는 놈이로군. 채석장에서도 못 써먹겠구나. 마지막 순간을 즐겨라. 곧 넋 나간 언데드가 될 테니 말이다.', `MaleText_loc4`='嗯，低劣，就连在矿坑里作苦力都不配。享受最后的时刻吧。很快你们就会变成行尸走肉了。', `MaleText_loc5`='哼，雜碎。甚至連在礦場當苦工都不夠格。好好品味這最後一刻吧，因為很快地你將會變成一具沒有心智的不死生物。', `MaleText_loc7`='Pff, carne de cañón. No sirven ni para trabajar en la cantera. Saboreen estos últimos momentos: pronto no serán más que no-muertos sin voluntad.' WHERE `ID`=37040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 용이 카자로 산에 무슨 짓을 한 걸까요?!!!', `MaleText_loc4`='那头龙对卡亚罗山干了什么？！！！', `MaleText_loc5`='那隻龍到底對卡亞羅山做了什麼?!!!', `MaleText_loc7`='¡¡¡¿Qué le ha hecho ese dragón al Monte Kajaro?!!!', `FemaleText_loc1`='저 용이 카자로 산에 무슨 짓을 한 걸까요?!!!', `FemaleText_loc4`='那头龙对卡亚罗山干了什么？！！！', `FemaleText_loc5`='那隻龍到底對卡亞羅山做了什麼?!!!', `FemaleText_loc7`='¡¡¡¿Qué le ha hecho ese dragón al Monte Kajaro?!!!' WHERE `ID`=37041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 기억으로 끔찍한 고통만이 남게 해 주마.', `MaleText_loc4`='你们最后的记忆将填满痛苦。', `MaleText_loc5`='你最後的記憶將會是極端的痛苦。', `MaleText_loc7`='Su último recuerdo será un dolor lleno de agonía.' WHERE `ID`=37042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공중에서 성채를 공격하도록 하늘파괴자호를 준비하라!', `MaleText_loc4`='让破天号做好空袭城堡的准备！', `MaleText_loc5`='讓破天者號準備對城塞發動空中攻擊!', `MaleText_loc7`='¡Preparen El Rompecielos para un asalto aéreo sobre la Ciudadela!' WHERE `ID`=37043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들아, 침입자들을 처치해라!', `MaleText_loc4`='奴仆们，消灭那些闯入者！', `MaleText_loc5`='手下們，消滅那些闖入者。', `MaleText_loc7`='Esbirros, ¡destruid a estos intrusos!' WHERE `ID`=37044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 적이 수적으로 우세한데다, 십자로와 듀로타와의 연결망은 차단된 상태라네. 하지만 얼라이언스 열 놈이 우리 오크 한 명을 못 당해내지 않겠나.$B$B이 통로에서 저들의 세력을 억제하고 돼지 멱 따듯이 끝장내 버리세.', `MaleText_loc4`='敌人的数量远远超过我们，我们与十字路口和杜隆塔尔的联系已经被切断。但一个兽人能打败十个联盟懦夫。$B$B我们要对他们迎头痛击，把他们像赶猪群一样轰走。', `MaleText_loc5`='我們人數較少，與十字路口和杜洛塔的連繫也中斷了。但獸人可以一個打十個聯盟的懦夫。$B$B我們會在這裡將他們包圍後把他們像豬一樣給宰了。', `MaleText_loc7`='Nos superan en número, han cortado nuestras comunicaciones con El Cruce y Durotar. Pero un orco vale por 10 cobardes de la Alianza.$B$BLes acorralaremos en ese paso y los sacrificaremos como a cerdos.' WHERE `ID`=37045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 그대들은 길을 뚫어 성채 안 구출 지점을 확보해야 하네. 성루에서 그대들과 합류하겠네!', `MaleText_loc4`='英雄们，你们必须尽快在冰冠堡垒内部夺取一个立足点。我们在城墙上汇合！', `MaleText_loc5`='英雄們，你們一定得在寒冰皇冠中清出一個撤離點。我們會試著在壁壘那邊會合。', `MaleText_loc7`='Héroes, deben abrirse paso hasta un punto de extracción despejado en Corona de Hielo. ¡Intentaremos encontrarnos en las murallas! ' WHERE `ID`=37046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬록, 어떻게 해서 명예의 감시탑을 잃게 된 겁니까?', `MaleText_loc4`='基洛克，我们是怎样失去荣耀岗哨的？', `MaleText_loc5`='奇爾羅克，我們是如何失去榮譽看臺的?', `MaleText_loc7`='¿Kilrok, cómo perdimos El Alto del Honor?', `FemaleText_loc1`='킬록, 어떻게 해서 명예의 감시탑을 잃게 된 겁니까?', `FemaleText_loc4`='基洛克，我们是怎样失去荣耀岗哨的？', `FemaleText_loc5`='奇爾羅克，我們是如何失去榮譽看臺的?', `FemaleText_loc7`='¿Kilrok, cómo perdimos El Alto del Honor?' WHERE `ID`=37047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 영리한 계략이었네, $n. 얼라이언스 부대는 북부감시 요새에서 나와 황금길 위로 행군하다가, 땅거미가 지자 십자로를 포위했다네. 그런 다음 타오르는 모닥불을 남겨둔 채 한밤중에 남쪽으로 진격했지.$B$B명예의 감시탑에 있던 변변찮은 우리 부대는 동이 트자마자 길을 따라 쳐들어온 얼라이언스에게 속수무책으로 당하고 말았네. 용감한 전사들이 칼을 맞고 쓰러져갔지.', `MaleText_loc4`='联盟耍了一个极端狡诈的诡计，$n。联盟的军队从北方城堡出发，沿着黄金之路前进，在日暮时分向十字路口发动了进攻。到了深夜，他们又掉头南进，只留下空无一人的营地和依旧在燃烧的篝火。$B$B当黎明的第一缕曙光出现时，我们在荣耀岗哨的大军突然遭到了联盟的猛烈袭击。大批联盟士兵冲过隘口。我们许多最勇敢的战士都死在了他们的刀锋之下。', `MaleText_loc5`='那是一個聰明的策略，$n。聯盟的部隊從北方城堡傾巢而出，往黃金之路前進，想在夜晚到來時圍攻十字路口。但在深夜之時，他們卻往南方前進，把營火棄置於後方。$B$B我們在榮譽看臺的兵力非常稀疏，聯盟便在太陽升起的那一刻向那發動攻擊。許多我們最勇敢的戰士都死在他們的劍刃之下。', `MaleText_loc7`='Fue una artimaña muy inteligente, $n. Las fuerzas de la Alianza salieron en masa del Fuerte del Norte, marcharon por el Camino del Oro y asediaron El Cruce al caer la noche. Después, en medio de la noche, avanzaron a marchas forzadas hacia el sur, dejando encendidas sus fogatas del campamento.$B$BLas fuerzas de la Alianza asomaron por el paso con la primera luz del día y pillaron por sorpresa a nuestras escasas fuerzas de El Alto del Honor. Muchos de nuestros guerreros más valientes cayeron bajo sus hojas.' WHERE `ID`=37048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식이에요, 여러분! 독성 수액 배출관을 고쳤어요!', `MaleText_loc4`='好消息！各位！我修好了毒性软泥管道！', `MaleText_loc5`='大夥聽著，好消息!我修好了劇毒軟泥管!', `MaleText_loc7`='¡Buenas noticias, amigos! He arreglado las tuberías de babosas venenosas.' WHERE `ID`=37049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대편 골대 뒤에 있는 굴뚝 사이로 축구탄을 날려보내야 합니다!', `MaleText_loc4`='把球踢起来，让它飞进对面的烟囱球门！', `MaleText_loc5`='將足球炸彈踢到那兩根煙囪之間和對手的球門內!', `MaleText_loc7`='¡Chuta el bombalón para que pase entre las chimeneas que hay detrás de la portería contraria!' WHERE `ID`=37050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 성기사가 살아 있다고? 그게 정말이오, 대영주? 그가 살아 있단 말이오?', `MaleText_loc4`='那名圣骑士还活着？是真的吗，大领主？他居然还活着？', `MaleText_loc5`='那位聖騎士還活著?這不可能吧，大領主?他有可能倖存嗎?', `MaleText_loc7`='¿El paladín aún vive? ¿Acaso es posible, Alto señor? ¿Acaso pudo haber sobrevivido?' WHERE `ID`=37051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변 이전에 일어난 일입니까?', `MaleText_loc4`='这是在大灾变之前的事？', `MaleText_loc5`='這發生在大災變之前嗎?', `MaleText_loc7`='¿Eso sucedió antes del Cataclismo?', `FemaleText_loc1`='대격변 이전에 일어난 일입니까?', `FemaleText_loc4`='这是在大灾变之前的事？', `FemaleText_loc5`='這發生在大災變之前嗎?', `FemaleText_loc7`='¿Eso sucedió antes del Cataclismo?' WHERE `ID`=37052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 그를 구해야 하오! 볼바르 폴드라곤을 구해내면, 얼라이언스와 호드의 갈등을 잠재울 수 있을 거요.', `MaleText_loc4`='那我们必须去救他！如果我们救出了伯瓦尔·弗塔根，就能平息联盟和部落无休止的纷争。', `MaleText_loc5`='那我們一定要救他!如果我們能拯救伯瓦爾·弗塔根，我們或許能消減聯盟與部落間的不安。', `MaleText_loc7`='¡Debemos salvarlo! Si rescatamos a Bolvar Fordragón, quizá calmemos las tensiones entre la Alianza y la Horda.' WHERE `ID`=37053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 할 일이 뚜렷해지는군. 리치 왕이 죗값을 치르게 하고, 대영주 볼바르 폴드라곤을 구해내는 거요!', `MaleText_loc4`='任务已经明确：巫妖王将为他的罪行付出代价，我们一定要救出伯瓦尔·弗塔根公爵。', `MaleText_loc5`='我們的任務現在非常明確:巫妖王將為他的罪行付出代價，而且我們要拯救大領主伯瓦爾·弗塔根!', `MaleText_loc7`='Nuestra misión ahora está clara: el Rey Exánime responderá por sus crímenes y salvaremos al alto señor Bolvar Fordragón.' WHERE `ID`=37054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론, 오그림의 망치호 최후의 비행을 준비하라! 용사들이여, 성채 위쪽 적당한 곳을 찾아 비행포격선을 대겠네. 거기서 만나세!', `MaleText_loc4`='库卡隆，为最后的冲锋做好准备！勇士们，炮船将在那座堡垒的顶部着陆。我们在那里汇合！', `MaleText_loc5`='柯爾克隆，準備奧格林之錘進行它最後一趟航行!勇士們，我們的砲艇會在城塞上層找地方停靠。在那裡和我們碰頭!', `MaleText_loc7`='¡Kor''kron, prepara el Martillo de Orgrim para su último viaje! Campeones, nuestra nave atracará en la parte superior de la Ciudadela. ¡Nos veremos allí!' WHERE `ID`=37055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사울팽이여, 빛의 힘에는 한계가 없소. 그의 영혼은 엄청난 굴레에 묶여 있지만, 살아 있소. 지금은 말이오.', `MaleText_loc4`='圣光的力量没有止境，萨鲁法尔。他的灵魂饱受压抑，但他现在，还活着。', `MaleText_loc5`='聖光的力量無遠弗屆，薩魯法爾。他的靈魂受到嚴重的傷害，但他現在 - 還活著。', `MaleText_loc7`='El poder de la Luz no tiene límites, Colmillosauro. Su alma está bajo una gran tensión, pero vive, por ahora.' WHERE `ID`=37056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 길 동쪽 부근에서 재정비한 뒤 반격을 준비하는데, 글쎄 다음 날 하늘이 갑자기 붉은빛으로 변하더니 땅이 두 동강 나버렸지 뭔가. 어린아이가 선인장 사과를 쪼개듯이 그렇게 간단하게 말이네. 대대적인 파괴의 흔적이 지평선 끝까지 뻗어 나간 게 보이나?$B$B갑작스러운 참사로 임시 감시탑에 있던 얼라이언스도 꽤나 놀랐는지 정신이 없어 보이더군. 그때 쳤으면 딱 좋았는데! 장군 가르둘이 남쪽으로 철수해 재정비해야 한다고 고집하지 뭔가.$B$B<땅에 침을 뱉는 킬록>$B$B모두가 그를 따른 건 아니네. 지난 전쟁에서도 난 악마들과 얼굴을 맞대며 싸웠네, $n. 얼라이언스가 우리 땅에 뿌리내리게 놔둔 채 꽁무니를 빼고 달아날 생각은 추호도 없다네.', `MaleText_loc4`='是的，我们在隘口东边重新集结，准备发动反击。但在第二天，天空变成了赤红色，大地分裂成两块，就好象一块被小孩掰开的饼干。在地平线与地平线之间，一切都惨遭凌夷。$B$B刚刚建起防御碉堡的联盟军队也像我们一样惊恐异常，茫然不知所措。这本来是最佳的进攻时机！但督军加杜尔坚持要撤往南方，重组队伍。$B$B<基洛克向地面上啐了一口。>$B$B我们之中有许多人没有跟着他走。在上一场战争中，我曾经和恶魔正面交战，半步未退，$n。现在我也不打算掉头逃跑，让联盟占据我们的土地。', `MaleText_loc5`='對。我們在那的東邊重新整隊準備進行一次反擊，但隔天，天空變成紅色，大地裂成了兩半，就像一個小孩把仙人掌果掰成兩半一樣。有看到這些裂痕從地平線的一端延伸至另一端嗎?$B$B我們那些龜在碉堡裡的聯盟敵人跟我們一樣因為這個災害而感到震驚和慌亂。那本來是個絕佳的攻擊時機!但督軍迦爾杜爾勸我們後退到南方重新進行整頓。$B$B<奇爾羅克往地下吐了口痰>$B$B有些人並沒有聽他的話。$n，我曾在前次的戰爭中與惡魔面對面的單挑，我絕對不允許讓聯盟在我的土地上生根。', `MaleText_loc7`='Sí. Nos reagrupamos al este del paso para contraatacar, pero al día siguiente los cielos se tiñeron de rojo y la tierra se dividió en dos, tan fácil como un niño que parte una manzana de cactus. ¿Ves cómo la devastación se extiende de horizonte a horizonte?$B$BLos de la Alianza, refugiados en sus búnkeres improvisados, se sorprendieron y desorganizaron tanto como nosotros. ¡Habría sido el momento de atacar! Pero el señor de la guerra Gar''dul insistió en que nos retiráramos al sur para fortificarnos$B$B<Kilrok escupe en el suelo.>$B$BNo le seguimos todos. En la última guerra luché cara a cara contra los demonios, $n. No voy a irme con el rabo entre las piernas mientras los de la Alianza echan raíces en mi tierra.' WHERE `ID`=37057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 부하들은 계속 남아서 싸웠군요.', `MaleText_loc4`='你和你的人留下来继续作战。', `MaleText_loc5`='你和你的同伴留下來戰鬥。', `MaleText_loc7`='Tú y tus hombres se quedaron atrás para luchar.', `FemaleText_loc1`='당신과 부하들은 계속 남아서 싸웠군요.', `FemaleText_loc4`='你和你的人留下来继续作战。', `FemaleText_loc5`='你和你的同伴留下來戰鬥。', `FemaleText_loc7`='Tú y tus hombres se quedaron atrás para luchar.' WHERE `ID`=37058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 싸웠지. 죽을 작정으로? 그렇다고 볼 수 있네. 하지만 놈들에게 단 한 뼘의 땅도 줄 수 없네.$B$B비록 머릿수에서 밀리고, 방어구는 누더기로 변하고, 무기는 낡아빠졌지만...$B$B이곳은 우리 땅이 아닌가! 동맹 타우렌이 숨겨진 통로와 바위 틈, 언덕 사이로 난 길까지 구석구석 알고 있다네. 적들이 예상치 못한 높은 곳에서 내려와, 환영처럼 지형 속으로 사라질 수 있네. 두려움을 무기 삼아, 멈추지 않고 적을 공격할 작정이네.', `MaleText_loc4`='是的，我们继续作战。也许我们难免一死，但我们不会给他们半寸土地，$c。$B$B敌人的数量远远超过我们。我们的盔甲破碎，武器损坏。$B$B但这是我们的土地！我们的牛头人盟友熟悉这片山丘中的每一条小道、裂谷和每一个山口。我们埋伏在高地上，向联盟发动了出其不意的突袭，然后又像影子一样消失。恐惧就是我们的武器，我们要向敌人发动毫无止歇的攻击。', `MaleText_loc5`='沒錯，戰鬥。送死?很有可能。但我們不會讓他們侵占我們的土地，$c。$B$B我們的人數比對方少很多，我們的護甲是拼湊而成的，武器也是些破銅爛鐵。$B$B但這是我們的土地!我們的牛頭人盟友知道這些山丘上的所有小徑。我們將從高處發動攻擊，然後利用地形像幽靈般的消失。恐懼是我們最大的武器，我們的攻擊會讓他們連喘氣的機會都沒有。', `MaleText_loc7`='Luchar, sí. ¿Morir? Probablemente. Pero no vamos a cederles ni un centímetro de tierra, $c.$B$BNos superan en número. Nuestras armaduras no son más que retales y nuestras armas las hemos recogido de los muertos.$B$B¡Pero esta tierra es nuestra! Nuestros aliados tauren conocen cada sendero, recoveco y paso de estas colinas. Descenderemos por donde menos se los esperen y luego desapareceremos en el terreno como fantasmas. El miedo es nuestra arma y golpearemos una y otra vez, sin descanso.' WHERE `ID`=37059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런, 오늘 펠릭스 일진이 안 좋군요.', `MaleText_loc4`='哦，天哪。菲利克斯的情况并不乐观。', `MaleText_loc5`='老天，這看起來對菲利克斯不太好。', `MaleText_loc7`='Ay, madre. Las cosas no pintan muy bien para Felix.' WHERE `ID`=37060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=37061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승점을 넣어야 하니 다시 기회를 주세요, 감독님!', `MaleText_loc4`='再教教我该怎么踢致胜球，教练！', `MaleText_loc5`='再給我一次拿下勝利的射門機會，教練!', `MaleText_loc7`='Entrenador, ¡dame otra oportunidad para marcar el gol de la victoria!', `FemaleText_loc1`='승점을 넣어야 하니 다시 기회를 주세요, 감독님!', `FemaleText_loc4`='再教教我该怎么踢致胜球，教练！', `FemaleText_loc5`='再給我一次拿下勝利的射門機會，教練!', `FemaleText_loc7`='Entrenador, ¡dame otra oportunidad para marcar el gol de la victoria!' WHERE `ID`=37062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 화나서 응가 나왔어. 빵하고 터질 거야!', `MaleText_loc4`='吹个球，吹个“卟卟”会爆的大气球！', `MaleText_loc5`='我想我拉了一坨憤怒的便便。它要爆嘍!', `MaleText_loc7`='Creo que hice un popó enojado. ¡Va a hacer pum!' WHERE `ID`=37063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s|1이;가; |cFFFF0000불안정한 수액괴물 폭발|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s开始施放|cFFFF0000不稳定的软泥爆炸！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s開始施展|cFFFF0000不穩定的軟泥爆炸!|r', `MaleText_loc7`='|TInterfaceIconsspell_shadow_unstableaffliction_2.blp:16|t%s comienza a lanzar |cFFFF0000¡Deflagración de moco inestable!|r' WHERE `ID`=37064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형편없는 놈들! 죽어라!', `FemaleText_loc4`='可怜的生物！死吧！', `FemaleText_loc5`='可悲的生物!死吧!', `FemaleText_loc7`='¡Criaturas miserables! ¡Mueran!' WHERE `ID`=37065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 우리가 떠날 수 있는 겁니까? 다시 일하러 가야 한단 말입니다.', `MaleText_loc4`='你认为我什么时候能离开？我还要回去工作呢。', `MaleText_loc5`='你覺得我們什麼時候可以離開?我必須回去工作。', `MaleText_loc7`='¿Cuándo crees que podremos irnos? Tengo que volver al trabajo.', `FemaleText_loc1`='언제 우리가 떠날 수 있는 건가요? 다시 일하러 가야 한단 말이에요.', `FemaleText_loc4`='你认为我什么时候能离开？我还要回去工作呢。', `FemaleText_loc5`='你覺得我們什麼時候可以離開?我必須回去工作。', `FemaleText_loc7`='¿Cuándo crees que podremos irnos? Tengo que volver al trabajo.' WHERE `ID`=37066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트로그놈들은 어디서 오는 겁니까? 평생 땅속에서 살고 있었던 건가요?', `MaleText_loc4`='那些穴居人到底是从哪里来的？他们一直都住在地下吗？', `MaleText_loc5`='這些穴居怪都是哪來的?他們這些日子一直都住在地底下嗎?', `MaleText_loc7`='¿De dónde vienen todos estos troggs? ¿Han vivido bajo tierra todo este tiempo?', `FemaleText_loc1`='이 트로그놈들은 어디서 오는 걸까요? 평생 땅속에서 살고 있었던 건가요?', `FemaleText_loc4`='那些穴居人到底是从哪里来的？他们一直都住在地下吗？', `FemaleText_loc5`='這些穴居怪都是哪來的?他們這些日子一直都住在地底下嗎?', `FemaleText_loc7`='¿De dónde vienen todos estos troggs? ¿Han vivido bajo tierra todo este tiempo?' WHERE `ID`=37067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리 마음을 편하게 가지십시오. 아이언스톡은 트로그놈들이 사라질 때까지 아무도 밖에 내보내지 않을 겁니다.', `MaleText_loc4`='你最好能安下心来。在穴居人被消灭干净之前，铁枷不会让任何人出去。', `MaleText_loc5`='好好的習慣這裡吧。鐵樁在穴居怪沒死光前是不會讓任何人出去的。', `MaleText_loc7`='Más te vale sentarte tranquilamente. Cargacero no va a dejar salir a nadie hasta que mueran todos los troggs.', `FemaleText_loc1`='차라리 마음을 편하게 가지세요. 아이언스톡은 트로그놈들이 사라질 때까지 아무도 밖에 내보내지 않을 거니까요.', `FemaleText_loc4`='你最好能安下心来。在穴居人被消灭干净之前，铁枷不会让任何人出去。', `FemaleText_loc5`='好好的習慣這裡吧。鐵樁在穴居怪沒死光前是不會讓任何人出去的。', `FemaleText_loc7`='Más te vale sentarte tranquilamente. Cargacero no va a dejar salir a nadie hasta que mueran todos los troggs.' WHERE `ID`=37068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에서 아무 소식도 듣지 못했습니까? 트롤들이 말썽을 부리고 있다는 이야기를 들었습니다만.', `MaleText_loc4`='外面有什么新闻吗？我听说那些巨魔也在蠢蠢欲动。', `MaleText_loc5`='你有任何外面的消息嗎?我聽說食人妖也開始行動了。', `MaleText_loc7`='¿Alguna noticia del exterior? He oído que los trols también tienen que ver con esto.', `FemaleText_loc1`='밖에서 아무 소식도 듣지 못했나요? 트롤들이 말썽을 부리고 있다는 이야기를 들었어요.', `FemaleText_loc4`='外面有什么新闻吗？我听说那些巨魔也在蠢蠢欲动。', `FemaleText_loc5`='你有任何外面的消息嗎?我聽說食人妖也開始行動了。', `FemaleText_loc7`='¿Alguna noticia del exterior? He oído que los trols también tienen que ver con esto.' WHERE `ID`=37069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 사람들이 점점 많아지고 있군요. 전 좁은 곳에서 지내기가 너무 싫어요.', `MaleText_loc4`='这里真是拥挤得令人窒闷。我在密闭空间里总是感到不自在。', `MaleText_loc5`='這裡越來越擠了。我在擁擠的空間下無法好好發揮。', `MaleText_loc7`='Aquí dentro empieza a haber demasiada gente. No me hacen mucha gracia los espacios cerrados.', `FemaleText_loc1`='이곳에 사람들이 점점 많아지고 있어요. 전 좁은 곳에서 지내기가 너무 싫은데 말이죠.', `FemaleText_loc4`='这里真是拥挤得令人窒闷。我在密闭空间里总是感到不自在。', `FemaleText_loc5`='這裡越來越擠了。我在擁擠的空間下無法好好發揮。', `FemaleText_loc7`='Aquí dentro empieza a haber demasiada gente. No me hacen mucha gracia los espacios cerrados.' WHERE `ID`=37070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이라고도 불릴 정도로 거대한 지진이 일어났는데, 집안으로 피신해 있다는 건 정말 말도 안 되지 않습니까?', `MaleText_loc4`='试想一下，在经历了灾变程度的大地震后，你最不想待的地方应该就是屋里了，不是吗？', `MaleText_loc5`='你想想，在大災變的地震頻率不斷上升之下，你為何還選擇待在室內呢?', `MaleText_loc7`='La verdad es que después de un terremoto de proporciones cataclísmicas, el ÚLTIMO sitio en el que te gustaría estar es un lugar cerrado, ¿no crees?', `FemaleText_loc1`='대격변이라고도 불릴 정도로 거대한 지진이 일어났는데, 집안으로 피신해 있다는 건 정말 말도 안 되지 않나요?', `FemaleText_loc4`='试想一下，在经历了灾变程度的大地震后，你最不想待的地方应该就是屋里了，不是吗？', `FemaleText_loc5`='你想想，在大災變的地震頻率不斷上升之下，你為何還選擇待在室內呢?', `FemaleText_loc7`='La verdad es que después de un terremoto de proporciones cataclísmicas, el ÚLTIMO sitio en el que te gustaría estar es un lugar cerrado, ¿no crees?' WHERE `ID`=37071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 당신이 아이언스톡의 새로운 희생양이라더군요. 당신에게는 또 무슨 일을 시키던가요?', `MaleText_loc4`='$n! 我听说你是铁枷的新$r奴隶。她要你做些什么？', `MaleText_loc5`='$n!我聽說你是鐵樁新的$r奴工。她給了你什麼樣的工作?', `MaleText_loc7`='¡$n! He oído que eres $gel nuevo chivo expiatorio:la nueva chivo expiatorio; $r de Cargacero. ¿Qué te tiene haciendo ahora?', `FemaleText_loc1`='$n! 당신이 아이언스톡의 새로운 희생양이라더군요. 당신에게는 또 무슨 일을 시키던가요?', `FemaleText_loc4`='$n! 我听说你是铁枷的新$r奴隶。她要你做些什么？', `FemaleText_loc5`='$n!我聽說你是鐵樁新的$r奴工。她給了你什麼樣的工作?', `FemaleText_loc7`='¡$n! He oído que eres $gel nuevo chivo expiatorio:la nueva chivo expiatorio; $r de Cargacero. ¿Qué te tiene haciendo ahora?' WHERE `ID`=37072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 영원히 갇혔던 기분이 듭니다. 가을 축제는 대체 언제 시작한답니까?', `MaleText_loc4`='我觉得自己永远都要被关在这里了。已经到美酒节了吗？', `MaleText_loc5`='我感覺我已經在這待了大半輩子。啤酒節還沒到嗎?', `MaleText_loc7`='Tengo la impresión de llevar toda la vida encerrado aquí dentro. ¿Ya es la época de la Fiesta de la Cerveza?', `FemaleText_loc1`='이곳에 영원히 갇혔던 기분이 들어요. 가을 축제는 대체 언제 시작하나요?', `FemaleText_loc4`='我觉得自己永远都要被关在这里了。已经到美酒节了吗？', `FemaleText_loc5`='我感覺我已經在這待了大半輩子。啤酒節還沒到嗎?', `FemaleText_loc7`='Tengo la impresión de llevar toda la vida encerrada aquí dentro. ¿Ya es la época de la Fiesta de la Cerveza?' WHERE `ID`=37073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제일 윗... 선반에선... 꺼내지 못했어...', `MaleText_loc4`='永远……差那么……一点儿……', `MaleText_loc5`='永遠... 搆不到...架子...頂層...', `MaleText_loc7`='Nunca... llegué... al estante de arriba...' WHERE `ID`=37074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 상한 거미 수액을 가져온 대가다!', `MaleText_loc4`='这是为了让我得到变质的蜘蛛毒液！', `MaleText_loc5`='這就是帶給我腐爛蜘蛛毒液的下場!', `MaleText_loc7`='¡ESO fue por haberme traído icor de araña en mal estado!' WHERE `ID`=37075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 네놈들은 괜찮은 박쥐 날개 고르는 법도 몰랐지.', `MaleText_loc4`='你们这些傻瓜永远找不到一只像样的蝙蝠翅膀。', `MaleText_loc5`='你們這些可悲的蠢貨永遠也沒辦法選出像樣的蝙蝠翅膀。', `MaleText_loc7`='Imbéciles, nunca eligieron un ala de murciélago decente.' WHERE `ID`=37076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸을... 핑클스타인이... 재료로 쓰게 두지는...', `MaleText_loc4`='不要……让芬克斯坦拿我……做药……', `MaleText_loc5`='別...讓芬克斯坦把我...做成他的藥劑...', `MaleText_loc7`='No... dejen que Finklestein me utilice... para sus pociones...' WHERE `ID`=37077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 바위들이 가득하잖아!', `MaleText_loc4`='天哪，这里全都是石头！', `MaleText_loc5`='我的天啊，到處都是岩石!', `MaleText_loc7`='¡Madre mía, está lleno de rocas!' WHERE `ID`=37078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 포기하려던 참이었습니다.', `MaleText_loc4`='我几乎放弃了希望。', `MaleText_loc5`='我幾乎要放棄希望了。', `MaleText_loc7`='Casi había perdido la esperanza.', `FemaleText_loc1`='거의 포기하려던 참이었어요.', `FemaleText_loc4`='我几乎放弃了希望。', `FemaleText_loc5`='我幾乎要放棄希望了。', `FemaleText_loc7`='Casi había perdido la esperanza.' WHERE `ID`=37079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보시다시피 낙석들을 모두 제거했습니다. 많은 희생자가 생긴 건 슬픈 일이지만, 이제 트로그들이 들끓는 동굴로 아무 문제 없이 지나갈 수 있게 되었습니다.$b$b정말 환영합니다', `MaleText_loc4`='就像你看见的那样，我们清理了这片山岩中的敌人。我们损失了许多兄弟，但现在你能安全地通过这条曾经被穴居人占据的隧道了。$b$b不用谢！', `MaleText_loc5`='如同你所見，我們已經把落石清乾淨了。對於大量生命的消失我感到很難過，但至少你現在有條充滿穴居怪的通道可以用了。$B$B我知道，不用客氣!', `MaleText_loc7`='Como puedes ver hemos despejado el desprendimiento de rocas. Lamentablemente ha habido muchas muertes, pero ya puedes pasar libremente por el túnel infestado de troggs.$b$b¡De nada!' WHERE `ID`=37080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까?', `MaleText_loc4`='你好吗，$c？', `MaleText_loc5`='你好嗎，$c?', `MaleText_loc7`='Encantado, $c.' WHERE `ID`=37081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해질 무렵까지도 불길이 활활 타올랐네. 모든 걸 잃었어. 전부 다.$B$B대체 여관을 왜 불태우는 거지?', `MaleText_loc4`='到黄昏时分，火舌已经照亮了天空。我失去了一切。一切。$B$B为什么他们要烧掉一家旅店？', `MaleText_loc5`='到了黃昏，火焰高高升起直達天際。我喪失了一切，所有的一切。$B$B他們為什麼要燒了旅店?', `MaleText_loc7`='Al anochecer, las llamas se alzaban hasta el cielo. Lo perdí todo. Todo.$B$B¿Por qué alguien quemaría una posada?' WHERE `ID`=37082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신과 눈을 맞추지 못하는 켈수와>$B$B전투 도중에 도망치고 말았지만 야수를 풀어주는 일은 잊지 않았소.$B$B계속 데리고 있을 수가 없었다오. 모두 연기 속으로 뿔뿔이 흩어졌지...', `MaleText_loc4`='<克尔苏瓦避开你的眼睛。>$B$B我在战斗中逃了出来，但没有能及时放开所有被拴住的牲口。$B$B我没办法聚拢它们，结果它们全都逃进烟雾里去了……', `MaleText_loc5`='<克爾蘇瓦和你的眼神並沒有交集。>$B$B我在戰鬥中逃跑了，但沒時間將獸欄的動物們救出來。$B$B我無法保護牠們，牠們全都四散於煙霧之中...', `MaleText_loc7`='<Kelsuwa evita mirarte a los ojos.>$B$BEscapé en medio de la batalla, pero no antes de liberar a todos los animales que tenía en el establo.$B$B$n, no podía llevármelos conmigo. Se perdieron en el humo...' WHERE `ID`=37083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 따르는 중', `MaleText_loc4`='敲击', `MaleText_loc5`='倒酒', `MaleText_loc7`='Abrir', `FemaleText_loc1`='맥주 따르는 중', `FemaleText_loc4`='敲击', `FemaleText_loc5`='倒酒', `FemaleText_loc7`='Abrir' WHERE `ID`=37086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스의 영웅들이여, 공격하세요!', `FemaleText_loc4`='联盟的英雄们，进攻！', `FemaleText_loc5`='聯盟的英雄們，進攻!', `FemaleText_loc7`='¡Héroes de la Alianza, al ataque!' WHERE `ID`=37087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 이 괴물!', `FemaleText_loc4`='不！你这怪物！', `FemaleText_loc5`='不!你這怪物!', `FemaleText_loc7`='¡NO! ¡MONSTRUO!' WHERE `ID`=37088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할 일을 한 거예요. 고귀한 병사들이여, 용서하세요...', `FemaleText_loc4`='我别无选择。请原谅我，高贵的战士们……', `FemaleText_loc5`='我只是做我必須之事。請原諒我，高貴的士兵。', `FemaleText_loc7`='Sólo cumplo con mi deber. Perdónenme, nobles soldados…' WHERE `ID`=37089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 채석장은 여러분 힘만으로 빠져나가야 해요.', `FemaleText_loc4`='你只能靠自己冲过这个矿坑了。', `FemaleText_loc5`='你得要自己想辦法穿過這個礦場。', `FemaleText_loc7`='Tendrán que atravesar esta cantera por su cuenta.' WHERE `ID`=37090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마주치는 얼라이언스 노예들을 모두 풀어 주세요. 티라누스와 싸우려면 그들의 도움이 꼭 필요하니까요. 나는 지원 병력을 모아 채석장 반대편에서 여러분과 합류하겠어요.', `FemaleText_loc4`='解救你遇到的所有联盟奴隶.我们需要他们的协助来对抗泰兰努斯。我会集结援军，并在矿坑对面与你汇合。', `FemaleText_loc5`='釋放你遇到的任何一個聯盟奴隸。我們在對抗提朗紐斯的戰鬥中會需要他們的協助。我會召集援軍在礦場另一邊跟你會合。', `FemaleText_loc7`='Liberen a los esclavos de la Alianza que encuentren en su camino. Seguramente necesitemos su ayuda en la batalla contra Tyrannus. Reuniré refuerzos y nos veremos al otro lado de la cantera.' WHERE `ID`=37091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 주인님의 영역에 들어왔다. 경보를 울려라!', `MaleText_loc4`='入侵者进入了主人的领地。拉响警报！', `MaleText_loc5`='入侵者已經闖入了主人的領域。敲響警鐘!', `MaleText_loc7`='Han entrado intrusos en los dominios del amo. ¡Suenen las alarmas!' WHERE `ID`=37093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 별볼일없는 놈이로군. 채석장에서도 못 써먹겠구나. 마지막 순간을 즐겨라. 곧 넋 나간 언데드가 될 테니 말이다.', `MaleText_loc4`='嗯，废物，就连在矿坑里作苦力都不配。享受最后的时刻吧。很快你们就会变成行尸走肉了。', `MaleText_loc5`='哼，雜碎。甚至連在礦場當苦工都不夠格。好好品味這最後一刻吧，因為很快地你將會變成一具沒有心智的不死生物。', `MaleText_loc7`='Pff, carne de cañón. No sirven ni para trabajar en la cantera. Saboreen estos últimos momentos: pronto no serán más que no-muertos sin voluntad.' WHERE `ID`=37094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 기억으로 끔찍한 고통만이 남게 해 주마.', `MaleText_loc4`='你们最后的记忆将填满痛苦。', `MaleText_loc5`='你最後的記憶將會是極端的痛苦。', `MaleText_loc7`='Su último recuerdo será un dolor lleno de agonía.' WHERE `ID`=37095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들아, 침입자들을 처치해라!', `MaleText_loc4`='奴仆们，消灭那些闯入者！', `MaleText_loc5`='手下們，消滅那些闖入者。', `MaleText_loc7`='¡Lacayos, destruyan a estos intrusos!' WHERE `ID`=37096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위입니다! 화산 바위 사가세요!', `MaleText_loc4`='火山岩！来看看这里的火山岩吧！', `MaleText_loc5`='火山岩!要買火山岩找我就對了!', `MaleText_loc7`='¡Rocas volcánicas! ¡Compren sus rocas volcánicas aquí!' WHERE `ID`=37098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위 사가세요! 산에서 떨어진 따끈따끈한 바위랍니다! 갖고 싶으신가요? 여기 있습니다!', `MaleText_loc4`='出售火山岩！刚离开火山，还热气腾腾哪！你想要的，就在我这里！', `MaleText_loc5`='火山岩大拍賣!剛從火山運來的新鮮貨!你要多少，我就有多少!', `MaleText_loc7`='¡Se venden rocas volcánicas! ¡Calentitas, recién salidas de la montaña! ¡Si quieres una, la tienes!' WHERE `ID`=37099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위예요! 가격 인하! 마음에 꼭 드실 거예요!', `MaleText_loc4`='火山岩，最新低价！你一定会爱上我的岩石。', `MaleText_loc5`='火山岩...史上最低價!你會愛死我的火山岩。', `MaleText_loc7`='¡Rocas volcánicas a precio módico! Te encantarán mis rocas.' WHERE `ID`=37100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위가 여기 있습니다! 고양이들이 아주 좋아하죠!', `MaleText_loc4`='来看看这里的火山岩吧！……对猫正合适！', `MaleText_loc5`='快來買火山岩!...貓咪的最愛!', `MaleText_loc7`='¡Compra aquí tus rocas volcánicas...! ¡Ideales para gatos!' WHERE `ID`=37101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변의 한 조각을 집에 보관하세요! 화산 바위 할인 판매합니다! 앗, 뜨거워!', `MaleText_loc4`='把大灾变的纪念带回家吧！出售火山岩——火热，火热，火热的火山岩！', `MaleText_loc5`='把大災變的一部份買回家做紀念!火山岩大拍賣...燙手...燙手...燙手!', `MaleText_loc7`='¡Llévate a casa un pedazo del Cataclismo! ¡Se venden rocas volcánicas, calentitas, calentitas!' WHERE `ID`=37102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종이 뭉치를 눌러 놓으셔야 하나요? 문 받침대가 필요하신가요? 유리창을 깨고 싶으신가요? 자, 자, 화산 바위가 왔습니다!', `MaleText_loc4`='能做镇纸，能挡门，还能砸窗户！来看看，来看看！火山岩。', `MaleText_loc5`='需要東西壓住紙嗎?需要東西卡住門嗎?需要東西砸爛窗戶嗎?來來來!火山岩就是你想要的!', `MaleText_loc7`='¿Papeles que pisar? ¿Ventanas que romper? ¿Puertas que necesitan un tope? ¡Bam, bam, BAM! Rocas volcánicas.' WHERE `ID`=37103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위입니다. 백만 가지 용도로 쓸 수 있어요. 용암, 요양, 사우나, 바나나...', `MaleText_loc4`='火山岩。用法多多。', `MaleText_loc5`='火山岩是你的好幫手，使用方法一千種。一種兩種三種四種，功用多到你不懂!', `MaleText_loc7`='Rocas volcánicas. Un millón y un usos. Lava, java, sauna, banana...' WHERE `ID`=37104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 여왕께 다가가도록 두지 않겠다. 서둘러라! 저들을 막아라!', `MaleText_loc4`='绝不能让他们靠近冰霜女王。快，阻止他们！', `MaleText_loc5`='你一定不能靠近冰霜之后。快，阻止他們!', `MaleText_loc7`='No se acercarán a la Reina de Escarcha. ¡Deténganlos, rápido!', `FemaleText_loc1`='서리 여왕께 다가가도록 두지 않겠다. 서둘러라! 저들을 막아라!', `FemaleText_loc4`='绝不能让他们靠近冰霜女王。快，阻止他们！', `FemaleText_loc5`='你一定不能靠近冰霜之后。快，阻止他們!', `FemaleText_loc7`='No se acercarán a la Reina de Escarcha. ¡Deténganlos, rápido!' WHERE `ID`=37105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산 바위입니다! 한정 판매해요! 감정서, 기타 등등 다 있어요!', `MaleText_loc4`='火山岩！限时供应！配有品质证书和一切相关手续！', `MaleText_loc5`='火山岩!限量搶購!附加品質證書!', `MaleText_loc7`='¡Rocas volcánicas! ¡Oferta por tiempo limitado ¡Con papeles de autenticidad y todo!' WHERE `ID`=37106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변 진품 기념물을 하나 가지고 싶어요, 비니!', `MaleText_loc4`='薇尼，我刚刚弄到了一个真正的大灾变纪念品！', `MaleText_loc5`='薇妮，我想要買一個真正的大災變紀念品!', `MaleText_loc7`='¡Vinny! ¡Tengo que comprarme un recuerdo genuino del Cataclismo.', `FemaleText_loc1`='대격변 진품 기념물을 하나 가지고 싶어요, 비니!', `FemaleText_loc4`='薇尼，我刚刚弄到了一个真正的大灾变纪念品！', `FemaleText_loc5`='薇妮，我想要買一個真正的大災變紀念品!', `FemaleText_loc7`='¡Vinny! ¡Tengo que comprarme un recuerdo genuino del Cataclismo.' WHERE `ID`=37107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 냉혹한 한파의 파도를 내뿜으려 합니다!', `FemaleText_loc4`='%s 准备释放一波严寒！', `FemaleText_loc5`='%s準備釋放一波極凍之寒!', `FemaleText_loc7`='¡%s se prepara para desatar una oleada de Frío virulento!' WHERE `ID`=37108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 주인님의 무한한 힘을 느끼고 절망에 빠져보아라!', `FemaleText_loc4`='绝望吧，体会主人那无穷无尽的力量吧！', `FemaleText_loc5`='現在，絕望地感受我主無限的力量吧!', `FemaleText_loc7`='¡Ahora sientan el poder ilimitado de mi amo y tiemblen!' WHERE `ID`=37109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 말에서 "우나페"는 "피난처"란 뜻입니다. 더는 어울리지 않는 이름이지요. 야영지를 세운 후부터 저 이상한 밀림이 이곳을 집어삼키려는 듯 위협하고 있습니다.', `FemaleText_loc4`='在牛头人语中，“乌纳菲”是避难所的意思。但这个名字已经不再合适了。从我们建起这座营地的时候开始，这片诡异的丛林就要将这座营地吞噬。', `FemaleText_loc5`='在我們的語言，「烏納非」就是避難所的意思，但字面上的意思已經沒有意義了。從我們建好這個營地開始，這個奇妙的叢林便無時無刻威脅著要吞噬我們。', `FemaleText_loc7`='En nuestra lengua nativa, "Una''fe" puede ser traducido como "refugio". Pero el nombre ya no es apropiado. Desde el momento en el que levantamos este campamento, esta extraña jungla ha amenazado con devorarlo entero.' WHERE `ID`=37110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 강한 전사들이 사냥 나간 틈을 타 공격해왔어요. 얼라이언스가 본격적으로 쳐들어오기 전에 기적적으로 몇몇 분들과 함께 이 아이들을 대피시킬 수 있었지요...$B$B<아이들 앞에서 울음을 참으려 목소리를 낮추는 타와네>', `FemaleText_loc4`='当我们最强壮的战士进行狩猎的时候，他们对陶拉祖发动了进攻。我们遇到的也许是一个奇迹。在联盟的阵线中出现了一个缺口。所以我和另一些人才能带着这些小东西逃出来……$B$B<塔瓦妮的声音低沉了下去。他正努力不让自己在孩子们的面前哭出来。>', `FemaleText_loc5`='在我們最勇猛的戰士們出去打獵時，陶拉祖營地被攻擊了。我們奇蹟般地找到了聯盟陣線的缺口，讓我和其他人能帶孩子們逃出來...$b$b<泰灣娜的聲音逐漸變小，努力克制，不想在孩子們面前流下眼淚。>', `FemaleText_loc7`='Atacaron Taurajo mientras nuestros hombres más fuertes estaban de caza. De milagro encontramos un hueco en las líneas de la Alianza por el cual pudimos escabullirnos yo y unos cuantos más...$B$B<Tawane se calla e intenta no llorar delante de los niños.>' WHERE `ID`=37111;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿, 조용히 하렴. 괜찮아.', `FemaleText_loc4`='放心，放心。没有事的，小家伙。', `FemaleText_loc5`='乖，乖。沒事了小朋友。', `FemaleText_loc7`='Hala, hala, hala. No pasa nada, pequeño.' WHERE `ID`=37112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 잠들 시간이란다, 얘야. 부모님을 곧 찾아줄게.', `FemaleText_loc4`='睡吧，小家伙。我们很快就能找到你的爸爸妈妈。', `FemaleText_loc5`='先睡個覺吧，我們很快就會讓你們回到父母身邊。', `FemaleText_loc7`='Ahora duerme, pequeño. Pronto encontraremos a tus padres.' WHERE `ID`=37113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼬마 사냥꾼님, 제가 당신을 도와드리죠.', `FemaleText_loc4`='嗨，小猎人。我正要找你。', `FemaleText_loc5`='乖，乖，小獵人，我會一直在這陪著你們。', `FemaleText_loc7`='Hala, hala, hala, pequeño cazador. Estoy aquí.' WHERE `ID`=37114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<치지직>$b이게 작동하는 건가? 여보세요?', `MaleText_loc4`='<静电噪音>$b这东西连通了吗？喂？', `MaleText_loc5`='<雜訊>$b這個東西開了嗎? 哈囉?', `MaleText_loc7`='<Estática>$b¿Está encendido? ¿Hola?' WHERE `ID`=37115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 여기에서 지원군이 더 올 때까지 시간을 끌어 보겠지만, 그대들은 계속 움직여야 해요.$B$B우리가 여기 있다는 것을 아서스가 알아차릴 때까지 시간이 얼마 남지 않았어요.', `FemaleText_loc4`='在援兵赶到前我会尽量拖延时间，但你必须继续前进。$B$B阿尔萨斯很快会发现我们在这里。', `FemaleText_loc5`='我會在這裡等待更多援軍抵達，但你必須要繼續前進。$B$B再不用多久，阿薩斯就會發現我們在這裡。', `FemaleText_loc7`='Yo esperaré aquí hasta que lleguen refuerzos, pero ustedes debéis seguir.$B$BNo tenemos mucho tiempo antes de que Arthas se dé cuenta de que estamos aquí.' WHERE `ID`=37116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거기 있었군요. 안녕하세요! 당신이 카라노스로 날아가는 동안 눈마루 골짜기 밖에서 일어나는 일에 대한 정보를 줄 수 있을 거라고 짐작했어요.', `MaleText_loc4`='啊，你在这里。你好！我想，既然你飞去了卡拉诺斯，我应该告诉你一下寒脊山谷外都发生了什么事。', `MaleText_loc5`='啊，你在這啊。哈囉!我想說在你飛往卡拉諾斯的時候我可以給你些寒脊山谷以外的相關消息和資料。', `MaleText_loc7`='Aaah, estás ahí. ¡Hola! He pensado que mientras volabas a Kharanos podía darte alguna información sobre lo que ocurre en el Valle de Crestanevada.' WHERE `ID`=37117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 눈마루쪽 사람들은 요 며칠 사이에 일어난 일 때문에 공포에 빠진 것 같아요.', `MaleText_loc4`='看样子，你们这些寒脊山人根本不知道过去几天发生了什么。', `MaleText_loc5`='看來你們這些從寒脊山谷出來的人對前幾天發生的事不太了解。', `MaleText_loc7`='Al parecer, los de Crestanevada estáis muy mal informados de los acontecimientos que han sucedido en los últimos días.' WHERE `ID`=37118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈마루 골짜기에서 트롤 문제로 힘드셨다고요? 카라노스에 안 가 보셨으면 말을 하지 마세요! 대격변 때문에 트롤들이 몽땅 날뛰고 있어요.', `MaleText_loc4`='如果你们以为寒脊山最大的问题是巨魔，那么就到卡拉诺斯去看看吧！这场大灾变让巨魔全都发了疯。', `MaleText_loc5`='如果你認為食人妖在寒脊山谷是個問題，那就去卡拉諾斯那看看吧!大災變讓食人妖們像蟑螂一樣一湧而出。', `MaleText_loc7`='Si creías que en Crestanevada teníais problemas con los trols, ¡espera a llegar a Kharanos! Ese Gran Cataclismo ha puesto muy nerviosos a los trols de allí.' WHERE `ID`=37119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자유야!', `MaleText_loc4`='终于自由了！', `MaleText_loc5`='終於自由了!', `MaleText_loc7`='¡Al fin libre!', `FemaleText_loc1`='이제 자유예요!', `FemaleText_loc4`='终于自由了！', `FemaleText_loc5`='終於自由了!', `FemaleText_loc7`='¡Al fin libre!' WHERE `ID`=37120;
