UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시멧돼지의 말은 몇 마디밖에 알아듣지 못하지만, 좋은 얘기는 듣지 못했소.', `MaleText_loc4`='野猪人的话我懂得不多，但我可不喜欢我听到的这些话。', `MaleText_loc5`='我只聽得懂一點點野豬人所說的話，不過我不喜歡我所聽到的。', `MaleText_loc7`='Solo entiendo unas pocas palabras de la lengua de los jabaespines, pero no me gusta lo que he oído.', `FemaleText_loc1`='가시멧돼지의 말은 몇 마디밖에 알아듣지 못하지만, 좋은 얘기는 듣지 못했어요.', `FemaleText_loc4`='野猪人的话我懂得不多，但我可不喜欢我听到的这些话。', `FemaleText_loc5`='我只聽得懂一點點野豬人所說的話，不過我不喜歡我所聽到的。', `FemaleText_loc7`='Solo entiendo unas pocas palabras de la lengua de los jabaespines, pero no me gusta lo que he oído.' WHERE `ID`=37122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우나페 야영지에 피난민들이 아직 모여 있소?', `MaleText_loc4`='难民们是不是还聚集在乌纳菲营地？', `MaleText_loc5`='難民們仍舊聚集在烏納非營地嗎?', `MaleText_loc7`='¿Los refugiados siguen reuniéndose en el Campamento Una''fe?', `FemaleText_loc1`='우나페 야영지에 피난민들이 아직 모여 있나요?', `FemaleText_loc4`='难民们是不是还聚集在乌纳菲营地？', `FemaleText_loc5`='難民們仍舊聚集在烏納非營地嗎?', `FemaleText_loc7`='¿Los refugiados siguen reuniéndose en el Campamento Una''fe?' WHERE `ID`=37123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 구원자요! 놈들이 대체 우리한테 뭘 원하는지 모르겠소...', `MaleText_loc4`='你是我们的救星！我不知道那些怪物想从我们这里抢走什么……', `MaleText_loc5`='你是個救世主!我不知道那些東西到底想從我們這得到什麼...', `MaleText_loc7`='¡Me has salvado! No sé qué querrían esas cosas de nosotros...', `FemaleText_loc1`='당신은 구원자예요! 놈들이 대체 우리한테 뭘 원하는지 모르겠어요...', `FemaleText_loc4`='你是我们的救星！我不知道那些怪物想从我们这里抢走什么……', `FemaleText_loc5`='你是個救世主!我不知道那些東西到底想從我們這得到什麼...', `FemaleText_loc7`='¡Me has salvado! No sé querrían esas cosas de nosotros...' WHERE `ID`=37124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐야? <그릉> <킁킁> $r|1이;가; 왔나? 위대하신 칼주둥이 님께 도전하러 <킁>?', `MaleText_loc4`='这是什么？ <呼噜呼噜> <哼哼>那个$r来了？来挑战强大的刃鼻？', `MaleText_loc5`='什麼?<咯咯><哼氣>$r來到這了?來向強大的刃鼻挑戰<哼氣>?', `MaleText_loc7`='¿Qué ocurre? <Barboteo> <Bufido> ¿$gEl:La; $r ha venido? ¿Para desafiar al poderoso Hozasable <Bufido>?' WHERE `ID`=37125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r에게 본 때를 보여 주지, <킁킁>! 단단히 준비해라, <그릉> 애송이.', `MaleText_loc4`='我要给$r树立个榜样 <哼哼>！做好准备吧<呼噜>，软弱的家伙。', `MaleText_loc5`='我會殺$r儆猴<哼氣>!準備好了<咯咯>，你這塊嫩肉。', `MaleText_loc7`='¡Daré ejemplo con $r! <Bufido> Prepárate, <barboteo> cara blanda.' WHERE `ID`=37126;
