UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 이제 아스파라거스는 절대 먹지 않겠소.', `MaleText_loc4`='唉呦！我绝不再吃芦笋了。', `MaleText_loc5`='哇噢!我永遠都不再吃蘆筍了。', `MaleText_loc7`='¡Guau! No pienso volver a comer espárragos.', `FemaleText_loc1`='휴, 이제 아스파라거스는 절대 먹지 않을래요.', `FemaleText_loc4`='唉呦！我绝不再吃芦笋了。', `FemaleText_loc5`='哇噢!我永遠都不再吃蘆筍了。', `FemaleText_loc7`='¡Guau! No pienso volver a comer espárragos.' WHERE `ID`=37142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 밀림은 정말 지긋지긋하오!', `MaleText_loc4`='我对这片森林已经受够了！', `MaleText_loc5`='我受夠這片叢林了!', `MaleText_loc7`='¡Ya me he hartado de esta selva!', `FemaleText_loc1`='이 밀림은 정말 지긋지긋해요!', `FemaleText_loc4`='我对这片森林已经受够了！', `FemaleText_loc5`='我受夠這片叢林了!', `FemaleText_loc7`='¡Ya me he hartado de esta selva!' WHERE `ID`=37143;
