UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소! 놈이 날 인형처럼 쥐고 흔들어대지 뭐요.', `MaleText_loc4`='谢谢！我在那个家伙的触手里简直就象个破布娃娃。', `MaleText_loc5`='謝謝你!那個東西把我當成布娃娃甩來甩去。', `MaleText_loc7`='¡Gracias! Esa cosa me estaba meneando como a una muñeca de trapo.', `FemaleText_loc1`='고마워요! 놈이 절 인형처럼 쥐고 흔들어대지 뭐예요.', `FemaleText_loc4`='谢谢！我在那个家伙的触手里简直就象个破布娃娃。', `FemaleText_loc5`='謝謝你!那個東西把我當成布娃娃甩來甩去。', `FemaleText_loc7`='¡Gracias! Esa cosa me estaba meneando como a una muñeca de trapo.' WHERE `ID`=37146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에는 불모의 땅이... 불모지였는데. 그 때가 좋았소!', `MaleText_loc4`='我记得以前的贫瘠之地是真的很……“贫瘠”。我们还是比较喜欢那个时候的贫瘠之地！', `MaleText_loc5`='我記得當貧瘠之地還是...貧瘠之地的時候。我們喜歡那時的貧瘠之地!', `MaleText_loc7`='Recuerdo cuando Los Baldíos eran tierras... baldías. ¡Y nos gustaba!', `FemaleText_loc1`='예전에는 불모의 땅이... 불모지였는데. 그 때가 좋았어요!', `FemaleText_loc4`='我记得以前的贫瘠之地是真的很……“贫瘠”。我们还是比较喜欢那个时候的贫瘠之地！', `FemaleText_loc5`='我記得當貧瘠之地還是...貧瘠之地的時候。我們喜歡那時的貧瘠之地!', `FemaleText_loc7`='Recuerdo cuando Los Baldíos eran tierras... baldías. ¡Y nos gustaba!' WHERE `ID`=37147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘델라를 마지막으로 휘둘렀던 탈로리엔 돈시커의 유해처럼 보입니다.', `MaleText_loc4`='这看上去像是萨洛瑞安·寻晨者的遗体，奎尔德拉最后的使用者。', `MaleText_loc5`='這看來像是薩洛瑞安·曦尋者的遺骸，他是奎爾德拉的最後持有者。', `MaleText_loc7`='Parece que estos son los restos de Thalorien Buscalba, el último portador de Quel''Delar.' WHERE `ID`=37148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해를 살펴봅니다.', `MaleText_loc4`='检查遗骸。', `MaleText_loc5`='檢查屍體。', `MaleText_loc7`='Examina los restos.', `FemaleText_loc1`='유해를 살펴봅니다.', `FemaleText_loc4`='检查遗骸。', `FemaleText_loc5`='檢查屍體。', `FemaleText_loc7`='Examina los restos.' WHERE `ID`=37149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시오. 제발!', `MaleText_loc4`='救命。救命！', `MaleText_loc5`='救命。救命!', `MaleText_loc7`='Ayuda. ¡Ayuda!', `FemaleText_loc1`='도와주세요. 제발!', `FemaleText_loc4`='救命。救命！', `FemaleText_loc5`='救命。救命!', `FemaleText_loc7`='Ayuda. ¡Ayuda!' WHERE `ID`=37150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 잡혀 있소!', `MaleText_loc4`='它抓住我了！', `MaleText_loc5`='它抓住我了!', `MaleText_loc7`='¡Me ha pillado!', `FemaleText_loc1`='여기 잡혀 있어요!', `FemaleText_loc4`='它抓住我了！', `FemaleText_loc5`='它抓住我了!', `FemaleText_loc7`='¡Me ha pillado!' WHERE `ID`=37151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워...병이 날 것 같소!', `MaleText_loc4`='喔……我要吐了！', `MaleText_loc5`='哇!我要吐了!', `MaleText_loc7`='¡Buah, me voy a poner enfermo!', `FemaleText_loc1`='워...병이 날 것 같아요!', `FemaleText_loc4`='喔……我要吐了！', `FemaleText_loc5`='哇!我要吐了!', `FemaleText_loc7`='¡Buah, me voy a poner enferma!' WHERE `ID`=37152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과부하 중', `MaleText_loc4`='销毁', `MaleText_loc5`='超載中', `MaleText_loc7`='Sobrecargando', `FemaleText_loc1`='과부하 중', `FemaleText_loc4`='销毁', `FemaleText_loc5`='超載中', `FemaleText_loc7`='Sobrecargando' WHERE `ID`=37153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 희생을 치르더라도 태양샘을 지켜야 한다.', `MaleText_loc4`='无论如何我们都要守住太阳之井。', `MaleText_loc5`='我們一定要不惜代價守住太陽之井。', `MaleText_loc7`='Debemos defender La Fuente del Sol del enemigo pase lo que pase.' WHERE `ID`=37154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 준비를 도울 수 있도록 태양샘으로 물러갈 것을 명한다.', `MaleText_loc4`='我命令你们撤退回太阳之井，在那里协助布置防线。', `MaleText_loc5`='我命令你們撤退進入太陽之井，以便準備防禦。', `MaleText_loc7`='Les ordeno que se retiren hacia La Fuente del Sol para ayudar a preparar las defensas.' WHERE `ID`=37155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 여기에서 가능한 많은 시간을 벌겠다. 왕자님께서 자랑스러워하시도록 그 시간을 잘 활용하라.', `MaleText_loc4`='我会守在这里，尽量为你们争取时间。记住，不要辜负我们的王子。', `MaleText_loc5`='我會守在這裡，盡我所能地替你們爭取時間。好好使用它並讓我們的王子感到驕傲。', `MaleText_loc7`='Yo me quedaré aquí y les daré tanto tiempo como pueda. Usénlo bien y hagan que nuestro príncipe esté orgulloso.' WHERE `ID`=37156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅과 종족을 지키고자 그대들과 함께 싸울 수 있어서 영광이었다.', `MaleText_loc4`='能与你们携手保卫家园和人民，是我的荣幸。', `MaleText_loc5`='能和你們並肩作戰，守護我們的土地與人民是我莫大的榮幸。', `MaleText_loc7`='Ha sido un gran honor combatir a tu lado en defensa de nuestra tierra y nuestro pueblo.' WHERE `ID`=37157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여... 당신은 제 부하가 아니군요. 혹시 저와 함께 여기에서 적과 싸워주시겠습니까?', `MaleText_loc4`='你……你，不是我的士兵。你愿意留下来和我共同抗敌吗？', `MaleText_loc5`='你，陌生人...你不是我的手下。你願意留下來跟我一起面對敵人嗎?', `MaleText_loc7`='Tú... no eres uno de mis soldados. ¿Te quedarás y lucharás a mi lado contra el enemigo?' WHERE `ID`=37158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 녀석들아, 잘 들어라. 내가 지키는 한, 한 놈도 태양샘에 갈 수 없다!', `MaleText_loc4`='天灾的渣滓们，给我听着。只要我活着，你们就休想靠近太阳之井！', `MaleText_loc5`='聽好了，天譴雜碎。只要我還站著，你們就休想靠近太陽之井!', `MaleText_loc7`='Escucha bien, Plaga infecta. ¡Ninguno de ustedes llegará a La Fuente del Sol mientras yo viva!' WHERE `ID`=37159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈앞에서 네 나라와 도시가 무너질 때 너도 함께 쓰러질 것이다. 우리 군주께서 이곳에서 큰 승리를 거두고, 네 이름은 누구의 기억에도 남지 않으리라!', `MaleText_loc4`='你会同你的家园和城池一样遭受灭顶之灾。我的主人会在这里大获全胜，你的名字将被人们遗忘。', `MaleText_loc5`='就如同你的家園和城市在你面前陷落，你也一樣會倒下。我的主人將在此贏得一場大勝，沒有人會記得你的名字!', `MaleText_loc7`='Caerás como tus tierras y tu ciudad han caído antes que tú. Mi señor obtendrá una gran victoria ¡y nadie recordará tu nombre!' WHERE `ID`=37160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찢어지는 듯한 울음소리가 대기를 가르며 들려옵니다!', `MaleText_loc4`='一声尖叫直入云霄！', `MaleText_loc5`='一聲尖銳的咆哮穿透上空!', `MaleText_loc7`='¡Un chillido desgarra el aire!' WHERE `ID`=37161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로!', `MaleText_loc4`='前进！', `MaleText_loc5`='前進!', `MaleText_loc7`='¡Adelante!' WHERE `ID`=37162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐야? 너무 쉽게 죽잖아. 한심한 것들.', `FemaleText_loc4`='什么？这就死了？这也不错。', `FemaleText_loc5`='他們死得太輕鬆了。算了。', `FemaleText_loc7`='Murieron tan fácilmente. No importa.' WHERE `ID`=37163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으! 잠시 쉬어야겠소.', `MaleText_loc4`='啊！我必须休息一下了。', `MaleText_loc5`='喔!我一定得休息一下。', `MaleText_loc7`='¡Aauug! Necesito descansar un momento.' WHERE `ID`=37164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사들이여! 더는 붙잡아 두지 못하겠소.', `MaleText_loc4`='勇士们！我就要挡不住她了。', `MaleText_loc5`='勇士們!我沒辦法繼續困住她了。', `MaleText_loc7`='¡Campeones! No puedo contenerla más tiempo.' WHERE `ID`=37165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受训练。', `MaleText_loc5`='我希望獲得訓練。', `MaleText_loc7`='Me gustaría recibir instrucción.', `FemaleText_loc1`='훈련을 받고 싶어요.', `FemaleText_loc4`='我要接受训练。', `FemaleText_loc5`='我希望獲得訓練。', `FemaleText_loc7`='Me gustaría recibir instrucción.' WHERE `ID`=37166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 내가 직접 처리해 주겠다!', `MaleText_loc4`='我要亲手杀了你！', `MaleText_loc5`='我要親手殺了你!', `MaleText_loc7`='¡Te mataré yo mismo!' WHERE `ID`=37167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는... 너무 강하다. 영웅들이여, 어서... 이쪽으로 오라! 즉시 이곳을 떠나야 한다! 도망치는 동안 그를 잡아놓을 수 있도록 조치를 취하겠다.', `FemaleText_loc4`='他……太强大了。英雄们，快，快过来！我们必须马上离开！你们先走。我会尽全力挡住他。', `FemaleText_loc5`='他...太強大了。英雄們，快點...到我這裡來!我們要立刻離開這裡!我會盡可能地在我們逃走時把他困住。', `FemaleText_loc7`='Es... demasiado poderoso. Héroes, rápido… ¡vengan a mí! Debemos abandonar este lugar ahora mismo. Haré lo que pueda para inmovilizarlo mientras huimos.' WHERE `ID`=37168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스를 그리 오래 붙잡아 둘 수는 없다. 즉시 떠나야 한다!', `FemaleText_loc4`='我没办法阻挡他太久，我们必须马上离开！', `FemaleText_loc5`='我沒辦法困住他太久!我們一定要立刻離開!', `FemaleText_loc7`='No puedo retenerlo mucho tiempo, ¡debemos marcharnos!' WHERE `ID`=37169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='완전히 막다른 곳이다! 이렇게 끝이 나는구나. 마음을 단단히 먹어라, 영웅들이여. 오늘 최후의 싸움을 하리라!', `FemaleText_loc4`='天杀的死路！看来真的无路可走了。准备战斗，英雄们，让我们放手一搏！', `FemaleText_loc5`='天殺的死路!看來結局就是如此了。做好準備，英雄們，今天我們要在這裡背水一戰!', `FemaleText_loc7`='¡MALDICIÓN, NO HAY SALIDA! Así que este es el fin... ¡Prepárense, héroes, hoy será nuestra última batalla!' WHERE `ID`=37170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 안전하다... 당분간은 말이지. 마지막으로 싸웠을 때보다 아서스는 열 배나 강해졌다. 리치 왕을 물리치려면 강력한 군대가 필요하다. 호드가 모을 수 있는 것보다 더 강력한 군대 말이다.', `FemaleText_loc4`='我们暂时……安全了。他的力量已经十倍于往昔。只有一支大军才能战胜巫妖王。单凭部落的力量毫无胜算。', `FemaleText_loc5`='我們安全了...起碼現在如此。他的力量比我們上一次交手時強上十倍。我們需要一支強大的軍隊才能消滅巫妖王。一支遠超過部落動員能力的大軍。', `FemaleText_loc7`=' Estamos a salvo… por ahora. Su fuerza se ha multiplicado por diez desde nuestra última batalla. Necesitamos un ejército poderoso para destruir al Rey Exánime. Un ejército mejor incluso que el que la Horda puede convocar.' WHERE `ID`=37171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나, 네가 믿었던 대로 동맹이 왔구나. 너희 모두 스컬지의 강력한 하수인이 되리라.', `MaleText_loc4`='你的盟友到了，吉安娜，你说的没错。全都变成效忠我的天灾战士吧。', `MaleText_loc5`='珍娜，如同你所承諾的，你的盟友抵達了。你們全都會成為天譴軍團的強大部屬。', `MaleText_loc7`='Han llegado tus aliados, Jaina, como lo prometiste. Se convertirán en poderosos agentes de la Plaga.' WHERE `ID`=37172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스, 같은 실수를 두 번 하지는 않을 것이다. 이번에는 탈출할 수 없다. 모두 죽음으로 나를 섬기리라!', `MaleText_loc4`='我不会再犯同样的错误，希尔瓦娜斯。这次你走不了了，你们死后都会成为我的奴仆！', `MaleText_loc5`='我不會再犯同樣的錯誤，希瓦娜斯。這一次你們將無處可逃。你們全都要在死後服侍我!', `MaleText_loc7`='No volveré a cometer el mismo error, Sylvanas. Esta vez no habrá escapatoria. ¡Todos serán mis siervos después de muertos!' WHERE `ID`=37173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 차디찬 손아귀가 기다린다.', `MaleText_loc4`='阴冷的死亡等待着你。', `MaleText_loc5`='死亡的冰冷擁抱在等著你。', `MaleText_loc7`='El frío abrazo de la muerte los espera.' WHERE `ID`=37174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무덤의 한기에 굴복하라.', `MaleText_loc4`='屈服于死亡的严寒吧！', `MaleText_loc5`='屈服於墓地的酷寒之下吧!', `MaleText_loc7`='Sucumban al frío de la tumba.' WHERE `ID`=37175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 막다른 곳이다.', `MaleText_loc4`='死路一条！', `MaleText_loc5`='又是死路一條!', `MaleText_loc7`='¡Otro camino sin salida!' WHERE `ID`=37176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 방법은 없다!', `MaleText_loc4`='你们无路可逃！', `MaleText_loc5`='無處可逃!', `MaleText_loc7`='¡No hay escapatoria!' WHERE `ID`=37177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인이 죽었습니다! 장비를 갖추십시오! 처리해야 할 스컬지군주가 아직 남았습니다.', `MaleText_loc4`='熔炉之主已经死了！抽刀亮剑，我们要干掉天灾领主。', `MaleText_loc5`='鍛造大師終於死了!穿好你們的裝備，我們還有一個天譴領主要宰。', `MaleText_loc7`='El maestro de la forja está muerto. Prepárense, hombres, tenemos a un Señor de la Plaga al que matar.' WHERE `ID`=37178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 준비하라. 리치 왕의 시대를 끝낼 순간이 왔다.', `MaleText_loc4`='接受现实吧，$c。$b$b巫妖王的统治已经到了尽头。', `MaleText_loc5`='做好準備，$c。$b$b終結巫妖王統治的時刻到了。', `MaleText_loc7`='Prepárate, $c.$b$bHa llegado el momento de que termine el reinado del Rey Exánime.' WHERE `ID`=37179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 선고단이 무엇입니까?', `MaleText_loc4`='灰烬审判军是怎么一回事？', `MaleText_loc5`='什麼是灰燼裁決軍?', `MaleText_loc7`='¿Qué es El Veredicto Cinéreo?', `FemaleText_loc1`='잿빛 선고단이 무엇인가요?', `FemaleText_loc4`='灰烬审判军是怎么一回事？', `FemaleText_loc5`='什麼是灰燼裁決軍?', `FemaleText_loc7`='¿Qué es El Veredicto Cinéreo?' WHERE `ID`=37180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 선고단은 칠흑의 기사단과 은빛십자군에서 가장 능력 있는 장인들을 모아 놓은 단체이다. 그들이 만들어내는 물건은 리치 왕과 그 하수인들에게 마지막 공격을 감행할 때 우리 군대의 단결을 상징한다.$B$B태고의 사로나이트를 마음대로 구부렸다 폈다 하는 법을 발견해낸 것도 잿빛 선고단의 노력 덕이다.', `MaleText_loc4`='灰烬审判军是由黑锋骑士团和银色北伐军中的精英工匠组成的一支队伍。他们的创造标志了一种团结，各支力量齐心协力同巫妖王及其爪牙展开最终的战斗。  $b$b正是通过灰烬审判军的努力，我们掌握了如何将源生萨隆邪铁为我们所用的方法。', `MaleText_loc5`='灰燼裁決軍是一群由黯刃騎士團和銀白十字軍中選出來最有能力的工匠。我們乘坐著他們的創造物攻向巫妖王與他的爪牙，這象徵的是我們部隊的合作。$b$b也是透過灰燼裁決軍的努力，我們才發現要如何讓薩鋼為我們所用。', `MaleText_loc7`='El Veredicto Cinéreo es un grupo selecto de los artesanos con más talento de la Espada de Ébano y la Cruzada Argenta. Su creación simboliza la unión de nuestras fuerzas a medida que ascendemos hacia el asalto final contra el Rey Exánime y sus esbirros.$b$bEs gracias al esfuerzo del Veredicto Cinéreo que hemos descubierto como amoldar la saronita primordial a nuestra voluntad.' WHERE `ID`=37181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하면 태고의 사로나이트 다루는 법을 배울 수 있습니까?', `MaleText_loc4`='如何学习加工源生萨隆邪铁？', `MaleText_loc5`='我要怎麼學會加工原始薩鋼?', `MaleText_loc7`='¿Cómo puedo aprender a trabajar la saronita primordial?', `FemaleText_loc1`='어떻게 하면 태고의 사로나이트 다루는 법을 배울 수 있나요?', `FemaleText_loc4`='如何学习加工源生萨隆邪铁？', `FemaleText_loc5`='我要怎麼學會加工原始薩鋼?', `FemaleText_loc7`='¿Cómo puedo aprender a trabajar la saronita primordial?' WHERE `ID`=37182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사 핑클스타인과 대화해보아라. 그가 길을 알려줄 수 있다.$b$b네 충성심을 증명해 보인다면, 그들이 쓰는 방법을 알게 될 것이다.', `MaleText_loc4`=' $c，和炼金师菲肯斯坦谈谈。他会为你指明道路。$b$b表明你的忠诚，你就会知道他们的办法。', `MaleText_loc5`='去跟鍊金師芬克斯坦談談，$c。他可以幫你指引方向。$b$b證明你的忠誠，他們就會告訴你方法。', `MaleText_loc7`='Habla con el Alquimista Finklestein, $c. Puede guiarte por el buen camino.$b$bDemuestra tu lealtad y te revelará sus métodos.' WHERE `ID`=37183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리한이 있었다면, 리치 왕을 무찌를 수 있었겠습니까?', `MaleText_loc4`='凭借霜之哀伤，我能否击败巫妖王？', `MaleText_loc5`='有了霜之哀傷就能擊敗巫妖王嗎?', `MaleText_loc7`='Con la Agonía de Escarcha, ¿podría derrotar al Rey Exánime?', `FemaleText_loc1`='서리한이 있었다면, 리치 왕을 무찌를 수 있었을까요?', `FemaleText_loc4`='凭借霜之哀伤，我能否击败巫妖王？', `FemaleText_loc5`='有了霜之哀傷就能擊敗巫妖王嗎?', `FemaleText_loc7`='Con la Agonía de Escarcha, ¿podría derrotar al Rey Exánime?' WHERE `ID`=37184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석구나! 그 저주받은 검에 대해서 아무것도 모르는가, $c?$b$b그 검은 네 존재 전부를 삼켜버렸을 것이다. 생명이 빠져나간 네 껍질에 남은 것은 영원토록 적을 섬기며 살아가리라.$b$b아서스에게 아제로스 군단에서 최고의 용사들을 희생시켜야 하는 운명이 닥친 것도 같은 이유에서지.$b$b아직, 무언가 남아 있긴 하지만...', `MaleText_loc4`='蠢货！$c，你对那把诅咒之剑完全不了解？$b$b它会把你彻底吞噬，所剩下的皮囊会为敌人永远效力。$b$b阿尔萨斯的命运就是这样铸成的，艾泽拉斯无数的精英勇士为此而倒下。$b$b不过，可能还有…', `MaleText_loc5`='蠢貨!你對那把詛咒之劍一無所知，$c?$b$b它會把你吞噬殆盡。而不管在你那無生命的軀殼中還剩下什麼，它都將會永遠替敵人服務。$b$b不過是落得跟阿薩斯同樣的下場，葬送了艾澤拉斯最好的勇士。$b$b但或許...', `MaleText_loc7`='¡Tonterías! ¿Es que no sabes nada de esa espada maldita, $c?$b$bTe consumirá por completo. Lo que quede de tu cuerpo inerte pasará toda la eternidad sirviendo al enemigo.$b$bEs lo mismo que llevó a Arthas a su destino y le costó a las legiones de Azeroth su mejor campeón.$b$bAun así, puede que haya algo...' WHERE `ID`=37185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀해 주십시오, 모그레인 대영주님. 무얼 할 수 있겠습니까?', `MaleText_loc4`='那么告诉我，大领主莫格莱尼，我们还能做些什么？', `MaleText_loc5`='告訴我，大領主莫格萊尼。我們還能做些什麼?', `MaleText_loc7`='Dime, alto señor Mograine. ¿Qué podemos hacer?', `FemaleText_loc1`='말씀해 주세요, 모그레인 대영주님. 무얼 할 수 있나요?', `FemaleText_loc4`='那么告诉我，大领主莫格莱尼，我们还能做些什么？', `FemaleText_loc5`='告訴我，大領主莫格萊尼。我們還能做些什麼?', `FemaleText_loc7`='Dime, alto señor Mograine. ¿Qué podemos hacer?' WHERE `ID`=37186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 문제를 계속 생각해봤다.$b$b서리한과 맞먹는 위력을 지녔으면서도 그 주인을 사로잡지 않도록 만들어진 무기가 있다고 믿는다.$b$b그건 신경 쓰지 마라, $r. 그런 게 가능하더라도, 그토록 정교한 유물을 만들 시간이 없다.$b$b지금은 공격에 온 힘을 쏟는 것이 최선이다.', `MaleText_loc4`='我一直不断地思考这个问题。$b$b我相信可以造出一件能与霜之哀伤抗衡但却不会奴役其使用者的武器。$b$b算了，$r。即使有这个可能，也没有打造这样一件神器的时间了。$b$b你最好还是把精力专注在我们的这场战斗上吧。', `MaleText_loc5`='我反覆思量過這件事。$b$b我相信或許能製造一把武器足以跟霜之哀傷的力量匹敵但不會奴役它的持有者。$b$b別管它了，$r。就算有這樣的可能性，現在也沒空製作那樣的神器。$b$b現在最好還是把精力全集中我們的攻勢上。', `MaleText_loc7`='He reflexionado sobre este tema sin descanso.$b$bCreo que puede confeccionarse un arma que pudiera ser rival para la Agonía de Escarcha en cuanto a poder, pero que no esclavizara a su maestro.$b$bDa igual, $r. Incluso si fuera posible, no hay tiempo para crear ese artefacto.$b$BEs mejor que centres tus energías en el asalto.' WHERE `ID`=37187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가능성이 있다면, 제가 시도해 보도록 허락해 주십시오!', `MaleText_loc4`='只要希望尚存，你就必须允许我试上一试！', `MaleText_loc5`='如果有任何機會，請務必讓我試試看!', `MaleText_loc7`='Si hay esperanza, ¡debes permitir que lo intente!', `FemaleText_loc1`='가능성이 있다면, 제가 시도해 보도록 허락해 주세요!', `FemaleText_loc4`='如果希望尚存，请允许我试上一试！', `FemaleText_loc5`='如果有任何機會，請務必讓我試試看!', `FemaleText_loc7`='Si hay esperanza, ¡debes permitir que lo intente!' WHERE `ID`=37188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도, $c|1이여;여;... 아마 있을지도 모르지.$b$b그러나 그 무기를 만들고자 한다면, 잿빛 선고단 제련장인의 방법을 배워야만해.$b$b그들과 교류하면서 충성심과 헌신을 보여라.$b$b그러고 난 다음에, 이 문제를 더 자세히 논의하자.', `MaleText_loc4`='也许，$c…只是也许。$b$b如果你想实现这一杰作，你必须遵循灰烬审判军锻炉之主的方式。$b$b融入他们，证明你的忠诚和奉献的决心。$b$b等你做到以后，我们再来讨论接下去的事。', `MaleText_loc5`='或許吧，$c...或許。$b$b但如果你打算要試著製作它，你必須得學會銀白裁決軍鍛造大師的技藝。$b$b和他們談談看，然後讓他們瞭解你的忠誠與決心。$b$b等你完成這些，我們再來進一步討論。', `MaleText_loc7`='Quizá, $c... quizá.$b$bPero si tú fueras a ser $gel:la; que intentara crearla, deberás aprender el arte de los maestros de forja del Veredicto Argenta.$b$bAsóciate con ellos y demuestra tu lealtad y dedicación.$b$bCuando hayas terminado, hablaremos más sobre ello.', `FemaleText_loc1`='아마도, $c|1이여;여;... 아마 있을지도 모르지.$b$b그러나 그 무기를 만들고자 한다면, 잿빛 선고단 제련장인의 방법을 배워야만해.$b$b그들과 교류하면서 충성심과 헌신을 보여라.$b$b그러고 난 다음에, 이 문제를 더 자세히 논의하자.', `FemaleText_loc4`='也许，$c…只是也许。$b$b如果你想实现这一杰作，你必须遵循灰烬审判军锻炉之主的方式。$b$b融入他们，证明你的忠诚和奉献的决心。$b$b等你做到以后，我们再来讨论接下去的事。', `FemaleText_loc5`='或許吧，$c...或許。$b$b但如果你打算要試著製作它，你必須得學會銀白裁決軍鍛造大師的技藝。$b$b和他們談談看，然後讓他們瞭解你的忠誠與決心。$b$b等你完成這些，我們再來進一步討論。', `FemaleText_loc7`='Quizá, $c... quizá.$b$bPero si tú fueras a ser $gel:la; que intentara crearla, deberás aprender el arte de los maestros de forja del Veredicto Argenta.$b$bAsóciate con ellos y demuestra tu lealtad y dedicación.$b$bCuando hayas terminado, hablaremos más sobre ello.' WHERE `ID`=37189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쟁취 중', `MaleText_loc4`='夺取中', `MaleText_loc5`='佔領中', `MaleText_loc7`='Capturando', `FemaleText_loc1`='쟁취 중', `FemaleText_loc4`='夺取中', `FemaleText_loc5`='佔領中', `FemaleText_loc7`='Capturando' WHERE `ID`=37190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물에 대해 더 자세히 말씀해 주십시오, 모그레인 대영주님.', `MaleText_loc4`='请告诉我更多有关这件神器的事，大领主莫格莱尼。', `MaleText_loc5`='拜託，告訴我更多關於神器的事情，大領主莫格萊尼。', `MaleText_loc7`='Por favor, háblame de este artefacto, alto señor Mograine.', `FemaleText_loc1`='이 유물에 대해 더 자세히 말씀해 주세요, 모그레인 대영주님.', `FemaleText_loc4`='请告诉我更多有关这件神器的事，大领主莫格莱尼。', `FemaleText_loc5`='拜託，告訴我更多關於神器的事情，大領主莫格萊尼。', `FemaleText_loc7`='Por favor, háblame de este artefacto, alto señor Mograine.' WHERE `ID`=37191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도, $c|1이여;여;... 아마 있을지도 모르지.$b$b그러나 그 무기를 만들고자 한다면, 잿빛 선고단 제련장인의 방법을 배워야만해.$b$b그들과 교류하면서 충성심과 헌신을 보여라.$b$b그러고 난 다음에, 이 문제를 더 자세히 논의하자.', `MaleText_loc4`='也许，$c…只是也许。$b$b如果你想实现这一杰作，你必须遵循灰烬审判军熔炉之主的方式。$b$b融入他们，证明你的忠诚和奉献的决心。$b$b等你做到以后，我们再来讨论接下去的事。', `MaleText_loc5`='或許吧，$c...或許。$b$b但如果你打算要試著製作它，你必須得學會銀白裁決軍鍛造大師的技藝。$b$b和他們談談看，然後向他們證明你的忠誠與決心。$b$b等你完成這些，我們再來進一步討論。', `MaleText_loc7`='Quizá, $c... quizá.$b$bPero si tú fueras a ser $gel:la; que intentara crearla, deberás aprender el arte de los maestros de forja del Veredicto Argenta.$b$bAsóciate con ellos y demuestra tu lealtad y dedicación.$b$bCuando hayas terminado, hablaremos más sobre ello.' WHERE `ID`=37192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠서리가 무엇입니까?', `MaleText_loc4`='什么是暗影冰霜？', `MaleText_loc5`='什麼是暗霜?', `MaleText_loc7`='¿Qué es la escarcha de las Sombras?', `FemaleText_loc1`='어둠서리가 무엇인가요?', `FemaleText_loc4`='什么是暗影冰霜？', `FemaleText_loc5`='什麼是暗霜?', `FemaleText_loc7`='¿Qué es la escarcha de las Sombras?' WHERE `ID`=37193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저, 그 검은 우리 적을 섬기는 자들의 영혼을 받아야 한다. 그러고 나서, 그 검이 그들의 힘을 이용하기 전에, 어둠서리에 담아야 한다. 이렇게 하면 너를 집어삼켜 버릴지도 모르는 타락한 목소리를 막을 수 있다... 막기를 바란다.', `MaleText_loc4`='首先，宝剑必须吞噬我们敌人奴仆的灵魂。在动用它们的力量之前，宝剑还必须侵注暗影冰霜。这将使你不受堕落之音的侵害，否则你会被它吞噬…希望这可以起作用。', `MaleText_loc5`='首先，這把武器必須要以我們敵人僕從的靈魂餵食。然後，在兵刃吸收他們的力量之前，我必須以暗霜包裹它。這樣可以把它腐化之聲給隔離開來，否則它將會吞噬你...希望這樣有用。', `MaleText_loc7`='Primero, la espada debe alimentarse con las almas de aquellos que sirven al enemigo. Después, antes de que el filo utilice su poder, debo encerrarla en escarcha de las Sombras. Esto te aislará de las voces corruptoras que, si no, te consumirían... espero.' WHERE `ID`=37194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 리치 왕이 가까이에 있소. 그의 음성이 나를 조롱한다오...$b$b입을 다물게 해 주시오!', `MaleText_loc4`='巫妖王已经离我们很近了，$n。我感觉到了他声音中的嘲弄…$b$b去让他安静下来吧！', `MaleText_loc5`='巫妖王就在附近，$n。他的聲音在嘲弄我...$b$b讓我們叫他永遠閉嘴!', `MaleText_loc7`='El Rey Exánime está cerca, $n. Su voz me provoca...$b$b¡Acallémoslo de una vez!' WHERE `ID`=37195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는... 살아남지 못할 운명이었습니다.', `MaleText_loc4`='我……我没有想过能生还。', `MaleText_loc5`='我...我不該在這攻擊中活下來。', `MaleText_loc7`='Yo... no debería haber sobrevivido a este ataque.' WHERE `ID`=37196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이런 일이 일어났습니까? 왜 여기에 오셨습니까?', `MaleText_loc4`='为什么会发生这种事？为什么你会来？', `MaleText_loc5`='為什麼會發生這些?為什麼你會到這裡來?', `MaleText_loc7`='¿Por qué ha ocurrido esto? ¿Por qué has venido?' WHERE `ID`=37197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘델라로군요! 그 검을 손에 넣으시다니!', `MaleText_loc4`='这是奎尔德拉！你获得了它！', `MaleText_loc5`='那是奎爾德拉!你帶著那把劍!', `MaleText_loc7`='¡Es Quel''Delar! ¡Tú posees la espada!' WHERE `ID`=37198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게인지 모르지만, 검이 당신을 새로운 주인으로 선택했군요. 검과 함께 축복을 받으십시오. 그리고 저처럼, 스컬지를 상대로 휘둘러주십시오.', `MaleText_loc4`='我说不清楚，但这把剑已经认定你是它的新主人。请带上我的祝福，像我一样去血战天灾军团！', `MaleText_loc5`='我不知道為什麼，但那把劍選擇你作為它的新持有者。帶著它還有我的祝福，用它對抗天譴軍團，就像我以前那樣。', `MaleText_loc7`='No sé cómo, pero la espada te ha elegido para que la portes. Llévala con mi bendición y utilízala contra la Plaga, como hice yo una vez.' WHERE `ID`=37199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수세기 전, 악마 군주인 킬제덴은 주술사 넬쥴의 영혼을 얼어붙은 수정 안에 가두기 전에 그를 영원히 계속되는 것만 같은 고문에 처하게 했다. 이게 바로 뒤틀린 황천의 심연에서 만들어진 그 감옥으로, 우리는 얼어붙은 왕좌라고 부르지.$b$b아서스가 서리한으로 수정을 깨뜨리고 나서 넬쥴의 영혼과 융합한 다음 리치 왕이 되었다. 이 왕좌를 깨뜨렸을 때 생겨난 [어둠서리]의 얼어붙은 파편은 지금 성채 곳곳에 흩어져 있다.', `MaleText_loc4`='很早以前，恶魔领主基尔加丹迫使萨满耐奥祖向他屈服，在受尽无尽折磨后，耐奥祖的灵魂被封禁在一块冰封的水晶之中。这是一个在扭曲虚空的深入打造的监牢，我们将它称为冰封王座。$b$b直到后来阿尔萨斯用霜之哀伤击碎了那块水晶，将耐奥祖的灵魂融入自身，便成了巫妖王。王座的碎裂产生了[shadowfrost]冰封碎片，这些碎片现在就散落在冰冠堡垒中。', `MaleText_loc5`='許多年前，惡魔領主基爾加丹讓薩滿耐祖奧屈服於他，然後在無盡折磨之後，將耐祖奧的靈魂封入冰凍的水晶中。而那個在扭曲虛空的深淵中所鑄造的監牢，後來被我們稱為冰封王座。$b$b直到阿薩斯以霜之哀傷擊碎水晶，讓他自己與耐祖奧的靈魂融合，成為巫妖王。王座粉碎時四散的冰凍碎片就是[暗影冰晶]，如今散落在整個冰冠城塞中。', `MaleText_loc7`='Hace mucho tiempo, el señor demoníaco Kil''jaeden sometió al chamán, Ner''zhul, a lo que parecía una tortura sin fin antes de sellar su alma en un cristal helado. Es esta cárcel, forjada en las profundidades del Vacío Abisal, la que hoy en día llamamos el Trono Helado.$b$bUna vez Arthas hizo añicos el cristal con la Agonía de Escarcha, se fusionó con el alma de Ner''zhul y se convirtió en el Rey Exánime. Al destrozar el trono se crearon los fragmentos helados de [escarcha de las Sombras] que ahora están repartidos por toda la ciudadela.' WHERE `ID`=37200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추게! 그 검을 들고 더 나아가서는 안 돼!', `MaleText_loc4`='住手！你快把那剑放下！', `MaleText_loc5`='快停!別再繼續拿著那把劍!', `MaleText_loc7`='¡Alto! ¡No den un paso más con esa espada!' WHERE `ID`=37201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 무슨 짓을 했는지 아는가?', `MaleText_loc4`='你知道你在干什么吗？', `MaleText_loc5`='你知道自己做了什麼嗎?', `MaleText_loc7`='¿Se dan cuenta de lo que han hecho?' WHERE `ID`=37202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또, 가스 전기 부주의, 타기 쉬운 침대 불장난 사고인가요?', `MaleText_loc4`='又一起电气煤炉燃床瓦斯意外火灾事故？', `MaleText_loc5`='另一場有缺陷的電瓦斯燃床煙火所引發的意外嗎?!', `MaleText_loc7`='¡¿Otro accidente con un fallo eléctrico, una cama inflamable, gas y fuegos artificiales?!' WHERE `ID`=37203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 이 검을 고대 신의 피, 사로나이트로 벼려냈네. 리치 왕의 힘이 이 검을 부른다네.', `MaleText_loc4`='你用上古之神的血，萨隆邪铁重铸了这把剑。巫妖王的力量会召唤它。', `MaleText_loc5`='你以古神之血塑成的薩鋼鑄造了這把劍。巫妖王的力量正在呼喚這柄武器。', `MaleText_loc7`='Han forjado esta espada con saronita, la mismísima sangre de un Dios Antiguo. El poder del Rey Exánime llama a esta arma.' WHERE `ID`=37204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검을 정화할 방법은 딱 하나뿐일세. 서둘러 태양샘으로 가서 그 물에 검을 담그게.', `MaleText_loc4`='只有一个办法能净化它。赶快到太阳之井去，将剑沉入井水之中。', `MaleText_loc5`='淨化這柄劍只有一個方法。盡快趕去太陽之井，將劍浸在井水之中。', `MaleText_loc7`='Solo hay una manera de limpiar esta espada. Apresúrense a La Fuente del Sol y sumerjan la espada en sus aguas.' WHERE `ID`=37205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 서리한의 부름에 저항할 수 없네...', `MaleText_loc4`='我抵抗不住霜之哀伤的召唤…', `MaleText_loc5`='我無法繼續抵抗霜之哀傷的呼喚了...', `MaleText_loc7`='No puedo resistir más el llamado de la Agonía de Escarcha…' WHERE `ID`=37206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 빛의 복수를 되찾아야 합니까?', `MaleText_loc4`='为什么我必须取回圣光的复仇？', `MaleText_loc5`='為什麼我得找回聖光報復?', `MaleText_loc7`='¿Por qué debo recuperar la Venganza de la Luz?', `FemaleText_loc1`='왜 빛의 복수를 되찾아야 하나요?', `FemaleText_loc4`='为什么我必须取回圣光的复仇？', `FemaleText_loc5`='為什麼我得找回聖光報復?', `FemaleText_loc7`='¿Por qué debo recuperar la Venganza de la Luz?' WHERE `ID`=37207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스가 서리한을 들어 올릴 때 내던진 망치에는 엄청난 잠재력이 담겼다.$b$b그 망치 때문에 이 세계의 운명을 결정지은 사건이 일어났지. 그 안에는 이해하기도 어려운 힘이 엄청나게 담겼다.$b$b사로나이트가 충분히 있으면 서리한에 대적할만한 무기로 그 망치를 다시 벼려낼 수 있다.$b$b네게 가장 위험한 시험이 시작되는 것은 그때부터다...', `MaleText_loc4`='阿尔萨斯在选择霜之哀伤时丢弃的战锤中蕴藏了极大的潜力。$b$b那股力量曾引发过奠定世界命运的事件。它拥有的强大力量很少有人能够领悟。$b$b给我足够的萨隆邪铁，我能将这把战锤打造成一件可以对抗霜之哀伤的神器。$b$b那时，你便开始了一项最危险的试炼…', `MaleText_loc5`='當阿薩斯拔出霜之哀傷時，他捨棄了這把錘子，但它有著巨大的潛能。$b$b它曾協助過改變這世界命運的事件。很少人瞭解到它能發揮出強大的力量。$b$b只要有大量的薩鋼，我就能將這柄鐵錘重鑄成一把神器，足以跟霜之哀傷匹敵。$b$b然而這才是你最危險試煉的開端...', `MaleText_loc7`='Hay un gran potencial en el martillo que Arthas abandonó cuando tomó la Agonía de Escarcha.$b$bHa ayudado a dirigir las circunstancias que han dibujado el destino de este mundo. Posee un gran poder que pocos entienden.$b$bCon algo de saronita puedo volver a forjar el martillo para ser rival de la mismísima Agonía de Escarcha.$b$bEntonces comenzará la prueba más peligrosa para ti...' WHERE `ID`=37208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일을 시작하고 싶습니다, 모그레인 대영주님!', `MaleText_loc4`='我十分渴望启动我们的工作，大领主莫格莱尼！', `MaleText_loc5`='我等不及要開始我的工作了，大領主莫格萊尼!', `MaleText_loc7`='¡Estoy ansioso por comenzar nuestro trabajo, Alto señor Mograine!', `FemaleText_loc1`='할 일을 시작하고 싶어요, 모그레인 대영주님!', `FemaleText_loc4`='我十分渴望启动我们的工作，大领主莫格莱尼！', `FemaleText_loc5`='我等不及要開始我的工作了，大領主莫格萊尼!', `FemaleText_loc7`='¡Estoy ansiosa por comenzar nuestro trabajo, Alto señor Mograine!' WHERE `ID`=37209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의욕이 지나치지 않도록 자제하라, $r|1이여;여;.$b$b너를 파멸로 이끌지도 모르는 어리석은 짓을 할 수도 있으니. 우리 중 가장 고결한 자를 타락시켰던 존재가 너를 끊임없이 괴롭힐 수 있음을 미리 예측하고 있어라.$b$b이것 또한 염두에 두어라. 만약 굴복하면 네가 이 세상의 끈을 놓도록 도울 수밖에 없다는 것을.', `MaleText_loc4`='收起你的激情吧，$r。$b$b你正在进行一项徒劳的任务，并且这任务很可能会毁了你。那些使我们最高贵的同伴变得堕落的力量会向你无情地袭来。$b$b相信这一切吧；屈服吧，我将不得不把你逐出这个世界。', `MaleText_loc5`='控制你的熱情，$r。你所要進行的愚蠢任務可能會導致你自己的毀滅。它腐化我們之中最高貴的人，也將會無情地攻擊你。$b$b要知道，如果你一旦屈服，我將別無選擇只能讓你從這世上解脫。', `MaleText_loc7`='Pon freno a tu entusiasmo, $r.$b$bTe embarcas en un recado de locos que sin duda será tu fin. Las fuerzas que han corrompido a los más nobles de los nuestros te asaltarán sin descanso.$b$bDebes saber: si sucumbes, no tendré más opción que despacharte de este mundo.' WHERE `ID`=37210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공격할 준비를 합니다!', `MaleText_loc4`='%s准备攻击！', `MaleText_loc5`='%s準備攻擊!', `MaleText_loc7`='¡%s se prepara para atacar!' WHERE `ID`=37211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승선하라, 당장! 언제 이쪽 산 전체가 무너져내릴지 모른다.', `MaleText_loc4`='立刻上船！快！这面山壁随时都可能塌陷。', `MaleText_loc5`='立刻上船!這片山坡可能隨時都會崩塌。', `MaleText_loc7`='¡A bordo, YA! La ladera de la montaña se derrumbará en cualquier momento.' WHERE `ID`=37212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 승선하라! 여기에서 늑장부려서는 안 된다! 이쪽 산 전체가 언제 무너질지 아무도 모른다.', `MaleText_loc4`='快！立刻上船！此地不可久留，整面山壁随时都可能塌陷。', `MaleText_loc5`='快點，快爬上來!我們不能在此耽擱了!誰知道這片山坡什麼時候會崩塌。', `MaleText_loc7`='¡Rápido, a bordo! ¡No debemos entretenernos! La ladera de la montaña se derrumbará en cualquier momento.' WHERE `ID`=37213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕을 방어하십시오!', `MaleText_loc4`='守住山丘！', `MaleText_loc5`='防禦山丘!', `MaleText_loc7`='¡Defiende la colina!' WHERE `ID`=37214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공입니다! 언덕을 차지했습니다!', `MaleText_loc4`='成功！这座山丘是你的了！', `MaleText_loc5`='成功!山丘是你的了!', `MaleText_loc7`='¡Has ganado! ¡La colina es tuya!' WHERE `ID`=37215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배했습니다! 방어 세력이 언덕을 지키지 못했습니다.', `MaleText_loc4`='失败了！防御部队无法守住那座山丘。', `MaleText_loc5`='戰敗了!守衛們無法守住山丘。', `MaleText_loc7`='¡Has perdido! Los defensores no han podido mantener el control de la colina.' WHERE `ID`=37216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림토템 부족은 절대로 항복하지 않는다!', `MaleText_loc4`='恐怖图腾绝不投降！', `MaleText_loc5`='恐怖圖騰永遠不會投降!', `MaleText_loc7`='¡Los Tótem Siniestro no se rendirán nunca!' WHERE `ID`=37217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐방울만한 쪼끄만 존재들, 가프로스트에게 맛난 거 가져왔다!', `MaleText_loc4`='看这些小东西，你给加弗斯特带来了好吃的！', `MaleText_loc5`='小東西在我的腳下，你帶了好東西給加弗羅斯吃!', `MaleText_loc7`='¡Criaturitas de los pies, traigan a Gargelus algo bueno para comer!' WHERE `ID`=37218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간식으로 남겨놔야지. 나중에 먹게.', `MaleText_loc4`='可以留下来当个小点心。', `MaleText_loc5`='留起來當點心。晚點吃。', `MaleText_loc7`='Guardaré de refrigerio. Más tarde.' WHERE `ID`=37219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 아마... 지금 먹으면 맛없을 거다. 바보 가프로스트! 나쁘다! 나빠!', `MaleText_loc4`='这个好像不……不太好吃。加弗斯特真笨！真笨！', `MaleText_loc5`='這個可不適合現在吃。笨加弗羅斯!壞!壞!', `MaleText_loc7`='Este no... no tan rico para comer ahora. ¡Gargelus tonto! ¡MALO! ¡MALO!' WHERE `ID`=37220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가프로스트 커다란 속옷 안 보이면 좋겠다. 두목님 나중에 창피하지 않게.', `MaleText_loc4`='加弗斯特不想弄的太狼狈。不想给头领丢脸。晚了。', `MaleText_loc5`='加弗羅斯希望沒拉在超大內褲上。免得待會讓老大丟臉。', `MaleText_loc7`='Gargelus llevar calzones limpios, esperar. Evitar mucha vergüenza al jefe. Más tarde.' WHERE `ID`=37221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일을 방해하게 둘 순 없어! 이크, 저놈들을 처리해!', `MaleText_loc4`='我们的工作绝不能被干扰！伊克，招呼他们！', `MaleText_loc5`='我們的工作不能受到干擾!艾克，去處理他們!', `MaleText_loc7`='¡Nuestro trabajo no debe ser interrumpido! ¡Ick, ocúpate de ellos!' WHERE `ID`=37222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부분은 아마 쓸모가 있을 거야.', `MaleText_loc4`='这些部件也许对我们有用。', `MaleText_loc5`='我們或許可以用上這些零件。', `MaleText_loc7`='Estas partes podrían servirnos.' WHERE `ID`=37223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔과 다리가 부족해! 네가 보태준다니 고마워!', `MaleText_loc4`='我们正缺胳膊和腿呢！感谢你们的大力援助！', `MaleText_loc5`='手臂和腿有點短缺!感謝你們的貢獻!', `MaleText_loc7`='¡El suministro de piernas y brazos escasea! ¡Gracias por tu aportación!' WHERE `ID`=37224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 바뀌었어, 대신 저놈을 잡아!', `MaleText_loc4`='我改主意了，现在我要的是这个！', `MaleText_loc5`='我改變心意了，換成那個傢伙!', `MaleText_loc7`='Cambié de idea, ¡mejor ése!' WHERE `ID`=37225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그놈을 공격해? 더 위험한 놈은 저기 있는데! 이 바보!', `MaleText_loc4`='你打这个家伙干什么？真正危险的人在那儿，傻子！', `MaleText_loc5`='你攻擊那個傢伙做什麼?危險的是在那邊!', `MaleText_loc7`='¿Para qué lo atacas a él? ¡El peligroso es aquel de allí, imbécil!' WHERE `ID`=37226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가! 나는 왕관화학회사를 대표해서 여기 나왔어.$B$B선물이 필요해? 아니면 일? 아마 작게라도 무언가 자신에게 도움이 될 거 말이지? 음. 그럼 제대로 온 거야, 친구.$B$B네가 필요한 물건은 나한 테 없어. 우리 귀염둥이 큐이피나 내 옆에 있는 사랑의 상인이 가지고 있을 거야.', `MaleText_loc4`='嗨！我来自皇冠药剂公司。$B$B你在寻找礼物吗？还是要找份工作？想不想送自己点东西？好吧，你来对地方了，朋友。$B$B如果我没有你想要的东西，那么在我旁边的福星基维或是可爱的商贩一定会有。', `MaleText_loc5`='唷!我代表了王冠化學製藥公司。$B$B你在找禮物嗎?找工作?或許是給自己的一點小東西?很好，你找對地方了，朋友。$B$B如果我沒有你想要的東西，我們的吉祥物或我身後的可愛商品商人也一定會有。', `MaleText_loc7`='¡Eh! Vengo en representación de Químicos La Corona, S.L.$b$b¿Buscas un regalo? ¿Un trabajo? ¿Algo para ti? Bueno, has venido al lugar adecuado, $gamigo:amiga;.$b$bSi no tengo lo que buscas, nuestra mascota Kwee o la mercader preciosa a mi lado lo tendrán.' WHERE `ID`=37227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 새시. 준비됐어요.', `MaleText_loc4`='好的，莎希，我已经准备好出发了。', `MaleText_loc5`='好啦，賽希，我準備好上路了。', `MaleText_loc7`='Ya, Sassy, estoy listo para ir.', `FemaleText_loc1`='좋아요. 새시. 준비됐어요.', `FemaleText_loc4`='好的，莎希，我已经准备好出发了。', `FemaleText_loc5`='好啦，賽希，我準備好上路了。', `FemaleText_loc7`='Ya, Sassy, estoy lista para ir.' WHERE `ID`=37228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 비축된 물자를 이용해 사람들을 무장시키겠소.$B$B계속 전진하시오. 저 위에서 봅시다.', `MaleText_loc4`='我们要利用那些补给为所有人做好战斗的准备。$B$B继续吧。我们会再见面的。', `MaleText_loc5`='我們會利用這些補給，讓所有人準備好戰鬥。$B$B繼續吧。我們在前面跟你碰頭。', `MaleText_loc7`='Utilizaremos estos suministros para preparar a todos para el combate.$b$bSigan adelante. Nos encontraremos más adelante.' WHERE `ID`=37229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예가 된 다른 이들을 모아 전투를 준비하겠소. 스컬지군주 티라누스를 상대하기 전에 당신과 합류하겠소.', `MaleText_loc4`='我会集结其它的奴隶，被让他们做好战斗的准备。在你同天灾领主泰兰努斯开始交战前我们会赶上你的。', `MaleText_loc5`='我會召集剩下的奴隸讓他們準備好作戰。我們會在你對上天譴領主提朗紐斯之前趕上你。', `MaleText_loc7`='Yo reuniré a los demás esclavos y los prepararé para luchar. Te alcanzaremos antes de que comiences a luchar contra el Señor de la Plaga Tyrannus.' WHERE `ID`=37230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때 안전한 타우라조 야영지에서 젊은 사냥꾼들에게 야생의 방식을 가르친 적이 있네.$B$B지금은 그와 같은 사치를 누릴 수 없네. 문 앞에 진을 친 적과의 전투, 그 열기 속에서 기술을 계속 익혀야 할 것이네.', `MaleText_loc4`='我曾经在陶拉祖营地安全的环境中训练年轻的猎人熟悉荒野之道。$B$B现在我们不能奢望再有那种条件了。敌人已经踏过了我们的门槛，我们的年轻人必须在与敌人的激烈搏杀中学会战斗的技巧。', `MaleText_loc5`='為了陶拉祖營地的安全，我曾經訓練年輕的獵人們讓他們了解大自然的一切。$B$B但我們現在沒有這種時間了。我們的敵人就在這的門口前紮營，生存技巧必須直接在實戰中學習。', `MaleText_loc7`='Hace tiempo instruía a los cazadores jóvenes en las artes de la vida salvaje desde la seguridad del Campamento Taurajo.$b$bYa no podemos permitirnos semejante lujo: las facultades deben aprenderse en el fragor de la batalla contra un enemigo acampado en tu rellano.' WHERE `ID`=37231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여! 죽음을 각오하고, 숨을 거두는 그 순간까지 언데드를 저지하겠습니다. 스컬지군주를 상대하십시오!', `MaleText_loc4`='英雄们！我们就算拼了性命，也会挡住那些亡灵。去消灭天灾领主吧！', `MaleText_loc5`='英雄們!我們拼著最後一口氣也會擋住那些不死生物。去對付天譴領主!', `MaleText_loc7`='¡Héroes! Retendremos a los no-muertos cuanto podamos, hasta nuestro aliento final. ¡Encárguense del Señor de la Plaga!' WHERE `ID`=37232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아. 용감하고 용감한 모험가들아, 참견도 이제 끝이다. 네놈들 뒤에 있는 굴에서 뼈와 칼이 부딪치는 소리가 들리는가? 네놈들에게 곧 닥칠 죽음의 소리다.', `MaleText_loc4`='唉，勇敢的冒险者，你们的路已经到头了。难道你们没有听到身后隧道里钢铁撞击的声音吗？那就是末日降临的乐章。', `MaleText_loc5`='終於，勇敢、勇敢的冒險者，你的干擾終到盡頭。你聽見了身後隧道中的金屬與骨頭敲擊聲嗎?這就是你即將面對的死亡之聲。', `MaleText_loc7`='Qué pena, valientes, valientes aventureros, su intromisión ha llegado a su fin. ¿Oyen el ruido de huesos y acero acercándose por ese túnel detrás de ustedes? Es el sonido de su inminente muerte.' WHERE `ID`=37233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하, 어중이떠중이치고는 꽤 놀라운걸. 네놈을 처리하고 나면 주인님의 칼이 네 영혼으로 잔치를 벌이리라. 죽어라!', `MaleText_loc4`='哈，一群不自量力的乌合之众。等我杀了你们之后，主人的剑就能尽情享用你们的灵魂了。去死吧。', `MaleText_loc5`='哈，多可笑的賤民騷動。等我解決你，我主之劍將會大啖你們的靈魂。死吧。', `MaleText_loc7`='Ja, un gesto tan divertido de la multitud. Cuando haya terminado con ustedes, la espada de mi amo se alimentará de sus almas. ¡Mueran!' WHERE `ID`=37234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들의 지시를 따르겠소, 영웅들이여. 오늘, 스컬지군주는 쓰러질 것이오.', `MaleText_loc4`='英雄们，我们会追随你们的领导。今夕就是天灾领主的死期。', `MaleText_loc5`='我們會跟隨你的領導，英雄們。天譴領主將會就此死去。', `MaleText_loc7`='Los seguiremos, héroes. El Señor de la Plaga morirá hoy.' WHERE `ID`=37235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낟알 한 줌을 바람에 날려 보내는 디아미.', `MaleText_loc4`='将一把谷粒撒向风中。', `MaleText_loc5`='將稻米灑向空中隨風而飄。', `MaleText_loc7`='lanza un puñado de grano al viento.' WHERE `ID`=37236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다!', `MaleText_loc4`='谢谢！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!', `FemaleText_loc1`='고마워요!', `FemaleText_loc4`='谢谢！', `FemaleText_loc5`='謝謝你!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=37237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그 소문이 사실이었군요! 저주에 걸린 사람들조차도 포세이큰과 싸우다니!', `MaleText_loc4`='这是真的？就连那些身陷诅咒的人也在和被遗忘者作战！', `MaleText_loc5`='所以這是真的?就連那些遭受詛咒的人都在與被遺忘者戰鬥!', `MaleText_loc7`='¿Entonces es verdad? ¡Hasta las víctimas de la maldición luchan contra los Renegados!', `FemaleText_loc1`='정말 그 소문이 사실이었어요! 저주에 걸린 사람들조차도 포세이큰과 싸우다니요!', `FemaleText_loc4`='这是真的？就连那些身陷诅咒的人也在和被遗忘者作战！', `FemaleText_loc5`='所以這是真的?就連那些被詛咒的人都在與被遺忘者戰鬥!', `FemaleText_loc7`='¿Entonces es verdad? ¡Hasta las víctimas de la maldición luchan contra los Renegados!' WHERE `ID`=37238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰은 그들이 저지른 만행의 대가를 치르게 될 겁니다!', `MaleText_loc4`='被遗忘者将要为他们所犯的罪行付出代价！', `MaleText_loc5`='被遺忘者將會為他們所做的付出代價!', `MaleText_loc7`='¡Los Renegados pagarán por lo que han hecho!', `FemaleText_loc1`='포세이큰은 그들이 저지른 만행의 대가를 치르게 될 거예요!', `FemaleText_loc4`='被遗忘者将要为他们所犯的罪行付出代价！', `FemaleText_loc5`='被遺忘者將會為他們所做的付出代價!', `FemaleText_loc7`='¡Los Renegados pagarán por lo que han hecho!' WHERE `ID`=37239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티가 뭐 어쩌고 어째? 난 초대도 안 하고?', `MaleText_loc4`='怎么回事儿？听说你要搞个聚会，却没有邀请我！', `MaleText_loc5`='我聽到什麼派對了嗎? 我沒有受到邀請!', `MaleText_loc7`='¿Oí que hay una fiesta? ¡No me invitaron!' WHERE `ID`=37240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으른 놈들! 어서 일하지 못해? 특히 너!', `MaleText_loc4`='你们这帮懒鬼！赶快回去工作，特别是你，$n！', `MaleText_loc5`='你們都是懶鬼! 全都回去工作，特別是你，$n!', `MaleText_loc7`='¡Holgazanes! ¡A trabajar, especialmente tú!' WHERE `ID`=37241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 경기에서 상어들이 해적단한테 이기면 다 강등이다!', `MaleText_loc4`='如果鲨鱼队击败了海盗队，所有人都要降职！', `MaleText_loc5`='如果鯊魚隊打贏海盜隊，全部的人都降職!', `MaleText_loc7`='¡Descensos para todos si los Tiburones les ganan a los Bucaneros!' WHERE `ID`=37242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 너! 본부 밖에서 뭘 하고 있는 거지? 당장 복귀하라고!', `MaleText_loc4`='又是你，$n？你跑到总部外面来干什么？还不赶快回去给我工作！', `MaleText_loc5`='是你啊，$n?你離開總部來這裡做什麼?快回去工作!', `MaleText_loc7`='¿Eres tú? ¿Qué haces fuera del cuartel general? ¡A trabajar!' WHERE `ID`=37243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 최고의 무역왕을 맞이해라... 바로 나 말이다!', `MaleText_loc4`='所有人为我——艾泽拉斯最伟大的贸易大王——欢呼！', `MaleText_loc5`='為艾澤拉斯最偉大的貿易親王歡呼吧...那就是我!', `MaleText_loc7`='Alaben al mejor príncipe mercante de Azeroth... ¡yo!' WHERE `ID`=37244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 밤낮없이 열심히 일해준 덕에 야근 연장 승인이 났다! 물론 무급이지!', `MaleText_loc4`='感谢你的努力工作和无私奉献。没有报酬的加班对所有人都应该是最合适的安排！', `MaleText_loc5`='感謝你們的努力工作與投入。我通過所有人的無薪假!', `MaleText_loc7`='Gracias por tu esfuerzo y dedicación. ¡Horas extras no asalariadas para todos!' WHERE `ID`=37245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라를 마시자!', `MaleText_loc4`='喝点卡亚可乐吧！', `MaleText_loc5`='暢飲卡迦可樂!', `MaleText_loc7`='¡Bebe Kaja''Cola!' WHERE `ID`=37246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 승진시킨 게 후회되는데!', `MaleText_loc4`='我开始为提拔你而感到后悔了，$n！', `MaleText_loc5`='我開始後悔替你升職了，$n!', `MaleText_loc7`='¡Me estoy arrepintiendo de haberte ascendido!' WHERE `ID`=37247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 시작됐군...', `MaleText_loc4`='终于，开始了……', `MaleText_loc5`='終於，開始了...', `MaleText_loc7`='Y así ha comenzado...' WHERE `ID`=37248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라! 이는 성스러움과 부패의 결합이다. 무한한 힘을 지닌 어둠의 칼날도끼를 제련했다!', `MaleText_loc4`='看啊！神圣与堕落的结合，那就是影锋，一把潜能无限的武器。', `MaleText_loc5`='看吶!神聖與腐化的結合;暗影之鋒的鑄造，擁有無盡潛能的武器!', `MaleText_loc7`='¡Observen! La unión de lo sagrado y lo corrupto: la forja del Filo de las Sombras, un arma de potencial inefable.' WHERE `ID`=37249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 의지 앞에 굴복시켜라. 그러면 엄청난 힘을 쓸 수 있으리라!', `MaleText_loc4`='让它服从你，你就能获得无法想象的力量！', `MaleText_loc5`='讓它順從你的意志，你將能擁有無可言喻的力量!', `MaleText_loc7`='¡Amóldala a tu voluntad y blandirás un poder indescriptible!' WHERE `ID`=37250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하면, 네 영혼은 영원히 노예가 되리라.', `MaleText_loc4`='如果失败，你的灵魂就将永远被奴役。', `MaleText_loc5`='失敗...你的靈魂將永遠成為它的奴隸。', `MaleText_loc7`='Fracasa y tu alma será su esclava para siempre.' WHERE `ID`=37251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 경고한다, 필멸자여. 실패하면, 너는 내 손으로 처리하리라!', `MaleText_loc4`='凡人，这是给你们的最后警告；如果你们失败了，我会亲手毁了你们！', `MaleText_loc5`='最後一次警告，凡人;若失敗，你將會死在我手上!', `MaleText_loc7`='Una última advertencia, mortal. Si fallas, seré yo mismo el que te mate.' WHERE `ID`=37252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 일하란 말이다, 이 버러지 같은 놈들아! 가만있지만 말고 어서 빨리 광물을 캐란 말이야!', `MaleText_loc4`='工作再努力些，你们这帮垃圾！矿石可不会自己蹦出来！', `MaleText_loc5`='認真工作，你們這些蟲子!這些礦不會自己把自己挖起來!', `MaleText_loc7`='¡Trabajad más, gusanos! ¡Ese mineral no se va a excavar solo!' WHERE `ID`=37253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 걸 감사하게 여겨라, 이 나약한 길니아스인들아! 죽기 싫으면 일을 하란 말이다!', `MaleText_loc4`='你能活着是你的运气，吉尔尼斯败狗！现在去工作吧，不要等我们改变主意！', `MaleText_loc5`='我們留下你們的狗命是你們運氣好，吉爾尼斯人!在我們沒改變心意前滾回去工作!', `MaleText_loc7`='¡Tenéis suerte de estar vivos, perros gilneanos! ¡Ahora poneos a trabajar antes de que cambiemos de opinión!' WHERE `ID`=37254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산과 그 안에 있는 모든 것은 이제 여왕 실바나스 님의 소유이다. 물론 버러지 같은 네놈들도 마찬가지지. 그러니 가서 일이나 하란 말이다!', `MaleText_loc4`='这座矿藏和这里的一切都是希尔瓦娜斯女王的财产，也包括你们这些蛆虫。所以，赶快回去工作！', `MaleText_loc5`='這片礦場和所有的一切現在已歸希瓦娜斯女王所有，包括你們這些蟲子也是她的所有物。知道了就回去工作!', `MaleText_loc7`='Ahora esta mina y todo lo que contiene son propiedad de la reina Sylvanas. Eso los incluye a todos ustedes, gusanos, ¡así que volver al trabajo!' WHERE `ID`=37255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 잡아요! 쭉 밟을 거예요!!!', `FemaleText_loc4`='抓紧了！我要把油门踩到底了！', `FemaleText_loc5`='抓好了!我要把油門踩到底了!!!', `FemaleText_loc7`='¡Aguanta! ¡Voy a pisar a fondo!' WHERE `ID`=37256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 돌아가야겠어요.', `FemaleText_loc4`='我们必须试试看。', `FemaleText_loc5`='我們必須避開。', `FemaleText_loc7`='Tendremos que dar un rodeo.' WHERE `ID`=37257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비켜요!', `FemaleText_loc4`='别挡路！', `FemaleText_loc5`='閃開!', `FemaleText_loc7`='¡FUERA DE MI CAMINO!' WHERE `ID`=37258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이제 안전해... 아니, 안돼! 우린 배신당했어요!', `FemaleText_loc4`='我们来了，一切平安……哦，不！我们被骗了！', `FemaleText_loc5`='我們到了，平安無恙又...喔不!我們被出賣了!', `FemaleText_loc7`='Aquí estamos, sanos y salvos y... ¡OH, NO! ¡Hemos sido traicionados!' WHERE `ID`=37259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n에게 |cFF00AACC동결|r을 시전합니다.', `MaleText_loc4`='%s向$n施放|cFF00AACC深度冻结|r。', `MaleText_loc5`='%s對$n施展|cFF00AACC極度冰凍|r。', `MaleText_loc7`='%s lanza |cFF00AACCCongelación profunda|r sobre $n.' WHERE `ID`=37260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 영웅들이여. 나는 뒤에 남아 여러분이 풀어 주는 노예들을 규합하겠소. 여러분이 동쪽에 있는 제련장인을 처치해 준다면, 우리도 장비를 갖춰 전투에 참여할 수 있을 거요.', `MaleText_loc4`='十分感谢，英雄们。我会一直呆在这，将你们施放的奴隶集结起来。如果你们能杀死东北方的熔炉之主，我们便可以把自己武装起来。', `MaleText_loc5`='感謝你，英雄們。我會留在後面並且召集那些被你釋放的奴隸。如果你殺死了東邊的熔爐大師，我們就能替自己裝備武器以便戰鬥。', `MaleText_loc7`='Gracias, héroes. Me quedaré atrás y reuniré a los esclavos que vayan liberando. Si matan al Maestro de forja al este, podremos equiparnos para la batalla.' WHERE `ID`=37261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구덩이에서 죽는 줄 알았습니다. 감사합니다!', `MaleText_loc4`='我以为我会死在这坑里。谢谢你！', `MaleText_loc5`='我還以為我會死在這個深淵裡。謝謝你!', `MaleText_loc7`='Pensé que moriría en este foso. Gracias.', `FemaleText_loc1`='이 구덩이에서 죽는 줄 알았어요. 감사합니다!', `FemaleText_loc4`='我以为我会死在这坑里。谢谢你！', `FemaleText_loc5`='我還以為我會死在這個深淵裡。謝謝你!', `FemaleText_loc7`='Pensé que moriría en este foso. Gracias.' WHERE `ID`=37262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크게 한턱내야겠군요. 감사합니다, 친구여.', `MaleText_loc4`='我欠你一顿好酒，我的朋友。', `MaleText_loc5`='我欠你整晚的暢飲，我的朋友。', `MaleText_loc7`='Te debo una larga noche bebiendo, $gamigo mío:amiga mía;.', `FemaleText_loc1`='크게 한턱내야겠군요. 감사합니다, 친구여.', `FemaleText_loc4`='收下我的礼物吧。', `FemaleText_loc5`='收下我的寶物。', `FemaleText_loc7`='Quiero un hijo tuyo.' WHERE `ID`=37263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 살려 보내지 마십시오.', `MaleText_loc4`='不要放走任何一个。', `MaleText_loc5`='一個也別讓他們活著。', `MaleText_loc7`='No dejes que ninguno viva.', `FemaleText_loc1`='한 놈도 살려 보내지 마세요.', `FemaleText_loc4`='不要放走任何一个。', `FemaleText_loc5`='一個也別讓他們活著。', `FemaleText_loc7`='No dejes que ninguno viva.' WHERE `ID`=37264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁합니다. 저희를 대신해 스컬지군주에게 복수해 주십시오.', `MaleText_loc4`='拜托了，为我们向天灾领主报仇。', `MaleText_loc5`='拜託，幫我們向天譴領主復仇。', `MaleText_loc7`='Por favor, lleva a cabo nuestra venganza sobre el Señor de la Plaga.', `FemaleText_loc1`='부탁합니다. 저희를 대신해 스컬지군주에게 복수해 주세요.', `FemaleText_loc4`='拜托了，为我们向天灾领主报仇。', `FemaleText_loc5`='拜託，幫我們向天譴領主復仇。', `FemaleText_loc7`='Por favor, lleva a cabo nuestra venganza sobre el Señor de la Plaga.' WHERE `ID`=37265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구덩이의 주인을 처치하고 나면, 저 대신 시체에 침을 뱉어 주십시오. 해 주시겠습니까?', `MaleText_loc4`='在你打败矿坑的头目以后，替我向他的尸体吐口水，好吗？', `MaleText_loc5`='等你宰了深淵之主，可以幫我在他的屍體上吐口水嗎?', `MaleText_loc7`='Cuando mates al maestro del foso, escupe sobre su cadáver, ¿de acuerdo?', `FemaleText_loc1`='이 구덩이의 주인을 처치하고 나면, 저 대신 시체에 침을 뱉어 주세요. 해 주시겠어요?', `FemaleText_loc4`='在你打败矿坑的头目以后，替我向他的尸体吐口水，好吗？', `FemaleText_loc5`='等你宰了深淵之主，可以幫我在他的屍體上吐口水嗎?', `FemaleText_loc7`='Cuando mates al maestro del foso, escupe sobre su cadáver, ¿de acuerdo?' WHERE `ID`=37266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔에 감각이 없을 지경입니다만, 무기만 손에 넣으면 당신과 함께 싸우겠습니다.', `MaleText_loc4`='我感觉我的手臂已经没了，不过只要我找到些武器，我就会和你并肩作战。', `MaleText_loc5`='我幾乎感覺不到我的手臂，但等我找到武器，我一定會跟你並肩作戰。', `MaleText_loc7`='Apenas siento los brazos, pero estaré junto a ti en cuanto encuentre un arma.', `FemaleText_loc1`='팔에 감각이 없을 지경입니다만, 무기만 손에 넣으면 당신과 함께 싸우겠어요.', `FemaleText_loc4`='我感觉我的手臂已经没了，不过只要我找到些武器，我就会和你并肩作战。', `FemaleText_loc5`='我幾乎感覺不到我的手臂，但等我找到武器，我一定會跟你並肩作戰。', `FemaleText_loc7`='Apenas siento los brazos, pero estaré junto a ti en cuanto encuentre un arma.' WHERE `ID`=37267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 끔찍한 장소에 오래 있으니 시간 감각마저 없어지더군요. 당신이 얼마나 반가운지 모릅니다, 친구여.', `MaleText_loc4`='在这个被遗忘的区域，我迷失在了时间的长河中。能见到你真不错，我的朋友。', `MaleText_loc5`='在這個被遺棄的地方，我幾乎失去了時間感。而你是痛苦視界中的一片美景，朋友。', `MaleText_loc7`='Había perdido la noción del tiempo en este maldito lugar. Da gusto verte, $gamigo:amiga;.', `FemaleText_loc1`='이 끔찍한 장소에 오래 있으니 시간 감각마저 없어지더군요. 당신이 얼마나 반가운지 모릅니다, 친구여.', `FemaleText_loc4`='在这个被遗忘的区域，我迷失在了时间的长河中。能见到你真不错，我的朋友。', `FemaleText_loc5`='在這個被遺棄的地方，我幾乎失去了時間感。而你是痛苦視界中的一片美景，朋友。', `FemaleText_loc7`='Había perdido la noción del tiempo en este maldito lugar. Da gusto verte, $gamigo:amiga;.' WHERE `ID`=37268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 마치 천사 같아 보이는군요... 제 기분 모르실 겁니다.', `MaleText_loc4`='你的出现是美妙的一幕…对此你可能还并不能理解。', `MaleText_loc5`='你是一片絕美的景致...你無法想像。', `MaleText_loc7`='¡Qué gusto da verte! No tienes ni idea.', `FemaleText_loc1`='당신이 마치 천사 같아 보이는군요... 제 기분 모르실 거예요.', `FemaleText_loc4`='你的出现是美妙的一幕…对此你可能还并不能理解。', `FemaleText_loc5`='你是一片絕美的景致...你無法想像。', `FemaleText_loc7`='¡Qué gusto da verte! No tienes ni idea.' WHERE `ID`=37269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 이가 여기서 목숨을 잃었습니다. 너무 많은 이가요.', `MaleText_loc4`='我们在这个大坑里损失太多人了。太多太多了。', `MaleText_loc5`='太多同伴死在這深淵之中。太多了。', `MaleText_loc7`='Demasiados morimos en este foso. Demasiados.', `FemaleText_loc1`='수많은 이가 여기서 목숨을 잃었어요. 너무 많은 이가요.', `FemaleText_loc4`='我们在这个大坑里损失太多人了。太多太多了。', `FemaleText_loc5`='太多同伴死在這深淵之中。太多了。', `FemaleText_loc7`='Demasiados morimos en este foso. Demasiados.' WHERE `ID`=37270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 보니 정말 기쁩니다. 제가 얼마나 더 버틸 수 있을지 의심스러웠어요.', `MaleText_loc4`='很高兴你来了。我本来撑不了那么久的。', `MaleText_loc5`='我真高興你在這裡。不然我也撐不下去了。', `MaleText_loc7`='Me alegro tanto de que estés aquí. No habría aguantado mucho más.', `FemaleText_loc1`='당신을 보니 정말 기쁩니다. 제가 얼마나 더 버틸 수 있을지 의심스러웠어요.', `FemaleText_loc4`='很高兴你来了。我本来撑不了那么久的。', `FemaleText_loc5`='我真高興你在這裡。不然我也撐不下去了。', `FemaleText_loc7`='Me alegro tanto de que estés aquí. No habría aguantado mucho más.' WHERE `ID`=37271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨 좀 돌리고 바로 합류하겠습니다, 영웅들이여. 감사합니다.', `MaleText_loc4`='让我先喘口气，一会儿我会赶上你们的，英雄们。谢谢你们。', `MaleText_loc5`='只要我喘過氣來，我會立刻加入你，英雄們。感謝你。', `MaleText_loc7`='Me reuniré con ustedes en cuanto recobre el aliento, héroes. Gracias.', `FemaleText_loc1`='숨 좀 돌리고 바로 합류하겠습니다, 영웅들이여. 감사합니다.', `FemaleText_loc4`='让我先喘口气，一会儿我会赶上你们的，英雄们。谢谢你们。', `FemaleText_loc5`='只要我喘過氣來，我會立刻加入你，英雄們。感謝你。', `FemaleText_loc7`='Me reuniré con ustedes en cuanto recobre el aliento, héroes. Gracias.' WHERE `ID`=37272;
