UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 한번 꼭 안아 드려도 되겠습니까?', `MaleText_loc4`='来个男人强有力的拥抱吧。', `MaleText_loc5`='你值得一個大力的擁抱。', `MaleText_loc7`='Te mereces un buen abrazo de hombres.', `FemaleText_loc1`='당신에게 입맞추고 싶은 심정이에요!', `FemaleText_loc4`='我真想吻你！', `FemaleText_loc5`='你值得一個大力的擁抱。', `FemaleText_loc7`='¡Podría besarte!' WHERE `ID`=37274;
