UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빈손으로 당신에게 건배합니다.', `MaleText_loc4`='%s举起空着的手向你做了个敬酒的姿势。', `MaleText_loc5`='%s舉起空蕩蕩的手，對你舉杯祝賀。', `MaleText_loc7`='%s levanta su mano vacía y brinda por ti.', `FemaleText_loc1`='%s|1이;가; 당신에게 키스를 날려보냅니다.', `FemaleText_loc4`='%s给了你一个飞吻。', `FemaleText_loc5`='%s舉起空蕩蕩的手，對你舉杯祝賀。', `FemaleText_loc7`='%s te tira un beso.' WHERE `ID`=37282;
