UPDATE `locales_broadcast_text` SET `MaleText_loc1`='극도로 지친 %s|1이;가; 곡괭이를 질질 끌며 다가옵니다.', `MaleText_loc4`='%s每挥出一锄时都完全任由矿工锄拖在地上，明显体力不支。', `MaleText_loc5`='當她靠近的時候，%s任由他的礦工鎬掉在地上，顯然已經精疲力盡。', `MaleText_loc7`='%s deja que su pico de minería se arrastre por el suelo mientras se acerca, exhausto.', `FemaleText_loc1`='극도로 지친 %s|1이;가; 곡괭이를 질질 끌며 다가옵니다.', `FemaleText_loc4`='%s每挥出一锄时都完全任由矿工锄拖在地上，明显体力不支。', `FemaleText_loc5`='當她靠近的時候，%s任由他的礦工鎬掉在地上，顯然已經精疲力盡。', `FemaleText_loc7`='%s deja que su pico de minería se arrastre por el suelo mientras se acerca, exhausta.' WHERE `ID`=37284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께하겠습니다, 영웅이여.', `MaleText_loc4`='英雄，我与你同在。', `MaleText_loc5`='我支持你，英雄。', `MaleText_loc7`='Estoy contigo, $ghéroe:heroína;.', `FemaleText_loc1`='당신과 함께하겠어요, 영웅이여.', `FemaleText_loc4`='英雄，我与你同在。', `FemaleText_loc5`='我支持你，英雄。', `FemaleText_loc7`='Estoy contigo, $ghéroe:heroína;.' WHERE `ID`=37285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께 목숨을 빚졌군요.', `MaleText_loc4`='我欠你一条命。', `MaleText_loc5`='我欠你一條命。', `MaleText_loc7`='Te debo la vida.', `FemaleText_loc1`='당신께 목숨을 빚졌군요.', `FemaleText_loc4`='我欠你一条命。', `FemaleText_loc5`='我欠你一條命。', `FemaleText_loc7`='Te debo la vida.' WHERE `ID`=37286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아서든 죽어서든 이 은혜는 꼭 갚겠습니다. 반드시 말입니다.', `MaleText_loc4`='为了报答你，我愿付出任何代价。', `MaleText_loc5`='如果我的性命能報答你，我會很樂意。', `MaleText_loc7`='Si con mi vida o muerte puedo devolverte el favor, lo haré.', `FemaleText_loc1`='살아서든 죽어서든 이 은혜는 꼭 갚겠습니다. 반드시 말입니다.', `FemaleText_loc4`='为了报答你，我愿付出任何代价。', `FemaleText_loc5`='如果我的性命能報答你，我會很樂意。', `FemaleText_loc7`='Si con mi vida o muerte puedo devolverte el favor, lo haré.' WHERE `ID`=37287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 옆에서 싸우겠습니다. 놈들에게 자비를 베풀지 마세요.', `MaleText_loc4`='我会同你并肩作战。对他们绝不留情。', `MaleText_loc5`='我會跟你並肩作戰。絕對不會對他們手下留情。', `MaleText_loc7`='Lucharé a tu lado. No tengas piedad.', `FemaleText_loc1`='당신 옆에서 싸우겠습니다. 놈들에게 자비를 베풀지 마세요.', `FemaleText_loc4`='我会同你并肩作战。对他们绝不留情。', `FemaleText_loc5`='我會跟你並肩作戰。絕對不會對他們手下留情。', `FemaleText_loc7`='Lucharé a tu lado. No tengas piedad.' WHERE `ID`=37288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 다른 이들을 풀어주는 걸 거들러 가겠습니다. 다시 한 번 감사합니다, 영웅이여.', `MaleText_loc4`='我要回去帮助解救其它奴隶。再次感谢你，英雄。', `MaleText_loc5`='我回去幫忙釋放剩下的奴隸。再次感謝你，英雄。', `MaleText_loc7`='Voy a volver para ayudar a liberar a los demás esclavos. Gracias de nuevo, $ghéroe:heroína;.', `FemaleText_loc1`='전 다른 이들을 풀어주는 걸 거들러 가겠어요. 다시 한 번 감사합니다, 영웅이여.', `FemaleText_loc4`='我要回去帮助解救其它奴隶。再次感谢你，英雄。', `FemaleText_loc5`='我回去幫忙釋放剩下的奴隸。再次感謝你，英雄。', `FemaleText_loc7`='Voy a volver para ayudar a liberar a los demás esclavos. Gracias de nuevo, $ghéroe:heroína;.' WHERE `ID`=37293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채석장 입구로 돌아가겠습니다. 절 위해 몇 놈 더 혼내 주세요.', `MaleText_loc4`='我要回到采石场前线去。帮我多杀几个。', `MaleText_loc5`='我回到礦場前方去。替我多殺幾個。', `MaleText_loc7`='Voy a volver al frente de la cantera. Mata a unos cuantos por mí.', `FemaleText_loc1`='채석장 입구로 돌아가겠습니다. 절 위해 몇 놈 더 혼내 주세요.', `FemaleText_loc4`='我要回到采石场前线去。帮我多杀几个。', `FemaleText_loc5`='我回到礦場前方去。替我多殺幾個。', `FemaleText_loc7`='Voy a volver al frente de la cantera. Mata a unos cuantos por mí.' WHERE `ID`=37294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불모의 땅은 비록 메말랐지만 생명의 기운으로 충만하던 때가 분명히 있었어요. 우리는 이곳을 누비며 사냥하고, 이 땅에 의지해서 살아갔어요.$B$B얼라이언스가 와서 부수고, 불태우고, 살육하기 전까지는... 지금 이곳은 피의 들판이라 불리고 있지요, $c님.$B$B모두 피난을 떠났어요. 남은 이들만이 이곳에서 싸움을 계속하고 있어요.', `FemaleText_loc4`='贫瘠之地现在也许是干枯荒凉的，但这片土地曾经生机勃勃。我们在这里漫游、狩猎，过着丰足的生活。$B$B然后，联盟来了……他们烧杀抢掠。被他们蹂躏过的地方，现在被我们称为鲜血旷野，$c。$B$B那里的居民已经全部流亡到其它地方。留下来的只有继续与敌人苦战的士兵。', `FemaleText_loc5`='貧瘠之地或許乾涸，但是這些平原曾充滿了生機。這是我們賴以為生的大地，我們在此地上漫遊、打獵。$B$B後來聯盟來了之後...便不停地砍、殺、燒。我們現在將此稱為鮮血草原，$c。$B$B難民們都跑走了，那些留下的人則是為了起身對抗之。', `FemaleText_loc7`='Quizá Los Baldíos estén secos, pero en otros tiempos, estas llanuras rebosaban vida. Íbamos de acá para allá, cazábamos y vivíamos de la tierra.$B$BEntonces llegó la Alianza... destrozando, quemando, asesinando. Ahora llamamos a estas tierras Campos de Sangre, $c.$B$BLos refugiados han huido. Aquellos que se han quedado atrás, lo han hecho para luchar.' WHERE `ID`=37295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부족하게나마 관문을 방어할 준비가 됐습니다, $n 님. 당신은 준비되셨나요?', `FemaleText_loc4`='大门的守卫者们已经做好了准备，$n。你呢？', `FemaleText_loc5`='簡陋的城門防禦工事已經準備完成，$n。你呢?', `FemaleText_loc7`='Las escasas defensas de la puerta está listas, $n. ¿Y tú?' WHERE `ID`=37296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, $n 님! 바인 님과 우리 호드 동맹들이 힘을 합하면 침입자들을 놈들의 고향인 습지대로 되돌려보낼 수 있을 겁니다.', `FemaleText_loc4`='谢谢你，$n！只要贝恩和我们的部落盟友同心协力，我们就能将入侵者赶回到他们盘踞的沼泽里面去。', `FemaleText_loc5`='謝謝你，$n!在貝恩和部落盟友的共同努力下，我們應該能把這些入侵者趕回牠們當初來的沼澤。', `FemaleText_loc7`='¡Gracias, $n! Con Baine y tus aliados de la Horda, quizá todavía podamos enviar a los invasores de vuelta al pantano del que han salido.' WHERE `ID`=37297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임시입니다! 쾅!', `MaleText_loc4`='占位符！锵锵!', `MaleText_loc5`='Placeholder! WHAMS!', `MaleText_loc7`='Placeholder! WHAMS!' WHERE `ID`=37298;
