UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울이여, 저 가증스러운 하이 엘프를 없애라!', `MaleText_loc4`='食尸鬼们，杀掉这个可怜的高等精灵！', `MaleText_loc5`='食屍鬼，殺死這個可悲的高等精靈!', `MaleText_loc7`='Necrófagos, ¡acabad con este patético elfo noble!' WHERE `ID`=37301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 스컬지의 강력한 군대 앞에 무릎 꿇으리라. 지하마귀 침입자들이여, 공격하라!', `MaleText_loc4`='你们都会被天灾军团的力量击垮。地穴劫掠者，进攻！', `MaleText_loc5`='你會在天譴軍團的力量前敗倒。地穴劫掠者，攻擊!', `MaleText_loc7`='Caerás ante el poder de la Plaga. ¡Asaltantes de tumbas, ataquen!' WHERE `ID`=37302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비상 탈출용 차원문입니다.', `MaleText_loc4`='这是一道紧急撤离传送门。', `MaleText_loc5`='這是個緊急疏散傳送門。', `MaleText_loc7`='Esto es un portal de evacuación de emergencia.' WHERE `ID`=37303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 밖으로 이동합니다.', `MaleText_loc4`='带我离开这座城市。', `MaleText_loc5`='把我弄出城。', `MaleText_loc7`='Sácame de la ciudad.', `FemaleText_loc1`='도시 밖으로 이동합니다.', `FemaleText_loc4`='带我离开这座城市。', `FemaleText_loc5`='把我弄出城。', `FemaleText_loc7`='Sácame de la ciudad.' WHERE `ID`=37304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 여기예요. 당신 도움이 필요해요.', `FemaleText_loc4`='$n，请过来一下。我需要你的帮助。', `FemaleText_loc5`='$n - 請來找我。我需要你的幫忙。', `FemaleText_loc7`='$n, por favor, mírame. Necesito tu ayuda.' WHERE `ID`=37305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오! 날씨가 궂어집니다. 곧 정령이 몰려올 것입니다! 피할 곳을 찾으십시오!', `MaleText_loc4`='保持戒备！天气越来越糟，元素生物就快追来了！找掩护！', `MaleText_loc5`='提高警覺!天候轉壞，元素很快就會到來!尋找掩蔽!', `MaleText_loc7`='¡En guardia! El tiempo empeora y pronto vendrán los elementales. ¡Busca refugio!', `FemaleText_loc1`='조심하세요! 날씨가 궂어집니다. 곧 정령이 몰려올 것입니다! 피할 곳을 찾으세요!', `FemaleText_loc4`='保持戒备！天气越来越糟，元素生物就快追来了！找掩护！', `FemaleText_loc5`='提高警覺!天候轉壞，元素很快就會到來!尋找掩蔽!', `FemaleText_loc7`='¡En guardia! El tiempo empeora y pronto vendrán los elementales. ¡Busca refugio!' WHERE `ID`=37306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건물 안으로 들어가십시오! 하늘이 어두워졌으니 곧 정령이 공격해올 겁니다. 경계하십시오!', `MaleText_loc4`='清理街道！天色开始阴沉，元素生物很快就要发动袭击了。保持警惕！', `MaleText_loc5`='清空街道!天色轉暗，元素很快就會展開攻擊。做好準備!', `MaleText_loc7`='¡Abandonad las calles! Los cielos se oscurecen y pronto atacarán los elementales. ¡En guardia!', `FemaleText_loc1`='건물 안으로 들어가세요! 하늘이 어두워졌으니 곧 정령이 공격해올 겁니다. 경계하세요!', `FemaleText_loc4`='清理街道！天色开始阴沉，元素生物很快就要发动袭击了。保持警惕！', `FemaleText_loc5`='清空街道!天色轉暗，元素很快就會展開攻擊。做好準備!', `FemaleText_loc7`='¡Abandonad las calles! Los cielos se oscurecen y pronto atacarán los elementales. ¡En guardia!' WHERE `ID`=37307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질병이 치료되어 정상적인 상태로 돌아왔습니다!', `MaleText_loc4`='疾病已经被治愈，你感到再次恢复正常！', `MaleText_loc5`='疾病已經痊癒，你感覺恢復正常!', `MaleText_loc7`='¡La enfermedad se ha curado y te vuelves a sentir normal!' WHERE `ID`=37308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러! 병사들이 벌써 이곳으로 오고 있어.', `MaleText_loc4`='快点。士兵们已经出发了。', `MaleText_loc5`='快點，那些士兵已經離開這裡了。', `MaleText_loc7`='Deprisa. Los soldados ya se han retirado de aquí.', `FemaleText_loc1`='서둘러! 병사들이 벌써 이곳으로 오고 있어.', `FemaleText_loc4`='快点。士兵们已经出发了。', `FemaleText_loc5`='快點，那些士兵已經離開這裡了。', `FemaleText_loc7`='Deprisa. Los soldados ya se han retirado de aquí.' WHERE `ID`=37309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸만한 건 모두 집으라고.', `MaleText_loc4`='寻找一切可以做掩护的东西。', `MaleText_loc5`='拿著任何你覺得可以用來防衛的東西。', `MaleText_loc7`='Agarra cualquier cosa que creas que podemos esgrimir.', `FemaleText_loc1`='쓸만한 건 모두 집으라고.', `FemaleText_loc4`='寻找一切可以做掩护的东西。', `FemaleText_loc5`='拿著任何你覺得可以用來防衛的東西。', `FemaleText_loc7`='Agarra cualquier cosa que creas que podemos esgrimir.' WHERE `ID`=37310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관은 아직 안 쓸었나? 끝낸 곳은 모두 불태워 버려!', `MaleText_loc4`='我们还没有将这家旅店里的敌人清除干净？完成这个任务之后就把它一把火烧掉！', `MaleText_loc5`='旅店已經清空了嗎?好了後把其他的都燒了!', `MaleText_loc7`='¿Ya hemos saqueado la posada? ¡Quemen lo que quede cuando hayan terminado!', `FemaleText_loc1`='여관은 아직 안 쓸었나? 끝낸 곳은 모두 불태워 버려!', `FemaleText_loc4`='我们还没有将这家旅店里的敌人清除干净？完成这个任务之后就把它一把火烧掉！', `FemaleText_loc5`='旅店已經清空了嗎?好了後把其他的都燒了!', `FemaleText_loc7`='¿Ya hemos saqueado la posada? ¡Quemen lo que quede cuando hayan terminado!' WHERE `ID`=37311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구슬과 가죽 쪼가리밖에 없군. 보물은 다 어디 있는 거야?', `MaleText_loc4`='这帮家伙身上只有些破珠子和硬皮。财宝到底在哪里？', `MaleText_loc5`='這些大都是串珠和獸皮。寶藏都跑去哪了?', `MaleText_loc7`='Esto no son más abalorios y pieles. ¿Dónde está el tesoro?', `FemaleText_loc1`='구슬과 가죽 쪼가리밖에 없군. 보물은 다 어디 있는 거야?', `FemaleText_loc4`='这帮家伙身上只有些破珠子和硬皮。财宝到底在哪里？', `FemaleText_loc5`='這些大都是串珠和獸皮。寶藏都跑去哪了?', `FemaleText_loc7`='Esto no son más abalorios y pieles. ¿Dónde está el tesoro?' WHERE `ID`=37312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸물대지 마. 반격 당하기 전에 재빨리 털고 나가야 돼.', `MaleText_loc4`='我们在浪费时间。这个地方必须在他们发动反攻之前清理干净。', `MaleText_loc5`='不要浪費時間。我要這個地方在他們發動反擊前被搜括得一乾二淨。', `MaleText_loc7`='Se acaba el tiempo. Quiero que limpiéis este sitio antes de que contraataquen.', `FemaleText_loc1`='꾸물대지 마. 반격 당하기 전에 재빨리 털고 나가야 돼.', `FemaleText_loc4`='我们在浪费时间。这个地方必须在他们发动反攻之前清理干净。', `FemaleText_loc5`='不要浪費時間。我要這個地方在他們發動反擊前被搜括得一乾二淨。', `FemaleText_loc7`='Se acaba el tiempo. Quiero que limpiéis este sitio antes de que contraataquen.' WHERE `ID`=37313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우체통은 뒤졌나?', `MaleText_loc4`='嗨，有人搜过信箱了没？', `MaleText_loc5`='喂!有人去檢查郵箱了嗎?', `MaleText_loc7`='Eh, ¿alguien ha saqueado ya el buzón?', `FemaleText_loc1`='우체통은 뒤졌나?', `FemaleText_loc4`='嗨，有人搜过信箱了没？', `FemaleText_loc5`='喂!有人去檢查郵箱了嗎?', `FemaleText_loc7`='Eh, ¿alguien ha saqueado ya el buzón?' WHERE `ID`=37314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 더 있을 거야. 시체를 다시 확인해 봐!', `MaleText_loc4`='还应该有更多的东西。再把他们搜查一遍！', `MaleText_loc5`='一定不止這些。再去檢查一下屍體!', `MaleText_loc7`='Tiene que haber más. ¡Volved a comprobar los cadáveres!', `FemaleText_loc1`='뭔가 더 있을 거야. 시체를 다시 확인해 봐!', `FemaleText_loc4`='还应该有更多的东西。再把他们搜查一遍！', `FemaleText_loc5`='一定不止這些。再去檢查一下屍體!', `FemaleText_loc7`='Tiene que haber más. ¡Volved a comprobar los cadáveres!' WHERE `ID`=37315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근사한 연회 복장을 꺼내 근사한 색안경, 끝내주는 새 옷, 빛나는 반짝이를 입어야 합니다.', `MaleText_loc4`='打开你们超酷派对套装，穿戴上你们的清爽遮阳镜、潮人装束和亮闪闪的珠宝!', `MaleText_loc5`='把你的超炫的舞會套裝解開來後戴上你的拉風墨鏡，時髦新裝和亮晶晶的玩意兒!', `MaleText_loc7`='¡Desenvuelve tu modelito de fiesta impresionante, ponte tus gafas de sol chulas, tu atuendo pistonudo y tu cadena de oro lustrosa!', `FemaleText_loc1`='근사한 연회 복장을 꺼내 근사한 색안경, 끝내주는 새 옷, 빛나는 반짝이를 입어야 합니다.', `FemaleText_loc4`='打开你们超酷派对套装，穿戴上你们的清爽遮阳镜、潮人装束和亮闪闪的珠宝!', `FemaleText_loc5`='把你的超炫的舞會套裝解開來後戴上你的拉風墨鏡，時髦新裝和亮晶晶的玩意兒!', `FemaleText_loc7`='¡Desenvuelve tu modelito de fiesta impresionante, ponte tus gafas de sol chulas, tu atuendo pistonudo y tu cadena de oro lustrosa!' WHERE `ID`=37316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 갇혀 있던 가시멧돼지 본 사람 없어?', `MaleText_loc4`='有人见到那些被关在笼子里的野猪人吗？', `MaleText_loc5`='有人看到這裡關了一隻野豬人嗎?', `MaleText_loc7`='¿Alguien ha visto el jabaespín que tenían enjaulado allí?', `FemaleText_loc1`='여기 갇혀 있던 가시멧돼지 본 사람 없어?', `FemaleText_loc4`='有人见到那些被关在笼子里的野猪人吗？', `FemaleText_loc5`='有人看到這裡關了一隻野豬人嗎?', `FemaleText_loc7`='¿Alguien ha visto el jabaespín que tenían enjaulado allí?' WHERE `ID`=37317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가서 혼쭐을 내 주세요!', `FemaleText_loc4`='去试试吧，老板！', `FemaleText_loc5`='去幹掉他們，老大!', `FemaleText_loc7`='¡Ve por ellos, $gjefe:jefa;!' WHERE `ID`=37318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격이 시작됐을 때 곧바로 다른 이들을 깨우러 달려갔네. 도망칠 수 있었냐고? 무두질용 손칼로 병사들과 싸우려 해봤지만...', `MaleText_loc4`='当战斗开始时，我跑去叫醒了其他人。他们逃出来了么？我只能用一把剥皮小刀和那些凶恶的士兵对抗……', `MaleText_loc5`='被攻擊時我試著要叫醒其他人。他們逃脫了嗎?我用剝皮小刀試著將那些士兵擊退...', `MaleText_loc7`='Corrí a despertar a los demás cuando atacaron. ¿Pudieron escapar? Intenté luchar contra los soldados con un cuchillo desollador...' WHERE `ID`=37319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 영웅들이여, 우리는 그대들에게 목숨을, 자유를 빚졌습니다... 이런 큰 빚을 갚기엔 너무나도 모자라겠지만, 그대들의 훌륭한 행동과 이 어두운 성채의 그림자를 가른 행보를 오늘부터 모든 이들에게 알리겠다고 맹세합니다.', `MaleText_loc4`='勇士们，你们救了我们，还我们自由……这种大恩大德我们无以为报。但我发誓，从今往后所有人都会知道你们的事迹，知道你们如何在这座黑暗的城堡中劈开一条光明之路。', `MaleText_loc5`='英勇的戰士們，我欠你們的不只是自己的生命，還有我們的自由...儘管，這點回報相較於你的恩情，只是輕如鴻毛，但我發誓從今天以後，所有人都將明白你們的義舉，以及你們斬斷這座黑暗城塞中的陰影所帶來的光明之道。', `MaleText_loc7`='Valientes campeones, les debemos la vida, nuestra libertad... Aunque sea un pequeño gesto frente a nuestra gran deuda, prometo que, de hoy en adelante, todos sabrán de sus hazañas y el camino ardiente de Luz que marcaron en esta oscura ciudadela.' WHERE `ID`=37320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 날은 그대들의 용맹함을 입증하고, 리치 왕조차도 적수가 안됨을 증거하는 날이 될 것입니다. 만약 얼라이언스와 호드가 차이를 극복하고...', `MaleText_loc4`='今天我们不仅见证了你们的勇猛，还见证了联盟和部落抛开仇怨，精诚团结的力量。有了这种力量，即使是巫妖王也会败倒在你们脚下。', `MaleText_loc5`='今天不單是你們英勇的明證，更說明了沒有敵人，就算是巫妖王本人也無法對抗捐棄成見、攜手合作的聯盟與部落，以及--', `MaleText_loc7`='Hoy han demostrado no solo su valor, sino también que ningún enemigo, ni siquiera el Rey Exánime, puede resistirse cuando la Horda y la Alianza dejan de lado sus diferencias y...' WHERE `ID`=37321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 살아 있는 모든 존재에 대지모신의 영원한 평화가 함께함을 느낍니다. 고맙습니다.', `MaleText_loc4`='现在，我能感觉到全部生命的拥抱，大地母亲永恒的平静。谢谢你。', `MaleText_loc5`='我現在可以感覺到所有活著的生命所帶來的擁抱，大地之母永恆的和平。謝謝你。', `MaleText_loc7`='Ahora siento el abrazo de todas las cosas vivas, la paz eterna de la Madre Tierra. Gracias.' WHERE `ID`=37322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스가 우리 야영지를 포위했습니다! 이곳에서 뭘 하는 거죠? 타우라조를 공격한 이유가 뭔가요? 아이들을 구해야 합니다. 뛰어요! 어서!', `FemaleText_loc4`='联盟已经包围了这座营地！他们到这里来干什么？为什么他们要攻击陶拉祖？赶快带孩子们逃走，快！快！', `FemaleText_loc5`='聯盟!他們已經將營地包圍了!他們為什麼在這?他們為什麼要攻擊陶拉祖營地?保護孩子們，跑!快跑!', `FemaleText_loc7`='La Alianza... ¡Han rodeado el campamento! ¿Qué hacen aquí? ¿Por qué atacan Taurajo? ¡Ve por los niños! ¡Corran! ¡CORRAN!' WHERE `ID`=37323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 다른 분들과 함께 계십시오. 그들을 북쪽으로, 싸움으로부터 멀리 데려가십시오. 전 와이번과 함께 이곳에 남아 여러분을 엄호하겠습니다. 출발하십시오!', `MaleText_loc4`='不，和其他人待在一起。护送他们向北离开战场。我会和双足飞龙留在这里掩护你们。快走！', `MaleText_loc5`='不，跟其他人待在一起。護送他們到北方，迴避戰鬥。我會和雙足翼龍待在這掩護你們逃跑。快走!', `MaleText_loc7`='No, quédate con los demás. Escóltalos hacia el norte, lejos de la batalla. Yo me quedaré aquí con los dracohalcones y cubriré su retirada. ¡Corran!' WHERE `ID`=37324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...잠깐, 다 끝난 건가요? 칼에 찔리고 나서... 아. 그렇군요. 이제 알겠습니다. 제가 있을 곳은 여기가 아니군요.', `MaleText_loc4`='……等等，结束了？', `MaleText_loc5`='...等下，已經結束了?我得知的是...噢。原本是這樣，我現在瞭解了。我應該去別的地方。', `MaleText_loc7`='...espera, ¿ya ha terminado? He sido atravesado... Ah, claro. Ahora lo entiendo. Me esperan en otro sitio.' WHERE `ID`=37325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이거야! 쥐어짜는 바위!', `MaleText_loc4`='我有个好点子：可挤压的石头！', `MaleText_loc5`='我想到了:可以擠的石頭!', `MaleText_loc7`='¡Lo tengo! ¡Rocas que se pueden estrujar!', `FemaleText_loc1`='바로 이거야! 쥐어짜는 바위!', `FemaleText_loc4`='我有个好点子：可挤压的石头！', `FemaleText_loc5`='我想到了:可以擠的石頭!', `FemaleText_loc7`='¡Lo tengo! ¡Rocas que se pueden estrujar!' WHERE `ID`=37326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개줄이 좋겠어... 미리 애완동물을 붙여놓고 말이지!', `MaleText_loc4`='绳索……还有已经套在上面的宠物。', `MaleText_loc5`='已經套好寵物的...皮帶。', `MaleText_loc7`='Correas... que vengan ya con la mascota.', `FemaleText_loc1`='개줄이 좋겠어... 미리 애완동물을 붙여놓고 말이지!', `FemaleText_loc4`='绳索……还有已经套在上面的宠物。', `FemaleText_loc5`='已經套好寵物的...皮帶。', `FemaleText_loc7`='Correas... que vengan ya con la mascota.' WHERE `ID`=37327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리 구멍이 난 셔츠라... 셔츠 겸용 반바지!', `MaleText_loc4`='有腿洞的衬衫。翻领衬衫短裤！', `MaleText_loc5`='襯衫有給腿穿過去的洞。可雙用的短褲襯衫!', `MaleText_loc7`='Camisas con agujeros para las piernas. ¡Camibermudas reversibles!', `FemaleText_loc1`='다리 구멍이 난 셔츠라... 셔츠 겸용 반바지!', `FemaleText_loc4`='有腿洞的衬衫。翻领衬衫短裤！', `FemaleText_loc5`='襯衫有給腿穿過去的洞。可雙用的短褲襯衫!', `FemaleText_loc7`='Camisas con agujeros para las piernas. ¡Camibermudas reversibles!' WHERE `ID`=37328;
