UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모터 달린 육수 그릇이 좋겠군. 레이저 각설탕 분무기하고 어울리지.', `MaleText_loc4`='自动酱油壶，配有激光除垢器。', `MaleText_loc5`='可動的船形器皿，配有雷射方糖融化器。', `MaleText_loc7`='Una salsera motorizada. Con vaporizador de terrones láser.', `FemaleText_loc1`='모터 달린 육수 그릇이 좋겠군. 레이저 각설탕 분무기하고 어울리지.', `FemaleText_loc4`='自动酱油壶，配有激光除垢器。', `FemaleText_loc5`='可動的船形器皿，配有雷射方糖融化器。', `FemaleText_loc7`='Una salsera motorizada. Con vaporizador de terrones láser.' WHERE `ID`=37331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리에 신는 신발!', `MaleText_loc4`='穿在脑袋上的鞋子！', `MaleText_loc5`='頭鞋!', `MaleText_loc7`='¡Zapatos para la cabeza!', `FemaleText_loc1`='머리에 신는 신발!', `FemaleText_loc4`='穿在脑袋上的鞋子！', `FemaleText_loc5`='頭鞋!', `FemaleText_loc7`='¡Zapatos para la cabeza!' WHERE `ID`=37332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 어때? 즉석 물! 여기에 추가 재료는... 어!?', `MaleText_loc4`='这个怎么样：速食开水！你只需要往里边加……哦。', `MaleText_loc5`='這個如何:瞬間產水器!只要加...噢。', `MaleText_loc7`='Y qué tal esto: ¡agua instantánea! Tan solo añadimos... oh.', `FemaleText_loc1`='이건 어때? 즉석 물! 여기에 추가 재료는... 어!?', `FemaleText_loc4`='这个怎么样：速食开水！你只需要往里边加……哦。', `FemaleText_loc5`='這個如何:瞬間產水器!只要加...噢。', `FemaleText_loc7`='Y qué tal esto: ¡agua instantánea! Tan solo añadimos... oh.' WHERE `ID`=37333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 영화 아이디어로군! 세 노움이 마력의 팔찌를 찾아서...', `MaleText_loc4`='我有了个能拍成电影的创意。三个侏儒找到了一个魔力手镯……', `MaleText_loc5`='我想到了一個很好的電影主題。三隻地精有一天找到了一個帶有強大力量的手鐲...', `MaleText_loc7`='Tengo una idea para una película. Tres gnomos encuentran un brazalete de poder...', `FemaleText_loc1`='이번엔 영화 아이디어로군! 세 노움이 마력의 팔찌를 찾아서...', `FemaleText_loc4`='我有了个能拍成电影的创意。三个侏儒找到了一个魔力手镯……', `FemaleText_loc5`='我想到了一個很好的電影主題。三隻地精有一天找到了一個帶有強大力量的手鐲...', `FemaleText_loc7`='Tengo una idea para una película. Tres gnomos encuentran un brazalete de poder...' WHERE `ID`=37334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번지 점프랑 비슷해요. 아시죠? 그런데 줄이 안 달린 거죠. 밑에서 올라가고요. 음... 생각해 보니 그냥 뛰어오르는 거랑 비슷하네요... 총 든 거만 빼고.', `MaleText_loc4`='就像蹦极跳一样，懂吗？只是没有拴上绳子，明白吗？而且你是从地面开始的。我觉得它更像是普通的跳跃，不过你是被大炮轰上去的。', `MaleText_loc5`='就像是高空彈跳，對吧?差別是沒有繩子，看到了嗎?還有就是你是從下往上跳的。其實大概就跟一般的跳躍差不多，不同的地方是有槍。', `MaleText_loc7`='Es como el salto en bungee, ¿me oyes? Pero sin cuerda. Y empiezas abajo. Supongo que es como saltar normal. Pero con armas.', `FemaleText_loc1`='번지 점프랑 비슷해요. 아시죠? 그런데 줄이 안 달린 거죠. 밑에서 올라가고요. 음... 생각해 보니 그냥 뛰어오르는 거랑 비슷하네요... 총 든 거만 빼고.', `FemaleText_loc4`='就像蹦极跳一样，懂吗？只是没有拴上绳子，明白吗？而且你是从地面开始的。我觉得它更像是普通的跳跃，不过你是被大炮轰上去的。', `FemaleText_loc5`='就像是高空彈跳，對吧?差別是沒有繩子，看到了嗎?還有就是你是從下往上跳的。其實大概就跟一般的跳躍差不多，不同的地方是有槍。', `FemaleText_loc7`='Es como el salto en bungee, ¿me oyes? Pero sin cuerda. Y empiezas abajo. Supongo que es como saltar normal. Pero con armas.' WHERE `ID`=37335;
