UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자동차 두 대를 더 큰 자동차에 결합해서, 승객들이 건너다닐 수 있게 하는 거야!', `MaleText_loc4`='将两辆车组合成一辆更大的车，然后让乘客从一辆车跳到另一辆车上！', `MaleText_loc5`='把兩台載具連接於一台更大的載具，然後讓乘客從一台跳到另一台上面!', `MaleText_loc7`='¡Unir dos vehículos a otro más grande y hacer que los pasajeros salten de un vehículo a otro!', `FemaleText_loc1`='자동차 두 대를 더 큰 자동차에 결합해서, 승객들이 건너다닐 수 있게 하는 거야!', `FemaleText_loc4`='将两辆车组合成一辆更大的车，然后让乘客从一辆车跳到另一辆车上！', `FemaleText_loc5`='把兩台載具連接於一台更大的載具，然後讓乘客從一台跳到另一台上面!', `FemaleText_loc7`='¡Unir dos vehículos a otro más grande y hacer que los pasajeros salten de un vehículo a otro!' WHERE `ID`=37341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전선을 사용하여 장거리 메시지를 전달하는 거야... 아냐, 실용적이지 않아. 거대한 로켓이 좋겠어. 스피커를 달아서...', `MaleText_loc4`='利用电线把信息传送到远方……不，这个发明不现实。还是造巨型火箭，把说话的人绑在上边……', `MaleText_loc5`='電纜可以將訊息傳送到很遠的地方...不行!這不夠有效率。用巨大的火箭裝上了擴音器才...', `MaleText_loc7`='Cables eléctricos que se utilizan para enviar mensajes a grandes distancias... No, muy poco práctico. Cohetes gigantes equipados con altavoces...', `FemaleText_loc1`='전선을 사용하여 장거리 메시지를 전달하는 거야... 아냐, 실용적이지 않아. 거대한 로켓이 좋겠어. 스피커를 달아서...', `FemaleText_loc4`='利用电线把信息传送到远方……不，这个发明不现实。还是造巨型火箭，把说话的人绑在上边……', `FemaleText_loc5`='電纜可以將訊息傳送到很遠的地方...不行!這不夠有效率。用巨大的火箭裝上了擴音器才...', `FemaleText_loc7`='Cables eléctricos que se utilizan para enviar mensajes a grandes distancias... No, muy poco práctico. Cohetes gigantes equipados con altavoces...' WHERE `ID`=37342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지들이 퉁퉁 튕길 때까지 고무를 먹이는 거야. 뭔가 방법이 없을까?', `MaleText_loc4`='喂猪吃橡胶，直到它们能弹起来。这肯定有应用价值。', `MaleText_loc5`='餵豬吃橡膠，直到它彈起來。這一定在哪裡可以派上用場。', `MaleText_loc7`='Dar de comer goma a los cerdos hasta que sean capaces de rebotar. Seguro que le encontramos una aplicación práctica.', `FemaleText_loc1`='돼지들이 퉁퉁 튕길 때까지 고무를 먹이는 거야. 뭔가 방법이 없을까?', `FemaleText_loc4`='喂猪吃橡胶，直到它们能弹起来。这肯定有应用价值。', `FemaleText_loc5`='餵豬吃橡膠，直到它彈起來。這一定在哪裡可以派上用場。', `FemaleText_loc7`='Dar de comer goma a los cerdos hasta que sean capaces de rebotar. Seguro que le encontramos una aplicación práctica.' WHERE `ID`=37343;
