UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송곳 달린 스프링 청소기 어때? 과일 주스를 만들 때도 쓸 수 있잖아?', `MaleText_loc4`='一只用弹簧带动的活塞，上面绑着刀刃，用来处理食物。或者是一些和你意见不一的人。', `MaleText_loc5`='一個裝有刀片的彈簧吸把，處理食物用的，或處理你看不順眼的人。', `MaleText_loc7`='Un desatascador con cuchillas accionado por muelles, para procesar comida. O gente que te lleva la contraria.', `FemaleText_loc1`='송곳 달린 스프링 청소기 어때? 과일 주스를 만들 때도 쓸 수 있잖아?', `FemaleText_loc4`='一只用弹簧带动的活塞，上面绑着刀刃，用来处理食物。或者是一些和你意见不一的人。', `FemaleText_loc5`='一個裝有刀片的彈簧吸把，處理食物用的，或處理你看不順眼的人。', `FemaleText_loc7`='Un desatascador con cuchillas accionado por muelles, para procesar comida. O gente que te lleva la contraria.' WHERE `ID`=37350;
