UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광대들 말인데. 웃길 때가 아니면 맞으려고 있는 거지.', `MaleText_loc4`='小丑，除了让你发笑之外，你还可以暴打他们。', `MaleText_loc5`='小丑。功能一般應該是讓你笑，但它們是讓你出氣用的。', `MaleText_loc7`='Payasos. Aunque en vez de hacerte reír, están ahí para que les des una paliza.', `FemaleText_loc1`='광대들 말인데. 웃길 때가 아니면 맞으려고 있는 거지.', `FemaleText_loc4`='小丑，除了让你发笑之外，你还可以暴打他们。', `FemaleText_loc5`='小丑。功能一般應該是讓你笑，但它們是讓你出氣用的。', `FemaleText_loc7`='Payasos. Aunque en vez de hacerte reír, están ahí para que les des una paliza.' WHERE `ID`=37352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코연장기가 있다면 여러 방에서 냄새를 맡을 수 있을 텐데.', `MaleText_loc4`='模拟鼻子。用来闻不同房间里的气味。', `MaleText_loc5`='鼻子加長器，為了讓你能聞到不同房間裡的味道。', `MaleText_loc7`='Extensores de nariz. Para oler cosas en habitaciones distintas.', `FemaleText_loc1`='코연장기가 있다면 여러 방에서 냄새를 맡을 수 있을 텐데.', `FemaleText_loc4`='模拟鼻子。用来闻不同房间里的气味。', `FemaleText_loc5`='鼻子加長器，為了讓你能聞到不同房間裡的味道。', `FemaleText_loc7`='Extensores de nariz. Para oler cosas en habitaciones distintas.' WHERE `ID`=37353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이지 않는 토끼를 만드는 거야! 여기저기 뿌려놓고 모든 것을 조종하는 거지!', `MaleText_loc4`='隐形触发器！我们会让它们遍布这里的每一个角落。它们就能控制一切了！', `MaleText_loc5`='隱形兔寶寶!將它們四處放置，所有一切都將被它們控制!', `MaleText_loc7`='¡Conejos invisibles! ¡Los pondremos por todas partes y lo controlarán todo!', `FemaleText_loc1`='보이지 않는 토끼를 만드는 거야! 여기저기 뿌려놓고 모든 것을 조종하는 거지!', `FemaleText_loc4`='隐形触发器！我们会让它们遍布这里的每一个角落。它们就能控制一切了！', `FemaleText_loc5`='隱形兔寶寶!將它們四處放置，所有一切都將被它們控制!', `FemaleText_loc7`='¡Conejos invisibles! ¡Los pondremos por todas partes y lo controlarán todo!' WHERE `ID`=37354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적 조합을 만들어볼까?', `MaleText_loc4`='组建个犯罪公司如何？', `MaleText_loc5`='如果我們是個犯罪組織呢?', `MaleText_loc7`='¿Y si ORGANIZAMOS el crimen?', `FemaleText_loc1`='해적 조합을 만들어볼까?', `FemaleText_loc4`='组建个犯罪公司如何？', `FemaleText_loc5`='如果我們是個犯罪組織呢?', `FemaleText_loc7`='¿Y si ORGANIZAMOS el crimen?' WHERE `ID`=37355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 전체를 조그만 상자에 넣는 거야!', `MaleText_loc4`='我们把整个小镇……放进了一个胶囊里！', `MaleText_loc5`='我會將整座城市...放進一個小盒子裡!', `MaleText_loc7`='Poner toda una ciudad... ¡en una caja minúscula!', `FemaleText_loc1`='마을 전체를 조그만 상자에 넣는 거야!', `FemaleText_loc4`='我们把整个小镇……放进了一个胶囊里！', `FemaleText_loc5`='我會將整座城市...放進一個小盒子裡!', `FemaleText_loc7`='Poner toda una ciudad... ¡en una caja minúscula!' WHERE `ID`=37356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 행사를 여는 거예요! 우리의 발명품들을 보여주는 거죠. 고블린컨이라고 하면 좋을 것 같아요. 선물로 특별 애완동물도 나눠주고요! 대부분 경매장에 팔아버리겠지만...', `MaleText_loc4`='明白吗？这可是一场盛会。你在这里可以看到我们全部的发明。我们称它为地精嘉年华。而且我们在这场盛会中还会派送特别宠物！只是大多数人可能会把那些宠物在拍卖行里卖掉。', `MaleText_loc5`='一個發表大會，了解嗎?可以現出我們所有的發明。我們將叫它「哥布林大會」。我們將會送出特殊的寵物!不過多數人大概會把它們放在拍賣場販賣賺錢。', `MaleText_loc7`='Una gran convención, ¿entiendes? Donde exhibiremos todas nuestras invenciones. Podríamos llamarlo GoblinCon. ¡Y regalaríamos mascotas especiales! Aunque la mayoría de la gente las revendería luego en la casa de subastas para sacar beneficios.', `FemaleText_loc1`='큰 행사를 여는 거예요! 우리의 발명품들을 보여주는 거죠. 고블린컨이라고 하면 좋을 것 같아요. 선물로 특별 애완동물도 나눠주고요! 대부분 경매장에 팔아버리겠지만...', `FemaleText_loc4`='明白吗？这可是一场盛会。你在这里可以看到我们全部的发明。我们称它为地精嘉年华。而且我们在这场盛会中还会派送特别宠物！只是大多数人可能会把那些宠物在拍卖行里卖掉。', `FemaleText_loc5`='一個發表大會，了解嗎?可以現出我們所有的發明。我們將叫它「哥布林大會」。我們將會送出特殊的寵物!不過多數人大概會把它們放在拍賣場販賣賺錢。', `FemaleText_loc7`='Una gran convención, ¿entiendes? Donde exhibiremos todas nuestras invenciones. Podríamos llamarlo GoblinCon. ¡Y regalaríamos mascotas especiales! Aunque la mayoría de la gente las revendería luego en la casa de subastas para sacar beneficios.' WHERE `ID`=37357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이진수 시스템을 개발하는 거야. 6과 11만 사용해서 말이지!', `MaleText_loc4`='这是一个二进制系统。它只使用两个数字。6和11。', `MaleText_loc5`='一個二位數的數字系統。它只使用兩個號碼，6和11。', `MaleText_loc7`='Un sistema de números binario. Solo utiliza dos números. El 6 y el 11.', `FemaleText_loc1`='이진수 시스템을 개발하는 거야. 6과 11만 사용해서 말이지!', `FemaleText_loc4`='这是一个二进制系统。它只使用两个数字。6和11。', `FemaleText_loc5`='一個二位數的數字系統。它只使用兩個號碼，6和11。', `FemaleText_loc7`='Un sistema de números binario. Solo utiliza dos números. El 6 y el 11.' WHERE `ID`=37358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 노움은 어떨까? 아니, 잠시만... 작은 거인이 낫겠어!', `MaleText_loc4`='巨型侏儒。不，等等……是小巨人！', `MaleText_loc5`='巨人地精。不...應該是小隻的巨人!', `MaleText_loc7`='Gnomos gigantes. No, espera... ¡gigantes pequeñitos!', `FemaleText_loc1`='거대한 노움은 어떨까? 아니, 잠시만... 작은 거인이 낫겠어!', `FemaleText_loc4`='巨型侏儒。不，等等……是小巨人！', `FemaleText_loc5`='巨人地精。不...應該是小隻的巨人!', `FemaleText_loc7`='Gnomos gigantes. No, espera... ¡gigantes pequeñitos!' WHERE `ID`=37359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이지 않는 양념을 만드는 거예요! 음식을 제대로 볼 수 있도록 말이죠!', `MaleText_loc4`='隐形调味品。永远不影响你的食物的美妙外观。', `MaleText_loc5`='隱形的佐料，讓你可以完整地看見你所有的食物。', `MaleText_loc7`='Condimentos invisibles. Para disfrutar de una visión de la comida sin obstáculos.', `FemaleText_loc1`='보이지 않는 양념을 만드는 거예요! 음식을 제대로 볼 수 있도록 말이죠!', `FemaleText_loc4`='隐形调味品。永远不影响你的食物的美妙外观。', `FemaleText_loc5`='隱形的佐料，讓你可以完整地看見你所有的食物。', `FemaleText_loc7`='Condimentos invisibles. Para disfrutar de una visión de la comida sin obstáculos.' WHERE `ID`=37360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바퀴 달린 신발과 바퀴 달린 장갑이 좋겠어요! 넘어질 때를 대비해서!', `MaleText_loc4`='带轮子的鞋子。还有带轮子的手套——专为你跌倒时设计。', `MaleText_loc5`='有輪子的鞋和手套，讓你跌倒時可以繼續往目的地前進。', `MaleText_loc7`='Zapatos con ruedas incorporadas. Y guantes con ruedas incorporadas... para cuando te caigas.', `FemaleText_loc1`='바퀴 달린 신발과 바퀴 달린 장갑이 좋겠어요! 넘어질 때를 대비해서!', `FemaleText_loc4`='带轮子的鞋子。还有带轮子的手套——专为你跌倒时设计。', `FemaleText_loc5`='有輪子的鞋和手套，讓你跌倒時可以繼續往目的地前進。', `FemaleText_loc7`='Zapatos con ruedas incorporadas. Y guantes con ruedas incorporadas... para cuando te caigas.' WHERE `ID`=37361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄 달린 비누! 사슬을 붙이고, 어떤 건 철줄에 올리고...', `MaleText_loc4`='绳子上的肥皂！特别限定版的锁链肥皂和钢缆肥皂已经上架！多种附加选择，多种额外功能。', `MaleText_loc5`='肥皂繩索!接在鐵鏈上!用鋼線綁成一串!一大串肥皂!', `MaleText_loc7`='¡Jabón con una cuerda! Atada a una cadena. Ensamblada con un cable de acero. Unido a un jabón.', `FemaleText_loc1`='줄 달린 비누! 사슬을 붙이고, 어떤 건 철줄에 올리고...', `FemaleText_loc4`='绳子上的肥皂！特别限定版的锁链肥皂和钢缆肥皂已经上架！多种附加选择，多种额外功能。', `FemaleText_loc5`='肥皂繩索!接在鐵鏈上!用鋼線綁成一串!一大串肥皂!', `FemaleText_loc7`='¡Jabón con una cuerda! Atada a una cadena. Ensamblada con un cable de acero. Unido a un jabón.' WHERE `ID`=37362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식용 침대가 좋겠어. 아침에 침대에서 식사를 할 수 있게 말이지! 아침 식사 침대!', `MaleText_loc4`='可食用的床。这样你就能在床上吃早餐了。床……为早餐而设计！', `MaleText_loc5`='可食用的床。這樣你就可以在床上吃早餐。早餐用的...床!', `MaleText_loc7`='Camas comestibles. Así puedes desayunar en la cama. Camas... ¡para desayunar!', `FemaleText_loc1`='식용 침대가 좋겠어. 아침에 침대에서 식사를 할 수 있게 말이지! 아침 식사 침대!', `FemaleText_loc4`='可食用的床。这样你就能在床上吃早餐了。床……为早餐而设计！', `FemaleText_loc5`='可食用的床。這樣你就可以在床上吃早餐。早餐用的...床!', `FemaleText_loc7`='Camas comestibles. Así puedes desayunar en la cama. Camas... ¡para desayunar!' WHERE `ID`=37363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행성 지하를 바깥으로 보여주는 행성 모형은 어떨까요? 그럼 어디를 파 들어가야 하는지 알 수 있겠죠!', `MaleText_loc4`='一个球，能够在球面上显示出这颗行星的……内部构造……这样你就知道能在哪里进行挖掘了！', `MaleText_loc5`='一個天球儀，將行星的裡面...顯示在外面。這樣你就知道要挖哪了!', `MaleText_loc7`='Un globo que muestra el interior del planeta... en el exterior. ¡Así sabrás dónde cavar!', `FemaleText_loc1`='행성 지하를 바깥으로 보여주는 행성 모형은 어떨까요? 그럼 어디를 파 들어가야 하는지 알 수 있겠죠!', `FemaleText_loc4`='一个球，能够在球面上显示出这颗行星的……内部构造……这样你就知道能在哪里进行挖掘了！', `FemaleText_loc5`='一個天球儀，將行星的裡面...顯示在外面。這樣你就知道要挖哪了!', `FemaleText_loc7`='Un globo que muestra el interior del planeta... en el exterior. ¡Así sabrás dónde cavar!' WHERE `ID`=37364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옆으로 가는 계단이 있다면 좋겠는걸!', `MaleText_loc4`='专为水平移动设计的……楼梯！', `MaleText_loc5`='讓你平形走在地面的樓梯!', `MaleText_loc7`='Escaleras... ¡para superficies horizontales!', `FemaleText_loc1`='옆으로 가는 계단이 있다면 좋겠는걸!', `FemaleText_loc4`='专为水平移动设计的……楼梯！', `FemaleText_loc5`='讓你平形走在地面的樓梯!', `FemaleText_loc7`='Escaleras... ¡para superficies horizontales!' WHERE `ID`=37365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 거기. 자네가 누구인지, 왜 나를 따라다니는지 모르겠지만, 하여튼 난 배에 오를 참이라고. 나 좀 내버려 두라고, 알아들었나?', `MaleText_loc4`='嘿，伙计，我不认识你，也不知道你为什么要一直跟着我，但我马上就要上船了，并且我想自己一个人呆着，明白吗？', `MaleText_loc5`='嗨，老兄，我不知道你是誰或是你跟著我想做什麼，但即將上船而且想一個人靜靜，懂嗎?', `MaleText_loc7`='Eh, $gamigo:amiga;, no sé quién eres ni por qué me estás siguiendo, pero estoy a punto de embarcar y quiero que me dejes en paz, ¿vale?' WHERE `ID`=37366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신의 표시가 있는 로켓을 가지고 있습니다, 스니블.', `MaleText_loc4`='斯内维尔，我这有一只火箭，上面有你的标记。', `MaleText_loc5`='我這裡有個火箭上頭有你的印記，史尼佛。', `MaleText_loc7`='Tengo aquí un cohete con tu marca, Quejica.', `FemaleText_loc1`='난 당신의 표시가 있는 로켓을 가지고 있어요, 스니블.', `FemaleText_loc4`='斯内维尔，我这有一只火箭，上面有你的标记。', `FemaleText_loc5`='我這裡有個火箭上頭有你的印記，史尼佛。', `FemaleText_loc7`='Tengo aquí un cohete con tu marca, Quejica.' WHERE `ID`=37367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFFFF00비춰진 영혼|r을 시전합니다!', `MaleText_loc4`='%s施放了|cFFFFFF00灵魂倒映!|r', `MaleText_loc5`='%s施展了|cFFFFFF00鏡像之魂!|r', `MaleText_loc7`='%s lanza |cFFFFFF00Alma reflejada|r' WHERE `ID`=37368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사들이여, 잘 해내셨군요! 이 방 안에 우리 기지를 세워야겠어요. 곧 마법사들이 스컬지 이동 수단을 준비할 거예요. 다음 임무를 수행할 준비가 되면 그 안으로 들어가세요. 다른 쪽에서 만나도록 하지요.', `FemaleText_loc4`='干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务会在目的地等着你。', `FemaleText_loc5`='幹得漂亮，勇士們!我們會在這些密室設下營地。我的法師很快會讓天譴軍團的傳送裝置恢復運作。等你準備好，就站進去迎接下一項任務吧。我會在另一邊和你碰頭。', `FemaleText_loc7`='¡Un trabajo excelente, campeones! Armaremos nuestro campamento base en estas salas. Mis magos harán que el teletransportador de la Plaga funcione en poco tiempo. Entren cuando estén preparados para la próxima misión. Nos veremos en el otro lado.' WHERE `ID`=37369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 무사히 여기까지 인도하신 빛에 감사드려요! 리치 왕을 무찌르고 스컬지를 끝장내려면 할 일이 많아요.', `FemaleText_loc4`='感谢圣光，你安然无恙！为了消灭巫妖王和天灾军团，我们还有很多事要做。', `FemaleText_loc5`='感謝聖光能看到你平安無事!如果要擊敗巫妖王和天譴軍團，還有好多事情等著我們。', `FemaleText_loc7`='¡Le doy gracias a la Luz por verlos a salvo! Tenemos mucho trabajo que hacer si queremos derrotar al Rey Exánime y poner fin a la Plaga.' WHERE `ID`=37370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은빛십자군과 칠흑의 기사단에 있는 우리 동맹은 얼음왕관의 정문을 통과하여 성채 안에 근거지를 마련하려는 중이에요.', `FemaleText_loc4`='银色北伐军和黑锋骑士团的盟军已经打破冰冠堡垒的大门，他们正努力在城堡中安置一个前哨站。', `FemaleText_loc5`='我們在銀白十字軍和黯刃騎士團中的盟友已經攻破了寒冰皇冠的前門，而且也準備在城塞中建立橋頭堡。', `FemaleText_loc7`='Nuestros aliados de la Cruzada Argenta y de los Caballeros de la Espada de Ébano han traspasado la Puerta Principal de la Corona de Hielo y tratan de asentar una avanzada en la Ciudadela.' WHERE `ID`=37371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이 성공할지는 우리가 이 저주받은 전당 안에서 무엇을 발견하는지에 달렸어요. 비록 우리 임무는 너무나 위험하지만, 끝까지 해내야 해요.', `FemaleText_loc4`='我们在这些厅堂中的发现将决定他们的成败。虽然任务危险重重，但我们必须坚持！', `FemaleText_loc5`='他們的成功取決於在這些受詛咒大廳中的發現。儘管我們的任務如此艱難，我們必須堅持不懈!', `FemaleText_loc7`='Su éxito depende de lo que descubramos en estos salones malditos. Aunque nuestra misión sea arriesgada, ¡debemos perseverar!' WHERE `ID`=37372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕이 정문으로 주의를 돌렸으니 우리는 측면으로 들어가 정보를 찾도록 해요. 스컬지를 마지막으로 확실히 무찌를 수 있는 정보 말이에요.', `FemaleText_loc4`='当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找有用的重要情报，从而一劳永逸地铲除天灾军团。', `FemaleText_loc5`='隨著巫妖王的注意力被吸引到前門，我們要趁機從旁收集能一勞永逸解決天譴軍團的情報。', `FemaleText_loc7`='Con la atención del Rey Exánime puesta en la Puerta Principal, nos abriremos camino por el lateral en busca de información que nos permitirá derrotar a la Plaga de una vez por todas.' WHERE `ID`=37373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안 폐하의 SI:7 요원들은 투영의 전당이라 불리는 곳 깊숙이 자리 잡은 리치 왕의 개인 성소에 대한 정보를 수집했지요.', `FemaleText_loc4`='瓦里安国王的军情七处得到情报，巫妖王的私人密室就深藏在一个被称作映像大厅的地方。', `FemaleText_loc5`='瓦里安王的軍情七處探員收集到了關於巫妖王私人聖所的情報，深藏在一個名為倒影大廳的地方。', `FemaleText_loc7`='Los agentes IV:7 del rey Varian tienen información sobre el sagrario privado del Rey Exánime en lo profundo del lugar llamado las Cámaras de Reflexión. ' WHERE `ID`=37374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 참담한 곳을 지나 투영의 전당으로 들어갈 방법을 모색하겠어요. 전당 안에 감춰진, 강력한 마법이 느껴지는군요. 이 마법이 스컬지를 파괴하는 열쇠가 될 수 있어요!', `FemaleText_loc4`='我们要想办法杀出一条通往映像大厅的血路。我感到那里潜藏着强大的魔法。那将是摧毁天灾军团的关键！', `FemaleText_loc5`='我們將會從這個卑劣的地方中挖出一條通道，找到方法進入倒影大廳。我感應到強大的魔法藏在這些大廳之中。這樣的法力或許正是摧毀天譴軍團的關鍵!', `FemaleText_loc7`='Nos abriremos paso a través de ese espantoso lugar y encontraremos la forma de entrar en las Cámaras de Reflexión. Siento una magia poderosa oculta en esos salones. ¡Una magia que podría ser la clave para destruir a la Plaga! ' WHERE `ID`=37375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첫 번째 임무는 이 사악한 영혼의 기관 안에서 죽음의 기계를 파괴하고 병사들이 나아갈 길을 마련하는 거예요.', `FemaleText_loc4`='你的首个任务是摧毁灵魂引擎中的死亡机器，为我们的士兵杀出一条路来。', `FemaleText_loc5`='你的首要任務就是摧毀這個邪惡靈魂引擎中的死亡機械，並且替我們的士兵清出一條通道來。', `FemaleText_loc7`='Su primera misión consiste en destruir las máquinas de la muerte dentro de este maldito engranaje de almas y despejar el camino para nuestros soldados.' WHERE `ID`=37376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅들이여, 서두르세요! 부대를 뒤로 집결시키겠어요.', `FemaleText_loc4`='赶快，勇士们！我会让部队紧跟在你们身后。', `FemaleText_loc5`='動作快一點，勇士們!我會集結部隊盡快趕上你們。', `FemaleText_loc7`='¡Apresúrense, campeones! Ordenaré a las tropas que los sigan.' WHERE `ID`=37377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡는 중', `MaleText_loc4`='拾起', `MaleText_loc5`='拿取', `MaleText_loc7`='Recogiendo', `FemaleText_loc1`='잡는 중', `FemaleText_loc4`='拾起', `FemaleText_loc5`='拿取', `FemaleText_loc7`='Recogiendo' WHERE `ID`=37379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은빛십자군과 칠흑의 기사단은 얼음왕관 성채 관문을 습격했고 스컬지에 대규모 공격을 퍼부으려 준비 중이다. 우리 임무는 좀 더 까다롭지만, 중요하기는 마찬가지다.', `FemaleText_loc4`='银色北伐军和黑锋骑士团已经攻入冰冠城堡大门，正准备向天灾军团发动总攻。我们的任务虽小，但同样重要。', `FemaleText_loc5`='銀白十字軍和黯刃騎士團正在攻打冰冠城塞的大門，並且準備對天譴軍團展開大規模進攻。我們的任務比較低調一點，但同樣的重要。', `FemaleText_loc7`='La Cruzada Argenta y los Caballeros de la Espada de Ébano han asaltado las puertas de la Ciudadela de la Corona de Hielo y están preparando un ataque masivo sobre la Plaga. Nuestra misión es un tanto más sutil, pero igual de importante.' WHERE `ID`=37380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕이 정문으로 주의를 돌렸으니 우리는 옆으로 들어가 정보를 찾도록 하자. 그를 완전히, 그리고 영원히 끝장낼 수 있는 정보 말이다.', `FemaleText_loc4`='当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找能帮助我们的重要情报，彻底除掉巫妖王。', `FemaleText_loc5`='隨著巫妖王的注意力被吸往前門，我們要先從旁側擊來收集情報，這樣可以讓我們一勞永逸地擊敗巫妖王。', `FemaleText_loc7`='Con la atención del Rey Exánime puesta en la Puerta Principal, nos abriremos camino por el lateral en busca de información que nos permita derrotar al Rey Exánime... de una vez por todas.' WHERE `ID`=37381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정찰병의 보고에 따르면 리치 왕은 얼어붙은 왕좌 바깥쪽, 투영의 전당이라 불리는 곳에 자기 공간이 따로 있다고 한다. 영웅들이여, 그곳이 우리 목표다.', `FemaleText_loc4`='我们的侦察兵说巫妖王在冰封王座外有个私人密室，深藏在被称作映像大厅的地方。那就是我们的目标，勇士们。', `FemaleText_loc5`='我們斥候回報說巫妖王有一間私人密室，在冰封王座之外，深藏在一個名為倒影大廳的地方。而這就是我們的目標，勇士們。', `FemaleText_loc7`='Nuestros exploradores nos han informado que el Rey Exánime tiene una sala en el exterior del Trono Helado, en lo profundo de un lugar llamado las Cámaras de Reflexión. Ese es nuestro objetivo, campeones.' WHERE `ID`=37382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 저주받은 곳을 쓸고 지나가면서 투영의 전당으로 가는 길을 찾겠다. 이곳에 무언가 귀중한 것이 있다면, 전당 안에 있을 거다.', `FemaleText_loc4`='我们会一路杀进这个被诅咒的地方，找到进入映像大厅的入口。那里一定隐藏着某些极具价值的情报。', `FemaleText_loc5`='我們會對這個詛咒之地造成一連串破壞，然後找出一條路進入倒影大廳。如果能找到任何有價值的東西，必定在大廳之中。', `FemaleText_loc7`='Abriremos una senda de destrucción a través de ese maldito lugar y encontraremos una forma de entrar a las Cámaras de Reflexión. Si hay algo de valor aquí, lo encontraremos en los salones.' WHERE `ID`=37383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 여왕이 지켜보겠다. 서둘러라!', `FemaleText_loc4`='黑暗女王正在看着你，加紧行动！', `FemaleText_loc5`='黑暗女王看照著你。動作快!', `FemaleText_loc7`='La Dama Oscura los protege. ¡Apresúrense!' WHERE `ID`=37384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘해냈다, 용사들이여! 이 방 안에 우리 기지를 세워야겠다. 마법사들이 곧 스컬지 이동 수단을 준비할 것이다. 다음 임무를 수행할 준비가 되면 그 안으로 들어가라. 나와 그쪽에서 만나자.', `FemaleText_loc4`='干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务在目的地等着你。', `FemaleText_loc5`='幹得漂亮，勇士們!我們會在這些密室設立據點。我的法師很快會讓天譴軍團的傳送裝置恢復運作。等你準備好，就站進去迎接下一項任務吧。我會在另一邊和你碰頭。', `FemaleText_loc7`='¡Un trabajo excelente, campeones! Armaremos nuestro campamento base en estas salas. Mis magos harán que el teletransportador de la Plaga funcione en poco tiempo. Entren cuando estén preparados para la próxima misión. Nos veremos en el otro lado.' WHERE `ID`=37387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 감사드리오, $n. 쿠엘델라를 적법한 소유자에게 가져다줘서 말이오.', `MaleText_loc4`='就这样吧。感谢你，$n，帮助我们将奎尔德拉归还给它真正的拥有者。', `MaleText_loc5`='你辦到了。我感謝你，$n，使奎爾德拉復原並回到正確的持有者之手。', `MaleText_loc7`='Así sea. Tienes mi agradecimiento, $n, por restaurar Quel''Delar a sus legítimos propietarios.' WHERE `ID`=37388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 이런 반역 행위를?', `MaleText_loc4`='这场背叛究竟意味着什么？', `MaleText_loc5`='這場背叛有何意義?', `MaleText_loc7`='¿Qué significa esta traición?' WHERE `ID`=37389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 놓고 항복해라, 반역자여.', `MaleText_loc4`='放下武器投降，叛徒。', `MaleText_loc5`='放下你的武器並且投降，叛徒。', `MaleText_loc7`='Suelta el arma y ríndete, $gtraidor:traidora;.' WHERE `ID`=37390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 순간이동기를 작동시키느라 너무나 많은 피를 흘렸소. 이 수모는 반드시 갚도록 각오를 다져야 하오. 나를 따르시오, 제군들!', `MaleText_loc4`='我们的勇士在激活这台天灾传送器的战斗中付出了沉重的代价。我们必须时刻准备着延续他们的光辉。伙伴们，跟我来！', `MaleText_loc5`='我們的勇士付出很大的犧牲才啟動這個天譴軍團傳送器。我們一定要回報他們的付出。跟著我!', `MaleText_loc7`='Nuestros campeones han perdido mucha sangre en esta lucha por activar el teletransportador de la Plaga. Debemos estar preparados para devolver el favor. ¡Síganme, hombres!' WHERE `ID`=37391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드의 병사들이여, 공격하라!', `FemaleText_loc4`='部落的战士们，进攻！', `FemaleText_loc5`='部落的士兵們，攻擊!', `FemaleText_loc7`='¡Soldados de la Horda, al ataque!' WHERE `ID`=37392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나약한 존재 같으니.', `FemaleText_loc4`='可怜的家伙。', `FemaleText_loc5`='可悲的弱者。', `FemaleText_loc7`='¡Patéticos alfeñiques!' WHERE `ID`=37393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 구덩이는 너희 힘만으로 빠져나가야 한다.', `FemaleText_loc4`='你只能靠自己冲过这个肮脏的地方了。', `FemaleText_loc5`='你必須要自己打出一條通路穿過這個污穢之淵。', `FemaleText_loc7`='Tendrán que atravesar este foso por su cuenta.' WHERE `ID`=37394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 노예는 마주치는 대로 자유롭게 해 주어라. 티라누스와 싸울 때 그들의 도움이 반드시 필요하다. 나는 지원병력을 모아 채석장 반대편에서 합류하겠다.', `FemaleText_loc4`='解救你遇到的所有部落奴隶。我们需要他们的协助来对抗泰兰努斯。我会集结援军，并在矿坑对面与你汇合。', `FemaleText_loc5`='釋放你遇到的任何一個部落奴隸。在對抗提朗紐斯的戰鬥中會需要他們的協助。我會召集援軍在礦場的另一邊跟你會合。', `FemaleText_loc7`='Liberen a los esclavos de la Horda que encuentren en su camino. Seguramente necesitemos su ayuda en la batalla contra Tyrannus. Reuniré refuerzos y nos veremos al otro lado de la cantera.' WHERE `ID`=37395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지원 병력이 더 올 때까지 여기서 시간을 끌어보겠지만, 그대들은 계속 나아가야 한다. 우리가 여기에 왔음을 곧 아서스가 눈치챌 것이다.', `FemaleText_loc4`='在援兵赶到前我会尽量拖延时间，但你必须继续前进。阿尔萨斯很快会发现我们在这里。', `FemaleText_loc5`='我會留在這裡等候更多援軍抵達，但你一定要繼續往前。阿薩斯很快就會知道我們在這裡了。', `FemaleText_loc7`='Yo esperaré aquí hasta que lleguen refuerzos, pero ustedes deben seguir. Pronto Arthas se dará cuenta de que estamos aquí.' WHERE `ID`=37397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 포세이큰 놈들! 반드시 대가를 치르게 될 거야!', `MaleText_loc4`='该死的被遗忘者！他们要为他们所做的一切付出代价！', `MaleText_loc5`='天殺的被遺忘者!他們會為他們所做的付出代價!', `MaleText_loc7`='¡Malditos Renegados! ¡Pagarán por lo que han hecho!' WHERE `ID`=37398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 소중한 우리의 삶터야. 적들에게 순순히 빼앗길 수는 없지!', `MaleText_loc4`='这是我们的土地——如果不打败我们，就别想夺走它！', `MaleText_loc5`='這是我們的土地，他們別以為我們會在不反抗下把它拱手讓人!', `MaleText_loc7`='Esta es nuestra tierra. ¡No vamos a dejar que se la quede nadie sin luchar!' WHERE `ID`=37399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이렇게 노예로 죽지는 않을 것이다... 우리는 길니아스인이니까!', `MaleText_loc4`='我们不会作为奴隶而死……我们是吉尔尼斯人！', `MaleText_loc5`='我們不會以奴隸的身分死去...我們是吉爾尼斯人!', `MaleText_loc7`='No moriremos como esclavos... ¡Somos gilneanos!' WHERE `ID`=37400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라를 마셔보아요!', `MaleText_loc4`='喝点卡亚可乐吧！', `MaleText_loc5`='暢飲卡迦可樂!', `MaleText_loc7`='¡Bebe Kaja''Cola!' WHERE `ID`=37401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 새로운 카자콜라! 근사한 생각이 마구 떠오릅니다!', `MaleText_loc4`='全新的卡亚可乐！喝下一口，灵感翻倍！', `MaleText_loc5`='全新的卡迦可樂!現在增添了百分之百更多的好點子!', `MaleText_loc7`='¡Nueva Kaja''Cola! ¡Ahora con un cien por cien más de ideas!' WHERE `ID`=37402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라 맛보기 시험에 도전하세요!', `MaleText_loc4`='卡亚可乐尝味大挑战！', `MaleText_loc5`='參加卡迦可樂試喝挑戰!', `MaleText_loc7`='¡Acepta el desafío de la prueba de cata de Kaja''Cola!' WHERE `ID`=37403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라! 생각이 팡팡 터집니다!', `MaleText_loc4`='卡亚可乐！灵感之源！', `MaleText_loc5`='卡迦可樂!帶給你好靈感!', `MaleText_loc7`='¡Kaja''Cola! ¡Te da IDEAS!' WHERE `ID`=37404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라! 족제비가 말했지! 카자콜라를 마셔라 아니면...!', `MaleText_loc4`='卡亚可乐！阿尔伯特·牛盾说过，有卡亚，有我在！', `MaleText_loc5`='卡迦可樂!白鼬金克希說:「不喝它就什麼都不要喝!」', `MaleText_loc7`='¡Kaja''Cola! Jinxy la comadreja dice: "¡Bébela... o ya verás!".' WHERE `ID`=37405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라는 자랑스러운 우리의 빌지워터 해적구단을 후원합니다!', `MaleText_loc4`='卡亚可乐——锈水海盗队荣誉赞助品牌！', `MaleText_loc5`='卡迦可樂的榮譽贊助商污水海盜!', `MaleText_loc7`='Kaja''Cola es el orgulloso patrocinador de los Bucaneros Pantoque.' WHERE `ID`=37406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라! 최고의 땜장이가 되고 싶을 때 필요한 것!', `MaleText_loc4`='卡亚可乐！喝上一口，你的工艺技巧就无人可比！', `MaleText_loc5`='卡迦可樂!讓你不再需要苦惱喝哪種飲料!', `MaleText_loc7`='¡Kaja''Cola! ¡Para cuando tus trapicheos tienen que estar a la altura!' WHERE `ID`=37407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원기를 회복시켜주고 머리를 좋게 해주는 새로운 카자콜라를 마셔보세요!', `MaleText_loc4`='品尝全新的卡亚可乐，享受全新的智慧生活！', `MaleText_loc5`='享受清涼爽口的新版卡迦可樂!', `MaleText_loc7`='¡Disfruta del nuevo sabor refrescantemente inteligente de la nueva Kaja''Cola!' WHERE `ID`=37408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못생긴 놈이 코로스 깃발 잡았다! 못생긴 놈 잡아먹을 거야!', `MaleText_loc4`='丧尸人抢了克洛斯的旗帜！丧尸人要被打成碎片了！！！', `MaleText_loc5`='屍體人拿了寇羅斯的旗子!屍體人會被打成爛泥!', `MaleText_loc7`='Los hombres-cadáveres se llevan el estandarte de Koroth! ¡¡¡Hagamos añicos a los hombres-cadáveres!!!' WHERE `ID`=37409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 맞춰 왔소. 포세이큰이 몰려오는군.', `MaleText_loc4`='正是时候，$n。被遗忘者来了。', `MaleText_loc5`='正是時候，朋友。被遺忘者來了。', `MaleText_loc7`='Justo a tiempo, amigo. Aquí vienen los Renegados.' WHERE `ID`=37410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 한 발자국도 움직일 생각 말아라, 포세이큰 쓰레기들아! 그레이메인의 전쟁 깃발 아래, 내 너희를 조상님들의 땅에서 몰아낼 것이다!', `MaleText_loc4`='到此为止了，被遗忘者渣滓！以格雷迈恩家族战旗起誓，我要把你们驱逐出这片先祖之地！', `MaleText_loc5`='到此為止了，被遺忘者的敗類們!以葛雷邁恩部族的古老戰旗之名，我驅逐你們離開我們的先祖之地!', `MaleText_loc7`='¡No avanzarán más, basura renegada! ¡Por el estandarte del clan ancestral de Cringris, estás expulsado de nuestras tierras!' WHERE `ID`=37411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하룻강아지 같은 놈. 네놈이 깃발이라고 부르는 이 너저분한 넝마로 화장실이나 닦아야겠군.', `MaleText_loc4`='没用的杂种。拿这块被你们叫做旗子的破布擦地板再合适不过了。', `MaleText_loc5`='沒用的垃圾。我會用你稱為旗幟的這塊爛布來清理我們的廁所。', `MaleText_loc7`='Chucho inútil. Daré la orden de que limpien nuestros establos con este trapo que tú llamas estandarte.' WHERE `ID`=37412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가짜 음식이 좋겠어! 진짜 음식을 갈아 다른 음식처럼 모양을 만들고 인공 감미료로 위장시키는 거야!', `MaleText_loc4`='仿真食物！把真正的食物碾碎，然后压制成各种食物的形状。还添加了足以以假乱真的香料！', `MaleText_loc5`='假的食物!先將真的食物搗碎了再做成其他種類的食物，還帶有人工香料!', `MaleText_loc7`='¡Comida de mentira! Podemos crearla moliendo alimentos reales para luego darles forma de otros alimentos. ¡Con condimentos artificiales!', `FemaleText_loc1`='가짜 음식이 좋겠어! 진짜 음식을 갈아 다른 음식처럼 모양을 만들고 인공 감미료로 위장시키는 거야!', `FemaleText_loc4`='仿真食物！把真正的食物碾碎，然后压制成各种食物的形状。还添加了足以以假乱真的香料！', `FemaleText_loc5`='假的食物!先將真的食物搗碎了再做成其他種類的食物，還帶有人工香料!', `FemaleText_loc7`='¡Comida de mentira! Podemos crearla moliendo alimentos reales para luego darles forma de otros alimentos. ¡Con condimentos artificiales!' WHERE `ID`=37413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마 탐지기는 어떨까?', `MaleText_loc4`='老妈探测器。', `MaleText_loc5`='媽媽探測器。', `MaleText_loc7`='Detectores de madres.', `FemaleText_loc1`='엄마 탐지기는 어떨까?', `FemaleText_loc4`='老妈探测器。', `FemaleText_loc5`='媽媽探測器。', `FemaleText_loc7`='Detectores de madres.' WHERE `ID`=37414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지로 만든 집! 청소만 하면... 사라지는 거예요.', `MaleText_loc4`='用泥土做的房子！如果你把它们清扫干净……它们就不存在了。', `MaleText_loc5`='灰塵做的房子!當你用吸塵器打掃時...房子便沒了。', `MaleText_loc7`='¡Casas de mugre! Cuando las limpias... DESAPARECEN.', `FemaleText_loc1`='먼지로 만든 집! 청소만 하면... 사라지는 거예요.', `FemaleText_loc4`='用泥土做的房子！如果你把它们清扫干净……它们就不存在了。', `FemaleText_loc5`='灰塵做的房子!當你用吸塵器打掃時...房子便沒了。', `FemaleText_loc7`='¡Casas de mugre! Cuando las limpias... DESAPARECEN.' WHERE `ID`=37415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미사용 제품 전용 재활용기는 어떨까?', `MaleText_loc4`='循环回收利用！但只回收从未使用用过的全新物品。', `MaleText_loc5`='回收中!但只有從沒用過的東西。', `MaleText_loc7`='¡Reciclado! Pero para cosas que nunca han sido utilizadas.', `FemaleText_loc1`='미사용 제품 전용 재활용기는 어떨까?', `FemaleText_loc4`='循环回收利用！但只回收从未使用用过的全新物品。', `FemaleText_loc5`='回收中!但只有從沒用過的東西。', `FemaleText_loc7`='¡Reciclado! Pero para cosas que nunca han sido utilizadas.' WHERE `ID`=37416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플러버츠라... 뭔지는 잘 모르지만 상표명으로 등록해야겠어.', `MaleText_loc4`='“吸引力诱发”，我不确定这有什么用，不过我最好先把这个名字注册一个商标。', `MaleText_loc5`='FLIRBERTS...呃..婦樂伯爾特斯??我不確定這是幹什麼用的，但我最好先把這名字註冊下再說。', `MaleText_loc7`='Florbetes. No sé qué son, pero mejor me aseguro el nombre con una marca registrada.', `FemaleText_loc1`='플러버츠라... 뭔지는 잘 모르지만 상표명으로 등록해야겠어요.', `FemaleText_loc4`='“吸引力诱发”，我不确定这有什么用，不过我最好先把这个名字注册一个商标。', `FemaleText_loc5`='FLIRBERTS...呃..婦樂伯爾特斯??我不確定這是幹什麼用的，但我最好先把這名字註冊下再說。', `FemaleText_loc7`='Florbetes. No sé qué son, pero mejor me aseguro el nombre con una marca registrada.' WHERE `ID`=37417;
