UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐만 한 곰덫... 아니 곰만 한 쥐덫!!', `MaleText_loc4`='适合老鼠体形的捕熊器……不……适合熊体形的捕鼠器！！', `MaleText_loc5`='老鼠大小的捕熊夾...不對...像熊一樣大的捕鼠夾!!', `MaleText_loc7`='Trampas del tamaño de un ratón para osos... no... ¡¡Trampas del tamaño de un oso para ratones!!', `FemaleText_loc1`='쥐만 한 곰덫... 아니 곰만 한 쥐덫!!', `FemaleText_loc4`='适合老鼠体形的捕熊器……不……适合熊体形的捕鼠器！！', `FemaleText_loc5`='老鼠大小的捕熊夾...不對...像熊一樣大的捕鼠夾!!', `FemaleText_loc7`='Trampas del tamaño de un ratón para osos... no... ¡¡Trampas del tamaño de un oso para ratones!!' WHERE `ID`=37423;
