UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀이개도 어딘가 쓸모가 있지 않을까?', `MaleText_loc4`='耳垢，这一定会有点什么用处的。', `MaleText_loc5`='耳垢。這應該可以用來做什麼。', `MaleText_loc7`='Cera de oídos. Tiene que servir para ALGO.', `FemaleText_loc1`='귀이개도 어딘가 쓸모가 있지 않을까?', `FemaleText_loc4`='耳垢，这一定会有点什么用处的。', `FemaleText_loc5`='耳垢。這應該可以用來做什麼。', `FemaleText_loc7`='Cera de oídos. Tiene que servir para ALGO.' WHERE `ID`=37429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롬매스, 이건 제가 한 일이 아닙니다. 여기에서 반역따위는 일어나지 않습니다.', `MaleText_loc4`='这并不是我做的，罗曼斯。我没有背叛任何人。', `MaleText_loc5`='這不是我幹的，洛摩斯。這不是背叛。', `MaleText_loc7`='Esto no es culpa mía, Rommath. No es una traición.' WHERE `ID`=37430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들을 물러나게 하십시오. 로르테마르는 어리석었기에 그런 부상을 자초한 겁니다. 쿠엘델라는 선택받지 않습니다. 주인을 선택하지요.', `MaleText_loc4`='叫你的人停手。洛瑟玛·塞隆受伤只能怪他自己愚蠢。没人能驾驭奎尔德拉；它只听从自己认定的主人。', `MaleText_loc5`='叫你的手下退開。洛索瑪的愚昧讓他自己受了傷。奎爾德拉不能讓人去持有;它會選擇自己的主人。', `MaleText_loc7`='Retira a tus hombres. La estupidez del propio Lor''themar causó sus heridas. Quel''Delar no se elige; ella elige a su maestro.' WHERE `ID`=37431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병들, 자기 구역으로 돌아가라.', `MaleText_loc4`='卫兵，回到你们的岗位。', `MaleText_loc5`='守衛，回到你們的崗位。', `MaleText_loc7`='Guardias, vuelvan a sus puestos.' WHERE `ID`=37432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장의 말이 맞는 듯하오. 결국 쿠엘델라는 우리에게 돌아오지 않는군.', `MaleText_loc4`='看起来队长说的是对的。我们完全无法驾驭奎尔德拉。', `MaleText_loc5`='看來上尉是對的。終究，奎爾德拉並不屬於我們。', `MaleText_loc7`='Parece que el capitán tiene razón. Al final, Quel''Delar no será nuestra.' WHERE `ID`=37433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 그대가 찾으러 온 것을 가져가도 좋소. 검을 가지고 물러가시오. 그리고 아우릭 자네는 이런 성스러운 곳에서는 말을 가려서 하게.', `MaleText_loc4`='你会得到你想要的，$n。带着这把剑走吧。至于你，乌瑞克，在圣地要注意你讲话的方式。', `MaleText_loc5`='你會得到你為此而來的東西，$n。拿著劍並且離去吧。而你，阿瑞克，注意你在聖地中的言詞。', `MaleText_loc7`='Tendrás lo que buscas, $n. Toma la espada y márchate. Y tú, Auric, ten cuidado con lo que dices en este lugar sagrado.' WHERE `ID`=37434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이시여, 순간이동기가 작동합니다!', `MaleText_loc4`='圣光万岁，传送器工作了！', `MaleText_loc5`='以聖光之名，傳送器可以運作了!', `MaleText_loc7`='¡Por la Luz, el teletransportador funcionó!' WHERE `ID`=37435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 감도는 한기 때문에 뼛속까지 시리군.', `MaleText_loc4`='这个寒冷的地方让我的骨髓都凝固了。', `MaleText_loc5`='這個地方的寒冷幾乎把我連骨髓都凍住了。', `MaleText_loc7`='El frío de este lugar me hiela hasta la médula.' WHERE `ID`=37436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 손길이 느껴지네... 우리를 보고 있어.', `MaleText_loc4`='我能感到巫妖王的召唤。', `MaleText_loc5`='我可以感覺到巫妖王的視線...注視著我們。', `MaleText_loc7`='Siento al Rey Exánime cerca... observándonos.' WHERE `ID`=37437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 거대한 사로나이트 덩어리를 당신에게 던집니다!', `MaleText_loc4`='%s向你用力投出一大块萨隆邪铁巨石！', `MaleText_loc5`='%s對你丟出一大塊薩鋼巨石!', `MaleText_loc7`='¡%s te lanza un pedrusco de saronita enorme!' WHERE `ID`=37438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섭정님! 저들이 무슨 짓을 한 겁니까?', `MaleText_loc4`='我的摄政王！他们都对你做了些什么？', `MaleText_loc5`='攝政王!他們對你做了什麼?', `MaleText_loc7`='¡Mi Señor regente! ¿Qué te han hecho?' WHERE `ID`=37439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 차원문을 타고 그 검을 달라란으로 가져가십시오. 오랜 세월 동안 많은 쿠엘도레이가 꿈꿔왔던 일을 해내셨습니다. 마침내 쿠엘델라가 복원되었으니 말입니다.', `MaleText_loc4`='$n，带着剑穿过那道传送门返回达拉然。你完成了众多奎尔多雷人许多年来梦寐以求的伟业。终于夺回了奎尔德拉。', `MaleText_loc5`='帶著劍穿過傳送門回去達拉然吧，$n。你完成了無數奎爾多雷許多年來夢寐以求之事。奎爾德拉終於復原了。', `MaleText_loc7`='Lleva la espada de vuelta a Dalaran a través del portal, $n. Has hecho lo que muchos quel''dorei han soñado durante años. Por fin se ha restaurado Quel''Delar.' WHERE `ID`=37440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 검이 정말 쿠엘델라입니까?', `MaleText_loc4`='那真的会是奎尔德拉吗？', `MaleText_loc5`='那真的是奎爾德拉嗎?', `MaleText_loc7`='¿De verdad esa es Quel''Delar?' WHERE `ID`=37441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 봅시다.', `MaleText_loc4`='我们会搞清楚的。', `MaleText_loc5`='我們很快就會知道。', `MaleText_loc7`='Ya lo veremos.' WHERE `ID`=37442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 성소를 어지럽혔구나!', `MaleText_loc4`='有人闯进了主人的房间！', `MaleText_loc5`='主人的聖所受到了打擾!', `MaleText_loc7`='El sagrario del maestro ha sido perturbado.' WHERE `ID`=37443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르 님, 보십시오. 쿠엘델라가 분명합니다.', `MaleText_loc4`='洛瑟玛，看那。的确是奎尔德拉。', `MaleText_loc5`='看著它，洛索瑪。這當然是奎爾德拉。', `MaleText_loc7`='¡Mira, Lor''themar! Sin duda es Quel''Delar.' WHERE `ID`=37444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격렬한 싸움이었다, $n! 잠시 숨을 돌리면서 힘을 비축하라. 저 문 뒤에 무엇이 도사리는지 누가 알겠나?$B$B준비가 되면 알려라. 성채의 상층 구역으로 올라가기 시작하겠다.', `MaleText_loc4`='那是一场激烈的战斗，$n！集结部队、重整旗鼓。谁知道在那道门后面等待我们的是什么？$B$B准备好以后告诉我，我们准备向上游攻打敌人的堡垒。', `MaleText_loc5`='真是場激烈的戰鬥，$n!休息一下並且召集你的隊伍。誰知道有什麼等在門後頭?$B$B等你準備好就告訴我，讓我們來前往城塞的更高層。', `MaleText_loc7`='¡Ha sido una batalla encarnizada, $n! Tómate un momento para descansar y recuperarte. ¿Quién sabe que hay tras esa puerta?$B$BAvísame cuando estés $gpreparado:preparada; y comenzaremos nuestro ascenso hacia la parte superior de la ciudadela.' WHERE `ID`=37445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다, 무라딘 님.', `MaleText_loc4`='我们准备好了，穆拉丁。', `MaleText_loc5`='我們準備好了，穆拉丁。', `MaleText_loc7`='Estamos listos, Muradin.', `FemaleText_loc1`='준비되었어요, 무라딘 님.', `FemaleText_loc4`='我们准备好了，穆拉丁。', `FemaleText_loc5`='我們準備好了，穆拉丁。', `FemaleText_loc7`='Estamos listos, Muradin.' WHERE `ID`=37446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실한가? 몇 분 더 필요하지 않겠나?', `MaleText_loc4`='你能肯定吗，$g 伙计:小姑娘;？再给你一两分钟？', `MaleText_loc5`='你確定嗎，$g小夥子:小姑娘;?你不需要再休息個一兩分鐘?', `MaleText_loc7`='¿Estáis seguros? ¿No necesitáis unos minutos más?' WHERE `ID`=37447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다. 지금 가도 좋습니다!', `MaleText_loc4`='确信无疑。出发吧！', `MaleText_loc5`='我們很確定。出發吧!', `MaleText_loc7`='Estamos seguros. ¡Vámonos!', `FemaleText_loc1`='아니에요. 지금 가도 좋아요!', `FemaleText_loc4`='确信无疑。出发吧！', `FemaleText_loc5`='我們很確定。出發吧!', `FemaleText_loc7`='Estamos seguros. ¡Vámonos!' WHERE `ID`=37448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 쿠엘델라가 맞군. 살아서 탈로리엔 돈시커가 지녔던 전설의 검이 우리에게 되돌아오는 날을 맞이하리라고는 생각 못 했소.', `MaleText_loc4`='这的确是奎尔德拉。传说中萨洛瑞安·寻晨者的宝剑又回到我们的手里了，我从没想过我会活着见到这一天。', `MaleText_loc5`='這真的是奎爾德拉。沒想到我能活到這一天，目睹薩洛瑞安·曦尋者的傳奇之劍完整地回到我們手中。', `MaleText_loc7`='Sin duda es Quel''Delar. No pensé que vería el día en que se nos devolvería la espada legendaria de Thalorien Buscalba.' WHERE `ID`=37449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 그대는 영웅이자 신도레이에 본보기가 되는 존재라오. 그런 비극과 배신을 견뎌낸 우리의 상징이오.', `MaleText_loc4`='你是辛多雷的英雄，你鼓舞着我们，$n，在面对悲剧和背叛时一种坚韧的象征。', `MaleText_loc5`='你是個英雄並且激勵了辛多雷，$n，它象徵了我們在面對悲劇與背叛時的堅忍。', `MaleText_loc7`='Eres $gun héroe:una heroína; y una inspiración para los sin''dorei, $n, un símbolo de nuestra resistencia al enfrentarnos a las tragedias y las traiciones.' WHERE `ID`=37450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섭정의 말씀이 사실이오, $n. 탈로리엔의 희생으로도 이 태양샘의 몰락을 막을 수 없었소.', `MaleText_loc4`='摄政者说的对，$n。萨洛瑞安的牺牲无法阻止太阳之井的覆灭。', `MaleText_loc5`='攝政王說得沒錯，$n。薩洛瑞安的犧牲無法避免太陽之井最終的陷落。', `MaleText_loc7`='El Señor regente dice la verdad, $n. El sacrificio de Thalorien no pudo evitar la caída de la mismísima Fuente del Sol.' WHERE `ID`=37451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 저 검을 찾아내었을 때는 부서지고 버려진 상태였소. 마치 캘타스가 배신한 다음의 실버문 같았지.', `MaleText_loc4`='当你找到那把剑时，那把剑已经是残破不堪、无人问津了，更像是被凯尔萨斯出卖了的银月城。', `MaleText_loc5`='當你找到這把劍時，它折毀而且被遺棄，就像是銀月城遭到凱爾薩斯的背叛。', `MaleText_loc7`='Cuando encontraste la espada, estaba rota y abandonada, como Lunargenta tras la traición de Kael''thas.' WHERE `ID`=37452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 포기하지 않는다는 우리의 표상으로 쿠엘델라를 내걸고 어떤 적도 두려움 없이 상대할 것이오.', `MaleText_loc4`='让奎尔德拉成为我们永不言弃的标志，面对敌人我们将不再心存恐惧。', `MaleText_loc5`='讓奎爾德拉成為我們從未放棄的象徵，我們將會無所畏懼地面對任何敵人。', `MaleText_loc7`='¡Que Quel''Delar sea la prueba de que jamás nos rendiremos, de que nos enfrentaremos al enemigo sin miedo!' WHERE `ID`=37453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신도레이만이 쿠엘델라를 추앙한 게 아닙니다. 실버문 자손 모두의 마음속에 자리 잡고 있지요.', `MaleText_loc4`='不仅辛多雷的人十分看重奎尔德拉。它在银月城所有孩子们的心中都占据着一定的位置。', `MaleText_loc5`='奎爾德拉不只是受到辛多雷的推崇。它在所有銀月城子民的心中有著一席之地。', `MaleText_loc7`='No solo los sin''dorei tienen en alta estima Quel''Delar. También tiene un lugar en los corazones de los hijos de Lunargenta.' WHERE `ID`=37454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검이 저희에게 돌아온 건 이유가 있습니다. 이제 쿠엘델라를 든 자를 중심으로 다시 모여 실버문과 태양샘을 파괴한 복수를 해야 할 때가 온 겁니다.', `MaleText_loc4`='出于某种原因，这把剑重新回到了我们手里，我的主人。现在，是紧随奎尔德拉持有者重整旗鼓的时候了，为银月城和太阳之井的毁灭报仇。', `MaleText_loc5`='這把劍回到我們手中是有理由的，大人們。現在正是集結在奎爾德拉持有者的身後，替銀月城和太陽之井的毀壞作出復仇的時刻。', `MaleText_loc7`='Esta espada ha vuelto a nosotros por una razón, mis señores. Ahora es el momento de unirse con el portador de Quel''Delar y vengar la destrucción de Lunargenta y La Fuente del Sol.' WHERE `ID`=37455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검을 집으시오, $n. 그리고 차원문을 타고 달라란으로 가져가시오. 대마법사 에이타스 선리버께서 당신을 치하하려 기다리실 거요.', `MaleText_loc4`='拿回那把剑，$n，带着他穿过传送门前往达拉然。大法师艾萨斯·夺日者正等待着为你喝彩。', `MaleText_loc5`='重新拿起這把劍，$n，帶著它穿過達拉然的傳送門。大法師埃薩·奪日者正等著要恭喜你。', `MaleText_loc7`='Reclama la espada, $n, y llévala a través del portal hasta Dalaran. El archimago Aethas Atracasol estará esperando para felicitarte.' WHERE `ID`=37456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 이동하자! 이동...', `MaleText_loc4`='那我们要行动了，我们要……', `MaleText_loc5`='那我們走吧!快點...', `MaleText_loc7`='¡Entonces, vámonos! ¡Sali...!' WHERE `ID`=37457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이 쓰러뜨린 호드 병사와 쓰러진 얼라이언스 쓰레기 하나하나가 리치 왕의 군대를 더 강대하게 했다. 지금 이 순간도 발키르가 쓰러진 너희 병사를 스컬지로 일으켜 세우지.', `MaleText_loc4`='你每消灭一名部落士兵，或是杀死一只联盟狗。巫妖王的军力就会增长一分。瓦格里正在把你们的阵亡者变为天灾战士。', `MaleText_loc5`='每個你殺死的部落士兵 -- 每條死去的聯盟狗，都讓巫妖王的軍隊隨之增長。此時此刻華爾琪都還在把你們倒下的同伴復活成天譴軍。', `MaleText_loc7`='Por cada soldado de la Horda que mataron... Por cada perro de la Alianza que cayó, el ejército del Rey Exánime creció. Ahora, hasta las Val''kyr alzan a los caídos para la Plaga.' WHERE `ID`=37458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 훨씬 더 나빠지려 하는군. 오너라, 리치 왕께서 내리신 힘을 맛보게 해주마!', `MaleText_loc4`='你们就要大祸临头了。来吧，尝尝巫妖王赐予我的力量吧！', `MaleText_loc5`='事情將會變得更糟糕。來吧，嚐嚐巫妖王他所賜予我的力量!', `MaleText_loc7`='Las cosas se van a poner mucho peor. ¡Vengan, prueben el poder que el Rey Exánime me ha concedido!' WHERE `ID`=37459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 혼자서 얼라이언스의 힘에 맞서겠다고?', `MaleText_loc4`='区区一个兽人竟然想与联盟对抗？？？', `MaleText_loc5`='一個獸人單槍匹馬就想對抗聯盟的力量???', `MaleText_loc7`='¿¿¿Un solo orco contra el poder de la Alianza???' WHERE `ID`=37460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌격!!!', `MaleText_loc4`='冲锋！！！', `MaleText_loc5`='衝啊!!!', `MaleText_loc7`='¡¡¡A la carga!!!' WHERE `ID`=37461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 황폐의 요새라네, $c. 얼라이언스에 반격할 준비가 될 때까지 기회를 노리고 있다네.', `MaleText_loc4`='欢迎来到凄凉要塞，$c。我们在此等待时机，向联盟还以颜色。', `MaleText_loc5`='這裡是荒寂堡，$c。我們在這等待，等待著對聯盟發動反攻。', `MaleText_loc7`='Esto es Bastión de la Desolación, $c. Aquí esperaremos el momento oportuno para contraatacar a la Alianza.' WHERE `ID`=37462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 넘어가지, $c. 대족장께서는 불모의 땅에서 호드의 성과를 높이고자 친히 날 이곳으로 보내셨소. 헌데 도착해보니 마을은 불길에 휩싸여 있고 얼라이언스 놈들이 미친 듯이 날뛰고 있는 게 아니겠소.', `MaleText_loc4`='快一点， $c。酋长亲自派我来评估我们在贫瘠之地的工作进展，然而我却在这里看到我们的城镇燃起大火，联盟败狗肆无忌惮地发狂。', `MaleText_loc5`='長話短說，$c。大酋長親自指名要我來貧瘠之地評估這裡的狀況。我一來，便看見我們的城鎮失火和一堆聯盟狗跑來跑去。', `MaleText_loc7`='Date prisa, $c. El Jefe de Guerra en persona me envió para evaluar nuestro progreso en Los Baldíos, y cuando llego me encuentro nuestras ciudades en llamas y a esos perros de la Alianza campando a sus anchas.' WHERE `ID`=37463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신은 잠재력이 뛰어난 친구요. 이곳 불모의 땅에서 호드가 주도권을 되찾으려면 당신 같은 병사들이 필요하오.', `MaleText_loc4`='你很有潜力，$n。要想重获对贫瘠之地的控制权，就绝对少不了像你这样的精兵。', `MaleText_loc5`='你擁有許多潛力，$n。如果我們想重新在貧瘠之地取得優勢，便需要像你這樣的士兵。', `MaleText_loc7`='Tienes mucho potencial, $n. Si queremos recuperar la iniciativa en Los Baldíos, voy a necesitar soldados como tú.' WHERE `ID`=37464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음 봤을 때부터 용이 벼려낸 검임을 알았습니다.', `MaleText_loc4`='我第一眼看到它，就知道这是一把龙铸之刃。', `MaleText_loc5`='我第一眼看到它就知道這是一把龍族鑄造的武器。', `MaleText_loc7`='Supe que esta era una espada forjada por los dragones cuando la vi por primera vez.' WHERE `ID`=37465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 정말일까요? 이 검이...', `MaleText_loc4`='怎么可能？难道真的……？', `MaleText_loc5`='但這可能嗎?這真的是 --', `MaleText_loc7`='Pero, ¿puede ser? Es realmente...' WHERE `ID`=37466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선봉대의 일원으로 황폐의 요새로 이동할 준비가 되었소, $n?$B$B가르둘이 아마 갖은 핑계를 둘러댈 거요. 그에게 심판의 시간이 다가왔음을 알려 주시오.', `MaleText_loc4`='$n，你是否准备好了作为我的先锋赶赴凄凉要塞？$B$B加杜尔也许想要从你面前蒙混过去。要让他知道，他的审判已经到了。', `MaleText_loc5`='你準備好成為我的先鋒往荒寂堡前進嗎，$n?$B$B迦爾杜爾可能會找藉口，讓他知道他的懲罰即將降臨。', `MaleText_loc7`='¿Ya estás en condiciones de cabalgar hasta Bastión de la Desolación como parte de mi vanguardia, $n?$B$BGar''dul quizá te dé largas. Hazle saber que su juicio se acerca.' WHERE `ID`=37467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈 준비가 됐습니다, 장군님!', `MaleText_loc4`='我准备好了，督军！', `MaleText_loc5`='我準備好了，督軍!', `MaleText_loc7`='¡Estoy listo para ir, jefe de guerra!', `FemaleText_loc1`='갈 준비가 됐습니다, 장군님!', `FemaleText_loc4`='我准备好了，督军！', `FemaleText_loc5`='我準備好了，督軍!', `FemaleText_loc7`='¡Estoy lista para ir, jefe de guerra!' WHERE `ID`=37468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검의 모양이나 무늬는 용이 벼려낸 검임을 암시합니다. 마침내 해답을 얻은 셈이군요.', `MaleText_loc4`='这把剑的形制和铭文表明它是一把龙铸之刃。终于，答案找到了。', `MaleText_loc5`='這把劍的樣式與上頭的印記讓我覺得很可能是龍族鑄造的劍刃。但至少，我們能找出答案。', `MaleText_loc7`='El estilo de esta espada y sus marcas insinuaban que podría haber sido forjada por los dragones. Al fin, tendremos nuestra respuesta.' WHERE `ID`=37469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이토록 오랜 세월 후에, 정말 이 검이...', `MaleText_loc4`='过了这么多年，难道它真的……', `MaleText_loc5`='經過了這麼多年，難道真的 --', `MaleText_loc7`='Después de tantos años, ¿puede ser...?' WHERE `ID`=37470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 놈들...', `MaleText_loc4`='矮人……', `MaleText_loc5`='矮人...', `MaleText_loc7`='Enanos...' WHERE `ID`=37471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드힐트 장군님의 명으로 이곳에 왔습니다. 그분께서 곧 도착한다고 알리라 하셨습니다.', `MaleText_loc4`='我代表血柄督军前来通知你，他很快就到。', `MaleText_loc5`='我在這代表了督軍血柄，他要你們知道他很快就會到這了。', `MaleText_loc7`='Estoy aquí en nombre del señor de la guerra Sangrastil. Desea que sepas que llegará en breve.', `FemaleText_loc1`='블러드힐트 장군님의 명으로 이곳에 왔습니다. 그분께서 곧 도착한다고 알리라 하셨습니다.', `FemaleText_loc4`='我代表血柄督军前来通知你，他很快就到。', `FemaleText_loc5`='我在這代表了督軍血柄，他要你們知道他很快就會到這了。', `FemaleText_loc7`='Estoy aquí en nombre del señor de la guerra Sangrastil. Desea que sepas que llegará en breve.' WHERE `ID`=37472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 블러드힐트? 가로쉬의 졸개 말인가?$B$B그가 여기에 올 이유가 없는데. 보다시피, 어, 여기 상황은 내가 잘 통제하고 있다 전하게.', `MaleText_loc4`='血柄督军？加尔鲁什的狗腿子？$B$B正如你看到的，这儿不需要他——啊，告诉他这里的一切状况都在我的掌握之中。', `MaleText_loc5`='督軍血柄?卡爾洛斯的寵物?$B$B如你所見，這裡不需要他在這，跟他說一切都在我的掌握之中。', `MaleText_loc7`='¿El señor de la guerra Sangrastil? ¿La mascota de Garrosh?$B$BComo puedes ver, no hace falta que venga hasta aquí. Eh, dile que tenemos la situación controlada.' WHERE `ID`=37473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우라조 피난민들에게 그 말을 반드시 전해 드리죠. 이미 많은 분들이 세상을 떠났지만요.', `MaleText_loc4`='我一定会告诉那些陶拉祖难民的。告诉那些活下来的。', `MaleText_loc5`='我會通知陶拉祖的難民的，那些活下來的人。', `MaleText_loc7`='Me aseguraré de decírselo a los refugiados de Taurajo. A los que han sobrevivido.', `FemaleText_loc1`='타우라조 피난민들에게 그 말을 반드시 전해 드리죠. 이미 많은 분들이 세상을 떠났지만요.', `FemaleText_loc4`='我一定会告诉那些陶拉祖难民的。告诉那些活下来的。', `FemaleText_loc5`='我會通知陶拉祖的難民的，那些活下來的人。', `FemaleText_loc7`='Me aseguraré de decírselo a los refugiados de Taurajo. A los que han sobrevivido.' WHERE `ID`=37474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 어, 그땐 보급품이 부족했네. 음, 사람 수도 부족하고 말이지. 블러드힐트에게, 어...', `MaleText_loc4`='但是，啊，目前的供给非常紧张。而且，呃，我这里的人力也很短缺。告诉血柄，啊-', `MaleText_loc5`='但是，嗯...補給很吃緊。我...呃...這的人手不足。告訴血柄說...嗯...', `MaleText_loc7`='Pero, eh, los suministros escasean. No tengo, eh, suficientes hombres. Díselo a Sangrastil, dile, eh...' WHERE `ID`=37475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 말하시죠. 거의 다 왔을 겁니다!', `MaleText_loc4`='你亲口告诉他吧。他就快到了！', `MaleText_loc5`='你自己跟他說。他快到了!', `MaleText_loc7`='Díselo tú. ¡Ya casi está aquí!', `FemaleText_loc1`='직접 말하시죠. 거의 다 왔을 겁니다!', `FemaleText_loc4`='你亲口告诉他吧。他就快到了！', `FemaleText_loc5`='你自己跟他說。他快到了!', `FemaleText_loc7`='Díselo tú. ¡Ya casi está aquí!' WHERE `ID`=37476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 나는... 해방되었다...', `MaleText_loc4`='我……终于……解脱了……', `MaleText_loc5`='我...終於...解脫了...', `MaleText_loc7`='Es... toy... libre…' WHERE `ID`=37477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리 여왕은 사라졌군요. 우리는... 우리는 계속 가야 해요. 목표가 멀지 않았어요.', `FemaleText_loc4`='冰霜女王飞走了。我们……我们必须继续前进——目标就在眼前。', `FemaleText_loc5`='冰霜之后已經離開了。我們必須繼續前進 - 目標不遠了。', `FemaleText_loc7`='La Reina de Escarcha se ha ido. Debemos... Debemos seguir adelante. Nuestro objetivo está cerca.' WHERE `ID`=37478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅들이여, 이리로!', `FemaleText_loc4`='英雄们，到我这来！', `FemaleText_loc5`='英雄們，到這來!', `FemaleText_loc7`='¡Héroes, vengan a mí!' WHERE `ID`=37479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저... 저들을 구하지 못했어... 저주하겠어, 아서스! 저주해!', `FemaleText_loc4`='我……我救不了他们……该死，阿尔萨斯！你这恶魔！', `FemaleText_loc5`='我...我沒辦法救他們...該死，阿薩斯!你真該死!', `FemaleText_loc7`='No... pude salvarlos... ¡Maldito seas, Arthas! ¡MALDITO SEAS!' WHERE `ID`=37480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 끌지 말자고. 그가, 어, 곧 올테니!$B$B난 북쪽 탑의 맨 꼭대기에 가 있겠네.', `MaleText_loc4`='不要再耽搁了，他——啊——他就快到了！$B$B到最北边塔的塔顶找我', `MaleText_loc5`='別耽誤了，他...阿...他就快到了!$B$B我們在最北方的塔上見。', `MaleText_loc7`='¡No te retrases, él, eh... eh... casi está aquí!$B$BReúnete conmigo en lo alto de la torre que se alza más al norte.' WHERE `ID`=37481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 자네가, 어, 이 문제에 관해서는 내 권위를 존중해줄 거라 믿네.', `MaleText_loc4`='谢谢你，$n。我相信你一定会，啊，维护我的权力。', `MaleText_loc5`='謝謝你，$n。我相信你會...嗯...在這個狀況下服從我的命令。', `MaleText_loc7`='Gracias, $n. Confío en que, eh, apoyes mi autoridad en este tema.' WHERE `ID`=37482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 필요한 게 뭡니까?$b$b스톰윈드가 정령에 포위됐단 말입니다! 도시 대부분이 이미 피난을 떠났고 경비병들이 정령들이 접근하지 못하도록 막고 있습니다.$b$b안전한 곳으로 몸을 피하십시오. 지금은 도시를 방어하면서 당신까지 살펴줄 여력이 없습니다.', `MaleText_loc4`='你需要什么，$c？暴风城已经被元素团团包围了！我们已经护送撤离了大部分市民，我们的卫兵正在奋力将元素阻绝在城门之外。$b$b你最好自己找个安全的地方待着。我们没工夫一边守城一边还要替你担心。', `MaleText_loc5`='你想要什麼，$c?$B$B暴風城被元素們所包圍了!我們疏散了城中大部份的人，守衛們正奮力地對抗那些元素。$b$b我建議你到安全的地方去。保護這座城已經很難了，我們沒有多餘的人手來管你。', `MaleText_loc7`='¿Qué necesitas, $c?$b$b¡Ventormenta está bajo asedio de los elementales! Hemos evacuado la mayor parte de la ciudad y nuestros guardias luchan para mantener a raya a los elementales.$b$bTe sugiero que te dirijas a una zona más segura. No tenemos hombres suficientes para proteger la ciudad y además preocuparnos por ti.' WHERE `ID`=37483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쿠엘델라다.', `FemaleText_loc4`='奎尔德拉。', `FemaleText_loc5`='奎爾德拉。', `FemaleText_loc7`='Quel''Delar.' WHERE `ID`=37484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용이 벼려낸 쿠엘세라는 칼도레이가 받았고, 그 쌍둥이 검인 쿠엘델라는 우리 종족이 받았다.', `FemaleText_loc4`='巨龙铸造出奎尔塞拉，送给了卡多雷；而将奎尔德拉，送给了我们。', `FemaleText_loc5`='就像是奎爾賽拉由龍族所鑄造並賜予卡多雷，跟它是一對的，就是奎爾德拉，賜給了我族。', `FemaleText_loc7`='Quel''Serrar fue forjada por los dragones y otorgada a los kaldorei, mientras que su gemela, Quel''Delar, fue entregada a mi pueblo.' WHERE `ID`=37485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왕께서 그 검을 내 친구, 탈로리엔 돈시커에게 하사하셨지.', `FemaleText_loc4`='国王将它赠予了我的朋友，萨洛瑞安·寻晨者。', `FemaleText_loc5`='國王將這把劍賜給了我的朋友，薩洛瑞安·曦尋者。', `FemaleText_loc7`='El Rey confirió la espada a mi amigo, Thalorien Buscalba.' WHERE `ID`=37486;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만, 탈로리엔의 능력이나 쿠엘델라의 마력으로도 스컬지로부터 실버문은 지키지 못했다.', `FemaleText_loc4`='但即使是萨洛瑞安的力量和奎尔德拉的魔力也无法从天灾手中拯救银月城。', `FemaleText_loc5`='但就算靠著薩洛瑞安的劍技和奎爾德拉的魔法也無法從天譴軍的手中拯救銀月城。', `FemaleText_loc7`='Pero ni la habilidad de Thalorien ni la magia de Quel''Delar pudieron salvar a Lunargenta del poder de la Plaga.' WHERE `ID`=37487;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈로리엔은 다른 이들이 탈출할 시간을 벌다 태양샘으로 가는 길목에 쓰러졌지.', `FemaleText_loc4`='为掩护族人逃生，萨洛瑞安在太阳之井的大门前壮烈牺牲。', `FemaleText_loc5`='薩洛瑞安在太陽之井門前倒下，但爭取了時間讓其他人可以逃脫。', `FemaleText_loc7`='Thalorien cayó a las puertas de La Fuente del Sol, ganando tiempo para que los demás escaparan.' WHERE `ID`=37488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 일로도 다시 이 칼을 잡는 일은 없을 것이라고 다짐했었지.$B$B내가 바보였네.', `MaleText_loc4`='我曾经发过誓，再没有任何东西能让我重新拿起这把剑了。$B$B我是个傻瓜。', `MaleText_loc5`='我曾發誓沒什麼可以再讓我把這把武器拿起來了。$B$B我那時真是個白癡。', `MaleText_loc7`='Juré que nada haría que volviera a tomar esta espada.$B$BFui un estúpido.' WHERE `ID`=37489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 전투 후에, 전장에서 검을 찾아냈다. 그리고 왕자님을 모시고 그 검을 노스렌드로 가져갔지. 우리 종족의 패배를 설욕하려 말이다.', `FemaleText_loc4`='战后，我从战场上找回这把剑，为了我的王子，为了替我的族人复仇，我把它带到了诺森德。', `FemaleText_loc5`='在戰鬥結束後，我從戰場上找回了那把劍。我在追隨王子時把劍帶到了北裂境，希望能夠替我們族人的失敗報仇。', `FemaleText_loc7`='Tras la batalla, recuperé la espada. La llevé hasta Rasganorte al servicio de mi Príncipe, buscando vengar la caída de nuestra gente.' WHERE `ID`=37490;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 병력을 조각낸 아서스는 가장 강력한 이들을 산레인으로 받아들여 자신을 섬기게 했다.', `FemaleText_loc4`='阿尔萨斯粉碎了我们，将我们最强大的战士变成他的爪牙，萨莱因。', `FemaleText_loc5`='阿薩斯擊潰了我們的部隊，把我們之中最強大的人帶走，以煞婪一族的形式服侍他。', `FemaleText_loc7`='Arthas destruyó nuestras fuerzas y convirtió a los más fuertes de nosotros en los San''layn.' WHERE `ID`=37491;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈로리엔에 대한 내 기억은 차갑게 식었고, 그의 검도 식어버렸다.', `FemaleText_loc4`='对萨洛瑞安的回忆已和他的剑一样冰冷。', `FemaleText_loc5`='我對薩洛瑞安的記憶日漸冰冷，而他的劍也一樣。', `FemaleText_loc7`='Mis recuerdos de Thalorien y su espada se enfriaron.' WHERE `ID`=37492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쿠엘델라를 만든 이에게 돌려주고자 여기로 가져온 것이 바로 나였다. 이 검을 깨뜨리면서, 그 힘도 깨뜨렸지.', `FemaleText_loc4`='是我将奎尔德拉带来，交给它的铸造者，只为打碎这把武器，消除它的力量。', `FemaleText_loc5`='是我把奎爾德拉帶到這裡，把它歸還給它的鑄造者。而破壞這把劍，我也破壞了它的力量。', `FemaleText_loc7`='Fui yo la que trajo a Quel''Delar aquí, para devolvérsela a sus creadores. Al romper el arma, también rompí su poder.' WHERE `ID`=37493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쿠엘델라는 결코 다른 이를 섬기지 않는다!', `FemaleText_loc4`='奎尔德拉只能有一个主人！', `FemaleText_loc5`='奎爾德拉將永不服侍別人!', `FemaleText_loc7`='¡Quel''Delar no servirá a nadie más!' WHERE `ID`=37494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에 숨어 있었군, 가르둘.', `MaleText_loc4`='原来你躲在这儿了，加杜尔。', `MaleText_loc5`='原來你躲在這啊，迦爾杜爾。', `MaleText_loc7`='Así que ahí era donde te escondías, Gar''dul.' WHERE `ID`=37495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 숨기만 하는 겁쟁이 같으니! $n|1이;가; 여기 없었으면 얼라이언스가 멀고어까지 진군할 뻔했다.', `MaleText_loc4`='你这个只会躲在墙后的懦夫！要不是有$n在，联盟早就杀进莫高雷了。', `MaleText_loc5`='你就打算像個懦夫躲在這!如果不是$n，聯盟現在已經在往莫高雷前進了。', `MaleText_loc7`='¡Puedes esconderte detrás de tus murallas! Si $n no hubiera estado aquí, la Alianza marcharía ya por Mulgore.' WHERE `ID`=37496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 변명엔 이제 신물이 나는구나! 지휘 임무에서 해방됐다 생각해라.', `MaleText_loc4`='你的借口令我恶心！你的指挥权被解除了。', `MaleText_loc5`='你的藉口讓我噁心!', `MaleText_loc7`='¡Tus excusas me ponen enfermo! Considérate relevado del mando.' WHERE `ID`=37497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 주제에 자존심은 남았나 보군!', `MaleText_loc4`='噢！你还有点儿骨气！', `MaleText_loc5`='所以你還是有勇氣的!', `MaleText_loc7`='¡Vaya! ¡Así que SÍ que tienes valor!' WHERE `ID`=37498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨었다고? 이봐라, 블러드힐트 나는, 어, 불모의 땅에서 열심히 버텼다.', `MaleText_loc4`='躲？听着血柄——我已经，啊，加强了对贫瘠之地的控制。', `MaleText_loc5`='躲藏?聽著，血柄，我...呃...穩固了我們在貧瘠之地的控制。', `MaleText_loc7`='¿Escondiéndome? Escucha Sangrastil, yo, eh, he reforzado nuestro poder en Los Baldíos.' WHERE `ID`=37499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 저들이, 어, 지원군을 데려왔다고! 동부 왕국에서 말이다. 반면에 나는, 어, 지원도 끊기고...', `MaleText_loc4`='但他们，呃，他们得到了援军！东部王国来的援军。然而我的部队却，呃，被包围了-', `MaleText_loc5`='但他們...呃...他們有增援!從東部王國來的。而我呢...呃...我有其他的事...', `MaleText_loc7`='¡Pero ellos, eh, han recibido refuerzos! De los Reinos del Este. Mientras tanto, a nosotros, eh, nos ha recortado...' WHERE `ID`=37500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해방이라고? 내 눈에 흙이 들어가기 전엔 안 돼!', `MaleText_loc4`='解除指挥权？除非从我的尸体上碾过去！', `MaleText_loc5`='解除職位?你先殺了我吧!', `MaleText_loc7`='¿Relevado? ¡Por encima de mi cadáver!' WHERE `ID`=37501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 막혔던 숨을 들이쉽니다.', `MaleText_loc4`='%s气喘吁吁。', `MaleText_loc5`='%s氣喘吁吁。', `MaleText_loc7`='%s da una bocanada.' WHERE `ID`=37502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 사울팽의 아들이다. 분노의 관문에서 호드를 지휘했던 자이지. 정말 비참한 최후로군...', `MaleText_loc4`='这就是萨鲁法尔的儿子——部落在天谴之门的指挥官。真是个悲剧……', `MaleText_loc5`='那是薩魯法爾的兒子 - 部落在憤怒之門的指揮官。多悲傷的結局...', `MaleText_loc7`='Ese era el hijo de Colmillosauro, el comandante de la Horda en la Puerta de Cólera. Un trágico final...' WHERE `ID`=37503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 뭐지? 저기, 멀리 말이다!', `MaleText_loc4`='远处那里……那里是什么！', `MaleText_loc5`='那裡面是什麼...那邊，靠近了!', `MaleText_loc7`='¿Qué dem...? ¡Allí, a lo lejos!' WHERE `ID`=37504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여, 집합하라! 호드가 한 번 더 공격하러 오는 듯하다!', `MaleText_loc4`='士兵们，集合！看样子部落马上又要射击了！', `MaleText_loc5`='士兵們，列隊!看來部落打算再試一次!', `MaleText_loc7`='¡Soldados, en formación! Parece que la Horda viene de nuevo.' WHERE `ID`=37505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 예상대로군...', `MaleText_loc4`='不出所料……', `MaleText_loc5`='多容易預料...', `MaleText_loc7`='Tan predecible...' WHERE `ID`=37506;
