UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기까지 오다니 너무나 어리석구나. 노스렌드의 얼음 바람이 영혼까지 삼키리라!', `FemaleText_loc4`='你们这些蠢货胆敢闯入这里。诺森德的冰风将卷走你们的灵魂！', `FemaleText_loc5`='你們真是夠蠢了才會來到此地。北裂境的冰冷寒風將吞噬你們的靈魂!', `FemaleText_loc7`='Están locos por haber venido a este lugar. ¡Los vientos helados de Rasganorte consumirán sus almas!' WHERE `ID`=37511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 성공이다!', `MaleText_loc4`='这次我成功了！', `MaleText_loc5`='這次是我贏了!', `MaleText_loc7`='¡Esta vez ya lo tengo!' WHERE `ID`=37512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽으며 내지르는 고함이 울려 퍼집니다.', `MaleText_loc4`='%s临死前的哀号响彻云霄。', `MaleText_loc5`='%s垂死的哭吼反覆迴盪。', `MaleText_loc7`='%s emite un rugido aterrador al morir.' WHERE `ID`=37513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠엘델라가 선리버를 위해 복원되도록 하는 일은 우리 손에 달렸습니다.', `MaleText_loc4`='见证逐日者夺回奎尔德拉是我们的使命。', `MaleText_loc5`='讓奎爾德拉復原並回到奪日者之手是我們的責任。', `MaleText_loc7`='Es nuestro deber ver que Quel''Delar se restaura para los Atracasol.' WHERE `ID`=37514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려... 어, 잠깐! 항복할게. 항복한다고!', `MaleText_loc4`='等等，啊……等等！我认输，我认输！', `MaleText_loc5`='等...啊..等一下!我投降。我投降!', `MaleText_loc7`='¡Espera, eh... espera! Me rindo. Me rindo.' WHERE `ID`=37515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐...? 항복한다고?', `MaleText_loc4`='认输？你……认输？', `MaleText_loc5`='投降?你...投降?', `MaleText_loc7`='¿Te rindes? Tú... ¿te RINDES?' WHERE `ID`=37516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 "승리가 아니면 죽음을"이란 말도 모르나?!', `MaleText_loc4`='非胜即死，你还有什么不明白的？赶紧给我从这里消失吧！', `MaleText_loc5`='「不勝即亡」，這句話你不懂嗎!?', `MaleText_loc7`='¡¿Qué parte de "victoria o muerte" es la que no entiendes?!' WHERE `ID`=37517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 은빛 서약단에 복원된 쿠엘델라를 가져다주겠다고 맹세한다.', `MaleText_loc4`='我发誓，银色盟约终将迎来奎尔德拉的回归。', `MaleText_loc5`='我發誓會讓白銀誓盟看到奎爾德拉回復原狀。', `MaleText_loc7`='Juro que El Pacto de Plata verá a Quel''Delar restaurada.' WHERE `ID`=37518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여깁니다. 한때 커다란 비극이 벌어진 곳임을 느낄 수 있습니다. 아직도 극심한 고통이 저 안에서 메아리치는군요. 저 너머의 공포가 이곳을 지배한 것이 분명합니다.$B$B이 세상으로의 침입을 완전히 막아내려면, 먼저 완전히 열어야 합니다. 이곳으로 오려는 존재를 저지하는 데 당신의 힘이 필요할 듯하군요.$B$B준비는 되셨습니까?', `MaleText_loc4`='就是这里。我能感觉到这就是发生那场大悲剧的地方。痛苦的嚎叫仿佛仍然在这里回荡。毫无疑问，这就是那些异界的恐怖曾经肆虐横行的地方。$B$B为了能彻底将那些异界怪物入侵这个世界的道路封死，我必须先将它完全打开。那时，我需要你的力量来挡住可能从其中出来的一切东西。$B$B你准备好了吗？', `MaleText_loc5`='就是這。我可以感覺到這裡曾發生了大慘劇:我仍可聽到凡人受苦的回音。這一定是無上的恐懼所凝聚的結果。$B$B如要完全封印這個入侵至我們的世界，我必須先把它完全打開。我需要你的力量，在過程中擊退任何想要穿越過來的東西。$B$B準備好了嗎?', `MaleText_loc7`='Aquí es. Percibo que este es el lugar donde una vez se desató una gran tragedia. El sufrimiento mortal todavía tiene aquí su eco. No me cabe duda de que los horrores de más allá aprovecharon para entrar por aquí.$B$BPara erradicar totalmente esta intrusión de nuestro mundo, primero debo abrir la brecha por completo. Necesitaré tu ayuda para mantener a raya cualquier intento de cruzar.$B$B¿Empezamos ya?' WHERE `ID`=37519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 나랄렉스.', `MaleText_loc4`='准备好了，纳拉雷克斯。', `MaleText_loc5`='我準備好了，納拉雷克斯。', `MaleText_loc7`='Estoy preparado, Naralex.', `FemaleText_loc1`='준비됐습니다, 나랄렉스.', `FemaleText_loc4`='准备好了，纳拉雷克斯。', `FemaleText_loc5`='我準備好了，納拉雷克斯。', `FemaleText_loc7`='Estoy preparada, Naralex.' WHERE `ID`=37520;
