UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님의 호드는 실패를 용납하지 않는다.', `MaleText_loc4`='加尔鲁什的部落不会容忍失败。', `MaleText_loc5`='卡爾洛斯的部落是不允許失敗的。', `MaleText_loc7`='La Horda de Garrosh no tolera el fracaso.' WHERE `ID`=37522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아래쪽에서 만나 이후 반격 계획을 논의하지.', `MaleText_loc4`='到下面去找我，我们会认真谈一谈即将到来的反击。', `MaleText_loc5`='你可以在下面找到我，我們能商量一下之後的反擊。', `MaleText_loc7`='Reúnete conmigo abajo y hablaremos de nuestro contraataque.' WHERE `ID`=37523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크, 나를 맘대로 움직일 수 없다. 지나가지 못한다.', `MaleText_loc4`='别逼我，兽人。我不能让你过去。', `MaleText_loc5`='別逼我動手，獸人。我們不能讓你通過。', `MaleText_loc7`='No me fuerces a actuar, orco. No podemos dejarte pasar.' WHERE `ID`=37524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 네 뒤에 내 외아들이 있다. 아무것도 나를 막지 못한다.', `MaleText_loc4`='躺在那里的是我唯一的儿子。无论什么也不能把我和他分离。', `MaleText_loc5`='在你身後躺著我唯一的兒子。沒有任何事能阻擋我去找他。', `MaleText_loc7`='Detrás de ti está el cuerpo de mi único hijo. Nada me alejará de él.' WHERE `ID`=37525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 그렇게는 못한다. 함선으로 돌아가면 목숨은 부지시켜주마.', `MaleText_loc4`='我，我不能这样做。回到船上去，我就饶你一命。', `MaleText_loc5`='我...我辦不到。回到你的船上去，我們就饒你一命。', `MaleText_loc7`='No... No puedo hacerlo. Vuelve a tu nave y te perdonaré la vida.' WHERE `ID`=37526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나시오, 무라딘. 슬픔에 잠긴 아버지 아니오.', `MaleText_loc4`='退后，穆拉丁，让这位伤心的父亲过去。', `MaleText_loc5`='退下，穆拉丁。讓這個悲傷的父親過去。', `MaleText_loc7`='Apártate, Muradin. Abre paso a un padre en duelo.' WHERE `ID`=37527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 번개의 축복을.', `MaleText_loc4`='Blood and thunder, my son.', `MaleText_loc5`='鮮血與雷霆，吾兒。', `MaleText_loc7`='Blood and thunder, my son.' WHERE `ID`=37528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배려는... 잊지 않겠소... 왕이여, 고맙소.', `MaleText_loc4`='我不会忘记您的……仁慈。感谢您，殿下。', `MaleText_loc5`='我不會忘記這樣的...仁慈。我感謝你，陛下。', `MaleText_loc7`='No olvidaré esta... amabilidad. Le agradezco, Alteza.' WHERE `ID`=37529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 분노의 관문에 없었지만, 살아남은 병사들이 많은 이야기를 전해주었다. 그대의 아들은 명예롭게 싸웠고 영웅답게 전사했다. 그러니 영웅답게 묻힐 자격이 있다.', `MaleText_loc4`='我……那时不在天谴之门。但活下来的士兵告诉了我当时的情况。你的儿子为荣耀而战，他英勇地战死，应该得到英雄般的厚葬。', `MaleText_loc5`='我...那時並不在憤怒之門，但倖存的士兵告訴我事情發生的經過。你的兒子英勇而光榮地作戰。他死得像個英雄，也值得一個英雄的葬禮。', `MaleText_loc7`='Yo... Yo no estuve en la Puerta de Cólera, pero los soldados que sobrevivieron me contaron lo que ocurrió. Tu hijo luchó con honor. Murió como un héroe. Se merece un entierro de héroe.' WHERE `ID`=37530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点头。', `MaleText_loc5`='%s點點頭。', `MaleText_loc7`='%s asiente.' WHERE `ID`=37531;
