UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지를 상대하는 이 전쟁에서 큰일을 하셨습니다. 빛의 가호가 있기를.', `MaleText_loc4`='你在与天灾的战争中立下了大功。愿圣光给你恩泽。', `MaleText_loc5`='你在對抗天譴軍團的戰爭中付出夠多了。願聖光擁抱你。', `MaleText_loc7`='Has hecho mucho durante esta guerra contra la Plaga. Que la Luz te envuelva.' WHERE `ID`=37533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료의 죽음은 막을 수 없었습니다. 그들은 은빛십자군의 이름으로 살다 죽었습니다.', `MaleText_loc4`='战斗难免牺牲，而我们的战友无论生死，都会效忠银色北伐军。', `MaleText_loc5`='我們同志的損失是無可避免的。他們的生與死全都是為了銀白十字軍。', `MaleText_loc7`='La pérdida de nuestros camaradas fue inevitable. Vivieron y murieron al servicio de la Cruzada Argenta.' WHERE `ID`=37534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부정한 장소를 무엇으로 정화할 수 있겠나? 고맙네.', `MaleText_loc4`='拯救这个邪恶之地非你莫属，谢谢你。', `MaleText_loc5`='這塊穢邪之地真的能獲得救贖嗎?感謝你。', `MaleText_loc7`='¿Qué puede purificar este lugar profano? Gracias.' WHERE `ID`=37535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험이 도사리고 있음을 명심하게... 그리고 뻥 터지지 않도록 조심해.', `MaleText_loc4`='小心前面潜伏的危险……就是死也要留个全尸。', `MaleText_loc5`='當心前頭的危險...然後盡量保住自己的小命。', `MaleText_loc7`='Cuidado con los peligros más adelante... e intenten seguir enteros.' WHERE `ID`=37536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 장치 가동!', `MaleText_loc4`='火箭背包启动！', `MaleText_loc5`='火箭包啟動!', `MaleText_loc7`='¡Paquete de cohetes activo!', `FemaleText_loc1`='로켓 장치 가동!', `FemaleText_loc4`='火箭背包启动！', `FemaleText_loc5`='火箭包啟動!', `FemaleText_loc7`='¡Paquete de cohetes activo!' WHERE `ID`=37537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 장치 작동 중지. 장치를 다시 가동하려면 자포드 붐박스 근처로 가십시오.', `MaleText_loc4`='火箭背包已关闭。移至扎福德·波姆布克斯旁边以重新启动。', `MaleText_loc5`='火箭包關閉。靠近札弗德·轟箱以重新啟動。', `MaleText_loc7`='Paquete de cohetes desactivado. Acércate más a Zafod Transistor para reactivarlo.', `FemaleText_loc1`='로켓 장치 작동 중지. 장치를 다시 가동하려면 자포드 붐박스 근처로 가십시오.', `FemaleText_loc4`='火箭背包已关闭。移至扎福德·波姆布克斯旁边以重新启动。', `FemaleText_loc5`='火箭包關閉。靠近札弗德·轟箱以重新啟動。', `FemaleText_loc7`='Paquete de cohetes desactivado. Acércate más a Zafod Transistor para reactivarlo.' WHERE `ID`=37538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로보스, 당신은 실라스 동물원에 있는 편이 훨씬 더 어울립니다.', `MaleText_loc4`='你在希拉斯的动物园里将成为一件精彩的展品，鲁博斯。', `MaleText_loc5`='希拉斯的動物馬戲團會很歡迎你加入的，羅勃斯。', `MaleText_loc7`='Vas a ser una gran novedad en el arca de Silas, Lobos.' WHERE `ID`=37539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 뒤에 숨어라! 어서!', `FemaleText_loc4`='躲到我后面来！快！', `FemaleText_loc5`='在我身後尋找掩蔽!快!', `FemaleText_loc7`='¡Cúbranse detrás de mí! ¡Rápido!' WHERE `ID`=37540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원히 입을 다물지 않을 놈이라고 생각했다. 마침내 그 입을 신드라고사가 막았구나. 영웅들이여, 투영의 전당으로 향하라! 목표가 가까이 있음이... 느껴진다.', `FemaleText_loc4`='我以为他永远都闭不上嘴。但辛达苟萨让这个呱噪的家伙安静下来了。勇士们，向映像大厅前进！我能感觉到……目标已近。', `FemaleText_loc5`='我以為他永遠不會閉嘴。總算，辛德拉苟莎讓那個嘮叨的笨蛋安靜了。前往倒影大廳，勇士們!我們的目標靠近了...我可以感覺得到。', `FemaleText_loc7`='Pensé que nunca se callaría. Por fin, Sindragosa silenció a ese loco impertinente. ¡A las Cámaras de Reflexión, campeones! Nuestro objetivo está cerca... Lo presiento.' WHERE `ID`=37541;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 울음을 터뜨립니다.', `FemaleText_loc4`='%s哭了起来。', `FemaleText_loc5`='%s流下眼淚。', `FemaleText_loc7`='%s llora.' WHERE `ID`=37542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나? 왜 우는 것이오?', `MaleText_loc4`='吉安娜，你怎么哭了？', `MaleText_loc5`='珍娜?你為什麼在哭?', `MaleText_loc7`='¿Jaina? ¿Por qué lloras?' WHERE `ID`=37543;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 눈물을 닦아내고 국왕 바리안 린에게 미소를 짓습니다.', `FemaleText_loc4`='%s擦干眼泪，朝着瓦里安·乌瑞恩国王笑了笑。', `FemaleText_loc5`='%s擦去眼淚，然後對著瓦里安·烏瑞恩國王微笑。', `FemaleText_loc7`='%s se limpia las lágrimas y sonríe al rey Varian Wrynn.' WHERE `ID`=37544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 무라딘! 갑판을 정리하고 위쪽 성채를 공격할 수 있도록 병사들을 준비하시오. 스톰윈드에서 병력을 더 보내겠소.', `MaleText_loc4`='穆拉丁，守住甲板，组织士兵向城堡上层发动进攻。我会带另一支暴风城部队过去。', `MaleText_loc5`='哼!穆拉丁，守住甲板並且讓士兵準備攻擊城塞的上層。我會從暴風城派出另一批援軍。', `MaleText_loc7`='¡Bah! Muradin, asegura la cubierta y prepara a los soldados para un asalto a la parte superior de la Ciudadela. Enviaré otro regimiento desde Ventormenta.' WHERE `ID`=37545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무것도 아니에요, 폐하. 그저... 폐하가 자랑스러워서요.', `FemaleText_loc4`='没什么，陛下……我只是，为国王而自豪。', `FemaleText_loc5`='沒什麼，陛下。只是...我只是替吾王感到驕傲。', `FemaleText_loc7`='No es nada, majestad. Es que... estoy orgullosa de mi rey.' WHERE `ID`=37546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리하지요, 폐하!', `MaleText_loc4`='这就去，陛下！', `MaleText_loc5`='立刻就辦，陛下!', `MaleText_loc7`='¡De inmediato, su majestad!' WHERE `ID`=37547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 별로 없다, $c|1이여;여;. 왜 여기서 지체하는 것이냐?', `FemaleText_loc4`='我们没有时间可以浪费了，$c。为什么你在这停了下来？', `FemaleText_loc5`='我們沒有時間可以浪費了，$c。你還杵在這裡做什麼?', `FemaleText_loc7`='No tenemos tiempo que perder, $c. ¿Qué haces aún aquí?' WHERE `ID`=37548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 무엇을 원하십니까, 밴시 여왕님?', `MaleText_loc4`='有什么我能效劳的，女妖之王？', `MaleText_loc5`='你希望我怎麼做，女妖之王?', `MaleText_loc7`='¿Qué quieres de mí, Reina alma en pena?', `FemaleText_loc1`='제게 무엇을 원하십니까, 밴시 여왕님?', `FemaleText_loc4`='有什么我能效劳的，女妖之王？', `FemaleText_loc5`='你希望我怎麼做，女妖之王?', `FemaleText_loc7`='¿Qué quieres de mí, Reina alma en pena?' WHERE `ID`=37549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 별로 없어요, 영웅들이여. 무슨 일이죠?', `FemaleText_loc4`='我们时间不多了，英雄。你需要些什么？', `FemaleText_loc5`='我們時間不多了，英雄。你需要什麼?', `FemaleText_loc7`='No tenemos mucho tiempo, $ghéroe:heroína;. ¿Qué necesitas?' WHERE `ID`=37550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 무엇을 원하십니까, 여군주님?', `MaleText_loc4`='有什么我能效劳的，我的女士？', `MaleText_loc5`='你希望我怎麼做，我的女士?', `MaleText_loc7`='¿Qué quieres de mí, mi señora?', `FemaleText_loc1`='제게 무엇을 원하십니까, 여군주님?', `FemaleText_loc4`='有什么我能效劳的，我的女士？', `FemaleText_loc5`='你希望我怎麼做，我的女士?', `FemaleText_loc7`='¿Qué quieres de mí, mi señora?' WHERE `ID`=37551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법학자 하소렐 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라더군요.', `MaleText_loc4`='魔导师哈瑟尔说你会借我一件战袍。', `MaleText_loc5`='博學者哈索瑞爾說你或許能借我一件外袍?', `MaleText_loc7`='Magister Hathorel me ha dicho que quizá podrías prestarme cierto tabardo.', `FemaleText_loc1`='마법학자 하소렐 님 말로는 당신이 제게 휘장을 빌려줄 수 있을 거라던데요.', `FemaleText_loc4`='魔导师哈瑟尔说你会借我一件战袍。', `FemaleText_loc5`='博學者哈索瑞爾說你或許能借我一件外袍?', `FemaleText_loc7`='Magister Hathorel me ha dicho que quizá podrías prestarme cierto tabardo.' WHERE `ID`=37552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 문을 열려고 최고의 실력을 지닌 노움들을 데려왔다네, $n! 추측건대 $4939W일 정도 더 있어야 문을 열 수 있을 걸세!', `MaleText_loc4`='我派出了我们最强干的侏儒来对付这些大门，$n！根据他们的计算，打开那道大门还需要$4939W天！', `MaleText_loc5`='我可是派出我們最棒的地精才打開這些門，$n!他們估計這還需要$4939W天才能搞定那扇門!', `MaleText_loc7`='He traído a los mejores gnomos que tenemos para abrir estas puertas, $n. Creen que van a tardar $4939W días más en derribarlas.' WHERE `ID`=37553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<로켓을 보고는 신경질적으로 미소 짓는 스니블>$b$b그래, 좋아, 내가 누군가에게 로켓을 몇 개 만들어 줬을지도 모르지. 그래서 어쩌라고? 보수가 괜찮았기에 일을 하고 돈을 받았을 뿐이야. 그래서 누가 죽기라도 했나? 이보다 더 정직한 일도 없다고. 자네가 무슨 상관이야?', `MaleText_loc4`='<他看了看火箭，咧开嘴紧张地笑了笑。>$b$b好吧，我是给别人做了些火箭。那又怎么样？价格不错，我也得到了酬劳。这不是出不出人命的问题。工作就要实事求是。这跟你有关系吗？', `MaleText_loc5`='<他看著火箭然後閃過一個緊張的微笑。>$b$b沒錯，對，我或許是替某些人做了一兩個火箭。所以怎樣?在商言商，我只是付錢辦事。又不是有人死掉。我們打開天窗說亮話。你打算怎樣?', `MaleText_loc7`='<Mira al cohete y sonríe nervioso.>$B$BVale, sí, puede que haya hecho algunos cohetes para otros tipos. ¿Y qué? Me pagaron bien por mi trabajo. Ni que hubiera muerto nadie. Eso sí es trabajo sincero. ¿A ti qué más te da?' WHERE `ID`=37554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 안에 화학 물질이 있던데요, 어떤 물질입니까?', `MaleText_loc4`='火箭里携带了一种化学品。是什么东西？', `MaleText_loc5`='火箭中有一種化學藥劑。那是什麼?', `MaleText_loc7`='Hay un elemento químico dentro del cohete. ¿Qué es?', `FemaleText_loc1`='로켓 안에 화학 물질이 있던데요, 어떤 물질인가요?', `FemaleText_loc4`='火箭里携带了一种化学制品。是什么东西？', `FemaleText_loc5`='火箭中有一種化學藥劑。那是什麼?', `FemaleText_loc7`='Hay un elemento químico dentro del cohete. ¿Qué es?' WHERE `ID`=37555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나도 몰라, 응? 모른다고!$b$b그냥 누가 공기 중에 퍼지는 화학 물질이 담긴 로켓을 만들어 달라고 의뢰하기에, 돈 받고 일했을 뿐이라고. 일은 이미 끝났어. 포장해서, 보내버렸지. 그리고 돈 받아서 기분 좀 내 보려는데 갑자기 자네가 동네방네 나를 쫓아다닌 거야. 나는 그 화학 물질이 뭔지도 모르고, 남은 것도 없어.', `MaleText_loc4`='听着，我不知道，可以吗？我不知道！$b$b我只是拿钱做了一些火箭，用来空运那些化学品，这就是我是任务。我的任务结束了，朋友。火箭都做好了，而且装备完成发射了出去。我拿了钱，正准备去消费消费，你就在这个时候满世界的追我。我这没有那种化学品了，我也不知道那究竟是什么东西。', `MaleText_loc5`='聽著，我不知道，好嗎?我不知道!$b$b有人付錢讓用火箭空運一個化學彈頭，而我也在做了這些。工作已完成了，老兄。它們已經全都完成，打包並且送走了。我拿到錢，而我只想要小小地享受一下我的人生，你卻跑來打擾。我這裡已經沒有那些化學藥劑，我也不知道那是什麼。', `MaleText_loc7`='Mira, no lo sé, ¿vale? ¡No lo sé!$b$bMe pagaron para hacer cohetes para entregar una carga química aérea, y eso hice. Trabajo hecho, $gamigo:amiga;. Están hechos, empaquetados y enviados. Me dieron el dinero y estaba INTENTANDO disfrutarlo cuando empezaste a perseguirme por toda la ciudad. No tengo más de esa carga y no sé lo que era.' WHERE `ID`=37556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 배달했습니까?', `MaleText_loc4`='那些化学品是送到哪去的？', `MaleText_loc5`='東西送往哪裡?', `MaleText_loc7`='¿Dónde se entregó?', `FemaleText_loc1`='어디로 배달했지요?', `FemaleText_loc4`='那些化学品是送到哪去的？', `FemaleText_loc5`='東西送往哪裡?', `FemaleText_loc7`='¿Dónde se entregó?' WHERE `ID`=37557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 그딴 걸 굳이 기억하고 있어야 하지? 좋아, 이렇게 하지. 내가 이런 일을 참고 견뎌야 할 만큼 돈을 많이 받은 것도 아니고, 계약서에는 그냥 비밀로 하라고만 적혀 있었어. 그러니 내가 여기 바닥에 장부를 떨어뜨리지. 그거 줍고 제발 날 가만히 내버려 두라고.$b$b알겠나?', `MaleText_loc4`='你要我想起所有那些让我精神失常的事？听着。他们并没有付钱让我跟进这件事，我们之间的协议也不允许我透露这些。我可以把我的账本扔在地上，你自己捡起来然后别来烦我了。$b$b听明白了？', `MaleText_loc5`='你期待我會把所有東西都記在腦袋裡?聽著。他們可沒付錢叫我應付這種事，合約也只說要我不能多話。所以，我會把我的帳本掉在地板上，然後你就可以拿了它然後離我遠遠的。$b$b懂嗎?', `MaleText_loc7`='¿Esperas que recuerde eso así como si nada? Mira. No me pagaron lo suficiente como para aguantar esto y el contrato solo pedía mi silencio. Así que se me va a caer mi libro de contabilidad aquí en el suelo y tú lo vas a coger y a dejarme en paz.$b$b¿Entendido?' WHERE `ID`=37558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! "팔찌를 나눠요"라는 운동에 대해 들어본 적 있나?$B$B나같은 공식 왕관화학회사 행사 마스코트는 아름다운 장식 수집가 도구를 배포할 수 있다고.$B$B아름다운 장식을 모으면 아름다운 장식 팔찌를 만들 수 있는데, 이건 친구나 연인에게 줄 수도 있고 사랑의 상인에게 가져가서 사랑의 징표로 바꿀 수도 있지!$B$B요새 유행은 팔찌를 만들어서 자기가 가장 좋아하는 수장에게 바치는 거라지? 고마움과 사랑을 표시하려고 말이야...', `MaleText_loc4`='你听说过我们的“慈善情人符”计划吗？$B$B官方的加冕活动，像我这样的福星会得到授权，分发可爱的情人符工具箱。$B$B你可以用得来的可爱的情人符为自己的朋友和心爱的人制作可爱的情人符手镯，或是把它们拿到可爱的商贩那里来兑换爱情信物！$B$B这期间的另一个流行做法是将自己制作的手镯送给自己喜爱的领袖，让他们感受到众人对他们的欣赏和爱戴…', `MaleText_loc5`='唷!你知道我們的「慈善符咒」計畫嗎?$B$B王冠化學製藥公司的官方活動吉祥物，就像我將會分送可愛符咒收集工具組。$B$B你可以利用收集到的可愛符咒來製作可愛符咒手鐲，送給朋友或愛人，也可以把它拿給可愛商品商人換成愛之硬幣!$B$B另一個熱門活動就是製作手鐲送給你最愛的領袖，讓他們知道你對他們的感激與愛慕...', `MaleText_loc7`='¿Has oído hablar de nuestro programa "Talismanes caritativos"?$B$BLas mascotas oficiales de eventos de La Corona, S.L. como yo podemos distribuir Juegos de coleccionista de talismanes preciosos.$B$BPuedes usar los talismanes preciosos para crear pulseras de talismanes preciosos para tus amigos y amados, o entregárselas a mercaderes preciosas a cambio de pruebas de amor.$b$BUna actividad popular es crear pulseras para tus líderes preferidos para que sepan que se les valora y adora...' WHERE `ID`=37559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 재미있군요!', `MaleText_loc4`='漂亮！', `MaleText_loc5`='精采的表演!', `MaleText_loc7`='¡Buen espectáculo!' WHERE `ID`=37560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아름다운 장식 수집가 도구를 받고 싶습니다.', `MaleText_loc4`='我想要一个可爱的情人符工具箱。', `MaleText_loc5`='我想要一個可愛符咒收集工具組。', `MaleText_loc7`='Me gustaría obtener un juego de coleccionista de talismanes preciosos.', `FemaleText_loc1`='아름다운 장식 수집가 도구를 받고 싶어요.', `FemaleText_loc4`='我想要一个可爱的情人符工具箱。', `FemaleText_loc5`='我想要一個可愛符咒收集工具組。', `FemaleText_loc7`='Me gustaría obtener un juego de coleccionista de talismanes preciosos.' WHERE `ID`=37561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아는 건 다 말했다고. 이제 가버려!', `MaleText_loc4`='我已经把我知道的都告诉你了，现在走吧！', `MaleText_loc5`='我把所有我知道的都告訴你了，現在給我滾!', `MaleText_loc7`='Te he dicho lo que sé, ahora déjame.' WHERE `ID`=37562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 있다면 브레이지 게츠를 찾으세요! 아셨죠?$B$B"합법적인" 무언가만 말하는 게 아니랍니다. "원하는 건 뭐든지"라고요, 친구! 뭐든지요...', `MaleText_loc4`='无论你要什么，布雷泽·盖茨！明白吗？$B$B而且我指的不光是那些“合法”的东西。我是说——无论——你要什么，朋友！任何东西……', `MaleText_loc5`='不管你要什麼，布瑞奇·蓋茲!懂嗎?$B$B我也不是跟你說什麼「合法」的事情。不管你要什麼，老兄!任何東西...', `MaleText_loc7`='¡Lo que necesites, Brazie Lopillas! ¿Lo pillas?$B$BY no solo hablo de las cosas "legales". ¡LO QUE NECESITES, $gAMIGO:AMIGA;! Lo que sea...' WHERE `ID`=37563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 삶을 빼앗은 검에 이토록 가까이 있으니... 그 고통이... 다시금 느껴지는군.', `FemaleText_loc4`='站在这把杀害我的长剑面前……那种痛苦……仿佛又重新回来了。', `FemaleText_loc5`='如此靠近這把終結我性命的劍...那種痛苦...彷彿再次浮現。', `FemaleText_loc7`='Al estar tan cerca de la espada que puso fin a mi vida… el dolor… se renueva.' WHERE `ID`=37564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 좋아하는 이상한 물건엔 취미 없습니다. "합법적인" 물건만 보여 주시죠.', `MaleText_loc4`='我对你喜欢的那些怪东西不感兴趣，布雷泽。只管拿给我“合法”的东西。', `MaleText_loc5`='我對你喜歡的詭異東西沒興趣，布瑞奇。我要看「合法」的貨物。', `MaleText_loc7`='A mí no me gustan esas cosas raras como a ti, Brazie. Solo quiero que me enseñes las mercancías "legales".', `FemaleText_loc1`='당신이 좋아하는 이상한 물건엔 취미 없어요. "합법적인" 물건만 보여 주시죠.', `FemaleText_loc4`='我对你喜欢的那些怪东西不感兴趣，布雷泽。只管拿给我“合法”的东西。', `FemaleText_loc5`='我對你喜歡的詭異東西沒興趣，布瑞奇。我要看「合法」的貨物。', `FemaleText_loc7`='A mí no me gustan esas cosas raras como a ti, Brazie. Solo quiero que me enseñes las mercancías "legales".' WHERE `ID`=37565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검을 뽑으실 수 있습니까?', `MaleText_loc4`='你能取出那把剑吗？', `MaleText_loc5`='你能把劍拔出來嗎?', `MaleText_loc7`='¿Puedes retirar la espada?', `FemaleText_loc1`='검을 뽑으실 수 있나요?', `FemaleText_loc4`='你能取出那把剑吗？', `FemaleText_loc5`='你能把劍拔出來嗎?', `FemaleText_loc7`='¿Puedes retirar la espada?' WHERE `ID`=37566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님, 아서스가 오는 것 같습니다. 뭘 하시려는 건지 몰라도, 서두르는 게 좋겠습니다.', `MaleText_loc4`='黑暗女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。', `MaleText_loc5`='黑暗女王，我想我聽見阿薩斯正在靠近。不管你們打算作什麼，請加快動作。', `MaleText_loc7`='Dama Oscura, creo que oigo a Arthas acercándose. Sea lo que sea que vayas a hacer, hazlo rápido.', `FemaleText_loc1`='어둠의 여왕님, 아서스가 오는 것 같습니다. 뭘 하시려는 건지 몰라도, 서두르는 게 좋겠어요.', `FemaleText_loc4`='黑暗女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。', `FemaleText_loc5`='黑暗女王，我想我聽見阿薩斯正在靠近。不管你們打算作什麼，請加快動作。', `FemaleText_loc7`='Dama Oscura, creo que oigo a Arthas acercándose. Sea lo que sea que vayas a hacer, hazlo rápido.' WHERE `ID`=37567;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런... 믿을 수가 없어! 서리한이... 무방비 상태로 눈앞에 있다니. 그 노움의 말이 맞았다. 오라, 영웅들이여!', `FemaleText_loc4`='真是……不敢相信！霜之哀伤居然……无人看管，那个侏儒说的没错。来吧，英雄们！', `FemaleText_loc5`='我...我不相信!霜之哀傷就在我們眼前 - 無人守護 - 就像地精說得一樣。來吧，英雄們!', `FemaleText_loc7`='¡No... no puede ser! La Agonía de Escarcha está justo ante nosotros, sin vigilancia, tal y como dijo el gnomo. ¡Vamos, héroes!' WHERE `ID`=37568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 삶을 끝장냈던 검에 이토록 가까이 있으니... 그때의 고통이... 다시금 느껴진다.', `FemaleText_loc4`='就是这把剑终结了我的生命……那种痛苦……挥之不去。', `FemaleText_loc5`='如此靠近這把終結我性命之劍...那種痛苦...彷彿再次浮現。', `FemaleText_loc7`='Al estar tan cerca de la espada que puso fin a mi vida… el dolor… se renueva.' WHERE `ID`=37569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='건드릴 엄두가 나지 않는다. 물러나라! 물러나! 내가 검과 대화해볼 테니! 우리의 구원이 그 안에 있을지도 모른다...', `FemaleText_loc4`='我不敢碰它。后退！后退，我要试着和这把剑交谈！也许我们的救赎就在其中……', `FemaleText_loc5`='我可不敢碰它。退後!在我試圖跟劍溝通時退開!或許我們的救贖之道就在...', `FemaleText_loc7`='No me atrevo a tocarla. ¡Atrás! ¡Atrás mientras intento comunicarme con la espada! Puede que nuestra salvación se halle dentro...' WHERE `ID`=37570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우서... 빛의 수호자 우서라니 어떻게...', `FemaleText_loc4`='乌瑟尔……乌瑟尔·光明使者。怎么……', `FemaleText_loc5`='烏瑟...『光明使者』烏瑟。怎麼會...', `FemaleText_loc7`='Uther... Uther el Iluminado. ¿Cómo...?' WHERE `ID`=37571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕이 여기에? 그렇다면 오늘 숙원을 풀 것이오!', `FemaleText_loc4`='巫妖王就在这里？那今天就是我完成使命的日子！', `FemaleText_loc5`='巫妖王在這裡?那麼我將在今天完成我的宿命!', `FemaleText_loc7`='¿El Rey Exánime está aquí? Entonces, ¡hoy cumpliré mi destino!' WHERE `ID`=37572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방법이 있을 텐데...', `FemaleText_loc4`='一定有办法……', `FemaleText_loc5`='一定有什麼方法...', `FemaleText_loc7`='Tiene que haber un modo...' WHERE `ID`=37573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 그런 짐을 지겠소?', `FemaleText_loc4`='谁能扛起这样的重担？', `FemaleText_loc5`='誰能肩負如此重擔?', `FemaleText_loc7`='¿Quién podría soportar tal carga?' WHERE `ID`=37574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼어붙은 왕좌인가...', `FemaleText_loc4`='冰封王座……', `FemaleText_loc5`='冰封王座...', `FemaleText_loc7`='El Trono Helado...' WHERE `ID`=37575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리 쉽게 도망칠 것 같으냐, 아서스! 난 복수하고 말 것이다!', `FemaleText_loc4`='你别想轻易逃走，阿尔萨斯！我的仇一定要报！', `FemaleText_loc5`='你不會這麼容易從我手中逃掉，阿薩斯!我將會復仇!', `FemaleText_loc7`='¡No escaparás de mí tan fácilmente, Arthas! ¡Obtendré mi venganza!' WHERE `ID`=37576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늦었군요, 밀사여. 아니, 변명은 듣지 않겠습니다. 이 임무는 너무나도 중요하니까요.', `MaleText_loc4`='你太迟了，信使。不，我不想听你的借口；这个任务极为重要。', `MaleText_loc5`='你遲到了，信差。不，我不接受任何藉口;這次任務太重要了。', `MaleText_loc7`='Llegas tarde, $gmensajero:mensajera;. No, no quiero excusas: esta tarea es demasiado importante.' WHERE `ID`=37580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 대표자가 고룡쉼터 사원에서 가져온 고서입니다. 당장 이걸 미랄리온 선블레이즈에게 가져가십시오.', `MaleText_loc4`='这是我们的使者从龙眠神殿带回来的宝典。立刻将它带给麦雷昂·阳炎。', `MaleText_loc5`='這是我們的代表從龍眠拿來的書冊。盡快把這個拿給米拉連恩·日炎。', `MaleText_loc7`='Este es el escrito que trajo nuestro representante de Reposo del Dragón. Llévaselo a Myralion Resplandor inmediatamente.' WHERE `ID`=37581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤를 조심하십시오, 밀사여. 이 책의 가치를 다시 알려 드릴 필요는 없겠죠. 이걸 차지할 수만 있다면 은빛 서약단이 무슨 짓이든 하리란 것도 잘 아시리라 믿습니다.', `MaleText_loc4`='信使，你要小心。我无须向你解释这本书的重要性，况且，银色盟约的人会不惜一切代价把它从我们手里夺走。', `MaleText_loc5`='小心，信差。我不需要提醒你這本書的價值，也不用說明白銀誓盟會盡一切可能把書從我們這裡奪走。', `MaleText_loc7`='Vigila tu espalda, $gmensajero:mensajera;. No tengo que recordarte el valor del libro, ni el hecho de que El Pacto de Plata no se detendrá ante nada para quitárnoslo.' WHERE `ID`=37582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게. 이전에 우리를 구했던 그 저주받은 검에 대해 들은 적 있네. 서리한 때문에 무엇이 생겨났는지 주위를 둘러보게나.', `MaleText_loc4`='小心，女孩。我听说这把被诅咒的剑救过我们。注意周围，看看霜之哀伤都创造了些什么。', `MaleText_loc5`='小心點，女孩。我聽說這把詛咒之劍曾經拯救過我們。瞧瞧你四周，看看霜之哀傷帶來了什麼後果。', `MaleText_loc7`='Cuidado. Ya he oído antes que esa espada maldita nos salvaría. Mira a tu alrededor y observa lo que ha brotado de la Agonía de Escarcha.' WHERE `ID`=37583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 얼마 없어. 이 검이 보는 걸 리치 왕도 본다네. 그가 곧 들이닥칠 걸세.', `MaleText_loc4`='你没有时间了。巫妖王能看到剑旁的一切。他就要来了。', `MaleText_loc5`='你們沒有太多時間。巫妖王可以看到劍所看到的一切。他很快就會出現。', `MaleText_loc7`='Hay poco tiempo. El Rey Exánime ve lo que ve la espada. Llegará en cualquier momento. ' WHERE `ID`=37584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 물리칠 순 없네. 여기선 말이지. 그냥 덤비는 건 바보짓이야. 리치 왕은 그대를 따르는 자들을 죽여, 강력한 스컬지 병사로 일으킬 걸세. 그렇지만, 실바나스... 그대에게는 지난번보다 더 끔찍한 일이 닥칠 걸세.', `MaleText_loc4`='在这里，你无法击败巫妖王。这种企图是愚蠢的。他会打倒那些跟随你的人，把他们变成强大的天灾战士。只有你除外，希尔瓦娜斯……他对你的“馈赠”要比上次更恐怖。', `MaleText_loc5`='你們無法擊敗巫妖王，在這裡辦不到。也不應該蠢到去嘗試。他會殺死你們全部，然後把你們復活成天譴軍團的強大士兵。而你，希瓦娜斯，他將給你最慘絕人寰的獎勵。', `MaleText_loc7`='No puedes derrotar al Rey Exánime. No aquí. Estarías loca si lo intentases. Matará a los que te siguen y los levantará como poderosos soldados de la Plaga. Pero en tu caso, Sylvanas… la recompensa que tiene para ti será peor que la última.' WHERE `ID`=37585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르지. 하지만, 이건 알아두게. 리치 왕은 언제나 존재해야만 해. 그대가 아서스를 물리쳐도, 누군가가 그의 자리를 대신해야만 하네. 리치 왕이 지배하지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 휩쓸며 모든 것을 파괴할 테니까.', `MaleText_loc4`='也许吧，但要记住：一定要有一位巫妖王。即使你终结了阿尔萨斯，也要有另一个人来取代他。没有了巫妖王的控制，天灾军团就会像蝗灾一样横扫世界，所到之处，寸草不生。', `MaleText_loc5`='或許，但是要知道:世上永遠都需要一個巫妖王。就算你們擊倒了阿薩斯，另一個人就得取代他的位置，要是沒有巫妖王的控制，天譴軍團將會像是蝗蟲一般，摧毀它們接觸到的所有事物。', `MaleText_loc7`='Tal vez, pero ten esto en cuenta: siempre debe haber un Rey Exánime. Incluso si derrotas a Arthas, otro deberá tomar su lugar, ya que, sin el dominio del Rey Exánime, la Plaga invadirá este mundo como langostas, destruyendo todo lo que toque.' WHERE `ID`=37586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밴시 여왕이여, 모르겠네. 어쩌면 스컬지가 아제로스를 쓸어 버리지 않는 유일한 이유는 리치 왕 안에 아서스의 일부가 남아서 그들을 막기 때문이 아닌가 하네.', `MaleText_loc4`='我不知道，女妖之王。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。', `MaleText_loc5`='我不知道，女妖之王。我懷疑阿薩斯的一部份仍然存在於巫妖王之中，這也是為什麼天譴軍團一直沒有滅絕艾澤拉斯。', `MaleText_loc7`='No lo sé, Reina Alma en Pena. Supongo que la parte de Arthas que vive dentro del Rey Exánime es todo lo que evita que la Plaga aniquile Azeroth.' WHERE `ID`=37587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도, 리치 왕을 무찌를 방법은 하나뿐이라네. 그 존재가 생겨난 곳에서 쓰러뜨려야 하지.', `MaleText_loc4`='唉，击败巫妖王的唯一方法就是在他的诞生地摧毁他。', `MaleText_loc5`='最終，打倒巫妖王的唯一辦法就是在他被創造出來的地方毀滅他。', `MaleText_loc7`='Qué desgracia, la única forma de derrotar al Rey Exánime es destruirlo en el lugar donde fue creado.' WHERE `ID`=37588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 으아아아아아아아... 그... 그가 오고 있어. 그대는... 어서...', `MaleText_loc4`='啊……他……他来了。你……你必须……', `MaleText_loc5`='是。啊啊啊啊啊啊...他...他來了。你...你們一定...', `MaleText_loc7`='Sí. ARRRRRRGHHHH... Se... acerca. Debes... debes...' WHERE `ID`=37589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우서가 고개를 젓습니다.', `MaleText_loc4`='乌瑟尔摇了摇头。', `MaleText_loc5`='烏瑟搖頭。', `MaleText_loc7`='Uther niega con la cabeza.' WHERE `ID`=37590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 한기는... 피가 얼어붙는 것 같군요.', `FemaleText_loc4`='这种刺骨的寒冷……血液好像都要凝结了。', `FemaleText_loc5`='這個地方的冰冷...我感到血液在凝結。', `FemaleText_loc7`='El frío de este lugar... ¡Brrrr! Siento que se me congela la sangre.' WHERE `ID`=37591;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저게 뭐죠? 저 위에요! 말도 안 돼! 영웅들이여, 이리로!', `FemaleText_loc4`='看前面！那是什么！难道是？英雄们，到我身边来！', `FemaleText_loc5`='那是什麼!前面那個!這可能嗎?英雄們，到我旁邊來!', `FemaleText_loc7`='¿Qué es eso? ¡Ahí delante! ¿Será…? ¡Héroes, vengan conmigo!' WHERE `ID`=37592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리한. 우리 왕국을 파괴한 검...', `FemaleText_loc4`='霜之哀伤：正是它摧毁了我们的王国。', `FemaleText_loc5`='霜之哀傷:摧毀我們王國的那把劍...', `FemaleText_loc7`='La Agonía de Escarcha: la espada que destrozó nuestro reino.' WHERE `ID`=37593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러나세요! 저 검에 손을 대면 영혼에 영원한 상처가 남을 거예요! 서리한에 갇힌 영혼들과 대화해봐야 해요. 자리를 좀 비켜주세요. 물러서요.', `FemaleText_loc4`='后退！如果碰到这把剑，你的灵魂就会受到永恒的创伤！我必须试着与封印在霜之哀伤中的灵魂交谈。远离我，请再后退一点。', `FemaleText_loc5`='退後!觸碰那把劍將會永遠毀傷你的靈魂!我一定要試著跟那些被困在霜之哀傷中的靈魂溝通。給我一點空間。請退後。', `FemaleText_loc7`='¡Atrás! ¡Si tocan la espada, su alma quedará marcada para toda la eternidad! Debo intentar ponerme en contacto con los espíritus atrapados en la Agonía de Escarcha. A un lado. Retrocedan.' WHERE `ID`=37594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우서 경! 친애하는 우서 경! 정말... 미안해요.', `FemaleText_loc4`='乌瑟尔！亲爱的乌瑟尔！我……很难过。', `FemaleText_loc5`='烏瑟!親愛的烏瑟!我...我真的很抱歉。', `FemaleText_loc7`='¡Uther! ¡Querido Uther! Lo... lo siento tanto.' WHERE `ID`=37595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스가 여기에요? 어쩌면 제가...', `FemaleText_loc4`='阿尔萨斯在这里？也许我……', `FemaleText_loc5`='阿薩斯在這?或許我...', `FemaleText_loc7`='¿Arthas está aquí? Tal vez pueda...' WHERE `ID`=37596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 우서 경, 아서스에게 닿을 수 있는 희망이 있다면. 해... 봐야해요.', `FemaleText_loc4`='但是，乌瑟尔，哪怕有一丝见到他的可能，我……我也要去。', `FemaleText_loc5`='但烏瑟，如果有任何機會能靠近阿薩斯。我...我一定要試試。', `FemaleText_loc7`='Pero Uther, si hay alguna esperanza de llegar a Arthas... debo… debo intentarlo.' WHERE `ID`=37597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게요? 어떻게 나의 왕자님이었던 그를 쓰러뜨려요? 어떻게...', `FemaleText_loc4`='告诉我，乌瑟尔，我该怎样终结我的王子？我的……', `FemaleText_loc5`='告訴我該怎麼做，烏瑟。我要怎麼毀滅我的王子?我的...', `FemaleText_loc7`='Dime cómo, Uther. ¿Cómo acabo con mi príncipe? Mi...' WHERE `ID`=37598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 우서 경. 용서하세요... 제가... 제가 왜 그랬는지 모르겠네요. 이 정보를 얼음왕관 성채 안에서 스컬지와 전투를 벌이는 기사들과 폐하께 알리겠어요.', `FemaleText_loc4`='你是对的，乌瑟尔。原谅我。我……我不知道自己是怎么了。正在冰冠堡垒与天灾军团作战的国王和骑士们很快就会得到我们的报告。', `FemaleText_loc5`='你是對的，烏瑟。原諒我。我...我不知道是什麼讓我這樣。我們會把消息傳給國王與那些在冰冠城塞對抗天譴軍的騎士。', `FemaleText_loc7`='Tienes razón, Uther. Perdóname. No... no sé qué me ha pasado. Daremos esta información al Rey y a los caballeros que se enfrentan a la Plaga en la Ciudadela de la Corona de Hielo.' WHERE `ID`=37599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 그런 짐을 지겠어요?', `FemaleText_loc4`='谁能扛起这样的重担？', `FemaleText_loc5`='誰能肩負如此重擔?', `FemaleText_loc7`='¿Quién podría soportar tal carga?' WHERE `ID`=37600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 아직 희망이 있을 거예요...', `FemaleText_loc4`='也许还有希望……', `FemaleText_loc5`='那麼或許還有希望...', `FemaleText_loc7`='Entonces, aún hay esperanza...' WHERE `ID`=37601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스, 날 막을 수는 없어요! 난 알아야 해요... 찾아야 해요..', `FemaleText_loc4`='你不能拒绝我，阿尔萨斯！我必须知道……必须明白……', `FemaleText_loc5`='你不能否認我說的，阿薩斯!我一定要知道...我一定要找出來...', `FemaleText_loc7`='¡No me privarás de esto, Arthas! Debo saber... Debo averiguar...' WHERE `ID`=37602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나! 정말 자네인가?', `MaleText_loc4`='吉安娜！真的是你吗？', `MaleText_loc5`='珍娜!真的是你?', `MaleText_loc7`='¡JAINA! ¿Realmente eres tú?' WHERE `ID`=37603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 얼마 없어. 이 검이 보는 걸 리치 왕도 본다네. 그가 곧 들이닥칠 거야.', `MaleText_loc4`='吉安娜，你没有时间了。巫妖王能看到剑旁的一切。他就要来了。', `MaleText_loc5`='珍娜，你們沒有太多時間。巫妖王可以看到劍所看到的一切。他很快就會出現。', `MaleText_loc7`='Jaina, no tienen mucho tiempo. El Rey Exánime ve lo que ve la espada. Llegará en cualquier momento. ' WHERE `ID`=37604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야. 아서스는 여기 없네. 아서스는 리치 왕의 마음 안에만 있는 존재야. 그것도 점점 희미해지지...', `MaleText_loc4`='不，孩子。阿尔萨斯不在这里。阿尔萨斯只是巫妖王意识中的一个存在。一个即将泯灭的存在……', `MaleText_loc5`='不，女孩。阿薩斯不在這裡。阿薩斯只存在於巫妖王的心中。一個逐漸消退的存在...', `MaleText_loc7`='No, niña. Arthas no está aquí. Arthas no es más que una presencia en la mente del Rey Exánime. Un presencia cada vez más débil...' WHERE `ID`=37605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나, 내 말 잘 듣게. 리치 왕을 쓰러뜨려야만 하네. 그를 설득할 수는 없어. 리치 왕은 자네와 동료를 모두 처치하고 강력한 스컬지 병사로 다시 일으킬 걸세.', `MaleText_loc4`='吉安娜，听我说。你必须终结巫妖王。不要试图说服他。他会把你们全杀掉，变成天灾军团的战士。', `MaleText_loc5`='珍娜，聽我說。你一定要摧毀巫妖王。你不可能跟他講道理。他會殺死你和你的盟友，然後把你們全都變成天譴軍團的強大士兵。', `MaleText_loc7`='Jaina, escúchame. Debes acabar con el Rey Exánime. No puedes razonar con él. Los matará a ti y a tus aliados y los levantará como poderosos soldados de la Plaga.' WHERE `ID`=37606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기운을 내게. 리치 왕은 그가 넬쥴과 합쳐진 곳에서 처치해야만 하네. 첨탑 꼭대기의 얼어붙은 왕좌 말이네. 그게 유일한 방법일세.', `MaleText_loc4`='振作起来，女孩。你必须在巫妖王和耐奥祖融合的地方－－冰封王座，将他终结。这是唯一的办法。', `MaleText_loc5`='振作起來，女孩。你一定要在巫妖王和耐祖奧融合之處摧毀他 - 就在尖塔之頂，就在冰封王座。這是唯一的方法。', `MaleText_loc7`='Despierta, niña. Debes acabar con el Rey Exánime en el lugar donde se fusionó con Ner''zhul, en lo alto de la aguja, en el Trono Helado. Es la única manera.' WHERE `ID`=37607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕에 대해... 알아야 하는 게 더 있네. 스컬지에 대한 지배가 없어지면 안 돼. 리치 왕을 쓰러뜨린다 해도 누군가 그 자리를 대신해야만 하네. 주인이 다스리지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 뒤덮고 모든 생명을 파괴할 테니까.', `MaleText_loc4`='还有…还有一些事情你需要知道。天灾军团绝不能失去控制。即使你战胜了这个巫妖王，也要有别人来取代他。没有巫妖王的控制，天灾军团就会横扫整个世界，摧毁一切生灵。', `MaleText_loc5`='有...有件關於巫妖王的事情你需要知道。天譴軍團絕對不能失去控制。就算你擊倒巫妖王，另一個人就得取代他的位置。要是沒有巫妖王的控制，天譴軍團將會像蝗蟲般橫掃整個世界 - 摧毀所有的生靈。', `MaleText_loc7`='Hay... algo más que deberías saber sobre el Rey Exánime. Nunca se debe perder el control sobre la Plaga. Incluso si vencen al Rey Exánime, otro deberá ocupar su lugar. Sin el dominio del Rey Exánime, la Plaga andaría sin control por el mundo, destruyendo todo ser viviente.' WHERE `ID`=37608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고결한 영혼이 숭고하게 희생되어야...', `MaleText_loc4`='要有个崇高的灵魂作出牺牲……', `MaleText_loc5`='一個高貴靈魂的偉大犧牲...', `MaleText_loc7`='Un gran sacrificio de un alma noble…' WHERE `ID`=37609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠네, 제이나. 어쩌면 스컬지가 아제로스를 쓸어 버리지 않는 유일한 이유는 리치 왕 안에 아서스의 일부가 남아서 그들을 막기 때문이 아닌가 하네.', `MaleText_loc4`='我不知道，吉安娜。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。', `MaleText_loc5`='我不知道，珍娜。我懷疑阿薩斯的一部份仍然存在於巫妖王之中，這也是為什麼天譴軍團一直沒有滅絕艾澤拉斯。', `MaleText_loc7`='No lo sé, Jaina. Supongo que la parte de Arthas que vive dentro del Rey Exánime es todo lo que evita que la Plaga aniquile Azeroth.' WHERE `ID`=37610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 제이나! 으아아아아아아아... 그... 그가 오고 있어. 자... 자네는 어서...', `MaleText_loc4`='不，吉安娜！啊……他……他来了。你……你必须……', `MaleText_loc5`='不，珍娜!啊啊啊啊啊啊...他...他來了。你...你們一定...', `MaleText_loc7`='¡No, Jaina! ARRRRRRGHHHH... Se... acerca. Debes... debes...' WHERE `ID`=37611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우서가 고개를 젓습니다.', `MaleText_loc4`='乌瑟尔摇了摇头。', `MaleText_loc5`='烏瑟搖頭。', `MaleText_loc7`='Uther niega con la cabeza.' WHERE `ID`=37612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 해라, 성기사!', `MaleText_loc4`='闭嘴，圣骑士！', `MaleText_loc5`='閉嘴，聖騎士!', `MaleText_loc7`='¡SILENCIO, PALADÍN!' WHERE `ID`=37613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 자와 얘기하고 싶다는 건가? 그 소원을 들어주지.', `MaleText_loc4`='你真的想和死人交谈？我会满足你。', `MaleText_loc5`='好，你想跟死者溝通?你會達成你的願望。', `MaleText_loc7`='¿Así que quieres comunicarte con los muertos? Tendrás lo que deseas.' WHERE `ID`=37614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔릭, 마윈. 끝나면 놈들의 시체를 내 방으로 가져오너라.', `MaleText_loc4`='法瑞克，玛维恩，杀掉他们，送到我的大殿来。', `MaleText_loc5`='法勒瑞克。麥爾溫。結束之後把他們的屍體帶到我的房間。', `MaleText_loc7`='Falric. Marwyn. Traigan sus cuerpos a mi cámara cuando hayan terminado.' WHERE `ID`=37615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스, 같은 실수를 두 번 하지는 않을 것이다. 이번에는 탈출할 수 없다. 모두 죽음으로 나를 섬기리라!', `MaleText_loc4`='我不会再犯同样的错误，希尔瓦娜斯。这次你走不了了，你们死后都会成为我的奴仆！', `MaleText_loc5`='我不會再犯同樣的錯誤，希瓦娜斯。這一次你們將無處可逃。你們全都要在死後服侍我!', `MaleText_loc7`='No volveré a cometer el mismo error, Sylvanas. Esta vez no habrá escapatoria. ¡Todos serán mis siervos después de muertos!' WHERE `ID`=37616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석군. 내가 오래전에 죽여버린 자를 찾다니. 그는 이제 그저 유령일 뿐이다. 내 마음에 울리는 희미한 메아리지...', `MaleText_loc4`='你要找那个早就被我干掉的家伙吗？现在他只是一个幽魂，一个我脑中微弱的回音……', `MaleText_loc5`='傻女孩。你想找的老早就被我殺死了。他現在不過是個鬼魂。一個在我腦中的微弱回音...', `MaleText_loc7`='Tonta. Buscas lo que asesiné hace mucho tiempo. Ahora no es más que un fantasma. Un eco lejano en mi mente…' WHERE `ID`=37617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 날 방해하느냐, $c|1이여;여;?', `FemaleText_loc4`='你为什么要打断我，$c？', `FemaleText_loc5`='你為什麼干涉我，$c?', `FemaleText_loc7`='¿Por qué me interrumpes, $c?' WHERE `ID`=37618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기묘한 분이시군요.', `MaleText_loc4`='你是个奇怪的小家伙。', `MaleText_loc5`='你真是個奇怪的小傢伙。', `MaleText_loc7`='Eres muy raro.', `FemaleText_loc1`='기묘한 분이시군요.', `FemaleText_loc4`='你是个奇怪的小家伙。', `FemaleText_loc5`='你真是個奇怪的小傢伙。', `FemaleText_loc7`='Eres muy raro.' WHERE `ID`=37619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴을 보니 마음이 놓입니다, 밀사여. 크라서스가 고대의 용이 벼려낸 검이라는 책을 우리에게 하나 내줬습니다.', `MaleText_loc4`='总算盼到你来了，信使。克拉苏斯将其余的上古龙铸之刃复制品中的一个交给了我们。', `MaleText_loc5`='真高興終於見到你了，信差。卡薩斯託付給我們最後幾本上古龍鑄劍刃的其中一本。', `MaleText_loc7`='Me alegro de verte al fin, $gmensajero:mensajera;. Krasus nos ha confiado una de las pocas copias que quedan de Hojas antiguas forjadas por los dragones.' WHERE `ID`=37620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 책이 있습니다. 무슨 일이 벌어지는 건지 선리버에서 눈치채기 전에 반드시 이 책을 얼음왕관에 있는 칼라디스 브라이트스피어에게 가져다주십시오.', `MaleText_loc4`='给你书。你要确保赶在夺日者发现这一切之前将书送到卡莱迪斯·亮矛那里。', `MaleText_loc5`='書在這裡。你要確保會交到寒冰皇冠的卡拉迪斯·亮矛手上，要趕在奪日者明白發生什麼事之前。', `MaleText_loc7`='Aquí está tu libro. Asegúrate de que llegue a Caladis Lanza Reluciente en Corona de Hielo antes de que los Atracasol se den cuenta de lo que está ocurriendo.' WHERE `ID`=37621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직이십시오! 자기들이 찾는 정보를 우리가 쥐고 있다는 걸 알면, 선리버 놈들은 곧바로 행동을 개시할 겁니다.', `MaleText_loc4`='快马加鞭！夺日者发现我们有他们要的信息时会抓紧一切时间对付我们。', `MaleText_loc5`='快點出發吧!一旦奪日者知道我們握有他們在尋找的資訊，他們絕對不會浪費時間的。', `MaleText_loc7`='¡Viaja rápido! Los Atracasol no desperdiciarán ni un minuto en cuanto sepan que tenemos la información que buscan.' WHERE `ID`=37622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 시민들이여, 도시가 공격받고 있다! 무기를 들고 우리의 수도를 방어하라!! 전투에 직접 참가할 수 없는 자들은 모래주머니를 움켜쥐고 거리로 나와서 홍수를 막아라!', `MaleText_loc4`='暴风城的市民和客人们。我们的城市正在遭受攻击！拿起武器，保卫我们的首都！如果你不想参加战斗，就用沙包在街道上筑起堤坝，阻挡即将到来的洪水吧！', `MaleText_loc5`='暴風城的居民和訪客，我們的城鎮正遭受著攻擊!拿起你的武器保護我們的都市!如果你不想置身戰場，那就拿起沙袋把道路擋起來防止水淹進來!', `MaleText_loc7`='Ciudadanos e invitados de Ventormenta. Están atacando nuestra ciudad. ¡Tomad las armas y defended nuestra capital! ¡Si no deseáis acudir a la llamada de la batalla, entonces cargad sacos de arena y amontonadlos en las calles para evitar la inundación!' WHERE `ID`=37623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 주변에 정기의 균열이 열렸다. 당장 균열을 닫아야 한다! 무장을 하지 않은 시민들을 보살펴라. 모두 안전하게 대피시켜라!', `MaleText_loc4`='元素裂隙已经在这座城市周围张开。我们必须立刻将它们关闭！撤离全部非战斗市民。确保他们到达安全的地方！', `MaleText_loc5`='元素裂隙已經出現於城鎮的各地。我們必須馬上將它們關閉!疏散所有非戰鬥人員，確保他們到安全的場所!', `MaleText_loc7`='Se han abierto fallas elementales por toda la ciudad. ¡Tenemos que cerrarlas! ¡Evacuad a todos los todos los ciudadanos no combatientes! ¡Aseguraos de ponerlos a salvo!' WHERE `ID`=37624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$B$B서둘러라. 도시 네 모퉁이의 얼음 기둥을 사용해 정령계로 차원문을 열고, 이 공격을 주동한 존재를 소환해라.$B$B승리하려면 각 얼음 기둥을 동시에 작동시켜야 한다.', `MaleText_loc4`='$B$B抓紧时间，使用城中每个角落的寒冰之石打开一道通往元素位面的传送门并召唤那些要为此事负责的家伙。$B$B同时激活所有的寒冰之石以确保胜利的取得。', `MaleText_loc5`='$B$B快，在城市的每個角落使用冰石開啟通往元素界域的傳送門，並召喚那些可信賴的盟友。$B$B你必須同時啟動每一顆石頭已確保勝利。', `MaleText_loc7`='$B$BRápido, utiliza las piedras de hielo en cada esquina de la ciudad para abrir portales al plano elemental e invocar a los responsables.$B$BTendrás que activar las piedras a la vez para asegurarte la victoria.' WHERE `ID`=37625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 주변에 모래주머니를 쌓아 홍수를 방지하십시오!$B$B도시 곳곳에 쌓인 모래주머니 더미에서 모래주머니를 집어$B$B붉은색 화살표|Tinterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 놓으십시오.', `MaleText_loc4`='将沙袋堆砌在暴风城周围，挡住洪水！$B$B从散落在城市各个角落的沙袋堆里背起一个沙袋$B$B将它们放在红色箭头标记的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc5`='在暴風城的四周放置沙袋來防止淹水!$B$B從城市中各處的沙袋堆中拿起沙袋$B$B然後放在標有紅色箭頭的地方|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc7`='¡Coloca sacos de arena por todo Ventormenta para prevenir la inundación!$B$BRecoge un saco de arena de cualquier montón de sacos de arena situados por toda la ciudad$B$By colócalos en un sitio marcado con una flecha roja |TInterfaceIconsABILITY_HUNTER_MARKEDFORDEATH.blp:32|t.' WHERE `ID`=37626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열을 없애고, 대지 고리회 파수병이 준 토템을 사용해 갇혀 있는 시민을 풀어 주십시오!', `MaleText_loc4`='关闭那些裂隙，使用大地之环防御者提供的图腾，解救被围困的平民！', `MaleText_loc5`='關閉裂隙和使用陶土議會防衛者給你的圖騰來救出受困的居民!', `MaleText_loc7`='¡Acaba con las fallas y utiliza los tótems que te han dado los defensores del Anillo de la Tierra para liberar a los ciudadanos atrapados!' WHERE `ID`=37627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 전투의 흉터는 호드가 지배합니다!', `MaleText_loc4`='现在部落控制了战斗之痕！', `MaleText_loc5`='部落現在占領了戰痕!', `MaleText_loc7`='¡Ahora la Horda controla la Marca de Guerra!' WHERE `ID`=37628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 전투의 흉터는 얼라이언스가 지배합니다!', `MaleText_loc4`='现在联盟控制了战斗之痕！', `MaleText_loc5`='聯盟現在占領了戰痕!', `MaleText_loc7`='¡Ahora la Alianza controla la Marca de Guerra!' WHERE `ID`=37629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹스러운 호드의 병사여, 경의를 표하는 바이네. 자네와 함께 온 동맹이 아니었다면 우리는 분명히 얼라이언스 비행포격선에 끝장났을 걸세.$B$B성채의 상층 구역을 공격하기 전에 잠시 쉬게나.', `MaleText_loc4`='部落勇敢的战士，我向你致敬！如果没有你和你盟友的帮助，我们一定会死在联盟炮艇的火力下。$B$B请稍事休息，随后我们会展开针对敌人堡垒上游的袭击。', `MaleText_loc5`='部落的勇敢士兵，我向你致敬!如果不是你和你的盟友，我們肯定會被聯盟砲艇所摧毀。$B$B在我們開始攻擊城塞上層之前，請稍微休息一下。', `MaleText_loc7`='Valiente soldado de la Horda, ¡te saludo! Sin duda, la nave de guerra de la Alianza nos habría destruido de no haber sido por ti y tus aliados.$b$bDescansa un momento antes de que comencemos el asalto a la parte superior de la ciudadela.' WHERE `ID`=37630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대군주님, 저희는 시작할 준비가 되었습니다. 리치 왕은 반드시 쓰러져야만 합니다!', `MaleText_loc4`='我们准备好了，大王。巫妖王必须死！', `MaleText_loc5`='我們準備好了，霸王。巫妖王必須倒下!', `MaleText_loc7`='Estamos listos para partir, Alto señor supremo. ¡El Rey Exánime debe caer!', `FemaleText_loc1`='대군주님, 저희는 시작할 준비가 되었어요. 리치 왕은 반드시 쓰러져야만 해요!', `FemaleText_loc4`='我们准备好了，大王。巫妖王必须死！', `FemaleText_loc5`='我們準備好了，霸王。巫妖王必須倒下!', `FemaleText_loc7`='Estamos listos para partir, Alto señor supremo. ¡El Rey Exánime debe caer!' WHERE `ID`=37631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 확실한가? 우리가 성공을 거두려면 총력을 기울여 스컬지를 상대해야 하네. 더 쉴 필요가 없다면, 시작하겠네.', `MaleText_loc4`='你能肯定吗，$n？要想战胜天灾军团，我们必须全力以赴。如果你休息得差不多了，我们就开始吧。', `MaleText_loc5`='你確定，$n?若是我們成功，則將面對天譴軍團的全力攻擊。如果你不需要更多休息，那我們就開始吧。', `MaleText_loc7`='¿Seguro, $n? Debemos enfrentarnos a la Plaga con todas nuestras fuerzas si queremos tener éxito. Si no necesitas descansar más, comenzaremos.' WHERE `ID`=37632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르! 이제 준비되었습니다! 오크 형제여, 전진하십시오!', `MaleText_loc4`='Lok''tar ogar！我们准备好了！兽人兄弟们，冲啊！', `MaleText_loc5`='為了部落!我們準備好了!向前，獸人兄弟們!', `MaleText_loc7`='¡Lok''tar ogar! Estamos listos. ¡Adelante, hermano orco!', `FemaleText_loc1`='록타르 오가르! 이제 준비되었어요! 오크 형제여, 전진하세요!', `FemaleText_loc4`='Lok''tar ogar！我们准备好了！兽人兄弟们，冲啊！', `FemaleText_loc5`='為了部落!我們準備好了!向前，獸人兄弟們!', `FemaleText_loc7`='¡Lok''tar ogar! Estamos listos. ¡Adelante, hermano orco!' WHERE `ID`=37633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론, 출발하라! 용사들이여, 뒤를 조심하게. 스컬지는...', `MaleText_loc4`='库卡隆，行动！勇士们，提高警惕。天灾军团已经……', `MaleText_loc5`='柯爾克隆，前進!勇士們，要當心，天譴軍團已經...', `MaleText_loc7`='¡Kor''kron, vámonos! Campeones, vigilen su retaguardia. La Plaga ha sido…' WHERE `ID`=37634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께하시지요, 아버지. 저와 손을 잡고 함께 이 세계를 스컬지의 이름으로 궤멸합시다. 리치 왕의 영광을 위하여!', `MaleText_loc4`='加入我，父亲。让我们一同以天灾之名来粉碎这个渺小的世界——巫妖王万岁！', `MaleText_loc5`='加入我，父親。加入我，我們將能以天譴軍團之名粉碎這個世界 - 為了巫妖王的榮耀!', `MaleText_loc7`='Únete a mí, padre. Úneteme y juntos aplastaremos el mundo en nombre de la Plaga, ¡por la gloria del Rey Exánime!' WHERE `ID`=37635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들이 여기 있다는 이야기를 들었네. 그가 이제는 강력한 죽음의 기사로 리치 왕을 섬긴다고 말이야. 정말 이 얘기가 사실이라면, 그 목숨을 끊을 자는 나일 걸세.$B$B이제 내 임무는 오그림의 망치호를 얼음왕관 성채 꼭대기로 이동하여 우리 길을 막는 모든 스컬지를 처치하는 것이네. 자네와, 함께하는 동맹이 준비되면 떠나겠네.', `MaleText_loc4`='我曾听过我的孩子在那里发生的故事。现在，他已经成了巫妖王手下一名强大的死亡骑士。如果这是真的，我必须大义灭亲。$B$B我现在的责任就是指挥奥格瑞姆之锤号抵达冰冠堡垒之顶，并消灭所有阻拦我们的天灾军团。你和你的盟友准备好以后我们就出发。', `MaleText_loc5`='我聽說我的孩子在這裡。而且他現在是個服侍巫妖王的強大死亡騎士。如果這是真的，那麼我一定會親手結束我的血脈。$B$B我現在的任務是指揮奧格林之錘前往冰冠城塞之頂，並且摧毀所有擋住我們去路的天譴軍。等你和你的同伴準備好，我們就出發。', `MaleText_loc7`='He oído rumores de que mi hijo está aquí. Que ahora es un poderoso caballero de la Muerte en servicio del Rey Exánime. Si es cierto, la línea de descendencia acaba en mí.$b$bMi tarea ahora es dirigir el Martillo de Orgrim a la Ciudadela de la Corona de Hielo y destruir toda la Plaga en el camino. Partimos cuando tus aliados y tú estéis listos.' WHERE `ID`=37636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사울팽 님, 우리 동료 모두가 준비되었다고 합니다. 갑시다!', `MaleText_loc4`='算上我所有的同伴，萨鲁法尔。出发吧！', `MaleText_loc5`='我的勇士全都義不容辭，薩魯法爾。我們走!', `MaleText_loc7`='Mis compañeros están listos, Colmillosauro. ¡Vamos!', `FemaleText_loc1`='사울팽 님, 우리 동료 모두가 준비되었다고 해요. 가지요!', `FemaleText_loc4`='算上我所有的同伴，萨鲁法尔。出发吧！', `FemaleText_loc5`='我的勇士全都義不容辭，薩魯法爾。我們走!', `FemaleText_loc7`='Mis compañeros están listos, Colmillosauro. ¡Vamos!' WHERE `ID`=37637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들은 분노의 관문에서 목숨을 잃었다. 난 시신을 수습하러 왔을 뿐이다.', `MaleText_loc4`='我的儿子战死在天谴之门。我来只是想带走他的尸体。', `MaleText_loc5`='我的兒子死在憤怒之門。我來此只是為了帶回他的屍體。', `MaleText_loc7`='Mi hijo murió en la Puerta de Cólera. Solo he venido a recoger su cuerpo.' WHERE `ID`=37638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 답답도 하시군요. 뭘 하실 수나 있습니까? 저는 한창때 아버지보다 훨씬 강합니다.', `MaleText_loc4`='顽固的老头。你以为你能赢？即使你最强壮的时候，也不如我现在的力量。', `MaleText_loc5`='頑固的老傢伙。你有絲毫機會嗎?我比你任何時期都還要更強壯、更加有力。', `MaleText_loc7`='Viejo y testarudo. ¿Qué posibilidades tienes? Yo soy más fuerte y más poderoso de lo que tú nunca has sido.' WHERE `ID`=37639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 애를 드라노쉬라고 이름 지었었다. 오크 말로 "드레노어의 심장"이라는 뜻이지. 흑마법사들이 그 애를 데려가게 두지는 않았다. 가라다르의 장로들이 숨겼으니 안전할 터였지.', `MaleText_loc4`='我给他起名为德拉诺什，意思是“德拉诺之心”。我不会让那些术士带走他。我的孩子会安全地藏在加拉达尔长老那里。', `MaleText_loc5`='我們將他命名為德拉諾斯 - 獸人語的意思是「德拉諾之心」。我不會讓術士帶走他。我的兒子在卡拉達爾長老們的藏匿之下將會很安全。', `MaleText_loc7`='Lo llamamos Dranosh. Quiere decir "Corazón de Draenor" en orco. No dejé que los brujos se lo llevaran. Mi hijo estaba a salvo, los ancianos de Garadar lo escondían.' WHERE `ID`=37640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아내가 죽기 전에 약속했었다. 죽든 살든 어둠의 문은 나 혼자 넘고, 아들은 안전하게 있을 거라고. 더럽혀지지 않은 채로...', `MaleText_loc4`='我在他的母亲弥留时许下诺言。我会孤身穿过黑暗之门。无论我是生是死，我的儿子都不会有事，都会纯净如初……', `MaleText_loc5`='我在他母親死前許下承諾;我會獨自穿過黑暗之門 - 不管我是生是死，我的兒子都會平安無事。不受污染...', `MaleText_loc7`='Le hice una promesa a su madre antes de que muriera: que cruzaría el Portal Oscuro yo solo. Viviera o muriera, mi hijo estaría a salvo. Puro…' WHERE `ID`=37641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 그 약속을 지키는구나.', `MaleText_loc4`='今天，我兑现了诺言。', `MaleText_loc5`='今天，我完成了這項承諾。', `MaleText_loc7`='Hoy cumplo mi promesa.' WHERE `ID`=37642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 돌진합니다!', `MaleText_loc4`='%s开始冲锋！', `MaleText_loc5`='%s衝鋒!', `MaleText_loc7`='¡%s carga!' WHERE `ID`=37643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이를 헛드셨군요! 그렇다면 오시지요. 와서 스컬지의 힘에 맞서 보십시오!', `MaleText_loc4`='可怜的老兽人！来吧，英雄们，来尝尝天灾军团的力量吧！', `MaleText_loc5`='可悲的老獸人!來吧，英雄們。面對天譴軍團的力量吧!', `MaleText_loc7`='¡Viejo orco patético! Vengan, pues, héroes. ¡Vengan y enfréntense al poder de la Plaga!' WHERE `ID`=37644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리한의 존재 앞에서 쿠엘델라가 생명을 얻습니다!', `MaleText_loc4`='面对霜之哀伤，奎尔德拉很快复苏了！', `MaleText_loc5`='霜之哀傷的出現讓奎爾德拉彷彿有生命般地跳起來!', `MaleText_loc7`='¡Quel''Delar cobra vida en presencia de la Agonía de Escarcha!' WHERE `ID`=37645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기침합니다.', `MaleText_loc4`='%s开始咳嗽。', `MaleText_loc5`='%s咳嗽。', `MaleText_loc7`='%s tose.' WHERE `ID`=37646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아들의 시체 위로 눈물을 흘립니다.', `MaleText_loc4`='%s对着自己儿子的尸体流下了眼泪。', `MaleText_loc5`='%s對他的兒子的屍體流淚。', `MaleText_loc7`='%s llora sobre el cadáver de su hijo.' WHERE `ID`=37647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드에서 제대로 장례를 치러 주마. 네 어머니와 조상을 화장한 곳 옆에 말이다.', `MaleText_loc4`='你会在纳格兰有一个隆重的葬礼，安睡在你的母亲与祖先身旁。', `MaleText_loc5`='你會在納葛蘭有一場適宜的葬禮，就在你母親和祖先的火堆旁邊。', `MaleText_loc7`='Tendrás una ceremonia digna en Nagrand, junto a las piras de tu madre y tus ancestros.' WHERE `ID`=37648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 용사들이여, 아무리 끔찍한 전투라도... 도의까지 저버려서는 안 되네.', `MaleText_loc4`='年轻的英雄们……无论战斗多么可怕……也不要忘记荣耀。', `MaleText_loc5`='榮譽，年輕的英雄們...不管戰鬥有多艱辛...永遠不要拋棄榮譽。', `MaleText_loc7`='El honor, héroes jóvenes... No importa lo atroz de la batalla... Nunca renuncien a él.' WHERE `ID`=37649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣고, 따르겠습니다. 주인님...', `MaleText_loc4`='听从您的吩咐，主人……', `MaleText_loc5`='我聽令並且服從，主人...', `MaleText_loc7`='Escucho y obedezco, maestro...' WHERE `ID`=37650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에 커다란 고통을 안겨주겠습니다, 주인님!', `MaleText_loc4`='敌人即将大难临头，主人！', `MaleText_loc5`='敵人將會受盡苦難，主人!', `MaleText_loc7`='¡El enemigo sufrirá enormemente, amo!' WHERE `ID`=37651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아이의 영혼은 이제 리치 왕의 손아귀에서 벗어났네. 우리는 상층 구역으로 가는 길을 막은 저 벽을 무너뜨리는 데 집중해야 해. 이제 시간문제일 뿐이네, $n. 공성 기술자들이 $4939W일 안에 저 문을 무너뜨릴 걸세.', `MaleText_loc4`='他的灵魂已经摆脱了巫妖王的束缚。我们现在必须集中力量击破那几面阻挡我们前往上方的高墙。这只是个时间问题，$n。攻城工程师只需$4939W天就可以攻破大门了。', `MaleText_loc5`='他的靈魂掙脫了巫妖王的掌控。我們現在要將注意力集中在打破阻擋我們通往上層的牆壁上。這只是時間的問題，$n。攻城工程師應該會在$4939W天內解決這扇門。', `MaleText_loc7`='Su espíritu queda libre del Rey Exánime. Ahora debemos centrar nuestra atención en derribar los muros que impiden nuestro paso hasta las zonas altas. Solo es cuestión de tiempo, $n. Los ingenieros de asedio deberían haber tirado la puerta en $4939W días.' WHERE `ID`=37652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오너라, 스컬지베인. 누가 진짜 "용사" 호칭을 들을 자격이 있는지 주인님께 보여주리라!', `FemaleText_loc4`='来吧，斩亡者。我会让主人知道，我们谁才配得上“勇士”之名！', `FemaleText_loc5`='來吧，天譴剋星。我會讓主人瞧瞧，我們才配得上「勇士」的頭銜。', `FemaleText_loc7`='Ven, Finiquiplaga. ¡Le mostraré al amo quién merece realmente el título de "Campeón"!' WHERE `ID`=37653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 동지를 고르다니. 크록, 딱하구나!', `FemaleText_loc4`='怎么选这种低能的盟友，科罗克！', `FemaleText_loc5`='多糟糕的同伴選擇，克羅科!', `FemaleText_loc7`='¡Una pésima elección de aliado, Crok!' WHERE `ID`=37654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났습니다, 주인님.', `MaleText_loc4`='结束了，主人。', `MaleText_loc5`='完成了，主人。', `MaleText_loc7`='Listo, amo.' WHERE `ID`=37655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님... 실패...했습니다.', `MaleText_loc4`='主人……我……失败了。', `MaleText_loc5`='主人...我...失敗了。', `MaleText_loc7`='Amo... he... fracasado.' WHERE `ID`=37656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오, 주인님. 제대로 손봐주겠습니다!', `MaleText_loc4`='别害怕，主人。看我怎么将敌人撕个粉碎！', `MaleText_loc5`='無所懼怕，主人。我將會把敵人的血肉全給撕下來!', `MaleText_loc7`='No tema, amo. ¡Le traeré la carne de tus enemigos!' WHERE `ID`=37657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 고통은 없지요. 안 그렇습니까?', `MaleText_loc4`='一点都不疼了，是不是？', `MaleText_loc5`='再也不痛了，對吧?', `MaleText_loc7`='Ya no duele, ¿verdad?' WHERE `ID`=37658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다...', `MaleText_loc4`='很抱歉……', `MaleText_loc5`='我很抱歉...', `MaleText_loc7`='Lo siento...' WHERE `ID`=37659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어때, 후끈하지?', `MaleText_loc4`='能感到那灼热吗？', `MaleText_loc5`='你能感到那股灼熱嗎?', `MaleText_loc7`='¿Sienten cómo quema?' WHERE `ID`=37660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가...무슨 짓을 한 거지? 안 돼!', `MaleText_loc4`='我……做了什么？不！', `MaleText_loc5`='我...做了什麼?不!', `MaleText_loc7`='¿Qué... he hecho? ¡No!' WHERE `ID`=37661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄과 가까이 있으면 그렇게 되는 거야!', `MaleText_loc4`='这就是你距离炸弹太近的结果！', `MaleText_loc5`='這就是太靠近炸彈的下場!', `MaleText_loc7`='¡Eso es lo que pasa si estás demasiado cerca de una bomba!' WHERE `ID`=37662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로... 뻥 터지는 결말이로군!', `MaleText_loc4`='多么……爆炸性的结局啊！', `MaleText_loc5`='多麼...爆炸性的結尾!', `MaleText_loc7`='¡Qué final más... explosivo!' WHERE `ID`=37663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 이 힘은...? 모든 고통이 사라지다니! 당신도 나와 함께... 영원한 죽음의 품에 안겨야 합니다!', `MaleText_loc4`='什么？这种力量是……？所有的痛苦都消失了！你……？难道我们都投入了永恒的死亡怀抱？', `MaleText_loc5`='什麼?這股力量...?所有的痛苦都消失了!你...一定要與我一同迎接死亡的永恆擁抱!', `MaleText_loc7`='¿Qué? ¿Esta fuerza...? ¡Ya no hay dolor! Tú... ¡debes unirte a mí en el abrazo eterno de la muerte!' WHERE `ID`=37664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이제 틀렸습니다. 형제들이여, 계속 싸우십시오...', `MaleText_loc4`='我已经救不活了。兄弟们，继续战斗……', `MaleText_loc5`='沒什麼治療能救我了。繼續戰鬥吧，兄弟們...', `MaleText_loc7`='Ninguna cura puede salvarme ya. Sigan luchando, hermanos...' WHERE `ID`=37665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 내 시체는 화장해줘. 다음 생에는 따뜻하게 살도록...', `MaleText_loc4`='请……将我火化。让我在死后得到温暖……', `MaleText_loc5`='請...請把我的遺體燒了。讓我能在死後溫暖一些。', `MaleText_loc7`='Por favor... cremen mis restos. Déjenme vivir cálidamente en el más allá...' WHERE `ID`=37666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 안 돼! 왜 화장조차 허락되지 않는 거지? 너희 모두 불타버려!', `MaleText_loc4`='不！不！为什么我不能在火中死去？ 都烧成焦炭吧！', `MaleText_loc5`='不!不!為什麼不以火焰結束我的生命?你一定要全燒光!', `MaleText_loc7`='No... ¡No! ¿Por qué no pude morir en las llamas? ¡Ahora todos ARDERÁN!' WHERE `ID`=37667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째도 보람있는 삶이었어...', `MaleText_loc4`='我死的……很值得。', `MaleText_loc5`='這是...一場值得的死後世界。', `MaleText_loc7`='Ha sido... una no-muerte provechosa.' WHERE `ID`=37668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 뜻에서 벗어날 방법은 없다네. 뻥뻥 터지는 녀석들을 만나보게!', `MaleText_loc4`='巫妖王的意志不可逃避。准备好迎接一场爆炸吧！', `MaleText_loc5`='誰也不能逃脫巫妖王的意志。準備迎接爆炸!', `MaleText_loc7`='Nadie escapa de la voluntad del Rey Exánime. ¡Prepárense para un encuentro explosivo!' WHERE `ID`=37669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동기가 희미하게 빛납니다.', `MaleText_loc4`='传送器闪出水晶般的光芒。', `MaleText_loc5`='傳送器閃爍著一種結晶般的光芒。', `MaleText_loc7`='El teletransportador brilla con luz cristalina.', `FemaleText_loc1`='순간이동기가 희미하게 빛납니다.', `FemaleText_loc4`='传送器闪出水晶般的光芒。', `FemaleText_loc5`='傳送器閃爍著一種結晶般的光芒。', `FemaleText_loc7`='El teletransportador brilla con luz cristalina.' WHERE `ID`=37670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 망치로 순간이동', `MaleText_loc4`='传送到圣光之锤。', `MaleText_loc5`='傳送往聖光之錘。', `MaleText_loc7`='Teletransporte a Martillo de la Luz.', `FemaleText_loc1`='빛의 망치로 순간이동', `FemaleText_loc4`='传送到圣光之锤。', `FemaleText_loc5`='傳送往聖光之錘。', `FemaleText_loc7`='Teletransporte a Martillo de la Luz.' WHERE `ID`=37671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 쉬운 먹잇감이군. 실바나스 님께서 아주 기뻐하시겠어!', `FemaleText_loc4`='真是轻而易举的捕猎。希尔瓦娜斯一定会非常高兴的！', `FemaleText_loc5`='如此簡單的獵物。希瓦娜斯將會很高興!', `FemaleText_loc7`='Qué presa más fácil. ¡A Sylvanas le complacerá!' WHERE `ID`=37672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도대체 어떻게...?! 상관없다. 네놈을 상대하는 데 함정 따위는 없어도 돼!', `FemaleText_loc4`='你怎么？！没关系，我不需要用陷阱来击败你。', `FemaleText_loc5`='你是怎麼...?!無所謂...我不需要陷阱也能幹掉你。', `FemaleText_loc7`='¿Cómo has...? Da igual. No me hacen falta trampas para vencerte.' WHERE `ID`=37673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠 정찰병이 당신을 쏘기 전에 벨리사의 부적을 이용해 도망치십시오!$B$B|TInterface\\Icons\\inv_jewelry_talisman_10.blp:64|t', `FemaleText_loc4`='在黑暗斥候击中你之前，使用贝瑞莎的护身符！$B$B|TInterface\\Icons\\inv_jewelry_talisman_10.blp:64|t', `FemaleText_loc5`='在黑暗斥候射殺你之前，使用貝里莎的咒符逃離!$B$B|TInterface\\Icons\\inv_jewelry_talisman_10.blp:64|t', `FemaleText_loc7`='¡Utiliza el dije de Belrysa para escapar antes de que la exploradora oscura te dispare!$B$B|TInterfaceIconsinv_jewelry_talisman_10.blp:64|t' WHERE `ID`=37674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 전쟁에서 승리할 계획을 세워 볼까!$B$B동쪽 흉터의 땅에서 얼라이언스는 해안의 요새들을 육로로 연결하려는 심산이오. 이곳, 불모의 땅 가운데에 요새를 지으려 하고 있지. 바로 우리 불모의 땅에 말이오.$B$B어림없는 일이지.', `MaleText_loc4`='现在，我们要赢得这场战争！$B$B越过这片满目疮痍的地区向东，联盟希望在他们的海岸要塞之间建立起陆上连接。他们想要在这里，在贫瘠之地的正中心建立一座堡垒。但这是我的贫瘠之地。$B$B我绝不会允许那座堡垒出现。', `MaleText_loc5`='現在，回歸贏得此場戰爭的正題!$B$B在傷痕累累的東邊地帶，聯盟想要建造一個與他們海灘堡壘連接的建築。他們想在這建造一座堡壘，就在貧瘠之地的正中央，在我的貧瘠之地該死的正中央。$B$B他們絕對不可能成功。', `MaleText_loc7`='¡Ahora, al negocio de ganar esta guerra!$B$BMás allá del terreno dañado al este, la Alianza espera construir un vínculo por tierra entre sus bastiones de la costa. Están pensando en construir una fortaleza aquí, en el centro de Los Baldíos. En el centro de MIS Baldíos.$B$BNo aguantará.' WHERE `ID`=37675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 끔찍했다네, $c 친구. 오그리마에서 인정사정없이 해고당하고, 성문 밖으로 끌려나가 신선하게 꿈틀대는 부품 단지와 함께 바닥에 모두 내동댕이쳐졌지.$B$B사람을 무슨 괴물처럼 취급하더군!$B$B다행히도 신선한 시체가 끊임없이 솟아나는 이곳에서 연구를 계속할 수 있었다네.', `MaleText_loc4`='这太可怕了，$c。我被蛮横地赶出奥格瑞玛。当我被拖出奥格瑞玛的大门时，我的实验材料全都被扔在地上，被彻底毁了。$B$B他们对待我就好象对待某种可怕的怪物！$B$B幸运的是，我在这里还能继续我的研究。这里从不会缺乏新鲜的实验材料。', `MaleText_loc5`='那太恐怖了，$c。從奧格瑪被毫無尊嚴的踢出來，一盆盆還在蠕動的新鮮器官在我被拖出大門時被砸在地上。$B$B好像我是個怪物一樣!$B$B還好，我仍舊可以在這繼續進行我的研究，這不缺新鮮的屍體。', `MaleText_loc7`='Ha sido terrible, $c. Echado de Orgrimmar sin ninguna ceremonia, tinajas de miembros corporales estrelladas contra el suelo mientras me arrastraban a través de las puertas.$B$B¡Como si fuera un monstruo!$B$BPor suerte he conseguido continuar mi investigación aquí, donde no escasean los cadáveres frescos.' WHERE `ID`=37676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도를 올려라! 제군들, 곧 운명과 마주할 것이다!', `MaleText_loc4`='启动引擎！小伙子们，向命运之战前进！', `MaleText_loc5`='發動引擎!小夥子們，我們即將面對命運啦!', `MaleText_loc7`='¡Enciendan los motores! ¡Tenemos una cita con el destino, muchachos!' WHERE `ID`=37677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 붙들어라!', `MaleText_loc4`='都给我抓紧了！', `MaleText_loc5`='坐穩了!', `MaleText_loc7`='¡Agárrense fuerte!' WHERE `ID`=37678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 저게 뭐지? 선원, 망원경을 주게!', `MaleText_loc4`='那到底是什么？来人，给我望远镜！', `MaleText_loc5`='這是怎麼回事?船員，拿我的望遠鏡來!', `MaleText_loc7`='¿Qué demonios es esto? ¡Tripulante, mi catalejo!' WHERE `ID`=37679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수염 떨어질 뻔했네! 호드가 빠른 속도로 접근 중이다!', `MaleText_loc4`='以我的胡子起誓！部落的速度真快啊！', `MaleText_loc5`='我自個兒的鬍子啊!部落航行得像著火一樣快!', `MaleText_loc7`='¡Por mis barbas! ¡LA HORDA NAVEGA A TODA MÁQUINA!' WHERE `ID`=37680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대피하라! 포를 잡아라!', `MaleText_loc4`='规避动作！炮火准备！', `MaleText_loc5`='閃避飛行!握緊佩槍!', `MaleText_loc7`='¡ACCIÓN EVASIVA! ¡A LAS ARMAS!' WHERE `ID`=37681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비열한 놈들! 기습 공격을 하다니!', `MaleText_loc4`='卑鄙的家伙！竟敢偷袭我们！', `MaleText_loc5`='懦弱的蠢狗!竟敢偷襲我們!', `MaleText_loc7`='¡Cobardes! ¡Nos toman por sorpresa!' WHERE `ID`=37682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 낄 싸움이 아니라고? 자기를 얼마나 대단하게 생각하는지 모르겠지만, 난 아서스에게 갚아야 할 원수가 있으니 방해할 생각은 마라! 총공격! 발사! 발사!', `MaleText_loc4`='想挡住我？也不看看自己是谁？我现在就要去和阿尔萨斯算账了，谁也别想拦着我！注意！全火力射击！开火！开火！', `MaleText_loc5`='叫我不要戰鬥?我不知道你以為自己是誰，先生，我要去跟阿薩斯算帳，好狗不擋路!發射所有火砲!開火!開火!', `MaleText_loc7`='¿Que no es mi batalla? ¡No sé quién te crees que eres, amigo, pero tengo un asunto pendiente con Arthas y no te vas a poner en mi camino! ¡DISPAREN CON TODO! ¡FUEGO! ¡FUEGO!' WHERE `ID`=37683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 죽음과 파괴의 무리가 되어 이 세상을 쓸어버리리라!', `MaleText_loc4`='强大的天灾军团将让死亡和毁灭席卷整个世界！', `MaleText_loc5`='天譴軍團會化身為死亡與毀滅，席捲整個世界。', `MaleText_loc7`='¡La Plaga arrasará este mundo como un enjambre de muerte y destrucción!' WHERE `ID`=37684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프여, 이건 네가 낄 싸움이 아니다. 물러나지 않으면 그 배를 부술 수 밖에 없다.', `MaleText_loc4`='这不是你的战斗，矮人。回去，否则我们就只能摧毁你们。', `MaleText_loc5`='這不是你的戰鬥，矮人。滾下去，否則我們就得摧毀你們的艦艇。', `MaleText_loc7`='Esta no es tu batalla, enano. Retrocede o tendremos que destruir su barco.' WHERE `ID`=37685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈를 더 바쳐라!', `MaleText_loc4`='又一份给主人的献礼！', `MaleText_loc5`='更多骸骨祭品!', `MaleText_loc7`='¡Más huesos para la ofrenda!', `FemaleText_loc1`='뼈를 더 바쳐라!', `FemaleText_loc4`='又一份给主人的献礼！', `FemaleText_loc5`='更多骸骨祭品!', `FemaleText_loc7`='¡Más huesos para la ofrenda!' WHERE `ID`=37686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥으로 사라져라!', `MaleText_loc4`='到下面去挣扎吧！', `MaleText_loc5`='在詛咒中凋零!', `MaleText_loc7`='¡Púdrete en tu condena!', `FemaleText_loc1`='지옥으로 사라져라!', `FemaleText_loc4`='到下面去挣扎吧！', `FemaleText_loc5`='在詛咒中凋零!', `FemaleText_loc7`='¡Púdrete en tu condena!' WHERE `ID`=37687;
