UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 아들딸이여, 일어나라! 오늘 우리는 증오하던 적과 전투를 벌이리라! 록타르 오가르!', `MaleText_loc4`='来吧！部落忠诚勇敢的儿女们！今天是部落仇敌灭亡的日子！LOK''TAR OGAR！', `MaleText_loc5`='起來吧，部落的子女!今天我們要和最可恨的敵人作戰!為了部落!', `MaleText_loc7`='¡Levántense, hijos e hijas de la Horda! ¡Hoy nos enfrentamos a un enemigo odiado por todos! ¡LOK''TAR OGAR!' WHERE `ID`=37689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 분노가 나를 타고 흐른다!', `MaleText_loc4`='主人的怒火赐予我力量！', `MaleText_loc5`='主人的憤怒在我身體中奔流!', `MaleText_loc7`='¡LA RABIA DEL AMO FLUYE DENTRO DE MÍ!', `FemaleText_loc1`='주인님의 분노가 나를 타고 흐른다!', `FemaleText_loc4`='主人的怒火赐予我力量！', `FemaleText_loc5`='主人的憤怒在我身體中奔流!', `FemaleText_loc7`='¡LA RABIA DEL AMO FLUYE DENTRO DE MÍ!' WHERE `ID`=37690;
