UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 뭐지? 저 멀리서 무언가 다가온다.', `MaleText_loc4`='那是什么？有东西正从远方靠近！', `MaleText_loc5`='那是什麼?有東西從遠方靠近。', `MaleText_loc7`='¿Qué es eso? Algo se aproxima en la distancia.' WHERE `ID`=37692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈출할 길은 죽음뿐이다!', `MaleText_loc4`='死亡是唯一的解脱！', `MaleText_loc5`='唯一的出路只有死亡!', `MaleText_loc7`='¡La única salida es la muerte!', `FemaleText_loc1`='탈출할 길은 죽음뿐이다!', `FemaleText_loc4`='死亡是唯一的解脱！', `FemaleText_loc5`='唯一的出路只有死亡!', `FemaleText_loc7`='¡La única salida es la muerte!' WHERE `ID`=37693;
