UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사울팽이다. 당장 응답하라!', `MaleText_loc4`='在你面前的是萨鲁法尔！', `MaleText_loc5`='你們現在聽命於薩魯法爾!', `MaleText_loc7`='¡Ahora responden ante Colmillosauro!' WHERE `ID`=37697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 할 일을 당장 알려 주마. 코르크론, 저들을 처단하라!', `MaleText_loc4`='你很快就会明白了。库卡隆，消灭他们！', `MaleText_loc5`='你很快就會知道我們有何貴幹。柯爾克隆，殲滅他們!', `MaleText_loc7`='Pronto sabrás qué tenemos que hacer aquí. ¡Kor''kron, ANIQUÍLALOS!' WHERE `ID`=37698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 그 고철 덩어리 치워라. 그러지 않으면 날려버리겠다! 여기서 호드가 할 일은 없다.', `MaleText_loc4`='兽人！挪开你的破飞艇，否则我就把它轰烂！这里没部落什么事！', `MaleText_loc5`='獸人，讓你們的老爺飛機開快點，否則我就把你們從天空轟下來!這裡沒有部落的事。', `MaleText_loc7`='¡Mueve ese trasto o lo reventamos, orco! La Horda no tiene nada que hacer aquí.' WHERE `ID`=37699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소총병, 더 빨리 쏴라!', `MaleText_loc4`='火枪手，加速射击！', `MaleText_loc5`='步槍兵，加緊射擊!', `MaleText_loc7`='¡Fusileros, más rápido!' WHERE `ID`=37700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박격포 부대, 재장전!', `MaleText_loc4`='火炮小队，装弹！', `MaleText_loc5`='迫砲隊，裝填!', `MaleText_loc7`='¡Morteros, recarguen!' WHERE `ID`=37701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해병, 하사관, 공격하라!', `MaleText_loc4`='将士们，给我进攻！', `MaleText_loc5`='海員們，士官們，攻擊!', `MaleText_loc7`='¡Soldados, sargentos, ataquen!' WHERE `ID`=37702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선체가 공격받고 있다. 마술사를 불러 저 대포를 막아버려라!', `MaleText_loc4`='我们的船体受伤了，赶快叫个法师来干掉那些大炮！', `MaleText_loc5`='船體受損，找個巫士到這裡來，搞定那些火砲!', `MaleText_loc7`='¡Nos están dañando el casco, traigan a un brujo para que acabe con esos cañones!' WHERE `ID`=37703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지?! 이 아이언포지의 후예가 이끄는 배를 그냥 차지하지는 못한다!', `MaleText_loc4`='什么？！别妄想能轻易就夺走我们铁炉堡的船！', `MaleText_loc5`='搞什麼鬼?!你休想輕易拿下這艘鐵爐堡之子的船艦!', `MaleText_loc7`='¡¿Qué es esto?! ¡No derribarán la nave de este hijo de Forjaz sin luchar!' WHERE `ID`=37704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악당 놈들, 분명히 경고했다! 형제자매여, 전진!', `MaleText_loc4`='我早就警告过你，恶棍！兄弟姐妹们，前进！', `MaleText_loc5`='別說我沒警告過你，無賴!兄弟姊妹們，向前衝!', `MaleText_loc7`='¡No digan que no les avisé, sinvergüenzas! ¡Adelante, hermanos y hermanas!' WHERE `ID`=37705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바틀릿 선장, 여기서 벗어나자! 피해가 너무 커 계속 항해할 수 없다!', `MaleText_loc4`='指挥官巴雷特，离开这里！我们受到重创，难以漂浮了！', `MaleText_loc5`='巴特勒提督，帶我們離開這裡!我們受損到無法停留在空中了!', `MaleText_loc7`='¡Capitán Bartlett, sácanos de aquí! Hemos sufrido demasiados daños como para seguir volando.' WHERE `ID`=37706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 그리 좋지 않다.', `MaleText_loc4`='看上去不妙啊，小子们。', `MaleText_loc5`='這看來不妙，小夥子們!', `MaleText_loc7`='Esto se está poniendo feo, chicos.' WHERE `ID`=37707;
