UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선체가 공격받고 있다. 전투마법사를 불러 저 대포를 막아버려라!', `MaleText_loc4`='我们的船体受损了，赶快叫个战斗法师来轰掉那些大炮！', `MaleText_loc5`='船體受到傷害，找個戰鬥法師來，搞定那些火砲!', `MaleText_loc7`='¡Nos están dañando el casco, traigan a un mago de batalla para que acabe con esos cañones!' WHERE `ID`=37711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 배에 올라와? 순식간에 죽여주마.', `MaleText_loc4`='你竟敢上我的船？你活不长了。', `MaleText_loc5`='你好大的狗膽竟敢登上我的船?你死期到了。', `MaleText_loc7`='¿Te ATREVES a abordar mi barco? Tendrás una muerte rápida.' WHERE `ID`=37712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 기가 꺾였다. 리치 왕을 향해 전진하라!', `MaleText_loc4`='联盟不行了。向巫妖王进攻！', `MaleText_loc5`='聯盟已經動搖了。向巫妖王前進!', `MaleText_loc7`='La Alianza flaquea. ¡Hacia el Rey Exánime!' WHERE `ID`=37713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황을 수습하라! 저기 불을 꺼라. 호드는 아직 끝나지 않았다!', `MaleText_loc4`='把火扑灭，控制损伤！让你们见识一下部落的坚强！', `MaleText_loc5`='傷害控管!快點把火給滅了。這點小火對部落來說不算什麼!', `MaleText_loc7`='¡Control de daños! Apaguen esos incendios. ¡La Horda aún no está acabada!' WHERE `ID`=37714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하고 말았군.', `MaleText_loc4`='我们失败了。', `MaleText_loc5`='我們失敗了。', `MaleText_loc7`='Hemos fracasado.' WHERE `ID`=37715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<바퀴벌레가 칼더의 입에서 스르르 기어나와 텅 빈 눈을 통해 그의 머릿속으로 재빠르게 사라집니다.>', `MaleText_loc4`='<一只蟑螂从卡尔德的嘴里爬出来，又爬进了他的一只空眼窝。>', `MaleText_loc5`='<一隻蟑螂從考德爾的口中鑽了出來後，慌忙地由他空空的眼睛鑽回進入他的頭骨。>', `MaleText_loc7`='<Una cucaracha se desliza de la boca de Calder y vuelve a entrar en su cráneo a través de una cuenca ocular vacía.>' WHERE `ID`=37716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가오자 칼더는 말을 하기 위해 턱뼈를 다시 맞춥니다.>', `MaleText_loc4`='<一看到你，卡尔德装上他的下巴，准备和你说话。>', `MaleText_loc5`='<在看到你接近後，考德爾為了與你交談將他的下巴接了回去。>', `MaleText_loc7`='<Al ver que te acercas, Calder se encaja la mandíbula para hablar contigo.>' WHERE `ID`=37717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<칼더는 단검으로 한가롭게 귀부분을 매만지고 있습니다.>', `MaleText_loc4`='<你发现卡尔德正用一把匕首无聊地拨弄着他的耳朵。>', `MaleText_loc5`='<你發現考德爾懶散的用匕首在挖他的耳朵。>', `MaleText_loc7`='<Te encuentras con Calder andándose distraídamente en el oído con una daga.>' WHERE `ID`=37718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내가 뭘 좋아하는지 아나?', `MaleText_loc4`='知道我喜欢什么吗，$n？', `MaleText_loc5`='你知道我喜歡什麼嗎，$n?', `MaleText_loc7`='¿Sabes qué me gusta, $n?' WHERE `ID`=37719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 뭘 좋아하십니까?', `MaleText_loc4`='不，卡尔德。你喜欢什么？', `MaleText_loc5`='不，考德爾。你喜歡什麼?', `MaleText_loc7`='No Calder. ¿Qué te gusta?', `FemaleText_loc1`='아니요, 뭘 좋아하십니까?', `FemaleText_loc4`='不，卡尔德。你喜欢什么？', `FemaleText_loc5`='不，考德爾。你喜歡什麼?', `FemaleText_loc7`='No Calder. ¿Qué te gusta?' WHERE `ID`=37720;
