UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드린의 정령이 우리 드루이드에게 축복을 내렸던 것처럼, $n에게도 종족의 지혜와 늑대 신의 야성을 축복으로 내려 주십시오.', `MaleText_loc4`='就像戈德林之魂曾经祝福过我们的德鲁伊那样，请让$n得到祝福，赐予他智慧和狼神的勇猛吧。', `MaleText_loc5`='就像戈德林的靈魂曾經祝福過我們德魯伊一樣，讓$n獲得他們一族智慧的祝福和狼神力量的祝福。', `MaleText_loc7`='Del mismo modo que el espíritu de Goldrinn bendijo a nuestros druidas, que $n sea bendecido con la sabiduría de su raza y la ferocidad del dios lobo.' WHERE `ID`=37727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신드라고사의 둥지로 이동', `MaleText_loc4`='传送到辛达苟萨的巢穴。', `MaleText_loc5`='傳送往辛德拉苟莎之巢。', `MaleText_loc7`='Teletransporte a la Guarida de Sindragosa.', `FemaleText_loc1`='신드라고사의 둥지로 이동', `FemaleText_loc4`='传送到辛达苟萨的巢穴。', `FemaleText_loc5`='傳送往辛德拉苟莎之巢。', `FemaleText_loc7`='Teletransporte a la Guarida de Sindragosa.' WHERE `ID`=37728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야수로 변해 자연의 균형을 잃은 드루이드들의 고통을 다랄니르 님께서 덜어주셨던 것처럼, 탈도렌이 $n의 고통을 덜어주도록 하소서.', `FemaleText_loc4`='让塔多伦去安慰$n吧，就像达拉尼尔安慰那些因为受到诅咒，而放弃了平衡的信仰，变成野兽的德鲁伊一样。', `FemaleText_loc5`='當達然尼爾安撫那些俸給野獸和拋棄平衡的詛咒德魯伊時，讓塔爾多倫安撫$n。', `FemaleText_loc7`='Del mismo modo que Daral''nir alivió a los druidas malditos que se abandonaron a la bestia y rechazaron el equilibrio, que Tal''doren alivie a $n.' WHERE `ID`=37729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속박되지 말아야 했던 이 낫의 속박을 풀어 주십시오! 야성이 정신을 지배하지 않고, 정신이 야성을 지배하게 해 주십시오!', `MaleText_loc4`='让月神镰刀解放不应受束缚的生灵！让灵魂控制这兽性，而不是兽性控制灵魂！', `MaleText_loc5`='讓鐮刀切開不應該結合的!讓靈魂駕馭野獸，讓野獸駕馭靈魂!', `MaleText_loc7`='¡Que la guadaña desate aquello que no debería estar atado! ¡Que el alma domine a la bestia, para que la bestia no domine al alma!' WHERE `ID`=37730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요! 이리 오세요, $n 님.', `FemaleText_loc4`='嘿！过来，$n。', `FemaleText_loc5`='嘿!來這邊，$n。', `FemaleText_loc7`='¡Eh! $n, ven aquí.' WHERE `ID`=37731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 만족스럽게 당신 뒤를 통통 뛰며 따라갑니다.', `MaleText_loc4`='%s在你身后高兴地轻轻摇晃着。', `MaleText_loc5`='%s在你後面高興的跳來跳去。', `MaleText_loc7`='%s te hace reverencias muy contento.' WHERE `ID`=37732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집는 중', `MaleText_loc4`='正在拾取', `MaleText_loc5`='撿拾', `MaleText_loc7`='Despojar', `FemaleText_loc1`='집는 중', `FemaleText_loc4`='正在拾取', `FemaleText_loc5`='撿拾', `FemaleText_loc7`='Despojar' WHERE `ID`=37733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 그대들을 보내주신 영혼께 감사드립니다. 하늘파괴자호는 이미 떠났습니다. 이제 서둘러 오그림의 망치호를 향해 떠나십시오! 바로 출발한다면, 따라잡을 수 있을 겁니다.', `MaleText_loc4`='感谢你们，我的兄弟姐妹。破天号已经启程了。快到奥格瑞姆之锤去！也许你们还能乘上那艘船。', `MaleText_loc5`='感謝精靈，你們終於來了。破天者號已經離開了。現在快去奧格林之錘號!如果你動作夠快，或許還有機會趕上他們。', `MaleText_loc7`='Doy gracias a los espíritus por su presencia, hermanos. El Rompecielos ya ha partido. ¡Rápido, al Martillo de Orgrim! Si parten pronto, quizás puedan alcanzarlos.', `FemaleText_loc1`='형제자매여, 그대들을 보내주신 영혼께 감사드려요. 하늘파괴자호는 이미 떠났어요. 이제 서둘러 오그림의 망치호를 향해 떠나세요! 바로 출발한다면, 따라잡을 수 있을 거예요.', `FemaleText_loc4`='感谢你们，我的兄弟姐妹。破天号已经启程了。快到奥格瑞姆之锤去！也许你们还能乘上那艘船。', `FemaleText_loc5`='感謝精靈，你們終於來了。破天者號已經離開了。現在快去奧格林之錘號!如果你動作夠快，或許還有機會趕上他們。', `FemaleText_loc7`='Doy gracias a los espíritus por su presencia, hermanos. El Rompecielos ya ha partido. ¡Rápido, al Martillo de Orgrim! Si parten pronto, quizás puedan alcanzarlos.' WHERE `ID`=37734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 될 거예요!', `MaleText_loc4`='这对你来说应该有帮助！', `MaleText_loc5`='這應該能幫上忙!', `MaleText_loc7`='¡E''to os ayudará!', `FemaleText_loc1`='도움이 될 거예요!', `FemaleText_loc4`='这对你来说应该有帮助！', `FemaleText_loc5`='這應該能幫上忙!', `FemaleText_loc7`='¡E''to os ayudará!' WHERE `ID`=37735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마고쉬, 용감한 전사들이여. 여기에는 얼라이언스가 아주 많소.', `MaleText_loc4`='Aka''Magosh，勇士们。联盟在这里驻有重兵。', `MaleText_loc5`='(獸人語)祝福你與你的同伴，勇敢的戰士們。聯盟在這裡的數量眾多。', `MaleText_loc7`='Aka''Magosh, valientes guerreros. Las fuerzas de la Alianza son numerosas.', `FemaleText_loc1`='아카마고쉬, 용감한 전사들이여. 여기에는 얼라이언스가 아주 많소.', `FemaleText_loc4`='Aka''Magosh，勇士们。联盟在这里驻有重兵。', `FemaleText_loc5`='(獸人語)祝福你與你的同伴，勇敢的戰士們。聯盟在這裡的數量眾多。', `FemaleText_loc7`='Aka''Magosh, valientes guerreros. Las fuerzas de la Alianza son numerosas.' WHERE `ID`=37736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그림의 망치호에 오른 당신을 보면 사울팽 함장님께서 기뻐하실 거요. 서두르시오, 출발할 준비가 될 때까지 이 지역을 지키겠소.', `MaleText_loc4`='萨鲁法尔大王会在奥格瑞姆之锤号欢迎你们。我们会守住这里，等你们做好起飞准备。', `MaleText_loc5`='薩魯法爾船長會高興看到你登上奧格林之錘。動作快點，在你準備好離開前，我們得確保這個地區的安全。', `MaleText_loc7`='El capitán Colmillosauro se alegrará de verlos en el Martillo de Orgrim. Apresúrense, mantendremos segura la zona hasta que estén listos.', `FemaleText_loc1`='오그림의 망치호에 오른 당신을 보면 사울팽 함장님께서 기뻐하실 거요. 서두르시오, 출발할 준비가 될 때까지 이 지역을 지키겠소.', `FemaleText_loc4`='萨鲁法尔大王会在奥格瑞姆之锤号欢迎你们。我们会守住这里，等你们做好起飞准备。', `FemaleText_loc5`='薩魯法爾船長會高興看到你登上奧格林之錘。動作快點，在你準備好離開前，我們得確保這個地區的安全。', `FemaleText_loc7`='El capitán Colmillosauro se alegrará de verlos en el Martillo de Orgrim. Apresúrense, mantendremos segura la zona hasta que estén listos.' WHERE `ID`=37737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그림의 망치호 병사들, 위치로!', `MaleText_loc4`='奥格瑞姆之锤的兄弟们，坚守岗位！', `MaleText_loc5`='奧格林之錘步兵，堅守崗位!', `MaleText_loc7`='¡Infantería del Martillo de Orgrim, mantengan su posición!', `FemaleText_loc1`='오그림의 망치호 병사들, 위치로!', `FemaleText_loc4`='奥格瑞姆之锤的兄弟们，坚守岗位！', `FemaleText_loc5`='奧格林之錘步兵，堅守崗位!', `FemaleText_loc7`='¡Infantería del Martillo de Orgrim, mantengan su posición!' WHERE `ID`=37738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르!', `MaleText_loc4`='Lok''tar!', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Lok''tar!', `FemaleText_loc1`='록타르!', `FemaleText_loc4`='Lok''tar!', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Lok''tar!' WHERE `ID`=37739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 와요, 만크릭. 내 옆에 앉아 쉬어요.', `FemaleText_loc4`='来吧，曼科里克，坐到我旁边来休息一下。', `FemaleText_loc5`='來吧，曼寇里克。坐在我旁邊休息一下。', `FemaleText_loc7`='Ven, Mankrik. Siéntate a mi lado y descansa.' WHERE `ID`=37740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 투덜댑니다.', `MaleText_loc4`='%s哼哼着。', `MaleText_loc5`='%s咕噥著。', `MaleText_loc7`='%s gruñe.' WHERE `ID`=37741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅을 봐요, 만크릭. 호드와 얼라이언스가 적대감에 사로잡혀 서로 할퀴기 위해 대지를 가르고 있어요.', `FemaleText_loc4`='看看这片土地，曼科里克。部落和联盟之间争斗不休，也让这片土地满目疮痍。', `FemaleText_loc5`='看看這片大地，曼寇里克。部落和聯盟因為彼此的仇恨撕裂了這片大地。', `FemaleText_loc7`='Mira este sitio, Mankrik. La Horda y la Alianza arrasan la tierra solo para herirse mutuamente con rencor.' WHERE `ID`=37742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='증오는 파괴를 불러올 뿐이에요. 가시멧돼지와 싸우는 당신에게서도 그걸 볼 수 있어요... 분노는 당신을 갉아먹을 뿐이에요.', `FemaleText_loc4`='这样的仇恨只会给我们带来毁灭。当你和那些野猪人作战的时候，我也能在你的眼睛里看到那种仇恨……你的愤怒只会让你变得衰弱。', `FemaleText_loc5`='這種憎恨只會為我們帶來毀滅。我可以在你和野豬人戰鬥時看到...看到你的怒火正在一點一點地侵蝕著你。', `FemaleText_loc7`='Semejante odio solo nos trae destrucción. Lo veo en ti cuando luchas contra los jabaespines... Tu ira no hace más que consumirte.' WHERE `ID`=37743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만크릭, 당신은 자기 자신을 파괴하고 있는 거예요.', `FemaleText_loc4`='你在毁灭你自己，曼科里克。', `FemaleText_loc5`='你這是在糟蹋自己，曼寇里克。', `FemaleText_loc7`='Te estás destruyendo a ti mismo, Mankrik.' WHERE `ID`=37744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내겐 아무것도 남지 않았으니, 전사의 죽음을 맞이하겠소. 그게 잘못된 거요?', `MaleText_loc4`='我已经一无所有。现在我想要的只是一位战士光荣的死亡。这有错吗？', `MaleText_loc5`='我已經一無所有。我尋求的是像戰士般光榮的戰死。我這樣錯了嗎?', `MaleText_loc7`='Ya no me queda nada. Busco una muerte de guerrero. ¿Acaso está mal?' WHERE `ID`=37745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영광이 아닌 도피를 꿈꾸고 있으니까요. 그건 자살이나 마찬가지예요.', `FemaleText_loc4`='你在寻找的是逃避，不是光荣。这是自杀。', `FemaleText_loc5`='你尋求的是逃避，不是榮耀。那是自殺。', `FemaleText_loc7`='Buscas una salida, no la gloria. Es un suicidio.' WHERE `ID`=37746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 또 어떻소? 대체 왜 신경 쓰는 거요?', `MaleText_loc4`='那又怎样，你为什么要关心这种事？', `MaleText_loc5`='是又怎麼樣?你為什麼要管那麼多?', `MaleText_loc7`='¿Y qué si lo es? ¿Por qué te importa?' WHERE `ID`=37747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜냐면...', `FemaleText_loc4`='因为……', `FemaleText_loc5`='因為...', `FemaleText_loc7`='Porque...' WHERE `ID`=37748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 생각과는 달리, 세상에는 당신의 죽음을 슬퍼하는 이들도 있을 테니까요.', `FemaleText_loc4`='无论你是否在意，但这个世界里终究还是有人会因为你的死而伤心。', `FemaleText_loc5`='不管你相不相信，但這世界上或許有人會因為你的死去而慟悼。', `FemaleText_loc7`='Porque, a pesar de lo que pienses, puede que haya gente en este mundo que lamentaría tu muerte.' WHERE `ID`=37749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마카...', `MaleText_loc4`='玛卡……', `MaleText_loc5`='瑪卡...', `MaleText_loc7`='Mahka...' WHERE `ID`=37750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발, 만크릭. 분노를 버리고 칼날을 거둬요.', `FemaleText_loc4`='求求你，曼科里克。放手吧，放下你的剑。', `FemaleText_loc5`='拜託，曼寇里克，算了吧，放下你的武器吧。', `FemaleText_loc7`='Te lo ruego, Mankrik. Déjalo. Abandona tu espada.' WHERE `ID`=37751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마카, 수년간 내 안에는 증오가 불타올랐소. 당신이 그렇게 말해도 내 감정은 쉽게 사그라지지 않아.', `MaleText_loc4`='憎恨已经在我的心中燃烧了许多年，玛卡。你不可能凭几句话就把它除去。', `MaleText_loc5`='這種憎恨的感覺已經伴隨我多年了，瑪卡。我沒有辦法因為你說的話就如此輕易的解脫。', `MaleText_loc7`='Este odio ha ardido en mí durante años, Mahka. Tus palabras no pueden alejarlo de mí tan fácilmente.' WHERE `ID`=37752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 혼자 품고 있지 마요. 그냥 내 옆에 앉아, 잠시만이라도 골치 아픈 일을 잊어요.', `FemaleText_loc4`='现在……你不需要独自面对这一切。坐到我身边来，忘记你的困扰吧。哪怕一会儿也好。', `FemaleText_loc5`='那...你不需要一個人承擔。坐在我旁邊忘記這些煩惱吧，一下下也好。', `FemaleText_loc7`='Aun así, no tienes por qué soportarlo solo. Siéntate a mi lado y olvida tus preocupaciones, aunque solo sea un momento.' WHERE `ID`=37753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지쳤을 땐 언제라도 날 만나러 와요.', `FemaleText_loc4`='如果累了，就来我这里。', `FemaleText_loc5`='每當你心情沉悶時便來找我吧。', `FemaleText_loc7`='Ven a verme cuando te flaquee el ánimo.' WHERE `ID`=37754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마카가 당신과 만나고 싶어합니다, 만크릭.', `MaleText_loc4`='玛卡想要你去看她，曼科里克。', `MaleText_loc5`='曼寇里克，瑪卡要你去見她。', `MaleText_loc7`='Mahka quiere que vayas a verla, Mankrik.', `FemaleText_loc1`='마카가 당신과 만나고 싶어합니다, 만크릭.', `FemaleText_loc4`='玛卡想要你去看她，曼科里克。', `FemaleText_loc5`='曼寇里克，瑪卡要你去見她。', `FemaleText_loc7`='Mahka quiere que vayas a verla, Mankrik.' WHERE `ID`=37755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마카가 나를 보고 싶어한다고? ...알았네. 곧 따라갈 테니 그녀에게 돌아가 있게.', `MaleText_loc4`='玛卡想要见我？……好吧，去告诉她，我这就来。', `MaleText_loc5`='瑪卡想要見我?...很好。回到她那裡，我會跟著你。', `MaleText_loc7`='¿Mahka quiere verme? Muy bien. Vuelve junto a ella, yo te seguiré.' WHERE `ID`=37756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날쌘발톱이 멈추지 않습니다! 검은창 요새 근처에 있는 랩터 우리로 몰아넣으십시오.', `MaleText_loc4`='迅爪不会停下来！控制它返回暗矛要塞旁边的迅猛龙围栏。', `MaleText_loc5`='迅爪停不下來!將牠拉回靠近暗矛要塞的迅猛龍圍欄那。', `MaleText_loc7`='¡Garrapresta no va a parar! Condúcelo de nuevo al Cercado de Raptores cerca del Bastión Lanza Negra.', `FemaleText_loc1`='날쌘발톱이 멈추지 않습니다! 검은창 요새 근처에 있는 랩터 우리로 몰아넣으십시오.', `FemaleText_loc4`='迅爪不会停下来！控制它返回暗矛要塞旁边的迅猛龙围栏。', `FemaleText_loc5`='迅爪停不下來!將牠拉回靠近暗矛要塞的迅猛龍圍欄那。', `FemaleText_loc7`='¡Garrapresta no va a parar! Condúcelo de nuevo al Cercado de Raptores cerca del Bastión Lanza Negra.' WHERE `ID`=37757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 황폐의 요새 성벽에 컵을 대고 소리를 듣습니다.', `MaleText_loc4`='%s将一只杯子扣在凄凉城堡的墙上，仔细地倾听着。', `MaleText_loc5`='%s將杯子靠在荒寂堡的牆上來聽取另一面的聲音。', `MaleText_loc7`='%s apoya un vaso contra el muro del Bastión de la Desolación y escucha.' WHERE `ID`=37758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 재채기를 하자 몸을 감싼 수풀이 부스럭거립니다.', `MaleText_loc4`='%s打了个喷嚏，吹动了他藏身的灌木丛。', `MaleText_loc5`='%s打了個噴嚏，使他藏身的草叢發出了聲音。', `MaleText_loc7`='%s estornuda agitando el arbusto en el que se está escondiendo.' WHERE `ID`=37759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고마워하며 깽깽거립니다.', `MaleText_loc4`='%s发出期待的叫声。', `MaleText_loc5`='%s發出感激的叫聲。', `MaleText_loc7`='%s gime apreciativamente.' WHERE `ID`=37760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 아래위로 깡충깡충 뜁니다.', `MaleText_loc4`='%s跳来跳去。', `MaleText_loc5`='%s上下彈來彈去。', `MaleText_loc7`='%s bota arriba y abajo.' WHERE `ID`=37761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약간 날카로운 소리를 냅니다.', `MaleText_loc4`='%s发出了一声细小的尖叫。', `MaleText_loc5`='%s發出了小小的尖叫聲。', `MaleText_loc7`='%s deja escapar un gritito.' WHERE `ID`=37762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 뿔을 흔듭니다.', `MaleText_loc4`='%s向你晃动着它的利角。', `MaleText_loc5`='%s向你搖了搖它的角。', `MaleText_loc7`='%s te saluda con su cuerno.' WHERE `ID`=37763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 팔짝팔짝 뛰어 당신을 따라갑니다.', `MaleText_loc4`='%s在你身后蹦跳着。', `MaleText_loc5`='%s跟著你跳著。', `MaleText_loc7`='%s salta detrás de ti.' WHERE `ID`=37764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흥분하여 거의 앞으로 넘어지려고 합니다.', `MaleText_loc4`='%s兴奋得几乎一头栽倒在地。', `MaleText_loc5`='%s因為太興奮差點跌了個狗吃屎。', `MaleText_loc7`='%s casi se cae de morros de la emoción.' WHERE `ID`=37765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 작은 발톱으로 톡톡 소리를 내며 당신에게 뛰어갑니다.', `MaleText_loc4`='%s向你跑过来，小爪子用力敲打着地面。', `MaleText_loc5`='%s跑向你時拍著他的小爪子。', `MaleText_loc7`='%s da unos golpecitos en el suelo con sus pequeñas garras y corre hacia ti.' WHERE `ID`=37766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 이 도시 밖으로 몰아낼 순 없다, 은빛 서약단 폭력배 같으니!', `MaleText_loc4`='你们永远别想把我们赶出城去，银色盟约的混蛋！', `MaleText_loc5`='你們永遠也不可能把我們趕出這座城市，白銀誓盟的暴徒!', `MaleText_loc7`='¡Nunca nos echarás de esta ciudad, $gmatón:matona; de El Pacto de Plata!', `FemaleText_loc1`='우릴 이 도시 밖으로 몰아낼 순 없다, 은빛 서약단 폭력배 같으니!', `FemaleText_loc4`='你们永远别想把我们赶出城去，银色盟约的混蛋！', `FemaleText_loc5`='你們永遠也不可能把我們趕出這座城市，白銀誓盟的暴徒!', `FemaleText_loc7`='¡Nunca nos echarás de esta ciudad, $gmatón:matona; de El Pacto de Plata!' WHERE `ID`=37767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 선리버 추종자들은 다 똑같은 놈들이야.', `MaleText_loc4`='你们这些夺日者下人全都一个样。', `MaleText_loc5`='你們這些奪日者廢物全都是一樣啦。', `MaleText_loc7`='Todos los lacayos Atracasol son iguales.', `FemaleText_loc1`='너희 선리버 추종자들은 다 똑같은 놈들이야.', `FemaleText_loc4`='你们这些夺日者下人全都一个样。', `FemaleText_loc5`='你們這些奪日者廢物全都是一樣啦。', `FemaleText_loc7`='Todos los lacayos Atracasol son iguales.' WHERE `ID`=37768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었구나, $n. 달라란에서 다른 이가 와서 그대와 마찬가지로 오색 용검에 대해 물었다.', `MaleText_loc4`='你来晚了，$n。来自达拉然的另一位访客已经来过这里，同样是为了了解有关远古龙剑的事情。', `MaleText_loc5`='你慢了一步，$n。另一個來自達拉然的訪客同樣問了關於稜彩龍刃的事情。', `MaleText_loc7`='Llegas tarde, $n. Otro visitante de Dalaran vino pidiendo información sobre las mismas hojas prismáticas de los dragones.' WHERE `ID`=37769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 설명을 들어 보니, 앞서 온 이에게 빌려준 책을 보면 그 무기가 무엇인지 쉽게 알 수 있을 듯하구나.', `MaleText_loc4`='根据你的描述我可以断定，我借给那位访客的书能使你很容易地对这把武器做出鉴定。', `MaleText_loc5`='根據你的描述，我很確定我借給訪客的那本書能幫你輕易鑑定出那把武器。', `MaleText_loc7`='Por tu descripción, estoy seguro de que el libro que le presté al visitante podría permitirte identificar con facilidad el arma.' WHERE `ID`=37770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 여기야! 여기! 나무 옆이네.', `MaleText_loc4`='嘘，$n！到这边来！树旁边。', `MaleText_loc5`='嘶～～$n!這裡!樹旁邊。', `MaleText_loc7`='Psssstt... ¡$n! ¡Aquí! Junto al árbol.' WHERE `ID`=37771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 그자에게 가서... 아니, 어쩌면 칼렉고스가 도울 수 있을지도 모르겠군.', `MaleText_loc4`='恐怕，你得找——嗯，或许卡雷苟斯会帮忙。', `MaleText_loc5`='恐怕你得去問 -- 嗯，或許卡雷苟斯能幫得上忙。', `MaleText_loc7`='Me temo que tendrás que preguntar a... Quizá Kalecgos pueda ayudar.' WHERE `ID`=37772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 오색 검의 잔해를 찾았나 보오, 칼렉고스. 그대가 이 손님을 좀 도와주겠소?', `MaleText_loc4`='$n可能已经发现了古剑的碎片，卡雷苟斯。你会帮助我们的到访者吗？', `MaleText_loc5`='$n可能找到一把稜彩之劍的殘骸，卡雷苟斯。你願意提供我們的訪客一些協助嗎?', `MaleText_loc7`='Puede que $n haya encontrado los restos de una espada prismática. ¿Ofrecerías tu ayuda a nuestro visitante?' WHERE `ID`=37773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들이 검을 찾게 도와줘야 한다고 확신하십니까?', `MaleText_loc4`='你确定你应该帮助那些凡人取得那把剑吗？', `MaleText_loc5`='你確定你應該在關於那把劍的事情上協助這些凡人?', `MaleText_loc7`='¿Estás seguro de que deberías estar ayudando a estos mortales en su misión en busca de la espada?' WHERE `ID`=37774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라서스, 이 검은... 아주 오래전에 만들어졌습니다. 그땐 지금과... 상황이 달랐죠.', `MaleText_loc4`='这些武器，克拉苏斯…它们制造于很久以前，那时候的一切…都不同。', `MaleText_loc5`='那些劍，卡薩斯...它們在許久以前所鑄造，那時候的世局...與現在不同。', `MaleText_loc7`='Estas espadas, Krasus... se forjaron hace mucho tiempo, cuando las cosas eran... diferentes.' WHERE `ID`=37775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=37776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<물주머니의 음료를 권하는 카토그>$B$B예전엔 여길 황금길이라 불렀소. 지금은 붉은 피가 흐르고 있지.$B$B난 얼라이언스의 피로 이곳을 물들일 생각이오.', `MaleText_loc4`='<卡索格将水袋递给你。>$B$B我们曾经称这里为黄金大道，$c。今天，它却被鲜血染红。$B$B那全都是联盟的血。', `MaleText_loc5`='<卡爾索格拿出他的皮水袋給你喝些水。>$B$B我們曾經稱此為黃金之路，$c。今天它將會被鮮血所染紅。$B$B聯盟的鮮血，如我會將參與的話。', `MaleText_loc7`='<Karthog te ofrece una bebida en su odre.>$B$BEn otro tiempo a esto lo llamábamos el Camino del Oro, $c. Hoy la sangre lo tiñe de rojo.$B$BSangre de la Alianza en lo que a mí respecta.' WHERE `ID`=37777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 동맹이 검에 담긴 힘을 제대로 제어하지 못하리라 생각하시오?', `MaleText_loc4`='你认为我们的盟友没有能力控制这些剑的力量？', `MaleText_loc5`='你認為我們的盟友無法控制那些劍的力量?', `MaleText_loc7`='¿Crees que nuestros aliados no podrán controlar el poder de las espadas?' WHERE `ID`=37778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침착하시오, 친구. 지금 장군이 온다고 했소?$B$B드디어 전리품을 챙길 기회가 왔군! 난 경비병들을 혼란에 빠뜨리겠소. 하지만 호손을 처치하는 건 당신의 몫이오. 공격할 준비가 됐소?', `MaleText_loc4`='慢一些，朋友。你说将军就要来了？$B$B我的墙上又要增添一件战利品了！我会吸引那些近卫的注意，你的任务就是去干掉霍索恩将军。准备好了吗？', `MaleText_loc5`='慢點，朋友。你說將軍要來了?$B$B這是我立功的大好機會!我會吸引保鑣的注意，但殺死霍桑將軍的工作就交給你的。你準備好要上了嗎?', `MaleText_loc7`='Cálmate, $gamigo:amiga;. ¿Dices que viene el general?$b$b¡Ese sí que es un trofeo digno de mi pared! Yo distraeré a los guardaespaldas, pero te tocará a ti matar al general Hawthorne. ¿Estás $glisto:lista; para entrar en acción?' WHERE `ID`=37779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 카토그. 호드를 위하여!', `MaleText_loc4`='准备好了，卡索格。为了部落！', `MaleText_loc5`='我準備好了，卡爾索格。為了部落!', `MaleText_loc7`='Estoy preparado, Karthog. ¡Por la Horda!', `FemaleText_loc1`='준비됐습니다, 카토그. 호드를 위하여!', `FemaleText_loc4`='准备好了，卡索格。为了部落！', `FemaleText_loc5`='我準備好了，卡爾索格。為了部落!', `FemaleText_loc7`='Estoy preparada, Karthog. ¡Por la Horda!' WHERE `ID`=37780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 용사들은 이런 무기로 오랫동안 악에 대적해 왔소. 그러니, 이 전투에서 저들이 그 검을 사용하지 못하게 할 이유가 없소.', `FemaleText_loc4`='凡间的勇士长久以来都在使用这些武器对抗着邪恶。我认为没有理由不让他们在这场战斗中使用这些剑。', `FemaleText_loc5`='凡人的勇士們曾長期使用這些武器來對抗邪惡。我看不出有什麼理由應該要阻止他們使用那些劍來作戰。', `FemaleText_loc7`='Durante mucho tiempo los campeones mortales han utilizado estas armas para combatir el mal. No veo por qué las espadas no habrían de participar en esta batalla.' WHERE `ID`=37781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때, 적은 우리의 가장 강한 무기를 우리에게 들이댔습니다. 오색 검은 다르리라 생각하시는 이유가 있습니까?', `MaleText_loc4`='我们的敌人曾利用我们最强大的武器来对抗我们。是什么让你觉得这些古剑会有所不同？', `MaleText_loc5`='我們的敵人曾經利用我們最強大的武器來對付我們。你認為稜彩之劍難道會有所不同嗎?', `MaleText_loc7`='Una vez, nuestros enemigos utilizaron nuestra mejor arma en nuestra contra. ¿Qué te hace pensar que será distinto con las espadas prismáticas?' WHERE `ID`=37782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜻을 따르겠습니다, 나의 여왕님. 그들을 방해하지 않겠습니다. 하지만 눈을 떼지는 않을 겁니다.', `MaleText_loc4`='遵从您的意愿，我的女王。我不会阻拦他们，但我会对他们紧密监视。', `MaleText_loc5`='如您所願，吾后。我不會插手妨礙，但我會好好看著他們。', `MaleText_loc7`='Como desees, mi reina. No me interpondré en su camino, pero los vigilaré de cerca.' WHERE `ID`=37783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바짝 붙어 있게. 매복 공격이야. 전투 준비!', `MaleText_loc4`='大家排成密集队形。这是一场伏击。准备武器！', `MaleText_loc5`='大家靠近一點，這是個埋伏。準備戰鬥!', `MaleText_loc7`='Manténganse cerca, chicos. Es una emboscada. ¡A las armas!' WHERE `ID`=37784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 그리할 것이오.', `MaleText_loc4`='我们都会如此。', `MaleText_loc5`='我們都會。', `MaleText_loc7`='Como todos.' WHERE `ID`=37785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다! 전원, 준비...', `MaleText_loc4`='他们来了！所有人，做好准备……', `MaleText_loc5`='他們來了!大家各就各位...', `MaleText_loc7`='¡Vienen! Todo el mundo preparado...' WHERE `ID`=37786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 번개의 축복을!', `MaleText_loc4`='鲜血与雷鸣！', `MaleText_loc5`='鮮血與雷霆!', `MaleText_loc7`='¡Sangre y truenos!' WHERE `ID`=37787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕관표 매혹적인 향수 분사기를 잃어버렸습니다.', `MaleText_loc4`='我把我的皇冠香水瓶弄丢了。', `MaleText_loc5`='我弄丟了我的王冠香水罐。', `MaleText_loc7`='He perdido mi vaporizador de perfume de La Corona.', `FemaleText_loc1`='왕관표 매혹적인 향수 분사기를 잃어버렸어요.', `FemaleText_loc4`='我把我的皇冠香水瓶弄丢了。', `FemaleText_loc5`='我弄丟了我的王冠香水罐。', `FemaleText_loc7`='He perdido mi vaporizador de perfume de La Corona.' WHERE `ID`=37788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕관표 은은한 향수 분사기를 잃어버렸습니다.', `MaleText_loc4`='我把我的皇冠古龙水瓶弄丢了。', `MaleText_loc5`='我弄丟了我的王冠古龍水罐。', `MaleText_loc7`='He perdido mi vaporizador de colonia de La Corona.', `FemaleText_loc1`='왕관표 은은한 향수 분사기를 잃어버렸어요.', `FemaleText_loc4`='我把我的皇冠古龙水瓶弄丢了。', `FemaleText_loc5`='我弄丟了我的王冠古龍水罐。', `FemaleText_loc7`='He perdido mi vaporizador de colonia de La Corona.' WHERE `ID`=37789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시식용 왕관표 초콜릿을 잃어버렸습니다.', `MaleText_loc4`='我把我的皇冠巧克力样本弄丢了。', `MaleText_loc5`='我弄丟了我的王冠巧克力取樣器。', `MaleText_loc7`='He perdido mi muestra de chocolate de La Corona.', `FemaleText_loc1`='시식용 왕관표 초콜릿을 잃어버렸어요.', `FemaleText_loc4`='我把我的皇冠巧克力样本弄丢了。', `FemaleText_loc5`='我弄丟了我的王冠巧克力取樣器。', `FemaleText_loc7`='He perdido mi muestra de chocolate de La Corona.' WHERE `ID`=37790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `MaleText_loc4`='%s点了点头。', `MaleText_loc5`='%s點了點頭。', `MaleText_loc7`='%s asiente.' WHERE `ID`=37791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...고맙소, 마카.', `MaleText_loc4`='……谢谢，玛卡', `MaleText_loc5`='...謝謝你，瑪卡。', `MaleText_loc7`='... Gracias, Mahka.' WHERE `ID`=37792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망갈 생각 마라, 타우라조 학살자! 넌 죽은 목숨이다!', `MaleText_loc4`='我们杀死他了！陶拉祖的屠夫死了！', `MaleText_loc5`='他是我的了!陶拉祖的屠夫死了!', `MaleText_loc7`='¡Es nuestro! ¡El Carnicero de Taurajo está muerto!' WHERE `ID`=37793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 공중에서 흔들리는 시체를 볼 수 있도록 나무에 매달아 놓읍시다. 블러드힐트 장군님께 돌아가 이 소식을 전하시오!', `MaleText_loc4`='我们要让联盟知道他是怎样完蛋的。你先回去，把这个消息告诉血柄督军。', `MaleText_loc5`='我們會把他綁在樹上讓他隨風擺動，直到聯盟發現他。回去向督軍血柄傳達這則消息!', `MaleText_loc7`='Colgaremos su cuerpo de los árboles y lo dejaremos a merced del viento para que lo descubran los de la Alianza. ¡Vuelve e informa al señor de la guerra Sangrastil!' WHERE `ID`=37794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸워라, 형제들이여! $n|1이;가; 낫을 회수하도록 도와야 한다!', `MaleText_loc4`='兄弟们，吸引她们的注意力！让$n能够取回镰刀！', `MaleText_loc5`='纏住他們，兄弟們!讓$n可以奪回鐮刀!', `MaleText_loc7`='¡Manténganlos ocupados, hermanos! ¡Permitan que $n consiga la guadaña!' WHERE `ID`=37795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴! 숲 속으로 후퇴하라!', `MaleText_loc4`='后撤！撤到树林里去！', `MaleText_loc5`='撤退!撤到森林中!', `MaleText_loc7`='¡Retrocedan! ¡Retirense a los bosques!' WHERE `ID`=37796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우라조 학살자는 죗값을 치르게 될 거요.', `MaleText_loc4`='陶拉祖的屠夫将会付出代价。', `MaleText_loc5`='陶拉祖的屠夫會付出代價。', `MaleText_loc7`='El Carnicero de Taurajo pagará.' WHERE `ID`=37797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 나는 놈들이 모두 바다로 물러날 때까지 멈추지 않겠소.', `MaleText_loc4`='在把他们赶回到大海之前，我不会休息，$n。', `MaleText_loc5`='我不會休息，$n。直到他們被趕回海中。', `MaleText_loc7`='No descansaré, $n. No hasta que vuelvan al mar.' WHERE `ID`=37798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네! 그록타르 모가르. 청경채예요. 움. 쩝쩝!', `MaleText_loc4`='明白！Grok''thar More''gar。Bok choy，朋友。呃。达姆达姆！', `MaleText_loc5`='是!呃...洛克塔歐買尬...(獸人語)不勝即亡。吧哺，朋友。嗯，喳喳!', `MaleText_loc7`='¡Sí! Grok''thar More''gar. Bok choy, $gamigo:amiga;. Eh. ¡Zub zub!' WHERE `ID`=37799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 당신은 누구고, 어느 부족 소속입니까?', `MaleText_loc4`='什么？你是谁？你来自于那个氏族？', `MaleText_loc5`='什麼?你是誰?你是哪個氏族的?', `MaleText_loc7`='¿Qué? ¿Quién eres? ¿De qué clan eres?', `FemaleText_loc1`='뭐라고요? 당신은 누구고, 어느 부족 소속입니까?', `FemaleText_loc4`='什么？你是谁？你来自于那个氏族？', `FemaleText_loc5`='什麼?你是誰?你是哪個氏族的?', `FemaleText_loc7`='¿Qué? ¿Quién eres? ¿De qué clan eres?' WHERE `ID`=37800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 어, 일할 준비가 됐어요!', `MaleText_loc4`='遵……遵命。呃。准备工作！', `MaleText_loc5`='OKOK啦!呃...準...準備開始工作!', `MaleText_loc7`='Listo calisto. Eh. ¡Y-yo trabajar!' WHERE `ID`=37801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 오크가 아니야. 첩자다. 얼라이언스 첩자!', `MaleText_loc4`='你不是兽人。你是间谍！联盟的间谍！', `MaleText_loc5`='你不是獸人，你是個間諜!聯盟間諜!', `MaleText_loc7`='No eres un orco. ¡Eres un espía! ¡Un espía de la Alianza!', `FemaleText_loc1`='넌 오크가 아니야. 첩자다. 얼라이언스 첩자!', `FemaleText_loc4`='你不是兽人。你是间谍！联盟的间谍！', `FemaleText_loc5`='你不是獸人，你是個間諜!聯盟間諜!', `FemaleText_loc7`='No eres un orco. ¡Eres un espía! ¡Un espía de la Alianza!' WHERE `ID`=37802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님의 승인을 받은 자만이 태양샘 고원에 들어갈 수 있소.', `MaleText_loc4`='只有取得游侠将军的许可才能进入太阳井高地。', `MaleText_loc5`='只有獲得遊俠將軍許可的人能進入太陽之井高地。', `MaleText_loc7`='Solo aquellos que tienen la aprobación del General Forestal pueden entrar en la Meseta de La Fuente del Sol.', `FemaleText_loc1`='사령관님의 승인을 받은 자만이 태양샘 고원에 들어갈 수 있습니다.', `FemaleText_loc4`='只有取得游侠将军的许可才能进入太阳井高地。', `FemaleText_loc5`='只有獲得遊俠將軍許可的人能進入太陽之井高地。', `FemaleText_loc7`='Solo aquellos que tienen la aprobación del General Forestal pueden entrar en la Meseta de La Fuente del Sol.' WHERE `ID`=37803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 내가 태양샘 고원 안으로 안내하겠소.', `MaleText_loc4`='等你准备好了，我就护送你去太阳之井。', `MaleText_loc5`='等你準備好的時候，我會護送你進入太陽之井。', `MaleText_loc7`='Te escoltaré a La Fuente del Sol cuando estés $glisto:lista;.', `FemaleText_loc1`='준비되면 제가 태양샘 고원 안으로 안내하겠습니다.', `FemaleText_loc4`='等你准备好了，我就护送你去太阳井。', `FemaleText_loc5`='等你準備好的時候，我會護送你進入太陽之井。', `FemaleText_loc7`='Te escoltaré a La Fuente del Sol cuando estés $glisto:lista;.' WHERE `ID`=37804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 요새 보급품을 뒤지며 뭔가를 찾고 있습니다.', `MaleText_loc4`='%s在城堡的供给物资中翻找着什么东西。', `MaleText_loc5`='%s翻找著堡壘的補給品，在找某種東西。', `MaleText_loc7`='%s hojea los suministros de la Fortaleza buscando algo.' WHERE `ID`=37805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양샘 고원에 들어갈 준비가 되었습니다.', `MaleText_loc4`='我已经准备好进入太阳之井了。', `MaleText_loc5`='我準備好進入太陽之井。', `MaleText_loc7`='Estoy listo para ir a La Fuente del Sol.', `FemaleText_loc1`='태양샘 고원에 들어갈 준비가 됐어요.', `FemaleText_loc4`='我已经准备好进入太阳之井了。', `FemaleText_loc5`='我準備好進入太陽之井。', `FemaleText_loc7`='Estoy lista para ir a La Fuente del Sol.' WHERE `ID`=37806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 눈에 저주를 내리겠다, $r!', `MaleText_loc4`='诅咒你的眼睛，$r！', `MaleText_loc5`='你該死的眼睛，$r!', `MaleText_loc7`='¡Malditos sean tus ojos, $r!' WHERE `ID`=37808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제자매여, 다시 불타오르는 태양샘을 보며 내가 느꼈던 감정을 말로 다 표현할 수가 없구나.', `FemaleText_loc4`='兄弟姐妹们，目睹太阳之井再度复苏的感受简直难以言表。', `FemaleText_loc5`='我的兄弟姊妹，看到太陽之井再興的感動是言語無法形容的。', `FemaleText_loc7`='Hermanos, no hay palabras para describir lo que sentí al ver La Fuente del Sol reavivada.' WHERE `ID`=37809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리우스 님! 어둠 순찰자들이 낫을 가지고 갔습니다! 우리가 도착하기 전에 놈들이 먼저 손을 쓴 것 같습니다.', `MaleText_loc4`='达利乌斯！黑暗游侠得到了那把镰刀！他们抢在我们之前得到了它。', `MaleText_loc5`='達瑞亞斯!鐮刀在黑暗遊俠手裡!他們在我們到之前就拿到手了。', `MaleText_loc7`='¡Darius! ¡Las Forestales Oscuras tienen la guadaña! La consiguieron antes de que pudiéramos hacernos con ella.' WHERE `ID`=37810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 그 순간, 성스러운 빛은 내가 저지른 끔찍한 행동들이 진실로 어떠한 것이었는지 보여주었다.', `FemaleText_loc4`='在那一刻，圣光为我揭示出我所犯下的种种罪过的真相。', `FemaleText_loc5`='那時，聖光向我揭露出我所作所為的可怕真相。', `FemaleText_loc7`='En ese momento, la Luz me reveló la verdad de las cosas tan terribles que había hecho.' WHERE `ID`=37811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 따르겠습니다!', `MaleText_loc4`='该结束了！', `MaleText_loc5`='會完成的!', `MaleText_loc7`='¡Inmediatamente!' WHERE `ID`=37812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 어두운 길을 걸었다. 그중에서도 내가 걸어온 길이 가장 어두웠지.', `FemaleText_loc4`='我们的人民走上了一条黑暗的道路，而我在这条路上走得最远。', `FemaleText_loc5`='我們的人民走在黑暗之途上，而我則是其中最黑暗的。', `FemaleText_loc7`='Nuestro pueblo ha caminado a oscuras y mi camino ha sido uno de los más terribles.' WHERE `ID`=37813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 성스러운 빛은 내가 길을 잃지 않았음을 보여주었다. 과거의 모든 일, 내가 저지른 악행을 딛고 살아남을 수 있게 힘을 주었다.', `FemaleText_loc4`='但圣光使我明白我并没有迷失。它帮助我找到力量，使我在经历许多后仍可幸存，即使我曾犯下如此重罪。', `FemaleText_loc5`='但聖光讓我明白我並未迷失。在這一切的怨恨和我自己所帶來的邪惡中，祂讓我找到力量得以倖存。', `FemaleText_loc7`='Pero la Luz me mostró que no estaba perdida. Me ayudó a tener fuerzas para sobrevivir a pesar de lo que había ocurrido y de todo el mal que había hecho.' WHERE `ID`=37814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그것은 우리 신도레이가 모두 나누는 힘이다. 그 힘이, 우리를 파괴한 중독을 떨쳐 버리게 해줄 것이다.', `FemaleText_loc4`='那是一种所有辛多雷成员共享的力量。我们需要这种力量来摆脱蹂躏我们人民的魔瘾。', `FemaleText_loc5`='這是我們辛多雷所共享的力量。我們也需要這股力量，讓大家能從摧殘我們同胞的成癮症狀中解放出來。', `FemaleText_loc7`='Es una fuerza que todos los sin''dorei compartimos. Es una fuerza de necesitaremos para liberarnos de la adición que asola a nuestro pueblo.' WHERE `ID`=37815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이는 지금껏 마주한 그 어떤 전투보다도 힘든 싸움이리라. 그러나 우리가 영광을 되찾는 그날까지, 우리의 결의와 태양샘의 힘이 버팀목이 돼줄 것이다.', `FemaleText_loc4`='这场将是我们遭遇过的最残酷的一场战斗，但我们的决心和太阳之井的力量将始终支撑我们重返巅峰。', `FemaleText_loc5`='這將會是我們從未面對過的艱難戰鬥，但我們的決心與太陽之井的力量將會支持我們，直到我們能重新恢復屬於我們的光榮。', `FemaleText_loc7`='Será la batalla más dura a la que nos hayamos enfrentado, pero nuestra decisión y el poder de La Fuente del Sol nos sustentarán hasta que hayamos restaurado nuestra grandeza.' WHERE `ID`=37816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옳은 말씀입니다, 여군주님. 우리 신도레이는 자유와 영광을 되찾을 것입니다!', `MaleText_loc4`='说得好，我的女王。我们辛多雷会重获自由并再度强大！', `MaleText_loc5`='說得好，女士。我們辛多雷將會重獲自由，而我們將會重返榮耀!', `MaleText_loc7`='¡Bien dicho, mi señora! Los sin''dorei seremos libres y volveremos a ser grandes.', `FemaleText_loc1`='옳은 말씀입니다, 여군주님. 우리 신도레이는 자유와 영광을 되찾을 것입니다!', `FemaleText_loc4`='说得好，我的女王。我们辛多雷会重获自由并再度强大！', `FemaleText_loc5`='說得好，女士。我們辛多雷將會重獲自由，而我們將會重返榮耀!', `FemaleText_loc7`='¡Bien dicho, mi señora! Los sin''dorei seremos libres y volveremos a ser grandes.' WHERE `ID`=37817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 친구. 티키 표적을 박살 냅시다!', `MaleText_loc4`='耶，兄弟。去敲烂几个蒂基面具假人吧！', `MaleText_loc5`='是啊，老兄。讓我們敲爛一些提基頭顱吧!', `MaleText_loc7`='Sí, hombre. ¡Vamos a partir algunos tikis!' WHERE `ID`=37818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 부하들을 배치하게, 토비아스. 절대 낫이 포세이큰의 손에 넘어가게 할 수는 없네!!', `MaleText_loc4`='立刻让我们的人就位，托比亚斯。我们不能让镰刀落到被遗忘者的手上！！', `MaleText_loc5`='托比亞斯，馬上讓你的人各就各位。我們不能讓鐮刀落入被遺忘者的手裡!!', `MaleText_loc7`='Coloca a nuestros hombres en posición inmediatamente, Tobias. ¡No podemos permitir que la guadaña caiga en manos de los Renegados!' WHERE `ID`=37819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀하신 분들께 아룁니다. 쿠엘델라를 지닌 자, $n입니다.', `MaleText_loc4`='我的主人和女王，请允许我向您们介绍$n，奎尔德拉的持有者。', `MaleText_loc5`='高貴的大人與女士們，請容我介紹$n，奎爾德拉的持有者。', `MaleText_loc7`='Señoras y señores, les presento a $N, $gportador:portadora; de Quel''Delar.' WHERE `ID`=37820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽의 훈련장에 직업 상급자가 있네. 검은창 부족의 자부심을 보여주게.', `MaleText_loc4`='$n。祖尼。你们可以在东边的训练场找到你的训练师。不要给暗矛部族丢脸。', `MaleText_loc5`='$n。朱尼。你們會在東邊的訓練區那找到你的訓練師。為暗矛帶來榮耀。', `MaleText_loc7`='Tu entrenador está en el campo de entrenamiento del este. Enorgullece a la Lanza Negra.' WHERE `ID`=37821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르둘에게 실리시드 서식지 위에는 요새를 짓지 말라고 했건만.$B$B이 크로골의 말을 듣지 않았어!', `MaleText_loc4`='我告诉过加杜尔，不要在异种生物的巢穴上建造城堡。$B$B他会听克劳格的话吗？不！', `MaleText_loc5`='我跟迦爾杜爾說不要在異種穴上面建造堡壘。$B$B他有聽克羅勾的話嗎?沒有!', `MaleText_loc7`='Le dije a Gar''dul que no construyera una fortaleza sobre una colonia de silítidos.$B$B¿Acaso hizo caso a Crawgol? ¡No!' WHERE `ID`=37822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노는... 거야?', `MaleText_loc4`='玩吗？玩吗？', `MaleText_loc5`='玩耍時間?', `MaleText_loc7`='¿Hora de divertirse?' WHERE `ID`=37823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠, 내가 했어!', `MaleText_loc4`='哈哈，我做到了！', `MaleText_loc5`='爹地，我做到了!', `MaleText_loc7`='¡Papi, lo logré!' WHERE `ID`=37824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나빠, 나빠, 나빠!', `MaleText_loc4`='死吧，死吧，死！', `MaleText_loc5`='死，死，死!', `MaleText_loc7`='¡Muerto, muerto, muerto!' WHERE `ID`=37825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 빠...', `MaleText_loc4`='我的妈呀！', `MaleText_loc5`='爹...地...', `MaleText_loc7`='Pa... pi...' WHERE `ID`=37826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안 놀거야!', `MaleText_loc4`='你……玩完了！', `MaleText_loc5`='Fun time over!', `MaleText_loc7`='¡Se acabó la hora de divertirse!' WHERE `ID`=37827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 속이 안 좋아...', `MaleText_loc4`='我有点不舒服……*呕*', `MaleText_loc5`='我感覺不舒服...', `MaleText_loc7`='Me siento mal…' WHERE `ID`=37829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나빠! 너 구리구리 죽였어! 너 싫어!', `MaleText_loc4`='不！你杀了大臭！你赔！', `MaleText_loc5`='不!你殺了臭皮!你要付出代價!', `MaleText_loc7`='¡No! ¡Has matado a Apestoso! ¡Paga!' WHERE `ID`=37830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아아아아아!', `MaleText_loc4`='WEEEEEE!', `MaleText_loc5`='耶～～～～～～!', `MaleText_loc7`='¡WEEEEEEE!' WHERE `ID`=37831;
