UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠가 너가지고 새 장난감 만들 거다!', `MaleText_loc4`='我会拿你做新玩具！', `MaleText_loc5`='爹地會把你做成新玩具!', `MaleText_loc7`='¡Papi los convertirá en juguetes!' WHERE `ID`=37833;
