UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식이에요, 여러분! 아제로스의 모든 생명체를 파괴할 역병을 완성했어요!', `MaleText_loc4`='喜讯，各位！我想我已经研制出一种能够毁灭艾泽拉斯的药剂了！', `MaleText_loc5`='大夥聽著，好消息!我想我研發出一種瘟疫足以毀滅艾澤拉斯上所有的生命!', `MaleText_loc7`='¡Buenas noticias, amigos! Creo que he perfeccionado una plaga que destruirá toda la vida en Azeroth.' WHERE `ID`=37838;
