UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 소식이에요, 여러분... 전 살 것 같지 않아요...', `MaleText_loc4`='噩耗，各位……我觉得我要失败了……', `MaleText_loc5`='大夥聽著，壞消息...我想我大概撐不下去了...', `MaleText_loc7`='Malas noticias, amigos... No creo que sobreviva...' WHERE `ID`=37841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 소식이에요, 여러분!', `MaleText_loc4`='重大喜讯！各位！', `MaleText_loc5`='大夥聽著，超級好消息!', `MaleText_loc7`='¡Excelentes noticias, amigos!' WHERE `ID`=37842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 평범한 가스 구름 같지만, 잘 보세요. 평범한 가스 구름이 아니거든요!', `MaleText_loc4`='这是普通的毒云，但请千万小心，这毒云其实并不普通！', `MaleText_loc5`='看似一般的毒氣雲，但罩子放亮點，因為這可不是普通的毒氣雲!', `MaleText_loc7`='¡Una nube de gas normal, pero cuidado porque no es una nube de gas normal!' WHERE `ID`=37843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 아무 느낌도 없군요. 엥?! 이건 어디서 온 거지요?', `MaleText_loc4`='嗯，什么感觉也没有。什么？！这是哪儿来的？', `MaleText_loc5`='嗯，我看不出來有何不同。啊?!這些東西從哪來的?', `MaleText_loc7`='Mmm, no siento nada. ¿¡Qué!? ¿De dónde salió eso?' WHERE `ID`=37844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 맛은... 체리군요! 오! 이런 실례!', `MaleText_loc4`='味道像……樱桃！哦！见笑了！', `MaleText_loc5`='嚐起來像是...櫻桃!喔!抱歉!', `MaleText_loc7`='¡Sabe a... cereza! ¡Ay! ¡Disculpen!' WHERE `ID`=37845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수액괴물 둘이 방 하나에 있네요. 짜잔! 정말 재미있겠지요?', `MaleText_loc4`='两泥，一室。会有无限惊喜哦！', `MaleText_loc5`='兩個軟泥、一個房間。超多令人開心的可能性!', `MaleText_loc7`='Dos babas, un cuarto. ¡Tantas posibilidades excelentes!' WHERE `ID`=37846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍한 소식이에요, 여러분. 썩은얼굴이 죽었답니다. 그런데 끝내주는 소식도 있어요, 여러분! 썩은얼굴은 죽어서 수액을 남겼답니다! 아니? 제가 이런 명언을 알다니... 놀랄 노자예요!', `MaleText_loc4`='惊天噩耗，我作的腐面，刚刚死了。但重大喜讯，他留下了，大量软泥！哇，我居然还有这么出众的诗歌才华……雷死了！', `MaleText_loc5`='大夥聽著，糟糕的壞消息。腐臉死了，但有個超級好消息!他留下一大堆軟泥供我使用!什麼?我竟沒發現自己是個詩人...太嚇人了!', `MaleText_loc7`='Pésimas noticias, amigos. Carapútrea ha muerto, pero ¡buenas noticias, amigos! ¡Me ha dejado baba que necesitaba! ¿Qué? Soy un poeta y no lo sabía... ¡Asombroso!' WHERE `ID`=37847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 구린속. 언제나 제일 좋아했어. 썩은얼굴 다음으로 말이야. 좋은 소식이라면 네가 가스를 많이 남겨서 내가 맛볼 수 있다는 거야!', `MaleText_loc4`='哦烂肠，你是我的最爱，仅次于腐面。不过你的死给我留下了那么多毒气，我都快被熏死了！', `MaleText_loc5`='喔，膿腸，你永遠都是我的最愛 -- 僅次於腐臉。好消息是你留下那麼多毒氣。我幾乎都可以嚐到它的味道!', `MaleText_loc7`='Oh, Panzachancro, eras mi preferido... junto a Carapútrea. La buena noticia es que has dejado tanto gas, ¡que casi puedo saborearlo!' WHERE `ID`=37848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 큰 소리로 울부짖습니다!', `MaleText_loc4`='%s大声哭嚎起来！', `MaleText_loc5`='%s發出一聲巨大的咆哮!', `MaleText_loc7`='%s emite un aullido agudo y penetrante.', `FemaleText_loc1`='%s|1이;가; 큰 소리로 울부짖습니다!', `FemaleText_loc4`='%s大声哭嚎起来！', `FemaleText_loc5`='%s發出一聲巨大的咆哮!', `FemaleText_loc7`='%s emite un aullido agudo y penetrante.' WHERE `ID`=37849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열기가 밀려온다. 정령들의 공격을 막아야 한다! 록타르 오가르!', `MaleText_loc4`='高潮到了。准备抵御元素生物的进攻！Lok''tar ogar！', `MaleText_loc5`='熱氣湧現。準備防禦元素的攻擊!為了部落!', `MaleText_loc7`='Llega el calor. Preparaos para defenderos del ataque de los elementales. ¡Lok''tar ogar!', `FemaleText_loc1`='열기가 밀려온다. 정령들의 공격을 막아야 한다! 록타르 오가르!', `FemaleText_loc4`='高潮到了。准备抵御元素生物的进攻！Lok''tar ogar！', `FemaleText_loc5`='熱氣湧現。準備防禦元素的攻擊!為了部落!', `FemaleText_loc7`='Llega el calor. Preparaos para defenderos del ataque de los elementales. ¡Lok''tar ogar!' WHERE `ID`=37850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하라, 형제자매여. 정령들이 우리 도시를 공격한다. 전투를 준비하라!', `MaleText_loc4`='兄弟姐妹们，做好准备。元素生物集结在一起攻打我们的城池。准备战斗！', `MaleText_loc5`='做好準備，兄弟姊妹們。元素共謀要對抗我們的城市。準備作戰!', `MaleText_loc7`='Preparaos, hermanos. Los elementos conspiran contra nuestra ciudad. ¡Preparaos para la batalla!', `FemaleText_loc1`='준비하라, 형제자매여. 정령들이 우리 도시를 공격한다. 전투를 준비하라!', `FemaleText_loc4`='兄弟姐妹们，做好准备。元素生物集结在一起攻打我们的城池。准备战斗！', `FemaleText_loc5`='做好準備，兄弟姊妹們。元素共謀要對抗我們的城市。準備作戰!', `FemaleText_loc7`='Preparaos, hermanos. Los elementos conspiran contra nuestra ciudad. ¡Preparaos para la batalla!' WHERE `ID`=37851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 힘을 얻었다! 이세라여, 더러운 생명들에 안식을 내릴 수 있도록 은혜를 베푸소서!', `MaleText_loc4`='我获得了新生！伊瑟拉的恩泽赐予我消灭邪恶的力量！', `MaleText_loc5`='我重生了!伊瑟拉賦予我讓那些邪惡生物安眠的力量!', `MaleText_loc7`='¡ESTOY RENOVADA! ¡Ysera, haz que estas asquerosas criaturas descansen, por favor!' WHERE `ID`=37852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 빛나는 천재성이 고작 상자 안에 담길 수는 없다고!$B$B잠깐, 여기가 아즈샤라 아니야?! 여긴 어디지? 저건 휴화산이로군!$B$B지금 난 무역왕을 만나고 싶은 마음 반, 꼬꼬 알을 무기로 만들 마음 반이야!', `MaleText_loc4`='我的天才不可能被束缚在一个胶囊里！$B$B等等，这里不是艾萨拉？！这是什么地方？这是一座休眠火山！$B$B我本来有些想去找贸易大王的！但我也在考虑将肉鸡蛋实现武器化的可能！', `MaleText_loc5`='不能讓我的天賦被侷限在一個盒子裡!$B$B等等，這裡不是艾薩拉?!這是哪裡?那是一座休眠的火山!$B$B一半的我想加入貿易親王!但另一半的我則思考著將咯雞卵武器化的可能性!', `MaleText_loc7`='¡Mi genio no se puede contener en una caja!$B$B¡¿Espera, esto no es Azshara? ¿Qué es este lugar? ¡Un volcán inactivo!$B$B¡La mitad de mi mente quiere que vaya a unirme al Príncipe mercante! ¡La otra mitad está considerando convertir en armas los huevos de la cloqueadora!' WHERE `ID`=37853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상자 마을 안에 들어갈 때, 아즈샤라의 어딘가로 보내진다고 들었어요. 여기가 아즈샤라인가요?$B$B궁금한 게 있는데요. 상자 마을은 누가 준비했죠? 먹고 살 음식을 넉넉하게 공급하나요?! 달랑 닭고기처리기 하나만 있는데요!$B$B"초소형" 기계닭이 어떻게 만들어지는지 모두 다 안단 말이에요.', `FemaleText_loc4`='当我们被像行李一样打包运到胶囊镇里的时候，他们对我们说的是我们将受雇前往艾萨拉的某地工作。这是艾萨拉吗？$B$B我问你：是谁搞出了胶囊镇，却又不在里面准备好足够的食物？！某个肮脏的变鸡器？！$B$B我们都知道机动战鸡的微型化是怎么实现的。', `FemaleText_loc5`='當我們被派到盒中鎮時，他們跟我們說我們會被分配到艾薩拉的某個地方。這就是艾薩拉嗎?$B$B我問你，有哪個白癡會準備一個盒中鎮卻不提供足夠的糧食?!就一個原料的雞肉料理機?!$B$B我們都知道「微型」機械小雞是如何運作的。', `FemaleText_loc7`='Cuando nos metieron en la Ciudad de Bolsillo, nos dijeron que nos reasentarían en alguna parte de Azshara. ¿Esto es Azshara?$b$bY yo me pregunto: ¿a quién se le ocurre preparar una Ciudad de Bolsillo sin proveer la comida suficiente para vivir? ¡Un mísero Pollotizador!$B$BTodos sabemos cómo resultó el "micro" mecapollo.' WHERE `ID`=37854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모그레인 대영주님, 저를 위해 어둠의 칼날도끼를 재련해주셨으면 합니다.', `MaleText_loc4`='大领主莫格莱尼，我必须请你为我重新铸造影锋。', `MaleText_loc5`='我必須請你替我重鑄暗影之鋒，大領主莫格萊尼。', `MaleText_loc7`='Debo pedirte que vuelvas a forjar el Filo de las Sombras para mí, alto señor Mograine.', `FemaleText_loc1`='모그레인 대영주님, 저를 위해 어둠의 칼날도끼를 재련해주셨으면 해요.', `FemaleText_loc4`='大领主莫格莱尼，我必须请你为我重新铸造影锋。', `FemaleText_loc5`='我必須請你替我重鑄暗影之鋒，大領主莫格萊尼。', `FemaleText_loc7`='Debo pedirte que vuelvas a forjar el Filo de las Sombras para mí, alto señor Mograine.' WHERE `ID`=37855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오! 불타오른다!', `MaleText_loc4`='喔！瞧这烧的！', `MaleText_loc5`='耶!體會燃燒的感覺吧!', `MaleText_loc7`='¡Guaaaau! ¡Siente el calor!' WHERE `ID`=37856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨겁구나!', `MaleText_loc4`='真烫！', `MaleText_loc5`='烤熟了!', `MaleText_loc7`='¡Crujiente!' WHERE `ID`=37857;
