UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험할 정도로 매력적이야!', `MaleText_loc4`='真性感啊，就是太痛了！', `MaleText_loc5`='真是性感到無可救藥!', `MaleText_loc7`='¡Es tan sexy que duele!' WHERE `ID`=37860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내주는 운동이군.', `MaleText_loc4`='最好的永远是最有效的。', `MaleText_loc5`='有史以來...最棒的...健身。', `MaleText_loc7`='El mejor. Entrenamiento. De la Historia.' WHERE `ID`=37861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나도 활활 타올라!', `MaleText_loc4`='烧得真漂亮！', `MaleText_loc5`='燒得真爽!', `MaleText_loc7`='¡Quema tan bien!' WHERE `ID`=37862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아직 여자친구 없어요.', `MaleText_loc4`='是的，女士们，我还是单身。', `MaleText_loc5`='沒錯，小姐們，我還是單身。', `MaleText_loc7`='Sí, señoras, estoy soltero.' WHERE `ID`=37863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사나운 불의 정령 처치: $4582W/$4862W', `MaleText_loc4`='已杀死狂怒的火元素：$4582W/$4862W', `MaleText_loc5`='擊殺的狂烈火元素:$4582W/$4862W', `MaleText_loc7`='Elementales de fuego furiosos matados: $4582W/$4862W' WHERE `ID`=37864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 침입해 온다. 오그리마를 방어하라!', `MaleText_loc4`='元素生物正在入侵这里地区。准备保卫奥格瑞玛！', `MaleText_loc5`='元素開始入侵這一區。準備保衛奧格瑪!', `MaleText_loc7`='Los elementales están invadiendo la zona. ¡Preparaos para defender Orgrimmar!' WHERE `ID`=37865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 불의 정령 처치: $4584W/$4863W', `MaleText_loc4`='已杀死灼热的火元素：$4584W/$4863W', `MaleText_loc5`='擊殺的灼熱火元素:$4584W/$4863W', `MaleText_loc7`='Elementales de fuego abrasador matados: $4584W/$4863W' WHERE `ID`=37866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강력한 정령들이 공격해 들어온다. 불길도 마구 번지고 있다! 정령들을 처치하고 불길을 잡아라!', `MaleText_loc4`='现在发动进攻的是一波更强大的元素生物，不过那些火元素已经失控！清除那些元素生物，控制住那些火元素。', `MaleText_loc5`='新出現、更強大的元素正在攻擊，但火勢已經失去!控制消滅那些元素，並且控制火勢。', `MaleText_loc7`='Hay nuevos elementales más fuertes atacando, pero los fuegos han perdido el control. Acaba con los elementales y controla esos fuegos.' WHERE `ID`=37867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$B$B서둘러라. 도시 네 모퉁이의 얼음 기둥을 사용해 정령계로 차원문을 열고, 이 공격을 주동한 존재를 소환해라.$B$B승리하려면 각 얼음 기둥을 동시에 작동시켜야 한다.', `MaleText_loc4`='$B$B抓紧时间，使用城中每个角落的寒冰之石打开一道通往元素位面的传送门并召唤那些要为此事负责的家伙。$B$B同时激活所有的寒冰之石以确保胜利的取得。', `MaleText_loc5`='$B$B快，在城市的每個角落使用冰石開啟通往元素界域的傳送門，並召喚那些可信賴的盟友。$B$B你必須同時啟動每一顆石頭已確保勝利。', `MaleText_loc7`='$B$BRápido, utiliza las piedras de hielo en cada esquina de la ciudad para abrir portales al plano elemental e invocar a los responsables.$b$bTendrás que activar las piedras a la vez para asegurarte la victoria.' WHERE `ID`=37868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 오그리마를 집어삼키려고 합니다. 저기 뛰어들 만큼 강하시다면 말리지는 않겠습니다. 실력이 모자란다고 생각하면 도시에 들어가지 마시고 저희 손에 맡겨 두십시오.', `MaleText_loc4`='大火要将奥格瑞玛全部吞噬。如果你认为自己强大到足以进去，那么请便。否则，就留在城外，让我们来对付它。', `MaleText_loc5`='熊熊大火威脅著奧格瑪的存亡。如果你覺得你的能力強到可以進去，請便。不然，就站在城外面讓我們來處理。', `MaleText_loc7`='El fuego amenaza con destruir todo Orgrimmar. Si crees que eres suficientemente fuerte para ir allí, adelante. De lo contrario, puedes quedarte fuera de la ciudad y dejar que nos encarguemos nosotros.', `FemaleText_loc1`='불길이 오그리마를 집어삼키려고 합니다. 저기 뛰어들 만큼 강하시다면 말리지는 않겠습니다. 실력이 모자란다고 생각하면 도시에 들어가지 마시고 저희 손에 맡겨 두십시오.', `FemaleText_loc4`='大火要将奥格瑞玛全部吞噬。如果你认为自己强大到足以进去，那么请便。否则，就留在城外，让我们来对付它。', `FemaleText_loc5`='熊熊大火威脅著奧格瑪的存亡。如果你覺得你的能力強到可以進去，請便。不然，就站在城外面讓我們來處理。', `FemaleText_loc7`='El fuego amenaza con destruir todo Orgrimmar. Si crees que eres suficientemente fuerte para ir allí, adelante. De lo contrario, puedes quedarte fuera de la ciudad y dejar que nos encarguemos nosotros.' WHERE `ID`=37869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 옆에 와서 무릎을 좀 굽혀주겠습니까? 마지막 기습 공격 도중 그만 총에 맞고 말았습니다.$B$B<자세를 바꾸려다가 고통에 신음하는 갠. 그의 왼쪽 손은 상처를 움켜잡고 있으며 떨리는 손가락 사이로 피가 흘러내립니다.>$B$B드워프가 처음 불모의 땅을 침략했을 땐, 놈들의 굴착기를 공격하거나 장비를 망가뜨리며 스스로 만족하곤 했습니다. 기회가 있을 때 치명타를 날렸어야 했는데 말이지요.', `MaleText_loc4`='靠我近点，朋友。我在上一次袭击中被一颗子弹射中了。$B$B<甘恩努力想挪动一下身体，却只是痛苦地呻吟了一声。他的左手按在一处伤口上。血不断地从他的指缝间涌出。>$B$B当矮人们最初入侵贫瘠之地的时候，我只是满足于骚扰他们的挖掘工，破坏他们的设备。我真应该趁有机会的时候对他们发动致命的打击。', `MaleText_loc5`='跪在我旁邊，朋友。我在上次的掠奪中被打到了一槍。$B$B<加恩想要變換姿勢時發出了痛苦的聲音。他的左手緊握著一個傷口，鮮血從他顫抖的指縫中流了出來。>$B$B當矮人第一次入侵貧瘠之地時，我手下留情地只騷擾了他們的礦工和摧毀了他們的器具。我真應該在那時殺幾個才對。', `MaleText_loc7`='Arrodíllate junto a mí, colega. Me dio una bala durante el último encuentro.$B$B<Gann gime de dolor mientras trata de cambiar de posición. Su mano izquierda aprieta una herida y la sangre se amontona entre sus temblorosos dedos.>$B$BLa primera vez que los enanos invadieron Los Baldíos, me contenté con hostigar a sus excavadores y sabotear su equipo. Debería haber asestado un golpe mortal cuando tuve la oportunidad.' WHERE `ID`=37870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위질 슬립섀도, 위장의 대가!', `MaleText_loc4`='维兹尔·滑影，伪装大师！', `MaleText_loc5`='偽裝大師:維吉爾·滑影。', `MaleText_loc7`='¡Weezil Sombraligera, maestro del disfraz!' WHERE `ID`=37871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_creature_disease_02.blp:16|t당신은 |cFF00FF00돌연변이 전염병|r에 걸렸습니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你获得了|cFF00FF00畸变感染|r效果！', `MaleText_loc5`='|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你得了|cFF00FF00突變感染!|r', `MaleText_loc7`='|TInterfaceIconsability_creature_disease_02.blp:16|tTienes |cFF00FF00¡Infección mutada!|r' WHERE `ID`=37872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 필멸의 존재여, 달라란에 있는 신비술사 티발린과 이야기하기 바란다. 그가 선리버와 협상해 책을 볼 수 있게 해줄 게다.', `MaleText_loc4`='拜托你了，凡人，同达拉然的奥术师泰拜林谈一谈。他可能有办法和夺日者进行交涉，让你看一看那本书。', `MaleText_loc5`='請吧凡人，去和達拉然的秘法師泰巴林談談。他或許能跟奪日者交涉以取得那本書。', `MaleText_loc7`='Por favor, mortal, busca al arcanista Tybalin en Dalaran. Puede que él pueda negociar con los Atracasol para acceder al libro.' WHERE `ID`=37873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 필멸의 존재여, 달라란에 있는 마법학자 하소렐과 이야기하기 바란다. 그가 은빛 서약단과 협상해 책을 볼 수 있게 해줄 게다.', `MaleText_loc4`='拜托你了，凡人，在达拉然找到魔导师哈瑟尔。他可能有办法和银色盟约进行交涉，让你看一看那本书。', `MaleText_loc5`='請吧凡人，去和達拉然的博學者哈索瑞爾談談。他或許能跟白銀誓盟交涉以取得那本書。', `MaleText_loc7`='Por favor, mortal, busca al magister Hathorel en Dalaran. Puede que él pueda negociar con El Pacto de Plata para acceder al libro.' WHERE `ID`=37874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 나를 도와다오. 더는... 더는 저들을 붙들어 둘 수 없다. 이 상처를 치유해다오!', `MaleText_loc4`='英雄们，请快些帮助我，我……我快要抵挡不住他们了。请治疗我的伤口！', `MaleText_loc5`='英雄們，協助我。我...我無法繼續擋住他們了。你們必須治療我的傷勢!', `MaleText_loc7`='Héroes, ayúdenme. No... no puedo mantenerlos alejados por mucho más tiempo. ¡Tienen que sanar mis heridas!' WHERE `ID`=37875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드의 꿈으로 가는 차원문을 열어두었다. 너희의 구원은 그 안에 있다...', `MaleText_loc4`='我打开了进入梦境的传送门。英雄们，救赎就在其中……', `MaleText_loc5`='我打開了一道傳送門通往夢境。你們的救贖就在其中，英雄們...', `MaleText_loc7`='He abierto un portal al Sueño. Su salvación está dentro, héroes…' WHERE `ID`=37876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 버티지는 못하겠다.', `MaleText_loc4`='我坚持不了多久了。', `MaleText_loc5`='我支持不了多久了。', `MaleText_loc7`='No aguantaré mucho más.' WHERE `ID`=37877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 돌아오고 있다. 영웅들이여, 계속 싸워라!', `MaleText_loc4`='我的力量回来了。坚持，英雄们！', `MaleText_loc5`='我的力量正在恢復。加把勁，英雄們!', `MaleText_loc7`='Mi fuerza vuelve. ¡Sigan así, héroes!' WHERE `ID`=37878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 도망칠 순 없을 게다!', `MaleText_loc4`='我们不会让你轻易逃脱的！', `MaleText_loc5`='你沒這麼簡單就擺脫我們!', `MaleText_loc7`='¡No escaparán de nosotros tan fácilmente!', `FemaleText_loc1`='쉽게 도망칠 순 없을 게다!', `FemaleText_loc4`='我们不会让你轻易逃脱的！', `FemaleText_loc5`='你沒這麼簡單就擺脫我們!', `FemaleText_loc7`='¡No escaparán de nosotros tan fácilmente!' WHERE `ID`=37879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 부지하고 도망칠 수 있을 줄 알았더냐?', `MaleText_loc4`='你认为你能活着逃走吗？', `MaleText_loc5`='你以為你能逃出活命?', `MaleText_loc7`='¿Pensabas que escaparías con vida?', `FemaleText_loc1`='목숨을 부지하고 도망칠 수 있을 줄 알았더냐?', `FemaleText_loc4`='你认为你能活着逃走吗？', `FemaleText_loc5`='你以為你能逃出活命?', `FemaleText_loc7`='¿Pensabas que escaparías con vida?' WHERE `ID`=37880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 시선을 고정합니다!', `MaleText_loc4`='%s将目光指向了你！', `MaleText_loc5`='%s盯著你看!', `MaleText_loc7`='¡%s pone su mirada en ti!', `FemaleText_loc1`='%s|1이;가; 당신에게 시선을 고정합니다!', `FemaleText_loc4`='%s将目光指向了你！', `FemaleText_loc5`='%s盯著你看!', `FemaleText_loc7`='¡%s pone su mirada en ti!' WHERE `ID`=37881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불 꺼짐: $4857W/$4864W', `MaleText_loc4`='已熄灭火焰：$4857W/$4864W', `MaleText_loc5`='已滅的火源:$4857W/$4864W', `MaleText_loc7`='Fuegos apagados: $4857W/$4864W' WHERE `ID`=37882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한 도전은 아닙니다만, 당신을 받아들이기 전에 구덩이에서의 일을 처리할 수 있는지 알아야겠습니다.', `MaleText_loc4`='这不算什么大挑战，朋友，但在接纳你之前，我们要确认你有能力对付这个地穴里的东西。', `MaleText_loc5`='這不是什麼很大的挑戰，老兄，但我們必須確定你能力夠才能帶你進去。', `MaleText_loc7`='Eh''to no es un gran reto, tron, pero tenemos que saber que nueh''tros reclutas pue''en sobrevivir en el foso antes de aceptah''los.', `FemaleText_loc1`='대단한 도전은 아닙니다만, 당신을 받아들이기 전에 구덩이에서의 일을 처리할 수 있는지 알아야겠습니다.', `FemaleText_loc4`='这不算什么大挑战，朋友，但在接纳你之前，我们要确认你有能力对付这个地穴里的东西。', `FemaleText_loc5`='這不是什麼很大的挑戰，老兄，但我們必須確定你能力夠才能帶你進去。', `FemaleText_loc7`='Eh''to no es un gran reto, tron, pero tenemos que saber que nueh''tros reclutas pue''en sobrevivir en el foso antes de aceptah''los.' WHERE `ID`=37884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전에 임할 준비가 되었습니다.', `MaleText_loc4`='我已经准备好面对挑战了。', `MaleText_loc5`='我準備好接受挑戰了。', `MaleText_loc7`='Estoy listo para enfrentarme a mi reto.', `FemaleText_loc1`='도전에 임할 준비가 되었어요.', `FemaleText_loc4`='我已经准备好面对挑战了。', `FemaleText_loc5`='我準備好接受挑戰了。', `FemaleText_loc7`='Estoy lista para enfrentarme a mi reto.' WHERE `ID`=37885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구덩이에 들어가서 당신의 기술을 보여주십시오.', `MaleText_loc4`='到这个地穴里去，让我们看看你的能耐，$G小伙子:姑娘;。', `MaleText_loc5`='到場子裡讓我們看看你的厲害，$G小鬼:女孩;。', `MaleText_loc7`='Entra en el foso y demueh''tra lo que vales, $gchico:chica;.', `FemaleText_loc1`='구덩이에 들어가서 당신의 기술을 보여주십시오.', `FemaleText_loc4`='到这个地穴里去，让我们看看你的能耐，$G小伙子:姑娘;。', `FemaleText_loc5`='到場子裡讓我們看看你的厲害，$G小鬼:女孩;。', `FemaleText_loc7`='Entra en el foso y demueh''tra lo que vales, $gchico:chica;.' WHERE `ID`=37886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 리치 왕의 하수인이 올 곳이 아니다!', `MaleText_loc4`='巫妖王的爪牙，这里不欢迎你们！', `MaleText_loc5`='你在此地不受歡迎，巫妖王的爪牙!', `MaleText_loc7`='¡No eres bienvenido aquí, esbirro del Rey Exánime!', `FemaleText_loc1`='여기는 리치 왕의 하수인이 올 곳이 아니다!', `FemaleText_loc4`='巫妖王的爪牙，这里不欢迎你们！', `FemaleText_loc5`='你在此地不受歡迎，巫妖王的爪牙!', `FemaleText_loc7`='¡No eres bienvenido aquí, esbirro del Rey Exánime!' WHERE `ID`=37887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰은 우리가 나약하다고, 힘없는 민족이라고 생각한다. 겁먹은 강아지처럼 설설 기리라 생각한다.', `MaleText_loc4`='被遗忘者以为我们软弱无能。心灰意冷。他们以为我们会像丧家犬一样投降。', `MaleText_loc5`='被遺忘者認為我們很弱。人心渙散。他們以為我們會像嚇壞的狗一樣翻滾。', `MaleText_loc7`='Los Renegados creen que somos débiles. Un pueblo deshecho. Creen que rogaremos como perros asustados.' WHERE `ID`=37888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 도전에 임하는 중입니다. 인내심을 가지고 기다리십시오.', `MaleText_loc4`='他们正在进行挑战，朋友。耐心一些。', `MaleText_loc5`='他們正處於試煉之中，老兄。耐心點。', `MaleText_loc7`='E''tan en medio de un reto, tron. Ten paciencia.', `FemaleText_loc1`='저들은 도전에 임하는 중입니다. 인내심을 가지고 기다리십시오.', `FemaleText_loc4`='他们正在进行挑战，朋友。耐心一些。', `FemaleText_loc5`='他們正處於試煉之中，老兄。耐心點。', `FemaleText_loc7`='E''tan en medio de un reto, tron. Ten paciencia.' WHERE `ID`=37889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상당한 채 무기도 없이 적에게 둘러싸여도... 마지막 희망마저 잃은 그때에도, 우리는 당당히 고개를 들고 적의 얼굴에 침을 뱉을 것이다!', `MaleText_loc4`='即使我们被包围，失去武器……身受重伤，孤立无援……我们也会带着轻蔑的神情高昂起头，将唾沫啐在敌人的脸上。', `MaleText_loc5`='如果我們發現自己被包圍又被繳械...受傷且被擊潰...我們將不屑一顧地向他們的臉上吐口水。', `MaleText_loc7`='Y si nos encontramos rodeados y desarmados... heridos y superados... Levantaremos la cabeza desafiantes y escupiremos en sus caras.' WHERE `ID`=37890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 마지막 총알을 발사할 때까지 거리를 누비며 싸울 것이다. 총알이 다 떨어지면, 도로에 깔린 돌덩이를 뜯어내 적을 있는 힘껏 내리칠 것이다.', `MaleText_loc4`='我们会在城市中战斗，直到射出最后一颗子弹，然后我们会掘起铺路的石块，砸向他们的脑袋。', `MaleText_loc5`='我們會在街上奮戰，直到最後一支箭射完。等我們彈盡援絕，我們會拿城裡鋪路的石頭敲碎他們的頭骨。', `MaleText_loc7`='Los combatiremos en las calles hasta que oiga el último disparo. Y cuando no queden municiones, aplastaremos sus cráneos con los adoquines de la ciudad.' WHERE `ID`=37891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골목에서도 적과 싸울 것이다. 주먹이 까지고 피가 배일 때까지, 검이 닳아 없어질 때까지 싸울 것이다.', `MaleText_loc4`='我们会在巷道里战斗，直到我们用尽最后一丝气力，手中的刀剑崩成碎片。', `MaleText_loc5`='我們會在後巷奮戰，直到我們的拳頭皮開肉綻，直到我們的彎刀碎裂在地。', `MaleText_loc7`='Los combatiremos en los callejones hasta que nos sangren los nudillos y nuestros estoques se hagan añicos.' WHERE `ID`=37892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼마나 큰 착각인가? 우리는 포탄이 다 떨어질 때까지, 마지막 참호가 무너지는 그 순간까지 싸울 것이다.', `MaleText_loc4`='他们大错特错了。我们会在旷野上战斗，直到最后一条战壕崩塌，最后一门大炮哑火。', `MaleText_loc5`='他們錯得很離譜。我們會在野地上奮戰，直到最後的壕溝垮下，最後的火砲熄滅。', `MaleText_loc7`='Qué equivocados están. Los combatiremos hasta que la última trinchera se derrumbe y el último cañón se calle.' WHERE `ID`=37893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입 다물어라, 멍청이들. 죽일 생각이 있었다면, 너희는 이미 죽은 목숨이었다.', `FemaleText_loc4`='安静点，蠢货。如果我要杀你，你早已经死了。', `FemaleText_loc5`='安靜，蠢貨。如果我想要殺你，你早就死透了。', `FemaleText_loc7`='Silencio, insensatos. Si hubiera querido matarlos, ya lo habría hecho.' WHERE `ID`=37894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상당한 채 무기도 없이 적에게 둘러싸여도... 마지막 희망마저 잃은 그때에도, 우리는 당당히 고개를 들고 적의 얼굴에 침을 뱉을 것이다!', `MaleText_loc4`='即使被包围，失去武器，身受重伤，毫无希望……我们也会高昂着头，将唾沫啐在敌人的脸上。', `MaleText_loc5`='如果我們被包圍並已毫無武裝，受傷並已毫無希望，我們會抬起頭來反抗並吐口水在他們臉上。', `MaleText_loc7`='Y si nos vemos rodeados y desarmados... heridos y sin esperanzas... alzaremos la frente desafiantes y les escupiremos la cara.' WHERE `ID`=37895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는... 절대로 항복하지 않을 것이다!!!!!', `MaleText_loc4`='但是我们……决不投降！！！', `MaleText_loc5`='但我們絕對不會投降!!!!', `MaleText_loc7`='Pero nunca... ¡¡¡NUNCA NOS RENDIREMOS!!!' WHERE `ID`=37896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스를 위하여!!!', `MaleText_loc4`='为吉尔尼斯而战！', `MaleText_loc5`='為了吉爾尼斯!', `MaleText_loc7`='¡¡¡POR GILNEAS!!!', `FemaleText_loc1`='길니아스를 위하여!!!', `FemaleText_loc4`='为吉尔尼斯而战！', `FemaleText_loc5`='為了吉爾尼斯!', `FemaleText_loc7`='¡¡¡POR GILNEAS!!!' WHERE `ID`=37897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $n!', `MaleText_loc4`='干得好，$n！', `MaleText_loc5`='做得好，$n!', `MaleText_loc7`='¡Bien hecho, $n!', `FemaleText_loc1`='잘하셨어요, $n!', `FemaleText_loc4`='干得好，$n！', `FemaleText_loc5`='做得好，$n!', `FemaleText_loc7`='¡Bien hecho, $n!' WHERE `ID`=37898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 처치하라. 그 영혼은 곧 다시 나의 것이 될 테니.', `MaleText_loc4`='拿走它们吧，凡人，这些灵魂很快又将是我的。', `MaleText_loc5`='拿走它們，凡人，這些靈魂很快又會是屬於我的。', `MaleText_loc7`='Llévatelos, mortal. Pronto estas almas serán mías de nuevo.' WHERE `ID`=37899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 머지않아 너도 네 무기에 갇히리라.', `MaleText_loc4`='凡人，你很快也会成为剑中的囚徒。', `MaleText_loc5`='快了，凡人，你也很快將被囚禁在劍刃之中。', `MaleText_loc7`='Pronto, mortal, también tendrás una espada por cárcel.' WHERE `ID`=37900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하라. 나도 한때는 위대한 힘을 지닌 무기를 찾아 헤맸었다...', `MaleText_loc4`='记住，英雄：我也曾寻找一件强大的武器……', `MaleText_loc5`='要記得，英雄:我，也曾追尋一件擁有強大力量的武器...', `MaleText_loc7`='Recuerda, héroe: yo también busqué un arma de gran poder alguna vez…' WHERE `ID`=37901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 네 욕심을 채우려고 영혼을 거두는구나. 용사여, 너와 내가 정말 그렇게 다른 존재일까?', `MaleText_loc4`='我看到你也在收集着灵魂，就像我一样。我们真的不同吗，勇士？', `MaleText_loc5`='我看見你為達目的也同樣在收集靈魂。我們有何不同，勇士?', `MaleText_loc7`='Veo que tú también recolectas almas para tus propios fines. ¿Somos tan diferentes, ''campeón''?' WHERE `ID`=37902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 만들어라! 끔찍한 무기를 새로 만들어라. 네 영혼이 내 것이 되면 그 무기도 나를 섬기리라.', `MaleText_loc4`='没错！打造你的恐怖武器吧。它将随着你的灵魂一同为我效命。', `MaleText_loc5`='對，去做!製造屬於你自己的恐怖武器吧。當你的靈魂屬於我的時候，它也將服侍我。', `MaleText_loc7`='¡Sí, hazlo! Crea tu nueva arma monstruosa. También me servirá cuando tu alma sea mía.' WHERE `ID`=37903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기를 나에게 가져오너라, 용사여. 그 주인의 영혼을 먹이리라!', `MaleText_loc4`='带上你的武器，勇士，它会尝到自己主人灵魂的鲜美！', `MaleText_loc5`='把你的武器帶來給我，勇士。我或許會讓它飽食它主人的靈魂!', `MaleText_loc7`='¡Tráeme tu arma, campeón, para que pueda alimentarla con el alma de su amo!' WHERE `ID`=37904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이, 자신을 보아라. 영혼의 주인이 될 자여... 내 마음대로 쓸 수 있는 힘이 어떤 것인지 짐작조차 못 하리라!', `MaleText_loc4`='孩子，你想操纵灵魂吗……你还无法理解我所掌握的力量！', `MaleText_loc5`='看看你自己，孩子;即將持舞著眾多靈魂...你無法揣度它在我指揮下的力量!', `MaleText_loc7`='Mírate, aspirante a portador de almas... ¡Jamás comprenderás el poder que comando!' WHERE `ID`=37905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제넘은 자여, 오너라! 내 검을 배 불려라!', `MaleText_loc4`='狂妄之徒！来祭我的剑吧！', `MaleText_loc5`='到我這兒來，偽善者!餵我的劍!', `MaleText_loc7`='¡Ven a mí, aspirante! ¡Alimenta MI espada!' WHERE `ID`=37906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격려를 좀 해주었더니 강해졌구나, 용사여. 앞으로 날 아주 잘 섬기겠다!', `MaleText_loc4`='我的考验让你变得更强，你将更好地效忠我！', `MaleText_loc5`='我的挑戰讓你力量增長，勇士。你將可以好好服侍我!', `MaleText_loc7`='Mis retos te han fortalecido, campeón. íMe servirás bien!' WHERE `ID`=37907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 네 목숨을 살려준 걸 후회할 일은 없구나. 언제나, 나를 즐겁게 하니 말이다.', `MaleText_loc4`='你要知道，凡人，我并不后悔饶你一命，因为你总会给我带来乐趣。', `MaleText_loc5`='我從來沒有後悔過饒你一命，凡人。你總是有辦法娛樂我。', `MaleText_loc7`='Nunca he podido arrepentirme de haberte perdonado la vida, mortal. Siempre encuentras una forma de entretenerme.' WHERE `ID`=37908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 그때가 가까웠다. 새로운 아제로스에서 영원히 나를 섬기리라!', `MaleText_loc4`='你的大限将至，凡人。你将在新的艾泽拉斯永受折磨！', `MaleText_loc5`='時機即將到來，凡人。你們將在嶄新的艾澤拉斯中永世沉淪。', `MaleText_loc7`='Pronto llegará el momento, mortal. Vagarás eternamente en un nuevo Azeroth.' WHERE `ID`=37909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을 더 많이... 그래, 더... 멈추기 어렵다는 것을 깨달으리라.', `MaleText_loc4`='你会发现……对灵魂的渴求……是多么的难以抗拒。', `MaleText_loc5`='更多的靈魂...沒錯，更多...你會發現你將難以自制，凡人。', `MaleText_loc7`='Más almas... Sí, más... Verás que es difícil parar.' WHERE `ID`=37910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기가 느끼는 갈망은 앞으로 닥칠 일의 그림자일 뿐이다. 진정한 갈망을 보고 싶나? 진정한 힘을? 영웅이여, 계속 나아오라. 기다리고 있겠다.', `MaleText_loc4`='你的武器感到了饥饿。这不算什么。想要感受真的饥饿，真的力量吗？继续吧，英雄，我等着你们。', `MaleText_loc5`='你武器所感到的飢渴只不過是未來的冰山一角。你想見識看看真正的飢渴嗎?真正的力量嗎?繼續吧，英雄。我在等著。', `MaleText_loc7`='El hambre que siente tu arma es sólo una sombra de lo que te espera. ¿Quieres ver el verdadero hambre? ¿El verdadero poder? Sigue adelante, héroe. Te espero.' WHERE `ID`=37911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에서 헤매는구나. 여기엔 빛이 없다. 자비도 없다! 얼음왕관에서는 너보다 더 나은 영웅들의 영혼도 사라져갔다.', `MaleText_loc4`='你只能在黑暗中踌躇。那里没有光明，也没有怜悯！冰冠堡垒吞噬过比你更加强大的灵魂。', `MaleText_loc5`='你步入黑暗的歧途，這裡沒有光明。沒有慈悲!寒冰皇冠佔有的靈魂，是遠比你更優秀的英雄。', `MaleText_loc7`='Vas dando tumbos en la oscuridad. Aquí no hay luz. ¡No hay piedad! Corona de Hielo ha tomado las almas de héroes mejores que tú.' WHERE `ID`=37912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 심장이... 끊임없이 고동치는 소리가 역겹구나. 네 심장도 내 것과 마찬가지로 잠잠하게 해 주마.', `MaleText_loc4`='你不停跳动的心脏令我厌恶。我会让它停止，就像我一样。', `MaleText_loc5`='你的心臟 - 那持續的跳動令我作嘔。我要讓它如同我的一樣，永遠靜止。', `MaleText_loc7`='Tu corazón... Su constante palpitar me da asco. Lo acallaré como hice con el mío.' WHERE `ID`=37913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 빛이 너를 저버리리라. 나를 버렸던 것처럼.', `MaleText_loc4`='圣光会抛弃你，英雄，就像抛弃我那样。', `MaleText_loc5`='聖光將會遺棄你，英雄，一如它遺棄了我。', `MaleText_loc7`='La Luz te abandonará, héroe, como hizo conmigo.' WHERE `ID`=37914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미에겐 다양한 운동 속도 조절 기능 있다. 에이미의 디자인 사양인 U-2502에 따르면 사용자가 에이미의 운동 속도를 원하는 데로 조정할 수 있다.$b$b느긋 모드에서는 일반 $r의 속도로 움직인다.$b$b달려라 모드에선 일반 말이나 늑대의 속도로 움직인다.$b$b폭주 모드에선 매우 빠른 말이나 늑대의 속도로 움직인다.$b$b어떤 모드로 설정하겠나?', `MaleText_loc4`='A-Me有许多运动速度模式。根据A-Me设计说明U-2502，使用者可以自行设定A-Me的运动模式，让它完全符合自己的需求。$b$b在缓行模式下，A-Me以正常的$r速度移动。$b$b在奔跑模式下，A-Me以普通马匹或座狼的速度移动。$b$b在超速模式下，A-Me以高速战马或迅捷座狼的速度移动。$b$b你想要哪种模式？', `MaleText_loc5`='艾米有許多行進速度的模式。艾米的設計說明U-2502指出使用者可以依自己的喜好和需求調整艾米的行進模式。$b$b$r，在步行模式下，艾米會以標準的速度前進。$b$b在跑步模式下，艾米的速度將提升的與狼或馬的普通速度一樣。$b$b在高速模式下，艾米的速度可以媲美速度極快的馬或狼。$b$b你喜歡哪個模式?', `MaleText_loc7`='Memo tener muchos modos de locomoción. Directriz de diseño de Memo U-2502 afirmar que usuario definir modo de locomoción de Memo según preferencia.$b$bEn modo paseo, Memo moverse a velocidad de $r normal.$b$bEn modo carrera, Memo moverse a velocidad de caballo o lobo normal.$b$bEn modo ultravelocidad, Memo moverse a velocidad de caballo o lobo MUY RÁPIDO.$b$b¿Preferencia de modo?' WHERE `ID`=37915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느긋 모드로 한 번 가보자, 에이미.', `MaleText_loc4`='我认为应该从缓速模式开始，A-Me。', `MaleText_loc5`='我想還是使用步行模式吧，艾米。', `MaleText_loc7`='Creo que prefiero el modo paseo, Memo.', `FemaleText_loc1`='느긋 모드로 한 번 가볼까, 에이미?', `FemaleText_loc4`='我认为应该从缓速模式开始，A-Me。', `FemaleText_loc5`='我想還是使用步行模式吧，艾米。', `FemaleText_loc7`='Creo que prefiero el modo paseo, Memo.' WHERE `ID`=37916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달려라 모드로 가볼까.', `MaleText_loc4`='让我们试试奔跑模式。', `MaleText_loc5`='讓我們試試跑步模式。', `MaleText_loc7`='Vamos a probar el modo carrera.', `FemaleText_loc1`='달려라 모드가 어떨지 궁금하군.', `FemaleText_loc4`='让我们试试奔跑模式。', `FemaleText_loc5`='讓我們試試跑步模式。', `FemaleText_loc7`='Vamos a probar el modo carrera.' WHERE `ID`=37917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭주 모드로! 한 번 달려 보자고!', `MaleText_loc4`='超速模式！我们来试试！', `MaleText_loc5`='高速模式!衝啊!', `MaleText_loc7`='¡Modo ultravelocidad! ¡Venga!', `FemaleText_loc1`='폭주 모드로! 한 번 달려 보자고!', `FemaleText_loc4`='超速模式！我们来试试！', `FemaleText_loc5`='高速模式!衝啊!', `FemaleText_loc7`='¡Modo ultravelocidad! ¡Venga!' WHERE `ID`=37918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입력 완료. 이제 이동한다.', `MaleText_loc4`='指令输入已确认。请准备好开始旅程。', `MaleText_loc5`='資料輸入確認。請準備開始你的旅程。', `MaleText_loc7`='Datos reconocidos. Preparar para el viaje.' WHERE `ID`=37919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 사용자 준비된 것 같다. 이제 가자.', `MaleText_loc4`='良好。良好。使用者已准备好。现在，我们出发。', `MaleText_loc5`='很好。很好。使用者看來準備好了。我們現在出發。', `MaleText_loc7`='Bien. Bien. Usuario parecer listo. Partir.' WHERE `ID`=37920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐. 에이미 뭔가 잊고 갈 뻔했다. 잠시 어디 들린 다음 탈출 단계로 다시 돌입하겠다.', `MaleText_loc4`='等待。A-Me遗忘了某事件。我们应立刻停止，然后返回至逃跑进程。', `MaleText_loc5`='等等，艾米忘了做件事。我們稍微停一下再繼續我們的脫逃計畫。', `MaleText_loc7`='Alto. Memo olvidar algo. Hacer parada rápida y volver a protocolo de huida.' WHERE `ID`=37921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미가 가슴을 치며 근처의 고릴라들에게 신호를 보냅니다.', `MaleText_loc4`='A-Me拍打着胸口，向附近的一只猩猩发出呼吼。', `MaleText_loc5`='艾米搥著她的胸，向附近的猩猩呼叫。', `MaleText_loc7`='Memo se golpea el pecho y llama a un gorila cercano.' WHERE `ID`=37922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔구나, 우가... 지금부터 에이미 말 잘 들어라.', `MaleText_loc4`='乌嘎……你来了。良好。A-Me需要你听一听。', `MaleText_loc5`='烏加...你來了。太好了，艾米有話想對你說。', `MaleText_loc7`='Wooga venir... Bien. Memo querer tú escuchar.' WHERE `ID`=37923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미 말하기 괴롭다... 에이미 집에 간다. 에이미 떠날 시간이다.', `MaleText_loc4`='这对A-Me来说不容易…… A-Me要回家。 这是A-Me离开的最后时刻。', `MaleText_loc5`='艾米很難說出口...艾米要回家了。該是時候艾米回家了。', `MaleText_loc7`='No ser fácil de decir para Memo... Memo volver a casa. Por fin Memo tener que irse.' WHERE `ID`=37924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이미 다른 친구들에게도 전해야 한다. 라쿠에게는 번개 만드는 법을 가르쳐줘서 고맙다고... 미스코에겐 공룡과 싸우는 법을 알려줘서 고맙다고 전해야 한다.', `MaleText_loc4`='A-Me需要你告诉拉库，A-Me感谢他教导A-Me如何制造闪电；还要告诉米思科，A-Me感谢他教导A-Me如何同恐龙作战。', `MaleText_loc5`='艾米需要你跟大家說。告訴拉庫謝謝他教艾米做閃電。還有跟米絲可說謝謝他教艾米如何跟恐龍戰鬥。', `MaleText_loc7`='Memo querer tú decir a los demás. Dar Rakoo gracias por enseñar a Memo cómo hacer relámpagos. Dar Misko gracias por enseñar a Memo cómo luchar contra dinosaurios.' WHERE `ID`=37925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 누구보다... 네가 가장 고맙다, 우가. 에이미에게 사랑하는 법을 가르쳐줘서.', `MaleText_loc4`='但最重要的是……感谢你，乌嘎，是你教会了A-Me该如何去爱。', `MaleText_loc5`='但最重要的是...謝謝你，烏加，謝謝你教了艾米如何去愛。', `MaleText_loc7`='Pero sobre todo... Gracias, Wooga, por enseñar a Memo a amar.' WHERE `ID`=37926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우가의 마지막 뒷모습을 오랫동안 바라보는 에이미 01의 눈에서 야자 과즙 한 방울이 떨어집니다.', `MaleText_loc4`='A-Me 01最后凝望了乌嘎一眼，一滴椰奶从她的眼睛里流出来。', `MaleText_loc5`='當艾米不捨的看了烏加最後一眼時，一滴椰子奶從艾米01的眼角流了下來，', `MaleText_loc7`='Una solitaria gota de leche de coco se derrama del ojo de Memo 01 cuando dirige una última y prolongada mirada a Wooga.' WHERE `ID`=37927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘지 않군, $n. 나쁘지 않아.', `MaleText_loc4`='不坏，$n。不坏。', `MaleText_loc5`='不錯嘛，$n。不錯。', `MaleText_loc7`='No eh''tá mal, $n. No eh''tá mal.', `FemaleText_loc1`='나쁘지 않군요, $n. 나쁘지 않아요.', `FemaleText_loc4`='不坏，$n。不坏。', `FemaleText_loc5`='不錯嘛，$n。不錯。', `FemaleText_loc7`='No eh''tá mal, $n. No eh''tá mal.' WHERE `ID`=37928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 ''왕관화학회사''라는 거, 정말로 마음에 안 든다고.', `MaleText_loc4`='我一点也不喜欢这个皇冠药剂公司的样子。', `MaleText_loc5`='我一點也不喜歡這個「王冠化學製藥公司」。', `MaleText_loc7`='No me gusta la pinta de estos Químicos La Corona, S.L. ni un poco.' WHERE `ID`=37929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 잘 간수하시면 그 답으로 무기가 당신을 지켜줄 겁니다.', `MaleText_loc4`='照顾好你的武器，它们就能照顾好你。', `MaleText_loc5`='保護好你的武器，它們便會保護好你。', `MaleText_loc7`='Cui''a de tus armas y ella'' también cuidarán de ti.' WHERE `ID`=37930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남자든 여자든 아이든... 아무도 주인님의 분노를 피할 수 없다. 다 죽은 목숨이지.', `MaleText_loc4`='男人，女人，还有孩子……没人能逃过主人的怒火。你的死早已注定。', `MaleText_loc5`='男人、女人和小孩...沒有人能逃過主人的憤怒。你的死也沒有差別。', `MaleText_loc7`='Hombres, mujeres, niños... Nadie se libró de la cólera de nuestro amo. Tu muerte no será distinta.' WHERE `ID`=37931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들은 거칠고 혼란스러운 상태라네. 배움을 통해서만 정령들과의 관계를 유지하고 제어할 수 있다네.', `FemaleText_loc4`='元素混乱而且狂野。只有通过学习，我们才能保持和它们的联系并控制它们。', `FemaleText_loc5`='元素是野蠻和混亂的。只有不斷地學習我們才能跟它們溝通和控制它們。', `FemaleText_loc7`='Los elementos son salvajes y caóticos. Solo mediante la inh''trucción podemos eh''tar en contacto con ellos y mantenerlos bajo contro''.' WHERE `ID`=37932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 전사 훈련을 받고자 한다면, 노르텟과 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受战士训练，就去和诺泰特谈谈。', `MaleText_loc5`='我幫不了你，想要接受戰士的訓練就去跟諾泰特談話。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Nortet si quieres instrucción para guerreros.', `FemaleText_loc1`='도와드릴 수가 없군요. 전사 훈련을 받고자 한다면, 노르텟과 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受战士训练，就去和诺泰特谈谈。', `FemaleText_loc5`='我幫不了你，想要接受戰士的訓練就去跟諾泰特談話。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Nortet si quieres instrucción para guerreros.' WHERE `ID`=37933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 주술사 훈련을 받고자 한다면, 네칼리와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受萨满祭司训练，就去和奈卡利谈谈。', `MaleText_loc5`='我幫不了你。跟薩滿訓練有關的可以去找內卡利聊聊。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Nekali si quieres instrucción para chamanes.', `FemaleText_loc1`='도와드릴 수가 없군요. 주술사 훈련을 받고자 한다면, 네칼리와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受萨满祭司训练，就去和奈卡利谈谈。', `FemaleText_loc5`='我幫不了你。跟薩滿訓練有關的可以去找內卡利聊聊。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Nekali si quieres instrucción para chamanes.' WHERE `ID`=37934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 드루이드 훈련을 받고자 한다면, 젠타브라와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受德鲁伊训练，就去和岑塔布拉谈谈。', `MaleText_loc5`='我幫不了你，想要接受德魯伊的訓練就去跟贊塔布拉談話。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Zen''tabra si quieres instrucción pa'' druidas.', `FemaleText_loc1`='도와드릴 수가 없군요. 드루이드 훈련을 받고자 한다면, 젠타브라와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受德鲁伊训练，就去和岑塔布拉谈谈。', `FemaleText_loc5`='我幫不了你，想要接受德魯伊的訓練就去跟贊塔布拉談話。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Zen''tabra si quieres instrucción pa'' druidas.' WHERE `ID`=37935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 도적 훈련을 받고자 한다면, 레가티와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受潜行者训练，就去和雷加提谈谈。', `MaleText_loc5`='我幫不了你，想要接受盜賊的訓練就去跟雷加悌談話。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Legati si quieres instrucción para pícaros.', `FemaleText_loc1`='도와드릴 수가 없군요. 도적 훈련을 받고자 한다면, 레가티와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受潜行者训练，就去和雷加提谈谈。', `FemaleText_loc5`='我幫不了你，想要接受盜賊的訓練就去跟雷加悌談話。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Legati si quieres instrucción para pícaros.' WHERE `ID`=37936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 사제 훈련을 받고자 한다면, 투나리와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受牧师训练，就去和图娜尼谈谈。', `MaleText_loc5`='我幫不了你，想要接受牧師的訓練就去跟圖那利談話。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Tunari si quieres instrucción para sacerdotes.', `FemaleText_loc1`='도와드릴 수가 없군요. 사제 훈련을 받고자 한다면, 투나리와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受牧师训练，就去和图娜尼谈谈。', `FemaleText_loc5`='我幫不了你，想要接受牧師的訓練就去跟圖那利談話。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Tunari si quieres instrucción para sacerdotes.' WHERE `ID`=37937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 마법사 훈련을 받고자 한다면, 소라타와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受法师训练，就去和索拉萨谈谈。', `MaleText_loc5`='我幫不了你，想要接受法師的訓練就去跟索拉薩談話。', `MaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Soratha si quieres instrucción para magos.', `FemaleText_loc1`='도와드릴 수가 없군요. 마법사 훈련을 받고자 한다면, 소라타와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受法师训练，就去和索拉萨谈谈。', `FemaleText_loc5`='我幫不了你，想要接受法師的訓練就去跟索拉薩談話。', `FemaleText_loc7`='No pue''o ayudah''te. Ve a hablar con Soratha si quieres instrucción para magos.' WHERE `ID`=37938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 사냥꾼 훈련을 받고자 한다면, 오르테자와 대화해 보시기 바랍니다.', `MaleText_loc4`='我不能帮助你，如果你想接受猎人训练，就去和欧塔扎谈谈。', `MaleText_loc5`='我幫不了你，想要接受獵人的訓練就去跟奧泰薩談話。', `MaleText_loc7`='No pue''o ayudah''te. Habla con Ortezza si quieres instrucción para cazadores.', `FemaleText_loc1`='도와드릴 수가 없군요. 사냥꾼 훈련을 받고자 한다면, 오르테자와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我不能帮助你，如果你想接受猎人训练，就去和欧塔扎谈谈。', `FemaleText_loc5`='我幫不了你，想要接受獵人的訓練就去跟奧泰薩談話。', `FemaleText_loc7`='No pue''o ayudah''te. Habla con Ortezza si quieres instrucción para cazadores.' WHERE `ID`=37939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줄 수가 없네.', `MaleText_loc4`='我们不能帮你，朋友。', `MaleText_loc5`='我們幫不了你，老兄。', `MaleText_loc7`='No podemos ayudah''te, colega.', `FemaleText_loc1`='도와줄 수가 없네.', `FemaleText_loc4`='我们不能帮你，朋友。', `FemaleText_loc5`='我們幫不了你，老兄。', `FemaleText_loc7`='No podemos ayudah''te, colega.' WHERE `ID`=37940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실컷 꿈틀대봐라!', `MaleText_loc4`='无能的家伙！', `MaleText_loc5`='流鼻涕的蛆!', `MaleText_loc7`='¡Gusano llorón!' WHERE `ID`=37941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스트라솔름에 사는 어린애도 이보다는 잘 싸우겠다!', `MaleText_loc4`='斯坦索姆的小孩子都要比你们勇猛！', `MaleText_loc5`='斯坦索姆的孩童都比你會戰鬥!', `MaleText_loc7`='¡Los niños de Stratholme lucharon con más ferocidad que esto!' WHERE `ID`=37942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마윈, 저놈들을 끝장내...', `MaleText_loc4`='玛维恩，干掉他们……', `MaleText_loc5`='麥爾溫，解決他們...', `MaleText_loc7`='Marwyn, acaba con ellos...' WHERE `ID`=37943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론의 병사들아, 일어나 주인님의 부름에 응해라!', `MaleText_loc4`='洛丹伦的战士们，服从主人的召唤！', `MaleText_loc5`='羅德隆的士兵們，起來回應你們主人的召喚!', `MaleText_loc7`='¡Soldados de Lordaeron, levántense y respondan al llamado de su amo!' WHERE `ID`=37944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망... 너무나 달콤하지...', `MaleText_loc4`='绝望……如此甘甜……', `MaleText_loc5`='絕望...多麼美味...', `MaleText_loc7`='Desesperación... qué delicia…' WHERE `ID`=37945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포... 너무나 상쾌하지...', `MaleText_loc4`='恐惧……如此美好……', `MaleText_loc5`='恐懼...多令人振奮...', `MaleText_loc7`='Miedo... qué estimulante…' WHERE `ID`=37946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다, 주인님.', `MaleText_loc4`='听命，主人！', `MaleText_loc5`='如您所願，大人。', `MaleText_loc7`='Como lo desee, mi señor.' WHERE `ID`=37947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 여기에서 얻을 것은 죽음뿐이다!', `MaleText_loc4`='你们只会寻得死亡！', `MaleText_loc5`='你們在這裡只能找到死亡!', `MaleText_loc7`='¡La muerte es todo lo que encontrarán aquí!' WHERE `ID`=37948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈이 죽을 때도 똑같은 눈빛이었지. 테레나스는 믿지 못했지만.', `MaleText_loc4`='我看到的是同样的眼神。泰瑞纳斯怎么也想不到。', `MaleText_loc5`='他死的時候，我在他眼中看到同樣的眼神。泰瑞納斯幾乎無法相信。', `MaleText_loc7`='Vi la misma mirada en sus ojos cuando murió. Terenas no lo podía creer.' WHERE `ID`=37949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통 속에 죽어가라!', `MaleText_loc4`='痛苦的窒息吧！', `MaleText_loc5`='被你的痛苦噎死吧!', `MaleText_loc7`='¡Atragántate con tu sufrimiento!' WHERE `ID`=37950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 도망쳐라... 네 운명을 만날 때까지... 쓰라리고, 차디찬 결말이 너를 기다린다.', `MaleText_loc4`='对，去吧……迎接你的命运吧……痛苦、冰冷的拥抱正等着你。', `MaleText_loc5`='是...跑吧...跑去面對你的命運...它苦澀、冰冷的擁抱正等著你。', `MaleText_loc7`='Sí... Corre... Corre hacia tu destino... Su amargo y frío abrazo te espera.' WHERE `ID`=37951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서는 왕국을 살펴보고 모자라다고 생각하셨다. 그리고 자비도 주저함도 없이 심판하셨지. 모두 죽여주마!', `MaleText_loc4`='主人审视他的王国，找到了它的……不足。他的决断迅速而无情：生灵俱灭！', `MaleText_loc5`='主人俯視他的王國並且發覺出它所...欠缺之處。他的裁決迅速而且毫不心軟:全部處死!', `MaleText_loc7`='El amo observó su reino y le pareció... insuficiente. Su juicio fue rápido e inclemente: ¡MUERTE A TODOS!' WHERE `ID`=37952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다, 주인님.', `MaleText_loc4`='如您所愿，我的主人。', `MaleText_loc5`='如您所願，大人。', `MaleText_loc7`='Como desee, mi señor.' WHERE `ID`=37953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩어들어 가는 네 몸을 직접 보여주마!', `MaleText_loc4`='你的躯壳将在你的眼前朽化！', `MaleText_loc5`='你的血肉會在你眼前腐爛!', `MaleText_loc7`='¡Tu carne se pudrirá ante tus ojos!' WHERE `ID`=37954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라, 흔적도 없이!', `MaleText_loc4`='灰飞烟灭吧！', `MaleText_loc5`='消失殆盡吧!', `MaleText_loc7`='¡Consúmete en la nada!' WHERE `ID`=37955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은창 트롤은 예로부터 자연과 연결되어 있지만, 최근에 들어서야 드루이드의 기술을 알게 되었다네. 열린 마음을 갖도록 해 보게나, $n.', `FemaleText_loc4`='暗矛巨魔在很久以前就和自然有着密切的联系，但直到最近，我们才了解到德鲁伊的技艺。 $n，你要尽量保持谦虚的态度。', `FemaleText_loc5`='暗矛食人妖與大自然有著極為長久的淵源，但直到最近我們才開始瞭解德魯伊之道。要心胸寬敞接受新的事物，$n。', `FemaleText_loc7`='Los trols Lanza Negra siempre hemos eh''ta''o conecta''os con la naturaleza, pero hace poco que hemos aprendi''o las artes druídicas. Mantén la mente abie''ta, $n.' WHERE `ID`=37956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠르게 치고 사라지게나. 다른 이들은 자네 이름을 모르지만, 자네의 행적에 대해서는 알게 될 때가 자네가 기술에 통달하기 시작하는 때라는 걸 알게 될 걸세.', `MaleText_loc4`='骤隐骤现。当人们看到你所做的一切，却看不到你的时候，你就掌握了你的职业技巧。', `MaleText_loc5`='攻擊後潛入黑影中，敵在明我在暗。如何知道你已經成為精通所有技巧的大師?就是當人們知道你所做的事，卻完全沒聽過你的名字時。', `MaleText_loc7`='Ataca con rapidez y desaparece. Sabrás que empiezas a dominar tus habilidades cuando la gente conozca tus hazañas, pero nadie haya oí''o hablar de ti.' WHERE `ID`=37957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투의 혼란 속에서 우리를 승리로 이끄는 건 빛과 어둠의 조화입니다.', `FemaleText_loc4`='在混乱的战场上，光与影的平衡将引领我们取得胜利。', `FemaleText_loc5`='在戰爭的混沌中，是光和影的平衡帶領我們邁向勝利。', `FemaleText_loc7`='En el caos de la batalla, es el equilibrio entre la luz y la sombra lo que nos conduce a la victoria.' WHERE `ID`=37958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자는 기사의 오른팔이다. 너도 잘 알겠지만, 팔은 물건을 들 때 가장 쓸만하지. 그러므로 내가 이 땅에 정의를 행할 동안 넌 내 물건, 장신구, 그리고 이런저런 소지품들을 날라라. 잡다한 물건들을 들고 다니는 건 기사의 품격을 떨어뜨리니 말이다.', `MaleText_loc4`='侍从是骑士的左右手。要知道，手应该特别擅长于搬运东西，所以你的第一个任务就是负责搬运我的杂物、小东西和其它各种随身用具。这样我才能放心地在世界各处维护正义。毕竟搬运杂物可不是骑士应该做的事情。', `MaleText_loc5`='侍從是一個騎士的左右手。就像我所說的，手的最大用處就是搬東西，所以你的第一個任務就是在我為這片大地伸張正義時搬運我的雜物。搬運物品的工作並不是一個騎士應該要做的。', `MaleText_loc7`='Un escudero es la mano derecha del caballero. Como ya sabes, las manos son especialmente buenas para llevar cosas y, por eso, tu primera tarea será llevar mis cachivaches, chismes y otros cacharros varios mientras yo reparto justicia. Arrastrar esos trastos es un trabajo poco adecuado para un caballero.' WHERE `ID`=37959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말인지 알겠습니다.', `MaleText_loc4`='可以理解。', `MaleText_loc5`='瞭解。', `MaleText_loc7`='Comprensible.', `FemaleText_loc1`='무슨 말인지 알겠어요.', `FemaleText_loc4`='可以理解。', `FemaleText_loc5`='瞭解。', `FemaleText_loc7`='Comprensible.' WHERE `ID`=37960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 둘째로, 기사는 신조보다도 기사도 정신에 더 철저해야 한다는 사실을 알아야 한다. 또한, 기사는 손에서 창을 놓지 않듯이 언제나 관대함을 지녀야 한다. 용맹함은 갑옷만큼이나 빛을 내야 하며, 소지한 단검은 날카로울 수 있을지언정 그 태도는 부드럽고, 또 정중해야만 한다.$b$b이제 내게 답하라, $n. 기사도와 용맹에 대한 내 가르침을 따르리라 맹세하겠는가?', `MaleText_loc4`='很好。第二，你必须知道，对于骑士来说，最重要的莫过于骑士精神。骑士永远要秉承慷慨仁慈的骑士情怀，就如同绝对不能放开手中的长枪。他的勇猛果敢必须比他身上的铠甲更加耀眼夺目。无论他的佩剑多么锋利刚硬，他对待朋友却必须和善谦恭。$b$b现在，告诉我，$n，你会立下誓言，坚守骑士的精神和勇气吗？', `MaleText_loc5`='很好。第二，你必須瞭解騎士信條是一個騎士所有的一切。保持寬恕的心裡就與他手中的騎士槍一樣重要。他的榮耀與他的鎧甲一樣閃閃發亮。雖然他的配劍鋒利無比，他對盟友的態度確溫文儒雅。$b$b告訴我，$n，你願意發誓永遠向騎士信條和武勇之心看齊嗎?', `MaleText_loc7`='Muy bien. En segundo lugar debes saber que el principio que más fuerte abraza un caballero es la caballerosidad. Se aferra a su generosidad igual que se aferra a su lanza. Su valor brilla como su armadura. Y aunque su florete puede estar afilado, sus modales entre los aliados son suaves y corteses.$b$bAhora dime, $n, ¿juras regirte por las enseñanzas de la caballerosidad y la gallardía?' WHERE `ID`=37961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세합니다.', `MaleText_loc4`='我在此立誓。', `MaleText_loc5`='我願意發誓。', `MaleText_loc7`='Tienes mi juramento.', `FemaleText_loc1`='맹세해요.', `FemaleText_loc4`='我在此立誓。', `FemaleText_loc5`='我願意發誓。', `FemaleText_loc7`='Tienes mi juramento.' WHERE `ID`=37962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다.', `MaleText_loc4`='是，先生。', `MaleText_loc5`='是的。', `MaleText_loc7`='Sí, señor.', `FemaleText_loc1`='네, 알겠습니다.', `FemaleText_loc4`='是，先生。', `FemaleText_loc5`='是的。', `FemaleText_loc7`='Sí, señor.' WHERE `ID`=37963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='핫! 착한 종자야, 내가 방금 기사도 정신과 용맹은 기사의 몫이라고 언급했더냐? 넌 그저 종자일 뿐, 기사로서 안고 가야 할 거대한 짐은 종자에게 어울리지 않느니라. 전에 내가 말했듯이 네가 안고 가야 할 거대한 짐은 내 소지품뿐이다.', `MaleText_loc4`='哈！我没有说过吗，好$n，骑士精神和勇气是骑士必须坚持的原则？你要做的只是一名侍从。严格的骑士精神对于侍从来说是难以承受的重担。就像我曾经提到过的一样，你要扛起的担子只有我的随身物品。', `MaleText_loc5`='哈!$n，我剛不是說了嗎?騎士信條和武勇之心是僅限於騎士的!你的職位是個侍從。騎士信條如此沉重的負擔並不適合侍從。就像我之前說的，你唯一擁有的沉重負擔就是我的雜物。', `MaleText_loc7`='¡Ja! ¿No te acabo de decir, ben $n, que la caballerosidad y la gallardía son la carga del CABALLERO? Solo buscas ser un ESCUDERO. La colosal carga de la caballerosidad no es apropiada para el escudero, porque, como ya he mencionado antes, la única carga colosal que tú debes soportar son mis pertenencias.' WHERE `ID`=37964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼! 더 이상 못 참겠습니다!', `MaleText_loc4`='这太荒谬了！我可不会容忍这个！', `MaleText_loc5`='這太誇張了!我沒有必要這樣做!', `MaleText_loc7`='¡Esto es ridículo! ¡No tengo que aguantarlo!', `FemaleText_loc1`='말도 안 돼! 더 이상 못 참겠어요!', `FemaleText_loc4`='这太荒谬了！我可不会容忍这个！', `FemaleText_loc5`='這太誇張了!我沒有必要這樣做!', `FemaleText_loc7`='¡Esto es ridículo! ¡No tengo que aguantarlo!' WHERE `ID`=37965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속하지! 기사도가 기사의 길이라면 기사로서 내 개인적인 목표는 용맹 그 자체의 실천임을 알아야 하느니라. 나는 내 여인 돌로리아를 위해, 그녀의 아름다움과 위엄을 온누리에 떨치기 위해 싸운다. 돌로리아의 아름다움에 의문을 제시하는 그 누구든 가장 타락한 적이며, 정의의 심판을 받아 마땅하도다.$b$b말하다 보니 내가 일을 제대로 하지 않았다는 생각이 드는구나. 종자 임명식이 거의 막바지에 이르렀는데 아직도 너에게 은혜를 내릴지 정당한 분노를 퍼부을지 결정하지 못했으니 말이다.$b$b내 질문에 답해라. 내 여인 돌로리아가 두말할 것 없이 전 아제로스에서 가장 아름다운 여인이란 사실에 동의하느냐?', `MaleText_loc4`='开始吧！骑士精神是骑士之道，我正是一名骑士。你必须明白，我天生就是一名勇者。这是真的，我为多罗莉亚女士而战，要将她的美丽与高贵在全世界传颂。任何对她的美好有所质疑的人都是我最大的敌人，一定会得到我正义的惩罚。$b$b当我说话的时候，我才意识到我的一个失误。我们已经正式开始了接纳侍从的仪式，但我还没有确认你是应该接受我的赞许，还是我的正义怒火。$b$b现在我必须知道，你是否认为多罗莉亚女士是艾泽拉斯无可置疑的最美丽的人？', `MaleText_loc5`='動作快!騎士信條是一個騎士的一切，而我就是一個騎士!你必須知道我自己的想法一定都是極具榮譽感的。沒錯，我為我的朵莉亞女士而戰，來宣揚她的美麗和威嚴於這片大地。任何對她美麗存有疑惑的人毫無疑問的絕對是最邪惡的敵人，必須受到正義的制裁。$b$b說到這，我似乎很沒用...我們已經進入到侍從教育儀式的這個環節了，但我卻還是不確定我是否應該對你使用騎士信條或是正義之怒。$b$b我現在必須知道，你是否完全同意我的朵莉亞女士是艾澤拉斯最美麗的女人?', `MaleText_loc7`='¡Sigamos! Como la caballerosidad es el sendero del caballero y yo soy un caballero, debes saber que mis intenciones son valerosas. Es cierto, lucho por mi Lady Doloria, para proclamar su belleza y majestad por todas las tierras. Cualquiera que dude de su belleza es, sin duda, el más miserable de los enemigos y hay que llevarlo ante la justicia.$B$BAl hablar me viene a la mente que soy un fracaso. Hemos avanzado bastante en la ceremonia del escudero, pero aún no he averiguado si mereces mi caridad o mi furia justa.$B$BAhora debo saberlo, ¿estás de acuerdo en que mi Lady Doloria es, sin duda alguna, la dama más bella de todo Azeroth?' WHERE `ID`=37966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대답을 들으니 기쁘군. 축하한다, $n. 훈련을 마쳤으니 이제는 내 옆에 함께 달리며 싸움에 동참해도 될지어다.', `MaleText_loc4`='很高兴听到你这样说。祝贺你，$n，你已经完成了训练。现在你可以跟随我一同上战场了。', `MaleText_loc5`='我為你感到高興，$n。恭喜你已經完成了你的訓練，我現在允許你和我一起行動。', `MaleText_loc7`='Me alegra oír eso. Enhorabuena, $n, pues has completado tu instrucción. Ahora puedes cabalgar junto a mí hacia la batalla.' WHERE `ID`=37967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습을 통해 자네는 마법이 어떤 무기보다도 훨씬 강하다는 걸 알아채게 될 걸세.', `MaleText_loc4`='聪明，你会发现，魔法比任何武器都要强大得多。', `MaleText_loc5`='在不斷地練習下，你會發現魔法比任何武器都要來的強大。', `MaleText_loc7`='Con práctica, pronto te darás cuenta de que la magia puede ser más fueh''te que cualquier arma.' WHERE `ID`=37968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 아, 네, 그렇습니다. 두말할 나위 없죠.', `MaleText_loc4`='嗯……是的，她当然是，毫无疑问。', `MaleText_loc5`='呃...是，是...她是，完全同意。', `MaleText_loc7`='Ehm... sí, lo es. Sin duda.', `FemaleText_loc1`='음... 아, 네, 그래요. 두말할 나위 없죠.', `FemaleText_loc4`='嗯……是的，她当然是，毫无疑问。', `FemaleText_loc5`='呃...是，是...她是，完全同意。', `FemaleText_loc7`='Ehm... sí, lo es. Sin duda.' WHERE `ID`=37969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='喔嚯！', `MaleText_loc5`='哇呼!', `MaleText_loc7`='¡Yujuuuuu!', `FemaleText_loc1`='야호!', `FemaleText_loc4`='喔嚯！', `FemaleText_loc5`='哇呼!', `FemaleText_loc7`='¡Yujuuuuu!' WHERE `ID`=37970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자신의 활을 믿으십시오. 가장 필요할 때에 당신 곁에 있을 테니까요.', `FemaleText_loc4`='要信任你的弓。当你需要它的时候，它绝不会辜负你。', `FemaleText_loc5`='相信你的弓，它會在你最需要它的時候陪在你身邊。', `FemaleText_loc7`='Confía en tu arco. Estará ahí para ti cuando más lo necesites.' WHERE `ID`=37971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 모든이들이 실패했을 때 자연이 자네를 인도할 걸세.', `FemaleText_loc4`='当一切都已失去，自然仍然会指引你。', `FemaleText_loc5`='當一切都不如意時，大自然便會引導你前進的方向。', `FemaleText_loc7`='La naturaleza te guiará cuando todo lo demás falle.' WHERE `ID`=37972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 인식하지 못하고 기도에 몰입한 맥시밀리언>', `MaleText_loc4`='<麦斯米兰沉浸在祈祷中，忘却了你的存在。>', `MaleText_loc5`='<瑪克西米利安沉醉在他的禱告中，忽略了你的存在。>', `MaleText_loc7`='<Maximilian está inmerso en sus oraciones y no nota tu presencia.>' WHERE `ID`=37973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검을 내리고 투구를 벗어라. 칼을 맞대기 전에, 먼저 두 귀로 내 열변을 감당해야 할 것이니.$b$b준비되었느냐?', `MaleText_loc4`='收起你的剑，取下你的头盔。在我们用刀剑作战之前，我有好些话得先灌输到你的耳朵里去。$b$b准备好了吗？', `MaleText_loc5`='握好你的劍和活動你的鎧甲。在我們拿著劍殺入戰場前，我必須先在你的耳朵旁製造些氣勢。$b$b你準備好了嗎?', `MaleText_loc7`='Deja tu espada y aflójate el almete. Antes de que luchemos con nuestras espadas, he preparado un asalto para desatar contra tus oídos.$B$B¿Estás $gpreparado:preparada;?' WHERE `ID`=37974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다.', `MaleText_loc4`='好的，我准备好了。', `MaleText_loc5`='OK，我準備好了。', `MaleText_loc7`='Vale, estoy listo.', `FemaleText_loc1`='네, 알겠어요.', `FemaleText_loc4`='好的，我准备好了。', `FemaleText_loc5`='OK，我準備好了。', `FemaleText_loc7`='Vale, estoy lista.' WHERE `ID`=37975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 전체가 폭파될 것입니다. 밖으로 나가십시오!', `MaleText_loc4`='这里就要爆炸了，赶快出去！', `MaleText_loc5`='這整個地方會變的一團亂。快到出口那!', `MaleText_loc7`='Este lugar va a explotar. ¡Vayan a la salida!' WHERE `ID`=37976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 꿰뚫었습니다!', `MaleText_loc4`='%s刺穿了$n！', `MaleText_loc5`='%s刺穿了$n!', `MaleText_loc7`='¡%s ha empalado a $n!', `FemaleText_loc1`='%s|1이;가; $n|1을;를; 꿰뚫었습니다!', `FemaleText_loc4`='%s刺穿了$n！', `FemaleText_loc5`='%s刺穿了$n!', `FemaleText_loc7`='¡%s ha empalado a $n!' WHERE `ID`=37977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; %s의 에테르 보호막을 없앴습니다!', `MaleText_loc4`='%s的以太护盾已经被$n击碎。', `MaleText_loc5`='%s的蒼穹之盾被$n所粉碎!', `MaleText_loc7`='¡$n ha roto el escudo de éter de %s!', `FemaleText_loc1`='$n|1이;가; %s의 에테르 보호막을 없앴습니다!', `FemaleText_loc4`='%s的以太护盾已经被$n击碎。', `FemaleText_loc5`='%s的蒼穹之盾被$n所粉碎!', `FemaleText_loc7`='¡$n ha roto el escudo de éter de %s!' WHERE `ID`=37978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 크나큰 모험이 우리 앞에 놓였다. 보아라. 평화롭게 정글을 거닐던 젊은 여인이 무시무시한 불사조 새끼의 표적이 되었구나!', `MaleText_loc4`='这次冒险的意义已经很明显了。看，当天真的少女在丛林中穿行时，一只凤凰幼鸟却在伺机将她猎杀！', `MaleText_loc5`='看來冒險的開始已經很明確了。看，當遠方那位少女無辜的踏過叢林，年幼的鳳凰將她當成獵物跟蹤著她。', `MaleText_loc7`='Parece que la aventura sale a mi paso. Mirad, pues a esa joven doncella que camina inocentemente por la jungla ¡mientras una cría de fénix la acecha como a una presa!' WHERE `ID`=37979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 저주받은 새가 내 검을 받고 불과 재로 화하는 것을 지켜보아라.', `MaleText_loc4`='看着这只可憎的鸟在被杀死时变成火焰和灰烬吧。', `MaleText_loc5`='看這受詛咒的鳥被殺死後轉化為火焰和灰燼。', `MaleText_loc7`='Observad cómo el abominable pájaro se convierte en llama y ceniza en cuanto le dé muerte.' WHERE `ID`=37980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌로리아를 위하여!', `MaleText_loc4`='为了多罗莉亚！', `MaleText_loc5`='為了朵莉亞!', `MaleText_loc7`='¡Por Doloria!' WHERE `ID`=37981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이상하게도 이 새는 불과 재로 변하지 않는군. 불사조의 시체가 변하지 않다니, 참으로 무시무시한 징조로다.', `MaleText_loc4`='奇怪的是，那只鸟并没有变成火焰和灰烬。一只凤凰在死亡时没有变成火焰和灰烬，这是一个可怕的预兆。', `MaleText_loc5`='真奇怪，這鳥死後並沒變為火焰和灰燼。一隻死後不化為火焰和灰燼的鳳凰...看來這是個很邪惡的詛咒。', `MaleText_loc7`='Es curioso que el pájaro no se convierta en llama y ceniza. Un fénix que no se convierte en llama y ceniza al morir es, sin duda, un temible presagio.' WHERE `ID`=37982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여인이여, 궁금증이 그대를 괴롭히게 하고 싶지는 않소. 그대를 구한 이 사람은 북녘골의 맥시밀리언이라 하오.', `MaleText_loc4`='女士，如果你真的是如此好奇，那么我可以告诉你，是北郡的麦斯米兰拯救了你。', `MaleText_loc5`='少女，如果你的好奇心問道你眼前的人是誰，我可以為你解答。拯救你的人乃是北郡的瑪克西米利安。', `MaleText_loc7`='Doncella: si te carcome la curiosidad, entonces sabes que tu salvador se llama Maximilian de Villanorte.' WHERE `ID`=37983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽉꽉아...', `FemaleText_loc4`='真聒噪……', `FemaleText_loc5`='咯咯咕...', `FemaleText_loc7`='Perico...' WHERE `ID`=37984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하얗게, 깨끗하게!', `MaleText_loc4`='干净整洁！', `MaleText_loc5`='乾淨而整齊!', `MaleText_loc7`='¡Bien limpito!' WHERE `ID`=37985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그렇게 하는 거죠!', `MaleText_loc4`='应该这么干！', `MaleText_loc5`='事情就是這樣做的!', `MaleText_loc7`='¡Así es como se hace!' WHERE `ID`=37986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨어요. 저 얼룩의 정체가 뭔진 알고 싶지 않네요.', `MaleText_loc4`='干得好。我不想知道那点污迹究竟是什么。', `MaleText_loc5`='很好。我一點也不想知道那片污漬是什麼。', `MaleText_loc7`='Genial. No quiero saber de qué era esa mancha.' WHERE `ID`=37987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쿠아노스가 힘든 모양이에요!', `MaleText_loc4`='阿夸诺斯要忙不过来了！', `MaleText_loc5`='阿夸諾斯快跟不上你了!', `MaleText_loc7`='¡Aquanos apenas puede mantener el ritmo!' WHERE `ID`=37988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이랑 친하게 지내야겠네요.', `MaleText_loc4`='我应该留住你的。', `MaleText_loc5`='我應該僱用你才對。', `MaleText_loc7`='Debería tenerte aquí conmigo.' WHERE `ID`=37989;
