UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없군.', `MaleText_loc4`='无能之辈！', `MaleText_loc5`='你什麼都不是!', `MaleText_loc7`='¡No eres nada!' WHERE `ID`=37991;
