UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 나는... 해방되었다...', `MaleText_loc4`='我……终于……解脱了……', `MaleText_loc5`='我...終於...解脫了...', `MaleText_loc7`='Me... he... liberado...' WHERE `ID`=37993;
