UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지가 네 피로 붉게 물들리라!', `MaleText_loc4`='翻腾的仇恨将吞没你们！', `MaleText_loc5`='此地將會被你的鮮血染紅!', `MaleText_loc7`='¡El suelo se vuelve rojo con tu sangre!' WHERE `ID`=37995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들아, 배불리 먹어라!', `MaleText_loc4`='吃吧，奴仆们！', `MaleText_loc5`='吃吧，我的爪牙們!', `MaleText_loc7`='¡Dense un festín, mis lacayos!' WHERE `ID`=37996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어리석은 필멸자들 같으니. 그리 쉽게 우리를 이겼다고 생각했어? 산레인은 리치 왕이 다스리는 불멸의 병사들이야! 이제 합쳐진 그 힘을 보여주겠어!', `FemaleText_loc4`='愚蠢的凡人。你以为能轻易打败我们？萨莱因是巫妖王永生的战士！现在他们将合力撕碎你！', `FemaleText_loc5`='愚蠢的凡人。你以為我們會如此輕易被擊敗?煞婪一族是巫妖王的永恆士兵!現在你將面對他們聯合的力量!', `FemaleText_loc7`='Mortales imbéciles. ¿Pensaron que nos derrotarían tan fácilmente? ¡Los San''layn son los soldados inmortales del Rey Exánime! ¡Ahora se enfrentarán a todo su poder combinado!' WHERE `ID`=37997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저녁이... 준비됐군.', `MaleText_loc4`='晚餐……开席。', `MaleText_loc5`='晚餐...上桌了。', `MaleText_loc7`='La cena... está servida.' WHERE `ID`=37998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 암흑사도의 힘을 알겠느냐?', `MaleText_loc4`='见识到黑暗堕落者的力量了吧？', `MaleText_loc5`='你現在看見暗殞的力量嗎?', `MaleText_loc7`='¿Ahora ves el poder de los Caído Oscuro?' WHERE `ID`=37999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산레인 앞에 무릎 꿇어라!', `MaleText_loc4`='向萨莱因屈服吧！', `MaleText_loc5`='在煞婪一族前屈膝!', `MaleText_loc7`='¡ARRODÍLLENSE ANTE LOS SAN''LAYN!' WHERE `ID`=38000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙사나르에서는 잠시 물러났을 뿐이다! 보주의 힘으로, 발라나르는 복수를 행하리라!', `MaleText_loc4`='纳克萨纳尔的失败早已过去！有了这颗宝珠，瓦拉纳就能完成复仇！', `MaleText_loc5`='納克薩爾不過是一點小挫折!有了寶珠的力量，瓦拉納爾終將復仇!', `MaleText_loc7`='¡Naxxanar fue un pequeño revés! ¡Con el poder de la esfera, Valanar conseguirá su venganza!' WHERE `ID`=38001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 넘치는구나.', `MaleText_loc4`='杯子已经被斟满了。', `MaleText_loc5`='我杯滿溢。', `MaleText_loc7`='Mi copa rebalsa.' WHERE `ID`=38002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 하긴 했느냐?', `MaleText_loc4`='你们也敢来冒犯？', `MaleText_loc5`='你是個威脅嗎?', `MaleText_loc7`='¿Alguna vez fuiste una amenaza?' WHERE `ID`=38003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실은 죽음 안에 있지.', `MaleText_loc4`='死亡才是真谛。', `MaleText_loc5`='真相只存在於死亡。', `MaleText_loc7`='La verdad se halla en la muerte.' WHERE `ID`=38004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님, 저들이... 옵니다.', `MaleText_loc4`='我的女王，他们……来了。', `MaleText_loc5`='女王陛下，他們...來了。', `MaleText_loc7`='Mi reina, se… acercan.' WHERE `ID`=38005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 힘이다! 암흑사도의 보주로 나는 무적이다!', `MaleText_loc4`='如此汹涌的力量！黑暗堕落宝珠让我所向无敌！', `MaleText_loc5`='多美好的力量!暗殞寶珠讓我所向披靡!', `MaleText_loc7`='¡Qué poder tan maravilloso! La Esfera del Caído Oscuro me ha vuelto INVENCIBLE.' WHERE `ID`=38006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가 강을 이루리라.', `MaleText_loc4`='血溅当场吧！', `MaleText_loc5`='血將漫流。', `MaleText_loc7`='Correrá sangre.' WHERE `ID`=38007;
