UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들아, 두려움으로 몸부림쳐라! 보주의 힘이 이 몸에 흐르니 말이다!', `MaleText_loc4`='在塔达拉姆面前颤抖吧，因为我拥有黑暗堕落宝珠的力量！', `MaleText_loc5`='在泰爾達朗前顫抖吧，凡人，因為寶珠的力量在我體內流竄!', `MaleText_loc7`='¡Tiemblen ante Taldaram, mortales, el poder de la esfera fluye en mí!' WHERE `ID`=38010;
