UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 영혼의 지배자를 바라보다니? 집어삼켜 주마, 네놈을 통째로!', `MaleText_loc4`='你竟敢和灵魂之主对视？我会把你一口吃掉！', `MaleText_loc5`='你膽敢凝視眾魂之主?我要將你吞噬殆盡!', `MaleText_loc7`='¿Se atreven a mirar al anfitrión de almas? ¡LOS DEVORARÉ ENTEROS!' WHERE `ID`=38012;
