UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저주받아라, 영원히!', `FemaleText_loc4`='彻底毁灭吧！', `FemaleText_loc5`='永恆的毀滅!', `FemaleText_loc7`='¡Eternamente condenados!' WHERE `ID`=38016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 삼켜지는 걸 막을 수는 없다! 너희는 그저 시간을 조금 늦췄을 뿐이다.', `MaleText_loc4`='灵魂的汹涌不会被削弱！一切都只是徒劳。', `MaleText_loc5`='眾魂的壯大將無法阻擋!你不過是在拖延必然之事。', `MaleText_loc7`='¡No se puede amainar la marejada de almas! Sólo posponen lo inevitable.' WHERE `ID`=38017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼이 삼켜지는 걸 막을 수는 없다! 너희는 그저 시간을 조금 늦췄을 뿐이다.', `FemaleText_loc4`='灵魂的汹涌不会被削弱！一切都只是徒劳。', `FemaleText_loc5`='眾魂的壯大將無法阻擋!你不過是在拖延必然之事。', `FemaleText_loc7`='¡No se puede amainar la marejada de almas! Sólo posponen lo inevitable.' WHERE `ID`=38018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통! 번뇌! 혼돈! 일어나라, 먹어치워라!', `MaleText_loc4`='磨难！痛苦！和混乱！来吧，吃个痛快！', `MaleText_loc5`='受難!苦痛!混亂!甦醒並吞食吧!', `MaleText_loc7`='¡SUFRIMIENTO! ¡ANGUSTIA! ¡CAOS! ¡LEVÁNTENSE Y COMAN!' WHERE `ID`=38019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심연을 들여다보아라. 네 종말이 보이리라.', `FemaleText_loc4`='看这深渊，那里有你的末日。', `FemaleText_loc5`='凝視深淵並看見自己的末日。', `FemaleText_loc7`='Contemplen el abismo y observen su fin.' WHERE `ID`=38020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자꾸 얼쩡거리지 말게, 친구.$B$B왕관화학회사의 축제 용품을 사려거든, 도시 안으로 들어가 사랑의 상인을 만나 보게.', `MaleText_loc4`='朋友，无需四处寻觅。$B$B要买皇冠节日货物，你就一定要去城里的可爱的商贩。', `MaleText_loc5`='別在那邊窺探，朋友。$B$B如果你想買王冠公司節日商品，你可以去找城裡的可愛商品商人。', `MaleText_loc7`='Nada de cotillear, $gamigo:amiga;.$b$bSi quieres comprar regalos festivos de La Corona, tendrás que ir a la mercader preciosa en la ciudad.', `FemaleText_loc1`='자꾸 얼쩡거리지 말게, 친구.$B$B왕관화학회사의 축제 용품을 사려거든, 도시 안으로 들어가 사랑의 상인을 만나 보게.', `FemaleText_loc4`='朋友，无需四处寻觅。$B$B要买Crown holiday goods，你就一定要去城里的Lovely Merchant。', `FemaleText_loc5`='別在那邊窺探，朋友。$B$B如果你想買王冠公司節日商品，你可以去找城裡的可愛商品商人。', `FemaleText_loc7`='Nada de cotillear, $gamigo:amiga;.$b$bSi quieres comprar regalos festivos de La Corona, tendrás que ir a la mercader preciosa en la ciudad.' WHERE `ID`=38021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 금이라네, 친구. 어서 가보게!', `MaleText_loc4`='时间就是金钱，我的朋友。快快快！', `MaleText_loc5`='時間就是金錢，朋友。快快快!', `MaleText_loc7`='El tiempo es oro, colega. ¡Vamos, vamos!', `FemaleText_loc1`='시간은 금이라네, 친구. 어서 가보게!', `FemaleText_loc4`='时间就是金钱，我的朋友。快快快！', `FemaleText_loc5`='時間就是金錢，朋友。快快快!', `FemaleText_loc7`='El tiempo es oro, colega. ¡Vamos, vamos!' WHERE `ID`=38022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑의 상인이 기다리고 있다네. 서두르게!', `MaleText_loc4`='可爱的商贩正等着呢。快点吧！', `MaleText_loc5`='可愛商品商人在等著這個，動作快!', `MaleText_loc7`='La mercader preciosa está esperando esto. ¡Date prisa!', `FemaleText_loc1`='사랑의 상인이 기다리고 있다네. 서두르게!', `FemaleText_loc4`='可爱的商贩正等着呢。快点吧！', `FemaleText_loc5`='可愛商品商人在等著這個，動作快!', `FemaleText_loc7`='La mercader preciosa está esperando esto. ¡Date prisa!' WHERE `ID`=38023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자에 발이 달려서 스스로 배달될 것 같은가, 친구? 어서 움직이게!', `MaleText_loc4`='箱子不会自己长腿走路，朋友。开始干活儿吧！', `MaleText_loc5`='木箱不會自己長腳運送，朋友。快出發吧!', `MaleText_loc7`='Esa caja no se va a entregar sola, $gamigo:amiga;. ¡Muévete!', `FemaleText_loc1`='상자에 발이 달려서 스스로 배달될 것 같은가, 친구? 어서 움직이게!', `FemaleText_loc4`='箱子不会自己长腿走路，朋友。开始干活儿吧！', `FemaleText_loc5`='木箱不會自己長腳運送，朋友。快出發吧!', `FemaleText_loc7`='Esa caja no se va a entregar sola, $gamigo:amiga;. ¡Muévete!' WHERE `ID`=38024;
