UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 가지 않으면, 나 쓰러질지도 몰라.', `MaleText_loc4`='如果我们不慢一些，我也许就要昏过去了。', `MaleText_loc5`='如果我們不放慢點速度，我可能會暈倒。', `MaleText_loc7`='Si no vamos más despacio pronto, puede que me desmaye.' WHERE `ID`=38027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 나 도움이 필요할 것 같은데...', `MaleText_loc4`='嗯……我也许需要点帮助……', `MaleText_loc5`='嗯...我想我可能需要一點幫助...', `MaleText_loc7`='Umm... Creo que necesitaré una mano por aquí...' WHERE `ID`=38028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽... 따귀 한 대만 살짝 때려주면 안 될까...', `MaleText_loc4`='啊……如果你能轻轻地拍拍我的面颊，也许……', `MaleText_loc5`='呃...如果你可以輕輕地打我臉頰一下...', `MaleText_loc7`='Quizá si pudieras golpearme suavito en la mejilla...' WHERE `ID`=38029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 여기 좀 도와달라고!', `MaleText_loc4`='嗨！谁来帮帮忙！', `MaleText_loc5`='喂!幫個忙啊!', `MaleText_loc7`='¡Oye! ¡Un poco de ayuda aquí!' WHERE `ID`=38030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 세게 때렸어야지!', `MaleText_loc4`='你不必这么狠地打我！', `MaleText_loc5`='你也不用打的那麼大力!', `MaleText_loc7`='¡No tenías que pegarme tan FUERTE!' WHERE `ID`=38031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠어, 알겠다고. 가면 되잖아!', `MaleText_loc4`='好，好，要来了！', `MaleText_loc5`='好，好，我繼續走!', `MaleText_loc7`='¡Vale, vale, voy!' WHERE `ID`=38032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워. 마침 그게 필요했거든.', `MaleText_loc4`='谢谢，这正是我需要的。', `MaleText_loc5`='謝啦，正是我所需要的。', `MaleText_loc7`='Gracias, lo necesitaba.' WHERE `ID`=38033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손이 맵다는 사실 알아?', `MaleText_loc4`='你知道你很强壮吗？', `MaleText_loc5`='你知道你很強壯嗎?', `MaleText_loc7`='¿Sabes que eres muy fuerte?' WHERE `ID`=38034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕에게 맞서는 모든 이에게 오늘은 참으로 특별한 날이다! 용감한 $n|1이;가; 은빛 서약단의 이름 아래 고대 검 쿠엘델라를 손에 넣었노라!', `FemaleText_loc4`='对于所有反抗巫妖王的人来说这都是个伟大的日子！以银色盟约的名义，勇敢的$n已经拿起了古剑奎尔德拉。', `FemaleText_loc5`='對於所有對抗巫妖王的人們來說，這是偉大的一天!英勇的$n以白銀誓盟之名拔出了遠古劍刃，奎爾德拉!', `FemaleText_loc7`='¡Es un gran día para los que se oponen al Rey Exánime! ¡$gEl:La; valiente $n ha tomado la antigua espada, Quel''Delar, en nombre de El Pacto de Plata!' WHERE `ID`=38035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버의 지도자로서, 쿠엘델라의 새로운 소유자 $n|1을;를; 자랑스럽게 소개하노라!', `MaleText_loc4`='我以夺日者领袖的身份自豪的宣布$n成为奎尔德拉新的持有者！', `MaleText_loc5`='身為奪日者的領袖，我以極大的榮幸來向諸位介紹，$n，奎爾德拉的新持有者!', `MaleText_loc7`='¡Como líder de los Atracasol, es un honor para mí presentar a $n como $gnuevo portador:nueva portadora; de Quel''Delar!' WHERE `ID`=38036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 냄새가 나는데, 이번엔 내 양말에서 나는 게 아니라고.', `MaleText_loc4`='有东西在发出臭味，这次可不是我的袜子。', `MaleText_loc5`='有東西聞起好臭，而且這次不是我的襪子。', `MaleText_loc7`='Algo huele mal, y por una vez, no son mis calcetines.', `FemaleText_loc1`='뭔가 냄새가 나는데, 이번엔 내 양말에서 나는 게 아니라고.', `FemaleText_loc4`='有东西在发出臭味，这次可不是我的袜子。', `FemaleText_loc5`='有東西聞起好臭，而且這次不是我的襪子。', `FemaleText_loc7`='Algo huele mal, y por una vez, no son mis calcetines.' WHERE `ID`=38037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이 사라진다...', `MaleText_loc4`='希望破灭……', `MaleText_loc5`='希望破滅...', `MaleText_loc7`='Se disipa la esperanza…' WHERE `ID`=38038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성전사와 참가자 여러분, 오늘 진정한 용사가 여러분 앞에 섰습니다! 은빛 서약단의 $n|1이;가; 고대 검 쿠엘델라를 복원하여, 리치 왕을 물리치리라는 우리의 결의를 똑똑히 보여주었습니다!', `FemaleText_loc4`='今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！银色盟约的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！', `FemaleText_loc5`='十字軍與戰士們，今天一位真正的英雄站在你們面前!白銀誓盟的$n，修復了遠古之劍奎爾德拉，這也象徵了我們打倒巫妖王的決心!', `FemaleText_loc7`='¡Cruzados, combatientes, hoy se alza $gun gran héroe:una gran heroína; ante ustedes! ¡$N, de El Pacto de Plata, ha restaurado la antigua espada de Quel''Delar como símbolo de nuestra determinación de vencer al Rey Exánime!' WHERE `ID`=38039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 순간이다!', `MaleText_loc4`='末日降临！', `MaleText_loc5`='末日已然降臨!', `MaleText_loc7`='¡Ha llegado el fin!' WHERE `ID`=38040;
