UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리한이여, 나에게 복종하라!', `MaleText_loc4`='霜之哀伤，服从我！', `MaleText_loc5`='霜之哀傷，服從我!', `MaleText_loc7`='Agonía de Escarcha, ¡OBEDÉCEME!' WHERE `ID`=38043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리한은 쓰러진 네 동료의 영혼으로 배를 채운다!', `MaleText_loc4`='霜之哀伤会饱餐你们盟友的灵魂！', `MaleText_loc5`='霜之哀傷以你倒下同伴的靈魂為食!', `MaleText_loc7`='¡La Agonía de Escarcha se alimenta del alma de tu aliado caído!' WHERE `ID`=38044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙은 껍질만 남을 때까지 네놈을 얼려주마.', `MaleText_loc4`='我会让你的血脉和躯壳化为寒冰！', `MaleText_loc5`='我會將你從內心深處開始凍結起來，直到你只剩下一個冰冷的軀殼。', `MaleText_loc7`='Los congelaré por dentro hasta que sólo quede un cuerpo hueco y helado.' WHERE `ID`=38046;
