UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말... 현명하지 못한... 결정을 했군.', `FemaleText_loc4`='你做了一个……愚蠢的……决定。', `FemaleText_loc5`='你做了一個...不明智的...選擇。', `FemaleText_loc7`='Han tomado una... decisión... necia.' WHERE `ID`=38048;
