UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 군주이자 주인 앞에 무릎 꿇어라!', `MaleText_loc4`='跪拜你的主人和首领吧！', `MaleText_loc5`='臣服於你的主人吧!', `MaleText_loc7`='¡Arrodíllense ante su amo y señor!' WHERE `ID`=38050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발키르여, 네 주인이 부르노라!', `MaleText_loc4`='瓦格里，主人在召唤你！', `MaleText_loc5`='華爾琪，你的主人在呼喚你!', `MaleText_loc7`='Val''kyr, ¡tu amo te llama!' WHERE `ID`=38052;
