UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 지금 스컬지의 신성한 땅 위에 서 있다. 성기사여, 여기서는 빛도 너를 보호하지 못한다. 그 무엇도 널 보호하지 못해...', `MaleText_loc4`='这是天灾军团的神圣土地。圣光在这里毫无用处，圣骑士。你将孤立无援……', `MaleText_loc5`='你現在站在天譴軍團的聖地。聖光在這裡沒辦法保護你，聖騎士。沒有東西能保護你...', `MaleText_loc7`='Ahora estás sobre el suelo sacro de la Plaga. La Luz no te protegerá aquí, paladín. Nada te protegerá…' WHERE `ID`=38054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 넌 나의 가장 위대한 용사가 될 수도 있었다. 어둠의 힘으로 이 세계를 쓸어버리고 투쟁의 새로운 시대를 여는 용사 말이다.', `MaleText_loc4`='弗丁，你本应是我最强大的战士，你的黑暗力量将清洗这个世界，开启一个新的世代。', `MaleText_loc5`='你原可以成為我最強大的勇士，弗丁: 一支黑暗大軍將橫掃整個世界，然後帶來新的爭鬥紀元。', `MaleText_loc7`='Podrías haber sido el mejor de mis campeones, Vadín: una fuerza oscura que asolaría el mundo y lo llevaría a una nueva era de conflictos.' WHERE `ID`=38055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그러한 명예는 네 몫이 아니다. 곧, 새로운 용사가 나타난다.', `MaleText_loc4`='但这个荣耀不属于你了。很快，我将有一名新的勇士。', `MaleText_loc5`='但這樣的殊榮已經不再屬於你了。很快，我將會擁有一位新的勇士。', `MaleText_loc7`='Pero ese honor ya no te pertenece. Pronto, tendré un nuevo campeón.' WHERE `ID`=38056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 정신을 굴복시키는 일은 꽤 힘들었다. 그 영혼을 잔인하게 괴롭혔지... 오랫동안 저항했지만, 머지않아 자신이 섬길 왕 앞에 무릎 꿇고 말리라.', `MaleText_loc4`='我为这个灵魂耗费了巨大的力量，让他承受了无数痛苦……他抵抗了那么长时间，但用不了多久就会屈服了。', `MaleText_loc5`='要破壞這個人的意志並不容易。我對他的靈魂反覆蹂躪。然而他抵抗了如此之久，但很快地，他將會在他的王跟前屈膝。', `MaleText_loc7`='El adiestramiento ha sido agotador. Las atrocidades que he cometido sobre su alma... Ha resistido por mucho tiempo, pero pronto se arrodillará ante su Rey.' WHERE `ID`=38057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 갈증을 느껴봐라!', `FemaleText_loc4`='我饿了！', `FemaleText_loc5`='瞭解我的飢渴!', `FemaleText_loc7`='¡Conozcan mi hambre!' WHERE `ID`=38058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국에는, 나만을 섬기리라.', `MaleText_loc4`='你们最终都要臣服于我。', `MaleText_loc5`='到最後，你們全都將服侍我。', `MaleText_loc7`='Al final, todos me servirán.' WHERE `ID`=38059;
