UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말...? 이게 전부란 말이야?', `FemaleText_loc4`='真的……？你就这点能耐？', `FemaleText_loc5`='真的...嗎?你只有這點能耐嗎?', `FemaleText_loc7`='¿En serio...? ¿Eso es todo?' WHERE `ID`=38066;
