UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 끝을 내주마!', `FemaleText_loc4`='一切都结束了！', `FemaleText_loc5`='就此終結!', `FemaleText_loc7`='¡Esto se termina AHORA!' WHERE `ID`=38068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니... 우리 잘 지냈잖아.. 아주... 친하게...', `FemaleText_loc4`='真是的……我们相处得……那么……好……', `FemaleText_loc5`='但是...我們如此...契...合...', `FemaleText_loc7`='Pero... si nos estábamos llevando… tan… bien…' WHERE `ID`=38069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 성스러운 빛이 자랑하던 정의가 마침내 왔다 이건가? 폴드링, 서리한을 내려놓고 자비라도 애걸하라는 건가?', `MaleText_loc4`='怎么，自诩正义的圣光终于来了？我是不是该丢下霜之哀伤，恳求您的宽恕呢，弗丁？', `MaleText_loc5`='聖光所謂的正義終於來了嗎?我是否該把霜之哀傷放下，祈求你的寬恕呢，弗丁?', `MaleText_loc7`='¿Así que por fin ha llegado la tan anunciada justicia de la Luz? ¿Debería dejar la Agonía de Escarcha y someterme a tu piedad, Vadín?' WHERE `ID`=38070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 깨달으리라. 내 일이 끝나면, 너는 자비를 구걸하겠지. 나는 거부할 테고. 고뇌에 찬 네 비명은 풀려난 내 힘에 대한 서약이 되리라...', `MaleText_loc4`='让我来亲自告诉你。当一切结束，你将跪求我的宽恕－－而我会拒绝你。你痛苦的哀号将是我狂野力量的最好证明……', `MaleText_loc5`='你將會最先體驗到。等我完成的時候，你會乞求我給你一個痛快--而我會拒絕。你的痛苦哀嚎將會是我無窮力量的見證...', `MaleText_loc7`='Lo sabrás en carne propia. Cuando acabe mi trabajo, SUPLICARÁS clemencia... y te la negaré. Tus angustiosos gritos serán el testamento de mi poder desenfrenado…' WHERE `ID`=38071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 너는 살려서 최후를 지켜보게 하겠다. 이 비참한 세상이 내 생각대로 만들어지는 모습을 빛의 가장 위대한 용사가 놓치게 하고 싶지 않다.', `MaleText_loc4`='我会让你活着目睹这个末日，弗丁。这悲惨的世界将在我手中重铸，我不想让圣光最强大的勇士错过这一切。', `MaleText_loc5`='我會讓你活著見證到最後，弗丁。我不會希望聖光最偉大的勇士錯過觀賞這個可悲的世界...如何以「我」的意念重建。', `MaleText_loc7`='Te mantendré con vida para que puedas ver el final, Vadín. No quiero que el mejor campeón de la Luz se pierda cómo quedará este maldito mundo rehecho a mi imagen y semejanza.' WHERE `ID`=38072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 영웅들이여. 너희 분노로 나를 채워라!', `MaleText_loc4`='来吧，勇士们。释放你们的怒火吧！', `MaleText_loc5`='那就來吧，勇士們。讓我享用你們的怒火!', `MaleText_loc7`='Pues vengan, campeones. ¡Aliméntenme con su ira!' WHERE `ID`=38073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 의문도 남지 않았다. 어떤 의심도 없다. 너희는 아제로스의 가장 위대한 용사들이다. 너희 앞에 놓아둔 모든 도전을 극복해 내었다. 가장 강력한 종들이 너희의 무자비한 살육 앞에 쓰러졌지... 너희가 억눌렀던 분노 앞에 말이다...', `MaleText_loc4`='我不再有问题，也不再有疑问。你是艾泽拉斯最强大的勇士。我的阻挠都被你一一化解。我最悍勇的仆从也都倒在了你的无情怒火和利刃之下……', `MaleText_loc5`='沒有問題尚未解答。沒有任何懷疑。你們就是艾澤拉斯最偉大的勇士。你們克服了每一個我所設下的考驗。我最強大的僕人們都在你們不屈不撓的猛攻中倒下...在你們奔放的怒火之中...', `MaleText_loc7`='No quedan preguntas sin respuestas. No quedan dudas. Ustedes SON los campeones más grandes de Azeroth. Superaron todos los retos que les puse. Mis más poderosos sirvientes han caído ante su implacable matanza… su furia desenfrenada…' WHERE `ID`=38074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정으로 정의에 이끌렸단 말이냐? 궁금하구나...', `MaleText_loc4`='真的是正义在驱使你吗？我很好奇……', `MaleText_loc5`='你們的原動力真的是正義感嗎?我很懷疑...', `MaleText_loc7`='Me pregunto... ¿será verdad que los guía la rectitud?' WHERE `ID`=38075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴드링, 훈련을 잘 시켰구나. 역사상 가장 뛰어난 군대를 데려오다니... 바로 내 손에 말이다. 내가 계획한 대로구나! 의도는 아니었겠지만, 희생물을 바쳤으니 합당한 보상이 있으리라.', `MaleText_loc4`='你把他们训练的很好，弗丁。你把世界上最强大的勇士都送到我了的面前，这正合我意！你们的默默牺牲会得到我的褒奖。', `MaleText_loc5`='他們被你訓練得不錯，弗丁。你把這個世界有史以來最強大的戰力...送到我的手中 - 正如我所願!你將因為這無心獻祭而獲得獎賞。', `MaleText_loc7`='Los has entrenado bien, Vadín. Has traído a los mejores luchadores del mundo... directo a mis manos, ¡como yo quería! Te recompensaré por tu sacrificio involuntario.' WHERE `ID`=38076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그들을 죽음에서 일으켜 스컬지의 주인으로 만드는 광경을 지켜보아라. 이 세계를 혼돈과 파괴로 덮을 자들이다. 그들이 직접, 아제로스의 몰락을 가져오리라. 그리고 가장 먼저 네놈부터 처리하리라.', `MaleText_loc4`='亲眼目睹吧，我会把他们从尸骸变为天灾军团的战士。艾泽拉斯会在他们的手中陷入混乱，走向毁灭！而你，将是第一具尸体。', `MaleText_loc5`='現在就看著我把他們從亡者中召回，成為天譴軍團的戰將。他們將會用混亂和毀滅覆蓋這個世界。艾澤拉斯將會在他們手中滅亡 -- 而你會是第一個死者。', `MaleText_loc7`='Observa como los traigo de la muerte para que se conviertan en amos de la Plaga. Cubrirán al mundo en una mortaja de caos y destrucción. La caída de Azeroth llegará de sus manos... Y tú serás el primero en morir.' WHERE `ID`=38077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 참 재미있구나.', `MaleText_loc4`='我会享受这种讽刺。', `MaleText_loc5`='我喜歡這種諷刺感。', `MaleText_loc7`='Me encanta esta ironía.' WHERE `ID`=38078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나라, 형제들이여. 적들을 물리쳐라!', `FemaleText_loc4`='站起来，兄弟们，消灭这些敌人！', `FemaleText_loc5`='復活吧，兄弟們，摧毀我們的敵人!', `FemaleText_loc7`='¡Levántense, hermanos, y destruyan a nuestros enemigos!' WHERE `ID`=38079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼...', `MaleText_loc4`='这不可能...', `MaleText_loc5`='不可能...', `MaleText_loc7`='Imposible...' WHERE `ID`=38080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 하찮은 네놈들 때문에 진짜로 다치다니... 아마 너무 오래 가지고 놀았나보구나... 이제 파멸의 복수를 맛보아라!', `MaleText_loc4`='哼！这些蛆虫居然让我受伤了！… 也许戏弄该结束了……现在－－感受大墓地的复仇吧！', `MaleText_loc5`='啊!你們這些蚊子居然真的弄痛我了...也許我玩弄你們太久了...現在 - 嘗嘗亡者的復仇吧!', `MaleText_loc7`='¡BAH! Estos MOSQUITOS han logrado herirme... Quizá ya haya jugado demasiado con ustedes. Ahora, ¡prueben la VENGANZA DE LA TUMBA!' WHERE `ID`=38081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아아아!', `MaleText_loc4`='AARRRGGHHH!', `MaleText_loc5`='啊啊啊啊!', `MaleText_loc7`='¡AARRRGGHHH!' WHERE `ID`=38082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 처치하라. 그 영혼은 곧 다시 나의 것이 될 테니.', `MaleText_loc4`='拿走它们吧，凡人，这些灵魂很快又将是我的。', `MaleText_loc5`='拿走它們，凡人，這些靈魂很快又會是屬於我的。', `MaleText_loc7`='Llévatelos, mortal. Pronto estas almas serán mías de nuevo.' WHERE `ID`=38083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성전사와 참가자 여러분, 오늘 진정한 용사가 여러분 앞에 섰습니다! 선리버의 $n|1이;가; 고대 검 쿠엘델라를 복원하여, 리치 왕을 물리치리라는 우리의 결의를 똑똑히 보여주었습니다!', `FemaleText_loc4`='今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！夺日者的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！', `FemaleText_loc5`='十字軍與戰士們，今天一位真正的英雄站在你們面前!奪日者的$n，修復了遠古之劍奎爾德拉，這也象徵了我們打倒巫妖王的決心!', `FemaleText_loc7`='¡Cruzados, combatientes, hoy se alza $gun gran héroe:una gran heroína; ante ustedes! ¡$N, de los Atracasol, ha restaurado la antigua espada de Quel''Delar como símbolo de nuestra determinación de vencer al Rey Exánime!' WHERE `ID`=38084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 머지않아 너도 네 무기에 갇히리라.', `MaleText_loc4`='凡人，你很快也会成为剑中的囚徒。', `MaleText_loc5`='快了，凡人，你也很快將被囚禁在劍刃之中。', `MaleText_loc7`='Pronto, mortal, también tendrás una espada por cárcel.' WHERE `ID`=38085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하라. 나도 한때는 위대한 힘을 지닌 무기를 찾아 헤맸었다...', `MaleText_loc4`='记住，英雄：我也曾寻找一件强大的武器……', `MaleText_loc5`='要記得，英雄:我，也曾追尋一件擁有強大力量的武器...', `MaleText_loc7`='Recuerda, héroe: yo también busqué un arma de gran poder alguna vez…' WHERE `ID`=38086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 네 욕심을 채우려고 영혼을 거두는구나. 용사여, 너와 내가 정말 그렇게 다른 존재일까?', `MaleText_loc4`='我看到你也在收集着灵魂，就像我一样。我们真的不同吗，勇士？', `MaleText_loc5`='我看見你為達目的也同樣在收集靈魂。我們有何不同，勇士?', `MaleText_loc7`='Veo que tú también recolectas almas para tus propios fines. ¿Somos tan diferentes, ''campeón''?' WHERE `ID`=38087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 만들어라! 끔찍한 무기를 새로 만들어라. 네 영혼이 내 것이 되면 그 무기도 나를 섬기리라.', `MaleText_loc4`='没错！打造你的恐怖武器吧。它将随着你的灵魂一同为我效命。', `MaleText_loc5`='對，去做!製造屬於你自己的恐怖武器吧。當你的靈魂屬於我的時候，它也將服侍我。', `MaleText_loc7`='¡Sí, hazlo! Crea tu nueva arma monstruosa. También me servirá cuando tu alma sea mía.' WHERE `ID`=38088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기를 나에게 가져오너라, 용사여. 그 주인의 영혼을 먹이리라!', `MaleText_loc4`='带上你的武器，勇士，它会尝到自己主人灵魂的鲜美！', `MaleText_loc5`='把你的武器帶來給我，勇士。我或許會讓它飽食它主人的靈魂!', `MaleText_loc7`='¡Tráeme tu arma, campeón, para que pueda alimentarla con el alma de su amo!' WHERE `ID`=38089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이, 자신을 보아라. 영혼의 주인이 될 자여... 내 마음대로 쓸 수 있는 힘이 어떤 것인지 짐작조차 못 하리라!', `MaleText_loc4`='孩子，你想操纵灵魂吗……你还无法理解我所掌握的力量！', `MaleText_loc5`='看看你自己，孩子;即將持舞著眾多靈魂...你無法揣度它在我指揮下的力量!', `MaleText_loc7`='Mírate, aspirante a portador de almas... ¡Jamás comprenderás el poder que comando!' WHERE `ID`=38090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제넘은 자여, 오너라! 내 검을 배 불려라!', `MaleText_loc4`='狂妄之徒！来祭我的剑吧！', `MaleText_loc5`='到我這兒來，偽善者!餵我的劍!', `MaleText_loc7`='¡Ven a mí, aspirante! ¡Alimenta MI espada!' WHERE `ID`=38091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격려를 좀 해주었더니 강해졌구나, 용사여. 앞으로 날 아주 잘 섬기겠다!', `MaleText_loc4`='我的考验让你变得更强，你将更好地效忠我！', `MaleText_loc5`='我的挑戰讓你力量增長，勇士。你將可以好好服侍我!', `MaleText_loc7`='Mis retos te han fortalecido, campeón. ¡Me servirás bien!' WHERE `ID`=38092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 네 목숨을 살려준 걸 후회할 일은 없구나. 언제나, 나를 즐겁게 하니 말이다.', `MaleText_loc4`='你要知道，凡人，我并不后悔饶你一命，因为你总会给我带来乐趣。', `MaleText_loc5`='我從來沒有後悔過饒你一命，凡人。你總是有辦法娛樂我。', `MaleText_loc7`='Nunca he podido arrepentirme de haberte perdonado la vida, mortal. Siempre encuentras una forma de entretenerme.' WHERE `ID`=38093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재여, 그때가 가까웠다. 새로운 아제로스에서 영원히 나를 섬기리라!', `MaleText_loc4`='你的大限将至，凡人。你将在新的艾泽拉斯永受折磨！', `MaleText_loc5`='時機即將到來，凡人。你們將在嶄新的艾澤拉斯中永世沉淪。', `MaleText_loc7`='Pronto llegará el momento, mortal. Vagarás eternamente en un nuevo Azeroth.' WHERE `ID`=38094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을 더 많이... 그래, 더... 멈추기 어렵다는 것을 깨달으리라.', `MaleText_loc4`='你会发现……对灵魂的渴求……是多么的难以抗拒。', `MaleText_loc5`='更多的靈魂...沒錯，更多...你會發現你將難以自制，凡人。', `MaleText_loc7`='Más almas... Sí, más... Verás que es difícil parar.' WHERE `ID`=38095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기가 느끼는 갈망은 앞으로 닥칠 일의 그림자일 뿐이다. 진정한 갈망을 보고 싶나? 진정한 힘을? 영웅이여, 계속 나아오라. 기다리고 있겠다.', `MaleText_loc4`='你的武器感到了饥饿。这不算什么。想要感受真的饥饿，真的力量吗？继续吧，英雄，我等着你们。', `MaleText_loc5`='你武器所感到的飢渴只不過是未來的冰山一角。你想見識看看真正的飢渴嗎?真正的力量嗎?繼續吧，英雄。我在等著。', `MaleText_loc7`='El hambre que siente tu arma es sólo una sombra de lo que te espera. ¿Quieres ver el verdadero hambre? ¿El verdadero poder? Sigue adelante, héroe. Te espero.' WHERE `ID`=38096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에서 헤매는구나. 여기엔 빛이 없다. 자비도 없다! 얼음왕관에서는 너보다 더 나은 영웅들의 영혼도 사라져갔다.', `MaleText_loc4`='你只能在黑暗中踌躇。那里没有光明，也没有怜悯！冰冠堡垒吞噬过比你更加强大的灵魂。', `MaleText_loc5`='你步入黑暗的歧途，這裡沒有光明。沒有慈悲!寒冰皇冠佔有的靈魂，是遠比你更優秀的英雄。', `MaleText_loc7`='Vas dando tumbos en la oscuridad. Aquí no hay luz. ¡No hay piedad! Corona de Hielo ha tomado las almas de héroes mejores que tú.' WHERE `ID`=38097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 심장이... 끊임없이 고동치는 소리가 역겹구나. 네 심장도 내 것과 마찬가지로 잠잠하게 해 주마.', `MaleText_loc4`='你不停跳动的心脏令我感到厌恶。我会让它停止，就像我的一样。', `MaleText_loc5`='你的心臟 - 那持續的跳動令我作嘔。我要讓它如同我的一樣，永遠靜止。', `MaleText_loc7`='Tu corazón... Su constante palpitar me da asco. Lo acallaré como hice con el mío.' WHERE `ID`=38098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 빛이 너를 저버리리라. 나를 버렸던 것처럼.', `MaleText_loc4`='圣光会抛弃你，英雄，就像抛弃我那样。', `MaleText_loc5`='聖光將會遺棄你，英雄，一如它遺棄了我。', `MaleText_loc7`='La Luz te abandonará, héroe, como hizo conmigo.' WHERE `ID`=38099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='링고가 정신을 잃기 전에 뺨을 때리십시오!', `MaleText_loc4`='狠狠地抽林格，别让他昏过去。', `MaleText_loc5`='在林格暈倒前給他一巴掌!', `MaleText_loc7`='¡Abofetea a Ringo antes de que se desmaye!' WHERE `ID`=38100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물...', `MaleText_loc4`='水……', `MaleText_loc5`='水...', `MaleText_loc7`='Agua...' WHERE `ID`=38101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수통... 수통이 필요해...', `MaleText_loc4`='水壶……水壶……', `MaleText_loc5`='水壺...那那個水壺...', `MaleText_loc7`='La cantimplora... Coge la cantimplora...' WHERE `ID`=38102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 필요해... 시간이 없어...', `MaleText_loc4`='要水……时间不多了……', `MaleText_loc5`='需要水...時間不多了...', `MaleText_loc7`='Necesito agua... poco tiempo...' WHERE `ID`=38103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... 목이 말라...', `MaleText_loc4`='太……太渴了……', `MaleText_loc5`='好渴...好渴...', `MaleText_loc7`='Muy... muy sediento...' WHERE `ID`=38104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 놀라운 검입니다. 그렇죠? 드워프가 만든 건 아닙니다. 네. 훨씬 오래된 검이죠.$B$B선리버와 은빛 서약단의 대표자들은 이 수수께끼를 끝까지 파헤쳐 볼 모양입니다. 전 이미 브란에게 보낼 보고서를 작성하고 있지요.', `MaleText_loc4`='真是一把神器的剑，你觉得呢？这绝不会是出自矮人之手，不，还要古老的多。$B$B这些夺日者和银色盟约的使者似乎打算对这一秘密一探究竟。我已经开始准备给布莱恩的报告了。', `MaleText_loc5`='真是一把令人驚嘆的劍，你不覺得嗎?這不是矮人做得出來的，遠比那些更加古老。$B$B那些奪日者和白銀誓盟的代表似乎打算深究這個謎團。我也已經在撰寫給布萊恩的報告。', `MaleText_loc7`='Es una espada increíble, ¿no crees? No es una espada forjada por los enanos, no, es mucho más antigua.$b$bEsos representantes de los Atracasol y El Pacto de Plata parecen decididos a descubrir el misterio. Ya estoy preparando un informe para Brann.' WHERE `ID`=38105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 세상에서 제일 큰 알을 닭고기처리기에 넣어. 모두가 먹을 기계닭완자를 만들자고!', `MaleText_loc4`='好的，把史上最大的蛋装进变鸡器里。麦可鸡块人人有份儿！', `MaleText_loc5`='格里利，把最大的蛋放進變形器中。每個人都有麥卡雞塊!', `MaleText_loc7`='Greely, carga el huevo más grande del mundo en el Pollotizador. ¡Mecamuslitos para todos!' WHERE `ID`=38106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 드루이드로서 자연의 조화를 지킬 임무가 있습니다. 제 삶은 이를 거역했지요. 저의 어리석음이 혼돈을 자아내었으니, 더 널리 퍼지기 전에 돌연변이 작물을 거둬들여야 합니다.', `MaleText_loc4`='作为德鲁伊，我们的任务就是维护自然的平衡。但我的努力却与此背道而驰。我的愚蠢造成极为巨大的混乱。必须在这种异常的作物进一步扩散之前将它收割。', `MaleText_loc5`='身為德魯伊，我們的任務便是要維護自然界的平衡。我這一生卻與此背道而馳。我愚蠢地製造了混亂，必須在這些畸形的稻草擴散開前把它們割乾淨。', `MaleText_loc7`='Como druidas, se nos encarga proteger el equilibrio de la naturaleza. El trabajo de mi vida ha ido en contra de esto. En mi necedad, he sembrado el caos y esta cosecha desviada ha de ser segada antes de que se extienda.' WHERE `ID`=38107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이곳에 머무르며 대지가 치유되는 과정을 지켜보겠습니다. 남아 있는 생물체들을 조심하십시오.', `MaleText_loc4`='我会留在这里，照看这片正在痊愈的大地。请一定注意来自于这里的游荡者……', `MaleText_loc5`='我會待在這看著這片大地被治療。還是要請你注意一下這裡的離群者...', `MaleText_loc7`='Me quedaré aquí y cuidaré de la tierra mientras se cura. Vigila que no haya rezagados desde aquí...' WHERE `ID`=38108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스, 순식간에 끝내주마. 그동안 너는 무수히 많은 생명을 고통스럽게 빼앗아왔지만 말이다.', `MaleText_loc4`='我们会让你死个痛快，阿尔萨斯。对于犯下累累罪行的你，这是最大的仁慈了。', `MaleText_loc5`='我們會賞你一個痛快，阿薩斯。怎麼說都比數以萬計被你折磨到死的人來得好。', `MaleText_loc7`='Te daremos una muerte rápida, Arthas. Más de lo que se puede decir de los miles que tú has torturado y asesinado.' WHERE `ID`=38109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고보자. 용사들이여, 공격하라!', `MaleText_loc4`='好吧，勇士们，进攻！', `MaleText_loc5`='就這樣吧。勇士們，進攻!', `MaleText_loc7`='Así sea. Campeones, ¡ATAQUEN!' WHERE `ID`=38110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛이여, 마지막 축복을 내려주소서! 이 구속을 깨뜨릴... 힘을 주소서!', `MaleText_loc4`='无上的圣光啊！请祝福我！赐予我力量……帮助我冲破这些枷锁！', `MaleText_loc5`='聖光請賜與我最後的祝福!給我足夠的力量...粉碎這些束縛!', `MaleText_loc7`=' ¡QUE LA LUZ ME DÉ UNA ÚLTIMA BENDICIÓN! ¡DAME LA FUERZA... PARA ROMPER ESTAS ATADURAS!' WHERE `ID`=38111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스, 더는 없으리라! 네 증오에 소중한 생명이 희생되는 일은!', `MaleText_loc4`='结束了，阿尔萨斯！你残害生灵的日子今天结束了！', `MaleText_loc5`='夠了，阿薩斯!不會再有生命被你的仇恨所吞噬!', `MaleText_loc7`='¡Basta, Arthas! ¡¡¡Tu odio ya no consumirá más vidas!!!' WHERE `ID`=38112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕은 쓰러져야만 한다!!', `MaleText_loc4`='巫妖王必须死！', `MaleText_loc5`='巫妖王必須倒下!!', `MaleText_loc7`='¡¡El Rey Exánime DEBE CAER!!' WHERE `ID`=38113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스를 심판하러 왔나? 리치 왕의 최후를 보러?', `MaleText_loc4`='你是来审判阿尔萨斯的吗？想要看到巫妖王的灭亡？', `MaleText_loc5`='你是來制裁阿薩斯的嗎?是來毀滅巫妖王的嗎?', `MaleText_loc7`='¿Han venido a ajusticiar a Arthas? ¿A ver la destrucción del Rey Exánime?' WHERE `ID`=38114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 서리한의 손아귀에서 탈출해야 한다. 그렇지 않으면 나처럼 저주받아 이 가증스러운 검 안에 영원히 갇히리라.', `MaleText_loc4`='首先，你需要摆脱霜之哀伤的控制，否则就会像我一样，永世成为这把邪剑的囚徒。', `MaleText_loc5`='首先，你必須逃離霜之哀傷的支配，否則就會像我一樣，永遠的困在這把受到詛咒的劍裡面。', `MaleText_loc7`='Primero, deben escapar del abrazo de la Agonía de Escarcha o estarán condenados como yo, atrapados en esta espada maldita por toda la eternidad.' WHERE `ID`=38115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고통받은 영혼들을 처리하도록 나를 도와라! 함께 서리한의 지배를 늦추고 안에서부터 리치 왕을 약하게 하자!', `MaleText_loc4`='帮我摧毁这些痛苦的灵魂！我们合力就能弱化霜之哀伤的控制，从内部削弱巫妖王！', `MaleText_loc5`='幫我消滅這些痛苦的靈魂!只要齊心合力，我們可以減輕霜之哀傷的支配，並從中削弱巫妖王的力量!', `MaleText_loc7`='¡Ayúdenme a destruir a estas almas torturadas! ¡Juntos debilitaremos el poder de la Agonía de Escarcha y al Rey Exánime desde dentro!' WHERE `ID`=38116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 풀려났구나! 아들아, 다 끝났다. 응보의 시간이 왔다.', `MaleText_loc4`='终于自由了！结束了，我的儿子。清算的时候到了。', `MaleText_loc5`='終於自由了!結束了，我的兒子。清算的時刻到了。', `MaleText_loc7`='¡Libre al fin! Ha terminado, hijo mío. Es la hora del juicio.' WHERE `ID`=38117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 빛의 용사들이여!', `MaleText_loc4`='圣光的勇士们！集结起来！', `MaleText_loc5`='起身吧，聖光的勇士們!', `MaleText_loc7`='¡Levántense, campeones de la Luz!' WHERE `ID`=38118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋진 생각이세요, 선생님. 전 언제나 선생님 생각 때문에 깜짝깜짝 놀란답니다!', `FemaleText_loc4`='长官，这真是天才的主意。你的智慧总是让我感到吃惊！', `FemaleText_loc5`='這主意太了不起了，長官。你腦子持續為我帶來驚喜!', `FemaleText_loc7`='Una idea genial, señor. ¡Tu ingenio nunca deja de impresionarme!' WHERE `ID`=38119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 소식이에요, 여러분! 수액이 다시 나오는군요!', `MaleText_loc4`='重大喜讯！各位！软泥又开始流动啦！', `MaleText_loc5`='大夥聽著，超級好消息!軟泥又開始流動了!', `MaleText_loc7`='¡Buenas noticias, amigos! ¡La baba ha vuelto a fluir!' WHERE `ID`=38120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 마나 방벽이 가물거리며 사라집니다!', `MaleText_loc4`='%s的法力壁垒闪着微光并在逐渐消退！', `MaleText_loc5`='%s的法力屏障發出閃光並開始消退。', `MaleText_loc7`='¡La Barrera de maná de %s brilla y desaparece!' WHERE `ID`=38121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 소란이지? 감히 이 신성한 땅을 지나가려 해? 여기가 마지막 숨을 거둘 곳이 되리라!', `MaleText_loc4`='是谁在打扰我？你们竟敢擅闯这神圣的地方？这里将会是你们的埋骨之地！', `MaleText_loc5`='這騷動是怎麼回事?你竟敢擅闖聖地?這裡將是你的最終之地!', `MaleText_loc7`='¿Qué es este disturbio? ¿Osan pisar este suelo sagrado? ¡Entonces este será el lugar donde mueran! ' WHERE `ID`=38122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부질없는 짓임을 아직도 깨닫지 못했느냐?', `MaleText_loc4`='你还不明白自己的徒劳吗？', `MaleText_loc5`='你瞭解到自己行為的毫無意義嗎?', `MaleText_loc7`='¿Aún no te das cuenta de la insignificancia de tus acciones?' WHERE `ID`=38123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠을 받아들여라... 영원의 어둠을.', `MaleText_loc4`='拥抱黑暗吧……永恒的黑暗。', `MaleText_loc5`='擁抱黑暗...永恆的黑暗。', `MaleText_loc7`='Abraza la oscuridad... la oscuridad eterna.' WHERE `ID`=38124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 주인님의 계획이다... 너도 죽음을 피할 순 없다...', `MaleText_loc4`='这全是主人的计划……你的结局是必然的……', `MaleText_loc5`='在主人計畫的每一個部分中...你的死亡都是不可避免的...', `MaleText_loc7`='Todo es parte del plan del Amo... Tu final es inevitable…' WHERE `ID`=38125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 내 손으로 직접 처리해야겠구나!', `MaleText_loc4`='够了！看来需要我亲自上阵了！', `MaleText_loc5`='夠了!看來我得親自動手!', `MaleText_loc7`='¡Basta! ¡Veo que debo hacer esto yo misma!' WHERE `ID`=38126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 의지에 저항하기에는 나약하고 무능하구나!', `MaleText_loc4`='软弱的你抵挡不了我强大的意志！', `MaleText_loc5`='你脆弱而且無力抗拒我的意志!', `MaleText_loc7`='¡Eres frágil y débil para resistirte a mi voluntad!' WHERE `ID`=38127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난을 너무 오래 했나 보구나!', `MaleText_loc4`='陪你们玩的够久了！', `MaleText_loc5`='這打啞謎已經進行太久了!', `MaleText_loc7`='¡Esta farsa ya ha durado bastante!' WHERE `ID`=38128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 기다렸던 날이 찾아왔네, 용사여. 그대와 동료들은 리치 왕에게 정의의 심판을 내릴 준비가 되었나? 그대의 지휘에 따라 진격해 나가겠네!', `MaleText_loc4`='我等待这一天的到来已经太久了，英雄。你和你的同袍们是否已经准备好对巫妖王进行正义的审判？我们将在你的命令下向敌人发起冲锋！', `MaleText_loc5`='我已經等了這一天很久了，英雄。你和你的盟友們準備要制裁巫妖王了嗎?只要你一聲令下，我們就會衝鋒殺敵!', `MaleText_loc7`='Hace mucho que espero este día. ¿Están preparados tú y tus aliados para ajusticiar al Rey Exánime? ¡Atacaremos a su señal!' WHERE `ID`=38129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축복을 주노니 이 침입자들에게 주인님의 힘을 맛보여 주어라!', `MaleText_loc4`='来接受这祝福，让入侵者尝尝主人伟大的力量吧！', `MaleText_loc5`='接受祝福並且讓那些入侵者嚐嚐主人的力量!', `MaleText_loc7`='¡Toma mi bendición y muéstrale a estos intrusos el poder del Amo!' WHERE `ID`=38130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다, 대영주님. 아제로스의 운명을 걸고 싸우게 해 주십시오! 여명의 빛을 위하여!', `MaleText_loc4`='我们准备好了，大领主。让我们为艾泽拉斯的命运而战！为冲破黑暗的光明而战！', `MaleText_loc5`='我們準備好了，大領主。讓我們為了艾澤拉斯的命運而戰!為了黎明之光!', `MaleText_loc7`='Estamos preparados, Alto señor. ¡Luchemos por el destino de Azeroth! ¡Por la luz del alba!', `FemaleText_loc1`='준비되었어요, 대영주님. 아제로스의 운명을 걸고 싸우게 해 주세요! 여명의 빛을 위하여!', `FemaleText_loc4`='我们准备好了，大领主。让我们为艾泽拉斯的命运而战！为冲破黑暗的光明而战！', `FemaleText_loc5`='我們準備好了，大領主。讓我們為了艾澤拉斯的命運而戰!為了黎明之光!', `FemaleText_loc7`='Estamos preparados, Alto señor. ¡Luchemos por el destino de Azeroth! ¡Por la luz del alba!' WHERE `ID`=38131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신실한 자들이여, 육신의 구속에서 해방하노라!', `MaleText_loc4`='忠诚的追随者，从血肉的诅咒中解脱吧！', `MaleText_loc5`='讓我將你們從血肉詛咒中釋放!', `MaleText_loc7`='¡Fiel seguidor, te libero de la maldición de la carne!' WHERE `ID`=38132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 순수한 모습을 기뻐하라!', `MaleText_loc4`='来吧，为纯粹的形态欢喜吧！', `MaleText_loc5`='起來，在純粹的形態中感受狂喜!', `MaleText_loc7`='¡Álzate y goza de tu forma pura!' WHERE `ID`=38133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 조잡한 손을 들여다보아라. 힘줄과 살덩이, 그 안에 흐르는 어두운 피까지.', `MaleText_loc4`='好好看看你粗陋的手：看看那肌腱、软肉和其中的黑暗之血。', `MaleText_loc5`='注視你們天生的雙手:精力，柔軟的肉體，奔馳於其中的黑暗血液。', `MaleText_loc7`='Observen con atención sus burdas manos: los tendones, la carne blanda, la oscura sangre que las recorre.' WHERE `ID`=38134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약하고 절뚝거리는 결함일 뿐이다... 창조주가 창조물에게 한 장난인 셈이지.', `MaleText_loc4`='多么的软弱和不堪……这真是造物主的玩笑。', `MaleText_loc5`='這是個弱點;一項嚴重的缺陷...一個造物主對所造之物所開的玩笑。', `MaleText_loc7`='Es una debilidad, un defecto atroz... Una broma de los Creadores a expensas de su creación' WHERE `ID`=38135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신이 부족한 존재임을 빨리 깨달을수록, 그걸 초월하는 자리에 더 빨리 오르리라.', `MaleText_loc4`='你只有承认自己必然的失败，才有可能早日获得更强的力量，重获新生。', `MaleText_loc5`='你們越早認清自己缺陷的狀態，就越早能夠轉變它。', `MaleText_loc7`='Cuanto antes acepten su condición como un defecto, antes estarán listos para superarla.' WHERE `ID`=38136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 통하면, 모든 것이 가능하도다. 그분의 능력은 무한하며, 의지는 굽힘이 없느니라.', `MaleText_loc4`='我的主人是无所不能的，他有无比强大的力量，不可抗拒的意志。', `MaleText_loc5`='透過我們的主人，什麼事情都有可能。他的力量毫無盡頭，他的意志不受束縛。', `MaleText_loc7`='Con nuestro Amo, todo es posible. Su poder es ilimitado y su voluntad, inflexible.' WHERE `ID`=38137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님에 맞서는 자는 완전히 파괴되리라. 주인님을 섬기는 자는... 마음과 영혼을 다 바쳐 온전하게, 의심 없이 섬기는 자는 이해할 수 있는 경지를 넘어 저 높은 곳에 이르렀도다.', `MaleText_loc4`='反抗者必将被毁灭。而那些全身心的，坚定不移的，有虔诚的思想与灵魂的效忠者们，必将得到超乎你们想象范畴的强大的力量。', `MaleText_loc5`='所有反抗他的人終將被摧毀，那些徹底服從全不質疑，心靈完全奉獻的人，終將獲得超遠同族的崇高地位。', `MaleText_loc7`='Los que se le oponen serán destruidos sin excepción, y los que lo sirven... los que lo sirven en cuerpo y alma con total y completa devoción, sin cuestionarle, serán elevados más allá de su comprensión.' WHERE `ID`=38138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 찾아올 수 있었던 것은 네가 앞 못 보는 저주에 걸린 이 세상에서 진정한 눈을 가진 몇 안 되는 자이기 때문이다.', `MaleText_loc4`='你们之所以在这里，那是因为你们是少数几个拥有特殊能力，能够洞悉这诅咒世界的人。', `MaleText_loc5`='你找到了這裡，因為你是這個盲目的詛咒世界中少數具有天賦的人。', `MaleText_loc7`='Han encontrado el camino hasta aquí, porque están entre los pocos dotados con verdadera visión en un mundo ciego.' WHERE `ID`=38139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세계에 수의처럼 드리워진 안개를 헤치고 세상을 보며 진정한 힘이 어디에 있는지 깨달으리라.', `MaleText_loc4`='你们能够看穿遮蔽世界的迷雾，掌握真正的力量。', `MaleText_loc5`='你能看穿覆蓋於迷霧之下的世界，並瞭解真正力量的所在。', `MaleText_loc7`=' Pueden ver la niebla que envuelve este mundo como una mortaja y dónde se encuentra el verdadero poder.' WHERE `ID`=38140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 정말 엄청나게 크군요! 닭고기처리기의 양극을 바꿔보세요. 알을 그 연통으로 밀어 넣어야겠네요.', `FemaleText_loc4`='这蛋可真大！掉转变鸡器的电极。我们得把它推进传送口里。', `FemaleText_loc5`='這東西真巨大!把變形器的極性反轉一下。我們必須將它推過通氣孔。', `FemaleText_loc7`='¡Esta cosa es enorme! Invierte la polaridad del pollotizador. Vamos a tener que meterlo por el escape.' WHERE `ID`=38141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 됐어요. 이제 금방 될 거예요...', `FemaleText_loc4`='就这样吧。应该用不了多久……', `FemaleText_loc5`='這樣就可以了。應該很快就可以了...', `FemaleText_loc7`='Ya está. Debería ser cuestión de segundos...' WHERE `ID`=38142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지...', `MaleText_loc4`='父亲……', `MaleText_loc5`='父親...', `MaleText_loc7`='Padre...' WHERE `ID`=38143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝났다.', `MaleText_loc4`='结束了。', `MaleText_loc5`='完成了。', `MaleText_loc7`='Ya está.' WHERE `ID`=38144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두가 주저앉는 곳을, 너는 넘어섰구나.', `MaleText_loc4`='你赢得了令人胆寒的挑战。', `MaleText_loc5`='當大多數人顫抖退縮時，你卻克服了。', `MaleText_loc7`='Donde muchos fracasarían, tú has vencido.' WHERE `ID`=38145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 직접 안긴 고통을 견뎌냈구나. 이제 어둠한은 네 것이다.', `MaleText_loc4`='你承受住了巫妖王的折磨，现在，影之哀伤是你的了。', `MaleText_loc5`='你抵抗了巫妖王的親手磨難，現在影之哀傷是屬於你了。', `MaleText_loc7`='Has resistido el tormento del mismísimo Rey Exánime y ahora la Agonía de Sombras es tuya.' WHERE `ID`=38146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 떠나라...', `MaleText_loc4`='去吧……', `MaleText_loc5`='現在走吧...', `MaleText_loc7`='Vete...' WHERE `ID`=38147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 강력한 무기를 휘둘러 영혼들을 인도하고 힘을 얻어라.', `MaleText_loc4`='挥舞这强大的武器，指挥那些赋予它力量的灵魂。', `MaleText_loc5`='持舞這把強大的武器並指揮那些增強武器的靈魂。', `MaleText_loc7`='Blande esta poderosa arma y dirige las almas que le dan poder.' WHERE `ID`=38148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가서 어둠의 왕자를 물리쳐라.', `MaleText_loc4`='去吧，去战胜黑暗的王子。', `MaleText_loc5`='走吧，去擊敗黑暗王子。(DO NOT USE?)', `MaleText_loc7`='Ahora vete y derrota al Príncipe de las Tinieblas.' WHERE `ID`=38149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지. 아버지 정신이... 온전하실지 걱정스러웠습니다.', `MaleText_loc4`='父亲。你的圣洁……让我，感到战栗。', `MaleText_loc5`='父親。我-我對你的...你的理智感到憂心。', `MaleText_loc7`='Padre. Temía por tu... tu cordura.' WHERE `ID`=38150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지... 아버지를 위해서라면 천 번이라도 목숨을 바칠 겁니다.', `MaleText_loc4`='父亲……为了你，我万死不辞。', `MaleText_loc5`='父親...為了你，獻出一千次生命我也願意。', `MaleText_loc7`='Padre... por ti, daría mi vida mil veces.' WHERE `ID`=38151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리온, 내 아들아.', `MaleText_loc4`='达里安，我的孩子。', `MaleText_loc5`='達瑞安，我的兒子。', `MaleText_loc7`='Darion, hijo mío.' WHERE `ID`=38152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 이 눈으로 다시 너를 보는 날이 왔구나.', `MaleText_loc4`='终于，我能够重新见到你了。', `MaleText_loc5`='我終於又能親眼見到你了。', `MaleText_loc7`='Por fin puedo verte otra vez.' WHERE `ID`=38153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리온, 리치 왕은 내게 끝없는 고통을 주었다.', `MaleText_loc4`='巫妖王一直在折磨我，达里安。', `MaleText_loc5`='巫妖王不斷地折磨著我，達瑞安。', `MaleText_loc7`='El Rey Exánime me atormentó sin descanso, Darion.' WHERE `ID`=38154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없이, 내 의지를 꺾어 자신을 섬기고 그 검과 결속되게 하려 애쓰더구나...', `MaleText_loc4`='无休无止，他想要击溃我的意志，让我屈服，成为剑中的冤魂……', `MaleText_loc5`='他不停地設法要摧毀我的意志，想強迫我服侍他，想把我束縛在他的劍上面...', `MaleText_loc7`='Sin fin, buscó destruir mi voluntad para obligarme a servirle y vincularme a su espada…' WHERE `ID`=38155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국, 다른 일에 모든 관심을 쏟아야 하자 나를 떠났다.', `MaleText_loc4`='最后，战争让他无暇分身，他才放弃了我。', `MaleText_loc5`='最後，當事情的演變需要他全力應付的時候，他才離開。', `MaleText_loc7`='Al final, cuando la situación reclamó toda su atención, me dejó.' WHERE `ID`=38156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 매달렸던, 날 견딜 수 있게 했던 그 한 가지는... 다리온...', `MaleText_loc4`='有个回忆，是我的力量，达里安……是让我不被奴役的力量……', `MaleText_loc5`='我緊抓著不放的回憶，達瑞安...唯一使我不至於屈服的念頭...', `MaleText_loc7`='El pensamiento al que me aferraba, Darion... El recuerdo que evitó que cediera...' WHERE `ID`=38157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원한 재앙에서 나를 다시 구해낸 네 희생에 대한 기억이었다.', `MaleText_loc4`='那就是你的牺牲，我的儿子，再度拯救我于万劫不复。', `MaleText_loc5`='是你的犧牲，我的兒子，那讓我又再次從永恆的險境中得救。', `MaleText_loc7`='Fue tu sacrificio, hijo mío, que de nuevo me salvó del peligro eterno.' WHERE `ID`=38158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주게, 친구. 영혼의 힘을 빌어 환영을 보세.', `FemaleText_loc4`='朋友们，帮帮我。让我们召唤卡尔加的幻像。', `FemaleText_loc5`='幫助我，朋友。讓我們一起呼喚精靈作為我們的雙眼。', `FemaleText_loc7`='Ayudadme, amigos míos. Pidamos una visión a los espíritus.' WHERE `ID`=38159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아서스...', `MaleText_loc4`='阿尔萨斯……', `MaleText_loc5`='阿薩斯...', `MaleText_loc7`='Arthas...' WHERE `ID`=38160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 아제로스의 영웅이여. 내게 아주 큰 선물을 주었네.', `MaleText_loc4`='艾泽拉斯的英雄们，你们对我的恩泽远超想象。', `MaleText_loc5`='啊，艾澤拉斯的英雄，你送我的禮物比你所想的還要珍貴。', `MaleText_loc7`='Héroe de Azeroth, me has dado un obsequio más grande de lo que crees.' WHERE `ID`=38161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안, 끔찍한 죄악을 저지른 그 왕자를 용서하려고 애썼지.', `MaleText_loc4`='长久以来，我苦苦地想要宽恕王子的滔天罪行。', `MaleText_loc5`='長久以來我一直都很難去原諒王子他可怕的墮落。', `MaleText_loc7`='Mucho tiempo he luchado por perdonar al príncipe por sus terribles transgresiones.' WHERE `ID`=38162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참을 수 없는 불안과 어두운 생각으로... 빛에서 멀어진 내 영혼은 괴롭기 그지없었네.', `MaleText_loc4`='焦虑和痛苦撕扯着我的灵魂，邪恶的念头……让我远离圣光。', `MaleText_loc5`='難以承受的焦慮和黑暗的想法折磨著我的靈魂...使我和聖光漸行漸遠。', `MaleText_loc7`='Mi alma ha sido devastada con una ansiedad insoportable, con pensamientos oscuros... que me alejaron de la Luz.' WHERE `ID`=38163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모험을 떠날 준비가 되었습니다.', `MaleText_loc4`='麦斯米兰，我已经准备好进行冒险了。', `MaleText_loc5`='瑪克西米利安，我準備好要探險了。', `MaleText_loc7`='Maximillian, estoy preparado para la aventura.', `FemaleText_loc1`='이제 모험을 떠날 준비가 되었습니다.', `FemaleText_loc4`='麦斯米兰，我已经准备好进行冒险了。', `FemaleText_loc5`='瑪克西米利安，我準備好要探險了。', `FemaleText_loc7`='Maximillian, estoy preparada para la aventura.' WHERE `ID`=38164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에 섰을 때, 그의 눈에 빛나던 긍지를 똑똑히 기억하네. 빛의 적들을 물리치겠다는 간절함과...', `MaleText_loc4`='我清晰地记得他眼中的光芒，那光芒带着荣耀，带着击败圣光之敌的热切……', `MaleText_loc5`='我還能清楚地想起他站在我面前時眼中所閃爍的傲氣，渴望要擊敗聖光的敵人...', `MaleText_loc7`='Recuerdo claramente el brillo de orgullo en sus ojos cuando se paraba frente a mí, ansioso por vencer a los enemigos de la Luz…' WHERE `ID`=38165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게해서든 자기 백성을 지키겠다는 간절함도.', `MaleText_loc4`='带着宁死也要保护人民的决心……', `MaleText_loc5`='渴望著守護他的人民，無論任何代價...', `MaleText_loc7`='Ansioso por defender a su gente, sin importar el costo...' WHERE `ID`=38166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 내가 마음속에 간직하기로 한 아서스의 기억일세.', `MaleText_loc4`='这就是阿尔萨斯，我要永记于心的阿尔萨斯。', `MaleText_loc5`='這才是我選擇要記在心裡的阿薩斯。', `MaleText_loc7`='Es esta memoria de Arthas la que elijo guardar en mi corazón.' WHERE `ID`=38167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 진 빚은 영원히 남을 걸세.', `MaleText_loc4`='朋友，你们的恩情没齿难忘。', `MaleText_loc5`='我會永遠記得欠你的人情，朋友。', `MaleText_loc7`='Estaré en deuda contigo por siempre, amigo.' WHERE `ID`=38168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네.', `MaleText_loc4`='谢谢。', `MaleText_loc5`='謝謝你。', `MaleText_loc7`='Gracias.' WHERE `ID`=38169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 꺼, 끄라고! 알이 못쓰게 됐잖아!!!', `MaleText_loc4`='关掉它，关掉它！这些蛋有问题！！！', `MaleText_loc5`='關起來，關起來!那些蛋是壞掉的!!!', `MaleText_loc7`='¡Apágalo! ¡Apágalo! ¡Los huevos no valen!' WHERE `ID`=38170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런...', `MaleText_loc4`='哦，伙计……', `MaleText_loc5`='噢，老弟...', `MaleText_loc7`='Oh, muchacho...' WHERE `ID`=38171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 끝없던 로데론의 날들을 어떻게 잊겠나...', `MaleText_loc4`='我忘不了在洛丹伦的那些日子……', `MaleText_loc5`='我多麼懷念羅德隆那些日子...', `MaleText_loc7`='Cómo extraño esos días eternos en Lordaeron...' WHERE `ID`=38172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...자네가 이 무딘 검과 함께 기술을 갈고 닦으며...', `MaleText_loc4`='……用这把钝剑训练你的剑术……', `MaleText_loc5`='...用這把鈍劍磨練你的技巧...', `MaleText_loc7`='…afinando tu habilidad con esa espada roma…' WHERE `ID`=38173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...위대한 운명의 부름에 맞서고자 자신을 병기로 단련하던 그때를 말이네.', `MaleText_loc4`='……让你成才，期待着你去完成伟大的使命。', `MaleText_loc5`='...把你打造成一把可以承受偉大宿命的武器。', `MaleText_loc7`='...moldeándote en un arma que debía soportar las exigencias de un gran destino.' WHERE `ID`=38174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... 그렇게 익힌 기술은 써 봤을 테지. 안 그런가?', `MaleText_loc4`='呵呵……那些功夫没有白费，不是吗，伙计？', `MaleText_loc5`='呵...你學到的那些技巧用得可真不錯，不是嗎，老弟?', `MaleText_loc7`='Sí... Sí, utilizaste bien esas habilidades, ¿verdad, muchacho?' WHERE `ID`=38175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날 자네를 막을 수만 있었다면, 상황이 얼마나 달라졌을까 싶네.', `MaleText_loc4`='如果那天我能阻止你，也许一切都会不一样。', `MaleText_loc5`='如果我那天可以阻止你，這一切該會有多麼不一樣。', `MaleText_loc7`='Si hubiera podido pararte aquel día, qué diferentes habrían sido las cosas.' WHERE `ID`=38176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그 저주받은 검을 찾아내지만 않았어도...', `MaleText_loc4`='要是我从没发现过那把被诅咒的剑……', `MaleText_loc5`='如果我從來沒發現過那把該死的劍就好了...', `MaleText_loc7`='Si nunca hubiera descubierto esa maldita espada...' WHERE `ID`=38177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게, 아서스... 내 형제여.', `MaleText_loc4`='再见了，阿尔萨斯……好兄弟。', `MaleText_loc5`='再見了，阿薩斯...我的兄弟。', `MaleText_loc7`='Adiós, Arthas... hermano mío.' WHERE `ID`=38178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게, 끝났구나.', `FemaleText_loc4`='一切都结束了。', `FemaleText_loc5`='看來，是結束了。', `FemaleText_loc7`='Está listo, entonces.' WHERE `ID`=38179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 느낌을 믿을 수가 없었다. 너무나 여러 번 리치 왕에게 속았기 때문에 말이다.', `FemaleText_loc4`='我不敢相信这是真的——因为巫妖王已经愚弄我太多太多次了。', `FemaleText_loc5`='我還是不敢相信我雙眼所見的一切 - 巫妖王已經愚弄我太多次了。', `FemaleText_loc7`='No me atrevería a confiar en mis sentidos; no sería la primera vez que el Rey Exánime me hace quedar como una tonta.' WHERE `ID`=38180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어, 내 백성에게 저질렀던 수많은 죄악의 대가를 치렀구나.', `FemaleText_loc4`='他对我们犯下累累罪行，现在他终于付出了代价。', `FemaleText_loc5`='終於，他為加諸在我的子民身上的暴行付出了代價。', `FemaleText_loc7`='Al fin se le ha hecho pagar por las atrocidades que desató sobre mi gente.' WHERE `ID`=38181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가자, 내 종자야. 모험이 우리를 기다린다!', `MaleText_loc4`='来吧，侍从$n，冒险正等待着我们！', `MaleText_loc5`='來吧，侍從$n，冒險等著我們!', `MaleText_loc7`='¡Ven, $gescudero:escudera; $n, pues nos esperan aventuras!' WHERE `ID`=38182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약함과 자존심 때문에 치렀던 끔찍한 대가를 아제로스가 잊지 않기를.', `FemaleText_loc4`='愿艾泽拉斯不要忘记那曾因软弱和傲慢所付出的沉重代价。', `FemaleText_loc5`='希望艾澤拉斯不會忘記我們是因為軟弱...和傲慢，而付出了慘痛的代價。', `FemaleText_loc7`='Que Azeroth nunca olvide el precio terrible que hemos pagado por nuestra debilidad... por nuestro orgullo.' WHERE `ID`=38183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 이제 어찌해야 하는가? 그의 손아귀에서 벗어났지만, 여전히 필멸의 굴레에 묶인 이들은?', `FemaleText_loc4`='但现在呢，英雄？那些摆脱了他的束缚，却无法摆脱凡尘俗世的人呢？', `FemaleText_loc5`='接下來又如何呢?那些脫離掌控，卻仍被禁錮在軀殼內的人又該怎麼辦?', `FemaleText_loc7`='Pero ¿y ahora qué, héroe? ¿Qué pasará con esos que liberaste de su control, pero siguen condenados a vivir en la muerte?' WHERE `ID`=38184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼자 있고 싶구나.', `FemaleText_loc4`='退下。', `FemaleText_loc5`='離開吧。', `FemaleText_loc7`='Déjenme.' WHERE `ID`=38185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생각할 것이 많다.', `FemaleText_loc4`='我的思绪很乱。', `FemaleText_loc5`='我得好好想一想。', `FemaleText_loc7`='Tengo mucho que reflexionar.' WHERE `ID`=38186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 혼자 모험하고 싶습니다.', `MaleText_loc4`='我想，我要孤身走一段冒险的征程了。', `MaleText_loc5`='我想要暫時一個人探險。', `MaleText_loc7`='Creo que me aventuraré solo un rato.', `FemaleText_loc1`='잠시 혼자 모험하고 싶네요.', `FemaleText_loc4`='我想，我要孤身走一段冒险的征程了。', `FemaleText_loc5`='我想要暫時一個人探險。', `FemaleText_loc7`='Creo que me aventuraré sola un rato.' WHERE `ID`=38187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아감마간을 부활시키려면 피가 필요해! 제물이 필요하다!', `FemaleText_loc4`='没有了血，阿迦玛甘将无法再次崛起！他的躯体在渴求祭品！', `FemaleText_loc5`='阿迦瑪甘沒有鮮血是不會甦醒的!他的身體需要犧牲品!', `FemaleText_loc7`='¡Agamaggan no se alzará de nuevo sin SANGRE! ¡Su cuerpo exige sacrificio!' WHERE `ID`=38188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가라! 가서 우리 땅을 정복하라! 가시멧돼지가 세상을 지배하는 날, 우리는 해방되리라. 그리고 아감마간이 부활하리라!', `FemaleText_loc4`='走！去夺回我们的土地！当野猪人得到了一切，我们也将得到我们所要的。阿迦玛甘将再次崛起！', `FemaleText_loc5`='去吧!去奪走我們的土地!當一切都歸野豬人所有時，我們也將會是其中之一，阿迦瑪甘也將再次甦醒!', `FemaleText_loc7`='¡Id! ¡Id y tomad nuestra tierra! ¡Cuando todo pertenezca a los jabaespines, seremos libres y Agamaggan se alzará de nuevo!' WHERE `ID`=38189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분께서 내게 말씀하셨도다...가서, 죽이라고!', `FemaleText_loc4`='这就是他对我说的……去战斗！', `FemaleText_loc5`='他有跟我說過這個...去吧，殺!', `FemaleText_loc7`='Ha hablado conmigo y me ha dicho: "Ve... ¡y MATA!"' WHERE `ID`=38190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇군... 모두를 조종하기 위해 그를 이용하는 게야...', `FemaleText_loc4`='我明白了……她在利用他操纵他们所有人……', `FemaleText_loc5`='這樣啊...她利用他來控制他們全部...', `FemaleText_loc7`='Ya veo... La está utilizando para manipularlos...' WHERE `ID`=38191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라, 종자야. 저 여인이 골락카 간헐천의 유황물 속에 손지갑을 빠뜨렸구나.', `MaleText_loc4`='看啊，侍从，那位少女的荷包掉在了葛拉卡温泉的硫磺水中。', `MaleText_loc5`='聽著，侍從，那位少女的皮包掉進了葛拉卡溫泉的硫磺水中了。', `MaleText_loc7`='Mira, escudero, la joven doncella ha perdido su bolsa en las sulfurosas aguas de los Baños de Golakka.' WHERE `ID`=38192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여인이여! 두려워 마시오. 이 기사는 떨리는 그대의 입술에 평화를 주고 싶을 뿐이니. 손에 잡힐 듯 가까우면서 아득히 먼 곳에 떠다니는 저것이 그대의 손지갑이오?', `MaleText_loc4`='姑娘！不要害怕，我只是要让你的嘴唇不再颤抖。那个漂在水上的是不是你的荷包？小心，那温泉是很危险的。', `MaleText_loc5`='少女!別怕!我的目標就是讓你那美麗的嘴唇不再顫抖。那個浮在水上的皮包是你的嗎?遠在天邊，近在眼前?', `MaleText_loc7`='¡Doncella! No temas, tan solo deseo que tu fino labio deje de temblar. ¿Acaso es tu bolsa eso que flota en el agua, tan agonizantemente cerca pero, sin embargo, tan peligrosamente lejos?' WHERE `ID`=38193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 제 손지갑... 아니 소지품이 맞긴 한데 전 여인이...', `MaleText_loc4`='什么？是的，这是我的……箱子。还有，我不是……', `MaleText_loc5`='什麼?呃對，那是我的...箱子。還有...我不是一個...', `MaleText_loc7`='¿Qué? Sí, eso es mi... cajón. Y no yo no soy...' WHERE `ID`=38194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 걱정하지 마시오. 그대같이 어여쁜 여인은 많은 남성을 사로잡아 마땅하나, 이 기사의 심장은 오로지 돌로리아의 것이니.', `MaleText_loc4`='你不什么？不会接受我？不必担心，我的心只属于多罗莉亚女士。但像你这样美丽的女子一定能征服许多男人的心。', `MaleText_loc5`='你不是什麼?不是單身的人?別擔心，我的心只屬於朵莉亞女士，但像你如此美麗的少女一定能俘虜許多人的心。', `MaleText_loc7`='¿No sois qué? ¿Soltera? No os preocupéis, pues mi corazón pertenece tan solo a mi Lady Doloria, aunque alguien tan hermosa como vos debe conquistar los corazones de muchos hombres.' WHERE `ID`=38195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 종자가 그대의 손지갑을 찾아줄 것이오.', `MaleText_loc4`='我的侍从会为你取回荷包。', `MaleText_loc5`='我的侍從會把你的皮包拿回來。', `MaleText_loc7`='Mi escudero recuperará tu bolso.' WHERE `ID`=38196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 어떻게 반응해야 할지 난감한 건 둘째치고, 엄청나게 모욕적이군요. 어쨌든 제 손지갑, 아니 상자를 돌려준 건 고맙습니다!', `MaleText_loc4`='除了感觉受到了严重的冒犯，我真不知道该怎样形容我今天的遭遇。谢谢你把荷包还给我。我是说箱子！', `MaleText_loc5`='我不確定這一切代表了什麼，我只覺得我被嚴重羞辱了。噢，謝謝你把我的皮包拿了回來...我是說箱子!', `MaleText_loc7`='No sé qué pensar de todo esto, aparte de sentirme muy insultado. Y gracias por recuperar mi bolso, quiero decir, cajón.' WHERE `ID`=38197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자야, 어서 가자. 모험은 우릴 기다려주지 않는다!', `MaleText_loc4`='来吧，侍从。冒险可不会等人！', `MaleText_loc5`='快，侍從，冒險是不等人的!', `MaleText_loc7`='Ven, $gescudero:escudera;. ¡La aventura no aguarda!' WHERE `ID`=38198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바엘 모단... 드워프...', `MaleText_loc4`='巴尔莫丹……那些矮人……', `MaleText_loc5`='巴爾莫丹...矮人們...', `MaleText_loc7`='Bael Modan... Los enanos...' WHERE `ID`=38199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흉터가 봉인되었습니다! 세나리우스에게 감사를...', `MaleText_loc4`='这道伤痕被封印了！感谢塞纳留斯……', `MaleText_loc5`='傷痕被封印起來了!謝謝你，塞納留斯...', `MaleText_loc7`='¡La cicatriz está sellada! Gracias, Cenaruis...' WHERE `ID`=38200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 뭐죠!?', `FemaleText_loc4`='这是什么？', `FemaleText_loc5`='這...這是!?', `FemaleText_loc7`='¿¡Qué es esto!?' WHERE `ID`=38201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가... 가지고 있었다고요? 계속, 가지고 있었어요?', `FemaleText_loc4`='这……他还留着？一直以来，他还带着它？', `FemaleText_loc5`='他 - 他還留著它?過了這麼久，他還留著它!?', `FemaleText_loc7`='¿Lo... Lo ha guardado? Todo este tiempo, ¿lo ha guardado?' WHERE `ID`=38202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 줄 알았어요!', `FemaleText_loc4`='我知道！', `FemaleText_loc5`='我就知道!', `FemaleText_loc7`='¡Lo sabía!' WHERE `ID`=38203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스의 일부가 살아 있을 줄 알았어요! 갇힌 채... 괴로워하며... 오, 아서스!', `FemaleText_loc4`='我还能感觉到他！饱受摧残……苦苦挣扎……啊，阿尔萨斯！', `FemaleText_loc5`='我感覺到他的一部分還存在!困在其中...不斷掙扎...噢，阿薩斯!', `FemaleText_loc7`='Sentía que parte de él seguía vivo. Atrapado... luchando... ¡Oh, Arthas!' WHERE `ID`=38204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩌면... 그가 예전 모습을 기억해 냈을지도 몰라요.', `FemaleText_loc4`='也许……也许有一天，他会想起真正的自己。', `FemaleText_loc5`='也許 - 也許有天他會再記起原本的自己。', `FemaleText_loc7`='Quizá, quizá un día podrá recordar quién fue una vez.' WHERE `ID`=38205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛이시여, 그가 끔찍한 검의 차가운 손아귀에서 벗어나 평안하기를.', `FemaleText_loc4`='圣光啊，愿他摆脱那把魔剑的寒冷束缚，魂归故里。', `FemaleText_loc5`='以聖光之名，希望他終究能獲得安息，脫離那把詛咒之劍冰冷的掌控。', `FemaleText_loc7`='Por la Luz, que encuentre reposo, libre de la garra gélida de esa terrible espada.' WHERE `ID`=38206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 자네로구만...내 영혼을 안정시킨답시고 쓸데없는 노력을 기울일 필요는 없네. 그녀 없이는 마음의 안정을 되찾을 수 없다는 걸 깨달았네. 안되고 말고.$B$B놈들의 서식지가 완전히 파괴되는 광경을 꼭 지켜보고야 말겠어. 역겨운 살인자들을 더 해치울 준비는 됐나?', `MaleText_loc4`='又是你……真希望你不曾如此尽心竭力地想要安抚我的灵魂。我早就明白，没有了她，就不会有和平，再也不会有了。$B$B我要将他们的家全部夷为平地。你准备好消灭这些可憎的杀人犯了么？', `MaleText_loc5`='又是你...我希望你不要對安置我的靈魂這件事抱有太大的希望。我瞭解到在沒有她的狀況下我是無法得到平靜的。$B$B我要看到他們的家鄉被夷平。你準備好殺死更多這些噁心的殺人兇手了嗎?', `MaleText_loc7`='Tú de nuevo... Espero que no tuvieras mucha fe en tus acciones para calmar mi espíritu. Me he dado cuenta de que no volverá a haber paz sin ella.$B$BMe encargaré de arrasar sus hogares. ¿Estás $gpreparado:preparada; para seguir matando a esos asesinos asquerosos?' WHERE `ID`=38207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오! 제 물건을 간헐천에 빠뜨렸습니다.$b$b안에는 저의 제복이 들어 있습니다!', `MaleText_loc4`='救救我！我的东西都掉在这个热泉里了。$b$b我的长袍就在那里！', `MaleText_loc5`='救救我!我的東西掉進溫泉裡了。$b$b我的袍子掉進去了!', `MaleText_loc7`='¡Sálvame! Se me han caído mis posesiones en los baños.$b$b¡Todas mis togas están ahí!' WHERE `ID`=38208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운의 여신이 미소 짓는구나! 한 숙녀가 속절없이 바위에 갇혀 오도 가도 못하고 있다! 저 여인을 구하자!', `MaleText_loc4`='幸运在召唤我们！一位少女出现在我们面前，她被困在高耸的悬崖上！让我们去拯救她！', `MaleText_loc5`='幸運今天與我們同在!一個少女出現在我們眼前，身陷險崖，沒有逃脫的希望!讓我們去英雄救美!', `MaleText_loc7`='¡La fortuna nos acompaña! ¡Una damisela aparece ante nosotros, atrapada en un peñasco, sin escape posible! ¡Salvémosla!' WHERE `ID`=38209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여인이여! 두려워 마시오. 북녘골의 맥시밀리언이 그대를 바위 무덤에서 구해내리다!', `MaleText_loc4`='姑娘！不要害怕，北郡的麦斯米兰将把你从岩壁牢狱中拯救下来！', `MaleText_loc5`='少女!別怕，北郡的瑪克西米利安已來這把你從那岩石古墓中救出來!', `MaleText_loc7`='¡Doncella! No temas, pues Maximilian de Villanorte ha llegado para liberarte de tu tumba rocosa.' WHERE `ID`=38210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이얍!', `MaleText_loc4`='嚯！', `MaleText_loc5`='汪汪!', `MaleText_loc7`='¡Arriba!' WHERE `ID`=38211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 울지 마시오. 그대는 차디찬 죽음이 아닌 내 종자의 두 팔 안에 떨어질 테니! 자, 가시오!', `MaleText_loc4`='不要哭，你不会跌向死亡，而是会跌落在我的侍从的臂弯里！现在，松开手吧！', `MaleText_loc5`='別哭!因為你掉入的並不是死亡的懷抱，而是我等待已久的侍從的懷抱!快走吧!', `MaleText_loc7`='¡No lloréis, pues no caeréis en las fauces de la muerte, sino en los brazos anhelantes de mi escudero! ¡Adelante!' WHERE `ID`=38212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠나기 전에 한마디 해야겠소. 그대가 이렇게 된 건 내가 아닌 내 종자의 잘못이라는 점을 부디 알아주시오.', `MaleText_loc4`='在我离开之前，我要告诉你，你会躺在地上不是我的错，而是我的侍从的错。', `MaleText_loc5`='在我離開前，你必須瞭解會摔倒在地上並不是我的錯，而是我侍從的錯。', `MaleText_loc7`='Antes de que parta, debéis saber que no es por mi culpa que yazcáis en el suelo de esa manera, sino de mi escudero.' WHERE `ID`=38213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 이제 그대는 산의 손아귀를 벗어나 자유를 찾았소. 동쪽에 마샬의 격전지가 있을 거요.', `MaleText_loc4`='不管怎样，你现在已经摆脱了高山的魔爪，不会再受伤害了。马绍尔哨站大概就在东边。', `MaleText_loc5`='儘管如此，你已經不再被困在山中，也安全了。我相信馬紹爾觀測站就在這裡的東方。', `MaleText_loc7`='Sea como sea, ahora estáis libre de la prisión de la montaña y a salvo de todo daño. Alto de Marshal queda al este, creo.' WHERE `ID`=38214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 20분 후에 시작됩니다!', `MaleText_loc4`='卡鲁亚克钓鱼大赛将在20分钟后开始！', `MaleText_loc5`='卡魯耶克釣魚大賽即將在20分鐘後開始!', `MaleText_loc7`='¡La competición de pesca Kalu''ak empieza en 20 minutos!' WHERE `ID`=38215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 10분 후에 시작됩니다!', `MaleText_loc4`='卡鲁亚克钓鱼大赛将在10分钟后开始！', `MaleText_loc5`='卡魯耶克釣魚大賽即將在10分鐘後開始!', `MaleText_loc7`='¡La competición de pesca Kalu''ak empieza en 10 minutos!' WHERE `ID`=38216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 5분 후에 시작됩니다!', `MaleText_loc4`='卡鲁亚克钓鱼大赛将在5分钟后开始！', `MaleText_loc5`='卡魯耶克釣魚大賽即將在5分鐘後開始!', `MaleText_loc7`='¡La competición de pesca Kalu''ak empieza en 5 minutos!' WHERE `ID`=38217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 시작되었습니다! 흑기흉상어를 달라란에 있는 제게 가장 먼저 가져오시는 분이 우승자입니다! 흑기흉상어는 난쟁이 빨판상어가 낚이는 곳이라면 어디서나 잡을 수 있습니다.', `MaleText_loc4`='卡鲁亚克钓鱼大赛已经开始了！第一个到达拉然带给我一只黑鳍鲨的参赛者便是本届比赛的冠军！能够钓到小型亚口鱼的地方能都钓到黑鳍鲨。', `MaleText_loc5`='卡魯耶克釣魚大賽開始啦!首先將黑尖鯊魚帶到達拉然交給我的參賽者將會贏得這場比賽!只要能釣到小巧的長印魚的地方就可以釣到黑尖鯊魚。', `MaleText_loc7`='¡Ha empezado la competición de pesca Kalu''ak! ¡La primera persona que me traiga un tiburón macuira a Dalaran será el ganador! Los tiburones macuira se encuentran en cualquier lugar en el que haya rémoras pigmeas.' WHERE `ID`=38218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 칼루아크 낚시 대회에서 우승했습니다!', `MaleText_loc4`='$n在卡鲁亚克钓鱼大赛中取得了胜利！', `MaleText_loc5`='$n贏得了卡魯耶克釣魚大賽!', `MaleText_loc7`='¡$n ha ganado la competición de pesca Kalu''ak!' WHERE `ID`=38219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회 종료까지 10분밖에 남지 않았습니다!', `MaleText_loc4`='离卡鲁亚克钓鱼大赛结束仅剩10分钟！', `MaleText_loc5`='卡魯耶克釣魚大賽的結束時間只剩下10分鐘!', `MaleText_loc7`='¡Solo quedan 10 minutos para que termine la competición de pesca Kalu''ak!' WHERE `ID`=38220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 5분 후에 종료됩니다!', `MaleText_loc4`='卡鲁亚克钓鱼大赛将在5分钟后结束！', `MaleText_loc5`='卡魯耶克釣魚大賽即將在5分鐘後結束!', `MaleText_loc7`='¡La competición de pesca Kalu''ak termina en 5 minutos!' WHERE `ID`=38221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼루아크 낚시 대회가 종료되었습니다! 상어를 낚으셨다면 1시간 안에 제게 가져오시기 바랍니다.', `MaleText_loc4`='卡鲁亚克钓鱼大赛已经结束了！如果你捉到了一条黑鳍鲨，请在规定时间内把它送到我这。', `MaleText_loc5`='卡魯耶克釣魚大賽已經結束了!如果你釣到了鯊魚，請在一小時內帶來給我。', `MaleText_loc7`='¡Ha terminado la competición de pesca Kalu''ak! Si has atrapado un tiburón, tráemelo en menos de una hora.' WHERE `ID`=38222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한 곳으로 훨훨 날아가시오!', `MaleText_loc4`='快走吧！到安全的地方去！', `MaleText_loc5`='舞動吧!為安全乾杯!', `MaleText_loc7`='¡Saltad! ¡A la salvación!' WHERE `ID`=38223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 한때는 나도 성기사였다. 내가 지은 죄가 너무나 크기에 이제 성스러운 빛은 나를 멀리한다.$B$B내가 할 수 있는 한 최대의 노력을 다해 동지들을 돕겠지만, 다시 어둠의 힘을 쓰는 일은 결코 없을 것이다.', `MaleText_loc4`='我曾经是一名圣骑士，$n。由于我罪孽深重，现在圣光已离我远去。$B$B我会尽我所能帮助我的盟友，我绝不会再触碰黑暗的力量。', `MaleText_loc5`='我曾是一名聖騎士，$n。現在聖光已不再眷顧我，因為我犯下的罪行實在太深了。$B$B我會盡其所能的協助盟友，而我永遠也不會再重執黑暗的力量。', `MaleText_loc7`='Una vez fui un paladín, $n. Ahora la Luz me rechaza, pues mis pecados son muchos.$b$bAyudaré a mis aliados lo mejor que pueda, pero nunca más utilizaré los poderes de la oscuridad.' WHERE `ID`=38224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 자초한 상처지. 리치 왕의 손아귀에 잡힌 내가 끔찍스러운 일들을 저질렀던 세상을 감히 쳐다볼 수 없었다.$B$B구원을 받고자 하는 첫걸음인 셈이다. 만약 내 죄가 용서받을 수 없을 만큼 크다면, 남은 일생을 그들에게 속죄하며 살아가려고 한다.', `MaleText_loc4`='朋友，这是自己造成的创伤。我实在无法面对这样一个在巫妖王的蹂躏下充满恐慌的世界。$B$B这是我救赎之旅的第一站，如果我的罪孽无法得到原谅，我会设法用我的余生加以偿还。', `MaleText_loc5`='這都是由我一手造成的，朋友。我無法忍受在巫妖王掌控之下的我，對這世界所犯下的罪行。$B$B這將是我贖罪的第一步，如果我的罪行無法獲得饒恕，那麼我將會終其一生致力彌補我所犯下的過錯。', `MaleText_loc7`='Una herida que me infligí, $gamigo:amiga;. No podía soportar ver un mundo en el que yo había cometido tantos horrores bajo la presión del Rey Exánime.$b$bFue mi primer paso hacia la redención, y si mis pecados son imperdonables, entonces intentaré compensarlos durante el resto de mi vida.' WHERE `ID`=38225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르무스 님, 눈은 어떻게 되신 겁니까?', `MaleText_loc4`='欧姆斯，你的眼睛怎么了？', `MaleText_loc5`='歐姆斯，你的眼睛怎麼了?', `MaleText_loc7`='Ormus, ¿qué les ha pasado a tus ojos?', `FemaleText_loc1`='오르무스 님, 눈은 어떻게 되신 건가요?', `FemaleText_loc4`='欧姆斯，你的眼睛怎么了？', `FemaleText_loc5`='歐姆斯，你的眼睛怎麼了?', `FemaleText_loc7`='Ormus, ¿qué les ha pasado a tus ojos?' WHERE `ID`=38226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반지를 잃어버린 듯합니다.', `MaleText_loc4`='我发现我弄丢了我的戒指。', `MaleText_loc5`='我的戒指弄丟了。', `MaleText_loc7`='Parece que he perdido mi anillo.', `FemaleText_loc1`='반지를 잃어버린 듯해요.', `FemaleText_loc4`='我发现我弄丢了我的戒指。', `FemaleText_loc5`='我的戒指弄丟了。', `FemaleText_loc7`='Parece que he perdido mi anillo.' WHERE `ID`=38227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잃어버렸단 말이냐?$B$B$n, 정말로 실망스럽군.$B$B그 반지는 여느 반지와는 다르다. 쓰러진 우리 영웅들의 갑옷 파편과 적의 검에서 나온 금속을 정화하여 만든 반지란 말이다.$B$B같은 일이 다시는 일어나지 않도록 해라.', `MaleText_loc4`='丢了？$B$B我真是失望极了，$n。$B$B那只戒指曾是用我们已逝英雄的护甲碎片，加上净化后的敌人刀刃打造的。$B$B这样的事情不要再次发生。', `MaleText_loc5`='遺失了?$B$B我對你非常的失望，$n。$B$B那枚戒指可是獨一無二，用我方陣亡勇士身上所遺留下來的護甲，以及從敵方奪回的劍刃加以淨化過後的金屬打造而成的。$B$B別讓這種事情再度發生了。', `MaleText_loc7`='¿Perdido?$b$bEstoy decepcionado, $n.$b$bEse anillo era único, labrado de los restos de las armaduras de nuestros héroes caídos y el metal purificado de las espadas de nuestros enemigos.$b$bNo dejes que vuelva a pasar.' WHERE `ID`=38228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 잃어버리는 일은 없을 겁니다.', `MaleText_loc4`='不会的。', `MaleText_loc5`='不會的。', `MaleText_loc7`='No lo haré.', `FemaleText_loc1`='다시 잃어버리는 일은 없을 거예요.', `FemaleText_loc4`='不会的。', `FemaleText_loc5`='不會的。', `FemaleText_loc7`='No lo haré.' WHERE `ID`=38229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가십시오. 나가가 북쪽에 있는 섬을 장악하고 있습니다. 그곳에 있으면 위험합니다.', `MaleText_loc4`='回头吧，朋友，纳迦正控制着北边的那座岛。那里对你不安全。', `MaleText_loc5`='回去，老兄。納迦占領了北方的島，你在這並不安全。', `MaleText_loc7`='Date la vuelta, colega. Los nagas controlan la i''la del no''te. No e''tarás a salvo allí.', `FemaleText_loc1`='돌아가십시오. 나가가 북쪽에 있는 섬을 장악하고 있습니다. 그곳에 있으면 위험합니다.', `FemaleText_loc4`='回头吧，朋友，纳迦正控制着北边的那座岛。那里对你不安全。', `FemaleText_loc5`='回去，老兄。納迦占領了北方的島，你在這並不安全。', `FemaleText_loc7`='Date la vuelta, colega. Los nagas controlan la i''la del no''te. No e''tarás a salvo allí.' WHERE `ID`=38230;
