UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위에서는 대격변의 파괴 현장을 모두 지켜볼 수 있다네. 우리 세상이 얼마나 깨지기 쉬운 존재인지 몸서리쳐질 정도라네.', `MaleText_loc4`='从这里，你能看到大灾变所造成的全部破坏。看到我们的世界竟然如此脆弱，这真是令人胆寒。', `MaleText_loc5`='從這上面你可以看到大災變的全景。看到我們的世界如此脆弱真是讓人不寒而慄。', `MaleText_loc7`='Desde aquí puedes ver el alcance completo de la destrucción del Cataclismo. Es espantoso ver lo frágil que es nuestro mundo en realidad.' WHERE `ID`=38232;
