UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요란하게 삑삑거리며 정신없이 번쩍입니다. 이곳을 파보십시오!', `MaleText_loc4`='这东西开始“哔哔”地狂叫，还在不停地闪耀着。就在这里挖！', `MaleText_loc5`='它正在瘋狂地閃爍和嗶嗶叫。挖這!', `MaleText_loc7`='Pita y destella como loco. ¡Excava aquí!', `FemaleText_loc1`='요란하게 삑삑거리며 정신없이 번쩍입니다. 이곳을 파보십시오!', `FemaleText_loc4`='这东西开始“哔哔”叫了，还在不停地发光。就在这里挖！', `FemaleText_loc5`='它正在瘋狂地閃爍和嗶嗶叫。挖這!', `FemaleText_loc7`='Pita y destella como loco. ¡Excava aquí!' WHERE `ID`=38240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환하게 빛을 냅니다. 거의 다 왔습니다!', `MaleText_loc4`='现在它发出了亮光。你已经很靠近了！', `MaleText_loc5`='它越來越亮了，你離它非常的近!', `MaleText_loc7`='Ahora resplandece con fuerza. ¡Estás muy cerca!', `FemaleText_loc1`='환하게 빛을 냅니다. 거의 다 왔습니다!', `FemaleText_loc4`='现在它发出了亮光。你已经很靠近了！', `FemaleText_loc5`='它越來越亮了，你離它非常的近!', `FemaleText_loc7`='Ahora resplandece con fuerza. ¡Estás muy cerca!' WHERE `ID`=38241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화석에서 겨우 몇 걸음 떨어져 있다는 듯, 요란하게 삑삑거립니다.', `MaleText_loc4`='它发出了响亮的“哔哔”声，你距离目标应该只有几步之遥了。', `MaleText_loc5`='它正大聲地嗶嗶叫，代表你離它只有幾步了。', `MaleText_loc7`='Está pitando con fuerza, lo que sugiere que solo estás a unos pasos.', `FemaleText_loc1`='화석에서 겨우 몇 걸음 떨어져 있다는 듯, 요란하게 삑삑거립니다.', `FemaleText_loc4`='它发出了响亮的“哔哔”声，你距离目标应该只有几步之遥了。', `FemaleText_loc5`='它正大聲地嗶嗶叫，代表你離它只有幾步了。', `FemaleText_loc7`='Está pitando con fuerza, lo que sugiere que solo estás a unos pasos.' WHERE `ID`=38242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1초에 한 번 정도 규칙적으로 삑삑거립니다.', `MaleText_loc4`='它正在发出规律的“哔哔”声，大约每秒钟一次。', `MaleText_loc5`='它正規律地在跳動，大約一秒跳一次。', `MaleText_loc7`='Está pitando regularmente, más o menos una vez cada segundo.', `FemaleText_loc1`='1초에 한 번 정도 규칙적으로 삑삑거립니다.', `FemaleText_loc4`='它正在发出规律的“哔哔”声，大约每秒钟一次。', `FemaleText_loc5`='它正規律地在跳動，大約一秒跳一次。', `FemaleText_loc7`='Está pitando regularmente, más o menos una vez cada segundo.' WHERE `ID`=38243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2초에 한 번 정도 규칙적으로 삑삑거립니다.', `MaleText_loc4`='它正在发出规律的“哔哔”声，大约每两秒钟一次。', `MaleText_loc5`='它正規率地發出叫聲，大概每兩秒叫一次。', `MaleText_loc7`='Está pitando regularmente, más o menos una vez cada dos segundos.', `FemaleText_loc1`='2초에 한 번 정도 규칙적으로 삑삑거립니다.', `FemaleText_loc4`='它正在发出规律的“哔哔”声，大约每两秒钟一次。', `FemaleText_loc5`='它正規率地發出叫聲，大概每兩秒叫一次。', `FemaleText_loc7`='Está pitando regularmente, más o menos una vez cada dos segundos.' WHERE `ID`=38244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5초에 한 번 정도 조용히 삑삑거립니다.', `MaleText_loc4`='它每5秒钟发出一次低微的“哔哔”声。', `MaleText_loc5`='它正發出小的叫聲，大約每五秒叫一次。', `MaleText_loc7`='Está pitando bajo, más o menos cada cinco segundos.', `FemaleText_loc1`='5초에 한 번 정도 조용히 삑삑거립니다.', `FemaleText_loc4`='它每5秒钟发出一次低微的“哔哔”声。', `FemaleText_loc5`='它正發出小的叫聲，大約每五秒叫一次。', `FemaleText_loc7`='Está pitando bajo, más o menos cada cinco segundos.' WHERE `ID`=38245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희미하게 삑삑거립니다. 아직 꽤 떨어져 있는 듯합니다.', `MaleText_loc4`='它发出的“哔哔”声很微弱。你距离目标还很远。', `MaleText_loc5`='它發出微小的叫聲，你離目標還蠻遠的。', `MaleText_loc7`='Está pitando muy débilmente. Todavía estás bastante lejos.', `FemaleText_loc1`='희미하게 삑삑거립니다. 아직 꽤 떨어져 있는 듯합니다.', `FemaleText_loc4`='它发出的“哔哔”声很微弱。你距离目标还很远。', `FemaleText_loc5`='它發出微小的叫聲，你離目標還蠻遠的。', `FemaleText_loc7`='Está pitando muy débilmente. Todavía estás bastante lejos.' WHERE `ID`=38246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삑삑거리는 소리가 거의 안 들립니다. 화석이 아주 아주 멀리 떨어져 있는 것 같습니다.', `MaleText_loc4`='你只能听到极为微弱的“哔哔”声。化石距离你一定还非常非常远。', `MaleText_loc5`='你聽到它發出極微小的叫聲，化石離你還非常，非常的遠。', `MaleText_loc7`='Lo escuchas pitar muy débilmente. El fósil debe de estar muy, muy lejos.', `FemaleText_loc1`='삑삑거리는 소리가 거의 안 들립니다. 화석이 아주 아주 멀리 떨어져 있는 것 같습니다.', `FemaleText_loc4`='你只能听到极为微弱的“哔哔”声。化石距离你一定还非常非常远。', `FemaleText_loc5`='你聽到它發出極微小的叫聲，化石離你還非常，非常的遠。', `FemaleText_loc7`='Lo escuchas pitar muy débilmente. El fósil debe de estar muy, muy lejos.' WHERE `ID`=38247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽에서 역풍이 불어오고 있소, $c.', `MaleText_loc4`='$c，东方吹来了一阵污秽的风。', `MaleText_loc5`='一股令人不舒服的風從東邊吹來，$c。', `MaleText_loc7`='Un viento nauseabundo sopla desde el Este, $c.' WHERE `ID`=38248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교수 퓨트리사이드가 당신의 돌연변이를 제거했습니다!', `MaleText_loc4`='普崔塞德教授驱散了你身上的变异效果！', `MaleText_loc5`='普崔希德教授移除了你的突變狀態!', `MaleText_loc7`='¡El Profesor Putricidio ha eliminado tu mutación!' WHERE `ID`=38249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우거진 땅의 회복을 도울 몇 가지 방법을 생각해 두었소, $c.$B$B하지만 나랄렉스 님께선 너무도 화가 나신 나머지 새롭게 시도할 의향이 없으시더군.', `MaleText_loc4`='对于治疗这种蔓生，我有一点主意，$c。$B$B不幸的是，纳拉雷克斯已经完全陷入了混乱，拒绝进行任何尝试。', `MaleText_loc5`='我有幾個主意可以治療這個蔓延現象，$c。$B$B可惜的是，納拉雷克斯已經絕望，不願意再做任何的嘗試。', `MaleText_loc7`='Tengo ciertas ideas sobre cómo curar la hojarasca, $c.$b$bPor desgracia, Naralex está tan frustrado que se niega a asumir más riesgos.' WHERE `ID`=38250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썩은박치기 나약한 늑대인간 박살 낸다!!', `MaleText_loc4`='腐血打烂小狼人！', `MaleText_loc5`='血腐殺光可悲的狼人!', `MaleText_loc7`='¡Gorerot aplastar huargencito!' WHERE `ID`=38251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 일이나 신경 쓰라고 말로 하면 못 알아듣는군!', `MaleText_loc4`='这会让你明白别管闲事的道理！', `MaleText_loc5`='這個教訓告訴你別多管閒事!', `MaleText_loc7`='¡Esto te enseñará a meterte en tus asuntos!' WHERE `ID`=38253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥시밀리언 님, 또 다른 모험을 떠날 준비가 되었습니다.', `MaleText_loc4`='麦斯米兰，我已经准备好进行更多的冒险了。', `MaleText_loc5`='瑪克西米利安，我準備好進行更多的探險了。', `MaleText_loc7`='Maximillian, estoy preparado para más aventuras.', `FemaleText_loc1`='맥시밀리언 님, 또 다른 모험을 떠날 준비가 되었습니다.', `FemaleText_loc4`='麦斯米兰，我已经准备好进行更多的冒险了。', `FemaleText_loc5`='瑪克西米利安，我準備好進行更多的探險了。', `FemaleText_loc7`='Maximillian, estoy preparada para más aventuras.' WHERE `ID`=38254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 조상은 송사리였을 게야.', `MaleText_loc4`='你这条死笨鱼。', `MaleText_loc5`='我都用你老媽當餌，笨魚。', `MaleText_loc7`='Tu mamá era carnada.' WHERE `ID`=38255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 뱀물고기야!', `MaleText_loc4`='死吧，蛇脑袋鱼。', `MaleText_loc5`='死吧蛇魚!', `MaleText_loc7`='¡Muere, pez!' WHERE `ID`=38256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하다가 널 낚으면 도로 던져 버릴 거야. 미끼가 아깝지.', `MaleText_loc4`='如果我钓到你，也只能扔回水里，真是浪费好鱼饵。', `MaleText_loc5`='要是我把你釣起來，又把你丟回去，那就浪費不少好吃的魚肉。', `MaleText_loc7`='Si te pescara, te devolvería al agua. Qué desperdicio de pescado.' WHERE `ID`=38257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 삼지창이나 닦아라.', `MaleText_loc4`='去舔你的三头叉吧。', `MaleText_loc5`='去舔三叉戟啦你。', `MaleText_loc7`='Chupa un tridente.' WHERE `ID`=38258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 잘못 걸린 거다, 물고기머리야.', `MaleText_loc4`='你惹了不该惹的巨魔，鱼脑袋。', `MaleText_loc5`='你惹了不該惹的食人妖了，臭魚頭。', `MaleText_loc7`='Te metiste con los trols equivocados.' WHERE `ID`=38259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 맛을 봐라!', `MaleText_loc4`='你是暗矛的猎物啦。', `MaleText_loc5`='嘗嘗暗矛的滋味吧。', `MaleText_loc7`='Sentirás la lanza negra.' WHERE `ID`=38260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 넌 나가치고도 못생겼다.', `MaleText_loc4`='哇哦，你还真是个丑纳迦。', `MaleText_loc5`='哇賽。你在納迦裡也算醜的吧。', `MaleText_loc7`='Uau. Feo hasta para ser naga.' WHERE `ID`=38261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우웩, 여기 생선 썩는 냄새가 나는데요.', `MaleText_loc4`='喂，兄弟，这里到处都是烂鱼的臭味儿。', `MaleText_loc5`='噢老兄，這裡有鹹魚味。', `MaleText_loc7`='Hombre, apesta a pescado podrido.' WHERE `ID`=38262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 운고로의 사악한 우두머리를 물리칠 힘을 저희에게 주소서.', `MaleText_loc4`='圣光啊，请赐予我们力量，帮助我们击败安戈洛的邪恶龙女王。', `MaleText_loc5`='聖光，賜予我們足以擊敗安戈洛邪惡育母的力量。', `MaleText_loc7`='Luz, danos la fuerza necesaria para derrotar a la vil madre de linaje de Un''Goro.' WHERE `ID`=38263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 운고로의 타락한 용과 싸울 용기를 저희에게 주소서.', `MaleText_loc4`='圣光啊，请赐予我们勇气，帮助我们与安戈洛的堕落群龙作战。', `MaleText_loc5`='聖光，賜予我們前往安戈洛與那些腐化之龍戰鬥的勇氣吧!', `MaleText_loc7`='Luz, danos el valor necesario para presentar batalla a los corruptos dragones de Un''Goro.' WHERE `ID`=38264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 운고로의 용을 파멸로 이끌 능력을 저희에게 주소서.', `MaleText_loc4`='圣光啊，请赐予我们能力，让我们消灭安戈洛的恶龙。', `MaleText_loc5`='聖光，賜予我們可以消滅安戈洛龍族的力量。', `MaleText_loc7`='Luz, danos la habilidad para acabar con los dragones de Un''Goro.' WHERE `ID`=38265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 저의 돌로리아, 아름다운 그녀의 걸음걸음마다 야생화가 꽃 피게 해주소서.', `MaleText_loc4`='我还请求您，在我美丽的多罗莉亚散步时，让鲜花在她的步履间开放。', `MaleText_loc5`='我也要求你把野生的花草灑在我美麗的朵莉亞腳下，在她可能會走到的地方。', `MaleText_loc7`='También te pido que eches flores silvestres a los pies de mi hermosa Doloria, allí por donde camine.' WHERE `ID`=38266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 티 없이 깨끗한 돌로리아의 얼굴에 눈부신 빛을 비춰 주소서.', `MaleText_loc4`='我还请求您，将您的光辉洒在多罗莉亚女士完美无暇的脸蛋上。', `MaleText_loc5`='我也要求你把那燦爛的燈光打在我的朵莉亞女士那無瑕的臉龐上。', `MaleText_loc7`='También te pido que hagas brillar tu gloriosa luz en el rostro inmaculado de mi Lady Doloria.' WHERE `ID`=38267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌로리아가 잠든 동안, 그녀의 귓가에서 들새가 따사로운 초원의 노래를 부르게 해 주소서.', `MaleText_loc4`='我祈求您，当多罗莉亚入睡时召唤来鸟雀，在她的耳边唱起优美的旋律。', `MaleText_loc5`='我要求你召喚小鳥在我的朵莉亞睡覺時在她耳邊唱著輕快的鄉野音樂。', `MaleText_loc7`='Te ruego que convoques pájaros que canten bellas canciones al oído de mi Doloria, mientras duerme.' WHERE `ID`=38268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 부디 제 종자를 용서하시고 당신이 내리는 고통을 거두어 주십시오.', `MaleText_loc4`='最后，衷心地请您原谅我的侍从，不要再对他施以惩罚了。', `MaleText_loc5`='最後，請由衷地原諒我的侍從，因為我看見你正在打他。', `MaleText_loc7`='Por último, busca en tu corazón el perdón para mi escudero, porque veo que le estás golpeando.' WHERE `ID`=38269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 간청하오니, 제 종자에게서 주먹과 발길질을 거두어 주십시오.', `MaleText_loc4`='最后，我恳求你不要再捶打踩踏我的侍从。', `MaleText_loc5`='最後，我請求你停止對我的侍從拳打腳踢。', `MaleText_loc7`='Por último, te suplico que dejes de zarandear a mi escudero con puñetazos y patadas.' WHERE `ID`=38270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 제 착한 종자에게 격하게 분노를 표출하는 것을 그만둬 주시길 간곡히 바라나이다.', `MaleText_loc4`='最后，我谦恭地祈求您不要再将恨意发泄在我的好侍从身上了。', `MaleText_loc5`='最後，我謙卑地請求你收回對我可愛侍從的敵意。', `MaleText_loc7`='Por último, te ruego humildemente que ceses de descargar tu hostilidad sobre mi buen escudero.' WHERE `ID`=38271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자여! 빛의 은혜를 입은 이 정령에게서 축복을 구할 터이니 내 옆에 있어라.', `MaleText_loc4`='侍从！请在我祈求圣光之灵的祝福时站在我的身边。', `MaleText_loc5`='侍從!站在我旁邊，當我向這受到聖光祝福的靈魂要求祝福時。', `MaleText_loc7`='¡Escudero! Permanece a mi lado mientras ruego por la bendición de este espíritu ungido por la Luz.' WHERE `ID`=38272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 축복을 받겠나이다.', `MaleText_loc4`='我接受您的祝福。', `MaleText_loc5`='我接受你的祝福。', `MaleText_loc7`='Acepto tu bendición.' WHERE `ID`=38273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이네, $n. 살아 있어!', `MaleText_loc4`='它还活着，$n。它还活着！', `MaleText_loc5`='它活過來了，$n。它活過來了!', `MaleText_loc7`='Está vivo, $n. ¡Está vivo!' WHERE `ID`=38274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가보거라, 우리 귀염둥이 천사! 아, 자식을 둥지에서 떠나보내는 부모의 마음처럼 슬픈 게 또 어디 있겠나, 안 그래?', `MaleText_loc4`='前进，我美丽的天使！啊，当孩子离开窝巢的时候总是让人感到伤心，不是吗？', `MaleText_loc5`='去吧，我美麗的天使!啊，孩子翅膀長硬飛走了是多麼地令人難過啊!', `MaleText_loc7`='¡Ve, mi bello ángel! Ah, es tan triste cuando los hijos abandonan el nido, ¿verdad?' WHERE `ID`=38275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 그렇게 쳐다봐? 천재 처음 보나?', `MaleText_loc4`='你在盯着看什么？没见过天才吗？', `MaleText_loc5`='你在看什麼?沒看過天才嗎?', `MaleText_loc7`='¿Qué miras? ¿Nunca habías visto a un genio antes?' WHERE `ID`=38276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자야! 비록 네가 아직 훈련 중이긴 하나, 빛의 정령을 죽여선 안 되느니라!', `MaleText_loc4`='侍从！我明白你刚刚接受训练不久，但我难道没有告诉过你，不能杀死圣光之灵吗？', `MaleText_loc5`='侍從!我瞭解你才剛接受完新生訓練，但你一定要我跟你說你才知道不要殺那些聖光之靈嗎?', `MaleText_loc7`='¡Escudero! Entiendo que seas novela en la profesión, pero ¿acaso debo decirte que no mates a los espíritus de la Luz?' WHERE `ID`=38277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신이여, 감사합니다!', `MaleText_loc4`='感谢大地母亲！', `MaleText_loc5`='感謝大地之母!', `MaleText_loc7`='¡Gracias madre tierra!', `FemaleText_loc1`='대지모신이여, 감사합니다!', `FemaleText_loc4`='感谢大地母亲！', `FemaleText_loc5`='感謝大地之母!', `FemaleText_loc7`='¡Gracias madre tierra!' WHERE `ID`=38278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다시 움직일 수 있습니다!', `MaleText_loc4`='我又能动了！', `MaleText_loc5`='我可以再次行走了!', `MaleText_loc7`='¡Puedo moverme de nuevo!', `FemaleText_loc1`='이제 다시 움직일 수 있어요!', `FemaleText_loc4`='我又能动了！', `FemaleText_loc5`='我可以再次行走了!', `FemaleText_loc7`='¡Puedo moverme de nuevo!' WHERE `ID`=38279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시멧돼지 놈들은 대가를 치를 것입니다!', `MaleText_loc4`='我要让野猪人付出代价！', `MaleText_loc5`='野豬人會付出代價!', `MaleText_loc7`='¡El jabaespín pagará!', `FemaleText_loc1`='가시멧돼지 놈들은 대가를 치를 것입니다!', `FemaleText_loc4`='我要让野猪人付出代价！', `FemaleText_loc5`='野豬人會付出代價!', `FemaleText_loc7`='¡El jabaespín pagará!' WHERE `ID`=38280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투의 해협으로 돌아가지 않으면 기계상어 쾌속-X가 알 수 없는 이유로 산산조각 납니다.', `MaleText_loc4`='返回险峻海峡，否则X型蒸汽机械鲨鱼就会神秘地解体。', `MaleText_loc5`='回到恐怖海峽，不然機械鯊魚噴射X就會神秘的分解。', `MaleText_loc7`='Regresa al Estrecho Temible o, misteriosamente, el Mecatiburón Vapor-X se romperá en pedazos.' WHERE `ID`=38282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도 이제 그대와 불사조를 떠나야겠소. 빛이 함께하길!', `MaleText_loc4`='恐怕我现在必须离开你和你的凤凰了。愿圣光照耀你。', `MaleText_loc5`='我想我現在恐怕必須離開你和你的前鳳凰。願聖光與你們同在!', `MaleText_loc7`='Me temo que debo despedirme de vos y de tu antiguo fénix. ¡Que la Luz sea con vos!' WHERE `ID`=38284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 내가 이런 ''폭죽류''의 값을 부르는 걸 좋아하지.', `MaleText_loc4`='没错，我会把那些“烟火”列一张表出来。', `MaleText_loc5`='沒錯，我打算清點一下這些『煙火』。', `MaleText_loc7`='Eso es, me gustaría que hicieras una lista de esos ''fuegos artificiales''.' WHERE `ID`=38285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽 바다에서 돌아오면 저걸로 짭짤하게 벌 거야.', `MaleText_loc4`='从南海回来后那些东西就能卖大价钱了。', `MaleText_loc5`='等我回到南海的時候，這些東西可以讓我獲得相當豐厚的利潤。', `MaleText_loc7`='Esos me darán un buen beneficio cuando vuelva de los Mares del Sur.' WHERE `ID`=38286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너... 내가 널 못 보리라 생각하지 마. 이제 날 내버려 두라고!', `MaleText_loc4`='你…别以为我看不到你。离我远点！', `MaleText_loc5`='你...別以為我沒看到你。離我遠一點!', `MaleText_loc7`='Tú... No creas que no te veo. ¡Déjame en paz!' WHERE `ID`=38287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이발도 면도도 말끔하게 됐군, 고마워.', `MaleText_loc4`='伙计，感谢你提供这么棒的理发、修面服务。', `MaleText_loc5`='多謝你的剪髮和刮鬍啦，老哥。', `MaleText_loc7`='Gracias por el corte y el afeitado, colega.' WHERE `ID`=38288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 가버릴 거니까 좀 더 줄게.', `MaleText_loc4`='因为我就要离开了，所以准备了这么一点额外的东西。', `MaleText_loc5`='自從我注意到以後，這裡就多了一點什麼。', `MaleText_loc7`='Aquí hay algo de más, para cuando no esté.' WHERE `ID`=38289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 생각해봤는데, 그냥 가방 채로 가져. 나는, 그러니까 가야 하거든.', `MaleText_loc4`='我又想了想，整个袋子都拿走吧。我必须，嗯，走了。', `MaleText_loc5`='考慮一下之後，我想還是整袋留下。我得要，噢，要走了。', `MaleText_loc7`='Pensándolo bien, quédate toda la bolsa. Tengo que, uh, irme.' WHERE `ID`=38290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 이렇게 쉽게 나를 궁지에 몰아넣을 수 있다고 생각했어?', `MaleText_loc4`='你真以为我这么容易就会被你困住？', `MaleText_loc5`='你以為你真能這麼容易逮到我嗎?', `MaleText_loc7`='¿De verdad pensabas que me acorralarías tan fácilmente?' WHERE `ID`=38291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비탄에 빠져 약해져선 안 되네. 우리는 침략자에게 굳건히 맞설 것이야.', `MaleText_loc4`='绝不能让悲痛的心情削弱我们的力量。我们将并肩作战，以强大的力量击退入侵者。', `MaleText_loc5`='我們不能因悲傷而變得軟弱。我們的人民將昂首對抗入侵者。', `MaleText_loc7`='No debemos permitir que nuestro desconsuelo nos debilite. Nuestra gente resistirá frente a los invasores.' WHERE `ID`=38292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 기다리던 지원이 왔군요! 스내글볼트가 요청한 서류는 준비해놨어요. 이제 남은 일은 서류를 전달하는 분 몫이지요.', `MaleText_loc4`='终于盼到我要的援助了！我准备了滑栓需要的各项文书。现在只剩下找人执行了。', `MaleText_loc5`='終於，我一直在等待的後援到了!我準備了凸栓要的文件。現在只等某人來把它送出去。', `MaleText_loc7`='¡Por fin, el apoyo que esperaba! He preparado el papeleo que pidió Tuerceganzúas. Solo falta alguien que lo entregue.' WHERE `ID`=38293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진, 넌 약해빠졌어. 바로 네 아비처럼 말이야. 오늘, 내가 오래전에 시작한 일을 끝내야겠다. 검은창 부족을 흔적도 없이 쓸어 버리겠어!', `FemaleText_loc4`='你真弱，沃金，跟你的父亲一样弱。今天，我将结束这场久远的战争——暗矛巨魔将被彻底扫除干净！', `FemaleText_loc5`='你太弱了，沃金，跟你父親一樣弱..今天我會把許久之前就開始的工作完成 - 把暗矛部族的存在整個抹去!', `FemaleText_loc7`='Eres débil, Vol''jin, igual que tu padre. Hoy terminaré lo que empecé hace tanto: ¡los Lanza Negra dejarán de existir!' WHERE `ID`=38294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주님, 저희를 도와주러 오시다니 감사합니다. 도움이 되는 일이라면 무슨 일이든 하겠습니다.', `MaleText_loc4`='我的女王，感谢您接受我们的援助。我向您保证，我们会尽一切所能提供帮助。', `MaleText_loc5`='我的女士，感謝你來幫助我們。我向你保證我們會盡一切所能提供協助。', `MaleText_loc7`='Mi señora, gracias por venir en nuestra ayuda. Te aseguro que haremos todo lo posible por ayudar.' WHERE `ID`=38295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아, 그거 냄새 좋은데... 이봐! 그놈의 거 나한테 그만 뿌리라고!', `MaleText_loc4`='你知道的，那个闻起来十分的…嘿！别拿那个喷我！', `MaleText_loc5`='你知道，那個的確聞起來不錯...嘿!別再拿那個東西對著我噴!', `MaleText_loc7`='Sabes, si que huele bastante... ¡eh! ¡Deja de echarme eso!' WHERE `ID`=38296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이로군!', `MaleText_loc4`='一头龙！', `MaleText_loc5`='一隻龍!', `MaleText_loc7`='¡UN DRAGÓN!' WHERE `ID`=38297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이다!', `MaleText_loc4`='龙！', `MaleText_loc5`='龍!', `MaleText_loc7`='¡DRAGÓN!' WHERE `ID`=38298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 내 너를 처단하리라!', `MaleText_loc4`='龙，我要消灭你！', `MaleText_loc5`='惡龍啊，我將消滅你!', `MaleText_loc7`='¡DRAGÓN! ¡TE ATRAVESARÉ!' WHERE `ID`=38299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌로리아를 위하여!', `MaleText_loc4`='为了多罗莉亚！', `MaleText_loc5`='為了朵莉亞!', `MaleText_loc7`='¡POR DOLORIA!' WHERE `ID`=38300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 공격대 전체가 도전해보고 싶습니다.', `MaleText_loc4`='我要试试我们的团队。', `MaleText_loc5`='我想要測試我們整個團隊。', `MaleText_loc7`='Quiero probar a toda nuestra banda.', `FemaleText_loc1`='우리 공격대 전체가 도전해보고 싶어요.', `FemaleText_loc4`='我要试试我们的团队。', `FemaleText_loc5`='我想要測試我們整個團隊。', `FemaleText_loc7`='Quiero probar a toda nuestra banda.' WHERE `ID`=38301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사냥의 길에 들어선 젊은 투사들을 시험하는 것이 저의 역할입니다.$B$B지금도 제 역할은 변하지 않았습니다. 오늘의 사냥감은 가시멧돼지라는 점만 다를 뿐이죠.', `FemaleText_loc4`='我的责任是测试我们年轻的学徒对于狩猎技艺的掌握程度。$B$B这就是我今天要做的。而那些野猪人就是我们的猎物。', `FemaleText_loc5`='我的職責是測驗我們年輕的新手們對於打獵的瞭解。$B$B這到現在並沒有改變，野豬人便是我們的獵物。', `FemaleText_loc7`='Mi deber es examinar a los jóvenes iniciados en el camino de la caza.$b$bEso no ha cambiado. Hoy nuestras presas son los jabaespines.' WHERE `ID`=38302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신이시여, 오늘 저희 중 하나가 당신의 품에 듭니다. 그녀는 우나야 호크윈드, 제 어머니이자 우리 모두의 대모님입니다. 부족에서 가장 현명한 분이시지요.', `MaleText_loc4`='大地母亲，我们之中的一员将投入您的怀抱。她就是乌纳雅·鹰风，我的母亲，也是我们所有人的伟大母亲，我们部族中最具智慧的人。', `MaleText_loc5`='大地之母，我們將把自己最親愛的人交到你的手裡。她就是烏娜亞·鷹風，我的母親，也是我們所有人的主母。她是我們部族裡最為睿智的人。', `MaleText_loc7`='Madre Tierra, dejamos en tus brazos a una de nosotros. Es Unaya Viento de Halcón, mi madre y la abuela de todos nosotros. La más sabia de la tribu.' WHERE `ID`=38303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 영혼이 순식간에 당신께 닿길. 바람이 그녀를 부드럽게 감싸고, 풀잎이 그녀의 이름을 속삭이길.', `MaleText_loc4`='愿她飞翔的灵魂拥有您的迅捷，愿风温柔地吹拂她，青草悄声传诵她的名字。', `MaleText_loc5`='祝福她的靈魂能順利地飛去你那，希望她能與風共翔，也希望花草會輕聲呼喊她的名字。', `MaleText_loc7`='Que su espíritu vuele rápidamente hacia ti, que los vientos la lleven con delicadeza y la hierba susurre su nombre.' WHERE `ID`=38304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 저희를 돌보았듯 그녀를 돌봐 주십시오. 저희 또한 안식에 드는 그날까지, 그녀가 안쉬와 무샤의 영원한 빛으로 저희를 기쁘게 바라보게 해 주십시오.', `MaleText_loc4`='看护她，如同她看护我们。让她怀着喜悦之心，通过永恒的安瑟和穆莎凝视看到我们，直到我们和她在死亡中相会。', `MaleText_loc5`='請庇護她，就像她庇護我們一樣，讓她透過安希和姆莎的永恆之眼快樂地看著我們，直到我們死亡後投向她的懷抱。', `MaleText_loc7`='Cuida de ella como ella ha cuidado de nosotros. Que nos mire con alegría, a través de la mirada eterna de An''she y Mu''sha, hasta que nos unamos a ella en la muerte.' WHERE `ID`=38305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 당신께 났으니, 마땅히 당신께 돌아갈 것입니다.', `MaleText_loc4`='我们全都来自于您，也全都将回到您身边。', `MaleText_loc5`='正因我們都誕生於妳，也該回歸於妳。', `MaleText_loc7`='Pues todos nacemos de ti y a ti hemos de regresar.' WHERE `ID`=38306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 당신이 우리와 손잡는다니 기쁘군. 나가한테서 뭔가 얻어내는 일은 쉽지가 않거든!', `MaleText_loc4`='很高兴你能和我们在一起，$n。对付纳迦可不是一件容易的事！', `MaleText_loc5`='我很高興你與我們同在，$n。從納迦那奪取東西不是那麼簡單的!', `MaleText_loc7`='Me alegra que estés aquí con nosotros, $n. ¡No es fácil conseguir cosas de los nagas!' WHERE `ID`=38307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명예의 감시탑에 온 걸 환영해요, $c님! 호드의 손아귀로부터 계곡을 빼앗는 데는 성공했지만, 열려 있는 관문을 지키는 건 훨씬 더 어렵네요.', `FemaleText_loc4`='欢迎来到荣耀岗哨， $c！我们已经将这座山谷从部落手中夺了过来，但如果要保持这个咽喉要道的通畅就是另一回事了。', `FemaleText_loc5`='歡迎來到榮譽看臺，$c!我們從部落的手中將這片山谷奪了過來，但讓這隘口保持開敞的狀況卻就沒那麼簡單了。', `FemaleText_loc7`='¡Te doy la bienvenida a El Alto del Honor, $c! Hemos arrancado este valle de las garras de la Horda, pero mantener abierto este cuello de botella ha resultado ser harina de otro costal.' WHERE `ID`=38308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님! 위로 조금만 올라가시면 명예의 감시탑이 있습니다. 돌발톱과 해안 지역을 잇는 얼라이언스의 유일한 연결점이죠.$B$B경험해봐서 압니다만 가는 길이 보기보다 위험하더군요.', `MaleText_loc4`='你好，$c！荣耀岗哨就在前面。那是联盟在石爪山脉和海岸之间的唯一通道。$B$B根据我的亲身经验，那也是一条充满危险的道路。', `MaleText_loc5`='你好，$c!榮譽看臺就在你的前面，那是聯盟唯一連結了石爪山脈和海岸的營地。$B$B只是這條路隱藏了許多危險，這是我的經驗談。', `MaleText_loc7`='¡Alto, $c! Justo delante verás El Alto del Honor, el único enlace de la Alianza entre Sierra Espolón y la costa.$b$bPero el camino es traicionero. Lo sé por experiencia propia.' WHERE `ID`=38309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 나가와 거래할 수 있는지 알아보러 왔어요. 반응은 썩 좋지 않더군요.', `FemaleText_loc4`='我来到这里是为了看看能否和那些纳迦建立贸易往来。但他们的回答并不尽如人意。', `FemaleText_loc5`='我來到這想說或許可以跟納迦進行貿易上的往來，但他們的反應不太友善。', `FemaleText_loc7`='He venido para ver si podíamos abrir rutas comerciales con estos naga. No me ha gustado mucho su respuesta.' WHERE `ID`=38310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈마디가 쑤시는군. 무릎도 아프고, 얼굴도 아프고. 학교를 계속 다녔어야 하는데, 학교를.', `MaleText_loc4`='我骨头疼，膝盖疼，脸也疼。我真不应该离开学校。', `MaleText_loc5`='我的骨頭在痛，膝蓋在痛，臉在痛。我真應該待在學校裡!真應該!', `MaleText_loc7`='Me duelen los huesos. Me duelen las rodillas. Me duele la cara. No debería haber dejado la escuela.' WHERE `ID`=38311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오게, $c|1이여;여;. 우리 주술사들은 이 땅을 보살피고 상처를 치유하기 위해 화염석 거점에 모였다네.', `FemaleText_loc4`='你好，$c。我们萨满祭司聚集在火石岗哨，照看这片土地，治疗它受到的伤害。', `FemaleText_loc5`='你好，$c。我們薩滿集結在這火石崗哨來觀察這片大地和治癒它的傷口。', `FemaleText_loc7`='Saludos, $c. Los chamanes nos hemos reunido aquí, en la Punta Piedra de Fuego, para observar la tierra y sanar sus heridas.' WHERE `ID`=38312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사용자는 어서 빨리 탈출 단계를 준비해라. 탈것이 있으면 타도 좋다.', `MaleText_loc4`='来吧，用户。我们准备好了逃亡方案。如果你有坐骑，现在就使用它吧。', `MaleText_loc5`='來，使用者。我們準備執行逃脫計畫。如果你有坐騎的話，現在就使用它。', `MaleText_loc7`='Ven, usuario. Nos preparamos para el protocolo de escape. Si tienes una, usa tu montura ahora.' WHERE `ID`=38313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 독 폭발이 시작됩니다! 어서 몸을 숨기십시오!', `MaleText_loc4`='毒气炸药要爆炸了！快找掩护！', `MaleText_loc5`='劇毒爆炸快來了!快找個掩護躲在後面!', `MaleText_loc7`='¡Se acerca una Deflagración de veneno! ¡Poneos a cubierto donde podáis!' WHERE `ID`=38314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대괴수가 땅속으로 몸을 숨깁니다!', `MaleText_loc4`='巨虫正在地下挖洞！', `MaleText_loc5`='巨像遁入了地底!', `MaleText_loc7`='¡El coloso se mete bajo tierra!' WHERE `ID`=38315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 마녀가 돌아왔네. 드디어 검은창 부족의 복수가 실현되는군.$B$B준비가 되면 내게 알려주게나, $n. 또다시 마녀가 사라지도록 두진 않을 걸세.', `MaleText_loc4`='她回来了。暗矛部族的仇恨终于要在今天有个了结。$B$B准备好以后就告诉我们，$n。我们绝不会再让她逃走。', `MaleText_loc5`='她回來了。暗矛部族可以復仇雪恥的那天終於來了。$B$B$n，等你準備好了就讓我知道，我們這次絕不會再讓她溜走了。', `MaleText_loc7`='Ella ha regresa''o. Por fin llega el momento de la venganza de los Lanza Negra.$B$BAvísame cuando te''mines de prepararte, $n. No dejaremos que se eh''cape de nuevo.' WHERE `ID`=38316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님, 준비되었습니다.', `MaleText_loc4`='我准备好了，沃金。', `MaleText_loc5`='我準備好了，沃金。', `MaleText_loc7`='Estoy listo, Vol''jin.', `FemaleText_loc1`='볼진 님, 준비되었습니다.', `FemaleText_loc4`='我准备好了，沃金。', `FemaleText_loc5`='我準備好了，沃金。', `FemaleText_loc7`='Estoy lista, Vol''jin.' WHERE `ID`=38317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기로 돌아오다니, 바보 같은 것. 네가 한 번은 복수의 손길을 빠져나갔다만, 검은창 부족이 이번에도 널 봐주리라 생각지는 마라.', `MaleText_loc4`='你来到这里是个错误，女海巫。你曾经逃脱过我们的复仇。但暗矛氏族不会容忍你再次践踏我们的家园。', `MaleText_loc5`='海巫，你真的很蠢才會來這。你本來已經逃離我們的復仇，但這次暗矛部族不會再忍受你的入侵。', `MaleText_loc7`='Qué tonta fuiste en venir aquí, Bruja de Mar. Ya escapaste a nuestra venganza, pero la Tribu Lanza Negra no te volverá a permitir esta ofensa.' WHERE `ID`=38318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리마트라스라고? 아니, 한동안 그에게서 소식이 없네. 분명히 여왕님을 위해 중요한 일을 하느라 어디 갔겠지.', `MaleText_loc4`='瓦里玛萨斯？不，他已经有一阵子没来报到了。他无疑是外出完成他的女王交给他的任务去了。', `MaleText_loc5`='瓦里瑪薩斯?沒有，他好一陣子沒有關於他的報告了。毫無疑問他已經不受他女王的重用了。', `MaleText_loc7`='¿Varimathras? No, no ha presentado informes de estado desde hace tiempo. Debe estar haciendo algo importante para su reina.' WHERE `ID`=38319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리마트라스가, 그러니까... 없을 때는, 내가 브라고르 대장을 돕기로 되어 있네.', `MaleText_loc4`='瓦里玛萨斯，嗯…不在的时候，我被派来协助布拉贡大人完成任务。', `MaleText_loc5`='當瓦里瑪薩斯，呃...不在時，我被指派去協助貝拉戈隊長。', `MaleText_loc7`='Mientras Varimathras está, eh... fuera, me han asignado para ayudar al Capitán Bragor en sus tareas.' WHERE `ID`=38320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티 병력 대부분이 노스렌드에 있는 복수의 상륙지로 배치된 상황이어서, 대족장님께서는 언더시티 방어를 지원하도록 우리를 보내셨네.', `MaleText_loc4`='由于幽暗城的大部分兵力都已部署在了诺森德的复仇港，酋长派我们来支援幽暗城的防守。', `MaleText_loc5`='隨著幽暗城的大批部隊被派往北裂境的復仇臺地，大酋長就派我們來增強城市的防務。', `MaleText_loc7`='Como gran parte de las fuerzas de Entrañas se han desplegado a Campo Venganza en Rasganorte, el Jefe de Guerra nos ha enviado para reforzar las defensas de la ciudad.', `FemaleText_loc1`='언더시티 병력 대부분이 노스렌드에 있는 복수의 상륙지로 배치된 상황이어서, 대족장님께서는 언더시티 방어를 지원하도록 우리를 보내셨네.', `FemaleText_loc4`='由于幽暗城的大部分兵力都已部署在了诺森德的复仇港，酋长派我们来支援幽暗城的防守。', `FemaleText_loc5`='隨著幽暗城的大批部隊被派往北裂境的復仇臺地，大酋長就派我們來增強城市的防務。', `FemaleText_loc7`='Como gran parte de las fuerzas de Entrañas se han desplegado a Campo Venganza en Rasganorte, el Jefe de Guerra nos ha enviado para reforzar las defensas de la ciudad.' WHERE `ID`=38321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을 사람들이 잿불석 마을을 되찾아 줘서 고맙다며, 포세이큰과의 전투에 쓸만한 것들을 가져다줬답니다!', `FemaleText_loc4`='夺回烬石村让村民欢欣鼓舞。他们送了些东西来帮助我们对抗被遗忘者。', `FemaleText_loc5`='村民們很高興能奪回燼石村。他們帶一些東西來幫我們對付被遺忘者!', `FemaleText_loc7`='Los lugareños están felices de recuperar Piedra Ígnea. ¡Nos lo agradecen con una ayudita contra los Renegados!' WHERE `ID`=38322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시목도리가 이 땅 차지한다! 타우렌 불태울 거다!', `MaleText_loc4`='这片土地属于尖啸！牛头人必将毁灭！', `MaleText_loc5`='這片大地是尖叫者的!牛頭人的末日到了!', `MaleText_loc7`='¡Chillón tomar esta tierra! ¡Tauren arder!' WHERE `ID`=38323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=38324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돈을 벌고 싶으신가요?', `FemaleText_loc4`='对赚钱有兴趣吗？', `FemaleText_loc5`='你對賺錢有興趣嗎?', `FemaleText_loc7`='¿Te interesa ganar un poco de dinero?' WHERE `ID`=38325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 운고로에 온 이유는 단 한 가지, 바로 돈 때문이야. 나와 내 동료들은 늘 새로운 사업 동반자를 구하고 있어. 관심 있다면 합류하는 건 어때?', `MaleText_loc4`='我们来到安戈洛只为了一件事：利润。我的同伴我和一直在寻找生意上的合作对象。你有兴趣吗？', `MaleText_loc5`='我們來到安戈洛只有一個目的:賺錢。我的助手和我一直都歡迎生意上的夥伴，如果你有興趣的話。', `MaleText_loc7`='Vinimos a Un''Goro con un objetivo en mente: beneficios. Mis colegas y yo siempre buscamos socios, por si te interesa.' WHERE `ID`=38326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $n. 여기까지 와주다니 정말 기뻐. 상황이 점점 엉망이거든.', `MaleText_loc4`='你好， $n。很高兴见到你在这里。这里简直是一团乱了。', `MaleText_loc5`='哈囉，$n。你來到這太好了。這裡已經變的一團亂了。', `MaleText_loc7`='Hola, $n. Me alegra que estés aquí. Esto se está convirtiendo en un desastre.' WHERE `ID`=38327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있었습니까?', `MaleText_loc4`='这里发生了什么？', `MaleText_loc5`='這裡發生了什麼事?', `MaleText_loc7`='¿Qué ha ocurrido aquí?', `FemaleText_loc1`='무슨 일이 있었습니까?', `FemaleText_loc4`='这里发生了什么？', `FemaleText_loc5`='這裡發生了什麼事?', `FemaleText_loc7`='¿Qué ha ocurrido aquí?' WHERE `ID`=38328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅이 한때 우거진 숲이었다는 걸 알고 계셨습니까? 수천 년 전, 처음 세계가 분리되기 전에는 칼도레이의 보호 아래 신록의 땅으로 번창했지요. 하지만 대륙이 갈라지고 이곳 역시 칼림도어라 불리는 대륙으로 분리되면서, 자연의 계곡은 태양에 혹독하게 그을린 평원으로 변했습니다.$B$B이 사실을 처음 알았을 때는 커다란 비극이라 생각했습니다. 그리고 숲을 다시 한 번 자라게 할 방법을 찾겠다고 결심했습니다.', `MaleText_loc4`='你知道吗？贫瘠之地曾经是一片青葱茂密的森林。几千年以前，那时第一次大崩裂还没有发生。卡多雷照料着这片繁荣富饶之地。但随着大陆分崩离析，这一片被撕裂的陆地成为了现在被我们称为卡利姆多的地方，昔日的绿地成为了一片被阳光炙烤的荒芜平原。$B$B当我第一次听说这场恐怖的悲剧时，我就决定要找到办法，让森林重新生长在这片土地上。', `MaleText_loc5`='你知道貧瘠之地曾是一片茂盛的叢林嗎?幾千年前，在第一次大爆炸發生前，它是青翠和極具活力的，由卡多雷所守護著。但當這片大陸被撕裂後，它被分割成我們口中的卡林多，這片山谷變成了一個嚴酷，受到太陽炙熱的光芒所灼燒的土地。$B$B當我第一次知道這件事，便認為這是個慘烈悲劇。我決定我一定要找到一個方法來讓花草樹木再次在這裡生根。', `MaleText_loc7`='¿Sabías que, en otro tiempo, Los Baldíos fueron un suntuoso bosque? Hace miles de años, antes del primer Cataclismo, era verde y próspero, y los cuidaban los Kaldorei. Pero cuando los continentes se rasgaron y esta tierra se separó en lo que llamamos Kalimdor, este valle de naturaleza se convirtió en una árida explanada abrasada por el sol.$B$BCuando me enteré de esto, me di cuenta de que era una gran tragedia y decidí que encontraría la manera de repoblar los bosques de nuevo.' WHERE `ID`=38329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 말입니까?', `MaleText_loc4`='如何？', `MaleText_loc5`='要怎麼做?', `MaleText_loc7`='¿Cómo?', `FemaleText_loc1`='어떻게 말입니까?', `FemaleText_loc4`='如何？', `FemaleText_loc5`='要怎麼做?', `FemaleText_loc7`='¿Cómo?' WHERE `ID`=38330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 연구하던 중, 대지 아래 깊숙이 뻗어 있는 동굴을 발견했습니다. 바싹 마른 대초원 바로 아래에는 지하의 강이 멀리까지 이어져 물길을 이루고 있었습니다. 전 이곳에서 바람이 내는 울부짖음과 깊게 흐르는 물에서 피어나는 수증기를 보고 통곡의 동굴이라 이름 지었습니다. $B$B그리고 생각했습니다. 이 동굴을 소생의 도구로 삼을 수 있으리라고. 불모의 땅 전역에는 이미 작지만 우거진 오아시스가 부글거리며 물을 뿜어대고 있었습니다... 마법의 힘을 부여하고 강화시킨다면, 성장의 기운이 대륙 전체로 퍼져 나갈 것으로 생각했습니다.', `MaleText_loc4`='在研究这片土地的时候，我发现有一座洞穴一直延伸到地下很深的地方。在这片炎热的荒原下面，地下暗河形成的水网覆盖了很大一片地方。我称这座因暗河冲刷而形成的洞穴为哀嚎洞穴。因为风和水流在这座洞中总是会发出一阵阵凄厉的嚎叫。$B$B我相信，这座洞穴是让大地回复生机的契机。暗河中的水已经在贫瘠之地的一些角落里渗透到地面，形成了一些葱翠茂盛的绿洲……如果这种渗水作用得到加强，那么这片土地就会被绿色所覆盖。', `MaleText_loc5`='在研究這片土地時，我發現了一個直達地底深處的洞穴。這些水道從幾英哩外的乾涸大草原將水運到了這裡。風和蒸汽在深淵裡的流動就像是發出了低吼聲，所以我稱它們為哀嚎洞穴。$B$B我認為...這會是讓一切重生的關鍵因素。水源已經上升到地表，在貧瘠之地的四處形成了小型的綠洲...如果它能被開流和分支，這種現象將會擴大散佈於這整片土地。', `MaleText_loc7`='Mientras estudiaba la tierra, encontré una cueva que se extendía en la profundidad bajo tierra. Estos canales albergaban nidos subterráneos durante kilómetros bajo la sabana. Les di el nombre de Cuevas de los Lamentos, por los alaridos del viento y el vapor cuando pasan por sus profundidades.$B$BPensé que este sería el instrumento del renacimiento. El agua ya se había filtrado a la superficie en forma de pequeños y exuberantes oasis en Los Baldíos... Si estuviera imbuida, mejorada, el crecimiento podría expandirse por toda la tierra.' WHERE `ID`=38331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 하셨습니까?', `MaleText_loc4`='那你做了什么？', `MaleText_loc5`='所以你做了什麼?', `MaleText_loc7`='Entonces, ¿qué hiciste?', `FemaleText_loc1`='그래서 어떻게 하셨습니까?', `FemaleText_loc4`='那你做了什么？', `FemaleText_loc5`='所以你做了什麼?', `FemaleText_loc7`='Entonces, ¿qué hiciste?' WHERE `ID`=38332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하수를 에메랄드의 꿈과 직접 연결하려는 계획을 세웠습니다. 믿음직한 신도들과 함께 통곡의 동굴 안쪽으로 깊숙이 탐험하여 명상을 시작한 후, 꿈속으로 들어갔지요. 제 몸을 통해 바깥 세계와 꿈이 연결되었습니다.$B$B그곳에서부터 모든 게 잘못되기 시작했습니다.', `MaleText_loc4`='我的计划是将这些地下水与翡翠梦境直接连通。我带领我忠实的信徒们，进入到哀嚎洞穴深处，在冥想中进入翡翠梦境。通过我的躯体，这个世界和翡翠梦境连接在一起。$B$B然而就在那时，发生了可怕的灾祸。', `MaleText_loc5`='我的計畫是直接將這些地底水源與翡翠夢境連接起來。與我忠心侍徒的陪同下，我到哀嚎洞穴的深處進行了冥想，進入了翡翠夢境。透過了我的肉身，這個世界與夢境聯接了起來。$B$B就是在那...一切都變了樣。', `MaleText_loc7`='Mi plan era conectar estas aguas subterráneas directamente al Sueño Esmeralda. Con mis fieles discípulos, viaje por las profundidades de las Cuevas de los Lamentos, medité y entré en el sueño. A través de mi propio cuerpo, este mundo permaneció conectado a él.$B$BAhí es donde todo salió mal.' WHERE `ID`=38333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어났습니까?', `MaleText_loc4`='出了什么事？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué ha ocurrido?', `FemaleText_loc1`='무슨 일이 일어났습니까?', `FemaleText_loc4`='出了什么事？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué ha ocurrido?' WHERE `ID`=38334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에메랄드의 꿈속에서 너무나도 강력한, 타락의 기운이라고밖에는 설명할 수 없는 존재와 마주치고 말았습니다. 서슬 퍼런 눈으로 절 주시하던 끝없는 악몽의 갈고리로 제 마음은 산산조각이 났습니다. 악몽의 손아귀에서 도저히 벗어날 방법이 없었습니다. 신도들도 절 깨우지 못했지요.$B$B알 수 없는 타락의 존재는 제 몸을 통해 세상으로 나가는 길을 발견했습니다. 그의 에너지를 통곡의 동굴에 집중하려 애썼지만, 결국 끔찍한 힘이 동굴 안의 생명체들을 뒤틀린 형태로 변화시키고 말았습니다. 영향을 받은 신도들의 마음은 광기와 흉포함에 사로잡혔습니다. 천둥매의 모습으로 변신한 그들은 자신을 송곳니의 드루이드라 일컬었습니다.', `MaleText_loc4`='我在翡翠梦境中遭遇了可怖的腐蚀力量，言语难尽其详。无尽的噩梦抓住了我，折磨我的心智。我无法摆脱它的囚禁。我的信徒们无法唤醒我。$B$B无论这种腐蚀来自于何处，它已经通过我的躯体来到了我们的世界。它的能量藉由我进入哀嚎洞穴。那种恐怖的力量扭曲了这里的野生动物，让它们变成了怪物。就连我的信徒们也受到了影响。他们的意识变得疯狂野蛮。他们的身体变得如同巨大的毒蛇。现在他们称自己为尖牙德鲁伊。', `MaleText_loc5`='我來自於那個已被腐化至極的翡翠夢境。無盡的夢魘將我牢牢地抓住，撕裂著我的心志。我無法掙脫它的魔爪;我的侍徒們無法將我叫醒。$B$B不管這個腐化是從哪開始的，它藉由我的身體入侵到我們的世界。我成功的把這股能量引導至哀嚎洞穴，它的影響力將那裡的生物轉化為混沌和扭曲的形態。就連我的侍徒都受到了影響;他們的心志變得瘋狂和野蠻，以毒蛇的形態示人，稱自己為尖牙德魯伊。', `MaleText_loc7`='Descubrí algo que solo se puede describir como una corrupción abrumadora dentro del Sueño Esmeralda. Una pesadilla interminable que me atrapó en sus garras y rasgó mi propia mente. No podía liberarme de su apretón; mis discípulos no podían despertarme.$B$BFuera lo que fuera esta corrupción, se abrió paso hasta nuestro mundo a través de mi cuerpo. Canalicé sus energías a las Cuevas de los Lamentos y su horrible influencia trastornó la vida salvaje de allí convirtiéndola en formas caóticas y desviadas. Incluso afectó a mis discípulos: la locura y el salvajismo se apoderaron de sus mentes, adoptaron la forma de serpientes y se hicieron llamar los Druidas del Colmillo.' WHERE `ID`=38335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 어떻게 탈출하셨습니까?', `MaleText_loc4`='你是怎样逃脱的？', `MaleText_loc5`='你是如何逃脫的?', `MaleText_loc7`='¿Cómo escapaste?', `FemaleText_loc1`='그곳에서 어떻게 탈출하셨습니까?', `FemaleText_loc4`='你是怎样逃脱的？', `FemaleText_loc5`='你是如何逃脫的?', `FemaleText_loc7`='¿Cómo escapaste?' WHERE `ID`=38336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 신도인 무요와 한 무리의 모험가에게 구출되었습니다. 모든 걸 완전한 실패로만 여겼는데, 대격변이 일어나자 오히려 지나치게 성공적이었다는 사실을 깨달았습니다!$B$B불모의 땅이 갈라져 분리되자, 엄청난 양의 지하수가 뿜어져 나와 땅 위로 흘러내렸습니다. 통곡의 동굴 안에 깃들어 있던 마력도 모두 함께 분출되었습니다. 주변에는 곧 생명의 기운이 충만했고 동물들도 번성하기 시작했습니다... 거침없이, 통제할 수 없을 때까지 계속된 성장을 거듭한 것입니다.$B$B이제는 자연의 흐름과 형태를 바꾸어 놓을 수 있으리라 생각한 제 오만함에 답할 때입니다. 야생의 자연이 완전히 침식당하기 전에, 이 비정상적인 성장을 멈추어야 합니다.', `MaleText_loc4`='我被我的最后一名信徒穆约和一队冒险者救了出来。我以为我的计划已经彻底失败了。当大灾变到来时，我才意识到，我的计划可以说是过度地成功了！$B$B当贫瘠之地裂开时，巨大的地下水流涌上地表，其中充满了那股在哀嚎洞穴中肆虐的诡异能量。各种生命随之迅速繁衍壮大，无论植物还是动物……都在不受控制地过度生长。$B$B我以为自己能控制自然本身的形态和变化。而现在，我必须为自己的傲慢做出补救。这种生命的蔓生必须被阻止，否则它就会吞没整个自然生态。', `MaleText_loc5`='我是被我最後的一位侍徒繆幽和一群冒險者所救。我本來認為這次的事件是個完全的失敗，直到大災變的發生我才認知到我做得非常成功!$B$B當貧瘠之地裂開時，一條洶湧的地下水道被破壞，衝上了地表之上，它充滿了在哀嚎洞穴中所被灌注的能量。生命立刻源源不絕地冒出來，動物們獲得了能量...而且無止境地持續長大。$B$B我現在必須為我當初認為能控制自然循環的傲慢付出代價。我必須阻止這種無止境的生長，在它完全吞噬了自然界的野生生物前。', `MaleText_loc7`='Me salvaron mi último discípulo, Muyoh, y un grupo de aventureros. Consideré el incidente entero como un fracaso. No fue hasta el Cataclismo, cuando me di cuenta de que había tenido demasiado éxito.$B$BCuantos Los Baldíos se agrietaron, se abrió paso hasta la superficie una gran fuente de agua subterránea que rezumaba la energía con la que estaban imbuidas las Cuevas de los Lamentos. La vida comenzó a surgir en la tierra que la rodeaba y los animales prosperaron... y continuó creciendo, sin control, sin obstáculos.$B$BAhora tengo que responder por mi arrogancia al pensar que podía dictar el flujo y la forma de la naturaleza. Este crecimiento ha de ser detenido, antes de que ahogue completamente toda la vida salvaje natural.' WHERE `ID`=38337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히?!', `MaleText_loc4`='谁这么大胆？！', `MaleText_loc5`='誰敢?!', `MaleText_loc7`='¿QUIÉN OSA?' WHERE `ID`=38338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숙녀분들은 어디서 찾아야 합니까?', `MaleText_loc4`='少女在哪里？', `MaleText_loc5`='尋覓少女的話要去哪裡找呢?', `MaleText_loc7`='¿Dónde iría uno para encontrar damiselas?', `FemaleText_loc1`='숙녀분들은 어디서 찾아야 하나요?', `FemaleText_loc4`='少女在哪里？', `FemaleText_loc5`='尋覓少女的話要去哪裡找呢?', `FemaleText_loc7`='¿Dónde iría uno para encontrar damiselas?' WHERE `ID`=38339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 눈에 용은 안 보입니다.', `MaleText_loc4`='我没有看到任何龙。', `MaleText_loc5`='我沒看到有什麼龍族。', `MaleText_loc7`='No veo dragones por ninguna parte.', `FemaleText_loc1`='제 눈에 용은 안 보이는데요.', `FemaleText_loc4`='我没有看到任何龙。', `FemaleText_loc5`='我沒看到有什麼龍族。', `FemaleText_loc7`='No veo dragones por ninguna parte.' WHERE `ID`=38340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적절한 질문이로구나.$b$b먼저 온천 근처를 찾아보거라. 서쪽의 절벽에서 봉화를 찾아보는 것도 괜찮겠지. 마지막으로 먼 북쪽의 실리더스에서도 위험이 도사리는 곳이니라.$b$b이 장소들을 수색할 생각이다.', `MaleText_loc4`='这是个好问题。$b$b温泉的周围，西边悬崖上的烽火，以及北面通往希利苏斯的小路。$b$b这些都是我要去查看的地方。', `MaleText_loc5`='好問題。$b$b可以去檢查溫泉的外圍，或者去尋找從西邊山壁發出的信號。前往希利蘇斯的道路，延伸至遙遠的北邊，是條充滿著荊棘與危險的路。$b$b而以上這些是我會去檢查的地方。', `MaleText_loc7`='Buena pregunta.$B$BSe puede comprobar el perímetro de los manantiales cálidos, o buscar hogueras de señalización en los riscos al oeste. Finalmente, el camino a Silithus, a lo lejos al norte, a menudo está plagado de peligros.$B$BEsos son los lugares que comprobaría yo.' WHERE `ID`=38341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되는 소리. 내가 눈먼 종자를 고용했더냐? 사방이 용 천지이지 않으냐.$b$b내 이웃 스파크는 이놈들을 "공룡"이라고 부르지만 내 눈에는 엄연히 용으로 보이느니라. 이놈들을 반드시 처단해야 한다.', `MaleText_loc4`='胡说。难道我雇佣了一个瞎眼的侍从？这里到处都是龙。$b$b我的邻居斯巴克说它们是“恐龙”。但我知道龙是什么样子。所以它们必须被消灭。', `MaleText_loc5`='胡說八道。我是雇用了一名瞎眼侍從嗎?到處都是飛龍。$b$b我的鄰居斯巴克說牠們是『恐龍』。但我看一眼就能認出飛龍。牠們必須被消滅。', `MaleText_loc7`='Absurdo. ¿He contratado a un escudero ciego? Hay dragones por todas partes.$B$BMi vecino Chispik se refiere a ellos como "dinosaurios", pero yo sé reconocer a un dragón en cuanto lo veo. Hay que matarlos.' WHERE `ID`=38342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 화석으로 만들어 버리겠다, 이 $r 녀석아!', `MaleText_loc4`='我要把你变成化石，$r！', `MaleText_loc5`='我要把你變成化石，$r!', `MaleText_loc7`='¡Te convertiré en fósil, $r!' WHERE `ID`=38343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 내 무덤을 팠구나...', `MaleText_loc4`='我真是自掘坟墓……', `MaleText_loc5`='我自掘墳墓...', `MaleText_loc7`='He cavado mi propia tumba...' WHERE `ID`=38344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르나, 눈물 나게 반갑소. 자, 대포에 병사를 배치해라! 나머지 병력은 누더기골렘을 넓은 곳으로 유인하라!', `MaleText_loc4`='见到你真是太好了，罗娜。我们来操纵这些大炮！其他人，把那些憎恶引到开阔地去！', `MaleText_loc5`='看到你真叫人精神一振啊，羅娜。快點找人手操作那些火砲吧!你們其他人，把那些憎惡體引到空曠的地方!', `MaleText_loc7`='Dichosos los ojos que te ven, Lorna. ¡Quiero un hombre en cada cañón! ¡El resto, que las abominaciones los sigan a descubierto!' WHERE `ID`=38345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자그마한 고블린이라고? 너희 종족이 창조되던 때를 기억한다.', `MaleText_loc4`='小地精？我还记得你们这一族被创造出来的情景。', `MaleText_loc5`='小哥布林?我對你們種族被創造之時還印象深刻。', `MaleText_loc7`='¿Pequeños goblins? Recuerdo cuando su raza fue creada.' WHERE `ID`=38346;
