UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 협박도 이 나가도 전혀 상관하지 않는다. 곧 존재가 없어질 각오나 해라.', `MaleText_loc4`='我不害怕你的威胁，也不会在乎这些纳迦。为灭亡做好准备吧。', `MaleText_loc5`='我才不在乎你的威脅或這些納迦。準備好從這個世上消失吧。', `MaleText_loc7`='No me interesan sus amenazas ni estos nagas. Prepárense para desaparecer de la existencia.' WHERE `ID`=38349;
