UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 몸짓 하나까지 다 보고 계신다...', `MaleText_loc4`='你的每个举动都在他的监视之下…', `MaleText_loc5`='他注視著你的一舉一動...', `MaleText_loc7`='Él vigila todos tus movimientos...', `FemaleText_loc1`='네 몸짓 하나까지 다 보고 계신다...', `FemaleText_loc4`='你的每个举动都在他的监视之下…', `FemaleText_loc5`='他注視著你的一舉一動...', `FemaleText_loc7`='Él vigila todos tus movimientos...' WHERE `ID`=38354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통으로 몸부림쳐라... 고통이 네 힘을 누르게 하라...', `MaleText_loc4`='在痛苦中哭泣吧…让你的痛消磨你的力量…', `MaleText_loc5`='在苦難中哭嚎吧...讓你的痛苦壓倒你的力量...', `MaleText_loc7`='Grita por tu tormento... Deja que el dolor supere tu fuerza...', `FemaleText_loc1`='고통으로 몸부림쳐라... 고통이 네 힘을 누르게 하라', `FemaleText_loc4`='在痛苦中哭泣吧…让你的痛消磨你的力量…', `FemaleText_loc5`='在苦難中哭嚎吧...讓你的痛苦壓倒你的力量...', `FemaleText_loc7`='Grita por tu tormento... Deja que el dolor supere tu fuerza...' WHERE `ID`=38355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요 작은 귀염둥이들을 짧은 끈으로 묶어 두었지, $n. 어린 나가를 데리고 있는 한 우리를 공격 못할 거야.', `MaleText_loc4`='我已经紧紧控制住了这些小混蛋，$n。当我们控制他们的时候，纳迦是不会攻击我们的。', `MaleText_loc5`='我把這些小惡棍綁得牢牢的，$n。只要我們有他們的小孩，納迦就不會攻擊我們。', `MaleText_loc7`='Tengo a estos pequeños demonios atados en corto, $n. Los nagas no nos atacarán mientras tengamos a sus crías.' WHERE `ID`=38356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들 지도자를 항복시킬 준비는 되었어, 친구? 좋아, 가자고.', `MaleText_loc4`='你准备好让他们的首领投降了，$g小伙子:姑娘;？好吧，我们开始吧。', `MaleText_loc5`='你準備好讓他們的首領求饒了嗎，$g兄弟:小妞;?好，我們出發。', `MaleText_loc7`='¿Estás $gpreparado:preparada; para obligar a su líder a rendirse, $gchico:chica;? Vale, allá vamos.' WHERE `ID`=38357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 이봐. 좋지 않은데. 난 빠지겠어!', `MaleText_loc4`='嗯，小子，这看上去不太好。我要离开这里！', `MaleText_loc5`='嗯～～老兄，這看起來不妙。我要閃了!', `MaleText_loc7`='Ehm, tío, esto no tiene buena pinta. ¡Yo me largo!' WHERE `ID`=38358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $n|1아;야;, 이제 네 차례다!', `MaleText_loc4`='年轻的$n，你现在要死了！', `MaleText_loc5`='現在，年輕的$n，受死吧!', `MaleText_loc7`='¡Ahora, joven $n, morirás!' WHERE `ID`=38359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤리의 병력이 앞에 있다! 계속 전진하라!', `MaleText_loc4`='克罗雷的部队就在前面！继续前进！', `MaleText_loc5`='克羅雷的軍隊就在前面!繼續前進!', `MaleText_loc7`='¡Las tropas de Crowley están más adelante! ¡Sigan!' WHERE `ID`=38360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 함께 싸우겠네. 실바나스를 상대하려면 우리의 도움이 필요할 게야.', `MaleText_loc4`='加入你父亲的军队，利亚姆。我们一起对抗希尔瓦娜斯。', `MaleText_loc5`='讓我們加入你父親的軍隊，黎姆。他們需要我們幫忙對付希瓦娜斯。', `MaleText_loc7`='Déjanos ayudar a las fuerzas de tu padre, Liam. Nos necesitarán contra Sylvanas.' WHERE `ID`=38361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누더기골렘이 군사 지구로 통하는 길을 막고 있다! 이거 쉽진 않겠군.', `MaleText_loc4`='憎恶封锁了通向军事区的道路！这将会是一场硬仗。', `MaleText_loc5`='那些憎惡體擋住了前往軍事區的路!它們會有點棘手。', `MaleText_loc7`='¡Unas abominaciones bloquean el paso al distrito militar! Será difícil.' WHERE `ID`=38362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독액 뿌리기를 시전합니다!', `MaleText_loc4`='%s开始施放软泥喷射！', `MaleText_loc5`='%s開始施放泥漿噴霧!', `MaleText_loc7`='¡%s comienza a lanzar Pulverizador de babas!' WHERE `ID`=38363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퇴각로를 막아라, 리암! 놈들이 딱 좋은 위치에 있다!', `MaleText_loc4`='封锁退路！利亚姆，把他们赶到计划中的地点去！', `MaleText_loc5`='擋住他們去路，黎姆! 這正是我們要他們在的位置!', `MaleText_loc7`='¡Bloquea su retirada, Liam! ¡Los tenemos justo donde los queríamos!' WHERE `ID`=38364;
