UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만!', `FemaleText_loc4`='够了！', `FemaleText_loc5`='夠了!', `FemaleText_loc7`='¡Suficiente!' WHERE `ID`=38366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이 있어도 이 전투에는 빠질 수 없죠! 가자고요!', `FemaleText_loc4`='我绝对不会缺席这场战斗。我们出发！', `FemaleText_loc5`='我絕不可能在這場戰鬥中缺席。走吧!', `FemaleText_loc7`='Ni loca me quedo fuera de esta pelea. ¡Vamos!' WHERE `ID`=38367;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈들의 용감한 지도자 없이도 길니아스인이 승리할지 두고 보겠다!', `FemaleText_loc4`='让我们看看，当吉尔尼斯人失去了他们顽固的首领时，他们还会有多勇敢！', `FemaleText_loc5`='讓我們來瞧瞧他們失去頑強的領導者後會多勇敢!', `FemaleText_loc7`='¡Veamos lo valientes que son en Gilneas sin su testarudo líder!' WHERE `ID`=38368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지!!!', `MaleText_loc4`='父亲！！！', `MaleText_loc5`='父親!', `MaleText_loc7`='¡¡¡PADRE!!!' WHERE `ID`=38369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화살만 낭비했군. 네놈의 피붙이나 잡으려고 쏜 독화살이 아니었는데. 다음을 기약하지!', `FemaleText_loc4`='真是浪费。这样的毒箭可不该浪费在你这种小狗崽的身上。我们会再见的！', `FemaleText_loc5`='真是浪費。那支箭上的毒不該浪費在這兔崽子身上的。我們會再見的!', `FemaleText_loc7`='Qué desperdicio. No se suponía que usáramos el veneno de esa flecha en tu cría. ¡Nos volveremos a ver!' WHERE `ID`=38370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다...', `MaleText_loc4`='我们做到了，父亲……', `MaleText_loc5`='我們成功了，父親...', `MaleText_loc7`='Lo logramos, padre...' WHERE `ID`=38371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 도시를 되찾았습니다... 해냈어요...', `MaleText_loc4`='我们夺回了城市……夺回了……', `MaleText_loc5`='我們搶回了我們的城，搶回了...', `MaleText_loc7`='Recuperamos nuestra ciudad... lo hicimos...' WHERE `ID`=38372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜나지 못해. 안 그러면 어린 나가가 대신 혼쭐날 거야!', `MaleText_loc4`='别挡我们的道，否则就让你们的鱼苗吃点苦头！', `MaleText_loc5`='閃開，要不然就宰了你的幼獸!', `MaleText_loc7`='¡Fuera de nuestro camino, o sus crías se enterarán!' WHERE `ID`=38373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 나가들 가까이 다가오지 말라고. 농담이 아니야!', `MaleText_loc4`='纳迦最好和我们保持距离。我们可不是在开玩笑！', `MaleText_loc5`='你們納迦最好離遠點。我們可不是好惹的!', `MaleText_loc7`='Mantened las distancias, nagas. ¡No estamos de broma!' WHERE `ID`=38374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 너희 새끼가 있어. 우리를 공격하지 않는 게 서로 좋다는 정도는 알겠지!', `MaleText_loc4`='我们已经得到了你们的鱼苗。你们最好放明白一些，不要攻击我们！', `MaleText_loc5`='我們抓了你們的小孩。如果你知道什麼對你有利的話，你最好不要攻擊我們!', `MaleText_loc7`='Tenemos a tus crías. ¡Será mejor que no nos ataques si sabes lo que te conviene!' WHERE `ID`=38375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사에 항복할 준비나 해!', `MaleText_loc4`='准备向锈水财阀投降吧！', `MaleText_loc5`='準備向污水企業聯合投降吧!', `MaleText_loc7`='¡Preparaos para rendiros al Cártel Pantoque!' WHERE `ID`=38376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 공격하려고 준비하던 거 다 알아. 이건 너희가 자초한 일이라고.', `MaleText_loc4`='我们知道，你们正准备攻击我们。这一切都是你们造成的。', `MaleText_loc5`='我們知道你們準備要攻擊我們。這是你們自找的。', `MaleText_loc7`='Sabemos que les estaban preparando para atacarnos. Esto se lo han buscado ustedes.' WHERE `ID`=38377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 움직이거나 하지 마! 항복을 받아낸 다음 평화롭게 떠날 테니.', `MaleText_loc4`='不要有任何出轨的举动！我们在谈妥你们的投降条件之后，就会和平地离开。', `MaleText_loc5`='通通不要動!我們只想協商你們投降的條件，然後就會平靜地離去。', `MaleText_loc7`='¡Que nadie haga movimientos bruscos! Negociaremos tu rendición y nos iremos pacíficamente.' WHERE `ID`=38378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 전부 항복하고 나면 특별 나가 감사 할인 행사를 계획 중이야. 지금 있는 상품 대부분을 30퍼센트 깎아줄 거야. 칼도레이 유물은 오늘만 특별 한정 할인이야!', `MaleText_loc4`='在投降程序完成之后，我们计划进行一场特别的纳迦感恩促销。我们的货架商品绝大部分都会降价30%。', `MaleText_loc5`='在處理完你們的投降後，我們打算來個納迦感恩特賣。所有現貨商品通通七折。卡多雷神器賤價甩賣只限今天!', `MaleText_loc7`='Cuando ya tengamos solucionado todo el tema de su rendición, vamos a celebrar una venta especial de temática naga. Un treinta por ciento de descuento en todos los artículos que tenemos en stock. ¡Un ahorro espectacular en artefactos Kaldorei! ¡Solo hoy!' WHERE `ID`=38379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 시끄럽게 하고 싶지는 않아. 그저 우리 앞길을 가로막지만 않는다면 아무 문제도 없어. 아무도 다칠 필요도 없고. 특히 내가 안 다쳐도 되지!', `MaleText_loc4`='我们不想惹麻烦。只要别挡我们的路，一切都不会有问题。没有人会受到伤害。特别是我！', `MaleText_loc5`='我們不想要任何麻煩。只要我們的道路沒有任何阻礙，一切就相安無事。沒有人會受到傷害，尤其是我!', `MaleText_loc7`='No queremos problemas. Tan solo mantened nuestro camino libre y todo saldrá bien. Nadie tiene que resultar herido. ¡Y en especial yo!' WHERE `ID`=38380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 나가 우두머리. 그렇게 숨어 있지 말고 나와서 $n|1과;와; 빌지워터 무역회사 이름 앞에 항복해!', `MaleText_loc4`='好吧，纳迦头领，从你的藏身之地钻出来，向$n和锈水财阀投降吧！', `MaleText_loc5`='好啦，納迦的首領，別再躲了，以$n與污水企業聯合之名投降吧!', `MaleText_loc7`='Está bien, líder de los nagas, sal de tu escondite y ríndete a $n y al Cártel Pantoque.' WHERE `ID`=38381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 유혹하지는 말라고! 그 안에 뭐가 들었는지 알기나 해?', `MaleText_loc4`='别试探我！你根本不知道那些东西里究竟有什么吧？', `MaleText_loc5`='別誘惑我!你知道那些東西裡面是什麼嗎?', `MaleText_loc7`='¡No me tientes! ¿Sabes siquiera qué hay en esas cosas?' WHERE `ID`=38382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주님, 아서스가 오는 소리가 들린 듯합니다. 무얼 하시려는지 몰라도 서두르십시오.', `MaleText_loc4`='我的女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。', `MaleText_loc5`='女士，我想我聽見阿薩斯正在靠近。不管你們打算作什麼，請加快動作。', `MaleText_loc7`='Mi señora, creo que escucho a Arthas acercarse. Lo que vayas a hacer, hazlo deprisa.', `FemaleText_loc1`='여군주님, 아서스가 오는 소리가 들린 듯해요. 무얼 하시려는지 몰라도 서두르세요.', `FemaleText_loc4`='我的女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。', `FemaleText_loc5`='女士，我想我聽見阿薩斯正在靠近。不管你們打算作什麼，請加快動作。', `FemaleText_loc7`='Mi señora, creo que escucho a Arthas acercarse. Lo que vayas a hacer, hazlo deprisa.' WHERE `ID`=38383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 저게 뭐죠?', `FemaleText_loc4`='喔，那是什么？', `FemaleText_loc5`='哇喔，那是什麼?', `FemaleText_loc7`='¡Guau! ¿Qué es eso?' WHERE `ID`=38384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분석하는 데 쓸 만한 스컬지 역병을 구하느라 우리 요원들이 얼마나 많이 실패했는지 몰라요. 제가 직접 최전방에 나가서 어떻게 하는지 지켜봤지요. 사람들 말대로, 일을 제대로 하고 싶다면 말이에요...', `FemaleText_loc4`='我们的密探在搜集可用的天灾军团枯萎样本时经历了很多次失败，现在我亲自到前线来视察工作进度。就像他们说的，如果你希望工作能够干好…', `FemaleText_loc5`='我們的探員在歷經無數的失敗後，終於弄到了天譴荒疫的樣本來進行分析，我也親自到過前線去監督進度。就像俗話說的，希望事情辦得好...', `FemaleText_loc7`='Tras los incontables fracasos de nuestros agentes para conseguir muestras de añublo de la Plaga aptas para el análisis, he venido a las líneas de frente para supervisar sus esfuerzos. Como dicen, si quieres algo bien hecho...' WHERE `ID`=38385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보아하니 썩은얼굴과 재미있게 노신 듯하군요. 그러나 제대로 된 견본을 얻으려면 역병 종이 둘 다 있어야겠네요.', `FemaleText_loc4`='看起来你和腐面在一起玩的挺开心，但要取得合适的标本，恐怕我同时需要两样东西才行！', `FemaleText_loc5`='看來你跟腐臉玩得很愉快，但要收集到適合的樣本，我恐怕得需要同時取得兩種荒疫!', `FemaleText_loc7`='Parece que te has divertido jugando con Carapútrea, pero para conseguir un espécimen adecuado, me temo que necesitaré AMBAS cepas de añublo a la vez.' WHERE `ID`=38386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보아하니 구린속과 재미있게 노신 듯하군요. 그러나 제대로 된 견본을 얻으려면 역병 종이 둘 다 있어야겠네요.', `FemaleText_loc4`='看起来你和烂肠在一起玩的挺开心，但要取得合适的标本，恐怕我同时需要两样东西才行！', `FemaleText_loc5`='看來你跟膿腸玩得很愉快，但要收集到適合的樣本，我恐怕得需要同時取得兩種荒疫!', `FemaleText_loc7`='Parece que te has divertido jugando con Panzachancro, pero para conseguir un espécimen adecuado, me temo que necesitaré AMBAS cepas de añublo a la vez.' WHERE `ID`=38387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사님, 전 살아 있는 역병으로 뒤덮였습니다!', `MaleText_loc4`='炼金师，我沾到了活的枯萎！', `MaleText_loc5`='鍊金師，我被活體荒疫所覆蓋!', `MaleText_loc7`='¡Alquimista, estoy cubierto de añublo viviente!', `FemaleText_loc1`='연금술사님, 전 살아 있는 역병으로 뒤덮였어요!', `FemaleText_loc4`='炼金师，我沾到了活的枯萎！', `FemaleText_loc5`='鍊金師，我被活體荒疫所覆蓋!', `FemaleText_loc7`='¡Alquimista, estoy cubierto de añublo viviente!' WHERE `ID`=38388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사님, 전 살아 있는 역병으로 뒤덮였습니다!', `MaleText_loc4`='炼金师，我沾到了活的枯萎！', `MaleText_loc5`='鍊金師，我被活體荒疫所覆蓋!', `MaleText_loc7`='¡Alquimista, estoy cubierto de añublo viviente!', `FemaleText_loc1`='연금술사님, 전 살아 있는 역병으로 뒤덮였습니다!', `FemaleText_loc4`='炼金师，我沾到了活的枯萎！', `FemaleText_loc5`='鍊金師，我被活體荒疫所覆蓋!', `FemaleText_loc7`='¡Alquimista, estoy cubierto de añublo viviente!' WHERE `ID`=38389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿을 수가 없군요. 강력하고, 치명적이며, 끝내주는 역병으로 뒤범벅이군요! 잠시만, 제가 이 신선한 견본을 채취하도록 해 주세요. 동료 여러분께 남은 감염도 제거해 드리고 의술의 이름으로 용감하고 희생적인 당신에게 보상해 드리겠어요. 계속할 준비가 되면 말씀해 주세요. [진행하기 전에, 성취에 대한 공로를 함께 인정받을 수 있도록 ''모든'' 공격대원을 가까이 오도록 하십시오.]', `FemaleText_loc4`='简直难以置信！你身上覆盖了奇异的活性剧毒枯萎！拜托，请允许我采集这些纯净的标本。我还会帮你的队友清楚残留的感染，并以医学的名义对你们的勇敢和自我牺牲精神加以回报！准备好了以后请告诉我。', `FemaleText_loc5`='太驚人了!你被強大、致命的絕妙荒疫所覆蓋!拜託，請讓我收集這些原始樣本。我也會移除你盟友身上的殘存傳染，並獎勵你為醫學所付出的犧牲與勇氣!如果你準備好進行，就跟我說一聲。

[在進行前，請確定『所有』的團隊成員都在集合到附近，以獲得完成的效果。]', `FemaleText_loc7`='¡Esto es increíble! ¡Estás $gcubierto:cubierta; de un añublo potente, virulento y fantástico! Permíteme recolectar estas muestras inmaculadas. ¡También eliminaré cualquier infección restante de tus aliados y te recompensaré por tu valor y sacrificio en el nombre de la medicina! Avísame si estás $gpreparado:preparada; para continuar.

[Antes de continuar, asegúrate de que TODOS los miembros de la banda están cerca para poder recibir el crédito de tu logro.]' WHERE `ID`=38390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 견본을 수집하십시오.', `MaleText_loc4`='好了。采集你的标本吧。', `MaleText_loc5`='繼續吧。收集你的樣本。', `MaleText_loc7`='Adelante. Recolecta tus especímenes.', `FemaleText_loc1`='자, 어서 견본을 수집하세요.', `FemaleText_loc4`='好了。采集你的标本吧。', `FemaleText_loc5`='繼續吧。收集你的樣本。', `FemaleText_loc7`='Adelante. Recolecta tus especímenes.' WHERE `ID`=38391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 더 이상 말해줄 게 없다. 여길 떠나라.', `FemaleText_loc4`='你在这里什么都得不到。走吧。', `FemaleText_loc5`='這裡沒有什麼可以給你的。滾吧!', `FemaleText_loc7`='Aquí no tienes nada que hacer. Vete.' WHERE `ID`=38392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마샬의 격전지로 돌아가게 해 주십시오.', `MaleText_loc4`='行行好，我要回到马绍尔哨站。', `MaleText_loc5`='我想要回到馬紹爾觀測站，拜託。', `MaleText_loc7`='Me gustaría regresar al Alto de Marshal, por favor.', `FemaleText_loc1`='마샬의 격전지로 돌아가게 해 주세요.', `FemaleText_loc4`='行行好，我要回到马绍尔哨站。', `FemaleText_loc5`='我想要回到馬紹爾觀測站，拜託。', `FemaleText_loc7`='Me gustaría regresar al Alto de Marshal, por favor.' WHERE `ID`=38393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 알겠는가, $n?', `FemaleText_loc4`='你现在明白了，$n？', `FemaleText_loc5`='你現在明白了嗎，$n?', `FemaleText_loc7`='¿Entiendes ahora, $n?' WHERE `ID`=38394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 너를 찾으신다.', `MaleText_loc4`='我的主人需要你。', `MaleText_loc5`='我的守護神要求見你一面。', `MaleText_loc7`='Mi jefe solicita tu presencia.' WHERE `ID`=38395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구체자의 정원에 갈 준비가 되었습니다.', `MaleText_loc4`='我准备好前往塑造者之台了。', `MaleText_loc5`='我已經準備好前往塑造者殿堂。', `MaleText_loc7`='Estoy preparado para ir a El Bancal del Creador.', `FemaleText_loc1`='구체자의 정원에 갈 준비가 되었어요.', `FemaleText_loc4`='我准备好前往塑造者之台了。', `FemaleText_loc5`='我已經準備好前往塑造者殿堂。', `FemaleText_loc7`='Estoy preparada para ir a El Bancal del Creador.' WHERE `ID`=38396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구체자의 정원으로 돌아가고 싶습니다.', `MaleText_loc4`='我想要返回塑造者之台。', `MaleText_loc5`='我想要回到塑造者殿堂。', `MaleText_loc7`='Me gustaría regresar a El Bancal del Creador.', `FemaleText_loc1`='구체자의 정원으로 돌아가겠어요.', `FemaleText_loc4`='我想要返回塑造者之台。', `FemaleText_loc5`='我想要回到塑造者殿堂。', `FemaleText_loc7`='Me gustaría regresar a El Bancal del Creador.' WHERE `ID`=38397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가, $n?', `MaleText_loc4`='什么事，$n？', `MaleText_loc5`='是的，$n?', `MaleText_loc7`='¿Sí, $n?' WHERE `ID`=38398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가자. 길니아스를 위해 실바나스를 찾아내겠다!', `MaleText_loc4`='立刻出发。我们一定能打倒希尔瓦娜斯。为了吉尔尼斯！', `MaleText_loc5`='讓我們立刻出發。我們要找到希瓦娜斯。為了吉爾尼斯!', `MaleText_loc7`='Vayamos inmediatamente. Localizaremos a Sylvanas. ¡Por Gilneas!' WHERE `ID`=38399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토비아스 미스트맨틀을 따라 대성당 광장으로 가십시오.', `MaleText_loc4`='跟踪托比亚斯·密斯特曼托，进入教堂区。', `MaleText_loc5`='跟隨托比亞斯·密斯特曼托前往大教堂區。', `MaleText_loc7`='Sigue a Tobias Mantoniebla al Distrito de la Catedral.' WHERE `ID`=38400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발견되지 않도록 최대한 노력해야 한다, $n.', `MaleText_loc4`='让我们尽量别被发现，$n。', `MaleText_loc5`='我們要千萬小心不要被發現，$n。', `MaleText_loc7`='Hagamos todo lo posible para que no nos vean, $n.' WHERE `ID`=38401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그 말 들으셨습니까, $n? 실바나스가 새벽빛 대성당으로 향했습니다. 어서 서둘러야 합니다!', `MaleText_loc4`='$n，你听到了吗？希尔瓦娜斯正赶往那座教堂。我们要立刻采取行动！', `MaleText_loc5`='你聽到了嗎，$n?希瓦娜斯要前往大教堂。我們動作要快點!', `MaleText_loc7`='¿Has oído eso, $n? Sylvanas se dirige hacia la catedral. ¡Démonos prisa!' WHERE `ID`=38402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요! 물속으로 숨으십시오!', `MaleText_loc4`='快点！藏进水里！', `MaleText_loc5`='快!躲進水裡!', `MaleText_loc7`='¡Deprisa! ¡Escóndete en el agua!' WHERE `ID`=38403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 누구냐? 우리 부족에게 원하는 게 뭐지?', `MaleText_loc4`='你是谁？你想从我们的部族得到什么？', `MaleText_loc5`='你是誰?你想要對我們的部族做什麼?', `MaleText_loc7`='¿Quién eres? ¿Qué quieres de nuestra tribu?' WHERE `ID`=38404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나블리아 님, 당신이십니까?', `MaleText_loc4`='娜博亚，是你吗？', `MaleText_loc5`='娜畢雅，是你嗎?', `MaleText_loc7`='Nablya, ¿eres tú?' WHERE `ID`=38405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 우리 집에 온 걸 환영한다.', `MaleText_loc4`='外乡人，欢迎来到我们的家园。', `MaleText_loc5`='歡迎你，外來者，歡迎你來到我們的家。', `MaleText_loc7`='$gBienvenido: Bienvenida; a nuestro hogar, $gforastero:forastera;.' WHERE `ID`=38406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 관찰하러 온 건가? 야자라도 하나 먹을 텐가?', `MaleText_loc4`='你是来进行观察的吗？想要一个椰子吗？', `MaleText_loc5`='你是來觀察的嗎?要不要一棵椰子?', `MaleText_loc7`='¿Has venido a observar? ¿Quieres un coco?' WHERE `ID`=38407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 뭘 가르쳐주실 수 있으십니까, 천둥고릴라님?', `MaleText_loc4`='你能教我些什么，大猩猩？', `MaleText_loc5`='你可以教我什麼呢，雷鳴者?', `MaleText_loc7`='¿Qué puedes enseñarme, Tronador?', `FemaleText_loc1`='저에게 뭘 가르쳐주실 수 있으신가요, 천둥고릴라님?', `FemaleText_loc4`='你能教我些什么，大猩猩？', `FemaleText_loc5`='你可以教我什麼呢，雷鳴者?', `FemaleText_loc7`='¿Qué puedes enseñarme, Tronador?' WHERE `ID`=38408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 무엇을 가르쳐주실 수 있으십니까? 우레고릴라님?', `MaleText_loc4`='你能教我些什么，巨猩猩？', `MaleText_loc5`='你可以教我什麼呢，踐踏者?', `MaleText_loc7`='¿Qué puedes enseñarme, Vapuleador?', `FemaleText_loc1`='제게 무엇을 가르쳐주실 수 있나요? 우레고릴라님?', `FemaleText_loc4`='你能教我些什么，巨猩猩？', `FemaleText_loc5`='你可以教我什麼呢，踐踏者?', `FemaleText_loc7`='¿Qué puedes enseñarme, Vapuleador?' WHERE `ID`=38409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 뭘 가르쳐주실 수 있습니까?', `MaleText_loc4`='你能教我些什么，猩猩？', `MaleText_loc5`='你能教我什麼，猩猩?', `MaleText_loc7`='¿Qué puedes enseñarme, Gorila?', `FemaleText_loc1`='제게 뭘 가르쳐주실 수 있나요?', `FemaleText_loc4`='你能教我些什么，猩猩？', `FemaleText_loc5`='你能教我什麼，猩猩?', `FemaleText_loc7`='¿Qué puedes enseñarme, Gorila?' WHERE `ID`=38410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중 일부는 천둥의 힘을 활용하기도 한다. 그 힘으로 인간, 오크, 공룡과 같은 침략자들로부터 우리를 지키곤 하지.$b$b우리의 번개는 그 어떠한 공룡도 기절시킬 수 있다.', `MaleText_loc4`='我们部落中的一些人能够驾驭雷电的力量。我们就是用这种力量来抵抗入侵者，不管是人类、兽人还是恐龙。$b$b要知道，我们的雷电能够震晕任何恐龙。', `MaleText_loc5`='我們的部族中有幾個已經掌握了雷霆的力量。我們用它來保護自己對抗入侵者，不論是人類、獸人或是恐龍。$b$b我們的雷霆能擊暈所有恐龍，知道吧。', `MaleText_loc7`='Algunos miembros de nuestra tribu han dominado el poder del trueno. Lo utilizamos para defendernos de los invasores, ya sean humanos, orcos o dinosaurios.$b$bSabes, nuestro trueno aturde a todos los dinosaurios.' WHERE `ID`=38411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개개인의 힘도 중요하다. 하지만 부족 전체의 힘은 더더욱 중요하다. 그렇기에 우리 부족의 힘은 우리 중 가장 약한 전사의 힘과 비례한다고 생각한다.', `MaleText_loc4`='个体的力量很重要，但全族的力量更加重要。只有当我们部族中最弱小的个体也强大起来，我们的部族才会真正变得强大。', `MaleText_loc5`='個人的力量很重要，但是部族的力量更重要。我們的部族就跟族中的弱者一樣弱。', `MaleText_loc7`='La fuerza individual es importante, pero la tribal también lo es. Nuestra tribu es tan fuerte como nuestro miembro más débil.' WHERE `ID`=38412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽의 덩굴손은 개구리나 앵무새처럼 작은 생물을 먹는다. 우리 고릴라는 덩굴손을 먹는다. 그리고 공룡은 고릴라를 먹는다. 이 모든 게 고결하고 자연스러운 자연의 섭리다.$b$b하지만 인간과 오크는 고릴라를 사냥하고 가죽만 챙기고는 몸은 썩게 버려둔다. 그것이 우리가 인간과 오크를 공격하는 이유다.', `MaleText_loc4`='南边的鳄鱼人喜欢吃小动物，比如青蛙和鹦鹉。我们猩猩则喜欢吃鳄鱼人。恐龙喜欢吃猩猩。所有这些都是严肃的自然规律。$b$b人类和兽人也会猎杀猩猩。但他们只剥去我们的毛皮，我们的尸体则被随意丢弃，任由它们腐烂。所以我们才会攻击人类和兽人。', `MaleText_loc5`='南邊的鞭笞者會吃像是青蛙和鸚鵡等小型生物。我們這群大猩猩會吃這些鞭笞者，而恐龍則會吃掉我們。這一切都是光榮的且符合自然規律。$b$b人類和獸人也獵殺我們，但是他們只取走外皮，然後留下軀體任其腐爛。這就是為什麼我們會攻擊人類和獸人。', `MaleText_loc7`='Los azotadores del sur suelen devorar pequeñas criaturas como ranas y loros. Nosotros, los gorilas, nos comemos a los azotadores. Y los dinosaurios se alimentan de nosotros. Todo esto es honorable y natural.$b$bLos humanos y los orcos también cazan a los gorilas, pero se llevan la piel y dejan el cuerpo para que se pudra. Por eso atacamos a los humanos y a los orcos.' WHERE `ID`=38413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지다! 스컬지가 온다!', `MaleText_loc4`='天灾军团！发现目标！', `MaleText_loc5`='天譴軍!來襲!', `MaleText_loc7`='¡LA PLAGA! ¡SE ACERCA!', `FemaleText_loc1`='스컬지에요! 스컬지가 와요!', `FemaleText_loc4`='天灾军团！发现目标！', `FemaleText_loc5`='天譴軍!來襲!', `FemaleText_loc7`='¡LA PLAGA! ¡SE ACERCA!' WHERE `ID`=38414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 감사합니다.', `MaleText_loc4`='我明白了，谢谢你。', `MaleText_loc5`='我了解。謝謝你。', `MaleText_loc7`='Comprendo. Gracias.', `FemaleText_loc1`='알겠어요. 감사합니다.', `FemaleText_loc4`='我明白了，谢谢你。', `FemaleText_loc5`='我了解。謝謝你。', `FemaleText_loc7`='Comprendo. Gracias.' WHERE `ID`=38415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝났다.', `MaleText_loc4`='结束了。', `MaleText_loc5`='完成了。', `MaleText_loc7`='Ya está.' WHERE `ID`=38416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두가 주저앉는 곳을, 너는 넘어섰구나.', `MaleText_loc4`='你赢得了令人胆寒的挑战。', `MaleText_loc5`='當大多數人顫抖退縮時，你卻克服了。', `MaleText_loc7`='Donde muchos fracasarían, tú has vencido.' WHERE `ID`=38417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 직접 안긴 고통을 견뎌냈구나. 이제 어둠한은 네 것이다.', `MaleText_loc4`='你承受住了巫妖王的折磨，现在，影之哀伤是你的了。', `MaleText_loc5`='你抵抗了巫妖王的親手磨難，現在影之哀傷是屬於你了。', `MaleText_loc7`='Has resistido el tormento del mismísimo Rey Exánime y ahora la Agonía de Sombras es tuya.' WHERE `ID`=38418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 떠나라...', `MaleText_loc4`='去吧……', `MaleText_loc5`='現在走吧...', `MaleText_loc7`='Vete...' WHERE `ID`=38419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 강력한 무기를 휘둘러 영혼들을 인도하고 힘을 얻어라.', `MaleText_loc4`='挥舞这强大的武器，指挥那些赋予它力量的灵魂。', `MaleText_loc5`='持舞這把強大的武器並引導那些靈魂來強化它。', `MaleText_loc7`='Blande esta poderosa arma y dirige las almas que le dan poder.' WHERE `ID`=38420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가서, 어둠의 왕자를 물리쳐라.', `MaleText_loc4`='去吧，去战胜黑暗的王子。', `MaleText_loc5`='走吧，去擊敗黑暗王子。', `MaleText_loc7`='Ahora vete y derrota al Príncipe de las Tinieblas.' WHERE `ID`=38421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬에게 사소한 문제일 뿐이라고 전해라. 우리는 길니아스에서 반드시 승리할 것이다.', `FemaleText_loc4`='你要让加尔鲁什知道，这只是一次小小的挫折。我们必将在吉尔尼斯取得胜利。', `FemaleText_loc5`='你可以向卡爾洛斯保證這只是個小小的挫折。我們會在吉爾尼斯取得絕對的勝利。', `FemaleText_loc7`='Dile a Garrosh que esto es sólo un contratiempo menor. Nuestra victoria en Gilneas será absoluta.' WHERE `ID`=38422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말이 거슬리는구나, 장군. 그대나 가로쉬 모두 역병에 대해 걱정할 필요는 없다. 이미 역병을 제조하는 것을 그만둔 지 오래니까. 가로쉬의 허락 없이는 역병을 절대로 사용하지 않을 것이다.', `FemaleText_loc4`='小心说话，将军。你和加尔鲁什都不必担心。我们已经服从他的命令，停止施展危害性魔法。如果没有他的许可，我们绝对不会使用那种魔法。', `FemaleText_loc5`='你最好注意你的語氣，將軍。你或卡爾洛斯都沒什麼好擔心的。我們已經照他的命令全面停止製造瘟疫了。我們絕不會未經他的允許進行散播的。', `FemaleText_loc7`='Será mejor que cuide su tono, General. Ni usted ni Garrosh tienen de qué preocuparse. Se nos ordenó detener la producción de la plaga y lo hicimos. No la desplegaremos sin su permiso.' WHERE `ID`=38423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명예롭게 싸워라, 장군.', `FemaleText_loc4`='荣誉与你同在，将军。', `FemaleText_loc5`='願榮耀與你同行，將軍。', `FemaleText_loc7`='Vaya con honor, General.' WHERE `ID`=38424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 무슨 멍청한 질문인가? 계획한 대로 역병을 퍼뜨려라! 길니아스 놈들이 하찮은 승리를 만끽하도록 놓아두어라. 내일이면 뼈도 못 추릴 테니까.', `FemaleText_loc4`='这算什么问题？我们当然要按照计划施展魔法！就让吉尔尼斯人去享受他们渺小的胜利吧。到明天，他们就连骨头也不会剩下。', `FemaleText_loc5`='這是什麼樣的問題?我們當然是按照計畫散播瘟疫。讓吉爾尼斯人享受他們的小小勝利吧。等到明天，他們連骨頭都不會剩下。', `FemaleText_loc7`='¿Qué clase de pregunta es esa? Claro que desplegaremos la plaga como planeamos. Que los gilneanos disfruten su victoria efímera. Mañana no quedarán ni sus huesos.' WHERE `ID`=38425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스 님, 아무래도 길니아스는 놓치셨나 보군요. 가로쉬 님께서 이 침략 작전을 직접 지휘해야 할지 고민하십니다.', `MaleText_loc4`='你正在失去对吉尔尼斯的控制，希尔瓦娜斯。加尔鲁什担心他恐怕要亲自来指挥这场战争。', `MaleText_loc5`='看來妳正在失去對吉爾尼斯的控制，希瓦娜斯。卡爾洛斯擔心他得親自執行這次的入侵行動。', `MaleText_loc7`='Parece que estás perdiendo el control de Gilneas, Sylvanas. Garrosh siente que tendrá que llevar a cabo esta invasión solo.' WHERE `ID`=38426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신감이 아주 넘치시는군요. 그렇지만 역병을 사용하지는 않으셨으면 합니다. 가로쉬 님께서 분명히 금지한 일이니 말입니다.', `MaleText_loc4`='听起来你很有信心，女王陛下。希望你没有使用伤害性魔法计划。加尔鲁什已严禁使用它。', `MaleText_loc5`='妳聽起來很有信心，陛下。我真心希望妳不打算使用瘟疫。卡爾洛斯很明確的禁止了。', `MaleText_loc7`='Parece muy seguro, su Majestad. Espero que no planee usar la Plaga. Garrosh lo ha prohibido explícitamente.' WHERE `ID`=38427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 지도자님께 그렇게 보고하지요. 이만 가 보겠습니다, 여군주님.', `MaleText_loc4`='那么，我会向我们的领袖报告的。请原谅，我的女士。', `MaleText_loc5`='那我就把報告送去給我們領袖了。先告退了，我的女士。', `MaleText_loc7`='Entonces le daré mi informe a nuestro líder. Con su permiso, mi lady.' WHERE `ID`=38428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마샬의 격전지에 있는 사람들에게 물기 기술을 시험해 보아라.', `MaleText_loc4`='我想让你在马绍尔哨站的敌人身上测试你的撕咬技能。', `MaleText_loc5`='我要你對馬紹爾觀測站的人試驗一下你的撕咬技能。', `MaleText_loc7`='Quiero que utilices tu habilidad Mordedura en la gente del Alto de Marshal.', `FemaleText_loc1`='마샬의 격전지에 있는 사람들에게 물기 기술을 시험해 보아라.', `FemaleText_loc4`='我想让你在马绍尔哨站的敌人身上测试你的撕咬技能。', `FemaleText_loc5`='我要你對馬紹爾觀測站的人試驗一下你的撕咬技能。', `FemaleText_loc7`='Quiero que utilices tu habilidad Mordedura en la gente del Alto de Marshal.' WHERE `ID`=38429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t 인간형 대상 5명에게 물기를 사용하십시오.$B$B|Tinterface\\Icons\\inv_misc_bone_02.blp:32|t 뼈 갑옷을 사용해 방어도를 올리십시오.', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t对5个人形目标使用撕咬技能。$B$B|TInterface\\Icons\\inv_misc_bone_02.blp:32|t使用骨刺护甲提高你的护甲值。', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t對5名人形目標使用撕咬。$B$B|TInterface\\Icons\\inv_misc_bone_02.blp:32|t使用骨甲來提高你的護甲值。', `MaleText_loc7`='|TInterfaceIconsinv_misc_monsterfang_02.blp:32|t Utiliza Mordedura en 5 objetivos humanoides.$B$B|TInterfaceIconsinv_misc_bone_02.blp:32|t Utiliza Armadura huesuda para aumentar tu armadura.', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t 인간형 대상 5명에게 물기를 사용하십시오.$B$B|Tinterface\\Icons\\inv_misc_bone_02.blp:32|t 뼈 갑옷을 사용해 방어도를 올리십시오.', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t对5个人形目标使用撕咬技能。$B$B|TInterface\\Icons\\inv_misc_bone_02.blp:32|t使用骨刺护甲提高你的护甲值。', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:32|t對5名人形目標使用撕咬。$B$B|TInterface\\Icons\\inv_misc_bone_02.blp:32|t使用骨甲來提高你的護甲值。', `FemaleText_loc7`='|TInterfaceIconsinv_misc_monsterfang_02.blp:32|t Utiliza Mordedura en 5 objetivos humanoides.$B$B|TInterfaceIconsinv_misc_bone_02.blp:32|t Utiliza Armadura huesuda para aumentar tu armadura.' WHERE `ID`=38430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역 고릴라와 대화하거라.', `MaleText_loc4`='我希望你和当地的猩猩谈一谈。', `MaleText_loc5`='我要你和原生大猩猩談談。', `MaleText_loc7`='Quiero que hables con los gorilas de la zona.', `FemaleText_loc1`='이 지역 고릴라와 대화하거라.', `FemaleText_loc4`='我希望你和当地的猩猩谈一谈。', `FemaleText_loc5`='我要你和原生大猩猩談談。', `FemaleText_loc7`='Quiero que hables con los gorilas de la zona.' WHERE `ID`=38431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각기 다른 종류의 고릴라와 대화하거라. 고릴라, 우레고릴라, 천둥고릴라와 대화하고 이들의 지식을 습득해야 한다.', `MaleText_loc4`='分别找一只猩猩、大猩猩和巨猩猩谈一谈。$b了解一下他们都会教你一些什么。', `MaleText_loc5`='與大猩猩、安戈洛巨猩猩和安戈洛大猩猩交談，$b學習牠們教你的東西。', `MaleText_loc7`='Habla con cada tipo, gorila, vapuleador y tronador, $by aprende lo que tengan para enseñarte.', `FemaleText_loc1`='각기 다른 종류의 고릴라와 대화하거라. 고릴라, 우레고릴라, 천둥고릴라와 대화하고 이들의 지식을 습득해야 한다.', `FemaleText_loc4`='分别找一只猩猩、大猩猩和巨猩猩谈一谈。$b了解一下他们都会教你一些什么。', `FemaleText_loc5`='與大猩猩、安戈洛巨猩猩和安戈洛大猩猩交談，$b學習牠們教你的東西。', `FemaleText_loc7`='Habla con cada tipo, gorila, vapuleador y tronador, $by aprende lo que tengan para enseñarte.' WHERE `ID`=38432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 날개의 한계를 시험해 보거라.', `MaleText_loc4`='希望你测试一下你的翅膀的极限。', `MaleText_loc5`='我要你測試你翅膀的最大極限。', `MaleText_loc7`='Quiero que pongas a prueba los límites de tus alas.', `FemaleText_loc1`='네 날개의 한계를 시험해 보거라.', `FemaleText_loc4`='希望你测试一下你的翅膀的极限。', `FemaleText_loc5`='我要你測試你翅膀的最大極限。', `FemaleText_loc7`='Quiero que pongas a prueba los límites de tus alas.' WHERE `ID`=38433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀림 위를 높이 날아오르십시오.$b$b테러닥스질주를 사용하면 비행 속도를 일시적으로 증가시킬 수 있습니다.$b$b|Tinterface\\Icons\\ability_druid_dash.blp:32|t', `MaleText_loc4`='飞越这片丛林的树冠。$b$b使用展翼掠飞暂时提高你的飞行速度。$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t', `MaleText_loc5`='飛到叢林樹冠之上$b$b使用翼手猛勁來暫時提高你的飛行速度。$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t', `MaleText_loc7`='Alza el vuelo por encima de la espesura de la selva.$b$bUtiliza Corredáctilo para aumentar temporalmente tu velocidad de vuelo.$b$b|TInterfaceIconsability_druid_dash.blp:32|t', `FemaleText_loc1`='밀림 위를 높이 날아오르십시오.$b$b테러닥스질주를 사용하면 비행 속도를 일시적으로 증가시킬 수 있습니다.$b$b|Tinterface\\Icons\\ability_druid_dash.blp:32|t', `FemaleText_loc4`='飞越这片丛林的树冠。$b$b使用展翼掠飞暂时提高你的飞行速度。$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t', `FemaleText_loc5`='飛到叢林樹冠之上$b$b使用翼手猛勁來暫時提高你的飛行速度。$b$b|TInterface\\Icons\\ability_druid_dash.blp:32|t', `FemaleText_loc7`='Alza el vuelo por encima de la espesura de la selva.$b$bUtiliza Corredáctilo para aumentar temporalmente tu velocidad de vuelo.$b$b|TInterfaceIconsability_druid_dash.blp:32|t' WHERE `ID`=38434;
