UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로 검사관을 다시 소환해 주시겠습니까?', `MaleText_loc4`='你能重新召唤安戈洛测试者吗？', `MaleText_loc5`='可以請你重新召喚這個安戈洛檢驗器嗎?', `MaleText_loc7`='¿Podrías volver a convocar al Examinador de Un''Goro?', `FemaleText_loc1`='운고로 검사관을 다시 소환해 주실 수 있으신가요?', `FemaleText_loc4`='你能重新召唤安戈洛测试者吗？', `FemaleText_loc5`='可以請你重新召喚這個安戈洛檢驗器嗎?', `FemaleText_loc7`='¿Podrías volver a convocar al Examinador de Un''Goro?' WHERE `ID`=38437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운고로 분화구의 식물은 참으로 놀랍기 짝이 없소. 그렇지 않소, $n?', `MaleText_loc4`='安戈洛环形山中的这种花是非常特别的。你说对不对，$n？', `MaleText_loc5`='不可否認地安戈洛環形山的植物還蠻特別的。你說是嗎，$n?', `MaleText_loc7`='La flora del Cráter de Un''Goro es bastante extraordinaria la verdad. ¿No estás de acuerdo, $n?' WHERE `ID`=38438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 있는 수정탑으로 보내주시겠습니까?', `MaleText_loc4`='你能把我传送到上面的水晶塔那儿去吗？', `MaleText_loc5`='你能把我傳送到上方的水晶塔嗎?', `MaleText_loc7`='¿Podrías llevarme a lo alto de la torre?', `FemaleText_loc1`='저 위에 있는 수정탑으로 보내주실 수 있나요?', `FemaleText_loc4`='你能把我传送到上面的水晶塔那儿去吗？', `FemaleText_loc5`='你能把我傳送到上方的水晶塔嗎?', `FemaleText_loc7`='¿Podrías llevarme a lo alto de la torre?' WHERE `ID`=38439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스 님! 제 부하들에게 역병을 퍼뜨리는 것을 멈추라고 해야 합니까? 아니면 계획대로 계속 진행해야 합니까?', `MaleText_loc4`='女王陛下，我是否要命令手下停止部署魔法？或者我们还是按原计划进行？', `MaleText_loc5`='我的女士，我是否該命令手下停止散播瘟疫?還是要按照計畫進行?', `MaleText_loc7`='Mi señora, ¿les ordeno a mis hombres que detengan el uso de la plaga? ¿O seguiremos con el plan?' WHERE `ID`=38440;
