UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 이곳에 머무르는 동안, 쿠엘델라는 계속 사악함을 흡수한다네.', `MaleText_loc4`='只要你留在这里，奎尔德拉就会汲取这里的邪能。', `MaleText_loc5`='你在此的每一秒，奎爾德拉都在吸取這裡的邪惡。', `MaleText_loc7`='Cada segundo que se demoren, Quel''Delar bebe del mal de este lugar.' WHERE `ID`=38442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전과 똑같지 않아, $n?', `MaleText_loc4`='就像过去一样，对不对， $n？', `MaleText_loc5`='像以往一樣，是吧，$n?', `MaleText_loc7`='Como en los viejos tiempos, ¿eh, $n?' WHERE `ID`=38443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전과 똑같지 않아, $n?$B$B지금은 그리 바쁘지 않으니 자네를 훈련할 수 있어. 여기 있는 놈들은 너무 물러 터졌다고.', `MaleText_loc4`='就像过去一样，对不对，$n？$B$B我不算很忙，可以训练你。这些家伙都还不错。', `MaleText_loc5`='像以往一樣，是吧，$n?$B$B我還不會太忙，可以訓練你。這些傢伙還不賴。', `MaleText_loc7`='Como en los viejos tiempos, ¿eh, $n? No estoy demasiado ocupado para instruirte. Esos tipos son unos bocaditos de crema.' WHERE `ID`=38444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 도와달라니까?', `MaleText_loc4`='有人愿意帮忙吗？', `MaleText_loc5`='需要幫忙嗎?', `MaleText_loc7`='¿Un poco de ayuda?' WHERE `ID`=38445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 도와주겠어? 훈련을 더 받고 싶어, $n?$B$B눈치 못 챘나 본데, 지금 좀 바쁘거든.', `MaleText_loc4`='有人愿意帮忙吗？还是你需要更多训练，$n？$B$B不知你是否注意到，我现在很忙。', `MaleText_loc5`='需要幫忙嗎?或是你需要一些訓練，$n?$B$B如果你還未注意到的話，我現在可是挺忙的。', `MaleText_loc7`='¿Un poco de ayuda aquí? ¿O es que necesitas más instrucción, $n?$B$BPor si no te has dado cuenta, estoy bastante ocupado ahora mismo.' WHERE `ID`=38446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 좀 도와주겠어? 나한테 마나가 무한정 있는 건 아냐.', `MaleText_loc4`='你能帮帮我吗？我的法力是有限的。', `MaleText_loc5`='你能幫忙一下嗎?我可沒有無限的法力。', `MaleText_loc7`='¿Podrías ayudarme con esto? No tengo maná ilimitado.' WHERE `ID`=38447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 좀 도와주겠어? 나한테 마나가 무한정 있는 건 아냐.$B$B물론, 훈련이 필요하다면...', `MaleText_loc4`='你能帮帮我吗？我的法力是有限的。$B$B当然，如果你需要一些训练……', `MaleText_loc5`='你能幫忙一下嗎?我可沒有無限的法力。$B$B當然了，如果你需要一點訓練...', `MaleText_loc7`='¿Podrías ayudarme con esto? No tengo maná ilimitado.' WHERE `ID`=38448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 그럭저럭 괜찮아 보여. 팔 힘 좀 쓸 일이 있는데.$B$B일거리를 찾는다고 하지 않았어, $n?', `MaleText_loc4`='这个地方看上去很不错。只是需要进行一下清洁。$B$B你在找工作吗，$n？', `MaleText_loc5`='這地方看起來還可以，應該吧。我需要一些勞力。$B$B你不是需要一份工作嗎，$n?', `MaleText_loc7`='Supongo que este lugar no está mal. Aunque habrá que trabajar duro.$B$B¿Buscas trabajo $n?' WHERE `ID`=38449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 것들은 정말 골칫거리야!', `MaleText_loc4`='这些如芒在背的小混蛋！', `MaleText_loc5`='我對這些小東西非常頭痛!', `MaleText_loc7`='¡Pero qué incordio que son estos pequeñajos!' WHERE `ID`=38450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조그만 것들은 정말 골칫거리야!$B$B어쨌거나, 훈련이 좀 필요하다고?', `MaleText_loc4`='这些如芒在背的小混蛋！$B$B你需要训练吗？', `MaleText_loc5`='我對這些小東西非常頭痛!$B$B所以，你需要一些訓練嗎?', `MaleText_loc7`='¡Pero qué incordio que son estos pequeñajos!$b$b¿Qué, necesitas instrucción?' WHERE `ID`=38451;
