UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소인족 때문에 수입이 자꾸 준답니다!$B$B$n 님, 깨달음에 관심이 있으신가요?', `FemaleText_loc4`='这些俾格米人减少了我的利润！$B$B在寻求教导吗，$n？', `FemaleText_loc5`='那些俾格米使利潤減少了!$B$B尋求啟示嗎，$n?', `FemaleText_loc7`='¡Estos pigmeos están afectando a mis beneficios!$b$b¿Buscas iluminación, $n?' WHERE `ID`=38453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동작이 뛰어나군요, $n 님. 이제 그 동작을 이용하세요!', `FemaleText_loc4`='你已经掌握了诀窍，$n。尽量使用它们！', `FemaleText_loc5`='你可以採取行動了，$n。使用它們!', `FemaleText_loc7`='Dominas la técnica, $n. ¡Utilízala!' WHERE `ID`=38454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동작이 뛰어나군요, $n 님. 이제 그 동작을 이용하세요!$B$B그게 아니라면, 다른 새 동작을 찾아보시는 건가요?', `FemaleText_loc4`='你已经掌握了诀窍，$n。尽量使用它们！$B$B你还想知道一些新的诀窍吗？', `FemaleText_loc5`='你可以採取行動了，$n。現在快點使用它們!$B$B還是你在等待其他機會?', `FemaleText_loc7`='Dominas la técnica, $n. ¡Utilízala!$b$b¿O prefieres aprender una nueva?' WHERE `ID`=38455;
