UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01이 작동 중입니다.$B$B훈련을 더 받으려면 동전을 넣어 주십시오.', `MaleText_loc4`='全能战士NX-01型联线运行中！$B$B塞进钱币，获取更多训练。', `MaleText_loc5`='自動戰士NX-01已上線。$B$B請投幣以進行更多訓練。', `MaleText_loc7`='Guerreromática NX-01 conectada.$B$BInserta monedas para recibir más instrucción sobre cómo dar órdenes.' WHERE `ID`=38457;
