UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형편없는 첩보원 같으니. 만약 네가 머리라 부르는 그 텅 빈 곳에 정보가 조금이라도 있었다면, 지금쯤은 이미 털어놓았을 게다. 이런 일은 이제 싫증이 난다. 사라져라!', `FemaleText_loc4`='没用的间谍，如果那个空壳，也就是你所谓的脑袋，真装了那么一点儿情报的话，你早已经招了。我受够这一套了。现在去死吧！', `FemaleText_loc5`='沒用的間諜，如果那個你叫做顱骨的中空容器中有任何一丁點的資訊，你最好現在乖乖講出來。我厭倦這些練習了。現在去死!', `FemaleText_loc7`='Inmundo espía, si en ese recipiente vacío al que llamas cráneo hubiera algo de información, ya la habrías escupido. Me canso de este ejercicio. ¡Ahora, muere!' WHERE `ID`=38462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $r $c 이야기 들어본 적 있어? 자, 들어봐.$b$b$r $c|1이;가; 동굴로 들어가 고릴라와 싸우기 시작했어. 그러자 고릴라의 우두머리가 물었지, "이봐, 대체 왜 그러는 거야?!" 그러자 $r $c|1이;가; "고블린이 그러라고 했어."하고 답했어.$b$b그래서 고릴라 우두머리가 "넌 고블린이 하란다고 정말 하냐?"라고 물으니 $r $c|1이;가; 답했다지. "응, 왜냐면 난 바보에다 냄새도 나고 두 발로 걸어 다니거든."$b$b꽤 재미있지, 응? 흠... 이야기를 좀 다듬어야겠군...', `MaleText_loc4`='嗨，你听过那个关于$r$c的故事么？事情是这样的：$b$b一个$r$c走进一座洞穴，开始和猩猩战斗。那群猩猩的头领说：“嘿，你为什么要这么干？！”那个$r$c就说：“是一个地精让我这么干的。”$b$b猩猩头领说：“地精让你干什么，你就干什么？”$r$c回答：“是的，因为我很笨，浑身臭气，而且还用两条腿走路。”$b$b很有趣，对不对？嗯……也许还需要再做些加工……', `MaleText_loc5`='嘿，你曾聽過有關$r $c的事嗎?好，是這樣的: $b$b有一名$r $c走進一個洞穴內跟大猩猩打了起來。大猩猩的首領說:「嘿，你為什麼要這麼做?!」這名$r $c說:「一名哥布林叫我這麼做的。」$b$b大猩猩的首領問道:「你會做那名哥布林叫你做的每一件事嗎?」這名$r $c回答說:「會的，因為我又傻又臭，而且我以雙腳走路。」$b$b很好笑對吧?嗯...或許還需要再修改一下...', `MaleText_loc7`='Eh, ¿conoces el $gdel:de la; $r $c? Vale, allá va:$b$b$gUn:Una; $r $c entra en una cueva y empieza a pelear con gorilas. El líder de los gorilas dice: "Eh, ¡¿por qué lo haces?!" Así que $gel:la; $r $c contesta: "Un goblin me dijo que lo hiciera."$b$bEntonces el líder gorila replica: "¿Es que haces todo lo que te dicen los goblins?" Y $gel:la; $r $c dice: "Sí, porque soy idiota, apesto y camino sobre dos piernas."$b$bTiene gracia, ¿verdad? Hmm... quizá tenga que trabajar un poco en él...' WHERE `ID`=38463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 힘으로!', `MaleText_loc4`='以巫妖王的力量为名！', `MaleText_loc5`='以巫妖王之力!', `MaleText_loc7`='¡POR EL PODER DEL REY EXÁNIME!' WHERE `ID`=38464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 여기까지 오긴 했는데, 이제 그 견본을 어떻게 손에 넣지?', `FemaleText_loc4`='哦，我已经做了这么多了，现在，我怎么才能拿到那些样本呢…？', `FemaleText_loc5`='嗯，都已經走到了這一步，但我現在該拿什麼來裝這些樣本呢...?', `FemaleText_loc7`='Hmm, bueno, he llegado hasta aquí, ¿pero cómo voy a conseguir hacerme con esas muestras...?' WHERE `ID`=38465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들아, 배불리 먹어라!', `MaleText_loc4`='吃吧，奴仆们！', `MaleText_loc5`='吃吧，我的爪牙們!', `MaleText_loc7`='¡Comed, mis esbirros!' WHERE `ID`=38466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운고로 분화구는 매우 구체적인 목적을 위해 존재한다, $n. 이제 네가 그 목적을 알아야 할 때다.', `FemaleText_loc4`='安戈洛环形山的存在有其特殊的意图，$n。现在该是你知道这个意图的时候了。', `FemaleText_loc5`='安戈洛環形山有個非常特殊的用途，$n。是時候去了解一下那個用途是什麼。', `FemaleText_loc7`='El Cráter de Un''Goro tiene un propósito muy concreto, $n. Ha llegado el momento de que sepas cuál es.' WHERE `ID`=38467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에엑!', `MaleText_loc4`='呃！', `MaleText_loc5`='呃!', `MaleText_loc7`='¡Ay!' WHERE `ID`=38468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 이런, 이게 누구지...? 비밀을 많이 아는 놈인가 보구나...', `FemaleText_loc4`='好吧、好吧，看看我们都发现什么了…？你一定知道不少秘密……', `FemaleText_loc5`='喔，嗯嗯，瞧瞧我們這裡有了什麼...?你一定知道很多秘密...', `FemaleText_loc7`='Bueno, bueno, ¿qué tenemos aquí...? Debes de conocer muchos secretos...' WHERE `ID`=38469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까?', `MaleText_loc4`='你是谁？', `MaleText_loc5`='你是誰?', `MaleText_loc7`='¿Quién eres?', `FemaleText_loc1`='당신은 누구신가요?', `FemaleText_loc4`='你是谁？', `FemaleText_loc5`='你是誰?', `FemaleText_loc7`='¿Quién eres?' WHERE `ID`=38470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭘 하시는 겁니까?', `MaleText_loc4`='你在这里干什么？', `MaleText_loc5`='你在這裡做什麼?', `MaleText_loc7`='¿Qué haces aquí?', `FemaleText_loc1`='여기서 뭘 하시는 건가요?', `FemaleText_loc4`='你在这里干什么？', `FemaleText_loc5`='你在這裡做什麼?', `FemaleText_loc7`='¿Qué haces aquí?' WHERE `ID`=38471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실험이라니? 어떤 실험입니까?', `MaleText_loc4`='测试？什么测试？', `MaleText_loc5`='測試?什麼樣的測試?', `MaleText_loc7`='¿Pruebas? ¿Qué clase de pruebas?', `FemaleText_loc1`='실험이라니? 어떤 실험입니까?', `FemaleText_loc4`='测试？什么测试？', `FemaleText_loc5`='測試?什麼樣的測試?', `FemaleText_loc7`='¿Pruebas? ¿Qué clase de pruebas?' WHERE `ID`=38472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카즈고로스 님의 창조물이라고요? 그 말은 이 분화구의 모든 생물체가 카즈고로스의 창조물이라는 겁니까?', `MaleText_loc4`='卡兹格罗斯创造的？你说这座环形山里的全部生物都是卡兹格罗斯创造的？', `MaleText_loc5`='他的作品?你是說這個環形山裡的所有生物都是卡茲格羅斯的作品?', `MaleText_loc7`='¿Sus creaciones? ¿Dices que todas las criaturas del cráter son creaciones de Khaz''goroth?', `FemaleText_loc1`='카즈고로스 님의 창조물이라고요? 그 말은 이 분화구의 모든 생물체가 카즈고로스의 창조물이라는 건가요?', `FemaleText_loc4`='卡兹格罗斯创造的？你说这座环形山里的全部生物都是卡兹格罗斯创造的？', `FemaleText_loc5`='他的作品?你是說這個環形山裡的所有生物都是卡茲格羅斯的作品?', `FemaleText_loc7`='¿Sus creaciones? ¿Dices que todas las criaturas del cráter son creaciones de Khaz''goroth?' WHERE `ID`=38473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이런 걸 알려주시는 겁니까?', `MaleText_loc4`='为什么你要告诉我这些？', `MaleText_loc5`='你為什麼要跟我說這些?', `MaleText_loc7`='¿Por qué me estás contando todo esto?', `FemaleText_loc1`='왜 이런 걸 알려주시는 건가요?', `FemaleText_loc4`='为什么你要告诉我这些？', `FemaleText_loc5`='你為什麼要跟我說這些?', `FemaleText_loc7`='¿Por qué me estás contando todo esto?' WHERE `ID`=38474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나블리아, 궁금한 게 있습니다... 혹시 카즈고로스가 저와 제 종족 모두를 창조했습니까?', `MaleText_loc4`='娜博亚，我必须问的是……我和我的种族是卡兹格罗斯创造的吗？', `MaleText_loc5`='娜畢雅，我必須問...是卡茲格羅斯創造了我和我的同類嗎?', `MaleText_loc7`='Nablya, debo preguntar... ¿Fue Khaz''goroth el que nos creó a mí y al resto de mi raza?', `FemaleText_loc1`='나블리아, 궁금한 게 있습니다... 혹시 카즈고로스가 저와 제 종족 모두를 창조했는지요?', `FemaleText_loc4`='娜博亚，我必须问的是……我和我的种族是卡兹格罗斯创造的吗？', `FemaleText_loc5`='娜畢雅，我必須問...是卡茲格羅斯創造了我和我的同類嗎?', `FemaleText_loc7`='Nablya, debo preguntar... ¿Fue Khaz''goroth el que nos creó a mí y al resto de mi raza?' WHERE `ID`=38475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 나블리아.', `MaleText_loc4`='谢谢你，娜博亚。', `MaleText_loc5`='謝謝你，娜畢雅。', `MaleText_loc7`='Gracias, Nablya.', `FemaleText_loc1`='감사합니다, 나블리아.', `FemaleText_loc4`='谢谢你，娜博亚。', `FemaleText_loc5`='謝謝你，娜畢雅。', `FemaleText_loc7`='Gracias, Nablya.' WHERE `ID`=38476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 나블리아, 카즈고로스 님의 제자이자 운고로 분화구의 사절이다. 감시자로도 알려져 있지.$b$b난 아제로스를 떠난 스승님을 대신해 여길 지키는 중이다. 여기 이 자리가 스승님이 수많은 창조물을 만드신 바로 그곳이지.', `FemaleText_loc4`='我是娜博亚，卡兹格罗斯的弟子，安戈洛环形山的使者。我也被称为观察者。$b$b自从我的导师离开艾泽拉斯之后，我就是他的代表。他就是在这里塑造了许多生物。', `FemaleText_loc5`='我是娜畢雅，是卡茲格羅斯的學徒，以及安戈洛環形山的使者。我被稱作看守者。$b$b自從我主人離開艾澤拉斯後，我便佇立於我主人之前所站之處。他在創造眾多生物時就是站在這個位置。', `FemaleText_loc7`='Soy Nablya, aprendiza de Khaz''goroth y estoy destinada en el Cráter de Un''Goro. Me conocen como Nablya la Observadora.$b$bOcupo el lugar de mi maestro desde que abandonó Azeroth. Una vez él estuvo en este mismo lugar, cuando dio forma a muchas de sus creaciones.' WHERE `ID`=38477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 관찰 중이다. 여기서 운고로를 감시하는 게 내 일이지.$b$b그와 동시에 실험을 하고 그 결과를 기록하기도 한다. 이 실험을 통해 내 흥미를 끄는 걸 관찰할 수 있지.', `FemaleText_loc4`='我在观察。看护安戈洛就是我的职责。这里就是我观察的位置。$b$b我还会进行测试，并记录测试结果。这些测试让我能够观察最令我感兴趣的事物。', `FemaleText_loc5`='我正在觀察。看管安戈洛環形山是我的職責，我就站在這裡守著這一切。$b$b我同時也會執行試驗，並且將試驗結果記錄下來。這些試驗讓我能觀察我最感興趣的事物。', `FemaleText_loc7`='Estoy observando. Es mi deber vigilar Un''Goro, y lo hago desde este lugar.$b$bTambién hago pruebas y tomo nota de los resultados. Esas pruebas me permiten observar aquello que más me interesa.' WHERE `ID`=38478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='단순한 자극과 반응 실험이지. 일반적으로 우리 종족은 아제로스의 일에 개입하지 않는다. 하지만 여기 운고로에서는 더 직접적으로 접근하는 게 허용되지. 운고로는 티탄에게 있어 실험이 자유로운, 실험의 땅이라 할 수 있다.$b$b예를 들어, 카즈고로스 님의 창조물 중 하나가 유황 온천에 노출되었을 때 어떤 반응을 일으키는지 알고 싶다면 수천 년을 기다리면서 관찰하는 것도 방법이고, 그 생명체가 실수로 온천에 빠질 때까지 기다리는 것도 방법이지. 아니면 단순히 그 생명체를 물에 직접 넣어보는 방법도 있고...$b$b운고로에선 후자의 방법을 쓴다.', `FemaleText_loc4`='简单的刺激——响应测试。一般来说，我们不会干扰艾泽拉斯的运转。但在安戈洛，我们可以自由地使用更加直接的手段，因为安戈洛是泰坦的试验场。$b$b比如说，卡兹格罗斯想要知道，当他创造的一种生物被暴露在硫磺热泉中的时候，会有怎样的变化。他可以等待千万年，观察，等待这种生物在偶然间跌落入热泉——或者他或许亲手将这种生物放进热泉中。$b$b在安戈洛，我们就能这么做。', `FemaleText_loc5`='像是一些簡單的刺激反應測試。通常我族是不會干擾艾澤拉絲的事物，但是在安戈洛環形山中我們可以自由地採取較為直接的手段。安戈洛環形山是泰坦們的實驗場，我們有權利如此做。$b$b舉例來說，當卡茲格羅斯想了解他的其中一個創造物遇到硫磺熱泉會有什麼反應的時候，他可以花上千年，觀察並等待這個生物不小心地踩進且跌入。或者他可以自己將這個生物放入水裡。$b$b在安戈洛環形山的話我們就能這樣做。', `FemaleText_loc7`='Simples pruebas de estímulo-respuesta. Normalmente, mi gente no suele interferir en los asuntos de Azeroth, pero en Un''Goro tenemos libertad para emprender una acción más directa. Como Un''Goro es el campo experimental de los Titanes, tenemos derecho a hacerlo.$b$bPor ejemplo, imagina que Khaz''goroth quiere saber qué ocurre cuando una de sus creaciones es expuesta a un manantial sulfuroso. Podría esperar milenios, observando y esperando a que una de las criaturas cayera accidentalmente en una. O, podría colocar a la criatura en el agua él mismo.$b$bEn Un''Goro es lo que hacemos.' WHERE `ID`=38479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼭 그런 건 아니다. 사실, 이 분화구의 많은 생물체는 주인님이 오시기 전부터 존재했다... 하지만 어떤 생물체는 주인님이 만드셨지.$b$b하지만 우린 모든 생물체를 아무 편견 없이 관찰한다.', `FemaleText_loc4`='不尽然。事实上，这座环形山中的许多生物在我的导师到来之前就已经存在了……$b$b无论是否由我的导师亲手创造，我都对它们进行绝对客观的观察。', `FemaleText_loc5`='也不完全是如此。事實上，安戈洛環形山中有許多生物早在我主人到來前就已經存在了...而有些不是。$b$b儘管如此，我們會不帶偏見地觀察所有生物。', `FemaleText_loc7`='No exactamente. De hecho, muchas de las criaturas de este cráter ya existían mucho antes de la llegada de mi maestro... pero otras no.$b$bSea como sea, nosotros las observamos todas, sin prejuicios.' WHERE `ID`=38480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 아제로스를 휩쓸었을 때, 이 정원을 숨겨주었던 은폐 효과가 해제되었다. 그 순간부터, 지성을 가진 종족이 날 발견하는 건 시간문제였지.$b$b솔직히 이건 우리도 예측하지 못한 상황이었다. 이 때문에 새로운 시험이 필요해진 거다. 그리고 $n, 바로 네가 그 실험을 수행할 거다.', `FemaleText_loc4`='当大灾变肆虐艾泽拉斯的时候，也打破了保证这一地区处于隐藏状态的屏蔽系统。如此一来，具有智慧的种族发现我就只是时间问题了。$b$b老实说，我们此前并未预见过这种情况。所以现在，我们需要进行一些新的测试。而你，$n，就是我的测试对象。', `FemaleText_loc5`='當大災變降臨艾澤拉斯時，把讓這區域保持隱密的庇護機關給摧毀了。因為這樣，聰明的種族在這找到我只是遲早的事。$b$b這個狀況...老實說...是我們未所預料的。因此，新的實驗和測試是必要的，而你，$n，就是我的實驗品。', `FemaleText_loc7`='Cuando el Cataclismo desgarró Azeroth, anuló el mecanismo de invisibilidad que ocultaba esta terraza. Llegados a ese punto, era cuestión de tiempo que las razas inteligentes me descubrieran.$b$bEsta es una situación que, para ser honestos, no previmos. Tuvimos que realizar algunas pruebas nuevas. Y tú, $n, eres mi conejillo de indias.' WHERE `ID`=38481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 그 질문에 답할 권리가 없다. 하지만, 조언해줄 수는 있지.$b$b브란 브론즈비어드를 찾아보아라.$b$b그는 이미 우리에 대해 많은 걸 알고 있을뿐더러 새로운 발견을 눈앞에 두고 있지. 브란 브론즈비어드를 돕는다면 분명 네가 원하는 지식을 구하는 데 도움이 될 것이다.', `FemaleText_loc4`='我没有权限回答这个问题。但我可以向你提供一个建议：$b$b找到布莱恩·铜须。$b$b他已经掌握了许多关于我们的线索。而且现在他即将有一个新的发现。帮助他，他也许就能帮助你找到你所需要的知识。', `FemaleText_loc5`='我未被授權回答那個問題，但提供建議是允許的:$b$b去找布萊恩·銅鬚。$b$b他已經學習到很多與我們相關的一切，而且馬上就會擁有新的發現。幫助他，他或許便可以幫助你尋找你想知道的答案。', `FemaleText_loc7`='No estoy autorizada a contestar esa pregunta. Sin embargo, se me permite hacerte una sugerencia:$b$bBusca a Brann Barbabronce.$b$bÉl ya sabe mucho sobre nosotros y está al borde de hacer otro descubrimiento. Ayúdale, y quizá él te ayude a descubrir el conocimiento que anhelas.' WHERE `ID`=38482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스를 되찾을 때가 다가왔습니다.', `MaleText_loc4`='夺回吉尔尼斯城的时刻已经到了。', `MaleText_loc5`='奪回吉爾尼斯城的時刻即將到來。', `MaleText_loc7`='Ya es la hora de recuperar la Ciudad de Gilneas.' WHERE `ID`=38483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 이제 우리 도시를 되찾을 때입니다!', `MaleText_loc4`='让我们夺回我们的城市！', `MaleText_loc5`='讓我們奪回我們的城市!', `MaleText_loc7`='¡Recuperemos nuestra ciudad!', `FemaleText_loc1`='맞아요! 이제 우리 도시를 되찾을 때가 왔어요!', `FemaleText_loc4`='让我们夺回我们的城市！', `FemaleText_loc5`='讓我們奪回我們的城市!', `FemaleText_loc7`='¡Recuperemos nuestra ciudad!' WHERE `ID`=38484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리암!! 안 돼!!', `MaleText_loc4`='利亚姆！！不！！', `MaleText_loc5`='黎姆!!不要!!', `MaleText_loc7`='¡¡LIAM!! ¡¡¡NO!!!' WHERE `ID`=38485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 사로잡고 말았군요!', `MaleText_loc4`='终于，来了个看客！', `MaleText_loc5`='終於，逮到了一個觀眾!', `MaleText_loc7`='¡Por fin, un público atento!' WHERE `ID`=38486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포식자가 기다립니다...', `MaleText_loc4`='吞噬者在等待着…', `MaleText_loc5`='吞噬者在等著你...', `MaleText_loc7`='El Devorador espera...' WHERE `ID`=38487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 소용돌이가 손짓하지 않습니까!', `MaleText_loc4`='死亡的漩涡在召唤你！', `MaleText_loc5`='攫取靈魂的漩渦在呼喚你!', `MaleText_loc7`='¡El vórtice de la destrucción te llama!' WHERE `ID`=38488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸과 영혼을 분리해 드리지요.', `MaleText_loc4`='我会剥下你低贱的灵魂！', `MaleText_loc5`='我將把你的靈魂從肉體剝離!', `MaleText_loc7`='¡Separaré tu alma de tu cuerpo!' WHERE `ID`=38489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련할 때 써 드리겠습니다.', `MaleText_loc4`='去注满引擎吧。', `MaleText_loc5`='引擎的燃料。', `MaleText_loc7`='Combustible para el motor.' WHERE `ID`=38490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 영혼이 힘을 더하는군요!', `MaleText_loc4`='又是一个属于我们的灵魂！', `MaleText_loc5`='另一個強化眾魂之主的靈魂!', `MaleText_loc7`='¡Otra alma para fortalecer al anfitrión!' WHERE `ID`=38491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 흉터를 봉인하겠습니다, $n. 다른 쪽에서 아무것도 들어오지 않도록 해주십시오!', `MaleText_loc4`='我会尝试封住这道伤疤，$n。绝不让它另一侧的怪物们再钻过来！', `MaleText_loc5`='我會試著把這道痕封起來，$n。確保沒有任何東西能從另一邊來到這裡!', `MaleText_loc7`='Intentaré sellar la cicatriz, $n. ¡Asegúrate de que no pase nada desde el otro lado!' WHERE `ID`=38492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스는 승리할 것이다!', `MaleText_loc4`='吉尔尼斯必将复兴。', `MaleText_loc5`='勝利屬於吉爾尼斯!', `MaleText_loc7`='¡Gilneas prevalecerá!' WHERE `ID`=38493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 이제 끝장이다! 포세이큰 쓰레기들아!', `MaleText_loc4`='你们的时代结束了，被遗忘者！', `MaleText_loc5`='你的時間到了，不死族雜碎!', `MaleText_loc7`='¡Se acaba su tiempo, escoria Renegada!' WHERE `ID`=38494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!', `MaleText_loc4`='进攻！', `MaleText_loc5`='衝啊!', `MaleText_loc7`='¡Ataquen!' WHERE `ID`=38495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들을 몰아내라!', `MaleText_loc4`='将他们击退！', `MaleText_loc5`='把他們擊退!', `MaleText_loc7`='¡Hagan que retrocedan!' WHERE `ID`=38496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 네가 나를 죽음보다 더한 운명에서 구했구나. 그들 장치를 내버려두었다면, 리치 왕의 마술사들이 점점 내 의지를 꺾고 언데드라는 영원한 저주에 빠뜨렸으리라. 네 앞에는 그리 운이 나쁜 존재가 있다. 한때는 말리고스의 자랑스러운 배우자였던 신드라고사 말이다.$B$B넬타리온이 배신한 다음 심한 상처를 입고 얼음왕관의 눈 속에서 혼자 죽도록 버려졌다가, 지금은 순전한 증오의 화신으로 존재할 뿐이다. 그러나 그 겹겹이 쌓인 사악함 아래에는 용 여왕의 숭고한 영혼이 아직 남아 있다. 나는 아직 신드라고사의 영혼이 평화로운 안식을 취할 수 있는 희망이 있다고 믿는다.', `FemaleText_loc4`='凡人们，你们将我从那比死亡更可怕的厄运中拯救了出来。如果继续困在那些设备中，我的意志迟早会被巫妖王的巫师们摧毁，我的身体也将遭受永恒的折磨。在你们面前的便是荣耀一时的辛达苟萨——玛里苟斯的配偶。$B$B奈萨里奥的背叛使她受到了致命的创伤，躺在冰冠冰川的积雪中孤独的等待死亡，现在的她完全被仇恨所充斥。然而，恶意之下仍存留着龙之女王的高尚灵魂。我相信辛达苟萨的灵魂还有机会回归安宁。', `FemaleText_loc5`='凡人，你拯救了我免於比死亡更悽慘的命運。靠著那些裝置，巫妖王手下的巫士最終能摧毀我的意志，讓我落入受盡折磨的永恆不死中。在你前方的則是另一個沒那麼幸運的存在:曾是瑪里苟斯驕傲配偶的辛德拉苟莎。$B$B她在奈薩里奧的背叛中受到了致命的傷勢，留在寒冰皇冠的霜雪中等待自己的死亡，如今她的存在只剩下全然的仇恨。然而，在那層層惡毒之下，依舊留存著一個龍后的高貴靈魂。我相信辛德拉苟莎的靈魂依舊有希望能獲得安息。', `FemaleText_loc7`='Mortales, me han salvado de un destino peor que la muerte. De haber continuado, los hechiceros del Rey Exánime habrían quebrado mi voluntad y me habrían condenado a una vida de no-muerte. Ante ustedes yace una que no tuvo tanta suerte: la otrora orgullosa consorte de Malygos, Sindragosa.$B$BHerida de muerte tras la traición de Neltharion y abandonada para morir sola en la nieve de Corona de Hielo, ahora es un ser de odio puro. Y aun así, bajo todas esas capas de maldad todavía se encuentra el noble espíritu de una reina de los dragones. Creo que todavía hay esperanza de que el alma de Sindragosa pueda descansar en paz.' WHERE `ID`=38497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF7F00숨막히는 가스탄|r을 시전합니다!', `MaleText_loc4`='%s施放了|cFFFF7F00窒息毒气弹！|r', `MaleText_loc5`='%s施展|cFFFF7F00窒息毒氣彈!|r', `MaleText_loc7`='¡%s lanza |cFFFF7F00Bomba de gas asfixiante!|r' WHERE `ID`=38498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s|1이;가; |cFF00FF00유연한 끈적이|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s施放了|cFF00FF00可延展黏液！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s施展|cFF00FF00延展黏液!|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_herb_evergreenmoss.blp:16|t ¡%s lanza |cFF00FF00Moco maleable!|r' WHERE `ID`=38499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안정한 실험을 시작합니다!', `MaleText_loc4`='%s开始施放不稳定的实验！', `MaleText_loc5`='%s開始施展不穩定的實驗!', `MaleText_loc7`='¡%s comienza a lanzar Experimento inestable!' WHERE `ID`=38500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교수 퓨트리사이드가 |cFF00FF00유연한 끈적이|r를 시전합니다!', `MaleText_loc4`='普崔塞德教授施放了|cFF00FF00可延展黏液！|r', `MaleText_loc5`='普崔希德教授施展|cFF00FF00延展黏液!|r', `MaleText_loc7`='¡Profesor Putricidio lanza|cFF00FF00Moco maleable!|r' WHERE `ID`=38501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일을 방해하게 둘 순 없어! 이크, 저놈들을 처리해!', `MaleText_loc4`='我们的工作绝不能被干扰！伊克，招呼他们！', `MaleText_loc5`='我們的工作不能受到干擾!艾克，去處理他們!', `MaleText_loc7`='¡Nuestro trabajo no debe ser interrumpido! ¡Agh, ocúpate de ellos!' WHERE `ID`=38502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부분은 아마 쓸모가 있을 거야.', `MaleText_loc4`='这些部件也许对我们有用。', `MaleText_loc5`='我們或許可以用上這些零件。', `MaleText_loc7`='Estas partes podrían servirnos.' WHERE `ID`=38503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔과 다리가 부족해! 네가 보태준다니 고마워!', `MaleText_loc4`='我们正缺胳膊和腿呢！感谢你们的大力援助！', `MaleText_loc5`='手臂和腿有點短缺!感謝你們的貢獻!', `MaleText_loc7`='¡Necesitamos brazos y piernas! ¡Gracias por la contribución!' WHERE `ID`=38504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 저놈! 저놈이야! 저놈 잡아!', `MaleText_loc4`='不，是那个！那个！就是他！', `MaleText_loc5`='不，那個!那個!抓住那一個!', `MaleText_loc7`='¡No, ése! ¡Ése! ¡Trae ése!' WHERE `ID`=38505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 바뀌었어, 대신 저놈을 잡아!', `MaleText_loc4`='我改主意了，现在我要的是这个！', `MaleText_loc5`='我改變心意了，換成那個傢伙!', `MaleText_loc7`='Cambié de idea, ¡mejor ése!' WHERE `ID`=38506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그놈을 공격해? 더 위험한 놈은 저기 있는데! 이 바보!', `MaleText_loc4`='你打这个家伙干什么？真正危险的人在那儿，傻子！', `MaleText_loc5`='你攻擊那個傢伙做什麼?危險的是在那邊!', `MaleText_loc7`='¿Para qué lo atacas a él? ¡El peligroso es aquel de allí, imbécil!' WHERE `ID`=38507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들아, 이건 시작이자 끝이다. 주인님의 성소에는 아무도 들어갈 수 없다!', `MaleText_loc4`='这就是你们的开始与终结之地，凡人们。休想进入主人的密室！', `MaleText_loc5`='這是起點也是終點，凡人。沒有人能進入我主的聖所!', `MaleText_loc7`='Este es el principio Y el fin, mortales. ¡Nadie puede entrar en el sagrario del amo!' WHERE `ID`=38508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r|1이여;여;. 제가 여기 있는 게 좀 혼란스러우신 듯하군요. 다른 이들도 제게 의심을 품곤 합니다. 제 형제들이 그들에게 고초를 안겼으니, 그들을 탓할 순 없지요.$B$B태양샘에서 사건이 벌어진 이후 많은 일이 일어났고, 좋은 일은 거의 없었습니다. 그리고 전 모든 일을 바로잡고, 제가 속한 용군단의 자긍심을 회복하려고 애쓰고 있습니다. 할 말도, 할 일도 많지만 이것만은 알아 주셨으면 합니다. 아제로스에 일어난 문제에 대해 푸른용군단의 모두가 필멸의 종족을 탓하는 건 아니라는 사실을요.$B$B우리 중 일부는 그보다는 분별이 있습니다.', `MaleText_loc4`='你好，$r。我察觉到你对我出现在这里感到困惑。其他人也心存怀疑，不过鉴于我的同胞给他们带来的遭遇，我并不怪他们。$B$B太阳之井事件后发生了很多事，几乎没有一样是好事。我着手开始收拾残局，希望能挽救我此行带来的影响。要说的很多，要做的更多，不过记住这一点：不是蓝龙军团的每个成员都责怪艾泽拉斯的凡人给这个世界带来的祸患。$B$B我们中的某些成员对此有着更深的理解。', `MaleText_loc5`='你好，$r。我感覺自己在此帶來了些許騷動。其他人也心懷疑慮，在我的同胞造成了那一切之後，我不怪他們。$B$B自從太陽之井那件事以來發生了很多，沒幾件是好事。現在輪到我要來重新拾起我們龍群的自尊。這裡還有很多話要說，還有很多事得做，但要知道:不是所有的藍龍軍團都把這世界所遭逢的厄運怪罪到艾澤拉斯的凡人身上。$B$B我們其中的一些，並非如此無感。', `MaleText_loc7`='Saludos, $r. Mi presencia en este lugar me confunde. El resto tiene sospechas también, y no los culpo, después de lo que pasaron mis hermanos.$B$BHan pasado muchas cosas desde La Fuente del Sol, casi nada bueno. Y cae sobre mí tener que recoger los pedazos, e intentar rescatar el orgullo de mi vuelo. Hay mucho que decir, pero mucho más que hacer. Hay que saber que no todo el Vuelo Azul culpa a las razas mortales de Azeroth de los problemas que han sucedido en el mundo.$B$BAlgunos de nosotros tenemos algo más de sentido que todo eso.' WHERE `ID`=38509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가 정말로 가버렸군요. 그렇죠?$b$b느낄... 수 있어요.', `FemaleText_loc4`='他真的离去了，是吗？$b$b我……我能感觉到。', `FemaleText_loc5`='他真的死了，對不對?$b$b我...我可以感覺到。', `FemaleText_loc7`='Se ha ido de verdad, ¿no?$B$BPuedo... sentirlo.' WHERE `ID`=38510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 그를 구해낼 방법이 없었나요?$b$b계속 이 질문을 던지며 살아야 할까 봐 두려워요.', `FemaleText_loc4`='真的没有办法拯救他吗？$b$b我恐怕永远也无法对此释怀。', `FemaleText_loc5`='真的沒有辦法可以拯救他嗎?$b$b我有生之年大概會一直思考著這一個可能性。', `FemaleText_loc7`='¿Realmente no había forma de salvarlo?$B$BTemo que me lo preguntaré siempre.' WHERE `ID`=38511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 여기 어딘가요...? 이 무슨 악몽을 꾼거지... 하지만 곰곰히 생각해 볼 시간은 없어요. 보고해야 할 정보가 많습니다!', `MaleText_loc4`='我…我在哪…？这真是场可怕的恶梦…不过没时间细想了，还有很多事情在等着我汇报！', `MaleText_loc5`='我...我在哪裡...?我彷彿做了一場噩夢...但沒時間回神了，我有很多消息要回報!', `MaleText_loc7`='¿Dón… dónde estoy…? ¿Qué clase de pesadilla…? ¡No es hora de reflexionar, tengo que hacer llegar mucha información!' WHERE `ID`=38512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지게 싸워봅시다, $n! 당신이 우리 편이어서 정말 든든합니다!', `MaleText_loc4`='该是上战场的时候了，$n！有你的帮助，胜利的天平一定会向我们倾斜！', `MaleText_loc5`='是投身戰鬥的時候了，$n!有你加入我們陣容的話絕對能為我們帶來優勢!', `MaleText_loc7`='¡Es hora de unirse a la lucha, $n! ¡Contigo de nuestra parte, es seguro que la balanza se inclinará hacia nuestro lado!' WHERE `ID`=38513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비를 철저히 하십시오. 오크 특사들이 빛의 대성당 안에서 실바나스를 만날 준비가 끝났습니다.', `MaleText_loc4`='做好一切准备。兽人使者就要在这座教堂里与希尔瓦娜斯会面了。', `MaleText_loc5`='確保已經作好萬全準備。獸人大使已經準備好在大教堂中與希瓦娜斯會面。', `MaleText_loc7`='Asegúrate de que todo está preparado. El emisario de los orcos está listo para reunirse con Sylvanas dentro de la catedral.' WHERE `ID`=38514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 갈증으로 목이 마릅니다!', `MaleText_loc4`='你嗜血成性！', `MaleText_loc5`='你渴望鮮血!', `MaleText_loc7`='¡Tienes sed de sangre!', `FemaleText_loc1`='피의 갈증으로 목이 마릅니다!', `FemaleText_loc4`='你嗜血成性！', `FemaleText_loc5`='你渴望鮮血!', `FemaleText_loc7`='¡Tienes sed de sangre!' WHERE `ID`=38515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 침입자들아! 누구도 교단의 계획을 간섭할 순 없다!', `MaleText_loc4`='死吧，入侵者！没人能干预教派的计划！', `MaleText_loc5`='去死，入侵者!沒有人能阻撓神教的計畫!', `MaleText_loc7`='¡Morid, intrusos! Nadie interferirá en los planes del Culto!' WHERE `ID`=38516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 깨어난다!', `MaleText_loc4`='我醒了!', `MaleText_loc5`='我...甦醒了!', `MaleText_loc7`='Estoy despierto...' WHERE `ID`=38517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기... 누구냐?', `MaleText_loc4`='那里是谁？', `MaleText_loc5`='誰...在那兒...?', `MaleText_loc7`='¿Quién... anda ahí?' WHERE `ID`=38518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 명령하신다.', `MaleText_loc4`='我们受主人的指挥。', `MaleText_loc5`='我們的主人指揮我們。', `MaleText_loc7`='¡Nuestro maestro ordena!', `FemaleText_loc1`='주인님께서 명령하신다.', `FemaleText_loc4`='我们受主人的指挥。', `FemaleText_loc5`='我們的主人指揮我們。', `FemaleText_loc7`='¡Nuestro maestro ordena!' WHERE `ID`=38519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 죽어서도 섬기리라.', `MaleText_loc4`='死后我们忠心不改。', `MaleText_loc5`='死後亦然。', `MaleText_loc7`='Servimos hasta en la muerte.', `FemaleText_loc1`='우리는 죽어서도 섬기리라.', `FemaleText_loc4`='死后我们忠心不改。', `FemaleText_loc5`='死後亦然。', `FemaleText_loc7`='Servimos hasta en la muerte.' WHERE `ID`=38520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 얼라이언스의 일원이시군요!$B$B저는 가젯잔의 공식 대표로서 이곳에 흩어져있는 가난한 노움들과 스팀휘들 고블린들이 함께 잘 살아나갈 수 있도록 하는 역할을 맡고 있어요! 호드의 새로운 고블린 친구의 존재조차도 마음을 열어 관대하게 대할 수 있을 거고요.$B$B당신이 도와준다면 우리 모두 적절한 합의점을 찾을 수 있을 거예요!', `FemaleText_loc4`='你好，联盟的成员！$B$B作为加基森的官方代表，我的任务是确保我们离散的可怜侏儒们能够与与热砂港地精在加基森和平相处！为此，我们甚至可以容忍他们新的部落地精朋友。$B$B相信有你的帮助，我们能够达成令人愉快的共识！', `FemaleText_loc5`='哈囉，聯盟的同伴們!$B$B做為加基森的官方代表，我來這是想確認我們這些四散的可憐地精可以和平地與熱砂哥布林待在加基森!我們甚至還能放寬尺度接受他們的新部落朋友。$B$B我相信在你的幫助下我們全部人都能達成共識!', `FemaleText_loc7`='¡Vaya, hola, $gcompañero:compañera; de la Alianza!$b$bComo representante oficial de Gadgetzan, estoy aquí para asegurarme de que los pobres gnomos podemos convivir pacíficamente con los goblins del Cártel Bonvapor, aquí en Gadgetzan. Puede que incluso lleguemos a tolerar la presencia de sus nuevos amigos goblins de la Horda.$b$b¡Seguro que con tu ayuda podemos llegar a un acuerdo!' WHERE `ID`=38521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을 위해 한 번 더 싸우리라.', `MaleText_loc4`='我们再次为主人而战。', `MaleText_loc5`='我們將再次為主人而戰。', `MaleText_loc7`='Luchamos una vez más por nuestro maestro.', `FemaleText_loc1`='주인님을 위해 한 번 더 싸우리라.', `FemaleText_loc4`='我们再次为主人而战。', `FemaleText_loc5`='我們將再次為主人而戰。', `FemaleText_loc7`='Luchamos una vez más por nuestro maestro.' WHERE `ID`=38522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 죽음을 이런 곳에서 찾느냐?', `MaleText_loc4`='你为什么要在这寻死？', `MaleText_loc5`='為什麼你要在此求死?', `MaleText_loc7`='¿Por qué buscas la muerte en este lugar?', `FemaleText_loc1`='왜 죽음을 이런 곳에서 찾느냐?', `FemaleText_loc4`='你为什么要在这寻死？', `FemaleText_loc5`='為什麼你要在此求死?', `FemaleText_loc7`='¿Por qué buscas la muerte en este lugar?' WHERE `ID`=38523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 산 자가 올 데가 아니다.', `MaleText_loc4`='活人不属于这里。', `MaleText_loc5`='生靈不屬於此地。', `MaleText_loc7`='¡Este no es el lugar de los vivos!', `FemaleText_loc1`='여기는 산 자가 올 데가 아니다.', `FemaleText_loc4`='活人不属于这里。', `FemaleText_loc5`='生靈不屬於此地。', `FemaleText_loc7`='¡Este no es el lugar de los vivos!' WHERE `ID`=38524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 고통은 영원하리라.', `MaleText_loc4`='我们永远无法摆脱折磨。', `MaleText_loc5`='我們的苦難永無止境。', `MaleText_loc7`='¡Nuestro tormento es eterno!', `FemaleText_loc1`='우리 고통은 영원하리라.', `FemaleText_loc4`='我们永远无法摆脱折磨。', `FemaleText_loc5`='我們的苦難永無止境。', `FemaleText_loc7`='¡Nuestro tormento es eterno!' WHERE `ID`=38525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 우리의 마지막 안식은 아니다.', `MaleText_loc4`='最终的胜利还没有到来。', `MaleText_loc5`='這不是我們的最終安息。', `MaleText_loc7`='Este no es nuestro descanso final.', `FemaleText_loc1`='이것이 우리의 마지막 안식은 아니다.', `FemaleText_loc4`='最终的胜利还没有到来。', `FemaleText_loc5`='這不是我們的最終安息。', `FemaleText_loc7`='Este no es nuestro descanso final.' WHERE `ID`=38526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽음 안에서 주인님을 섬긴다.', `MaleText_loc4`='死后仍为主人效命。', `MaleText_loc5`='所有人都得在死後服侍主人。', `MaleText_loc7`='Servimos al maestro en la muerte.', `FemaleText_loc1`='모두 죽음 안에서 주인님을 섬긴다.', `FemaleText_loc4`='死后仍为主人效命。', `FemaleText_loc5`='所有人都得在死後服侍主人。', `FemaleText_loc7`='Servimos al maestro en la muerte.' WHERE `ID`=38527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 짧은 휴식일 뿐이다...', `MaleText_loc4`='这只不过是暂时的休息…', `MaleText_loc5`='這只是短暫的安歇...', `MaleText_loc7`='No es más que un pequeño descanso.', `FemaleText_loc1`='이건 짧은 휴식일 뿐이다...', `FemaleText_loc4`='这只不过是暂时的休息…', `FemaleText_loc5`='這只是短暫的安歇...', `FemaleText_loc7`='No es más que un pequeño descanso.' WHERE `ID`=38528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 영혼은 결코 자유롭지 못하리라.', `MaleText_loc4`='我们的灵魂将永无宁日。', `MaleText_loc5`='我們的靈魂永遠無法被釋放。', `MaleText_loc7`='¡Nuestras almas nunca serán libres!', `FemaleText_loc1`='우리 영혼은 결코 자유롭지 못하리라.', `FemaleText_loc4`='我们的灵魂将永无宁日。', `FemaleText_loc5`='我們的靈魂永遠無法被釋放。', `FemaleText_loc7`='¡Nuestras almas nunca serán libres!' WHERE `ID`=38529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c! 오브리 제독님이 위에서 당신을 기다리고 계시오.', `MaleText_loc4`='你好啊，$c！海军司令奥布里正在楼上等你呢。', `MaleText_loc5`='你好啊，$c!奧布里上將在上面等著你。', `MaleText_loc7`='¡Saludos, $c! El almirante Aubrey te espera arriba.' WHERE `ID`=38530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저 안으로 가서 고블린을 구해주세요!', `FemaleText_loc4`='$n，你一定能拯救我的族人！', `FemaleText_loc5`='$n，你一定要去那裡拯救我們的人民!', `FemaleText_loc7`='¡$n, tienes que entrar ahí y salvar a nuestra gente!' WHERE `ID`=38531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 개입해선 안 된다.', `MaleText_loc4`='不要惹麻烦。', `MaleText_loc5`='你別想干擾。', `MaleText_loc7`='No interferirás.' WHERE `ID`=38532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사 지역을 오염시켜지 마라.', `MaleText_loc4`='不要污染调查现场。', `MaleText_loc5`='你不應該污染調查現場。', `MaleText_loc7`='No contaminarás el lugar de la investigación.' WHERE `ID`=38533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사 작업을 방해하지 마라.', `MaleText_loc4`='不要干扰调查工作。', `MaleText_loc5`='不要妨礙調查計畫。', `MaleText_loc7`='No interrumpas el protocolo de investigación.' WHERE `ID`=38534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 더러운 몸으로 여기 올 수 없어요. 먼저 그 역겨운 살부터 벗어버리세요!', `MaleText_loc4`='别就这么脏兮兮的进来。赶快把身上的脏肉给我弄干净！', `MaleText_loc5`='你可不能這麼髒就跑來這裡。你得先把這些爛肉給刷乾淨!', `MaleText_loc7`='No pueden entrar así de sucios. ¡Primero hay que sacarles esa piel con un cepillo!' WHERE `ID`=38535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 벽을 무너뜨릴 테니 언데드가 다가오지 못하도록 막아요!', `FemaleText_loc4`='我会摧毁这道屏障，但你必须挡住那些亡灵！', `FemaleText_loc5`='我要摧毀這個屏障。你一定要擋住那些不死生物!', `FemaleText_loc7`='Destruiré esta barrera. Mantengan alejados a los no-muertos!' WHERE `ID`=38536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼음 벽이 또 있어요! 이 벽이 무너지도록 주문을 외울 테니 언데드가 방해하지 못하게 해 주세요.', `FemaleText_loc4`='又是一道冰墙！不要让那些亡灵打断我的法术，这样我才能摧毁冰墙。', `FemaleText_loc5`='另一面冰牆!別讓那些不死生物干擾我念咒，這樣我才能破壞那面牆。', `FemaleText_loc7`='¡Otro muro de hielo! Impidan que los no-muertos interrumpan mis conjuros para que pueda derribar este muro.' WHERE `ID`=38537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거의 다 왔어요... 포기하지 말아요!', `FemaleText_loc4`='我们就要到了……不要放弃！', `FemaleText_loc5`='我們快成功了...千萬別放棄!', `FemaleText_loc7`='Ya casi llegamos… ¡No se rindan!' WHERE `ID`=38538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁜 놈, 이런 벽으로 더는 우리를 막을 수 없다! 전부 산산조각 내 버리겠어!', `FemaleText_loc4`='你的屏障挡不住我们，怪物！我会将它们全部粉碎！', `FemaleText_loc5`='你的屏障擋不我們多久的，怪物!我會把他們全打爛!', `FemaleText_loc7`='¡Tus muros no pueden detenernos, monstruo! ¡Los destruiré todos!' WHERE `ID`=38539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤 장벽으로도 밴시 여왕을 막을 수 없다. 영웅들이여, 언데드를 막아라. 이 벽을 무너뜨리겠다!', `FemaleText_loc4`='没有墙壁能阻挡女妖之王。挡住那些亡灵，英雄们。我会粉碎这道屏障！', `FemaleText_loc5`='沒有高牆能阻擋女妖之王。英雄們，擋住那些不死生物。我要撕開這個屏障!', `FemaleText_loc7`='Ningún muro detendrá a la Reina Alma en Pena. Mantengan a los no-muertos a raya, héroes. ¡Destruiré la barrera!' WHERE `ID`=38540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장벽이 또 있다! 용사들이여, 버텨야 한다. 벽을 무너뜨리겠다.', `FemaleText_loc4`='又是一道！坚持住，勇士们。我会粉碎这面冰墙。', `FemaleText_loc5`='另一道屏障?站穩了，勇士們。我要拆毀這面牆。', `FemaleText_loc7`='¡Otra barrera! Sean fuertes, campeones. Derrumbaré el muro.' WHERE `ID`=38541;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스, 이제 이런 놀이는 지루하다! 장벽으로 나를 막을 수는 없다!', `FemaleText_loc4`='我厌倦了你的把戏，阿尔萨斯！你的冰墙阻挡不了我！', `FemaleText_loc5`='我厭倦這些遊戲了，阿薩斯!你的牆壁阻擋不了我!', `FemaleText_loc7`='¡Me canso de estos juegos, Arthas! ¡Tus muros no me detendrán!' WHERE `ID`=38542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괴물 같은 놈, 우리를 막지는 못한다! 이 장벽을 무너뜨리는 동안 언데드가 다가오지 못하게 하라.', `FemaleText_loc4`='你们这些恶魔拦不住我们！挡住那些亡灵，我在努力摧毁冰墙！', `FemaleText_loc5`='你無法阻止我們離去，惡魔!在我粉碎這道屏障前，別讓那些不死生物靠近我。', `FemaleText_loc7`='¡No impedirás que escapemos, demonio! Mantengan a los no-muertos lejos de mí mientras derribo esta barrera.' WHERE `ID`=38543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 흥미롭군요...', `MaleText_loc4`='嗯，有趣……', `MaleText_loc5`='嗯，有意思...', `MaleText_loc7`='Mmm, qué interesante…' WHERE `ID`=38544;
