UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 소식이에요, 여러분!', `MaleText_loc4`='重大喜讯！各位', `MaleText_loc5`='大夥聽著，好消息!', `MaleText_loc7`='¡Excelentes noticias, amigos!' WHERE `ID`=38546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 삼켜지는 걸 막을 수는 없다! 너희는 그저 시간을 조금 늦췄을 뿐이다.', `MaleText_loc4`='灵魂的汹涌不会被削弱！一切都只是徒劳。', `MaleText_loc5`='眾魂的壯大將無法阻擋!你不過是在拖延必然之事。', `MaleText_loc7`='¡No se puede amainar la marejada de almas! Sólo posponen lo inevitable.' WHERE `ID`=38547;
