UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 앞에 길이 있다. 어서 가라!', `FemaleText_loc4`='前面有个出口，赶快！', `FemaleText_loc5`='前面有個缺口。就是現在!', `FemaleText_loc7`='Hay una salida ahí delante. ¡VAMOS!' WHERE `ID`=38551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고빈!!!', `MaleText_loc4`='地精！！！', `MaleText_loc5`='哥卜林!!!', `MaleText_loc7`='¡¡¡GOBIN!!!' WHERE `ID`=38552;
