UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러! 저놈들 뒤에서 습격하자!', `MaleText_loc4`='快点，我们会在背后伏击他们！', `MaleText_loc5`='快，我們要從後面奇襲他們!', `MaleText_loc7`='Rápido, ¡los emboscaremos por la espalda!', `FemaleText_loc1`='서둘러! 저놈들 뒤에서 습격하자!', `FemaleText_loc4`='快点，我们会在背后伏击他们！', `FemaleText_loc5`='快，我們要從後面奇襲他們!', `FemaleText_loc7`='Rápido, ¡los emboscaremos por la espalda!' WHERE `ID`=38563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아있는 놈이... 여기에?!', `MaleText_loc4`='这里有活人？！', `MaleText_loc5`='生人...在此?', `MaleText_loc7`='¿Los vivos? ¿¡Aquí!?', `FemaleText_loc1`='살아있는 놈이... 여기에?!', `FemaleText_loc4`='这里有活人？！', `FemaleText_loc5`='生人...在此?', `FemaleText_loc7`='¿Los vivos? ¿¡Aquí!?' WHERE `ID`=38564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 당신은 내 생명의 은인이야!', `MaleText_loc4`='我自由了！是你救了我！', `MaleText_loc5`='我自由了!我欠你一條命!', `MaleText_loc7`='¡Soy libre! ¡Te debo la vida!', `FemaleText_loc1`='자유다! 당신은 제 생명의 은인이에요!', `FemaleText_loc4`='我自由了！是你救了我！', `FemaleText_loc5`='我自由了!我欠你一條命!', `FemaleText_loc7`='¡Soy libre! ¡Te debo la vida!' WHERE `ID`=38565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영영 가망이 없을 줄 알았다고!', `MaleText_loc4`='我还以为自己必死无疑了！', `MaleText_loc5`='我以為我死定了!', `MaleText_loc7`='¡Creí que ya no lo contaba!', `FemaleText_loc1`='영영 가망이 없을 줄 알았어요!', `FemaleText_loc4`='我还以为自己必死无疑了！', `FemaleText_loc5`='我以為我死定了!', `FemaleText_loc7`='¡Creí que ya no lo contaba!' WHERE `ID`=38566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명줄이 점점 짧아지는 게 느껴졌지 뭐야.', `MaleText_loc4`='我觉得我的生命正在离开我。', `MaleText_loc5`='我覺得我的生命正在流逝。', `MaleText_loc7`='Sentía cómo se me escapaba la vida.', `FemaleText_loc1`='생명줄이 점점 짧아지는 게 느껴졌지 뭐예요.', `FemaleText_loc4`='我觉得我的生命正在离开我。', `FemaleText_loc5`='我覺得我的生命正在流逝。', `FemaleText_loc7`='Sentía cómo se me escapaba la vida.' WHERE `ID`=38567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 좀비로 바꾸려고 했다고!', `MaleText_loc4`='他们要把我变成僵尸！！！', `MaleText_loc5`='他們想把我變為殭屍!!!', `MaleText_loc7`='¡Estaban intentando convertirme en un zombi!', `FemaleText_loc1`='저를 좀비로 바꾸려고 했어요!', `FemaleText_loc4`='他们要把我变成僵尸！！！', `FemaleText_loc5`='他們想把我變為殭屍!!!', `FemaleText_loc7`='¡Estaban intentando convertirme en un zombi!' WHERE `ID`=38568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 잡히기 전에 여기서 빠져나가야겠어!', `MaleText_loc4`='我要在他们再次抓住我之前离开这里！', `MaleText_loc5`='在他們抓到我之前我必須逃離這裡!', `MaleText_loc7`='¡Tengo que salir de aquí antes de que me vuelvan a atrapar!', `FemaleText_loc1`='다시 잡히기 전에 여기서 빠져나가야겠어요!', `FemaleText_loc4`='我要在他们再次抓住我之前离开这里！', `FemaleText_loc5`='在他們抓到我之前我必須逃離這裡!', `FemaleText_loc7`='¡Tengo que salir de aquí antes de que me vuelvan a atrapar!' WHERE `ID`=38569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 감사를 해야 할지 모르겠는데!', `MaleText_loc4`='真不知道该怎样感谢你！', `MaleText_loc5`='對你我真是感激不盡!', `MaleText_loc7`='¡No puedo agradecértelo suficiente!', `FemaleText_loc1`='어떻게 감사를 드려야 할지 모르겠네요!', `FemaleText_loc4`='真不知道该怎样感谢你！', `FemaleText_loc5`='對你我真是感激不盡!', `FemaleText_loc7`='¡No puedo agradecértelo suficiente!' WHERE `ID`=38570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이들은 화산으로 끌려갔어. 몇몇은 좀비로 변했고, 몇몇은 그들이 섬기는 거북이 신인 볼카노스에게 제물로 바쳐졌다고!', `MaleText_loc4`='他们把其他人带进了火山口。有些人变成了僵尸，有些人被献祭给他们的海龟神沃卡洛斯！', `MaleText_loc5`='他們把其他人抓到火山中。有些會被變成殭屍，有些則會被當成祭品獻祭給他們的烏龜神，火岩諾斯!', `MaleText_loc7`='¡Se llevaron a los demás al volcán! ¡A algunos los transformaron en zombis y otros fueron sacrificados en nombre de su dios tortuga, Volcanoth!', `FemaleText_loc1`='다른 이들은 화산으로 끌려갔어요. 몇몇은 좀비로 변했고, 몇몇은 그들이 섬기는 거북이 신인 볼카노스에게 제물로 바쳐졌어요!', `FemaleText_loc4`='他们把其他人带进了火山口。有些人变成了僵尸，有些人被献祭给他们的海龟神沃卡洛斯！', `FemaleText_loc5`='他們把其他人抓到火山中。有些會被變成殭屍，有些則會被當成祭品獻祭給他們的烏龜神，火岩諾斯!', `FemaleText_loc7`='¡Se llevaron a los demás al volcán! ¡A algunos los transformaron en zombis y otros fueron sacrificados en nombre de su dios tortuga, Volcanoth!' WHERE `ID`=38571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 포로들이 아직 화산 안에 있어... 제물로 바쳐지거나, 아니면 좀비가 될 거라고!', `MaleText_loc4`='其他俘虏还在火山口里……他们或者是被献祭了，或者下场更悲惨——变成了僵尸！', `MaleText_loc5`='其他被抓的人在火山上面...他們被犧牲了，或更慘，被殭屍化了!', `MaleText_loc7`='Los demás cautivos están arriba en el volcán. Los están sacrificando, o peor, ¡zombificando!', `FemaleText_loc1`='다른 포로들이 아직 화산 안에 있어요... 제물로 바쳐지거나, 아니면 좀비가 될 거예요!', `FemaleText_loc4`='其他俘虏还在火山口里……他们或者是被献祭了，或者下场更悲惨——变成了僵尸！', `FemaleText_loc5`='其他被抓的人在火山上面...他們被犧牲了，或更慘，被殭屍化了!', `FemaleText_loc7`='Los demás cautivos están arriba en el volcán. Los están sacrificando, o peor, ¡zombificando!' WHERE `ID`=38572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 버텨내야 합니다. 북부감시 요새는 배수의 진이나 다름없으니까요!', `MaleText_loc4`='我们必须坚守阵地。如果北方城堡失守，我们就只能背水一战了！', `MaleText_loc5`='我們必須堅強。如果北方那淪陷了，我們後方將除了海水外什麼都沒有。', `MaleText_loc7`='Debemos resistir. ¡Si Fuerte del Norte cae, no tendremos donde retirarnos porque detrás de nosotros solo hay mar!' WHERE `ID`=38573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독님, 검은호수호로 날아갈 수 있을까요?', `MaleText_loc4`='指挥官，我能申请一匹坐骑前往黑弹珠号吗？', `MaleText_loc5`='上將，可以送我到布萊克波爾號嗎?', `MaleText_loc7`='Almirante, ¿podría conseguirme transporte a Pozo Negro?', `FemaleText_loc1`='제독님, 검은호수호로 날아갈 수 있을까요?', `FemaleText_loc4`='指挥官，我能申请一匹坐骑前往黑弹珠号吗？', `FemaleText_loc5`='上將，可以送我到布萊克波爾號嗎?', `FemaleText_loc7`='Almirante, ¿podría conseguirme transporte a Pozo Negro?' WHERE `ID`=38574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기 놀러 온 게 아니라고, 친구. 노겐포저 씨께서 임무를 주셔서 왔단 말이야. 그 임무란 건 바로 이곳의 실리시드들로 이윤을 창출할 방법을 찾아보거나, 그렇지 않다면 깨끗이 청소해버리는 거지.$B$B당신 같은 $r|1이;가; 스팀휘들 무역회사를 위해 일하고 싶어한다면 내가 도와줄 수도 있지.', `MaleText_loc4`='我到这里来可不是为了渡假，朋友。诺格弗格派我来这里完成一个任务：确认该如何从这些异种怪物身上获取利润。如果不行，就将它们消灭干净。$B$B如果像你这样的$r想要为热砂集团做些事情，那么我倒是可以给你个机会。', `MaleText_loc5`='我不是來度假的，老兄。諾格弗格派我來這執行一個任務:看看如何從這些異種蠍中獲利，要不然就消滅牠們。$B$B如果像你這樣的$r願意助協助熱砂企業的話，我需要點幫忙。', `MaleText_loc7`='No estoy aquí de vacaciones, camarada. Tragonublo me ha enviado con una misión: averiguar cómo sacar beneficios de estos silítidos o borrarlos del mapa.$B$BSi $gun:una; $r como tú quiere hacerle un par de favores al Cártel Bonvapor, me vendría bien una mano.' WHERE `ID`=38575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 쌓이더니 $n에게 몰려듭니다!', `MaleText_loc4`='蜂拥的阴影在$n的四周积聚！', `MaleText_loc5`='暗影聚集並旋繞在$n四周!', `MaleText_loc7`='¡Las sombras se acumulan alrededor de $n!', `FemaleText_loc1`='어둠이 쌓이더니 $n에게 몰려듭니다!', `FemaleText_loc4`='蜂拥的阴影在$n的四周积聚！', `FemaleText_loc5`='暗影聚集並旋繞在$n四周!', `FemaleText_loc7`='¡Las sombras se acumulan alrededor de $n!' WHERE `ID`=38576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 무기를 어떻게 쓰는지조차도 모르겠어... 하지만 이걸 들고 여기 이렇게 서 있으면 늑대인간이 겁에 질려 다른 곳으로 가버릴지도 몰라.', `FemaleText_loc4`='我甚至不知道该如何使用这件武器……但我相信，如果我摆出一副凶恶的样子，那些狼人也许就会逃到别的地方去。', `FemaleText_loc5`='我根本不知道如何使用這個武器...但我發現如果我很兇惡的站在這，狼人或許就會去別的地方。', `FemaleText_loc7`='Ni siquiera sé cómo utilizar esta arma... pero creo que si me quedo aquí, con una pose amenazadora, los huargen quizá se marchen a otra parte.' WHERE `ID`=38577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프르프르 타 디, 고빈!!!', `MaleText_loc4`='准备去死吧，地精！！！', `MaleText_loc5`='批啊批啊它地，哥布!', `MaleText_loc7`='¡¡¡PR''PR TA DI, GOBIN!!!' WHERE `ID`=38579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 휘둘러! 모두 베어라!', `MaleText_loc4`='全体上甲板！把他们赶走！', `MaleText_loc5`='所有甲板上的人員聽令!幹掉他們!', `MaleText_loc7`='¡Todos a cubierta! ¡A por ellos!' WHERE `ID`=38580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님, 북부감시 요새로 돌아가고 싶습니다.', `MaleText_loc4`='队长，我需要坐骑返回北方城堡。', `MaleText_loc5`='上尉，我需要你送我回北方城堡。', `MaleText_loc7`='Capitán, necesito regresar a Fuerte del Norte.', `FemaleText_loc1`='선장님, 북부감시 요새로 돌아가고 싶습니다.', `FemaleText_loc4`='队长，我需要坐骑返回北方城堡。', `FemaleText_loc5`='上尉，我需要你送我回北方城堡。', `FemaleText_loc7`='Capitán, necesito regresar a Fuerte del Norte.' WHERE `ID`=38581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌겠소, $c!', `MaleText_loc4`='万事平安，$c！', `MaleText_loc5`='祝你平安，$c!', `MaleText_loc7`='¡Buena suerte, $c!' WHERE `ID`=38582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블레인, $n 님을 위해 그리핀을 준비해 주시겠소?', `MaleText_loc4`='布兰恩先生？请为$n准备一只狮鹫。', `MaleText_loc5`='布雷因先生?請你幫$n攔下一隻獅鷲獸。', `MaleText_loc7`='¿Señor Blaine? Haga señales y detenga un grifo para $n, si no te importa.' WHERE `ID`=38583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 제독님! 즉시 대령하겠습니다!', `MaleText_loc4`='是，长官！马上，长官！', `MaleText_loc5`='是的，長官!立刻辦理，長官!', `MaleText_loc7`='¡Señor, sí, señor! ¡Inmediatamente, señor!' WHERE `ID`=38584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상황에서 살아남는다 해도, 내 모자에 튄 살점을 닦아내려면 족히 한 달은 걸리겠군.', `MaleText_loc4`='即使我们能取得胜利，我也要用一个月的时间才能把甲板上的脏东西清理干净。', `MaleText_loc5`='假如我們成功撐過的話，我看大概需要花一個月的時間才能把濺在盔甲上的腦漿清乾淨。', `MaleText_loc7`='Si al final resulta que salimos de esta, me llevará todo un mes limpiar los sesos de toda la decoración de latón.' WHERE `ID`=38585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 내가 누군지와 왜 이 일을 하는지 말해주려고 귀찮게 하든가?', `MaleText_loc4`='他们顾得上告诉你我是谁或者我在做些什么吗？', `MaleText_loc5`='他們有告訴你我是誰還有我為什麼這麼做嗎?', `MaleText_loc7`='¿Se han molestado en decirte quién soy y por qué estoy haciendo esto?' WHERE `ID`=38586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 기원이 공작 켈레세스에게 옮겨갑니다!', `MaleText_loc4`='凯雷塞斯王子获得了鲜血唤醒的效果！', `MaleText_loc5`='血魄祈願跳到凱雷希斯親王身上!', `MaleText_loc7`='¡Invocación de orbe de sangre para el príncipe Keleseth!' WHERE `ID`=38588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 기원이 공작 발라나르에게 옮겨갑니다!', `MaleText_loc4`='瓦拉纳王子获得了鲜血唤醒的效果！', `MaleText_loc5`='血魄祈願跳到瓦拉納爾親王身上!', `MaleText_loc7`='¡Invocación de orbe de sangre para el príncipe Valanar!' WHERE `ID`=38589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 기원이 공작 탈다람에게 옮겨갑니다!', `MaleText_loc4`='塔达拉姆王子获得了鲜血唤醒的效果！', `MaleText_loc5`='血魄祈願跳到泰爾達朗親王身上!', `MaleText_loc7`='¡Invocación de orbe de sangre para el príncipe Taldaram!' WHERE `ID`=38590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 알게 뭔가. 이젠 이 일을 끝내야 할 때이네.', `MaleText_loc4`='但这有什么关系。到了该结束的时候了。', `MaleText_loc5`='但這又什麼關係。反正終結的時間要到了。', `MaleText_loc7`='Pero qué más da. Es hora de acabar con esto.' WHERE `ID`=38591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백스터! 이리 와서 돕거라! 어서!', `MaleText_loc4`='巴柯斯特！到这儿来帮帮我！快来！', `MaleText_loc5`='巴克斯特!快進來幫忙!立刻!', `MaleText_loc7`='¡Baxter! ¡Ven a ayudar! ¡AHORA!' WHERE `ID`=38592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프라이, 시간 됐다! 공격해!', `MaleText_loc4`='到时候了，进攻！', `MaleText_loc5`='就是現在，弗萊伊!攻擊!', `MaleText_loc7`='¡Es el momento, Frye! ¡Ataca!' WHERE `ID`=38593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사들아! 왕관화학사를 위해 너희의 생명을 내 놓거라!', `MaleText_loc4`='药剂师们！把你们的生命献给皇冠药剂公司吧！', `MaleText_loc5`='藥劑師們!為王冠公司付出你們的生命!', `MaleText_loc7`='¡Boticarios! ¡Entreguen su vida por la corona!' WHERE `ID`=38594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훔멜 님, 당신을 모시게 되어 제 인생의 크나큰 영광이었습니다.', `MaleText_loc4`='同您共事是我一生最大的荣耀。', `MaleText_loc5`='我這輩子最大的榮幸就是服侍你，胡默爾。', `MaleText_loc7`='Servir contigo ha sido el mayor honor de mi vida, Hummel.' WHERE `ID`=38595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 그래. 우린 무기력한 게 아니라 무능한 거야.', `MaleText_loc4`='很好。我们不是没种，而是无能。', `MaleText_loc5`='很好。我們不是懦弱，我們是缺乏能力。', `MaleText_loc7`='Genial. No somos cobardes, somos incompetentes.' WHERE `ID`=38596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 부디 날 미천한 존재로 여기지 말게.', `MaleText_loc4`='…请不要轻视我。', `MaleText_loc5`='...不要小看我。', `MaleText_loc7`='... por favor, no me infravalores.' WHERE `ID`=38597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이지, 혹시 잉위의 육신이 어디에 있는지 압니까?', `MaleText_loc4`='小静，你不会正好知道英格维的躯体在哪儿，对吧？', `MaleText_loc5`='伊茲，你該不會知道英格威的屍體在哪裡吧?', `MaleText_loc7`='Izzy, ¿por casualidad no sabrás dónde está el cuerpo de Yngwie, verdad?', `FemaleText_loc1`='이지, 혹시 잉위의 육신이 어디에 있는지 알아요?', `FemaleText_loc4`='小静，你不会正好知道英格维的躯体在哪儿，对吧？', `FemaleText_loc5`='伊茲，你該不會知道英格威的屍體在哪裡吧?', `FemaleText_loc7`='Izzy, ¿por casualidad no sabrás dónde está el cuerpo de Yngwie, verdad?' WHERE `ID`=38598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 그걸 어떻게 찾았는지는 묻지 마세요. 그냥 저기 커다랗고 푸른 화톳불에 던져넣고 너무 늦기 전에 잉위의 영혼을 파괴하세요!', `FemaleText_loc4`='听着，别管我是怎么找到它的。趁还来得及，快把它扔到那蓝色的大篝火里，毁掉英格维的灵魂！', `FemaleText_loc5`='聽著，別問我是如何找到它的。趁現在還來的及以前，你只要趕快把它丟向大型藍色營火，摧毀英格威的靈魂就行了!', `FemaleText_loc7`='Mira, no me preguntes cómo le encontré. ¡Tú simplemente arrójalo a esa gran hoguera azul y destruye el alma de Yngwie antes de que sea demasiado tarde!' WHERE `ID`=38599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 아니면 저들이 다른 모든 이들에게 하듯 자네를 이용하는 건가?', `MaleText_loc4`='…还是说他们只是像利用别人一样在利用你？', `MaleText_loc5`='...還是他們就像利用其他人一樣的利用你?', `MaleText_loc7`='¿... o te están usando como a todos los demás?' WHERE `ID`=38600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤리는 야수들과 함께 감옥에 있어야 마땅합니다!', `MaleText_loc4`='我们该把克罗雷留在监狱里喂野兽！', `MaleText_loc5`='我們應該把克羅雷丟進監獄陪那些野獸。', `MaleText_loc7`='¡Debemos dejar a Crowley en prisión con esas bestias!' WHERE `ID`=38601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 난 이미 결정했네. 우리에겐 크롤리가 필요해.', `MaleText_loc4`='够了！我已经做出了决定。我们需要克罗雷。', `MaleText_loc5`='夠了!我已經做出決定。我們需要克羅雷站在我們這方。', `MaleText_loc7`='¡Basta! Ya lo he decidido. Necesitamos a Crowley con nosotros.' WHERE `ID`=38602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 카드들은 있나요?', `MaleText_loc4`='还有其它套牌吗？', `MaleText_loc5`='還有其他套卡嗎?', `MaleText_loc7`='¿Existen otras barajas?', `FemaleText_loc1`='다른 카드들은 있나요?', `FemaleText_loc4`='还有其它套牌吗？', `FemaleText_loc5`='還有其他套卡嗎?', `FemaleText_loc7`='¿Existen otras barajas?' WHERE `ID`=38603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c님, 그걸 묻다니 눈치가 빠르군요. 각인사들은 대단한 힘의 타로 카드를 각인할 수 있답니다. 비록 그들이 만들 카드가 어떤 카드인지 완벽하게 통제할 순 없지만요. 운명이 카드를 결정하지요.$b$b카드 한 벌을 손에 넣으면 제게 가져오세요. 굉장한 보상을 드리지요.', `MaleText_loc4`='你的提问相当机敏，年轻的$c。铭文师能够制作蕴藏强大力量的塔罗牌，当然即使是铭文师自己也无法完全驾驭他们所创造出来的东西。决定一切的还是命运。$b$b如果你有办法集齐完整的套牌，请把它带给我，你会得到不错的回报。', `MaleText_loc5`='你很精明才曉得要問，年輕的$c。雕銘師能夠銘刻擁有強大力量的塔羅牌，儘管他們未必有能力控制自己做出什麼。命運自有決定。$b$b如果你收集到一整套的牌卡，請帶來給我，我將會給你驚人的報酬。', `MaleText_loc7`='Eres $gastuto:astuta; al preguntar, joven $c. Los escribas son capaces de inscribir cartas de tarot de gran poder, aunque no tienen total control sobre lo que hacen. El destino decide por ellos.$b$bSi consigues una baraja completa, tráemela y obtendrás una magnífica recompensa.' WHERE `ID`=38604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기에 집중해, $n!', `MaleText_loc4`='专注于比赛，$n！', `MaleText_loc5`='認真一點，$n!', `MaleText_loc7`='¡Concéntrate en el juego, $n!' WHERE `ID`=38605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 다들 물러나지마!', `MaleText_loc4`='大家听好，守住阵线！', `MaleText_loc5`='好，大夥守住陣線啊!', `MaleText_loc7`='¡Muy bien, chicos, aguantad ahí!' WHERE `ID`=38606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경기는 지화자 늴리리 얼씨구 작전이야. 셋에 시작하겠어. 하나... 둘... 셋! 음... 이봐들?!', `MaleText_loc4`='数三下，闪电傻瓜跳着基洛探戈上场。一……二……三！嗯……人呢？！', `MaleText_loc5`='這驚天動地無敵霹靂精采的一幕要開始了。一...二...三!呃...怎麼啦?!', `MaleText_loc7`='La maniobra es Kilo Tango Charlie Blitz a la de tres. ¡Una... dos... tres! Eh... ¿chicos?' WHERE `ID`=38607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테러닥스, 상어, 거대랩터도 모자라서 폭탄 던지는 원숭이까지 상대해야 하지. 이기려면 기적이라도 일어나야 해!', `MaleText_loc4`='我们要对付翼手龙，鲨鱼，刺角龙，还有扔炸弹的猴子。我们要是能取得胜利，那简直就是奇迹！', `MaleText_loc5`='我們面對的是翼手龍、鯊魚、迅猛龍和會丟炸彈的猴子。必須發生奇蹟我們才可能贏啊!', `MaleText_loc7`='Nos enfrentamos a pterrordáctilos, tiburones, teraptores y monos lanzabombas. ¡Vamos a necesitar un milagro para ganar!' WHERE `ID`=38608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 축구탄이 아냐, 애송이. 진짜 폭탄이라고!', `MaleText_loc4`='这可不是玩足球炸弹，孩子们。这是真正的交易！', `MaleText_loc5`='這可不是足球炸彈，小鬼。這可是玩真的!', `MaleText_loc7`='Esto no es bombalón, chicos. Esto es de verdad.' WHERE `ID`=38609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드스키머, 그 방법 써먹을 준비는 되셨나?', `MaleText_loc4`='金筛，你准备好出发了吗？', `MaleText_loc5`='金杓，你準備好跟它一起跑了嗎?', `MaleText_loc7`='Sacacuartos, ¿estás lista?' WHERE `ID`=38610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 원숭이한테 그냥 당할 거야? 안 되지!', `MaleText_loc4`='难道我们要让那群猴子为所欲为吗？绝不！', `MaleText_loc5`='我會讓那些野蠻的猴子得逞嗎?絕不!', `MaleText_loc7`='¿Vamos a dejar que se forren a costa nuestra? ¡NO!' WHERE `ID`=38611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 당장 해적단 벌목기 제복이 있다면 더 바랄 게 없을 텐데!', `MaleText_loc4`='我现在最渴望的是立刻得到一台海盗队伐木机。', `MaleText_loc5`='以前我不肯給海盜隊伐木機用的東西，現在正好派上用場啦!', `MaleText_loc7`='¡Qué no daría yo por tener aquí mismo uno de mis trajes triturados de los Bucaneros!' WHERE `ID`=38612;
