UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정하세요! 모두 다 돌봐 드릴 거예요.', `FemaleText_loc4`='保持平静！我们会照顾好大家。', `FemaleText_loc5`='保持冷靜!我們會照顧大家。', `FemaleText_loc7`='¡Mantengan la calma! Nos encargaremos de todo el mundo.' WHERE `ID`=38625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마차는 준비됐어요. 지금 그레이메인 페하의 명령이 떨어지기만을 기다리고 있어요.', `FemaleText_loc4`='我们已经备好了马车，正在等待格雷迈恩国王的命令。', `FemaleText_loc5`='馬車都準備好了，只要葛雷邁恩國王一聲令下就可上路。', `FemaleText_loc7`='Los carros están listos, estamos esperando la orden del rey Cringris.' WHERE `ID`=38626;
