UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났네, 고드프리. 동부의 군주들 중 자네를 지지할 사람은 없네.', `MaleText_loc4`='结束了，高弗雷。东部的领主中已经没有人会支持你了。', `MaleText_loc5`='一切都結束了，高佛雷。東部領主中沒人支持你。', `MaleText_loc7`='Se acabó, Godfrey. No te quedan apoyos entre los señores del este.' WHERE `ID`=38632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 너 같은 괴물을 왕으로 섬기느니 차라리 죽겠다!', `MaleText_loc4`='不……我宁愿早死也不愿有你这样的国王！', `MaleText_loc5`='不...我寧願死也不要一隻野獸來做我的國王!', `MaleText_loc7`='No... ¡Prefiero morir antes de tener de rey a uno de tu especie!' WHERE `ID`=38633;
