UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 다 아닐세. 자네의 동족으로서 여기 왔네.', `MaleText_loc4`='不，老朋友。我以平等的身份来找你。', `MaleText_loc5`='不，老朋友。我是以對等身分前來的。', `MaleText_loc7`='No, viejo amigo. Vengo a hablar de igual a igual.' WHERE `ID`=38637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 결정됐네. 모든 길니아스인이 힘을 합쳐 포세이큰을 우리 땅에서 몰아내는 걸세.', `MaleText_loc4`='那么就这样决定。我们将团结全部吉尔尼斯人，将被遗忘者从我们的国土上赶走。', `MaleText_loc5`='那就這麼決定了。我們會聚集所有吉爾尼斯的人，並把被遺忘者趕出我們的土地。', `MaleText_loc7`='Está decidido. Unificaremos a los gilneanos y echaremos a los Renegados.' WHERE `ID`=38638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤리! 엘프 동료들을 이끌고 왕의 군대로서 전투에 뛰어들 것을 명한다. 저주받은 몸일지라도, 넌 아직 길니아스의 법을 따라야 한다!', `MaleText_loc4`='克罗雷！你和你的精灵盟友将与国王的军队并肩战斗。不管你是不是受到了诅咒，你仍然受到吉尔尼斯法律的约束！', `MaleText_loc5`='克羅雷!命令你和你的精靈朋友們為國王的軍隊效命。不管受到詛咒與否，你仍然必須遵守吉爾尼斯的法律!', `MaleText_loc7`='¡Crowley! Se les ordena a ti y a tus elfos aliados que sirvan junto al ejército del rey. ¡Malditos o no, siguen regidos por la ley gilneana!' WHERE `ID`=38639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 작자가 말하는 게 자네의 뜻인가? 자넨 친구로서 온 것인가, 폭군으로서 온 것인가?', `MaleText_loc4`='这只癞蛤蟆是你的代言人吗，吉恩？你是以朋友的身份，还是暴君的身份来的？', `MaleText_loc5`='這討厭鬼是你的代言人嗎，吉恩?你是以朋友的身分來找我們嗎?還是以暴君的身分?', `MaleText_loc7`='¿Este sapo habla por ti, Genn? ¿Vienes aquí como amigo? ¿O como tirano?' WHERE `ID`=38640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르나!', `MaleText_loc4`='罗娜！', `MaleText_loc5`='羅娜!', `MaleText_loc7`='¡Lorna!' WHERE `ID`=38641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네, 겐. 이제 우리를 묶는 건 법을 넘어선 그 무언가일세. 내 부하들은 자네의 명에 따라 기꺼이 목숨을 바칠 게야.', `MaleText_loc4`='遵命，吉恩。约束我们的不是法律，而是某种更为牢固的东西。我的人将服从你的命令，至死方休。', `MaleText_loc5`='是的，吉恩。使我們結合的不是法律。是更強大的東西。我的人已經準備好為你的命令獻出生命。', `MaleText_loc7`='Sí, Genn. No es por la ley que lo hacemos. Es algo mucho más fuerte. Mis hombres están listos para dar su vida bajo tu mando.' WHERE `ID`=38642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 콜링우드 호를 완전히 가라앉혔지만, 간신히 대포를 끌고 나오는 데 성공했소.$B$B짐승같은 놈들이 더러운 녹색 발을 해변에 딛게 놔둘 순 없지! 내 손에 화약이 있는 한은 절대로!', `MaleText_loc4`='他们把科林伍德沉入了海底，但我们还是把她的舰炮拖到了岸上。$B$B只要我有火药，那些野兽肮脏的绿脚就别想踏上这片海滩！', `MaleText_loc5`='他們把科靈伍德丟入了海中，但我們將她的臼砲拉上了岸邊。$B$B只要我還有火藥，那些野獸別想把他們的綠色髒腳踏上這個海岸一步!', `MaleText_loc7`='Han hundido el Collingwood cerca de la costa, pero nos las hemos arreglado para llevar las carronadas a tierra.$B$B¡Esos animales no pondrán ni uno de sus sucios pies verdes en esta playa! ¡No mientras nos quede pólvora!' WHERE `ID`=38643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명중이야!', `MaleText_loc4`='正中靶心！', `MaleText_loc5`='正中紅心!', `MaleText_loc7`='¡Diana!', `FemaleText_loc1`='명중이네요!', `FemaleText_loc4`='正中靶心！', `FemaleText_loc5`='正中紅心!', `FemaleText_loc7`='¡Diana!' WHERE `ID`=38644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 좀 아프겠군!', `MaleText_loc4`='哦，这可真疼！', `MaleText_loc5`='噢，那鐵定很痛!', `MaleText_loc7`='¡Au, eso tiene que doler!', `FemaleText_loc1`='이런, 좀 아프겠네요!', `FemaleText_loc4`='哦，这可真疼！', `FemaleText_loc5`='噢，那鐵定很痛!', `FemaleText_loc7`='¡Au, eso tiene que doler!' WHERE `ID`=38645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 생각해? 이번 주 최고의 좀비 처치라고 하면?', `MaleText_loc4`='你在想什么？这个星期的任务是消灭僵尸？', `MaleText_loc5`='你覺得如何?殺殭屍之週?', `MaleText_loc7`='¿Cómo lo ves? ¿La matanza zombi de la semana?', `FemaleText_loc1`='어떻게 생각하세요? 이번 주 최고의 좀비 처치라고 하면요?', `FemaleText_loc4`='你在想什么？这个星期的任务是消灭僵尸？', `FemaleText_loc5`='你覺得如何?殺殭屍之週?', `FemaleText_loc7`='¿Cómo lo ves? ¿La matanza zombi de la semana?' WHERE `ID`=38646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라 이야기는 들어봤어? 거기에는 좀비가 없대.', `MaleText_loc4`='你听说过艾萨拉吗？那里没有僵尸。', `MaleText_loc5`='你聽過艾薩拉這個地方嗎?那裡沒有殭屍。', `MaleText_loc7`='¿Has oído hablar de Azshara? Allí no hay zombis.', `FemaleText_loc1`='아즈샤라 이야기는 들어보셨나요? 거기에는 좀비가 없대요.', `FemaleText_loc4`='你听说过艾萨拉吗？那里没有僵尸。', `FemaleText_loc5`='你聽過艾薩拉這個地方嗎?那裡沒有殭屍。', `FemaleText_loc7`='¿Has oído hablar de Azshara? Allí no hay zombies.' WHERE `ID`=38647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 말라고. 좀비가 찾는 건 뇌니까. 당신은 안전할 수밖에.', `MaleText_loc4`='别担心。僵尸喜欢有脑子的人，所以你是安全的。', `MaleText_loc5`='別擔心，殭屍喜歡吃腦子，你是很安全的。', `MaleText_loc7`='No te preocupes. Los zombis buscan cerebros. Tú estás a salvo.', `FemaleText_loc1`='걱정하지 마세요. 좀비가 찾는 건 뇌니까요. 당신은 안전할 수밖에 없어요.', `FemaleText_loc4`='别担心。僵尸喜欢有脑子的人，所以你是安全的。', `FemaleText_loc5`='別擔心，殭屍喜歡吃腦子，你是很安全的。', `FemaleText_loc7`='No te preocupes. Los zombis buscan cerebros. Tú estás a salvo.' WHERE `ID`=38648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기다!', `MaleText_loc4`='烟鬼！', `MaleText_loc5`='帥呆了!', `MaleText_loc7`='¡Cañón!', `FemaleText_loc1`='연기에요!', `FemaleText_loc4`='烟鬼！', `FemaleText_loc5`='帥呆了!', `FemaleText_loc7`='¡Cañón!' WHERE `ID`=38649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의사전달은 신속히, 행동은 확실하게 하는 겁니다, $n.', `MaleText_loc4`='说话很容易，但行动才有力量，$n$g先生:女士; 。', `MaleText_loc5`='重點是快、狠、準，$n$g先生:女士;。', `MaleText_loc7`='La orden rápida y la acción veloz, $gseñor:señora; $n.' WHERE `ID`=38650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비가 오고 있어요.', `MaleText_loc4`='僵尸来了。', `MaleText_loc5`='殭屍來襲。', `MaleText_loc7`='Vienen los zombis.', `FemaleText_loc1`='좀비가 오고 있다고요.', `FemaleText_loc4`='僵尸来了。', `FemaleText_loc5`='殭屍來襲。', `FemaleText_loc7`='Vienen los zombis.' WHERE `ID`=38651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아요. 저기 예쁜 깃발 좀 보세요.', `MaleText_loc4`='好啊，看看这些漂亮的旗子。', `MaleText_loc5`='沒錯。看那些漂亮的旗幟。', `MaleText_loc7`='Cierto. Mira esas bonitas banderas.', `FemaleText_loc1`='맞아요. 저기 예쁜 깃발 좀 보세요.', `FemaleText_loc4`='好啊，看看这些漂亮的旗子。', `FemaleText_loc5`='沒錯。看那些漂亮的旗幟。', `FemaleText_loc7`='Cierto. Mira esas bonitas banderas.' WHERE `ID`=38652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블레인, 해안포에 신호를 보내면 $n 님이 지금 멋지게 도착 중임을 훼산이 알 수 있을 거요.', `MaleText_loc4`='布兰恩先生，向海岸炮兵阵地发信号，让维桑恩先生知道$n就要到了。好，就是现在。', `MaleText_loc5`='布雷因先生，發訊號給海岸砲台，讓維桑恩先生知道$n已經在路上了。動作快點，現在就去。', `MaleText_loc7`='Señor Blaine, haga una señal a las baterías de tierra para que el Sr. Whessan sepa que $n está de camino. Ahora tranquilamente.' WHERE `ID`=38653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜드로의 애완동물 상자', `MaleText_loc4`='兰德鲁的宠物笼', `MaleText_loc5`='藍卓的寵物盒', `MaleText_loc7`='Caja de mascotas de Landro', `FemaleText_loc1`='랜드로의 애완동물 상자', `FemaleText_loc4`='兰德鲁的宠物笼', `FemaleText_loc5`='藍卓的寵物盒', `FemaleText_loc7`='Caja de mascotas de Landro' WHERE `ID`=38654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 아래 서리날개 전당으로 가는 길을 막은 마지막 장벽에 도달했네. 신드라고사만이 리치 왕과 성스러운 보복의 길 사이를 가로막고 있지! 대체 무엇을 기다리나!?', `MaleText_loc4`='霜翼大厅前的最后一道屏障已经被我们击破了，$g小伙子:姑娘;。只有辛达苟萨还挡在正义之师和巫妖王之间！还等什么？！', `MaleText_loc5`='我們搞定了進入霜翼大廳的最後一道屏障，$g小夥子:小姑娘;。現在只剩辛德拉苟莎擋在巫妖王還有我們神聖的復仇之前!你還在等什麼?!', `MaleText_loc7`='Hemos superado la barrera final que bloqueaba la entrada a Las Cámaras de Alaescarcha. $gchico:chica;. ¡Solo Sindragosa se interpone entre el Rey Exánime y el castigo divino! ¿A qué estás esperando?' WHERE `ID`=38655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진홍빛 전당으로 가는 장벽이 열렸군! 서리날개 전당으로 가는 장벽을 열 최고의 노움들이 나와 함께한다네. 보아하니 이번 일은 $4939W일 더 걸릴 듯하군! 당분간 그대들은 피의 공작과 그들의 여왕을 상대하는 게 좋겠네!', `MaleText_loc4`='血色厅堂的屏障已经击破，$g伙计:小姑娘;！我派出了最优秀的侏儒去对付霜翼大厅的屏障。看起来还要花$4939W天才能击破那里的屏障！现在，你们最好前去挑战那些鲜血王子和他们的女王！', `MaleText_loc5`='赤紅大廳的屏障已經被打開了，$g小夥子:小姑娘;!我已經讓我手下最高明的地精去處理霜翼大廳的屏障了。看來他們還需要$4939W天!現在，你最好去對付血親王還有他們的女王!', `MaleText_loc7`='La barrera hacia La Sala Carmesí está abierta, $gchico:chica;. Mis mejores gnomos están trabajando para abrir la barrera hacia Las Cámaras de Alaescarcha. ¡Parece que van a tardar otros $4939W días! De momento será mejor que te enfrentes a los príncipes de sangre y a su reina.' WHERE `ID`=38656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 저 문을 파괴하고 역병작업장으로 가는 입구를 막은 장벽을 무너뜨려 열었네! 우리 노움 친구들이 진홍빛 전당으로 가는 장벽을 허물려고 작업 중이지. 장벽이 열리기까지 $4939W일이 더 걸릴 걸세.$B$B그리로 가서 스컬지들을 없애버리게!', `MaleText_loc4`='我们已经击破了大门和阻挡在天灾工厂前面的屏障！我派出的侏儒正在对付血色厅堂前的屏障。冲破它还需要$4939W天。$B$B杀进去，给天灾军团点颜色看看！', `MaleText_loc5`='我們搞定了大門並且終於拆解了保護瘟疫工坊的屏障!我手下的地精會開始對付赤紅大廳的屏障。這大概還需要$4939W天。$B$B衝進工坊去解決一些天譴軍吧!', `MaleText_loc7`='¡Hemos echado la puerta abajo y la barrera que protegía la entrada a Los Talleres de la Peste quedó abierta! Mis gnomos están trabajando para derribar la barrera de Las Salas Carmesí. Tardarán otros $4939W en derribarla.$B$B¡Entra ahí y derrota algo de Plaga!' WHERE `ID`=38657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽이 모두 무너졌네, $n! 신드라고사만이 리치 왕과 우리 사이에 있을 뿐이야. 정의는 곧 실현될 걸세...', `MaleText_loc4`='所有的屏障都被击破了，$n！只有辛达苟萨还挡在我们和巫妖王之间。审判即将开始…', `MaleText_loc5`='所有的屏障現在全都被拆解了，$n!只剩辛德拉苟莎阻擋在我們和巫妖王之間。很快正義即將到來...', `MaleText_loc7`='¡Todas las barreras han caído, $n! Solo Sindragosa se interpone entre el Rey Exánime y nosotros. Se acerca la justicia...' WHERE `ID`=38658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진홍빛 전당으로 가는 길을 막은 장벽이 부서졌네. 피의 공작과 그들의 여왕이 우리의... 도착을 기다리고 있네. 바로 상대해 주자고.$B$B서리날개 전당으로 가는 길을 막은 최후의 장벽은 $4939W일 후에 파괴될 걸세.', `MaleText_loc4`='阻挡我们进入血色厅堂的屏障已经被击破。鲜血王子们和他们的女王在等待我们的…到来。我们别让他们等太久。$B$B挡在霜翼大厅前的那最后一道屏障将在$4939W天后被摧毁。', `MaleText_loc5`='保護赤紅大廳的屏障已經被摧毀了。血親王和他們的女王正等候我們的到來，別讓他們多等。$B$B最後一道屏障，保護霜翼大廳的屏障將會在$4939W天後被拆解。', `MaleText_loc7`='Han destrozado la barrera que cortaba el paso a Las Salas Carmesí. Los príncipes de sangre y su reina esperan nuestra... llegada. No les haremos esperar.$B$BLa última barrera que evita nuestro paso a Las Cámaras de Alaescarcha estará destruida en $4939W días.' WHERE `ID`=38659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린들이 마침내 첨탑의 상층 구역으로 가는 문을 파괴했네. 우리 마법사들 또한 성소 내의 세 개 구역의 첫 번째를 무력화하는 데 성공했지. 이제 역병작업장으로 가는 길이 열렸네. 그리로 가서 스컬지들을 박살 내게!$B$B$4939W일 뒤에 진홍빛 전당으로 가는 길을 가로막은 장벽을 걷어낼 수 있을 걸세.', `MaleText_loc4`='地精们终于设法打开了通往这座塔上层的大门。我们的法师也已经成功地关闭了密室三道屏障的第一道。通往天灾工厂的大门现在已经打开。冲进去，砸碎那些骨头！$B$B再过$4939W天，我们就应该能够冲破血色厅堂的屏障了。', `MaleText_loc5`='哥布林終於打開了大門讓我們可以通往尖塔上層。我們的法師也成功地拆解了聖所內三道屏障的第一道。現在可以進入瘟疫工坊了，進去裡頭並且踩爛那些骨頭!$B$B我們會在$4939W天後打開赤紅大廳前的屏障。', `MaleText_loc7`='Los goblins han conseguido derribar la puerta que llega a la parte superior de la aguja. Nuestros magos también han conseguido desactivar la primera de las tres barreras del sagrario. Ahora el acceso a Los Talleres de la Peste está abierto. ¡Entra y aplasta algunos cráneos!$B$BDeberíamos abrir la barrera de Las Salas Carmesí en $4939W días.' WHERE `ID`=38660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='不可能!', `MaleText_loc7`='¡Imposible!' WHERE `ID`=38661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 너무 강력하다! 투석기를 사용해라!', `MaleText_loc4`='他太强了！用投石车打倒他！', `MaleText_loc5`='他太強悍了!使用投石車打死他!', `MaleText_loc7`='¡Es demasiado fuerte! ¡Usen las catapultas!' WHERE `ID`=38662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_unstableaffliction_1.blp:16|t%s|1이;가; |cFFFF0000일촉즉발 실험|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_unstableaffliction_1.blp:16|t%s施放了|cFFFF0000危险实验！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_unstableaffliction_1.blp:16|t%s施展|cFFFF0000暴泥實驗!|r', `MaleText_loc7`='|TInterfaceIconsspell_shadow_unstableaffliction_1.blp:16|t ¡%s lanza |cFFFF0000Experimento volátil!|r' WHERE `ID`=38663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 리치 왕을 마주할 자격이 없다!', `MaleText_loc4`='你没有资格觐见巫妖王！', `MaleText_loc5`='你不配面對巫妖王!', `MaleText_loc7`='¡No eres digno de enfrentarte al Rey Exánime!' WHERE `ID`=38664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 장비, 내 소중한 장비만은 제발!', `MaleText_loc4`='我的设备……不，我美丽的设备！', `MaleText_loc5`='不要啊!我美麗的裝備!不要啊!', `MaleText_loc7`='¡Mis engranajes no! ¡Mis preciosos engranajes no!' WHERE `ID`=38665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗! 그건 제독님의 은 제품!', `MaleText_loc4`='嗨！那可是司令最好的银餐具！', `MaleText_loc5`='嘿!那是上將最好的銀器!', `MaleText_loc7`='¡Oye! ¡Esa es la mejor plata del almirante!' WHERE `ID`=38666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종말을 안겨주마. 망각으로... 사라져라.', `MaleText_loc4`='末日降临。万劫…不复。', `MaleText_loc5`='末日降臨。進入...消亡吧。', `MaleText_loc7`=' Su fin se acerca. ¡Bienvenidos al OLVIDO!' WHERE `ID`=38667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 더 싸울 수 있겠느냐?', `MaleText_loc4`='你能抵挡多久？', `MaleText_loc5`='你還能支持多久?', `MaleText_loc7`='¿Cuánto podrán resistirse?' WHERE `ID`=38668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 부하들아! 지나가게 하지 마라!', `MaleText_loc4`='苏醒吧，奴仆们。拦住他们。', `MaleText_loc5`='甦醒吧，爪牙們!別讓他們越雷池一步!', `MaleText_loc7`='Alzaos, esbirros. Que no pasen.' WHERE `ID`=38669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡아라, 부하들아. 나에게 그놈들 시체를 가져와라.', `MaleText_loc4`='奴仆们，抓住他们！带他们的尸体来见我！', `MaleText_loc5`='爪牙們 - 捉住他們!帶回他們的屍體。', `MaleText_loc7`='¡Lacayos, atrápenlos! Tráiganme sus cadáveres.' WHERE `ID`=38670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석군. 내가 오래전에 죽여버린 자를 찾다니. 그는 이제 그저 유령일 뿐이다. 내 마음에 울리는 희미한 메아리지...', `MaleText_loc4`='你要找那个早就被我干掉的家伙吗？现在他只是一个幽魂，一个我脑中微弱的回音……', `MaleText_loc5`='傻女孩。你想找的老早就被我殺死了。他現在不過是個鬼魂。一個在我腦中的微弱回音...', `MaleText_loc7`='¡Niñata estúpida! Buscas algo que maté hace tiempo. Un débil eco en mi mente.' WHERE `ID`=38671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; $n에게 얼어붙은 구슬을 발사합니다!', `FemaleText_loc4`='%s向$n掷出一颗冰冻宝珠！', `FemaleText_loc5`='%s朝著$n的方向施放了冰霜之球!', `FemaleText_loc7`='¡%s dispara un orbe congelado hacia $n!' WHERE `ID`=38672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 상황이 꽤 빡빡하다고, $n.', `MaleText_loc4`='我们在这里的情况相当糟糕，$n。', `MaleText_loc5`='我們現在的狀況蠻糟的, $n。', `MaleText_loc7`='Estamos metidos en un buen lío, $n.' WHERE `ID`=38673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 일을 하겠다고는 절대로 서명하지 않았어요! 소인족에 좀비라니... 호바트 박사님은 제 봉급을 엄청나게 올려주셔야 해요!', `FemaleText_loc4`='我确定合同里没提过会遇到这种情况！俾格米人，僵尸……这次霍巴特一定要把我晋升到一个足够高的职位才行！', `FemaleText_loc5`='我絕對沒有同意要做這種差事!俾格米...殭屍...荷巴爾特最好大幅地提高我的加薪幅度!', `FemaleText_loc7`='¡Desde luego que no me alisté para esto! Pigmeos, zombis... ¡Más vale que Hobart me suba mucho el sueldo!' WHERE `ID`=38674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이보다 더 나빠질 순 없겠어요...', `FemaleText_loc4`='我本来以为情况不可能更糟了……', `FemaleText_loc5`='就在我認為事情不會變得更糟糕的時候...', `FemaleText_loc7`='Justo cuando pensaba que la cosa no podía ponerse peor...' WHERE `ID`=38675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위에서 뭘 하고 있어? 이 섬을 벗어날 방법을 찾아야 하지 않아?', `MaleText_loc4`='我们待在这里干什么？难道我们不应该想办法离开这座岛吗？！！！', `MaleText_loc5`='你在上面幹什麼?我們不是應該尋求離開這個島的方法嗎?', `MaleText_loc7`='¿Qué haces aquí? ¡¡¡¿No deberías estar buscando una forma de salir de esta isla?!!!' WHERE `ID`=38676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상자 마을은 기계공학이 가져다준 선물이야! 아주 끝내주지!', `MaleText_loc4`='胶囊镇实在是工程学上的一项伟大成就！', `MaleText_loc5`='這個盒中鎮是工程學上的一大成就!', `MaleText_loc7`='¡Esta Ciudad de Bolsillo es toda una hazaña de ingeniería!' WHERE `ID`=38677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 죽음의 역병에 걸렸습니다!', `MaleText_loc4`='$n感染了死亡疫病！', `MaleText_loc5`='$n被死亡瘟疫所感染!', `MaleText_loc7`='¡$n está infectado con Peste mortífera!' WHERE `ID`=38679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자여, 지금은 잡담할 때가 아니다. 지금은 임무 수행 중이 아닌가.', `MaleText_loc4`='现在不是闲聊的时候，侍从$n。我们正在执行任务。', `MaleText_loc5`='現在不是閒聊的最佳時間，侍從$n。我們正在進行一個任務。', `MaleText_loc7`='Ahora no es momento de parlotear, $gescudero:escudera;, $n. Estamos en medio de una misión.' WHERE `ID`=38680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사! 발사!', `MaleText_loc4`='开火！开火！', `MaleText_loc5`='開火!開火!', `MaleText_loc7`='¡FUEGO! ¡FUEGO!' WHERE `ID`=38681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 내부 성소로 들어왔다. 서둘러 녹색용을 파멸시켜라! 되살려 낼 때 쓸 뼈와 힘줄만 남겨라!', `MaleText_loc4`='入侵者闯入了内室。加紧毁掉那条绿龙！留下龙筋龙骨用来复生！', `MaleText_loc5`='入侵者已經突破了內部聖所。加快摧毀綠龍的速度!只要留下骨頭和肌腱來復活!', `MaleText_loc7`='Hay Intrusos en el Sagrario Interior. ¡Apresuren la destrucción del dragón verde! ¡Dejen sólo huesos y tendones para la reanimación!' WHERE `ID`=38682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악한 용의 여왕을 찾는 모험을 지금 시작한다. 길을 떠나자, 종자여!', `MaleText_loc4`='我们要继续前进，找到邪恶的巨龙女王。跟我来，侍从！', `MaleText_loc5`='我們將進軍搜尋龍族卑鄙的育母。跟著我，侍從!', `MaleText_loc7`='Partimos en busca de la vil madre de linaje de los dragones. ¡Sígueme, escudero!' WHERE `ID`=38683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자여, 내 종마의 발구르기 기술을 시험해 보아라. 그 강력한 발굽이 땅을 가르면, 주변의 모든 용이 기절하고 말 것이다.', `MaleText_loc4`='你应该使用我的坐骑的蹬踏能力。她强有力的蹄子能够踏碎大地，也能把附近的龙全部震晕。', `MaleText_loc5`='你應該試著用我戰馬的踐踏能力。她強而有力的馬蹄可以把大地震裂，擊暈附近的龍。', `MaleText_loc7`='Deberías intentar utilizar la habilidad pisotón de mi semental. Sus poderosos cascos sacudirán la tierra y aturdirán a los dragones cercanos.' WHERE `ID`=38684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋았군! 피멘토의 발구르기 덕에 강력한 용에게 던질 돌덩이가 생겼다. 오오, 영광스러운 날이로다!', `MaleText_loc4`='运气真好！多香果的蹄子踢起来一些石头，用来对付那些龙正合适。真是愉快的一天！', `MaleText_loc5`='運氣太好了!皮曼托的蹄踢起了一些石頭讓我們可以拿來對付力量強大的龍。噢!多麼光榮的一天!', `MaleText_loc7`='¡Qué suerte! Los cascos de Rocilante han desenterrado piedras que podremos utilizar contra los dragones. ¡Oh, qué día más glorioso!' WHERE `ID`=38685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 용이 보인다. 예상했던 것보다 훨씬 더 크군.', `MaleText_loc4`='我看见恶龙就在前面。她比我预料得更大。', `MaleText_loc5`='我看見龍就在前方。她比我原先預期的還要巨大。', `MaleText_loc7`='Veo al dragón ahí delante. Es más grande de lo que pensaba.' WHERE `ID`=38686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여! 내 말을 들어라! 나는 네게 영원한 안식을 안겨 줄 북녘골의 맥시밀리언이다. 너의 피가...', `MaleText_loc4`='恶龙！听我说！我是北郡的麦斯米兰。我将对你进行正义的审判。你必死无疑……', `MaleText_loc5`='飛龍!仔細聽好了!我是北郡的瑪克西米利安，我是來消滅你的。你的鮮血將瀰漫...', `MaleText_loc7`='¡Dragón! ¡Atiende! Soy Maximilian de Villanorte y he venido a darte muerte. Tu sangre llenará...' WHERE `ID`=38687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 우서 경의 영혼이여! 용이 우리를 쫓는다! 종자여, 뭐라도 해 보아라! 돌을 던져! 나는 모르겠다!', `MaleText_loc4`='伟大的乌瑟尔之灵，它在追赶我！侍从，想想办法！向它扔石头！我该怎么办？！', `MaleText_loc5`='偉大的烏瑟之靈，它在追著我們!侍從，快做點什麼!對它丟石頭!我毫無頭緒!', `MaleText_loc7`='¡Genial! Nos persigue el fantasma de Uther. ¡Escudero, haz algo! ¡Tírale piedras! ¡No tengo ningún plan!' WHERE `ID`=38688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 좋은 생각이 있다! 빛의 축복을 받은 내 방패를 놈에게 던져라!', `MaleText_loc4`='等等，我有主意了！给，用我受过圣光祝福的盾牌去砸那个怪兽！', `MaleText_loc5`='等等，我有個主意!拿著，把我的聖光祝福之盾丟向那頭怪獸!', `MaleText_loc7`='¡Espera, tengo una idea! ¡Toma! ¡Lánzale a la bestia mi escudo bendecido por la Luz!' WHERE `ID`=38689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방패를 던지니 꽤 효과가 좋군. 어서, 내 신성한 어깨갑옷도 던져라!', `MaleText_loc4`='那个盾牌扔得真好。快，再把我的神圣肩甲扔过去！', `MaleText_loc5`='丟盾牌這招帶來的效果出奇地好。快點，扔擲我的神聖肩甲!', `MaleText_loc7`='Lo de lanzar el escudo ha funcionado bastante bien. ¡Deprisa! ¡Lanza mis hombreras de placas sagradas!' WHERE `ID`=38690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까스로 장갑을 벗었다. 우리 적에게 던져 버리거라!', `MaleText_loc4`='我把手套也脱下来了。快用它来砸我们的敌人。', `MaleText_loc5`='我已經把手套脫下來了。你可以將它們扔向我們的敵人。', `MaleText_loc7`='He conseguido quitarme los guantes. Puedes tirárselos a nuestro enemigo.' WHERE `ID`=38691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무거운 장화에 달린 철굽이라면 꽤 큰 피해를 줄 수 있겠지.', `MaleText_loc4`='我的钢板靴子一定能对敌人造成非常严重的伤害。', `MaleText_loc5`='我戰靴的鐵後跟應該能造成毀滅性傷害。', `MaleText_loc7`='El talón de hierro de la bota de mi armadura puede ser muy destructivo.' WHERE `ID`=38692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 한쪽 어깨갑옷도 받아라, 나쁜 도마뱀아!', `MaleText_loc4`='再吃我一记肩甲，邪恶的蜥蜴！', `MaleText_loc5`='嚐嚐我的另一個肩甲吧，邪惡的蜥蜴!', `MaleText_loc7`='¡Cómete mis hombreras de placas, vil lagarto!' WHERE `ID`=38693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가슴보호갑을 벗길 수 있겠나? 어서 벗겨서 던져! 돌로리아를 위하여!', `MaleText_loc4`='如果你能举起我的胸甲，就把它扔出去！为了多罗莉亚把它扔出去！', `MaleText_loc5`='如果你可以舉起我的胸甲，就快扔過去!為了朵莉亞，將它扔出!', `MaleText_loc7`='¡Si puedes con mi coraza, tírasela! ¡Tírasela por Doloria!' WHERE `ID`=38694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문득 창피해지는군... 춥기도 하고. 이 다리갑옷으로 치명타를 입히면 좋겠는데.', `MaleText_loc4`='这副样子可不好看……不过很凉快。希望我的腿甲能对敌人造成致命一击。', `MaleText_loc5`='這真是羞辱人啊...感覺也涼涼的。希望我的腿鎧能給它致命的一擊。', `MaleText_loc7`='Esto se está convirtiendo en algo humillante... y expuesto. Espero que mis quijotes den el golpe de gracia.' WHERE `ID`=38695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈어! 운고로가 정화되었다!', `MaleText_loc4`='我们成功了！安戈洛得到了净化。', `MaleText_loc5`='我們辦到了!安戈洛已被淨化了。', `MaleText_loc7`='¡Lo hemos conseguido! Hemos purificado Un''Goro.' WHERE `ID`=38696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종자여, 내 야영지에서 보상을 받아라.', `MaleText_loc4`='侍从，去我的营地找我，接受我的酬金吧。', `MaleText_loc5`='侍從，回到我的營地找我以領取你的獎賞。', `MaleText_loc7`='Escudero, reúnete conmigo en mi campamento para recibir tu recompensa.' WHERE `ID`=38697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, $n! 끝내주진 않아도 괜찮았습니다.', `MaleText_loc4`='好啊，$n！这不中看，但是很中用。', `MaleText_loc5`='太棒了，$n!不是做得很漂亮，但至少成功了。', `MaleText_loc7`='¡Bravo, $n! No ha sido agradable, pero ha funcionado.' WHERE `ID`=38698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변의 용에게 돌덩이를 던져 보아라. 연습을 좀 해두는 편이 나을 테니.', `MaleText_loc4`='也许你应该试着将它们抛向附近的恶龙。这样也可以锻炼你的臂力。', `MaleText_loc5`='或許你應該將它們丟向附近的飛龍以練習你扔擲護甲的技術。', `MaleText_loc7`='Quizá debas practicar tu lanzamiento apedreando a los dragones cercanos.' WHERE `ID`=38699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥시밀리언이 방패를 넘겼습니다. 방패를 데빌사우루스... 아니, 용을 향해 던지십시오!', `MaleText_loc4`='麦斯米兰把他的盾牌交给你。把它向那头魔暴龙，呃，……那头恶龙扔过去！', `MaleText_loc5`='瑪克西米利安把他的盾牌交給了你。把它丟向魔暴龍!呃...丟向噴火龍!', `MaleText_loc7`='Maximillian te ha entregado su escudo. ¡Tíraselo al demosaurio! Ehm... ¡Dragón!' WHERE `ID`=38700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 맥시밀리언의 갑옷을 던지십시오!', `MaleText_loc4`='不住手地扔出麦斯米兰的铠甲！', `MaleText_loc5`='不停地扔擲瑪克西米利安的護甲!', `MaleText_loc7`='¡Sigue arrojando partes de la armadura de Maximilian!' WHERE `ID`=38701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 체력이 떨어진 것 같구나. 내가 도와주겠다.', `MaleText_loc4`='你的生命值太低了。请让我帮助你。', `MaleText_loc5`='你的生命力越來越弱了。讓我來幫你吧。', `MaleText_loc7`='Tu salud flaquea. Permite que te ayude.' WHERE `ID`=38702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붕대에서 젖은 개털 냄새가 나는데?', `MaleText_loc4`='为什么这些绷带闻起来有一股汗臭味？', `MaleText_loc5`='為什麼這些繃帶聞起來有種騷臭味?', `MaleText_loc7`='¿Por qué huelo a perro mojado con estas vendas?' WHERE `ID`=38703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소. 이곳은 학살 현장으로 변해가고 있소.', `MaleText_loc4`='谢谢。我们已经损失惨重……', `MaleText_loc5`='謝謝你，這差點就變成了一場大屠殺...', `MaleText_loc7`='Gracias. Esto se estaba convirtiendo en una masacre...' WHERE `ID`=38704;
