UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌지워터 무역회사 구명로켓을 입거나, 잡고 있거나 또는 다른 용도로 사용하시는 것은 이 제품의 최종 사용자 사용권 계약의 내용에 동의하시는 거예요!', `FemaleText_loc4`='为佩戴，握持或以其它方式使用锈水财阀求生火箭，你同意接受此最终用户协议的全部条款！', `FemaleText_loc5`='在穿上、握住或使用了這個污水企業聯合救生火箭後，你同意並接受此份使用者授權合約!', `FemaleText_loc7`='Al ponerte, sostener o simplemente usar este cohete salvavidas del Cártel Pantoque, aceptas todos los términos del contrato de licencia del usuario final.' WHERE `ID`=38709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 구명로켓에는 2년의 사용 기간과 무료 비중재 계약이 포함됩니다!', `FemaleText_loc4`='每个求生火箭的合同期为两年，一切合同条款最终解释权以及仲裁权属于锈水财阀！', `FemaleText_loc5`='所有的救生火箭都帶有兩年的保固合約和免費非仲裁條款!', `FemaleText_loc7`='¡Cada cohete salvavidas viene con una garantía de dos años y una cláusula que impide el arbitraje!' WHERE `ID`=38710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌지워터 무역회사가 계속되는 여러분의 선구매에 감사드려요!', `FemaleText_loc4`='锈水财阀感谢您使用本企业产品，并期待您继续购买本企业产品！', `FemaleText_loc5`='污水企業聯合謝謝你對我們產品的愛戴!', `FemaleText_loc7`='El Cártel Pantoque te agradece tus futuras frecuentes compras.' WHERE `ID`=38711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분께서 육지에 착륙하는 즉시 빌지워터 무역회사의 담당자들이 사용 요금 지불 계획을 상담해 드릴 거예요!', `FemaleText_loc4`='只要你一落地，我们的锈水财阀代表就会帮助你确定合适的酬金计划！', `FemaleText_loc5`='我們污水企業聯合的代表將在您登陸後馬上為您選擇最適合的付費專案!', `FemaleText_loc7`='¡Los representantes de nuestro Cártel Pantoque esperan para ayudarte a encontrar el programa de pago que más se adecúe a ti en cuanto toques tierra!' WHERE `ID`=38712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비행하시는 동안 첨부된 문서를 모두 작성하시는 걸 잊지 마세요!', `FemaleText_loc4`='请一定在飞行过程中填写好全部的相关文件！', `FemaleText_loc5`='請在您飛行時填好所有的相關手續文件。', `FemaleText_loc7`='¡Durante el vuelo, asegúrate de rellenar todo el papeleo que viene incluido!' WHERE `ID`=38713;
