UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리 양, 왜 강력 추진기 로켓 장화는 좀비한테만 쓸 수 있는 겁니까?', `MaleText_loc4`='格瑞里，为什么超级助推火箭之靴只对僵尸有用？', `MaleText_loc5`='格里利，為什麼超級增壓火箭靴只對殭屍有用?', `MaleText_loc7`='Greely, ¿por qué las botas con súper cohetes propulsores solo funcionan con los zombis?', `FemaleText_loc1`='그릴리 양, 왜 강력 추진기 로켓 장화는 좀비한테만 쓸 수 있는 거지요?', `FemaleText_loc4`='格瑞里，为什么超级助推火箭之靴只对僵尸有用？', `FemaleText_loc5`='格里利，為什麼超級增壓火箭靴只對殭屍有用?', `FemaleText_loc7`='Greely, ¿por qué las botas con súper cohetes propulsores solo funcionan con los zombis?' WHERE `ID`=38722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런 질문을 해 주시다니 너무나 기쁘네요, $n 님! $B$B그 장화가 어떻게 작동하는지 묻는 사람이 아무도 없었거든요. 그건 바로 여기 말이죠. 그냥 제게 주세요. 제가 불어 볼 테니까요. 자세한 내용을 설명하느라 서로 지루해질 필요는 없겠죠. 그냥 요점만 딱 집어 말할게요. 그보다 더 나쁜 건 아직 말 안 했어요. 장화가 어떻게 작동하는지 누가 상관이나 하겠어요. 지난번보다 폭발이 더 크게 일어나나요?$B$B까놓고 말해서 가끔 소리라도 지를 수 있으면 좋겠다는 거 아세요? 언제나 호바트 박사님의 일을 제가 혼자 다 하는데 보상은 하나도 없잖아요! 이제까지 감사도 별로 못 받고, 엄청나게 추가로 근무하는 데다가 월급도 엄청나게 적게 받는 땜장이 보조였어요!$B$B잠깐만요, 질문이 뭐였죠?', `FemaleText_loc4`='很高兴你这样问，$n！$B$B还从来没有人来问过这东西是怎么运作的。他们要不来了就说：“把它给我，我要炸东西了。”要不就是：“别拿那些细节的事情来烦我，我只需要瞄准和射击。”还有更糟的：“谁在乎它是怎么运作的，这次爆炸不是比上一次更壮观吗？”$B$B我发誓，有时候我真的很想尖叫。霍巴特总是把他的工作全都扔给我，我辛辛苦苦地做完了，却根本得不到承认！我一定是最不被承认，最过劳，所得报酬最不合理的工匠助手！$B$B等等，你刚才在问什么？', `FemaleText_loc5`='我很高興你問了，$n!$B$B從來沒有人提出過這種問題，大家早就習以為常，反正東西有得用就好了。把那給我，我要炸爛一些東西。或者是:別跟我講那麼多有的沒的，讓我瞄準後發射就好了。誰會管那麼多細節，這次的爆炸比上次還來得大嗎?$B$B我發誓，有的時候我真的好想大聲尖叫，你知道嗎?荷巴爾特所有的事情幾乎都是我在做的，可是我從來沒有獲得什麼獎勵!我一定是有史以來最不受重視，加班時間最長和拿的錢最少的工匠助手了!$B$B啊，你想問什麼?', `FemaleText_loc7`='¡Me alegra mucho que preguntes, $n!$B$BNadie me pregunta jamás cómo funcionan las cosas. Se limitan a está aquí, dame eso, voy a hacer que explote. O, no me aburras con los detalles, déjame apuntar y disparar. O, aún peor, a quién le importa cómo funcione, ¿es una explosión mayor que la última vez?$B$BJuro que, a veces, podría gritar, ¿sabes? ¡Siempre hago el trabajo de Hobart, pero nunca me llevo el mérito! ¡Tengo que ser la ayudante de manitas más menospreciada, más explotada y con el peor sueldo de la historia!$B$BEspera, ¿qué me habías preguntado?' WHERE `ID`=38723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥시밀리언 님, 이제 출발할 준비가 되었습니다.', `MaleText_loc4`='麦斯米兰，我已经做好了出发的准备。', `MaleText_loc5`='瑪克西米利安，我們準備好要上路了。', `MaleText_loc7`='Maximillian, estoy listo para cabalgar.', `FemaleText_loc1`='맥시밀리언 님, 이제 출발할 준비가 되었습니다.', `FemaleText_loc4`='麦斯米兰，我已经做好了出发的准备。', `FemaleText_loc5`='瑪克西米利安，我們準備好要上路了。', `FemaleText_loc7`='Maximillian, estoy lista para cabalgar.' WHERE `ID`=38724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 배를 건조하는 걸 좋아해서 다행이야. 해적들은 그걸 날려 먹는 걸 좋아하니까.', `MaleText_loc4`='幸好我很喜欢建造船只，因为那些海盗总喜欢把船炸飞。', `MaleText_loc5`='我喜歡建造船隻是件好事，因為這些海盜愛把自己炸爛。', `MaleText_loc7`='Menos mal que me encanta construir barcos, porque a estos piratas les encanta destrozarlos.' WHERE `ID`=38725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕스가 배를 가지고 오라고 저를 보냈습니다.', `MaleText_loc4`='梅格斯派我来取一艘小艇。', `MaleText_loc5`='梅格斯送我來拿一艘船。', `MaleText_loc7`='Megs me envía a por un barco.', `FemaleText_loc1`='맥스가 배를 가지고 오라고 저를 보냈습니다.', `FemaleText_loc4`='梅格斯派我来取一艘小艇。', `FemaleText_loc5`='梅格斯送我來拿一艘船。', `FemaleText_loc7`='Megs me envía a por un barco.' WHERE `ID`=38726;
