UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빵은 필요 없습니다. 우린 그저 아가씨가 목소리 좀 줄여주기만을 바랄 뿐입니다.', `MaleText_loc4`='没有人想要你的面包，女士。我们只想你能安静一些。', `MaleText_loc5`='沒有人想要妳的麵包，女士。我們只想要妳降低妳的音量。', `MaleText_loc7`='Nadie quiere tu pan, señora. Lo que queremos es que bajes la voz.', `FemaleText_loc1`='빵은 필요 없어요. 우린 그저 아가씨가 목소리 좀 줄여주기만을 바랄 뿐이에요.', `FemaleText_loc4`='没有人想要你的面包，女士。我们只想你能安静一些。', `FemaleText_loc5`='沒有人想要妳的麵包，女士。我們只想要妳降低妳的音量。', `FemaleText_loc7`='Nadie quiere tu pan, señora. Lo que queremos es que bajes la voz.' WHERE `ID`=38734;
