UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 아무리 애써봤자 눈 하나 깜짝 안 한다, 바스툰. 이놈은 내가 맡지.', `MaleText_loc4`='呸！你的影子吓唬不了任何人，巴斯东。这家伙是我的了。', `MaleText_loc5`='嘿!你的暗影魔法是嚇不到人的，巴斯通。這隻是我的獵物。', `MaleText_loc7`='¡BAH! Tus sombras no asustan a nadie, Bastún. Este es mío.' WHERE `ID`=38748;
