UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라 20cc, 서둘러 가져다줘! 아니, 환자 말고... 내가 마실 거!', `MaleText_loc4`='20毫升卡亚可乐，注射！不是给病人……是给我！', `MaleText_loc5`='20cc的卡迦可樂，馬上!不是給病人...是我要喝的!', `MaleText_loc7`='¡Veinte centímetros cúbicos de Kaja''Cola, rápido! ¡Para el paciente no... para mí!' WHERE `ID`=38782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 파이 상인. 우리가 지켜보고 있다고.', `MaleText_loc4`='我已经注意到你了，馅饼小贩。', `MaleText_loc5`='我們在注意你的舉動，餡餅商人。', `MaleText_loc7`='No te quitamos la vista de encima, vendedor de tartas.', `FemaleText_loc1`='이봐요, 파이 상인. 우리가 지켜보고 있어요.', `FemaleText_loc4`='我已经注意到你了，馅饼小贩。', `FemaleText_loc5`='我們在注意你的舉動，餡餅商人。', `FemaleText_loc7`='No te quitamos la vista de encima, vendedor de tartas.' WHERE `ID`=38783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 누군지 다 알아. 그 향수하며 장미 꽃잎까지. 조심하라고!', `MaleText_loc4`='我们全都认识你，还有这种香气和玫瑰花瓣。它多漂亮啊！', `MaleText_loc5`='我們知悉你的一切，還有這香水，這玫瑰花瓣。看招!', `MaleText_loc7`='Lo sabemos todo sobre ti, el perfume y los pétalos de rosa. ¡Así que ojo!', `FemaleText_loc1`='당신이 누군지 다 알아요. 그 향수하며 장미 꽃잎까지. 조심하세요!', `FemaleText_loc4`='我们全都认识你，还有这种香气和玫瑰花瓣。它多漂亮啊！', `FemaleText_loc5`='我們知悉你的一切，還有這香水，這玫瑰花瓣。看招!', `FemaleText_loc7`='Lo sabemos todo sobre ti, el perfume y los pétalos de rosa. ¡Así que ojo!' WHERE `ID`=38784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파이 상인, 우리가 두 눈 똑똑히 뜨고 지켜본다고.', `MaleText_loc4`='我们在注意你，馅饼小贩。', `MaleText_loc5`='我們正在注意你，餡餅商人。', `MaleText_loc7`='Te vigilamos, vendedor de tartas.', `FemaleText_loc1`='파이 상인, 우리가 두 눈 똑똑히 뜨고 지켜본다고요.', `FemaleText_loc4`='我们在注意你，馅饼小贩。', `FemaleText_loc5`='我們正在注意你，餡餅商人。', `FemaleText_loc7`='Te vigilamos, vendedor de tartas.' WHERE `ID`=38785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하는 게 좋아, 파이 상인. 지금 화를 자초하는 거야.', `MaleText_loc4`='小心，馅饼小贩。不要惹祸上身。', `MaleText_loc5`='注意自己的一舉一動，餡餅商人。小心玩火自焚。', `MaleText_loc7`='Ten mucho cuidado, vendedor de tartas. Estás flirteando con el desastre.', `FemaleText_loc1`='조심하는 게 좋아요, 파이 상인. 지금 화를 자초하는 거예요.', `FemaleText_loc4`='小心，馅饼小贩。不要惹祸上身。', `FemaleText_loc5`='注意自己的一舉一動，餡餅商人。小心玩火自焚。', `FemaleText_loc7`='Ten mucho cuidado, vendedor de tartas. Estás flirteando con el desastre.' WHERE `ID`=38786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 파는 파이에 항의가 계속 들어온다고. 똑바로 하란 말이야!', `MaleText_loc4`='我们已经收到了一些关于你的馅饼的投诉。你做事可要小心一些！', `MaleText_loc5`='關於你的派，我們收到了一些抱怨投訴。給我收乾淨!', `MaleText_loc7`='Hemos recibido algunas quejas sobre tus tartas. ¡Será mejor que te enmiendes!', `FemaleText_loc1`='당신이 파는 파이에 항의가 계속 들어온다고요. 똑바로 하란 말이에요!', `FemaleText_loc4`='我们已经收到了一些关于你的馅饼的投诉。你做事可要小心一些！', `FemaleText_loc5`='關於你的派，我們收到了一些抱怨投訴。給我收乾淨!', `FemaleText_loc7`='Hemos recibido algunas quejas sobre tus tartas. ¡Será mejor que te enmiendes!' WHERE `ID`=38787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과일 상인, 목소리 낮춰!', `MaleText_loc4`='安静些，水果贩子！', `MaleText_loc5`='安靜!水果小販!', `MaleText_loc7`='¡Baja la voz, frutero!', `FemaleText_loc1`='과일 상인, 목소리 낮춰요!', `FemaleText_loc4`='安静些，水果贩子！', `FemaleText_loc5`='安靜!水果小販!', `FemaleText_loc7`='¡Baja la voz, frutero!' WHERE `ID`=38788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 때문에 시끄럽다는 얘기가 계속 들어온다고. 조용히 좀 해!', `MaleText_loc4`='很多人都在抱怨你过于吵闹。安静一些！', `MaleText_loc5`='一直有人向我們回報，說你的噪音太大。安靜點!', `MaleText_loc7`='Hemos recibido informes sobre el ruido que haces. ¡Baja la voz!', `FemaleText_loc1`='당신 때문에 시끄럽다고 얘기가 계속 들어온다고요. 조용히 좀 해요!', `FemaleText_loc4`='很多人都在抱怨你过于吵闹。安静一些！', `FemaleText_loc5`='一直有人向我們回報，說你的噪音太大。安靜點!', `FemaleText_loc7`='Hemos recibido informes sobre el ruido que haces. ¡Baja la voz!' WHERE `ID`=38789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 떠드는 소리만큼이나 과일도 형편없다고 항의가 들어온단 말이야.', `MaleText_loc4`='我们已经收到投诉，说你的水果不像你所宣扬的那样新鲜。', `MaleText_loc5`='有人抱怨說你的水果並不如你說得那樣新鮮。', `MaleText_loc7`='Hemos recibido quejas de que la fruta que vendes no es tan fresca como afirmas.', `FemaleText_loc1`='당신이 떠드는 소리만큼이나 과일도 형편없다고 항의가 들어온단 말이에요.', `FemaleText_loc4`='我们已经收到投诉，说你的水果不像你所宣扬的那样新鲜。', `FemaleText_loc5`='有人抱怨說你的水果並不如你說得那樣新鮮。', `FemaleText_loc7`='Hemos recibido quejas de que la fruta que vendes no es tan fresca como afirmas.' WHERE `ID`=38790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상한 사과를 판다고 들었어.', `MaleText_loc4`='我们听说，你正在贩卖一些坏掉的苹果。', `MaleText_loc5`='我們聽說你賣的是爛蘋果。', `MaleText_loc7`='Hemos oído que vendes manzanas podridas.', `FemaleText_loc1`='상한 사과를 판다고 들었어요.', `FemaleText_loc4`='我们听说，你正在贩卖一些坏掉的苹果。', `FemaleText_loc5`='我們聽說你賣的是爛蘋果。', `FemaleText_loc7`='Hemos oído que vendes manzanas podridas.' WHERE `ID`=38791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 지켜보는 중이야, 고기 상인.', `MaleText_loc4`='我们正在注意你，肉贩子。', `MaleText_loc5`='我們正在注意你，肉商。', `MaleText_loc7`='Te vigilamos, carnicero.', `FemaleText_loc1`='우리가 지켜보는 중이에요, 고기 상인.', `FemaleText_loc4`='我们正在注意你，肉贩子。', `FemaleText_loc5`='我們正在注意你，肉商。', `FemaleText_loc7`='Te vigilamos, carnicero.' WHERE `ID`=38792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기 상인, 이 근처에서 행동 조심하라고.', `MaleText_loc4`='在这里做买卖可要小心一点，肉贩子。', `MaleText_loc5`='自己小心點，肉商。', `MaleText_loc7`='Ten mucho cuidado con nosotros, carnicero.', `FemaleText_loc1`='고기 상인, 이 근처에서 행동 조심하시죠.', `FemaleText_loc4`='在这里做买卖可要小心一点，肉贩子。', `FemaleText_loc5`='自己小心點，肉商。', `FemaleText_loc7`='Ten mucho cuidado con nosotros, carnicero.' WHERE `ID`=38793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상한 고기를 먹고 탈이 났다는 보고를 받았어. 지켜보겠어, 고기 상인!', `MaleText_loc4`='我们得到报告，有不少人因为吃了腐败的肉食而生病了。我们会盯着你的，肉贩子！', `MaleText_loc5`='我們收到報告，人們吃了劣質肉品然後生病。我們正在注意你，肉商。', `MaleText_loc7`='Hemos recibido informes de que hay gente que se ha puesto enferma por tu carne podrida. ¡Te vigilamos, carnicero!', `FemaleText_loc1`='상한 고기를 먹고 탈이 났다는 보고를 받았어요. 지켜보겠어요, 고기 상인!', `FemaleText_loc4`='我们得到报告，有不少人因为吃了腐败的肉食而生病了。我们会盯着你的，肉贩子！', `FemaleText_loc5`='我們收到報告，人們吃了劣質肉品然後生病。我們正在注意你，肉商。', `FemaleText_loc7`='Hemos recibido informes de que hay gente que se ha puesto enferma por tu carne podrida. ¡Te vigilamos, carnicero!' WHERE `ID`=38794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 조심하는 게 좋아, 고기 상인.', `MaleText_loc4`='要记住你是在什么地方，肉贩子。', `MaleText_loc5`='走路要看路，肉商。', `MaleText_loc7`='Vigila adónde vas, carnicero.', `FemaleText_loc1`='앞으로 조심하는 게 좋아요, 고기 상인.', `FemaleText_loc4`='要记住你是在什么地方，肉贩子。', `FemaleText_loc5`='走路要看路，肉商。', `FemaleText_loc7`='Vigila adónde vas, carnicero.' WHERE `ID`=38795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지 군주들의 갑옷을 보여주십시오, 오르무스.', `MaleText_loc4`='给我看看天灾领主的护甲，欧姆斯。', `MaleText_loc5`='讓我看看天譴領主護甲，歐姆斯。', `MaleText_loc7`='Muéstrame la armadura de los señores de la Plaga, Ormus.', `FemaleText_loc1`='스컬지 군주들의 갑옷을 보여주세요, 오르무스.', `FemaleText_loc4`='给我看看天灾领主的护甲，欧姆斯。', `FemaleText_loc5`='讓我看看天譴領主護甲，歐姆斯。', `FemaleText_loc7`='Muéstrame la armadura de los señores de la Plaga, Ormus.' WHERE `ID`=38796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 전투에 함께하고 싶습니다.', `MaleText_loc4`='我想要参加这场战斗。', `MaleText_loc5`='我希望加入正在進行的戰鬥。', `MaleText_loc7`='Quiero unirme a la batalla que ya está en marcha.', `FemaleText_loc1`='지금 이 전투에 함께하고 싶어요.', `FemaleText_loc4`='我想要参加这场战斗。', `FemaleText_loc5`='我希望加入正在進行的戰鬥。', `FemaleText_loc7`='Quiero unirme a la batalla que ya está en marcha.' WHERE `ID`=38797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스 전투가 한창입니다! 최전선으로 가거나 우리 병사들이 다음 공격을 위해 재정비할 때까지 기다리십시오.', `MaleText_loc4`='吉尔尼斯城之战正在进行！你可以直接到前线去，或者等待我们的队伍重新集结，展开下一波进攻。', `MaleText_loc5`='戰火即將延燒至吉爾尼斯城!你可以到前線去或等我們的人馬聚集了後發動下次的進攻。', `MaleText_loc7`='¡La Batalla por la Ciudad de Gilneas está en marcha! Puedes dirigirte al frente o esperar a que nuestros hombres se reagrupen para el próximo ataque.' WHERE `ID`=38798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병사들이 재정비하고 있습니다. 곧 다시 싸울 수 있을 겁니다.', `MaleText_loc4`='我们的战士正在重新集结。再过几分钟，他们就能做好战斗准备。', `MaleText_loc5`='我們的人馬正在重新集結。他們很快就能前進至戰場。', `MaleText_loc7`='Nuestros hombres se reagrupan. En cuestión de minutos estarán listos para el combate.' WHERE `ID`=38799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 고블린 여자가 오우거랑 친구 하는 거 도와준다.', `MaleText_loc4`='我帮助地精女士和食人魔交朋友。', `MaleText_loc5`='我幫哥布林女士跟巨魔做朋友。', `MaleText_loc7`='Yo ayudar a mujer goblin a hacer amigos ogros.' WHERE `ID`=38800;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐, 오우거. 이제 너희 부족들이 이 서류에 서명했으니 다른 오우거들도 우리와 함께 일하러 오게 설득하려면 어떻게 해야 하지?', `FemaleText_loc4`='嗨，食人魔。现在你的部族已经签好了文件。但我们该怎样说服他们真正为我们工作？', `FemaleText_loc5`='喂，巨魔。你的部族已經簽署了協議，我們必須怎麼做才能讓他們全部來為我們工作?', `FemaleText_loc7`='Eh, ogro. Ahora que tu tribu ha firmado todo el papeleo, ¿qué podemos hacer para convencerlos de verdad de que vengan a trabajar para nosotros?' WHERE `ID`=38801;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오우거가 좋아하는 것 말이야. 오우거에게 주면 좋아하는 게 뭐야?', `FemaleText_loc4`='给食人魔喜欢的东西。给食人魔觉得有趣的东西。', `FemaleText_loc5`='巨魔喜歡的東西。什麼好玩的給巨魔。', `FemaleText_loc7`='LO QUE OGROS QUERER. DAR GRAN DIVERSIÓN A OGROS.' WHERE `ID`=38802;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 한숨을 내쉽니다.', `FemaleText_loc4`='%s叹了口气。', `FemaleText_loc5`='%s嘆了口氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=38803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실리시드라고? 그 벌레들은 구역질 나고 정말로 못 먹는 건데... 아, 가져다줄게.', `FemaleText_loc4`='那些异种虫？那些东西令人讨厌，而且根本不能吃……哦，根本不能吃。', `FemaleText_loc5`='異種?那些東西噁心到爆了，而且完全不能吃...噢，隨便啦。', `FemaleText_loc7`='¿Los silítidos? Esas cosas son asquerosas y absolutamente incomestibles... Oh, da igual.' WHERE `ID`=38804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=38805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, 영웅이여. 나는 드루이드가 입는 프레이야의 덩굴손매듭 방어구를 제작하고 판매하오.', `MaleText_loc4`='你好，英雄。我制造和出售德鲁伊需要的树纹套装。', `MaleText_loc5`='歡迎，英雄。我替德魯伊製造並販賣芙蕾雅的棘織護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura tejeazote de Freya para druidas.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 드루이드가 입는 프레이야의 덩굴손매듭 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售德鲁伊需要的树纹套装。', `FemaleText_loc5`='歡迎，英雄。我替德魯伊製造並販賣芙蕾雅的棘織護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura tejeazote de Freya para druidas.' WHERE `ID`=38806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 살펴보고 싶습니다.', `MaleText_loc4`='我想看看你的货物。', `MaleText_loc5`='我想跟你借東西。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.', `FemaleText_loc1`='물건을 살펴보고 싶어요.', `FemaleText_loc4`='我想看看你的货物。', `FemaleText_loc5`='我想跟你借東西。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías.' WHERE `ID`=38807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...네가 말하는 거 잘 모르겠다.', `MaleText_loc4`='……俺不懂你说的啥。', `MaleText_loc5`='...我不懂你在說什麼。', `MaleText_loc7`='... yo no saber qué decir.' WHERE `ID`=38808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 주술사가 입는 서리술사의 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售萨满祭司需要的霜巫套装。', `MaleText_loc5`='歡迎，英雄。我替薩滿製造並販賣冰霜女巫護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura bruja de escarcha para chamanes.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 주술사가 입는 서리술사의 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售萨满祭司需要的霜巫套装。', `FemaleText_loc5`='歡迎，英雄。我替薩滿製造並販賣冰霜女巫護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura bruja de escarcha para chamanes.' WHERE `ID`=38809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 영웅이여. 나는 도적이 입는 그림자칼날 방어구를 제작하고 판매한다네.', `MaleText_loc4`='你好，英雄。我制造和出售潜行者需要的影刃套装。', `MaleText_loc5`='歡迎，英雄。我替盜賊製造並販賣影刃護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura Hoja de las Sombras para pícaros.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 도적이 입는 그림자칼날 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售潜行者需要的影刃套装。', `FemaleText_loc5`='歡迎，英雄。我替盜賊製造並販賣影刃護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura Hoja de las Sombras para pícaros.' WHERE `ID`=38810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 사냥꾼이 입는 안카하르 피사냥꾼의 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售猎人需要的安卡哈猎血套装。', `MaleText_loc5`='歡迎，英雄。我替獵人製造並販賣安卡哈血狩護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura cazador de sangre de Ahn''kahar para cazadores.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 사냥꾼이 입는 안카하르 피사냥꾼의 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售猎人需要的安卡哈猎血套装。', `FemaleText_loc5`='歡迎，英雄。我替獵人製造並販賣安卡哈血狩護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura cazador de sangre de Ahn''kahar para cazadores.' WHERE `ID`=38811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 전사가 입는 이미야르 군주의 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售战士需要的伊米亚之王套装。', `MaleText_loc5`='歡迎，英雄。我替戰士製造並販賣依米亞領主護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura de señor Ymirjar para guerreros.' WHERE `ID`=38812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, 영웅이여. 나는 성기사가 입는 서약의 빛 방어구를 제작하고 판매하오.', `MaleText_loc4`='你好，英雄。我制造和出售圣骑士需要的光誓套装。', `MaleText_loc5`='歡迎，英雄。我替聖騎士製造並販賣光誓護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura juraluz para paladines.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 성기사가 입는 서약의 빛 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售圣骑士需要的光誓套装。', `FemaleText_loc5`='歡迎，英雄。我替聖騎士製造並販賣光誓護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura juraluz para paladines.' WHERE `ID`=38813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 사제가 입는 진홍빛 수행사제 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售牧师需要的血色侍僧套装。', `MaleText_loc5`='歡迎，英雄。我替牧師製造並販賣赤紅侍僧護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura de acólito carmesí para sacerdotes.', `FemaleText_loc1`='반가워요, 영웅이여. 저는 사제가 입는 진홍빛 수행사제 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售牧师需要的血色侍僧套装。', `FemaleText_loc5`='歡迎，英雄。我替牧師製造並販賣赤紅侍僧護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura de acólito carmesí para sacerdotes.' WHERE `ID`=38814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 마법사가 입는 혈법사 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售法师需要的血法套装。', `MaleText_loc5`='歡迎，英雄。我替法師製造並販賣血法師護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura de mago sangriento para magos.', `FemaleText_loc1`='반갑네, 영웅이여. 나는 마법사가 입는 혈법사 방어구를 제작하고 판매한다네.', `FemaleText_loc4`='你好，英雄。我制造和出售法师需要的血法套装。', `FemaleText_loc5`='歡迎，英雄。我替法師製造並販賣血法師護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura de mago sangriento para magos.' WHERE `ID`=38815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 영웅이여. 저는 흑마법사가 입는 어둠의 집회 방어구를 제작하고 판매합니다.', `MaleText_loc4`='你好，英雄。我制造和出售术士需要的黑巫套装。', `MaleText_loc5`='歡迎，英雄。我替術士製造並販賣黑暗巫會護甲。', `MaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura Aquelarre oscuro para brujos.', `FemaleText_loc1`='반가워요, 영웅이여. 나는 흑마법사가 입는 어둠의 집회 방어구를 제작하고 판매합니다.', `FemaleText_loc4`='你好，英雄。我制造和出售术士需要的黑巫套装。', `FemaleText_loc5`='歡迎，英雄。我替術士製造並販賣黑暗巫會護甲。', `FemaleText_loc7`='Saludos, $ghéroe:heroína;. Yo fabrico y vendo la armadura Aquelarre oscuro para brujos.' WHERE `ID`=38816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 오우거는 벌레 좋아한다. 서쪽에서 벌레 가져와라.', `MaleText_loc4`='哦，食人魔喜欢吃虫子。去西边弄虫子。', `MaleText_loc5`='喔，巨魔很愛吃蟲。去西邊抓些蟲吧。', `MaleText_loc7`='Oh. A ogro gustar bicho. Coger bicho en oeste.' WHERE `ID`=38817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 다시 나타납니다!', `MaleText_loc4`='灵魂们再次复苏！', `MaleText_loc5`='鬼魂再次甦醒吧!', `MaleText_loc7`='¡Los espíritus se alzan de nuevo!', `FemaleText_loc1`='영혼들이 다시 나타납니다!', `FemaleText_loc4`='灵魂们再次复苏！', `FemaleText_loc5`='鬼魂再次甦醒吧!', `FemaleText_loc7`='¡Los espíritus se alzan de nuevo!' WHERE `ID`=38818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불을 건드리지 마라, 귀찮은 놈들! 그만 포기하고 죽어 버려.', `FemaleText_loc4`='别碰那火，讨厌的巨魔！放弃反抗，去死吧。', `FemaleText_loc5`='不要動那個火，煩人的食人妖! 趕快放棄死一死吧。', `FemaleText_loc7`='¡Dejen el fuego en paz, trols molestos! Ríndanse y mueran.' WHERE `ID`=38819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 서서히 고통스럽게 처치해 주마, 조그만 트롤 놈들아!', `FemaleText_loc4`='不！我会让你死得既漫长又痛苦，小巨魔。', `FemaleText_loc5`='不! 我會讓你們死得又慢又痛苦，小食人妖們。', `FemaleText_loc7`='¡No! Morirán lenta y dolorosamente, pequeños trols.' WHERE `ID`=38820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 불을 건드리다니, 멍청한 놈 같으니! 볼진이 죽으면, 다음은 네 차례다.', `FemaleText_loc4`='你这蠢货竟敢碰我的火焰！等沃金死掉，你就是下一个！', `FemaleText_loc5`='你竟敢碰我的火! 等沃金倒下，下個死的就是你!', `FemaleText_loc7`='¡Sólo un imbécil tocaría mis fuegos! ¡Cuando caiga Vol''jin, ya saben quiénes siguen!' WHERE `ID`=38821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 대체 뭐지?! 날 풀어줘!', `FemaleText_loc4`='这是什么？！放开我！', `FemaleText_loc5`='這是什麼? 放開我!', `FemaleText_loc7`='¡¿Qué es esto?! ¡Libérenme!' WHERE `ID`=38822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 말도 안 돼... 이렇게 끝날 리가 없단 말이다!', `FemaleText_loc4`='这样不对——不应该，不应该就这样结束的。', `FemaleText_loc5`='這樣不對 - 不該是這樣結束的!', `FemaleText_loc7`='No puede ser... ¡no se suponía que terminara así!' WHERE `ID`=38823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진! 성난 파도가 높이 일어 너희 종족을 덮칠 것이다. 넌 돌아오지 말았어야 했어!', `FemaleText_loc4`='巨浪将会升起，吞没你的部族，沃金！你们不应该回来的！', `FemaleText_loc5`='海浪會升起並吞噬你的部族，沃金! 你不應該回來的!', `FemaleText_loc7`='¡Las olas se elevarán y consumirán a tu tribu, Vol''jin! ¡No debiste regresar!' WHERE `ID`=38824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 마녀가 불에서 힘을 뽑아내고 있습니다. 빨리 화로를 끄십시오!', `MaleText_loc4`='她正在从火焰中吸取力量！赶快扑灭火盆！', `MaleText_loc5`='她正在從火中吸取能量!撲滅火盆!快!', `MaleText_loc7`='¡Está absorbiendo energía del fuego! ¡Apaga las hogueras, rápido!' WHERE `ID`=38825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바다 마녀의 현신을 처리하세요! 우리는 자르지라를 맡지요.', `FemaleText_loc4`='解决那些鬼魂！我们来对付扎尔吉拉。', `FemaleText_loc5`='處理那些海巫靈體，札爾基拉交給我們。', `FemaleText_loc7`='¡Cuida sus espíritus! Zar''jira es nuestra.' WHERE `ID`=38826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<길가에서 발견한 불행한 병사는 긴 칼로 난도질당한 모습입니다. 당신은 시체를 이리저리 살펴보다가 이빨 자국을 발견합니다.>$B$B<야생 동물의 소행일까요?>', `MaleText_loc4`='<你在路旁发现了这名不幸的士兵，他的身上有许多仿佛是用长匕首划开的伤口。你将他的身体翻转过来，注意到一些齿印。>$B$B<这会是野兽干的吗？>', `MaleText_loc5`='<你在路邊發現的悲慘士兵看起來是被長刃開腸剖肚的。將身體翻過來後，你發現了齒印。>$B$B<這會是野生動物幹的嗎?>', `MaleText_loc7`='<Parece que el desafortunado soldado que encuentras en el lado de la carretera ha sido destripado con cuchillos largos. Al girar el cuerpo, ves marcas de dientes.>$B$B<¿Es posible que esto lo hayan hecho animales salvajes?>' WHERE `ID`=38827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 마녀가 저기 있어. 난 느낄 수 있다네. 곧 은신처에서 기어나올 테니 기다리게나.', `MaleText_loc4`='那个女海巫就在这里，我能感觉到她。耐心等待，她很快就会从她的洞里出来了。', `MaleText_loc5`='海巫在這，我感覺的到。耐心等待，她不一會兒就會從洞裡出來的。', `MaleText_loc7`='La Bruja del Mar eh''tá aquí, pue''o sentih''la. Quédate y seguro que revela su presencia enseguida.' WHERE `ID`=38828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났네. 오랜 원수를 마침내 처치했군.', `MaleText_loc4`='结束了。我们古老的敌人被击败了。', `MaleText_loc5`='結束了。我們的宿敵被擊敗了。', `MaleText_loc7`='Hecho está. Nuestro enemigo ancestral, derrotado.' WHERE `ID`=38829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 경매장을 이용하는 데 필요한 서류를 작성하고, 요금을 내셨습니까?', `MaleText_loc4`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?', `MaleText_loc5`='[DND]文件填寫正確嗎?使用拍賣場的費用付過了嗎?', `MaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?', `FemaleText_loc1`='[DND] 경매장을 이용하는 데 필요한 서류를 작성하고, 요금을 내셨나요?', `FemaleText_loc4`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?', `FemaleText_loc5`='[DND]文件填寫正確嗎?使用拍賣場的費用付過了嗎?', `FemaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the auction house?' WHERE `ID`=38830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 은행 이용권이 있습니다.', `MaleText_loc4`='我有使用这家银行的权利证明。', `MaleText_loc5`='我有使用銀行的適當證明文件。', `MaleText_loc7`='Tengo el certificado correspondiente para utilizar el banco.', `FemaleText_loc1`='전 은행 이용권이 있어요.', `FemaleText_loc4`='我有使用这家银行的权利证明。', `FemaleText_loc5`='我有使用銀行的適當證明文件。', `FemaleText_loc7`='Tengo el certificado correspondiente para utilizar el banco.' WHERE `ID`=38831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DND] 은행을 이용하는 데 필요한 서류를 작성하고, 요금을 내셨습니까?', `MaleText_loc4`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?', `MaleText_loc5`='[DND]文件填寫正確嗎?使用銀行的費用付過了嗎?', `MaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?', `FemaleText_loc1`='[DND] 은행을 이용하는 데 필요한 서류를 작성하고, 요금을 내셨나요?', `FemaleText_loc4`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?', `FemaleText_loc5`='[DND]文件填寫正確嗎?使用銀行的費用付過了嗎?', `FemaleText_loc7`='[DND] Have you filled out the proper paper work and paid the appropriate fees to gain access to the bank?' WHERE `ID`=38832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 오랫동안 아버님의 복수를 염원했다네. 오늘 드디어 그 무거운 짐을 내려놓는군.', `MaleText_loc4`='为了清算我父亲的仇恨，我已经等待了很长时间。现在，这副重担终于卸下了。', `MaleText_loc5`='我等待了很久才找到機會替我父親報仇。我肩膀上的重擔終於減輕了。', `MaleText_loc7`='Esperé mucho tiempo la oportunidad de vengar a mi padre. Mis hombros ya no cargan ese peso enorme.' WHERE `ID`=38833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 검은창 요새로 돌아가야 하네. 바니라가 소년을 치료하고 나면 돌아와서 날 찾아오게.', `MaleText_loc4`='我必须回到暗矛要塞去。当瓦妮拉结束对这个孩子的治疗以后，请到那里去找我。', `MaleText_loc5`='我必須回到暗矛要塞。等凡妮拉治療完那個孩子，請在那裡跟我碰面。', `MaleText_loc7`='Debo volver al Bastión Lanza Negra. Ven a buscarme cuando Vanira ya haya curado al chico.' WHERE `ID`=38834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 형제에게 아무것도 해줄 수가 없군요... 마녀의 힘이 주니의 영혼을 갈가리 찢었어요.', `FemaleText_loc4`='恐怕我救不了我们的兄弟了……女海巫的力量夺走了他的灵魂。', `FemaleText_loc5`='我想我沒辦法為我們兄弟做些什麼...她的力量把他的靈魂撕裂了。', `FemaleText_loc7`='No puedo salvar a nuestro hermano... el poder de ella destrozó su alma.' WHERE `ID`=38835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보초들이 주니의 시체를 수습할 겁니다. 장례를 치러야죠... 겨우 이것밖에 할 수 없다니.', `FemaleText_loc4`='我会派人来取回他的尸体，让我们为他举行一个告别仪式……希望还有些什么是我能做的。', `FemaleText_loc5`='我會派衛兵來收回他的屍體，給他一個正式的告別...真希望還能多做些什麼。', `FemaleText_loc7`='Enviaré vigías a que traigan su cuerpo así podremos despedirnos... Ojalá pudiera hacer más.' WHERE `ID`=38836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진 님께서 급히 떠나셨으니, 내가 당신을 데려가지요. 준비되면 알려 주세요.', `FemaleText_loc4`='沃金回去得太急了，不过我会把所有人安全地带回去。准备好了就告诉我一声，兄弟。', `FemaleText_loc5`='沃金匆忙地走了，但我可以帶我們回去。等你準備好就跟我說，老兄。', `FemaleText_loc7`='Vol''jin se fue ávidamente, pero yo conozco un lugar seguro. Dime cuando estemos listos para ir, hombre.' WHERE `ID`=38837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 고대로부터 이어져 온 원한이 풀릴 겁니다.', `FemaleText_loc4`='古老的仇恨在今天得以消弭。', `FemaleText_loc5`='我們在今天了結了一場古老的私仇。', `FemaleText_loc7`='Hoy terminará una antigua dih''puta.' WHERE `ID`=38838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 $n, 이 이상한 막대기로 뭘 할 수 있는지 봅시다...', `MaleText_loc4`='喂，$n。让我们来看看这根疯狂的棒子能做些什么……', `MaleText_loc5`='現在呢，$n，讓我們看看這根瘋狂的棒子能夠做什麼...', `MaleText_loc7`='Vamos, $n. Descubramos de qué es capaz este loco palo...' WHERE `ID`=38839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군요. 아주 흥미롭습니다...', `MaleText_loc4`='有趣。非常……有趣。', `MaleText_loc5`='有趣...太有趣了。', `MaleText_loc7`='Interesante. Muy... interesante.' WHERE `ID`=38840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지저분한 꼴을 좀 보십시오. 불모의 땅은...메말랐다고 들었습니다만.$B$B밤 사이 밀림이 나타나 제 야영지를 덮어버리고, 길도 전부 막아버리지 않았겠습니까!', `MaleText_loc4`='太奇怪了。我听说贫瘠之地非常……贫瘠。$B$B而这片森林在昨天晚上才冒出来，现在却已经吞掉了我的营地，还把道路堵住了！', `MaleText_loc5`='看看這團亂。我所聽到和印象中的貧瘠之地...就單純是個貧瘠之地。$B$B但這片叢林在一夜之間冒了出來，並且吞噬了我的營地和這裡的道路!', `MaleText_loc7`='Observa este desastre. Me habían dicho que Los Baldíos eran tierras... baldías.$B$B¡Esta jungla apareció de la noche a la mañana y se ha tragado mi campamento y ha cubierto los caminos!' WHERE `ID`=38841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥하러 왔나, $n?', `MaleText_loc4`='你是来参加狩猎的吗，$n？', `MaleText_loc5`='你是來參加狩獵行動的嗎，$n?', `MaleText_loc7`='¿Has venido para unirte a mí en la caza, $n?', `FemaleText_loc1`='사냥하러 왔나, $n?', `FemaleText_loc4`='你是来参加狩猎的吗，$n？', `FemaleText_loc5`='你是來參加狩獵行動的嗎，$n?', `FemaleText_loc7`='¿Has venido para unirte a mí en la caza, $n?' WHERE `ID`=38842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가게, $c. 내 사냥에 자네는 필요 없네.', `MaleText_loc4`='滚吧，$c。我的狩猎不需要你。', `MaleText_loc5`='走開，$c。我不需要你參加我的狩獵行動。', `MaleText_loc7`='Márchate, $c. No te necesito en mi cacería.', `FemaleText_loc1`='저리 가게, $c. 내 사냥에 자네는 필요 없네.', `FemaleText_loc4`='滚吧，$c。我的狩猎不需要你。', `FemaleText_loc5`='走開，$c。我不需要你參加我的狩獵行動。', `FemaleText_loc7`='Márchate, $c. No te necesito en mi cacería.' WHERE `ID`=38843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금...가재?!', `MaleText_loc4`='是龙虾！？', `MaleText_loc5`='什麼喇蛄!?', `MaleText_loc7`='¡¿Santa cigala?!' WHERE `ID`=38844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파핫 젝일! 이기 대체 뭐얏?!', `MaleText_loc4`='抓住它！你在说什么！？', `MaleText_loc5`='拉緊那個啥!該死的嘿嘿啥!?', `MaleText_loc7`='¡Maldita sea! ¿¡Hijo de... HEY... qué!?' WHERE `ID`=38845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무래도 끄야! 가! 때러부, 음푸, 대길!', `MaleText_loc4`='''magonna - git! Git! Horkin'' nit, unfh, DABBIT!', `MaleText_loc5`='瑪勾納吉!吉!毫金，安發，達比!', `MaleText_loc7`='Voy a... ¡Imbécil! ¡Imbécil! ¡MALDITA SEA!' WHERE `ID`=38846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼카노스의 숨결에서 벗어나십시오!', `MaleText_loc4`='快躲开沃卡洛斯的呼吸！', `MaleText_loc5`='遠離火岩諾斯的吐息範圍!', `MaleText_loc7`='¡Mantente alejado del aliento de Volcanoth!' WHERE `ID`=38847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신 나갔군요, 그만 쏘지 못해요! 아주 사람 잡겠어요!', `FemaleText_loc4`='停止射击，你这个老白痴！你要打死人了！', `FemaleText_loc5`='你這老白癡別再射了!這樣會射到人的!', `FemaleText_loc7`='¡Deja de disparar, idiota senil! ¡Vas a matar a alguien!' WHERE `ID`=38848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 참으세요, 아저씨!', `MaleText_loc4`='坚持住，老朋友！', `MaleText_loc5`='老兄!撐著點!', `MaleText_loc7`='¡Aguanta, camarada!' WHERE `ID`=38849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]썬더 블러프 시민 여러분! 소정의 이용료를 내야 은행을 이용할 수 있다고 마가타 님께서 말씀하셨습니다.', `MaleText_loc4`='[ph]Citizens of Thunder Bluff! Our matriarch Magath requires citizens wanting to access their vault to pay a small service fee.', `MaleText_loc5`='[ph]雷霆崖的居民們!我們的族母瑪加薩要求你們在存取貴重物品時付點小小的費用。', `MaleText_loc7`='[ph]Citizens of Thunder Bluff! Our matriarch Magath requires citizens wanting to access their vault to pay a small service fee.', `FemaleText_loc1`='[ph]썬더 블러프 시민 여러분! 소정의 이용료를 내야 은행을 이용할 수 있다고 마가타 님께서 말씀하셨어요.', `FemaleText_loc4`='[ph]Citizens of Thunder Bluff! Our superior matriarch Magath requires citizens wanting to access their vault to pay a small service fee.', `FemaleText_loc5`='[ph]雷霆崖的居民們!我們的族母瑪加薩要求你們在存取貴重物品時付點小小的費用。', `FemaleText_loc7`='[ph]Citizens of Thunder Bluff! Our superior matriarch Magath requires citizens wanting to access their vault to pay a small service fee.' WHERE `ID`=38850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이용료를 내면 한정된 시간 동안 은행을 이용하실 수 있습니다.', `MaleText_loc4`='[ph]This fee ensures the use of the bank for a limited amount of time.', `MaleText_loc5`='[ph]花這筆錢能讓你在一定時間內使用銀行服務。', `MaleText_loc7`='[ph]This fee ensures the use of the bank for a limited amount of time.', `FemaleText_loc1`='[ph]이용료를 내면 한정된 시간 동안 은행을 이용하실 수 있어요.', `FemaleText_loc4`='[ph]This fee ensures the use of the bank for a limited amount of time.', `FemaleText_loc5`='[ph]花這筆錢能讓你在一定時間內使用銀行服務。', `FemaleText_loc7`='[ph]This fee ensures the use of the bank for a limited amount of time.' WHERE `ID`=38851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이용료를 내지 않으면 썬더 블러프에서 은행을 이용하실 수 없습니다.', `MaleText_loc4`='[ph]Citizens who refuse to pay this fee will not be allowed to use the banking services here on Thunder Bluff.', `MaleText_loc5`='[ph]拒絕支付這筆費用的居民，不得在雷霆崖使用銀行服務。', `MaleText_loc7`='[ph]Citizens who refuse to pay this fee will not be allowed to use the banking services here on Thunder Bluff.', `FemaleText_loc1`='[ph]이용료를 내지 않으면 썬더 블러프에서 은행을 이용하실 수 없어요.', `FemaleText_loc4`='[ph]Citizens who refuse to pay this fee will not be allowed to use the banking services here on Thunder Bluff.', `FemaleText_loc5`='[ph]拒絕支付這筆費用的居民，不得在雷霆崖使用銀行服務。', `FemaleText_loc7`='[ph]Citizens who refuse to pay this fee will not be allowed to use the banking services here on Thunder Bluff.' WHERE `ID`=38852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]허가증을 구매하면 금고에 접속할 권한을 받습니다.', `MaleText_loc4`='[ph]Purchase a permission slip from me and access to your vault will be granted.', `MaleText_loc5`='[ph]從我這裡買一張准許證明，你就能存取你的寶庫。', `MaleText_loc7`='[ph]Purchase a permission slip from me and access to your vault will be granted.', `FemaleText_loc1`='[ph]허가증을 구매하면 금고에 접속할 권한을 받습니다.', `FemaleText_loc4`='[ph]Purchase a permission slip from me and access to your vault will be granted.', `FemaleText_loc5`='[ph]從我這裡買一張准許證明，你就能存取你的寶庫。', `FemaleText_loc7`='[ph]Purchase a permission slip from me and access to your vault will be granted.' WHERE `ID`=38853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 %s|1을;를; 포획하십시오!', `MaleText_loc4`='%s已经可以捕捉了！', `MaleText_loc5`='已經準備好捉補%s了!', `MaleText_loc7`='¡El %s está preparado para ser capturado!' WHERE `ID`=38854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]썬더 블러프 시민 여러분, 주목해 주십시오!', `MaleText_loc4`='[ph]Attention Citizens of Thunder Bluff!', `MaleText_loc5`='[ph]各位雷霆崖的居民注意這邊!', `MaleText_loc7`='[ph]Attention Citizens of Thunder Bluff!', `FemaleText_loc1`='[ph]썬더 블러프 시민 여러분, 주목해 주세요!', `FemaleText_loc4`='[ph]Attention Citizens of Thunder Bluff!', `FemaleText_loc5`='[ph]各位雷霆崖的居民注意這邊!', `FemaleText_loc7`='[ph]Attention Citizens of Thunder Bluff!' WHERE `ID`=38855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]소정의 이용료를 내면 모든 그림토템 경매인을 이용하실 수 있습니다.', `MaleText_loc4`='[ph]For a small fee, you can have an all access pass to either Grimtotem auctioneer.', `MaleText_loc5`='[ph]只要一小筆金額，你們就能取得使用任何一位恐怖圖騰拍賣師服務的全境許可。', `MaleText_loc7`='[ph]For a small fee, you can have an all access pass to either Grimtotem auctioneer.', `FemaleText_loc1`='[ph]소정의 이용료를 내면 모든 그림토템 경매인을 이용하실 수 있어요.', `FemaleText_loc4`='[ph]For a small fee, you can have an all access pass to either Grimtotem auctioneer.', `FemaleText_loc5`='[ph]只要一小筆金額，你們就能取得使用任何一位恐怖圖騰拍賣師服務的全境許可。', `FemaleText_loc7`='[ph]For a small fee, you can have an all access pass to either Grimtotem auctioneer.' WHERE `ID`=38856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]모인 돈은 호드의 번영을 위해 쓰입니다.', `MaleText_loc4`='[ph]All money collected will be used for the betterment of the Horde.', `MaleText_loc5`='[ph]這筆錢會全數用在部落的改善措施上。', `MaleText_loc7`='[ph]All money collected will be used for the betterment of the Horde.', `FemaleText_loc1`='[ph]모인 돈은 호드의 번영을 위해 쓰이지요.', `FemaleText_loc4`='[ph]All money collected will be used for the betterment of the Horde.', `FemaleText_loc5`='[ph]這筆錢會全數用在部落的改善措施上。', `FemaleText_loc7`='[ph]All money collected will be used for the betterment of the Horde.' WHERE `ID`=38857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편리한 그림토템 경매를 이용하시려면, 위대하신 마가타 그림토템 님의 허가증이 있어야 합니다!', `MaleText_loc4`='如果要使用恐怖图腾拍卖服务功能，你必须首先得到玛加萨·恐怖图腾的许可！', `MaleText_loc5`='要使用便利的恐怖圖騰拍賣服務，你得先從偉大的瑪加薩·恐怖圖騰那取得使用權!', `MaleText_loc7`='¡Para utilizar los servicios de subasta de los Tótem Siniestro, necesitas el permiso de la gran Magatha Tótem Siniestro!', `FemaleText_loc1`='편리한 그림토템 경매를 이용하시려면, 위대하신 마가타 그림토템 님의 허가증이 있어야 해요!', `FemaleText_loc4`='如果要使用恐怖图腾拍卖服务功能，你必须首先得到玛加萨·恐怖图腾的许可！', `FemaleText_loc5`='要使用便利的恐怖圖騰拍賣服務，你得先從偉大的瑪加薩·恐怖圖騰那取得使用權!', `FemaleText_loc7`='¡Para utilizar los servicios de subasta de los Tótem Siniestro, necesitas el permiso de la gran Magatha Tótem Siniestro!' WHERE `ID`=38858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이용료를 내지 않는 시민은 경매를 하실 수 없습니다.', `MaleText_loc4`='[ph]Citizens unwilling to pay will be refused access to the Auction services.', `MaleText_loc5`='[ph]不願意付錢的居民不得使用拍賣服務。', `MaleText_loc7`='[ph]Citizens unwilling to pay will be refused access to the Auction services.', `FemaleText_loc1`='[ph]이용료를 내지 않는 시민은 경매를 하실 수 없어요.', `FemaleText_loc4`='[ph]Citizens unwilling to pay will be refused access to the Auction services.', `FemaleText_loc5`='[ph]不願意付錢的居民不得使用拍賣服務。', `FemaleText_loc7`='[ph]Citizens unwilling to pay will be refused access to the Auction services.' WHERE `ID`=38859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 도와주십시오! 밧줄을... 제발...', `MaleText_loc4`='$n，救命！这绳子……救命……', `MaleText_loc5`='$n救命!給我繩子...拜託...', `MaleText_loc7`='¡$n! ¡Socorro! Las cuerdas... Por favor...' WHERE `ID`=38860;
