UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 고맙습니다! 일단 협상은...계획대로 진행됐습니다.', `MaleText_loc4`='啊，感谢你！应该说……谈判是按照计划进行的。', `MaleText_loc5`='啊，謝謝你!我可以說...討論的進行與計畫中的一樣。', `MaleText_loc7`='¡Ah! ¡Gracias! No es necesario decirlo... Las negociaciones fueron según lo planeado.' WHERE `ID`=38862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지까지는 제 힘으로 돌아갈 수 있습니다.', `MaleText_loc4`='我应该能自己回营地了。', `MaleText_loc5`='我應該可以自己回到營地。', `MaleText_loc7`='Debería poder volver a mi campamento solo.' WHERE `ID`=38863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]케른 님께서 돌아가셨다고? 믿기 어렵군.', `MaleText_loc4`='[ph]Caire is dead?  It''s hard to imagine.', `MaleText_loc5`='[ph]克蕾兒死了?難以想像會發生這樣的事情。', `MaleText_loc7`='[ph]Caire is dead?  It''s hard to imagine.', `FemaleText_loc1`='[ph]케른 님께서 돌아가셨다고요? 믿기 어렵네요.', `FemaleText_loc4`='[ph]Caire is dead?  It''s hard to imagine.', `FemaleText_loc5`='[ph]克蕾兒死了?難以想像會發生這樣的事情。', `FemaleText_loc7`='[ph]Caire is dead?  It''s hard to imagine.' WHERE `ID`=38864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]그래도 다행입니다. 마가타 님께서 우리를 잘 이끌어 주셨으니까요. 이런 날이 오리라는 걸 아셨던 겁니다.', `MaleText_loc4`='[ph]It is still fortunate for us.  Magatha has guided us well.  She knew this day would come.', `MaleText_loc5`='[ph]我們還是相當幸運。瑪加薩帶得不錯。她知道會有這麼一天的。', `MaleText_loc7`='[ph]It is still fortunate for us.  Magatha has guided us well.  She knew this day would come.', `FemaleText_loc1`='[ph]그래도 다행이에요. 마가타 님께서 우리를 잘 이끌어 주셨으니까요. 이런 날이 오리라는 걸 아셨던 거죠.', `FemaleText_loc4`='[ph]It is still fortunate for us.  Magatha has guided us well.  She knew this day would come.', `FemaleText_loc5`='[ph]我們還是相當幸運。瑪加薩帶得不錯。她知道會有這麼一天的。', `FemaleText_loc7`='[ph]It is still fortunate for us.  Magatha has guided us well.  She knew this day would come.' WHERE `ID`=38865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]그렇게나 빨리 말입니까? 이번 침공이 그렇게나 신속하게 이루어질 줄은 마가타 님조차도 생각 못하신 듯합니다.', `MaleText_loc4`='[ph] So soon though?  I do not think even she thought this invasion would go as swiftly as it did.', `MaleText_loc5`='[ph]居然這麼快?我想連她都沒料到這次的入侵會順利到這種程度。', `MaleText_loc7`='[ph] So soon though?  I do not think even she thought this invasion would go as swiftly as it did.', `FemaleText_loc1`='[ph]그렇게나 빨리 말이에요? 이번 침공이 그렇게나 신속하게 이루어질 줄은 마가타 님 조차도 생각 못하신 듯해요.', `FemaleText_loc4`='[ph]Thinking about things?  What do YOU have to think about?', `FemaleText_loc5`='[ph]在想事情?你能有什麼事情好想的?', `FemaleText_loc7`='[ph]Thinking about things?  What do YOU have to think about?' WHERE `ID`=38866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]케른 님께서 돌아가시고 나서 이렇게나 빨리 썬더 블러프... ''우리'' 썬더 블러프에 있는 것은 그저 운이 좋아서가 아닙니다.', `MaleText_loc4`='[ph]To be standing in Thunder Bluff....OUR Thunder Bluff so soon after Cairne died is not luck.', `MaleText_loc5`='[ph]在凱恩死掉後這麼短的時間內又站上「我們的」雷霆崖...這不是好運。', `MaleText_loc7`='[ph]To be standing in Thunder Bluff....OUR Thunder Bluff so soon after Cairne died is not luck.', `FemaleText_loc1`='[ph]케른 님께서 돌아가시고 나서 이렇게나 빨리 썬더 블러프... ''우리'' 썬더 블러프에 있는 것은 그저 운이 좋아서가 아니지요.', `FemaleText_loc4`='[ph]To be standing in Thunder Bluff....OUR Thunder Bluff so soon after Cairne died is not luck.', `FemaleText_loc5`='[ph]在凱恩死掉後這麼短的時間內又站上「我們的」雷霆崖...這不是好運。', `FemaleText_loc7`='[ph]To be standing in Thunder Bluff....OUR Thunder Bluff so soon after Cairne died is not luck.' WHERE `ID`=38867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종이는 뭐에 쓰려고 하십니까?', `MaleText_loc4`='你要纸干什么？', `MaleText_loc5`='你要哪種文件?', `MaleText_loc7`='¿Para qué necesitas papeles?', `FemaleText_loc1`='종이는 뭐에 쓰시게요?', `FemaleText_loc4`='你要纸干什么？', `FemaleText_loc5`='你要哪種文件?', `FemaleText_loc7`='¿Para qué necesitas papeles?' WHERE `ID`=38868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 필요하십니까?', `MaleText_loc4`='你需要什么？', `MaleText_loc5`='你需要什麼嗎?', `MaleText_loc7`='¿Qué necesitas?', `FemaleText_loc1`='뭐가 필요하신가요?', `FemaleText_loc4`='你需要什么？', `FemaleText_loc5`='你需要什麼嗎?', `FemaleText_loc7`='¿Qué necesitas?' WHERE `ID`=38869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무얼 이용하시려는 겁니까?', `MaleText_loc4`='你想要使用什么？', `MaleText_loc5`='你想怎麼用?', `MaleText_loc7`='¿Qué intentas utilizar?', `FemaleText_loc1`='무얼 이용하시려는 건가요?', `FemaleText_loc4`='你想要使用什么？', `FemaleText_loc5`='你想怎麼用?', `FemaleText_loc7`='¿Qué intentas utilizar?' WHERE `ID`=38870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?', `FemaleText_loc1`='뭐라고요?', `FemaleText_loc4`='什么？', `FemaleText_loc5`='什麼?', `FemaleText_loc7`='¿Qué?' WHERE `ID`=38871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 돈은 저희가 안전하게 보관하겠습니다.', `MaleText_loc4`='别担心，你的钱在我们这里很安全。', `MaleText_loc5`='別擔心，和我們在一起，你的錢呢會很安全的。', `MaleText_loc7`='No te preocupes, tu dinero está a salvo con nosotros.', `FemaleText_loc1`='걱정하지 마세요. 돈은 저희가 안전하게 보관하겠어요.', `FemaleText_loc4`='别担心，你的钱在我们这里很安全。', `FemaleText_loc5`='別擔心，和我們在一起，你的錢呢會很安全的。', `FemaleText_loc7`='No te preocupes, tu dinero está a salvo con nosotros.' WHERE `ID`=38872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행을 이용하는 데 필요한 서류를 다 작성했습니다.', `MaleText_loc4`='我已经填好了进入银行所需的文件。', `MaleText_loc5`='我填好銀行的文件表單了。', `MaleText_loc7`='He rellenado los papeles para el banco.', `FemaleText_loc1`='은행을 이용하는 데 필요한 서류를 다 작성했어요.', `FemaleText_loc4`='我已经填好了进入银行所需的文件。', `FemaleText_loc5`='我填好銀行的文件表單了。', `FemaleText_loc7`='He rellenado los papeles para el banco.' WHERE `ID`=38873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 버텨요, $n 님! 여기서 빠져나가야 해요. 당장요!', `FemaleText_loc4`='坚持住，$n！我们必须马上离开这里！', `FemaleText_loc5`='等一下，$n!我們必須離開這裡，現在!', `FemaleText_loc7`='¡Espera un segundo, $n! ¡Tenemos que salir de aquí, AHORA!' WHERE `ID`=38874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가... 피가 더 필요해!', `MaleText_loc4`='鲜血……更多的鲜血！', `MaleText_loc5`='血...要更多血!', `MaleText_loc7`='Sangre... ¡más SANGRE!' WHERE `ID`=38875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 마녀는 죽었고, 우리는 고향을 되찾았네. 하지만 우리의 미래는 아직 불안하군.', `MaleText_loc4`='女海巫死了，我们夺回了家园，但我们的未来仍然充满未知数。', `MaleText_loc5`='海巫已經死了，我們奪回了家園，但我們的未來仍然是個未知數。', `MaleText_loc7`='La Bruja de Mar ha muerto, recuperamos nuestro hogar, pero el futuro es incierto.' WHERE `ID`=38876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 대답을 줄 수 있는 이는 하나뿐이지. 원한다면 자네도 지켜보게.', `MaleText_loc4`='有一个人能为我解惑。如果你愿意，就留下来看看。', `MaleText_loc5`='只有一個人可以為我解答。你想要的話可以留下來看看。', `MaleText_loc7`='Sólo uno me dará la respuesta que busco. Puedes quedarte a mirar, si gustas.' WHERE `ID`=38877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 가로쉬가 싫네. 그건 확실하지. 하지만 호드를 떠나는 건 가볍게 내릴 결정이 아니야.', `MaleText_loc4`='我并不喜欢加尔鲁什，但离开部落对我来说，是一个非常艰难的决定。', `MaleText_loc5`='我不喜歡卡爾洛斯，這我很確定，但我不會這麼輕易的就離開部落。', `MaleText_loc7`='No me gusta Garrosh, eso es seguro, pero dejar la Horda no es una decisión fácil.' WHERE `ID`=38878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실일세. 누군가 나를 죽이려 했지. 하지만 지금은 그게 중요한 게 아닐세. 세상은 내 도움이 필요해.', `MaleText_loc4`='确实有人想要杀死我，但这并不是我现在最关注的问题。这个世界正需要我的帮助。', `MaleText_loc5`='沒錯，是有人想要我的命，但那不是我現在最擔心的事。這個世界正呼喚著我的幫忙。', `MaleText_loc7`='Así es. Alguien trató de matarme, pero no es mi principal preocupación ahora. El mundo mismo pide mi ayuda.' WHERE `ID`=38879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 자네가 무사해서 다행이군. 흉흉한 소문을 들었는데.', `MaleText_loc4`='萨尔，很高兴你一切平安。我听到了可怕的消息。', `MaleText_loc5`='索爾。很高興你一切安好。傳言說你已遭遇不測。', `MaleText_loc7`='¡Thrall! Qué alegría que estés bien. Los rumores decían otra cosa.' WHERE `ID`=38880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진, 가로쉬에겐 이 시국에 호드를 이끌 힘이 있네. 그래서 그를 택했네.', `MaleText_loc4`='沃金，我选择加尔鲁什，是因为他有能力率领人民渡过这艰难的时代。', `MaleText_loc5`='沃金，我選擇卡爾洛斯是因為他有力量帶領我們的人民度過這個非常時期。', `MaleText_loc7`='Vol''jin, elegí a Garrosh porque tiene la fuerza para guiar al pueblo en estos tiempos difíciles.' WHERE `ID`=38881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 조언이 필요하네, 친구여. 가로쉬는 오로지 전쟁만을 바라보며 호드 사이에 불화를 일으키고 있네. 난 자네를 존경하지만, 이 새로운 호드는 존경할 수 없네... 그래서 호드를 나갈 생각을 하고 있지.', `MaleText_loc4`='我的朋友，我需要你的建议。加尔鲁什使人民自相残杀，我不能支持他这样做。我尊敬你，但我不会因此继续效忠于新的部落……我要带着我的族人离开了。', `MaleText_loc5`='我需要你的意見，老朋友。我無法忍受卡爾洛斯為了戰鬥而讓我們的人民自相殘殺。我對你的尊敬無法延伸到這個新的部落上...我想我會帶領我的族人離開。', `MaleText_loc7`='Necesito consejo, mi amigo. No puedo quedarme con Garrosh y ver cómo enemista a nuestra gente para llevarlos a la guerra. Mi respeto por ti no se extiende a esta Horda nueva... Estuve pensando en llevarme a mi gente.' WHERE `ID`=38882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들은 나더러 지혜롭다고 하지... 하지만, 나도 지금껏 호드의 분열을 가까스로 막아냈네. 분노의 관문과 언더시티를 생각해 보게.', `MaleText_loc4`='即使我倾尽智慧也曾多次几乎无法维持部落的团结。天谴之门和幽暗城就是最好的证明。', `MaleText_loc5`='在我有限的智慧下，曾有幾次連我都無法讓部落團結一致。憤怒之門和幽暗城之戰清楚的說明了這點。', `MaleText_loc7`='Con mi supuesta sabiduría, hubo momentos en que apenas logré mantener unida a la Horda. La Puerta de Cólera y las Entrañas lo dejaron en claro.' WHERE `ID`=38883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 정통성 있는 영웅을 원한다네. 절대로 인간에게 고개 숙이지 않을, 배신 따위를 허락하지 않을 진정한 오크이자 호드의 자긍심을 찾아줄 전사 말이야. 가로쉬는 그런 영웅이 될 수 있네.', `MaleText_loc4`='部落渴望一个旧时代的英雄，一个血统纯粹，不会向人类低头，不会容忍背叛的兽人。一位能让人民重活荣耀的战士。加尔鲁什就是这样的英雄。', `MaleText_loc5`='部落渴望古代的那種英雄。一個血統純正，不向任何人類低頭和不允許任何背叛的獸人。一個能為我們的人民帶來榮耀的戰士。卡爾洛斯可以成為這個英雄。', `MaleText_loc7`='La Horda clama un héroe de antaño. Un orco de sangre pura que no se someta a los humanos ni cargue con traiciones. Que enorgullezca a nuestra gente. Garrosh puede ser ese héroe.' WHERE `ID`=38884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네, 형제여. 자네를 더 귀찮게 하지 않고 좀 더 생각해 보겠네. 자네는 세상을 구원해야지...', `MaleText_loc4`='我明白，兄弟。我会自己考虑，不再打扰你了。你还要去拯救这个世界。', `MaleText_loc5`='我懂了，兄弟。我會好好想想，不再為此打擾你。這個世界等著你這大忙人來拯救。', `MaleText_loc7`='Entiendo, hermano. Lo pensaré y no te molestaré más. Tienes un mundo por salvar.' WHERE `ID`=38885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 강인하고 자긍심 높은 젊은이일세. 자네 같은 인재와 함께 싸워서 자랑스럽군.', `MaleText_loc4`='你强壮而又高傲，年轻人。你将为暗矛部族带来巨大的胜利与光荣。', `MaleText_loc5`='你要堅強和驕傲，年輕人。暗矛部族很榮幸跟你並肩作戰。', `MaleText_loc7`='Sé fuerte y orgulloso, sangre joven. La Lanza Negra estará honrada de que luches a su lado.' WHERE `ID`=38887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, 친구여.', `MaleText_loc4`='Throm''ka，老朋友。', `MaleText_loc5`='(獸人語)相見愉快，老朋友。', `MaleText_loc7`='Throm''ka, viejo amigo.' WHERE `ID`=38888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 힘든 시기야... 하지만 모두를 위해, 역시 우리는 호드와 함께 해야 할 것 같네.', `MaleText_loc4`='这是一个艰难的时代，但是为了所有人的利益，我们会继续帮助部落。', `MaleText_loc5`='這會是個黑暗的時期，但我們族人會為了大家的福祉留在部落。', `MaleText_loc7`='Son tiempos oscuros pero nuestra gente se quedará con la Horda, por el bien de todos. ' WHERE `ID`=38889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄의 말이 옳네. 그는 언제나 옳았지. 호드란 무엇인가? 고집 센 늙은 지도자들, 노스렌드에서 명성을 날린 영웅 몇 명이 전부는 아니지. 사람들은 가로쉬의 이름을 외치고 있네. 적어도 지금은.', `MaleText_loc4`='萨尔的话是正确的，一如既往。组成部落的并不只是几个顽固的老领袖和从诺森德回来的英雄。人们在呼喊加尔鲁什的名字……至少现在是如此。', `MaleText_loc5`='索爾是對的，一向都是。部落不只是由少數又老又臭的首領和一些北裂境的英雄們所組成的。至少現在...就讓他們繼續高唱卡爾洛斯的名字吧。', `MaleText_loc7`='La palabra de Thrall es fuerte y cierta. La Horda es mucho más que algunos líderes testarudos y un puñado de héroes de Rasganorte. La gente clamará el nombre de Garrosh... por ahora.' WHERE `ID`=38890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 성난모래 부족 전설 속의 칼을 찾고 싶다고?$B$B술트라제를위해 피를 묻힐 준비가 되었나? 사막을 가로질러 그 피를 뿌릴 준비도? 강력한 힘이 담긴 보물을 찾아 헤맬 수 있단 말이지? $B$B그렇다면... 사막에 온 것을 환영하네, 친구.', `MaleText_loc4`='那么，你想要找到传说中的沙怒之剑？$B$B为了寻求财富与权力，你已经准备好为苏萨斯而杀戮？将热血泼洒在黄沙之上？$B$B既然如此……欢迎来到这片沙漠，朋友。', `MaleText_loc5`='所以，你想找傳說中的沙怒之劍，啊?$B$B你準備好成為蘇薩斯的殺手了嗎?讓鮮血濺滿這片沙地?想要寶藏?力量強大的寶藏?$B$B如果都是...便歡迎來到這片沙漠，老兄。', `MaleText_loc7`='Así que quieres encont''ar las legendarias eh''padas de Furiarena, ¿eh?$B$B¿Matarás po'' Sul''thraze? ¿Derramarás sangre a lo largo de las arenas? ¿En busca de tesoros, de poder?$B$BSi crees que pue''es hacerlo... te doy la bienvenida al desie''to, colega.' WHERE `ID`=38891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 보여줄 게 있네. 직접 보는 게 더 이해하기 쉽겠지.', `MaleText_loc4`='我要让你看样东西。亲眼看到它，你就会明白了。', `MaleText_loc5`='我有東西想讓你看。你親自看看會比較容易瞭解。', `MaleText_loc7`='Tengo que mostrarte algo. Lo entenderás mejor si lo ves con tus ojos.' WHERE `ID`=38892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이크랄라 그리 카이. 피와 가시의 힘으로...', `FemaleText_loc4`='Eekrala gree-kay。以血与荆棘……', `FemaleText_loc5`='Eekrala gree-kay。鮮血和荊棘...', `FemaleText_loc7`='Eekrala gree-kay. Por la sangre y por la espina...' WHERE `ID`=38893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진흙에서 태어난 생명. 죽은 대지에서... 다시 태어나라.', `FemaleText_loc4`='来自泥土的新生命。死亡之土……得到重生。', `FemaleText_loc5`='黏土誕生的新生命。死亡的大地...重生。', `FemaleText_loc7`='Nueva vida del barro. Tierra inerte... renace.' WHERE `ID`=38894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이 와... <킁킁> 깜찍한 $r|1이야;야;, 그렇지? 아주 깜찍해...', `FemaleText_loc4`='他们来了……<哼哼>漂亮的$r，是么？真漂亮……', `FemaleText_loc5`='他們來了...<哼氣>漂亮的$r，對吧?太漂亮了...', `FemaleText_loc7`='Ya vienen... <Resopla> Bonito, ¿verdad, $r? Muy bonito...' WHERE `ID`=38895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 우리에게 한 일들을 생각하면 충분히 이 땅을 잃어 마땅하다! 이제 물러서라! 아니면 늑대인간의 분노와 맞서야 할 것이다!', `MaleText_loc4`='就凭你们的人对我们所做的一切，你们也不配继续占据这片土地！离开这里，否则狼人的怒火就要把你们烧毁！', `MaleText_loc5`='從你的人對我們所做的一切來看，喪失這片土地是你活該!現在快滾，不然就讓你見識看看狼人的怒火!', `MaleText_loc7`='¡Mereces perder esta tierra por lo que tu gente nos hizo! ¡Ahora apártate o enfréntate a la ira de los huargen!' WHERE `ID`=38896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말대꾸하지 마라, 트롤. 누가 여기 책임자인지 잘 알 텐데. 스랄이 어째서 당신이 아닌 나를 선택했는지 아직도 이해하지 못하겠나?', `MaleText_loc4`='别跟我顶嘴，巨魔。你清楚现在掌权的是谁。难道你没有自问过，为什么萨尔选择了我，而不是你？', `MaleText_loc5`='別跟我頂嘴，食人妖。你知道這裡的老大是誰。你沒問問你自己為什麼索爾選了我而不是你嗎?', `MaleText_loc7`='No me hables así, trol. Sabes quién quedó a cargo aquí. ¿Acaso nunca te preguntaste por qué será que Thrall me eligió a mí y no a ti?' WHERE `ID`=38897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 잘 이해하고 있네, 가로쉬. 백성은 전쟁 영웅을 원하고, 자넨 그롬의 아들이지. 그래서 스랄이 대족장의 자리를 맡긴 게야.', `MaleText_loc4`='这没什么好想的，加尔鲁什。他之所以给你这个头衔，是因为你是格罗姆的儿子，因为人们想要一位战争的英雄。', `MaleText_loc5`='這不令人意外，卡爾洛斯。他給了你這個稱號是因為你是葛羅的兒子，也因為人們現在想要的是個戰爭英雄。', `MaleText_loc7`='No hay porqués, Garrosh. Te dio el título porque eres el hijo de Grom y porque la gente quiere un héroe de guerra.' WHERE `ID`=38898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 나의 대족장은 아니야. 나는 자네를 존경하지 않으며, 그 어리석은 전쟁욕이 호드를 파괴하는 걸 보고만 있지는 않겠네.', `MaleText_loc4`='你不是我的酋长。你并没有赢得我的尊敬，我也不会眼睁睁地看着部落因为你对战争的渴望而毁灭。', `MaleText_loc5`='你不是我的大酋長。你並沒有贏得我的尊敬，我不會看著部落因為你對戰爭的饑渴而遭到毀滅。', `MaleText_loc7`='Tú no eres mi Jefe de Guerra. No te has ganado mi respeto y no toleraré que destruyas a la Horda en tu tonta sed de guerra.' WHERE `ID`=38899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 아들이여, 난 내가 어떻게 할지 확실히 알고 있다. 나는 지켜볼 것이야. 네 백성이 너의 무능함을 알게 되고, 나처럼 널 경멸하게 되는 걸 즐겁게 웃으며 지켜볼 테다.', `MaleText_loc4`='我知道我将会怎样做，地狱咆哮之子。我会静静等待人们逐渐意识到你没有能力担当这个职位。最终，他们会像我一样离开你。', `MaleText_loc5`='我心裡清楚的很，地獄吼之子。我會靜靜地等待和冷眼旁觀，看到你的族人慢慢地發現你的愚蠢。當他們唾棄你的時候，就是我嘲笑你的時候。', `MaleText_loc7`='Sé exactamente lo que haré al respecto, hijo Grito Infernal. Miraré y esperaré a que tu gente empiece a ver tu ineptitud. Y reiré al ver cómo empiezan a detestarte.' WHERE `ID`=38900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화를 자초하는군, 트롤.', `MaleText_loc4`='你这是自掘坟墓，巨魔。', `MaleText_loc5`='你是自尋死路，食人妖。', `MaleText_loc7`='Has sellado tu destino, trol.' WHERE `ID`=38901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 자리에서 네 숨을 끊지 않는 걸 다행으로 생각해라. 감히 호드의 대족장에게 그딴 식으로 말해도 된다고 생각하나?', `MaleText_loc4`='你很走运，我没打算现在就干掉你。你竟然蠢到以为可以用这种口气和你的酋长说话。', `MaleText_loc5`='我沒現在就將你開膛剖肚算你運氣好，死老頭。你居然愚蠢到以為可以這樣跟你的大酋長說話。', `MaleText_loc7`='Tienes suerte de que no te destripe aquí mismo, cría. Si piensas que puedes hablarle así a tu Jefe de Guerra eres un imbécil.' WHERE `ID`=38903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구체적으로 도대체 뭘 어떻게 하겠다는 거지? 그딴 게 위협이 된다고 생각하나? 이제 동족을 이끌고 뒷골목으로 썩 물러가라. 방 안에 가득 찬 악취를 이젠 도저히 참아줄 수가 없군.', `MaleText_loc4`='你觉得你到底能做什么？你的威胁是空洞的。和你的同类一起滚到贫民窟去吧，我已经无法容忍你这种渣滓继续留在我的王座旁边了。', `MaleText_loc5`='要不然你以為你能怎麼樣?你的威脅十分空洞。和你的同類一起夾著尾巴溜回貧民區吧，我無法再忍受你的臭味在我的大殿飄蕩。', `MaleText_loc7`='¿Y qué piensas hacer al respecto, a ver? Tus amenazas son vanas. Vuelve escabulléndote a los tugurios como todos los de tu raza, ya no tolero tu mugrosa presencia en la sala de mi trono.' WHERE `ID`=38904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 네가 완전히 무너지고, 네 힘이 아무런 의미도 없어지는 바로 그때, 내가 너의 통치를 빠르고 조용하게 끝낼 것이다.', `MaleText_loc4`='你最终只能得到彻底的失败，你的“力量”将变得毫无意义。到时候，我会无声迅捷地结束你的统治。', `MaleText_loc5`='當你所擁有的權力毫無意義，當你完全失敗的那天到來，我會迅速而安靜地終結你的統治。', `MaleText_loc7`='Y cuando llegue el momento de tu fracaso y tu "poder" no valga nada, allí estaré para terminar tu mandato rápida y silenciosamente.' WHERE `ID`=38905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 볼진의 발에 침을 뱉습니다.', `MaleText_loc4`='%s在沃金面前的地上啐了一口。', `MaleText_loc5`='%s對沃金的腳邊吐了口痰。', `MaleText_loc7`='%s escupe a los pies de Vol''jin.' WHERE `ID`=38906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 어서요! 이쪽으로 와 보세요!!!', `FemaleText_loc4`='$n，快点！到这里来！！！', `FemaleText_loc5`='$n，快!快到這裡 !!!', `FemaleText_loc7`='¡Venga, $n! ¡¡Ven aquí!!' WHERE `ID`=38908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='익키... 따가워! 날 부순다! 우리에게 장난을 치다니, 녀석을 죽여라!', `FemaleText_loc4`='哎呀呀，它可真扎人啊！$G他:她;骗了我们。杀掉$G他:她;，杀掉！', `FemaleText_loc5`='嗚哇─刺痛啊!絞痛啊!$G他:她;耍了我們，殺了$g他:她;，殺!', `FemaleText_loc7`='¡Ayayayay! ¡Pincha! ¡Y se aplasta! $gÉl:Ella; engañarnos, matar $gél:ella; ¡matar!' WHERE `ID`=38909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족이 당당히 하나의 세력으로 거듭나는 날까지, 내가 직접 움직이겠네.', `MaleText_loc4`='我会确保暗矛巨魔顽强屹立，发挥出它所应有的力量。', `MaleText_loc5`='我會親眼看到暗矛部族重拾它應有的繁榮。', `MaleText_loc7`='Me encargaré pe''sonalmente de que lo'' Lanza Negra se alcen como una potencia por derecho p''opio.' WHERE `ID`=38910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족이 오그리마를 떠났을 때 얘기를 해 주시겠습니까? 가로쉬의 행동을 직접 보고 싶습니다.', `MaleText_loc4`='沃金，能否告诉我暗矛部族在何时离开奥格瑞玛？我需要亲眼见证加尔鲁什的行为。', `MaleText_loc5`='沃金，你可以跟我說暗矛部族是什麼時候離開奧格瑪的嗎?我必須親眼看到卡爾洛斯的所做所為。', `MaleText_loc7`='¿Puedes hablarme de cuando los Lanza Negra abandonaron Orgrimmar, Vol''jin? Necesito ver las acciones de Garrosh con mis propios ojos.', `FemaleText_loc1`='검은창 부족이 오그리마를 떠났을 때 얘기를 해 주시겠습니까? 가로쉬의 행동을 직접 보고 싶어요.', `FemaleText_loc4`='沃金，能否告诉我暗矛部族在何时离开奥格瑞玛？我需要亲眼见证加尔鲁什的行动。', `FemaleText_loc5`='沃金，你可以跟我說暗矛部族是什麼時候離開奧格瑪的嗎?我必須親眼看到卡爾洛斯的所做所為。', `FemaleText_loc7`='¿Puedes hablarme de cuando los Lanza Negra abandonaron Orgrimmar, Vol''jin? Necesito ver las acciones de Garrosh con mis propios ojos.' WHERE `ID`=38911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘도 속았군. 장트라제는 이미 오래전에 내가 찾아냈다. 어떤 교활한 놈이 한밤중에 상트라제를 훔쳐가기 전까지는 칼 두 자루를 모두 다 가지고 있었지.', `MaleText_loc4`='我在开玩笑，朋友。我很久以前就找到了迦萨斯，从而同时拥有了它的两半……但有个狡诈的家伙趁着黑夜把其中一半偷走了。', `MaleText_loc5`='開玩笑的，老兄。我找到迦薩斯很久了。那兩半都有了...直到那個狡猾的人在晚上偷走了一個。', `MaleText_loc7`='Te ha sali''o el tiro por la culata, colega. Encontré la Jang''thraze hace tiempo. Tenía las dos mitades... hah''ta que algún lih''to vino y me robó una de ellas en medio de la noche.' WHERE `ID`=38912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 상트라제도 다시 내 손에 들어왔으니. 네가 이곳에서 찾을 수 있는 건... 방금 파낸 네놈의 무덤 자리뿐이다.', `MaleText_loc4`='现在，桑萨斯终于又是我的了。而你只能在这里找到……你新鲜的坟墓。', `MaleText_loc5`='桑薩斯再次屬於我，你唯一能在這找到的...便是你自己的墳墓。', `MaleText_loc7`='Ahora que Sang''thraze es mía de nuevo, lo único que encontrarás aquí será... tu tumba recién cavada.' WHERE `ID`=38913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 질풍의 술트라제가 다시 하나가 될 것이다!', `MaleText_loc4`='小心！鞭笞者苏萨斯要复活了！', `MaleText_loc5`='看著吧!鞭笞者蘇薩斯即將重回!', `MaleText_loc7`='¡Observa! ¡Sul''thraze la Azotadora eh''tá entera de nuevo!' WHERE `ID`=38914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만하라고... 이렇게 죽으면 족장 우코르즈가 내게 주기로 한 보상을 받을 수 없거든. 알겠지? 그러면 잘 가게 친구... 영원히.', `MaleText_loc4`='够了……如果我死了，沙顶酋长就不可能奖励我了，对不对？再见，朋友……最好永远别见了。', `MaleText_loc5`='夠了...如果我死了就無法從酋長沙頂那得到獎勵，嗯?再見，老兄...永遠地。', `MaleText_loc7`='Ya bah''ta... El jefe Cabellarena no podrá recompensarme si eh''toy mueh''to, ¿no? Adiós, colega... hah''ta nunca.' WHERE `ID`=38915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 경매인들은 믿으셔도 됩니다.', `MaleText_loc4`='你可以信任我们的拍卖师。', `MaleText_loc5`='你可以相信我們的拍賣師。', `MaleText_loc7`='Puedes fiarte de nuestros subastadores.', `FemaleText_loc1`='저희 경매인들은 믿으셔도 돼요.', `FemaleText_loc4`='你可以信任我们的拍卖师。', `FemaleText_loc5`='你可以相信我們的拍賣師。', `FemaleText_loc7`='Puedes fiarte de nuestros subastadores.' WHERE `ID`=38916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장을 이용하는 데 필요한 서류를 전부 작성했습니다.', `MaleText_loc4`='我已经填写了进入拍卖行所需的全部文件。', `MaleText_loc5`='我填好使用拍賣場所需的文件了。', `MaleText_loc7`='He rellenado los papeles para la casa de subastas.', `FemaleText_loc1`='경매장을 이용하는 데 필요한 서류를 전부 작성했어요.', `FemaleText_loc4`='我已经填写了进入拍卖行所需的全部文件。', `FemaleText_loc5`='我填好使用拍賣場所需的文件了。', `FemaleText_loc7`='He rellenado los papeles para la casa de subastas.' WHERE `ID`=38917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]생각해보면... 아무도 그런 일이 일어나는 것을 깨닫지조차 못했습니다.', `MaleText_loc4`='[ph] And to think...no one even saw it coming.', `MaleText_loc5`='[ph]這讓我想到...完全沒有人料到這一點。', `MaleText_loc7`='[ph] And to think...no one even saw it coming.', `FemaleText_loc1`='[ph]생각해보면... 아무도 그런 일이 일어나는 것을 깨닫지조차 못했어요.', `FemaleText_loc4`='[ph] And to think...no one even saw it coming.', `FemaleText_loc5`='[ph]這讓我想到...完全沒有人料到這一點。', `FemaleText_loc7`='[ph] And to think...no one even saw it coming.' WHERE `ID`=38918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이 일을 오랫동안 계획했음이 틀림없습니다.', `MaleText_loc4`='[ph]She must have been planning this for a long time.', `MaleText_loc5`='[ph]她八成盤算很久了。', `MaleText_loc7`='[ph]She must have been planning this for a long time.', `FemaleText_loc1`='[ph]이 일을 오랫동안 계획했음이 틀림없어요.', `FemaleText_loc4`='[ph]She must have been planning this for a long time.', `FemaleText_loc5`='[ph]她八成盤算很久了。', `FemaleText_loc7`='[ph]She must have been planning this for a long time.' WHERE `ID`=38919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[Ph]썬더 블러프 공격은 생각보다 쉬웠습니다.', `MaleText_loc4`='[ph]Attacking Thunder Bluff was easier than expected.', `MaleText_loc5`='[ph]對雷霆崖發動攻擊比原先預期的要來得容易。', `MaleText_loc7`='[ph]Attacking Thunder Bluff was easier than expected.', `FemaleText_loc1`='[Ph]썬더 블러프 공격은 생각보다 쉬웠어요.', `FemaleText_loc4`='[ph]Attacking Thunder Bluff was easier than expected.', `FemaleText_loc5`='[ph]對雷霆崖發動攻擊比原先預期的要來得容易。', `FemaleText_loc7`='[ph]Attacking Thunder Bluff was easier than expected.' WHERE `ID`=38920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]케른이 없으니, 썬더 블러프 시민은 제대로 싸우지도 못하더군요.', `MaleText_loc4`='[ph] Without Cairne, the citizens of Thunder Bluff really didn''t have much fight in them.', `MaleText_loc5`='[ph]沒有了凱恩，雷霆崖的居民們已經沒什麼鬥志。', `MaleText_loc7`='[ph] Without Cairne, the citizens of Thunder Bluff really didn''t have much fight in them.', `FemaleText_loc1`='[ph]케른이 없으니, 썬더 블러프 시민은 제대로 싸우지도 못하더군요.', `FemaleText_loc4`='[ph] Without Cairne, the citizens of Thunder Bluff really didn''t have much fight in them.', `FemaleText_loc5`='[ph]沒有了凱恩，雷霆崖的居民們已經沒什麼鬥志。', `FemaleText_loc7`='[ph] Without Cairne, the citizens of Thunder Bluff really didn''t have much fight in them.' WHERE `ID`=38921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이제 우리가 주도권을 잡았으니, 변화가 좀 있을 겁니다.', `MaleText_loc4`='[ph] Now that we have control, there are going to be some changes around here.', `MaleText_loc5`='[ph]現在這邊為我們所控制，這附近將會變得不一樣。', `MaleText_loc7`='[ph] Now that we have control, there are going to be some changes around here.', `FemaleText_loc1`='[ph]이제 우리가 주도권을 잡았으니, 변화가 좀 있을 거예요.', `FemaleText_loc4`='[ph] Now that we have control, there are going to be some changes around here.', `FemaleText_loc5`='[ph]現在這邊為我們所控制，這附近將會變得不一樣。', `FemaleText_loc7`='[ph] Now that we have control, there are going to be some changes around here.' WHERE `ID`=38922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph] 스톰송이 그 위선자를 처리했기만을 바랍니다. 베인이 죽으면, 여기 있는 추가 경비병 몇 명을 쓰러뜨릴 수 있을 테니 말입니다.', `MaleText_loc4`='[ph] I just hope Stormsong was able to take out the Pretender.  With Baine dead, we could take some of these extra guard patrols down.', `MaleText_loc5`='[ph]我只是希望風暴之歌當時能解決那偽善者。貝恩一死，我們就能再搞定更多的巡邏衛兵。', `MaleText_loc7`='[ph] I just hope Stormsong was able to take out the Pretender.  With Baine dead, we could take some of these extra guard patrols down.', `FemaleText_loc1`='[ph] 스톰송이 그 위선자를 처리했기만을 바라요. 베인이 죽으면, 여기 있는 추가 경비병 몇 명을 쓰러뜨릴 수 있을 테니 말이에요.', `FemaleText_loc4`='[ph] I just hope Stormsong was able to take out the Pretender.  With Baine dead, we could take some of these extra guard patrols down.', `FemaleText_loc5`='[ph]我只是希望風暴之歌當時能解決那偽善者。貝恩一死，我們就能再搞定更多的巡邏衛兵。', `FemaleText_loc7`='[ph] I just hope Stormsong was able to take out the Pretender.  With Baine dead, we could take some of these extra guard patrols down.' WHERE `ID`=38923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph] 블러드후프 마을 공격은 어떻게 되었는지 들으신 거 있습니까?', `MaleText_loc4`='[ph] Have you heard anything from the attack on Bloodhoof Village?', `MaleText_loc5`='[ph]你有沒有聽到任何關於血蹄村受到攻擊的消息?', `MaleText_loc7`='[ph] Have you heard anything from the attack on Bloodhoof Village?', `FemaleText_loc1`='[ph] 블러드후프 마을 공격은 어떻게 되었는지 들으신 거 있나요?', `FemaleText_loc4`='[ph] Have you heard anything from the attack on Bloodhoof Village?', `FemaleText_loc5`='[ph]你有沒有聽到關於血蹄村受到攻擊的事情?', `FemaleText_loc7`='[ph] Have you heard anything from the attack on Bloodhoof Village?' WHERE `ID`=38924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph] 아직은요. 타라코르와 마지막으로 얘기했을 때, 공격은 이미 시작되었을 겁니다.', `MaleText_loc4`='[ph] Not yet.  When I last talked to Tarakor, it should have started already.', `MaleText_loc5`='[ph]還沒。我最後一次和塔拉寇說話的時候，就應該已經開始了。', `MaleText_loc7`='[ph] Not yet.  When I last talked to Tarakor, it should have started already.', `FemaleText_loc1`='[ph] 아직은요. 타라코르와 마지막으로 얘기했을 때, 공격은 이미 시작되었을 거예요.', `FemaleText_loc4`='[ph] Not yet.  When I last talked to Tarakor, it should have started already.', `FemaleText_loc5`='[ph]還沒。我最後一次和塔拉寇說話的時候，就應該已經開始了。', `FemaleText_loc7`='[ph] Not yet.  When I last talked to Tarakor, it should have started already.' WHERE `ID`=38925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph] 경계를 늦추지 마십시오. 블러드후프가 나타나는 조짐이 보인다면 진짜 싸움을 시작할 테니 말입니다.', `MaleText_loc4`='[ph] Just stay alert.  Any sign of Bloodhoof and we''ll have a true fight on our hands.', `MaleText_loc5`='[ph]保持警戒。看到血蹄的徽記就代表我們即將要面臨一場硬仗。', `MaleText_loc7`='[ph] Just stay alert.  Any sign of Bloodhoof and we''ll have a true fight on our hands.', `FemaleText_loc1`='경계를 늦추지 마세요. 블러드후프가 나타나는 조짐이 보인다면 진짜 싸움을 시작할 테니 말이에요.', `FemaleText_loc4`='[ph] Just stay alert.  Any sign of Bloodhoof and we''ll have a true fight on our hands.', `FemaleText_loc5`='[ph]保持警戒。看到血蹄的徽記就代表我們即將要面臨一場硬仗。', `FemaleText_loc7`='[ph] Just stay alert.  Any sign of Bloodhoof and we''ll have a true fight on our hands.' WHERE `ID`=38926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에도 높은 밀림에 둘러싸여 이빨까지 뒤덮인 적이 있습니다. 전 세계 곳곳을 돌아다녔지요. 만일 여기서 이대로 끝이라면 얻어맞은 돼지 꼴이 될 겁니다.', `MaleText_loc4`='这已经不是我第一次在古怪危险的丛林中拼尽全力挣扎求生了。我去过这个世界的许多地方，$g孩子:姑娘;，如果我会在这里完蛋，那我也只不过是个没用的家伙。', `MaleText_loc5`='這不是第一次我陷在叢生裡還被偷襲了。我全世界都跑遍遍了，$g小子:小妞;，我不可能在這裡栽個跟斗的啦。', `MaleText_loc7`='No es la primera vez que acabo metido hasta las cejas en una selva que me tiende una emboscada. He recorrido el mundo entero, $ghijo:muchacha;, y que me aspen si voy a dejarme matar aquí.' WHERE `ID`=38927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기해 주십시오, 더러븐 피트.', `MaleText_loc4`='给我讲个故事，老脏鬼佩蒂！', `MaleText_loc5`='講個故事給我聽，老髒鬼皮特!', `MaleText_loc7`='¡Cuéntame una historia, viejo Pete!', `FemaleText_loc1`='얘기해 주십시오, 더러븐 피트.', `FemaleText_loc4`='给我讲个故事，老脏鬼佩蒂！', `FemaleText_loc5`='講個故事給我聽，老髒鬼皮特!', `FemaleText_loc7`='¡Cuéntame una historia, viejo Pete!' WHERE `ID`=38928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 아주 오래전에, 저와 제 친구들은 툭하면 술을 진탕 마시는데 월급을 탕진하다 보니, 가볍게 마실 돈도 한 푼 남지 않아 그만 애를 먹고 있었습니다. $B$B그래서 바키의 맥줏집 창고에 있는 엄청나게 커다란 포고꾼 맥주통을 슬쩍 가져오기로 했지요.$B$B버팀대를 손도끼로 부숴버렸더니, 술통이 지붕 옆을 따라 둥지떠난 어린 새 마냥 데굴데굴 굴러갑디다. 하지만 너무 커서 사람이라도 깔아뭉갤 기세였습니다.', `MaleText_loc4`='在很久以前，我和我的同伴根本没有几个钱喝酒。几番豪饮之后，我们就花光了所有的铜板，搞得连每天的日常酒钱都没了着落。$B$B于是我们决定上老巴克的啤酒馆去，从他堆在酒馆顶楼上那些硕大的啤酒桶里“征收”一桶来。$B$B说干就干，我们用短柄斧砍断了支撑酒桶的架子，好家伙，那满满装着啤酒的酒桶就这么从茅草屋顶上滚了下去，就好象一只从巢里掉出来的鸟崽，呃，应该是只大胖鸟，能轧死人的那种。', `MaleText_loc5`='在以前啊，我和我的哥們沒有什麼錢可以買酒，因為我們的錢幾乎都拿去買烈酒，所以沒剩下多少可以喝的休閒一點。$B$B所以我們決定跟巴吉的釀酒吧那要一桶史詩級大小的招牌陳年烈酒。$B$B我們用手斧把支柱給砍斷了，那位老兄便像小鳥離巢一樣地從稻草屋頂的邊上滾了出去，說是小鳥可能不太對，應該是大隻的酒桶鳥。那真是痛死人了。', `MaleText_loc7`='Hace tiempo, incluso antes del propio tiempo, mis camaradas y yo no podíamos beber mucho, porque nos gastábamos toda la paga en alcohol y eso no nos dejaba pelados para dedicarnos a beber por afición.$B$BAsí que decidimos re-qui-sar uno de esos barriles de Ol'' Barkerstout de tamaño épico que había en el altillo de la Cervecería de Barky.$B$BCortamos los amarres con hachas y esa cosa enorme RODÓ por todo el costado del tejado de paja como un pajarito que abandonara el nido, una especie de pájaro grande y redondo claro, que podía aplastar a un tipo.' WHERE `ID`=38929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포고꾼 맥주통이 얼마나 큰지 아십니까? 언덕에서 한번 구르기 시작하면 절대 막을 수 없죠. 자비도 후회도 없고, 두려움도 없습니다.$B$B맥주가 사태를 일으킨 것처럼, 행복하게 죽기 딱 좋아요.$B$B맥주통은 언덕 아래 고아원에 부딪혀서 곧 폭발했고, 전 진흙 웅덩이 속으로 입을 벌린 채 뛰어들었습니다. 한 번 생각해 보십시오. 이 얘기가 어떻게 끝나는지는 기억이 잘 안 납니다. 문신이나 구경하실래요?$B$B<바지를 내리는 노친네 더러븐 피트>', `MaleText_loc4`='知道为什么他们管它叫刚强烈酒吗？因为它曾经一直从山上滚下来。那时你可没办法和它商量，和它讲道理。它根本不懂得同情，不知道后悔，也绝不会害怕。$B$B那简直就像是一场啤酒雪崩，要是在那里死掉绝对算得上是轰轰烈烈。$B$B酒桶在撞到山下的孤儿院时炸开了。我立刻大张着嘴扑到了满是酒液的泥地里，然后……我记不清那个故事是怎样结尾的了。想要看看我的刺青吗？$B$B<老脏鬼佩蒂脱下了裤子。>', `MaleText_loc5`='你知道他們為什麼叫它烈酒?因為它一旦下肚後整個人就HIGH了起來，完全不知道周圍是什麼。它讓人感覺沒有遺憾，沒有憐憫，沒有恐懼。$B$B那就像是一場酒崩，就這樣死了一定很爽。$B$B所以呢，那個酒桶在撞到山丘下的孤兒院後就爆炸了，我就張著嘴跳進泥土中，然後...我想想...想不起來之後是怎樣了。你想看看那個刺青嗎?$B$B<老髒鬼皮特脫下了他的褲子。>', `MaleText_loc7`='¿Sabes por qué la llaman así? Porque cuando empieza a rodar colina abajo no se puede negociar con ella, no se puede razonar con ella. No siente ni piedad, ni arrepentimiento, ni miedo.$b$bEra como una birravalancha, que habría sido una forma estupenda de morir.$b$bAsí que el barril explotó en cuanto alcanzó el orfanato en la falda de la colina, y me tiré al charco de lodo con la boca abierta, y... Ahora que lo pienso, no me acuerdo de cómo acaba la historia. ¿Quieres ver el tatuaje?$b$b<El Viejo Pete se baja los pantalones.>' WHERE `ID`=38930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 이 총이 보이십니까?$B$B<무기를 얼굴 가까이 들이대며 흔드는 노친네 더러븐 피트>$B$B이녀석은 노스렌드를 빼고 안 가본 데가 없습니다. 제 목숨을 셀 수 없을 만큼 구해줬지요. 제가 셀 수 있는 숫자는 일곱까집니다만. 한 번은, 작은 맥덩갈의 아버지인 "덩치 큰 매키" 맥덩갈이 자신의 막내딸과 제 총을 맞바꾸자고 했답니다.$B$B에디에 관해 말하자면, 저와 공통점이 아주 많습니다. 입은 크고, 이빨은 사슴 같고요. 끝 부분이 아주 위험하고, 안전장치는 반쯤 풀어진 채 돌아다니길 좋아합니다.$B$B작은 에디가 척 브랜디비어드에게 발로 머리를 세게 차서 눈에서 콧물이 쏙 빠지게 하는 데 25실버를 걸었다는 이야기는 들어보셨습니까?', `MaleText_loc4`='看到这杆枪了吗，$g小子:小妞;？$B$B<老脏鬼佩蒂满不在乎地在你面前挥舞着他的武器。>$B$B这杆枪去过诺森德以外的每一块大陆。我已经数不清它救过我几次命了，大概七次吧。有一次，“大麦克”麦当高——我说的可不是那个小麦当高，而是他的老爹。那家伙想要用他最年轻的女儿和我换这杆枪。$B$B要知道，爱蒂可是个有趣的女孩。她和我的枪有很多相同的地方——嘴很大，还是大龅牙，很容易走火，一走火就能把你烤个半熟。$B$B你有没有听说过那个小爱蒂和查克·白酒须用25枚银币打赌的故事？他们赌的就是爱蒂能一脚踢在查克的脑袋上，让查克疼得大哭鼻子！', `MaleText_loc5`='$g小子:小妞;，這把槍你看到了嗎?$B$B<老髒鬼皮特很悠然地將他的武器對著你搖了搖。>$B$B這把槍除了北裂境沒去過其他哪都去了。我數不清我的老命被它救過幾次:七次!!有一次，「大麥基」麥克當格─不是小麥克當格，是他老爸─想用他的女兒來換我這把槍。$B$B跟你說說艾蒂吧:她跟我的槍其實有很多像的地方，嘴巴大，牙縫也大，使用時的效果不太安全，沒完全準備好就喜歡直接上。$B$B你有聽說過小艾蒂有次跟恰克·白蘭地鬚賭25銀幣說她可以一腳把他的頭踢到噴出鼻涕?', `MaleText_loc7`='¿Ves esta escopeta, $gchaval:chavala;?$b$b<El Viejo Pete apunta el arma directamente a tu cara como si nada.>$b$bEsta escopeta ha conocido la acción en todos los continentes menos Rasganorte. Me ha salvado la vida más veces de las que puedo contar: siete. Una vez, "Gran Mackie" MacDungal (no el muchacho MacDungal, sino su padre) me ofreció su hija menor a cambio de mi escopeta.$b$bDeja que te cuente algo sobre Edie: tenía mucho en común con mi escopeta. La boca ancha, los dientes de conejo, peligrosa por un extremo, a veces se encasquilla.$b$b¿Has oído la historia de cuando la moza se apostó 25 monedas de plata con Chuck Barbabrandy a que podía darle una patada en la cara tan fuerte que lloraría mocos?' WHERE `ID`=38931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇죠, 소문이 빠르게 퍼져서 메네실 사람이 전부 내기를 하러 모여들었답니다. 과일 상인이고 뭐고 할 것 없이 모두 모여서 구경하는데, 그 규칙이 아무래도 실망스러워서 아주 장황하게 정리를 해야 했습니다. 시장까지 직접 나서서 피를 흘리는 건 쳐주지 않는다고 인정했지요.$B$B그래서 척은 무릎을 꿇고 그녀는 의자 위에 올라가 튼튼한 다리로 꼿꼿이 선 채... 음, 본론에서 좀 벗어났군요. 요점은, 거래를 받아들여야 했다는 겁니다. 이 총이 좀 부실하거든요.', `MaleText_loc4`='唔，这消息以惊人的速度传播。没过多久，米奈希尔港的所有人都聚集了起来，有些人开始打赌，水果小贩则干脆就地做起了生意。他们就具体的规则进行了冗长的争论，直到镇长亲自出面他们才达成了共识：擦血不算输。$B$B就这样，查克跪倒下去，她则在一只凳子上挺起身，扬起她的那条大粗腿——我好像扯远了。重点是，我当时真应该接受那提议，因为这把枪现在有点儿不灵光了。', `MaleText_loc5`='嘿啊，八卦很快就傳開了，整個米奈希爾，包括水果販子，都開賭盤在接受下注，然後賭博的規則又出現了一堆亂七八糟的問題，直到鎮長自己同意如果噴出血是不算的。$B$B所以恰克蹲了下來，艾蒂便站上了板凳然後舉起了她那又肥又粗的腿然後─呃...我離題了。重點是，我應該接受那個交易，因為這把槍已經有點秀逗了。', `MaleText_loc7`='Sí, se corrió la voz hasta el punto de que todo Menethil se reunió para ver cómo acababa la cosa, con apuestas y vendedores de fruta y tal, y hubo polémica con algunas normas que hubo que arreglar a bombo y platillo, hasta que el propio alcalde tuvo que dictaminar que llorar sangre no cuenta.$b$bAsí que Chuck se arrodilla y Edie se sube a un taburete y levanta esa enorme pierna suya y... me estoy yendo por las ramas. A lo que iba: debería haber aceptado el trato, porque esta escopeta está un poco p''allá.' WHERE `ID`=38932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 원래부터 더러븐 피트라 불린 건 아닙니다.$B$B젊고 거칠던 한때, 풍만하고 아름다운 벨리라는 처녀한테 멋진 조각을 선물해 깊은 인상을 심어주려고 했단 말입니다.$B$B벨리, 그녀는 뭔가 달라도 다른 여자였죠. 아주 단단하고 크지만, 가운데는 잘록했습니다.$B$B그래서 저는 그녀의 피부처럼 새하얀 석회암 덩어리를 구해다가 다듬고 조각하고, 소위 말하는 걸작을 만들어내는 작업을 시작했습니다. 하지만 비율 계산에 실패했지요, 아시겠습니까? 아주 거대한, 뭐라고 하더라? 엉덩이만 남았지요.', `MaleText_loc4`='他们一直都叫我老脏鬼佩蒂。$B$B不过我也有过又年轻又脏的时候。那时我曾经打算用自己的雕刻工艺吸引一个名叫贝丽的姑娘。她可真是个肉感的甜心。$B$B老贝丽！她就完全是另一回事了。我的那个贝丽可不一样。她的身上除了中间的一段细腰之外，都是那么丰满，真是该多么漂亮就有多么漂亮。$B$B所以我找了一块像她的皮肤一样雪白的石灰石，打算雕出了一件惊世杰作。但我把比例全搞错了。最后，我只弄出一个奇怪的大块头。应该叫它什么呢？枪靶子吧！', `MaleText_loc5`='我不是一直都被叫做老髒鬼皮特。$B$B在我年輕和也很髒的時候，我以為可以靠著我的巧手把到一個叫做佩麗的奶媽。$B$B老佩麗啊!她真的與眾不同。很固執的，除了那個以外什麼都大，女人嘛!$B$B所以我找了一塊和她皮膚一樣白的大理石，然後用我的巧手開始雕刻，創造出了所謂的曠世鉅作。但我的比例出了問題，懂嗎?我最後雕出來的是一個巨大無比的...屁股。', `MaleText_loc7`='No siempre me han llamado Viejo Pete.$b$bUna vez, cuando era joven y gallardo, me decidí a seducir a un bombón llamado Bellie con mi tallado inimitable.$b$b¡Ah, Bellie! Era única. Firme como nadie. Grande por todos lados menos en la cintura, como tiene que ser.$b$bAsí que encontré una piedra caliza tan blanca como su piel y me puse a tallar y a cincelar y a crear una auténtica obra maestra, pero me salió mal la escala, ¿sabes? Acabó con un enorme, ¿cómo lo diría? Culo.' WHERE `ID`=38933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들으신 대로, 엉덩이입니다! 숙녀에게 어울리는 선물은 아니죠. 하지만 전 맘에 들었습니다. 그래서 동네 술집에 기부했습니다.$B$B사람들은 그걸 더러븐 피트의 엉덩이라 불렀고 나중엔 술집 이름도 그렇게 바뀌었죠. 오크들이 싹 다 불태우기 전까지 말입니다. 결국 남은 건 저기 돌무더기 가운데 커다랗고 새까만 엉덩이뿐입니다.$B$B<눈물을 한 방울 떨구는 노친네 더러븐 피트>', `MaleText_loc4`='听我说，$g小子:小妞;，一个枪靶子可不能当作送给女士的礼物。但我还是很喜欢它。所以我把它送给了当地的酒馆做装饰品。$B$B他们管它叫脏鬼佩蒂的屁股。最后就连那家酒馆也被叫成这个名字了。可恨的是，那家酒馆后来被兽人烧成了一块黑炭。现在那里只剩下了我那个变黑的大屁股嵌在一堆残垣断壁上。$B$B<老脏鬼佩蒂的眼眶里落下一滴泪水。>', `MaleText_loc5`='你沒聽錯，$g小子:小妞;，一個屁股!似乎不是很適合送給女士的東西，但我喜歡它。所以我把它捐給了我常去的酒吧。$B$B他們稱我的作品為「老髒鬼皮特的屁屁」，最後把酒吧的名字也取為「老髒鬼皮特的屁屁」。但獸人把酒吧燒成了焦炭，如今還剩下的只有夾在瓦礫中的大焦黑屁屁了。$B$B<老髒鬼皮特滴了一滴眼淚下來。>', `MaleText_loc7`='Ya me has oído, $gchaval:chavala;, ¡un culo! No es un regalo apropiado para una señorita. Pero a mí me gustaba. Así que lo doné a mi taberna local.$b$bLo llamaron "el trasero de Pete", y al final la taberna se acabó llamando así, antes de que los orcos la redujeran a cenizas, y ahora solo queda mi trasero grande y ennegrecido en medio de un montón de escombros.$b$b<El Viejo Pete derrama una sola lágrima.>' WHERE `ID`=38934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 전쟁 시절에는... 그 전쟁 말고, 다른 전쟁 말입니다. 오크가 용을 탔을 때 말이죠? 저와 위슬러는 체리 그로그주를 마시고 눈이 벌게져서 울퉁불퉁한 소나무로 만든 나룻배를 타고 남녘해안에서 메네실 항구로 가던 중이었습니다.$B$B그리고 한 삼 분의 일쯤 와서 보니, 주변에 바다 말고는 아무것도 보이질 않아 꽤 많이 온 듯한데 발이 점점 축축해지는 게 느껴지더란 말입니다.', `MaleText_loc4`='在那场战争中——我说的是很早以前的那场战争。那时兽人好似都还骑着龙打仗？总之，我和威斯利从南海镇出发，前往米奈希尔港。我们只乘着一艘用多节的松木做成的独木舟，肚子里灌满了樱桃酒。$B$B因为周围只有海水，所以我们很难判断走了多远的路。不过，应该是在走完三分之一路程的时候，我感到我的脚被打湿了。', `MaleText_loc5`='當年打仗的時候—不是那個，另一個，獸人有騎龍的那個。我跟惠斯勒從南海鎮要去米奈希爾港，然後我們坐的是自己弄的船，大松樹的樹幹砍下來自己搞的划艇，而且櫻桃酒還灌得還蠻爽的。$B$B等我們划到大概三分之一的時候—我猜差不多有那麼遠了，因為旁邊什麼都沒有，就只有海。反正就是那個時候，我開始覺得腳濕濕的。', `MaleText_loc7`='En la guerra... Esa no, la otra... Esa con los orcos que iban montados en dragones... Silbidos y yo nos propusimos cruzar de Costasur al Puerto de Menethil en una lancha que habíamos construido con un pino nudoso mientras estábamos ciegos de grog de cereza.$b$bYo creo que recorrimos un tercio del camino, lo digo porque no había nada a nuestro alrededor excepto mar cuando empecé a sentir los pies mojados.' WHERE `ID`=38935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울퉁불퉁한 소나무로 말씀드릴 것 같으면, 옹이가 꽤 많았습니다.$B$B옹이는 나무에 있는 큰 구멍이라 나룻배가 영 불품 없었고, 전 위슬러를 원망했습니다만 그 친구는 또 생각이 달라서 제가 고른 송진에 문제가 있다더군요. 전 그냥 잊어버리기로 하고 함께 술을 마시며 회포를 풀기로 했습니다.$B$B그로그주가 떨어지자, 그가 글쎄 칼을 들고 싸우려 들지 뭡니까. 운동삼아라나요.$B$B어쨌거나, 결국 메네실에 도착하지는 못하고 둘 중 하나였는지 둘 다였는지 물에 빠지고 말았습니다.', `MaleText_loc4`='现在，$g小子:姑娘;，让我和你说说那根长满瘤子的老松木吧。它的确是有很多瘤子和疖子。$B$B那些节瘤让松木上多了许多窟窿，用这种木材可做不出好的独木舟来。我要给它上面涂一层柏油，威斯利却不同意。所以我们决定用拼酒来达成一致。$B$B酒喝光了以后，我们开始抽出匕首来对打。当然，我们只是要比试一下。$B$B不管怎样，那艘松木船最后也没能到达米奈希尔港。我相信我们之中至少有一个人，或者两个人都溺水了。', `MaleText_loc5`='我跟你說，$g小子:小妞;，大松樹有個問題，就是有很多那個那個樹瘤的。$B$B然後那個樹瘤，就是樹上粗粗的洞洞。所以我就怪惠斯勒拿大松樹來做船很蠢，結果他反而怪是我選錯了焦油(我選擇故意忘記)。最後咧，我們決定比賽喝酒來決定誰對誰錯。$B$B結果酒喝完了，我們就拿小刀出來決鬥。好玩的。$B$B反正，我們最後也是沒有到米奈希爾港，而且我很肯定，我們有個人、還是兩個人，最後都淹死了。', `MaleText_loc7`='Te voy a decir una cosa sobre el pino nudoso, $ghijo:moza;: tiene nudos.$b$bY los nudos no son más que agujeros enormes en los árboles, es una tontería ponerlos en una lancha, y le eché la culpa a Silbidos pero él tenía su propia opinión sobre mi elección de alquitrán (no elegí ninguno) así que decidimos arreglarlo bebiendo.$b$bCuando se acabó el grog es cuando empezamos con la pelea a navajas. Por deporte.$b$bPero bueno, que nunca llegamos a Menethil, y creo que al menos uno o dos de nosotros nos ahogamos.' WHERE `ID`=38936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심각하군요.', `MaleText_loc4`='听起来情况相当严重。', `MaleText_loc5`='聽起來很嚴重。', `MaleText_loc7`='Eso parece serio.', `FemaleText_loc1`='심각하군요.', `FemaleText_loc4`='听起来情况相当严重。', `FemaleText_loc5`='聽起來很嚴重。', `FemaleText_loc7`='Eso parece serio.' WHERE `ID`=38937;
