UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 뒤쪽 조심해요!!!', `FemaleText_loc4`='哦，天哪！你的背后！！！', `FemaleText_loc5`='我的天啊!小心你後面!!!', `FemaleText_loc7`='¡AY MADRE MÍA! ¡¡¡DETRÁS DE TI!!!' WHERE `ID`=38943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장으로 있는 동안, 넌 언제나 등 뒤를 신경 쓰고 어둠을 두려워할 것이다. 그리고 때가 되면, 넌 피 흘리며 죽어갈 것이다... 심장을 꿰뚫은 그 화살이 누구 것인지는... 말하지 않아도 잘 알겠지.', `MaleText_loc4`='你应该经常注意一下自己的背后和你身边的阴影。只有这样，当你的血慢慢流干的时候，你才会知道究竟是谁射出了那支夺去你生命的利箭。', `MaleText_loc5`='你每天會過的提心吊膽，連自己的影子也懼怕。因為當那天來臨，你的血將一滴滴的流乾，你會知道是誰射出了那穿過你黑心的那一箭。', `MaleText_loc7`='Pasarás tu reinado con la vista sobre el hombro y miedo a las sombras, y cuando llegue el momento y la sangre se te escurra, sabrás exactamente quién disparó la flecha que atravesó tu corazón negro.' WHERE `ID`=38944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님과 이야기한다고 하셨지요? 제가 두 분의 대화를 놓쳤습니까?', `MaleText_loc4`='你说你和萨尔说过话？我听错了吗？', `MaleText_loc5`='你和索爾商量過?我錯過了嗎?', `MaleText_loc7`='¿Has hablado de estar en contacto con Thrall? ¿Me lo he perdido?', `FemaleText_loc1`='스랄 님과 이야기한다고 하셨지요? 제가 두 분의 대화를 놓쳤습니까?', `FemaleText_loc4`='你说你和萨尔说过话？我听错了吗？', `FemaleText_loc5`='你和索爾商量過?我錯過了嗎?', `FemaleText_loc7`='¿Has hablado de estar en contacto con Thrall? ¿Me lo he perdido?' WHERE `ID`=38946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너야말로, "대족장".', `MaleText_loc4`='彼此彼此，“酋长大人”。', `MaleText_loc5`='沃金謹上，「大酋長」', `MaleText_loc7`='Y tú al tuyo, "Jefe de Guerra".' WHERE `ID`=38947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우거진 식물들은 전부 다 잘라 버려! 그래도 안 되면, 불을 질러야겠다.', `MaleText_loc4`='砍掉这些过度生长的植物！如果这样还没有用，我们就必须烧光它们了。', `MaleText_loc5`='繼續劈了那些生長過剩的!如果沒有用，我們便會開始燃燒。', `MaleText_loc7`='¡Sigue cortando el crecimiento excesivo! Si eso no funciona, comenzaremos a quemar.' WHERE `ID`=38948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 생각하는 게 제대로구만, 브리지워터.', `MaleText_loc4`='我喜欢你思考的方式，布瑞哲沃特。', `MaleText_loc5`='我喜歡你的思路，布莉姬瓦特。', `MaleText_loc7`='Me gusta tu forma de pensar, Puenteagua.' WHERE `ID`=38949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티간 님, 길을 막는 건 모두 불태워버릴 계획이십니까?', `FemaleText_loc4`='这就是你的计划，缇甘？点火烧光一切挡路的东西？', `FemaleText_loc5`='那是你的計畫嗎，提根?把任何擋在我們面前的事物給燒了?', `FemaleText_loc7`='¿Ese es tu plan, Teegan? ¿Pegarle fuego a todo lo que se interponga en nuestro camino?' WHERE `ID`=38950;
