UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지긋지긋하군! 전방 지휘소에 도착할 때까지 계속해서 자르고 불태워야겠어.', `MaleText_loc4`='可恶！我们只能连砍带烧地向前线指挥站前进了。', `MaleText_loc5`='噁心死了!我們必須邊劈邊燒才能到達前線指揮營地。', `MaleText_loc7`='¡Desagradable! Tendremos que abrirnos paso hasta el Mando de Vanguardia a base de tajos y fuego.' WHERE `ID`=38952;
