UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지난 밤부터 불모의 땅에 갑자기 식물이 우거진 이유가 전혀 궁금하지 않나요?', `FemaleText_loc4`='贫瘠之地仿佛在一夜之间就变得林木茂盛，郁郁葱葱，难道你对此一点也不感到奇怪吗？', `FemaleText_loc5`='你難到不好奇為什麼貧瘠之地會突然重拾光輝，在一夜之間?', `FemaleText_loc7`='¿No tienes ni la más mínima curiosidad de por qué Los Baldíos están floreciendo de la noche al día?' WHERE `ID`=38954;
