UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아요, 가시멧돼지는 악취가 나는 놈들입니다.', `MaleText_loc4`='嘿，那些野猪人真是脏得要命。', `MaleText_loc5`='嗯，野豬人是噁心的。', `MaleText_loc7`='Sí, los jabaespines son repugnantes.' WHERE `ID`=38959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 큰 소리로 트림합니다.', `MaleText_loc4`='%s大声地打着嗝。', `MaleText_loc5`='%s大聲地抱怨。', `MaleText_loc7`='%s eructa fuertemente.' WHERE `ID`=38960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에는 사냥감이 아주 풍부합니다. 사냥할 의지만 있다면요.', `MaleText_loc4`='要是你有胃口，贫瘠之地可是个打猎的好地方。', `MaleText_loc5`='在貧瘠之地這裡有些不錯的打獵地點，如果你有種的話。', `MaleText_loc7`='Hay buena caza en Los Baldíos, si es que tienes estómago para ellos.' WHERE `ID`=38961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전방 지휘소와는 아직 단절된 상태지만, 당신이 가시멧돼지와 ''협상''해준 덕에 팔만 좀 더 휘두르면 길이 다시 뚫리겠습니다.', `MaleText_loc4`='我们和前线指挥站还没取得联系。但多亏了你和那些野猪人的“沟通”。只要再做些努力，就能重新打通道路了。', `MaleText_loc5`='我們仍舊無法跟前線指揮營地聯絡上，不過多謝了你跟野豬人的「溝通」，我們只需要花一點力氣便能重新開啟這些道路。', `MaleText_loc7`='Todavía estamos aislados del Mando de Vanguardia, pero gracias a tus "negociaciones", con un poco de trabajo duro debería ser posible reabrir los caminos.' WHERE `ID`=38962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하사관님은 좋은 분이시지만 명령을 내릴 때만큼은 다른 건 신경도 안 쓰신다니까요.$B$B이곳에선 뭔가 이상한 일이 벌어지고 있어요, $n 님. 여긴 밀림이 있어야 할 곳이 아니라고요!', `FemaleText_loc4`='下士是个好人，但一执行命令就变得鼠目寸光。$B$B这地方好像有什么不对劲，$n。这片丛林不该出现在这里！', `FemaleText_loc5`='下士是一個好人，但在命令之下眼光會變得狹隘。$B$B不自然的現象正發生在這片土地上，$n。這片叢林不該在這!', `FemaleText_loc7`='El cabo es un buen hombre, pero tiene una visión limitada cuando se trata de órdenes.$B$BAlgo antinatural le ocurre a esta tierra, $n. ¡Esta jungla no debería estar aquí!' WHERE `ID`=38963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들은 랩터가 사납고 포악하다고 생각합니다만, 사실 랩터들은 놀라울 정도로 충성스럽고 영리하답니다.', `MaleText_loc4`='人们对迅猛龙的了解只限于野蛮凶残，除此之外知之甚少。实际上，他们的忠诚和机智超乎你的想象。', `MaleText_loc5`='大家認為迅猛龍不過是野蠻和兇猛的動物。事實上，牠們的忠心和狡猾是你想像不到的。', `MaleText_loc7`='Mucha gente piensa que los raptores solo son salvaje'' y violentos. En realidad, son más leales y ah''tutos de lo que piensas.' WHERE `ID`=38964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두둥실 떠오르는 거예요. 운전은 제가 할 테니 지켜보기만 하세요.', `FemaleText_loc4`='出发了宝贝儿。我来掌舵，你留心周围。', `FemaleText_loc5`='上路了，親愛的。我來掌舵，你來觀察。', `FemaleText_loc7`='Sube a bordo y despegamos, cielín. Yo llevo el timón, tú tan solo ten los ojos bien abiertos.' WHERE `ID`=38965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이제 구명로켓을 아래에 있는 생존자들에게 던져주세요. 그리고 해적들에게는 폭탄을 던져주고요. 두 개를 섞어 놓지는 마세요, 아셨죠?', `FemaleText_loc4`='好吧，快把救生火箭包扔给下面的幸存者，把炸弹扔给海盗。可别搞混了，知道吗？', `FemaleText_loc5`='好了，把救生火箭丟下去給生還者，把炸彈丟到海盜頭上。記得不要搞混了，OK?', `FemaleText_loc7`='Vale, lanza los paquetes de los cohetes salvavidas a los supervivientes y arroja las bombas sobre los piratas. Intenta no liarte, ¿vale?' WHERE `ID`=38966;
