UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이럴 수가! 다들 어디 있죠? 여기에 내려줬는데!', `FemaleText_loc4`='哦不！人都去哪儿了？我把他们放在这儿的！', `FemaleText_loc5`='噢不!大家到哪去了?我明明把他們放在這的!', `FemaleText_loc7`='¡Oh no! ¿Dónde está todo el mundo? ¡Los dejé aquí!' WHERE `ID`=38971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강력한 충격의 소용돌이를 시전하기 시작합니다!', `MaleText_loc4`='%s开始发动强能震荡涡流！', `MaleText_loc5`='%s開始施展強力震擊漩渦!', `MaleText_loc7`='¡%s comienza a lanzar Vórtice de choque potenciado!' WHERE `ID`=38972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤에 앉아요. 여기서 빠져나갈 거예요. 우리 옛 친구인 오크가 어디 있는지 알아요!', `FemaleText_loc4`='在后座上坐好。我们马上就要离开这里了。我知道我们的兽人老朋友在哪儿！', `FemaleText_loc5`='到後座去。我們要離開這裡。我知道我們的獸人老朋友們在哪!', `FemaleText_loc7`='Sube al asiento de atrás, nos largamos. ¡Sé dónde están nuestros viejos amigos, los orcos!' WHERE `ID`=38973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤를 조심하시오, $n! 적이 접근 중이오!', `MaleText_loc4`='$n，注意背后！小心！', `MaleText_loc5`='在你後面，$n!小心，要來了!', `MaleText_loc7`='¡Detrás de ti, $n! ¡Cuidado, se acercan!' WHERE `ID`=38974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이오! 호드가 쳐들어오고 있으니 뒤를 조심하시오, $n!', `MaleText_loc4`='来啦！部落来啦——$n，小心身后！', `MaleText_loc5`='敵人來襲! 部落殺過來了 - 小心你後面，$n!', `MaleText_loc7`='¡Vienen! ¡Viene la Horda! ¡Cuidado, detrás de ti, $n!' WHERE `ID`=38975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\ability_creature_cursed_01.blp:12|t %s|1이;가; |cFFFF7F00치명적인 가스|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_creature_cursed_01.blp:12|t %s开始释放|cFFFF7F00邪恶毒气！|r', `MaleText_loc5`='|TInterface\\Icons\\ability_creature_cursed_01.blp:12|t%s施展|cFFFF7F00污穢毒氣!|r', `MaleText_loc7`='|TInterfaceIconsability_creature_cursed_01.blp:12|t ¡%s lanza |cFFFF7F00Gas inmundo!|r' WHERE `ID`=38977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가를 향한 공격에 참여하고 싶으신가요?', `MaleText_loc4`='你想要加入对抗纳迦的战斗吗？', `MaleText_loc5`='你要加入攻擊納迦的行動嗎?', `MaleText_loc7`='¿Quieres unih''te al ataque contra los nagas?' WHERE `ID`=38978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 그곳으로 저를 태워갈 랩터가 있습니까?', `MaleText_loc4`='是的。你有迅猛龙可以带我过去吗？', `MaleText_loc5`='是的。你有可以把我帶到那的迅猛龍嗎?', `MaleText_loc7`='Sí. ¿Tienes un raptor que pueda llevarme allí?', `FemaleText_loc1`='네. 그곳으로 저를 태워갈 랩터가 있습니까?', `FemaleText_loc4`='是的。你有迅猛龙可以带我过去吗？', `FemaleText_loc5`='是的。你有可以把我帶到那的迅猛龍嗎?', `FemaleText_loc7`='Sí. ¿Tienes un raptor que pueda llevarme allí?' WHERE `ID`=38979;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내게서 떨어져, 이 괴물! 날 보지 마! 난 지금 끔찍한 모습이란 말이야!', `FemaleText_loc4`='滚开，怪物！别盯着我！我知道我很丑！', `FemaleText_loc5`='離我遠一點，你這個怪獸!不要看我!我很恐怖!', `FemaleText_loc7`='¡Aléjate de mí, monstruo! ¡No me mires! ¡Soy horrenda!' WHERE `ID`=38980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 끔찍한 모습이 아닙니다, 릴리안... 우리의 일원이죠. 여기 이 거울을 보고 직접 확인하십시오.', `MaleText_loc4`='你不丑，莉莉安……你跟我们一样。来，看看这面镜子，看看你自己的样子。', `MaleText_loc5`='你並不醜陋，莉莉安...你是我們的一份子。看，看這面鏡子，用你自己的雙眼看看。', `MaleText_loc7`='No eres horrible, Lilian... eres una de nosotros. Toma, mírate en este espejo y compruébalo tú misma.', `FemaleText_loc1`='당신은 끔찍한 모습이 아니에요, 릴리안... 우리의 일원이죠. 여기 이 거울을 보고 직접 확인해보세요.', `FemaleText_loc4`='你不丑，莉莉安……你跟我们一样。来，看看这面镜子，看看你自己的样子。', `FemaleText_loc5`='你並不醜陋，莉莉安...你是我們的一份子。看，看這面鏡子，用你自己的雙眼看看。', `FemaleText_loc7`='No eres horrible, Lilian... eres una de nosotros. Toma, mírate en este espejo y compruébalo tú misma.' WHERE `ID`=38981;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 몰라... 난 언데드가 돼선 안 돼! 내가 왜... 이제 와서...', `FemaleText_loc4`='你不明白……我不能变成亡灵！我不能，现在不能……', `FemaleText_loc5`='你不懂...我不能變成不死族!不該是我，不該是現在...', `FemaleText_loc7`='No lo entiendes... ¡NO PUEDO estar no-muerta! Yo no, ahora no...' WHERE `ID`=38982;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지, 안 돼! 잠깐... 여긴 어디지?', `FemaleText_loc4`='父亲，不！等等……我在哪里？', `FemaleText_loc5`='父親，不!等等...我在哪?', `FemaleText_loc7`='¡Padre, no! Un segundo... ¿dónde estoy?' WHERE `ID`=38983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아악! 저리 가, 이 악마!', `FemaleText_loc4`='啊！滚开，魔鬼！', `FemaleText_loc5`='啊!離遠我一點，你這個惡魔!', `FemaleText_loc7`='¡Aaah! ¡No te acerques a mí, desalmado!' WHERE `ID`=38984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 여기서 뭐 하는 건가? 어서 나가!', `FemaleText_loc4`='你在这里干什么？离开这儿！', `FemaleText_loc5`='你在這做什麼?滾出去!', `FemaleText_loc7`='¿Qué haces aquí? ¡Fuera!' WHERE `ID`=38985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 당신을 구하러 왔습니다.', `MaleText_loc4`='我是来救你的。', `MaleText_loc5`='我是來這救你的。', `MaleText_loc7`='He venido a rescatarte.', `FemaleText_loc1`='전 당신을 구하러 왔어요.', `FemaleText_loc4`='我是来救你的。', `FemaleText_loc5`='我是來這救你的。', `FemaleText_loc7`='He venido a rescatarte.' WHERE `ID`=38986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 구출될 필요가 없네. 그리고 무슨 일이 있어도 너 같은 누더기골렘 따위에게 구출되지 않을 거야!', `FemaleText_loc4`='首先，我不需要被援救。第二，我绝不会让你这样的憎恶来救我！', `FemaleText_loc5`='第一，我不需要被拯救。第二，我永遠都無法允許我被你這種禍害救!', `FemaleText_loc7`='En primer lugar, no necesito que me rescaten. En segundo lugar, ¡nunca dejaría que me rescatara una abominación como tú!' WHERE `ID`=38987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴리안, 당신은 저처럼 포세이큰입니다. 그렇다면, 왜 붉은십자군이 당신을 감옥에 가두었는지 아십니까? 원래 그들은 언데드를 발견하는 족족 죽이지 않습니까.', `MaleText_loc4`='莉莉安，你是被遗忘者，就像我一样。可问题是——为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。', `MaleText_loc5`='莉莉安，你是被遺忘者的一員，就跟我一樣。問題來了:為什麼血色十字軍會將你關在籠子裡?他們一向見到不死族都是格殺勿論。', `MaleText_loc7`='Lilian, eres una de los Renegados, igual que yo. Y eso me hace preguntarme: ¿Por qué la Cruzada Escarlata te ha metido en una jaula? Normalmente matan a los no-muertos en cuanto los ven.', `FemaleText_loc1`='릴리안, 당신은 저처럼 포세이큰이에요. 그렇다면, 왜 붉은십자군이 당신을 감옥에 가두었는지 아세요? 원래 그들은 언데드를 발견하는 족족 죽이잖아요.', `FemaleText_loc4`='莉莉安，你是被遗忘者，就像我一样。可问题是——为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。', `FemaleText_loc5`='莉莉安，你是被遺忘者的一員，就跟我一樣。問題來了:為什麼血色十字軍會將你關在籠子裡?他們一向見到不死族都是格殺勿論。', `FemaleText_loc7`='Lilian, eres una de los Renegados, igual que yo. Y eso me hace preguntarme: ¿Por qué la Cruzada Escarlata te ha metido en una jaula? Normalmente matan a los no-muertos en cuanto los ven.' WHERE `ID`=38988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 붉은십자군이 당신을 감옥에 가두었는지 아십니까? 원래 그들은 언데드를 발견하는 족족 죽이지 않습니까.', `MaleText_loc4`='为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。', `MaleText_loc5`='血色十字軍為什麼要把你關在籠子裡?他們一般碰到不死族都會直接就地正法。', `MaleText_loc7`='¿Por qué la Cruzada Escarlata te ha metido en una jaula? Normalmente matan a los no-muertos en cuanto los ven.', `FemaleText_loc1`='왜 붉은십자군이 당신을 감옥에 가두었는지 아세요? 원래 그들은 언데드를 발견하는 족족 죽이잖아요.', `FemaleText_loc4`='为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。', `FemaleText_loc5`='血色十字軍為什麼要把你關在籠子裡?他們一般碰到不死族都會直接就地正法。', `FemaleText_loc7`='¿Por qué la Cruzada Escarlata te ha metido en una jaula? Normalmente matan a los no-muertos en cuanto los ven.' WHERE `ID`=38989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 언데드가 아니야! 이제 곧 아버지가 구하러 올 거고, 난 알 수 있어...', `FemaleText_loc4`='我不是亡灵！至少很快就不是了。我父亲会来救我，我知道……', `FemaleText_loc5`='我不是不死族!很快就不會是了。我的父親會救我的，我相信...', `FemaleText_loc7`='¡No soy no-muerta! No por mucho tiempo, al menos. Sé que mi padre me rescatará...' WHERE `ID`=38990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금, 당신의 아버지라고 했습니까?', `MaleText_loc4`='你父亲？', `MaleText_loc5`='你的父親?', `MaleText_loc7`='¿Tu padre?', `FemaleText_loc1`='당신의 아버지요?', `FemaleText_loc4`='你父亲？', `FemaleText_loc5`='你的父親?', `FemaleText_loc7`='¿Tu padre?' WHERE `ID`=38991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음엔 케잔이더니 이젠 여기네요. 이 섬을 탈출할 방법을 찾지 못하면 우린 죽은 목숨이나 마찬가지예요!', `FemaleText_loc4`='先是科赞，现在又是这里。如果不马上离开这座岛，我们就要被烤熟了！', `FemaleText_loc5`='先是凱贊然後是這。如果不找到方法逃出這個島，我們都會變成烤肉的!', `FemaleText_loc7`='Primero Kezan y luego aquí. ¡Si no encontramos el modo de salir de esta isla pronto, estamos acabados!' WHERE `ID`=38992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 시간이 왔다. 내 작은 포로여... 네 아버지의 말을 전하러 왔다.', `MaleText_loc4`='时间到了，我的小俘虏……你父亲那里传来了消息。', `MaleText_loc5`='是時候了，我弱小的囚犯...你父親已經下了定論。', `MaleText_loc7`='Ha llegado la hora, mi pequeña cautiva... Tenemos noticias de tu padre.' WHERE `ID`=38993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='게블러, 왔구나! 뭐라시던?', `FemaleText_loc4`='盖比勒，你来了！他怎么说？', `FemaleText_loc5`='哥伯勒，你來了!他說了什麼?', `FemaleText_loc7`='¡Gebler, has venido! ¿Qué ha dicho?' WHERE `ID`=38994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이제 그분의 딸이 아니라고 하셨다. 지금 당장 너를 처형하라고도 하셨지.', `MaleText_loc4`='高阶牧师沃斯已经抛弃了你这个女儿。他要求立刻把你处死。', `MaleText_loc5`='高階祭司佛斯宣稱與妳斷絕父女關係。他下了命令讓妳立即接受死刑。', `MaleText_loc7`='El sumo sacerdote Voss te rechaza como hija. Ha ordenado que te ejecutemos inmediatamente.' WHERE `ID`=38995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐? 아니야! 그럴 리가! 게블러, 넌 날 알잖아, 우린 친구였잖아!', `FemaleText_loc4`='什么？不！这不可能！盖比勒，你了解我……我们曾经是朋友！', `FemaleText_loc5`='什麼?不!這不可能!哥伯勒，你瞭解我...我們曾經是朋友!', `FemaleText_loc7`='¿Qué? ¡NO! ¡No puede ser! Gebler, tú me conoces... ¡una vez fuimos amigos!' WHERE `ID`=38996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사제님께서 안타까워하시더군. 언젠가 네가 적을 향한 강력한 무기가 되길 바라셨으니 말이야.', `MaleText_loc4`='高阶牧师对你失望不已。他曾经以为，你终有一天会成为我们对抗敌人的一件强大武器。', `MaleText_loc5`='高階祭師表達了他的遺憾。他希望有一天你能成為對抗我們敵人的強力武器。', `MaleText_loc7`='El sumo sacerdote nos transmite su pesar. Tenía la esperanza de que llegara el momento en el que te convirtieses en un arma poderosa contra nuestros enemigos.' WHERE `ID`=38997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안됐지만 넌 생전에도 너무나 위험한 존재였고, 언데드가 되어 더욱더 위험해졌다. 기쁘게 처치해 주마, 스컬지 마녀야...', `MaleText_loc4`='不幸的是，你活着的时候就太过危险，成为亡灵后变得更加危险。受死吧，天灾女巫……', `MaleText_loc5`='很悲哀地，妳活著的時候很危險，死了之後更加地危險。我會享受殺妳的過程的，妳這該死的天譴女巫...', `MaleText_loc7`='Desafortunadamente, viva eras demasiado peligrosa, y como no-muerta lo eres mucho más. Disfrutaré matándote, bruja plagada.' WHERE `ID`=38998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아있는 모든 것이 내게 등을 돌린다 해도, 나는 저주받은 스컬지는 되지 않겠다. 그냥 가거라.', `FemaleText_loc4`='生者的世界已经抛弃了我，但我并不是该诅咒的天灾亡灵。走吧。', `FemaleText_loc5`='生者的世界或許已經背棄了我，但我也不屬於那該死的天譴軍。你走吧。', `FemaleText_loc7`='Quizá el mundo de los vivos me haya dado la espalda, pero yo no pertenezco a la maldita Plaga. Lárgate.' WHERE `ID`=38999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 난... 잠깐, 조용히 해! 부관이 다가오는 소리가 들려.', `FemaleText_loc4`='是……等等，安静！我听到那名军官正向这里走来。', `FemaleText_loc5`='是的，我的...噓!小聲點!我聽到中尉接近的聲音。', `FemaleText_loc7`='Sí, mi... ¡Espera, silencio! Oigo que se acerca el teniente.' WHERE `ID`=39000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='게블러, 아버지, 어째서...', `FemaleText_loc4`='盖比勒，父亲，为什么你们……', `FemaleText_loc5`='哥伯勒，父親，為什麼你...', `FemaleText_loc7`='Gebler, padre, por qué...' WHERE `ID`=39001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 일원으로 이렇게 자랑스러웠던 적은 없습니다. 볼진 님께서 우리를 영광으로 이끌고 계시니 말입니다.', `MaleText_loc4`='作为暗矛部族的一员，是我最大的光荣。沃金将领导我们赢取巨大的荣耀。', `MaleText_loc5`='沒有比身為暗矛一族更光榮的了。沃金的領導為我們帶來榮耀。', `MaleText_loc7`='Nunca había eh''tado tan orgulloso de ser un Lanza Negra. Vol''jin no'' guía hacia la gloria.' WHERE `ID`=39002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양 앞에 선 사자와 같은 나를 두려워하지 않는구나.', `MaleText_loc4`='我如同羊群前的雄狮，但它们不畏惧我。', `MaleText_loc5`='面對我的力量，他們根本是以卵擊石，但卻毫不畏懼。', `MaleText_loc7`='Aquí estoy, el lobo ante los corderos... y no me temen.' WHERE `ID`=39003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워할 수가 없겠지...', `MaleText_loc4`='也不敢畏惧。', `MaleText_loc5`='他們絕不能害怕...', `MaleText_loc7`='No pueden temerme.' WHERE `ID`=39004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 축하와 애도가 필요한 날이라네...', `MaleText_loc4`='这是值得庆祝的一天，也是应该追悼的一天，英雄……', `MaleText_loc5`='這是值得慶祝，也需要哀悼的一天，英雄...', `MaleText_loc7`='Un día de celebración y lamento, $ghéroe:heroína;.' WHERE `ID`=39005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 우리가 여기에서 어디로 가야 할지는 모르겠네. 아는 것이라곤, 이 일 중 어느 하나라도 그대의 도움이 없이는 불가능했으리라는 점일세.$B$B칠흑의 기사단은 그대에게 경의를 표하는 바이네.', `MaleText_loc4`='英雄，我们还不知道未来的目标在哪里。但我们知道，如果没有你的帮助，我们在这里将一事无成。$B$B黑锋骑士团向你致敬。', `MaleText_loc5`='我們接下來要怎麼做還沒有決定，英雄。我們能確定的是，如果不是因為你的幫忙，我們將無法達成這一切。$B$B黯刃騎士團向你致敬。', `MaleText_loc7`='No sabemos qué ocurrirá ahora, $ghéroe:heroína;. Lo que sí sabemos es que nada de esto habría sido posible sin tu ayuda.$B$BLos Caballeros de la Espada de Ébano te saludan.' WHERE `ID`=39006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 춥군요...', `FemaleText_loc4`='真冷……', `FemaleText_loc5`='好冷...', `FemaleText_loc7`='Tan frío...' WHERE `ID`=39007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차가운 어둠이 다시 몰려오네요...', `FemaleText_loc4`='寒冷和黑暗在向我招手……', `FemaleText_loc5`='寒冷的黑暗在呼喚...', `FemaleText_loc7`='La oscuridad helada nos llama...' WHERE `ID`=39008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 차가움으로부터 절 구해주세요!', `FemaleText_loc4`='请从寒冷中拯救我！', `FemaleText_loc5`='從寒冷中救我出去!', `FemaleText_loc7`='¡Sálvame del frío!' WHERE `ID`=39009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]이제 그림토템 부족이 기반으로 삼을 고향이 생긴 듯합니다.', `MaleText_loc4`='[ph]It appears the Grimtotem clan now has a home to build upon.', `MaleText_loc5`='[ph]看起來恐怖圖騰部族現在有地方能建造家園了。', `MaleText_loc7`='[ph]It appears the Grimtotem clan now has a home to build upon.', `FemaleText_loc1`='[ph]이제 그림토템 부족이 기반으로 삼을 고향이 생긴 듯하군요.', `FemaleText_loc4`='[ph]It appears the Grimtotem clan now has a home to build upon.', `FemaleText_loc5`='[ph]看起來恐怖圖騰部族現在有地方能建造家園了。', `FemaleText_loc7`='[ph]It appears the Grimtotem clan now has a home to build upon.' WHERE `ID`=39010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]그렇게 빨리라고는 하지 않겠습니다.', `MaleText_loc4`='[ph]I would not say that so soon.', `MaleText_loc5`='[ph]我不會這麼快就下定論。', `MaleText_loc7`='[ph]I would not say that so soon.', `FemaleText_loc1`='[ph]그렇게 빨리라고는 하지 않겠어요.', `FemaleText_loc4`='[ph]I would not say that so soon.', `FemaleText_loc5`='[ph]我不會這麼快就下定論。', `FemaleText_loc7`='[ph]I would not say that so soon.' WHERE `ID`=39011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은창 녀석들아, 시작한 일을 끝내고자 내가 돌아왔도다. 너희의 피가 섬에 흐를 것이다.', `FemaleText_loc4`='我回来是为了结束我所开始的一切，暗矛巨魔。这些岛屿将成为你的墓地。', `FemaleText_loc5`='我回來完成我該做的，暗矛部族。這些島嶼將染上你們的鮮血。', `FemaleText_loc7`='He vuelto para terminar lo que empecé, Lanza Negra. Sssu sangre empapará estas islasss.' WHERE `ID`=39012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차려엇!', `MaleText_loc4`='立……正！', `MaleText_loc5`='集合!', `MaleText_loc7`='¡Aaaateeen... CIÓN!' WHERE `ID`=39013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 아비는 허약한 자였다, 볼진. 네 아비에게 했던 것처럼 네 생명을 빨아내는 걸 즐길 것이다.', `FemaleText_loc4`='沃金，你的父亲是个无能的家伙。我很愿意从你的身上吸取生命，就像对他一样。', `FemaleText_loc5`='你的父親是個弱蝦，沃金。我會好好享受消磨你的生命的，就像我對他所做的一樣。', `FemaleText_loc7`='Tu padre era un debilucho, Vol''jin. Disfrutaré succionándote la vida, como disfruté con él.' WHERE `ID`=39014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 또 다른 검은창 전사 녀석이 내 제단에 희생됐구나. 하나하나씩 모두 죽으리라.', `FemaleText_loc4`='啊，又一名暗矛战士被放到了我的祭坛上。一个接一个，你们终将彻底毁灭。', `FemaleText_loc5`='啊，另一個暗矛戰士獻祭在我的祭壇上。一個接著一個，你們全都要死。', `FemaleText_loc7`='Ah, otro guerrero Lanza Negra sacrificado en mi altar. Uno a uno, todos moriréis.' WHERE `ID`=39015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은창 녀석들아, 이번엔 스랄이 너희를 구해주지 않는다. 살금살금 어둠 속으로 숨거라. 내가 너희를 마지막 녀석까지 찾아내 주마.', `FemaleText_loc4`='这次萨尔不会来拯救你们了，暗矛巨魔。躲到阴影中去吧，我会将你们逐一猎杀。', `FemaleText_loc5`='索爾不在這，他這次無法再救你們了，暗矛部族。溜回暗影去吧，因為我會把你們一個個殺得乾乾淨淨。', `FemaleText_loc7`='Thrall no está aquí para salvaros esta vez, Lanza Negra. Escabúllanse hacia las sombras, pues cazaré hasta al último de ustedes.' WHERE `ID`=39016;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파도가 검은창 부족을 깡그리 쓸어가리라.', `FemaleText_loc4`='潮水将会冲走整个暗矛部落。', `FemaleText_loc5`='浪潮將會衝垮整個暗矛部族。', `FemaleText_loc7`='Lasss mareas ssse llevarán a toda la tribu Lanza Negra.' WHERE `ID`=39017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롤 약골 녀석들아, 희망 따윈 없다. 파도가 너희의 죽음을 예견했다.', `FemaleText_loc4`='软弱的巨魔们，你们已经没有希望了。潮水已预言了你们的灭亡。', `FemaleText_loc5`='弱蝦食人妖，希望是不存在的。你們的死亡已在浪潮的預測之中。', `FemaleText_loc7`='Debiluchosss trols, no hay esperanza. Las mareasss han presagiado su muerte.' WHERE `ID`=39018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 부족 녀석들을 끝장내면 일전에 내 분노의 손길에서 너를 구해낸 그 오크 녀석을 찾아내고야 말겠다. 누구도 살아남지 못할 거다.', `FemaleText_loc4`='当我消灭掉你们一族之后，我会去干掉那些该死的兽人。他们曾经在我的怒火中救过你们一次。但这次历史不会重演了。', `FemaleText_loc5`='當我解決了你們一族，我將獵殺那個之前從我手上救出你們的獸人垃圾。沒人得以存活。', `FemaleText_loc7`='Cuando haya acabado con su tribu, cazaré a essse perro orco que ssse libró de mi ira en el passsado. Nadie sobrevivirá.' WHERE `ID`=39019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희는 고향의 안전을 버린 멍청이들이었다. 바다로 돌아와 봤자 너희의 종말만 확인할 뿐이다.', `FemaleText_loc4`='离开你们安全的城市是愚蠢的。当你们回到大海上的时候，你们的灭亡就注定了。', `FemaleText_loc5`='離開你們安全的城市是個愚蠢的決定。回到海洋便注定了你們悲慘的下場。', `FemaleText_loc7`='Fueron unos insensatosss al abandonar la seguridad de su ciudad. Su regressso al océano asegura su perdición.' WHERE `ID`=39020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무장... 준비!', `MaleText_loc4`='武装……准备！', `MaleText_loc5`='拿起武器!', `MaleText_loc7`='¡Presenteeeeen... ARMAS!' WHERE `ID`=39021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오른쪽 어깨... 장착!', `MaleText_loc4`='枪托上肩！', `MaleText_loc5`='托槍...上肩!', `MaleText_loc7`='¡ARMAAAAS... al hombro!' WHERE `ID`=39022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격 준비!', `MaleText_loc4`='瞄准！', `MaleText_loc5`='瞄準!', `MaleText_loc7`='¡PRESENTE!' WHERE `ID`=39023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 꾸물대지 마, 그리즈왈드!', `MaleText_loc4`='格兹沃德，睁大眼睛。', `MaleText_loc5`='看起來有精神點，葛瑞茲沃德。', `MaleText_loc7`='Más rápido, Grizwald.' WHERE `ID`=39024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홀름버그, 대체 무기를 언제 닦은 건가?', `MaleText_loc4`='赫姆伯格，你上次清理武器是在什么时候？', `MaleText_loc5`='你最後一次保養那個武器是什麼時候，霍姆柏格?', `MaleText_loc7`='¿Cuándo limpiaste esa arma por última vez, Holmberg?' WHERE `ID`=39025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 감고 조준하는 거 아냐, 바클리!', `MaleText_loc4`='巴克利，我们闭上眼睛就没法瞄准了！', `MaleText_loc5`='巴克萊，我們不會閉著眼睛瞄準!', `MaleText_loc7`='¡Barkley, NO se apunta con los ojos cerrados!' WHERE `ID`=39026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='색깔이 뭐든지 간에, 상대편의 눈을 본 다음에 쏘는 걸 명심해라!', `MaleText_loc4`='记住，在看清楚他们眼睛的颜色之前绝不能开火。', `MaleText_loc5`='記住，你們要開火必須看見...管他們的眼睛是什麼顏色。', `MaleText_loc7`='Recordad, no dispararéis hasta que podáis ver el... el color del que sean sus ojos.' WHERE `ID`=39027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠르군. 하지만 아직 부족해. 다시 간다.', `MaleText_loc4`='很快。但还不够快。我们再做一遍。', `MaleText_loc5`='快，但還不夠快。我們再做一次。', `MaleText_loc7`='Rápido, pero no lo suficiente. Una vez más.' WHERE `ID`=39028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잭슨, 바닥에 화약을 잔뜩 흘렸잖나. <한숨>', `MaleText_loc4`='杰克逊，你把火药洒得到处都是。<叹气>', `MaleText_loc5`='傑克森，你把你的火藥粉都灑到地上了。<嘆氣>', `MaleText_loc7`='Jackson, has tirado toda la pólvora por el suelo. <Suspiro>' WHERE `ID`=39029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 목표물을 처치하는 게 우리 일이다. 일이란 좋은 거지.', `MaleText_loc4`='先生们，我们的工作是杀敌。这是个美妙的工作。', `MaleText_loc5`='先生們，我們的工作是殺人。而有工作是好事。', `MaleText_loc7`='Caballeros, nuestro negocio es el asesinato. Y el negocio va BIEN.' WHERE `ID`=39030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬어.', `MaleText_loc4`='放松。', `MaleText_loc5`='解散。', `MaleText_loc7`='Descansen.' WHERE `ID`=39031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph] 그 위선자가 여기 오는 여부에 대해서는 아무런 할 말이 없습니다.', `MaleText_loc4`='[ph] We will not have anything to speak of if the Pretender comes here.', `MaleText_loc5`='[ph]如果那個篡位者來到這裡，我們跟他沒什麼好說的。', `MaleText_loc7`='[ph] We will not have anything to speak of if the Pretender comes here.', `FemaleText_loc1`='[ph] 그 위선자가 여기에 오는 여부에 대해서는 아무런 할 말이 없어요.', `FemaleText_loc4`='[ph] We will not have anything to speak of if the Pretender comes here.', `FemaleText_loc5`='[ph]如果那個篡位者來到這裡，我們跟他沒什麼好說的。', `FemaleText_loc7`='[ph] We will not have anything to speak of if the Pretender comes here.' WHERE `ID`=39032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]베인이라고요? 여기에 온다면 정신이 나간 거겠죠. 우리가 적어도 두 배는 많습니다. 걱정할 쪽은 베인입니다.', `MaleText_loc4`='[ph]Baine?  He would be crazy to come here.  We outnumber him at least two to one.  He''s the one that should be worried.', `MaleText_loc5`='[ph]貝恩?要他來這的話他會抓狂的。我們這邊人數至少是他的兩倍。那個需要擔心的對象是他才對。', `MaleText_loc7`='[ph]Baine?  He would be crazy to come here.  We outnumber him at least two to one.  He''s the one that should be worried.', `FemaleText_loc1`='[ph]베인이라고요? 여기에 온다면 정신이 나간 거겠죠. 우리가 적어도 두 배는 많아요. 걱정할 쪽은 베인이에요.', `FemaleText_loc4`='[ph]Baine?  He would be crazy to come here.  We outnumber him at least two to one.  He''s the one that should be worried.', `FemaleText_loc5`='[ph]貝恩?要他來這的話他會抓狂的。我們這邊人數至少是他的兩倍。那個需要擔心的對象是他才對。', `FemaleText_loc7`='[ph]Baine?  He would be crazy to come here.  We outnumber him at least two to one.  He''s the one that should be worried.' WHERE `ID`=39033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]블러드후프를 우습게 보지 마십시오. 케른 님께서 지니셨던 토템은 본 적 있습니까?', `MaleText_loc4`='[ph]Do not underestimate members of the Bloodhoof.  Did you ever see that totem that Cairne carried around?', `MaleText_loc5`='[ph]別低估了血蹄那邊的人數。你有沒有看過凱恩平常帶著的那根圖騰?', `MaleText_loc7`='[ph]Do not underestimate members of the Bloodhoof.  Did you ever see that totem that Cairne carried around?', `FemaleText_loc1`='[ph]블러드후프를 우습게 보지 마세요. 케른 님께서 지니셨던 토템은 본 적 있나요?', `FemaleText_loc4`='[ph]Do not underestimate members of the Bloodhoof.  Did you ever see that totem that Cairne carried around?', `FemaleText_loc5`='[ph]別低估了血蹄那邊的人數。你有沒有看過凱恩平常帶著的那根圖騰?', `FemaleText_loc7`='[ph]Do not underestimate members of the Bloodhoof.  Did you ever see that totem that Cairne carried around?' WHERE `ID`=39034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]저도 얘기만 들었습니다. 누군가는 두 손을 다 써야만 들어 올릴 수 있는 토템이라고 했는데, 케른 님은 한 손으로도 쉽게 휘두르셨습니다.', `MaleText_loc4`='[ph]I''ve only heard stories.  Some say it can only be picked up with two hands, but Cairne could wield it easily in one.', `MaleText_loc5`='[ph]我只聽過故事。有些人說這得要用兩手才能拿得起來，可是凱恩用單手就能輕鬆揮舞。', `MaleText_loc7`='[ph]I''ve only heard stories.  Some say it can only be picked up with two hands, but Cairne could wield it easily in one.', `FemaleText_loc1`='[ph]저도 얘기만 들었어요. 누군가는 두 손을 다 써야만 들어 올릴 수 있는 토템이라고 했는데, 케른 님은 한 손으로도 쉽게 휘두르셨어요.', `FemaleText_loc4`='[ph]I''ve only heard stories.  Some say it can only be picked up with two hands, but Cairne could wield it easily in one.', `FemaleText_loc5`='[ph]我只聽過故事。有些人說這得要用兩手才能拿得起來，可是凱恩用單手就能輕鬆揮舞。', `FemaleText_loc7`='[ph]I''ve only heard stories.  Some say it can only be picked up with two hands, but Cairne could wield it easily in one.' WHERE `ID`=39035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[ph]그렇죠. 베인이 그 아버지의 반도 못 따라오기를 바랄 뿐입니다... 아니면 경비병을 더 세워야 할 테니까요.', `MaleText_loc4`='[ph] Exactly.  Let us hope that Baine has less than half the strength of his father...or we are going to need more guards.', `MaleText_loc5`='[ph]的確是。讓我們祈禱貝恩的力量不及他父親的一半...不然我們需要的是更多的衛兵。', `MaleText_loc7`='[ph] Exactly.  Let us hope that Baine has less than half the strength of his father...or we are going to need more guards.', `FemaleText_loc1`='[ph]그렇죠. 베인이 그 아버지의 반도 못 따라오기를 바랄 뿐이에요... 아니면 경비병을 더 세워야 할 테니까요.', `FemaleText_loc4`='[ph] Exactly.  Let us hope that Baine has less than half the strength of his father...or we are going to need more guards.', `FemaleText_loc5`='[ph]的確是。讓我們祈禱貝恩的力量不及他父親的一半...不然我們需要的是更多的衛兵。', `FemaleText_loc7`='[ph] Exactly.  Let us hope that Baine has less than half the strength of his father...or we are going to need more guards.' WHERE `ID`=39036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 막 요리 중입니다, $n 님.', `MaleText_loc4`='我们正在做饭，$n。', `MaleText_loc5`='我們現在在烹飪，$n。', `MaleText_loc7`='Ahora sí que sí, $n.' WHERE `ID`=39037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와서 좀 드세요!', `MaleText_loc4`='快来尝尝！', `MaleText_loc5`='來拿啊!', `MaleText_loc7`='¡Toma eso!' WHERE `ID`=39038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 폭풍주둥이도마뱀이 꽤 독하죠!', `MaleText_loc4`='长官，这些雷角蜥蜴真是麻烦。', `MaleText_loc5`='是的長官，那些雷角蜥蜴打人還頗痛的。', `MaleText_loc7`='Sí señor, esos morrotormenta no son moco de pavo.' WHERE `ID`=39039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님의 도움을 진심으로 감사하게 생각하고 있습니다. 우리가 싸우는 적은 단순한 야수가 아닌, 교활하고 사악하기 그지없는 적입니다. 모두가 단결하지 않으면 자멸할 것이 분명합니다.', `MaleText_loc4`='要知道，我衷心感谢你的帮助，$c。我们在这里的敌人并不是普通的野兽，而是兼具狡诈与疯狂的怪物。我们必须团结一致，否则就会被它们逐一击破。', `MaleText_loc5`='我要讓你知道我們真的很感謝你的幫助，$c。我們的敵人並不是野獸，但卻狡猾且瘋狂。如果我們不集中在一起，就會一個個被吊死。', `MaleText_loc7`='Quiero que sepas que aprecio tu ayuda de verdad, $n. No estamos luchando contra animales, sino que nos enfrentamos a un enemigo astuto y fanático. Debemos permanecer juntos o separarnos.' WHERE `ID`=39040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름이 뭐라고 하셨죠, $c님?$B$B불모의 땅에 오신 걸 환영합니다. 이 대륙에서 중요한 작전을 수행 중인 선봉기지에 와 계십니다. 당신의 힘을 기꺼이 빌려주신다면 영광이겠군요.', `MaleText_loc4`='$c，你叫什么名字？$n？欢迎来到贫瘠之地。你正站在我们在这片大陆上最重要的前锋阵地之一。如果你能帮助我们，我会感到非常荣幸。', `MaleText_loc5`='你的名字是什麼，$c?$n?$B$B歡迎來到貧瘠之地。你現在所在的是我們在這個地區最重要的前線基地。能夠得到你的力量是我的榮幸。', `MaleText_loc7`='¿Cómo te llamas, $c? ¿$n?$B$BTe doy la bienvenida a Los Baldíos. Estás en la vanguardia de una de las mayores operaciones del continente. Me sentiría muy honrado si te quedaras para prestarnos tu fuerza.' WHERE `ID`=39041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 다시는 네놈들에게 지지 않을 것이다. 우리는 지금 그 어느 때보다도 강하다.', `MaleText_loc4`='暗矛部族绝不会再次屈服，女海巫。我们的力量远远超过了你的想象。', `MaleText_loc5`='暗矛部族不會再向你們屈服，札爾基拉。你永遠不可能比我們強大。', `MaleText_loc7`='La Lanza Negra nunca se rendirá a tu especie, Zar''jira. Somos más fuertes que ustedes.' WHERE `ID`=39042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 제가 끄겠습니다!', `MaleText_loc4`='让我去踩灭那妖火！', `MaleText_loc5`='這次讓我來弄這個火!', `MaleText_loc7`='¡Yo me encargaré del fuego!' WHERE `ID`=39043;
