UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 년 동안 자고 일어난 기분이군...', `MaleText_loc4`='我仿佛已经睡了许多年……', `MaleText_loc5`='我感覺好像已經沉睡了很多年...', `MaleText_loc7`='Tengo la sensación de haber dormido durante años...', `FemaleText_loc1`='몇 년 동안 자다 깬 기분이군요...', `FemaleText_loc4`='我仿佛已经睡了许多年……', `FemaleText_loc5`='我感覺好像已經沉睡了很多年...', `FemaleText_loc7`='Tengo la sensación de haber dormido durante años...' WHERE `ID`=39053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇군. 그렇다면 이제 일하러 가야지.', `MaleText_loc4`='啊，我明白了。我猜我应该去工作了。', `MaleText_loc5`='啊，我懂了。那...我想我該回去工作了。', `MaleText_loc7`='Ah, entiendo. Bueno, supongo que entonces vuelvo al trabajo.', `FemaleText_loc1`='아, 그렇군요. 그렇다면 이제 일하러 가야지요.', `FemaleText_loc4`='啊，我明白了。我猜我应该去工作了。', `FemaleText_loc5`='啊，我懂了。那...我想我該回去工作了。', `FemaleText_loc7`='Ah, entiendo. Bueno, supongo que entonces vuelvo al trabajo.' WHERE `ID`=39054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...무슨 일인지 알 것 같군. 최소한 내 자유 의지는 갖고 있으니.', `MaleText_loc4`='……我想，我明白发生了什么事。至少我还有我的自由意志。', `MaleText_loc5`='...我想我知道發生了什麼事。至少我還擁有自由。', `MaleText_loc7`='...Creo que entiendo lo que ha sucedido. Por lo menos todavía conservo mi voluntad propia.', `FemaleText_loc1`='...무슨 일인지 알 것 같군요. 최소한 제 자유 의지는 갖고 있으니까요.', `FemaleText_loc4`='……我想，我明白发生了什么事。至少我还有我的自由意志。', `FemaleText_loc5`='...我想我知道發生了什麼事。至少我還擁有自由。', `FemaleText_loc7`='...Creo que entiendo lo que ha sucedido. Por lo menos todavía conservo mi voluntad propia.' WHERE `ID`=39055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 알겠군. 이제 호드의 일원이 된 건가.', `MaleText_loc4`='啊，我明白了。看样子，现在我已经是部落的一员了。', `MaleText_loc5`='啊，我了解了。看來我現在好像是部落的一份子。', `MaleText_loc7`='Ah, entiendo. Al parecer ahora formo parte de la Horda.', `FemaleText_loc1`='아, 알겠어요. 이제 호드의 일원이 된 거군요.', `FemaleText_loc4`='啊，我明白了。看样子，现在我已经是部落的一员了。', `FemaleText_loc5`='啊，我了解了。看來我現在好像是部落的一份子。', `FemaleText_loc7`='Ah, entiendo. Al parecer ahora formo parte de la Horda.' WHERE `ID`=39056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이해했어. 이제 일하러 가야겠군!', `MaleText_loc4`='啊，我明白。去工作！', `MaleText_loc5`='啊，我明白。開工!', `MaleText_loc7`='Ah, entiendo. ¡A trabajar!', `FemaleText_loc1`='아, 알겠어요. 이제 일해러 가야겠군요!', `FemaleText_loc4`='啊，我明白。去工作！', `FemaleText_loc5`='啊，我明白。開工!', `FemaleText_loc7`='Ah, entiendo. ¡A trabajar!' WHERE `ID`=39057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 언데드가 되다니? 리치 왕에게 복수하고 말겠어!', `MaleText_loc4`='亡灵？我要向巫妖王复仇！', `MaleText_loc5`='不死族?我會向巫妖王復仇!', `MaleText_loc7`='¿No-muerto? ¡Conseguiré vengarme del Rey Exánime!', `FemaleText_loc1`='내가 언데드가 되다니? 리치 왕에게 복수하고 말겠어요!', `FemaleText_loc4`='亡灵？我要向巫妖王复仇！', `FemaleText_loc5`='不死族?我會向巫妖王復仇!', `FemaleText_loc7`='¿No-muerta? ¡Conseguiré vengarme del Rey Exánime!' WHERE `ID`=39058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 알겠군. 날 깨워줘서 고맙소.', `MaleText_loc4`='啊，我现在明白了。感谢你唤醒我。', `MaleText_loc5`='啊哈，我現在懂了。謝謝你叫我起來。', `MaleText_loc7`='Ajá, ahora lo entiendo. Gracias por despertarme.', `FemaleText_loc1`='아, 이제 알겠군요. 절 깨워주셔서 고마워요.', `FemaleText_loc4`='啊，我现在明白了。感谢你唤醒我。', `FemaleText_loc5`='啊哈，我現在懂了。謝謝你叫我起來。', `FemaleText_loc7`='Ajá, ahora lo entiendo. Gracias por despertarme.' WHERE `ID`=39059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 어두워. 언데드가 나랑 잘 맞는지 모르겠군.', `MaleText_loc4`='这里可真黑。真不知道我是不是喜欢成为一个亡灵。', `MaleText_loc5`='這裡好黑啊～～我不確定我喜歡當不死族。', `MaleText_loc7`='Aquí está muy oscuro. No creo que me guste estar no-muerto.', `FemaleText_loc1`='너무 어두워요. 언데드가 저랑 잘 맞는지 모르겠네요.', `FemaleText_loc4`='这里可真黑。真不知道我是不是喜欢成为一个亡灵。', `FemaleText_loc5`='這裡好黑啊～～我不確定我喜歡當不死族。', `FemaleText_loc7`='Aquí está muy oscuro. No creo que me guste estar no-muerta.' WHERE `ID`=39060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 잤다. 잠깐, 내 팔꿈치와 무릎은 어디 갔지?!', `MaleText_loc4`='这场觉睡得真香。等等，我的胳膊肘和膝盖到哪里去了？！', `MaleText_loc5`='真是睡了個好覺。等等，我的手肘和膝蓋去了哪裡?!', `MaleText_loc7`='Ha sido un buen sueñecito. Espera, ¡¿dónde tengo los codos y las rodillas?!', `FemaleText_loc1`='잘 잤다. 잠깐, 제 팔꿈치와 무릎은 어디 갔죠?!', `FemaleText_loc4`='这场觉睡得真香。等等，我的胳膊肘和膝盖到哪里去了？！', `FemaleText_loc5`='真是睡了個好覺。等等，我的手肘和膝蓋去了哪裡?!', `FemaleText_loc7`='Ha sido un buen sueñecito. Espera, ¡¿dónde tengo los codos y las rodillas?!' WHERE `ID`=39061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 너희 모두를 없애리다! 죽음이 이 땅을 뒤덮으리라!', `MaleText_loc4`='天灾军团将把你们全部摧毁！死亡将横扫这片陆地！', `MaleText_loc5`='天譴軍團將消滅你們!死亡將橫掃這片大地!', `MaleText_loc7`='¡La Plaga os destruirá a todos! ¡La muerte arrasará estas tierras!' WHERE `ID`=39062;
