UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 혼자서 다 처리하진 말라고요!', `MaleText_loc4`='别那么快！给我留点，兄弟！', `MaleText_loc5`='慢一點!留一點給我，老兄!', `MaleText_loc7`='¡Espera! ¡Guárdame alguno, hombre!' WHERE `ID`=39064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 흥분되는군요! 볼진 님은 가만히 계실 분이 아닙니다. 반드시 바다 마녀를 잡아서 복수하실 겁니다.', `MaleText_loc4`='这太疯狂了！沃金是认真的。他要找到那个女海巫，向她复仇。', `MaleText_loc5`='這真瘋狂!沃金不是在亂來，他要去找那海巫算帳。', `MaleText_loc7`='¡Eh''to es muy gordo! Vol''jin no se anda con tontería''. Va detrás de esa Bruja del Mar pa'' cobrarse una venganza terrible.' WHERE `ID`=39065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려요, 친구!', `MaleText_loc4`='等等，兄弟！', `MaleText_loc5`='等等，老兄!', `MaleText_loc7`='¡Espera, hombre!' WHERE `ID`=39066;
