UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 쓸데없는 임무일진 몰라도 전 상관없습니다. 새끼 랩터들은 귀엽잖아요.', `MaleText_loc4`='这是件苦差事，但我不介意。这些小恐龙都是可爱的小恶魔。', `MaleText_loc5`='我知道這是苦差事，但是我不在乎。這些小迅猛龍都是可愛的小惡魔。', `MaleText_loc7`='Sé que será mucho trabajo, pero no importa. Estos raptores bebé son unos diablillos.' WHERE `ID`=39068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저만 나쁜 놈 되게 하지 마세요!', `MaleText_loc4`='别让我太难堪，嗯？', `MaleText_loc5`='別讓我太難看，嗯?', `MaleText_loc7`='No me hagas quedar mal, ¿eh?' WHERE `ID`=39069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 결국은 따라잡았군요! 저 안에선 같이 다닙시다.', `MaleText_loc4`='哈！我追上你了！让咱们并肩作战，行吗？', `MaleText_loc5`='哈!我追上你了!我們別再走散了，好嗎?', `MaleText_loc7`='¡Ja! ¡Te alcancé! No nos separemos, ¿sí?' WHERE `ID`=39070;
