UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보시다시피, 제 몫을 챙기고 있는 것뿐입니다.', `MaleText_loc4`='嗨，$g小伙子:姑娘;我正努力要拿到我的那一份。', `MaleText_loc5`='喂，我不過是想拿我應得的。', `MaleText_loc7`='Eh, $gcompadre:comadre;, tan solo estoy intentando llevarme mi trozo de pastel.', `FemaleText_loc1`='보시다시피, 제 몫을 챙기고 있는 것뿐이에요.', `FemaleText_loc4`='嗨，$g小伙子:姑娘;我正在想应该怎样拿到我的那一份。', `FemaleText_loc5`='喂，我不過是想拿我應得的。', `FemaleText_loc7`='Eh, $gcompadre:comadre;, tan solo estoy intentando llevarme mi trozo de pastel.' WHERE `ID`=39072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 끼겠습니까? 닥치는 대로 꺼내서 가져가기만 하면 됩니다!', `MaleText_loc4`='你也想分一份？那你可要努力了，宝贝儿！', `MaleText_loc5`='你想加入?盡情擄掠，寶貝!', `MaleText_loc7`='¿Quieres tajada? ¡Ven a por ella, colega!', `FemaleText_loc1`='당신도 낄래요? 닥치는 대로 꺼내서 가져가기만 하면 돼요!', `FemaleText_loc4`='你也想分一份？那你可要努力了，宝贝儿！', `FemaleText_loc5`='你想加入?盡情擄掠，寶貝!', `FemaleText_loc7`='¿Quieres tajada? ¡Ven a por ella, colega!' WHERE `ID`=39073;
