UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 시체에는 구슬 아니면 잡동사니 뿐이군요. 괜찮은 물건 좀 건졌습니까?', `MaleText_loc4`='所有这些牛头人的身上都只有一些念珠和垃圾。你有没有找到什么有用的东西？', `MaleText_loc5`='這些死掉的牛頭人身上只有珠子和垃圾。你有拿到什麼好東西嗎?', `MaleText_loc7`='Estos tauren muertos no tienen más que cuentas y fruslerías. ¿Has conseguido algo bueno?', `FemaleText_loc1`='타우렌 시체에는 구슬 아니면 잡동사니 뿐이네요. 괜찮은 물건 좀 건졌어요?', `FemaleText_loc4`='所有这些牛头人的身上都只有一些念珠和垃圾。你有没有找到什么有用的东西？', `FemaleText_loc5`='這些死掉的牛頭人身上只有珠子和垃圾。你有拿到什麼好東西嗎?', `FemaleText_loc7`='Estos tauren muertos no tienen más que cuentas y fruslerías. ¿Has conseguido algo bueno?' WHERE `ID`=39075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸만한 건 이미 다 털렸지만 아직 괜찮은 것들이 남았으니 시간을 들여 찾아볼 만해요!', `MaleText_loc4`='嗨，$c！这个地方已经被搜检得差不多了。不过你也许还可以花些时间来搜索一下。', `MaleText_loc5`='喂，$c!這個地方已經被搜括得差不多了，但你應該還是能找到什麼你想要的。', `MaleText_loc7`='¡Oye, $c! Este lugar está bastante saqueado, pero a lo mejor aún puedes encontrar algo que merezca la pena.', `FemaleText_loc1`='쓸만한 건 이미 다 털렸지만 아직 괜찮은 것들이 남았으니 시간을 들여 찾아볼 만해요!', `FemaleText_loc4`='嗨，$c！这个地方已经被搜检得差不多了。不过你也许还可以花些时间来搜索一下。', `FemaleText_loc5`='喂，$c!這個地方已經被搜括得差不多了，但你應該還是能找到什麼你想要的。', `FemaleText_loc7`='¡Oye, $c! Este lugar está bastante saqueado, pero a lo mejor aún puedes encontrar algo que merezca la pena.' WHERE `ID`=39076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마, 우릴 잡으러 온 건 아니겠죠?', `MaleText_loc4`='喔，你来这里不是要对我们进行突击搜查吧？', `MaleText_loc5`='哇，你不是來這找我們麻煩的，對吧?', `MaleText_loc7`='¡Oye! ¿No habrás venido a liberarnos?', `FemaleText_loc1`='설마, 우릴 잡으러 온 건 아니겠죠?', `FemaleText_loc4`='喔，你来这里不是要对我们进行突击搜查吧？', `FemaleText_loc5`='哇，你不是來這找我們麻煩的，對吧?', `FemaleText_loc7`='¡Oye! ¿No habrás venido a liberarnos?' WHERE `ID`=39077;
