UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 가르쳐줄 사람이 여기 어딘가에 있을 겁니다. 나중에 봅시다.', `MaleText_loc4`='你的训练师应该就在不远的地方。稍后我再来找你，兄弟。', `MaleText_loc5`='你的訓練師應該就在訓練場這附近。晚點再聊囉，老兄。', `MaleText_loc7`='Tu entrenador tiene que estar por aquí. Hablamos luego, hombre.' WHERE `ID`=39087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 작전은 큰 무리 없이 진행되리라 예상하고 있어요.', `FemaleText_loc4`='我希望这次行动过程中不会出现任何严重事故。', `FemaleText_loc5`='我希望這個計畫能在沒有重大的突發狀況下進行。', `FemaleText_loc7`='Tengo previsto que la operación salga adelante sin mayores contratiempos.' WHERE `ID`=39088;
