UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 널 사지로 보냈구나, 애송이 녀석.', `MaleText_loc4`='他们要置你于死地，年轻人。', `MaleText_loc5`='他們把你送去受死，年輕人。', `MaleText_loc7`='Te envían a tu muerte, joven.' WHERE `ID`=39091;
