UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서지 말게!', `MaleText_loc4`='守住阵线！', `MaleText_loc5`='堅守防線!', `MaleText_loc7`='¡Mantened el frente!' WHERE `ID`=39093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼라이언스 놈들을 다시 바다로 던져넣겠네!', `MaleText_loc4`='我们要把那些联盟渣滓赶进海里去！', `MaleText_loc5`='我們會把這些聯盟垃圾丟回海中!', `MaleText_loc7`='¡Echaremos a estos perros de la Alianza de vuelta al mar!' WHERE `ID`=39094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르!', `MaleText_loc4`='Lok''tar ogar！', `MaleText_loc5`='(獸人語)不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar!' WHERE `ID`=39095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 할!', `MaleText_loc4`='萨尔万岁！', `MaleText_loc5`='偉大的索爾!', `MaleText_loc7`='¡Larga vida a Thrall!' WHERE `ID`=39096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 겁쟁이들에 진짜 전쟁이 뭔지 가르쳐 주게!', `MaleText_loc4`='让这些懦夫们明白，什么是真正的战争！', `MaleText_loc5`='讓這些膽小鬼看看什麼才是真正的戰爭!', `MaleText_loc7`='¡Enseñadles a estos cobardes el verdadero significado de la guerra!' WHERE `ID`=39097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상님과 진정한 대족장을 위해 싸우게!', `MaleText_loc4`='为了你们的祖先和真正的酋长而战！', `MaleText_loc5`='為你的祖先而戰，為你真正的大酋長而戰!', `MaleText_loc7`='¡Lucha por tus ancestros y por tu verdadero Jefe de Guerra!' WHERE `ID`=39098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 우리를 상대하라고 노움과 드워프를 보냈단 말인가? 장난하나?', `MaleText_loc4`='联盟派侏儒和矮人来对抗我们？他们是在开玩笑吗？！', `MaleText_loc5`='聯盟派了地精和矮人來對抗我們?你這是在開玩笑嗎?', `MaleText_loc7`='¿La Alianza envía gnomos y enanos contra nosotros? ¿Es una broma?' WHERE `ID`=39099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 꼬마 친구가 여기 있군. 고블린에게 잡초 제거기가 있다면 불쌍한 드워프를 위해 눈물을 흘리겠네!', `MaleText_loc4`='我们的小朋友来了。等到地精拿起他们的除草器，我就要为那些矮人哀悼了！', `MaleText_loc5`='我們小個頭的朋友來了。如果哥布林有除草機的話，我會為矮人們感到悲哀。', `MaleText_loc7`='Ha llegado nuestro amiguito. ¡Me apiado de los enanos si el goblin tiene su segador de malas hierbas!' WHERE `ID`=39100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그들을 가지고 노는 거요? 잔인하군.', `MaleText_loc4`='你为什么要玩弄他们？这太残酷了。', `MaleText_loc5`='你幹嘛戲弄他們?很殘忍耶。', `MaleText_loc7`='¿Por qué juegas con ellos? Es cruel.' WHERE `ID`=39101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 죽으려고 작정하고 덤벼드는군. 멍청하기는!', `MaleText_loc4`='找死也要这么着急吗？一群蠢货！', `MaleText_loc5`='他們急著飛蛾撲火。真是蠢!', `MaleText_loc7`='Se lanzan ansiosos a la muerte. ¡Qué necios!' WHERE `ID`=39102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움을 이리 보내야 할지도 모르겠다고? 최악의 선택을 했군!', `MaleText_loc4`='也许他们应该把侏儒派到这里来？他们不可能更蠢了！', `MaleText_loc5`='或許他們可以派地精加入戰場?他們的娛樂性不比矮人低!', `MaleText_loc7`='¿Por qué no envían a sus gnomos? ¡No podrían hacerlo peor!' WHERE `ID`=39103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 광산을 세워서 해변을 망쳐버렸지. 역겨운 놈들!', `MaleText_loc4`='现在这片海滩上到处都埋了他们肮脏的地雷。真可恶！', `MaleText_loc5`='膽小鬼們用了地雷把海岸搞砸了。噁心!', `MaleText_loc7`='Mancillan la costa con sus cobardes minas. ¡Qué vergüenza!' WHERE `ID`=39104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 피로 목욕을 한 날이 제일 보람차다오.', `MaleText_loc4`='没有比把矮人打得落花流水更痛快的事情了！', `MaleText_loc5`='有什麼是比看到矮人的鮮血染紅地面更爽的嗎?', `MaleText_loc7`='¡El mejor día es el que está lleno de sangre de enanos!' WHERE `ID`=39105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 꽉 묶으시오. 그놈들이 도망치면 재미를 볼 수 없거든.', `MaleText_loc4`='再把它收紧一点。我们可不想让它们溜走，这样会错过许多乐趣。', `MaleText_loc5`='綁緊一點。我們不會希望他們穿過去讓我們錯過娛性節目。', `MaleText_loc7`='Presta atención. No queremos que se escabullan y perdernos la diversión.' WHERE `ID`=39106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 고블린 친구가 뭘 할 수 있는지 지켜봤소. 틀림없이 드워프 놈들은 더러운 기분이 들 거요!', `MaleText_loc4`='我已经见识过了地精朋友的能耐。那些矮人这次可要大吃一惊了！', `MaleText_loc5`='我瞭解我們的哥布林朋友的厲害。這些矮人一定會有個悲慘的驚喜!', `MaleText_loc7`='He visto lo que es capaz de hacer nuestro amigo goblin. ¡A estos enanos les espera una desagradable sorpresa!' WHERE `ID`=39107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론은 온 힘을 다해 싸웠소! 호드를 위하여!', `MaleText_loc4`='库卡隆不可能打得更好了！为了部落！', `MaleText_loc5`='柯爾克隆的勇猛無庸置疑!為了部落!', `MaleText_loc7`='¡Los Kor''kron no podrían luchar mejor! ¡Por la Horda!' WHERE `ID`=39108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산이 폭발할 때 무역왕 갤리윅스가 그대 친구들을 포로로 데려갔지.$B$B그들을 구출해서 이 섬을 떠나려면 얼라이언스를 빨리 처리해야 해.', `MaleText_loc4`='火山爆发的时候，你的朋友全都被贸易大王加里维克斯抓住了。$B$B我们必须尽快解决联盟的人，这样才能救出他们，离开这座岛。', `MaleText_loc5`='你的朋友已經在火山爆發時全被貿易親王加里維克斯抓了起來。$B$B我們必須趕快把聯盟解決了才能將他們救出後離開這個島。', `MaleText_loc7`='El príncipe mercante Gallywix tomó prisioneros a todos tus amigos mientras el volcán entraba en erupción.$b$bVamos a tener que encargarnos de la Alianza muy rápido si queremos rescatarlos y salir de esta isla.' WHERE `ID`=39109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 트롬카. 다시 만나서 반갑구나.', `MaleText_loc4`='你好，$n。很高兴再见到你。', `MaleText_loc5`='你好，$n。很高興再次看到你。', `MaleText_loc7`='Throm-Ka, $n. Me alegro de volver a verte.' WHERE `ID`=39110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제로드 님과 일하는 건 나쁘지 않아요. 가끔 화를 참지 못하고 이성을 잃으시기도 하지만, 돈은 꼬박꼬박 주시고, 높은 곳의 물건에 제 손이 닿지 않을 때는 번쩍 들어주시기도 하거든요.', `MaleText_loc4`='为杰罗德工作并不是那么糟糕。他也许偶尔会发发脾气，但他付的薪水很高。当我不能按进度完成工作的时候，他甚至还会帮我的忙。', `MaleText_loc5`='為傑洛德工作並沒那麼糟。他雖然有時候脾氣不太好，但他給的薪水不錯，而且在我力不從心的時候甚至還會幫我一把。', `MaleText_loc7`='Trabajar para Jerrod no es tan malo. A veces pierde la compostura, pero paga bien y hasta me aúpa cuando no llego a coger algo del carro.' WHERE `ID`=39111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 도와주면 좋겠나?', `MaleText_loc4`='我能为你做些什么？', `MaleText_loc5`='我能為你做什麼?', `MaleText_loc7`='¿Qué puedo hacer por ti?' WHERE `ID`=39112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기대에 부푼 얼굴로 당신을 바라보는 죽음경비병 시머>', `MaleText_loc4`='<亡灵卫兵希米尔专注地看着你。>', `MaleText_loc5`='<亡靈守衛希米爾意有所指地看著你。>', `MaleText_loc7`='<El Guardia de la Muerte Simmer te mira expectante.>' WHERE `ID`=39113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하다! 안 때릴게!', `MaleText_loc4`='很抱歉！我没有恶意！', `MaleText_loc5`='對不起!別傷害我!', `MaleText_loc7`='¡Lo siento! ¡No hacer daño!' WHERE `ID`=39114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야만인도 전쟁에서 이길 수는 있습니다. 하지만 진정한 영웅은 전장에서 승리만을 노리지 않고, 마지막 공격이 끝난 뒤 평화가 유지되도록 힘쓰는 법입니다.', `MaleText_loc4`='任何野蛮人都可能赢得一场战斗。但真正的英雄所关注的并不是战场上的胜利，而是在最后一支羽箭落下之后去维系长久的和平。', `MaleText_loc5`='勇猛的戰士可以贏得戰爭。真正的英雄關注得不只是贏得勝利，而是在戰爭結束後將和平維持下去。', `MaleText_loc7`='Cualquier salvaje puede ganar una guerra. Un verdadero héroe no busca tan solo la victoria en el campo de batalla, sino que su objetivo es también conseguir una paz duradera después de que caiga la última flecha.' WHERE `ID`=39115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평온의 해안 하늘로 돌아가던가 아니면 추방되던가!', `MaleText_loc4`='到静谧湾岸的天空中去，否则将被弹出机舱！', `MaleText_loc5`='快回到寧靜海岸的天空，否則將被彈射出去!', `MaleText_loc7`='¡Vuelve a los cielos de la Costa Tranquila o te desmontarás!' WHERE `ID`=39116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 불모의 땅에서 흘륭한 성과를 이루고 계십니다.$B$B당신과 같은 영웅의 도움으로 우리는 칼림도어를 지키고, 그럼으로써 고향의 평화를 지킬 수 있습니다.', `MaleText_loc4`='你在贫瘠之地立下了令人难以置信的功绩，$n。$B$B有了像你这样的英雄，我们就能守住卡利姆多确保我们的家园能够实现长久的和平。', `MaleText_loc5`='你在貧瘠之地這做的很好，$n。$B$B有了你這樣的英雄的幫忙，我們絕對可以守住卡林多，這樣才能維持我們家園的和平。', `MaleText_loc7`='Estás haciendo un trabajo increíble aquí, en Los Baldíos, $n.$B$BCon la ayuda de héroes como tú, podremos proteger Kalimdor, y así conseguiremos que la paz sea duradera en nuestras patrias.' WHERE `ID`=39117;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장님께서는 얼라이언스를 처리하는 데 도움을 준다면, 우리가 고블린을 구해내고 갤리윅스를 처치할 때 돕겠다고 약속하셨어요.$B$B제게는 꽤 공정한 제안 같아요. 내 친구의 적은 나의 적이다. 맞죠?', `FemaleText_loc4`='酋长会帮助我们保卫我们的族人，对付加里维克斯。只要我们帮助他们对付联盟。$B$B听上去，这是一笔公平的交易。我的朋友的敌人就是我的敌人，对不对？', `FemaleText_loc5`='只要我們答應幫助大酋長對抗聯盟，他承諾會幫助我們救人和對付加里維克斯。$B$B對我來說這聽起來是樁公平對等的買賣。朋友的敵人就是我的敵人，你說是不是?', `FemaleText_loc7`='El Jefe de Guerra nos ha prometido ayuda para rescatar a los nuestros y acabar con Gallywix si le ayudamos con la Alianza.$b$bA mí me parece un buen trato. El enemigo de mi amigo es mi enemigo, ¿no?' WHERE `ID`=39118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새시, 날 하늘로 올려 보내줘!', `MaleText_loc4`='把我送到天空中去，莎希！', `MaleText_loc5`='把我送上天空，賽希!', `MaleText_loc7`='¡Sassy, llévame al cielo!', `FemaleText_loc1`='새시, 날 하늘로 올려 보내줘요!', `FemaleText_loc4`='把我送到天空中去，莎希！', `FemaleText_loc5`='把我送上天空，賽希!', `FemaleText_loc7`='¡Sassy, llévame al cielo!' WHERE `ID`=39119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 제가 뭘 도와드리면 좋겠습니까?', `MaleText_loc4`='$n!我该怎样帮助你，老朋友？', `MaleText_loc5`='$n!我能幫你什麼，老朋友?', `MaleText_loc7`='¡$n! ¿Cómo puedo ayudarte, camarada?' WHERE `ID`=39120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 당신에게만 하는 얘긴데, 실은 여기 계신 장군님이 임무를 수행할 마음이 별로 없으신 듯합니다.$B$B우린 지금 호드를 상대하고 있지 않습니까? 역사에서도 평화는 찾아볼 수 없습니다.$B$B우리는 호드의 전멸을 목표로 해야 한단 말입니다.', `MaleText_loc4`='这话可别对别人说。我很担心这里的将军并不想做他该做的事情。$B$B我们要对付的是部落。历史表明，他们从不会给予我们真正的和平。$B$B我们的目标是……把敌人消灭干净。', `MaleText_loc5`='我只跟你說，我擔心好人將軍沒有勇氣做出他該做的事。$B$B我們面對的是部落。歷史指出和平是永遠不可能的。$B$B我的的目標應該是...將他們消滅。', `MaleText_loc7`='Entre tú y yo, me preocupa que el General no tenga agallas para hacer lo que debe hacerse.$b$bEstamos hablando de la Horda. La historia nos enseña que la paz es imposible.$b$bNuestro objetivo debería ser... la aniquilación.' WHERE `ID`=39121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 같은 늑대인간이 스테이크를 잘 구울 수 있다고는 생각지 못하셨을 겁니다.$B$B제가 워낙 날고기를 즐기다 보니... 쫓기는 동물의 헐떡임과... 동맥에서 얼굴로 뿜어져나오는...$B$B무슨 얘기를 하던 중이었죠? 아, 그렇죠! 저도 길니아스에 있을 땐 나름 미식가였답니다.', `MaleText_loc4`='你也许不会相信，像我这样的狼人竟然能做出美味的肉排。$B$B就因为我喜欢吃生肉……我还没有从飞行的疲惫中恢复过来……我脑袋上的血管还在一蹦一蹦的……$B$B我们在说什么？哦，是了！我在吉尔尼斯可是一位著名的美食家。', `MaleText_loc5`='你大概在想像我這種狼人不知道如何煎出一塊好牛排。$B$B就因為我喜歡吃生肉...因為逃走在喘氣...臉上沾滿了鮮血...$b$b我在說什麼?喔對了!我在吉爾尼斯可算是個美食家呢。', `MaleText_loc7`='A lo mejor te piensas que un huargen como yo no sabría cocinar un buen filete.$b$bSolo porque me gusta la carne cruda... aún jadeando por la persecución... con el flujo arterial salpicándome la cara...$b$b¿De qué estábamos hablando? ¡Ah, sí! Era todo un gourmet en Gilneas.' WHERE `ID`=39122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우라조에서 무슨 일이 일어났는지 말씀해주십시오.', `MaleText_loc4`='告诉我，陶拉祖发生了什么事。', `MaleText_loc5`='告訴我在陶拉祖營地發生了什麼事。', `MaleText_loc7`='Cuéntame qué ha pasado en Taurajo.', `FemaleText_loc1`='타우라조에서 무슨 일이 일어났는지 말씀해주십시오.', `FemaleText_loc4`='告诉我，陶拉祖发生了什么事。', `FemaleText_loc5`='告訴我在陶拉祖營地發生了什麼事。', `FemaleText_loc7`='Cuéntame qué ha pasado en Taurajo.' WHERE `ID`=39123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 호드 마을인 타우라조에 대한 공격 말씀이시죠. 그와 같은 결정을 내리면서 많은 어려움을 겪었습니다.$B$B타우라조는 기본적으로 사냥꾼의 야영지였기에, 실은 손쉬운 목표임을 인정하지 않을 수 없습니다. 하지만 꽤 오랫동안 호드에서 보병을 모집, 장비하고 훈련하는 데 중요한 역할을 해왔죠.$B$B정찰병들이 타우라조에서 가장 위험한 병력이 사냥을 떠났다고 보고했을 때, 빠르게 행동으로 옮기지 않을 수 없었습니다.', `MaleText_loc4`='啊，是的，我们要对部落城镇陶拉祖发动进攻。我一直在努力厘清这一决定可能产生的后果。$B$B陶拉祖大概可以被称为一个“软目标”。它实际上只是一处猎人营地。但多年以来，它也一直是部落征募兵员，装备和训练军队的基地。$B$B我们的斥候报告说，陶拉祖最危险的部队都已经外出狩猎了。所以我们必须迅速行动。', `MaleText_loc5`='啊，對，我們對部落的城鎮陶拉祖發動的攻擊。我對這個決定當初非常的掙扎。$B$B陶拉祖營地基本上是個「軟目標」，它主要是個獵人營地。不過，它多年來還是在徵召、訓練和提供彈藥給部落的軍隊。$B$B當我們的斥候報告說陶拉祖最致命的獵人們外出時，我們迅雷不及掩耳地行動了。', `MaleText_loc7`='Ah, sí, nuestro asalto sobre Taurajo, el pueblo de la Horda. Tuve que considerar las consecuencias de esa decisión.$b$bAdmito que Taurajo era lo que podríamos llamar un "objetivo fácil", principalmente un campamento de cazadores, pero hacía años que se utilizaba para reclutar, equipar y entrenar a la infantería de la Horda.$b$bCuando nuestros exploradores nos informaron de que las unidades más peligrosas de Taurajo se habían ido de caza, tuvimos que actuar rápido.' WHERE `ID`=39124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을을 박살 낸 겁니까?', `MaleText_loc4`='我们洗劫了那座城市？', `MaleText_loc5`='我們洗劫了那個城鎮?', `MaleText_loc7`='¿Hemos saqueado el pueblo?', `FemaleText_loc1`='마을을 박살 낸 겁니까?', `FemaleText_loc4`='我们洗劫了那座城市？', `FemaleText_loc5`='我們洗劫了那個城鎮?', `FemaleText_loc7`='¿Hemos saqueado el pueblo?' WHERE `ID`=39125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<눈썹을 찡그리는 호손>$B$B박살 냈다기보다는, 아무래도 거침없이 공격을 가했다는 게 맞는 말이겠군요. 타우라조를 위험 요소에서 배제한 겁니다. 그곳에서 무기를 압수한 뒤, 대장 시설을 파괴했습니다. 우리 부대는 타우라조를 공격함으로써 어느 정도 여유를 가지는 한편 적의 균형을 무너뜨릴 수 있었습니다.$B$B그렇다고는 해도 저는 부하들에게 공격 병력 사이에 빠져나갈 틈을 두라고 지시했습니다...', `MaleText_loc4`='<霍索恩皱了皱眉。>$B$B我可不喜欢用“洗劫”这个词。但这场攻击实在是完美无缺。我们除掉了陶拉祖，收缴了他们的武器，摧毁了他们的锻造工厂。这次攻击为我们赢得了巨大的喘息空间，并打乱了敌人的阵脚。$B$B不过，在进攻过程中，我特意命令我的部下在阵线中留出一个豁口……', `MaleText_loc5`='<霍桑皺了皺眉頭。>$B$B我會希望不要用「洗劫」兩字，不過是的，那次的攻擊行動的確相當完美。我們將陶拉祖夷為平地，沒收了他們的武器和摧毀了他們的鍛造器具。那次攻擊為我們爭取了喘息的機會也重擊了敵人。$B$B儘管如此，在發動攻擊時，我還是特別吩咐屬下要留出一條活路...', `MaleText_loc7`='<Hawthorne frunce el ceño.>$b$bPreferiría evitar la palabra "saquear", pero sí, el ataque ha tenido un éxito rotundo. Hemos eliminado Taurajo de la ecuación, confiscado sus armas y destruido sus herrerías. El salto ha desequilibrado al enemigo y ha dado un respiro a nuestras tropas.$b$bSin embargo, durante el asalto ordené a mis hombres que abrieran una brecha en nuestras filas...' WHERE `ID`=39126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그랬습니까?', `MaleText_loc4`='为什么你会这样做？', `MaleText_loc5`='為什麼?', `MaleText_loc7`='¿Por qué lo hiciste?', `FemaleText_loc1`='왜 그랬습니까?', `FemaleText_loc4`='为什么你会这样做？', `FemaleText_loc5`='為什麼?', `FemaleText_loc7`='¿Por qué lo hiciste?' WHERE `ID`=39127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우라조에는 민간인이 많았습니다. 그들이 전투로부터 도망칠 기회를 주고 싶었습니다. 실제로 많은 이들이 탈출에 성공했고 북쪽으로 피난을 떠났죠.$B$B얼라이언스 총사령부에도, 제가 기회를 놓쳐버렸다고 주장하는 세력이 있었습니다. 인질로 잡아둬야 했다고 말입니다. 하지만 전 그와 같은 협박 전략에는 일말의 가치도 없다고 봅니다.$B$B잘 들으십시오, $n. 전 이 전쟁이 언젠가는 끝났으면 좋겠습니다. 민간인을 학살하거나 가두는 짓을 일삼는다면 전쟁을 끝낼 수 없습니다.$B$B적군 중에도 저와 같은 생각을 하는 자들이 있기를 간절히 바랍니다.', `MaleText_loc4`='陶拉祖有许多平民。我希望能让他们避过战火。他们之中有许多人逃出来了，流亡到了北方。$B$B但即使是在联盟最高指挥部里，也有人在指责我放任敌人逃走，说我应该把他们全部俘获，当作人质。但我完全看不出来这种可怕的战术对我们有什么益处。$B$B听我说，$n：我希望这场战争能够结束。但如果我们屠杀或者囚禁平民，这张战争就永远不会有结束的可能。$B$B希望在我们的敌人之中也会有人能看清这一点。', `MaleText_loc5`='陶拉祖營地擁有大量的平民。我希望他們可以逃離戰場，而很多人的確逃走了，往北方尋求庇護。$B$B有些人，甚至包括聯盟高層，認為我放走了人就是放走了機會，我應該俘虜他們。但我看不出這種恐怖戰術的意義。$B$B聽我一言，$n:我希望這個戰爭有一天能結束，但如果我們不停止屠殺或俘虜平民，它是不可能會結束的。$B$B我只希望在對面陣營也有人抱持著相同的想法。', `MaleText_loc7`='Taurajo contaba con una considerable población civil. Quería asegurarme de que pudieran huir de la batalla, y muchos lo consiguieron y encontraron refugio en el norte.$b$bAlgunas personas, incluso en el alto mando de la Alianza, piensan que dejé pasar una oportunidad. Que debería haber tomado rehenes. Pero esas tácticas de terror me parecen inútiles.$b$bEscúchame, $n: quiero que esta guerra acabe algún día. Si masacramos o encarcelamos a civiles, no acabará nunca.$b$bSolo rezo para que en el otro bando haya quien piense como yo.' WHERE `ID`=39128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가고 싶은 곳이라도 있나?', `MaleText_loc4`='要到哪里去？', `MaleText_loc5`='要去哪裡嗎?', `MaleText_loc7`='¿Vas a alguna parte?' WHERE `ID`=39129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브릴로 가고 싶습니다.', `MaleText_loc4`='现在我要飞往布瑞尔。', `MaleText_loc5`='我現在要飛去布瑞爾。', `MaleText_loc7`='Tomaré el vuelo a Rémol ahora.', `FemaleText_loc1`='브릴로 가고 싶어요.', `FemaleText_loc4`='现在我要飞往布瑞尔。', `FemaleText_loc5`='我現在要飛去布瑞爾。', `FemaleText_loc7`='Tomaré el vuelo a Rémol ahora.' WHERE `ID`=39130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박쥐를 타고 싶습니다.', `MaleText_loc4`='我要租一只蝙蝠。', `MaleText_loc5`='我想要買一趟蝙蝠之旅。', `MaleText_loc7`='Me gustaría comprar un viaje en murciélago.', `FemaleText_loc1`='박쥐를 타고 싶어요.', `FemaleText_loc4`='我要租一只蝙蝠。', `FemaleText_loc5`='我想要買一趟蝙蝠之旅。', `FemaleText_loc7`='Me gustaría comprar un viaje en murciélago.' WHERE `ID`=39131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 살아있었군! 소식은 들었소?', `MaleText_loc4`='$n!你还活着！你听说了吗？', `MaleText_loc5`='$n!你還活著!你聽到了嗎?', `MaleText_loc7`='¡$n! ¡Estás $gvivo:viva;! ¿Te has enterado?', `FemaleText_loc1`='$n! 살아있었군요! 소식은 들었어요?', `FemaleText_loc4`='$n!你还活着！你听说了吗？', `FemaleText_loc5`='$n!你還活著!你聽到了嗎?', `FemaleText_loc7`='¡$n! ¡Estás $gvivo:viva;! ¿Te has enterado?' WHERE `ID`=39132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 호손 장군님을 죽이고 말았소! 호드 암살자들이 길에서 장군님을 습격한 거요!', `MaleText_loc4`='他们杀了他！霍索恩将军在路上遭到了部落刺客的偷袭。', `MaleText_loc5`='他們把他殺了!霍桑將軍在路上被部落的刺客殺死了。', `MaleText_loc7`='¡Lo han matado! Al general Hawthorne, unos asesinos de la Horda le tendieron una emboscada en la carretera.', `FemaleText_loc1`='저들이 호손 장군님을 죽이고 말았어요! 호드 암살자들이 길에서 장군님을 습격한 거예요!', `FemaleText_loc4`='他们杀了他！霍索恩将军在路上遭到了部落刺客的偷袭。', `FemaleText_loc5`='他們把他殺了!霍桑將軍在路上被部落的刺客殺死了。', `FemaleText_loc7`='¡Lo han matado! Al general Hawthorne, unos asesinos de la Horda le tendieron una emboscada en la carretera.' WHERE `ID`=39133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 시체가 나무 위에 매달려 있었소. 짐승 같은 놈들... 더러운 짐승 같으니!', `MaleText_loc4`='我们找到了他的尸体。那些野兽……那些肮脏的怪物！', `MaleText_loc5`='他的屍體被發現吊在一棵樹上。那些禽獸...那些下流的禽獸!', `MaleText_loc7`='Encontraron su cadáver colgado de un árbol. Animales... ¡Animales despreciables!', `FemaleText_loc1`='그분의 시체가 나무 위에 매달려 있었어요. 짐승 같은 놈들... 더러운 짐승 같으니!', `FemaleText_loc4`='我们找到了他的尸体。那些野兽……那些肮脏的怪物！', `FemaleText_loc5`='他的屍體被發現吊在一棵樹上。那些禽獸...那些下流的禽獸!', `FemaleText_loc7`='Encontraron su cadáver colgado de un árbol. Animales... ¡Animales despreciables!' WHERE `ID`=39134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에서, 우리는 초토화 정책 외에 그 어떤 방법으로도 호드라는 짐승을 박멸할 수 없음을 깨달았습니다. 자비란 없습니다!', `MaleText_loc4`='贫瘠之地告诉我们，只有焦土政策才能彻底清除那些部落怪物。对敌人不要有半点同情！', `MaleText_loc5`='我們在貧瘠之地學到的教訓是，除了放大火把這裡徹底燒光之外，沒有任何東西能擊潰這些部落的禽獸。絕對不能對他們手下留情!', `MaleText_loc7`='La lección que hemos aprendido en Los Baldíos es que solo la tierra arrasada sirve para echar a estos animales de la Horda. ¡Sin cuartel!' WHERE `ID`=39135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 호손 장군님이 살아계셔서 직접 복수를 계획했다면, 의심할 여지도 없이 대규모의 보복 학살을 명하셨을 겁니다.', `MaleText_loc4`='如果霍索恩将军还活着，一定会毫不留情地将敌人消灭干净。', `MaleText_loc5`='要是他還活著能為他自己報仇的話，霍桑將軍絕對會同意我們進行反擊，做出毀滅性的屠殺。', `MaleText_loc7`='Si estuviera vivo para vengarse, sin duda el general Hawthorne habría ordenado una masacre a gran escala como represalia.' WHERE `ID`=39136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 말이 맞네, 트라스크.', `MaleText_loc4`='你是对的，塔斯克。', `MaleText_loc5`='你說得相當對，特拉斯克。', `MaleText_loc7`='Tienes razón, Trask.' WHERE `ID`=39137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지!', `FemaleText_loc4`='父亲！', `FemaleText_loc5`='父親!', `FemaleText_loc7`='¡Padre!' WHERE `ID`=39138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴리안... 지금 네 모습은... 다시 만나게 되어 기쁘구나.', `MaleText_loc4`='莉莉安……你……真高兴能看到你没事。', `MaleText_loc5`='莉莉安...你...看到你好好的我很高興。', `MaleText_loc7`='Lilian... estás... Me alegro de ver que estás bien.' WHERE `ID`=39139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='닥쳐요.', `FemaleText_loc4`='闭嘴。', `FemaleText_loc5`='住嘴。', `FemaleText_loc7`='Cállate.' WHERE `ID`=39140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 절 살인마로 키우셨지요. 지금 제 실력이 어떤가요, 아빠?', `FemaleText_loc4`='你将我培育成一个杀手。我做得如何，爸爸？', `FemaleText_loc5`='你把我培養成了一個殺手。我做的如何，父親?', `FemaleText_loc7`='¡Me educaste para que fuera una asesina! ¿Qué tal lo hago, papi?' WHERE `ID`=39141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 난...', `MaleText_loc4`='我，啊……', `MaleText_loc5`='我，啊...', `MaleText_loc7`='Yo, eh...' WHERE `ID`=39142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만요... 이제 기억이 나네요. 제게 오직 언데드를 죽이는 방법 만을 가르치셨잖아요. 그 말은 제가 스스로 목숨이라도 끊으란 말씀이신가요, 아빠?', `FemaleText_loc4`='但，等一等……我现在记起来了。你教过我只能杀亡灵。那么你想让我杀掉我自己吗，爸爸？', `FemaleText_loc5`='不過等等...我現在記得了。你教我只要殺不死族，那你是希望我殺了自己嗎，爸爸?', `FemaleText_loc7`='Espera... Ahora lo recuerdo. Me enseñaste a matar solo a los no-muertos. ¿Así que quieres que me suicide, papi?' WHERE `ID`=39143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴리안, 난...', `MaleText_loc4`='莉莉安，我……', `MaleText_loc5`='莉莉安，我...', `MaleText_loc7`='Lilian, yo...' WHERE `ID`=39144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데 다시 한번 생각해보니, 제가 스스로 목숨을 끊을 이유가 없더군요... 대신 당신이 죽어도 되니까!', `FemaleText_loc4`='那么，我为什么要把自己杀死……我可以杀死你！', `FemaleText_loc5`='所以，為什麼要殺了我自己...當我可以殺了你的時候!', `FemaleText_loc7`='Pero, por qué suicidarme... ¡Si puedo matarte a TI en mi lugar!' WHERE `ID`=39145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러 가지로 고마웠어요... 아버지.', `FemaleText_loc4`='谢谢你为我做的一切……爸爸。', `FemaleText_loc5`='謝謝這一切...父親。', `FemaleText_loc7`='Gracias por todo... padre.' WHERE `ID`=39146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서판을 바로 넘기면 고통 없이 빠르게 처리해주마.', `MaleText_loc4`='交出石板，我会让你死个痛快。', `MaleText_loc5`='把石板交出來，那我可以讓你死得痛快點。', `MaleText_loc7`='Entrégame las tablillas y te permitiré tener una muerte rápida.', `FemaleText_loc1`='서판을 바로 넘기면 고통 없이 빠르게 처리해주마.', `FemaleText_loc4`='交出石板，我会让你死个痛快。', `FemaleText_loc5`='把石板交出來，那我可以讓你死得痛快點。', `FemaleText_loc7`='Entrégame las tablillas y te permitiré tener una muerte rápida.' WHERE `ID`=39147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아, 드워프. 어디 멋대로 해 봐. 널 처치하고 서판을 가져갈 테니.', `MaleText_loc4`='很好，矮人。尽管挣扎吧。我先把你干掉，然后再拿走这些石板。', `MaleText_loc5`='很好，矮人。那就這樣子吧。我會殺了你，然後再拿走石板。', `MaleText_loc7`='Muy bien, enano. Lo haremos a tu manera. Te mataré y luego me quedaré con las tablillas.', `FemaleText_loc1`='아주 좋아, 드워프. 어디 멋대로 해 봐. 널 처치하고 서판을 가져갈 테니.', `FemaleText_loc4`='很好，矮人。尽管挣扎吧。我先把你干掉，然后再拿走这些石板。', `FemaleText_loc5`='很好，矮人。那就這樣子吧。我會殺了你，然後再拿走石板。', `FemaleText_loc7`='Muy bien, enano. Lo haremos a tu manera. Te mataré y luego me quedaré con las tablillas.' WHERE `ID`=39148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 뭐 도와줄 거라도 있는가?', `FemaleText_loc4`='我能帮助你吗？', `FemaleText_loc5`='我可以幫你什麼嗎?', `FemaleText_loc7`='¿Puedo ayudarte en algo?' WHERE `ID`=39149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작업을 시작할 준비 됐는가?', `FemaleText_loc4`='是否做好开始的准备了？', `FemaleText_loc5`='你準備好開始進行了嗎?', `FemaleText_loc7`='¿Estás $glisto:lista; para comenzar el proceso?' WHERE `ID`=39150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 이곳에서 뒤틀린 대지를 치유하기 위해 온 힘을 다하고 있어요. 그렇지 않아도 힘든 상황에, 밤마다 습격을 당하기 시작한 거죠.', `MaleText_loc4`='我们在这里竭尽全力医治残破的大地。就在这种极为艰难的情况下，我们还在夜晚遭到了袭击。', `MaleText_loc5`='我們在這盡一切的力量治療著崩壞的大地。這原本就是件很艱鉅的事，更別說我們現在晚上還會被襲擊。', `MaleText_loc7`='Hemos hecho todo lo posible para sanar la tierra herida. Resultó muy complicado, sobre todo porque nos atacaron por la noche.' WHERE `ID`=39151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy listo.', `FemaleText_loc1`='준비 됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy lista.' WHERE `ID`=39152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 날 따라오게.', `FemaleText_loc4`='很好，跟着我。', `FemaleText_loc5`='好吧，跟隨我。', `FemaleText_loc7`='De acuerdo. Sígueme.' WHERE `ID`=39153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 시작할 시간이군.', `FemaleText_loc4`='现在该是开始的时候了。', `FemaleText_loc5`='我們現在可以開始了。', `FemaleText_loc7`='Es hora de comenzar.' WHERE `ID`=39154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데블린 아가만드여! 내 목소리를 들어라!', `FemaleText_loc4`='代弗林·阿加曼德！听我说！', `FemaleText_loc5`='戴弗林·阿加曼德!傾聽我的聲音!', `FemaleText_loc7`='¡Devlin Agamand! ¡Escucha mi voz!' WHERE `ID`=39155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 어린 시절을 보냈던 바로 이곳에, 너의 유해가 모두 모였도다!', `FemaleText_loc4`='你在凡间的遗骸已经被收集完整，被放置在这个你渡过童年光阴的地方！', `FemaleText_loc5`='在你出生長大的地方!就在這裡，你的凡人血肉殘骸已經被回收了!', `FemaleText_loc7`='¡Tus restos mortales están reunidos, aquí, en el lugar en el que pasaste tu infancia!' WHERE `ID`=39156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕의 뜻에 저항해라, 데블린! 우리에게 와라!', `FemaleText_loc4`='代弗林，抵抗巫妖王的意志！到我们这里来吧！', `FemaleText_loc5`='抗拒巫妖王的意志，戴弗林!到我們這裡來!', `FemaleText_loc7`='¡Resiste la voluntad del Rey Exánime, Devlin! ¡Vuelve con nosotros!' WHERE `ID`=39157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 초소로 돌아가야겠군. 뭐든 필요한 게 있으면 지하로 와서 나를 찾게.', `FemaleText_loc4`='我最好回到我的岗位上去。如果有需要，你可以在楼下找到我。', `FemaleText_loc5`='我最好回到我的工作崗位。如果你需要什麼可在樓下找到我。', `FemaleText_loc7`='Será mejor que vuelva a mi puesto. Si necesitas cualquier cosa, estaré en el piso de abajo.' WHERE `ID`=39158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 내가 좀 바쁘네, $c|1이여;여;... 여유가 있을 때 날 찾아오게.', `FemaleText_loc4`='$c，现在我有一点忙……等我有空的时候再来找我吧。', `FemaleText_loc5`='我現在有點忙，$c...等我閒一點的時候再過來。', `FemaleText_loc7`='Estoy un poco ocupada, $c... Vuelve cuando tenga menos preocupaciones.' WHERE `ID`=39159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디지?', `MaleText_loc4`='这里出了什么事？', `MaleText_loc5`='這裡發生了什麼事?', `MaleText_loc7`='¿Qué está pasando aquí?' WHERE `ID`=39160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 여긴 지금... 집이잖아?', `MaleText_loc4`='等等，我是……在家里？', `MaleText_loc5`='等等，我現在是...在家裡?', `MaleText_loc7`='Espera, estoy... ¿en casa?' WHERE `ID`=39161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들... 여기서 뭣들 하는 겁니까? 왜 우리 집에 있는 거죠?', `MaleText_loc4`='你们……你们在这里干什么？为什么你们会在我的房子里？', `MaleText_loc5`='你們...你們在這做什麼?為什麼會在我家裡?', `MaleText_loc7`='Ustedes... ¿Qué están haciendo aquí? ¿Por qué están en mi casa?' WHERE `ID`=39162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니.. 아버지... 투르만... 다 어디있나요? 저 좀 도와주세요!', `MaleText_loc4`='妈妈……爸爸……萨尔曼……你们在哪里？来帮帮我！', `MaleText_loc5`='母親...父親...薩爾曼...你們在哪裡?來救救我!', `MaleText_loc7`='Madre... Padre... Thurman... ¿Dónde estáis? ¡Ayudadme!' WHERE `ID`=39163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야... 기억났어. 내 가족은 모두 죽었지. 나도 죽었고.', `MaleText_loc4`='不……我想起来了。我的家人都死了。我也死了。', `MaleText_loc5`='不...我記得。我的家人都死了，而且我也死了。', `MaleText_loc7`='No... Ya recuerdo. Mi familia está muerta. Como yo.' WHERE `ID`=39164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 내 영혼은... 내 영혼은 스컬지의 것이다!', `MaleText_loc4`='我的灵魂……我的灵魂属于天灾！', `MaleText_loc5`='我的靈魂...我的靈魂是屬於天譴軍團的!', `MaleText_loc7`='Y mi alma... ¡mi alma pertenece a la Plaga!' WHERE `ID`=39165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가련한 그 목숨을 거둬주마! 죽어라!', `MaleText_loc4`='死吧，倒霉鬼！', `MaleText_loc5`='死吧，垃圾們!', `MaleText_loc7`='¡MORID, DESGRACIADOS!' WHERE `ID`=39166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥경기장으로 들어가라고, $n! 한 사람이 쓰러질 때까지 못 나오는 거야! 이제 경기를 시작하자고!', `MaleText_loc4`='走进雷霆机场吧，$n！谁都不能退出，直到一方倒下为止。演出开始！', `MaleText_loc5`='進去雷霆競技場裡面，$n!沒人死之前不准任何人出來。讓表演開始吧!', `MaleText_loc7`='¡Al Truenódromo, $n! No se puede salir hasta que alguien muerda el polvo. ¡Que comience el espectáculo!' WHERE `ID`=39167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n 님. 이제 마지막 조립 작업을 시작할 수 있겠어요...', `FemaleText_loc4`='谢谢你，$n！现在我可以开始最终的装配了……', `FemaleText_loc5`='謝謝你，$n!現在我可以開始我最後的組裝工程...', `FemaleText_loc7`='¡Gracias, $n! Ahora puedo comenzar mi ensamblaje final...' WHERE `ID`=39168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요... 구조? 확인. 동력? 확인. 위험 요소? 중복 확인 완료. 제가 만든 회심의 역작을 작동시켜 보죠!', `FemaleText_loc4`='好了……结构？确认。能量？确认。危险？双重确认。让我们发射我的杰作吧！', `FemaleText_loc5`='好...結構?打勾。能源?打勾。危險性?打兩個勾。好，讓我們啟動我的偉大傑作!', `FemaleText_loc7`='Venga... ¿Estructura? Sí. ¿Energía? Sí. ¿Peligro? Sí y sí. ¡Vamos a activar mi obra maestra!' WHERE `ID`=39169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 장비가 완전히 얻어맞고 있군요!', `FemaleText_loc4`='我们的装备在这里受到了真正的打击！', `FemaleText_loc5`='我們的器具在這受到了嚴重的打擊!', `FemaleText_loc7`='¡Están machacando nuestro equipo ahí fuera!' WHERE `ID`=39170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 네. 하지만 좀... 작은 것 같지 않아요?', `MaleText_loc4`='嗯……确实。不过这只是很少一点……唔……非常少，对不对？', `MaleText_loc5`='嗯...對。但有一點點，對吧?', `MaleText_loc7`='Mmmm... Bueno. Pero es un poquitín... eh.. pequeño, ¿no?' WHERE `ID`=39171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시머는 고르도 근성은 있지만 두뇌는 없다고 한다. 그게 무슨 뜻이지?', `MaleText_loc4`='希米尔说葛尔多有肚子，却没有脑子。这是什么意思？', `MaleText_loc5`='希米爾說葛爾多有勇氣，但是沒腦子。他什麼意思?', `MaleText_loc7`='Simmer dice que Gordo tiene agallas pero le falta cerebro. ¿Qué quiere decir?' WHERE `ID`=39172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르도는 꽃 뽑는 거 좋아한다. 꽃 뽑는 거 죽이는 거랑 비슷하다.', `MaleText_loc4`='葛尔多喜欢摘花。摘花就像是打仗。', `MaleText_loc5`='葛爾多喜歡摘花。摘花感覺有點像殺人。', `MaleText_loc7`='A Gordo le gusta recoger flores. Recoger flores es un poco como matar.' WHERE `ID`=39173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 쌀쌀하다.', `MaleText_loc4`='这里通风很不错。', `MaleText_loc5`='這裡空氣不錯。', `MaleText_loc7`='Aquí hay corriente.' WHERE `ID`=39174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요한은 고르도가 배를 수리 해야 하니 재봉사가 필요하다 했다.', `MaleText_loc4`='乔汉说，葛尔多需要个裁缝来修整一下葛尔多的肚子。', `MaleText_loc5`='喬漢說葛爾多需要一位裁縫來修好葛爾多的肚子。', `MaleText_loc7`='Johaan dice que Gordo necesita un sastre para arreglar la barriga de Gordo.' WHERE `ID`=39175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르도, 제 장비를 고쳐줄 수 있습니까?', `MaleText_loc4`='葛尔多，你能修理我的装备吗？', `MaleText_loc5`='葛爾多，你認為你可以修好我的裝備嗎?', `MaleText_loc7`='Gordo, ¿podrías reparar mi equipo?', `FemaleText_loc1`='고르도, 제 장비를 고쳐줄 수 있나요?', `FemaleText_loc4`='葛尔多，你能修理我的装备吗？', `FemaleText_loc5`='葛爾多，你認為你可以修好我的裝備嗎?', `FemaleText_loc7`='Gordo, ¿podrías reparar mi equipo?' WHERE `ID`=39176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말도 안 되는 소리! 전쟁의 미래는 축소화에 달렸어요!', `FemaleText_loc4`='胡说！微型化才是战争的未来。', `FemaleText_loc5`='胡說!小型化會是未來的戰爭趨勢。', `FemaleText_loc7`='¡Tonterías! La miniaturización es el futuro de la guerra.' WHERE `ID`=39177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페로몬 냄새를 맡아 곤충집 안으로 들어가야 합니다!', `MaleText_loc4`='通过嗅觉寻找信息素，这样才能找到进入虫巢的路径！', `MaleText_loc5`='嗅嗅費洛蒙來找到進入巢穴的路!', `MaleText_loc7`='¡Olisquea feromonas para encontrar el camino a la colmena!', `FemaleText_loc1`='페로몬 냄새를 맡아 곤충집 안으로 들어가야 합니다!', `FemaleText_loc4`='通过嗅觉寻找信息素，这样才能找到进入虫巢的路径！', `FemaleText_loc5`='嗅嗅費洛蒙來找到進入巢穴的路!', `FemaleText_loc7`='¡Olisquea feromonas para encontrar el camino a la colmena!' WHERE `ID`=39178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소형 틀에 맞추느라 변속 장치를 거꾸로 조립한 사실은 인정하죠.', `FemaleText_loc4`='我应该说一下。我翻转了变速箱，以适应变小的整体外形。', `FemaleText_loc5`='我應該說一下，我準備了工具箱來應對更小的結構因子。', `FemaleText_loc7`='Debería señalar que he invertido la caja de cambios para adaptarla al tamaño menor.' WHERE `ID`=39179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 중립을 지키는 유명한 스팀휘들 무역회사를 대표해 이곳에 머무는 동안 즐겁게 지냈으면 좋겠군.$B$B기억하라고, 가젯잔은 누구든 환영이야! 물론 해적만 빼고 말이야.', `MaleText_loc4`='我代表杰出的，并依旧保持中立的热砂集团向你表示问候，并衷心希望你能在这里渡过一段愉快的时光。$B$B请记住，加基森欢迎所有人！只有海盗除外。', `MaleText_loc5`='代表著有名和中立的熱砂企業，我希望你能擁有一個愉快的經驗。$B$B記住，加基森歡迎所有的人，除了海盜。', `MaleText_loc7`='En nombre del ilustre y todavía neutral Cártel Bonvapor, te deseo que disfrutes de tu estancia.$b$b¡Recuerda, todo el mundo es bienvenido en Gadgetzan! Todo el mundo menos los piratas.' WHERE `ID`=39180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 돌아와서 반갑군, 친구! 내 첫 번째 노겐포저의 물약을 만들 수 있도록 도와준 뒤로 거의 몇 년만인 것 같군.$B$B이제 나는 도시 전체를 운영하고 있지! 그 물약은 아직도 날개돋친 듯이 팔리고 있고 말이야.', `MaleText_loc4`='欢迎回来，朋友！你帮助我配制出第一副诺格弗格药剂到现在仿佛已经有好几年的时间了。$B$B现在我掌管着整座城市！而且那些药剂依旧大受欢迎。', `MaleText_loc5`='歡迎回來，朋友!感覺在你幫我做出第一瓶諾格弗格藥劑之後已經過了好幾年了。$B$B我現在已經在管理整個城市了!而那些藥劑還是照樣被瘋狂搶購。', `MaleText_loc7`='¡$gBienvenido:Bienvenida; de nuevo, $gamigo:amiga;! Parece que hayan pasado años desde que me ayudaste a crear mi primer elixir de Tragonublo.$b$b¡Ahora controlo toda la ciudad! Se sigue vendiendo como rosquillas.' WHERE `ID`=39181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓰러진 자들의 피가 정의를 갈구하며 울부짖는군요.', `FemaleText_loc4`='死者的鲜血依旧在呼唤着公正的到来。', `FemaleText_loc5`='死者的鮮血哭喊著正義。', `FemaleText_loc7`='La sangre de los caídos clama justicia.' WHERE `ID`=39182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송하지만 얌전하신 신사 숙녀 여러분께서는 자리를 비워 주시기 바랍니다... 진정한 사나이와 여장부만이 앞으로 펼쳐질 피비린내나는 광경을 참아낼 수 있을 테니까요! 첫 번째 상대를 소개합니다. 사막유랑단의 전사이자 카자콜라의 실권자인... 자이노무스!', `MaleText_loc4`='在场的每一位绅士和小姐现在都可以离开了……因为只有真正的男女勇者才能面对这即将出现在你们眼前的血腥场面！让我们欢迎第一位斗士——废土战士——卡亚可乐教派的伟大象征……巨又霸！', `MaleText_loc5`='現場的先生和女士們該離開此地了...只有真正的男人和女人才有辦法目睹即將呈現出的偉大一幕!介紹第一位戰士，廢土的勇士，卡加可樂的真主...大巨人!', `MaleText_loc7`='Las damas y caballeros que queden deberían IRSE... ¡porque solo los HOMBRES Y MUJERES DE VERDAD serán capaces de soportar el baño de sangre que está a punto de desatarse! Os presento al primer luchador, el guerrero Vagayermos, la Pistola de Kaja''Cola... ¡EL ENORMUS!' WHERE `ID`=39183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이 될 생각은 하지 마십시오. 그냥 가시죠.', `MaleText_loc4`='别作英雄了。走吧。', `MaleText_loc5`='別想當個英雄。趕快退下。', `MaleText_loc7`='No te hagas el héroe. Vete.' WHERE `ID`=39184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 이럴 수가... 최전방 전초기지가 없어졌잖아!', `MaleText_loc4`='不……这不可能。我们的前哨站被彻底摧毁了！', `MaleText_loc5`='不...不可能。我們的前哨站被摧毀了!', `MaleText_loc7`='No... No puede ser. ¡Nuestro puesto de avanzada ha sido aniquilado!' WHERE `ID`=39185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦은 것인가...? 데스윙의 존재가 느껴진다!', `MaleText_loc4`='是否已经太晚了？我感觉到死亡之翼就在附近！', `MaleText_loc5`='太遲了嗎?我感覺到死亡之翼在附近!', `MaleText_loc7`='¿Será tarde? ¡Siento cerca la presencia de Alamuerte!' WHERE `ID`=39186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지체할 시간이 없습니다. 승전의 요새를 완성하고 병력을 강화하지 않는 한, 이 대륙에서 영원히 정착하리라는 희망은 버려야 합니다.', `MaleText_loc4`='绝不能再耽搁了。必须完成凯旋壁垒的建造和布防，否则我们将没有可能在这片大陆上建立永久定居点。', `MaleText_loc5`='我們無法接受任何延誤。凱旋堡壘必須完工和被強化，不然任何我們想扎根在這個地區的希望都將破滅。', `MaleText_loc7`='No podemos permitirnos el más mínimo retraso. Fuerte Triunfo debe completarse y reforzarse, o perderemos toda esperanza de establecer un asentamiento permanente en este continente.' WHERE `ID`=39187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 용병들과 함께 승전의 요새 방어 임무에 고용되었을 땐, 호드와 싸우게 되리라 예상했지.$B$B하지만 온갖 적들이 기습해 왔네! 고블린 폭파병과 땅속을 파고드는 벌레, 전기를 내뿜는 도마뱀까지...', `MaleText_loc4`='当我和我的蛮锤佣兵受雇守卫凯旋壁垒的时候，我以为我们的敌人将是部落。$B$B但现在我们却陷入了无数敌人的围困之中！爆炸的地精，挖洞的虫子，放电的蜥蜴……', `MaleText_loc5`='當我和我的蠻錘傭兵們被雇用保護凱旋堡壘時，我以為是要跟部落戰鬥。$B$B但我們的對手什麼人都有!自爆的哥布林，地底的蟲子，放電的蜥蝪...', `MaleText_loc7`='Cuando nos contrataron a mí y a mis mercenarios Martillo Salvaje para proteger Fuerte Triunfo, supuse que lucharíamos contra la Horda.$b$b¡Pero nos atacan por todas partes! Goblins explosivos, bichos enterrados, lagartos eléctricos...' WHERE `ID`=39188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주가 나타났군! 다른 이에게 알려야 한다. 서두르자!', `MaleText_loc4`='炎魔之王来了！我们必须赶快把这件事告诉其他人。抓紧时间！', `MaleText_loc5`='火領主來了!我們必須通知其他人。咱們快一點!', `MaleText_loc7`='¡El Señor del Fuego se ha levantado! Avisemos a los demás. ¡Pronto!' WHERE `ID`=39189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투의 흉터는 위험한 곳이군요. 제아무리 튼튼한 장비도 증기 전차가 대지에 휩쓸리는 걸 막아낼 도리는 없으니까요.', `FemaleText_loc4`='战斗之痕是一个危险的地方。当大地把一辆蒸汽坦克吞下去的时候，就算是全世界最好的护甲也保护不了它。', `FemaleText_loc5`='戰痕是個恐怖的地方。蒸汽坦克那麼厚的裝甲也無法避免被大地吞噬。', `FemaleText_loc7`='La Marca de Guerra es un lugar peligroso. Ni toda la armadura del mundo puede salvar a un tanque de vapor cuando se lo traga la tierra.' WHERE `ID`=39190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 발명품은 시대를 앞서고 있어요, $n 님.$B$B이 설계도를 보세요! 미래의 기술을 망라하고 있잖아요.', `FemaleText_loc4`='我们要创造的是超越这个时代的东西，$n。$B$B看看这些蓝图！这就是世界的未来。', `FemaleText_loc5`='我正在做的完全不是現在的科技可達成的，$n。$B$B看看這些藍圖!這就像是在體驗未來一樣。', `FemaleText_loc7`='Lo que estoy preparando se adelanta a nuestro tiempo, $n.$b$b¡Mira estos planos! Es como tocar el futuro.' WHERE `ID`=39191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론, 해결해야 할 문제는 있지만요. 초소형 전차는 정말 경이로운 기술이라고요.$B$B만드는 데 필요한 재료는 일반 공성 전차의 4분의 1에 불과하고, 누구든지 대량 생산할 수 있어요! ...손이 아무리 작아도 문제없어요!', `FemaleText_loc4`='当然，这里面还有不少的错误要解决。但微型坦克绝对是工程学上的一大奇迹。$B$B它只需要攻城坦克四分之一的制作材料，而且能够由任何人进行大规模生产！……呃，只要你有一双精巧的小手！', `FemaleText_loc5`='沒錯，是還有錯誤必須要修正。但微型燃料箱是工程學裡的奇蹟。$B$B他只使用了攻城機具四分之一的材料，而且可以被任何擁有...擁有小手的人大量製造!', `FemaleText_loc7`='Tiene algunos problemillas que hay que corregir, claro. Pero el microtanque es una maravilla de la ingeniería.$b$bUtiliza una cuarta parte de los materiales de una máquina de asedio de tamaño normal y lo puede producir en masa cualquiera... ¡Cualquiera que tenga unas manos muy pequeñas!' WHERE `ID`=39192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌지워터 무역회사는 해가 지기 전까지만 영업해요. 잘 알아두세요.', `FemaleText_loc4`='记住我的话，锈水财阀终将在这里稳稳地扎下根来。', `FemaleText_loc5`='污水企業聯合在今天結束前會到這做生意，我很確定。', `FemaleText_loc7`='El Cártel Pantoque empezará a hacer negocios aquí antes de que se acabe el día. Recuerda mis palabras.' WHERE `ID`=39193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<텅 빈 눈으로 시체를 바라보는 클라리스>$B$B소식을 듣자마자 테라모어에서 달려왔어요.$B$B존과 저는 항상, 충돌이 가라앉으면 함께 정착하자고 얘기했었죠.$B$B싸움은 앞으로도 영원히 끝나지 않을 것 같아요, 그렇죠?', `FemaleText_loc4`='<克拉莉斯看着这具尸体，目光显得苍白而空洞。>$B$B我一得到消息，就从塞拉摩岛马不停蹄地赶到这里。$B$B约翰和我一直在讨论，等战争结束以后就定居下来。$B$B我觉得这场战争永远也不会结束，你觉得呢？', `FemaleText_loc5`='<克拉莉斯的目光越過了屍體，眼神空洞。>$B$B我一聽到消息就趕緊從塞拉摩趕到了這裡。$B$B約翰和我常常會說當衝突結束後要如何安定下來。$B$B我覺得這衝突永遠不會消失，你說呢?', `FemaleText_loc7`='<Clarice observa el cuerpo, con la mirada ausente.>$b$bVine cabalgando desde Theramore en cuanto llegaron las noticias.$b$bJohn y yo siempre hablábamos de sentar la cabeza cuando amainara el conflicto.$b$bYo no creo que la guerra vaya a parar nunca. ¿Y tú?' WHERE `ID`=39194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 상대는 줄파락 무덤의 깊은 곳에서 왔습니다! 저주받은 피를 마음껏 마시고 죽음에서 수도 없이 부활한, 격노와 포악함 밖에 모르는 존재! 인정사정없는 분노의 소유자... 주몽가!', `MaleText_loc4`='我们下一位斗士来自祖尔法拉克最深的墓穴之中！饱食诅咒之血，无数次死而复生，他现在只知道狂怒与暴力！鼓起勇气面对……祖蒙加盲目的怒火吧！', `MaleText_loc5`='我們的下一位戰士是從祖爾法拉克最深處的墳墓中所找到的!充滿了詛咒之血，從死亡中站起了無數次，現在在他腦中的只有狂怒和暴力!讓我們提起膽子，面對兇臨天下的...祖孟迦!', `MaleText_loc7`='¡A nuestro siguiente luchador lo encontramos en las tumbas más profundas de Zul''Farrak! Atiborrado de sangre maldita, rescatado de la muerte un millón de veces, ¡ya solo conoce furia y violencia! ¡Atrévete a enfrentarte a la ira descontrolada de... ZUMONGA!' WHERE `ID`=39195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이노무스가 졌습니다! $n|1은;는; 아직도 힘이 넘쳐 보이는군요!', `MaleText_loc4`='巨又霸倒下了！$n看来还能应付更多！', `MaleText_loc5`='大巨人倒下了!$n看起來似乎已經準備好面對下位對手!', `MaleText_loc7`='¡El Enormus ha caído! ¡Parece que $n está $glisto:lista; para más!' WHERE `ID`=39196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주몽가... 다 없애버린다...', `MaleText_loc4`='祖蒙加……杀……', `MaleText_loc5`='祖孟迦...殺...', `MaleText_loc7`='ZUMONGA... MATAR...' WHERE `ID`=39197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨 쉴 수 있습니다!', `MaleText_loc4`='我能呼吸了！', `MaleText_loc5`='我能呼吸!', `MaleText_loc7`='¡Puedo respirar!' WHERE `ID`=39198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 날짜가 어떻게 되죠?', `MaleText_loc4`='今天是哪一天？', `MaleText_loc5`='哪一天?', `MaleText_loc7`='¿Qué día es?' WHERE `ID`=39199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 저 벌레들이 내 시계를 가져갔습니다!', `MaleText_loc4`='嗨！那些虫子把我的表抢走了！', `MaleText_loc5`='喂!那些蟲子拿走了我的錶!', `MaleText_loc7`='¡Oye! ¡Esos bichos se han llevado mi reloj!' WHERE `ID`=39200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 감사합니다!', `MaleText_loc4`='非常感谢，朋友！', `MaleText_loc5`='謝啦，老兄!', `MaleText_loc7`='¡Montones de gracias, colega!' WHERE `ID`=39201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 살았습니다!', `MaleText_loc4`='我还活着！', `MaleText_loc5`='我還活著!', `MaleText_loc7`='¡Estoy vivo!' WHERE `ID`=39202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 할, $n! 길을 잘못든 드워프와 노움을 처치하는 데 힘을 보태러 왔나?', `MaleText_loc4`='萨尔万岁，$n！你是要帮我们消灭那些可恶的矮人和侏儒吗？', `MaleText_loc5`='偉大的索爾，$n!來這幫忙殺死幾隻迷路的矮人和地精嗎?', `MaleText_loc7`='¡Larga vida a Thrall, $n! ¿Has venido para matar unos cuantos enanos y gnomos descarriados?' WHERE `ID`=39203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바스티아, 가자!', `MaleText_loc4`='巴斯蒂亚，我们上吧！', `MaleText_loc5`='巴斯堤亞，我們上路吧!', `MaleText_loc7`='¡Vamos, Bastia!', `FemaleText_loc1`='바스티아, 가자!', `FemaleText_loc4`='巴斯蒂亚，我们上吧！', `FemaleText_loc5`='巴斯堤亞，我們上路吧!', `FemaleText_loc7`='¡Vamos, Bastia!' WHERE `ID`=39204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 섬에서 유일하게 남은 멋진 곳이 여기예요... 화산 바로 옆이잖아요!', `FemaleText_loc4`='也许这是岛上唯一凉快的地方了……虽然它就在火山的旁边！', `FemaleText_loc5`='這可能是這島上最後一個涼爽的地方了...位於火山的正隔壁!', `FemaleText_loc7`='Este podría ser el único sitio chulo que queda en la isla... ¡justo al lado del volcán!' WHERE `ID`=39205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐. 거기, $n. 오고 있어?', `MaleText_loc4`='嗨，$n。你要进去吗？', `MaleText_loc5`='嗨，$n。你要進去嗎?', `MaleText_loc7`='Hola, $n. ¿Vas a entrar?' WHERE `ID`=39206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 내가 여기에서 나갈 수 있게 피즈와 함께 도와주겠다고? 그 녀석은 또 나쁜 일을 꾸미는 중이야!', `MaleText_loc4`='$n！能帮帮我摆脱菲兹吗？他又要发脾气了！', `MaleText_loc5`='$n!你可以幫我對付費嘶嗎?他又在打壞主意了!', `MaleText_loc7`='¡$n! ¿Me puedes ayudar con Fizz? ¡Ya vuelve a estar tramando algo!' WHERE `ID`=39207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에볼 핑거스는 대가를 치를 거야! 멋진 이익을 남길 테니. $n, 도와줘!', `MaleText_loc4`='艾沃·邪指一定要为此付出代价！为了我的利润，$n，请帮帮我！', `MaleText_loc5`='伊柏·芬格要付出代價!為了利潤，$n，幫幫我!', `MaleText_loc7`='¡Evol Dedos debe pagar! ¡Por el amor del capital, $n, ayúdame!' WHERE `ID`=39208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가십시오, $c님.$B$B대격변이 오기 전에 발견한 물건이 있습니다.$B$B땅 속에서 꺼내지 말아야 할 것을 파내고 말았지요.$B$B산사태가 그 물건을 영원히 잠재우길 기도해 주십시오...', `MaleText_loc4`='走吧，$c。$B$B在大灾变到来之前，我们发现了一些东西。$B$B我们挖出了一些本应该永远被深埋在地下的东西。$B$B无论你信仰什么神，你最好现在就向他祈祷崩裂的大地能再把它埋住……', `MaleText_loc5`='回去，$c。$B$B在大災變發生前，我們找到了些東西。$B$B我們挖出了一些不該被挖出來的東西。$B$B向你的信仰禱告山崩足以把這些東西藏起來吧...', `MaleText_loc7`='Da media vuelta, $c.$b$bEncontramos algo antes de que se desencadenara el Cataclismo.$b$bExcavamos algo que debería haber permanecido enterrado.$b$bReza a quien quieras para que el corrimiento de tierras baste para contenerlo...', `FemaleText_loc1`='돌아가세요, $c님.$B$B대격변이 오기 전에 발견한 물건이 있어요.$B$B땅 속에서 꺼내지 말아야 할 것을 파내고 말았지요.$B$B산사태가 그 물건을 영원히 잠재우길 기도해 주세요...', `FemaleText_loc4`='走吧，$c。$B$B在大灾变到来之前，我们发现了一些东西。$B$B我们挖出了一些本应该永远被深埋在地下的东西。$B$B无论你信仰什么神，你最好现在就向他祈祷崩裂的大地能再把它埋住……', `FemaleText_loc5`='回去，$c。$B$B在大災變發生前，我們找到了些東西。$B$B我們挖出了一些不該被挖出來的東西。$B$B向你的信仰禱告山崩足以把這些東西藏起來吧...', `FemaleText_loc7`='Da media vuelta, $c.$b$bEncontramos algo antes de que se desencadenara el Cataclismo.$b$bExcavamos algo que debería haber permanecido enterrado.$b$bReza a quien quieras para que el corrimiento de tierras baste para contenerlo...' WHERE `ID`=39209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 쥐어라. 모두 물리치자!', `MaleText_loc4`='控制好设备——我们要进行清除了！', `MaleText_loc5`='拿起工具，我們必須出去!', `MaleText_loc7`='¡Coged el equipo, tenemos que marcharnos!', `FemaleText_loc1`='장비를 쥐어라. 모두 물리치자!', `FemaleText_loc4`='控制好设备——我们要进行清除了！', `FemaleText_loc5`='拿起工具，我們必須出去!', `FemaleText_loc7`='¡Coged el equipo, tenemos que marcharnos!' WHERE `ID`=39210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곳곳에 적이 있다!', `MaleText_loc4`='他们到处都是！', `MaleText_loc5`='他們無所不在!', `MaleText_loc7`='¡Están por todas partes!', `FemaleText_loc1`='곳곳에 적이 있다!', `FemaleText_loc4`='他们到处都是！', `FemaleText_loc5`='他們無所不在!', `FemaleText_loc7`='¡Están por todas partes!' WHERE `ID`=39211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프로서 지킬 수 있는 건 스스로 지키자!', `MaleText_loc4`='把身上的东西保管好——每个矮人都应该照顾好自己！', `MaleText_loc5`='能拿多少拿多少，矮人矮人為己!', `MaleText_loc7`='¡Salvad lo que podáis! ¡Que cada enano cuide de sí mismo!', `FemaleText_loc1`='드워프로서 지킬 수 있는 건 스스로 지키자!', `FemaleText_loc4`='把身上的东西保管好——每个矮人都应该照顾好自己！', `FemaleText_loc5`='能拿多少拿多少，矮人矮人為己!', `FemaleText_loc7`='¡Salvad lo que podáis! ¡Que cada enano cuide de sí mismo!' WHERE `ID`=39212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 유물을 훔치게 놔두지 마라!', `MaleText_loc4`='不要让他们把宝物偷走！', `MaleText_loc5`='別讓他們搶走任何一件文物!', `MaleText_loc7`='¡No dejes que se lleven ningún artefacto!', `FemaleText_loc1`='저들이 유물을 훔치게 놔두지 마라!', `FemaleText_loc4`='不要让他们把宝物偷走！', `FemaleText_loc5`='別讓他們搶走任何一件文物!', `FemaleText_loc7`='¡No dejes que se lleven ningún artefacto!' WHERE `ID`=39213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피즈와 에볼이 다시 싸우다니 믿을 수 없어. 꽤 골치가 아파. 우린 그 어느 때보다도 자네가 필요하다고, $n.', `MaleText_loc4`='我不敢相信菲兹和艾沃竟然会自相残杀。这一定是因为他们的压力太大了。现在我们更加需要你了，$n。', `MaleText_loc5`='我不敢相信費嘶和伊柏又在彼此針鋒相對。是壓力造成的。$n，我們沒有比現在更需要你的時候了。', `MaleText_loc7`='No me puedo creer que Fizz y Evol estén intentando matarse otra vez. Es la presión. Te necesitamos más que nunca, $n.' WHERE `ID`=39214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신없군!', `MaleText_loc4`='恐慌！', `MaleText_loc5`='驚慌!', `MaleText_loc7`='¡Que cunda el pánico!', `FemaleText_loc1`='정신없군!', `FemaleText_loc4`='恐慌！', `FemaleText_loc5`='驚慌!', `FemaleText_loc7`='¡Que cunda el pánico!' WHERE `ID`=39215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저리 들어갈 건가요? 전 다시 들어가지 않겠어요!', `FemaleText_loc4`='你要到那里去？我可不打算回去了！', `FemaleText_loc5`='你要進去?我不要回去那裡!', `FemaleText_loc7`='¿Vas a entrar ahí? ¡Yo ahí no vuelvo!' WHERE `ID`=39216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전을 넣으십시오.', `MaleText_loc4`='请投入硬币。', `MaleText_loc5`='請投幣。', `MaleText_loc7`='Introducir monedas.' WHERE `ID`=39217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 제 일이에요, $c님. 장군님께서 순찰하러 나가시면 전 깃발을 들고 다니면서 땅 위에 꽂지요.$B$B장군님께서 깃발 없이 돌아다닌다고 생각해 보세요. 바지를 입지 않고 다니는 거나 마찬가지 아니겠어요?', `MaleText_loc4`='这是我的工作，$c。将军在巡逻的时候，我扛起他的旗帜，并将旗帜牢牢插在土中。$B$B一位将军怎么可能没有旗帜？他还不如不穿裤子。', `MaleText_loc5`='那是我的工作，$c。將軍外出巡邏了，而我便把他的旌旗插在地上。$B$B想看看一個沒有旌旗的將軍，他乾脆連褲子也不要穿算了。', `MaleText_loc7`='Ese es mi trabajo, $c. El General sale de patrulla, y yo llevo su estandarte y lo planto en la tierra.$b$bImagina un general que vaya por ahí sin un estandarte. Es como si no llevara pantalones.' WHERE `ID`=39218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에 들어가도 좋습니다. 이번은 말입니다.', `MaleText_loc4`='这次，我们让你进城。', `MaleText_loc5`='我們這次就讓你進來城裡吧。', `MaleText_loc7`='Por esta vez te dejaremos entrar en la ciudad.', `FemaleText_loc1`='도시에 들어가도 좋아요. 이번은 말이에요.', `FemaleText_loc4`='这次，我们让你进城。', `FemaleText_loc5`='我們這次就讓你進來城裡吧。', `FemaleText_loc7`='Por esta vez te dejaremos entrar en la ciudad.' WHERE `ID`=39219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 당신, 깃발에서 손 떼세요.', `MaleText_loc4`='嗨！别碰那面旗，$g小子:姑娘;。', `MaleText_loc5`='嘿! 把旌旗交出來，$g小子:小妞;。', `MaleText_loc7`='¡Ey! El estandarte no se toca, $ghijo:hija;.' WHERE `ID`=39220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에 들어가는 데 필요한 서류를 작성했습니다.', `MaleText_loc4`='我已经填好了入城所需的文件。', `MaleText_loc5`='我已經填好進入城市所需的文件了。', `MaleText_loc7`='He rellenado todo el papeleo para entrar en la ciudad.', `FemaleText_loc1`='도시에 들어가는 데 필요한 서류를 작성했어요.', `FemaleText_loc4`='我已经填好了入城所需的文件。', `FemaleText_loc5`='我已經填好進入城市所需的文件表格了。', `FemaleText_loc7`='He rellenado todo el papeleo para entrar en la ciudad.' WHERE `ID`=39221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서류에 이상이 없어 보입니다. 들어가십시오.', `MaleText_loc4`='你还要把文件整理好。赶快去做。', `MaleText_loc5`='你的文件看起來沒問題。過去吧。', `MaleText_loc7`='Parece que tus papeles están en orden. Adelante.', `FemaleText_loc1`='서류에 이상이 없어 보이는군요. 들어가세요.', `FemaleText_loc4`='你还要把文件整理好。赶快去做。', `FemaleText_loc5`='你的文件看起來沒問題。進去吧。', `FemaleText_loc7`='Parece que tus papeles están en orden. Adelante.' WHERE `ID`=39222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에 본 적이 있는 것 같습니다만? 당신을 지켜보겠습니다.', `MaleText_loc4`='我以前见过你吗？我们会注意你的。', `MaleText_loc5`='我們以前沒見過嗎?我們會看緊你的一舉一動，市民。', `MaleText_loc7`='¿No te he visto antes? Ten por seguro que no vamos a perderte de vista.', `FemaleText_loc1`='이전에 본 적이 있는 것 같은데요? 당신을 지켜보겠어요..', `FemaleText_loc4`='我以前见过你吗？我们会注意你的。', `FemaleText_loc5`='我們以前沒見過嗎?我們會看緊你的一舉一動，市民。', `FemaleText_loc7`='¿No te he visto antes? Ten por seguro que no vamos a perderte de vista.' WHERE `ID`=39223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1시간 동안만 도시에 머물 수 있습니다. 할 일을 서둘러 처리하십시오.', `MaleText_loc4`='你只能进城一个小时。有什么事就快点干。', `MaleText_loc5`='你只被允許在城裡一個小時。你的動作最好快一點。', `MaleText_loc7`='Tan solo puedes permanecer una hora en la ciudad. Date prisa en ultimar tus asuntos.', `FemaleText_loc1`='1시간 동안만 도시에 머물 수 있어요. 할 일을 서둘러 처리하세요.', `FemaleText_loc4`='你只能进城一个小时。有什么事就快点干。', `FemaleText_loc5`='你只被允許在城裡一個小時。你的動作最好快一點。', `FemaleText_loc7`='Tan solo puedes permanecer una hora en la ciudad. Date prisa en ultimar tus asuntos.' WHERE `ID`=39224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에 들어갈 수 있는 허가를 받으셨습니다.', `MaleText_loc4`='你已经被许可进城了。', `MaleText_loc5`='你身上有入城許可。', `MaleText_loc7`='Tienes permiso para entrar en la ciudad.', `FemaleText_loc1`='도시에 들어갈 수 있는 허가를 받으셨어요.', `FemaleText_loc4`='你已经被许可进城了。', `FemaleText_loc5`='你身上有入城許可。', `FemaleText_loc7`='Tienes permiso para entrar en la ciudad.' WHERE `ID`=39225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 앞에 있는 얼간이가 노움 군대를 데리고 갑자기 나타나기 전까지는 정말 쉬운 일이었어요. 이 기분 나쁜 꼬맹이들이 우리보다 앞서나간다면 푸직 갤리윅스 님에게 제 목을 내놓아야 할지도 모르겠어요.', `FemaleText_loc4`='这里本来是一个美好而又安全的地方。但前面那片空地上突然就出现了一支侏儒军队。$B$B如果我们让那些卑鄙的小个子在这里打赢我们，加里维克斯一定会要我的脑袋。', `FemaleText_loc5`='這本來是再輕鬆不過的了，直到那個不知從哪裡冒出的笨蛋和地精軍團改變了一切。$B$B如果讓這些噁心的小蠢貨來到我們這，加里維克斯一定會把我的頭給摘下來。', `FemaleText_loc7`='Esto iba a ser pan comido hasta que esa cabeza hueca de ahí salió de la nada con un ejército de gnomos.$b$bGallywix me cortará la cabeza si dejamos que estos alfeñiques nos superen.' WHERE `ID`=39226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말리 트윈브레이드 님은 꼭대기에 계세요.', `MaleText_loc4`='马尔雷·双辫就在这上边，$g先生:女士;。', `MaleText_loc5`='你可以在頂層找到馬爾利·塔文布萊德。', `MaleText_loc7`='Marley Trenzado está arriba, $gseñor:señora;.' WHERE `ID`=39227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 거야, 내가 찾은 거라고. 내 거! 내 거란 말이야!', `MaleText_loc4`='我的，是我的，我找到它的。我说了，是我的！我的！', `MaleText_loc5`='我的～～是我的，我找到的。我說了是我的!我的!', `MaleText_loc7`='Mío, es mío, lo he encontrado. ¡Mío, digo! ¡Mío!' WHERE `ID`=39228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기저기 방황하지 마십시오. 할 일이 있으니까요.', `MaleText_loc4`='别闲逛了，我们在这里还有工作。', `MaleText_loc5`='別閒晃;我們還有工作要做。', `MaleText_loc7`='No pierdas el tiempo, tenemos trabajo que hacer.' WHERE `ID`=39229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안에 있군. 놈을 잡아라!', `MaleText_loc4`='他就在这里。别放过他！', `MaleText_loc5`='他在這裡面。抓住他!', `MaleText_loc7`='Está aquí. ¡A por él!' WHERE `ID`=39230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엇... 이게 어떻게 된 거지?', `MaleText_loc4`='什么……我出了什么事？', `MaleText_loc5`='我...我發生了什麼事?', `MaleText_loc7`='¿Qué... Qué me está pasando?' WHERE `ID`=39231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 또 해냈습니다! 주몽가가 다시 한번 쓰러졌군요', `MaleText_loc4`='$n再次取得了成功！祖蒙加再一次死掉了！', `MaleText_loc5`='$n又辦到了!他讓祖孟迦再次被送回了陰間!', `MaleText_loc7`='¡$n lo ha vuelto a conseguir! ¡Y Zumonga ha vuelto a morir!' WHERE `ID`=39232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심약하신 분들은 아마도 눈을 가려야 할지도 모릅니다! 이제 경기장으로 들어올 상대는 센티파르 곤충집의 어두운 굴속에서 생포해온 공포의 생명체니까요! 바람처럼 빠른 죽음의 존재! 사리넥스!', `MaleText_loc4`='胆小的人简直恨不得遮住自己的眼睛！现在登场的是——来自森提帕虫巢黑暗隧道深处的恐怖斗士！跟我一起向着死亡奔跑吧——有请萨里尼克斯！', `MaleText_loc5`='心臟不夠強的觀眾閉上你們的眼睛!身處在觀眾席是一種恐懼，這是森提帕爾巢穴中最陰暗的隧道中抓到的!我們帶來的是瞬間的死亡:薩利尼克斯!', `MaleText_loc7`='¡Los cardíacos deberían taparse los ojos! ¡Ahora traen un horror capturado de los oscuros túneles de la colmena Centipaar! Os presento la muerte con cien pies: ¡SARINEXX!' WHERE `ID`=39233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 바로 진정한 결투라네! 격투는 피를 부르고, 피는 전쟁을 부르지. 모든 고객은 대부분 그런 방식으로 끝을 맺었고 말이야.$B$B이제 사람들은 싸울 일이 있으면 이곳에서 싸우고, 이곳에서 결판을 낸다네! 잠재력을 최고로 발휘할 수 있거든!', `MaleText_loc4`='这就是真相！战斗导致杀戮，杀戮导致战争。而这几乎就是我们全部客户的结局！$B$B现在，当人们要进行战斗的时候，它就发生在这里，也在这里结束！并发挥出最大的观赏潜力！', `MaleText_loc5`='這就是真理!戰鬥帶來死亡，而死亡帶來對立。我們所有客人的下場幾乎都是這樣!$B$B現在呢，在這戰鬥的人開啟了序幕，也將完成閉幕!觀眾的視覺感觀將被刺激到極限!', `MaleText_loc7`='¡Esta es la verdad! La lucha conduce a la muerte, y la muerte conduce a la guerra. ¡Casi nos quedamos sin clientes!$b$bAhora, cuando los hombres luchan, sucede aquí. ¡Y termina aquí! ¡Con el máximo entretenimiento potencial!' WHERE `ID`=39234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사리넥스가 곤죽이 되었군요! $n|1을;를; 멈출 수 있는 자는 아무도 없습니다!', `MaleText_loc4`='谁也无法阻挡$n！萨里尼克斯被杀死了！', `MaleText_loc5`='沒有人能與$n抗衡!薩利尼克斯被屠殺了!', `MaleText_loc7`='¡$n es imparable! ¡Ha masacrado a Sarinexx!' WHERE `ID`=39235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모이신 여러분을 위해 아낌없이 준비했습니다! 이제 무슨 수를 써서라도 $n|1을;를; 없애버리기로 했으니까요! 여러분, 그러니까 관중 여러분이 더 즐겁도록 말입니다! 멀리 운고로 분화구의 숨겨진 밀림에서 잡아온, 여러분을 두려움에 움츠러들게 할... 크라우 왕입니다!', `MaleText_loc4`='我们为搏您一笑不惜血本，朋友们！我们要不惜一切代价干掉$n，只为让您看得过瘾，亲爱的观众！接下来是我们不远万里从安戈洛环形山的隐秘丛林中请出来的重量级人物——在他的力量面前畏缩吧……有请大金钢！', `MaleText_loc5`='我們知道大家想看到的是什麼!為了你們，我們會不計一切代價讓$n被殺死!從遙遠的安戈洛環形山中的隱密叢林所運來的，在庫爾王前感受恐怖的威脅吧!', `MaleText_loc7`='¡No hemos reparado en gastos para el público, amigos! ¡Nos hemos propuesto matar a $n cueste lo que les cueste a ustedes, los espectadores! Teman a lo que ha venido desde una selva oculta en el Cráter de Un''goro... ¡EL REY KRAW!' WHERE `ID`=39236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없습니다! $n|1이;가; 승리했군요! 크라우 왕은 끝장났습니다!', `MaleText_loc4`='难以置信！$n获胜了！大金钢从这个世界上消失了！', `MaleText_loc5`='難以相信!$n又再次勝利了!庫爾王已不存在於這個世界上!', `MaleText_loc7`='¡INCREÍBLE! ¡$n ha ganado! ¡El Rey Kraw está acabado!' WHERE `ID`=39237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=39238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덤불 골짜기의 네싱워리라는 친구 이야기는 들어본 적이 있지. 재미로 모든 동물을 잡는다는 그 친구 말이야.$B$B단지 재미로라... 이 친구 진짜 멍청하지 않나? 안 그래? 이익을 모두 땅바닥에 내버린다고 생각해 보라고!', `MaleText_loc4`='我听说过这个叫奈辛瓦里的家伙。他来自于荆棘谷，以猎捕各种野兽为乐。$B$B他认为这是一种运动。真是个彻头彻尾的白痴，对不对？真不知道他到底把多少值钱的东西扔在田野里，任由它们烂掉！', `MaleText_loc5`='我聽說過這個叫奈辛瓦里的傢伙，在荊棘谷中以狩獵野獸為樂。$B$B他以狩獵為樂!真是個無敵大白癡，對吧?想想他放棄了多少可以賺錢的機會!', `MaleText_loc7`='Me han hablado de un tal Nesingwary, por la Vega de Tuercespina, que caza todo tipo de bestias por deporte.$b$bPor DEPORTE. Vaya idiota, ¿no? ¡Piensa en todos los beneficios que está dejando pudrirse en el campo!' WHERE `ID`=39239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요. 이제 폭발하는 화산에서 벗어난 다음 오크를 만나러 갈 거예요. 함께 무역왕에게 최후의 공격을 퍼부으러 말이지요. 다른 쪽에서 만나...기를 바랄게요.', `FemaleText_loc4`='好了，我们现在要离开这座正在爆炸的火山，尝试和兽人们取得联系，对那个贸易大王发动最后的攻击。希望到时候能再见到你。', `FemaleText_loc5`='好。我們要離開爆發的火山，試著與其他的獸人會合來對貿易親王發動最終突襲。跟你在另一端見...我希望。', `FemaleText_loc7`='De acuerdo. Vamos a alejarnos del volcán en erupción y trataremos de unirnos a los orcos para el asalto final contra el Príncipe mercante. Te veré al otro lado... Espero.' WHERE `ID`=39240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬으로 돌아가야 합니다.', `MaleText_loc4`='返回回音群岛。', `MaleText_loc5`='返回回音群島。', `MaleText_loc7`='Regresa a las Islas del Eco.' WHERE `ID`=39241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이전에는 종종 저를 쇠약하게 만드는 격한 분노 때문에 고생을 해왔습니다. 그렇지만 드리즈를 만난 뒤로는 행복하고 생산적인 인생을 살게 되었습니다.$B$B그리고 이렇게 맨손으로 물건들 두 조각 낼 수 있게 되었습니다.', `MaleText_loc4`='我以前经常会频繁地陷入令人疲惫的愤怒之中。但自从我遇到德利兹之后，我的生活变得更加快乐而且积极。$B$B现在我已经学会了用两只空手把东西撕碎。', `MaleText_loc5`='我曾經非常的暴躁，整個人充滿了憤怒的情緒。但自從我碰到了德瑞茲，我便過著開心和有意義的生活。$B$B而且我還可以用手把東西扯爛。', `MaleText_loc7`='Antes me dejaba llevar por ataques de ira frecuentes e irresistibles. Pero desde que conocí a Driz he llevado una vida feliz y productiva.$b$bY puedo destrozar cosas en mil pedazos con las manos desnudas.' WHERE `ID`=39242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 제게 알려 주십시오.', `MaleText_loc4`='准备好了就告诉我，朋友。', `MaleText_loc5`='你準備好了就跟我說，老兄。', `MaleText_loc7`='Avísame cuando acabes, colega.' WHERE `ID`=39243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서 타고 오던 배가 황혼의 망치단에게 공격당했소! 놈들이 어떻게 배 안으로 들어왔는지는 모르겠지만, 사람들을 전부 죽여버렸소.', `MaleText_loc4`='我们来自诺森德的船遭到了暮光之锤的袭击！我不知道他们是怎样攻入那艘船的。那艘船的船员都牺牲了。', `MaleText_loc5`='暮光之錘對我們從北裂境過來的船發動攻擊!我不知道他們怎麼上船的，但是他們殺光了每一個人。', `MaleText_loc7`='¡El Martillo Crepuscular ha atacado nuestro barco procedente de Rasganorte! No sé cómo consiguieron abordarlo, pero han asesinado a todo el mundo.' WHERE `ID`=39244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브란이 서판과 함께 보낸 수정을 사용해 간신히 목숨을 부지하고 탈출했는데 성공했지만, 놈들 중 하나가 날 따라오고 말았소!', `MaleText_loc4`='利用了布莱恩连同石板一起送来的那块水晶，我保护了自己，并设法逃脱了。但一名袭击者一直对我紧追不舍！', `MaleText_loc5`='我打算利用布萊恩和石板一起送來的水晶保護自己，然後逃脫，不過其中一名攻擊者尾隨在後!', `MaleText_loc7`='Utilicé un cristal que Brann envió junto con las tablillas y me las arreglé para protegerme y escapar. ¡Pero uno de los atacantes me siguió!' WHERE `ID`=39245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정을 사용해 서판을 보호할 테니, 그동안 수정에서 힘을 얻어 날 보호해주시오. 황혼의 망치단 하수인이 내 보호막을 뚫고 들어오면, 아마 날 죽이고 서판을 가져가버릴 거요!', `MaleText_loc4`='我会利用这块水晶来保护石板，看看它是否能为你提供力量来守卫我。如果暮光之锤的爪牙们打破了我的护盾，他们一定会杀死我，夺走石板！', `MaleText_loc5`='我會用水晶來加護石板。看看這會不會給你防禦我的能力。如果暮光之錘的爪牙們破除我的護盾，他們會把我殺死並搶走石板!', `MaleText_loc7`='Utilizaré el cristal para proteger las tablillas. Comprueba si también te otorgará poderes para defenderme. Si los esbirros del Martillo Crepuscular consiguen atravesar mi escudo, ¡me matarán y se llevarán las tablillas!' WHERE `ID`=39246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 붙잡으세요! 안전띠는 바보들이나 매는 겁니다.', `MaleText_loc4`='稳住身体，不要惊慌！安全带是给傻瓜用的。', `MaleText_loc5`='後面的抓緊了!蠢蛋才需要安全帶。', `MaleText_loc7`='¡Agárrate bien fuerte! Los cinturones de seguridad son para nenazas.' WHERE `ID`=39247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 바엘 모단을 자랑스러워 합니다. 칼림도어 최초의 드워프 정착지였죠.', `MaleText_loc4`='我们为巴尔莫丹感到骄傲。它是矮人在卡利姆多的第一个定居点。', `MaleText_loc5`='我們對巴爾莫丹感到很驕傲。那是矮人在卡林多的第一座基地。', `MaleText_loc7`='Todos estamos muy orgullosos de Bael Modan. Fue el primer asentamiento enano en Kalimdor.' WHERE `ID`=39248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위에 있는 건 바엘던 요새입니다. 정말 아름답죠? 아주 튼튼한 요새라고요!', `MaleText_loc4`='前方就是巴尔丹城堡了。是不是很漂亮？她绝对是坚不可摧的！', `MaleText_loc5`='前面就是巴爾丹城堡，她很美對吧?那個堡壘是堅不可摧的!', `MaleText_loc7`='Más adelante está la Fortaleza de Bael''dun. ¿No es una belleza? Ese bastión es indestructible.' WHERE `ID`=39249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 성채가 공격받고 있습니다!', `MaleText_loc4`='……什么？城堡遭到了攻击！', `MaleText_loc5`='...搞什麼?基地正受到攻擊!', `MaleText_loc7`='...¿Pero qué? ¡Están atacando la fortaleza!' WHERE `ID`=39250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 안 되겠는데! 구조 요청! 구조 요청!', `MaleText_loc4`='我……我控制不住了！求援！求援！', `MaleText_loc5`='我...我支撐不住了!求救!求救!', `MaleText_loc7`='No... ¡No puedo controlarlo! ¡Mayday! ¡MAYDAY!' WHERE `ID`=39251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 난폭한 타우렌 따위 전혀 무섭지 않습니다.', `MaleText_loc4`='呸！吵闹的牛头人吓不住我。', `MaleText_loc5`='嘎!粗暴的牛頭人是嚇不到我的。', `MaleText_loc7`='¡Bah! Los tauren pendecieros no me dan nada de miedo.' WHERE `ID`=39252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일인용 비행기지만 동체 위에 한 명은 더 앉을 수 있습니다. 아주 안전하죠.$B$B준비는 되셨습니까?', `MaleText_loc4`='这是一架单座飞机。但你可以骑在机身上。这非常安全。$B$B准备好了吗？', `MaleText_loc5`='這是個一人座位飛機，但歡迎你坐在機身上。別怕別怕，超級安全的啦。$B$B你準備好了嗎?', `MaleText_loc7`='Es un avión monoplaza, pero siempre puedes sentarte en el fuselaje. Es perfectamente seguro.$b$b¿Despegamos ya?' WHERE `ID`=39253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐어요, 말리. 출발합시다!', `MaleText_loc4`='准备好了，马尔雷。我们起飞吧！', `MaleText_loc5`='我準備好了，馬爾利。我們飛吧!', `MaleText_loc7`='Estoy listo, Marley. ¡A volar!', `FemaleText_loc1`='준비됐어요, 말리. 출발합시다!', `FemaleText_loc4`='准备好了，马尔雷。我们起飞吧！', `FemaleText_loc5`='我準備好了，馬爾利。我們飛吧!', `FemaleText_loc7`='Estoy lista, Marley. ¡A volar!' WHERE `ID`=39254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈시가 배를 가지고 오라고 저를 보냈습니다.', `MaleText_loc4`='凯尔希派我来要一艘船。', `MaleText_loc5`='凱爾希送我來拿一艘船。', `MaleText_loc7`='Kelsey me ha enviado en busca de un bote.', `FemaleText_loc1`='켈시가 배를 가지고 오라고 저를 보냈습니다.', `FemaleText_loc4`='凯尔希派我来要一艘船。', `FemaleText_loc5`='凱爾希送我來拿一艘船。', `FemaleText_loc7`='Kelsey me ha enviado en busca de un bote.' WHERE `ID`=39255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 작은 친구는 누구입니까?', `MaleText_loc4`='那个小家伙是谁？', `MaleText_loc5`='這個小傢伙是誰?', `MaleText_loc7`='¿Quién es el pequeñín?', `FemaleText_loc1`='이 작은 친구는 누구인가요?', `FemaleText_loc4`='那个小家伙是谁？', `FemaleText_loc5`='這個小傢伙是誰?', `FemaleText_loc7`='¿Quién es el pequeñín?' WHERE `ID`=39256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 친구는 내 조수일세.$B$B우리처럼 한 번도 역병에 걸려본 적 없던 녀석이었지, 하지만 이번에 확실히 역병에 걸리고 말았다네. 이 친구도 실바나스 님께 무릎을 꿇었지, 자네나 나처럼 말이지.$B$B이건 우리 둘만의 비밀인데... 솔직히 말하면, 어둠의 여왕님은 이 친구가 방에 들어가기도 전부터 이미 무릎을 꿇은 상태였다고 생각하셨을 거야!', `MaleText_loc4`='他是我的助手。$B$B虽然他也受到了瘟疫的感染，但显然感染的方式和我们有些区别。就像你和我一样，他也臣服于希尔瓦娜斯。$b$b这话不要告诉别人……说实话，我相信当他进入黑暗女王的房间时，黑暗女王并没有怀疑他的忠诚。', `MaleText_loc5`='他是我的助手。$B$B當然，他腐化的方式與我們不一樣，但他很明顯的還是腐化了。他向希瓦娜斯低了頭，所以他其實跟你我都是一樣的。$b$b跟你說別說出去...老實說，黑暗女王覺得他在進入她的大廳前就已經低頭了!', `MaleText_loc7`='Es mi ayudante.$b$bVale, no ha sufrido la peste de la misma forma que nosotros, pero en cualquier caso le ha afectado alguna peste. Se ha arrodillado ante Sylvanas, así que es uno de los nuestros igual que tú y yo.$b$bEntre nosotros... ¡Para ser sincero, creo que la Dama Oscura se ha pensado que ya estaba de rodillas cuando ha entrado en la cámara!' WHERE `ID`=39257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화산이 진짜로 터지기 전에 모두 구출해서 여기를 빠져나가야 해요!', `FemaleText_loc4`='我们必须在火山真正爆发之前救出所有人，并离开这里！', `FemaleText_loc5`='我們必須在這的火山真的爆發前救出所有的人後離開這裡!', `FemaleText_loc7`='¡Tenemos que rescatar a todo el mundo y salir de aquí antes de que el volcán estalle de verdad!' WHERE `ID`=39258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 생각이 떠올랐어요!', `FemaleText_loc4`='我有主意了！', `FemaleText_loc5`='我想到了一個主意!', `FemaleText_loc7`='¡TENGO UNA IDEA!' WHERE `ID`=39259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 수정 같으니! 우린 절대 쉽게 포기하지 않는다. 선조를 위해 반드시 서판을 차지하겠어. 오늘은 실패했지만 곧 다시 오겠다!', `MaleText_loc4`='该死的水晶！我们不会这样轻易就放弃。我们一定会把这块石板献给我们的先祖。也许不是今天，但这一天很快就要来了！', `MaleText_loc5`='該死的水晶!我們才不會輕易放棄呢。有一天我們會將石板拿到手，化為不死之身。或許不是今天，但是用不了多久了!', `MaleText_loc7`='¡Maldito sea el cristal! No vamos a rendirnos tan fácilmente. Tenemos que hacernos con esa tablilla para nuestros ascendientes. Puede que hoy no, ¡pero pronto!', `FemaleText_loc1`='망할 수정 같으니! 우린 절대 쉽게 포기하지 않는다. 선조를 위해 반드시 서판을 차지하겠어. 오늘은 실패했지만 곧 다시 오겠다!', `FemaleText_loc4`='该死的水晶！我们不会这样轻易就放弃。我们一定会把这块石板献给我们的先祖。也许不是今天，但这一天很快就要来了！', `FemaleText_loc5`='該死的水晶!我們才不會輕易放棄呢。有一天我們會將石板拿到手，化為不死之身。或許不是今天，但是用不了多久了!', `FemaleText_loc7`='¡Maldito sea el cristal! No vamos a rendirnos tan fácilmente. Tenemos que hacernos con esa tablilla para nuestros ascendientes. Puede que hoy no, ¡pero pronto!' WHERE `ID`=39260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 서판을 보호할 수 있도록 날 도와주시오. 황혼의 망치단은 서판을 손에 넣을 때까지 멈추지 않을 거요.', `MaleText_loc4`='你必须帮助我保卫地之石板。暮光之锤如果得不到这些石板，绝不会善罢甘休。', `MaleText_loc5`='你一定要幫我保護大地石板。除非暮光之錘取得石板，不然他們不會收手的。', `MaleText_loc7`='Debes ayudarme a defender las tablillas de la tierra. El Martillo Crepuscular no se detendrá hasta que las haya conseguido.' WHERE `ID`=39261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 서판 지키는 걸 도와드리겠습니다.', `MaleText_loc4`='我会帮助你保卫这些石板。', `MaleText_loc5`='我會幫你保護石板。', `MaleText_loc7`='Te ayudaré a defender las tablillas.', `FemaleText_loc1`='제가 서판 지키는 걸 도와드리겠습니다.', `FemaleText_loc4`='我会帮助你保卫这些石板。', `FemaleText_loc5`='我會幫你保護石板。', `FemaleText_loc7`='Te ayudaré a defender las tablillas.' WHERE `ID`=39262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 꽤 인상적이군. 좋아, 자네는 내 시험을 통과했네.', `MaleText_loc4`='嗯……非常精彩。好了，你通过了我的测试。', `MaleText_loc5`='嗯...令人印象非常深刻。好吧，你通過了我的試驗。', `MaleText_loc7`='Mm... Impresionante. De acuerdo, has superado la prueba.' WHERE `ID`=39263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랍군요! 배우는 속도가 빠르시네요.', `FemaleText_loc4`='真是精彩！你学得很快，我的学生。', `FemaleText_loc5`='了不起!你學習的很快，我的學生。', `FemaleText_loc7`='¡Impresionante! Aprendes rápido, $gaprendiz:aprendiza;.' WHERE `ID`=39264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈어! 서판을 보호하는 데 성공했군. 서둘러 아이언포지로 이 서판을 가져가시오. 난 얼마간 체력을 회복한 다음 들르겠소.', `MaleText_loc4`='你成功了！你拯救了这些石板。赶快把它们送到铁炉堡。我恢复一下就会赶回去。', `MaleText_loc5`='你辦到了!石板安全了。快點把石板帶去鐵爐堡交給麥格尼。跟他說等我復原之後就會回去。', `MaleText_loc7`='¡Lo has conseguido! Has salvado las tablillas. Date prisa y llévalas a Forjaz. Yo iré en cuanto me haya recuperado un poco.' WHERE `ID`=39265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두오크나... 이거 부끄러워서 원.', `MaleText_loc4`='多克纳……这太难堪了。', `MaleText_loc5`='多克納...這很丟臉。', `MaleText_loc7`='Duokna... Me estás avergonzando.' WHERE `ID`=39266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두오크나, 지금 뭐 하는 거요?', `MaleText_loc4`='多克纳，你在干什么？', `MaleText_loc5`='多克納，你在做什麼?', `MaleText_loc7`='Duokna, ¿qué estás haciendo?' WHERE `ID`=39267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 여기로 내려오시오!', `MaleText_loc4`='立刻给我下来！', `MaleText_loc5`='馬上給我下來!', `MaleText_loc7`='¡Baja de ahí ahora mismo!' WHERE `ID`=39268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발이 뜨겁지도 않소?', `MaleText_loc4`='你不怕两只脚被烧掉吗？', `MaleText_loc5`='你的腳怎麼沒燒起來?', `MaleText_loc7`='¿No te quemas los pies?' WHERE `ID`=39269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 서판을 손에 넣었다!', `MaleText_loc4`='石板终于是我们的了！', `MaleText_loc5`='終於，這些石板是屬於我們的了!', `MaleText_loc7`='¡Por fin las tablillas son nuestras!', `FemaleText_loc1`='드디어, 서판을 손에 넣었다!', `FemaleText_loc4`='石板终于是我们的了！', `FemaleText_loc5`='終於，這些石板是屬於我們的了!', `FemaleText_loc7`='¡Por fin las tablillas son nuestras!' WHERE `ID`=39270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴장하십시오, $r|1이여;여;.$b$b나가가 언제든 다시 쳐들어올 수 있으니 말입니다.', `MaleText_loc4`='坚持住，$r。$b$b纳迦随时有可能再次发动攻击。', `MaleText_loc5`='準備好，$r。$b$b納迦隨時都會發動攻擊。', `MaleText_loc7`='Prepárate, $r.$b$bLos nagas pueden atacar en cualquier momento.' WHERE `ID`=39271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역은 세상을 찢어발긴 대격변의 진원지 중 하나입니다.$b$b만약 우리가 살아남는다면, 원인을 파악해 봐야 할 겁니다.', `MaleText_loc4`='这里正是这场可能毁灭世界的大灾变爆发的核心区域之一。$b$b如果我们要生存下去，就必须发掘出它的原因。', `MaleText_loc5`='這個地區是導致大地被撕裂的大災變的一處震源。$b$b如果我們活了下來，我們必定得找出災難發生的原因。', `MaleText_loc7`='Esta región es uno de los epicentros de un cataclismo que amenaza con desgarrar nuestro mundo.$b$bSi conseguimos sobrevivir, debemos intentar descubrir su causa.' WHERE `ID`=39272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배에 퍼부어진 공격은, 무차별로 이뤄진 것이 아니었습니다.$b$b나가가 여기 온 의도를 밝혀내야 합니다.', `MaleText_loc4`='对于这些船只的攻击显然不是偶然的。$b$b我们必须查清楚那些纳迦的动机。', `MaleText_loc5`='對這些船發動的攻擊，很明顯的並不是巧合。$b$b我們必須找出納迦出現在這的動機。', `MaleText_loc7`='Los ataques que han sufrido estos barcos son claramente intencionados.$b$bDebemos descubrir qué interés tienen los nagas en todo esto.' WHERE `ID`=39273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 전체가 무너질 거예요!', `MaleText_loc4`='这座城堡就要塌了！', `MaleText_loc5`='整個堡壘要垮了!', `MaleText_loc7`='¡Todo esto se viene abajo!', `FemaleText_loc1`='요새 전체가 무너질 거예요!', `FemaleText_loc4`='这座城堡就要塌了！', `FemaleText_loc5`='整個堡壘要垮了!', `FemaleText_loc7`='¡Todo esto se viene abajo!' WHERE `ID`=39274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고마워요!', `MaleText_loc4`='谢谢你，谢谢你！', `MaleText_loc5`='謝謝你，謝謝!', `MaleText_loc7`='¡Gracias, gracias!', `FemaleText_loc1`='정말 고마워요!', `FemaleText_loc4`='谢谢你，谢谢你！', `FemaleText_loc5`='謝謝你，謝謝!', `FemaleText_loc7`='¡Gracias, gracias!' WHERE `ID`=39275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌다 이런 일이 일어났을까요?', `MaleText_loc4`='这怎么可能发生？', `MaleText_loc5`='怎麼會發生這種事?', `MaleText_loc7`='¿Cómo ha podido pasar esto?', `FemaleText_loc1`='어쩌다 이런 일이 일어났을까요?', `FemaleText_loc4`='这怎么可能发生？', `FemaleText_loc5`='怎麼會發生這種事?', `FemaleText_loc7`='¿Cómo ha podido pasar esto?' WHERE `ID`=39276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람이 아직 더 있어요. 병영 쪽을 찾아보세요!', `MaleText_loc4`='还有其他人——搜索整座营地！', `MaleText_loc5`='還有其他人─搜索兵營!', `MaleText_loc7`='¡Aún hay más! ¡Busca en el cuartel!', `FemaleText_loc1`='사람이 아직 더 있어요. 병영 쪽을 찾아보세요!', `FemaleText_loc4`='还有其他人——搜索整座营地！', `FemaleText_loc5`='還有其他人─搜索兵營!', `FemaleText_loc7`='¡Aún hay más! ¡Busca en el cuartel!' WHERE `ID`=39277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 짓을 할 수 있는 거죠?', `MaleText_loc4`='他们怎么能这样做！', `MaleText_loc5`='他們怎麼能做出這種事?', `MaleText_loc7`='¿Cómo han podido hacer esto?', `FemaleText_loc1`='어떻게 이런 짓을 할 수 있는 거죠?', `FemaleText_loc4`='他们怎么能这样做！', `FemaleText_loc5`='他們怎麼能做出這種事?', `FemaleText_loc7`='¿Cómo han podido hacer esto?' WHERE `ID`=39278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전당 쪽 지붕이 무너져내리는 바람에, 죽은 사람이 많아요!', `MaleText_loc4`='大厅的屋顶坍塌了。许多人都死了！', `MaleText_loc5`='食堂的屋頂垮了下來。好多人...死了!', `MaleText_loc7`='Se ha derrumbado el techo del comedor. ¡Cuántos... muertos!', `FemaleText_loc1`='전당 쪽 지붕이 무너져내리는 바람에, 죽은 사람이 많아요!', `FemaleText_loc4`='大厅的屋顶坍塌了。许多人都死了！', `FemaleText_loc5`='食堂的屋頂垮了下來。好多人...死了!', `FemaleText_loc7`='Se ha derrumbado el techo del comedor. ¡Cuántos... muertos!' WHERE `ID`=39279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 난장판이 되어가는데, 어떻게 손쓸 방법이 없군요.', `MaleText_loc4`='要是有把铲子，我就能把自己从这堆废墟下面挖出来。', `MaleText_loc5`='這地方快要倒下來了，我卻沒有可以躲的地方。', `MaleText_loc7`='Este sitio es un río de porquería y yo no tengo pala.', `FemaleText_loc1`='칠면조 구이가 돼버리는 줄 알았어요!', `FemaleText_loc4`='我还以为自己会像一只火鸡一样被烤熟！', `FemaleText_loc5`='這地方快要倒下來了，我卻沒有可以躲的地方。', `FemaleText_loc7`='Este sitio es un río de porquería y yo no tengo pala.' WHERE `ID`=39280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장나는 줄로만 알았는데, 정말 고맙습니다!', `MaleText_loc4`='我还以为自己完蛋了！谢谢你！', `MaleText_loc5`='我以為我死定了!謝謝你!', `MaleText_loc7`='¡Creía que era el fin! ¡Gracias!', `FemaleText_loc1`='끝장나는 줄로만 알았는데, 정말 고맙습니다!', `FemaleText_loc4`='我还以为自己完蛋了！谢谢你！', `FemaleText_loc5`='我以為我死定了!謝謝你!', `FemaleText_loc7`='¡Creía que era el fin! ¡Gracias!' WHERE `ID`=39281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이여, 모습을 드러내 여기 황혼의 망치단의 적을 처치하라!', `MaleText_loc4`='元素，听我的命令，消灭这个暮光之锤的敌人！', `MaleText_loc5`='元素啊，我喚你前來、殺掉暮光之錘的敵人!', `MaleText_loc7`='¡Elementales! ¡Les ordeno que acudan a mí y eliminen al enemigo del Martillo Crepuscular!', `FemaleText_loc1`='정령들이여, 모습을 드러내 여기 황혼의 망치단의 적을 처치하라!', `FemaleText_loc4`='元素，听我的命令，消灭这个暮光之锤的敌人！', `FemaleText_loc5`='元素啊，我喚你前來、殺掉暮光之錘的敵人!', `FemaleText_loc7`='¡Elementales! ¡Les ordeno que acudan a mí y eliminen al enemigo del Martillo Crepuscular!' WHERE `ID`=39282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아! 오래 버티긴 힘들겠어!', `MaleText_loc4`='唉呦！我已经受不了了！', `MaleText_loc5`='喔天啊!我再也受不了啦!', `MaleText_loc7`='¡Ay! ¡No creo que pueda resistirlo más!' WHERE `ID`=39283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 너무 아프군!', `MaleText_loc4`='圣光在上，真疼啊！', `MaleText_loc5`='喔聖光啊，那可真痛!', `MaleText_loc7`='¡Por la Luz, eso duele!' WHERE `ID`=39284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 머릴 부수려고 해!', `MaleText_loc4`='它打得可真狠啊！', `MaleText_loc5`='它就像是要把我的頭骨敲扁!', `MaleText_loc7`='¡Está intentando aplastarme el cráneo!' WHERE `ID`=39285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붓는 중', `MaleText_loc4`='灌下去', `MaleText_loc5`='倒出中', `MaleText_loc7`='Vertiendo', `FemaleText_loc1`='붓는 중', `FemaleText_loc4`='灌下去', `FemaleText_loc5`='倒出中', `FemaleText_loc7`='Vertiendo' WHERE `ID`=39286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 저 어둠의 문이 열리기 전부터 이 계곡에 있었소. 이 블러드 엘프 떨거지 놈들이 이곳에 어슬렁거리거나 폐허를 약탈하도록 가만히 놓아둘 생각은 전혀 없소!', `MaleText_loc4`='自从黑暗之门打开以前，我就已经在这座谷里了，$g小子:姑娘;。我可不打算让几个血精灵来肆意劫掠这些遗迹！', `MaleText_loc5`='我在黑暗之門出現之前就已經在這個山谷了。我可不打算讓一堆血精靈在這閒晃並破壞這些廢墟!', `MaleText_loc7`='Yo estuve en este valle incluso antes de que abrieran El Portal Oscuro, $gmuchacho:muchacha;. ¡No tengo ninguna intención de dejar que un puñado de elfos de sangre anden por ahí a sus anchas saqueando esas ruinas!' WHERE `ID`=39287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 필요한가?', `MaleText_loc4`='有什么需要？', `MaleText_loc5`='需要什麼嗎?', `MaleText_loc7`='¿Necesitas algo?' WHERE `ID`=39288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕까지 태워 주시겠습니까?', `MaleText_loc4`='能载我前往剃刀岭吗？', `MaleText_loc5`='我可以搭去剃刀嶺的便車嗎?', `MaleText_loc7`='¿Puedo ir a Cerrotajo?', `FemaleText_loc1`='칼바위 언덕까지 태워 주시겠어요?', `FemaleText_loc4`='能载我前往剃刀岭吗？', `FemaleText_loc5`='我可以搭去剃刀嶺的便車嗎?', `FemaleText_loc7`='¿Puedo ir a Cerrotajo?' WHERE `ID`=39289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서 오던 비행선이 황혼의 망치단의 공격을 받았소! 어떻게 우리를 찾았는진 모르겠지만, 비행선에 있던 선원들은 모두 죽었소.', `MaleText_loc4`='来自诺森德的飞艇遭到了暮光之锤的攻击！我不知道他们是怎样找到我们的，但我们的船员都遇害了。', `MaleText_loc5`='北裂境的飛艇被暮光之錘攻擊了!我不知道他們怎麼找到我們的，但是他們把所有人都殺了。', `MaleText_loc7`='¡El Martillo Crepuscular ha atacado el zepelín de Rasganorte! No sé cómo nos han encontrado, pero han asesinado a todo el mundo.' WHERE `ID`=39290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 티탄의 기록관에서 이 수정과 서판을 발견했소. 이 수정으로 시간을 좀 벌긴 했지만, 놈들은 아직도 나를 쫓고 있소!', `MaleText_loc4`='我们在一座泰坦宝库中发现了这块水晶和一些石板。我用这块水晶争取了一些时间，但他们还在追杀我！', `MaleText_loc5`='我們在一座泰坦資料庫中發現這顆水晶和這些石板。我使用水晶爭取到一些時間，但是他們仍舊尾隨在後!', `MaleText_loc7`='Descubrimos las tablillas en un archivo Titán. Utilicé el cristal para conseguirnos un poco de tiempo, ¡pero todavía me siguen!' WHERE `ID`=39291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정의 힘을 이용하여 나와 서판을 지켜 주시오. 황혼의 망치단 놈들이 내 보호막을 뚫고 들어오면, 분명히 나를 죽이고 이 서판을 가져갈 것이오!', `MaleText_loc4`='利用水晶的力量保卫我和石板。如果暮光之锤的爪牙们打破了我的护盾，他们一定会杀死我，夺走石板！', `MaleText_loc5`='使用水晶來保護我和石板。如果暮光之錘那些爪牙們突破護盾衝過來，他們會殺掉我然後拿走石板!', `MaleText_loc7`='Utiliza el poder del cristal para defenderme a mí y proteger las tablillas. Si los esbirros del Martillo Crepuscular consiguen atravesar mi escudo, ¡me matarán y se llevarán las tablillas!' WHERE `ID`=39292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 정령들을 몰아냈구려. 이 서판을 가지고 서둘러 힘의 골짜기에 있는 대지치유사 노르살라에게 가시오! 나는 조금 쉬다가 몸이 좀 회복되고나서 찾아가겠다고 그녀에게 전해 주시오.', `MaleText_loc4`='你终于将他们赶走了。马上带着这些石板到力量谷去找大地治愈者诺莎拉。告诉她，等我恢复过来就会回去。', `MaleText_loc5`='你終於趕走他們了。立刻拿著石板去力量谷見癒地者諾爾莎拉!告訴她，等過些時間復原以後，我會過去碰面。', `MaleText_loc7`='Por fin has conseguido alejarlos. ¡Toma las tablillas y llévaselas enseguida a la ensalmadora de la tierra Norsala en el Valle de la Fuerza! Dile que yo iré en cuanto me haya recuperado un poco.' WHERE `ID`=39293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르시오. 도움이 필요하오!', `MaleText_loc4`='快，我需要帮助！', `MaleText_loc5`='快點，我需要幫助!', `MaleText_loc7`='¡Deprisa, necesito ayuda!' WHERE `ID`=39294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 밀리면 안 되오!', `MaleText_loc4`='不要让他们冲破防线！', `MaleText_loc5`='別讓他們壓制住我們!', `MaleText_loc7`='¡No dejes que nos dominen!' WHERE `ID`=39295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무식한 황혼의 망치단은 서판을 손에 넣기 위해서라면 세상이라도 멸망시킬 놈들이오.', `MaleText_loc4`='为了得到这些石板，暮光之锤的傻瓜们会把大地撕裂。', `MaleText_loc5`='這些暮光之錘的混球們會翻遍每一寸土地，只為了將這些石板拿到手。', `MaleText_loc7`='Esos insensatos del Martillo Crepuscular removerían cielo y tierra para conseguir esas tablillas.' WHERE `ID`=39296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼애애애애!', `FemaleText_loc4`='不——！', `FemaleText_loc5`='不～～～～～～', `FemaleText_loc7`='¡NOOOOOO!' WHERE `ID`=39297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 독침을 쏘려고 합니다! 지금 토템을 설치하십시오!', `MaleText_loc4`='%s施放了毒伤！现在马上放好图腾！', `MaleText_loc5`='%s正在施展毒化!馬上放下你的圖騰!', `MaleText_loc7`='¡%s está lanzando Envenenar! ¡Planta tu tótem ahora!' WHERE `ID`=39298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $r 친구... 거의 죽을 뻔했네. 잠시만 곁에 있게 해주겠나?', `MaleText_loc4`='谢谢你，$r……我差一点就死了。我能在你身边待一会儿吗？', `MaleText_loc5`='謝謝你，$r...我本來快死了。我可以在你的身邊待一會兒嗎?', `MaleText_loc7`='Gracias, $r... Estaba a punto de morir. ¿Puedo acompañarte un rato?', `FemaleText_loc1`='고맙네, $r 친구... 거의 죽을 뻔했네. 잠시만 곁에 있게 해주겠나?', `FemaleText_loc4`='谢谢你，$r……我差一点就死了。我能在你身边待一会儿吗？', `FemaleText_loc5`='謝謝你，$r...我本來快死了。我可以在你的身邊待一會兒嗎?', `FemaleText_loc7`='Gracias, $r... Estaba a punto de morir. ¿Puedo acompañarte un rato?' WHERE `ID`=39299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우다 죽는 줄 알았는데... 아아, 아직 살아 있군. 좀 회복될 때까지 자네를 따르겠네.', `MaleText_loc4`='我应该死在战场上……嗯，总有一天。现在我会跟随你，直到我恢复过来。', `MaleText_loc5`='我應該要戰死沙場才對...算了，改天吧。我在復元前會跟著你。', `MaleText_loc7`='Debería haber muerto en combate... Bueno, otra vez será. Te seguiré hasta que me recupere.', `FemaleText_loc1`='싸우다 죽는 줄 알았는데... 아아, 아직 살아 있군. 좀 회복될 때까지 자네를 따르겠네.', `FemaleText_loc4`='我应该死在战场上……嗯，总有一天。现在我会跟随你，直到我恢复过来。', `FemaleText_loc5`='我應該要戰死沙場才對...算了，改天吧。我在復元前會跟著你。', `FemaleText_loc7`='Debería haber muerto en combate... Bueno, otra vez será. Te seguiré hasta que me recupere.' WHERE `ID`=39300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 목숨을 구해 줬군. 상처가 나을 때까지 조금만 더 날 보호해 주게.', `MaleText_loc4`='你救了我， $c。在我体力恢复之前，请再保护我一段时间。', `MaleText_loc5`='你救了我一命，$c。在我恢復前再保護我一下。', `MaleText_loc7`='Me has salvado la vida, $c. Protégeme unos minutos más mientras me recupero.', `FemaleText_loc1`='내 목숨을 구해 줬군. 상처가 나을 때까지 조금만 더 날 보호해 주게.', `FemaleText_loc4`='你救了我， $c。在我体力恢复之前，请再保护我一段时间。', `FemaleText_loc5`='你救了我一命，$c。在我恢復前再保護我一下。', `FemaleText_loc7`='Me has salvado la vida, $c. Protégeme unos minutos más mientras me recupero.' WHERE `ID`=39301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님을 위하여! 앞장서게. 자네를 따르겠네.', `MaleText_loc4`='为了酋长！我会紧紧地跟随你。', `MaleText_loc5`='為了大酋長!你領導，我跟隨。', `MaleText_loc7`='¡Por el Jefe de Guerra! Lidera, yo te seguiré.', `FemaleText_loc1`='대족장님을 위하여! 앞장서게. 자네를 따르겠네.', `FemaleText_loc4`='为了酋长！我会紧紧地跟随你。', `FemaleText_loc5`='為了大酋長!你領導，我跟隨。', `FemaleText_loc7`='¡Por el Jefe de Guerra! Lidera, yo te seguiré.' WHERE `ID`=39302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 좀 살 만하군. 호드를 위하여!', `MaleText_loc4`='我感觉好多了。为了部落！', `MaleText_loc5`='我感覺好多了。為了部落!', `MaleText_loc7`='Ya me siento mucho mejor. ¡Por la Horda!', `FemaleText_loc1`='이제 좀 살 만하군. 호드를 위하여!', `FemaleText_loc4`='我感觉好多了。为了部落！', `FemaleText_loc5`='我感覺好多了。為了部落!', `FemaleText_loc7`='Ya me siento mucho mejor. ¡Por la Horda!' WHERE `ID`=39303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거듭 감사하네. 이제 칼바위 언덕으로 돌아가겠네.', `MaleText_loc4`='再次感谢你。现在我要返回剃刀岭了。', `MaleText_loc5`='再次謝謝你。我現在會回去剃刀嶺。', `MaleText_loc7`='Gracias de nuevo. Ahora volveré a Cerrotajo.', `FemaleText_loc1`='거듭 감사하네. 이제 칼바위 언덕으로 돌아가겠네.', `FemaleText_loc4`='再次感谢你。现在我要返回剃刀岭了。', `FemaleText_loc5`='再次謝謝你。我現在會回去剃刀嶺。', `FemaleText_loc7`='Gracias de nuevo. Ahora volveré a Cerrotajo.' WHERE `ID`=39304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네가 싸우는 걸 지켜볼 수 있어 영광이었네.', `MaleText_loc4`='能亲眼见证你的战斗是我的荣幸，$n。', `MaleText_loc5`='能看到你的戰技是我的榮幸，$n。', `MaleText_loc7`='Ha sido un honor verte luchar, $n.', `FemaleText_loc1`='$n, 자네가 싸우는 걸 지켜볼 수 있어 영광이었네.', `FemaleText_loc4`='能亲眼见证你的战斗是我的荣幸，$n。', `FemaleText_loc5`='能看到你的戰技是我的榮幸，$n。', `FemaleText_loc7`='Ha sido un honor verte luchar, $n.' WHERE `ID`=39305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 참 잘 싸우는군. 이제 가봐야겠네. 록타르 오가르!', `MaleText_loc4`='你打得很好。现在我要和你说再见了。Lok''tar ogar！', `MaleText_loc5`='好好戰鬥。我先走了。不勝即亡!', `MaleText_loc7`='Luchas bien. Ahora te dejo. ¡Lok''tar ogar!', `FemaleText_loc1`='자네 참 잘 싸우는군. 이제 가봐야겠네. 록타르 오가르!', `FemaleText_loc4`='你打得很好。现在我要和你说再见了。Lok''tar ogar！', `FemaleText_loc5`='好好戰鬥。我先走了。不勝即亡!', `FemaleText_loc7`='Luchas bien. Ahora te dejo. ¡Lok''tar ogar!' WHERE `ID`=39306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 나를 좀 도와 주시오. 황혼의 망치단이 내 비행선을 공격하더니, 오그리마로 운반 중이던 서판과 수정을 빼앗아 가려고 하고 있소.', `MaleText_loc4`='你必须帮助我，$c！暮光之锤袭击了我的飞艇，妄图夺走正在被运往奥格瑞玛的石板和水晶。', `MaleText_loc5`='你一定得幫幫我啊，$c!暮光之錘對我的飛船發動攻擊，他們企圖搶走我要送去奧格瑪的石板和水晶。', `MaleText_loc7`='¡Tienes que ayudarme, $c! El Martillo Crepuscular ha atacado mi zepelín y sus hombres han intentado llevarse las tablillas y el cristal que transportaba a Orgrimmar.' WHERE `ID`=39307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 서판 지키는 걸 도와드리겠습니다.', `MaleText_loc4`='我会帮助你保卫这些石板。', `MaleText_loc5`='我會幫你守衛這些石板。', `MaleText_loc7`='Te ayudaré a defender las tablillas.', `FemaleText_loc1`='제가 서판 지키는 걸 도와드리겠습니다.', `FemaleText_loc4`='我会帮助你保卫这些石板。', `FemaleText_loc5`='我會幫你守衛這些石板。', `FemaleText_loc7`='Te ayudaré a defender las tablillas.' WHERE `ID`=39308;
