UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너같은 놈 노예도 아니다! 일하지 않으려면 죽어라!', `MaleText_loc4`='该死的奴隶！不干活就去死！', `MaleText_loc5`='你!奴隸!不工作!死翹翹!', `MaleText_loc7`='¡No eres un esclavo! ¡Trabaja o muere!' WHERE `ID`=39315;
