UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 노움이 떠돌이 생활을 청산하고 돌아갈 때가 왔네.$B$B놈리건은 다시 한 번 우리의 보금자리가 될 걸세!', `MaleText_loc4`='侏儒夺回家园的时候终于到了。$B$B诺莫瑞根将再次回到我们的手中！', `MaleText_loc5`='終於，是該讓流亡在外的地精回家的時候了。$B$B諾姆瑞根將會再次成為我們的家園!', `MaleText_loc7`='Por fin es hora de que regresen los gnomos exiliados.$B$BUna vez más, ¡Gnomeregan será nuestro hogar!' WHERE `ID`=39317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역왕께서 너 좀 손봐주랬다!', `MaleText_loc4`='贸易大王说了，要对你厉害点！', `MaleText_loc5`='貿易親王說要傷害你!', `MaleText_loc7`='¡Príncipe mercante decir hacer daño a ti!' WHERE `ID`=39318;
