UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 손봐주는 거 재밌다!', `MaleText_loc4`='我很喜欢打你！', `MaleText_loc5`='我喜歡打你!', `MaleText_loc7`='¡A mí gustar darte paliza!' WHERE `ID`=39320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 감독관이고, 너 노예다!', `MaleText_loc4`='我是工头，你是奴隶！', `MaleText_loc5`='我是監督者，你是奴隸!', `MaleText_loc7`='¡Yo supervisor, tú esclavo!' WHERE `ID`=39321;
