UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 전투의 충격이 갑작스레 우리를 흔들어도, 한순간도 긴장을 놓을 수 없는 날들이 끝없이 이어진다 해도, 우리는 무릎 꿇지 않을 것이다.', `MaleText_loc4`='', `MaleText_loc5`='[PH]不論是受到突發戰鬥的驚嚇，還是長時間執行警戒任務，都無法削弱我們。', `MaleText_loc7`='[PH] Neither the sudden shock of battle, nor the long-drawn trials of vigilance and exertion will wear us down.' WHERE `ID`=39336;
