UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 고블린을 처치해버리세요. 어서요!', `FemaleText_loc4`='杀掉那个地精，赶快！', `FemaleText_loc5`='殺了那個哥布林，快點!', `FemaleText_loc7`='Matad a $gese:esa; goblin, ¡rápido!' WHERE `ID`=39341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비된 광산 수레를 움직일 수 있습니다.', `MaleText_loc4`='矿车已经做好了出发的准备。', `MaleText_loc5`='礦坑推車已經準備好隨時可以出發了。', `MaleText_loc7`='La vagoneta está preparada y lista para partir.' WHERE `ID`=39342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현장에 온 걸 환영해요, $c 친구! 온종일 요새에만 틀어박혀 있으면 전술 상황에 대해 감을 잡을 수가 없지요. 전 언제나 직접 발로 뛰고 있어요.', `MaleText_loc4`='欢迎来到前线，$c！如果只是躲在城堡里面，你将无法对现在的战争态势有真正的感受。这就是我总不愿意离开战场的原因。', `MaleText_loc5`='歡迎來到這片土地，$c!你如果整天都躲在堡壘後面是無法感受到戰略所帶來的臨場感的。我一向都不在意來點刺激的。', `MaleText_loc7`='¡Bienvenido al campo de batalla, $c! Si te pasas todo el día escondido en una fortaleza es imposible percibir la situación táctica. A mí me gusta ensuciarme las botas.' WHERE `ID`=39343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발굴현장에 있는 제 착한 아들 말리를 꼭 만나보세요. 바엘 모단에서 제 눈과 귀가 되어주고 있지요.', `MaleText_loc4`='一定要去那片挖掘场和我的儿子马尔雷谈一谈。他是个好孩子。我必须以全部的精力监视巴尔莫丹。', `MaleText_loc5`='別忘了到挖掘場找我的兒子馬爾利。他是個好孩子，是我在巴爾莫丹的眼睛和耳朵。', `MaleText_loc7`='Asegúrate de hablar con mi hijo Marley en la excavación. Es un buen muchacho, mis ojos y mis oídos por todo Bael Modan.' WHERE `ID`=39344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바엘 모단에 갔었나요? 그곳은 별 일 없던가요?', `MaleText_loc4`='你去过巴尔莫丹吗？那里发生了什么事？', `MaleText_loc5`='你有去過巴爾莫丹嗎?那裡發生了什麼事?', `MaleText_loc7`='¿Has estado en Bael Modan? ¿Qué está sucediendo allí?' WHERE `ID`=39345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 대가를 치르게 해주고 말겠어요, $n. 한 놈도 빠짐없이 모두.', `MaleText_loc4`='他们一定要付出代价，$n。他们全都要付出代价。', `MaleText_loc5`='他們會為此付出代價的，$n。他們全部的人都將付出代價。', `MaleText_loc7`='Pagarán por esto, $n. Todos pagarán por esto.' WHERE `ID`=39346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 나간 타우렌들...호시탐탐 제 비행기를 망가뜨리려고 하지 뭡니까. 벌써 몇 년 동안이나요!', `MaleText_loc4`='那些疯狂的牛头人。已经有好几年了，他们总是要炸掉我的飞行器！', `MaleText_loc5`='這些牛頭人瘋子，一直想要炸飛我的飛行器。已經這樣好幾年了!', `MaleText_loc7`='Esos tauren locos siempre intentan hacer saltar por los aires mi máquina voladora. ¡Llevamos así años!' WHERE `ID`=39347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴장 푸십시오, 친구여. 저승길 떠나는 것도 아니지 않습니까... 아직은요. 여기 있는 이들은 안타깝게도 벌써 떠났지만 말입니다.', `MaleText_loc4`='放松，朋友。你还活着。但其他人就没有你这么幸运了。', `MaleText_loc5`='放輕鬆，朋友。你還活著...至少現在還是。不幸的是，其他人運氣就沒那麼好了。', `MaleText_loc7`='Tranquilo, camarada. No has muerto... aún. Lamentablemente, no puedo decir lo mismo de otros.' WHERE `ID`=39348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 땅을 침범하다니!', `MaleText_loc4`='你冒犯了神圣的领地！', `MaleText_loc5`='你侵入了神聖的土地!', `MaleText_loc7`='¡Has entrado en terreno sagrado sin permiso!' WHERE `ID`=39349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 폭발하듯 격렬하게 분노합니다!', `MaleText_loc4`='%s发出一阵凶猛的吼叫！', `MaleText_loc5`='%s帶著無比狂野的怒氣爆發了!', `MaleText_loc7`='%s explota en una ataque de cólera rabioso y salvaje.' WHERE `ID`=39350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅이...널...삼켜버릴 것이다, $r.', `MaleText_loc4`='贫瘠之地……会……吞噬你，$r。', `MaleText_loc5`='貧瘠之地...將會...吞噬你，$r。', `MaleText_loc7`='Los Baldíos... te... devorarán, $r.' WHERE `ID`=39351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 공황 상태예요!', `MaleText_loc4`='所有人都慌了！', `MaleText_loc5`='大家都會緊張!', `MaleText_loc7`='¡Que cunda el pánico!' WHERE `ID`=39352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 성문을 뚫고 들어왔어요! 여기서 벗어나야겠어요!', `MaleText_loc4`='他们冲过了大门！我要离开这里！', `MaleText_loc5`='他們已經過了門了!我要離開這裡!', `MaleText_loc7`='¡Han atravesado las puertas! ¡Yo me largo!' WHERE `ID`=39353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향으로 가는 배가 오면 바로 탈 거예요.', `MaleText_loc4`='我会乘下一艘船回家。', `MaleText_loc5`='我要將下一艘船帶回家。', `MaleText_loc7`='Tomaré el próximo barco rumbo a casa.' WHERE `ID`=39354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 달아나! 살고 싶거든 어서 도망쳐!', `MaleText_loc4`='逃命吧！自求多福吧！', `MaleText_loc5`='逃命啊!地精地精為己!', `MaleText_loc7`='¡Corred para salvar la vida! ¡Que cada gnomo cuide de sí mismo!' WHERE `ID`=39355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 테라모어까지 뛰어서 갈 수 있을까요?', `MaleText_loc4`='你以为我会走着去塞拉摩？', `MaleText_loc5`='你覺得我可以步行到塞拉摩嗎?', `MaleText_loc7`='¿Crees que puedo llegar a Theramore a pie?' WHERE `ID`=39356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전압계를 어디다 뒀더라? 에이, 상관없어. 호드더러 가지라고 하지!', `MaleText_loc4`='我的电压表到哪里去了？呸，没关系，部落会保管好它的！', `MaleText_loc5`='我的伏特計放在哪了?算了，無所謂，就送給部落好了!', `MaleText_loc7`='¿Dónde me he dejado el voltímetro? Bah, da igual. ¡Que se lo quede la Horda!' WHERE `ID`=39357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자료는 많고... 시간은 턱없이 부족하고...', `FemaleText_loc4`='这么多数据……这么点时间……', `FemaleText_loc5`='那麼多的資料...那麼少的時間...', `FemaleText_loc7`='Tantos datos... Tan poco tiempo...' WHERE `ID`=39358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항법장치는 모두 준비됐어요. 조사선을 탈 준비는 되셨나요?', `FemaleText_loc4`='旋翼机全都起飞了。你准备好进行空中勘察了么？', `FemaleText_loc5`='螺旋槳已經在轉了。你準備好要駕駛我的勘查機了嗎?', `FemaleText_loc7`='Los girocópteros están todos boca arriba. ¿Estás $glisto:lista; para llevar a cabo mi estudio?' WHERE `ID`=39359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아갈 준비가 됐습니다.', `MaleText_loc4`='我已经做好了飞行准备。', `MaleText_loc5`='我已準備好可以隨時起飛。', `MaleText_loc7`='Estoy listo para volar.', `FemaleText_loc1`='날아갈 준비가 됐습니다.', `FemaleText_loc4`='我已经做好了飞行准备。', `FemaleText_loc5`='我已準備好可以隨時起飛。', `FemaleText_loc7`='Estoy lista para volar.' WHERE `ID`=39360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥미롭군요. 진원지에서 꽤 먼 곳인데도 아제로스의 지표면이 갈기갈기 찢겨 있으니 말이에요.', `FemaleText_loc4`='真有趣，即使在距离震中如此遥远的地方，艾泽拉斯的外表还是彻底被撕碎了。', `FemaleText_loc5`='很有趣。就算離震央那麼遠，艾澤拉斯的邊緣也被完全震裂了。', `FemaleText_loc7`='Interesante. Incluso aquí, tan lejos del epicentro, la corteza de Azeroth está totalmente destrozada.' WHERE `ID`=39361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 대체 뭐지? 지난주에 조사할 때만 해도 이곳에는 밀림이 없었는데. 불모의 땅에 대체 무슨 일이 일어나고 있는 거죠?', `FemaleText_loc4`='这些都是什么？在上周进行勘察的时候，这片丛林还没有出现。贫瘠之地发生了什么？', `FemaleText_loc5`='這是什麼?這片叢林在上週的勘查中根本不存在。貧瘠之地發生了什麼事?', `FemaleText_loc7`='¿Qué es esto? Esta selva no estaba aquí la semana pasada. ¿Qué está pasando en Los Baldíos?' WHERE `ID`=39362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바닷물이군요. 균열이 대양까지 침투했어요. 점점 커지고 있지 않은가요?', `FemaleText_loc4`='是海水。海洋也被扯开了。你认为这道裂缝还在变宽吗？', `FemaleText_loc5`='那是海水。它已經穿過了海洋。你認為裂縫在擴大嗎?', `FemaleText_loc7`='Es agua de mar. Ha llegado al océano. ¿Crees que la fisura está creciendo?' WHERE `ID`=39363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 멈춰요. 적이 북부감시 요새의 성벽을 뚫고 들어왔어요! 공격받고 있다고요!', `FemaleText_loc4`='固守阵地。北方城堡的城墙被打破了！我们遭到了攻击！', `FemaleText_loc5`='保護好一切!北方城堡的城牆已經被攻破了!我們正遭受攻擊!', `FemaleText_loc7`='¡Atención! ¡Hay una brecha en los muros de Fuerte del Norte! ¡Nos atacan!' WHERE `ID`=39364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감독님께서 여기 계시다고요?! 따로 작전이 있나 보네요.', `FemaleText_loc4`='教练在这里？！他一定有办法的！', `FemaleText_loc5`='教練在這?!他會有辦法。', `FemaleText_loc7`='¿El entrenador está aquí? Él tendrá un plan.' WHERE `ID`=39365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야 이건? 또 다른 쓰레기 지원자인가?', `MaleText_loc4`='你是谁？另一个微不足道的学生？', `MaleText_loc5`='什麼跟什麼?另一個沒用的學生?', `MaleText_loc7`='¿Qué es esto? ¿Más pupilos indignos?' WHERE `ID`=39366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통이 가득한 훈련을 받게 해주지!', `MaleText_loc4`='你将得到一个痛苦的教训！', `MaleText_loc5`='來上一堂何謂痛苦的課!', `MaleText_loc7`='¡Descubrirás lo que es el dolor!' WHERE `ID`=39368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자격이 있는 자만이 우리가 간직한 비밀을 배우게 될 것이다!', `MaleText_loc4`='只有真正的强者才能学到我们的秘密！', `MaleText_loc5`='只有夠格的人才能知道我們守護的秘密!', `MaleText_loc7`='¡Solo los dignos aprenderán los secretos que custodiamos!' WHERE `ID`=39369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산 수레에 탑니다.', `MaleText_loc4`='驾驶矿车。', `MaleText_loc5`='搭乘礦坑推車。', `MaleText_loc7`='Conduce la vagoneta.', `FemaleText_loc1`='광산 수레에 탑니다.', `FemaleText_loc4`='驾驶矿车。', `FemaleText_loc5`='搭乘礦坑推車。', `FemaleText_loc7`='Conduce la vagoneta.' WHERE `ID`=39370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 온 걸 후회하게 될 것이다, 이 벌레 같은 놈아!', `MaleText_loc4`='你会希望自己从没有来过这里，蛆虫！', `MaleText_loc5`='你會希望你從沒到過這裡，蟲子!', `MaleText_loc7`='¡Desearás no haber venido nunca, gusano!' WHERE `ID`=39371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 가르쳐 줄 수 있는 건 죽는 훈련뿐이다.', `MaleText_loc4`='你得到的唯一教训就是死亡。', `MaleText_loc5`='你唯一的課程便是死亡。', `MaleText_loc7`='Aquí solo descubrirás la muerte.' WHERE `ID`=39372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 육체가 불타오르리라, 필멸의 존재여!', `MaleText_loc4`='你将化为灰烬，凡人！', `MaleText_loc5`='凡人!你的血肉將會燃燒!', `MaleText_loc7`='¡Tu carne arderá, mortal!' WHERE `ID`=39373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 배울 수 있을 만큼 실력이 있다고 생각하는가 보군? 그 오만함에 대한 대가를 치르게 해 주겠다!', `MaleText_loc4`='你以为你有能力学习我们的秘密？你将为自己的傲慢付出代价！', `MaleText_loc5`='你以為你有資格向我們學習?為你的自大付出代價吧!', `MaleText_loc7`='¿Crees que eres $gdigno:digna; de aprender de nosotros? ¡Pagarás por tu insolencia!' WHERE `ID`=39374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 맹랑한 주술사로군. 네놈을 처치하고 서판을 초갈 님께 가지고 가겠다.', `MaleText_loc4`='很好，萨满。我会干掉你，然后带着这些石板去见古加尔。', `MaleText_loc5`='很好，薩滿。我會殺死你，把石板帶給丘加利。', `MaleText_loc7`='Muy bien, chamán. Te mataré y le llevaré las tablillas a Cho''Gall.', `FemaleText_loc1`='아주 맹랑한 주술사로군. 네놈을 처치하고 서판을 초갈 님께 가지고 가겠다.', `FemaleText_loc4`='很好，萨满。我会干掉你，然后带着这些石板去见古加尔。', `FemaleText_loc5`='很好，薩滿。我會殺死你，把石板帶給丘加利。', `FemaleText_loc7`='Muy bien, chamán. Te mataré y le llevaré las tablillas a Cho''Gall.' WHERE `ID`=39375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 내게 작전이 있다고!', `MaleText_loc4`='我有一个有趣的计划，孩子！', `MaleText_loc5`='我有一個比賽計畫，小子!', `MaleText_loc7`='¡Tengo una estrategia de juego, chaval!' WHERE `ID`=39376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g젊은이:아가씨;, 이놈들을 얼마나 오래 막아둘 수 있을지 모르겠네. 자네에게 어떤 계획이 있기를 바랄 뿐이야!', `MaleText_loc4`='不知道我们能将他们拖延多久，$g小子:姑娘;，希望你知道该怎样做！', `MaleText_loc5`='我不知道我們還能撐多久。跟我說你已經想到方法了!', `MaleText_loc7`='No sé cuánto tiempo vamos a ser capaces de mantenerlos a raya, $gamigo:señora;. ¡Espero que tengas un plan!' WHERE `ID`=39377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜투덜>', `MaleText_loc4`='<哼哼>', `MaleText_loc5`='<嘀咕>', `MaleText_loc7`='<Gruñido>' WHERE `ID`=39378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 시민들이여, 내 말을 들으시오. 우리는 너무 오랫동안 장님으로 살아왔소! 부탁하노니, 진실에 눈을 뜨시오!', `MaleText_loc4`='奥格瑞玛的居民们，听我说。我们已经失明了太长时间！我请求你们，向真实睁开双眼吧！', `MaleText_loc5`='奧格瑪的人民啊，大家仔細聽。我們被蒙蔽太久了!我要求你們張開雙眼看看真相!', `MaleText_loc7`='Ciudadanos de Orgrimmar, escuchen. ¡Hemos estado ciegos durante demasiado tiempo! ¡Les ruego que abran los ojos y vean la verdad!', `FemaleText_loc1`='오그리마의 시민들이여, 내 말을 들으시오. 우리는 너무 오랫동안 장님으로 살아왔소! 부탁하노니, 진실에 눈을 뜨시오!', `FemaleText_loc4`='奥格瑞玛的居民们，听我说。我们已经失明了太长时间！我请求你们，向真实睁开双眼吧！', `FemaleText_loc5`='奧格瑪的人民啊，大家仔細聽。我們被蒙蔽太久了!我要求你們張開雙眼看看真相!', `FemaleText_loc7`='Ciudadanos de Orgrimmar, escuchen. ¡Hemos estado ciegos durante demasiado tiempo! ¡Les ruego que abran los ojos y vean la verdad!' WHERE `ID`=39379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말이 머지 않았소, 형제자매들이여! 아제로스도 사라질 것이오!', `MaleText_loc4`='世界的末日已经近了，兄弟姐妹们！艾泽拉斯将不复存在！', `MaleText_loc5`='兄弟姊妹們，世界毀滅即將到來!艾澤拉斯將不復存在!', `MaleText_loc7`='¡Se acerca el fin de nuestro mundo, hermanos y hermanas! ¡Azeroth desaparecerá!', `FemaleText_loc1`='세상의 종말이 머지 않았소, 형제자매들이여! 아제로스도 사라질 것이오!', `FemaleText_loc4`='世界的末日已经近了，兄弟姐妹们！艾泽拉斯将不复存在！', `FemaleText_loc5`='兄弟姊妹們，世界毀滅即將到來!艾澤拉斯將不復存在!', `FemaleText_loc7`='¡Se acerca el fin de nuestro mundo, hermanos y hermanas! ¡Azeroth desaparecerá!' WHERE `ID`=39380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 세상을 삼킬 것이고, 폭풍이 희망을 모조리 쓸어갈 것이오. 마침내 정령들의 세상이 도래할 거란 말이오!', `MaleText_loc4`='火焰将吞噬整个世界。暴风会吹走全部希望。元素终将成为这里的统治者！', `MaleText_loc5`='火焰將會吞噬這個世界。風暴將會捲走所有希望。最後元素將會統治一切!', `MaleText_loc7`='Las llamas consumirán el mundo. Las tormentas barrerán toda esperanza. ¡Los elementos reinarán al fin!', `FemaleText_loc1`='불길이 세상를 삼킬 것이고, 폭풍이 희망을 모조리 쓸어갈 것이오. 마침내 정령들의 세상이 도래할 거란 말이오!', `FemaleText_loc4`='火焰将吞噬整个世界。暴风会吹走全部希望。元素终将成为这里的统治者！', `FemaleText_loc5`='火焰將會吞噬這個世界。風暴將會捲走所有希望。最後元素將會統治一切!', `FemaleText_loc7`='Las llamas consumirán el mundo. Las tormentas barrerán toda esperanza. ¡Los elementos reinarán al fin!' WHERE `ID`=39381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 절망할 필요 없소, 오그리마의 시민들이여! 우리와 함께 진리를 배웁시다.', `MaleText_loc4`='奥格瑞玛的人们，不要绝望！加入我们，来了解这个世界的真相吧。', `MaleText_loc5`='但不要感到絕望，奧格瑪的人們!加入我們並了解真相。', `MaleText_loc7`='¡Pero no se desesperen, ciudadanos de Orgrimmar! Únanse a nosotros y descubran la verdad.', `FemaleText_loc1`='하지만 절망할 필요 없소, 오그리마의 시민들이여! 우리와 함께 진리를 배웁시다.', `FemaleText_loc4`='奥格瑞玛的人们，不要绝望！加入我们，来了解这个世界的真相吧。', `FemaleText_loc5`='但不要感到絕望，奧格瑪的人們!加入我們並了解真相。', `FemaleText_loc7`='¡Pero no se desesperen, ciudadanos de Orgrimmar! Únanse a nosotros y descubran la verdad.' WHERE `ID`=39382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 먼저 배워야 할 것은 강인한 군인 정신이다.', `MaleText_loc4`='你要学会的第一件事就是遵守纪律。', `MaleText_loc5`='首先你要學的是，適當的紀律。', `MaleText_loc7`='Lo primero que tienen que aprender como es debido es la disciplina.' WHERE `ID`=39383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 전투에서 가장 중요한 건 힘겹게 얻은 승리를 어떻게 축하하느냐이다.', `MaleText_loc4`='不管怎样，一场战争中最重要的部分是你该如何庆祝来之不易的胜利！', `MaleText_loc5`='儘管如此，戰爭中最重要的部份是你如何慶祝一場得來不易的勝利!', `MaleText_loc7`='¡Sin embargo, la parte más importante de una batalla es cómo celebrar una victoria ganada con el sudor de nuestra frente!' WHERE `ID`=39384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에 돌입하면, 귀청이 떨어질 듯한 고함으로 적의 기선을 제압하는 것이 중요하다!', `MaleText_loc4`='当你进入战斗的时候，知道如何用震耳欲聋的战吼威吓敌人是非常重要的！', `MaleText_loc5`='當你進入戰鬥，知道如何用震耳欲聾的戰鬥怒吼來恫嚇敵人是很重要的一件事。', `MaleText_loc7`='¡Cuando vayan al combate, es importante que sepan cómo intimidar al enemigo con un rugido de batalla ensordecedor!' WHERE `ID`=39385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 꼭 명심해라. 전투에서 승리하려면 사기를 높이는 게 필수적이다.', `MaleText_loc4`='但要记住，赢得战争的关键因素是活跃的增援力量。', `MaleText_loc5`='別忘了，任何勝仗的關鍵之一就是確實的後援。', `MaleText_loc7`='Pero recuerden, el factor clave para ganar una batalla es infundir ánimos.' WHERE `ID`=39386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일동, 환호!', `MaleText_loc4`='大家欢呼吧！', `MaleText_loc5`='大家歡呼!', `MaleText_loc7`='¡Todos a animar!' WHERE `ID`=39387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='회수하는 중', `MaleText_loc4`='回收', `MaleText_loc5`='回收中', `MaleText_loc7`='Recuperando', `FemaleText_loc1`='회수하는 중', `FemaleText_loc4`='回收', `FemaleText_loc5`='回收中', `FemaleText_loc7`='Recuperando' WHERE `ID`=39388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도대체 이 벌목기는 전부 어디에서 생겨나는 거죠?', `FemaleText_loc4`='这些伐木机是从哪里来的？', `FemaleText_loc5`='這些天殺的伐木機是從哪來的?!', `FemaleText_loc7`='¡¿De dónde demonios han salido todas esas trituradoras?!' WHERE `ID`=39389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 이런 짓을 하다니 말도 안 돼!', `MaleText_loc4`='真无法相信，你竟然这样对我！', `MaleText_loc5`='我不敢相信你會這樣對我!', `MaleText_loc7`='¿Cómo has podido hacerme esto?' WHERE `ID`=39390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁으로 얼룩진 이 지긋지긋한 삶을 던져 버리고, 새로운 세상에서 정령으로 다시 태어나 우리의 마땅한 권리를 누리는 거요!', `MaleText_loc4`='抛弃战斗和苦役的生活，在元素中重生，在新世界中取得你的一席之地吧！', `MaleText_loc5`='拋開充滿戰爭和苦工勞役的生活，在元素之中重獲新生，然後在新世界中取得你應有的正當地位!', `MaleText_loc7`='¡Abandonen sus vidas de guerras y trabajos rutinarios! ¡Renazcan como elementos y reclamen su lugar en el nuevo mundo!', `FemaleText_loc1`='전쟁으로 얼룩진 이 지긋지긋한 삶을 던져 버리고, 새로운 세상에서 정령으로 다시 태어나 우리의 마땅한 권리를 누리는 거요!', `FemaleText_loc4`='抛弃战斗和苦役的生活，在元素中重生，在新世界中取得你的一席之地吧！', `FemaleText_loc5`='拋開充滿戰爭和苦工勞役的生活，在元素之中重獲新生，然後在新世界中取得你應有的正當地位!', `FemaleText_loc7`='¡Abandonen sus vidas de guerras y trabajos rutinarios! ¡Renazcan como elementos y reclamen su lugar en el nuevo mundo!' WHERE `ID`=39391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 이 쓸모없는 깡통 녀석들, 한번 시작해 볼까?', `MaleText_loc4`='好啊，你真有让机器起死回生的能力。让我们开始工作吧！', `MaleText_loc5`='好呀，你們這堆歪七扭八的破銅爛鐵，開始幹活啦!', `MaleText_loc7`='Muy bien, montón de chatarra inútil, ¡a trabajar!' WHERE `ID`=39392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 왜 당신을 믿어야 돼?', `MaleText_loc4`='为什么我们要相信你？', `MaleText_loc5`='憑什麼要我們相信你?', `MaleText_loc7`='¿Por qué deberíamos creerte?', `FemaleText_loc1`='우리가 왜 당신을 믿어야 되죠?', `FemaleText_loc4`='为什么我们要相信你？', `FemaleText_loc5`='憑什麼要我們相信你?', `FemaleText_loc7`='¿Por qué deberíamos creerte?' WHERE `ID`=39393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일동, 차렷, 경례!', `MaleText_loc4`='好了，新兵们，敬礼！', `MaleText_loc5`='來吧，新兵，敬禮!', `MaleText_loc7`='¡Bien, reclutas, saluden!' WHERE `ID`=39394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고함 일발 장전, 발사!', `MaleText_loc4`='让我听听你们的战吼！', `MaleText_loc5`='讓我聽聽你們的戰吼聲!', `MaleText_loc7`='¡Quiero oír ese rugido de batalla!' WHERE `ID`=39395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음엔 세상이 멸망한다고 하더니, 이제는 걱정할 거 없다니? 이건 무슨 꿍꿍이지?', `MaleText_loc4`='你告诉我们这个世界就要毁灭了。现在你却又对我们说不必担心。你到底要干什么？', `MaleText_loc5`='一開始你告訴我們說，這世界要毀滅了，現在你又告訴我們別擔心。這是哪門子的騙術?', `MaleText_loc7`='Primero anuncias que se acerca el fin del mundo y ahora nos dices que no nos preocupemos. ¿Qué ardid es este?', `FemaleText_loc1`='처음엔 세상이 멸망한다고 하더니, 이제는 걱정할 거 없다니? 이건 무슨 꿍꿍이지?', `FemaleText_loc4`='你告诉我们这个世界就要毁灭了。现在你却又对我们说不必担心。你到底要干什么？', `FemaleText_loc5`='一開始你告訴我們說，這世界要毀滅了，現在你又告訴我們別擔心。這是哪門子的騙術?', `FemaleText_loc7`='Primero anuncias que se acerca el fin del mundo y ahora nos dices que no nos preocupemos. ¿Qué ardid es este?' WHERE `ID`=39396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그동안 폭력과 고통을 너무 많이 겪어왔지. 내게 좋은 해결책이 하나 있다. 바로 네놈이 내 앞에서 그냥 도망치는 것이다.', `MaleText_loc4`='这里有太多的暴力，太多的痛苦。但我也会在这里得到光荣。离开我吧。', `MaleText_loc5`='有太多的暴力，太多的痛苦。但我可以光榮地妥協，只要走掉就好了。', `MaleText_loc7`='Ha habido demasiada violencia. Demasiado dolor. Pero tengo una solución honorable. Vete.' WHERE `ID`=39397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 실망이군. 너는 내가 겪은 전쟁의 참화를 또다시 불러일으켰다.', `MaleText_loc4`='我非常非常失望。你让我不得不再次放开我的战争之犬。', `MaleText_loc5`='我非常的失望。你再次地讓我放出了我的戰狗們。', `MaleText_loc7`='Estoy profundamente decepcionado. Una vez más me haces liberar a los canes de guerra.' WHERE `ID`=39398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 조잡한 방법이군.', `MaleText_loc4`='真是个可怜的计划。', `MaleText_loc5`='真是個殘破的計畫。', `MaleText_loc7`='Qué plan más endeble.' WHERE `ID`=39399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 선고단의 계속된 희생과 그대 같은 영웅들 덕에 최후의 승리가 눈앞으로 다가왔다. 이제 스컬지에 대항하여 싸우는 이들을 돕고자 얼음왕관 성채로 왔노라. 우리는 함께 리치 왕의 포악한 압제를 끝장낼 것이다!', `MaleText_loc4`='灰烬审判军和像你一样的英雄们以惨重的牺牲为代价，终于接近了最终的胜利。现在，我来到冰冠堡垒，帮助所有对抗天灾军团的勇士们。我们将并肩作战，结束巫妖王的暴行！', `MaleText_loc5`='灰燼裁決軍持續的犧牲和像你這樣的英雄一起把我們帶領到最終勝利的邊緣。現在我來到冰冠城塞來提供幫助給和天譴軍作戰的人們。只要齊心合力，我們就能終結巫妖王的暴行!', `MaleText_loc7`='El continuo sacrificio del Veredicto Cinéreo y de los héroes como tú nos acerca a todos a la victoria final. He venido a la Ciudadela de la Corona de Hielo para prestar mi ayuda a aquellos que luchan contra la Plaga. ¡Juntos acabaremos con la tiranía del Rey Exánime!' WHERE `ID`=39400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만 폐하, 이 일은 저희만으로도 해낼 수 있습니다.', `MaleText_loc4`='尊敬的殿下，我们能够完成这个任务。', `MaleText_loc5`='沒有不敬的意思，陛下，我們可以自己來完成。', `MaleText_loc7`='Con el debido respeto, alteza, podemos hacerlo solos.', `FemaleText_loc1`='죄송합니다만 폐하, 이 일은 저희만으로도 해낼 수 있어요.', `FemaleText_loc4`='尊敬的殿下，我们能够完成这个任务。', `FemaleText_loc5`='沒有不敬的意思，陛下，我們可以自己來完成。', `FemaleText_loc7`='Con el debido respeto, alteza, podemos hacerlo solos.' WHERE `ID`=39401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 일을 그대들의 힘만으로 해낼 수 있다고 했나? 단순히 멍청한 건가, 아니면 근거 없는 자신감인가?

그대들의 눈빛을 보아하니 아니라는 걸 알겠다. 이건 알아두어라. 이 일을 도움 없이 해낼 수 있음을 증명해야 한다. 잘 알겠다. 그대가 원한다면 전장에서 물러나겠다.', `MaleText_loc4`='你一个人就行？你是傻了？还是自信过度？

当然，我能在你的眼睛里看到取胜的决心。不过你需要用实力来证明自己。好吧，如果你想要这样，我会从战场上撤退。', `MaleText_loc5`='你說，你可以自己完成?我看到的是純粹的愚蠢還是盲目的自信?

不，我可以從你的眼中看出來。你想要知道，想要證明你可以獨力完成。很好。如果這是你的請求，我會從戰場上撤離。', `MaleText_loc7`='¿Dicen que pueden hacerlo solos? ¿Esto que veo ante mí es pura necedad o confianza infundada?

No, lo veo en sus ojos. Tienen que saber. Tienen que demostrar que pueden hacerlo solos. Bien. Me retiraré del campo de batalla si así lo desean.' WHERE `ID`=39402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='춤 일발 장전, 발사!', `MaleText_loc4`='跳舞吧！', `MaleText_loc5`='現在呢,跳舞!', `MaleText_loc7`='¡Ahora, a bailar!' WHERE `ID`=39403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너희들을 제대로 된 군인으로 만들어 주마!', `MaleText_loc4`='我要让你们知道该如何成为一名真正的士兵！', `MaleText_loc5`='我會讓你知道怎樣才能成為一名合格的士兵!', `MaleText_loc7`='¡Les voy a enseñar lo que hay que tener para ser un verdadero soldado!' WHERE `ID`=39404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나 주셨으면 합니다, 폐하.', `MaleText_loc4`='我们恳请您解除戒备，陛下。', `MaleText_loc5`='我們的確希望你退出，陛下。', `MaleText_loc7`='Preferimos que te retires, alteza.', `FemaleText_loc1`='물러나 주셨으면 해요, 폐하.', `FemaleText_loc4`='我们恳请您解除戒备，陛下。', `FemaleText_loc5`='我們的確希望你退出，陛下。', `FemaleText_loc7`='Preferimos que te retires, alteza.' WHERE `ID`=39405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕을 무찌르려면 용기 이상의 무언가가 필요하리라. 행운을 빈다.', `MaleText_loc4`='要击败巫妖王，你需要的将不止是勇气。祝你好运。', `MaleText_loc5`='你想打敗巫妖王光靠勇氣是不夠的。祝你好運吧。', `MaleText_loc7`='Os hará falta algo más que coraje para derrotar al Rey Exánime. Buena suerte.' WHERE `ID`=39406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택한 대로 해 주겠다. 스스로 선택했으니 죽고 사는 것은 이제 네게 달렸다.', `MaleText_loc4`='你已经做出了选择。至于是生是死，就只能靠你自己了。', `MaleText_loc5`='你已經做出選擇了。因這個選擇而生或死就看你了。', `MaleText_loc7`='Habéis tomado una decisión. Ahora os corresponde vivir o morir por ella.' WHERE `ID`=39407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행하는 동안 즐거웠기를 바란다. 이만 가겠노라!', `MaleText_loc4`='希望你会喜欢这种旅行方式，我要出去了！', `MaleText_loc5`='希望你享受騎乘的過程，我先閃了!', `MaleText_loc7`='Espero que hayas disfrutado del viaje, ¡yo me voy!' WHERE `ID`=39408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다시 태어날래. 어떻게 하면 되는지 알려줘!', `MaleText_loc4`='我想要得到重生，告诉我要怎样做吧！', `MaleText_loc5`='我想獲得新生。告訴我，我該怎麼做!', `MaleText_loc7`='Yo quiero renacer. ¡Dime qué tengo que hacer!', `FemaleText_loc1`='난 다시 태어날래. 어떻게 하면 되는지 알려줘요!', `FemaleText_loc4`='我想要得到重生，告诉我要怎样做吧！', `FemaleText_loc5`='我想獲得新生。告訴我，我該怎麼做!', `FemaleText_loc7`='Yo quiero renacer. ¡Dime qué tengo que hacer!' WHERE `ID`=39409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 알려줘!', `MaleText_loc4`='是的，告诉我们！', `MaleText_loc5`='是呀，告訴我們!', `MaleText_loc7`='Sí, ¡dínoslo!', `FemaleText_loc1`='그래요, 알려줘요!', `FemaleText_loc4`='是的，告诉我们！', `FemaleText_loc5`='是呀，告訴我們!', `FemaleText_loc7`='Sí, ¡dínoslo!' WHERE `ID`=39410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 신호를 주면, 목이 찢어져라 커다란 고함을 지른다!', `MaleText_loc4`='我一发出信号，你们就用最大的力气吼叫！', `MaleText_loc5`='我一下令，就發出你最響亮的怒吼!', `MaleText_loc7`='Cuando dé la señal, quiero oír su rugido de batalla más feroz!' WHERE `ID`=39411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽기 싫어!', `MaleText_loc4`='我不想死！', `MaleText_loc5`='我不想死!', `MaleText_loc7`='¡No quiero morir!', `FemaleText_loc1`='난 죽기 싫어!', `FemaleText_loc4`='我不想死！', `FemaleText_loc5`='我不想死!', `FemaleText_loc7`='¡No quiero morir!' WHERE `ID`=39412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 신호를 주면 절도 있는 경례로 너희들의 군인 정신을 보여 준다!', `MaleText_loc4`='听我的命令，敬一个标准的军礼，让我看看你们的纪律！', `MaleText_loc5`='當我下令的時候，就適當地敬個禮，讓我看看你的紀律!', `MaleText_loc7`='¡Demuéstrenme que tienen disciplina saludando cuando se los ordene!' WHERE `ID`=39413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정들 하시오, 친구여. 질문에 대답할 시간은 충분하오.', `MaleText_loc4`='镇定，朋友们。你们的问题都会得到解答，不必着急。', `MaleText_loc5`='冷靜點，朋友。有很多時間可以慢慢回答你的問題。', `MaleText_loc7`='Tranquilos, amigos míos. Habrá mucho tiempo para responder a todas sus preguntas.', `FemaleText_loc1`='진정들 하시오, 친구여. 질문에 대답할 시간은 충분하오.', `FemaleText_loc4`='镇定，朋友们。你们的问题都会得到解答，不必着急。', `FemaleText_loc5`='冷靜點，朋友。有很多時間可以慢慢回答你的問題。', `FemaleText_loc7`='Tranquilos, amigos míos. Habrá mucho tiempo para responder a todas sus preguntas.' WHERE `ID`=39414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀드린 대로입니다. 리치 왕은 저희 손으로 처치하겠습니다!', `MaleText_loc4`='我们言出如山，巫妖王必将败倒在我们脚下！', `MaleText_loc5`='話已經說出口了。巫妖王將會死在我們的手上!', `MaleText_loc7`='Está decidido. ¡El Rey Exánime morirá por nuestra mano!', `FemaleText_loc1`='말씀드린 대로에요. 리치 왕은 저희 손으로 처치하겠어요!', `FemaleText_loc4`='我们言出如山，巫妖王必将败倒在我们脚下！', `FemaleText_loc5`='話已經說出口了。巫妖王將會死在我們的手上!', `FemaleText_loc7`='Está decidido. ¡El Rey Exánime morirá por nuestra mano!' WHERE `ID`=39415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 대군주님, 노스렌드에 주의를 기울여주십시오. 리치 왕과 그의 부하들은 대군주님의 도움 없이 저희 힘으로 처리하겠습니다.', `MaleText_loc4`='诺森德的战事需要你的关注，地狱咆哮统帅。没有你的力量，我们也将去讨伐巫妖王和他的爪牙。', `MaleText_loc5`='北裂境需要你的守護，霸主地獄吼。我們可以自己解決掉巫妖王和他的嘍囉。', `MaleText_loc7`='Rasganorte requiere tu atención, Señor supremo Grito Infernal. Nos encargaremos del Rey Exánime y sus esbirros sin tu ayuda.', `FemaleText_loc1`='헬스크림 대군주님, 노스렌드에 주의를 기울여주세요. 리치 왕과 그의 부하들은 대군주님의 도움 없이 저희 힘으로 처리하겠어요.', `FemaleText_loc4`='诺森德的战事需要你的关注，地狱咆哮统帅。没有你的力量，我们也将去讨伐巫妖王和他的爪牙。', `FemaleText_loc5`='北裂境需要你的守護，霸主地獄吼。我們可以自己解決掉巫妖王和他的嘍囉。', `FemaleText_loc7`='Rasganorte requiere tu atención, Señor supremo Grito Infernal. Nos encargaremos del Rey Exánime y sus esbirros sin tu ayuda.' WHERE `ID`=39416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 얼음왕관 성채 안에 있는 전쟁노래 공격대와 함께라면, 승리는 우리 손안에 있다! 리치 왕을 처치하고 호드에 영광을 안기리라!', `MaleText_loc4`='战歌远征军已经到达冰冠堡垒。胜利就在眼前！巫妖王的惨败将成为部落新的荣耀！', `MaleText_loc5`='有了戰歌進攻部隊在冰冠城塞，勝利就在我們的指掌之間!巫妖王的滅亡將會替部落帶來榮耀!', `MaleText_loc7`='¡Ahora que la Ofensiva Grito de Guerra está en la Ciudadela de la Corona de Hielo, la victoria está a nuestro alcance! ¡La muerte del Rey Exánime dará gloria a la Horda!' WHERE `ID`=39417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁노래 공격대의 힘을 거절한다고? 전투가 너무 치열해서 돌아버린 것 아닌가? 도움을 받는다면, 이미 승리한 것이나 다름없는데! 내 도움이 없이는 어려운 싸움을 할 걸세.', `MaleText_loc4`='你拒绝战歌远征军的协助？难道战争让你的脑子烧坏了吗？有我的帮助，胜利的果实就唾手可得！如果没有我，那么你将面临极为困难的战局。', `MaleText_loc5`='你拒絕戰歌進攻部隊強力的幫助?混亂的戰鬥把你搞瘋了嗎?有了我的幫助，勝利唾手可得!沒有我的幫助，你的戰鬥將會十分艱辛。', `MaleText_loc7`='¿Declináis el poder de la Ofensiva Grito de Guerra? ¿Acaso el caos de la batalla os ha arrebatado la cordura? ¡Con mi ayuda, la victoria está a nuestro alcance! Sin ella, la lucha será difícil.' WHERE `ID`=39418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에 영광을!', `MaleText_loc4`='荣耀属于部落！', `MaleText_loc5`='為了部落的榮耀!', `MaleText_loc7`='¡Gloria a la Horda!' WHERE `ID`=39419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 이야기에 관심이 있으시오? 앞으로 집회를 열 예정이요. 더 알고 싶은 자들은 나와 대화를 나눕시다. 하지만 조심하시오. 오그리마는 진실을 감추려는 자들로 가득하니.', `MaleText_loc4`='我将要召集对我们的使命感兴趣的人。如果你想知道得更多，就和我谈谈吧。奥格瑞玛里对现实保持沉默的人太多了。', `MaleText_loc5`='假如你對我們傳佈的訊息有興趣，我將會舉辦一次集會。如果你想多了解一些，來和我聊聊，不過要注意，奧格瑪裡到處都是想要消滅真理之音的人。', `MaleText_loc7`='Si estáis interesados en nuestro mensaje, voy a celebrar una reunión. Hablad conmigo si deseáis saber más, pero tened cuidado porque mucha gente en Orgrimmar desearía silenciar la verdad.', `FemaleText_loc1`='우리의 이야기에 관심이 있으시오? 앞으로 집회를 열 예정이요. 더 알고 싶은 자들은 나와 대화를 나눕시다. 하지만 조심하시오. 오그리마는 진실을 감추려는 자들로 가득하니.', `FemaleText_loc4`='我将要召集对我们的使命感兴趣的人。如果你想知道得更多，就和我谈谈吧。奥格瑞玛里对现实保持沉默的人太多了。', `FemaleText_loc5`='假如你對我們傳佈的訊息有興趣，我將會舉辦一次集會。如果你想多了解一些，來和我聊聊，不過要注意，奧格瑪裡到處都是想要消滅真理之音的人。', `FemaleText_loc7`='Si estáis interesados en nuestro mensaje, voy a celebrar una reunión. Hablad conmigo si deseáis saber más, pero tened cuidado porque mucha gente en Orgrimmar desearía silenciar la verdad.' WHERE `ID`=39420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 능력을 증명해 보이겠습니다!', `MaleText_loc4`='我会证明我自己的！', `MaleText_loc5`='我會證明自己的!', `MaleText_loc7`='¡Demostraré lo que valgo!', `FemaleText_loc1`='제 능력을 증명해 보이겠어요!', `FemaleText_loc4`='我会证明我自己的！', `FemaleText_loc5`='我會證明自己的!', `FemaleText_loc7`='¡Demostraré lo que valgo!' WHERE `ID`=39421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 이 순간을 위해 훈련해 왔습니다!', `MaleText_loc4`='为了这一刻，我已经接受了许多年的训练！', `MaleText_loc5`='為了這一刻我已經準備了好幾年!', `MaleText_loc7`='¡Me he estado entrenando para esto durante años!', `FemaleText_loc1`='오랫동안 이 순간을 위해 훈련해 왔어요!', `FemaleText_loc4`='为了这一刻，我已经接受了许多年的训练！', `FemaleText_loc5`='為了這一刻我已經準備了好幾年!', `FemaleText_loc7`='¡Me he estado entrenando para esto durante años!' WHERE `ID`=39422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결심이 단단히 섰군! 영광과 명예를 바라는 자네의 열망을 존중하네. 명예롭게 죽을 수 있기를 빌어주겠네, $n!', `MaleText_loc4`='你的选择很勇敢！而你对荣耀和功业的欲望也值得尊敬！光荣地去死吧，$n！', `MaleText_loc5`='你的選擇十分大膽。我尊重你追求榮耀的渴望!希望你能死得其所，$n!', `MaleText_loc7`='¡Una brava decisión! ¡Respeto sus ansias de gloria y honor! ¡Mueran bien, $n!' WHERE `ID`=39423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하지 않겠습니다!', `MaleText_loc4`='我不会失败！', `MaleText_loc5`='我不會失敗的!', `MaleText_loc7`='¡No fallaré!', `FemaleText_loc1`='실패하지 않을 거예요!', `FemaleText_loc4`='我不会失败！', `FemaleText_loc5`='我不會失敗的!', `FemaleText_loc7`='¡No fallaré!' WHERE `ID`=39424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 이름으로 승리하겠습니다!', `MaleText_loc4`='我会以他们的名义取得胜利！', `MaleText_loc5`='我會以「他們」之名歡慶勝利!', `MaleText_loc7`='¡Triunfaré en su nombre!', `FemaleText_loc1`='그들의 이름으로 승리할 거예요!', `FemaleText_loc4`='我会以他们的名义取得胜利！', `FemaleText_loc5`='我會以「他們」之名歡慶勝利!', `FemaleText_loc7`='¡Triunfaré en su nombre!' WHERE `ID`=39425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련은 충분히 했습니다! 이제 실전입니다!', `MaleText_loc4`='训练已经够多了！现在是行动的时刻！', `MaleText_loc5`='演講完畢!開始行動!', `MaleText_loc7`='¡Basta de lecciones! ¡Es la hora de la acción!', `FemaleText_loc1`='훈련은 충분히 했어요! 이제 실전입니다!', `FemaleText_loc4`='训练已经够多了！现在是行动的时刻！', `FemaleText_loc5`='演講完畢!開始行動!', `FemaleText_loc7`='¡Basta de lecciones! ¡Es la hora de la acción!' WHERE `ID`=39426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 오늘 여기서 죽지 않을 것입니다!', `MaleText_loc4`='今天我不会死在这里，怪物！', `MaleText_loc5`='我不會死於今天，低等動物!', `MaleText_loc7`='¡No moriré aquí hoy, bicho!', `FemaleText_loc1`='저는 오늘 여기서 죽지 않을 거예요!', `FemaleText_loc4`='今天我不会死在这里，怪物！', `FemaleText_loc5`='我不會死於今天，低等動物!', `FemaleText_loc7`='¡No moriré aquí hoy, bicho!' WHERE `ID`=39427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우렁찬 환호로 전투 중인 동료 병사들에게 용기를 북돋아 주는 거다. 자, 내가 신호를 하면 나를 향해 환호한다!', `MaleText_loc4`='你们还要懂得在战场上用欢呼激励你们的同袍。现在，听我的命令，发出欢呼！', `MaleText_loc5`='在戰鬥中要以響亮的鼓舞聲激勵同伴。我叫你這樣做的時候，給我個激昂的鼓舞!', `MaleText_loc7`='¡En la batalla, deben recompensar a sus compañeros soldados con grande ánimos. ¡Ahora anímenme cuando se los ordene!' WHERE `ID`=39428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 신호를 주면 제군들은 승리를 축하하는 최고의 춤을 춘다!', `MaleText_loc4`='我一发出信号，就给我跳出最漂亮的胜利舞蹈！', `MaleText_loc5`='我一下令，就跳出你最棒的勝利之舞!', `MaleText_loc7`='¡Cuando dé la señal quiero que me enseñen su mejor baile de la victoria!' WHERE `ID`=39429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어!', `MaleText_loc4`='干得好！', `MaleText_loc5`='做得好!', `MaleText_loc7`='¡Buen trabajo!' WHERE `ID`=39430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와우, 멋져. 무시무시한데!', `MaleText_loc4`='喔，真是惊人啊！', `MaleText_loc5`='哇喔，很好很好，夠嚇人了!', `MaleText_loc7`='¡Guau, desde luego da miedo!' WHERE `ID`=39431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환상적이야!', `MaleText_loc4`='太棒了！', `MaleText_loc5`='棒呆了!', `MaleText_loc7`='¡Fantástico!' WHERE `ID`=39432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고야!', `MaleText_loc4`='漂亮极了！', `MaleText_loc5`='非常好!', `MaleText_loc7`='¡Magnífico!' WHERE `ID`=39433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 제군들은 내가 만나 본 최고의 훈련생일지도 모르겠군. 자, 반복 훈련이다. 처음부터 다시!', `MaleText_loc4`='你们是我见过的最优秀的新兵！我们很快就会再次开始演习了。', `MaleText_loc5`='你們大概是我所見過的最有潛力的新人了!咱們再從頭來一次吧!', `MaleText_loc7`='¡Quizá sean los mejores reclutas que he visto! ¡Repasémoslo todo de nuevo!' WHERE `ID`=39434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아아!', `MaleText_loc4`='啊啊！！', `MaleText_loc5`='啊～～～～～～', `MaleText_loc7`='¡¡Aaaaaaaaargggh!!', `FemaleText_loc1`='으아아아아아아!', `FemaleText_loc4`='啊啊！！', `FemaleText_loc5`='啊～～～～～～', `FemaleText_loc7`='¡¡Aaaaaaaaargggh!!' WHERE `ID`=39435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 하나가 되었다! 불과... 하아아아아! 뜨겁다아아!!!', `MaleText_loc4`='我已经和火焰融为一体！我已经……啊！！！真热啊！！！', `MaleText_loc5`='我與火焰合而為一!我已經...哇啊啊啊!!!高溫的灼熱!!!', `MaleText_loc7`='¡Soy uno con el fuego! Soy... ¡Aaagggh! ¡Queeemaaa!', `FemaleText_loc1`='불과 하나가 되었다! 불과... 하아아아아! 뜨겁다아아!!!', `FemaleText_loc4`='我已经和火焰融为一体！我已经……啊！！！真热啊！！！', `FemaleText_loc5`='我與火焰合而為一!我已經...哇啊啊啊!!!高溫的灼熱!!!', `FemaleText_loc7`='¡Soy una con el fuego! Soy... ¡Aaagggh! ¡Queeemaaa!' WHERE `ID`=39436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체는 나약하다! 오직 불로만 깨끗이 씻을 수 있다!', `MaleText_loc4`='肉体是软弱的！必须被火焰净化！', `MaleText_loc5`='血肉是脆弱的!只有火焰能進行淨化!', `MaleText_loc7`='¡La carne es débil! ¡Solo el fuego purifica!', `FemaleText_loc1`='육체는 나약하다! 오직 불로만 깨끗이 씻을 수 있다!', `FemaleText_loc4`='肉体是软弱的！必须被火焰净化！', `FemaleText_loc5`='血肉是脆弱的!只有火焰能進行淨化!', `FemaleText_loc7`='¡La carne es débil! ¡Solo el fuego purifica!' WHERE `ID`=39437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 날, 배고픈 늑대가 먹을 것을 찾아 동쪽으로 달려갔다네.', `MaleText_loc4`='有一天，孤狼饿坏了。他向东跑去，寻找食物。', `MaleText_loc5`='有一天，狼感到非常饑餓，所以牠跑向東方尋找食物。', `MaleText_loc7`='Un día al lobo le entró mucha hambre, así que corrió hacia el este para buscar comida.', `FemaleText_loc1`='어느 날, 배고픈 늑대가 먹을 것을 찾아 동쪽으로 달려갔다네.', `FemaleText_loc4`='有一天，孤狼饿坏了。他向东跑去，寻找食物。', `FemaleText_loc5`='有一天，狼感到非常饑餓，所以牠跑向東方尋找食物。', `FemaleText_loc7`='Un día al lobo le entró mucha hambre, así que corrió hacia el este para buscar comida.' WHERE `ID`=39438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이윽고 늑대는 서로 싸우는 코도 두 마리를 발견했다네.$b영리한 늑대는, 한쪽이 쓰러질 때까지 기다리기로 했지.', `MaleText_loc4`='他遇到了两头正在打斗的科多兽。$b聪明的孤狼决定等待他们两败俱伤。', `MaleText_loc5`='牠碰到了兩隻正在爭鬥的科多獸。$b狼很聰明的決定等一隻擊敗另一隻。', `MaleText_loc7`='Se encontró con un par de kodos que se estaban peleando.$b$bComo era muy listo, el lobo decidió esperar a que uno matara al otro.', `FemaleText_loc1`='이윽고 늑대는 서로 싸우는 코도 두 마리를 발견했다네.$b영리한 늑대는, 한쪽이 쓰러질 때까지 기다리기로 했지.', `FemaleText_loc4`='他遇到了两头正在打斗的科多兽。$b聪明的孤狼决定等待它们之中的一个被打倒。', `FemaleText_loc5`='牠碰到了兩隻正在爭鬥的科多獸。$b狼很聰明的決定等一隻擊敗另一隻。', `FemaleText_loc7`='Se encontró con un par de kodos que se estaban peleando.$b$bComo era muy listo, el lobo decidió esperar a que uno matara al otro.' WHERE `ID`=39439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 코도가 죽자, 늑대는 그 고기를 먹으려고 달려들었어.', `MaleText_loc4`='当较软弱的科多兽死亡的时候，孤狼走上前，要吃掉它。', `MaleText_loc5`='當較弱的科多獸死掉時，狼接近了牠並想把牠給吃了。', `MaleText_loc7`='Cuando el kodo más débil murió, el lobo se acercó y trató de comérselo.', `FemaleText_loc1`='약한 코도가 죽자, 늑대는 그 고기를 먹으려고 달려들었어.', `FemaleText_loc4`='当较软弱的科多兽死亡的时候，孤狼走上前，要吃掉它。', `FemaleText_loc5`='當較弱的科多獸死掉時，狼接近了牠並想把牠給吃了。', `FemaleText_loc7`='Cuando el kodo más débil murió, el lobo se acercó y trató de comérselo.' WHERE `ID`=39440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 코도는 성급하고 제멋대로인 늑대에게 화가 났지.$b그래서 늑대가 먹이를 입에 물기도 전에 재빨리 죽여 버렸다네.', `MaleText_loc4`='另一头科多兽被孤狼激怒了。$b孤狼还没有来得及尝一口鲜肉，就被它杀掉了。', `MaleText_loc5`='另外一隻科多獸對狼的莽撞感到憤怒，$b在牠要進食前輕鬆地將牠殺了。', `MaleText_loc7`='El kodo restante, enfadado por el ímpetu del lobo, lo mató rápidamente antes de que tuviera tiempo de comer.', `FemaleText_loc1`='남은 코도는 성급하고 제멋대로인 늑대에게 화가 났지.$b그래서 늑대가 먹이를 입에 물기도 전에 재빨리 죽여 버렸다네.', `FemaleText_loc4`='另一头科多兽被孤狼激怒了。$b孤狼还没有来得及尝一口鲜肉，就被它杀掉了。', `FemaleText_loc5`='另外一隻科多獸對狼的莽撞感到憤怒，$b在牠要進食前輕鬆地將牠殺了。', `FemaleText_loc7`='El kodo restante, enfadado por el ímpetu del lobo, lo mató rápidamente antes de que tuviera tiempo de comer.' WHERE `ID`=39441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때는 지금보다 상황이 훨씬 좋았는데... 대체 우리에게 무슨 일이 일어난 거지?', `MaleText_loc4`='以前的情形要比现在好得多……我们到底出了什么事？', `MaleText_loc5`='本來一切都好好的...我們發生了什麼事?', `MaleText_loc7`='Antes todo era mucho mejor... ¿Qué nos ha pasado?' WHERE `ID`=39442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신, 우화를 들려 주시겠습니까?', `MaleText_loc4`='希恩，能给我讲讲你的预言吗？', `MaleText_loc5`='小新，可以告訴我你的傳說嗎?', `MaleText_loc7`='¿Puedes contarme tu fábula, Shin?', `FemaleText_loc1`='신, 우화를 들려 주시겠어요?', `FemaleText_loc4`='希恩，能给我讲讲你的预言吗？', `FemaleText_loc5`='小新，可以告訴我你的傳說嗎?', `FemaleText_loc7`='¿Puedes contarme tu fábula, Shin?' WHERE `ID`=39443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 쉽게 배를 채울 건수를 찾아 달리고 또 달렸어.', `MaleText_loc4`='孤狼跑啊跑，寻找容易到口的食物。', `MaleText_loc5`='狼不斷地跑，尋找著弱小的獵物。', `MaleText_loc7`='El lobo corrió y corrió, en busca de una comida fácil.', `FemaleText_loc1`='늑대는 쉽게 배를 채울 건수를 찾아 달리고 또 달렸어.', `FemaleText_loc4`='孤狼跑啊跑，寻找容易到口的食物。', `FemaleText_loc5`='狼不斷地跑，尋找著弱小的獵物。', `FemaleText_loc7`='El lobo corrió y corrió, en busca de una comida fácil.' WHERE `ID`=39444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 코도 고기가 먹고 싶었지.', `MaleText_loc4`='他渴望着科多兽的肉。', `MaleText_loc5`='他渴望著科多獸的肉。', `MaleText_loc7`='Le apetecía carne de kodo.', `FemaleText_loc1`='늑대는 코도 고기가 먹고 싶었지.', `FemaleText_loc4`='他渴望着科多兽的肉。', `FemaleText_loc5`='他渴望著科多獸的肉。', `FemaleText_loc7`='Le apetecía carne de kodo.' WHERE `ID`=39445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 게을렀기 때문에, 먹이를 애써 사냥하고 싶지 않았다네.', `MaleText_loc4`='孤狼很懒，不想为取得食物而努力。', `MaleText_loc5`='懶惰的狼，不肯為食物努力。', `MaleText_loc7`='El lobo era perezoso y no quería trabajar para conseguir su comida.', `FemaleText_loc1`='늑대는 게을렀기 때문에, 먹이를 애써 사냥하고 싶지 않았다네.', `FemaleText_loc4`='孤狼很懒，不想为取得食物而努力。', `FemaleText_loc5`='懶惰的狼，不肯為食物努力。', `FemaleText_loc7`='El lobo era perezoso y no quería trabajar para conseguir su comida.' WHERE `ID`=39446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달리면 달릴수록, 배가 고파졌어.', `MaleText_loc4`='他跑得越远，他的肚子就叫得越响。', `MaleText_loc5`='他越跑，他肚子叫的聲音就越大。', `MaleText_loc7`='Cuanto más corría, más le rugía el estómago.', `FemaleText_loc1`='달리면 달릴수록, 배가 고파졌어.', `FemaleText_loc4`='他跑得越远，他的肚子就叫得越响。', `FemaleText_loc5`='他越跑，他肚子叫的聲音就越大。', `FemaleText_loc7`='Cuanto más corría, más le rugía el estómago.' WHERE `ID`=39447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 랩터 고기는 거들떠도 보지 않았다네.', `MaleText_loc4`='孤狼不喜欢恐龙肉。', `MaleText_loc5`='狼不考慮迅猛龍的肉。', `MaleText_loc7`='Al lobo no le gustaba la carne de raptor.', `FemaleText_loc1`='늑대는 랩터 고기는 거들떠도 보지 않았다네.', `FemaleText_loc4`='孤狼不喜欢恐龙肉。', `FemaleText_loc5`='狼不考慮迅猛龍的肉。', `FemaleText_loc7`='Al lobo no le gustaba la carne de raptor.' WHERE `ID`=39448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전갈 살점은 너무 쓸 것 같았지.', `MaleText_loc4`='蝎子肉对他来说太苦了。', `MaleText_loc5`='狼認為蠍子的肉太苦了。', `MaleText_loc7`='Al lobo le parecía que la carne de escórpido era demasiado amarga.', `FemaleText_loc1`='전갈 살점은 너무 쓸 것 같았지.', `FemaleText_loc4`='蝎子肉对他来说太苦了。', `FemaleText_loc5`='狼認為蠍子的肉太苦了。', `FemaleText_loc7`='Al lobo le parecía que la carne de escórpido era demasiado amarga.' WHERE `ID`=39449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧돼지 고기는 지겨웠어.', `MaleText_loc4`='孤狼也吃腻了野猪肉。', `MaleText_loc5`='狼已經吃膩了野豬肉。', `MaleText_loc7`='El lobo se había cansado de comer carne de jabalí.', `FemaleText_loc1`='멧돼지 고기는 지겨웠어.', `FemaleText_loc4`='孤狼也吃腻了野猪肉。', `FemaleText_loc5`='狼已經吃膩了野豬肉。', `FemaleText_loc7`='El lobo se había cansado de comer carne de jabalí.' WHERE `ID`=39450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 먹잇감을 찾아 듀로타의 사막을 샅샅이 뒤졌어.', `MaleText_loc4`='他在杜隆塔尔的沙丘上搜寻着猎物。', `MaleText_loc5`='他在杜洛塔的土地上奔跑，獵殺他的食物。', `MaleText_loc7`='Recorrió las arenas de Durotar, dando caza a su presa.', `FemaleText_loc1`='늑대는 먹잇감을 찾아 듀로타의 사막을 샅샅이 뒤졌어.', `FemaleText_loc4`='他在杜隆塔尔的沙丘上搜寻着猎物。', `FemaleText_loc5`='他在杜洛塔的土地上奔跑，獵殺他的食物。', `FemaleText_loc7`='Recorrió las arenas de Durotar, dando caza a su presa.' WHERE `ID`=39451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='강물을 헤치느라 피곤해졌네. 좀 쉽게 가 보지 않겠나? 물의 정령이여, 와서 우리를 도우라!', `FemaleText_loc4`='我已经厌倦在水里跋涉了。让我们给自己找点儿便利吧，好吗？流水之灵，快来帮助我们！', `FemaleText_loc5`='我已經厭煩在水中跋涉了。讓我們對自己好一點吧，怎樣?水靈，助我一臂之力!', `FemaleText_loc7`='Estoy cansada de chapotear por el agua. Vamos a hacernos la vida un poco más fácil, ¿te parece? ¡Espíritu del agua, ven en nuestra ayuda!' WHERE `ID`=39452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤가, 훨씬 낫지 않나?', `FemaleText_loc4`='瞧，这样不就好多了？', `FemaleText_loc5`='嗯，這不是好多了嗎?', `FemaleText_loc7`='Ya está. Mucho mejor, ¿no?' WHERE `ID`=39453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라가란, 난 무사하단다.', `FemaleText_loc4`='拉格兰，我安全了。', `FemaleText_loc5`='拉迦連，我安全了。', `FemaleText_loc7`='Raggaran, estoy a salvo.' WHERE `ID`=39454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할머니... 살아 계셨군요!', `MaleText_loc4`='主母……您还活着！', `MaleText_loc5`='監護總管...你還活著!', `MaleText_loc7`='Gran matrona... ¡Estás viva!' WHERE `ID`=39455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 가보세. 우리 손자 라가란에게 데려다 주게나.', `FemaleText_loc4`='那我们出发吧。带我去我的孙子拉格兰那里。', `FemaleText_loc5`='我們走吧，拉迦連。帶我到我孫子那。', `FemaleText_loc7`='Vale, vámonos. Llévame con mi nieto, Raggaran.' WHERE `ID`=39456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악! 내 발목! 이대로는 걸을 수 없을 듯한데... 여기까지 와서 이리되다니...', `FemaleText_loc4`='不！我——我的脚踝！我不确定自己是否能做到……我们已经走了这么远……', `FemaleText_loc5`='不!我的膝蓋!我不確定我是否還能堅持下去...我們都走了那麼遠了...', `FemaleText_loc7`='¡No! ¡M-mi tobillo! No sé si puedo hacerlo... Después de haber llegado hasta aquí...' WHERE `ID`=39457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람의 정령이여! 와서 나를 도우라!', `FemaleText_loc4`='空气之灵！快来帮我！', `FemaleText_loc5`='風之靈!助我一臂之力!', `FemaleText_loc7`='¡Espíritus del aire! ¡Venid en mi ayuda!' WHERE `ID`=39458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 계속 갈 수 있겠군. 이대로 가세.', `FemaleText_loc4`='我想我们现在可以继续了。继续前进。', `FemaleText_loc5`='我想我們現在可以繼續了。前進吧。', `FemaleText_loc7`='Creo que podemos continuar. Sigamos.' WHERE `ID`=39459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋으로 덧붙인 부가 장치가 너무나 많습니다!', `MaleText_loc4`='那么多零零碎碎的东西！', `MaleText_loc5`='好多鈴鐺和哨子!', `MaleText_loc7`='¡Cuántos controles!' WHERE `ID`=39460;
