UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 한 명, 많으면 두 명을 태울 수 있을 것 같습니다.', `MaleText_loc4`='看上去，它足以承载一名侏儒，也许还能承载两个。', `MaleText_loc5`='看起來剛好夠載一個地精。也許可以兩個。', `MaleText_loc7`='Parece lo suficientemente poderoso como para transportar un gnomo. Quizá dos.' WHERE `ID`=39463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남은 우리 종족은 전부 저 아래에 있어요!', `FemaleText_loc4`='我们其余所有人都在那下面！', `FemaleText_loc5`='我們其他的人全在下面那裡!!', `FemaleText_loc7`='¡Todos los que quedan de nuestro pueblo están aquí abajo!' WHERE `ID`=39464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데, 귀염둥이...?', `FemaleText_loc4`='可是，宝贝儿……？', `FemaleText_loc5`='但是，甜心...?', `FemaleText_loc7`='Pero, ¿cariño...?' WHERE `ID`=39465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막막하군. 대지모신께서만이 이 일의 원인을 아실지도 모르겠소. 하지만 우린 이번 일이 계속 되기 전에 조치해야만 하오.', `MaleText_loc4`='我迷惑了。也许只有大地之母本人才明白这一切的缘由。但我们必须设法阻止它……', `MaleText_loc5`='我已經一籌莫展了。大概只有大地之母她自己才知道起因。但我們必須做些什麼來應對...', `MaleText_loc7`='No sé nada. Quizá tan solo la Madre Tierra sepa la causa. Pero debemos hacer algo antes de que continúe...' WHERE `ID`=39466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 신실함이 감동적이구나, 드루이드여.', `FemaleText_loc4`='你的真诚很让人感动，德鲁伊。', `FemaleText_loc5`='你的誠懇令人感動，德魯伊。', `FemaleText_loc7`='Tu sinceridad es conmovedora, druida.' WHERE `ID`=39467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코누! 우리 뒤를 봐라! 나이트 엘프다.', `MaleText_loc4`='克努！我们身后！一个暗夜精灵。', `MaleText_loc5`='寇奴!我們後面!一個夜精靈。', `MaleText_loc7`='¡Konu! ¡Detrás de nosotros! ¡Un elfo de la noche!' WHERE `ID`=39468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저분은 나이트 엘프가 아니오... 나이트 엘프의 모습을 한 녹색용이오! 대지모신의 이름으로 제가...', `MaleText_loc4`='你不是暗夜精灵……这是绿龙的伪装！以大地之母的名义，我……', `MaleText_loc5`='你不是夜精靈...這是綠龍的偽裝!以大地之母之名，我...', `MaleText_loc7`='Tú no eres un elfo de la noche... ¡Esa es la apariencia de un dragón Verde! Por la Madre Tierra, yo...' WHERE `ID`=39469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 존경이나 경외심 따위를 받을 자격이 없도다, 드루이드여. 난 내 종족을 배신했다. 이 땅의 병폐는 내 잘못이다.', `FemaleText_loc4`='我不配受到如此尊重或敬仰，德鲁伊。我背叛了自己的土地。这片土地的疾患都是我的错。', `FemaleText_loc5`='我不值得受到這種尊敬，德魯伊。我是我們族人的叛徒。這片大地會生病是我害的。', `FemaleText_loc7`='No merezco tanto respeto ni reverencia, druida. He traicionado a mi gente. La enfermedad de esta tierra es culpa mía.' WHERE `ID`=39470;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 병폐는 에메랄드의 꿈에 나타난 악몽에서 나왔으며, 용 타에라가 이 세계에 퍼뜨렸다. 그는 그저 예전 자신의 미쳐버린 망령일 뿐이며, 이 땅이 삼켜지는 걸 보게 될 것이다.', `FemaleText_loc4`='疾患来自翡翠梦境内部的梦魇，巨龙泰拉尔对其进行了散播。现在的他就是从前自己的癫狂镜像，要亲眼看着这片土地被吞噬殆尽。', `FemaleText_loc5`='疾病是由翡翠夢境中的惡夢所產生的，而綠龍泰拉爾是散佈它的兇手。他現在只是他過去的發瘋了的暗影，想要的只有看到這片大地被吞噬。', `FemaleText_loc7`='La enfermedad ha nacido de la Pesadilla, dentro del Sueño Esmeralda, y el dragón Taerar la extiende. No queda de él más que una sombra de lo que fue y está loco, pero no parará hasta devorar esta tierra.' WHERE `ID`=39471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나 혼자서는 그를 감당할 수 없도다. 그에게 접근하려고만 해도 나를 엄습했던 타락을 겪는 위험을 또다시 감수해야 할 것이다.', `FemaleText_loc4`='我不敢亲自去面对他。仅是靠近他，就有让同样的腐化再次将我打倒的危险。', `FemaleText_loc5`='我無法獨自面對他。就連接近他都有可能會讓我再次遭受相同的腐化。', `FemaleText_loc7`='No puedo hacerle frente yo mismo. Incluso simplemente acercándome a él me arriesgaría a contagiarme con la corrupción una vez más.' WHERE `ID`=39472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 어떻게 해야 합니까?', `MaleText_loc4`='我们该怎么做？', `MaleText_loc5`='我們應該怎麼做?', `MaleText_loc7`='¿Qué debemos hacer?' WHERE `ID`=39473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지가 고통으로 눈물 흘리리라. 그 눈물을 모아서 세계수로 가는 차원문을 봉인하는 데 사용해라. 에메랄드의 꿈으로 가는 연결 고리를 반드시 끊어버려야 한다.', `FemaleText_loc4`='大地在因痛苦而啜泣。收集它的眼泪，用它们去封闭位于符印巨树的传送门。与梦境的联结必须被割断。', `FemaleText_loc5`='大地自己因為苦痛而在流淚。收集它的眼淚，使用它們來封印巨偉之樹的傳送門。與夢境的連結必須被切斷。', `FemaleText_loc7`='La tierra misma llora por su sufrimiento. Reúne sus lágrimas y utilízalas para sellar el portal de El Gran Árbol. Hay que cortar la conexión con el Sueño.' WHERE `ID`=39474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용감해지거라, 영웅들이여.', `FemaleText_loc4`='一定要勇敢，英雄们。', `FemaleText_loc5`='英雄們，勇氣與你們同在。', `FemaleText_loc7`='Sed valientes, héroes.' WHERE `ID`=39475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 타이라가드는 북부감시대의 것이다!', `MaleText_loc4`='提拉加德现在归北卫军了！', `MaleText_loc5`='提拉加德現在是屬於北方城堡的!', `MaleText_loc7`='¡Tiragarde pertenece ahora al Fuerte del Norte!' WHERE `ID`=39476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 무역왕을 추적해서 잡아야지!', `MaleText_loc4`='$n，你必须干掉那个贸易大王！', `MaleText_loc5`='$n，你必須抓到貿易親王!', `MaleText_loc7`='¡$n, tienes que ir a por el Príncipe mercante!' WHERE `ID`=39477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피즈가 그렇게 서투르지만 않았어도, 우리가 잡히는 일은 없었을 텐데!', `MaleText_loc4`='要是菲兹能稍微机灵点儿，我们绝对不会被捉住！', `MaleText_loc5`='如果費嘶沒那麼愚笨，我們永遠都不會被抓!', `MaleText_loc7`='¡Si Fizz no hubiera sido tan torpe, no nos habrían atrapado nunca!' WHERE `ID`=39478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에볼이 그렇게 서투르지만 않았어도, 우리가 잡히는 일은 없었을 텐데!', `MaleText_loc4`='要是艾沃能稍微机灵点儿，我们绝对不会被捉住！', `MaleText_loc5`='如果伊柏沒那麼愚笨，我們永遠都不會被抓!', `MaleText_loc7`='¡Si Evol no hubiera sido tan torpe, no nos habrían atrapado nunca!' WHERE `ID`=39479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 망치단은 무시할 수 없는 강력한 조직이다. 우리 덕분에 데스윙 님이 풀려나셨다. 우리 덕분에 고대 신들이 대지 깊은 곳에서 깨어났고, 또 우리 덕분에... 하이잘이 불타고 있지.$B$B넌 우릴 위해 뭘 할 수 있나?', `FemaleText_loc4`='暮光之锤是起决定性作用的力量。因为我们，死亡之翼自由了。因为我们，上古之神从大地深处重生。因为我们……海加尔在燃烧。$B$B你觉得你能为我们做什么？', `FemaleText_loc5`='暮光之錘是難以對付的勢力。因為我們，死亡之翼自由了。因為我們，上古之神從地淵中甦醒了。因為我們，海加爾山正在燃燒。$B$B你認為你還能幫我們什麼?', `FemaleText_loc7`='El Martillo Crepuscular es un poder al que no hay que subestimar. Gracias a nosotros, Alamuerte es libre. Gracias a nosotros, los dioses antiguos se han alzado de las entrañas de la tierra. Gracias a nosotros... Hyjal arde.$B$B¿Qué crees que tienes para ofrecernos?' WHERE `ID`=39480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어디로 가야 할지 드러났군요. 돌아가도록 해 주십시오.', `MaleText_loc4`='我们已经看清了前方的道路。回去吧。', `MaleText_loc5`='我們眼前的道路已經出現了，讓我們回去吧。', `MaleText_loc7`='El camino que se extiende ante nosotros nos ha sido revelado. Regresemos.' WHERE `ID`=39481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 바로 $n|1이로군;로군;. 무역왕을 처치하지 않으면 만사 끝이야.', `MaleText_loc4`='全靠你了，$n。你必须击败贸易大王，否则我们将一败涂地。', `MaleText_loc5`='你是救世主，$n。你必須擊敗貿易親王，不然一切都將化為烏有。', `MaleText_loc7`='Tú eres el elegido, $n. Tú derrotarás al Príncipe mercante o todo estará perdido.' WHERE `ID`=39482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전체적으로 남는 게 전혀 없는 상황이에요. 무역왕과 다시 손을 잡으셔야 해요, $n 님!', `FemaleText_loc4`='现在的整个局面都非常不利。你必须把贸易大王找回来，$n！', `FemaleText_loc5`='現在這整個狀況是非常沒有利潤的。你必須將貿易親王帶回，$n!', `FemaleText_loc7`='Esta situación no es rentable en absoluto. ¡$n, debes meter en vereda al Príncipe mercante!' WHERE `ID`=39483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 걱정은 마세요, $n 님. 가서 무역왕이나 확실히 처리하시라고요.', `FemaleText_loc4`='别担心我们，$n。你只要过去那边，确保解决掉贸易大王就可以了。', `FemaleText_loc5`='別擔心我們，$n。你只要到那去確定貿易親王被解決了就好了。', `FemaleText_loc7`='No te preocupes por nosotros, $n. Tú tienes que ir allí y asegurarte de que el Príncipe mercante se lleva su merecido.' WHERE `ID`=39484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여어.', `MaleText_loc4`='嗨。', `MaleText_loc5`='嘿。', `MaleText_loc7`='Eh.' WHERE `ID`=39485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전을 넣고 나서 무역왕을 계속 처리하십시오.', `MaleText_loc4`='请插入硬币，然后继续同贸易大王做交易。', `MaleText_loc5`='請投入硬幣後前進與貿易親王對抗。', `MaleText_loc7`='Inserta monedas y luego procede a ocuparte del Príncipe mercante.' WHERE `ID`=39486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그쪽은 잘 되어 가오?', `MaleText_loc4`='运气如何？', `MaleText_loc5`='運氣怎樣?', `MaleText_loc7`='¿Has tenido suerte?' WHERE `ID`=39487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=39488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지진, 홍수, 정령이 벌이는 그 어떤 짓도 제가 임무를 수행하는 걸 막을 수는 없어요.', `MaleText_loc4`='不管是地震还是洪水，魂灵使出的任何把戏都别想阻止我履行自己的职责。', `MaleText_loc5`='沒有任何地震、水災或靈體能阻止我完成工作。', `MaleText_loc7`='Ni un terremoto, ni una inundación, ni cualquier otro acontecimiento provocado por los espíritus me impedirán cumplir con mi deber.' WHERE `ID`=39489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어났던 그 모든 일이 결국 여기까지 이어졌네. $n, 실패해서는 안 돼. 만약 실패하면 끝장이야. 이 섬과 함께 우리 모두 죽는 거지.', `MaleText_loc4`='天意如此，$n。你必须获胜，否则我们将落得一败涂地，与这座岛屿一同消亡。', `MaleText_loc5`='一切都是為了現在這個時候，$n。你不能失敗，否則將失去一切，我們也都會死在這個島上。', `MaleText_loc7`='Todo iba encaminado a esto, $n. No puedes fracasar, o todo estará perdido y moriremos con esta isla.' WHERE `ID`=39490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히, 이들처럼 계속 붙잡히는 것도 능력이라고 봐. 정말 엄청난 집단 무능력 말이야. 진심으로 그렇게 생각해!$B$B고블린이라는 게 부끄러울 정도지.$B$B부끄러움 얘기가 나와서 말인데, 게을러빠진 우리 조수는 어디 있어? 어딘가 철퍼덕 앉아서 아무것도 안 할 게 뻔해.$B$B아, 정말이지 천재란. 우리 모두 이 궁지에서 벗어날 방법을 생각해내는 건 나 혼자만의 몫인가 봐.', `MaleText_loc4`='老实说，这些家伙怎么老是会被捉住？真是彻彻底底的无能！$B$B这简直让我为地精的身份而感到羞耻。$B$B说到羞耻，我那个好吃懒做的助手跑哪儿去了？不用猜，她肯定正坐在什么地方发呆呢！$B$B喔，这可真叫做能者多劳。我想只能靠我来想办法帮大家脱困了。', `MaleText_loc5`='說真的，這些人為什麼會一直被抓?跟你說，是因為他們無能到了極點!$B$B這讓我都快為身為哥布林而感到丟臉了。$B$B說到丟臉，我那懶惰的助手在哪?她一定在哪裡坐著什麼事都沒在做。$B$B唉，一個天才的責任真大啊。我看大概只能靠我一個人來想出一個方法解決這些問題。', `MaleText_loc7`='De verdad, ¿cómo se las arreglan para que los capturen una y otra vez? ¡Te digo que es incompetencia absoluta!$B$BCasi me siento avergonzado de ser un goblin.$B$BY hablando de vergüenza, ¿dónde está la vaga de mi ayudante? Seguro que está sentada en alguna parte tocándose las narices.$B$BOh, qué duro es ser un genio. Supongo que tendré que pensar en algo para sacarnos a todos de este lío yo mismo.' WHERE `ID`=39491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 위대한 숲에 경이로움을 보내고, 대지모신이 주신 선물의 기적을 누리고자 여기에 왔소이다.', `MaleText_loc4`='我们来此表达对伟大森林的敬意，亲眼见证大地之母馈赠的奇迹。', `MaleText_loc5`='我們是來這裡對偉大的森林致敬和體驗大地之母所送的這個驚人禮物的。', `MaleText_loc7`='Estamos aquí para presentar nuestros respectos al gran bosque y tomar parte en los maravillosos dones de la Madre Tierra.' WHERE `ID`=39492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저흴 도와주러 오셨나요, $c님? 이 계곡은 천혜의 요충지 역할을 하고 있어요. 우리가 이 보급로를 차단하면, 세계수에 있는 우리 동료들이 반격을 준비할 시간을 벌 수 있을 거예요.', `FemaleText_loc4`='你是来帮忙的吗，$c？这个山谷就是个天然的阻塞点。要是我们能扼住这条补给线，就能为我们在世界之树的同伴争取时间来发起反击。', `FemaleText_loc5`='你是來這幫忙的嗎，$c?這個山谷就是個自然的狹口。如果我們能攔截這個補給線，就可以為在世界之樹的同伴爭取一些反擊的時間。', `FemaleText_loc7`='¿Has venido a ayudar, $c? Este valle es como un cuello de botella natural. Si podemos estrangular la línea de suministros, ganaremos tiempo para que nuestros compañeros del Árbol del Mundo monten un contraataque.' WHERE `ID`=39493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 보급품이 어디서 오는지 도무지 모르겠어요. 어찌 됐든 황혼의 망치단이 산 전체를 한번에 공격할 방법을 찾은 것 같군요...', `FemaleText_loc4`='我不明白这些补给品是从哪儿来的。暮光之锤不知想出了什么办法，同时对整座圣山发起攻击……', `FemaleText_loc5`='我不懂這些補給是從哪來的。暮光之錘不知道用了什麼方法對整座山發動了攻擊...', `FemaleText_loc7`='No sé de dónde proceden esos suministros. De alguna manera, el Martillo Crepuscular ha encontrado la manera de asaltar de una sola vez la montaña entera...' WHERE `ID`=39494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍둥이 바위산의 꼭대기로 갑시다.', `MaleText_loc4`='让我们爬到那大家伙的顶上去。', `MaleText_loc5`='讓我們回到山頂上。', `MaleText_loc7`='Vamos a subir a lo alto del Coloso.', `FemaleText_loc1`='쌍둥이 바위산의 꼭대기로 갑시다.', `FemaleText_loc4`='让我们爬到那大家伙的顶上去。', `FemaleText_loc5`='讓我們回到山頂上。', `FemaleText_loc7`='Vamos a subir a lo alto del Coloso.' WHERE `ID`=39495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 이 철창에 바닥이 있다는 걸 알기는 해요?', `MaleText_loc4`='嗯……你注意到这笼子有底了？', `MaleText_loc5`='嗯...你知道這個籠子是有底的吧?!', `MaleText_loc7`='Mmm... ¿Eres consciente de que esta jaula tiene fondo?', `FemaleText_loc1`='음... 이 철창에 바닥이 있다는 걸 알기는 하세요?', `FemaleText_loc4`='嗯……你注意到这笼子有底了？', `FemaleText_loc5`='嗯...你知道這個籠子是有底的吧?!', `FemaleText_loc7`='Mmm... ¿Eres consciente de que esta jaula tiene fondo?' WHERE `ID`=39496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마야!', `MaleText_loc4`='妈咪！', `MaleText_loc5`='媽咪!', `MaleText_loc7`='¡Mamaíta!', `FemaleText_loc1`='엄마야!', `FemaleText_loc4`='妈咪！', `FemaleText_loc5`='媽咪!', `FemaleText_loc7`='¡Mamaíta!' WHERE `ID`=39497;
