UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아내에게 너무나 사랑한다고 전해 줘요!', `MaleText_loc4`='请转告我的妻子，我很爱她！', `MaleText_loc5`='告訴我妻子我非常愛她!', `MaleText_loc7`='¡Dile a mi mujer que la quiero mucho!', `FemaleText_loc1`='그이에게 너무나 사랑한다고 전해 주세요!', `FemaleText_loc4`='请转告我的妻子，我很爱她！', `FemaleText_loc5`='告訴我妻子我非常愛她!', `FemaleText_loc7`='¡Dile a mi marido que le quiero mucho!' WHERE `ID`=39499;
