UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 대족장, 배신자가 너를 구하러 왔군. 이거 일이 쉬워졌어. 자, 함께 끝장나기 싫거든 둘 다 내게 무릎 꿇어라!', `MaleText_loc4`='那个叛徒来救你了，酋长。这倒方便了。你们要么一起向我下跪，要么就一起去死！', `MaleText_loc5`='看來叛徒已經來救你了，大酋長。真省事。你們看是要一起向我臣服，還是一起死!', `MaleText_loc7`='VEO QUE EL TRAIDOR LLEGÓ A TU RESCATE, JEFE DE GUERRA. QUÉ CONVENIENTE. ¡SE ARRODILLARÁN ANTE MÍ O CAERÁN JUNTOS!' WHERE `ID`=39530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위투성이 길만 가득한 망할 동네 같으니! 난 갈 데가 많은데, 여긴 그중 하나가 아니란 말일세.', `MaleText_loc4`='炸毁那些杜隆塔尔的岩石大道！我已经确定了几个需要炸毁的地方。但这里并不是其中之一。', `MaleText_loc5`='杜洛塔這些天殺的石頭路!我有該去的地方，而這裡卻不是那些地方。', `MaleText_loc7`='¡Malditas sean las rocosas carreteras de Durotar! Tengo que estar en muchos sitios, y este no es uno de ellos.' WHERE `ID`=39531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경사로 위쪽이네, $n! 스랄 님께서 무역왕을 처치하시도록 도와드리게!', `MaleText_loc4`='坡道上面，$n！帮助萨尔击败贸易大王！', `MaleText_loc5`='從斜坡上去，$n!幫助索爾擊敗貿易親王!', `MaleText_loc7`='¡Sube por la rampa, $n! ¡Tienes que ayudar a Thrall a derrotar al Príncipe mercante!' WHERE `ID`=39532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님께서 부두 반대편 꼭대기에서 무역왕과 싸우고 계신다오. $n, 서두르시오!', `MaleText_loc4`='萨尔正和贸易大王在码头的另一端打得难解难分。快去，$n！', `MaleText_loc5`='索爾正與貿易親王在碼頭另一邊的上面交戰。動作快，$n!', `MaleText_loc7`='Thrall está luchando contra el Príncipe mercante al otro extremo de los muelles. ¡Date prisa, $n!' WHERE `ID`=39533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여; 나를 도와라. 무역왕이 훨씬 더 강력해졌다!$B$B얼마나 더 버틸 수 있을지 모르겠구나.', `MaleText_loc4`='$n，帮助我。贸易大王已经强大了许多！$B$B我不知道自己还能坚持多久。', `MaleText_loc5`='幫助我，$n。貿易親王變得更加強大了!$B$B我不知道我還能夠撐多久。', `MaleText_loc7`='Ayúdame, $n. ¡El Príncipe mercante se ha vuelto más poderoso!$B$BNo sé cuánto tiempo más podré resistir.' WHERE `ID`=39534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 졌어요. 뭘 잘못했는지 아주 확실히 깨달았습니다. 앞으로 무역회사 운영 방식을 확 바꾸겠다고 맹세합니다!', `MaleText_loc4`='我输了。你让我看到了我的错误。从现在起，我承诺对财阀进行彻底的改革。', `MaleText_loc5`='我輸了。你們讓我看到我錯誤的做事方式。從現在開始，我答應改革企業的運作方式!', `MaleText_loc7`='Vencido. Me has mostrado mis errores. ¡De ahora en más, prometo que el cártel será reformado!' WHERE `ID`=39536;
