UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리 축하 파티는 멀었나? 벌써부터 춤추고 싶어 근질근질하다고!', `MaleText_loc4`='庆功会什么时候开始？我已经准备好跳舞了！', `MaleText_loc5`='慶功宴什麼時候才要開始呀?我已經準備好要開始跳舞了!', `MaleText_loc7`='¿Cuánto falta para que empiece la fiesta de la victoria? ¡Estoy listo para bailar!', `FemaleText_loc1`='승리 축하 파티는 멀었나? 벌써부터 춤추고 싶어 근질근질하다고!', `FemaleText_loc4`='庆功会什么时候开始？我已经准备好跳舞了！', `FemaleText_loc5`='慶功宴什麼時候才要開始呀?我已經準備好要開始跳舞了!', `FemaleText_loc7`='¿Cuánto falta para que empiece la fiesta de la victoria? ¡Estoy lista para bailar!' WHERE `ID`=39541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형님, 형님! 살려주세요! 도저히 못 당하겠어요!', `MaleText_loc4`='老爷！老爷！我让步！你们太厉害了！', `MaleText_loc5`='叔叔!叔叔!我投降!你們實在太強了!', `MaleText_loc7`='¡Me rindo! ¡Me rindo! ¡Ustedes son demasiado para mí!' WHERE `ID`=39542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든지 합죠. 시키실 일이라도?', `MaleText_loc4`='我是你的地精，萨尔。你要我干嘛？', `MaleText_loc5`='我是你的哥布林了，索爾。你要我怎麼做?', `MaleText_loc7`='Soy tu goblin, Thrall. ¿Qué quieres que haga?' WHERE `ID`=39543;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='골두니 오우거는 이 땅을 망칠 만큼 망쳐놨네. 우린 호드를 위해 이 땅과 자원을 손에 넣고자 하네.', `FemaleText_loc4`='戈杜尼食人魔已经破坏这片土地相当久了。我们来这里，就是要为部落夺回这片土地以及它丰富的资源！', `FemaleText_loc5`='戈杜尼巨魔已經殘害這片土地夠久了。我們是來這為部落接手這片土地和取得資源的。', `FemaleText_loc7`='Los orcos Gordunni ya llevan demasiado tiempo arruinando esta tierra. Debemos hacernos con ella y sus recursos para la Horda.' WHERE `ID`=39544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오우거들이 우리 편입니까?', `MaleText_loc4`='这些食人魔是站我们这边儿的？', `MaleText_loc5`='這些巨魔是站在我們這邊的?', `MaleText_loc7`='¿Esos ogros están de nuestra parte?', `FemaleText_loc1`='이 오우거들이 우리 편인가요?', `FemaleText_loc4`='这些食人魔是站我们这边儿的？', `FemaleText_loc5`='這些巨魔是站在我們這邊的?', `FemaleText_loc7`='¿Esos ogros están de nuestra parte?' WHERE `ID`=39545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌망치 일족은 호드를 위해 일한다네!$B$B오그리마 건설 당시, 우리들의 고향으로 칼림도어에 적응하고 있었을 때, 영웅이신 렉사르 님께서는 돌망치 일족의 수장을 그의 발밑에 무릎 꿇리셨네.$B$B그 후로 그들은 호드를 위해 일하고 있네. 난 골두니 일족을 상대로 하는 힘든 싸움을 풀어내고자 이들을 여기로 불러들인 것이고 말이야.', `FemaleText_loc4`='石槌部族效忠于部落！$B$B在奥格瑞玛建立期间，当我们的族人努力将卡利姆多改造成我们的家园时，英雄雷克萨击败了石槌食人魔部族的首领。$B$B从那时起，他们便发誓为部落效忠，我已经将他们召集至此，铲除戈杜尼部族。', `FemaleText_loc5`='石槌氏族是屬於部落的!$B$B當建立奧格瑪時，當卡林多被馴服成為了我們人民的家鄉時，英雄雷克薩擊敗了石槌氏族的巨魔酋長。$B$B他們之後便臣服於部落，我將他們叫來這搬運重物來對付戈杜尼氏族。', `FemaleText_loc7`='¡El clan Quebrantarrocas sirve a la Horda!$B$BDurante la fundación de Orgrimmar, cuando Kalimdor estaba siendo domesticado para servir de hogar para nuestra gente, el héroe Rexxar derrotó al jefe del clan ogro de los Quebrantarrocas.$B$BHan servido a la Horda desde entonces, y los he mandado llamar para que se ocupen del trabajo sucio contra el clan Gordunni.' WHERE `ID`=39546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예.', `MaleText_loc4`='是的。', `MaleText_loc5`='是的。', `MaleText_loc7`='Sí.', `FemaleText_loc1`='네.', `FemaleText_loc4`='是的。', `FemaleText_loc5`='是的。', `FemaleText_loc7`='Sí.' WHERE `ID`=39547;
