UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 질문자의 가치관에 따라 다릅니다.', `MaleText_loc4`='这取决于你对“是”字的定义……', `MaleText_loc5`='那要看你真正的意思是什麼。', `MaleText_loc7`='Eso depende de cuál sea tu definición de "es"...', `FemaleText_loc1`='그건 질문자의 가치관에 따라 다르죠.', `FemaleText_loc4`='这取决于你对“是”字的定义……', `FemaleText_loc5`='那要看你真正的意思是什麼。', `FemaleText_loc7`='Eso depende de cuál sea tu definición de "es"...' WHERE `ID`=39549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음이 없는 자만이 그런 질문을 할 수 있습니다! 믿음이 없으십니까?', `MaleText_loc4`='只有怀疑论者才会问出这样的问题！你是怀疑论者吗？', `MaleText_loc5`='只有不信之徒才會問這種問題!你是個不信之徒嗎?', `MaleText_loc7`='¡Tan solo un no creyente haría una pregunta así! ¿Eres un no creyente?', `FemaleText_loc1`='믿음이 없는 자만이 그런 질문을 할 수 있어요! 믿음이 없으신가요?', `FemaleText_loc4`='只有怀疑论者才会问出这样的问题！你是怀疑论者吗？', `FemaleText_loc5`='只有不信之徒才會問這種問題!你是個不信之徒嗎?', `FemaleText_loc7`='¡Tan solo un no creyente haría una pregunta así! ¿Eres un no creyente?' WHERE `ID`=39550;
