UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요... 당신이 생각하는 답은 뭡니까?', `MaleText_loc4`='那么……你觉得答案是什么？', `MaleText_loc5`='嗯...你認為答案是什麼?', `MaleText_loc7`='Bueno... ¿Cuál crees que es la respuesta?', `FemaleText_loc1`='글쎄요... 당신이 생각하는 답은 뭔가요?', `FemaleText_loc4`='那么……你觉得答案是什么？', `FemaleText_loc5`='嗯...你認為答案是什麼?', `FemaleText_loc7`='Bueno... ¿Cuál crees que es la respuesta?' WHERE `ID`=39552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇기도 하고 아니기도 합니다. 어떤 시선으로 보느냐에 따라... 달라진다고 봅니다. 질문에 대한 답이 되었습니까?', `MaleText_loc4`='既是又不是。我想这真要取决于你怎么看了……这个答案你满意吗？', `MaleText_loc5`='不一定。這要看你以什麼角度來看...我想吧。我有回答你的問題嗎?', `MaleText_loc7`='Sí y no. En realidad depende de tu punto de vista... Supongo. ¿Contesta eso a tu pregunta?', `FemaleText_loc1`='그렇기도 하고 아니기도 해요. 어떤 시선으로 보느냐에 따라... 달라진다고 봐요. 질문에 대한 답이 되었나요?', `FemaleText_loc4`='既是又不是。我想这真要取决于你怎么看了……这个答案你满意吗？', `FemaleText_loc5`='不一定。這要看你以什麼角度來看...我想吧。我有回答你的問題嗎?', `FemaleText_loc7`='Sí y no. En realidad depende de tu punto de vista... Supongo. ¿Contesta eso a tu pregunta?' WHERE `ID`=39553;
