UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈이 황혼의 망치단을 이끌고 있습니까?', `MaleText_loc4`='古加尔是暮光之锤的领袖吗？', `MaleText_loc5`='丘加利是暮光之錘的首領嗎?', `MaleText_loc7`='¿Cho''Gall lidera el Martillo Crepuscular?', `FemaleText_loc1`='초갈이 황혼의 망치단을 이끌고 있나요?', `FemaleText_loc4`='古加尔是暮光之锤的领袖吗？', `FemaleText_loc5`='丘加利是暮光之錘的首領嗎?', `FemaleText_loc7`='¿Cho''Gall lidera el Martillo Crepuscular?' WHERE `ID`=39577;
