UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예 구덩이나 갤리윅스 부두로 돌아가지 않으면 축구탄 제복을 잃어버립니다!', `MaleText_loc4`='返回奴隶营或加里维克斯码头，否则你将失去足球炸弹制服！', `MaleText_loc5`='回到奴隸之坑或加里維克斯碼頭，又或交出你的足球炸彈戰鬥裝!', `MaleText_loc7`='¡Regresa a Los Pozos de Esclavos o a los Muelles de Gallywix, o perderás tu uniforme de bombalón!' WHERE `ID`=39579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<피즐의 몸이 힘없이 물결에 흔들립니다. 오른손에 수정구가 꽉 쥐어져 있습니다.>', `MaleText_loc4`='<菲兹尔的躯体晃动着，毫无生命气息，右手却依然紧攥着那颗宝珠。>', `MaleText_loc5`='<菲茲爾的身體沒有生氣地擺動著。他的右手緊緊握著他的寶珠。>', `MaleText_loc7`='<El cuerpo de Fizzle se balancea sin vida. La mano derecha sujeta con fuerza su orbe.>' WHERE `ID`=39580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<수정구를 빼내려고 애써 봅니다.>', `MaleText_loc4`='<尝试移除这颗宝珠。>', `MaleText_loc5`='<試著拿走寶珠。>', `MaleText_loc7`='<Intenta recuperar el orbe.>', `FemaleText_loc1`='<수정구를 빼내려고 애써 봅니다.>', `FemaleText_loc4`='<尝试移除这颗宝珠。>', `FemaleText_loc5`='<試著拿走寶珠。>', `FemaleText_loc7`='<Intenta recuperar el orbe.>' WHERE `ID`=39581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<수정구를 쥐어 보지만, 피즐의 손이 수정구를 너무 꽉 붙잡고 있습니다. 수정구가 희미하게 빛납니다.>', `MaleText_loc4`='<你抓住那颗宝珠，但菲兹尔的手将它抓得更紧了。这颗球微微闪烁着光亮。>', `MaleText_loc5`='<你抓住寶珠，但菲茲爾的手握得更緊了。寶珠微微的發亮。>', `MaleText_loc7`='<Agarras el orbe, pero la mano de Fizzle se cierra aún más fuerte en torno a él. El orbe brilla ligeramente.>' WHERE `ID`=39582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<힘주어 피즐의 손가락을 차례차례 펴 봅니다.>', `MaleText_loc4`='<尝试移开菲兹尔的手。>', `MaleText_loc5`='<那就試著扳開菲茲爾的手。>', `MaleText_loc7`='<Entonces, intenta recuperar la mano de Fizzle.>', `FemaleText_loc1`='<힘주어 피즐의 손가락을 차례차례 펴 봅니다.>', `FemaleText_loc4`='<尝试移开菲兹尔的手。>', `FemaleText_loc5`='<那就試著扳開菲茲爾的手。>', `FemaleText_loc7`='<Entonces, intenta recuperar la mano de Fizzle.>' WHERE `ID`=39583;
