UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 무역왕을 어떻게 할지 잠시 고민합니다.', `MaleText_loc4`='萨尔咕哝着思考了一会儿，琢磨该拿贸易大王怎么办。', `MaleText_loc5`='索爾哼了一聲，思考著要如何處理貿易親王。', `MaleText_loc7`='Thrall gruñe y piensa durante unos segundos qué hacer con el Príncipe mercante.' WHERE `ID`=39585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당분간은 계속해서 빌지워터 무역회사의 무역왕을 맡아라.', `MaleText_loc4`='至少现在，你仍然是锈水财阀的贸易大王。', `MaleText_loc5`='現在，你就繼續當你污水企業聯合的貿易親王吧。', `MaleText_loc7`='Por ahora, seguirás siendo el Rey Mercante del Cártel Pantoque.' WHERE `ID`=39586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 동료 중 대표자를 하나 골라 오그리마에 있는 새로운 대족장, 가로쉬에게 보내겠다.', `MaleText_loc4`='我会在你们族内选择一名代表，去见新酋长——奥格瑞玛的加尔鲁什·地狱咆哮。', `MaleText_loc5`='我會從你的人民中挑出代表去找在奧格瑪的新任大酋長，卡爾洛斯·地獄吼。', `MaleText_loc7`='Enviaré un representante de tu pueblo al nuevo Jefe de Guerra, Garrosh Grito Infernal en Orgrimmar.' WHERE `ID`=39587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라를 새로운 고향으로 삼아라. 빌지워터 무역회사는 호드의 일원이 될 것이다!', `MaleText_loc4`='你们将在艾萨拉有一个新家。锈水财阀将成为部落的一分子！', `MaleText_loc5`='你在艾薩拉會有一個新家，而污水企業聯合將會成為部落的一員!', `MaleText_loc7`='¡Tendrás un nuevo hogar en Azshara y el Cártel Pantoque será parte de la Horda!' WHERE `ID`=39588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다! 빌지워터 무역회사여 영원하라! 호드를 위하여!', `MaleText_loc4`='就按照你说的去做！锈水财阀万岁！为了部落！', `MaleText_loc5`='如你所願! 污水企業聯合萬歲! 為了部落!', `MaleText_loc7`='¡Será como tú dispongas! ¡Larga vida al Cártel Pantoque! ¡Por la Horda!' WHERE `ID`=39589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하피의 부드러워 보이는 깃털에 속으면 안 돼... 저 생물들은 정말 끔찍하다고!', `MaleText_loc4`='别被鹰身人那长满羽毛的翘臀迷惑……她们的杀伤力可是致命的！', `MaleText_loc5`='別把注意力放在鷹身人緊實和毛絨絨的屁股上...這種生物真的是很危險的!', `MaleText_loc7`='Procura no hacer caso de las firmes y emplumadas partes traseras de las arpías... ¡Esas criaturas son realmente mortales!' WHERE `ID`=39590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르, 병사여.', `MaleText_loc4`='Lok''tar ogar，士兵。', `MaleText_loc5`='(獸人語)不勝即亡，士兵。', `MaleText_loc7`='Lok''tar ogar, soldado.' WHERE `ID`=39591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡POR LA HORDA!' WHERE `ID`=39592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 지금은 칼림도어로 돌아갈 수 없다. 초우그만 함께 돌아가리라. 우리 모두를 목적지로 데려다 줄 다른 함선이 오는 중이다.$B$B$n, 앞길에 최고의 모험이 펼쳐지기를 비노라. 우리가 가는 길에서 언젠가 다시 만나리라. 그리고 그날에, 세상의 운명은 그대 손에 놓이리라!', `MaleText_loc4`='我们暂时还无法返回卡利姆多。只有卡乌格会跟你一起回去。另一艘船会把我们剩下这些人带去目的地。$B$B最伟大的冒险还在前方等着你呢，$n。我们的道路还会再次交汇，到那时，世界的命运将掌握在我们手中！', `MaleText_loc5`='我們目前無法回到卡林多，只有查爾格會跟你回去。另一艘船將會把我們其他人帶到我們的目的地。$B$B最偉大的冒險正在等你，$n。我們的命運將再次交錯，當那個時候到來時，世界的命運將會掌握在你的手裡!', `MaleText_loc7`='Por ahora no podemos regresar a Kalimdor. Tan solo Chawg volverá contigo. Otro barco vendrá a recogernos a los demás para llevarnos a nuestro destino.$b$bTu mayor aventura te aguarda, $n. Nuestros caminos volverán a encontrarse de nuevo, y cuando lo hagan, ¡el destino del mundo descansará en tus manos!' WHERE `ID`=39593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 끝인가 보네요. 정말 영광이었어요. 분명히 곧 다시 만날 거예요.$B$B오그리마로 떠날 준비가 되시면 말씀만 해주세요.', `FemaleText_loc4`='看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。$B$B当你准备好动身前往奥格瑞玛时，告诉我一声。', `FemaleText_loc5`='看來是結束了，老大。這是我的光榮。我相信我們很快會再見的。$B$B讓我知道你什麼時候要回到奧格瑪就好了。', `FemaleText_loc7`='Parece que esto es todo, $gjefe:jefa;. Has sido todo un honor. Estoy segura de que pronto nos veremos de nuevo.$b$bAvísame cuando quieras ir Orgrimmar.' WHERE `ID`=39594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새시, 이 섬이 폭발해서 영원히 사라지기 전에 오그리마를 향해 떠납시다!', `MaleText_loc4`='莎希，在岛屿彻底覆灭前，我们得尽快赶往奥格瑞玛！', `MaleText_loc5`='賽希，讓我們在這島爆炸前回到奧格瑪吧!', `MaleText_loc7`='¡Sassy, zarpemos hacia Orgrimmar antes de que la isla explote!', `FemaleText_loc1`='새시, 이 섬이 폭발해서 영원히 사라지기 전에 오그리마를 향해 떠나요!', `FemaleText_loc4`='莎希，在岛屿彻底覆灭前，我们得尽快赶往奥格瑞玛！', `FemaleText_loc5`='賽希，讓我們在這島爆炸前回到奧格瑪吧!', `FemaleText_loc7`='¡Sassy, zarpemos hacia Orgrimmar antes de que la isla explote!' WHERE `ID`=39595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 능력을 증명해라! 오우거여, 처치해라! (주인님께 바칠 피! 피와 고통!)', `MaleText_loc4`='证明忠诚！食人魔，消灭害虫！（主人需要鲜血！鲜血和痛苦！）', `MaleText_loc5`='證明你自己，我的巨魔們!捏死這隻蟲子!(給主人的血，鮮血和痛苦。)', `MaleText_loc7`='¡Prueben su valía, mis ogros! ¡Maten al insecto! (¡Sangre para el Amo! ¡Sangre y sufrimiento!)' WHERE `ID`=39596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르, $c|1이여;여;.', `MaleText_loc4`='Lok''tar，$c。', `MaleText_loc5`='為了部落，$c。', `MaleText_loc7`='Lok''tar, $c.' WHERE `ID`=39597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 당신의 전투검은늑대가 또다시 필요할 것 같습니다.', `MaleText_loc4`='嗯……我还会用到你的战斗座狼的。', `MaleText_loc5`='呃...我還需要你的作戰座狼。', `MaleText_loc7`='Emm... Voy a necesitar de nuevo mi huargo de batalla.', `FemaleText_loc1`='음... 당신의 전투검은늑대가 또다시 필요할 것 같아요.', `FemaleText_loc4`='嗯……我还会用到你的战斗座狼的。', `FemaleText_loc5`='呃...我還需要你的作戰座狼。', `FemaleText_loc7`='Emm... Voy a necesitar de nuevo mi huargo de batalla.' WHERE `ID`=39598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g젊은이:아가씨;, 우리는 오그리마로 갈 거야. 그다음에는 아즈샤라에 있는 새 고향으로 가고. 거기에서 만나자고!', `MaleText_loc4`='我们要先去奥格瑞玛，$g 小伙子 : 姑娘;，然后前往我们在艾萨拉的新家。在那儿见吧！', `MaleText_loc5`='我們的目的地是奧格瑪，然後就是我們的新家艾薩拉。我們那裡見!', `MaleText_loc7`='Nos dirigimos a Orgrimmar, $gamigo:muchacha;, y desde allí seguiremos a nuestro nuevo hogar, Azshara. ¡Nos veremos allí!' WHERE `ID`=39599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기까지 오느라 정말 긴 여행을 했네요. 고마워요!$B$B얼른 이 섬을 떠나요.', `FemaleText_loc4`='这可真是个漫长的旅程啊，宝贝儿。谢谢你！$B$B现在让我们离开这座岛吧。', `FemaleText_loc5`='來到這真是路途遙遠啊，甜心。謝謝你!$B$B我們現在離開這個島吧。', `FemaleText_loc7`='Ha sido un viaje muy largo hasta aquí, cielo. ¡Gracias!$b$bAhora vámonos de esta isla.' WHERE `ID`=39600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마... 워...', `MaleText_loc4`='谢谢……你……', `MaleText_loc5`='謝謝...你...', `MaleText_loc7`='Muchas... gracias...' WHERE `ID`=39601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님은 진정한 영웅이세요! 빌지워터 무역회사의 모델감이죠.$B$B우리 주가도 엄청나게 오르고 제 봉급도 오를 거예요!', `FemaleText_loc4`='你是位真正的$g大英雄:女英雄;，$n！是锈水财阀的偶像$g帅哥:美女;。$B$B我们的股价将一路飙升，而我也能得到加薪了！', `FemaleText_loc5`='你是一位真正的英雄，$n!是污水企業商周的頭版人物。$B$B我們的股票一定會暴漲，我的薪水也會更高!', `FemaleText_loc7`='¡Eres $gun verdadero héroe:una verdadera heroína;, $n! ¡La estrella del Cártel Pantoque!$b$bNuestras acciones se van a disparar y yo voy a conseguir un ascenso.' WHERE `ID`=39602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무역회사의 장래를 생각하면 별로 좋아 보이지 않는군요. 손톱만큼도 좋지 않아요.$B$B이 곤경에서 벗어나게 해주세요. $n 님, 그렇지 않으면 차라리 저 위 화산으로 걸어 들어가는 게 나아요.', `FemaleText_loc4`='锈水财阀的未来看起来可不乐观。一点儿也不。$B$B你必须帮我们及早抽身，$n，否则我们不如直接跳进那边的火山里算了。', `FemaleText_loc5`='這看起來對企業未來的發展並不好，很不好。$B$B你必須把我們的財產從火中救出來，$n，不然我們全部都只能被逼著跳進那個火山口了。', `FemaleText_loc7`='Esto no pinta bien para el futuro del cártel. Nada bien.$b$bTienes que sacarnos las castañas del fuego, $n, o más nos vale que saltemos a ese volcán.' WHERE `ID`=39603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오 이런, 당신이 해내시다니. $n 님, 정말로 해내셨군요!$B$B자, 계산해보니 이 양동이를 아주 바로 떠내려 보내지 않으면 저 거대한 화산 바위 하나가 대기를 뚫고 떨어져 배를 산산조각낼 가능성이 커진다고요.$B$B자 해볼까요?', `FemaleText_loc4`='喔天哪，你做到了，$n，你真的做到了！$B$B现在，根据我的估计，如果我们不在最短最短的时内里起航，那堆巨型火山石从天而降，把快艇击成碎片的可能性会越来越大。$B$B出发吗？', `FemaleText_loc5`='我的天啊，你辦到了，$n，你真的辦到了!$B$B現在，根據我的計算，如果我們不能很快地讓這船動起來，其中一顆火山巨岩從空中飛過來砸爛這遊艇的機率就會變得非常大。$B$B走了吧?', `FemaleText_loc7`='¡Vaya, lo has conseguido, $n, lo has conseguido de verdad!$b$bSegún mis cálculos, si no zarpamos ya mismo hay muchas probabilidades de que una de esas rocas volcánicas gigantes que vuelan por los aires aplaste este yate y lo rompa en mil pedazos.$b$b¿Nos vamos?' WHERE `ID`=39604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사의 영웅은 언제나 마지막 할인 행사도 여유 있게 즐기지.', `MaleText_loc4`='锈水财阀的$g 英雄 : 女英雄; 总能在最后一刻赶上清仓销售的好机会，$n。', `MaleText_loc5`='我們就是有足夠的時間為污水企業的英雄$n航行。', `MaleText_loc7`='¡Siempre hay tiempo para una venta de última hora para el $ghéroe:heroína; del Cártel Pantoque, $n!' WHERE `ID`=39605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이게 당신이 사업에 좋지 않다고 할 만한 일이야!', `MaleText_loc4`='这里就是被你称为很糟糕的地方！', `MaleText_loc5`='在這裡的這個就是我們所謂的爛生意!', `MaleText_loc7`='¡Esto de aquí es lo que yo llamaría malo para el negocio!' WHERE `ID`=39606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄청난 난장판이로군요! 이걸 뭐라 이야기해야 하죠?$B$B게다가 정말... 고블린 좀비란 말이에요?!!', `FemaleText_loc4`='真是一团糟！我该怎么旋转这个？$B$B这是真的吗？僵尸地精？！！', `FemaleText_loc5`='真是一團亂!我要怎麼轉這個?$B$B還有...哥布林殭屍?!!...真的假的?!!', `FemaleText_loc7`='¡Vaya desastre! ¿Cómo voy a explicar esto?$b$bY por cierto... ¡¿goblins zombis?! ¡Esto es el colmo!' WHERE `ID`=39607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배짱이 두둑하던데! 끝까지 공을 몰고 가더니 한 방에 터트렸어!$B$B이제 여기서 나가자고. 새로운 팀은 ''$n 대폭발''로 이름 지을까 생각 중이야!', `MaleText_loc4`='你成功了，孩子！你带球冲进了得分区，引爆并一举取得了胜利！$B$B现在让我们离开这儿吧。我想新的队伍可以命名为$n爆破队！', `MaleText_loc5`='你有種，小子!你真有種到最裡面去引爆炸彈!$B$B我們現在快閃吧。我在想新的隊名應該叫$n轟炸隊!', `MaleText_loc7`='¡Eres grande, rapaz! ¡Has hecho llegar el balón a la zona de anotación y lo has detonado a lo grande!$B$BAhora, salgamos de aquí. ¡Se me ocurre que el nuevo equipo quizá tenga que llamarse los Explosivos de $n!' WHERE `ID`=39608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군. 자네가 해냈어!$B$B이제 새로 개업하게 아즈샤라로 가자고. 휴가가 너무 길었더니 고지서가 잔뜩 쌓였거든!', `MaleText_loc4`='你做到了，我的$g 小伙子 : 姑娘;，你做到了！$B$B现在让我们前往艾萨拉，是时候开始我的新事业了。这个假期可真漫长，我还有账单要付！', `MaleText_loc5`='你辦到了!你辦到了!$B$B我們現在到艾薩拉好讓我可以開始經營新的生意。這個旅途很長，我還有欠的費要繳呢!', `MaleText_loc7`='¡Lo has conseguido, $gchico:chica;, ¡lo has conseguido!$B$BAhora vayamos a Azshara para montar mi nuevo chiringuito. ¡Han sido unas vacaciones muy largas y tengo facturas que pagar!' WHERE `ID`=39609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 여기에서 벗어나게 해줄 방법이 있다고는 생각하지 않는 데 말이지? 없다고?$B$B아 그렇다면, 용암이 천천히 이 구덩이 안으로 쏟아질 때 너무 고통스럽지는 않으리라고 상상하겠어.', `MaleText_loc4`='我不认为你还能想到什么办法把我们从这里弄出去？有吗？$B$B啊，好吧，希望当岩浆缓缓流进来时，我们不会死得太痛苦。', `MaleText_loc5`='我想你應該沒有任何方法可以讓我們逃出這裡，對吧?$B$B唉，至少被熔岩燒死不算太痛。', `MaleText_loc7`='Supongo que no hay ninguna manera de que nos saques de aquí, ¿verdad? ¿No?$B$BOh, bueno, creo que no será tan doloroso cuando la lava empiece a llenar este pozo.' WHERE `ID`=39610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 여기서 죽고 말 거야!!!$B$B노예를 관리하는 현장감독인데... 무역왕 편에 서기엔 너무 늦었을까?', `MaleText_loc4`='我们都要死在这儿了！！！$B$B我是个奴隶工头……不知道现在投靠贸易大王还来得及吗？', `MaleText_loc5`='我們全都會死在這裡!!!$B$B我是個奴隸工頭...我想現在靠去貿易親王那邊會不會太遲?', `MaleText_loc7`='¡¡¡Vamos a MORIR aquí!!!$B$BSoy un capataz de esclavos... ¿Me pregunto si es demasiado tarde para ponerme de parte del Príncipe mercante?' WHERE `ID`=39611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가지고 있을 줄 알았지.$B$B음, 아즈샤라에 내 자리가 있을까? 거기도 트롤이 있긴 해?', `MaleText_loc4`='我知道你一直都有这潜质，$n。$B$B现在说说——你觉得在艾萨拉会有我的位置吗？那儿有巨魔吗？', `MaleText_loc5`='我知道你一直都在隱瞞，$n。$B$B跟我說，你認為我在艾薩拉能找到工作機會嗎?那裡有食人妖嗎?', `MaleText_loc7`='$n, he sabido que lo tenías en tu interior todo este tiempo.$B$B¿Crees que habrá un puesto para mí en Azshara? ¿Hay trols allí?' WHERE `ID`=39612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그저 고마울 따름이야, $n.$B$B여기 계신 의사 선생님께서 전기 충격으로 당신을 되살려내서 정말 기뻐. 안 그랬다면 우리 모두 이미 죽은 목숨이었겠지. 아니면 더 끔찍한 상황이 벌어지던가!', `MaleText_loc4`='我只想说声谢谢，$n。$B$B这儿的医生能把你救醒真是太好了，不然我们现在都已经死了，甚至更糟！', `MaleText_loc5`='我只想說聲謝謝，$n。$B$B我很慶幸這裡的醫生能把你救回來，不然我們現在已經死光光...或更慘!', `MaleText_loc7`='Solo quería darte las gracias, $n.$B$BMe alegro mucho de que el doctor pudiera traerte a la vida o todos estaríamos muertos ya, ¡o peor!' WHERE `ID`=39613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 구덩이 바닥 따위를 청소하지는 않겠어. 이 점은 분명히 해 둘 테야!$B$B저 쥐새끼는 당신이 좀 처리해 줘. 무역왕 말이야!', `MaleText_loc4`='我才不会为你收拾残局呢，你听好了！$B$B你得去解决贸易大王那只老鼠，我就是这么想的！', `MaleText_loc5`='我告訴你，我可不想在爛泥巴裡找人!$B$B你必須找出那隻老鼠，那個貿易親王，瞭解嗎!', `MaleText_loc7`='¡Te aseguro que NO tengo ninguna intención de barrer el suelo de un pozo de lodo!$B$BTienes que hacer tratos con esa rata del Príncipe mercante, ¡eso es lo que creo!' WHERE `ID`=39614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 만세 삼창을!!!$B$B아즈샤라에 나만의 침대를 놓고 아침을 먹고 싶어서 몸살 날 지경이야. 아즈샤라는 어떨 거 같아?', `MaleText_loc4`='为$n三呼万岁！$B$B我真恨不得现在就去艾萨拉搭起我的小床，吃顿可口的早餐。你觉得那里会是什么样的？', `MaleText_loc5`='為$n歡呼三聲!!!$B$B我實在等不及在艾薩拉開一間民宿了。你對那裡有什麼感覺?', `MaleText_loc7`='¡¡¡Tres hurras por $n!!!$B$BNo puedo esperar a abrir mi propio hotelito rural en Azshara. ¿Cómo crees que es aquel lugar?' WHERE `ID`=39615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈부신 활약이었어, $n. 최고야!$B$B물론, 내가 천재적인 땜장이 기술을 발휘하지 않았더라면 못 해냈겠지만. 이 내용을 회사 보고서에 반드시 써주시리라고 믿어. 우리 조수가 좀 시원치 않았지만 어려운 일을 정말로 훌륭히 해냈다고.', `MaleText_loc4`='你干得棒极了，$n。你可真是一流！$B$B不过，当然，要是没有我的聪明才智，你也做不到——我相信你肯定会在工作报告中写上这一条的。不管怎样，虽然我那笨手笨脚的助手老是添乱，你还是圆满完成了。', `MaleText_loc5`='你做的太棒了，$n，棒呆了!$B$B不過當然，如果不是在我天才的工匠技術下你是辦不到的，你會把這記錄在你們的公司報告中對吧?但你做的還是很好，雖然我出了非常多的力。', `MaleText_loc7`='¡Has hecho un trabajo de primera, $n. ¡De lujo!$B$BAunque, claro, no lo habrías conseguido sin mi genio como manitas, algo que estoy seguro harás constar en tu informe. Pero realmente lo has conseguido, a pesar de las quejas de mi ayudante.' WHERE `ID`=39616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오그리마와 아즈샤라로 가. 이 녀석을 바다로 띄우자고!', `MaleText_loc4`='我们的目的地是奥格瑞玛和艾萨拉。舰船宝贝儿，起航！', `MaleText_loc5`='目的地為奧格瑪和艾薩拉。讓這寶貝出海吧!', `MaleText_loc7`='Vamos de camino de Orgrimmar y Azshara. ¡Vamos a arrojar esta belleza en el mar!' WHERE `ID`=39617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발하는 섬에서 벗어나려면 함선에 동전을 넣어 주십시오.', `MaleText_loc4`='请把硬币插入船里，以驶离爆炸的岛屿。', `MaleText_loc5`='請投入硬幣至船中來離開正在爆炸的小島。', `MaleText_loc7`='Por favor, inserte monedas en el barco para que se aleje de la isla a punto de explotar.' WHERE `ID`=39618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돛을 올리기 바로 전에 피즈를 놀라게 해주자고. 내가 위쪽을 칠 테니 자네는 아래쪽을 쳐!', `MaleText_loc4`='让我们起航前先把菲兹扔出去。我抬头，你搬脚！', `MaleText_loc5`='在我們啟航前去偷襲費嘶。我攻擊上半身你負責下半身!', `MaleText_loc7`='Vamos a atacar a Fizz justo antes de zarpar. ¡Yo lanzo golpes altos y tú golpes bajos!' WHERE `ID`=39619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 풋내기를 처리해버리자, 에볼. 영원히 말이야. 아즈샤라는 우리 둘 다 있기엔 너무 좁아!', `MaleText_loc4`='让我们彻底解决那个废物吧，艾沃。艾萨拉没法同时容下我们两个人！', `MaleText_loc5`='讓我們對付伊柏那個垃圾，終結這一切。艾薩拉是個一山不容二虎的地方!', `MaleText_loc7`='Vamos a encargarnos de ese mequetrefe de Evol de una vez por todas. ¡Azshara no es lo bastante grande para los dos!' WHERE `ID`=39620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 해낼 줄 알았어! 우리 목숨을 구해준 거야.$B$B피즈와 에볼을 내 손으로 처리하는 상황이 오기 전에 여기서 나가자고.', `MaleText_loc4`='我就知道你能做到，$n！你救了我们。$B$B现在趁我还没杀死菲兹和艾沃，让我们赶快离开这儿。', `MaleText_loc5`='我就知道你可以，$n!你救了我們。$B$B在我殺了費嘶和伊柏前讓我們離開此地吧。', `MaleText_loc7`='¡Sabía que podrías, $n! Nos has salvado el pellejo.$b$bAhora salgamos de aquí antes de que tenga que matar a Fizz y a Evol.' WHERE `ID`=39621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='덕분에 얼마나 많은 시간과 금전이 절약되었는지 아시기나 해요, $n 님? 하마터면 엄청난 재앙이 될 뻔했어요. 그런데 단독으로 무역회사 전체를 구했어요.$B$B스랄 님과 당신이 갤리윅스를 용서한 건 상당히 맘에 안 들지만요. 당신은 훌륭한 $g무역 왕자:무역 공주;가 될 거예요!', `FemaleText_loc4`='你知道你为我们节省了多少宝贵的时间和金钱吗，$n？这原本有可能成为一场彻底的灾难，而你单凭一己之力就拯救了整个财阀。$B$B你和萨尔就这么放过了加里维克斯真是太可惜了。我想你肯定能成为一位杰出的贸易$g大王:女王;！', `FemaleText_loc5`='你知道你幫我們救回了多少錢和時間嗎，$n?這本來會是一個大災難，而你一個人救了整個企業。$B$B可惜你和索爾饒了加里維克斯一命，不然我覺得你一定會是一個很棒的貿易$g親王:女王;!', `FemaleText_loc7`='¿Tienes idea de todo el tiempo y la pasta que nos has ahorrado, $n? Esto podría haber terminado en un gran desastre, pero tú, sin ayuda alguna, has salvado al cártel entero.$B$BEs una pena que Thrall y tú hayan permitido vivir a Gallywix. ¡Creo que sería un $gpríncipe:princesa; mercante de primera!' WHERE `ID`=39622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무도 당신처럼 해낼 수 없을 거예요. $n 님, 갤리윅스를 왜 살려뒀는지 저로선 알 수 없어요. 그놈이 하던 일을 당신이 가로채야 했는데요.$B$B아즈샤라에 새로운 둥지를 틀겠다는 희망이 사라지지 말기를 바라요. 전 은퇴할 날을 고대한답니다.', `FemaleText_loc4`='没人能取得你的成就，$n。可我不明白为什么你没把加里维克斯拉下马。你本该接替他的职位。$B$B希望我们能顺利在艾萨拉安下新家。我盼望着能早点儿退休呢。', `FemaleText_loc5`='沒人能做到你所做到的，$n。你饒了加里維克斯是我所不解的。你應該要把他的頭銜給拿過來才對。$B$B現在我只希望在艾薩拉打造新的家園不會碰上太多困難。我很期待退休後的生活。', `FemaleText_loc7`='Nadie podría haber hecho lo que tú, $n. No entiendo por qué permitiste vivir a Gallywix. Deberías ocupar su puesto.$B$BEsperemos que todo vaya bien en nuestros esfuerzos por construir un nuevo hogar en Azshara. Estoy deseando jubilarme.' WHERE `ID`=39623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 너하고 얘기하는 게 아니야. 내가 너라면 올해에는 봉급 인상을 기대하지 않겠어, $n.', `MaleText_loc4`='我现在没和你说话。如果我是你，我决不会指望今年的加薪了，$n。', `MaleText_loc5`='我現在不是在跟你說話。如果我是你，我不會期待今年會加什麼薪的，$n。', `MaleText_loc7`='Ahora mismo estoy enfadado contigo. Si yo estuviera en tu lugar, no esperaría recibir un aumento este año, $n.' WHERE `ID`=39624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요! 이젠 살았습니다!', `MaleText_loc4`='你成功了！我们得救了！', `MaleText_loc5`='你辦到了!我們得救了!', `MaleText_loc7`='¡Lo has conseguido! ¡Estamos salvados!', `FemaleText_loc1`='해내셨군요! 이젠 살았어요!', `FemaleText_loc4`='你成功了！我们得救了！', `FemaleText_loc5`='你辦到了!我們得救了!', `FemaleText_loc7`='¡Lo has conseguido! ¡Estamos salvados!' WHERE `ID`=39625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 아즈샤라로 가는 겁니까? 거기에도 화산이 있습니까?', `MaleText_loc4`='我们真的要去艾萨拉吗？那里是不是也有一座火山？', `MaleText_loc5`='我們真的要飛到艾薩拉?那裡是不是也有座火山?', `MaleText_loc7`='¿Vamos a ir a Azshara? ¿Allí también hay un volcán?', `FemaleText_loc1`='정말 아즈샤라로 가는 건가요? 거기에도 화산이 있어요?', `FemaleText_loc4`='我们真的要去艾萨拉吗？那里是不是也有一座火山？', `FemaleText_loc5`='我們真的要飛到艾薩拉?那裡是不是也有座火山?', `FemaleText_loc7`='¿Vamos a ir a Azshara? ¿Allí también hay un volcán?' WHERE `ID`=39626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 어떻게 감사를 드려야 할지 모르겠습니다.', `MaleText_loc4`='我该怎么感谢你呢，$n？', `MaleText_loc5`='我該如何才能報答你，$n?', `MaleText_loc7`='¿Cómo podría agradecértelo, $n?', `FemaleText_loc1`='$n 님, 어떻게 감사를 드려야 할지 모르겠네요.', `FemaleText_loc4`='我该怎么感谢你呢，$n？', `FemaleText_loc5`='我該如何才能報答你，$n?', `FemaleText_loc7`='¿Cómo podría agradecértelo, $n?' WHERE `ID`=39627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신이라면 제 눈과 귀를 항상 열어두겠습니다. 당신 때문에 카자로 산과 잃어버린 섬의 화산이 폭발했다는 소문이 퍼지고 있으니까요.$B$B미친 소리죠. 저도 압니다. 그러나 대중은 무엇에든 소문을 만들어 내고 영웅을 밟아버리는 걸 좋아합니다. 특히나 그렇게 해서 무언가 얻어낼 게 있을 때는 말입니다.', `MaleText_loc4`='如果我是你，我就会放亮眼睛、竖起耳朵。有传闻说，卡亚罗和失落群岛的火山喷发都与你有关。$B$B我知道这听起来很疯狂。但人们八卦的素材总是千奇百怪，而且总以毁掉英雄为乐——尤其是在有利润和晋升驱使的情况下。', `MaleText_loc5`='我如果是你的話就會眼觀四面耳聽八方。謠言指出是你造成卡亞羅山和失落群島的火山爆發的。$B$B我知道這很瘋狂，但人們喜歡八卦，他們英雄負面的八卦，尤其是這可帶來利潤和升遷的時候。', `MaleText_loc7`='Si estuviera en tu lugar, mantendría los ojos y los oídos bien abiertos. Se rumorea que fuiste tú quien provocó la explosión de los volcanes del Monte Kajaro y de Las Islas Perdidas.$B$BEs una locura, lo sé. Pero a la gente le encanta cotillear y son capaces de despedazar a sus héroes, especialmente si con eso sacan tajada.', `FemaleText_loc1`='제가 당신이라면 제 눈과 귀를 항상 열어두겠어요. 당신 때문에 카자로 산과 잃어버린 섬의 화산이 폭발했다는 소문이 퍼지고 있으니까요.$B$B미친 소리죠. 저도 알아요. 그러나 대중은 무엇에든 소문을 만들어 내고 영웅을 밟아버리는 걸 좋아하죠. 특히나 그렇게 해서 무언가 얻어낼 게 있을 때는 말이에요.', `FemaleText_loc4`='如果我是你，我就会放亮眼睛、竖起耳朵。有传闻说，卡亚罗和失落群岛的火山喷发都与你有关。$B$B我知道这听起来很疯狂。但人们八卦的素材总是千奇百怪，而且总以毁掉英雄为乐——尤其是在有利润和晋升驱使的情况下。', `FemaleText_loc5`='我如果是你的話就會眼觀四面耳聽八方。謠言指出是你造成卡亞羅山和失落群島的火山爆發的。$B$B我知道這很瘋狂，但人們喜歡八卦，他們英雄負面的八卦，尤其是這可帶來利潤和升遷的時候。', `FemaleText_loc7`='Si estuviera en tu lugar, mantendría los ojos y los oídos bien abiertos. Se rumorea que fuiste tú quien provocó la explosión de los volcanes del Monte Kajaro y de Las Islas Perdidas.$B$BEs una locura, lo sé. Pero a la gente le encanta cotillear y son capaces de despedazar a sus héroes, especialmente si con eso sacan tajada.' WHERE `ID`=39628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화산이 우리 모두를 덮치기 전에 부두를 떠납시다!', `MaleText_loc4`='我们得在被火山杀死之前离开码头！', `MaleText_loc5`='讓我們在火山摧毀我們之前離開碼頭!', `MaleText_loc7`='¡Será mejor que zarpemos antes de que el volcán nos destruya a todos!', `FemaleText_loc1`='화산이 우리 모두를 덮치기 전에 부두를 떠나요!', `FemaleText_loc4`='我们得在被火山杀死之前离开码头！', `FemaleText_loc5`='讓我們在火山摧毀我們之前離開碼頭!', `FemaleText_loc7`='¡Será mejor que zarpemos antes de que el volcán nos destruya a todos!' WHERE `ID`=39629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 준비되면 떠나겠습니다, $n 님!', `MaleText_loc4`='等您准备好就能出发了，$g 阁下 : 女士;！', `MaleText_loc5`='你準備好了我們就準備好了，$g先生:女士;!', `MaleText_loc7`='¡Listo para partir cuando quieras, $gseñor:señora;!', `FemaleText_loc1`='당신이 준비되면 떠날게요, $n 님!', `FemaleText_loc4`='等您准备好就能出发了，$g 阁下 : 女士;！', `FemaleText_loc5`='你準備好了我們就準備好了，$g先生:女士;!', `FemaleText_loc7`='¡Listo para partir cuando quieras, $gseñor:señora;!' WHERE `ID`=39630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠습니다. 이곳을 그리워할 것 같군요. 여기서 꽤 잘 지냈으니 말입니다.', `MaleText_loc4`='我不知道。我想我会想念这里的。我们在这儿共度了不少美好时光。', `MaleText_loc5`='我很矛盾，我想我會想念這裡。我們在這有一些美好的回憶。', `MaleText_loc7`='No lo sé. Creo que voy a echar de menos este lugar. Aquí hemos pasado buenos momentos.', `FemaleText_loc1`='모르겠네요. 이곳을 그리워할 것 같아요. 여기서 꽤 잘 지냈으니 말이죠.', `FemaleText_loc4`='我不知道。我想我会想念这里的。我们在这儿共度了不少美好时光。', `FemaleText_loc5`='我很矛盾，我想我會想念這裡。我們在這有一些美好的回憶。', `FemaleText_loc7`='No lo sé. Creo que voy a echar de menos este lugar. Aquí hemos pasado buenos momentos.' WHERE `ID`=39631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 생각이 들었습니다... 이번에는 얼라이언스와 호드가 치르는 해상 전투 가운데서 헤매지 맙시다.$B$B그냥 말이 그렇다는 겁니다.', `MaleText_loc4`='我有个主意……这次我们别在联盟和部落的海战中徘徊了。$B$B我只是说说。', `MaleText_loc5`='我有個主意...我們這次就不要淌這場聯盟和部落海戰的混水了。$B$B我是這樣想的。', `MaleText_loc7`='Tengo una idea... Esta vez intentemos no inmiscuirnos en una batalla naval entre la Alianza y la Horda.$b$bLo digo solo por decir.', `FemaleText_loc1`='이런 생각이 들었는데요... 이번에는 얼라이언스와 호드가 치르는 해상 전투 가운데서 헤매지 말아요.$B$B그냥 말이 그렇다는 거예요.', `FemaleText_loc4`='我有个主意……这次我们别在联盟和部落的海战中徘徊了。$B$B我只是说说。', `FemaleText_loc5`='我有個主意...我們這次就不要淌這場聯盟和部落海戰的混水了。$B$B我是這樣想的。', `FemaleText_loc7`='Tengo una idea... Esta vez intentemos no inmiscuirnos en una batalla naval entre la Alianza y la Horda.$b$bLo digo solo por decir.' WHERE `ID`=39632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1을;를; 대지모신께서 굽어보시길. 도와주셔서 감사합니다.', `FemaleText_loc4`='愿大地母亲时刻护佑你，$n。谢谢你的帮助。', `FemaleText_loc5`='希望大地之母保護你，$n。謝謝你的幫忙。', `FemaleText_loc7`='Que la Madre Tierra te proteja, $n. Gracias por tu ayuda.' WHERE `ID`=39633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네 삶을 기리는 노래가 울려 퍼질 걸세. 다시 만날 때까지 말이네.', `MaleText_loc4`='你的生命之歌将永远激昂，$n。下次再见。', `MaleText_loc5`='你的事蹟將受後人讚嘆，$n。期待下次再見。', `MaleText_loc7`='Los poderosos cantarán las hazañas de tu vida, $n. Hasta que nos volvamos a ver.' WHERE `ID`=39634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라에서 해야 할 다른 일이 있으니, 자네와 함께 가겠네, $n.', `MaleText_loc4`='我在艾萨拉还有其它事情要解决，所以我会和你一起上路，$n。', `MaleText_loc5`='我在艾薩拉有要處理的事情，所以我會加入你，$n。', `MaleText_loc7`='Tengo asuntos que tratar en Azshara, $n, así que me reuniré contigo en el transcurso de tu viaje.' WHERE `ID`=39635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덩치는 작지만, 배포는 거인 같군. $n, 함께 해서 영광이었소!', `MaleText_loc4`='你有一颗巨人的心，$n。我无比荣幸！', `MaleText_loc5`='你的心與巨人一樣寬敞，$n。我很光榮!', `MaleText_loc7`='Tienes el corazón de un gigante, $n. ¡Ha sido un honor!' WHERE `ID`=39636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 끝인가 보네요. 정말 영광이었어요. 분명히 곧 다시 만날 거예요.', `FemaleText_loc4`='看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。', `FemaleText_loc5`='看來就到此為止了，老大，我很光榮。我相信我們很快就會再次相見。', `FemaleText_loc7`='Pues se acabó, $gjefe:jefa;. Ha sido un honor. Estoy segura de pronto nos volveremos a ver.' WHERE `ID`=39637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오너라. 그림 바톨 위로 날아가 데스윙에게 잊을 수 없는 일격을 날려보내자!', `MaleText_loc4`='欢迎你，朋友。我们一起直取格瑞姆巴托，给死亡之翼难忘的重重一击！', `MaleText_loc5`='歡迎你，朋友。讓我們穿越格瑞姆巴托給死亡之翼一個難以忘懷的重擊。', `MaleText_loc7`='Te doy la bienvenida, camarada. ¡Atravesemos Grim Batol y lancemos un ataque contra Alamuerte que no olvide fácilmente!' WHERE `ID`=39638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로글로스 오그 샨다이, 필멸자여. 오직 죽음만이 영원하다. 이제 죽음을 맞이하라...', `MaleText_loc4`='Log''loth og shandai，凡人。只有死亡才能永恒。你将不复存在。', `MaleText_loc5`='Log''loth og shandai，凡人。只有死亡是永恆的。你將會毀滅。', `MaleText_loc7`='Log''loth og shandai, mortal. Sólo la muerte es eterna. Serás destruido.' WHERE `ID`=39639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명은 믿음보다 강하다, 필멸자여. 기도해 봤자 소용없어.', `MaleText_loc4`='命运凌驾信仰之上，凡人。此时祈祷，毫无意义。', `MaleText_loc5`='宿命強於信仰，凡人。你的禱告在這裡毫無用處。', `MaleText_loc7`='El destino doblega a la fe, mortal. Tus plegarias son insignificantes aquí.' WHERE `ID`=39640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 시간 낭비만 하고 있잖습니까!', `MaleText_loc4`='你现在只是在浪费我的时间！', `MaleText_loc5`='你現在根本就是在浪費我的時間!', `MaleText_loc7`='¡Estás haciéndome perder el tiempo!', `FemaleText_loc1`='지금 시간 낭비만 하고 있잖아요!', `FemaleText_loc4`='你现在只是在浪费我的时间！', `FemaleText_loc5`='你現在根本就是在浪費我的時間!', `FemaleText_loc7`='¡Estás haciéndome perder el tiempo!' WHERE `ID`=39641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='啊哈！', `MaleText_loc5`='喂!', `MaleText_loc7`='¡Ah del barco!' WHERE `ID`=39642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다로 나간다아아아!', `MaleText_loc4`='我在航——行！', `MaleText_loc5`='開船開船!', `MaleText_loc7`='¡Navegooo!' WHERE `ID`=39643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이 멸망한다고 할 때마다 1실버씩 모았으면, 내가 지금 고블린 무역왕보다 더 부자다!', `MaleText_loc4`='如果我在每次听到世界末日即将到来的时候攒下一枚银币，那我现在就要比地精贸易巨头更富有了！', `MaleText_loc5`='如果每次我聽到世界末日的事情都能拿到一枚銀幣，那我一定會比那些哥布林的貿易大亨們還有錢!', `MaleText_loc7`='Si me dieran una moneda de plata por cada vez que he escuchado que se iba a acabar el mundo, ¡ahora sería más rico que un príncipe mercante goblin!', `FemaleText_loc1`='세상이 멸망한다고 할 때마다 1실버씩 모았으면, 내가 지금 고블린 무역왕보다 더 부자다!', `FemaleText_loc4`='如果我在每次听到世界末日即将到来的时候攒下一枚银币，那我现在就要比地精贸易巨头更富有了！', `FemaleText_loc5`='如果每次我聽到世界末日的事情都能拿到一枚銀幣，那我一定會比那些哥布林的貿易大亨們還有錢!', `FemaleText_loc7`='Si me dieran una moneda de plata por cada vez que he escuchado que se iba a acabar el mundo, ¡ahora sería más rica que un príncipe mercante goblin!' WHERE `ID`=39644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 이교도? 우리 오크족은 세상이 멸망해도 살아남은 경험이 있다고. 두려울 게 뭐야?', `MaleText_loc4`='末日教信徒？兽人已经经历过一次世界末日了，再来一次又能怎样？', `MaleText_loc5`='末日教徒?獸人已經從一個世界末日中活下來過，再一個世界末日又怎樣?', `MaleText_loc7`='¿Cultores del día del Juicio Final? Bueno, los orcos ya han sobrevivido a un fin del mundo, ¿qué importa otro más?', `FemaleText_loc1`='파멸의 이교도? 우리 오크족은 세상이 멸망해도 살아남은 경험이 있어. 두려울 게 뭐야?', `FemaleText_loc4`='末日教信徒？兽人已经经历过一次世界末日了，再来一次又能怎样？', `FemaleText_loc5`='末日教徒?獸人已經從一個世界末日中活下來過，再一個世界末日又怎樣?', `FemaleText_loc7`='¿Cultores del día del Juicio Final? Bueno, los orcos ya han sobrevivido a un fin del mundo, ¿qué importa otro más?' WHERE `ID`=39645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이교도들 싸그리 비행선에 태워 스톰윈드로 보내버려! 우리 오그리마엔 저런 녀석들 필요 없다고.', `MaleText_loc4`='把这些教徒都扔进一艘飞艇里。再让那艘飞艇飞到暴风城去！奥格瑞玛不需要这种人。', `MaleText_loc5`='把這些教徒裝在飛艇上送去暴風城!奧格瑪這邊不需要這種人。', `MaleText_loc7`='¡Mete a esos cultores en un zepelín y mándalos a Ventormenta! No necesitamos a esa gente en Orgrimmar.', `FemaleText_loc1`='이 이교도들 싸그리 비행선에 태워 스톰윈드로 보내버려! 우리 오그리마엔 저런 녀석들 필요 없다고.', `FemaleText_loc4`='把这些教徒都扔进一艘飞艇里。再让那艘飞艇飞到暴风城去！奥格瑞玛不需要这种人。', `FemaleText_loc5`='把這些教徒裝在飛艇上送去暴風城!奧格瑪這邊不需要這種人。', `FemaleText_loc7`='¡Mete a esos cultores en un zepelín y mándalos a Ventormenta! No necesitamos a esa gente en Orgrimmar.' WHERE `ID`=39646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어쩐지 옆집 친구가 갑자기 삭발을 하고 저런 로브를 입고 다닌다 했지. 어쩌면 안 쓰는 물건을 나 가지라고 줄지도 모르겠는데?', `MaleText_loc4`='嗯，我的邻居一定是为了这个才会剃掉头发，穿上这种袍子。也许他会把他的袍子借给我。', `MaleText_loc5`='喔，這八成就是我那位鄰居理了光頭、披上袍子的理由了。說不定他會把他的東西都給我。', `MaleText_loc7`='Vaya, entonces debe ser por eso que mi vecino se ha afeitado la cabeza y se viste con esas túnicas. Quizá deje que me quede con todas sus cosas.', `FemaleText_loc1`='아, 어쩐지 옆집 친구가 갑자기 삭발을 하고 저런 로브를 입고 다닌다 했지. 어쩌면 안 쓰는 물건을 나 가지라고 줄지도 모르겠는데?', `FemaleText_loc4`='嗯，我的邻居一定是为了这个才会剃掉头发，穿上这种袍子。也许他会把他的袍子借给我。', `FemaleText_loc5`='喔，這八成就是我那位鄰居理了光頭、披上袍子的理由了。說不定他會把他的東西都給我。', `FemaleText_loc7`='Vaya, entonces debe ser por eso que mi vecino se ha afeitado la cabeza y se viste con esas túnicas. Quizá deje que me quede con todas sus cosas.' WHERE `ID`=39647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 데 빠지는 사람들은 이해를 못 하겠단 말이야. 생각해 봐. 세상이 멸망하는데 과연 친절하게 미리 경고를 해주겠냐고?', `MaleText_loc4`='有谁会加入这种组织？如果世界真的会完蛋，那这种警告又有什么意义？', `MaleText_loc5`='誰要加入那種鬼玩意兒呀?如果這世界真要滅亡了，還會特地通知我們不成?', `MaleText_loc7`='¿Tú te unirías a algo así? Si el mundo se va a terminar de verdad, ¿en serio creen que avisarnos sirve para algo?', `FemaleText_loc1`='이런 데 빠지는 사람들은 이해를 못 하겠단 말이야. 생각해 봐. 세상이 멸망하는데 과연 친절하게 미리 경고를 해주겠어?', `FemaleText_loc4`='有谁会加入这种组织？如果世界真的会完蛋，那这种警告又有什么意义？', `FemaleText_loc5`='誰要加入那種鬼玩意兒呀?如果這世界真要滅亡了，還會特地通知我們不成?', `FemaleText_loc7`='¿Tú te unirías a algo así? Si el mundo se va a terminar de verdad, ¿en serio creen que avisarnos sirve para algo?' WHERE `ID`=39648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골목길과 어둠의 틈새를 다시 한 번 싹 청소할 때가 된 것 같군.', `MaleText_loc4`='看样子，现在已经是再次清理暗巷区和暗影裂口的时候了。', `MaleText_loc5`='看樣子，蠻兵清理暗巷區和暗影裂口的時候又到了。', `MaleText_loc7`='Parece que ya es hora de que los brutos limpien de nuevo la Calle Mayor y el Circo de las Sombras.', `FemaleText_loc1`='골목길과 어둠의 틈새를 다시 한 번 싹 청소할 때가 된 것 같군.', `FemaleText_loc4`='看样子，现在已经是再次清理暗巷区和暗影裂口的时候了。', `FemaleText_loc5`='看樣子，蠻兵清理暗巷區和暗影裂口的時候又到了。', `FemaleText_loc7`='Parece que ya es hora de que los brutos limpien de nuevo la Calle Mayor y el Circo de las Sombras.' WHERE `ID`=39649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 저어 나가세... 부두를 떠나 바다 저 멀리...', `MaleText_loc4`='泛舟乘海……远离湾岸……', `MaleText_loc5`='我在船上...不在碼頭上...', `MaleText_loc7`='En un bote... lejos del muelle…
' WHERE `ID`=39650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람을 안고 저 푸른 하늘과 세상 속으로...', `MaleText_loc4`='拥抱海风，天空澄明……', `MaleText_loc5`='飛啊飛啊，乘著風飛向天空...', `MaleText_loc7`='Como el viento, con el cielo y todo eso…
' WHERE `ID`=39651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오... 반짝거린다!', `MaleText_loc4`='哦……闪闪发光！', `MaleText_loc5`='哇...亮晶晶!', `MaleText_loc7`='Oooh... ¡Brilla!' WHERE `ID`=39652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 영혼이여, 이는 나 자신이 아니라 검은창 부족을 위해... 우리 트롤을 위해서이다.', `MaleText_loc4`='伟大的英灵，我并非为我一个人而祈祷，而是为了暗矛部族……为了我的人民。', `MaleText_loc5`='這並不是為了我自己，偉大的聖靈，這樣做是為了整個暗矛部族...為了我的子民。', `MaleText_loc7`='No sólo por mí, Gran Espíritu, por toda la Tribu Lanza Negra... por toda mi GENTE.' WHERE `ID`=39653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동기부여장치를 잃어버렸습니다. 하나 더 받을 수 있을까요?', `MaleText_loc4`='我的激励仪丢了，能再给我一台么？', `MaleText_loc5`='我的激勵裝置搞丟了。我可以再拿一個嗎?', `MaleText_loc7`='He perdido mi Motivatrón. ¿Podría tener otro?', `FemaleText_loc1`='동기부여장치를 잃어버렸습니다. 하나 더 받을 수 있을까요?', `FemaleText_loc4`='我的激励仪丢了，能再给我一台么？', `FemaleText_loc5`='我的激勵裝置搞丟了。我可以再拿一個嗎?', `FemaleText_loc7`='He perdido mi Motivatrón. ¿Podría tener otro?' WHERE `ID`=39654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 있으십니까?', `MaleText_loc4`='你想要什么吗？', `MaleText_loc5`='你要什麼嗎?', `MaleText_loc7`='¿Quieres algo?', `FemaleText_loc1`='원하는 게 있으신가요?', `FemaleText_loc4`='你想要什么吗？', `FemaleText_loc5`='你要什麼嗎?', `FemaleText_loc7`='¿Quieres algo?' WHERE `ID`=39655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 보여줄 거라도 있습니까?', `MaleText_loc4`='你有什么东西要给我看？', `MaleText_loc5`='你要給我看什麼嗎?', `MaleText_loc7`='¿Tienes algo que enseñarme?', `FemaleText_loc1`='제게 보여줄 거라도 있나요?', `FemaleText_loc4`='你有什么东西要给我看？', `FemaleText_loc5`='你要給我看什麼嗎?', `FemaleText_loc7`='¿Tienes algo que enseñarme?' WHERE `ID`=39656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 따라가죠. 별거 아닌 일이면 곤란합니다.', `MaleText_loc4`='好吧。我跟你来。这最好是重要的事。', `MaleText_loc5`='好吧，我跟你走。最好是什麼重要的事情。', `MaleText_loc7`='Vale. Iré contigo. Más vale que sea importante.', `FemaleText_loc1`='좋아요. 따라가죠. 별거 아닌 일이면 곤란해요.', `FemaleText_loc4`='好吧。我跟你来。这最好是重要的事。', `FemaleText_loc5`='好吧，我跟你走。最好是什麼重要的事情。', `FemaleText_loc7`='Vale. Iré contigo. Más vale que sea importante.' WHERE `ID`=39657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히히히! 어서 타시죠. 빨리 올라와요!', `MaleText_loc4`='上船来吧，快上来！', `MaleText_loc5`='上船了，快點。上前來!', `MaleText_loc7`='Sube a bordo, ya. ¡Pasa nomás!
' WHERE `ID`=39658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사미르 선장은 쉬지도 않고 간다네. 저 멀리 바다 끝으로 우릴 데려간다네!', `MaleText_loc4`='萨米尔船长将指引这艘船直达大洋彼岸……', `MaleText_loc5`='山米爾隊長在海洋的那邊不停地幫這艘船在做導航...', `MaleText_loc7`='El capitán Samir navega esta nave sin parar hasta el océano y más allá…
' WHERE `ID`=39659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 얼라이언스랑 투닥투닥 싸움질하는 곳으로! 우리는 얼라이언스 편!', `MaleText_loc4`='……我们将前往协助联盟，增援他们对部落的突袭。', `MaleText_loc5`='...我們會在那裡幫助聯盟進行與部落之間的小衝突戰。', `MaleText_loc7`='...donde comenzaremos a asistir a la Alianza en su batalla contra la Horda.
' WHERE `ID`=39660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈 벌기 쉽지, 히히히! 용병비는 살아남은 사람들끼리 나눠 가지는 거야!', `MaleText_loc4`='轻松赚钱！佣金将由所有幸存者平分，人人有份！', `MaleText_loc5`='真好賺!傭金會平均分配給所有的生還者!', `MaleText_loc7`='¡Dinero fácil! ¡Se repartirán comisiones para todos los sobrevivientes en partes iguales!
' WHERE `ID`=39661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아래로 내려갈 준비가 되었습니다.', `MaleText_loc4`='我已经准备好撤退了。', `MaleText_loc5`='我準備好上路了。', `MaleText_loc7`='Estoy listo para el viaje de regreso abajo.', `FemaleText_loc1`='아래로 내려갈 준비가 되었습니다.', `FemaleText_loc4`='我已经准备好撤退了。', `FemaleText_loc5`='我準備好上路了。', `FemaleText_loc7`='Estoy lista para el viaje de regreso abajo.' WHERE `ID`=39662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 정... 정말 아픕니다!', `MaleText_loc4`='哎呦！这可……这可真疼！', `MaleText_loc5`='啊!痛...痛死啦!', `MaleText_loc7`='¡Ay! ¡Eso... eso ha dolido!', `FemaleText_loc1`='아야! 정... 정말 아프잖아요!', `FemaleText_loc4`='哎呦！这可……这可真疼！', `FemaleText_loc5`='啊!痛...痛死啦!', `FemaleText_loc7`='¡Ay! ¡Eso... eso ha dolido!' WHERE `ID`=39663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 지원자를 모임 밖으로 불러내 가죽곤봉으로 때려 기절시키십시오.', `MaleText_loc4`='把暮光新兵从人群里带离，用硬铁棒将他击晕。', `MaleText_loc5`='把暮光志願兵從團隊中引出來後用皮頭敲擊棒將他擊昏。', `MaleText_loc7`='Aleja al recluta Crepuscular del grupo y utiliza la porra de tachuelas para dejarlo fuera de combate.', `FemaleText_loc1`='황혼의 지원자를 모임 밖으로 불러내 가죽곤봉으로 때려 기절시키십시오.', `FemaleText_loc4`='把暮光新兵从人群里带离，用硬铁棒将他击晕。', `FemaleText_loc5`='把暮光志願兵從團隊中引出來後用皮頭敲擊棒將他擊昏。', `FemaleText_loc7`='Aleja al recluta Crepuscular del grupo y utiliza la porra de tachuelas para dejarlo fuera de combate.' WHERE `ID`=39664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Starting test.  Casting trigger spell now.', `MaleText_loc4`='测试开始。正在施放触发法术。', `MaleText_loc5`='開始測試。施展觸發法術中。', `MaleText_loc7`='Iniciando prueba. Lanzando hechizo activador.' WHERE `ID`=39665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Trigger spell received. Idling.', `MaleText_loc4`='触发法术已收到。闲置中。', `MaleText_loc5`='收到觸發法術。暫停中。', `MaleText_loc7`='Hechizo activador recibido. En pausa.' WHERE `ID`=39666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로미, 이 시간의 동굴에서 무슨 일이 일어났는지 우리 둘 다 알고 있습니다. 예전에 다 본 적이 있으니 그냥 일이 일어나기 바로 직전으로 넘어가면 안 되겠습니까?', `MaleText_loc4`='克罗米，你和我都知道在这个时间流中会出什么事。我们以前都遇到过这种情形。你能不能略过这些部分，直接进入真正的行动？', `MaleText_loc5`='克羅米，你和我都知道在這條時間流會發生什麼事情。我們都親眼見過這一切。$B$B你能不能把我們跳到實際採取行動的時間點去?', `MaleText_loc7`='Cromi, tú y yo sabemos lo que va a ocurrir a continuación. Ya lo hemos visto antes. ¿No podemos saltárnoslo todo y pasar a la acción de verdad?', `FemaleText_loc1`='크로미, 이 시간의 동굴에서 무슨 일이 일어났는지 우리 둘 다 알고 있잖아요. 예전에 다 본 적이 있으니 그냥 일이 일어나기 바로 직전으로 넘어가면 안 될까요?', `FemaleText_loc4`='克罗米，你和我都知道在这个时间流中会出什么事。我们以前都遇到过这种情形。你能不能略过这些部分，直接进入真正的行动？', `FemaleText_loc5`='克羅米，你和我都知道在這條時間流會發生什麼事情。我們都親眼見過這一切。$B$B你能不能把我們跳到實際採取行動的時間點去?', `FemaleText_loc7`='Cromi, tú y yo sabemos lo que va a ocurrir a continuación. Ya lo hemos visto antes. ¿No podemos saltárnoslo todo y pasar a la acción de verdad?' WHERE `ID`=39667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞아요. 예전에 여기서 당신을 만났었어요! 그걸 어떻게 잊어버리겠어요!$B$B원한다면 지금 바로 스트라솔름으로 순간이동시켜 드릴게요.', `FemaleText_loc4`='没错，我曾在这里见过你！我怎么会忘记呢？$B$B如果你愿意的话，我可以立刻把你传送到斯坦索姆去。', `FemaleText_loc5`='沒錯，我見過你!我怎麼會忘記呢?$B$B如果你想要的話，我可以現在就把你傳送到斯坦索姆。', `FemaleText_loc7`='¡Claro! ¡Sí que te había visto aquí antes! ¿Cómo he podido olvidarlo?$B$BPuedo teletransportarte a Stratholme ahora si quieres.' WHERE `ID`=39668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 황혼의 눈이시여, 미천한 이 종을 이끄소서!', `MaleText_loc4`='伟大的暮光之眼，引导你谦卑的奴仆吧！', `MaleText_loc5`='強大的暮光之眼，引導你謙卑的侍從!', `MaleText_loc7`='¡Poder del Ojo del Crepúsculo, guía a tu humilde siervo!' WHERE `ID`=39669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀하십시오, 황혼의 눈이시여.', `MaleText_loc4`='请说吧，暮光之眼。', `MaleText_loc5`='說話，暮光之眼。', `MaleText_loc7`='Habla, Ojo del Crepúsculo.' WHERE `ID`=39670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 내리시겠습니까, 황혼의 눈이시여?', `MaleText_loc4`='你有何指示，暮光之眼？', `MaleText_loc5`='你的命令是什麼，暮光之眼?', `MaleText_loc7`='¿Cuáles son tus órdenes, Ojo del Crepúsculo?' WHERE `ID`=39671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선장님! 우현 쪽으로 난파선 파편입니다! 생존자가 있는 것 같아요!', `FemaleText_loc4`='船长！右舷下方发现船骸，好像还有幸存者！', `FemaleText_loc5`='隊長!右舷發現了船難的殘骸!看來似乎有生還者!', `FemaleText_loc7`='¡Capitán! ¡Naufragio a estribor! ¡Parece que hay sobrevivientes!' WHERE `ID`=39672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 둘 달린 녀석은 어딨어? 황혼의 눈이 이번엔 뭐라고 하나?', `MaleText_loc4`='双头在哪儿？暮光之眼正在告诉我们什么？', `MaleText_loc5`='「雙頭」在哪?眼睛正在跟我們說什麼?', `MaleText_loc7`='¿Dónde está dos cabezas? ¿Qué decir Ojo ahora?' WHERE `ID`=39673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 마지막으로 황혼의 눈하고 이야기했나? 황혼의 눈은 기분 좋나? 가르골에게 말해라!', `MaleText_loc4`='谁最后和眼睛说话的？眼睛高兴吗？快告诉伽格尔！', `MaleText_loc5`='最後跟眼睛說話的是誰?眼睛開心嗎?跟加爾勾說!', `MaleText_loc7`='¿Quién fue último en hablar con el Ojo? ¿Estaba contento? ¡Decir a Gar''gol!' WHERE `ID`=39674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴이 너무 지저분해! 쓰레기는 표시해 둔 곳에만 버려라.', `MaleText_loc4`='洞里太脏了！把污物放在标有旗子的污物堆上吧。', `MaleText_loc5`='洞穴太骯髒了!把髒東西放在有旗標的穢物堆裡。', `MaleText_loc7`='¡La cueva está demasiado sucia! Poner porquería en pilas de porquería y marcarlas con una bandera.' WHERE `ID`=39675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르골 저녁 시간이다! 요리사를 데려와. 음식 없으면 요리사를 요리해라.', `MaleText_loc4`='伽格尔的大餐时间！去找厨师。如果大餐没有准备好，就把厨师煮了。', `MaleText_loc5`='加爾勾的晚餐時間!去叫主廚。如果晚餐還沒好，就吃主廚當晚餐。', `MaleText_loc7`='¡Hora de cenar para Gar''gol! Ir a por cocinero. Cocinar al cocinero si cena no está lista.' WHERE `ID`=39676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈은 은밀하게 말한다. 난 눈이 시키는 대로 한다! 너희는 가르골이 시키는 대로 한다!', `MaleText_loc4`='眼睛用暗语交谈。我照眼睛说的做！你们照伽格尔说的做！', `MaleText_loc5`='眼球在暗影中說話。我照眼球說的做!你照加爾勾說的做!', `MaleText_loc7`='El Ojo hablar en lenguaje de las Sombras. ¡Yo hacer lo que el Ojo decir! ¡Tú hacer lo que Gar''gol decir!' WHERE `ID`=39677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에는 입술이 없지만, 가르골에게는 속삭인다. 눈은 모든 걸 알고 있다!', `MaleText_loc4`='眼睛没有嘴唇，可眼睛偷偷说给伽格尔听。眼睛无所不知！', `MaleText_loc5`='眼睛沒有嘴唇，但眼睛對加爾勾呢喃。眼睛什麼都知道!', `MaleText_loc7`='El Ojo no tener labios, pero el Ojo susurra a Gar''gol. ¡El Ojo saber todo!' WHERE `ID`=39678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기에서 하는 일이 마음에 안 들면, 눈하고 얘기해라. 하지만 말을 들어주진 않을걸. 귀가 아니라 눈이니까.', `MaleText_loc4`='要是你对我们不满意，就去跟眼睛说。可眼睛不会听。它不是耳朵。', `MaleText_loc5`='如果你不喜歡我們在這所做的，你可以跟眼睛說。但它不會聽，它不是耳朵。', `MaleText_loc7`='Si no te gusta lo que hacemos aquí, hablar con el Ojo. Pero no escuchará. No es el Oído.' WHERE `ID`=39679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버드한텐 신경 쓰지 마십시오... 가엾게도 정신줄을 놨답니다.', `MaleText_loc4`='别去理会巴德……那伙计的脑子里少了几根筋。', `MaleText_loc5`='別理霸德...那倒楣蛋的腦子少了幾根螺絲。', `MaleText_loc7`='No le prestes atención a Budd... le faltan unos cuantos tornillos.' WHERE `ID`=39680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군요, $n! 제단을 되찾았습니다!', `MaleText_loc4`='你成功了，$n！神殿又是我们的了！', `MaleText_loc5`='你辦到了，$n!神殿再次是屬於我們的了!', `MaleText_loc7`='¡Lo has conseguido, $n! ¡El santuario es nuestro de nuevo!', `FemaleText_loc1`='해냈군요, $n! 제단을 되찾았어요!', `FemaleText_loc4`='你成功了，$n！神殿又是我们的了！', `FemaleText_loc5`='你辦到了，$n!神殿再次是屬於我們的了!', `FemaleText_loc7`='¡Lo has conseguido, $n! ¡El santuario es nuestro de nuevo!' WHERE `ID`=39681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 내 직접 너희의 피로 내 손을 적시리라! (캬하하하하! 없애! 없애!)', `MaleText_loc4`='够了！我要亲自来对付你。（呵哈哈哈哈！杀啊！杀啊！）', `MaleText_loc5`='夠了!我將親自用你的血來洗手!(哈哈哈～～殺呀殺呀)', `MaleText_loc7`='¡Suficiente! ¡Me mancharé las manos con tu sangre! (¡Muerte!)' WHERE `ID`=39682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천치 같은 것들! 죽고 싶으냐! (놈들의 최후를 보여줘.)', `MaleText_loc4`='真可怜！看看我精兵真正的力量吧……', `MaleText_loc5`='可悲!準備好見識我所選擇之人的厲害...', `MaleText_loc7`='¡Patético! Contempla el verdadero poder de mi elegido...' WHERE `ID`=39683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이언 듀란이 야영지에서 기다리고 있습니다.', `MaleText_loc4`='伊安·杜兰正在营地里等你。', `MaleText_loc5`='伊安·杜蘭在營中等你。', `MaleText_loc7`='Ian Duran te espera en el campamento.', `FemaleText_loc1`='이언 듀란이 야영지에서 기다리고 있어요.', `FemaleText_loc4`='伊安·杜兰正在营地里等你。', `FemaleText_loc5`='伊安·杜蘭在營中等你。', `FemaleText_loc7`='Ian Duran te espera en el campamento.' WHERE `ID`=39684;
