UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이 멸망한다고 할 때마다 1실버씩 모았으면, 내가 지금 고블린 무역왕보다 더 부자가 됐겠다!', `MaleText_loc4`='如果我在每次听到世界末日即将到来的时候攒下一枚银币，那我现在就要比地精贸易巨头更富有了！', `MaleText_loc5`='如果每次我聽到世界末日的事情都能拿到一枚銀幣，那我一定會比那些哥布林的貿易大亨們還有錢!', `MaleText_loc7`='Si me dieran una moneda de plata por cada vez que he escuchado que se iba a acabar el mundo, ¡ahora sería más rico que un príncipe mercante goblin!', `FemaleText_loc1`='세상이 멸망한다고 할 때마다 1실버씩 모았으면, 내가 지금 고블린 무역왕보다 더 부자가 됐겠다!', `FemaleText_loc4`='如果我在每次听到世界末日即将到来的时候攒下一枚银币，那我现在就要比地精贸易巨头更富有了！', `FemaleText_loc5`='如果每次我聽到世界末日的事情都能拿到一枚銀幣，那我一定會比那些哥布林的貿易大亨們還有錢!', `FemaleText_loc7`='Si me dieran una moneda de plata por cada vez que he escuchado que se iba a acabar el mundo, ¡ahora sería más rica que un príncipe mercante goblin!' WHERE `ID`=39689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이 멸망한다고? 골치 아픈 데피아즈단원부터 먼저 처리하고 생각해보지.', `MaleText_loc4`='末日教信徒？在那些迪菲亚暴徒之后，我们又有新的麻烦了。', `MaleText_loc5`='末日預言教徒?在迪菲亞暴徒帶來了一堆麻煩之後，我們需要的正是這個。', `MaleText_loc7`='¿Cultores del día del Juicio Final? Justo lo que nos hacía falta después de todos los problemas con los matones de la Hermandad Defias.', `FemaleText_loc1`='세상이 멸망한다고? 골치 아픈 데피아즈단원부터 먼저 처리하고 생각해보지.', `FemaleText_loc4`='末日教信徒？在那些迪菲亚暴徒之后，我们又有新的麻烦了。', `FemaleText_loc5`='末日預言教徒?在迪菲亞暴徒帶來了一堆麻煩之後，我們需要的正是這個。', `FemaleText_loc7`='¿Cultores del día del Juicio Final? Justo lo que nos hacía falta después de todos los problemas con los matones de la Hermandad Defias.' WHERE `ID`=39690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈의 이교도들 좀 누가 배에 태워서 소용돌이로 안 보내나! 스톰윈드에 이런 놈들은 필요 없다고!', `MaleText_loc4`='把这些教徒都扔进一艘船里。再让那艘船驶进大漩涡里去！暴风城不需要这种人。', `MaleText_loc5`='把這些教徒綁在船上然後丟進大漩渦裡去!暴風城才不需要這種鬼傢伙!', `MaleText_loc7`='¡Mete a esos cultores en un barco y mándalos de regreso a La Vorágine! No necesitamos a esa gente en Ventormenta.', `FemaleText_loc1`='이놈의 이교도들 좀 누가 배에 태워서 소용돌이로 안 보내나! 스톰윈드에 이런 놈들은 필요 없다고!', `FemaleText_loc4`='把这些教徒都扔进一艘船里。再让那艘船驶进大漩涡里去！暴风城不需要这种人。', `FemaleText_loc5`='把這些教徒綁在船上然後丟進大漩渦裡去!暴風城才不需要這種鬼傢伙!', `FemaleText_loc7`='¡Mete a esos cultores en un barco y mándalos de regreso a La Vorágine! No necesitamos a esa gente en Ventormenta.' WHERE `ID`=39691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 옆집 사람이 머리카락을 밀고 로브를 뒤집어 쓴 이유가 바로 이거로군. 나도 그 사람한테 물건을 얻을 수 있을 거야.', `MaleText_loc4`='嗯，我的邻居一定是为了这个才会剃掉头发，穿上这种袍子。也许他会把他的财产给我。', `MaleText_loc5`='喔，這一定就是為何我的鄰居會剃光頭髮、披上袍子的原因。也許他會把他的東西都給我。', `MaleText_loc7`='Vaya, entonces debe ser por eso que mi vecino se ha afeitado la cabeza y se viste con esas túnicas. Quizá deje que me quede con todas sus cosas.', `FemaleText_loc1`='흠, 옆집 사람이 머리카락을 밀고 로브를 뒤집어 쓴 이유가 바로 이거로군. 나도 그 사람한테 물건을 얻을 수 있을 거야.', `FemaleText_loc4`='嗯，我的邻居一定是为了这个才会剃掉头发，穿上这种袍子。也许他会把他的财产给我。', `FemaleText_loc5`='喔，這一定就是為何我的鄰居會剃光頭髮、披上袍子的原因。也許他會把他的東西都給我。', `FemaleText_loc7`='Vaya, entonces debe ser por eso que mi vecino se ha afeitado la cabeza y se viste con esas túnicas. Quizá deje que me quede con todas sus cosas.' WHERE `ID`=39692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도들은 세상에 종말이 온다고 경고하면 우리가 걱정이라도 할 줄 안 건가?', `MaleText_loc4`='如果世界真的要完了，难道这些教徒警告我们还有什么意义吗？', `MaleText_loc5`='如果這世界即將走向終點，那些教徒真的以為警不警告我們有啥差別嗎?', `MaleText_loc7`='Si el mundo se va a terminar de verdad, ¿en serio creen que avisarnos sirve para algo?', `FemaleText_loc1`='이교도들은 세상에 종말이 온다고 경고하면 우리가 걱정이라도 할 줄 안 건가?', `FemaleText_loc4`='如果世界真的要完了，难道这些教徒警告我们还有什么意义吗？', `FemaleText_loc5`='如果這世界即將走向終點，那些教徒真的以為警不警告我們有啥差別嗎?', `FemaleText_loc7`='Si el mundo se va a terminar de verdad, ¿en serio creen que avisarnos sirve para algo?' WHERE `ID`=39693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병이 구 시가지를 다시 청소할 때가 왔군.', `MaleText_loc4`='看样子，该是让卫兵再次清理旧城区的时候了。', `MaleText_loc5`='看來，是時候了，再次派守衛去掃蕩舊城區。', `MaleText_loc7`='Parece que ya es hora de que los guardias limpien de nuevo el Casco Antiguo.', `FemaleText_loc1`='경비병이 구 시가지를 다시 청소할 때가 왔군.', `FemaleText_loc4`='看样子，该是让卫兵再次清理旧城区的时候了。', `FemaleText_loc5`='看來，是時候了，再次派守衛去掃蕩舊城區。', `FemaleText_loc7`='Parece que ya es hora de que los guardias limpien de nuevo el Casco Antiguo.' WHERE `ID`=39694;
