UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갠은 고개를 한쪽으로 늘어뜨린 채 거친 숨을 내쉬고 있습니다.$B$B당신이 온 걸 알아채지 못한 것 같습니다.', `MaleText_loc4`='加恩的头歪向一侧，呼吸变得越发没有节律。$B$B他没有注意到你的到来。', `MaleText_loc5`='加恩的頭轉到了一邊，呼吸變得不規率。$B$B他對你的存在毫無反應。', `MaleText_loc7`='La cabeza de Gann cae hacia un lado y su respiración se vuelve entrecortada.$B$BSi te ha visto, no hace nada para darlo a entender.' WHERE `ID`=39705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원격 조종 폭죽을 어디 잘못 두었나 봅니다.', `MaleText_loc4`='我似乎把远程遥控焰火放错地方了。', `MaleText_loc5`='我似乎把遙控煙火放錯地方了。', `MaleText_loc7`='Al parecer he perdido los fuegos artificiales teledirigidos.', `FemaleText_loc1`='원격 조종 폭죽을 어디 잘못 두었나 봐요.', `FemaleText_loc4`='我似乎把远程遥控焰火放错地方了。', `FemaleText_loc5`='我似乎把遙控煙火放錯地方了。', `FemaleText_loc7`='Al parecer he perdido los fuegos artificiales teledirigidos.' WHERE `ID`=39706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 알았어. 여기 여분이 있어. 나는 폭죽의 화신이니까...', `MaleText_loc4`='哦，当然，这儿还有一些特别的。我可是焰火专业户……', `MaleText_loc5`='當然啦，這裡有更多。我這到處都是煙火....', `MaleText_loc7`='Bueno, claro, aquí tienes algunos extra. Prácticamente estoy hecho de fuegos artificiales...' WHERE `ID`=39707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 우리의 생명을 앗아 갈지도 모른다. 하지만 절대로 앗아 가지 못할 것이 하나 있으니...', `MaleText_loc4`='他们也许会夺走我们的生命，但他们永远也无法夺走……', `MaleText_loc5`='他們也許能取走我們的生命，但是他們絕對無法取走...', `MaleText_loc7`='Pueden quitarnos la vida, pero jamás nos quitarán...' WHERE `ID`=39708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기 있는 제군들에게 바라는 것은 이 구역에 있는 급유소, 주거지, 창고, 농장, 닭장, 화장실, 개집의 정확한 위치를 파악해 오는 것이다.', `MaleText_loc4`='你们要搜遍每个补给站，每个居民点，每一座仓库、农舍、鸡窝、厕所和狗屋。哪怕钻进地心也要把目标找出来！', `MaleText_loc5`='我要你們每個人做的，就是在這區域裡所有的加油站、住家、倉庫、農場、雞舍、廁所和狗屋進行地毯式搜索。', `MaleText_loc7`='Lo que quiero de ustedes es que registren en profundidad cada estación de reabastecimiento, cada residencia, almacén, granja, gallinero, retrete exterior o caseta de perro en esta zona.' WHERE `ID`=39709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤에 몰래 쳐들어가지 않을 것이다! 사라지더라도 제대로 싸워보고 사라지겠다!', `MaleText_loc4`='我们不会沉默地堕入黑夜！我们不会不经一战就自行消失！', `MaleText_loc5`='我們不會在夜色中無聲無息地離開!我們不會不戰而敗!', `MaleText_loc7`='¡No desapareceremos en silencio en la oscuridad! ¡No nos desvaneceremos sin luchar!' WHERE `ID`=39710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 충분히 통할 것 같아요. 자신감을 갖고 좀 더 강하게 밀어붙여 보세요!', `MaleText_loc4`='嗯，我猜它可能会有用。但它至少还要再诱人一些！', `MaleText_loc5`='嗯，我想這應該行得通。但是內容應該要再豐富一點吧!', `MaleText_loc7`='Mmm, supongo que podría funcionar. ¡Pero me vendría bien un poco más de empuje!' WHERE `ID`=39711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요? 대체 무슨 말을 하는지 알 수가 없네요. 최악이에요!', `FemaleText_loc4`='什么？我甚至不知道你在说些什么！这太恐怖了！', `FemaleText_loc5`='什麼?我甚至聽不懂你在說啥!真是太糟糕了!', `FemaleText_loc7`='¿Qué? ¡Ni siquiera sé de qué estás hablando! ¡Es terrible!' WHERE `ID`=39712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔직하군! 아, 아니에요. 살짝 손을 보고 정리하면 좀 괜찮아질 것 같기도 하네요.', `MaleText_loc4`='太可怕了！好吧，也许它只是需要被清理一下？', `MaleText_loc5`='有夠爛! 好吧，可能只需要稍微潤一下稿就行了?', `MaleText_loc7`='¡Terrible! Bueno, quizá haya que limpiarlo un poquito.' WHERE `ID`=39713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도달 아문 리다엘 보르모스! 보르모스! 보르모스!', `MaleText_loc4`='Thoth''al amun Ree''thael vormos！Vormos！Vormos！', `MaleText_loc5`='Thoth''al amun Ree''thael vormos! Vormos! Vormos!', `MaleText_loc7`='¡Thoth''al amun Ree''thael vormos! ¡Vormos! ¡Vormos!' WHERE `ID`=39714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알다, 알다, 보르마즈, 니 보르마즈 타달? 옵니다, 불속을 걸어 옵니다, $r|1이여;여;!', `MaleText_loc4`='Al''tha， Al''tha bormaz， Ni bormaz ta''thall？它来了，它行走在火焰中，$r！', `MaleText_loc5`='Al''tha, Al''tha bormaz。Ni bormaz ta''thall?他要是敢來，就會全身燒起來，$r!', `MaleText_loc7`='Al''tha, Al''tha bormaz. ¿Ni bormaz ta''thall? ¡Se acerca, camina en las llamas, $r!' WHERE `ID`=39715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자가 보고 있습니다. 보알 랄 아르위 크토스. 조용한 불길 속에 종말이 다가옵니다.', `MaleText_loc4`='阴影看得见。Bo''al lal arwi C''toth。末日即将来临，掩藏在无声的烈焰之中。', `MaleText_loc5`='睿智的暗影。Bo''al lal arwi C''toth。末日到來，被沉默的火焰所籠罩。', `MaleText_loc7`='El sombra ve. Bo''al lal arwi C''toth. El fin se acerca, cubierto de fuego silencioso.' WHERE `ID`=39716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마르코와 탈롤 예타린, 알고 있습니다. 그것은 알고 있습니다.', `MaleText_loc4`='Mar''kowa tallol ye''tarin，它知道，它明白。', `MaleText_loc5`='Mar''kowa tallol ye''tarin，它知道的，它知道的。', `MaleText_loc7`='Mar''kowa tallol ye''tarin, lo sabe, lo sabe.' WHERE `ID`=39717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무한의 깊은 곳으로부터 두려움이 끝없이 일고 있습니다. 저에게 보여주지 마십시오! 이미 견딜 수 없을 만큼 봤습니다!', `MaleText_loc4`='恐惧从永恒之心内蒸腾而出。别逼我看！我所看到的一切已经超出了我的承受极限！', `MaleText_loc5`='無盡的恐懼從心中沸騰。別讓我看!我已經無法承受我所見的了!', `MaleText_loc7`='El temor se abrasa en el corazón del infinito. ¡No me obligues a mirar! ¡He visto más de lo que puedo soportar!' WHERE `ID`=39718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 아무것도 아닙니다. 투랄 파로코스. 파르알, 카카르. 공허가 삼켜 버립니다.', `MaleText_loc4`='我们什么都不是。Tulall par''okoth。Far''al, ka''kar。虚空吞噬一切。', `MaleText_loc5`='我們什麼都不是。Tulall par''okoth。Far''al, ka''kar。虛無吞噬一切。', `MaleText_loc7`='No somos nada. Tulall par''okoth. Far''al, ka''kar. El vacío devora.' WHERE `ID`=39719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<황혼의 복종자가 입에 하얀 거품을 물고 웅얼거리며 당신을 쳐다봅니다.>', `MaleText_loc4`='<暮光仆从向你“嘎嘎”地叫着，白色的泡沫从嘴角边淌了下来。>', `MaleText_loc5`='<暮光僕從對你發出咯咯的聲音，嘴邊冒出了白色的唾液泡泡。>', `MaleText_loc7`='<El servidor Crepuscular balbucea y de su boca mana espuma blanca.>' WHERE `ID`=39720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐쏜, 어둠의 기둥이 보이지 않는 곳까지 뻗어 가고 있습니다. 흐쏜 마르울 쿠알라. 무한한 밤의 손길이여.', `MaleText_loc4`='H''thon，黑暗的幕帘延伸到视野之外。H''thon marwol qualar：面对黑暗的永恒之握。', `MaleText_loc5`='H''thon，黑暗之柱在肉眼看不到的地方展開。H''thon marwol qualar:黑夜無盡的擁抱。', `MaleText_loc7`='H''thon, la columna de oscuridad que se extiende más allá de donde alcanza la vista. H''thon marwol qualar: la comprensión infinita de la noche.' WHERE `ID`=39721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그건 바로 우리의 혁신 정신이다!', `MaleText_loc4`='……我们的发明！', `MaleText_loc5`='...我們的新發明!', `MaleText_loc7`='¡...nuestra INNOVACIÓN!' WHERE `ID`=39722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들이 찾아야 할 자의 이름은 기계박사 텔마플러그라네.', `MaleText_loc4`='那个逃亡者的名字是机械师瑟玛普拉格。', `MaleText_loc5`='那個逃犯的名字是機電師瑟瑪普拉格。', `MaleText_loc7`='El nombre del fugitivo que buscamos es mekigeniero Termochufe.' WHERE `ID`=39723;
