UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 죽지 않는다! 우리는 살아남을 것이다! 기억하라. 오늘은 우리의...', `MaleText_loc4`='虽然历经劫难，但我们还是会生存下去！今天，我们要庆祝……', `MaleText_loc5`='我們會繼續活著!我們會存活下去!今天我們要慶祝...', `MaleText_loc7`='¡Vamos a vivir! ¡Sobreviviremos! Hoy celebramos...' WHERE `ID`=39725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...자율 투쟁의 날이다!', `MaleText_loc4`='……我们终于夺回了主权！', `MaleText_loc5`='...我們獲得自主權的這天!', `MaleText_loc7`='...¡nuestro Día de la Independencia!' WHERE `ID`=39726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 늑대의 터에서 당신과 다른 사람들이 풀어 준 황혼의 노예들이 야영지로 모여들고 있지만, 어떻게 된 일인지 자신에 대해 말하지는 못하고 수수께끼 같은 말만 하며 횡설수설하고 있어요.$B$B저는 황혼의 망치단이 옛날 방식으로 노예들을 부린다고 생각했어요. 채찍이나 쇠사슬 같은 것들로 말이죠. 지금 보니 뭔가 다른 방법으로 노예를 세뇌시키는 게 분명해요...
', `FemaleText_loc4`='$n，你们从狼神小径救出来的那些暮光奴隶进了营地，可他们无法讲明他们的身份，语言也含混不清。$B$B我原本以为暮光之锤是以古老的方式对待奴隶——你知道，就是鞭子和锁链那种——但很显然，他们还加入了洗脑的步骤……', `FemaleText_loc5`='$n，你跟其他人在狼之小徑搭救的暮光奴隸正在往營地前進，但他們無法跟我說他們是誰，並出口就是謎語和胡言亂語。$B$B我以為暮光之錘會用傳統的方法來控制這些奴隸，像是鞭子和鐵鏈。很明顯他們還使用了洗腦這種手段...', `FemaleText_loc7`='$n, los esclavos Crepusculares que tú y otros habéis estado rescatando de la Senda del Lobo, están vagando por el campamento. Pero no pueden decirme quiénes son, hablan como en acertijos y no dicen más que tonterías.$B$BYo creía que el Martillo Crepuscular mantenía a los esclavos a raya al viejo estilo, ya sabes, látigos y cadenas, pero está claro que les han sometido también a algún tipo de lavado de cerebro...' WHERE `ID`=39727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스틸그릴의 정비소 내에 있어야 합니다.', `MaleText_loc4`='你必须留在钢架补给站。', `MaleText_loc5`='你必須待在鋼架補給站。', `MaleText_loc7`='Debes permanecer en el Almacén de Brasacerada.', `FemaleText_loc1`='스틸그릴의 정비소 내에 있어야 합니다.', `FemaleText_loc4`='你必须留在钢架补给站。', `FemaleText_loc5`='你必須待在鋼架補給站。', `FemaleText_loc7`='Debes permanecer en el Almacén de Brasacerada.' WHERE `ID`=39728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<물약을 먹입니다.>', `MaleText_loc4`='<给予药剂。>', `MaleText_loc5`='<施用藥劑。>', `MaleText_loc7`='<Administra el jarabe.>', `FemaleText_loc1`='<물약을 먹입니다.>', `FemaleText_loc4`='<给予药剂。>', `FemaleText_loc5`='<施用藥劑。>', `FemaleText_loc7`='<Administra el jarabe.>' WHERE `ID`=39729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어라? 내가 왜 여기 있는 거지? 여기서 도망쳐야 해!', `MaleText_loc4`='什——什么？我这是在哪儿？我得从这儿离开！', `MaleText_loc5`='什...什麼?我在哪裡?我必須離開這!', `MaleText_loc7`='¿Do-dónde? ¿Dónde estoy? ¡Tengo que salir de aquí!' WHERE `ID`=39730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있었던 거죠? 전 떠납니다!', `MaleText_loc4`='我这是怎么了？我要离开了！', `MaleText_loc5`='我發生了什麼事?我要離開!', `MaleText_loc7`='¿Qué me ha sucedido? ¡Me marcho!' WHERE `ID`=39731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 내가 지금 무슨 말을 하고 있는 거죠? 말도 안 되는 말을... 여길 나가야겠어요!', `MaleText_loc4`='……我在说什么？这已经没意义了。我要离开这个地方！', `MaleText_loc5`='...我在說什麼?一切都不合理了。我必須離開這個地方!', `MaleText_loc7`='¿... Qué estoy diciendo? Ya nada tiene sentido. ¡Tengo que salir de este sitio!' WHERE `ID`=39732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뇌가 ... 너무 ... 아파!', `MaleText_loc4`='我的……头……好疼！', `MaleText_loc5`='我的...腦袋...痛啊!', `MaleText_loc7`='¡Me... duele... el cerebro!' WHERE `ID`=39733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 덕분에 절 따라다니던 목소리가 사라졌습니다. 전 여길 벗어나겠습니다!', `MaleText_loc4`='哇，你让那些声音消失了。我得走了！', `MaleText_loc5`='哇，你讓聲音消失了。我要離開這裡!', `MaleText_loc7`='Eh, has hecho que desaparezcan las voces. ¡Me marcho de aquí!' WHERE `ID`=39734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 내게 무슨 짓을 한 거지? 야영지로 돌아가야 해...', `MaleText_loc4`='他们对我做了什么？我得回营地去……', `MaleText_loc5`='他們對我做了什麼?我必須回到營地...', `MaleText_loc7`='¿Qué me han hecho? Tengo que regresar al campamento...' WHERE `ID`=39735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖에 일은 잘 돼 가나요? 풀려난 노예들과 대화하려고 하는데 정말 머리가 아프네요.$B$B다들 정신이 오락가락해요.
', `FemaleText_loc4`='运气怎么样？试着和那些被解救的奴隶交谈真让我头痛不已。$B$B他们口齿不清的发着刺耳的噪音，然而还很押韵。', `FemaleText_loc5`='你那邊怎麼樣?跟這些被放出來的奴隸說話真是讓我頭痛啊。$B$B他們的隊列真是歪七扭八。', `FemaleText_loc7`='¿Has tenido suerte? El mero intento de mantener una conversación con los esclavos liberados hace que me duela la cabeza.$B$BEstán justo en la frontera entre la discordancia y la rima.' WHERE `ID`=39736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와줘서 고마워요, $n 님.
', `FemaleText_loc4`='谢谢你的帮助，$n。', `FemaleText_loc5`='謝謝你的幫忙，$n。', `FemaleText_loc7`='Gracias por tu ayuda, $n.' WHERE `ID`=39737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신은 돌아왔지만 기뻐해야 할지 모르겠군요.$B$B그 사실을 알아버렸으니... 우리에게 일어날 일을 말입니다...$B$B<몸서리를 치고는 말을 잃은 황혼의 복종자>', `MaleText_loc4`='不知恢复神智是不是件好事。$B$B我所知道的一切……也许即将发生在这世界上的一切……$B$B<他战栗着陷入了沉默。>', `MaleText_loc5`='我不知道取回自己的意識究竟是不是好事。$B$B知道了我原本所知道的...知道我們的世界將面臨什麼...$b$b<他發著抖進入沉默。>', `MaleText_loc7`='No estoy muy seguro de que sea bueno que haya recuperado mi mente.$B$BSaber lo que sé... Saber lo que quizá le suceda a nuestro mundo... $b$b<Siente un escalofrío y guarda silencio.>' WHERE `ID`=39738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 고맙습니다, $c님.$B$B다음 짐마차를 기다려 이곳을 벗어나겠습니다. 하지만... 제가 예전의 모습으로 돌아갈 수 있을까요...', `MaleText_loc4`='多谢你救了我们，$c。$B$B我们要护送下一个车队下山，但……我不认为我还会犯同样的错误……', `MaleText_loc5`='謝謝你雇用我們，$c。$B$B我們將護送下個車隊離開這座山，但...我不知道我是否還是一樣...', `MaleText_loc7`='Gracias por rescatarnos, $c.$B$BAcompañaremos a la próxima caravana que parta de esta montaña pero... No creo que alguna vez vuelva a ser el mismo.' WHERE `ID`=39739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 가만히 놔두시오, 이방인이여. 우린 당신에게 아무 짓도 안 했소.', `MaleText_loc4`='放过我们吧，陌生人。我们没有对你做任何事。', `MaleText_loc5`='別惹我們，陌生人。我們沒得罪你。', `MaleText_loc7`='Tú no eres de aquí, déjanos en paz. No te hemos hecho nada.', `FemaleText_loc1`='우리를 가만히 놔두시오, 이방인이여. 우린 당신에게 아무 짓도 안 했소.', `FemaleText_loc4`='放过我们吧，陌生人。我们没有对你做任何事。', `FemaleText_loc5`='別惹我們，陌生人。我們沒得罪你。', `FemaleText_loc7`='Tú no eres de aquí, déjanos en paz. No te hemos hecho nada.' WHERE `ID`=39740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 도시의 삶에서 벗어나 이곳에서 우리의 운명을 기다리고 있소. 이곳에서 우리는 진실에 눈을 떴소.', `MaleText_loc4`='我们远离这座城市中的生活，在这里等待我们的命运，倾心领受最真实的真相。', `MaleText_loc5`='我們離開了都市的生活，來到這裡等待我們的宿命，在這裡我們得知了真相。', `MaleText_loc7`='Hemos abandonado nuestra vida en la ciudad para esperar a nuestro destino aquí, donde la verdad nos ha sido revelada.', `FemaleText_loc1`='우리는 도시의 삶에서 벗어나 이곳에서 우리의 운명을 기다리고 있소. 이곳에서 우리는 진실에 눈을 떴소.', `FemaleText_loc4`='我们远离这座城市中的生活，在这里等待我们的命运，倾心领受最真实的真相。', `FemaleText_loc5`='我們離開了都市的生活，來到這裡等待我們的宿命，在這裡我們得知了真相。', `FemaleText_loc7`='Hemos abandonado nuestra vida en la ciudad para esperar a nuestro destino aquí, donde la verdad nos ha sido revelada.' WHERE `ID`=39741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께하겠소? 도시에 있는 우리 전도사들이 당신이 무엇을 해야 하는지 알려줄 것이오.', `MaleText_loc4`='你想要加入我们？我们在这座城市中的信使将告诉你必须怎样去做，寻觅者。', `MaleText_loc5`='你想要加入我們嗎?我們在城裡有使者會告訴你必要的條件，搜尋者。', `MaleText_loc7`='¿Deseas unirte a nosotros? Hemos enviado mensajeros a la ciudad que te dirán lo que tienes que hacer, aspirante.', `FemaleText_loc1`='우리와 함께하겠소? 도시에 있는 우리 전도사들이 당신이 무엇을 해야 하는지 알려줄 것이오.', `FemaleText_loc4`='你想要加入我们？我们在这座城市中的信使将告诉你必须怎样去做，寻觅者。', `FemaleText_loc5`='你想要加入我們嗎?我們在城裡有使者會告訴你必要的條件，搜尋者。', `FemaleText_loc7`='¿Deseas unirte a nosotros? Hemos enviado mensajeros a la ciudad que te dirán lo que tienes que hacer, aspirante.' WHERE `ID`=39742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수대는 칼림도어 전 지역에서 호드를 저지하고 있습니다. 잿빛 골짜기와 돌발톱 산맥에서는 전투가 계속되고 있지요. 하지만 이곳에도 우리 파수대가 필요합니다. 남은 야생 동물들을 보호하고, 우리의 적이 더는 근거지를 마련하지 못하도록 막아야 하니까요.', `FemaleText_loc4`='哨兵部队在卡利姆多各地阻挡部落的攻势。当灰谷与石爪山相继被战火席卷之时，这里也需要我们的帮助——我们要保护那些仅存的野生动植物，并阻止我们的敌人攻占更为纵深的据点。', `FemaleText_loc5`='哨兵部隊在整個卡林多抗衡著部落的軍隊。但戰爭繼續在梣谷和石爪山脈進行，這裡也需要我們的力量，來保護野生動植物和阻止我們的敵人擴大勢力。', `FemaleText_loc7`='Las tropas del ejército de los centinelas mantienen a raya a la Horda por todo Kalimdor. Mientras la guerra continúa en Vallefresno y Sierra Espolón, también aquí necesitan a nuestras tropas para proteger las tierras salvajes que quedan y evitar que nuestros enemigos avancen aún más.' WHERE `ID`=39743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 하는 거냐, 이 $c 녀석아! 당장 그것에서 손 떼지 못해?', `MaleText_loc4`='你以为你在干什么，$c？离那些工具远点儿！', `MaleText_loc5`='你在幹什麼，$c?離那些裝置遠一點!', `MaleText_loc7`='¿Qué crees que estás haciendo, $c? ¡Aléjate de esos instrumentos!' WHERE `ID`=39744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 눈을 조종할 수 없다! 초갈 님께서 곧 아실 거야. 네놈은... 대가를 치를 것이다.', `MaleText_loc4`='你无法……控制眼睛！古加尔会知道的。你将受到……惩罚。', `MaleText_loc5`='你無法...無法控制眼睛!丘加利會發現，而你...會被...懲罰。', `MaleText_loc7`='¡No puedes... controlar el Ojo! Cho''gall lo sabrá. Serás... castigado.' WHERE `ID`=39745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕카토크에게 가자!', `MaleText_loc4`='带我去梅卡托克那里！', `MaleText_loc5`='帶我去見梅卡托克!', `MaleText_loc7`='¡Llévame donde Mekkatorque!', `FemaleText_loc1`='멕카토크에게 가주렴!', `FemaleText_loc4`='带我去梅卡托克那里！', `FemaleText_loc5`='帶我去見梅卡托克!', `FemaleText_loc7`='¡Llévame donde Mekkatorque!' WHERE `ID`=39746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명을 주는 태양은 영원히 지고, 끝없는 망각의 밤이 시작된다! (파멸이 보인다! 파멸이 부른다...)', `MaleText_loc4`='生命之日将永远落下，空无之夜即将降临。(毁灭迫近了!它在呼唤!)', `MaleText_loc5`='生命的太陽會永遠沈下，而光明會被無盡的夜晚吞噬。(遺忘要來了，他在呼喊～～)', `MaleText_loc7`='El sol de la vida se pondrá para siempre, y la luz dará paso a la noche eterna. (¡El olvido se acerca! ¡Llama!)' WHERE `ID`=39747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단은 이 위대한 파괴의 도구이자 영광스러운 파멸의 수단이다. (장막을 찢어. 마음을 열고 공허를 받아들여.) 우리를 통해서 너희는 진정한 힘을 얻을 것이다!', `MaleText_loc4`='暮光之锤是带来伟大毁灭的造物，是让一切化为虚无的荣耀之光！（别再迷茫了！向虚无敞开你的心智吧！）真正的力量就在我们手中！', `MaleText_loc5`='暮光之錘是這個大災變的工具，也是榮光之毀滅的導演!(把面紗撕爛，放空你的意志)透過我們，你將見識絕對的力量!', `MaleText_loc7`='¡El Martillo Crepuscular es el instrumento de esta destrucción, el método de la aniquilación gloriosa! (¡Rasga su velo! ¡Abre tu mente al vacío!) Con nosotros tendrás poder de verdad.' WHERE `ID`=39748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동참하라. (동참하라!) 그리하면 넘쳐나는 힘을 얻을 것이다! (힘! 그분의 힘, 그분의 권능...)', `MaleText_loc4`='加入我们，（加入我们！）你们将获得超乎想象的力量！（力量！他的力量！强大的力量！）', `MaleText_loc5`='加入我們(加入我們!)來獲得無上的力量!(力量，他的力量，他的神力!)', `MaleText_loc7`='¡Únetenos (¡Únetenos!) y recibe una fuerza inconmensurable! (¡Fuerza! ¡Su FUERZA! ¡Su PODER!)' WHERE `ID`=39749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 황혼의 눈이다... 새로운 주인을 받들라!', `MaleText_loc4`='我是暮光之眼……快来认识你们的新主人吧！', `MaleText_loc5`='我是暮光之眼...臣服於你新的主人之下吧!', `MaleText_loc7`='Yo soy el Ojo del Crepúsculo... ¡Contempla a tu nuevo amo!', `FemaleText_loc1`='나는 황혼의 눈이다... 새로운 주인을 받들라!', `FemaleText_loc4`='我是暮光之眼……快来认识你们的新主人吧！', `FemaleText_loc5`='我是暮光之眼...臣服於你新的主人之下吧!', `FemaleText_loc7`='Yo soy el Ojo del Crepúsculo... ¡Contempla a tu nuevo amo!' WHERE `ID`=39750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘에서 너희의 할 일은 끝났다. 왔던 곳으로 돌아가거라.', `MaleText_loc4`='你在海加尔的工作已经完成——回到你的来时之地吧。', `MaleText_loc5`='你已經完成你在海加爾的工作 - 回到你來的地方去。', `MaleText_loc7`='Ya has terminado lo que tenías que hacer en Hyjal... Regresa al lugar del que provienes.', `FemaleText_loc1`='하이잘에서 너희의 할 일은 끝났다. 왔던 곳으로 돌아가거라.', `FemaleText_loc4`='你在海加尔的工作已经完成——回到你的来时之地吧。', `FemaleText_loc5`='你已經完成你在海加爾的工作 - 回到你來的地方去。', `FemaleText_loc7`='Ya has terminado lo que tenías que hacer en Hyjal... Regresa al lugar del que provienes.' WHERE `ID`=39751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 명령을 내리는 자는 모두 죽여라. 황혼의 눈이 명하노라!', `MaleText_loc4`='消灭任何胆敢有异议的人。听从眼睛的号令！', `MaleText_loc5`='將所有意見不一的人殺了。這是眼睛的命令!', `MaleText_loc7`='Mata a todos los que te digan lo contrario. ¡Palabra del Ojo!', `FemaleText_loc1`='다른 명령을 내리는 자는 모두 죽여라. 황혼의 눈이 명하노라!', `FemaleText_loc4`='消灭任何胆敢有异议的人。听从眼睛的号令！', `FemaleText_loc5`='將所有意見不一的人殺了。這是眼睛的命令!', `FemaleText_loc7`='Mata a todos los que te digan lo contrario. ¡Palabra del Ojo!' WHERE `ID`=39752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 방해하러 온 건가요, 이방인이여?', `FemaleText_loc4`='为何来这里打扰我们，陌生人？', `FemaleText_loc5`='外來者，你是來這打擾我們的嗎?', `FemaleText_loc7`='Tú no eres de aquí. ¿Has venido a molestarnos?' WHERE `ID`=39753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두려워하지 마세요, $c|1이여;여;. 우리는 진실을 찾는 모든 이들을 환영해요.', `FemaleText_loc4`='不要害怕，$c。我们全心接受所有寻觅真相的人。', `FemaleText_loc5`='別害怕，$c。我們會擁抱任何尋求真理的人。', `FemaleText_loc7`='No tengas miedo, $c. Nosotros damos la bienvenida a todos los que buscan la verdad.' WHERE `ID`=39754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그저 가만히 있고 싶을 뿐입니다. 왜 그렇게 못 알아 들으시나요?', `MaleText_loc4`='我们只希望能不被打扰。为什么这一点就如此难以被理解？', `MaleText_loc5`='我們只想與世無爭地過日子。這真的有那麼難理解嗎?', `MaleText_loc7`='Solo queremos que nos dejen en paz. ¿Por qué es tan difícil de entender?' WHERE `ID`=39755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말이 다가오고 있지만, 아직 바로잡을 시간은 있습니다, $c.', `MaleText_loc4`='世界末日即将到来，但现在还有时间纠正一切，$c。', `MaleText_loc5`='$c，世界破碎的腳步逐漸逼近，但是我們還是有足夠時間可以做出正確的事情。', `MaleText_loc7`='Se acerca el fin del mundo, pero aún hay tiempo para arreglar las cosas, $c.' WHERE `ID`=39756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리에 무슨 의미가 있겠느냐, 벌레야. (어둠이 온다...) 이래 봤자 어차피 세상은 썩어갈 텐데.', `MaleText_loc4`='享受你们空虚的胜利吧，害虫们。（黑暗降临了……）愿它成为你们腐烂世界的安慰。', `MaleText_loc5`='享受你們空洞的勝利，蟲子們。(黑暗降臨...)讓這成為你們世界腐壞時的慰藉吧!', `MaleText_loc7`='Disfruten su victoria vacía, insectos. (Llega la oscuridad...) Que los consuele mientras su mundo se pudre.' WHERE `ID`=39757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c 친구. 나한테 궁금한 게 많을 거라 생각하오.$B$B짧게 말하겠소. 로이스 더스크위스퍼가 "황혼의 눈" 작전이라는 쓸데없는 걸 시킨다고 나를 오우거 동굴 한가운데로 보냈는데, 일이 좀 꼬였소.$B$B그 비쩍 마르고, 비열한 데다가, 거짓말이나 해대는 나이트 엘프 녀석, 내 손에 잡히는 날엔...$B$B<크리스토프가 공중에 매달린 채로 무력하게 꿈틀거리며 얼굴을 붉힙니다.>', `MaleText_loc4`='你好啊，$c。我想你一定有很多问题要问。$B$B简单说吧，罗伊斯·暮语把我派到这个食人魔洞穴里干什么与暮光之眼相关的活计，可进展得并不顺利。$B$B要是我能抓住那个皮包骨头、没心没肺、油嘴滑舌的暗夜小精灵……$B$B<倒吊在空中的克里斯托弗无助的扭动着，脸涨得通红。>', `MaleText_loc5`='嗨，$c。我相信你一定有很多的問題。$B$B基本上，羅伊斯·暮語將我送進了巨魔的巢穴調查一個叫「暮光之眼」的東西，但進行的不是很順利。$B$B就不要讓我再碰到那又黑心又虛偽的死竹竿夜精靈...$b$b<克里斯多夫在半空中無助地掙扎扭動，臉脹得越來越紅。>', `MaleText_loc7`='Hola, $c. Supongo que tienes un montón de preguntas.$B$BBasta con que te diga que Royce Susurro del Anochecer me envió al corazón de una cueva llena de ogros en busca de algo llamado "Ojo del Crepúsculo", un trabajo fácil que no ha ido muy bien.$B$BSi alguna vez le pongo las manos encima a ese pequeño elfo de la noche desgarbado, cruel y de palabras comedidas...$B$B<Kristoff se retuerce mientras cuelga en el aire, con el rostro sonrojado.>' WHERE `ID`=39758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 돌아가십시오. 가족들이 걱정하고 있습니다.', `MaleText_loc4`='你应该回奥格瑞玛去。你的家人都很担心。', `MaleText_loc5`='你該回去奧格瑪。你的家人正在擔心著。', `MaleText_loc7`='Deberías regresar a Orgrimmar. Tu familia está preocupada.', `FemaleText_loc1`='오그리마로 돌아가세요. 가족들이 걱정하고 있어요.', `FemaleText_loc4`='你应该回奥格瑞玛去。你的家人都很担心。', `FemaleText_loc5`='你該回去奧格瑪。你的家人正在擔心著。', `FemaleText_loc7`='Deberías regresar a Orgrimmar. Tu familia está preocupada.' WHERE `ID`=39759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니에요. 나는 오그리마로 돌아가지 않겠어요. 가족들에게는 슬픈 일이겠지만, 가족은 가족만의, 나는 나만의 선택을 한 거예요. 내 미래를 여기, 바로 내가 선택한 형제들과 함께하겠어요.', `FemaleText_loc4`='不，我不能回奥格瑞玛。我也在为家人伤心，但他们已经做出了选择，我也做出了我的选择。我的未来在这里，在我的兄弟姐妹中间。', `FemaleText_loc5`='不，我不能回奧格瑪。我為家人感到難過，但是他們做出了他們的決定，而我也做出屬於我的選擇。我的未來就在這，在我選擇的教友這裡。', `FemaleText_loc7`='No, no puedo volver a Orgrimmar. Sufro por mi familia, pero ellos han tomado su decisión y yo la mía. Mi futuro está aquí, entre mis hermanos que yo he elegido.' WHERE `ID`=39760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족들이 당신에 대해 물어봤습니다. 많이 걱정하더군요.', `MaleText_loc4`='你的家人正在找你。他们很担心。', `MaleText_loc5`='你的家人問起你的事情。他們很擔心。', `MaleText_loc7`='Tu familia ha preguntado por ti. Están preocupados.', `FemaleText_loc1`='가족들이 당신에 대해 물어봤어요. 많이 걱정하고 있었어요.', `FemaleText_loc4`='你的家人正在找你。他们很担心。', `FemaleText_loc5`='你的家人問起你的事情。他們很擔心。', `FemaleText_loc7`='Tu familia ha preguntado por ti. Están preocupados.' WHERE `ID`=39761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 떠나지 않겠어요. 가족들에게 내가 여기서 잘 지내고 있으니 가족들도 잘 지내라고 전해 주세요.', `FemaleText_loc4`='我不会离开的。告诉我的家人，我在这里很好，也希望他们过得好。', `FemaleText_loc5`='我不會走的。告訴我的家人，我在這感受到平靜，我希望他們過得很好。', `FemaleText_loc7`='No me marcharé. Di a mi familia que aquí me encuentro en paz y que les deseo todo lo mejor.' WHERE `ID`=39762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가는, 저도... 승천할 거예요.', `FemaleText_loc4`='有一天，我也会升华。', `FemaleText_loc5`='總有一天，我也會獲得不死之身。', `FemaleText_loc7`='Algún día, yo también ascenderé.' WHERE `ID`=39763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도시의 그 많은 사람 중 여기 있는 몇 명만이 정령들의 경고를 귀담아 듣다니 정말 놀랍군요.', `FemaleText_loc4`='在这样一座大城市里，注意到元素发出警告的人却屈指可数，这真令我感到惊诧。', `FemaleText_loc5`='在一個人口如此眾多的城市之中，竟然只有一小部份人察覺到元素的警訊，真是令我訝異。', `FemaleText_loc7`='Me sorprende que en una ciudad llena de gente, tan solo unos pocos prestaran atención a las advertencias de los elementos.' WHERE `ID`=39764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열심히 싸우십시오, $c. 예언이 이루어지기 전까지 우리의 목표를 완수하려면 시간이 얼마 없습니다.', `MaleText_loc4`='努力工作吧，$c。我们完成任务的时间已经不多了。预言即将实现。', `MaleText_loc5`='認真點，$c。在完成預言之前，剩下沒多少時間能讓我們完成任務。', `MaleText_loc7`='Trabaja duro, $c. Tenemos poco tiempo para completar nuestras tareas antes de que se cumplan las profecías.' WHERE `ID`=39765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상은 곧 종말을 맞겠지만, 우리는 모두 함께 승천해 정령들의 힘을 물려받게 될 것입니다.', `MaleText_loc4`='我们的世界很快就要完结。但我们将共同得到升华，得到元素的力量。', `MaleText_loc5`='我們這個世界就要滅亡了，但是只要團結起來，我們能夠化為不朽之身，並繼承元素的力量。', `MaleText_loc7`='Nuestro mundo pronto llegará a su fin, pero juntos ascenderemos y heredaremos el poder de los elementos.' WHERE `ID`=39766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 가족들은 당신이 오그리마로 되돌아오기를 바랍니다.', `MaleText_loc4`='你的家人希望你能回到奥格瑞玛去。', `MaleText_loc5`='你的家人希望你回奧格瑪。', `MaleText_loc7`='Tu familia quiere que regreses a Orgrimmar.', `FemaleText_loc1`='당신 가족들은 당신이 오그리마로 되돌아오기를 바라고 있어요.', `FemaleText_loc4`='你的家人希望你能回到奥格瑞玛去。', `FemaleText_loc5`='你的家人要你回去奧格瑪。', `FemaleText_loc7`='Tu familia quiere que regreses a Orgrimmar.' WHERE `ID`=39767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 좀 나오?', `MaleText_loc4`='你闻到什么了吗？', `MaleText_loc5`='你有聞到什麼嗎?', `MaleText_loc7`='¿Hueles algo?' WHERE `ID`=39768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 손을 빌려 주고 싶소만, 사슬... 두드러기가 있어서. 잠시 뒤에 있겠소.', `MaleText_loc4`='我很愿意帮你，可我被……链子缠住了。我只能往回晃一点儿。', `MaleText_loc5`='我很想幫忙，但我現在...在跟鐵鏈做伴。我還是先待在後面好了。', `MaleText_loc7`='Te echaría una mano pero me ha salido... un sarpullido. Creo que mejor voy un poquito por detrás de ti.' WHERE `ID`=39769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 특이한 $c|1이요;요;, $n. 나쁜 뜻은 아니오. 단지 좀 재미있는 친구 같아서 말이오.', `MaleText_loc4`='你可真是个与众不同的$c，$n。我不是在说你坏话。我只是说，你还挺有趣儿。', `MaleText_loc5`='你真是個不平凡的$c，$n。這沒有任何負面的意思。我只是想說你蠻有趣的。', `MaleText_loc7`='Eres $gun:una; $c de lo más inusual, $n. No lo digo en el sentido negativo. Es solo que eres un poco $graro:rara;.' WHERE `ID`=39770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 얼마나 오래 매달려 있었냐고? 한 며칠은 된 것 같소만.', `MaleText_loc4`='我吊在那儿多久了？感觉应该有好多天了。', `MaleText_loc5`='我被吊在那多久了?感覺有一整天。', `MaleText_loc7`='¿Cuánto tiempo llevaba ahí colgado? Tengo la impresión de que han sido días.' WHERE `ID`=39771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇠사슬에 저렇게 매달리는 건 그다지 추천할 일은 아니오만, 솔직히 말하면 덕분에 머리는 꽤 멋있어졌다오.', `MaleText_loc4`='像那样吊在链子上的滋味可不怎么好。不过，老实说，那对我头发有好处。', `MaleText_loc5`='我不建議被鐵鏈吊成那樣。但老實說，這對我的頭髮還不錯。', `MaleText_loc7`='No te recomiendo que te cuelgues de una cadena como yo. Pero, para ser sincero, me ha quedado un pelo muy chulo.' WHERE `ID`=39772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거들.$B$B난 오우거를 증오하오.', `MaleText_loc4`='食人魔。$B$B我恨食人魔。', `MaleText_loc5`='巨魔。$B$B我恨巨魔。', `MaleText_loc7`='Ogros.$B$BOdio a los ogros.' WHERE `ID`=39773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구를 죽일 일이 있으면 항상 그렇게 말이 많소?', `MaleText_loc4`='当有东西给你杀时，你总是话那么多吗？', `MaleText_loc5`='你在有東西可以殺的時候廢話都那麼多嗎?', `MaleText_loc7`='¿Siempre hablas tanto cuando hay cosas que matar?' WHERE `ID`=39774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 쓸데없는 말은 줄이고, 오우거에 집중하기요. 알겠소?', `MaleText_loc4`='少说废话，多杀点儿食人魔。好吗？', `MaleText_loc5`='你少耍點笨，多打點巨魔。可以嗎?', `MaleText_loc7`='Menos charlar y más machacar ogros, ¿trato hecho?' WHERE `ID`=39775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족들은 저와 함께할 기회를 얻었는데도 오히려 제 믿음을 비웃기만 했습니다. 그들은 이제 제게 아무런 의미가 없습니다.', `MaleText_loc4`='他们本来有机会和我在一起。但他们却只是嘲笑我的信仰。他们对我已经毫无意义了。', `MaleText_loc5`='他們曾經有機會和我一起走，而不是嘲弄我的信念。對我而言他們什麼也不是。', `MaleText_loc7`='Tuvieron la oportunidad de venir conmigo y, en vez de eso, se burlaron de mis creencias. Ya no significan nada para mí.' WHERE `ID`=39776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 아내가 많이 걱정하고 있습니다. 그녀는 당신이 오그리마로 돌아오기를 바라고 있습니다.', `MaleText_loc4`='你的妻子很想你。她想让你回奥格瑞玛去。', `MaleText_loc5`='你的妻子很擔心你。她希望你回去奧格瑪。', `MaleText_loc7`='Tu mujer está preocupada por ti. Quiere que regreses a Orgrimmar.', `FemaleText_loc1`='당신 아내가 많이 걱정하고 있어요. 그녀는 당신이 오그리마로 돌아오기를 바라고 있어요.', `FemaleText_loc4`='你的妻子很想你。她想让你回奥格瑞玛去。', `FemaleText_loc5`='你的妻子很擔心你。她希望你回去奧格瑪。', `FemaleText_loc7`='Tu mujer está preocupada por ti. Quiere que regreses a Orgrimmar.' WHERE `ID`=39777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 내가 같이 가고 싶어했다는 걸 모르는 겁니까? 난 아직 젊습니다. 죽기 싫단 말입니다. 앞으로도 계속 행복하려면 이 방법밖에 없습니다. 그녀에게 이 말을 전해 주십시오. 그리고 알아듣도록 해 주십시오.', `MaleText_loc4`='难道她不明白？我希望她能到我身边来。我很年轻，我还不想死。我们还要共渡许多美好的岁月。而这是唯一能让我们活下去的办法。把这些告诉她，请一定让她明白。', `MaleText_loc5`='她還不明白我要她跟我一起走嗎?我還年輕;我不想死。我們的未來應該有許多好時光，而這是唯一的方法。將這些話轉告她。讓她了解。', `MaleText_loc7`='¿Acaso no se da cuenta de que yo quería que ella viniera conmigo? Soy joven, no quiero morir. Aún deberíamos tener por delante muchos años felices juntos y esta es la única manera de tenerlos. Díselo. Haz que lo comprenda.' WHERE `ID`=39778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소, 한번 해 봅시다! 당신이 오우거와 싸우는 동안, 난... 싸움을 피하겠소. 자, 출구로 갑시다!', `MaleText_loc4`='好吧，就这么办！你对付食人魔，我……就不对付他们了。我去找出口！', `MaleText_loc5`='好，我們開打吧!你去跟巨魔戰鬥，而我...不去跟巨魔戰鬥。朝出口前進!', `MaleText_loc7`='¡Bien, lo haremos así! Tú luchas contra los ogros y yo... Yo no lucho. ¡Yo busco la salida!' WHERE `ID`=39779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에게 한 번 더 기회를 주시는 겁니까? 다시는 실패하지 않겠습니다!', `MaleText_loc4`='又给了我一次效力的机会？我不会再失败了！', `MaleText_loc5`='我又獲得了一次機會嗎?我這次絕對不會失敗!', `MaleText_loc7`='¿Tengo otra oportunidad de servir? ¡No volveré a fallar!', `FemaleText_loc1`='저에게 한 번 더 기회를 주시는 건가요? 다시는 실패하지 않겠어요!', `FemaleText_loc4`='又给了我一次效力的机会？我不会再失败了！', `FemaleText_loc5`='我又獲得了一次機會嗎?我這次絕對不會失敗!', `FemaleText_loc7`='¿Tengo otra oportunidad de servir? ¡No volveré a fallar!' WHERE `ID`=39780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자가 쓸만한 동맹을 골랐군. ...딱하게도 내 손에 끝장나겠지만!', `MaleText_loc4`='阿莱克丝塔萨选对了盟友……很可惜，你们都将死在这里！', `MaleText_loc5`='雅立史卓莎派了可靠的盟友過來....可惜你們都會死在我手中!', `MaleText_loc7`='Alexstrasza ha elegido aliados capaces... ¡Una pena que tenga que ELIMINARLOS!' WHERE `ID`=39781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 있으리라 생각했나?', `MaleText_loc4`='不要心存侥幸！', `MaleText_loc5`='你以為你有機會贏?', `MaleText_loc7`='¿Creían que podrían?' WHERE `ID`=39782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 잘 된 일이군.', `MaleText_loc4`='这是最好的结局。', `MaleText_loc5`='這樣就對了。', `MaleText_loc7`='Mejor así.' WHERE `ID`=39783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할리온 님! 저는...', `MaleText_loc4`='海里昂，我……', `MaleText_loc5`='海萊恩!我....', `MaleText_loc7`='¡HALION! Yo...' WHERE `ID`=39784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들을 재로 만들어버려라!', `MaleText_loc4`='让他们化为灰烬，仆从们！', `MaleText_loc5`='去吧!將他們挫骨揚灰!', `MaleText_loc7`='¡Háganlos cenizas, esbirros!' WHERE `ID`=39785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈소! 돌아가는 길은 나 혼자 찾겠소. 부탁할 게 하나 있는데, 로이스 더스크위스퍼에게 멍청한 황혼의 눈은 궁둥이에나 붙이라고 말해 주시오.', `MaleText_loc4`='我们成功了！我能自己找到回去的路。帮我个忙，告诉罗伊斯·暮语该把那要命的暮光之眼放到哪儿。', `MaleText_loc5`='我們辦到了!我會自己找到回去的路。幫我個忙，告訴羅伊斯·暮語他可以把他的白癡暮光之眼插在哪裡。', `MaleText_loc7`='¡Lo hemos conseguido! Encontraré el camino de vuelta por mí mismo. Hazme un favor y ve a decirle a Royce Susurro del Anochecer dónde se puede meter su estúpido Ojo del Crepúsculo.' WHERE `ID`=39786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수가 많이 늘었군, 형제들이여. 우리 주인님의 계획이 얼마나 진행되었는지 말해 보아라.', `MaleText_loc4`='兄弟姐妹们，我看到你们的数量正在增长。告诉我，主人的计划实施得如何？', `MaleText_loc5`='教友們，我知道你們的人數正日漸壯大。告訴我，將主人的計畫付諸實行這件事你辦得怎樣。', `MaleText_loc7`='Veo que siguen aumentando en número, hermanos míos. Manténganme al corriente de cómo avanza el desarrollo del plan de nuestro maestro.' WHERE `ID`=39787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 잘 되어 간단 말이로군. 주인님은 우리에게 대단히 중요한 임무를 주셨다. 그리고 그분은 실패를 용납하지 않으실 것이야.', `MaleText_loc4`='看来，一切都按部就班。主人将最重要的任务给了我们，他不会接受失败的。', `MaleText_loc5`='所以一切都按照計畫進行。主人給了我們最重要的任務，而他不能接受失敗。', `MaleText_loc7`='Entonces todo está en orden. El maestro nos ha dado una misión de increíble importancia y no admitirá ningún fallo.' WHERE `ID`=39788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 무시무시한 심판을 받은 세상을 봐라. (불, 물, 대지, 바람...) 성난 원소 앞에 모든 것이 소멸하리라! (불타고, 물에 빠지고, 부서지고, 질식하고!)', `MaleText_loc4`='看吧！你面前的世界已经受到了裁决。（火、水、土、风！）元素必将毁灭一切生命！（烧灼、溺死、碾碎、窒息！）', `MaleText_loc5`='準備好!你眼前的世界已經受到審判。(火、水、地、風!)一切都將在元素的力量前蒸發!(燒死淹死壓死悶死!)', `MaleText_loc7`='¡Observa! El mundo que ves ante ti ha sido juzgado. (¡Fuego, agua, tierra, aire!) ¡Todo perecerá ante los elementos! (¡Quemen, ahoguen, aplasten y sofoquen!)' WHERE `ID`=39789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동참하라! 그리고 피할 수 없는 종말을 받아들여라. (주인님의 힘이 부른다...) 너희는 살덩이를 벗어나 강력한 모습으로 다시 태어나리라! (형상을 뛰어넘는 힘, 무한한 힘!)', `MaleText_loc4`='加入我们，接受必然的结局吧。（主人的力量在召唤！）你将重生，超越血肉！（超越形体的力量！无穷无尽的能量！）', `MaleText_loc5`='加入我們，接受這個無法改變的結果。(主人的力量在呼喊!)你將重生，獲得凡人無法相比的力量!(沒有形態的力量，無止境的力量!)', `MaleText_loc7`='Únetenos y acepta el inevitable fin. (¡El poder del Amo llama!) ¡Renacerás, más fuerte que la carne! (¡Fuerza más allá de la forma! ¡Poder en el infinito!)' WHERE `ID`=39790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 충성을 맹세해라. (주인님이 원해. 주인님이 보고 원하고 굶주려.) 그러면 나의 형상으로 다시 태어나리라! (잠깐! 불신자다! 여기 이교도가 있다!) 침입자인가? 누구냐! 모습을 보여라!', `MaleText_loc4`='向我宣誓效忠，（主人看要的就要得到，他渴望一切！）——你将被我的精神重新塑造（等等！异端！我们这儿藏着一个异端！）入侵者！你！现身吧……', `MaleText_loc5`='向我宣示忠誠(主人想要!他看到他要他飢渴!)你將會重生於我的名下。(等一下!異教徒!這裡有異教徒!)一個入侵者，你滾出來...', `MaleText_loc7`='Jura tu lealtad a mí (¡El Amo quiere! ¡Ve y quiere y ansía!) y serás rehecho a mi imagen. (¡Esperen! ¡INFIEL! ¡Un pagano entre nosotros!) ¡Un intruso! ¡TÚ! Muéstrate…' WHERE `ID`=39791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지시하셨던 대로 장치를 제작하고 있습니다. 곧 지시하셨던 그다음 단계로 넘어갈 준비가 완료됩니다.', `MaleText_loc4`='对这些装置的处理正按照你的指示进行。我们很快就能准备好执行你下一阶段的命令了。', `MaleText_loc5`='目前照你先前的指示先處理裝置的事情。我們很快就會做好準備，照你的命令邁入下一階段。', `MaleText_loc7`='El trabajo con los artefactos sigue adelante como ordenaste. Pronto estaremos listos para avanzar a la siguiente fase de tus órdenes.' WHERE `ID`=39792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 주인님이 세상에 종말을 가져와 그분의 뜻대로 세상을 재건하는 데 쓰일 도구일 뿐이다.', `MaleText_loc4`='主人将毁灭这个世界，并按照他的意志重铸全新的世界。而你正是他实现这一目标的工具。', `MaleText_loc5`='你是主人用來終結，並以他的形象重鑄這個世界所用的工具。', `MaleText_loc7`='Ustedes son los instrumentos que el maestro utilizará para provocar el fin de este mundo y forjar uno nuevo a su imagen y semejanza.' WHERE `ID`=39793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 일을 끝내면, 너는 오그리마 전체에 이 장치들을 숨길 것이다.', `MaleText_loc4`='当它们完成的时候，你就要把这些装置分散放在奥格瑞玛各处。', `MaleText_loc5`='等他們完成，你要將這些裝置藏在奧格瑪的各個角落。', `MaleText_loc7`='Cuando estén completados, esconderán estos artefactos por todo Orgrimmar.' WHERE `ID`=39794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 거대한 녀석이오. 괜히 건드리지 말 걸 그랬소.', `MaleText_loc4`='那家伙可真大。你不该激怒他。', `MaleText_loc5`='那隻真巨大，你不應該激怒他的。', `MaleText_loc7`='Ese es enorme. No deberías haberle hecho enfadar.' WHERE `ID`=39795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약속된 시간이 되면, 그들은 도시를 불태워 삼킬 불의 정령들을 불러내 우리 주인님의 영광스러운 귀환을 받들 준비를 할 것이다!', `MaleText_loc4`='等那个时刻一到，它们就会释放出火元素，让这座城市被熊熊烈火吞噬！为我们主人荣耀的恢复而做好准备！', `MaleText_loc5`='他們將會在指定的時間放出火元素，讓火焰吞噬掉整座城市，然後鋪設我們主人光榮回歸的舞台!', `MaleText_loc7`='Cuando llegue el momento, liberarán elementales de fuego que consumirán la ciudad y ¡prepararán el escenario para el glorioso regreso de nuestro maestro!' WHERE `ID`=39796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=39797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우거다!', `MaleText_loc4`='食人魔！', `MaleText_loc5`='巨魔!', `MaleText_loc7`='¡Ogro!' WHERE `ID`=39798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 냄새가 특히 더 고약하오.', `MaleText_loc4`='这个闻起来尤其恶心。', `MaleText_loc5`='這個聞起來最臭。', `MaleText_loc7`='Este huele especialmente mal.' WHERE `ID`=39799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 녀석을 없애시오! 난 여기 있겠소.', `MaleText_loc4`='干掉它！我会守在这儿。', `MaleText_loc5`='殺死那隻!我在這等。', `MaleText_loc7`='¡Mata a ese! Yo te espero aquí.' WHERE `ID`=39800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 오우거가 더 있단 말이오?', `MaleText_loc4`='啊，更多的食人魔？', `MaleText_loc5`='什麼?更多的巨魔?', `MaleText_loc7`='¿Más ogros?' WHERE `ID`=39801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짓밟히지 마시오.', `MaleText_loc4`='别被踩死。', `MaleText_loc5`='別被踩到了。', `MaleText_loc7`='Que no te pisen.' WHERE `ID`=39802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 오우거가 날 쳐다보고 있는 건 아니겠지. 안 그렇소?', `MaleText_loc4`='他看不见我，对吧？', `MaleText_loc5`='他沒看到我，對吧?', `MaleText_loc7`='No me ve, ¿verdad?' WHERE `ID`=39803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 황혼의 외경? 정말 믿을 수가 없소. 저게 진짜 존재하다니!', `MaleText_loc4`='那是暮光伪经？我要被活煮了——它真的存在！', `MaleText_loc5`='那是暮光聖典嗎?我會被活活烤成肉串─它真的存在!', `MaleText_loc7`='¿Eso es el Apócrifo Crepuscular? ¡Que me aspen! ¡Existe de verdad!' WHERE `ID`=39804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오. 그래, 알고 있소. 다시 붙잡혔소.$B$B그 일에 대해서는 별로 이야기하고 싶지 않소.$B$B준비는 됐소?', `MaleText_loc4`='嗨。对，我知道。我又被抓住了。$B$B我不想谈这些。$B$B你准备好了吗？', `MaleText_loc5`='嗨。對啦，我知道，我知道我又被抓住了。$B$B我不想說這個。$B$B你準備好了嗎?', `MaleText_loc7`='Hola. Sí, ya lo sé, me han vuelto a capturar.$b$bNo quiero hablar de ello.$b$b¿Estás $glisto:lista;?' WHERE `ID`=39805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 날 좀 아래로 내려주겠소?', `MaleText_loc4`='嗯？你打算帮我下去吗？', `MaleText_loc5`='所以?你要幫我下來嗎?', `MaleText_loc7`='¿Y bien? ¿Me vas a echar una mano?' WHERE `ID`=39806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 다시 한 번 해봅시다.', `MaleText_loc4`='好吧，让我们再试一次。', `MaleText_loc5`='好，讓我們再試一次。', `MaleText_loc7`='Vale, vamos a intentarlo de nuevo.', `FemaleText_loc1`='좋아요. 다시 한 번 해보자고요.', `FemaleText_loc4`='好吧，让我们再试一次。', `FemaleText_loc5`='好，讓我們再試一次。', `FemaleText_loc7`='Vale, vamos a intentarlo de nuevo.' WHERE `ID`=39807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음. 아닙니다. 조금 더 기다려 주시겠습니까? 먼저 해야 할 일이 좀 있습니다.', `MaleText_loc4`='嗯，不。你不介意再多吊上一会儿吧？我还得先干点儿别的事。', `MaleText_loc5`='嗯...不。可以請你再等一下嗎?我有事情必須先處理一下。', `MaleText_loc7`='Eh, no. ¿Te importa esperar un poco más? Antes tengo algunos asuntos de los que ocuparme.', `FemaleText_loc1`='음. 아니에요. 조금 더 기다려 주시겠어요? 먼저 해야 할 일이 좀 있어요.', `FemaleText_loc4`='嗯，不。你不介意再多吊上一会儿吧？我还得先干点儿别的事。', `FemaleText_loc5`='嗯...不。可以請你再等一下嗎?我有事情必須先處理一下。', `FemaleText_loc7`='Eh, no. ¿Te importa esperar un poco más? Antes tengo algunos asuntos de los que ocuparme.' WHERE `ID`=39808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 뭐라고 했어?$B$B이리 와서 말해봐!$B$B<크리스토프가 머리를 돌려 당신을 쏘아보며 분노에 가득차 팔을 버둥거립니다.>$B$B그러니까 도와 달라고, 응? 내가... 내가 말이야... 네놈의 머리통을 박살 내겠어! 그리고 내 장화를 입에 쑤셔넣겠어! 이리 와! 이리 오라고!$B$B<크리스토프가 당신의 목을 잡으려고 낑낑대며 손가락을 뻗어 보지만 닿지는 않습니다.>', `MaleText_loc4`='你说……什么？$B$B过来给我再说一遍！$B$B<克里斯托弗因愤怒而乱踢乱抓，面目扭曲的瞪着你。>$B$B快来帮我，不然我就——我就——我就把你打个鼻青脸肿！然后把靴子踩在你肮脏的脸上！你过来！快给我回来！$B$B<克里斯托弗奋力想要掐住你的脖子，抓挠的手指尖几乎就要碰到你的脸。>', `MaleText_loc5`='你...什麼?$B$B你給我過來這說!$B$B<克里斯多夫生氣的亂揮亂踢，他的頭轉了過來瞪著你。>$B$B那就幫我，我會...我要...我會把你的腦子給踹飛!然後用我的靴子塞滿你那空空如也的頭殼裡!過來!給我滾回來!$B$B<克里斯多夫伸出手想握住你的脖子，他的手指離你的臉只有幾寸的距離。>', `MaleText_loc7`='Tú... ¿QUÉ?$b$b¡Ven aquí y dímelo a la cara!$b$b<Kristoff da patadas y sacude los brazos en un acceso de ira, girando la cabeza para lanzarte una mirada furibunda.>$b$bTe juro que te... Te voy a... ¡Te voy a volar la tapa de los sesos! ¡Y voy a rellenar el hueco resultante con mi bota! ¡Ven aquí! ¡VUELVE!$b$b<Kristoff intenta agarrarte el cuello, pero sus dedos se agitan a unos centímetros de tu cara.>' WHERE `ID`=39809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 눈에 대한 연구는 어떻게 돼 가고 있습니까?', `MaleText_loc4`='你对眼睛的研究进展得怎么样了？', `MaleText_loc5`='所以...你對眼睛所做的研究進行得怎樣?', `MaleText_loc7`='¿Cómo va tu investigación sobre el Ojo?', `FemaleText_loc1`='그래서 눈에 대한 연구는 어떻게 돼 가고 있나요?', `FemaleText_loc4`='你对眼睛的研究进展得怎么样了？', `FemaleText_loc5`='所以...你對眼睛所做的研究進行得怎樣?', `FemaleText_loc7`='¿Cómo va tu investigación sobre el Ojo?' WHERE `ID`=39810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, $n. 그냥 $n|1이라고;라고; 불러도 되겠소?$B$B혹시 지금 내가 오우거 동굴 속에 있는 고리에 매달려 있는 거 안 보이오?$B$B그런데, 뭐? 내 연구가 어떻게 돼 가고 있냐고? 이 거만하고 지저분한 $c 놈 같으니. 이리 와! 이리 오라고! 이 더러운 자식!$B$B<크리스토프가 기를 쓰고 쇠사슬을 흔들며 당신 얼굴을 걷어차려고 애씁니다.>', `MaleText_loc4`='$n，$n，我能叫你$n吗？$B$B我马上就要被挂到食人魔洞穴里的肉钩子上了。$B$B你觉得我的研究进度如何？你这个中看不中用的笨$c！到这里来！你这个坏家伙！$B$B<克里斯托弗在锁住他的链子上晃来晃去，拼命想要踢到你的脸。>', `MaleText_loc5`='$n，$n，我可以叫你$n嗎?$B$B我被巨魔吊在他們洞穴深處的一個肉勾上。$B$B你認為這種情況下我的研究能進行得怎樣?你這自大的王八$c!過來!快過來!你這豬娘養的!$B$B<克里斯多夫不斷扯著他的鎖鍊，渴望在你臉上踹一腳。>', `MaleText_loc7`='$n, $n. ¿Puedo llamarte $n?$b$bEstoy colgando de un gancho de carne en el fondo de la cueva de un ogro.$b$b¿Tú como piensas que va mi investigación, $c de pacotilla $gcretino:cretina; y $gpresuntuoso:presuntuosa;? ¡Ven! ¡Ven aquí, $ghijo:hija; de piara!$b$b<Kristoff se retuerce arriba y abajo en su cadena, intentando desesperadamente darte una patada en la cara.>' WHERE `ID`=39811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<크리스토프가 끙끙댑니다.>', `MaleText_loc4`='<克里斯托弗哼哼着。>', `MaleText_loc5`='<克里斯多夫低吼。>', `MaleText_loc7`='<Kristoff gruñe.>' WHERE `ID`=39812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 그리고 그 후 우리는 이 나약한 육신을 벗어나 불멸의 존재가 될 것이다!', `MaleText_loc4`='我的兄弟姐妹们，我们应该抛弃这副脆弱的躯壳，升华为不朽之身！', `MaleText_loc5`='到時候，我的兄弟姊妹們，我們就能拋棄這些脆弱的身軀並成為不死之身!', `MaleText_loc7`='¡Y después, hermanos y hermanas, nos liberaremos de estos frágiles cuerpos y ascenderemos a la inmortalidad!' WHERE `ID`=39813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 고대정령 중에서도 골드린 님께서 가장 멋지오. 그분의 맹렬함과 단호함이란... 성공하려면 그분을 본받으시오.', `MaleText_loc4`='在所有远古半神中，戈德林是最杰出的一位。他的狂怒，他的决心……你一定能赶上他。', `MaleText_loc5`='在所有的先祖裡，戈德林是最了不起的。他的強悍，他的意志...效法他對你來說是正確的。', `MaleText_loc7`='De todos los ancestros, Goldrinn es el más magnífico. Su furia, su determinación... Harías bien en imitarlas.' WHERE `ID`=39814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀하신 대로 될 것입니다, 주인님.', `MaleText_loc4`='如您所愿，主人。', `MaleText_loc5`='如你所願，我的主人。', `MaleText_loc7`='Será como dices, mi señor.' WHERE `ID`=39815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 자리는 원래 내 거야! 증명해 주지!', `MaleText_loc4`='你的位置应该是我的！我要让你瞧瞧！', `MaleText_loc5`='你的工作應該是我的才對!我讓你見識見識!', `MaleText_loc7`='¡Tú deberías estar en mi lugar! ¡Verás lo que es bueno!', `FemaleText_loc1`='네 자리는 원래 내 거야! 증명해 주지!', `FemaleText_loc4`='你的位置应该是我的！我要让你瞧瞧！', `FemaleText_loc5`='你的工作應該是我的才對!我讓你見識見識!', `FemaleText_loc7`='¡Tú deberías estar en mi lugar! ¡Verás lo que es bueno!' WHERE `ID`=39816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 없애고 그 자리를 차지할 테다, 이 쓸모없는 놈아!', `MaleText_loc4`='我要杀了你，然后夺回你的位置，渣滓！', `MaleText_loc5`='我要殺了你並取代你，人渣!', `MaleText_loc7`='¡Te mataré y ocuparé tu lugar, escoria!', `FemaleText_loc1`='너를 없애고 그 자리를 차지할 테다, 이 쓸모없는 놈아!', `FemaleText_loc4`='我要杀了你，然后夺回你的位置，渣滓！', `FemaleText_loc5`='我要殺了你並取代你，人渣!', `FemaleText_loc7`='¡Te mataré y ocuparé tu lugar, escoria!' WHERE `ID`=39817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어도 살아도 우린 그분들을 섬길 것이다!', `MaleText_loc4`='无论生死，我们都将效忠他们！', `MaleText_loc5`='我們是生是死都得聽他們的!', `MaleText_loc7`='¡Vivimos o morimos para servirles!', `FemaleText_loc1`='죽어도 살아도 우린 그분들을 섬길 것이다!', `FemaleText_loc4`='无论生死，我们都将效忠他们！', `FemaleText_loc5`='我們是生是死都得聽他們的!', `FemaleText_loc7`='¡Vivimos o morimos para servirles!' WHERE `ID`=39818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신의 비밀을 배울 자는 바로 나다! 잘 봐라!', `MaleText_loc4`='我才应该是了解上古诸神秘密的那个人！我会让你看看！', `MaleText_loc5`='我才應該是學習古神秘密的那個人!看清楚了!', `MaleText_loc7`='¡Yo debería estar descubriendo los secretos de los dioses antiguos! ¡Te vas a enterar!', `FemaleText_loc1`='고대 신의 비밀을 배울 자는 바로 나다! 잘 봐라!', `FemaleText_loc4`='我才应该是了解上古诸神秘密的那个人！我会让你看看！', `FemaleText_loc5`='我才應該是學習古神秘密的那個人!看清楚了!', `FemaleText_loc7`='¡Yo debería estar descubriendo los secretos de los dioses antiguos! ¡Te vas a enterar!' WHERE `ID`=39819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 선택받았다! 나는 승리할 것이다!', `MaleText_loc4`='我是被选中的！我是不可战胜的！', `MaleText_loc5`='我才是被選上的人!我將戰勝一切!', `MaleText_loc7`='¡Me eligieron! ¡Prevaleceré!', `FemaleText_loc1`='나는 선택받았다! 나는 승리할 것이다!', `FemaleText_loc4`='我是被选中的！我是不可战胜的！', `FemaleText_loc5`='我才是被選上的人!我將戰勝一切!', `FemaleText_loc7`='¡Me eligieron! ¡Prevaleceré!' WHERE `ID`=39820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 보십시오, 황혼의 군주여! 이 $r|1을;를; 제물로 바치겠나이다!', `MaleText_loc4`='暮光领主，请听我说！接受$r这份卑微的贡品吧！', `MaleText_loc5`='聆聽我的聲音，暮光的領主們!我謙卑地奉獻給你這個$r，接受吧!', `MaleText_loc7`='¡A mí, señores Crepusculares! ¡Aceptad a $geste:esta; $r como una humilde ofrenda!', `FemaleText_loc1`='저를 보십시오, 황혼의 군주여! 이 $r|1을;를; 제물로 바치겠나이다!', `FemaleText_loc4`='暮光领主，请听我说！接受$r这份卑微的贡品吧！', `FemaleText_loc5`='聆聽我的聲音，暮光的領主們!我謙卑地奉獻給你這個$r，接受吧!', `FemaleText_loc7`='¡A mí, señores Crepusculares! ¡Aceptad a $geste:esta; $r como una humilde ofrenda!' WHERE `ID`=39821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타에라 님께서는 여기 계시지 않는다, 멍청한 녀석. 그분은 네놈을 막을 만큼의 힘을 내게 주셨다!', `MaleText_loc4`='泰拉尔主人已经不住在这里了，你这傻瓜。他已赐予我足够的力量来阻止你！', `MaleText_loc5`='泰拉爾大人已經不在這了，蠢貨。他賦予了我足夠的力量來阻止你!', `MaleText_loc7`='El maestro Taerar ya no vive aquí, $gnecio:necia;. ¡Me ha otorgado suficiente poder para detenerte!' WHERE `ID`=39822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='못 보던 얼굴이네요. 여기 처음이신가요?', `FemaleText_loc4`='我不认识你，你刚到这里吗？', `FemaleText_loc5`='我不認得你。你是新來的?', `FemaleText_loc7`='No te reconozco. ¿Acabas de llegar aquí?' WHERE `ID`=39823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 사람들이 만들고 있는 저 장치들은 무엇입니까?', `MaleText_loc4`='这是什么设备，要这么多人共同建造？', `MaleText_loc5`='大家在製造什麼裝置?', `MaleText_loc7`='¿Qué son esos artefactos que está construyendo todo el mundo?', `FemaleText_loc1`='다른 사람들이 만들고 있는 저 장치들은 뭔가요?', `FemaleText_loc4`='这是什么设备，要这么多人共同建造？', `FemaleText_loc5`='大家在製造什麼裝置?', `FemaleText_loc7`='¿Qué son esos artefactos que está construyendo todo el mundo?' WHERE `ID`=39824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 처음 오신 분이군요. 이 장치는 세상을 변화시킬 우리 주인님의 계획 중 하나예요. 심판의 불길을 뿜어내며 우리를 불멸의 존재로 만들어 줄 것이랍니다. 주인님께서 그렇게 약속하셨어요.', `FemaleText_loc4`='哦，看来你是个新人。这些装置是我们主人改造世界计划的一部分。它会向整个世界释放出审判的烈火，并让我们得到永恒的生命。这是主人对我们许下的承诺。', `FemaleText_loc5`='啊，對了你是新人。這些裝置是我們主人計畫中的其中一個環節，我們要為世界帶來蛻變。這些東西會放出審判之火，讓我們飛昇至不朽之路。主人允諾過的。', `FemaleText_loc7`='Ah, acabas de llegar. Estos artefactos son parte del plan de nuestro maestro para la transformación del mundo. Liberarán el fuego del Juicio Final que nos permitirá ascender a la inmortalidad. Esa es la promesa del maestro.' WHERE `ID`=39825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='외부인은 여기 오면 안 돼요. 문제가 생기기 전에 떠나세요.', `FemaleText_loc4`='你不属于这里，陌生人。别惹麻烦，赶快离开吧。', `FemaleText_loc5`='外來者，你不屬於這裡。在你惹上麻煩前快點離開。', `FemaleText_loc7`='Tú no eres de aquí y esto no es asunto tuyo. Márchate antes de que te metas en líos.' WHERE `ID`=39826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애애애애애!', `MaleText_loc4`='不——————！', `MaleText_loc5`='不～～～～～～～～～～～～!', `MaleText_loc7`='¡Noooooooooooo!' WHERE `ID`=39827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타에라는 페랄라스에서 도망치지 못했도다. 그는 원래 자신의 모습을 통해 에메랄드 악몽으로의 연결 고리로서의 역할을 하고 있다.', `FemaleText_loc4`='泰拉尔并没有逃离菲拉斯。而是以自己的方式充当着连通恶梦的管道。', `FemaleText_loc5`='泰拉爾並沒有逃到菲拉斯。他利用自己的型體做為去夢魘的橋樑。', `FemaleText_loc7`='Taerar no ha abandonado Feralas. Hace las veces de conducto de la pesadilla mediante su propia forma.' WHERE `ID`=39828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더는 도망치지 않겠도다. 동쪽에 있는 봉우리 꼭대기에서 나를 찾아라.', `FemaleText_loc4`='我不会再逃离。到东边的山峰顶上找我。', `FemaleText_loc5`='我不會再跑了。到東邊的山頂上來找我。', `FemaleText_loc7`='Ya no huiré más. Me encontrarás en lo alto del pico del este.' WHERE `ID`=39829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투사님, 그 사람을 찾아주십시오. 어디로 갔는지 알 수가 없습니다!', `MaleText_loc4`='血卫士，你必须帮我找到他。我完全找不到他！', `MaleText_loc5`='血衛士，你得幫我找到他。他突然失蹤了!', `MaleText_loc7`='Debes ayudarme a encontrarla, guardia de sangre. ¡Ha desaparecido!', `FemaleText_loc1`='혈투사님, 그이를 제발 찾아주세요. 어디로 갔는지 알 수가 없어요!', `FemaleText_loc4`='血卫士，你必须帮我找到他。我完全找不到他！', `FemaleText_loc5`='血衛士，你得幫我找到他。他突然失蹤了!', `FemaleText_loc7`='Debes ayudarme a encontrarlo, guardia de sangre. ¡Ha desaparecido!' WHERE `ID`=39830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 도와주실 수 있을 겁니다. 시장에 간다고 나가서는 들어오질 않네요.', `MaleText_loc4`='你一定要帮帮我。他去了市场，就再没有回来。', `MaleText_loc5`='你當然可以幫忙。他只是去了趟市場，然後就沒回來過。', `MaleText_loc7`='Estoy seguro de que puedes ayudarme. Ella fue al mercado y no ha regresado.', `FemaleText_loc1`='분명히 도와주실 수 있을 거예요. 시장에 간다고 나가서는 들어오질 않고 있어요.', `FemaleText_loc4`='你一定要帮帮我。他去了市场，就再没有回来。', `FemaleText_loc5`='你當然可以幫忙。他只是去了趟市場，然後就沒回來過。', `FemaleText_loc7`='Estoy segura de que puedes ayudarme. Él fue al mercado y no ha regresado.' WHERE `ID`=39831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투사님이 하실 수 있는 일이 분명히 있을 겁니다.', `MaleText_loc4`='你一定能做些什么的，血卫士。', `MaleText_loc5`='一定有什麼事情是你可以做的，血衛士。', `MaleText_loc7`='Debe haber algo que puedas hacer, guardia de sangre.', `FemaleText_loc1`='혈투사님이 하실 수 있는 일이 분명히 있을 거예요.', `FemaleText_loc4`='你一定能做些什么的，血卫士。', `FemaleText_loc5`='一定有什麼事情是你可以做的，血衛士。', `FemaleText_loc7`='Debe haber algo que puedas hacer, guardia de sangre.' WHERE `ID`=39832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자서 그냥 떠났을 리가 없습니다! 도대체 어디로 간 걸까요?', `MaleText_loc4`='他绝对不会单独离开！他到底去哪里了？', `MaleText_loc5`='他永遠不會自己一個人離開的!他會跑去哪裡?', `MaleText_loc7`='¡Ella nunca abandonaría a los suyos! ¿Dónde habrá podido ir?', `FemaleText_loc1`='혼자서 그냥 떠났을 리가 없어요! 도대체 어디로 간 걸까요?', `FemaleText_loc4`='他绝对不会单独离开！他到底去哪里了？', `FemaleText_loc5`='他永遠不會自己一個人離開的!他會跑去哪裡?', `FemaleText_loc7`='¡Él nunca abandonaría a los suyos! ¿Dónde habrá podido ir?' WHERE `ID`=39833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 남편이 사라졌어요. 도와주세요, 혈투사님. 그이는 싸움도 못해요. 그이를 찾을 수 있게 도와주세요.', `MaleText_loc4`='我的丈夫失踪了。求求你，血卫士，他并不是战士。请一定帮我找到他。', `MaleText_loc5`='我的丈夫失蹤了。拜託你，血衛士，他不是個戰士。你得幫我找到他。', `MaleText_loc7`='Mi mujer ha desaparecido. Por favor, guardia de sangre, ella no es una guerrera. Tienes que ayudarme.', `FemaleText_loc1`='제 남편이 사라졌어요. 도와주세요, 혈투사님. 그이는 싸움도 못해요. 그이를 찾을 수 있게 도와주세요.', `FemaleText_loc4`='我的丈夫失踪了。求求你，血卫士，他并不是战士。请一定帮我找到他。', `FemaleText_loc5`='我的丈夫失蹤了。拜託你，血衛士，他不是個戰士。你得幫我找到他。', `FemaleText_loc7`='Mi marido ha desaparecido. Por favor, guardia de sangre, él no es una guerrero. Tienes que ayudarme.' WHERE `ID`=39834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투사님은 이성적인 분이시죠? 만약 가족이 사라지면 누구에게 도움을 청하시겠어요?', `MaleText_loc4`='你是个通情达理的人，血卫士。如果你的亲人失踪了，你会怎么做？', `MaleText_loc5`='你是個通情達理的人，血衛士。如果你的親戚失蹤了，你會怎麼做?', `MaleText_loc7`='Guardia de sangre, tú eres un hombre razonable. ¿Adónde acudirías si desapareciera alguien de tu familia?', `FemaleText_loc1`='혈투사님은 이성적인 분이시죠? 만약 가족이 사라지면 누구에게 도움을 청하시겠어요?', `FemaleText_loc4`='你是个通情达理的人，血卫士。如果你的亲人失踪了，你会怎么做？', `FemaleText_loc5`='你是個通情達理的人，血衛士。如果你的親戚失蹤了，你會怎麼做?', `FemaleText_loc7`='Guardia de sangre, tú eres un hombre razonable. ¿Adónde acudirías si desapareciera alguien de tu familia?' WHERE `ID`=39835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 납치된 걸까요? 다시 그를 볼 수 있을까요?', `MaleText_loc4`='你认为他被绑架了？我还能再见到他么？', `MaleText_loc5`='你想他是不是被綁架了?我會再見到他嗎?', `MaleText_loc7`='¿Crees que han podido secuestrarla? ¿La volveré a ver alguna vez?', `FemaleText_loc1`='혹시 납치된 걸까요? 다시 그이를 볼 수 있을까요?', `FemaleText_loc4`='你认为他被绑架了？我还能再见到他么？', `FemaleText_loc5`='你想他是不是被綁架了?我會再見到他嗎?', `FemaleText_loc7`='¿Crees que han podido secuestrarlo? ¿Lo volveré a ver alguna vez?' WHERE `ID`=39836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저만 실종 신고를 하러 온 게 아니에요. 없어진 사람이 한둘이 아니에요. 엄청 많다고요.', `MaleText_loc4`='我并非唯一到这里来报告失踪案件的人。这样的案件已经发生了许多。', `MaleText_loc5`='我不是唯一一個來報告失蹤案件的人。還有其他許多許多人也一樣。', `MaleText_loc7`='No soy el único que ha venido para informar de una desaparición. Hay más, muchos más.', `FemaleText_loc1`='저만 실종 신고를 하러 온 게 아니에요. 없어진 사람이 한둘이 아니에요. 엄청 많다고요.', `FemaleText_loc4`='我并非唯一到这里来报告失踪案件的人。这样的案件已经发生了许多。', `FemaleText_loc5`='我不是唯一一個來報告失蹤案件的人。還有其他許多許多人也一樣。', `FemaleText_loc7`='No soy la única que ha venido para informar de una desaparición. Hay más, muchos más.' WHERE `ID`=39837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에 무슨 일이 벌어지고 있는 게 분명하네. 왠지 느낌이 안 좋아. 이 여성들은 가족이 사라졌다고 걱정하고 있고, 또 다른 이들은 세상이 멸망할 거라고 말하네. 대체 무슨 뜻이지?', `MaleText_loc4`='奥格瑞玛正在发生一些可怕的事情。这里的女人们都在传说有人失踪了。还有人说，世界将要完结。这到底是什么意思？', `MaleText_loc5`='奧格瑪裡正在發生些怪事，而我覺得看起來不妙。這些女人在抱怨有人失蹤。還有人說世界末日要到了。這到底怎麼回事?', `MaleText_loc7`='Algo sucede en Orgrimmar, aunque no sé qué puede ser. Estas mujeres se quejan de que ha habido desapariciones. Otros dicen que el mundo llega a su fin. ¿Qué quiere decir todo esto?' WHERE `ID`=39838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 세례를 받아라!!!!', `MaleText_loc4`='让火焰净化一切！！！！', `MaleText_loc5`='讓火焰淨化一切!!!!', `MaleText_loc7`='¡¡¡¡QUE EL FUEGO TE PURIFIQUE!!!!' WHERE `ID`=39839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말이 머지않았소, $c|1이여;여;. 걱정할 필요는 없소. 나와 내 형제들이 하는 말을 잘 들으시오.', `MaleText_loc4`='$c，世界末日就要到了。但不需要绝望。听听我所说的，看看我的兄弟所给予你的一切吧。', `MaleText_loc5`='世界的末日正在逼近，$c。但是不需要感到絕望。聽聽我說的話，還有我的兄弟們能幫你們的事。', `MaleText_loc7`='Se acerca el fin del mundo, $c. Pero no desesperes. Escucha lo que yo tengo que decir y lo que mis hermanos ofrecen.', `FemaleText_loc1`='세상의 종말이 머지않았습니다, $c|1이여;여;. 걱정할 필요는 없습니다. 나와 내 형제들이 하는 말을 잘 들으십시오.', `FemaleText_loc4`='$c，世界末日就要到了。但不需要绝望。听听我所说的，看看我的兄弟所给予你的一切吧。', `FemaleText_loc5`='世界的末日正在逼近，$c。但是不需要感到絕望。聽聽我說的話，還有我的兄弟們能幫你們的事。', `FemaleText_loc7`='Se acerca el fin del mundo, $c. Pero no desesperes. Escucha lo que yo tengo que decir y lo que mis hermanos ofrecen.' WHERE `ID`=39840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말을 하는지 한번 들어봅시다.', `MaleText_loc4`='我会听一听你要说些什么。', `MaleText_loc5`='我會聽聽你說的話。', `MaleText_loc7`='Escucharé lo que tengas que decir.', `FemaleText_loc1`='무슨 말을 하는지 한번 들어봅시다.', `FemaleText_loc4`='我会听一听你要说些什么。', `FemaleText_loc5`='我會聽聽你說的話。', `FemaleText_loc7`='Escucharé lo que tengas que decir.' WHERE `ID`=39841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 원고에 무언가를 급하게 휘갈겨 써 넣습니다.', `MaleText_loc4`='%s匆忙地将一张纸条夹进他的手稿里。', `MaleText_loc5`='%s快速地做了一頁筆記後將它放進了他的手稿中。', `MaleText_loc7`='%s garabatea con prisas una página de notas en su manuscrito.' WHERE `ID`=39842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 툴툴거리며 원고를 살펴봅니다.', `MaleText_loc4`='%s查看着他的手稿，不住地嘟囔着。', `MaleText_loc5`='%s參考了他的手稿，嘀咕著。', `MaleText_loc7`='%s consulta su manuscrito y gruñe.' WHERE `ID`=39843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 작업대 위의 별난 기구들을 만지작거립니다.', `MaleText_loc4`='%s摆弄着工作台上一些奇形怪状的工具。', `MaleText_loc5`='%s在他的工作台上操弄著一組奇怪的裝置。', `MaleText_loc7`='%s trastea con un extraño despliegue de equipo en su banco de trabajo.' WHERE `ID`=39844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 원고에 진척 상황을 조심스럽게 기록하며 조용히 웃습니다.', `MaleText_loc4`='%s轻声笑着，仔细地把进展情况记录在他的手稿里。', `MaleText_loc5`='%s對自己偷笑了幾聲，然後小心地將他的進度記錄在他的手稿裡。', `MaleText_loc7`='%s se ríe en silencio y registra su progreso con cuidado en su manuscrito.' WHERE `ID`=39845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아둔한 네놈의 머리로는 꿈도 꾸지 못할 작업을 방해하고 있구나!', `MaleText_loc4`='你现在妨碍的是你这榆木脑袋根本无法理解的工作！', `MaleText_loc5`='你正在干擾的是你那低能的頭腦無法理解的事。', `MaleText_loc7`='¡Estás interrumpiendo un trabajo que tu raquítica mente es incapaz de comprender!' WHERE `ID`=39846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 당신과 함께하고 싶습니다.', `MaleText_loc4`='我想加入你们的行动。', `MaleText_loc5`='我想成為活動的一份子。', `MaleText_loc7`='Quiero unirme a tu movimiento.', `FemaleText_loc1`='저도 당신과 함께하고 싶습니다.', `FemaleText_loc4`='我想加入你们的行动。', `FemaleText_loc5`='我想成為活動的一份子。', `FemaleText_loc7`='Quiero unirme a tu movimiento.' WHERE `ID`=39847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로브가 한 벌 더 필요합니다.', `MaleText_loc4`='我还需要一件长袍。', `MaleText_loc5`='我需要另一件袍子。', `MaleText_loc7`='Necesito otra túnica.', `FemaleText_loc1`='로브가 한 벌 더 필요합니다.', `FemaleText_loc4`='我还需要一件长袍。', `FemaleText_loc5`='我需要另一件袍子。', `FemaleText_loc7`='Necesito otra túnica.' WHERE `ID`=39848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여! 제단으로 모이십시오! 계시가 있을 겁니다!', `MaleText_loc4`='兄弟姐妹们，聚集在圣坛周围吧！真相即将被揭示！', `MaleText_loc5`='各位兄弟姊妹，在祭壇邊集合!揭露真相的時刻到了!', `MaleText_loc7`='¡Reúnanse alrededor del altar, hermanos y hermanas! ¡Les espera la revelación!' WHERE `ID`=39849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친애하는 놈리건 시민이여!', `MaleText_loc4`='诺莫瑞根的居民和朋友们！', `MaleText_loc5`='諾姆瑞根的居民和友人!', `MaleText_loc7`='¡Ciudadanos y amigos de Gnomeregan!' WHERE `ID`=39850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 종족이 피난민이나 추방자로, 미치광이의 전쟁 기계에 속박당한 채 방사능에 찌든 비참한 노예로 사는 것도 이제 끝이다!', `MaleText_loc4`='我们曾经是难民，是被放逐之人，是饱受辐射之苦，被拴在战争机器上的奴隶！但是，灾难已经过去！', `MaleText_loc5`='我們的人民毋需再像難民一樣，不用再被視為亡國流民，不必再可悲地束縛在那台狂人戰爭機器上當輻射的奴隸!', `MaleText_loc7`='¡Nuestra gente ya no vivirá como refugiados, como parias, como esclavos encadenados al yugo de la máquina de guerra de un loco!' WHERE `ID`=39851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔마플러그의 시대도 종말이 다가왔다!', `MaleText_loc4`='我们将终结瑟玛普拉格的统治！', `MaleText_loc5`='瑟瑪普拉格的統治即將終結!', `MaleText_loc7`='¡El fin del reinado de Termochufe se acerca!' WHERE `ID`=39852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 가진 작전과 과학, 용기와 결의로 승리를 쟁취하리라.', `MaleText_loc4`='我们的战术，我们的技术，我们的勇气和决心都无可匹敌。', `MaleText_loc5`='我們的戰術、我們的科技、我們的勇氣以及決心終將壓倒全場。', `MaleText_loc7`='Nuestras tácticas, nuestra ciencia, nuestra valentía y determinación prevalecerán.' WHERE `ID`=39853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 놈리건 작전을 시작한다!', `MaleText_loc4`='诺莫瑞根行动正式开始！', `MaleText_loc5`='行動:諾姆瑞根即刻展開!', `MaleText_loc7`='¡La Operación Gnomeregan comienza YA!' WHERE `ID`=39854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표물 확인! 부대, 위치로! 적의 로켓 발사기를 모두 파괴하라!', `MaleText_loc4`='目标进入视野！各小队，摧毁全部敌方火箭发射器！', `MaleText_loc5`='目標已進入視線範圍!傳令各小隊展開部署: 摧毀敵方每座火箭發射器!', `MaleText_loc7`='¡Objetivos localizados! Escuadrones: ¡destruyan los lanzamisiles enemigos!' WHERE `ID`=39855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 처리했다. 계속 공격!', `MaleText_loc4`='干掉了一个。保持攻势！', `MaleText_loc5`='拿下一座了。不要停下來!', `MaleText_loc7`='Uno menos. ¡Sigan atacando!' WHERE `ID`=39856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 하나 처리했구나. 공격 태세 유지!', `MaleText_loc4`='又摧毁了一个。给我继续攻击！', `MaleText_loc5`='又毀掉了一座。繼續突擊!', `MaleText_loc7`='Otro destruido. ¡Mantengan el asalto!' WHERE `ID`=39857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 멈추지 마라!', `MaleText_loc4`='干得好。不要松懈！', `MaleText_loc5`='幹得好。別放過他們!', `MaleText_loc7`='Excelente. ¡No desistan!' WHERE `ID`=39858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행장을 손에 넣었으니, 놈리건 하늘은 이제 우리 차지다.', `MaleText_loc4`='我们占领了机场，也掌握了制空权。', `MaleText_loc5`='這座機場是我們的了，諾姆瑞根的天空也連帶納入我們掌握之中。', `MaleText_loc7`='La base aérea es nuestra y, con ella, los cielos de Gnomeregan.' WHERE `ID`=39859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 바로 사악한 배신자 텔마플러그에게 빼앗긴 영광의 도시를 탈환하는 날이다!', `MaleText_loc4`='今天，我们将消灭叛徒瑟玛普拉格，夺回我们光荣的城市！', `MaleText_loc5`='今天，就是今天，我們要從那邪惡的叛徒瑟瑪普拉格的手中，奪回屬於我們的榮光之城!', `MaleText_loc7`='¡Hoy recuperaremos nuestra gloriosa ciudad de las manos del vil traidor Termochufe!' WHERE `ID`=39860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 여기 모여, 다 같이 우리 고향을 되찾자!', `MaleText_loc4`='请加入我们的队伍，光复我们失落已久的家园！', `MaleText_loc5`='靠過來我身邊，做好準備!準備奪回我們的家園!', `MaleText_loc7`='¡Preparémonos para reclamar nuestra tierra natal!' WHERE `ID`=39861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 바로 집결지로 모여라!', `MaleText_loc4`='在待命区集结！', `MaleText_loc5`='立刻到集結區域待命!', `MaleText_loc7`='¡Vayan a la zona de escala!' WHERE `ID`=39862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 공격을 시작하겠다!', `MaleText_loc4`='进攻马上就要开始了！', `MaleText_loc5`='突擊行動即將展開!', `MaleText_loc7`='¡El asalto ya casi comienza!' WHERE `ID`=39863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1단계 개시, 적의 비행장을 탈환하라!', `MaleText_loc4`='第一阶段：我们将夺取敌方机场！', `MaleText_loc5`='第一階段行動展開:奪回機場!', `MaleText_loc7`='Inicien la Fase 1: ¡capturar la base aérea enemiga!' WHERE `ID`=39864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 발사기를 파괴하여 제공권을 장악하라!', `MaleText_loc4`='摧毁火箭发射器，完全取得制空权！', `MaleText_loc5`='毀掉敵方火箭發射器，取得完全制空優勢!', `MaleText_loc7`='¡Destruyan sus lanzamisiles para tener total superioridad aérea!' WHERE `ID`=39865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다중 폭격기가 보호막으로 무장한 텔마플러그의 대전차포를 부술 수 있다.', `MaleText_loc4`='现在多重轰炸机可以摧毁瑟玛普拉格的反坦克大炮护盾了。', `MaleText_loc5`='這樣多重轟炸機隊就能消滅瑟瑪普拉格的反坦克火砲防護。', `MaleText_loc7`='Ahora nuestros Multibombarderos podrán aniquilar a los Cañones tronchatanques blindados de Termochufe.' WHERE `ID`=39866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2단계 개시, 지휘소 외부를 점령하라!', `MaleText_loc4`='第二阶段：攻占地面指挥所！', `MaleText_loc5`='第二階段行動展開:佔領地面指揮站!', `MaleText_loc7`='Inicien la Fase 2: ¡capturar el Puesto de mando de la superficie!' WHERE `ID`=39867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다중 폭격기 부대가 대전차포의 보호막을 파괴했다. 적을 쓰러뜨리고 지휘소 외부를 확보하라!', `MaleText_loc4`='多重轰炸机摧毁了反坦克大炮的护盾。端掉那些大炮，攻占地面指挥所！', `MaleText_loc5`='我方的多重轟炸機隊已經摧毀反坦克火砲的防護。打倒敵人，拿下地面指揮站!', `MaleText_loc7`='Los Multibombarderos han destruido los blindajes de los Cañones tronchatanques. ¡Destrúyanlos y aseguren el Puesto de mando de la superficie!' WHERE `ID`=39868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함정이다! 방사능오염기가 작동 중이다!', `MaleText_loc4`='陷阱！一台全线运作的辐射器！', `MaleText_loc5`='這是個陷阱!那可是台效能全開的輻射儀啊!', `MaleText_loc7`='¡ES UNA TRAMPA! ¡Es un irradiador funcionando!' WHERE `ID`=39869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지휘소 외부를 확보했다! 놈리건 작전이 93 퍼센트의 효율로 진행 중이다... 모두들 잘했다!', `MaleText_loc4`='我们占领了地面！诺莫瑞根行动完成进度93%%……干得好！', `MaleText_loc5`='地面安全無虞!行動:諾姆瑞根進行中，目前執行效率93%%...大家都很棒!', `MaleText_loc7`='¡Hemos asegurado la superficie! La Operación Gnomeregan se desarrolla con un 93%% de eficiencia... ¡Bien hecho!' WHERE `ID`=39870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어용 방사능 펌프를 정지하겠다. 남은 기계 병력을 모아 정문으로 이동하라.', `MaleText_loc4`='我会关闭防御辐射泵。各小队，拿上剩余的机械装备，向主入口全速前进。', `MaleText_loc5`='我來關閉防禦性輻射幫浦。傳令各小隊，徵用現存可用之器械裝備，然後往主要入口移動。', `MaleText_loc7`='Apagaré las bombas de radiación defensiva. Escuadrones, tomen los trajes mecas restantes y avancen a la Entrada principal.' WHERE `ID`=39871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리의 고지가 눈앞에 있다, 전우들이여. 3단계 개시. 통로로 진입하라!', `MaleText_loc4`='朋友们，我们已经站到了胜利的边缘。第三阶段：进入隧道！', `MaleText_loc5`='各位朋友，我們正處於勝利的最後關頭。第三階段行動展開:突入隧道!', `MaleText_loc7`='Estamos al borde la victoria, amigos. Inicien la Fase 3: ¡a los túneles!' WHERE `ID`=39872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하 철로와 하역장을 점령하면 도시 심장부를 신속하게 공격할 수 있다.', `MaleText_loc4`='一旦我们攻占了地下铁路和码头，我们就可以对城市中心发动快速突袭。', `MaleText_loc5`='只要我們佔領地下鐵路和卸貨港口，就可以利用這些設施在城市心臟地帶發動快攻。', `MaleText_loc7`='Una vez que capturemos las líneas subterráneas y los andenes de carga los usaremos para un ataque relámpago al corazón de la ciudad.' WHERE `ID`=39873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건이 우리 손아귀에 있다!', `MaleText_loc4`='光复诺莫瑞根近在咫尺！', `MaleText_loc5`='諾姆瑞根已在我們的掌握之中!', `MaleText_loc7`='¡Gnomeregan ya casi es nuestra!' WHERE `ID`=39874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로! 잠깐... 이거 켜진 건가? 이거... 누르면 되나? 시험 중... 마이크 시험 중!', `MaleText_loc4`='绝不！等等……这东西启动了？是这个……按钮？测试……测试。啊！*咳嗽*', `MaleText_loc5`='別想!啊等下...那東西開著嗎?是...這按鈕沒錯吧?測試...測試。啊! *清喉嚨*', `MaleText_loc7`='¡NUNCA! A ver... ¿está encendido esto? ¿Este botón? Probando...  ¡Ah! *ejem*' WHERE `ID`=39875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 안 돼! 놈리건은 내 거라고.', `MaleText_loc4`='绝不！诺莫瑞根是我的，梅卡托克。', `MaleText_loc5`='想都別想!梅卡托克，諾姆瑞根是我的。', `MaleText_loc7`='¡NUNCA! Gnomeregan es MÍA, Mekkatorque.' WHERE `ID`=39876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕카토크, 내 도시에 그냥 걸어들어올 수 있다고 생각했어?', `MaleText_loc4`='你自以为能闯进我的城市？', `MaleText_loc5`='你還以為你能這樣大搖大擺踏進「我的」城市?', `MaleText_loc7`='¿Crees que puedes invadir MI ciudad?' WHERE `ID`=39877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소모성 원자력 방어 시스템을 가동해. 트로그를 내보내라고!!!', `MaleText_loc4`='马上激活一次性原子防御系统：把穴居人都给我派过去！！！', `MaleText_loc5`='啟動即可拋原子能防禦系統:放出穴居怪!!!', `MaleText_loc7`='Activando el sistema defensivo atómico prescindible: ¡¡TROGGS AL FRENTE!!' WHERE `ID`=39878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런... 트로그를 한 놈도 빠짐없이 동원했군! 부대, 전투태세를 갖춰라!', `MaleText_loc4`='我的天啊……这座城里的穴居人一定全都杀出来了！', `MaleText_loc5`='我的天啊...這城市的每一個穴居怪大概全在這兒了!士兵們，穩住!', `MaleText_loc7`='Con un... ¡Deben de ser todos los troggs de la ciudad! ¡Escuadrones, trincheras!' WHERE `ID`=39879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파편 폭탄과 제압 사격을 퍼부어! ... 제자리를 지켜라! 여기서 물러나지 않겠다!', `MaleText_loc4`='全队注意，准备手榴弹和压制火力……坚守战线！我们绝不会退却！', `MaleText_loc5`='利用破片炸彈進行火力壓制...守住前線!我們不能在此刻被擊退!', `MaleText_loc7`='¡Bombas y fuego supresor... MANTENGAN SU POSICIÓN! ¡No nos harán retirar ahora!' WHERE `ID`=39880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청나게 큰 녀석이군! 저렇게 큰 트로그는 처음 보는데! 계속 공격하라... 저놈을 쓰러뜨려!', `MaleText_loc4`='我的娘亲啊！这是我见过的最大的穴居人！继续开火……把它干掉！', `MaleText_loc5`='喔親愛的泰坦寶貝!那大概是我這輩子見過最大隻的穴居怪了!開火!不要停...放倒他!', `MaleText_loc7`='¡Por los titanes infantes! ¡Es el trogg más grande que vi en mi vida! ¡Sigan disparando... derríbenlo!' WHERE `ID`=39882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 조용한데. 텔마플러그의 방어 병력은 어디 있지?', `MaleText_loc4`='太安静了。瑟玛普拉格的军队在哪里？', `MaleText_loc5`='太安靜了。瑟瑪普拉格的守備兵力跑哪去了?', `MaleText_loc7`='Qúe silencio. ¿Dónde están las fuerzas defensivas de Termochufe?' WHERE `ID`=39883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 이건 뭐지? 놈리건을 중독 시킨 방사능 폭탄인가... 이런! 적의 공격이다!', `MaleText_loc4`='这是什么？这就是那颗污染了诺莫瑞根的辐射炸弹……等等！有情况！', `MaleText_loc5`='那是什麼呀?看起來像是污染諾姆瑞根的那種輻射炸彈...喔等等!快閃啊!', `MaleText_loc7`='¿Qué es eso? Parece la bomba de radiación que envenenó Gnomeregan... ¡Esperen! ¡Bomba!' WHERE `ID`=39884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 안돼, 안돼, 안돼! 내 왕국에 들어오게 할 순 없어, 이놈들! 그렇겐 못 해!', `MaleText_loc4`='不！不，不，不！！！我不会让你进入我的王国！我绝不允许！', `MaleText_loc5`='不!不，不，絕不!!!我才不會讓你踏進我的王國，你這篡位的傢伙!我才不允許呢!', `MaleText_loc7`='¡No! ¡¡¡No, NO!!! ¡No entrarás en mi reino, usurpador! ¡NO LO PERMITIRÉ!' WHERE `ID`=39885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고 원자력 방어 시스템을 가동해.', `MaleText_loc4`='激活终极原子保卫系统。', `MaleText_loc5`='啟動終極原子能防護系統。', `MaleText_loc7`='Activando el Sistema de protección atómico máximo.' WHERE `ID`=39886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...전부 분해해 버리겠어!', `MaleText_loc4`='……彻底粉碎他们！', `MaleText_loc5`='...讓他們全都灰飛煙滅!', `MaleText_loc7`='¡DESINTEGRARLOS A TODOS!' WHERE `ID`=39887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 맞아... 게다가 26배나 더 강력하지!', `MaleText_loc4`='这……比第一个强大二十六倍！', `MaleText_loc5`='這隻...可是要比一開始那隻強二十六倍以上!', `MaleText_loc7`='Sí... ¡y veintiséis VECES más poderoso que el primero!' WHERE `ID`=39888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10분?! 초기 설정 그대로 놔뒀다고? 조종기 이리 내, 이 멍청이!', `MaleText_loc4`='十分钟！你还没改那东西的设置？快把控制器给我，白痴！', `MaleText_loc5`='十分鐘!?你保留了原廠設定?把那個控制器給我，你這蠢蛋!', `MaleText_loc7`='¡¿DIEZ MINUTOS?! ¿Dejaste la configuración de la fábrica? ¡Dame ese control, idiota!' WHERE `ID`=39889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕카토크, 네놈은 틀렸어! 내 소중한 도시에 발을 들여놓기도 전에 이미 끝장난 셈이지!', `MaleText_loc4`='你失败了，梅卡托克！别想踏入我宝贵的城市！', `MaleText_loc5`='梅卡托克，你輸定了!你在踏進我的寶貝城市之前，就被我抓到過、擊敗過!', `MaleText_loc7`='¡Has FALLADO, Mekkatorque! ¡Te vencí aún antes de que pusieras UN PIE en mi preciosa ciudad!' WHERE `ID`=39890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 죽어라!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='現在去死吧!', `MaleText_loc7`='¡MUERE!' WHERE `ID`=39891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그놈 면상을 보고 싶군... 보나마나... 어라? 아직 켜져 있었어? 그럼 꺼야지-', `MaleText_loc4`='哦，我想看看那个老家伙的脸。我打赌他……什么？它还开着？快关掉……', `MaleText_loc5`='喔，我想看看那個老傢伙的臉，我敢打賭他...什麼?擴音器還開著?給我關-', `MaleText_loc7`='Ah, me encantaría verte la cara. A que... ¿cómo? ¿Sigue encendido? PUES APÁGUENL…' WHERE `ID`=39892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10분이라고? 장치를 해제하고도 남을 시간이군.', `MaleText_loc4`='十分钟？足够拆除这个装置了。', `MaleText_loc5`='十分鐘?我們有的是時間來拆掉這東西。', `MaleText_loc7`='¿Diez minutos? Sobra tiempo para desarmar ese dispositivo.' WHERE `ID`=39893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힝클스, 거기 청동 회전 장치와 신선한 샘물 좀 가져와라. 코그스핀, 넌 더러운 트로그 옷감과 구리 나사 한 줌을 가져와...', `MaleText_loc4`='辛克尔斯，把高速青铜齿轮和清凉的泉水给我。克斯宾，扔给我肮脏的穴居人布片和一把螺栓……', `MaleText_loc5`='辛寇斯，把那個高速青銅齒輪拿給我，再加上一些清涼的泉水。科士賓，我還要骯髒的穴居怪布片和一把螺栓...', `MaleText_loc7`=' Hinkles, alcánzame ese aparejo zumbante y agua mineral. Rotadiente, pásame ese paño trogg sucio y unos tornillos de cobre…' WHERE `ID`=39894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 여기서 나가야겠다! 랩포지, 우리를 날려보내, 어서!', `MaleText_loc4`='呦喔！雷戈，送我们回去，赶快！', `MaleText_loc5`='哇喔!咱們得快點離開這!水爐，把我們傳送回去!快!', `MaleText_loc7`='¡Yaa-juu! ¡Larguémonos de aquí! ¡Forjavuelta, elévanos, RÁPIDO!' WHERE `ID`=39895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길! 물러날 수밖에 없군. 하지만 텔마플러그에겐 가망이 없어. 스스로 잘 알겠지만... 녀석은 시간을 버는 데만 성공했을 뿐이야.', `MaleText_loc4`='见鬼！我们必须撤退。但瑟玛普拉格已经失败了。他清楚这一点……现在他只是在垂死挣扎。', `MaleText_loc5`='該死!我們得往後撤。不過瑟瑪普拉格已經輸了，他自己明白這點...這只是在拖延時間罷了。', `MaleText_loc7`='¡Maldición! Tenemos que retroceder. Pero Termochufe está perdido y lo sabe... Sólo ganó tiempo.' WHERE `ID`=39896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부는 장악했으니 방사능이 사라지면 두 배의 병력으로 공격하여 놈리건을 되찾고 말 테다.', `MaleText_loc4`='我们控制了地面，等到辐射被清除干净，我们就会以更加强大的攻势彻底占领诺莫瑞根。', `MaleText_loc5`='守住地表，等輻射退去，到時我們會以兩倍的兵力殺進去奪回諾姆瑞根。', `MaleText_loc7`='Defendamos la superficie, cuando se disipe la radiación recapturaremos Gnomeregan con una fuerza el doble de ésta.' WHERE `ID`=39897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 이걸 좀 보고해야겠어!', `MaleText_loc4`='必须有人报告这里的情况！', `MaleText_loc5`='得有人回報這件事!', `MaleText_loc7`='¡Alguien tiene que informar de esto!', `FemaleText_loc1`='누군가 이걸 좀 보고해야겠어!', `FemaleText_loc4`='必须有人报告这里的情况！', `FemaleText_loc5`='得有人回報這件事!', `FemaleText_loc7`='¡Alguien tiene que informar de esto!' WHERE `ID`=39898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하라, 오우거. 누가 이 물건을 너희 일족에게 주었나?', `MaleText_loc4`='快说，食人魔。这些宝珠是谁给你们的？', `MaleText_loc5`='說，巨魔!是誰提供這些飾品給你們的部族的?', `MaleText_loc7`='Habla, ogro. ¿Quién le ha dado estos trastos a tu clan?' WHERE `ID`=39899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 전사들이여, 오그리마를 와해하려는 황혼의 망치단의 계략을 밝혀낸 $n의 용기에 경의를 표하자!', `MaleText_loc4`='部落的战士们，我们将赞颂$n的勇气。正是$g他:她;发现了暮光之锤侵害这座城市的阴谋！', `MaleText_loc5`='奧格瑪的人民，部落的戰士，今日，我們要向$n$g他:她;的勇氣致敬，暮光之錘意圖對我們的城市下手，而此人揭發了這項奸計!', `MaleText_loc7`='¡Guerreros de la Horda, hoy honramos a $n por su valor al desmantelar el plan que el Martillo Crepuscular tramaba contra Orgrimmar!' WHERE `ID`=39901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 소문들의 진상을 파악하고, 우리들 사이에 공포를 조장하려는 황혼의 망치단의 계획을 원천봉쇄할 것이다!', `MaleText_loc4`='我们必须揭开这些谣言的真相，阻止暮光之锤在我们之间散播恐惧！', `MaleText_loc5`='我們會發現那些傳言背後的事實，然後制止暮光之錘在奧格瑪街上散佈恐懼的行動!', `MaleText_loc7`='¡Debemos descubrir la verdad sobre esos rumores y detener la campaña del Martillo Crepuscular para extender el miedo entre nosotros!' WHERE `ID`=39902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하지 않겠다.', `MaleText_loc4`='不想说。', `MaleText_loc5`='不說。', `MaleText_loc7`='No hablar.' WHERE `ID`=39903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아아악!', `MaleText_loc4`='啊！', `MaleText_loc5`='哇啊啊啊啊啊!', `MaleText_loc7`='¡AAAAAAAAGH!' WHERE `ID`=39904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 너희에게 힘을 주었느냐?', `MaleText_loc4`='谁给的你能量？', `MaleText_loc5`='力量是誰給你們的?', `MaleText_loc7`='¿QUIÉN OS HA DADO PODER?' WHERE `ID`=39905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈 님이다!', `MaleText_loc4`='古加尔！', `MaleText_loc5`='丘加利!', `MaleText_loc7`='¡Cho''gall!' WHERE `ID`=39906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이라고?! 어디 있나?', `MaleText_loc4`='暮光之锤？！他们在哪儿？', `MaleText_loc5`='暮光之錘?!他們在哪?', `MaleText_loc7`='¡¿El Martillo Crepuscular?! ¿Dónde están?' WHERE `ID`=39907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 이제 가거라.', `MaleText_loc4`='很好。现在你可以滚了。', `MaleText_loc5`='很好。現在，你自己跳下去。', `MaleText_loc7`='Bien. Ahora lárgate.' WHERE `ID`=39908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈투의 전장! 혈투의 전장이다!', `MaleText_loc4`='厄运之槌！厄运之槌！', `MaleText_loc5`='厄運之槌!厄運之槌!', `MaleText_loc7`='¡La Masacre! ¡LA MASACRE!' WHERE `ID`=39909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스피릿혼 족장님, 더 늦기 전에 하늬자락 꼭대기에 지원군을 보내주시길 간청합니다.', `MaleText_loc4`='魂角酋长，我恳求你立刻向西岸峰派出援军，否则一切都将无法挽回。', `MaleText_loc5`='酋長魂角，我請求你現在派遣支援至西聯峰，在還來得及前。', `MaleText_loc7`='Jefe Almaspina, te ruego que envíes ayuda a la Cima Tramo Oeste ya, antes de que sea demasiado tarde.' WHERE `ID`=39912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리가 수백 미터 물 아래 잠겨 있습니다. 용감한 자들을 보내 우릴 도와주시면 안 되겠습니까?', `MaleText_loc4`='千针石林深埋在数百尺深的水底。你有勇气帮助我们吗？', `MaleText_loc5`='千針石林被淹沒在幾百英尺深的水之下。你可以施捨一些勇士來幫助我們嗎?', `MaleText_loc7`='Las Mil Agujes yacen en ruines bajo cientos de metros de agua. ¿Puedes prescindir de algunos valientes para que nos ayuden?' WHERE `ID`=39913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변으로 동쪽 산맥이 무너졌습니다. 남쪽 바닷물이 넘쳐 버섯구름 봉우리가 물속에 잠겼단 말입니다! 이러한 어려운 때에 우릴 도와줄 순 없습니까?', `MaleText_loc4`='大灾变把东部山脉碾碎。南海的水灌入并吞没了整个千针石林！你能在这紧要关头帮帮我们吗？', `MaleText_loc5`='大災變摧毀了東部群山。南海的水湧入將整個千針石林都給淹沒了!你可以在我們最需要幫忙的時候予以協助嗎?', `MaleText_loc7`='El Cataclismo derribó las montañas orientales. ¡Los Mares del Sur han entrado y han sumergido Las Mil Agujas por completo! ¿Puedes ayudarnos en este momento de necesidad?' WHERE `ID`=39914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 하늬자락 꼭대기에서 구호활동을 벌이는 우리를 도와주십시오. 버섯구름 봉우리가 파괴되었단 말입니다!', `MaleText_loc4`='拜托了。我们正在西岸峰展开救援工作。千针石林已经消亡了！', `MaleText_loc5`='拜託。我們正在西聯峰策劃救援行動。千針石林已經被夷平了!', `MaleText_loc7`='Te lo ruego. Estamos organizando una operación de rescate en la Cima Tramo Oeste. ¡La población de Las Mil Agujas está diezmada!' WHERE `ID`=39915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이 페랄라스도 강타했다는 점은 잘 알겠으나, 모자케 야영지는 비교적 안전한 것 같군요. 용감한 자들을 지원해 주실 수 없습니까?', `MaleText_loc4`='我明白大灾变也同样袭击了菲拉斯，但莫沙彻营地看上去还相对安全。你愿意伸出援手吗？', `MaleText_loc5`='我瞭解菲拉斯也受到了大災變的影響，但莫沙徹營地相較之下還算安全。你可以派遣一些勇士嗎?', `MaleText_loc7`='Tengo entendido que el Cataclismo también ha afectado a Feralas, pero el Campamento Mojache parece relativamente a salvo. ¿No puedes enviar algunos valientes?' WHERE `ID`=39916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늬자락 꼭대기에 도움을 주실 수 없다면, 높새바람 봉우리의 피난민들을 모자케 야영지의 구석에라도 머물도록 할 순 없겠습니까?', `MaleText_loc4`='要是你不能派帮手前往西岸峰，也许能让乱风岗的难民到莫沙彻营地的边上待一阵子？', `MaleText_loc5`='如果你無法派遣支援到西聯峰，我們可以將亂風崗的難民安置在莫沙徹營地的邊緣嗎?', `MaleText_loc7`='Si no puedes enviar ayuda a la Cima Tramo Oeste, ¿podrían los refugiados del Poblado Viento Libre quedarse alrededor del Campamento Mojache?' WHERE `ID`=39917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 버섯구름 봉우리가 지원을 받지 못한다면, 그림토템 부족이 움직일 거란 생각에 두렵습니다. 지금으로선 우리 자신을 그리 오래 지킬 상황이 못 됩니다.', `MaleText_loc4`='我担心要是援军不能尽快赶到千针石林的话，恐怖图腾就会开始行动了。我们无论如何都坚守不了多久。', `MaleText_loc5`='如果千針石林無法儘快獲得支援，我怕恐怖圖騰會有所行動。我們現在的力量是撐不久的。', `MaleText_loc7`='Temo que los Tótem Siniestro actúen si no recibimos refuerzos en Las Mil Agujas muy pronto. No estamos en posición de defendernos durante mucho tiempo.' WHERE `ID`=39918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스피릿혼 족장님, 버섯구름 봉우리의 슈할로가 무너진다면, 머지않아 그대의 집 앞에 그림토템 부족이 어슬렁거릴 겁니다. 지금 당장 조치해야 합니다!', `MaleText_loc4`='要是千针石林的舒哈鲁被击败，恐怖图腾部族很快就会出现在你家门口。现在是时候行动了，魂角酋长！', `MaleText_loc5`='如果千針石林的舒哈魯淪陷了，恐怖圖騰很快就會出現在你家門口。再不行動就沒機會了，酋長魂角!', `MaleText_loc7`='Si los Shu''halo de Las Mil Agujas caen, el clan Tótem Siniestro no tardará en presentarse a las puertas de tus tiendas. ¡Es el momento de actuar, Jefe Almaspina!' WHERE `ID`=39919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야생의 마법인 뮤세크 영혼의 방식을 연구하려고 이곳에 왔습니다. 의술사 우제리 님께서는 숲에 사는 작은 생물들로 연습을 시작할 수 있도록 저를 보내셨답니다.', `FemaleText_loc4`='我来这里是为了研究灵魂精华——野性魔法的作用方式。巫医尤克里派我来从森林里的低等生物入手。', `FemaleText_loc5`='我是來這研究靈魂精華的，野生的魔法。巫醫烏澤里派我來這使用森林中較弱小的生物來練習。', `FemaleText_loc7`='He venido para estudiar el camino de los espíritus de muisek, la magia salvaje. El médico brujo Uzeri me ha enviado para practicar con las criaturas menores del bosque.' WHERE `ID`=39920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $c|1이여;여;.$B$B산들이 무너지고 대격변의 영향으로 바닷물이 밀려 들어와 버섯구름 봉우리가 잠겼네.$B$B지금 그대의 도움이 필요하네!', `MaleText_loc4`='你好，$c。$B$B山脉崩塌，大灾变造成海水灌入，淹没了千针石林。$B$B我们需要你的帮助，就是现在！', `MaleText_loc5`='你好，$c。$B$B大災變使山崩塌了，海水湧進把千針石林給淹沒了。$B$B我們現在急需你的幫忙!', `MaleText_loc7`='Saludos, $c.$b$bLas montañas se han derrumbado y el Cataclismo ha provocado que los mares hayan entrado y arrasado Las Mil Agujas.$b$bNecesitamos tu ayuda, ¡ya!' WHERE `ID`=39921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉰, 하늬자락 꼭대기로 가야 합니다!', `MaleText_loc4`='夏恩，我得赶往西岸峰！', `MaleText_loc5`='夏恩，我要到西聯峰!', `MaleText_loc7`='¡Shyn, tengo que ir a la Cima Tramo Oeste!', `FemaleText_loc1`='쉰, 하늬자락 꼭대기로 가야 합니다!', `FemaleText_loc4`='夏恩，我得赶往西岸峰！', `FemaleText_loc5`='夏恩，我要到西聯峰!', `FemaleText_loc7`='¡Shyn, tengo que ir a la Cima Tramo Oeste!' WHERE `ID`=39922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 나 좀 도와주시오! 놈들이 날 죽이려 하오!', `MaleText_loc4`='请帮帮我！他们要杀我！', `MaleText_loc5`='拜託，幫幫我!他們要殺我!', `MaleText_loc7`='¡Por favor, ayúdenme! ¡Me matarán!' WHERE `ID`=39923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정으로 새로운 능력을 얻었습니다! 이 능력으로 소환된 정령들을 처치하십시오.', `MaleText_loc4`='水晶让你获得了新的能力！用这能力击败被召唤的元素吧。', `MaleText_loc5`='水晶賦予你新的能力!運用這些能力擊敗那些召喚出來的元素。', `MaleText_loc7`='¡El cristal te ha proporcionado nuevas habilidades! Utilízalas para derrotar a los elementales invocados.' WHERE `ID`=39924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주인님의 불꽃으로 다 타버려라!', `FemaleText_loc4`='在主人的烈焰中燃烧吧！', `FemaleText_loc5`='在吾主的火焰下燃燒吧!', `FemaleText_loc7`='¡Ardan en las llamas del amo!' WHERE `ID`=39925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정의 힘으로 저 정령들을 물리치시오! 나는 오래 버티지 못할 것 같소...', `MaleText_loc4`='使用水晶的力量击败元素！我坚持不了多久……', `MaleText_loc5`='運用水晶的力量擊敗那些元素!我撐不了多久的...', `MaleText_loc7`='¡Utiliza los poderes del cristal para derrotar a los elementales! No resistiré mucho más...' WHERE `ID`=39926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 부하였습니다. 수많은 전투를 함께했죠...$b$b그 짐승들이 후회하게 해 주겠습니다!', `MaleText_loc4`='这是个好人，$r。我们曾在多次战争中并肩作战……$b$b这些野兽有债要偿！', `MaleText_loc5`='他是個好同伴，$r。我們曾一起經歷過許多的戰場...$b$b我要這些野獸血債血還!', `MaleText_loc7`='Era un buen hombre, $r. Luchamos juntos en muchas batallas...$b$b¡Esas bestias deben pagar!' WHERE `ID`=39927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방사능오염기 3000 가동. 경보. 비상사태. 10분 안에 최소 안전 거리 밖으로 이동하세요.', `MaleText_loc4`='3000型辐射器已开启。注意，紧急。你有十分钟来抵达最近的安全区域。', `MaleText_loc5`='輻射儀3000啟動完畢。注意。警告。你只有10分鐘可以逃到安全距離外。', `MaleText_loc7`='Irradiador 3000 activado. Atención. Emergencia. Tiene diez minutos para alcanzar la distancia mínima de seguridad.' WHERE `ID`=39928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*삑* 경보. 비상사태. 10초 안에 최소 안전 거리 밖으로 이동하세요.', `MaleText_loc4`='*哔*注意，紧急。你有十秒钟来抵达最近的安全区域。', `MaleText_loc5`='*嗶* 注意。警告。你只有10秒鐘可以逃到安全距離外。', `MaleText_loc7`='*BIP* Atención. Emergencia. Ahora tiene diez segundos para alcanzar la distancia mínima de seguridad.' WHERE `ID`=39929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비로운 수정의 힘을 빌려 새로운 능력을 얻은 다음, 그 능력으로 듀락 플레임스피커를 보호하십시오.', `MaleText_loc4`='从这块神秘的水晶中获取新的能力，并用这些能力保护火语者杜莱克！', `MaleText_loc5`='和神秘的水晶互動以獲得新的能力，並使用這些能力守衛杜雷克·火語者。', `MaleText_loc7`='Interactúa con el misterioso cristal para obtener nuevos poderes y utilízalos para defender a Durak Hablallamas.' WHERE `ID`=39930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 절대로 이 겁쟁이들 앞에 무릎 꿇지 않을 것이다! 호드는 어떠한 적 앞에서도 단결하여 맞설 것이다! 록타르 오가르!', `MaleText_loc4`='我们绝不向这些懦夫低头！部落将团结一致对抗所有敌人！Lok''tar Ogar！', `MaleText_loc5`='我們永遠不會對懦夫投降!部落會團結一致對抗所有敵人!(獸人語)不勝即亡!', `MaleText_loc7`='¡Nunca sucumbiremos ante esos cobardes! ¡La Horda resistirá unida contra todos sus enemigos! ¡Lok''tar Ogar!' WHERE `ID`=39931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침입한 대가를 치르게 해 주마!', `FemaleText_loc4`='擅闯者死！', `FemaleText_loc5`='闖入者死死死死死!', `FemaleText_loc7`='¡Sssufrirán por esta intrusión!' WHERE `ID`=39932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연한 결과다...', `FemaleText_loc4`='本该如此……', `FemaleText_loc5`='本來就該這樣....', `FemaleText_loc7`='Como debía ser…' WHERE `ID`=39933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할리온 님께서 기뻐하시리라.', `FemaleText_loc4`='海里昂会高兴的。', `FemaleText_loc5`='海萊恩會很滿意的。', `FemaleText_loc7`='Halion estará feliz.' WHERE `ID`=39934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 날 즐겁게 해주러 왔나 보군.', `MaleText_loc4`='啊，娱乐要开始了！', `MaleText_loc5`='啊，終於有樂子了。', `MaleText_loc7`='Ah, un poco de entretenimiento.' WHERE `ID`=39935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 건... 예상하지 못했다..', `MaleText_loc4`='我……没想到会这样……', `MaleText_loc5`='沒...想到會這樣....', `MaleText_loc7`='No... me lo esperaba…' WHERE `ID`=39936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발타루스는 누구도 살려두지 않는다!', `MaleText_loc4`='巴尔萨鲁斯从不留活口！', `MaleText_loc5`='巴爾薩魯斯不會留活口!', `MaleText_loc7`='¡Baltharus no deja sobrevivientes!' WHERE `ID`=39937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상에는 영웅이 너무 많아.', `MaleText_loc4`='这个世界的英雄够多了。', `MaleText_loc5`='這世界的英雄夠多了。', `MaleText_loc7`='Este mundo ya tiene suficientes héroes…' WHERE `ID`=39938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통이 두 배면, 재미가 반이지.', `MaleText_loc4`='双倍的痛苦不过是个开始。', `MaleText_loc5`='別人的痛苦就是我的快樂。', `MaleText_loc7`='El doble de dolor, la mitad de la diversión.' WHERE `ID`=39939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 티탄들... 왜 만드는 것마다 각기 다른 작동 원리를 쓰는 거지?', `MaleText_loc4`='该死的泰坦……为什么他们的每一套设备中都要使用不同机械装置？', `MaleText_loc5`='該死的泰坦們...他們為什麼要用不同的方式來造物?', `MaleText_loc7`='Condenados titanes... ¿Por qué utilizan un conjunto de mecanismos distinto en cada una de sus instalaciones?' WHERE `ID`=39940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고맙소. 난 휴식을 좀 취한 다음에 오그리마로 돌아가겠소.', `MaleText_loc4`='感谢你救了我。等我恢复了体力，就会回到奥格瑞玛去。', `MaleText_loc5`='感謝你伸出的援手。等我狀況稍微好一點之後，我會自己回去奧格瑪。', `MaleText_loc7`='Gracias por salvarme. Volveré a Orgrimmar una vez me haya recuperado un poco.' WHERE `ID`=39941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 벌레들아! 너무 늦었다. 루비 성소는 이미 끝났다!', `MaleText_loc4`='多管闲事的虫子！你们来晚了。红玉圣殿已经沦陷了！', `MaleText_loc5`='愛管閒事的小蟲!你們晚了一步。晶紅聖所失陷了!', `MaleText_loc7`='¡Insectos entrometidos! Llegan tarde. ¡El Sagrario Rubí está perdido!' WHERE `ID`=39942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캬오! $r 좋은 친구다. 따라와라! 침입자 찾는다!', `MaleText_loc4`='咪呜！$R是我们的好朋友。快跟上！我们要找到入侵者！', `MaleText_loc5`='嗶!$R是好朋友。跟著!我們找入侵者!', `MaleText_loc7`='¡Meep! $R es $g buen amigo:buena amiga;. ¡Seguir ahora! ¡Nosotros encontrar intruso!' WHERE `ID`=39943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 악당 찾는다! 빨리!', `MaleText_loc4`='我们发现坏人了！赶快！', `MaleText_loc5`='我們找出邪惡的!快點!', `MaleText_loc7`='¡Encontraremos al malo! ¡Deprisa!' WHERE `ID`=39944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 나를 찾았지? 그건 별로 중요하지 않아... 죽어줘야겠다!', `MaleText_loc4`='你是怎么找到我的？这无关紧要……反正你得死！', `MaleText_loc5`='你如何找到我的?無所謂...你將死去!', `MaleText_loc7`='¿Cómo me has encontrado? No importa... ¡Morirás!', `FemaleText_loc1`='어떻게 나를 찾은 거지? 그건 별로 중요하지 않아... 죽어줘야겠다!', `FemaleText_loc4`='你是怎么找到我的？这无关紧要……反正你得死！', `FemaleText_loc5`='你如何找到我的?無所謂...你將死去!', `FemaleText_loc7`='¿Cómo me has encontrado? No importa... ¡Morirás!' WHERE `ID`=39945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 발각된 건가? 죽어줘야겠군!', `MaleText_loc4`='我被发现了？受死吧！', `MaleText_loc5`='我被發現了?死吧!', `MaleText_loc7`='¿Me han descubierto? ¡Hora de morir!', `FemaleText_loc1`='내가 발각된 건가? 죽어줘야겠군!', `FemaleText_loc4`='我被发现了？受死吧！', `FemaleText_loc5`='我被發現了?死吧!', `FemaleText_loc7`='¿Me han descubierto? ¡Hora de morir!' WHERE `ID`=39946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $c 녀석아, 내가 여기 있다는 사실을 누구한테 알리려고?', `MaleText_loc4`='你别想泄漏我的行踪，$c！', `MaleText_loc5`='我不會讓你把我的位置交出去，$c!', `MaleText_loc7`='¡No revelarás mi posición, $c!', `FemaleText_loc1`='이 $c 녀석아, 내가 여기 있다는 사실을 누구한테 알리려고?', `FemaleText_loc4`='你别想泄漏我的行踪，$c！', `FemaleText_loc5`='我不會讓你把我的位置交出去，$c!', `FemaleText_loc7`='¡No revelarás mi posición, $c!' WHERE `ID`=39947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 찾아낼 순 있었다 해도, 다른 사람에게 알리지는 못할 것이다!', `MaleText_loc4`='就算你发现了我，你也别想把消息带给别人！', `MaleText_loc5`='你或許找到我了，但將無法活著把這訊息告知其他人!', `MaleText_loc7`='¡Puede que me hayas encontrado, pero no les contarás nada a los demás!', `FemaleText_loc1`='나를 찾아낼 순 있었다 해도, 다른 사람에게 알리지는 못할 것이다!', `FemaleText_loc4`='就算你发现了我，你也别想把消息带给别人！', `FemaleText_loc5`='你或許找到我了，但將無法活著把這訊息告知其他人!', `FemaleText_loc7`='¡Puede que me hayas encontrado, pero no les contarás nada a los demás!' WHERE `ID`=39948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서판은 절대 못 내준다!', `MaleText_loc4`='你永远也得不到这些石板！', `MaleText_loc5`='你拿不到石板的!', `MaleText_loc7`='¡Nunca conseguirás las tablillas!' WHERE `ID`=39949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 계속해라!', `MaleText_loc4`='继续进攻！', `MaleText_loc5`='繼續攻擊!', `MaleText_loc7`='¡Continuen con el asalto!', `FemaleText_loc1`='공격을 계속해라!', `FemaleText_loc4`='继续进攻！', `FemaleText_loc5`='繼續攻擊!', `FemaleText_loc7`='¡Continuen con el asalto!' WHERE `ID`=39950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 서판을 갖고야 말겠다!', `MaleText_loc4`='我会得到这些石板！', `MaleText_loc5`='我會拿到那些石板的!', `MaleText_loc7`='¡Conseguiré esas tablillas!', `FemaleText_loc1`='저 서판을 갖고야 말겠다!', `FemaleText_loc4`='我会得到这些石板！', `FemaleText_loc5`='我會拿到那些石板的!', `FemaleText_loc7`='¡Conseguiré esas tablillas!' WHERE `ID`=39951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 심부름꾼을 처치하라!', `MaleText_loc4`='干掉信使！', `MaleText_loc5`='殺掉信差!', `MaleText_loc7`='¡Maten al mensajero!', `FemaleText_loc1`='저 심부름꾼을 처치하라!', `FemaleText_loc4`='干掉信使！', `FemaleText_loc5`='殺掉信差!', `FemaleText_loc7`='¡Maten al mensajero!' WHERE `ID`=39952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아에시나 님은 우리의 기도에 아무 대답이 없으세요. 라그나로스의 불타는 하수인들은 우리를 벼랑까지 내몰았고요. 여기서 그들을 멈추지 못한다면, 세계수는 큰 불길에 휩싸인 한낱 그루터기와 다를 게 없어요.', `FemaleText_loc4`='我们向艾森娜发出的祈求没有得到回应。拉格纳罗斯麾下的燃烧爪牙已经将我们逼到了悬崖的边缘。如果我们不能在此终止他们的行径，世界之树将被大火烧得只剩下残桩断枝！', `FemaleText_loc5`='我們對艾森娜的祈求沒有回應。拉格納羅斯的火焰爪牙已經將我們逼至絕境。如果再沒人阻止它們，世界之樹將會在烈焰中化為枯木!', `FemaleText_loc7`='Nuestras plegarias a Aessina no reciben respuesta. Los esbirros ardientes de Ragnaros nos han llevado al límite. Si no los detenemos aquí, ¡el Árbol del Mundo no será más que un tocón envuelto en llamas!' WHERE `ID`=39953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생명의 끈이 끊어졌도다.$B$B꿈꾸는 자들을 위해 복수하리라.', `FemaleText_loc4`='生命的希翼已被斩断。$B$B梦游者一定会复仇的。', `FemaleText_loc5`='生命的希冀已被破壞。$B$B夢遊者的仇必須要報。', `FemaleText_loc7`='Los hilos de la vida se han cortado.$b$bLos soñadores deben ser vengados.' WHERE `ID`=39954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나와라, 타에라! 내가 그대 앞에 있도다!', `FemaleText_loc4`='走上前来，泰拉尔！我就站在你面前！', `FemaleText_loc5`='出來，泰拉爾!我挑戰你!', `FemaleText_loc7`='¡Muéstrate, Taerar! ¡Me presento ante ti!' WHERE `ID`=39956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 돌아온 걸 알고 있었다, 이손드레... 그저 시간 문제였을 뿐이야...', `MaleText_loc4`='我就知道你会回来的，伊森德雷……只是时间问题……', `MaleText_loc5`='我知道你一定會回來的，伊索德雷...這只是時間上的問題...', `MaleText_loc7`='Sabía que volverías, Ysondre... Era cuestión de tiempo...' WHERE `ID`=39957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화? 평화라고?', `MaleText_loc4`='平静？“平静”？', `MaleText_loc5`='和平?和平?', `MaleText_loc7`='¿Paz? ¿PAZ?' WHERE `ID`=39958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타에라, 난 이 모든 일을 끝내고자 돌아왔다. 이 땅은 마침내 평화를 맞을 거다.', `FemaleText_loc4`='我回来只为了结这件事，泰拉尔。这片土地终将获得平静。', `FemaleText_loc5`='我回來終止這一切，泰拉爾。這片土地最終將獲得和平。', `FemaleText_loc7`='Solo he vuelto para acabar con esto, Taerar. Esta tierra por fin conocerá la paz.' WHERE `ID`=39959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 방해하러 오신 건가요? 우리는 그저 조용히 있고 싶을 뿐이에요.', `FemaleText_loc4`='你到这里来是为了打扰我们吗？我们只想在静瑟中独处。', `FemaleText_loc5`='你是來這裡騷擾我們的嗎?我們只想在這裡安靜度日。', `FemaleText_loc7`='¿Has venido a molestarnos? Solo queremos que nos dejen en paz.' WHERE `ID`=39960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기를 뒤지고 다닌다고 해서 얻을 건 별로 없을 겁니다, 친구. 도시 안에 있는 우리 친구들을 만나 보면 더 많을 걸 알 수 있을 겁니다.', `MaleText_loc4`='在这里晃荡是没用的，朋友。这座城市中有许多我们的人，你可以从他们那里得到更多关于我们的信息。', `MaleText_loc5`='在這裡探頭探腦並沒有幫助，朋友。你可以從我們在城裡的成員那裡進一步了解我們。', `MaleText_loc7`='Curiosear por aquí no te ayudará mucho, camarada. Podrás saber más sobre nosotros hablando con nuestros miembros en la ciudad.' WHERE `ID`=39961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인이 올 곳이 아닙니다, 이방인이여. 스톰윈드로 돌아가십시오.', `MaleText_loc4`='这里没有地方留给外人。回暴风城去吧，陌生人。', `MaleText_loc5`='陌生人，這裡不歡迎外來者。回暴風城去吧。', `MaleText_loc7`='Los extraños no son bienvenidos aquí. Regresa a Ventormenta.' WHERE `ID`=39962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 정수는... 사라지지... 않을 거다...', `MaleText_loc4`='我的精华将……永存……。', `MaleText_loc5`='我的意志...是...不滅的...', `MaleText_loc7`='Mi... esencia... persistirá...' WHERE `ID`=39963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말이 다가오고 있습니다!', `MaleText_loc4`='世界末日即将到来！', `MaleText_loc5`='世界末日即將降臨!', `MaleText_loc7`='¡El fin del mundo está a punto de llegar!', `FemaleText_loc1`='세상의 종말이 다가오고 있어요!', `FemaleText_loc4`='世界末日即将到来！', `FemaleText_loc5`='世界末日即將降臨!', `FemaleText_loc7`='¡El fin del mundo está a punto de llegar!' WHERE `ID`=39964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스에 종말이 다가오고 있습니다. 회개하십시오!', `MaleText_loc4`='艾泽拉斯即将完结。赶快忏悔吧！', `MaleText_loc5`='艾澤拉斯的末日到了。找到你的歸屬吧!', `MaleText_loc7`='El fin de Azeroth se acerca. ¡Confiesen sus pecados!', `FemaleText_loc1`='아제로스에 종말이 다가오고 있어요! 회개하세요!', `FemaleText_loc4`='艾泽拉斯即将完结。赶快忏悔吧！', `FemaleText_loc5`='艾澤拉斯的末日到了。找到你的歸屬吧!', `FemaleText_loc7`='El fin de Azeroth se acerca. ¡Confiesen sus pecados!' WHERE `ID`=39965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 갑시다, 형제자매들이여! 그리고 진실을 배웁시다!', `MaleText_loc4`='跟我来，兄弟姐妹们，去了解这个世界的真相吧！', `MaleText_loc5`='跟著我來，兄弟姊妹們，並了解真相!', `MaleText_loc7`='¡Vengan conmigo, hermanos y hermanas, y descubran la verdad!', `FemaleText_loc1`='함께 가요, 형제자매님! 그리고 진실을 배우세요!', `FemaleText_loc4`='跟我来，兄弟姐妹们，去了解这个世界的真相吧！', `FemaleText_loc5`='跟著我來，兄弟姊妹們，並了解真相!', `FemaleText_loc7`='¡Vengan conmigo, hermanos y hermanas, y descubran la verdad!' WHERE `ID`=39966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이 곧 멸망할 겁니다! 우리와 함께해 구원받읍시다!', `MaleText_loc4`='我们的世界将四分五裂。加入我们才能活命！', `MaleText_loc5`='我們的世界就要分崩離析了。加入我們，這樣你才能活下去!', `MaleText_loc7`='Nuestro mundo se destruirá. ¡Únanse a nosotros y vivirán!', `FemaleText_loc1`='세상이 곧 멸망할 거예요! 우리와 함께해 구원받아요!', `FemaleText_loc4`='我们的世界将四分五裂。加入我们才能活命！', `FemaleText_loc5`='我們的世界就要分崩離析了。加入我們，這樣你才能活下去!', `FemaleText_loc7`='Nuestro mundo se destruirá. ¡Únanse a nosotros y vivirán!' WHERE `ID`=39967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 다가오는 종말을 피할 수 있습니다!', `MaleText_loc4`='想要从即将到来的劫难中获得拯救，现在还不晚！', `MaleText_loc5`='災變即將到來，現在拯救自己還不算太晚!', `MaleText_loc7`='¡No es demasiado tarde para salvarse de la catástrofe que se avecina!', `FemaleText_loc1`='아직 다가오는 종말을 피할 수 있어요!', `FemaleText_loc4`='想要从即将到来的劫难中获得拯救，现在还不晚！', `FemaleText_loc5`='災變即將到來，現在拯救自己還不算太晚!', `FemaleText_loc7`='¡No es demasiado tarde para salvarse de la catástrofe que se avecina!' WHERE `ID`=39968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 세상을 삼켜버릴 겁니다!', `MaleText_loc4`='整个世界都将被元素吞噬！', `MaleText_loc5`='這世界將會被元素所吞噬!', `MaleText_loc7`='¡Los elementos consumirán nuestro mundo!', `FemaleText_loc1`='정령들이 세상을 삼켜버릴 거예요!', `FemaleText_loc4`='整个世界都将被元素吞噬！', `FemaleText_loc5`='這世界將會被元素所吞噬!', `FemaleText_loc7`='¡Los elementos consumirán nuestro mundo!' WHERE `ID`=39969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스에서 죽을 수는 없습니다! 저와 함께 구원을 얻읍시다!', `MaleText_loc4`='没有必要和艾泽拉斯一同灭亡。跟随我，得生存！', `MaleText_loc5`='你不用和艾澤拉斯一起面對滅亡的結局。跟我來，跟我一起活下去!', `MaleText_loc7`='No tienen por qué desaparecer junto con Azeroth. ¡Síganme y vivan!', `FemaleText_loc1`='아제로스에서 죽을 수는 없어요! 저와 함께 구원을 얻어요!', `FemaleText_loc4`='没有必要和艾泽拉斯一同灭亡。跟随我，得生存！', `FemaleText_loc5`='你不用和艾澤拉斯一起面對滅亡的結局。跟我來，跟我一起活下去!', `FemaleText_loc7`='No tienen por qué desaparecer junto con Azeroth. ¡Síganme y vivan!' WHERE `ID`=39970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분의 고민, 그리고 집과 가진 것들을 버리고 우리와 함께하십시오!', `MaleText_loc4`='抛下你们的家园，你们的财产，还有你们所珍爱的一切，加入我们吧！', `MaleText_loc5`='離開你們的家園，你們的身外之物，你們的煩惱，加入我們吧!', `MaleText_loc7`='¡Dejen atrás sus casas, sus posesiones y sus preocupaciones, y únanse a nosotros!', `FemaleText_loc1`='여러분의 고민, 그리고 집과 가진 것들을 버리고 우리와 함께 해요!', `FemaleText_loc4`='抛下你们的家园，你们的财产，还有你们所珍爱的一切，加入我们吧！', `FemaleText_loc5`='離開你們的家園，你們的身外之物，你們的煩惱，加入我們吧!', `FemaleText_loc7`='¡Dejen atrás sus casas, sus posesiones y sus preocupaciones, y únanse a nosotros!' WHERE `ID`=39971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 이 퀘스트를 완료하지 못하셨군요!', `MaleText_loc4`='你还没完成使命！', `MaleText_loc5`='你還未完成任務!', `MaleText_loc7`='¡No has completado la misión!' WHERE `ID`=39972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 퀘스트를 완료하셨습니다!', `MaleText_loc4`='你已经完成了使命！', `MaleText_loc5`='你已完成任務!', `MaleText_loc7`='¡Has completado la misión!' WHERE `ID`=39973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아 버리겠군. 참, 세상 한번 잘 돌아간다!', `MaleText_loc4`='这正是我们需要的，更多的蠢货！', `MaleText_loc5`='正是我們需要的，更多的神經病!', `MaleText_loc7`='Justo lo que nos hacía falta ¡más lunáticos!', `FemaleText_loc1`='돌아 버리겠군. 참, 세상 한번 잘 돌아간다!', `FemaleText_loc4`='这正是我们需要的，更多的蠢货！', `FemaleText_loc5`='正是我們需要的，更多的神經病!', `FemaleText_loc7`='Justo lo que nos hacía falta ¡más lunáticos!' WHERE `ID`=39974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맨날 같은 말 하고 또 하고 지겹지도 않아?', `MaleText_loc4`='难道你们还没有厌倦这样一遍又一遍地重复同一件事吗？', `MaleText_loc5`='你們這些人一直重複講過的話都不會厭煩嗎?', `MaleText_loc7`='¿Es que no se aburren de repetir lo mismo una y otra vez?', `FemaleText_loc1`='맨날 같은 말 하고 또 하고 지겹지도 않아?', `FemaleText_loc4`='难道你们还没有厌倦这样一遍又一遍地重复同一件事吗？', `FemaleText_loc5`='你們這些人一直重複講過的話都不會厭煩嗎?', `FemaleText_loc7`='¿Es que no se aburren de repetir lo mismo una y otra vez?' WHERE `ID`=39975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 가만히 좀 놔두라고, 이 이교도 놈아!', `MaleText_loc4`='教徒们，不要再扰乱和平了！', `MaleText_loc5`='不要再擾亂和平了，教徒!', `MaleText_loc7`='¡Cultor, deja de perturbar la paz!', `FemaleText_loc1`='우릴 가만히 좀 놔두라고, 이 이교도 놈아!', `FemaleText_loc4`='教徒们，不要再扰乱和平了！', `FemaleText_loc5`='不要再擾亂和平了，教徒!', `FemaleText_loc7`='¡Cultor, deja de perturbar la paz!' WHERE `ID`=39976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런 거 걸친 녀석들하고는 상종도 하지 말아야지!', `MaleText_loc4`='穿成这个德行还想让我听你的？', `MaleText_loc5`='我才不會聽穿那種衣服的人講的話!', `MaleText_loc7`='¡Como si yo fuera a escuchar a alguien con esas pintas!', `FemaleText_loc1`='저런 거 걸친 녀석들하고는 상종도 하지 말아야지!', `FemaleText_loc4`='穿成这个德行还想让我听你的？', `FemaleText_loc5`='我才不會聽穿那種衣服的人講的話!', `FemaleText_loc7`='¡Como si yo fuera a escuchar a alguien con esas pintas!' WHERE `ID`=39977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 저것 봐! 여군주 실바나스의 어릿광대가 새로 왔어!', `MaleText_loc4`='嘿，看啊，希尔瓦娜斯女士有了个新的傻瓜弄臣！', `MaleText_loc5`='嘿，看看，希瓦娜斯女士有個新的宮廷小丑了!', `MaleText_loc7`='¡Oye, mira, Lady Sylvanas tiene un nuevo bufón de la corte!', `FemaleText_loc1`='어이, 저것 봐! 여군주 실바나스의 어릿광대가 새로 왔어!', `FemaleText_loc4`='嘿，看啊，希尔瓦娜斯女士有了个新的傻瓜弄臣！', `FemaleText_loc5`='嘿，看看，希瓦娜斯女士有個新的宮廷小丑了!', `FemaleText_loc7`='¡Oye, mira, Lady Sylvanas tiene un nuevo bufón de la corte!' WHERE `ID`=39978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 관심 없으니까 딴 데 가서 알아보셔.', `MaleText_loc4`='为什么你不去找找会在乎它的人？', `MaleText_loc5`='你幹嘛不去有人願意聽的地方說?', `MaleText_loc7`='¿Por qué no lo llevas a un lugar donde pueda interesar a la gente?', `FemaleText_loc1`='우린 관심 없으니까 딴 데 가서 알아보셔.', `FemaleText_loc4`='为什么你不去找找会在乎它的人？', `FemaleText_loc5`='你幹嘛不去有人願意聽的地方說?', `FemaleText_loc7`='¿Por qué no lo llevas a un lugar donde pueda interesar a la gente?' WHERE `ID`=39979;
