UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 봐, 대족장님께서 재미있는 걸 보내셨다!', `MaleText_loc4`='看啊，酋长给我们送来了娱兴节目！', `MaleText_loc5`='嘿你看，從大酋長那來的餘興節目!', `MaleText_loc7`='¡Mira, el jefe de guerra nos ha enviado un poco de diversión!', `FemaleText_loc1`='저것 봐, 대족장님께서 재미있는 걸 보내셨다!', `FemaleText_loc4`='看啊，酋长给我们送来了娱兴节目！', `FemaleText_loc5`='嘿你看，從大酋長那來的餘興節目!', `FemaleText_loc7`='¡Mira, el jefe de guerra nos ha enviado un poco de diversión!' WHERE `ID`=39981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 돌망치 일족이여! 호드의 힘을 보여주자!', `MaleText_loc4`='石槌为部落而战！', `MaleText_loc5`='石槌氏族登場!為了部落!', `MaleText_loc7`='¡Llegan Quebrantarrocas POR LA HORDA!', `FemaleText_loc1`='일어나라, 돌망치 일족이여! 호드의 힘을 보여주자!', `FemaleText_loc4`='石槌为部落而战！', `FemaleText_loc5`='石槌氏族登場!為了部落!', `FemaleText_loc7`='¡Llegan Quebrantarrocas POR LA HORDA!' WHERE `ID`=39982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우욱...$b$b기분이... 좋지 않아요...', `MaleText_loc4`='啊……$b$b我的感觉……不太好……', `MaleText_loc5`='呃...$b$b我感覺...不是很好...', `MaleText_loc7`='Ugh...$b$bNo me encuentro... muy bien...' WHERE `ID`=39983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $c님.$b$b거의 죽을 뻔했다고요.', `FemaleText_loc4`='多谢你，$c。$b$b我差一点儿死在那了。', `FemaleText_loc5`='謝謝你，$c。$b$b我差點就掛了。', `FemaleText_loc7`='Gracias, $c.$b$bCasi muero ahí fuera.' WHERE `ID`=39984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 버틸 수가 없소...', `MaleText_loc4`='我坚持不住了……', `MaleText_loc5`='我已經撐不下去了...', `MaleText_loc7`='No puedo aguantar más...' WHERE `ID`=39985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건...', `FemaleText_loc4`='这是……', `FemaleText_loc5`='這是...', `FemaleText_loc7`='Esto es...' WHERE `ID`=39986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정으로 심각하군. 이 병의 정확한 원인을 찾아야만 하오. 우리의 땅을 위해서...', `MaleText_loc4`='情势的确十分严峻。我们必须找到这种疾病的真正诱因——为了这片土地。', `MaleText_loc5`='這情況很糟。我們必須找到這個疾病真正的起因，為了這片大地。', `MaleText_loc7`='Esto es como una tumba. Debemos encontrar el origen de esta enfermedad, por el bien de esta tierra.' WHERE `ID`=39987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 가면을 쓴 녹색용이시여! 제가 이런 영광을 얻을 줄을 생각조차 못 했...', `MaleText_loc4`='一头化身成凡人的绿龙！我从没有想过能够得到这样的光荣……', `MaleText_loc5`='一個偽裝成凡人的綠龍!我沒想到我會有這個榮幸...', `MaleText_loc7`='¡Un dragón Verde en forma humana! Nunca creí que tendría el honor de...' WHERE `ID`=39988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 백성을 위해 이 땅을 지키려고 여기에 왔소.', `MaleText_loc4`='我们来此为我们的人民守护这些土地。', `MaleText_loc5`='我們來到這為我們的人民保護這片大地。', `MaleText_loc7`='Estamos aquí para conservar estas tierras para nuestro pueblo.' WHERE `ID`=39989;
