UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다!', `MaleText_loc4`='做得好！', `MaleText_loc5`='幹得好!', `MaleText_loc7`='¡Bien hecho!', `FemaleText_loc1`='잘하셨습니다!', `FemaleText_loc4`='做得好！', `FemaleText_loc5`='幹得好!', `FemaleText_loc7`='¡Bien hecho!' WHERE `ID`=39992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고삐를 놓칠 것 같습니다. 조심하십시오!', `MaleText_loc4`='你失去控制了。小心！', `MaleText_loc5`='你沒抓穩。小心!', `MaleText_loc7`='Estás perdiendo agarre. ¡Ten cuidado!', `FemaleText_loc1`='고삐를 놓칠 것 같습니다. 조심하십시오!', `FemaleText_loc4`='你失去控制了。小心！', `FemaleText_loc5`='你沒抓穩。小心!', `FemaleText_loc7`='Estás perdiendo agarre. ¡Ten cuidado!' WHERE `ID`=39993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\ability_warrior_charge.blp:20|t장군 움브리스가 |cFFFF0000$n|r|1을;를; 보면서 |cFFFF0000|Hspell:74670|h[대공세]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t乌比斯将军盯住了|cFFFF0000$n|r，开始施展|cFFFF0000|Hspell:74670|h[迅猛突袭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t昂布里斯將軍的視線停留在|cFFFF0000$n|r身上，並且開始施展|cFFFF0000|Hspell:74670|h[閃擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_charge.blp:20|t¡El General Umbriss fija la mirada |cFFFF0000$n|r y comienza a lanzar |cFFFF0000|Hspell:74670|h[Ataque relámpago]|h|r!' WHERE `ID`=39994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 이야기를 나누러 왔나, $R? 주인님이 이 산에서 쓰러지신 지 얼마나 지났지?', `MaleText_loc4`='$R，你要找我？自从主人去世之后，我已经被遗弃多久了？', `MaleText_loc5`='$R。你是被派來與我對話的嗎?這個地方已經多久不曾受過主人的恩惠了?', `MaleText_loc7`='$R. ¿Te han enviado para que hables conmigo? ¿Cuánto tiempo ha pasado desde la muerte del maestro en estas mismas laderas?' WHERE `ID`=39995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 인내심을 가지십시오. 한 번 더 시도할 수 있게 제가 도와 드리겠습니다.', `MaleText_loc4`='耐心点儿，朋友。让我帮你准备下一次尝试。', `MaleText_loc5`='耐心點，朋友。讓我參與另一次攻擊的準備行動。', `MaleText_loc7`='Paciencia, camarada. Permíteme que te ayude a preparar un nuevo intento.' WHERE `ID`=39996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 이 수정구를 준 자가 누구지, 오우거?', `MaleText_loc4`='你的部族从哪儿得到这些宝珠的，食人魔？', `MaleText_loc5`='巨魔，把寶珠給你們氏族的人是誰?', `MaleText_loc7`='Ogro, ¿quién entregó estos orbes a tu clan?' WHERE `ID`=39997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, $c님.$B$B하이잘은 불타오르고 제가 평생을 바쳐 지켜온 세상은 흔적도 없이 사라질 위기에 처해 있어요.$B$B대답해 주세요. 타이러스 블랙혼이라는 이름을 들어본 적이 있나요?', `FemaleText_loc4`='欢迎你，$c。$B$B海加尔燃起了熊熊烈火，我耗尽毕生心血保护的世界已在毁灭的边缘。$B$B告诉我——你可曾听说过泰拉斯·黑角这个名字？', `FemaleText_loc5`='歡迎，$c。$B$B海加爾正在燃燒，我一生都在保護的世界也面臨著毀壞。$B$B你有聽過泰洛斯·黑角這個名字嗎?', `FemaleText_loc7`='Te doy la bienvenida, $c.$B$BHyjal arde y el mundo que he protegido toda mi vida está al borde del olvido.$B$BDime, ¿has oído hablar de Tyrus Cuerno Negro?' WHERE `ID`=39998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구역질 나는 생물아. 영광스러운 엘드레탈라스에 너희 추잡한 것들을 퍼뜨리더니 이젠 감히 내게 반항하는 것이냐? 말해라!', `MaleText_loc4`='你这恶心的怪物。你玷污了神圣的埃雷萨拉斯，现在又胆敢冒犯我？快说！', `MaleText_loc5`='你這噁心的生物。你污染了美麗的埃德薩拉斯，現在還敢忤逆我?說話!', `MaleText_loc7`='Criatura repugnante. Has extendido tu inmundicia por la gloriosa Eldre''thalas ¿y ahora OSAS desafiarme? ¡HABLA!' WHERE `ID`=39999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이라... 흥미롭군. 그들이 너희 "혈투의 전장" 내에 있는가?', `MaleText_loc4`='暮光之锤……有趣。他们在你们的“厄运之槌”里？', `MaleText_loc5`='暮光之錘...太有趣了。他們在你們的「厄運之槌」裡?', `MaleText_loc7`='Los del Martillo Crepuscular... fascinante. ¿Están dentro de esa "La Masacre"?' WHERE `ID`=40000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 더는 살 수 없을 거다, 오우거. 어딘가 안전한 곳에 도달하도록 기도하는 게 좋을 것이다.', `MaleText_loc4`='那里不再是你的家了，食人魔。另找个安全的地方安家吧——那地方已经不再适合你。', `MaleText_loc5`='你不用在待在那裡了，巨魔。保佑你能找到安全的地方，這是你應得的。', `MaleText_loc7`='Ya no vivirás allí, ogro. Reza para que acabes en un lugar seguro, porque es más de lo que te mereces.' WHERE `ID`=40001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수년에 걸쳐 연구한 끝에 여기까지 왔소.$b$b돌아가고 싶지는 않소...', `MaleText_loc4`='多年的研究把我带到了这里。$b$b我现在还不想回头……', `MaleText_loc5`='我多年的研究引導我到此地。$b$b還沒到我回頭的時候...', `MaleText_loc7`='Son años de investigación los que me han guiado hasta aquí.$b$bNo voy a darme la vuelta ahora...' WHERE `ID`=40002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추... 춥다...', `MaleText_loc4`='真……真冷……', `MaleText_loc5`='冷冷冷冷...', `MaleText_loc7`='F-f-frío...' WHERE `ID`=40003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타이러스 블랙혼이 누굽니까?', `MaleText_loc4`='泰拉斯·黑角是谁？', `MaleText_loc5`='誰是泰洛斯·黑角?', `MaleText_loc7`='¿Quién es Tyrus Cuerno Negro?', `FemaleText_loc1`='타이러스 블랙혼이 누군가요?', `FemaleText_loc4`='泰拉斯·黑角是谁？', `FemaleText_loc5`='誰是泰洛斯·黑角?', `FemaleText_loc7`='¿Quién es Tyrus Cuerno Negro?' WHERE `ID`=40004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초... 초... 초갈이... 그 수정구를... 우리에게 줬다... 황혼의 망치단이 우릴 강하게... 해 준다...', `MaleText_loc4`='古……古加尔给我们……魔球……暮光之锤部族让我们强大……', `MaleText_loc5`='是丘...丘...丘加利把寶珠...把寶珠給我們的...暮光之錘給我們力量...', `MaleText_loc7`='Ch-ch-Cho''gall dar a nosotros... orbes... Clan del Martillo Crepuscular hacer a nosotros fuertes...' WHERE `ID`=40005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다! 혈투의 전장! 가게 해 줘... 너무 춥다...', `MaleText_loc4`='对！厄运之槌！快放开……好冷……', `MaleText_loc5`='對!厄運之槌!快放開...好冷...', `MaleText_loc7`='¡Sí! ¡La Masacre! Dejar ir... tanto frío...' WHERE `ID`=40006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='10년 전, 이곳 하이잘 산 정상에서 엄청난 전투가 벌어졌어요. 파멸자 아키몬드는 악마들을 이끌고 세계수로 진격하여 세계수의 힘을 자신의 것으로 만들려 했죠.$B$B아키몬드가 패배하면서 군단의 아제로스 침략도 막을 내렸지만... 아키몬드의 타락한 추종자들은 여전히 많이 남았어요.', `FemaleText_loc4`='十年前，在海加尔山的顶峰爆发了一场旷世之战。污染者阿克蒙德指挥恶魔大军攻占了世界之树，并将其力量据为己有。$B$B他的战败标志着燃烧军团入侵艾泽拉斯计划的终结……但他许多堕落的支持者却仍没有离开。', `FemaleText_loc5`='十年前，在這海加爾山的山頂上發生了一場大戰。『污染者』阿克蒙德帶領了大群的惡魔進軍世界之樹，想將它的力量佔為己有。$B$B他的失敗象徵著燃燒軍團對艾澤拉斯入侵的終結...但許多支持他的墮落者活了下來。', `FemaleText_loc7`='Hace una década tuvo lugar una gran batalla en la cima del Monte Hyjal. Archimonde el Rapiñador era el líder de un ejército de demonios que marchó hacia el Árbol del Mundo para hacerse con su poder.$B$BSu derrota significó el fin de la invasión de Azeroth por parte de la Legión... Aunque muchos de sus corruptos seguidores quedaron atrás.' WHERE `ID`=40007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙혼은 악마입니까?', `MaleText_loc4`='黑角是魔鬼？', `MaleText_loc5`='黑角是個惡魔?', `MaleText_loc7`='¿Cuerno Negro es un demonio?', `FemaleText_loc1`='블랙혼은 악마인가요?', `FemaleText_loc4`='黑角是魔鬼？', `FemaleText_loc5`='黑角是個惡魔?', `FemaleText_loc7`='¿Cuerno Negro es un demonio?' WHERE `ID`=40008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇기도 하고 아니기도 해요. 지금은 악마일지도 모르지만, 타이러스 블랙혼은 한때 나이트 엘프였어요. 다른 형제들과 마찬가지로 그도 힘을 주겠다는 악마의 군대의 속삭임에 넘어가 악마로 변했어요.$B$B그의 주인이 패배한 후 타이러스 블랙혼은 사로잡혀 이곳 정상에 갇혔어요. 그가 취한 불멸의 형상은 신성한 힘으로 속박했고요.$B$B그렇지만 그의 내면에는 영혼의 불꽃이 아직 미약하나마 타오르고 있을지도 몰라요... 진실을 확인하려면 그와 이야기를 나누어야 해요.', `FemaleText_loc4`='既是又不是。他现在也许是个恶魔，可泰拉斯·黑角曾经是个暗夜精灵。就像他用恶魔军团许给他的权利去劝诱和转变的那些同胞一样。$B$B在主人战败后，他被俘获并关在这顶峰上，神圣能量缚住了他不朽的人形。$B$B可也许在他心中仍有最晦暗的灵魂火光在燃烧……我们至少要设法弄个明白。', `FemaleText_loc5`='是也非也。他現在雖然是個惡魔，但泰洛斯·黑角曾經是個夜精靈。像他許多的兄弟一樣，他無法抗拒惡魔在他頭裡的聲音，接受了獲得更強大力量的誘惑而變成了惡魔。$B$B他的主人被擊拜後他就被抓了起來，囚禁於這個頂峰上，他的肉身被神聖的能量所捆綁著。$B$B但或許他的內心仍存有一丁點的靈魂...我們至少必須確定這點。', `FemaleText_loc7`='Sí y no. Quizá sea un demonio ahora, pero en otra época Tyrus Cuerno Negro fue un elfo de la noche. Como otros muchos de sus hermanos, fue atraído y transformado por las promesas de poder que el ejército demoníaco susurró en sus oídos.$B$BTras la derrota de su señor, fue capturado y encarcelado aquí, en la cima, donde su forma inmortal es prisionera de energías sagradas.$B$BPero quizá todavía arda un leve rastro de alma en su interior... Debemos ir a comprobarlo.' WHERE `ID`=40009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 블랙혼. 도움을 요청하려고 왔습니다. 그럴 생각이 있으시다면요.', `MaleText_loc4`='是的，黑角。我奉命前来请求你的帮助——如果你愿意伸出援手。', `MaleText_loc5`='是的，黑角。我被派來請求你的幫助，如果你願意的話。', `MaleText_loc7`='Sí, Cuerno Negro. Me han enviado para pedirte ayuda, si estás dispuesto a darla.', `FemaleText_loc1`='그렇습니다, 블랙혼. 도움을 요청하려고 왔어요. 그럴 생각이 있으시다면요.', `FemaleText_loc4`='是的，黑角。我奉命前来请求你的帮助——如果你愿意伸出援手。', `FemaleText_loc5`='是的，黑角。我被派來請求你的支援，如果你願意的話。', `FemaleText_loc7`='Sí, Cuerno Negro. Me han enviado para pedirte ayuda, si estás dispuesto a darla.' WHERE `ID`=40010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도움이라? 정말 다급했긴 다급했나보군.$B$B<블랙혼의 잔인하고 어두운 눈 깊은 곳에 번뜩이는 불길>$B$B내가 네놈들의 세계를 태우지 말아야 할 이유를 대 봐라.', `MaleText_loc4`='我的帮助？事态已经恶化到如此地步了吗？$B$B<黑角残忍的黑色瞳仁里闪着许久未见的光焰。>$B$B告诉我，我为什么不该让你的世界自生自灭？', `MaleText_loc5`='我的幫助?事情真的變得那麼糟了嗎?$B$B<黑角殘忍、烏黑的眼睛深處閃爍著火苗。>$B$B給我個不讓你們世界燃燒的理由。', `MaleText_loc7`='¿Mi ayuda? ¿Las cosas se han puesto tan difíciles?$B$B<Una llama lejana arde en los ojos oscuros y crueles de Cuerno Negro>.$B$BDime por qué no debería dejar que ardiera el mundo.' WHERE `ID`=40011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 혹시 기절하는 병사들이 나올까 봐 여기 있는 거예요. 신병들은 마음이 너무 앞선 나머지 무리하는 경향이 있거든요.

...아, 그리고 가끔 신형 기계보행전차가 폭발하기도 하고 말이죠. 아, 이놈의 주둥이!', `MaleText_loc4`='我在这里是为了防备有人晕倒。新兵们有时会因为过度兴奋而导致体力透支。

……嗯，有时候那种新型步行坦克也会爆炸。轰！', `MaleText_loc5`='我會在這，只是怕萬一有人昏迷倒下。這些新人有些亢奮，有時候這會讓他們做出超出自身體能負荷的舉動。

...再說，有時候這些全新打造的機械坦克原型會忽然爆炸。喔糟糕我說出來了!', `MaleText_loc7`='Yo estoy aquí por si alguien se desmaya. Los nuevos reclutas se emocionan y a veces se esfuerzan demasiado.

...Bueno, eso y que a veces explota uno de los nuevos prototipos de mecanotanque. ¡Vaya!', `FemaleText_loc1`='전 혹시 기절하는 병사들이 나올까 봐 여기 있는 거예요. 신병들은 마음이 너무 앞선 나머지 무리하는 경향이 있거든요.

...아, 그리고 가끔 신형 기계보행전차가 폭발하기도 하고 말이죠. 아, 이놈의 주둥이!', `FemaleText_loc4`='我在这里是为了防备有人晕倒。新兵们有时会因为过度兴奋而导致体力透支。

……嗯，有时候那种新型步行坦克也会爆炸。轰！', `FemaleText_loc5`='我會在這，只是怕萬一有人昏迷倒下。這些新人有些亢奮，有時候這會讓他們做出超出自身體能負荷的舉動。

...再說，有時候這些全新打造的機械坦克原型會忽然爆炸。喔糟糕我說出來了!', `FemaleText_loc7`='Yo estoy aquí por si alguien se desmaya. Los nuevos reclutas se emocionan y a veces se esfuerzan demasiado.

...Bueno, eso y que a veces explota uno de los nuevos prototipos de mecanotanque. ¡Vaya!' WHERE `ID`=40012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 한때는 필멸의 존재였습니다, 블랙혼. 우리와 마찬가지로요.', `MaleText_loc4`='因为你曾是个凡人，黑角。和我们一样。', `MaleText_loc5`='你曾是個凡人，黑角。我們的一員。', `MaleText_loc7`='Una vez fuiste mortal, Cuerno Negro. Uno de nosotros.', `FemaleText_loc1`='당신도 한때는 필멸의 존재였어요, 블랙혼. 우리와 마찬가지로요.', `FemaleText_loc4`='因为你曾是个凡人，黑角。和我们一样。', `FemaleText_loc5`='你曾是個凡人，黑角。我們的一員。', `FemaleText_loc7`='Una vez fuiste mortal, Cuerno Negro. Uno de nosotros.' WHERE `ID`=40013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재? 그래, 나도 한때는 약하디 약한 필멸의 존재였지.$B$B내 결박이 보이나? 필멸의 굴레에 묶여 사는 것에 비하면 이건 약과야.$B$B주인님의 선물은 지금까지도 내 안에 용솟음치고 있으며, 언제든 뿜어낼 준비가 되어 있다.$B$B$c|1아;야;, 내가 필멸의 존재로 살았던 때는 지났다. 만약 내 안에 옛 삶의 불꽃이 살아 있다면 기꺼이 없애버리리라. 그런 말로는 나를 설득할 수 없다, $r.', `MaleText_loc4`='凡人？不错，我曾是个凡人。弱小的凡人。$B$B你看到我现在所受的束缚了吗？但与身为凡人的桎梏相比，这些根本算不了什么。$B$B甚至现在，我主人的馈赠都在我体内激涌，随时准备释放。$B$B不，$c，凡人的身份已经离我远去，假如我体内还有丝毫过往生命的残焰在燃烧，我也希望它尽快熄灭。你最好去想其它办法，$r。', `MaleText_loc5`='凡人?是的，我曾經是個弱小的凡人。$B$B你看到現在這些禁錮了嗎?這些與被關在一個血肉之身比起來根本不算什麼。$B$B就連現在，主人賜予我的力量都還在我體內流動，隨時準備爆發。$B$B不，$c，我身為凡人的日子已是過去式，如果我心中真的還有過去那個我的靈魂之火存在，我希望它熄滅。你不用浪費力氣了，$r。', `MaleText_loc7`='¿Mortal? Sí, una vez fui mortal. Débil.$B$B¿Ves estas ataduras? Esto no es nada en comparación con ser confinado dentro de una forma mortal.$B$BIncluso ahora los dones de mi amo se agitan en mi interior, listos para ser liberados.$B$BNo, $c, mis días de mortal han pasado ya, y si todavía hay una chispa de mi antigua vida en mi interior, ojalá pudiera extinguirla. Tendrás que esforzarte un poco más, $r.' WHERE `ID`=40014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 이 산을 정복하면 당신도 역시 파괴될 것입니다!', `MaleText_loc4`='要是暮光之锤毁了这座山，你也会被一并毁灭掉！', `MaleText_loc5`='如果暮光之錘夷平這座山你也難逃一死!', `MaleText_loc7`='¡Si el Martillo Crepuscular derriba esta montaña, serás destruido!', `FemaleText_loc1`='황혼의 망치단이 이 산을 정복하면 당신도 역시 파괴될 거예요!', `FemaleText_loc4`='要是暮光之锤毁了这座山，你也会被一并毁灭掉！', `FemaleText_loc5`='如果暮光之錘夷平這座山你也難逃一死!', `FemaleText_loc7`='¡Si el Martillo Crepuscular derriba esta montaña, serás destruido!' WHERE `ID`=40015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴? 그래, 그럴 수도 있겠어. 밤이 되면 나는 이 세상이 안에서부터 산산조각 찢어지는 환영을 본다. 슬픔이나 분노 따위는 없다. 단지... 좀 궁금할 뿐.$B$B나는 주인님을 섬기는 대가로 힘을 얻었다. 그런데 너희가 상대하는 자들은... 망각을 얻으려고 싸운단 말이야. 참 특이해.', `MaleText_loc4`='被摧毁了？好吧，这也有可能。深夜里，我常常会受到同一个噩梦的困扰——这个世界从内部被撕成了碎片。但我并不觉得哀伤，也没有愤怒。只是……好奇。$B$B$c，我侍奉我的主人，从而换取力量。但你与之战斗的这些家伙……他们想要的只有灭亡。这真是一个奇怪的动机。', `MaleText_loc5`='被夷平?是的，是有可能。我常做惡夢，夢到這個世界由裡到外被撕裂。我感覺不到任何的悲傷或是憤怒。只有...好奇。$B$B我以力量為條件臣服於我的主人，$c。但那些你戰鬥的...他們卻為了毀滅而戰。真是奇怪的動機。', `MaleText_loc7`='¿Destruido? Sí, eso es posible. Por las noches me asaltan visiones en las que este mundo es desgarrado desde el interior. No siento pena ni rabia. Simplemente... curiosidad.$B$BServí a mi señor a cambio de poder, $c. Pero aquellos contra los que luchas... solo buscan la muerte. Es una motivación muy extraña.' WHERE `ID`=40016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마토클로는 아직도 당신이 구원받을 수 있다고 믿습니다. 이 기회를 통해 악마와 손잡은 일을 속죄하십시오.', `MaleText_loc4`='麦托克劳相信，你仍值得被宽恕。这是你的机会，为投靠恶魔的行为赎罪。', `MaleText_loc5`='瑪托克勞相信你還有改邪歸正的機會。這是你為你與惡魔結盟的贖罪機會。', `MaleText_loc7`='Matogarra cree que todavía es posible tu redención. Esta es tu oportunidad de expiar que te pusieras del lado de los demonios.', `FemaleText_loc1`='마토클로는 아직도 당신이 구원받을 수 있다고 믿어요. 이 기회를 통해 악마와 손잡은 일을 속죄하세요.', `FemaleText_loc4`='麦托克劳相信，你仍值得被宽恕。这是你的机会，为投靠恶魔的行为赎罪。', `FemaleText_loc5`='瑪托克勞相信你還有改邪歸正的機會。這是你為你與惡魔結盟的贖罪機會。', `FemaleText_loc7`='Matogarra cree que todavía es posible tu redención. Esta es tu oportunidad de expiar que te pusieras del lado de los demonios.' WHERE `ID`=40017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<블랙혼이 결박에서 벗어나려 힘을 씁니다. 처음으로 뚜렷한 분노를 드러냅니다.>$B$B구원이라! 마치 불타는 군단으로부터 도망칠 수 있을 것처럼 말하는구나. 아주 건방져! 마치 10년 전의 노력으로, 그리고 아웃랜드에서의 승리로 군단의 침공을 눈곱만큼이라도 늦춘 것처럼 말하는데! 군단은 돌아온다, $r. 돌아오고말고. 그리고 나는 이곳에서 그들을 반갑게 맞이할 것이다.', `MaleText_loc4`='<黑角挣扎了一下。他第一次显露出烦乱的神情。>$B$B算了吧！难道你真能逃出燃烧军团的魔爪吗？不要自鸣得意了！难道你们十年前的所为和在外域的所作所为曾经减慢过燃烧军团的步伐吗？他们一定会回来的，$r。他们会回来。我则会在这里迎接他们。', `MaleText_loc5`='<黑角用力地扯著他的禁錮，第一次露出受挫的表情。>$B$B救贖!你認為你們可以從燃燒軍團的手裡跑掉嗎，實在是太天真了!雖然你們十年前和在外域所做的努力稍微延緩了軍團的腳步，但他們會回來的，$r!當他們回來的時候，我會在這歡迎他們。', `MaleText_loc7`='<Cuerno Negro tira de sus ataduras, por primera vez visiblemente afectado.>$b$b¡Redención! ¡Actúas como si hubiera alguna posibilidad de escapar de la Legión Ardiente! ¡Eres tan engreído! Como si tus esfuerzos de hace una década o en Terrallende hubieran retrasado a la Legión un solo ápice! Vendrán $r. Regresarán. Y yo estaré aquí para darles la bienvenida.' WHERE `ID`=40018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 주인은 지금 어디 있습니까, 블랙혼? 빛의 품으로 돌아서는 건 아직도 늦지 않았습니다...', `MaleText_loc4`='你的主人现在在哪儿，黑角？现在弃暗投明还不算太晚……', `MaleText_loc5`='你的主人現在在哪，黑角?現在回歸於聖光還不算太晚...', `MaleText_loc7`='¿Ahora dónde está tu maestro, Cuerno Negro? No es demasiado tarde para caminar hacia la luz...', `FemaleText_loc1`='당신의 주인은 지금 어디 있나요, 블랙혼? 빛의 품으로 돌아서는 건 아직도 늦지 않았어요...', `FemaleText_loc4`='你的主人现在在哪儿，黑角？现在弃暗投明还不算太晚……', `FemaleText_loc5`='你的主人現在在哪，黑角?現在回歸於聖光還不算太晚...', `FemaleText_loc7`='¿Ahora dónde está tu maestro, Cuerno Negro? No es demasiado tarde para caminar hacia la luz...' WHERE `ID`=40019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 도와 저들을 물리쳐 주시겠습니까?', `MaleText_loc4`='你愿意帮我们击败他们吗？', `MaleText_loc5`='你會幫助我們擊敗他們嗎?', `MaleText_loc7`='¿Nos ayudarás a derrotarlos?', `FemaleText_loc1`='우리를 도와 저들을 물리쳐 주시겠어요?', `FemaleText_loc4`='你愿意帮我们击败他们吗？', `FemaleText_loc5`='你會幫助我們擊敗他們嗎?', `FemaleText_loc7`='¿Nos ayudarás a derrotarlos?' WHERE `ID`=40020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 당신네들이 정복할 세계가 남아 있을 때나 가능한 얘기입니다. 황혼의 망치단은 모든 것을 파괴하려고 합니다.', `MaleText_loc4`='如果真的有一个世界等待着你的军团去征服，暮光之锤也会把那里的一切都摧毁。', `MaleText_loc5`='如果有這麼個世界，你的軍團想要統治它，但暮光之錘卻是想要摧毀一切。', `MaleText_loc7`='Eso en el caso de que quede un mundo que tu legión pueda invadir. El Martillo Crepuscular quiere destruirlo todo.', `FemaleText_loc1`='그건 당신네들이 정복할 세계가 남아 있을 때나 가능한 얘기예요. 황혼의 망치단은 모든 것을 파괴하려고 한다고요.', `FemaleText_loc4`='如果真的有一个世界等待着你的军团去征服，暮光之锤也会把那里的一切都摧毁。', `FemaleText_loc5`='如果有這麼個世界，你的軍團想要統治它，但暮光之錘卻是想要摧毀一切。', `FemaleText_loc7`='Eso en el caso de que quede un mundo que tu legión pueda invadir. El Martillo Crepuscular quiere destruirlo todo.' WHERE `ID`=40021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 날카로운 울음소리를 냅니다!', `MaleText_loc4`='%s发出一声尖叫！', `MaleText_loc5`='%s發出了尖嘯的吶喊!', `MaleText_loc7`='¡%s emite un chillido agudo!' WHERE `ID`=40022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<쿨럭>$b$b난... 죽은 걸까?', `MaleText_loc4`='<咳嗽。>$b$b我……死了吗？', `MaleText_loc5`='<咳嗽。>$b$b我...死了嗎?', `MaleText_loc7`='<Tose.>$b$b¿He... muerto?' WHERE `ID`=40023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에겐 재능이 있다, $n. 하지만 그놈의 자비가 널 약하게 만들고 있지.', `MaleText_loc4`='你很有天赋，$n。但仁慈使你懦弱。', `MaleText_loc5`='你具有天賦，$n。但憐憫之心使你變的軟弱。', `MaleText_loc7`='Tienes talento, $n. Pero la piedad te vuelve débil.' WHERE `ID`=40024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까?', `MaleText_loc4`='你是谁，朋友？', `MaleText_loc5`='朋友，你是哪位?', `MaleText_loc7`='¿Quién eres, amigo?', `FemaleText_loc1`='당신은 누구신지요?', `FemaleText_loc4`='你是谁，朋友？', `FemaleText_loc5`='朋友，你是哪位?', `FemaleText_loc7`='¿Quién eres, amigo?' WHERE `ID`=40025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구요? 여긴 어디고?', `MaleText_loc4`='你是谁？这里是哪儿？', `MaleText_loc5`='你是誰?這是哪裡?', `MaleText_loc7`='¿Quién eres? ¿Qué es este sitio?' WHERE `ID`=40026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 인생은 빼앗겼습니다. 만약 제 생의 마지막 시간에 무언가 할 수 있다면, 물어보실 필요도 없습니다. 저와 더불어 당신 뜻대로 하십시오...', `MaleText_loc4`='我的生命已逝。要是在我生命的最后时刻还能效力的话，我将再所不辞。听凭你的安排……', `MaleText_loc5`='我的生命已被拋棄。如果在我生命最後的時間還能有所用處，便不需要浪費力氣問我。跟我說我能做什麼....', `MaleText_loc7`='Mi vida está acabada. Si en mi hora final puedo prestar algún servicio, no te molestes en preguntar. Haz conmigo lo que quieras...' WHERE `ID`=40027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 병사여, 자네의 고결한 희생은 절대 잊히지 않도록 하겠네.', `MaleText_loc4`='勇敢的士兵，你高贵的牺牲绝不会被忘记。', `MaleText_loc5`='勇敢的士兵，我會確保你的光榮犧牲不會被後人所忘。', `MaleText_loc7`='Valiente soldado, me aseguraré de que tu noble sacrificio no caiga en el olvido.' WHERE `ID`=40028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...주인님?', `MaleText_loc4`='……主人？', `MaleText_loc5`='...主人?', `MaleText_loc7`='¿... Maestro?' WHERE `ID`=40029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 일이 끝나면, 너희는 이 장치를 스톰윈드 곳곳에 설치할 것이다.', `MaleText_loc4`='当它们完成的时候，你就要将这些装置隐藏在暴风城各处。', `MaleText_loc5`='等他們做好之後，你要將這些裝置藏在暴風城的各個角落。', `MaleText_loc7`='Cuando estén completados, esconderán esos artefactos por todo Ventormenta.' WHERE `ID`=40030;
