UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역은 대격변의 진원지였습니다.$b$b나가가 여기서 활동하고 있는 건 우연의 일치가 아니란 말입니다. 그들의 목적을 밝혀내야 합니다!', `MaleText_loc4`='这里是灾变的中心。$b$b纳迦在这里的活动一定不是巧合。我们必须揭穿他们的意图！', `MaleText_loc5`='這個地區是大災變的震央。$b$b納迦出現在此並不令人意外。必須揭開他們的目的!', `MaleText_loc7`='Esta región fue un epicentro del Cataclismo.$b$bLa actividad naga local no es ninguna casualidad. ¡Debemos descubrir sus intenciones!' WHERE `ID`=40032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하께서 궁중 어릿광대를 새로 뽑으셨나 봅니다.', `MaleText_loc4`='看来国王又有了一个新的宫廷小丑！', `MaleText_loc5`='看來，國王幫他自己找到了一名新的宮廷小丑!', `MaleText_loc7`='Parece que el rey se ha buscado un nuevo bufón de la corte.', `FemaleText_loc1`='국왕 폐하께서 궁중 어릿광대를 새로 뽑으셨나 봅니다.', `FemaleText_loc4`='看来国王又有了一个新的宫廷小丑！', `FemaleText_loc5`='看來，國王幫他自己找到了一名新的宮廷小丑!', `FemaleText_loc7`='Parece que el rey se ha buscado un nuevo bufón de la corte.' WHERE `ID`=40033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 공연을 공짜로 보는 기회가 흔한 게 아닙니다.', `MaleText_loc4`='平时想看一场这样的演出可是要付钱的。', `MaleText_loc5`='一般來說你得付錢才能觀賞這樣一場表演。', `MaleText_loc7`='Lo normal es que tengas que pagar por ver un espectáculo como este.', `FemaleText_loc1`='이런 공연을 공짜로 보는 기회가 흔한 게 아니에요.', `FemaleText_loc4`='平时想看一场这样的演出可是要付钱的。', `FemaleText_loc5`='一般來說你得付錢才能觀賞這樣一場表演。', `FemaleText_loc7`='Lo normal es que tengas que pagar por ver un espectáculo como este.' WHERE `ID`=40034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 사람이 말도 없이 사라졌어요. 도대체 어떻게 하죠?', `MaleText_loc4`='他失踪了，我完全不知道该怎么办！', `MaleText_loc5`='他失蹤了!我不知道該怎麼辦才好!', `MaleText_loc7`='¡Ha desaparecido y no sé qué hacer!', `FemaleText_loc1`='그이가 말도 없이 사라졌어요. 도대체 어떻게 하죠?', `FemaleText_loc4`='他失踪了，我完全不知道该怎么办！', `FemaleText_loc5`='他失蹤了!我不知道該怎麼辦才好!', `FemaleText_loc7`='¡Ha desaparecido y no sé qué hacer!' WHERE `ID`=40035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 좀 도와주세요! 시장 간다고 나간 그 사람한테서 아직까지 아무 소식이 없어요!', `MaleText_loc4`='一定要帮帮我！他去了市场，就再没有回来！', `MaleText_loc5`='你得要幫幫忙啊!他去了趟市場，然後再也沒回來過!', `MaleText_loc7`='¡Tienes que ayudarme! ¡Se marchó al mercado y no ha regresado!', `FemaleText_loc1`='절 좀 도와주세요! 시장 간다고 나간 그이한테서 아직까지 아무 소식이 없어요!', `FemaleText_loc4`='一定要帮帮我！他去了市场，就再没有回来！', `FemaleText_loc5`='你得要幫幫忙啊!他去了趟市場，然後再也沒回來過!', `FemaleText_loc7`='¡Tienes que ayudarme! ¡Se marchó al mercado y no ha regresado!' WHERE `ID`=40036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 우릴 도와줄 수 있는 사람이 있을 거야!', `MaleText_loc4`='一定有人能帮我！', `MaleText_loc5`='一定有誰能幫幫我的!', `MaleText_loc7`='¡Tiene que haber alguien que pueda ayudarme!', `FemaleText_loc1`='분명히 우릴 도와줄 수 있는 사람이 있을 거야!', `FemaleText_loc4`='一定有人能帮我！', `FemaleText_loc5`='一定有誰能幫幫我的!', `FemaleText_loc7`='¡Tiene que haber alguien que pueda ayudarme!' WHERE `ID`=40037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 갑자기 사라질 순 없어요! 그럴 사람이 아니라고요.', `MaleText_loc4`='他不会就这样无缘无故地消失！他不是这样的人。', `MaleText_loc5`='他從來沒像這樣消失過!這一點也不像他的作風。', `MaleText_loc7`='¡Ella nunca desaparecería así, sin decir nada! ¡No es propio de ella!', `FemaleText_loc1`='이렇게 갑자기 사라질 순 없어요! 그럴 사람이 아니라고요.', `FemaleText_loc4`='他不会就这样无缘无故地消失！他不是这样的人。', `FemaleText_loc5`='他從來沒像這樣消失過!這一點也不像他的作風。', `FemaleText_loc7`='¡Él nunca desaparecería así, sin decir nada! ¡No es propio de él!' WHERE `ID`=40038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남편이 말도 없이 사라졌어요. 저를 도와주세요, 대장님. 전 아무 힘이 없어요.', `MaleText_loc4`='我的丈夫失踪了。将军，请一定帮帮我。我不是战士。', `MaleText_loc5`='我的丈夫失蹤了。隊長，你得幫我找到他啊。我不是戰士啊。', `MaleText_loc7`='Mi mujer ha desaparecido. Tienes que ayudarme, capitán. No soy un guerrero.', `FemaleText_loc1`='남편이 말도 없이 사라졌어요. 저를 도와주세요, 대장님. 전 아무 힘이 없어요.', `FemaleText_loc4`='我的丈夫失踪了。将军，请一定帮帮我。我不是战士。', `FemaleText_loc5`='我的丈夫失蹤了。隊長，你得幫我找到他啊。我不是戰士啊。', `FemaleText_loc7`='Mi marido ha desaparecido. Tienes que ayudarme, capitán. No soy una guerrera.' WHERE `ID`=40039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님은 이성적인 분이시죠? 만약 가족 중 한 사람이 실종되면 어떻게 하시겠어요?', `MaleText_loc4`='长官，你是个通情达理的人。如果你的家人失踪了，你会怎样做？', `MaleText_loc5`='隊長，你看起來像是個明理的人。如果你的家人失蹤了，你會怎麼做?', `MaleText_loc7`='Pareces un hombre razonable, capitán. ¿Qué harías si desapareciera alguien de tu familia?', `FemaleText_loc1`='대장님은 이성적인 분이시죠? 만약 가족 중 한 사람이 실종되면 어떻게 하시겠어요?', `FemaleText_loc4`='长官，你是个通情达理的人。如果你的家人失踪了，你会怎样做？', `FemaleText_loc5`='隊長，你看起來像是個明理的人。如果你的家人失蹤了，你會怎麼做?', `FemaleText_loc7`='Pareces un hombre razonable, capitán. ¿Qué harías si desapareciera alguien de tu familia?' WHERE `ID`=40040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 사람이 납치라도 된 걸까요? 다시 볼 수 있을까요?', `MaleText_loc4`='你认为他被绑架了？我还能再见到他么？', `MaleText_loc5`='你覺得他是不是被綁架了呢?我還能不能再見到他?', `MaleText_loc7`='¿Crees que han podido secuestrarla? ¿La volveré a ver alguna vez?', `FemaleText_loc1`='그이가 납치라도 된 걸까요? 다시 볼 수 있을까요?', `FemaleText_loc4`='你认为他被绑架了？我还能再见到他么？', `FemaleText_loc5`='你覺得他是不是被綁架了呢?我還能不能再見到他?', `FemaleText_loc7`='¿Crees que han podido secuestrarlo? ¿Lo volveré a ver alguna vez?' WHERE `ID`=40041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족이 실종된 사람이 한둘이 아닙니다. 저 말고도 많아요, 정말 많아요!', `MaleText_loc4`='失去家人的并非只有我一个。和我有着相同遭遇的人还有很多！', `MaleText_loc5`='我不是唯一失去家人的人。其他人也是，許許多多人都一樣!', `MaleText_loc7`='No soy el único que ha perdido un miembro de su familia. Hay más, ¡muchos más!', `FemaleText_loc1`='가족이 실종된 사람이 한둘이 아닙니다. 저 말고도 많아요, 정말 많아요!', `FemaleText_loc4`='失去家人的并非只有我一个。和我有着相同遭遇的人还有很多！', `FemaleText_loc5`='我不是唯一失去家人的人。其他人也是，許許多多人都一樣!', `FemaleText_loc7`='No soy la única que ha perdido un miembro de su familia. Hay más, ¡muchos más!' WHERE `ID`=40042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족들의 걱정이 이만저만이 아닙니다. 스톰윈드로 돌아가시지요.', `MaleText_loc4`='你的家人很担心你，他们正在等你回暴风城去。', `MaleText_loc5`='你的家人相當擔心，他們希望你回到暴風城裡去。', `MaleText_loc7`='Tu familia está preocupada y quiere que regreses a Ventormenta.', `FemaleText_loc1`='가족들의 걱정이 이만저만이 아닙니다. 스톰윈드로 돌아가시지요.', `FemaleText_loc4`='你的家人很担心你，他们正在等你回暴风城去。', `FemaleText_loc5`='你的家人相當擔心，他們希望你回到暴風城裡去。', `FemaleText_loc7`='Tu familia está preocupada y quiere que regreses a Ventormenta.' WHERE `ID`=40043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 돌아갈 수 없어요. 가족들과 그렇게 심하게 다투고 왔는데 어떻게 그러겠어요. 미안해요, $n. 전 돌아갈 수 없어요.', `FemaleText_loc4`='我不能回去了，我和他们之间发生过可怕的争执。抱歉，$n，我真的不能回去。', `FemaleText_loc5`='我不能回去，在我和他們之間這番激烈的爭執之後我回不去。抱歉，$n，我就是不能回去。', `FemaleText_loc7`='No puedo volver, no después de la terrible pelea que tuve con ellos. Lo siento, $n, pero no puedo.' WHERE `ID`=40044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 돌아가지 않아요. 진실에 눈을 뜬 지금, 제가 있을 곳은 새로운 형제자매들과 함께하는 이곳이에요.', `FemaleText_loc4`='我不能回去了。我已经知道了什么是真实。我的位置是在我新的兄弟姐妹中间。', `FemaleText_loc5`='我不能回去。我得知了真理，我的容身之地就在新的兄弟姊妹這。', `FemaleText_loc7`='No puedo volver. Ahora que conozco la verdad, mi lugar está aquí, con mis hermanos y hermanas.' WHERE `ID`=40045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 점점 높은 곳으로 가고 있습니다, $n. 돌아갈 수는 없지요. 가족들에게는 잘 지내라고 전해 주십시오. 저는 여기 있을 테니, 혹시 생각 있으면 이리 오라는 말도 전해 주시고요.', `MaleText_loc4`='$n，我正在升华的道路上。我已经不能回头了。告诉我的家人，我希望他们一切平安，如果他们决定跟随我，我会在这里等他们。', `MaleText_loc5`='我正邁向升天得道之路，$n。沒有回頭的餘地。告訴我的家人，我希望他們過得安好，如果他們決定要和我在一起，我會在這等著。', `MaleText_loc7`='Estoy en el camino de la ascensión, $n. No hay vuelta atrás. Dile a mi familia que les deseo lo mejor y que estaré aquí esperándoles si al final deciden unirse a mí.' WHERE `ID`=40046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 돌아가야 합니까, $n? 세상의 종말이 다가오고, 전 더 대단한 존재가 될 기회를 잡았는데 말입니다. 가족들이 혹시 저처럼 진실에 눈을 뜬다면, 다시 만날 수도 있겠지요. 하지만 억지로 눈을 뜨게 만드는 게 어디 쉽답니까?', `MaleText_loc4`='$n，为什么我要回去？这个世界即将完结，而我有机会得到升华。如果他们的道路能够将他们引向真实，就像我的道路一样，那么我们终将重逢。如果不是，我也无法让他们睁开眼睛。', `MaleText_loc5`='嘿$n，我幹嘛要回去?這個世界正在滅亡，而我有機會變成更進一步的存在。如果他們跟我選擇的是同樣的真理之道，那麼我們還能再次碰面。如果不是，我也無法讓他們睜開雙眼看清真相。', `MaleText_loc7`='¿Por qué debería regresar, $n? El mundo llega a su fin y tengo la oportunidad de convertirme en algo más. Si sus caminos les llevan a la verdad, como lo hizo el mío, entonces volveremos a encontrarnos. Si no, yo no puedo abrirles los ojos.' WHERE `ID`=40047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 시민들이여, 내 말을 들어 보시오. 우리는 오랫동안 암흑 속에서 살았소. 모두들 제발 나처럼 눈을 뜨시오!', `MaleText_loc4`='听我说，暴风城的市民们。我们已经在黑暗中昏睡了太久。我祈求你们，像我一样睁开眼睛！', `MaleText_loc5`='暴風城的居民們啊，聽我說。我們長久以來活在黑暗之中，我求你們像我一樣睜開雙眼!', `MaleText_loc7`='Escúchenme, ciudadanos de Ventormenta. Llevamos mucho tiempo viviendo en la oscuridad. ¡Les ruego que abran los ojos tal y como he hecho yo!', `FemaleText_loc1`='스톰윈드의 시민들이여, 내 말을 들어 보시오. 우리는 오랫동안 암흑 속에서 살았소. 모두들 제발 나처럼 눈을 뜨시오!', `FemaleText_loc4`='听我说，暴风城的市民们。我们已经在黑暗中昏睡了太久。我祈求你们，像我一样睁开眼睛！', `FemaleText_loc5`='暴風城的居民們啊，聽我說。我們長久以來活在黑暗之中，我求你們像我一樣睜開雙眼!', `FemaleText_loc7`='Escúchenme, ciudadanos de Ventormenta. Llevamos mucho tiempo viviendo en la oscuridad. ¡Les ruego que abran los ojos tal y como he hecho yo!' WHERE `ID`=40048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말이 머지 않았소, 형제자매들이여! 아제로스도 사라질 것이오!', `MaleText_loc4`='兄弟姐妹们，世界末日已经临近！艾泽拉斯将不复存在！', `MaleText_loc5`='我的兄弟姊妹們啊，世界末日即將到來!艾澤拉斯將不復存在!', `MaleText_loc7`='¡Se acerca el fin de nuestro mundo, hermanos y hermanas! ¡Azeroth desaparecerá!', `FemaleText_loc1`='세상의 종말이 머지 않았소, 형제자매들이여! 아제로스도 사라질 것이오!', `FemaleText_loc4`='兄弟姐妹们，世界末日已经临近！艾泽拉斯将不复存在！', `FemaleText_loc5`='我的兄弟姊妹們啊，世界末日即將到來!艾澤拉斯將不復存在!', `FemaleText_loc7`='¡Se acerca el fin de nuestro mundo, hermanos y hermanas! ¡Azeroth desaparecerá!' WHERE `ID`=40049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 세상을 삼킬 것이고, 폭풍이 희망을 모조리 쓸어갈 것이오. 마침내 정령들의 세상이 도래할 거란 말이오!', `MaleText_loc4`='烈焰会吞噬这个世界。风暴会卷走一切希望。元素终将统治一切！', `MaleText_loc5`='火焰將會吞噬這個世界。風暴將會捲走所有希望。最後元素將會統治一切!', `MaleText_loc7`='Las llamas consumirán el mundo. Las tormentas barrerán toda esperanza. ¡Los elementos reinarán al fin!', `FemaleText_loc1`='불길이 세상을 삼킬 것이고, 폭풍이 희망을 모조리 쓸어갈 것이오. 마침내 정령들의 세상이 도래할 거란 말이오!', `FemaleText_loc4`='烈焰会吞噬这个世界。风暴会卷走一切希望。元素终将统治一切！', `FemaleText_loc5`='火焰將會吞噬這個世界。風暴將會捲走所有希望。最後元素將會統治一切!', `FemaleText_loc7`='Las llamas consumirán el mundo. Las tormentas barrerán toda esperanza. ¡Los elementos reinarán al fin!' WHERE `ID`=40050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망할 것 없소! 거짓된 빛에 현혹되지 말고, 내가 제시하는 희망과 진리를 받아들이시오!', `MaleText_loc4`='不要绝望，离开那虚伪的圣光吧，拥抱我给予你们的希望和真实！', `MaleText_loc5`='別灰心喪志!別去管那虛假的光明，來擁抱我賦予你的希望和真理吧!', `MaleText_loc7`='¡No desesperen! Aléjense de la falsa Luz y abrazen la verdad esperanzadora que les ofrezco!', `FemaleText_loc1`='절망할 것 없소! 거짓된 빛에 현혹되지 말고, 내가 제시하는 희망과 진리를 받아들이시오!', `FemaleText_loc4`='不要绝望，离开那虚伪的圣光吧，拥抱我给予你们的希望和真实！', `FemaleText_loc5`='別灰心喪志!別去管那虛假的光明，來擁抱我賦予你的希望和真理吧!', `FemaleText_loc7`='¡No desesperen! Aléjense de la falsa Luz y abrazen la verdad esperanzadora que les ofrezco!' WHERE `ID`=40051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁으로 얼룩진 이 지긋지긋한 삶을 벗어 버리고, 새로운 세상에서 정령으로 다시 태어나 우리의 마땅한 권리를 누리는 것입니다!', `MaleText_loc4`='抛弃你们充满战争和苦役的生活吧，在元素中重生，取得你们在新世界中的位置！', `MaleText_loc5`='拋開充滿戰爭和苦工勞役的生活，在元素之中重獲新生，然後在新世界中取得你應有的正當地位!', `MaleText_loc7`='¡Abandonen sus vidas de guerras y trabajos rutinarios! ¡Renazcan como elementos y reclamen su lugar en el nuevo mundo!', `FemaleText_loc1`='전쟁으로 얼룩진 이 지긋지긋한 삶을 벗어 버리고, 새로운 세상에서 정령으로 다시 태어나 우리의 마땅한 권리를 누리는 것입니다!', `FemaleText_loc4`='抛弃你们充满战争和苦役的生活吧，在元素中重生，取得你们在新世界中的位置！', `FemaleText_loc5`='拋開充滿戰爭和苦工勞役的生活，在元素之中重獲新生，然後在新世界中取得你應有的正當地位!', `FemaleText_loc7`='¡Abandonen sus vidas de guerras y trabajos rutinarios! ¡Renazcan como elementos y reclamen su lugar en el nuevo mundo!' WHERE `ID`=40052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정들 하시오, 친구여. 질문에 대답할 시간은 충분하오.', `MaleText_loc4`='冷静，朋友们。时间很充分，你们的问题都能得到回答。', `MaleText_loc5`='冷靜點，朋友。有很多時間可以慢慢回答你的問題。', `MaleText_loc7`='Tranquilos, amigos míos. Habrá mucho tiempo para responder a todas sus preguntas.', `FemaleText_loc1`='진정들 하시오, 친구여. 질문에 대답할 시간은 충분하오.', `FemaleText_loc4`='冷静，朋友们。时间很充分，你们的问题都能得到回答。', `FemaleText_loc5`='冷靜點，朋友。有很多時間可以慢慢回答你的問題。', `FemaleText_loc7`='Tranquilos, amigos míos. Habrá mucho tiempo para responder a todas sus preguntas.' WHERE `ID`=40053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 이야기에 관심이 있으시오? 앞으로 집회를 열 예정이요. 더 알고 싶은 자들은 나와 대화를 나눕시다. 하지만 조심하시오. 스톰윈드는 진실을 감추려는 자들로 가득하니.', `MaleText_loc4`='如果你对我们的信息感兴趣，那么我告诉你，我正在聚集信徒。如果你想要了解更多，就继续和我谈谈。但请小心，暴风城中有无数妄图扼杀真相的人。', `MaleText_loc5`='假如你對我們傳佈的訊息有興趣，我將會舉辦一次集會。如果你想多了解一些，來和我聊聊，不過要注意，暴風城裡到處都是想要消滅真理之音的人。', `MaleText_loc7`='Si estáis interesados en nuestro mensaje, voy a celebrar una reunión. Hablad conmigo si deseáis saber más, pero tened cuidado porque mucha gente en Ventormenta desearía silenciar la verdad.', `FemaleText_loc1`='우리의 이야기에 관심이 있으시오? 앞으로 집회를 열 예정이요. 더 알고 싶은 자들은 나와 대화를 나눕시다. 하지만 조심하시오. 스톰윈드는 진실을 감추려는 자들로 가득하니.', `FemaleText_loc4`='如果你对我们的信息感兴趣，那么我告诉你，我正在聚集信徒。如果你想要了解更多，就继续和我谈谈。但请小心，暴风城中有无数妄图扼杀真相的人。', `FemaleText_loc5`='假如你對我們傳佈的訊息有興趣，我將會舉辦一次集會。如果你想多了解一些，來和我聊聊，不過要注意，暴風城裡到處都是想要消滅真理之音的人。', `FemaleText_loc7`='Si estáis interesados en nuestro mensaje, voy a celebrar una reunión. Hablad conmigo si deseáis saber más, pero tened cuidado porque mucha gente en Ventormenta desearía silenciar la verdad.' WHERE `ID`=40054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 필멸의 존재 같으니. 육체는 불타리라.', `MaleText_loc4`='愚蠢的凡人。燃烧吧。', `MaleText_loc5`='愚蠢的凡人。血肉之軀是脆弱的。', `MaleText_loc7`='Mortal imprudente. La carne arde.' WHERE `ID`=40055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 떠나라!', `MaleText_loc4`='离开这儿！', `MaleText_loc5`='離開這個地方!', `MaleText_loc7`='¡ABANDONA ESTE LUGAR!' WHERE `ID`=40056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='센시리아, 당신을 사랑하지만 난 이곳을 떠나야만 하오.', `MaleText_loc4`='我爱你，森西莉亚，可我必须得离开这儿。', `MaleText_loc5`='我愛你，珊希莉雅，但我必須離開這裡。', `MaleText_loc7`='Te amo, Sensiria, pero debo irme.' WHERE `ID`=40057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 바보 같은 사람. 베리니아스, 더 일찍 떠났어야 해요.', `FemaleText_loc4`='噢，维林尼亚斯。你这可怜的傻瓜。你真该早点儿离开。', `FemaleText_loc5`='噢，維瑞尼亞斯。你這可憐的笨蛋。你應該早點離開的。', `FemaleText_loc7`='Oh, Verinias. Pobre insensato. Deberías haberte ido antes.' WHERE `ID`=40058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 다트리마와 다른 자들을 따르러 떠날 것이오. 셴드랄라는 이제 돌이킬 수 없소. 악마와 거래를 하다니... 우린 타락의 구렁텅이로 몸을 던져버린 거요.', `MaleText_loc4`='我要赶去与达斯雷玛他们会合。辛德拉已经走得太远了。与魔鬼做交易……我们已经将自己交付给堕落。', `MaleText_loc5`='我會在離開後跟隨達斯雷瑪和其他人。辛德拉做得太過份了。如果與惡魔為伍...就是接受讓自己墮落。', `MaleText_loc7`='Partiré para seguir a Dath''remar y los demás. Los Shen''dralar han ido demasiado lejos. Traficar con demonios... Nos estamos entregando a la corrupción.' WHERE `ID`=40059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 안 돼!', `MaleText_loc4`='不！不！', `MaleText_loc5`='不!不!', `MaleText_loc7`='¡No! ¡NO!' WHERE `ID`=40060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들을 막기엔 너무 늦었어요. 저들의 영광스러움을 그대에게 드리지요...', `FemaleText_loc4`='现在想要阻止他们已经来不及了。让我给你看看他们的荣光……', `FemaleText_loc5`='要阻止他們已經太遲了。讓我將他們的榮耀呈現在你眼前...', `FemaleText_loc7`='Es demasiado tarde para detenerlos. Deja que te muestre su gloria...' WHERE `ID`=40061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비로운 수정의 힘을 빌려 새로운 능력을 얻은 다음, 그 능력으로 급사 토르문을 보호하십시오!', `MaleText_loc4`='从这块神秘的水晶中获取新的能力，并用这些能力保护信使托姆恩！', `MaleText_loc5`='和神秘的水晶互動以獲得新的能力，並使用這些能力守衛信差托爾門!', `MaleText_loc7`='Interactúa con el misterioso cristal para obtener nuevos poderes y utilízalos para defender al mensajero Tormun.' WHERE `ID`=40062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정으로 새로운 능력을 얻었습니다! 이 능력으로 소환된 정령들을 처치하십시오.', `MaleText_loc4`='水晶给了你新的能力！利用这种能力来击败被召唤的元素吧。', `MaleText_loc5`='水晶賦予你新的能力!運用這些能力擊敗那些召喚出來的元素。', `MaleText_loc7`='¡El cristal te ha proporcionado nuevas habilidades! Utilízalas para derrotar a los elementales invocados.' WHERE `ID`=40063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 세상에 파멸의 바람이 불어온다. 파괴의 시대가 새로이 도래할 때 모두 그 증인이 되리라!', `MaleText_loc4`='你们的世界正在灭绝的边缘摇摆。你们都将见证毁灭时代的到来！', `MaleText_loc5`='你們的世界在滅亡的邊緣搖搖欲墜。你們接下來全都會見證這個毀滅新紀元的來臨!', `MaleText_loc7`='Su mundo se tambalea en el borde de la aniquilación. ¡TODOS serán testigos de la llegada de una nueva era de DESTRUCCIÓN!' WHERE `ID`=40064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들아, 승리를 만끽해라. 그것이 마지막일 테니. 주인님이 돌아오시면 이 세상은 불타버리리라!', `MaleText_loc4`='享受胜利吧，凡人们，这是你们最后的胜利。回归的主人将烧毁这个世界！', `MaleText_loc5`='享受這場勝利吧，凡人們，因為這是你們最後一次的勝利。這世界將會在主人回歸時化為火海!', `MaleText_loc7`='Aprecien esta victoria, mortales, pues será la última que tengan. ¡Este mundo arderá cuando regrese el amo!' WHERE `ID`=40065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"영웅"이 또 하나 가셨군.', `MaleText_loc4`='又一个“英雄”倒下了。', `MaleText_loc5`='又一個「英雄」倒下了。', `MaleText_loc7`='Otro "héroe" ha caído.' WHERE `ID`=40066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼 세계에서는 고통만이 있으리라! 자신 있다면 들어와 봐라!', `MaleText_loc4`='暮光的世界将会让你痛不欲生！够胆量的就进来吧！', `MaleText_loc5`='在暮光的國度只有磨難在等著你!有膽量的話就進去吧!', `MaleText_loc7`='¡Sólo encontrarán sufrimiento en el reino del crepúsculo! ¡Entren, si se atreven!' WHERE `ID`=40067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 타오른다!', `MaleText_loc4`='天空在燃烧！', `MaleText_loc5`='天堂也將燃燒!', `MaleText_loc7`='¡Arden los cielos!' WHERE `ID`=40068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠을 경계하라!', `MaleText_loc4`='阴影在弥漫！', `MaleText_loc5`='暗影無所不在!', `MaleText_loc7`='¡Cuidado con la sombra!' WHERE `ID`=40069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 맹랑한 드워프로군. 네놈을 처치하고 초갈 님께 서판을 가지고 가겠다.', `MaleText_loc4`='很好，矮人。我要干掉你，然后将这些石板交给古加尔。', `MaleText_loc5`='很好，矮人。我會殺死你，把石板帶給丘加利。', `MaleText_loc7`='Muy bien, enano. Te mataré y le llevaré las tablillas a Cho''Gall.', `FemaleText_loc1`='아주 맹랑한 드워프로군. 네놈을 처치하고 초갈 님께 서판을 가지고 가겠다.', `FemaleText_loc4`='很好，矮人。我要干掉你，然后将这些石板交给古加尔。', `FemaleText_loc5`='很好，矮人。我會殺死你，把石板帶給丘加利。', `FemaleText_loc7`='Muy bien, enano. Te mataré y le llevaré las tablillas a Cho''Gall.' WHERE `ID`=40070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 회전하는 구슬들이 고동치며 어둠의 기운을 내뿜습니다!', `MaleText_loc4`='黑暗能量正在这颗旋转的魔球中脉动！', `MaleText_loc5`='這些環繞的球體散發著黑暗能量!', `MaleText_loc7`='¡Las esferas que orbitan emiten energía oscura!' WHERE `ID`=40071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 빛이자 어둠이다! 필멸자들아, 데스윙의 사자 앞에 무릎 꿇어라!', `MaleText_loc4`='我就是交织的光影！凡人，在死亡之翼的使者面前颤抖吧！', `MaleText_loc5`='我是光明亦是黑暗!凡人，匍匐在死亡之翼的信使面前吧!', `MaleText_loc7`='¡Soy la luz y la oscuridad! ¡Tiembles, mortales, ante el heraldo de Alamuerte!' WHERE `ID`=40072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드와 얼라이언스의 적에게 확실히 알려주겠노라. 내 절대로 우리 시민들에게 공포와 소문을 퍼뜨리도록 놔두지 않을 것이다!', `MaleText_loc4`='让暴风城和联盟的敌人们知道，我不会容许他们肆意散播恐惧和谣言！', `MaleText_loc5`='讓暴風城和聯盟的敵人知道，我不會允許他們在人民當中散播恐懼和謠言!', `MaleText_loc7`='¡Que los enemigos de Ventormenta y la Alianza sepan que no voy a permitir que extiendan rumores y miedo entre mi gente!' WHERE `ID`=40073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1과;와; 같은 영웅이 우리 곁에 있는 한, 황혼의 망치단의 그 어떤 위협에도 스톰윈드는 끄떡없을 것이다!', `MaleText_loc4`='有了像$n这样的英雄，暴风城已经准备好迎击暮光之锤的任何威胁！', `MaleText_loc5`='有像$n這樣的英雄站在我們這邊戰鬥，暴風城可以面對任何暮光之錘的威脅!', `MaleText_loc7`='¡Con héroes como $n a nuestro lado, Ventormenta está preparada para hacer frente a la amenaza del Martillo Crepuscular!' WHERE `ID`=40074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단을 어떻게 상대할 것인가에 대한 이야기는 앞으로 할 기회가 충분할 것이다. 오늘만큼은 $n의 승리를 축하하자!', `MaleText_loc4`='我们有足够的时间准备同暮光之锤的战斗。而今天，我们要庆祝$n的胜利！', `MaleText_loc5`='我們有足夠的時間談論與暮光之錘戰鬥前的準備事項。今天，我們慶祝$n的勝利!', `MaleText_loc7`='Tendremos tiempo suficiente para hablar de los preparativos para la batalla contra el Martillo Crepuscular. ¡Hoy celebraremos la victoria de $n!' WHERE `ID`=40075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 분위기가 도시를 감싸고 있습니다, $c|1이여;여;. 시민들 사이에는 공포 분위기가 조성되었고, 실종된 사람들도 한둘이 아닙니다. 진상을 파악해 봐야겠습니다.', `MaleText_loc4`='$c，这座城市中弥漫着一种奇怪的气氛。人们都在害怕着什么。还有许多人失踪了。我们必须将这些谜团查清楚。', `MaleText_loc5`='一股奇怪的氣氛籠罩了城市，$c。人們在擔心某些事情，而許多人都失蹤了。我們必須要解決這件事。', `MaleText_loc7`='Hay un ambiente extraño en la ciudad, $c. La gente tiene miedo de algo y han desaparecido muchas personas. Debemos llegar al fondo de este asunto.' WHERE `ID`=40076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 국왕 폐하께 좀 알려야겠어. 이 이교도 녀석들, 로고쉬하고 면담 한 번 하고 나면 바로 정신 차릴 텐데 말이야.', `MaleText_loc4`='应该有人将这件事告诉国王。同洛戈什谈谈，应该能够让这些教徒明白道理！', `MaleText_loc5`='得有人跟國王講這件事。和洛戈許聊一下，這些教徒就不會再擾亂了。', `MaleText_loc7`='Alguien debería informar al rey. ¡Una charla con Lo''gosh enmendaría a esos cultores!', `FemaleText_loc1`='누가 국왕 폐하께 좀 알려야겠어요. 이 이교도 녀석들, 로고쉬하고 면담 한 번 하고 나면 바로 정신 차릴 텐데 말이에요.', `FemaleText_loc4`='应该有人将这件事告诉国王。同洛戈什谈谈，应该能够让这些教徒明白道理！', `FemaleText_loc5`='得有人跟國王講這件事。和洛戈許聊一下，這些教徒就不會再擾亂了。', `FemaleText_loc7`='Alguien debería informar al rey. ¡Una charla con Lo''gosh enmendaría a esos cultores!' WHERE `ID`=40077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 자들이 올 것이다... 필멸의 존재... 네놈들의 시대는 끝났다.', `MaleText_loc4`='其它人也会来……凡人的年代……已经远去。', `MaleText_loc5`='它們將會降臨...凡人之日...已成為過去式。', `MaleText_loc7`='Otros vendrán... El tiempo de los mortales... ha pasado.' WHERE `ID`=40078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료들의 노력으로 %s|1이;가; 현실 세계로 밀려납니다!', `MaleText_loc4`='战友们的努力逼迫%s进一步进入了物质世界！', `MaleText_loc5`='你們的努力迫使%s更進一步地進入現實國度!', `MaleText_loc7`='¡Los esfuerzos de tu compañero obligan a %s a adentrarse más en el reino físico!' WHERE `ID`=40079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료들의 노력으로 %s|1이;가; 황혼 세계로 밀려납니다!', `MaleText_loc4`='战友们的努力逼迫%s进一步进入了暮光世界！', `MaleText_loc5`='你們的努力迫使%s更進一步地進入暮光國度!', `MaleText_loc7`='¡Los esfuerzos de tu compañero obligan a %s a adentrarse más en el Reino Crepuscular!' WHERE `ID`=40080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 자손이여! 부족의 동지들이여!', `MaleText_loc4`='暗矛的儿女们！部族的朋友们！', `MaleText_loc5`='暗矛的各位子民!部族的友人們!', `MaleText_loc7`='¡Hijos e hijas de la Lanza Negra! ¡Amigos de la tribu!' WHERE `ID`=40081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬을 잘라제인의 사악한 지배에서 자유롭게 할 준비가 되었다. 나를 따르라!', `MaleText_loc4`='我们的军队将把那些岛屿从扎拉赞恩的魔爪中解放出来！加入我们吧！', `MaleText_loc5`='我們做好了準備，衝上島嶼，解放札拉贊恩邪惡統治下的人!和我一起來!', `MaleText_loc7`='¡Vamor a marchar a las Islas y LIBERARLAS de la opresión de Zalazane! ¡Únanse a mí!' WHERE `ID`=40082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인의 시대도 끝이다! 검은창 부족은 다시 고향을 얻으리라. 준비하라!', `MaleText_loc4`='扎拉赞恩的末日到了！暗矛部族将再次回到家园。准备出发！', `MaleText_loc5`='札拉贊恩的死期到了!暗矛部族會再次回到屬於我們的家園。準備好!', `MaleText_loc7`='¡A Zalazane le ha llegado su hora! La Lanza Negra volverá a su hogar. ¡Prepárense!' WHERE `ID`=40083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오셨군, 현명한 자매여! 검은창 부족은 감사하네.', `MaleText_loc4`='你好，睿智的姐妹！暗矛部族感谢你。', `MaleText_loc5`='你來了，睿智的姊妹!暗矛部族感謝你。', `MaleText_loc7`='¡Viniste, sabia hermana! La Lanza Negra te agradece.' WHERE `ID`=40084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론입니다, 센진의 아들이여. 젠타브라는 언제나 약속을 지킵니다.', `FemaleText_loc4`='不必担心，森金之子，岑塔布拉从来不会食言。', `FemaleText_loc5`='當然，森金之子。贊塔布拉一向遵守諾言。', `FemaleText_loc7`='Claro, Hijo de Sen''jin. Zen''tabra siempre respeta su palabra.' WHERE `ID`=40085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔네! 검은창 부족의 전사들이여, 준비하게! 로아께서 함께하신다네! 바니라, 젠타브라, 준비되셨나?', `MaleText_loc4`='暗矛部族的武士们，进军的时刻到了！众神与我们同在！准备好了吗？瓦妮拉，岑塔布拉？', `MaleText_loc5`='就是此刻!暗矛部族的戰士呀，做好準備!羅亞與我們同在!你準備好了嗎，凡妮拉?贊塔布拉?', `MaleText_loc7`='¡Es la hora! ¡Guerreros de la Lanza Negra, prepárense! ¡La Loa nos acompaña! ¿Están listas, Vanira, Zen''tabra?' WHERE `ID`=40086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들, 그들도 우리와 함께할 겁니다...', `FemaleText_loc4`='元素也将与我们同在……', `FemaleText_loc5`='元素也是與我們同在...', `FemaleText_loc7`='Los elementos también nos acompañan…' WHERE `ID`=40087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...섬에 있는 짐승들도 마찬가지지요.', `FemaleText_loc4`='……就像这里的野兽。', `FemaleText_loc5`='...就像島上的那些野獸一樣', `FemaleText_loc7`='...como las bestias de las Islas.' WHERE `ID`=40088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 가세! 먼저 브원삼디에게 가겠네... 이 싸움에서 이기려면 그의 힘이 필요하니 말일세.', `MaleText_loc4`='出发！我们先要去找邦桑迪……我们需要他强大的魔精力量。', `MaleText_loc5`='讓我們上吧!先去找伯昂撒姆第...如果我們想打贏這場仗，要先讓他的魔精站在我們這邊。', `MaleText_loc7`='¡Pues vamos! Primero, a Bwonsamdi... Si pensamos ganar, necesitaremos su mojo.' WHERE `ID`=40089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내 뼈를 건드리느냐? 브원삼디의 것이다. 손대지 마라!', `MaleText_loc4`='谁在碰我的骨头？这是邦桑迪的东西，绝不允许亵渎！', `MaleText_loc5`='是誰在動我的骨頭?那是伯昂撒姆第的東西，不是你可以觸碰的東西!', `MaleText_loc7`='¿QUIÉN HA ESTADO REVOLVIENDO MIS HUESOS? ¡Los huesos de Bwonsamdi no se tocan!' WHERE `ID`=40090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 센진의 아들, 볼진이다. 위대한 브원삼디여, 부탁이 있어서 왔다.', `MaleText_loc4`='我是沃金，森金之子。伟大的邦桑迪，我需要你的帮助。', `MaleText_loc5`='偉大的伯昂撒姆第啊，我是沃金，森金之子，在此請求你的協助。', `MaleText_loc7`='Soy Vol''jin, hijo de Sen''jin, y vengo a pedir tu ayuda,  oh, gran Bwonsamdi.' WHERE `ID`=40091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠사냥꾼, 네놈이 어떤 녀석인지 안다. 뭘 원하는지도. 어째서 내가 도와주리라 생각하는 거지? 현명하지 못하군. 나를 저편에서 불러내다니...', `MaleText_loc4`='我知道你是谁，暗影猎手。我知道你想要什么。但你凭什么认为我会帮助你？召唤我可算不上明智的行为……', `MaleText_loc5`='我知道你是誰，暗影獵手。而且我也知道你想要什麼。不過你憑什麼認為我會幫忙?把我從那個世界召喚過來，這麼做可不明智啊...', `MaleText_loc7`='Sé quién eres, cazador sombrío. Y sé lo que QUIERES. Pero ¿qué te hace pensar que voy a ayudarte? No es de sabios llamarme del Más Allá…' WHERE `ID`=40092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족이라... 그 북소리를 들은 지도, 의식에 바쳐진 공물을 마신 지도 오래전 일이군. 볼진, 네놈 부족의 죽은 자들을 돌봐주었다. 대가도 없이. 검은창 부족은 왜 브원삼디를 저버렸나, 음?', `MaleText_loc4`='暗矛……我已经很久没有听到这种鼓声……没喝过你们的祭品了。我很想见证你的死亡，沃金，你这个混帐。为什么暗矛要背弃邦桑迪？', `MaleText_loc5`='暗矛部族...上次聽到這鼓聲，上次飲用祭品...已經是好久好久以前的事了。沃金，我一直替你看著這些死傢伙，但你啥也沒給我。是什麼理由讓暗矛部族遺忘伯昂撒姆第，嗯?', `MaleText_loc7`='Lanza Negra... Ya no oigo sus tambores... ya no bebo sus ofrendas rituales. He cuidado a tus muertos, Vol''jin, a cambio de NADA. ¿Por qué la Lanza Negra abandonó a Bwonsamdi, eh?' WHERE `ID`=40093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 영혼이여, 우리는 쫓겨났다. 주술대가 잘라제인이 메아리 섬을 빼앗고... 우리를 미치게 하고, 서로 싸우게 했다. 메아리 섬에 남은 트롤은 넋 나간 부두 노예뿐이다.', `MaleText_loc4`='伟大的英灵，我们饱受欺凌。妖术之主扎拉赞恩夺走了我们的岛屿家园……他让我们疯狂地自相残杀。回音群岛上只剩下他那些失去意识的巨魔奴隶。', `MaleText_loc5`='偉大的聖靈啊，我們被迫離開家園。妖術大師札拉贊恩從我們手中奪走這片群島...讓我們發狂，讓我們互相交戰。留在回音群島上的食人妖，全都是他那些失去心智的巫毒奴僕。', `MaleText_loc7`='Fuimos exiliados. El hechicero Zalazane nos sacó las Islas... Nos enloqueció, nos hizo pelear entre nosotros. Los únicos trolls que quedan en las Islas Eco son sus esclavos zombificados por el vudú.' WHERE `ID`=40094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인이라...', `MaleText_loc4`='扎拉赞恩……', `MaleText_loc5`='札拉贊恩...', `MaleText_loc7`='Zalazane...' WHERE `ID`=40095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브원삼디여, 우리를 도와라! 고향을 되찾을 수 있도록! 검은창 부족이 메아리 섬으로 돌아가, 다시 북소리를 울릴 수 있도록! 그대에게 바쳐진 공물을 한 번 더 받아 다오! 센진의 아들로서 맹세하겠다.', `MaleText_loc4`='邦桑迪！请帮助我们！让暗矛部族回到岛国故土，让您的鼓声再次响起！请再次饮下我们的献祭！倾听我，森金之子的誓言！', `MaleText_loc5`='伯昂撒姆第啊，幫助我們吧!幫助我們拿回自己的家園!讓暗矛部族回歸群島，再次擊響屬於你的鼓聲!再次飲下屬於你的祭品!我以森金之子之名在此發誓。', `MaleText_loc7`='¡Ayúdanos, Bwonsamdi, a recuperar nuestro hogar! ¡Devuelve a la Lanza Negra a las Islas y volverás a oír tus tambores! ¡Beberás tus ofrendas rituales una vez más! Yo, el hijo de Sen''jin, te lo prometo.' WHERE `ID`=40096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 어둠사냥꾼이여, 네가 얼마나 간절히 원하는지 확인해 보겠다. 그럴 가치가 있는지도.', `MaleText_loc4`='嗯，我想看看你有几分真诚，暗影猎手，对我又有几分价值。', `MaleText_loc5`='嗯。是時候了，來看看你的渴望有多強烈，暗影獵手。來看看你是否有這個價值。', `MaleText_loc7`='Jmmmm. Es el momento de ver cuánto deseas esto, cazador sombrío. A ver si lo VALES.' WHERE `ID`=40097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 맞설 수 있다고 생각하나? 어둠사냥꾼, 포기해라.', `MaleText_loc4`='你以为你有资格面对我吗？放弃吧，暗影猎手！', `MaleText_loc5`='你還以為自己真能和我抗衡?放棄吧，暗影獵手!', `MaleText_loc7`='¿Crees que puedes enfrentarme a MÍ? ¡Ríndete, cazador sombrío!' WHERE `ID`=40098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 네 주술의 힘은 크구나. 볼진, 어쩌면 넌 도와줄 가치가 있을 지도...', `MaleText_loc4`='够了！沃金，你的魔精的确强大。也许你是值得帮助的……', `MaleText_loc5`='夠了!沃金，你的魔精還真夠大。或許你真的值得讓我幫這個忙...', `MaleText_loc7`='¡BASTA! Tienes un GRAN mojo, Vol''jin. Puede ser que valga la pena ayudarte...' WHERE `ID`=40099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 영혼이여, 내가 아니라 우리 부족이다.', `MaleText_loc4`='伟大的英灵，一切都是为我的部族。', `MaleText_loc5`='偉大的聖靈呀，不是為了我，是我的部族。', `MaleText_loc7`='No sólo yo, Gran Espíritu. Mi TRIBU.' WHERE `ID`=40100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음.', `MaleText_loc4`='嗯。', `MaleText_loc5`='呣。', `MaleText_loc7`='Mmm.' WHERE `ID`=40101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 건너 옛 마을로 가라. 그곳을 되찾아라. 그러면 도와주겠다.', `MaleText_loc4`='穿越水面，到那个村庄去，夺回它。我将帮助你。', `MaleText_loc5`='去那個老村子，就在河的那頭。奪回村落，我就會協助你們。', `MaleText_loc7`='Ve a la villa vieja, cruzando el agua. Recupérala. Y yo te ayudaré.' WHERE `ID`=40102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정해진 시간이 되면, 저들은 폭풍 정령을 풀어 도시를 쓸어버리고 우리 주인님께서 돌아오시는 영광스러운 그 순간을 준비하리라!', `MaleText_loc4`='等时刻一到，它们就会释放出暴风元素，彻底冲刷这座城市，为我们主人的荣耀回归而铺平道路！', `MaleText_loc5`='在指定的時間到來時，他們會釋放出風暴元素，把整座城市大清洗一番，為我們主人榮耀的歸來搭起舞台!', `MaleText_loc7`='Cuando llegue el momento, liberarán elementales de fuego que arrasarán la ciudad y ¡prepararán el escenario para el glorioso regreso de nuestro maestro!' WHERE `ID`=40103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상징, 예전에 본 적이 있는 것 같은데...', `MaleText_loc4`='这个标志……我以前可能见过……', `MaleText_loc5`='這個標誌，我想我曾在哪裡看過...', `MaleText_loc7`='Creo que he visto este símbolo antes...' WHERE `ID`=40104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 우리 모두를 기다린다. 옛 고향을 위해 싸운다... 우리 것은 다시 우리 손에 되찾고 말리라!', `MaleText_loc4`='他们正等在那里。我们将为古老的家园而战……我们要夺回我们的岛国！', `MaleText_loc5`='他們等著我們，都在等著我們。此刻我們為了古老家園而奮戰...我們要取回屬於我們的東西!', `MaleText_loc7`='Ellos nos esperan. Pelearemos por nuestro antiguo hogar... ¡Reclamaremos lo que es NUESTRO!' WHERE `ID`=40105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 영혼들이여... 일어나라! 고대의 가면을 써라... 피묻은 창을 들어라... 지금부터 볼진의 뒤를 따르라!', `MaleText_loc4`='暗矛的英灵们……起来吧！戴上古老的面具，拿起血色的长矛……现在你们将追随沃金而战！', `MaleText_loc5`='暗矛部族的靈魂呀...甦醒吧!戴上古老的面具，拾起染血的長矛...跟隨沃金，就是現在!', `MaleText_loc7`='Espíritus de la Lanza Negra, ¡DESPIERTEN! Tomen sus máscaras antiguas, sus lanzas sangrientas. ¡Seguirán a VOL''JIN!' WHERE `ID`=40106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라! 내가 베푼 은혜를 현명하게 쓰라.', `MaleText_loc4`='去吧！谨慎使用我的恩惠。', `MaleText_loc5`='現在，去吧!善用我賦予的恩典。', `MaleText_loc7`='¡VÉ! Usa mis huesos sabiamente.' WHERE `ID`=40107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 알갈라르 톨, 톨 알타우그. 끝은 새로운 시작이리니.', `MaleText_loc4`='那就来吧。Al''galar thol，thol al''thaug：末日即是新的开始。', `MaleText_loc5`='那就讓它來吧。Al''galar thol，thol al''thaug:結束就是開始。', `MaleText_loc7`='Que así sea. Al''galar thol, thol al''thaug: El final es el comienzo.' WHERE `ID`=40108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인을 얕보지마라... 까다롭고 교활한 데다 부두의 힘까지 얻어 강력한 적이니 말이다. 준비되었나? 자, 가자!', `MaleText_loc4`='不要低估扎拉赞恩……他是一个可怕的敌人，狡诈而且拥有强大的法力。准备好了吗？出发！', `MaleText_loc5`='別低估了札拉贊恩...這個敵人相當狡猾、精明，還具有強大的巫毒之力。準備好了嗎?上吧!', `MaleText_loc7`='No subestimen a Zalazane... es un enemigo astuto, con un fuerte vudú. ¿Están listos? ¡VAMOS!' WHERE `ID`=40109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술대가여, 때가 왔다! 검은창 부족의 아들딸이 돌아왔다! 네놈을 바다 속으로 처박아주겠다...', `MaleText_loc4`='你的末日到了，恶魔！现在，暗矛部族的儿女们回来了！我们要把你赶进大海……', `MaleText_loc5`='妖術大師，就是此刻!暗矛部族的子民們回來了!我們要把你趕到海裡去...', `MaleText_loc7`='¡Llegó la HORA, Hechicero! ¡Los hijos de la Lanza Negra han vuelto! El mar será tu tumba…' WHERE `ID`=40110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠사냥꾼, 어림도 없다. 메아리 섬은 내 것이다!', `MaleText_loc4`='你真是个可怜的家伙，暗影猎手。回音群岛是我的！', `MaleText_loc5`='暗影獵手，你別想這麼做。回音群島是我的!', `MaleText_loc7`='No harás nada, cazador sombrío. ¡Las Islas Eco son MÍAS!' WHERE `ID`=40111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하 하 하 하!', `MaleText_loc4`='哈哈哈哈！', `MaleText_loc5`='哈哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja, ja!' WHERE `ID`=40112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망가게 두지 마라!', `MaleText_loc4`='我们不能让他逃走！', `MaleText_loc5`='怎能讓他就這樣逃掉!', `MaleText_loc7`='¡No lo dejemos huir!' WHERE `ID`=40113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젠타브라에게서 벗어날 수는 없습니다. 이 섬에 있다면 말이지요.', `FemaleText_loc4`='只要他在群岛上，就逃不出岑塔布拉的手心。', `FemaleText_loc5`='只要贊塔布拉在這些島上，就別想從贊塔布拉身邊逃走。', `FemaleText_loc7`='No hay escape de Zen''tabra. No mientras él esté en estas islas.' WHERE `ID`=40114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 찾아내게. 현명한 자여, 어서!', `MaleText_loc4`='聪明的战士，马上去找到他！', `MaleText_loc5`='那就快把他找出來，智者。去吧!', `MaleText_loc7`='Entonces encuéntralo. ¡Vé!' WHERE `ID`=40115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 서쪽에 있군요. 흑마법을 시도하는 중입니다.', `FemaleText_loc4`='他就在西边，在操纵某种黑暗魔法。', `FemaleText_loc5`='他就在西邊，在那研究某種黑魔法。', `FemaleText_loc7`='Está al oeste de aquí, ocupado en su magia negra.' WHERE `ID`=40116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 못 갈 걸세. 이제 끝장낼 테니.', `MaleText_loc4`='他灭亡的时刻已经近了。', `MaleText_loc5`='不會太久的。是時候做個了斷了。', `MaleText_loc7`='No por mucho. A terminar con esto.' WHERE `ID`=40117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기해라, 잘라제인. 이제 끝이다.', `MaleText_loc4`='放弃吧，扎拉赞恩，一切都结束了。', `MaleText_loc5`='札拉贊恩，放棄吧。一切都結束了。', `MaleText_loc7`='Ríndete, Zalazane. Se acabó.' WHERE `ID`=40118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 놈! 도망친 줄 알았나! 네놈의 소중한 부족이 널 처리하도록 이리 꾀어낸 거다!', `MaleText_loc4`='傻瓜！我不会逃走。我把你引到这里，就是为了消灭你和你珍爱的部族！', `MaleText_loc5`='笨蛋!我不是逃，是把你們引誘到這裡，把你和你的寶貝部族一起殺掉!', `MaleText_loc7`='¡Imbécil! No huía. ¡Los traje hasta aquí para matarlos con su propia tribu tan amada!' WHERE `ID`=40119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상관없다! 나를 해칠 수는 없어! 살아있는 것은 이 장벽을 뚫을 수 없지! 어둠사냥꾼, 메아리 섬은 잘라제인이 다스린다. 지금도 앞으로도 영원히!', `MaleText_loc4`='没关系！我是不可战胜的。没有人能穿越这道屏障！回音群岛是扎拉赞恩的，暗影猎手！永远都是！', `MaleText_loc5`='沒差!反正沒人能碰得到我。沒有活物能夠穿越這道屏障!統治回音群島的是札拉贊恩，暗影獵手!此刻如此，未來也是如此!', `MaleText_loc7`='¡No importa! Soy intocable. ¡Nada que viva podrá atravesar esta barrera! ¡Las Islas Eco son de Zalazane, cazador sombrío! ¡Ahora y PARA SIEMPRE!' WHERE `ID`=40120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우 하 하 하 하!', `MaleText_loc4`='喔，哈哈哈哈！', `MaleText_loc5`='哇哈哈哈哈哈哈哈!', `MaleText_loc7`='¡BUAA JA JA JA JA!' WHERE `ID`=40121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저게 누구냐?', `MaleText_loc4`='谁……是谁？', `MaleText_loc5`='誰...到底是誰?', `MaleText_loc7`='¿Quién... quién es ese?' WHERE `ID`=40122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인. 무슨 생각으로 내 것을 가지려 하느냐? 검은창 부족의 죽은 자는 내 소관이다, 마술사여... 너도 그들과 똑같게 해 주마!', `MaleText_loc4`='扎拉赞恩……你怎么敢抢走我的东西？死去的暗矛都是我的……而现在，你也将加入他们！', `MaleText_loc5`='札拉贊恩，你在想什麼，以為能拿走我的東西?暗矛的死人全是我的，巫士...如今你也即將成為他們的一員!', `MaleText_loc7`='ZALAZANE. ¿Qué te creías, tomando lo que es mío? Los muertos de Lanza Negra son MI territorio, hechicero... ¡y tú serás uno de ellos!' WHERE `ID`=40123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 안돼... 안돼애!', `MaleText_loc4`='不！不……不！！！', `MaleText_loc5`='喔不!不...不不不!', `MaleText_loc7`='¡No! No... ¡NOOO!' WHERE `ID`=40124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악한 트롤에게 걸맞은 최후로군. 브원삼디여, 나도 검은창 부족 모두도 그대에게 감사할 따름이다. 마땅히 그대는 계속 칭송받으리라.', `MaleText_loc4`='这是邪恶巨魔应有的下场。邦桑迪，我们全体暗矛部族都感谢您。我们将继续赞颂您的荣耀。', `MaleText_loc5`='腐敗的食人妖就該是這種死法。伯昂撒姆第，我感謝你，全體暗矛部族感謝你。我們將會繼續依照傳統儀式膜拜你。', `MaleText_loc7`='El fin propicio para un troll tan corrupto. Bwonsamdi: La Lanza Negra y yo te agradecemos. Seguiremos honrándote, como corresponde.' WHERE `ID`=40125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전처럼 검은창 부족의 북소리를 들을 수 있다면 좋겠군. 센진의 아들이여, 몸조심해라. 브원삼디가 기다리겠다... 저편에서...', `MaleText_loc4`='真高兴能再一次听到暗矛的鼓声。一切小心，森金之子。邦桑迪将在另一个世界，等待你的到来……', `MaleText_loc5`='能再次聽到暗矛的鼓聲感覺真好。保重，森金之子。伯昂撒姆第會在另一個世界...在另一個世界等著你...', `MaleText_loc7`='Será bueno volver a oír los tambores de Lanza Negra. Cuídate, Hijo de Sen''jin. Bwonsamdi te estará esperando... en el Más Allá…' WHERE `ID`=40126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을로 돌아갈 시간이다. 우리 고향을 다시 세우자... 검은창 부족의 고향 말이다. 젠타브라, 그대도 우리와 함께할 텐가?', `MaleText_loc4`='我们要回到自己的村庄，重建家园……暗矛部族的家园。你愿意加入我们吗，岑塔布拉？', `MaleText_loc5`='是回家的時候了。是重建暗矛部族...重建我們家園的時候了。你會留在我們身邊嗎，睿智的贊塔布拉?', `MaleText_loc7`='Hora de volver a la villa, de reconstruir nuestro hogar... el hogar de la Lanza Negra. ¿Te quedarás, sabia Zen''tabra?' WHERE `ID`=40127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 운명은 이제 그대 운명과 얽혔습니다. 볼진이여, 좋든 나쁘든 함께하지요.', `FemaleText_loc4`='我们的命运已经纠缠在一起，沃金，无论结局会是如何，我都会留下。', `FemaleText_loc5`='沃金，從現在起我的命運和你交結，無論好壞。我會和你生死與共。', `FemaleText_loc7`='Nuestros destinos están unidos, Vol''jin, para bien o para mal. Me quedo.' WHERE `ID`=40128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 기쁜 일이 있나. 여기 오는 방법을 찾아내셨군요!$b$b시간 낭비하지 맙시다. 준비는 되셨죠?', `MaleText_loc4`='真好，你终于来了！$b$b时间不多，你准备好了吗？', `MaleText_loc5`='很好，你找到這了!$b$b時間緊迫。你準備好了嗎?', `MaleText_loc7`='¡Estupendo! ¡Has sabido cómo llegar aquí!$b$bNo tenemos tiempo que perder. ¿$gListo:Lista;?' WHERE `ID`=40129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악몽이 지배하리라!', `FemaleText_loc4`='噩梦统御一切！', `FemaleText_loc5`='夢魘將統治一切!', `FemaleText_loc7`='¡La pesadilla reina!' WHERE `ID`=40130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다! 출발합시다, 브란!', `MaleText_loc4`='我们准备好了！去吧，布莱恩！', `MaleText_loc5`='我們準備好了!上吧，布萊恩!', `MaleText_loc7`='¡Estamos listos! ¡Vamos, Brann!', `FemaleText_loc1`='준비되었어요! 출발해요, 브란!', `FemaleText_loc4`='我们准备好了！去吧，布莱恩！', `FemaleText_loc5`='我們準備好了!上吧，布萊恩!', `FemaleText_loc7`='¡Estamos listos! ¡Vamos, Brann!' WHERE `ID`=40131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생명의 끈...', `FemaleText_loc4`='生命的希冀……', `FemaleText_loc5`='生命的希冀...', `FemaleText_loc7`='Las hebras de la vida...' WHERE `ID`=40132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리와 함께 해라! 우리와 함께!', `FemaleText_loc4`='加入我们！加入我们！', `FemaleText_loc5`='加入我們!加入我們!', `FemaleText_loc7`='¡Únete a nosotros! ¡Únete a nosotros!' WHERE `ID`=40133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분의 목소리를 들어봐라...', `FemaleText_loc4`='聆听他的声音……', `FemaleText_loc5`='聆聽他的聲音...', `FemaleText_loc7`='Escucha su voz...' WHERE `ID`=40134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문을 외우는 %s 주변에 검은 잿가루가 휘몰아칩니다.', `MaleText_loc4`='黑暗的灰烬在%s周围打着转，他口里吟诵着咒语：', `MaleText_loc5`='被黑暗之塵環繞著的%s，低詠著咒語:', `MaleText_loc7`='Las cenizas negras se arremolinan en torno a %s, que murmura un conjuro:' WHERE `ID`=40135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊숙한 대지에서 나온 재를 적이 손수 흩뿌렸도다...', `MaleText_loc4`='灰烬燃自位面深渊，烧尽敌人散布梦魇……', `MaleText_loc5`='來自地獄的灰燼，由敵人之手灑出...', `MaleText_loc7`='Cenizas traídas de los llanos, que el enemigo esparció con sus manos…' WHERE `ID`=40136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 신이시여, 지진과 천둥이여, 저를 옭아맨 이 굴레를 산산이 부숴 주십시오!', `MaleText_loc4`='恐怖之神，雷霆地震，撕裂生灵，威慑凡尘！', `MaleText_loc5`='恐懼之神，地震和雷電，撕裂並粉碎這些凡世的束縛吧!', `MaleText_loc7`='¡Dioses del terror, de los truenos y temblores, de estas ataduras sean mis libertadores!' WHERE `ID`=40137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사악하게 웃습니다.', `MaleText_loc4`='%s发出一阵残忍的笑声。', `MaleText_loc5`='%s發出了冷酷的笑聲。', `MaleText_loc7`='%s se carcajea cruelmente.' WHERE `ID`=40138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 필멸자여! 지옥불에서 네가 설쳐 준 덕에 이렇게 탈출하게 되었군.', `MaleText_loc4`='感谢你，凡人！你在炼狱火海的英雄之举让我逃了出来。', `MaleText_loc5`='感謝你，凡人!因為你在火焰煉獄的英勇表現使得我有可能順利逃脫。', `MaleText_loc7`='¡Gracias, mortal! Tu heroísmo en el Inferno ha hecho posible mi escape.' WHERE `ID`=40139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 보답으로 널 살려 주마.', `MaleText_loc4`='作为回报，我会饶你一命。', `MaleText_loc5`='為了獎勵你，我會饒你一命。', `MaleText_loc7`='Como recompensa, te dejaré vivir.' WHERE `ID`=40140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 네 차례가 곧 올 것이다. 그래, 필멸자여. 머지않아 말이다...', `MaleText_loc4`='但你的时间已经不多了。是的，凡人。不多了……', `MaleText_loc5`='但是你的那一天很快就會到來。是的，凡人。很快...', `MaleText_loc7`='Pero tu hora llegará pronto. Sí, mortal. Muy pronto…' WHERE `ID`=40141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힝클스가 보급품을 찾으려고 자신의 배낭을 뒤집니다.', `MaleText_loc4`='辛克尔斯在背包中搜索着供给品。', `MaleText_loc5`='辛寇斯在他的背包中翻來翻去找尋補給品。', `MaleText_loc7`='Hinkles hurga en su mochila en busca de suministros.' WHERE `ID`=40142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코그스핀이 거인의 가방을 뒤져 물건을 찾습니다.', `MaleText_loc4`='克斯宾在他的“巨无霸”背包中找东西。', `MaleText_loc5`='科士賓在他的「巨無霸」背包翻來翻去找尋物品。', `MaleText_loc7`='Rotadiente hurga en su bolsa "gigantesca" en busca de objetos.' WHERE `ID`=40143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황량한 전망대로 향합니다.', `MaleText_loc4`='向荒野瞭望台前进。', `MaleText_loc5`='向野生眺望前進。', `MaleText_loc7`='De camino al Mirador Salvaje.' WHERE `ID`=40144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 방어는 뚫을 수 없다! 우리가 놈리건의 진정한 후예다!', `MaleText_loc4`='我们的防御牢不可破！我们是真正的诺莫瑞根之子！', `MaleText_loc5`='我們的防禦是無懈可擊的!我們才是真正的諾姆瑞根之子!', `MaleText_loc7`='¡Tenemos defensas impenetrables! ¡Somos los verdaderos hijos de Gnomeregan!' WHERE `ID`=40145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계상어의 ''수리''를 사용하십시오!', `MaleText_loc4`='快用机械鲨鱼的修复功能！', `MaleText_loc5`='使用機械鯊魚的修理功能!', `MaleText_loc7`='¡Utiliza la facultad REPARAR del Mecatiburón!' WHERE `ID`=40146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동지들이여, 계속 말만 할 겁니까? 이제는 행동할 때입니다. 이 "선택받은 자"들이 우리 것을 계속 빼앗게 놔두지 않겠습니다! 우리가 사로잡은 죄수입니다. 우리의 손으로 고대 신께 바칩시다!!', `MaleText_loc4`='话已经说得够多了，伙伴们！现在是行动的时刻！我们不会让那些“天选者”夺走属于我们的东西！我们要夺下这名囚徒，将他献给我们的古老神祗！！', `MaleText_loc5`='不用再多說了，戰友們!這是戰鬥的號角!我們絕不讓那些「獲選之人」拿走屬於我們的東西!我們會自己將抓到的這個囚犯獻給古神們!', `MaleText_loc7`='¡Ya basta de hablar, camaradas! ¡Esto es una llamada a la acción! No permitiremos que esos "elegidos" se lleven lo que es nuestro! ¡¡Fuimos nosotros los que capturamos a este prisionero y seremos nosotros los que se lo ofrezcamos a los dioses antiguos!!', `FemaleText_loc1`='동지들이여, 계속 말만 할 겁니까? 이제는 행동할 때입니다. 이 "선택받은 자"들이 우리 것을 계속 빼앗게 놔두지 않겠습니다! 우리가 사로잡은 죄수입니다. 우리의 손으로 고대 신께 바칩시다!!', `FemaleText_loc4`='话已经说得够多了，伙伴们！现在是行动的时刻！我们不会让那些“天选者”夺走属于我们的东西！我们要夺下这名囚徒，将他献给我们的古老神祗！！', `FemaleText_loc5`='不用再多說了，戰友們!這是戰鬥的號角!我們絕不讓那些「獲選之人」拿走屬於我們的東西!我們會自己將抓到的這個囚犯獻給古神們!', `FemaleText_loc7`='¡Ya basta de hablar, camaradas! ¡Esto es una llamada a la acción! No permitiremos que esos "elegidos" se lleven lo que es nuestro! ¡¡Fuimos nosotros los que capturamos a este prisionero y seremos nosotros los que se lo ofrezcamos a los dioses antiguos!!' WHERE `ID`=40147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동지여, 바로 이 순간, 우린 스스로에게 물어야 합니다. 고대 신께서는 우리가 과연 무엇을 하길 바라실까?', `MaleText_loc4`='就在这一刻，朋友，我们应该问问自己。上古之神希望我们做什么？', `MaleText_loc5`='在這個時刻，朋友們，我們應該捫心自問，上古之神希望我們做些什麼?', `MaleText_loc7`='Es en este preciso instante, amigos, cuando deberíamos preguntarnos: ¿Qué quieren que hagamos los dioses antiguos?', `FemaleText_loc1`='동지여, 바로 이 순간, 우린 스스로에게 물어야 합니다. 고대 신께서는 우리가 과연 무엇을 하길 바라실까?', `FemaleText_loc4`='就在这一刻，朋友，我们应该问问自己。上古之神希望我们做什么？', `FemaleText_loc5`='在這個時刻，朋友們，我們應該捫心自問，上古之神希望我們做些什麼?', `FemaleText_loc7`='Es en este preciso instante, amigos, cuando deberíamos preguntarnos: ¿Qué quieren que hagamos los dioses antiguos?' WHERE `ID`=40148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크툰께서 하신 말씀을 기억하십니까? 우린 똑똑히 기억합니다! "그대의 친구가 그대를 배신할지어다!" 친구들은 정말 우릴 배신했습니다!', `MaleText_loc4`='记住克苏恩的话！牢牢记住！“你的朋友将会背叛你！”而且已经背叛了我们！', `MaleText_loc5`='記得克蘇恩所說的!好好記得「你的朋友們將會背叛你!」這句話，因為他們真的背叛了我們!', `MaleText_loc7`='¡Recuerden las palabras de C''thun! ¡Recuérdenlas bien! "¡Sus amigos los traicionarán!" ¡Y nos han traicionado!', `FemaleText_loc1`='크툰께서 하신 말씀을 기억하십니까? 우린 똑똑히 기억합니다! "그대의 친구가 그대를 배신할지어다!" 친구들은 정말 우릴 배신했습니다!', `FemaleText_loc4`='记住克苏恩的话！牢牢记住！“你的朋友将会背叛你！”而且已经背叛了我们！', `FemaleText_loc5`='記得克蘇恩所說的!好好記得「你的朋友們將會背叛你!」這句話，因為他們真的背叛了我們!', `FemaleText_loc7`='¡Recuerden las palabras de C''thun! ¡Recuérdenlas bien! "¡Sus amigos los traicionarán!" ¡Y nos han traicionado!' WHERE `ID`=40149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 초갈이 황혼의 망치단을 만든 건 사실입니다. 하지만 오늘의 망치단을 만든 건 누구입니까? 누가 오크와 인간 도시에서 진실을 설파하며 박해를 받았습니까?', `MaleText_loc4`='是的，暮光之锤也许是古加尔建立的。但是谁让它有了今日的地位？是谁在兽人和人类的城市中成功地揭露了真相，散播了混乱？', `MaleText_loc5`='是的，丘加利或許是暮光之錘的創始者，但是誰讓它成長為現今的樣子?誰在人類和獸人的城市中宣揚真理和遭受迫害?', `MaleText_loc7`='Es cierto que Cho''gall fundó el Martillo Crepuscular, pero ¿quién lo convirtió en lo que es ahora? ¿Quién predicó la verdad y afrontó la persecución en las ciudades orcas y humanas?', `FemaleText_loc1`='예, 초갈이 황혼의 망치단을 만든 건 사실입니다. 하지만 오늘의 망치단을 만든 건 누구입니까? 누가 오크와 인간 도시에서 진실을 설파하며 박해를 받았습니까?', `FemaleText_loc4`='是的，暮光之锤也许是古加尔建立的。但是谁让它有了今日的地位？是谁在兽人和人类的城市中成功地揭露了真相，散播了混乱？', `FemaleText_loc5`='是的，丘加利或許是暮光之錘的創始者，但是誰讓它成長為現今的樣子?誰在人類和獸人的城市中宣揚真理和遭受迫害?', `FemaleText_loc7`='Es cierto que Cho''gall fundó el Martillo Crepuscular, pero ¿quién lo convirtió en lo que es ahora? ¿Quién predicó la verdad y afrontó la persecución en las ciudades orcas y humanas?' WHERE `ID`=40150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단은 좋은 시기를 맞이하고 있습니다. 정말 이보다 더 좋을 순 없습니다. 먼저 데스윙 님께서 도착하셨습니다. 그리고 이제... 이제 위대한 라그나로스 님께서 돌아오셨습니다!', `MaleText_loc4`='这真是暮光之锤的辉煌时刻。无与伦比的辉煌时刻。首先，我们迎来了死亡之翼领主。而现在……现在伟大的拉格纳罗斯也回来了！', `MaleText_loc5`='這是暮光之錘偉大的一刻，最偉大的一刻。先是死亡之翼大人的到來，然後強大的拉格納羅斯也復活了!', `MaleText_loc7`='Son buenos tiempos para el Martillo Crepuscular. Los mejores. Primero, la llegada del señor Alamuerte. Y ahora... ¡Ahora el regreso del gran Ragnaros!', `FemaleText_loc1`='황혼의 망치단은 좋은 시기를 맞이하고 있습니다. 정말 이보다 더 좋을 순 없습니다. 먼저 데스윙 님께서 도착하셨습니다. 그리고 이제... 이제 위대한 라그나로스 님께서 돌아오셨습니다!', `FemaleText_loc4`='这真是暮光之锤的辉煌时刻。无与伦比的辉煌时刻。首先，我们迎来了死亡之翼领主。而现在……现在伟大的拉格纳罗斯也回来了！', `FemaleText_loc5`='這是暮光之錘偉大的一刻，最偉大的一刻。先是死亡之翼大人的到來，然後強大的拉格納羅斯也復活了!', `FemaleText_loc7`='Son buenos tiempos para el Martillo Crepuscular. Los mejores. Primero, la llegada del señor Alamuerte. Y ahora... ¡Ahora el regreso del gran Ragnaros!' WHERE `ID`=40151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나씩 하나씩... 적들은 쓰러질 것입니다! 하나씩 하나씩... 적들은 파멸할 것입니다!', `MaleText_loc4`='一个接一个……我们的敌人都将消亡！一个接一个，他们都将走向毁灭！', `MaleText_loc5`='一個接著一個...我們的敵人將會蒸發!一個接著一個...他們會被摧毀!', `MaleText_loc7`='Uno por uno... ¡Nuestros enemigos caerán! Uno por uno... ¡Todos serán destruidos!', `FemaleText_loc1`='하나씩 하나씩... 적들은 쓰러질 것입니다! 하나씩 하나씩... 적들은 파멸할 것입니다!', `FemaleText_loc4`='一个接一个……我们的敌人都将消亡！一个接一个，他们都将走向毁灭！', `FemaleText_loc5`='一個接著一個...我們的敵人將會蒸發!一個接著一個...他們會被摧毀!', `FemaleText_loc7`='Uno por uno... ¡Nuestros enemigos caerán! Uno por uno... ¡Todos serán destruidos!' WHERE `ID`=40152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복은 없을 것입니다! 후퇴도 없을 것입니다! 자비도 없을 것입니다!', `MaleText_loc4`='不接受投降！不放过一个！！不留活口！！！', `MaleText_loc5`='沒人准許投降!沒人得以逃脫!沒人可以獲得饒恕!', `MaleText_loc7`='¡No habrá rendición! ¡No habrá huida! ¡No habrá cuartel!', `FemaleText_loc1`='항복은 없을 것입니다! 후퇴도 없을 것입니다! 자비도 없을 것입니다!', `FemaleText_loc4`='不接受投降！不放过一个！！不留活口！！！', `FemaleText_loc5`='沒人准許投降!沒人得以逃脫!沒人可以獲得饒恕!', `FemaleText_loc7`='¡No habrá rendición! ¡No habrá huida! ¡No habrá cuartel!' WHERE `ID`=40153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 가끔씩 자신에게 물어보아야 합니다. "이게 가치있는 일인가?" 답은 간단합니다. "고통은 감수하는 것이 아니라 축복이라고!"', `MaleText_loc4`='有时候，你不得不问自己：“这样做值得吗？”而答案很简单：“痛苦不是代价，而是奖赏！”', `MaleText_loc5`='有些人會問自己:「這是否值得?」答案非常簡單:「痛苦不是代價，而是獎勵!」', `MaleText_loc7`='¡Y a veces debéis haceros la siguiente pregunta: "¿Merece la pena?" Y la respuesta es bien simple: "El dolor no es el precio, sino la recompensa!', `FemaleText_loc1`='우리는 가끔씩 자신에게 물어보아야 합니다. "이게 가치있는 일인가?" 답은 간단합니다. "고통은 감수하는 것이 아니라 축복이라고!"', `FemaleText_loc4`='有时候，你不得不问自己：“这样做值得吗？”而答案很简单：“痛苦不是代价，而是奖赏！”', `FemaleText_loc5`='有些人會問自己:「這是否值得?」答案非常簡單:「痛苦不是代價，而是獎勵!」', `FemaleText_loc7`='¡Y a veces debéis haceros la siguiente pregunta: "¿Merece la pena?" Y la respuesta es bien simple: "El dolor no es el precio, sino la recompensa!' WHERE `ID`=40154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프타 나핫! 이마탄! 샤룹 나합! 샤룹 나합, 내 친구여!', `MaleText_loc4`='F''tagh nah''hat！I''mmathan！Sha''lub nahab！Sha''lub nahab，我的朋友！', `MaleText_loc5`='F''tagh nah''hat!  I''mmathan!  Sha''lub nahab!  Sha''lub nahab，我的朋友們!', `MaleText_loc7`='¡F''tagh nah''hat! I''mmathan! ¡Sha''lub nahab! ¡Sha''lub nahab, amigos míos!', `FemaleText_loc1`='프타 나핫! 이마탄! 샤룹 나합! 샤룹 나합, 내 친구여!', `FemaleText_loc4`='F''tagh nah''hat！I''mmathan！Sha''lub nahab！Sha''lub nahab，我的朋友！', `FemaleText_loc5`='F''tagh nah''hat!  I''mmathan!  Sha''lub nahab!  Sha''lub nahab，我的朋友們!', `FemaleText_loc7`='¡F''tagh nah''hat! I''mmathan! ¡Sha''lub nahab! ¡Sha''lub nahab, amigos míos!' WHERE `ID`=40155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 여러분은 보상받을 것입니다! 만약 여러분이 전쟁터에서 죽더라도, 그 죽음은 가치 있는 것이 됩니다! 그분이 부활하시면 여러분은 그분의 곁에 서게 될 것입니다! 그분의 영광과 함께하게 될 것입니다!', `MaleText_loc4`='你将得到奖励！如果你在战场上倒下，你的死亡也将彪炳史册！当他再次在世间崛起的时候，你将站立在他身边！你将分享他的荣耀！', `MaleText_loc5`='你將獲得獎勵!如果你死於戰場，那會是個英勇聖潔的死亡方式!在「他」掘起之時，你將屬於他那一方!你也將會分享他的榮耀!', `MaleText_loc7`='¡Seréis recompensados! ¡Si caéis en la batalla, tendréis una muerte virtuosa! ¡Cuando ÉL se alce de nuevo, estaréis a SU lado! ¡Compartiréis SU gloria!', `FemaleText_loc1`='그리고 여러분은 보상받을 것입니다! 만약 여러분이 전쟁터에서 죽더라도, 그 죽음은 가치 있는 것이 됩니다! 그분이 부활하시면 여러분은 그분의 곁에 서게 될 것입니다! 그분의 영광과 함께하게 될 것입니다!', `FemaleText_loc4`='你将得到奖励！如果你在战场上倒下，你的死亡也将彪炳史册！当他再次在世间崛起的时候，你将站立在他身边！你将分享他的荣耀！', `FemaleText_loc5`='你將獲得獎勵!如果你死於戰場，那會是個英勇聖潔的死亡方式!在「他」掘起之時，你將屬於他那一方!你也將會分享他的榮耀!', `FemaleText_loc7`='¡Y seréis recompensados! ¡Si caéis en la batalla, tendréis una muerte virtuosa! ¡Cuando ÉL se alce de nuevo, estaréis a SU lado! ¡Compartiréis SU gloria!' WHERE `ID`=40156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망은 없습니다! 모든 희망을 버리는 것만이 희망입니다. 그렇습니다, 형제자매여. 희망을 버려야만 진정한 희망을 얻을 수 있습니다!', `MaleText_loc4`='已经没有希望了！但兄弟姐妹们，只有当我们失去一切希望的时候，真正的希望才会显现！', `MaleText_loc5`='沒任何希望了!喪失所有希望後新的希望才會誕生。是的，兄弟和姐妹們，只有絕望才能帶給我們真正的希望!', `MaleText_loc7`='¡Y no hay esperanza! ¡No hay esperanza salvo en la pérdida total de esperanza. Así es, hermanos y hermanas. ¡Tan solo la desesperanza puede otorgarnos esperanza!', `FemaleText_loc1`='희망은 없습니다! 모든 희망을 버리는 것만이 희망입니다. 그렇습니다, 형제자매여. 희망을 버려야만 진정한 희망을 얻을 수 있습니다!', `FemaleText_loc4`='已经没有希望了！但兄弟姐妹们，只有当我们失去一切希望的时候，真正的希望才会显现！', `FemaleText_loc5`='沒任何希望了!喪失所有希望後新的希望才會誕生。是的，兄弟和姐妹們，只有絕望才能帶給我們真正的希望!', `FemaleText_loc7`='¡Y no hay esperanza! ¡No hay esperanza salvo en la pérdida total de esperanza. Así es, hermanos y hermanas. ¡Tan solo la desesperanza puede otorgarnos esperanza!' WHERE `ID`=40157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 친애하는 수습생 여러분. 내 적의 적의 친구는... 그러니까 내 친구의 적입니다. 아, 그러므로... 그 역시 파멸할 것입니다!', `MaleText_loc4`='是的，我的新兵小伙子们。我敌人的敌人的朋友……嗯他也是我朋友的敌人。啊对……他也得死！', `MaleText_loc5`='沒錯，我的新教徒們。我的敵人的敵人的朋友...便是我的朋友的敵人。是的...他將會消失於世!', `MaleText_loc7`='Sí, mis camaradas iniciados. El amigo de mi enemigo es mi enemigo... Bueno, también es el enemigo de mi amigo. Y sí... ¡él también caerá!', `FemaleText_loc1`='그렇습니다, 친애하는 수습생 여러분. 내 적의 적의 친구는... 그러니까 내 친구의 적입니다. 아, 그러므로... 그 역시 파멸할 것입니다!', `FemaleText_loc4`='是的，我的新兵小伙子们。我敌人的敌人的朋友……嗯他也是我朋友的敌人。啊对……他也得死！', `FemaleText_loc5`='沒錯，我的新教徒們。我的敵人的敵人的朋友...便是我的朋友的敵人。是的...他將會消失於世!', `FemaleText_loc7`='Sí, mis camaradas iniciados. El amigo de mi enemigo es mi enemigo... Bueno, también es el enemigo de mi amigo. Y sí... ¡él también caerá!' WHERE `ID`=40158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 일련의 사건들... 조직의 다른 구성원들을 향한 증오에 가득 찬 분열 행위들. 정말 비겁하고 추했습니다. 그렇지만 어쩌면... 그건 필요한 일이었을지도 모릅니다!', `MaleText_loc4`='所有这些事件……这些充满了仇恨的，针对我们组织中其他成员的行动。的确，它们懦弱而丑陋。但也许……它们也是必需的！', `MaleText_loc5`='這些事件...組織中彼此的怨恨和勾心鬥角。這些是懦弱和醜陋的，沒錯。但是!這些也是必要的!', `MaleText_loc7`='Y esos incidentes... esos actos de odio que solo fomentan la división entre nuestros miembros. Son acciones cobardes y horribles, sí. Pero quizá... ¡fueron NECESARIAS!', `FemaleText_loc1`='그리고 일련의 사건들... 조직의 다른 구성원들을 향한 증오에 가득 찬 분열 행위들. 정말 비겁하고 추했습니다. 그렇지만 어쩌면... 그건 필요한 일이었을지도 모릅니다!', `FemaleText_loc4`='所有这些事件……这些充满了仇恨的，针对我们组织中其他成员的行动。的确，他们懦弱而丑陋。但也许……他们也是必需的！', `FemaleText_loc5`='這些事件...組織中彼此的怨恨和勾心鬥角。這些是懦弱和醜陋的，沒錯。但是!這些也是必要的!', `FemaleText_loc7`='Y esos incidentes... esos actos de odio que solo fomentan la división entre nuestros miembros. Son acciones cobardes y horribles, sí. Pero quizá... ¡fueron NECESARIAS!' WHERE `ID`=40159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 얼마나 멀리까지 왔는지 보십시오! 어제까지만 해도 우린 문명의 그늘 속에 살았습니다... 쥐새끼처럼 쫓기며 말입니다! 그렇지만 오늘은! 보십시오... 하이잘이 불타고 있습니다!!!', `MaleText_loc4`='看看我们已经走了多远！昨天我们还活在文明的阴影下……就像过街老鼠！而今天！今天……海加尔正在燃烧！', `MaleText_loc5`='看看我們經歷過了什麼!我們昨天還躲藏於陰影之中...像鼠輩般地被到處獵殺!但是今天!就在今天...海加爾山將會燃燒!!!', `MaleText_loc7`='¡Observen lo lejos que hemos llegado! Ayer vivíamos entre las sombras de la civilización... como ratas! ¡Pero hoy! Hoy... ¡HYJAL ARDE!', `FemaleText_loc1`='우리가 얼마나 멀리까지 왔는지 보십시오! 어제까지만 해도 우린 문명의 그늘 속에 살았습니다... 쥐새끼처럼 쫓기며 말입니다! 그렇지만 오늘은! 보십시오... 하이잘이 불타고 있습니다!!!', `FemaleText_loc4`='看看我们已经走了多远！昨天我们还活在文明的阴影下……就像过街老鼠！而今天！今天……海加尔正在燃烧！', `FemaleText_loc5`='看看我們經歷過了什麼!我們昨天還躲藏於陰影之中...像鼠輩般地被到處獵殺!但是今天!就在今天...海加爾山將會燃燒!!!', `FemaleText_loc7`='¡Observen lo lejos que hemos llegado! Ayer vivíamos entre las sombras de la civilización como ratas! ¡Pero hoy! Hoy... ¡HYJAL ARDE!' WHERE `ID`=40160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가는 단결을 설파할 것입니다! 하지만 그런다고 가장 취약한 사슬의 고리가 끊어지지 않을까요?', `MaleText_loc4`='总是有人鼓吹团结！难道团结就能阻止锁链中最弱的一环断开吗？', `MaleText_loc5`='有些人說道要團結!但團結便能防止一條鎖鍊從它最脆弱的地方斷開嗎?', `MaleText_loc7`='¡Algunos predicarán la unidad! Pero ¿acaso la unidad impide que una cadena se rompa por su eslabón más débil?', `FemaleText_loc1`='누군가는 단결을 설파할 것입니다! 하지만 그런다고 가장 취약한 사슬의 고리가 끊어지지 않을까요?', `FemaleText_loc4`='总是有人鼓吹团结！难道团结就能阻止锁链中最弱的一环断开吗？', `FemaleText_loc5`='有些人說道要團結!但團結便能防止一條鎖鍊從它最脆弱的地方斷開嗎?', `FemaleText_loc7`='¡Algunos predicarán la unidad! Pero ¿acaso la unidad impide que una cadena se rompa por su eslabón más débil?' WHERE `ID`=40161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋아서 이곳에 왔다고 생각하지 마십시오. 운과는 아무런 상관이 없습니다. 주인님들의 의지가 우릴 이곳으로 이끈 겁니다!', `MaleText_loc4`='别以为是运气帮了你们的忙。这和运气一点儿关系也没有。是我们主人的意志把我们带到了这里！', `MaleText_loc5`='不要以為是運氣將你帶到這。運氣跟這一點關係都沒有。是我們主人的意志將你帶到這的!', `MaleText_loc7`='No crean que ha sido la suerte la que los ha traído aquí. La suerte no ha tenido nada que ver. ¡Ha sido la VOLUNTAD DEL MAESTRO la que los ha traído aquí!', `FemaleText_loc1`='운이 좋아서 이곳에 왔다고 생각하지 마십시오. 운과는 아무런 상관이 없습니다. 주인님들의 의지가 우릴 이곳으로 이끈 겁니다!', `FemaleText_loc4`='别以为是运气帮了你们的忙。这和运气一点儿关系也没有。是我们主人的意志把我们带到了这里！', `FemaleText_loc5`='不要以為是運氣將你帶到這。運氣跟這一點關係都沒有。是我們主人的意志將你帶到這的!', `FemaleText_loc7`='No crean que ha sido la suerte la que los ha traído aquí. La suerte no ha tenido nada que ver. ¡Ha sido la VOLUNTAD DEL MAESTRO la que los ha traído aquí!' WHERE `ID`=40162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 지금 우리를 하나로 묶어 주는 상징을 바라보고 있습니다. 이 망치를 말입니다. 이 망치는 창조와 건설의 망치입니다. 하지만 이것은 파괴와 폭력의 망치이기도 합니다!', `MaleText_loc4`='我望着这个将我们凝聚在一起的象征——这把锤子。这把锤子象征着建设和创造，也象征着暴力和毁灭！', `MaleText_loc5`='我看著凝聚我們的象徵。這個神錘，就是這個神錘創造了一切，但也可以摧毀一切!', `MaleText_loc7`='He recibido la inspiración de este símbolo que nos une. Este martillo. Es el martillo que construye y que crea. ¡Pero también es el martillo que golpea y destruye!', `FemaleText_loc1`='저는 지금 우리를 하나로 묶어 주는 상징을 바라보고 있습니다. 이 망치를 말입니다. 이 망치는 창조와 건설의 망치입니다. 하지만 이것은 파괴와 폭력의 망치이기도 합니다!', `FemaleText_loc4`='我望着这个将我们凝聚在一起的象征——这把锤子。这把锤子象征着建设和创造，也象征着暴力和毁灭！', `FemaleText_loc5`='我看著凝聚我們的象徵。這個神錘，就是這個神錘創造了一切，但也可以摧毀一切!', `FemaleText_loc7`='He recibido la inspiración de este símbolo que nos une. Este martillo. Es el martillo que construye y que crea. ¡Pero también es el martillo que golpea y destruye!' WHERE `ID`=40163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 구성원들 사이에 조화를 요구하는 자들에게 저는 묻습니다. "불화가 우리 주인님들을 기쁘게 하지 않은 적이 있습니까? 피가 우리의 목마름을 채워주지 않은 적이 있습니까?"', `MaleText_loc4`='对于所有那些呼吁要在我们组织内部保持和谐的人……我要问问他们：“我们的主人喜爱一切冲突，渴望每一场战火，难道不是这样吗？”', `MaleText_loc5`='我想問我們之中的那些和平主義者:「難道無盡的爭鬥不會取悅我們的主人嗎?難到無盡的鮮血無法滿足他們的饑渴嗎?」', `MaleText_loc7`='Y a aquellos que predican la armonía entre nuestras filas... a ellos les pregunto: "¿No es cierto que a nuestros amos les complacen todos tipo de conflictos? ¿No es cierto que TODO derramamiento de sangre calma su sed?"', `FemaleText_loc1`='우리 구성원들 사이에 조화를 요구하는 자들에게 저는 묻습니다. "불화가 우리 주인님들을 기쁘게 하지 않은 적이 있습니까? 피가 우리의 목마름을 채워주지 않은 적이 있습니까?"', `FemaleText_loc4`='对于所有那些呼吁要在我们组织内部保持和谐的人……我要问问他们：“我们的主人喜爱一切冲突，渴望每一场战火，难道不是这样吗？”', `FemaleText_loc5`='我想問我們之中的那些和平主義者:「難道無盡的爭鬥不會取悅我們的主人嗎?難到無盡的鮮血無法滿足他們的饑渴嗎?」', `FemaleText_loc7`='Y a aquellos que predican la armonía entre nuestras filas... a ellos les pregunto: "¿No es cierto que a nuestros amos les complacen todos tipo de conflictos? ¿No es cierto que TODO derramamiento de sangre calma su sed?"' WHERE `ID`=40164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진 님의 부르심에 가장 먼저 달려왔습니다. 그대도 함께하시겠습니까?', `FemaleText_loc4`='我是第一批响应沃金的号召，投身军队的人之一。你愿意加入我们吗？', `FemaleText_loc5`='我會是第一批回應沃金召集令的人。你會加入我們嗎?', `FemaleText_loc7`='Yo he sío una de las primeras en reh''ponder al llamamiento de Vol''jin. ¿Vas a unih''te a nosotros?' WHERE `ID`=40165;
