UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치... 마치 공허가 내 마음을 울리는 것 같아.', `MaleText_loc4`='就像……就像虚空刚刚触摸了我的灵魂。', `MaleText_loc5`='就像...就像是虛無觸摸了我的心靈一樣。', `MaleText_loc7`='Es... Es como si el vacío hubiera tocado mi mente.', `FemaleText_loc1`='마치... 마치 공허가 내 마음을 울리는 것 같아요.', `FemaleText_loc4`='就像……就像虚空刚刚触摸了我的灵魂。', `FemaleText_loc5`='就像...就像是虛無觸摸了我的心靈一樣。', `FemaleText_loc7`='Es... Es como si el vacío hubiera tocado mi mente.' WHERE `ID`=40185;
