UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표본 채취가 중단되었습니다. 샘비노 물산에서 진심으로 사과드립니다. 편하신 때에 다시 표본 추출을 시도해 주십시오.', `MaleText_loc4`='取样中断。萨比诺制品致以诚挚的歉意。请尽快在方便的时候再次尝试取样。', `MaleText_loc5`='樣品採取中斷。山比諾產品誠摯地表示歉意。請在您方便時盡快再次嘗試樣品的採集。', `MaleText_loc7`='Extracción de muestra interrumpida. Productos Sambino ofrece sus más sinceras disculpas. Vuelve a intentar extraer una muestra cuando puedas.' WHERE `ID`=40230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 갑시다! 최종 출입 암호를 넣기만 하면 이 출입문이 작동할 거예요...', `MaleText_loc4`='好啊，我们走！只需要在门禁系统中输入最终登录序列……然后……', `MaleText_loc5`='好了，快走吧!只需要把最後的登錄程序輸入到門的機關中....然後...', `MaleText_loc7`='Bien, ¡vamos! Sólo tengo que ingresar la última secuencia en el mecanismo de la puerta... y…' WHERE `ID`=40231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 됐습니다! 제어실은 바로 이 뒤에 있을 거예요... 우와...', `MaleText_loc4`='成功了！控制室应该就在这后面……哦……喔……', `MaleText_loc5`='成功了!控制房應該就在這個後面...噢....哇....', `MaleText_loc7`='¡Funcionó! La sala de control tiene que estar detrás de est... oh... uau…' WHERE `ID`=40232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 여긴 제어실이 아니잖아! 수호 장치가 또 하나 버티고 있는 데다가, 어떻게인지는 몰라도 망할 놈의 바위 트로그가 침입했군요. 트로그라. 왜 하필이면 트로그냐고!', `MaleText_loc4`='什么？这儿不是控制室！这儿有另外一套完整的防御系统，那些该死的石头穴居人却闯入了这儿。穴居人，为什么闯进来的是穴居人！', `MaleText_loc5`='什麼?這不是控制房!這裡還有一層防衛機關在某處。那些該死的穴居怪不知怎麼闖入這的。穴居怪，怎麼又是他們!', `MaleText_loc7`='¿Qué? ¡Esto no es la sala de control! Hay otro mecanismo de defensa, y los malditos Troggs de Roca lograron entrar aquí. Troggs. ¡¿Tenían que ser Troggs?!' WHERE `ID`=40233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 잠깐 생각 좀 하죠.', `MaleText_loc4`='好吧，让我好好考虑一下。', `MaleText_loc5`='好吧，讓我思考一下。', `MaleText_loc7`='A ver, déjenme pensar.' WHERE `ID`=40234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 정령이 네 단에 있고...', `MaleText_loc4`='四个平台，各有一个巨大的元素。', `MaleText_loc5`='擁有巨大元素的四個平台。', `MaleText_loc7`='Cuatro plataformas con elementales enormes.' WHERE `ID`=40235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다! 이 방을 설명하는 서판을 본 적이 있어요. 여긴 빛의 전당입니다! 좋아요. 이제 간단합니다. 모험가 여러분이 정령 넷을 처치하면 저 끝에 있는 문의 개폐 장치가 작동할 겁니다!', `MaleText_loc4`='我明白了！我读过的一块石板上提到了这个房间。这里就是光明穹顶！好吧，这很简单。冒险者们，去干掉那四个元素，触发远处那道门的开启程序！', `MaleText_loc5`='我想到了!一塊石板上提到過這個房間。這裡是聖光地窖!好吧，這很簡單。探險者們，我需要你們打敗那四個元素來觸發遠處那道門的開啟程序。', `MaleText_loc7`='¡Ya sé! Vi una tableta que mencionaba esta cámara. ¡Es el Arca de las Luces! Bien, es simple. ¡Ustedes deben derrotar a los cuatro elementales para activar la secuencia de apertura de aquella puerta!' WHERE `ID`=40236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 정령 넷을 처치하면 문이 열릴 겁니다. 확실해요. 트로그를 조심하세요. 더럽고 짜증 나는 족속입니다. ''육체의 저주''에 굴복하지 않았대도 말이죠.', `MaleText_loc4`='是的，只要毁了四种元素，门就会打开。我确定。不过要小心那些穴居人。那些脾气乖戾、又臭又脏的生物——尽管他们还没屈服于血肉诅咒。', `MaleText_loc5`='對，摧毀四個元素，門便會開啟，這我很確定。只要小心穴居怪就好了，他們脾氣很糟，是噁心的生物，就算他們沒受到血肉詛咒也是這樣。', `MaleText_loc7`='Sí, destruye a los cuatro elementales y la puerta se abrirá. Estoy seguro. Pero ten cuidado con los troggs; son criaturas iracundas y repugnantes, aunque no hayan sucumbido ante la maldición de la carne.' WHERE `ID`=40237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 어떨지 잘 모르겠지만, 친구. 난 물속에선 숨을 못 쉬겠어.', `MaleText_loc4`='我不知道你怎么样，老兄，可我不能在水下呼吸。', `MaleText_loc5`='老兄，你我是不知道，但我無法在水中呼吸。', `MaleText_loc7`='No sé tú, colega, pero yo no puedo respirar bajo el agua.' WHERE `ID`=40238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_mace_15.blp:20|t%s|1이;가; |cFFFF0000철퇴|r를 들고 |cFFFF0000|Hspell:75007|h[장애]|h|r 상태가 됩니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_mace_15.blp:20|t%s装备好了他的|cFFFF0000战锤|r并且受到了|cFFFF0000|Hspell:75007|h[重若千钧]|h|r效果！', `MaleText_loc5`='|TInterface\\Icons\\inv_mace_15.blp:20|t%s裝備他的|cFFFF0000錘子|r可獲得|cFFFF0000|Hspell:75007|h[負重]的效果|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_mace_15.blp:20|t¡%s equipa su |cFFFF0000maza|r y está |cFFFF0000|Hspell:75007|h[Sobrecargado]|h|r!' WHERE `ID`=40239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거울이 구석구석을 비추고 있고...', `MaleText_loc4`='镜子指向各个位置。', `MaleText_loc5`='四面八方的鏡子。', `MaleText_loc7`='Espejos apuntando a todos lados.' WHERE `ID`=40240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 자신을 증명할 수 있는 건 제 발톱뿐이에요!', `FemaleText_loc4`='我在此需要用来证明自己的，就是我的爪子！', `FemaleText_loc5`='我需要做的就是證明這是我的爪子!', `FemaleText_loc7`='¡Para mostrar mi valía solo necesito mis garras!' WHERE `ID`=40241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 모자는 뭐죠?', `MaleText_loc4`='那帽子怎么了？', `MaleText_loc5`='帽子怎麼了?', `MaleText_loc7`='¿Y ese casco?', `FemaleText_loc1`='그 모자는 뭐죠?', `FemaleText_loc4`='那帽子怎么了？', `FemaleText_loc5`='帽子怎麼了?', `FemaleText_loc7`='¿Y ese casco?' WHERE `ID`=40242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 대지 고리회잖아요. 다른 대지 고리회 사람들처럼 수중 호흡 마법을 쓸 수 있으실 텐데요.', `MaleText_loc4`='你与大地之环同在，我刚刚想到你应该和他们一样，获得水下呼吸的法术效果。', `MaleText_loc5`='你與陶土議會是一伙的，我想你應該和他們一樣擁有可在水中呼吸的法術。', `MaleText_loc7`='Estás con El Anillo de la Tierra... He dado por sentado que tendrías un hechizo para respirar bajo el agua, como todos los demás.', `FemaleText_loc1`='당신은 대지 고리회잖아요. 다른 대지 고리회 사람들처럼 수중 호흡 마법을 쓸 수 있으실 텐데요.', `FemaleText_loc4`='你与大地之环同在，我刚刚想到你应该和他们一样，获得水下呼吸的法术效果。', `FemaleText_loc5`='你與陶土議會是一伙的，我想你應該和他們一樣擁有可在水中呼吸的法術。', `FemaleText_loc7`='Estás con El Anillo de la Tierra... He dado por sentado que tendrías un hechizo para respirar bajo el agua, como todos los demás.' WHERE `ID`=40243;
