UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 끝내주는 주문 제작 보호모를 벗으라고? 말도 안 되지.', `MaleText_loc4`='然后放弃我帅气的特制潜水头盔？没门。', `MaleText_loc5`='然後錯過能戴著我那量身打造的超酷頭盔的機會?不可能。', `MaleText_loc7`='¿Y perderme la ocasión de ponerme mi maravilloso casco personalizado? Ni hablar.' WHERE `ID`=40245;
