UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 적인지 알려만 주십시오!', `MaleText_loc4`='指引我杀敌！', `MaleText_loc5`='只要為我指出敵人是誰!', `MaleText_loc7`='¡Tú solo señálame al enemigo!', `FemaleText_loc1`='누가 적인지 알려만 주세요!', `FemaleText_loc4`='指引我杀敌！', `FemaleText_loc5`='只要為我指出敵人是誰!', `FemaleText_loc7`='¡Tú solo señálame al enemigo!' WHERE `ID`=40253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됩니다. 욕심 그만 부리십시오.', `MaleText_loc4`='不。别再贪心了。', `MaleText_loc5`='不，別那麼貪心。', `MaleText_loc7`='No, deja de pedir tanto.', `FemaleText_loc1`='안 됩니다. 욕심 그만 부리십시오.', `FemaleText_loc4`='不。别再贪心了。', `FemaleText_loc5`='不，別那麼貪心。', `FemaleText_loc7`='No, deja de pedir tanto.' WHERE `ID`=40254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 곧 유행이라고, 친구! 정령을 이용한 첨단 기술이지. 잃어버린 지식과 새로운 자원을 찾아 아제로스 깊숙이까지 탐험하는 멋쟁이!$b$b샘비노를 기억하라고.', `MaleText_loc4`='我就是尖端技术的代表，宝贝儿！灌注元素能量的高科技。到艾泽拉斯海洋的最深处去探求失落的学识与新的资源吧。$B$B请牢记我的名字。', `MaleText_loc5`='我創造了最新的突破，寶貝!元素灌輸科技。探索艾澤拉斯最深層已被遺忘的知識和新的資源。$B$B記住這個名字。', `MaleText_loc7`='¡Estoy en la cresta de la ola, colega! Tecnología imbuida con los elementos. Explorando las profundidades de Azeroth en busca de conocimientos perdidos y nuevos recursos.$b$bAcuérdate de mi nombre.' WHERE `ID`=40255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='견뎌야 한다...', `MaleText_loc4`='必须——抵抗……', `MaleText_loc5`='必須...抗拒...', `MaleText_loc7`='Debo ressissstir...' WHERE `ID`=40256;
