UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌가죽 토템을 주시겠습니까?', `MaleText_loc4`='我能换一个石肤图腾吗？', `MaleText_loc5`='我可以要一根石甲圖騰嗎?', `MaleText_loc7`='¿Puedes darme un tótem Piel de piedra?', `FemaleText_loc1`='돌가죽 토템을 주시겠어요?', `FemaleText_loc4`='我能换一个石肤图腾吗？', `FemaleText_loc5`='我可以要一根石甲圖騰嗎?', `FemaleText_loc7`='¿Puedes darme un tótem Piel de piedra?' WHERE `ID`=40264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동물들을 돌보고 훈련하려면 많은 일을 해야 하지만, 그만한 가치가 있지요.$B$B그렇지만 도움의 손길이라면야 언제든지 받을 수 있답니다.', `FemaleText_loc4`='我们花费了大量精力训练和照料我们的动物们，但这一切都是值得的。$B$B尽管如此，有额外的帮手总是好的。', `FemaleText_loc5`='大部份的工作是要訓練和照顧我們的動物，但這都是值得的。$B$B而我也總是樂意接受一些額外的協助。', `FemaleText_loc7`='Pasamos gran parte de nuestro trabajo entrenando y cuidando nuestros animales, pero merece la pena.$b$bDe todas formas, siempre me viene bien un poco de ayuda.' WHERE `ID`=40265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬링키, 새로운 떡대 위장복이 필요합니다!', `MaleText_loc4`='史莉琪，我需要一件新的巨怪伪装服！', `MaleText_loc5`='史琳琪，我需要新的蠢蛋偽裝!', `MaleText_loc7`='¡Finta, necesito un nuevo disfraz de cateto!', `FemaleText_loc1`='슬링키, 새로운 떡대 위장복이 필요해요!', `FemaleText_loc4`='史莉琪，我需要一件新的巨怪伪装服！', `FemaleText_loc5`='史琳琪，我需要新的蠢蛋偽裝!', `FemaleText_loc7`='¡Finta, necesito un nuevo disfraz de cateto!' WHERE `ID`=40266;
