UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 잡았고!', `MaleText_loc4`='干掉一个！', `MaleText_loc5`='搞定一個!', `MaleText_loc7`='¡Uno menos!' WHERE `ID`=40270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 하나 잡았군요! 광선 좀 보세요! 저 끝에 있는 문에 연결된 것 같습니다!', `MaleText_loc4`='又干掉了一个！快看这些明亮的光柱！他们似乎和远处那道门是相互关联的！', `MaleText_loc5`='第二個也搞定了!看看那些光線!它們看來與那道門是連在一起的!', `MaleText_loc7`='¡Otro que cae! ¡Miren esos rayos de luz! ¡Están conectándose con la puerta!' WHERE `ID`=40271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나만 더 잡으면 됩니다! 문이 거의 열렸어요!', `MaleText_loc4`='只剩一个元素了！大门就要被打开了！', `MaleText_loc5`='剩下最後一個!門就快要打開了!', `MaleText_loc7`='¡Sólo falta un elemental! ¡La puerta casi se abre!' WHERE `ID`=40272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 해냈군요! 전당 문이 열리고 있습니다. 이제... 허? 아이고...', `MaleText_loc4`='你成功了！穹顶的大门被打开了！现在就能……哦，不！', `MaleText_loc5`='好了，你們辦到了!地窖的門已經打開!現在我們可以...噢...不!', `MaleText_loc7`='¡Ya está, lo lograron! ¡La puerta del arca se abre! Ya podemos... ¡no!' WHERE `ID`=40273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 미안해... 내 토템이 당신의 민감한 신경을 건드렸나? 좋아. 자, 이제 일을 하라고!', `MaleText_loc4`='喔抱歉……我的图腾冒犯到脆弱敏感的你了？好吧。看这儿。现在回去干活！', `MaleText_loc5`='噢，抱歉...我的圖騰傷害了你那樂觀的心情嗎?好吧，這給你。現在快給我回去工作!', `MaleText_loc7`='Ah, lo siento, ¿mi tótem ha herido tu delicada sensibilidad? Vale, toma. ¡Ahora a trabajar!', `FemaleText_loc1`='아, 미안해... 내 토템이 당신의 민감한 신경을 건드렸나? 좋아. 자, 이제 일을 하라고!', `FemaleText_loc4`='喔抱歉……我的图腾冒犯到脆弱敏感的你了？好吧。看这儿。现在回去干活！', `FemaleText_loc5`='噢，抱歉...我的圖騰傷害了你那樂觀的心情嗎?好吧，這給你。現在快給我回去工作!', `FemaleText_loc7`='Ah, lo siento, ¿mi tótem ha herido tu delicada sensibilidad? Vale, toma. ¡Ahora a trabajar!' WHERE `ID`=40274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이익... 네가 그러고 있는 동안 펠리스에게서 전달 사항이나 듣고 있으란 말이야? 자, 받아. 가서 표본을 채취해 오라고!', `MaleText_loc4`='天哪……你干活时需要让我派菲利斯给你做个全身按摩吗？这儿，拿去。快去找我要的样本！', `MaleText_loc5`='天啊...你是要我叫菲利斯給你做個馬殺雞嗎?拿去，去把我的樣品拿給我!', `MaleText_loc7`='Vaya... Ya que estamos, ¿quieres que le pida a Felice que te dé un masaje? Venga, cógelo. ¡Tráeme mi muestra!', `FemaleText_loc1`='네가 그러고 있는 동안 펠리스에게서 전달 사항이나 듣고 있으란 말이야? 자, 받아. 가서 표본을 채취해 오라고!', `FemaleText_loc4`='天哪……你干活时需要让我派菲利斯给你做个全身按摩吗？这儿，拿去。快去找我要的样本！', `FemaleText_loc5`='天啊...你是要我叫菲利斯給你做個馬殺雞嗎?拿去，去把我的樣品拿給我!', `FemaleText_loc7`='Vaya... Ya que estamos, ¿quieres que le pida a Felice que te dé un masaje? Venga, cógelo. ¡Tráeme mi muestra!' WHERE `ID`=40275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만... 누가 누굴 위해 여기 있는 거지? 내가 새 토템을 주면, 그 망할 일을 끝낼 수 있겠어?', `MaleText_loc4`='等一下……究竟是谁在替谁做事？要是我给你新的图腾，你能快点儿把那该死的任务完成吗？！', `MaleText_loc5`='等一下...現在是誰在為誰做事?我如果把新的圖騰給你，你可以把這該死的工作完成嗎?', `MaleText_loc7`='Espera un segundo... ¿Quién se supone que está trabajando para quién? Si te doy un tótem nuevo, ¿terminarás la misión de una vez?', `FemaleText_loc1`='잠깐만... 누가 누굴 위해 여기 있는 거지? 내가 새 토템을 주면, 그 망할 일을 끝낼 수 있겠어?', `FemaleText_loc4`='等一下……究竟是谁在替谁做事？要是我给你新的图腾，你能快点儿把那该死的任务完成吗？！', `FemaleText_loc5`='等一下...現在是誰在為誰做事?我如果把新的圖騰給你，你可以把這該死的工作完成嗎?', `FemaleText_loc7`='Espera un segundo... ¿Quién se supone que está trabajando para quién? Si te doy un tótem nuevo, ¿terminarás la misión de una vez?' WHERE `ID`=40276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유닛은 정상적인 작동 규약 밖에서 활성화되었습니다. 새로운 작동 매개 변수를 내려받습니다. 내려받기 완료. 유닛 자가 방어 절차가 완전히 활성화되었습니다. 시스템 내 외부 유닛 파괴를 지금 시작합니다.', `MaleText_loc4`='此单位已经激活，脱离正常操作程序。正在下载新的操作参数。下载完成。单位完全自我防卫程序现在已被激活。对进入系统的外部单位进行清除，相关程序即将开始。', `MaleText_loc5`='單位特殊運作系統已啟動。新的運作參數下載中。下載完畢。單位自我防衛系統已完全啟動。消滅入侵單位的行為程序開始。', `MaleText_loc7`='Unidad activada fuera de los protocolos de operación normales. Descargando parámetros nuevos. Descarga completa. Rutinas de autodefensa activadas. Comenzando la destrucción de unidades extrañas al sistema.' WHERE `ID`=40277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무역왕의 배가 곧 출항할 거예요. 모두 항구로 가세요! 열쇠 이리 주세요. 운전은 제가 맡을게요. 떠날 준비가 되면 말씀만 하세요.', `FemaleText_loc4`='贸易大王的游艇就要扬帆起航了。所有人都到码头上去！把钥匙给我，老板。我来驾驶。做好出发准备以后就通知我一声。', `FemaleText_loc5`='貿易親王的遊艇馬上就要出海了。全部人到碼頭那集合!把鑰匙給我，老大，我來駕駛。準備好後讓我知道就行了。', `FemaleText_loc7`='El yate del Príncipe mercante está a punto de zarpar. ¡Todos a los muelles! Dame las llaves $gjefe:jefa;. Conduzco yo. Tú solo infórmame cuando quieras zarpar.' WHERE `ID`=40278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 온 트롤입니다!', `MaleText_loc4`='新巨魔报道！', `MaleText_loc5`='新人報到!', `MaleText_loc7`='¡Aquí tienes otro trol!', `FemaleText_loc1`='새로 온 트롤이에요!', `FemaleText_loc4`='新巨魔报道！', `FemaleText_loc5`='新人報到!', `FemaleText_loc7`='¡Aquí tienes otro trol!' WHERE `ID`=40279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 보고합니다.', `MaleText_loc4`='报告工作。', `MaleText_loc5`='報到。', `MaleText_loc7`='Me presento al se''vicio.', `FemaleText_loc1`='임무를 보고합니다.', `FemaleText_loc4`='报告工作。', `FemaleText_loc5`='報到。', `FemaleText_loc7`='Me presento al se''vicio.' WHERE `ID`=40280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인과 싸울 준비가 되었습니다.', `MaleText_loc4`='准备开始对扎拉赞恩的战斗。', `MaleText_loc5`='準備和札拉贊恩交戰。', `MaleText_loc7`='Lih''to para luchar contra Zalazane.', `FemaleText_loc1`='잘라제인과 싸울 준비가 되었어요.', `FemaleText_loc4`='准备开始对扎拉赞恩的战斗。', `FemaleText_loc5`='準備和札拉贊恩交戰。', `FemaleText_loc7`='Lih''ta para luchar contra Zalazane.' WHERE `ID`=40281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님 곁에서 싸울 준비가 되었습니다!', `MaleText_loc4`='准备同沃金并肩作战！', `MaleText_loc5`='準備和沃金一起並肩作戰!', `MaleText_loc7`='¡Preparao para luchar al lao de Vol''jin!', `FemaleText_loc1`='볼진 님 곁에서 싸울 준비가 되었어요!', `FemaleText_loc4`='准备同沃金并肩作战！', `FemaleText_loc5`='準備和沃金一起並肩作戰!', `FemaleText_loc7`='¡Preparao para luchar al lao de Vol''jin!' WHERE `ID`=40282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련은 언제 시작합니까?', `MaleText_loc4`='训练什么时候开始？', `MaleText_loc5`='訓練何時開始?', `MaleText_loc7`='¿Cuándo empieza el ent''enamiento?', `FemaleText_loc1`='훈련은 언제 시작하나요?', `FemaleText_loc4`='训练什么时候开始？', `FemaleText_loc5`='訓練何時開始?', `FemaleText_loc7`='¿Cuándo empieza el ent''enamiento?' WHERE `ID`=40283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 와 줘서 고맙습니다, 친구여!$B$B야생동물들이 불길을 피해 이 숲까지 왔습니다. 이제 더는 도망갈 곳이 없습니다. 살아남은 동물들을 보호해야 합니다!', `MaleText_loc4`='你在这儿真是太好了，朋友！$B$B那些野生动物不得不逃到这片树林里来躲避烈火。它们已经无处可去了。我们必须保护幸存者！', `MaleText_loc5`='很高興你在這，朋友!$B$B火焰讓那些野生動物在這個森林尋求庇護，他們已經跑不動了，我們必須保護生存者!', `MaleText_loc7`='¡Me alegro de que estés aquí, $gamigo:amiga;!$b$bLos incendios han obligado a la fauna a refugiarse en esta arboleda. No pueden huir más lejos. ¡Debemos proteger a los supervivientes!' WHERE `ID`=40284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤로 물러서십시오!', `MaleText_loc4`='后退！', `MaleText_loc5`='後退!', `MaleText_loc7`='¡Atrás!' WHERE `ID`=40285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 옵니다! 물러서십시오!', `MaleText_loc4`='它来了，退后！', `MaleText_loc5`='要來了，後退!', `MaleText_loc7`='¡Aquí viene, atrás!' WHERE `ID`=40286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이 가라앉을 때까지 그에게서 떨어지십시오!', `MaleText_loc4`='在火熄灭前，别靠近他！', `MaleText_loc5`='在火熄滅前離他遠點!', `MaleText_loc7`='¡Aléjate de él hasta que el fuego disminuya!' WHERE `ID`=40287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 믿으시는 샨드리스 님을 실망시키지 않을 거예요.', `FemaleText_loc4`='珊蒂斯女士正指望我呢。我不会让她失望的。', `FemaleText_loc5`='珊蒂斯女士信任我，我絕不會讓她失望。', `FemaleText_loc7`='Lady Shandris cuenta conmigo. No la defraudaré.' WHERE `ID`=40288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데, 소문을 듣자니 당신이 무역왕 자리를 노린다던데.$B$B사실이야? 진짜야?', `MaleText_loc4`='嘿，$g老兄:小姐;！听说你对贸易大王的职位有兴趣。$B$B是真的吗？', `MaleText_loc5`='喂!聽說你想要搶貿易親王的飯碗。$B$B是真的嗎?', `MaleText_loc7`='¡Oye, $gcompadre:comadre;! Se rumorea que quieres el puesto del príncipe mercante.$b$b¿Es cierto?' WHERE `ID`=40289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<웅얼거리는 고버. 말을 할 수 있는지도 의심이 갑니다.>', `MaleText_loc4`='<大胖哼哼着。你甚至无法确定他是否真的会说话。>', `MaleText_loc5`='<古柏大多在咕噥，你根本不確定他是否會說話。>', `MaleText_loc7`='<Gargajo suelta gruñidos. Ni siquiera estás $gseguro:segura; de que pueda hablar.>' WHERE `ID`=40290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 친구. 애인이 있다는 말이 정말인가요?', `FemaleText_loc4`='嘿你好啊，宝贝儿！你和$g小甜甜:奇普;的传闻是怎么回事？', `FemaleText_loc5`='嘿，$g寶貝:帥哥;!你跟那$g小妞:小子;的傳聞是怎麼一回事啊?', `FemaleText_loc7`='¡Hola, cielo! ¿Qué es eso que he oído sobre $gCara:Locko; y tú?' WHERE `ID`=40291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에 마지막으로 남은 카자마이트를 캐기에 좋은 날입니다. 안 그런가요, $n 님?', `FemaleText_loc4`='今天可真是个好日子，正适合开挖这世上仅存的卡亚矿石，你不这样认为吗，$n？', `FemaleText_loc5`='今天真是將世界上最後一批卡迦邁礦挖走的好日子，你說對吧，$n?', `FemaleText_loc7`='Qué buen día para excavar los últimos depósitos conocidos de kaja''mita del mundo, ¿verdad, $n?' WHERE `ID`=40292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이상하지 않나요? 수천 년 전에 우리를 영리하게 만들어줬던 카자마이트가 트롤들에게는 아무런 효과가 없다는 사실이요.', `FemaleText_loc4`='卡亚矿石在几千年前把我们变得非常聪明，现在却对我们这些巨魔产生不了任何效果，这不奇怪吗？', `FemaleText_loc5`='你不覺得很奇怪嗎?卡迦邁礦在幾千年前讓我們變聰明，但是對我們的食人妖奴隸卻毫無影響。', `FemaleText_loc7`='¿No te parece curioso que la kaja''mita nos hiciera listos hace miles de años, pero no parezca surtir efecto alguno sobre nuestros trols?' WHERE `ID`=40293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='카자마이트에서 카자콜라를 증류하는 걸 생각해 내다니! 당신 정말 천재임에 틀림이 없어요, $n 님! 무역왕 자리는 당신 차지가 될 거예요. 지금 무역왕은 걱정 좀 되겠네요!', `FemaleText_loc4`='能想到用卡亚矿石蒸馏出卡亚可乐，你可真是个天才啊，$n。贸易大王这下要担心你要抢他的位子了！', `FemaleText_loc5`='由卡迦邁提煉出卡迦可樂是個無比天才的壯舉，$n。貿易親王看來是該擔心你會搶走他的頭銜了!', `FemaleText_loc7`='Destilar Kaja''Cola de la kaja''mita fue un golpe de puro genio por tu parte, $n. ¡El Príncipe mercante estará preocupado de que le vayas a quitar el título!' WHERE `ID`=40294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부두의 힘을 보아라... 살아서는 이 섬을 떠날 수 없으리라!', `MaleText_loc4`='看看我的魔法力量吧……别想活着离开这座岛屿！', `MaleText_loc5`='見識我的巫毒力量吧...誰都別想活著離開!', `MaleText_loc7`='Contempla el poder de mi vudú... ¡no saldrán de esta isla CON VIDA!' WHERE `ID`=40295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칩의 뻔뻔한 얼굴에 주먹을 한 방 날려주고 싶어! 캔디의 달콤한 입술에는 뽀뽀를 한 방 날려주고 싶고!', `MaleText_loc4`='我可真想一拳打在奇普的脸上！我还想一口亲在小甜甜的脸上！', `MaleText_loc5`='我真想揍那小子一拳!我同時也想親那小妞一下!', `MaleText_loc7`='¡Me dan ganas de sacudirle a ese tal Locko en todo el morro! ¡También me dan ganas de besarle a esa tal Cara en todo el morro!' WHERE `ID`=40296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 파티라고 했나?', `MaleText_loc4`='哈，有人在说“聚会”?', `MaleText_loc5`='有人提到派對嗎?', `MaleText_loc7`='¿Alguien ha dicho "fiesta"?' WHERE `ID`=40297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자콜라 때문에 자꾸 이런저런 생각이 떠오른다고. 아이디어를 내놓는 경연 대회를 여는 건 어떨까?', `MaleText_loc4`='这瓶叫做卡亚可乐的玩意儿让我想法不断。我们真需要竞赛来获取灵感吗？', `MaleText_loc5`='卡迦可樂一事讓我想了一下。我們難道真的希望競爭能有更多靈感嗎?', `MaleText_loc7`='Esto de la Kaja''Cola me ha hecho pensar. ¿Seguro que nos interesa tener competencia a la hora de idear cosas?' WHERE `ID`=40298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자마이트의 정수를 증류해내면 고블린들이 좋은 발상을 할 수 있게 해주는 달콤한 탄산음료를 만들 수 있답니다. 거기, 잠시만요...', `MaleText_loc4`='从卡亚矿石里蒸馏出的汁水能做成可口的碳酸饮料，让人的脑袋里充满灵感！嘿，等一下……', `MaleText_loc5`='用卡迦邁提煉出的濃縮汁做成美味的碳酸飲料，刺激人們的靈感!喂，等一下...', `MaleText_loc7`='¡Destilar el jugo de la kaja''mita para crear una bebida deliciosa y con gas que da IDEAS a la gente! Espera un segundo...', `FemaleText_loc1`='카자마이트의 정수를 증류해내면 고블린들이 좋은 발상을 할 수 있게 해주는 달콤한 탄산음료를 만들 수 있답니다. 거기, 잠시만요...', `FemaleText_loc4`='从卡亚矿石里蒸馏出的汁水能做成可口的碳酸饮料，让人的脑袋里充满灵感！嘿，等一下……', `FemaleText_loc5`='用卡迦邁提煉出的濃縮汁做成美味的碳酸飲料，刺激人們的靈感!喂，等一下...', `FemaleText_loc7`='¡Destilar el jugo de la kaja''mita para crear una bebida deliciosa y con gas que da IDEAS a la gente! Espera un segundo...' WHERE `ID`=40299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 악당 찾아낸다! 따라와!', `MaleText_loc4`='我们找到坏人了！快跟上！', `MaleText_loc5`='我們找到邪惡的了!跟隨!', `MaleText_loc7`='¡Nosotros encontrar a los malos! ¡Seguir!' WHERE `ID`=40300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽에 숨어 있다! 서둘러!', `MaleText_loc4`='他们逃去这边了！赶快！', `MaleText_loc5`='他們躲在這!快!', `MaleText_loc7`='¡Ellos esconderse por aquí! ¡Rápido!' WHERE `ID`=40301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 악당 찾는 거다, 맞지?', `MaleText_loc4`='我们在找坏人，是吧？', `MaleText_loc5`='我們要找的是邪惡的那些，對吧?', `MaleText_loc7`='Nosotros ahora buscar a los malos, ¿sí?' WHERE `ID`=40302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이야! 놈들을 잡아!', `MaleText_loc4`='在这边！你必须阻止他们！', `MaleText_loc5`='在這裡!你必須阻止他們!', `MaleText_loc7`='¡Por aquí! ¡Debes detenerlos!' WHERE `ID`=40303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 싸워야 해, $n!', `MaleText_loc4`='你现在必须战斗，$n！', `MaleText_loc5`='你現在必須戰鬥，$n!', `MaleText_loc7`='¡Ahora debes luchar, $n!' WHERE `ID`=40304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이야, $n!', `MaleText_loc4`='来这边，$n！', `MaleText_loc5`='在這裡，$n!', `MaleText_loc7`='¡Por aquí, $n!' WHERE `ID`=40305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기요, 저기요! 적개심을 버리세요! 전 자주 마주치고 완전히 무해한 중립적인 고블린 중 한 명이란 말이에요! 호드네 고블린 아니거든요!', `MaleText_loc4`='嘿，嘿！别再怀有敌意了！我就是你们常遇到的那些人畜无害的中立地精，跟部落没关系！', `MaleText_loc5`='喂，喂!收回你的敵意!我是那種常碰到且完全無害的中立哥布林，不是部落的那種!', `MaleText_loc7`='¡Oye, oye! ¡Cesa las hostilidades! Soy uno de esos goblins neutrales perfectamente inofensivos que se ven por todas partes, ¡no de esos de la Horda!' WHERE `ID`=40306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 보라고, $n 님이야. 돈도 엄청 많은 것 같아. 다음 무역왕이 될 거라고들 하던데!', `MaleText_loc4`='嘿，快瞧啊，是$n。我猜$g他:她;肯定富得流油了。听说$g他:她;在竞争贸易大王的位置！', `MaleText_loc5`='你們看，是$n。我賭$g他:她;身上一定很多錢。我聽說$g他:她;要去搶貿易親王的工作!', `MaleText_loc7`='Mirad, es $n. Seguro que está $gforrado:forrada;. ¡Dicen que quiere arrebatarle el puesto al Príncipe mercante!', `FemaleText_loc1`='자자, 보세요, $n 님이에요. 돈도 엄청 많은 것 같아요. 다음 무역왕이 될 거라고들 하던데요!', `FemaleText_loc4`='嘿，快瞧啊，是$n。我猜$g他:她;肯定富得流油了。听说$g他:她;在竞争贸易大王的位置！', `FemaleText_loc5`='你們看，是$n。我賭$g他:她;身上一定很多錢。我聽說$g他:她;要去搶貿易親王的工作!', `FemaleText_loc7`='Mirad, es $n. Seguro que está $gforrado:forrada;. ¡Dicen que quiere arrebatarle el puesto al Príncipe mercante!' WHERE `ID`=40307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스자보, 지금 아주 멋져 보이는걸!', `MaleText_loc4`='苏扎博。他现在太热了！', `MaleText_loc5`='薩波。他現在看起來真性感!', `MaleText_loc7`='Szabo. ¡Ahora mismo es lo más!', `FemaleText_loc1`='스자보, 지금 아주 멋져 보이는걸!', `FemaleText_loc4`='苏扎博。他现在太热了！', `FemaleText_loc5`='薩波。他現在看起來真性感!', `FemaleText_loc7`='Szabo. ¡Ahora mismo es lo más!' WHERE `ID`=40308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 꿈틀대는 새끼 곰을 잡아 안습니다.', `MaleText_loc4`='$n抱起一只蠕动的熊崽。', `MaleText_loc5`='$n發現了一隻在蠕動的小熊。', `MaleText_loc7`='$n recoge un cachorro de oso que no deja de retorcerse.' WHERE `ID`=40309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 한때 여사제였지만, 언제나 학자였어요. 잘 알지 못한 채 엄격한 수행을 하느니 명가에 대해 배울 기회를 얻는 게 더 소중하다고 생각한답니다.$B$B게다가 이곳의 수습생 대부분은 3차 대전쟁 동안 성년이 된 젊은이들이에요. 그들에겐 지도와 지혜가 필요하답니다.$B$B저를 친구라 부르곤 한 자들이 이해하기를 바랄 뿐이에요.', `FemaleText_loc4`='我曾经是位女祭司，但我不变的身份却是学者。能够汲取上层精灵的学识，比施行无知的严律要宝贵得多。$B$B更重要的是，这里的大多数学徒，都是在第三次大战期间成年的年轻人。他们需要指引，需要智慧……$B$B我只希望那些曾把我当成朋友的人能明白这一点。', `FemaleText_loc5`='我曾經是一個牧師，但我一直以來都是一個學者。研究精靈貴族的機會看起來比練習無知的事物來的有價值多了。$B$B大部份的學徒都是在第三次戰爭時過來的孩子。他們需要導引和智慧...$b$b我只希望那些曾當我是朋友的人能夠理解。', `FemaleText_loc7`='Antes era una sacerdotisa, pero siempre he sido una académica. La oportunidad de aprender de los Altonato me pareció más valiosa que practicar la estricta ignorancia.$b$bAdemás, muchos de los aprendices son jóvenes que crecieron durante la tercera guerra. Necesitan orientación y sabiduría...$b$bOjalá lo entendieran aquellos que solían considerarme una amiga.' WHERE `ID`=40310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 보고 있군요... 제가 보이나요?$B$B제발 도와주세요...', `FemaleText_loc4`='你在看着我……你能看见我吗？$B$B请你，帮帮我……', `FemaleText_loc5`='你正在看我...你看得到我?$B$B拜託，幫幫我...', `FemaleText_loc7`='Me estás mirando... ¿Puedes verme?$b$bPor favor, ayúdame.' WHERE `ID`=40311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더마인에서보다 일하기 편한걸!', `MaleText_loc4`='在安德麦工作要好得多！', `MaleText_loc5`='幽坑城的工作好多了!', `MaleText_loc7`='¡Se trabajaba mejo'' en Minahonda!', `FemaleText_loc1`='언더마인에서보다 일하기 편한걸!', `FemaleText_loc4`='在安德麦工作要好得多！', `FemaleText_loc5`='幽坑城的工作好多了!', `FemaleText_loc7`='¡Se trabajaba mejo'' en Minahonda!' WHERE `ID`=40312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭐 잘못했나요? 점심 먹고 두 번 쉬는 거 아닌가요?', `MaleText_loc4`='我做错了什么？一天连一顿午饭和两次休息都没有吗，老兄？', `MaleText_loc5`='我做錯了什麼?我不是應該每天有一頓午餐和兩次休息的機會嗎，老兄?', `MaleText_loc7`='¿Qué eh''toy haciendo mal? ¿Es que no tengo una hora de almue''zo y dos descanso'' al día, colega?', `FemaleText_loc1`='내가 뭐 잘못했나요? 점심 먹고 두 번 쉬는 거 아닌가요?', `FemaleText_loc4`='我做错了什么？一天连一顿午饭和两次休息都没有吗，老兄？', `FemaleText_loc5`='我做錯了什麼?我不是應該每天有一頓午餐和兩次休息的機會嗎，老兄?', `FemaleText_loc7`='¿Qué eh''toy haciendo mal? ¿Es que no tengo una hora de almue''zo y dos descanso'' al día, colega?' WHERE `ID`=40313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 아파!', `MaleText_loc4`='嗷！好疼！', `MaleText_loc5`='啊嗚!很痛啊!', `MaleText_loc7`='¡Auch! ¡Eso ha doli''o!', `FemaleText_loc1`='아야! 너무 아파!', `FemaleText_loc4`='嗷！好疼！', `FemaleText_loc5`='啊嗚!很痛啊!', `FemaleText_loc7`='¡Auch! ¡Eso ha doli''o!' WHERE `ID`=40314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인사부에 신고할거요!', `MaleText_loc4`='我要上告人力官员！', `MaleText_loc5`='我要向人資部投訴你!', `MaleText_loc7`='¡Me quejaré a Recuh''sos Humano''!', `FemaleText_loc1`='인사부에 신고할거요!', `FemaleText_loc4`='我要上告人力官员！', `FemaleText_loc5`='我要向人資部投訴你!', `FemaleText_loc7`='¡Me quejaré a Recuh''sos Humano''!' WHERE `ID`=40315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발... 도와주세요. 제 말이 들리신다면... 도와주세요.', `FemaleText_loc4`='帮帮我……求你，如果你能听见，请帮帮我……', `FemaleText_loc5`='救我...拜託，如果你聽得到我的聲音，救救我...', `FemaleText_loc7`='Socorro... Si puedes oírme, ayúdame, por favor...' WHERE `ID`=40316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 잘해주시네요, $n. 전 베리니아스 때문에 여기 오랫동안 갇혀 있었어요. 그 젊은 엘프는 제가 오래전에 느껴 본 첫 번째 영혼이에요.', `FemaleText_loc4`='你真是太好了，$n。因为维林尼亚斯，我被关在这儿太久了。那个年轻的精灵是我多年来尝到的第一个灵魂。', `FemaleText_loc5`='你實在是太好了，$n。因為維瑞尼亞斯，我被困在這裡已經很久很久。那個年輕的精靈是我過了那麼久所品嘗的第一個靈魂。', `FemaleText_loc7`='Has sido muy amable conmigo, $n. He estado atrapada aquí tanto tiempo por culpa de Verinias. Ese joven elfo ha sido la primera alma que he saboreado en años.' WHERE `ID`=40317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 모습을 그에게 준 이후로도, 그는 저를 계속 가둬놨어요. 심지어 그는 영혼을 모두 숨겨놔 저는 어떤 영혼도... 고집이 대단했죠.', `FemaleText_loc4`='就算我把那形态给了他，他还是坚持要把我困住。他甚至还把所有灵魂都藏了起来，就是为了不让我得到……真是太顽固了。', `FemaleText_loc5`='就連我賦予了他那個形態後，他還是堅持要把我困住。他甚至將所有的靈魂都儲存了起來，一個都不給我...真是固執。', `FemaleText_loc7`='Incluso después de que yo le otorgara el don de esa forma, él insistió en mantenerme atrapada. Llegó a acaparar todas las almas solo para que yo no pudiera tener ninguna... Es tan testarudo.' WHERE `ID`=40318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신세를 졌네요... 언젠가 갚을 수 있을 거예요.', `FemaleText_loc4`='我欠你个人情，宝贝儿……有一天我会回来偿还。', `FemaleText_loc5`='我欠你一次，親愛的...有一天我會回來報這個恩的。', `FemaleText_loc7`='Te debo un favor, cariño... Algún día te lo devolveré.' WHERE `ID`=40319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 그만하시지!', `FemaleText_loc4`='暂时够了！', `FemaleText_loc5`='現在這樣就夠了!', `FemaleText_loc7`='¡Ya es suficiente!' WHERE `ID`=40320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜히 놀란 척하지 말게. 자네의 그 주술사 친구말이야, 눈이 참 매섭더군. 개구리 눈치곤 말이야.', `FemaleText_loc4`='不要这么惊讶。你的萨满朋友有着明察秋毫的眼睛，或者说，有着明察秋毫的青蛙。', `FemaleText_loc5`='別擺出這副意外的模樣。你的薩滿朋友眼睛蠻銳利的，喔或者應該說，青蛙的眼睛蠻銳利的。', `FemaleText_loc7`='No te sorprendas tanto. Tu amiga chamán es muy lih''ta. O debería decir, que son las ranas las que son muy lih''tas.' WHERE `ID`=40321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나 같은 드루이드들은 말이야, 한동안 몸을 숨긴 채 조용히 살았다네. 이제나 저제나 볼진이 돌아올 날을 기다리면서 말이야.', `FemaleText_loc4`='我们德鲁伊一直潜伏在这里，等待着，看沃金是不是会回来。', `FemaleText_loc5`='我的同類，德魯伊們，我們已經低調了很久。我們一直等著看沃金是否會回來。', `FemaleText_loc7`='Los druidas como yo hemos intentado pasar desapercibíos durante mucho tiempo. Hemos eh''tado a la eh''pera del posible regreso de Vol''jin, si es que regresaba.' WHERE `ID`=40322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은창 부족이 이 섬으로 돌아온다고 하니 말이야, 이제 슬슬 우리도 모습을 드러낼 때가 온 것 같군.', `FemaleText_loc4`='看样子，暗矛部族正在返回这些岛屿。也许我们现身的时候到了。', `FemaleText_loc5`='現在看來，暗矛部族要回到島上了，也許是時候了，我們是該現身了。', `FemaleText_loc7`='Ahora parece que los Lanza Negra regresarán a las Islas y quizá haya llegao el momento de darnos a conocer.' WHERE `ID`=40323;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진에게 돌아가 이렇게 전하게. 젠타브라는 다가올 전투에서 볼진과 함께 싸울 준비가 되었다고 말이야.', `FemaleText_loc4`='回到沃金那里去，告诉他：岑塔布拉已经做好了和他并肩作战的准备。', `FemaleText_loc5`='回去找沃金並告訴他:贊塔布拉已經準備好在接下來的戰爭中協助他。', `FemaleText_loc7`='Vuelve al lado de Vol''jin y dile eh''to: Zen''tabra eh''tá preparada parara ayudah''le en la batalla que se avecina.' WHERE `ID`=40324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 무너져 버리다니...', `MaleText_loc4`='一切都化为了废墟……', `MaleText_loc5`='一切都成為混亂...', `MaleText_loc7`='Está todo en ruinas...', `FemaleText_loc1`='다 무너져 버리다니...', `FemaleText_loc4`='一切都化为了废墟……', `FemaleText_loc5`='一切都成為混亂...', `FemaleText_loc7`='Está todo en ruinas...' WHERE `ID`=40325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 넘쳐 들어오더니 모두 잠겨 버렸습니다!', `MaleText_loc4`='水冲了进来，把一切都淹没了！', `MaleText_loc5`='水湧了進來並將一切淹沒!', `MaleText_loc7`='¡El agua entró y lo anegó todo!', `FemaleText_loc1`='물이 넘쳐 들어오더니 모두 잠겨 버렸습니다!', `FemaleText_loc4`='水冲了进来，把一切都淹没了！', `FemaleText_loc5`='水湧了進來並將一切淹沒!', `FemaleText_loc7`='¡El agua entró y lo anegó todo!' WHERE `ID`=40326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리로 가서 도와주십시오. 제발요!', `MaleText_loc4`='你必须前往千针石林提供帮助。拜托了！', `MaleText_loc5`='你必須到千針石林幫忙。拜託!', `MaleText_loc7`='Debes ir a Las Mil Agujas y ayudar. ¡Te lo ruego!', `FemaleText_loc1`='버섯구름 봉우리로 가서 도와주십시오. 제발요!', `FemaleText_loc4`='你必须前往千针石林提供帮助。拜托了！', `FemaleText_loc5`='你必須到千針石林幫忙。拜託!', `FemaleText_loc7`='Debes ir a Las Mil Agujas y ayudar. ¡Te lo ruego!' WHERE `ID`=40327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지모신께서 우리를 지켜 주시길.', `MaleText_loc4`='愿大帝母亲保佑我们。', `MaleText_loc5`='大地之母保護我們。', `MaleText_loc7`='Que la Madre Tierra nos cuide a todos.', `FemaleText_loc1`='대지모신께서 우리를 지켜 주시길.', `FemaleText_loc4`='愿大帝母亲保佑我们。', `FemaleText_loc5`='大地之母保護我們。', `FemaleText_loc7`='Que la Madre Tierra nos cuide a todos.' WHERE `ID`=40328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높새바람 봉우리는 사라졌습니다. 버섯구름 봉우리가 파괴되었단 말입니다.', `MaleText_loc4`='我们失去了乱风岗。千针石林被毁了。', `MaleText_loc5`='已失去了亂風崗。千針石林被毀了。', `MaleText_loc7`='El Poblado Viento Libre está perdido. Las Mil Agujas han sido destruidas.', `FemaleText_loc1`='높새바람 봉우리는 사라졌습니다. 버섯구름 봉우리가 파괴되었단 말입니다.', `FemaleText_loc4`='我们失去了乱风岗。千针石林被毁了。', `FemaleText_loc5`='已失去了亂風崗。千針石林被毀了。', `FemaleText_loc7`='El Poblado Viento Libre está perdido. Las Mil Agujas han sido destruidas.' WHERE `ID`=40329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수대를 위해 이 지역을 지켜내는 일은 페랄라스의 수호를 위한 우리의 마지막 일이 될 겁니다.', `FemaleText_loc4`='为哨兵守住这片区域，将是我们守卫菲拉斯任务的最后一步。', `FemaleText_loc5`='為哨兵保衛這個地區將會是我們防衛菲拉斯的最後一環。', `FemaleText_loc7`='Ayudar a los Centinelas a proteger esta zona será la parte final de nuestra defensa de Feralas.' WHERE `ID`=40330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 대지모신께서 우릴 보호해 주지 않으시는 겁니까?', `MaleText_loc4`='大帝母亲为什么没有护佑我们？', `MaleText_loc5`='大地之母為什麼不保護我們?', `MaleText_loc7`='¿Por qué no nos ha protegido la Madre Tierra?', `FemaleText_loc1`='왜 대지모신께서 우릴 보호해 주지 않으시는 겁니까?', `FemaleText_loc4`='大帝母亲为什么没有护佑我们？', `FemaleText_loc5`='大地之母為什麼不保護我們?', `FemaleText_loc7`='¿Por qué no nos ha protegido la Madre Tierra?' WHERE `ID`=40331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스피릿혼 족장님이 높새바람 봉우리로 지원을 보내실 게 분명합니다.', `MaleText_loc4`='魂角酋长必须立刻向乱风岗派出援军。', `MaleText_loc5`='酋長魂角必須盡快派遣援兵至亂風崗。', `MaleText_loc7`='El Jefe Almaspina debe enviar ayuda al Poblado Viento Libre pronto.', `FemaleText_loc1`='스피릿혼 족장님이 높새바람 봉우리로 지원을 보내실 게 분명합니다.', `FemaleText_loc4`='魂角酋长必须立刻向乱风岗派出援军。', `FemaleText_loc5`='酋長魂角必須盡快派遣援兵至亂風崗。', `FemaleText_loc7`='El Jefe Almaspina debe enviar ayuda al Poblado Viento Libre pronto.' WHERE `ID`=40332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이 일어났다고들 하더군요. 어째서 이런 일이 일어난 거죠? 왜 우리에게 이런 일이...', `MaleText_loc4`='他们把它叫做大灾变。这毁灭因何而起？为什么是我们？', `MaleText_loc5`='他們稱之為大災變。什麼造成了這個災難?為什麼會找上我們?', `MaleText_loc7`='Lo llaman Cataclismo. ¿Qué ha causado esta destrucción? ¿Por qué nosotros?', `FemaleText_loc1`='대격변이 일어났다고들 하더군요. 어째서 이런 일이 일어난 거죠? 왜 우리에게 이런 일이...', `FemaleText_loc4`='他们把它叫做大灾变。这毁灭因何而起？为什么是我们？', `FemaleText_loc5`='他們稱之為大災變。什麼造成了這個災難?為什麼會找上我們?', `FemaleText_loc7`='Lo llaman Cataclismo. ¿Qué ha causado esta destrucción? ¿Por qué nosotros?' WHERE `ID`=40333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 호랑이의 혼이여, $n에게 힘을 빌려주소서. 우리가 해답을 찾도록 도와주소서!', `FemaleText_loc4`='猛虎之灵，将你的力量借给$n，帮助我们找到答案吧！', `FemaleText_loc5`='喔猛虎之靈呀，將你的神力借給$n吧，幫助我們找出我們企求的答案來!', `FemaleText_loc7`='¡Oh, Eh''píritu del tigre, préh''tale tu poder a $n y ayúdale a encontrar las reh''puestas que busca!' WHERE `ID`=40334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리 암호랑이가 나타납니다. 전투를 통해 당신을 증명하십시오!', `MaleText_loc4`='猛虎女王出现了！在战斗中证明你自己吧！', `MaleText_loc5`='猛虎族母出現了!在戰鬥中證明你的能力吧!', `MaleText_loc7`='¡Aparece la Matriarca tigresa! ¡Demuestra tu valor en combate!' WHERE `ID`=40335;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브록, 그대에게 간청하오니, 너무 늦기 전에 지금 당장 하늬자락 꼭대기에 고블린들을 보내주십시오.', `FemaleText_loc4`='布洛格，我请求你立刻派些地精前往西岸峰，趁现在还来得及。', `FemaleText_loc5`='布洛葛，我懇求你現在派些你的哥布林到西聯峰，在還來得及之前。', `FemaleText_loc7`='Brogg, te ruego que envíes a algunos de tus goblins a la Cima Tramo Oeste ahora mismo, antes de que sea demasiado tarde.' WHERE `ID`=40336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘장을 잃어버린 것 같습니다.', `MaleText_loc4`='我好象是丢了一件制服。', `MaleText_loc5`='我想我把外袍弄丟了。', `MaleText_loc7`='Creo que he perdido un tabardo.', `FemaleText_loc1`='휘장을 잃어버린 것 같습니다.', `FemaleText_loc4`='我好象是丢了一件制服。', `FemaleText_loc5`='我想我把外袍弄丟了。', `FemaleText_loc7`='Creo que he perdido un tabardo.' WHERE `ID`=40337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버섯구름 봉우리가 수백 미터 물 아래 잠겨 있습니다. 고블린들을 지원해서 우릴 도와주시면 안 되겠습니까?', `FemaleText_loc4`='化为废墟的千针石林沉没在数百尺深的水底。你能派些地精来帮助我们吗？', `FemaleText_loc5`='千針石林被淹沒在幾百英尺深的水之下。你可以施捨一些哥布林來幫助我們嗎?', `FemaleText_loc7`='Las Mil Agujas yacen destrozadas bajo cientos de metros de agua. ¿Puedes enviar algún goblin para que nos ayude?' WHERE `ID`=40338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 동쪽 산을 가루로 만들었습니다. 봇물처럼 쏟아져나온 남쪽 바닷물에 버섯구름 봉우리 전체가 잠겨버렸어요! 절망적인 상황에 빠진 우리를 구원해주실 수 있으십니까?', `FemaleText_loc4`='大灾变把东部山脉碾碎。南海的水灌入并吞没了整个千针石林！你能在这紧要关头帮帮我们吗？', `FemaleText_loc5`='大災變摧毀了東部群山。南海的水湧入將整個千針石林都給淹沒了!你可以在我們最需要幫忙的時候予以協助嗎?', `FemaleText_loc7`='El Cataclismo ha derribado las montañas del este. ¡Los Mares del Sur han entrado y sumergido todas Las Mil Agujas! ¿Puedes ayudarnos en esta hora de necesidad?' WHERE `ID`=40339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 부탁이니, 하늬자락 꼭대기에서 구호활동을 벌이는 중인 우리를 도와주십시오. 버섯구름 봉우리가 파괴되었습니다!', `FemaleText_loc4`='拜托了。我们正在西岸峰展开救援工作。千针石林已经消亡了！', `FemaleText_loc5`='拜託。我們正在西聯峰策劃救援行動。千針石林已經被夷平了!', `FemaleText_loc7`='Por favor. Estamos organizando una operación de rescate en la Cima Tramo Oeste. ¡Ha habido una catástrofe en Las Mil Agujas!' WHERE `ID`=40340;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 먼지진흙 습지대도 강타했다는 점은 잘 알겠으나, 진흙톱니 거점은 상대적으로 그 피해가 적은 것 같습니다. 그곳의 고블린들을 지원해주실 수 있으십니까?', `FemaleText_loc4`='我明白大灾变也同样袭击了尘泥沼泽，但泥链镇看上去还相对安全。你愿意派些地精来帮忙吗？', `FemaleText_loc5`='我瞭解塵泥沼澤也受到了大災變的影響，但泥鏈營地相較之下還算安全。你可以派遣一些哥布林嗎?', `FemaleText_loc7`='Tengo entendido que el Cataclismo también ha asolado el Marjal Revolcafango, pero Piñón de Barro parece relativamente a salvo. ¿No puedes enviar ningún goblin?' WHERE `ID`=40341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늬자락 꼭대기에 도움을 주실 수 없다면, 이곳의 피난민들을 그쪽으로 보내도 되겠습니까?', `FemaleText_loc4`='要是你不能派人前往西岸峰帮忙，那我们能把难民送到这儿来吗？', `FemaleText_loc5`='如果你無法派遣支援到西聯峰，我們可以將難民送到這裡嗎?', `FemaleText_loc7`='Si no puedes enviar ayuda a la Cima Tramo Oeste, ¿podemos traer a los refugiados aquí?' WHERE `ID`=40342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만약 이른 시일 내에 버섯구름 봉우리가 지원군을 받지 못한다면 그림토템들이 기습을 감행할 수도 있다는 생각에 두렵습니다. 지금으로선 우리 자신을 지킬 상황이 못되기 때문이죠.', `FemaleText_loc4`='我担心要是援军不能尽快赶到千针石林的话，恐怖图腾就会开始行动了。我们无论如何都坚守不了多久。', `FemaleText_loc5`='如果千針石林無法儘快獲得支援，我怕恐怖圖騰會有所行動。我們現在沒有力量能撐很久。', `FemaleText_loc7`='Temo que los Tótem Siniestro entren en acción si no recibimos refuerzos pronto. No estamos en posición de defendernos mucho tiempo.' WHERE `ID`=40343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브록, 만약 버섯구름 봉우리의 슈할로가 무너진다면, 머지않아 그대의 집앞에 그림토템 부족이 어슬렁거릴 거예요. 지금 당장 조치를 취해야 합니다!', `FemaleText_loc4`='要是千针石林的舒哈鲁被击败，恐怖图腾部族很快就会出现在你家门口。现在是时候行动了，布洛格！', `FemaleText_loc5`='如果千針石林的舒哈魯淪陷了，恐怖圖騰很快就會出現在你家門口。再不行動就沒機會了，布洛葛!', `FemaleText_loc7`='Si los Shu''halo de Las Mil Agujas caen, el clan Tótem Siniestro se presentará ante tus puertas poco después. ¡Es la hora de actuar, Brogg!' WHERE `ID`=40344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬이나 검은창 해안, 센진 마을을 벗어나서는 안 됩니다.', `MaleText_loc4`='你必须留在回音群岛、暗矛海滩或者是森金村。', `MaleText_loc5`='你必須待在回音群島、暗矛海灘或森金村。', `MaleText_loc7`='Debes permanecer en las Islas del Eco, en la Playa Lanza Negra o en el Poblado Sen''jin.' WHERE `ID`=40345;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브록이라고 불러도 되죠? 잠깐, 제가 어떤 머리와 말하고 있는 거죠?', `FemaleText_loc4`='布洛格。你不介意我这样称呼你吧？等等，我是在和哪个头说话？', `FemaleText_loc5`='布洛葛。你不在意我這樣叫你吧?等一下，我在跟哪個頭講話?', `FemaleText_loc7`='Brogg. No te importa que te llame así, ¿verdad? Espera, ¿con qué cabeza estoy hablando?' WHERE `ID`=40346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대와 고블린들의 도움이 필요해요. 버섯구름 봉우리가 파괴되었습니다! 탈라나르는 물 아래 잠겼고요!', `FemaleText_loc4`='我们需要你和你的地精伸出援手。千针石林被毁了！萨兰纳尔已经沉在水底！', `FemaleText_loc5`='我們需要你和你的哥布林的幫忙。千針石林被摧毀了!薩蘭納爾浸在水中!', `FemaleText_loc7`='Necesitamos tu ayuda y la de tus goblins. ¡Las Mil Agujas están destrozadas! ¡Thalanaar está sumergida!' WHERE `ID`=40347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 이곳의 책임자죠? 신 탈라나르에 지금 당장 도움이 필요해요!', `FemaleText_loc4`='你们现在谁是负责人？新萨兰纳尔现在需要你们的帮助！', `FemaleText_loc5`='你們哪個才是這的負責人?新薩蘭納爾現在就需要幫助!', `FemaleText_loc7`='¿Cuál de los dos está al mando? ¡Necesitamos ayuda en Nueva Thalanaar de inmediato!' WHERE `ID`=40348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 힘든 상황에 닥치면 지원해주세요. 신 탈라나르를 노리는 적들의 공격이 임박했어요!', `FemaleText_loc4`='你们必须在这紧要关头向我们施以援手。对新萨兰纳尔的攻击已经迫在眉睫！', `FemaleText_loc5`='你必須在我們需要的時候進行援助。新薩蘭納爾快遭到新一波的攻擊了!', `FemaleText_loc7`='Debes enviarnos ayuda en este momento de necesidad. ¡El ataque a Nueva Thalanaar es inminente!' WHERE `ID`=40349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 돈도 드릴 수 있어요.', `FemaleText_loc4`='是的，不会让你们白忙。', `FemaleText_loc5`='是的，我們願意付錢。', `FemaleText_loc7`='Sí, podemos pagar.' WHERE `ID`=40350;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고르독이나 골두니 부족과 한패는 아니시죠, 그렇죠?', `FemaleText_loc4`='你不是戈多克或戈杜尼部族那边的，对吧？', `FemaleText_loc5`='你不是戈多克或戈杜尼部族的，對吧?', `FemaleText_loc7`='No estás con las tribus Gordok o Gordunni, ¿verdad?' WHERE `ID`=40351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변 때문에 버섯구름 봉우리는 그 어느 지역보다도 큰 피해를 받았어요. 부탁이니, 저희에게 힘을 빌려주실 수 있으세요?', `FemaleText_loc4`='大灾变对千针石林造成的影响最大。拜托了，可以帮帮我们吗？', `FemaleText_loc5`='受大災變影響最深的就是千針石林。拜託，你可以提供幫助嗎?', `FemaleText_loc7`='El Cataclismo ha azotado Las Mil Agujas con más fuerza que ningún otro sitio. Por favor, ¿puedes ayudarnos?' WHERE `ID`=40352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토끼와 새끼 사슴들이요? 네, 물론 있죠. 신 탈라나르에 와서 우리 좀 도와주실 수 있나요? 잠깐... 그게 왜 알고 싶으신 거죠?', `FemaleText_loc4`='兔子和小鹿？是的，我们有那些动物。你现在能来新萨兰纳尔帮我们了吗？等等……你为什么会问这个问题？', `FemaleText_loc5`='兔寶寶和幼鹿?是的，我們有。你現在能來新薩蘭納爾幫助我們了嗎?等一下...你為什麼會問這個?', `FemaleText_loc7`='¿Conejos y cervatillos? Sí, los hay. ¿Entonces nos ayudaréis en Nueva Thalanaar? Espera... ¿por qué quieres saberlo?' WHERE `ID`=40353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 버섯구름 봉우리의 서쪽 산들을 파괴했어요. 남쪽 바닷물이 밀려들어 왔고 협곡은 물에 잠겨버렸죠.$B$B부탁입니다, $c님. 신 탈라나르를 구해주세요!', `FemaleText_loc4`='大灾变毁了千针石林的西部山脉。南海灌入并淹没了峡谷。$B$B拜托了，$c，你必须来新萨兰纳尔帮帮我们！', `FemaleText_loc5`='大災變摧毀了千針石林西邊的山脈。南海的水湧了進來將峽谷都給淹沒了。$B$B拜託，$c，你必須要來新薩蘭納爾幫助我們!', `FemaleText_loc7`='El Cataclismo ha destruido las montañas occidentales de Las Mil Agujas. Los Mares del Sur han entrado e inundado los cañones.$b$bPor favor, $c, ¡debes venir en nuestra ayuda en Nueva Thalanaar!' WHERE `ID`=40354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대격변이 버섯구름 봉우리를 파괴해 버렸습니다. $c|1이여;여;, 도움의 손길이 절실한 지금, 그대가 우릴 도와줄 수 있으십니까?', `FemaleText_loc4`='大灾变毁掉了千针石林，$c。你愿意在我们最危难的时刻来帮帮我们吗？', `FemaleText_loc5`='大災變摧毀了千針石林，$c。你能在我們最需要幫助時伸出援手嗎?', `FemaleText_loc7`='El Cataclismo ha destruido Las Mil Agujas, $c. ¿Nos ayudarás en nuestro momento de mayor necesidad?' WHERE `ID`=40355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자매여, 그대의 훈련이 좋은 성과를 보이고 있군요. 제가 더 가르쳐 드리지 않아도 그대의 소속 부대원들을 통솔할 날이 멀지 않았어요.', `FemaleText_loc4`='你们的训练进行得很顺利，姐妹们。过不了多久，你们就能带领自己的人民，再不需要我的教导。', `FemaleText_loc5`='姐妹們，你們的訓練進行的很順利。不久之後你們便可以獨當一面，帶領你們的人民。', `FemaleText_loc7`='Su instrucción ha progresado muy bien, hermanas. Dentro de poco podrán liderar a su pueblo sin necesidad de mis enseñanzas.' WHERE `ID`=40356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 지금 우리 마법에 매우 약해진 상태입니다! 제압하십시오!', `MaleText_loc4`='他现在很容易受到我们魔法的伤害！把他打倒！', `MaleText_loc5`='我們的魔法現在可以傷到他!快把他壓制下來!', `MaleText_loc7`='¡Ahora es vulnerable a nuestra magia! ¡Sujétalo!', `FemaleText_loc1`='그가 지금 우리 마법에 매우 약해진 상태입니다! 제압하십시오!', `FemaleText_loc4`='他现在很容易受到我们魔法的伤害！把他打倒！', `FemaleText_loc5`='我們的魔法現在可以傷到他!快把他壓制下來!', `FemaleText_loc7`='¡Ahora es vulnerable a nuestra magia! ¡Sujétalo!' WHERE `ID`=40357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 내게 그 통솔력을 보여줘야 할 때로군요. 탬버, 부대를 지휘하여 살도르 섬을 공격하세요. 그대의 사나운 기세가 필요할 겁니다.', `FemaleText_loc4`='是时候让我瞧瞧你的领导力了。塔姆布莉，你将率军在萨尔多岛展开攻势。你一定能在那里为你的勇猛找到用武之地。', `FemaleText_loc5`='該是你展示領導能力的時候了，湯布瑞。你將要進攻薩爾多島。你的兇猛在那是被需要的。', `FemaleText_loc7`='Es hora de que me enseñes ese liderazgo. Tambre, encabezarás la ofensiva en la Isla de Sardor. Allí hace falta tu ferocidad.' WHERE `ID`=40359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실비아, 에스툴란의 탑으로 가서 골두니 오우거들을 몰아내는 일을 맡기겠습니다. 그대의 외교술과 전략이 시험대에 오를 겁니다.', `FemaleText_loc4`='西尔维亚，我要派你前往埃斯图兰之塔驱逐那些戈杜尼食人魔。看看你的外交手段和战略对策能否经受住考验。', `FemaleText_loc5`='希爾薇雅，我將把你送到艾斯圖蘭之塔去對付戈杜尼的巨魔們。你的外交和戰略能力都將受到考驗。', `FemaleText_loc7`='Silvia, te envío a la Torre de Estulan para expulsar a los ogros Gordunni. Esta misión pondrá a prueba tanto tu diplomacia como tu estrategia.' WHERE `ID`=40360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아델라, 멀리 동쪽으로 향하세요. 우리 군은 동쪽 지역을 다시 손에 넣어야 하고 이전엔 보지 못한 호드들을 주시해야 해요. 그대 판단이 사격술만큼 예리하길 바랍니다.', `FemaleText_loc4`='艾德娜，你必须出击至遥远的东边。我们的军队一定要夺回东部荒野，并观察那些从未见过的部落。愿你的判断力与你的枪法一样精准。', `FemaleText_loc5`='愛德拉，你將向遙遠的東部發動進攻。我們的軍隊必須奪回東部荒野，並隱密地觀察部落的動靜。希望你的判斷力和你的射擊能力一樣的出眾。', `FemaleText_loc7`='Adella, tú atacarás al este. Nuestras tropas deben retomar el bosque oriental y observar a la Horda sin ser vistas. Que tu juicio sea tan agudo como tu puntería.' WHERE `ID`=40361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디슬릭스, 저를 하늬자락 꼭대기로 보내주십시오!', `MaleText_loc4`='德斯利克，我要前往西岸峰！', `MaleText_loc5`='迪司利克思，我要到西聯峰!', `MaleText_loc7`='¡Dyslix, tengo que ir a la Cima Tramo Oeste!', `FemaleText_loc1`='디슬릭스, 저를 하늬자락 꼭대기로 보내주세요!', `FemaleText_loc4`='德斯利克，我要前往西岸峰！', `FemaleText_loc5`='迪司利克思，我要到西聯峰!', `FemaleText_loc7`='¡Dyslix, tengo que ir a la Cima Tramo Oeste!' WHERE `ID`=40362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대들이 잘 해낼 거라 기대합니다. 절 실망시키지 마시기 바랍니다. 해산하세요!', `FemaleText_loc4`='我很看好你。别让我失望。去吧！', `FemaleText_loc5`='我對你們賦予重望。別讓我失望。解散!', `FemaleText_loc7`='Deposito grandes esperanzas en ti. No me falles. ¡Parte!' WHERE `ID`=40363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디슬릭스, 저를 신 탈라나르로 보내주십시오!', `MaleText_loc4`='德斯利克，我要前往新萨兰纳尔！', `MaleText_loc5`='迪司利克思，我要到新薩蘭納爾!', `MaleText_loc7`='¡Dyslix, tengo que ir a Nueva Thalanaar!', `FemaleText_loc1`='디슬릭스, 저를 신 탈라나르로 보내주세요!', `FemaleText_loc4`='德斯利克，我要前往新萨兰纳尔！', `FemaleText_loc5`='迪司利克思，我要到新薩蘭納爾!', `FemaleText_loc7`='¡Dyslix, tengo que ir a Nueva Thalanaar!' WHERE `ID`=40364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠? 얘야, 뭐라도 찾았니?', `MaleText_loc4`='嗯？你找到什么了吗，小子？', `MaleText_loc5`='嗯?你找到了什麼嗎，小子?', `MaleText_loc7`='¿Mm? ¿Has encontrado algo, chico?' WHERE `ID`=40365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 모두 파헤쳐라! 살아있는 건 모두 다 없애버려!', `MaleText_loc4`='没错，把它挖出来。身后不留活口！', `MaleText_loc5`='就是這樣，繼續挖。別留下任何的活口!', `MaleText_loc7`='Eso es, desentiérralo. ¡No dejes nada con vida!' WHERE `ID`=40366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 찾았니, 꿀꿀아?', `MaleText_loc4`='你找到什么了，蠢猪？', `MaleText_loc5`='你找到了什麼，豬頭?', `MaleText_loc7`='¿Qué has encontrado, cerdo?' WHERE `ID`=40367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하는구나! 다 파헤쳐 버려라. 보이는 돌은 다 뒤집어 버려.', `MaleText_loc4`='那个小姑娘！全都挖出来——一处都不放过。', `MaleText_loc5`='全部挖出來，別放過任何一個角落。', `MaleText_loc7`='¡Buena chica! ¡Excávalo todo, no dejes piedra sin remover!' WHERE `ID`=40368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 돼지 같으니라고. 이 땅은 이미 죽었잖아. 움직여!', `MaleText_loc4`='蠢猪。这地方已经没东西可挖了。继续前进！', `MaleText_loc5`='笨豬，這裡已經什麼都沒了。繼續前進!', `MaleText_loc7`='Cerdo estúpido. Esa tierra ya está muerta. ¡Sigue adelante!' WHERE `ID`=40369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파헤쳐, 파헤쳐, 파헤쳐. 태워, 태워, 태워. 이 대지를 청소하자!', `MaleText_loc4`='挖，挖，挖。烧，烧，烧。彻底的翻查这个地方！', `MaleText_loc5`='挖挖挖!燒燒燒!將這片土地給翻過來!', `MaleText_loc7`='Cava, cava, cava. Quema, quema, quema. ¡Arrasa esta tierra hasta que quede limpia!' WHERE `ID`=40370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 킁킁거리며 그을린 땅을 파헤칩니다.', `MaleText_loc4`='%s闻了闻，朝焦黑的土壤中挖去。', `MaleText_loc5`='%s嗅了後開始挖燒焦的土。', `MaleText_loc7`='%s olisquea y excava la tierra quemada.' WHERE `ID`=40371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세얄라, 신 탈라나르로 가야 합니다!', `MaleText_loc4`='塞亚娜，我要前往新萨兰纳尔！', `MaleText_loc5`='賽雅拉，我要到新薩蘭納爾!', `MaleText_loc7`='¡Seyala, tengo que ir a Nueva Thalanaar!', `FemaleText_loc1`='세얄라, 신 탈라나르로 가야 합니다!', `FemaleText_loc4`='塞亚娜，我要前往新萨兰纳尔！', `FemaleText_loc5`='賽雅拉，我要到新薩蘭納爾!', `FemaleText_loc7`='¡Seyala, tengo que ir a Nueva Thalanaar!' WHERE `ID`=40372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아델라, 신 탈라나르로 그대의 친구들을 불러줄 수 없습니까? 도움이 필요합니다.', `MaleText_loc4`='艾德琳，你不能请你的朋友来新萨兰纳尔帮助我们吗？', `MaleText_loc5`='艾德琳，你可以問你的朋友能不能到新薩蘭納爾幫助我們嗎?', `MaleText_loc7`='Adeline, ¿no puedes pedirle a ninguno de tus amigos que venga a ayudarnos a Nueva Thalanaar?' WHERE `ID`=40373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리는 남쪽 바닷물로 잠겨 버렸습니다. 탈라나르가 침수됐단 말입니다!', `MaleText_loc4`='千针石林被南海吞噬。萨兰纳尔已沉入水底！', `MaleText_loc5`='千針石林已經被南海所吞噬了。薩蘭納爾浸在水中!', `MaleText_loc7`='El Mar del Sur se ha tragado Las Mil Agujas. ¡Thalanaar está sumergida!' WHERE `ID`=40374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리의 동쪽 산맥이 무너져 물속에 잠기고 남쪽 바닷물이 넘쳤습니다. 모든 게 사라졌어요.', `MaleText_loc4`='千针石林的东部山脉崩塌入海，南海的海水倾灌而入。什么都没剩下。', `MaleText_loc5`='千針石林的東部山脈崩裂至水中，南海的海水也湧了進來。一切都沒了。', `MaleText_loc7`='Las montañas orientales de Las Mil Agujas se han desmoronado sobre el agua y han dejado pasar el Mar del Sur. Todo está perdido.' WHERE `ID`=40375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험', `MaleText_loc4`='测试', `MaleText_loc5`='測試', `MaleText_loc7`='Prueba' WHERE `ID`=40376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변으로 버섯구름 봉우리가 파괴되었습니다. 그대가 도와준다면 가능한 한 많은 생명을 살릴 수 있을 겁니다!', `MaleText_loc4`='大灾变毁了千针石林。我们需要你的帮助，以挽救尽可能多的生命！', `MaleText_loc5`='大災變毀了千針石林。我們需要你的幫忙來盡可能地拯救無助的生命!', `MaleText_loc7`='El Cataclismo ha destruido Las Mil Agujas. ¡Tienes que ayudarnos a salvar tantas vidas como sea posible!' WHERE `ID`=40377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이 바로 얼라이언스에 대한 그대의 충성을 보여줄 때입니다. 신 탈라나르를 위해 어떠한 지원이든 보내주시기 바랍니다.', `MaleText_loc4`='现在到了证明你对联盟忠心的时候了。请派出任何你所能调派的人手前往新萨兰纳尔。', `MaleText_loc5`='現在是你證明對聯盟效忠的機會。請將任何可能的幫助送到新薩蘭納爾。', `MaleText_loc7`='Ha llegado el momento de demostrar tu lealtad a la Alianza. Por favor, envía toda la ayuda que puedas a Nueva Thalanaar.' WHERE `ID`=40378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 탈라나르를 잃었지만 완전히 잃은 건 아닙니다. 홍수의 가장자리에 있었던 우린 운이 좋았습니다. 얼마나 많은 생명이 목숨을 잃었는지 상상할 수조차 없군요. 신 탈라나르의 친구들에게 가능한 한 많은 도움을 주셨으면 합니다.', `MaleText_loc4`='我们已经失去了萨兰纳尔，但跟许多人比起来这点损失还不算什么。我们是幸运的，洪水来袭时就处在灾区边缘。我甚至无法开始想象，有多少生命在瞬间陨落。请你尽力帮助我们建设新萨兰纳尔。', `MaleText_loc5`='我們失去了薩蘭納爾，但只有一部份。我們是幸運的一群人，位於淹水區的最邊緣上。我無法想像已經失去了多少生命。請盡可能的將救援送到新薩蘭納爾。', `MaleText_loc7`='Hemos perdido Thalanaar, pero no por mucho. Hemos tenido la suerte de estar en el borde de la inundación. No puedo ni imaginar cuántas vidas se han perdido. Por favor, envía toda la ayuda que puedas a Nueva Thalanaar.' WHERE `ID`=40379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대적으로 보면, 페랄라스는 대격변의 소용돌이에 거의 휘말리지 않았습니다. 그러니 신 탈라나르에 도움을 주실 수 있겠지요?', `MaleText_loc4`='相对而言，大灾变对菲拉斯的影响并不大。你当然能派些人前往新萨兰纳尔对吧？', `MaleText_loc5`='相較之下，菲拉斯幾乎沒有受到大災變的影響。理所當然的，你應該可以派遣救援至新薩蘭納爾吧?', `MaleText_loc7`='En comparación, el Cataclismo apenas ha tocado Feralas. ¿Sin duda podrás enviar algo de ayuda a Nueva Thalanaar?' WHERE `ID`=40380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리의 생존자 모두를 위해 신 탈라나르에 구호 지원을 벌이고 있습니다. 지금 그대의 도움이 필요합니다!', `MaleText_loc4`='我们正在新萨兰纳尔对从千针石林逃出的所有幸存者展开救援。我们现在需要你的帮助！', `MaleText_loc5`='我們正在新薩蘭納爾為千針石林的生還者策劃救援行動。我們現在需要你的幫助!', `MaleText_loc7`='Estamos organizando una operación de rescate en Nueva Thalanaar para todos los supervivientes de Las Mil Agujas. ¡Necesitamos tu ayuda!' WHERE `ID`=40381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아, 그만! 동굴을 가져라, 작은 주술사여.', `MaleText_loc4`='够了！这洞是你的了，小萨满。', `MaleText_loc5`='夠了!小薩滿。拿去!你的洞穴。', `MaleText_loc7`='¡Suficiente! Ten tu cueva, pequeño chamán.' WHERE `ID`=40382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C|1이여;여;, 대격변으로 산이 무너지고 남쪽 바다가 범람하여 버섯구름 봉우리가 잠겼습니다.$B$B지금 그대의 도움이 필요합니다!', `MaleText_loc4`='$C，这场大灾变震碎了山脉。南海淹没了千针石林。$B$B我们需要你的帮助！', `MaleText_loc5`='$C，大災變震倒了群山，南海的海水也湧進來淹沒了千針石林。$B$B我們現在急需你的幫助!', `MaleText_loc7`='$C, el Cataclismo ha destruido las montañas y el Mar del Sur ha anegado Las Mil Agujas.$b$b¡Necesitamos tu ayuda!' WHERE `ID`=40383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 영혼들이 자네를 인도하길.', `MaleText_loc4`='愿英灵指引你，$c。', `MaleText_loc5`='願靈魂指引你，$c。', `MaleText_loc7`='Que los eh''píritus te guíen, $c.' WHERE `ID`=40384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점괘를 봐 주십시오.', `MaleText_loc4`='让我们来解读预兆。', `MaleText_loc5`='讓我們尋求預兆的指引。', `MaleText_loc7`='Consultemos los augurios.', `FemaleText_loc1`='점괘를 봐 주십시오.', `FemaleText_loc4`='让我们来解读预兆。', `FemaleText_loc5`='讓我們尋求預兆的指引。', `FemaleText_loc7`='Consultemos los augurios.' WHERE `ID`=40385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림토템 부족이 저희를 갑작스럽게 공격해왔어요. 저흰 가까스로 버티고 있어요.', `FemaleText_loc4`='恐怖图腾出其不意地突袭了我们。我们就快要坚持不住了。', `FemaleText_loc5`='恐怖圖騰打了我們個措手不及。我們很勉強的在這支撐著。', `FemaleText_loc7`='Los Tótem Siniestro nos han atacado por sorpresa. Apenas podemos aguantar.' WHERE `ID`=40386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족이여, 이제 영혼들의 조언을 구하겠노라! 자, 북을 울릴 준비를 하라!', `MaleText_loc4`='暗矛的成员们，我们要向祖灵寻求答案！鼓手，立刻就位！', `MaleText_loc5`='暗矛食人妖們，我們尋求靈魂的指引!鼓手們，上工了!', `MaleText_loc7`='¡Lanza Negra, consultemos a los eh''píritus! ¡Tambores, a sus pueh''tos!' WHERE `ID`=40387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이시여, 앞으로 우리의 갈 길을 여쭙고자 여기에 모였습니다.', `MaleText_loc4`='伟大的英灵啊，我们聚集于此，寻求您的指引。', `MaleText_loc5`='靈魂啊，我們聚集於此，祈求您的指引。', `MaleText_loc7`='Eh''píritus, acudan pa que podamos pediros consejo.' WHERE `ID`=40388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='센진의 아들이자 우리의 지도자 볼진이 검은창 부족 전체를 대상으로 소집 명령을 내렸습니다. 메아리 섬을 되찾으려는 것입니다.', `MaleText_loc4`='我们的领袖，森金之子沃金向全体暗矛部族的成员发起了号召：夺回回音群岛。', `MaleText_loc5`='我們的領袖，沃金，森金之子，對全部的暗矛食人妖發出了召集:為我們的部族奪回回音群島。', `MaleText_loc7`='Nueh''tro líder, Vol''jin, hijo de Sen''jin, ha lanzao un llamamiento a los Lanza Negra: recuperar las Islas del Eco pa nueh''tra tribu.' WHERE `ID`=40389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이시여! 여기 제 몸을 바칩니다! 저를 통해 말씀해 주십시오! 바로 지금이, 위대한 볼진이 이 과업을 추진하기에 적당한 시기입니까?', `MaleText_loc4`='伟大的英灵啊！我向您献出自己的身躯。请通过我说话吧！现在是不是强大的沃金开始行动的时刻？', `MaleText_loc5`='靈魂們!我獻出我自己的身體!以我的身體為媒介吧!強大的沃金要做的事情，時機是否到了?', `MaleText_loc7`='¡Eh''píritus! ¡Les ofrezco mi cuerpo! ¡Hablen a través de mí! ¿Ha llegao la hora de que el poderoso Vol''jin emprenda su misión?' WHERE `ID`=40390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의술사여, 선조들은 듣고 있느니라!', `MaleText_loc4`='巫医，祖先听到你的话了！', `MaleText_loc5`='先祖們聽到了你的禱告，巫醫!', `MaleText_loc7`='¡Los anceh''tros te escuchan, médico brujo!' WHERE `ID`=40391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들의 계획이 마음에 든다, 검은창 부족이여. 센진의 아들은 올바른 길을 걷고 있도다.', `MaleText_loc4`='你们的计划让我们喜悦，暗矛部族，森金之子的道路是正确的。', `MaleText_loc5`='你的計畫讓我們蠻滿意的，暗矛部族。森金之子選擇了一條正確的道路。', `MaleText_loc7`='Sus planes nos satisfacen, Lanza Negra. El hijo de Sen''jin camina por el sendero correcto.' WHERE `ID`=40392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들 앞에 놓인 임무가 쉽지는 않을 것이다. 하지만 우리가 곁에 있겠노라.', `MaleText_loc4`='你们的任务相当艰巨，但你们将得到我们的祝福。', `MaleText_loc5`='你眼前的工作並不容易，但是你會擁有我們的祝福。', `MaleText_loc7`='La tarea que vas a emprender no será fácil, pero tienes nueh''tra bendición.' WHERE `ID`=40393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬을 떠나면서, 너희들은 고향을 버리고 선조들의 로아들을 버렸다. 로아들이 그런 대접을 받고 기뻐할 리가 있겠느냐?', `MaleText_loc4`='你们离开回音群岛，放弃了家园和祖先的光荣。祖先不喜欢你们如此冷漠沉寂。', `MaleText_loc5`='從你離開回音群島的那刻起，你就放棄了你的家園，放棄了先祖的羅亞。你曾經漠視他們的這件事情，可是會讓他們相當不悅。', `MaleText_loc7`='Cuando abandonah''on las Islas del Eco renunciah''on a su hogar y a los Loa de sus anceh''tros. No eh''tarán contentos de que los hayan ignorao todo eh''te tiempo.' WHERE `ID`=40394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인을 물리치려면 죽은 이들의 수호자, 브원삼디와 화해해야 한다. 다른 방법은 없다. 센진의 아들에게 돌아가 그대로 전해라.', `MaleText_loc4`='如果你们想要击败扎拉赞恩，你们就必须向亡魂的守护者邦桑迪赎罪。把这件事告诉森金之子。', `MaleText_loc5`='如果你想擊敗札拉贊恩，你必須和亡者的守護者，伯昂撒姆第重修舊好。這是唯一的辦法。把這件事告訴森金之子。', `MaleText_loc7`='Si quieren derrotar a Zalazane, deben arreglar las cosas con Bwonsamdi, el guardián de los mueh''tos. Es la única manera. Cuéntale todas eh''tas cosas al hijo de Sen''jin.' WHERE `ID`=40395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 우리에게 답을 내려 주셨다! 우리는 메아리 섬을 되찾을 것이다!', `MaleText_loc4`='祖灵祝福了我们！回音群岛将再次成为我们的家园！', `MaleText_loc5`='靈魂們用他們的回答來祝福了我們!回音群島將會再次屬於我們!', `MaleText_loc7`='¡Los eh''píritus nos han bendecío con una reh''pueh''ta! ¡Las Islas del Eco serán nueh''tras de nuevo!' WHERE `ID`=40396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 뒤를 봐주다 죽진 않겠다, 드라가!', `MaleText_loc4`='我不会为了救你而丧命，暮光小子！', `MaleText_loc5`='暮光人，我不會犧牲自己來救你!', `MaleText_loc7`='¡No moriré para salvarte el pellejo, sujeto Crepuscular!' WHERE `ID`=40397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림토템 부족 녀석들! 어떻게 우리가 가장 절박한 상황에 습격해올 수 있었지?', `MaleText_loc4`='在我们最为危难的时刻，恐怖图腾怎么能对我们作出这种事？', `MaleText_loc5`='恐怖圖騰竟然在我們最需要援助時做出這種事!', `MaleText_loc7`='¿Cómo han podido hacernos esto los Tótem Siniestro en nuestra hora de mayor necesidad?' WHERE `ID`=40398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물길 탐험선을 하나 더 구해도 되겠습니까, 모테가?', `MaleText_loc4`='莫特加，能再为我派一名水域探险家吗？', `MaleText_loc5`='莫特加，可以再給我一個水上冒險者嗎?', `MaleText_loc7`='Motega, ¿me puedes dar otro explorador de agua?', `FemaleText_loc1`='물길 탐험선을 하나 더 구할 수 있을까요, 모테가?', `FemaleText_loc4`='莫特加，能再为我派一名水域探险家吗？', `FemaleText_loc5`='莫特加，可以再給我一個水上冒險者嗎?', `FemaleText_loc7`='Motega, ¿me puedes dar otro explorador de agua?' WHERE `ID`=40399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 황폐함을 보게, $c|1이여;여;! 눈에 보이는 건 피와 잿더미뿐이네.$B$B하지만 자연은 쉽게 쓰러지지 않네. 조금만 신경 쓰면, 이 그슬린 땅에 생명을 되찾아 올 수 있을 걸세.', `MaleText_loc4`='看看这惨状，$c！放眼望去，视线所及到处都是鲜血与灰烬。$B$B但自然不会如此轻易被打败。只要我们做些努力，这片焦灼的土地将会重焕生机。', `MaleText_loc5`='看看這個損害，$c!映入眼簾的只有鮮血和塵土。$B$B但大自然是不會那麼輕易就屈服的。只要付出努力，我們或許仍舊可以從這焦土中孕育新的生命。', `MaleText_loc7`='¡Observa esta devastación, $c! Sangre y cenizas, hasta donde alcanza la vista.$b$bPero no basta para derrotar a la naturaleza. Con un poco de esfuerzo, aún podemos hacer brotar vida de esta tierra arrasada.' WHERE `ID`=40400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대드루이드 룬토템 님이 이런 폐허 한가운데에 야영지를 만드시는 게 무모하다 생각하긴 했지만, 그래도 이곳에 혼자 오시게 할 순 없었어요.$B$B룬토템 님께서는 뭔가를 계획하고 계신 것 같아요. 뭔가 거대한 계획 말이에요.', `FemaleText_loc4`='我认为符文图腾在这毁灭的中心地带设营是在鲁莽行事，可我并不会让大德鲁伊只身来此。$B$B他在酝酿着什么计划。大计划。', `FemaleText_loc5`='我認為符文圖騰決定紮營在這片破壞的正中央是種無謀的舉動，但我絕不能讓大德魯伊獨自來此冒險。$B$B他必定在策劃著什麼重大的事情。', `FemaleText_loc7`='Pensé que Tótem de Runa era muy imprudente al levantar el campamento en medio de esta devastación, pero no iba a dejar que el archidruida viajara solo.$B$BEstá planeando algo. Algo importante.' WHERE `ID`=40401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 그림토템 녀석들은 곧 그들의 원래 자리로 돌아가게 될 겁니다!', `FemaleText_loc4`='这群恐怖图腾畜生很快就要去见他们的造物主了！', `FemaleText_loc5`='這些恐怖圖騰很快的會被送去見他們的創造者!', `FemaleText_loc7`='¡Estas bestias Tótem Siniestro pronto conocerán a su creador!' WHERE `ID`=40402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렌도우, 물길 여행자를 한 번 더 탈 수 있을까요?', `MaleText_loc4`='瑞恩多尔，我还能再搭乘一次水上旅行者吗？', `MaleText_loc5`='倫朵，可以再給我另一隻水路旅人坐騎嗎?', `MaleText_loc7`='Rendow, ¿puedo montarme en otro viajero de agua?', `FemaleText_loc1`='렌도우, 물길 여행자를 한 번 더 탈 수 있을까요?', `FemaleText_loc4`='瑞恩多尔，我还能再搭乘一次水上旅行者吗？', `FemaleText_loc5`='倫朵，可以再給我另一隻水路旅人坐騎嗎?', `FemaleText_loc7`='Rendow, ¿puedo montarme en otro viajero de agua?' WHERE `ID`=40403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 전사들이여, 위대하신 우리의 지도자 볼진 님께서 메아리 섬을 되찾을 준비를 하고 계시다.', `MaleText_loc4`='暗矛部族的战士们，我们的领袖，伟大的沃金已经准备好夺回回音群岛了。', `MaleText_loc5`='暗矛部族的戰士啊，我們的領袖、偉大的沃金，準備要將回音群島奪回來。', `MaleText_loc7`='Guerreros de la tribu Lanza Negra, nueh''tro líder, el gran Vol''jin, se prepara pa recuperar las Islas del Eco.' WHERE `ID`=40404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다가올 전투는 진정한 전사의 자격을 시험하는 무대이자, 우리의 충성심을 시험하는 무대이다.', `MaleText_loc4`='等待在前方的战斗将是对我们的战斗力和忠诚心的真正试炼。', `MaleText_loc5`='眼前的戰鬥是個真正的試煉，對於各位的戰士技巧以及忠誠心皆是。', `MaleText_loc7`='La batalla que se avecina será una verdadera prueba pa la habilidad de nueh''tros guerreros y su lealtad.' WHERE `ID`=40405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잃었던 우리 땅을 되찾고자 오늘 이곳, 센진 마을의 검은창 해안에 모였다!', `MaleText_loc4`='我们聚集在森金村的海岸，来夺回本属于我们的东西！', `MaleText_loc5`='我們大家聚在這裡，聚在森金村的海岸上，是為了取回屬於我們的東西!', `MaleText_loc7`='¡Nos reunimos aquí, en las costas de la Villa Sen''jin, para RECUPERAR lo que es nuestro por derecho!' WHERE `ID`=40406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 나아오라! 함께 메아리 섬을 해방하자! 잘라제인은 쓰러지고 말리라!', `MaleText_loc4`='来吧！我们将解放回音群岛！扎拉赞恩必将失败！', `MaleText_loc5`='站起來吧!就是現在!加入解放回音群島的行列!札拉贊恩必敗!', `MaleText_loc7`='¡Únanse a la liberación de las Islas Eco! ¡Zalazane CAERÁ!' WHERE `ID`=40407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조의 영혼들이 이번 전투에서 우리를 보살피실 것이다.', `MaleText_loc4`='祖先的灵魂在注视着我们，并在战场上帮助我们。', `MaleText_loc5`='先祖的魂魄眷顧著我們，他們將會在這場仗中助我們一臂之力。', `MaleText_loc7`='Los eh''píritus de nueh''tros anceh''tros nos observarán y nos ayudarán en la batalla.' WHERE `ID`=40408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조들께 자랑스러운 모습을 보이자! 용맹과 패기를 보여 드리자! 그분들의 영혼에 명예를 선사하자!', `MaleText_loc4`='要让他们为我们而骄傲！让他们看到你们的勇敢和强大！为祖先的英灵夺取新的光荣！', `MaleText_loc5`='讓他們感到驕傲!讓他們看看你的勇氣!你的剽悍!將榮耀獻給他們的魂魄!', `MaleText_loc7`='¡Que eh''tén orgullosos de nosotros! ¡Demueh''treles nueh''tro valor y nueh''tra ferocidad! ¡Honra a los eh''píritus!' WHERE `ID`=40409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그 무엇보다, 우리는 잘라제인에게 알려줄 것이다. 잘라제인의 시대는 끝났음을! 그리고 이제 우리의 것을 당당하게 돌려받을 것임을!', `MaleText_loc4`='最重要的是，我们要让扎拉赞恩明白，他的末日到了！他将把从我们这里夺走的一切归还给我们！', `MaleText_loc5`='最重要的是，我們要讓札拉贊恩知道他的末日到了!他會把屬於我們的東西還給我們!', `MaleText_loc7`='¡Y sobre todo, demoh''traremos a Zalazane que eh''ta vez ha llegao su fin! ¡Que nos devolverá los que nos peh''tenece por derecho propio!' WHERE `ID`=40410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인은 사술에 걸린 트롤 병력의 대부분을 큰 섬의 숲 안쪽에 숨겨두었습니다.', `MaleText_loc4`='扎拉赞恩让他的大多数巨魔妖术师藏在那座大岛上的树屋里面。', `MaleText_loc5`='札拉贊恩和他那些被施展妖術的食人妖們都藏在島上的蓬子裡。', `MaleText_loc7`='Zalazane tiene a la mayoría de los trols embrujaos escondíos debajo del dosel en la isla más grande.', `FemaleText_loc1`='잘라제인은 사술에 걸린 트롤 병력의 대부분을 큰 섬의 숲 안쪽에 숨겨두었습니다.', `FemaleText_loc4`='扎拉赞恩让他的大多数巨魔妖术师藏在那座大岛上的树屋里面。', `FemaleText_loc5`='札拉贊恩和他那些被施展妖術的食人妖們都藏在島上的蓬子裡。', `FemaleText_loc7`='Zalazane tiene a la mayoría de los trols embrujaos escondíos debajo del dosel en la isla más grande.' WHERE `ID`=40411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병력이 상당히 많습니다. 무언가 계략을 꾸미는 것 같습니다.', `MaleText_loc4`='他有一支规模很大的军队，而且他正在策划着一个阴谋。', `MaleText_loc5`='他的軍隊很強大，而且他正在那裡計畫一些陰謀。', `MaleText_loc7`='Tiene un gran ejército y eh''tá claro que planea algo.', `FemaleText_loc1`='병력이 상당히 많습니다. 무언가 계략을 꾸미는 것 같습니다.', `FemaleText_loc4`='他有一支规模很大的军队，而且他正在策划着一个阴谋。', `FemaleText_loc5`='他的軍隊很強大，而且他正在那裡計畫一些陰謀。', `FemaleText_loc7`='Tiene un gran ejército y eh''tá claro que planea algo.' WHERE `ID`=40412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 정찰병. 계속 수고 부탁한다. 하지만 지금은 휴식을 좀 취하도록. 이상.', `MaleText_loc4`='谢谢你，哨兵。你还要继续巡逻的工作。不过现在你应该去休息一下。解散。', `MaleText_loc5`='謝謝你，斥候。保持巡邏。至於現在，先去休息吧。解散。', `MaleText_loc7`='Gracias, explorador. Seguirás patrullando, pero ahora debes descansar. Retírate.' WHERE `ID`=40413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 랩터는 물건이고 사람이고 파괴하지 못하는 게 없지!', `MaleText_loc4`='我的迅猛龙能战胜任何事任何人！', `MaleText_loc5`='我的迅猛龍可以撕裂所有的人、所有的東西!', `MaleText_loc7`='¡Mi raptor puede destrozar LO QUE SEA y A QUIEN SEA!' WHERE `ID`=40414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 네가 내 망나니를 죽였어! 가만두지 않겠다!', `MaleText_loc4`='你！你这蠢货杀了我的屠夫！我要碾碎你！', `MaleText_loc5`='你!你這雜種殺了我的屠夫!我宰了你!', `MaleText_loc7`='¡Tú! ¡Tu chucho mató a mi Carnicero! ¡Te aplastaré!' WHERE `ID`=40415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련교관 데보란이 당신의 랩터에 도전할 상대를 보냈습니다.', `MaleText_loc4`='导师德沃兰给你的迅猛龙找来了个对手。', `MaleText_loc5`='講師迪佛連派出了一個對手來挑戰你的迅猛龍。', `MaleText_loc7`='El instructor Devoran envía un contrincante contra tu raptor.', `FemaleText_loc1`='훈련교관 데보란이 당신의 랩터에 도전할 상대를 보냈습니다.', `FemaleText_loc4`='导师德沃兰给你的迅猛龙找来了个对手。', `FemaleText_loc5`='講師迪佛連派出了一個對手來挑戰你的迅猛龍。', `FemaleText_loc7`='El instructor Devoran envía un contrincante contra tu raptor.' WHERE `ID`=40416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃의 조련사에게서 도망치십시오!', `MaleText_loc4`='快逃离炽焰训练师吧！', `MaleText_loc5`='快在熾熱導師抓到你前夾著尾巴逃走吧!', `MaleText_loc7`='¡Huye del instructor llameante!' WHERE `ID`=40417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 보여줄 게 있네. 자네의 그 두 눈으로 본다면 더 이해하기 쉬울 것일세.', `MaleText_loc4`='我要让你看样东西。亲眼看到它，你就会明白了。', `MaleText_loc5`='我有東西想讓你看。你親自看看會比較容易了解。', `MaleText_loc7`='Tengo que mostrarte algo. Lo entenderás mejor si lo ves con tus ojos.' WHERE `ID`=40418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭔가, 볼진? 난 전쟁 준비로 바쁘다.', `MaleText_loc4`='你想要什么，沃金？我正在忙着为战争做准备。', `MaleText_loc5`='你要做什麼，沃金?我正忙著策劃一場戰爭。', `MaleText_loc7`='¿Qué quieres, Vol''jin? Estoy ocupado planeando una guerra.' WHERE `ID`=40419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전투의 함성을 질러 다른 전투원들을 독려합니다.', `MaleText_loc4`='%s用一声战吼鼓舞起了其他战士的士气。', `MaleText_loc5`='%s以戰吼召集其他戰士!', `MaleText_loc7`='¡%s consigue el apoyo de otros combatientes con un rugido de batalla!' WHERE `ID`=40420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 들어 봐, 코렌 다이어브루는 미치광이야.

그 녀석이 가을 축제에 초대받지 못한 건 내 탓이 아니라고! 그런데도 녀석과 그의 검은무쇠 일당은 막무가내로 내 직원들을 두들겨 패고는 내가 만든 맥주를 모두 마셔버렸어.

누가 나서서 본때를 보여 줘야겠어!', `MaleText_loc4`='我告诉你，那个科林·烈酒是个疯子。

他没有受邀请参加美酒节的美酒竞赛不是我的错！但这并不能阻止他和他的黑铁同伙殴打我的雇员，还喝光了我的藏酒。

必须有人阻止他的暴行！', `MaleText_loc5`='我跟你說，那個寇仁·恐酒是個瘋子。

他沒被邀請參加啤酒節又不是我的錯!但是他不肯罷休，現在那些黑鐵矮人都在欺負我的員工，還搶我釀的酒來喝。

得找人解決這件事!', `MaleText_loc7`='Te digo que Coren Cerveza Temible está loco.

¡No es culpa MÍA que no le hayan invitado a competir en la Fiesta de la Cerveza! Pero eso no ha impedido que él y sus colegas del Hierro Negro hayan dado una paliza a mis empleados y se hayan bebido toda mi cerveza.

¡Alguien tiene que poner fin a esto!' WHERE `ID`=40421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코렌 다이어브루 전투 대기열에 등록합니다.', `MaleText_loc4`='排队等待科林·烈酒战斗。', `MaleText_loc5`='排入寇仁·恐酒之戰佇列。', `MaleText_loc7`='Hacer cola para la batalla de Coren Cerveza Temible.', `FemaleText_loc1`='코렌 다이어브루 전투 대기열에 등록합니다.', `FemaleText_loc4`='排队等待科林·烈酒战斗。', `FemaleText_loc5`='排入寇仁·恐酒之戰佇列。', `FemaleText_loc7`='Hacer cola para la batalla de Coren Cerveza Temible.' WHERE `ID`=40422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리군주 아훈을 반드시 막아야 해요.

정신 나간 황혼의 망치단 이교도들이 아훈을 정령의 감옥으로부터 소환하고 있어요. 아훈이 점점 형태를 갖춰 나가고 있다는 말이죠.

그가 우리의 세계로 완전히 들어온다면, 우린 영원한 겨울 속에 묻히고 말 거예요.', `FemaleText_loc4`='必须阻止冰霜领主埃霍恩。

现在他正在获得现实的躯体。暮光之锤的疯狂教徒们将它从元素牢狱中召唤了出来。

如果他完全进入我们的世界，他会用永恒的寒冬埋葬我们。', `FemaleText_loc5`='必須阻止冰霜領主艾胡恩。

即使在此時此刻他仍然持續在實體化，暮光之錘瘋狂的教徒們正試圖將他從他的元素監牢中召喚出來。

如果他完全進入我們的世界，他會用永恆的冬天把我們埋葬。', `FemaleText_loc7`='Hay que detener al Señor de la Escarcha Ahune.

En estos mismos instantes está tomando forma al ser invocado de su prisión elemental por los cultores locos del Martillo Crepuscular.

Si consigue entrar en nuestro mundo por completo, nos enterrará bajo el manto de un invierno perpetuo.' WHERE `ID`=40424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리 군주 아훈 전투 대기열에 등록합니다.', `MaleText_loc4`='排队等待冰霜之王埃霍恩之战。', `MaleText_loc5`='加入冰霜領主艾胡恩之戰佇列。', `MaleText_loc7`='Hacer cola para la batalla del Señor de la Escarcha Ahune.', `FemaleText_loc1`='서리 군주 아훈 전투 대기열에 등록합니다.', `FemaleText_loc4`='排队等待冰霜之王埃霍恩之战。', `FemaleText_loc5`='加入冰霜領主艾胡恩之戰佇列。', `FemaleText_loc7`='Hacer cola para la batalla del Señor de la Escarcha Ahune.' WHERE `ID`=40425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 도와 주십시오...

저주받은 기사를... 막아야만 합니다...

그에게 목숨을 잃은 자가 한둘이 아닙니다... 아직도 달이 뜨는 밤이면 그의 사냥은 어김없이 계속됩니다.', `MaleText_loc4`='请……救……

……无头骑士……必须阻止……

他杀了那么多人！每天月亮升起的时候，他还去寻找更多牺牲者！', `MaleText_loc5`='請...幫忙...

無頭騎士...必須被阻止...

他殺死了如此多人...卻仍在每夜月亮升起後四處尋找更多的被害人!', `MaleText_loc7`='...por favor, ayuda...

...El Jinete decapitado...debe ser detenido...

...¡Ha matado a tantos! Y, sin embargo, en cuanto sale la luna sigue cabalgando en busca de nuevas víctimas.' WHERE `ID`=40426;
