UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 정말 끝내 주겠는데요!', `MaleText_loc4`='这一定会很迷人！', `MaleText_loc5`='這一定會很有趣!', `MaleText_loc7`='¡Esto va a ser fascinante!', `FemaleText_loc1`='이거 정말 끝내 주겠는데요!', `FemaleText_loc4`='这一定会很迷人！', `FemaleText_loc5`='這一定會很有趣!', `FemaleText_loc7`='¡Esto va a ser fascinante!' WHERE `ID`=40439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땜장이 마을에 잘 왔네!', `MaleText_loc4`='欢迎来到侏儒区！', `MaleText_loc5`='歡迎來到地精區!', `MaleText_loc7`='¡Te gustará Ciudad Manitas!' WHERE `ID`=40441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼음 조각에서 빙하가 마구 몰려오며 부딪치는 장중한 소리가 울려 나옵니다. 또한, 그 한기 때문에 머릿속에는 생명도, 끝도 없는 겨울만이 떠오릅니다.', `MaleText_loc4`='这块碎冰中回荡着冰川切割地壳时深沉的碎裂声。它能够将你的思维变成没有生命，没有尽头的寒冬。', `MaleText_loc5`='這塊碎冰有著入侵的冰河分裂時深沉的回音。它的寒冷會把你的思緒帶到無盡而死寂的冬天。', `MaleText_loc7`='En este fragmento de hielo retumba el eco del estruendo profundo y sonoro de los glaciares que se desplazan. El frío transforma tus pensamientos en un invierno eterno y sin vida.' WHERE `ID`=40442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음 덩어리를 건드려 군주 아훈을 소환합니다.', `MaleText_loc4`='用这块石头召唤埃霍恩大人。', `MaleText_loc5`='干擾石塊並召喚艾胡恩領主。', `MaleText_loc7`='Toca la piedra e invoca a Lord Ahune.', `FemaleText_loc1`='얼음 덩어리를 건드려 군주 아훈을 소환합니다.', `FemaleText_loc4`='用这块石头召唤埃霍恩大人。', `FemaleText_loc5`='干擾石塊並召喚艾胡恩領主。', `FemaleText_loc7`='Toca la piedra e invoca a Lord Ahune.' WHERE `ID`=40443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진이 해골 더미 앞에 무릎 꿇고 주문을 외우기 시작합니다.', `MaleText_loc4`='沃金跪倒下去，开始了颂唱。', `MaleText_loc5`='沃金跪在頭骨堆前，然後開始詠唱。', `MaleText_loc7`='Vol''jin se arrodilla ante una pila de calaveras y entona un cántico.' WHERE `ID`=40444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호랑이의 혼을 다시 한 번 불러 주시겠습니까, 바니라?', `MaleText_loc4`='瓦妮拉，你会再次召唤猛虎之魂吗？', `MaleText_loc5`='你能再次呼喚猛虎之靈嗎，凡妮拉?', `MaleText_loc7`='¿Podrías invocar de nuevo al Espíritu del tigre, Vanira?', `FemaleText_loc1`='호랑이의 혼을 다시 한 번 불러 주시겠습니까, 바니라?', `FemaleText_loc4`='瓦妮拉，你会再次召唤猛虎之魂吗？', `FemaleText_loc5`='你能再次呼喚猛虎之靈嗎，凡妮拉?', `FemaleText_loc7`='¿Podrías invocar de nuevo al Espíritu del tigre, Vanira?' WHERE `ID`=40445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염 감시기를 방어하십시오!', `MaleText_loc4`='守卫防火结界！', `MaleText_loc5`='保護好火焰結界!', `MaleText_loc7`='¡Protege el guardallamas!' WHERE `ID`=40446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리했습니다! 화염 감시기를 방어했습니다.', `MaleText_loc4`='胜利！防火结界守住了。', `MaleText_loc5`='勝利!火焰結界防衛成功。', `MaleText_loc7`='¡Victoria! Has defendido el guardallamas.' WHERE `ID`=40447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인의 시대는 저물었다. 메아리 섬은 다시 검은창 부족의 땅이 될 것이다!', `MaleText_loc4`='扎拉赞恩就要完蛋了。回音群岛将再次属于暗矛部族！', `MaleText_loc5`='札拉贊恩沒時間了。回音群島將會再次回歸暗矛部族的懷抱!', `MaleText_loc7`='El tiempo de Zalazane se agota. ¡Las Islas del Eco volverán a manos de la tribu Lanza Negra!' WHERE `ID`=40448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 검은창 부족이 보금자리를 되찾았네! 자네의 도움이 없었다면 불가능했을 거야, $n. 자, 한 번 제대로 축하해 보세!', `MaleText_loc4`='暗矛部族回到了家园！$n，如果没有你的帮助，我们无法实现这个梦想。现在，让我们庆祝吧！', `MaleText_loc5`='暗矛部族不再無家可歸!$n，沒有你來幫忙的話我們根本沒辦法成功。現在呢，讓我們來慶祝吧!', `MaleText_loc7`='¡Los Lanza Negra vuelven a tener un hogar! Y no lo habríamos conseguido sin tu ayuda, $n. Ahora, ¡a celebrarlo!' WHERE `ID`=40449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구멍은 물의 세계로 이어진다네. 바다사냥꾼, 넵튤론의 영역이지.', `MaleText_loc4`='这个裂口通往水元素位面。猎潮者耐普图隆的国度。', `MaleText_loc5`='這個裂痕通往水之界域。獵潮者奈普圖隆的國度。', `MaleText_loc7`='Eh''ta brecha conduce al plano de agua. El reino de Neptulon, el Cazamarea''.' WHERE `ID`=40450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가와 황혼의 신도들이 같이 움직이고 있네. 이것이 바로 그들이 중점적으로 애쓰고 있는 부분일 게야.', `MaleText_loc4`='纳迦正在和暮光教派合作，而这就是他们努力的焦点所在。', `MaleText_loc5`='納迦和暮光教正在連手，而這就是他們努力的目的。', `MaleText_loc7`='Los nagas y el Culto Crepuscular trabajan juntos, y eh''te es el centro de sus eh''fuerzos.' WHERE `ID`=40451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전망이 좋지 않네. 사람을 더 모으지 못하면 대처하기 어려울 걸세.', `MaleText_loc4`='前景真是令人堪忧。可如果没有更多的人手，我们几乎什么都做不了。', `MaleText_loc5`='令人憂慮的考察。在沒有足夠的人手前我們能做的有限。', `MaleText_loc7`='Es una visión preocupante. Y no hay mucho que podamo'' hacer sin más hombres.' WHERE `ID`=40452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피즐과 포직의 쾌속선 좋아하시네! 이 녀석은 원래 제가 만든 작품이에요! 저들도, 래저릭도 아닌 바로 제가 만들었다고요!$B$B징키의 쾌속선이라 불리는 게 옳아요!', `FemaleText_loc4`='菲兹尔与普兹克赛艇平台——我的小宝贝儿！是我造出来的！不是他们，不是拉泽瑞克！$B$B它应该叫做金吉赛艇平台才对！', `FemaleText_loc5`='我去他辣妹的菲茲爾與普茲克的高速駁船!這是我造的!不是他們，不是拉澤瑞克!$B$B它應該叫做金基的高速駁船!', `FemaleText_loc7`='¡El Barcódromo de Fizzle y Pozzik, y una porra! ¡Yo construí esta cosa! ¡Ellos no, ni Razzeric! ¡Debería llamarse el Barcódromo de Jinky!' WHERE `ID`=40453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 전사들이 잘라제인 잔당을 깨끗이 처리하고 있습니다.', `MaleText_loc4`='战士们正在清除扎拉赞恩的余党。', `MaleText_loc5`='戰士們正在做善後工作，殲滅札拉贊恩剩下的爪牙。', `MaleText_loc7`='Los guerreros eh''tán terminando el trabajo de acabar con el reh''to de las creaciones de Zalazane.', `FemaleText_loc1`='우리 전사들이 잘라제인 잔당을 깨끗이 처리하고 있습니다.', `FemaleText_loc4`='战士们正在清除扎拉赞恩的余党。', `FemaleText_loc5`='戰士們正在做善後工作，殲滅札拉贊恩剩下的爪牙。', `FemaleText_loc7`='Los guerreros eh''tán terminando el trabajo de acabar con el reh''to de las creaciones de Zalazane.' WHERE `ID`=40454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금방 건설 인력을 투입할 수 있을 겁니다. 할 일이 참 많습니다.', `MaleText_loc4`='你现在可以随时派遣建筑工人开始工作了。现在有许多工作正等着他们呢。', `MaleText_loc5`='你現在隨時可以派出建築師了。有許多工作等著他們。', `MaleText_loc7`='Dentro de poco podrás enviar conh''tructores. Hay mucho trabajo por hacer.', `FemaleText_loc1`='금방 건설 인력을 투입할 수 있을 겁니다. 할 일이 참 많습니다.', `FemaleText_loc4`='你现在可以随时派遣建筑工人开始工作了。现在有许多工作正等着他们呢。', `FemaleText_loc5`='你現在隨時可以派出建築師了。有許多工作等著他們。', `FemaleText_loc7`='Dentro de poco podrás enviar conh''tructores. Hay mucho trabajo por hacer.' WHERE `ID`=40455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했네. 섬에 가서 건물 지을 준비를 하라고 전해 주게. 검은창 부족이여, 우리는 고향으로 돌아간다!', `MaleText_loc4`='谢谢你，侦察兵。告诉那些建筑工人，这片群岛需要他们。暗矛部族将重建家园！', `MaleText_loc5`='謝謝你，斥候。告訴那些建築師島上需要他們。暗矛食人妖終於又回家了!', `MaleText_loc7`='Gracias, explorador. Informa a los conh''tructores de que les necesitamos en las Islas. ¡Los Lanza Negra regresarán a casa!' WHERE `ID`=40456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 전사들이여, 센진의 아들 볼진 님께서 우리를 승리로 이끄셨다!', `MaleText_loc4`='暗矛部族的战士们，森金之子沃金将率领你们走向胜利！', `MaleText_loc5`='暗矛部族的戰士呀，森金之子沃金帶領我們打了場勝仗!', `MaleText_loc7`='¡Guerreros de la tribu Lanza Negra, Vol''jin, hijo de Sen''jin, nos ha guiao a la victoria!' WHERE `ID`=40457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 전사들의 용맹과 솜씨도 만천하에 알렸다!', `MaleText_loc4`='我们战士的勇气和力量无人可及！', `MaleText_loc5`='我們戰士的勇猛和戰技是有目共睹的!', `MaleText_loc7`='¡El valor y la habilidad de nueh''tros guerreros ha quedao patente pa que pueda veh''lo todo el mundo!' WHERE `ID`=40458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조들께서는 너희를 자랑스럽게 지켜보셨다, 형제들이여!', `MaleText_loc4`='兄弟们，我们的祖先正自豪地看着你们！', `MaleText_loc5`='先祖們驕傲地看顧著你們的行動，我的兄弟們!', `MaleText_loc7`='¡Hermanos, los anceh''tros han observao sus actos llenos de orgullo!' WHERE `ID`=40459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조들께 이 영광을! 위대한 브원삼디께 영광을! 감사의 표시로 공물을 바치리라!', `MaleText_loc4`='感谢祖先们！感谢伟大的邦桑迪！我们在此奉上我们感激的心情！', `MaleText_loc5`='感謝先祖庇佑!感謝偉大的伯昂撒姆第!我們全都會心存感激地獻上祭品的!', `MaleText_loc7`='¡Gracias a los anceh''tros! ¡Gracias al gran Bwonsamdi! ¡Todo haremos ofrendas de gratitud!' WHERE `ID`=40460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 도와준 호드 동맹들도 절대 잊지 않으리라! 이제 오늘의 대승리를 함께 축하할 시간이다!', `MaleText_loc4`='不要忘记我们盟友的帮助。不要忘记来支援我们的部落战士！现在，正是我们一同庆祝这个伟大胜利的时刻！', `MaleText_loc5`='別忘記盟友所伸出的援手，不要忘記前來援助的部落成員!現在該是慶祝的時刻了，一起慶祝這光輝的勝利!', `MaleText_loc7`='¡No debemos olvidar la ayuda de nueh''tros aliaos, de los miembros de la Horda que nos han ayudao! ¡Ahora es el momento de celebrar juntos eh''ta gran victoria!' WHERE `ID`=40461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 공격 작전이 톱니바퀴 돌아가 듯 딱딱 진행되도록 하는 게 제 임무예요.$B$B땜장이왕 멕카토크 님께서는 지금 전장에 계신데, 병력을 충원하러 조만간 돌아오실 거예요.$B$B멕카토크 님은 절대로 늦으시는 법이 없으시죠. 그러니까 멀리 가지 마세요. 금방 오실 테니까요.', `FemaleText_loc4`='我的任务就是确保整个进攻行动像时钟一样准确地进行。$B$B大工匠梅卡托克已经到战场去了，但他正计划返回这里，再将更多的部队带上战场。$B$B他从不会迟到，所以你应该在这里等他。', `FemaleText_loc5`='我的職責，是確保整場攻擊行動會像時鐘一樣精確。$B$B大工匠梅卡托克此刻已加入戰局，不過按照計畫，他隨時會回來補充更多兵員。$B$B他從來沒遲到過，所以待在這邊不要亂跑，他會來的。', `FemaleText_loc7`='Mi trabajo es asegurarme de que este asalto funciona como la maquinaria de un reloj.$b$bEl Manitas Mayor Mekkatorque está en el campo de batalla, pero tengo previsto que regrese en breve por más tropas. $b$bNunca suele retrasarse, así que quédate por aquí y podrás verle.' WHERE `ID`=40462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 조금 지연되고 있긴 하지만, $5071W분만 있으면 공격을 개시할 예정이에요.$B$B그러니까, 준비가 거의 다 끝났다는 말이죠. 봐요. 자이로콥터, 기계보행전차, 그리고 보병들까지 모두 준비를 마쳤잖아요.$B$B국왕 폐하께서 공격 시작 전에 몇 가지를 점검할 게 있으신가 봐요. 제발 공격이 제 시간에 시작되길 빌자고요. 아니면 전 해고될지도 몰라요!', `FemaleText_loc4`='我们的进度有一点落后了，但进攻仍然要按照计划，在$5071W分钟后开始。$B$B现在战前准备大致已经就绪，侏儒直升机、步行坦克和步兵都已就位。$B$B看样子，梅卡托克还在等待一些东西就位后才会下令开始进攻。让我们希望行动能够按时开始吧，否则我可就要丢工作了！', `FemaleText_loc5`='好吧!我們進度有些落後，不過按照計畫這次攻擊行動將在$5071W分鐘內展開。$B$B我的意思是，看起來一切皆已就緒，旋翼機、機械坦克和步兵單位都到齊了。$B$B看來梅卡托克在開打前要等的東西不多。希望我們能準時開戰，不然我可能就要失業啦!', `FemaleText_loc7`='¡De acuerdo! Nos hemos retrasado un poco, pero está previsto que el asalto comience en $5071W minutos.$b$bMe refiero a que todo está listo y los girocópteros, los mecanotanques y la infantería ya están aquí.$b$bParece que Mekkatorque está esperando unas cuantas cosas más antes de lanzar el asalto. ¡Espero que empecemos a la hora o puede que pierda mi trabajo!' WHERE `ID`=40463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_infectedwound.blp:20|t%s|1이;가; |cFF01FFE1파괴의 휩쓸기|r를 시전하려고 몸을 곧추 세웁니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_infectedwound.blp:20|t%s扬起身子，发动了|cFF01FFE1爆裂打击！|r', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_infectedwound.blp:20|t%s反擊了一次|cFF01FFE1碎裂掃擊!|r', `MaleText_loc7`='|TInterfaceIconsability_druid_infectedwound.blp:20|t¡%s se prepara para un |cFF01FFE1Flagelo devastador|r!' WHERE `ID`=40464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s|1이;가; |cFFFF6F00|Hspell:75218|h[화염의 기원]|h|r을 소환합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s开始施放|cFFFF6F00|Hspell:75218|h[烈焰祈祷]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s進行|cFFFF6F00|Hspell:75218|h[火焰召喚]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_elemental_totem.blp:20|t¡%s lanza una |cFFFF6F00|Hspell:75218|h[Invocación de llamas]|h|r!' WHERE `ID`=40465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러요! 멕카토크 님과 대화를 나누어야 한다고요! 공격을 빨리 시작하지 않으면, 우린 늦고 말 거예요.$B$B국왕 님은 늦는 거라면 질색을 하신다고요!', `FemaleText_loc4`='快点！你现在应该去找梅卡托克！如果我们不尽快开始进攻，我们就要耽误行动了。$B$B如果我们耽误的话，我们的首领可是要发火的！', `FemaleText_loc5`='快點!你必須和梅卡托克談談!如果我們不快點進攻，我們就會遲到。$B$B而我的老闆真的很討厭遲到!', `FemaleText_loc7`='¡Deprisa! ¡Deberías hablar con Mekkatorque! Si no lanzamos el asalto ya llegaremos tarde.$b$b¡Y a mi jefe no le gusta nada que lleguemos tarde!' WHERE `ID`=40466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배했습니다! 화염 감시기가 파괴되었습니다.', `MaleText_loc4`='失败了！防火结界被摧毁了。', `MaleText_loc5`='失敗!火焰結界已被破壞。', `MaleText_loc7`='¡Derrota! El guardallamas ha sido destruido.' WHERE `ID`=40467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222피에 굶주린 상어가 광분하여 먹잇감에게 달려듭니다!|r', `MaleText_loc4`='|cFFFF2222嗜血鲨鱼因为贪食而陷入疯狂！|r', `MaleText_loc5`='|cFFFF2222嗜血的鯊魚進入了益趨狂亂的狀態!|r', `MaleText_loc7`='|cFFFF2222¡El tiburón sediento de sangre entra en un frenesí hambriento!|r' WHERE `ID`=40468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피즐, 포직, 징키... 모두 자신이 우리를 살렸다고 생각하지. 하지만 진짜 구원자는 바로 나야! 내가 이 배를 만들었거든!$B$B이 배는 원래 래저릭의 쾌속선이라 불려야 한다고!', `MaleText_loc4`='菲兹尔、普兹克、金吉……他们都把自己当成我们的救星。但其实是我！船是我造的！$B$B它应该叫拉泽瑞克的赛艇平台！', `MaleText_loc5`='菲茲爾、普茲克、金基...他們全都認為是他們救了我們。但其實是我!船是我造的!$B$B它應該叫做拉澤瑞克的高速駁船!', `MaleText_loc7`='Fizzle, Pozzik, Jinky... Todos creen que fueron ellos los que nos salvaron. ¡Pero fui yo! ¡Yo construí el barco!$B$B¡Debería llamarse el Barcódromo de Razzeric!' WHERE `ID`=40469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 어떤 얼간이 녀석이 감히!', `MaleText_loc4`='什么？我要让那小矮子瞧瞧！', `MaleText_loc5`='什麼?我會給那垃圾瞧瞧!', `MaleText_loc7`='¿Qué? Ya le enseñaré yo a ese don nadie.' WHERE `ID`=40470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님께서 말씀하시길 자기가 돌아올 때까지 북을 치고 있으라고 하시더군요. 볼진 님을 기다리나요? 금방 돌아오셔서 섬을 되찾으실 겁니다.$B$B여기서 기다리면서 음악이나 감상하시지요!', `MaleText_loc4`='沃金要我在他回来之前一直敲这面鼓。如果你在等他，那么我可以告诉你，他很快就会回来夺回这些岛屿了。$B$B暂时先在这里等一等他，欣赏一下这音乐吧！', `MaleText_loc5`='沃金叫我一直打鼓直到他回來。如果你是在等他，等他奪回回音群島就會回來。$B$B在這裡等就好了，享受一下音樂!', `MaleText_loc7`='Vol''jin me ha dicho que siga tocando el tambor hah''ta que él regrese. Si le eh''tás eh''perando, volverá pronto pa recuperar las Islas.$b$b¡Eh''pérale aquí y disfruta de la música!' WHERE `ID`=40471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님께서 당신을 기다리십니다. 가서 대화를 나누시지요. 팔이 점점 아파 옵니다.$B$B빨리 메아리 섬을 공격하러 갔으면 좋겠습니다.', `MaleText_loc4`='沃金正在等你。你现在应该和他谈一谈。我的双臂已经有些疲惫了。$B$B但进攻回音群岛的行动很快就要开始了。', `MaleText_loc5`='沃金正在等你呢。你現在該去和他談談，我的手都酸了。$B$B這場對回音群島的戰鬥最好快點開始。', `MaleText_loc7`='Vol''jin te ha eh''tao eh''perando. Deberías hablar con él, ya se me eh''tán cansando los brazos.$b$bEl ataque a las Islas del Eco comenzará en breve.' WHERE `ID`=40472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디냐?! 그 녀석은 어디 있지?', `MaleText_loc4`='在哪儿？！他在哪儿？', `MaleText_loc5`='哪?!他在哪裡?', `MaleText_loc7`='¡¿Dónde?! ¿Dónde está?' WHERE `ID`=40473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할! 누가 이 인간을 죽인 거야!? 이거 큰일났군!', `MaleText_loc4`='该死的！是谁杀死了那个人类？这可不好！', `MaleText_loc5`='可惡!誰把人類給殺了!?這很不好!', `MaleText_loc7`='¡Maldición! ¿Quién mató al humano? Esto no está bien.' WHERE `ID`=40474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬 공격이 곧 시작됩니다!$B$B자, 흥분하지 마시고 마음을 가라앉히세요. $5071W분 뒤에 이 노래가 끝나면, 바로 출발합니다.', `MaleText_loc4`='对回音群岛的进攻很快就要开始了！$B$B坐下来，放松一下，这首歌将在$5071W分钟内结束，然后我们就要出发了。', `MaleText_loc5`='我們即將攻擊回音群島!$B$B坐好，放輕鬆，這首歌再過$5071W分鐘就會結束，然後我們就出發。', `MaleText_loc7`='¡Pronto comenzará el ataque a las Islas del Eco!$b$bSiéntate y relájate, eh''ta canción terminará en $5071W minutos y entonces nos pondremos en marcha.' WHERE `ID`=40475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 세계의 압력에서 벗어난 %s|1이;가; 생명력을 회복합니다.', `MaleText_loc4`='没有了来自两个领域的压力，%s开始重生了。', `MaleText_loc5`='在兩個國度中都沒有壓力的狀況下，%s開始再生。', `MaleText_loc7`='Al no haber presión en ambos reinos, %s empieza a regenerarse.' WHERE `ID`=40476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈 님의 지도력과 우리의 단결력이라면 적을 모두 무찌를 수 있을 것입니다!', `MaleText_loc4`='古加尔的英明领导加上我们的精诚团结，我们一定能将敌人粉碎！', `MaleText_loc5`='以丘加利為首，我們將摧毀所有與我們對立的敵人!', `MaleText_loc7`='¡Con el liderazgo de Cho''gall y el sentimiento de unidad entre nuestras filas, aplastaremos a todos nuestros enemigos!' WHERE `ID`=40477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222작살포를 발사하십시오!|r', `MaleText_loc4`='|cFFFF2222发射鱼叉！|r', `MaleText_loc5`='|cFFFF2222發射魚叉獵槍!|r', `MaleText_loc7`='|cFFFF2222¡Disparar cañón de arpón!|r' WHERE `ID`=40478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 무슨 일인가요?', `MaleText_loc4`='这里出了什么事？', `MaleText_loc5`='這裡是怎麼回事?', `MaleText_loc7`='¿Qué ocurre aquí?', `FemaleText_loc1`='여기 무슨 일인가요?', `FemaleText_loc4`='这里出了什么事？', `FemaleText_loc5`='這裡是怎麼回事?', `FemaleText_loc7`='¿Qué ocurre aquí?' WHERE `ID`=40479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 해야 하나요?', `MaleText_loc4`='我们该怎样做？', `MaleText_loc5`='我們怎麼做呢?', `MaleText_loc7`='¿Cómo lo hacemos?', `FemaleText_loc1`='어떻게 해야 하나요?', `FemaleText_loc4`='我们该怎样做？', `FemaleText_loc5`='我們怎麼做呢?', `FemaleText_loc7`='¿Cómo lo hacemos?' WHERE `ID`=40480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬을 되찾을 준비를 시작할 걸세. 잘라제인은 부두 마법을 사용하여 마치 자신이 죽은 것처럼 사람들을 속이고는, 고대부터 내려오는 암흑의 의식을 거행하고 있지.$B$B녀석은 우리가 공격해 올 것을 알고 있네. 그러니까 우리도 단단히 준비해야지.', `MaleText_loc4`='我们正在为夺回回音群岛做准备。扎拉赞恩一直在施展他的黑暗魔法，操纵傀儡，进行古老的黑暗仪式。$B$B他知道我们的行动，所以我们必须做好万全的准备。', `MaleText_loc5`='我們會準備好奪回回音群島。札拉贊恩已經用他的巫毒魔法肆虐好一陣子了，使人們相信他已經死亡，並施展古老而黑暗的儀式。$B$B他知道我們會來，所以我們得確保我們已經準備好。', `MaleText_loc7`='Eh''tamos preparándonos pa recuperar las Islas del Eco. Zalazane lleva tiempo trabajando en su vudú, convenciendo a la gente de que eh''tá mueh''to y celebrando antiguos rituales oscuros.$b$bSabe que vamos a atacar, así que tenemos que eh''tar seguros de ir preparados.' WHERE `ID`=40481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리 섬에 있는 동료들의 도움이 필요하네.$B$B젠타브라는 오랫동안 섬에 있는 동물들을 관장하고 있네. 그녀와 동물들의 도움이 필요하네.$B$B브원삼디는 메아리 섬의 죽은 자들을 다스리는 강력한 로아라네. 우리의 작전이 성공하려면 그의 협조가 필수적이지.$B$B이들이 우리와 함께하기만 한다면, 잘라제인과 그의 조종을 받는 트롤들을 무찌르는 건 시간문제네! 그건 즉, 메아리 섬이 검은창 부족의 품으로 돌아온다는 말이지!', `MaleText_loc4`='如果要成功地夺回这些岛屿，我们就需要有援军的帮助。$B$B岑塔布拉一直在照看这片群岛上的动物们。我们需要她和那些动物的帮助。$B$B邦桑迪是一位强大的神灵。他控制着这片群岛上死者们的灵魂。他的祝福对我们是至关重要的。$B$B当我们取得他们的援助之后，扎拉赞恩和被他控制的巨魔将必败无疑！那时，回音群岛就会回到暗矛部族的怀抱！', `MaleText_loc5`='我們在島上需要盟友的協助。$B$B贊塔布拉已經照料島上的動物好一陣子了。我們需要她和動物們的協助。$B$B伯昂撒姆第是強大的羅亞，能在島上控制亡者的靈魂。對於我們的進攻，他的祝福是不可或缺的。$B$B等我們的盟友加入我們，札拉贊恩和被他控制心靈的食人妖們將會毫無勝算!然後，回音群島又將屬於暗矛部族!', `MaleText_loc7`='Necesitamos la ayuda de nueh''tros aliaos pa recuperar las Islas.$b$bZent''abra lleva tiempo cuidando de los animales de esas Islas. Necesitamos su ayuda y la de esas criaturas.$b$bBwonsamdi es un Loa muy poderoso que controla los eh''píritus de los mueh''tos de las Islas. Su bendición es fundamental pa el éxito de nueh''tro ataque.$b$bUna vez nueh''tros aliaos se unan a nosotros, ¡Zalazane y su ejército de trols controlados mentalmente no tendrán ni una opoh''tunidad! ¡Entonces las Islas del Eco volverán a ser de los Lanza Negra!' WHERE `ID`=40482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 신선한 고기 냄새에 정신이 쏠립니다.', `MaleText_loc4`='%s被鲜肉的气味弄得心烦意乱。', `MaleText_loc5`='%s被新鮮的肉所發出的味道吸引了。', `MaleText_loc7`='%s se distrae con el olor de la carne fresca.' WHERE `ID`=40483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 좀 있어! 롬오그가 머리 때려줄 거야!', `MaleText_loc4`='站着别动！罗姆欧格要打碎你的脑袋！', `MaleText_loc5`='站好!!羅姆歐格敲碎你的頭骨!', `MaleText_loc7`='¡Quieto! ¡Rom''ogg aplastar tú!' WHERE `ID`=40484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들은 분명히 우리 배를 습격한 놈들이오. 하지만 사라진 내 동료를 찾을 수가 없군. 그들을 어디로 데려갔을까?', `MaleText_loc4`='显然是这些人对我们的船只发动了突袭，可我没看见任何失踪者。他们被带到哪儿去了？', `MaleText_loc5`='我確定就是他們襲擊了我們的船，但我沒看見任何失蹤的同伴。他們被帶去哪了?', `MaleText_loc7`='Estos son los que asaltaron nuestros barcos, sin duda, pero no veo a ninguno de nuestros desaparecidos. ¿Adónde se los llevaron?' WHERE `ID`=40485;
