UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 저희를 도와 주셔서 감사합니다.', `MaleText_loc4`='感谢你帮助我们作战。', `MaleText_loc5`='謝謝你在我們這場戰鬥中伸出的援手。', `MaleText_loc7`='Gracias p''o ayuda''nos en la batalla.', `FemaleText_loc1`='전투에서 저희를 도와 주셔서 감사합니다.', `FemaleText_loc4`='感谢你帮助我们作战。', `FemaleText_loc5`='謝謝你在我們這場戰鬥中伸出的援手。', `FemaleText_loc7`='Gracias p''o ayuda''nos en la batalla.' WHERE `ID`=40489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조들의 도움이 없었다면, 아직도 우린 잘라제인을 두려워 하며 살고 있었을 겁니다.', `MaleText_loc4`='我们的祖先，如果没有你们的帮助，我们仍然会畏惧扎拉赞恩。', `MaleText_loc5`='各位先祖，如果不是因為你們的幫助，我們還活在札拉贊恩帶來的恐懼之中呢。', `MaleText_loc7`='Anceh''tros, sin vueh''tra ayuda, todavía seguiríamos temiendo a Zalazane.', `FemaleText_loc1`='선조들의 도움이 없었다면, 아직도 우린 잘라제인을 두려워 하며 살고 있었을 겁니다.', `FemaleText_loc4`='我们的祖先，如果没有你们的帮助，我们仍然会畏惧扎拉赞恩。', `FemaleText_loc5`='各位先祖，如果不是因為你們的幫助，我們還活在札拉贊恩帶來的恐懼之中呢。', `FemaleText_loc7`='Anceh''tros, sin vueh''tra ayuda, todavía seguiríamos temiendo a Zalazane.' WHERE `ID`=40490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 자의 영혼이 계속 우리를 굽어살피시길.', `MaleText_loc4`='愿死去的英灵继续护佑你。', `MaleText_loc5`='願逝者的靈魂繼續眷顧著我們。', `MaleText_loc7`='Que los eh''píritus de los mueh''tos nos guarden.', `FemaleText_loc1`='죽은 자의 영혼이 계속 우리를 굽어살피시길.', `FemaleText_loc4`='愿死去的英灵继续护佑你。', `FemaleText_loc5`='願逝者的靈魂繼續眷顧著我們。', `FemaleText_loc7`='Que los eh''píritus de los mueh''tos nos guarden.' WHERE `ID`=40491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이여, 우리를 인도해 주셔서 감사합니다.', `MaleText_loc4`='感谢你们的指引，伟大的英灵。', `MaleText_loc5`='靈魂啊，感謝你們的指引。', `MaleText_loc7`='Gracias por vueh''tros consejos, eh''píritus.', `FemaleText_loc1`='영혼들이여, 우리를 인도해 주셔서 감사합니다.', `FemaleText_loc4`='感谢你们的指引，伟大的英灵。', `FemaleText_loc5`='靈魂啊，感謝你們的指引。', `FemaleText_loc7`='Gracias por vueh''tros consejos, eh''píritus.' WHERE `ID`=40492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브원삼디여, 전투에서 목숨을 잃은 형제들을 인도하소서.', `MaleText_loc4`='邦桑迪，请指引那些战死的勇士们。', `MaleText_loc5`='指引在戰鬥中死亡的人們，伯昂撒姆第。', `MaleText_loc7`='Guía a los que han mueh''to en la batalla, Bwonsamdi.', `FemaleText_loc1`='브원삼디여, 전투에서 목숨을 잃은 형제들을 인도하소서.', `FemaleText_loc4`='邦桑迪，请指引那些战死的勇士们。', `FemaleText_loc5`='指引在戰鬥中死亡的人們，伯昂撒姆第。', `FemaleText_loc7`='Guía a los que han mueh''to en la batalla, Bwonsamdi.' WHERE `ID`=40493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 공물이지만 감사의 표시이니 받아 주십시오.', `MaleText_loc4`='这只是一份可怜的奉献，但它代表了我对您的谢意。', `MaleText_loc5`='我獻上此祭品感謝您的幫忙，雖然這不是什麼豐厚大禮。', `MaleText_loc7`='Es una ofrenda muy pobre, pero tómala como agradecimiento por tu ayuda.', `FemaleText_loc1`='보잘것없는 공물이지만 감사의 표시이니 받아 주십시오.', `FemaleText_loc4`='这只是一份可怜的奉献，但它代表了我对您的谢意。', `FemaleText_loc5`='我獻上此祭品感謝您的幫忙，雖然這不是什麼豐厚大禮。', `FemaleText_loc7`='Es una ofrenda muy pobre, pero tómala como agradecimiento por tu ayuda.' WHERE `ID`=40494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 동굴에서 기어나왔군? 곧 여군주님이 널 소유하실 것이다.', `MaleText_loc4`='啊，你离开了你的藏身洞？女士很快就会取你性命的。', `MaleText_loc5`='啊，所以你離開洞穴了嗎?女士很快就會注意到你的。', `MaleText_loc7`='Ah, ¿saliste de tu agujero? La señora te reclamará pronto.' WHERE `ID`=40495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 내 일을 과소평가하지 않았으면 하는 소망이 있소. 내가 직접 상어를 고꾸라뜨리고 장어를 비틀지 않는다고 해서, 내가 하는 일이 보잘것없는 건 아니지 않소?', `MaleText_loc4`='要是有谁能严肃对待我的工作，我会感激不尽。虽然我干的不是像和鲨鱼摔跤或是把鳗鱼打结那样的活儿，可不代表这就不重要。', `MaleText_loc5`='如果有人能認真看待我的工作我會很感激。我沒跟鯊魚摔跤和沒把鰻魚綁在一起不代表我做的就是不重要的。', `MaleText_loc7`='Me gustaría que alguien se tomara en serio mi trabajo. Solo porque no estoy luchando con tiburones o haciendo nudos con anguilas no quiere decir que esto no sea importante.' WHERE `ID`=40496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흩어지세요! 투사 분대가 오고 있어요!', `FemaleText_loc4`='住手！大块头保安来了！', `FemaleText_loc5`='住手!蠻卒隊員快來了!', `FemaleText_loc7`='¡Dejadlo ya! ¡Se acerca el pelotón de zoquetes!' WHERE `ID`=40497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분노에 차 울부짖습니다!', `MaleText_loc4`='%s愤怒地咆哮着！', `MaleText_loc5`='%s憤怒地吼叫!', `MaleText_loc7`='¡%s ruge con furia!' WHERE `ID`=40498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화났습니다. 도망치십시오!', `MaleText_loc4`='%s发怒了，跑吧！', `MaleText_loc5`='%s發怒了，快逃!', `MaleText_loc7`='%s está enfadado. ¡Huye!' WHERE `ID`=40499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고대정령의 눈빛은 광대하고 깊습니다.>$B$B<이 생명체가 당신이 이해할 수 없는 말로 천천히 말합니다. 서늘한 느낌이 등줄기를 타고 흐릅니다. 당신은 공포와 혼란에 압도됩니다.>', `MaleText_loc4`='<上古半神的眼睛巨大而深邃。>$B$B<它说话的速度很慢。你也听不懂它所说的语言。寒意爬上了你的脊骨，恐惧和困惑占据了你的心灵。>', `MaleText_loc5`='<先祖的雙眼深遂且巨大。>$B$B<這個生物以響亮的聲音說話，用的是你不懂的語言。寒冷刺透了你的背脊。你被恐懼和混亂的感覺所佔據了。>', `MaleText_loc7`='<Los ojos del ancestro son enormes y profundos.>$b$b<La criatura habla lentamente, en un idioma que no entiendes. Un escalofrío te recorre la espalda. Te embarga un sentimiento de terror y confusión.>' WHERE `ID`=40500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<거북이 고대정령이 천천히 눈을 뜨자, 깊은 고통과 두려움이 나타납니다.>', `MaleText_loc4`='<上古半神缓缓地张开眼睛，那双眼睛如同充满痛苦与畏惧的深潭。>', `MaleText_loc5`='<先祖的眼睛慢慢地打開，露出了汪洋般地痛苦和恐懼。>', `MaleText_loc7`='<Los ojos del ancestro se abren lentamente, revelando profundos pozos de miedo y dolor.>' WHERE `ID`=40501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 햇볕에 서 있지 말고 이리 들어오세요.$B$B마실 것이라도 드릴까요? 여기는 정말 아무것도 할 게 없어요.', `FemaleText_loc4`='嘿，快进来乘乘凉。$B$B我帮你弄点儿喝的吧？反正我在这儿也没其它事情可做。', `FemaleText_loc5`='喂，快從外面進來。$B$B想喝些什麼嗎?反正我在這也沒什麼事情好做。', `FemaleText_loc7`='Oye, resguárdate del sol.$b$b¿Quieres algo de beber? No tengo nada más que hacer.' WHERE `ID`=40502;
