UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 안 돼! 이건 우리 것이다...', `MaleText_loc4`='不——不！这个是我们的……', `MaleText_loc5`='不!不!這個是我們的...', `MaleText_loc7`='No. ¡No! Este es nuestro...' WHERE `ID`=40510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 손아귀에서 쉽게 벗어날 수 없다...', `MaleText_loc4`='主人的掌控没那么容易被脱离……', `MaleText_loc5`='主人的掌握不是那麼容易就能切斷的...', `MaleText_loc7`='El vínculo del maestro no se corta tan fácilmente...' WHERE `ID`=40511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 저주받을... 연약한 존재가!', `MaleText_loc4`='可怜的……一袋……肉！', `MaleText_loc5`='爛掉的...腐肉!', `MaleText_loc7`='¡Maldito... saco... de carne!' WHERE `ID`=40512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재! 넌 선을 넘었다.', `MaleText_loc4`='凡人！你越界了。', `MaleText_loc5`='凡人!你管得太多了!', `MaleText_loc7`='¡Mortal! Te estás extralimitando.' WHERE `ID`=40513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께 이런 모욕을 안겨드릴 순 없다!', `MaleText_loc4`='主人不会容忍这种冒犯！', `MaleText_loc5`='主人不能容忍這種侮辱!', `MaleText_loc7`='¡El maestro no tolerará este insulto!' WHERE `ID`=40514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고대정령의 검고 거대한 눈이 당신을 못 믿겠다는 듯 응시합니다.>', `MaleText_loc4`='<上古半神巨大的黑眼睛盯着你，眼睛里流露出不信任的神情。>', `MaleText_loc5`='<先祖巨大的黑色雙眼質疑地看著你。>', `MaleText_loc7`='<Los enormes ojos oscuros del ancestro te miran con desconfianza.>' WHERE `ID`=40515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생각엔 우리 형제들이 고블린들에게 조치를 취해야 한다고 봐요. 소문으로는 고블린 한 명이 축구탄으로 대격변을 일으켰다죠!$B$B더 늦기 전에 이 녀석들을 박멸해야 해요!', `MaleText_loc4`='要是你问我的话，我认为我的兄弟应该解决这些地精！据说他们当中有人用足球炸弹引发了大灾变！$B$B我们得尽快除掉他们，再晚就来不及了！', `MaleText_loc5`='如果你問我，我會認為我的兄弟應該對這些哥布林做出些處理!謠言說是他們其中一個引爆了足球炸彈才導致大災變!$B$B我們必須在還來得及前將他們全部處理掉!', `MaleText_loc7`='Si quieres mi opinión, creo que mi hermano debería hacer algo con todos estos goblins. ¡Dicen que uno de ellos desencadenó el Cataclismo con un bombalón!$b$b¡Tenemos que deshacernos de todos ellos antes de que sea demasiado tarde!' WHERE `ID`=40516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징키, 쾌속선 잠수모를 하나 더 받을 수 있겠습니까?', `MaleText_loc4`='金吉，能再给我一个赛艇平台潜水头盔吗？', `MaleText_loc5`='金基，我可以再要一個暴衝潛水頭盔嗎?', `MaleText_loc7`='Jinky, ¿me das otra escafandra del Barcódromo?', `FemaleText_loc1`='징키, 쾌속선 잠수모를 하나 더 받을 수 있을까요?', `FemaleText_loc4`='金吉，能再给我一个赛艇平台潜水头盔吗？', `FemaleText_loc5`='金基，我可以再要一個暴衝潛水頭盔嗎?', `FemaleText_loc7`='Jinky, ¿me das otra escafandra del Barcódromo?' WHERE `ID`=40517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼요, 아직 여분이 쌓이고 쌓였는걸요.', `FemaleText_loc4`='喔好的，我这儿还有几百万个没人要呢。', `FemaleText_loc5`='噢好，我有一百萬個沒在用的。', `FemaleText_loc7`='Ah, sí, los tengo a docenas por todas partes.' WHERE `ID`=40518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 거룻배 본 적 있으십니까? 찾을 수가 없습니다!', `MaleText_loc4`='看见我的赛艇了吗？我找不到它了！', `MaleText_loc5`='你有看到我的河艇嗎?我到處都找不到!', `MaleText_loc7`='¿Has visto mi barco fluvial? ¡No lo encuentro por ninguna parte!', `FemaleText_loc1`='제 거룻배 본 적 있으세요? 찾을 수가 없네요!', `FemaleText_loc4`='看见我的赛艇了吗？我找不到它了！', `FemaleText_loc5`='你有看到我的河艇嗎?我到處都找不到!', `FemaleText_loc7`='¿Has visto mi barco fluvial? ¡No lo encuentro por ninguna parte!' WHERE `ID`=40519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지, 친구!', `MaleText_loc4`='当然，$g小伙子:小姑娘;！', `MaleText_loc5`='當然!', `MaleText_loc7`='¡Faltaría más, $gchico:chica;!' WHERE `ID`=40520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 녀석들이 아니었다면 이런 난장판이 벌어지지 않았을 거야!$B$B노움들이 만든 영토 확장 장치를 비롯한 말도 안 되는 기기들이 대격변의 원인이란 건 이미 기정사실이지!', `MaleText_loc4`='要不是因为那些侏儒，我们怎么会陷入这种混乱！$B$B众所周知，他们才是大灾变的罪魁祸首！引起灾难的就是他们那些能放大世界的装置和诸如此类的破烂！', `MaleText_loc5`='如果不是因為地精我們根本不會像現在這樣!$B$B很多人都知道就是因為他們發明了一堆放大縮小的裝置才造成了這次的大災變，除了大災變，還有其他亂七八糟的事!', `MaleText_loc7`='¡No estaríamos metidos en este lío si no fuera por los gnomos!$b$bEs un hecho conocido que fueron ellos los que provocaron el Cataclismo con sus cacharros de agrandamiento del mundo o lo que sea.' WHERE `ID`=40521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마?', `MaleText_loc4`='妈妈？', `MaleText_loc5`='媽媽?', `MaleText_loc7`='¿Mamá?' WHERE `ID`=40522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배가 가라앉지 않게 내가 할 수 있는 일은 그게 전부야. 게다가 여기에서 아직 피즐처럼 잘난 체 하는 원숭이들을 처리해야 해!', `MaleText_loc4`='我已经尽力让这艘船不至于散架，我能做的就这么多，而且我还得腾出精力去对付像菲兹尔那样自吹自擂的小丑！', `MaleText_loc5`='我現在要讓這艘船不會支離破碎就已經很難了，同時還要應付像是菲茲爾這種大蠢蛋!', `MaleText_loc7`='¡Es todo lo que puedo hacer para evitar que este barco se haga pedazos, y además tengo que aguantar a bufones engreídos como Fizzle!' WHERE `ID`=40523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누누이 말하지만 이 녀석은 절 미치게 해요! 설마 고블린이 정말로 쾌속선처럼 굉장한 배를 운항하는 데 도움이 될 거라 믿으시진 않겠죠?$B$B이 녀석들이 잘하는 거라곤 뭐든 폭파시키는 건데, 그조차도 한 절반의 경우엔 자신들을 날려버리는 녀석들이라고요!', `MaleText_loc4`='我告诉你，这家伙快要把我逼疯了！难道真有人相信，地精能帮忙完成像这座赛艇驳船平台一样的宏伟之作？$B$B他们唯一的本事就是炸东西，而且多半炸飞的是自己！', `MaleText_loc5`='跟你說!這個人快把我弄瘋了!有人真的相信一個哥布林能讓高速駁船做出什麼了不起的事嗎?$B$B他們只知道如何把東西炸爛，而且有一半的時間還真的都在亂炸東西!', `MaleText_loc7`='¡Te digo que ese tipo me está volviendo loco! ¿De verdad hay alguien que crea que un goblin podría ayudar a gobernar algo tan magnífico como el Barcódromo?' WHERE `ID`=40524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물이다! 괴물이 우리 보물을 약탈하러 왔다!', `MaleText_loc4`='怪物！怪物来抢我们的金子了！', `MaleText_loc5`='怪物!怪物來搶我們的金幣了!', `MaleText_loc7`='¡Monstruos! ¡Monstruos que han venido a llevarse nuestro oro!', `FemaleText_loc1`='괴물이다! 괴물이 우리 보물을 약탈하러 왔다!', `FemaleText_loc4`='怪物！怪物来抢我们的金子了！', `FemaleText_loc5`='怪物!怪物來搶我們的金幣了!', `FemaleText_loc7`='¡Monstruos! ¡Monstruos que han venido a llevarse nuestro oro!' WHERE `ID`=40525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 추악한 괴물이 있다니! 도대체 우리가 어디에 정박한 거지?', `MaleText_loc4`='我们这是在哪儿着陆了，怎么会有这么恶心的怪物？！', `MaleText_loc5`='我們降落在哪?怎麼會有這種醜陋的生物?!', `MaleText_loc7`='¿En qué tierra estamos que tiene criaturas tan horripilantes?', `FemaleText_loc1`='이렇게 추악한 괴물이 있다니! 도대체 우리가 어디에 정박한 거지?', `FemaleText_loc4`='我们这是在哪儿着陆了，怎么会有这么恶心的怪物？！', `FemaleText_loc5`='我們降落在哪?怎麼會有這種醜陋的生物?!', `FemaleText_loc7`='¿En qué tierra estamos que tiene criaturas tan horripilantes?' WHERE `ID`=40526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아악! 아아아아아아아아아아아악!', `MaleText_loc4`='啊！啊！！', `MaleText_loc5`='啊啊啊啊啊啊!啊啊啊啊啊啊啊啊啊!', `MaleText_loc7`='¡Aaaaaaaaaahhh! ¡AAAAAAAAAAAHHHHHH!!', `FemaleText_loc1`='아아아아아아악! 아아아아아아아아아아아악!', `FemaleText_loc4`='啊！啊！！', `FemaleText_loc5`='啊啊啊啊啊啊!啊啊啊啊啊啊啊啊啊!', `FemaleText_loc7`='¡Aaaaaaaaaahhh! ¡AAAAAAAAAAAHHHHHH!!' WHERE `ID`=40527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라! 없애버리자!', `MaleText_loc4`='杀了那只蠢猪！让它的血溅出来！', `MaleText_loc5`='殺了豬!放出血!', `MaleText_loc7`='¡Mata al cerdo! ¡¡Derrama su sangre!!', `FemaleText_loc1`='죽여라! 없애버리자!', `FemaleText_loc4`='杀了那只蠢猪！让它的血溅出来！', `FemaleText_loc5`='殺了豬!放出血!', `FemaleText_loc7`='¡Mata al cerdo! ¡¡Derrama su sangre!!' WHERE `ID`=40528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 자를 보호해라! 살덩이얼굴을 보호해!', `MaleText_loc4`='保护那个智者！保护肉脸！', `MaleText_loc5`='保護智者!保護肉臉!', `MaleText_loc7`='¡Protege al sabio! ¡Protege a Carnecara!', `FemaleText_loc1`='현명한 자를 보호해라! 살덩이얼굴을 보호해!', `FemaleText_loc4`='保护那个智者！保护肉脸！', `FemaleText_loc5`='保護智者!保護肉臉!', `FemaleText_loc7`='¡Protege al sabio! ¡Protege a Carnecara!' WHERE `ID`=40529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 나를 산채로 데려가지는 못할걸!', `MaleText_loc4`='你永远别想活捉我！', `MaleText_loc5`='你永遠不可能活捉我!', `MaleText_loc7`='¡Nunca me atraparás vivo!', `FemaleText_loc1`='절대로 나를 산채로 데려가지는 못할 거야!', `FemaleText_loc4`='你永远别想活捉我！', `FemaleText_loc5`='你永遠不可能活捉我!', `FemaleText_loc7`='¡Nunca me atraparás viva!' WHERE `ID`=40530;
