UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과거에서 헤매고 있습니다. 즉각 돌아가십시오.', `MaleText_loc4`='你在偏离过往事件。快调头。', `MaleText_loc5`='你正被過往的事件所迷惑。馬上回頭。', `MaleText_loc7`='Te estás desviando de los eventos del pasado. Da la vuelta inmediatamente.', `FemaleText_loc1`='과거에서 헤매고 있습니다. 즉각 돌아가십시오.', `FemaleText_loc4`='你在偏离过往事件。快调头。', `FemaleText_loc5`='你正被過往的事件所迷惑。馬上回頭。', `FemaleText_loc7`='Te estás desviando de los eventos del pasado. Da la vuelta inmediatamente.' WHERE `ID`=40535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노겐포저 씨, 서류 작업은 다 준비 됐어요. 제 부하들이 당신의 결정을 기다리고 있답니다.', `FemaleText_loc4`='文书已经准备好，就等你签字了，马林。我的人正等着你做个决定。', `FemaleText_loc5`='文件等著你簽名，馬林。我的人都在等待你的決定。', `FemaleText_loc7`='Los papeles están listos para que los firmes, Marin. Mi pueblo está a la espera de tu decisión.' WHERE `ID`=40536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 노겐포저 씨, 호드와 한통속이 돼서 중립 무역자인 당신의 명성을 더럽히는 일은 하지 않으시겠죠!', `FemaleText_loc4`='天哪，诺格弗格先生，我知道你不希望和部落建立更为紧密的联系，怕因此损害你作为中立贸易实体的声誉！', `FemaleText_loc5`='嘿，諾格弗格先生，我知道你不會想因為跟部落走得比較近而傷害你中立立場的聲望!', `FemaleText_loc7`='¡Cielos, Sr. Tragonublo, ya sé que no querrías perjudicar tu reputación como entidad comercial neutral estrechando lazos con la Horda!' WHERE `ID`=40537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 웃기는군요. 노움과 거래한다는 게 어떤 건지 아시잖아요.', `FemaleText_loc4`='这太可笑了。你知道和侏儒做生意是什么感觉。', `FemaleText_loc5`='這真好笑。你知道要跟地精做生意是什麼樣的情況。', `FemaleText_loc7`='Esto es de risa. Ya sabes lo que es intentar hacer negocios con gnomos.' WHERE `ID`=40538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아하, 그러시군요! 다른 사람에게 도움이나 구걸하던 가난뱅이 고블린과 거래하는 것보다는 낫죠!', `FemaleText_loc4`='噢，噢，我知道这个！这可比和那些失败的地精做生意要好多了，他们总是要乞求别人的帮助！', `FemaleText_loc5`='哦，哦，這我知道!比跟失敗必須求人幫助的哥布林做生意來得好多了!', `FemaleText_loc7`='¡Oh, oh, conozco a este! Es mejor hacer negocios con goblins fracasados que tener que rogar ayuda a los demás!' WHERE `ID`=40539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 방사능에 절은 조그만 게...', `FemaleText_loc4`='你这被辐射的小矮子为什么要……', `FemaleText_loc5`='你這被輻射的小東西為什麼...', `FemaleText_loc7`='Maldito irradiado del...' WHERE `ID`=40540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 이 두 친구 때문에 정말 미치겠군! 둘 다 빨리 일을 시작하거나, 그렇지 않을 거면 내 마을에서 나가라고!', `MaleText_loc4`='啊！够了！你们两个都快把我逼疯了！赶快让这些怪诞的东西结束吧，或者把这东西扔到我的镇子外面去！', `MaleText_loc5`='啊啊!夠了!你們兩個快把我逼瘋了!如果再不好好做好你們該死的工作就滾出我的城鎮!', `MaleText_loc7`='¡AGH! ¡Ya basta! ¡Me están volviendo LOCO! ¡Empiezen a trabajar de una vez o sálganse de mi pueblo ahora mismo!' WHERE `ID`=40541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰, 이 도둑놈아!', `MaleText_loc4`='住手，你这小偷！', `MaleText_loc5`='停止，小偷!', `MaleText_loc7`='¡Al ladrón!', `FemaleText_loc1`='멈춰, 이 도둑놈아!', `FemaleText_loc4`='住手，你这小偷！', `FemaleText_loc5`='停止，小偷!', `FemaleText_loc7`='¡Al ladrón!' WHERE `ID`=40542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n! 당신이 온다는 소식을 작은 새에게 전해 들었소.$B$B아비아나 님은 이렇게 소식을 전달하신다오.', `MaleText_loc4`='啊，$n！一只小鸟告诉我，你会来这里。$B$B这是艾维娜传递信息的方式。', `MaleText_loc5`='啊，$n!有隻小鳥通知了我你的到來。$B$B這就是艾維娜傳達訊息的方式。', `MaleText_loc7`='¡Ah, $n! Me ha dicho un pajarito que vendrías.$b$bEn serio, así es como Aviana manda sus mensajes.' WHERE `ID`=40543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기와 잿더미라. 이 열기는 극복한다 해도, 질식을 피할 수 있을지 모르겠소.', `MaleText_loc4`='到处都是烟尘。就算热不死我，我也会窒息而死。', `MaleText_loc5`='灰煙和塵土。如果我不是被熱死，可能就是被嗆死。', `MaleText_loc7`='Humo y ceniza. Si el calor no me mata, podría asfixiarme.' WHERE `ID`=40544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어라, 비겁자여! 일격에 널 끝내리니! 이제 뜨거운 맛을 봐라!', `MaleText_loc4`='听着，该死的家伙！我要踏扁你们！现在……尝尝烈火的味道吧！', `MaleText_loc5`='哈肯，這雜種!看我把你一腳踢開!現在感受一下...燃燒的感覺吧!', `MaleText_loc7`='¡Escucha, perro callejero! ¡Yo te desprecio! Ahora... ¡Arde!' WHERE `ID`=40545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 몸은 망가지고 으스러져 만신창이가 되었구나! 나의 저주가 곧 너의 저주가 되리니, 이제는 되돌릴 길이 없도다!', `MaleText_loc4`='你将失败，你的身躯将会破碎！让我的诅咒落在你的身上。这是注定的命运！', `MaleText_loc5`='你就這樣一直被人毆打，打成重傷、打到殘廢!讓我的詛咒降臨到你身上，這就是宿命!', `MaleText_loc7`='¡Tu cuerpo yace apaleado, maltrecho y roto! ¡Que mi maldición sea también la tuya! ¡El destino ha hablado!' WHERE `ID`=40546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 절대 갚지 못할 빚을 졌군요, $n 님. 뭐, 못 갚을 정도는 아니려나?$B$B음?', `MaleText_loc4`='我欠你的永远还不清，$n。也许，能还清？$B$B嗯？', `MaleText_loc5`='我欠了你一個永遠無法還的人情，$n。還是說我可以?$B$B嗯?', `MaleText_loc7`='Tengo una deuda contigo que jamás podré pagar, $n. ¿O sí?$b$b¿Mmm?' WHERE `ID`=40547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어, $n. 난 누군가에게 빚지고는 못사는 성격이야. 그러니 이건 우리 둘 사이의 일로 묻어둬야겠어, 그래 줄 수 있어?$B$B빚쟁이들 귀에 들어가면 큰일 난다고.', `MaleText_loc4`='听着，$n，我不喜欢亏欠任何人。所以你能不能低调处理这件事，保守我们俩之间的秘密？$B$B我可不想让我的债主知道。', `MaleText_loc5`='聽著，$n，我很不喜歡欠債。可以低調點，讓這件事可以只介於你跟我之間嗎?$B$B我不想讓我的放款人知道。', `MaleText_loc7`='Escucha, $n, odio estar en deuda. Así que sé $gdiscreto:discreta; y que quede entre nosotros, ¿quieres?$b$bNo quiero que se enteren mis acreedores.' WHERE `ID`=40548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주주최자 미글렌이 화장실에서 탈출하고는 마구 몸을 휘저으며 쾌속선을 향해 헤엄칩니다.', `MaleText_loc4`='拖车管理员从厕所里逃了出来，对着赛艇平台疯狂地做手势。', `MaleText_loc5`='拖車管理員從公廁中逃了出來並對高速駁船狂亂地比著手勢。', `MaleText_loc7`='El maestro de arrastre escapa de la letrina y señala frenéticamente el Barcódromo.' WHERE `ID`=40549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='러그피즐이 화장실에서 탈출하고는 마구 몸을 휘저으며 쾌속선을 향해 헤엄칩니다.', `MaleText_loc4`='拉格菲兹从厕所里逃了出来，对着赛艇平台疯狂地做手势。', `MaleText_loc5`='魯格菲斯從公廁中逃了出來並對高速駁船狂亂地比著手勢。', `MaleText_loc7`='Alfombriz escapa de la letrina y señala frenéticamente el Barcódromo.' WHERE `ID`=40550;
