UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 장전해라, 이 하찮은 놈들아!', `MaleText_loc4`='把那些炮弹装上，你这可怜虫！', `MaleText_loc5`='你們這些廢渣，把那些大砲填滿彈藥!', `MaleText_loc7`='¡Cargá los cañones, perro''!' WHERE `ID`=40560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐이라도 콧잔등을 긁으며 멈추는 놈이 있다면, 손을 동강 내주겠다!', `MaleText_loc4`='要是你们这群蠢货敢停下来抓鼻子，我就把你们抓鼻子的手给砍下来！', `MaleText_loc5`='你們這些雜碎要是有任何一人停下來只是為了要抓下鼻子，我會把你抓鼻子的那隻手給卸下來!', `MaleText_loc7`='¡Si alguno de ustedes, cafres, se para siquiera pa'' rascarse la nariz, se la cortaré junto con la mano!' WHERE `ID`=40561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직여라! 움직이란 말이다!', `MaleText_loc4`='动起来！动起来！', `MaleText_loc5`='快動!快動!', `MaleText_loc7`='¡Moveos! ¡MOVEOS!' WHERE `ID`=40562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 쥐새끼 같은 놈들이... 이걸 지금 대포라고 쏘는 거냐? 정말 넌덜머리가 난다!', `MaleText_loc4`='你们这群鼠辈管那叫炮战技术？真让我恶心！', `MaleText_loc5`='你們這些鼠輩認為那就是砲彈工程?讓人噁心!', `MaleText_loc7`='¡Ratas! ¿A eso le llamáis dihpará con cañones? ¡Me ponéis enfermo!' WHERE `ID`=40563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 천한 놈들아! 쓸모있는 짓 좀 해라! 계속 쏘란 말이야!', `MaleText_loc4`='你们这群笨蛋做点儿有意义的事吧！保持开火！', `MaleText_loc5`='你們這些狗雜種證明下自己的用處!繼續開火!', `MaleText_loc7`='¡Haced algo útil, mamarrachos! ¡SEGUID DISPARANDO!' WHERE `ID`=40564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구스... 노움 위생병 좀... 불러 주세요...', `FemaleText_loc4`='格斯……你得……给我找个侏儒医疗人员……', `FemaleText_loc5`='箇司...你必須...幫我找一位地精醫生...', `FemaleText_loc7`='Gus... tienes que... conseguirme uno de esos médicos gnomos...' WHERE `ID`=40565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보, 첼시... 그건 말도 안 되는 소리라고요! 헛소리라고! 조금만 더 참아봐요...', `MaleText_loc4`='切尔西，孩子，你在说胡话！你一定是神志不清了！再坚持一下……', `MaleText_loc5`='雀兒喜，寶貝，那是胡言亂語!你發狂了!再撐一下下就好了...', `MaleText_loc7`='¡Chelsea, cariño, no dices más que tonterías! ¡Estás delirando! Aguanta un poco más...' WHERE `ID`=40566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤가요, 노겐포저 씨! 이제 더는 그 거인들 때문에 걱정하지 않아도 돼요!', `FemaleText_loc4`='好了，诺格弗格先生！你不用再担心那些巨人了！', `FemaleText_loc5`='看，諾格弗格先生!你不用再擔心那些巨人了!', `FemaleText_loc7`='¡Allá va, señor Tragonublo! ¡No tendrás que preocuparte por esas hormigas gigantes nunca más!' WHERE `ID`=40567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 한걱정 덜었군. 고맙네.', `MaleText_loc4`='这可真让我如释重负啊。谢谢你，孩子。', `MaleText_loc5`='這其實能減輕我鎧甲的負擔。謝啦，小兄弟。', `MaleText_loc7`='De hecho, me quitas un peso de encima. Gracias, chaval.' WHERE `ID`=40568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쳇. 풋내기잖아.', `FemaleText_loc4`='嗤！真业余。', `FemaleText_loc5`='切，不專業。', `FemaleText_loc7`='Pff. Aficionados.' WHERE `ID`=40569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보셨죠, 노겐포저 씨? 우리가 당신 일을 처리해 드렸어요. 어려울 것도 없었지만요.', `FemaleText_loc4`='看到了吗，马林？我们保护了你，宝贝儿。毫不费力。', `FemaleText_loc5`='看吧，馬林?我們罩著你，寶貝。', `FemaleText_loc7`='¿Ves, Marin? Te protegemos. No sufras.' WHERE `ID`=40570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이지 만족스러운 결과군, 드레드슈레더 양.', `MaleText_loc4`='我必须承认我喜欢我所见到的这一切，碎纸机夫人。', `MaleText_loc5`='我必須承認我喜歡我所看到的，驚懼伐木機小姐。', `MaleText_loc7`='Debo admitir que me gusta lo que estoy viendo, señora Trituramatic.' WHERE `ID`=40571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 멕스 양, 그러면 대충대충 일했다는 말이군요! 다음번에는 신경 좀 써야겠어요!', `FemaleText_loc4`='天哪，梅格斯小姐，也许下一次你能真的做点儿什么！', `FemaleText_loc5`='天啊，梅格斯小姐，或許你下次可以真正做些工作!', `FemaleText_loc7`='¡Guau, señorita Megs, la próxima vez igual hasta puedes hacer algo!' WHERE `ID`=40572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 이제 남쪽바다 해적단의 소유다, 애송아!', `MaleText_loc4`='那现在是南海海盗的财产了，旱鸭子！', `MaleText_loc5`='這是南海掠劫者的所有物，旱鴨子!', `MaleText_loc7`='¡Eso es propie''ad de los Filibuhteros de los Mares del Sul, marinero de agua dulse!' WHERE `ID`=40573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 포위망을 돌아다니며 뒤적거리지 마라!', `MaleText_loc4`='别想冲破我们的封锁线！', `MaleText_loc5`='你光是搜尋是無法通過我們的關卡的!', `MaleText_loc7`='¡No vas a conseguir escapal de nuehtro bloqueo escarbando!' WHERE `ID`=40574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 해안은 남쪽바다 해적단의 것이다!', `MaleText_loc4`='南海海盗是这片海岸的主人！', `MaleText_loc5`='這片海岸是南海掠劫者的!', `MaleText_loc7`='¡Los Filibuhteros de los Mares del Sul controlan la orilla!' WHERE `ID`=40575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다.$b$b죽을 지경에서 구해주셨군요.', `MaleText_loc4`='谢谢你，$r。$b$b是你把我从死亡线上拉了回来。', `MaleText_loc5`='謝謝你，$r。$b$b你把我從鬼門關救了回來。', `MaleText_loc7`='Gracias, $r.$b$bMe has salvado de una muerte segura.' WHERE `ID`=40576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 크기를 보셨습니까!?', `MaleText_loc4`='你有看清那个东西到底有多大吗！？', `MaleText_loc5`='你看到那東西有多大了嗎!?', `MaleText_loc7`='¿Has visto el tamaño de esa cosa?' WHERE `ID`=40577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님께 빚을 졌군요.$b$b전 끝난 줄로만 알았습니다.', `MaleText_loc4`='我欠你个人情，$c。$b$b我以为我死定了。', `MaleText_loc5`='我欠你一次，$c。$b$b我以為我死定了。', `MaleText_loc7`='Te debo una, $c.$b$bPensaba que ya estaba muerto.' WHERE `ID`=40578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나갈 수 있나요?', `MaleText_loc4`='我们要怎么才能从这儿离开？', `MaleText_loc5`='我們要怎麼離開這裡?', `MaleText_loc7`='¿Cómo vamos a salir de aquí?' WHERE `ID`=40579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 때가 된 거라면, 멋지게 죽고 싶습니다!', `MaleText_loc4`='就算我的死期已到，我也要死得轰轰烈烈！', `MaleText_loc5`='我要死也要死的漂亮一點!', `MaleText_loc7`='Si ha llegado la hora de mi muerte, ¡voy a marcharme bien alegre!' WHERE `ID`=40580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 우릴 찾아내는 건 시간문제입니다.$b$b뭘로 싸워야 하겠습니까?', `MaleText_loc4`='纳迦早晚会找到这儿来。$b$b到时候我们靠什么对付？', `MaleText_loc5`='納迦人找到我們是遲早的事。$b$b我們到時要拿什麼和他們對抗?', `MaleText_loc7`='Es cuestión de tiempo que los nagas nos encuentren aquí.$b$b¿Con qué nos enfrentaremos a ellos?' WHERE `ID`=40581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님이 살아 계셔서 다행입니다. 그분은 이 아수라장에서 우릴 어찌 이끌어야 할지 아실 겁니다.', `MaleText_loc4`='船长总算挺住了。他会想办法把我们从这混乱中救出去。', `MaleText_loc5`='隊長能辦到實在是太好了。他會知道如何帶我們渡過難關。', `MaleText_loc7`='Me alegro de que el capitán sobreviviera. Él sabrá cómo sacarnos de este lío.' WHERE `ID`=40582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우워어어어어어어어어어어어어어어!', `MaleText_loc4`='哇啊——！', `MaleText_loc5`='噫呀呀呀呀呀呀呀!', `MaleText_loc7`='¡¡RAAAAAAAAAAHHHHHHGGGGHHH!!' WHERE `ID`=40583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기! 고기다! 하하하하하!', `MaleText_loc4`='肉！肉！哈哈哈哈哈！', `MaleText_loc5`='肉!肉!哈哈哈哈哈!', `MaleText_loc7`='¡Carne! ¡CARNE! ¡Muahahahaha!' WHERE `ID`=40584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가 흥건하군!', `MaleText_loc4`='好多鲜血！', `MaleText_loc5`='好多血!', `MaleText_loc7`='¡Tanta sangre!' WHERE `ID`=40585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 거인이다!', `MaleText_loc4`='我是巨人！', `MaleText_loc5`='我是個巨人!', `MaleText_loc7`='¡Soy un GIGANTE!' WHERE `ID`=40586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드리즈가 원하는 부분을 찾아야 합니다. 나머지는 우리 것이죠!', `MaleText_loc4`='我们必须找到德利兹要的部分。剩下的归我们！', `MaleText_loc5`='我們必須給德瑞茲他要的。剩下全部屬於我們!', `MaleText_loc7`='Debemos conseguir las piezas que quiere Driz. ¡LO DEMÁS ES NUESTRO!' WHERE `ID`=40587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨간 게... 꼬불꼬불한 것과 연결되어 있고... 꼬불꼬불한 건... 제... 손목끈과 연결되어 있군요...', `MaleText_loc4`='那红色的东西连在……那弯弯曲曲的东西上……那弯弯曲曲的东西连在我的……腕带上……', `MaleText_loc5`='紅色的東西是跟...彎彎曲曲的東西連接的...跟彎彎曲曲的東西連接的...是我的護腕...', `MaleText_loc7`='La cosa roja está conectada a esa cosa retorcida... La cosa retorcida está conectada a mi... brazalete...' WHERE `ID`=40588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 아주 좋군요!', `MaleText_loc4`='多么令人兴奋！', `MaleText_loc5`='多麼令人興奮!', `MaleText_loc7`='¡Qué estimulante!' WHERE `ID`=40589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 아주 좋군요!', `MaleText_loc4`='多么令人兴奋！', `MaleText_loc5`='多麼令人興奮!', `MaleText_loc7`='¡Qué estimulante!' WHERE `ID`=40590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달의 신전 1층으로 가시면 드레나이 한 쌍이 마법 차원문을 관리하는 인간 마법사 엘리사 뒤마와 이야기를 나누고 있을 겁니다.$B$B그들이라면 그대를 도울 방법을 알고 있을 것입니다.', `MaleText_loc4`='在月神殿底层有两名德莱尼正在和埃莉萨·杜马斯——就是那位操纵魔法传送门的人类法师谈话。$B$B他们会知道该如何帮助你。', `MaleText_loc5`='在月神殿底層，你會看到兩名德萊尼正在和處理傳送門事務的埃麗莎·仲馬交談。$B$B他們會知道該如何幫你。', `MaleText_loc7`='Encontrarás a un par de draenei conversando con Elissa Dumas, la humana maga que se ocupa de los portales mágicos, en la planta baja del Templo de la Luna.$b$bEllos sabrán cómo ayudarte.', `FemaleText_loc1`='달의 신전 1층으로 가시면 드레나이 한 쌍이 마법 차원문을 관리하는 인간 마법사 엘리사 뒤마와 이야기를 나누고 있을 겁니다.$B$B그들이라면 그대를 도울 방법을 알고 있을 것입니다.', `FemaleText_loc4`='在月神殿底层有两名德莱尼正在和埃莉萨·杜马斯——就是那位操纵魔法传送门的人类法师谈话。$B$B他们会知道该如何帮助你。', `FemaleText_loc5`='在月神殿底層，你會看到兩名德萊尼正在和處理傳送門事務的埃麗莎·仲馬交談。$B$B他們會知道該如何幫你。', `FemaleText_loc7`='Encontrarás a un par de draenei conversando con Elissa Dumas, la humana maga que se ocupa de los portales mágicos, en la planta baja del Templo de la Luna.$b$bEllos sabrán cómo ayudarte.' WHERE `ID`=40591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나오너라 나가들아! 어디 한번 붙어보자!', `MaleText_loc4`='让纳迦过来吧！我正想打一仗哪！', `MaleText_loc5`='讓納迦來!我渴望戰爭!', `MaleText_loc7`='¡Que vengan los nagas! ¡Tengo ganas de pelea!' WHERE `ID`=40592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적어도 싸울 기회가 한 번은 생긴 셈이군요. 고맙습니다.', `MaleText_loc4`='感谢你，至少我们现在有了战斗的机会。', `MaleText_loc5`='多虧了你，至少我們現在有戰鬥的機會。', `MaleText_loc7`='Gracias a ti ahora al menos tenemos una oportunidad para luchar.' WHERE `ID`=40593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 죽을지도 모르지만, 이놈들을 무더기로 길동무 삼겠습니다!', `MaleText_loc4`='我也许会倒下，但我也会多拖些怪物给我垫背！', `MaleText_loc5`='我或許會戰死，但會帶一打的那些野獸陪葬!', `MaleText_loc7`='Quizá muera, ¡pero me llevaré a una docena de esas bestias conmigo!' WHERE `ID`=40594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수할 시간이다!', `MaleText_loc4`='复仇时间到！', `MaleText_loc5`='報仇的時間到了!', `MaleText_loc7`='¡Es la hora de la venganza!' WHERE `ID`=40595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다, $c님.$b$b저와 제 부하들은 적에 맞설 준비가 되었습니다.', `MaleText_loc4`='干得好，$c。$b$b现在我和我的人已经准备好面对敌人了。', `MaleText_loc5`='你做的很好，$c。$b$b我和我的人都準備好要面對敵人了。', `MaleText_loc7`='Has estado bien, $c.$b$bAhora mis hombres y yo nos prepararemos para hacer frente al enemigo.' WHERE `ID`=40596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 놈들은 여기서 벌인 짓에 죗값을 치러야 한다!', `MaleText_loc4`='纳迦必须为他们在这里的所作所为付出代价！', `MaleText_loc5`='納迦必須為他們在這所做的付出代價!', `MaleText_loc7`='¡Los nagas deben pagar por lo que han hecho!' WHERE `ID`=40597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와다오! 난 이 나무 안에 갇혀 있다! 도움이 필요하다!', `FemaleText_loc4`='救命！我被困在这棵树里了！我需要帮助！', `FemaleText_loc5`='救命!我被這棵樹困住了!我需要協助!', `FemaleText_loc7`='¡Ayúdenme! ¡Estoy atrapada dentro de este árbol!' WHERE `ID`=40598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙구나! 더 오래 버틸 수는 없었다... 끔찍한 일이 여기에서 일어났다.', `FemaleText_loc4`='谢谢你的帮助！我已经濒临崩溃了……这里发生了可怕的事情。', `FemaleText_loc5`='謝謝你!我的堅持正好到達了極限....這裡發生了可怕的事情。', `FemaleText_loc7`='¡Gracias! No podía aguantar mucho más... Ha ocurrido algo terrible en este lugar.' WHERE `ID`=40599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 성소를 철저히 방비했다고 믿었기에, 이런 공격은 감당할 준비를 하지 못했다.', `FemaleText_loc4`='我们相信圣殿是坚不可摧的，但我们没想到会遭受这样的攻击。', `FemaleText_loc5`='我們原以為聖所防衛嚴密，但我們沒有面對這一種攻擊方式的準備。', `FemaleText_loc7`='Creíamos que el Sagrario estaba bien fortificado, pero no estábamos preparados para este tipo de asalto.' WHERE `ID`=40600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은용군단이 느닷없이 나타나, 우리가 미처 손쓸 새도 없이 공격을 퍼붓더구나.', `FemaleText_loc4`='黑龙人凭空出现，在我们反应过来之前就发动了攻击。', `FemaleText_loc5`='黑色龍人無影無息地從空氣中突然現身，在我們做出反應之前發動了突襲。', `FemaleText_loc7`='El Dragonante Negro se materializó de la nada y nos embistió antes de que pudiéramos reaccionar.' WHERE `ID`=40601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기회조차 없었다. 주위에서 동지들이 쓰러져갈 때, 가까스로 여기까지 도망쳐 와 입구를 막았다.', `FemaleText_loc4`='我们全面溃败。同胞们一个个死去。只有我撤退到这里，并封住了入口。', `FemaleText_loc5`='我們一點機會也沒有。當我附近的同袍們一個個倒下，我成功地撤退到這裡並將入口封鎖。', `FemaleText_loc7`='Era nuestro fin. Con mis hermanos pereciendo a mi alrededor, logré la retirada hasta aquí, donde barriqué la entrada.' WHERE `ID`=40602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 무자비하게 우리를 학살했지만, 진짜 목적은 성소 안 이곳에 보관된 알에 있는 듯하더구나.', `FemaleText_loc4`='他们冷酷无情地屠杀我们，但他们真正的目标似乎是圣殿里的那些卵。', `FemaleText_loc5`='他們有效率而冷血地屠殺我們，不過他們真正的目標似乎是保存在聖所的龍蛋。', `FemaleText_loc7`='Nos masacraron con una eficacia fría, pero parecían más interesados en los huevos guardados aquí, en el Sagrario.' WHERE `ID`=40603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 지상 병력의 사령관은 자리스리안이라는 잔인한 자인데, 그보다 더 강력한 힘이 움직이기에 두렵기만 하다.', `FemaleText_loc4`='指挥他们的是一个名叫萨瑞瑟里安的残忍家伙。但我担心他背后还有更强大的力量。', `FemaleText_loc5`='這批地面部隊的指揮官是個殘忍而野蠻的傢伙叫做扎里斯利安，不過我擔心在這背後有著更強大的力量在運作。', `FemaleText_loc7`='El comandante de las fuerzas terrestres es un salvaje cruel llamado Zarithrian, pero me temo que hay fuerzas superiores de por medio.' WHERE `ID`=40604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음 공격받을 때 진짜 지도자를 얼핏 보았더니 완전하게 성장한, 무시무시한 황혼의 용이었다.', `FemaleText_loc4`='刚受到攻击时，我看见了他们真正的首领，一头恐怖的暮光巨龙。', `FemaleText_loc5`='在他們最初的攻擊中，我瞥見他們真正領袖的身影，那是一條令人畏懼、完全成長的暮光龍。', `FemaleText_loc7`='En su asalto inicial, pude ver fugazmente a su verdadero líder, un temible dragón crepuscular.' WHERE `ID`=40605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계획을 전부 알지는 못하나, 이건 확실하다. 저들이 뜻을 이루게 두어서는 안 된다!', `FemaleText_loc4`='我还不知道他们的全盘计划，但我知道，英雄们，绝不能让他们得逞！', `FemaleText_loc5`='我無法知悉他們的通盤計畫，英雄們，但是我知道一點:絕不能讓他們得手!', `FemaleText_loc7`='Desconozco sus verdaderos planes, héroes, pero sí sé esto: ¡no hay que permitirles que los lleven a cabo!' WHERE `ID`=40606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무른피부, 네 녀석이 배에서 나오는 걸 봤다! 네놈들 전부 잡아들이리라!', `MaleText_loc4`='我看见你离开那艘船了，弱者！很快我们就会把你们全都干掉！', `MaleText_loc5`='我看到你離開了那艘船，弱蝦!很快，我們就會把你們消滅殆盡!', `MaleText_loc7`='¡Te he visssto ssssalir de essse barco, piel ssssuave! ¡Pronto ossss mataremossss a todossss!' WHERE `ID`=40607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님! 나가입니다! 나가가 $n 님을 따라 배까지 쫓아왔습니다!', `MaleText_loc4`='船长！是纳迦！他们跟着$n到船上来了！', `MaleText_loc5`='隊長!是納迦!他們跟著$n到船上了!', `MaleText_loc7`='¡Capitán! ¡Los nagas! ¡Han seguido a $n hasta el barco!' WHERE `ID`=40608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\spell_shadow_shadowfury.blp:20|t%s|1이;가; |cFFA043E7|Hspell:75694|h[암흑 돌풍]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_shadowfury.blp:20|t%s开始施放|cFFA043E7|Hspell:75694|h[暗影飓风]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_shadowfury.blp:20|t%s開始施展|cFFA043E7|Hspell:75694|h[暗影強風]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_shadowfury.blp:20|t¡%s comienza a lanzar |cFFA043E7|Hspell:75694|h[Vendaval de las Sombras]|h|r!' WHERE `ID`=40609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s|1이;가; |cFF006EFD얼굴 없는 타락자|r에게 |cFF006EFD|Hspell:75809|h[악몽의 보호막]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s开始对|cFF006EFD无面腐蚀者|r施放|cFF006EFD|Hspell:75809|h[梦魇之盾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s開始對|cFF006EFD無面墮落者|r施展|cFF006EFD|Hspell:75809|h[夢魘之盾]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_sacrificialshield.blp:20|t¡%s comienza a lanzar |cFF006EFD|Hspell:75809|h[Escudo de pesadillas]|h|r al |cFF006EFDcorruptor ignoto!|r' WHERE `ID`=40610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무른피부들아! 너희도 곧 우리 여군주님을 섬길 것이다!', `MaleText_loc4`='弱者！很快你们就将臣服于我的女士！', `MaleText_loc5`='弱蝦!很快你就會臣服於我的女士!', `MaleText_loc7`='¡Pielesss sssuavesss! ¡Pronto ssservirás a mi ssseñora!' WHERE `ID`=40611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 고통이여... 오라, 혼돈이여!', `MaleText_loc4`='来吧，受苦吧……进入，混沌！', `MaleText_loc5`='來吧!苦難...混沌，登場!', `MaleText_loc7`='Ven, sufrimiento... ¡Ven, caos!' WHERE `ID`=40612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000망각|r을 시전합니다!', `MaleText_loc4`='%s开始施展|cFFFF0000湮灭术！|r', `MaleText_loc5`='%s開始施放|cFFFF0000遺忘!|r', `MaleText_loc7`='¡%s comienza a lanzar |cFFFF0000Olvido!|r' WHERE `ID`=40613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 존재여, 네 힘은 기울어간다. 곧 친구들을 만날 게다.', `MaleText_loc4`='你的力量在减弱，老家伙……准备下去见你的朋友吧。', `MaleText_loc5`='你的力量正在衰退，老傢伙....你很快就能和朋友作伴了。', `MaleText_loc7`='Tu poder mengua, anciano. Pronto te unirás a tus amigos.' WHERE `ID`=40614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 이 괴물!', `MaleText_loc4`='死吧，怪兽！', `MaleText_loc5`='死吧，野獸!', `MaleText_loc7`='¡Muere, bestia!' WHERE `ID`=40616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 다시 만나게 될 거야...', `MaleText_loc4`='我们很快就会再见……', `MaleText_loc5`='我們很快便會再見...', `MaleText_loc7`='Pronto nos encontraremos de nuevo...' WHERE `ID`=40617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발각됐습니다... 서두르십시오, $n 님. 시간이 얼마 없습니다!', `MaleText_loc4`='我们被发现了……动作快$n，没时间了！', `MaleText_loc5`='我們被發現了...$n動作快，時間不多了!', `MaleText_loc7`='Hemos sido descubiertos... ¡Rápido, $n, apenas queda tiempo!' WHERE `ID`=40618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='속으로는 내가 뚱뚱하다고 생각하는 거죠?', `FemaleText_loc4`='你暗地里总嫌我不够苗条。', `FemaleText_loc5`='你一向都默默地認為我看起來很胖!', `FemaleText_loc7`='¡Siempre has pensado en secreto que yo estaba gorda!' WHERE `ID`=40619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안마 좀 제대로 받느라 당신의 돈을 거의 써버렸어요. 당신 안마 솜씨는 아직 연습이 더 필요하다고요!', `FemaleText_loc4`='我把你大部分的钱都花在按摩上了，天晓得你为什么总是做不好！', `FemaleText_loc5`='我把你大部份的錢都花在按摩上，天知道，你怎麼按都按不好!', `FemaleText_loc7`='Me he gastado la mayor parte de tu dinero en un masaje decente. ¡Los dioses saben que tú no tienes ni idea dar uno!' WHERE `ID`=40620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 우리 미래에 대해 생각해 본 적이 없어요. 흥, 하지만 이제 괜찮아요. 난 마침내 내 지갑을 채워줄 진짜 고블린을 만났으니까.', `FemaleText_loc4`='你总是一无是处。我真开心总算找到了一个真正的男人来满足我的购物欲。', `FemaleText_loc5`='你根本不求上進、一事無成。我很高興我終於找到了一個可以滿足我購物需求的真男人。', `FemaleText_loc7`='Nunca has tenido ambiciones. Estoy tan contenta de haber encontrado un goblin que puede satisfacer mi necesidad de ir de compras.' WHERE `ID`=40621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 도와줘야만 해! 내 불쌍한... 불쌍한 첼시...', `MaleText_loc4`='你得帮帮我！我可怜的，可怜的切尔希……', `MaleText_loc5`='你必須幫助我!我的小可憐雀兒喜...', `MaleText_loc7`='¡Tienes que ayudarme! Mi pobre, pobre Chelsea...' WHERE `ID`=40622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 당신보다 더 남자다운 선원들도 만난 적이 있어요. 내 시간 버린 걸 생각하면...', `FemaleText_loc4`='就连我遇到的船上服务生都比你有男人气概。真没想到我居然在你身上耽误那么多时间……', `FemaleText_loc5`='我遇過的船艙服務員都比你還有男子氣概。我想想真是在浪費時間...', `FemaleText_loc7`='He conocido grumetes que eran más machos que tú. Pensar en todo el tiempo que perdido contigo...' WHERE `ID`=40623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 사람에게 내가 뚱뚱하다고 말했죠, 그렇죠?', `FemaleText_loc4`='你在我背后跟他说我是个胖子，对吗？', `FemaleText_loc5`='你在我背後跟他說我很胖，對吧?!', `FemaleText_loc7`='¡Cuando no escuchaba les has dicho que estaba gorda! ¿No es cierto?' WHERE `ID`=40624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 능력과 돈을 모두 갖춘 사람을 만났다고 질투하는군요.', `FemaleText_loc4`='你不过是在嫉妒我找到了一个有本事又有身家的男人。', `FemaleText_loc5`='你只是在嫉妒我找到一個既有技巧，錢包又滿的人罷了。', `FemaleText_loc7`='Estás celoso de que haya encontrado un hombre con habilidades Y una cartera bien gorda.' WHERE `ID`=40625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 대신할 고블린을 찾을 순 없을 거예요. 칩은 깡패도 매력적으로 보이게 할 만큼 못생긴 고블린과는 데이트하지 않으니까요!', `FemaleText_loc4`='你永远都取代不了我。奇普永远不会堕落到与一个比蠢猪更蠢的家伙约会！', `FemaleText_loc5`='你永遠都不可能取代我。奇普永遠都不會屈就和一個化妝後才能看的母豬約會!', `FemaleText_loc7`='Nunca podrás sustituirme. ¡Locko nunca se rebajará a salir con alguien que hace que un bruto parezca atractivo!' WHERE `ID`=40626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 그렇게 입고 외출을 할 수 있죠? 네? 어디 길거리에서 자고 일어난 사람 같잖아요!', `FemaleText_loc4`='你怎么能就那样出去？什么，你刚刚在某处沙滩上洗过了？！', `FemaleText_loc5`='你怎麼能忍受就這樣出門?你是不是只是在哪個海灘把臉沖了一下而已?!', `FemaleText_loc7`='¡Cómo eres capaz de SALIR con esta pinta! ¡¿Es que te has revolcado en una playa o qué?!' WHERE `ID`=40627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 출진!', `MaleText_loc4`='战斗吧，弟兄们！', `MaleText_loc5`='同伴們，上啊!', `MaleText_loc7`='¡Al combate, soldados!' WHERE `ID`=40628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채찍은 인간의 손에 어울리지 않는다!', `MaleText_loc4`='这鞭子可不是为凡人的双手准备的！', `MaleText_loc5`='鞭笞者不適合於凡人之手!', `MaleText_loc7`='¡El azotador no es apropiado para manos mortales!' WHERE `ID`=40629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드를 위하여!', `MaleText_loc4`='为了暴风城！', `MaleText_loc5`='為了暴風城!', `MaleText_loc7`='¡Por Ventormenta!' WHERE `ID`=40630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐군. 이거면 될 거야.', `MaleText_loc4`='好了，这应该行得通。', `MaleText_loc5`='喏，這應該可以了。', `MaleText_loc7`='¡Allá vamos! Esto debería bastar.' WHERE `ID`=40631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첼시, 이걸 마셔봐요. 좀 괜찮아질 거예요.', `MaleText_loc4`='切尔西，孩子，请喝下这个。这会让你好受些。', `MaleText_loc5`='雀兒喜寶貝，請把這喝了。這會讓你感覺好一點。', `MaleText_loc7`='Chelsea, cariño, bebe esto. Te hará sentir mejor.' WHERE `ID`=40632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='응? 알겠어요...', `FemaleText_loc4`='嗯？好吧……', `FemaleText_loc5`='嗯?好...', `FemaleText_loc7`='¿Mmmm? De acuerdo...' WHERE `ID`=40633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 뭐예요? 맛이... 우우욱... 이제 좀 쉬어야겠어요.', `FemaleText_loc4`='这是什么？吃上去感觉……我现在得躺一会儿。', `FemaleText_loc5`='這是什麼?嘗起來...呃...我現在要躺回去了。', `FemaleText_loc7`='¿Qué es esto? Sabe un poco... Agh... Voy a echarme un ratito.' WHERE `ID`=40634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첼시! 일어나요! 이제 됐어요! 이게 당신을 치유해 줄 거예요!', `MaleText_loc4`='切尔希，孩子，快起来！我得到它了！它一定能治愈你！', `MaleText_loc5`='雀兒喜，寶貝，坐起來!就是這個!這會治好你的!', `MaleText_loc7`='¡Chelsea, cariño, siéntate! ¡Lo tengo! ¡Esto te curará!' WHERE `ID`=40635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윽, 그거 안 마실래요. 여기까지도 냄새가 난단 말이에요. 그냥 식중독 증세가 나아지도록 잠이나 자게 해 주세요, 네?', `FemaleText_loc4`='呃，格斯，我可不喝，我从这儿都能闻到味道了。让我把食物中毒的效果给睡过去，行吗？', `FemaleText_loc5`='呃，箇司，我不會喝的，我在這就能聞到它的味道。讓我睡個覺，我的食物中毒就會自然痊癒了，OK?', `FemaleText_loc7`='Agh. Gus, no voy a beberme eso. Puedo olerlo desde aquí. Tú déjame dormir hasta que se me pase el envenenamiento por comida, ¿vale?' WHERE `ID`=40636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...식중독이라고? 잠깐만, 그 바실리스크 스테이크 말인가요? 그것 때문에?', `MaleText_loc4`='……食物有毒？等等，你说的是这些蜥蜴肉？所有这些？', `MaleText_loc5`='...食物中毒?等一下，你是指那些蜥蜴肉排嗎?就這樣而已?', `MaleText_loc7`='¿... Envenenamiento por comida? Espera, ¿te refieres a esos filetes de basilisco? ¿De eso se trata?' WHERE `ID`=40637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다행이에요, 여보. 이제 괜찮다니 정말 다행이야...', `MaleText_loc4`='没什么，宝贝儿。我只是很高兴你一切都好……', `MaleText_loc5`='沒什麼，甜心。我只是覺得你安好我很開心...', `MaleText_loc7`='Nada, cariño. Es solo que me alegro de que estés bien.' WHERE `ID`=40638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우욱! 말도 꺼내지 마세요. 물론 그것 때문이죠. 너무 덜 익혔단 말이에요...제가 뭣 때문에 식중독에 걸렸겠어요?', `FemaleText_loc4`='呸！不用说。这是当然了，那些东西完全没煮熟……你认为是什么使我中毒的？', `FemaleText_loc5`='咯!別說了。那是當然的，那些根本沒有熟...你以為是什麼讓我中的毒?', `FemaleText_loc7`='¡Puaj! Ni lo menciones. Por supuesto que se trataba de eso, estaban tan poco hechos... ¿Qué creías que me había envenenado?' WHERE `ID`=40639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전방 병력을 강화해라. 침입자가 있다!', `MaleText_loc4`='增援前方！我们遭到了入侵！', `MaleText_loc5`='增援前線! 我們受到侵略!', `MaleText_loc7`='¡Refuercen el frente! ¡Nos invaden!' WHERE `ID`=40640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 이제 좀 할 맛이 나는군. 황혼의 망치단이여, 이리 와서 나를 지켜라!', `MaleText_loc4`='好吧，现在我出汗了。暮光之锤竟然会到这里来保护我！', `MaleText_loc5`='好吧...我現正在流汗，暮光之錘快進來保護我!', `MaleText_loc7`='Está bien, ahora estoy sudando. ¡Martillo Crepuscular, venid aquí y defendedme!' WHERE `ID`=40641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후방을 지원해라! 알렉스트라자의 아이들이 우리를 공격한다!', `MaleText_loc4`='掩护后方！阿莱克丝塔萨的爪牙正在杀死我们的士兵！', `MaleText_loc5`='掩護後方! 雅立史卓莎的龍群正在屠殺我們的同伴!', `MaleText_loc7`='¡Cubran la retaguardia! ¡El linaje de Alexstrasza nos destroza!' WHERE `ID`=40642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 생각해보니, 드라가에게 도움이 필요할지도 모르겠다! 집합!', `MaleText_loc4`='经过三思——达加可能还是需要帮助！集合！', `MaleText_loc5`='不過想了一想，德拉卡或許真的需要幫忙!前進!', `MaleText_loc7`='¡Bueno, vale, Dragha quizá necesite ayuda después de todo! ¡A por ellos!' WHERE `ID`=40643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 불을 끄고 우리 배로 넘어오는 해적들을 막아 줄거지, 그렇지?', `MaleText_loc4`='你会灭火并阻止那些海盗上船的，对吧？', `MaleText_loc5`='你要把火滅了和阻止那些海盜上來，對吧?', `MaleText_loc7`='Tú apagarás los incendios e impedirás que esos piratas nos aborden, ¿verdad?' WHERE `ID`=40644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 제 배에 타게 해주십시오. 그리즈낙.', `MaleText_loc4`='让我到船上来，格里兹纳克。', `MaleText_loc5`='讓我到我的船裡，格里茲納克。', `MaleText_loc7`='Llévame a mi barco, Griznak.', `FemaleText_loc1`='네, 제 배에 타게 해주세요, 그리즈낙.', `FemaleText_loc4`='让我到船上来，格里兹纳克。', `FemaleText_loc5`='讓我到我的船裡，格里茲納克。', `FemaleText_loc7`='Llévame a mi barco, Griznak.' WHERE `ID`=40645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떡하지! 어떡하지! 당신이 불을 끄고 해적들이 쾌속선에 오르는 걸 막아주실 거죠? 그렇죠?!!', `MaleText_loc4`='喔天哪！喔神哪！你会扑灭火焰，并阻止那些海盗登上赛艇平台，是吧？！！', `MaleText_loc5`='天啊!地啊!你會把火滅了和阻止那些海盜上來高速駁船，對吧?!!', `MaleText_loc7`='¡Ay, caramba! ¡Ay, córcholis! Apagarás los incendios e impedirás que esos piratas aborden el Barcódromo, ¿verdad?' WHERE `ID`=40646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 제 배에 타게 해주십시오, 마제르.', `MaleText_loc4`='让我到船上来，玛兹尔。', `MaleText_loc5`='讓我到我的船裡，瑪瑟爾。', `MaleText_loc7`='Llévame a mi barco, Mazzer.', `FemaleText_loc1`='네, 제 배에 타게 해주세요, 마제르.', `FemaleText_loc4`='让我到船上来，玛兹尔。', `FemaleText_loc5`='讓我到我的船裡，瑪瑟爾。', `FemaleText_loc7`='Llévame a mi barco, Mazzer.' WHERE `ID`=40647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 아슬아슬했소, $n.', `MaleText_loc4`='已经很接近了，$n。', `MaleText_loc5`='真的驚險，$n。', `MaleText_loc7`='Eso ha estado muy cerca, $n.' WHERE `ID`=40648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요! 피즐과 포직의 쾌속선에 오신 것을 환영해요.$B$B우린 땅 위와 하늘 아래 있는 건 뭐든 다 갖추고 있답니다.', `MaleText_loc4`='嗨你好啊！欢迎来到菲兹尔与普兹克赛艇平台。$B$B天底下跑的深渊里游的，我们这里无所不有！', `MaleText_loc5`='哈囉!歡迎來到菲茲爾與普茲克的高速駁船。$B$B你可以在這找到任何天空下和地面上的東西。', `MaleText_loc7`='¡Hola! Te doy la bienvenida al Barcódromo de Fizzle y Pozzik.$B$BTenemos todo lo que existe bajo el cielo y sobre el mar.' WHERE `ID`=40649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적과 켄타우로스, 그림토템 부족도 모자라서, 맙소사!$B$B어젯밤에 커다란 뭔가가 제 머리 위로 날아가는 걸 봤어요. 크기가 얼마나 어마어마한지, 달을 가릴 정도였다니까요!', `MaleText_loc4`='海盗、半人马、恐怖图腾，我的天！$B$B而且我想我昨晚还看到一个庞然大物从头顶上飞了过去。它可真是太大了，大得把月亮都遮住了！', `MaleText_loc5`='海盜加上半人馬加上恐怖圖騰，我的媽呀!$B$B還有我想我昨晚看到了一個大東西飛了過去。那大到把月亮都遮起來了!', `MaleText_loc7`='¡Piratas, centauros y Tótem Siniestro, vaya!$B$BY creo que ayer por la noche vi algo enorme volando por el cielo. ¡Era tan grande que tapaba la luna!' WHERE `ID`=40650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마시오. 내가 옆에 있소.', `MaleText_loc4`='别担心——有我在。', `MaleText_loc5`='別擔心...有我在。', `MaleText_loc7`='No te preocupes, te tengo.' WHERE `ID`=40651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 조심하시오, $n!', `MaleText_loc4`='$n，一定要时刻保持谨慎！', `MaleText_loc5`='在那要更加小心，$n。', `MaleText_loc7`='¡Ten más cuidado ahí fuera, $n!' WHERE `ID`=40652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피즐과 포직의 쾌속선에 온 것을 환영합니다. 이곳에선 필요한 모든 것을 얻으실 수 있지요.', `MaleText_loc4`='欢迎来到菲兹尔与普兹克赛艇平台。你能在这里找到所有你想要的东西。', `MaleText_loc5`='歡迎來到菲茲爾與普茲克的高速駁船。你可以在這找到任何你所需要的。', `MaleText_loc7`='Te doy la bienvenida al Barcódromo de Fizzle y Pozzik. Aquí encontrarás todo lo que necesites.' WHERE `ID`=40653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮소, $n. 이제 안전하오.', `MaleText_loc4`='没事了$n——你现在安全了。', `MaleText_loc5`='沒事了，$n，你現在是安全的。', `MaleText_loc7`='Está bien, $n. Ahora estás a salvo.' WHERE `ID`=40654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아슬아슬하게 잡았소, $n!', `MaleText_loc4`='在这里遇到你真是恰逢其时啊，$n！', `MaleText_loc5`='千鈞一髮中找到了你，$n!', `MaleText_loc7`='¡Te he agarrado en el último momento, $n!' WHERE `ID`=40655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온갖 끔찍한 것들에 둘러싸여 있지만, 최소한 물 밖으로 나와있으니 다행이야.$B$B그곳에 있었다면 어젯밤 날아다니던 그 무언가를 피할 수 없었을 거야. 엄청나게 큰 크기였어... 정말, 어마어마하게 컸다고!', `MaleText_loc4`='我们在这儿可能会遇到各种各样的麻烦，但至少我们已经进入开放水域了。$B$B虽然我们不一定能逃过昨晚从我头顶飞过的那大家伙。那玩意儿可真大……我是说，真的很大！', `MaleText_loc5`='我們或許正被毒蛇猛獸包圍著，但至少我們已經從水中逃出來了。$B$B可是...那不代表我們就不用擔心我昨晚看到飛過天空的那個東西。那很大...真的真的很大!', `MaleText_loc7`='Puede que estemos rodeados de todo tipo de cosas desagradables, pero por lo menos estamos en mar abierto.$B$BSin embargo, eso no nos protegerá de lo que sea que vi volando la otra noche. Era grande... Y quiero decir que era ¡muy, muy grande!' WHERE `ID`=40656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙은 황무지에서 벌어진 전투 중 스컬지의 손에 죽은 자들을 기리며.', `MaleText_loc4`='献给那些在冰封荒原上为了对抗天灾军团而英勇牺牲的战士们。', `MaleText_loc5`='獻給那些在冰凍荒原和天譴軍團交戰時倒下的人們。', `MaleText_loc7`='Dedicado a quienes cayeron ante la Plaga en la guerra de los Baldíos Helados.' WHERE `ID`=40657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 몰락을 봅니다.', `MaleText_loc4`='必定要铲除巫妖王。', `MaleText_loc5`='目睹王者的隕落。', `MaleText_loc7`='Observa la caída del Rey Exánime.', `FemaleText_loc1`='리치 왕의 몰락을 봅니다.', `FemaleText_loc4`='必定要铲除巫妖王。', `FemaleText_loc5`='目睹王者的隕落。', `FemaleText_loc7`='Observa la caída del Rey Exánime.' WHERE `ID`=40658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연쇄 번개를 시전하고 있어요!! 파직 파직...', `MaleText_loc4`='我在施放闪电链！！啾啾……', `MaleText_loc5`='我在放閃電鏈!!咻咻...', `MaleText_loc7`='¡Estoy haciendo una Cadena de relámpagos! Puf, puf...' WHERE `ID`=40659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 위치를 사수하라! 놈들이 온다!', `MaleText_loc4`='坚守阵地，战士们！他们来了！', `MaleText_loc5`='堅守陣地，士兵們!他們要來了!', `MaleText_loc7`='¡Mantengan la posición, soldados! ¡Aquí vienen!' WHERE `ID`=40660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 너무 많습니다! 주술사님, 어떻게든 해 보십시오!', `MaleText_loc4`='他们人数太多了！萨满，快做点儿什么！', `MaleText_loc5`='數量太多了!薩滿，快想辦法!', `MaleText_loc7`='¡Son demasiados! ¡Chamán, haz algo!' WHERE `ID`=40661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 쉴 수 있을 때 휴식을 취하도록. 아직 끝이 아니다...', `MaleText_loc4`='抓紧时间休息吧，弟兄们。那可不是最后一波……', `MaleText_loc5`='有時間快點休息。那些還不是所有的...', `MaleText_loc7`='Descansen mientras puedan, soldados. Ese no era el último de ellos...' WHERE `ID`=40662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님!$B$B여기에 있는 불쌍한 수호자들은 이 어두운 장소에서 황혼의 망치단 하수인들을 상대로 온 힘을 다해 싸우고 있어요.$B$B저도 최선을 다해 전투 중에 떨어진 수호자를 되살리고 있지요.$B$B혹시 탈것이 더 필요하시다면 말씀하세요. 이 새들은 다시 날아오를 준비가 되었답니다. 새들을 잘 보살펴 주세요!', `FemaleText_loc4`='你好啊，$c！$B$B这些可怜的小家伙正在这黑暗的地方竭尽全力对抗暮光之锤的爪牙！$B$B我已经尽力让那些倒下的死而复生。$B$B要是你需要另一只坐骑，这些鸟已经准备好再次展翅翱翔。好好对待它们！', `FemaleText_loc5`='嗨，$c!$B$B這些可憐的生物已經盡力在這黑暗的地方對抗暮光之錘的爪牙了。$B$B我盡可能地復活了已經戰死的那些。$B$B如果你需要另一隻坐騎，這些鳥已經準備好再次飛翔了。好好對待牠們!', `FemaleText_loc7`='¡Hola, $c!$B$BEstas pobres criaturas están luchando con todas sus fuerzas contra los secuaces del Martillo Crepuscular en este lugar tenebroso.$B$BHe hecho todo lo que he podido para revivir a aquellas que han caído.$B$BSi necesitas una montura extra, estas aves están dispuestas a alzar el vuelo de nuevo. ¡Trátalas bien!' WHERE `ID`=40663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째 실전 비행:', `MaleText_loc4`='第二波：', `MaleText_loc5`='第二波:', `MaleText_loc7`='Segunda oleada:' WHERE `ID`=40664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 무너지고 있습니다!', `MaleText_loc4`='天塌了！', `MaleText_loc5`='天空要垮下來了!', `MaleText_loc7`='¡Sálvese quien pueda!' WHERE `ID`=40665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알 파괴 비행:', `MaleText_loc4`='卵摇晃着：', `MaleText_loc5`='蛋之浪:', `MaleText_loc7`='Oleada de huevos:' WHERE `ID`=40666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅 알을 파괴하십시오!', `MaleText_loc4`='摧毁火焰之地龙卵！', `MaleText_loc5`='摧毀火源之界的蛋!', `MaleText_loc7`='¡Destruye los huevos de las Tierras de Fuego!' WHERE `ID`=40667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 일에 너무 많이 끼어들었어, 노움 주제에.', `FemaleText_loc4`='你一而再再而三地碍我的事，侏儒。', `FemaleText_loc5`='你阻礙我太多次了，地精。', `FemaleText_loc7`='Te has cruzado en mi camino demasiadas veces, $gnomo:gnoma;.' WHERE `ID`=40668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그쪽 때문에 나도 참을 만큼 참았다고.', `FemaleText_loc4`='你也已经彻底耗尽了我的耐心。', `FemaleText_loc5`='你也磨光了我所有的耐心。', `FemaleText_loc7`='También has agotado toda mi paciencia.' WHERE `ID`=40669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을은 둘이 같이 살기에는 너무 좁아!', `FemaleText_loc4`='这城镇无法同时容下我们两个人！', `FemaleText_loc5`='我們之中只有一人能存在於這個小鎮!', `FemaleText_loc7`='¡En esta ciudad no hay sitio para ambos!' WHERE `ID`=40670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너를 깔끔하게 없애버리는 걸 너무 기뻐하지는 않도록 노력해 보겠어.', `FemaleText_loc4`='我会尽量让自己不因彻底摧毁你而感到过度狂喜。', `FemaleText_loc5`='我在徹底毀滅你的時候會盡量裝作沒那麼高興。', `FemaleText_loc7`='Intentaré no disfrutar demasiado cuando acabe contigo.' WHERE `ID`=40671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='덤벼! 이 좀팽아!', `FemaleText_loc4`='来啊，小矮子！', `FemaleText_loc5`='來吧，小不點!', `FemaleText_loc7`='¡TRÁELO, ALFEÑIQUE!' WHERE `ID`=40672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그건 그렇고. 싸움이 잘 마무리 됐군요. 폭력적으로 말이죠! 참가자들 이야기를 한번 들어보겠습니다!', `MaleText_loc4`='就是这样。听好了！这场冲突已经被我们用暴力引入了正轨！让我们看看敌人会有怎样的反应吧！', `MaleText_loc5`='大夥兒，就是這樣!這場衝突正在以最適合的方式解決，那就是暴力!讓我們聽聽參賽者的聲音!', `MaleText_loc7`='¡Y eso es todo, amigos! ¡Este conflicto se ha dirimido de la forma apropiada, con VIOLENCIA! ¡Veamos ahora qué opinan nuestros participantes!' WHERE `ID`=40673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 너와는 안 끝났어!', `FemaleText_loc4`='我跟你还没完呢！', `FemaleText_loc5`='我跟你還沒結束!', `FemaleText_loc7`='¡Todavía no he terminado contigo!' WHERE `ID`=40674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아! 네가 이겼다고! 난 예민한 거지 정신이 나간 게 아니야...', `FemaleText_loc4`='好吧！算你赢了！我是狡猾，可不是疯子……', `FemaleText_loc5`='好吧!你贏了!我是狡猾，並不是發瘋...', `FemaleText_loc7`='¡Vale! ¡Tú ganas! Soy astuta, no estoy loca...' WHERE `ID`=40675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 준비하라!', `MaleText_loc4`='大家坚持住！', `MaleText_loc5`='各就各位!', `MaleText_loc7`='¡Recupérense, soldados!' WHERE `ID`=40676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 경계하라! 끌려가지 마라!', `MaleText_loc4`='保持警觉！别让他们把你给拖走了！', `MaleText_loc5`='保持警戒!別讓他們把你拉走了!', `MaleText_loc7`='¡Permanezcan alerta! ¡No dejen que los arrastren!' WHERE `ID`=40677;
