UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*후욱후욱* ...아래에서는 아무런 이득도 얻을 수 없습니다! 이 벌레들은 *후우우우우욱* 먹지도 못하겠고요. 계속했더라면 이 노움이 한 대 맞을 뻔 *후우우우우우욱*', `MaleText_loc4`='*咯咯*……找不到有用的东西！这些虫子*咯咯咯*根本不能吃*咯咯咯*要狠砸这个侏儒，如果他还要*咯咯咯咯咯咯*', `MaleText_loc5`='*嘰嘰* ...這下面沒有利潤!這些蟲*嘰嘰嘰嘰嘰*不能吃*嘰嘰嘰嘰嘰嘰*揍這地精如果他繼續*嘰嘰嘰嘰嘰嘰嘰嘰嘰*', `MaleText_loc7`='*ksssshk* ...¡Aquí no hay beneficios! Estos bichos son*kssssshhhk* no hay nada para comer *khhhhshhk* voy a darle una paliza a ese gnomo si sigue *kssssssssssssssssshhhhk*' WHERE `ID`=40711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 추적자여. 우리는 Oscar Mike입니다! 반복합니다, 우리는 Oscar Mike입니다!', `MaleText_loc4`='明白，猎手。我们正在移动！重复，我们正在移动！', `MaleText_loc5`='確認，潛獵者，我們是奧斯卡麥克，我們是奧斯卡麥克!', `MaleText_loc7`='¡Afirmativo, acechador, estamos en movimiento! ¡Repito, estamos en movimiento!' WHERE `ID`=40712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 이제 당신의 고블린 친구들은 다시 행복하고 안전해졌고, 또 당신 배를 파괴할 해적도 더는 없어요!', `FemaleText_loc4`='现在你所有的地精伙伴都再次迎来了安全与快乐的生活，也不会再有海盗想要炸碎你们的船！', `FemaleText_loc5`='而現在，你所有的哥布林朋友都很開心也很安全，也不再有海盜來炸爛你的船了!', `FemaleText_loc7`='¡Ahora todos tus amigos goblins están sanos y salvos de nuevo y ya no queda ningún pirata que haga saltar tus barcos por los aires!' WHERE `ID`=40713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 과찬의 말씀을! 저도 그러고 싶어요! 당신 계속 킥킥거리며 웃고 있네요...', `FemaleText_loc4`='喔天哪，我太荣幸了！我愿意！你稍等一下，现在……', `FemaleText_loc5`='哇喔，我真是受寵若驚!我很樂意!你稍微等一下，現在...', `FemaleText_loc7`='¡Bueno, vaya, me siento tan halagada! ¡Me encantaría! Espera un segundito, verás...' WHERE `ID`=40714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 장치 배치 준비 완료. 델타 시나리오 실행. 사상자는 신경 쓰지 않음.', `FemaleText_loc4`='所有单位等待部署。执行代号德尔塔方案。不计人员伤亡。', `FemaleText_loc5`='所有單位已經準備好進行部署。執行DELTA計畫。不需要考慮傷亡人數。', `FemaleText_loc7`='Todas las unidades están listas para ser desplegadas. Ejecutad escenario delta. Las bajas no son importantes.' WHERE `ID`=40715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움이 이렇게 집을 청소하는 걸 본 적이 없어요. 당신과 같은 사람들을 고용해 나머지 해적들을 돌봐줬으면 좋겠어요. 영원히 말이에요.', `MaleText_loc4`='我从没见过想那样的侏儒大清洗，孩子。我可以派你这样的人去解决所有那些剩下的海盗，永久性的。', `MaleText_loc5`='小鬼，我從沒看過一個地精可以那麼猛。我需要一個像你這樣的人來幫我處理那些海盜，永遠都需要。', `MaleText_loc7`='Nunca había visto a ningún gnomo hacer limpieza de esa forma, joven. Podría venirme bien alguien como tú para que se hiciera cargo del resto de los piratas de forma permanente.' WHERE `ID`=40716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니지. 난 네 머리 꼭대기에 앉아 있다고, 꼬맹아. 누가 먼저 해적단 소굴을 파괴하는지 보자.', `FemaleText_loc4`='喔不，你不会的。我比你要快两步，小不点儿。让我们瞧瞧谁能先把落帆海湾夷为平地。', `FemaleText_loc5`='噢，你不會的。我比你超前了兩步，自大狂。我們到時就知道是誰會先摧毀落帆海灣。', `FemaleText_loc7`='Oh, no, nada de eso. Voy un paso por delante de ti, mequetrefe. Ya veremos quién arrasa primero la Cala del Aparejo Perdido.' WHERE `ID`=40717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁먹은 새끼 곰이 나무를 떠나지 않으려 합니다!', `MaleText_loc4`='那只受惊的小熊崽不肯离开那棵树！', `MaleText_loc5`='惶恐的幼熊拒絕離開這棵樹!', `MaleText_loc7`='¡El osezno aterrorizado se niega a abandonar el árbol!' WHERE `ID`=40718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 그론, 우리에게 복종하라. 그렇지 않으면... 그렇지 않으면... 어쨌든 그러는 게 좋다!', `MaleText_loc4`='愚蠢的戈隆，你要么服从我们，要么……要么……你最好识相点！', `MaleText_loc5`='笨古羅，你要服從我們，不然...不然...反正你最好照做!', `MaleText_loc7`='Gronn estúpido, nos obedecerás o... o... ¡Más te vale que lo hagas!', `FemaleText_loc1`='어리석은 그론, 우리에게 복종하라. 그렇지 않으면... 그렇지 않으면... 어쨌든 그러는 게 좋다!', `FemaleText_loc4`='愚蠢的戈隆，你要么服从我们，要么……要么……你最好识相点！', `FemaleText_loc5`='笨古羅，你要服從我們，不然...不然...反正你最好照做!', `FemaleText_loc7`='Gronn estúpido, nos obedecerás o... o... ¡Más te vale que lo hagas!' WHERE `ID`=40719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈에게 질렸다! 제련장인 트롱구스를 이리 불러오는 일은 너도 원치 않을 텐데!', `MaleText_loc4`='我快要受够你了！别逼我把铸炉之主索朗格斯请来！', `MaleText_loc5`='我就快要受不了你了!不要讓我叫鍛造大師瑟隆葛斯來這裡!', `MaleText_loc7`='¡Estoy harto de ti! ¡No me obligues a traer al maestro de forja Throngus!', `FemaleText_loc1`='네놈에게 질렸다! 제련장인 트롱구스를 이리 불러오는 일은 너도 원치 않을 텐데!', `FemaleText_loc4`='我快要受够你了！别逼我把铸炉之主索朗格斯请来！', `FemaleText_loc5`='我就快要受不了你了!不要讓我叫鍛造大師瑟隆葛斯來這裡!', `FemaleText_loc7`='¡Estoy harto de ti! ¡No me obligues a traer al maestro de forja Throngus!' WHERE `ID`=40720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋든 싫든 그 엘레멘티움을 옮겨라!', `MaleText_loc4`='不管你愿不愿意，你都得把那源质移开！', `MaleText_loc5`='不管你喜不喜歡，你都要把那個源質礦移開!', `MaleText_loc7`='¡Trasladarás ese elementium tanto si te gusta como si no!', `FemaleText_loc1`='좋든 싫든 그 엘레멘티움을 옮겨라!', `FemaleText_loc4`='不管你愿不愿意，你都得把那源质移开！', `FemaleText_loc5`='不管你喜不喜歡，你都要把那個源質礦移開!', `FemaleText_loc7`='¡Trasladarás ese elementium tanto si te gusta como si no!' WHERE `ID`=40721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 뒤, 조용히 해라, 안 그러면 저승에 있는 친구들을 만나게 해 줄 테니!', `MaleText_loc4`='待在那儿别动，否则你也要加入你的朋友们！', `MaleText_loc5`='別輕舉妄動，不然就讓你加入你朋友的行列!', `MaleText_loc7`='¡Guarda silencio, ahí atrás, o te reunirás con tus amigos!' WHERE `ID`=40722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징징대는 겁쟁이 같으니! 헬스크림의 호드가 네놈들 형제자매 모두에게 똑같은 운명을 안겨주겠다!', `MaleText_loc4`='只会哭鼻子的懦夫们！地狱咆哮的部落大军将让你们所有的兄弟姐妹都面对同样的命运！', `MaleText_loc5`='流鼻涕的懦夫!地獄吼的部落會讓你們所有的兄弟和姐妹擁有一樣的命運!', `MaleText_loc7`='¡Cobardes lloricas! ¡La Horda de Grito Infernal llevará a sus hermanos y hermanas a un destino similar!' WHERE `ID`=40723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 놈들! 툰드락은 자비 따위 베풀지 않는다!', `MaleText_loc4`='可怜的小东西们！桑德拉克不会对你们施以丝毫怜悯！', `MaleText_loc5`='可悲的小生物!桑德拉克對你不會有任何憐憫!', `MaleText_loc7`='¡Miserables criaturas lastimeras! ¡Thundrak no tendrá piedad de ustedes!' WHERE `ID`=40724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기와 똥은 뒤에 던져버려라. 이 노움이랑 똑같으니 말이다!', `MaleText_loc4`='把垃圾和粪便扔到后面，让这些侏儒们有东西玩儿！', `MaleText_loc5`='把你的排斥和垃圾問題丟到背後，讓這些地精至少有些同伴!', `MaleText_loc7`='¡Viertan sus restos y materia fecal en la parte de atrás para que estos gnomos tengan compañía!' WHERE `ID`=40725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나불대는 주둥이 닥치지 않으면 늑대 먹이로 삼겠다!', `MaleText_loc4`='闭上你那喋喋不休的臭嘴，否则我就把你送去喂狼！', `MaleText_loc5`='別再囉哩叭唆，不然就拿你去餵狼!', `MaleText_loc7`='¡Dejad de gemir lastimeramente u os arrojaré a los lobos!' WHERE `ID`=40726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제...제...제...발 우리 고...고...고통의 주인님을 해치지 마세요!', `MaleText_loc4`='请——请——请别伤害我们，痛苦主宰大——大人！', `MaleText_loc5`='請請請...不要傷害我們，痛痛痛苦大師，先生!', `MaleText_loc7`='P-p-p-or favor, maestro del dolor, n-n-o nos haga daño, señor.' WHERE `ID`=40727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 가라앉히게. 저 불 속에서 자신을 잊게.', `MaleText_loc4`='让心情平静。让自己沉浸在火焰中。', `MaleText_loc5`='冷靜下來。讓你自己迷失在火焰之中。', `MaleText_loc7`='Tranquilízate. Déjate llevar po'' las llamas.' WHERE `ID`=40728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하라, 동맹이여. 우리가 불의 군주를 공격할 것을 대비하여 적이 파 놓은 함정이 필시 있을 것이다.', `MaleText_loc4`='小心，朋友。炎魔之王有结界保护，让我们无法对他发动攻击。', `MaleText_loc5`='小心點，盟友。一定有陷阱保護炎魔阻止我們的入侵。', `MaleText_loc7`='Sean cautelosos, aliados. Las trampas protegerán al Señor del Fuego de nuestra incursión.' WHERE `ID`=40729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스와 싸울 준비가 되었습니다.', `MaleText_loc4`='我已经准备好开始对抗拉格纳罗斯的战斗了。', `MaleText_loc5`='我已經準備好進行對抗拉格納羅斯的戰鬥。', `MaleText_loc7`='Estoy preparado para comenzar la batalla contra Ragnaros.', `FemaleText_loc1`='라그나로스와 싸울 준비가 되었어요.', `FemaleText_loc4`='我已经准备好开始对抗拉格纳罗斯的战斗了。', `FemaleText_loc5`='我已經準備好進行對抗拉格納羅斯的戰鬥。', `FemaleText_loc7`='Estoy preparada para comenzar la batalla contra Ragnaros.' WHERE `ID`=40730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기, $g멋진 남자 분:귀여운 아가씨;. 쾌속선 주점에 오신 걸 환영해요.$B$B무엇을 찾으시나요?', `FemaleText_loc4`='嗨你好啊，$g帅哥:美女;。欢迎光临赛艇平台酒吧。$B$B想来点儿什么？', `FemaleText_loc5`='嗨，$g帥哥:美女;。歡迎來到高速駁船酒吧。$B$B想來點什麼?', `FemaleText_loc7`='Hola, $gguapo:guapa;. Te doy la bienvenida al Bar del Barcódromo.$B$B¿Qué vas a tomar?' WHERE `ID`=40731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마실 것 좀 있습니까?', `MaleText_loc4`='你们这儿有些什么饮品？', `MaleText_loc5`='你有什麼飲料?', `MaleText_loc7`='¿Qué bebidas tienes?', `FemaleText_loc1`='마실 것 좀 있나요?', `FemaleText_loc4`='你们这儿有些什么饮品？', `FemaleText_loc5`='你有什麼飲料?', `FemaleText_loc7`='¿Qué bebidas tienes?' WHERE `ID`=40732;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만나서 반가워요, $c님. 전쟁이 한창이지만, 편안한 휴식을 취하셨으면 해요.', `FemaleText_loc4`='你好，$c。希望你能有宾至如归的感觉，即使是在这战火之中。', `FemaleText_loc5`='你好，$c。希望你對這個居住環境感到滿意，這個戰爭中的簡居。', `FemaleText_loc7`='Saludos, $c. Espero que el alojamiento esté a tu altura, incluso en estos tiempos de guerra.' WHERE `ID`=40733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 해적들이 쾌속선을 파괴하기 전에 막아야 해요!', `FemaleText_loc4`='$n，请在那些海盗摧毁赛艇平台前阻止他们！', `FemaleText_loc5`='$n，請在那些海盜摧毀高速駁船前阻止他們!', `FemaleText_loc7`='¡$n, por favor, detén a esos piratas antes de que destrocen el Barcódromo!' WHERE `ID`=40734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적은 제가 상대할게요. 하지만, 그전에 먼저 술의 힘을 좀 빌려야겠습니다.', `MaleText_loc4`='我会解决那些海盗。不过首先，得先来几杯壮壮胆。', `MaleText_loc5`='我會料理這些海盜。但先來點酒精壯壯膽。', `MaleText_loc7`='Yo me ocuparé de esos piratas. Pero primero, necesito un poco de valor líquido.', `FemaleText_loc1`='해적은 제가 상대할게요. 하지만, 그전에 먼저 술의 힘을 좀 빌리는 게 좋겠네요.', `FemaleText_loc4`='我会解决那些海盗。不过首先，得先来几杯壮壮胆。', `FemaleText_loc5`='我會料理這些海盜。但先來點酒精壯壯膽。', `FemaleText_loc7`='Yo me ocuparé de esos piratas. Pero primero, necesito un poco de valor líquido.' WHERE `ID`=40735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하뮬과 말퓨리온이 도착하면 전투를 시작하지...', `MaleText_loc4`='等哈缪尔和玛法里奥一到，我们就开始……', `MaleText_loc5`='一旦哈繆爾和瑪法里恩抵達，我們將開始...', `MaleText_loc7`='Cuando lleguen Hamuul y Malfurion, comenzaremos...' WHERE `ID`=40736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 세나리우스.', `MaleText_loc4`='我们准备好了，塞纳留斯。', `MaleText_loc5`='我們準備好了，塞納留斯。', `MaleText_loc7`='Estamos listos, Cenarius.' WHERE `ID`=40737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 불의 군주와 맞서고, 놈을 이 땅에서 완전히 몰아낼 것이다!', `MaleText_loc4`='我们要直面炎魔之王，并将他的余烬残渣赶出我们的领地！', `MaleText_loc5`='我們必須面對炎魔並將他所有的餘燼都趕出我們的世界!', `MaleText_loc7`='¡Enfrentaremos al Señor del Fuego y lo borraremos de este reino, hasta la última brasa!' WHERE `ID`=40738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것 내리기 단추를 누르면 다시 쾌속호로 돌아갑니다.', `MaleText_loc4`='通过按下“离车”按钮来快速返回赛艇平台。', `MaleText_loc5`='使用離開載具這個按鍵以快速地回到高速駁船上。', `MaleText_loc7`='Utiliza el botón Abandonar vehículo para volver rápidamente a bordo del Barcódromo.' WHERE `ID`=40739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한기 도는 산바람을 불러내 라그나로스의 불길에서 우리를 보호할 것이다. 말퓨리온과 하뮬은 라그나로스의 방어를 약화시켜 우리의 전투를 도울 것이다.', `MaleText_loc4`='我会召唤冰冷的山风来保护我们，抵挡拉格纳罗斯的烈焰。玛法里奥和哈缪尔会打碎炎魔之王的防护，助我们击退他。', `MaleText_loc5`='我會召喚冰冷的山風來抵抗拉格納羅斯的火焰。瑪法里恩和哈繆爾會破壞炎魔的防禦，讓我們把他逼回去。', `MaleText_loc7`='Llamaré a la helada de la montaña para que nos proteja de la llama de Ragnaros. Malfurion y Hamuul romperán las defensas del Señor del Fuego, así podremos hacerlo retroceder.' WHERE `ID`=40740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시작하자. 시간을 너무 오래 끌다간 불의 군주가 우리의 존재를 알아채고 첨탑의 방어를 강화할 것이다.', `MaleText_loc4`='让我们开始吧。炎魔之王用不了多久就会觉察到我们的存在，并前来防御这座尖塔。', `MaleText_loc5`='我們開始吧。炎魔遲早會知道我們的存在並前來這裡防禦這座塔。', `MaleText_loc7`='Comencemos. En poco tiempo, el Señor del Fuego percibirá nuestra presencia y vendrá a la defensa de la aguja.' WHERE `ID`=40741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 살아 있는 불꽃의 전당을 더럽히느냐? 네놈들의 몸뚱이를 깡그리 불태워 주마!', `MaleText_loc4`='谁敢玷污烈焰之灵的大厅?我将烧尽你们的血肉与灵魂！', `MaleText_loc5`='是誰膽敢褻瀆烈焰的殿堂!我會燒毀你體內的生命精華!', `MaleText_loc7`='¿QUIÉN SE ATREVE A PROFANAR LA LLAMA VIVIENTE? ¡QUEMARÉ LA ESENCIA DE SU CARNE!' WHERE `ID`=40742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라! 위치로 이동하라! 놈을 불의 땅으로 돌려보내자!', `MaleText_loc4`='快点，所有人赶紧就位！把他赶回火焰之地！', `MaleText_loc5`='快點，所有人各就各位。把他逼回火源之界!', `MaleText_loc7`='¡Rápido, todos en posición! ¡Háganlo volver a las Tierras de Fuego!' WHERE `ID`=40743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀수업자의 흉터로 가고 싶습니다.', `MaleText_loc4`='送我去走私者洞穴。', `MaleText_loc5`='帶我到走私者之痕。', `MaleText_loc7`='Llévame a la Cicatriz del Contrabandista.', `FemaleText_loc1`='밀수업자의 흉터로 가고 싶어요.', `FemaleText_loc4`='送我去走私者洞穴。', `FemaleText_loc5`='帶我到走私者之痕。', `FemaleText_loc7`='Llévame a la Cicatriz del Contrabandista.' WHERE `ID`=40744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 너울 동굴로 가고 싶습니다.', `MaleText_loc4`='送我去银潮谷。', `MaleText_loc5`='帶我到銀浪谷地。', `MaleText_loc7`='Llévame a Cuenca de Marea Argenta.', `FemaleText_loc1`='은빛 너울 동굴로 가고 싶어요.', `FemaleText_loc4`='送我去银潮谷。', `FemaleText_loc5`='帶我到銀浪谷地。', `FemaleText_loc7`='Llévame a Cuenca de Marea Argenta.' WHERE `ID`=40745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_dualwield.blp:20|t%s|1이;가; |cFFFF0000검|r을 들고 |cFFFF0000|Hspell:74981|h[쌍칼]|h|r 능력을 얻습니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_dualwield.blp:20|t%s装备好|cFFFF0000剑|r并获得了|cFFFF0000|Hspell:74981|h[双持利刃]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\ability_dualwield.blp:20|t%s裝備他的|cFFFF0000劍|r並獲得了|cFFFF0000|Hspell:74981|h[雙刃攻擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_dualwield.blp:20|t¡%s equipa sus |cFFFF0000Espadas|r y obtiene |cFFFF0000|Hspell:74981|h[Hojas dobles]|h|r!' WHERE `ID`=40746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_shield_76.blp:20|t%s|1이;가; |cFFFF0000방패|r를 들고 |cFFFF0000|Hspell:74908|h[개인 밀집]|h|r 능력을 얻습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_shield_76.blp:20|t%s装备好|cFFFF0000盾牌|r并使用了|cFFFF0000|Hspell:74908|h[盾墙]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\inv_shield_76.blp:20|t%s裝備他的|cFFFF0000盾牌|r並獲得了|cFFFF0000|Hspell:74908|h[個人方陣兵]|h|r的效果!', `MaleText_loc7`='|TInterfaceIconsinv_shield_76.blp:20|t¡%s equipa su |cFFFF0000escudo|r y obtiene |cFFFF0000|Hspell:74908|h[Falange personal]|h|r!' WHERE `ID`=40747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버섯구름 봉우리로 돌아가지 않으면 거룻배를 잃습니다.', `MaleText_loc4`='如果不返回千针石林，你将失去你的赛艇。', `MaleText_loc5`='回到千針石林，否則你會失去你的河艇。', `MaleText_loc7`='Regresa a Las Mil Agujas o perderás tu barco fluvial.' WHERE `ID`=40748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 지금 이곳에서 황혼의 망치단, 라그나로스, 심지어는 데스윙을 뛰어넘는 존재를 상대하고 있다. 만약 우리가 패배하면 이 세계도 존속할 수 없을 것이다.', `MaleText_loc4`='我们在此对抗的势力远远不止暮光之锤、拉格纳罗斯甚至是死亡之翼。我们惟有取胜才能确保我们的世界不至于消亡。', `MaleText_loc5`='我們在這對抗的勢力比暮光之錘、拉格納羅斯、甚至死亡之翼都來的強大。如果不想我們的世界消失，就必須成功。', `MaleText_loc7`='Las fuerzas contra las que luchamos aquí van más allá del Martillo Crepuscular, de Ragnaros o incluso de Alamuerte. Si queremos que nuestro mundo sobreviva, debemos vencer aquí.' WHERE `ID`=40749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘은 파괴됐다! 포기해라!', `MaleText_loc4`='海加尔沦陷了！放弃吧！', `MaleText_loc5`='海加爾已經淪陷!放棄吧!', `MaleText_loc7`='¡Es el fin de Hyjal! ¡Ríndanse!' WHERE `ID`=40750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 가둘 감옥은 어디에도 없다!', `MaleText_loc4`='没有牢笼能够关住我，白痴！', `MaleText_loc5`='沒有牢籠能關住我，蠢蛋!', `MaleText_loc7`='¡Ninguna prisión me contiene!' WHERE `ID`=40751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락이 사방에 퍼져 있다! 넌 이길 수 없어!', `MaleText_loc4`='腐蚀已经泛滥了！你不可能成功！', `MaleText_loc5`='一切都已受到腐化!你不會成功的!', `MaleText_loc7`='¡La corrupción está en todos lados! ¡No ganarán!' WHERE `ID`=40752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알리스라가 걱정되는구나. 판드랄은 악몽 속에서 보았던 그 무엇보다도 심하게 타락했다. 하지만 거기 신경 쓸 여유가 없구나.', `FemaleText_loc4`='我担忧奥利瑟拉的命运。范达尔的腐蚀穿透的比任何噩梦都深。我们也没有太多时间去思考这个问题。', `FemaleText_loc5`='我替艾里絲拉感到擔心。范達爾的腐化比任何我在夢魘中見過的還要嚴重。但我們沒時間想這個問題了。', `FemaleText_loc7`='Temo por Alysra. La corrupción de Fandral es lo más profundo que he visto en la pesadilla. Pero no hay tiempo para meditarlo.' WHERE `ID`=40753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꿈속에서 아주 중요한 것을 발견했다. 이 세계의 경계를 약화시키는 균열이, 강력한 아군의 귀환을 앞당기고 있노라.', `FemaleText_loc4`='在梦境中，我有了一个重大的发现。那道削弱世界边际的裂隙如今加快了强大盟友的归来。', `FemaleText_loc5`='我在夢境中發現了一件重要的事。弱化這個世界邊界的裂縫加速了強力盟友們的回歸。', `FemaleText_loc7`='Durante mi visita al sueño, descubrí algo vital. La fisura que debilita los límites de este mundo ha acelerado el regreso de aliados poderosos.' WHERE `ID`=40754;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고대의 수호자들이 돌아오고 있다. 세나리우스, 아비아나, 골드린... 그들의 존재가 느껴진다. 반드시 우리가 수호자들을 이 세상으로 이끌어야 한다. 그들의 도움이 꼭 필요하니.', `FemaleText_loc4`='上古的守护者正在归来。塞纳留斯、艾维娜、戈德林……我能感受到他们的气息。我们必须确保他们能顺利回归。他们的及时援助将是不可或缺的。', `FemaleText_loc5`='古代的守護者們正在回歸。塞納留斯、艾維娜、戈德林...我能感覺到他們的存在。我們必須將他們接引回這個世界。我們需要他們及時的幫助。', `FemaleText_loc7`='Vuelven los Guardianes Antiguos. Cenarius, Aviana, Goldrinn... Siento sus presencias. Tenemos que ayudarlos a entrar a este mundo. Su ayuda oportuna será indispensable.' WHERE `ID`=40755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기본적인 분석 결과가... 내가 계속 싸우는 것을 멈추는 것을 권하고 있어.', `FemaleText_loc4`='初步分析显示……我不能再继续了。', `FemaleText_loc5`='初步分析指出...我無法繼續。', `FemaleText_loc7`='Un análisis preliminar sugiere... que soy capaz de continuar.' WHERE `ID`=40756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 멋진 공격이었어. 그렇지만 여기는 이제 고블린 영역이야. 이 사실에 익숙해져야 할 거야.', `FemaleText_loc4`='你的表现很好，孩子。可这里现在是地精的地盘了。我建议你努力去适应。', `FemaleText_loc5`='你做得不錯，小鬼，但這現在是哥布林的地盤了。我建議你好好習慣它。', `FemaleText_loc7`='Lo has intentado, joven. Pero ahora no es más que basura goblin. Te sugiero que te acostumbres.' WHERE `ID`=40757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 만나자, 친구. 언제 점심 같이 먹고 싶으면 말해. 이제 네가 예절을 좀 배웠으니까 앞으로 잘 지낼 수 있을 거야.', `FemaleText_loc4`='再见了，宝贝儿。要是你想要找个时间共进午餐，记得告诉我一声。既然你已经学会了一些礼节，我们会想出办法来的。', `FemaleText_loc5`='掰掰，寶貝。當你想共進午餐時，就跟我打聲招呼。既然你已經學了些禮儀，機會總是會有的。', `FemaleText_loc7`='Adiós, cariño. Hazme saber si te gustaría comer conmigo alguna vez. Podría funcionar ahora que has aprendido buenos modales.' WHERE `ID`=40758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈쉬르 감시기가 당신을 발견했습니다!', `MaleText_loc4`='你被艾萨尔监控器发现了！', `MaleText_loc5`='一個艾薩伊爾監控裝置看到了你!', `MaleText_loc7`='¡Un supervisor de Azsh''ir te ha detectado!' WHERE `ID`=40759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈쉬르 감시기가 지원 요청을 보냅니다!', `MaleText_loc4`='艾萨尔监控器发出了求援信号！', `MaleText_loc5`='一個艾薩伊爾監控裝置在呼救!', `MaleText_loc7`='¡Un supervisor de Azsh''ir pide ayuda!' WHERE `ID`=40760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 없애겠다는 건가? 우리의 비밀을 알고 싶겠지...', `MaleText_loc4`='它想要杀了我们？想要知道我们的秘密……', `MaleText_loc5`='想殺了我們是嗎?想要知道我們的秘密...', `MaleText_loc7`='Matarnos quiere, ¿verdad? Conocer quiere nuestros secretos...' WHERE `ID`=40761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자를 반드시 파괴해야 한다.', `MaleText_loc4`='我们必须消灭它。', `MaleText_loc5`='我們必須摧毀它。', `MaleText_loc7`='Destruirlo debemos.' WHERE `ID`=40762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자를 불태우자, 불태우는 거야! 불을 가져와라, 그렇지!', `MaleText_loc4`='我们烧了它，烧了它！火大点儿，就这样！', `MaleText_loc5`='我們燒了它，我們燃燒!帶來火焰，火焰!', `MaleText_loc7`='¡Lo quemaremos, lo quemaremos! ¡Que venga el fuego, sí!' WHERE `ID`=40763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람아, 불어라. 조용히 오너라... 이리 와 저자를 날려 버려라, 저 멀리 날려 버려라!', `MaleText_loc4`='风啊，悄悄地，悄悄地……吹它，吹它，将它吹飞！', `MaleText_loc5`='風來吧，細語細語...吹它，吹它，把它吹走!', `MaleText_loc7`='Vientos venid, susurra, susurra... Sopla, sopla, ¡y lo derriba!' WHERE `ID`=40764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는...저자를 부순다! 반드시... 부숴야 한다. 친구들아, 서둘러라!', `MaleText_loc4`='我们……粉碎它！必须……粉碎。快点儿朋友们！', `MaleText_loc5`='我們...摧毀它!必須...要摧毀。朋友，快!', `MaleText_loc7`='¡Aplastaremos... nosotros! ¡Aplastar... debemos! ¡Deprisa, amigos!' WHERE `ID`=40765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저자가 알아선 안 된다... 내주어선 안 된다... 우리의 비밀을...', `MaleText_loc4`='不能让它知道……不能让它了解……我们的……', `MaleText_loc5`='不能被發現...不能被瞭解...什麼是我們的...', `MaleText_loc7`='No debe saber... no debe saber... lo que es nuestro.' WHERE `ID`=40766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 불리한 상황인 것은 사실이지만, 그렇다고 여기서 물러설 순 없습니다, $n 님. 이 방어선이 무너지면 놀드랏실은 그대로 적의 손에 넘어갈 테니까요.', `FemaleText_loc4`='我们的胜算不大，但我们不能退缩，$n。在敌人的大军和诺达希尔之间就只剩下我们这一道屏障。', `FemaleText_loc5`='幸運之神似乎不眷顧我們，但我們不能畏縮，$n。我們是最後能夠進行戰鬥，保護諾達希爾的人了。', `FemaleText_loc7`='Parece que todo está en nuestra contra, pero no debemos flaquear, $n. Nosotros somos lo único que se interpone entre las hordas del enemigo y Nordrassil.' WHERE `ID`=40767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수... 숨이 막힐 것 같아요... 돌아가야겠어요!', `FemaleText_loc4`='我……我快要没气了……我必须调头！', `FemaleText_loc5`='我...我快喘不過氣來了...我必須回頭!', `FemaleText_loc7`='Me... me estoy quedado sin aliento... ¡Debo regresar!' WHERE `ID`=40768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안으로 오세요, $r님! 당신의 친절에 보답해야겠습니다.', `FemaleText_loc4`='请进来，$r。我必须报答你的恩情。', `FemaleText_loc5`='進來吧，$r。我必須回報你。', `FemaleText_loc7`='Entra, $r. Debo recompensar tu amabilidad.' WHERE `ID`=40769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발요, $r님.$b$b여기서 얼마나 더 버틸 수 있을지 모르겠어요...', `FemaleText_loc4`='拜托了，$r。$b$b我不知道自己还能在这儿撑多久……', `FemaleText_loc5`='拜託，$r。$b$b我不知道我在這還能撐多久...', `FemaleText_loc7`='Por favor, $r.$b$bNo sé cuánto tiempo más podré aguantar aquí...' WHERE `ID`=40770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오십시오! 밀수업자의 흉터까지 데려다 드리겠습니다.', `MaleText_loc4`='跟我来！我带你去走私者洞穴。', `MaleText_loc5`='跟著我!我會帶你到走私者之痕。', `MaleText_loc7`='¡Sígueme! Te llevaré a la Cicatriz del Contrabandista.', `FemaleText_loc1`='따라오세요! 밀수업자의 흉터까지 데려다 드리겠어요.', `FemaleText_loc4`='跟我来！我带你去走私者洞穴。', `FemaleText_loc5`='跟著我!我會帶你到走私者之痕。', `FemaleText_loc7`='¡Sígueme! Te llevaré a la Cicatriz del Contrabandista.' WHERE `ID`=40771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비, 조준... 발사!', `MaleText_loc4`='准备，瞄准……开火！', `MaleText_loc5`='準備，瞄準...開火!', `MaleText_loc7`='Preparados, apunten... ¡FUEGO!', `FemaleText_loc1`='준비, 조준... 발사!', `FemaleText_loc4`='准备，瞄准……开火！', `FemaleText_loc5`='準備，瞄準...開火!', `FemaleText_loc7`='Preparados, apunten... ¡FUEGO!' WHERE `ID`=40772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위즐, 이 바보 같은 녀석! 네가 입만 다물고 있었으면 모든 게 다 완벽했을 거야!', `MaleText_loc4`='维兹，你这白痴！要是你能管住你的嘴，一切就都不会出问题！', `MaleText_loc5`='維茲爾，你這白癡!都是因為你不閉上你的狗嘴事情才會變成這樣!', `MaleText_loc7`='¡Wizzle, eres un idiota! ¡Todo habría ido bien si hubieras cerrado la boca!' WHERE `ID`=40773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 우리에서 나 좀 꺼내줘!!!', `MaleText_loc4`='快来人把我从这笼子里放出去！！！', `MaleText_loc5`='誰來把我從這籠子裡救出去!', `MaleText_loc7`='¡¡Que alguien me saque de esta jaula!!' WHERE `ID`=40774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위즐, 내가 여기서 나가기만 해봐라. 네 목을 졸라 버릴 테다!', `MaleText_loc4`='只要我一出去，我就立刻把你掐死，维兹！', `MaleText_loc5`='我一出去一定要掐死你，維茲爾!', `MaleText_loc7`='¡Voy a estrangularte en cuanto salgamos de aquí, Wizzle!' WHERE `ID`=40775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 내 계획은 잘 풀리고 있었어. 이 해적들에게 소총을 한꺼번에 팔아서 떼돈을 벌 생각이었지! 하지만, 실패했어! 날 몰래 따라와 싸구려 기계공학 부품을 팔려던 위즐이 해적들의 대포와 내 소총을 폭파해버렸거든! 우린 이제 끝장이야!', `MaleText_loc4`='我在这儿本来好好的。我正准备把一堆步枪卖给那些海盗，发笔小财！可是，不！维兹尾随而来，想要让他们买下他那些廉价的工程学零件。结果却把他们的几座火炮和我的步枪都给炸毁了！我们势不两立！', `MaleText_loc5`='本來在這有個好機會。我打算把步槍賣給這些海盜來大賺一筆!但是!維茲爾一定要跟過來把他的那些便宜工程貨賣給他們，然後在過程中炸飛了一些他們的大砲和我的步槍!我們完蛋了!', `MaleText_loc7`='¡Tenía un buen trato entre manos. Iba a venderles a los piratas unos cuantos rifles a cambio de una fortuna! ¡Pero no! Wizzle tenía que venir conmigo para intentar venderles sus burdas piezas de ingeniería. ¡Y de paso, para volar unos cuantos de los cañones de los piratas y de mis rifles! ¡Estamos condenados!' WHERE `ID`=40776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 고마워요!', `FemaleText_loc4`='喔，谢谢你！', `FemaleText_loc5`='噢，謝謝你!', `FemaleText_loc7`='Oh, ¡gracias!' WHERE `ID`=40777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구지? 나 좀 꺼내줘! 이 냄새나는 해적들이 날 꼬챙이에 꽂아서 녹색 계란말이로 만들기로 하기 전에 말이야!', `MaleText_loc4`='谁在那儿？放我出去！趁这些臭死人的海盗还没决定把我蘸上口水做成绿色的火腿炒蛋，快放我出去！', `MaleText_loc5`='有人在嗎?放我出來!放我出來!在這些噁心的海盜把我放在肉叉上，做成綠色火腿之前!', `MaleText_loc7`='¿Quién está ahí? ¡Sácame de aquí! ¡Sácame de aquí antes que esos apestosos piratas decidan ponerme en una parrilla y hacer conmigo huevos verdes con jamón!' WHERE `ID`=40778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사를 대표하여, 나를 이 우리에서 나가게 해주는 첫 번째 사람에게 매우 후한 상을 내리겠다! 당연히 계약상의 조건이 적용되겠지만, 작은 글자 부분은 내가 책임질 테니 그저 여기서 나가게만 해줘!', `MaleText_loc4`='请允许我代表锈水财阀，向第一个把我从这笼子里放出去的人赠予慷慨奖励！当然，还是要遵守标准合同条款的规定，但不用在意那些细枝末节。只要你能快点儿放我出去！', `MaleText_loc5`='我代表污水企業，將給予第一位讓我脫離這個籠子的人豐厚的獎勵!當然，一般的合約規定還是通用的，但先不用考慮細則上的問題。把我弄出去就對了!', `MaleText_loc7`='En nombre del Cártel Pantoque, ¡permíteme que ofrezca una generosa recompensa al primero que me saque de esta jaula! Por supuesto, se aplicarán las cláusulas contractuales habituales, pero no te preocupes por la letra pequeña. ¡Simplemente sácame de aquí!' WHERE `ID`=40779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 자네 해적인가?! 이제 장난 좀 그만 치자고. 여기서 나가게만 해주면 쾌속선에 있는 신형소총들을 공짜로 준다니까!', `MaleText_loc4`='嘿，你是海盗吗？！快点儿过来，别再到处瞎闹了。把我从这儿放出去，我会给你们大家好多把全新的步枪——只要让我从赛艇平台把这些步枪拿出来！', `MaleText_loc5`='喂，你是海盜?!快過來，別鬧了。把我弄出去我就會在最快的時間內到高速駁船把最新的步槍寄給你們!', `MaleText_loc7`='¡Eh, oye, piratas! Venga, dejad de hacer bromas. Sacadme de aquí y os enviaré un cargamento de rifles nuevecitos en cuanto lo descargue del Barcódromo!' WHERE `ID`=40780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 저 대포 좀 처리해 줄 수 없어? 나 지금 머리가 안 돌아가!', `MaleText_loc4`='有没有人能对那些火炮做点儿什么？我在这儿没办法好好思考了！', `MaleText_loc5`='有人能處理一下那些大砲嗎?我現在無法正常思考!', `MaleText_loc7`='Que alguien haga algo son esos cañones, por favor. ¡Ni siquiera puedo oírme pensar!' WHERE `ID`=40781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱, 당신이 날 이 난장판에 끌어들이다니 믿을 수 없군요, 이 바보 같은 고블린 같으니라고!', `MaleText_loc4`='赛恩格，没想到你居然让我们陷入这样的混乱，你这个愚蠢的地精！', `MaleText_loc5`='賽恩格，我不敢相信你竟然讓我們身處於這種混亂，你這白癡哥布林!', `MaleText_loc7`='Synge, ¡no puedo creer que nos hayas metido en este lío, goblin estúpido!' WHERE `ID`=40782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불의 땅 어딘가에서 피조물을 불러냅니다.', `MaleText_loc4`='%s开始召唤某种火焰之地的怪物。', `MaleText_loc5`='%s從火源之界其他地方叫出了生物。', `MaleText_loc7`='%s convoca a criaturas de otras partes de las Tierras de Fuego.' WHERE `ID`=40783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 맙소사! 오 맙소사! 누가 나 좀 여기서 내보내 줘요! 전 그.. 밀실.. 밀실 뭐더라.. 음, 어쨌든 전 좁은 곳에 갇히는 걸 두려워하는 병이 있어요!', `MaleText_loc4`='喔我的天哪！喔我的天哪！快来人放我出去！我有幽闭恐惧症……幽闭……幽闭……呃，反正就是怕被关在笼子里！', `MaleText_loc5`='我的老天!我的老天啊!誰來救我出去!我有...什麼...呃...什麼恐懼症，就是怕被關在籠子裡那種!', `MaleText_loc7`='¡Oh, dios mío! ¡Oh, dios mío! ¡Que alguien me saque de aquí! Tengo claustro... claustro... claustro... eh, miedo a estar encerrado en una jaula!' WHERE `ID`=40784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 하늘담에서 피조물을 불러냅니다.', `MaleText_loc4`='%s开始召唤天空之墙的怪物。', `MaleText_loc5`='%s從天空之牆叫出了生物。', `MaleText_loc7`='%s convoca a criaturas del Muro Celeste.' WHERE `ID`=40785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심원의 영지 깊은 곳에서 피조물을 불러냅니다.', `MaleText_loc4`='%s开始召唤深岩之洲核心的怪物。', `MaleText_loc5`='%s從地深之源的核心地區叫出了生物。', `MaleText_loc7`='%s convoca a criaturas del corazón de Infralar.' WHERE `ID`=40786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 그래 거기 당신! 제발, 제발, 제발 부탁이니, 저 좀 이 우리에서 내보내 줘요!', `MaleText_loc4`='喂，你，快过来！拜托了，拜托了，拜托了，快把我从这笼子里放出去！', `MaleText_loc5`='喂，在那邊的!拜託，拜託，拜託，把我從這籠子中放出來!', `MaleText_loc7`='¡Eh, tú, aquí! ¡Por favor, por favor, sácame de esta jaula!' WHERE `ID`=40787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 제 특급 형태 완전 변신 광선총으로 당신을 어떻게 변신시킬지 목록을 작성하고 있어요, 싱! 당신의 그 형편없는 삶과 꼭 들어맞는 완전 쓸데없는 물건이 되어버렸으면 좋겠네요.', `MaleText_loc4`='我正在列出可以用超适应性变形射线把你变成哪些样子，赛恩格！我希望你最后能变成毫无用处的蠢货，来搭配你悲剧的人生。', `MaleText_loc5`='我正在做一個表，一個可以用我的超級適應變形轉換形成光束把你變形的生物列表，賽恩格!我希望你最終變成一個配得上你這可悲一生的垃圾生物。', `MaleText_loc7`='¡Synge, estoy haciendo una lista de todas las cosas en las que puedo transformarte con mi Rayo Transformador de Forma Súper Adaptativo! Espero que termines siendo algo completamente inútil que vaya a juego con tu patética vida.' WHERE `ID`=40788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적 친구들, 잘 들으세요. 전 이 싱이라는 자와 아무 관련이 없어요. 만약 당신이 저를 이 우리에서 꺼내준다면, 전 당신들이 썼던 기술자 중 최고의 기술자가 될 겁니다. 제가 보장해요. 당신들이 쏜 대포의 정확도를 보세요. 아깝긴커녕, 너어어어어어무 빗나가잖아요!', `MaleText_loc4`='海盗朋友们，听好了。我跟这个叫赛恩格的家伙不是一伙的。我向你们保证，要是你们能把我从这笼子里放出去，你们会发现我是你们所遇到的最顶级的工程师。我是说——真的，你们见识过你们火炮的精准性吧？非常接近目标，可还是差了好——远！', `MaleText_loc5`='海盜朋友，聽著。我跟這個賽恩格沒有關係。如果你放我出去，我可以保證我一定是你碰過最棒的工程師。說真的，你有看過你們大砲的精準度嗎?每次都差點打中目標，但打不中就是打不中!', `MaleText_loc7`='Amigos piratas, escuchen. Yo no tengo nada que ver con ese Synge. Les puedo asegurar que si me dejan salir de esta jaula, seré el mejor ingeniero que hayan tenido nunca. De verdad, hablando en serio, ¿han visto la precisión que tienen sus cañones? ¡Tan cerca pero a la vez taaaaaaaan lejos!' WHERE `ID`=40789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 결백한 노움 하나 좀 우리에서 꺼내주실 수 있나요? 제발 생각 좀 해보세요, 이런 제안을 받는 게 어디 흔한 일인가요?', `MaleText_loc4`='谁愿意把一个无辜的侏儒从笼子里放出去？快点儿动手吧。这样的机会可不常有！', `MaleText_loc5`='誰能把一個無辜的地精放出籠子?想想看，這種機會是很難得的!', `MaleText_loc7`='¿Quién quiere sacar de esta jaula a un inocente gnomo? Venga, hombre. ¿Cuántas veces recibiréis una oferta como esta?' WHERE `ID`=40790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱, 당신의 뺨을 몇 대 때리고 나서, 수십 대 더 때려주고 싶네요! 두고 보시라니까요. 제가 우리 밖으로 나가기만 하면 갇혀 있는 당신을 보며 실컷 비웃어 줄 거라고요!', `MaleText_loc4`='赛恩格，我要打扁你，然后再打扁你！等着瞧吧。我要从这笼子里出去，然后幸灾乐祸地嘲笑你！', `MaleText_loc5`='賽恩格，我要好好的侮辱你一下!看著吧。我會逃出這個籠子後在你面前炫耀和嘲笑你!', `MaleText_loc7`='¡Synge, voy a darte una paliza y luego otra! Ya verás. ¡Voy a salir de esta jaula y luego me regodearé y me reiré de ti!' WHERE `ID`=40791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 해적분들, 제가 사라진 걸 알면 형제들이 몹시 걱정스러워 할 거예요, 저 좀 보내주시면 안 될까요? 리즐은 술 주정뱅이고 피즐은 고혈합을 앓고 있다고요!', `MaleText_loc4`='嗯，海盗们，我的失踪一定正让我的兄弟们忧心不已。也许你能放我出去？里兹尔经常喝醉酒，而菲兹尔有血压高的毛病！', `MaleText_loc5`='嗯，海盜，我的兄弟如果發現我不見一定會很著急。或許你可以放我走?瑞茲爾有酗酒的問題而菲茲爾也有血壓上的問題!', `MaleText_loc7`='Em, piratas, mis hermanos se van a preocupar mucho al ver que he desaparecido. ¿Quizá queráis dejarme marchar? ¡Rizzle tiene problemas con la bebida y Fizzle tiene problemas con la presión sanguínea!' WHERE `ID`=40792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 봤나?', `MaleText_loc4`='你看见了吗？', `MaleText_loc5`='你有看到嗎?', `MaleText_loc7`='¿Has visto eso?', `FemaleText_loc1`='방금 봤나?', `FemaleText_loc4`='你看见了吗？', `FemaleText_loc5`='你有看到嗎?', `FemaleText_loc7`='¿Has visto eso?' WHERE `ID`=40793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어!', `MaleText_loc4`='好啊！', `MaleText_loc5`='好!', `MaleText_loc7`='¡De acuerdo!', `FemaleText_loc1`='좋았어!', `FemaleText_loc4`='好啊！', `FemaleText_loc5`='好!', `FemaleText_loc7`='¡De acuerdo!' WHERE `ID`=40794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=40795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명중이다!', `MaleText_loc4`='正中靶心！', `MaleText_loc5`='正中紅心!', `MaleText_loc7`='¡Diana!', `FemaleText_loc1`='명중이다!', `FemaleText_loc4`='正中靶心！', `FemaleText_loc5`='正中紅心!', `FemaleText_loc7`='¡Diana!' WHERE `ID`=40796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법은 도구입니다. 다른 이들은 심지어 선물이라고도 하죠. 하지만 그대는 마법의 기초적인 본질을 절대 잊어서는 안 됩니다.', `FemaleText_loc4`='魔法是个工具，有些人甚至会把它当作馈赠。可你永远不应该忘记它的本性。', `FemaleText_loc5`='魔法是一項工具，有些人會說是天賦。但你永遠都不該忘了它原始的自然法則。', `FemaleText_loc7`='La magia es una herramienta, algunos incluso dirían que es un don. Pero nunca debes olvidar su naturaleza fundamental.' WHERE `ID`=40797;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비전 마법은 우리 세계의 경계를 일그러뜨립니다. 잠시 이 세계의 질서를 약하게 하여 불가능한 일들을 실현 가능하게 하지요.', `FemaleText_loc4`='奥术魔法扭曲了我们世界的边界。它弱化了这个空间的自然定律，使原本不可能发生的事情变为了可能——就算只是在片刻。', `FemaleText_loc5`='秘法之術扭曲了我們世界的界限。它弱化了這個空間的法則，使不可能發生的事變為可能，就算只有一瞬間。', `FemaleText_loc7`='La magia Arcana retuerce los límites de nuestro mundo. Debilita las leyes de este reino para permitir que suceda lo imposible, aunque solo sea por un momento.' WHERE `ID`=40798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 잠깐의 순간이 한 악마가 대혼란을 일으키는 데 필요한 전부에요. 불타는 군단은 너무나도 오랜 세월 우리를 지켜봤어요. 슬며시 빠져나갈 수 있는 가장 작은 틈바구니, 속삭일 가장 미약한 동요를 기다리면서 말이에요.', `FemaleText_loc4`='可恶魔只需要那片刻的时间就能造成浩劫。燃烧军团已经盯了我们上千年，总是想伺机抓住最小的裂隙趁虚而入，利用最小的骚动制造混乱。', `FemaleText_loc5`='只要那麼一瞬間的時間就可讓惡魔帶來毀滅。燃燒軍團在千年中一直注視著我們，一直在等待任何一個小機會，任何一個破綻進行穿越進入我們的世界。', `FemaleText_loc7`='Ese momento es todo lo que necesita un demonio para causar la destrucción. La Legión Ardiente lleva siglos observándonos, siempre esperando a que se abra la más mínima brecha para colarse por ella, a que haya el más mínimo movimiento para aprovecharse de él.' WHERE `ID`=40799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젊은 분, 아무리 작더라도 그대가 시전하는 모든 주문은 두 가지 상반된 결과를 낳는다는 걸 기억하세요. 왜 마법을 장난삼아 사용해서는 절대 안 되는지의 이유예요.', `FemaleText_loc4`='记住这一点，年轻人。你所施放的每一个法术，不管威力多么不值一提，都会产生两方面的影响。这也正是严禁随意使用法术的原因。', `FemaleText_loc5`='記住，年輕的人啊，任何一個你所詠唱的法術，不管多麼地微小，都是一個雙面刃。這就是為什麼魔法的使用必須非常慎重。', `FemaleText_loc7`='Recordad esto, jóvenes. Cada hechizo que invoquéis, sin importar lo insignificante que sea, afecta en ambos sentidos. Por eso no debemos tomar la brujería con frivolidad.' WHERE `ID`=40800;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 망치단은 나에게 조직 그 이상의 의미가 있다. 가족이나 다름없지.$B$B자격 미달인 지원자가 훈련 과정을 통과하지 못하도록 내가 각별한 주의를 기울이는 것도 다 이런 이유 때문이다.', `FemaleText_loc4`='暮光之锤对我来说不仅仅是个组织。它就像是我的家。$B$B所以，我严加小心以确保不会有人滥竽充数地通过训练。', `FemaleText_loc5`='暮光之錘對我來說不單只是個組織。它是個家庭。$B$B因此，我非常注意，不會讓不夠資格的人通過訓練階段。', `FemaleText_loc7`='Para mí, el Martillo Crepuscular es más que una organización.$B$BPor eso yo me encargo de que los candidatos que no sean dignos no pasen la fase de instrucción.' WHERE `ID`=40802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 안전한 장소를 찾아내야 하오.$b$b맥의 상태가 심상치 않소.', `MaleText_loc4`='我得尽快找个安全的地方。$b$b老马克的情况不太好。', `MaleText_loc5`='我必須趕快找個安全的地方。$b$b老麥客的情況不太好。', `MaleText_loc7`='Tengo que encontrar un lugar seguro pronto.$b$bEl viejo Mack no está tan bien.' WHERE `ID`=40803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 서쪽에 있는 동굴로 갑시다. 안전하고 축축하지도 않습니다.', `MaleText_loc4`='到西边那个洞穴去。那里安全又干燥。', `MaleText_loc5`='到西方的洞窟，那裡是安全和乾燥的。', `MaleText_loc7`='Pon rumbo a esa cueva que hay al oeste. Es segura y está seca.', `FemaleText_loc1`='저기 서쪽에 있는 동굴로 가요. 안전하고 축축하지도 않아요.', `FemaleText_loc4`='到西边那个洞穴去。那里安全又干燥。', `FemaleText_loc5`='到西方的洞窟，那裡是安全和乾燥的。', `FemaleText_loc7`='Pon rumbo a esa cueva que hay al oeste. Es segura y está seca.' WHERE `ID`=40804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못해요! 여기에선 돌아버릴 지경이라고요!', `MaleText_loc4`='我受不了了，伙计！我在这儿快要发疯了！', `MaleText_loc5`='我快不行了!我快嚇死了!', `MaleText_loc7`='¡No puedo más, tío! ¡Yo me largo!' WHERE `ID`=40805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 되어가나요?! 지금 움직여야 하는데, 지금 말이에요! 지금이라고 말했잖아요!', `MaleText_loc4`='发生什么事了？！我们必须马上行动！我说马上！', `MaleText_loc5`='發生了什麼事?!我們必須馬上行動!我說馬上!', `MaleText_loc7`='¿Qué sucede? ¡Tenemos que actuar YA! ¡DIGO QUE YA!' WHERE `ID`=40806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교수님, 여기에서는 시간만 낭비할 뿐이에요. 오크가 우릴 결딴내는 상황이라고요!', `MaleText_loc4`='我们是在浪费时间，教授！兽人在屠杀我们！', `MaleText_loc5`='我們現在是在浪費時間，教授!獸人正在屠殺我們!', `MaleText_loc7`='¡Aquí perdemos el tiempo, profesor! ¡Los orcos nos están destrozando!' WHERE `ID`=40807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 쓰레기 같은 일을 하겠다고 취직한 게 아니에요! 돌아가서 멕카토크 님의 놈리건 탈환을 도와드릴 수도 있었다고요!', `MaleText_loc4`='我可没主动报名来蹚这浑水！我本该回去帮梅卡托克夺回诺莫瑞根！', `MaleText_loc5`='我來這不是為了這些鳥事!我本來可以幫梅卡托克一起奪回諾姆瑞根!', `MaleText_loc7`='¡Yo no me alisté para esta basura! ¡Podría haberme quedado para ayudar a Mekkatorque a recuperar Gnomeregan!' WHERE `ID`=40808;
