UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들아, 오늘 너희의 실패가 이 세상의 종말을 예견하는구나. 내 아이들이 새로운 시대를 열 것이다. 불꽃이 지배하는 시대를!', `MaleText_loc4`='凡人，你们今日的失败昭示了旧世界的终结。我的子嗣将会引领烈焰统治的新纪元！', `MaleText_loc5`='你們凡人今日的失敗預告了你們世界的終結。我的孩子們將會在由火焰統治的新紀元中引領風騷!', `MaleText_loc7`='HOY, SU FRACASO PREMONIZA EL FIN DE SU MUNDO.  ¡MIS HIJOS LIDERARÁN UNA NUEVA ERA, REINADA POR LA LLAMA!' WHERE `ID`=40837;
