UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 톱날 투척기입니다, 총감독관님.', `MaleText_loc4`='一台……掷刀车，长官。', `MaleText_loc5`='長官，一台...一台刀刃發射器。', `MaleText_loc7`='Un... un lanzacuchillos, señor.', `FemaleText_loc1`='음... 톱날 투척기입니다, 총감독관님.', `FemaleText_loc4`='一台……掷刀车，长官。', `FemaleText_loc5`='長官，一台...一台刀刃發射器。', `FemaleText_loc7`='Un... un lanzacuchillos, señor.' WHERE `ID`=40843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더럽다! 네놈의 나약한 육체가 내 작품을 더럽힌다.', `MaleText_loc4`='亵渎！你们脆弱的血肉玷污了我的工作。', `MaleText_loc5`='污穢!你脆弱的血肉褻瀆我的作品。', `MaleText_loc7`='¡Impureza! Tu carne frágil mancilla mi trabajo.' WHERE `ID`=40844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1을;를; 공격하는 정령을 처치하십시오!', `MaleText_loc4`='击败正在攻击%s的火元素！', `MaleText_loc5`='擊敗正在攻擊%s的火焰元素!', `MaleText_loc7`='¡Acaba con los elementales de fuego que atacan a %s!' WHERE `ID`=40845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러졌습니다!', `MaleText_loc4`='%s倒下了！', `MaleText_loc5`='%s已死亡!', `MaleText_loc7`='¡%s ha caído!' WHERE `ID`=40846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 회복해 다시 싸우기 시작합니다!', `MaleText_loc4`='%s恢复过来，重新加入战斗！', `MaleText_loc5`='%s已經復原並繼續開始戰鬥!', `MaleText_loc7`='¡%s se ha recuperado y vuelve a la batalla!' WHERE `ID`=40847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러졌습니다!', `MaleText_loc4`='%s倒下了！', `MaleText_loc5`='%s已死亡!', `MaleText_loc7`='¡%s ha caído!' WHERE `ID`=40848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 힘을 회복해 다시 싸우기 시작합니다!', `MaleText_loc4`='%s恢复过来，重新加入战斗！', `MaleText_loc5`='%s已經復原並繼續開始戰鬥!', `MaleText_loc7`='¡%s se ha recuperado y vuelve a la batalla!' WHERE `ID`=40849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 통크가 탑 꼭대기에서 자넬 기다리고 있네.', `MaleText_loc4`='索恩克正在塔顶等着你，$c。', `MaleText_loc5`='通克正在塔的頂端等你，$c。', `MaleText_loc7`='Thonk te espera en lo alto de la torre, $c.', `FemaleText_loc1`='$c|1이여;여;, 통크가 탑 꼭대기에서 자넬 기다리고 있네.', `FemaleText_loc4`='索恩克正在塔顶等着你，$c。', `FemaleText_loc5`='通克正在塔的頂端等你，$c。', `FemaleText_loc7`='Thonk te espera en lo alto de la torre, $c.' WHERE `ID`=40850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 톱날이 날카로워 보이나? 그런가, 감독관?', `MaleText_loc4`='这些刀刃在你看来够锋利吗？锋利吗，监工？', `MaleText_loc5`='你覺得這些刀刃看起來鋒利嗎?鋒利嗎，監督?', `MaleText_loc7`='¿Acaso te parece que estos cuchillos están afilados? ¿TE LO PARECEN, SOBRESTANTE?' WHERE `ID`=40851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 날 도와라!', `MaleText_loc4`='协助我，孩子们！', `MaleText_loc5`='協助我，我的孩子們!', `MaleText_loc7`='¡AYÚDENME, HIJOS MÍOS!' WHERE `ID`=40852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 살을 불태우고 뼈를 그슬려라!', `MaleText_loc4`='烧尽他们的血肉筋骨！', `MaleText_loc5`='燒他們的肉，烙他們的骨!', `MaleText_loc7`='¡QUEMEN SU CARNE, ABRASEN SUS HUESOS!' WHERE `ID`=40853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종말의 순간이 조금 미뤄졌을 뿐이다, 세나리우스. 불의 땅에서 내 군대가 또다시 태어날 것이다...', `MaleText_loc4`='你不过是在拖延时间，塞纳留斯。我的军团将在火焰之地重生……', `MaleText_loc5`='你只是延緩了不可避免的結果，塞納留斯。我的軍隊將在火源之界重生...', `MaleText_loc7`='SÓLO HAN RETRASADO LO INEVITABLE, CENARIUS. MIS EJÉRCITOS RENACERÁN DE LAS TIERRAS DE FUEGO…' WHERE `ID`=40854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 자네들이 하는 일이 뭐라고 생각하는 건가?', `MaleText_loc4`='你们这些兽人知不知道自己究竟在做什么？', `MaleText_loc5`='你們這些獸人他X的到底在想什麼?', `MaleText_loc7`='¿Qué demonios creéis que estáis haciendo los orcos?' WHERE `ID`=40855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚싯대라니... 투스카르 같군. 더 나쁘게 말하자면, 인간 같아.', `MaleText_loc4`='钓鱼竿……你们钓鱼的样子就像海象人。甚至更糟，简直像人类。', `MaleText_loc5`='魚竿...你像個海象人一樣的釣魚。或更糟，像個人類一樣。', `MaleText_loc7`='Cañas de pescar... Pescas como un tuskarr. O peor aún, como un humano.' WHERE `ID`=40856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늙은 오크가 일하는 법을 알려 주지!', `MaleText_loc4`='让老兽人教教你应该怎样做！', `MaleText_loc5`='讓一個老獸人教你真正應該怎麼做!', `MaleText_loc7`='¡Deja que un viejo orco te enseñe cómo se hace!' WHERE `ID`=40857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제자리로 가게. 헬스크림 님의 긍지를 지키게.', `MaleText_loc4`='兽人们，记住自己的荣耀。我们要让地狱咆哮为我们感到自豪。', `MaleText_loc5`='立正，獸人們。讓我們使地獄吼為我們感到驕傲。', `MaleText_loc7`='Sigan con lo suyo, orcos. Hagan que Grito Infernal se sienta orgulloso.' WHERE `ID`=40858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구역은 괜찮아 보이는군. 계속 잘해보게.', `MaleText_loc4`='这地方看上去很不错，兽人们。继续努力。', `MaleText_loc5`='這個地區看起來不錯，獸人。再接再厲。', `MaleText_loc7`='Esta zona tiene buen aspecto, orcos. Sigan con su excelente trabajo.' WHERE `ID`=40859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 내가 그림 바톨 전투에서 내게 달려든 드워프 얘기를 했던가?', `MaleText_loc4`='喂，我有没有告诉过你，我在格瑞姆巴托的战斗中差点儿被矮人杀死的事？', `MaleText_loc5`='嗯...我有跟你提過那個在格瑞姆巴托之戰想殺了我的那個矮人嗎?', `MaleText_loc7`='Oíd, ¿alguna vez os he hablado de la vez en que un enano intentó matarme en la batalla de Grim Batol?' WHERE `ID`=40860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 내 뒤통수에 칼을 꽂으려 했지. 다행스럽게도, 난 십 리 밖에서도 드워프 냄새를 맡을 수가 있단 말이야... 게다가 내 두개골은 다른 오크보다 단단하거든.', `MaleText_loc4`='他想要偷偷溜到我背后，把刀刃插进我的脑壳里。可幸运的是，我在一里外就能闻到矮人的气味……而且我的脑壳比普通人要厚得多。', `MaleText_loc5`='他想要偷偷從我背後把他的劍插在我的頭上。運氣好的是，我可以在幾英哩外就認出矮人的味道...而我的頭骨也比一般人還要硬。', `MaleText_loc7`='Intentó sorprenderme por la espalda y clavarme su hoja en el cráneo. Afortunadamente, puedo oler a un enano a kilómetros de distancia... y mi cráneo es más duro que el de la mayoría.' WHERE `ID`=40861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그 일이 있고 나서 두개골을 보호하려고 머리를 더 길렀지.', `MaleText_loc4`='当然，在那时候，我头上还有好多头发做保护。', `MaleText_loc5`='當然，我以前本來有很多毛髮可以保護它。', `MaleText_loc7`='Claro que, en aquella época, tenía mucho más pelo para protegerlo.' WHERE `ID`=40862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 난 돌아서서 그놈의 칼, 목숨, 탈것을 빼앗았지.', `MaleText_loc4`='我去那里转了一圈，拿回了他的剑，他的头，还有他的坐骑。', `MaleText_loc5`='反正，我轉了過來，拿了他的刀，他的命，他的頭，還有他的坐騎。', `MaleText_loc7`='Sea como sea, yo me di la vuelta y tomé su hoja, su vida, su cabeza y su montura.' WHERE `ID`=40863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁에 나가고 싶나, 제군들?', `MaleText_loc4`='你们这些兽人曾经梦想过战争吗？', `MaleText_loc5`='你們獸人會夢到打仗嗎?', `MaleText_loc7`='¿Los orcos nunca soñáis con la batalla?' WHERE `ID`=40864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵, 총감독관님.', `MaleText_loc4`='是的长官。', `MaleText_loc5`='是，長官。', `MaleText_loc7`='Sí, señor.', `FemaleText_loc1`='넵, 총감독관님.', `FemaleText_loc4`='是的长官。', `FemaleText_loc5`='是，長官。', `FemaleText_loc7`='Sí, señor.' WHERE `ID`=40865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무척 나가고 싶습니다, 총감독관님.', `MaleText_loc4`='简直是渴望，长官。', `MaleText_loc5`='很常，長官。', `MaleText_loc7`='Ya lo creo, señor.', `FemaleText_loc1`='무척 나가고 싶습니다, 총감독관님.', `FemaleText_loc4`='简直是渴望，长官。', `FemaleText_loc5`='很常，長官。', `FemaleText_loc7`='Ya lo creo, señor.' WHERE `ID`=40866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 좋다! 어쩌면 가로쉬 님께 자넬 추천해 드릴 수도 있겠지. 자, 돌아가서 일해라! 록타르 오가르!', `MaleText_loc4`='哈哈！很好！也许我会把你们的名字推荐给加尔鲁什。现在快去干活儿！Lok''tar ogar！', `MaleText_loc5`='哈哈!太棒了!或許我會把你的名字推薦上去，讓卡爾洛斯知道。至於現在，返回你的工作崗位!(獸人語)不勝即亡!', `MaleText_loc7`='¡Ja, ja! ¡Excelente! ¡Quizá me encargue de que os recomienden a Garrosh! ¡Ahora, volved al trabajo! ¡Lok''tar ogar!' WHERE `ID`=40867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관! 어떻게 된 건가?', `MaleText_loc4`='监工！这儿发生什么事了？', `MaleText_loc5`='監督!這到底是怎麼回事?', `MaleText_loc7`='¡SOBRESTANTE! ¿Qué ocurre aquí?' WHERE `ID`=40868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃에 휩싸여라!', `MaleText_loc4`='被烈焰吞没吧！', `MaleText_loc5`='沐浴在火焰中吧!', `MaleText_loc7`='¡BÁÑENSE EN LLAMAS!' WHERE `ID`=40869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넘실대는 불길이 널 삼키리라!', `MaleText_loc4`='在烈焰之流中燃烧！', `MaleText_loc5`='在液態火焰中燃燒吧!', `MaleText_loc7`='¡ARDAN EN FUEGO LÍQUIDO!' WHERE `ID`=40870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지난번에 확인했을 때, 자네 칭호는 감독관이었지 식충이가 아니었는데.', `MaleText_loc4`='上次我来的时候，你的头衔是监工，可不是暴食者。', `MaleText_loc5`='我記得你的頭銜是監督者，不是貪吃者。', `MaleText_loc7`='La última vez que lo comprobé, tenías el título de sobrestante, no de comedor compulsivo.' WHERE `ID`=40871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 두 번째 여길 지나가는데, 자넨 두 번 다 불 옆에 앉아서 다른 사람들이 일하는 동안 게으름을 피웠어.', `MaleText_loc4`='我已经经过这里两次了，两次都看到你坐在火堆边上，在手下干活的时候无所事事。', `MaleText_loc5`='我走過這裡已經兩次了，兩次都看到你坐在火旁邊偷懶，而你的人卻在工作。', `MaleText_loc7`='He venido aquí dos veces, y en las dos ocasiones te he encontrado sentado aquí al lado del fuego, haciendo el vago mientras los demás hombres trabajan a tu alrededor.' WHERE `ID`=40872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총감독관님, 저... 동료들이 일을 워낙 잘해서요. 그러니까 저는... 생각하길...', `MaleText_loc4`='长官，我……我的兽人们干得很好，所以我只是……认为我……', `MaleText_loc5`='長官，我...我的獸人工作的不錯，所以我...我才想說...', `MaleText_loc7`='Señor, yo... Mis orcos estaban trabajando tan bien que yo... bueno... pensé...', `FemaleText_loc1`='총감독관님, 저... 동료들이 일을 워낙 잘해서요. 그러니까 저는... 생각하길...', `FemaleText_loc4`='长官，我……我的兽人们干得很好，所以我只是……认为我……', `FemaleText_loc5`='長官，我...我的獸人工作的不錯，所以我...我才想說...', `FemaleText_loc7`='Señor, yo... Mis orcos estaban trabajando tan bien que yo... bueno... pensé...' WHERE `ID`=40873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기 더미 속에 붕대가 섞여 있네. 음식물이 태양빛에 노출되어 있고 말이야. 내가 자네에게 햇빛 가릴 천막을 지급한 게 똑똑히 기억나는데.', `MaleText_loc4`='我看到绷带像武器一样堆在一边。我看到食物就这么暴晒在太阳底下，尽管我显然已经为你们提供了用于遮阳的帐篷。', `MaleText_loc5`='我看到繃帶和武器堆在一起。我看到食物被丟在大太陽下任憑腐壞。而且我明明就給了你帳篷好遮擋陽光。', `MaleText_loc7`='Veo que las vendas están almacenadas en las mismas pilas que las armas. Veo que la comida se pudre al sol cuando ESTÁ CLARO que te proveí de tiendas de campaña que tuvierais sombra.' WHERE `ID`=40874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 자들을 감독하는 게 누구인가?', `MaleText_loc4`='谁是这些人的监工？', `MaleText_loc5`='誰是這些人的監督?', `MaleText_loc7`='¿Quién supervisa a estos hombres?' WHERE `ID`=40875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 접니다, 총감독관님.', `MaleText_loc4`='我……我是，长官。', `MaleText_loc5`='是...是我，長官。', `MaleText_loc7`='Eh, yo... señor.', `FemaleText_loc1`='저... 접니다, 총감독관님.', `FemaleText_loc4`='我……我是，长官。', `FemaleText_loc5`='是...是我，長官。', `FemaleText_loc7`='Eh, yo... señor.' WHERE `ID`=40876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게 멀쩡한지 확인하게. 업무에 복귀하라고, 감독관.', `MaleText_loc4`='那就让我们确保让它保持原状。回去工作吧，监工。', `MaleText_loc5`='讓我們確定這會維持下去。回去工作，監督者。', `MaleText_loc7`='Entonces asegurémonos de que es así. Vuelve al trabajo, sobrestante.' WHERE `ID`=40877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르, 신, 오두막 안에서 허송세월하지 말고 나가서 다른 오크들처럼 일하게!', `MaleText_loc4`='戈尔、希恩，你们真不该一天到晚待在这间小屋里。赶快出去和那些兽人一起干活！', `MaleText_loc5`='葛爾和辛，你們不應該把全部時間都花在這個小屋內。快出去和獸人一起工作去!', `MaleText_loc7`='Gor, Shin, no deberíais pasar todo el tiempo metidos en esta cabaña. ¡Salid de aquí y poneos a trabajar con los orcos!' WHERE `ID`=40878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 사실 자네 같은 주술사는 뭘 하든 신경 안 쓰네. 헬스크림 님이 자네를 왜 여기 데려다 놓았는지 모르겠단 말이야.', `MaleText_loc4`='的确，萨满，我并不真的很在意你在做什么。我甚至不明白地狱咆哮为什么要把你带到这里来。', `MaleText_loc5`='其實呢，薩滿，我不在乎你要做什麼。我甚至不確定地獄吼為什麼要帶你過來這裡。', `MaleText_loc7`='De hecho, chamán, no me importa nada lo que hagas. Ni siquiera sé por qué Grito Infernal te trajo aquí.' WHERE `ID`=40879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르, 자네가 새파란 신병이라고 생각하나? 그게 아니라면 나가서 한 번이라도 나와 같이 부대를 지휘해야 하지 않겠나?', `MaleText_loc4`='戈尔，当你感觉自己不再年轻时，为什么不和我到外边来，开始管制那些兽人一次呢？', `MaleText_loc5`='葛爾，你感覺越來越不像個孩子了，你就不能跟我一起出來開始做些什麼嗎?', `MaleText_loc7`='Gor, cuando empieces a sentirte un poco menos como un jovenzuelo, ¿por qué no sales aquí conmigo y empiezas a hacerte respetar para variar?' WHERE `ID`=40880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 농부, 이리 나오게. 할 얘기가 있네.', `MaleText_loc4`='农夫，到外面来。我们必须谈一谈。', `MaleText_loc5`='農夫，出來。我們必須談談。', `MaleText_loc7`='Granjero, sal. Debemos hablar.' WHERE `ID`=40881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 돼지들은 너무 약하군. 번식용으로 쓰기에도, 먹기에도 별로인 데다 싸움도 못 해.', `MaleText_loc4`='这些猪，它们太虚弱了。既不适合用来繁育，也不适合拿来食用，上战场当然更不行。', `MaleText_loc5`='這些豬，它們太弱了。它們不適合拿來繁殖，不適合做為食物，更不適合用來戰鬥。', `MaleText_loc7`='Estos puercos son débiles. No son buenos para cría, no son buenos para comer y desde luego, no lo son para luchar.' WHERE `ID`=40882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 더 까다롭게 돼지를 길러야겠네. 호드는 약한 놈에겐 자리를 주지 않아. 심지어 돼지우리라도 말이지.', `MaleText_loc4`='你的繁育要更具选择性一些。部落容不下弱者，即使是在猪圈里。', `MaleText_loc5`='你在繁殖上應該要更加挑剔才可以。部落是不接受弱者的，就連豬舍裡的都不行。', `MaleText_loc7`='Tienes que ser más selectivo en tus procesos de cría. La Horda no tiene espacio para debiluchos, ni siquiera en sus corrales de puercos.' WHERE `ID`=40883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 내가 이 짓을 또다시 하고 싶진 않군. 돼지치기, 자네가 하게.', `MaleText_loc4`='好吧。这样的事情我不想再做第二次。那是你的工作，猪倌。', `MaleText_loc5`='嗯。我不想再做一次了。這是你的工作，豬倌。', `MaleText_loc7`='Ahí tienes. No querría tener que hacer esto de nuevo, esto es tu trabajo, porquero.' WHERE `ID`=40884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼애애애애!!!!', `FemaleText_loc4`='不——！！！', `FemaleText_loc5`='不～～～～!!!', `FemaleText_loc7`='¡¡Nooooo!!' WHERE `ID`=40885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 쏘았소! 저격포는 정말 놀라운 기적의 발명품이오!', `MaleText_loc4`='射得漂亮！狙击炮可真是个神奇的玩意儿！', `MaleText_loc5`='射得好!狙擊火砲的存在真是一個奇蹟!', `MaleText_loc7`='¡Buen disparo! ¡Este cañón de francotirador es una maravilla milagrosa!' WHERE `ID`=40886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스의 자손을 없애라! 세나리우스를 도와야 해!', `MaleText_loc4`='击败拉格纳罗斯之子，我才能协助塞纳留斯！', `MaleText_loc5`='擊敗這些拉格納羅斯之子，讓我可以協助塞納留斯!', `MaleText_loc7`='¡Vence a los hijos de Ragnaros así puedo asistir a Cenarius!' WHERE `ID`=40887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 공격받고 있네! 날 도와주게!', `MaleText_loc4`='我正受到攻击！帮我！', `MaleText_loc5`='我受到攻擊了!協助我!', `MaleText_loc7`='¡Estoy bajo asalto! ¡Ayúdenme!' WHERE `ID`=40888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 라그나로스에게 공격당하고 있습니다. 치유하십시오!', `MaleText_loc4`='%s正在遭受拉格纳罗斯的攻击。快治疗他！', `MaleText_loc5`='%s正被拉格納羅斯攻擊。治療他!', `MaleText_loc7`='Ragnaros ataca a %s. ¡Sánale!' WHERE `ID`=40889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스의 공격을 당해내기 힘들구나... 날 치료하라!', `MaleText_loc4`='拉格纳罗斯的攻击削弱了我的战斗力……快治疗我！', `MaleText_loc5`='拉格納羅斯的襲擊削弱了我的力量...治療我!', `MaleText_loc7`='El ataque de Ragnaros me ha dejado al límite de mis fuerzas... ¡Cúrame!' WHERE `ID`=40890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘을 더럽히려는 놈들에게 교훈이 되길.', `MaleText_loc4`='这是你们玷污海加尔圣山的代价。', `MaleText_loc5`='這會讓想褻瀆海加爾的人引以為戒。', `MaleText_loc7`='Que esto sea una lección para quienes desecran Hyjal.' WHERE `ID`=40891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 분노가 무엇인지 아느냐!', `MaleText_loc4`='你对狂怒一无所知，虫子！', `MaleText_loc5`='你不懂什麼叫怒火，蟲子!', `MaleText_loc7`='¿Qué sabes tú de furia, gusano?' WHERE `ID`=40892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 $R|1이로구나;로구나;! 죽어라!', `MaleText_loc4`='弱小的$R！死吧！', `MaleText_loc5`='$R鼠輩!死吧!', `MaleText_loc7`='¡$R ENCLENQUE! ¡MUERE!' WHERE `ID`=40893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 님의 분노를 느껴봐라!', `MaleText_loc4`='感受拉格纳罗斯的愤怒吧！', `MaleText_loc5`='感受拉格納羅斯的怒火!', `MaleText_loc7`='¡Siente la furia de Ragnaros!' WHERE `ID`=40894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 열기. 숨이 막힐 것 같네.$B$B다른 것들을 해치고 싶은 기분이야.', `FemaleText_loc4`='这热浪。这令人窒息的热浪。$B$B令我想要靠破坏来发泄。', `FemaleText_loc5`='這個熱度。這個緊繃的熱度。$B$B這讓我想傷害什麼。', `FemaleText_loc7`='Este calor. Este calor insoportable.$B$BMe da ganas de machacar cosas.' WHERE `ID`=40895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 간다! 나무 뒤에 숨을 생각은 마라!', `MaleText_loc4`='我来了！别以为躲在那些树后面就没事了！', `MaleText_loc5`='我來了!你有種躲在那些樹後試試看!', `MaleText_loc7`='¡Ya vengo! ¡No te atrevas a esconderte detrás de esos árboles!' WHERE `ID`=40896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 저편에서 새로운 분이 오셨군요! 싸울 준비는 단단히 하고 오셨길 바랍니다, $c님.', `MaleText_loc4`='从传送门那边又有人过来了！希望你已经做好了战斗的准备，$c。', `MaleText_loc5`='從傳送門出來的另一人!準備好進行戰鬥了，$C。', `MaleText_loc7`='¡Alguien más del otro lado del portal! Espero que estés $gpreparado:preparada; para luchar, $c.' WHERE `ID`=40897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 적진 안쪽에 있습니다, $n 님. 놈들에게 최대한 큰 피해를 주어야 합니다!', `MaleText_loc4`='我们现在已经深入敌后了，$n。我们要尽可能地对敌人制造伤害！', `MaleText_loc5`='我們在敵人的後方，$n。我們必須盡可能地造成損害!', `MaleText_loc7`='Estamos tras las líneas enemigas, $n. ¡Tenemos que hacer todo el daño que podamos!' WHERE `ID`=40898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 이런 차원문을 아제로스 전 지역에 열게 놔둔다면, 제 아무리 강력한 군대도 이 세계를 구할 수 없을 겁니다. 이 차원문 연결망을 끊어야 합니다!', `MaleText_loc4`='要是我们任由暮光之锤在艾泽拉斯各地打开像这样的传送门，那这世上就没有任何军团能挽救这个星球。我们必须一举解决这个坑道网！', `MaleText_loc5`='如果我們讓暮光之錘像這樣在艾澤拉斯到處開啟傳送門，沒有任何軍隊有能力拯救這個世界。我們必須封印這個傳送網絡!', `MaleText_loc7`='Si permitimos al Martillo Crepuscular abrir portales como este por todo Azeroth, no habrá ejército en el mundo que pueda salvar el planeta. ¡Tenemos que cerrar esa red de túneles!' WHERE `ID`=40899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 인내심을 가져야 합니다, $n 님. 제가 존경하는 늑대 고대정령께 그렇게 배웠습니다.$B$B무슨 일이 있어도 절대로, 절대로 포기해선 안 됩니다.', `MaleText_loc4`='我们必须坚持，$n。我从我们敬爱的狼神先祖身上学到了一样东西。$B$B那就是永远、永远、永远都不要放弃。', `MaleText_loc5`='我們必須撐下去，$n。那是我和摯愛的狼先祖所學到的。$B$B永遠都不要放棄，永遠都不要。', `MaleText_loc7`='Debemos perseverar, $n. Eso es algo que aprendí de nuestro amado ancestro lobo.$B$BNunca, nunca, nunca te rindas.' WHERE `ID`=40900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피렌디우스가 죽었습니다! 이제 여기서 우리가 할 일은 다 했습니다.$B$B이 화염관문을 통해 하이잘 산으로 돌아가십시오, $c님. 제는 이 관문을 처리하고 따라가겠습니다.', `MaleText_loc4`='派伦迪乌斯倒下了！我们在这儿的工作完成了。$B$B现在只要穿过火焰之门就能返回海加尔山了，$c。我会确保看好大门的。', `MaleText_loc5`='已經殺了裴迪爾斯，我們在這的工作結束了。$B$B踏入火焰門便可回到海加爾山。剩下的就都交給我吧。', `MaleText_loc7`='¡Pyrendius ha muerto! Nuestro trabajo ha concluido.$b$bAtraviesa la puerta de llamas para volver al Monte Hyjal, $c. Yo me aseguraré de que se cierra la puerta.' WHERE `ID`=40901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로고쉬의 송곳니를 잃어버렸습니다. 하나 더 받을 수 있습니까?', `MaleText_loc4`='我把洛戈什之牙弄丢了。可以再给我一个吗？', `MaleText_loc5`='我把我的洛戈許之牙弄丟了。我可以再要一個嗎?', `MaleText_loc7`='He perdido mi Colmillo de Lo''Gosh. ¿Puedo tener otro?', `FemaleText_loc1`='로고쉬의 송곳니를 잃어버렸어요. 하나 더 받을 수 있나요?', `FemaleText_loc4`='我把洛戈什之牙弄丢了。可以再给我一个吗？', `FemaleText_loc5`='我把我的洛戈許之牙弄丟了。我可以再要一個嗎?', `FemaleText_loc7`='He perdido mi Colmillo de Lo''Gosh. ¿Puedo tener otro?' WHERE `ID`=40902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드린의 송곳니를 잃어버렸습니다. 하나 더 받을 수 있습니까?', `MaleText_loc4`='我把戈德林之牙弄丢了。可以再给我一个吗？', `MaleText_loc5`='我把我的戈德林之牙弄丟了。我可以再要一個嗎?', `MaleText_loc7`='He perdido mi Colmillo de Goldrinn. ¿Puedo tener otro?', `FemaleText_loc1`='골드린의 송곳니를 잃어버렸어요. 하나 더 받을 수 있나요?', `FemaleText_loc4`='我把戈德林之牙弄丢了。可以再给我一个吗？', `FemaleText_loc5`='我把我的戈德林之牙弄丟了。我可以再要一個嗎?', `FemaleText_loc7`='He perdido mi Colmillo de Goldrinn. ¿Puedo tener otro?' WHERE `ID`=40903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='번개와 물은 섞일 수 없다는 걸 알게 될 것이다!', `FemaleText_loc4`='你很快就会知道，闪电与水是无法融合的！', `FemaleText_loc5`='你很快就會學到閃電和水是不能混在一起的!', `FemaleText_loc7`='¡Pronto aprenderás que el relámpago y el agua no se mezclan!' WHERE `ID`=40904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에.', `MaleText_loc4`='再见。', `MaleText_loc5`='再見。', `MaleText_loc7`='Más tarde.' WHERE `ID`=40905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 자애로우신 지도자이자 수호자, 엘레스타라 바쉬 님께 경의를 표하노라.$b$b그분은 100년 동안 온 힘을 다해 우리를 감싸시고, 보호하시고, 근대 번영의 시대로 우릴 이끄셨다.$b$b아즈샤라 여왕의 비호 아래, 그분의 치세가 백 년을 더 이어가리라.', `MaleText_loc4`='向我们仁慈的统治者与保护者——埃利斯塔拉·瓦丝琪主母致敬。$B$B一百年来，她诚心地庇护着我们，保护着我们，坚定地引领我们走入了繁荣的现代新纪元。$B$B在艾萨拉女王的注视下，愿她的统治能再延续百年。', `MaleText_loc5`='紀念我們仁慈的統治者和保護者，艾勒史塔拉·瓦許女士。$B$B在這100年中，他忠誠地庇護我們，保護我們，以及帶領我們逐漸發展成繁榮的現代社會。$B$B希望在艾薩拉女王的凝視下，瓦許女士能再統治100年。', `MaleText_loc7`='En honor a nuestra benevolente gobernadora y protectora, Matrona Elestara Vashj.$B$BDurante 100 años hemos vivido a su abrigo, nos ha protegido y nos ha guiado constantemente hacia una nueva era de prosperidad.$B$BBajo la mirada de la reina Azshara, ojalá reine 100 años más.' WHERE `ID`=40906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 겁쟁이 놈이 감히 나 없는 동안 내 자식을 공격하는가? 네놈을 산 채로 내 자식들에게 먹이겠다!', `MaleText_loc4`='什么懦夫竟敢在我不在时攻击我的孩子？我要把你的内脏挖出来喂它们吃！', `MaleText_loc5`='什麼樣的膽小鬼敢趁我不在攻擊我的孩子?我會把你的內臟拿去餵我的孩子們!', `MaleText_loc7`='¿Qué cobarde se atreve a atacar a mis hijos mientras estoy fuera? ¡Alimentaré a mi prole con tus entrañas!' WHERE `ID`=40907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 함께 죽을 힘을 다해 싸워야 했지만, 어쨌든 라그나로스를 불의 땅으로 몰아냈군.', `MaleText_loc4`='这耗尽了我们集结起来的所有力量，不过我们终于把拉格纳罗斯赶回了火焰之地。', `MaleText_loc5`='我們用上了每一分力量，但至少成功把拉格納羅斯逼回火源之界了。', `MaleText_loc7`='Hizo falta toda nuestra fuerza combinada, pero Ragnaros volvió a las Tierras de Fuego.' WHERE `ID`=40908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유후!', `MaleText_loc4`='呜呼！', `MaleText_loc5`='呀呼!', `MaleText_loc7`='¡Yuuujuuuu!' WHERE `ID`=40909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 방심해선 안 됩니다. 놈이 다시 힘을 회복해 놀드랏실을 잿더미로 만드는 건 단지 시간문제일 뿐입니다.', `MaleText_loc4`='我们绝不能有丝毫的松懈。他迟早会重获力量并且卷土重来，将诺达希尔变成焦土。', `MaleText_loc5`='我們不能鬆懈。不久之後他的力量一定會回復，然後回來將諾達希爾夷為平地。', `MaleText_loc7`='No podemos bajar la guardia. Que recupere su fuerza y vuelva para convertir a Nordrassil en cenizas es sólo cuestión de tiempo.' WHERE `ID`=40910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드, 얼라이언스의 지도자들과 상의해야겠군요. 라그나로스의 영지 안에서 놈을 처치해야 합니다. 그래야만 라그나로스를 영원히 없앨 수 있으니까요.', `MaleText_loc4`='我们必须与联盟和部落的领袖谈一谈。一定要在拉格纳罗斯的老巢将其击败。那样，才能将他彻底征服。', `MaleText_loc5`='我們必須和部落及聯盟的首領們談談。必須在拉格納羅斯居住的世界擊敗他。只有這樣才能永遠消滅他。', `MaleText_loc7`='Debemos consultarlo con los líderes de la Horda y la Alianza. Ragnaros debe ser derrotado en su reino original. Sólo así será vencido para siempre.' WHERE `ID`=40911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단은 이곳을 떠나도록 하지. 하이잘로 돌아가 우리 적이 남긴 상처를 치유해야 하네.', `MaleText_loc4`='让我们先离开这里吧。我们必须返回海加尔去抚平敌人造成的创伤。', `MaleText_loc5`='讓我們先離開這裡吧。我們必須回到海加爾並修復敵人造成的創傷。', `MaleText_loc7`='Ahora vayámonos de aquí. Debemos volver a Hyjal y reparar el daño que causaron nuestros enemigos.' WHERE `ID`=40912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더는 하이잘의 바람을 더럽히지 못할 것이다, 이 괴물아!', `FemaleText_loc4`='怪物，你再也不能污染海加尔之风了！', `FemaleText_loc5`='我不會讓你再繼續褻瀆海加爾的風，怪物!', `FemaleText_loc7`='¡No desecrarás los vientos de Hyjal, monstruo!' WHERE `ID`=40913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타에라 님께서 경이로움을 보여주실 거다!', `MaleText_loc4`='主人泰拉尔将让你见证奇迹！', `MaleText_loc5`='你們將會看到泰拉爾主人的魔力!', `MaleText_loc7`='¡El maestro Taerar te enseñará semejantes maravillas...!' WHERE `ID`=40914;
