UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n... 님 저기 있는 게... 맞습니까? 호드가 저걸 터뜨리면 이 땅도 끝입니다.', `FemaleText_loc4`='是……是那边那个吗，$n？要是部落成功把它点着了，这座岛屿就将彻底毁灭。', `FemaleText_loc5`='那...那邊就這樣了嗎，$n?如果部落的計畫成功，這個島就完蛋了。', `FemaleText_loc7`='¿Es... es eso de ahí, $n? Esta tierra está condenada si la Horda se las arregla para activarlo.' WHERE `ID`=40919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭡니까? 공성 전차용 구급 상자? 그렇다면 조종사 스톤기어를 알겠군요!', `MaleText_loc4`='那是什么，攻城坦克急救工具？你一定认识驾驶员迪恩·石轮！', `MaleText_loc5`='那是什麼，一個攻城坦克急救箱?你一定認識駕駛員迪恩·石輪!', `MaleText_loc7`='¿Qué es eso? ¿Un botiquín de primeros auxilios para tanques de asedio? ¡Tienes que conocer al piloto Roscapiedra!' WHERE `ID`=40920;
