UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아비아나의 마법이 사라지기 전에 어서 처치하라!', `MaleText_loc4`='艾维娜的魔法还未褪去，现在就杀了她！', `MaleText_loc5`='在艾維娜的魔法消失前，趕快殺了她!', `MaleText_loc7`='¡Mátenla ya, mientras dure la magia de Aviana!' WHERE `ID`=40923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모습을 드러내라! 숨어도 소용없다. 반드시 너와 네 부정한 새끼들을 없애 버리겠다!', `MaleText_loc4`='出来吧，畜牲！不管你藏在哪儿，我们都会把你和你那些堕落的余孽一起铲除掉！', `MaleText_loc5`='現身吧，怪物!我們會消滅你和你腐敗的爪牙，不管你們躲在哪裡!', `MaleText_loc7`='¡Muéstrate, bestia! ¡Tu engendro y tú serán destruidos, sin importar dónde se oculten!' WHERE `ID`=40924;
