UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 보주를 안전하게 보관하기 위해... 잡고 있겠다. 가서 이교도들의 문제를 로크 올한에게 알려줘라.', `MaleText_loc4`='为了安全起见……我要留下这个宝珠。快去把这档子邪教徒的麻烦事告诉给洛卡·奥赫。', `MaleText_loc5`='我會暫時先...保管這個礦石。通知洛卡·奧赫有關教徒的問題。', `MaleText_loc7`='Voy a quedarme este orbe para... mantenerlo seguro. Ve a informar a Rok Orhan de nuestro problema con los cultores.' WHERE `ID`=40928;
