UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 나만 큰 바위 옮기나? 대족장이 새로 오면 일 덜 한다고 들었다! 바뀐다고 약속했다!', `MaleText_loc4`='为什么我非要搬大石头？他们说新酋长继任后工作量会减少的！他们保证会有所变化的！', `MaleText_loc5`='為什麼我要搬大石頭?他們說有新大酋長就不用那麼辛苦!他們答應會有改變!', `MaleText_loc7`='¿Por qué yo tener que cargar con gran roca? ¡Ellos decir que tener menos trabajo con este Jefe de guerra! ¡Ellos prometer cambio!' WHERE `ID`=40932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 나 이 바위 내려놓고 안녕 인사한다. 어쩌면.', `MaleText_loc4`='也许我该放下这块石头说声你好。也许。', `MaleText_loc5`='或許我可以把這塊岩石放下後打個招呼。或許。', `MaleText_loc7`='Quizá yo dejar caer esta roca e ir a saludar. Quizá.' WHERE `ID`=40933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 팔로 큰 바위 안고 아무것도 안 보이는 채로 껌껌한 동굴에서 걷는다. 그래도 그전에 했던 일보다 낫다.', `MaleText_loc4`='瞎子摸黑一样地走在黑漆漆的矿井里，手里还抱着大石头。真比上一份工作好多了。', `MaleText_loc5`='在黑暗中扛著大岩石走。比上份工作好多了。', `MaleText_loc7`='Caminar a ciegas por mina oscura con gran roca en brazos. Ser mucho mejor que el otro trabajo.' WHERE `ID`=40934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜나지 않으면 네가 양동이에 똥쌌다고 감독관한테 이른다!', `MaleText_loc4`='快走，不然我就去告诉监工，说你在桶里拉屎！', `MaleText_loc5`='不走我就跟監督說你在桶子裡拉屎!', `MaleText_loc7`='¡Tú mover o yo decir al sobrestante que hacerte caca en ese cubo!' WHERE `ID`=40935;
