UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 그대가 늑대인간으로 변하는 기록을 상영하던 곳이오! 또 우리는 현재로 건너뛰었소!', `MaleText_loc4`='我们在此为你演示你变身成为狼人的影像！我们同时还将镜头快速前移到当前！', `MaleText_loc5`='這裡是我們播放你成為狼人的影片的地方!我們還把它快速播放到現在的時間點!', `MaleText_loc7`='¡Aquí habrá una escena en la que te conviertes en huargen! ¡Y viajamos al presente!' WHERE `ID`=40945;
