UPDATE `locales_broadcast_text` SET `MaleText_loc1`='***귀환 명령 작동***', `MaleText_loc4`='***返回命令初始化***', `MaleText_loc5`='***已啟動返回指令***', `MaleText_loc7`='***EJECUTANDO ORDEN***' WHERE `ID`=40954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='***허가받지 않은 모든 승객 방출***', `MaleText_loc4`='***逐出全部未经许可的通行者***', `MaleText_loc5`='***彈射出所有未授權的乘客***', `MaleText_loc7`='***EYECTANDO A TODOS LOS PASAJEROS NO AUTORIZADOS***' WHERE `ID`=40955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<이세라의 몸은 당신의 눈앞에 있지만, 그녀의 의식은 이 세상과 다른 세상을 오가는 것 같습니다.>', `FemaleText_loc4`='<尽管伊瑟拉的肉身就站在你面前，可她的意识却仿佛在两个世界间游移。>', `FemaleText_loc5`='<雖然伊瑟拉的實體站在你的面前，但她的意識看起來似乎遊走於這個世界和另一個世界之間。>', `FemaleText_loc7`='<Aunque tienes delante de ti el cuerpo físico de Ysera, su consciencia parece alternar entre este mundo y el otro.>' WHERE `ID`=40956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근 잿빛 골짜기에 가보신 적 있으십니까? 어떻던가요?', `FemaleText_loc4`='你最近去过灰谷吗？那里情况怎么样？', `FemaleText_loc5`='你最近有去梣谷嗎?那邊怎麼樣?', `FemaleText_loc7`='¿Has estado en Vallefresno últimamente? ¿Qué tal van las cosas?' WHERE `ID`=40957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 형제들이여! 이 죄수는 진정한 황혼의 후예가 차지해야 옳습니다! 오우거 쓰레기들이 이자를 제물로 바치다니, 당치 않습니다! 그들은 고대 신의 은총을 받을 자격이 없습니다!', `MaleText_loc4`='是的，同胞！我们为真正的暮光之子带走这名囚犯！这些食人魔渣滓不配拿他来献祭！他们不够资格获得上古之神的眷顾！', `MaleText_loc5`='是的，兄弟們!我們要為真正的暮光之子取得這個囚犯!這些巨魔不適合獻祭他!他們不夠資格獲得上古之神的眷顧!', `MaleText_loc7`='¡Sí, hermanos! ¡Los Verdaderos Hijos del Crepúsculo reclaman este prisionero! ¡Los ogros no sabrán ofrecerlo como sacrificio! ¡No son dignos de los Dioses Antiguos!' WHERE `ID`=40958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오십시오, 사령관님. 여기서 나갑시다. 소단 관문으로 오세요. 이세라 님께서 기다리십니다!', `MaleText_loc4`='快点，指挥官。我们要把你带出去。$n，我们在索萨恩之门碰头——伊瑟拉正在那儿等着。', `MaleText_loc5`='來吧指揮官。我們護送你離開。$n，我們在索桑恩之門碰面--伊瑟拉等著我們!', `MaleText_loc7`='Vamos, comandante. Salgamos de aquí. Nos vemos en las Puertas de Sothann... ¡Ysera nos espera!' WHERE `ID`=40959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 정신을 집중하여 초신성을 시전합니다. 시선을 돌리십시오!', `FemaleText_loc4`='%s开始施放超级新星。转过头去！', `FemaleText_loc5`='%s開始引導超級新星。看向別處!', `FemaleText_loc7`='%s empieza a canalizar Supernova. ¡No mires!' WHERE `ID`=40960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 우린 아직 여러 위협에 시달리고 있네. 야영지를 방어하지 않은 상태로 둘 순 없네.', `MaleText_loc4`='我们四周仍然危机重重。我不能毫无戒备地离开这座营地。', `MaleText_loc5`='我們週遭還是有威脅。我不能讓這個營地毫無防衛能力。', `MaleText_loc7`='Aquí todavía estamos en peligro. No dejaré el campamento sin protección.' WHERE `ID`=40961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 살아온 자들을 보호하는 게 내가 할 수 있는 일의 전부라네.', `MaleText_loc4`='我已经尽全力去保护那些坚持走到这里的人。', `MaleText_loc5`='我能做的就是保護那些來到這裡的人。', `MaleText_loc7`='Es todo lo que puedo hacer para proteger a los que han llegado hasta aquí.' WHERE `ID`=40962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 보낼 수 있는 전사들은 모두 보냈네. 자네를 위해 한 명만 더 있었더라면...', `MaleText_loc4`='我已经派出所有可以调遣的战士。要是我能再为你派出哪怕一个人……', `MaleText_loc5`='我已經派出所有的戰士了。如果我還有個後備的戰士就好了...', `MaleText_loc7`='He enviado a todos los guerreros que he podido. Si tuviera alguno más para ti...' WHERE `ID`=40963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조운, 두 지역을 방어하지 않은 채로 놔두는 일은 더 큰 고통을 가져올 걸세.', `MaleText_loc4`='让我们自己在两边都不设戒备，将会带来更大的灾难，加恩。', `MaleText_loc5`='加恩，如果我們兩邊都沒有做出防衛，我們的損失會更大。', `MaleText_loc7`='Si quedamos sin protección por ambos lados, provocaremos aún más sufrimiento, Jawn.' WHERE `ID`=40964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피난민들을 보호하려면 이곳의 경비를 유지해야 하네.', `MaleText_loc4`='我们必须让守卫留在这里以保护难民。', `MaleText_loc5`='我們必須讓守衛待在這來保護難民。', `MaleText_loc7`='Debemos mantener aquí a los guardias para que protejan a los refugiados.' WHERE `ID`=40965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림토템 부족이 페랄라스로 숨어들었네. 이 야영지를 공격할 기회를 잡으려 하고 있단 말일세.', `MaleText_loc4`='恐怖图腾也潜伏在菲拉斯。他们在等待时机，对眼前这座营地发起攻击。', `MaleText_loc5`='恐怖圖騰也藏匿在菲拉斯。他們等待著襲擊這個營地的機會。', `MaleText_loc7`='Los Tótem Siniestro también merodean por Feralas. Esperan la oportunidad para atacar este campamento.' WHERE `ID`=40966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 좋은 보물이다.', `MaleText_loc4`='嗯，好多财宝。', `MaleText_loc5`='嗯...不錯的寶物。', `MaleText_loc7`='Mmm, buen tesoro.' WHERE `ID`=40967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빛의 봉화에 의해 보호되고 있습니다! 지렛대를 아래로 당겨 봉화를 끄십시오!', `MaleText_loc4`='%s受到了防御信标的保护！快拉下面的操纵杆，让防御信标停下！', `MaleText_loc5`='%s被他的光明之塔保護著!把下面的手桿拉下來關閉它們!', `MaleText_loc7`='¡%s se protege con sus señales de defensa! ¡Inutilízalas manipulando las palancas de abajo!' WHERE `ID`=40968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독과 싸우고 싶어? 보물 많이 줘. 난 이만 가볼께!', `MaleText_loc4`='想要跟将军打架？财宝可真多啊。算我一个！', `MaleText_loc5`='要跟上將對打嗎?有很多寶物，算我一份!', `MaleText_loc7`='¿Tú querer luchar contra almirante? ¡Muchos tesoros! ¡Yo irme!' WHERE `ID`=40969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움 싫어. 돈 줘.', `MaleText_loc4`='不想找麻烦。只想要钱。', `MaleText_loc5`='不要問題。要金幣。', `MaleText_loc7`='No querer problemas. Querer oro.' WHERE `ID`=40970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 많은 금이다. 나 이제 못 본 척해줄게.', `MaleText_loc4`='好多金币啊！我扭过头去。', `MaleText_loc5`='這是很多金幣!我看另外一邊。', `MaleText_loc7`='¡Esto ser mucho oro! Yo mirar para otro lado.' WHERE `ID`=40971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍엄니는 절대 내게 보물을 주지 않는다!', `MaleText_loc4`='双牙从来不给我财宝！', `MaleText_loc5`='雙牙從不給我寶物!', `MaleText_loc7`='¡Dos Colmillos nunca darme tesoro!' WHERE `ID`=40972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 보물 숨기고 쉬러 간다.', `MaleText_loc4`='我藏好宝贝。继续休息。', `MaleText_loc5`='我藏寶物。離開一下。', `MaleText_loc7`='Yo esconder tesoros. Tomar un descanso.' WHERE `ID`=40973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이는 거 많다. 제독보단 네가 더 좋은 것 같다.', `MaleText_loc4`='好多金灿灿的宝贝。也许你比将军更让我喜欢。', `MaleText_loc5`='好多亮晶晶的玩意。我可以喜歡你多過上將。', `MaleText_loc7`='Muchos brillos. Quizá tú gustarme más que almirante.' WHERE `ID`=40974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, $r 쓰레기치곤 나쁘지 않다.', `MaleText_loc4`='对愚蠢的$r来说，你还算不错。', `MaleText_loc5`='以$r廢渣來說你還不錯。', `MaleText_loc7`='Tú no estar mal para ser escoria $r.' WHERE `ID`=40975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 일어나!', `FemaleText_loc4`='醒醒，水泡先生！', `FemaleText_loc5`='醒醒，P先生!', `FemaleText_loc7`='¡Despierta, Sr. P!' WHERE `ID`=40976;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='착한 딸은 아빠 말 잘 들어!', `FemaleText_loc4`='所有好女孩都听爸爸的话！', `FemaleText_loc5`='好女孩都會聽爸爸的話!', `FemaleText_loc7`='¡Todas las niñas buenas hacen caso a sus papás!' WHERE `ID`=40977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런! 열쇠가 자물쇠 안에서 부러졌어! 이제 평생 우리 밖으로 나가지 못할 거야!', `MaleText_loc4`='喔不！钥匙断在锁眼里了！我永远也别想离开这笼子了！', `MaleText_loc5`='噢不!鑰匙斷在鑰匙孔裡了!我永遠不可能從這籠子中出去了!', `MaleText_loc7`='¡Oh, no! La llave se ha roto en la cerradura! ¡Nunca lograré salir de esta jaula!' WHERE `ID`=40978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 듣고 있어?', `FemaleText_loc4`='你在吗，水泡先生？', `FemaleText_loc5`='你在嗎，P先生?', `FemaleText_loc7`='¿Estás ahí, Sr. P?' WHERE `ID`=40979;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 일어나! 영혼들을 구해야지!', `FemaleText_loc4`='快醒醒，水泡先生！快救救那些灵魂！', `FemaleText_loc5`='醒醒，P先生!你必須救救那些靈魂!', `FemaleText_loc7`='¡Despierta, Sr. P! ¡Tienes que salvar a los espíritus!' WHERE `ID`=40980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런! 열쇠가 자물쇠 안에서 부러졌어요! 이제 평생 우리 밖으로 나가지 못할 거야!', `MaleText_loc4`='喔不！钥匙断在锁眼里了！我永远也别想离开这笼子了！', `MaleText_loc5`='噢不!鑰匙斷在鑰匙孔裡了!我永遠不可能從這籠子中出去了!', `MaleText_loc7`='¡Oh, no! La llave se ha roto en la cerradura! ¡Nunca lograré salir de esta jaula!' WHERE `ID`=40981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라이언은 제 이름이고, 사려면 절 부르시고! 뭐가 필요하십니까?', `MaleText_loc4`='莱恩为名，买卖随性！你想来点儿什么？', `MaleText_loc5`='我叫萊恩，我愛交易!你有些什麼?', `MaleText_loc7`='Mi nombre es Ryan y el comercio es mi negocio. ¿Qué necesitas?' WHERE `ID`=40982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라이언, 어떤 물건이 있는지 보여주십시오.', `MaleText_loc4`='让我看看你有些什么，莱恩。', `MaleText_loc5`='讓我看看你有什麼，萊恩。', `MaleText_loc7`='Enséñame lo que tienes, Ryan.', `FemaleText_loc1`='라이언, 어떤 물건이 있는지 보여주세요.', `FemaleText_loc4`='让我看看你有些什么，莱恩。', `FemaleText_loc5`='讓我看看你有什麼，萊恩。', `FemaleText_loc7`='Enséñame lo que tienes, Ryan.' WHERE `ID`=40983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 갈퀴발톱의 드루이드는 최전방 임무를 수행하는 데는 그다지 익숙하지 않아요. 공중 관측이나 은밀 침투가 주 임무니까요...$B$B그렇지만 가끔 이렇게 직접 발톱을 사용하는 것도 좋아한답니다.', `FemaleText_loc4`='我们猛禽德鲁伊并不适于前线作战。我们是空中侦察兵，是渗透者……$B$B不过我偶尔也不介意让我的爪子沾上血污。', `FemaleText_loc5`='我們猛禽德魯伊並不負責前線的戰鬥。我們是空中的斥候和間諜...$b$b但有時我們的利爪也會沾上鮮血。', `FemaleText_loc7`='Los Druidas de la Garfa no estamos hechos para el trabajo en el frente. Somos espías aéreos, infiltrados...$b$bPero a veces me gusta ensuciarme los espolones.' WHERE `ID`=40984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 조심하셔야 합니다. 웬디고들은 잔인한 동물이니까요.', `MaleText_loc4`='在这下面小心点儿，$c。这些雪怪都是残暴的战士。', `MaleText_loc5`='在這小心一點，$c。這些雪怪是野蠻的戰士。', `MaleText_loc7`='Tengo mucho cuidado aquí, $c. Esos wendigos son guerreros salvajes.' WHERE `ID`=40985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 대장님께서 원격 조종 관측 로봇을 설치한 뒤에 카라노스로 귀환하라고 말씀하셨습니다.', `MaleText_loc4`='萨兰恩队长希望你放置好观察机器人以后撤退至卡拉诺斯。', `MaleText_loc5`='薩蘭上尉要你部署好你的遙控觀測機器，然後撤回卡拉諾斯。', `MaleText_loc7`='El capitán Tharran quiere que despliegues tus robots de observación remotos y que te retires a Kharanos.', `FemaleText_loc1`='타란 대장님께서 원격 조종 관측 로봇을 설치한 뒤에 카라노스로 귀환하라고 말씀하셨어요.', `FemaleText_loc4`='萨兰恩队长希望你放置好观察机器人以后撤退至卡拉诺斯。', `FemaleText_loc5`='薩蘭上尉要你部署好你的遙控觀測機器，然後撤回卡拉諾斯。', `FemaleText_loc7`='El capitán Tharran quiere que despliegues tus robots de observación remotos y que te retires a Kharanos.' WHERE `ID`=40986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석어요! 딱합니다! 다가오는 종말은 눈치도 못 챈 채 이리저리 헤매는 자신을 보십시오!', `MaleText_loc4`='白痴！蠢货！看看你们无头苍蝇般的样子，对即将到来的末日浑然不觉！', `MaleText_loc5`='蠢貨!白癡!看你們毫無頭緒的亂竄，不知末日之將近!', `MaleText_loc7`='¡Estúpidos! ¡Simplones! Fijaos en cómo vais de acá para allá, ignorantes de que el final se acerca!' WHERE `ID`=40987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 간단한 질문 하나만 드렸으면 합니다. 인간은 땀 흘리며 일할 허락을, 아니 자격을 얻었습니까?', `MaleText_loc4`='请允许我问一个简单的问题：一个男人是否有资格靠自己的血汗为生？', `MaleText_loc5`='請容我問個簡單的問題:人是否能夠，甚至有資格，保有自己辛勤工作的成果?', `MaleText_loc7`='Permíteme que te haga una sencilla pregunta: ¿acaso un hombre no tiene derecho al sudor de su frente?' WHERE `ID`=40988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 이 동굴을 지긋지긋하게 봤습니다. 어서 카라노스로 돌아가고 싶어 못 견디겠군요.', `MaleText_loc4`='我这辈子看够这个洞穴了。我恨不得立即返回卡拉诺斯。', `MaleText_loc5`='我待在這個洞穴裡已經夠久，一輩子都不會想念這。我等不及要回到卡拉諾斯。', `MaleText_loc7`='Ya he visto esta cueva lo bastante para el resto de mi vida. No veo el momento de volver a Kharanos.' WHERE `ID`=40989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''아니오''라고 오그리마에 있던 오크가 말합니다. ''호드의 권리요!'' 라고 말입니다.', `MaleText_loc4`='“不”——奥格瑞玛的兽人说道，“它属于部落！”', `MaleText_loc5`='「不行」，奧格瑪的獸人說道，「那是屬於部落的!」', `MaleText_loc7`='"No", dice el orco de Orgrimmar, "¡le pertenece a la Horda!"' WHERE `ID`=40990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''아닙니다''라고 스톰윈드에 있던 인간이 말합니다. ''얼라이언스의 권리요!'' 라고 말입니다.', `MaleText_loc4`='“不”——暴风城的人类说道，“它属于联盟！”', `MaleText_loc5`='「不行」，暴風城的人類說道，「那是屬於聯盟的!」', `MaleText_loc7`='"No", dice el humano de Ventormenta, "¡le pertenece a la Alianza!"' WHERE `ID`=40991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때, 그런 답변을 받아들이지 않던 분을 알았습니다! 같은 생각을 하는 이를 위해 집을 지었던 위대한 분이었죠! 불가능한 일을 선택한 분이었습니다!', `MaleText_loc4`='我曾结识过一个摒弃这些答案的人！一个为那些令他感同身受的人建造家园的伟人！一个选择不可能的人！', `MaleText_loc5`='我知道有個人曾經拒絕過這兩種答案!一個為跟他有同樣理念的人打造了一個家園的偉人!一個選擇了不可能之任務的人!', `MaleText_loc7`='¡Conozco un hombre que rechazó esas respuestas! ¡Un gran hombre que construyó un hogar para aquellos que eran de su parecer! ¡Un hombre que eligió lo imposible!' WHERE `ID`=40992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분이 바로 겐 그레이메인이셨습니다. 그분이 선택했던 불가능한 일이 길니아스였죠!', `MaleText_loc4`='那个人就是吉恩·格雷迈恩，而那个“不可能”的选择就是吉尔尼斯！', `MaleText_loc5`='那個人就是吉恩·葛雷邁恩，而那不可能的任務就是吉爾尼斯!', `MaleText_loc7`='¡El hombre era Genn Cringris, y la elección imposible fue Gilneas!' WHERE `ID`=40993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 이 웬디고들도 성가시기는 하지만, 진정한 전투는 저기 서리갈기 부족의 난민들과 치러야 할 겁니다.', `MaleText_loc4`='这些雪怪当然是个麻烦，可真正的战斗却是对付那些霜鬃难民。', `MaleText_loc5`='這些雪怪是個麻煩沒錯，但真正的戰鬥是跟那些霜鬃難民。', `MaleText_loc7`='Los wendigos son un incordio, desde luego, pero la verdadera lucha es contra los refugiados Peloescarcha.' WHERE `ID`=40994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이... 오거라... 그들이... 나를 끌어내고 있다...', `FemaleText_loc4`='靠……近点……$c。他们……在把我拉远……', `FemaleText_loc5`='靠近點...$c。他們在...把我拉走...', `FemaleText_loc7`='Acércate... Me están... tirando…' WHERE `ID`=40995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 무덤 위로 어지럽고 희미하게 나타납니다.', `FemaleText_loc4`='有%s出现在圆环上方，模糊不清。', `FemaleText_loc5`='一隻%s出現在魔法陣上，模糊不清。', `FemaleText_loc7`='Un %s aparece sobre el círculo, difuso y desenfocado.' WHERE `ID`=40996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬께서 $n 님을 지켜보시길.', `FemaleText_loc4`='艾露恩在注视着你，$n。', `FemaleText_loc5`='伊露恩看照著你，$n。', `FemaleText_loc7`='Que Elune te proteja, $n.' WHERE `ID`=40997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베푸신 친절은 잊지 않겠어요!', `FemaleText_loc4`='你的仁慈将被永远铭记！', `FemaleText_loc5`='你的恩惠不會被遺忘!', `FemaleText_loc7`='¡Tu amabilidad no caerá en el olvido!' WHERE `ID`=40998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제까지라도 $n 님께 감사드리겠어요!', `FemaleText_loc4`='我将永远心怀感激，$n！', `FemaleText_loc5`='我永遠地感激你，$n!', `FemaleText_loc7`='¡Te estaré eternamente agradecida, $n!' WHERE `ID`=40999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끔찍한 호드 놈들이 저주받기를! $n 님이 아니었다면 전 이미 죽었을 거예요!', `FemaleText_loc4`='诅咒该死的部落！要不是有你在，我早就死了！', `FemaleText_loc5`='該死的流氓部落!如果沒我你我就死定了!', `FemaleText_loc7`='¡Maldita sea esa espantosa Horda! ¡Habría muerto de no ser por ti!' WHERE `ID`=41000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 똑똑하다고 생각하는 거죠? 그렇죠? 나를 이렇게 집단으로 괴롭히다니... 그렇다면, 어디 공포절단기와 한번 싸워 봐요!', `FemaleText_loc4`='你们自以为很聪明，是不是，像这样联手对付我……好吧，准备面对——恐怖伐木机！', `FemaleText_loc5`='你自以為很聰明，是吧?想這樣以多欺少...嘿，準備好面對:驚懼伐木機吧!', `FemaleText_loc7`='Os creéis muy listos, ¿verdad? ¿Uniéndoos contra mí? Pues preparaos para conocer... ¡LA TRITURAMATIC!' WHERE `ID`=41001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르거라...', `FemaleText_loc4`='快点……', `FemaleText_loc5`='快...', `FemaleText_loc7`='Rápido…' WHERE `ID`=41002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으으... 정정당당하게 싸우려고 했는데 친구를 데려오다니. 좋아! 어디 내 친구와 합금난타로봇 0호기와도 한번 싸워봐!', `FemaleText_loc4`='呃……我原本打算光明正大的与你公平交手，可你却带来了帮手。好吧！来面对合金锤击者零式吧！', `FemaleText_loc5`='哼...我本來想與你公平決鬥的，但你卻帶了幫手過來。很好!嘗嘗合金搗碎機零號的利害!', `FemaleText_loc7`='Grrr... Iba a luchar contigo de forma justa y honrada, pero has decidido traer a unos amigos. ¡Muy bien! ¡Contemplad al Machaca-aleación Cero!' WHERE `ID`=41003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 귀가 찢어지는 듯한 울음소리를 내며 당신의 머리 위로 나타납니다!', `MaleText_loc4`='%s俯视着你，发出一阵震耳发聩的嚎叫！', `MaleText_loc5`='%s帶著震耳欲聾的叫聲出現在你的上方!', `MaleText_loc7`='¡%s aparece sobre tu cabeza con un graznido ensordecedor!' WHERE `ID`=41004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 대장님께 설치한 원격 관찰로봇이 제대로 작동하는 것을 확인하는 즉시 카라노스로 귀환할 것이라고 전해 주십시오.', `MaleText_loc4`='告诉萨兰恩队长，等我确定那机器人能正常工作，我就立刻返回卡拉诺斯。', `MaleText_loc5`='跟薩蘭上尉說我一確定機器人運作正常就回馬上回去卡拉諾斯。', `MaleText_loc7`='Dile al capitán Tharran que volveré a Kharanos en cuanto verifique que el robot funciona correctamente.' WHERE `ID`=41005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 이곳을 벗어나 트롤들과 맞서 싸우고 싶어 몸이 근질거리는군요.', `MaleText_loc4`='我已经迫不及待想要离开这里，去帮助对付那些巨魔了。', `MaleText_loc5`='我等不及趕快從那出去加入與食人妖之間的戰鬥。', `MaleText_loc7`='No veo el momento de salir y ayudar a luchar contra esos trols.' WHERE `ID`=41006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자매여! 나도... 실패했...구나...', `FemaleText_loc4`='姐妹！我……也……失——败了……', `FemaleText_loc5`='姐姐!我...也...失敗了...', `FemaleText_loc7`='¡Hermana! Yo... también... he... f-fracasado.' WHERE `ID`=41007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이 일어난 뒤로 하루도 쉬는 날 없이 전투를 치러왔습니다. 휴식을 취할 수 있어서 정말 다행이군요. 비록 잠시뿐이라도 말이죠.', `MaleText_loc4`='自从大灾变发生以来，我们就日以继夜地战斗。能歇一歇真是太好了，哪怕只是稍作休息。', `MaleText_loc5`='大災變發生後我們就不停地在戰鬥。如果能稍微休息一下...會很好。', `MaleText_loc7`='No hemos parado de luchar desde el Cataclismo. Nos vendría bien un descanso, aunque sea breve.' WHERE `ID`=41008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 잘하셨습니다! 칼바람 요새로 돌아가셔서 팰로우미어 경께 호드의 꿍꿍이속을 알려 드리십시오. 저는 탈다라 전망대로 가서 우리 병사들에게 경고하겠습니다.', `FemaleText_loc4`='干得好，$n！回到风剪要塞把部落的意图告知指挥官法罗米尔。我会冒险前往萨达拉瞭望台，通知我们的士兵们。', `FemaleText_loc5`='做得好，$n!回到狂風堡通知法洛梅爾領主關於部落的意圖。我會到薩歐達拉瞰臺警告我們的士兵們。', `FemaleText_loc7`='¡Bien hecho, $n! Vuelve al Bastión Cortaviento y avisa a Lord Merobarbecho de las intenciones de la Horda. Yo entraré en el Mirador Thal''darah y alertaré a nuestros soldados.' WHERE `ID`=41009;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악! 얼굴은 안돼!', `FemaleText_loc4`='啊！别打脸！', `FemaleText_loc5`='啊!臉不行!', `FemaleText_loc7`='¡Agh! ¡En la cara no!' WHERE `ID`=41010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와아아아아!', `FemaleText_loc4`='哇——！', `FemaleText_loc5`='哇啊啊啊!!!!!', `FemaleText_loc7`='¡Aaaah!' WHERE `ID`=41011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 모두 죽은 목숨이다!', `MaleText_loc4`='现在你们统统去死吧！', `MaleText_loc5`='你們現在全都該死!', `MaleText_loc7`='¡Ahora moriréis todos!' WHERE `ID`=41012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정원 쪽에서 네 삼지창이 부러지는 소리가 들리더군! 크발디르의 두개골은 바위만큼이나 단단하지.', `MaleText_loc4`='我在花园里就能听到你的三叉戟折断的声音！那些克瓦迪尔的脑袋就跟岩石一样硬。', `MaleText_loc5`='我在花園可以聽到你三叉戟斷掉的聲音!這些科瓦迪爾的頭骨跟岩石一樣硬。', `MaleText_loc7`='¡Se oía tu tridente desde los jardines! Los cráneos de estos Kvaldires son fuertes como rocas.' WHERE `ID`=41013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겨우 한 갈래가 부러졌을 뿐입니다. 이대로도 수백 명은 거뜬히 해치울 수 있습니다.', `FemaleText_loc4`='一把叉子可不能阻止我再杀掉成百上千的敌人。', `FemaleText_loc5`='不過是斷了根分叉，根本無法阻止我再多殺個幾百個。', `FemaleText_loc7`='Una sola punta. Jamás podrá evitar que masacre a cientos más.' WHERE `ID`=41014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 뭐라 해도 전 사업가입니다. 절 다시 살려주시면 당신에게 붙어다니는 일은 깨끗이 그만두지요. 심지어 포상을 드릴지도 모릅니다.', `MaleText_loc4`='首先最重要的是，我是个商人。让我复活，我就停止对你的侵扰。你甚至还可能因此得到奖赏。', `MaleText_loc5`='第一點也是最重要的一點，我是個商人。把我帶回人世我就會停止糾纏你。你甚至還會有獎勵。', `MaleText_loc7`='Lo primero y más impoh''tante, soy un hombre de negocios. Si me devuelves la vi''a dejaré de atormentah''te. Incluso pue''e que haya una recompensa eh''perándote.' WHERE `ID`=41015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론. 그 정도론 널 막을 수 없지.', `MaleText_loc4`='当然，毋庸置疑。', `MaleText_loc5`='當然，毫無疑問。', `MaleText_loc7`='Ciertamente. No cualquiera podría.' WHERE `ID`=41016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 만약 당신이 저와 대화라도 시도했었더라면, 전 단순히 당신에게 열쇠를 팔아버렸을 수도 있었습니다. 하지만, 어차피 다 소용없었겠죠. 열쇠가 열쇠구멍 안에서 부러졌으니까요. 음하하하하하하하하하하!', `MaleText_loc4`='要知道，如果你在这整件事情上能通情达理一些，我也许就直接把钥匙卖给你了。倒不是说它会给你带来什么好处。但却能打破那把锁。木哈哈哈哈哈！', `MaleText_loc5`='你知道嗎，如果你在這整件事能再講點道理，我可能就會直接把鑰匙賣給你。雖然那不會對你有什麼太大的幫助。因為它已經斷在鑰匙孔裡了。哇哈哈哈哈哈!', `MaleText_loc7`='Sabes, si te hubieras moh''tra''o razonable, quizá simplemente te hubiera vendi''o la llave. Aunque tampoco es que te hubiera servi''o de mucho. Se rompió en la cerradura. ¡Buahahahahahaha!' WHERE `ID`=41017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 부인과 얽히게 해서 죄송합니다. 그녀는 미쳤어요, 하지만 전 그런 그녀를 아직 사랑합니다.', `MaleText_loc4`='很抱歉让你去和我妻子打交道，老兄。她很疯狂，但我仍然爱她，你知道吗？', `MaleText_loc5`='老兄，抱歉讓你必須應付我的老婆。她是瘋子，但我還是愛他，你懂嗎?', `MaleText_loc7`='Siento que hayas teni''o que aguantar a mi mujer, colega. Está loca, pero la quiero igua'', ¿sabes?' WHERE `ID`=41018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 사후세계도 그리 나쁘지 않은 것 같군요. 이곳엔 수많은 사업 거리가 보입니다. 괜찮은 조건만 내세우면 절 따를 영혼들이 널리고 널렸고 말입니다.', `MaleText_loc4`='做鬼的感觉也还不算糟。我能在这儿看到许多商机。不少鬼魂都在等待合适机会的到来。', `MaleText_loc5`='這個死後世界其實並沒那麼差。我看到了許多的生意機會。不少靈魂都在等待一個好的交易。', `MaleText_loc7`='El más allá no es pa'' tanto. Veo un montón de opoh''tunidades empresariales. Hay muchos eh''píritus eh''perando a que llegue el negocio adecua''o.' WHERE `ID`=41019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 쾌속선 공격은 그저 사업상의 오해 때문이었습니다. 당신이 절 구해주기만 하면 피즐과 포직과의 계약 체결을 고려해보죠.', `MaleText_loc4`='要知道，对赛艇平台的攻击只是场商业误会。等你把我复活之后，我会考虑与菲兹尔与普兹克洽谈一份合约。', `MaleText_loc5`='跟你說，導致高速駁船被攻擊的原因不過是一場生意上的誤會。當我被你復活後，我會考慮與菲茲爾和普茲克來簽署一份合約。', `MaleText_loc7`='Sabes, los ataque'' contra el Barcódromo no son más que un malentendi''o. Cuando me saques de aquí consideraré negociar un contrato con Fizzle y Pozzik.' WHERE `ID`=41020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 먹을 거 있습니까? 배고파 죽겠습니다!', `MaleText_loc4`='你有吃的吗？我很饿！', `MaleText_loc5`='你有什麼東西能吃嗎?我好餓!', `MaleText_loc7`='¿Tienes algo de comi''a? ¡Tengo hambre!' WHERE `ID`=41021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신을 따라다니는 게 마음에 안 드십니까? 안됐군요! 이제 열쇠 하나 때문에 누군가를 죽여야 한다면 재고하시는 게 좋을 겁니다!', `MaleText_loc4`='你不喜欢我到处跟着你吗？这可太糟了！也许下一次当你想要为了一把钥匙杀人时，你会三思！', `MaleText_loc5`='你不喜歡我跟著你嗎?很遺憾!或許下次你因為一把鑰匙而殺人前多想一想!', `MaleText_loc7`='¿Qué, no te guh''ta que te siga? ¡Una pena! ¡A lo mejor te lo pensarás dos vece'' la próxima vez que quieras asesinar a alguien solo pa'' conseguir una llave!' WHERE `ID`=41022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽 날씨가 어떠냐고요? 알려드리죠... 이쪽은 어두운 잿빛 하늘에 구름이 휘몰아치고 있습니다.', `MaleText_loc4`='天气怎么样？我说不好……总之这里到处都是灰蒙蒙阴沉沉的，天上还有翻卷的云。', `MaleText_loc5`='天氣如何?我不知道...這裡一片黯淡的灰色，還有旋轉的雲。', `MaleText_loc7`='¿Qué tiempo hace? No tengo ni idea... Aquí es to''o gris y con remolinos'' de nubes.' WHERE `ID`=41023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야몬의 여동생 사건은 모두 오해입니다. 전 그 아이의 아버지가 아닙니다, 정말이라고요! 제 생각에 뱃사람 파하르도가 범인인 것 같습니다. 아이가 제 아비를 꼭 빼닮았더라고요.', `MaleText_loc4`='阿加蒙姐妹那整件事真是个天大的误会。我没做过，我发誓！我想也许是老海盗法哈多。那小子看起来有点儿像他。', `MaleText_loc5`='那整個與阿迦蒙的姐妹有關的事是一場大誤會。不是我做的，我發誓!我覺得是老練水手法迦多。那小子長的跟他有點像。', `MaleText_loc7`='To''o eh''te follón con la hermana de Ajamon no ha si''o más que un malentendi''o. ¡Yo no fui, lo juro! Creo que fue el lobo de mar Fajardo. El crío e'' igualito que él.' WHERE `ID`=41024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 젠장, 제가 죽기 직전에 가려운 곳이 있었는데 아직도 가렵군요. 설마 이 가려움이 영원하진 않겠죠?! 저 좀 살려주십시오!!', `MaleText_loc4`='噢，老兄，我死的时候身上长了个疮，直到现在都没消失。你可别跟我说，我得永远带着它？！你一定要把我复活！！！', `MaleText_loc5`='老兄啊，我死的時候感覺有點癢，而現在它一直在癢。請告訴我這不會一直持續下去?!你一定要復活我!!!', `MaleText_loc7`='Ay, colega, cuando morí tenía un eh''cozor y ahora no se me va. ¡Dime que no va a durar toda la eterni''ad! ¡¡Tienes que resucitarme!!' WHERE `ID`=41025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들은 제가 해적으로 악명을 떨쳤다고 하지만, 당신은 설마 제가 돈 때문에 바다를 휘젓고 다니며 마구잡이로 사람을 죽였을 거라 생각하진 않겠... 아, 사실이군...', `MaleText_loc4`='他们说我是个臭名昭著的海盗，可你不会看到我为了点儿钱就四处航行滥杀无辜。喔，等一下……', `MaleText_loc5`='他們說我是個惡名昭彰的海盜，我又沒有到處航行亂殺人只為了要賺錢。呃，等一下...', `MaleText_loc7`='Se dice que tengo mala reputación como pirata, pero nadie me ha vih''to navegar por ahí matando gente indiscriminadamente solo pa conseguir pah''ta. Oh, eh''pera...' WHERE `ID`=41026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야몬이 다시 처녀 적 이름을 쓰더군요. 무슨 일이 있었든지 간에 좀 씁쓸합니다. 제 기분 아시겠어요?', `MaleText_loc4`='阿加蒙再一次使用了她的娘家姓。不管怎样，我会想念她的。你明白吗？', `MaleText_loc5`='阿迦蒙又再次用回原來的姓氏了。雖然發生了很多事，但我還是有點想念她，你懂嗎?', `MaleText_loc7`='Ajamon recuperó su nombre de soltera. A pesar de to''o, la echo de meno'', ¿sabes?' WHERE `ID`=41027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 여자들이 왜 나쁜지 알고 있습니까? 당신은 그녀들이 단지 죽은 자의 영혼을 불러오는 일만 하는 줄 알고 있겠죠. 하지만, 언젠가 그들이 단순히 대화만 하는 건 아니라는 걸 알게 될 겁니다! 제 말은, 그들은 유령과의 심적인 교감을 즐기는 거라고요!', `MaleText_loc4`='你知道为什么女人总是一无是处吗？因为你认为他们唯一会做的事就是招魂。可是然后，你发现她们并不只是会在那儿说话！我是说，那对鬼魂怎么会行得通？', `MaleText_loc5`='你想知道為什麼女人是不好的嗎?你會認為她們只會呼喚死亡的靈魂。但是呢，你又會抓到她們不只是在說話而已!你說，要怎樣才能跟一個鬼魂這樣?', `MaleText_loc7`='¿Sabes por qué no te pue''es fiar de las mujeres? Porque crees que se limitan a invocar los eh''píritus de los mueh''tos, pero entonces las pilla'' haciendo algo más que chah''lar. Vamos, ¿cómo pue''e funcionar siquiera con un fantasma?' WHERE `ID`=41028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸을 되찾기만 하면 당신을 반드시 죽일 겁니다! 아.. 그게 아니라, 제 말은 당신을 꼭 안아주겠다는 말이었습니다. 그렇죠, 그게 맞아요. 먼저 당신을 꼭 안아주고 큰 선물을 줄 겁니다. 제가 앞에 했던 헛소리는 무시하십시오.', `MaleText_loc4`='只要我一还魂，我就要杀了你，伙计！呃……不，我的意思是说，我就要拥抱你。对，没错，我就要抱住你，再给你一份大大的犒赏。别把我说的什么杀了你的话当回事。', `MaleText_loc5`='老兄，我一回到我的身體我就要殺了你!呃...沒有，我是說我要抱抱你。對對，我要抱你和給你一個大獎勵。忘了我說的那什麼殺不殺的。', `MaleText_loc7`='¡Cuando regrese a mi cuerpo, voy a matah''te, colega! Er... No, lo que quiero decir e'' que voy a dah''te un abrazo. Sí, eso eso, voy a dah''te un abrazo y una gran recompensa. No haga'' caso de eso que he dicho de matar.' WHERE `ID`=41029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨라타. 일이 잘 진행되고 있구나.', `MaleText_loc4`='啊，库拉萨。我相信一切都会顺利的。', `MaleText_loc5`='庫爾拉薩。事情看起來進行的還不錯。', `MaleText_loc7`='Kulratha. Veo que las cosas van bien.' WHERE `ID`=41030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아무것도 없던 황무지에 해적 제국을 만드는 데는 그리 오래 걸리지 않았죠. 아, 불모의 땅. 그때가 좋았죠. 그리고 보니... 이봐요, 혹시 만크릭의 부인에게 무슨 일이 있었는지 밝혀졌습니까?', `MaleText_loc4`='我没有用多长时间，就几乎是凭空创造出一个海盗帝国。啊，贫瘠之地。不过这都是过去的事了。嘿，有没有人知道曼科里克的妻子到底出了什么事？', `MaleText_loc5`='我白手起家建立了一個海盜王國並沒花我太久的時間。啊，貧瘠之地，真懷念啊。嘿，有人最後知道曼寇里克的老婆怎麼了嗎?', `MaleText_loc7`='No me coh''tó mucho levantar un imperio pirata de la na''a. Ah, Los Baldíos. Qué tiempo'' aquello''. Oye, ¿alguien sabe qué pasó al final con la mujer de Mankrik?' WHERE `ID`=41031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 조직에서 찾는 그런 류의 쓰레기입니다. 당신도 알다시피, 우린 남쪽바다 해적단이란 독립된 상호의 회사를 운영하고 있지요. 꽤 괜찮은 복지와 의료 보험, 치과 보험을 보장하는 데다 전망도 밝습니다. 더 자세한 이야기는 당신이 절 되살리고 나서 이야기해봅시다.', `MaleText_loc4`='我的组织正需要像你这样的帮手。要知道，我们是南海海盗独立运营的特许分支。我们向成员提供优厚的待遇、假期、全身检查、牙医和视力保健服务。也许我们应该等到你把我复活之后再谈。', `MaleText_loc5`='你就是我在我的組織中想找的那種人渣。你知道嗎，我們是南海掠劫者連鎖的獨立經營業。我們有不錯的獎金、假期和全額的醫療、牙齒和眼睛保險。或許我們應該在你幫我復活後再來談這些。', `MaleText_loc7`='Eres juh''to el tipo de escoria que busco pa mi organización. Ya sabes, somos una franquicia independiente de los Filibuh''teros de los Mare'' del Sur. Tenemos una pensión bah''tante buena, vacaciones, y un seguro médico, dental y ocular comp''eto. A lo mejor po''emos chah''lar cuando me devuelvas a la vida.' WHERE `ID`=41032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들의 사랑스러운 애완동물, 축복받은 야수 가즈릴라는 날마다 더 커지고 강해지고 있다... 황혼의 망치단과 마찬가지로.', `MaleText_loc4`='神兽加兹瑞拉——为上古之神所钟爱的灵宠，正在一天天地变得更大更强……暮光之锤教派也是如此。', `MaleText_loc5`='受到祝福的野獸加茲瑞拉，上古之神們的珍寵，牠一天比一天大，一天比一天強壯...就和暮光之錘教派一樣。', `MaleText_loc7`='Gahz''rilla, la bestia bendecida y mascota adorada de los dioses antiguos, se hace más grande y fuerte a medida que pasan los días... Al igual que el culto del Martillo Crepuscular.' WHERE `ID`=41033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하던 일을 계속하라, 유체술사여. 곧 이 세상이 다시 만들어지리라...', `MaleText_loc4`='继续你在这里的工作吧，水占师。这个世界很快就会被重塑……', `MaleText_loc5`='繼續你在這的工作，水占師。很快的，這個世界將會被重新組合...', `MaleText_loc7`='Prosigue con tu trabajo, hidromántica. Pronto este mundo renacerá...' WHERE `ID`=41034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그리고 너와 성난모래 부족은 주인님을 충실히 섬긴 만큼 보상을 받으리라!', `MaleText_loc4`='……只要效忠我们的主人，你和沙怒部落就能得到应有的奖赏！', `MaleText_loc5`='...做為我們主人的忠實僕人，你和沙怒氏族將得到應有的獎勵!', `MaleText_loc7`='...Y como los sirvientes devotos de nuestro maestro que son, ¡la tribu Furiarena y tú recibirán su justa recompensa!' WHERE `ID`=41035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 놈들을 없애라!', `MaleText_loc4`='入侵者！杀光他们！', `MaleText_loc5`='闖入者!殺了他們!', `MaleText_loc7`='¡INTRUSOS! ¡Matadlos!' WHERE `ID`=41036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 상대로 싸울 만큼 정말 용감하다고 생각하는 거야, 켈시? 저 땋은 머리를 한 것들은 파멸톱을 상대할 수 없을 거야!', `FemaleText_loc4`='你以为你们都能勇敢面对我，是吗，钢烁？！那些猪尾巴阻挡不了魔锯的力量！', `FemaleText_loc5`='鋼火，你以為你敢面對我很勇敢，嗯?!那些豬尾巴無法保護你免於承受毀滅之鋸的怒火!', `FemaleText_loc7`='Te crees muy valiente al enfrentarte a mí, ¿eh, Chispacero? ¡Esas coletas no te protegerán de la SIERRA DE FATALIDAD!' WHERE `ID`=41037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 조심하십시오! 록트로그 장군은 가까이에 있으니 금세 돌아올 겁니다!', `FemaleText_loc4`='小心，$n！督军罗克托克就在附近。他随时都会出现！', `FemaleText_loc5`='小心，$n!督軍羅克托格在附近。他隨時都有可能會回來!', `FemaleText_loc7`='¡Cuidado, $n! El señor de la guerra Roktrog está cerca. ¡Volverá en cualquier momento!' WHERE `ID`=41038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예. 머지않아 가즈릴라가 이교도의 도시를 직접 공격할 수 있을 만큼 균열이 커질 것입니다. 그러면 가즈릴라가 놈들의 도시를 얼어붙은 돌무더기로 바꿔 버리겠지요!', `FemaleText_loc4`='很快，加兹瑞拉就能通过增宽的裂隙一举摧毁异教徒的城市了。她会把它们都碾成冰冷的碎石！', `FemaleText_loc5`='很快的，裂隙就會大到足以讓加茲瑞拉直接攻擊那些異教徒的城鎮。牠會把它們全部變成冰凍的廢墟!', `FemaleText_loc7`='Pronto las fallas serán lo bastante grandes como para que Gahz''rilla asalte directamente las ciudades de los herejes. ¡Los reducirá a escombros helados!' WHERE `ID`=41039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군은 어디에 있습니까? 그를 처치하고 구해 드리겠습니다!', `MaleText_loc4`='督军在哪儿？我要杀了他，把你放出来！', `MaleText_loc5`='督軍在哪?我會殺了他後救你出去!', `MaleText_loc7`='¿Dónde está el Señor de la guerra? ¡Lo mataré y te liberaré!', `FemaleText_loc1`='장군은 어디에 있나요? 그를 처치하고 구해 드릴게요!', `FemaleText_loc4`='督军在哪儿？我要杀了他，把你放出来！', `FemaleText_loc5`='督軍在哪?我會殺了他後救你出去!', `FemaleText_loc7`='¿Dónde está el Señor de la guerra? ¡Lo mataré y te liberaré!' WHERE `ID`=41040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주 바쉬는 모친과 딴판이었지. 그녀가 오래전에 이 도시를 떠난 건 놀라울 일도 아니다.', `FemaleText_loc4`='瓦丝琪女士和她的母亲完全不同。毕竟她在很久以前就离开了这座城市。', `FemaleText_loc5`='瓦許女士跟她母親截然不同。這也難怪她很早就離開這座城市。', `FemaleText_loc7`='Lady Vashj es muy distinta a su madre. No es de extrañar que dejara la ciudad hace tanto.' WHERE `ID`=41041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 돌발톱 산맥에는 언제나 문제가 가득합니다. 그렇다고 돌발톱 산맥 때문에 땅과 그 위에 사는 이들이 큰 고통을 겪은 적은 없었습니다. 저지하지 않으면 호드가 우리 모두를 쓸어버리고 말 겁니다.', `MaleText_loc4`='石爪山这里总是困难重重，$n，但这片土地和生活在这里的人民从没像现在这么痛苦过。如果不加以制止的话，部落会把我们全都毁掉。', `MaleText_loc5`='石爪山脈一直都有問題，$n，但這塊土地和這裡的人民從沒像現在一樣那麼痛苦過。如果我就這麼走了，部落會摧毀這個地方的。', `MaleText_loc7`='Sierra Espolón siempre ha tenido problemas, $n, pero la tierra y sus gentes nunca han sufrido tanto. La Horda nos destruirá a todos si no le plantamos cara.' WHERE `ID`=41042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사랑하는 길니아스. 얼마나 그리운지...', `MaleText_loc4`='喔，我最亲爱的吉尔尼斯，我是多么的想念你……', `MaleText_loc5`='噢，親愛的吉爾尼斯，天知道我有多想你...', `MaleText_loc7`='Oh, queridísima Gilneas, cuánto la echo de menos...' WHERE `ID`=41043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 도우러 오너라, 비룡이여!', `MaleText_loc4`='龙啊，来帮助我！', `MaleText_loc5`='飛龍，來幫助我!', `MaleText_loc7`='¡Ven en mi ayuda, draco!' WHERE `ID`=41044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아야! 뜨겁잖아!', `FemaleText_loc4`='嗷！好烫！！', `FemaleText_loc5`='嗚!很燙啊!!', `FemaleText_loc7`='¡Ay! ¡Eso quema!' WHERE `ID`=41045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오우 오우! 오우 오우 오우!', `FemaleText_loc4`='哎呦！哎呦呦……！', `FemaleText_loc5`='啊嗚!啊嗚啊嗚啊嗚..!', `FemaleText_loc7`='¡Ay! ¡Ay ay ay!' WHERE `ID`=41046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앗 따가워!', `FemaleText_loc4`='疼！', `FemaleText_loc5`='好利!', `FemaleText_loc7`='¡Afilado!' WHERE `ID`=41047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 이거다. 고대정령은 우리의 것이 될 것이다.', `FemaleText_loc4`='就是它了。远古之神一定会站在我们这边。', `FemaleText_loc5`='就是這個。先祖將會是我們的了。', `FemaleText_loc7`='Este es. El ancestro será nuestro.' WHERE `ID`=41048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나머지 것들을 불의 땅 부화장으로 가져가라! 우리는 곧 하늘을 차지하리라.', `FemaleText_loc4`='把其余的带去火焰之地孵化场！很快我们就将控制天穹。', `FemaleText_loc5`='將其他的帶到火源之界孵化室!我們很快就會掌控整個天空。', `FemaleText_loc7`='¡Lleva los demás al Criadero de las Tierras de Fuego! Pronto los cielos serán nuestros.' WHERE `ID`=41049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날개 달린 모든 생물의 어머니시여, 제 기도를 들어 모습을 나타내소서... 환영이라! 이게 무슨 뜻일까요, $n? 제가 옴누론 님께 이 사실을 알리겠습니다.', `FemaleText_loc4`='天空万灵之母，聆听我的祈祷，为你自己显现……一幕景象！这会是什么意思呢，$n？我要报告给欧穆隆。', `FemaleText_loc5`='有翼生物之母，傾聽我的聲音現形於此吧...一道影像!這代表了什麼，$n?我會將這報告給歐姆奴隆。', `FemaleText_loc7`='Madre de todas las criaturas aladas, escucha mi plegaria y revélate ante mí... ¡Una visión! ¿Qué significará esto, $n? Informaré a Omnuron de esto.' WHERE `ID`=41050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 주머니에 있는 다이너마이트가 KS-L10 스틸스파크를 얼마나 좋아하는지 한번 보자, 멕스!', `FemaleText_loc4`='让我们看看你口袋里那些炸药喜不喜欢KS-L10钢烁，梅格斯！', `FemaleText_loc5`='梅格斯，讓我們看看在你的口袋裡的那些炸藥喜不喜歡KS-L10鋼火!', `FemaleText_loc7`='¡A ver qué piensa la dinamita de tu bolsillo del Chispacero KS-L10, Megs!' WHERE `ID`=41051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꺄악! 이거 물잖아!', `FemaleText_loc4`='呀！好疼！', `FemaleText_loc5`='哇嗚!那很痛耶!', `FemaleText_loc7`='¡Ay! ¡Eso escuece!' WHERE `ID`=41052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이햐하하하하!', `FemaleText_loc4`='Yeouuwch！！！', `FemaleText_loc5`='哇呀嗚!!!', `FemaleText_loc7`='¡Aaauuu!' WHERE `ID`=41053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 좀 구해주세요, $c님! 저자는 미쳤어요... 분명히 미쳤다고요! 버섯구름 봉우리를 휩쓴 홍수를 막을 수 없었다는 자책감이 그를 완전히 미치게 만들었어요!$B$B그는 대격변을 포함한 모든 상황을 제 잘못으로 뒤집어씌웠어요. 제가 데스윙이 변장이라도 한 모습이라 생각할 걸요!$B$B제발 살려주세요!', `MaleText_loc4`='你一定要救救我，$c！他已经疯了……疯了知道吗！由于他不能改变千针石林被洪水吞没的事实，他已经彻底精神失常了！$B$B他把一切都怪罪到我头上，包括大灾变。他可能认为我是死亡之翼或什么东西假扮的！$B$B救命！', `MaleText_loc5`='你一定要救救我，$c!他瘋了...真的瘋了!他對無力阻止千針石林被淹沒這一事已經被弄瘋了!$B$B什麼都怪我，包括大災變也怪我。他大概覺得我是死亡之翼偽裝的，或是類似的!$B$B救命啊!', `MaleText_loc7`='¡Tienes que ayudarme, $c! Se ha vuelto loco... Loco, ¿me oyes? Su impotencia ante la inundación de Las Mil Agujas le ha hecho perder el juicio.$b$bMe culpa por todo, hasta por el Cataclismo. Probablemente se piensa que soy Alamuerte disfrazado o algo.$b$b¡Socorro!' WHERE `ID`=41054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 안코나닭을 파신다면서요?', `MaleText_loc4`='我听说你出售灰色小鸡？', `MaleText_loc5`='我聽說你有賣灰色小雞?', `MaleText_loc7`='¿Es verdad que vendes pollos de Ancona?', `FemaleText_loc1`='당신이 안코나닭을 파신다면서요?', `FemaleText_loc4`='我听说你出售灰色小鸡？', `FemaleText_loc5`='我聽說你有賣灰色小雞?', `FemaleText_loc7`='¿Es verdad que vendes pollos de Ancona?' WHERE `ID`=41055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잡았다, 이 배은망덕한 것! 묻는 대로 대답하지 않으면 큰일 날 줄 알아.', `FemaleText_loc4`='抓到你了小家伙！你最好开口，别逼我动手。', `FemaleText_loc5`='逮到你了，臭鳥人!你最好乖乖回答，不然我就動手了。', `FemaleText_loc7`='¡Te tengo, labios de pollo! O tú empiezas a hablar, o yo empiezo a apuñalar.' WHERE `ID`=41056;
