UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<매리언이 비명을 지르며 당신을 노려봅니다.>', `FemaleText_loc4`='<玛瑞恩一边大声喘叫一边瞪着你。>', `FemaleText_loc5`='<瑪莉恩尖聲呱叫，惡狠狠地瞪著你。>', `FemaleText_loc7`='<Marion grazna con fuerza y te lanza una mirada furibunda.>' WHERE `ID`=41059;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희의 도시는 무너질 것이다, $r 녀석아. 새 세계의 어둠이 내리면 너도 사라지겠지!', `FemaleText_loc4`='你们的城市将会陷落，$r。你们将消亡在新政权的黑暗之中！', `FemaleText_loc5`='你們的城市將會淪陷，$r。你們會在新的黑暗統治之下全數滅亡!', `FemaleText_loc7`='Sus ciudades caerán, $r. ¡Ustedes perecerán en la oscuridad del nuevo orden!' WHERE `ID`=41060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음대로 해 봐라. 나의 새 주인님께서 네놈의 살가죽에 내 이름을 새겨 주실 테니까. 네놈을 처형하기 직전에 말이다.', `FemaleText_loc4`='想做什么尽管去做。我的新主人将会在他们处死你之前，把我的名字刻进你的血肉里。', `FemaleText_loc5`='要殺要宰隨便你!我的新主人會在處死你之前將我的名字刻在你的身上。', `FemaleText_loc7`='Haz lo que se te antoje. Mis nuevos maestros grabarán mi nombre en tu carne antes de ejecutarte.' WHERE `ID`=41061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<그녀를 고분고분하게 만듭니다.>', `MaleText_loc4`='<说服她。>', `MaleText_loc5`='<對她釋出善意。>', `MaleText_loc7`='<Darle un incentivo.>', `FemaleText_loc1`='<그녀를 고분고분하게 만듭니다.>', `FemaleText_loc4`='<说服她。>', `FemaleText_loc5`='<對她釋出善意。>', `FemaleText_loc7`='<Darle un incentivo.>' WHERE `ID`=41062;
