UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 끝없이 지껄이지만 않았어도 내가 물을 막을 수 있었을 거다!', `MaleText_loc4`='要不是因为你总是在咯咯咯的叫，我就能挡住海水！', `MaleText_loc5`='如果不是因為你一直在咯咯叫的關係，我已經阻止大海了!', `MaleText_loc7`='¡Habría podido detener el mar si no hubiera sido por tu incesante cacareo!' WHERE `ID`=41070;
