UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 수익 중 일부는 내가 챙기는 게 좋겠군! 아니지, 그냥 너를 처치하고 수익 모두를 차지하는 게 더 좋겠어.', `MaleText_loc4`='我得给自己捞点儿提成！最好直接把你烤熟了然后独吞所有利润。', `MaleText_loc5`='我最好要求分一杯羹!或更好的是，我只要把你炸了後再把所有的利潤拿走就好。', `MaleText_loc7`='¡Espero recibir tajada de esas ventas! Mejor todavía, te dejaré $gfrito:frita; y me quedaré con todos los beneficios.' WHERE `ID`=41090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 알을 훔치지?', `MaleText_loc4`='你为什么要偷这些蛋？', `MaleText_loc5`='你為什麼要偷蛋?', `MaleText_loc7`='¿Por qué estás robando huevos?', `FemaleText_loc1`='왜 알을 훔치지?', `FemaleText_loc4`='你为什么要偷这些蛋？', `FemaleText_loc5`='你為什麼要偷蛋?', `FemaleText_loc7`='¿Por qué estás robando huevos?' WHERE `ID`=41091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분께서 알을 구해오라고 하셨다. 다른 세계에 있는 불의 부화장에 쓸 알들을.$B$B그중에서도 특별한... 특별한 알 하나를... 찾으셨다.', `FemaleText_loc4`='她要这些蛋。要把它们带到她在另一个王国的炽热孵化场。$B$B而其中一只蛋……很特别的一只……是她最想要的。', `FemaleText_loc5`='她要蛋，她在另一個界域的火焰孵化室需要蛋。$B$B但是有一顆蛋...一顆特殊的蛋...是她特別想要的。', `FemaleText_loc7`='Pidió huevos. Huevos para su criadero ígneo en otro reino.$b$bY un huevo... un huevo especial... lo quería más que cualquier otro.' WHERE `ID`=41092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 누구야? 누구에게 알을 주는 거지?', `MaleText_loc4`='谁？你要把这些蛋拿给谁？', `MaleText_loc5`='誰?你要把這些蛋給誰?', `MaleText_loc7`='¿Quién? ¿A quién le estás dando los huevos?', `FemaleText_loc1`='그게 누구야? 누구에게 알을 주는 거지?', `FemaleText_loc4`='谁？你要把这些蛋拿给谁？', `FemaleText_loc5`='誰?你要把這些蛋給誰?', `FemaleText_loc7`='¿Quién? ¿A quién le estás dando los huevos?' WHERE `ID`=41093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분은 하늘과도 같지만, 어둠과도 같다. 대지의 수호자의 피가 흐르시기에 천하무적이시지!', `FemaleText_loc4`='她是天穹之主，也是黑暗之王。她是大地守护者的子嗣。她是不可战胜的！', `FemaleText_loc5`='她就是天空，但同時也是黑暗。大地守護者的子裔。是無敵的!', `FemaleText_loc7`='Domina los cielos, pero también la oscuridad. Es del linaje del Guardián de la Tierra. ¡Es invencible!' WHERE `ID`=41094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 수호자의 피라면... 검은용군단을 말하는 건가? 이름을 대라!', `MaleText_loc4`='大地守护者的子嗣……你听命于一只黑龙？告诉我名字！', `MaleText_loc5`='大地守護者的子裔...你是黑龍的人?我要名字!', `MaleText_loc7`='Prole del Guardián de la Tierra... ¿Respondes ante un dragón Negro? ¡Dame un nombre!', `FemaleText_loc1`='대지의 수호자의 피라면... 검은용군단을 말하는 건가? 이름을 대라!', `FemaleText_loc4`='大地守护者的子嗣……你听命于一只黑龙？告诉我名字！', `FemaleText_loc5`='大地守護者的子裔...你是黑龍的人?我要名字!', `FemaleText_loc7`='Prole del Guardián de la Tierra... ¿Respondes ante un dragón Negro? ¡Dame un nombre!' WHERE `ID`=41095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 $r 같으니! 이제 새로운 질서가 생겼다. 아비아나는 죽었어. 죽었다고! 다시는 돌아오지 않는다.$B$B나무에 있는 드루이드들에게도 그렇게 전해라.$B$B세스리아 님께서 곧 하늘의 주인이 되실 것이다. 그리고 아비아나가 다시는 되살아나지 않도록 손을 쓰셨다. 알은 세스리아 님의 것이다.$B$B너희는 한발 늦은 거야.', `FemaleText_loc4`='愚蠢的$r！新的秩序已然建立。艾维娜已经死了。死了！再也不会回来了。$B$B回去告诉树林里的那群德鲁伊。$B$B塞西莉亚很快将成为新的天穹之主，而且有她在，艾维娜再也别想重生！蛋是塞西莉亚的了！$B$B你来的太迟了。', `FemaleText_loc5`='愚蠢的$r!新的秩序已經誕生。艾維娜已經死了，死了!!永遠不會再回來。$B$B把這些話告訴樹上那些德魯伊。$B$B賽瑟莉亞很快就會成為天空的女王，她將不會給艾維娜任何重生的機會。蛋是她的。$B$B你來得太晚了。', `FemaleText_loc7`='¡$R idiota! Ahora existe un nuevo orden. Aviana está muerta. ¡MUERTA! Y nunca volverá.$B$BDíselo a los druidas de los árboles.$B$BPronto Sethria será la señora de los cielos y se ha asegurado de que Aviana no pueda renacer nunca. El huevo es suyo.$B$BLlegas demasiado tarde.' WHERE `ID`=41096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 결정하셨어요, $n 님. 우리 아비아나 님의 신성한 제단을 공격한 벌을 받은 거예요.', `FemaleText_loc4`='你自己决定，$n。当玛瑞恩攻击我们主人的圣殿时，就已经为自己惹上了麻烦。', `FemaleText_loc5`='你說了算，$n。瑪莉恩攻擊了我們主母的神聖祭壇，這是她咎由自取。', `FemaleText_loc7`='Tú decides, $n. Marion se lo buscó cuando atacó el santuario sagrado de nuestra señora.' WHERE `ID`=41097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<티살리에게 하피를 죽이라고 명령합니다.>', `MaleText_loc4`='<任由希萨莉处置这只鹰身女妖。>', `MaleText_loc5`='<下令黎沙莉殺死鷹身人。>', `MaleText_loc7`='<Ordena a Thisalee que mate a la arpía.>', `FemaleText_loc1`='<티살리에게 하피를 죽이라고 명령합니다.>', `FemaleText_loc4`='<任由希萨莉处置这只鹰身女妖。>', `FemaleText_loc5`='<下令黎沙莉殺死鷹身人。>', `FemaleText_loc7`='<Ordena a Thisalee que mate a la arpía.>' WHERE `ID`=41098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 만세! 정신이 들었네! 총을 어떻게 쏘는지는 기억나? 1분만 시간을 내서 다시 싸우는 법을 배워보면 어떨까? 혹시나 해서 말이야.', `FemaleText_loc4`='万岁，钳子先生！你回来了！你还记得怎么向敌人开枪吗？为什么不花点时间重新把战斗的技艺拾起来！以防万一。', `FemaleText_loc5`='耶，P先生!你回來了!你還記得如何操作你的槍嗎?你何不花幾分鐘練習一下!以防萬一。', `FemaleText_loc7`='¡Hurra, señor P.! ¡Has vuelto! ¿Recuerdas cómo disparar todas tus armas? ¡Por qué no te tomas unos minutos para refrescar cómo se luchaba! Por si acaso.' WHERE `ID`=41099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<티살리에게 하피를 풀어달라고 부탁합니다.>', `MaleText_loc4`='<要求希萨莉释放鹰身女妖。>', `MaleText_loc5`='<要求黎沙莉放走鷹身人。>', `MaleText_loc7`='<Pide a Thisalee que libere a la arpía.>', `FemaleText_loc1`='<티살리에게 하피를 풀어달라고 부탁합니다.>', `FemaleText_loc4`='<要求希萨莉释放鹰身女妖。>', `FemaleText_loc5`='<要求黎沙莉放走鷹身人。>', `FemaleText_loc7`='<Pide a Thisalee que libere a la arpía.>' WHERE `ID`=41100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 그대는 저보다 훌륭하신 분이세요. 그런데 이곳의 하피들은 하수인에 불과한 것 같군요.', `FemaleText_loc4`='你是个比我更好的人，$n。可我认为这里的鹰身人只是爪牙而已。', `FemaleText_loc5`='你比我好心多了，$n。好吧，反正鷹身人只是爪牙而已。', `FemaleText_loc7`='Eres mejor persona que yo, $n. Pero supongo que las arpías no son más que meros peones.' WHERE `ID`=41101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 정말 정말 조심해. 무더기로 있는 고블린을 보면 자기 인력 기술을 써! 전부 끌어당긴 다음에 저승으로 보내버리라고! 알았지!', `FemaleText_loc4`='一定要多加小心，水泡先生。要是你看到一大群地精，就用你的磁力对付他们！等你把他们全都吸过来之后，就送他们上西天！吖！', `FemaleText_loc5`='小心點，P先生。你如果看見一大群的哥布林就使用你的磁力吸引!一旦你將他們全都吸起來後，就丟給他們死!噢耶!', `FemaleText_loc7`='Ten mucho cuidado, Sr. P. ¡Si ves un grupo grande de goblins utiliza tu atracción magnética! ¡Una vez los hayas succionado a todos, lánzalos a su muerte! ¡SÍ!' WHERE `ID`=41102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨, 저놈들 잡아!', `FemaleText_loc4`='抓住他们，水泡先生！', `FemaleText_loc5`='抓住他們，P先生!', `FemaleText_loc7`='¡A por ellos, Sr. P.!' WHERE `ID`=41103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 관절을 꺾어버려!', `FemaleText_loc4`='打碎他们的骨头，水泡先生！', `FemaleText_loc5`='粉碎他們的骨頭，爸爸!', `FemaleText_loc7`='¡Rómpeles los huesos, papá!' WHERE `ID`=41104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠씨를 아프게 한 만큼 쓴맛을 보여줘!', `FemaleText_loc4`='让他们后悔对你造成的伤害，水泡先生！', `FemaleText_loc5`='讓他們瞭解傷害你的下場是什麼，P先生!', `FemaleText_loc7`='¡Haz que sientan haberte hecho daño, Sr. P!' WHERE `ID`=41105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야호!', `FemaleText_loc4`='吖！', `FemaleText_loc5`='耶!', `FemaleText_loc7`='¡SÍ!' WHERE `ID`=41106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 더 아프게 해 줘! 더 아프게!', `FemaleText_loc4`='让他们更痛苦！更痛苦！', `FemaleText_loc5`='讓他們死!讓他們死!', `FemaleText_loc7`='¡Hazles más daño! ¡MÁS!' WHERE `ID`=41107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드, 나빠! 못 됐어!', `FemaleText_loc4`='可恶，可恶，可恶的部落！', `FemaleText_loc5`='壞部落!壞部落!', `FemaleText_loc7`='¡MALA, HORDA MALA!' WHERE `ID`=41108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장기술로 처리해야 할 거라도 있으신가?', `MaleText_loc4`='需要什么吗？', `MaleText_loc5`='需要鍛造服務嗎?', `MaleText_loc7`='¿Necesitas un herrero?' WHERE `ID`=41109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리할 게 있습니다, 아이언고트.', `MaleText_loc4`='我需要修理，铁羊。', `MaleText_loc5`='我的東西需要修理，鐵羊。', `MaleText_loc7`='Necesito reparaciones, Hierrocabra.', `FemaleText_loc1`='수리할 게 있어요, 아이언고트.', `FemaleText_loc4`='我需要修理，铁羊。', `FemaleText_loc5`='我的東西需要修理，鐵羊。', `FemaleText_loc7`='Necesito reparaciones, Hierrocabra.' WHERE `ID`=41110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 부활했도다!', `MaleText_loc4`='我还活着！', `MaleText_loc5`='我活著!', `MaleText_loc7`='¡EH''TOY VIVO!' WHERE `ID`=41111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구. 당신은 약속을 지켰고 그 점은 제가 존중합니다.', `MaleText_loc4`='谢谢你，伙计。你实现了自己的诺言，我很钦佩。', `MaleText_loc5`='謝啦，老兄。你沒有食言，我敬重你。', `MaleText_loc7`='Gracias, colega. Has cumpli''o tu palabra, y eso lo re''peto.' WHERE `ID`=41112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이제 돌아가야만 합니다. 하지만 언젠가는 다시 만날 거라 생각합니다. 다음번에는 제가 이 은혜를 갚겠습니다.', `MaleText_loc4`='我要回去了。相信我们一定会再见面。下次见面时，我一定会还你这个人情。', `MaleText_loc5`='我必須回去了。我確定我們的命運一定會再度交錯。下一次會是我還你人情的時候。', `MaleText_loc7`='Debo volver. Seguro que no'' volveremos a encontrar. La próxima vez me toca devolveh''te el favo''.' WHERE `ID`=41113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가요, 여보. 오늘 밤에 봐요.', `MaleText_loc4`='再见，阁下。今晚再见。', `MaleText_loc5`='再見，甜心。我們晚上見。', `MaleText_loc7`='Chao, cielo. Luego te veo.' WHERE `ID`=41114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오 안돼, 토니. 저리 가버려, 난 지금 애인을 소환하느라 바쁘단 말이야!', `FemaleText_loc4`='不，千万别，托尼。离我远点儿，我晚上还有约会呢！', `FemaleText_loc5`='不行，東尼。走開，我正忙著安排晚一點的約會!', `FemaleText_loc7`='No, no me verás, Tony. Vete, ¡estoy ocupada invocando una cita para después!' WHERE `ID`=41115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아비아나의 제단에서 다시 만나요, $n 님!', `MaleText_loc4`='回艾维娜圣殿找我，$n！', `MaleText_loc5`='到艾維娜的聖壇見我，$n!', `MaleText_loc7`='¡Reúnete conmigo en el Santuario de Aviana, $n!' WHERE `ID`=41116;
