UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 이거 좀 당황스럽군...', `MaleText_loc4`='嗯，这可有点儿令人尴尬……', `MaleText_loc5`='呃，這有點令人不好意思...', `MaleText_loc7`='Bueno, esto es un poco embarazoso.' WHERE `ID`=41126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없이 참견한 대가를 치르게 될 것이다, $c 놈아!', `MaleText_loc4`='你要为你的妄为付出代价，$c！', `MaleText_loc5`='多管閒事是要付出代價的，$c!', `MaleText_loc7`='¡Pagarás por tu intromisión, $c!', `FemaleText_loc1`='거기서 물러나라, $c 놈아!', `FemaleText_loc4`='你要为你的妄为付出代价，$c！', `FemaleText_loc5`='離火源信號遠一點，$c!', `FemaleText_loc7`='¡Aléjate de aquí, $c!' WHERE `ID`=41127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 다 됐다, 매리언.', `FemaleText_loc4`='时间到了，玛瑞恩。', `FemaleText_loc5`='時間到了，馬里恩。', `FemaleText_loc7`='Se acabó el tiempo, Marion.' WHERE `ID`=41128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이스크림 사 주세요!', `FemaleText_loc4`='冰淇淋！', `FemaleText_loc5`='冰淇淋!', `FemaleText_loc7`='¡Helado!' WHERE `ID`=41129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠씨를 도울 준비가 되었으니 타게 해 주렴, 꼬마야.', `MaleText_loc4`='我已经准备好帮助Mr. P了，孩子。让我进去。', `MaleText_loc5`='我準備好跟P先生一起幫忙了，小子。讓我進去。', `MaleText_loc7`='Estoy listo para ayudar con el Sr. D. Déjame entrar.', `FemaleText_loc1`='아빠씨를 도울 준비가 되었으니 타게 해 주렴, 꼬마야.', `FemaleText_loc4`='我已经准备好帮助Mr. P了，孩子。让我进去。', `FemaleText_loc5`='我準備好跟P先生一起幫忙了，小子。讓我進去。', `FemaleText_loc7`='Estoy lista para ayudar con el Sr. D. Déjame entrar.' WHERE `ID`=41130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 $r 녀석이 여기 얼쩡거리지? ...그것도 하필 지금 같은 때에?$b$b흐으으으음?', `MaleText_loc4`='像你这样的$r在这里干什么？……尤其是在现在这样的时候？$b$b嗯？', `MaleText_loc5`='一個$r在這個地方做什麼?...尤其是在現在這種時刻?$b$b嗯?', `MaleText_loc7`='¿Qué hace $gun:una; $r como tú en un lugar como este...? ¿Especialmente en un momento como este?$b$b¿Mmmm?' WHERE `ID`=41131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 사악한 짐승은 물리쳤지만, 소중한 물이 오염되고 말았다! 즉시 정화해야만 한다.$b$b이곳에 계속 머무르려거든, 스스로 방어할 마음의 준비를 해라.', `MaleText_loc4`='那该死的野兽被赶跑了，可我宝贵的水资源被玷污了！我必须立刻净化它。$b$b如果你坚持要继续留在这儿，就请自保吧。', `MaleText_loc5`='骯髒的野獸已經被擊退了，但我珍貴的水也被污染了!我必須馬上淨化它們。$b$b如果你還想待在這，最好有要保護自己的心理準備。', `MaleText_loc7`='¡Esa bestia vil ha sido espantada, pero mis preciosas aguas han sido contaminadas! Debo purificarlas inmediatamente.$b$bSi insisten en quedarse aquí, prepárense para defenderse.' WHERE `ID`=41132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다!', `MaleText_loc4`='我们准备好了！', `MaleText_loc5`='我們準備好了!', `MaleText_loc7`='¡Estamos listos!', `FemaleText_loc1`='준비됐어요!', `FemaleText_loc4`='我们准备好了！', `FemaleText_loc5`='我們準備好了!', `FemaleText_loc7`='¡Estamos listos!' WHERE `ID`=41133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $c|1이여;여;! 하늘을 나는 모든 생명체의 안식처, 아비아나의 제단에 온 것을 환영합니다.$B$B아비아나 님은 우리 곁에 안 계실지 모르지만, 그분의 정신과 패기는 날개 달린 생명체의 마음속에 늘 살아 있습니다.$B$B아비아나 님의 이야기가 궁금하면, 아래에 있는 초루나와 이야기해 보십시오.', `MaleText_loc4`='欢迎你，$c！欢迎来到艾维娜圣殿——天空中所有生灵的避风港。$B$B艾维娜或许已经不再与我们同在，但她的心魂与她的凶猛战力却将永远留存在所有藉双翼翱翔的生灵身上。$B$B要是你想了解艾维娜的故事，可以与位于下方的楚伦娜交谈。', `MaleText_loc5`='歡迎，$c!歡迎來到艾維娜聖壇，所有天空中的生物之僻護所。$B$B艾維娜或許已經不在了，但她的意志和勇猛活在所有擁有翅膀的生物心中。$B$B如果你對艾維娜的故事有興趣，與下方的克魯娜聊聊吧。', `MaleText_loc7`='¡Te doy la bienvenida, $c! Te doy la bienvenida al Santuario de Aviana, el paraíso para todas las criaturas del cielo.$B$BPuede que Aviana ya no esté entre nosotros, pero su corazón y su ferocidad perduran en todas las criaturas aladas.$B$BHabla con Choluna, abajo, si tienes curiosidad por la historia de Aviana.' WHERE `ID`=41134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티살리의 말로는 하피들이 용들과 손을 잡았다던데, 정말입니까? 하지만 이해가 잘 안 되는군요. 조금 더 알아봐야겠습니다.$B$B여기서 초루나를 도와, 이번 일의 전모를 파악해 주십시오...', `MaleText_loc4`='希萨莉告诉我，鹰身人和龙结成了联盟？可有些事情却怎么都说不通。我们必须了解更多才行。$B$B请在此协助楚伦娜的工作，看看我们能否将这一切都串连起来……', `MaleText_loc5`='黎沙莉跟我說鷹身人已經跟龍族結盟了?但有些地方很不合理，我們必須收集更多情報。$B$B請幫助克魯娜在這裡的工作，看看我們是否能將所有線索串接起來...', `MaleText_loc7`='¿Thisalee me dice que las arpías están compinchadas con los dragones? Pero algo no cuadra. Debemos averiguar más.$b$bAyuda a Choluna con su trabajo, a ver si podemos aclarar esto...' WHERE `ID`=41135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초루나가 그대가 본 환영에 대해 말해줬습니다. 이해가 잘 안 되는군요. 우리의 소중한 고대정령께서 되살아나신단 말일까요? 그렇다면 그분은 어디 계실까요?$B$B좀 더 자세히 알 필요가 있습니다. 티살리를 도와 더 많은 정보를 수집하십시오. 그 후에 행동을 취하겠습니다.', `MaleText_loc4`='楚伦娜告诉了我你所看见的情景。那非常令人困惑。我们珍爱的古树将要重生吗？如果是这样，现在她在哪里？$B$B我们需要得到更多的信息！请帮助希萨莉进一步收集信息，这样我们才能采取行动。', `MaleText_loc5`='克魯娜告訴了我你所看到的。非常讓人困惑。我們崇愛的先祖將會重生嗎?如果是的話，她現在在哪裡?$B$B我們需要知道更多!請幫助黎沙莉為我們搜集更多的情報，然後我們再來展開行動。', `MaleText_loc7`='Choluna me ha hablado de tu visión. Muy extraño. ¿Quizá nuestro amado ancestro renacerá? Y si es así, ¿dónde está ahora?$B$B¡Necesitamos saber más! Por favor, ayuda a Thisalee a recopilar más información para nosotros. Después, actuaremos.' WHERE `ID`=41136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 뭘 하고 있는지 모르겠어. 난 협상가의 경험은 없거든.$B$B옛날에는 술집에서 일했는데, 예쁜 데이지가 등장하면서 자리를 뺏겼지. 새로운 직업을 찾아야 할 때인 것 같아.', `MaleText_loc4`='我不知道我在这儿干什么。我没有做合约谈判员的经验。$B$B我以前曾经干过酒保，可因为黛西的原因做不下去了。也许是时候转行了。', `MaleText_loc5`='我不知道我在這幹麻。我在合約商討上沒有任何的經驗。$B$B我以前是在賣飲料的，但是黛西害我沒生意可做。是該開始新職業生涯的時候了，我想。', `MaleText_loc7`='No sé lo que estoy haciendo aquí. No tengo experiencia como negociador de contratos.$b$bSolía ganarme la vida sirviendo copas, pero Daisy me dejó sin trabajo. Supongo que es el momento de cambiar de carrera.' WHERE `ID`=41137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초루나와 티살리에게 보고서를 받았습니다. 이제 모든 게 확실해졌습니다...$B$B$n, 전 아비아나 님께서 곧 우리에게 돌아오실 거라 믿습니다. 하지만 그러려면 검은용 세스리아를 멈춰야 합니다!', `MaleText_loc4`='楚伦娜和希萨莉都已经把他们的报告给了我。现在我已经非常清楚了……$B$B$n，我相信艾维娜应该很快就会回来了，但我们必须阻止黑龙塞西莉亚！', `MaleText_loc5`='克魯娜和黎沙莉已經給了我他們的報告。在我看來，局勢已經非常明朗...$b$b$n，我相信艾維娜很快就會歸來，但我們必須先阻止黑龍賽瑟莉亞!', `MaleText_loc7`='Tanto Choluna como Thisalee me han informado. Ya lo veo todo claro...$b$b$n, creo que Aviana volverá a nosotros dentro de poco, ¡pero solo si logramos detener a la dragona negra Sethria!' WHERE `ID`=41138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기, 여기예요! 지금은 잠깐 몸을 숨기세요...', `FemaleText_loc4`='喂——这边！暂时别出现在视线之内……', `FemaleText_loc5`='噓─這裡!現在先不要曝露行蹤...', `FemaleText_loc7`='Psst, ¡aquí! Permanece fuera de la vista un momento...' WHERE `ID`=41139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 경주장에서 일하는 평범한 상품권 교환원이었어요. 헌데, 경주장이 사라졌으니, 백수가 돼버렸죠.$B$B이제 협상가가 되어보는 수밖에 없겠군요. 제 일을 좀 도와주실 수 있나요? 그들은 원유를 가지고 있어요!', `MaleText_loc4`='我以前就是个在赛道边上谋生的奖券商。可现在没比赛，也就没钱赚了。$B$B我现在正在努力学习谈判。你能帮我让这里的一切顺利进行吗？他们有油！', `MaleText_loc5`='我以前是個單純的賽場售票員。嘿，賽場已經沒了，所以工作也沒了。$B$B我現在想從事貿易協商方面的工作。你可以幫我一下嗎?他們有石油!', `MaleText_loc7`='Solía ser un simple interventor en la pista de carreras. Pues bien, como ya no hay pista, ya no hay trabajo.$b$bAhora estoy probando suerte en las negociaciones. ¿Podrías ayudarme a establecerme aquí? ¡Tienen petróleo!' WHERE `ID`=41140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부활 의식이 실패했습니다!', `MaleText_loc4`='复活仪式已失败！', `MaleText_loc5`='復活儀式失敗了!', `MaleText_loc7`='¡El ritual de resurrección ha fracasado!' WHERE `ID`=41141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크레이블 콜비어드가 기절했습니다. 지금 얼라이언스의 제안서를 훔치십시오!', `MaleText_loc4`='克拉维尔·浓须晕了。趁现在快去把联盟投标书偷到手！', `MaleText_loc5`='克拉維爾·濃鬚被擊暈了。趕快把聯盟的提案偷過來!', `MaleText_loc7`='Kravel Karbarbán está aturdido. ¡Aprovecha para robar la proposición de la Alianza!' WHERE `ID`=41142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 짓이냐?', `MaleText_loc4`='这是什么意思？', `MaleText_loc5`='這是什麼意思?', `MaleText_loc7`='¿Qué significa esto?' WHERE `ID`=41143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식이 끝날 때까지 %s|1을;를; 보호하십시오!', `MaleText_loc4`='保护%s直到仪式结束！', `MaleText_loc5`='保護%s直到儀式結束!', `MaleText_loc7`='¡Protege a %s hasta que se complete el ritual!' WHERE `ID`=41144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐하는 건가?!', `MaleText_loc4`='你在做什么？！', `MaleText_loc5`='你在做什麼?!', `MaleText_loc7`='¡¿Qué estás haciendo?!' WHERE `ID`=41145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주로관리인 제린이 기절했습니다. 지금 호드의 제안서를 훔치십시오!', `MaleText_loc4`='赛道管理员泽尔林晕了。趁现在快去把部落投标书偷到手！', `MaleText_loc5`='賽道管理員澤爾林被擊暈了。趕快把部落的提案偷過來!', `MaleText_loc7`='El maestro rastreador Zherin está aturdido. ¡Aprovecha para robar la proposición de la Horda!' WHERE `ID`=41146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공격받습니다! 보호하십시오!', `MaleText_loc4`='%s遭到了攻击！赶快保护他！', `MaleText_loc5`='%s正遭受攻擊!保護他!', `MaleText_loc7`='¡Están atacando a %s! ¡Protégelo!' WHERE `ID`=41147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 고난의 거리에 있는 시장을 가리킵니다.>', `MaleText_loc4`='<奥术守护者向贫民窟的集市指了指。>', `MaleText_loc5`='<秘法守護者指向陰鬱城的商店街。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia el bazar del Bajo Arrabal.>' WHERE `ID`=41148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린노어, 피의 의식을 시작하고 싶습니다.', `MaleText_loc4`='我准备开始鲜血仪式了，莱诺雷。', `MaleText_loc5`='我希望能開始進行血之祭儀，萊諾雷。', `MaleText_loc7`='Quiero iniciar el ritual de sangre, Lynnore.', `FemaleText_loc1`='린노어, 피의 의식을 시작하고 싶어요.', `FemaleText_loc4`='我准备开始鲜血仪式了，莱诺雷。', `FemaleText_loc5`='我希望能開始進行血之祭儀，萊諾雷。', `FemaleText_loc7`='Quiero iniciar el ritual de sangre, Lynnore.' WHERE `ID`=41149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 이들이 피의 마법을 어두운 데다 기억에서 사라진 기술이라 여겨 피합니다. 그런 점이나 다른 여러 면에서 악마의 마법과 겹치는 뚜렷한 특징이 몇 가지 있지요. 여기, 검은늪의 남은 악마 스컬지 무리 가운데에서 우리 피의 학문이 꽃피리라 믿습니다.', `FemaleText_loc4`='许多人把血魔法当作一门黑暗与失落的艺术，对其避之不及。从那以及许多其它方面来说，它与恶魔的法术有着某种共通的鲜明特性。在这里——在黑色沼泽恶魔肆虐的遗迹中，我们相信我们的血魔法一定能焕发光华。', `FemaleText_loc5`='血魔法對很多人來說是種黑暗和禁忌的魔法。在許多方面，它跟惡魔法術有很多雷同的地方。在這散佈惡魔和天譴軍殘骸的黑色沼澤，我們相信我們對血魔法的研究將會發光。', `FemaleText_loc7`='Muchos reniegan de la magia de sangre por considerarla un arte oscuro y olvidado. En ese sentido, y en muchos otros, comparte algunas características con la magia demoníaca. Aquí, en los restos arrasados por los demonios de La Ciénaga Negra, creemos que nuestro estudio de la sangre prosperará.' WHERE `ID`=41150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 병사들에게 싸우는 법을 가르칠 수는 있겠지만, 싸우고 싶어하는 법을 가르칠 순 없을 겁니다. 이 아래서라면 걱정하지 않아도 되는 일이지요. 제 부하들 하나하나가 모두 나가의 만행에 이를 갈고 있으니까 말입니다. 저 역시 별반 다르지 않고요.$b$b물 밖 세상과 접촉할 방법을 찾아야 합니다. 하지만 그 전에, 이 나가들과 "접촉"하고 싶군요. 앙갚음할 친구들이 좀 있지요.', `MaleText_loc4`='你能教一名士兵学会杀戮的技巧，可你不能教他杀戮的欲望。还好我们在这下面不用担心这一点。我的每一位弟兄都已经迫不及待地想要把那些纳迦撕成碎片，让他们为犯下的恶行付出代价，而我也一样。$B$B我们要想办法与上面建立联系，可在那之前，我想先跟那些纳迦“联系”一下。那些倒下的兄弟不能白死。', `MaleText_loc5`='你可以教導士兵如何殺人，但你無法教他想要殺人。這是我們在這不需要擔心的其中一件事。我的每一個孩子都等不及要剝下那些納迦身上的皮，讓他們為所做的付出代價，我自己跟他們的想法也是一致的。$B$B我們必須找到與地面上取得聯絡的方法，但在此之前，我想先跟那些納迦「聯絡」一下。我們有許多兄弟之仇需要報。', `MaleText_loc7`='Puedes enseñar a un soldado a matar, pero no puedes hacer que quiera matar. De eso no tenemos que preocuparnos aquí abajo. Todos y cada uno de mis muchachos ansían hacer pedazos a esos nagas por lo que nos hicieron, y no puedo decir que yo opine lo contrario.$B$BNecesitamos encontrar la forma de entrar en contacto con la superficie, pero antes de eso, quiero entrar en "contacto" con esos nagas. Debemos vengar a nuestros hermanos.' WHERE `ID`=41151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 조각을 좀 보여주시겠어요, 제독님? 조각의 힘이 동굴 저편에서 발산되는 게 느껴져요.', `FemaleText_loc4`='让我看看那碎片，可以吗将军？我能感觉到它的能量正从洞穴的另一侧放射出来。', `FemaleText_loc5`='讓我們看看那個碎片，可以嗎，上將?我可以感覺到它的力量正從洞穴的另一面照射出來。', `FemaleText_loc7`='¿Me dejas echarle un vistazo a ese fragmento, Almirante? Podía sentir cómo irradiaba su poder desde el otro extremo de la cueva.' WHERE `ID`=41152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 가져가시지요.', `MaleText_loc4`='当然。全听你的。', `MaleText_loc5`='當然，請便。', `MaleText_loc7`='Claro. Es todo tuyo.' WHERE `ID`=41153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다.', `FemaleText_loc4`='谢谢你。', `FemaleText_loc5`='謝謝你。', `FemaleText_loc7`='Gracias.' WHERE `ID`=41154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 환영을 봤습니다.', `MaleText_loc4`='你已经目睹过这景象。', `MaleText_loc5`='你已經親眼目睹了這個景象。', `MaleText_loc7`='Ya has contemplado esta visión.', `FemaleText_loc1`='이미 환영을 봤습니다.', `FemaleText_loc4`='你已经目睹过这景象。', `FemaleText_loc5`='你已經親眼目睹了這個景象。', `FemaleText_loc7`='Ya has contemplado esta visión.' WHERE `ID`=41155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영을 보려면 나즈자르 여전사와 동화되어야 합니다.', `MaleText_loc4`='你需要进一步使自己与纳兹夏尔女武士谐调一致，才能分享这景象。', `MaleText_loc5`='你必須和納茲賈爾戰鬥仕女將你的狀況調整到更好來參與這個景象。', `MaleText_loc7`='Debes armonizarte más con la doncella de batalla Naz''jar para participar en esta visión.', `FemaleText_loc1`='환영을 보려면 나즈자르 여전사와 동화되어야 합니다.', `FemaleText_loc4`='你需要进一步使自己与纳兹夏尔女武士谐调一致，才能分享这景象。', `FemaleText_loc5`='你必須和納茲賈爾戰鬥仕女將你的狀況調整到更好來參與這個景象。', `FemaleText_loc7`='Debes armonizarte más con la doncella de batalla Naz''jar para participar en esta visión.' WHERE `ID`=41156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 장막 생성기를 끄자 세스리아의 새끼용이 드러납니다!', `MaleText_loc4`='关闭暗影遮罩之后，一只塞西莉亚的雏龙出现了！', `MaleText_loc5`='關閉暗影遮罩後出現了一隻賽瑟莉亞的幼龍!', `MaleText_loc7`='¡Al anular el manto de las Sombras descubres una de las proles de Sethria!' WHERE `ID`=41157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이건 무슨 술책이지?', `MaleText_loc4`='我……这是什么巫术？', `MaleText_loc5`='我...這是何種法術?', `MaleText_loc7`='¿Qué... qué brujería es esta?', `FemaleText_loc1`='이... 이건 무슨 술책이지?', `FemaleText_loc4`='我……这是什么巫术？', `FemaleText_loc5`='我...這是何種法術?', `FemaleText_loc7`='¿Qué... qué brujería es esta?' WHERE `ID`=41158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 한 일을 후회하게 해 주마!', `MaleText_loc4`='你会为你的行为感到后悔的！', `MaleText_loc5`='你會後悔你這樣做的!', `MaleText_loc7`='¡Te arrepentirás de tus actos!', `FemaleText_loc1`='네가 한 일을 후회하게 해 주마!', `FemaleText_loc4`='你会为你的行为感到后悔的！', `FemaleText_loc5`='你會後悔你這樣做的!', `FemaleText_loc7`='¡Te arrepentirás de tus actos!' WHERE `ID`=41159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내게는 힘이 없다. 그 고약한 장치에 묶여버리는 바람에.', `MaleText_loc4`='我……我失去控制了。被你的疯狂装置所束缚。', `MaleText_loc5`='我...我無法控制。因為你那些該死裝置。', `MaleText_loc7`='No... No tengo el control. Estoy aprisionado por tu artilugio infernal.', `FemaleText_loc1`='내... 내게는 힘이 없다. 그 고약한 장치에 묶여버리는 바람에.', `FemaleText_loc4`='我……我失去控制了。被你的疯狂装置所束缚。', `FemaleText_loc5`='我...我無法控制。因為你的地獄裝置。', `FemaleText_loc7`='No... No tengo el control. Estoy aprisionado por tu artilugio infernal.' WHERE `ID`=41160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우린 포르바에게 뭐라고 하지?', `MaleText_loc4`='我们要跟弗巴说什么？', `MaleText_loc5`='我們應該跟佛巴說什麼?', `MaleText_loc7`='¿Qué le vamos a decir a Forba?' WHERE `ID`=41161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 참! 맥주통을 감시하기로 한 사람은 자네잖아!', `MaleText_loc4`='哈！桶本该是归你看管的！', `MaleText_loc5`='哈!你是應該要負責看管桶子的人!', `MaleText_loc7`='¡Ja! ¡Se supone que tú tenías que vigilar el barril!' WHERE `ID`=41162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 그때 술에 절어 있었지 않나!', `MaleText_loc4`='你在工作中喝醉了！', `MaleText_loc5`='你在工作時喝醉了!', `MaleText_loc7`='¡Estabas bebiendo en el trabajo!' WHERE `ID`=41163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리라니? 그걸 걱정해야 할 사람은 자네라고! 왜 나까지 걸고넘어지나!', `MaleText_loc4`='我们？应该是你要跟弗巴说什么才对！', `MaleText_loc5`='我們?應該是你要跟佛巴說什麼吧!', `MaleText_loc7`='¿Nosotros? ¡Mejor qué le vas a decir TÚ a Forba!' WHERE `ID`=41164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크를 감시하기로 한 사람은 자네였지!', `MaleText_loc4`='你才是负责防范兽人的人！', `MaleText_loc5`='負責看有沒有獸人的那個人應該是你!', `MaleText_loc7`='¡Se suponía que tú ibas a vigilar por si venían orcos!' WHERE `ID`=41165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 그때 술떡이 돼 있었잖아!', `MaleText_loc4`='你也是！', `MaleText_loc5`='你也是!', `MaleText_loc7`='¡Y tú!' WHERE `ID`=41166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이겁니다! 아비아나의 알을 찾아내셨군요! 제가 지원 병력을 데려올 때까지 알을 안전하게 지켜 주세요.', `MaleText_loc4`='就是它！我们找到艾维娜的卵了！你保护它，我去找帮手。', `MaleText_loc5`='就是這個!你找到艾維娜之卵了!在我去求救的時候保護它的安全。', `MaleText_loc7`='¡Lo has conseguido! ¡Has encontrado el huevo de Aviana! Protégelo mientras busco ayuda.' WHERE `ID`=41167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 장막 생성기를 끄자 아비아나의 알이 드러납니다!', `MaleText_loc4`='关闭暗影遮罩之后，艾维娜的卵显现了出来！', `MaleText_loc5`='解除暗影遮罩使艾維娜之卵現形了!', `MaleText_loc7`='¡Al anular el manto de las Sombras descubres el Huevo de Aviana!' WHERE `ID`=41168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알을 보호하십시오!', `MaleText_loc4`='保护好这只卵！', `MaleText_loc5`='保護艾維娜之卵!', `MaleText_loc7`='¡Defiende el huevo!' WHERE `ID`=41169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 좀 도와주세요. 여기 이 게을러터진 드워프들 중 한 명에게라도 일을 시킬 수 있다면, 다른 이들을 시퍼렇게 멍이 들도록 두들겨 패는 일을 시킬 거예요!$B$B지금 할 일이 산더미란 말이에요!', `FemaleText_loc4`='请帮帮我，要是这群懒虫能有一个叫得动，我就会让他回去工作，再把其它人打得鼻青脸肿！$B$B我们在这儿有工作要做！', `FemaleText_loc5`='那就幫我，如果我可以讓這些懶惰的傢伙裡其中的一個勤勞點，我會讓他負責將其他的打成豬頭!$B$B我們還有很多工作要做啊!', `FemaleText_loc7`='Créeme, si consigo que uno solo de estos vagos se ponga en pie, ¡lo voy a mandar a darles una paliza de escándalo a todos los demás!$b$b¡Hay TRABAJO por hacer!' WHERE `ID`=41170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어보게나. 자네... 지질 조사를 하는 게 얼마나 힘든 일인지 알기나 하나? 엄밀함과 정확함이 요구되는 일이란 말이지!$B$B그리고 술에 취하면 더 힘들어지고 말이야.', `MaleText_loc4`='听着，你……你知道进行地质勘察是多么困难吗？这是精确、精密的工作！$B$B而且当你喝醉时，就更是难上加难了。', `MaleText_loc5`='聽著，你...你知道要籌備一次地質堪察活動有多困難嗎?那是最精密的工作!$B$B由其是當你喝醉的時候。', `MaleText_loc7`='Escucha... ¿tienes idea de lo difícil que es llevar a cabo una investigación geológica? ¡Es un trabajo preciso y agotador!$b$bY es aún más difícil cuando vas borracho.' WHERE `ID`=41171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 덕에 궁지에서 벗어났습니다.', `MaleText_loc4`='你可真是个大救星。', `MaleText_loc5`='你是生命拯救者。', `MaleText_loc7`='Eres una bendición.', `FemaleText_loc1`='당신 덕에 궁지에서 벗어났어요.', `FemaleText_loc4`='你可真是个大救星。', `FemaleText_loc5`='你是生命拯救者。', `FemaleText_loc7`='Eres una bendición.' WHERE `ID`=41172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다.', `MaleText_loc4`='多谢。', `MaleText_loc5`='謝謝。', `MaleText_loc7`='Gracias.', `FemaleText_loc1`='고맙습니다.', `FemaleText_loc4`='多谢。', `FemaleText_loc5`='謝謝。', `FemaleText_loc7`='Gracias.' WHERE `ID`=41173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올 것이 왔군요.', `MaleText_loc4`='是时候了。', `MaleText_loc5`='是時候了。', `MaleText_loc7`='Ya era hora.', `FemaleText_loc1`='올 것이 왔군요.', `FemaleText_loc4`='是时候了。', `FemaleText_loc5`='是時候了。', `FemaleText_loc7`='Ya era hora.' WHERE `ID`=41174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 잘해주시기 바랍니다.', `MaleText_loc4`='保持努力。', `MaleText_loc5`='再接再勵。', `MaleText_loc7`='Sigue así.', `FemaleText_loc1`='계속 잘해주시기 바랍니다.', `FemaleText_loc4`='保持努力。', `FemaleText_loc5`='再接再勵。', `FemaleText_loc7`='Sigue así.' WHERE `ID`=41175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제때에 오셨군요. 화살이 거의 떨어져 가던 참이었습니다.', `MaleText_loc4`='真及时——我差点就弹尽粮绝了。', `MaleText_loc5`='來的好不如來的巧，我正準備要出門。', `MaleText_loc7`='Llegas a tiempo. Estaba a punto de desmayarme.', `FemaleText_loc1`='제때에 오셨군요. 화살이 거의 떨어져 가던 참이었어요.', `FemaleText_loc4`='真及时——我差点就弹尽粮绝了。', `FemaleText_loc5`='來的好不如來的巧，我正準備要出門。', `FemaleText_loc7`='Llegas a tiempo. Estaba a punto de desmayarme.' WHERE `ID`=41176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 공격 빈도가 잦아지고 있습니다. 계속 이동하시는 게 좋겠습니다.', `MaleText_loc4`='他们的攻击日渐频繁了。你最好别停下。', `MaleText_loc5`='他們的攻擊次數越來越頻繁了。你最好繼續移動。', `MaleText_loc7`='Los ataques cada vez son más frecuentes. No te pares.', `FemaleText_loc1`='놈들의 공격 빈도가 잦아지고 있습니다. 계속 이동하시는 게 좋겠어요.', `FemaleText_loc4`='他们的攻击日渐频繁了。你最好别停下。', `FemaleText_loc5`='他們的攻擊次數越來越頻繁了。你最好繼續移動。', `FemaleText_loc7`='Los ataques cada vez son más frecuentes. No te pares.' WHERE `ID`=41177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 엄호하겠습니다. 습격에 성공하시길 바랍니다!', `MaleText_loc4`='我们会掩护你的。愿攻击一切顺利！', `MaleText_loc5`='我們會掩護你。祝你襲擊順利!', `MaleText_loc7`='Te cubriremos. ¡Buena suerte con el asalto!', `FemaleText_loc1`='저희가 엄호하겠습니다. 습격에 성공하시길 바랍니다!', `FemaleText_loc4`='我们会掩护你的。愿攻击一切顺利！', `FemaleText_loc5`='我們會掩護你。祝你襲擊順利!', `FemaleText_loc7`='Te cubriremos. ¡Buena suerte con el asalto!' WHERE `ID`=41178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전히 지원을 해 주신다니 고맙습니다!', `MaleText_loc4`='他们仍在背后支持我们，这可真是个好消息。谢谢你！', `MaleText_loc5`='很高興知道他們仍然在掩護我們。謝謝!', `MaleText_loc7`='Es bueno saber que nos cubren las espaldas. ¡Gracias!', `FemaleText_loc1`='여전히 지원을 해 주신다니 고마워요!', `FemaleText_loc4`='他们仍在背后支持我们，这可真是个好消息。谢谢你！', `FemaleText_loc5`='很高興知道他們仍然在掩護我們。謝謝!', `FemaleText_loc7`='Es bueno saber que nos cubren las espaldas. ¡Gracias!' WHERE `ID`=41179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공기를 들이마시려고 헐떡거립니다.', `MaleText_loc4`='%s大口喘息着。', `MaleText_loc5`='%s重重地喘著氣。', `MaleText_loc7`='%s toma aire.', `FemaleText_loc1`='%s|1이;가; 공기를 들이마시려고 헐떡거립니다.', `FemaleText_loc4`='%s大口喘息着。', `FemaleText_loc5`='%s重重地喘著氣。', `FemaleText_loc7`='%s toma aire.' WHERE `ID`=41180;
