UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로필리언 데인은 더 깊숙한 곳에 있네. 이 길만 따라가게.', `MaleText_loc4`='罗菲利安·达恩就在矿洞深处。跟着这些踪迹走就行了。', `MaleText_loc5`='羅菲里安·丹恩就在礦坑的深處。跟著這些痕跡走就可以了。', `MaleText_loc7`='Rofilian Dane está más allá en el interior de la mina. Solo tienes que seguir estas vías.', `FemaleText_loc1`='로필리언 데인은 더 깊숙한 곳에 있네. 이 길만 따라가게.', `FemaleText_loc4`='罗菲利安·达恩就在矿洞深处。跟着这些踪迹走就行了。', `FemaleText_loc5`='羅菲里安·丹恩就在礦坑的深處。跟著這些痕跡走就可以了。', `FemaleText_loc7`='Rofilian Dane está más allá en el interior de la mina. Solo tienes que seguir estas vías.' WHERE `ID`=41182;
