UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 말하겠는데... 움직이는 상자야. 기계공학자들이 이번에는 정말로 만들어냈나 보군!', `MaleText_loc4`='我非常确定……一个移动的盒子。工程师们这次真的做到了！', `MaleText_loc5`='我是有要求一個...會動的盒子。工程師們這次真的做到了!', `MaleText_loc7`='¡Por mi honor! Una caja que anda. ¡Esta vez los ingenieros se han superado!', `FemaleText_loc1`='분명히 말하겠는데... 움직이는 상자야. 기계공학자들이 이번에는 정말로 만들어냈나 봐!', `FemaleText_loc4`='我非常确定……一个移动的盒子。工程师们这次真的做到了！', `FemaleText_loc5`='我是有要求一個...會動的盒子。工程師們這次真的做到了!', `FemaleText_loc7`='¡Por mi honor! Una caja que anda. ¡Esta vez los ingenieros se han superado!' WHERE `ID`=41189;
