UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 누군지 안다, $n! 너처럼 추잡한 놈에게 신성한 불꽃을 내줄 순 없지!', `MaleText_loc4`='我知道你是谁，$n！我才不会把神圣烈焰交给像你这样恶心的饭桶！', `MaleText_loc5`='我知道你是誰，$n!我不會放棄神聖之火並把它交給你這種骯髒的垃圾的。', `MaleText_loc7`='¡Sé quién eres, $n! ¡No dejaré que un saco de carne asqueroso como tú se quede con la llama sacra!' WHERE `ID`=41191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 밑에 굉장한 물질이 묻혀 있어요. 굉장하지요! 모든 걸 대체할 수 있어요. 대체품을 대체할 수도 있죠. 뭐든지 가능하답니다!', `MaleText_loc4`='这里有令人惊叹的材料。任何工程材料和替换件都能找到代用品。一切皆有可能！', `MaleText_loc5`='奇妙的材料。太棒了!一切的代替品。代替品的代替品。這世上沒有不可能的事!', `MaleText_loc7`='¡Hay materiales increíbles aquí abajo! ¡Increíbles! Recambios para todo. Recambios de los recambios. ¡Todo es posible!' WHERE `ID`=41192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계단지를 습격할 준비가 되었습니다.', `MaleText_loc4`='我已经准备好对平台发起攻击了。', `MaleText_loc5`='我準備好對該地進行攻擊了。', `MaleText_loc7`='Estoy listo para comenzar el asalto al bancal.', `FemaleText_loc1`='계단지를 습격할 준비가 되었어요.', `FemaleText_loc4`='我已经准备好对平台发起攻击了。', `FemaleText_loc5`='我準備好對該地進行攻擊了。', `FemaleText_loc7`='Estoy lista para comenzar el asalto al bancal.' WHERE `ID`=41193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펑펑 터뜨리세요!', `MaleText_loc4`='把他们炸烂！', `MaleText_loc5`='炸爛他們!', `MaleText_loc7`='¡Hazlos saltar por los aires!' WHERE `ID`=41194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 저 상자가 혼자서 걸어오는 거야? 내가 돌아버렸나? 어서, 누가 나 좀 꼬집어봐!', `MaleText_loc4`='那盒子是在自己移动吗？还是我发疯了？赶快，去个人检查一下！', `MaleText_loc5`='那個盒子是自己在移動嗎?我是不是瘋了?快點，誰去檢查一下那隻金絲雀!', `MaleText_loc7`='¿Esa caja anda sola, o me estoy volviendo loco? ¡Rápido, que alguien vaya a ver al canario!' WHERE `ID`=41195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 전보다 더 노출되었습니다.$b$b서둘러 안전한 피난처를 찾아야 합니다!', `MaleText_loc4`='这地方让我们比先前更加暴露了，$r。$b$b我们必须尽快找到安全的藏身处！', `MaleText_loc5`='這裡...比之前的地方還要危險，$r。$b$b我們必須趕快找一個更安全的避難所!', `MaleText_loc7`='Aquí estamos aún más al descubierto que antes, $r.$b$b¡Debemos encontrar un refugio seguro cuanto antes!' WHERE `ID`=41196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 동료를 찾고 나가가 이곳에 온 목적이 무엇인지도 밝혀내야 합니다.$b$b하지만 먼저, 더 안전한 곳을 찾아야 합니다.', `MaleText_loc4`='我们必须集结你的同伴，探明纳迦在这里的真正目的。$b$b不过首先，我们得先找个更为安全的地方。', `MaleText_loc5`='我們必須找到你的盟友並瞭解出現在此地的納迦擁有何種動機。$b$b但首先，我們必須尋找一個更安全的地方。', `MaleText_loc7`='Debemos encontrar a tus aliados y descubrir los planes de los nagas para esta región.$b$bPero antes debemos encontrar un lugar más seguro.' WHERE `ID`=41197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이곳 나가를 제대로 판단하지 못했나보군요.$b$b저렇게 조직적이고 잘 훈련된 나가는 이제껏 본 적이 없습니다.', `MaleText_loc4`='我觉得我们对纳迦在此地出现的原因了解得远远不够。$b$b我以前从没见过他们像现在这么富于组织性和纪律性。', `MaleText_loc5`='我感覺我們看到的只是表面上一小部份的納迦。$b$b我從沒看過他們那麼地訓練有素。', `MaleText_loc7`='Tengo la impresión de que no alcanzamos a comprender realmente lo que ocurre con los nagas en este lugar.$b$bAntes nunca los había visto tan organizados ni tan disciplinados.' WHERE `ID`=41198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을... 사라졌어. 가족 사라졌어. 나가 가져갔어... 전부 다.', `MaleText_loc4`='村庄……消失。家庭消失。纳迦……带走……一切。', `MaleText_loc5`='村子...沒了。家庭...沒了。納迦...害的。', `MaleText_loc7`='La aldea ha... desaparecido. Mi familia también. Los nagas se lo han llevado... todo.' WHERE `ID`=41199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀록, 세바인의 아뮬렛 쥐고 있는 거 안다. 난 그 아뮬렛이 필요해.', `MaleText_loc4`='鱼人，我知道瑟温妮的护符在你手里。我需要它。', `MaleText_loc5`='魚人，我知道你擁有瑟溫妮的護符。我需要它。', `MaleText_loc7`='Múrloc, sé que tienes el amuleto de Sevine. Lo necesito.', `FemaleText_loc1`='멀록, 세바인의 아뮬렛 쥐고 있는 거 알아. 난 그 아뮬렛이 필요해.', `FemaleText_loc4`='鱼人，我知道瑟温妮的护符在你手里。我需要它。', `FemaleText_loc5`='魚人，我知道你擁有瑟溫妮的護符。我需要它。', `FemaleText_loc7`='Múrloc, sé que tienes el amuleto de Sevine. Lo necesito.' WHERE `ID`=41200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뮬렛 절대 못 가져간다! 그롤 영원히 산다!', `MaleText_loc4`='你别想拿走护符！戈洛尔永生！', `MaleText_loc5`='你永遠都不會拿到護符!戈洛爾萬歲!', `MaleText_loc7`='¡Nunca tendrás amuleto! ¡Grol vivir para siempre!' WHERE `ID`=41201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤에서 무슨 소리가 납니다.', `MaleText_loc4`='你听到背后传来了一声噪音。', `MaleText_loc5`='你聽到背後傳來了聲音。', `MaleText_loc7`='Oyes un sonido detrás de ti.' WHERE `ID`=41202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롤 너 죽인다!', `MaleText_loc4`='戈洛尔会杀了你！', `MaleText_loc5`='戈洛爾會殺了你!', `MaleText_loc7`='¡Grol te matará!' WHERE `ID`=41203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐야? 가짜잖아! 갈래발굽일족이여, $n|1과;와; 노움이 우릴 속이려 했다. 처치해라!', `MaleText_loc4`='这是什么？假的！裂蹄，$n还有那群侏儒想要耍我们。给我杀了$g他:她;！', `MaleText_loc5`='這是什麼?假的!裂蹄，$n和地精們想耍我們。殺了$g他:她;!', `MaleText_loc7`='¿Qué es esto? ¡FALSO! Pezuña Quebrada, $n y los gnomos han intentado engañarnos. ¡$gMatadlo:Matadla;!' WHERE `ID`=41204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐야? 가짜잖아! 갈래발굽일족이여, $n|1과;와; 노움이 우릴 속이려 했다. 처치해라!', `MaleText_loc4`='这是什么？假的！裂蹄，$n还有那群地精想要耍我们。给我杀了$g他:她;！', `MaleText_loc5`='這是什麼?假的!裂蹄，$n和哥布林們想耍我們。殺了$g他:她;!', `MaleText_loc7`='¿Qué es esto? ¡FALSO! Pezuña Quebrada, $n y los goblins han intentado engañarnos. ¡$gMatadlo:Matadla;!' WHERE `ID`=41205;
