UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을 하는 거냐?', `MaleText_loc4`='你觉得你在干什么？', `MaleText_loc5`='你在做什麼?', `MaleText_loc7`='¿Qué crees que haces?', `FemaleText_loc1`='무슨 짓을 하는 거냐?', `FemaleText_loc4`='你觉得你在干什么？', `FemaleText_loc5`='你在做什麼?', `FemaleText_loc7`='¿Qué crees que haces?' WHERE `ID`=41207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 도둑놈아, 썩 꺼지지 못해!', `MaleText_loc4`='滚开，部落的毛贼！', `MaleText_loc5`='滾，部落小偷!', `MaleText_loc7`='¡Largo, ladrón de la Horda!', `FemaleText_loc1`='호드 도둑놈아, 썩 꺼지지 못해!', `FemaleText_loc4`='滚开，部落的毛贼！', `FemaleText_loc5`='滾，部落小偷!', `FemaleText_loc7`='¡Largo, ladrón de la Horda!' WHERE `ID`=41208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한낱 벌레 같은 것이! 널 처단하고 제단도 불태우겠다!', `MaleText_loc4`='虫子！消灭了你们，我就会把你们的神殿烧成焦土！', `MaleText_loc5`='蟲子!等我解決你們，我會把你們的祭壇燒為灰燼!', `MaleText_loc7`='¡Insectos! ¡Cuando acabe con ustedes, haré cenizas su santuario!' WHERE `ID`=41209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 벌었을 뿐.. 목숨은 부지하지 못할 것이다... 부화장이 남아 있으니...', `MaleText_loc4`='你们拖延了时间……但仍难逃一死……我的孵化所还在……', `MaleText_loc5`='你們爭取到時間...但你們遲早要死...我的巢還在...', `MaleText_loc7`='Salvaron tiempo... pero no vidas... mi criadero prevalece…' WHERE `ID`=41210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 가고 있습니다, $n 님! 세스리아의 주의를 끄시는 동안, 저희가 돌아서 공격을 하겠습니다.', `MaleText_loc4`='我们来了，$n！在我们准备发动迂回攻击时，帮我们拖住她。', `MaleText_loc5`='我們來了，$n!纏住她，讓我們能繞到後方攻擊。', `MaleText_loc7`='¡Ya llegamos, $n! Mantenla ocupada mientras la rodeamos para atacar.' WHERE `ID`=41211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변은 우리 모두에게 정말 힘든 일이었지만, 그럭저럭 살아나가고 있습니다.$B$B당신도 소매를 걷어붙이고 주어진 일에만 충실해야 합니다.', `MaleText_loc4`='这对我们所有人来说都很困难，可我们正在勉强支撑。$B$B你要做的就是挽起袖子，做你该做的事。', `MaleText_loc5`='這對我們來說都並不容易，但我們做到了。$B$B你必須要下定決心完成該做的事情。', `MaleText_loc7`='Es difícil para todos, pero nos las arreglamos.$b$bA veces toca resignarse y hacer lo que hay que hacer.' WHERE `ID`=41212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈래발굽 언덕 켄타우로스가 원유 굴착 장치를 파괴했습니다!', `MaleText_loc4`='裂蹄高地的半人马摧毁了钻油机！', `MaleText_loc5`='裂蹄陵地的半人馬摧毀了鑽油機!', `MaleText_loc7`='¡Los centauros de las Cumbres Pezuña Quebrada han destruido la plataforma petrolífera!' WHERE `ID`=41213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<부상당한 병사의 고통스러운 신음이 물결에 일그러집니다.>', `MaleText_loc4`='<这名士兵痛苦的呻吟声在水中变得有些扭曲。>', `MaleText_loc5`='<受傷士兵痛苦的叫聲被水的聲音給扭曲了。>', `MaleText_loc7`='<El agua distorsiona un poco los gemidos de dolor del soldado herido.>', `FemaleText_loc1`='<부상당한 병사의 고통스러운 신음 소리가 물결에 일그러집니다.>', `FemaleText_loc4`='<这名士兵痛苦的呻吟声在水中变得有些扭曲。>', `FemaleText_loc5`='<受傷士兵痛苦的叫聲被水的聲音給扭曲了。>', `FemaleText_loc7`='<El agua distorsiona un poco los gemidos de dolor del soldado herido.>' WHERE `ID`=41214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<부상당한 병사는 아직 숨을 쉬는 것 같습니다. 고맙게도, 그의 공기 방울은 아직 멀쩡합니다.>', `MaleText_loc4`='<这名受伤的士兵似乎还有呼吸。谢天谢地，他的魔法气泡还没掉。>', `MaleText_loc5`='<受傷的士兵看來還有呼吸。還好，他的泡泡還沒有破掉。>', `MaleText_loc7`='<Parece que el soldado herido todavía respira. Afortunadamente, su burbuja permanece intacta.>', `FemaleText_loc1`='<부상당한 병사는 아직 숨을 쉬는 것 같습니다. 고맙게도, 그의 공기 방울은 아직 멀쩡합니다.>', `FemaleText_loc4`='<这名受伤的士兵似乎还有呼吸。谢天谢地，她的魔法气泡还没掉。>', `FemaleText_loc5`='<受傷的士兵看來還有呼吸。還好，她的泡泡還沒有破掉。>', `FemaleText_loc7`='<Parece que el soldado herido todavía respira. Afortunadamente, su burbuja permanece intacta.>' WHERE `ID`=41215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<병사 옆구리의 베인 상처가 무척 아파 보입니다.>', `MaleText_loc4`='<这名士兵的体侧有一道深得可怕的伤口。>', `MaleText_loc5`='<士兵的側面有個看起來非常痛的傷口。>', `MaleText_loc7`='<El soldado tiene un corte profundo de aspecto doloroso en un costado.>', `FemaleText_loc1`='<병사 옆구리의 베인 상처가 무척 아파 보입니다.>', `FemaleText_loc4`='<这名士兵的体侧有一道深得可怕的伤口。>', `FemaleText_loc5`='<士兵的側面有個看起來非常痛的傷口。>', `FemaleText_loc7`='<El soldado tiene un corte profundo de aspecto doloroso en un costado.>' WHERE `ID`=41216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 병사는 나가의 의심을 풀고자 위장했던 것으로 보입니다. 그래서 살 수 있었던 것 같습니다.>', `MaleText_loc4`='<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了他的命。>', `MaleText_loc5`='<看起來這個士兵是裝的，想消除納迦的懷疑。這很可能救了他一命。>', `MaleText_loc7`='<Parece que este soldado está fingiendo para no despertar las sospechas de los nagas. Puede que eso le haya salvado la vida.>', `FemaleText_loc1`='<이 병사는 나가의 의심을 풀고자 위장했던 것으로 보입니다. 그래서 살 수 있었던 것 같습니다.>', `FemaleText_loc4`='<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了她的命。>', `FemaleText_loc5`='<看起來這個士兵是裝的，想消除納迦的懷疑。這很可能救了她一命。>', `FemaleText_loc7`='<Parece que este soldado está fingiendo para no despertar las sospechas de los nagas. Puede que eso le haya salvado la vida.>' WHERE `ID`=41217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가운 분이로군요.', `MaleText_loc4`='见到你很高兴。', `MaleText_loc5`='很高興見到你。', `MaleText_loc7`='Dichosos los ojos que te ven.', `FemaleText_loc1`='반가운 분이로군요.', `FemaleText_loc4`='见到你很高兴。', `FemaleText_loc5`='很高興見到你。', `FemaleText_loc7`='Dichosos los ojos que te ven.' WHERE `ID`=41218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것을 잃어버리는 건 사형 선고와 같다고 했지요. 제독님이 틀렸다는 걸 보여주셔서 고맙습니다.', `MaleText_loc4`='我被告知弄丢坐骑就要等着受死。谢谢你证明将军是错的。', `MaleText_loc5`='我被告知說一旦喪失坐騎就會被判死刑。謝謝你證明上將是錯的。', `MaleText_loc7`='Me dijeron que perder la montura era una sentencia de muerte. Gracias por demostrarle al almirante que se equivocaba.', `FemaleText_loc1`='탈것을 잃어버리는 건 사형 선고와 같다고 했지요. 제독님이 틀렸다는 걸 보여주셔서 고마워요.', `FemaleText_loc4`='我被告知弄丢坐骑就要等着受死。谢谢你证明将军是错的。', `FemaleText_loc5`='我被告知說一旦喪失坐騎就會被判死刑。謝謝你證明上將是錯的。', `FemaleText_loc7`='Me dijeron que perder la montura era una sentencia de muerte. Gracias por demostrarle al almirante que se equivocaba.' WHERE `ID`=41219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 정말 멋지고도 멋진 분이십니다.', `MaleText_loc4`='见到你实在是太好了，太好了，朋友。', `MaleText_loc5`='看到你真是令人無比高興，朋友。', `MaleText_loc7`='Me alegro mucho, mucho, de verte, camarada.', `FemaleText_loc1`='당신은 정말 멋지고도 멋진 분이세요.', `FemaleText_loc4`='见到你实在是太好了，太好了，朋友。', `FemaleText_loc5`='看到你真是令人無比高興，朋友。', `FemaleText_loc7`='Me alegro mucho, mucho, de verte, camarada.' WHERE `ID`=41220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 사람들은 모두 무사한가요? 습격은 성공했고요?', `MaleText_loc4`='其他人都成功了吗？进攻胜利了吗？', `MaleText_loc5`='其他人也辦到了嗎?襲擊成功了嗎?', `MaleText_loc7`='¿Todos los demás han sobrevivido? ¿Ha tenido éxito el ataque?', `FemaleText_loc1`='다른 사람들은 모두 무사한가요? 습격은 성공했고요?', `FemaleText_loc4`='其他人都成功了吗？进攻胜利了吗？', `FemaleText_loc5`='其他人也辦到了嗎?襲擊成功了嗎?', `FemaleText_loc7`='¿Todos los demás han sobrevivido? ¿Ha tenido éxito el ataque?' WHERE `ID`=41221;
