UPDATE `locales_broadcast_text` SET `MaleText_loc1`='합류 지점에 거의 다 왔습니다. 이제 가셔도 됩니다.', `MaleText_loc4`='通往会合点的路基本已经畅通无阻了。你应该动身了。', `MaleText_loc5`='往會合點的路大部份是暢通的。你應該上路了。', `MaleText_loc7`='El camino hacia el punto de encuentro está despejado en su mayor parte. Deberías ponerte en marcha.', `FemaleText_loc1`='합류 지점에 거의 다 왔습니다. 이제 가셔도 됩니다.', `FemaleText_loc4`='通往会合点的路基本已经畅通无阻了。你应该动身了。', `FemaleText_loc5`='往會合點的路大部份是暢通的。你應該上路了。', `FemaleText_loc7`='El camino hacia el punto de encuentro está despejado en su mayor parte. Deberías ponerte en marcha.' WHERE `ID`=41223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번 말씀하실 필요는 없습니다.', `MaleText_loc4`='你不用告诉我两遍。', `MaleText_loc5`='跟我說一次就好了。', `MaleText_loc7`='No me lo digas dos veces.', `FemaleText_loc1`='두 번 말씀하실 필요는 없어요.', `FemaleText_loc4`='你不用告诉我两遍。', `FemaleText_loc5`='跟我說一次就好了。', `FemaleText_loc7`='No me lo digas dos veces.' WHERE `ID`=41224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*정확하게* 제가 듣고 싶었던 말씀입니다. 고맙습니다.', `MaleText_loc4`='这“正是”我想要听到的。谢谢你。', `MaleText_loc5`='這就是我想聽到的。謝謝。', `MaleText_loc7`='Eso es exactamente lo que quería oír. Gracias.', `FemaleText_loc1`='*정확하게* 제가 듣고 싶었던 말씀이에요. 고마워요.', `FemaleText_loc4`='这“正是”我想要听到的。谢谢你。', `FemaleText_loc5`='這就是我想聽到的。謝謝。', `FemaleText_loc7`='Eso es exactamente lo que quería oír. Gracias.' WHERE `ID`=41225;
