UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 왔습니다. 고맙습니다.', `MaleText_loc4`='我没问题了。谢谢你。', `MaleText_loc5`='我非常喜歡，謝謝。', `MaleText_loc7`='Ya lo he superado. Gracias.', `FemaleText_loc1`='거의 다 왔어요. 고마워요.', `FemaleText_loc4`='我没问题了。谢谢你。', `FemaleText_loc5`='我非常喜歡，謝謝。', `FemaleText_loc7`='Ya lo he superado. Gracias.' WHERE `ID`=41227;
