UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 더할 나위 없이 좋은 분이시군요.', `MaleText_loc4`='你可真是个难得一见的大好人。', `MaleText_loc5`='你好的讓人不太敢相信。', `MaleText_loc7`='Eres demasiado $gbueno:buena; para ser verdad.', `FemaleText_loc1`='당신 더할 나위 없이 좋은 분이시군요.', `FemaleText_loc4`='你可真是个难得一见的大好人。', `FemaleText_loc5`='你好的讓人不太敢相信。', `FemaleText_loc7`='Eres demasiado $gbueno:buena; para ser verdad.' WHERE `ID`=41229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광스러운 전투였습니다. 인정하죠.', `MaleText_loc4`='那可真是场漂亮的突击战。我很佩服。', `MaleText_loc5`='那是場輝煌的戰鬥。這我可以跟你說。', `MaleText_loc7`='Ha sido un asalto glorioso, eso tengo que reconocerlo.', `FemaleText_loc1`='영광스러운 전투였습니다. 인정하죠.', `FemaleText_loc4`='那可真是场漂亮的突击战。我很佩服。', `FemaleText_loc5`='那是場輝煌的戰鬥。這我可以跟你說。', `FemaleText_loc7`='Ha sido un asalto glorioso, eso tengo que reconocerlo.' WHERE `ID`=41230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제3함대 선원들의 영혼은 이 해안가를 영원히 방황하도록 저주받았습니다. 팔레스의 눈은 우리의 생을 가져가 수렁 속에 영원히 가두었지요.', `MaleText_loc4`='第三舰队被诅咒的魂灵将永世游荡在这片海岸上，$r。帕雷斯之眼掌控着我们的生命，并永远将我们囚禁在泥沼之中。', `MaleText_loc5`='$r，第三艦隊上的靈魂被詛咒後遊蕩於這個海岸，永遠地。帕雷斯之眼奪取了我們的生命，並將我們永遠地困在這裡。', `MaleText_loc7`='Las almas de la Tercera Flota estamos condenadas a vagar por estas costas por toda la eternidad, $r. El Ojo de Paleth reclamó nuestras vidas y nos atrapó en este páramo para siempre.' WHERE `ID`=41231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마여! 널 처치하러 저승에서 돌아왔다!', `MaleText_loc4`='恶魔！我从坟墓中回来，就是为了毁灭你！', `MaleText_loc5`='惡魔!我從死者的世界回到這裡來收拾你!', `MaleText_loc7`='¡Demonio! ¡He regresado de más allá de la tumba para destruirte!' WHERE `ID`=41232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음도 내 기억을 지우진 못했다. 난 아직 네 이름을 기억한다...', `MaleText_loc4`='死亡并没有抹去我的记忆。我还记得你的名字……', `MaleText_loc5`='死亡並沒帶走我的記憶。我仍然記得你的名字...', `MaleText_loc7`='La muerte no ha borrado mi memoria. Todavía sé cómo me llamo.' WHERE `ID`=41233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라크리크! 와라! 파멸을 맞아라!', `MaleText_loc4`='拉瑟莱克！来吧，面对死亡吧！', `MaleText_loc5`='拉瑟萊克!過來面對你的死亡!', `MaleText_loc7`='¡Rakh''likh! ¡Acude y enfréntate a tu muerte!' WHERE `ID`=41234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 악마 사냥꾼이로군. 이번엔 몇 조각을 내 줄까?', `MaleText_loc4`='愚蠢的恶魔猎手。这次我得把你切成多少块？', `MaleText_loc5`='愚蠢的惡魔獵人。我這次該把你大卸幾塊?', `MaleText_loc7`='Cazademonios insensato. ¿En cuántos trozos tengo que cortarte esta vez?' WHERE `ID`=41235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 지겹군!', `MaleText_loc4`='游戏时间结束了！', `MaleText_loc5`='遊戲結束了!', `MaleText_loc7`='¡Basta de juegos!' WHERE `ID`=41236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 로라무스... 알겠다. 폭풍의 제단을 사용했구나, 그렇지?', `MaleText_loc4`='这是什么？洛拉姆斯……我明白了，他们利用了风暴祭坛，是不是？', `MaleText_loc5`='這是怎麼回事?洛拉姆斯...我懂了，他們使用了暴風祭壇，對吧?', `MaleText_loc7`='¿Qué es esto? Loramus... Entiendo, utilizaron el Altar de la Tempestad, ¿verdad?' WHERE `ID`=41237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 이미 알고 있겠지... 악마의 기운이 네 심장에, 폐에, 영혼에 스며들고 있음을...', `MaleText_loc4`='那你一定已经感受到了……恶魔的能量侵入你的心肺，席卷你的灵魂……', `MaleText_loc5`='那你應該感覺到了...惡魔的能量充斥於你的心臟，你的肺，你的靈魂...', `MaleText_loc7`='Entonces ya debes sentirla... La energía demoníaca que invade tu corazón, tus pulmones, tu alma...' WHERE `ID`=41238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 잘 퍼지게 내가 도와주마!', `MaleText_loc4`='让我把进程速度加快一点！', `MaleText_loc5`='讓我把這過程加速一下!', `MaleText_loc7`='¡Permíteme que acelere un poco el proceso!' WHERE `ID`=41239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통이여! 아, 뜨겁고 달콤한 고통이여!', `MaleText_loc4`='好疼！喔，我的天，好疼！', `MaleText_loc5`='痛苦啊!噢，可愛性感的蜜糖，痛苦啊!', `MaleText_loc7`='¡Qué daño! ¡Por todos los dioses, qué daño!' WHERE `ID`=41240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 지금이오! 라크리크가 내 몸을 지배하는 동안 날 끝장내시오!', `MaleText_loc4`='冒险者们！了结我吧，不要让拉瑟莱克再控制我了！', `MaleText_loc5`='現在，英雄們!殺了我，趁拉瑟萊克侵佔了我的身體時!', `MaleText_loc7`='¡Ahora, héroe! ¡Acaba conmigo mientras Rakh''likh posee mi cuerpo!' WHERE `ID`=41241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서! 칼을 사용하시오! 시간이 없소!', `MaleText_loc4`='快！用那把刀杀了我！时间要来不及了！', `MaleText_loc5`='快點!把刀用在我身上!時間不多了!', `MaleText_loc7`='¡Rápido! ¡Usa el cuchillo! ¡Se acaba el tiempo!' WHERE `ID`=41242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달콤한 죽음이 너를 기다린다.', `MaleText_loc4`='死亡的喜悦在等着你。', `MaleText_loc5`='死亡的歡樂等著你。', `MaleText_loc7`='Las delicias de la muerte te aguardan.' WHERE `ID`=41243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌칼을 사용하시오! 어서! 곧 놈이 나를 완전히 지배하게 될 거요...', `MaleText_loc4`='那把石匕！快用！我就快控制不了他了……', `MaleText_loc5`='石製小刀!快用它!我無法再控制他太久...', `MaleText_loc7`='¡El cuchillo de piedra! ¡Úsalo AHORA! No podré controlarlo mucho más tiempo...' WHERE `ID`=41244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 돌아오시오!', `MaleText_loc4`='回到我这里来！', `MaleText_loc5`='回到我身邊!', `MaleText_loc7`='¡Regresa a mí!' WHERE `ID`=41245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났소. 날 그냥 두고 가시오. 저 세상에서도 나는 라크리크와 싸우겠지. 그대들의 임무는 끝났소, 영웅들이어.', `MaleText_loc4`='结束了。把我留在这儿吧，我会和拉瑟莱克在地狱里继续交战。你们的任务已经完成了，英雄们。', `MaleText_loc5`='結束了。離開吧，讓我和拉瑟萊克在另一個世界中糾纏。英雄們，你們在這的工作已經完成了。', `MaleText_loc7`='Está hecho. Entonces, déjame aquí para que pueda luchar con Rakh''likh en el siguiente mundo. Tu trabajo aquí ha terminado.' WHERE `ID`=41246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛께 감사를! 살았습니다!', `MaleText_loc4`='感谢圣光！我得救了！', `MaleText_loc5`='感謝聖光!我獲救了!', `MaleText_loc7`='¡Gracias a la Luz! ¡Estoy salvado!' WHERE `ID`=41247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모... 모두 죽었습니까? 암살자는요?', `MaleText_loc4`='那……那些刺客死了吗？', `MaleText_loc5`='他...他們死了嗎?那些殺手?', `MaleText_loc7`='¿Están... están muertos? ¿Los asesinos?' WHERE `ID`=41248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전합니까?', `MaleText_loc4`='安全吗？', `MaleText_loc5`='安全了嗎?', `MaleText_loc7`='¿Es seguro?' WHERE `ID`=41249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 어떻게 이런 일이?', `MaleText_loc4`='究竟是怎么回事？', `MaleText_loc5`='什麼還在詛咒中?', `MaleText_loc7`='¿Pero qué demonios?', `FemaleText_loc1`='세상에 어떻게 이런 일이?', `FemaleText_loc4`='究竟是怎么回事？', `FemaleText_loc5`='什麼還在詛咒中?', `FemaleText_loc7`='¿Pero qué demonios?' WHERE `ID`=41250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸어 다니는 상자라니? 혼도 님께 물어봐야지... 아냐, 그냥 나중에 물어봐야겠어.', `MaleText_loc4`='一只能走路的盒子？我应该问问宏多这件事……嗯，也许再等一段时间吧。', `MaleText_loc5`='一個會走路的盒子?我應該問問看漢兜...算了，下次吧。', `MaleText_loc7`='¿Una caja que camina? Debería comentar esto con Hondo... bah, no, quizá más tarde.', `FemaleText_loc1`='걸어 다니는 상자라니? 혼도 님께 물어봐야지... 아냐, 그냥 나중에 물어봐야겠어.', `FemaleText_loc4`='一只能走路的盒子？我应该问问宏多这件事……嗯，也许再等一段时间吧。', `FemaleText_loc5`='一個會走路的盒子?我應該問問看漢兜...算了，下次吧。', `FemaleText_loc7`='¿Una caja que camina? Debería comentar esto con Hondo... bah, no, quizá más tarde.' WHERE `ID`=41251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 맙소사.', `MaleText_loc4`='喔我的天。', `MaleText_loc5`='我的天啊。', `MaleText_loc7`='Ay, madre.', `FemaleText_loc1`='이런 맙소사.', `FemaleText_loc4`='喔我的天。', `FemaleText_loc5`='我的天啊。', `FemaleText_loc7`='Ay, madre.' WHERE `ID`=41252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가 일하지 못해! 아니 잠깐... 넌 그냥 상자잖아. 그럼 됐어.', `MaleText_loc4`='回去工作！喔等等……你只是个盒子，不要紧。', `MaleText_loc5`='回去工作!呃，等等...你只是個盒子，當我沒說。', `MaleText_loc7`='¡Vuelve al trabajo! Oh, no es más que una caja. No he dicho nada.', `FemaleText_loc1`='돌아가 일하지 못해! 아니 잠깐... 넌 그냥 상자잖아. 그럼 됐어.', `FemaleText_loc4`='回去工作！喔等等……你只是个盒子，不要紧。', `FemaleText_loc5`='回去工作!呃，等等...你只是個盒子，當我沒說。', `FemaleText_loc7`='¡Vuelve al trabajo! Oh, no es más que una caja. No he dicho nada.' WHERE `ID`=41253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬잇! 지금 여기 잠복한 거라네.', `MaleText_loc4`='嘘，小声点儿！我们正躲着呢。', `MaleText_loc5`='噓，老兄!我們躲在這裡。', `MaleText_loc7`='¡Chist, colega! ¡Nos e''conderemos aquí!' WHERE `ID`=41254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크릴라는 오크가 아닌 우리가 마을에 들어가는 걸 반기지 않네. 하지만, 그렇다고 우리에게 일을 안 시키지는 않아. 상관없네... 어쨌든 난 이 바깥쪽을 더 좋아하니까.', `MaleText_loc4`='奥莉里拉不喜欢让我们这些非兽人进入镇子，但那并不妨碍她安排我们去工作。不管怎样……我倒宁可待在这外面。', `MaleText_loc5`='歐克里拉不喜歡讓我們這些非獸人進入城鎮，但卻沒阻止她分配工作給我們。沒差...我寧願待在這裡。', `MaleText_loc7`='A Okrilla no le gusta que los que no son orcos entremos en la ciudad, pero eso no le impide ponernos a trabajar. No importa... De todas maneras prefiero estar aquí que fuera.' WHERE `ID`=41255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 같은 오크는 좋겠어... 여장군이 우레망치 요새에 머물게 해주니까 말이야. 오크 아닌 우리는 밖에서 일해야 하지. 상관없네... 여러 면에서, 여장군과 같은 지붕 아래에 있기보다 여기 밖에 나와 있는 걸 더 좋아하니까.', `MaleText_loc4`='你们这群兽人可真幸运……战争主母让你们待在巨槌要塞，而我们剩下这些人却要在外边干活。不过不要紧……从某种意义上说，我倒是宁可待在外面也不愿意待在她的屋檐下。', `MaleText_loc5`='你們獸人運氣真好...戰爭女總監讓你們待在巨槌要塞，我們其他人卻被送上戰場。不過算了...在某種程度上，我寧願在外面打仗。', `MaleText_loc7`='Los orcos tenéis suerte... La matrona de guerra os permite quedaros en Bastión Machacamiedo, mientras a los demás nos manda a hacer trabajo de campo. No importa... En cierta manera prefiero estar ahí fuera que bajo un techo.' WHERE `ID`=41256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 오크의 영역이라네. $r|1이여;여;, 뭐가 필요한가?', `FemaleText_loc4`='你已进入兽人的地盘。你需要什么吗，$r？', `FemaleText_loc5`='你在獸人的領土上。你需要什麼，$r?', `FemaleText_loc7`='Estás en territorio orco. ¿Qué necesitas, $r?' WHERE `ID`=41257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g형제:자매;여, 어서 오게.', `FemaleText_loc4`='欢迎你，$g兄弟:姐妹;。', `FemaleText_loc5`='歡迎，$g兄弟:姐妹;。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;.' WHERE `ID`=41258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밑져야 본전 아닌가! $n, 행운을 비네!', `MaleText_loc4`='让我们开始吧！为成功祈祷吧，$n！', `MaleText_loc5`='現在什麼都沒有!繼續祝自己好運吧，$n!', `MaleText_loc7`='¡Vamos a probar! ¡Cruza los dedos, $n!' WHERE `ID`=41259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋지군! 전부 폐쇄됐네! 이제 호드가 우리 뒤통수를 치지는 못할 테지!', `MaleText_loc4`='呀嘿！我们成功了！我们再也不会受到部落的威胁了！', `MaleText_loc5`='呀呼!她完全沒有回應!不會在有部落從後面偷襲我們了!', `MaleText_loc7`='¡YUJUUU! ¡SE HA CERRADO! ¡LA HORDA YA NO NOS PILLARÁ POR LA PUERTA DE ATRÁS!' WHERE `ID`=41260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, $n. 이리 좀 와보겠어? 부탁할 일이 있거든.', `MaleText_loc4`='嘿，$n，到这儿来，好吗？我有些任务要交给你。', `MaleText_loc5`='嘿，$n，你可以過來這一下嗎?我這有事情給你做。', `MaleText_loc7`='Eh, $n, ven aquí, ¿quieres? Me gustaría que hicieras algo por mí.' WHERE `ID`=41261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 괜찮다면 이리 좀 와 봐.', `MaleText_loc4`='$n，请到这儿来。', `MaleText_loc5`='$n，請過來一下。', `MaleText_loc7`='$n, ven aquí, por favor.' WHERE `ID`=41262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홍수의 피해는 그다지 크지 않았지. 아이언포지에 닥쳤던 것에 비하면 아무것도 아니라고.', `MaleText_loc4`='洪水并没那么可怕。至少没我们在铁炉堡里经历的那一切可怕。', `MaleText_loc5`='淹水的程度不算太糟，至少跟我們在鐵爐堡的比起來。', `MaleText_loc7`='La inundación no es tan grave. Al menos no lo es tanto como las que hemos tenido en Forjaz.' WHERE `ID`=41263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말조심해, 이 주정뱅이야! 그건 정말 실수였어!', `MaleText_loc4`='小心你的嘴巴，你这个醉鬼！那是无心之过！', `MaleText_loc5`='講話注意點，你這醉醺醺的粗人!那是個無心的錯誤!', `MaleText_loc7`='¡Ten cuidado con lo que dices, bárbaro insensible! ¡No ha sido un error intencionado!' WHERE `ID`=41264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 자네가 저지른 일을 말하는 건가?', `MaleText_loc4`='你的意思是，这是你造成的？', `MaleText_loc5`='喔，你是說你造成的那個?', `MaleText_loc7`='Sí, ¿te refieres a la que has provocado?' WHERE `ID`=41265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배수로 안쪽에 수문을 만들고서는 그 안에 자기가 갇혀 버렸지!', `MaleText_loc4`='你从里面给管道装上了闸门，把自己困住了！', `MaleText_loc5`='你從裡面把水閘放在通道上並把自己給困住了!', `MaleText_loc7`='¡Has instalado una compuerta en un canal desde el interior y te has quedado atrapado dentro!' WHERE `ID`=41266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고서는 그 배수로에서부터 굴을 파서 대식당으로 곧바로 뚫고 나왔잖아!', `MaleText_loc4`='然后你就会从这条隧道一直冲进饭厅！', `MaleText_loc5`='然後你從通道中直接挖了一個通往餐廳的隧道!', `MaleText_loc7`='Y después has hecho un túnel por el canal que da directamente al comedor.' WHERE `ID`=41267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가구 뒤쪽에서 물고기가 몇 주 동안이나 튀어나왔다고!', `MaleText_loc4`='我们已经喋喋不休地吵了几个星期了！', `MaleText_loc5`='我們已經好幾個星期可以在傢俱後面看到鯉魚了!', `MaleText_loc7`='¡Pasaremos semanas encontrando carpas detrás de los muebles!' WHERE `ID`=41268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 실수라니까!', `MaleText_loc4`='这是一个无心之过！', `MaleText_loc5`='無心之過!', `MaleText_loc7`='¡No ha sido un error intencionado!' WHERE `ID`=41269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그래도 에일 맥주는 안전했잖아.', `MaleText_loc4`='嗯，至少麦酒是安全的。', `MaleText_loc5`='至少麥芽酒沒事。', `MaleText_loc7`='Bueno, por lo menos la cerveza está a salvo.' WHERE `ID`=41270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 정말 비극이라고, 친구들. 우리 모두 메네실의 저주를 받은 거야.', `MaleText_loc4`='这可真是个悲剧啊，兄弟们。米奈希尔的诅咒落在了我们每个人的身上。', `MaleText_loc5`='這是場悲劇，夥計們。我們都中了米奈希爾的詛咒。', `MaleText_loc7`='Es una tragedia, muchachos. La maldición de Menethil ha caído sobre todos nosotros.' WHERE `ID`=41271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네. 제자리에 있는 것만큼은 끝내주게 잘했지! 하지만 제독님만큼은 못했네.', `MaleText_loc4`='哈，她干得可真漂亮！但和将军还没法比。', `MaleText_loc5`='對，而且她做得很好!但還是比不上上將。', `MaleText_loc7`='Sí, ¡y ha hecho un gran trabajo! Pero no tan bueno como el almirante.' WHERE `ID`=41272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 이 자리를 참 오랫동안 지키고 있었네. 그렇지만 그걸로는 부족했어.', `MaleText_loc4`='我们尽可能地守在这里，可还是不够。', `MaleText_loc5`='我們盡最大的努力在守衛這裡了，但還是不夠。', `MaleText_loc7`='Mantuvimos nuestra posición en este lugar todo lo que pudimos, pero no fue suficiente.' WHERE `ID`=41273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 그분처럼 자리를 지키진 못 할 거야, 친구.', `MaleText_loc4`='没人能像他那样守住一个地方，小子们。没人能做到。', `MaleText_loc5`='沒人能保護一個地方保護的跟他一樣好，夥計們。沒有人可以。', `MaleText_loc7`='Nadie puede mantener la posición como él, camaradas. Nadie.' WHERE `ID`=41274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님, 처녀의 순결호는 몇 년째 출항을 못 했습니다. 그냥 제자리에만 있었죠.', `MaleText_loc4`='船长，处女号已经许多年没有航行过了。它就被安放在那里。', `MaleText_loc5`='船長，處女號已經好幾年沒有出過港了。它一直停在那。', `MaleText_loc7`='Capitán, hace años que el Virtud no despliega velas. Simplemente estaba ahí anclado.' WHERE `ID`=41275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 알고 있습니다, 선장님. 알고 있단 말입니다.', `MaleText_loc4`='我们明白，头儿。我们明白。', `MaleText_loc5`='我們知道，船長。我們知道。', `MaleText_loc7`='Lo sabemos, capitán. Lo sabemos.' WHERE `ID`=41276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했습니다, $n. 그가 아직 살아 있습니까?', `MaleText_loc4`='我们到了，$n。他还活着吗？', `MaleText_loc5`='我們來了，$n。他還活著嗎?', `MaleText_loc7`='Hemos llegado, $n. ¿Todavía vive?' WHERE `ID`=41277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부는 중', `MaleText_loc4`='好强的风啊。', `MaleText_loc5`='吹起中', `MaleText_loc7`='Soplando', `FemaleText_loc1`='부는 중', `FemaleText_loc4`='好强的风啊。', `FemaleText_loc5`='吹起中', `FemaleText_loc7`='Soplando' WHERE `ID`=41278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 그 친구의 몸이 따뜻해 질 겁니다!', `MaleText_loc4`='这应该能让他暖和起来！', `MaleText_loc5`='這應該可以讓大夥暖起身!', `MaleText_loc7`='¡Esto hará que entre en calor!' WHERE `ID`=41279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롤!!', `MaleText_loc4`='戈洛尔！！', `MaleText_loc5`='格羅爾!!', `MaleText_loc7`='¡¡Grol!!' WHERE `ID`=41280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신, 무슨 짓을 한 거지?', `MaleText_loc4`='你——你都干了什么？', `MaleText_loc5`='你!你做了什麼?', `MaleText_loc7`='¡Tú! ¿Qué has hecho?' WHERE `ID`=41281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 하늘담의 군주에게 도전장을 내밀었나, $n? 널 쓰러뜨리고 그 시체를 진흙괴물이 가득한 구덩이로 던져 버리겠다!', `MaleText_loc4`='你竟敢召唤天空之墙的领主，$n？我要杀了你，然后把你的尸体扔回到你爬行而出的烂泥坑里！', `MaleText_loc5`='你敢召喚一個天空之牆的領主，$n?我會毀了你後把你的臭皮囊丟回你原本爬在裡面的那堆爛泥中。', `MaleText_loc7`='¿Te atreves a dar órdenes a un señor del Muro Celeste, $n? ¡Te destruiré y arrojaré tu cadáver de vuelta al cieno del que saliste arrastrándote!' WHERE `ID`=41282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아... 내가 가야만 하는 길이로군. 영웅들이여, 동굴 안에서 만납시다.', `MaleText_loc4`='我明白了……这是我必须选择的道路。回到洞里找我，英雄们。', `MaleText_loc5`='我懂了...這是我必須走的一條路。英雄們，回到洞穴裡面見我。', `MaleText_loc7`='Entiendo... este es el camino que debo tomar. Reuníos conmigo en la cueva, héroes.' WHERE `ID`=41283;
