UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 오래 이 광산에 내려와 있었나 봐요.', `MaleText_loc4`='我觉得我待在这矿井里太久了。', `MaleText_loc5`='我想我在這個礦坑待了太久了。', `MaleText_loc7`='Creo que llevo demasiado tiempo dentro de esta mina.', `FemaleText_loc1`='너무 오래 이 광산에 내려와 있었나 봐요.', `FemaleText_loc4`='我觉得我待在这矿井里太久了。', `FemaleText_loc5`='我想我在這個礦坑待了太久了。', `FemaleText_loc7`='Creo que llevo demasiado tiempo dentro de esta mina.' WHERE `ID`=41293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 상자 귀신이에요!', `MaleText_loc4`='小心！那是个盒子魔鬼！', `MaleText_loc5`='小心!它是個盒子惡魔!', `MaleText_loc7`='¡Mira! ¡Una caja embrujada!', `FemaleText_loc1`='조심하세요! 상자 귀신이에요!', `FemaleText_loc4`='小心！那是个盒子魔鬼！', `FemaleText_loc5`='小心!它是個盒子惡魔!', `FemaleText_loc7`='¡Mira! ¡Una caja embrujada!' WHERE `ID`=41294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='택배가 왔네요. 누가 물건을 잔뜩 샀나 본데요.', `MaleText_loc4`='看来这是给某人的特别快递包裹。', `MaleText_loc5`='看來有人有特別快遞。', `MaleText_loc7`='Parece que alguien ha recibido un paquete especial.', `FemaleText_loc1`='택배가 왔네요. 누가 물건을 잔뜩 샀나 본데요.', `FemaleText_loc4`='看来这是给某人的特别快递包裹。', `FemaleText_loc5`='看來有人有特別快遞。', `FemaleText_loc7`='Parece que alguien ha recibido un paquete especial.' WHERE `ID`=41295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 내가 말하는 대로 해주었으면 하오. 우리가 흔들리면, 라젤리크의 손바닥 안에서 놀아나기만 할 거요.', `MaleText_loc4`='我需要你按我说的去做，$r。如果我们退却，我们就很可能落入拉瑟莱克的股掌之中。', `MaleText_loc5`='我需要你照我所說的做，$r。如果我們退縮了，很有可能便落入拉瑟萊克的控制之中。', `MaleText_loc7`='Necesito que hagas lo que te digo, $r. Si flaqueamos, entonces estamos dándole toda la ventaja a Razelikh.' WHERE `ID`=41296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 대지 고리회에서 예상했던 것보다 훨씬 큰 무언가를 상대하고 있는 것 같군요.', `MaleText_loc4`='我们正在对付的，看来要比大地之环预料到的任何东西都要大得多。', `MaleText_loc5`='我們面對的東西似乎比陶土議會所預測的來得更加，更加巨大。', `MaleText_loc7`='Parece ser que estamos enfrentándonos a algo mayor que lo que cualquiera del Anillo de la Tierra haya podido sospechar.' WHERE `ID`=41297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 대지 고리회에서 예상했던 것보다 훨씬 큰 무언가를 상대하고 있는 것 같군요.', `MaleText_loc4`='我们正在对付的，看来要比大地之环预料到的任何东西都要大得多。', `MaleText_loc5`='我們面對的比陶土議會所預測的來得恐怖太多了。', `MaleText_loc7`='Parece ser que estamos enfrentándonos a algo mayor que lo que cualquiera del Anillo de la Tierra haya podido sospechar.' WHERE `ID`=41298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동굴 바로 바깥에 나가의 관심이 집중되고 있습니다.$b$b들키지 않고 여기까지 오다니 운이 좋았군요.', `MaleText_loc4`='在这个洞穴之外集结了大批纳迦。$b$b我们能神不知鬼不觉地到达这个地方，可真是幸运。', `MaleText_loc5`='這個洞穴外有大量的納迦在外面。$b$b我們能在不被發現之下來到這裡真是好運。', `MaleText_loc7`='Hay una gran concentración de nagas en el exterior de esa caverna.$b$bHemos tenido mucha suerte de haber podido llegar hasta aquí sin llamar su atención.' WHERE `ID`=41299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대원들은... 모두 붙잡혔습니다.', `MaleText_loc4`='我们的士兵……他们都已沦为俘虏。', `MaleText_loc5`='我們的士兵...他們現在都已經是俘虜了。', `MaleText_loc7`='Nuestros soldados... son todos prisioneros.' WHERE `ID`=41300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 동료가 나가의 손아귀에서 탈출을 시도했습니다.$b$b성공한 것은 저 하나뿐입니다...', `MaleText_loc4`='我们许多人都试图逃离纳迦。$b$b我是唯一成功的幸运儿……', `MaleText_loc5`='我們很多人都試著要從納迦手裡逃脫。$b$b我是唯一一個成功的...', `MaleText_loc7`='Muchos de nosotros intentamos escapar de los nagas.$b$bY yo soy el único que lo ha conseguido...' WHERE `ID`=41301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜인지는 모르지만, 저 괴물들은 우리 동료를 살려둘 속셈인 듯합니다...', `MaleText_loc4`='我不知道原因，但那些怪物在想方设法让我们的人活下来……', `MaleText_loc5`='我不知道為什麼，但那些怪物正在讓開使我們的人可以活下來...', `MaleText_loc7`='No sé por qué, pero esos monstruos se esfuerzan por salvarles la vida a nuestros hombres...' WHERE `ID`=41302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 아뮬렛 가져가고, $r|1이;가; 바위웅덩이 도와 준다.', `MaleText_loc4`='好！拿去护符，可$r要帮助岩池鱼人。', `MaleText_loc5`='算了!護符給你，但$r要幫助石塘。', `MaleText_loc7`='¡Vale! Tomar amuleto, pero $r ayudar a los Pozarroca.' WHERE `ID`=41303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 같은 파도 아래 살았고, 같은 물을 마셨고, 같은 신을 섬겼다. 그런데 왜, 나가는 우리에게 등을 돌렸을까?', `MaleText_loc4`='我们生活在同一片海浪中，吞吐着同一片海水，膜拜着同一位神灵。那究竟是为什么——纳迦要与我们反目为敌？', `MaleText_loc5`='我們曾生活在同個海浪下，呼吸一樣的海水，擁有相同的信仰。告訴我為什麼，為什麼納迦要把矛頭指向我們?', `MaleText_loc7`='Hemos vivido bajo las mismas olas, hemos respirado la misma agua y adorado al mismo dios. Entonces, ¿por qué los nagas se volverían contra nosotros?' WHERE `ID`=41304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔레스의 눈은 오래전에 회수해 정화했습니다. 그래서 저주가 풀렸다고 생각했었지요.', `MaleText_loc4`='帕雷斯之眼早在很久之前就已被夺回和净化，$c。我们以为诅咒早已被消除。', `MaleText_loc5`='帕雷斯之眼在很久以前就取回並淨化了，$c。我們以為詛咒已經被清除。', `MaleText_loc7`='El Ojo de Paleth fue recuperado y purificado hace mucho tiempo, $c. Creíamos que la maldición había desaparecido.' WHERE `ID`=41305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1년 전쯤에 불쌍한 노인 피츠시몬즈가 생을 마감했습니다. 술을 너무 많이 마셔 몸이 상했기 때문이었지요.', `MaleText_loc4`='不到一年前，大副菲兹莫斯那个可怜的老家伙去世了，是酒毁了他的身体。', `MaleText_loc5`='快一年前，可憐的老菲茲莫斯走了，他的身體被酒搞垮了。', `MaleText_loc7`='Hace casi un año, el viejo pobre Fistimos murió, con el cuerpo destrozado por la bebida.' WHERE `ID`=41306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이후로 사람들은 계속해서 피츠시몬즈가 팔레스의 눈을 가져오려고 그들과 이야기를 나누었다고 주장합니다...', `MaleText_loc4`='从那以后，时常会有人声称听到他跟他们说话，让他们去把眼睛拿来……', `MaleText_loc5`='在此之後，人們不斷地說他在跟他們說話，並要他們去拿眼睛...', `MaleText_loc7`='Desde entonces, de vez en cuando, la gente dice que él les habla y que les dice que consigan el ojo...' WHERE `ID`=41307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지를 영원히 떠도는 저주지요... 불쌍한 피츠시몬즈조차도 이 저주에서 벗어나지 못했습니다.', `MaleText_loc4`='被诅咒者只能永远在这里徘徊……就连可怜的菲兹莫斯也无法逃脱。', `MaleText_loc5`='受到永遠不得超生的詛咒...就連可憐的菲茲莫斯都逃不了這個命運。', `MaleText_loc7`='Condenado a vagar por la tierra eternamente... ni siquiera el pobre Fistimos podría escapar.' WHERE `ID`=41308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 가져온 게 정확히 무엇인지 제게 물어보지 마십시오. 지금까지 일어났던 일을 모두 잊는 편이 더 낫습니다.', `MaleText_loc4`='别问我你究竟给我带来了什么，$c。你最好忘记这件事曾经发生过。', `MaleText_loc5`='別問我你到底帶了什麼東西來給我，$c。你最好忘了這一切，當什麼都沒發生過。', `MaleText_loc7`='No me pidas lo que me has traído, $c. Será mejor que olvides que esto ha sucedido siquiera.' WHERE `ID`=41309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 헬스크림의 군대가 우리를 향해 전진하는 중이오!', `MaleText_loc4`='地狱咆哮的军队正在朝我们袭来，兄弟姐妹们！', `MaleText_loc5`='兄弟和姐妹，地獄吼的軍隊正朝我們邁進!', `MaleText_loc7`='¡Hermanos y hermanas, los ejércitos de Grito Infernal marchan hacia nosotros!' WHERE `ID`=41310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸우시오! 마가타 님이 명하셨소!', `MaleText_loc4`='继续作战！听从玛加萨的号令！', `MaleText_loc5`='繼續戰鬥!這是瑪加薩的命令!', `MaleText_loc7`='¡Seguid luchando! ¡Magatha lo ordena!' WHERE `ID`=41311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좌절하지 마시오! 모두 끝나지는 않았소! 아직은 아니오!', `MaleText_loc4`='不要丧失信心！我们还没一无所有！还没！', `MaleText_loc5`='不要絕望!我們還沒輸!還沒有!', `MaleText_loc7`='¡No desesperéis! ¡No todo está perdido! ¡Aún no!' WHERE `ID`=41312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 나는 미래를 보았소. 그 미래 속에 호드는 없었소!', `MaleText_loc4`='我见到了未来，兄弟姐妹们，但却没有看到部落的踪影！', `MaleText_loc5`='我看到了未來，兄弟和姐妹，那是個部落已經不存在的未來!', `MaleText_loc7`='¡He visto el futuro, hermanos y hermanas, y en él la Horda ya no existía!' WHERE `ID`=41313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 승리할 것이오! 꺾이지 마시오!', `MaleText_loc4`='我们会胜利的！不要懦弱！', `MaleText_loc5`='我們將會勝利!不要放鬆!', `MaleText_loc7`='¡Saldremos victoriosos! ¡No cedáis!' WHERE `ID`=41314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격하시오! 그림토템은 쓰러져야만 하오! 하나도 남김없이 모두!', `MaleText_loc4`='进攻！不惜一切代价！攻陷恐怖图腾！', `MaleText_loc5`='攻擊!務必消滅恐怖圖騰!消滅一切!', `MaleText_loc7`='¡ATAQUEN! ¡Los Tótem Siniestro deben caer! ¡TODOS DEBEN CAER!', `FemaleText_loc1`='공격하시오! 그림토템은 쓰러져야만 하오! 하나도 남김없이 모두!', `FemaleText_loc4`='进攻！不惜一切代价！攻陷恐怖图腾！', `FemaleText_loc5`='攻擊!務必消滅恐怖圖騰!消滅一切!', `FemaleText_loc7`='¡ATAQUEN! ¡Los Tótem Siniestro deben caer! ¡TODOS DEBEN CAER!' WHERE `ID`=41315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림을 위하여! 호드를 위하여!', `MaleText_loc4`='为了地狱咆哮！为了部落！', `MaleText_loc5`='為了地獄吼!為了部落!', `MaleText_loc7`='¡POR GRITO INFERNAL! ¡POR LA HORDA!', `FemaleText_loc1`='헬스크림을 위하여! 호드를 위하여!', `FemaleText_loc4`='为了地狱咆哮！为了部落！', `FemaleText_loc5`='為了地獄吼!為了部落!', `FemaleText_loc7`='¡POR GRITO INFERNAL! ¡POR LA HORDA!' WHERE `ID`=41316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='골드린은 고대 늑대정령이다. 호드어로는 "로고쉬"로 알려져 있는데, 그의 강인함은 전설적이지.$B$B세계수 서쪽에 분지가 하나 있는데, 그곳에 그를 기리는 제단이 있다. 그런데 전쟁이 시작된 뒤로는 제단을 지키던 자들에게서 아무런 소식이 없구나.$B$B우리가 앞으로 나아가려면 먼저 제단을 구해내야 한다. 늑대 고대정령의 행방을 찾아보고, 그의 적을 물리치거라.', `FemaleText_loc4`='戈德林是狼神先祖，在部落语中又被称作“洛戈什”。他有着传奇般的坚韧战力。$B$B为纪念他而建造的圣殿就位于世界之树西边的盆地那里，但它的看守人在那次攻击之后就变得杳无声息。我担心最坏的事情已经发生了。$B$B在我们继续前进之前，你必须确保圣殿安全无虞，查明狼神先祖的下落，击退他的敌人。', `FemaleText_loc5`='戈德林是狼魂先祖，在部落以「洛戈許」之名流傳著，擁有驚人的韌性與毅力。$B$B紀念他的聖壇就在世界樹西邊的盆地，但那些守衛者在最近的攻擊威脅中卻沒有反應，我擔心他們是否已經出事了。$B$B在我們繼續行動前，你必須保護聖壇，找到狼魂先祖，並且擊退他的敵人。', `FemaleText_loc7`='Goldrinn es el ancestro lobo, al que se conoce como "Lo''Gosh" en la lengua de la Horda. Su tenacidad es legendaria.$B$BHay un santuario dedicado a él en una cuenca al oeste del Árbol del Mundo, pero no hemos sabido de sus guardianes desde el ataque. Me temo lo peor.$B$BAntes de que podamos proseguir, debes salvar el santuario, descubrir el paradero del ancestro lobo y rechazar a sus enemigos.' WHERE `ID`=41317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아에시나는 자연의 혼이며, 이 세계와 그너머 꿈속 세계에서도 나와 함께하는 영원한 친구이다. 하이잘 서쪽 지역에 그녀의 제단이 있는데, 지금 황혼의 망치단의 집중 공격을 받고 있다. 지금 이 순간에도 불타고 있을지 모른다.$B$B$n, 아에시나의 도움 없이는 절대 하이잘 산을 되찾을 수 없다. 그녀의 제단을 화재로부터 구해내고, 화재로 겁에 질린 제단 주변의 동물들도 구해 주거라. 그렇게 하지 않으면 산 전체를 잃게 될 것이다.', `FemaleText_loc4`='艾森娜是自然之魂，也是我在这个世界和梦境中永恒的同伴。她位于海加尔西部的圣殿，就在暮光入侵的最前线，此刻应该已被战火席卷。$B$B$n，如果没有艾森娜的帮助，我们永远都别想重建海加尔山。确保她的圣殿免受大火的侵袭，并救救附近那些被烈焰威胁的生灵吧。要是我们做不到，就将失去这整座山。', `FemaleText_loc5`='艾森娜是自然之靈，她是我在這個世界和夢境中永遠的同伴。她的神殿在海加爾山的西側，位於暮光進攻部隊的最前線，隨時都可能被燒掉。$B$B$n，若是沒有艾森娜的幫助，我們永遠都無法重建海加爾山。營救她的神殿免於火難，還有救出那附近可能會受到火災威脅的動物。我們必須這樣做，不然將無法挽回這座聖山。', `FemaleText_loc7`='Aessina es el espíritu de la naturaleza, mi compañera inmortal tanto en este mundo como en el sueño más allá. Su santuario está en la zona oeste de Hyjal, en la vanguardia de la ofensiva Crepuscular; y en estos momentos puede que esté en llamas.$b$b$n, nunca podremos restaurar el Monte Hyjal sin la ayuda de Aessina. Salva su santuario de las llamas junto con todos los animales de los alrededores que se vean amenazados por el incendio. Debemos hacerlo antes de que todo el monte esté perdido.' WHERE `ID`=41318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아비아나는 사라진 하늘의 수호자이자 만 년 전에 악마의 무리와 싸우다 전사한 새의 여신이다. 놀드랏실 남서쪽에 그녀를 기리는 제단이 있다. 거대한 나무가 감싸고 있는 곳이지.$B$B갈퀴발톱의 드루이드들이 그 안에 근거지를 두고 있는데, 우리는 그들의 지원이 필요하다. 그래서 그들을 도와야 한다. 아비아나도 도와 주거라. 그녀가 이 세계로 돌아올 수 있도록...', `FemaleText_loc4`='艾维娜是天穹的失落卫士，一万年前在与恶魔大军的对抗中不幸消亡的鸟之女神。为纪念她而建造的圣殿就在西南边，在一棵参天大树的虬枝之中。$B$B猛禽德鲁伊把那圣殿作为他们的大本营，而我们需要他们的支援。你必须前去帮助他们。同时也帮助艾维娜，愿她能找到回归这世界的通途……', `FemaleText_loc5`='艾維娜是殞落的天空守護神，一個鳥之女神，在一萬年前與魔性部落的戰爭中犧牲了。在諾達希爾的西南方有一個為了紀念她而建的聖壇，位於一棵宏偉大樹的枝葉之中。$B$B猛禽德魯伊就棲息在聖壇之中，我們必須得到他們的幫助。為此，你必須幫助他們，幫助艾維娜，如果她能找到回這個世界的道路...', `FemaleText_loc7`='Aviana es la desaparecida guardiana de los cielos, una diosa pájaro que murió luchando contra las hordas de demonios hace diez mil años. Al suroeste de Nordrassil, entre las ramas de un gran árbol, se alza un santuario construido en su memoria.$B$BLos Druidas de la Garfa tienen su base dentro del santuario y necesitaremos su ayuda. Debes ayudarles. Y ayudar a Aviana si encuentra el camino de vuelta a este mundo...' WHERE `ID`=41319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대드루이드 하뮬 룬토템을 불타버린 말로른의 성역 주변으로 보냈다. 룬토템은 지금 최전선 근처에 있다. 불꽃의 흔적으로 알려진 검게 그을린 지역이지. 그는 우리가 입은 피해를 복구할 방법을 고민하는 동시에 거북이 고대정령인 토르톨라의 행방을 찾고 있다.$B$B그를 도우려면 먼저 서쪽에 있는 아에시나의 제단을 구하고 그곳의 동물들을 화재로부터 안전하게 대피시켜야 하느니라. 그렇지 않으면 모든 것을 잃고 말 것이다! 먼저 아에시나의 숲에 집중하거라. 적절한 때가 되면 그쪽의 친구들이 그대를 대드루이드에게 보낼 것이다.', `FemaleText_loc4`='我已经派大德鲁伊哈缪尔·符文图腾前往被烧得面目全非的玛洛恩庇护所。他在前线的后方——被称作烈焰之痕的焦枯之地。他正在寻找让我们挽回损失的办法，并调查龟神托尔托拉的下落。$B$B但在你前去帮他之前，你必须先确保西边艾森娜神殿的安全，还要保护那里的生灵免受烈焰的侵袭。否则我们将失去一切！先集中精力解决艾森娜林地的问题，然后他们会在适当的时候送你去大德鲁伊那里。', `FemaleText_loc5`='我已經派大德魯伊哈繆爾·符文圖騰到被燒毀的瑪洛尼聖地了。他位於前線的後方，在一個叫烈焰之甦的焦枯之地。他在調查我們怎樣才能治療該地的傷害和尋找烏龜的先祖托爾托拉。$B$B但在你去幫他前，你必須先確保艾森娜神殿西方的動物免於火焰的傷害，不然一切都將是徒勞的!先專心處理艾森娜之林的問題，然後他們很快就會要你去大德魯伊那裡。', `FemaleText_loc7`='He enviado al Archidruida Hamuul Tótem de Runa a las ruinas carbonizadas del Santuario de Malorne. Está detrás de las líneas enemigas, en una tierra carbonizada llamada La Estela Ardiente. Intenta descubrir cómo podremos deshacer el daño e investiga el paradero del ancestro tortuga Tortolla.$B$BPero antes de que vayas a ayudarle, debes asegurarte de que el Santuario de Aessina, al oeste, está a salvo de las llamas. De lo contrario, ¡todo estará perdido! Concéntrate en lo que haya que hacer en la Arboleda de Aessina y después te enviarán con el archidruida a tiempo.' WHERE `ID`=41320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드린의 제단에 대해 말해 주십시오.', `MaleText_loc4`='告诉我关于戈德林圣殿的事。', `MaleText_loc5`='跟我說有關戈德林聖壇的事。', `MaleText_loc7`='Háblame del Santuario de Goldrinn.', `FemaleText_loc1`='골드린의 제단에 대해 말해 주세요.', `FemaleText_loc4`='告诉我关于戈德林圣殿的事。', `FemaleText_loc5`='跟我說有關戈德林聖壇的事。', `FemaleText_loc7`='Háblame del Santuario de Goldrinn.' WHERE `ID`=41321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아에시나의 숲에 무슨 일이 일어나는 겁니까?', `MaleText_loc4`='艾森娜林地发生什么事了？', `MaleText_loc5`='艾森娜之林發生了什麼事?', `MaleText_loc7`='¿Qué sucede en la Arboleda de Aessina?', `FemaleText_loc1`='아에시나의 숲에 무슨 일이 일어나는 건가요?', `FemaleText_loc4`='艾森娜林地发生什么事了？', `FemaleText_loc5`='艾森娜之林發生了什麼事?', `FemaleText_loc7`='¿Qué sucede en la Arboleda de Aessina?' WHERE `ID`=41322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하면 아비아나의 제단을 도울 수 있습니까?', `MaleText_loc4`='我该怎样帮助艾维娜圣殿？', `MaleText_loc5`='我要如何幫助艾維娜聖壇?', `MaleText_loc7`='¿Cómo puedo ayudar al Santuario de Aviana?', `FemaleText_loc1`='어떻게 하면 아비아나의 제단을 도울 수 있나요?', `FemaleText_loc4`='我该怎样帮助艾维娜圣殿？', `FemaleText_loc5`='我要如何幫助艾維娜聖壇?', `FemaleText_loc7`='¿Cómo puedo ayudar al Santuario de Aviana?' WHERE `ID`=41323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말로른의 성역에서 제가 도울 일이 있습니까?', `MaleText_loc4`='我能在玛洛恩庇护所做些什么吗？', `MaleText_loc5`='瑪洛尼聖地那有什麼是我可以幫忙的嗎?', `MaleText_loc7`='¿Hay algo que pueda hacer en el Santuario de Malorne?', `FemaleText_loc1`='말로른의 성역에서 제가 도울 일이 있나요?', `FemaleText_loc4`='我能在玛洛恩庇护所做些什么吗？', `FemaleText_loc5`='瑪洛尼聖地那有什麼是我可以幫忙的嗎?', `FemaleText_loc7`='¿Hay algo que pueda hacer en el Santuario de Malorne?' WHERE `ID`=41324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 게을러터진 드워프들을 움직여보려고 두들겨 패는 것 말고는 모든 방법을 다 써봤어요.$B$B당신은 성격이 단호한 편이죠?', `FemaleText_loc4`='我已经想尽办法让这些矮人勤快起来，就差把他们暴打一顿了。$B$B你难道有更严苛的招数？', `FemaleText_loc5`='我為了讓這些矮人懶豬起來，除了給他們幾下正義之拳外什麼方法都試過了。$B$B你有比他們更勤勞嗎?', `FemaleText_loc7`='Lo he intentado todo menos darles una buena paliza a esos enanos para que muevan sus perezosos culos.$B$B¿Acaso tú eres de una pasta más dura?' WHERE `ID`=41325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='광산을 샅샅이 뒤져라! 한 놈도 목숨이 붙어 있어서는 안 된다!', `FemaleText_loc4`='扫清矿井！不留活口！', `FemaleText_loc5`='搜查礦坑!全部格殺無論!', `FemaleText_loc7`='¡Peinad las minas! ¡Que no queden supervivientes!' WHERE `ID`=41326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 많이 처치한 암살자는 대군주님께서 베푸시는 연회에 초대될 것이다!', `FemaleText_loc4`='干掉最多敌人的杀手，将被邀请与领主同桌共餐！', `FemaleText_loc5`='擊殺數最多的暗殺者將受到與霸主共進佳餚的邀請!', `FemaleText_loc7`='¡El asesino con mayor número de muertos podrá sentarse a la mesa del señor supremo en el banquete!' WHERE `ID`=41327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제들이여, 헬스크림 님께서 지켜보신다!', `FemaleText_loc4`='兄弟们，地狱咆哮之眼在注视着你们！', `FemaleText_loc5`='地獄吼的雙眼在盯著你，兄弟!', `FemaleText_loc7`='¡Los ojos de Grito Infernal están fijos en ustedes, hermanos!' WHERE `ID`=41328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카즈 모단은 무너질 것이다! 모든 것이 그분의 이름으로 폐허가 될 것이다!', `MaleText_loc4`='卡兹莫丹必将粉碎！一切都将以他的名义陷入毁灭！', `MaleText_loc5`='卡茲莫丹將會崩壞!一切都將毀滅於他的名下!', `MaleText_loc7`='¡Khaz Modan se desmoronará! ¡TODO SUCUMBIRÁ EN SU NOMBRE!' WHERE `ID`=41329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 종말을 멈출 수는... 없다...', `MaleText_loc4`='你无法阻止……末日……', `MaleText_loc5`='你無法阻止...末日來臨...', `MaleText_loc7`='No puedes detener... el fin...' WHERE `ID`=41330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을... 떠나라...', `MaleText_loc4`='离开……这里……', `MaleText_loc5`='離開...這個地方...', `MaleText_loc7`='ABANDONAD... ESTE LUGAR...' WHERE `ID`=41331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다지 편한 곳은 아니지만, 이곳은 아직 카즈 모단의 영역입니다. 그러니 아직도 우리의 고향이지요.', `MaleText_loc4`='也许这里并不怎么舒适宜人，可这里仍旧是卡兹莫丹，所以它还是我们的家。', `MaleText_loc5`='這裡或許沒有那麼舒適，但這仍舊是卡茲莫丹，仍舊是我們的家園。', `MaleText_loc7`='Quizá ahí fuera no se esté muy cómodo, pero todavía es Khaz Modan, así que aún sigue siendo nuestro hogar.' WHERE `ID`=41332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마을은 저 빌어먹을 바다 밑에 있고, 우리의 요새는 검은무쇠 부족 배신자들로 가득합니다. 그리고 저는 이렇게 상처를 입어 뭐 하나도 제대로 할 수 없는 상태입니다.$B$B그러니 메네실 항구에 오신 것을 정말 환영하는 바입니다!', `MaleText_loc4`='我们的城镇沉没在被诅咒的洋底，我们的要塞已被黑铁叛徒侵占，而我也身受重伤，对这种局面束手无策。$B$B所以欢迎来到米奈希尔港！', `MaleText_loc5`='我們的城鎮被該死的海洋淹沒，我們的要塞充斥著黑鐵叛徒，而我卻在這帶著這個傷口，什麼事情都做不了。$B$B歡迎來到米奈希爾港!', `MaleText_loc7`='Nuestra ciudad está bajo el maldito océano, nuestra fortaleza está llena de traidores Hierro Negro y yo estoy aquí tumbado con una herida tal que no puedo hacer nada para evitar todo eso.$B$B¡Así que te doy la bienvenida a Puerto de Menethil!' WHERE `ID`=41333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 물러나십시오! "쿠키"가 요리할 때는 좀 화끈해집니다!', `MaleText_loc4`='退后，$n！当“曲奇”烹饪时，场面可是相当疯狂！', `MaleText_loc5`='往後站，$n!當「小廚」煮東西，那可夠帶勁的啦!', `MaleText_loc7`='¡Atrás, $n! Cuando "Cocinitas" cocina, las cosas se vuelven un poco locas!' WHERE `ID`=41334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 전부 섞은 다음 나만의 특제 양념을 첨가하면!', `MaleText_loc4`='现在该把它搅拌在一起，加上我的秘制香料！', `MaleText_loc5`='將全部攪拌在一起和加入我的特制香料!', `MaleText_loc7`='¡Ahora se mezcla todo y se añaden especias especiales!' WHERE `ID`=41335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짜잔!', `MaleText_loc4`='嘿！', `MaleText_loc5`='搭啦!', `MaleText_loc7`='¡BUM!' WHERE `ID`=41336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 네놈을 집어삼킬 것이다! 우리 모두를 집어삼킬 거야!', `MaleText_loc4`='烈焰将会吞噬你！会把我们所有人都吞噬殆尽！', `MaleText_loc5`='火焰會吞噬你們!將吞噬你們全部!', `MaleText_loc7`='¡LAS LLAMAS OS CONSUMIRÁN! ¡NOS CONSUMIRÁN A TODOS!' WHERE `ID`=41337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 님께... 영광을...', `MaleText_loc4`='荣光献给……拉格纳罗斯……', `MaleText_loc5`='拉格納羅斯的...榮光...', `MaleText_loc7`='Gloria... a Ragnaros.' WHERE `ID`=41338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그래 이 냄새야! 냄새 죽이는군, 이게 바로 "쿠키" 요리지! 먹지 않고 버틸 이가 있을까? $n 님, 당장 이 고기 공물을 그림토템 대사에게 가져다주십시오.', `MaleText_loc4`='嗯，嗯！闻上去可真香啊，“曲奇”！谁能抵抗如此美味的诱惑？$n快把这份肥美的大餐送到恐怖图腾大使那里去！', `MaleText_loc5`='嗅嗅嗅，嗅嗅嗅!聞起來真香，「小廚!」誰有辦法抗拒這些食物?$n，立刻把這香噴噴的貢品交給恐怖圖騰大使!', `MaleText_loc7`='¡Mmmm, mmmm! Huele genial, "Cocinitas"! ¿Quién podría resistirse a una comida así? $n, lleva esta jugosa ofrenda al embajador Tótem Siniestro inmediatamente!' WHERE `ID`=41339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은 굽이로 돌아가야 합니다.', `MaleText_loc4`='返回赤色海岸。', `MaleText_loc5`='回到紅色海岸。', `MaleText_loc7`='Regresa a Las Costas Rojas.' WHERE `ID`=41340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이세라 님께서는 야생의 정령 아에시나와 접촉하도록 나를 이곳에 보내셨지.$B$B그렇지만 아에시나 님께서는 아직 답이 없으시네.', `MaleText_loc4`='伊瑟拉派我来这里与艾森娜的荒野灵魂取得联系。$B$B可这古老的灵魂仍在保持沉默。', `MaleText_loc5`='伊瑟拉將我送了過來與艾森娜的自然之靈交談。$B$B但先祖卻仍舊保持沉默。', `MaleText_loc7`='Ysera me ha enviado aquí para que establezca contacto con el espíritu de la naturaleza, Aessina.$B$BSin embargo, el ancestro permanece en silencio.' WHERE `ID`=41341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 시작한 전쟁이 아닙니다. 호드가 시작했죠.', `MaleText_loc4`='不是我们将战火引向部落，而是部落将战火引向我们。', `MaleText_loc5`='並不是我們向部落發起戰爭，而是部落將戰爭帶給我們。', `MaleText_loc7`='Nosotros no llevamos la guerra a la Horda, fue la Horda la que nos trajo la guerra a nosotros.' WHERE `ID`=41342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그룬디히는 가까이에 있소. 저기를 보시오.', `MaleText_loc4`='格鲁迪格就在附近。看那儿。', `MaleText_loc5`='格魯迪格就在附近。看那邊。', `MaleText_loc7`='Grundig está cerca. Mira.' WHERE `ID`=41343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에서 암살자를 보냈소! 모두 처치하시오!', `MaleText_loc4`='部落派来了刺客！把他们全都干掉！', `MaleText_loc5`='部落派出了刺客!殺光他們!', `MaleText_loc7`='¡La Horda envía asesinos! ¡Mátenlos a todos!' WHERE `ID`=41344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼?', `MaleText_loc7`='¿Qué es eso?', `FemaleText_loc1`='이게 뭐죠?', `FemaleText_loc4`='这是什么？', `FemaleText_loc5`='這是什麼?', `FemaleText_loc7`='¿Qué es eso?' WHERE `ID`=41345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이토록 강력한 무기가 있다니!', `MaleText_loc4`='真是强大的武器！', `MaleText_loc5`='如此強大的武器!', `MaleText_loc7`='¡Un arma tan poderosa!', `FemaleText_loc1`='이토록 강력한 무기가 있다니!', `FemaleText_loc4`='真是强大的武器！', `FemaleText_loc5`='如此強大的武器!', `FemaleText_loc7`='¡Un arma tan poderosa!' WHERE `ID`=41346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 내 앞에서 벌벌 떨겠구나!', `MaleText_loc4`='部落将在我面前战栗！', `MaleText_loc5`='部落將在我面前顫抖!', `MaleText_loc7`='¡La Horda temblará ante mí!', `FemaleText_loc1`='호드가 내 앞에서 벌벌 떨겠군요!', `FemaleText_loc4`='部落将在我面前战栗！', `FemaleText_loc5`='部落將在我面前顫抖!', `FemaleText_loc7`='¡La Horda temblará ante mí!' WHERE `ID`=41347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에게 얼라이언스 강철 맛을 보여주겠다!', `MaleText_loc4`='让部落尝尝联盟钢刃的味道！', `MaleText_loc5`='部落將會嘗到聯盟的利害!', `MaleText_loc7`='¡La Horda probará el acero de la Alianza!', `FemaleText_loc1`='호드에게 얼라이언스 강철 맛을 보여주겠어!', `FemaleText_loc4`='让部落尝尝联盟钢刃的味道！', `FemaleText_loc5`='部落將會嘗到聯盟的利害!', `FemaleText_loc7`='¡La Horda probará el acero de la Alianza!' WHERE `ID`=41348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 절대 승리하지 못한다!', `MaleText_loc4`='部落决不会获胜！', `MaleText_loc5`='部落將會失敗!', `MaleText_loc7`='¡La Horda no puede ganar!', `FemaleText_loc1`='호드는 절대 승리하지 못한다!', `FemaleText_loc4`='部落决不会获胜！', `FemaleText_loc5`='部落將會失敗!', `FemaleText_loc7`='¡La Horda no puede ganar!' WHERE `ID`=41349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 장군의 상자가 땅에 떨어집니다.', `MaleText_loc4`='部落将军的箱子掉在了地上。', `MaleText_loc5`='部落將軍的寶箱掉到了地上。', `MaleText_loc7`='El cofre del general de la Horda cae al suelo.' WHERE `ID`=41350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 볼타르가 쓰러졌소!', `MaleText_loc4`='兄弟们，沃塔倒下了！', `MaleText_loc5`='兄弟們，沃爾塔已經陣亡了!', `MaleText_loc7`='¡Hermanos, Vol''tar ha caído!' WHERE `ID`=41351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라호와 같은 운명을 맞이하지는 않겠다! 죽어라!', `MaleText_loc4`='我不会落得与沃拉琼相同的结局！死吧！', `MaleText_loc5`='我不會和佛拉祖遭受相同的命運!死吧!', `MaleText_loc7`='¡No sufriré el mismo destino que Vaurajo! ¡Muere!' WHERE `ID`=41352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그하르의 분노를 느껴봐라!', `MaleText_loc4`='面对玛格汉的愤怒吧！', `MaleText_loc5`='面對瑪格哈的怒火!', `MaleText_loc7`='¡Enfréntate a la furia de los Mag''har!' WHERE `ID`=41353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 랩터들로부터 겨우 도망쳤나 했는데, 이곳 상황은 더 악화되기 시작했어요.$B$B불평해봤자 무슨 소용이 있나요. 진정한 드워프의 자세로 이놈들을 상대해줘야겠군요!', `MaleText_loc4`='正当我以为我们终于能摆脱那些迅猛龙，喘口气时，这里的情况却变得更糟。$B$B可是抱怨是没用的。我们得像个真正的矮人一样去面对！', `MaleText_loc5`='我們才剛覺得逃離那些迅猛龍可以鬆一口氣，狀況卻變得更糟。$B$B發牢騷也沒用就是了。我們得用矮人的方式來面對!', `MaleText_loc7`='Justo cuando pensaba que tendríamos un respiro al escapar de esos raptores, las cosas se ponen peor por aquí.$B$BPero no sirve de nada quejarse. ¡Nos enfrentaremos a esto como verdaderos enanos!' WHERE `ID`=41354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랩터에 대해서라면 물어보지도 말게. 그냥 물어보지 말게나.', `MaleText_loc4`='别提那些迅猛龙。提也别提。', `MaleText_loc5`='別提跟迅猛龍有關的事。別提就對了。', `MaleText_loc7`='No preguntes sobre los raptores. No preguntes.' WHERE `ID`=41355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 다른 우리의 고향에 오신 것을 환영해요. 저희가 대접해 드릴 것이 더 있으면 좋겠군요.', `FemaleText_loc4`='欢迎来到远离家乡的家园，$c。希望我们能为您献上无比殷勤的款待。', `FemaleText_loc5`='歡迎來到我們不算家園的家園，$c。我希望我們擁有更多可以招待客人。', `FemaleText_loc7`='Te doy la bienvenida al hogar lejos del hogar, $c. Desearía poder ofrecerte más que simple hospitalidad.' WHERE `ID`=41356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 계곡에서는 조심하세요. 적이 사방에 깔렸으니 말이지요!', `FemaleText_loc4`='在谷地里要多加小心，$n。四周到处都是敌人！', `FemaleText_loc5`='在峽谷裡要小心，$n。那有大量的敵人!', `FemaleText_loc7`='Ten cuidado en la vega, $n. ¡Hay enemigos por todas partes!' WHERE `ID`=41357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리아나스, 파는 물건을 보여주십시오.', `MaleText_loc4`='让我看看你出售的货物，莱纳斯。', `MaleText_loc5`='讓我看看你的商品，莉雅納絲。', `MaleText_loc7`='Enséñame tus mercancías, Lyanath.', `FemaleText_loc1`='리아나스, 파는 물건을 보여주세요.', `FemaleText_loc4`='让我看看你出售的货物，莱纳斯。', `FemaleText_loc5`='讓我看看你的商品，莉雅納絲。', `FemaleText_loc7`='Enséñame tus mercancías, Lyanath.' WHERE `ID`=41358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 좀 사고 싶으신가요?', `FemaleText_loc4`='想要做买卖吗？', `FemaleText_loc5`='需要買些什麼嗎?', `FemaleText_loc7`='¿Necesitas comprar algo?' WHERE `ID`=41359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파는 물건을 보여주십시오.', `MaleText_loc4`='请让我看看你出售的货物。', `MaleText_loc5`='請讓我看看你的商品。', `MaleText_loc7`='Enséñame tus mercancías, por favor.', `FemaleText_loc1`='파는 물건을 보여주세요.', `FemaleText_loc4`='请让我看看你出售的货物。', `FemaleText_loc5`='請讓我看看你的商品。', `FemaleText_loc7`='Enséñame tus mercancías, por favor.' WHERE `ID`=41360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비가 전부 망가지셨군요. 그렇죠?', `MaleText_loc4`='东西都弄坏了，嗯？', `MaleText_loc5`='裝備都撞壞了，啊?', `MaleText_loc7`='Material hecho polvo, ¿eh?' WHERE `ID`=41361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고버, 내 보관함을 들여다보고 싶습니다.', `MaleText_loc4`='大胖，我要在我背包里找找。', `MaleText_loc5`='古柏，我需要看一下我的包包。', `MaleText_loc7`='Gargajo, tengo que echarle un vistazo a mi mochila.', `FemaleText_loc1`='고버, 내 보관함을 들여다보고 싶어요.', `FemaleText_loc4`='大胖，我要在我背包里找找。', `FemaleText_loc5`='古柏，我需要看一下我的包包。', `FemaleText_loc7`='Gargajo, tengo que echarle un vistazo a mi mochila.' WHERE `ID`=41362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 어린 바위웅덩이 멀록들은 여기에 버려진 듯합니다.>', `MaleText_loc4`='<这些小鱼人似乎是被遗弃在这里了。>', `MaleText_loc5`='<這些魚人寶寶似乎是被遺棄在這的。>', `MaleText_loc7`='<Parece que han abandonado a esos bebés múrloc.>' WHERE `ID`=41363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 어린 바위웅덩이 멀록들은 여기에 버려진 듯합니다. 곤란한 상황에 부닥친 멀록들을 바다로 데려가면 나가에서 벗어날 기회가 생길지도 모릅니다. 넵툴도 당신이 그래주기를 바란다는 생각이 듭니다.>', `MaleText_loc4`='<这些小岩池鱼人似乎是被遗弃在这里了。现在他们的境遇肯定很糟糕。耐普托一定想让你将他们带回到大海去。他们在那里才有可能躲避开纳迦的捕猎。>', `MaleText_loc5`='<這些石塘的魚人寶寶似乎是被遺棄在這的。你懷疑他們可能有麻煩，奈普吐爾會想要你將他們帶回海洋，在那他們至少還有機會可逃離納迦的魔爪。>', `MaleText_loc7`='<Parece que han abandonado a esos bebés múrloc Pozarroca. Sospechas que tienen problemas y que a Neptul le gustaría que los llevaras de vuelta al océano, donde tendrán una oportunidad de escapar de los nagas.>' WHERE `ID`=41364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어린 바위웅덩이 멀록을 돕습니다.>', `MaleText_loc4`='<帮助岩池鱼人蝌蚪。>', `MaleText_loc5`='<幫助石塘蝌蚪。>', `MaleText_loc7`='<Ayuda a los renacuajos Pozarroca.>', `FemaleText_loc1`='<어린 바위웅덩이 멀록을 돕습니다.>', `FemaleText_loc4`='<帮助岩池鱼人蝌蚪。>', `FemaleText_loc5`='<幫助石塘蝌蚪。>', `FemaleText_loc7`='<Ayuda a los renacuajos Pozarroca.>' WHERE `ID`=41365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어린 바위웅덩이 멀록이 알아서 살아가도록 내버려 둡니다.>', `MaleText_loc4`='<让他们自己保护自己吧。>', `MaleText_loc5`='<讓他們自力救濟。>', `MaleText_loc7`='<Déjalos para que se defiendan a sí mismos.>', `FemaleText_loc1`='<어린 바위웅덩이 멀록이 알아서 살아가도록 내버려 둡니다.>', `FemaleText_loc4`='<让他们自己保护自己吧。>', `FemaleText_loc5`='<讓他們自力救濟。>', `FemaleText_loc7`='<Déjalos para que se defiendan a sí mismos.>' WHERE `ID`=41366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 보병대 제13연대 소속, 레지날드 폴라드라고 합니다.', `MaleText_loc4`='列兵霍金纳多·伯纳德，暴风城步兵团第十三编队……$g阁下:女士;。', `MaleText_loc5`='士兵雷納德·波拉德，第十三旅，暴風城步兵...$g長官:女士;。', `MaleText_loc7`='Soldado Reginald Polard, Decimotercera Brigada, infantería de Ventormenta, $gseñor:señora;.' WHERE `ID`=41367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이곳으로 내려왔습니까?', `MaleText_loc4`='你是怎么下来的？', `MaleText_loc5`='你怎麼來到這下面的?', `MaleText_loc7`='¿Cómo has llegado aquí abajo?', `FemaleText_loc1`='어떻게 이곳으로 내려왔나요?', `FemaleText_loc4`='你是怎么下来的？', `FemaleText_loc5`='你怎麼來到這下面的?', `FemaleText_loc7`='¿Cómo has llegado aquí abajo?' WHERE `ID`=41368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 적들을 감시하고 있었습니다... 호드 함대 말이죠... 그런데 갑자기 어디선가 촉수가 올라와 아군의 배를 감싸더니... 정확히 두 조각으로 부숴버렸습니다!$b$b생존자들은... 물에 빠지자마자 나가에게 사로잡혔죠.$b$b그게 거의 일주일 전에 일어난 일입니다.', `MaleText_loc4`='我们发现了他们……部落的船队……然后突然就不见了，有触手伸出来一把抓住了我们的船……把它折成了两截！$b$b幸存者们……我们一落水就立刻被纳迦抓住。$b$b那是差不多一星期以前的事了。', `MaleText_loc5`='它們曾出現在我們的眼前...部落的船...然後不知哪來的觸手抓住了我們的船...把它捏成兩段!$b$b生還者...我們一接觸到水面就被納迦抓了起來。$b$b那已經是上週的事了。', `MaleText_loc7`='Ya los teníamos a la vista... los barcos de la Horda... Y de la nada aparecieron unos tentáculos que atraparon nuestro barco... ¡lo partieron en dos!$b$bLos supervivientes... fuimos capturados por los nagas en cuanto tocamos el agua.$b$bEso fue hace casi una semana.' WHERE `ID`=41369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가에 대해 말해줄 게 있습니까?', `MaleText_loc4`='关于那些抓你们的人，有什么能告诉我的吗？', `MaleText_loc5`='你可以告訴我多少與你補捉者有關的事?', `MaleText_loc7`='¿Qué puedes contarme sobre tus captores?', `FemaleText_loc1`='나가에 대해 말해줄 게 있나요?', `FemaleText_loc4`='关于那些抓你们的人，有什么能告诉我的吗？', `FemaleText_loc5`='你可以告訴我多少與你補捉者有關的事?', `FemaleText_loc7`='¿Qué puedes contarme sobre tus captores?' WHERE `ID`=41370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상합니다... 나가들이 우리를 살려둘 것이라고는 생각하지 않았으니까요.$b$b나가들은 생존자들 하나하나에게... 진주 거품을 만들어서... 숨쉴 수 있도록 해 줬습니다.$b$b나가들은 매일 사로잡은 포로들을... 어디론가 보냅니다.$b$b그렇게 떠난 포로들은 다시는 볼 수 없었습니다...', `MaleText_loc4`='真是奇怪……从没想过纳迦竟然会设法让我们活下来。$b$b他们弄出这些像珍珠一样的泡泡……一人一个……让我们能够呼吸。$b$b他们每天都会送走一些囚犯……不知道去往哪里。$b$b再也没见过他们……', `MaleText_loc5`='奇怪...我從沒想過納迦會多花力氣讓我們活下來。$b$b他們創造了珍珠泡泡...一人一個...讓我們可以呼吸。$b$b每天都有一批囚犯被他們送去...不知道哪裡。$b$b然後就下落不明了...', `MaleText_loc7`='Fue extraño... Nunca pensé que los nagas se molestarían en mantenernos con vida.$b$bCrearon una especie de burbujas perladas... una por hombre... Las hicieron para que pudiéramos respirar.$b$bTodos los días enviaban a un puñado de prisioneros a... alguna parte.$b$bNunca los volvimos a ver...' WHERE `ID`=41371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 어떻게 도망쳤습니까, 폴라드?', `MaleText_loc4`='你是怎么逃脱的呢，伯纳德？', `MaleText_loc5`='你是如何逃脫的，波拉德?', `MaleText_loc7`='¿Cómo escapaste, Polard?', `FemaleText_loc1`='당신은 어떻게 도망쳤나요, 폴라드?', `FemaleText_loc4`='你是怎么逃脱的呢，伯纳德？', `FemaleText_loc5`='你是如何逃脫的，波拉德?', `FemaleText_loc7`='¿Cómo escapaste, Polard?' WHERE `ID`=41372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하! 난 처음부터 그림토템 부족 편이었지! 어리석은 놈들... 모두 죽을 준비해라!', `MaleText_loc4`='哈哈哈！我与恐怖图腾同在！你们这些傻瓜全都要死！', `MaleText_loc5`='哈哈哈哈哈!我一直都是恐怖圖騰的人!你們這些蠢貨全都會死!', `MaleText_loc7`='¡Jajajajaja! ¡Yo siempre he estado de parte de los Tótem Siniestro! ¡Ustedes, idiotas, van a morir!' WHERE `ID`=41373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 풀려났는지는 모르겠지만, 한 병사가 풀려나서 진주를 깨고... 우리를 구해냈습니다.$b$b그래서 생존자 몇 명은 물 위로 헤엄쳐 올라갔고... 몇 명은 이 동굴을 발견해 헤엄쳐 온 거죠.$b$b그렇지만 끝까지 살아남은 건 저뿐입니다...', `MaleText_loc4`='另一名士兵设法获得了自由，打碎了我们的珍珠……释放了我们。$b$b有人游向了水面……有人看到这座洞穴，并向它游来。$b$b我是唯一一个活下来的……', `MaleText_loc5`='有個士兵不知怎樣逃了出來，打破我們許多人的珍珠...讓我們重獲自由。$b$b有些人朝水面游去...有些看到了這個洞穴，游了過來。$b$b我是唯一活著到這的....', `MaleText_loc7`='Uno de los soldados consiguió liberarse de alguna manera y rompió un puñado de nuestras perlas... nos liberó.$b$bAlgunos nadaron hacia la superficie, otros vimos esta cueva y tratamos de llegar a ella.$b$bYo soy el único que lo consiguió...' WHERE `ID`=41374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! $r|1이잖아;잖아;, 물러서!', `MaleText_loc4`='啊！$r！后退！', `MaleText_loc5`='嘖!後退，$r!', `MaleText_loc7`='¡Aj! ¡Atrás, $r!' WHERE `ID`=41375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대장 테일러와 그의 부하들을 본 적이 있습니까?', `MaleText_loc4`='你有没有见到泰勒上尉和他的部下？', `MaleText_loc5`='你有看到泰勒隊長和他的人嗎?', `MaleText_loc7`='¿Viste al capitán Taylor y a sus hombres?', `FemaleText_loc1`='부대장 테일러와 그의 부하들을 본 적이 있나요?', `FemaleText_loc4`='你有没有见到泰勒上尉和他的部下？', `FemaleText_loc5`='你有看到泰勒隊長和他的人嗎?', `FemaleText_loc7`='¿Viste al capitán Taylor y a sus hombres?' WHERE `ID`=41376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠습니다...$b$b나가들은 매일 새로운 포로들을 데려왔으니까요. 호드든 얼라이언스든 가리지 않았죠.$b$b어떤 포로들은 데려온 날 바로 어디론가 끌고 갔고... 또 어떤 포로들은 저처럼 일주일쯤, 아니면 그보다 더 오래 붙잡아 놓기도 했습니다.', `MaleText_loc4`='说不好……$b$b他们每天都会带来新的士兵。部落和联盟的都有。$b$b有些在来的当天就会被拖走……其它像我一样的，会在那儿待上一个星期……也许更久。', `MaleText_loc5`='很難說...$b$b他們每天都會抓來新的士兵，聯盟和部落的都有。$b$b有些人在當天就被抓到別處去，其他的人，像是我，就在那待了一個星期...或許更久。', `MaleText_loc7`='Ni rastro... $b$bTraían soldados nuevos todos los días. Tanto de la Horda como de la Alianza.$b$bA algunos se los llevaban el mismo día... otros, como yo, nos quedamos toda una semana... quizá más.' WHERE `ID`=41377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이용할 수 있는 나가의 약점은 없습니까? 나가들의 방어선이 허술한 곳이 있습니까?', `MaleText_loc4`='有没有什么弱点可供我们利用？纳迦的防御是否有什么漏洞？', `MaleText_loc5`='有什麼弱點是我們可以利用的嗎?納迦的防衛有漏洞嗎?', `MaleText_loc7`='¿Hay algún punto débil que podamos explotar? ¿Algún agujero en las defensas naga?', `FemaleText_loc1`='우리가 이용할 수 있는 나가의 약점은 없나요? 나가들의 방어선이 허술한 곳이 있나요?', `FemaleText_loc4`='有没有什么弱点可供我们利用？纳迦的防御是否有什么漏洞？', `FemaleText_loc5`='有什麼弱點是我們可以利用的嗎?納迦的防衛有漏洞嗎?', `FemaleText_loc7`='¿Hay algún punto débil que podamos explotar? ¿Algún agujero en las defensas naga?' WHERE `ID`=41378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈도 꾸지 마십시오, $r 친구여.$b$b도망칠 수 있을 때 도망치십시오.$b$b나가들의 수가 너무 많아서... 덤볐다간 목숨을 부지할 수 없을 것입니다...', `MaleText_loc4`='试都别试，$r。$b$b趁还来得及，赶快离开这儿……$b$b有太多人都将……必死无疑……', `MaleText_loc5`='想都別想，$r。$b$b趁你還能跑的時候快跑...$b$b數量太多了...一定會死的。', `MaleText_loc7`='Ni lo intentes, $r.$b$bSal de aquí mientras puedas... $b$bSon demasiados... muerte segura...' WHERE `ID`=41379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피의 의식을 마쳤습니다... 이제 로라무스 탈리페데스가 어디에서 그대를 기다리는지 보입니다.', `FemaleText_loc4`='鲜血仪式已经完成……而且我现在能看到洛拉姆斯·萨里比迪斯正在何处等待着你。', `FemaleText_loc5`='血之祭儀已經完成了...我現在看到了洛拉姆斯·薩里比迪斯正在哪裡等著你。', `FemaleText_loc7`='El ritual de la sangre ha sido completado... y ahora puedo ver dónde te aguarda Loramus Thalimedes.' WHERE `ID`=41380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 좋습니다. 물러나십시오... 좀 지저분해질지도 모릅니다.', `FemaleText_loc4`='很好。退后……别弄得你满身都是。', `FemaleText_loc5`='很好。後退點...這可能沒那麼簡單。', `FemaleText_loc7`='Muy bien. Échate atrás... esto puede ponerse muy feo.' WHERE `ID`=41381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 입을 열게 될거다!', `MaleText_loc4`='你早晚都要开口！', `MaleText_loc5`='你遲早會說的!', `MaleText_loc7`='¡Antes o después hablarás!', `FemaleText_loc1`='조만간 입을 열게 될거다!', `FemaleText_loc4`='你早晚都要开口！', `FemaleText_loc5`='你遲早會說的!', `FemaleText_loc7`='¡Antes o después hablarás!' WHERE `ID`=41382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통을 좋아하면 좋겠군.', `MaleText_loc4`='希望你喜欢痛苦。', `MaleText_loc5`='我希望你喜歡痛苦的感覺。', `MaleText_loc7`='Espero que te guste el dolor.', `FemaleText_loc1`='고통을 좋아하면 좋겠군.', `FemaleText_loc4`='希望你喜欢痛苦。', `FemaleText_loc5`='我希望你喜歡痛苦的感覺。', `FemaleText_loc7`='Espero que te guste el dolor.' WHERE `ID`=41383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 역습해 올 계획이지? 털어놔라, 그러면 고통스럽지 않게 해주마.', `MaleText_loc4`='你们的人准备什么时候发动反攻？告诉我，我就终结你的痛苦。', `MaleText_loc5`='你們計畫著什麼時候反擊?告訴我就給你個痛快。', `MaleText_loc7`='¿Cuándo contraatacará tu gente? Dímelo y pondré fin a tu sufrimiento.', `FemaleText_loc1`='언제 역습해 올 계획이지? 털어놔라, 그러면 고통스럽지 않게 해주마.', `FemaleText_loc4`='你们的人准备什么时候发动反攻？告诉我，我就终结你的痛苦。', `FemaleText_loc5`='你們計畫著什麼時候反擊?告訴我就給你個痛快。', `FemaleText_loc7`='¿Cuándo contraatacará tu gente? Dímelo y pondré fin a tu sufrimiento.' WHERE `ID`=41384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개인적인 원한이 있는 건 아니다. 단지 한곳에 자리 잡지 못하고 계속 쫓겨나는 게 조금 지겨워졌을 뿐이지. 이제 너희가 쫓겨날 차례다.', `MaleText_loc4`='无关私人恩怨。我们只是对那种被驱逐出家园的日子感到有些厌倦。现在轮到我们反击了。', `MaleText_loc5`='沒針對誰。我們只是對被逐出家園感到憤慨。是我們還擊的時候了。', `MaleText_loc7`='No es nada personal. Estamos un poquito cansados de que nos saquen de nuestros hogares. Ahora nos toca a nosotros.', `FemaleText_loc1`='개인적인 원한이 있는 건 아니다. 단지 한곳에 자리 잡지 못하고 계속 쫓겨나는 게 조금 지겨워졌을 뿐이지. 이제 너희가 쫓겨날 차례다.', `FemaleText_loc4`='无关私人恩怨。我们只是对那种被驱逐出家园的日子感到有些厌倦。现在轮到我们反击了。', `FemaleText_loc5`='沒針對誰。我們只是對被逐出家園感到憤慨。是我們還擊的時候了。', `FemaleText_loc7`='No es nada personal. Estamos un poquito cansados de que nos saquen de nuestros hogares. Ahora nos toca a nosotros.' WHERE `ID`=41385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받을 소 같으니라고! 모두 불어!', `MaleText_loc4`='快把一切都说出来，你这没用的蠢牛！', `MaleText_loc5`='把一切都跟我說，你這可悲的東西!', `MaleText_loc7`='¡Cuéntamelo todo, vaca miserable!', `FemaleText_loc1`='저주받을 소 같으니라고! 모두 불어!', `FemaleText_loc4`='快把一切都说出来，你这没用的蠢牛！', `FemaleText_loc5`='把一切都跟我說，你這可悲的東西!', `FemaleText_loc7`='¡Cuéntamelo todo, vaca miserable!' WHERE `ID`=41386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높새바람 봉우리는 우리가 차지했으니 남은 건 노움과 고블린, 그리고 고물 배 한 척 뿐이겠군. 불쌍한 놈들.', `MaleText_loc4`='既然我们已经占领了乱风岗，现在就只剩下那艘愚蠢的驳船。侏儒与地精。你们这些人是多么的可怜。', `MaleText_loc5`='亂風崗現在已經是我們的了，剩下的只剩那艘該死的駁船。地精和哥布林。你的人民真是可悲。', `MaleText_loc7`='Ahora que tenemos Poblado Viento Libre, todo lo que queda es esa estúpida barcaza. Gnomos y goblins. Mira que sois tristes.', `FemaleText_loc1`='높새바람 봉우리는 우리가 차지했으니 남은 건 노움과 고블린, 그리고 고물 배 한 척 뿐이겠군. 불쌍한 놈들.', `FemaleText_loc4`='既然我们已经占领了乱风岗，现在就只剩下那艘愚蠢的驳船。侏儒与地精。你们这些人是多么的可怜。', `FemaleText_loc5`='亂風崗現在已經是我們的了，剩下的只剩那艘該死的駁船。地精和哥布林。你的人民真是可悲。', `FemaleText_loc7`='Ahora que tenemos Poblado Viento Libre, todo lo que queda es esa estúpida barcaza. Gnomos y goblins. Mira que sois tristes.' WHERE `ID`=41387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지겹게도 저항하는군. 네놈을 죽이고 다른 놈에게 답을 들어야겠다.', `MaleText_loc4`='我已经对你的抵抗感到厌倦了。我现在就要杀了你，然后去撬开你其它同伴的嘴巴。', `MaleText_loc5`='我對你的抵抗已經失去耐心了。我現在要殺了你再從你其他的朋友那得到答案。', `MaleText_loc7`='Me estoy cansando de tu resistencia. Voy a matarte ahora y conseguiré las respuestas que busco de uno de tus amigos.', `FemaleText_loc1`='지겹게도 저항하는군. 네놈을 죽이고 다른 놈에게 답을 들어야겠다.', `FemaleText_loc4`='我已经对你的抵抗感到厌倦了。我现在就要杀了你，然后去撬开你其它同伴的嘴巴。', `FemaleText_loc5`='我對你的抵抗已經失去耐心了。我現在要殺了你再從你其他的朋友那得到答案。', `FemaleText_loc7`='Me estoy cansando de tu resistencia. Voy a matarte ahora y conseguiré las respuestas que busco de uno de tus amigos.' WHERE `ID`=41388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난칠 시간 없다! 입을 열지 않겠다면 죽어라!', `MaleText_loc4`='我没时间和你耗！不说就去死吧！', `MaleText_loc5`='我沒這麼多時間跟你耗!不說就死!', `MaleText_loc7`='¡No tengo tiempo para esto! ¡Habla o muere!', `FemaleText_loc1`='장난칠 시간 없다! 입을 열지 않겠다면 죽어라!', `FemaleText_loc4`='我没时间和你耗！不说就去死吧！', `FemaleText_loc5`='我沒這麼多時間跟你耗!不說就死!', `FemaleText_loc7`='¡No tengo tiempo para esto! ¡Habla o muere!' WHERE `ID`=41389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린노어, 아뮬렛 의식을 시작하고 싶습니다.', `MaleText_loc4`='我准备开始护符仪式了，莱诺雷。', `MaleText_loc5`='我想要開始護符儀式，萊諾雷。', `MaleText_loc7`='Me gustaría dar comienzo al ritual del amuleto, Lynnore.', `FemaleText_loc1`='린노어, 아뮬렛 의식을 시작하고 싶어요.', `FemaleText_loc4`='我准备开始护符仪式了，莱诺雷。', `FemaleText_loc5`='我想要開始護符儀式，萊諾雷。', `FemaleText_loc7`='Me gustaría dar comienzo al ritual del amuleto, Lynnore.' WHERE `ID`=41390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라젤리크의 아뮬렛 안에 담긴 힘으로...', `FemaleText_loc4`='以拉瑟莱克护符内的强大力量……', `FemaleText_loc5`='在擁有了拉瑟萊克護符裡的力量下...', `FemaleText_loc7`='¡Con el poder de estos amuletos de Razelikh...' WHERE `ID`=41391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 그대를 라젤리크의 소굴로 인도하노라!', `FemaleText_loc4`='……我将你缚于他的巢穴中！', `FemaleText_loc5`='...我把你丟進他的巢穴!', `FemaleText_loc7`='¡... te confino a su guarida!' WHERE `ID`=41392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시를 확보했다. 아즈쉬르들이 네 이름을 승리의 구호로 외치고 있다. 오늘 너는 많은 존경을 받았노라.', `MaleText_loc4`='城市已被攻陷。艾萨尔向你发出了胜利的恭贺。你今天为自己赢得了足够的尊重。', `MaleText_loc5`='城市已經被圍繞了起來。艾薩伊爾使用你的名字做為他們的勝利吶喊。你今天贏得了無比的尊重。', `MaleText_loc7`='La ciudad ha sido derrotada. Los Azsh''ir claman tu nombre en la victoria. Hoy te has ganado mucho respeto.' WHERE `ID`=41393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 빨리 도시를 탈환할 줄은 몰랐다. 공격을 준비할 시간은 충분할 것 같구나.', `MaleText_loc4`='我没想到能这么快地夺取这座城市。看来我们将有大把时间来准备入侵。', `MaleText_loc5`='我沒想到城鎮會那麼快就被攻陷了。原本以為我們會有更多時間為侵略做出準備。', `MaleText_loc7`='No esperaba que tomáramos la ciudad tan rápido. Al parecer tendremos mucho tiempo para prepararnos para la invasión.' WHERE `ID`=41394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소환 주문을 외울 준비는 되어 있지만, 주문에 사용할 힘의 원천인 나즈샤린의 도가니가 관건입니다. 반드시 유물을 되찾아야만 합니다.', `FemaleText_loc4`='召唤咒语已经就绪，可我们是依靠纳萨林坩埚来汲取法术能量。必须找回这件圣物。', `FemaleText_loc5`='召喚用的咒語已經準備好了，但我們必須依賴納茲夏琳大爐來吸取我們法術的力量。我們必須獲得那個神器。', `FemaleText_loc7`='Los conjuros de invocación están preparados, pero dependíamos del Crisol de Nazsharin para obtener energía para nuestro hechizo. Debemos recuperar el artefacto.' WHERE `ID`=41395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마티아스 쇼 님께서 나이트 엘프를 도우라고 직접 지시하셨죠.', `FemaleText_loc4`='马迪亚斯·肖尔亲自派我来协助暗夜精灵。', `FemaleText_loc5`='馬迪亞斯·肖爾自己指定要我來幫助夜精靈。', `FemaleText_loc7`='Mathias Shaw en persona me eligió para ayudar a los elfos de la noche.' WHERE `ID`=41396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이토록 무거운 짐을 지다니... 그대는 누구인가?', `FemaleText_loc4`='你是谁，$c，要背负如此重担？', `FemaleText_loc5`='你是誰，$c，為何背負如此沉重的負擔?', `FemaleText_loc7`='¿Quién eres, mortal, para llevar tal carga?' WHERE `ID`=41397;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동물의 수호자... 용을 물리친 자... 고대의 용사여...', `FemaleText_loc4`='动物的庇护者……屠龙者……远古之灵的勇士……', `FemaleText_loc5`='動物的保護者...屠龍者...先祖的勇士...', `FemaleText_loc7`='Protector de los animales...  Matador de dragones...  Campeón de los ancestros…' WHERE `ID`=41398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 오랜 친구 노르두가 그대에게 크나큰 선물을 주었구나. 생명의 선물을.', `FemaleText_loc4`='我最亲爱的老友诺尔度赠予了你一件伟大的礼物，$r。生命的礼物。', `FemaleText_loc5`='我親愛的老朋友諾爾度賜給了你一個很棒的禮物，$n。就是生命。', `FemaleText_loc7`='Mi querido amigo Nordu te ha brindado un gran don. El don de la vida.' WHERE `ID`=41399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러나 나는 너에게 그보다도 더 큰 책임을 부여하노라.', `FemaleText_loc4`='而我会给予你一个更加伟大的责任。', `FemaleText_loc5`='但現在我要委託給你一個更大的責任。', `FemaleText_loc7`='Ahora yo te encomiendo una responsabilidad aún mayor.' WHERE `ID`=41400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 손길 덕분에 이 산은 다시 울창해질 것이다. 하지만, 산을 지키고 보호하는 것도 네 몫이다.', `FemaleText_loc4`='由你之手，这座圣山将再次繁茂。守卫它，便是你的责任。', `FemaleText_loc5`='在你的手下，這座山會起死回生。就交給你來保護和防衛它。', `FemaleText_loc7`='Harás que esta montaña vuelva a florecer. Es tuya: protégela y defiéndela.' WHERE `ID`=41401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초목을 가꾸어라. 산을 해하는 자를 몰아내라. 내 이름으로 이를 행하라.', `FemaleText_loc4`='定要使它兴盛。驱逐意欲危害它的敌人，以我之名。', `FemaleText_loc5`='確保它的茁壯。驅走任何想傷害它的人。以我之名為之。', `FemaleText_loc7`='Haz que prospere. Aleja a quienes quieran dañarla. Hazlo en mi nombre.' WHERE `ID`=41402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두 번째 기회는 없을 것이다.', `FemaleText_loc4`='不会有第二次机会了，$r。', `FemaleText_loc5`='不會有第二次機會，$r。', `FemaleText_loc7`='No habrá segundas oportunidades.' WHERE `ID`=41403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 해냈군! 내 눈을 믿을 수 없네... 불길이 사라졌어... 아에시나 님께서 무슨 일을 하신 건가?', `MaleText_loc4`='$n!你做到了！我无法相信自己的眼睛……烈火消失了……艾森娜做了什么？', `MaleText_loc5`='$n!你辦到了!我簡直無法相信自己的眼睛...大火停了...艾森娜做了什麼!?', `MaleText_loc7`='¡$n! ¡Lo has conseguido! No puedo creer lo que ven mis ojos... El Averno ha desaparecido... ¡¿Qué ha hecho Aessina?!' WHERE `ID`=41404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 도와주시기를.', `MaleText_loc4`='愿艾露恩帮助我们。', `MaleText_loc5`='伊露恩幫助我們!', `MaleText_loc7`='Que Elune nos ayude.' WHERE `ID`=41405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 어찌 되겠습니까? 돌발톱은요?', `MaleText_loc4`='我们会有怎样的遭遇？石爪又会有怎样的遭遇？', `MaleText_loc5`='我們會變成什麼樣子?石爪會變成什麼樣子?', `MaleText_loc7`='¿Qué será de nosotros? ¿De Sierra Espolón?' WHERE `ID`=41406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 헬스크림이 태어난 그날을 저주합니다.', `MaleText_loc4`='加尔鲁什·地狱咆哮，我诅咒你出生的那一天。', `MaleText_loc5`='卡爾洛斯·地獄吼，你這惡魔之子。', `MaleText_loc7`='Garrosh Grito Infernal, maldigo el día en el que naciste.' WHERE `ID`=41407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 몰살당할 위험에 처했습니다. 정녕 저희를 도울 이는 아무도 남지 않았단 말입니까?', `MaleText_loc4`='我们在毁灭的边缘摇摆。难道就没人能帮帮我们吗？', `MaleText_loc5`='我們正在瀕臨毀損的邊緣上。沒有人能夠幫助我們了嗎?', `MaleText_loc7`='Estamos al borde de la aniquilación. ¿Es que no hay nadie que pueda ayudarnos?' WHERE `ID`=41408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어의 미래가 어두워 보입니다.', `MaleText_loc4`='卡利姆多未来的情势相当严峻。', `MaleText_loc5`='卡林多的未來看起來是險惡的。', `MaleText_loc7`='El futuro de Kalimdor es bastante negro.' WHERE `ID`=41409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피해 상황은 어떤가, 라즐?', `MaleText_loc4`='拉兹，损伤如何？', `MaleText_loc5`='傷害有多大，拉索?', `MaleText_loc7`='Razzle, ¿cuáles son los daños?' WHERE `ID`=41410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변은 던 모로에 혼돈을 창조해냈네. 이전에는 보지 못했던 막대한 양의 트로그들이 지상에 나타났고, 그 트로그 놈들은 우리의 오랜 적인 서리갈기 트롤을 우리의 정착지에서 정말 가까운 곳으로 몰아내 버렸지.$B$B이 문제를 해결하려고 아이언포지에서 내 산악경비대원들을 이곳에 파견해 주었네.', `MaleText_loc4`='大灾变在丹莫罗引起了混乱。穴居人以我们前所未见的规模成群结队地迁移到地表，把我们的宿敌霜鬃巨魔赶到了离我们居住地更近的地方。$B$B铁炉堡已经派出我的巡山小队来协助解决这一问题。', `MaleText_loc5`='大災變在丹莫洛造成了混亂。來到地面上的穴居怪的數量是我們前所未見的，把我們的老敵人霜鬃食人妖趕到離我們這越來越近。$B$B鐵爐堡已經緊急派出我的巡山公會去幫助解決這個問題。', `MaleText_loc7`='El Cataclismo ha provocado el caos en Dun Morogh. Los troggs han salido a la superficie más numerosos que nunca y obligan a nuestros tradicionales enemigos, los trols Peloescarcha, a acercarse aún más a nuestros asentamientos.$B$BForjaz ha enviado a mi compañía de montaraces para ayudar a solventar los problemas.' WHERE `ID`=41411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래된 잿더미 속에서 피어나는 새로운 삶... 이것이 바로 아에시나 님의 선물이네.$B$B그대가 없었으면 이 기적은 일어나지 않았을 걸세.', `MaleText_loc4`='从过往的灰烬中生出新的生命……这是艾森娜的馈赠。$B$B如果没有你，这奇迹决不会出现。', `MaleText_loc5`='古老灰燼所誕生的新生命...這是艾森娜的禮物。$B$B如果沒有你，這個奇蹟就不會發生。', `MaleText_loc7`='Vida nueva a partir de las cenizas de la vieja... es el regalo de Aessina.$B$BSin ti, este milagro no hubiera sucedido nunca.' WHERE `ID`=41412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고대정령이 고개를 돌려 당신의 머리보다 큰 눈으로 당신을 응시합니다. 그 눈을 들여다보니 마치 깊은 바닷속으로 빠져드는 것 같습니다.>', `MaleText_loc4`='<这个上古生物盯着你。那双眼睛比你的头还要大。望着它们就好象坠入了一片深蓝的海洋。>', `MaleText_loc5`='<先祖轉過來用比你頭還大的眼睛凝視著你。看著它們就像是掉進了深藍大海一樣。>', `MaleText_loc7`='<El ancestro se vuelve para mirarte con unos ojos más grandes que tu cabeza. Mirar en ellos es como caer en un océano profundo y azul.>' WHERE `ID`=41413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 쉬어도 되겠습니까?', `MaleText_loc4`='我能在这儿休息吗？', `MaleText_loc5`='我可以在這休息嗎?', `MaleText_loc7`='¿Puedo descansar aquí?', `FemaleText_loc1`='여기서 쉬어도 될까요?', `FemaleText_loc4`='我能在这儿休息吗？', `FemaleText_loc5`='我可以在這休息嗎?', `FemaleText_loc7`='¿Puedo descansar aquí?' WHERE `ID`=41414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품 좀 있습니까?', `MaleText_loc4`='你这儿有什么补给品吗？', `MaleText_loc5`='你有任何糧食嗎?', `MaleText_loc7`='¿Tienes suministros?', `FemaleText_loc1`='보급품 좀 있나요?', `FemaleText_loc4`='你这儿有什么补给品吗？', `FemaleText_loc5`='你有任何糧食嗎?', `FemaleText_loc7`='¿Tienes suministros?' WHERE `ID`=41415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 끝나고 나면 서리갈기 부족은 트로그들보다 우리를 더 무서워하게 될 거예요. 그리고 이곳을 떠날 수밖에 없게 될 거고요.', `MaleText_loc4`='等我们完成之后，那些霜鬃巨魔会把我们看作是比穴居人更可怕的对手。他们只能离开，别无选择。', `MaleText_loc5`='當我們在這的工作結束後，跟穴居怪比起來，那些霜鬃食人妖會更怕我們。他們唯一的選擇就是離開。', `MaleText_loc7`='Cuando terminemos aquí, esos Peloescarcha nos temerán más que a los troggs. No tendrán más remedio que marcharse.' WHERE `ID`=41416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여.. 여긴 어딥니까? 당신도 그들과 한편입니까?', `MaleText_loc4`='哇——我这是在哪儿？你是和他们一伙的吗？', `MaleText_loc5`='什麼─我在哪?你是暮光之錘的人嗎?', `MaleText_loc7`='¿Qué... dónde estoy? ¿Eres uno de ellos?', `FemaleText_loc1`='여.. 여긴 어디죠? 당신도 그들과 한편인가요?', `FemaleText_loc4`='哇——我这是在哪儿？你是和他们一伙的吗？', `FemaleText_loc5`='什麼─我在哪?你是暮光之錘的人嗎?', `FemaleText_loc7`='¿Qué... dónde estoy? ¿Eres uno de ellos?' WHERE `ID`=41417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 안 끝났습니까?', `MaleText_loc4`='都结束了没有？', `MaleText_loc5`='都結束了嗎?', `MaleText_loc7`='¿Ya ha terminado todo?', `FemaleText_loc1`='아직 안 끝났나요?', `FemaleText_loc4`='都结束了没有？', `FemaleText_loc5`='都結束了嗎?', `FemaleText_loc7`='¿Ya ha terminado todo?' WHERE `ID`=41418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언트리 님께... 돌아가야... 합니다!', `MaleText_loc4`='必须……回到……铁木那里！', `MaleText_loc5`='必須...回報...鐵樹隊長!', `MaleText_loc7`='¡Debo... volver con... Troncoferro!', `FemaleText_loc1`='아이언트리 님께... 돌아가야... 해요!', `FemaleText_loc4`='必须……回到……铁木那里！', `FemaleText_loc5`='必須...回報...鐵樹隊長!', `FemaleText_loc7`='¡Debo... volver con... Troncoferro!' WHERE `ID`=41419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 아니시군요. 밖에 무슨 일이 일어난 겁니까?', `MaleText_loc4`='你不是暮光之锤的人。外面发生什么事了？', `MaleText_loc5`='你不是暮光之錘的人。那裡發生了什麼事?', `MaleText_loc7`='Tú no eres del Martillo Crepuscular. ¿Qué ocurre ahí fuera?', `FemaleText_loc1`='황혼의 망치단이 아니시군요. 밖에 무슨 일이 일어난 거죠?', `FemaleText_loc4`='你不是暮光之锤的人。外面发生什么事了？', `FemaleText_loc5`='你不是暮光之錘的人。那裡發生了什麼事?', `FemaleText_loc7`='Tú no eres del Martillo Crepuscular. ¿Qué ocurre ahí fuera?' WHERE `ID`=41420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심한 화상을 입었습니다.', `MaleText_loc4`='我烧伤了。非常严重。', `MaleText_loc5`='我被燒傷了，很嚴重。', `MaleText_loc7`='Tengo quemaduras. Graves.', `FemaleText_loc1`='심한 화상을 입었어요.', `FemaleText_loc4`='我烧伤了。非常严重。', `FemaleText_loc5`='我被燒傷了，很嚴重。', `FemaleText_loc7`='Tengo quemaduras. Graves.' WHERE `ID`=41421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단... 그들이 소리지르며 도망치는 소리를 들었습니다... 우리가 반격하는 중입니까?', `MaleText_loc4`='暮光之锤……我听见他们尖叫窜逃……我们是在发动反攻吗？', `MaleText_loc5`='暮光之錘...我聽到他們尖叫和逃跑的聲音...我們開始反擊了嗎?', `MaleText_loc7`='El Martillo Crepuscular... Los he oído correr y gritar... ¿Vamos a contraatacar?', `FemaleText_loc1`='황혼의 망치단... 그들이 소리지르며 도망치는 소리를 들었어요... 우리가 반격하는 중인가요?', `FemaleText_loc4`='暮光之锤……我听见他们尖叫窜逃……我们是在发动反攻吗？', `FemaleText_loc5`='暮光之錘...我聽到他們尖叫和逃跑的聲音...我們開始反擊了嗎?', `FemaleText_loc7`='El Martillo Crepuscular... Los he oído correr y gritar... ¿Vamos a contraatacar?' WHERE `ID`=41422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을이... 무너졌습니다! 막을 수가 없었습니다.', `MaleText_loc4`='城镇……被毁了！我们无法阻止他们。', `MaleText_loc5`='城鎮...毀滅了!我們無法阻止他們。', `MaleText_loc7`='¡La ciudad... derruida! No pudimos detenerlos.', `FemaleText_loc1`='마을이... 무너졌어요! 막을 수가 없었어요.', `FemaleText_loc4`='城镇……被毁了！我们无法阻止他们。', `FemaleText_loc5`='城鎮...毀滅了!我們無法阻止他們。', `FemaleText_loc7`='¡La ciudad... derruida! No pudimos detenerlos.' WHERE `ID`=41423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 불의 땅으로 가는 관문을 열었습니다... 아직 희망이 있다고 말해 주십시오!', `MaleText_loc4`='他们打开了通往火焰之地的传送门……告诉我希望还在！', `MaleText_loc5`='他們已經開啟了通往火源之界的傳送門了...告訴我還有希望!', `MaleText_loc7`='Han abierto las puertas que dan a las Tierras de Fuego... ¡Dime que aún hay esperanza!', `FemaleText_loc1`='놈들이 불의 땅으로 가는 관문을 열었어요... 아직 희망이 있다고 말해 주세요!', `FemaleText_loc4`='他们打开了通往火焰之地的传送门……告诉我希望还在！', `FemaleText_loc5`='他們已經開啟了通往火源之界的傳送門了...告訴我還有希望!', `FemaleText_loc7`='Han abierto las puertas que dan a las Tierras de Fuego... ¡Dime que aún hay esperanza!' WHERE `ID`=41424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮습니다, 병사여. 고대정령이 우리와 함께하십니다. 이제 산은 치유되었습니다!', `MaleText_loc4`='振作起来，士兵。远古半神与我们同在，群山得到了治愈！', `MaleText_loc5`='站起來，士兵。先祖與我們同在，高山也已被治癒!', `MaleText_loc7`='En pie, soldado. ¡Los ancestros están con nosotros y la montaña ha sanado!', `FemaleText_loc1`='이제 괜찮아요, 병사여. 고대정령이 우리와 함께하세요. 이제 산은 치유되었습니다!', `FemaleText_loc4`='振作起来，士兵。远古半神与我们同在，群山得到了治愈！', `FemaleText_loc5`='站起來，士兵。先祖與我們同在，高山也已被治癒!', `FemaleText_loc7`='En pie, soldado. ¡Los ancestros están con nosotros y la montaña ha sanado!' WHERE `ID`=41425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 전투 중입니까? 아이언트리 님께 가서 보고해야겠습니다!', `MaleText_loc4`='我们还身陷这场争斗？我得报告给铁木！', `MaleText_loc5`='這一戰還沒打完?我必須向鐵樹隊長回報!', `MaleText_loc7`='¿Todavía seguimos luchando? ¡Tengo que ir a informar a Troncoferro!', `FemaleText_loc1`='아직도 전투 중인가요? 아이언트리 님께 가서 보고해야겠어요!', `FemaleText_loc4`='我们还身陷这场争斗？我得报告给铁木！', `FemaleText_loc5`='這一戰還沒打完?我必須向鐵樹隊長回報!', `FemaleText_loc7`='¿Todavía seguimos luchando? ¡Tengo que ir a informar a Troncoferro!' WHERE `ID`=41426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $c님! 다시 싸우러 가겠습니다!', `MaleText_loc4`='谢谢你，$c！继续作战！', `MaleText_loc5`='謝謝你，$c!回去戰鬥!', `MaleText_loc7`='¡Gracias, $c! ¡De vuelta a la batalla!', `FemaleText_loc1`='감사해요, $c님! 다시 싸우러 가겠어요!', `FemaleText_loc4`='谢谢你，$c！继续作战！', `FemaleText_loc5`='謝謝你，$c!回去戰鬥!', `FemaleText_loc7`='¡Gracias, $c! ¡De vuelta a la batalla!' WHERE `ID`=41427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전세가 역전됐단 말입니까? 다시 싸우러 가야겠습니다!', `MaleText_loc4`='情势逆转了？我得回去作战！', `MaleText_loc5`='情勢逆轉了?我必須回去戰鬥!', `MaleText_loc7`='¿Han cambiado las tornas? ¡Debo volver a la batalla!', `FemaleText_loc1`='전세가 역전됐단 말인가요? 다시 싸우러 가야겠어요!', `FemaleText_loc4`='情势逆转了？我得回去作战！', `FemaleText_loc5`='情勢逆轉了?我必須回去戰鬥!', `FemaleText_loc7`='¿Han cambiado las tornas? ¡Debo volver a la batalla!' WHERE `ID`=41428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼... 혼자서도 아이언트리 님께 돌아갈 수 있을 것 같습니다. 우리는 승리할 수 있습니다!', `MaleText_loc4`='我……我想我一定能回到铁木那里。我们会成功的！', `MaleText_loc5`='我...我想我有辦法回鐵樹隊長那裡。我們一定能獲勝!', `MaleText_loc7`='Creo... creo que podré llegar hasta Troncoferro. ¡Podemos ganar!', `FemaleText_loc1`='혼... 혼자서도 아이언트리 님께 돌아갈 수 있을 것 같아요. 우리는 승리할 수 있어요!', `FemaleText_loc4`='我……我想我一定能回到铁木那里。我们会成功的！', `FemaleText_loc5`='我...我想我有辦法回鐵樹隊長那裡。我們一定能獲勝!', `FemaleText_loc7`='Creo... creo que podré llegar hasta Troncoferro. ¡Podemos ganar!' WHERE `ID`=41429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하시던 일 계속하십시오. 자세한 얘기는 아이언트리 님의 야영지에서 듣겠습니다. 감사합니다!', `MaleText_loc4`='你先出发，我会到铁木的营地那里与你回合。谢谢你！', `MaleText_loc5`='你去吧，我之後會在鐵樹隊長那邊與你碰面。謝謝你!', `MaleText_loc7`='Sigue adelante, me reuniré contigo en el campamento de Troncoferro. ¡Gracias!', `FemaleText_loc1`='하시던 일 계속하세요. 자세한 얘기는 아이언트리 님의 야영지에서 들을게요. 고마워요!', `FemaleText_loc4`='你先出发，我会到铁木的营地那里与你回合。谢谢你！', `FemaleText_loc5`='你去吧，我之後會在鐵樹隊長那邊與你碰面。謝謝你!', `FemaleText_loc7`='Sigue adelante, me reuniré contigo en el campamento de Troncoferro. ¡Gracias!' WHERE `ID`=41430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 도망치고 있단 말입니까? 전선으로 돌아가야겠습니다!', `MaleText_loc4`='暮光之锤的人跑了？我得回到前线上去！', `MaleText_loc5`='暮光之錘正在逃?我必須回到前線去!', `MaleText_loc7`='¿El Martillo Crepuscular huye? ¡Debo volver al frente!', `FemaleText_loc1`='황혼의 망치단이 도망치고 있다고요? 전선으로 돌아가야겠어요!', `FemaleText_loc4`='暮光之锤的人跑了？我得回到前线上去！', `FemaleText_loc5`='暮光之錘正在逃?我必須回到前線去!', `FemaleText_loc7`='¿El Martillo Crepuscular huye? ¡Debo volver al frente!' WHERE `ID`=41431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 무기가 근처에 있습니다. 아이언트리 님의 부대와 재합류할 수 있습니다.', `MaleText_loc4`='我的武器就在附近——我们可以去和铁木会合。', `MaleText_loc5`='我的武器就在附近─我們可以去跟鐵樹隊長會合。', `MaleText_loc7`='Mis armas están cerca... podemos reagruparnos con Troncoferro.', `FemaleText_loc1`='제 무기가 근처에 있어요. 아이언트리 님의 부대와 재합류할 수 있습니다.', `FemaleText_loc4`='我的武器就在附近——我们可以去和铁木会合。', `FemaleText_loc5`='我的武器就在附近─我們可以去跟鐵樹隊長會合。', `FemaleText_loc7`='Mis armas están cerca... podemos reagruparnos con Troncoferro.' WHERE `ID`=41432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시덥잖은 승리 몇 번 해봤자 소용없다. 황혼의 망치단의 힘은 절대적이니까!', `MaleText_loc4`='你们那不起眼的小胜利根本算不了什么。暮光之锤的力量是无可匹敌的！', `MaleText_loc5`='你們這短暫的勝利不過是困獸之鬥。暮光之錘的神力是絕對的!', `MaleText_loc7`='Tus pequeños triunfos no han sido más que minucias. ¡El poder del Martillo Crepuscular es absoluto!' WHERE `ID`=41433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발가라스?! 그리고 다른 적들이... 네놈들은 이미 죽었잖아! 이게 무슨 사악한 속임수란 말인가?', `MaleText_loc4`='巴尔加拉斯？！还有其他人……你们全都死了！这到底是什么邪恶的伎俩？', `MaleText_loc5`='巴爾加拉斯?!還有其他人...你們都死了!這是什麼邪惡的把戲?', `MaleText_loc7`='¡¿Balgaras?! Y los demás... ¡Estabais todos muertos! ¿Qué oscuro truco es este?' WHERE `ID`=41434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈다라 전망대, 전투의 흉터 계곡, 돌발톱 봉우리, 탈다라 숲으로 돌아가지 않으면 히포그리프에서 떨어집니다!', `MaleText_loc4`='返回萨达拉瞭望台、战痕谷、石爪峰或萨达拉树林，否则你的角鹰兽会把你丢下去！', `MaleText_loc5`='回到薩歐達拉瞰臺、戰痕山谷、石爪峰或薩歐達拉樹林，不然你的角鷹獸將把你丟下去。', `MaleText_loc7`='¡Regresa al Mirador de Thal''darah, al Valle Marca de Guerra, a la Cima del Espolón o a la Arboleda de Thal''darah o tu hipogrifo te dejará caer!' WHERE `ID`=41435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타십시오!', `MaleText_loc4`='上来！', `MaleText_loc5`='上來!', `MaleText_loc7`='¡Sube!', `FemaleText_loc1`='타세요!', `FemaleText_loc4`='上来！', `FemaleText_loc5`='上來!', `FemaleText_loc7`='¡Sube!' WHERE `ID`=41436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 전부 폭발할 겁니다! 갑시다!', `MaleText_loc4`='这地方快要爆炸了！快跑！', `MaleText_loc5`='這整個地方就要爆炸了!我們走!', `MaleText_loc7`='¡Este lugar va a saltar por los aires! ¡Vamos!', `FemaleText_loc1`='이곳은 전부 폭발할 거예요! 갑시다!', `FemaleText_loc4`='这地方快要爆炸了！快跑！', `FemaleText_loc5`='這整個地方就要爆炸了!我們走!', `FemaleText_loc7`='¡Este lugar va a saltar por los aires! ¡Vamos!' WHERE `ID`=41437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프에 타십시오. 시간이 많지 않습니다!', `MaleText_loc4`='快到我角鹰兽背上来。我们没多少时间！', `MaleText_loc5`='上來我的角鷹獸。我們時間不多了!', `MaleText_loc7`='Sube a mi hipogrifo. ¡No tenemos mucho tiempo!', `FemaleText_loc1`='히포그리프에 타세요. 시간이 많지 않아요!', `FemaleText_loc4`='快到我角鹰兽背上来。我们没多少时间！', `FemaleText_loc5`='上來我的角鷹獸。我們時間不多了!', `FemaleText_loc7`='Sube a mi hipogrifo. ¡No tenemos mucho tiempo!' WHERE `ID`=41438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 손을 잡으십시오, 어린 드루이드여.', `MaleText_loc4`='抓住我的手，年轻人。', `MaleText_loc5`='年輕人，拉住我的手。', `MaleText_loc7`='Dame la mano, joven.', `FemaleText_loc1`='제 손을 잡으세요, 어린 드루이드여.', `FemaleText_loc4`='抓住我的手，年轻人。', `FemaleText_loc5`='年輕人，拉住我的手。', `FemaleText_loc7`='Dame la mano, joven.' WHERE `ID`=41439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈다라 스승님께서 그대를 구하라고 저를 보내셨습니다. 올라타십시오!', `MaleText_loc4`='萨达拉大师派我来营救你。快上来！', `MaleText_loc5`='薩歐達拉大師派我來救你。快爬上來!', `MaleText_loc7`='El maestro Thal''darah me ha enviado a rescatarte. ¡Sube!', `FemaleText_loc1`='탈다라 스승님께서 그대를 구하라고 저를 보내셨어요. 올라타세요!', `FemaleText_loc4`='萨达拉大师派我来营救你。快上来！', `FemaleText_loc5`='薩歐達拉大師派我來救你。快爬上來!', `FemaleText_loc7`='El maestro Thal''darah me ha enviado a rescatarte. ¡Sube!' WHERE `ID`=41440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희를 구해주실 분 없습니까?', `MaleText_loc4`='没人能来帮帮我们吗？', `MaleText_loc5`='沒人能幫助我們嗎?', `MaleText_loc7`='¿No va a ayudarnos nadie?', `FemaleText_loc1`='저희를 구해주실 분 없습니까?', `FemaleText_loc4`='没人能来帮帮我们吗？', `FemaleText_loc5`='沒人能幫助我們嗎?', `FemaleText_loc7`='¿No va a ayudarnos nadie?' WHERE `ID`=41441;
