UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베푸신 친절을 절대 잊지 않겠습니다.', `MaleText_loc4`='我永远不会忘记你的善举。', `MaleText_loc5`='我永遠不會忘記這個恩惠的。', `MaleText_loc7`='Nunca olvidaré este acto de amabilidad.', `FemaleText_loc1`='베푸신 친절을 절대 잊지 않겠습니다.', `FemaleText_loc4`='我永远不会忘记你的善举。', `FemaleText_loc5`='我永遠不會忘記這個恩惠的。', `FemaleText_loc7`='Nunca olvidaré este acto de amabilidad.' WHERE `ID`=41447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빚은 언젠가 꼭 갚겠습니다.', `MaleText_loc4`='总有一天，我会报答你。', `MaleText_loc5`='我有天一定會報答你的恩情。', `MaleText_loc7`='Algún día te devolveré el favor.', `FemaleText_loc1`='이 빚은 언젠가 꼭 갚겠습니다.', `FemaleText_loc4`='总有一天，我会报答你。', `FemaleText_loc5`='我有天一定會報答你的恩情。', `FemaleText_loc7`='Algún día te devolveré el favor.' WHERE `ID`=41448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희를 위해 하신 일은 다르나서스에 있는 모두에게 알리겠습니다.', `MaleText_loc4`='达纳苏斯的所有人都会知道你为我们所做的。', `MaleText_loc5`='整個達納蘇斯都將知道你為我們做了什麼。', `MaleText_loc7`='Todo Darnassus sabrá lo que has hecho por nosotros.', `FemaleText_loc1`='저희를 위해 하신 일은 다르나서스에 있는 모두에게 알리겠습니다.', `FemaleText_loc4`='达纳苏斯的所有人都会知道你为我们所做的。', `FemaleText_loc5`='整個達納蘇斯都將知道你為我們做了什麼。', `FemaleText_loc7`='Todo Darnassus sabrá lo que has hecho por nosotros.' WHERE `ID`=41449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 끝장이라고 생각했습니다!', `MaleText_loc4`='我以为我完蛋了！', `MaleText_loc5`='我以為我完蛋了!', `MaleText_loc7`='¡Creía que me había llegado la hora!', `FemaleText_loc1`='이젠 끝장이라고 생각했습니다!', `FemaleText_loc4`='我以为我完蛋了！', `FemaleText_loc5`='我以為我完蛋了!', `FemaleText_loc7`='¡Creía que me había llegado la hora!' WHERE `ID`=41450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 높이 날 수 있을까요?', `MaleText_loc4`='我们能飞得更高一些吗？', `MaleText_loc5`='我們可以飛高一點嗎?', `MaleText_loc7`='¿Podríamos volar más alto?', `FemaleText_loc1`='좀 더 높이 날 수 있을까요?', `FemaleText_loc4`='我们能飞得更高一些吗？', `FemaleText_loc5`='我們可以飛高一點嗎?', `FemaleText_loc7`='¿Podríamos volar más alto?' WHERE `ID`=41451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정 영웅이십니다.', `MaleText_loc4`='你真是位英雄。', `MaleText_loc5`='你是個英雄。', `MaleText_loc7`='Eres tan valiente.', `FemaleText_loc1`='진정 영웅이십니다.', `FemaleText_loc4`='你真是位英雄。', `FemaleText_loc5`='你是個英雄。', `FemaleText_loc7`='Eres tan valiente.' WHERE `ID`=41452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 그대가 제 목숨을 구하셨습니다.', `MaleText_loc4`='谢谢你。你救了我一命。', `MaleText_loc5`='謝謝你，你救了我一命。', `MaleText_loc7`='Gracias. Me has salvado la vida.', `FemaleText_loc1`='감사합니다. 그대가 제 목숨을 구하셨습니다.', `FemaleText_loc4`='谢谢你。你救了我一命。', `FemaleText_loc5`='謝謝你，你救了我一命。', `FemaleText_loc7`='Gracias. Me has salvado la vida.' WHERE `ID`=41453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상에는 그대 같은 영웅이 더 많이 있어야 합니다.', `MaleText_loc4`='我们的世界需要更多像你这样的英雄。', `MaleText_loc5`='我們世界需要多一點像你這樣的英雄。', `MaleText_loc7`='Nuestro mundo necesita más valientes como tú.', `FemaleText_loc1`='이 세상에는 그대 같은 영웅이 더 많이 있어야 합니다.', `FemaleText_loc4`='我们的世界需要更多像你这样的英雄。', `FemaleText_loc5`='我們世界需要多一點像你這樣的英雄。', `FemaleText_loc7`='Nuestro mundo necesita más valientes como tú.' WHERE `ID`=41454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 갚지 못할 빚을 져버렸습니다.', `MaleText_loc4`='我欠你的永远还不清，朋友。', `MaleText_loc5`='我永遠都有欠於你，我的朋友。', `MaleText_loc7`='Estoy en deuda contigo para toda la vida, camarada.', `FemaleText_loc1`='영원히 갚지 못할 빚을 져버렸습니다.', `FemaleText_loc4`='我欠你的永远还不清，朋友。', `FemaleText_loc5`='我永遠都有欠於你，我的朋友。', `FemaleText_loc7`='Estoy en deuda contigo para toda la vida, camarada.' WHERE `ID`=41455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께서 그대를 지켜보시길.', `MaleText_loc4`='愿艾露恩护佑你。', `MaleText_loc5`='願伊露恩保護你。', `MaleText_loc7`='Que Elune te cuide.', `FemaleText_loc1`='엘룬께서 그대를 지켜보시길.', `FemaleText_loc4`='愿艾露恩护佑你。', `FemaleText_loc5`='願伊露恩保護你。', `FemaleText_loc7`='Que Elune te cuide.' WHERE `ID`=41456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사제 몇 명을 보내 당신을 도와드리겠습니다. 다가오는 전투에 필요한 동맹을 소환할 수 있도록 신속히 유물을 찾아 주시지요.', `FemaleText_loc4`='我会派我的祭司来帮助你。尽快找到神器，这样我才能开始召唤援军，来应对即将到来的战争。', `FemaleText_loc5`='我會派一些我的女牧師來幫助你。趕快找到神器，讓我能趕快召喚我們的盟友，為接下來的戰爭做準備。', `FemaleText_loc7`='Enviaré a algunas de mis sacerdotisas a ayudarte. Encuentra el artefacto rápidamente para que pueda empezar a convocar a nuestros aliados para las batallas que están por venir.' WHERE `ID`=41457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하 중 최고의 실력을 갖춘 자들과 함께할 것이다. 걱정 말라, 여전사여. 빨리 돌아오너라. 어서 바다사냥꾼을 잡고 싶으니 말이다.', `MaleText_loc4`='我的精英良将会任你调遣，别担心，女武士。尽快回来找我们——我已经迫不及待想要开始追击猎潮者了。', `MaleText_loc5`='戰鬥仕女，不用擔心，我將會把一些我這最好的人給你。趕快回到我們這─我等不及要獵殺獵潮者了。', `MaleText_loc7`='Tendrás a algunos de mis mejores hombres, no te preocupes, doncella de batalla. Regresa a nosotros rápidamente, estoy deseando dar caza al Cazamareas.' WHERE `ID`=41458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군을 보내 주겠다, 여전사여. 내 이미 크발디르를 모아 네스피라 안에서 일하게 할 생각이었다. 그러니 아주 시기적절하지.', `MaleText_loc4`='你会有援军的，女武士。我已经打算集结克瓦迪尔人去奈瑟匹拉工作了，所以你的时机刚刚好。', `MaleText_loc5`='你會得到你的增援，戰鬥仕女。我已經決定要俘虜科瓦迪爾在奈斯畢拉當工人了，所以對你來說時間點剛剛好。', `MaleText_loc7`='Tendrás los refuerzos que pides, doncella de batalla. Ya tenía la intención de reunir a los Kvaldir para que trabajen en Nespirah, así que vienes en el momento oportuno.' WHERE `ID`=41459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈샤린의 도가니를 되찾을 생각입니다. 저를 도와줄 전사들이 있으십니까?', `MaleText_loc4`='我正要去找纳萨林坩埚。你有战士能助我一臂之力吗？', `MaleText_loc5`='我的狩獵目標是納茲夏琳大爐。你有戰士能夠幫助我嗎?', `MaleText_loc7`='Voy a cazar el Crisol de Nazsharin. ¿Tienes guerreros que me puedan ayudar?', `FemaleText_loc1`='나즈샤린의 도가니를 되찾을 생각이에요. 저를 도와줄 전사들이 있나요?', `FemaleText_loc4`='我正要去找纳萨林坩埚。你有战士能助我一臂之力吗？', `FemaleText_loc5`='我的狩獵目標是納茲夏琳大爐。你有戰士能夠幫助我嗎?', `FemaleText_loc7`='Voy a cazar el Crisol de Nazsharin. ¿Tienes guerreros que me puedan ayudar?' WHERE `ID`=41460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎을 꿇어라!', `MaleText_loc4`='跪下！', `MaleText_loc5`='跪下!', `MaleText_loc7`='¡De rodillas!' WHERE `ID`=41461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 기운이시여, 손을 빌려 주십시오!', `MaleText_loc4`='生命之魂，给我你的力量！', `MaleText_loc5`='生命之靈，助我一臂之力!', `MaleText_loc7`='¡Espíritu de la vida, préstame tu ayuda!' WHERE `ID`=41462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 피조물과 말할 수 있도록 명료함을 주십시오!', `MaleText_loc4`='让我能清楚地与我面前的生灵对话！', `MaleText_loc5`='賦予我和這生物對話的能力!', `MaleText_loc7`='¡Concédeme la claridad a la hora de hablar con esta criatura!' WHERE `ID`=41463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지치유사 두아른이 안절부절못합니다.', `MaleText_loc4`='大地治愈者达鲁不安的踱着步。', `MaleText_loc5`='大地治癒者杜亞恩焦躁地走來走去。', `MaleText_loc7`='El ensalmador de la tierra Duarn se remueve incómodo.' WHERE `ID`=41464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 일도 일어나지 않는군... 무언가 대화를 막고 있는 게 틀림없소.', `MaleText_loc4`='什么都没有发生……一定有东西在阻止我与她交流。', `MaleText_loc5`='什麼都沒發生...一定有什麼在阻止我與她對話。', `MaleText_loc7`='No sucede nada... algo debe impedirme que hable con ella.' WHERE `ID`=41465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 피조물은... 꽤 나이가 들었소. 그리고 아주 현명하오. 네스피라와 이야기할 수만 있다면 바쉬르와 나가에 대해 많은 것을 알 수 있을 것 같소.', `MaleText_loc4`='这个生灵……她相当年迈且非常睿智。要是我们能与奈瑟匹拉交谈的话，我们就能了解很多与瓦丝琪尔和纳迦有关的事。', `MaleText_loc5`='這個生物...她年齡頗大，也很睿智。要是我們能和奈斯畢拉交談，就能對瓦許伊爾和納迦有更深入的瞭解。', `MaleText_loc7`='Esa criatura... es bastante anciana y muy sabia. Si pudiéramos hablar con Nespirah aprenderíamos mucho sobre Vashj''ir y los nagas.' WHERE `ID`=41466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제든지 시작하십시오, 두아른.', `MaleText_loc4`='你准备好就可以开始了，达鲁。', `MaleText_loc5`='等你準備好，杜亞恩。', `MaleText_loc7`='Cuando estés listo, Duarn.', `FemaleText_loc1`='언제든지 시작하세요, 두아른.', `FemaleText_loc4`='你准备好就可以开始了，达鲁。', `FemaleText_loc5`='等你準備好，杜亞恩。', `FemaleText_loc7`='Cuando estés listo, Duarn.' WHERE `ID`=41467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 모든 크발디르에게 교훈이 되었겠지. 너희는 나약하다! 아즈샤라 님께 맞서면 죽음만이 있을 뿐이다.', `MaleText_loc4`='让这成为所有克瓦迪尔人的教训。你太弱了！面对艾萨拉只会为你带来死亡。', `MaleText_loc5`='讓這成為所有科瓦迪爾的一場教訓。你們太弱了!反抗艾薩拉所帶來的只有死亡。', `MaleText_loc7`='Que esto sea una lección para todos los Kvaldir. ¡Son débiles! Enfrentarse a Azshara supone la muerte.' WHERE `ID`=41468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 하찮은 안개 속으로 조용히 기어들어가거라. 다시 나오면 하나도 빠짐없이 없애줄 테니.', `MaleText_loc4`='逃回你那可悲的迷雾中去吧。要是胆敢回来，我们就要把你们杀得一个不剩。', `MaleText_loc5`='躲回你們那可悲的霧裡。回去後並讓我們把你們殺得乾乾淨淨。', `MaleText_loc7`='Arrastrense de regreso a su patética niebla. Vuelvan aquí y les mataremos a todos y a cada uno de ustedes.' WHERE `ID`=41469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 낡은 여관이 볼품없긴 해도, 훌륭한 요새 역할을 수행하고 있습니다.', `MaleText_loc4`='这间破旧的旅馆从外面看已经惨不忍睹，不过倒是个理想的据点。', `MaleText_loc5`='這間老舊旅館雖然看起來不怎麼樣，卻是個不錯的要塞據點。', `MaleText_loc7`='Esta vieja posada está hecha polvo, pero sería una buena fortaleza.' WHERE `ID`=41470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!', `FemaleText_loc1`='감사해요!', `FemaleText_loc4`='谢谢你！', `FemaleText_loc5`='謝謝你!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=41471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사합니다!', `MaleText_loc4`='是你救了我一命！', `MaleText_loc5`='你救了我一命!', `MaleText_loc7`='¡Me has salvado la vida!', `FemaleText_loc1`='구해주셔서 감사해요!', `FemaleText_loc4`='是你救了我一命！', `FemaleText_loc5`='你救了我一命!', `FemaleText_loc7`='¡Me has salvado la vida!' WHERE `ID`=41472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지저분한 곳에서 벗어났으면 좋겠습니다.', `MaleText_loc4`='我太愿意离开这鬼地方了。', `MaleText_loc5`='能逃離這個地獄我會很高興的。', `MaleText_loc7`='Me alegraré cuando salga de este agujero infernal.', `FemaleText_loc1`='이 지저분한 곳에서 벗어났으면 좋겠어요.', `FemaleText_loc4`='我太愿意离开这鬼地方了。', `FemaleText_loc5`='能逃離這個地獄我會很高興的。', `FemaleText_loc7`='Me alegraré cuando salga de este agujero infernal.' WHERE `ID`=41473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 우리에게 무슨 짓을 했는지 상상도 못할 겁니다...', `MaleText_loc4`='你无法想象我们所经历的一切……', `MaleText_loc5`='你不瞭解他們讓我們經歷了什麼...', `MaleText_loc7`='No tienes ni idea de lo que nos han hecho pasar...', `FemaleText_loc1`='그들이 우리에게 무슨 짓을 했는지 상상도 못할 거예요...', `FemaleText_loc4`='你无法想象我们所经历的一切……', `FemaleText_loc5`='你不瞭解他們讓我們經歷了什麼...', `FemaleText_loc7`='No tienes ni idea de lo que nos han hecho pasar...' WHERE `ID`=41474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가는 추악한 괴물입니다!', `MaleText_loc4`='纳迦简直是恶魔！', `MaleText_loc5`='納迦是怪物!', `MaleText_loc7`='¡Los nagas son monstruos!', `FemaleText_loc1`='나가는 추악한 괴물이에요!', `FemaleText_loc4`='纳迦简直是恶魔！', `FemaleText_loc5`='納迦是怪物!', `FemaleText_loc7`='¡Los nagas son monstruos!' WHERE `ID`=41475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 갚지 못할 빚을 졌습니다, 영웅이시여.', `MaleText_loc4`='我欠你的永远还不清，英雄。', `MaleText_loc5`='這個人情我永遠也還不了，英雄。', `MaleText_loc7`='Estaré en deuda contigo eternamente, $ghéroe:heroína;.', `FemaleText_loc1`='영원히 갚지 못할 빚을 졌어요, 영웅이시여.', `FemaleText_loc4`='我欠你的永远还不清，英雄。', `FemaleText_loc5`='這個人情我永遠也還不了，英雄。', `FemaleText_loc7`='Estaré en deuda contigo eternamente, $ghéroe:heroína;.' WHERE `ID`=41476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!', `FemaleText_loc1`='감사해요!', `FemaleText_loc4`='谢谢你！', `FemaleText_loc5`='謝謝你!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=41477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 구해주셨군요!', `MaleText_loc4`='是你救了我一命！', `MaleText_loc5`='你救了我一命!', `MaleText_loc7`='¡Me has salvado la vida!', `FemaleText_loc1`='저를 구해주셨어요!', `FemaleText_loc4`='是你救了我一命！', `FemaleText_loc5`='你救了我一命!', `FemaleText_loc7`='¡Me has salvado la vida!' WHERE `ID`=41478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 우리에게 무슨 짓을 했는지 상상도 못할 겁니다...', `MaleText_loc4`='你无法想象我们所经历的一切……', `MaleText_loc5`='你不瞭解他們讓我們經歷了什麼...', `MaleText_loc7`='No tienes ni idea de lo que nos han hecho pasar...', `FemaleText_loc1`='그들이 우리에게 무슨 짓을 했는지 상상도 못할 거예요...', `FemaleText_loc4`='你无法想象我们所经历的一切……', `FemaleText_loc5`='你不瞭解他們讓我們經歷了什麼...', `FemaleText_loc7`='No tienes ni idea de lo que nos han hecho pasar...' WHERE `ID`=41479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지저분한 곳에서 벗어났으면 좋겠습니다.', `MaleText_loc4`='我太愿意离开这鬼地方了。', `MaleText_loc5`='能逃離這個地獄我會很高興的。', `MaleText_loc7`='Me alegro de haber salir de ese agujero infernal.', `FemaleText_loc1`='이 지저분한 곳에서 벗어났으면 좋겠어요.', `FemaleText_loc4`='我太愿意离开这鬼地方了。', `FemaleText_loc5`='能逃離這個地獄我會很高興的。', `FemaleText_loc7`='Me alegro de haber salir de ese agujero infernal.' WHERE `ID`=41480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가는 추악한 괴물입니다!', `MaleText_loc4`='纳迦简直是恶魔！', `MaleText_loc5`='納迦是殘酷的怪物!', `MaleText_loc7`='¡Los nagas son monstruos!', `FemaleText_loc1`='나가는 추악한 괴물이에요!', `FemaleText_loc4`='纳迦简直是恶魔！', `FemaleText_loc5`='納迦是殘酷的怪物!', `FemaleText_loc7`='¡Los nagas son monstruos!' WHERE `ID`=41481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 갚지 못할 빚을 졌군요, 영웅이시여.', `MaleText_loc4`='我欠你的永远还不清，英雄。', `MaleText_loc5`='這個人情我永遠也還不了，英雄。', `MaleText_loc7`='Estaré en deuda contigo eternamente, $ghéroe:heroína;.', `FemaleText_loc1`='영원히 갚지 못할 빚을 졌어요, 영웅이시여.', `FemaleText_loc4`='我欠你的永远还不清，英雄。', `FemaleText_loc5`='這個人情我永遠也還不了，英雄。', `FemaleText_loc7`='Estaré en deuda contigo eternamente, $ghéroe:heroína;.' WHERE `ID`=41482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 없는 동안에 그들이 공격해 왔습니다... 제독님께서는 전사하셨습니다. 남은 병력은 동굴로 후퇴했으니, 어서 대피하셔야 합니다.', `MaleText_loc4`='他们在你离开时发动了攻击……首领在战斗中倒下了。其它人都退进了洞里，你也应该这么做。', `MaleText_loc5`='他們趁你不在時發動了攻擊...上將不幸陣亡了。剩下的人撤退到了洞穴...你最好也這麼做。', `MaleText_loc7`='Atacaron mientras no estabas... El almirante no lo consiguió. Los demás se retiraron a la cueva. Tú deberías hacer lo mismo.', `FemaleText_loc1`='당신이 없는 동안에 그들이 공격해 왔어요... 제독님께서는 전사하셨어요. 남은 병력은 동굴로 후퇴했으니, 어서 대피하셔야 해요.', `FemaleText_loc4`='他们在你离开时发动了攻击……首领在战斗中倒下了。其它人都退进了洞里，你也应该这么做。', `FemaleText_loc5`='他們趁你不在時發動了攻擊...上將不幸陣亡了。剩下的人撤退到了洞穴...你最好也這麼做。', `FemaleText_loc7`='Atacaron mientras no estabas... El almirante no lo consiguió. Los demás se retiraron a la cueva. Tú deberías hacer lo mismo.' WHERE `ID`=41483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기뻐해라. 네놈이 가장 먼저 죽게 될 테니까. 우리는 카즈 모단을 휩쓸고 불태워 모두 잿더미로 만들어버릴 것이다.', `MaleText_loc4`='狂喜吧，因为你将第一个死去。我们会横扫卡兹莫丹，将一切烧成灰烬。', `MaleText_loc5`='欣喜吧，因為你將會是第一個先赴黃泉的人。我們會掃蕩卡茲莫丹，將一切都燒為灰燼。', `MaleText_loc7`='Alegraos, porque seréis los primeros en morir. Arrasaremos Khaz Modan y lo reduciremos a cenizas.' WHERE `ID`=41484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 몇 번이나 없애야 하든 상관없다... 네놈들을 모두 처치하고 이 땅을 구하겠다!', `MaleText_loc4`='我不在乎我得把你杀死多少回……为了救这片土地，我可以拿去你们所有人的生命！', `MaleText_loc5`='我不在乎到底要殺你幾次才夠...為了拯救這塊土地，就算要對付你們全部我也不怕!', `MaleText_loc7`='No me importa cuántas veces tenga que mataros... ¡Os mataré a todos para salvar esta tierra!' WHERE `ID`=41485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다. 우리도 싸울 거예요!', `FemaleText_loc4`='没错，我们也一样！', `FemaleText_loc5`='對，我們也是!', `FemaleText_loc7`='¡Sí, y nosotros también!' WHERE `ID`=41486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기를 보십시오! 크롬가르 열기구가 숲으로 향하는군요! 서둘러야겠습니다!', `MaleText_loc4`='看那儿！克罗姆加热气球朝林地飞去了！我们得赶快！', `MaleText_loc5`='看那裡!克羅姆加汽球正在朝林地前進!我們必須儘快!', `MaleText_loc7`='¡Mira eso! ¡El globo de Krom''gar viene hacia la arboleda! ¡Debemos apresurarnos!' WHERE `ID`=41487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었습니다. 숲과 함께 저희의 꿈과 희망이 함께 파괴되었습니다.', `MaleText_loc4`='我们来得太迟了。林地已经被毁，一起被毁的还有我们的希望和梦想。', `MaleText_loc5`='太遲了。林地已經被摧毀，連同我們的希望和夢想一起。', `MaleText_loc7`='Demasiado tarde. La arboleda ha sido destruida y con ella han muerto nuestros sueños y esperanzas.' WHERE `ID`=41488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 끔찍한 짓을 저지른 호드는 대가를 치러야 합니다. 이번 사건의 책임은 헬스크림이 져야 합니다!', `MaleText_loc4`='部落将为他们的残暴付出代价。地狱咆哮必须对这罪行负责！', `MaleText_loc5`='部落將為此暴行付出代價。地獄吼必須為此罪孽負責!', `MaleText_loc7`='La Horda pagará por esta atrocidad. ¡Grito Infernal debe responder por este crimen!' WHERE `ID`=41489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 웬 횡재인가! 제물이 알아서 제단 위로 떨어지다니!', `MaleText_loc4`='真是好运！贡品竟把自己扔上了祭坛！', `MaleText_loc5`='多麼好運啊!祭品自己送上祭壇了!', `MaleText_loc7`='¡Qué suerte! ¡Las ofrendas se arrojan solas al altar!' WHERE `ID`=41490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격! 아무도 살려두지 마라!', `MaleText_loc4`='进攻！不留活口！', `MaleText_loc5`='攻擊!別留活口!', `MaleText_loc7`='¡ATAQUEN! ¡NO DEJEN SOBREVIVIENTES!' WHERE `ID`=41491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카즈 모단을 위하여!', `MaleText_loc4`='为了卡兹莫丹！', `MaleText_loc5`='為了卡茲莫丹!', `MaleText_loc7`='¡POR KHAZ MODAN!', `FemaleText_loc1`='카즈 모단을 위하여!', `FemaleText_loc4`='为了卡兹莫丹！', `FemaleText_loc5`='為了卡茲莫丹!', `FemaleText_loc7`='¡POR KHAZ MODAN!' WHERE `ID`=41492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타 버려라아아아...', `MaleText_loc4`='烧吧……', `MaleText_loc5`='燒吧...', `MaleText_loc7`='Ardeeeeeeed...' WHERE `ID`=41493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살덩이, 살아 움직이는 살덩이야...', `MaleText_loc4`='肉，鲜活的肉……', `MaleText_loc5`='血肉，活生生的血肉...', `MaleText_loc7`='Carne, carne palpitante...' WHERE `ID`=41494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길에 네 몸을 맡겨라.', `MaleText_loc4`='把你自己献给火焰。', `MaleText_loc5`='將你自己獻給火焰。', `MaleText_loc7`='Entregaos a la llama.' WHERE `ID`=41495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 뼈와 무른 살덩이여. 오너라, 이리 오너라! 불꽃의 먹이가 되어라!', `MaleText_loc4`='脆弱的骨头和纤细的肌肉。来吧，来吧！被火焰吞噬吧！', `MaleText_loc5`='易碎的骨頭和細弱的血肉。來，快來!餵食火焰吧!', `MaleText_loc7`='Huesos quebradizos y carne fibrosa. ¡Venid, venid! ¡Alimentad las llamas!' WHERE `ID`=41496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활활 타올라 사라져 버려라, $r 녀석아.', `MaleText_loc4`='$r，耀眼的闪电总是会在转瞬间便消失。', `MaleText_loc5`='燃燒出光芒後消失吧，$r。', `MaleText_loc7`='Arde con fuerza y desaparece, $r.' WHERE `ID`=41497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 불길과 함께하거라.', `MaleText_loc4`='随我一同拥抱黑暗与烈火吧。', `MaleText_loc5`='和我一起進入黑暗和火焰之中。', `MaleText_loc7`='Uníos a mí en la oscuridad y el fuego.' WHERE `ID`=41498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 고통이 불길을 활활 타오르게 하는구나!', `MaleText_loc4`='你的痛苦将会使烈火烧得更旺！', `MaleText_loc5`='你的痛苦使火焰燃燒得更旺!', `MaleText_loc7`='¡Tu sufrimiento alimenta las llamas!' WHERE `ID`=41499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 한몸이 되어라!', `MaleText_loc4`='和这火焰融为一体吧！', `MaleText_loc5`='與火焰合而為一!', `MaleText_loc7`='¡Convertíos en uno con el fuego!' WHERE `ID`=41500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장로님, 저게 무엇입니까? 저런 건 본 적도 없습니다... 텔드랏실이 병들었을 때조차 말입니다.', `FemaleText_loc4`='这是什么，长者？我从没见过像这样的东西……就连泰达希尔染病时都没见过。', `FemaleText_loc5`='怎麼了，長者?我從來都沒看過這種東西...就連泰達希爾生病時都沒有。', `FemaleText_loc7`='¿Qué sucede, anciana? Nunca he visto nada parecido... ni siquiera cuando Teldrassil estaba sumido en la enfermedad.' WHERE `ID`=41501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수꾼이여, 모르겠군요. 제가 느낀 것은 어두운 마법입니다. 악 그 자체 말이지요.', `FemaleText_loc4`='我不知道，哨兵。我唯一能感受到的就是黑暗魔法的气息。绝对的邪恶。', `FemaleText_loc5`='我不知道，哨兵。我感覺到的是黑魔法。絕對的邪惡。', `FemaleText_loc7`='No lo sé, centinela. Lo que percibo es magia negra. Pura maldad.' WHERE `ID`=41502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드입니까? 저렇게 된 까닭은 호드 때문입니까?', `FemaleText_loc4`='是部落吗？腐化会是他们造成的吗？', `FemaleText_loc5`='是部落嗎?是他們造成這個腐化的嗎?', `FemaleText_loc7`='¿Es la Horda? ¿Pueden ser los responsables de esta corrupción?' WHERE `ID`=41503;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니에요. 호드보다 훨씬 더 나쁜 존재이지요. 돌발톱 봉우리에서 뿜어져 나오는 어둠은 아주 오래된 것입니다. 이 세상 자체보다 더 오래되었어요.', `FemaleText_loc4`='不，宝贝儿，这可比部落要邪恶得多。从石爪峰发散而出的黑暗力量非常古老。甚至比这个世界本身还要久远。', `FemaleText_loc5`='不，親愛的，這是遠比部落糟糕的。由石爪峰傳來的黑暗是遠古的。比這個世界更加遠古的東西。', `FemaleText_loc7`='No, querida, esto es mucho peor que la Horda. La oscuridad que emana la Cima del Espolón es antigua. Más antigua que el mundo mismo.' WHERE `ID`=41504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장로님, 그러면 어떻게 해야 살아남을 수 있겠습니까? 어떻게 호드와 이 고대 악의 세력을 막아낼 수 있습니까?', `FemaleText_loc4`='那我们要如何存活下去，长者？我们该怎样对抗部落和这古老的邪恶力量？', `FemaleText_loc5`='我們要如何才能生存，長者?我要如何才能同時對抗部落和這遠古的力量?', `FemaleText_loc7`='¿Cómo sobreviviremos, anciana? ¿Cómo podemos defendernos de la Horda y de esa antigua fuerza del mal?' WHERE `ID`=41505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 모르겠군요.', `FemaleText_loc4`='我也没有答案，孩子。', `FemaleText_loc5`='我不知道，孩子。', `FemaleText_loc7`='No lo sé, hija mía.' WHERE `ID`=41506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어두운 기운이 돌발톱 봉우리를 사로잡았습니다.', `FemaleText_loc4`='一股黑暗力量在席卷石爪峰。', `FemaleText_loc5`='一股黑暗的力量握住了石爪峰。', `FemaleText_loc7`='Una fuerza oscura atenaza la Cima del Espolón.' WHERE `ID`=41507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 언제 무슨 목적으로 생겼는진 알 수 없습니다.$B$B아마도 병력의 이동 경로로 쓰인 것 같습니다. 그런데 이곳엔 새까맣게 타고 고문당한 시체도 곳곳에 널려 있습니다. 온전한 모양이 아닌 것들도 있고, 대부분은 짓뭉개지거나 구타당한 모습입니다.$B$B이곳은 불의 땅이지만, 왠지 지옥의 문턱을 넘어온 듯한 느낌입니다.', `MaleText_loc4`='我不明白这地方的起源与用途。$B$B这些通道是行军用的，这没错，可这里同样遍布烧焦与饱受折磨的尸体，有些尸体已经部分被吞食，而大部分则只是被打得面目全非。$B$B尽管我们是在火焰之地，我却感觉像是已经跨进了地狱。', `MaleText_loc5`='我無法查出這個地方存在的最初目的。$B$B這些走廊是讓軍隊移動用的，沒錯，但它也散滿了燒焦和受虐至死的屍體，有些已經被吞噬了一半，大部份是受重擊和被打死的。$B$B我們正處於火源之界，但我感覺到我們已經踏入了地獄。', `MaleText_loc7`='No puedo llegar a comprender el propósito o el origen de este lugar.$B$BEsos pasillos se utilizaban para el movimiento de tropas, sí, pero también están llenos de cuerpos torturados y calcinados, algunos parcialmente devorados, o simplemente aplastados y golpeados.$B$BEstamos en las Tierras de Fuego, pero siento como si hubiéramos cruzado el umbral del infierno.' WHERE `ID`=41508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 거북이 친구를 잃어버렸습니다. 친구를 하나 더 받을 수 있을까요?', `MaleText_loc4`='我把我的海龟伙伴弄丢了。我能再拥有一个吗？', `MaleText_loc5`='我的烏龜同伴不見了。我可以再要一個嗎?', `MaleText_loc7`='He perdido a mi compañera tortuga. ¿Podría tener otra?', `FemaleText_loc1`='제 거북이 친구를 잃어버렸어요. 친구를 하나 더 받을 수 있을까요?', `FemaleText_loc4`='我把我的海龟伙伴弄丢了。我能再拥有一个吗？', `FemaleText_loc5`='我的烏龜同伴不見了。我可以再要一個嗎?', `FemaleText_loc7`='He perdido a mi compañera tortuga. ¿Podría tener otra?' WHERE `ID`=41509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다, $n. 이 거북이들은 당신 덕분에 황혼의 망치단으로부터 벗어났는 걸요. 당신이 가는 곳이라면 어디든 따라갈 겁니다.', `MaleText_loc4`='当然可以，$n。是你把这些海龟从暮光之锤的魔爪中救了出来——他们会追随你到任何地方。', `MaleText_loc5`='當然，$n。你從暮光之錘的手中救出了這些烏龜─你到哪牠們都會跟著你。', `MaleText_loc7`='Claro, $n. Has salvado a esas tortugas del Martillo Crepuscular, te seguirán donde quieras.' WHERE `ID`=41510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포피가 어떻게 해서 이토록 엉망인 상황에 놓였을까나???', `MaleText_loc4`='你是怎么让自己卷入这混乱的，鲍比？？？', `MaleText_loc5`='爸比，你是怎麼讓你自己置身於這團混亂之中的???', `MaleText_loc7`='¿¿¿Cómo te has metido en este lío, Poppi???' WHERE `ID`=41511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 이 물건은 무엇에 쓰는 거지? 스패너로 좀 더 때려봐야겠어. 뭐든 고장 났을 때 좀 세게 때려주면 멀쩡해지기 마련이거든.', `MaleText_loc4`='可这东西究竟是什么？我会再用我的扳手狠狠敲它几下。不管是什么毛病，希望这顿猛敲都能把它修好。', `MaleText_loc5`='這到底是個什麼東西?我再用我的板手多打它幾下好了。希望這種暴力的敲打能夠修理好它。', `MaleText_loc7`='¿Y, de todas maneras, qué es esta cosa? La golpearé un poco más con mi llave inglesa. Espero que esos golpes arreglen lo que sea que esté roto.' WHERE `ID`=41512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에, 포피... 다음에...', `MaleText_loc4`='下一次，鲍比……下一次……', `MaleText_loc5`='下一，爸比...下一次...', `MaleText_loc7`='La próxima vez, Poppi... La próxima vez...' WHERE `ID`=41513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"물론이지요. 그럴게요. 돌발톱 산맥에서 나이트 엘프 물건 고치고 싶습니다."라니. 포피, 너무 멍청했어.', `MaleText_loc4`='“当然没问题，我会接下这个活儿，去石爪山好好地修理修理那些垃圾暗夜精灵。”鲍比，你可真是个白痴。', `MaleText_loc5`='「完全可以，我願意接受到石爪山脈清除夜精垃圾的這項工作。」爸比，你是個白癡。', `MaleText_loc7`='"Claro que sí, acepto el trabajo en Sierra Espolón para arreglar chatarra de los elfos de la noche." Poppi, eres un idiota.' WHERE `ID`=41514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 달린 엄청난 날개가 무너져내려 이 비참한 신세를 끝장내줄지도 모르지. 그런 일이 더 빨리 일어나도록 더 세게, 더 빠르게 두드려봐야겠어.', `MaleText_loc4`='也许这玩意儿的疯狂翅膀会突然砸到我头上，帮我解除这痛苦。我要敲得更用力更快一些来加速这情况的发生。', `MaleText_loc5`='或許這個東西超大的翅膀會掉到我身上讓我死個乾淨。我再大力和再快點打它來加速這個過程好了。', `MaleText_loc7`='Quizá las estúpidas alas de esta cosa me caigan encima y pongan fin a mi sufrimiento. La golpearé más fuerte y más rápido para acelerar el acontecimiento.' WHERE `ID`=41515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 네메시스 수정에 다가가더니 호기심 어린 눈으로 수정을 조사합니다.', `MaleText_loc4`='%s靠近涅墨西斯水晶，小心翼翼地检查着它。', `MaleText_loc5`='%s接近了復仇水晶並小心的研究它。', `MaleText_loc7`='%s se acerca al cristal de Némesis y lo examina con cautela.' WHERE `ID`=41516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈다라 전망대나 전투의 흉터 계곡으로 돌아가지 않으면 다르나서스 수리검 투척기에서 떨어집니다.', `MaleText_loc4`='要是你不马上返回萨达拉瞭望台或战痕谷，你将被从达纳苏斯投刃车上移下来。', `MaleText_loc5`='你如果不回到薩歐達拉瞰臺或戰痕山谷，你便會由達納蘇斯旋刃投擲器上被移除下來。', `MaleText_loc7`='Te retiraremos del lanzagujas darnassiano si no regresas al Mirador de Thal''darah o al Valle Marca de Guerra.' WHERE `ID`=41517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가소로운 $r 녀석. 네놈은 지금 내 영역에 들어왔다!', `MaleText_loc4`='小$r。你现在闯入了我的地盘！', `MaleText_loc5`='弱小的$r。你現在處於我的國度中!', `MaleText_loc7`='Insignificante $r. ¡Ahora estás en MI reino!' WHERE `ID`=41518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산양을 되찾고 싶다면 어디 와서 한번 가져가 봐라, 겁쟁이들아!', `MaleText_loc4`='要是你想找回你们的牲畜，就来抢啊，懦夫！', `MaleText_loc5`='你如果想要回你的山羊就自己來拿啊!膽小鬼!', `MaleText_loc7`='¡Si quieren que les devuelva sus carneros, vengan a tomarlos, cobardes!' WHERE `ID`=41519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 격노가 폭발하려고 합니다! 투가의 껍질 밑으로 들어가십시오!', `MaleText_loc4`='%s就要爆发了！快到图加的壳下面来！', `MaleText_loc5`='%s就快爆發了!趕緊躲到托爾托拉之殼底下!', `MaleText_loc7`='¡%s está a punto de explotar! ¡Métete bajo el caparazón de Tooga!' WHERE `ID`=41520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 이상한 소리가 들리지 않았나?', `MaleText_loc4`='有人听到什么奇怪的声音了吗？', `MaleText_loc5`='有人聽到什麼不尋常的聲音嗎?', `MaleText_loc7`='¿Nadie más oye algo raro?', `FemaleText_loc1`='무슨 이상한 소리가 들리지 않았어?', `FemaleText_loc4`='有人听到什么奇怪的声音了吗？', `FemaleText_loc5`='有人聽到什麼不尋常的聲音嗎?', `FemaleText_loc7`='¿Nadie más oye algo raro?' WHERE `ID`=41521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 소리가! 확실히 무슨 소리가 났다고!', `MaleText_loc4`='又来了！我肯定听到什么声音了！', `MaleText_loc5`='又來了!我就知道真的有聲音!', `MaleText_loc7`='¡Ahí está de nuevo! ¡Sabía que había oído algo!', `FemaleText_loc1`='또다시 소리가! 확실히 무슨 소리가 들렸어!', `FemaleText_loc4`='又来了！我肯定听到什么声音了！', `FemaleText_loc5`='又來了!我就知道真的有聲音!', `FemaleText_loc7`='¡Ahí está de nuevo! ¡Sabía que había oído algo!' WHERE `ID`=41522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리갈기 공격대다! 비상경보를 울려라!', `MaleText_loc4`='霜鬃袭击者！快响警报！', `MaleText_loc5`='霜鬃劫掠者!快發出警報!', `MaleText_loc7`='¡Asaltantes Peloescarcha! ¡Da la alarma!', `FemaleText_loc1`='서리갈기 공격대다! 비상경보를 울려라!', `FemaleText_loc4`='霜鬃袭击者！快响警报！', `FemaleText_loc5`='霜鬃劫掠者!快發出警報!', `FemaleText_loc7`='¡Asaltantes Peloescarcha! ¡Da la alarma!' WHERE `ID`=41523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산악경비대! 전투 준비! 저 산양들을 되찾아 와야 한다!', `MaleText_loc4`='准备作战，巡山人！把那些牲畜抢回来！', `MaleText_loc5`='拿起武器，巡山者!奪回那些山羊!', `MaleText_loc7`='¡A las armas, montaraces! ¡Recuperad esos carneros!', `FemaleText_loc1`='산악경비대! 전투 준비! 저 산양들을 되찾아 와야 한다!', `FemaleText_loc4`='准备作战，巡山人！把那些牲畜抢回来！', `FemaleText_loc5`='拿起武器，巡山者!奪回那些山羊!', `FemaleText_loc7`='¡A las armas, montaraces! ¡Recuperad esos carneros!' WHERE `ID`=41524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리갈기 트롤들은 끊임없이 농장을 공격해 왔습니다.', `MaleText_loc4`='霜鬃巨魔一直在突袭这农场。', `MaleText_loc5`='霜鬃食人妖一直都在不斷地掠奪牧場。', `MaleText_loc7`='Los trols Peloescarcha han estado atacando la granja continuamente.' WHERE `ID`=41525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금으로서는 놈들이 모든 것을 빼앗아 가지 못하도록 간신히 막아내고만 있습니다.', `MaleText_loc4`='我们的人数严重不足，很难抵挡他们的侵掠。', `MaleText_loc5`='因為這樣，我們的人手只夠阻止不讓他們搶走所有的東西。', `MaleText_loc7`='Ahora mismo no somos suficientes para evitar que se lleven todo lo que quieran.' WHERE `ID`=41526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리갈기 트롤들은 산양들을 잡아서 그냥 가져가 버립니다. 이제 놈들을 가만두고 볼 수만은 없습니다.', `MaleText_loc4`='他们每次都是抢了牲畜就走。畜群已经再也经不起这种打击。', `MaleText_loc5`='他們搶了山羊就跑。牧羊人已經忍無可忍了。', `MaleText_loc7`='Simplemente cogen los carneros y se van. El rebaño ya no puede aguantarlo más.' WHERE `ID`=41527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산악경비대원이 무언가를 봤다. 경계를 늦추지 말도록!', `MaleText_loc4`='有位巡山人已经看见了什么。睁大你们的双眼！', `MaleText_loc5`='一位巡山者剛才好像看到了什麼。眼睛放亮一點!', `MaleText_loc7`='Uno de los montaraces ha visto algo. ¡Abre bien los ojos!' WHERE `ID`=41528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈습니다! 정말 잘하셨습니다!!', `MaleText_loc4`='我们做到了！干得好，小子们！', `MaleText_loc5`='我們成功了!夥計們，幹得好!', `MaleText_loc7`='¡Lo hemos conseguido! ¡Buen trabajo, camaradas!' WHERE `ID`=41529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네스피라와 이야기합시다.', `MaleText_loc4`='让我们与奈瑟匹拉谈一谈。', `MaleText_loc5`='讓我們與奈斯畢拉對話。', `MaleText_loc7`='Hablemos con Nespirah.', `FemaleText_loc1`='네스피라와 이야기합시다.', `FemaleText_loc4`='让我们与奈瑟匹拉谈一谈。', `FemaleText_loc5`='讓我們與奈斯畢拉對話。', `FemaleText_loc7`='Hablemos con Nespirah.' WHERE `ID`=41530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크으... 아아아...!', `MaleText_loc4`='Kkkk……aaahhh……！', `MaleText_loc5`='喀喀喀...啊啊啊...!', `MaleText_loc7`='¡Kkkk... aaahhh...!' WHERE `ID`=41531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌된 일인가? 내 말이 들리는가?', `MaleText_loc4`='发生什么事了？你能听到我说话吗？', `MaleText_loc5`='發生了什麼事?你聽得到我說話嗎?', `MaleText_loc7`='¿Qué ocurre? ¿Puedes oírme?' WHERE `ID`=41532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 볼 수는 없지만 여기 있다는 건 느낄 수 있다. 내가 아는 걸 설명해 주마.', `MaleText_loc4`='我看不见你，但我能感觉到你的存在。我会说清楚我能做些什么。', `MaleText_loc5`='我看不到你，但能感覺到你的存在。我會盡我所能解釋。', `MaleText_loc7`='No puedo verte, pero siento tu presencia. Explicaré lo que pueda.' WHERE `ID`=41533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 내 의지를 누르고 있다. 그들이 무엇을 하는지 느낄 수 있지만, 움직일 힘이 없다.', `MaleText_loc4`='纳迦在压制我的意志。我能感觉到他们在做什么，可我无力采取任何行动。', `MaleText_loc5`='納迦壓迫了我的意志。我能感覺到他們在做什麼，但我沒有力量做出行動。', `MaleText_loc7`='Los nagas suprimen mi voluntad. Puedo sentir lo que hacen, pero no tengo poder para actuar.' WHERE `ID`=41534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 내 진주를 파내고, 내 몸을 깎아내고, 그리고 내 정신을 뒤틀어 놓았다. 내 의지가 무너지는 게 느껴진다. 이방인이여... 그들은 나를 전쟁에 이용할 생각이다!', `MaleText_loc4`='他们挖掘我的珍宝，他们切刻我的身体，他们扭曲我的灵魂。我能感觉到我的意志在粉碎，陌生人……他们想要让我为他们作战！', `MaleText_loc5`='他們挖我的珍珠，刻我的身體，還扭曲我的精神。我能感覺到我的意志在崩潰，陌生人...他們想使用我做為戰爭的工具!', `MaleText_loc7`='Recogen mis perlas, me hacen cortes en el cuerpo y manipulan mi mente. Puedo sentir cómo se quiebra mi voluntad, extraños... ¡Quieren utilizarme para la guerra!' WHERE `ID`=41535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 나가의 도구가 되지 않을 것이다. 온 힘을 다해 저항하겠지만, 영원히 버틸 수는 없노라. 제발 누군가가 그들을 멈추어 다오!', `MaleText_loc4`='我不会成为纳迦的傀儡。我会尽我所能去抵抗，可我恐怕不能一直坚持下去。拜托了，快来人阻止他们！', `MaleText_loc5`='我不會變成納迦的傀儡。我會抵抗到最後一分一秒，但我無法一直持續下去。拜託，誰能去阻止他們!', `MaleText_loc7`='NO seré una herramienta de los nagas. Resistiré todo lo que pueda, pero no podrá ser para siempre. ¡Por favor, que alguien los detenga!' WHERE `ID`=41536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!' WHERE `ID`=41537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 꼼짝없이 죽는 줄로만 알았습니다.', `MaleText_loc4`='我还以为我要死在这下面了。', `MaleText_loc5`='我以為我會死在這下面。', `MaleText_loc7`='Creí que iba a morir aquí abajo.' WHERE `ID`=41538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 저를 없애버릴 줄로만 알고 있었습니다!', `MaleText_loc4`='我以为他们要把我撕成碎片！', `MaleText_loc5`='我以為他們要把我大卸八塊!', `MaleText_loc7`='¡Creí que iban a despedazarme!' WHERE `ID`=41539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 축복이 함께하기를. 구해주셔서 고맙습니다!', `MaleText_loc4`='愿圣光护佑你，陌生人。是你救了我！', `MaleText_loc5`='聖光祝福你，陌生人。你救了我一命!', `MaleText_loc7`='Que la Luz te bendiga, $gextraño:extraña;. ¡Me has salvado!' WHERE `ID`=41540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트로그 놈들이 나타난 뒤로 제가 본 것 중 가장 멋진 일을 해 주신 분이십니다!', `MaleText_loc4`='从穴居人出现的那天起，我就再没有像现在这样高兴过！', `MaleText_loc5`='你是穴居怪出現以來我看過最美好的事物!', `MaleText_loc7`='¡Eres lo mejor que he visto desde que aparecieron los troggs!' WHERE `ID`=41541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 빨리 가족이 있는 고향으로 돌아갔으면 좋겠군요. 구해주셔서 정말 감사합니다.', `MaleText_loc4`='我已经迫不及待想要回家与家人团聚了。谢谢你，陌生人。', `MaleText_loc5`='我等不及要回去與我的家人團聚。謝謝你，陌生人。', `MaleText_loc7`='Ardo en deseos de volver a casa con mi familia. Gracias, $gextraño:extraña;.' WHERE `ID`=41542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간으로 바꿔줄 방법이 없음을 살스베리에게 몇 번이고 설명했소. 귓등으로도 들으려 하지 않더니 오히려 내게 신임을 얻으면 비밀리에 해주리라 생각하더군.$B$B노움은 참 이상한 종족이오.', `MaleText_loc4`='我已经试着向沙尔斯巴里解释过很多次了——我没办法把他变成一只狼人。可他总是充耳不闻，反而让自己坚信，只要能获得我的信任，我就会和他分享秘密。$B$B侏儒可真是奇怪的家伙。', `MaleText_loc5`='我已經跟沙爾斯伯利解釋了千百遍說我不可能有辦法能將他變成一隻狼人。他不但不接受而且還很篤定地認為只要贏得我的信任我就會偷偷地幫助他。$B$B地精真是奇怪的生物。', `MaleText_loc7`='Una y otra vez he intentado explicarle a Salsbury que yo no podría transformarle en un huargen de ninguna forma posible. Se niega a escucharme y se ha convencido a sí mismo de que si se gana mi confianza compartiré mi secreto con él.$B$BLos gnomos son muy extraños.' WHERE `ID`=41543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주목! 모두 정렬!', `MaleText_loc4`='听口令！集合！', `MaleText_loc5`='聽著!前進!', `MaleText_loc7`='¡Atención! ¡A FORMAR!' WHERE `ID`=41544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌발톱 산맥에 계신 대군주 크롬가르 님께서 지원 병력을 요청하셨다.', `MaleText_loc4`='克罗姆加大王正在召集步兵前往石爪山。', `MaleText_loc5`='霸主克羅姆加在石爪山脈要求更多的步兵。', `MaleText_loc7`='El señor supremo Krom''gar ha ordenado a la infantería que acuda a Sierra Espolón.' WHERE `ID`=41545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그곳으로 진군해 단 하나의 목적을 달성한다.', `MaleText_loc4`='我们将向那里进军，目的只有一个——而且是唯一的一个：', `MaleText_loc5`='我們會行進到那並只做一件事情，就只有一件:', `MaleText_loc7`='Vamos a ir allí y haremos una cosa y solo una cosa:' WHERE `ID`=41546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 얼라이언스를 없애버리는 것이다!', `MaleText_loc4`='消灭联盟！', `MaleText_loc5`='殺死聯盟!', `MaleText_loc7`='¡MATAR A LOS DE LA ALIANZA!' WHERE `ID`=41547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에헴, 폭탄에 대해 이야기하는 것도 잊지 마세요, 알도.', `FemaleText_loc4`='嗯哼。别忘了炸弹，阿尔多。', `FemaleText_loc5`='咳咳。別忘了炸藥，奧多。', `FemaleText_loc7`='Ejem. No te olvides de la bomba, Aldo.' WHERE `ID`=41548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정한다. 우리는 두 가지의 목적을 달성한다.', `MaleText_loc4`='更正一下。我们要做两件事：', `MaleText_loc5`='更正。我們會做兩件事件:', `MaleText_loc7`='Corrijo. Vamos a hacer DOS cosas:' WHERE `ID`=41549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 없애버리고 신형 고블린 폭탄을 돌발톱 산맥까지 무사히 옮겨서...', `MaleText_loc4`='消灭联盟，并确保我们的新式地精炸弹能完好无损的到达石爪山……', `MaleText_loc5`='殺死聯盟和確保我們新的哥布林炸彈能完好的抵達石爪山脈...', `MaleText_loc7`='¡MATAR A LOS DE LA ALIANZA y asegurarnos de que nuestra nueva bomba goblin llega a Sierra Espolón de una pieza...' WHERE `ID`=41550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그 폭탄을 이용해 얼라이언스를 없애버리는 것이다!', `MaleText_loc4`='用它去干掉联盟吧！', `MaleText_loc5`='然後使用它來殺死聯盟!', `MaleText_loc7`='¡Y después utilizarla para MATAR A LOS DE LA ALIANZA!' WHERE `ID`=41551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 지원자는 없나?', `MaleText_loc4`='现在，有没有志愿者？', `MaleText_loc5`='現在，有人自願前往嗎?', `MaleText_loc7`='Y bien, ¿algún voluntario?' WHERE `ID`=41552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 훌륭해. 1대대는 준비하라! 그리고 절대 잊지 말도록...', `MaleText_loc4`='听起来不错。第一营做好准备！而且千万别忘了……', `MaleText_loc5`='聽起來不錯。第一營準備!還有，千萬別忘了...', `MaleText_loc7`='Suena bien. Primer batallón, ¡prepárense! Y nunca olviden que...' WHERE `ID`=41553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 대족장님께서 귀관들을 지켜보고 계신다!', `MaleText_loc4`='地狱咆哮之眼注视着你。', `MaleText_loc5`='地獄吼的雙眼在盯著你!', `MaleText_loc7`='¡Los ojos de Grito Infernal están fijos en ustedes!' WHERE `ID`=41554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안에서 보니 몸체가 더 큰 것 같소. 정말 흥미롭소!', `MaleText_loc4`='她的身体从里面看似乎显得更大了。真令人惊叹！', `MaleText_loc5`='她的身體內部看起來更大。太有趣了!', `MaleText_loc7`='Su cuerpo parece mucho mayor desde el interior. ¡Fascinante!' WHERE `ID`=41555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, $r 친구. 인간과 오크가 노예가 되어 쇠사슬에 묶인 채로 네스피라의 진주를 캐는 것을 봤소. 그리고 나가가 채찍을 쥐고 있는 것도 말이오. 뭔가 대책을 세워야 하겠소.', `MaleText_loc4`='看，$r。我看到了人类和兽人，他们是戴着锁链的奴隶，正在挖掘奈瑟匹拉的珠宝。我还看到手执鞭子的纳迦。一定要想想办法。', `MaleText_loc5`='聽著，$r。我看到了人類和獸人被當成奴隸鎖著鐵鏈，挖著奈斯畢拉的珍珠。我還看到納迦拿著鞭子。我們必須做些什麼。', `MaleText_loc7`='Mira, $c. Veo un hombre y un orco encadenados como esclavos, recogiendo las perlas de Nespirah. Y veo un naga con un látigo. Hay que hacer algo.' WHERE `ID`=41556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이건 뭐요?', `MaleText_loc4`='这边这个是什么？', `MaleText_loc5`='這邊這個是什麼?', `MaleText_loc7`='¿Qué es eso de ahí?' WHERE `ID`=41557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드린 님의 강인함은 전설 그 자체입니다.$B$B모든 지역의 전사들이 골드린 님 같은 힘을 얻길 기원하며 이 제단을 방문합니다.', `MaleText_loc4`='戈德林的坚韧战力充满着传奇色彩。$B$B各地的战士都纷纷到访这座圣殿，祈求能像戈德林那样勇猛卓绝。', `MaleText_loc5`='戈德林的強韌是個傳奇。$B$B從各地來的戰士會去拜訪他的聖壇希望能在戰場上和他一樣英勇。', `MaleText_loc7`='La tenacidad de Goldrinn es legendaria.$B$BGuerreros de todas partes visitan su santuario con la esperanza de recibir parte de esa destreza para el combate.' WHERE `ID`=41558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다, 멍청한 놈들아! 고대 생물의 의지는 이미 꺾였다! 모든 과정이 거의 끝났어!', `MaleText_loc4`='你太迟了，蠢货！古灵的意志已经破碎了。占据已经接近完成了！', `MaleText_loc5`='你們太遲了，蠢材!老傢伙的意志已經崩潰!儀式快要完成了!', `MaleText_loc7`='¡Demasiado tarde, imbécilesss! ¡La voluntad del ancestro essstá rota! ¡El processso ya está casi completo!' WHERE `ID`=41559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 봐라. 내가 의식을 끝내고, 네스피라가 야수로 돌변해 네놈을 공격하는 모습을!', `MaleText_loc4`='现在，你将见证仪式的完成，那匹野兽将成为你的敌人！', `MaleText_loc5`='現在，看著我完成儀式，用這頭野獸對抗你!', `MaleText_loc7`='¡Ahora me verás completar el ritual y poner a la bestia contra ti!' WHERE `ID`=41560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 네스피라는 나가의 것이다!', `MaleText_loc4`='不！奈瑟匹拉属于纳迦！', `MaleText_loc5`='不!奈斯畢拉屬於納迦!', `MaleText_loc7`='¡No! ¡Nessspirah es de los nagasss!' WHERE `ID`=41561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아! 내 보호막이!', `MaleText_loc4`='啊！我的魔球！', `MaleText_loc5`='呃啊!我的球啊!', `MaleText_loc7`='¡Aaagh! ¡Mi esssfera!' WHERE `ID`=41562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내 보호막이 약해지잖아!', `MaleText_loc4`='不！我的气泡正在变得薄弱！', `MaleText_loc5`='不!我的泡泡變弱了!', `MaleText_loc7`='¡No! ¡Mi burbuja se debilita!' WHERE `ID`=41563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네스피라! 어째서 날 거역하는 거지?', `MaleText_loc4`='奈瑟匹拉！你为何要对抗我？', `MaleText_loc5`='奈斯畢拉!為什麼你要反抗我?', `MaleText_loc7`='¡Nessspirah! ¿Por qué te vuelvesss contra mí?' WHERE `ID`=41564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 끝났다! 네스피라는 내 것이다!', `MaleText_loc4`='终于完成了！现在，奈瑟匹拉是我的了！！！', `MaleText_loc5`='結束了!奈斯畢拉是我的了!!', `MaleText_loc7`='¡Lo hicccce! ¡¡Nessspirah esss mío!!' WHERE `ID`=41565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 잡으십시오. 길이 매우 험할 겁니다. 틈새를 노리는 나이트 엘프들을 조심하십시오!', `MaleText_loc4`='抓紧了，这一路可会相当颠簸。密切留意暗夜精灵！', `MaleText_loc5`='抓緊了，這會有點顛陂。小心夜精靈的出沒!', `MaleText_loc7`='Agárrate fuerte, va a ser un viaje movidito. ¡Tú vigila por si ves elfos de la noche!' WHERE `ID`=41566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병들이 새로 수송됐습니다, 사우르보즈. 제 마차에 있는 이전 대대원들같이 시체가 되어 돌아오지 않기를 바라야겠군요.', `MaleText_loc4`='又有一批新鲜的肉为你送到了，索博兹。希望这些不会像上次那营人一样，最后成为我车上的死尸。', `MaleText_loc5`='這是你另的一批新的新鮮血肉，索波茲。希望這些不會像上批士兵一樣最終成為我貨車上的屍體。', `MaleText_loc7`='Tenemos otro envío de carne fresca para ti, Saurboz. Esperamos que no acaben muertos en mi carreta como el último batallón.' WHERE `ID`=41567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 놈들을 없애버리는 것만큼 신나는 일도 없지.', `MaleText_loc4`='没什么事比杀联盟更让我感到爽快了。', `MaleText_loc5`='比殺聯盟還讓我喜歡的少數幾件事。', `MaleText_loc7`='Hay pocas cosas que me gusten más que matar a los de la Alianza.' WHERE `ID`=41568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너같이 흉악한 오크가 얼라이언스 놈들 잡는 거 말고 신나는 일이 또 뭐가 있겠어?', `MaleText_loc4`='对像你这样堕落的兽人来说，还有什么是比杀联盟更美妙的呢，乌图克？', `MaleText_loc5`='像你這種沒品的獸人，烏特佛奇，有什麼是會比殺聯盟還讓你高興的?', `MaleText_loc7`='¿Qué puede gustarle más que matar a los de la Alianza a un orco tan depravado como tú, Utvoch?' WHERE `ID`=41569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 타우렌 여자라면 껌벅 죽는 거 잘 알잖나. 내 유일한 약점이라고...', `MaleText_loc4`='你知道我无法拒绝牛头人美女，多特拉格。她们是我的死穴……', `MaleText_loc5`='我無法抗拒母牛頭人，阿東。她們是我的罩門...', `MaleText_loc7`='Sabes que no puedo resistirme a las mujeres tauren, Donty. Son mi debilidad...' WHERE `ID`=41570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우, 이 징그러운 자식...', `MaleText_loc4`='你真是个恶心到极点的兽人啊，乌特。', `MaleText_loc5`='你真是個變態的獸人，阿烏。', `MaleText_loc7`='Eres un orco muy enfermo, Ut.' WHERE `ID`=41571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 전쟁 무기를 위한 희생물이 더 있군.', `MaleText_loc4`='为部落作战机器准备了更多的弹药。', `MaleText_loc5`='更多部落戰爭機械的砲灰。', `MaleText_loc7`='Más forraje para la maquinaria de guerra de la Horda.' WHERE `ID`=41572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 이곳에 록레인의 병사들이 있는 것 같다. 돈트래그, 우트보크. 크롬가르 요새에 자네들의 노련한 기술이 필요할 것이다.', `MaleText_loc4`='看来我们这儿来了一些石雨的士兵。多特拉格、乌图克，你们的专长能够在克罗姆加壁垒派上用场。', `MaleText_loc5`='看來我們這有些石雨的士兵。東崔格、烏特佛奇，我們在克羅姆加堡壘會需要你們的力量。', `MaleText_loc7`='Parece que tenemos aquí a algunos de los muchachos de Llueverroca. Dontrag, Utvoch, vamos a necesitar tus habilidades en la Fortaleza Krom''gar.' WHERE `ID`=41573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남아 있는 그런트들이여! 무장하라! 죽여야 할 것들이 있다.', `MaleText_loc4`='其余的步兵立刻整装出发！我们要战斗了。', `MaleText_loc5`='至於剩下的蠻兵，準備好!我們要大開殺戒了。', `MaleText_loc7`='¡En cuanto a todos los demás, animales, prepárense! Tenemos que salir a matar un poco.' WHERE `ID`=41574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생 오크로 살면서 아까 그런 건 본 적이 없네.', `MaleText_loc4`='$r，我这一辈子都没见过这样的东西……', `MaleText_loc5`='獸人，在我有生之年我還沒看過這種...', `MaleText_loc7`='En toda mi vida, $r, no he visto nada parecido...' WHERE `ID`=41575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 전투를 치르기에는 장비가 너무 열악하다네.$b$b전투에 대비해야 할 텐데...', `MaleText_loc4`='我们的战备不足以在此交战。$b$b必须做好准备才行……', `MaleText_loc5`='我們在這裡的裝備太差了。$b$b必須更加做好準備...', `MaleText_loc7`='No estamos adecuadamente equipados para la batalla.$B$BDebemos hacer preparativos...' WHERE `ID`=41576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다! 어서 움직입시다.', `MaleText_loc4`='是，长官！乌特，我们出发。', `MaleText_loc5`='是的，長官!我們走吧阿烏。', `MaleText_loc7`='¡Sí, señor! Vamos, Ut.' WHERE `ID`=41577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 돈 되는 것 좀 있나?', `MaleText_loc4`='你有宝贝吗？', `MaleText_loc5`='你有亮晶晶嗎?', `MaleText_loc7`='¿Ves algo que brille?' WHERE `ID`=41578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠? 주머니에 뭐가 들었는지 볼까?', `MaleText_loc4`='那口袋里是什么？嗯？', `MaleText_loc5`='它口袋裡面的是什麼?嗯?', `MaleText_loc7`='¿Qué llevan en los bolsillos? ¿Hmm?' WHERE `ID`=41579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 죽이고 가진 걸 털고...', `MaleText_loc4`='我们干掉他们之后，夺走他们的东西……', `MaleText_loc5`='我們殺了他們拿他們的東西...', `MaleText_loc7`='Los matamos y nos llevamos sus cosas...' WHERE `ID`=41580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 가져온 거지? 땅에서 나온 보물인가?', `MaleText_loc4`='你给我们带来了什么？从上面带来了财宝？', `MaleText_loc5`='你帶什麼給我們?上面的寶物?', `MaleText_loc7`='¿Qué nos traes? ¿Tesoros de la superficie?' WHERE `ID`=41581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사기가 점점 높아지고 있네. 자네의 노력에 감사하네. $c|1이여;여;.', `MaleText_loc4`='士气变得高涨了，多谢你的努力，$c。', `MaleText_loc5`='士氣越來越高了，謝謝你的努力，$c。', `MaleText_loc7`='Gracias a tus esfuerzos está subiendo la moral, $c.' WHERE `ID`=41582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 싸워 밖으로 나갈 방법을 찾아낸다면, 헬스크림 님께서 자네의 공을 치하하실 것이네, $r|1이여;여;.', `MaleText_loc4`='要是我们能从这儿杀出去，地狱咆哮一定会获知你的功绩，$r。', `MaleText_loc5`='如果我們找到方法殺出去，地獄吼便會知道你的所做所為，$r。', `MaleText_loc7`='Si encontramos la forma de salir de aquí, Grito Infernal sabrá de tus hazañas, $r.' WHERE `ID`=41583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오크들과 나는 함께 수많은 전투를 치렀지.$b$b여기 들어오는 나가는 후회할 걸세.', `MaleText_loc4`='这些兽人和我已经在多次战斗中出生入死。$b$b我不羡慕任何进到这里的纳迦。', `MaleText_loc5`='這些獸人和我已經身經百戰。$b$b我會同情那些進入此區的納迦的。', `MaleText_loc7`='Estos orcos y yo hemos servido juntos en muchas batallas.$b$bNo envidio a ningún naga que se aventure en este lugar.' WHERE `ID`=41584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 곧 들이닥칠 걸세! 서두르게, $n. 내 도끼가 나가들의 피를 원하네!', `MaleText_loc4`='他们来了！动作快，$n，我的战斧渴望这些纳迦的鲜血！', `MaleText_loc5`='他們就在眼前!快點，$n，我的斧頭渴望吸食納迦的鮮血!', `MaleText_loc7`='¡Caen sobre nosotros! ¡Rápido, $n, mi hacha está sedienta de la sangre de esos nagas!' WHERE `ID`=41585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가입니다! $n|1이;가; 배로 돌아오는 걸 따라왔습니다!', `MaleText_loc4`='纳迦！他们跟踪$n溜上船了！', `MaleText_loc5`='是納迦!他們跟著$n到船上了!', `MaleText_loc7`='¡Los nagas! ¡Han seguido a $n hasta el barco!' WHERE `ID`=41586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언트리 대장님은 절대 포기하지 않으셨소. 놈들이 더럽힌 우리 땅을 보며 반드시 되갚아 주겠노라 말씀하시곤 했소. 아직 저 아래 어딘가에 살아계실지도 모르오!', `MaleText_loc4`='他从不放弃——铁木队长——他说要让他们为其所玷污的每一寸土地付出代价。他很可能就在那下面，也许还活着！', `MaleText_loc5`='鐵樹隊長他從不放棄!他說要讓他們為每一吋被糟蹋的土地都付出代價。他可能還活著!', `MaleText_loc7`='El capitán Troncoferro nunca se rindió, dijo que les haría pagar por cada centímetro de tierra que profanaran. ¡Quizá siga vivo ahí abajo, en alguna parte!' WHERE `ID`=41587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 번개의 축복을!', `MaleText_loc4`='鲜血与雷鸣！', `MaleText_loc5`='鮮血與雷霆!', `MaleText_loc7`='¡Sangre y truenos!' WHERE `ID`=41588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림을 위해!', `MaleText_loc4`='为了地狱咆哮！', `MaleText_loc5`='為了地獄吼!', `MaleText_loc7`='¡Por Grito Infernal!' WHERE `ID`=41589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도끼 준비! 적들이 접근한다!', `MaleText_loc4`='准备好战斧！敌人靠近了！', `MaleText_loc5`='拿起斧頭!敵人接近中!', `MaleText_loc7`='¡Hachas preparadas! ¡El enemigo se acerca!' WHERE `ID`=41590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사여, 적이 몰려오고 있소! 그대의 능력을 보여주시오!', `MaleText_loc4`='他们在围攻我们，萨满！发挥你的作用！', `MaleText_loc5`='他們要淹沒我們了，薩滿!你快做些什麼!', `MaleText_loc7`='¡Nos rodean y nos superan en número, chamán! ¡Haz algo útil!' WHERE `ID`=41591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이여, 긴장을 늦추지 마라! 아직 처치해야 할 나가가 많다!', `MaleText_loc4`='战士们，坚定意志！现在还有许多纳迦需要消灭！', `MaleText_loc5`='保持理性，戰士們!還有更多的納迦要殺!', `MaleText_loc7`='¡No desperdicien sus fuerzas, guerreros! ¡Aún quedan nagas que matar!' WHERE `ID`=41592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 쉬려고 헐떡이며 추위에 몸을 떱니다.', `MaleText_loc4`='%s大口喘息着，在寒风中颤抖着。', `MaleText_loc5`='%s深呼吸了一口氣後冷得發抖。', `MaleText_loc7`='%s jadea en busca de aire y tiembla de frío.', `FemaleText_loc1`='%s|1이;가; 숨을 쉬려고 헐떡이며 추위에 몸을 떱니다.', `FemaleText_loc4`='%s大口喘息着，在寒风中颤抖着。', `FemaleText_loc5`='%s深呼吸了一口氣後冷得發抖。', `FemaleText_loc7`='%s jadea en busca de aire y tiembla de frío.' WHERE `ID`=41593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섞고 흔들어서, 열을 가한다...', `MaleText_loc4`='混合、搅拌、加热……', `MaleText_loc5`='混合攪拌，然後加熱...', `MaleText_loc7`='Mezclar, batir, aplicar calor…' WHERE `ID`=41594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급격한 온도 변화에 필멸의 육신이 어떻게 반응할까? 아하하! 실험해 봐야지! 과학을 위해!', `MaleText_loc4`='凡人的躯壳能否经得住极端温度的转变，要弄清楚！为了科学！', `MaleText_loc5`='凡人之軀能承受多大的溫度改變?必須測試!為了科學!', `MaleText_loc7`='¿Cambios de temperatura extremos en el caparazón mortal? ¡Debo saber! ¡POR LA CIENCIA!' WHERE `ID`=41595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 좀 불안정하지만... 실패 없이는 성공도 없는 법이지!', `MaleText_loc4`='这个有点儿不稳定，但不经过失败怎么会进步？', `MaleText_loc5`='這個有點不穩定，但哪有實驗不失敗的?', `MaleText_loc7`='Será algo inestable, pero el progreso viene de los errores.' WHERE `ID`=41596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대피할 곳을 찾았습니다, $n. 그대도 저와 함께 가시지요.', `MaleText_loc4`='我为我们安排了逃路，$n。你们跟我来。', `MaleText_loc5`='我為你準備了逃離的路徑，$n。你必須跟我走。', `MaleText_loc7`='He organizado una vía de escape para nosotros, $n. Debes venir conmigo.' WHERE `ID`=41597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해냈군요, 두아른. 네스피라의 껍데기 안에서 우물쭈물하지 마십시오. 그대도 분노한 반신이 얼마나 위험한지는 저만큼이나 잘 아실 테지요.', `MaleText_loc4`='达鲁——做得好。别在奈瑟匹拉的壳里耽搁太久。你跟我都清楚由愤怒的半神带来的危险。', `MaleText_loc5`='做得太棒了，杜亞恩。不要在奈斯畢拉的體內耽擱太久。你跟我一樣清楚半神在憤怒之時有多危險。', `MaleText_loc7`='Duarn, un trabajo excelente. No te entretengas dentro del cascarón de Nespirah. Sabes tan bien como yo lo peligroso que puede ser un semidiós enfadado.' WHERE `ID`=41598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저를 따라오십시오!', `MaleText_loc4`='现在，跟我走！', `MaleText_loc5`='現在，跟著我!', `MaleText_loc7`='¡Ahora, sígueme!' WHERE `ID`=41599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해마를 타십시오, 친구여. 네스피라가 나가를 공격할 때 가까이 있고 싶지 않을 테니까요.', `MaleText_loc4`='朋友，跨上海马吧。当奈瑟匹拉攻击纳迦的时候，你绝不会想要靠近她的。', `MaleText_loc5`='坐上海馬，朋友。當奈斯畢拉與納迦交手時你不會想靠近的。', `MaleText_loc7`='Súbete al caballito de mar, joven. No te gustaría estar cerca de Nespirah cuando se vuelva contra los nagas.' WHERE `ID`=41600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크으으아아! 나가의 지배에서 벗어나 내 의지를 찾았노라!', `MaleText_loc4`='啊——啊！我终于不用再受纳迦的奴役了，我的意志又是我自己的了！', `MaleText_loc5`='喀喀喀!我已經掙脫納迦的奴役了，我的意志再次歸我自己所有!', `MaleText_loc7`='¡Aaaaaaaaaah! ¡Soy libre de la esclavitud a la que me sometían los nagas, y he recuperado mi voluntad!' WHERE `ID`=41601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸은 나가의 병균과 싸우고 있도다. 내가 분노를 해방하기 전에 부디 안전한 곳으로 대피하라!', `MaleText_loc4`='我的身体已经开始对抗纳迦的侵染。我请你们在我释放怒火之前，快逃到安全的地方去！', `MaleText_loc5`='我的身體已經開始與納迦的侵襲對抗了。拜託，請你在我釋放怒火前找個安全的地方躲起來!', `MaleText_loc7`='Mi cuerpo empieza a luchar contra la infección de los nagas. ¡Te ruego que te pongas a salvo antes de que desate mi ira!' WHERE `ID`=41602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대도 떠나거라, 친구여. 이 타우렌의 친구인 에루낙이 밖에서 해마를 타고 기다리고 있을 것이다. 실은, 이제 여기까지 도착한 것 같군.', `MaleText_loc4`='你现在可以走了，朋友。牛头人的挚友埃鲁纳克应该正和海马一起等在外面。事实上，就像他现在就在这儿。', `MaleText_loc5`='你現在可以離開了，朋友。牛頭人的朋友伊魯納克應該在外面帶著海馬等你。事實上，看起來他現在已經在這裡了。', `MaleText_loc7`='Puedes marcharte, joven. El amigo del tauren, Erunak, debería estar esperándote fuera con los caballitos de mar. De hecho, parece que ya está aquí.' WHERE `ID`=41603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 말라, 에루낙. 타우렌은 안전할 것이다.', `MaleText_loc4`='别担心，埃鲁纳克。牛头人会没事的。', `MaleText_loc5`='別擔心，伊魯納克。牛頭人會是安全的。', `MaleText_loc7`='No te preocupes, Erunak. El tauren estará a salvo.' WHERE `ID`=41604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 기다리십니까? 어서 갑시다!', `MaleText_loc4`='我们在等什么？出发！', `MaleText_loc5`='我們在等什麼?走吧!', `MaleText_loc7`='¿A qué esperamos? ¡Adelante!', `FemaleText_loc1`='뭘 기다리세요? 어서 가자고요!', `FemaleText_loc4`='我们在等什么？出发！', `FemaleText_loc5`='我們在等什麼?走吧!', `FemaleText_loc7`='¿A qué esperamos? ¡Adelante!' WHERE `ID`=41605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이여! 적을 피로 물들여라!', `MaleText_loc4`='战士们！让他们流血！', `MaleText_loc5`='戰士們!讓他們血濺八方!', `MaleText_loc7`='¡Guerreros! ¡Hagan que sangren!' WHERE `ID`=41606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=41607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳건히 버텨라... 싸워라!', `MaleText_loc4`='坚守阵地……战斗！', `MaleText_loc5`='堅守陣地...戰鬥!', `MaleText_loc7`='¡Mantengan posiciones... luchen!' WHERE `ID`=41608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오크다. 전투를 위해 태어났다! 오크답게 싸워라! 후퇴는 없다!', `MaleText_loc4`='你们天生就是英勇的兽人战士！绝不后退半步！', `MaleText_loc5`='帶著獸人的光榮之血而戰!背水一戰!', `MaleText_loc7`='¡Luchen como los orcos que son! ¡No hay retirada!' WHERE `ID`=41609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가... 졌네. 어서 도망치게...', `MaleText_loc4`='我们……被打败了。尽量逃走……', `MaleText_loc5`='我們被...打敗了。能逃就快逃吧...', `MaleText_loc7`='Nos han... vencido. Huye si puedes...' WHERE `ID`=41610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 이놈의 나가들, 정말 지긋지긋해 죽겠군.', `MaleText_loc4`='以萨尔之名！到处都是敌人……', `MaleText_loc5`='索爾老大啊!他們無所不在!', `MaleText_loc7`='¡Por Thrall! ¡Están en todos lados!' WHERE `ID`=41611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 님! 놈들이 저를...', `MaleText_loc4`='纳兹戈林！他们抓住我了……', `MaleText_loc5`='納茲格寧姆!他們逮到我了....', `MaleText_loc7`='¡Nazgrim! Me han capturado...' WHERE `ID`=41612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아아!', `MaleText_loc4`='啊！！', `MaleText_loc5`='呃啊啊啊啊!!', `MaleText_loc7`='¡¡¡Grooooar!!!' WHERE `ID`=41613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쐐기에 꽂혀 머리가 노출되었습니다!', `MaleText_loc4`='%s将自己钉在刺上，露出了他的头！', `MaleText_loc5`='%s被釘在尖刺上，露出了他的頭!', `MaleText_loc7`='¡%s acaba empalado en el pincho y deja expuesta la cabeza!' WHERE `ID`=41614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군!', `MaleText_loc4`='真是令人震惊！', `MaleText_loc5`='了不起!', `MaleText_loc7`='¡Alucinante!' WHERE `ID`=41615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일에는 자네가 제격이군, 두아른. 나는 밖의 문제에 관여해야만 하네.', `MaleText_loc4`='这份工作对你来说再适合不过了，达鲁。我必须去处理外面的事情。', `MaleText_loc5`='這份工作再適合你不過了，杜亞恩。我在外面還有必須處理的事情。', `MaleText_loc7`='Este trabajo te viene al pelo, Duarn. Yo debo ocuparme de otros asuntos en el exterior.' WHERE `ID`=41616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 행운을 빌겠네, $n.', `MaleText_loc4`='也祝你好运，$n。', `MaleText_loc5`='你也是，祝你好運，$n。', `MaleText_loc7`='Buena suerte para ti también, $n.' WHERE `ID`=41617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부대장님, 제가 그 조각을 한번 살펴봐도 되겠습니까? 동굴 저편에서 그 힘이 뿜어져 나오는 것이 느껴집니다.', `FemaleText_loc4`='让我看看那碎片，可以吗队长？我能感觉到它的能量正从洞穴的另一侧放射出来。', `FemaleText_loc5`='隊長，能讓我看一下那個碎片嗎?我可以感受到它的力量從洞穴的那一邊散發過來。', `FemaleText_loc7`='Déjame echar un vistazo a ese fragmento, capitán. Puedo sentir el poder que emana desde el otro lado de la cueva.' WHERE `ID`=41618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 멀었다...', `MaleText_loc4`='还不够好……', `MaleText_loc5`='還不夠好...', `MaleText_loc7`='No fue suficiente…' WHERE `ID`=41619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 아래에 묻혀 있는 것들에 대해 불평할 수는 없어. 모두 대체품뿐이거든. 대체품도 대체할 것들. 며칠만 시간을 주면 해초와 조개껍데기를 벗어날 고성능 수중 유영기를 만들어 보겠어!', `MaleText_loc4`='这些水下的资源真是让人无话可说。任何工程材料和替换件都能找到代用品。给我几天时间，我就能用水藻和贝壳做出一辆水下改装跑车！', `MaleText_loc5`='這邊的材料實在沒什麼好抱怨的。什麼東西都能替代。連替代品都能替代。嘿，再給我個幾天，我就用海藻和貝殼做輛車出來給你看!', `MaleText_loc7`='No puedo quejarme de los materiales que hay aquí abajo. Recambios para todo. Recambios de los recambios. ¡Dame unos cuantos días y construiré un bólido acuático con las algas y las conchas!' WHERE `ID`=41620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 바위봉쇄 감옥을 빼앗겼습니다!', `MaleText_loc4`='部落失去了斯通沃德监狱的控制权！', `MaleText_loc5`='部落失去了石衛監獄的控制權!', `MaleText_loc7`='¡La Horda ha perdido el control de la Prisión Guardapétrea!' WHERE `ID`=41621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 바위봉쇄 감옥을 빼앗겼습니다!', `MaleText_loc4`='联盟失去了斯通沃德监狱的控制权！', `MaleText_loc5`='聯盟失去了石衛監獄的控制權!', `MaleText_loc7`='¡La Alianza ha perdido el control de la Prisión Guardapétrea!' WHERE `ID`=41622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 바위봉쇄 감옥을 차지했습니다!', `MaleText_loc4`='联盟夺取了斯通沃德监狱的控制权！', `MaleText_loc5`='聯盟獲得了石衛監獄的控制權!', `MaleText_loc7`='¡La Alianza tiene el control de la Prisión Guardapétrea!' WHERE `ID`=41623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 바위봉쇄 감옥을 차지했습니다!', `MaleText_loc4`='部落夺取了斯通沃德监狱的控制权！', `MaleText_loc5`='部落獲得了石衛監獄的控制權!', `MaleText_loc7`='¡La Horda tiene el control de la Prisión Guardapétrea!' WHERE `ID`=41624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 극단적인 실험을 하면 결과를 예측할 수가 없는데...', `MaleText_loc4`='当被逼入绝境，结果可能是无法预料的……', `MaleText_loc5`='抵達極限時，結果可能會難以預測...', `MaleText_loc7`='Llevado al extremo, los resultados son impredecibles…' WHERE `ID`=41625;
