UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 젊은 나이에 죽을 수는 없어! 젠장, 난 죽기에는 너무 잘생겼단 말이야!', `MaleText_loc4`='我还年轻，我不想死！见鬼，我那么漂亮，怎么能死！', `MaleText_loc5`='我太年輕了，還不該死!嘿，我太好看了，我還不能死!', `MaleText_loc7`='¡Soy demasiado joven para morir! ¡Diablos, soy demasiado guapo para morir!' WHERE `ID`=41640;
