UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 당신 잘못인 거야! 죽은 줄로만 알았는데! 이제 당신 머리를 먹었잖아!', `MaleText_loc4`='这都是你的错！它本该已经死了！现在它吃掉了你的脑子！', `MaleText_loc5`='都是你的錯!它本來應該要死了的!現在它要吃掉你的腦袋了!', `MaleText_loc7`='¡Es culpa tuya! ¡Se suponía que estaba muerto! ¡Ahora se ha comido tu cerebro!' WHERE `ID`=41644;
