UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF68228B나에게 복종한 뒤 고통스럽게 죽을 것이다.|r', `MaleText_loc4`='|cFF68228B你将侍奉我，然后在痛苦中死去。|r', `MaleText_loc5`='|cFF68228B你將服侍於我，然後痛苦地死去。|r', `MaleText_loc7`='|cFF68228BME SERVIRÁS Y DESPUÉS MORIRÁS DOLOROSAMENTE.|r', `FemaleText_loc1`='|cFF68228B나에게 복종한 뒤 고통스럽게 죽을 것이다.|r', `FemaleText_loc4`='|cFF68228B你将侍奉我，然后在痛苦中死去。|r', `FemaleText_loc5`='|cFF68228B你將服侍於我，然後痛苦地死去。|r', `FemaleText_loc7`='|cFF68228BME SERVIRÁS Y DESPUÉS MORIRÁS DOLOROSAMENTE.|r' WHERE `ID`=41651;
