UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF68228B네 눈앞에서 세상이 부서질 것이다.|r', `MaleText_loc4`='|cFF68228B你的世界在你的面前崩溃。|r', `MaleText_loc5`='|cFF68228B你的世界在你眼前崩毀。|r', `MaleText_loc7`='|cFF68228BTU MUNDO SE DESMORONA ANTE TI.|r', `FemaleText_loc1`='|cFF68228B네 눈앞에서 세상이 부서질 것이다.|r', `FemaleText_loc4`='|cFF68228B你的世界在你的面前崩溃。|r', `FemaleText_loc5`='|cFF68228B你的世界在你眼前崩毀。|r', `FemaleText_loc7`='|cFF68228BTU MUNDO SE DESMORONA ANTE TI.|r' WHERE `ID`=41653;
