UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF68228B너의 어리석음으로는 무슨 일이 일어나는지조차도 알지 못할 것이다.|r', `MaleText_loc4`='|cFF68228B你简单的头脑不可能领悟这其中的真相。|r', `MaleText_loc5`='|cFF68228B這不是你愚蠢的腦袋所能理解的。|r', `MaleText_loc7`='|cFF68228BTU MENTE SIMPLE NO ALCANZA A COMPRENDER LO QUE OCURRE.|r', `FemaleText_loc1`='|cFF68228B너의 어리석음으로는 무슨 일이 일어나는지조차도 알지 못할 것이다.|r', `FemaleText_loc4`='|cFF68228B你简单的头脑不可能领悟这其中的真相。|r', `FemaleText_loc5`='|cFF68228B這不是你愚蠢的腦袋所能理解的。|r', `FemaleText_loc7`='|cFF68228BTU MENTE SIMPLE NO ALCANZA A COMPRENDER LO QUE OCURRE.|r' WHERE `ID`=41655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더러운 짐승 같으니!', `FemaleText_loc4`='无耻的怪物！', `FemaleText_loc5`='邪惡的怪物!', `FemaleText_loc7`='¡Bestias asquerosas!' WHERE `ID`=41656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 땅에서 떠나라!', `FemaleText_loc4`='滚出我们的土地！', `FemaleText_loc5`='滾出我們的土地!', `FemaleText_loc7`='¡Abandonad nuestras tierras!' WHERE `ID`=41657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리 빠르지는 않군!', `FemaleText_loc4`='不要那么快！', `FemaleText_loc5`='沒那麼快!', `FemaleText_loc7`='¡No tan rápido!' WHERE `ID`=41658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 보기에 여긴 폐허만큼 멋지지도 않고, 공기도 약간 축축하군요. 그렇지만 편안하고 내 집 같은 느낌은 드네요.$B$B안 그런가요?', `MaleText_loc4`='这地方跟废墟相比没那么凉爽，如果要我说的话，这儿的空气也有些太过潮湿，不过确实给我一种舒服的、回到家里的感觉。$B$B你不这么认为吗？', `MaleText_loc5`='這個地方沒有遺跡那麼涼爽，而且我覺得濕氣也太重了點。不過，還是蠻舒適、蠻有家的感覺啦。$B$B你說是吧?', `MaleText_loc7`='Este lugar no es tan frío como las ruinas y el aire es un poco húmedo, si quieres saber mi opinión, pero tiene un toque confortable y hogareño.$B$B¿No crees?' WHERE `ID`=41659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헥사스크럽, 그 무자비한 생물을 제게 주십시오.', `MaleText_loc4`='“洗衣桶”，让我再看看那个无悯者。', `MaleText_loc5`='赫克薩克拉，讓我再看看那隻殘虐獸。', `MaleText_loc7`='Friegahexágonos, déjame ver a ese despiadado otra vez.', `FemaleText_loc1`='헥사스크럽, 그 무자비한 생물을 제게 주세요.', `FemaleText_loc4`='“洗衣桶”，让我再看看那个无悯者。', `FemaleText_loc5`='赫克薩克拉，讓我再看看那隻殘虐獸。', `FemaleText_loc7`='Friegahexágonos, déjame ver a ese despiadado otra vez.' WHERE `ID`=41660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 어떨지 몰라도, 난 폐허 밑에 묻힌 무한한 원자재가 정말 너무나 아깝다고!$B$B이 동굴에서 허접스러운 폭탄이라도 만들어 뭘 좀 뜯어낼 수나 있을지!', `MaleText_loc4`='我不知道你怎么想，可我真的很想念下面废墟里那些取之不尽的原料！$B$B就凭我们在这洞里找到的少得可怜的材料，我甚至都不知道能不能造出一颗哑弹！', `MaleText_loc5`='我是不知道你怎麼想，可是我真的很懷念廢墟那邊取之不盡的原料!$B$B這個洞裡根本什麼鳥東西也沒有，連個假手榴彈我都不知道做不做得出來!', `MaleText_loc7`='¡No sé tú, pero yo sí que echo de menos el ilimitado surtido de materias primas que había bajo las ruinas!$B$B¡No estoy seguro de que ahora pudiera fabricar una simple granada con lo poco que podemos sacar de esta cueva!' WHERE `ID`=41661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피아스코, 그 무자비한 생물을 다시 한번 봐야겠습니다.', `MaleText_loc4`='菲亚斯科，我想再看看那无悯之头。', `MaleText_loc5`='菲亞斯戈，我得再看看那隻殘虐獸屍體。', `MaleText_loc7`='Fiasco, tengo que ver ese cuerpo despiadado de nuevo.', `FemaleText_loc1`='피아스코, 그 무자비한 생물을 다시 한번 봐야겠어요.', `FemaleText_loc4`='菲亚斯科，我想再看看那无悯之头。', `FemaleText_loc5`='菲亞斯戈，我得再看看那隻殘虐獸屍體。', `FemaleText_loc7`='Fiasco, tengo que ver ese cuerpo despiadado de nuevo.' WHERE `ID`=41662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 놈들.$B$B<역겨워하며 바닥에 침을 뱉는 바일쏜>$B$B채찍으로 오크를 노예로 만들 수 있다고 생각하다니 정말 멍청한 놈들이군. 기회가 있을 때 우릴 죽이지 않았던 것을 뼈저리게 후회하게 해줄 걸세.', `MaleText_loc4`='纳迦。$B$B<维索恩充满厌恶地朝地上吐了口唾沫。>$B$B他们可真蠢，居然妄想能用鞭子把兽人训得任其差遣。我们要让他们后悔，没把握住机会杀了我们，让他们一个个全都后悔。', `MaleText_loc5`='納迦。$B$B<惡刺不屑地在地上啐了一口。>$B$B他們愚蠢地以為可以用鞭子來奴役獸人為他們工作。哼，我們要讓他們每一隻都後悔，當時有機會的時候竟然沒把我們給殺了。', `MaleText_loc7`='Nagas.$B$B<Espinavil escupe en el suelo con disgusto.>$B$BHa sido bastante tonto por su parte creer que podían hacer trabajar a un orco a ritmo de látigo. Haremos que hasta el último de ellos se arrepienta de no habernos matado cuando tuvieron la oportunidad.' WHERE `ID`=41663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, 친구여.

공급해드릴 것이 거의 없기는 합니다만, 할 수 있는 데까지 도와드리겠습니다.', `MaleText_loc4`='欢迎你，朋友。

虽然我们这儿没什么现成的补给品，可我一定会尽我所能为你提供帮助。', `MaleText_loc5`='歡迎，朋友。

雖然我們無法提供你什麼補給品，但我還是會盡全力協助你。', `MaleText_loc7`='Te doy la bienvenida, camarada.

No tenemos mucho que ofrecerte en tema de suministros, pero te ayudaré en todo lo que pueda.' WHERE `ID`=41664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 구조 계획은 기발하기도 하지. 한 치의 실수도 없어. 이 계획을 방해할 수 있는 건 고블린뿐일 거야. 아가미 달린 고블린 말이야. 지긋지긋해.', `MaleText_loc4`='我的营救计划非常完美。简直无懈可击。只有一个地精可能阻止我成功。一个长鳍的地精。这想法可真可怕。', `MaleText_loc5`='我的拯救計畫英明可靠、天衣無縫。只有一個哥布林有可能阻止得了我。一個有鰭的哥布林。真嚇人。', `MaleText_loc7`='Mi plan de rescate es brillante. Infalible. Tan solo un goblin podría impedirme tener éxito. Un goblin con aletas. Que pensamiento tan terrible.' WHERE `ID`=41665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 오크라니... 이거 익숙해지려면 시간 좀 걸리겠군...', `MaleText_loc4`='啊！兽人……这得慢慢习惯才行……', `MaleText_loc5`='嘎!獸人...這可能要點時間才能習慣...', `MaleText_loc7`='¡Argh! Orcos... Me va a costar acostumbrarme...' WHERE `ID`=41666;
