UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='착한 동생은 오빠 말 잘 들어!', `FemaleText_loc4`='所有好女孩都听爸爸的话！', `FemaleText_loc5`='乖女孩都會聽他們爸爸的話!', `FemaleText_loc7`='¡Todas las niñas buenas hacen caso a sus papás!' WHERE `ID`=41669;
