UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 이야기를 더 들려 주십시오.', `MaleText_loc4`='是的，我还想知道更多。', `MaleText_loc5`='是的，我想要再多聽一些。', `MaleText_loc7`='Sí, cuéntame más.', `FemaleText_loc1`='네, 이야기를 더 들려 주세요.', `FemaleText_loc4`='是的，我还想知道更多。', `FemaleText_loc5`='是的，我想要再多聽一些。', `FemaleText_loc7`='Sí, cuéntame más.' WHERE `ID`=41691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오십시오, $c|1이여;여;!', `FemaleText_loc4`='欢迎你，$c！', `FemaleText_loc5`='歡迎，$c!', `FemaleText_loc7`='¡Te doy la bienvenida, $c!' WHERE `ID`=41692;
