UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나타나곤 "하셨다"니요? 그분에게 무슨 일이 일어났습니까?', `MaleText_loc4`='你为什么用过去式讲话？她发生了什么事？', `MaleText_loc5`='你說「在她生前」。她後來怎麼了?', `MaleText_loc7`='Hablas de ella en pasado. ¿Qué le ocurrió?', `FemaleText_loc1`='나타나곤 "하셨다"니요? 그분에게 무슨 일이 일어났나요?', `FemaleText_loc4`='你为什么用过去式讲话？她发生了什么事？', `FemaleText_loc5`='你說「在她生前」。她後來怎麼了?', `FemaleText_loc7`='Hablas de ella en pasado. ¿Qué le ocurrió?' WHERE `ID`=41694;
