UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지감시자들은 이곳에서 알력 다툼으로 옥신각신하며 대지 고리회의 임무를 방해하는 것을 허용하지 않을 것입니다.

평화를 위협하는 자들은... 단호한 처벌을 받을 것입니다.', `MaleText_loc4`='大地观察者不会容许派系争斗威胁到大地之环在此地的工作。

任何打破和平的人，都将面临……严厉的处罚。', `MaleText_loc5`='大地看守者絕不允許陣營之間的紛爭危及到陶土議會在此的運作。

凡是破壞和平者都會受到...嚴厲的處罰。', `MaleText_loc7`='Los Vigiatierra no permitirán que las riñas entre facciones pongan en peligro el trabajo del Anillo de la Tierra en este lugar.

Aquellos que perturben la paz serán castigados... severamente.' WHERE `ID`=41698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 되었습니까?', `MaleText_loc4`='后来发生了什么事？', `MaleText_loc5`='後來發生了什麼事情?', `MaleText_loc7`='¿Qué ocurrió después?', `FemaleText_loc1`='그래서 어떻게 되었나요?', `FemaleText_loc4`='后来发生了什么事？', `FemaleText_loc5`='後來發生了什麼事情?', `FemaleText_loc7`='¿Qué ocurrió después?' WHERE `ID`=41699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머는 언제나 주술의 힘을 존중해 왔습니다. 그렇고 말고요. 그렇지만 대지 고리회 일원이 된 우리 자신을 바다 밑에서 찾으라는 말입니까?

그것을 믿으려고 큰 잔으로 몇 번이나 술을 마셨던 것 같군요. 한 일 년 전에 말입니다.', `MaleText_loc4`='蛮锤总是对萨满巫术青睐有加，这没错，可让我们待在海底下，作为大地之环的一员？

要是在一年前，几大杯啤酒就能让我相信这个事实。', `MaleText_loc5`='蠻錘氏族向來是薩滿信仰的擁護者，沒錯，可是來到海底下變成跟陶土議會混在一起?

啊，要是換做一年前，給我喝再多杯酒我也還是不會相信。', `MaleText_loc7`='Los Martillo Salvaje siempre han abrazado el chamanismo, sí, ¿pero acabar bajo el mar como parte del Anillo de la Tierra?

Hace un año habría necesitado más que unas pocas jarras para creerme eso.' WHERE `ID`=41700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전사와 오랫동안 동화한 결과, 새로운 능력을 얻었습니다!', `MaleText_loc4`='正在使你与女武士进一步协调，你已获得一项新技能！', `MaleText_loc5`='與戰鬥仕女的協調更為一致，你獲得了一項新能力!', `MaleText_loc7`='Para que estés en sintonía con la doncella de batalla, ¡has ganado una nueva habilidad!', `FemaleText_loc1`='여전사와 오랫동안 동화한 결과, 새로운 능력을 얻었습니다!', `FemaleText_loc4`='正在使你与女武士进一步协调，你已获得一项新技能！', `FemaleText_loc5`='與戰鬥仕女的協調更為一致，你獲得了一項新能力!', `FemaleText_loc7`='Para que estés en sintonía con la doncella de batalla, ¡has ganado una nueva habilidad!' WHERE `ID`=41701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 전사들이... 모두 잡혀가 버렸네.', `MaleText_loc4`='我们的战士……他们现在都已沦为俘虏。', `MaleText_loc5`='我們的戰士...現在他們全都變成俘虜了。', `MaleText_loc7`='Nuestros guerreros... son todos prisioneros.' WHERE `ID`=41702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이들이 나가로부터 도망치려고 했지.$b$b그렇지만 나 혼자만 살아남았네...', `MaleText_loc4`='我们当中有许多人试图摆脱纳迦。$b$b可只有我成功了……', `MaleText_loc5`='我們有很多人都試過要逃離那些納迦。$b$b我是唯一成功的...', `MaleText_loc7`='Muchos de nosotros intentamos escapar de los nagas.$b$bY yo soy el único que lo ha conseguido...' WHERE `ID`=41703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해는 되지 않지만, 저 해충들이 우리 군대를 아주 오랫동안 살려둘 모양이네...', `MaleText_loc4`='这说不通，可那些恶棍却不遗余力地想要延长我们的生命……', `MaleText_loc5`='很沒有道理，那些混蛋大費周章保住我們部隊的性命...', `MaleText_loc7`='No tiene mucho sentido, pero esas alimañas se están esforzando mucho para mantener vivas a nuestras tropas...' WHERE `ID`=41704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름을 말해 주십시오, 오크여.', `MaleText_loc4`='告诉我你的名字，兽人。', `MaleText_loc5`='告訴我你的名字，獸人。', `MaleText_loc7`='Dime tu nombre, orco.', `FemaleText_loc1`='이름을 말해 주세요, 오크여.', `FemaleText_loc4`='告诉我你的名字，兽人。', `FemaleText_loc5`='告訴我你的名字，獸人。', `FemaleText_loc7`='Dime tu nombre, orco.' WHERE `ID`=41705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 구로크, 헬스크림 선봉대원이네.', `MaleText_loc4`='我们是地狱咆哮的先锋战士！', `MaleText_loc5`='我叫古爾洛克，隸屬地獄吼的先鋒。', `MaleText_loc7`='Soy Gurrok, de la vanguardia de Grito Infernal.' WHERE `ID`=41706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 어떻게 내려왔습니까?', `MaleText_loc4`='你是怎么下来的？', `MaleText_loc5`='你怎麼會來到下面這邊?', `MaleText_loc7`='¿Cómo has llegado aquí abajo?', `FemaleText_loc1`='이곳에 어떻게 내려왔나요?', `FemaleText_loc4`='你是怎么下来的？', `FemaleText_loc5`='你怎麼會來到下面這邊?', `FemaleText_loc7`='¿Cómo has llegado aquí abajo?' WHERE `ID`=41707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 끝장낼 수 있었네!$b$b거의 조각난 얼라이언스 함선을... 스톰윈드로 향하는 항로를 차단할 수 있었단 말이지!$b$b...그런데 갑자기 어디선가 거대한 촉수가 올라와 우리 배를 감싸더니... 정확히 두 동강을 내버렸네!$b$b생존자들은... 우리들은 물에 빠지자마자 나가에게 생포되었고.', `MaleText_loc4`='我们抓到他们了！$b$b该死的联盟船只……我们本可以第一时间抄近路直取暴风城，彻底解决了他们！$b$b可不知打哪儿冒出来巨大的触手，一把抓住了我们的船……把它断成了两截！$b$b幸存者们……我们一落水就立刻被纳迦抓住了。', `MaleText_loc5`='我們逮到他們了!$b$b該死的聯盟艦隊...我們本來可以直接殺到暴風城，把他們通通幹掉!$b$b...但是不知道從哪裡冒出來的巨大觸手忽然伸出來抓住了我們的船...把它折成兩半!$b$b我們這些生還者才掉進水裡...就馬上被納迦給抓走了。', `MaleText_loc7`='¡Los teníamos!$B$BEsos malditos barcos de la Alianza... ¡Y podríamos haberles cortado el paso hacia Ventormenta y haber acabado con ellos!$b$b... Pero de la nada aparecieron unos tentáculos que se alzaron y atraparon nuestro barco... ¡lo partieron en dos!$b$bLos supervivientes... fuimos capturados por los nagas en cuanto tocamos el agua.' WHERE `ID`=41708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로들에 대해 이야기해 주십시오, 구로크.', `MaleText_loc4`='告诉我们是谁把你抓住的，古罗克。', `MaleText_loc5`='告訴我們，是誰把你們抓走的，古爾洛克。', `MaleText_loc7`='Háblanos de tus captores, Gurrok.', `FemaleText_loc1`='포로들에 대해 이야기해 주세요, 구로크.', `FemaleText_loc4`='告诉我们是谁把你抓住的，古罗克。', `FemaleText_loc5`='告訴我們，是誰把你們抓走的，古爾洛克。', `FemaleText_loc7`='Háblanos de tus captores, Gurrok.' WHERE `ID`=41709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 우리를 살려두다니 정말 이상한 일이었네.$b$b나가들은 신비한 진주 감옥을 만들어 우리를 가두었지. 그 안에서 숨을 쉴 수는 있었지만, 그것뿐이었다네.$b$b그 후 나가들은 포로를... 어딘가로 보냈지.$b$b그 포로들은 다시는 볼 수 없었네...', `MaleText_loc4`='真是奇怪，从没想过纳迦竟然会设法让我们活下来。$b$b他们用神秘的珍珠造出牢房——让我们能够呼吸的小单间，然后就不管我们了……。$b$b他们每天都会送走一些囚犯……不知道去往哪里。$b$b再也没见过他们……', `MaleText_loc5`='很奇怪的是，這些納迦竟然還一反常態地保住了我們的性命。$b$b把我們關進用神秘的珍珠做成的牢房，讓我們可以呼吸...$b$b他們把囚犯運送到...別的地方。$b$b再也沒看到他們....', `MaleText_loc7`='Fue raro que los nagas se molestaran en mantenernos con vida.$b$bCrearon prisiones a partir de perlas místicas... Celdas en las que podíamos respirar, pero nada más.$b$bEnviaban prisioneros a... alguna parte.$b$bNunca los volvimos a ver...' WHERE `ID`=41710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 어떻게 빠져나왔습니까?', `MaleText_loc4`='你是怎么逃脱的呢？', `MaleText_loc5`='你怎麼有辦法逃走?', `MaleText_loc7`='¿Cómo escapaste?', `FemaleText_loc1`='그곳에서 어떻게 빠져나왔나요?', `FemaleText_loc4`='你是怎么逃脱的呢？', `FemaleText_loc5`='你怎麼有辦法逃走?', `FemaleText_loc7`='¿Cómo escapaste?' WHERE `ID`=41711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대원 중 하나가 그 감옥에서 빠져나와 다른 포로들을 풀어주었네... 우리는 자유였지... 잠깐 동안은 말이야.$b$b어떤 이들은 물 위로 헤엄쳐 올라가고... 어떤 이들은 이 동굴을 발견하고 이리로 왔네.$b$b그렇지만 결국엔 나 혼자만 살아남았어...', `MaleText_loc4`='我们当中有位战士得以逃脱，并打碎了许多牢笼……我们自由了——至少是片刻的自由。$b$b有些人朝水面蜂拥游去……有些则看到并朝这个洞穴游来。$b$b我是唯一活下来的人……', `MaleText_loc5`='我們有個戰士掙脫了出來，然後打破了許多個牢房...我們重獲自由—至少暫時如此。$b$b有些人朝海面游上去...有些人看到這個洞穴游了過來。$b$b我是唯一的倖存者....', `MaleText_loc7`='Uno de nuestros guerreros consiguió escapar y rompió muchas de las celdas... Éramos libres, por lo menos durante unos instantes.$b$bAlgunos nadaron hacia la superficie... otros vimos esta cueva y tratamos de llegar a ella.$b$bYo soy el único que lo consiguió...' WHERE `ID`=41712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 차렷!', `MaleText_loc4`='步兵们，立正站好！', `MaleText_loc5`='士兵們，立正!', `MaleText_loc7`='¡A ver, inútiles, ATENCIÓN!' WHERE `ID`=41713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림과 그의 병사들을 본 적이 있습니까?', `MaleText_loc4`='你有见到纳兹戈林和他的部队吗？', `MaleText_loc5`='你有看到納茲格寧姆和他的部隊嗎?', `MaleText_loc7`='¿Viste a Nazgrim y a sus tropas?', `FemaleText_loc1`='나즈그림과 그의 병사들을 본 적이 있나요?', `FemaleText_loc4`='你有见到纳兹戈林和他的部队吗？', `FemaleText_loc5`='你有看到納茲格寧姆和他的部隊嗎?', `FemaleText_loc7`='¿Viste a Nazgrim y a sus tropas?' WHERE `ID`=41714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 아군이 어떻게 되었는지는 모르겠네.$b$b호드든 얼라이언스든 가리지 않고 계속해서 포로들이 끌려왔으니까. 모두 간신히 숨만 붙어서 말이야.$b$b아마 협곡 너머로 끌려갔거나, 아니면 죽었을 거네.', `MaleText_loc4`='我不知道他们发生了什么事。$b$b不断有俘虏出现。部落和联盟的都有——几乎都只剩下一口气。$b$b他们一定是被强行拖到海沟那边去了，不然就只有死路一条。', `MaleText_loc5`='我不知道他們的下場如何。$b$b一直不斷有俘虜被送走，有部落的也有聯盟的，全部都奄奄一息。$b$b他們一定是被帶到海溝之外的地方，或者是已經不幸死亡了吧。', `MaleText_loc7`='No sé qué fue de ellos.$b$bHabía un flujo constante de prisioneros. De la Horda y de la Alianza, y apenas estaban vivos.$b$bSe los habrán llevado más allá de la trinchera, o habrán muerto.' WHERE `ID`=41715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물들에 대해 알려주실 게 있습니까, 구로크? 어떻게 하면 나가를 이길 수 있습니까?', `MaleText_loc4`='那该怎么解决这些怪物呢，古罗克？我们该如何击败他们？', `MaleText_loc5`='關於這些怪獸你還有什麼要報告的嗎，古爾洛克?我們該怎樣打敗他們?', `MaleText_loc7`='¿Qué puedes contarnos de esas bestias, Gurrok? ¿Cómo podemos derrotarlas?', `FemaleText_loc1`='이 괴물들에 대해 알려주실 게 있나요, 구로크? 어떻게 하면 나가를 이길 수 있죠?', `FemaleText_loc4`='那该怎么解决这些怪物呢，古罗克？我们该如何击败他们？', `FemaleText_loc5`='關於這些怪獸你還有什麼要報告的嗎，古爾洛克?我們該怎樣打敗他們?', `FemaleText_loc7`='¿Qué puedes contarnos de esas bestias, Gurrok? ¿Cómo podemos derrotarlas?' WHERE `ID`=41716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 셀 수도 없을 정도로 많네. 방어도 빈틈없이 단단한 것 같고.$b$b파고들 만한 약점 같은 것은 보지 못했네, $r 친구.', `MaleText_loc4`='他们的人数多得难以计算。他们的防御仿佛无懈可击。$b$b我找不出任何可以利用的薄弱环节，$r。', `MaleText_loc5`='他們的數量多到數不清，而且看起來他們的防禦也同樣牢不可破。$b$b我看不出來有任何可以利用的弱點，$r。', `MaleText_loc7`='Son tantos que es imposible contarlos. Sus defensas parecen impenetrables.$b$bNo vi ningún punto débil del que podamos aprovecharnos, $r.' WHERE `ID`=41717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있어, 이놈의 물고기!', `MaleText_loc4`='待着别动，小鱼！', `MaleText_loc5`='小魚你別亂動!', `MaleText_loc7`='¡Estate quieto, pez!' WHERE `ID`=41718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 그렇게 나를 놀려야겠냐?', `MaleText_loc4`='你为什么非要如此嘲弄我？', `MaleText_loc5`='你為什麼要這樣折磨我?', `MaleText_loc7`='¿Por qué me provocas de esa forma?' WHERE `ID`=41719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, "주얼스" 선장이 화낼 텐데...', `MaleText_loc4`='哦，珍宝船长要发怒了……', `MaleText_loc5`='哦，『珠寶』船長一定會很生氣...', `MaleText_loc7`='Oh, el capitán Julios se va a enfadar mucho...' WHERE `ID`=41720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리... 오... 라... 고...', `MaleText_loc4`='回到……这儿……来……', `MaleText_loc5`='給...我...回...來...', `MaleText_loc7`='Vuelve... aquí...' WHERE `ID`=41721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 물고기!', `MaleText_loc4`='啊哈！一条鱼！', `MaleText_loc5`='啊哈!一條魚!', `MaleText_loc7`='¡AJÁ! ¡UN PEZ!' WHERE `ID`=41722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이란다, 물고기야 물고기야...', `MaleText_loc4`='过来，小乖鱼儿……', `MaleText_loc5`='來喔，小魚小魚...', `MaleText_loc7`='Aquí, pececito bonito, pececito...' WHERE `ID`=41723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 당황스럽다. 목격한 것 때문에...', `MaleText_loc4`='我糊涂了。我所见到的一切让我困惑不已……', `MaleText_loc5`='我很困惑。我對目睹的東西很擔心...', `MaleText_loc7`='Estoy perplejo. Preocupado por lo que veo...' WHERE `ID`=41724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 상황에서 벗어나고 싶단 말이에요!', `FemaleText_loc4`='快把我弄出去！', `FemaleText_loc5`='讓我離開這裡!', `FemaleText_loc7`='¡Sácame de aquí!' WHERE `ID`=41725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 멍청하게 죽은 바다 악마를 머리에 써요?!', `FemaleText_loc4`='谁会把“死”海怪放到他们脑袋上，真有这事儿？！', `FemaleText_loc5`='說真的，誰會把「死掉的」海惡魔的頭放到他們的頭上?!', `FemaleText_loc7`='De verdad, hombre, ¿quién se pone la cabeza de un demonio del mar "muerto" en la cabeza?' WHERE `ID`=41726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피아스코, 왜 이리 멍청한 거야! 다음번엔 그냥 날려버려!', `FemaleText_loc4`='菲亚斯科，你可真是个蠢货！下次随便找个什么东西炸了！', `FemaleText_loc5`='菲亞斯戈，你這白痴!下回你只要負責炸東西就好!', `FemaleText_loc7`='¡Fiasco, eres un idiota! ¡Lo próxima vez limítate a hacer saltar algo por los aires!' WHERE `ID`=41727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 왜 이걸 두려워하고 있지?', `FemaleText_loc4`='我干嘛要怕这玩意儿？', `FemaleText_loc5`='為什麼我會害怕這個?', `FemaleText_loc7`='¿Por qué tengo miedo de esto?' WHERE `ID`=41728;
