UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바뀐 대족장님이 제군들 기대에 못 미치던가?', `MaleText_loc4`='我们敬爱的酋长怎么让你失望了？', `MaleText_loc5`='我們尊敬的大酋長是怎樣讓你失望了?', `MaleText_loc7`='¿Cómo les ha fallado nuestro reverenciado jefe de guerra?' WHERE `ID`=41740;
