UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제군들 가족이 굶주릴 일은 없다.', `MaleText_loc4`='你的家人不用再忍饥受饿。', `MaleText_loc5`='你的家人不會再受餓。', `MaleText_loc7`='Sus familias ya no mueren de hambre.' WHERE `ID`=41742;
