UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 기다리고 있었습니다, 사절이여.', `MaleText_loc4`='大使，我们一直在等您。', `MaleText_loc5`='大使，我們正在等你呢。', `MaleText_loc7`='Embajador. Te esperábamos.' WHERE `ID`=41744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 거리를 당당하게 걸을 수 있다!', `MaleText_loc4`='你可以昂首挺胸地走在奥格瑞玛的街道上！', `MaleText_loc5`='你可以驕傲地走在奧格瑪的街道上!', `MaleText_loc7`='¡Puedes caminar por las calles de Orgrimmar lleno de orgullo!' WHERE `ID`=41745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 헬스크림 님이 이끄시는, 새로운 호드다. 우리 운명은 우리가 개척한다.', `MaleText_loc4`='在地狱咆哮酋长的率领下，我们成为了新的部落，我们是自己命运的主人。', `MaleText_loc5`='我們是新的部落，而且在大酋長地獄吼的統領之下，我們將充分掌握自己的命運。', `MaleText_loc7`='Nosotros somos la nueva Horda, y bajo el mando del jefe de guerra Grito Infernal somos dueños de nuestro propio destino.' WHERE `ID`=41746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 왜, 우리는 돌발톱 산맥을 장악하지 못했나?', `MaleText_loc4`='可为什么，我们没能夺回石爪山？', `MaleText_loc5`='那是為什麼?為什麼我們無法獲得石爪山脈?', `MaleText_loc7`='ENTONCES, ¿POR QUÉ hemos fracasado en tomar Sierra Espolón?' WHERE `ID`=41747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 얼라이언스 따위가 위대한 호드 전쟁 기계를 멈출 수 있었나?', `MaleText_loc4`='联盟是怎么阻止强大的部落战争机器的？', `MaleText_loc5`='聯盟為什麼有辦法阻止我們偉大的部落?', `MaleText_loc7`='¿Cómo ha podido la Alianza detener a la gran maquinaria de guerra de la Horda?' WHERE `ID`=41748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이후로, 실패는 용납하지 않는다.', `MaleText_loc4`='从今天开始，我们的字典里再无失败二字。', `MaleText_loc5`='從今天開始，我們不能再接受失敗。', `MaleText_loc7`='A partir de hoy, el fracaso no es una opción.' WHERE `ID`=41749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 지켜보시는 가운데, 죽든 살든 우리는 돌발톱을 접수한다.', `MaleText_loc4`='在地狱咆哮警觉的掩护下，不论生死，我们都要夺回石爪山。', `MaleText_loc5`='在地獄吼嚴厲的監督之下，不是生就是死，我們一定要拿下石爪山。', `MaleText_loc7`='Bajo la vigilante mirada de Grito Infernal, tomaremos Sierra Espolón, a vida o muerte.' WHERE `ID`=41750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머뭇거리지 마라. 헬스크림 님께서 제군 모두를 지켜보신다!', `MaleText_loc4`='不要退缩——地狱咆哮的双目在注视着你们每一个人！', `MaleText_loc5`='不准退縮，地獄吼的雙眼在盯著你們每一個人!', `MaleText_loc7`='¡No flaqueen, los ojos de Grito Infernal están fijos en ustedes!' WHERE `ID`=41751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문을 아무리 들여다봐도 눈에 들어오는 것은 모래뿐입니다. 기껏해야 사막의 폐허로 둘러싸인 물웅덩이가 전부입니다. 이 차원문은 과연 어디로 통하는 것일까요?', `MaleText_loc4`='向传送门的另一侧望去，你满眼却只看到黄沙。只能分辨出沙漠废墟当中的一池水。这传送门是通向哪里的呢？', `MaleText_loc5`='在傳送門的另一邊看到的是一片黃沙。你唯一能看到的就是一個被沙地廢墟所環繞的水塘。這個傳送門內的世界究竟是哪裡?', `MaleText_loc7`='Al mirar a través del portal tu ojo solo percibe arena. Todo lo que alcanzas a ver es una masa de agua rodeada de ruinas en un desierto. ¿Adónde conducirá este portal?' WHERE `ID`=41752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어갑니다.', `MaleText_loc4`='走进传送门。', `MaleText_loc5`='進入傳送門。', `MaleText_loc7`='Atraviesa el portal.', `FemaleText_loc1`='차원문으로 들어갑니다.', `FemaleText_loc4`='走进传送门。', `FemaleText_loc5`='進入傳送門。', `FemaleText_loc7`='Atraviesa el portal.' WHERE `ID`=41753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 안에 오래된 고대 사막이 보입니다. 바람이 거세지는 것을 보니, 차원문 안에서 모래 폭풍이 일고 있는 것이 분명합니다. 차원문은 중요한 미지의 장소로 연결된 것 같습니다. 하지만 대체 어디로?', `MaleText_loc4`='传送门里是一片古老的史前沙漠废墟。狂风吹过，一场沙尘暴呼之欲出。这传送门肯定是通往某个重要的地方，但究竟是哪里呢？', `MaleText_loc5`='傳送門中顯示了很久以前的遠古沙漠遺蹟。裡面吹著狂風，看來一定有沙塵風暴在蘊釀著。這個傳送門通往的一定是某個重要的地方，但會是哪裡?', `MaleText_loc7`='El portal muestras ruinas antiguas y erosionadas en un desierto. Este portal debe conducir a un lugar importante, pero, ¿adónde?' WHERE `ID`=41754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어갑니다.', `MaleText_loc4`='走进传送门。', `MaleText_loc5`='進入傳送門。', `MaleText_loc7`='Atraviesa el portal.', `FemaleText_loc1`='차원문으로 들어갑니다.', `FemaleText_loc4`='走进传送门。', `FemaleText_loc5`='進入傳送門。', `FemaleText_loc7`='Atraviesa el portal.' WHERE `ID`=41755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보처럼 이리저리 뛰어다니지 말게! 맞서란 말이네!', `MaleText_loc4`='你们这些蠢货别再四处乱跑了！面对惩罚吧！', `MaleText_loc5`='你們這些笨蛋，別再亂跑了!面對它!', `MaleText_loc7`='¡Dejad de correr, idiotas! ¡Afrontadlo!' WHERE `ID`=41756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 $n의 머리에 있는 것 좀 없애 주게!', `MaleText_loc4`='快来人，把$n的脑袋给我砍下来！', `MaleText_loc5`='誰去把那個東西從$n的頭上弄掉!', `MaleText_loc7`='¡Que alguien le quite eso de la cabeza a $n!' WHERE `ID`=41757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 우리 모두를 지켜보신다!', `MaleText_loc4`='地狱咆哮之眼注视着我们！', `MaleText_loc5`='地獄吼的雙眼在盯著我們!', `MaleText_loc7`='¡Los ojos de Grito Infernal están fijos en nosotros!' WHERE `ID`=41758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화났다. 종 부숴버리고 싶다.', `MaleText_loc4`='愤怒，渴望杀戮。', `MaleText_loc5`='憤怒，想要殺掉銅鑼。', `MaleText_loc7`='Enfadado, querer matar el gong, por favor.' WHERE `ID`=41759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보주 표면에는 인간의 손자국이 커다랗게 패여 있습니다. 부드러운 녹색 빛이 보주 안에 감도는 듯합니다.', `MaleText_loc4`='这颗宝珠上有一个巨大的人形生物掌印。掌印中似乎还脉动着一种绿色微光。', `MaleText_loc5`='一個巨大的人形掌印嵌在這顆光球的球面上。裡頭似乎還散發著忽強忽弱的的溫和綠光。', `MaleText_loc7`='La gran huella de una mano humanoide está incrustada en la superficie del cristal. Un suave brillo verde late en su interior.' WHERE `ID`=41760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅을 시작으로 어둠의 여왕님의 정복이 시작될 걸세. 잘 봐두게, $n. 머지않아 모두 포세이큰의 손아귀에 떨어지게 될 거야.', `FemaleText_loc4`='这些土地是黑暗女王征战的前线，$n。看看它们吧；过不了多久，这些都将落入被遗忘者的掌控之中。', `FemaleText_loc5`='這片土地是黑暗女王將要征服的前線，$n。看清楚了，過不了多久，它們都會落入被遺忘者的掌中。', `FemaleText_loc7`='Estas tierras son la frontera con la conquista de la Dama Oscura, $n. Míralas; con el tiempo, todo estará al alcance de los Renegados.' WHERE `ID`=41761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하... 영광스러운 마지막을 향해 역경을 뚫고 온 영웅들이로군. 기분은 좀 어떤가? 마지막 전투를 벌일 준비는 됐나? 그럼 내 궁극의 창조물을 보여주지! 일어나라, 자매여!', `MaleText_loc4`='啊，英雄们坚持到了辉煌的尾声。你们斗志昂扬，为最后一战做好准备了吧？那就看看我的终极造物！复活吧，妹妹！', `MaleText_loc5`='哈哈哈哈!英雄們來到了輝煌的終章。你們應該精神斗擻吧?準備好進行最後一戰了吧?那就看看我終極的創造!起來吧，妹妹!', `MaleText_loc7`='Los héroes han llegado al final glorioso. ¿Están de buen ánimo? ¿Listos para la batalla final? ¡Pues contemplen mi creación máxima! ¡DESPIERTA!' WHERE `ID`=41762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오!', `MaleText_loc4`='帮帮我！', `MaleText_loc5`='救我!', `MaleText_loc7`='¡Ayúdame!', `FemaleText_loc1`='도와주세요!', `FemaleText_loc4`='帮帮我！', `FemaleText_loc5`='救我!', `FemaleText_loc7`='¡Ayúdame!' WHERE `ID`=41763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 누가 우리한테 이러는 겁니까?', `MaleText_loc4`='是谁在对我们做这样的事？', `MaleText_loc5`='誰對我們做出這種事?', `MaleText_loc7`='¿Quién nos hace esto?', `FemaleText_loc1`='도대체 누가 저희에게 이러는 거죠?', `FemaleText_loc4`='是谁在对我们做这样的事？', `FemaleText_loc5`='誰對我們做出這種事?', `FemaleText_loc7`='¿Quién nos hace esto?' WHERE `ID`=41764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어나고 있는 겁니까?', `MaleText_loc4`='发生什么了？', `MaleText_loc5`='發生了什麼事?', `MaleText_loc7`='¿Qué ocurre?', `FemaleText_loc1`='무슨 일이 일어나고 있는 거죠?', `FemaleText_loc4`='发生什么了？', `FemaleText_loc5`='發生了什麼事?', `FemaleText_loc7`='¿Qué ocurre?' WHERE `ID`=41765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕의 가호가 함께하기를...', `MaleText_loc4`='黑暗女王在注视着你……', `MaleText_loc5`='黑暗女王眷顧著你...', `MaleText_loc7`='La Dama Oscura cuida de ti...' WHERE `ID`=41766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일들이 계속 일어나는데 어떻게 여관을 계속 깨끗하게 유지하겠어? 당신이 소인족 문제를 해결해주면 어떨까?', `MaleText_loc4`='在这种情况下要我怎么保持旅店的清洁？你会负责处理这俾格米的麻烦吗？', `MaleText_loc5`='發生這種事情你是要我怎樣把旅店保持乾淨?你到底要不要解決這個俾格米的問題?', `MaleText_loc7`='¿Cómo puedo mantener la posada limpia con todo lo que está ocurriendo? ¿Vas a encargarte del problema de los pigmeos?' WHERE `ID`=41767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 좀비라니?! 다음은 뭐야... 화산이 폭발한다고?', `MaleText_loc4`='地精僵尸？！接下来是什么……火山喷发？', `MaleText_loc5`='哥布林殭屍?!再來是什麼...火山爆發?', `MaleText_loc7`='¡¿Goblins zombis?! ¿Qué vendrá después? ¿Un volcán que explote?' WHERE `ID`=41768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도가니는 방치되고 힘을 잃은 듯이 보입니다.$b$b아마도 주변에 여전사와 동화할 수 있는 곳이 있을 것입니다...', `MaleText_loc4`='坩埚看起来废弃无力。$B也许你能在附近某个地方设法让自己与女武士谐调起来……', `MaleText_loc5`='這個熔爐看起來像是被遺棄也沒有能量了。$B也許附近會有個地方可以讓你和戰鬥仕女進行調諧...', `MaleText_loc7`='El crisol parece estar abandonado y sin poder.$BQuizá haya por aquí cerca algún lugar donde puedas ponerte en sintonía con la doncella de batalla...', `FemaleText_loc1`='도가니는 방치되고 힘을 잃은 듯이 보입니다.$b$b아마도 주변에 여전사와 동화할 수 있는 곳이 있을 것입니다...', `FemaleText_loc4`='坩埚看起来废弃无力。$B也许你能在附近某个地方设法让自己与女武士谐调起来……', `FemaleText_loc5`='這個熔爐看起來像是被遺棄也沒有能量了。$B也許附近會有個地方可以讓你和戰鬥仕女進行調諧...', `FemaleText_loc7`='El crisol parece estar abandonado y sin poder.$BQuizá haya por aquí cerca algún lugar donde puedas ponerte en sintonía con la doncella de batalla...' WHERE `ID`=41769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오빠씨, 만세! 정신이 들었네! 총을 어떻게 쏘는지는 기억나? 1분만 시간을 내서 다시 싸우는 법을 배워보면 어떨까? 혹시나 해서 말이야.', `FemaleText_loc4`='万岁，气泡先生！你回来了！你还记得怎么开枪吗？为什么不花上几分钟来温习战斗的技巧呢！以防万一也好。', `FemaleText_loc5`='萬歲，老爹!你回來了!你還記得要怎樣開槍嗎?要不要花點時間重學一次怎樣打架!以防萬一。', `FemaleText_loc7`='¡Hurra, Sr. D! ¡Has vuelto! ¿Recuerdas cómo disparar todas tus armas? ¿Por qué no te tomas unos minutos para recordar cómo se lucha? Por si acaso.' WHERE `ID`=41770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오빠씨, 정말 정말 조심해. 무더기로 있는 노움을 보면 자기 인력 기술을 써! 전부 끌어당긴 다음에 저승으로 보내버리라고! 알았지!', `FemaleText_loc4`='千万要多加小心，气泡先生。要是你看见大批侏儒，记得用磁性拉住他们！等把他们全都吸住，就送他们归天！耶！', `FemaleText_loc5`='要小心喔，老爹。要是你看到一大群的的地精，就要用你的魔法拉拉!等你把他們都吸過來了，就發射出去弄死他們!耶!', `FemaleText_loc7`='Ten mucho cuidado, Sr. D. ¡Si ves un grupo grande de gnomos utiliza tu atracción magnética! ¡Una vez los hayas succionado a todos, lánzalos a su muerte! ¡SÍ!' WHERE `ID`=41771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오빠씨, 저놈들 잡아!', `FemaleText_loc4`='抓住他们，气泡先生！', `FemaleText_loc5`='去解決他們，老爹!', `FemaleText_loc7`='¡A por ellos, Sr. D!' WHERE `ID`=41772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='관절을 꺾어버려!', `FemaleText_loc4`='打碎他们的骨头！', `FemaleText_loc5`='打斷他們的骨頭!', `FemaleText_loc7`='¡Rómpeles los huesos!' WHERE `ID`=41773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오빠씨를 아프게 한 만큼 쓴맛을 보여줘!', `FemaleText_loc4`='让他们后悔对你造成的伤害，气泡先生！', `FemaleText_loc5`='讓他們後悔弄傷了你，老爹!', `FemaleText_loc7`='¡Haz que sientan haberte hecho daño, Sr. D!' WHERE `ID`=41774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야호!', `FemaleText_loc4`='吖！', `FemaleText_loc5`='耶!', `FemaleText_loc7`='¡SÍ!' WHERE `ID`=41775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 더 아프게 해 줘! 더 아프게!', `FemaleText_loc4`='让他们更痛苦！更痛苦！', `FemaleText_loc5`='再給他們點教訓!再多點教訓!', `FemaleText_loc7`='¡Hazles más daño! ¡MÁS!' WHERE `ID`=41776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스, 나빠! 못 됐어!', `FemaleText_loc4`='可恶，可恶，可恶的联盟！', `FemaleText_loc5`='壞壞，壞壞聯盟!', `FemaleText_loc7`='¡MALA, ALIANZA, MALA!' WHERE `ID`=41777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오빠씨를 도울 준비가 되었으니 타게 해 주렴, 꼬마야.', `MaleText_loc4`='我已经准备好帮助气泡先生了，孩子。让我进去。', `MaleText_loc5`='我準備好要幫助老爹了，孩子。讓我進去。', `MaleText_loc7`='Estoy listo para ayudar con el Sr. D. Déjame entrar.', `FemaleText_loc1`='오빠씨를 도울 준비가 되었으니 타게 해 주렴, 꼬마야.', `FemaleText_loc4`='我已经准备好帮助气泡先生了，孩子。让我进去。', `FemaleText_loc5`='我準備好要幫助老爹了，孩子。讓我進去。', `FemaleText_loc7`='Estoy lista para ayudar con el Sr. D. Déjame entrar.' WHERE `ID`=41778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 사원으로 돌아가게. 곧 의식이 시작될 것이네.', `FemaleText_loc4`='立刻返回圣殿。仪式马上就要开始了。', `FemaleText_loc5`='立刻返回神殿，儀式就快要開始了。', `FemaleText_loc7`='Regresa al templo inmediatamente. El ritual comenzará enseguida.' WHERE `ID`=41779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='근위병, 여군주님의 명령이네. 사원으로 돌아가게.', `FemaleText_loc4`='女士要你返回圣殿，荣誉卫兵。', `FemaleText_loc5`='榮譽守衛，女士要求你立刻返回神殿。', `FemaleText_loc7`='La Dama desea que regreses al templo, guardia de honor.' WHERE `ID`=41780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다행이군, 근위병. 사원으로 돌아가게.', `FemaleText_loc4`='你的重担已经卸除，荣誉卫兵。回圣殿去吧。', `FemaleText_loc5`='你的任務結束了，榮譽守衛。回神殿去。', `FemaleText_loc7`='Estás relevado, guardia de honor. Regresa al templo.' WHERE `ID`=41781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사원으로 돌아가게. 나는 이곳에서 나머지를 처리하겠네.', `FemaleText_loc4`='你先回圣殿。我留下收拾烂摊子。', `FemaleText_loc5`='回神殿去。這邊交給我。', `FemaleText_loc7`='Regresa al templo. Yo me encargo de esto.' WHERE `ID`=41782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주님께서 그대에게 사원으로 돌아오라는 말을 전하셨네. 지체하지 말고 돌아가게.', `FemaleText_loc4`='女士捎话来，要你返回圣殿。别耽搁了。', `FemaleText_loc5`='席拉克斯女士下令要你返回神殿，不得耽擱。', `FemaleText_loc7`='La Dama desea que regreses al templo. No te retrases.' WHERE `ID`=41783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여사제들이 곧 그대의 도움이 필요할 것이네. 여군주님께서 돌아오라고 하셨네.', `FemaleText_loc4`='祭司们很快就会需要你的帮助。女士命你返回。', `FemaleText_loc5`='祭司們即將需要你的協助。席拉克斯女士要你立刻返回。', `FemaleText_loc7`='Las sacerdotisas necesitarán tu ayuda de un momento a otro. La Dama desea que regreses.' WHERE `ID`=41784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식을 행하러 후퇴하게. 여군주님께서 기다리고 계시네.', `FemaleText_loc4`='回去参加仪式。我们的女士在等着你。', `FemaleText_loc5`='回去準備進行儀式。我們的女士正在等著。', `FemaleText_loc7`='Para el ritual debes retroceder. Nuestra Dama aguarda.' WHERE `ID`=41785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해일의 여주인께서는 사원 후방 지역에서 그대의 도움이 필요하실 것이네. 즉시 그곳으로 가보게.', `FemaleText_loc4`='潮汐女王需要你帮她守卫圣殿。立即赶回那里。', `FemaleText_loc5`='席拉克斯女士要你返回神殿協助防禦。趕緊回去那裡。', `FemaleText_loc7`='La Señora de las Mareas te necesita para defender el templo. Debes regresar inmediatamente.' WHERE `ID`=41786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 여전사님?', `FemaleText_loc4`='怎么，女武士？', `FemaleText_loc5`='戰鬥仕女，你找我?', `FemaleText_loc7`='¿Sí, doncella de batalla?' WHERE `ID`=41787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 시라케스 님께서 보내셨습니다. 의식을 행하는 데 당신이 필요합니다.', `MaleText_loc4`='希拉柯丝女士派我来找你。她需要你参加仪式。', `MaleText_loc5`='席拉克斯女士在找你。你必須去參加儀式。', `MaleText_loc7`='Lady Sira''kess me ha enviado a buscarte. Te necesitan para el ritual.', `FemaleText_loc1`='여군주 시라케스 님께서 보내셨어요. 의식을 행하는 데 당신이 필요해요.', `FemaleText_loc4`='希拉柯丝女士派我来找你。她需要你参加仪式。', `FemaleText_loc5`='席拉克斯女士在找你。你必須去參加儀式。', `FemaleText_loc7`='Lady Sira''kess me ha enviado a buscarte. Te necesitan para el ritual.' WHERE `ID`=41788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즉시 그곳으로 가겠습니다, 여전사님. 감사합니다.', `FemaleText_loc4`='我会立即前往的，女武士。谢谢你。', `FemaleText_loc5`='我會立刻趕回去，戰鬥仕女。謝謝你。', `FemaleText_loc7`='Iré inmediatamente, doncella de batalla. Gracias.' WHERE `ID`=41789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아즈샤라의 이름으로.', `FemaleText_loc4`='以艾萨拉之名。', `FemaleText_loc5`='以艾薩拉之名。', `FemaleText_loc7`='En nombre de Azshara.' WHERE `ID`=41790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바다사냥꾼은 패할 거예요.', `FemaleText_loc4`='猎潮者必败。', `FemaleText_loc5`='獵潮者必將敗亡。', `FemaleText_loc7`='El Cazamareas caerá.' WHERE `ID`=41791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 그 삼지창으로 우리 수비진을 빛내주셨으면 좋겠어요. 크발디르의 숫자가 계속해서 불어나고 있으니까요.', `FemaleText_loc4`='希望你能用你的战戢为我们的防御带来荣光。克瓦迪尔人的数量还在增长。', `FemaleText_loc5`='我希望你能夠帶著你的三叉戟來協助我們的防禦。科瓦迪爾人的數量還在增加。', `FemaleText_loc7`='Tenemos la esperanza de que te unas a nuestras defensas con tu tridente. Los Kvaldir son cada vez más numerosos.' WHERE `ID`=41792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 소식을 전하시다니 정말 명예로운 일을 하신 거예요, 여전사님.', `FemaleText_loc4`='非常感谢你为我带来这个消息，女武士。', `FemaleText_loc5`='謝謝你傳達這道訊息給我，戰鬥仕女。我倍感榮耀。', `FemaleText_loc7`='Me has hecho un honor al transmitirme este mensaje, doncella de batalla.' WHERE `ID`=41793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주 나즈자르 님의 영광을 위해.', `FemaleText_loc4`='为了她的荣耀，纳兹夏尔女士。', `FemaleText_loc5`='奉她之名，納茲賈爾女士。', `FemaleText_loc7`='Por la gracia de Lady Naz''jar.' WHERE `ID`=41794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즉시 해일의 여주인을 찾아볼게요. 소식을 전해 주셔서 감사해요, 여전사님.', `FemaleText_loc4`='我马上就去找潮汐女王。谢谢你为我带来这个消息，女武士。', `FemaleText_loc5`='我會立刻去找她回報。謝謝你幫忙傳達這則訊息，戰鬥仕女。', `FemaleText_loc7`='Iré al encuentro de la Señora de las Mareas inmediatamente. Gracias por transmitirme el mensaje, doncella de batalla.' WHERE `ID`=41795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠어요. 몰래 알려주셔서 감사해요, 여전사님.', `FemaleText_loc4`='我明白了。多谢你亲自赶来通知我，女武士。', `FemaleText_loc5`='我知道了。謝謝你親自來告訴我，戰鬥仕女。', `FemaleText_loc7`='Entiendo. Gracias por informarme personalmente doncella de batalla.' WHERE `ID`=41796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여전사님, 만나뵙게 되어 영광입니다. 의식을 진행할 시간이 되었습니까?', `MaleText_loc4`='女武士，你的出现使我倍感荣幸。现在可以开始仪式了吗？', `MaleText_loc5`='戰鬥仕女，你的現身讓我倍感榮耀。儀式要準備開始了嗎?', `MaleText_loc7`='Doncella de batalla, me honras con tu presencia. ¿Ya es el momento de que comience el ritual?' WHERE `ID`=41797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 심해소환사님. 여주인님께서 기다리십니다.', `MaleText_loc4`='是的，深渊召唤者。女王在等待。', `MaleText_loc5`='是，深淵呼喚者。女士正在等我。', `MaleText_loc7`='Sí, Clamaprofundidades. La Señora aguarda.', `FemaleText_loc1`='네, 심해소환사님. 여주인님께서 기다리세요.', `FemaleText_loc4`='是的，深渊召唤者。女王在等待。', `FemaleText_loc5`='是，深淵呼喚者。女士正在等我。', `FemaleText_loc7`='Sí, Clamaprofundidades. La Señora aguarda.' WHERE `ID`=41798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 금방 일을 끝내고 사원에서 여주인님을 뵙겠습니다. 고맙습니다, 여전사님.', `MaleText_loc4`='当然，我会立即收工，回圣殿与女王会面。谢谢你，女武士。', `MaleText_loc5`='是。我會立刻把事情辦完，回神殿去見女士。謝謝你，戰鬥仕女。', `MaleText_loc7`='Por supuesto. Terminaré cuanto antes y me reuniré con la Señora en el templo. Gracias, doncella de batalla.' WHERE `ID`=41799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부하신 대로 하겠습니다, 여전사여.', `MaleText_loc4`='如您所愿，女士。', `MaleText_loc5`='遵命，女士。', `MaleText_loc7`='Como desees, mi señora.', `FemaleText_loc1`='분부하신 대로 하겠습니다, 여전사여.', `FemaleText_loc4`='如您所愿，女士。', `FemaleText_loc5`='遵命，女士。', `FemaleText_loc7`='Como desees, mi señora.' WHERE `ID`=41800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 그렇게 하겠습니다, 여전사여.', `MaleText_loc4`='马上，女士。', `MaleText_loc5`='馬上去辦，女士。', `MaleText_loc7`='Enseguida, mi señora.', `FemaleText_loc1`='당장 그렇게 하겠습니다, 여전사여.', `FemaleText_loc4`='马上，女士。', `FemaleText_loc5`='馬上去辦，女士。', `FemaleText_loc7`='Enseguida, mi señora.' WHERE `ID`=41801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 따르겠습니다.', `MaleText_loc4`='听从命令。', `MaleText_loc5`='遵從你的命令。', `MaleText_loc7`='Como ordenes.', `FemaleText_loc1`='명령을 따르겠습니다.', `FemaleText_loc4`='听从命令。', `FemaleText_loc5`='遵從你的命令。', `FemaleText_loc7`='Como ordenes.' WHERE `ID`=41802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 그렇게 하겠습니다, 여전사여.', `MaleText_loc4`='立即执行，我的女士。', `MaleText_loc5`='立刻去辦，女士。', `MaleText_loc7`='Inmediatamente, mi señora.', `FemaleText_loc1`='즉시 그렇게 하겠습니다, 여전사여.', `FemaleText_loc4`='立即执行，我的女士。', `FemaleText_loc5`='立刻去辦，女士。', `FemaleText_loc7`='Inmediatamente, mi señora.' WHERE `ID`=41803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 여전사여.', `MaleText_loc4`='明白，女士大人。', `MaleText_loc5`='瞭解了，女士。', `MaleText_loc7`='Entendido, mi señora.', `FemaleText_loc1`='알겠습니다, 여전사여.', `FemaleText_loc4`='明白，女士大人。', `FemaleText_loc5`='瞭解了，女士。', `FemaleText_loc7`='Entendido, mi señora.' WHERE `ID`=41804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지체 없도록 하겠습니다.', `MaleText_loc4`='我即刻执行。', `MaleText_loc5`='我不會耽擱的。', `MaleText_loc7`='No me retrasaré.', `FemaleText_loc1`='지체 없도록 하겠습니다.', `FemaleText_loc4`='我即刻执行。', `FemaleText_loc5`='我不會耽擱的。', `FemaleText_loc7`='No me retrasaré.' WHERE `ID`=41805;
