UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열은 사라지고 스톰윈드는 안전하다! 이 차원문이 놈들의 두 번째 공격 수단일 것이다.$b$b서둘러 차원문으로 이동하라! 승기를 잡았을 때 공격에 박차를 가해야 한다!', `MaleText_loc4`='裂隙已经被关闭，暴风城安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！', `MaleText_loc5`='元素裂隙已經關閉，暴風城安全了!這些傳送門必定是他們後半段的攻擊行動。$B$B動作快!進入傳送門!我們必須趁勝追擊!', `MaleText_loc7`='¡Las fallas han caído y Ventormenta está a salvo! Los portales deben de ser la segunda mitad de su ataque.$B$B¡Rápido! ¡Al portal! ¡Debemos atacar ahora que llevamos ventaja!' WHERE `ID`=41813;
