UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 용병선을 타고 가는 거죠? 원래는 해적을 보자마자 해치우는 게 우리가 할 일 아닙니까?', `MaleText_loc4`='我们为什么要乘一艘雇佣兵船上战场？在过去我们早把这些海盗就地正法了。', `MaleText_loc5`='我們為什麼要乘坐傭兵海賊的船上戰場?以前我們不是一看到海盜就開打的嗎?', `MaleText_loc7`='¿Por qué vamos a la batalla en una nave mercenaria? Antes matábamos a los piratas con sólo mirarlos.' WHERE `ID`=41841;
