UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 돈을 넉넉하게 주지는 않아요... 이런 쓰레기 같은 일을 할 정도로는요!', `MaleText_loc4`='部落可没给我足够的钱来干这……破事儿！', `MaleText_loc5`='部落付我這點錢就要我做這種...鳥事!', `MaleText_loc7`='¡La Horda no me paga lo suficiente como para aguantar... esta porquería!', `FemaleText_loc1`='호드가 돈을 넉넉하게 주지는 않아요... 이런 쓰레기 같은 일을 할 정도로는요!', `FemaleText_loc4`='部落可没给我足够的钱来干这……破事儿！', `FemaleText_loc5`='部落付我這點錢就要我做這種...鳥事!', `FemaleText_loc7`='¡La Horda no me paga lo suficiente como para aguantar... esta porquería!' WHERE `ID`=41892;
