UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 질렸어요! 사방에 가득한 그 소중한 똥덩이를 지켜줄 고블린이 필요하다면 다른 데 가서 알아보세요!', `MaleText_loc4`='我受够了！找别人来守你这满是粪便的鬼地方吧！', `MaleText_loc5`='我受夠了!你找別人來看著你這充滿垃圾的寶貴基地吧!', `MaleText_loc7`='¡Se acabó! ¡Búscate a otro que vigile tu preciosa base llena de zurullos!', `FemaleText_loc1`='이제 질렸어요! 사방에 가득한 그 소중한 똥덩이를 지켜줄 고블린이 필요하다면 다른 데 가서 알아보세요!', `FemaleText_loc4`='我受够了！找别人来守你这满是粪便的鬼地方吧！', `FemaleText_loc5`='我受夠了!你找別人來看著你這充滿垃圾的寶貴基地吧!', `FemaleText_loc7`='¡Se acabó! ¡Búscate a otro que vigile tu preciosa base llena de zurullos!' WHERE `ID`=41894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 열 받거든요! 더는 못 참겠어요! 때려치우겠다고요!', `MaleText_loc4`='我快崩溃了，我再也不想忍受下去了！我退出！', `MaleText_loc5`='我他喵的很生氣已經忍無可忍!我不幹了!', `MaleText_loc7`='¡ESTOY ENFADADO QUE TE CAGAS Y NO VOY A AGUANTAR MÁS! ¡DIMITO!', `FemaleText_loc1`='진짜 열 받거든요! 더는 못 참겠어요! 때려치우겠다고요!', `FemaleText_loc4`='我快崩溃了，我再也不想忍受下去了！我退出！', `FemaleText_loc5`='我他喵的很生氣已經忍無可忍!我不幹了!', `FemaleText_loc7`='¡ESTOY ENFADADO QUE TE CAGAS Y NO VOY A AGUANTAR MÁS! ¡DIMITO!' WHERE `ID`=41895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 똥 더미를 지켜줄 멍청이나 찾아보시죠! 전 그만두니까요!', `MaleText_loc4`='找别的倒霉鬼来守你这粪山吧！我不干了！', `MaleText_loc5`='找另一個失敗者來看守你這個糞坑，我不幹了!', `MaleText_loc7`='Búscate a otro imbécil que vigile tu enorme montón de caca. ¡Yo me largo!', `FemaleText_loc1`='엄청난 똥 더미를 지켜줄 멍청이나 찾아보시죠! 전 그만두니까요!', `FemaleText_loc4`='找别的倒霉鬼来守你这粪山吧！我不干了！', `FemaleText_loc5`='找另一個失敗者來看守你這個糞坑，我不幹了!', `FemaleText_loc7`='Búscate a otro imbécil que vigile tu enorme montón de caca. ¡Yo me largo!' WHERE `ID`=41896;
