UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 음... 안녕하세요. 저는 그냥 여기서 이 조개를 조사해요. 에이! 여기엔 볼 게 없군요!', `MaleText_loc4`='啊！嗯……你好啊。我在这儿只是在检查这个壳。继续！这儿没什么好看的！', `MaleText_loc5`='啊!呃...嗨，你好。我只是在檢查這個貝殼而已。繼續吧!這什麼都沒有!', `MaleText_loc7`='¡Ah! Eeeeh... hola. Simplemente estaba examinando esta concha de aquí. ¡Venga, circulen! ¡Aquí no hay nada que ver!' WHERE `ID`=41899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오는 길에 공원에 들렀었지. 싹 불탔더군...', `MaleText_loc4`='我在来的路上经过了公园区。那儿已经什么都没了……', `MaleText_loc5`='我來的時候在花園區停了一下，那裡已經什麼都沒了...', `MaleText_loc7`='Me detuve en el distrito del parque camino aquí. No queda nada…
' WHERE `ID`=41900;
