UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 마음만 먹었더라면 도시 전체를 쓸어버렸을걸. 우린 그냥 당했을 테고.', `MaleText_loc4`='要是愿意，他原本可以毁掉整座城市。而我们根本无能为力。', `MaleText_loc5`='他想要的話，隨時都可以摧毀整座城市，我們無法阻止他。', `MaleText_loc7`='Podría haber destruido la ciudad entera. Pararlo nos era imposible.' WHERE `ID`=41902;
