UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 날아와서 공원만 불태우고 가 버렸다고.', `MaleText_loc4`='他飞进来，一把火烧光了公园，然后拍拍翅膀飞走了。', `MaleText_loc5`='他飛了過來，把花園燒光，然後又飛走了。', `MaleText_loc7`='Entro volando, quemó el parque y se fue.' WHERE `ID`=41906;
