UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투의 흉터 계곡으로 돌아가지 않으면 크롬가르 파괴전차에서 떨어집니다.', `MaleText_loc4`='要是你不马上返回战痕谷，你将被从克罗姆加攻城车上移下来。', `MaleText_loc5`='你如果不回到戰痕山谷，將會被移除於克羅姆加石毀車。', `MaleText_loc7`='Te retiraremos del demoledor Krom''gar si no regresas al Valle Marca de Guerra.' WHERE `ID`=41910;
