UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게는 음... 뜨는 문제가 있는 것 같아요.', `MaleText_loc4`='我看来遇到了……漂浮的麻烦。', `MaleText_loc5`='我似乎有些...浮起來的問題。', `MaleText_loc7`='Parece ser que tengo un... problema de flotación.' WHERE `ID`=41916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 모르겠어요. 아마 골밀도가 낮은가 봐요. 아니면 폐활량이 보통 이상이던가요. 어쩌면 점심으로 먹은 치즈 때문일지도 모르죠.$B$B어떻든간에, 이 조개껍데기는 제가 수면으로 튕겨 나가지 않는 유일한 이유랍니다.', `MaleText_loc4`='我也不确定。可能是因为我骨头太轻，或是肺活量异于常人。也许只是因为我中午吃的那块奶酪。$b$b不管怎样，要不是有这壳在，我早就像火箭一样窜出水面了。', `MaleText_loc5`='我不能跟你說啊。或許我骨骼的密度太低，或肺容量比一般人來的大。又或許是我中午吃的起士。$b$b不管怎樣，這個貝殼是唯一能讓我不會浮到水面上的工具。', `MaleText_loc7`='No sabría decirte. Quizá es que tengo poca densidad en los huesos o mi capacidad pulmonar es mayor que la media. Quizá es por todo ese queso que me comí en el almuerzo.$B$BSea como sea, esta concha es lo único que evita que salga disparado hacia la superficie.' WHERE `ID`=41917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아. 이건 집안 내력이에요. 디그송 집안에는 언제나 부력이 문제예요. 좀 그렇지요.', `MaleText_loc4`='哎，家族遗传问题。恐怕掘歌家的人总是被浮力问题困扰。', `MaleText_loc5`='是的，這是血統的問題。掘曲家族一直以來都有悲觀傾向的問題，唉。', `MaleText_loc7`='Sí, es algo familiar. Me temo que los Buenacanción siempre hemos tenido problemas de flotabilidad.' WHERE `ID`=41918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 손을 번갈아 움직여서요, 젊은이... 한 손 다음에 아픈 손, 그렇게요. 코로 바닷물이 얼마나 들어갔는지 말로는 다 못할 정도랍니다.$B$B발과 이빨만으로 장작껍질 게와 싸우는 모습을 봤어야 해요! 감동 그 자체였지요. 암요.', `MaleText_loc4`='我用手划啊划啊，$g小伙子:小姑娘;……精疲力竭地划。我都不知道究竟有多少海水直接灌进了我的鼻子。$b$b不过你应该看见我用脚和牙齿力战大螃蟹的精彩场面了！那可真是荣耀啊，真的。', `MaleText_loc5`='手抓著手，$g小子:小妞;...手抓著很痛的手。我已經算不清楚我的鼻子到底灌進了多少加侖的海水了。$b$b真可惜，你們沒看到我用腳和牙齒把那隻炎殼螃蟹打跑的樣子!可精采的咧!', `MaleText_loc7`='Poco a poco, $gmuchacho:muchacha; ... poco a poco. No sabría decirte cuántos galones de agua de mar pasaron ante mis narices.$b$b¡Sin embargo, deberías haberme visto luchar contra ese cangrejo piroconcha solo con los pies y los dientes! Algo digno de alcanzar la gloria, ya lo creo que sí.' WHERE `ID`=41919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어릴 때 생각이 나는군요... 다른 애들은 모단 호수 바닥으로 헤엄쳐 간 다음 성게나 바닷조개를 집어오곤 했죠. 오스카 형님과 저는 호숫물 위에 떠있었을 뿐이었어요. 허공에 대고 허무하게 발장구를 쳐봤지만, 친구들 있는 곳으로 내려갈 수 없었답니다.', `MaleText_loc4`='我记得当我还是个小不点儿的时候……别的男孩子都能一猛子扎到洛克莫丹湖底，拾上来各种各样的海胆和贝壳。奥斯卡和我却只能趴在湖面上，两腿乱蹬，分享不到半点儿乐趣。', `MaleText_loc5`='我記得當我還是一個小鬼...其他小朋友會游到洛克莫丹的湖底去撿海膽和貝殼。歐斯卡和我每次都浮在湖的表面，沒用地向空氣擺動著我們的雙腿，我們就是無法加入他們一起玩。', `MaleText_loc7`='Recuerdo cuando yo no era más que un chaval... los demás niños podían nadar hasta el fondo del Loch Modan para coger conchas y erizos de mar. Oskar y yo siempre nos quedábamos en la superficie, dando patadas al aire en vano, sin poder unirnos a ellos.' WHERE `ID`=41920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마치 저를 조롱하듯이 아름다운 광맥이 호수나 강 밑바닥에서 빛나는 걸 본 적이 한두 번이 아니랍니다. 광석 하나 건지지도 못하고 손에 채광용 곡괭이를 든 채, 망할 놈의 오크나 블러드 엘프가 물 밑으로 내려가 광석을 캔 다음 사라지는 모습만 하염없이 바라보며 그저 떠 있어야 했지요.', `MaleText_loc4`='我都数不清究竟有多少次，远远看见水底有金光闪闪的矿脉，透过水面折射出诱人的光芒。我却只能拿着矿锄两手空空地游走，眼睁睁地看着该死的兽人和血精灵轻而易举的潜入水底，大摇大摆的携矿而去。', `MaleText_loc5`='我甚至想不起來有多少次我看到湖底還是河底有個漂亮的礦脈，閃亮亮地在那邊嘲笑我。我手裡明明拿著採礦鎬，卻只能就這樣漂過去，眼睜睜地看著該死的獸人還是血精靈游泳到底下去，從我的眼前把礦給挖走。', `MaleText_loc7`='Ni siquiera puedo recordar las veces que he localizado una preciosa veta de minerales en el fondo de un lago o un río, reluciendo y riéndose de mí. Me veo destinado a flotar sin minerales, con mi pico en la mano, mientras un maldito orco o elfo de sangre bucea delante de mis narices y se lo lleva todo.' WHERE `ID`=41921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 바쉬르에 이런 꼴로 처박혀 있는 게 어떤 기분인지 상상도 못할 거예요! 나를 해초 조각으로 착각해서 발가락을 물어뜯거나 방어구 사이에 숨는 물고기가 몇 마리나 되는지 아세요?$b$b간지러운 것 하나만으로도 드워프는 미쳐버리고도 남을 정도란 말이라고요!', `MaleText_loc4`='你根本无法想象像这样被困在瓦丝琪尔是什么感觉！你知道有多少鱼把我当成海草，咬我的脚趾头，在我的护甲里钻来钻去吗？$b$b光是挠痒痒就能把一个矮人逼疯！', `MaleText_loc5`='你不知道像這樣被困在瓦許伊爾有多麼痛苦!你知道有多少隻魚把我誤會成海草，在那邊咬我的腳指頭，還有躲進我的盔甲縫隙裡面嗎?$b$b噢，那種搔癢的感覺真快把我給逼瘋了!', `MaleText_loc7`='¡No tienes ni idea de lo que es estar atrapado en Vashj''ir como yo! ¿Sabes cuántos peces me han confundido con un pedazo de alga y me han dado mordisquitos y se han escondido en mi armadura?$b$b¡Las cosquillas bastan para volver loco a un enano!' WHERE `ID`=41922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징징대는 얘기는 별로 듣고 싶지 않으신 게로군요. 좋아요.$b$b그냥 당신이 얼마나 행운아인지만 잊지 말아 주세요. "바다 걸음"도 있고 "위쪽이 아닌 다른 방향으로 헤엄칠 수 있는 능력"도 있으니까요.', `MaleText_loc4`='我知道你没兴趣听我抱怨这些。不要紧。$b$b但别忘了你有多幸运——“深谙水性”还能“向着一个方向游泳而不是只能往上浮”。', `MaleText_loc5`='我看得出來，你並不想聽我在這邊碎碎念。算了，無所謂。$b$b只是不要忘了你有多麼的幸運，還有一雙「海腿」和「游泳到除了上方以外的其他方向的能力」。', `MaleText_loc7`='Me doy cuenta de que no quieres oír mis quejas. Está bien.$b$bPero no olvides la suerte que tienes al contar con tus "piernas de mar" y tu "habilidad para nadar en una dirección u otra".' WHERE `ID`=41923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루걸러 한 번씩은 지진이 나고, 미친 용이 세상을 조각내고... 다음은 뭘까요?', `MaleText_loc4`='每天都在地震。一头疯狂的龙正在毁灭世界，接着是什么？', `MaleText_loc5`='天天都有地震，還有瘋狂的龍要毀滅世界。接下來還有嗎?', `MaleText_loc7`='Terremotos día por medio, un dragón loco destroza al mundo, ¿qué sigue?' WHERE `ID`=41924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없는 생각은 그만두게.', `MaleText_loc4`='别胡思乱想，新兵。', `MaleText_loc5`='把你的胡思亂想拋開，新兵。', `MaleText_loc7`='Borra esas ideas, recluta.
' WHERE `ID`=41925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십 년을 호드와 싸우면서, 이번처럼 상황이 나쁜 건 처음 보네.', `MaleText_loc4`='我跟部落打了十年的仗，还没见过比这次更糟的。', `MaleText_loc5`='我已經與部落打了十年的仗了，從來沒看過比這還慘的。', `MaleText_loc7`='He luchado contra la Horda durante diez años y nunca la vi tan mal.' WHERE `ID`=41926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 눈앞에 닥친 전투에만 집중하게. 살아야 걱정도 하는 거지.', `MaleText_loc4`='专注于眼前的这场战斗，不然你怕是没命来担心了。', `MaleText_loc5`='我們必須專心面對眼前的這場仗，不然你會連怎麼死的都不知道。', `MaleText_loc7`='Concéntrate en la batalla que se avecina o no vivirás para la prueba.' WHERE `ID`=41927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 어디에서 왔나?', `MaleText_loc4`='你从哪儿来，士兵？', `MaleText_loc5`='你從哪裡搭船來的，士兵?', `MaleText_loc7`='¿De dónde vienes, soldado?' WHERE `ID`=41928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불모의 땅에서 막 도착했지.', `MaleText_loc4`='刚刚从贫瘠之地回来。', `MaleText_loc5`='剛從貧瘠之地來的。', `MaleText_loc7`='Acabo de llegar de Los Baldíos.' WHERE `ID`=41929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아슬아슬하다고? 잘못 들은 걸세. 완전히 처절하지!', `MaleText_loc4`='危险？你肯定听错了。那地方简直是绝境！', `MaleText_loc5`='危險?你聽錯了。根本就是要命啊!', `MaleText_loc7`='¿Peliagudo? Creo que no te has enterado bien. Es una situación desesperada.' WHERE `ID`=41930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병력 절반을 파병한다는 명령을 받았을 때는 믿을 수가 없었지...', `MaleText_loc4`='我当时真不敢相信他们竟然要让我们一半人出海……', `MaleText_loc5`='我不敢相信他們竟然下命令將我們一半的人遣送出去...', `MaleText_loc7`='No podía creerlo cuando nos ordenaron a la mitad de nosotros que nos embarcáramos...' WHERE `ID`=41931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 그 격전지 말인가. 듣기론 꽤 아슬아슬하다던데.', `MaleText_loc4`='啊，战斗之痕。我听说那地方相当危险。', `MaleText_loc5`='啊，戰痕。我聽說那裡怪危險的。', `MaleText_loc7`='Aaah, la Marca de Guerra.' WHERE `ID`=41932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰린속 정말 특별하다. 쓰린속 처음으로 새로운 곳의 조그만 인간 처치하게 될 거다.$B$B쓰린속 너무 행복하다.', `MaleText_loc4`='痛肠可真了不起。痛肠是在这新地方头一个打碎弱小人类的英雄。$B$B痛肠可真高兴。', `MaleText_loc5`='污腸很特別。污腸在新的地方第一個打爛弱小的人類。$B$B污腸好高興。', `MaleText_loc7`='Goutgut especial. Goutgut aplastará a insignificantes humanos en nuevo sitio.$B$BGoutgut muy feliz.' WHERE `ID`=41933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실바나스의 승리를 위하여! 이 땅은 우리 것이 되리라.', `FemaleText_loc4`='希尔瓦娜斯的胜利！这些土地将是我们的。', `FemaleText_loc5`='希瓦娜斯的勝利!這片土地將會是我們的。', `FemaleText_loc7`='¡Victoria para Sylvanas! ¡Esta tierra será nuestra!' WHERE `ID`=41934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군을 보내지 못하면, 우리 진지는 며칠 안에 괴멸될 거야.', `MaleText_loc4`='如果没有援军，我们过不了几天就将被击溃。', `MaleText_loc5`='沒有援軍，我們的陣地不出幾天就會被擊潰。', `MaleText_loc7`='Sin refuerzos nuestras posiciones caerán en manos del enemigo en cuestión de días.' WHERE `ID`=41935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형제들에게 빛이 함께하시길. 우리한테도 함께하시고. 병력이 워낙 여기저기로 분산돼서 말이야.', `MaleText_loc4`='愿圣光与他们同在，老兄——当然也与我们同在。我们的兵力近来分得太散了。', `MaleText_loc5`='願聖光與他們同在，兄弟—也與我們同在。我們的戰力散得太開了。', `MaleText_loc7`='Que la Luz sea con ellos, hermano, y con nosotros, ya puestos. La verdad es que no somos suficientes ni por asomo.' WHERE `ID`=41936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 우리가 수백 마리의 정령을 처치하였는데, 그들은 오히려 점점 더 강해지고 있는 것 같소! 경비병들이 굳건히 버티고는 있지만, 분명히 당신의 도움이 필요할 거요. 바리안 린 국왕께서는 상업 지구에서 방어 병력을 이끌고 있고, 제이나 프라우드무어 여군주께서는 마법사 지구의 방어를 돕고 있으며, 베네딕투스 대주교님은 빛의 대성당을 단단히 지켜내고 있소.$b$b당신이 스톰윈드 어디를 가도 분명히 큰 도움이 될 거요, $n.', `MaleText_loc4`='我们已经消灭了数百个元素，$n，可他们的力量却在增强！我们的守卫还能撑住，但他们肯定需要你的帮助。瓦里安·乌瑞恩国王正亲自坐镇贸易区指挥防御，吉安娜·普罗德摩尔女士正在法师区支援，大主教本尼迪塔斯则在镇守光明大教堂。$b$b不管你要前往暴风城的哪个方向，$n，我们需要你伸出援手！', `MaleText_loc5`='我們已經摧毀了數百個元素了，$n，但它們的力量越來越強!我們的守衛正堅強地在對抗它們，但我相信他們一定會需要你的協助。瓦里安·烏瑞恩國王帶領著護衛隊在貿易區奮戰，珍娜·普勞德摩爾女士在法師區戰鬥，大主教本尼迪塔斯則保護著聖光大教堂。$b$b$n不管你到暴風城的哪裡，你的幫助都將是極為重要的。', `MaleText_loc7`='Hemos destruido cientos de elementales, $n, ¡y ahora parece que su fuerza está aumentando! Nuestros guardias se mantienen firmes en su posición, pero estoy seguro de que les vendrá bien tu ayuda. El rey Varian Wrynn está al frente de la defensa del Distrito de Mercaderes, Lady Jaina Valiente ayuda en la defensa del Barrio de los Magos y el arzobispo Benedictus se mantiene firme en la Catedral de la Luz.$b$bNo importa adónde vayas en Ventormenta, $n, siempre serás de gran ayuda.' WHERE `ID`=41937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 스톰윈드가 정령들의 공격을 받고 있습니다. 당신의 도움이 필요합니다!$b$b거의 모든 지역에서 주민들을 피난 보냈고, 린 국왕 폐하는 상업 지구, 프라우드무어 님과 대주교는 마법사 지구와 대성당 광장을 방어하고 있습니다.$b$b어디로 가도 당신이 큰 도움이 될 것입니다.', `MaleText_loc4`='$n！暴风城已陷入元素的围困，需要你的支援！$b$b我们已疏散了大部分市民。乌瑞恩国王正在守卫贸易区，吉安娜·普罗德摩尔女士与大主教本尼迪塔斯正分别镇守法师区和教堂区。$b$b不论你要去哪儿，你的帮助都是必不可少的！', `MaleText_loc5`='$n!暴風城被元素們包圍了，我們需要你的力量!$b$b城市的居民已經大多疏散完畢。瓦里安·烏瑞恩國王在貿易區戰鬥，珍娜·普勞德摩爾女士和大主教本尼迪塔斯則分別在保護法師區和教堂區。$b$b不管你去哪，你都會是個很強的助力。', `MaleText_loc7`='¡$n! ¡Ventormenta está bajo asedio de los elementales y necesita tu fuerza!$b$bHemos evacuado la mayor parte de la ciudad! El rey Wrynn se ha hecho fuerte en el Distrito de Mercaderes mientras Lady Valiente y el arzobispo defiende el Barrio de los Magos y el Distrito de la Catedral.$b$b¡Allí donde quiera que vayas, serás de gran ayuda!' WHERE `ID`=41938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들을 물리쳤습니다, $n. 하지만 그들이 이상한 차원문을 남겼군요.$b$b국왕 폐하께서는 차원문이 어디로 통하는 지 확인하시려고 직접 차원문으로 들어가셨습니다. 차원문은 상업 지구, 대성당 광장, 마법사 지구에서 발견됐습니다.$b$b저는 여기 남아서 도시를 정리하고 주민들의 귀환을 도와야 합니다. 가서 폐하를 도우십시오!', `MaleText_loc4`='我们击退了元素，$n。但它们留下了不少诡异的传送门。$b$b尽管于理不合——国王已经穿过了传送门，去探明它们通往哪里。我们已经在贸易区、教堂区和法师区都发现了传送门。$b$b我必须留下收拾残局，安排市民的返城工作。你快去帮国王！', `MaleText_loc5`='我們擊退元素了，$n。但它們留下了奇怪的傳送門。$b$b國王不聽勸告已經進入了傳送門，說要看看它們通往哪裡。報告指出貿易區，法師區和教堂區都出現了傳送門的蹤影。$b$b我必須待在這善後和疏導居民回來暴風城。去幫助國王吧!', `MaleText_loc7`='Hemos hecho retroceder a los elementales, $n. Pero han dejado tras de sí unos portales extraños.$b$bA pesar de que no era muy prudente, el Rey ha cruzado uno de ellos para descubrir adónde conducen. Se han visto portales en el Distrito de los Mercaderes, en el Distrito de la Catedral y en el Barrio de los Magos.$b$bDebo permanecer aquí para supervisar el proceso de limpieza de la ciudad y el regreso de los ciudadanos. ¡Ve y ayuda al Rey!' WHERE `ID`=41939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군, 너무나 터무니없는 주장을 하는군.', `MaleText_loc4`='你的要求可真过分，将军。', `MaleText_loc5`='你的要求太過份了，將軍。', `MaleText_loc7`='Tus afirmaciones resultan intolerables, general.' WHERE `ID`=41940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈다라 숲에서 잔뜩 겁에 질린, 젊은 드루이드밖에 나올 게 없네. 그들에게 대량 살상 무기 따위는 없어.', `MaleText_loc4`='你在萨达拉树林只会找到受惊的小德鲁伊。他们手里根本没有什么大规模杀伤性武器。', `MaleText_loc5`='在薩歐達拉樹林能找到的只有那些被嚇壞了的年輕德魯伊。他們沒有大規模的毀滅性武器。', `MaleText_loc7`='Lo único que encontrarás en la Arboleda de Thal''darah será jóvenes druidas aterrados. No tienen ningún arma de destrucción masiva.' WHERE `ID`=41941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말조심하시오, 타우렌. 그런 발언은 반역으로 간주될 수 있소.', `MaleText_loc4`='小心点儿，牛头人，你的话可以会成为背叛的证据。', `MaleText_loc5`='注意你的用詞，牛頭人，你說的可被視為背叛。', `MaleText_loc7`='Cuidado, tauren, tus palabras pueden ser interpretadas como traición.' WHERE `ID`=41942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네.', `MaleText_loc4`='是，长官。', `MaleText_loc5`='是!長官。', `MaleText_loc7`='Sí, señor.' WHERE `ID`=41943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 정찰병이 그 숲에 강력한 무기가 있다고 보고했소. 서둘러 처리하지 않으면 얼라이언스가 우리를 상대로 사용할지도 모르오.', `MaleText_loc4`='据我的眼线回报，在树林里藏着某种强大的武器。如果不加以阻止，联盟就将用它来对付我们。', `MaleText_loc5`='我的斥候通知我說那個樹林裡有一個強大的武器。若是沒人阻止聯盟的話，那麼他們將會用這把武器來對付我們。', `MaleText_loc7`='Mis exploradores me han informado de que en la arboleda se esconde un arma poderosa. Un arma que la Alianza utilizará contra nosotros si no los detenemos antes.' WHERE `ID`=41944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가, 나는 크롬가르 대군주님의 명에 따라 이곳에 왔소. 대군주님은 대족장이신 가로쉬 헬스크림 님이 직접 임명하신 분이지. 대군주님의 명에 따르든가 그렇지 않으면 고통스러운 결과를 맛볼 거요.', `MaleText_loc4`='此外，是克罗姆加大王——加尔鲁什·地狱咆哮的钦点爱将派我来的。你可以选择按他说的做，或者后果自负。', `MaleText_loc5`='還有，我代表了霸主克羅姆加，而他則是大酋長卡爾洛斯·地獄吼直接指派的。如果你不服從，就必須接受後果。', `MaleText_loc7`='Es más, estoy aquí bajo la autoridad del Señor supremo Krom''gar, que fue nombrado personalmente por nuestro Jefe de guerra, Garrosh Grito Infernal. Obedecerás sus órdenes o sufrirás las consecuencias.' WHERE `ID`=41945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증거를 보여주려고 우리 아들을 탈다라 숲으로 보냈네. 그곳에 있는 자들이 우리에게 아무런 위협이 되지 않음을 곧 깨달을 걸세.', `MaleText_loc4`='我已经派人去萨达拉树林找你所谓的证据了。你很快就会发现，那里的人根本不会对我们构成任何威胁。', `MaleText_loc5`='我已經派人去薩歐達拉樹林拿證據給你了。你很快就會見到，他們根本對我們不構成威脅。', `MaleText_loc7`='He enviado a mi muchacho a la Arboleda de Thal''darah para conseguirte pruebas. Pronto podrás ver que no suponen ninguna amenaza para nosotros.' WHERE `ID`=41946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왈!', `MaleText_loc4`='嗷！', `MaleText_loc5`='啊啊!', `MaleText_loc7`='¡Guau!' WHERE `ID`=41947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고마워하는 것 같습니다.', `MaleText_loc4`='%s看上去充满感激。', `MaleText_loc5`='%s看起來很感激。', `MaleText_loc7`='%s parece apreciativo.' WHERE `ID`=41948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아이를 찾기 전까진 아무 데도 가지 않을 거예요!', `MaleText_loc4`='不找到她，我就哪儿都不去！', `MaleText_loc5`='在找到她之前我哪裡都不去!', `MaleText_loc7`='¡No voy a ir ninguna parte hasta que la encuentre!' WHERE `ID`=41949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서도 어렴풋이 보이는 것 같군... 저기 수평선 너머에 말이야.', `MaleText_loc4`='我想我从这儿刚刚能看到它。就在海平线那儿。', `MaleText_loc5`='我好像在這裡就看得到了，就在地平線的另一端。', `MaleText_loc7`='Creo que puedo salir justo a tiempo. En el borde mismo del horizonte.' WHERE `ID`=41950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 섬 말일세. 지진이 일어나고 나서 떠올랐지.', `MaleText_loc4`='那座新岛是在上次地震之后升出水面的。', `MaleText_loc5`='一座新島─在前次的地震所浮出來的。', `MaleText_loc7`='La nueva isla surgió a la superficie tras el último terremoto.' WHERE `ID`=41951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 저것 때문에 싸우는 거야. 적어도 이 전선에서는.', `MaleText_loc4`='在这条战线，我们将为那座岛屿而战。', `MaleText_loc5`='這是我們戰鬥的原因，至少在這個前線是這樣。', `MaleText_loc7`='Por ella peleamos... en este frente, al menos.' WHERE `ID`=41952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 이번이 세 번째라네.', `MaleText_loc4`='我这已经是第三次了。', `MaleText_loc5`='這已經是我的第三次了。', `MaleText_loc7`='Esta será mi tercera vez.' WHERE `ID`=41953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치열한 전투가 벌어지지...', `MaleText_loc4`='那可是场硬仗……', `MaleText_loc5`='我看過最艱辛的戰鬥...', `MaleText_loc7`='La lucha más dura que he visto…' WHERE `ID`=41954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 저 섬을 차지하면 스톰윈드는 끝난 거나 마찬가지야. 호드도 이 사실을 알고 있지.', `MaleText_loc4`='要是那座岛落到部落的手里，暴风城就保不住了……他们都明白。', `MaleText_loc5`='如果部落得到那座島，暴風城基本上也完蛋了...他們非常清楚。', `MaleText_loc7`='La Horda nos sacó esa isla y a Ventormenta la damos por perdida... y lo saben.' WHERE `ID`=41955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아들이... 그럴리 없어!!!! 도대체 왜!???', `FemaleText_loc4`='我的宝贝儿子……不！！！为什么？？！', `FemaleText_loc5`='我的孩子...不!!!!!為什麼!???', `FemaleText_loc7`='Mi niño... ¡¡¡¡NO!!! ¿¿¡¡POR QUÉ!!??' WHERE `ID`=41956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마샤, 막사로 가서 몸을 숨기게.', `MaleText_loc4`='玛莎，快到我们帐篷那边去躲起来。', `MaleText_loc5`='瑪莎，到我們的帳篷裡躲起來。', `MaleText_loc7`='Masha, ve a tu tienda y escóndete.', `FemaleText_loc1`='마샤, 막사로 가서 몸을 숨기세요.', `FemaleText_loc4`='玛莎，快到我们帐篷那边去躲起来。', `FemaleText_loc5`='瑪莎，到我們的帳篷裡躲起來。', `FemaleText_loc7`='Masha, ve a tu tienda y escóndete.' WHERE `ID`=41957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 곁을 떠나지 않겠어요! 저도 여사냥꾼임을 잊지 마세요!', `MaleText_loc4`='我不会离开你！别忘了，我可是家族中的女猎手！', `MaleText_loc5`='我不會離開你!別忘了我是這個家的女獵人!', `MaleText_loc7`='¡No te abandonaré! ¡No olvides que yo soy el cazador en esta familia!', `FemaleText_loc1`='그대 곁을 떠나지 않겠어요! 저도 여사냥꾼임을 잊지 마세요!', `FemaleText_loc4`='我不会离开你！别忘了，我可是家族中的女猎手！', `FemaleText_loc5`='我不會離開你!別忘了我是這個家的女獵人!', `FemaleText_loc7`='¡No te abandonaré! ¡No olvides que yo soy la cazadora en esta familia!' WHERE `ID`=41958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s 叹了口气。', `MaleText_loc5`='%s嘆了氣。', `MaleText_loc7`='%s suspira.', `FemaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `FemaleText_loc4`='%s 叹了口气。', `FemaleText_loc5`='%s嘆了氣。', `FemaleText_loc7`='%s suspira.' WHERE `ID`=41959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마샤, 후...', `MaleText_loc4`='噢，玛莎……', `MaleText_loc5`='唉，瑪莎...', `MaleText_loc7`='Oh, Masha...', `FemaleText_loc1`='마샤, 후...', `FemaleText_loc4`='噢，玛莎……', `FemaleText_loc5`='唉，瑪莎...', `FemaleText_loc7`='Oh, Masha...' WHERE `ID`=41960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만들 해라.', `MaleText_loc4`='够了，士兵。', `MaleText_loc5`='夠了，士兵。', `MaleText_loc7`='Basta, soldado.' WHERE `ID`=41961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드는 건재하다. 우리는 그 무엇도 호드 손에 넘겨주지 않는다!', `MaleText_loc4`='暴风城还没失守，我们不会让部落占到半点儿便宜！', `MaleText_loc5`='暴風城不會屈服，我們不會讓部落獲得任何東西!', `MaleText_loc7`='Ventormenta aún sigue en pie ¡y no vamos a permitir que la Horda nos arrebate nada!' WHERE `ID`=41962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군! 막사에서 나와 얼굴을 보여라!', `MaleText_loc4`='将军！从你的帐篷里出来面对我吧！', `MaleText_loc5`='將軍!從你的帳篷走出來面對我!', `MaleText_loc7`='¡GENERAL! ¡Sal de tu tienda y enfréntate a mí!', `FemaleText_loc1`='장군! 막사에서 나와 얼굴을 보여라!', `FemaleText_loc4`='将军！从你的帐篷里出来面对我吧！', `FemaleText_loc5`='將軍!從你的帳篷走出來面對我!', `FemaleText_loc7`='¡GENERAL! ¡Sal de tu tienda y enfréntate a mí!' WHERE `ID`=41963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 똑바로 차려라! 잠시 후면 오크와 싸울 테니.', `MaleText_loc4`='集中精神！很快就要和兽人交手了。', `MaleText_loc5`='別胡思亂想了!我們很快就會開始殺獸人了。', `MaleText_loc7`='¡Compóngase! En una hora estaremos matando orcos.' WHERE `ID`=41964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확히 뭐 말씀이십니까?', `MaleText_loc4`='到底要打什么？', `MaleText_loc5`='那裡...有什麼?', `MaleText_loc7`='¿Comprender qué, exactamente?' WHERE `ID`=41965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 가 보셨나요?', `MaleText_loc4`='你去过那里对吗？', `MaleText_loc5`='你有到過那裡嗎?', `MaleText_loc7`='¿Han estado allí?' WHERE `ID`=41966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 저도 알 것 같습니다.', `MaleText_loc4`='是的，我……我想我也能看到它。', `MaleText_loc5`='對呀，我...我想我也能看到。', `MaleText_loc7`='Sí, yo... Creo que también lo veo.' WHERE `ID`=41967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하고 늙어빠진 타우렌 주제에 감히 그런 식으로 무례하게 나오다니?!', `MaleText_loc4`='愚蠢的老牛头人，你竟敢如此目空一切？！', `MaleText_loc5`='愚蠢的老牛頭人，你敢用這種不尊敬的態度?!', `MaleText_loc7`='Tauren idiota y senil, ¡¿te atreves a mostrarme tan poco respeto?!', `FemaleText_loc1`='멍청하고 늙어빠진 타우렌 주제에 감히 그런 식으로 무례하게 나오다니?!', `FemaleText_loc4`='愚蠢的老牛头人，你竟敢如此目空一切？！', `FemaleText_loc5`='愚蠢的老牛頭人，你敢用這種不尊敬的態度?!', `FemaleText_loc7`='Tauren idiota y senil, ¡¿te atreves a mostrarme tan poco respeto?!' WHERE `ID`=41968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러는 의도가 뭐지?', `MaleText_loc4`='究竟为什么要打断我？', `MaleText_loc5`='這是怎麼回事?誰在打擾我?', `MaleText_loc7`='¿Qué significa esta interrupción?', `FemaleText_loc1`='이러는 의도가 뭐지?', `FemaleText_loc4`='究竟为什么要打断我？', `FemaleText_loc5`='這是怎麼回事?誰在打擾我?', `FemaleText_loc7`='¿Qué significa esta interrupción?' WHERE `ID`=41969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 잃어버렸나, 장군?', `MaleText_loc4`='这是你掉的吗，将军？', `MaleText_loc5`='這是你掉的嗎?將軍?', `MaleText_loc7`='¿Acaso ha perdido esto, general?', `FemaleText_loc1`='이걸 잃어버렸나, 장군?', `FemaleText_loc4`='这是你掉的吗，将军？', `FemaleText_loc5`='這是你掉的嗎?將軍?', `FemaleText_loc7`='¿Acaso ha perdido esto, general?' WHERE `ID`=41970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 계급장! 그렇다. 잃어버렸지. 어디서 났나, 타우렌?', `MaleText_loc4`='我的徽章！是，是我丢的。你在哪里找到的，牛头人？', `MaleText_loc5`='我的徽記!沒錯，是我掉的。你在哪找到它的，牛頭人?', `MaleText_loc7`='¡Mi insignia! Sí. Es mía. ¿Dónde la has encontrado, tauren?', `FemaleText_loc1`='내 계급장! 그렇다. 잃어버렸지. 어디서 났나, 타우렌?', `FemaleText_loc4`='我的徽章！是，是我丢的。你在哪里找到的，牛头人？', `FemaleText_loc5`='我的徽記!沒錯，是我掉的。你在哪找到它的，牛頭人?', `FemaleText_loc7`='¡Mi insignia! Sí. Es mía. ¿Dónde la has encontrado, tauren?' WHERE `ID`=41971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 찾아왔다.', `MaleText_loc4`='是$n找到的。', `MaleText_loc5`='是$n找到的。', `MaleText_loc7`='$n la encontró.', `FemaleText_loc1`='$n|1이;가; 찾아왔다.', `FemaleText_loc4`='是$n找到的。', `FemaleText_loc5`='是$n找到的。', `FemaleText_loc7`='$n la encontró.' WHERE `ID`=41972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 외아들의 시체에서 말이다. 더러운 돼지 새끼 같은 자식.', `MaleText_loc4`='在我唯一孩子的尸体上，你这蠢货。', `MaleText_loc5`='以我獨子的屍體起誓，你這隻該死的豬雜種。', `MaleText_loc7`='Sobre el cadáver de mi hijo, miserable hijo de un puerco.', `FemaleText_loc1`='우리 외아들의 시체에서 말이다. 더러운 돼지 새끼 같은 자식.', `FemaleText_loc4`='在我唯一孩子的尸体上，你这白痴。', `FemaleText_loc5`='以我獨子的屍體起誓，你這隻該死的豬雜種。', `FemaleText_loc7`='Sobre el cadáver de mi hijo, miserable hijo de un puerco.' WHERE `ID`=41973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s大笑。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.', `FemaleText_loc1`='%s|1이;가; 웃습니다.', `FemaleText_loc4`='%s大笑。', `FemaleText_loc5`='%s大笑。', `FemaleText_loc7`='%s ríe.' WHERE `ID`=41974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 아들놈은 약해빠졌더군. 줏대도 없고. 꼭 그 아비처럼 말이지.', `MaleText_loc4`='你的儿子无能又懦弱。真是有其父必有其子。', `MaleText_loc5`='你的孩子太弱了。沒骨氣。就跟他老子一樣。', `MaleText_loc7`='Tu hijo era débil. Sin carácter. Igual que su padre.', `FemaleText_loc1`='네 아들놈은 약해빠졌더군. 줏대도 없고. 꼭 그 아비처럼 말이지.', `FemaleText_loc4`='你的儿子无能又懦弱。真是有其父必有其子。', `FemaleText_loc5`='你的孩子太弱了。沒骨氣。就跟他老子一樣。', `FemaleText_loc7`='Tu hijo era débil. Sin carácter. Igual que su padre.' WHERE `ID`=41975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 자네 $n, 실망스럽군. 호드의 수치야!', `MaleText_loc4`='至于你——$n，可真令人失望。你简直是部落的耻辱！', `MaleText_loc5`='至於你，$n，太令人失望了。你是部落之恥!', `MaleText_loc7`='En cuanto a ti, $n, me decepcionas. ¡Eres la vergüenza de la Horda!', `FemaleText_loc1`='그리고 자네 $n, 실망스럽군. 호드의 수치야!', `FemaleText_loc4`='至于你——$n，可真令人失望。你简直是部落的耻辱！', `FemaleText_loc5`='至於你，$n，太令人失望了。你是部落之恥!', `FemaleText_loc7`='En cuanto a ti, $n, me decepcionas. ¡Eres la vergüenza de la Horda!' WHERE `ID`=41976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 모두를 죽음으로써 처벌하겠다!', `MaleText_loc4`='你们所有人应受的惩罚，就是死！', `MaleText_loc5`='給你們所有人的懲罰就是死亡!', `MaleText_loc7`='¡El castigo para todos ustedes es la MUERTE!', `FemaleText_loc1`='너희 모두를 죽음으로써 처벌하겠다!', `FemaleText_loc4`='你们所有人应受的惩罚，就是死！', `FemaleText_loc5`='給你們所有人的懲罰就是死亡!', `FemaleText_loc7`='¡El castigo para todos ustedes es la MUERTE!' WHERE `ID`=41977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아들을 대신해서 하는 거다!', `MaleText_loc4`='那是为我儿子！', `MaleText_loc5`='這是代替我兒子!', `MaleText_loc7`='¡Eso es por mi hijo!', `FemaleText_loc1`='우리 아들을 대신해서 하는 거다!', `FemaleText_loc4`='那是为我儿子！', `FemaleText_loc5`='這是代替我兒子!', `FemaleText_loc7`='¡Eso es por mi hijo!' WHERE `ID`=41978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마샤, 서둘러야겠네. 여기서 멀리 떠나야 해. 저들이 우리를 잡으러 올 테니.', `MaleText_loc4`='玛莎，我们必须逃走。逃得远远的。他们会来找我们的。', `MaleText_loc5`='瑪莎，我們必須逃跑。我們必須遠離這裡。他們就要來抓我們了。', `MaleText_loc7`='Masha, debemos huir. Debemos alejarnos de aquí rápidamente. Vendrán por nosotros.', `FemaleText_loc1`='마샤, 서둘러야겠네. 여기서 멀리 떠나야 해. 저들이 우리를 잡으러 올 테니.', `FemaleText_loc4`='玛莎，我们必须逃走。逃得远远的。他们会来找我们的。', `FemaleText_loc5`='瑪莎，我們必須逃跑。我們必須遠離這裡。他們就要來抓我們了。', `FemaleText_loc7`='Masha, debemos huir. Debemos alejarnos de aquí rápidamente. Vendrán por nosotros.' WHERE `ID`=41979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대를 찾아주어 고마워요.', `MaleText_loc4`='谢谢你为我带回了狼。', `MaleText_loc5`='感謝你將狼帶了回來。', `MaleText_loc7`='Gracias por volver, lobo.' WHERE `ID`=41980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위하여!', `MaleText_loc4`='为了联盟！', `MaleText_loc5`='為了聯盟!', `MaleText_loc7`='¡Por la Alianza!', `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=41981;
