UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라! 곧 우리가 탈 배가 올 것이다.', `MaleText_loc4`='听好了！运输船随时都会抵达。', `MaleText_loc5`='聽好!我們的船應該很快就會到了。', `MaleText_loc7`='¡Escuchen! Nuestro transporte llegará pronto.' WHERE `ID`=41983;
