UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 제군들... Task 37066이 완료되면 배는 ''곧바로'' 도착할 것이다. 그동안 함께 춤이나 추며 시간을 보내자...', `MaleText_loc4`='好吧，兄弟们……等37066号任务一执行，船就会“即刻”抵达。在此期间，我邀请你们一起来跳段小舞消磨时光……', `MaleText_loc5`='好，大家聽好...一旦計畫37066啟動，船將會「瞬間」到達這裡。至於現在呢，讓我邀請你跳支舞來消磨時間...', `MaleText_loc7`='De acuerdo, camaradas... Una vez la tarea 37066 esté implementada, el barco llegará en nada. Mientras tanto, os invito a que os unáis a nosotros en una pequeña danza para matar el tiempo...' WHERE `ID`=41985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부끄러워할 거 없다, 모두 친구 아닌가...', `MaleText_loc4`='别不好意思了，这里都是自己人……', `MaleText_loc5`='別害羞，我們這邊全都是朋友...', `MaleText_loc7`='Venga, no seáis tímidos, aquí todos nos conocemos...' WHERE `ID`=41986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 제군들! 이동!', `MaleText_loc4`='好，兄弟们！出发！', `MaleText_loc5`='好了，兄弟們!出發!', `MaleText_loc7`='¡Bien, señores! ¡Salgan!' WHERE `ID`=41987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 승리를 부릅니다...', `MaleText_loc4`='我们是胜利使者……', `MaleText_loc5`='我們帶來勝利...', `MaleText_loc7`='Saldremos victoriosos...', `FemaleText_loc1`='우리는 승리를 불러요...', `FemaleText_loc4`='我们是胜利使者……', `FemaleText_loc5`='我們帶來勝利...', `FemaleText_loc7`='Saldremos victoriosos...' WHERE `ID`=41988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가소롭도다, 무력한 $n|1이여;여;. 하지만 부름에 답해 주지. 이제, 저 아래 계신 우리 주인께 돌아가게 해다오!', `MaleText_loc4`='我嘲笑你，没用的$n，但我会照做。现在我们该回下面找我的主人了！', `MaleText_loc5`='我嘲笑你，沒用的$n。但我還是來了。現在，讓我們一起回去我主人那裡。在下面!', `MaleText_loc7`='Me río de ti, débil $n, pero accedo. Ahora, ¡regresemos con mi señor, abajo!' WHERE `ID`=41989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 이 비커와 연금술 도구를 사용하여 다양한 잠수함 연료를 실험하고 있습니다.', `MaleText_loc4`='有人正在用这些烧杯和炼金工具进行各种潜水艇燃料的实验。', `MaleText_loc5`='有人用這些燒杯和鍊金術工具在試驗各種不同的潛水艇燃料。', `MaleText_loc7`='Alguien está utilizando estos vasos de precipitado y las herramientas de alquimia para realizar experimentos con varios tipos de combustible submarino.', `FemaleText_loc1`='누군가 이 비커와 연금술 도구를 사용하여 다양한 잠수함 연료를 실험하고 있습니다.', `FemaleText_loc4`='有人正在用这些烧杯和炼金工具进行各种潜水艇燃料的实验。', `FemaleText_loc5`='有人用這些燒杯和鍊金術工具在試驗各種不同的潛水艇燃料。', `FemaleText_loc7`='Alguien está utilizando estos vasos de precipitado y las herramientas de alquimia para realizar experimentos con varios tipos de combustible submarino.' WHERE `ID`=41990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오크들은 인간이 이곳에 만든 야영지에서 죄수나 노예로 잡혀 살았었지. 나 역시 이 감옥에 갇힌 채, 우리에 갇히고 교수대에 매달린 내 형제들의 모습을 보곤 했었네,$b$b우리 모두의 지도자였던 오그림 둠해머가 등에 칼이 꽂힌 채 쓰러진 모습도 보았지. 그가 흘린 피가 우리가 서 있는 이 땅을 검붉게 물들였었다네.$b$b이제 지금 우리의 모습을 보게. 이곳, 망치 주둔지는 우리의 유산일세. 한 때 모든 것을 잃었었지만, 우리 두 손으로 되찾아온 바로 그곳이라네.', `MaleText_loc4`='我们的人民被人类当作囚犯、当作奴隶，就关在这座营地里。我被锁在这些笼子里面；我看到我的兄弟们被关在这儿，吊在这些绞架上。$B$B我看见我们所有人的领袖——奥格瑞姆·毁灭之锤，被利刃刺穿背部。他的血把我们脚下的土地都染成了深色。$B$B现在再看看我们。落锤镇——我们世代的家园，我们在这里失去了一切，然后再用我们自己的双手夺回来。', `MaleText_loc5`='我們的同胞曾在這個營區被人類當成囚犯和奴隸般對待。我曾經被鎖在這些籠子裡，看到兄弟們像家畜一樣被囚禁和送上斷頭台。$B$B我看到了奧格林·末日錘，我們的領袖，被人從背後偷襲。他的鮮血將支撐我們的大地染成了黑色。$B$B現在呢?看看我們!這是我們的傳奇!我們失去一切的地方，被我們用自己的力量給奪了回來。', `MaleText_loc7`='Nuestro pueblo era prisionero, esclavo, en este campamento de humanos. Estuve encerrado en esas jaulas; vi a mis hermanos aprisionados en esos cepos o colgando de esas horcas.$B$BVi cómo apuñalaban a Orgrimm Martillo Maldito, nuestro líder, por la espalda.$B$BY miradnos ahora. Este es nuestro legado: Sentencia, el lugar donde lo perdimos todo y los volvimos a recuperar con nuestras propias manos.' WHERE `ID`=41991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈 비커 옆에 기름 표본 몇 개가 놓여 있습니다. 비커를 보니 표본 다섯 종을 담을 수 있을 듯합니다.$B$B어떤 기름을 먼저 넣겠습니까?', `MaleText_loc4`='你面前放着几种油料样本，旁边还有一个空烧杯。烧杯看起来能装下大约五种样本。$b$b你想先选哪种油料？', `MaleText_loc5`='你的面前有幾個少量的油料樣本，還有一個空的燒杯。這個燒杯大概裝得下五份樣本。$b$b你要先加哪種油進去?', `MaleText_loc7`='Tienes ante ti varias pequeñas muestras de aceite, junto con un vaso de precipitados vacío. En el vaso puedes verter cinco muestras.$b$b¿Qué tipo de aceite verterás primero?', `FemaleText_loc1`='빈 비커 옆에 기름 표본 몇 개가 놓여 있습니다. 비커를 보니 표본 다섯 종을 담을 수 있을 듯합니다.$B$B어떤 기름을 먼저 넣겠습니까?', `FemaleText_loc4`='你面前放着几种油料样本，旁边还有一个空烧杯。烧杯看起来能装下大约五种样本。$b$b你想先选哪种油料？', `FemaleText_loc5`='你的面前有幾個少量的油料樣本，還有一個空的燒杯。這個燒杯大概裝得下五份樣本。$b$b你要先加哪種油進去?', `FemaleText_loc7`='Tienes ante ti varias pequeñas muestras de aceite, junto con un vaso de precipitados vacío. En el vaso puedes verter cinco muestras.$b$b¿Qué tipo de aceite verterás primero?' WHERE `ID`=41992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음으로 어떤 기름을 선택하겠습니까?', `MaleText_loc4`='你接下来想要选哪种油料？', `MaleText_loc5`='你接下來會加哪種油進去?', `MaleText_loc7`='¿Qué tipo de aceite elegirás a continuación?', `FemaleText_loc1`='다음으로 어떤 기름을 선택하겠습니까?', `FemaleText_loc4`='你接下来想要选哪种油料？', `FemaleText_loc5`='你接下來會加哪種油進去?', `FemaleText_loc7`='¿Qué tipo de aceite elegirás a continuación?' WHERE `ID`=41993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 기름 표본 두 가지를 넣었습니다. 다음은 어떤 표본을 선택하겠습니까?', `MaleText_loc4`='你现在有两份油料样本了。接下来想要选哪种？', `MaleText_loc5`='你現在有兩種作為樣本的油。你接下來會選擇哪個?', `MaleText_loc7`='Ahora tienes dos muestras de aceite. ¿Qué muestra elegirás a continuación?', `FemaleText_loc1`='이제 기름 표본 두 가지를 넣었습니다. 다음은 어떤 표본을 선택하겠습니까?', `FemaleText_loc4`='你现在有两份油料样本了。接下来想要选哪种？', `FemaleText_loc5`='你現在有兩種作為樣本的油。你接下來會選擇哪個?', `FemaleText_loc7`='Ahora tienes dos muestras de aceite. ¿Qué muestra elegirás a continuación?' WHERE `ID`=41994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 표본 세 가지를 넣었습니다. 다음은 어떤 표본을 선택하겠습니까?', `MaleText_loc4`='你现在有三份样本了。接下来想要选哪种？', `MaleText_loc5`='你現在有三種樣本。你接下來會選擇哪個?', `MaleText_loc7`='Ahora tienes tres muestras. ¿Qué muestra elegirás a continuación?', `FemaleText_loc1`='이제 표본 세 가지를 넣었습니다. 다음은 어떤 표본을 선택하겠습니까?', `FemaleText_loc4`='你现在有三份样本了。接下来想要选哪种？', `FemaleText_loc5`='你現在有三種樣本。你接下來會選擇哪個?', `FemaleText_loc7`='Ahora tienes tres muestras. ¿Qué muestra elegirás a continuación?' WHERE `ID`=41995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표본 네 개를 넣었습니다. 이제 하나만 더 시험해볼 수 있습니다. 어느 표본을 시험하겠습니까?', `MaleText_loc4`='你现在选好四份样本了，只能再选一份。选哪种呢？', `MaleText_loc5`='你有四種樣本，但只有空間再測試一種。你會選擇哪種?', `MaleText_loc7`='Tienes cuatro muestras y solo queda sitio para probar una más. ¿Cuál será?', `FemaleText_loc1`='표본 네 개를 넣었습니다. 이제 하나만 더 시험해볼 수 있습니다. 어느 표본을 시험하겠습니까?', `FemaleText_loc4`='你现在选好四份样本了，只能再选一份。选哪种呢？', `FemaleText_loc5`='你有四種樣本，但只有空間再測試一種。你會選擇哪種?', `FemaleText_loc7`='Tienes cuatro muestras y solo queda sitio para probar una más. ¿Cuál será?' WHERE `ID`=41996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다섯 가지를 모두 선택했습니다.', `MaleText_loc4`='你已经把五份样本都选好了。', `MaleText_loc5`='你已經選擇了全部五種樣本了。', `MaleText_loc7`='Ya has elegido tus cinco muestras.', `FemaleText_loc1`='다섯 가지를 모두 선택했습니다.', `FemaleText_loc4`='你已经把五份样本都选好了。', `FemaleText_loc5`='你已經選擇了全部五種樣本了。', `FemaleText_loc7`='Ya has elegido tus cinco muestras.' WHERE `ID`=41997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북이 기름 표본', `MaleText_loc4`='龟油样本', `MaleText_loc5`='鑽紋龜油樣本', `MaleText_loc7`='Muestra de aceite de tortuga de agua dulce', `FemaleText_loc1`='거북이 기름 표본', `FemaleText_loc4`='龟油样本', `FemaleText_loc5`='鑽紋龜油樣本', `FemaleText_loc7`='Muestra de aceite de tortuga de agua dulce' WHERE `ID`=41998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨판상어 기름 표본', `MaleText_loc4`='鮣魚油样本', `MaleText_loc5`='印魚魚油樣本', `MaleText_loc7`='Muestra de aceite de rémora', `FemaleText_loc1`='빨판상어 기름 표본', `FemaleText_loc4`='鮣魚油样本', `FemaleText_loc5`='印魚魚油樣本', `FemaleText_loc7`='Muestra de aceite de rémora' WHERE `ID`=41999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀상어 기름 표본', `MaleText_loc4`='锤头鲨鱼油样本', `MaleText_loc5`='錘頭鯊魚油樣本', `MaleText_loc7`='Muestra de aceite de tiburón martillo', `FemaleText_loc1`='귀상어 기름 표본', `FemaleText_loc4`='锤头鲨鱼油样本', `FemaleText_loc5`='錘頭鯊魚油樣本', `FemaleText_loc7`='Muestra de aceite de tiburón martillo' WHERE `ID`=42000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비커와 연금술 도구를 사용하여 여러 가지 잠수함 연료를 실험할 수 있습니다.', `MaleText_loc4`='你可以用这些烧杯和炼金工具进行各种潜水艇燃料的实验。', `MaleText_loc5`='你可以用這些燒杯和鍊金工具開始你各種海底油的樣本實驗。', `MaleText_loc7`='Puedes utilizar estos vasos de precipitado y las herramientas de alquimia para realizar experimentos con varios tipos de combustible submarino.', `FemaleText_loc1`='비커와 연금술 도구를 사용하여 여러 가지 잠수함 연료를 실험할 수 있습니다.', `FemaleText_loc4`='你可以用这些烧杯和炼金工具进行各种潜水艇燃料的实验。', `FemaleText_loc5`='你可以用這些燒杯和鍊金工具開始你各種海底油的樣本實驗。', `FemaleText_loc7`='Puedes utilizar estos vasos de precipitado y las herramientas de alquimia para realizar experimentos con varios tipos de combustible submarino.' WHERE `ID`=42001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작하겠습니다!', `MaleText_loc4`='我们开始吧！', `MaleText_loc5`='我們開始吧!', `MaleText_loc7`='¡Empecemos!', `FemaleText_loc1`='시작하겠어요!', `FemaleText_loc4`='我们开始吧！', `FemaleText_loc5`='我們開始吧!', `FemaleText_loc7`='¡Empecemos!' WHERE `ID`=42002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표본을 섞어 주십시오!', `MaleText_loc4`='把样本混合在一起！', `MaleText_loc5`='把樣本混在一起攪拌!', `MaleText_loc7`='¡Mezcla las muestras!', `FemaleText_loc1`='표본을 섞어 주세요!', `FemaleText_loc4`='把样本混合在一起！', `FemaleText_loc5`='把樣本混在一起攪拌!', `FemaleText_loc7`='¡Mezcla las muestras!' WHERE `ID`=42003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음부터 다시 하고 싶습니다.', `MaleText_loc4`='我想重新开始。', `MaleText_loc5`='我想再試一次。', `MaleText_loc7`='Quiero empezar de nuevo.', `FemaleText_loc1`='처음부터 다시 하고 싶어요.', `FemaleText_loc4`='我想重新开始。', `FemaleText_loc5`='我想再試一次。', `FemaleText_loc7`='Quiero empezar de nuevo.' WHERE `ID`=42004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 내 왕실에 들이닥쳐 터무니없는 음모를 퍼뜨리려 하다니!', `FemaleText_loc4`='你竟敢闯进我的宫殿，妄图散播这阴谋论的胡话！', `FemaleText_loc5`='你竟敢闖入我的王座廳散佈這些陰謀謠言!', `FemaleText_loc7`='¡Cómo te atreves a irrumpir en mi Sala del Trono y a intentar extender esas tonterías conspiratorias!' WHERE `ID`=42005;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈과... 그 반역자 스톤브레이커가 내 아들의 왕좌를 훔쳐가게 놔둘 것 같으냐!', `FemaleText_loc4`='我不会让你和这大逆不道的指挥官碎石盗取我儿子与生俱来的权利！', `FemaleText_loc5`='我不會讓你和叛徒指揮官碎石搶走我兒子的繼承權!', `FemaleText_loc7`='¡No permitiré que tú y ese Comandante Rompepedras le robéis a mi hijo sus derechos de nacimiento!' WHERE `ID`=42006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 앞서 가는군, 모이라. 애초에 네 왕실도 아니지 않으냐.', `MaleText_loc4`='这指控可真荒诞啊，茉艾拉。首先，这就不能算是你的宫殿。', `MaleText_loc5`='真是個嚴重的指控啊，茉艾拉。這裡什麼時候變成你的王座廳了?', `MaleText_loc7`='Esa es una acusación muy seria, Moira. Para empezar, ni siquiera es tu Sala del Trono.' WHERE `ID`=42007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톤브레이커 사령관은 내가 잘 아니 그의 정직함과 충성심은 내가 보장하겠소. 우리는 그의 말에 귀 기울여야만 하오.', `MaleText_loc4`='我知道指挥官碎石和我都会为他的忠心和诚实打包票。我们必须相信他。', `MaleText_loc5`='我認識指揮官碎石，我願意為他的忠心和誠實擔保。我們必須相信他。', `MaleText_loc7`='Conozco al Comandante Rompepedras y respondo por su lealtad y su honestidad. Debemos aceptar su palabra.' WHERE `ID`=42008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 자욱한 연료 표본을 만들었습니다. 연기가 제대로 납니다!', `MaleText_loc4`='看这儿，我做成了一份巨浪燃料样本。这烟可真呛人！', `MaleText_loc5`='這裡，我做了一份翻騰的燃料樣本，還在冒煙呢!', `MaleText_loc7`='Mira, he fabricado una muestra de combustible vaporoso. ¡Echa mucho humo!', `FemaleText_loc1`='여기, 자욱한 연료 표본을 만들었어요. 연기가 제대로 나네요!', `FemaleText_loc4`='看这儿，我做成了一份巨浪燃料样本。这烟可真呛人！', `FemaleText_loc5`='這裡，我做了一份翻騰的燃料樣本，還在冒煙呢!', `FemaleText_loc7`='Mira, he fabricado una muestra de combustible vaporoso. ¡Echa mucho humo!' WHERE `ID`=42009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 원자 연료 표본을 만들었습니다. 좀 지나치게 뜨거워 보입니다.', `MaleText_loc4`='看这儿，我做成了一份原子燃料样本。它看起来有点儿过热了。', `MaleText_loc5`='這裡，我做了一份原子能燃料樣本。看起來好像有點太燙了。', `MaleText_loc7`='Mira, he fabricado una muestra de combustible atómico. ¡Parece demasiado ardiente!', `FemaleText_loc1`='여기, 원자 연료 표본을 만들었어요. 좀 지나치게 보이네요.', `FemaleText_loc4`='看这儿，我做成了一份原子燃料样本。它看起来有点儿过热了。', `FemaleText_loc5`='這裡，我做了一份原子能燃料樣本。看起來好像有點太燙了。', `FemaleText_loc7`='Mira, he fabricado una muestra de combustible atómico. ¡Parece demasiado ardiente!' WHERE `ID`=42010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 생기없는 연료 표본을 만들었습니다. 좀... 약해 보입니다.', `MaleText_loc4`='看这儿，我做成了一份贫油样本。它看上去……真不带劲儿。', `MaleText_loc5`='這裡，我做了一份稀薄的燃料樣本。它看起來...有點虛。', `MaleText_loc7`='Mira, he fabricado una muestra de combustible anémico. Es un poco... débil.', `FemaleText_loc1`='여기, 생기없는 연료 표본을 만들었어요. 좀... 약해 보이네요.', `FemaleText_loc4`='看这儿，我做成了一份贫油样本。它看上去……真不带劲儿。', `FemaleText_loc5`='這裡，我做了一份稀薄的燃料樣本。它看起來...有點虛。', `FemaleText_loc7`='Mira, he fabricado una muestra de combustible anémico. Es un poco... débil.' WHERE `ID`=42011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇 때문에 검은무쇠 부족이 무기를 들고 아이언포지에 반하는 행동을 하게 된 것이냐? 네 백성조차 제대로 다스리지 못하는 건가, 모이라?', `MaleText_loc4`='黑铁矮人有什么理由对铁炉堡兵戎相见？你连自己的人都管不住了吗，茉艾拉？', `MaleText_loc5`='是什麼讓黑鐵與鐵爐堡針鋒相對的?你連自己的人都管不好嗎，茉艾拉?', `MaleText_loc7`='¿Qué causa tienen los Hierro Negro para levantarse en armas contra Forjaz? ¿Acaso eres incapaz de controlar a tu pueblo, Moira?' WHERE `ID`=42012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 변치않는 연료 표본을 만들었습니다. 어떻습니까?', `MaleText_loc4`='看这儿，我做成了一份持久燃料样本。你觉得怎么样？', `MaleText_loc5`='這裡，我做了一份持久的燃料樣本。你覺得怎樣?', `MaleText_loc7`='Mira, he fabricado una muestra de combustible duradero. ¿Qué opinas?', `FemaleText_loc1`='여기, 변치않는 연료 표본을 만들었어요. 어떤가요?', `FemaleText_loc4`='看这儿，我做成了一份持久燃料样本。你觉得怎么样？', `FemaleText_loc5`='這裡，我做了一份持久的燃料樣本。你覺得怎樣?', `FemaleText_loc7`='Mira, he fabricado una muestra de combustible duradero. ¿Qué opinas?' WHERE `ID`=42013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 연기나는 연료 표본을 만들었습니다. 아름답죠. 그렇지 않습니까?', `MaleText_loc4`='看这儿，我做成了一份浓烟燃料样本。很漂亮，是吧？', `MaleText_loc5`='喏，我做了一份起煙的燃料樣本。漂亮吧?', `MaleText_loc7`='Mira, he fabricado una muestra de combustible humeante. Bonito, ¿verdad?', `FemaleText_loc1`='여기, 연기나는 연료 표본을 만들었어요. 아름답죠. 그렇지 않나요?', `FemaleText_loc4`='看这儿，我做成了一份浓烟燃料样本。很漂亮，是吧？', `FemaleText_loc5`='喏，我做了一份起煙的燃料樣本。漂亮吧?', `FemaleText_loc7`='Mira, he fabricado una muestra de combustible humeante. Bonito, ¿verdad?' WHERE `ID`=42014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 빠르게 타오르는 연료 표본을 만들었습니다. 이 정도면 충분하죠?', `MaleText_loc4`='看这儿，我做成了一份快速燃烧的燃料样本。达到标准了吗？', `MaleText_loc5`='嘿，我做了一份快速燃燒的燃料樣本。這夠棒了吧?', `MaleText_loc7`='Mira, he fabricado una muestra de quemado rápido. ¿Es suficientemente bueno?', `FemaleText_loc1`='여기, 빠르게 타오르는 연료 표본을 만들었어요. 이 정도면 충분하죠?', `FemaleText_loc4`='看这儿，我做成了一份快速燃烧的燃料样本。达到标准了吗？', `FemaleText_loc5`='嘿，我做了一份快速燃燒的燃料樣本。這夠棒了吧?', `FemaleText_loc7`='Mira, he fabricado una muestra de quemado rápido. ¿Es suficientemente bueno?' WHERE `ID`=42015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 장래성 있는 연료 표본을 만들었습니다. 귀상어 기름과 빨판상어 기름을 3 대 2로 넣었지요.', `MaleText_loc4`='看这儿，我做成了一份可靠的燃料样本。锤头鲨鱼油和鮣魚油的比例是三比二。', `MaleText_loc5`='這裡，我做了一份有成功希望的燃料樣本。三份錘頭鯊和兩份印魚。', `MaleText_loc7`='Mira, he fabricado una muestra prometedora. Tres partes de tiburón martillo y dos de rémora.', `FemaleText_loc1`='여기, 장래성 있는 연료 표본을 만들었습니다. 귀상어 기름과 빨판상어 기름을 3 대 2로 넣었지요.', `FemaleText_loc4`='看这儿，我做成了一份可靠的燃料样本。锤头鲨鱼油和鮣魚油的比例是三比二。', `FemaleText_loc5`='這裡，我做了一份有成功希望的燃料樣本。三份錘頭鯊和兩份印魚。', `FemaleText_loc7`='Mira, he fabricado una muestra prometedora. Tres partes de tiburón martillo y dos de rémora.' WHERE `ID`=42016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무라딘의 말도 일리가 있소. 그대의 백성을 스스로 다스리지 못한다면, 이 협탁에 그대의 자리는 없소.', `MaleText_loc4`='穆拉丁说得对。要是你连自己的人都管不好，就没资格进行这场谈判。', `MaleText_loc5`='穆拉丁說的有道理。如果你連自己的人民都管不好，你也就不需要出現在這了。', `MaleText_loc7`='Muradin tiene razón. Si no puedes gobernar a tu propio pueblo, no hay sitio para ti en esta mesa.' WHERE `ID`=42017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸헉! <콜록> 연기가 너무 많이 나잖아요! <콜록> 거북이 기름을 너무 많이 넣었나 보군요! 다시 해 보세요!', `MaleText_loc4`='呸！<咳嗽>那么多烟！<咳嗽>看来你加进了太多龟油！重来！', `MaleText_loc5`='呸! <咳嗽>煙太大了! <咳嗽>看來你好像放太多鑽紋龜油了!再試一次!', `MaleText_loc7`='¡Bah! <tos> ¡Demasiado humeante! <tos> ¡Parece que le has puesto demasiado aceite de tortuga de agua dulce! ¡Inténtalo de nuevo!' WHERE `ID`=42018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 확실히 아주 뜨겁게 타오르겠군요. 배를 날려버리고 싶어요? 다음번에는 빨판상어 기름을 좀 줄여 보세요.', `MaleText_loc4`='没错，这确实太热了。你想要把船炸了吗？下次少放点儿鮣魚油。', `MaleText_loc5`='是的，這絕對會讓溫度太高。你想把船炸了嗎?下次少加點印魚魚油。', `MaleText_loc7`='Sí, definitivamente este se quema a temperaturas demasiado altas. ¿Es que quieres hacer saltar el barco por los aires? La próxima vez reduce la cantidad de aceite de rémora.' WHERE `ID`=42019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아요. 너무 약해빠졌어요. 빨판상어 기름이 더 필요해요. 다시 해보세요!', `MaleText_loc4`='你说得对，真是一点劲儿都没有。还得加入更多的鮣魚油。重试一次！', `MaleText_loc5`='你說對了，這太弱了。需要更多的印魚。再試一次!', `MaleText_loc7`='Tienes razón, demasiado débil. Necesita más rémora. ¡Inténtalo de nuevo!' WHERE `ID`=42020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 꽤 괜찮아 보이네요... 하지만, 너무 오래 타요! 불이 단번에 꺼져야 하거든요. 다음번에는 귀상어 기름을 줄여보세요.', `MaleText_loc4`='看上去是不错……可它烧得太久了！我需要能立刻让火停掉。下次少放点儿锤头鲨鱼油。', `MaleText_loc5`='這看起來不錯...但它燒太久了!火必須馬上能被熄滅才可以。下次少加點錘頭鯊魚油。', `MaleText_loc7`='Este tiene buena pinta... ¡pero arde demasiado tiempo! Necesito poder detener el fuego al momento. Para la próxima vez reduce la cantidad de aceite de tiburón martillo.' WHERE `ID`=42021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신들 모두 내가 이런 명령을 절대로 내리지 않을 것이라는 건 알잖소! 어째서 내가 아들이 다스릴 두 부족 사이에 불화를 만들겠소?', `FemaleText_loc4`='你们都知道我决不会下这种命令！我为什么要把我儿子的遗产分一半给别人？', `FemaleText_loc5`='你們兩個心知肚明，我絕對不會下達這種命令!我為什麼要讓我兒子繼承的兩邊互相內鬥呢?', `FemaleText_loc7`='¡Los dos sabéis que yo jamás ordenaría nada semejante! ¿Por qué enfrentaría entre sí las dos mitades de la herencia de mi hijo?' WHERE `ID`=42022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 된 것 같군요... 하지만, 연기가 아직도 너무 많이 나요. 다음번에는 거북이 기름을 아예 빼요. <콜록> 연기가 너무 많이 나니까요. 다시 해 보세요!', `MaleText_loc4`='我们接近成功了……可烟还是太多了点儿。下次别放龟油。<咳嗽>太多烟了。重来！', `MaleText_loc5`='我們離成功不遠了...煙還是有點太濃了。下次不要再加鑽紋龜油了。<咳嗽>太多煙了，再試一次!', `MaleText_loc7`='Nos acercamos... Pero este sigue siendo demasiado humeante. La próxima vez no pongas nada de aceite de tortuga de agua dulce. <tos> ¡Demasiado humo! ¡Inténtalo otra vez!' WHERE `ID`=42023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이걸 만들어 냈죠? 섬광 화약처럼 타잖아요... 너무 빨리 타네요. 귀상어 기름을 더 넣으세요.', `MaleText_loc4`='你怎么做出这个的？它烧得就像闪光粉一样……太快了。再加点儿锤头鲨鱼油。', `MaleText_loc5`='你是怎麼調出這種東西的?燒得跟閃光粉一樣...太快了。多加點錘頭鯊魚油。', `MaleText_loc7`='¿Cómo te las arreglado para conseguir este? Arde como la pólvora cegadora... demasiado rápido. Añade más tiburón martillo.' WHERE `ID`=42024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이거예요! 완벽한 생물 연료! 잘하셨어요, $n 님!', `MaleText_loc4`='就是它了！完美的生物燃料！干得好，$n！', `MaleText_loc5`='這就是了!完美的生質燃料!幹得好，$n!', `MaleText_loc7`='¡Este es! ¡El biocombustible perfecto! ¡Buen trabajo, $n!' WHERE `ID`=42025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 이건 백성들을 갈라놓으려는 배신자의 짓이오. 온 힘을 다한 내 노력에도 검은무쇠 부족 중 누군가는 아직도 황혼의 망치단의 지배를 받고 있는 거요.', `FemaleText_loc4`='不，这对我们双方的人民来说都是一种背叛。尽管我拼尽了全力，一些黑铁矮人仍在暮光之锤的掌控之中。', `FemaleText_loc5`='不，這是我們雙方人民的叛徒所幹的好事。我已經盡力了，但一些黑鐵的同胞還是受到了暮光之錘的控制。', `FemaleText_loc7`='No, esto es obra de alguien que traiciona a ambos pueblos. A pesar de mis mayores esfuerzos, algunos Hierro Negro siguen bajo el yugo del Martillo Crepuscular.' WHERE `ID`=42026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 생체 연료를 발견했습니다! 기술자 헥사스크럽에게 가져가서 시험해 보십시오.', `MaleText_loc4`='你发现了一种新型生物燃料！快把它拿给工程师“洗衣桶”测试一下。', `MaleText_loc5`='你創造了一種全新的生質燃料!把這帶給工程師赫克薩克拉來進行測試。', `MaleText_loc7`='¡Has descubierto un nuevo tipo de biocombustible! Llévaselo al ingeniero Friegahexágonos para que lo pruebe.', `FemaleText_loc1`='새로운 생체 연료를 발견했습니다! 기술자 헥사스크럽에게 가져가서 시험해 보십시오.', `FemaleText_loc4`='你发现了一种新型生物燃料！快把它拿给工程师“洗衣桶”测试一下。', `FemaleText_loc5`='你創造了一種全新的生質燃料!把這帶給工程師赫克薩克拉來進行測試。', `FemaleText_loc7`='¡Has descubierto un nuevo tipo de biocombustible! Llévaselo al ingeniero Friegahexágonos para que lo pruebe.' WHERE `ID`=42027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 이교도들은 이런 공격을 조정할 누군가를 이 도시에 심어놨을 거요. 의심스러운 자가 한 명 있소. 바로 사절 슬래그해머요!', `FemaleText_loc4`='教派肯定在城里安插了人手来协同配合此次进攻。只有一个人有嫌疑——熔锤大使！', `FemaleText_loc5`='暮光一定在城市派有間諜來組織這次的攻擊。這樣的話嫌疑犯只有一人，戰錘大使!', `FemaleText_loc7`='El culto debe tener a alguien en la ciudad que les ayude a coordinar este tipo de ataques. Eso solo nos deja un sospecho, ¡el embajador Martillo de Escoria!' WHERE `ID`=42028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑똑히 보아라, 클리프워커. 전투의 영광스러운 승리가 무엇인지 말이다.', `MaleText_loc4`='看好了，峭壁行者，这场战斗即将迎来荣耀的结局。', `MaleText_loc5`='看，崖行者，看這場戰爭是如何光榮地劃下句號。', `MaleText_loc7`='Observa, Caminarrisco, cómo la batalla llega a su conclusión gloriosa.', `FemaleText_loc1`='똑똑히 보아라, 클리프워커. 전투의 영광스러운 승리가 무엇인지 말이다.', `FemaleText_loc4`='仔细看，峭壁行者，这场战斗即将迎来荣耀的结局。', `FemaleText_loc5`='看，崖行者，看這場戰爭是如何光榮地劃下句號。', `FemaleText_loc7`='Observa, Caminarrisco, cómo la batalla llega a su conclusión gloriosa.' WHERE `ID`=42029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 지금 선을 넘으려고 하고 있소, 크롬가르. 대지모신께서 그대의 영혼에 자비를 베풀길.', `MaleText_loc4`='你正要跨过一道可怕的门槛，克罗姆加。愿大地母亲宽恕你的灵魂。', `MaleText_loc5`='你即將做出天理不容的事，克羅姆加。希望大地之母會憐憫你的靈魂。', `MaleText_loc7`='Estás por cruzar un umbral terrible, Krom''gar. Que la Madre Tierra se apiade de tu alma.', `FemaleText_loc1`='그대는 지금 선을 넘으려고 하고 있소, 크롬가르. 대지모신께서 그대의 영혼에 자비를 베풀길.', `FemaleText_loc4`='你正要跨过一道可怕的门槛，克罗姆加。愿大地母亲宽恕你的灵魂。', `FemaleText_loc5`='你即將做出天理不容的事，克羅姆加。希望大地之母會憐憫你的靈魂。', `FemaleText_loc7`='Estás por cruzar un umbral terrible, Krom''gar. Que la Madre Tierra se apiade de tu alma.' WHERE `ID`=42030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 생체 연료를 발견했습니다! 피아스코 시즐그린에게 가져가서 시험해 보십시오.', `MaleText_loc4`='你发现了一种新型生物燃料！快把它拿给菲亚斯科·尖笑测试一下。', `MaleText_loc5`='你已經創造了一種新的生質燃料了!將它帶給菲亞斯戈·嘶咧來做測試。', `MaleText_loc7`='¡Has descubierto un nuevo tipo de biocombustible! Llévaselo al Hobble Girafusible para que lo pruebe.', `FemaleText_loc1`='새로운 생체 연료를 발견했습니다! 피아스코 시즐그린에게 가져가서 시험해 보십시오.', `FemaleText_loc4`='你发现了一种新型生物燃料！快把它拿给菲亚斯科·尖笑测试一下。', `FemaleText_loc5`='你已經創造了一種新的生質燃料了!將它帶給菲亞斯戈·嘶咧來做測試。', `FemaleText_loc7`='¡Has descubierto un nuevo tipo de biocombustible! Llévaselo al Hobble Girafusible para que lo pruebe.' WHERE `ID`=42031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸헉! <콜록> 연기가 너무 많이 나잖아! <콜록> 거북이 기름을 너무 많이 넣었나 보군! 다시 해 보라고!', `MaleText_loc4`='呸！<咳嗽>那么多烟！<咳嗽>看来你加进了太多龟油！重来！', `MaleText_loc5`='嘎!<咳嗽>煙實在太多了!<咳嗽>看來你放了太多鑽紋龜油了!再試一次!', `MaleText_loc7`='¡Bah! <tos> ¡Demasiado humeante! <tos> ¡Parece que le has puesto demasiado aceite de tortuga de agua dulce! ¡Inténtalo de nuevo!' WHERE `ID`=42032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 확실히 아주 뜨겁게 타오르겠군. 배를 날려버리고 싶어? 다음번에는 빨판상어 기름을 좀 줄여 봐.', `MaleText_loc4`='没错，这确实太热了。你想要把船炸了吗？下次少放点儿鮣魚油。', `MaleText_loc5`='對，這樣溫度一定會太高。你想要把船給炸了嗎?下次少加點印魚魚油。', `MaleText_loc7`='Sí, definitivamente este se quema a temperaturas demasiado altas. ¿Es que quieres hacer saltar el barco por los aires? La próxima vez reduce la cantidad de aceite de rémora.' WHERE `ID`=42033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아. 너무 약해빠졌어. 빨판상어 기름이 더 필요해. 다시 해봐!', `MaleText_loc4`='你说得对，真是一点劲儿都没有。还得加入更多的鮣魚油。重试一次！', `MaleText_loc5`='你說的沒錯，太弱了。需要更多的印魚。再試一次!', `MaleText_loc7`='Tienes razón, demasiado débil. Necesita más rémora. ¡Inténtalo de nuevo!' WHERE `ID`=42034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 꽤 괜찮아 보이네... 하지만, 너무 오래 타! 불이 단번에 꺼져야 하거든. 다음번에는 귀상어 기름을 줄여보라고.', `MaleText_loc4`='看上去是不错……可它烧得太久了！我需要能立刻让火停掉。下次少放点儿锤头鲨鱼油。', `MaleText_loc5`='看起來不錯...但燒的時間太久了!我需要馬上就把火熄滅。下次少加點錘頭鯊魚油。', `MaleText_loc7`='Este tiene buena pinta... ¡pero arde demasiado tiempo! Necesito poder detener el fuego al momento. Para la próxima vez reduce la cantidad de aceite de tiburón martillo.' WHERE `ID`=42035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 된 것 같군... 하지만, 연기가 아직도 너무 많이 나. 다음번에는 거북이 기름을 아예 빼. <콜록> 연기가 너무 많이 나니까. 다시 해 보라고!', `MaleText_loc4`='我们接近成功了……可烟还是太多了点儿。下次别放龟油。<咳嗽>太多烟了。重来！', `MaleText_loc5`='我們快成功了...但煙還是有點太多。下次別放任何的鑽紋龜油。<咳嗽>太多煙了，再試一次。', `MaleText_loc7`='Nos acercamos... Pero este sigue siendo demasiado humeante. La próxima vez no pongas nada de aceite de tortuga de agua dulce. <tos> ¡Demasiado humo! ¡Inténtalo otra vez!' WHERE `ID`=42036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이걸 만들어 냈지? 섬광 화약처럼 타잖아... 너무 빨리 타. 귀상어 기름을 더 넣으라고.', `MaleText_loc4`='你怎么做出这个的？它烧得就像闪光粉一样……太快了。再加点儿锤头鲨鱼油。', `MaleText_loc5`='你是如何做出這個的?它燒得跟閃光粉一樣...太快了!再加點錘頭鯊魚。', `MaleText_loc7`='¿Cómo te las arreglado para conseguir este? Arde como la pólvora cegadora... demasiado rápido. Añade más tiburón martillo.' WHERE `ID`=42037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이거야! 완벽한 생물 연료! 잘했어, $n!', `MaleText_loc4`='就是它了！完美的生物燃料！干得好，$n！', `MaleText_loc5`='就是這個!完美的生質燃料!幹得好，$n!', `MaleText_loc7`='¡Este es! ¡El biocombustible perfecto! ¡Buen trabajo, $n!' WHERE `ID`=42038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 검은무쇠 부족 떨거지 놈이 마침내 벌을 받다니, 속이 다 시원하군!', `MaleText_loc4`='黑铁矮人渣滓终于得到了他应得的，这太令人高兴了！', `MaleText_loc5`='看到那個黑鐵雜碎受到報應真爽!', `MaleText_loc7`='¡Me alegro de ver que esa escoria Hierro Negro recibe por fin lo que se merece!' WHERE `ID`=42039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 하십시오! 모이라 공주님께서 기분이 좋지 않으시니 방해했다가는 목이 달아날 겁니다...', `MaleText_loc4`='安静！茉艾拉现在心情很糟，要是让她听见，你的脑袋就保不住了……', `MaleText_loc5`='安靜點!茉艾拉現在的心情非常差，如果被她聽到你的聲音，她會把你的頭摘下來...', `MaleText_loc7`='¡Silencio! Moira está de muy mal humor y si te oye te arrancará la cabeza...' WHERE `ID`=42040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 아제로스의 시련의 시기입니다.', `MaleText_loc4`='这是艾泽拉斯的困难时期，$n。', `MaleText_loc5`='這是艾澤拉斯艱難的時期，$n。', `MaleText_loc7`='Estos son tiempos difíciles para Azeroth, $n.', `FemaleText_loc1`='지금은 아제로스의 시련의 시기입니다.', `FemaleText_loc4`='这是艾泽拉斯的困难时期，$n。', `FemaleText_loc5`='這是艾澤拉斯艱難的時期，$n。', `FemaleText_loc7`='Estos son tiempos difíciles para Azeroth, $n.' WHERE `ID`=42041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 감옥을 파괴할 수 있는 토템이 필요합니다!', `MaleText_loc4`='我需要图腾来打破元素囚牢！', `MaleText_loc5`='我需要一根圖騰來摧毀元素監獄!', `MaleText_loc7`='¡Necesito un tótem para quebrar las prisiones elementales!', `FemaleText_loc1`='정령 감옥을 파괴할 수 있는 토템이 필요합니다!', `FemaleText_loc4`='我需要图腾来打破元素囚牢！', `FemaleText_loc5`='我需要一根圖騰來摧毀元素監獄!', `FemaleText_loc7`='¡Necesito un tótem para quebrar las prisiones elementales!' WHERE `ID`=42042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 뭘 어떻게 하든 두려움은 없다. 저 잡종 난쟁이는 절대로 내 왕이 될 수 없어! 황혼의 망치단이여 영원하라!', `MaleText_loc4`='要怎样尽管来。我不怕。那个杂种永远别想成为我的帝王！暮光之锤万岁！', `MaleText_loc5`='你想對我做什麼隨便你，我並不害怕。那個汙血雜種永遠都不可能成為我的帝王!暮光之錘萬歲!', `MaleText_loc7`='Haz lo que quieras conmigo. No tengo miedo. ¡Ese renacuajo mestizo jamás será mi emperador! ¡Larga vida al Martillo Crepuscular!' WHERE `ID`=42043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳이 어둠의 괴철로도시였다면 그대의 범법행위를 법의 심판장에서 물었을 것이다, 대사. 이제 아이언포지의 가장 깊은 던전이 그것을 대신해 줄 것이야.', `FemaleText_loc4`='要是我们在暗炉城，我一定会把你扔进秩序竞技场的，大使先生。现在只好拿铁炉堡里最黑暗的地下城凑合一下。', `FemaleText_loc5`='大使，如果我們是在影爐城，我會因為你的背叛把你丟進秩序競技場。至於現在，可以讓鐵爐堡最深最黑暗的迷宮代替。', `FemaleText_loc7`='Si estuviéramos en Ciudad Forjatinibela, te habría arrojado al Círculo de la Ley por tus transgresiones, embajador. Por ahora tendrán que bastar con las mazmorras más oscuras de Forjaz.' WHERE `ID`=42044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 둘러보아라, 클리프워커. 호드의 위용을 똑똑히 보아라!', `MaleText_loc4`='仔细看着这一切，峭壁行者，见证部落的力量！', `MaleText_loc5`='看看這個世界吧，崖行者，目睹部落的力量!', `MaleText_loc7`='¡Contempla el mundo, Caminarrisco, y el poderío de la Horda!', `FemaleText_loc1`='세상을 둘러보아라, 클리프워커. 호드의 위용을 똑똑히 보아라!', `FemaleText_loc4`='仔细看着这一切，峭壁行者，见证部落的力量！', `FemaleText_loc5`='看看這個世界吧，崖行者，目睹部落的力量!', `FemaleText_loc7`='¡Contempla el mundo, Caminarrisco, y el poderío de la Horda!' WHERE `ID`=42045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 따라가 주지, $c 친구. 주인님의 계획에서 내가 맡은 목적은 이미 실행에 옮겼으니까 말이야.', `MaleText_loc4`='我愿意去，$c。我在主人计划中应尽的职责已经完成。', `MaleText_loc5`='非常樂意，$c。我已經完成主人計畫中我所該做的事了。', `MaleText_loc7`='Voy voluntariamente, $c. Ya he cumplido con mi papel en el plan del maestro.' WHERE `ID`=42046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을 한 거지, 크롬가르?', `MaleText_loc4`='你都干了些什么，克罗姆加？', `MaleText_loc5`='你做了什麼，克羅姆加?', `MaleText_loc7`='¿Qué has hecho, Krom''gar?' WHERE `ID`=42047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각하, 이제 새로운 거처로 안내해 드리겠습니다.', `MaleText_loc4`='我会护送你到新的“住所”，阁下。', `MaleText_loc5`='請讓我護送你到新的「住所」，閣下。', `MaleText_loc7`='Te acompañaré a tus nuevos "aposentos", excelencia.' WHERE `ID`=42048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대, 대족장님! 저, 전... 명령을 수행했을 뿐입니다!', `MaleText_loc4`='酋长！我……只是在执行你的命令！', `MaleText_loc5`='大酋長!我...我只是遵從了你的命令!', `MaleText_loc7`='¡Jefe de Guerra! Yo... ¡llevaba a cabo sus órdenes!' WHERE `ID`=42049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령이라고?', `MaleText_loc4`='我的命令？', `MaleText_loc5`='我的命令?', `MaleText_loc7`='¿Mis órdenes?' WHERE `ID`=42050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롬가르, 내가 무고한 자를 죽이라고 명령했나?', `MaleText_loc4`='我的命令是滥杀无辜吗，克罗姆加？', `MaleText_loc5`='我的命令是讓你屠殺無辜嗎，克羅姆加?', `MaleText_loc7`='¿Mis órdenes eran asesinar inocentes, Krom''gar?' WHERE `ID`=42051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암아귀를 구속하던 단 하나의 사슬이 끊어지려고 합니다!', `MaleText_loc4`='熔喉开始挣脱捆绑他的锁链了！', `MaleText_loc5`='熔喉要從栓住它的唯一一條鐵鏈中掙脫了!', `MaleText_loc7`='¡Faucemagma empieza a liberarse de la única cadena que lo mantiene atado!' WHERE `ID`=42052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님... 그, 그게... 전...', `MaleText_loc4`='酋长……大人……我……', `MaleText_loc5`='大酋長...長官...我...', `MaleText_loc7`='Jefe de Guerra... Señor... ' WHERE `ID`=42053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 살인마로 보이나?', `MaleText_loc4`='我是个杀人狂吗，克罗姆加？', `MaleText_loc5`='我是個殺人狂嗎，克羅姆加?', `MaleText_loc7`='¿Soy yo un asesino, Krom''gar?' WHERE `ID`=42054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다, 대족장님!', `MaleText_loc4`='不，酋长！', `MaleText_loc5`='不，大酋長!', `MaleText_loc7`='¡No, Jefe de Guerra!' WHERE `ID`=42055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 다시 묻겠다. 무슨 짓을 한 거냐!', `MaleText_loc4`='那么，我再问你一次，你都干了些什么！', `MaleText_loc5`='那我再問你一次:你做了什麼?', `MaleText_loc7`='Entonces, te vuelvo a preguntar: ¡¿QUÉ HAS HECHO?!' WHERE `ID`=42056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 너에게 군대를 주고 돌발톱 산맥으로 보냈다. 내가 내린 명령은 이 땅을 확보하라는 것이었지.', `MaleText_loc4`='我派你带一支军队来到石爪山。你的使命是为了部落守住这块土地。', `MaleText_loc5`='我派你帶一支軍隊到石爪山脈。你的命令是為部落保衛這片土地。', `MaleText_loc7`='Te envié a Sierra Espolón con un ejército. Tus órdenes eran rescatar esta tierra de la Horda.' WHERE `ID`=42057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 넌 이 땅을 짓밟았다. 무고한 자를, 심지어 어린아이까지 학살했어...', `MaleText_loc4`='然而，你却把它变成了废土，滥杀无辜，连孩童也不放过……', `MaleText_loc5`='但，你反而損毀了這片土地。濫殺無辜，連小孩都不放過...', `MaleText_loc7`='En cambio, arrasaste con todo. Asesinaste inocentes. Hasta niños…' WHERE `ID`=42058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 오랜 시간을 노스렌드에서 보냈다, 크롬가르. 그때 호드에 대해 많은 것을 배웠지.', `MaleText_loc4`='我在诺森德奋战了很长一段日子，克罗姆加。在那儿我学到了很多有关部落的东西。', `MaleText_loc5`='我在北裂境待了很長的一斷時間，克羅姆加。我學到了很多與部落有關的事物。', `MaleText_loc7`='Pasé mucho tiempo en Rasganorte, Krom''gar. Aprendí mucho sobre la Horda.' WHERE `ID`=42059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서, 경험 많고 지혜로운 한 용사가 평생 잊지 못할 가르침을 내게 주었다...', `MaleText_loc4`='正是在那儿，一位睿智的老英雄给我留下了终生难忘的教导……', `MaleText_loc5`='我在那的時候，一位年邁的戰爭英雄告訴了我我一輩子都不會忘記的事...', `MaleText_loc7`='Un héroe de guerra anciano, un sabio, me dijo algo que me acompañará por siempre…' WHERE `ID`=42060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무리 끔찍한 전투라도... 도의를 저버려서는 안 된다는 가르침을 말이다, 크롬가르.', `MaleText_loc4`='“荣耀”，克罗姆加，“无论战斗多么可怕……也不要忘记荣耀”。', `MaleText_loc5`='那就是「榮耀」，克羅姆加，「不管戰爭如何的險惡...永遠不要轉身而逃。」', `MaleText_loc7`='"El honor", Krom''gar, "no importa cuán terrible la batalla... nunca lo manches".' WHERE `ID`=42061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대군주 크롬가르, 너는 호드를 부끄럽게 했다.', `MaleText_loc4`='克罗姆加大王，你使部落蒙羞了。', `MaleText_loc5`='霸主克羅姆加，你丟了部落的臉。', `MaleText_loc7`='Señor supremo Krom''gar, has deshonrado a la Horda.' WHERE `ID`=42062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두의 얼굴에 먹칠을 했다.', `MaleText_loc4`='你给我们带来了耻辱。', `MaleText_loc5`='你為我們所有人帶來了恥辱。', `MaleText_loc7`='Has avergonzado a nuestra gente.' WHERE `ID`=42063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장의 권한으로, 지금 이 자리에서 네 직위를 해제한다.', `MaleText_loc4`='以部落酋长之名，我现在解除你的职务。', `MaleText_loc5`='以大酋長之名，我在此解除你的職務。', `MaleText_loc7`='Como Jefe de guerra, te relevo de tu deber.' WHERE `ID`=42064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아들었나? 썩 물러가라!', `MaleText_loc4`='你被罢免了！', `MaleText_loc5`='你可以下去了。', `MaleText_loc7`='ESTÁS DESTITUÍDO.' WHERE `ID`=42065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너!', `MaleText_loc4`='还有你，$r！', `MaleText_loc5`='還有你，$r!', `MaleText_loc7`='¡Y tú, $r!' WHERE `ID`=42066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 대족장! 기다리시오! 이자는 영웅이오. 크롬가르의 악행을 밝혀낸 장본인이란 말이오. 그를 막으려고도 했소!', `MaleText_loc4`='等等，酋长！请等等！正是$n这位英雄揭露了这场堕落。$g他:她;曾竭力阻止克罗姆加！', `MaleText_loc5`='等等，大酋長!拜託!這位是發現這次腐化的英雄。$g他:她;試著阻止克羅姆加!', `MaleText_loc7`='¡Espera, Jefe de Guerra! ¡Por favor! Este es el héroe responsable de descubrir esta corrupción. ¡Este intentó detener a Krom''gar!' WHERE `ID`=42067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 보이시오, 대족장.', `MaleText_loc4`='请宽恕他，酋长。', `MaleText_loc5`='手下留情，大酋長。', `MaleText_loc7`='Ten piedad, Jefe de Guerra.' WHERE `ID`=42068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비라고? 그대의 아내와 아이가 목숨을 잃었소. 그대의 동족이 학살당했소. 그대의 고향이 불탔소.', `MaleText_loc4`='宽恕……你的妻儿被杀，族群被灭，你的家园被烧至焦土。', `MaleText_loc5`='留情...你的老婆和孩子都被殺死了。你的族人也全死光了。你的家園被毀燒殆盡。', `MaleText_loc7`='Piedad...  Tu mujer y tus hijos fueron asesinados. Tu especie, aniquilada. Tu hogar reducido a cenizas.' WHERE `ID`=42069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비라니... 대부족장이여, 오늘 그대에게 가르침을 받는군.', `MaleText_loc4`='宽恕……族长，今日你教导了我。', `MaleText_loc5`='留情...酋長，今天我得要向你學學。', `MaleText_loc7`='Piedad...  Cabecilla, hoy aprendo de ti.' WHERE `ID`=42070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산악경비대 발리브루가 당신이 모단 호수로 가는 것을 도와줄 수 있을 것이라고 했습니다.', `MaleText_loc4`='巡山人维拉特·麦酒说你能帮我抵达洛克莫丹。', `MaleText_loc5`='巡山人維拉特·麥酒說你可以幫我前往洛克莫丹。', `MaleText_loc7`='El montaraz Cebadiz dice que puedes ayudarme a llegar a Loch Modan.', `FemaleText_loc1`='산악경비대 발리브루가 당신이 모단 호수로 가는 것을 도와줄 수 있을 것이라고 했어요.', `FemaleText_loc4`='巡山人维拉特·麦酒说你能帮我抵达洛克莫丹。', `FemaleText_loc5`='巡山人維拉特·麥酒說你可以幫我前往洛克莫丹。', `FemaleText_loc7`='El montaraz Cebadiz dice que puedes ayudarme a llegar a Loch Modan.' WHERE `ID`=42071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롬가르의 군대는 물러갔다. 네 직위엔 이제 아무 의미가 없다. 정말로 호드를 돕고 싶다면, 네 강력한 힘을 잊혀진 땅이나 남부 불모의 땅에서 쓰도록 해라.', `MaleText_loc4`='$n，克罗姆加的军队不复存在了。你的军阶不再有意义。如果真心希望帮助部落，你的能力可以在凄凉之地或者南贫瘠之地派上用场。', `MaleText_loc5`='$n，克羅姆加的部隊已不再存在。你的軍階已經不再存有任何意義。如果你真心的想幫助部落，淒涼之地和南貧瘠之地或許會需要你的力量。', `MaleText_loc7`='$n, el ejército de Krom''gar ya no existe. Tu rango ya no vale nada. Si realmente quieres ayudar a la Horda, tu poder será útil en Desolace o en los Baldíos del Sur.' WHERE `ID`=42075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택은 너의 몫이다.', `MaleText_loc4`='你自行决定吧。', `MaleText_loc5`='選擇權在於你。', `MaleText_loc7`='La elección es tuya.' WHERE `ID`=42076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예가 너를 인도하길. 헬스크림이 언제나 너를 지켜보고 있음을 잊지 마라.', `MaleText_loc4`='让荣誉指引你，$n。不要忘记，地狱咆哮一直在注视着你。', `MaleText_loc5`='讓榮耀指引你，$n。別忘了地獄吼的雙瞳將一直注視著你。', `MaleText_loc7`='Que el honor te guíe, $n. No olvides que los ojos de Grito Infernal no te abandonan.' WHERE `ID`=42077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<신음하는 퓨리엔>', `MaleText_loc4`='<弗瑞恩呻吟着。>', `MaleText_loc5`='<弗里安呻吟了起來。>', `MaleText_loc7`='<Furien gruñe.>' WHERE `ID`=42078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 저걸 놓칠 리는 없을 거요. 대포를 쏘든 말든 말이오.', `MaleText_loc4`='哈哈！他们肯定会看见这个，能不能开火都一样。', `MaleText_loc5`='哈哈!不管有沒有火砲，他們肯定不會錯過的。', `MaleText_loc7`='¡Ja, ja! ¡Haya fuego de cañones o no, eso no se les pasará por alto!' WHERE `ID`=42079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 말게. 만약 저들이 이걸 못 본 체한다면, 내가 헤엄쳐 가서 저들의 배를 끌어 오겠네.', `MaleText_loc4`='别担心——要是他们敢装没看见，我会亲自游过去把他们从船上拽来。', `MaleText_loc5`='別擔心，如果他們裝做沒看到，我會親自游過去將他們從船上拉下來。', `MaleText_loc7`='No te preocupes, si intentan hacer como que no la han visto, nadaré allí y les sacaré de sus barcos yo mismo.' WHERE `ID`=42080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수없이 많은 나가를 처리하였지만 놈들은 아직도 몰려오고 있습니다. 이 처참한 동굴에서 빠져나가려면 어찌해야 하겠습니까?', `MaleText_loc4`='我们坚持到现在已经消灭了许多纳迦，可他们还在前仆后继地冲过来。到底要怎么做才能逃出这该死的洞穴？', `MaleText_loc5`='我們殺了許多納迦才來到這，但他們還是源源不絕的出現。要怎樣才能逃出這個該死的洞窟?', `MaleText_loc7`='A estas alturas hemos matado docenas de nagas, pero siguen apareciendo más. ¿Qué más tendremos que hacer para escapar de esta maldita cueva?' WHERE `ID`=42081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 전 이 소라 안에서 죽더라도 개의치 않습니다. 놈들이 죽이거나 잡아간 우리 군대의 앙갚음을 하고 말 겁니다!$b$b다른 이들은 여기서 탈출할 궁리를 하고, 저는 저 뱀자식들에게 천벌을 내릴 궁리를 하지요.', `MaleText_loc4`='我不在乎自己是否会死在这儿，$n。我要让这些纳迦为我们每一个被杀死或奴役的同胞付出代价！$b$b就让其它人去烦恼该如何逃生吧。我要考虑的是该怎么让这些魔鬼受到惩罚。', `MaleText_loc5`='我不在乎是否會死在這裡，$n。我會讓那些殺了我的同伴和奴役了他們的納迦付出代價!$b$b其他人想著如何逃出去我不管，我想的是如何懲罰這些蛇人。', `MaleText_loc7`='No me importa si tengo que morir aquí dentro, $n. ¡Haré que esos nagas paguen por todos y cada uno de mis compañeros soldados que han matado o esclavizado!$b$bPara los demás lo importante es escapar. Para mí lo importante es castigar a esas serpientes.' WHERE `ID`=42082;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 왜 이런 일을 하는 걸까요? 진주 때문에? 싸우기 위해서? 이 고대 생물 네스피라는 나가들이 알고 있는 것보다 훨씬 더 강력한 존재예요. 만약 저들이 네스피라를 굴복시킨다면... 막강한 힘을 손에 넣게 될 거예요.', `FemaleText_loc4`='他们为什么这么做？为了珠宝？为了战争？上古之神奈瑟匹拉远比纳迦了解得要强大得多。要是奈瑟匹拉能为他们所用……那他们所能造成的伤害将达到令人发指的程度。', `FemaleText_loc5`='他們為什麼要這樣做?為了珍珠?為了戰爭?這個先祖，奈斯畢拉的力量遠比納迦想像的要來的大。如果他們可以操控奈斯畢拉...他們製造出的傷害將會非常的大。', `FemaleText_loc7`='¿Por qué hacen esto? ¿Por las perlas? ¿Por la guerra? Ese ancestro, Nespirah, es mucho más poderosa de lo que creen los nagas. Si son capaces de conseguir que ella se pliegue a lo que desean... El daño que podrían causar sería terrible.' WHERE `ID`=42083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상당한 채 여기 앉아서 형제들이 싸우는 것을 바라보기만 하는 건 견디기 힘들지만, 난 죽기보다는 살아 있는 편이 가치 있다는 걸 잘 아오.', `MaleText_loc4`='负伤坐在这儿，看着我的弟兄们奋力战斗，这感觉可真让人难以忍受，可就连我都知道，我活着的价值要比死掉大得多。', `MaleText_loc5`='受傷坐在這看到我的兄弟在戰鬥實在是難以忍受，但我清楚我活著會比死了來的有價值。', `MaleText_loc7`='No puedo soportar tener que quedarme aquí sentado, herido, mientras mis hermanos luchan. Pero incluso yo me doy cuenta de que valgo más vivo que muerto.' WHERE `ID`=42084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이곳의 분위기가 마음에 들지 않습니다, $n 님. 나가 여마법사와 노예감독들은 차치하고... 이 동굴 안에서 느껴지는 건 고통뿐이로군요. 고대 생물이 울부짖으려 하고 있지만, 목소리를 못 내고 있습니다.', `FemaleText_loc4`='我不喜欢这里的感觉，$n。到处都是纳迦巫师和奴役者……我在这洞里唯一能感受到的就是痛苦。古老的生命在试图呼喊，可我却说不出话来。', `FemaleText_loc5`='我不喜歡這個地方，$n。除了納迦巫女和奴隸驅使者以外...在這個洞穴裡我唯一的感覺就是痛苦。上古之神想要出聲咆哮，可是卻開不了口。', `FemaleText_loc7`='Este sitio me da muy mala espina, $n. Aparte de las hechiceras naga y los explotadores... lo único que percibo aquí es dolor. El ancestro está intentando gritar, pero no puede hablar.' WHERE `ID`=42085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 자네 도움이 필요하네. 우린 필사적으로 싸워 여기까지 왔지만, 나가들이 계속 몰려들고 있네.', `MaleText_loc4`='我们需要你的帮助，$c。我们已经拼尽了全力，但纳迦的攻势丝毫没有减弱。', `MaleText_loc5`='我們需要你的幫忙，$c。我們艱辛萬苦的才到了這，但納迦還是不斷出現。', `MaleText_loc7`='Necesitamos tu ayuda, $c. Hemos luchado hasta la extenuación para llegar aquí, pero siguen apareciendo más nagas.' WHERE `ID`=42086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상처가 낫질 않는군, $r 친구. 우리가 바로 행동을 개시하지 않으면 이 생물체 안에서 죽을 수도 있을 것 같아 두렵네.', `MaleText_loc4`='我的伤口还没愈合，$r。要是我们不尽快行动，恐怕我就要死在这家伙的肚子里。', `MaleText_loc5`='我的傷口沒有好轉，$r。要是我們不趕緊採取行動的話，我怕我可能會死在這怪物的肚子裡。', `MaleText_loc7`='Mis heridas no sanan, $r. Temo que moriré dentro de las tripas de esta criatura si no hacemos algo pronto.' WHERE `ID`=42087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 손에 나가의 피가 묻어 있다면, 내 맹우라 할 수 있네.$b$b아주 오래전에, 다시는 누구의 노예도 되지 않겠다고 맹세했고, 이드라케스에게 붙잡히기 전까지는 맹세를 지켰지. 이제 분노를 억누르기 어렵군. 내가 원하는 건... 음식도, 잠도 승리도 아닐세. 피를 보고 싶을 뿐이야.', `MaleText_loc4`='要是你的双手沾上了纳迦的鲜血，那你就是我的盟友。$b$b很久以前，我发誓决不再做任何人的奴隶，在那以后我一直信守对自己的承诺，直到落在埃卓凯丝的手里。现在我已经抑制不住胸中的怒火。鲜血是我唯一的渴望……我可以不吃不睡，甚至可以不要胜利……只要鲜血。', `MaleText_loc5`='只要你手上沾著納迦的鮮血，你就是我們的盟友。$b$b很久以前，我發誓過我絕對不會再變成任何人的奴隸。這個狀況為遲了好一段時間，直到艾德拉奇斯逮住了我們。現在我已經快要克制不住我的憤怒了。我只要血...不要食物、不要睡覺，甚至勝不勝利也無所謂...就只要血。', `MaleText_loc7`='Si tienes sangre naga en tus manos, entonces estás de mi parte.$b$bHace mucho tiempo, juré que no volvería a ser esclavo de nadie y he mantenido mi promesa hasta que Idra''kess nos capturó. Ahora apenas puedo contener mi furia. Todo lo que deseo es sangre... No quiero comida, ni dormir, ni siquiera la victoria... solo sangre.' WHERE `ID`=42088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으, 버드. 대체 왜 그런 짓을 한 거야...', `MaleText_loc4`='噢……巴德。你这是又要干嘛？', `MaleText_loc5`='噢，霸德。你為什麼要這麼做?', `MaleText_loc7`='Ay, Budd. ¿Por qué tenías que hacer eso?
' WHERE `ID`=42089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 민간인이란...', `MaleText_loc4`='平民…', `MaleText_loc5`='哼，死老百姓...', `MaleText_loc7`='Civiles...' WHERE `ID`=42090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 정렬!', `MaleText_loc4`='列队！', `MaleText_loc5`='排好隊!', `MaleText_loc7`='¡Formen filas!' WHERE `ID`=42091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수평선 위로 보이는 저 섬이 우리의 목적지이다.', `MaleText_loc4`='海平线上的岛就是我们的目的地！', `MaleText_loc5`='海平線上的島就是我們的目的地。', `MaleText_loc7`='Esa isla en el horizonte es nuestro destino.' WHERE `ID`=42092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 저기서 임무를 다할 것이다. 우리의 왕을 위해, 스톰윈드와 거기에 사는 모든 이를 위해...', `MaleText_loc4`='我们将在那里履行使命——为了国王，为了暴风城和她的子民们……', `MaleText_loc5`='我們會在那裡為國王履行職責，為了暴風城和她的人民...', `MaleText_loc7`='Es donde haremos nuestro deber, por nuestro rey, por Ventormenta y su gente…' WHERE `ID`=42093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 쓰러뜨리는 오크 하나하나가 스톰윈드와 쓰러진 전우들을 명예롭게 할 것이다.', `MaleText_loc4`='击败那些兽人，送他们去追求荣耀，以此告慰每一名阵亡的士兵。', `MaleText_loc5`='你今天所殺的每一個獸人都是為了他們，同時也是為了在你之前每一個士兵的榮耀。', `MaleText_loc7`='Cada orco que maten hoy los honrará a ellos y a los soldados que estuvieron aquí antes que ustedes.' WHERE `ID`=42094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림은 저 섬을 차지하려고 최정예 부대를 보냈다. 그놈들을 하나도 살려 보내선 안 된다!', `MaleText_loc4`='地狱咆哮派来了他最强的战士。我们要确保他们全都回不了家……', `MaleText_loc5`='地獄吼派出了他的精銳來搶奪這個島嶼。我們要確保他們沒有人能活著回去...', `MaleText_loc7`='Grito Infernal ha enviado a sus mejores hombres. Procuraremos que ninguno sobreviva…' WHERE `ID`=42095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 가로쉬 헬스크림은 스랄이 가르칠 수 없었던 것을 배우게 될 것이다...', `MaleText_loc4`='今天，地狱咆哮将学到萨尔没能教会他的那堂课…', `MaleText_loc5`='今天地獄吼會得到索爾沒有教會他的教訓...', `MaleText_loc7`='Le enseñaremos a Grito Infernal una lección que Thrall no pudo enseñarle…' WHERE `ID`=42096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드는 쓰러지지 않는다!', `MaleText_loc4`='暴风城永不陷落！', `MaleText_loc5`='暴風城永不會陷落!', `MaleText_loc7`='¡Ventormenta nunca caerá!' WHERE `ID`=42097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 쉼 없이 항해하는 대가로 많은 돈을 치렀다. 지체할 시간이 없어...', `MaleText_loc4`='你已经获得不菲的报酬来完成这次直达行程，小姐。我们可没时间耽搁……', `MaleText_loc5`='我們付了你很多錢讓你通行無阻，小姐。我們必須馬不停蹄...', `MaleText_loc7`='Te han pagado muy bien por transporte ilimitado, señorita. No podemos permitirnos retrasos...' WHERE `ID`=42098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 준비해라. 곧 육지에 닿을 것이다.', `MaleText_loc4`='现在做好准备。我们即将登岸。', `MaleText_loc5`='現在準備好吧。我們很快就會靠岸。', `MaleText_loc7`='Vayan a prepararse. Pronto estarán en tierra.' WHERE `ID`=42099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말뚝이 바위에 박혀 있고, 주변에 기다란 밧줄이 감겨 있습니다.$b$b무언가 쓰임새가 있는 것 같습니다.', `MaleText_loc4`='一块肉排被敲进了石头里，周围还垂着一大段绳子。$B$B这肯定有什么用途。', `MaleText_loc5`='有一根樁子打進到了岩石裡面，上頭綁著一條長長的繩索。$B$B這一定有什麼作用。', `MaleText_loc7`='En la roca hay clavada una estaca, y una larga cuerda trenzada cuelga de la misma.$B$BEsto debe tener algún propósito.' WHERE `ID`=42100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끼를 매단 다음 밧줄을 풉니다.', `MaleText_loc4`='解开你的诱饵，让它走。', `MaleText_loc5`='綁好你的餌後放開它。', `MaleText_loc7`='Suelta a tu cebo y déjalo libre.', `FemaleText_loc1`='미끼를 매단 다음 밧줄을 풉니다.', `FemaleText_loc4`='解开你的诱饵，让它走。', `FemaleText_loc5`='綁好你的餌後放開它。', `FemaleText_loc7`='Suelta a tu cebo y déjalo libre.' WHERE `ID`=42101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<머릿속에 울려퍼지는 고레크의 목소리>$b$b나...는 곧 죽을... 것이다. 도와 다오... 황혼의 망치단을... 멈추어 다오...$b$b그들이... 내 힘을... 빨아들여... 승천한 신도를... 창조하려 한다... 크나큰 위협이... 넵튤론과의... 전쟁이 닥쳐온다...', `MaleText_loc4`='<拉葛雷克的声音在你脑中回荡。>$B$B我已经要……死了。你必须帮忙……阻止……暮光之锤。$B$B他们汲取……我的能量……来创造……他们的升腾者。他们在……对抗耐普图隆的……战争中……将是重大的……威胁。', `MaleText_loc5`='<勒苟雷克的聲音出現在你的腦中。>$B$B我快不行了。你必須...幫忙...阻止...暮光之錘。$B$B他們...吸取了我的能量...來...來創造他們的卓越者。他們...他們的存在...在這場與...與奈普圖隆的戰爭中...是個...巨大的...威脅。', `MaleText_loc7`='<La voz de L''ghorek resuena en tu cabeza.>$b$BESTOY CASI... MUERTO. DEBES AYUDARME... A DETENER... AL MARTILLO CREPUSCULAR.$B$BABSORBEN... MI ENERGÍA PARA... CREAR... A SUS ASCENDIENTES. SON UNA... GRAN AMENAZA... EN LA GUERRA QUE SE AVECINA... CONTRA NEPTULON.' WHERE `ID`=42102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 위해 거북을 준비해 두셨겠지요?', `MaleText_loc4`='我想你为我准备了一只海龟？', `MaleText_loc5`='我相信你為我準備了一隻烏龜對吧?', `MaleText_loc7`='¿Creo que tienes una tortuga preparada para mí?', `FemaleText_loc1`='절 위해 거북을 준비해 두셨겠지요?', `FemaleText_loc4`='我想你为我准备了一只海龟？', `FemaleText_loc5`='我相信你為我準備了一隻烏龜對吧?', `FemaleText_loc7`='¿Creo que tienes una tortuga preparada para mí?' WHERE `ID`=42104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 분노에 차 울부짖고 있네. 나가들이 여기 온 것도 우연의 일치는 아닐세. 무언가를 기다리고 있어.', `MaleText_loc4`='元素在愤怒的咆哮着。这与纳迦的到来一定不会是巧合。他们一定在等待着什么。', `MaleText_loc5`='元素們會憤怒地怒吼。納迦出現在這不是巧合，他們一定是想要什麼。', `MaleText_loc7`='Los elemento'' gritan de ira. No es una coincidencia que los nagas eh''tén aquí. Eh''peran algo.' WHERE `ID`=42107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식에 동화할 준비가 되었습니다, 선견자님.', `MaleText_loc4`='我已经准备好和你一起看了，先知。', `MaleText_loc5`='我已經準備好觀看你所看到的了，先知。', `MaleText_loc7`='He terminado de prepararme para tu visión, clarividente.', `FemaleText_loc1`='의식에 동화할 준비가 되었습니다, 선견자님.', `FemaleText_loc4`='我已经准备好和你一起看了，先知。', `FemaleText_loc5`='我已經準備好觀看你所看到的了，先知。', `FemaleText_loc7`='He terminado de prepararme para tu visión, clarividente.' WHERE `ID`=42108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었다면 내게 알려주게.', `MaleText_loc4`='等你准备好出发时，告诉我一声。', `MaleText_loc5`='想離開時就跟我說吧。', `MaleText_loc7`='Avísame cuando quieras pah''tir.' WHERE `ID`=42109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버드! 안 돼애애!', `FemaleText_loc4`='巴德！不——！', `FemaleText_loc5`='霸德!不——!', `FemaleText_loc7`='¡Budd! ¡Noooo!' WHERE `ID`=42110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전진하라! 다리를 방어하라!', `FemaleText_loc4`='前进！守住桥梁！', `FemaleText_loc5`='前進!守住橋樑!', `FemaleText_loc7`='¡Avancen! ¡Cuiden el puente!' WHERE `ID`=42111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발하자고, 기어첨.', `MaleText_loc4`='出发，断轮先生。', `MaleText_loc5`='帶我們離開，輪餌先生。', `MaleText_loc7`='Vamos, señor Engranajes.' WHERE `ID`=42113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽으로 방향 잡고 최대 속도로 운전해. 주 함대에 합류해야지.', `MaleText_loc4`='设定航路向东，全速前进，与主力舰队汇合。', `MaleText_loc5`='盡可能用最快速度設定往東飛行。我們去和主艦隊會合。', `MaleText_loc7`='Marque el curso al este a toda marcha. Nos reuniremos con la flota principal.' WHERE `ID`=42114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치안대장, 새로 온 신병들의 상황은 어떤가? 우린 병사들이 더 필요하다. 우리 영토를 침범한 검은바위 오크들을 차단해야 한다!', `MaleText_loc4`='新兵招募有何进展，统帅？我们迫切需要新兵增援。必须阻止黑石兽人对我们领土的入侵！', `MaleText_loc5`='目前招募的進度如何，治安官?我們極需更多的士兵，務必阻止黑石山的獸人入侵我們的領土!', `MaleText_loc7`='¿Cómo va el reclutamiento, mariscal? Necesitamos desesperadamente más soldados. ¡Los orcos Roca Negra que invaden nuestro territorio deben ser detenidos!' WHERE `ID`=42115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 제발, 누가 날 이 우리 안에서 꺼내주었으면!', `MaleText_loc4`='喔上帝，快来人把我从这笼子里弄出去！', `MaleText_loc5`='哦，天啊，誰來把我從牢房放出去啊!', `MaleText_loc7`='Oh, dioses, ¡que alguien me saque de esta jaula!', `FemaleText_loc1`='오 제발, 누가 날 이 우리 안에서 꺼내주었으면!', `FemaleText_loc4`='喔上帝，快来人把我从这笼子里弄出去！', `FemaleText_loc5`='哦，天啊，誰來把我從牢房放出去啊!', `FemaleText_loc7`='Oh, dioses, ¡que alguien me saque de esta jaula!' WHERE `ID`=42116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 제물로 바쳐져 죽기에는 아직 젊어!', `MaleText_loc4`='我还年轻，我不想做祭品！', `MaleText_loc5`='做為犧牲品來說我太年輕了!', `MaleText_loc7`='¡Soy demasiado joven para morir sacrificado!', `FemaleText_loc1`='난 제물로 바쳐져 죽기에는 아직 젊어!', `FemaleText_loc4`='我还年轻，我不想做祭品！', `FemaleText_loc5`='做為犧牲品來說我太年輕了!', `FemaleText_loc7`='¡Soy demasiado joven para morir sacrificada!' WHERE `ID`=42117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 나가면 너희 황혼의 망치단 놈들을 만나는 족족 해치울 거다!', `MaleText_loc4`='等我出去了，我一定要把你们这群暮光之锤渣滓杀得一个不留！', `MaleText_loc5`='等我從這出來，我就會把你們這些暮光之錘的雜種殺的乾乾淨淨。', `MaleText_loc7`='¡Cuando salga de aquí, voy a matarlos a todos y cada unos de ustedes, escoria del Martillo Crepuscular!', `FemaleText_loc1`='내가 여기서 나가면 너희 황혼의 망치단 놈들을 만나는 족족 해치우겠어!', `FemaleText_loc4`='等我出去了，我一定要把你们这群暮光之锤渣滓杀得一个不留！', `FemaleText_loc5`='等我從這出來，我就會把你們這些暮光之錘的雜種殺的乾乾淨淨。', `FemaleText_loc7`='¡Cuando salga de aquí, voy a matarlos a todos y cada unos de ustedes, escoria del Martillo Crepuscular!' WHERE `ID`=42118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 제물로 바칠 필요는 없습니다. 제가 위대한 신도가 될 테니까요!', `MaleText_loc4`='你们不用献祭我。我能做一个很好的教徒！', `MaleText_loc5`='不要拿我當犧牲品。我會是個很棒的教徒!', `MaleText_loc7`='No tenéis por qué sacrificarme. ¡Yo sería un gran cultor!', `FemaleText_loc1`='절 제물로 바칠 필요는 없어요. 제가 위대한 신도가 될 테니까요!', `FemaleText_loc4`='你们不用献祭我。我能做一个很好的教徒！', `FemaleText_loc5`='不要拿我當犧牲品。我會是個很棒的教徒!', `FemaleText_loc7`='No tenéis por qué sacrificarme. ¡Yo sería una gran cultora!' WHERE `ID`=42119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 신도들은 비겁해. 넌더리가 난다고!', `MaleText_loc4`='你们这些教徒都是懦夫。你们令我恶心！', `MaleText_loc5`='你們這些教徒是膽小鬼。你們讓我想吐!', `MaleText_loc7`='Ustedes, los cultores, son unos cobardes. ¡Me ponen enfermo!', `FemaleText_loc1`='너희 신도들은 비겁해. 넌더리가 난다고!', `FemaleText_loc4`='你们这些教徒都是懦夫。你们令我恶心！', `FemaleText_loc5`='你們這些教徒是膽小鬼。你們讓我想吐!', `FemaleText_loc7`='Ustedes, los cultores, son unos cobardes. ¡Me ponen enfermo!' WHERE `ID`=42120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신. 네, 당신 말입니다. 황혼의 신도가 아니군요. 절 여기서 꺼내주십시오!', `MaleText_loc4`='嘿，你。对，就是你。你不是邪教徒。快把我弄出去！', `MaleText_loc5`='喂，那邊的。對，就是你。你不是教徒，放我出來!', `MaleText_loc7`='Eh, tú. Sí, tú. Tú no eres uno de esos cultores. ¡Sácame de aquí!', `FemaleText_loc1`='거기 당신. 네, 당신 말이에요. 황혼의 신도가 아니군요. 절 여기서 꺼내주세요!', `FemaleText_loc4`='嘿，你。对，就是你。你不是邪教徒。快把我弄出去！', `FemaleText_loc5`='喂，那邊的。對，就是你。你不是教徒，放我出來!', `FemaleText_loc7`='Eh, tú. Sí, tú. Tú no eres uno de esos cultores. ¡Sácame de aquí!' WHERE `ID`=42121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들 중 하나가 열쇠를 갖고 있습니다. 그걸 찾아서 절 꺼내주십시오!', `MaleText_loc4`='他们当中有人身上带着钥匙。快找来放我出去！', `MaleText_loc5`='他們其中一人有鑰匙。將它找到救我出來!', `MaleText_loc7`='Uno de ellos tiene la llave. ¡Encuéntrala y sácame de aquí!', `FemaleText_loc1`='저들 중 하나가 열쇠를 갖고 있어요. 그걸 찾아서 절 꺼내주세요!', `FemaleText_loc4`='他们当中有人身上带着钥匙。快找来放我出去！', `FemaleText_loc5`='他們其中一人有鑰匙。將它找到救我出來!', `FemaleText_loc7`='Uno de ellos tiene la llave. ¡Encuéntrala y sácame de aquí!' WHERE `ID`=42122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 끝날 줄은 상상조차 못 했습니다.', `MaleText_loc4`='我从没想到会以这种方式结束。', `MaleText_loc5`='我從沒想過會這樣結束。', `MaleText_loc7`='Nunca creí que mi vida terminaría así.', `FemaleText_loc1`='이렇게 끝날 줄은 상상조차 못 했어요.', `FemaleText_loc4`='我从没想到会以这种方式结束。', `FemaleText_loc5`='我從沒想過會這樣結束。', `FemaleText_loc7`='Nunca creí que mi vida terminaría así.' WHERE `ID`=42123;
