UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 절 구해주실 줄은 몰랐습니다, $n 님!', `MaleText_loc4`='我从没想过救我的人竟会是你，$n！', `MaleText_loc5`='我從沒料到，救我出來的人竟然會是你，$n!', `MaleText_loc7`='¡Nunca creí que serías tú quien me rescataría, $n!', `FemaleText_loc1`='당신이 절 구해주실 줄은 몰랐어요, $n 님!', `FemaleText_loc4`='我从没想过救我的人竟会是你，$n！', `FemaleText_loc5`='我從沒料到，救我出來的人竟然會是你，$n!', `FemaleText_loc7`='¡Nunca creí que serías tú quien me rescataría, $n!' WHERE `ID`=42125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기서 망치단을 괴멸하고 있다고 테일러 부대장님께 분명히 말씀드리겠습니다.', `MaleText_loc4`='我一定会转告泰勒上尉，你正在这里解决暮光之锤。', `MaleText_loc5`='我會跟泰勒隊長說，讓他知道你要在這摧毀暮光之錘。', `MaleText_loc7`='Me aseguraré de decirle al capitán Taylor que estás aquí destruyendo a los del Martillo.', `FemaleText_loc1`='당신이 여기서 망치단을 괴멸하고 있다고 테일러 부대장님께 분명히 말씀드리겠어요.', `FemaleText_loc4`='我一定会转告泰勒上尉，你正在这里解决暮光之锤。', `FemaleText_loc5`='我會跟泰勒隊長說，讓他知道你要在這摧毀暮光之錘。', `FemaleText_loc7`='Me aseguraré de decirle al capitán Taylor que estás aquí destruyendo a los del Martillo.' WHERE `ID`=42126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 임무 수행 중이시군요! 전 부대장님께 돌아가는 게 좋겠습니다.', `MaleText_loc4`='$n正在拼搏！我得赶快回到上尉那儿去。', `MaleText_loc5`='$n正在執行任務!我最好回去找隊長。', `MaleText_loc7`='¡$n está en ello! Será mejor que vuelva con el capitán.', `FemaleText_loc1`='$n 님이 임무 수행 중이시군요! 전 부대장님께 돌아가는 게 좋겠어요.', `FemaleText_loc4`='$n正在拼搏！我得赶快回到上尉那儿去。', `FemaleText_loc5`='$n正在執行任務!我最好回去找隊長。', `FemaleText_loc7`='¡$n está en ello! Será mejor que vuelva con el capitán.' WHERE `ID`=42127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 승천자라고 이름 지은 어떤 강력한 정령으로 자기 자신을 탈바꿈시키고 있습니다. 그들을 저지하십시오, $n 님!', `MaleText_loc4`='他们正在把自己变成某种叫做升腾者的超能元素。你得去阻止他们，$n！', `MaleText_loc5`='它們將自己轉換成一個大家稱為「卓越者」的超級元素。你必須阻止它們，$n!', `MaleText_loc7`='Están transformándose en una especie de súper elementales que ellos denominan un ascendiente. ¡Tienes que detenerlos, $n!', `FemaleText_loc1`='저들은 승천자라고 이름 지은 어떤 강력한 정령으로 자기 자신을 탈바꿈시키고 있어요. 그들을 저지하세요, $n 님!', `FemaleText_loc4`='他们正在把自己变成某种叫做升腾者的超能元素。你得去阻止他们，$n！', `FemaleText_loc5`='它們將自己轉換成一個大家稱為「卓越者」的超級元素。你必須阻止它們，$n!', `FemaleText_loc7`='Están transformándose en una especie de súper elementales que ellos denominan un ascendiente. ¡Tienes que detenerlos, $n!' WHERE `ID`=42128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 확실히 끝이라고 생각했습니다. 고맙습니다, $n 님!', `MaleText_loc4`='我以为我死定了。谢谢你，$n！', `MaleText_loc5`='我以為我死定了。謝謝你，$n!', `MaleText_loc7`='¡Creí que ya no lo contaba! ¡Gracias, $n!', `FemaleText_loc1`='이젠 확실히 끝이라고 생각했어요. 고마워요, $n 님!', `FemaleText_loc4`='我以为我死定了。谢谢你，$n！', `FemaleText_loc5`='我以為我死定了。謝謝你，$n!', `FemaleText_loc7`='¡Creí que ya no lo contaba! ¡Gracias, $n!' WHERE `ID`=42129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저편에서 다시 만납시다, $g 형제여 : 자매여;. 어느 쪽이 나가는 길입니까?', `MaleText_loc4`='我们在另一边见，$g兄弟:姐妹;。出口在哪边？', `MaleText_loc5`='在另一頭與你們相見，$g兄弟:姊妹;。出口在哪?', `MaleText_loc7`='Te veo en el otro lado $ghermano:hermana;. ¿Por dónde queda la salida?', `FemaleText_loc1`='저편에서 다시 만나요, $g 형제여 : 자매여;. 어느 쪽이 나가는 길이죠?', `FemaleText_loc4`='我们在另一边见，$g兄弟:姐妹;。出口在哪边？', `FemaleText_loc5`='在另一頭與你們相見，$g兄弟:姊妹;。出口在哪?', `FemaleText_loc7`='Te veo en el otro lado $ghermano:hermana;. ¿Por dónde queda la salida?' WHERE `ID`=42130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥브라이드, 이 친구는 어떤가? 이 $c 친구는 우리의 대의에 참여할 수 있겠지!', `MaleText_loc4`='这个怎么样，玛克布莱德？这位$c一定能帮到我们的！', `MaleText_loc5`='這一位如何，瑪克布萊德?這位$c想必可加入我們的陣容!', `MaleText_loc7`='¿Y qué pasa con $geste:esta;, McBride? ¡Seguro que $geste:esta; $c puede unirse a la causa!' WHERE `ID`=42131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, $n. 너는 쓸모 있는 $c|1이;가; 되어야 한다. 맥브라이드가 스톰윈드 군대의 일원이 되는 데 필요한 모든 걸 가르쳐 줄 것이다!', `MaleText_loc4`='太棒了。$n，你一定会成为优秀的$c。玛克布莱德会教你学会你所要了解的一切，帮你成为守卫暴风城的精兵强将！', `MaleText_loc5`='太好了，$n，你必定會成為一位優秀的$c。瑪克布萊德會認真指導你加入暴風城衛兵所需知道的所有事情!', `MaleText_loc7`='Estupendo. $n, serás $gun:una; $c excelente. ¡McBride te enseñará todo lo que necesites saber para unirte a las filas de la guardia de Ventormenta!' WHERE `ID`=42132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 여기 꽤 오래 있었습니다. 놈들이 절 제물로 바치려고 해요!', `MaleText_loc4`='我已经被关在这儿好多天了。他们正准备拿我献祭！', `MaleText_loc5`='我在這已經好幾天了。他們就要拿我當犧牲品了!', `MaleText_loc7`='Llevo días aquí. ¡Están a punto de sacrificarme!', `FemaleText_loc1`='전 여기 꽤 오래 있었어요. 놈들이 절 제물로 바치려고 해요!', `FemaleText_loc4`='我已经被关在这儿好多天了。他们正准备拿我献祭！', `FemaleText_loc5`='我在這已經好幾天了。他們就要拿我當犧牲品了!', `FemaleText_loc7`='Llevo días aquí. ¡Están a punto de sacrificarme!' WHERE `ID`=42133;
