UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 나가면 너희 황혼의 망치단을 단단히 혼내주겠어!', `MaleText_loc4`='等我出去，我一定会把你们这群暮光之锤杂种撕成碎片！', `MaleText_loc5`='等我出來，我會把你們暮光之錘的每個垃圾都撕成碎片!', `MaleText_loc7`='¡Cuando salga de aquí voy a arrancaros la piel a tiras, perros del Martillo Crepuscular!', `FemaleText_loc1`='내가 여기서 나가면 너희 황혼의 망치단을 단단히 혼내주겠어!', `FemaleText_loc4`='等我出去，我一定会把你们这群暮光之锤杂种撕成碎片！', `FemaleText_loc5`='等我出來，我會把你們暮光之錘的每個垃圾都撕成碎片!', `FemaleText_loc7`='¡Cuando salga de aquí voy a arrancaros la piel a tiras, perros del Martillo Crepuscular!' WHERE `ID`=42144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 거래합시다. 제가 훌륭한 신도가 될게요!', `MaleText_loc4`='也许我们能做个交易。我会是个优秀的教徒！', `MaleText_loc5`='也許我們可以打個商量。我會變成很棒的教徒!', `MaleText_loc7`='Quizá podamos hacer un trato. ¡Yo sería un gran cultor!', `FemaleText_loc1`='우리 거래하죠. 제가 훌륭한 신도가 될게요!', `FemaleText_loc4`='也许我们能做个交易。我会是个优秀的教徒！', `FemaleText_loc5`='也許我們可以打個商量。我會變成很棒的教徒!', `FemaleText_loc7`='Quizá podamos hacer un trato. ¡Yo sería una gran cultora!' WHERE `ID`=42145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 신도들은 비겁해. 넌더리가 난다고!', `MaleText_loc4`='你们这些教徒都是懦夫。你们令我恶心！', `MaleText_loc5`='你們這些教徒是膽小鬼。你們讓我想吐!', `MaleText_loc7`='Ustedes, los cultores, son unos cobardes. ¡Me ponen enfermo!', `FemaleText_loc1`='너희 신도들은 비겁해. 넌더리가 난다고!', `FemaleText_loc4`='你们这些教徒都是懦夫。你们令我恶心！', `FemaleText_loc5`='你們這些教徒是膽小鬼。你們讓我想吐!', `FemaleText_loc7`='Ustedes, los cultores, son unos cobardes. ¡Me ponen enferma!' WHERE `ID`=42146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신. 황혼의 신도가 아니군. 날 여기서 꺼내주시오!', `MaleText_loc4`='你过来。你不是教徒。快把我放出去！', `MaleText_loc5`='喂，那邊那個。你不是教徒的一員，把我從這放出來!', `MaleText_loc7`='Eh, tú. Tú no eres uno de esos cultores. ¡Sácame de aquí!', `FemaleText_loc1`='거기 당신. 황혼의 신도가 아니군요. 절 여기서 꺼내주세요!', `FemaleText_loc4`='你过来。你不是教徒。快把我放出去！', `FemaleText_loc5`='喂，那邊那個。你不是教徒的一員，把我從這放出來!', `FemaleText_loc7`='Eh, tú. Tú no eres uno de esos cultores. ¡Sácame de aquí!' WHERE `ID`=42147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들 중 한 명이 열쇠를 갖고 있소. 그걸 찾아 날 우리에서 꺼내 주시오!', `MaleText_loc4`='他们当中有人身上带着钥匙。快找来放我出去！', `MaleText_loc5`='鑰匙就在他們其中一個人的身上。找到鑰匙，把我從牢裡放出來!', `MaleText_loc7`='Uno de ellos tiene la llave. ¡Encuéntrala y sácame de aquí!', `FemaleText_loc1`='저들 중 한 명이 열쇠를 갖고 있어요. 그걸 찾아 절 우리에서 꺼내 주세요!', `FemaleText_loc4`='他们当中有人身上带着钥匙。快找来放我出去！', `FemaleText_loc5`='鑰匙就在他們其中一個人的身上。找到鑰匙，把我從牢裡放出來!', `FemaleText_loc7`='Uno de ellos tiene la llave. ¡Encuéntrala y sácame de aquí!' WHERE `ID`=42148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 힘없이 당하진 않는다!', `MaleText_loc4`='我不要这么无助的死去！', `MaleText_loc5`='我不會就這樣束手待斃!', `MaleText_loc7`='¡No pienso morir así, indefenso!', `FemaleText_loc1`='이렇게 힘없이 당하진 않겠어!', `FemaleText_loc4`='我不要这么无助的死去！', `FemaleText_loc5`='我不會就這樣束手待斃!', `FemaleText_loc7`='¡No pienso morir así, indefensa!' WHERE `ID`=42149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사드립니다, $n 님.', `MaleText_loc4`='向你致敬，$n。', `MaleText_loc5`='我由衷地感謝你，$n。', `MaleText_loc7`='Te doy las gracias, $n.', `FemaleText_loc1`='감사드립니다, $n 님.', `FemaleText_loc4`='向你致敬，$n。', `FemaleText_loc5`='我由衷地感謝你，$n。', `FemaleText_loc7`='Te doy las gracias, $n.' WHERE `ID`=42150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 날 구하리라고는 꿈에도 생각하지 못했소, $n!', `MaleText_loc4`='我从没想过救我的人竟会是你，$n！', `MaleText_loc5`='我從沒想過會被你所救，$n!', `MaleText_loc7`='¡Nunca creí que serías tú quien me rescataría, $n!', `FemaleText_loc1`='당신이 날 구하리라고는 꿈에도 생각하지 못했어요, $n!', `FemaleText_loc4`='我从没想过救我的人竟会是你，$n！', `FemaleText_loc5`='我從沒想過會被你所救，$n!', `FemaleText_loc7`='¡Nunca creí que serías tú quien me rescataría, $n!' WHERE `ID`=42151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기서 망치단을 괴멸하고 있다고 나즈그림 부관님께 말씀드리겠소.', `MaleText_loc4`='我一定会转告军团士兵纳兹戈林，你正在这里解决暮光之锤。', `MaleText_loc5`='我會告訴軍團士兵納茲格寧姆你正在消滅這裡的暮光之錘。', `MaleText_loc7`='Le diré al legionario Nazgrim que estás aquí destruyendo a los del Martillo.', `FemaleText_loc1`='당신이 여기서 망치단을 괴멸하고 있다고 나즈그림 부관님께 말씀드리겠어요.', `FemaleText_loc4`='我一定会转告军团士兵纳兹戈林，你正在这里解决暮光之锤。', `FemaleText_loc5`='我會告訴軍團士兵納茲格寧姆你正在消滅這裡的暮光之錘。', `FemaleText_loc7`='Le diré al legionario Nazgrim que estás aquí destruyendo a los del Martillo.' WHERE `ID`=42152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 나즈그림 님께 돌아가는 게 낫겠군.', `MaleText_loc4`='我得回去找纳兹戈林了。', `MaleText_loc5`='我最好回到納茲格寧姆。', `MaleText_loc7`='Será mejor que vuelva con Nazgrim.', `FemaleText_loc1`='전 나즈그림 님께 돌아가는 게 낫겠군요.', `FemaleText_loc4`='我得回去找纳兹戈林了。', `FemaleText_loc5`='我最好回到納茲格寧姆。', `FemaleText_loc7`='Será mejor que vuelva con Nazgrim.' WHERE `ID`=42153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 승천자라고 이름 지은 강력한 정령으로 스스로를 탈바꿈하고 있소. 저들을 저지해야 하오, $n!', `MaleText_loc4`='他们正在把自己变成某种叫做升腾者的超能元素。你得去阻止他们，$n！', `MaleText_loc5`='他們把自己轉變成某種叫做「卓越者」的超級元素生物。你一定要阻止他們，$n!', `MaleText_loc7`='Están transformándose en una especie de súper elementales que ellos denominan un ascendiente. ¡Tienes que detenerlos, $n!', `FemaleText_loc1`='저들은 승천자라고 이름 지은 강력한 정령으로 스스로를 탈바꿈하고 있어요. 저들을 저지해야 해요, $n!', `FemaleText_loc4`='他们正在把自己变成某种叫做升腾者的超能元素。你得去阻止他们，$n！', `FemaleText_loc5`='他們把自己轉變成某種叫做「卓越者」的超級元素生物。你一定要阻止他們，$n!', `FemaleText_loc7`='Están transformándose en una especie de súper elementales que ellos denominan un ascendiente. ¡Tienes que detenerlos, $n!' WHERE `ID`=42154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 죽었다고 생각했소. 고맙소, $n!', `MaleText_loc4`='我以为我死定了。谢谢你，$n！', `MaleText_loc5`='我以為我死定了。謝謝，$n!', `MaleText_loc7`='Creía que era hombre muerto. ¡Gracias, $n!', `FemaleText_loc1`='난 이제 죽었다고 생각했어요. 고마워요, $n!', `FemaleText_loc4`='我以为我死定了。谢谢你，$n！', `FemaleText_loc5`='我以為我死定了。謝謝，$n!', `FemaleText_loc7`='Creía que era mujer muerta. ¡Gracias, $n!' WHERE `ID`=42155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에서 만납시다, $g 형제여 : 자매여;, 나가는 길은 저쪽인가?', `MaleText_loc4`='我们外面见，$g兄弟:姐妹;。出口是在那边吗？', `MaleText_loc5`='外面見，$g兄弟:姐妹;。那是出口嗎?', `MaleText_loc7`='Te veo fuera, $ghermano:hermana;. ¿La salida es por aquí?', `FemaleText_loc1`='밖에서 만납시다, $g 형제여 : 자매여;, 나가는 길은 저쪽인가요?', `FemaleText_loc4`='我们外面见，$g兄弟:姐妹;。出口是在那边吗？', `FemaleText_loc5`='外面見，$g兄弟:姐妹;。那是出口嗎?', `FemaleText_loc7`='Te veo fuera, $ghermano:hermana;. ¿La salida es por aquí?' WHERE `ID`=42156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 여기 꽤 오래 있었소. 저들이 날 제물로 바치려 하오!', `MaleText_loc4`='我已经被关在这儿好多天了。他们正准备拿我献祭！', `MaleText_loc5`='我在這已經好幾天了。他們就要拿我當犧牲品了!', `MaleText_loc7`='Llevo días aquí. ¡Están a punto de sacrificarme!', `FemaleText_loc1`='난 여기 꽤 오래 있었어요. 저들이 날 제물로 바치려 해요!', `FemaleText_loc4`='我已经被关在这儿好多天了。他们正准备拿我献祭！', `FemaleText_loc5`='我在這已經好幾天了。他們就要拿我當犧牲品了!', `FemaleText_loc7`='Llevo días aquí. ¡Están a punto de sacrificarme!' WHERE `ID`=42157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문을 들여다보니, 지하 동굴의 내부가 보입니다. 물이 떨어지는 소리가 대지가 흔들리는 소리에 묻혀 들리지 않습니다. 이 차원문이 열린 이유가 있을 것입니다. 그 이유가 무엇일까요?', `MaleText_loc4`='穿过传送门往里望去，你看到一个地下洞穴的内部。水流拍击与大地移位的声音混杂在一起。这个传送门一定是因某种原因打开的，但究竟是为什么呢？', `MaleText_loc5`='凝視著傳送門另一邊的你，看到了一個地底洞窟的內部。水滴落下的聲音混雜了土地震動的聲音。傳送門一定是為了什麼原因才打開的，為什麼?', `MaleText_loc7`='Al mirar a través del portal ves la parte más profunda de una cueva submarina. El sonido del agua que cae es amortiguado por el ruido de la tierra al moverse. Este portal debió abrirse por alguna razón, pero ¿cuál?' WHERE `ID`=42158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어갑니다.', `MaleText_loc4`='走进传送门。', `MaleText_loc5`='進入傳送門。', `MaleText_loc7`='Atraviesa el portal.', `FemaleText_loc1`='차원문으로 들어갑니다.', `FemaleText_loc4`='走进传送门。', `FemaleText_loc5`='進入傳送門。', `FemaleText_loc7`='Atraviesa el portal.' WHERE `ID`=42159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 근처로 가자 극심한 열기가 뿜어져 나옵니다. 협곡에서 메아리치는 망치 소리가 희미하게 반복적으로 들려옵니다. 대체 이 차원문은 어디로 통하는 것일까요?', `MaleText_loc4`='当你靠近传送门时，你感到了自门内侵散而出的热浪。锤子敲击声自峡谷回响而来，在四周环绕着微弱而坚实的节奏。这传送门究竟是通往哪里的？', `MaleText_loc5`='當你靠近傳送門，你感覺到了高熱的輻射線。你聽到了錘子敲打所發出的聲音在山谷之間迴響，就像是種微弱而規律的旋律。這個傳送門通往哪裡?', `MaleText_loc7`='A medida que te acercas al portal, sientes el intenso calor que irradia. El eco de los martillos que rebota en las paredes de un cañón crea un ritmo regular que te envuelve. ¿Adónde conducirá este portal?' WHERE `ID`=42160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어갑니다.', `MaleText_loc4`='走进传送门。', `MaleText_loc5`='進入傳送門。', `MaleText_loc7`='Atraviesa el portal.', `FemaleText_loc1`='차원문으로 들어갑니다.', `FemaleText_loc4`='走进传送门。', `FemaleText_loc5`='進入傳送門。', `FemaleText_loc7`='Atraviesa el portal.' WHERE `ID`=42161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤가, $n? 데스윙과 그의 추종자들을 처치하려면 모을 수 있는 최대한의 도움이 필요한 상황이다!', `MaleText_loc4`='你怎么说，$n？我们必须集结一切力量来击败死亡之翼和他的爪牙！', `MaleText_loc5`='你怎麼說，$n?想要打敗死亡之翼和他的嘍囉們，我們會需要所有一切的援助。', `MaleText_loc7`='¿Qué dices, $n? ¡Necesitamos toda la ayuda que podamos reunir si queremos derrotar a Alamuerte y a sus esbirros!' WHERE `ID`=42162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 전하! 다음 전투를 위해 $n|1을;를; 준비시키겠습니다!', `MaleText_loc4`='是。阁下！我们会帮$n为即将打响的战斗做好准备！', `MaleText_loc5`='是，陛下!我們會好好訓練$n，為即將來臨的戰鬥做好準備!', `MaleText_loc7`='Sí. ¡Alteza! ¡Prepararemos a $n para la batalla que se avecina!' WHERE `ID`=42163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함대에 밀집 대형 갖추라고 명령해. 바짝 붙으라고!', `MaleText_loc4`='命令舰队组成密集队形。所有人，高度戒备！', `MaleText_loc5`='命令艦隊排成緊密隊形。大家靠近一點!', `MaleText_loc7`='Ordene a la flota que forme cerca. ¡No se alejen!' WHERE `ID`=42164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 우리의 동맹이 도착했노라! 적을 다리 너머로 밀어내라, 형제자매여.', `FemaleText_loc4`='我们的盟军到了！全力进攻，族人们，把他们赶回去。', `FemaleText_loc5`='我們的盟軍到了!把他們趕回去，族人們。', `FemaleText_loc7`='¡Llegaron nuestros aliados! Empújenlos del borde, mis hermanos.' WHERE `ID`=42165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님! 함대가 바로 앞에 있습니다.', `MaleText_loc4`='长官！舰队正向前进发。', `MaleText_loc5`='長官! 艦隊就在正前方。', `MaleText_loc7`='¡Señor! La flota está adelante.' WHERE `ID`=42166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄돌 교각에 접근 중입니다, 선장님.', `MaleText_loc4`='接近萨多尔大桥，长官。', `MaleText_loc5`='接近薩多爾大橋中，長官。', `MaleText_loc7`='Nos acercamos al Puente Thandol, señor.' WHERE `ID`=42167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 승리했도다. 아즈샤라의 이름으로!', `FemaleText_loc4`='我们胜利了！以艾萨拉之名！', `FemaleText_loc5`='我們成功了。以艾薩拉之名!', `FemaleText_loc7`='Victoria. ¡En nombre de Azshara!' WHERE `ID`=42168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 여전사여, 다시 한 번 그대의 공을 치하하노라. 나뿐 아니라 온 백성이 그대를 예우할 것이다.', `FemaleText_loc4`='我的女武士，你再一次赢得了我和我们全部族人的尊重。', `FemaleText_loc5`='我的戰鬥仕女，你們又一次贏得我的敬意，還有我們人民的敬意。', `FemaleText_loc7`='Mi Doncella de batalla, has vuelto a ganarte mi respeto y el de toda nuestra gente.' WHERE `ID`=42169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이토록 큰 공을 세웠는데 어찌 그대를 그냥 여전사라 부를 수 있겠는가. 새 칭호를 받아라. 그대는 이제 아즈샤라의 용사, 나르지라이다.', `FemaleText_loc4`='女武士这个头衔已经无法彰显你的功勋了。接受这新的冠冕吧——纳尓吉拉，艾萨拉的勇士。', `FemaleText_loc5`='你已經超越了這個稱號。你不再是戰鬥仕女。接受你新的榮耀，納吉拉，艾薩拉的勇士。', `FemaleText_loc7`='Has superado tu título. Ya no eres una Doncella de batalla. Toma tu nueva corona, Nar''jira, campeona de Azshara.' WHERE `ID`=42170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소환이 이미 끝났고 아즈샤라 님의 군대가 전쟁을 준비하러 모여들고 있으니, 바다사냥꾼 넵튤론도 머지않아 쓰러질 것이다.', `FemaleText_loc4`='召唤已经完成，艾萨拉的军队正在集结，猎潮者耐普图隆很快就会被击溃。', `FemaleText_loc5`='召喚已經完成，艾薩拉的軍隊正在集結，獵潮者很快就會倒下。', `FemaleText_loc7`='Con el conjuro completo y los ejércitos de Azshara listos para la guerra, el Cazamareas caerá pronto.' WHERE `ID`=42171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 이렇게 자꾸 새로운 문제가 발생해서는 이곳 주위의 질서를 바로잡기가 어렵습니다! $n, 당신이 좋은 소식을 가져왔으면 좋겠군요...', `MaleText_loc4`='啊，就算没有这些新麻烦不断的冒出来，维持这儿的秩序就已经够让人头痛的了！希望你有好消息，$n……', `MaleText_loc5`='唉，光要管好這邊的秩序已經很不容易了，更何況還有這麼多的新問題一直冒出來。我希望你帶來的是好消息，$n...', `MaleText_loc7`='¡Ay, ya es difícil mantener el orden por aquí sin que aparezcan de repente todos esos nuevos problemas! ¡Espero que traigas buenas noticias, $n...' WHERE `ID`=42172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 군마를 탔으면 합니다, 치안대장님.', `MaleText_loc4`='我希望能骑上暴风城军马，长官。', `MaleText_loc5`='我想要騎上暴風城戰騎，長官。', `MaleText_loc7`='Deseo montar al destrero de Ventormenta, señor.', `FemaleText_loc1`='스톰윈드 군마를 탔으면 합니다, 치안대장님.', `FemaleText_loc4`='我希望能骑上暴风城军马，长官。', `FemaleText_loc5`='我想要騎上暴風城戰騎，長官。', `FemaleText_loc7`='Deseo montar al destrero de Ventormenta, señor.' WHERE `ID`=42173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 차질이 있었지만, 그래도 우리는 임무를 다해야 합니다.', `MaleText_loc4`='我们经受了一次不小的挫折，但我们无论如何都要完成任务。', `MaleText_loc5`='我們遭受了一個嚴重的挫折，儘管如此，我們必須完成任務。', `MaleText_loc7`='Hemos sufrido un grave contratiempo, pero a pesar de todo debemos cumplir con nuestra misión.' WHERE `ID`=42175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 단단히 먹으십시오, $n 님.$B$B틈을 만들어 나가들이 물의 세계로 들어가는 것을 막아야 합니다!', `MaleText_loc4`='打起精神来，$n。$b$b我们必须赶往决口处，不能让纳迦进入水元素位面！', `MaleText_loc5`='準備好， $n。$b$b我們必須前進到止境那然後防止納迦進入水之界域!', `MaleText_loc7`='Vuelve a reunir tus fuerzas, $n.$b$b¡Debemos llegar a la brecha y evitar que los nagas entren en el plano de agua!' WHERE `ID`=42176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 완전히 망가졌네요! 다른 곳에서 해 봐요.', `MaleText_loc4`='啊，它已经完全被破坏了！我们得换别处试试。', `MaleText_loc5`='哇噢，它完全毀掉了!我們試試別的地方吧。', `MaleText_loc7`='¡Vaya, está totalmente destrozado! Probemos en otro lugar.', `FemaleText_loc1`='우와, 완전히 망가졌네요! 다른 곳에서 해 봐요.', `FemaleText_loc4`='啊，它已经完全被破坏了！我们得换别处试试。', `FemaleText_loc5`='哇噢，它完全毀掉了!我們試試別的地方吧。', `FemaleText_loc7`='¡Vaya, está totalmente destrozado! Probemos en otro lugar.' WHERE `ID`=42177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 심장호, 너무 낮게 날고 있다. 너무 낮다고!', `MaleText_loc4`='奥格瑞玛之心，你的高度太低了。太低了！', `MaleText_loc5`='奧格瑪之心，你飛太低了。太低了!', `MaleText_loc7`='Por Orgrimmar, estás yendo muy bajo. ¡Muy bajo! ¡Sube! ¡Gira! ¡HAZ ALGO!' WHERE `ID`=42178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라가! 멈춰! 어떻게든 해 봐!', `MaleText_loc4`='拉升！下降！随便做点儿什么！', `MaleText_loc5`='往上拉!往下拉!隨便拉就對了!', `MaleText_loc7`='¡Sube! ¡Baja! ¡HAZ ALGO!' WHERE `ID`=42179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s|1이;가; 몸을 곧추세우고 |cFFFF0000|Hspell:77982|h[이글거리는 불길]|h|r을 시전합니다!
', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s高仰起身子，开始施放|cFFFF0000|Hspell:77982|h[灼热烈焰]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s昂首準備使出|cFFFF0000|Hspell:77982|h[灼熱烈焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_selfdestruct.blp:20|t¡%s se echa hacia atrás y lanza |cFFFF0000|Hspell:77982|h[Llamas abrasadoras]|h|r!' WHERE `ID`=42180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오. 상처를 돌볼 시간이 없습니다!', `MaleText_loc4`='站起来，朋友们。没时间处理伤口！', `MaleText_loc5`='起身吧，朋友。我們沒有時間舔舐傷口!', `MaleText_loc7`='Arriba, amigo. ¡No hay tiempo para lamer las heridas!' WHERE `ID`=42181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탈것에 문제가 생겨 피해를 보더라도, 버텨내야 합니다. 성공해야 합니다!', `MaleText_loc4`='尽管我们损失了这辆战车，但必须坚持下去。我们必须成功！', `MaleText_loc5`='失去這台載具是個挫折，但我們必須前進。我們必須勝利!', `MaleText_loc7`='Aunque la pérdida de ese vehículo en un contratiempo, debemos continuar. ¡Debemos tener éxito!' WHERE `ID`=42182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 다 고치기나 할까요? 다른 쪽으로 가 봐요.', `MaleText_loc4`='以为他们能把这一切都弄好？我们去另一侧。', `MaleText_loc5`='你認為他們什麼時候才會處理好?讓我們去另一邊。', `MaleText_loc7`='¿Crees que en algún momento arreglarán todo esto? Vamos al otro lado.', `FemaleText_loc1`='이걸 다 고치기나 할까요? 다른 쪽으로 가 봐요.', `FemaleText_loc4`='以为他们能把这一切都弄好？我们去另一侧。', `FemaleText_loc5`='你認為他們什麼時候才會處理好?讓我們去另一邊。', `FemaleText_loc7`='¿Crees que en algún momento arreglarán todo esto? Vamos al otro lado.' WHERE `ID`=42183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤처진 자들을 모두 죽이고 이벤트를 보냅니다...', `MaleText_loc4`='我克服重重障碍才走到这里……', `MaleText_loc5`='我殺掉所有落單的，發出通報...', `MaleText_loc7`='Mataré a todos los rezagados y enviaré un aviso...' WHERE `ID`=42184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용돌이까지 나아가야 합니다!', `MaleText_loc4`='我们必须到裂口那里去！', `MaleText_loc5`='我們必須要前往坑洞!', `MaleText_loc7`='¡Debemos llegar al cráter!' WHERE `ID`=42185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠수함이 폭발한다! 이동!', `MaleText_loc4`='潜艇要爆炸了！撤离！', `MaleText_loc5`='潛水艇要爆炸了!快走!', `MaleText_loc7`='¡El submarino explotará! ¡Salgan!' WHERE `ID`=42186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디가 아프신가?', `MaleText_loc4`='哪儿疼？', `MaleText_loc5`='哪裡在痛?', `MaleText_loc7`='¿Dónde te duele?' WHERE `ID`=42187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 더러운 바다마녀가 우리 배를 장악했네! 충격에 대비하게!', `MaleText_loc4`='该死的海巫击垮了我们的舰船！抓紧了！！！', `MaleText_loc5`='骯髒的海巫壓制了我們的船!做好衝擊準備!', `MaleText_loc7`='¡Esa repugnante bruja marina se ha hecho con nuestro barco! ¡¡Prepárate para el impacto!!' WHERE `ID`=42188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 땅에 주문 집중점을 던집니다!', `MaleText_loc4`='%s将他的法术核心掷到地面上！', `MaleText_loc5`='%s把他的法術焦點丟到地上!', `MaleText_loc7`='¡%s arroja su foco de encantamiento al suelo!', `FemaleText_loc1`='%s|1이;가; 땅에 주문 집중점을 던집니다!', `FemaleText_loc4`='%s将他的法术核心掷到地面上！', `FemaleText_loc5`='%s把他的法術焦點丟到地上!', `FemaleText_loc7`='¡%s arroja su foco de encantamiento al suelo!' WHERE `ID`=42189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보같이 우리 바다에 흙발로 들어서다니, 어리석은 호드 놈들. 폭풍의 채찍을 받아라!', `FemaleText_loc4`='你们愚蠢地侵入了我们的水域，部落的傻瓜们。接受我风暴的鞭笞吧！', `FemaleText_loc5`='部落的笨蛋，你們竟敢愚蠢地踏入我們的水域。看我的風暴的厲害!', `FemaleText_loc7`='Os habéis adentrado estúpidamente en nuestras aguas, idiotas de la Horda. ¡Os borraré de la faz de la tierra con el azote de mi tormenta!' WHERE `ID`=42190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아, 고블린 맙소사!', `MaleText_loc4`='哦，地精圣灵啊！', `MaleText_loc5`='噢，哥布林的主啊!', `MaleText_loc7`='¡Oh, la Goblinidad!' WHERE `ID`=42191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계곡이 우리 움직임을 숨겨 줄 거야. 낮게 날고 바짝 붙어.', `MaleText_loc4`='这座山谷能掩护我们。低空飞行，跟紧。', `MaleText_loc5`='山谷應該可以掩護我們。降低高度，跟緊。', `MaleText_loc7`='El valle ocultará nuestros movimientos. Mantente bajo. No te alejes. ¡No quiero más errores!' WHERE `ID`=42192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 실수하면 안 된다고!', `MaleText_loc4`='别再有人犯错误！', `MaleText_loc5`='我不想再看到任何的錯誤!', `MaleText_loc7`='¡No quiero más errores!' WHERE `ID`=42193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 호드의 전사들이여, 내 말을 들어라!', `MaleText_loc4`='追随部落的勇士们。听我说！', `MaleText_loc5`='部落的戰士們，聽我一言!', `MaleText_loc7`='Hermanos guerreros de la Horda. ¡Escúchenme!' WHERE `ID`=42194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 앞에 우리의 적이 숨어 있다. 혼돈을 숭배하며 세상을 다시 만들려는 자들이.', `MaleText_loc4`='敌人近在眼前。混沌的信徒正图谋重铸这个世界。', `MaleText_loc5`='我們的敵人躲在前方。混沌的信奉者想要重造這個世界。', `MaleText_loc7`='Delante de nosotros se oculta nuestro enemigo. Los adoradores del caos que buscan rehacer al mundo.' WHERE `ID`=42195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들이여, 새로운 세상이 올 것이다. 하지만 놈들이 바라는 세상은 아니야!', `MaleText_loc4`='新的世界即将到来，朋友们，但并不是他们设计的世界。', `MaleText_loc5`='新的世界即將來臨，朋友們。但不是他們所設計的世界。', `MaleText_loc7`='Un mundo nuevo se acerca, amigos. Pero no será el mundo que ellos traman.' WHERE `ID`=42196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는, 함께 황혼의 망치단을 쓸어버리고 놈들의 요새를 파괴할 것이다.', `MaleText_loc4`='我们将齐心协力，粉碎暮光之锤，摧毁他们的堡垒，', `MaleText_loc5`='我們將合力摧毀暮光之錘，摧毀他們的堡壘，', `MaleText_loc7`='Juntos, aplastaremos al Martillo Crepuscular, arrasaremos su bastión,' WHERE `ID`=42197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 땅을 짓밟고, 시체를 불태우리라. 온 세상이 우리 앞에 벌벌 떨 것이다.', `MaleText_loc4`='让他们的土地寸草不生。我们的力量将让他们颤抖。', `MaleText_loc5`='在他們的土地上灑鹽，燒掉他們的屍體。在我們的力量之下，萬物都會顫抖。', `MaleText_loc7`='salaremos la tierra y quemaremos los cuerpos. Nuestra fuerza hará temblar TODO.' WHERE `ID`=42198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 우리는 진정한 이 세계의 주인으로 우뚝 서리라.', `MaleText_loc4`='我们将成为这个世界真正的主人。', `MaleText_loc5`='然後我們會以主人的姿態君臨這個世界...', `MaleText_loc7`='Y entonces seremos los jinetes de este mundo,' WHERE `ID`=42199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신념으로 뭉친, 그 누구의 힘도 빌리지 않는 무적의 호드로서 말이다!', `MaleText_loc4`='我们拥有共同的信念，强大的力量，无畏的勇气。', `MaleText_loc5`='在我們的信念下團結一致，有著無與倫比的力量，不需要對任何人交代。', `MaleText_loc7`=' los amos: unidos por nuestra convicción, incomparables por nuestra fuerza, inexpugnables por nuestra propia cuenta.' WHERE `ID`=42200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 세상을 다시 만들자. 바로 우리의 세상을! 호드를 위하여!', `MaleText_loc4`='今天，我们将重铸世界。我们的世界。为了部落！', `MaleText_loc5`='今天，重造世界的是我們。我們的世界。為了部落!', `MaleText_loc7`='Hoy, NOSOTROS reharemos el mundo. NUESTRO mundo. ¡POR LA HORDA!' WHERE `ID`=42201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 고원에 접근하는 중입니다, 선장님.', `MaleText_loc4`='即将到达暮光高地，船长。', `MaleText_loc5`='即將來到暮光高地了，船長。', `MaleText_loc7`='Las Tierras Altas Crepusculares, Capitán.' WHERE `ID`=42202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보게, 드워프로군. 하하하! 구멍 속에 숨은 생쥐처럼 샐쭉한 꼴이라니.', `MaleText_loc4`='看——那些矮人。哈！他们生气的样子就好像缩在洞里的土拨鼠。', `MaleText_loc5`='看─矮人。哈!他們生氣起來像是地洞裡的土撥鼠。', `MaleText_loc7`='Miren: enanos. ¡Ja! Se guardan en sus hoyos como topos.' WHERE `ID`=42203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님! 선두 쪽 좌현에 얼라이언스 함대가 보입니다.', `MaleText_loc4`='船长！船首左舷发现联盟海军舰队。', `MaleText_loc5`='隊長，長官!在舷艏處發現聯盟的海軍艦隊。', `MaleText_loc7`='¡Capitán, señor! Flota naval de la Alianza, proa a babor.' WHERE `ID`=42204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 호위 병력 없이 밀집 대형으로 접근 중이다.', `MaleText_loc4`='联盟军队阵型密集，而且没有护卫。', `MaleText_loc5`='聯盟在沒有護衛下以密集隊形接近中。', `MaleText_loc7`='La Alianza vuela en formación cerrada sin escolta.' WHERE `ID`=42205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 공격하라! 놈들이 무기력해진 이 틈에 싹 쓸어 버려라! 으하하하!', `MaleText_loc4`='空军部队进攻！！趁他们动弹不得的时候，狠狠地打！', `MaleText_loc5`='空中守衛，攻擊!轟炸他們，在他們無法做出反應前!', `MaleText_loc7`='¡¡Guardia aérea, ataquen!! ¡Ametrállenlos ahora que no pueden maniobrar!' WHERE `ID`=42206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야... 뭐야?! 도대체 뭐 하는 거지? 수송선을 지켜줄 비행기가 없잖아.', `MaleText_loc4`='什么……什么？！他以为他在干什么？运输船没有保护啦。', `MaleText_loc5`='什麼 - 什麼!? 他以為他在幹嘛? 運輸艦完全沒人保護了。', `MaleText_loc7`='Qué... ¡¿QUÉ?! ¿Qué está HACIENDO? Los portanaves están desprotegidos.' WHERE `ID`=42207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호위선을 다 내보내다니, 지가 무슨 용가리 통뼈야?', `MaleText_loc4`='是哪个疯子下令撤去对他的空中支援？', `MaleText_loc5`='什麼樣的瘋子會命令身邊的空中支援離開?', `MaleText_loc7`='¿Qué clase de loco ordena la retirada de su apoyo aéreo?' WHERE `ID`=42208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기어첨, 함대에 신호 보내라고. 방어 대형으로!', `MaleText_loc4`='断轮先生，向舰队发信号。防御队形！', `MaleText_loc5`='輪餌先生，給艦隊信號。防禦隊形!', `MaleText_loc7`='Señor Engranajes, señalice a la flota. ¡Formaciones defensivas!' WHERE `ID`=42209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 호위선이 없다. 어디에든 대포 쏠 수 있게 대형 잡으라고. 어서! 어서!', `MaleText_loc4`='我们已经没有护卫了，准备交叉火力射击。赶快，赶快！', `MaleText_loc5`='我們沒有護衛了。我要看到火力網。快點，快點!', `MaleText_loc7`='No tenemos escolta. Quiero áreas de fuego entrelazadas. ¡Ya, ya!' WHERE `ID`=42210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\spell_fire_selfdestruct.blp:20|t눈먼 용이 몸을 곧추세우고 |cFFFF0000이글거리는 불길|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t盲眼巨龙跳向后方，开始施放|cFFFF0000灼热烈焰！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t盲龍昂首準備使出|cFFFF0000灼熱烈焰!|r', `MaleText_loc7`='|TInterfaceIconsspell_fire_selfdestruct.blp:20|tEl dragón ciego se echa hacia atrás y lanza ¡|cFFFF0000Llamas abrasadoras|r!' WHERE `ID`=42211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 자식이.', `MaleText_loc4`='胜利者。', `MaleText_loc5`='勝利者。', `MaleText_loc7`='Un ganador.' WHERE `ID`=42212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카심, 피의 의식을 시작하고 싶습니다.', `MaleText_loc4`='我准备开始鲜血仪式了，卡西姆。', `MaleText_loc5`='卡辛，我想要開始進行血之祭儀。', `MaleText_loc7`='Me gustaría comenzar el ritual de sangre, Kasim.', `FemaleText_loc1`='카심, 피의 의식을 시작하고 싶어요.', `FemaleText_loc4`='我准备开始鲜血仪式了，卡西姆。', `FemaleText_loc5`='卡辛，我想要開始進行血之祭儀。', `FemaleText_loc7`='Me gustaría comenzar el ritual de sangre, Kasim.' WHERE `ID`=42213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 물러나라고... 지저분해지는 일이니 말이야.', `MaleText_loc4`='很好。退后……别弄得你满身都是。', `MaleText_loc5`='很好。站後面點...接下來可能會有點混亂。', `MaleText_loc7`='Muy bien. Échate atrás... esto puede ponerse muy feo.' WHERE `ID`=42214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 의식을 마쳤어... 이제 그 아뮬렛 셋이 어디에서 자네를 기다리는지 보여.', `MaleText_loc4`='鲜血仪式已经完成……现在我能看到有三个护符在等着你。', `MaleText_loc5`='鮮血儀式完成了...我現在知道三個護符在哪等待你。', `MaleText_loc7`='El ritual de sangre ha concluido... Y ya puedo ver dónde te esperan los tres amuletos.' WHERE `ID`=42215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카심, 아뮬렛 의식을 시작하고 싶습니다.', `MaleText_loc4`='我准备开始护符仪式了，卡西姆。', `MaleText_loc5`='卡辛，我想要開始進行護符儀式。', `MaleText_loc7`='Me gustaría comenzar el ritual del amuleto, Kasim.', `FemaleText_loc1`='카심, 아뮬렛 의식을 시작하고 싶어요.', `FemaleText_loc4`='我准备开始护符仪式了，卡西姆。', `FemaleText_loc5`='卡辛，我想要開始進行護符儀式。', `FemaleText_loc7`='Me gustaría comenzar el ritual del amuleto, Kasim.' WHERE `ID`=42216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라젤리크의 아뮬렛 안에 담긴 힘으로...', `MaleText_loc4`='以拉瑟莱克护符内的强大力量……', `MaleText_loc5`='擁有了拉瑟萊克護符中的力量後...', `MaleText_loc7`='¡Con el poder de estos amuletos de Razelikh...' WHERE `ID`=42217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그대를 라젤리크의 보금자리로 잇노라!', `MaleText_loc4`='……我将你缚于他的巢穴中！', `MaleText_loc5`='...將你束縛到他的巢穴!', `MaleText_loc7`='¡... te confino a su guarida!' WHERE `ID`=42218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 돌리고 기침을 두 번 해보라고.', `MaleText_loc4`='转头，咳嗽两次。', `MaleText_loc5`='把頭轉過來然後咳兩下。', `MaleText_loc7`='Vuelve la cabeza y tose dos veces.' WHERE `ID`=42219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 것을 보고, 그런 일을 해내고도 목숨이 붙어 있다니... 난 정말 운 좋은 노움이야.', `MaleText_loc4`='见过我所见过的那些，做过我所做过的那些，而现在还能呼吸……我真是个幸运的侏儒。', `MaleText_loc5`='見識了我見識過的東西，做了我做過的事情，然後竟然還活著...我真是個幸運的地精。', `MaleText_loc7`='Haber podido ver las cosas que he visto, hacer las cosas que he hecho, y seguir vivo... Soy un gnomo con suerte.' WHERE `ID`=42220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 또 뭐야?', `MaleText_loc4`='怎么？怎么啦？！', `MaleText_loc5`='什麼跟什麼!?', `MaleText_loc7`='¡¿Que QUÉ?!' WHERE `ID`=42221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포 쏴, 대포 쏘라고! 가진 건 전부 쏴 버려!', `MaleText_loc4`='那些炮！别让它们闲着！有什么打什么！', `MaleText_loc5`='砲台呢，砲台快來人! 把我們能用的全射出去!', `MaleText_loc7`='¡A las armas, a las armas! ¡Disparen con todo!' WHERE `ID`=42222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기습이다!', `MaleText_loc4`='被攻击了！', `MaleText_loc5`='我們被攻擊了!', `MaleText_loc7`='¡Es un ataque!' WHERE `ID`=42223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 완전히 피바다인데요, 반장님. 모두 살해된 것 같습니다.', `MaleText_loc4`='真是场惨祸啊，中尉。他们都被谋杀了。', `MaleText_loc5`='這是一件滅門慘案，中尉。他們都是被人蓄意殺害的。', `MaleText_loc7`='Es un baño de sangre, teniente. Han sido asesinados.' WHERE `ID`=42224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신체 온도를 보면 숨이 끊어진 지 채 6시간이 지나지 않은 것 같습니다.', `MaleText_loc4`='根据体温判断，我敢说他们的死亡时间不超过6小时。', `MaleText_loc5`='從他們的體溫來看，我敢說他們死亡尚未超過6小時。', `MaleText_loc7`='Según la temperatura del cuerpo, yo diría que no llevan muertos más de 6 horas.' WHERE `ID`=42225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은말 블랑쉬에게 이런 짓을...', `MaleText_loc4`='他们居然对老马布兰契做出这种事……', `MaleText_loc5`='真為他們對老馬布蘭契所做的感到悲哀...', `MaleText_loc7`='Es una vergüenza lo que le han hecho a la Vieja Blanchy.' WHERE `ID`=42226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난이 아닌데...', `MaleText_loc4`='不是开玩笑，菜鸟……', `MaleText_loc5`='我同意，菜鳥...', `MaleText_loc7`='No se andan con bromas, novato...' WHERE `ID`=42227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 잃고 외양간 고친다던데...', `MaleText_loc4`='看来他们真把推车放在了……', `MaleText_loc5`='看來他們還真的是本末倒置，把車子擺在...', `MaleText_loc7`='Parece ser que pusieron la carreta...' WHERE `ID`=42228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...이제와서 말해봤자.', `MaleText_loc4`='……马前面。', `MaleText_loc5`='...馬兒前面了。', `MaleText_loc7`='... delante del caballo.' WHERE `ID`=42229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건 작전은 성공적이었네. 물론 그 비열한 텔마플러그가 뜻밖의 속임수를 가지고 있긴 했지만, 결국 그를 도망치도록 만들었지 않은가! 이제 놈리건을 깨끗하게 정화해 다시 우리 손에 넣는 건 시간문제일 뿐이네!', `MaleText_loc4`='诺莫瑞根行动取得了成功。当然，那个卑鄙的瑟玛普拉格使出了让人出乎意料的一招，但我们还是把他赶跑了！诺莫瑞根很快就会被肃清，重新回到我们的手中，这只是时间问题！', `MaleText_loc5`='行動:諾姆瑞根是個大成功。是的，雖然那個渾蛋瑟瑪普拉格將了我們一軍，但他已經被我們逼到逃亡了!諾姆瑞根被清空然後重新回到我們手上只是時間上的問題!', `MaleText_loc7`='Operación: Gnomeregan fue todo un éxito. Es cierto que ese cobarde de Termochufe guardaba un as en la manga, ¡pero le hicimos huir! ¡Es solo cuestión de tiempo que hagamos limpieza en Gnomeregan y la ciudad vuelva a nuestras manos!' WHERE `ID`=42230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채집 중', `MaleText_loc4`='收获中', `MaleText_loc5`='收割中', `MaleText_loc7`='Cosechando', `FemaleText_loc1`='채집 중', `FemaleText_loc4`='收获中', `FemaleText_loc5`='收割中', `FemaleText_loc7`='Cosechando' WHERE `ID`=42231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕을 위해 요리하는 건 영예지 일이 아니오. 나를 도와 심부름을 좀 해줄 시간이 되겠소?', `MaleText_loc4`='为国王料理膳食是份荣耀，可不是工作。你有时间帮我跑跑腿儿吗？', `MaleText_loc5`='為國王烹飪是個榮譽，不是工作。你有時間來幫我一把嗎?', `MaleText_loc7`='Cocinar para el rey es un honor, no un trabajo. ¿Tienes tiempo para ayudarme con unos cuantos recados?', `FemaleText_loc1`='왕을 위해 요리하는 건 영예지 일이 아니오. 나를 도와 심부름을 좀 해줄 시간이 되겠소?', `FemaleText_loc4`='为国王料理膳食是份荣耀，可不是工作。你有时间帮我跑跑腿儿吗？', `FemaleText_loc5`='為國王烹飪是個榮譽，不是工作。你有時間來幫我一把嗎?', `FemaleText_loc7`='Cocinar para el rey es un honor, no un trabajo. ¿Tienes tiempo para ayudarme con unos cuantos recados?' WHERE `ID`=42232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 멈춰선 안 됩니다, $n. 배신자 텔마플러그를 영원히 없애버릴 그날을 위해 모든 노움들은 철저히 훈련해야 합니다.', `MaleText_loc4`='训练一刻都不能停，$n。我要每个侏儒都做好准备，等到我们将叛徒瑟玛普拉格彻底干掉的那天，都能大展拳脚！', `MaleText_loc5`='訓練絕對不能鬆懈，$n。等我們準備對瑟瑪普拉格發動最後總攻擊的時候，我希望每一位地精都做好戰鬥的準備。', `MaleText_loc7`='Nunca dejes de instruirte, $n. Quiero que todos y cada uno de los gnomos estén preparados para el día en el que eliminemos a ese traidor de Termochufe para siempre.' WHERE `ID`=42233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈리건 작전이 끝난 후, 대부분의 사람들은 쉴 시간을 갖게 되었죠. 그렇지만 저와 제 조수는 안심지대 동료들이 도시 안에서 구출해온 생존자들과 부상자들을 돌봐오고 있었답니다.', `FemaleText_loc4`='诺莫瑞根行动的结束对大多数人来说意味着终于有了喘息的机会。然而我的助手和我却一直忙于救治那些救援人员从城里救出的伤病员和幸存者。', `FemaleText_loc5`='「行動: 諾姆瑞根」已經告一段落，大多數人都在休息，養精蓄銳。 但是我和我的助理們卻一點喘息的機會也沒有，一直在忙著照顧S.A.F.E.團隊從城裡頭救出來的傷患。', `FemaleText_loc7`='El final de la Operación: Gnomeregan supuso una oportunidad de descansar para mucha gente. Sin embargo, mis ayudantes y yo hemos estado cuidando de los heridos y los supervivientes que los equipos de S.E.G.U.R.O. rescataron del interior de la ciudad.' WHERE `ID`=42234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 네더가드는 좀 답답하게 돌아가지요. 가끔 드워프는 임무를 잠시라도 잊을 수 있는 한 잔이 필요하답니다.', `FemaleText_loc4`='守望堡有时真是闷得够呛。有时一个矮人需要的只是一杯啤酒，让她的脑袋换换气儿！', `FemaleText_loc5`='守望堡這並不是一個很有趣的地方。一個矮人有時必須來點酒精讓她輕鬆一下。', `FemaleText_loc7`='El ambiente puede estar un poco cargado en Negthergarde. A veces una enana necesita una cerveza para evadirse del trabajo por un momento.' WHERE `ID`=42235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 쉬고 있었을 뿐이네. 계속 감시하는 게 보기보다 쉬운 일은 아니거든.', `MaleText_loc4`='我只是稍事休息。永恒地坚守并不像听上去那么容易，$r。', `MaleText_loc5`='我只是休息了一下。做個「永恆看守者」不像說的那麼簡單，$r。', `MaleText_loc7`='Estaba descansando. La guardia eterna no es tan fácil como suena, $r.' WHERE `ID`=42236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고레크로 돌아가십시오!', `MaleText_loc4`='回到拉葛雷克那里去！', `MaleText_loc5`='返回勒苟雷克!', `MaleText_loc7`='¡Vuelve con L''ghorek!' WHERE `ID`=42237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에루낙, 이걸 좀 보세요. 전에 말씀드렸던 환영 마법에 쓸 만한 중심체가 될 것 같아요.', `FemaleText_loc4`='埃鲁纳克，来看看这个。还记得我跟你说过的视象法术吗？这看起来像是个有力的证据。', `FemaleText_loc5`='伊魯納克，來看一下這個。這個應該可以當作我提過的那個影像魔法的施法焦點。', `FemaleText_loc7`='Erunak, échale un vistazo a esto. Podría ser un foco suficiente para las magias de visión de las que te hablaba.' WHERE `ID`=42238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에루낙이 조각을 살펴보고는 끄덕이며 동의합니다.', `MaleText_loc4`='埃鲁纳克检视着碎片，认同地点了点头。', `MaleText_loc5`='伊魯納克調查了碎片後點頭同意。', `MaleText_loc7`='Erunak examina el fragmento y asiente para mostrar su acuerdo.', `FemaleText_loc1`='에루낙이 조각을 살펴보고는 끄덕이며 동의합니다.', `FemaleText_loc4`='埃鲁纳克检视着碎片，认同地点了点头。', `FemaleText_loc5`='伊魯納克調查了碎片後點頭同意。', `FemaleText_loc7`='Erunak examina el fragmento y asiente para mostrar su acuerdo.' WHERE `ID`=42239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 지금 바로 마법을 준비할게요. 나가의 목적과 수법에 대해 드디어 알게 될지도 모르겠군요.', `FemaleText_loc4`='那我这就准备施法。这也许总算能让我们对纳迦的手段和意图有所了解。', `FemaleText_loc5`='我們立刻開始進行施法的準備工作。這或許可以讓我們對納迦的目的和計畫總算有所瞭解。', `FemaleText_loc7`='Entonces prepararé el encantamiento ahora mismo. Quizá esto por fin arroje un poco de luz sobre los objetivos y las intenciones de los nagas.' WHERE `ID`=42240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구는 안전하다! 이제 다른 지역의 안전을 확보하라!', `MaleText_loc4`='贸易区守住了！现在，守住城市的其它部分！', `MaleText_loc5`='貿易區已經安全了!現在，保護城市其他的地方!', `MaleText_loc7`='¡El Distrito de Mercaderes está a salvo! ¡Ahora, debemos hacer lo mismo con el resto de la ciudad!' WHERE `ID`=42241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법사 지구의 안전을 확보했어요! 침략자들을 모두 쫓아냈고, 주민들도 모두 안전한 곳으로 이동했어요!', `FemaleText_loc4`='我们守住了法师区！所有入侵者都已被击退，撤离也已顺利完成！', `FemaleText_loc5`='法師區已經安全了!所有侵略者都被擊退，疏散行動也已經完成了!', `FemaleText_loc7`='¡El Barrio de los Magos está a salvo! Hemos repelido a todos los invasores y la evacuación ha sido completada!' WHERE `ID`=42242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, $n. 제가 당신에게 마법사들이 사용하는 주문을 가르쳐 드릴 수 있답니다.', `FemaleText_loc4`='你好啊，$n。我可以对你进行法师方面的训练。', `FemaleText_loc5`='你好，$n。我可以教導你法師的知識。', `FemaleText_loc7`='Saludos, $n. Puedo ofrecerte instrucción en las artes de un mago.' WHERE `ID`=42243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드가 대성당 광장을 탈환했소. 빛은 항상 승리한다오!', `MaleText_loc4`='教堂区又归暴风城控制了！圣光之力永胜！', `MaleText_loc5`='教堂區再次歸暴風城所有。聖光是不滅的!', `MaleText_loc7`='El Distrito de la Catedral vuelve a estar bajo el control de Ventormenta. ¡La Luz siempre prevalece!' WHERE `ID`=42244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송해요, $c님, 저는 당신을 도와드릴 수 없어요. $c 전문 상급자를 찾아보시는 게 좋겠어요.', `FemaleText_loc4`='对不起，$c，我帮不了你。你得去找$c训练师。', `FemaleText_loc5`='很抱歉，$c，我無法幫你。你必須找一位$c訓練師。', `FemaleText_loc7`='Lo siento, $c, no puedo ayudarte. Tendrás que buscar un instructor de $c.' WHERE `ID`=42245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 도둑놈아, 썩 꺼지지 못해!', `MaleText_loc4`='滚开，联盟渣滓！', `MaleText_loc5`='滾回去，聯盟小偷!', `MaleText_loc7`='¡Largo, ladrón de la Alianza!', `FemaleText_loc1`='얼라이언스 도둑놈아, 썩 꺼지지 못해!', `FemaleText_loc4`='滚开，联盟渣滓！', `FemaleText_loc5`='滾回去，聯盟小偷!', `FemaleText_loc7`='¡Largo, ladrón de la Alianza!' WHERE `ID`=42246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다. 제가 가르쳐 드릴 수 있는 게 없군요.', `MaleText_loc4`='对不起，我无法对你进行训练。', `MaleText_loc5`='抱歉，我無法訓練你。', `MaleText_loc7`='Lo siento, no puedo ofrecerte instrucción.' WHERE `ID`=42247;
