UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물들에게 스톰윈드의 힘을 보여주어라!', `MaleText_loc4`='让这群怪物见识下暴风城的力量，$n！', `MaleText_loc5`='$n，讓這些怪物看看暴風城的利害!', `MaleText_loc7`='¡Muestra a esos monstruos el poder de Ventormenta, $n!', `FemaleText_loc1`='이 괴물들에게 스톰윈드의 힘을 보여주세요, $n!', `FemaleText_loc4`='让这群怪物见识下暴风城的力量，$n！', `FemaleText_loc5`='$n，讓這些怪物看看暴風城的利害!', `FemaleText_loc7`='¡Muestra a esos monstruos el poder de Ventormenta, $n!' WHERE `ID`=42250;
