UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아니군, $n!', `MaleText_loc4`='看来你这强大$c的名头可真是名不虚传啊，$n！', `MaleText_loc5`='看來你身為一個優秀的$c果然名不虛傳，$n!', `MaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!', `FemaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아니군요, $n!', `FemaleText_loc4`='看来你这强大$c的名头可真是名不虚传啊，$n！', `FemaleText_loc5`='看來你身為一個優秀的$c果然名不虛傳，$n!', `FemaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!' WHERE `ID`=42253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 기술이 인상적이군, $n.', `MaleText_loc4`='你的作战技巧令人印象深刻，$n。', `MaleText_loc5`='你的戰鬥技巧令人嘆為觀止，$n。', `MaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.', `FemaleText_loc1`='전투 기술이 인상적이군요, $n.', `FemaleText_loc4`='你的作战技巧令人印象深刻，$n。', `FemaleText_loc5`='你的戰鬥技巧令人嘆為觀止，$n。', `FemaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.' WHERE `ID`=42254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n처럼 강력한 $c|1이;가; 지키고 있는데 스톰윈드가 어떻게 무너지겠는가! 스톰윈드를 위하여!', `MaleText_loc4`='有像$n一样的$c守卫，暴风城怎么会陷落？为了暴风城！', `MaleText_loc5`='有$n這樣的$c協助我們防守，暴風城有可能會淪陷嗎?為了暴風城!', `MaleText_loc7`='¿Cómo puede caer Ventormenta si tenemos a $n y a los de su clase para defenderla? ¡POR VENTORMENTA!', `FemaleText_loc1`='$n 님처럼 강력한 $c|1이;가; 지키고 있는데 스톰윈드가 어떻게 무너지겠나요? 스톰윈드를 위하여!', `FemaleText_loc4`='有像$n一样的$c守卫，暴风城怎么会陷落？为了暴风城！', `FemaleText_loc5`='有$n這樣的$c協助我們防守，暴風城有可能會淪陷嗎?為了暴風城!', `FemaleText_loc7`='¿Cómo puede caer Ventormenta si tenemos a $n y a los de su clase para defenderla? ¡POR VENTORMENTA!' WHERE `ID`=42255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 없는 동안에 그들이 공격해 왔습니다... 부대장님은 놈들과 싸우다 퇴각하셨습니다. 남은 병력은 동굴로 후퇴했으니, 당신도 어서 대피하셔야 합니다.', `MaleText_loc4`='他们在你离开时发动了攻击……首领在战斗中倒下了。其它人都退进了洞里，你也应该这么做。', `MaleText_loc5`='你不在的時候我們遭受了攻擊...隊長在對抗中喪生了。剩下的人都撤退到了洞窟中，你也應該如此。', `MaleText_loc7`='Atacaron mientras no estabas... El capitán murió luchando. Los demás se retiraron a la cueva. Tú deberías hacer lo mismo.' WHERE `ID`=42256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맑은 공기! 빛이여, 이게 그리웠지. 북으로 향하는 배가 시야에 들어왔소. $n, 그쪽으로 신호탄을 쏘시오.', `MaleText_loc4`='新鲜的空气！以圣光的名义，我想念它。我看见在我们的北边有几艘船，$n——快朝他们的方向发射信号弹！', `MaleText_loc5`='新鮮的空氣!以聖光之名，我錯過了。有些船出現在我們北方的視野中，$n。朝他們的方向發射閃光彈。', `MaleText_loc7`='¡Aire fresco! Por la Luz, lo echaba de menos. Tenemos algunos barcos a la vista hacia el norte, $n. Dispara la bengala en aquella dirección.' WHERE `ID`=42257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맑은 공기! 그롬의 수염이여, 이게 그리웠지. 북으로 향하는 배가 시야에 들어왔네. $n, 그쪽으로 신호탄을 쏘게.', `MaleText_loc4`='新鲜的空气！以格罗姆胡须的名义，我想念它。我看见在我们的北边有几艘船，$n——快朝他们的方向发射信号弹！', `MaleText_loc5`='新鮮空氣!地獄吼的鬍子啊，真是有夠懷念的。我們的船就在北邊視線範圍之內的地方，$n，朝那個方向發射信號彈。', `MaleText_loc7`='¡Aire fresco! Por la barba de Grom, lo echaba de menos. Tenemos algunos barcos a la vista hacia el norte, $n. Dispara la bengala en aquella dirección.' WHERE `ID`=42258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"아아아아아"라고 해 보라고.', `MaleText_loc4`='说“啊——”。', `MaleText_loc5`='說「啊啊啊啊」。', `MaleText_loc7`='Di "aaaaaaaaah".' WHERE `ID`=42259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번 건강 검진은 언제였지?', `MaleText_loc4`='你上一次体检是在什么时候？', `MaleText_loc5`='你上次檢查是什麼時候?', `MaleText_loc7`='¿Cuándo fue la última vez que te hiciste un chequeo?' WHERE `ID`=42260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓인가? 내 일을 위태롭게 하는구나! 타락의 흉터가 되살아난다면 모두 내 덕이란 말이다!', `MaleText_loc4`='你在干什么？你影响了我的工作！腐烂之痕的重振都是我的功劳！', `MaleText_loc5`='你在做什麼?你威脅了我的作品!腐化之痕的重生都是我的功勞!', `MaleText_loc7`='¿Qué haces? ¡Amenazas mi trabajo! ¡El resurgir de la Escara Impía es obra mía!' WHERE `ID`=42261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물약 2개를 먹고 아침에 날 불러.', `MaleText_loc4`='吃两剂，早上再叫我。', `MaleText_loc5`='拿兩瓶藥水，然後早上再叫我。', `MaleText_loc7`='Tómate dos pociones y llámame por la mañana.' WHERE `ID`=42262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살을 좀 빼야겠는데...', `MaleText_loc4`='你该考虑减减肥了。', `MaleText_loc5`='你應該好好考慮甩掉一些肥肉。', `MaleText_loc7`='Deberías pensar en perder algo de peso.' WHERE `ID`=42263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그저... 무언가 좋은 일을... 하고 싶었을 뿐이었다...', `MaleText_loc4`='我只想要……做点……好事……', `MaleText_loc5`='我只是想要...做點...好事...', `MaleText_loc7`='Yo solo quería.. hacer algo... bueno.' WHERE `ID`=42264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 가기 전에, 너희 모두 노예 아니면 시체가 되리라!', `MaleText_loc4`='今天，你们要么成为奴隶，要么粉身碎骨！', `MaleText_loc5`='在那一日來臨時，你們將全變為奴隸和屍體!', `MaleText_loc7`='¡Antes de que acabe el día, todos serán esclavos y cadáveres!' WHERE `ID`=42265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 또 나가와 잠시 대립하게 되었군요.', `MaleText_loc4`='在这儿又与纳迦短兵相接。', `MaleText_loc5`='另一次與納迦的小規模衝突。', `MaleText_loc7`='Otro breve enfrentamiento con los nagas.' WHERE `ID`=42266;
