UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 벌레야!', `MaleText_loc4`='死吧，虫子！', `MaleText_loc5`='死吧，蟲子!', `MaleText_loc7`='¡Muere, gusano!' WHERE `ID`=42268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 늦어지겠군... 모두 제자리에!', `MaleText_loc4`='麻烦真多…重组阵型！', `MaleText_loc5`='又有耽擱...列隊，弟兄們!', `MaleText_loc7`='Más demoras... ¡Formen, señores!' WHERE `ID`=42269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표가 보이는군. 그대로 전진하라...', `MaleText_loc4`='我们的目标已经在望——前进……', `MaleText_loc5`='我們的目的地就在前面─向前壓進...', `MaleText_loc7`='Tenemos el objetivo a la vista... Continúa...' WHERE `ID`=42270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵튤론의 수하들이 위험합니다! 서둘러야 합니다!', `MaleText_loc4`='耐普图隆的仆从在拼死抵抗！我们得快点！', `MaleText_loc5`='奈普圖隆的手下很危急了!我們得快點!', `MaleText_loc7`='¡Los esbirros de Neptulon se desesperan! ¡Rápido!' WHERE `ID`=42271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우릴 봤다! 준비해라!', `MaleText_loc4`='我们被发现了！准备战斗！', `MaleText_loc5`='我們被發現了!準備作戰!', `MaleText_loc7`='¡Nos encontraron! ¡Prepárense!' WHERE `ID`=42273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈리건 비밀특수부대의 켈시 스틸스파크예요. 무슨 일이든 말씀만 하세요! 도적 훈련을 받을 곳을 찾고 있다면 잘 찾아 오신 거예요.', `FemaleText_loc4`='诺莫瑞根隐秘行动组织的凯尔希·钢烁为你效劳！要是你想接受潜行者方面的训练，你可来对地方了。', `FemaleText_loc5`='諾姆瑞根特勤隊的凱爾希·鋼火聽候差遣。你如果想接受盜賊訓練，你就來對地方了。', `FemaleText_loc7`='¡Kelsey Chispacero de Operaciones Encubiertas de Gnomeregan, a tu servicio! Si buscas instrucción para pícaros, has venido al lugar adecuado.' WHERE `ID`=42274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송해요, 제가 가르쳐 드릴 수 있는 게 없어요. 당신이 사용하는 기술을 조금 더 익숙하게 사용하는 다른 훈련 교관을 찾아보세요.', `FemaleText_loc4`='很抱歉，我不能对你进行训练。你得去找更熟悉你技能的训练师。', `FemaleText_loc5`='抱歉，我無法訓練你。你必須找熟悉你的技巧的訓練師。', `FemaleText_loc7`='Lo siento, no puedo ofrecerte instrucción. Tendrás que buscar a alguien que esté más familiarizado con tus habilidades.' WHERE `ID`=42275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 다시 만나 반가워요. 생각보다 오래 걸렸네요. 유용한 정보를 얻으셨나요?', `FemaleText_loc4`='欢迎回来，$n。你去得比我预想的要久。了解到什么有用的信息了吗？', `FemaleText_loc5`='歡迎你回來，$n。時間比我預期的還久。有探聽到什麼有用的消息嗎?', `FemaleText_loc7`='Me alegro de verte de nuevo, $n. Te ha llevado más tiempo de lo esperado. ¿Has aprendido algo útil?' WHERE `ID`=42276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에루낙! 이럴 시간이 없습니다...', `MaleText_loc4`='埃鲁纳克！我们没时间做这个……', `MaleText_loc5`='伊魯納克!我們沒時間磨蹭了...', `MaleText_loc7`='¡Erunak! No tenemos tiempo para esto...' WHERE `ID`=42277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 우리를 공격한다! 잠수함 문을 부수려고 하고 있어! 배 위쪽을 방어해라!', `MaleText_loc4`='我们被纳迦围攻了，他们想要破坏我们的气闸！守住船的上舷！', `MaleText_loc5`='納迦想透過摧毀風閘攻進我們這!防禦船的上部!', `MaleText_loc7`='¡Los nagas nos asedian e intentan entrar por las esclusas de aire! ¡Defended las cubiertas!' WHERE `ID`=42278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린! 상황 보고!', `MaleText_loc4`='地精！进度报告！', `MaleText_loc5`='哥布林!狀況報告!', `MaleText_loc7`='¡Goblin! ¡Informe!' WHERE `ID`=42279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해저를 향해 포격을 계속하라! 나가에게 호드의 위력을 보여주자!', `MaleText_loc4`='继续轰击洋底！让那些纳迦看看部落的力量！', `MaleText_loc5`='繼續轟炸海床!讓那些納迦知道部落的厲害!', `MaleText_loc7`='¡Continuad con el bombardeo del lecho oceánico! ¡Mostradles a esos nagas el poder la Horda!' WHERE `ID`=42280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좌현과 우현에는 나가, 뱃머리에선 얼굴 없는 자들이 쳐들어옵니다...! 수적으로 엄청나게 열세이지만, 어쨌든 배는 아직 버티고 있습니다!', `MaleText_loc4`='纳迦从左舷和右舷方向同时发动了攻击！正前方还遭遇到未知目标的突袭……！我们在人数上处于极端劣势，但船还在坚持，长官！', `MaleText_loc5`='納迦正由左舷和右舷發動攻擊!無面者們從正面...!長官，我們的人數比對方少很多，但船還是撐得住!', `MaleText_loc7`='¡Los nagas atacan por babor y estribor! ¡Los ignotos atacan por proa...! ¡Nos superan ampliamente en número, pero el barco aguanta, señor!' WHERE `ID`=42281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 보잘것없는 깡통은 <크라켄 이름>의 힘 앞에서 무력하도다!', `FemaleText_loc4`='在<此处为海怪号的名字>的力量面前，这条破船简直是废铁一块！', `FemaleText_loc5`='這破東西在<Kraken Name here>的力量下將不堪一擊!', `FemaleText_loc7`='¡Ese miserable can no es nada comparado con el poder de <Aquí nombre del kraken>!' WHERE `ID`=42282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공원이 폐허가 되었군요... 오늘은 다른 길로 가야겠습니다. 망할 용 같으니!', `FemaleText_loc4`='花园已经变成了废墟……我们今天得另寻出路了。这该死的龙！', `FemaleText_loc5`='花園已經亂七八糟...我們今天要繞道了。不幸的龍啊!', `FemaleText_loc7`='El Parque está destrozado... Hoy tendremos que ir por otro lado. ¡Dragón miserable!' WHERE `ID`=42283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 더 온다! 긴장해라!', `MaleText_loc4`='更多的纳迦！当心！', `MaleText_loc5`='更多的納迦!做好準備!', `MaleText_loc7`='¡Más nagas! ¡Prepárense!' WHERE `ID`=42284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파도여, 고맙습니다. 돌아오셨군요! 다른 사람들은 모두 퇴각했습니다. 우리도 여기서 나가야 해요!', `FemaleText_loc4`='感谢海浪的庇护，你终于回来了！别人都已经撤退，我们得离开这儿！', `FemaleText_loc5`='要謝謝海浪把你帶了回來!其他人已經成功撤離了，我們必須離開這裡!', `FemaleText_loc7`='¡Gracias a las olas que has vuelto! ¡Los demás ya se han retirado, tenemos que salir de aquí!' WHERE `ID`=42285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고레크가 죽습니다!', `MaleText_loc4`='拉葛雷克死了！', `MaleText_loc5`='勒苟雷克死亡了!', `MaleText_loc7`='¡L''ghorek muere!' WHERE `ID`=42286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러, $n! 라젤리크가 돌아오기 전까지 시간이 얼마 남지 않았다고.', `MaleText_loc4`='动作快，$n！我们没多少时间，拉瑟莱克很快就会回来。', `MaleText_loc5`='快點，$n!我們沒有多少時間，拉瑟萊克就快要回來了。', `MaleText_loc7`='¡Rápido, $n! No tenemos mucho tiempo antes de que Razelikh regrese.' WHERE `ID`=42287;
