UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어린 바위웅덩이 멀록들이 바다로 향합니다.>', `MaleText_loc4`='<这群岩池鱼人宝宝朝海洋的方向看去。>', `MaleText_loc5`='<這些石塘魚人寶寶朝海洋的方向看去。>', `MaleText_loc7`='<Esos bebés de múrloc Pozarroca miran hacia el océano.>' WHERE `ID`=42289;
