UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 주민 여러분! 도시를 비우십시오!', `MaleText_loc4`='暴风城的市民们！开始撤离城市！', `MaleText_loc5`='暴風城的人民!開始撤離這個城市!', `MaleText_loc7`='¡Ciudadanos de Ventormenta! ¡Evacuad la ciudad!', `FemaleText_loc1`='스톰윈드 주민 여러분! 도시를 비우십시오!', `FemaleText_loc4`='暴风城的市民们！开始撤离城市！', `FemaleText_loc5`='暴風城的人民!開始撤離這個城市!', `FemaleText_loc7`='¡Ciudadanos de Ventormenta! ¡Evacuad la ciudad!' WHERE `ID`=42293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 방문객 여러분, 몸을 피할 곳을 찾으십시오!', `MaleText_loc4`='暴风城的宾客们，请在风暴来临前找到栖身之所！', `MaleText_loc5`='暴風城的客人，請在大戰開打前尋找庇護所!', `MaleText_loc7`='¡Invitados de Ventormenta, buscad refugio de la tormenta que se avecina!', `FemaleText_loc1`='스톰윈드 방문객 여러분, 몸을 피할 곳을 찾으세요!', `FemaleText_loc4`='暴风城的宾客们，请在风暴来临前找到栖身之所！', `FemaleText_loc5`='暴風城的客人，請在大戰開打前尋找庇護所!', `FemaleText_loc7`='¡Invitados de Ventormenta, buscad refugio de la tormenta que se avecina!' WHERE `ID`=42294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거리를 비우십시오!', `MaleText_loc4`='清空街道！', `MaleText_loc5`='淨空街道!', `MaleText_loc7`='¡Despejad las calles!', `FemaleText_loc1`='거리를 비우세요!', `FemaleText_loc4`='清空街道！', `FemaleText_loc5`='淨空街道!', `FemaleText_loc7`='¡Despejad las calles!' WHERE `ID`=42295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시를 떠나십시오! 스톰윈드의 거리를 비우십시오!', `MaleText_loc4`='疏散市民！清空暴风城的街道！', `MaleText_loc5`='疏散城市中的人!清空暴風城的街道!', `MaleText_loc7`='¡Evacuad la ciudad! ¡Despejad las calles de Ventormenta!', `FemaleText_loc1`='도시를 떠나세요! 스톰윈드의 거리를 비우세요!', `FemaleText_loc4`='疏散市民！清空暴风城的街道！', `FemaleText_loc5`='疏散城市中的人!清空暴風城的街道!', `FemaleText_loc7`='¡Evacuad la ciudad! ¡Despejad las calles de Ventormenta!' WHERE `ID`=42296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Basta!' WHERE `ID`=42297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 대지 고리회가 잠시 침략을 멈추게 하였다. 하지만 기억하라. 정령은 반드시 돌아올 것이다!', `MaleText_loc4`='够了！大地之环暂时阻止了入侵。但小心点，那些元素会再回来的！', `MaleText_loc5`='夠了!陶土議會可以暫時的阻止這次的入侵。但是你必須知道，元素們會再回來的!', `MaleText_loc7`='¡Ya basta! El Anillo de la Tierra detendrá temporalmente la invasión. Pero están avisados, ¡los elementales volverán!', `FemaleText_loc1`='그만! 대지 고리회가 잠시 침략을 멈추게 하였다. 하지만 기억하라. 정령은 반드시 돌아올 것이다!', `FemaleText_loc4`='够了！大地之环暂时阻止了入侵。但小心点，那些元素会再回来的！', `FemaleText_loc5`='夠了!陶土議會可以暫時的阻止這次的入侵。但是你必須知道，元素們會再回來的!', `FemaleText_loc7`='¡Ya basta! El Anillo de la Tierra detendrá temporalmente la invasión. Pero están avisados, ¡los elementales volverán!' WHERE `ID`=42298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러야 합니다! 정령들은 오래 버티지 못할 겁니다.', `MaleText_loc4`='我们必须快点！元素无法抵挡这样的攻击。', `MaleText_loc5`='我們必須快點!元素無法抵擋這樣的攻勢!', `MaleText_loc7`='¡Debemos apurarnos! Los elementales no soportarán este asedio.' WHERE `ID`=42299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보같이 우리 바다에 흙발을 들이다니, 어리석은 얼라이언스 놈들. 폭풍의 채찍을 받아라!', `FemaleText_loc4`='你们愚蠢地侵入了我们的水域，联盟的傻瓜们。接受我风暴的鞭笞吧！', `FemaleText_loc5`='你們愚昧地侵入了我們的海域，愚蠢的聯盟。被我的狂浪鞭打吧!', `FemaleText_loc7`='Os habéis adentrado estúpidamente en nuestras aguas, idiotas de la Alianza. ¡Os borraré de la faz de la tierra con el azote de mi tormenta!' WHERE `ID`=42300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아, 손님이 오셨군!', `FemaleText_loc4`='啊，有客——人！', `FemaleText_loc5`='啊，有訪客!', `FemaleText_loc7`='¡Aaa, visitantesss!' WHERE `ID`=42301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오... 이런 깜짝 선물을 봤나.', `FemaleText_loc4`='真是个意外的惊喜。', `FemaleText_loc5`='這真是一個驚喜啊。', `FemaleText_loc7`='Qué sssorpresa inesssperada.' WHERE `ID`=42302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부디 저를 용서하시길... 직접 놀아 드릴 시간이 없군요.', `FemaleText_loc4`='请原谅……我没时间陪你们找乐子了。', `FemaleText_loc5`='不好意思...我沒有時間待在這裡玩耍。', `FemaleText_loc7`='Disssculpa... No tengo tiempo para esssto.' WHERE `ID`=42303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 저 대신 제 종들이 여러분을... 보살펴 줄 겁니다.', `FemaleText_loc4`='我走之后，我的仆人……会满足你们的需求的。', `FemaleText_loc5`='我不在的時候，我的僕人們將會...滿足你的需求。', `FemaleText_loc7`='En mi ausssencia, Mis sssirvientess te... atenderán.' WHERE `ID`=42304;
