UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 필요한 거라도 있으십니까?', `MaleText_loc4`='你需要什么吗，$g老兄:女士;？', `MaleText_loc5`='需要什麼嗎，$g老兄:小姐;?', `MaleText_loc7`='¿Necesitas algo $gchaval:señora;?' WHERE `ID`=42307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 게 있으시다면, 제가 구해다 드릴 수 있지요...', `MaleText_loc4`='不管你要什么，我都有……', `MaleText_loc5`='你要什麼，我就有什麼...', `MaleText_loc7`='Cualquier cosa que necesites, yo puedo conseguirla...' WHERE `ID`=42308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷 멋진데요? 돈 좀 있어 보여요.', `MaleText_loc4`='好东西。你肯定很有钱。', `MaleText_loc5`='好貨色。你一定很有錢。', `MaleText_loc7`='Eso es bueno. Debes ser rico.' WHERE `ID`=42309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 뭐하러 오셨습니까? 설마 빈민가에 산책이라도 오신 겁니까?', `MaleText_loc4`='你在这儿干什么？体验苦日子吗？', `MaleText_loc5`='你來這個地方幹啥?來鬼混嗎?', `MaleText_loc7`='¿Qué haces aquí? ¿De visita por los barrios pobres?' WHERE `ID`=42310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요하신 게 있으십니까? 정보라고요? 저도 가지고 있습니다!', `MaleText_loc4`='你想要什么？消息？这我也有！', `MaleText_loc5`='你要啥?情報?我一樣也有!', `MaleText_loc7`='¿Qué necesitas? ¿Información? ¡De eso también tengo!' WHERE `ID`=42311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...특별한 물건을 찾고 계십니까?', `MaleText_loc4`='你在找更有……异域风情的东西吗？', `MaleText_loc5`='想要找點...不一樣的?', `MaleText_loc7`='¿Acaso buscas algo más... exótico?' WHERE `ID`=42312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 말이 좀 통할 것 같군요.', `MaleText_loc4`='我想我们能做笔交易。', `MaleText_loc5`='我想我們應該做得成生意。', `MaleText_loc7`='Creo que podemos hacer negocios.' WHERE `ID`=42313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 더 숙이고 말씀하십시오.', `MaleText_loc4`='往这儿瞧瞧，$g老兄:女士;。', `MaleText_loc5`='把頭壓低一點，$g老兄:小姐;。', `MaleText_loc7`='No llames mucho la atención $gcolega:señora;.' WHERE `ID`=42314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 쉽게 죽지 않는다, 바다 마녀야!', `MaleText_loc4`='海巫，我们没那么容易对付！', `MaleText_loc5`='我們不會輕易死掉的，海巫!', `MaleText_loc7`='¡No morimos tan fácilmente, bruja!' WHERE `ID`=42315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 죽을 때는, 밉살스러운 적들을 해치우고 자랑스럽게 죽을 걸세!', `MaleText_loc4`='就算我们要死，也要带着消灭夙敌的荣耀！', `MaleText_loc5`='就算會死，我們也要死得光榮，也要跟我們痛恨的敵人決一死戰!', `MaleText_loc7`='¡Si tenemos que morir, que sea de forma honorable luchando contra nuestros odiados enemigos!' WHERE `ID`=42316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 무슨 일이라도 났나?', `MaleText_loc4`='这儿究竟发生了什么？', `MaleText_loc5`='這裡到底發生了什麼事情?', `MaleText_loc7`='¿Qué demonios ha sucedido aquí?' WHERE `ID`=42318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가와의 마지막 결전이 다가왔습니다. 승리하지 않으면 심연의 틈에서 괴로워하며 죽을 것입니다.', `MaleText_loc4`='对纳迦的最后一战即将打响。我们将取胜，或在深渊裂口里奋战至死。', `MaleText_loc5`='與納迦的戰爭即將爆發。我們不是在深淵止境獲得勝利就是戰到只剩一兵一卒。', `MaleText_loc7`='La batalla final contra los nagas es inminente. Triunfaremos o moriremos en la Brecha Abisal.' WHERE `ID`=42319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄브라우 일가가 살해됐다는군...', `MaleText_loc4`='看来法布隆一家遭到了杀害……', `MaleText_loc5`='法布隆被人害死了...', `MaleText_loc7`='Parece que los Cejade fueron asesinados...' WHERE `ID`=42320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 우리가 왜 이런 일을 겪어야 하지? 이건 데피아즈단이 날뛰던 때보다 더 심하잖아!', `MaleText_loc4`='我们是怎么了？我们现在比迪菲亚恣意妄为时的状态更糟！', `MaleText_loc5`='這是怎麼回事?我們現在的狀況比迪菲亞盜賊四處肆虐的時候還要糟糕!', `MaleText_loc7`='¿Qué nos ha sucedido? ¡Ahora estamos peor que cuando los Defias se volvieron locos!' WHERE `ID`=42321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 국왕 바리안 린 님도 전혀 도움이 안 되고 말이야...', `MaleText_loc4`='没错。那个瓦里安国王简直一无是处。', `MaleText_loc5`='沒錯。那個瓦里安國王根本是個廢物。', `MaleText_loc7`='Sí. Ese rey Varian no sirve para nada.' WHERE `ID`=42322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 죄를 뒤집어씌우기 전에 어서 여길 떠나자고.', `MaleText_loc4`='我们赶快离开这里吧，不然他们又要归罪到我们头上。', `MaleText_loc5`='還是趕緊離開這裡，下一個才不會輪到我們。', `MaleText_loc7`='Será mejor que nos alejemos antes de que alguien nos endilgue el muerto.' WHERE `ID`=42323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 생각이야.', `MaleText_loc4`='说得对。', `MaleText_loc5`='說得好。', `MaleText_loc7`='Buena idea.' WHERE `ID`=42324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 전투를 시작하기 전에, 우리 앞에 놓인 저 고대 생물 안에서 무슨 일이 일어나고 있는지 알아내어 끝장을 봐야 합니다. 하지만 우리는 할 수 없겠군요.$B$B$n 님, 에루낙 님께 힘을 빌려주십시오.', `MaleText_loc4`='在我们加入最终战斗之前，我们必须对发生在对面那个上古生灵体内的事情做个了断。否则，我们将毫无胜算。$B$B尽全力去帮埃鲁纳克吧，$n。', `MaleText_loc5`='在展開最後決戰之前，我們務必先阻止我們對面那個祖靈生物裡頭所發生的事情。否則的話，我們一點勝算也沒有。$B$B請務必盡全力協助伊魯納克，$n。', `MaleText_loc7`='Antes de que podamos unirnos a la batalla final, debemos asegurarnos de poner fin a lo que sea que sucede en el interior de ese ancestro de ahí enfrente. De lo contrario, no tendremos ni una sola oportunidad.$B$BDebes prestar a Erunak toda tu ayuda, $n.' WHERE `ID`=42325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 앞 협곡에 있는 저 태고의 신은 고레크라 합니다. 뭔가가 저기 기생하고 있군요.$B$B결판을 내지 않으면 우리 모두 파멸할 것입니다!', `MaleText_loc4`='拉葛雷克是位远古之神，就在沟壑的另一侧。他正在受到某种力量的侵扰。$B$B我们必须终结这一切，否则我们谁都活不了！', `MaleText_loc5`='海溝對面那位先祖之神叫做勒苟雷克。祂被某種東西給感染了。$B$B我們一定要阻止這件事情，否則的話我們全部都會滅亡!', `MaleText_loc7`='L''ghorek es el nombre del dios ancestro que se sienta justo al otro lado de la sima. Algo le ha infestado.$B$BDebemos poner fin a esto o iremos directos a nuestra perdición.' WHERE `ID`=42326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다했지만, 나가가 균열을 공격했습니다!$b$b물의 세계를 지켜야 합니다!', `MaleText_loc4`='尽管我们拼尽了全力，纳迦还是对裂口发动了攻击！$B$B必须守住水元素位面！', `MaleText_loc5`='雖然我們做出了努力，納迦還是攻擊了止境!$B$B我們必須守護水之界域!', `MaleText_loc7`='¡A pesar de nuestros mayores esfuerzos, los nagas han atacado la brecha!$B$B¡Debemos defender el plano de agua!' WHERE `ID`=42327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 틈에서 전투가 발발할 기미가 보이오. 쌍집게발호와 함께 도착한 지원군으로 충분하면 좋겠군.', `MaleText_loc4`='在深渊裂口，一场战争正在酝酿。希望与扳钳X2号一起赶来的援军足够抵挡。', `MaleText_loc5`='深淵止境正蘊釀著一場戰爭。希望鉗手X2能帶來足夠的增援人手。', `MaleText_loc7`='Se está organizando una batalla en la Brecha Abisal. Espero que los refuerzos que han llegado con Tenazario X2 sean suficientes.' WHERE `ID`=42328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 들여보내 주십시오!', `MaleText_loc4`='放我们进去！', `MaleText_loc5`='放我們進去!', `MaleText_loc7`='¡Déjanos entrar!', `FemaleText_loc1`='우릴 들여보내 줘요!', `FemaleText_loc4`='放我们进去！', `FemaleText_loc5`='放我們進去!', `FemaleText_loc7`='¡Déjanos entrar!' WHERE `ID`=42329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕을 몰아내자!', `MaleText_loc4`='打倒国王！', `MaleText_loc5`='叫國王下台啦!', `MaleText_loc7`='¡Abajo con el rey!', `FemaleText_loc1`='국왕을 몰아내자!', `FemaleText_loc4`='打倒国王！', `FemaleText_loc5`='叫國王下台啦!', `FemaleText_loc7`='¡Abajo con el rey!' WHERE `ID`=42330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 더러운 상황이 있나!', `MaleText_loc4`='尝尝马粪的滋味！', `MaleText_loc5`='屁啦!', `MaleText_loc7`='¡Este acaballo está agotado!', `FemaleText_loc1`='이런 더러운 상황이 있나!', `FemaleText_loc4`='尝尝马粪的滋味！', `FemaleText_loc5`='屁啦!', `FemaleText_loc7`='¡Este acaballo está agotado!' WHERE `ID`=42331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 권리로 우릴 쫓아내시는 겁니까?', `MaleText_loc4`='你有什么权利不让我们进去？', `MaleText_loc5`='你憑什麼把我們擋在外面?', `MaleText_loc7`='¿Qué derecho tienes a mantenernos al margen?', `FemaleText_loc1`='무슨 권리로 우릴 쫓아내시는 거죠?', `FemaleText_loc4`='你有什么权利不让我们进去？', `FemaleText_loc5`='你憑什麼把我們擋在外面?', `FemaleText_loc7`='¿Qué derecho tienes a mantenernos al margen?' WHERE `ID`=42332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='춥고 배고픕니다! 우릴 도와주십시오!', `MaleText_loc4`='我们又冷又饿！帮帮我们！', `MaleText_loc5`='我們又餓又冷!幫幫我們!', `MaleText_loc7`='¡Tenemos hambre y frío! ¡Ayúdanos!', `FemaleText_loc1`='춥고 배고파요! 우릴 도와주세요!', `FemaleText_loc4`='我们又冷又饿！帮帮我们！', `FemaleText_loc5`='我們又餓又冷!幫幫我們!', `FemaleText_loc7`='¡Tenemos hambre y frío! ¡Ayúdanos!' WHERE `ID`=42333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비정한 놈들 같으니라고!', `MaleText_loc4`='没心没肺的怪物！', `MaleText_loc5`='死沒良心的混蛋!', `MaleText_loc7`='¡Monstruos sin corazón!', `FemaleText_loc1`='비정한 놈들 같으니라고!', `FemaleText_loc4`='没心没肺的怪物！', `FemaleText_loc5`='死沒良心的混蛋!', `FemaleText_loc7`='¡Monstruos sin corazón!' WHERE `ID`=42334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 모두를 위한 정의와 평등입니까?', `MaleText_loc4`='这就叫人人享有平等与公正？', `MaleText_loc5`='這樣對大家公平、公正嗎?', `MaleText_loc7`='¿Acaso esto es igualdad y justicia para todos?', `FemaleText_loc1`='이게 모두를 위한 정의와 평등인가요?', `FemaleText_loc4`='这就叫人人享有平等与公正？', `FemaleText_loc5`='這樣對大家公平、公正嗎?', `FemaleText_loc7`='¿Acaso esto es igualdad y justicia para todos?' WHERE `ID`=42335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 뭘 어쩔 수 있겠습니까?', `MaleText_loc4`='你还想要我们怎么样？', `MaleText_loc5`='不然你要我們怎麼做?', `MaleText_loc7`='¿Qué esperas que hagamos?', `FemaleText_loc1`='우리가 뭘 어쩔 수 있을까요?', `FemaleText_loc4`='你还想要我们怎么样？', `FemaleText_loc5`='不然你要我們怎麼做?', `FemaleText_loc7`='¿Qué esperas que hagamos?' WHERE `ID`=42336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 틈에서 최후의 결전을 시작하기 전까지는, 우리 앞에 놓인 고대 존재의 몸 안에서 일어나는 일들을 막아야 하네. 그러지 않으면 이길 수 없으니까.$B$B에루낙에게 힘을 빌려주게, $n.', `MaleText_loc4`='在我们加入深渊裂口的最终战斗之前，我们必须终结在对面那上古生灵体内所发生的一切。否则，我们都将失败。$B$B尽全力去帮埃鲁纳克吧，$n。', `MaleText_loc5`='在我們展開深淵止境的最後決戰之前，我們務必先阻止對面那先祖裡頭所發生的事情。否則的話，我們必定會失敗$B$B請你務必盡全力協助伊魯納克，$n。', `MaleText_loc7`='Antes de que podamos unirnos a la batalla final en la Brecha Abisal, debemos detener lo que sea que suceda en el interior de ese ancestro de ahí enfrente. De lo contrario, fracasaremos.$B$BDebes prestar a Erunak toda tu ayuda, $n.' WHERE `ID`=42337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가와의 마지막 전투가 시작되었네. 놈들을 말살하거나, 아니면 심연의 틈에서 싸우다 명예롭게 죽는 걸세.', `MaleText_loc4`='对纳迦的最后一战已经打响。我们将根除他们，或在深渊裂口里光荣地奋战至死。', `MaleText_loc5`='與納迦的最終之戰已經開始。我們不是摧毀他們就是光榮地戰死在深淵止境。', `MaleText_loc7`='La batalla final contra los nagas ha comenzado. Los destruiremos o moriremos gloriosamente en el intento en la Brecha Abisal.' WHERE `ID`=42338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 생각에는 말이지, 해군에서 이 쌈박질을 해결해야 한다고 보오.$B$B우리 모두가 죽기 전에 밖에서 춤이나 출 때라는 거라오.$B$B내 말 무슨 뜻인지 알겠소, 친구?', `FemaleText_loc4`='要是你问我的话，我认为让那些汤羹和肉汁去充数就够了。$B$B趁我们还没变成烤面包之前，应该纵身从这儿逃出去。$B$B你明白我的意思吗，宝贝儿？', `FemaleText_loc5`='要我說啊，我想還是讓那些海軍仔去拖堵就好。$B$B我們最好閃快一點，撇遠一點，省得一起葛屁。$B$B了不了啊，寶貝?', `FemaleText_loc7`='Si quieres saber mi opinión, yo diría que dejemos que el aceite y el agua se las apañen solos y solucionen esto niquelado.$B$BYa es hora de que tomemos las de Villadiego antes de que terminemos tostados.$B$B¿Captas lo que quiero decir, encanto?' WHERE `ID`=42339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 거기 그대로 멈춰!', `MaleText_loc4`='嘿，你好啊伙计！', `MaleText_loc5`='嘿，老兄!', `MaleText_loc7`='¡EOOO, COLEGA!', `FemaleText_loc1`='어이! 거기 그대로 멈춰!', `FemaleText_loc4`='嘿，你好啊伙计！', `FemaleText_loc5`='嘿，老兄!', `FemaleText_loc7`='¡EOOO, COLEGA!' WHERE `ID`=42340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 둘, 지금 어딜 가려는 거냐?', `MaleText_loc4`='你们俩这是要去哪儿呢？', `MaleText_loc5`='你們兩個是要去哪裡?', `MaleText_loc7`='¿Dónde se creen que van ustedes dos?', `FemaleText_loc1`='거기 둘, 지금 어딜 가려는 거냐?', `FemaleText_loc4`='你们俩这是要去哪儿呢？', `FemaleText_loc5`='你們兩個是要去哪裡?', `FemaleText_loc7`='¿Dónde se creen que van ustedes dos?' WHERE `ID`=42341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그저 제대로 된 식사와 편안한 잠자리를 구하고 싶어서...', `MaleText_loc4`='我们只是想饱餐一顿，要是能再舒服的睡上一觉就更好了。', `MaleText_loc5`='我們想吃頓像樣一點的飯，晚上睡個舒服一點的覺而已。', `MaleText_loc7`='Solo intentamos conseguir una comida decente y quizá dormir bien una noche.' WHERE `ID`=42342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기랑 나 사이니까 말인데요. 난 이렇게 막중한 임무를 짊어지기에는 부족한 인물이랍니다. 한 달 후에 죽을지도 모르죠.$B$B이미 한 번 죽었는걸요. 두 번째는 아무 의미 없어요.', `FemaleText_loc4`='我们两个私下说，宝贝儿，我的身高不适合执行这种任务。再坚持一个月我就要离开了。$B$B我已经死过一次。没必要再来一回。', `FemaleText_loc5`='嘿，我偷偷跟你說。這種活我實在是幹不來，頂多再撐一個月我就要閃人了。$B$B我已經死過一次了。沒道理還要再死個第二次。', `FemaleText_loc7`='Entre tú y yo, cielo, soy demasiado baja para llevar a cabo este tipo de misiones. Un mes más y me largo.$B$BYa he muerto una vez. No tiene sentido hacerlo una segunda.' WHERE `ID`=42343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 글도 못읽나? 설마 까막눈이겠지?', `MaleText_loc4`='你不认字吗，伙计？看来是的，哈？', `MaleText_loc5`='你是不認識字是不是?哼，八成是看不懂啊?', `MaleText_loc7`='¿Es que no sabes leer, colega? Probablemente no, ¿eh?', `FemaleText_loc1`='너 글도 못읽나? 설마 까막눈이겠지?', `FemaleText_loc4`='你不认字吗，伙计？看来是的，哈？', `FemaleText_loc5`='你是不認識字是不是?哼，八成是看不懂啊?', `FemaleText_loc7`='¿Es que no sabes leer, colega? Probablemente no, ¿eh?' WHERE `ID`=42344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표지판에 이렇게 쓰여있잖아. "부랑자 절대 출입 금지!"라고... 알았으면 꺼져!', `MaleText_loc4`='牌子上写着：“严禁游民！”还不赶紧滚开！', `MaleText_loc5`='牌子上面寫的是:『禁止流浪漢』!快滾吧!', `MaleText_loc7`='El cartel dice: "¡NADA DE VAGABUNDOS!". ¡Ahora piérdete!', `FemaleText_loc1`='표지판에 이렇게 쓰여있잖아. "부랑자 절대 출입 금지!"라고... 알았으면 꺼져!', `FemaleText_loc4`='牌子上写着：“严禁游民！”还不赶紧滚开！', `FemaleText_loc5`='牌子上面寫的是:『禁止流浪漢』!快滾吧!', `FemaleText_loc7`='El cartel dice: "¡NADA DE VAGABUNDOS!". ¡Ahora piérdete!' WHERE `ID`=42345;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첫 번째 고대 생물인 네스피라의 일을 처리하는 건 꽤 힘겨웠습니다. 우리 앞에 있는 또 하나의 고대 생물, 고레크는 죽어가고 있습니다.$B$B고통에 겨워 울부짖는 것이 느껴집니다. 무언가가 고레크의 생명력을 빼앗아 가고 있습니다. 무엇 때문일까요?', `FemaleText_loc4`='要与第一个上古生物奈瑟匹拉打交道已经够难了。而在我们对面的那个，叫拉葛雷克的，就快要死了。$B$B我能感觉到它痛苦的哀号。有什么东西正在偷取它的生命能量。我不知道那些被偷走的生命能量将被用于什么目的。', `FemaleText_loc5`='處理第一位先祖奈斯畢拉的事情已經夠難的了。而我們對面的勒苟雷克也正逐漸凋零死亡。$B$B我可以感受得到祂的痛苦吶喊，有東西正在竊取祂的生命能量。但目的究竟是什麼呢?', `FemaleText_loc7`='Ya fue difícil arreglar lo del primer ancestro, Nespirah. El que está ahí enfrente, L''ghorek, se está muriendo.$B$BPuedo sentir sus gritos de agonía. Algo le está robando la energía vital. Pero, ¿con qué propósito?' WHERE `ID`=42346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더럽고 썩은 돼지 같은 놈들. 너희도 언젠가 심판을 받을 거다.', `MaleText_loc4`='肮脏恶心的杂碎。你们一定会遭报应的。', `MaleText_loc5`='不要臉的死馬屁精。你一定會有報應的。', `MaleText_loc7`='Apestosos y podridos amantes de los cerdos. Algún día recibirán su castigo.' WHERE `ID`=42347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 이 더러운 곳을 떠나자고. 차라리 여기가 잿더미가 되어버렸으면 좋겠군!', `MaleText_loc4`='我们赶紧离开这鬼地方。真希望这里能化为焦土。', `MaleText_loc5`='我們趕緊離開這裡吧。我希望這個地方被火一把燒個精光。', `MaleText_loc7`='Salgamos de aquí echando leches. Espero que este lugar arda hasta los cimientos.' WHERE `ID`=42348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다가오는 전투에서 당신과 함께 싸우고 싶었습니다만, 에루낙 님은 제가 여기 남길 바라시는군요.$B$B행운을 빕니다, $n 님.', `FemaleText_loc4`='我希望能与你在即将打响的战争中并肩作战，但埃鲁纳克要我留下。$B$B祝你好运，$n。', `FemaleText_loc5`='我希望可以在即將到來的戰爭中與你並肩作戰，但伊魯納克要我待在這裡。$B$B祝你好運，$n。', `FemaleText_loc7`='Desearía luchar a tu lado en la batalla que se avecina, pero Erunak desea que me quede aquí.$B$BBuena suerte, $n.' WHERE `ID`=42349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 나락은 실로 악몽이에요.$B$B저 아래 틈에서 벌어지려 하는 전투에 대면 이것도 애교로 보이겠지만요.', `FemaleText_loc4`='这深渊可真是噩梦。$B$B但和即将加入的下方裂口里的战斗比起来，简直就是小巫见大巫。', `FemaleText_loc5`='這片深海簡直是惡夢一場。$B$B但是，如果跟即將在底下爆發的決戰比起來，大概也不算什麼了吧。', `FemaleText_loc7`='Estas profundidades son una verdadera pesadilla.$B$BAunque la batalla que está a punto de desatarse en la brecha de ahí abajo hará que esto parezca el país de las maravillas.' WHERE `ID`=42350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 그렇지!', `MaleText_loc4`='头彩！', `MaleText_loc5`='中獎啦!', `MaleText_loc7`='¡PREMIO!', `FemaleText_loc1`='그럼 그렇지!', `FemaleText_loc4`='头彩！', `FemaleText_loc5`='中獎啦!', `FemaleText_loc7`='¡PREMIO!' WHERE `ID`=42351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 맛좋고 깨끗한 진흙을 발견한 것 같네요. 거기 멋진 누님, 신선한 진흙 한 사발 하실래요? 오늘 밤 우리 한번 왕처럼 먹어 보자고요!', `MaleText_loc4`='看来我给咱们找到了一块可口又干净的泥巴！今晚我们将吃得像皇帝一样，企鹅先生！我当然会与你分享！你可是我最好的朋友！', `MaleText_loc5`='看來我找到了一塊又乾淨又美味的土了!今晚我們會吃得跟國王一樣豐盛，企鵝先生!我當然會跟你一起分享囉!你是我最好的朋友!', `MaleText_loc7`='¡Parece que he encontrado un sabroso y limpio montón de tierra! ¡Esta noche cenaremos como reyes, Sr. Pingüino! ¡Claro que lo compartiré contigo! ¡Eres mi mejor amigo!', `FemaleText_loc1`='방금 맛좋고 깨끗한 진흙을 발견한 것 같네요. 거기 멋진 오빠, 신선한 진흙 한 사발 하실래요? 오늘 밤 우리 한번 왕처럼 먹어 보자고요!', `FemaleText_loc4`='看来我给咱们找到了一块可口又干净的泥巴！今晚我们将吃得像皇帝一样，企鹅先生！我当然会与你分享！你可是我最好的朋友！', `FemaleText_loc5`='看來我找到了一塊又乾淨又美味的土了!今晚我們會吃得跟國王一樣豐盛，企鵝先生!我當然會跟你一起分享囉!你是我最好的朋友!', `FemaleText_loc7`='¡Parece que he encontrado un sabroso y limpio montón de tierra! ¡Esta noche cenaremos como reyes, Sr. Pingüino! ¡Claro que lo compartiré contigo! ¡Eres mi mejor amigo!' WHERE `ID`=42352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고파!', `MaleText_loc4`='我快饿死了！', `MaleText_loc5`='我快餓死了!', `MaleText_loc7`='¡Me muero de hambre!', `FemaleText_loc1`='배고파!', `FemaleText_loc4`='我快饿死了！', `FemaleText_loc5`='我快餓死了!', `FemaleText_loc7`='¡Me muero de hambre!' WHERE `ID`=42353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하! 그거 재미있네요, 멋진 아가씨! 정말 재미있어요!', `MaleText_loc4`='哈哈哈！好样的，企鹅先生！好样的！', `MaleText_loc5`='哈哈哈!說得好，企鵝先生!說得好!', `MaleText_loc7`='¡JAJAJAJA! ¡Muy bueno, Sr. Pingüino! ¡MUY BUENO!', `FemaleText_loc1`='하하하하! 그거 재미있네요, 멋진 오빠! 정말 재미있어요!', `FemaleText_loc4`='哈哈哈！好样的，企鹅先生！好样的！', `FemaleText_loc5`='哈哈哈!說得好，企鵝先生!說得好!', `FemaleText_loc7`='¡JAJAJAJA! ¡Muy bueno, Sr. Pingüino! ¡MUY BUENO!' WHERE `ID`=42354;
