UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 무슨 일이 있었던 거지? 난 스톰윈드의 왕이었다고!', `MaleText_loc4`='我这是怎么了？我从前可是暴风城的国王！', `MaleText_loc5`='我怎麼了?我以前可是暴風城國王啊!', `MaleText_loc7`='¿Qué me ha ocurrido? ¡Una vez fui el rey de Ventormenta!', `FemaleText_loc1`='내게 무슨 일이 있었던 거지? 난 스톰윈드의 왕이었다고!', `FemaleText_loc4`='我这是怎么了？我从前可是暴风城的国王！', `FemaleText_loc5`='我怎麼了?我以前可是暴風城國王啊!', `FemaleText_loc7`='¿Qué me ha ocurrido? ¡Una vez fui la reina de Ventormenta!' WHERE `ID`=42357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저녁도 신발 가죽이나 먹어야겠군.', `MaleText_loc4`='看来我们今天的晚餐又只能啃皮鞋了。', `MaleText_loc5`='看來我們的晚餐又要吃皮鞋了。', `MaleText_loc7`='Parece que otra vez tendremos que cenar cuero de zapatos.', `FemaleText_loc1`='오늘 저녁도 신발 가죽이나 먹어야겠군.', `FemaleText_loc4`='看来我们今天的晚餐又只能啃皮鞋了。', `FemaleText_loc5`='看來我們的晚餐又要吃皮鞋了。', `FemaleText_loc7`='Parece que otra vez tendremos que cenar cuero de zapatos.' WHERE `ID`=42358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌을 먹는 게 가능할까? 이곳은 발에 차이는 게 돌이거든. 상상해봐! 그걸 증명할 수만 있다면 세상에서 제일가는 부자가 될 거야!', `MaleText_loc4`='不知道吃石头行不行？这儿附近可有好多石头。想象一下！我将因这一伟大的发现成为这世上最富有的人！', `MaleText_loc5`='石頭不曉得能不能吃?這邊石頭倒是不少。對!想想看!這個發現會讓我變成全世界最有錢的人!', `MaleText_loc7`='Me pregunto si las piedras pueden comerse. Por aquí hay un montón de piedras. ¡Imagínate! ¡Con este descubrimiento podría llegar a ser el hombre más rico del mundo!', `FemaleText_loc1`='돌을 먹는 게 가능할까? 이곳은 발에 차이는 게 돌이거든. 상상해봐! 그걸 증명할 수만 있다면 세상에서 제일가는 부자가 될 거야!', `FemaleText_loc4`='不知道吃石头行不行？这儿附近可有好多石头。想象一下！我将因这一伟大的发现成为这世上最富有的人！', `FemaleText_loc5`='石頭不曉得能不能吃?這邊石頭倒是不少。你想一想!這個發現會讓我變成全世界最有錢的人!', `FemaleText_loc7`='Me pregunto si las piedras pueden comerse. Por aquí hay un montón de piedras. ¡Imagínate! ¡Con este descubrimiento podría llegar a ser la mujer más rica del mundo!' WHERE `ID`=42359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 데피아즈단에게 털리던 시절이 그리워. 그때는 그래도 하루하루 버틸 음식이라도 있었거든.', `MaleText_loc4`='我怀念被迪菲亚抢劫的那段日子。起码他们偶尔还会给你留下点儿吃的。', `MaleText_loc5`='我好懷念以前被迪菲亞盜賊搶劫的那段日子。至少那個時候偶爾還可以吃到東西。', `MaleText_loc7`='Echo de menos que me roben los Defias. Por lo menos, de vez en cuando te dejaban algo para comer.', `FemaleText_loc1`='이제 데피아즈단에게 털리던 시절이 그리워. 그때는 그래도 하루하루 버틸 음식이라도 있었거든.', `FemaleText_loc4`='我怀念被迪菲亚抢劫的那段日子。起码他们偶尔还会给你留下点儿吃的。', `FemaleText_loc5`='我好懷念以前被迪菲亞盜賊搶劫的那段日子。至少那個時候偶爾還可以吃到東西。', `FemaleText_loc7`='Echo de menos que me roben los Defias. Por lo menos, de vez en cuando te dejaban algo para comer.' WHERE `ID`=42360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 그래 당신! 내 구역에서 당장 나가!', `MaleText_loc4`='嘿！说你呢！离我的东西远点儿！', `MaleText_loc5`='嘿!嘿就是你!滾開我的地盤!', `MaleText_loc7`='¡EH! ¡EH, TÚ! ¡NO TE ACERQUES A MIS COSAS!', `FemaleText_loc1`='이봐! 그래 당신! 내 구역에서 당장 나가!', `FemaleText_loc4`='嘿！说你呢！离我的东西远点儿！', `FemaleText_loc5`='嘿!嘿就是你!滾開我的地盤!', `FemaleText_loc7`='¡EH! ¡EH, TÚ! ¡NO TE ACERQUES A MIS COSAS!' WHERE `ID`=42361;
