UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 대단하신 영웅님께서 등장하셨네. 난 살았다... 라고 할 줄 알았지?', `MaleText_loc4`='喔，是大英雄来了。我得救了！对，是的……', `MaleText_loc5`='哇!大英雄來囉!我有救囉!哼，跟真的一樣...', `MaleText_loc7`='¡Oh, $gel gran héroe:la gran heroína; ha venido! ¡Estoy salvado! Sí, claro...', `FemaleText_loc1`='오, 대단하신 영웅님께서 등장하셨네. 난 살았다... 라고 할 줄 알았지?', `FemaleText_loc4`='喔，是大英雄来了。我得救了！对，是的……', `FemaleText_loc5`='哇!大英雄來囉!我有救囉!哼，跟真的一樣...', `FemaleText_loc7`='¡Oh, $gel gran héroe:la gran heroína; ha venido! ¡Estoy salvada! Sí, claro...' WHERE `ID`=42368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 대화하고 싶나? 그럼, 돈을 내.', `MaleText_loc4`='你想聊聊？给钱。', `MaleText_loc5`='要聊天嗎?請先付錢。', `MaleText_loc7`='¿Quieres que hable? Pues paga.', `FemaleText_loc1`='나와 대화하고 싶나? 그럼, 돈을 내.', `FemaleText_loc4`='你想聊聊？给钱。', `FemaleText_loc5`='要聊天嗎?請先付錢。', `FemaleText_loc7`='¿Quieres que hable? Pues paga.' WHERE `ID`=42369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄브라우 일가를 죽인 사람을 보셨습니까?', `MaleText_loc4`='你看到是谁杀了法布隆一家吗？', `MaleText_loc5`='你有看到是誰殺了法布隆家的人嗎?', `MaleText_loc7`='¿Viste quién mató a los Cejade?', `FemaleText_loc1`='펄브라우 일가를 죽인 사람을 보셨나요?', `FemaleText_loc4`='你看到是谁杀了法布隆一家吗？', `FemaleText_loc5`='你有看到是誰殺了法布隆家的人嗎?', `FemaleText_loc7`='¿Has visto quién mató a los Cejade?' WHERE `ID`=42370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동전 몇 잎이면 혀가 좀 풀리겠습니까? 이제 말해주십시오. 누가 펄브라우 일가를 죽였습니까?', `MaleText_loc4`='也许几枚铜币就能撬开你的牙齿。现在请你告诉我，你有没有看到是谁杀了法布隆一家？', `MaleText_loc5`='這幾塊銅板或許會讓你更健談一點。好吧，告訴我，你有沒有看到是誰殺了法布隆家的人?', `MaleText_loc7`='Quizá una moneda de cobre te suelte la lengua. Ahora dime, ¿viste quién mató a los Cejade?', `FemaleText_loc1`='동전 몇 잎이면 혀가 좀 풀리시겠죠? 이제 말해주세요. 누가 펄브라우 일가를 죽였나요?', `FemaleText_loc4`='也许几枚铜币就能撬开你的牙齿。现在请你告诉我，你有没有看到是谁杀了法布隆一家？', `FemaleText_loc5`='這幾塊銅板或許會讓你更健談一點。好吧，告訴我，你有沒有看到是誰殺了法布隆家的人?', `FemaleText_loc7`='Quizá una moneda de cobre te suelte la lengua. Ahora dime, ¿viste quién mató a los Cejade?' WHERE `ID`=42371;
