UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 해줄 수 있는 말은 이것뿐이야. 여기서 당장 꺼져!', `MaleText_loc4`='我唯一能告诉你的，就是给我滚开！', `MaleText_loc5`='我唯一會告訴你的事情，就是滾開這裡!', `MaleText_loc7`='¡Lo único que voy a decirte es que te largues de aquí!', `FemaleText_loc1`='내가 해줄 수 있는 말은 이것뿐이야. 여기서 당장 꺼져!', `FemaleText_loc4`='我唯一能告诉你的，就是给我滚开！', `FemaleText_loc5`='我唯一會告訴你的事情，就是滾開這裡!', `FemaleText_loc7`='¡Lo único que voy a decirte es que largues de aquí!' WHERE `ID`=42375;
