UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 자연사한 거야...', `MaleText_loc4`='他们是自然死亡……', `MaleText_loc5`='他們是因疾病死亡的...', `MaleText_loc7`='Murieron por causas naturales...', `FemaleText_loc1`='그들은 자연사한 거야...', `FemaleText_loc4`='他们是自然死亡……', `FemaleText_loc5`='他們是因疾病死亡的...', `FemaleText_loc7`='Murieron por causas naturales...' WHERE `ID`=42377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게선 아무것도 알아낼 수 없을 거다!', `MaleText_loc4`='你从我这儿什么都别想知道！', `MaleText_loc5`='你無法從我身上問到任何東西!', `MaleText_loc7`='¡No me sacarás nada!', `FemaleText_loc1`='내게선 아무것도 알아낼 수 없을 거다!', `FemaleText_loc4`='你从我这儿什么都别想知道！', `FemaleText_loc5`='你無法從我身上問到任何東西!', `FemaleText_loc7`='¡No me sacarás nada!' WHERE `ID`=42378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심판의 날이 온다! 결사단이 부활할 것이다!', `MaleText_loc4`='审判日到了！兄弟会必将重生！', `MaleText_loc5`='審判日來臨!兄弟會將會重生!', `MaleText_loc7`='¡Se acerca el día del Juicio! ¡La hermandad renacerá!', `FemaleText_loc1`='심판의 날이 온다! 결사단이 부활할 것이다!', `FemaleText_loc4`='审判日到了！兄弟会必将重生！', `FemaleText_loc5`='審判日來臨!兄弟會將會重生!', `FemaleText_loc7`='¡Se acerca el día del Juicio! ¡La hermandad renacerá!' WHERE `ID`=42379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑똑히 들어, 난 더 이상 문제를 일으키고 싶진 않으니까. 누가 죽였는지는 정확히 모르겠어. 하지만 많은 사람들이 고함지르는 소리는 들었지... 알아 들겠어? 이제 널 때려눕히고 신발을 뺏고 싶어지기 전에 어서 내 앞에서 당장 사라져.', `MaleText_loc4`='听着，$g伙计:女士;，我可不想惹麻烦。我没看见是谁杀了他们，但我听到了！不绝的哭喊声，还有人说话的声音……懂了吗？现在赶紧离开这儿，趁我还没改变主意把你的鞋子扒下来痛打你一顿。', `MaleText_loc5`='嘿，$g兄弟:小姐;，我不想惹上麻煩，好嗎?雖然我沒看到是誰殺了他們，但我可是聽得清清楚楚!人類的聲音...聽懂了嗎?好了，快點滾開，趁我還沒改變心意把你痛扁一頓、搶走你的鞋子。', `MaleText_loc7`='Escucha, $gamigo:señorita;, no quiero problemas, ¿vale? No vi quién los mató, ¡pero desde luego sí que lo oí! Muchos gritos. Voces humanas... ¿captas? Ahora lárgate de aquí antes de que cambie de idea y te dé una paliza para quedarme con tus zapatos.', `FemaleText_loc1`='똑똑히 들어, 난 더 이상 문제를 일으키고 싶진 않으니까. 누가 죽였는지는 정확히 모르겠어. 하지만 많은 사람들이 고함지르는 소리는 들었지... 알아 들겠어? 이제 널 때려눕히고 신발을 뺏고 싶어지기 전에 어서 내 앞에서 당장 사라져.', `FemaleText_loc4`='听着，$g伙计:女士;，我可不想惹麻烦。我没看见是谁杀了他们，但我听到了！不绝的哭喊声，还有人说话的声音……懂了吗？现在赶紧离开这儿，趁我还没改变主意把你的鞋子扒下来痛打你一顿。', `FemaleText_loc5`='嘿，$g兄弟:小姐;，我不想惹上麻煩，好嗎?雖然我沒看到是誰殺了他們，但我可是聽得清清楚楚!人類的聲音...聽懂了嗎?好了，快點滾開，趁我還沒改變心意把你痛扁一頓、搶走你的鞋子。', `FemaleText_loc7`='Escucha, $gamigo:señorita;, no quiero problemas, ¿vale? No vi quién los mató, ¡pero desde luego sí que lo oí! Muchos gritos. Voces humanas... ¿captas? Ahora lárgate de aquí antes de que cambie de idea y te dé una paliza para quedarme con tus zapatos.' WHERE `ID`=42380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 죽였는지 보진 못했어. 하지만 냄새는 맡았지. 너처럼 부자 냄새가 났어. 참 안된 일이야. 펄브라우 일가는 이곳 붙박이였는데, 좋은 사람들이었거든. 먹을 걸 나눌 줄 아는 사람들이었어.', `MaleText_loc4`='我没看见是谁杀了他们，$g伙计:女士;，但我嗅到了点儿什么。闻上去像是有钱人的味道，跟你有点儿像。我也感到很遗憾。法布隆一家是这儿的老住户了。他们一家都是好人，总是愿意拿出饭菜或泥土与人分享。', `MaleText_loc5`='我沒看到是誰殺了他們，$g小弟:小姐;，但是我有聞到一點味道。有錢的味道，就像你一樣。真是遺憾啊，法布隆他們家在這裡住好久了說。不錯的好人，經常願意跟大家分享著一頓飯還是一塊土的。', `MaleText_loc7`='No vi quién los mató, $gchaval:señora;, pero me huelo algo. Olían a rico, como tú. Una pena. Los Cejade eran parte de este lugar. Muy amables, siempre estaban dispuestos a compartir una comida o un poco de tierra.', `FemaleText_loc1`='누가 죽였는지 보진 못했어, 하지만 냄새는 맡았지. 너처럼 부자 냄새가 났어. 참 안된 일이야. 펄브라우 일가는 이곳 붙박이였는데, 좋은 사람들이었거든. 먹을 걸 나눌 줄 아는 사람들이었어.', `FemaleText_loc4`='我没看见是谁杀了他们，$g伙计:女士;，但我嗅到了点儿什么。闻上去像是有钱人的味道，跟你有点儿像。我也感到很遗憾。法布隆一家是这儿的老住户了。他们一家都是好人，总是愿意拿出饭菜或泥土与人分享。', `FemaleText_loc5`='我沒看到是誰殺了他們，$g小弟:小姐;，但是我有聞到一點味道。有錢的味道，就像你一樣。真是遺憾啊，法布隆他們家在這裡住好久了說。不錯的好人，經常願意跟大家分享著一頓飯還是一塊土的。', `FemaleText_loc7`='No vi quién los mató, $gchaval:señora;, pero me huelo algo. Olían a rico, como tú. Una pena. Los Cejade eran parte de este lugar. Muy amables, siempre estaban dispuestos a compartir una comida o un poco de tierra.' WHERE `ID`=42381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 펄브라우 일가를 죽였냐고? 내가 말해주지. 바로 국왕 바리안 린이야! 그 자식은 우리도 죽이려 하고 있어. 한 명, 한 명씩 말이야. 내가 줄 수 있는 유일한 정보는 수사관이 나타나기 몇 시간 전에 놀이 이곳을 떠나는 모습을 봤다는 거야.', `MaleText_loc4`='谁杀了法布隆一家？让我来告诉你是谁干的——是瓦里安·乌瑞恩国王，对，就是他！而且他还要把我们都杀了，一次性全干掉。我唯一能告诉你的，就是我看到有几个豺狼人在办案人员到来的几小时前从那里走掉了。', `MaleText_loc5`='誰殺了法布隆夫婦?我告訴你是誰殺了法布隆夫婦:瓦里安·烏瑞恩國王!就是他!而且他還要把我們全都給殺了。一個災民一個災民的殺光光!我唯一能告訴你的事情，就是在穿制服的跑來這裡的幾個小時以前，我有看到幾隻豺狼人離開那個地方。', `MaleText_loc7`='¿Quién mató a los Cejade? Yo te diré quién mató a los Cejade: ¡EL REY VARIAN WRYNN, ÉL ES QUIEN LOS MATÓ! Y también nos está matando a los demás. A todos los vagabundos, de uno en uno. Lo único que puedo decirte es que vi a unos gnolls que abandonaban el lugar pocas horas antes de que llegaran los representantes de la ley.', `FemaleText_loc1`='누가 펄브라우 일가를 죽였냐고? 내가 말해주지. 바로 국왕 바리안 린이야! 그 자식은 우리도 죽이려 하고 있어. 한 명, 한 명씩 말이야. 내가 줄 수 있는 유일한 정보는 수사관이 나타나기 몇 시간 전에 놀이 이곳을 떠나는 모습을 봤다는 거야.', `FemaleText_loc4`='谁杀了法布隆一家？让我来告诉你是谁干的——是瓦里安·乌瑞恩国王，对，就是他！而且他还要把我们都杀了，一次性全干掉。我唯一能告诉你的，就是我看到有几个豺狼人在办案人员到来的几小时前从那里走掉了。', `FemaleText_loc5`='誰殺了法布隆夫婦?我告訴你是誰殺了法布隆夫婦:瓦里安·烏瑞恩國王!就是他!而且他還要把我們全都給殺了。一個災民一個災民的殺光光!我唯一能告訴你的事情，就是在穿制服的跑來這裡的幾個小時以前，我有看到幾隻豺狼人離開那個地方。', `FemaleText_loc7`='¿Quién mató a los Cejade? Yo te diré quién mató a los Cejade: ¡EL REY VARIAN WRYNN, ÉL ES QUIEN LOS MATÓ! Y también nos está matando a los demás. A todos los vagabundos, de uno en uno. Lo único que puedo decirte es que vi a unos gnolls que abandonaban el lugar pocas horas antes de que llegaran los representantes de la ley.' WHERE `ID`=42382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와, 나 사이의 비밀인데. 멀록이 펄브라우 일가를 죽였어. 그럼 그럼, 내 두 눈으로 똑똑히 봤는데. 며칠, 아니 몇 달째 기회를 노리고 있었을 거야. 저쪽의 "반장 나으리"와 바보같은 여단이 나타나자 급히 사라지더군.', `MaleText_loc4`='你知，我知，树知——是鱼人杀死了法布隆一家。没错，是我亲眼看见的。我想他们已经蓄谋了好几天，甚至是好几个月了。后来当他们听到与“约翰尼警员”和那白痴编队有关的风声时，就仓皇逃走了……', `MaleText_loc5`='此事只有你知、我知，還有這棵樹知道...是魚人殺了法布隆全家。沒錯，我親眼看到他們。好像他們已經打探好幾天了，搞不好幾個月。不過一聽到當官的還有那邊的白痴軍隊來了，他們馬上就趕緊溜跑了...', `MaleText_loc7`='Entre tú y yo el árbol te diré que los múrlocs mataron a los Cejade. Sí, lo vi con mis propios ojos. Creo que llevaban días, quizá meses, apareciendo por aquí para fichar el lugar. Se largaron a toda pastilla en cuanto olieron al poli ese y a su brigada de idiotas...', `FemaleText_loc1`='너와, 나 사이의 비밀인데. 멀록이 펄브라우 일가를 죽였어. 그럼 그럼, 내 두 눈으로 똑똑히 봤는데. 며칠, 아니 몇 달째 기회를 노리고 있었을 거야. 저쪽의 "반장 나으리"와 바보같은 여단이 나타나자 급히 사라지더군.', `FemaleText_loc4`='你知，我知，树知——是鱼人杀死了法布隆一家。没错，是我亲眼看见的。我想他们已经蓄谋了好几天，甚至是好几个月了。后来当他们听到与“约翰尼警员”和那白痴编队有关的风声时，就仓皇逃走了……', `FemaleText_loc5`='此事只有你知、我知，還有這棵樹知道...是魚人殺了法布隆全家。沒錯，我親眼看到他們。好像他們已經打探好幾天了，搞不好幾個月。不過一聽到當官的還有那邊的白痴軍隊來了，他們馬上就趕緊溜跑了...', `FemaleText_loc7`='Entre tú y yo el árbol te diré que los múrlocs mataron a los Cejade. Sí, lo vi con mis propios ojos. Creo que llevaban días, quizá meses, apareciendo por aquí para fichar el lugar. Se largaron a toda pastilla en cuanto olieron al poli ese y a su brigada de idiotas...' WHERE `ID`=42383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 부자 놈들은 다 똑같아!', `MaleText_loc4`='你们有钱人都是一个样！', `MaleText_loc5`='你們這些有錢的痞子都是一個樣!', `MaleText_loc7`='¡Los ricos sois todos iguales!', `FemaleText_loc1`='너희 부자 놈들은 다 똑같아!', `FemaleText_loc4`='你们有钱人都是一个样！', `FemaleText_loc5`='你們這些有錢的痞子都是一個樣!', `FemaleText_loc7`='¡Los ricos sois todos iguales!' WHERE `ID`=42384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에겐 눈곱만큼도 털어놓지 않을 거다!', `MaleText_loc4`='不管什么事情，我都不会告诉你的！', `MaleText_loc5`='我死都不會跟你說一個字!', `MaleText_loc7`='¡No voy a soltar prenda!', `FemaleText_loc1`='너에겐 눈곱만큼도 털어놓지 않을 거다!', `FemaleText_loc4`='不管什么事情，我都不会告诉你的！', `FemaleText_loc5`='我死都不會跟你說一個字!', `FemaleText_loc7`='¡No voy a soltar prenda!' WHERE `ID`=42385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 눈으로 보지 않아도 이 짐승같은 삶은 충분히 힘들다고!', `MaleText_loc4`='像个畜生一样的活着已经够痛苦了，现在你还来羞辱我！', `MaleText_loc5`='像畜生般活著已經夠苦了，不要再來污辱我!', `MaleText_loc7`='¡Ya es duro vivir como un animal como para que encima vengas tú a insultarme!', `FemaleText_loc1`='그런 눈으로 보지 않아도 이 짐승같은 삶은 충분히 힘들다고!', `FemaleText_loc4`='像个畜生一样的活着已经够痛苦了，现在你还来羞辱我！', `FemaleText_loc5`='像畜生般活著已經夠苦了，不要再來污辱我!', `FemaleText_loc7`='¡Ya es duro vivir como un animal como para que encima vengas tú a insultarme!' WHERE `ID`=42386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 신장을 팔아넘겨야겠다.', `MaleText_loc4`='也许我能拿你的肝脏去换几个钱。', `MaleText_loc5`='或許我可以賣了你的肝來賺點金幣。', `MaleText_loc7`='Quizá pueda vender tu hígado para sacarme unas monedas de oro.', `FemaleText_loc1`='네 신장을 팔아넘겨야겠다.', `FemaleText_loc4`='也许我能拿你的肝脏去换几个钱。', `FemaleText_loc5`='或許我可以賣了你的肝來賺點金幣。', `FemaleText_loc7`='Quizá pueda vender tu hígado para sacarme unas monedas de oro.' WHERE `ID`=42387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛 갚으라고 했잖아!', `MaleText_loc4`='我告诉过你要全部付清了，小子！', `MaleText_loc5`='我不是跟你說了要先給錢嗎?混蛋!', `MaleText_loc7`='¡TE HE DICHO QUE SUELTES LA PASTA, COLEGA!', `FemaleText_loc1`='빛 갚으라고 했잖아!', `FemaleText_loc4`='我告诉过你要全部付清了，小子！', `FemaleText_loc5`='我不是跟你說了要先給錢嗎?混蛋!', `FemaleText_loc7`='¡TE HE DICHO QUE SUELTES LA PASTA, COLEGA!' WHERE `ID`=42388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못 참아! 이리로 와, 이 자식!', `MaleText_loc4`='你这蠢货竟然真敢这么干！尝尝我的拳头！', `MaleText_loc5`='不給錢硬要問是吧!吃拳頭吧你!', `MaleText_loc7`='¡Esta vez la has cagado! ¡HORA DE QUE LOS PUÑOS ENTREN EN ACCIÓN!', `FemaleText_loc1`='더는 못 참아! 이리로 와, 이 자식!', `FemaleText_loc4`='你这蠢货竟然真敢这么干！尝尝我的拳头！', `FemaleText_loc5`='不給錢硬要問是吧!吃拳頭吧你!', `FemaleText_loc7`='¡Esta vez la has cagado! ¡HORA DE QUE LOS PUÑOS ENTREN EN ACCIÓN!' WHERE `ID`=42389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디에 발차기를 먹여줄까? 얼굴? 뒤통수? 어디 한번 골라보시지.', `MaleText_loc4`='你想让我踢你前胸还是屁股？随你挑。', `MaleText_loc5`='你要我把腳印蓋在你的前面還是後面?給你自己決定。', `MaleText_loc7`='¿Dónde quieres que te de la patada? ¿Delante o detrás? Puedes elegir.', `FemaleText_loc1`='어디에 발차기를 먹여줄까? 얼굴? 뒤통수? 어디 한번 골라보시지.', `FemaleText_loc4`='你想让我踢你前胸还是屁股？随你挑。', `FemaleText_loc5`='你要我把腳印蓋在你的前面還是後面?給你自己決定。', `FemaleText_loc7`='¿Dónde quieres que te de la patada? ¿Delante o detrás? Puedes elegir.' WHERE `ID`=42390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 시작합시다!', `MaleText_loc4`='攻击开始！', `MaleText_loc5`='突擊開始!', `MaleText_loc7`='¡Que comience el asalto!', `FemaleText_loc1`='공격을 시작하죠!', `FemaleText_loc4`='攻击开始！', `FemaleText_loc5`='突擊開始!', `FemaleText_loc7`='¡Que comience el asalto!' WHERE `ID`=42391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 아제로스의 시련의 시기입니다, $n. 정령들이 시민과 병사를 감옥에 가두고 있습니다. 정령의 감옥을 부술 수 있는 토템을 드릴 수 있습니다.', `MaleText_loc4`='这是艾泽拉斯的困难时期，$n。元素已经把许多市民和与他们交战的对手都囚禁了起来。我们可以给你一个图腾，用它就能打破元素的禁锢。', `MaleText_loc5`='這是艾澤拉斯的黑暗期，$n。元素們將城市周遭的居民和與它們打仗的戰士們囚禁了。我們可以給你一個能夠破壞元素監獄的圖騰。', `MaleText_loc7`='Estos son tiempos difíciles para Azeroth, $n. Los elementales han hecho prisioneros a los ciudadanos que estaban tanto alrededor de la ciudad como en la batalla. Podemos darte un tótem que romperá la prisión elemental.', `FemaleText_loc1`='지금은 아제로스의 시련의 시기입니다, $n. 정령들이 시민과 병사를 감옥에 가두고 있습니다. 정령의 감옥을 부술 수 있는 토템을 드릴 수 있습니다.', `FemaleText_loc4`='这是艾泽拉斯的困难时期，$n。元素已经把许多市民和与他们交战的对手都囚禁了起来。我们可以给你一个图腾，用它就能打破元素的禁锢。', `FemaleText_loc5`='這是艾澤拉斯的黑暗期，$n。元素們將城市周遭的居民和與它們打仗的戰士們囚禁了。我們可以給你一個能夠破壞元素囚牢的圖騰。', `FemaleText_loc7`='Estos son tiempos difíciles para Azeroth, $n. Los elementales han hecho prisioneros a los ciudadanos que estaban tanto alrededor de la ciudad como en la batalla. Podemos darte un tótem que romperá la prisión elemental.' WHERE `ID`=42392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었나, 제군. 여기를 사수한다!', `MaleText_loc4`='你们听见他说的了。我们将坚守此地！', `MaleText_loc5`='你聽到了，老兄。我們將在這裡進行對抗!', `MaleText_loc7`='Ya le habéis oído, muchachos. ¡Nos quedaremos aquí a defender!' WHERE `ID`=42393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구로서, 영웅으로서 내 야영지에 집결하겠다. 그곳에서 가장 위험한 마지막 임무에 대해 의논하겠노라. 가자 피멘토, 이랴!', `MaleText_loc4`='让我们到我营地处重聚——以朋友与同行英雄的身份，来讨论我们最后也是最重要的任务。来吧，多香果！', `MaleText_loc5`='以惺惺相惜的朋友和英雄夥伴的身分回我的營地集合吧。討論我們最後一個、同時也是最危險的任務。喝，皮曼托!', `MaleText_loc7`='Reunámonos en nuestro campamento, como amigos y camaradas héroes, para hablar sobre muestra misión final y más peligrosa. ¡Hap, hap! ¡Rocilante!' WHERE `ID`=42394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸우게, $n!', `MaleText_loc4`='战斗到底，$n！', `MaleText_loc5`='戰鬥，$n!', `MaleText_loc7`='¡Sigue luchando, $n!' WHERE `ID`=42395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르, $n!', `MaleText_loc4`='Lok''tar，$n！', `MaleText_loc5`='為了部落, $n!', `MaleText_loc7`='¡Lok''tar, $n!' WHERE `ID`=42396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 행위가 호드에 영광과 명예를 가져오네, $n!', `MaleText_loc4`='你的功绩为部落带来了辉煌与荣耀，$n！', `MaleText_loc5`='你的功績為部落帶來榮耀和光輝，$n!', `MaleText_loc7`='¡Tus hazañas traen a la Horda honor y gloria, $n!' WHERE `ID`=42397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침략자 놈들에게 죽음을 선사하게, $n!', `MaleText_loc4`='把这些入侵者立即处死，$n！', `MaleText_loc5`='$n，給這些入侵者們一個痛快!', `MaleText_loc7`='¡Que los invasores sufran una muerte rápida, $n!' WHERE `ID`=42398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들을 부숴버리게, $n! 우리의 땅에서 몰아내 버리게!', `MaleText_loc4`='碾碎这些元素，$n！把它们从我们的土地上驱逐出去！', `MaleText_loc5`='摧毀這些元素，$n!把它們趕出我們的土地!', `MaleText_loc7`='¡Aplasta a esos elementales, $n! ¡Échalos de nuestras tierras!' WHERE `ID`=42399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다! 넵튤론의 세계 입구입니다...', `MaleText_loc4`='就是这儿！进入耐普图隆王国的入口……', `MaleText_loc5`='就是這!前往奈普圖隆領域的入口...', `MaleText_loc7`='¡Aquí está! La entrada al reino de Neptulon...' WHERE `ID`=42400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞서 싸우게, $n!', `MaleText_loc4`='把他们击退，$n！', `MaleText_loc5`='擊退他們，$n!', `MaleText_loc7`='¡Lucha, $n!' WHERE `ID`=42401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해지면 안 되네, $n!', `MaleText_loc4`='不要松懈，$n！', `MaleText_loc5`='不要鬆懈，$n!', `MaleText_loc7`='¡No te detengas, $n!' WHERE `ID`=42402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들은 자네에게 꼼짝도 못 할 걸세, $n!', `MaleText_loc4`='这些元素在你面前毫无机会，$n！', `MaleText_loc5`='那些元素不會是你的對手，$n!', `MaleText_loc7`='¡Los eleme''tos no tienen ninguna opo''tunidad contra ti, $n!' WHERE `ID`=42403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 놈들을 고통의 세계로 보내주지! 내 지시를 따르게, $n!', `MaleText_loc4`='让这些元素痛不欲生！听从我的指挥，$n！', `MaleText_loc5`='那些元素自尋死路!跟著我，$n!', `MaleText_loc7`='¡Los eleme''tos suf''irán lo indecible! ¡Sígueme, $n!' WHERE `ID`=42404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 엄청난 힘을 지녔구먼, $n!', `MaleText_loc4`='你可真有两下子，$n！', `MaleText_loc5`='看來你還蠻有料的嘛，$n!', `MaleText_loc7`='¡Tu mojo es mu'' poderoso, $n!' WHERE `ID`=42405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 따르라, 아즈샤라의 아이들이여... 때가 왔다. 물의 세계는 곧 우리 것이 된다!', `FemaleText_loc4`='集结起来，艾萨拉的孩子们！我们终于要夺取水元素位面了！', `FemaleText_loc5`='來吧，艾薩拉之子們!我們終於來佔領水之界域了!', `FemaleText_loc7`='¡Vengan, hijos de Azshara! ¡Al fin, reclamamos el Plano del Agua!' WHERE `ID`=42406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가자, 나가들아! 아제로스에 납신 위대한 바다사냥꾼을 맞이하라!', `FemaleText_loc4`='去吧，我的纳迦！迎接强大的猎潮者来到艾泽拉斯。', `FemaleText_loc5`='去吧，我的納迦!迎接強大的獵潮者來到艾澤拉斯!', `FemaleText_loc7`='¡Vayan, mis nagas! ¡Denle al poderoso Cazamareas su bienvenida!' WHERE `ID`=42407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 우리는 강력한 군대를 조직해 텔마플러그의 하수인들을 모조리 무찌르며 도시에 진입했지. 하지만 비열한 텔마플러그가 마지막으로 더러운 수작을 부렸어...', `MaleText_loc4`='我们召集起了一支强大的军队，击败了瑟玛普拉格的爪牙，一路杀回这座城市。但瑟玛普拉格这个篡位者还留了一招……', `MaleText_loc5`='我們聚集了一支強大的軍隊並擊敗了瑟瑪普拉格的手下們，一路殺進城裡。但篡位者瑟瑪普拉格留了最後一手...', `MaleText_loc7`='Reunimos una fuerza poderosa y vencimos a los sirvientes de Termochufe, hasta que llegamos a la ciudad. Pero al usurpador Termochufe le quedaba un as bajo la manga…' WHERE `ID`=42408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난모래 트롤이 황혼의 망치단과 손을 잡았다고?! 설령 그렇더라도 그 악랄한 마녀가 나의 도시로 그녀의 괴물을 보낼 순 없을 것이다.', `MaleText_loc4`='沙怒巨魔与暮光之锤联手？！不要紧。那个邪恶的女巫别想把她的怪物送进我的城市。', `MaleText_loc5`='沙怒食人妖跟暮光之錘合作?!無所謂，那個邪惡的女巫別想讓她的怪物進到我的城市中。', `MaleText_loc7`='¡¿Trols Furiarena aliados con el Martillo Crepuscular?! No pasa nada. Esa bruja repugnante no enviará ningún monstruo a MI ciudad.' WHERE `ID`=42409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오라, 용맹한 전사들이여! 우리는 놈들의 피로 땅을 물들이고 승리의 나팔을 불며 귀향할 것이다.', `MaleText_loc4`='来吧，勇士们！我们要用他们的污血点缀这片沙地，凯旋而归！', `MaleText_loc5`='來吧，勇敢的人們!我們會用他們的鮮血將沙地染成紅色，然後光榮地凱旋歸去。', `MaleText_loc7`='¡Adelante, mis valientes! Cubriremos la arena con sus entrañas y regresaremos a casa victoriosos.' WHERE `ID`=42410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하아... 우린 퇴각할 수밖에 없었지. 텔마플러그는 지금도 방사능을 방패 삼아 놈리건에 숨어 있네. 크러쉬코그를 지상에 내보내 우릴 괴롭히면서 말이야!', `MaleText_loc4`='我们不得不撤退。瑟玛普拉格则继续躲在地下的辐射尘中，派遣他的部下碎轮来到地面上作恶。', `MaleText_loc5`='我們被迫撤退。瑟瑪普拉格一直躲在輻射的背後，派出他的走狗:碾輪來到地面騷擾我們。', `MaleText_loc7`='Tuvimos que retirarnos. Termochufe sigue detrás de la radiación y nos manda a su compinche, Prensadiente, a hostigarnos en la superficie.' WHERE `ID`=42411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기는 다시 호드가 통제한다! 오그리마에 이런 한심한 공격을 감행한 놈들을 모두 부숴버리겠다. 호드를 위하여!', `MaleText_loc4`='部落夺回了力量谷！进攻奥格瑞玛的可怜把戏必将覆灭。为了部落！', `MaleText_loc5`='力量谷又再次回到部落的手中!這種弱小的攻擊對奧格瑪來說就像搔癢。為了部落!', `MaleText_loc7`='¡El Valle de la Fuerza pertenece a la Horda de nuevo! El patético ataque a Orgrimmar será aplastado. ¡Por la Horda!' WHERE `ID`=42412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부두교의 마법은 호드의 힘이다. 정기의 골짜기는 이제 볼진이 통제한다!', `MaleText_loc4`='巫毒是部落的力量。精神谷现在受沃金控制！', `MaleText_loc5`='巫毒是部落的力量。精神谷的控制權現在在沃金手裡!', `MaleText_loc7`='¡El vudú e'' la fuerza de la Horda. El Valle de los Eh''píritus eh''tá ahora bajo el control de Vol''jin!' WHERE `ID`=42413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기는 이제 안전하다!', `MaleText_loc4`='荣誉谷守住了！', `MaleText_loc5`='榮譽谷已經安全了!', `MaleText_loc7`='¡El Valle de la Fuerza está a salvo!' WHERE `ID`=42414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍집게발호가 곧 도착합니다! 무장을 갖추고 정렬하세요, 여러분!', `MaleText_loc4`='扳钳X2号马上就要到了！整装列队，弟兄们！', `MaleText_loc5`='鉗手X2馬上就到了!小子們，拿好你們的裝備和排好陣形!', `MaleText_loc7`='¡El Tenazario X2 llegará en breve! ¡Tomen sus cosas y a formar, muchachos!' WHERE `ID`=42415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍집게발호가 정박했습니다. 모두 올라타세요!', `MaleText_loc4`='扳钳X2号已经到达。全体上船！', `MaleText_loc5`='鉗手X2已經靠站了。所有人員登船!', `MaleText_loc7`='El Tenazario X2 ha llegado al muelle. ¡Subid a bordo!' WHERE `ID`=42417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 필요한가? 글럽톡 왜 불렀나?', `MaleText_loc4`='你这小小的凡人想要什么？为什么要找格拉布托克？', `MaleText_loc5`='小小的人類要什麼?為什麼找格魯巴托克?', `MaleText_loc7`='¿Qué tú querer pequeño humano? ¿Por qué llamar a Glubtok?' WHERE `ID`=42418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불쌍하군... 이게 네가 원하던 삶이었나, 글럽톡? 동굴 밖에서 하찮은 공갈단이나 운영하는 그런 삶?', `FemaleText_loc4`='真可悲……这就是你向往的生活吗，格拉布托克？从洞穴里时不时地跑出来靠敲诈发点儿小财？', `FemaleText_loc5`='真可悲...這就是你想過的生活嗎，格魯巴托克?躲在個洞裡做這種不入流的勒索勾當?', `FemaleText_loc7`='Qué triste... ¿Esta es la vida a la que aspirabas, Glubtok? ¿Llevando operaciones de extorsión de poca monta en una cueva?' WHERE `ID`=42419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글럽톡 너 부숴버린다!', `MaleText_loc4`='格拉布托克要粉碎你！', `MaleText_loc5`='格魯巴托克把你打扁!', `MaleText_loc7`='¡Glubtok aplastar!' WHERE `ID`=42420;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 그러시겠다? 자신의 목숨을 내던지시겠다 이건가?', `FemaleText_loc4`='哦你会吗？你敢冒生命危险做这种越界的事情吗？', `FemaleText_loc5`='喔?你會嗎?你敢這樣做拿你的生命冒險?', `FemaleText_loc7`='¿En serio? ¿Vas a atreverte a cruzar la línea y a arriesgar tu vida?' WHERE `ID`=42421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 길?', `MaleText_loc4`='另一个选择是什么？', `MaleText_loc5`='什麼第二個選擇?', `MaleText_loc7`='¿Qué ser opción dos?' WHERE `ID`=42422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 내 목숨을 노릴 수도 있지. 물론 실패하겠지만... 아니면 다른 길을 선택할 수도 있고.', `FemaleText_loc4`='你可以试着杀死我——然后失败——或者你也可以接受另一个选择。', `FemaleText_loc5`='你可以動手把我殺掉—但是你會失敗。或者，你可以選第二種選擇。', `FemaleText_loc7`='Puedes intentar matarme y fracasar, o puedes elegir la opción dos.' WHERE `ID`=42423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 밑으로 들어오면 너에게 부와 권력을 보장하겠다.', `FemaleText_loc4`='加入我，我将让你沐浴在财富与权力之中。', `FemaleText_loc5`='加入我。我就給你至高的財富和力量。', `FemaleText_loc7`='Únete a mí y te cubriré de riqueza y poder.' WHERE `ID`=42424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말은 글럽톡에게 두 가지 선택권이 있다 이거지? 죽음 아니면 부와 권력?', `MaleText_loc4`='所以格拉布托克现在有两种选择——死，或是变得富有而强大？', `MaleText_loc5`='所以格魯巴托克有兩個選擇:死掉，或是變有錢和變厲害?', `MaleText_loc7`='¿Así que Glubtok tener dos opciones: morir o ser rico y poderoso?' WHERE `ID`=42425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했습니다, $n! 스톰윈드가 당신에게 큰 빚을 졌군요.', `MaleText_loc4`='干得漂亮，$n！暴风城将永远不忘你的恩情。', `MaleText_loc5`='做得好，$n!暴風城欠你一個人情。', `MaleText_loc7`='¡Bien hecho, $n! Ventormenta está en deuda contigo.', `FemaleText_loc1`='수고했어요, $n! 스톰윈드가 당신에게 큰 빚을 졌군요.', `FemaleText_loc4`='干得漂亮，$n！暴风城将永远不忘你的恩情。', `FemaleText_loc5`='做得好，$n!暴風城欠你一個人情。', `FemaleText_loc7`='¡Bien hecho, $n! Ventormenta está en deuda contigo.' WHERE `ID`=42426;
