UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회 구성원 중 아무에게나 가서 토템을 받게! 토템을 사용해서 정령 감옥에 갇힌 주민과 병사를 풀어주게.', `MaleText_loc4`='你可以从任何大地之环成员那里取得图腾！用图腾将市民和防御者从元素囚牢中解救出来！', `MaleText_loc5`='跟任何一位陶土議會的成員拿一個圖騰!用它來釋放困在元素監獄的平民或衛兵!', `MaleText_loc7`='¡Consigue un tótem de cualquier miembro del Anillo de la Tierra! Utilízalo para sacar a los ciudadanos o defensores de las prisiones elementales!', `FemaleText_loc1`='대지 고리회 구성원 중 아무에게나 가서 토템을 받게! 토템을 사용해서 정령 감옥에 갇힌 주민과 병사를 풀어주게.', `FemaleText_loc4`='你可以从任何大地之环成员那里取得图腾！用图腾将市民和防御者从元素囚牢中解救出来！', `FemaleText_loc5`='跟任何一位陶土議會的成員拿一個圖騰!用它來釋放困在元素監獄的平民或衛兵!', `FemaleText_loc7`='¡Consigue un tótem de cualquier miembro del Anillo de la Tierra! Utilízalo para sacar a los ciudadanos o defensores de las prisiones elementales!' WHERE `ID`=42436;
