UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄브라우 일가에 한 일은 고맙다고 전해달라고 했어. 너희 모두와 나눠 가지라며 이 황금더미도 주었지.', `MaleText_loc4`='她要我转告你们这群蠢货，她很欣赏我们替她对法布隆一家所做的一切。还给了我不少赏金，让我跟你们分。', `MaleText_loc5`='她要我跟你們這些蠢蛋說，她非常感謝你們在法布隆農場為她所做的。而且給了我一些金幣要我跟大家分了。', `MaleText_loc7`='Quería que os dijera, tarugos, que le satisface cómo llevamos el asunto de los Cejade. Me dio un montón de oro para repartirlo entre todos.' WHERE `ID`=42441;
