UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남의 이야기나 엿듣고 다니는 작자를 가르치는 방법은 한 가지밖에 없지.', `MaleText_loc4`='对惹人讨厌、一无是处的偷听者来说，只有一个待遇。', `MaleText_loc5`='對於沒路用兼討人厭的偷聽者，只有一種下場。', `MaleText_loc7`='Solo hay una forma de tratar a los fisgones apestosos e inútiles.' WHERE `ID`=42444;
