UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 부디 다른 형제들도 구해다오. 우리가 너희를 지원할 것이다!', `MaleText_loc4`='拜托了英雄们，求你们帮帮我的同胞，我们会帮助你们的！', `MaleText_loc5`='求求你，英雄們。幫助我的兄弟們，然後我們也會幫助你們!', `MaleText_loc7`='¡Por favor, héroes, ayudad a mis hermanos y nosotros os ayudaremos!' WHERE `ID`=42453;
