UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 군대를 먹여 살리는 건 쉬운 일이 아닐세. 할 일이 너무 많아. 자네, 도와줄 시간이 있나?', `MaleText_loc4`='喂饱 一支部落大军可不是件容易的事。我有许多活儿要干，你有时间帮帮我吗？', `MaleText_loc5`='要餵飽一整個部落軍隊並不是一件輕鬆的差事。我有很多的事情要做。你有空可以幫我嗎?', `MaleText_loc7`='Dar de comer a un ejército de la Horda no es tarea fácil. Tengo montones de cosas que hacer. ¿Tienes tiempo para echarme una mano?', `FemaleText_loc1`='호드 군대를 먹여 살리는 건 쉬운 일이 아닐세. 할 일이 너무 많아. 자네, 도와줄 시간이 있나?', `FemaleText_loc4`='喂饱 一支部落大军可不是件容易的事。我有许多活儿要干，你有时间帮帮我吗？', `FemaleText_loc5`='要餵飽一整個部落軍隊並不是一件輕鬆的差事。我有很多的事情要做。你有空可以幫我嗎?', `FemaleText_loc7`='Dar de comer a un ejército de la Horda no es tarea fácil. Tengo montones de cosas que hacer. ¿Tienes tiempo para echarme una mano?' WHERE `ID`=42455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 여기 있지 않았나! 뭘 봤지? 어서 말해!', `MaleText_loc4`='你当时就站在这儿！你究竟看见了什么？快说！', `MaleText_loc5`='你們剛剛就站在這裡!你們到底看到了什麼東西?快說!', `MaleText_loc7`='¡Estabas justo ahí! ¿Qué demonios viste! ¡Habla!' WHERE `ID`=42456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 아무것도 못 봤습니다! 자... 자연사인 것 같아요.', `MaleText_loc4`='我……我什么也没看见！他……他是自然死亡的。', `MaleText_loc5`='我...我什麼都沒看到!他...他是自然死亡的。', `MaleText_loc7`='¡No... No vi nada! Murió... Murió de causas naturales.', `FemaleText_loc1`='아... 아무것도 못 봤습니다! 자... 자연사인 것 같아요.', `FemaleText_loc4`='我……我什么也没看见！他……他是自然死亡的。', `FemaleText_loc5`='我...我什麼都沒看到!他...他是自然死亡的。', `FemaleText_loc7`='¡No... No vi nada! Murió... Murió de causas naturales.' WHERE `ID`=42457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자연사라고? 가슴에서 총알 두 발이 나오고 신발을 머리에 뒤집어쓴 채 죽었는데 세상에 이런 자연사가 어디 있나?', `MaleText_loc4`='自然死亡？胸部中了两枪，鞋子也跑到头上去了。什么样的自然死亡会是这种效果？', `MaleText_loc5`='自然死亡?胸口兩個彈孔，鞋子跑到頭上。這是哪門子的自然死亡?', `MaleText_loc7`='¿Causas naturales? Dos balazos en el pecho y los zapatos en la cabeza. ¿Qué tipo de muerte natural es esa?' WHERE `ID`=42458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 수를 써서라도 세계 기둥을 원상복구해야 합니다.$B$B그러려면 먼저 세계 기둥 파편을 모두 찾아야 합니다.', `FemaleText_loc4`='我们必须不惜一切代价将世界之柱碎片重新拼合在一起。$B$B但首先，我们得先找齐它们。', `FemaleText_loc5`='我們不惜一切也必須將世界之柱的碎片組合起來。$B$B前題是，我們先得收集完全部的碎片。', `FemaleText_loc7`='Debemos hacer lo que sea para recombinar los fragmentos del Pilar del Mundo.$b$bPero antes tenemos que recuperarlos todos.' WHERE `ID`=42459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평생을 서부 몰락지대에서 살았기에, 전 이곳이 가시덤불 골짜기의 북쪽에서 가장 번성하던 농경지였던 그때를 기억합니다. 하지만, 그 시절은 오래전에 지났습니다.$b$b문제를 일으키던 데피아즈단을 몰아내고 나서도, 공포의 시대가 남긴 잔재들이 아직도 느껴집니다.$b$b게다가, 우린 역사상 최악의 경제 불황을 겪고 있습니다. 스컬지와 싸우는 데 퍼부은 그 많은 돈이, 군 관련 직업이 아니었던 사람들을 실업자로 만들고 결국엔 부랑자로 만든 겁니다.$B$B그 사람들이 결국 어디에 모였을 것 같습니까?', `MaleText_loc4`='我这辈子都没离开过西部荒野，$g兄弟:姐妹;。我还记得西部荒野曾是荆棘谷这一侧最富生机的地方。那些日子已经一去不复返了。$B$B尽管我们摆脱了迪菲亚制造的麻烦，但他们恐怖统治的影响至今犹存。更糟糕的是，我们现在正面临有史以来最严重的经济危机。由于我们将所有的积蓄都拿去对付天灾军团，所以那些不在军中任职的普通百姓全都陷入失业与最终无家可归的境地。$B$B你猜这些人最后怎么办了？', `MaleText_loc5`='這位$g小兄弟:小姐;，我這輩子一直都住在西部荒野。我還記得，以前西部荒野可是荊棘谷西北邊最林木茂盛的土地，不過現在一切都變了。$B$B雖然迪菲亞盜賊已經不再惹是生非了，但你還是可以感受得到他們的恐怖統治的後續影響。雪上加霜的是，我們正面臨著有史以來最嚴重的經濟蕭條。國庫所有的錢都拿去跟天譴軍團作戰用了，凡是跟軍隊無關的人失去了工作，然後也失去了家園。$B$B猜猜看，這些人最後都變什麼了?', `MaleText_loc7`='Llevo toda la vida en los Páramos de Poniente, $ghermano:hermana;. Recuerdo los días en los que los Páramos de Poniente eran la tierra más exuberante a este lado de la Vega de Tuercespina. Aquellos días desaparecieron hace tiempo.$B$BAunque ya no tenemos a la Hermandad Defias causando problemas como antes, las consecuencias de su reino de terror todavía son patentes. Para empeorar las cosas aún más, estamos sufriendo la peor crisis económica de toda nuestra historia. Todo el oro que gastamos luchando contra la Plaga hizo que los que no estuvieran ocupados en algo relacionado con el ejército se quedaran sin trabajo y, al final, sin casa.$B$B¿Adivinas dónde terminó toda esa gente?' WHERE `ID`=42460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 대지 고리회가 잠시 침략을 멈추게 하였다. 하지만 기억하라. 정령은 반드시 돌아올 것이다!', `MaleText_loc4`='够了！大地之环暂时阻止了入侵。但小心点，元素会再回来的！', `MaleText_loc5`='夠了!陶土議會可以暫時的阻止這次的入侵。但是你必須知道，元素們會再回來的!', `MaleText_loc7`='¡Basta! El Anillo de la Tierra detendrá la invasión de forma temporal. Pero te avisamos: ¡los elementales volverán!', `FemaleText_loc1`='그만! 대지 고리회가 잠시 침략을 멈추게 하였다. 하지만 기억하라. 정령은 반드시 돌아올 것이다!', `FemaleText_loc4`='够了！大地之环暂时阻止了入侵。但小心点，元素会再回来的！', `FemaleText_loc5`='夠了!陶土議會可以暫時的阻止這次的入侵。但是你必須知道，元素們會再回來的!', `FemaleText_loc7`='¡Basta! El Anillo de la Tierra detendrá la invasión de forma temporal. Pero te avisamos: ¡los elementales volverán!' WHERE `ID`=42461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악, 전원 선미로. 한 놈이 올라탔다고. 쏴 버려! 어서!', `MaleText_loc4`='啊——后甲板集合。有敌人登船了。射击！干掉它！', `MaleText_loc5`='呃 - 全體船尾集合! 有人登上來了。射牠! 殺死牠!', `MaleText_loc7`='Egah: todos a popa. Uno abordó. ¡Dispárenle! ¡Mátenlo!' WHERE `ID`=42462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구든 좋으니 어떻게 좀 해봐!! 며, 명령이다!', `MaleText_loc4`='来人呐，快做点什么！这是命令！', `MaleText_loc5`='來人啊，做點什麼!這是命令!', `MaleText_loc7`='¡Que alguien HAGA ALGO! ¡Es una orden!' WHERE `ID`=42463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 돛대에 붙어 있습니다!', `MaleText_loc4`='它被缠在索具里了。', `MaleText_loc5`='他被網纏住了。', `MaleText_loc7`='Se enredó en el aparejo.' WHERE `ID`=42464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했다, 영웅들이여! 저 마녀가 이 괴물을 통과시켜 보내려 했던 그 차원문을 사용해서 스톰윈드로 돌아가자! 도시에서 날 기다리고 있는 일이 많다.', `MaleText_loc4`='干得好，英雄们。这传送门本来是用来送这怪物的，现在就让我们从这道门返回吧！在暴风城还有许多工作在等着我。', `MaleText_loc5`='做得好，英雄們。讓我們使用原本要讓這怪物穿過的傳送門回去吧!暴風城還有很多的事情在等我處理。', `MaleText_loc7`='Bien hecho, héroes. ¡Regresemos por el mismo portal por el que esa bruja quería enviar a esta bestia! Me espera mucho trabajo en Ventormenta.' WHERE `ID`=42465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 주위에 방어물을 설치해서 도시를 보호하십시오!$B$B도시 곳곳에 놓인 상자에서 방어물을 집어$B$B붉은색 화살표|Tinterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 설치하십시오.', `MaleText_loc4`='在奥格瑞玛附近布下路障来保卫城市！$B$B从散落在城市各个角落的箱子里拾取路障$B$B将它们安放在红色箭头|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t所标记的位置。', `MaleText_loc5`='在奧格瑪四周放置路障來保護它!$B$B由城市中散佈的路障箱中拿起路障$B$B然後放在標有紅色箭頭的地方|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc7`='¡Levanta barricadas por toda Orgrimmar para proteger la ciudad!$B$BRecoge una barricada de las cajas situadas por toda la ciudad$B$By colócalas en un sitio marcado con una flecha roja|TInterfaceIconsABILITY_HUNTER_MARKEDFORDEATH.blp:32|t.' WHERE `ID`=42466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이럴 줄 알았어. 뭐? 아주 쉬운 황무지 여행이 될 거라고?', `MaleText_loc4`='没错，她是这么说的：“只是一次前往废土的简单旅程，毫无压力。”', `MaleText_loc5`='她說當然沒問題，不過是個簡單的荒地之旅。', `MaleText_loc7`='Sí, claro, decía ella, no será más que un viajecito a los baldíos.' WHERE `ID`=42467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n 님. 당신의 친절함은 절대 잊지 않을 거예요.', `FemaleText_loc4`='谢谢你，$n。我们永远不会忘记你的慷慨相助。', `FemaleText_loc5`='謝謝你，$n。你的好心我一定不會忘記的。', `FemaleText_loc7`='Gracias, $n. Tu amabilidad no será olvidada.' WHERE `ID`=42468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저녁식사가 준비됐으니 어서 와서 먹으렴!', `FemaleText_loc4`='开饭啦！快来吃吧！', `FemaleText_loc5`='晚餐好了!來吃吧!', `FemaleText_loc7`='¡La cena está lista! ¡Ven a por ella!' WHERE `ID`=42469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 기쁠 수가. 고마워요, 어머니. 그리고 감사합니다, $n 님.', `MaleText_loc4`='我太高兴了。谢谢你，妈妈；也谢谢你，$n。', `MaleText_loc5`='我太高興了。謝謝你，媽媽。還有謝謝你，$n。', `MaleText_loc7`='Estoy tan contento. ¡Gracias, mamá, y gracias, $n!', `FemaleText_loc1`='이렇게 기쁠 수가. 고마워요, 어머니. 그리고 감사합니다, $n 님.', `FemaleText_loc4`='我太高兴了。谢谢你，妈妈；也谢谢你，$n。', `FemaleText_loc5`='我太高興了。謝謝你，媽媽。還有謝謝你，$n。', `FemaleText_loc7`='Estoy tan contenta. ¡Gracias, mamá, y gracias, $n!' WHERE `ID`=42470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 폭발하려고 합니다! 낙하산을 착용하고 뛰어내리세요!', `MaleText_loc4`='她要炸了！快背好降落伞准备跳！', `MaleText_loc5`='要爆炸了!快拿降落傘，跳機逃生!', `MaleText_loc7`='¡Va a explotar! ¡Toma un paracaídas y salta!' WHERE `ID`=42471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 만세!', `MaleText_loc4`='为$n欢呼！', `MaleText_loc5`='$n太棒了!', `MaleText_loc7`='¡HURRA POR $n!', `FemaleText_loc1`='$n 님, 만세!', `FemaleText_loc4`='为$n欢呼！', `FemaleText_loc5`='$n太棒了!', `FemaleText_loc7`='¡HURRA POR $n!' WHERE `ID`=42472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 울음을 터뜨립니다.', `MaleText_loc4`='%s哭了。', `MaleText_loc5`='%s哭了。', `MaleText_loc7`='%s llora.', `FemaleText_loc1`='%s|1이;가; 울음을 터뜨립니다.', `FemaleText_loc4`='%s哭了。', `FemaleText_loc5`='%s哭了。', `FemaleText_loc7`='%s llora.' WHERE `ID`=42473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 모래 속으로 파고듭니다!', `MaleText_loc4`='%s把自己埋进了沙里！', `MaleText_loc5`='%s將自己埋到了沙地中!', `MaleText_loc7`='¡%s se entierra en la arena!' WHERE `ID`=42474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과부하된 허수아비골렘은 몰센 농장에서만 탈 수 있습니다.', `MaleText_loc4`='你只能在摩尔森农场使用过载的麦田傀儡。', `MaleText_loc5`='你只可在摩爾森農場駕駛超載的麥田魔像。', `MaleText_loc7`='Podrás montar el gólem de la cosecha sobrecargado solo en la Granja de Molsen.' WHERE `ID`=42475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화를 시작합니다... ...', `MaleText_loc4`='正在初始化清除……', `MaleText_loc5`='開始清理... ...', `MaleText_loc7`='Iniciando limpieza... ...' WHERE `ID`=42476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 추락합니다!', `MaleText_loc4`='舰体严重损毁，长官！', `MaleText_loc5`='船要裂開了，長官!', `MaleText_loc7`='¡Se está quebrando, señor!' WHERE `ID`=42477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 무기에 화약 채워. 장비 있는 대로 짊어지고! 해안으로 방향 잡아!', `MaleText_loc4`='抛去全部多余负重。加固装备舱。让飞船转向岸边。', `MaleText_loc5`='保持冷靜。固定好運輸設備。轉向海岸前進。', `MaleText_loc7`='Apisonen los inflamantes. Alistonen el carruaje de equipo. Timón hacia la costa.' WHERE `ID`=42478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원 낙하산 장착!', `MaleText_loc4`='全部准备跳伞！', `MaleText_loc5`='所有人，去拿你們的降落傘!', `MaleText_loc7`='¡Todos a los paracaídas!' WHERE `ID`=42479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구조 요청! 구조 요청! 모두 탈출해. 탈출하라고!', `MaleText_loc4`='求救！求救！求救！所有人跳伞。跳！', `MaleText_loc5`='求救!求救!求救!所有人逃生!快逃!', `MaleText_loc7`='¡Mayday! ¡Mayday! ¡Mayday! Salten todos. ¡SALTEN!' WHERE `ID`=42480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 여러 조각으로 흩어집니다!', `MaleText_loc4`='%s消散了！', `MaleText_loc5`='%s消散了!', `MaleText_loc7`='¡%s se dispersa!' WHERE `ID`=42481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도가 치고, 햇살이 비치는 이곳에서도 어딘가 도사리는 어둠의 기운이 느껴지는군.$b$b참 흥미롭기도 하지. 안 그렇소?', `MaleText_loc4`='就算是在这儿——在这海浪与暖日的环抱下，我都能感觉到在这些土地上涌动的黑暗力量。$B$B这可真有趣儿，你不觉得吗？', `MaleText_loc5`='即使在這裡，雖然有美麗的陽光和海浪，我依然可以感覺到潛伏在這片土地裡的邪惡。$B$B真是迷人，你不覺得嗎?', `MaleText_loc7`='Incluso aquí, entre el surf y el sol, puedo sentir que la oscuridad camina por estar tierras.$B$BEs fascinante, ¿no crees?' WHERE `ID`=42482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도가 치고 햇살이 내리쬐는 이곳에 있어도, 전 이 땅에 숨어있는 어둠의 기운을 느낄 수 있어요.$b$b참 흥미롭지 않나요?', `MaleText_loc4`='就算是在这儿——在这海浪与暖日的环抱下，我都能感觉到在这些土地上涌动的黑暗力量。$B$B这可真有趣儿，你不觉得吗？', `MaleText_loc5`='即使在這裡，雖然有美麗的陽光和海浪，我依然可以感覺到潛伏在這片土地裡的邪惡。$B$B真是迷人，你說是吧?', `MaleText_loc7`='Incluso aquí, entre el surf y el sol, puedo sentir que la oscuridad camina por estar tierras.$B$BEs fascinante, ¿no?' WHERE `ID`=42483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들아, 사라져라! 정기의 골짜기는 우리 것이다!', `MaleText_loc4`='赶走元素！精神谷是我们的！', `MaleText_loc5`='元素們滾回去!精神谷是我們的!', `MaleText_loc7`='¡Los elementales desaparecen! ¡El Valle de los Eh''píritus es nueh''tro!' WHERE `ID`=42484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 호드를 섬기는 최후의 숲트롤 부족이라는 사실을 자랑스럽게 생각한다네.$b$b결국에는 우리가 다른 부족과 드워프를 물리치고 동부 내륙지를 차지하게 될 걸세.', `MaleText_loc4`='我们自豪地宣称，我们是效忠于部落的森林巨魔最后的部族。$B$B总有一天，我们将战胜其它部族，还有那些矮人，辛特兰将属于我们。', `MaleText_loc5`='我們是部落旗下最後的一支森林食人妖部族，這點我們非常自豪。$B$B我們遲早會戰勝其他的部族還有矮人，將整個辛特蘭納為我們的領土。', `MaleText_loc7`='Eh''tamos orgullosos de ser la última tribu de los trols del bosque que sirven a la Horda.$B$BCon el tiempo, conquih''taremos a las otras tribus y a los enanos y las Tierras del Interior serán nueh''tras.' WHERE `ID`=42485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 참 친절하고 상냥하시네요.', `MaleText_loc4`='谢谢你，和善有礼的陌生人。', `MaleText_loc5`='謝謝你，善良和溫柔的陌生人。', `MaleText_loc7`='Gracias, amable y gentil $gextraño:extraña;.', `FemaleText_loc1`='고맙습니다. 참 친절하고 상냥하시네요.', `FemaleText_loc4`='谢谢你，和善有礼的陌生人。', `FemaleText_loc5`='謝謝你，善良和溫柔的陌生人。', `FemaleText_loc7`='Gracias, amable y gentil $gextraño:extraña;.' WHERE `ID`=42486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 설마... 서부정통 스튜? 이 순간은 평생 잊지 못할 겁니다!', `MaleText_loc4`='杂味炖肉？我永远都不会忘了这一刻！', `MaleText_loc5`='西部荒野燉肉?我永遠不會忘記這一刻!', `MaleText_loc7`='¿Estofado de los Páramos de Poniente? ¡Nunca olvidaré este momento!', `FemaleText_loc1`='이건 설마... 서부정통 스튜? 이 순간은 평생 잊지 못할 겁니다!', `FemaleText_loc4`='杂味炖肉？我永远都不会忘了这一刻！', `FemaleText_loc5`='西部荒野燉肉?我永遠不會忘記這一刻!', `FemaleText_loc7`='¿Estofado de los Páramos de Poniente? ¡Nunca olvidaré este momento!' WHERE `ID`=42487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 냄새는 어디에서도 맞출 수 있어요! 살마 아줌마의 특제 스튜 냄새 맞죠?', `MaleText_loc4`='不论走到哪儿都会牢记的味道！萨尔玛的拿手炖肉！', `MaleText_loc5`='到哪裡我都聞得出這個味道!薩爾瑪最有名的燉肉!', `MaleText_loc7`='¡Reconocería ese olor en cualquier lugar! ¡El famoso estofado de Salma!', `FemaleText_loc1`='이 냄새는 어디에서도 맞출 수 있어요! 살마 아줌마의 특제 스튜 냄새 맞죠?', `FemaleText_loc4`='不论走到哪儿都会牢记的味道！萨尔玛的拿手炖肉！', `FemaleText_loc5`='到哪裡我都聞得出這個味道!薩爾瑪最有名的燉肉!', `FemaleText_loc7`='¡Reconocería ese olor en cualquier lugar! ¡El famoso estofado de Salma!' WHERE `ID`=42488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면... 삶은 살 가치가 있을지도 몰라요.', `MaleText_loc4`='也许……也许活着是有意义的。', `MaleText_loc5`='或許...或許生命是有意義的。', `MaleText_loc7`='Quizá... quizá merezca la pena vivir la vida.', `FemaleText_loc1`='어쩌면... 삶은 살 가치가 있을지도 몰라요.', `FemaleText_loc4`='也许……也许活着是有意义的。', `FemaleText_loc5`='或許...或許生命是有意義的。', `FemaleText_loc7`='Quizá... quizá merezca la pena vivir la vida.' WHERE `ID`=42489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께 축복을...', `MaleText_loc4`='祝福你，朋友。', `MaleText_loc5`='祝福你，朋友。', `MaleText_loc7`='Tienes mi bendición.', `FemaleText_loc1`='당신께 축복을...', `FemaleText_loc4`='祝福你，朋友。', `FemaleText_loc5`='祝福你，朋友。', `FemaleText_loc7`='Tienes mi bendición.' WHERE `ID`=42490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜는 언젠가 반드시 갚겠습니다.', `MaleText_loc4`='也许有一天我将报答你的善举。', `MaleText_loc5`='或許有天我能歸還你這個人情。', `MaleText_loc7`='Quizá algún día pueda devolverte el favor de un acto tan amable.', `FemaleText_loc1`='이 은혜는 언젠가 반드시 갚겠습니다.', `FemaleText_loc4`='也许有一天我将报答你的善举。', `FemaleText_loc5`='或許有天我能歸還你這個人情。', `FemaleText_loc7`='Quizá algún día pueda devolverte el favor de un acto tan amable.' WHERE `ID`=42491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴 수가 없군요. 흑마법사 훈련을 받고자 한다면, 볼드레카와 대화해 보시기 바랍니다.', `MaleText_loc4`='我帮不了你。要是你想进行术士训练的话，可以去找沃德雷卡。', `MaleText_loc5`='我幫不了你。要接受術士訓練的話，請去找沃德瑞卡。', `MaleText_loc7`='No pue''o ayudah''te. Vete a hablar con Voldreka si quieres recibir inh''trucción como $gbrujo:bruja;.', `FemaleText_loc1`='도와드릴 수가 없군요. 흑마법사 훈련을 받고자 한다면, 볼드레카와 대화해 보시기 바랍니다.', `FemaleText_loc4`='我帮不了你。要是你想进行术士训练的话，可以去找沃德雷卡。', `FemaleText_loc5`='我幫不了你。要接受術士訓練的話，請去找沃德瑞卡。', `FemaleText_loc7`='No pue''o ayudah''te. Vete a hablar con Voldreka si quieres recibir inh''trucción como $gbrujo:bruja;.' WHERE `ID`=42492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습을 통해 자네는 흑마법이 어떤 무기보다도 훨씬 강하다는 걸 알아채게 될 걸세.', `MaleText_loc4`='心智的训练，你会发现黑暗艺术要比任何武器都要强大得多。', `MaleText_loc5`='聰明的行為，你會發現黑暗魔法比任何武器都要來的利害。', `MaleText_loc7`='Con práctica deh''cubrirás que las ah''tes oscuras son mucho más poderosas que cualquier arma.' WHERE `ID`=42493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 트롤은 우리 종족을 꽤 잘 받아주는 것 같네. 따지고 보면 포세이큰이 탄생하기 수세기 전부터 죽은 자와 대화해 온 자들 아닌가?$b$b이런 점이 사업에 도움이 된다네.', `FemaleText_loc4`='这里的巨魔很能接受像我这样的人。毕竟，在被遗忘者还没出现时，他们就已经与死者交流了几个世纪。$B$B这是个很好的契机。', `FemaleText_loc5`='這邊的食人妖對我的接受度還蠻高的。畢竟，在被遺忘者出現之前，他們跟死人講話的習慣已經維持了好幾個世紀。$B$B對生意還蠻有幫助的。', `FemaleText_loc7`='Los trols aceptan bastante bien a los de mi especie. Después de todo llevan siglos hablando con los muertos, mucho antes de que aparecieran los no-muertos.$B$BEs bueno para el negocio.' WHERE `ID`=42494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어릴 때 우리 가족은 제가 주술에 관심 보이는 걸 인정해 주지 않았죠. 어리석었던 저는 자신만만하게도 집을 뛰쳐나와 독학을 시작했어요. 어느 날 집에 돌아갔더니, 부모님께서 안 계셨더랬죠. 집이 무너진 거예요. 누가 그랬는지도 몰라요.

그때부터 전 과거를 보기 위해 주술사 수업에 매진했어요. 우리 가족에게 무슨 일이 일어났고, 누가 한 짓인지 알아내려고요. 고난의 길이었죠. 가까운 과거에 일어난 큰 사건을 집중적으로 볼 수는 있게 되었지만, 더 오래전에 일어난 일을 엿보려면 아직 멀었어요.', `FemaleText_loc4`='在我小时候，我的家人不许我研习萨满巫术。任性而愚蠢的我竟然从他们身边逃离，一个人学习了起来。有一天当我回到故乡，却发现父母都已不在。我的家园也已被毁。没人知道是谁下的手。

我耗尽毕生的精力，想要延展我萨满的视野来回望过去——查明在我家人身上究竟发生过什么，谁该对此负责。我一路走来历尽艰辛。现在我已学会将意念集中在于不久前发生的重大事件上，可要想获知发生在那么久之前的事，我还有很长的路要走。', `FemaleText_loc5`='在我年輕的時候，我的家人們並不贊同我對學習薩滿知識的熱誠。當時的我既衝動又愚蠢，於是我逃家自行去修練了。等到有一天我終於回家去的時候，我才發現我爸媽已經不在，家園被毀，而且他們一直沒找到是誰幹的。

我畢生都在努力修練如何將我的薩滿預知能力延伸推向過去，找出我家到底發生了什麼，而且兇手又是誰。雖然我已經有了長足的進展，總算有辦法聚焦在幾個重大的過去事件上，但我還是有許多關鍵要一一克服，才有辦法完整窺見多年前那場悲劇的真實面貌。', `FemaleText_loc7`='En mi juventud, a mi familia no le sentó bien que tuviera interés en el chamanismo. Yo era tonta y descarada y me escapé de casa para aprender por mi cuenta. Cuando un día regresé a mi casa, vi que mis padres ya no estaban. Mi casa estaba destrozada. Nunca encontraron a los culpables.

Me he pasado toda la vida esforzándome por ampliar mi visión chamanística para ver el pasado; para averiguar qué le ocurrió a mi familia y quién es el responsable. He avanzado mucho. He aprendido a concentrarme en hechos impactantes del pasado reciente, pero aún me queda mucho por aprender si alguna vez espero poder ver algo que ocurrió hace tanto tiempo.' WHERE `ID`=42495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 마법을 걸어 준 외날창을 잃어버렸습니다. 혹시 보셨습니까?', `MaleText_loc4`='我忘记把你给我的魔能之刃放哪儿了。你看见过吗？', `MaleText_loc5`='我不知把你給我那附過魔的劍放到哪去了。你有看到它嗎?', `MaleText_loc7`='He perdido la espada encantada que me diste. ¿La has visto?', `FemaleText_loc1`='당신이 마법을 걸어 준 외날창을 잃어버렸어요. 혹시 보셨나요?', `FemaleText_loc4`='我忘记把你给我的魔能之刃放哪儿了。你看见过吗？', `FemaleText_loc5`='我不知把你給我那附過魔的劍放到哪去了。你有看到它嗎?', `FemaleText_loc7`='He perdido la espada encantada que me diste. ¿La has visto?' WHERE `ID`=42496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<석상 앞에 서자 세찬 바람이 석상을 지나 당신에게 불어옵니다.>', `MaleText_loc4`='<当你站在塑像面前时，你感觉到一阵风呼啸而过。>', `MaleText_loc5`='<當你站在雕像前，一陣狂風吹了過去。>', `MaleText_loc7`='<El viento aúlla alrededor de la estatua cuando te pones delante.>' WHERE `ID`=42497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아킬다라, 저를 동료들에게 보내주십시오.', `MaleText_loc4`='阿基尔达拉，把我送回盟友那里。', `MaleText_loc5`='阿奇達拉，將我帶回盟友那。', `MaleText_loc7`='Akil''darah, llévame de vuelta con mis aliados.', `FemaleText_loc1`='아킬다라, 저를 동료들에게 보내주세요.', `FemaleText_loc4`='阿基尔达拉，把我送回盟友那里。', `FemaleText_loc5`='阿奇達拉，將我帶回盟友那。', `FemaleText_loc7`='Akil''darah, llévame de vuelta con mis aliados.' WHERE `ID`=42498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진타알로는 우리 것이 될 걸세, 친구. 썩은가지 부족은 쇠약하고 고약한 배신자들이야. 로아의 가호를 받을 자격이 없는 것들이지.', `MaleText_loc4`='辛萨罗一定属于我们，朋友。邪枝部族只不过是软弱而令人生厌的背叛者，他们不配得到神灵的眷顾。', `MaleText_loc5`='辛薩羅會變成我們的，老兄。邪枝部族是懦弱、卑鄙的叛徒，沒有獲得神靈眷顧的資格。', `MaleText_loc7`='Jintha''alor será nueh''tro, colega. Los Vilrama son traidores débiles y deh''preciables que no se merecen el favo'' de los loa.' WHERE `ID`=42499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정원 중간층에 있는 아킬다라에게 보내주십시오.', `MaleText_loc4`='送我到平台中央的阿基尔达拉那里去。', `MaleText_loc5`='將我送到中央區的阿奇達拉那。', `MaleText_loc7`='Envíame junto a Akil''darah, en la terraza del medio.', `FemaleText_loc1`='정원 중간층에 있는 아킬다라에게 보내주세요.', `FemaleText_loc4`='送我到平台中央的阿基尔达拉那里去。', `FemaleText_loc5`='將我送到中央區的阿奇達拉那。', `FemaleText_loc7`='Envíame junto a Akil''darah, en la terraza del medio.' WHERE `ID`=42500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 적극적으로 협조하겠습니다, 반장님. 펄브라우 가족은 좋은 사람들이었어요. 그들의 죽음은 반드시 그 대가를 치러야 할 것입니다.', `MaleText_loc4`='你会得到我们全力的配合，中尉。法布隆一家是好人。他们决不会枉死。', `MaleText_loc5`='我們會全力配合，中尉。法布隆家的人都是好人。我們一定會揪出害死他們的兇手。', `MaleText_loc7`='Tienes toda nuestra cooperación, teniente. Los Cejade eran buena gente. Sus asesinos serán castigados.' WHERE `ID`=42505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식이군, 치안대장. $n|1이;가; 범죄자들에겐 정의의 심판을 내렸지만, 놈들의 우두머리는 아직 못 잡았네. 그래도 서부 몰락지대 여단의 도움이면 이번 사건을 잘 마무리 지을 수 있을 것 같군.', `MaleText_loc4`='这是个好消息，长官。可尽管$n已经将行凶者绳之以法，但他们的主谋却仍逍遥法外。也许在西部荒野人民军的协助下，我们终于能够了结这个案子。', `MaleText_loc5`='很高興聽你這麼說，斯托曼。雖然$n已經讓犯人自食惡果，但他們的頭目還是逍遙法外。或許在得到了西荒兵團的幫助後我們終於可以解決這個案件。', `MaleText_loc7`='Me alegra oírlo, mariscal. $n ha apresado a los autores del crimen, pero el cabecilla sigue libre. Quizá con la ayuda de la Brigada de los Páramos de Poniente podremos finalmente resolver este caso.' WHERE `ID`=42506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁금한 게 있는데. 이 늑대인간은 어쩌다 여기 잡아넣게 된 거지?', `MaleText_loc4`='请允许我问一下，那里面关着的狼人是怎么回事儿？', `MaleText_loc5`='請問，戴上枷鎖的的狼人是怎麼了?', `MaleText_loc7`='¿Puedo preguntar qué pasa con el huargen que hay en el cepo?' WHERE `ID`=42507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변두리 지역에서 양을 학살하고 있기에 잡아넣었죠. 고집이 세고 쉽게 흥분하는 녀석입니다. 충분히 떨어지십시오, 반장님.', `MaleText_loc4`='这畜生在村庄里屠杀羊群时被我们抓住了。他死不悔改，脾气极为暴躁。千万别靠得太近，中尉。', `MaleText_loc5`='我們在村裡抓到這隻野獸正在屠殺綿羊。他毫無悔意，而且十分激動。中尉，不要靠太近。', `MaleText_loc7`='Pillamos a esa bestia masacrando ovejas en el campo. No se arrepiente y se pone nervioso con facilidad. No te acerques mucho, teniente.' WHERE `ID`=42508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 부수고 나가면 네 심장을 도려내 통째로 삼켜버릴 테다!', `MaleText_loc4`='有本事别让我逃出去，否则我就要把你的心挖出来一口吃掉！', `MaleText_loc5`='等我掙脫這個枷鎖，我要把你的心臟挖出來，一口吃掉!', `MaleText_loc7`='¡Cuando me libere de este cepo voy a arrancarte el corazón y a comérmelo entero!' WHERE `ID`=42509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 치안대장 말이 농담이 아니었군.', `MaleText_loc4`='哇哦，治安官看来没开玩笑。', `MaleText_loc5`='哇噢，斯托曼不是在開玩笑的。', `MaleText_loc7`='Vaya, el mariscal no bromeaba.' WHERE `ID`=42510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 네놈이 그렇게 짖어댄다고 해서...', `MaleText_loc4`='可你的吠叫……', `MaleText_loc5`='不過，你是真的會咬人...', `MaleText_loc7`='Pero es tu ladrido...' WHERE `ID`=42511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 밖으로 나올 수 있을 것 같나?', `MaleText_loc4`='比你的撕咬还凶狠？', `MaleText_loc5`='還是只會亂吠鬼叫呢?', `MaleText_loc7`='¿Peor que tu mordedura?' WHERE `ID`=42512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 너무 멀리 왔다. 주제넘은 짓을 한 대가를 톡톡히 치르게 해주지!', `MaleText_loc4`='你们太过火了，毒蛇。你们会为这次入侵付出惨重的代价！', `MaleText_loc5`='你們挑戰了我的極限，小蛇。你們將會為你們的侵入付出慘痛的代價。', `MaleText_loc7`='Has ido demasiado lejos, serpiente. ¡Sufrirás mucho por tu transgresión!' WHERE `ID`=42518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 해저로 숨으려 합니다!', `MaleText_loc4`='%s试图藏在海底！', `MaleText_loc5`='%s試著藏身於海底!', `MaleText_loc7`='¡%s intenta esconderse en el fondo marino!' WHERE `ID`=42526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서의 전쟁이 사람들을 이 지경으로 몰아 넣었습니다, $n 님. 우리가 얼어붙은 땅에서 승리를 거두고 있었을 때, 정작 우리 땅의 사람들은 큰 혼란 속에 하나 둘 쓰러지고 있었단 말입니다.
', `MaleText_loc4`='诺森德的战火给我们所有人都造成了损失，$n。尽管我们在寒冰荒野上取得了胜利，我们自己的土地却陷入了混乱。', `MaleText_loc5`='北裂境之戰對我們的人民來說犧牲慘重，$n。當我們在那片冰凍荒原取得勝利時，我們的家鄉卻變得一團亂。', `MaleText_loc7`='La guerra de Rasganorte nos pasa factura, $n. Mientras salíamos victoriosos en los baldíos helados, nuestras tierras caían en la confusión y el desorden.' WHERE `ID`=42527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭔지 알아 보겠나, 이 괴물 녀석아? 그 제독이란 작자는 누구지? 어서 말해!', `MaleText_loc4`='关于这件事你到底知道些什么，怪物？谁是首领？快说！', `MaleText_loc5`='你知道這件事情嗎，野獸?上將是誰?說!', `MaleText_loc7`='¿Sabes algo sobre esto, bestia? ¿Quién es el almirante? ¡Habla!' WHERE `ID`=42528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 시대가 올 것이다, 스타우트맨틀. 그리고 그 시대가 도래하면 네 목숨은 끝난 거나 마찬가지지.', `MaleText_loc4`='黎明来临了，斯托曼，你的末日也将到随之到来。', `MaleText_loc5`='「黎明」將至，斯托曼，屆時就是你的死期。', `MaleText_loc7`='Se acerca el amanecer, Mantorrecio, y con él llega tu final.' WHERE `ID`=42529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미친 늑대가 헛소리를 하는군. 쳇!', `MaleText_loc4`='一头疯狼的胡言乱语。啊呸！', `MaleText_loc5`='哼，聽你這隻瘋狼在亂吠!', `MaleText_loc7`='Tonterías pronunciadas por un lobo loco. ¡Bah!' WHERE `ID`=42530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤는 제게 맡겨 두세요, $n 님.', `FemaleText_loc4`='包在我身上，$n。', `FemaleText_loc5`='我會掩護你，$n。', `FemaleText_loc7`='Te cubro, $n.' WHERE `ID`=42531;
