UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀들이 실패했습니다, 주인님.', `MaleText_loc4`='那群豺狼人失败了，女主人。', `MaleText_loc5`='豺狼人失敗了，小姐。', `MaleText_loc7`='Los gnolls han fracasado, señora.' WHERE `ID`=42536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들은 연막에 불과했다. 계획에는 차질이 없을 거다.', `FemaleText_loc4`='他们已经成功牵扯了敌人的注意力。我们按计划继续。', `FemaleText_loc5`='他們已成功轉移了焦點。我們繼續照計畫進行。', `FemaleText_loc7`='Han proporcionado la distracción que queríamos. Continuamos con lo planeado.' WHERE `ID`=42537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 주인님, 제독님이 아직...', `MaleText_loc4`='可是女主人，将军仍然……', `MaleText_loc5`='但...小姐，上將還...', `MaleText_loc7`='Pero señora, el almirante está tod...' WHERE `ID`=42538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님은 새 시대가 떠오를 그날 구출할 것이다.', `FemaleText_loc4`='我们将在黎明之时把将军放出来。', `FemaleText_loc5`='我們會在黎明行動時讓上將重獲自由。', `FemaleText_loc7`='Liberaremos al almirante al amanecer.' WHERE `ID`=42539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 주인님.', `MaleText_loc4`='是，女主人。', `MaleText_loc5`='是，小姐。', `MaleText_loc7`='Sí, señora.' WHERE `ID`=42540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심판의 날이 머지않았다, 헬릭스.', `FemaleText_loc4`='审判日很快就要到来了，赫利克斯。', `FemaleText_loc5`='審判日即將到來，赫利克斯。', `FemaleText_loc7`='El día del Juicio pronto caerá sobre nosotros, Helix.' WHERE `ID`=42541;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들을 불러모아라. 새 시대가 시작되기 전에 마지막으로 연설하겠다.', `FemaleText_loc4`='叫来我的人民。我想在黎明到来之前再对他们讲最后一次话。', `FemaleText_loc5`='聚集大家。我希望在黎明行動前跟他們說最後一次話。', `FemaleText_loc7`='Convoca a todo el mundo. Deseo hablarles una última vez antes del amanecer.' WHERE `ID`=42542;
