UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈자르와 근위병들이다! 목숨을 걸고 싸워라!', `MaleText_loc4`='纳兹夏尔和她的荣誉守卫！拼死一战吧！', `MaleText_loc5`='納茲賈爾和她的榮譽守衛...是拼命的時候了!', `MaleText_loc7`='¡Naz''jar y su guardia de honor! ¡Luchen por sus vidas!' WHERE `ID`=42549;
