UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 내가 만든 녀석이야! 난 이 녀석을 "쌩쌩이"라고 부르지.', `MaleText_loc4`='这个孩子只属于我！我叫她“节流圈儿”。', `MaleText_loc5`='這個寶貝是完全屬於我的!我稱她為「窒息者」。', `MaleText_loc7`='¡Esta belleza es toda mía! Lo llamo "El Acelerador".' WHERE `ID`=42556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검사 준비 완료됐다고! 살살 다뤄 줘.', `MaleText_loc4`='准备好检查了！……记得温柔一点。', `MaleText_loc5`='準備好接受檢查了!...溫柔一點。', `MaleText_loc7`='¡Listo para inspección! ... Ten cuidado.' WHERE `ID`=42557;
