UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 아무리 맞아도 계속해서 적을 혼내주는 파괴전차라고!', `MaleText_loc4`='没错。稍事休息，再接再厉！', `MaleText_loc5`='這就對了。就算遭受打擊還是如此強大!', `MaleText_loc7`='Cierto. ¡Las críticas lo han vapuleado, pero todavía puede patear traseros!' WHERE `ID`=42559;
