UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 저기, 괜찮다고! 아주 작은 문제가 하나 있을 뿐이야. 알지?', `MaleText_loc4`='看哪，看哪，没事了！只是个小得不能再小的小故障。看到没有？', `MaleText_loc5`='你看，你看，沒問題!只是一點小故障罷了。看?', `MaleText_loc7`='¡Mira, mira, está bien! Es solo un minúsculo fallo de sistema. ¿Ves?' WHERE `ID`=42562;
