UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이래서 기술자는 하기 싫었는데.', `MaleText_loc4`='我……不管怎样我从来都没想过要当工程师。', `MaleText_loc5`='我...我本來就從不想當個工程師。', `MaleText_loc7`='De todas formas yo... yo nunca quise ser ingeniero.' WHERE `ID`=42564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 말이야... 언제나 춤꾼이 되고 싶었다고! 기계는 무서워.
', `MaleText_loc4`='我一直想当个……舞者！电动工具让我害怕。', `MaleText_loc5`='我一直都想成為一個...舞蹈家!我怕這些能量工具。', `MaleText_loc7`='Siempre quise ser... ¡bailarín! Las herramientas de poder me asustan.' WHERE `ID`=42565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 나 발가락으로 서서 돌아다닐 수 있다? 나비처럼 우아하게 말이야. 볼래?', `MaleText_loc4`='我能旋舞。在脚尖上旋舞。就像只蝴蝶一样。想看看吗？', `MaleText_loc5`='我會飛喔。腳趾踮起來，我就像蝴蝶一樣。想看看嗎?', `MaleText_loc7`='Puedo flotar. Si ando de puntillas. Soy como una mariposa. ¿Quieres verlo?' WHERE `ID`=42566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 달아납니다.', `MaleText_loc4`='%s飞快地跑掉了。', `MaleText_loc5`='%s開始奔跑。', `MaleText_loc7`='%s echa a correr.' WHERE `ID`=42567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 출고할 수 있어. 땜질만 조금 하면 된다고!', `MaleText_loc4`='它还能用作船运。我稍微修修就好！', `MaleText_loc5`='還是可以拿去賣的。我只要修一下就好了!', `MaleText_loc7`='Sigue siendo lo bastante bueno para el lanzamiento. ¡Lo puedo arreglar más adelante con un parche!' WHERE `ID`=42568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 연설이 시작됩니다!', `FemaleText_loc4`='快要开始集结了！', `FemaleText_loc5`='集會就要開始了!', `FemaleText_loc7`='¡La reunión está a punto de comenzar!' WHERE `ID`=42569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제자매여! 모두 모여 내 말을 들어라!', `FemaleText_loc4`='集合，兄弟姐妹们！所有人都过来，听好了！', `FemaleText_loc5`='來呀，兄弟姐妹們，集合!全部人都過來，聽我說!', `FemaleText_loc7`='¡Venid, hermanos y hermanas! ¡Venid todos, y escuchad!' WHERE `ID`=42570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제자매여, 우리는 버림받았다. 스톰윈드로부터 버려진 고아들이다.', `FemaleText_loc4`='兄弟们。姐妹们。我们是被遗弃的——我们是暴风城的孤儿。', `FemaleText_loc5`='兄弟們，姐妹們。我們都被遺棄了─我們是暴風城的孤兒。', `FemaleText_loc7`='Hermanos. Hermanas. Hemos sido ABANDONADOS, somos los hijos huérfanos de Ventormenta.' WHERE `ID`=42571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"폐하"께선 금으로 만든 왕좌에 앉아 우리의 역경을 지켜보고만 계시지!', `FemaleText_loc4`='我们的“国王”高高坐在他那用黄金打造的宝座上，对我们的困境无动于衷。', `FemaleText_loc5`='我們的「國王」坐在他的黃金寶座上，對我們的困苦視若無睹!', `FemaleText_loc7`='¡Nuestro "rey" se sienta en su trono de oro y se encoge de hombros al escuchar nuestras súplicas!' WHERE `ID`=42572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그동안 우리 아들딸은 길거리에서 배고픔에 죽어간다!', `FemaleText_loc4`='与此同时，我们的孩子们却正饿死在我们脚下的这些条街道上！', `FemaleText_loc5`='同時，我們的孩子因為饑餓而死在這條街上!', `FemaleText_loc7`='¡Mientras tanto, nuestros hijos mueren de hambre en estas mismas calles!' WHERE `ID`=42573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='국왕이 벌인 전쟁 때문에 바쳐야 했던 건 우리 삶이었다. 얼라이언스의 승리는 우리와 사랑하는 이들 모두가 피를 흘림으로써 일궈내지 않았는가!', `FemaleText_loc4`='他的战争——并不是我们的战争，却夺走了我们幸福的生活。我们用自己与所爱的人的鲜血，换来了联盟的胜利！', `FemaleText_loc5`='害我們活不下去的不是我們的戰爭，而是「他的」戰爭。可是，聯盟的勝利卻是用「我們」的鮮血換來的。', `FemaleText_loc7`='¡Es SU guerra, no la nuestra, pero nos está costando nuestras vidas. NOSOTROS pagamos por las victorias de la Alianza con nuestra sangre y la sangre de los que amamos!' WHERE `ID`=42574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때가 왔다. 내 형제자매여. 드디어 이 부당함에 종지부를 찍을 때가 왔다!', `FemaleText_loc4`='时机已经到来了，兄弟姐妹们，我们要让正义得伸！', `FemaleText_loc5`='時候到了，兄弟姐妹們，該是宣張正義的時候了!', `FemaleText_loc7`='¡Ha llegado el momento, hermanos y hermanas, de poner fin a esta injusticia!' WHERE `ID`=42575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드의 정부, 그보다 얼라이언스 전체에 지금 우리 모습의 책임을 물어야 한다!', `FemaleText_loc4`='暴风城与整个联盟的执政阶级，必须为他们对我们犯下的罪行负责！', `FemaleText_loc5`='暴風城的政府，聯盟的政府，必須為他們施加在我們身上的不公不義負責!', `FemaleText_loc7`='¡El gobierno de Ventormenta, de la ALIANZA, debe hacerse responsable de lo que nos han hecho!' WHERE `ID`=42576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘, 우리는 다시 태어난다! 오늘, 우리는 이름도 정체도 없는 이가 아닌, 당당한 존재로 일어서리라!', `FemaleText_loc4`='今天，我们获得了新生！今天，我们是以男人和女人的身份屹立在这里，而不再是无名无姓的数字！', `FemaleText_loc5`='今天，我們重獲新生!今天，我們要當個實實在在的人，而不是沒有臉孔、沒有名字的統計數字!', `FemaleText_loc7`='¡Hoy, renacemos! ¡Hoy, ocupamos nuestro lugar como hombres y mujeres, no como meros números sin nombre ni rostro!' WHERE `ID`=42577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 향해 물고기를 던지고는 두려움에 떨며 달아나려고 합니다!
', `MaleText_loc4`='%s把他的鱼扔向你，恐惧地试图逃走！', `MaleText_loc5`='%s把他的魚丟向你，充滿恐懼地想要轉身逃跑!', `MaleText_loc7`='¡%s te arroja un pez e intenta escapar aterrorizado!', `FemaleText_loc1`='%s|1이;가; 당신을 향해 물고기를 던지고는 두려움에 떨며 달아나려고 합니다!
', `FemaleText_loc4`='%s把他的鱼扔向你，恐惧地试图逃走！', `FemaleText_loc5`='%s把他的魚丟向你，充滿恐懼地想要轉身逃跑!', `FemaleText_loc7`='¡%s te arroja un pez e intenta escapar aterrorizado!' WHERE `ID`=42578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼내주셔서 감사해요!', `MaleText_loc4`='谢谢你把我从这儿弄出来！', `MaleText_loc5`='謝謝你幫我逃離這裡!', `MaleText_loc7`='¡Gracias por sacarme de ahí!' WHERE `ID`=42579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 씻지도 않는 트로그놈들의 지독한 냄새를 두 번 다시 맡고 싶지 않아요!', `MaleText_loc4`='我再也不想闻到穴居人身上几百年没洗的臭味了！', `MaleText_loc5`='我不想再聞到沒洗澡的臭穴居怪了!', `MaleText_loc7`='¡No quiero volver a oler a trogg sucio en toda mi vida!' WHERE `ID`=42580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 이제 저 동굴을 날려버려야겠어요!', `MaleText_loc4`='谢谢你。现在，让我们把这洞穴炸烂吧！', `MaleText_loc5`='謝啦。現在，讓我們把這洞穴炸了!', `MaleText_loc7`='Gracias. Ahora, ¡hagamos explotar esa cueva!' WHERE `ID`=42581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 만나서 제가 얼마나 반가운지 모를 거예요!', `MaleText_loc4`='你想象不出我见到你有多高兴！', `MaleText_loc5`='你無法瞭解我看到你有多開心!', `MaleText_loc7`='¡No te haces la idea de lo feliz que me hace verte!' WHERE `ID`=42582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 트로그가 아니어서 정말 기뻐요!', `MaleText_loc4`='终于见到个不是穴居人的人！', `MaleText_loc5`='我終於看到穴居怪以外的生物了!', `MaleText_loc7`='¡Por fin, alguien que no es un trogg!' WHERE `ID`=42583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자유다! 정말 자유야!', `MaleText_loc4`='我自由了！我真的自由了！', `MaleText_loc5`='我自由了!我真的自由了!', `MaleText_loc7`='¡Soy libre! ¡Libre como el viento!' WHERE `ID`=42584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부족의 동지들이여, 우리의 도시가 공격받고 있다! 모두 무기를 들고 우리의 고향을 지켜내야 한다! 직접 싸우고 싶지 않다면, 바람막이로 도시 주변을 둘러서 주민을 정령으로부터 보호하라!', `MaleText_loc4`='部族的朋友们，我们的城市遭到了攻击！拿起你们的武器，共同保卫我们的家园！要是你不想战斗，那就把天气障壁安放在城市周围，保护市民免受元素的侵扰！', `MaleText_loc5`='部落的朋友，我們的城市正遭受到攻擊!拿起你的武器保護我們的家園!如果你不想參與戰鬥，那就拿起障礙棚排在城市中來保護我們的居民免受元素的迫害!', `MaleText_loc7`='¡Amigos de la tribu, están atacando nuestra ciudad! ¡Tomad las armas y defended nuestro hogar! Si no deseáis luchar, ¡coged las protecciones contra el clima y cubrid la ciudad para proteger a sus ciudadanos de los elementos!' WHERE `ID`=42585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 주위에 바람막이를 설치해서 도시를 보호하십시오!$b$b도시 곳곳에 놓인 상자에서 바람막이를 집어$b$b붉은색 화살표|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 설치하십시오.', `MaleText_loc4`='把天气障壁放在雷霆崖周围来保护城市！$B$B从城市周围的箱子里取出防风屏障$B$B将它们安放在红色箭头标出的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc5`='在雷霆崖的四周放置障礙棚來保護它!$B$B由城市中散佈的盒子中拿起遮風棚$B$B然後放在標有紅色箭頭的地方|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc7`='¡Coloca protecciones contra el clima por toda Cima del Trueno para proteger la ciudad!$B$BRecoge rompevientos de las cajas situadas por toda la ciudad$B$By colócalas en un sitio marcado con una flecha roja|TInterfaceIconsABILITY_HUNTER_MARKEDFORDEATH.blp:32|t.' WHERE `ID`=42586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 고쳐 놓는다고!', `MaleText_loc4`='我们马上就开始，$g阁下:女士;！', `MaleText_loc5`='我們會立刻去辦，$g先生:女士;!', `MaleText_loc7`='¡Nos encargaremos enseguida, $gseñor:señora;!' WHERE `ID`=42587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중앙 봉우리를 탈환했네! 대지모신께 찬미를!', `MaleText_loc4`='我们夺回了中央高地！赞美大地之母！', `MaleText_loc5`='中央高地已經奪回了!感謝大地之母!', `MaleText_loc7`='¡Hemos recuperado el Alto Central! ¡Alabada sea la Madre Tierra!' WHERE `ID`=42588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 고치고 있다고!', `MaleText_loc4`='明白！', `MaleText_loc5`='我們在做了!', `MaleText_loc7`='¡Estamos en ello!' WHERE `ID`=42589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 지금 바로 손볼 거야!', `MaleText_loc4`='是$g阁下:女士;！马上执行，$g阁下:女士;！', `MaleText_loc5`='遵命$g先生:女士;!馬上辦，$g先生:女士;!', `MaleText_loc7`='¡Sí, $gseñor:señora;! ¡Ahora mismo $gseñor:señora;!' WHERE `ID`=42590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수렵의 봉우리의 안전을 확보했습니다! 모든 침략자를 무찌르고 주민을 모두 안전한 곳으로 대피시켰습니다!', `FemaleText_loc4`='我们守住了猎人高地！入侵者已经被彻底击退，撤退完成了！', `FemaleText_loc5`='獵人高地已經安全了!所有的入侵者都被擊退了，疏散活動也已經完成!', `FemaleText_loc7`='¡Tenemos el control del Alto de los Cazadores! ¡Hemos hecho retroceder a los invasores y la evacuación se ha completado con éxito!' WHERE `ID`=42591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정기의 봉우리의 안전을 확보했다! 침략자를 모두 제거하고 주민을 안전한 곳으로 피난시켰다!', `MaleText_loc4`='灵魂高地守住了！所有入侵者都已被击退，撤离也已顺利完成！', `MaleText_loc5`='靈魂高地安全了!入侵者都被消滅，疏散已經完成!', `MaleText_loc7`='¡Tenemos el control del Alto de los Espíritus! ¡Los invasores han sido eliminados y la evacuación ha sido completada con éxito!' WHERE `ID`=42592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 도망칠 곳은 없다, 밴클리프! 데피아즈단은 여기서 끝이다!', `MaleText_loc4`='你无路可逃了，范克里夫！迪菲亚的末日到了！', `MaleText_loc5`='你無處可躲了，范克里夫!迪菲亞兄弟會已經結—束—了!', `MaleText_loc7`='¡No queda ningún lugar donde te puedas esconder VanCleef! ¡Los Defias están ACABADOS!' WHERE `ID`=42593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝을 보러왔다! 어서 덤벼라, 이 비겁한 놈아!', `MaleText_loc4`='我们是来此做了结的！面对我们吧，懦夫！', `MaleText_loc5`='出來吧，膽小鬼!我們來結束這一切!', `MaleText_loc7`='¡Hemos venido para terminar con esto! ¡Enfréntate a nosotros, cobarde!' WHERE `ID`=42594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 결사단에 맞설 수는 없다!', `MaleText_loc4`='谁也别想挑战兄弟会！', `MaleText_loc5`='沒有人能與兄弟會抗衡!', `MaleText_loc7`='¡Nadie osa desafiar a la Hermandad!' WHERE `ID`=42595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 단단히 하십시오, $n 님. 하지만 빨리하셔야 합니다!', `MaleText_loc4`='去做准备吧，$n，但动作要快！', `MaleText_loc5`='做好你的準備，$n，但速度快點!', `MaleText_loc7`='¡Prepárate, $n, y hazlo rápido!' WHERE `ID`=42596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다. 에루낙, 이제 갑시다!', `MaleText_loc4`='我准备好了，埃鲁纳克。出发吧！', `MaleText_loc5`='我準備好了，伊魯納克。我們走吧!', `MaleText_loc7`='Estoy listo, Erunak. ¡Vamos!', `FemaleText_loc1`='준비되었어요. 에루낙, 이제 가요!', `FemaleText_loc4`='我准备好了，埃鲁纳克。出发吧！', `FemaleText_loc5`='我準備好了，伊魯納克。我們走吧!', `FemaleText_loc7`='Estoy lista, Erunak. ¡Vamos!' WHERE `ID`=42597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 닫아라! 놈을 찾아냈다!', `MaleText_loc4`='守住门——我们抓到他了！', `MaleText_loc5`='守住門—我們逮到他了!', `MaleText_loc7`='¡Cubran la puerta, lo tenemos!', `FemaleText_loc1`='문을 닫아라! 놈을 찾아냈다!', `FemaleText_loc4`='守住门——我们抓到他了！', `FemaleText_loc5`='守住門—我們逮到他了!', `FemaleText_loc7`='¡Cubran la puerta, lo tenemos!' WHERE `ID`=42598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 제발 여기서 이러지 마! 밖에서 싸우라고, 친구!', `MaleText_loc4`='哦不，别在酒吧里闹事！去外面解决，伙计！', `MaleText_loc5`='喔不!別在酒吧裡!快出去，老兄!', `MaleText_loc7`='¡Eh, en el bar no! ¡La'' peleas fuera, colega!' WHERE `ID`=42599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 순찰을 끝내겠습니다!', `MaleText_loc4`='我现在停止巡查了！', `MaleText_loc5`='我現在停止巡邏了!', `MaleText_loc7`='¡Voy a detener mi patrulla ahora mismo!' WHERE `ID`=42600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 순찰을 시작하겠습니다!', `MaleText_loc4`='我现在开始巡查了！', `MaleText_loc5`='我現在就開始巡邏!', `MaleText_loc7`='¡Voy a comenzar mi patrulla ahora mismo!' WHERE `ID`=42601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 승리를! 스톰윈드에 영광을!', `MaleText_loc4`='胜利属于联盟！荣誉献给暴风城！', `MaleText_loc5`='聯盟的勝利!暴風城的榮光!', `MaleText_loc7`='¡Victoria para la Alianza! ¡Gloria a Ventormenta!' WHERE `ID`=42602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시의 언덕으로 돌아가자. 그라이언 님께 밴클리프의 죽음을 알려야 겠군!', `MaleText_loc4`='让我们尽快返回哨兵岭，伙伴们，把范克里夫死亡的消息通知给格里安！', `MaleText_loc5`='讓我們回到哨兵嶺吧，盟友，然後向格里安報告范克里夫的死訊!', `MaleText_loc7`='¡Volvamos a la Colina del Centinela, aliados, e informemos a Gryan del fin de VanCleef!' WHERE `ID`=42603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠...', `FemaleText_loc4`='爸爸……', `FemaleText_loc5`='爸爸...', `FemaleText_loc7`='Papá...' WHERE `ID`=42604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질풍과 바람의 정령이 썬더 블러프를 파괴하려 합니다. 그곳에 갈 만큼 자신이 강하다고 생각하면 한 번 가 보십시오. 아니라면, 도시 근처에 가지 말고 우리가 해결하도록 내버려 두십시오.', `MaleText_loc4`='狂风与空气的元素之灵正欲毁灭雷霆崖。要是你认为自己强大到足以进去帮忙，那么请便。不然的话就别进去添乱，让我们来解决这一危局。', `MaleText_loc5`='風和空氣元素們正威脅著要摧毀雷霆崖。如果你覺得你的能力強到可以進去，請便。不然，就站在城外面讓我們來處理。', `MaleText_loc7`='Los elementales del viento y del aire amenazan con destruir Cima del Trueno. Si crees que eres suficientemente fuerte para ir allí, adelante. De lo contrario, puedes quedarte fuera de la ciudad y dejar que nos encarguemos nosotros.' WHERE `ID`=42605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 주위에 정령의 균열이 일어나고 있다. 지금 당장 균열을 막아야 한다! 전투 준비가 되지 않은 주민을 모두 대피시켜라. 그들이 안전한 곳까지 무사히 도착하도록 하라!', `MaleText_loc4`='元素裂隙已经在这座城市周围张开。我们必须立刻将它们关闭！撤离全部未做好战斗准备的市民。确保他们到达安全的地方！', `MaleText_loc5`='元素裂隙已經出現於城鎮的各地。我們必須馬上將它們關閉!疏散所有非戰鬥人員，確保他們到安全的場所!', `MaleText_loc7`='Se han abierto fallas elementales por toda la ciudad. ¡Tenemos que cerrarlas! ¡Evacuad a todos los todos los ciudadanos no combatientes! ¡Aseguraos de ponerlos a salvo!' WHERE `ID`=42606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 멈추지 말게, $n!', `MaleText_loc4`='继续奋力作战，$n！', `MaleText_loc5`='不要停止攻擊，$n!', `MaleText_loc7`='¡Sigue luchando, $n!', `FemaleText_loc1`='전투를 멈추지 마십시오, $n!', `FemaleText_loc4`='继续奋力作战，$n！', `FemaleText_loc5`='不要停止攻擊，$n!', `FemaleText_loc7`='¡Sigue luchando, $n!' WHERE `ID`=42607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해지면 안 되네, $n!', `MaleText_loc4`='别放松，$n！', `MaleText_loc5`='別放鬆，$n!', `MaleText_loc7`='¡No te rindas, $n!', `FemaleText_loc1`='약해지면 안 됩니다, $n!', `FemaleText_loc4`='别放松，$n！', `FemaleText_loc5`='別放鬆，$n!', `FemaleText_loc7`='¡No te rindas, $n!' WHERE `ID`=42608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸우게, $n!', `MaleText_loc4`='继续战斗，$n！', `MaleText_loc5`='繼續戰鬥，$n!', `MaleText_loc7`='¡Sigue luchando, $n!', `FemaleText_loc1`='계속 싸우세요, $n!', `FemaleText_loc4`='继续战斗，$n！', `FemaleText_loc5`='繼續戰鬥，$n!', `FemaleText_loc7`='¡Sigue luchando, $n!' WHERE `ID`=42609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 공격하게, $n!', `MaleText_loc4`='继续攻击，$n！', `MaleText_loc5`='繼續攻擊，$n!', `MaleText_loc7`='¡Continúa el ataque, $n!', `FemaleText_loc1`='계속 공격하십시오, $n!', `FemaleText_loc4`='继续攻击，$n！', `FemaleText_loc5`='繼續攻擊，$n!', `FemaleText_loc7`='¡Continúa el ataque, $n!' WHERE `ID`=42610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아닌 것 같군, $n!', `MaleText_loc4`='看来你这强大$c的名头可真是名不虚传啊，$n！', `MaleText_loc5`='看來你身為一個優秀的$c果然名不虛傳，$n!', `MaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!', `FemaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아닌 것 같군요, $n!', `FemaleText_loc4`='看来你这强大$c的名头可真是名不虚传啊，$n！', `FemaleText_loc5`='看來你身為一個優秀的$c果然名不虛傳，$n!', `FemaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!' WHERE `ID`=42611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 전투 기술이군, $n.', `MaleText_loc4`='你的作战技巧令人印象深刻，$n。', `MaleText_loc5`='你的戰鬥技巧令人讚賞，$n。', `MaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.', `FemaleText_loc1`='놀라운 전투 기술이군요, $n.', `FemaleText_loc4`='你的作战技巧令人印象深刻，$n。', `FemaleText_loc5`='你的戰鬥技巧令人讚賞，$n。', `FemaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.' WHERE `ID`=42612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늙은 용아귀 오크를 가만히 내버려 두시오, $c|1이여;여;.$B$B난 듣기만 해도 등골이 오싹할 생물들과 싸웠고, 아웃랜드의 폐허와 축축한 늪지대에서 내 동족이 학살당하는 것을 보았다오.$B$B당장, 꺼지시오.', `MaleText_loc4`='别去打扰这年老的龙喉兽人喝酒了，$c。$B$B我曾经对抗过足以把你脊椎扭弯的怪物，在湿地的沼泽和外域的废墟间看着自己的人民惨遭屠戮。$B$B茫然。无措。', `MaleText_loc5`='不要煩我這老龍喉，$c。$B$B我與能把你脊柱折斷的生物作過戰，我看到了我的人民在濕地的沼澤和外域的廢墟中被屠殺。$B$B給我滾開。', `MaleText_loc7`='Deja a este Faucedraco que disfrute de su bebida, $c.$B$BHe luchado contra criaturas que te producirían escalofríos y he visto a mi gente masacrada en los pantanos de Los Humedales y entre las ruinas de Terrallende.$B$BPiérdete.' WHERE `ID`=42613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐요, $c|1이여;여;? 내 이름을 아시오?$B$B그렇다면 내 명성도 익히 알겠군?$B$B나는 용아귀 부족의 플레임터스크요. 군단을 지휘하고, 용을 타고 하늘을 누비고, 그림 바톨이 파괴되는 것을 직접 보았지...$B$B황혼의 망치단과 놈들의 애완동물 오우거에게 저주가 내리길. 지금의 날 보시오. 싸구려 술에 절어서 입만 나불대는 꼴이라니.', `MaleText_loc4`='这是什么，$c？你知道我叫什么？$B$B那你可知道我的名气？$B$B我是龙喉部族的火牙。我曾统领军团，驭龙驰骋，见证过格瑞姆巴托的分崩离析……$B$B该死的暮光之锤，还有他们屁股后面那群食人魔哈巴狗。看看我现在的落魄样。只能絮叨着与廉价的烈酒为伴。', `MaleText_loc5`='怎麼回事，$c?你知道我的名字?$B$B那麼，你有聽過我的名聲嗎?$B$B我是龍喉氏族的焰牙。我指揮過大軍，我騎過飛龍，我見識過格瑞姆巴托的毀滅...$b$b該死的暮光之錘，還有他們該死的巨魔走狗。啊，你看看我，現在只會講大話和灌劣酒而已。', `MaleText_loc7`='¿Y eso, $c? ¿Sabes cómo me llamo?$B$BEntonces, ¿conoces mi reputación?$B$BSoy Colmifuego del clan Faucedraco. Yo he comandado legiones, he volado montado en un dragón y he sido testigo de la caída de Grim Batol...$B$BMaldigo al Martillo Crepuscular y maldigo a sus perritos falderos ogros. Mírame ahora. Me dedico a hablar y a beber licor barato.' WHERE `ID`=42614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족은 다시 한번 위대해질 수 있습니다. 황혼의 고원을 정복하는 걸 도와주시면 말입니다... 제게 그곳의 지도를 주실 수 있을까요?', `MaleText_loc4`='龙喉必将再次崛起。帮我们征服暮光之锤吧——你能给我一张地图吗？', `MaleText_loc5`='龍喉氏族有辦法再恢復昔日的榮光。協助我們征服暮光高地—可以拿張地圖給我嗎?', `MaleText_loc7`='Los Faucedraco pueden llegar a ser grandes de nuevo. Ayúdanos en nuestra conquista de las Tierras Altas Crepusculares. ¿Puedes darme un mapa?', `FemaleText_loc1`='용아귀 부족은 다시 한번 위대해질 수 있습니다. 황혼의 고원을 정복하는 걸 도와주시면 말입니다... 제게 그곳의 지도를 주실 수 있을까요?', `FemaleText_loc4`='龙喉必将再次崛起。帮我们征服暮光之锤吧——你能给我一张地图吗？', `FemaleText_loc5`='龍喉氏族有辦法再恢復昔日的榮光。協助我們征服暮光高地—可以拿張地圖給我嗎?', `FemaleText_loc7`='Los Faucedraco pueden llegar a ser grandes de nuevo. Ayúdanos en nuestra conquista de las Tierras Altas Crepusculares. ¿Puedes darme un mapa?' WHERE `ID`=42615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았소. 당신을 돕겠소. 하지만 독사의 소굴에 발을 들이는 것임은 알아 두시오. 내가 지도를 그려 주지... 잠깐, 뒤를 보시오!', `MaleText_loc4`='我会帮忙，可你要知道，你们正在踏入毒蛇的巢穴。让我来为你画张地图——哇——你后面！', `MaleText_loc5`='我願意幫你，但是你得知道你這可是自行踏入了毒蛇的巢穴。我畫個地圖給你看—小心—後面!', `MaleText_loc7`='Te ayudaré, pero debes saber que vas de cabeza a la boca del lobo. Déjame que te dibuje un mapa... qué... ¡detrás de ti!' WHERE `ID`=42616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 황혼의 망치단이 날 없애고 싶어한단 말이지? 역겹고 한심한 놈들!$B$B내 진심으로 당신을 돕겠소, $c|1이여;여;. 지도가 필요하다고 하셨소?', `MaleText_loc4`='这么说来，暮光之锤想要除掉我？恬不知耻的垃圾！$B$B我一定会帮助你的，$c。你说你需要一张地图？', `MaleText_loc5`='暮光之錘想要終結我?沒榮譽感的畜生!$B$B我幫你幫定了，$c。你說你需要一張地圖?', `MaleText_loc7`='¿Así que el Martillo Crepuscular quiere matarme? ¡Escoria sin honor!$B$BSí que voy a ayudarte, $c. ¿Has dicho que necesitabas un mapa?' WHERE `ID`=42617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 곳에서 어떤 일이 일어나더라도, 아이언포지는 이 대지와 카즈 모단 모두를 잊지 않았어요.', `FemaleText_loc4`='不管在别处正在发生着什么，铁炉堡没有忘记这片土地，也没有忘记卡兹莫丹的任何角落！', `FemaleText_loc5`='不管別的地方發生了什麼事情，鐵爐堡並沒有忘記這塊土地，沒有忘記卡茲莫丹的任何地方。', `FemaleText_loc7`='Lo que ocurra en otras partes no importa. Forjaz no ha olvidado estas tierras, ni a los de Khaz Modan.' WHERE `ID`=42618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 몰래 따라오는 것 같습니다...', `MaleText_loc4`='你感觉到你被跟踪了……', `MaleText_loc5`='你感覺你好像被跟蹤了...', `MaleText_loc7`='Sientes que te están siguiendo...' WHERE `ID`=42619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비겁한 쥐새끼에게 어울리는 죽음이로군!', `MaleText_loc4`='你毫无荣誉感地战斗，死也死得像只害虫！', `MaleText_loc5`='沒有榮譽感的螻蟻，去死吧!', `MaleText_loc7`='¡Luchas sin honor y mueres como una alimaña!' WHERE `ID`=42620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단 쓰레기 같으니.', `MaleText_loc4`='暮光渣滓。', `MaleText_loc5`='暮光垃圾。', `MaleText_loc7`='Escoria Crepuscular.' WHERE `ID`=42621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족의 손맛을 보아라!', `MaleText_loc4`='感受龙喉的利齿吧！', `MaleText_loc5`='體驗龍喉的尖牙吧!', `MaleText_loc7`='¡Siente el mordisco de los Faucedraco!' WHERE `ID`=42622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레가 하나 쓰러졌군.', `MaleText_loc4`='又一只虫子回归大地了。', `MaleText_loc5`='又一隻回歸塵土的小蟲。', `MaleText_loc7`='Otro gusano aplastado en la tierra.' WHERE `ID`=42623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약한 자만이 어둠 속에서 몰래 공격하는 법이다, 역겨운 놈!', `MaleText_loc4`='只有弱者才藏在阴影里，暮光垃圾！', `MaleText_loc5`='只有弱者才隱藏在暗影之中，暮光的蟲子!', `MaleText_loc7`='¡Tan solo los débiles se ocultan entre las sombras, escoria Crepuscular!' WHERE `ID`=42624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 해안가와 통하는 길이 그려진 지도가 필요합니다.', `MaleText_loc4`='是的，一张绘有海岸地形的地图。', `MaleText_loc5`='是的，海岸路線的地圖。', `MaleText_loc7`='Sí, una mapa de la zona cercana a la costa.', `FemaleText_loc1`='예, 해안가와 통하는 길이 그려진 지도가 필요합니다.', `FemaleText_loc4`='是的，一张绘有海岸地形的地图。', `FemaleText_loc5`='是的，海岸路線的地圖。', `FemaleText_loc7`='Sí, una mapa de la zona cercana a la costa.' WHERE `ID`=42625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고향에 있는 항구를 찢어진 양피지에 자세히 그립니다.', `MaleText_loc4`='%s在一张撕下的羊皮纸上画下了他故乡港口附近的地形。', `MaleText_loc5`='%s在破舊的紙卷上潦草地畫下了暮光高地港口的路線圖。', `MaleText_loc7`='%s garabatea una imagen del puerto de su hogar en un trozo de pergamino.' WHERE `ID`=42626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있소, $n. 황혼의 고원으로 통하는 안전한 길을 모두 표시했소. 우리 적을 완전히 짓밟아 주시오!', `MaleText_loc4`='拿去吧，$n。所有可攻入暮光高地的安全路线都在这上面了。将毁灭带给我们的敌人吧！', `MaleText_loc5`='拿去吧，$n。所有前進至暮光高地的安全路線。給我們的敵人帶來毀滅吧!', `MaleText_loc7`='Ahí lo tienes, $n. Todos los pasos seguros hacia las Tierras Altas Crepusculares. ¡Desata el caos entre nuestros enemigos!' WHERE `ID`=42627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이라니. 하. 거들먹거리며 뽐내고 다니는... 고양이 새끼들. 다시 본론으로 들어가서... 그래비! 내가 뭘 마시고 있는 거지?', `MaleText_loc4`='暮光之锤。啊呸！一群上蹿下跳的紫色……娘娘腔。算了，坐在酒吧里喝酒才是正经事儿。格莱维！我喝点什么好呢？', `MaleText_loc5`='暮光之錘。呸。一群臭屁的紫衣懦夫...回歸正題。葛瑞敏!你要給我喝什麼?', `MaleText_loc7`='El Martillo Crepuscular. Bah. Un puñado de tíos haciendo cabriolas... Debiluchos. ¡Volvamos al negocio! ¡Salsera! ¿Qué estoy bebiendo?' WHERE `ID`=42628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 계속 갖다 달라고.', `MaleText_loc4`='很好。那就随便来吧。', `MaleText_loc5`='很好。再接再勵。', `MaleText_loc7`='Bien, pues sigue sirviéndome lo mismo.' WHERE `ID`=42629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무거나 마시고 있지, 친구.', `MaleText_loc4`='你反正什么酒都喝，老兄。', `MaleText_loc5`='想喝什麼都可以，老兄。', `MaleText_loc7`='Eh''tás bebiendo de to''o, colega.' WHERE `ID`=42630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 이야기하자는 듯 손짓합니다.', `MaleText_loc4`='%s朝你打手势，还有话要对你说。', `MaleText_loc5`='%s指示你與他再次對話。', `MaleText_loc7`='%s te hace señales para que hables con él de nuevo.' WHERE `ID`=42631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 아직도 여기 있는 거요, $c|1이여;여;?$B$B지금쯤 황혼의 고원에서 망할 이교도를 때려잡고 있어야 하는 거 아니오?', `MaleText_loc4`='你怎么还待在这儿，$c？$B$B你不是应该已经抵达暮光高地，让那该死的教派彻底毁灭吗？', `MaleText_loc5`='你還在這裡做什麼，$c?$B$B你不是應該到暮光高地去幹掉那些個可惡的教徒了嗎?', `MaleText_loc7`='¿Qué haces aquí, $c?$B$B¿No deberías estar ya en las Tierras Altas Crepusculares arrasando a ese maldito culto?' WHERE `ID`=42632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 우리 식량에 독을 탔습니다... 이교도 놈들이 계속 비행선에 타고 있었던 겁니다...', `MaleText_loc4`='他们在我们的食物中下了毒……教徒们早就混上了船……', `MaleText_loc5`='他們對我們的補給下毒...有教徒混在我們之中...', `MaleText_loc7`='Envenenaron nuestros suministros... Teníamos cultores a bordo...', `FemaleText_loc1`='그들은 우리 식량에 독을 탔어요... 이교도 놈들이 계속 비행선에 타고 있었던 거예요...', `FemaleText_loc4`='他们在我们的食物中下了毒……教徒们早就混上了船……', `FemaleText_loc5`='他們對我們的補給下毒...有教徒混在我們之中...', `FemaleText_loc7`='Envenenaron nuestros suministros... Teníamos cultores a bordo...' WHERE `ID`=42633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 속여 호드 비행포격선을 매복 공격하게 했습니다... 왜 그랬을까요?', `MaleText_loc4`='他们引我们去伏击部落的炮艇……可这是为什么呢？', `MaleText_loc5`='他們利用我們襲擊部落的砲艇...但為什麼?', `MaleText_loc7`='Nos obligaron a tender una emboscada a la nave de guerra de la Horda... pero ¿por qué?', `FemaleText_loc1`='우리를 속여 호드 비행포격선을 매복 공격하게 했어요... 왜 그랬을까요?', `FemaleText_loc4`='他们引我们去伏击部落的炮艇……可这是为什么呢？', `FemaleText_loc5`='他們利用我們襲擊部落的砲艇...但為什麼?', `FemaleText_loc7`='Nos obligaron a tender una emboscada a la nave de guerra de la Horda... pero ¿por qué?' WHERE `ID`=42634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신을 잃는 순간, 그들이 어둠의 신에게 기도하는 소릴 들었습니다... 황혼의 망치단이 벌인 짓입니다!', `MaleText_loc4`='在黑暗降临的一瞬间，我听见他们在向自己的黑暗神灵祈祷……是暮光之锤干的！', `MaleText_loc5`='整個全部變黑，然後我聽到他們在跟他們的邪神祈禱...這是暮光之錘幹的!', `MaleText_loc7`='Oí cómo rezaban a sus dioses oscuros y todo se volvió negro... ¡El Martillo Crepuscular es el culpable de esto!', `FemaleText_loc1`='정신을 잃는 순간, 그들이 어둠의 신에게 기도하는 소릴 들었어요... 황혼의 망치단이 벌인 짓이에요!', `FemaleText_loc4`='在黑暗降临的一瞬间，我听见他们在向自己的黑暗神灵祈祷……是暮光之锤干的！', `FemaleText_loc5`='整個全部變黑，然後我聽到他們在跟他們的邪神祈禱...這是暮光之錘幹的!', `FemaleText_loc7`='Oí cómo rezaban a sus dioses oscuros y todo se volvió negro... ¡El Martillo Crepuscular es el culpable de esto!' WHERE `ID`=42635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 힘없이 픽 쓰러졌습니다... 배 안에서 음식을 먹었던 자 모두가요.', `MaleText_loc4`='人们开始纷纷倒毙……那些吃过食物的人全都没能幸免。', `MaleText_loc5`='所有人都一個個倒下...所有吃過糧食的人。', `MaleText_loc7`='Todos empezaron a caer como moscas... Todos los que comieron de las raciones.', `FemaleText_loc1`='모두들 힘없이 픽 쓰러졌어요... 배 안에서 음식을 먹었던 자 모두가요.', `FemaleText_loc4`='人们开始纷纷倒毙……那些吃过食物的人全都没能幸免。', `FemaleText_loc5`='所有人都一個個倒下...所有吃過糧食的人。', `FemaleText_loc7`='Todos empezaron a caer como moscas... Todos los que comieron de las raciones.' WHERE `ID`=42636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이교도 쓰레기 같으니! 네놈이 날 이렇게 만들었다!', `MaleText_loc4`='暮光渣滓！这是你们造的孽！', `MaleText_loc5`='暮光的混蛋!這都是你們害的!', `MaleText_loc7`='¡Escoria Crepuscular! ¡Ustedes nos han hecho esto!', `FemaleText_loc1`='이 이교도 쓰레기 같으니! 네놈이 날 이렇게 만들었다!', `FemaleText_loc4`='暮光渣滓！这是你们造的孽！', `FemaleText_loc5`='暮光的混蛋!這都是你們害的!', `FemaleText_loc7`='¡Escoria Crepuscular! ¡Ustedes nos han hecho esto!' WHERE `ID`=42637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 커다란 해골을 단지에 넣고!', `MaleText_loc4`='把那块大头骨扔进锅里去！', `MaleText_loc5`='把大頭骨丟進鍋裡!', `MaleText_loc7`='¡Mete la calavera g''ande en la olla!' WHERE `ID`=42638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해골 위에 모조를 부으면!', `MaleText_loc4`='然后把魔精扔到头骨上！', `MaleText_loc5`='把魔精丟到顱骨上!', `MaleText_loc7`='¡Vie''te los mojos sobre la calavera!' WHERE `ID`=42639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 끝.', `MaleText_loc4`='法术完成。', `MaleText_loc5`='完成了!', `MaleText_loc7`='La magia eh''tá hecha.' WHERE `ID`=42640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일은 내가 전문이지. 잘 보게.', `MaleText_loc4`='看尼姆布亚给你变个他最擅长的戏法。', `MaleText_loc5`='看尼姆布亞做尼姆布亞最會做的事情。', `MaleText_loc7`='Observa cómo Nimboya hace lo que mejo'' se le da a Nimboya.' WHERE `ID`=42641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이여. 얼어붙은 황무지에서 지금껏 잘 싸워 주었소. 제군들의 용기를 다시 한 번 시험할 때가 왔소.', `MaleText_loc4`='战士们。你们曾在寒冷的荒野上顽强奋战。现在又到了再次考验你们勇气的时候了。', `MaleText_loc5`='戰士們，你們在冰凍荒原英勇地戰鬥。你們的勇氣將再次面臨挑戰。', `MaleText_loc7`='Guerreros. Han luchado duro en los baldíos helados. Su valor será puesto a prueba de nuevo.' WHERE `ID`=42642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사들이여! 그대들의 용기는 이미 증명되었소. 그것이 바로 대족장님께서 그대들을 선택하신 이유일 것이오.', `MaleText_loc4`='我的战士们！你们已经证明了自己的勇猛。这也是酋长选中你们的原因。', `MaleText_loc5`='戰士們!你們已經證明了你們的勇敢，而這也正是大酋長選擇了你們的原因。', `MaleText_loc7`='¡Mis guerreros! Ya hab probado su valor. Por eso los ha elegido el Jefe de Guerra.' WHERE `ID`=42643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 영웅들이여! 역사를 창조할 준비가 되었소?', `MaleText_loc4`='部落的英雄们！你们准备好创造历史了吗？', `MaleText_loc5`='部落的英雄們!準備好要創造歷史了嗎?', `MaleText_loc7`='¡Héroes de la Horda! ¿Están preparados para hacer historia?' WHERE `ID`=42644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 본거지로 뛰어들기 위한 장거리 항해가 곧 시작될 예정이오.', `MaleText_loc4`='我们很快就将登船前往遥远的彼岸，扑向敌人的老巢。', `MaleText_loc5`='我們即將登上前往遠方海岸的船，將我們投身於敵人的家鄉。', `MaleText_loc7`='Pronto embarcaremos rumbo a orillas lejanas, para arrojarnos sobre la patria del enemigo.' WHERE `ID`=42645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠에 휩싸인 적들은 우리의 세계를 파괴하려 들고 있소. 또다시 고향을 잃을 순 없소.', `MaleText_loc4`='我们的敌人——潜于暗影之中，妄图颠覆我们的世界。我们不会再失去另一个家园。', `MaleText_loc5`='我們的敵人，以暗影為掩護，想要破壞我們的世界。我們不會再失去另一個家園了。', `MaleText_loc7`='Nuestro enemigo, oculto entre la sombra, ansía destrozar nuestro mundo. No perderemos otro hogar.' WHERE `ID`=42646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적지는 황혼의 고원. 적의 심장부를 직접 치는 작전이오.', `MaleText_loc4`='我们的目的地是暮光高地。我们要直接把敌人跃动的心脏给挖出来。', `MaleText_loc5`='我們的目的地是暮光高地。我們的攻擊將讓敵人心驚動魄。', `MaleText_loc7`='Nuestro destino son las Tierras Altas Crepusculares. Golpearemos en el corazón de nuestro enemigo.' WHERE `ID`=42647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅과 바다, 그리고 공중에서 활약할 거대한 함대가 편성됐소. 우리는 군단이오!', `MaleText_loc4`='我们集结了庞大的军队——凝聚海陆空三军。我们是强大的军团！', `MaleText_loc5`='我們聚集了一批巨大的軍隊:陸軍、海軍和空軍。我們是一支軍團!', `MaleText_loc7`='Hemos reunido una gran flota: por tierra, por mar y por aire. ¡Somos legiones!' WHERE `ID`=42648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 분노 앞에 적들은 무릎 꿇고 말 것이오!', `MaleText_loc4`='当我们释放出怒火，我们的敌人就只会瑟缩不已！', `MaleText_loc5`='當我們的怒火釋放之時，就是敵人颤抖之時!', `MaleText_loc7`='¡Cuando desatemos nuestra furia, nuestros enemigos temblarán!' WHERE `ID`=42649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광포한 기세로 고원은 붉게 물들고 적이 흘리는 피로 뒤덮일 지어다!', `MaleText_loc4`='我们的怒火将把高地染红——或是敌人血液的任何颜色！', `MaleText_loc5`='我們的憤怒將把高地染成紅色─或任何敵人所流之血的顏色!', `MaleText_loc7`='Nuestra ira teñirá las tierras altas de rojo... ¡o del color que sea la maldita sangre de nuestros enemigos!' WHERE `ID`=42650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 그대들을 지켜보고 있소.', `MaleText_loc4`='地狱咆哮的双目在注视着你。', `MaleText_loc5`='地獄吼的雙眼在盯著你!', `MaleText_loc7`='Los ojos de Grito Infernal están fijos en ustedes.' WHERE `ID`=42651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 가볍게 시작합시다. 공격! 공격!', `MaleText_loc4`='让我们看看高昂的斗志吧。出击！出击！出击！', `MaleText_loc5`='提起精神。攻擊!攻擊!攻擊!', `MaleText_loc7`='Veamos un poco de ese espíritu. ¡Golpeen! ¡Golpeen! ¡Golpeen!' WHERE `ID`=42652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들의 실력을 보여주시오!', `MaleText_loc4`='让我看看你的本事！', `MaleText_loc5`='讓我看看你們的能耐!', `MaleText_loc7`='¡Enséñenme lo que pueden hacer!' WHERE `ID`=42653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 바로, 그대들이 가진 분노를 폭발시키시오!', `MaleText_loc4`='现在。让我看看你的怒火。来吧！', `MaleText_loc5`='現在。釋放你的怒火，釋放它!', `MaleText_loc7`='Ahora. Muéstrenme su furia. ¡Muéstrenmela!' WHERE `ID`=42654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예감이 좋지 않습니다, $n 님. 경계를 늦추지 마십시오!', `MaleText_loc4`='这我可不喜欢，$n。保持警觉！', `MaleText_loc5`='我不喜歡這種感覺，$n。提高警戒。', `MaleText_loc7`='¡No me gusta esto, $n! ¡Estate alerta!' WHERE `ID`=42655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 놈들은 죄값으로 지옥불에 타는 벌을 받을 것이다.', `FemaleText_loc4`='你们这群混蛋要为自己的罪行付出代价。', `FemaleText_loc5`='你們這些混蛋會自食惡果。', `FemaleText_loc7`='Bastardos, arderéis por lo que hicisteis.' WHERE `ID`=42656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호프! 대체 무슨...', `MaleText_loc4`='希望！什……', `MaleText_loc5`='喜願!你...', `MaleText_loc7`='¡Esperanza! Qué...' WHERE `ID`=42657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호프? 당신 부하가 우리 아버지를 죽였을 때 그런 희망 따위를 느꼈어야 했나?', `FemaleText_loc4`='希望？当我看见父亲的头被你的手下砍掉时，我心里应该有这种感觉吗？', `FemaleText_loc5`='喜願?可喜之願?這就是在我看到父親被你的手下砍頭的時候，應該要有的感覺嗎?', `FemaleText_loc7`='¿Esperanza?¿Se supone que es lo que tenía que sentir cuando tus secuaces decapitaron a mi padre?' WHERE `ID`=42658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='희망은 이 가혹하고 냉담한 세상에 놀아나는 잔인한 농담에 불과해. 더 이상 희망은 없다, 오직, 바네사... 바네사 밴클리프만이 존재할 뿐.', `FemaleText_loc4`='希望就是个残忍的笑话，是这个严酷而冷漠的世界同我们开的一个玩笑。希望根本就是不存在的，存在的只有梵妮莎。梵妮莎·范克里夫。', `FemaleText_loc5`='喜願?有何可喜?這只是無情冷酷的世界對我們開的殘酷玩笑。喜願是不存在的，存在的只有凡妮莎。凡妮莎·范克里夫。', `FemaleText_loc7`='La esperanza es un broma pesada, una broma de un mundo duro al que no le importamos nada. No había ninguna Esperanza, tan solo Vanessa. Vanessa VanCleef.' WHERE `ID`=42659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나라 결사단이여! 새로운 시대가 우리를 기다린다!', `FemaleText_loc4`='站起来吧兄弟会！破晓之日即将到来！', `FemaleText_loc5`='崛起吧兄弟會!黎明之日即將到臨!', `FemaleText_loc7`='¡ALZAOS HERMANDAD! ¡EL DÍA DEL AMANECER HA LLEGADO!' WHERE `ID`=42660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들을 묶어라.', `FemaleText_loc4`='把他们绑起来。', `FemaleText_loc5`='把他們綁起來。', `FemaleText_loc7`='Atadlos.' WHERE `ID`=42661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님, 모자를 받으십시오.', `FemaleText_loc4`='长官，你的帽子。', `FemaleText_loc5`='上將，你的帽子。', `FemaleText_loc7`='Almirante, tu sombrero.' WHERE `ID`=42662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군.', `MaleText_loc4`='谢谢你，宝贝儿。', `MaleText_loc5`='謝謝你，親愛的。', `MaleText_loc7`='Gracias, querida.' WHERE `ID`=42663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위풍당당한 보덴이여, 나는 대지 고리회를 대표해 여기 왔습니다. 당신들에게 해를 끼칠 생각은 전혀 없습니다. 단지 우리와 당신들의 세계 사이에 생긴 균열을 닫고 싶을 뿐입니다. 어째서 우리를 공격하는 것입니까?', `MaleText_loc4`='执行者博登，我是代表大地之环来的。我愿你族远离任何伤害。我们希望修复横亘在我们世界间的裂隙。你为什么要攻击我们？', `MaleText_loc5`='莊嚴的波登，我謹代表陶土議會而來。我們毫無惡意，只是想修復我們世界之間的裂隙而已。你為什麼要攻擊我們?', `MaleText_loc7`='Boden el Imponente, vengo de parte del Anillo de la Tierra. No deseamos hacer daño a tu gente. Deseamos reparar el abismo que separa nuestros mundos. ¿Por qué nos atacas?', `FemaleText_loc1`='위풍당당한 보덴이여, 나는 대지 고리회를 대표해 여기 왔습니다. 당신들에게 해를 끼칠 생각은 전혀 없습니다. 단지 우리와 당신들의 세계 사이에 생긴 균열을 닫고 싶을 뿐입니다. 어째서 우리를 공격하는 것입니까?', `FemaleText_loc4`='执行者博登，我是代表大地之环来的。我愿你族远离任何伤害。我们希望修复横亘在我们世界间的裂隙。你为什么要攻击我们？', `FemaleText_loc5`='莊嚴的波登，我謹代表陶土議會而來。我們毫無惡意，只是想修復我們世界之間的裂隙而已。你為什麼要攻擊我們?', `FemaleText_loc7`='Boden el Imponente, vengo de parte del Anillo de la Tierra. No deseamos hacer daño a tu gente. Deseamos reparar el abismo que separa nuestros mundos. ¿Por qué nos atacas?' WHERE `ID`=42664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 내가 디아만트인 줄 아나? 아니면 훌쩍거리면서 뭐든 시키는 대로 하는 트로그로 보이나?', `MaleText_loc4`='哈！你是不是把我错认成岱亚曼塔，$r？还是只知道哭鼻子的软骨头穴居人？', `MaleText_loc5`='哈!你是不是把我當成戴門了，$r?還是其他那些愛哭和聽話的穴居怪?無所謂。', `MaleText_loc7`='¡Ja! ¿Me confundes con Diamant? ¿O tal vez con algún trogg quejoso y obediente al que le importa?' WHERE `ID`=42665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화를 원한다면, 세계 기둥을 포기하고 심원의 영지를 떠나라. 여기는 우리 땅이다. 너희가 받을 수 있는 환대는 내 발에 짓밟히는 것뿐이다!', `MaleText_loc4`='如果你寻求和平，那么就放弃世界之柱并离开深岩之洲。这是我们的国度，你不会受到欢迎，只配被我碾于脚下。', `MaleText_loc5`='如果你在尋找和平，放棄世界之柱和離開地深之源。這是我們的國度。在這唯一歡迎你的只有我的石頭腳板。', `MaleText_loc7`='Si buscan la paz, entreguen el Pilar Mundial y dejen Infralar. Este es nuestro reino. La única bienvenida para ustedes se encuentra bajo mi pie de piedra.' WHERE `ID`=42666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 맥크리의 역발산 주식회사의 제섭 맥크리라고 합니다.', `MaleText_loc4`='麦氏移山人有限公司杰萨普·麦格雷，为您效劳。', `MaleText_loc5`='麥克利的移山者有限公司的傑瑟普·麥克利，聽候您的差遣。', `MaleText_loc7`='Jessup McCree, de Muevemontañas de McCree, a tu servicio.' WHERE `ID`=42667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산을 옮기는 일이 제가 하는 일입니다. 물론 산을 만들어낼 수도 있고 말입니다.', `MaleText_loc4`='要是您想要搬山，找我就对了。我还能为您造座山出来。', `MaleText_loc5`='如果你希望移動一座山，我辦得到。我也可以建一座山給你。', `MaleText_loc7`='Si necesitas mover una montaña, yo puedo hacerlo. También puedo hacerlas para ti.' WHERE `ID`=42668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 했던 일은 그다지 큰일도 아닙니다. 발끝에도 못 미치죠. 이 대격변이 아마도 우리에게 일어났던 일 중 가장 멋진 일이 아닐까 싶습니다!', `MaleText_loc4`='这不是我所干过最重要的工作，连边儿都沾不上。大灾变一定是我们所经历过最棒的事了！', `MaleText_loc5`='這不是我們幹過最大票的工作，哈，還差得遠了。這場災變說不定是我們最棒的大好機會!', `MaleText_loc7`='Este no es mi mayor trabajo, ni por asomo. ¡Puede que este cataclismo sea lo mejor que nos haya pasado nunca!' WHERE `ID`=42669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와줄까?', `MaleText_loc4`='我能为你做些什么吗，长官？', `MaleText_loc5`='我能為你做什麼，老大?', `MaleText_loc7`='¿Qué puedo hacer por ti, $gjefe:jefa;?', `FemaleText_loc1`='뭘 도와드릴까요?', `FemaleText_loc4`='我能为你做些什么吗，长官？', `FemaleText_loc5`='我能為你做什麼，老大?', `FemaleText_loc7`='¿Qué puedo hacer por ti, $gjefe:jefa;?' WHERE `ID`=42670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와 주셔서 감사합니다. 저 녀석, 생각보다 훨씬 강하더군요.', `MaleText_loc4`='多谢你的帮忙。不知为什么那个要难对付得多。', `MaleText_loc5`='謝謝你的幫忙。那隻不知道為什麼會那麼的難搞。', `MaleText_loc7`='Gracias por tu ayuda. Por alguna razón, ese era mucho más duro que los demás.', `FemaleText_loc1`='도와 주셔서 감사합니다. 저 녀석, 생각보다 훨씬 강하더군요.', `FemaleText_loc4`='多谢你的帮忙。不知为什么那个要难对付得多。', `FemaleText_loc5`='謝謝你的幫忙。那隻不知道為什麼會那麼的難搞。', `FemaleText_loc7`='Gracias por tu ayuda. Por alguna razón, ese era mucho más duro que los demás.' WHERE `ID`=42671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제들이여! 그대들이 지난 자리에는 잿더미만이 남게 하여라! 감시의 언덕을 모조리 다 불태워 버려라!', `FemaleText_loc4`='让你们所见之处只留下灰烬，兄弟们！把哨兵岭烧光！', `FemaleText_loc5`='兄弟們，放火把這裡全燒了!將哨兵嶺燒成灰燼!', `FemaleText_loc7`='¡No dejen más que cenizas a sus paso, hermanos! ¡Que la Colina del Centinela arda hasta los cimientos!' WHERE `ID`=42672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 너, $n. 네 목숨만은 살려주마. 의도한 바는 아니었겠지만, 결국 우리 계획에 큰 도움이 되었으니 말이다. 하지만, 다음에 보면 살려두지 않을 것이다.', `FemaleText_loc4`='至于你，$n，我会饶你不死。你帮了我们不少忙——尽管是在不经意间，但下一次我们再见面时，就只能用武器说话了。', `FemaleText_loc5`='至於你，$n，我會饒你一命。雖然你並不知情，但也算是幫了我們一個大忙。但是，下次再見面的時候我們可就是敵人了。', `FemaleText_loc7`='Y a ti, $n, te perdonaré la vida. Has hecho mucho por nuestra causa, aunque haya sido de forma inconsciente; pero la próxima vez que nos encontremos será como enemigos.' WHERE `ID`=42673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 한 가지만 알려주게, 바네사.', `MaleText_loc4`='我只想知道一件事，梵妮莎。', `MaleText_loc5`='告訴我，凡妮莎。', `MaleText_loc7`='Dime una cosa, Vanessa.' WHERE `ID`=42674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄브라우 일가는 대체 왜 죽인 거지?', `MaleText_loc4`='你为什么要除掉法布隆一家？', `MaleText_loc5`='你為什麼要殺掉法布隆全家?', `MaleText_loc7`='¿Por qué hiciste que mataran a los Cejade?' WHERE `ID`=42675;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달리 선택권이 없었다. 그들은 날 알아봤어. 이 세상에서 내 존재를 알고 있던 유일한 사람들이었던 그들이 내 어릴적 얼굴을 기억해냈단 말이지.', `FemaleText_loc4`='我别无选择，中尉。他们认出了我。在这个世界上唯一知道我存在的人，从我在襁褓之时起就认得我的脸。', `FemaleText_loc5`='我別無選擇，中尉。他們認出了我。他們是這個世界上唯一知道我的存在、唯一認得我小時候模樣的人。', `FemaleText_loc7`='No tuve elección, teniente. Me reconocieron. Las únicas personas en todo el mundo que sabían que yo existía me reconocieron a pesar de haberme visto una vez cuando era niña.' WHERE `ID`=42676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 그들을 죽이는 건 결코 쉽지 않았다...', `FemaleText_loc4`='他们的死亡令我也感到难过。', `FemaleText_loc5`='我對他們的死同樣感到遺憾。', `FemaleText_loc7`='No disfruté con sus muertes.' WHERE `ID`=42677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 의심의 여지가 없군. 이 정령들은 최근에 잠에서 깨어난 것이 틀림없네.', `FemaleText_loc4`='现在可以肯定了。这些石头元素不久前才被唤醒。', `FemaleText_loc5`='所以這是真的。這些元素是最近才由沉睡中甦醒的。', `FemaleText_loc7`='Entonces ya es seguro. Estos elementales se hicieron de rocas inactivas recientemente.' WHERE `ID`=42678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령 군주만이 이렇게 빨리 이렇게 많은 정령을 불러낼 수 있지. 아무래도 우리는 바위 어머니 본인을 상대하고 있는 듯하네...', `FemaleText_loc4`='只有元素领主才有可能在短时间内唤醒这么多的元素。看来，我们面对的正是石母本尊……', `FemaleText_loc5`='只有元素領主才能在短時間內喚醒那麼多的元素，感覺簡直是與石母本人在作戰一樣...', `FemaleText_loc7`='Sólo un señor elemental pudo hacer tantos tan rápidamente. Parece que estamos en guerra con la Madre Pétrea…' WHERE `ID`=42679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원소가 우리를 보호하길...', `FemaleText_loc4`='愿元素保护我们。', `FemaleText_loc5`='願元素保護我們。', `FemaleText_loc7`='Que los elementos nos protejan.' WHERE `ID`=42680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 스톰윈드로 가십시오. 그리고 국왕 바리안 린 님께 모든 것을 전하십시오. 지금 당장!', `MaleText_loc4`='$n，前去暴风城。把一切都告诉乌瑞恩国王。一切！现在就去！', `MaleText_loc5`='$n，快到暴風城，把這一切告訴烏瑞恩國王!趕快去!', `MaleText_loc7`='$n, ve a Ventormenta. Cuéntale todo al rey Wrynn. ¡TODO! ¡VE, AHORA!' WHERE `ID`=42681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 좀 숨을 돌릴 수 있겠군요! 고맙습니다.', `MaleText_loc4`='终于能喘口气了！谢谢你。', `MaleText_loc5`='讓我喘個氣休息一下!謝謝你。', `MaleText_loc7`='Una oportunidad para recuperar el aliento. ¡Gracias!', `FemaleText_loc1`='이제 좀 숨을 돌릴 수 있겠군요! 고맙습니다.', `FemaleText_loc4`='终于能喘口气了！谢谢你。', `FemaleText_loc5`='讓我喘個氣休息一下!謝謝你。', `FemaleText_loc7`='Una oportunidad para recuperar el aliento. ¡Gracias!' WHERE `ID`=42682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 놈들이... 보통 끈질긴 게 아닙니다...', `MaleText_loc4`='以元素之名……那家伙……就是死不了……', `MaleText_loc5`='以元素之名...那個東西...就是不願意死去...', `MaleText_loc7`='Por los elementos... a ese... le ha costado morirse.', `FemaleText_loc1`='정령 놈들이... 보통 끈질긴 게 아닙니다...', `FemaleText_loc4`='以元素之名……那家伙……就是死不了……', `FemaleText_loc5`='以元素之名...那個東西...就是不願意死去...', `FemaleText_loc7`='Por los elementos... a ese... le ha costado morirse.' WHERE `ID`=42683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다. 상황이 점점 어려워지는군요.', `MaleText_loc4`='谢谢你的帮忙。这儿可真危险。', `MaleText_loc5`='謝謝你的幫忙。現在外頭越來越危險了。', `MaleText_loc7`='Gracias por el relevo. Las cosas se están poniendo peliagudas por aquí.', `FemaleText_loc1`='도와주셔서 감사합니다. 상황이 점점 어려워지는군요.', `FemaleText_loc4`='谢谢你的帮忙。这儿可真危险。', `FemaleText_loc5`='謝謝你的幫忙。現在外頭越來越危險了。', `FemaleText_loc7`='Gracias por el relevo. Las cosas se están poniendo peliagudas por aquí.' WHERE `ID`=42684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 홀로 버려지는 게 아닐까 걱정하던 참이었습니다. 도와주셔서 감사합니다!', `MaleText_loc4`='我本以为我们要被留在这儿了。谢谢你出手相救！', `MaleText_loc5`='我都開始在想我們是不是被遺棄在這了。謝謝你的幫忙!', `MaleText_loc7`='Había empezado a pensar que nos habían abandonado. ¡Gracias por tu ayuda!', `FemaleText_loc1`='여기에 홀로 버려지는 게 아닐까 걱정하던 참이었습니다. 도와주셔서 감사합니다!', `FemaleText_loc4`='我本以为我们要被留在这儿了。谢谢你出手相救！', `FemaleText_loc5`='我都開始在想我們是不是被遺棄在這了。謝謝你的幫忙!', `FemaleText_loc7`='Había empezado a pensar que nos habían abandonado. ¡Gracias por tu ayuda!' WHERE `ID`=42685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, 놈들이 끝도 없이 밀려옵니다.', `MaleText_loc4`='多加小心，他们不会就这么停手。', `MaleText_loc5`='注意力集中，他們會不斷地過來。', `MaleText_loc7`='Ten cuidado, no dejan de venir más.', `FemaleText_loc1`='조심하십시오, 놈들이 끝도 없이 밀려옵니다.', `FemaleText_loc4`='多加小心，他们不会就这么停手。', `FemaleText_loc5`='注意力集中，他們會不斷地過來。', `FemaleText_loc7`='Ten cuidado, no dejan de venir más.' WHERE `ID`=42686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 너무 오래 머무르진 마십시오. 놈들이 들이닥치는 건 순식간입니다.', `MaleText_loc4`='别待在这儿太久，随时会有更多敌人出现。', `MaleText_loc5`='別待在這太久，隨時都會有更多出現在你眼前。', `MaleText_loc7`='No te quedes mucho tiempo aquí fuera, en cualquier momento caerán más sobre ti.', `FemaleText_loc1`='여기에 너무 오래 머무르진 마십시오. 놈들이 들이닥치는 건 순식간입니다.', `FemaleText_loc4`='别待在这儿太久，随时会有更多敌人出现。', `FemaleText_loc5`='別待在這太久，隨時都會有更多出現在你眼前。', `FemaleText_loc7`='No te quedes mucho tiempo aquí fuera, en cualquier momento caerán más sobre ti.' WHERE `ID`=42687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 잠시 휴식을 취할 수 있겠습니다.', `MaleText_loc4`='谢谢你。我可以稍微休息下了。', `MaleText_loc5`='謝謝你，我是需要休息一下。', `MaleText_loc7`='Gracias. Me vendrá bien el descanso.', `FemaleText_loc1`='고맙습니다. 잠시 휴식을 취할 수 있겠습니다.', `FemaleText_loc4`='谢谢你。我可以稍微休息下了。', `FemaleText_loc5`='謝謝你，我是需要休息一下。', `FemaleText_loc7`='Gracias. Me vendrá bien el descanso.' WHERE `ID`=42688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 녀석을 끝장내죠!', `MaleText_loc4`='干得漂亮！让我们解决了他。', `MaleText_loc5`='幹得好!讓我們給他最後一擊。', `MaleText_loc7`='¡Buen trabajo! Terminemos con él.' WHERE `ID`=42689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴까요?', `MaleText_loc4`='需要帮忙吗？', `MaleText_loc5`='需要幫忙嗎?', `MaleText_loc7`='¿Necesitas una mano?' WHERE `ID`=42690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 포박 다루는 모습을 봤습니다. 본진으로 돌아가면 모두들 그 멋진 솜씨를 칭송할 것입니다.', `MaleText_loc4`='我看见你那一把抓过来的动作了。等我们回去，一定要给弟兄们讲讲你的英勇事迹。', `MaleText_loc5`='我看到你剛剛在用勾爪的招式了。等我們回去以後我一定要講給其他人聽。', `MaleText_loc7`='He visto ese movimiento que has hecho con el gancho. Cuando volvamos me ocuparé de contárselo a los muchachos.' WHERE `ID`=42691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르십시오! 거인이 쓰러졌을 때 처치해야 합니다!', `MaleText_loc4`='快！趁现在把他干掉！', `MaleText_loc5`='快!趁他倒下時了結他!', `MaleText_loc7`='¡Rápido! ¡Acaba con él mientras esté en el suelo!' WHERE `ID`=42692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그겁니다.', `MaleText_loc4`='这才像话。', `MaleText_loc5`='這還差不多。', `MaleText_loc7`='Así mejor.' WHERE `ID`=42693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 거인 놈아, 이제 우리에게 돌을 못 던지겠지?', `MaleText_loc4`='别再朝我们扔石头了，好不？', `MaleText_loc5`='不會再向我們丟巨礫了，啊?', `MaleText_loc7`='¿Qué? ¿Ya no nos tiras rocas, eh?' WHERE `ID`=42694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 포박은 어디에서 구할 수 있을까요?! 정말 멋진 활약이었습니다.', `MaleText_loc4`='哪儿有像那样的绳子？！那可真棒！', `MaleText_loc5`='我哪裡才可以買到那個繩子?做得太漂亮了。', `MaleText_loc7`='¡¿Dónde puedo conseguir una de esas cuerdas?! ¡Ha sido genial!' WHERE `ID`=42695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 놈이 다시는 일어나지 못하게 하십시오...', `MaleText_loc4`='千万别让他再站起来……', `MaleText_loc5`='現在，必須確定他無法再爬起來...', `MaleText_loc7`='Y ahora, asegurémonos de que no se levanta...' WHERE `ID`=42696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매들이여, 아이언포지가 공격받고 있다! 무기를 들고 수도를 지켜내야 한다! 전투의 부름에 응할 수 없거든 벽 강화물을 구축해서 벽이 무너지지 않게 도와라!', `MaleText_loc4`='兄弟姐妹们，铁炉堡遭到了攻击！拿起你们的武器，保卫我们的主城！要是你不想回应战斗的召唤，也可以帮忙部署防御工事，确保城墙不会倒塌！', `MaleText_loc5`='兄弟和姐妹們，鐵爐堡正受到攻擊!拿起武器防衛我們的首都!如果你不想踏上戰場，那就去拿些器具參與防禦工事，幫助我們不要讓城牆倒塌壓在我們身上!', `MaleText_loc7`='Hermanos y hermanas de Forjaz. Están atacando nuestra ciudad. ¡Tomad las armas y defended nuestra capital! ¡Si no deseáis acudir a la llamada de la batalla, entonces acudid a las fortificaciones y ayudad para impedir que los muros se derrumben sobre nosotros!' WHERE `ID`=42697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광장의 안전이 확보되었다! 이제 다른 지역의 안전을 확보하라!', `MaleText_loc4`='平民区守住了！现在去守卫城市其它区域！', `MaleText_loc5`='平民大廳已經安全了!現在，保護城市其他的地方!', `MaleText_loc7`='¡La Cámara del Pueblo está a salvo! ¡Ahora, debemos hacer lo mismo con el resto de la ciudad!' WHERE `ID`=42698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강화물을 구축해서 아이언포지의 벽이 무너지지 않게 하십시오!$B$B도시 곳곳에 놓인 상자에서 벽 강화물을 집어$B$B붉은색 화살표|Tinterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 설치하십시오.', `MaleText_loc4`='在铁炉堡城墙周围构筑防御工事，来防止城墙坍塌！$B$B从城市周围的箱子里取出城墙防御工事$B$B将它们安放在红色箭头标出的位置|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc5`='加強鐵爐堡的城牆防止塌陷!$B$B從城市中各處的箱子裡拿起強化材料$B$B然後放在標有紅色箭頭的地方|TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t。', `MaleText_loc7`='¡Fortifica los muros de Forjaz para evitar que se derrumbe la ciudad!$B$BCoge los cajones de fortificación de muro que hay por la ciudad$B$By colócalos en los puntos marcados con una flecha roja |TInterfaceIconsABILITY_HUNTER_MARKEDFORDEATH.blp:32|t.' WHERE `ID`=42699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줘버려! 랩터를 줘버리게! 내 얼굴에 칼집 나는 건 싫어!', `MaleText_loc4`='照做！把迅猛龙给他！我不喜欢他把剑指在我脸上的感觉！', `MaleText_loc5`='快點!把迅猛龍給他!我不喜歡被這把劍指著臉!', `MaleText_loc7`='¡Hazlo! ¡Dale el raptor! ¡No me guh''ta que ponga su eh''pada tan cerca de mi cara!' WHERE `ID`=42700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 따돌린 것 같군.', `MaleText_loc4`='我想我失去它们了。', `MaleText_loc5`='我想我把他們甩掉了。', `MaleText_loc7`='Creo que los he perdido.' WHERE `ID`=42701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광학 감지 장치에 이상 발견! 시스템을 정지합니다...', `MaleText_loc4`='已发现光学感应故障！正在关闭中……', `MaleText_loc5`='偵測光學傳感器失靈!關閉中...', `MaleText_loc7`='¡Detectado fallo en sensor óptico! Apagando...' WHERE `ID`=42702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구에서 균열을 모두 없애고 주민 모두를 안전한 곳으로 대피시켰다!', `MaleText_loc4`='军事区危险已排除，而且我们已成功撤离该区市民！', `MaleText_loc5`='軍事區已經沒有裂隙，我們也完成了此區平民的疏散活動了!', `MaleText_loc7`='¡La Sala Militar está despejada de fallas y hemos llevado a cabo la completa evacuación de los ciudadanos de este distrito!' WHERE `ID`=42703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 마법 지구에는 정령이 하나도 남아 있지 않다. 붙잡혔던 형제들도 모두 구출했다!', `MaleText_loc4`='秘法区里已经没有元素了。我们还救出了所有被困住的人！', `MaleText_loc5`='秘法區已經沒有元素的存在了。我們也救出所有被困住的居民們了!', `MaleText_loc7`='Ya no habrá más elementales en la Sala Mística. ¡También hemos evacuado a todos los que estaban allí atrapados!' WHERE `ID`=42704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 방해받았습니다! 알렉스를 부르세요!', `MaleText_loc4`='我被打断了！去叫阿莱克斯！', `MaleText_loc5`='我被干擾了!快叫艾力克斯!', `MaleText_loc7`='¡HE SIDO INTERRUMPIDO! ¡LLAMA A ALEX!', `FemaleText_loc1`='지금 방해받았습니다! 알렉스를 부르세요!', `FemaleText_loc4`='我被打断了！去叫阿莱克斯！', `FemaleText_loc5`='我被干擾了!快叫艾力克斯!', `FemaleText_loc7`='¡HE SIDO INTERRUMPIDO! ¡LLAMA A ALEX!' WHERE `ID`=42705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거인이 쓰러졌습니다. 서둘러 처치하십시오!', `MaleText_loc4`='巨人倒下了。快杀了他！', `MaleText_loc5`='巨人倒下了。快殺了他!', `MaleText_loc7`='El gigante ha caído. ¡Mátalo rápidamente!', `FemaleText_loc1`='거인이 쓰러졌습니다. 서둘러 처치하십시오!', `FemaleText_loc4`='巨人倒下了。快杀了他！', `FemaleText_loc5`='巨人倒下了。快殺了他!', `FemaleText_loc7`='El gigante ha caído. ¡Mátalo rápidamente!' WHERE `ID`=42706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지가 공격받고 있습니다! 도시를 보호하러 가려면 그만큼 아주 강해야 할 거예요.$b$b마그니 폐하께서는 도시에 있는 모든 주민의 대피를 지시하셨고 제게 그 임무를 맡기셨죠. 괜히 거기로 갔다가 부상당하고 나서 저를 원망하지 마세요!', `MaleText_loc4`='铁炉堡遭到了攻击！要是你想进去，你最好足够强壮以参与到保卫城市的战斗中去。$B$B国王麦格尼·铜须已下达全面撤离的命令，并要我负责这项工作。不要进去了，万一你受伤又要怪到我头上来！', `MaleText_loc5`='鐵爐堡正遭受到攻擊!你最好擁有防衛城市的能力再進去那裡。$B$B麥格尼·銅鬚國王下令疏散這個城市和指派我進行監督。別進去那，你受傷後一定會怪到我的頭上!', `MaleText_loc7`='¡Están atacando Forjaz! Más te vale que seas muy fuerte si quieres entrar ahí.$B$BEl rey Magni ha ordenado la evacuación total de la ciudad y me ha puesto al mando de la operación. ¡Si entras ahí y te hieren, no me eches a mí la culpa!' WHERE `ID`=42707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 날아 봐라, 쥐새끼야!', `MaleText_loc4`='但愿你会飞，小不点儿！', `MaleText_loc5`='希望你會飛，垃圾!', `MaleText_loc7`='¡Ojalá sepas volar, inútil!' WHERE `ID`=42708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거네, $n!', `MaleText_loc4`='就是那样，$n！', `MaleText_loc5`='就是這樣，$n!', `MaleText_loc7`='¡Así se hace, $n!', `FemaleText_loc1`='바로 그겁니다, $n!', `FemaleText_loc4`='就是那样，$n！', `FemaleText_loc5`='就是這樣，$n!', `FemaleText_loc7`='¡Así se hace, $n!' WHERE `ID`=42709;
