UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아닌 것 같군, $n!', `MaleText_loc4`='你令人闻风丧胆的$c威名可真是名不虚传啊，$n！', `MaleText_loc5`='做為一個傑出的$c，你證明了自己，$n!', `MaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!', `FemaleText_loc1`='무시무시한 $c|1이라는;라는; 호칭은 그냥 얻어진 게 아닌 것 같군요, $n!', `FemaleText_loc4`='你令人闻风丧胆的$c威名可真是名不虚传啊，$n！', `FemaleText_loc5`='做為一個傑出的$c，你證明了自己，$n!', `FemaleText_loc7`='¡Parece ser que tu reputación de $c formidable es bien merecida, $n!' WHERE `ID`=42714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 전투 실력이군, $n.', `MaleText_loc4`='你的作战技巧可真令人难忘，$n。', `MaleText_loc5`='你的作戰本事真是令人嘆為觀止，$n。', `MaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.', `FemaleText_loc1`='놀라운 전투 실력이군요, $n.', `FemaleText_loc4`='你的作战技巧可真令人难忘，$n。', `FemaleText_loc5`='你的作戰本事真是令人嘆為觀止，$n。', `FemaleText_loc7`='Tus habilidades en el combate son impresionantes, $n.' WHERE `ID`=42715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거라네, $n!', `MaleText_loc4`='简直无懈可击，$n！', `MaleText_loc5`='就是這樣做沒錯，$n!', `MaleText_loc7`='¡Así es como tiene que hacerse, $n!', `FemaleText_loc1`='바로 그겁니다, $n!', `FemaleText_loc4`='简直无懈可击，$n！', `FemaleText_loc5`='就是這樣做沒錯，$n!', `FemaleText_loc7`='¡Así es como tiene que hacerse, $n!' WHERE `ID`=42716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기는 생각도 말게, $n!', `MaleText_loc4`='千万别松懈，想都别想，$n！', `MaleText_loc5`='別想要打混，$n!', `MaleText_loc7`='¡Ni se te ocurra ceder un milímetro, $n!', `FemaleText_loc1`='포기는 생각도 마세요, $n!', `FemaleText_loc4`='千万别松懈，想都别想，$n！', `FemaleText_loc5`='別想要打混，$n!', `FemaleText_loc7`='¡Ni se te ocurra ceder un milímetro, $n!' WHERE `ID`=42717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추지 말고 공격하게, $n!', `MaleText_loc4`='持续攻击，$n！', `MaleText_loc5`='不要停下攻勢，$n!', `MaleText_loc7`='¡Insiste en el ataque, $n!', `FemaleText_loc1`='멈추지 말고 공격하세요, $n!', `FemaleText_loc4`='持续攻击，$n！', `FemaleText_loc5`='不要停下攻勢，$n!', `FemaleText_loc7`='¡Insiste en el ataque, $n!' WHERE `ID`=42718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 정말 최고로 효과적인 투사군, $n!', `MaleText_loc4`='你是最具战斗力的斗士，$n！', `MaleText_loc5`='你是個天生的戰士，$n!', `MaleText_loc7`='¡Eres $gun luchador:una luchadora; de lo más eficaz, $n!', `FemaleText_loc1`='당신 정말 최고로 효과적인 투사군요, $n!', `FemaleText_loc4`='你是最具战斗力的斗士，$n！', `FemaleText_loc5`='你是個天生的戰士，$n!', `FemaleText_loc7`='¡Eres $gun luchador:una luchadora; de lo más eficaz, $n!' WHERE `ID`=42719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $c!$B$B끝내주는 돈벌이가 있는데, 관심 있어? 10분의 1만큼 떼줄게! 1퍼센트 중에 말이야!', `MaleText_loc4`='嘿，$c！$B$B有兴趣签几份赚钱的合约吗？我会分给你十分之一！百分之一的十分之一！', `MaleText_loc5`='喂，$c!$B$B最近有什麼賺頭嗎?我會將十分之一的利潤分給你，百分之一的十分之一!', `MaleText_loc7`='¡Eh, $c!$B$B¿Tienes alguna idea de dónde conseguir contratos lucrativos? ¡Te daré una décima parte! ¡De una décima parte!' WHERE `ID`=42720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 문제야, $c?$B$B자네가 내 작업장을 헤집고 다닌다는 소문이 들리던데...', `MaleText_loc4`='到底是怎么回事，$c？$B$B码头附近有传言说，你最近一直在我的建筑工地附近游荡……', `MaleText_loc5`='怎麼回事啊，$c?$B$B碼頭上有人說你在我的建築工地鬼鬼祟祟的...', `MaleText_loc7`='¿Qué hay, $c?$B$BSe dice en los muelles que has estado fisgoneando en mis obras...' WHERE `ID`=42721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 헬스크림 님의 기대에 못 미치게 일을 해선 안 됩니다. 배를 완성하세요. 제대로 말입니다... 아니면 일이 고약해질 걸요.', `MaleText_loc4`='没人敢不把加尔鲁什·地狱咆哮放在眼里。你赶紧造好这些船——还要造得漂亮——否则就是给你自己找麻烦。', `MaleText_loc5`='沒有人敢騙卡爾洛斯·地獄吼。你把船造好—而且立刻造好—否則我就要給你好看。', `MaleText_loc7`='Nadie tima a Garrosh Grito Infernal. Vas a terminar esos barcos, y vas a terminarlos bien, o esto se convertirá en algo personal.', `FemaleText_loc1`='가로쉬 헬스크림 님의 기대에 못 미치게 일을 해선 안 됩니다. 배를 완성하세요. 제대로 말입니다... 아니면 일이 고약해질 걸요.', `FemaleText_loc4`='没人敢不把加尔鲁什·地狱咆哮放在眼里。你赶紧造好这些船——还要造得漂亮——否则就是给你自己找麻烦。', `FemaleText_loc5`='沒有人敢騙卡爾洛斯·地獄吼。你把船造好—而且立刻造好—否則我就要給你好看。', `FemaleText_loc7`='Nadie tima a Garrosh Grito Infernal. Vas a terminar esos barcos, y vas a terminarlos bien, o esto se convertirá en algo personal.' WHERE `ID`=42722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이익!', `FemaleText_loc4`='呀！', `FemaleText_loc5`='咿哎!', `FemaleText_loc7`='¡Yiiik!' WHERE `ID`=42723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 남의 사업에 감 놔라 배 놔라 하는 거야!', `MaleText_loc4`='我用不着别人来告诉我该怎么在这儿做生意。', `MaleText_loc5`='沒人能教我如何在這做我自己的生意。', `MaleText_loc7`='Nadie me dice cómo tengo que llevar el negocio.' WHERE `ID`=42724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하십시오! 땅이 흔들리고 불길이 더 뜨겁게 타오릅니다! 지금이라도 여기서 나갈 수 있다면 나가십시오!', `MaleText_loc4`='做好准备！大地在震颤，火焰也燃烧得更猛烈！要是你还能逃脱，就赶紧走！', `MaleText_loc5`='準備好了!大地在震動，火焰也越燒越烈!趁你還來得及之前快走!', `MaleText_loc7`='¡Cuidado! ¡La tierra tiembla y el fuego arde con más fuerza! ¡Sal de aquí mientras puedas!', `FemaleText_loc1`='준비하십시오! 땅이 흔들리고 불길이 더 뜨겁게 타오릅니다! 지금이라도 여기서 나갈 수 있다면 나가십시오!', `FemaleText_loc4`='做好准备！大地在震颤，火焰也燃烧得更猛烈！要是你还能逃脱，就赶紧走！', `FemaleText_loc5`='準備好了!大地在震動，火焰也越燒越烈!趁你還來得及之前快走!', `FemaleText_loc7`='¡Cuidado! ¡La tierra tiembla y el fuego arde con más fuerza! ¡Sal de aquí mientras puedas!' WHERE `ID`=42725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨어지는 바위를 조심하십시오! 땅이 점점 더 심하게 흔들립니다. 도시에서 나가십시오!', `MaleText_loc4`='小心那些滚落的石头！大地颤动得更为剧烈了。快逃离城市！', `MaleText_loc5`='注意落石!地面越晃越厲害了。逃離這個城市!', `MaleText_loc7`='¡Cuidado con los desprendimientos de rocas! El suelo tiembla con más fuerza. ¡Huye de la ciudad!', `FemaleText_loc1`='떨어지는 바위를 조심하세요! 땅이 점점 더 심하게 흔들립니다. 도시에서 나가세요!', `FemaleText_loc4`='小心那些滚落的石头！大地颤动得更为剧烈了。快逃离城市！', `FemaleText_loc5`='注意落石!地面越晃越厲害了。逃離這個城市!', `FemaleText_loc7`='¡Cuidado con los desprendimientos de rocas! El suelo tiembla con más fuerza. ¡Huye de la ciudad!' WHERE `ID`=42726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 시민 여러분! 도시를 비우고 대피하십시오!', `MaleText_loc4`='铁炉堡的市民们！开始撤离！', `MaleText_loc5`='鐵爐堡的人民!開始進行疏散!', `MaleText_loc7`='¡Ciudadanos de Forjaz! ¡Que comience la evacuación!', `FemaleText_loc1`='아이언포지의 시민 여러분! 도시를 비우고 대피하십시오!', `FemaleText_loc4`='铁炉堡的市民们！开始撤离！', `FemaleText_loc5`='鐵爐堡的人民!開始進行疏散!', `FemaleText_loc7`='¡Ciudadanos de Forjaz! ¡Que comience la evacuación!' WHERE `ID`=42727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지 방문객 여러분! 도시에서 나가십시오! 도시가 언제 무너질지 모릅니다!', `MaleText_loc4`='铁炉堡的宾客们！快离开！城市随时都会倒塌！', `MaleText_loc5`='鐵爐堡的客人們!快離開這個城市!它隨時都有可能會垮掉!', `MaleText_loc7`='¡Invitados de Forjaz! ¡Salid de la ciudad! ¡Puede derrumbarse de un momento a otro!', `FemaleText_loc1`='아이언포지 방문객 여러분! 도시에서 나가세요! 도시가 언제 무너질지 모릅니다!', `FemaleText_loc4`='铁炉堡的宾客们！快离开！城市随时都会倒塌！', `FemaleText_loc5`='鐵爐堡的客人們!快離開這個城市!它隨時都有可能會垮掉!', `FemaleText_loc7`='¡Invitados de Forjaz! ¡Salid de la ciudad! ¡Puede derrumbarse de un momento a otro!' WHERE `ID`=42728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨어지는 바위를 조심하십시오! 거리를 비우십시오!', `MaleText_loc4`='小心那些滚落的石头！清空街道！', `MaleText_loc5`='注意落石!淨空街道!', `MaleText_loc7`='¡Cuidado con los desprendimientos de rocas! ¡Despejad las calles!', `FemaleText_loc1`='떨어지는 바위를 조심하세요! 거리를 비우세요!', `FemaleText_loc4`='小心那些滚落的石头！清空街道！', `FemaleText_loc5`='注意落石!淨空街道!', `FemaleText_loc7`='¡Cuidado con los desprendimientos de rocas! ¡Despejad las calles!' WHERE `ID`=42729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에서 나가십시오! 땅의 흔들림이 멈추지 않습니다!', `MaleText_loc4`='快逃离城市！大地还在不停的颤动！', `MaleText_loc5`='地面一直搖動不停!快逃離此城!', `MaleText_loc7`='¡Huid de la ciudad! ¡La tierra no puede dejar de temblar!', `FemaleText_loc1`='도시에서 나가세요! 땅의 흔들림이 멈추지 않습니다!', `FemaleText_loc4`='快逃离城市！大地还在不停的颤动！', `FemaleText_loc5`='逃離此城!地面一直搖動不停!', `FemaleText_loc7`='¡Huid de la ciudad! ¡La tierra no puede dejar de temblar!' WHERE `ID`=42730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘은 점점 어두워지고 정령들의 공격이 멈추지 않습니다! 피난처를 찾으십시오!', `MaleText_loc4`='天黑下来了，元素们变得越来越躁动不安！快找地方躲起来！', `MaleText_loc5`='天空變暗，元素也變得狂暴了!尋找庇護所!', `MaleText_loc7`='¡El cielo se oscurece y los elementos están nerviosos! ¡Buscad refugio!', `FemaleText_loc1`='하늘은 점점 어두워지고 정령들의 공격이 멈추지 않습니다! 피난처를 찾으세요!', `FemaleText_loc4`='天黑下来了，元素们变得越来越躁动不安！快找地方躲起来！', `FemaleText_loc5`='天空變暗，元素也變得狂暴了!尋找庇護所!', `FemaleText_loc7`='¡El cielo se oscurece y los elementos están nerviosos! ¡Buscad refugio!' WHERE `ID`=42731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마십시오! 구름이 몰려오고 바람이 점점 거세지고 있습니다! 피난처를 찾으십시오!', `MaleText_loc4`='做好防卫！云团滚滚而来，狂风骤起！快躲起来！', `MaleText_loc5`='整裝戒備!這裡即將風起雲湧!快尋找避難的地方!', `MaleText_loc7`='¡Estad alerta! ¡Las nubes se acercan y los vientos soplan más fuerte! ¡Buscad refugio!', `FemaleText_loc1`='경계를 늦추지 마세요! 구름이 몰려오고 바람이 점점 거세지고 있습니다! 피난처를 찾으세요!', `FemaleText_loc4`='做好防卫！云团滚滚而来，狂风骤起！快躲起来！', `FemaleText_loc5`='整裝戒備!這裡即將風起雲湧!快尋找避難的地方!', `FemaleText_loc7`='¡Estad alerta! ¡Las nubes se acercan y los vientos soplan más fuerte! ¡Buscad refugio!' WHERE `ID`=42732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 시민 여러분! 도시를 비우십시오!', `MaleText_loc4`='雷霆崖的市民们！撤离城市！', `MaleText_loc5`='雷霆崖的居民!趕快進行撤離!', `MaleText_loc7`='¡Ciudadanos de Cima del Trueno! ¡Evacuad la ciudad!', `FemaleText_loc1`='썬더 블러프 시민 여러분! 도시를 비우십시오!', `FemaleText_loc4`='雷霆崖的市民们！撤离城市！', `FemaleText_loc5`='雷霆崖的居民!趕快進行撤離!', `FemaleText_loc7`='¡Ciudadanos de Cima del Trueno! ¡Evacuad la ciudad!' WHERE `ID`=42733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람이 거세지고 있습니다! 승강기를 타고 안전한 땅으로 내려가십시오!', `MaleText_loc4`='风力越来越大了！快乘升降机去安全的地方！', `MaleText_loc5`='風越來越大了!快搭升降梯到安全的場所!', `MaleText_loc7`='¡Los vientos son más fuertes! ¡Tomad los ascensores para bajar a un sitio más seguro!', `FemaleText_loc1`='바람이 거세지고 있습니다! 승강기를 타고 안전한 땅으로 내려가십시오!', `FemaleText_loc4`='风力越来越大了！快乘升降机去安全的地方！', `FemaleText_loc5`='風越來越大了!快搭升降梯到安全的場所!', `FemaleText_loc7`='¡Los vientos son más fuertes! ¡Tomad los ascensores para bajar a un sitio más seguro!' WHERE `ID`=42734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 비우십시오! 절벽 근처로 가지 마십시오!', `MaleText_loc4`='清空道路！别待在绝壁两侧！', `MaleText_loc5`='淨空走道!不要站在懸崖的邊緣上!', `MaleText_loc7`='¡Despejad los caminos! ¡Alejaos de los bordes de la cima!', `FemaleText_loc1`='길을 비우십시오! 절벽 근처로 가지 마십시오!', `FemaleText_loc4`='清空道路！别待在绝壁两侧！', `FemaleText_loc5`='淨空走道!不要站在懸崖的邊緣上!', `FemaleText_loc7`='¡Despejad los caminos! ¡Alejaos de los bordes de la cima!' WHERE `ID`=42735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프를 비우고 대피하십시오! 절벽 가까이 가지 마십시오!', `MaleText_loc4`='撤离雷霆崖！都别待在绝壁两侧！', `MaleText_loc5`='撤離雷霆崖!不要站在懸崖的邊緣上!', `MaleText_loc7`='¡Evacuad la Cima del Trueno! ¡Alejaos de los bordes de la cima!', `FemaleText_loc1`='썬더 블러프를 비우고 대피하십시오! 절벽 가까이 가지 마십시오!', `FemaleText_loc4`='撤离雷霆崖！都别待在绝壁两侧！', `FemaleText_loc5`='撤離雷霆崖!不要站在懸崖的邊緣上!', `FemaleText_loc7`='¡Evacuad la Cima del Trueno! ¡Alejaos de los bordes de la cima!' WHERE `ID`=42736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고작 이음못 몇 개 뺐을 뿐이라고. 워낙 많이 박혀 있어서 말이야!', `MaleText_loc4`='只是几颗铆钉而已。船上多得是！', `MaleText_loc5`='不過是幾根釘子罷了。那艘船上有很多!', `MaleText_loc7`='Fueron solo un par de remaches. ¡Ese barco tenía un montón!' WHERE `ID`=42738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔잔한 바다에서 항해하는 데는 아무 문제 없다고.', `MaleText_loc4`='我确定它在平静的水域中航行时一定会平稳得多。', `MaleText_loc5`='我相信在靜海上一定就可以安全地出航。', `MaleText_loc7`='Estoy seguro de que habría sido muy marinero en aguas tranquilas.' WHERE `ID`=42739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이음못을 덜 쓰는 건 환경을 보호하는 길이야!', `MaleText_loc4`='少几颗铆钉就意味着更整洁的环境！', `MaleText_loc5`='鉚釘越少越環保!', `MaleText_loc7`='¡Menos remaches significan un medio ambiente más limpio!' WHERE `ID`=42740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 얼마면 눈감아 줄래?', `MaleText_loc4`='……我们能用钱解决这个问题吗？', `MaleText_loc5`='...可不可以用現金解決?', `MaleText_loc7`='¿... no podemos solucionarlo con dinero?' WHERE `ID`=42741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 알았다고. 그만! 그만! 충분히 알아들었어.', `MaleText_loc4`='好吧好吧，停！停！你可真有说服力。', `MaleText_loc5`='好，好，停止!你的論點很有說服力。', `MaleText_loc7`='¡Vale, vale, para! ¡Para! Tu argumento tiene mucho peso.' WHERE `ID`=42742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업 시간 두 배로 늘리고 내 돈 들여서 일정 맞춰 튼튼하게 만들어 줄게. 믿어 달라고!', `MaleText_loc4`='我会让工人们加班加点，再从自己的腰包里掏钱来让这些船能禁得起大风大浪并且按时交工。放心吧！', `MaleText_loc5`='我會派人加班趕工，而且花我自己的錢來造好這些船，追上進度，讓它們可以順利出海航行。我保證!', `MaleText_loc7`='Doblaré los turnos de los trabajadores e invertiré mi propio dinero para conseguir que esos barcos sean aptos para el mar y se terminen en el plazo acordado. ¡Cuenta con ello!' WHERE `ID`=42743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 마구잡이로 하는 공격이 아닐세. 정령과 거인들이 힘을 합쳐 우리를 노리는군. 뭔진 몰라도 우리가 바위 어머니, 테라제인 님의 노여움을 산 모양일세.', `MaleText_loc4`='关于此次攻击没什么混乱的。元素和巨人们有组织地前来对付我们。看来我们在不经意间引起了石母本人——塞拉赞恩的愤怒。', `MaleText_loc5`='這不是胡亂發動的攻擊，而是元素和巨人聯合起來對抗我們。看來，我們似乎激怒了石母瑟拉贊恩。', `MaleText_loc7`='No hay nada caótico en eh''te ataque. Los elementales y los gigantes se han organizado para atacah''nos. De alguna manera nos hemos granjeado la ira de Therazane, la Madre Pétrea en persona.' WHERE `ID`=42744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄구룹에 온 걸 환영한다, 오간아카여... 지금은 별거 없어 보일지 모르지만, 우리가 발전해 나가는 모습을 천천히 지켜보거라...', `MaleText_loc4`='欢迎来到祖尔格拉布，小不点儿。它现在的样子可能和以往大相径庭，但假以时日……', `MaleText_loc5`='歡迎來到祖爾格拉布，小傢伙。現在或許看起來還不怎麼樣，但給它一點時間...', `MaleText_loc7`='Te doy la bienvenida a Zul''Gurub, pequeña. Ahora no te parecerá gran cosa, pero dame tiempo...' WHERE `ID`=42745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 고향으로 돌아오니 참 좋군.', `MaleText_loc4`='啊……回家的感觉真好。', `MaleText_loc5`='啊哈...回到家真好。', `MaleText_loc7`='Aaah... es agradable eh''tar en casa.' WHERE `ID`=42746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 네 친구들이 아주 많지, 하지만 경쟁할 필요 없다. 넌 내 가장 오랜 친구인 오간의 피를 이어받았거든... 알겠나. 우리의 영혼은... 너와 나의 영혼은 하나로 연결되어 있는 거야.', `MaleText_loc4`='在这儿有许多像你一样的人，可我并不担心竞争。你有着我的老朋友——奥根的血统。你看……我们的灵魂交织在一起，你的和我的。', `MaleText_loc5`='這裡有很多你的同類，但是我一點也不擔心你會被比下去，因為你繼承了我的老朋友奧根的血脈。你要知道...我們的靈魂，是彼此相連的。', `MaleText_loc7`='Aquí hay muchos como tú, pero no te preocupes por la competencia. Tú tienes la sangre de Oghan, mi más antiguo amigo. Verás... nueh''tras almas eh''tán entrelazadas, la tuya y la mía.' WHERE `ID`=42747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했군. 이제 곧 훈련을 시작할 테니 준비하거라, 오간아카. 쓸모없는 $r $c 따윈 잊어버리고 줄구룹에서 네가 해야 할 일에만 전념하는 거다.', `MaleText_loc4`='好了，准备开始训练吧，小家伙。我建议你忘记关于$r $c那些没用的东西，开始思考你在祖尔格拉布的责任。', `MaleText_loc5`='到啦。準備好接受訓練，小傢伙。我建議你忘了那個沒用的$r$c，開始專心你在祖爾格拉布的工作。', `MaleText_loc7`='Ya eh''tamos. Prepárate pa'' tu inh''trucción pequeña. Recomiendo que olvides a $gese:esa; $r $c inútil y te centres en tus deberes aquí, en Zul''Gurub.' WHERE `ID`=42748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 싫어! 옹고롱고 집에 가고 싶다!', `MaleText_loc4`='没有了！安戈龙格回家了！', `MaleText_loc5`='夠了!翁戈隆戈快回去!', `MaleText_loc7`='¡BASTA! ¡ONGOLONGO IR A CASA!' WHERE `ID`=42749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없는 트롤들은 옹고롱고 못 막는다!', `MaleText_loc4`='弱小的巨魔别想阻止安戈龙格！', `MaleText_loc5`='翁戈隆戈不怕弱小的食人妖!', `MaleText_loc7`='¡TROLS ENCLENQUES NO DETENER A ONGOLONGO!' WHERE `ID`=42750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 줄구룹에 대해 잘 알고 있습니다.$b$b아마 제 도움이 필요할 겁니다.', `FemaleText_loc4`='祭司了解很多与祖尔格拉布有关的事。$b$b祭司认为你需要她的帮助。', `FemaleText_loc5`='女祭師對祖爾格拉布非常瞭解。$b$b女祭師認為你需要她的幫忙。', `FemaleText_loc7`='La sacerdotisa sabe mucho sobre Zul''Gurub.$b$bLa sacerdotisa cree que puedes necesitar su ayuda.' WHERE `ID`=42751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음의 눈 의식을 치를 준비가 되었습니다, 후랄라.', `MaleText_loc4`='我准备好开始意识影像仪式了，胡纳拉。', `MaleText_loc5`='我已經準備好進行心靈幻象的儀式了，胡瑞拉。', `MaleText_loc7`='Estoy listo para el ritual de Visión mental, Hu''rala.', `FemaleText_loc1`='마음의 눈 의식을 치를 준비가 되었어요, 후랄라.', `FemaleText_loc4`='我准备好开始意识影像仪式了，胡纳拉。', `FemaleText_loc5`='我已經準備好進行心靈幻象的儀式了，胡瑞拉。', `FemaleText_loc7`='Estoy lista para el ritual de Visión mental, Hu''rala.' WHERE `ID`=42752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 우리로 돌아가!', `MaleText_loc4`='你给我回到围栏里去！', `MaleText_loc5`='給我進去那個柵欄裡!', `MaleText_loc7`='¡Vuelve a ese cubil!' WHERE `ID`=42753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크러쉬코그의 패배는 그의 주인인 텔마플러그에게 엄청난 충격을 안겨줄 것이네. 놈리건의 노움들은 절대로 멈추지 않을 거야!', `MaleText_loc4`='碎轮的失败将向他的主人瑟玛普拉格发出强大的信息。诺莫瑞根的侏儒是不可被阻止的！', `MaleText_loc5`='擊敗碾輪是我們送給它的主人瑟瑪普拉格的強力證明，沒人可以阻擋諾姆瑞根的地精!', `MaleText_loc7`='La derrota de Prensadiente enviará un poderoso mensaje a su amo, Termochufe. ¡No detendrán a los gnomos de Gnomeregan!' WHERE `ID`=42754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 시작할 준비가 되었습니다.', `MaleText_loc4`='我已经准备好发起攻击了。', `MaleText_loc5`='我準備好發動攻擊了。', `MaleText_loc7`='Estoy preparado para comenzar el asalto.', `FemaleText_loc1`='공격을 시작할 준비가 되었습니다.', `FemaleText_loc4`='我已经准备好发起攻击了。', `FemaleText_loc5`='我準備好發動攻擊了。', `FemaleText_loc7`='Estoy preparada para comenzar el asalto.' WHERE `ID`=42755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 피할 순 없을 것이다!', `MaleText_loc4`='我已得出结论——你必须死！', `MaleText_loc5`='我推論的結果就是:你必須要死!', `MaleText_loc7`='¡He deducido que debes morir!' WHERE `ID`=42756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 결말을 예상했어야... 했는데...', `MaleText_loc4`='我应该……预见到……的……', `MaleText_loc5`='我應該要...預測到...這個的...', `MaleText_loc7`='Debí... predecir... esto...' WHERE `ID`=42757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계박사 텔마플러그는 패배가 다가오고 있음을 절대로 인정하지 않는다. 놈은 라즐로 크러쉬코그를 보내, 우리가 사랑하는 놈리건의 재건을 방해하고 있다!', `MaleText_loc4`='机械师瑟玛普拉格拒绝承认他的失败已经近在眼前！现在，他又派出了拉兹诺·碎轮来阻止我们重新建设我们亲爱的诺莫瑞根！', `MaleText_loc5`='機電師瑟瑪普拉格拒絕承認他的失敗是遲早的事!他派出了拉茲羅·碾輪來阻止我們重建摯愛的諾姆瑞根!', `MaleText_loc7`='¡El Meikgeniero Termochufe no acepta que su derrota es inminente! ¡Ha mandado a Razlo Prensadiente a que impida la reconstrucción de Gnomeregan!' WHERE `ID`=42758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 여기 있는 용감한 친구가 놈을 번번이 좌절시켰고, 이제 아이언포지의 드워프 동료들도 우리와 함께한다!', `MaleText_loc4`='但是我们勇敢的朋友$n已经挫败了他们的邪恶计划。铁炉堡的矮人也在与我们并肩作战！', `MaleText_loc5`='但是我們這裡的勇敢朋友阻撓了他計畫的每一步，而現在鐵爐堡的矮人們也跟我們同一陣線!', `MaleText_loc7`='¡Pero nuestro valiente amigo desbarató su plan y ahora los enanos de Forjaz se nos unieron!' WHERE `ID`=42759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 혼내 주자. 엉엉 울면서 주인에게 돌아가게 만들자!', `MaleText_loc4`='让我们击败他，让他爬着回去见他的主子！', `MaleText_loc5`='讓我們擊敗他，讓他爬著回去見他的主人。', `MaleText_loc7`='¡Hagamos que vuelva con su amo arrastrándose!' WHERE `ID`=42760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니! 어떻게 경비로봇을 통과해 여기까지 온 거지?', `MaleText_loc4`='你！怎么可能逃过我的哨兵机器人？这不可能！', `MaleText_loc5`='你!你是怎麼躲過我哨衛機器人的偵測?', `MaleText_loc7`='¡Tú! ¿Cómo evadiste la detección de mis Avizor-bots?' WHERE `ID`=42761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상관없어! 내 부하들과 함께 순식간에 처리해 주마. 공격해라, 제군들!', `MaleText_loc4`='没有关系！我会带领护卫迅速地干掉你。准备战斗！', `MaleText_loc5`='沒關係!我和我的守衛會讓你吃不完兜著走。大家準備戰鬥!', `MaleText_loc7`='¡No importa! Mis guardianes y yo te eliminaremos en segundos. ¡A las armas, señores!' WHERE `ID`=42762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈다! 마침내 놈을 쓰러뜨렸어! 으하하하하!', `MaleText_loc4`='我们成功了！我们胜利了！', `MaleText_loc5`='我們成功了!我們獲得了勝利!', `MaleText_loc7`='¡Lo logramos! ¡La victoria es nuestra!' WHERE `ID`=42763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사모플랜지!', `MaleText_loc4`='主动式负载平衡器！', `MaleText_loc5`='平衡器!', `MaleText_loc7`='¡CHURUMBELE!' WHERE `ID`=42764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크러쉬코그의 패배를 보며 텔마플러그 놈이 기계보행전차 안에서 벌벌 떨겠군! 마땅히 그래야지! 다음은 네놈이다, 텔마플러그! 기다려라!', `MaleText_loc4`='碎轮被打败了，瑟玛普拉格一定正在他的机械坦克里发抖，下一个完蛋的就是你，瑟玛普拉格，下一个就是你！', `MaleText_loc5`='碾輪被擊敗後，瑟瑪普拉格一定嚇得在他的機械坦克中發抖，活該!下個就是你，瑟瑪普拉格，就是你!', `MaleText_loc7`='¡Tras la derrota de Prensadiente, seguro que Termochufe está temblando dentro de su mecanotanque, como debe ser! ¡Ahora tú, Termochufe! ¡Ahora tú!' WHERE `ID`=42765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 네놈에게 놈리건과 아이언포지의 위대함에 함부로 덤빈 대가다!', `MaleText_loc4`='这就是你招惹强大铁炉堡和诺莫瑞根的下场！', `MaleText_loc5`='找鐵爐堡和諾姆瑞根麻煩的下場就是這樣!', `MaleText_loc7`='¡Eso te enseñará a meterte con el poder de Forjaz y Gnomeregan!' WHERE `ID`=42766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았습니다. 이 오염된 노움들을 혼쭐 내주겠습니다!', `MaleText_loc4`='对，让我们给这脑筋错乱的侏儒上一课！', `MaleText_loc5`='嗯，讓我們給這腦筋爛掉的地精上一堂課!', `MaleText_loc7`='¡Sí, démosle una buena lección a ese gnomo cerebro de chorlito!' WHERE `ID`=42767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 스무트를 밀쳐내 땅에 쓰러뜨립니다.', `MaleText_loc4`='$n一把推开斯姆特，把他丢到了地上。', `MaleText_loc5`='$n一把推開斯穆特，把他扔到地上。', `MaleText_loc7`='$n tensa los brazos de Smoot y lo arroja al suelo.' WHERE `ID`=42768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 사모플랜지야... 지켜주지 못해서 미안해!', `MaleText_loc4`='喔主动式负载平衡器……我让你失望了！', `MaleText_loc5`='嗚，平衡器啊...我對不起你!', `MaleText_loc7`='Oh, churumbele… ¡te he fallado!' WHERE `ID`=42769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북서쪽 전장에 당신의 도움이 필요합니다! 떠나십시오!', `MaleText_loc4`='他们正在西北边的战场上等着你！快去吧！', `MaleText_loc5`='他們需要你在西北方的戰場!快去!', `MaleText_loc7`='¡Te necesitan en el campo del noroeste! ¡Ve!' WHERE `ID`=42770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원이 포위당했습니다. 서둘러 밖으로 가십시오!', `MaleText_loc4`='神殿被包围了。我们需要你出去，马上！', `MaleText_loc5`='神殿遭到攻擊，快點到外面去!', `MaleText_loc7`='El templo está bajo asedio. ¡Te necesitamos fuera, ahora!' WHERE `ID`=42771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 가십시오!', `MaleText_loc4`='到战场上去！', `MaleText_loc5`='快到戰場上去!', `MaleText_loc7`='¡Ve al campo de batalla!' WHERE `ID`=42772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없습니다. 병사들이 당신의 도움을 기다리고 있습니다!', `MaleText_loc4`='继续前进！他们需要你前去支援！', `MaleText_loc5`='繼續前進!他們需要你在戰場上!', `MaleText_loc7`='¡Sigue andando! ¡Te necesitan en el campo!' WHERE `ID`=42773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병력이 북서쪽에 적들을 상대하고 있습니다. 그 전투에 합류하십시오!', `MaleText_loc4`='我们在西北面拖住他们了——增援前线！', `MaleText_loc5`='我們在西北邊擋住了他們─前線需要增援!', `MaleText_loc7`='Los estamos manteniendo a raya en el noroeste. ¡Ve a reforzar la línea!' WHERE `ID`=42774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북서쪽에서 우리 형제들이 쓰러지고 있습니다. 그쪽으로 가 형제들을 도우십시오!', `MaleText_loc4`='我们的兄弟们在西北面遇到了危险。快去帮帮他们！', `MaleText_loc5`='我們的兄弟們在往西北邊撤退。快出來幫助他們!', `MaleText_loc7`='Nuestros hermanos caen al noroeste. ¡Ve allí y ayúdales!' WHERE `ID`=42775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령들이 우리를 공격하고 있습니다. 전장으로 가서 정령들을 물리치십시오!', `MaleText_loc4`='土元素转而攻击我们了。快到战场上阻击他们！', `MaleText_loc5`='石元素開始攻擊我們了。趕快進行防衛!', `MaleText_loc7`='Los elementales de tierra se han rebelado contra nosotros. ¡Ve al campo de batalla y contenlos!' WHERE `ID`=42776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령과 거인들이 우리를 포위했습니다! 북서쪽으로 가서 적과 맞서 싸우십시오!', `MaleText_loc4`='我们被元素和巨人包围了！西北面需要你的援助，大地守护者！', `MaleText_loc5`='我們被元素和巨人圍攻了!我們在西北方需要你的幫忙，大地守衛!', `MaleText_loc7`='¡Nos asedian elementales y gigantes! ¡Necesitan tu ayuda en el frente noroeste, elementalista!' WHERE `ID`=42777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 귀환 장소로 설정합니다.', `MaleText_loc4`='将炉石绑在此处。', `MaleText_loc5`='綁定在此。', `MaleText_loc7`='Vincularse aquí.', `FemaleText_loc1`='이곳을 귀환 장소로 설정합니다.', `FemaleText_loc4`='将炉石绑在此处。', `FemaleText_loc5`='綁定在此。', `FemaleText_loc7`='Vincularse aquí.' WHERE `ID`=42778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식과 음료를 구입합니다.', `MaleText_loc4`='购买食物和饮料。', `MaleText_loc5`='購買食物和飲水。', `MaleText_loc7`='Compra agua y comida.', `FemaleText_loc1`='음식과 음료를 구입합니다.', `FemaleText_loc4`='购买食物和饮料。', `FemaleText_loc5`='購買食物和飲水。', `FemaleText_loc7`='Compra agua y comida.' WHERE `ID`=42779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 쉬시지요. 음식과 물도 있답니다.', `MaleText_loc4`='你可以在此休息，这里还有食物和饮料可供享用。', `MaleText_loc5`='你可以在這裡休息，而且有食物和飲水。', `MaleText_loc7`='Puedes descansar aquí, hay agua y comida.', `FemaleText_loc1`='이곳에서 쉬시지요. 음식과 물도 있답니다.', `FemaleText_loc4`='你可以在此休息，这里还有食物和饮料可供享用。', `FemaleText_loc5`='你可以在這裡休息，而且有食物和飲水。', `FemaleText_loc7`='Puedes descansar aquí, hay agua y comida.' WHERE `ID`=42780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈리건의 진정한 자손이 네놈들에게 질 것 같으냐!', `MaleText_loc4`='你永远也不可能战胜真正的诺莫瑞根之子！', `MaleText_loc5`='你永遠無法擊敗真正的諾姆瑞根之子!', `MaleText_loc7`='¡Nunca vencerás a los verdaderos hijos de Gnomeregan!' WHERE `ID`=42781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사모플랜지 만세!', `MaleText_loc4`='为主动式负载平衡器欢呼！', `MaleText_loc5`='平衡器萬歲!', `MaleText_loc7`='¡Viva el churumbele!' WHERE `ID`=42782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사모플랜지만 있으면 전부 지배할 수 있어!', `MaleText_loc4`='一部主动式负载平衡器就能统御一切！', `MaleText_loc5`='一個平衡器將統治一切!', `MaleText_loc7`='¡Un churumbele para gobernarlos a todos!' WHERE `ID`=42783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라, 사모플랜지를.', `MaleText_loc4`='来见证——主动式负载平衡器。', `MaleText_loc5`='平衡器的逆襲。', `MaleText_loc7`='Observad: El churumbele.' WHERE `ID`=42784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 만들었어. 사모플랜지는 내 거란 말이야!', `MaleText_loc4`='是我把它造出来。它是我的。主动式负载平衡器！', `MaleText_loc5`='是我打造的，所以是屬於我的。平衡器!', `MaleText_loc7`='Yo lo he construido y es mío. ¡El churumbele!' WHERE `ID`=42785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사모플랜지, 네가 못 하는 일은 없는 거지?', `MaleText_loc4`='喔，主动式负载平衡器。有什么是你办不到的吗？', `MaleText_loc5`='哦，平衡器，有什麼是你辦不到的嗎?', `MaleText_loc7`='Oh, churumbele. ¿Hay algo que pueda hacer por ti?' WHERE `ID`=42786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑한다, 사모플랜지!', `MaleText_loc4`='我爱你，主动式负载平衡器！', `MaleText_loc5`='我愛你，平衡器!', `MaleText_loc7`='¡Te quiero, churumbele!' WHERE `ID`=42787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫날 새벽부터 사모플랜지가 이룬 일을 보면서, 정말 감탄하지 않을 수 없었지.', `MaleText_loc4`='在第一天的黎明到来之时，主动式负载平衡器就看到了它所引发的一切，瞧瞧，多好。', `MaleText_loc5`='在新的一天陽光出現的那一刻，平衡器開始了它的運作。看哪!多麼地美好!', `MaleText_loc7`='Y al despuntar el alba, el primer día, el churumbele observó su obra y pensó que era buena.' WHERE `ID`=42788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망갈 생각을 하다니 용감하군, 오간아카.$b$b떠나기 전에 이빨로 트롤의 그물을 뜯고 나가는 방법을 가르쳐주지.', `MaleText_loc4`='你可真勇敢，居然想要逃走，年轻的奥根阿卡。$b$b在你继续之前，让我教你如何用牙齿咬破那些巨魔的网。', `MaleText_loc5`='年輕的奧根阿卡，你很勇敢，竟然想要逃走。$b$b在你繼續努力之前，我先來教教你怎樣用牙齒咬破食人妖的網子。', `MaleText_loc7`='Si intentas escapar es que eres muy valiente, joven Ohgan''aka.$b$bAntes de que continúes, déjame que te enseñe cómo utilizar tus dientes para romper a mordiscos las redes de los trols.' WHERE `ID`=42789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<큰 랩터에게서 그물을 물어뜯고 나가는 방법을 배웁니다.>', `MaleText_loc4`='<从年老迅猛龙那里学习用牙咬穿网的技能。>', `MaleText_loc5`='<向老迅猛龍學習怎樣咬破網子。>', `MaleText_loc7`='<Aprende del raptor viejo cómo romper las redes a mordiscos.>', `FemaleText_loc1`='<큰 랩터에게서 그물을 물어뜯고 나가는 방법을 배웁니다.>', `FemaleText_loc4`='<从年老迅猛龙那里学习用牙咬穿网的技能。>', `FemaleText_loc5`='<向老迅猛龍學習怎樣咬破網子。>', `FemaleText_loc7`='<Aprende del raptor viejo cómo romper las redes a mordiscos.>' WHERE `ID`=42790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랩터 소굴을 탈출하려고? 난 이 초소를 지키고 탈출하는 자들을 막으라고 명령받은 상태지만... 네가 탈출하려는 이유를 조금은 알 것같군.$b$b좋아. 떠나도 좋아. 하지만 그 전에 조건이 있어.$b$b보아하니 트롤들이 랩터 음식을 가지고 다닌다더군. 난 며칠째 음식을 못 먹고 있고... 싸운다면 네가 맥없이 질 게 뻔하지만 그 작은 몸을 활용해 천막에 잠들어 있는 트롤에게서 음식을 훔쳐와 줄 순 있겠지?', `MaleText_loc4`='你要离开迅猛龙巢穴了吗？我奉命守卫这岗哨并阻止逃逸，不过……我想我明白你为什么会想要离开。$b$b好吧。你可以通过这里，但首先，我有个要求。$b$b巨魔们经常会携带好多包迅猛龙爱吃的食物，而我已经许多天没进过食了。也许你打架毫无胜算，可你身形小巧，应该能趁那些巨魔熟睡时从帐篷里偷点儿吃的出来……', `MaleText_loc5`='你要離開迅猛龍巢穴?我奉命守住這裡阻止逃亡，但是...我想我可以理解為什麼你會想走。$b$b好吧，我可以放你過去。但是，我有個條件。$b$b食人妖它們經常會帶著一包包的迅猛龍食物，而我已經好幾天沒人餵了。雖然你一點打贏他們的機會也沒有，但是你也夠小，說不定能溜進帳篷裡面從睡覺的食人妖身上偷到食物...', `MaleText_loc7`='¿Abandonas el cubil de los raptores? Me han ordenado permanecer aquí para vigilar este puesto e impedir cualquier fuga, pero... creo que entiendo por qué quieres marcharte.$b$bEstá bien. Puedes pasar, pero primero tengo una petición que hacerte.$b$bLos trols suelen llevar normalmente paquetes de comida de raptores, y hace días que no me alimentan. En una pelea no tendrías ninguna oportunidad, pero eres suficientemente pequeño como para robársela a uno de los trols mientras duermen dentro de las tiendas...' WHERE `ID`=42791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 텐지유. 잠자는 트롤에게서 음식을 훔쳐다 드리겠습니다.', `MaleText_loc4`='好吧，特基乌。我去从那些熟睡的巨魔身边帮你偷些吃的。', `MaleText_loc5`='好吧，天誅。我會從睡覺的食人妖身上幫你偷些食物。', `MaleText_loc7`='Está bien, Tenjiyu. Te traeré algo de comida de los trols durmientes.', `FemaleText_loc1`='알겠습니다, 텐지유. 잠자는 트롤에게서 음식을 훔쳐다 드리겠습니다.', `FemaleText_loc4`='好吧，特基乌。我去从那些熟睡的巨魔身边帮你偷些吃的。', `FemaleText_loc5`='好吧，天誅。我會從睡覺的食人妖身上幫你偷些食物。', `FemaleText_loc7`='Está bien, Tenjiyu. Te traeré algo de comida de los trols durmientes.' WHERE `ID`=42792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식을 가져왔습니다.', `MaleText_loc4`='我给你带回一些食物。', `MaleText_loc5`='我為你帶來了一些食物。', `MaleText_loc7`='Te he traído un poco de comida.', `FemaleText_loc1`='음식을 가져왔습니다.', `FemaleText_loc4`='我给你带回一些食物。', `FemaleText_loc5`='我為你帶來了一些食物。', `FemaleText_loc7`='Te he traído un poco de comida.' WHERE `ID`=42793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 오다니 제법이군, 오간아카. 넌 정말 재능이 넘치는 랩터야... 하지만 지금부터는 쉽지 않을 거야.$b$b저 앞의 다리에는 정찰임무를 수행하는 트롤이 있는데 주의를 끌기 힘들 거야. 하지만 저놈들의 이동 경로에 해골을 놓아둔다면 발에 걸려 다리 밑으로 떨어지게 할 수 있을지도 모르지...', `MaleText_loc4`='能走到这一步可真令人印象深刻啊，奥根阿卡。你可真是只天赋异禀的年轻迅猛龙……可最难通过的考验还在后面呢。$b$b巨魔们就在前方的桥附近巡视，他们的注意力很难被分散。可要是你能在他们的必经之路上放块头骨，也许能把他们绊个跟头……', `MaleText_loc5`='能來到這裡還挺令人驚訝的，奧根阿卡。你的確是個天賦異秉的迅猛龍...但最難的試煉還沒來呢。$b$b前面的橋有食人妖在巡邏，要分散他們的注意力是很難的。但如果你可以在他們行進的路線放一個骷髏，或許可以絆倒他們...', `MaleText_loc7`='Es bastante impresionante que hayas llegado tan lejos, Ohgan''aka. Eres una joven raptor con mucho talento... pero la prueba más dura está aún por llegar.$b$bLos trols patrullan los puentes de ahí delante, y será difícil distraerles. Sin embargo, si dejas caer una calavera en su camino, quizá puedas hacerles tropezar y caer...' WHERE `ID`=42794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<큰 랩터로부터 해골을 깔아두는 방법을 배웁니다.>', `MaleText_loc4`='<从年老迅猛龙那里学习丢落头骨的技能。>', `MaleText_loc5`='<向老迅猛龍學習怎樣放一顆骷髏。>', `MaleText_loc7`='<Aprende del raptor viejo cómo dejar caer calaveras.>', `FemaleText_loc1`='<큰 랩터로부터 해골을 깔아두는 방법을 배웁니다.>', `FemaleText_loc4`='<从年老迅猛龙那里学习丢落头骨的技能。>', `FemaleText_loc5`='<向老迅猛龍學習怎樣放一顆骷髏。>', `FemaleText_loc7`='<Aprende del raptor viejo cómo dejar caer calaveras.>' WHERE `ID`=42795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡았다!', `MaleText_loc4`='抓住你了！', `MaleText_loc5`='被騙了吧!', `MaleText_loc7`='¡Te tengo!' WHERE `ID`=42796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 지배 의식을 치를 준비가 되었습니다, 후랄라.', `MaleText_loc4`='我准备好开始意识控制仪式了，胡纳拉。', `MaleText_loc5`='我已經準備好進行精神控制的儀式了，胡瑞拉。', `MaleText_loc7`='Estoy listo para el ritual de Control mental, Hu''rala.', `FemaleText_loc1`='정신 지배 의식을 치를 준비가 되었어요, 후랄라.', `FemaleText_loc4`='我准备好开始意识控制仪式了，胡纳拉。', `FemaleText_loc5`='我已經準備好進行精神控制的儀式了，胡瑞拉。', `FemaleText_loc7`='Estoy lista para el ritual de Control mental, Hu''rala.' WHERE `ID`=42797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포박을 하수인의 발목에 걸었습니다. 잡아당겨 그를 쓰러뜨리십시오!', `MaleText_loc4`='绳子已经紧紧绕在他的脚踝上了。拉动绳子把他绊倒！', `MaleText_loc5`='他的腳踝已經被我們固定住了。快點往後拉將他絆倒!', `MaleText_loc7`='La cuerda está atada a su tobillo. ¡Tira de ella para que se tropiece!', `FemaleText_loc1`='포박을 하수인의 발목에 걸었습니다. 잡아당겨 그를 쓰러뜨리십시오!', `FemaleText_loc4`='绳子已经紧紧绕在他的脚踝上了。拉动绳子把他绊倒！', `FemaleText_loc5`='他的腳踝已經被我們固定住了。快點往後拉將他絆倒!', `FemaleText_loc7`='La cuerda está atada a su tobillo. ¡Tira de ella para que se tropiece!' WHERE `ID`=42798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기다, 못생긴 뚱땡아!', `FemaleText_loc4`='到这儿来，你这傻大个儿！', `FemaleText_loc5`='這裡，你這醜陋的鯨魚!', `FemaleText_loc7`='¡Aquí, ballena fea!' WHERE `ID`=42799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야! 이거 놔! 아니, 잠깐! 놓지 마!', `MaleText_loc4`='你！快放开我！等等……不！别放手！', `MaleText_loc5`='你!快放開我!等一下...不要!不要放開我!', `MaleText_loc7`='¡Tú! ¡Suéltame! ¡Espera! ¡No me sueltes!' WHERE `ID`=42800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 땜장이왕 멕카토크와 산악경비대 스톤그라인드와 함께 라즐로 크러쉬코그를 처치했다!', `MaleText_loc4`='$n与大工匠梅卡托克和巡山人石磨一起击败了拉奇诺·碎轮！', `MaleText_loc5`='$n在大工匠梅卡托克和巡山人石磨的協助之下，成功擊敗了拉茲羅·碾輪!', `MaleText_loc7`='¡$n ha derrotado a Razlo Prensadiente en colaboración con el manitas mayor Mekkatorque y el montaraz Triturapiedras!' WHERE `ID`=42801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승전의 영웅들이 돌아왔습니다! 찬바람 골짜기는 다시 우리 것이 되었습니다!', `MaleText_loc4`='英雄们载誉凯旋了！寒风峡谷的控制权又是我们的了！', `MaleText_loc5`='勝利的英雄們凱旋歸來了!寒風峽谷再次的歸我們所控制!', `MaleText_loc7`='¡Los héroes victoriosos han regresado! ¡El Valle del Escalofrío es nuestro de nuevo!' WHERE `ID`=42802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛!', `MaleText_loc4`='$g阁下:女士;！', `MaleText_loc5`='$g先生:女士;!', `MaleText_loc7`='¡$gSeñor:Señora;!' WHERE `ID`=42803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛! 보고드립니다!', `MaleText_loc4`='$g阁下，是阁下:女士，是女士;！', `MaleText_loc5`='$g是，長官:是，長官;!', `MaleText_loc7`='¡$gSeñor, sí, señor:Señora, sí, señora;!' WHERE `ID`=42804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 존경과 경의를!', `MaleText_loc4`='为$n欢呼三声！', `MaleText_loc5`='為$n歡呼三次!', `MaleText_loc7`='¡Tres hurras por $n!', `FemaleText_loc1`='$n에게 존경과 경의를!', `FemaleText_loc4`='为$n欢呼三声！', `FemaleText_loc5`='為$n歡呼三次!', `FemaleText_loc7`='¡Tres hurras por $n!' WHERE `ID`=42805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛! 바로 복귀하겠습니다!', `MaleText_loc4`='$g马上，阁下:马上，女士;！', `MaleText_loc5`='$g馬上，先生:馬上，女士;!', `MaleText_loc7`='¡$gAhora mismo, señor:Ahora mismo, señora;!' WHERE `ID`=42806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 승리를 쟁취했습니다!', `MaleText_loc4`='终于胜利了！', `MaleText_loc5`='最終的勝利!', `MaleText_loc7`='¡Por fin la victoria!', `FemaleText_loc1`='마침내 승리를 쟁취했어요!', `FemaleText_loc4`='终于胜利了！', `FemaleText_loc5`='最終的勝利!', `FemaleText_loc7`='¡Por fin la victoria!' WHERE `ID`=42807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시정하겠습니다!', `MaleText_loc4`='抱歉，$g阁下:女士;！', `MaleText_loc5`='很抱歉，$g長官:長官;!', `MaleText_loc7`='¡Lo siento, $gseñor:señora;!' WHERE `ID`=42808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 다행입니다! 만세!', `MaleText_loc4`='我要为此干一杯！', `MaleText_loc5`='為慶祝乾杯!', `MaleText_loc7`='¡Brindo por eso!', `FemaleText_loc1`='정말 다행이에요! 만세!', `FemaleText_loc4`='我要为此干一杯！', `FemaleText_loc5`='為慶祝乾杯!', `FemaleText_loc7`='¡Brindo por eso!' WHERE `ID`=42809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 이러지 않겠습니다!', `MaleText_loc4`='不会再有下一次，$g阁下:女士;。', `MaleText_loc5`='下次不會再犯了，$g長官:長官;。', `MaleText_loc7`='No volverá a ocurrir, $gseñor:señora;.' WHERE `ID`=42810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군님께는 비밀로 좀...', `MaleText_loc4`='请别让督军知道……', `MaleText_loc5`='請不要告訴督軍...', `MaleText_loc7`='Por favor, no se lo digas al Señor de la guerra...' WHERE `ID`=42811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위에서 만나죠. 이 괴물 녀석한테 물어볼 게 좀 있으니까요!', `FemaleText_loc4`='回到顶上找我。这个双头怪物有几个问题要回答！', `FemaleText_loc5`='跟你在上面見。這個雙頭怪胎需要回答一些問題!', `FemaleText_loc7`='Nos vemos en la cima. ¡El monstruo de dos cabezas me debe unas respuestas!' WHERE `ID`=42812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만, 그만, 항복! 전부 다 얘기할게!', `MaleText_loc4`='好吧，好吧，我放弃！我什么都告诉你！', `MaleText_loc5`='好，好，我投降!我會全跟你說!', `MaleText_loc7`='¡Está bien, me rindo! ¡Te diré todo!' WHERE `ID`=42813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무단 이탈한 그런트를 꾸짖습니다.', `MaleText_loc4`='严厉训斥一个擅离职守的兽人步兵。', `MaleText_loc5`='訓斥擅離職守的蠻兵。', `MaleText_loc7`='escupe a un bruto prófugo.', `FemaleText_loc1`='무단 이탈한 그런트를 꾸짖습니다.', `FemaleText_loc4`='严厉训斥一个擅离职守的兽人步兵。', `FemaleText_loc5`='訓斥擅離職守的蠻兵。', `FemaleText_loc7`='escupe a un bruto prófugo.' WHERE `ID`=42814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 내 상급자도 아니잖소!', `MaleText_loc4`='你又不是我老大！', `MaleText_loc5`='你又不是我的長官!', `MaleText_loc7`='¡Tú no eres mi superior!' WHERE `ID`=42815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 $c|1이;가; 싸움질이 하고 싶은가 보군.', `MaleText_loc4`='我看这个$c是想要找茬打架。', `MaleText_loc5`='我想這個$c在亂搞，想討打。', `MaleText_loc7`='Creo que $geste:esta; $c está buscando pelea.' WHERE `ID`=42816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한판 붙고 싶소?!', `MaleText_loc4`='你想试试吗？！', `MaleText_loc5`='要嚐嚐我的厲害嗎!?', `MaleText_loc7`='¡¿Quieres un poco de esto?!' WHERE `ID`=42817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 대 맞고 싶은가 보군!', `MaleText_loc4`='你想试试吗？！', `MaleText_loc5`='要嚐嚐我的厲害嗎!?', `MaleText_loc7`='¡¿Quieres un poco de esto?!' WHERE `ID`=42818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 $r 자식이 자기가 내 상급자인 줄 아는군.', `MaleText_loc4`='那个愚蠢的$r认为$g他是:她是;我的头儿。', `MaleText_loc5`='笨蛋$r還以為$g他:她;是我老大。', `MaleText_loc7`='$r idiota cree que es mi jefe.' WHERE `ID`=42819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C, 원하는 대로 비 오는 날 먼지 나게 두들겨 주지.', `MaleText_loc4`='$C，你刚为自己争取到一顿海扁。', `MaleText_loc5`='$C，你為你自己討了一頓打。', `MaleText_loc7`='$C, acabas de ganarte una paliza.' WHERE `ID`=42820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못했소... 바로 복귀하겠소!', `MaleText_loc4`='我错了——我马上回到岗位上去！', `MaleText_loc5`='對不起...我會回到我的崗位!', `MaleText_loc7`='Lo siento, ¡regresaré a mi puesto!' WHERE `ID`=42821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 대든 게 잘못이지...', `MaleText_loc4`='够了！我不该质疑你的命令……', `MaleText_loc5`='夠了!我應該要質疑你的命令才對...', `MaleText_loc7`='¡Basta! No debí cuestionar tus órdenes...' WHERE `ID`=42822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 몇 주간 벌인 싸움 중에 제일 대단했소! 이제는 우리 적과 싸우겠소.', `MaleText_loc4`='那是我几个星期以来最痛快的一次吵架了！我要把剩下的留给我们的敌人。', `MaleText_loc5`='這幾個禮拜以來就屬這一架打得最過癮。其他的就留給我們的敵人吧。', `MaleText_loc7`='¡Es la mejor pelea que he tenido desde hace semanas! Reservaré lo demás para nuestros enemigos.' WHERE `ID`=42823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹이 꽤 맵군! 고원에서 당신과 함께 싸웠으면 좋겠소.', `MaleText_loc4`='你可真能打！希望你能和我一起前往高地。', `MaleText_loc5`='你是個厲害的戰士!我希望你能在高地與我並肩作戰。', `MaleText_loc7`='¡Has luchado bien! ¡Espero tenerte a mi lado en las tierras altas!' WHERE `ID`=42824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 산에 있는 검은바위 동굴은 79에서 81 레벨의 플레이어가 공략할 수 있는 던전으로 지금 시험해볼 수 있습니다. 던전 안으로 순간이동하기 전에 파티를 맺은 상태여야 합니다. 만남의 돌은 아직 사용할 수 없습니다. 돌의 전당에서 나오려면, 던전 안에 있는 입구로 빠져나오면 됩니다. 그러면 바로 여기로 돌아오게 되지요. 죽어서 영혼이 빠져나갔다면 다시 NPC와 대화하여 순간이동해야 합니다.', `MaleText_loc4`='你现在可以参与黑石岩窟的测试了，这是位于黑石山的一座79-81级地下城。请在传送至地下城之前组满队伍。集合石目前对该地下城不可用。

若要离开岩石大厅，只需从位于地下城内的普通出口离开即可，你将被自动传送至达拉然。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。', `MaleText_loc5`='黑石洞穴現在已可進行測試。黑石洞穴坐落在黑石山，是一座等級79-81的地城。本地城的集合石功能尚未建構完成，因此請先組好完整隊伍再傳送進地城。

如要離開石之大廳，請從地城內正常的出口離開，你就會被傳送到達拉然。倘若不幸死亡並已釋放靈魂，你應當經由這位NPC來傳送回去。', `MaleText_loc7`='Las Cavernas Roca Negra, una mazmorra de nivel 79-81 en la Montaña Roca Negra, ya está disponible para pruebas. Antes de teletransportarte a la mazmorra, asegúrate de que el grupo está formado. Las rocas de encuentro para esta mazmorra todavía no están disponibles.

Para abandonar las Cámaras de Piedra, simplemente sal por la salida normal dentro de la mazmorra y serás teletransportado a Dalaran. Si mueres y liberas espíritu, puedes teletransportarte de nuevo con este PNJ.' WHERE `ID`=42825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 검은바위 동굴로 순간이동시켜 주십시오!', `MaleText_loc4`='我已组好队伍，准备好被传送到黑石岩窟了！', `MaleText_loc5`='我已經在我的隊伍裡，準備好可以傳送到黑石洞穴了!', `MaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cavernas Roca Negra!', `FemaleText_loc1`='저와 파티원 모두 준비되었습니다. 검은바위 동굴로 순간이동시켜 주십시오!', `FemaleText_loc4`='我已组好队伍，准备好被传送到黑石岩窟了！', `FemaleText_loc5`='我已經在我的隊伍裡，準備好可以傳送到黑石洞穴了!', `FemaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme a las Cavernas Roca Negra!' WHERE `ID`=42826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 검은바위 동굴로 다시 보내 주십시오!', `MaleText_loc4`='送我回黑石岩窟！', `MaleText_loc5`='將我帶回黑石洞穴!', `MaleText_loc7`='¡Llévame de vuelta a las Cavernas Roca Negra!', `FemaleText_loc1`='절 검은바위 동굴로 다시 보내 주세요!', `FemaleText_loc4`='送我回黑石岩窟！', `FemaleText_loc5`='將我帶回黑石洞穴!', `FemaleText_loc7`='¡Llévame de vuelta a las Cavernas Roca Negra!' WHERE `ID`=42827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무단 이탈한 그런트가 주사위를 던집니다.', `MaleText_loc4`='擅离职守的兽人步兵投了投骰子。', `MaleText_loc5`='擅離職守的蠻兵在扔骰子。', `MaleText_loc7`='El bruto prófugo echa unos dados.' WHERE `ID`=42828;
