UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕카토크 미사일!', `MaleText_loc4`='梅卡托克——导弹！', `MaleText_loc5`='梅卡托克─飛彈!', `MaleText_loc7`='¡Misiles Mekkatorque!' WHERE `ID`=42833;
