UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이걸 여기에 버리고 갔지? 우아아아악...', `MaleText_loc4`='谁把它放在这儿的，伙计？哇啊……', `MaleText_loc5`='誰把東西丟在這裡，老兄?嗚啊...', `MaleText_loc7`='¿Quién ha deja''o eso aquí, colega? Aaaaah...', `FemaleText_loc1`='누가 이걸 여기에 버리고 갔지? 우아아아악...', `FemaleText_loc4`='谁把它放在这儿的，伙计？哇啊……', `FemaleText_loc5`='誰把東西丟在這裡，老兄?嗚啊...', `FemaleText_loc7`='¿Quién ha deja''o eso aquí, colega? Aaaaah...' WHERE `ID`=42835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게든... 균형을... 잡아야... 해...', `MaleText_loc4`='我……我失去……平衡了……老兄……', `MaleText_loc5`='我要...保持...平衡...老兄...', `MaleText_loc7`='Debo... recuperar... el equilibrio... colega...', `FemaleText_loc1`='어떻게든... 균형을... 잡아야... 해...', `FemaleText_loc4`='我……我失去……平衡了……老兄……', `FemaleText_loc5`='我要...保持...平衡...老兄...', `FemaleText_loc7`='Debo... recuperar... el equilibrio... colega...' WHERE `ID`=42836;
