UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 거의 넘어질 뻔했잖아!', `MaleText_loc4`='哎呦，伙计！我被绊倒了！', `MaleText_loc5`='哇，老兄!我被絆倒了!', `MaleText_loc7`='¡Ay, colega! ¡Estoy alucinando!', `FemaleText_loc1`='이런! 거의 넘어질 뻔했잖아!', `FemaleText_loc4`='哎呦，伙计！我被绊倒了！', `FemaleText_loc5`='哇，老兄!我被絆倒了!', `FemaleText_loc7`='¡Ay, colega! ¡Estoy alucinando!' WHERE `ID`=42838;
