UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딜 가는 건가, 오간아카?', `MaleText_loc4`='你要去哪儿，小家伙？', `MaleText_loc5`='要去哪裡呀，小傢伙?', `MaleText_loc7`='¿Adónde vas, pequeña?' WHERE `ID`=42840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄구룹에서 도망치려고?', `MaleText_loc4`='你想要逃出祖尔格拉布？', `MaleText_loc5`='你想要逃出祖爾格拉布?', `MaleText_loc7`='¿Intentas escapar de Zul''Gurub?' WHERE `ID`=42841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 진도가 있는 한 그 누구도 줄구룹을 빠져나갈 순 없다!', `MaleText_loc4`='谁也别想从祖尔格拉布逃出去！只要金度在，就别想！', `MaleText_loc5`='沒人可以在金度的統治下逃出祖爾格拉布!', `MaleText_loc7`='¡NADIE escapa de Zul''Gurub! ¡No mientras Jin''do eh''té al mando!' WHERE `ID`=42842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 널 죽이지 않는 걸 행운으로 생각해라... 네가 해줘야 할 더 큰일이 있기 때문이지.', `MaleText_loc4`='你该庆幸我现在不会马上杀了你……不过我为你准备了更重要的任务。', `MaleText_loc5`='你很幸運，我現在先不殺你...但是我有更重要的計畫要用到你。', `MaleText_loc7`='Tienes sueh''te de que no te mate... Tengo planes más impoh''tantes pa'' ti.' WHERE `ID`=42843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 알겠지만... 학카르를 소환하려면 만도키르가 필요하다. 그리고 만도키르에겐 네가 필요하지.', `MaleText_loc4`='你看……要想召唤哈卡，我就需要曼多基尔。而曼多基尔，他需要你。', `MaleText_loc5`='你看...要召喚哈卡，我需要曼多基爾。而曼多基爾，他需要你。', `MaleText_loc7`='Verás... Para invocar a Hakkar necesito a Mandokir. Y Mandokir te necesita a ti.' WHERE `ID`=42844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군, 오간아카.', `MaleText_loc4`='你好啊，奥根阿卡。', `MaleText_loc5`='嗨，奧根阿卡。', `MaleText_loc7`='Hola, Ohgan''aka.' WHERE `ID`=42845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혈군주시여, 저 랩터를 기를 생각이십니까?', `MaleText_loc4`='血领主，你要更用心地照看你的财产吗？', `MaleText_loc5`='血領主，你是不是該好好照顧一下你的東西?', `MaleText_loc7`='Señor sangriento, ¿cuidarás mejor de tus posesiones?' WHERE `ID`=42846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하지, 진도. 오간아카는 특별히 더 신경 써서 돌볼 생각이다.', `MaleText_loc4`='喔没错，金度。我们会非常小心地照料奥根阿卡。', `MaleText_loc5`='喔，對啊，金度。我們會『好好』照顧奧根阿卡。', `MaleText_loc7`='Oh, sí, Jin''do. Cuidaremos MUY bien de Ohgan''aka.' WHERE `ID`=42847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 우리도 지었지. 이 녀석이 다시는 도망치지 못하도록 조련할 방법은 얼마든지 있다.', `MaleText_loc4`='我造了个新笼子，而且我们有许多种手段来……教她打消逃跑的念头。', `MaleText_loc5`='我做了個新的籠子，而且我們有很多方式可以...教她不要再逃了。', `MaleText_loc7`='Hemos hecho conh''truir una jaula nueva y conocemos muchas formas de... convenceh''la de que no vuelva a escapar.' WHERE `ID`=42848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 아주 좋습니다. 그리고 너... 그래, 바로 너... 정신 지배 주문 속에서 간섭하는 녀석. 내가 널 못 볼 거라 생각했다면 오산이지.', `MaleText_loc4`='很好，很好。还有你……对，就是你……在意识控制法术中忙活的虫子。别以为金度看不见你。', `MaleText_loc5`='很好，很好。還有你...對，就是你...用精神控制法術在搞鬼的臭蟲子。不要以為金度看不見你。', `MaleText_loc7`='Bien, bien. Y tú... sí, tú... El gusano entrometido que hay dentro del hechizo de control mental. No creas que Jin''do no puede veh''te.' WHERE `ID`=42849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제라도 이곳으로 돌아올 용기가 생긴다면 마음의 준비를 하는 게 좋을 거다. 널 위해 깜짝 선물을 준비했거든...', `MaleText_loc4`='等你有勇气回到这里时，可一定要做好准备。因为金度为你准备了一份惊喜……', `MaleText_loc5`='等你有『膽子』回來這裡的時候，你可得做好準備啊。因為金度有個驚喜要給你...', `MaleText_loc7`='Cuando consigas reunir el VALOR pa'' volver aquí, será mejor que te prepares. Porque Jin''do tiene una sorpresita pa'' ti...' WHERE `ID`=42850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카!$B$B대족장님께서는 내게 황혼의 고원을 공격할 최고의 정예 부대를 모으라고 명령하셨소.$B$B당신도 꽤 노련한 $c|1으로;로; 보이긴 하오만, 우리에겐 좀 더...뭐랄까, 전투에 단련된 병사가 필요하오. 누가 알겠소, 언젠간 우리 둘이 나란히 함께 싸우게 될지! 그때까진 훈련을 게을리하지 마시오.', `MaleText_loc4`='你好，朋友！$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B你看起来底子不错，$c，可我们需要的士兵得更加……久经沙场一些。也许有一天你和我能并肩作战。在那以前，继续加紧训练吧！', `MaleText_loc5`='(獸人語)你好，朋友!$B$B大酋長下令動員他麾下最資深的士兵，準備對暮光高地發動攻擊。$B$B你看起來是蠻硬朗的，$c，但我們需要的是更有...實戰經驗的。說不定哪天我們會有機會一起並肩作戰。至於現在，還是繼續你的訓練吧!', `MaleText_loc7`='¡Throm''ka, camarada!$B$BEl Jefe de Guerra me ha ordenado que reúna a los mejores veteranos para el asalto a las Tierras Altas Crepusculares.$B$BTú pareces ser $gun:una; $c resistente, pero necesitamos soldados más... curtidos en la batalla. Quizá algún día tú y yo luchemos hombro con hombro. Mientras tanto, ¡continúa entrenando!' WHERE `ID`=42851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카! 노스렌드 전투에서 활약한 정예 부대원을 만나게 돼서 반갑소.$B$B대족장님께서는 내게 황혼의 고원을 공격할 최고의 정예 부대를 모으라고 명령하셨소.$B$B<당신을 위아래로 훑어보는 장군 크로그>$B$B당신이 우리에게 도움이 될지도 모르겠군. 오그리마에 계신 대족장님께 가서 뭔가 맡기실 일이 없는지 여쭤보시오.', `MaleText_loc4`='你好，朋友！很高兴见到诺森德战役的老战友。$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B<酋长把你上下打量了一番。>$B$B我们也许需要你的帮助。去奥格瑞玛的酋长那里，看看他有没有任务交给你。', `MaleText_loc5`='(獸人語)你好，朋友!很高興見到北裂境戰役的資深士兵。$B$B大酋長下令動員他麾下最英勇的士兵，準備對暮光高地發動攻擊。$B$B<督軍克羅格上下打量著你。>$B$B我們說不定會需要你的協助。到奧格瑪去找大酋長報到，看看他有沒有需要你效力的地方。', `MaleText_loc7`='¡Throm''ka, camarada! Me alegro de ver a un camarada veterano de la campaña de Rasganorte.$B$BEl Jefe de Guerra me ha ordenado que reúna a los mejores veteranos para el asalto a las Tierras Altas Crepusculares.$B$B<El señor de la guerra Krogg te mira de arriba abajo.>$B$BQuizá necesitemos tu ayuda. Ve a hablar con el Jefe de Guerra en Orgrimmar para ver si tiene alguna tarea para ti.' WHERE `ID`=42852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\inv_misc_net_01.blp:32|t$b$b그물 물어뜯기 능력을 사용해 구루바시 그물을 뚫고 나가십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b用把网罩一起吃掉的技能咬穿古拉巴什的网！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b使用「破網而出」技能來咬破古拉巴什網子!', `MaleText_loc7`='|TInterfaceIconsinv_misc_net_01.blp:32|t$b$b¡Utiliza la facultad Morder red para atravesar las redes Gurubashi!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b그물 물어뜯기 능력을 사용해 구루바시 그물을 뚫고 나가십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b用把网罩一起吃掉的技能咬穿古拉巴什的网！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_net_01.blp:32|t$b$b使用「破網而出」技能來咬破古拉巴什網子!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_net_01.blp:32|t$b$b¡Utiliza la facultad Morder red para atravesar las redes Gurubashi!' WHERE `ID`=42853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠든 구루바시 병사에게서 음식을 훔치십시오!', `MaleText_loc4`='从熟睡的古拉巴什士兵身上偷取食物！', `MaleText_loc5`='從睡覺的古拉巴什士兵身上偷走食物!', `MaleText_loc7`='¡Roba comida de los soldados Gurubashi dormidos!', `FemaleText_loc1`='잠든 구루바시 병사에게서 음식을 훔치십시오!', `FemaleText_loc4`='从熟睡的古拉巴什士兵身上偷取食物！', `FemaleText_loc5`='從睡覺的古拉巴什士兵身上偷走食物!', `FemaleText_loc7`='¡Roba comida de los soldados Gurubashi dormidos!' WHERE `ID`=42854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\spell_fire_fire.blp:32|t$b$b화로에서 불타는 가지를 획득하고 불 붙이기 능력을 사용해 줄구룹 티키를 불태우십시오!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b从火盆里取出燃烧的树枝，然后用点火技能烧毁祖尔格拉布神像！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b從火盆拿起燃燒的嫩枝，然後使用「點火」來燒掉祖爾格拉布提基!', `MaleText_loc7`='|TInterfaceIconsspell_fire_fire.blp:32|t$b$b¡Recoge ramitas ardientes de los blandones y utiliza Encender fuego para quemar tikis de Zul''Gurub!', `FemaleText_loc1`='|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b화로에서 불타는 가지를 획득하고 불 붙이기 능력을 사용해 줄구룹 티키를 불태우십시오!', `FemaleText_loc4`='|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b从火盆里取出燃烧的树枝，然后用点火技能烧毁祖尔格拉布神像！', `FemaleText_loc5`='|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b從火盆拿起燃燒的嫩枝，然後使用「點火」來燒掉祖爾格拉布提基!', `FemaleText_loc7`='|TInterfaceIconsspell_fire_fire.blp:32|t$b$b¡Recoge ramitas ardientes de los blandones y utiliza Encender fuego para quemar tikis de Zul''Gurub!' WHERE `ID`=42855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b해골더미에서 구루바시 해골을 집어 들고 트롤의 이동 경로에 내려놓으십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b从巫毒堆里取出古拉巴什徽记，然后丢在巨魔的必经之路上！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b從顱骨堆拿起古拉巴什顱骨，然後將它們放在食人妖經過的路上!', `MaleText_loc7`='|TInterfaceIconsinv_misc_bone_orcskull_01.blp:32|t$b$b¡Recoge calaveras Gurubashi de los montones de calaveras y colócalas en los caminos de los trols!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b해골더미에서 구루바시 해골을 집어 들고 트롤의 이동 경로에 내려놓으십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b从巫毒堆里取出古拉巴什徽记，然后丢在巨魔的必经之路上！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b從顱骨堆拿起古拉巴什顱骨，然後將它們放在食人妖經過的路上!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_bone_orcskull_01.blp:32|t$b$b¡Recoge calaveras Gurubashi de los montones de calaveras y colócalas en los caminos de los trols!' WHERE `ID`=42856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 마을에서는 많은 문제에 휘말리게 될 수 있소.$B$B골치 아프지.', `MaleText_loc4`='一位士兵在这样的城镇里能惹上许多麻烦。$B$B许多麻烦。', `MaleText_loc5`='士兵在這樣的小鎮裡，是有可能會捲入大麻煩的。$B$B很大的麻煩。', `MaleText_loc7`='Un soldado podría meterse en un montón de problemas en una ciudad como esta.$B$BEn un montón de problemas.' WHERE `ID`=42857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군.$b$b감사의 표시로 저 앞에 있는 트롤의 주위를 분산시키는 법을 가르쳐주지.', `MaleText_loc4`='谢谢你。$b$b作为回报，我会教你如何分散前面那群巨魔的注意力。', `MaleText_loc5`='謝謝你。$b$b為了回報你，我要教你怎樣吸引前面那些食人妖的注意。', `MaleText_loc7`='Gracias.$B$BA cambio te enseñaré cómo distraer a los trols que encontrarás más adelante.' WHERE `ID`=42858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티키에 불이 붙었다! 어서 꺼!', `MaleText_loc4`='神像！快把火扑灭！', `MaleText_loc5`='提基!把火撲滅!', `MaleText_loc7`='¡El Tiki! ¡Apágalo!', `FemaleText_loc1`='티키에 불이 붙었다! 어서 꺼!', `FemaleText_loc4`='神像！快把火扑灭！', `FemaleText_loc5`='提基!把火撲滅!', `FemaleText_loc7`='¡El Tiki! ¡Apágalo!' WHERE `ID`=42859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이야! 어서 서두르라고!', `MaleText_loc4`='着火了！动作快伙计！', `MaleText_loc5`='起火了!動作快，老兄!', `MaleText_loc7`='¡Un incendio! ¡Corre, colega!', `FemaleText_loc1`='불이야! 어서 서두르라고!', `FemaleText_loc4`='着火了！动作快伙计！', `FemaleText_loc5`='起火了!動作快，老兄!', `FemaleText_loc7`='¡Un incendio! ¡Corre, colega!' WHERE `ID`=42860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 우리 티키에 불을 붙였다!', `MaleText_loc4`='有人在烧我的神像！', `MaleText_loc5`='有人放火燒了我的提基!', `MaleText_loc7`='¡Alguien le ha pega''o fuego a mi Tiki!', `FemaleText_loc1`='누군가 우리 티키에 불을 붙였다!', `FemaleText_loc4`='有人在烧我的神像！', `FemaleText_loc5`='有人放火燒了我的提基!', `FemaleText_loc7`='¡Alguien le ha pega''o fuego a mi Tiki!' WHERE `ID`=42861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 어서 빨리 이쪽으로!', `MaleText_loc4`='到这儿来，兄弟们，赶快！', `MaleText_loc5`='過來這裡，兄弟，快點!', `MaleText_loc7`='¡Venid aquí, he''manos, rápido!', `FemaleText_loc1`='형제들이여, 어서 빨리 이쪽으로!', `FemaleText_loc4`='到这儿来，兄弟们，赶快！', `FemaleText_loc5`='過來這裡，兄弟，快點!', `FemaleText_loc7`='¡Venid aquí, he''manos, rápido!' WHERE `ID`=42862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈출하겠다고? 좋아. 하지만 그전에 알아야 할 것들이 있어.$b$b우선 트롤에게 걸리지 말아야 해. 널 죽이진 않겠지만, 다시 이곳으로 던져 넣을 테니까.$b$b둘째로는 눈에 띄는 모든 랩터들에게 말을 걸어. 너에게 새로운 능력을 가르쳐주고 네 진행상황을 기억해 줄구룹을 더 쉽게 빠져나갈 수 있게 해 줄 거야.$b$b이미 질주 능력을 갖추고 있으니 위험한 순간에서 벗어날 때 사용하면 되겠군.$b$b아, 그리고 물에 가까이 다가가지 마.$b$b행운을 빈다!', `MaleText_loc4`='你想逃走？没问题，可你必须得先了解一些事情。$b$b离那些巨魔远点儿。他们不会杀你，可他们会困住你然后把你带回来。$b$b和你所见到的每只迅猛龙都打个招呼。它们不仅能教你新的技能，还会帮你记住你的进度，让你能更加容易地逃离祖尔格拉布。$b$b你已经学会了急奔技能——用它来脱离险境吧。$b$b喔……还要注意别下水。$b$b祝你好运！', `MaleText_loc5`='你想要逃跑嗎?這可以接受，但你必須先瞭解一些事。$b$b離食人妖遠一點。他們不會殺了你，但他們會把你抓起來後帶回這。$b$b跟每一隻你看到的迅猛龍說話，它們不單能教你新的技能，還可以幫助你記錄你的進度，讓你在祖爾格拉布的歷險更加順暢。$b$b你已經學會突進這個技能了─使用它來逃離危險。$b$b噢...還有別離有水的地方太近。$b$b祝你好運!', `MaleText_loc7`='¿Quieres escapar? Está bien, pero primero tienes que saber unas cuantas cosas.$b$bNo te acerques a los trols. No te matarán, pero te atraparán y te traerán aquí de nuevo.$b$bHabla con todos los raptores que veas. No solo pueden enseñarte nuevas habilidades, sino que te ayudarán a recordar tu progreso y harán que el camino de salida de Zul''Gurub sea mucho más sencillo.$b$bYa cuentas con la habilidad Carrerilla, úsala para salir de aprietos.$b$bOh... y no te acerques al agua.$b$b¡Buena suerte!' WHERE `ID`=42863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF768EBD5년 전, 죽음의 폐광의 한가운데...|r |Tinterface\\QuestFrame\\UI-QUESTLOG-BOOKICON.BLP:32|t', `MaleText_loc4`='|cFF768EBD五年前，在死亡矿井的中心……|r |TInterface\\QuestFrame\\UI-QUESTLOG-BOOKICON.BLP:32|t', `MaleText_loc5`='|cFF768EBD五年前，在死亡礦坑的深處...|r |TInterface\\QuestFrame\\UI-QUESTLOG-BOOKICON.BLP:32|t', `MaleText_loc7`='|cFF768EBDHace cinco años, en el corazón de las Minas de la Muerte...|r |TInterface\QuestFrame\UI-QUESTLOG-BOOKICON.BLP:32|t' WHERE `ID`=42864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아, 내가 하는 일을 하고 싶진 않을 걸, 친구.$B$B썩 꺼지시오!', `MaleText_loc4`='呀，你对我这儿的东西都没兴趣，$g小男孩:小女孩;。$B$B快走开！', `MaleText_loc5`='呀啊，你不會想碰到我在解決的那些東西的，$g小子:小妞;。$B$B快滾吧你!', `MaleText_loc7`='Aaarrrr, no quieres tener nada que ver con lo que me traigo entre manos, $ghijo:señorita;.$B$B¡Largo de aquí!' WHERE `ID`=42865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호! 호호호.$B$B요호호, 동점이군.$B$B황혼의 고원으로 가는 비행편은 현재 점검 중이오. 그동안 내가 당신을 눈 깜짝할 사이에 데려다 드리지.$B$B날 믿을 수 있소, $c?', `MaleText_loc4`='喔，嚯！喔嚯嚯。$B$B呦嚯嚯，扯平。$B$B去往暮光高地的航班正在准备中。与此同时，我愿意送你去——全速直达。$B$B你信任我吗，$c？', `MaleText_loc5`='喔呴!喔呴呴。$B$B甚至，呦呴呴。$B$B飛往暮光高地的事件正在製作中。在此同時，我就先帶你過去。馬上就到。$B$B你相信我嗎，$c?', `MaleText_loc7`='¡Oh, jo! Oh, jo, jo.$B$BY más, yo, jo, jo.$B$BEstamos trabajando en el vuelo al evento de las Tierras Crepusculares. Mientras tanto, yo te enviaré en menos de lo que canta un gallo.$B$B¿Confías en mí, $c?' WHERE `ID`=42866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 저를 이동시켜 주십시오!', `MaleText_loc4`='嗯，送我去吧！', `MaleText_loc5`='對，傳送我!', `MaleText_loc7`='¡Sí, teletranspórtame!', `FemaleText_loc1`='네, 저를 이동시켜 주십시오!', `FemaleText_loc4`='嗯，送我去吧！', `FemaleText_loc5`='對，傳送我!', `FemaleText_loc7`='¡Sí, teletranspórtame!' WHERE `ID`=42867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 내 지시에 따라 여기로 이주했네. 헬스크림의 손아귀에 떨어진 오그리마는 우리의 집이 아니야.', `MaleText_loc4`='是我带领暗矛部族来到这儿。但现在奥格瑞玛已经不再是我们的家了。', `MaleText_loc5`='暗矛部族會在這是因為我帶領他們來到這。奧格瑪只要一天在地獄吼手裡，這裡就不會是我們的家。', `MaleText_loc7`='Los Lanza Negra están aquí porque yo los traje. Orgrimmar no será hogar mientras esté en manos de Grito Infernal.' WHERE `ID`=42869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 내가 화를 못 이겨 경솔하게 행동한 건 아닌지 걱정스럽네. 스랄은 지금의 호드를 만드는 데 모든 것을 바쳤지. 충동적으로 호드를 떠나고 싶지는 않네. 깊이 생각해 볼 일이야.', `MaleText_loc4`='不过，我也在担心会过于意气用事。萨尔竭尽心力，才让部落成为今天这个样子，我不想因为一时冲动就离开。我需要再好好想想。', `MaleText_loc5`='雖然如此，我擔心我的脾氣讓我過於魯莽了。索爾奉獻了一切打造了現在的部落，我並不想因為一時衝動就永遠離開。我需要更加深思熟慮。', `MaleText_loc7`='Aunque temo que dejé que mi carácter me condicione. Thrall dedicó su vida a hacer la Horda lo que es, así que no la abandonaré por un capricho. Hay que reflexionar sobre esto.' WHERE `ID`=42870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진. 참으로 반갑네, 형제여.', `MaleText_loc4`='沃金。很高兴看到你，兄弟。', `MaleText_loc5`='沃金，很高興見到你，兄弟。', `MaleText_loc7`='Vol''jin. Qué bueno verte, hermano.' WHERE `ID`=42871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주니가 마지막 인사를 하러 왔습니다.', `MaleText_loc4`='这是老祖尼最后的请求。', `MaleText_loc5`='老朱尼最後的禮物。', `MaleText_loc7`='Un último favor del viejo Zuni.' WHERE `ID`=42872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 훌륭한 일들을 해낼 겁니다. 절 잊지 마세요.', `MaleText_loc4`='你会变成了不起的人，别忘了我，兄弟。', `MaleText_loc5`='你會有很大的成就。別忘了我，老兄。', `MaleText_loc7`='Vas a ser grande. No me olvides, hombre.' WHERE `ID`=42873;
