UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 여기서 살아나가지 못한다!', `MaleText_loc4`='谁也别想活着离开！', `MaleText_loc5`='沒人可以活著出去!', `MaleText_loc7`='¡Nadie sale de aquí con vida!', `FemaleText_loc1`='누구도 여기서 살아나가지 못한다!', `FemaleText_loc4`='谁也别想活着离开！', `FemaleText_loc5`='沒人可以活著出去!', `FemaleText_loc7`='¡Nadie sale de aquí con vida!' WHERE `ID`=42882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 안 좋은 시간에 안 좋은 장소에 온 거야!', `MaleText_loc4`='你在错误的时间来到了错误的地点，$g小伙子:小姑娘;！', `MaleText_loc5`='你來錯時間、來錯地方啦，$g老兄:小妞;!', `MaleText_loc7`='¡Estás en el lugar equivocado en el momento equivocado, $gamigo:amiga;!', `FemaleText_loc1`='넌 안 좋은 시간에 안 좋은 장소에 온 거야!', `FemaleText_loc4`='你在错误的时间来到了错误的地点，$g小伙子:小姑娘;！', `FemaleText_loc5`='你來錯時間、來錯地方啦，$g老兄:小妞;!', `FemaleText_loc7`='¡Estás en el lugar equivocado en el momento equivocado, $gamigo:amiga;!' WHERE `ID`=42883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈을 내놓든지 아니면 목숨을 내놔라!', `MaleText_loc4`='要钱还是要命！', `MaleText_loc5`='給我錢，或給我你的命!', `MaleText_loc7`='¡El dinero o la vida!', `FemaleText_loc1`='돈을 내놓든지 아니면 목숨을 내놔라!', `FemaleText_loc4`='要钱还是要命！', `FemaleText_loc5`='給我錢，或給我你的命!', `FemaleText_loc7`='¡El dinero o la vida!' WHERE `ID`=42884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명이 널 내게 데려왔구나!', `MaleText_loc4`='是命运把你带到我的面前！', `MaleText_loc5`='命運將你帶到我面前!', `MaleText_loc7`='¡El destino te ha traído a mí!', `FemaleText_loc1`='운명이 널 내게 데려왔구나!', `FemaleText_loc4`='是命运把你带到我的面前！', `FemaleText_loc5`='命運將你帶到我面前!', `FemaleText_loc7`='¡El destino te ha traído a mí!' WHERE `ID`=42885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 거짓말이 아니다. 놀드랏실이 위험해. 서둘러 하이잘 방어 준비를 해야겠다.', `MaleText_loc4`='她没撒谎。诺达希尔处于险境之中。我必须加紧准备海加尔的防御。', `MaleText_loc5`='她沒有說謊。諾達希爾面臨著危險。我必須儘快為海加爾山的防禦做準備。', `MaleText_loc7`='No miente. Nordrassil está en peligro. Debo apurarme y preparar la defensa de Hyjal.' WHERE `ID`=42886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대정령의 뿔피리를 불어 소고스의 귀환을 막는 임무는 그대에게 맡기겠다.', `MaleText_loc4`='这次将由你来使用远古号角，阻止索苟斯的回归。', `MaleText_loc5`='使用遠古號角阻止索苟斯的歸來將會是你的工作。', `MaleText_loc7`='Tú tendrás que usar el Cuerno de los Ancestros y detener el regreso de Soggoth.' WHERE `ID`=42887;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 말퓨리온 스톰레이지군. 네놈을 좀 더 잡아두길 바랐는데. 내 동맹들이 공격하는 동안 네놈을 하이잘에서 멀리 떨어뜨려 놓는 게 내 목표였다. 내 계획이 성공한 것 같구나.', `FemaleText_loc4`='啊……玛法里奥·怒风。我原本希望能再把你多拖住一会儿。我的目标是要保证在我的盟友出击时，让你远离海加尔。看来我已经成功了。', `FemaleText_loc5`='啊... 瑪法里恩·怒風。雖說我本來是希望還可以再耽擱你更久一點的，但無所謂，我的目的只是要在我的盟軍發動攻擊的時候，把你從海加爾山引開。而看來，我已經成功了。', `FemaleText_loc7`='Ah... Malfurion Tempestira. Había esperado tenerte ocupado un poco más de tiempo. Mi objetivo era mantenerte alejado de Hyjal mientras mis aliados atacaban. Parece ser que he tenido éxito.' WHERE `ID`=42888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이미 내가 이긴 것 같으니 네놈과 싸울 필요가 없구나. 네놈이 여기 어둠해안 공격을 막아내면서 하이잘도 구할 수는 없으니 말이다!', `FemaleText_loc4`='我根本不用和你作战，因为我显然已经赢了。你不能在阻止我们攻击黑海岸的同时，还能救得了海加尔山！', `FemaleText_loc5`='我不必跟你戰鬥，因為看來我已經贏了。你無法同時又要阻止我們對黑海岸的攻擊，又想要拯救海加爾山!', `FemaleText_loc7`='No necesito luchar contra ti, porque creo que ya he ganado. ¡No puedes detener nuestro ataque contra la Costa Oscura y salvar Hyjal al mismo tiempo!' WHERE `ID`=42889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 생명체여, 너는 이 땅에 속하지 않았다! 자연의 분노를 느껴보아라!', `MaleText_loc4`='你不属于这个世界，邪恶的生物！忍受自然的愤怒吧！', `MaleText_loc5`='邪惡的魔物，你不屬於這個世界!品嚐自然之怒的厲害!', `MaleText_loc7`='¡No perteneces a este mundo, criatura repugnante! ¡Sufre la ira de la naturaleza!' WHERE `ID`=42890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례한 필멸의 존재 같으니, 네놈의 영혼을 삼켜버리겠다!', `MaleText_loc4`='我要吞噬你们的灵魂，无礼的凡人！', `MaleText_loc5`='傲慢的凡人，我要吞噬掉你們的靈魂!', `MaleText_loc7`='¡Devoraré sus almas, insolentes mortales!' WHERE `ID`=42891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 오그리마로 보내주십시오.', `MaleText_loc4`='送我去奥格瑞玛。', `MaleText_loc5`='帶我到奧格瑪。', `MaleText_loc7`='Envíame a Orgrimmar.', `FemaleText_loc1`='절 오그리마로 보내주세요.', `FemaleText_loc4`='送我去奥格瑞玛。', `FemaleText_loc5`='帶我到奧格瑪。', `FemaleText_loc7`='Envíame a Orgrimmar.' WHERE `ID`=42892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났네. 이제 멀고어는 그림토템 부족의 증오에 시달리지 않을 게야.', `MaleText_loc4`='我们在这儿的任务完成了。莫高雷不会再受到恐怖图腾仇恨的侵扰。', `MaleText_loc5`='這裡和平了。莫高雷永遠不會再受到恐怖圖騰的荼毒了。', `MaleText_loc7`='Aquí hemos terminado. Mulgore ya no sufrirá más el odio de los Tótem Siniestro.' WHERE `ID`=42893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프에서 다시 보세.', `MaleText_loc4`='我会在雷霆崖上与你再次会面。', `MaleText_loc5`='我回雷霆崖等你。', `MaleText_loc7`='Me reuniré contigo en Cima del Trueno.' WHERE `ID`=42894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<큰 랩터에게서 불 붙이기 능력을 배웁니다.>', `MaleText_loc4`='<从年老迅猛龙那里学习点火的技能。>', `MaleText_loc5`='<向老迅猛龍學習怎樣點火。>', `MaleText_loc7`='<Aprende del raptor viejo cómo encender fuegos.>', `FemaleText_loc1`='<큰 랩터에게서 불 붙이기 능력을 배웁니다.>', `FemaleText_loc4`='<从年老迅猛龙那里学习点火的技能。>', `FemaleText_loc5`='<向老迅猛龍學習怎樣點火。>', `FemaleText_loc7`='<Aprende del raptor viejo cómo encender fuegos.>' WHERE `ID`=42895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 필요한 거라도 있소?', `MaleText_loc4`='你需要什么吗？', `MaleText_loc5`='你需要什麼嗎?', `MaleText_loc7`='¿Hay algo que necesites?' WHERE `ID`=42896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검이 모쉬오그 노획물 안으로 들어갔습니다. 억지로라도 여십시오!', `MaleText_loc4`='刀刃插进了莫什奥格的馈赠，把它打开！', `MaleText_loc5`='刀刃砍進了莫什奧格贈物，硬把它打開!', `MaleText_loc7`='¡La hoja cae sobre la recompensa de Mosh''Ogg y la abre de par en par!', `FemaleText_loc1`='검이 모쉬오그 노획물 안으로 들어갔습니다. 억지로라도 여십시오!', `FemaleText_loc4`='刀刃插进了莫什奥格的馈赠，把它打开！', `FemaleText_loc5`='刀刃砍進了莫什奧格贈物，硬把它打開!', `FemaleText_loc7`='¡La hoja cae sobre la recompensa de Mosh''Ogg y la abre de par en par!' WHERE `ID`=42897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 피부', `MaleText_loc4`='%s皮肤', `MaleText_loc5`='%s皮', `MaleText_loc7`='%s piel' WHERE `ID`=42898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 상관 마!', `MaleText_loc4`='你待在后面！那巨魔是我的！', `MaleText_loc5`='退後!這食人妖是我的!', `MaleText_loc7`='¡Quédate atrá''! ¡Ese trol es mío!' WHERE `ID`=42899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백골가루 부족은... 영원하리라...', `MaleText_loc4`='劈颅……是……永存的……伙计……', `MaleText_loc5`='劈顱...部族...萬歲...老兄...', `MaleText_loc7`='Machacacráneos... es... pa'' siempre... colega...' WHERE `ID`=42900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔질 님은 가시덤불 전체를 쓸어버릴 군대를 모으고 계시지! 붉은머리 부족, 백골가루 부족, 구루바시와 호드 모두가 잔질 님을 섬길 것이다!', `MaleText_loc4`='赞吉尔正在集结一支荡涤荆棘谷的大军！血顶、劈颅、古拉巴什与部落……都将为赞吉尔效命！', `MaleText_loc5`='贊吉爾正在創造一支足以橫掃整個荊棘谷的軍隊!血頂部族、劈顱部族 ，古拉巴什，還有部落...通通都會臣服於贊吉爾!', `MaleText_loc7`='Zanzil eh''tá creando un ejército que arrasará todo Tuerceh''pina. Los Machacacráneos, los Sangrapellejo, los Gurubashi y la Horda... ¡todos se''virán a Zanzil!' WHERE `ID`=42901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...얼라이언스 친구들이랑 싸울 때 호드 편을 들러 왔다지.', `MaleText_loc4`='……我们将开始协助部落，解决他们与那群联盟对手的小争端。', `MaleText_loc5`='...而我們會開始在部落與聯盟的小型衝突戰中幫助部落。', `MaleText_loc7`='...donde comenzaremos ayudando a la Horda en su pequeña escaramuza contra esos de la Alianza.' WHERE `ID`=42902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 너희가 있을 곳이 아니다!', `MaleText_loc4`='你不属于这里！', `MaleText_loc5`='你不屬於這裡!', `MaleText_loc7`='¡No deberías estar en este lugar!' WHERE `ID`=42903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 일부가 아닌 자들은 파괴해야 한다!', `MaleText_loc4`='与大地作对的人就只有死路一条！', `MaleText_loc5`='非屬地之界域者都必須消滅!', `MaleText_loc7`='¡Aquellos que no formen parte de la tierra tienen que ser destruidos!' WHERE `ID`=42904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 영역에 너희의 자리는 없다!', `MaleText_loc4`='你不属于土灵王国！', `MaleText_loc5`='你不屬於地之國度!', `MaleText_loc7`='¡No perteneces al mundo de la tierra!' WHERE `ID`=42905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런, 나 이러다.. 꺼억!', `MaleText_loc4`='呃哦……我要……嗝儿！', `MaleText_loc5`='呃噢...我要...噁!', `MaleText_loc7`='¡Eh, oh... voy a... vomitar!', `FemaleText_loc1`='오 이런, 나 이러다.. 꺼억!', `FemaleText_loc4`='呃哦……我要……嗝儿！', `FemaleText_loc5`='呃噢...我要...噁!', `FemaleText_loc7`='¡Eh, oh... voy a... vomitar!' WHERE `ID`=42906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과자 주셔서 고맙습니다!', `MaleText_loc4`='非常感谢你的点心！', `MaleText_loc5`='謝謝你送的餅乾!', `MaleText_loc7`='¡Gracias por las galletas!', `FemaleText_loc1`='과자 주셔서 고맙습니다!', `FemaleText_loc4`='非常感谢你的点心！', `FemaleText_loc5`='謝謝你送的餅乾!', `FemaleText_loc7`='¡Gracias por las galletas!' WHERE `ID`=42907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 고맙습니다!', `MaleText_loc4`='嗯，谢谢！', `MaleText_loc5`='耶，謝謝!', `MaleText_loc7`='¡Sí, gracias!', `FemaleText_loc1`='이야, 고맙습니다!', `FemaleText_loc4`='嗯，谢谢！', `FemaleText_loc5`='耶，謝謝!', `FemaleText_loc7`='¡Sí, gracias!' WHERE `ID`=42908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 봬요!', `MaleText_loc4`='再见！', `MaleText_loc5`='再見!', `MaleText_loc7`='¡Nos vemos!', `FemaleText_loc1`='또 봬요!', `FemaleText_loc4`='再见！', `FemaleText_loc5`='再見!', `FemaleText_loc7`='¡Nos vemos!' WHERE `ID`=42909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골에 온 걸 환영하네, $c|1이여;여;. 자네와는 처음부터 일이 꼬이고 싶지 않으니 말해두지만, 내 주둔지에 게으름뱅이 따위는 필요 없네. 그래도 자네처럼 건장한 $r라면 분명히 제 몫을 해낼 수 있을 걸세.', `MaleText_loc4`='$c，欢迎来到格罗姆高。为了避免今后发生问题，我现在要提醒你，我的营地里可容不下懒人。希望像你这样的健康$r能在这里发挥出应有的作用。', `MaleText_loc5`='歡迎來到格羅姆高，$c。為了避免一開始就有什麼不愉快，我先把醜話說在前面:在我的營地絕對不准打混。我希望像你這麼個健壯的$r能在這裡盡好你的本分。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Grom''gol, $c. Antes de que empecemos con mal pie, quiero que sepas que no quiero gandules en mi Campamento Base. Espero que $gun:una; $r rebosante de salud como tú deje su huella por estos lares.' WHERE `ID`=42910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 작고 궁벽하게 느껴질지 몰라도, 헬스크림 님께서 항상 자네를 지켜보고 계신다는 걸 잊지 말게.', `MaleText_loc4`='即使是在这个世界如此偏远的角落里，都不要忘记地狱咆哮的双目在注视着你。', `MaleText_loc5`='就算在這麼個偏遠的角落，要記住，地獄吼的雙眼在盯著你。', `MaleText_loc7`='Incluso en este remoto rincón del mundo, debes saber que los ojos de Grito Infernal te vigilan.' WHERE `ID`=42911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덤불의 트롤들은 우리 검은창 부족을 매우 싫어하지. 붉은머리 부족이나 백골가루 부족 따위는 두렵지 않지만, 그래도... 그롬골의 높은 벽을 보면 안도감이 느껴진다네.', `MaleText_loc4`='荆棘谷的巨魔对我们暗矛部族并不怎么友好。我不怕那些血顶或劈颅，可是……格罗姆高的高墙令我感到安全。', `MaleText_loc5`='荊棘谷的食人妖對我們暗矛一族不太友好。我並不害怕血頂或劈顱部族，但...在格羅姆高的圍牆後能給我安全的感覺。', `MaleText_loc7`='Los trols de Tuercespina no nos tratan muy bien a los Lanza Negra. No tengo miedo de los Sangrapellejo o los Machacacráneos, pero... los altos muros de Grom''gol me hacen sentirme seguro.' WHERE `ID`=42912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그롬골이 안전할 거란 내 생각이 틀렸을지도 모르겠군.$b$b트롤이라면 어딜 가든 몸조심해야 해.', `MaleText_loc4`='也许格罗姆高并非像我想的那么安全。$b$b身为巨魔，不论走到哪里，都要随时小心自己的脖颈被偷袭。', `MaleText_loc5`='也許我在格羅姆高並沒有我想像的那麼安全。$b$b食人妖不論走到哪裡都得顧好自己的腦袋。', `MaleText_loc7`='Quizá Grom''gol no sea tan seguro como creía.$b$bUn trol debe vigilar su espalda en todas partes.' WHERE `ID`=42913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<가마솥이 부글거립니다.>', `MaleText_loc4`='<大锅在冒着气泡。>', `MaleText_loc5`='<大鍋冒著泡泡。>', `MaleText_loc7`='<El caldero borbotea.>' WHERE `ID`=42914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 형은 오염된 노움들을 치료하는 데 여러 해 동안 애써왔어요. 그의 기록을 이용하면 녹괴물로 변해버린 노움들을 치료할 방법을 정립할 수 있을 거예요.', `MaleText_loc4`='我的兄弟多年来一直在研究使麻风侏儒痊愈的方法。通过研习他的笔记，我想我已经完善了流程——可以使那些已经被认定无药可救的侏儒回复到从前的样子。', `MaleText_loc5`='我兄弟花了好幾年的時間在研發醫治麻瘋地精的解藥。根據他的筆記，我想我已經改良了一道程序，可以把軟泥化的地精給恢復原形。', `MaleText_loc7`='Mi hermano lleva años buscando la cura para los gnomos parias. Basándome en sus notas, creo que he perfeccionado el método para recuperar a los gnomos que sucumbieron al lodo.' WHERE `ID`=42915;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포병의 손이 화약으로 시꺼멓습니다.', `FemaleText_loc4`='炮兵的双手沾满了黑色的火药粉。', `FemaleText_loc5`='砲手的雙手因為火藥而是黑的。', `FemaleText_loc7`='El cañonero tiene las manos negras por la pólvora.' WHERE `ID`=42916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<트롤이 혼자 노래를 부르며 가마솥을 바라보고 있습니다. 상처를 입은 것처럼 보입니다.>', `MaleText_loc4`='<巨魔自己唱着歌，眼睛看着锅里。他像是受了伤。>', `MaleText_loc5`='<食人妖兩眼盯著大鍋，自言自語在唱歌。他好像受傷了。>', `MaleText_loc7`='<El trol canta para sí mismo mientras mira fijamente el caldero. Parece que está herido.>' WHERE `ID`=42917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 해보자고요. 모두 고글을 쓰세요!', `MaleText_loc4`='让我们试试这个。所有人带好眼镜！', `MaleText_loc5`='來試試看這個吧。所有人，戴上護目鏡!', `MaleText_loc7`='Intentémoslo. ¡Pónganse las gafas!' WHERE `ID`=42918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 밀림에는 돈이 널려 있어, $n. 눈치챘어?$b$b아니, 금이나 구리 같은 거 말고. 랩터 가죽, 광맥, 고대 트롤 유물 같은 거 말이야.$b$b뭐, 광맥은 금이나 구리라고 할 수도 있겠지.$b$b하지만 내 말의 요점은 파악했지? 그렇지?', `MaleText_loc4`='在那片丛林里可藏着许多钱，$r。你看见了吗？$b$b不，这钱的样子跟你平时见到的金币或铜币不同。它的外观是迅猛龙的龙皮，还有矿脉，以及古老的巨魔圣物。$b$b好吧，也许矿脉和金币铜币的样子有点儿像。$b$b不过反正你明白我的意思了，对吧？', `MaleText_loc5`='叢林裡多的是錢，$r。你有看見嗎?$b$b不對，這裡的錢不是銅也不是金。這裡的錢是迅猛龍皮，是礦脈，還有古老的食人妖文物。$b$b好啦，礦脈也算銅和金啦。$b$b不過，你瞭解我講的重點吧?', `MaleText_loc7`='Hay un montón de dinero ahí fuera, en la jungla, $r. ¿Puedes verlo?$b$bNo, no aparece en forma de oro o de cobre; sino como pellejos de raptor, vetas de mineral y antiguos artefactos de los trols.$b$bVale, quizá las vetas de minerales sí aparezcan en forma de oro o cobre.$b$bPero entiendes lo que quiero decir, ¿no?' WHERE `ID`=42919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대하신 라스타칸 님이 호드의 일원인 자네에게 안부를 전하시네.', `MaleText_loc4`='伟大的拉斯塔哈为你送来了问候，部落的成员。', `MaleText_loc5`='偉大的拉斯塔哈要我代他向你致意，部落的成員。', `MaleText_loc7`='El gran Rastakhan te envía sus saludos, miembro de la Horda.' WHERE `ID`=42920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게... 무슨 일이 일어난 거지?', `MaleText_loc4`='什么……我这是怎么了？', `MaleText_loc5`='我...我怎麼了?', `MaleText_loc7`='¿Qué... qué me ha ocurrido?' WHERE `ID`=42921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단해! 우리가 해냈어요!', `MaleText_loc4`='真了不起！我们成功了！', `MaleText_loc5`='真是太驚人了!我們成功了!', `MaleText_loc7`='¡Absolutamente flipante! ¡Lo hemos conseguido!' WHERE `ID`=42922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 노움의 기준으로 보더라도 조금 작지만, 정신은 온전해요! 진짜 중요한 건 그가 기억하는 게 무엇이냐는 걸 거예요!', `MaleText_loc4`='当然，他个子小了点儿，即使是按侏儒的标准来看也一样，可他够机敏！关键问题是，他还记得什么？', `MaleText_loc5`='對啦，他是有點小，即使以地精標準而言。可是他人還在啊!現在更重要的問題是，他會記得什麼?', `MaleText_loc7`='Claro, es muy bajito, incluso para un gnomo, ¡pero está entero! La pregunta importante es: ¿Qué es lo que recordará?' WHERE `ID`=42923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 다 들리거든요?! 제가 아는 건 배가 고프다는 것과 이 끔찍하고 냄새나는 옷을 벗어버리고 싶다는 거예요!', `MaleText_loc4`='别把我当空气！我只知道我现在饥肠辘辘，我还要脱掉这身又臭又脏的衣服！', `MaleText_loc5`='不要視若無睹地在我面前講我的事情!我只知道我肚子好餓，而且我得脫掉這身奇臭無比的衣服!', `MaleText_loc7`='¡No hables de mí como si no estuviera presente! Todo lo que sé es que estoy hambriento y que necesito quitarme esta ropas feas y apestosas!' WHERE `ID`=42924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만, 이리 돌아오세요! 검사 결과를 봐야 해요!', `MaleText_loc4`='等等，快回来！我还要读取信息！', `MaleText_loc5`='等一下，回來!我還有數據要讀取!', `MaleText_loc7`='¡Espera, vuelve! ¡Debo hacer mediciones!' WHERE `ID`=42925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위생병에게도 가봐야 한단 말이에요!', `MaleText_loc4`='你该看医生了！', `MaleText_loc5`='你得去看醫生!', `MaleText_loc7`='¡Necesitas un médico!' WHERE `ID`=42926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일인가요, $n?', `FemaleText_loc4`='看看这是谁，$n？', `FemaleText_loc5`='這是什麼啊，$n?', `FemaleText_loc7`='¿Qué tenemos aquí, $n?' WHERE `ID`=42927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 사원으로 가는 게로구나, 맞지?', `MaleText_loc4`='我们是要前往大地神殿，对吧？', `MaleText_loc5`='我們要前往大地神殿，是嗎?', `MaleText_loc7`='Vamos al Templo de la Tierra, ¿verdad?' WHERE `ID`=42928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 대지 고리회 친구에게 날 데려가 다오. 너희들에게 알릴 중요한 소식이 있다.', `MaleText_loc4`='把我带到你这位大地之环的朋友那里去。我有重要的消息要告诉给你们两位。', `MaleText_loc5`='帶我去見你這位陶土議會的朋友。我有重要的消息要告訴你們兩個。', `MaleText_loc7`='Llévame ante esa amiga tuya del Anillo de la Tierra. Tengo noticias importantes para ambos.' WHERE `ID`=42929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장의 일지가 주위에 놓여 있습니다.', `MaleText_loc4`='船长的日志就放在附近。', `MaleText_loc5`='艦長的日誌就放在附近。', `MaleText_loc7`='El Diario del Capitán yace cerca.' WHERE `ID`=42930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 건 몰라도 우리 아바마마는 반드시 구출해야 하느니라.', `MaleText_loc4`='唯一要紧的事是救出我父亲。', `MaleText_loc5`='唯一重要的事情就是我們救出我的父親。', `MaleText_loc7`='Lo único que importa es que rescatemos a mi padre.' WHERE `ID`=42931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 하던 일은 당장 멈추고, 나를 도와 내 아버지이시자 토석인 지도자이신 바위 아버지를 구해야 한다.', `MaleText_loc4`='你必须放下手头所有事情，全力帮我救出我的父亲——土灵之王。', `MaleText_loc5`='你必須放下手邊所有的事情，幫助我救出我父親，也就是我們的首領石父。', `MaleText_loc7`='Debes dejar todo lo que tienes entre manos para ayudarme a liberar a mi padre y nuestro líder, el Padre Pétreo.' WHERE `ID`=42932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라. 그대의 대지 고리회 친구와 이야기를 나눠야겠다.', `MaleText_loc4`='我们必须抓紧时间并与你大地之环的朋友交谈。', `MaleText_loc5`='我們動作必須快，趕快與你在陶土議會的朋友們對話。', `MaleText_loc7`='Debemos darnos prisa y hablar con esa amiga tuya del Anillo de la Tierra.' WHERE `ID`=42933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 사원으로 가던 중에 공격을 받았다. 바위 트로그들이 손을 쓰기 전에 우리 아바마마를 구해야 하느니라.', `MaleText_loc4`='当我受到攻击时我正在前往神殿的途中。必须在石头穴居人对我父亲下手前把他救出来。', `MaleText_loc5`='我是在前往神殿的半路上遭到偷襲的。我們一定得趕在穴居怪殺掉我父親之前，將他救出來。', `MaleText_loc7`='Iba de camino al templo cuando me atacaron por sorpresa. Tenemos que rescatar a mi padre antes de que los troggs de piedra lo maten.' WHERE `ID`=42934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토석인과 바위 트로그 사이의 전쟁은 아득한 옛날부터 계속되고 있다. 그런데 녀석들이 이번 혼란을 틈타 바위 아버지를 포로로 잡았지. 항복하지 않으면 그분을 죽이겠다고 위협하면서 말이다.', `MaleText_loc4`='土灵与石头穴居人的战争已经不知持续了多少年。可在眼下这混乱之中，他们竟然将土灵之王囚禁了起来。他们威胁说，如果我们不投降，就杀了他。', `MaleText_loc5`='土靈與岩石穴居怪之間的戰爭已經持續了千百萬年。但如今在這場混亂之中，石父竟然被俘虜了。他們威脅如果我們不投降的話，就要把他給殺了。', `MaleText_loc7`='La guerra entre los terráneos y los troggs de piedra hace tiempo que se les ha ido de las manos. Pero ahora, en medio del caos, se han llevado al Padre Pétreo como prisionero. Amenazan con matarlo si no nos rendimos.' WHERE `ID`=42935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우물쭈물할 시간이 없다. 아버지께서 돌아가시기라도 하는 날엔 세계 기둥 중간 파편의 행방도 영영 묻히겠지. 너희가 그걸 찾는다는 걸 알고 있다.', `MaleText_loc4`='你要是聪明就别耽误时间。要是我父亲死了，那世界之柱中部碎片的位置也将和他一同消亡。我知道你们这些人想要得到它。', `MaleText_loc5`='你最好不要再浪費任何時間。萬一我父親不幸喪生，世界之柱中間段碎片藏在哪裡的情報也會隨他而消失。我知道你們的人正在找它。', `MaleText_loc7`='Sería mejor no perder el tiempo. Si mi padre muere, se llevará con él el conocimiento de dónde está escondido el segundo fragmento del Pilar del Mundo. Sé que ustedes lo quieren.' WHERE `ID`=42936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지술사여, 가시바위 잔여지의 바위 트로그들이 바위 아버지 오어맨틀, 나의 부친을 포로로 잡고 있다.', `MaleText_loc4`='唤地者，我的父亲，岩幔国王，已经被针石熔渣场的石头穴居人抓为了俘虏。', `MaleText_loc5`='喚地者，針岩尖柱的岩石穴居怪抓走了我的父親，石父礦被。', `MaleText_loc7`='Clamatierras, los troggs de piedra Rocaguja han hecho prisionero a mi padre, el Padre Pétreo Mantomena.' WHERE `ID`=42937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로에 지원병을 보낼 것을 요청하노라. 우리 전쟁에 동참하여 바위 아버지 오어맨틀 님을 구해 다오.', `MaleText_loc4`='我要你派人前往巨石之炉。帮我们打赢这场仗，把岩幔国王救出来。', `MaleText_loc5`='我要你協助石爐，幫我們打贏這一仗，救出石父礦被。', `MaleText_loc7`='Te exijo que envíes ayuda al Hogar Pétreo. Ayúdanos con nuestra guerra y a liberar al Padre Pétreo Mantomena.' WHERE `ID`=42938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 보기엔 나를 도와줬던 이 친구가 적합할 것 같다. 이 친구에게 명령하여 돌난로에 있는 우리의 사령관 크래그 록크러셔에게 보고하게 하라.', `MaleText_loc4`='帮我的这个人应该能够胜任。让他们去报告给我们在巨石之炉的军队指挥官——克拉格·摧石者。', `MaleText_loc5`='協助我的這一位應該就很合適。叫他們去石爐找我們的部隊指揮官峭壁碾石者報到。', `MaleText_loc7`='$gEste:Esta; que me ayudó servirá. Haz que informen a nuestro comandante, Crag Aplastarrocas en el Hogar Pétreo.' WHERE `ID`=42939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 돌난로로 날아가, 바위 트로그와 싸우고 있는 나의 백성들을 돕고, 우리 아버지를 구하라.$B$B나는 대지술사와 이야기를 좀 나누고 곧바로 따라가겠다.$B$B아버지께서 돌아가시게 놔두어선 안 된다, $n. 만약 일이 잘못되면 내 그대를 가만두지 않겠노라!', `MaleText_loc4`='你必须飞往巨石之炉，帮我的人民击败石头穴居人，救出我的父亲。$B$B等我与唤地者谈过之后就会去那里找你。$B$B别让他死了，$n，否则我会亲手把你埋进地里！', `MaleText_loc5`='你必須飛到石爐上，協助我們對抗岩石穴居怪，並且救出我父親。$B$B等我和喚地者談完之後我就會立刻趕過去那邊跟你碰面。$B$B不要讓他就此死掉，$n，否則我會親自把你埋進土裡!', `MaleText_loc7`='Debes volar al Hogar Pétreo para ayudar a mi gente contra los troggs de piedra y liberar a mi padre.$B$BMe reuniré contigo justo después de hablar con la clamatierras.$B$B¡No dejes que muera, $n, o yo mismo cavaré una tumba para ti!' WHERE `ID`=42940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 얘기한 그 대지술사와 만날 준비가 되었다.', `MaleText_loc4`='我已经准备好与你口中的唤地者会面了。', `MaleText_loc5`='我已經準備好和你們的喚地者見面。', `MaleText_loc7`='Estoy listo para conocer a esa que llamas clamatierras.' WHERE `ID`=42941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포탄의 표면에 "스톰윈드왕립공업"이라고 새겨져 있습니다.', `MaleText_loc4`='外壳上写着：“暴风城皇家工业集团”', `MaleText_loc5`='外殼上的刻印顯示:「暴風城皇家工業」', `MaleText_loc7`='En los restos se ve la marca: "INDUSTRIAS REALES DE VENTORMENTA".' WHERE `ID`=42942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 정글에 가 본 적 있나?$b$b정말 멋지다네.', `MaleText_loc4`='你去过丛林吗，$r？$b$b那可真是个好地方。', `MaleText_loc5`='有去過叢林嗎，$r?$b$b真的很棒。', `MaleText_loc7`='¿Alguna vez habías estado en la jungla, $r?$b$bEstá muy bien.' WHERE `ID`=42943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덤불 말이네, 친구. 바로 정글이 있는 곳이지!', `MaleText_loc4`='荆棘谷，$g伙计:宝贝儿;。就在那儿！', `MaleText_loc5`='荊棘谷，$g帥哥:美女;。它就在那裡!', `MaleText_loc7`='En Tuercespina, $gtío:nena;. ¡Allí es donde está!' WHERE `ID`=42944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가.', `MaleText_loc4`='你好。', `MaleText_loc5`='嗨。', `MaleText_loc7`='Hola.' WHERE `ID`=42945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 가시덤불에 돌아가고 싶군. 꽥꽥대는 랩터들, 트롤 전쟁, 끝도 없는 정글 생명체들, 그저 죽여 달라는...$b$b<한숨 쉬는 보트>', `MaleText_loc4`='啊，要是再回到荆棘谷。那些发出尖啸的迅猛龙，巨魔间的战争，目力所及处各式各样的丛林生物，就等着人们的捕杀……$b$b<博特叹了口气。>', `MaleText_loc5`='啊，總算回到荊棘谷。尖叫的迅猛龍，食人妖戰爭，放眼望去數不清的叢林生物，全都等著被你宰掉...$b$b<波爾特嘆了口氣。>', `MaleText_loc7`='Ah, volver a Tuercespina. Los chirridos de los raptores, las guerra de los trols, las criaturas de la jungla que se extienden hasta donde abarca la vista, ROGÁNDOTE que las mates...$B$B<Bort suspira.>' WHERE `ID`=42946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇에 마무리 손질을 해야겠어요.', `MaleText_loc4`='我的机器人就要大功告成了。', `MaleText_loc5`='該對我的機器人做點最後調校的時候了。', `MaleText_loc7`='Es hora de darle a mi robot el toque final.' WHERE `ID`=42947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 됐군요.', `MaleText_loc4`='终于，完成了。', `MaleText_loc5`='終於完成了。', `MaleText_loc7`='Por fin, está terminado.' WHERE `ID`=42948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라 나의... 가만, 이걸 뭐라고 부르지? ''다목적 로봇''이라고 하면 어떨까? 일어나라, 나의 다목적로봇!', `MaleText_loc4`='起来吧，我的……我该叫你什么好呢？叫你“多功能机器人”怎么样？起来吧，我的多功能机器人！', `MaleText_loc5`='起來吧，我的...呃，我該叫你什麼咧?『多工機器人』如何?起來吧，我的多工機器人!', `MaleText_loc7`='Levántate mi, eh... ¿Cómo debería llamarte? ¿Qué tal multi robot?' WHERE `ID`=42949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 몇 군데 조정 좀 해야겠군요...', `MaleText_loc4`='呃……看来还需要略做调整……', `MaleText_loc5`='嗯...再調整著幾下應該就可以了，我想...', `MaleText_loc7`='Eh... un par de ajustes más bastarán, creo...' WHERE `ID`=42950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 지원군과 함께 온 것 같지는 않군요. 이곳도 인원이 매우 부족한 상태입니다.', `MaleText_loc4`='难道你又带了一队人来，会吗？我们这儿已经没有人手了。', `MaleText_loc5`='我不敢奢望你又帶了一隊的人過來，有嗎?我們已經沒有多餘的人力了。', `MaleText_loc7`='No has traído otro pelotón contigo, ¿verdad? Estamos muy ocupados ahí fuera.' WHERE `ID`=42951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r 한 분 도착합니다!', `MaleText_loc4`='$r进入！', `MaleText_loc5`='到站了，$r!', `MaleText_loc7`='¡$r que llega!', `FemaleText_loc1`='$r 한 분 도착해요!', `FemaleText_loc4`='$r进入！', `FemaleText_loc5`='到站了，$r!', `FemaleText_loc7`='¡$r que llega!' WHERE `ID`=42958;
