UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은마루 산맥에 오신 것을 환영합니다, $c님!', `MaleText_loc4`='欢迎来到赤脊山，$c！', `MaleText_loc5`='歡迎來到赤脊山，$c!', `MaleText_loc7`='¡Te doy la bienvenida a Crestagrana, $c!', `FemaleText_loc1`='붉은마루 산맥에 오신 것을 환영해요, $c님!', `FemaleText_loc4`='欢迎来到赤脊山，$c！', `FemaleText_loc5`='歡迎來到赤脊山，$c!', `FemaleText_loc7`='¡Te doy la bienvenida a Crestagrana, $c!' WHERE `ID`=42962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸조심하십시오, $c님.', `MaleText_loc4`='时刻保持警惕，$c。', `MaleText_loc5`='整裝戒備,$c。', `MaleText_loc7`='No bajes la guardia, $c.', `FemaleText_loc1`='몸조심하세요, $c님.', `FemaleText_loc4`='时刻保持警惕，$c。', `FemaleText_loc5`='整裝戒備,$c。', `FemaleText_loc7`='No bajes la guardia, $c.' WHERE `ID`=42963;
