UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c 또 한 분 오십니다!', `MaleText_loc4`='又有个$r进来了！', `MaleText_loc5`='另一個$c回來了!', `MaleText_loc7`='¡$gOtro:Otra; $r que está a punto de llegar!', `FemaleText_loc1`='$c 또 한 분 오고 계세요!', `FemaleText_loc4`='又有个$r进来了！', `FemaleText_loc5`='另一個$c回來了!', `FemaleText_loc7`='¡$gOtro:Otra; $r que está a punto de llegar!' WHERE `ID`=42965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 위협하는 저 마법은 황혼의 망치단이 사용하는 것이다.$B$B우리는 놈들을 우리 고향에서 싹 쓸어버리기를 간절히 원하고 있지.$B$B하지만 우리의 분열 때문에 그리할 수가 없다.$B$B그래서 난 지켜보고...$B$B기다린다.', `MaleText_loc4`='暮光教派中存在着对我们具有严重威胁的法术。$B$B我们恨不得马上让他们滚出我们的家园。$B$B我们被分开了，所以我们不能这么做。$B$B于是我在观望着……$B$B等待着……', `MaleText_loc5`='暮光教派給我們帶來的是極大的魔法威脅。$B$B我們每分每秒都想著要把他們從我們的世界中消去。$B$B但我們分裂了，所以做不到。$B$B我現在在觀察...$b$b在等待...', `MaleText_loc7`='En el culto Crepuscular hay magos que nos amenazan.$B$BEstamos deseando borrarlos de la faz de la tierra y eliminarlos de nuestro hogar.$B$BEstamos divididos, por lo que no podemos.$B$BAsí que me dedico a observar... $B$BY a esperar...' WHERE `ID`=42971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위벌레가 또 우릴 공격한다! 빨리 처치해라!', `MaleText_loc4`='又一只岩虫！快杀了它！', `MaleText_loc5`='又一隻岩石蟲!快點殺掉它!', `MaleText_loc7`='¡Nos ataca otro gusano de piedra! ¡Mátalo, rápido!' WHERE `ID`=42982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레가 공격한다! 모두 전투 태세로!', `MaleText_loc4`='我们遭到攻击了！准备作战！', `MaleText_loc5`='我們遭到攻擊了!準備作戰!', `MaleText_loc7`='¡Nos atacan! ¡A las armas!' WHERE `ID`=42983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지에 바위벌레가 또 나타났다! 비룡을 보호하라!', `MaleText_loc4`='营地里又出现一只岩虫！快召唤龙！', `MaleText_loc5`='營地又出現一隻岩石蟲!去通報那些龍!', `MaleText_loc7`='¡Hay otro gusano de piedra en el campamento! ¡Que alguien vaya a por los dracos!' WHERE `ID`=42984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에! 이번 벌레는 아까보다 더 크다!', `MaleText_loc4`='以元素的名义，这个比之前的还要大！', `MaleText_loc5`='我的天啊，這一隻比之前的還要更大!', `MaleText_loc7`='¡Por los elementos, este es incluso más grande que el anterior!' WHERE `ID`=42985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c 한 분 출발합니다.', `MaleText_loc4`='出发，$c。', `MaleText_loc5`='出發了，$c。', `MaleText_loc7`='Saliendo, $c.', `FemaleText_loc1`='$c 한 분 출발해요.', `FemaleText_loc4`='出发，$c。', `FemaleText_loc5`='出發了，$c。', `FemaleText_loc7`='Saliendo, $c.' WHERE `ID`=42986;
