UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지는 네놈 머리 위로 무너질 것이다!', `MaleText_loc4`='深岩之洲会塌在你们身上！', `MaleText_loc5`='地深之源會崩塌在你身上!', `MaleText_loc7`='¡Infralar se derrumbará sobre ustedes!', `FemaleText_loc1`='심원의 영지는 네놈 머리 위로 무너질 것이다!', `FemaleText_loc4`='深岩之洲会塌在你们身上！', `FemaleText_loc5`='地深之源會崩塌在你身上!', `FemaleText_loc7`='¡Infralar se derrumbará sobre ustedes!' WHERE `ID`=42992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 내리는 장엄한 분노를 맛봐라!', `MaleText_loc4`='面对暮光炫目的怒气吧！', `MaleText_loc5`='你所面對的是輝煌的暮光之怒!', `MaleText_loc7`='¡Os enfrentáis a la gloriosa ira del Crepúsculo!', `FemaleText_loc1`='황혼의 망치단이 내리는 장엄한 분노를 맛봐라!', `FemaleText_loc4`='面对暮光炫目的怒气吧！', `FemaleText_loc5`='你所面對的是輝煌的暮光之怒!', `FemaleText_loc7`='¡Os enfrentáis a la gloriosa ira del Martillo Crepuscular!' WHERE `ID`=42993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 님의 그림자가 네 위로 내려앉는다.', `MaleText_loc4`='死亡之翼的阴影笼罩着你。', `MaleText_loc5`='死亡之翼的影子覆蓋了你。', `MaleText_loc7`='La sombra de Alamuerte planea sobre ustedes.', `FemaleText_loc1`='데스윙 님의 그림자가 네 위로 내려앉는다.', `FemaleText_loc4`='死亡之翼的阴影笼罩着你。', `FemaleText_loc5`='死亡之翼的影子覆蓋了你。', `FemaleText_loc7`='La sombra de Alamuerte planea sobre ustedes.' WHERE `ID`=42994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라제인은 파멸을 피할 수 없다!', `MaleText_loc4`='塞拉赞恩必死无疑！', `MaleText_loc5`='瑟拉贊恩的末日已成定局!', `MaleText_loc7`='¡La condenación de Therezane es segura!', `FemaleText_loc1`='테라제인은 파멸을 피할 수 없다!', `FemaleText_loc4`='塞拉赞恩必死无疑！', `FemaleText_loc5`='瑟拉贊恩的末日已成定局!', `FemaleText_loc7`='¡La condenación de Therezane es segura!' WHERE `ID`=42995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 세계는 붕괴됐다! 곧, 너도 따라갈 것이다!', `MaleText_loc4`='你的世界已经破碎！很快，你也将成为这世上的亡魂！', `MaleText_loc5`='你的世界已經破碎!不久，你也將同它一起死亡!', `MaleText_loc7`='¡Su mundo está destrozado! ¡Y ustedes pronto se unirán a él en la muerte!', `FemaleText_loc1`='네놈의 세계는 붕괴됐다! 곧, 너도 따라갈 것이다!', `FemaleText_loc4`='你的世界已经破碎！很快，你也将成为这世上的亡魂！', `FemaleText_loc5`='你的世界已經破碎!不久，你也將同它一起死亡!', `FemaleText_loc7`='¡Su mundo está destrozado! ¡Y ustedes pronto se unirán a él en la muerte!' WHERE `ID`=42996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단에 맞서는 자에게 희망은 없다!', `MaleText_loc4`='暮光的敌人只有死路一条！', `MaleText_loc5`='暮光的敵人毫無希望!', `MaleText_loc7`='¡No hay esperanza para los enemigos del Crepúsculo!', `FemaleText_loc1`='황혼의 망치단에 맞서는 자에게 희망은 없다!', `FemaleText_loc4`='暮光的敌人只有死路一条！', `FemaleText_loc5`='暮光的敵人毫無希望!', `FemaleText_loc7`='¡No hay esperanza para los enemigos del Crepúsculo!' WHERE `ID`=42997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 스며드는구나! 두려움에 떨 것이다!', `MaleText_loc4`='暮色降临！在恐惧中战栗吧！', `MaleText_loc5`='暮光將近!驚懼而慄!', `MaleText_loc7`='¡Se acerca el anochecer! ¡Temblad de miedo!', `FemaleText_loc1`='어둠이 스며드는구나! 두려움에 떨 것이다!', `FemaleText_loc4`='暮色降临！在恐惧中战栗吧！', `FemaleText_loc5`='暮光將近!驚懼而慄!', `FemaleText_loc7`='¡Se acerca el anochecer! ¡Temblad de miedo!' WHERE `ID`=42998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라즐로 크러쉬코그는 쓰러졌다! 바로 오늘, 아이언포지와 놈리건의 시민들이 한마음 한뜻이 되었노라. 잘 들어라, 텔마플러그. 네놈의 마지막도 머지않았다!', `MaleText_loc4`='拉奇诺·碎轮已经完蛋了！铁炉堡和诺莫瑞根的成员们今天团结在了一起。给我听好了，瑟玛普拉格。你被我们消灭的日子也不远了！', `MaleText_loc5`='拉茲羅·碾輪已是過去式!鐵爐堡和諾姆瑞根的人民在今天是一體的。好好聽著，瑟瑪普拉格，你被擊敗的那天就快到了!', `MaleText_loc7`='¡Razlo Prensadiente ya no existe! Los pueblos de Forjaz y Gnomeregan han unido sus voces. Escúchanos, Termochufe. ¡El día de tu derrota se acerca!' WHERE `ID`=42999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 과학자에게 가보는 게 더 좋겠네요.', `MaleText_loc4`='最好弄成个火箭专家。', `MaleText_loc5`='最好把那變成像發明火箭一樣困難。', `MaleText_loc7`='Mejor un científico de cohetes.' WHERE `ID`=43022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상해. 어제 막 잿빛 골짜기에 투입되던 중이었는데...', `MaleText_loc4`='奇怪……昨天我刚刚被决定派往灰谷。', `MaleText_loc5`='奇怪...就在昨天，我被派往了梣谷。', `MaleText_loc7`='Qué extraño...  Ayer mismo fue enviado a Vallefresno.' WHERE `ID`=43037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도중에 갑자기 여기로 집합하라는 명령을 받았어. 중요한 일인가 보지?', `MaleText_loc4`='我在半途接到与你们汇合的命令。这准是个重要的任务。', `MaleText_loc5`='行進到一半，我接到指令與你們在這碰面。這一定非常重要。', `MaleText_loc7`='En camino, me ordenaron que me reuniera con ustedes aquí. Debe ser importante.' WHERE `ID`=43038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기 못 들었나?', `MaleText_loc4`='你没听说吗？', `MaleText_loc5`='你沒聽說嗎?', `MaleText_loc7`='¿No oyeron?' WHERE `ID`=43039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다 밑에서 섬이 솟아올랐다네... 스톰윈드 해안가에 말이야.', `MaleText_loc4`='一座岛屿从深渊里升了起来……就在暴风城的海岸边。', `MaleText_loc5`='一座島在離暴風城的海灘不遠處從地底升起了。', `MaleText_loc7`='Una isla emergió de las profundidades... cerca de la costa de Ventormenta.' WHERE `ID`=43040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거길 차지하러 가는 걸세.', `MaleText_loc4`='我们要去占领它。', `MaleText_loc5`='我們要奪取它。', `MaleText_loc7`='La tomaremos.' WHERE `ID`=43041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 섬만 손에 넣으면 스톰윈드는 끝장이라고 할 수 있지.', `MaleText_loc4`='一旦我们成功，暴风城就没几天好日子了。', `MaleText_loc5`='等我們成功後，暴風城的日子就不多了。', `MaleText_loc7`='Una vez hecho, los días de Ventormenta estarán contados.' WHERE `ID`=43042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬이 솟아오르다니... 그것도 스톰윈드를 칠 수 있는 곳에?', `MaleText_loc4`='一座岛屿从海里冒出来……暴风城在它的攻击范围内？', `MaleText_loc5`='一座島從海中升起...在暴風城的攻擊範圍內?', `MaleText_loc7`='Una isla emergió del mar... ¿a corta distancia de Ventormenta?' WHERE `ID`=43043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 깨진엄니 마을로 데려다 주십시오.', `MaleText_loc4`='送我去恶齿村。', `MaleText_loc5`='帶我去惡齒村。', `MaleText_loc7`='Llévame a Poblado Sañadiente.', `FemaleText_loc1`='저를 깨진엄니 마을로 데려다 주세요.', `FemaleText_loc4`='送我去恶齿村。', `FemaleText_loc5`='帶我去惡齒村。', `FemaleText_loc7`='Llévame a Poblado Sañadiente.' WHERE `ID`=43044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 분명히 필연이라고! 이 아제로스가 호드를 돕고 있는 거야!', `MaleText_loc4`='这绝不是巧合！艾泽拉斯世界正眷顾着部落！', `MaleText_loc5`='這不是個巧合!這一定是艾澤拉斯要幫助部落!', `MaleText_loc7`='¡Esto no es coincidencia! ¡Azeroth mismo envió a los suyos con la Horda!' WHERE `ID`=43045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=43046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=43047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 전사여. 이걸 먹게.', `MaleText_loc4`='给，战士。吃掉它。', `MaleText_loc5`='這裡，戰士。嚐嚐這個。', `MaleText_loc7`='Toma, guerrero. Cómelo.' WHERE `ID`=43049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반사 신경이 좋아지고 체력도 꽤 늘어날 걸세.', `MaleText_loc4`='它能让你变得更加灵敏，更加坚韧。', `MaleText_loc5`='你的反射神經將會變快，你的耐力也會跟著提高。', `MaleText_loc7`='Tus reflejos se agudizarán y tu aguante se incrementará.' WHERE `ID`=43050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허! 난 그딴 것에 의지할 필요 없네.', `MaleText_loc4`='哈！我不需要这种玩意儿，朋友。', `MaleText_loc5`='哈!我不需要你的幫助，朋友。', `MaleText_loc7`='¡Ja! No necesito tus muletas, amigo.' WHERE `ID`=43051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 스톰윈드 최정예 부대와 싸워 왔고, 아직 쌩쌩하다고.', `MaleText_loc4`='我曾经面对过暴风城最强的战士，而我还是站在这儿。', `MaleText_loc5`='我曾經面對過暴風城菁英中的菁英，而我還是昂首站立著。', `MaleText_loc7`='He enfrentado a los mejores de Ventormenta y sigo aquí.' WHERE `ID`=43052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 나도 자네만큼, 어쩌면 자네보다 더 많이 얼라이언스를 처치했네.', `MaleText_loc4`='我干掉的联盟战士可不比你少，兄弟。也许更多。', `MaleText_loc5`='我的斧頭劈開的聯盟頭骨數量不輸於你，兄弟。或許還要更多。', `MaleText_loc7`='Mi hacha ha partido tantos cráneos de la Alianza como la tuya. Tal vez más.' WHERE `ID`=43053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님은 그야말로 완벽한 승리를 바라실 게야.', `MaleText_loc4`='只有彻底的胜利才能让地狱咆哮满意。', `MaleText_loc5`='地獄吼只會對壓倒性的完全勝利感到滿意。', `MaleText_loc7`='Grito Infernal sólo se conformará con la victoria absoluta.' WHERE `ID`=43054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하면 저 세상까지 쫓아와서라도 우릴 처벌하시고 말걸.', `MaleText_loc4`='要是我们失败了，他会一直追到地狱来惩罚我们的。', `MaleText_loc5`='如果我們失敗了，他就算追到地獄也會來懲罰我們。', `MaleText_loc7`='Si fallamos, nos perseguirá en la otra vida en busca de retribución.' WHERE `ID`=43055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 그 말을 듣고 보니 생각이 달라지는군. 형제여, 고맙게 먹겠네...', `MaleText_loc4`='恩，你的话语中包含着智慧，兄弟。我会带上你的食物……', `MaleText_loc5`='你的言語中帶有智慧，兄弟。我接受你的食物...', `MaleText_loc7`='Tus palabras son sabias, hermano. Tomaré esa comida…' WHERE `ID`=43056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하. 그래, 형제여. 정말 그런 것 같군...', `MaleText_loc4`='当然，兄弟。就是这样……', `MaleText_loc5`='沒錯，兄弟，看起來是這樣...', `MaleText_loc7`='Cierto, hermano. Eso parece…' WHERE `ID`=43058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 행운이 따르길 빕니다!', `MaleText_loc4`='好运相伴，$n！', `MaleText_loc5`='祝你好運，$n!', `MaleText_loc7`='¡Toda la suerte del mundo, $n!', `FemaleText_loc1`='$n 님, 행운이 따르길 빌어요!', `FemaleText_loc4`='好运相伴，$n！', `FemaleText_loc5`='祝你好運，$n!', `FemaleText_loc7`='¡Toda la suerte del mundo, $n!' WHERE `ID`=43076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 좀 주게.', `MaleText_loc4`='好的，我也要。', `MaleText_loc5`='是的，遵命。', `MaleText_loc7`='Sí, como yo.' WHERE `ID`=43080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 헬스크림 선봉대라고!', `MaleText_loc4`='我们是地狱咆哮的先锋！', `MaleText_loc5`='我們是地獄吼的先鋒!', `MaleText_loc7`='¡Somos la Vanguardia de Grito Infernal!' WHERE `ID`=43081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리가 저런 꼴사나운 용병선을 타고 싸우러 가야 하나?', `MaleText_loc4`='为什么我们要乘着这些可悲的雇佣兵船去打仗？', `MaleText_loc5`='我們為什麼要坐著這些可悲的傭兵工具到戰場上?', `MaleText_loc7`='¿Por qué vamos a la batalla en un navío mercenario patético?' WHERE `ID`=43082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 함선은 이미 그 지역에 파견됐네.', `MaleText_loc4`='其他的舰队都已经被派往战区了。', `MaleText_loc5`='其餘的艦隊已經被派遣到這一區了。', `MaleText_loc7`='El resto de la flota ya ha sido enviado a la región.' WHERE `ID`=43083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 귀항이 많이 늦어지고 있어.', `MaleText_loc4`='…但他们迟迟没有返航。', `MaleText_loc5`='...他們早就應該回來了。', `MaleText_loc7`='...ya era hora de su regreso.' WHERE `ID`=43084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 그러니까 애초에 우리를 보냈어야지.', `MaleText_loc4`='哈！他们早知道该先派我们出马。', `MaleText_loc5`='哈!他們早該派我們出馬了。', `MaleText_loc7`='¡Ja! Debieron enviarnos a nosotros desde un principio.' WHERE `ID`=43085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동의하네, 형제여. 하지만 요즘 전투가 벌어지는 곳은 많은데 선봉대원은 수가 적잖나...', `MaleText_loc4`='我同意，兄弟，部落最近征战不断，可先锋战士的数量却不够……', `MaleText_loc5`='同意，兄弟，但部落近期東征西討，先鋒隊的人已經越來越少了...', `MaleText_loc7`='De acuerdo, pero la Horda tiene muchos problemas actualmente y en la Vanguardia son pocos…' WHERE `ID`=43086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에겐 다행이지. 우리가 한 번에 한 군데밖에 있을 수 없다는 게.', `MaleText_loc4`='我们的敌人真走运，我们每次只能出现在一个地方。', `MaleText_loc5`='算我們的敵人運氣好，我們一次只能出現在一個地方。', `MaleText_loc7`='Por suerte para el enemigo, sólo podemos estar en un lugar a la vez.' WHERE `ID`=43087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁을 준비하십시오! 썩은가지 부족의 만행을 더는 용납할 수 없습니다!', `FemaleText_loc4`='准备作战！我们已经对邪枝部族忍无可忍！', `FemaleText_loc5`='準備開戰!我們不能再縱容邪枝部族的敗類!', `FemaleText_loc7`='¡Preparaos para la guerra! ¡Ya no estamos dispuestos a tolerar a los Vilrama!' WHERE `ID`=43088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수다는 그만! 승선할 시간이다.', `MaleText_loc4`='闲聊结束！我们的船来了。', `MaleText_loc5`='聊夠了!我們的交通工具來了。', `MaleText_loc7`='¡Basta de cháchara! Aquí están.' WHERE `ID`=43089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 손수 취역하신 배다.', `MaleText_loc4`='这是由地狱咆哮亲自派来的。', `MaleText_loc5`='這艘船是由地獄吼親自任命的。', `MaleText_loc7`='Esa nave fue encomendada por el mismo Grito Infernal.' WHERE `ID`=43090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 군령을 따라라. 승무원을 괴롭히지 마라!', `MaleText_loc4`='你们都给我记住—— 不得侵扰船员！', `MaleText_loc5`='全部的人都必須嚴守規矩 - 不得騷擾船員!', `MaleText_loc7`='Las órdenes son estrictas: ¡no molesten a su tripulación!' WHERE `ID`=43091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿빛 골짜기에 스며드는 타락을 끝내버려야만 합니다.', `MaleText_loc4`='我们必须终结渗入灰谷的堕落之息。', `MaleText_loc5`='我們必須終止腐化持續滲透進入梣谷。', `MaleText_loc7`='Debemos poner fin a la corrupción que invade Vallefresno.' WHERE `ID`=43092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 배에서 인간 냄새가 난다.', `MaleText_loc4`='呜……这艘船上有人类的臭气。', `MaleText_loc5`='嘎...這艘船散發人類的臭味。', `MaleText_loc7`='Puaj... Esta nave apesta a humanos.' WHERE `ID`=43093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 인간이란... 으하하하하!', `MaleText_loc4`='哈！人类……', `MaleText_loc5`='哈!人類...', `MaleText_loc7`='¡Ja! Humanos...' WHERE `ID`=43094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 내 말을 들어라!', `MaleText_loc4`='听我号令，弟兄们！', `MaleText_loc5`='聽我一言，兄弟們!', `MaleText_loc7`='¡Escúchenme, hermanos!' WHERE `ID`=43095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 미지의 섬을 향해 간다. 아제로스가 호드에게 주는 선물이지!', `MaleText_loc4`='我们将航向一座新生的岛屿，那是艾泽拉斯世界赠予部落的厚礼！', `MaleText_loc5`='我們航行到一座新島嶼，艾澤拉斯給部落的禮物!', `MaleText_loc7`='¡Zarpamos a una isla virgen, un regalo de Azeroth a la Horda!' WHERE `ID`=43096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 땅을 차지하면 전쟁에서 이길 것이다!', `MaleText_loc4`='占领那岛屿，我们就能赢得这场战争！', `MaleText_loc5`='佔領這個島嶼能讓我們贏得戰爭!', `MaleText_loc7`='¡Afiancemos esta tierra y la victoria será nuestra!' WHERE `ID`=43097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적은 잘 싸웠다, 얼라이언스치고는 말이지... 하지만 놈들은 지쳐가고 있어.', `MaleText_loc4`='就联盟而言，敌人的表现还不错……但他们已经显出疲态了。', `MaleText_loc5`='聯盟這次相當頑強，但是他們也累了。', `MaleText_loc7`='El enemigo ha peleado bien... pero se están cansando.' WHERE `ID`=43098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 놈들의 잔당을 처리하고 저 땅을 차지하고 말 것이다.', `MaleText_loc4`='我们将摧毁剩下的敌人，并占领那座岛屿。', `MaleText_loc5`='我們會殲滅他們剩下的殘兵並佔領這座島嶼。', `MaleText_loc7`='Aplastaremos lo que queda de ellos y reclamaremos esta tierra.' WHERE `ID`=43099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 해안을 통해 스톰윈드를 정복할 것이다. 적에게서 마지막 한 조각 희망까지 빼앗을 것이다.', `MaleText_loc4`='以它为桥头堡，我们将征服暴风城，粉碎敌人依靠的任何希望。', `MaleText_loc5`='從它的海岸，我們會征服暴風城並摧毀敵人殘留的希望。', `MaleText_loc7`='Desde estas costas tomaremos Ventormenta y la esperanza que le quede al enemigo.' WHERE `ID`=43100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스는 단 하나의 깃발 아래 재편성될 것이다!', `MaleText_loc4`='艾泽拉斯世界将会重新臣服同一面旗帜之下！', `MaleText_loc5`='艾澤拉斯將會在同一面旗幟下重生!', `MaleText_loc7`='¡Azeroth será reforjado bajo un solo estandarte!' WHERE `ID`=43101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 깃발 아래!', `MaleText_loc4`='这面旗帜！', `MaleText_loc5`='就是這面旗!', `MaleText_loc7`='¡¡Este estandarte!!' WHERE `ID`=43102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 적 텔마플러그가 계속해서 놈리건 나머지 지역의 장악을 강화하는 것을 그냥 놓아둘 수는 없어요.', `MaleText_loc4`='我们不能再任由我们的敌人——瑟玛普拉格，继续对诺莫瑞根的其余地区施行统治了。', `MaleText_loc5`='我們不能讓我們的敵人，瑟瑪普拉格，繼續鞏固他在諾姆瑞根其他地區的統治權。', `MaleText_loc7`='No podemos permitir que nuestro enemigo, Termochufe, continúe cerrando su puño sobre el resto de Gnomeregan.' WHERE `ID`=43103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텔마플러그는 그의 충복인 라즐로 크러쉬코그에게 우리가 계속해서 수비에만 치중하도록 유도하라고 명령을 내린 상태예요. 힝클스, 라즐로 크러쉬코그와 그의 부하들에 대한 최신 정보는 어떤 것이 있나요?', `MaleText_loc4`='他已经命部下——拉奇诺·碎轮来让我们疲于防御。辛克尔斯，有什么关于拉奇诺和他手下的最新情报吗？', `MaleText_loc5`='他下令他的親信拉茲羅·碾輪對我們展開猛攻，逼我們採取守勢。辛寇斯，有什麼拉茲羅和他手下的最新消息嗎?', `MaleText_loc7`='Ha ordenado a su compinche, Razlo Prensadiente, que nos mantenga a la defensiva. Hinkles, ¿qué es lo último que sabemos sobre Razlo y sus hombres?' WHERE `ID`=43104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라즐로 크러쉬코그가 꾸미는 계획의 정보를 우리 첩보원이 알아내기란 쉬운 일이 아니었죠.', `MaleText_loc4`='我们的侦察兵很难获知碎轮的计划。', `MaleText_loc5`='我們的斥候要探查到碾輪的計畫並不容易。', `MaleText_loc7`='A los exploradores nos ha costado mucho reunir información sobre los planes de Prensadiente.' WHERE `ID`=43105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히히히! 어서 타시죠. 빨리 올라와요!', `MaleText_loc4`='快上船来，快点。踩上来！', `MaleText_loc5`='上船囉。快點上來!', `MaleText_loc7`='Todos a bordo. ¡Arriba!' WHERE `ID`=43106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사미르 선장은 쉬지도 않고 간다네. 저 멀리 바다 끝으로 우릴 데려간다네!', `MaleText_loc4`='萨米尔船长将指引这艘船直达大洋彼岸……', `MaleText_loc5`='山米爾船長率領這艘船全速從這裡航行到那個外海...', `MaleText_loc7`='El capitán Samir navega esta nave sin parar hasta el océano y más allá…
' WHERE `ID`=43107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 얼라이언스랑 투닥투닥 싸움질하는 곳으로! 우리는 호드 편!', `MaleText_loc4`='……我们要在那里协助部落，解决他们跟联盟对手的小冲突。', `MaleText_loc5`='...到那邊去協助部落作戰，對抗聯盟那些傢伙。', `MaleText_loc7`='...donde comenzaremos ayudando a la Horda en su pequeña escaramuza contra esos de la Alianza.' WHERE `ID`=43108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈 벌기 쉽지, 히히히! 용병비는 살아남은 사람들끼리 나눠 가지는 거야!', `MaleText_loc4`='轻松赚钱！佣金将由所有幸存者平分，人人有份！', `MaleText_loc5`='輕鬆賺大錢!佣金到時候會平均分給所有的生還者!', `MaleText_loc7`='¡Dinero fácil! ¡Se repartirán comisiones para todos los sobrevivientes en partes iguales!
' WHERE `ID`=43109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 확실히 알아낸 건 크러쉬코그는 시험용 최첨단 기계보행전차를 사용하고 있다는 것과 그의 오염된 노움들이 오래된 무기고에서 그것을 더 수리하려고 한다는 거예요.', `MaleText_loc4`='据我们所知，碎轮正在使用一种先进的步行坦克原型，而他手下那些被辐射的侏儒们正在破旧的兵工厂里奋力修复更多同类坦克。', `MaleText_loc5`='我們確定知道的是，碾輪正在使用一輛先進的機器坦克原型機，而他的輻射地精們則試圖修復舊軍火庫那邊的武器。', `MaleText_loc7`='Lo que sí sabemos es que Prensadiente está usando un prototipo de mecanotanque avanzando y sus gnomos irradiados están intentado reparar más en el viejo arsenal.' WHERE `ID`=43110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 단독으로 이 일을 해결하려면 쉽지 않을 거예요. 그래서 드워프 도시인 아이언포지에 지원을 요청하는 편지를 보냈어요.', `FemaleText_loc4`='若想单凭我们的力量解决简直太难了。我已经送信到矮人主城铁炉堡，请求他们的支援。', `FemaleText_loc5`='我們要獨自應付這件事情恐怕會有點困難。我已經送了一封信到矮人的首都鐵爐堡去請求他們的支援。', `FemaleText_loc7`='Va a estar complicado que nos encarguemos solos de esto. He enviado un mensaje a la capital de los enanos, Forjaz, pidiéndoles ayuda.' WHERE `ID`=43111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신 왼쪽을 보면 노움들이 놈리건을 되찾았다는 걸 알 수 있을 거예요. 만세!', `MaleText_loc4`='要是你往你的左边看看，就会发现侏儒们已经夺回了诺莫瑞根！我们真是太伟大了！', `MaleText_loc5`='如果你往左邊看過去的話，就可以看到地精已經奪回了諾姆瑞根。為我們歡呼吧!', `MaleText_loc7`='Y si miras a tu izquierda, verás que los gnomos han recuperado Gnomeregan. ¡Tres hurras por nosotros!' WHERE `ID`=43112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 역시 많은 일이 일어나고 있어요. 공항으로 가는 길이 열렸고, 동쪽에 검은무쇠 부족이 있다는 소문과... 아, 그리고 드워프의 왕이신 마그니 브론즈비어드 님께 무언가 이상한 일이 일어나는 것 같으니 아마도 그걸 한번 알아봐야 할 거예요.', `MaleText_loc4`='外面也有许多事情正在发生。通往机场的路线打通了，在东边有关于黑铁部族的传闻……噢，我想矮人国王麦格尼最近也有些不太对劲。也许应该去查清楚。', `MaleText_loc5`='這邊也還有很多其他的事情。我們開通了連往機場的道路，然後還有黑鐵矮人在東邊出沒的傳聞...哦，而且我覺得矮人國王麥格尼好像有點不大對勁。也許你可以去看看。', `MaleText_loc7`='Ahí fuera también están pasando muchas cosas. Hemos abierto un camino hasta el aeropuerto, corren rumores de que se han visto Hierro Negro en el este... oh, y creo que algo raro sucede con ese rey enano, Magni. Quizá quieras echar un vistazo.' WHERE `ID`=43113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체 무슨 일이지?!', `MaleText_loc4`='这意味着什么？！', `MaleText_loc5`='這是做什麼?', `MaleText_loc7`='¡¿Qué significa esto?!' WHERE `ID`=43114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다 왔어요! 카라노스에 오신 것을 환영해요! 내릴 때 발 조심하시고요.', `MaleText_loc4`='我们到了！欢迎来到卡拉诺斯！出去时请小心脚下。', `MaleText_loc5`='就是這裡!歡迎來到卡拉諾斯!出去時當心你的腳步。', `MaleText_loc7`='¡Y aquí estamos! ¡Te doy la bienvenida a Kharanos! Ten cuidado al salir.' WHERE `ID`=43115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장이 눈앞에 있는데!', `MaleText_loc4`='我们必须胜利！', `MaleText_loc5`='我們還有場仗要打!', `MaleText_loc7`='¡Tenemos una batalla pendiente!' WHERE `ID`=43116;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브루날 마을에서 떠난 전령이 오늘 아침 우리에게 도착했어요. 드워프들이 우리를 도우려고 산악경비대원들을 보내고 있답니다.', `FemaleText_loc4`='有位来自烈酒村的信使今早抵达了这里。矮人们正派出一支巡山人小队来帮我们。', `FemaleText_loc5`='今天早上一位烈酒村的信差來到了我們這。矮人們將會派一隊巡山人來幫助我們。', `FemaleText_loc7`='Esta mañana ha llegado un mensajero de Las Birras.' WHERE `ID`=43117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산악경비대원들이 도착했을 때 크러쉬코그를 공격하려면 병력 배치가 완료되어 있어야 해요.', `MaleText_loc4`='当巡山人抵达时，我们必须做好对付碎轮的准备。', `MaleText_loc5`='當巡山人來到這時，我們必須已經準備好對碾輪發動進攻。', `MaleText_loc7`='Cuando los montaraces lleguen debemos estar en situación de golpear a Prensadiente.' WHERE `ID`=43118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크러쉬코그를 처치했으니 텔마플러그는 분명히 기계보행전차 안에서 벌벌 떨고 있을 거예요. 그럴 수밖에 없겠죠. 다음은 네놈 차례다, 텔마플러그. 네놈 차례야!', `MaleText_loc4`='打败碎轮之后，瑟玛普拉格肯定会立刻启动他的步行坦克。你的下一个目标就是瑟玛普拉格！下一个目标就是！', `MaleText_loc5`='碾輪被擊敗後，瑟瑪普拉格一定嚇得在他的機械坦克中發抖，活該!下個就是你，瑟瑪普拉格，就是你!', `MaleText_loc7`='¡Tras la derrota de Prensadiente, seguro que Termochufe está temblando dentro de su mecanotanque, como debe ser! ¡Ahora tú, Termochufe! ¡Ahora tú!' WHERE `ID`=43119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 판 붙을 준비 되셨나요?', `FemaleText_loc4`='准备好打斗了吗，$g小伙子:小姑娘;？', `FemaleText_loc5`='要打架了嗎，$G小子:小妞;?', `FemaleText_loc7`='¿$gListo:Lista; para una pelea $gmuchacho:muchacha;?' WHERE `ID`=43120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성가신 놈들 같으니! 우리가 그리 쉽게 꺾일 것 같으냐?', `FemaleText_loc4`='多管闲事的虫子们！你以为你能轻易地打败我们？', `FemaleText_loc5`='煩人的蟲子!你們以為這樣就贏了嗎?', `FemaleText_loc7`='¡Moscos entrometidos! ¿Creyeron que caeríamos tan fácilmente?' WHERE `ID`=43121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳건히 버텨라, 형제여! 놈을 조각내 버려라!', `MaleText_loc4`='坚守信念，兄弟们！浴血杀敌！', `MaleText_loc5`='絕不後退，兄弟們!給他們好看!', `MaleText_loc7`='¡Mantengan la posición, hermanos! ¡Que sangre!' WHERE `ID`=43122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지는 평화롭고 여유로운 곳이었다. 항상 생명이 넘쳤지. 천천히 움직였고, 절대 서두르는 법이 없었다. 이 시기에 난 대지와 하나가 되기로 했고, 어느 정도 성공하게 되었지.$B$B시간이 지나, 대지의 수호자가 부상을 당한 채 이곳에 돌아왔다. 처음에 그는 이곳의 균형을 깨지 않았다. 그는 이곳에 머문 적이 있었고, 우리도 그를 알고 있었으니. 본격적인 변화는 황혼의 망치단이 데스윙과 합류하면서 시작되었다.', `MaleText_loc4`='深岩之洲是个平静而节奏缓慢的地方。永远都充满生机，平稳改变，有条不紊。我一度努力与大地融为一体。在很大的程度上，我成功了。$B$B后来，大地的守卫者回来了，身上带着累累伤痕。起初他并没有扰乱平衡。他曾经在这里生活过，我们了解他。直到暮光教派开始和他打交道以后，他才真正开始发生了变化。', `MaleText_loc5`='地深之源原本是個步調緩慢而安靜的地方。活力十足。沈穩運作。永不急躁。在此時刻，我努力與大地合而為一，而整體而言，我也算成功了。$B$B後來，大地守護者回來了，而且身受重傷。他一開始並沒有破壞平衡。他曾經待過這裡，我們也都認識他。整個轉變直到暮光教派的人來加入他之後才開始。', `MaleText_loc7`='Infralar era un lugar tranquilo de ritmo lento. Siempre vivo. Siempre en movimiento. Pero sin prisas. En aquella época, yo deseaba llegar a ser uno con la tierra, y en gran medida, lo conseguí.$B$BMás tarde, el Guardián de la Tierra regresó, herido. Al principio no trastocó el equilibrio. Ya había venido aquí en otras ocasiones y le conocíamos. El cambio no comenzó de verdad hasta que el culto Crepuscular se unió a él.' WHERE `ID`=43123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 수호자는 여기서 몸을 추스르면서 이곳의 고요함, 이곳의 평화를 탐탁지 않아 했다. 얼마 지나지 않아 놈은 바위용들이 우리에게 맞서게 만들었지.$B$B이제 데스윙이 가버렸으니 바위용이 우리와 싸울 이유도 없어졌다. 그러니 그들에게 우리의 힘을 보여주고, 바위 어머니의 품으로 돌아오게 할 수 있을 것이다.', `MaleText_loc4`='当大地守护者逐渐恢复的时候，他开始不满足于这里的安静与和平。没过多久，他就驱使岩石巨龙攻击我们。$B$B死亡之翼离开之后，它们一直没有明确的目标。我们能够让它们明白我们的力量，再次将它们送回到大地母神的怀抱中。', `MaleText_loc5`='當大地守護者的傷勢逐漸恢復，他開始對此處的寧靜、對此處的祥和感到不滿。沒過多久，他便鼓動石龍來攻擊我們。$B$B而當死亡之翼離開之後，他們又再度迷失了目的。我們可以讓他們想起我們的力量，帶他們回歸石母的懷抱。', `MaleText_loc7`='Cuando el Guardián de la Tierra se recuperó, empezó a molestarle la tranquilidad. La paz. Y no pasó mucho tiempo hasta que volvió a los dragones de piedra contra nosotros.$B$BSin Alamuerte, esos dragones ya no tienen un propósito. Podemos recordarles nuestra fuerza. Devolverlos a la Madre Tierra.' WHERE `ID`=43124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 디아만트의 마음을 얻는 데 성공한 것 같군. 네가 지나가도록 허락하라는 명령을 받았다, 육체의 소유자여. 하지만 내 호의는 딱 거기까지다.$B$B우리가 처음 나눈 대화를 잊지 마라. 난 너를 깊이 신뢰하지 않는다. 너는 아직 증명할 게 많이 남았다.$B$B이제 떠나라. 움직일 때마다 발밑을 살피는 것도 이제 지겹다.', `MaleText_loc4`='所以我看到你已经向岱亚曼塔发出了诉求。我接受的命令是容忍你的出现，凡人。但我对你的接受程度也仅限于此。$B$B不要忘记我们的第一次交谈。要得到我的信任，你还需要做很多事。$B$B你最好先离开吧。我已经厌倦了每迈出一步都必须小心不要踩到你这种事。', `MaleText_loc5`='看來，你已經去找過戴門了。我被指示不得耽擱你的通行，肉身凡人。但是我對你的歡迎僅此為止。$B$B不要忘記我們的第一場對話。我對你的信任十分淺薄，你得證明的事情還很多。$B$B你還是趕緊離開吧，我已經厭倦了每走一步都得小心翼翼。', `MaleText_loc7`='Así que has llamado a Diamant. Me veo en la obligación de permitirte el paso, trozo de carne. Pero esa será toda la bienvenida que te daré.$B$BNo olvides nuestra primera conversación. Apenas confío en ti. Tienes mucho que demostrar.$B$BSerá mejor que te vayas. Me cansé de estar pendiente de dónde pongo los pies.' WHERE `ID`=43125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라오라고, 친구들! 조심해서 말이야...', `MaleText_loc4`='请登船，朋友们！小心……', `MaleText_loc5`='上船吧，朋友們!小心地...', `MaleText_loc7`='¡Suban a bordo, amigos! Con cuidado…' WHERE `ID`=43126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지, 모두 탔구먼. 좋아...', `MaleText_loc4`='都登船啦，这就对啦……', `MaleText_loc5`='好啦，全都上來了。這就對了...', `MaleText_loc7`='Eso, todos a bordo. Muy bien…' WHERE `ID`=43127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그리고, 우리 선원들 종족이 뭐랄까... 좀 다양한 건 눈감아 주게.', `MaleText_loc4`='请不要太在意……呃……我们船员的多样性。', `MaleText_loc5`='還有，別在意...呃...我們船員人種的多元化。', `MaleText_loc7`='Y, por favor, ignoren la... ehm... diversidad de nuestra tripulación.' WHERE `ID`=43128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편히 있으라고. 목적지까지 안전하게 데려가 줄 테니까.', `MaleText_loc4`='敬请放心。他们一定会把你们安全地送到目的地。', `MaleText_loc5`='不用擔心，他們一定會把你們安全送到目的地。', `MaleText_loc7`='Les aseguro que los llevarán a destino a salvo.' WHERE `ID`=43129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 왕국 연안에 떠오른 그 새로운 땅덩어리까지 말일세.', `MaleText_loc4`='那还是东部王国海岸边的处女地呢。', `MaleText_loc5`='那是東部王國沿岸的一片新大陸。', `MaleText_loc7`='El cual es esa tierra nueva junto a la costa de los Reinos del Este.' WHERE `ID`=43130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 좋았어. 모두 준비하라고... 이제 출발!', `MaleText_loc4`='好，大家坐稳啦……我们出发！', `MaleText_loc5`='好啦，大家坐穩了...上路了!', `MaleText_loc7`='Bien. Prepárense todos... ¡Aquí vamos!' WHERE `ID`=43131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤에서 돌 부딪치는 소리가 들립니다.', `MaleText_loc4`='从你身后传来了石头撞击的声音。', `MaleText_loc5`='你聽到背後傳來石頭翻動的聲音。', `MaleText_loc7`='Oyes un ruido de rocas desprendiéndose detrás de ti.' WHERE `ID`=43132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 신나게 방방 뜁니다.', `MaleText_loc4`='砾石佩波欢快地上下蹦跳着。', `MaleText_loc5`='小石岩高興地跳上跳下。', `MaleText_loc7`='Guijarro salta como un canguro feliz.' WHERE `ID`=43133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 신나게 이리저리 돌아다닙니다.', `MaleText_loc4`='砾石佩波在周围欢快地滑动着。', `MaleText_loc5`='小石岩高興地走來走去。', `MaleText_loc7`='Guijarro da vueltas feliz.' WHERE `ID`=43134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 주위를 돕니다. 신난 것 같습니다.', `MaleText_loc4`='砾石佩波不停地绕着圈，显得非常欢快。', `MaleText_loc5`='小石岩很高興地繞圈跑來跑去。', `MaleText_loc7`='Guijarro corre en círculos, lleno de felicidad.' WHERE `ID`=43135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 다가와 행복한 듯 당신의 다리에 기댑니다.', `MaleText_loc4`='砾石佩波快活地蹭着你的腿。', `MaleText_loc5`='小石岩高興地磨蹭著你的腿。', `MaleText_loc7`='Guijarro se arrima feliz a tu pierna.' WHERE `ID`=43136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 슬프게 내려앉습니다.', `MaleText_loc4`='砾石佩波伤心地趴了下去。', `MaleText_loc5`='小石岩難過地坐下。', `MaleText_loc7`='Guijarro se desploma triste.' WHERE `ID`=43137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 슬프게 등을 돌립니다.', `MaleText_loc4`='砾石佩波伤心地转过了身。', `MaleText_loc5`='小石岩難過地轉開。', `MaleText_loc7`='Guijarro se aparta triste.' WHERE `ID`=43138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 기대에 찬 눈빛으로 당신을 올려봅니다.', `MaleText_loc4`='砾石佩波充满希望地抬头看着你。', `MaleText_loc5`='小石岩用充滿希望的眼神看著你。', `MaleText_loc7`='Guijarro te mira esperanzado.' WHERE `ID`=43139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이 몸 안에서 돌 부딪치는 소리가 들립니다. 무언가에 흥분한 게 틀림없습니다.', `MaleText_loc4`='你听到砾石佩波体内石块的撞击声。他显得很是兴奋。', `MaleText_loc5`='你聽見小石岩的肚子裡有碎石子晃動的聲音。他顯然對某件事情很興奮。', `MaleText_loc7`='Oyes las piedras de Guijarro moviéndose en su interior. No hay duda de que está emocionado por algo.' WHERE `ID`=43140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이를 구성하는 돌들이 바닥으로 흩어지더니, 천천히 다시 모여 즐거운 돌돌이로 다시 태어납니다.', `MaleText_loc4`='砾石佩波的石块散落在地上，然后又慢慢地组合成一个完整的，快活的砾石佩波。', `MaleText_loc5`='小石塊散在地上到處都是，然後慢慢地重組成一個完整開心的小石岩。', `MaleText_loc7`='Las piedras de Guijarro explotan y se esparcen por el suelo. Poco a poco se convierte en un Guijarro feliz hecho y derecho.' WHERE `ID`=43141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 앞에 있는 수정을 보더니, 흥분해서 그곳으로 달려갑니다.', `MaleText_loc4`='砾石佩波看到前面的水晶，兴奋地向它们跑了过去！', `MaleText_loc5`='小石岩看見前方的水晶，興奮地衝了過去!', `MaleText_loc7`='Guijarro ve los cristales frente a él y corre emocionado hacia ellos.' WHERE `ID`=43142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 태세를 갖춰라!', `MaleText_loc4`='坚守不退！', `MaleText_loc5`='守住陣地!', `MaleText_loc7`='¡Mantengan la posición!' WHERE `ID`=43143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그들을 다시 땅속으로 돌려보내라!', `MaleText_loc4`='把这些石头穴居人赶回到地下去！', `MaleText_loc5`='把那些岩石穴居怪打回土裡面!', `MaleText_loc7`='¡Que esos troggs de piedra vuelvan a la tierra!' WHERE `ID`=43144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원병이 도착했다! 바위 아버지를 위하여!', `MaleText_loc4`='援军来了！为了国王而战！', `MaleText_loc5`='我們的增援來了!為了石父而戰!', `MaleText_loc7`='¡Tenemos refuerzos! ¡Por el Padre Pétreo!' WHERE `ID`=43145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천년만년 살겠다는 거냐?', `MaleText_loc4`='你想要永生不死吗？', `MaleText_loc5`='你想永遠活下去嗎?', `MaleText_loc7`='¿Quieres vivir eternamente?' WHERE `ID`=43146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='측면 방어를 보강하라!', `MaleText_loc4`='撑住侧翼！', `MaleText_loc5`='守住側翼!', `MaleText_loc7`='¡Apuntalad esos flancos!' WHERE `ID`=43147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 돌난로다!', `MaleText_loc4`='这就是巨石之炉！', `MaleText_loc5`='這『就是』石爐!', `MaleText_loc7`='¡Esto es el Hogar Pétreo!' WHERE `ID`=43148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카즈고로스 님의 망치로, 우리는 적을 박살내리라!', `MaleText_loc4`='以卡兹格罗斯的铁锤起誓，我们一定要消灭他们！', `MaleText_loc5`='卡茲格羅斯的錘子啊，我們要擊潰他們!', `MaleText_loc7`='¡Por el martillo de Khaz''goroth, los derribaremos!' WHERE `ID`=43149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 아버지 오어맨틀 님을 위하여!', `MaleText_loc4`='为了岩幔国王！', `MaleText_loc5`='為石父礦被而戰!', `MaleText_loc7`='¡Por el Padre Pétreo Mantomena!' WHERE `ID`=43150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 공격을 받고 있으면 의식을 진행할 수 없습니다!', `MaleText_loc4`='我没法在他们进攻的时候干这事儿！', `MaleText_loc5`='我沒辦法在他們攻擊我的時候進行這件事!', `MaleText_loc7`='¡No puedo hacerlo si me están atacando!' WHERE `ID`=43151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 낙석을 소환할 수 있게 이 바위 트로그들을 처리해 주십시오!', `MaleText_loc4`='把这些石头穴居人赶走，这样我才能召唤岩石崩落！', `MaleText_loc5`='讓這些岩石穴居怪離我遠點，讓我可以召喚落石!', `MaleText_loc7`='¡Sácame de encima a estos troggs para que pueda invocar el desprendimiento de rocas!' WHERE `ID`=43152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 공격을 당하면 의식을 수행할 수 없습니다.', `MaleText_loc4`='我没法在他们攻击我的时候继续进行仪式！', `MaleText_loc5`='我無法在他們攻擊我的時候進行儀式!', `MaleText_loc7`='¡No puedo realizar el ritual si me están pegando!' WHERE `ID`=43153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석들을 먼저 좀 처리해 주시겠습니까, $c 친구여?', `MaleText_loc4`='$c，能不能先帮个小忙？', `MaleText_loc5`='先幫點忙好嗎，$c?', `MaleText_loc7`='¿Ayúdame aquí primero, $c?' WHERE `ID`=43154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바위 트로그들을 해치운 다음에 시약을 제게 주십시오.', `MaleText_loc4`='等这些石头穴居人死掉之后，再把那些试剂给我。', `MaleText_loc5`='等這些岩石穴居怪都死光了，把藥材再給我一次。', `MaleText_loc7`='Vuelve a darme los componentes cuando esos troggs de piedra estén muertos.' WHERE `ID`=43155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 절 공격하지 못하고 막아 주십시오. 그동안에 전 입구를 봉인하겠습니다.', `MaleText_loc4`='别让他们打到我，然后我才能封住这个缺口！', `MaleText_loc5`='別讓他們攻擊到我，我就會把開口封起來!', `MaleText_loc7`='¡Haz que dejen de atacarme y sellaré la escotilla!' WHERE `ID`=43156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 어떻게 땅 밑에서 나타날 생각을 했는진 모르겠지만, 일단 놈들을 떼어 놓아야 입구를 봉인할 수 있습니다.', `MaleText_loc4`='我不知道他们是怎样从下面上来的。但如果不将他们击退，我就没办法把这个缺口封住！', `MaleText_loc5`='我不知道他們是從哪找到上來的路的，但不讓他們遠離我我是無法把這封起來的!', `MaleText_loc7`='¡No sé cómo encontraron el camino a la superficie, pero no puedo sellar la escotilla si los tengo encima!' WHERE `ID`=43157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바위 트로그들을 먼저 처리해야 합니다. 그다음에 시약을 제게 주십시오.', `MaleText_loc4`='我们必须先击退这些石头穴居人。然后再把那些试剂给我。', `MaleText_loc5`='我們得先解決掉這些岩石穴居怪，然後再把材料給我。', `MaleText_loc7`='Tenemos que encargarnos de los troggs de piedra primero. Después, échame una mano con los componentes.' WHERE `ID`=43158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 고맙다는 듯 고개를 까닥까닥합니다.', `MaleText_loc4`='砾石佩波感激地来回蹦跳着。', `MaleText_loc5`='小石岩感激地跳來跳去。', `MaleText_loc7`='Guijarro salta a tu alrededor agradecido.' WHERE `ID`=43159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 아버지를 위하여!', `MaleText_loc4`='为了国王！', `MaleText_loc5`='石父萬歲!', `MaleText_loc7`='¡Por el Padre Pétreo!' WHERE `ID`=43160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 아버지 오어맨틀 님을 위하여!', `MaleText_loc4`='为了岩幔国王！', `MaleText_loc5`='為了石父礦被!', `MaleText_loc7`='¡Por el Padre Pétreo Mantomena!' WHERE `ID`=43161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌난로를 위하여!', `MaleText_loc4`='为了巨石之炉！', `MaleText_loc5`='為石爐而戰!', `MaleText_loc7`='¡Por el Hogar Pétreo!' WHERE `ID`=43162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그를 처치하라!', `MaleText_loc4`='消灭石头穴居人！', `MaleText_loc5`='殺死岩石穴居怪!', `MaleText_loc7`='¡Maten a los troggs de piedra!' WHERE `ID`=43163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 파수대장 파커 님을 만나보시기 바랍니다. 지금 이 탑 꼭대기에 계십니다.', `MaleText_loc4`='感恩吧，公民。我推荐你去见卫兵帕克。他就在这座塔的顶上。', `MaleText_loc5`='你好，市民。我建議你去找警衛隊長派克談談。他目前就在這座塔的樓頂上。', `MaleText_loc7`='Saludos, ciudadano. Te recomendaría que hables con el capitán de la Avanzada Parker. Está en lo alto de esta torre.' WHERE `ID`=43164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 너무 흥분한 나머지 근처 바위갈퀴의 눈에 띄었습니다!', `MaleText_loc4`='兴奋的砾石佩波引起了附近剥石者的注意！', `MaleText_loc5`='小石岩興奮的表現吸引到了附近鐮奪怪的注意!', `MaleText_loc7`='¡La emoción de Guijarro ha llamado la atención de los despellejadores de roca!' WHERE `ID`=43165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 오우거 씨. 전부 불지 않으면 뼈저리게 후회할 거야!', `FemaleText_loc4`='好了，宝贝儿。快把你知道的都说出来，别逼我动手！', `FemaleText_loc5`='好啦，小可愛，該是時候告訴我我想知道的，不要讓我逼你說出來!', `FemaleText_loc7`='Bien, solcito. ¡Habla o te destripo!' WHERE `ID`=43166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 이럴 순 없어! 너희한텐 명예의 규약인가 뭔가 하는 게 있잖아!', `MaleText_loc4`='等等！你不能这么做！你们总得有点儿荣誉感还是什么的！', `MaleText_loc5`='等一下!你不能這樣做!你們這些人一定有榮譽感之類的東西!', `MaleText_loc7`='¡Esperen! ¡No lo hagan! ¿Acaso su gente no tiene un código de honor o algo?' WHERE `ID`=43167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 위대한 와일드해머 부족의 일원이자 대지 고리회 주술사이다. 우리 조상님과 원소를 존중하는 규약을 따르지.', `FemaleText_loc4`='我是蛮锤部族的女儿，大地之环的萨满祭司。我的信条迫使我捍卫祖先与元素的荣耀。', `FemaleText_loc5`='我是蠻錘氏族之女和陶土議會的薩滿。我的規範促使我必須為先祖和元素帶來榮耀。', `FemaleText_loc7`='Soy una hija del Clan Martillo Salvaje y chamán del Anillo de la Tierra. Mi código me obliga a honrar a mis antepasados y a los elementos.' WHERE `ID`=43168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='못생긴 오우거에 대한 존중 따윈 없어.', `FemaleText_loc4`='别胡扯那些有关脏垢食人魔的事。', `FemaleText_loc5`='完全沒提跟那些醜陋巨魔有關的半個字。', `FemaleText_loc7`='No dice ni una palabra sobre ogros repugnantes.' WHERE `ID`=43169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 세계 기둥 파편이 있는 곳부터 불어 봐. 널 끌고 다니느라 그리핀도 좀 지쳐 보이니까 말이야.', `FemaleText_loc4`='你可以从世界之柱碎片的下落开始说。带着你这个胖子飞了这么长的时间，我的狮鹫看上去有点儿累了。', `FemaleText_loc5`='你可以先跟我們說世界之柱碎片在哪。我的獅鷲獸載你飛來飛去已經有點累了。', `FemaleText_loc7`='Comienza diciéndome dónde está el fragmento del Pilar Mundial. Mi grifo se está cansando de llevarte de aquí para allá.' WHERE `ID`=43170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만둬, 이 작고 무서운 여자야! 전부 다 얘기할게. 뭐가 알고 싶지?', `MaleText_loc4`='快住手，你这狂暴的小女人！我把一切都告诉你！你想知道什么？', `MaleText_loc5`='住手，你這脾氣差的小不點女人!我會全部都跟你說!你想知道什麼?', `MaleText_loc7`='¡Basta, mujercita enojada! ¡Te diré todo! ¿Qué quieres saber?' WHERE `ID`=43171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙의 몰락지에 있는 제련장인에게 전달됐어. 내가 아는 건 그게 다야!', `MaleText_loc4`='它被送到了死亡之翼的陨落地，交到了铸炉之主的手里。我就知道这么多了！', `MaleText_loc5`='已經送到死翼之殞的鍛造大師那了。我發誓，我只知道這麼多!', `MaleText_loc7`='Se le entregó al maestro de forja tras la Caída de Alamuerte. ¡Lo juro, es todo lo que sé!' WHERE `ID`=43172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가... 제발... 이... 바위를... 치워... 주시오...', `MaleText_loc4`='有人吗……请……把……这块……石头……挪开……', `MaleText_loc5`='拜託...誰來...把我...身上的...石頭...弄掉...', `MaleText_loc7`='Alguien... puede... sacarme... esa... roca...' WHERE `ID`=43173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아파... 너무 아파...', `MaleText_loc4`='疼啊……真是太疼了……', `MaleText_loc5`='好痛...真的好痛...', `MaleText_loc7`='Duele... duele mucho...' WHERE `ID`=43174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 날... 죽여 주시오...', `MaleText_loc4`='请……杀死……我……', `MaleText_loc5`='拜託...請你...殺了我...', `MaleText_loc7`='Matadme...' WHERE `ID`=43175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 빌어먹을... 다리를... 만들고 싶었을... 뿐인데...', `MaleText_loc4`='我……只……想……建好……这座……该死的……桥……', `MaleText_loc5`='我...只是...想把...該死的...橋...給...造好...', `MaleText_loc7`='Solo... quería... construir... el... maldito... puente...' WHERE `ID`=43176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무서울 게 뭐가 있다고. 떨어져도 아래에 있는 친구들이 받아 줬을 텐데. 널 살려 둬야 우리한테 유리하거든!', `FemaleText_loc4`='你从来没有生命危险，宝贝儿。我朋友在下面会接住你的。你活着对我们的价值可太大了！', `FemaleText_loc5`='從來不曾危險過，甜心。我下面的朋友也會接住你。活著的你對我們的價值太高了!', `FemaleText_loc7`='Nunca estuviste en peligro, corazón. Mis amigos allí abajo te habrían atrapado. ¡Te necesitamos con vida!' WHERE `ID`=43177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 됐지? 올려 줘, 이 피도 눈물도 없는 드워프야!', `MaleText_loc4`='满意了吗？快把我拉起来，你这凶残的矮子！', `MaleText_loc5`='高興了嗎?拉我上去，你這惡毒的小矮人!', `MaleText_loc7`='¿Estás contento? ¡Levántame, enano maldito!' WHERE `ID`=43178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 무슨 짓을 한 거야! 안 돼! 내가 무슨 말을 했는지 황혼의 의회에서 알면 가만있지 않을 거라고! 차라리 죽어버리는 게 나아!', `MaleText_loc4`='什么？不……你都干了什么？不，你知不知道要是暮光议会发现我开了口，我会有什么下场？我宁可早点死！', `MaleText_loc5`='什麼?你做了什麼?不!你知道要是暮光議會知道我說了這些會怎樣嗎?我寧可自己去死!', `MaleText_loc7`='¿Qué? ¿Qué han hecho? ¡No! ¡¿Se dan cuenta de lo que me hará el Consejo Crepuscular cuando sepa que hablé?! ¡Será peor que la muerte!' WHERE `ID`=43179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거 참 흥미롭군요. 황혼의 의회는 처음 듣는 이름이에요.', `FemaleText_loc4`='有趣。在这以前我还从来没听说过暮光议会。', `FemaleText_loc5`='有意思。我之前完全沒有聽說過暮光議會。', `FemaleText_loc7`='Qué interesante. Nunca había oído hablar del Consejo Crepuscular.' WHERE `ID`=43180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 등을 붙이고 밀 준비를 해!', `MaleText_loc4`='把你们的后背靠上去，孩子们！', `MaleText_loc5`='弟兄們，把背靠上去，準備使勁!', `MaleText_loc7`='¡Esforzaos al máximo, chicos!' WHERE `ID`=43181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀어!', `MaleText_loc4`='用力！', `MaleText_loc5`='抬!', `MaleText_loc7`='¡EMPUJAD!' WHERE `ID`=43182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영차!', `MaleText_loc4`='嚯！', `MaleText_loc5`='啊!', `MaleText_loc7`='¡AY!' WHERE `ID`=43183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 바위가 꿈쩍도 안 해!', `MaleText_loc4`='该死的石头，就是不动！', `MaleText_loc5`='該死的岩石動也不動!', `MaleText_loc7`='¡MALDITA ROCA, MUÉVETE!' WHERE `ID`=43184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 세게 밀어!', `MaleText_loc4`='继续用力！', `MaleText_loc5`='再加把勁!', `MaleText_loc7`='¡EMPUJAD CON FUERZA!' WHERE `ID`=43185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 힘을 다해 밀고 있다고! 이 바위 정말 엄청나게 무거워!', `MaleText_loc4`='我已经拼尽全力了！这东西肯定有一吨重！', `MaleText_loc5`='我已經使出全力了!這東西有沒有一噸重啊!', `MaleText_loc7`='¡EMPUJO LO MÁS FUERTE QUE PUEDO! ¡PESA UNA TONELADA!' WHERE `ID`=43186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독님, 꼭 꺼내 드릴게요! 잠깐만 버텨요!', `MaleText_loc4`='我们救你出来的，工头。坚持住！', `MaleText_loc5`='我們會救你出來的，工頭，忍住啊!', `MaleText_loc7`='¡Te sacaremos de aquí, supervisor, solo AGUANTA!' WHERE `ID`=43187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닷가로 가는 거요, $n?$B$B말만 하면 내가 배를 하나 내려 주겠소.', `MaleText_loc4`='$n，要去岸边？$B$B只要你说一声，我就会为你放下一艘小船。', `MaleText_loc5`='要上岸嗎，$n?$B$B告訴我一聲，我就幫你放船下去。', `MaleText_loc7`='¿Hora de desembarcar, $n?$B$BDilo y echaré al agua un bote para ti.' WHERE `ID`=43188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닷가로 보내 주십시오, 호조그.', `MaleText_loc4`='送我去岸边，霍尔佐格。', `MaleText_loc5`='送我到岸上，荷索格。', `MaleText_loc7`='Envíame a tierra, Horzog.', `FemaleText_loc1`='바닷가로 보내 주세요, 호조그.', `FemaleText_loc4`='送我去岸边，霍尔佐格。', `FemaleText_loc5`='送我到岸上，荷索格。', `FemaleText_loc7`='Envíame a tierra, Horzog.' WHERE `ID`=43189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 상황이 좋지 않군요. 전투 때문에 증기 전차 두 대 모두 심각하게 부서졌어요. 주변이 안전해지면 제 구조대원들이 잔해를 확보할 거예요.', `MaleText_loc4`='嗯，这并不好。你的两辆蒸汽坦克都在战斗中损毁了。我的搜救队在确认安全之后就会把它们的残骸取回来。', `MaleText_loc5`='唉，狀況不妙。戰鬥對你的兩架蒸汽坦克都造成了相當的損耗。等狀況變安全之後，我的回收隊就會立刻去回收。', `MaleText_loc7`='Vaya, eso no es bueno. La batalla ha dejado mella en tus dos tanques de vapor. Mis equipos de recate se encargarán de lo que queda de ellos en cuanto sea seguro.' WHERE `ID`=43190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이로 기어도 충분하니까 기술자들이 힘을 합치면 전차를 완벽하게 수리할 수 있어요. 시간은 좀 걸리겠지만요.', `MaleText_loc4`='只要有足够的配件和一支工程师队伍，你的坦克就能得到彻底修复。但这还需要很长一段时间。', `MaleText_loc5`='只要有充足的協動齒輪零件，還有優秀的工程師團隊，你的坦克肯定可以完全修復，只是會花上好一段時間。', `MaleText_loc7`='Con un suministro amplio de engranajes giromecánicos y un equipo de ingenieros, tus tanques pueden recuperarse del todo, pero será un largo trayecto.' WHERE `ID`=43191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 트롤플로우. 그래도 나가서 자기가 좋아하던 일을 하다 그렇게 됐으니 어쩌겠어...', `MaleText_loc4`='可怜的巨魔碾压者。至少这个老女孩竭尽全力做了一件她喜爱的事情。', `MaleText_loc5`='可憐的崔爾波勞。至少老傢伙是在做她喜歡的事情的時候走的。', `MaleText_loc7`='Pobre Potenciatrol. Al menos la vieja chica se fue haciendo lo que le gustaba.' WHERE `ID`=43192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하게, 스톤! 자네는 증기 전차 조종사란 말이야! 제발 좀!', `MaleText_loc4`='振作起来，石轮！你是一名蒸汽坦克驾驶员，为圣光而战！', `MaleText_loc5`='振作一點，阿石!你是一個蒸汽坦克的駕駛啊，拜託!', `MaleText_loc7`='¡Recomponte, Rosco! ¡Eres un piloto de tanques de vapor, por el nombre de la Luz!' WHERE `ID`=43193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리 국왕 폐하를 포로로 삼다니!$B$B돌난로를 되찾은 다음, 전초지를 가로질러 적진에 있는 바위 트로그들을 쓸어 버리겠다!', `MaleText_loc4`='他们怎么敢囚禁我们的国王！$B$B我们要夺回巨石之炉，然后将战线推进到石头穴居人的老窝，在那里彻底粉碎他们！', `MaleText_loc5`='他們竟敢虜走我們的國王為囚!$B$B我們必定會奪回石爐，然後突破前線，在岩石穴居怪的地盤上擊垮他們!', `MaleText_loc7`='¡Cómo se atreven a hacer prisionero a nuestro Rey!$B$B¡Recuperaremos el Hogar Pétreo y entonces avanzaremos por el frente de batalla para aplastar a los troggs de piedra en su hogar!' WHERE `ID`=43194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호조그가 상륙정을 내리라고 명령합니다.', `MaleText_loc4`='霍尔佐格下令将一艘登陆艇放进水中。', `MaleText_loc5`='荷索格下令將一艘登陸艇降到水上。', `MaleText_loc7`='Horzog ordena que se eche al agua un esquife.' WHERE `ID`=43195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=43196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가서 저 바위 트로그들을 다시 땅속으로 돌려 보내세, $r 친구!', `MaleText_loc4`='让我们从这里出去，把那些石头穴居人赶回到地底去，$r！', `MaleText_loc5`='讓我們離開這裡，去把那些岩石穴居怪打回土裡，$r!', `MaleText_loc7`='¡Salgamos de aquí y hagamos que esos troggs de piedra vuelvan a la tierra, $r!' WHERE `ID`=43197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라즐, 이 친구에게 다 괜찮을 거라고 말해주게!', `MaleText_loc4`='拉兹，告诉他一切都会好起来的！', `MaleText_loc5`='拉索，跟他說一切都沒問題!', `MaleText_loc7`='¡Razzle, dile que todo va a ir bien!' WHERE `ID`=43198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 최전선에 가 주어야겠네, $n.$B$B자네라면 상황을 반전시킬 수 있을 거야. 우린 바위 트로그들을 박멸할 것이네.$B$B오어맨틀 국왕 폐하를 구출해야 하네!', `MaleText_loc4`='我需要你上阵支援我，$n。$B$B你将使战局产生逆转。我们将一举击溃石头穴居人。$B$B我们必须救出岩幔国王！', `MaleText_loc5`='我需要你到前線去，$n。$B$B你可以幫我們扭轉戰局，我們會徹底擊垮岩石穴居怪。$B$B我們一定要救出礦被國王!', `MaleText_loc7`='Te necesito en el frente, $n.$B$BTú marcarás la diferencia. Aplastaremos a los troggs de piedra de una vez por todas.$B$B¡Debemos rescatar al rey Mantomena!' WHERE `ID`=43199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요, 정말 다 괜찮을 거예요. 사실 더 좋은 일이죠. 트롤플로우는 예전보다 훨씬 더 좋아질 테니까요.', `MaleText_loc4`='是的，是的，一切都会好起来的！会变得非常好。她会比以往任何时候都更好！', `MaleText_loc5`='是，是，一切都沒問題!其實是太棒了!她會比以前還要好!', `MaleText_loc7`='¡Sí, sí, todo estará bien! Estupendamente, de hecho. ¡Estará mejor que nunca!' WHERE `ID`=43200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<투덜대며 코웃음 치는 클레이>$B$B하여간 요즘 젊은 것들은.', `MaleText_loc4`='<克莱嘟囔着，冷笑着。>$B$B这个该死的时代。', `MaleText_loc5`='<克雷悶哼獰笑。>$B$B該死的小鬼。', `MaleText_loc7`='<Berilo se queja y sonríe con desdén.>$B$B¡Malditos niños de hoy en día!' WHERE `ID`=43201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 저는 어서 저 기어들을 준비하러 가야겠어요!', `MaleText_loc4`='好了，我立刻就去看看那些装备！', `MaleText_loc5`='事實上，我現在就要去找找那些齒輪!', `MaleText_loc7`='¡De hecho, voy a echarle un ojo a esos engranajes ahora mismo!' WHERE `ID`=43202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 봤지? 낡은 트롤플로우는 더 좋아질 거라고! 곧 자네는 또 나보다 더 좋은 증기 전차를 가졌다고 자랑을 늘어놓을 테고 말이야...', `MaleText_loc4`='看到了吗？老巨魔碾压者很快就会好起来的！用不了多久，你就又会吹牛说赢过我了……', `MaleText_loc5`='看吧!老崔爾波勞很快就會好起來了!要不了多久...你就又可以炫耀你的槍法比我準了...', `MaleText_loc7`='¿Ves? ¡La vieja Potenciatrol estará mejor en un santiamén! Antes de que te des cuenta, estarás de nuevo recochineándome que eres mejor que yo...' WHERE `ID`=43203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오게. 에일 맥주나 한 잔 더 하자고.', `MaleText_loc4`='好了，再来一杯啤酒吧。', `MaleText_loc5`='好啦，你再來一杯吧。', `MaleText_loc7`='Vamos, a por otra cerveza para ti.' WHERE `ID`=43204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식이 끝나는 대로 마날 님이 도착하실 거야. 내 동료들이 이 역겨운 괴물의 뒤처리를 도울 거고.', `MaleText_loc4`='等到仪式完成的时候，玛尔纳就会到来。我的人会帮忙塑造出这个奇异的怪物。', `MaleText_loc5`='等儀式完成的時候，馬爾諾就會抵達，然後我的手下們會一起幫忙砍死這隻怪物。', `MaleText_loc7`='Cuando el ritual esté completo, Marnal llegará y mis hombres ayudarán a acabar con esta grotesca criatura.' WHERE `ID`=43206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 지금까지 본 모든 승강기 중 가장 놀라운 걸 상상해 보라고... 그게 바로 이거야. 그래, 멋있지, 응? 하지만... 슬프게도 아직은 작동이 안 된다고.', `MaleText_loc4`='想象一下最令人惊叹的升降机会是什么样子……它就在这里。很漂亮，不是么？糟糕的是，它还没有准备好。', `MaleText_loc5`='想像你所見過最驚人的電梯...就在這裡。對，很棒吧，對不對?遺憾的是，它還沒有弄好。', `MaleText_loc7`='Imagina el elevador más increíble del mundo... justo ahí. Sí, ¿no está mal, eh? Por desgracia, aún no está listo.' WHERE `ID`=43207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단은 그냥 순간이동 시켜주십시오. 하지만 승강기가 정말로 기대되는군요!', `MaleText_loc4`='现在就传送我。我已经等不及使用那个漂亮的升降机了！', `MaleText_loc5`='現在傳送我就對了。但是我等不及那個寶貝電梯了!', `MaleText_loc7`='Por ahora solo teletranspórtame. ¡Pero estoy impaciente por ver ese increíble elevador!', `FemaleText_loc1`='일단은 그냥 순간이동 시켜주세요. 하지만 승강기가 정말로 기대되는군요!', `FemaleText_loc4`='现在就传送我。我已经等不及使用那个漂亮的升降机了！', `FemaleText_loc5`='現在傳送我就對了。但是我等不及那個寶貝電梯了!', `FemaleText_loc7`='Por ahora solo teletranspórtame. ¡Pero estoy impaciente por ver ese increíble elevador!' WHERE `ID`=43208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내를 가지게... 곧 우리 차례가 올 걸세.', `MaleText_loc4`='耐心……我们的机会就要来了。', `MaleText_loc5`='耐心點...會輪到我們的。', `MaleText_loc7`='Paciencia... Nuestro turno llegará.' WHERE `ID`=43209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<갈증 난다는 얼굴로 당신을 빤히 쳐다보는 멀록>', `MaleText_loc4`='<鱼人用饥渴的眼睛看着你。>', `MaleText_loc5`='<魚人以飢渴的眼神看著你。>', `MaleText_loc7`='<El múrloc te mira con ojos sedientos.>' WHERE `ID`=43210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<멀록에게 청량음료를 줍니다.>', `MaleText_loc4`='<给这个鱼人一些喝的。>', `MaleText_loc5`='<給魚人一杯酒。>', `MaleText_loc7`='<Ofrécele una bebida al múrloc.>', `FemaleText_loc1`='<멀록에게 청량음료를 줍니다.>', `FemaleText_loc4`='<给这个鱼人一些喝的。>', `FemaleText_loc5`='<給魚人一杯酒。>', `FemaleText_loc7`='<Ofrécele una bebida al múrloc.>' WHERE `ID`=43211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R 오르구스 보러 왔나? 사진 찍어라, 기억에 오래 남는다.', `MaleText_loc4`='$R来看奥古斯？照相，待久一些。', `MaleText_loc5`='$R來看奧古斯嗎?拍張照，可以看更久。', `MaleText_loc7`='$R, ¿vienes a ver a Orgus? Una foto dura más.' WHERE `ID`=43212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<오우거에게 청량음료를 줍니다.>', `MaleText_loc4`='<给这个食人魔一些喝的。>', `MaleText_loc5`='<給巨魔一杯酒。>', `MaleText_loc7`='<Ofrécele una bebida al ogro.>', `FemaleText_loc1`='<오우거에게 청량음료를 줍니다.>', `FemaleText_loc4`='<给这个食人魔一些喝的。>', `FemaleText_loc5`='<給巨魔一杯酒。>', `FemaleText_loc7`='<Ofrécele una bebida al ogro.>' WHERE `ID`=43213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 어떤 영혼이 나보다 더 목이 마르랴.', `MaleText_loc4`='呀，谁也不会有我这样渴。', `MaleText_loc5`='我說啊，沒有比我更渴的人啦，耶。', `MaleText_loc7`='Jarrr, aquí no hay nadie más sediento, que yo, señol.' WHERE `ID`=43214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<해적에게 청량음료를 줍니다.>', `MaleText_loc4`='<给这个海盗一些喝的。>', `MaleText_loc5`='<給海盜一杯酒。>', `MaleText_loc7`='<Ofrécele una bebida al pirata.>', `FemaleText_loc1`='<해적에게 청량음료를 줍니다.>', `FemaleText_loc4`='<给这个海盗一些喝的。>', `FemaleText_loc5`='<給海盜一杯酒。>', `FemaleText_loc7`='<Ofrécele una bebida al pirata.>' WHERE `ID`=43215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 우리 세계로 들어오면서 아제로스와 심원의 영지 사이에 균열이 생겼다네.$B$B세계 기둥을 복원하는 것이야말로 균열을 안정시킬 유일한 방법이네.', `MaleText_loc4`='死亡之翼的侵入在我们的世界和深岩之洲之间打开了一道裂隙。$B$B重建世界之柱是唯一控制住裂隙的方法。', `MaleText_loc5`='死亡之翼重返我們世界的時候，在地深之源與艾澤拉斯之間撕開了一道裂隙。$B$B重建世界之柱是唯一能穩定住這道裂隙的方法。', `MaleText_loc7`='La entrada de Alamuerte en nuestro mundo abrió una fisura entre este e Infralar.$B$BLa única forma de estabilizar la fisura es volver a construir el Pilar del Mundo.' WHERE `ID`=43216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협상이 제대로 되고 있지 않습니다, $n 님. 용아귀 부족은 아직 진정 자유로운 오크라고 할 수 없어요.$B$B어떻게든 그들이 호드에 들어오게 해야 합니다!$B$B함대로 다시 돌아가려면 이야기하십시오.', `MaleText_loc4`='谈判进展得并不顺利，$n。龙喉氏族还不是意志自由的兽人。$B$B不管怎样，我们必须争取他们加入部落！$B$B如果你要返回舰队，就告诉我。', `MaleText_loc5`='協商進行得並不順利，$n。龍喉獸人仍未獲得自由。$B$B但是，我們『一定』要叫他們加入部落!$B$B你想回到船艦上的時候就告訴我一聲。', `MaleText_loc7`='Las negociaciones no han ido bien, $n. Los Faucedraco aún no son orcos libres.$B$BDe alguna forma, ¡tenemos que hacer que se unan a la Horda!$B$BSi necesitas un transporte de vuelta a la flota, házmelo saber.' WHERE `ID`=43217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 하나도 안 무거워! 인간들 약해빠졌어!', `MaleText_loc4`='石头没有多重！小人类！', `MaleText_loc5`='石頭沒有很重!小人類!', `MaleText_loc7`='¡ROCA NO PESAR TANTO! ¡HUMANOS FLOJOS!' WHERE `ID`=43218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함대로 돌아가게 해주시겠습니까?', `MaleText_loc4`='能给我一艘船返回舰队么？', `MaleText_loc5`='可以送我回船艦上嗎?', `MaleText_loc7`='¿Puedo volver a la flota?', `FemaleText_loc1`='함대로 돌아가게 해주시겠어요?', `FemaleText_loc4`='能给我一艘船返回舰队么？', `FemaleText_loc5`='可以送我回船艦上嗎?', `FemaleText_loc7`='¿Puedo volver a la flota?' WHERE `ID`=43219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 던져? 다리에 던져?', `MaleText_loc4`='扔去哪儿？扔到桥上？', `MaleText_loc5`='丟哪裡?丟橋上??', `MaleText_loc7`='¿Dónde lanzar? ¿LANZAR A PUENTE?' WHERE `ID`=43220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무르글이 당신을 따라오기 시작합니다.', `MaleText_loc4`='古穆尔格要跟随你。', `MaleText_loc5`='葛穆格開始跟著你。', `MaleText_loc7`='Gmurgl empieza a seguirte.' WHERE `ID`=43221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어! 물속에 던질게!', `MaleText_loc4`='好吧！扔到水里！', `MaleText_loc5`='好!我丟水裡!', `MaleText_loc7`='¡Vale! ¡Lanzar a agua!' WHERE `ID`=43222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르낙이 당신이 함대로 타고 갈 배를 내줍니다.', `MaleText_loc4`='欧纳克下令让一艘小艇去舰队。', `MaleText_loc5`='奧納克下令一艘小艇離岸划向艦隊。', `MaleText_loc7`='Ornak ordena que se suelte un esquife para volver a la flota.' WHERE `ID`=43223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 오르구스 속 안 좋다...', `MaleText_loc4`='哦……奥古斯觉得不太好……', `MaleText_loc5`='噢...奧古斯覺得不舒服...', `MaleText_loc7`='Oh... Orgus no se sentirse bien...' WHERE `ID`=43224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이;가; 준 청량음료가 뭔가 이상하다...', `MaleText_loc4`='奥古斯觉得$r柠檬水有问题……', `MaleText_loc5`='奧古斯覺得$r檸檬汁有問題...', `MaleText_loc7`='Orgus creer que algo malo con limonada de $r...' WHERE `ID`=43225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 안녕, 아빠!', `MaleText_loc4`='再见，爸爸！', `MaleText_loc5`='再見，爹地!', `MaleText_loc7`='¡CHAO, CHAO, PAPI!' WHERE `ID`=43226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 풋내기 불한당 주제에 이런 음료를 가져오다니!', `MaleText_loc4`='该死的！这个旱鸭子无赖来拿朗姆酒了！', `MaleText_loc5`='轟掉他們!旱鴨子無賴鬼有酒啊!', `MaleText_loc7`='¡Será posible! ¡El maldito rufián de agua dulce trae ron!' WHERE `ID`=43227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?', `MaleText_loc4`='什么？', `MaleText_loc5`='啊?', `MaleText_loc7`='¿Yarr?' WHERE `ID`=43228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 빌어먹을!', `MaleText_loc4`='天哪！', `MaleText_loc5`='我的媽啊!', `MaleText_loc7`='¡Que me parta un rayo!' WHERE `ID`=43229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안돼! 안돼! 제발!', `MaleText_loc4`='不，不，不！求求你！', `MaleText_loc5`='不、不，不!求求你!', `MaleText_loc7`='¡NO, NO, NO! ¡Por favor!' WHERE `ID`=43230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애애!!!', `MaleText_loc4`='不！！！', `MaleText_loc5`='不——!!!', `MaleText_loc7`='¡¡¡NOOOOOO!!!' WHERE `ID`=43231;
