UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 갈 거야, 친구?', `MaleText_loc4`='去哪里，朋友？', `MaleText_loc5`='要去哪裡，兄弟?', `MaleText_loc7`='¿Adónde, amigo?', `FemaleText_loc1`='어디로 가시겠어요?', `FemaleText_loc4`='去哪里，朋友？', `FemaleText_loc5`='要去哪裡，兄弟?', `FemaleText_loc7`='¿Adónde, amigo?' WHERE `ID`=43233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닷가로 가는 배가 필요하다면 이쪽으로 오시오, $n!', `MaleText_loc4`='如果你需要一艘小艇去岸边，就来找我，$n！', `MaleText_loc5`='要搭船去岸上就來找我，$n!', `MaleText_loc7`='¡Ven a verme si necesitas un esquife para ir a la orilla, $n!' WHERE `ID`=43234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리갈기 트롤과의 전투가 교착상태에 빠져가고 있네.', `MaleText_loc4`='我们已经陷在和霜鬃巨魔的战斗中了。', `MaleText_loc5`='我們和霜鬃食人妖之間的戰鬥陷入了僵局。', `MaleText_loc7`='Nos estamos atascando en la lucha contra los trols Peloescarcha.' WHERE `ID`=43235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증기 전차 대부분이 작동하지 않아서 산악경비대원들을 많이 잃고 있다네.', `MaleText_loc4`='我们的大多数蒸汽坦克都已经无法使用，而且我们的山地作战人员也损失惨重。', `MaleText_loc5`='我們大部份的蒸汽坦克都已經無法使用了，巡山者的數量也在快速的減少。', `MaleText_loc7`='La mayoría de nuestros tanques de vapor están fuera de servicio y estamos perdiendo montaraces rápidamente.' WHERE `ID`=43236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠다, 잴라. 넌 언제나 옳은 행동을 하지... $C|1이여;여;, 부상당한 전사들을 도와주겠소...', `MaleText_loc4`='很好，扎伊拉。我相信你做得对。$C，我能拯救你那些被打败的战士……', `MaleText_loc5`='好吧，札伊拉，我相信你會做出正確的事情。$C，我可以幫助你們垂危的將士...', `MaleText_loc7`='Muy bien, Zaela. Confío en que hagas lo correcto. $C, puedo ayudar a tus guerreros caídos...' WHERE `ID`=43237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 ... 당신에겐 아무것도 줄 수 없소! 우리 대족장이... 그가...', `MaleText_loc4`='我……我不能把我们的物资给你！我们的酋长……他会……', `MaleText_loc5`='我...我不能把所有的補給物品都給你!我們的大酋長他...他會...', `MaleText_loc7`='¡No... no puedo darte nada de nuestros suministros! Nuestro Jefe de guerra... Él nos...' WHERE `ID`=43238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그레고르, 이 겁쟁이! 순수한 피를 가진 오크들이 우리 해안에서 죽어가고 있습니다. 그들이 죽게 내버려두면, 우리를 죽게 내버려두는 거나 마찬가지라고요.', `FemaleText_loc4`='格雷戈，你这个懦夫！兽人的鲜血正泼洒在我们的海岸上。如果你毁灭了他们，你就把我们全都毁了。', `FemaleText_loc5`='格里高，你這懦夫!純正血統的獸人正在我們的海岸外陣亡。要是你害死了他們，你也就害死了我們全部的人。', `FemaleText_loc7`='¡Gregor, cobarde! Hay orcos de sangre pura muriendo en nuestras costas. Si los condenas, nos condenas a todos.' WHERE `ID`=43239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 로켓길 교역소에 오신 걸 환영합니다! 아직 무사하시군요.', `MaleText_loc4`='欢迎来到奥格瑞玛火箭车换乘站！别担心，你看上去还是一整块儿的。', `MaleText_loc5`='歡迎來到奧格瑪火箭道交會點!你看起來還好好的嘛。', `MaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista de Orgrimmar! Parece que sigues de una pieza.', `FemaleText_loc1`='오그리마 로켓길 교역소에 오신 걸 환영합니다! 아직 무사하시군요.', `FemaleText_loc4`='欢迎来到奥格瑞玛火箭车换乘站！别担心，你看上去还是一整块儿的。', `FemaleText_loc5`='歡迎來到奧格瑪火箭道交會點!你看起來還好好的嘛。', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista de Orgrimmar! Parece que sigues de una pieza.' WHERE `ID`=43240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 저 "대족장"이란 작자가 우리 모두를 대변하는 건 아니라는 걸 알아 두게. 용아귀 부족이 다시 한번 위대한 부족이 되기를... 타락에서 벗어나기를 꿈꾸는 이들도 있네.', `FemaleText_loc4`='$n，要知道，我们的“酋长”并不代表我们所有人的意志。我们之中有一些人希望看到龙喉氏族再次强大起来……并不再继续堕落下去。', `FemaleText_loc5`='$n，你得知道，我們的「大酋長」並不代表我們全體的意見。我們族裡還是有很多人希望能見到龍喉氏族恢復昔日的榮耀...而且甩脫所有的腐敗。', `FemaleText_loc7`='$n, quiero que sepas que nuestro "Jefe de Guerra" no habla en nombre de todos. Entre nosotros hay quienes deseamos ver a los Faucedraco con su grandeza de antaño... Y libres de toda corrupción.' WHERE `ID`=43241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대장님, 보급품도 얼마 안 가 바닥날 거예요. 트롤과 설인의 공격으로 일주일 내에 식량이 반으로 줄어들 거예요.', `FemaleText_loc4`='我们的物资也就快要耗光了，队长。由于巨魔和雪人的袭击，一周之内我们的定额口粮就得减半。', `FemaleText_loc5`='我們的補給品很快就會用光了，隊長。在食人妖和雪人的雙重夾攻之下，不到一個禮拜糧食就會只剩一半。', `FemaleText_loc7`='Nosotros tampoco tardaremos en quedarnos sin suministros, capitán. Entre los trols y los asaltos de los yetis, en una semana estaremos consumiendo medias raciones.' WHERE `ID`=43242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작전을 더 수행할 수는 없네. 델버와 그의 동료들은 최대한 빨리 스틸그릴의 정비소에서 공격을 개시해야만 하네!', `MaleText_loc4`='我们已经坚持不了多久了。戴博和他的队伍必须尽快从钢架补给站发动进攻！', `MaleText_loc5`='這項行動無法再維持多久了。戴爾伯和他的小隊必須馬上由鋼架補給站發動攻擊!', `MaleText_loc7`='No podemos mantener la operación mucho más. ¡Delber y su equipo tienen que lazar el ataque desde el Almacén de Brasacerada cuanto antes!' WHERE `ID`=43243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딜 도망가려고!', `MaleText_loc4`='别这么快，疯家伙！', `MaleText_loc5`='沒那麼容易，臭傢伙!', `MaleText_loc7`='¡No tan rápido, branquias!', `FemaleText_loc1`='어딜 도망가려고!', `FemaleText_loc4`='别这么快，疯家伙！', `FemaleText_loc5`='沒那麼容易，臭傢伙!', `FemaleText_loc7`='¡No tan rápido, branquias!' WHERE `ID`=43244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 델버와 그의 동료들은 밤낮없이 일하고 있습니다. 그는 공격대를 전투 지역의 후방으로 침투시키는 방법을 고안해냈더군요.', `MaleText_loc4`='戴博和他的人正在没日没夜地工作，队长。他已经设计出一种手段，能够将进攻部队送到战场的侧后方。', `MaleText_loc5`='戴爾伯和他的手下已經在加班趕工了，隊長。他還想到了把一支突擊隊送到戰線後方的方法。', `MaleText_loc7`='Delber y sus hombres están trabajando horas extra, capitán. Ha encontrado la forma de llevar un equipo de asalto al flanco posterior de la batalla.', `FemaleText_loc1`='대장님, 델버와 그의 동료들은 밤낮없이 일하고 있습니다. 그는 공격대를 전투 지역의 후방으로 침투시키는 방법을 고안해냈더군요.', `FemaleText_loc4`='戴博和他的人正在没日没夜地工作，队长。他已经设计出一种手段，能够将进攻部队送到战场的侧后方。', `FemaleText_loc5`='戴爾伯和他的手下已經在加班趕工了，隊長。他還想到了把一支突擊隊送到戰線後方的方法。', `FemaleText_loc7`='Delber y sus hombres están trabajando horas extra, capitán. Ha encontrado la forma de llevar un equipo de asalto al flanco posterior de la batalla.' WHERE `ID`=43245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 로켓길 교역소로 가주십시오.', `MaleText_loc4`='奥格瑞玛火箭车换乘站，谢谢。', `MaleText_loc5`='奧格瑪火箭道交會點，謝謝。', `MaleText_loc7`='Al Intercambiador de la Cohetepista de Orgrimmar, por favor.', `FemaleText_loc1`='오그리마 로켓길 교역소로 가주십시오.', `FemaleText_loc4`='奥格瑞玛火箭车换乘站，谢谢。', `FemaleText_loc5`='奧格瑪火箭道交會點，謝謝。', `FemaleText_loc7`='Al Intercambiador de la Cohetepista de Orgrimmar, por favor.' WHERE `ID`=43246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비 해적이잖아?! 놈을 처치해라!', `MaleText_loc4`='僵尸海盗？！消灭它！', `MaleText_loc5`='殭屍海盜?!殺掉它!', `MaleText_loc7`='¡¿Piratas zombis?! ¡Mátalo!', `FemaleText_loc1`='좀비 해적이잖아?! 놈을 처치하자!', `FemaleText_loc4`='僵尸海盗？！消灭它！', `FemaleText_loc5`='殭屍海盜?!殺掉它!', `FemaleText_loc7`='¡¿Piratas zombis?! ¡Mátalo!' WHERE `ID`=43247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 우리는 작전 수행을 위한 공중 지원도 확보했고, 곧 배치도 완료될 것입니다. 대장님의 부하들도 공격대에 합류시키기를 원하신다면 델버에게 보내기만 하시면 됩니다.', `MaleText_loc4`='为了这次行动，我们还取得了空中支援。行动很快就要展开了。如果你们想要加入进攻部队，就去找戴博吧。', `MaleText_loc5`='我們也已經安排好了空中支援，很快就可以進行部署。然後要是你有任何手下想加入突擊隊伍，就派他們去找戴爾伯。', `MaleText_loc7`='También hemos asegurado el apoyo aéreo para la operación y estará listo para desplegarse pronto. Si alguno de tus hombres quiere unirse al equipo, envíalo con Delber.', `FemaleText_loc1`='또한 우리는 작전 수행을 위한 공중 지원도 확보했고, 곧 배치도 완료될 것입니다. 대장님의 부하들도 공격대에 합류시키기를 원하신다면 델버에게 보내기만 하시면 됩니다.', `FemaleText_loc4`='为了这次行动，我们还取得了空中支援。行动很快就要展开了。如果你们想要加入进攻部队，就去找戴博吧。', `FemaleText_loc5`='我們也已經安排好了空中支援，很快就可以進行部署。然後要是你有任何手下想加入突擊隊伍，就派他們去找戴爾伯。', `FemaleText_loc7`='También hemos asegurado el apoyo aéreo para la operación y estará listo para desplegarse pronto. Si alguno de tus hombres quiere unirse al equipo, envíalo con Delber.' WHERE `ID`=43248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남부 로켓길 종착지로 가주십시오.', `MaleText_loc4`='南部火箭车终点站，谢谢。', `MaleText_loc5`='南方火箭道終點，謝謝。', `MaleText_loc7`='A la Terminal de la Cohetepista del Sur, por favor.', `FemaleText_loc1`='남부 로켓길 종착지로 가주십시오.', `FemaleText_loc4`='南部火箭车终点站，谢谢。', `FemaleText_loc5`='南方火箭道終點，謝謝。', `FemaleText_loc7`='A la Terminal de la Cohetepista del Sur, por favor.' WHERE `ID`=43249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갤리윅스 로켓길 교역소로 가주십시오.', `MaleText_loc4`='加里维克斯火箭车换乘站，谢谢。', `MaleText_loc5`='加里維克斯火箭道交會點，謝謝。', `MaleText_loc7`='Al Intercambiador de la Cohetepista de Gallywix, por favor.', `FemaleText_loc1`='갤리윅스 로켓길 교역소로 가주십시오.', `FemaleText_loc4`='加里维克斯火箭车换乘站，谢谢。', `FemaleText_loc5`='加里維克斯火箭道交會點，謝謝。', `FemaleText_loc7`='Al Intercambiador de la Cohetepista de Gallywix, por favor.' WHERE `ID`=43250;
