UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부 로켓길 종착지로 가주십시오.', `MaleText_loc4`='北部火箭车终点站，谢谢。', `MaleText_loc5`='北方火箭道終點，謝謝。', `MaleText_loc7`='A la Terminal de la Cohetepista del Norte, por favor.', `FemaleText_loc1`='북부 로켓길 종착지로 가주십시오.', `FemaleText_loc4`='北部火箭车终点站，谢谢。', `FemaleText_loc5`='北方火箭道終點，謝謝。', `FemaleText_loc7`='A la Terminal de la Cohetepista del Norte, por favor.' WHERE `ID`=43252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가운 소식이군. 델버에게 내 병력을 최대한 많이 보내겠네.', `MaleText_loc4`='很高兴听到这个消息。我会将能够调遣的部队全派给戴博。', `MaleText_loc5`='很高興聽你這麼說。我會盡力抽派人手去給戴爾伯。', `MaleText_loc7`='Me alegra saberlo. Enviaré a Delber todas las fuerzas de las que pueda disponer.', `FemaleText_loc1`='반가운 소식이군. 델버에게 내 병력을 최대한 많이 보내겠네.', `FemaleText_loc4`='很高兴听到这个消息。我会将能够调遣的部队全派给戴博。', `FemaleText_loc5`='很高興聽你這麼說。我會盡力抽派人手去給戴爾伯。', `FemaleText_loc7`='Me alegra saberlo. Enviaré a Delber todas las fuerzas de las que pueda disponer.' WHERE `ID`=43253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 용아귀 부족은 너무나도 많은 고통을 겪었소... 그림 바톨에서 패배하고... 아웃랜드에서 수많은 전사들을 잃고... 지금은 황혼의 망치단이 갑자기 나타나 우릴 괴롭히고 있소.$B$B가끔은 우리 용아귀 부족이 다시 위대한 부족이 될 수 있을지 의심스럽다오. 하지만 잴라 같은 젊은이들이 이 늙은이에게 희망을 준다오.', `MaleText_loc4`='我们龙喉氏族经历过太多的磨难……在格瑞姆巴托的失败……那么多强大的战士死在外域……现在，暮光之锤又向我们发动了进攻。$B$B有时我会怀疑，我们是否还能再次强大起来。但像扎伊拉这样的年轻人让我们这些老骨头又有了希望。', `MaleText_loc5`='我們龍喉氏族實在已見識了太多的苦難...我們在格瑞姆巴托的挫敗...許多偉大的戰士在外域陣亡...然後現在還有暮光之錘的入侵。$B$B有時候我忍不住會懷疑，我們是否還有可能再恢復往日的光榮。還好有像札伊拉這樣的年輕人，他們給了我這把老骨頭一線希望。', `MaleText_loc7`='Nosotros los Faucedraco hemos visto mucho sufrimiento... Nuestra derrota en Grim Batol... la pérdida de tantos grandes guerreros en Terrallende... y ahora las incursiones del Martillo Crepuscular.$B$BA veces me pregunto si alguna vez volveremos a ser grandes. Pero los jóvenes como Zaela hacen que viejos montones de huesos como yo tengan todavía alguna esperanza.' WHERE `ID`=43254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭐요, 이방인이여? 난 당신과 얘기해선 안 되오...', `MaleText_loc4`='你需要什么，外乡人？我不应该和你说话的……', `MaleText_loc5`='你要什麼，外地人?我不該跟你說話的...', `MaleText_loc7`='¿Qué es lo que necesitas, $gforastero:forastera;? No debería hablar contigo...' WHERE `ID`=43255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 전사들이 죽어가고 있습니다. 의약품을 가지고 있다면 좀 내주실 수 없을까요?', `MaleText_loc4`='我们的战士正一个个死去。你有药品能让我带回去吗？', `MaleText_loc5`='我們的戰士性命垂危。你有任何醫療補給品可以給我帶回去嗎?', `MaleText_loc7`='Nuestros guerreros están muriendo. ¿Tienes suministros médicos que me pueda llevar?', `FemaleText_loc1`='우리 전사들이 죽어가고 있습니다. 의약품을 가지고 있다면 좀 내주실 수 없을까요?', `FemaleText_loc4`='我们的战士正一个个死去。你有药品能让我带回去吗？', `FemaleText_loc5`='我們的戰士性命垂危。你有任何醫療補給品可以給我帶回去嗎?', `FemaleText_loc7`='Nuestros guerreros están muriendo. ¿Tienes suministros médicos que me pueda llevar?' WHERE `ID`=43256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갤리윅스 로켓길 교역소에 오신 것을 환영합니다! 갚을 빚이 없다면 다른 곳으로 이동하십시오.', `MaleText_loc4`='欢迎来到加里维克斯火箭车换乘站！付清债务，或者滚开。', `MaleText_loc5`='歡迎來到加里維克斯火箭道交會點!快點付錢，不然就快點滾開。', `MaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista de Gallywix! ¿Tienes deudas que pagar? Si no lárgate.', `FemaleText_loc1`='갤리윅스 로켓길 교역소에 오신 것을 환영합니다! 갚을 빚이 없다면 다른 곳으로 이동하십시오.', `FemaleText_loc4`='欢迎来到加里维克斯火箭车换乘站！付清债务，或者滚开。', `FemaleText_loc5`='歡迎來到加里維克斯火箭道交會點!快點付錢，不然就快點滾開。', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista de Gallywix! ¿Tienes deudas que pagar? Si no lárgate.' WHERE `ID`=43257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부 로켓길 교역소에 오신 것을 환영합니다! 로켓길 홍보실에서는 여러분이 마지막 회전까지 살아남으신 걸 기쁘게 생각합니다.', `MaleText_loc4`='欢迎来到北部火箭车换乘站！我们火箭车相关人员很高兴你在最后一个转弯中活了下来！', `MaleText_loc5`='歡迎來到北方火箭道交會點!火箭道公關部很高興上一趟旅程你沒有死!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista del Norte! ¡Aquí en Relaciones Paso de Cohetes estamos encantados de que hayas sobrevivido a este último viaje!', `FemaleText_loc1`='북부 로켓길 교역소에 오신 것을 환영합니다! 로켓길 홍보실에서는 여러분이 마지막 회전까지 살아남으신 걸 기쁘게 생각합니다.', `FemaleText_loc4`='欢迎来到北部火箭车换乘站！我们火箭车相关人员很高兴你在最后一个转弯中活了下来！', `FemaleText_loc5`='歡迎來到北方火箭道交會點!火箭道公關部很高興上一趟旅程你沒有死!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; al Intercambiador de la Cohetepista del Norte! ¡Aquí en Relaciones Paso de Cohetes estamos encantados de que hayas sobrevivido a este último viaje!' WHERE `ID`=43258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부 로켓길 종착지에 오신 것을 환영합니다! 아마 길을 잘못 드셨겠지만, 어쨌거나 여러분을 만나뵙게 되어 기쁩니다!', `MaleText_loc4`='欢迎来到北部火箭车终点站！你也许转错了弯，但我们还是很高兴看到你！', `MaleText_loc5`='歡迎來到北方火箭道終點!你大概跑錯地方了，不過我們還是很歡迎你!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Terminal de la Cohetepista del Norte! ¡Probablemente hayas tomado un viaje equivocado, pero nos alegramos de tenerte aquí de todas formas!', `FemaleText_loc1`='북부 로켓길 종착지에 오신 것을 환영합니다! 아마 길을 잘못 드셨겠지만, 어쨌거나 여러분을 만나뵙게 되어 기쁩니다!', `FemaleText_loc4`='欢迎来到北部火箭车终点站！你也许转错了弯，但我们还是很高兴看到你！', `FemaleText_loc5`='歡迎來到北方火箭道終點!你大概跑錯地方了，不過我們還是很歡迎你!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la Terminal de la Cohetepista del Norte! ¡Probablemente hayas tomado un viaje equivocado, pero nos alegramos de tenerte aquí de todas formas!' WHERE `ID`=43259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남부 로켓길 종착지에 오신 것을 환영합니다! 세계적으로 유명한 비밀 실험실의 본고장이죠!', `MaleText_loc4`='欢迎来到南部火箭车终点站！这里是世界闻名的秘密实验室之家！', `MaleText_loc5`='歡迎來到南方火箭道終點!舉世聞名的秘密實驗室之家!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Terminal de la Cohetepista del Sur! El hogar del laboratorio secreto más famoso del mundo.', `FemaleText_loc1`='남부 로켓길 종착지에 오신 것을 환영합니다! 세계적으로 유명한 비밀 실험실의 본고장이죠!', `FemaleText_loc4`='欢迎来到南部火箭车终点站！这里是世界闻名的秘密实验室之家！', `FemaleText_loc5`='歡迎來到南方火箭道終點!舉世聞名的秘密實驗室之家!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la Terminal de la Cohetepista del Sur! El hogar del laboratorio secreto más famoso del mundo.' WHERE `ID`=43260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고대 토템은 박쥐 모양을 하고 있습니다.', `MaleText_loc4`='这个古老的图腾被雕刻成一只蝙蝠的形状。', `MaleText_loc5`='這個古老的圖騰做成了蝙蝠的造型。', `MaleText_loc7`='Este antiguo tótem tiene forma de murciélago.' WHERE `ID`=43261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝장입니다! 오크들이 쳐들어오기 전에 당장 대피 명령을 내리고 호숫골을 떠나야 할 것 같습니다.', `MaleText_loc4`='我们完了！我也许应该在兽人杀过来之前发出撤退令，疏散湖畔镇的居民。', `MaleText_loc5`='我們完蛋了!趁著獸人還沒有進軍攻過來，乾脆叫大家立刻緊急撤離湖畔鎮算了', `MaleText_loc7`='¡Estamos acabados! ¡Será mejor que ordene la evacuación ahora y así Villa del Lago estará vacía cuando los orcos marchen por ella.' WHERE `ID`=43262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 빌어먹을 다리! 애써 만들자마자 이렇게 되다니! 이제 더는 희망이 없습니다, $n.', `MaleText_loc4`='我们刚刚建好了那座该死的桥！$n，我们还有什么希望？', `MaleText_loc5`='而且就在我們剛造好那個該死的橋的時候!還有什麼好期望的嗎，$n?', `MaleText_loc7`='¡Y justo cuando acabamos de construir ese maldito puente! ¿Dónde está la esperanza, $n?' WHERE `ID`=43263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 희망은 있습니다, 집정관님.', `MaleText_loc4`='希望仍然存在，所罗门。', `MaleText_loc5`='還是有希望的，所羅門鎮長。', `MaleText_loc7`='Hay esperanza, Solomon.' WHERE `ID`=43264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 희망이 있다는 말이오, 대령? 저 무시무시한 습격을 막을 방법이 어디 있겠소?', `MaleText_loc4`='什么希望，上校？有什么能拯救我们，挡住敌人的进攻？', `MaleText_loc5`='有什麼希望，上校?有什麼方法可以保護我們不受到接下來的攻擊?', `MaleText_loc7`='¿Qué esperanza, coronel? ¿Qué nos podría salvar del inminente asalto?' WHERE `ID`=43265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 1차, 2차, 3차 대전쟁을 거치며 총 248회에 달하는 임무를 완수했습니다.', `MaleText_loc4`='他在第一次，第二次和第三次兽人战争时期完成过248个任务。', `MaleText_loc5`='他在第一次、第二次，還有第三次大戰中連續服役並參與了248場戰役。', `MaleText_loc7`='Sirvió en 248 períodos consecutivos en la Primera Guerra, en la Segunda y en la Tercera.' WHERE `ID`=43266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 5년 전, 남쪽 비무장지대 인근에서 저 더러운 검은바위 부족 부대에 사로잡혀 포로가 되었습니다.', `MaleText_loc4`='在五年以前，他被一支肮脏下贱的黑石部队俘虏。他被俘的地方距离南部非军事区只有五分钟路程。', `MaleText_loc5`='五年前不幸被一整營該死的髒獸人給抓走了，在南方五公里遠的地方。', `MaleText_loc7`='Hecho prisionero hace cinco años por un batallón de apestosos chupacerdos Roca Negra, a cinco kilómetros al sur de la zona desmilitarizada.' WHERE `ID`=43267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 더러운 우리에 갇혀 고문을 당하면서도 살아남았습니다. 자그마치 5년 동안이나.', `MaleText_loc4`='在五年时间里，他不断地受到各种拷打和折磨，还成为了年轻兽人战士的溺器。', `MaleText_loc5`='飽受折磨，被年輕的獸人當成活小便斗在羞辱。整整五年。', `MaleText_loc7`='Torturado y mantenido con vida para servir como urinario para jóvenes guerreros orcos. Durante CINCO AÑOS.' WHERE `ID`=43268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존 J. 키샨.', `MaleText_loc4`='约翰·J·基沙恩。', `MaleText_loc5`='約翰·J·基沙恩。', `MaleText_loc7`='JOHN J. KEESHAN.' WHERE `ID`=43269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키샨이 살아 있다고? 죽은 줄로만 알았는데.', `MaleText_loc4`='基沙恩还活着？我还以为他已经死了。', `MaleText_loc5`='基沙恩還活著?我以為他已經死了。', `MaleText_loc7`='¿Keeshan, vivo? Pensé que había muerto.' WHERE `ID`=43270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사히 살아 있을 뿐 아니라 지난 5개월간 이곳 호숫골에 조용히 숨어 있었습니다. 아마 알아보지 못하셨을 겁니다. 이렇게 떠들 시간이 없습니다. 지금 당장 사람들을 구해야 합니다!', `MaleText_loc4`='是的，他还活着，在过去的五个月里像个被放逐者一样活在湖畔镇。你没有注意到吗？我们已经聊够了。我还要去救人！', `MaleText_loc5`='沒錯，他還活著。而且這五個月以來都在湖畔鎮過著像遊民一樣的生活。難道你都沒發現嗎?啊，閒話聊太多了。我們還有鎮民要救呢!', `MaleText_loc7`='Está vivo sí, y ha estado viviendo como un paria en Villa del lago durante los últimos cinco meses. ¿O es que no te has dado cuenta? Basta de hablar. ¡Tenemos gente a la que salvar!' WHERE `ID`=43271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협상가가 어디 있는지 모르겠습니다. 사실상 죽었다고 보는 편이 맞겠지요. 다른 협상가가 있습니까?', `MaleText_loc4`='我不知道我的交涉者在哪里。实际上，他可能已经死了。还有其他人选吗？', `MaleText_loc5`='我搞丟了我的協商者。事實上，他可能已經死掉了。還有其他的嗎?', `MaleText_loc7`='He perdido mi negociador. De hecho, probablemente esté muerto. ¿Hay otro disponible?', `FemaleText_loc1`='협상가가 어디 있는지 모르겠습니다. 사실상 죽었다고 보는 편이 맞겠지요. 다른 협상가가 있습니까?', `FemaleText_loc4`='我不知道我的交涉者在哪里。实际上，他可能已经死了。还有其他人选吗？', `FemaleText_loc5`='我搞丟了我的協商者。事實上，他可能已經死掉了。還有其他的嗎?', `FemaleText_loc7`='He perdido mi negociador. De hecho, probablemente esté muerto. ¿Hay otro disponible?' WHERE `ID`=43272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에 틀어박혀 지내는 것도 이제 지긋지긋하네요. 다나스 님의 복귀를 지연시키는 사무원이 누군진 몰라도 제가 주먹으로 세게 한 방 먹여줄 겁니다.', `MaleText_loc4`='我可不喜欢坐在这个洞里。真希望我们在等待达纳斯将军回来的时候能好好喝上一杯潘趣酒。', `MaleText_loc5`='我已經不想再待在這個鳥地方。希望那個害達納斯沒辦法回來的臭傢伙會被痛扁一頓。', `MaleText_loc7`='Ya estoy cansado de estar aquí sentado. Espero que el desgraciado chupatintas que esté impidiendo el regreso de Danath reciba un puñetazo en los huevillos.' WHERE `ID`=43273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 이 옷이 빨간색이라는 게 내가 곧 죽을 거라는 의미는 아니겠지요?', `MaleText_loc4`='嗨，这身红褂子就让我看上去是一件可消耗品吗？', `MaleText_loc5`='嘿，這件紅上衣會害我看起來像可犧牲的小卒嗎?', `MaleText_loc7`='¡Eh! ¿Es que esta camisa roja me hace parecer más prescindible?' WHERE `ID`=43274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 준비됐소, $n. 용아귀 부족은 곧 호드의 일원이 될 거요!', `MaleText_loc4`='我准备好了，$n。龙喉氏族很快就会成为部落的一份子！', `MaleText_loc5`='我已經準備好了，$n。不久後龍喉氏族就會加入部落!', `MaleText_loc7`='Estoy listo, $n. ¡Pronto los Faucedraco se unirán a la Horda!' WHERE `ID`=43275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오른쪽에 있는 큰 건물에 훌륭한 용아귀 부족의 약사가 산다고 들었소.', `MaleText_loc4`='我听说一位伟大的龙喉医师就住在右边的那座棚子里。', `MaleText_loc5`='我聽說有個很棒的龍喉醫生住在這裡，在我們右手邊的大帳篷裡面。', `MaleText_loc7`='He oído que un gran auxiliador Faucedraco vive aquí, en la gran cabaña a nuestra derecha.' WHERE `ID`=43276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고대 토템은 박쥐 모양을 하고 있습니다. 차발이 말한 그 토템이 확실합니다.', `MaleText_loc4`='这个古老的图腾被雕刻成一只蝙蝠的形状。它一定是查巴尔所说的图腾。', `MaleText_loc5`='這個古老的圖騰是蝙蝠的造型，必定就是查巴爾講的那個圖騰。', `MaleText_loc7`='El antiguo tótem está tallado con forma de murciélago. Debe ser el tótem del que habló Chabal.' WHERE `ID`=43277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='향료를 토템 밑에 놓습니다.', `MaleText_loc4`='将熏香放在这尊雕像的脚下。', `MaleText_loc5`='把焚香放在雕像的腳下。', `MaleText_loc7`='Coloca el incienso a los pies de la estatua.', `FemaleText_loc1`='향료를 토템 밑에 놓습니다.', `FemaleText_loc4`='将熏香放在这尊雕像的脚下。', `FemaleText_loc5`='把焚香放在雕像的腳下。', `FemaleText_loc7`='Coloca el incienso a los pies de la estatua.' WHERE `ID`=43278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 협상이 끝나면 오랫동안 풍족하게 살 수 있기를 기대하고 있다오.', `MaleText_loc4`='经过多次谈判之后，我期待一个长久的繁荣时代即将到来。', `MaleText_loc5`='等這件事協商完成後，我就等著過段長長久久的安定生活了。', `MaleText_loc7`='Después de las negociaciones, estoy deseando disfrutar de una larga y próspera vida.' WHERE `ID`=43279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족의 대족장은 여기 언덕 위의 가장 큰 건물에 있소. 분명히 합리적인 오크일 거요.', `MaleText_loc4`='龙喉酋长就在这里山顶上最高大的那座房子里。相信他是个通情达理的人。', `MaleText_loc5`='龍喉氏族的大酋長就在山丘頂上最大的那棟房子裡面。我相信他應該會講道理的。', `MaleText_loc7`='El jefe de guerra Faucedraco está en el edificio más grande en lo alto de esa colina. Estoy convencido de que será razonable.' WHERE `ID`=43280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여기요! 가까이 서 있으시오. 말은 전문가인 내가 할 거요.', `MaleText_loc4`='就是这里！跟紧我，让我来谈判。我是这方面的专家。', `MaleText_loc5`='到了!跟緊一點，讓我來講就好。我可是專家。', `MaleText_loc7`='¡Ya estamos! Quédate cerca y deja que hable yo. Soy el experto.' WHERE `ID`=43281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머의 고향, 맹금의 봉우리에 오신 것을 환영합니다.$b$b고위 영주 폴스타트 님이 아이언포지에 가 계시니 저와 일하셔야 할 거예요.', `MaleText_loc4`='欢迎来到鹰巢山，蛮锤部族的家园。$B$B大领主弗斯塔德·蛮锤已经前往铁炉堡，有事情的话可以和我说。', `MaleText_loc5`='歡迎來到鷹巢山，蠻錘氏族的家鄉。$B$B因為大族長弗斯塔德人在鐵爐堡，所以是由我來接見你。', `MaleText_loc7`='Te doy la bienvenida a Pico Nidal, hogar del Clan Martillo Salvaje.$B$BEl señor feudal Falstad está en Forjaz, así que tendrás que tratar conmigo.' WHERE `ID`=43282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在1分钟内开始。', `MaleText_loc5`='戰鬥在1分鐘後開始。', `MaleText_loc7`='La batalla comienza en 1 minuto.' WHERE `ID`=43283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전투가 시작됩니다! 준비하십시오!', `MaleText_loc4`='战斗将在30秒内开始。做好准备！', `MaleText_loc5`='戰鬥在30秒後開始。準備迎戰!', `MaleText_loc7`='La batalla comienza en 30 segundos. ¡Prepárense!' WHERE `ID`=43284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅의 영혼은 생명을 제물로 바치는 잔혹함과 어둠의 주술을 더는 용납하지 않을 겁니다.$B$B썩은가지 부족은 반드시 처단해야 합니다!', `MaleText_loc4`='这片土地的英灵不会再容忍这种黑暗魔法和邪恶的献祭。$B$B邪枝巨魔必须被赶走！', `MaleText_loc5`='這片土地的魂靈已經無法再容忍這種邪惡的魔法和殘酷的獻祭。$B$B邪枝食人妖必須消失!', `MaleText_loc7`='Los espíritus de esta tierra ya no toleran su magia oscura ni sus crueles sacrificios.$B$B¡Los Vilrama tienen que irse!' WHERE `ID`=43285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 얼굴이면 괜찮은 가면을 만들 수 있겠군!', `MaleText_loc4`='你的脑袋倒是能做成个好袋子！', `MaleText_loc5`='你的頭可以做成很不錯的袋子!', `MaleText_loc7`='¡Tu cabeza será una buena bolsa!' WHERE `ID`=43286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 일을 마무리 지읍시다. 이 못생긴 트롤을 멍하니 쳐다보고 있을 바에야 차라리 고향인 맹금의 봉우리로 돌아가는 게 나을 것 같으니까요.', `MaleText_loc4`='让我们结束这一切吧。我现在只想回到鹰巢山的家里去，而不是盯着这些丑陋的巨魔。', `MaleText_loc5`='快點把事情搞定。我想趕緊回去鷹巢山，不想盯著這些醜不拉嘰的食人妖。', `MaleText_loc7`='Acabemos con esto. Preferiría estar en casa, en Pico Nidal, que aquí mirando a estos trols espantosos.' WHERE `ID`=43287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 긴 팔로 어떻게 해볼 수 있을 줄 알았나, $r? 착각하지 마라!', `MaleText_loc4`='$r，你以为这些长胳膊能让你占据优势？再想想吧！', `MaleText_loc5`='你以為你的雙手比較長就佔上風了，$r?試看看啊!', `MaleText_loc7`='¿Crees que esos brazos largos te dan ventaja, $r? ¡Reconsidéralo!' WHERE `ID`=43288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옹고롱고를 내버려 둬!', `MaleText_loc4`='别惹昂格隆格！', `MaleText_loc5`='離翁戈隆戈遠一點!', `MaleText_loc7`='¡Deja en paz a Ongo''longo !' WHERE `ID`=43289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 낭비하지 맙시다! 언데드가 코앞에 있어요.', `MaleText_loc4`='不要浪费时间了！这里还有许多亡灵呢。', `MaleText_loc5`='我們別浪費時間!前面還有不死族。', `MaleText_loc7`='¡No perdamos el tiempo! Los no-muertos andan sueltos.' WHERE `ID`=43290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추세요. 성급하게 움직이지 맙시다.', `MaleText_loc4`='稳住，不要鲁莽。', `MaleText_loc5`='先等一下，不要貿然進去。', `MaleText_loc7`='Espera. No nos apresuremos.' WHERE `ID`=43291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 못 참겠군! 잠시 한숨 돌려야겠어...', `MaleText_loc4`='赞吉尔受够了！现在该休息……', `MaleText_loc5`='我受夠了!該是休息一下的時候...', `MaleText_loc7`='¡Ya e'' suficiente! Hora de toma''se un descanso...' WHERE `ID`=43292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 잔질이 돌아왔다!', `MaleText_loc4`='赞吉尔回来了！', `MaleText_loc5`='贊吉爾回來了!', `MaleText_loc7`='¡Zanzil ha regresa''o!' WHERE `ID`=43293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 빠져나가기만 하면, 너희 더러운 오크 녀석들의 머리통을 모두 박살 내주겠어.', `MaleText_loc4`='如果我能从这里出去，我一定会在你的脑袋上拉泡屎。你这个该死的兽人。', `MaleText_loc5`='要是我離開這裡的話，該死的獸人，我一定要拉坨屎在你頭上。', `MaleText_loc7`='Si alguna vez salgo de aquí, voy a cagarme encima de sus cabezas, orcos chupacerdos.' WHERE `ID`=43294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 내 동료들은 어디에 있지?!', `MaleText_loc4`='我的人都在哪里？？！', `MaleText_loc5`='我其他的手下呢??!', `MaleText_loc7`='¡¿¿Dónde está el resto de mi tripulación??!' WHERE `ID`=43295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우 이 정도 철창으로 나를 가둬둘 수 있을 것 같아? 하!', `MaleText_loc4`='你以为这些东西能困住我？哈！', `MaleText_loc5`='你以為這樣就關得住我?哈!', `MaleText_loc7`='¿Creéis que estas barras pueden tenerme prisionero? ¡JA!' WHERE `ID`=43296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대여사제 제클릭이 거의 다 회복되었습니다!', `FemaleText_loc4`='高阶祭司耶克里克就要痊愈了！', `FemaleText_loc5`='高階祭司耶克里克快徹底恢復了!', `FemaleText_loc7`='¡La suma sacerdotisa Jeklik está casi sanada!' WHERE `ID`=43297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경하는 대족장님...', `MaleText_loc4`='最受敬爱的酋长——', `MaleText_loc5`='最崇高的大酋長—', `MaleText_loc7`='Estimado Jefe de Guerra...' WHERE `ID`=43298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 뭔가 잘못 생각하시는 것 같군요. 가로쉬 헬스크림 님은 당신의 도움이 있건 없건 상륙 거점을 확보하실 겁니다. 저희가 부탁드리고자 하는 것은...', `MaleText_loc4`='酋长，你误会了。不管能否得到你的帮助，加尔鲁什·地狱咆哮都将在这片海岸上抢滩登陆。我们的要求是——', `MaleText_loc5`='大酋長，你誤會了。卡爾洛斯·地獄吼會在這邊建立起灘頭堡，不論你幫不幫忙。我們要求的是—', `MaleText_loc7`='Jefe de guerra, nos malinterpretas. Garrosh Grito Infernal tendrá una cabeza de playa en estas orillas, con tu ayuda o sin ella. Lo que queremos saber es...' WHERE `ID`=43299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭘 하는 게냐? 상관없다. 네가 방해하기 전에 제크릭을 부활시킬 거니까!', `MaleText_loc4`='你在这儿干什么？不要紧，在你找到机会插手之前，我要复活耶克里克！', `MaleText_loc5`='你在這裡做什麼?無所謂，我要在你沒有機會干預之前，復活耶克里克!', `MaleText_loc7`='¿Qué hace'' aquí? No impoh''ta, voy a resucitar a Jeklik antes de que tenga'' la opoh''tunidad de interferir.' WHERE `ID`=43300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 막강한 세력입니다! 엄청난 수의 함대와 전쟁 기계, 노련한 역전 용사들을 보유하고 있지요. 헬스크림 님은 손쉽게 이곳을...', `MaleText_loc4`='可部落已经集结了一支所向披靡的大军！这支规模庞大的舰队满载着精锐老兵和战争机器。地狱咆哮会把你碾碎，只要——', `MaleText_loc5`='但是部落已經集結了一支大軍!帶來了精銳的士兵和龐大的作戰艦隊。地獄吼會把你徹底擊潰，就像—', `MaleText_loc7`='¡Pero la Horda ha reunido a una multitud! Una vasta flota de máquinas de guerra y duros veteranos. Pronto Grito Infernal te aplastará como...' WHERE `ID`=43301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 어리석은 행동입니다!', `MaleText_loc4`='这简直是疯狂！', `MaleText_loc5`='這太瘋狂了!', `MaleText_loc7`='¡Es una locura!' WHERE `ID`=43302;
