UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런.. 진도가 기뻐할 일은 아니군...', `MaleText_loc4`='呃哦……金度一定不会喜欢这个……', `MaleText_loc5`='呃...金度一定會不高興的...', `MaleText_loc7`='Oh, oh... A Jin''do eh''to no le va a hacer ninguna gracia...' WHERE `ID`=43304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 시간이다!', `MaleText_loc4`='该离开这儿了！', `MaleText_loc5`='該閃人了!', `MaleText_loc7`='¡Ahora de sali'' de aquí!' WHERE `ID`=43305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸데없이 지껄이지 마라, 벌레야. 용아귀 부족의 도움이 필요하다면 선물을 들고 와서 애걸해야지.', `MaleText_loc4`='别废话了，虫子。要是你真想得到龙喉的帮助，你应该卑躬屈膝地来，还要带上足够多的金子。', `MaleText_loc5`='別再囉唆了，你這廢物。如果你要龍喉氏族出兵幫你，你應該要跪下來奉上黃金才對。', `MaleText_loc7`='Deja de malgastar palabras, gusano. Si quieres la ayuda de los Faucedraco deberías haberte arrodillado y habernos ofrecido oro.' WHERE `ID`=43306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 위협하는 것이냐? 난 아웃랜드에서 헬스크림이 어땠는지 안다. 훌쩍거리는 애송이였지. 그딴 게 무슨 대족장이라고.', `MaleText_loc4`='这算是威胁吗？我在外域见过地狱咆哮。不过是个只会哀鸣的小崽子罢了。他算什么酋长。', `MaleText_loc5`='這是在威脅我嗎?我知道外域那個地獄吼。一個沒用的小鬼。他才不是大酋長。', `MaleText_loc7`='¿Eso ha sido una AMENAZA? Conocí a Grito Infernal en Terrallende. Un cachorrillo llorica. No es un jefe de guerra.' WHERE `ID`=43307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올 테면 와 봐라!', `MaleText_loc4`='把他带上来！', `MaleText_loc5`='帶他上來!', `MaleText_loc7`='¡Deténganlo!' WHERE `ID`=43308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는...', `MaleText_loc4`='这就是……', `MaleText_loc5`='這是...', `MaleText_loc7`='Esto es...' WHERE `ID`=43309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족이다!', `MaleText_loc4`='龙喉！！', `MaleText_loc5`='龍喉氏族!!', `MaleText_loc7`='¡¡FAUCEDRACO!!' WHERE `ID`=43310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 $c|1은;는; 살려 두어라. 협상에서 인질로 써먹을 것이다.', `MaleText_loc4`='别让那$c死了。$g他:她;将是我们谈判的筹码。', `MaleText_loc5`='留住這個$c的性命。$g他:她;將是我們的籌碼。', `MaleText_loc7`='Que $gel:la; $c viva. Será nuestra baza para negociar.' WHERE `ID`=43311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 동료들을 불러 보아라. 우리는 헬스크림의 호드를 쳐부수고 시체는 바다에 던져 버릴 것이다...', `MaleText_loc4`='叫其它人来。我们将粉碎地狱咆哮的部落军团，把他们的尸体丢进海里喂鱼……', `MaleText_loc5`='呼叫其他人。我們會一舉擊潰地獄吼的部落，把他們的屍體扔進海裡...', `MaleText_loc7`='Llamen a los demás. Aplastaremos la Horda de Grito Infernal y arrojaremos sus cuerpos al mar...' WHERE `ID`=43312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 폭탄이 식지 않게 하는 중이잖아. 내가 뭘 하고 있는 걸로 보여?!', `MaleText_loc4`='保持炸弹的温度，这显而易见。我看上去像是在做什么？', `MaleText_loc5`='當然是在讓炸彈保持溫暖啊。不然你以為我在幹什麼?!', `MaleText_loc7`='Está claro que mantengo caliente la bomba. ¡¿Qué parece que estoy haciendo?!' WHERE `ID`=43313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 가만히 앉아서 뭘 하고 있지?', `MaleText_loc4`='你光坐在那儿是要干什么？！', `MaleText_loc5`='你坐在那邊發呆是幹什麼?!', `MaleText_loc7`='¡¿Qué haces ahí sentado sin hacer nada?!' WHERE `ID`=43314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사제 베녹시스가 거의 다 회복되었습니다!', `MaleText_loc4`='高阶祭司温诺希斯快要痊愈了！', `MaleText_loc5`='高階祭司溫諾希斯差一點就完全恢復了!', `MaleText_loc7`='¡El sumo sacerdote Venoxis está casi sanado!' WHERE `ID`=43315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페더문 폐허에서 벌어지는 전투에 데려가 주십시오.', `MaleText_loc4`='带我到羽月废墟的战场上去。', `MaleText_loc5`='帶我前往羽月廢墟的戰鬥。', `MaleText_loc7`='Llévame a la batalla en las Ruinas Plumaluna.', `FemaleText_loc1`='페더문 폐허에서 벌어지는 전투에 데려가 주십시오.', `FemaleText_loc4`='带我到羽月废墟的战场上去。', `FemaleText_loc5`='帶我前往羽月廢墟的戰鬥。', `FemaleText_loc7`='Llévame a la batalla en las Ruinas Plumaluna.' WHERE `ID`=43316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕국을 구하는 데 필요하다면 어떤 일이라도 할 수 있겠습니까?', `MaleText_loc4`='你是否愿意不惜一切代价来挽救你的王国？', `MaleText_loc5`='你願意不惜一切代價來拯救你的王國嗎?', `MaleText_loc7`='¿Harás lo que sea necesario para salvar nuestro reino?' WHERE `ID`=43318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페더문 요새로 돌아가야 합니다!', `MaleText_loc4`='我必须返回羽月要塞！', `MaleText_loc5`='我必須回到羽月要塞!', `MaleText_loc7`='¡Debo regresar al Bastión Plumaluna!', `FemaleText_loc1`='페더문 요새로 돌아가야 해요!', `FemaleText_loc4`='我必须返回羽月要塞！', `FemaleText_loc5`='我必須回到羽月要塞!', `FemaleText_loc7`='¡Debo regresar al Bastión Plumaluna!' WHERE `ID`=43319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 할 일이 남았다 이건가? 안됐군. 이번엔 훨씬 더 강한 물약을 가져왔거든! 베녹시스는 곧 부활할 것이다!', `MaleText_loc4`='你又回来了，哈？真是太糟了，因为我这次混合制出了更为强大的药剂！温诺希斯将复活！', `MaleText_loc5`='你還想要，啊?太可惜了，因為這回我又調出更強的藥劑了!溫諾希斯會活起來!', `MaleText_loc7`='Has vuelto a por más, ¿eh? ¡Es una pena, porque eh''ta vez he mezcla''o una poción más fueh''te! ¡Venoxis vivirá!' WHERE `ID`=43320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 이상 참을 수 없다...', `MaleText_loc4`='我已经受够了……', `MaleText_loc5`='我沒辦法再承受這個了...', `MaleText_loc7`='No pue''o soportar esto mucho más...' WHERE `ID`=43321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔질 님 나가신다!', `MaleText_loc4`='赞吉尔来了！', `MaleText_loc5`='贊吉爾來了!', `MaleText_loc7`='¡Aquí llega Zanzil!' WHERE `ID`=43322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하! 이번엔 나, 잔질의 승리다! 누가 축하하러 왔는지 잘 봐라!', `MaleText_loc4`='啊哈哈哈！这次的赢家是赞吉尔！而且快看看是谁来庆祝！', `MaleText_loc5`='啊哈哈哈!這一次是贊吉爾贏了!看看是誰來慶祝了!', `MaleText_loc7`='¡Jajajajaja! ¡Eh''ta vez gana Zanzil! ¡Y mira quién ha veni''o a celebrah''lo!' WHERE `ID`=43323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 내가 실패했단 말인가...', `MaleText_loc4`='不！赞吉尔失败了……', `MaleText_loc5`='不～～～～!贊吉爾是個失敗...', `MaleText_loc7`='¡Noooo! Zanzil e'' un fracaso...' WHERE `ID`=43324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크발디르 놈들을 이 도시에서 모조리 몰아냈다. 이제 작업을 시작할 수 있겠군. 아하하하!', `FemaleText_loc4`='城市中的克瓦迪尔已经被清除了。现在我们可以开始仪式的准备了。', `FemaleText_loc5`='科瓦迪爾已經被逐出這座城市。現在我們可以開始準備了。', `FemaleText_loc7`='La ciudad ha sido purgada de Kvaldires. Ahora comienzan las preparaciones.' WHERE `ID`=43326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여전사여, 너에게 맡길 임무가 하나 있다.', `FemaleText_loc4`='女武士，我有一个任务需要你去完成。', `FemaleText_loc5`='戰鬥仕女，我有項任務要交給你。', `FemaleText_loc7`='Doncella de batalla, tengo una tarea para ti.' WHERE `ID`=43327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여전사여! 전쟁터에 네가 필요하다. 크발디르 놈들이 우리 전선을 무너뜨렸다!', `FemaleText_loc4`='女武士！立即赶赴战场。克瓦迪尔已经突破了我们的战线！', `FemaleText_loc5`='戰鬥仕女!戰場需要你。科瓦迪爾已經突破我們的防線!', `FemaleText_loc7`='¡Doncella de batalla! Te necesitan en el campo de batalla. ¡Los Kvaldires han penetrado nuestras líneas!' WHERE `ID`=43328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요!', `MaleText_loc4`='欢迎！', `MaleText_loc5`='歡迎!', `MaleText_loc7`='¡$gBienvenido:Bienvenida;!', `FemaleText_loc1`='어서 오세요!', `FemaleText_loc4`='欢迎！', `FemaleText_loc5`='歡迎!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida;!' WHERE `ID`=43329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님.', `MaleText_loc4`='你好啊，$c。', `MaleText_loc5`='你好啊，$c。', `MaleText_loc7`='Saludos, $c.', `FemaleText_loc1`='안녕하세요, $c님.', `FemaleText_loc4`='你好啊，$c。', `FemaleText_loc5`='你好啊，$c。', `FemaleText_loc7`='Saludos, $c.' WHERE `ID`=43330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 버텨라! 머지않아 의식이 끝날 것이다.', `FemaleText_loc4`='坚持住！召唤仪式就要完成了。', `FemaleText_loc5`='堅持住!儀式快要完成了。', `FemaleText_loc7`='¡El ritual ya está casi completo!' WHERE `ID`=43331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여전사여, 저들을 쓰러뜨려라!', `FemaleText_loc4`='消灭他们，女武士！', `FemaleText_loc5`='砍死他們，戰鬥仕女!', `FemaleText_loc7`='¡Córtalos, Doncella de batalla!' WHERE `ID`=43332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 천천히 둘러보세요.', `MaleText_loc4`='欢迎！请随便看看。', `MaleText_loc5`='你好!請隨處看看。', `MaleText_loc7`='¡Saludos! Echa un vistazo.', `FemaleText_loc1`='안녕하세요! 천천히 둘러보세요.', `FemaleText_loc4`='欢迎！请随便看看。', `FemaleText_loc5`='你好!請隨處看看。', `FemaleText_loc7`='¡Saludos! Echa un vistazo.' WHERE `ID`=43333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 저지하라! 사원 가까이 못 오게 해!', `FemaleText_loc4`='挡住他们！绝不能让他们靠近神殿！', `FemaleText_loc5`='擋住他們!別讓他們靠近神殿!', `FemaleText_loc7`='¡Conténganlos! ¡Aléjenlos del templo!' WHERE `ID`=43334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 찾는 물건이 있다면 말씀만 하세요.', `MaleText_loc4`='你需要什么，可以直接告诉我，$c。', `MaleText_loc5`='如果你需要幫忙找什麼就讓我知道，$c。', `MaleText_loc7`='Si necesitas ayuda para encontrar algo, $c, dímelo.', `FemaleText_loc1`='$c님, 찾는 물건이 있다면 말씀만 하세요.', `FemaleText_loc4`='你需要什么，可以直接告诉我，$c。', `FemaleText_loc5`='如果你需要幫忙找什麼就讓我知道，$c。', `FemaleText_loc7`='Si necesitas ayuda para encontrar algo, $c, dímelo.' WHERE `ID`=43335;
