UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 없애 버려라! 봐주지 마라, 형제들이여!', `MaleText_loc4`='消灭他们，绝不怜悯，兄弟们！', `MaleText_loc5`='殺光他們!兄弟們，不需要有絲毫猶豫!', `MaleText_loc7`='¡Mátenlos a todos! ¡Sin piedad, hermanos!' WHERE `ID`=43346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 안식은 죽음뿐이다, 크발디르 놈들아!', `MaleText_loc4`='你们只能在死亡后获得和平，克瓦迪尔！', `MaleText_loc5`='你唯一可找到平靜的方式便是死亡，科瓦迪爾!', `MaleText_loc7`='¡La única paz que tendrás será en la muerte, Kvaldir!' WHERE `ID`=43347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 향해 전진하는 꼴이라니! 아즈샤라 님이 너희를 바다에서 몰아내리라!', `MaleText_loc4`='你们在迈向死亡！艾萨拉会将你们彻底驱逐出海洋！', `MaleText_loc5`='你正向死亡邁進!艾薩拉將目睹你們滅亡於海洋的那一刻!', `MaleText_loc7`='¡Marchan a sus muertes! ¡Azshara los verá ser arrasados de los mares!' WHERE `ID`=43348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 죽음을 향해... 뛰어드는 거다... 멍청이들아.', `MaleText_loc4`='你们这是……急着寻死，蠢货。', `MaleText_loc5`='你只是...在加快...你的死亡...蠢貨。', `MaleText_loc7`='Siguen avanzando... a sus muertes... tontos.' WHERE `ID`=43349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보들. 나약한 것들.', `MaleText_loc4`='蠢货！懦夫！', `MaleText_loc5`='蠢材。弱者。', `MaleText_loc7`='Tontos. Débiles.' WHERE `ID`=43350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일찌감치 패배를 인정했어야지.', `MaleText_loc4`='你应该接受你的失败。', `MaleText_loc5`='你們應該要接受自己的失敗。', `MaleText_loc7`='Debieron aceptar su derrota.' WHERE `ID`=43351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아와 봤자 죽음만이 기다릴 뿐이다.', `MaleText_loc4`='回来了，就只有死路一条。', `MaleText_loc5`='你們回來只會面臨死亡。', `MaleText_loc7`='Su regreso sólo traerá muerte.' WHERE `ID`=43352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 기다리는 건 노예의 삶이나 죽음뿐이다.', `MaleText_loc4`='等待你的只有奴役和死亡。', `MaleText_loc5`='奴役和死亡正等待著你們。', `MaleText_loc7`='Sólo tendrán esclavitud y la muerte.' WHERE `ID`=43353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크발디르가 다리 위로 몰려오고 있다! 여전사여, 여군주 나즈자르 님께서 부르신다!', `MaleText_loc4`='克瓦迪尔人正从桥上涌过来！女武士，纳兹夏尔女士在召唤你！', `MaleText_loc5`='科瓦迪爾已經穿過橋了!戰鬥仕女，納茲賈爾女士在呼喚你!', `MaleText_loc7`='¡Los Kvaldires cruzan el puente! ¡Doncella de Batalla, Lady Naz''jar te llama!' WHERE `ID`=43354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모래밭으로 돌아가라, 버러지 같으니!', `MaleText_loc4`='回到沙子里去吧，渣滓！', `MaleText_loc5`='回到地面上去吧，蠢貨!', `MaleText_loc7`='¡Vuelve a las arenas, desgraciado!' WHERE `ID`=43355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 아주 줄줄이 기어들어 오는군.', `MaleText_loc4`='真不错，他们一个接一个的进来。', `MaleText_loc5`='他們真是好心，一個一個過來。', `MaleText_loc7`='Qué amables en pasar de a uno.' WHERE `ID`=43356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다풀만큼이나 질긴 놈들이군.', `MaleText_loc4`='就像海草一样难以剿除。', `MaleText_loc5`='大概軟得跟海藻一樣吧。', `MaleText_loc7`='Resistentes como algas marinas.' WHERE `ID`=43357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시가 어지간히 마음에 드나 보군. 전망 때문인가?', `MaleText_loc4`='他们也许真的喜欢这座城市。因为这儿风景不错？', `MaleText_loc5`='他們真的很喜歡這個城市。是因為它的風景嗎?', `MaleText_loc7`='Se ve que les encanta esta ciudad. ¿Será la vista?' WHERE `ID`=43358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구루바시 부족은 학카르와 함께 사라졌네. 우리 잔달라 부족도 대부분 고향으로 가버렸고.$b$b이제 줄구룹을 감시하는 건 나, 메이위키, 그리고 밤발라에 있는 검은창 부족의 몫일세.', `MaleText_loc4`='古拉巴什连同哈卡一起都完蛋了。大多数追随我的赞达拉巨魔都回到了他们的家园。$b$b现在，看护祖尔格拉布的任务落在了我、梅维克和邦巴拉暗矛巨魔的肩上。', `MaleText_loc5`='古拉巴什食人妖已經滅亡，還有哈卡也跟著他們一起滅亡了。我的贊達拉同胞們絕大多數都已返回他們的家園。$B$B現在換成了必須由我，梅維基，還有班姆巴拉島上的暗矛部族，來負責看守祖爾格拉布。', `MaleText_loc7`='Los Gurubashi eh''tán mueh''tos y los Hakkar también. Casi todos mis compañeros Zandalar han regresa''o a su patria.$b$bAhora somos nosotros, Maywiki, los Lanza Negra de Bambala y yo, los que debemos vigilar Zul''Gurub.' WHERE `ID`=43359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차발, 잔질을 추적하다 무슨 일을 하고 있었나 잊어버렸습니다. 다음에 어디로 가야 하는지 알려주시겠습니까?', `MaleText_loc4`='查巴尔，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？', `MaleText_loc5`='我本來在追捕贊吉爾，但是我忘記做到哪裡了。可以提醒我，接下來我該去哪裡嗎?', `MaleText_loc7`='Chabal, andaba detrás de Zanzil y he olvidado lo que estaba haciendo. ¿Puedes recordarme adónde tengo que ir ahora?', `FemaleText_loc1`='차발, 잔질을 추적하다 무슨 일을 하고 있었나 잊어버렸네요. 다음에 어디로 가야 하는지 알려주시겠어요?', `FemaleText_loc4`='查巴尔，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？', `FemaleText_loc5`='我本來在追捕贊吉爾，但是我忘記做到哪裡了。可以提醒我，接下來我該去哪裡嗎?', `FemaleText_loc7`='Chabal, andaba detrás de Zanzil y he olvidado lo que estaba haciendo. ¿Puedes recordarme adónde tengo que ir ahora?' WHERE `ID`=43360;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여전사여, 크발디르가 또다시 도시를 빼앗으러 왔습니다. 밖에 나가 보십시오.', `FemaleText_loc4`='女武士，克瓦迪尔要将这座城市从我们手中夺回去。外边的人需要你的帮助。', `FemaleText_loc5`='科瓦迪爾回來了，想從我們手中奪回城市，戰鬥仕女。到外面吧，他們需要你的幫助。', `FemaleText_loc7`='El Kvaldir ha vuelto para recuperar la ciudad, Doncella de Batalla. Te necesitan afuera.' WHERE `ID`=43361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사술사 진도가 아닌가! 그 가면은 정말 오랜만이군.', `MaleText_loc4`='妖术师金度！我已经好久没见过那面具了。', `MaleText_loc5`='『妖術師』金度!距離我上次看到那個面具已經過了很久。', `MaleText_loc7`='¡Jin''do el Aojador! Ha pasa''o mucho tiempo desde la última vez que vi esa máscara.' WHERE `ID`=43362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 일로 내가 관리하는 지역에 온 건가? 난 위대한 줄구룹의 방문객을 맞는 데는 익숙치 않다고.', `MaleText_loc4`='是什么风把你吹到我这儿来了？我还不习惯接待来自神圣祖尔格拉布的访客。', `MaleText_loc5`='是什麼把你帶到我在荊棘谷裡的地盤?我很少有機會接待從尊貴的祖爾格拉布來的客人。', `MaleText_loc7`='¿Qué te trae a eh''ta pah''te de Tuercespina? No eh''toy acoh''tumbra''o a recibir visitas procedentes del eh''timado Zul''Gurub.' WHERE `ID`=43363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 여기 왔는지는 잘 알 텐데, 잔질.', `MaleText_loc4`='你对我来此的原因了解得一清二楚，赞吉尔。', `MaleText_loc5`='你很清楚我為什麼在這，贊吉爾。', `MaleText_loc7`='Sabes muy bien por qué eh''toy aquí, Zanzil.' WHERE `ID`=43364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구루바시 부족의 존폐가 위태로운 상황이다. 내가 부활했고 만도키르도 부활했지만... 다른 이들은 모두 사라졌지.', `MaleText_loc4`='古拉巴什遭遇了危难。我活了下来，曼多基尔也回来了……可我们却失去了剩下的所有人。', `MaleText_loc5`='古拉巴什正面臨艱難的時刻。我活下來了，曼多基爾也回來了...但我們其他人都不在了。', `MaleText_loc7`='Los Gurubashi eh''tán acaba''os. Yo vivo y Mandokir ha regresa''o... pero todos los demás han mueh''to.' WHERE `ID`=43365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것 참 안됐군... 하지만 늙은 추방자인 나, 잔질의 걱정거리는 아니야.', `MaleText_loc4`='真是遗憾……可对于像赞吉尔这样的老牌流亡者来说算不了什么。', `MaleText_loc5`='真遺憾...可惜不是贊吉爾這位老流放者要煩惱的問題。', `MaleText_loc7`='Una pena... pero no e'' asunto de un viejo exilia''o como Zanzil.' WHERE `ID`=43366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇단 말이지, 잔질. 그렇다면 걱정하게 만들어 줘야 겠군. 내가 대여사제 제클릭과 대사제 베녹시스의 몸을 복구했다.', `MaleText_loc4`='嗯，赞吉尔，我有个能让你在意的理由。我找到了高阶祭司耶克里克和温诺希斯的遗体。', `MaleText_loc5`='可是，贊吉爾，我想把它變成你也要煩惱的問題。我已經找回了高階祭司耶克里克，還有高階祭司溫諾希斯的屍體。', `MaleText_loc7`='Bueno, Zanzil, me guh''taría conveh''tih''lo en asunto tuyo. He recupera''o los cuerpos de la Suma Sacerdotisa Jeklik y del Sumo Sacerdote Venoxis.' WHERE `ID`=43367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 네 비약으로 무슨 일을 할 수 있는지 알고 있지. 옛 친구들을 도와주지 않겠나?', `MaleText_loc4`='我还记得你能让那些合剂发挥出什么样的效力。你愿意用你的合剂帮帮老朋友吗？', `MaleText_loc5`='我還記得你那些魔藥的神奇妙用。怎麼樣，你的魔藥能幫幫一位老朋友嗎?', `MaleText_loc7`='Aún recuerdo lo que ere'' capaz de hacer con esos elixires tuyos. ¿Podrán ayudar a un viejo amigo?' WHERE `ID`=43368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구라고? 네놈도 내게 돌을 던지던 자들 중 하나가 아니었나, 진도. 하지만 옛날 이야기는 옛날 이야기로 남겨두지.', `MaleText_loc4`='老朋友？你可是那群落井下石的人之一啊，金度。但是过去的就让它过去吧，你说好吗？', `MaleText_loc5`='朋友?當初是誰在那邊對我吐口水、丟石頭的，金度?但好吧，過去的事就讓它過去好了，嗯?', `MaleText_loc7`='¿Amigo? Tú eh''tabas entre los que me escupieron y me arrojaron piedras, Jin''do. Pero, lo pasa''o, pasa''o, ¿no?' WHERE `ID`=43369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 박쥐와 뱀에게 나, 잔질 님의 도움이 필요하다 이거지? 알겠다. 줄구룹 안에서 보지... 오랜 친구여.', `MaleText_loc4`='这么说，你的蝙蝠和蛇群需要赞吉尔的帮助？非常好。那我们在祖尔格拉布里面见吧……老朋友。', `MaleText_loc5`='所以，你的蝙蝠和蛇需要贊吉爾的協助?很好，我們祖爾格拉布裡見...老朋友。', `MaleText_loc7`='¿Así que tu mu''ciélago y tu se''piente necesitan la ayu''a de Zanzil? Muy bien. Te veré en Zul''Gurub... viejo amigo.' WHERE `ID`=43370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크발디르는 죽지 않는다... 이 도시는 우리 것이다...', `MaleText_loc4`='克瓦迪尔永生……这座城是我们的……', `MaleText_loc5`='科瓦迪爾永不死亡...這個城市是我們的...', `MaleText_loc7`='Kvaldir nunca morirá... la ciudad es nuestra…' WHERE `ID`=43371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기엔 아직 우리가 모르는 것이 있습니다, $n 님. 그거 하나는 분명히 말씀드릴 수 있어요.', `FemaleText_loc4`='我们知道的只是皮毛而已，$n。我可以向你担保。', `FemaleText_loc5`='事情的全貌絕對不只我們所知的那樣，$n。我可以跟你保證。', `FemaleText_loc7`='Aquí pasa algo más de lo que sabemos, $n. Te lo garantizo.' WHERE `ID`=43372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다.', `FemaleText_loc4`='谢谢你。', `FemaleText_loc5`='謝謝你。', `FemaleText_loc7`='Gracias.' WHERE `ID`=43373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에루낙 님, 이걸 좀 보십시오. 전에 말씀드렸던 환영 마법에 쓸 만한 중심체가 될 것 같습니다.', `FemaleText_loc4`='埃鲁纳克，来看看这个。还记得我跟你说过的视象法术吗？这看起来像是个有力的证据。', `FemaleText_loc5`='伊魯納克，你看看這個。應該足以當作聚焦的輔助，施展我跟你提過的那道預見魔法。', `FemaleText_loc7`='Erunak, échale un vistazo a esto. Podría ser un foco suficiente para las magias de visión de las que te hablaba.' WHERE `ID`=43374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 지금 바로 마법을 준비하겠습니다. 나가의 목적과 수법에 대해 드디어 알게 될지도 모르겠군요.', `FemaleText_loc4`='那我这就准备施法。这也许总算能让我们对纳迦的手段和意图有所了解。', `FemaleText_loc5`='我會立刻開始準備需要的東西。說不定我們終於可以獲知納迦他們的目的與方法。', `FemaleText_loc7`='Entonces prepararé el encantamiento ahora mismo. Quizá esto arroje por fin un poco de luz sobre los objetivos y las intenciones de los nagas.' WHERE `ID`=43375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론. 가져가게.', `MaleText_loc4`='当然。请便。', `MaleText_loc5`='當然，全都是你的了。', `MaleText_loc7`='Claro. Es todo tuyo.' WHERE `ID`=43376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남김없이 죽인 줄 알았는데... 모르노록 님께서 좋아하시겠군!', `MaleText_loc4`='我以为我们把所有人都杀了……莫诺洛克一定会很开心的！', `MaleText_loc5`='我以為我們已經殺光了所有的人... 莫爾洛克應該會很高興才對!', `MaleText_loc7`='Creía que habíamos matado a todo el mundo... ¡Mor''norokk estará satisfecho con esto!' WHERE `ID`=43377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 바닷속의 전염병 같은 족속이다.', `MaleText_loc4`='你的种族就是海洋的疾病。', `MaleText_loc5`='你的種族是海洋中的病毒。', `MaleText_loc7`='Su raza es una enfermedad para el mar.' WHERE `ID`=43378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵튤론께서 몸을 일으켜 네놈들을 아제로스에서 쓸어버릴 것이다.', `MaleText_loc4`='耐普图隆将会崛起，将你们从艾泽拉斯清除掉。', `MaleText_loc5`='奈普圖隆會起來，把你們的種族從艾澤拉斯抹去!', `MaleText_loc7`='Neptulon se levantará y borrará su especie de Azeroth.' WHERE `ID`=43379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크발디르의 모래로 숨통을 막아 주마!', `MaleText_loc4`='窒息于克瓦迪尔之沙！', `MaleText_loc5`='窒息於科瓦迪爾之沙吧!', `MaleText_loc7`='¡Ahóguense en las arenas de Kvaldir!' WHERE `ID`=43380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시의 주인은 너희가 아닌 파도다!', `MaleText_loc4`='你们该把这座城市还给波涛。', `MaleText_loc5`='你該把這座城市留給海浪。', `MaleText_loc7`='Debieron dejar esta ciudad a las olas.' WHERE `ID`=43381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지?', `MaleText_loc4`='这儿发生什么事了？', `MaleText_loc5`='這裡發生了什麼事?', `MaleText_loc7`='¿Qué ocurre aquí?' WHERE `ID`=43382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔질! 일단 베녹시스부터 부활시키고 나서 네 실패에 대해 이야기하자.', `MaleText_loc4`='赞吉尔！解决温诺希斯，然后我们再来讨论下你的失败。', `MaleText_loc5`='贊吉爾!搞定溫諾希斯，然後我們再來討論你的失敗。', `MaleText_loc7`='¡Zanzil! Acaba con Venoxis y deh''pués hablaremos de tus fracasos.' WHERE `ID`=43383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠다, 진도.', `MaleText_loc4`='是，金度。', `MaleText_loc5`='是，金度。', `MaleText_loc7`='Sí, Jin''do.' WHERE `ID`=43384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너. 내 계획을 방해하는 것도 이게 마지막이다.', `MaleText_loc4`='还有你。你这是最后一次破坏我的计划。', `MaleText_loc5`='還有你。這是你最後一次干擾我的計畫了。', `MaleText_loc7`='Y tú. Eh''ta es la última vez que interfiere'' en mis planes.' WHERE `ID`=43385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 학카르의 참을성이 한계에 다다르고 있다.', `MaleText_loc4`='哈卡变得越来越不耐烦了。我也一样。', `MaleText_loc5`='哈卡已經逐漸失去耐心。而我也是。', `MaleText_loc7`='Hakkar se impacienta. Y yo también.' WHERE `ID`=43386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제클릭을 처치했을지는 모르겠지만 줄구룹에서 살아 돌아가지는 못할 거다.', `MaleText_loc4`='你也许杀死了耶克里克，可你别想活着离开祖尔格拉布。', `MaleText_loc5`='你殺了耶克里克沒錯，但你不會活著離開祖爾格拉布。', `MaleText_loc7`='Quizá hayas mata''o a Jeklik, pero no saldrás de Zul''Gurub con vida.' WHERE `ID`=43387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비해라!', `MaleText_loc4`='准备受死吧！', `MaleText_loc5`='準備受死吧!', `MaleText_loc7`='¡Prepárate a mori''!' WHERE `ID`=43388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 오른쪽을 보시면... 보이시죠? 제 친구가 죽기 직전이라고요!', `FemaleText_loc4`='而且要是你往右侧转一转头，你会看见……我的朋友，就要被杀死了！', `FemaleText_loc5`='如果你看看你的右手邊，你就會看到...我的朋友，就要被殺掉了!', `FemaleText_loc7`='Y si miras a tu derecha verás... a un colega, ¡a punto de ser asesinado!' WHERE `ID`=43389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서요! 사다리를 올라오세요!', `FemaleText_loc4`='快！抓住梯子！', `FemaleText_loc5`='快!快抓住梯子!', `FemaleText_loc7`='¡Rápido! ¡Agárrate a la escalera!' WHERE `ID`=43390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 천천히 몰라고, 항해사.', `MaleText_loc4`='慢慢接近她，二号。', `MaleText_loc5`='慢慢地接近，二副。', `MaleText_loc7`='Éntralo lentamente, número dos.' WHERE `ID`=43391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사! 발사! 물 밖으로 쫓아내 버려!', `MaleText_loc4`='开火！开火！把它轰出水面！', `MaleText_loc5`='開火!開火!把它轟出水面!', `MaleText_loc7`='¡Fuego! ¡Fuego! ¡Háganlos pedazos!' WHERE `ID`=43392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 걱정 말라고, 항해사. 다시 기회가 오겠지. 그리고 우린 준비됐어. 으히히히하하하하!', `MaleText_loc4`='别担心，二号，我们还会有机会。下次我们会准备周全的。', `MaleText_loc5`='別擔心，二副。我們還會有機會的。我們會做好充足的準備。', `MaleText_loc7`='No te preocupes, número dos. Tendremos otra oportunidad. Y estaremos listos.' WHERE `ID`=43393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴에 접근 중입니다.', `MaleText_loc4`='正在接近洞穴，船长。', `MaleText_loc5`='我們正在靠近洞穴，船長。', `MaleText_loc7`='Nos acercamos a la caverna, Capitán.' WHERE `ID`=43394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고가 정확했군요! 괴수는 여기 있습니다...', `MaleText_loc4`='报告是正确的！那头怪兽就在这里……', `MaleText_loc5`='報告說的沒錯!那隻野獸在這...', `MaleText_loc7`='¡Los informes eran acertados! La bestia está aquí…' WHERE `ID`=43395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후후후... 그렇지, 그대로.', `MaleText_loc4`='稳住，二号……', `MaleText_loc5`='穩穩的，二副...', `MaleText_loc7`='Con cuidado, número dos…' WHERE `ID`=43396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴수가 달아났습니다! 갤리윅스의 배때기에 맹세코, 무진장 빨랐습니다!', `MaleText_loc4`='以加里维克斯的黑心肠起誓，那怪兽逃得真快！', `MaleText_loc5`='野獸逃脫了!加里維克斯的屁股啊，牠可真快!', `MaleText_loc7`='¡La bestia escapó, señor! ¡Por Gallywix, qué rápida era!' WHERE `ID`=43397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 몰아라, 항해사.', `MaleText_loc4`='慢慢接近她，二号。', `MaleText_loc5`='慢慢地接近，二副。', `MaleText_loc7`='Éntralo lentamente, número dos.' WHERE `ID`=43398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지, 그대로...', `MaleText_loc4`='稳住，二号……', `MaleText_loc5`='穩穩地，二副...', `MaleText_loc7`='Con cuidado, número dos…' WHERE `ID`=43399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사! 발사! 물 밖으로 쫓아내 버려!', `MaleText_loc4`='开火！开火！把它轰出水面！', `MaleText_loc5`='開火!開火!把它轟出水面!', `MaleText_loc7`='¡Fuego! ¡Fuego! ¡Háganlos pedazos!' WHERE `ID`=43400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마라, 항해사. 다른 기회가 있겠지. 그리고 우린 준비됐어.', `MaleText_loc4`='别担心，二号，我们还有机会。下次我们会准备充分的。', `MaleText_loc5`='別擔心，二副。我們還會有機會的。我們會做好充足的準備。', `MaleText_loc7`='No te preocupes, número dos. Tendremos otra oportunidad. Y estaremos listos.' WHERE `ID`=43401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴에 접근 중입니다, 선장님.', `MaleText_loc4`='我们正在接近洞穴，船长。', `MaleText_loc5`='我們正在靠近洞穴，船長。', `MaleText_loc7`='Nos acercamos a la caverna, Capitán.' WHERE `ID`=43402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고가 정확했군요! 괴수는 여기 있습니다.', `MaleText_loc4`='情报没错！那怪兽就在这儿……', `MaleText_loc5`='報告說得沒錯!那隻野獸在這...', `MaleText_loc7`='¡Los informes eran acertados! La bestia está aquí…' WHERE `ID`=43403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴수가 달아났습니다! 멕카토크의 수염에 맹세코, 무진장 빨랐습니다!', `MaleText_loc4`='怪兽逃跑了！以梅卡托克的胡子起誓，它可真快！', `MaleText_loc5`='野獸逃脫了!梅卡托克的鬍子啊，牠可真快!', `MaleText_loc7`='¡La bestia escapó! ¡Por Mekkatorque, qué rápida era!' WHERE `ID`=43404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 빠져나가기만 하면, 너희 오크 녀석들 후회하게 될 거다.', `MaleText_loc4`='等我离开这儿，你们这群兽人就要倒霉了。', `MaleText_loc5`='等我離開這裡你們獸人一定會後悔。', `MaleText_loc7`='Cuando salga de aquí, los orcos lo vais a lamentar, y mucho.' WHERE `ID`=43405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피눈물을 흘리게 해주마.', `MaleText_loc4`='偿还总是痛苦的。', `MaleText_loc5`='加十倍奉還給你們。', `MaleText_loc7`='Mi venganza os va a doler.' WHERE `ID`=43406;
