UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하드렌치 은신처에 오신 것을 환영합니다!$b$b복잡하고 시끄러운 도시의 삶에서 탈출하고 싶으세요? 그렇다면 잘 오셨습니다!$b$b경이로움으로 가득한 아제로스의 밀림 명소를 직접 체험하고 싶으세요? 멀리에서 찾지 마세요!$b$b갓 뽑아낸 생물 연료나 광석을 구입하고 싶으세요? 그렇다면 잘 오셨습니다, $c님!', `FemaleText_loc4`='欢迎来到硬钳避世乐园！$b$b希望远离纷繁嘈杂的城市生活？那你可来对地方了！$b$b想要亲眼见证艾泽拉斯知名丛林的奇迹胜景？不用去别处了！$b$b想要购买新鲜出炉的生物燃料或武器级矿物？这里一定能满足你的需要，$c！', `FemaleText_loc5`='歡迎來到硬心藏匿處!$b$b想遠離都市生活的塵囂與忙碌?你來對地方了!$b$b想要親自見識艾澤拉斯最出名的叢林奇景?不用再找了!$b$b想要購買剛抽出來的生質燃料品還是軍武等級的高純度礦石嗎?那你就來對地方了，$c!', `FemaleText_loc7`='¡Te doy la bienvenida a los Dominios Velasangre!$b$b¿Buscas un poco de tranquilidad lejos del bullicio de la vida urbana? ¡Has venido al lugar indicado!$b$b¿Quieres ver en persona las maravillas de la famosa jungla de Azeroth? ¡No busques más!$b$b¿Deseas comprar biocombustible recién extraído o mineral para mejorar tus armas? ¡Entonces has venido al lugar indicado, $c!' WHERE `ID`=43410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 대장.', `FemaleText_loc4`='嘿，老大。', `FemaleText_loc5`='嘿，老大。', `FemaleText_loc7`='Eh, $gjefe:jefa;.' WHERE `ID`=43411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와줄까? 혹시 우리 집의 별미라 소문난 마크루라 소스구이를 먹으러 온 거야?', `MaleText_loc4`='您想来点儿什么？要不要尝尝我们的招牌菜芝士焗龙虾？', `MaleText_loc5`='有什麼我能幫忙的嗎?來嚐嚐我們最出名的焗烤蝦怪?', `MaleText_loc7`='¿En qué puedo ayudarte? ¿Has venido a probar nuestra famosa langostrok termidor?' WHERE `ID`=43412;
