UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 혼자 돌아갈 수 있을 것 같소.', `MaleText_loc4`='我想我能自己回去了。', `MaleText_loc5`='我想我應該有辦法自己回去。', `MaleText_loc7`='Creo que podré regresar solo.' WHERE `ID`=43414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 참 이상하게도 생겼구려. 고맙소.', `MaleText_loc4`='你是个长相奇特的家伙。谢谢你。', `MaleText_loc5`='你真是個外貌奇特的生物。謝謝你。', `MaleText_loc7`='Eres una criatura de lo más extraña. Gracias.' WHERE `ID`=43415;
