UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 대신 적들을 처치해 주시오. 괜찮겠소?', `MaleText_loc4`='帮我干掉几个，可以吗？', `MaleText_loc5`='幫我殺幾個，好嗎?', `MaleText_loc7`='Mata unos cuantos más, ¿quieres?' WHERE `ID`=43417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 걱정은 하지 마시오. 국왕 폐하를 구해야 하오!', `MaleText_loc4`='别担心我。我们快去救国王！', `MaleText_loc5`='不必擔心我。我們得救出土靈之王!', `MaleText_loc7`='No te preocupes por mí. ¡Tenemos que rescatar al Rey!' WHERE `ID`=43418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈란, 난민들을 이렇게 남겨놓을 수는 없습니다. 이곳에 있는 부인이 그의 무기와 갑옷을 팔아 난민들에게 줄 음식을 사고 있습니다만, 혼자서는 난민들을 돌볼 수가 없습니다.', `MaleText_loc4`='我们不能不管这些难民，克朗恩。布伊恩已经把他的武器和护甲换成了救助难民的食物。他一个人的力量是不够的。', `MaleText_loc5`='我們不能就這樣拋棄這些難民，基拉安。布恩都已經賣掉武器和護甲來籌錢幫他們買食物了。他沒辦法獨自一個人承擔這件事情。', `MaleText_loc7`='No podemos dejar así a estos refugiados, Kelaan. Buin ha vendido sus armas y su armadura para comprar comida para ellos. No puede hacerlo solo.' WHERE `ID`=43419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지종결자 트로그조르를 처치해야 하오!', `MaleText_loc4`='你要干掉颤地者特罗格佐尔！', `MaleText_loc5`='你得殺掉大地終結者特洛格佐爾!', `MaleText_loc7`='¡Tienes que matar a Troggzor el Terrinator!' WHERE `ID`=43420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가서 보고를 해야겠소. 고맙소, $c 친구!', `MaleText_loc4`='我得赶回去汇报了。谢谢你，$c！', `MaleText_loc5`='我得去回報了。謝謝你，$c!', `MaleText_loc7`='Debo volver a informar. ¡Gracias, $c!' WHERE `ID`=43421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난민들이 겪는 고통을 모르는 척하는 게 아닙니다, 로완. 그렇지만 우리의 임무는 대격변이 어떤 결과를 가져왔는지 알아내는 것입니다. 아제로스 자체가 고통받고 있단 말입니다.', `MaleText_loc4`='我不是对他们的痛苦视而不见，罗旺，可我们来此的任务是了解大灾变所带来的灾难。艾泽拉斯世界正在受苦。', `MaleText_loc5`='我並沒有對他們的苦難視而不見，洛溫。可是，我們的任務是要調查這場大災變造成了什麼影響。連艾澤拉斯本身都受創了。', `MaleText_loc7`='No soy insensible al sufrimiento, Lowan, pero nuestra misión es investigar qué consecuencias ha tenido aquí el Cataclismo. Azeroth mismo sufre.' WHERE `ID`=43422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망의 빛 예배당에 난민들을 돌볼 수 있도록 지원금을 요청했습니다. 임무를 계속 진행하되, 난민들도 최대한 도와주십시오.', `MaleText_loc4`='我已经派人前往圣光之愿礼拜堂来筹措照料难民所需要的资金。执行你的任务，但也请尽全力帮助我们。', `MaleText_loc5`='我已經通報了聖光之願禮拜堂，請他們拿出一筆錢來賑濟這些災民。你願意幫忙是好事，但你還是得繼續執行你的任務。', `MaleText_loc7`='He mandado recado a la Capilla de la Esperanza de la Luz para que nos envíen oro para cuidar de los refugiados. Sigue con tu misión, pero ayuda en todo lo que puedas.' WHERE `ID`=43423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 가빈 신부님. 이렇게 어두운 시대에는 부인과 신부님 같은 분들이 더욱 많이 필요할 겁니다.', `MaleText_loc4`='谢谢你，伽文神父。在这黑暗的时刻，这个世界需要更多像你和布伊恩这样的人。', `MaleText_loc5`='謝謝你，伽文神父。在這個動盪的時刻，這個世界正需要更多像你和布恩這樣的人。', `MaleText_loc7`='Gracias, padre Gavin. En estos tiempos oscuros, el mundo necesita más personas como tú y Buin.' WHERE `ID`=43424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 헛되이 생명이 사라지다니.', `MaleText_loc4`='这么多无谓的损失。', `MaleText_loc5`='太多無意義的損失。', `MaleText_loc7`='Tanta pérdida sin sentido.' WHERE `ID`=43425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시는 당연하게 우리 집안 가업으로 이어져 왔네. 자네가 좀 도와줄 수 있어 보이는군. 낚시왕을 위해 몇 가지 일 좀 처리해주겠나?', `MaleText_loc4`='钓鱼是我家族世代相传的天性。不过你看上去倒像是能帮点儿小忙。替钓鱼者跑跑腿儿怎么样？', `MaleText_loc5`='釣魚對我們家來講向來是很自然的一件事情。但是看來你好像需要一點協助的樣子。要不要幫釣手大師跑跑腿做點事情?', `MaleText_loc7`='La pesca corre en las venas de mi familia. Sin embargo, tú sí parece que necesites ayuda. ¿Qué te parece hacer unos recados para un Maestro pescador?' WHERE `ID`=43426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 죽어라, 이 더러운 녀석!', `MaleText_loc4`='含羞而败吧你这恶心的杂种！', `MaleText_loc5`='該死的雜種，去吃土吧你!', `MaleText_loc7`='¡Muerde el polvo chucho asqueroso!' WHERE `ID`=43427;
