UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거스름돈은 넣어둬라, 이 더러운 짐승 녀석!', `MaleText_loc4`='不用找零了，你这恶心的生物！', `MaleText_loc5`='零錢甭找了，該死的禽獸!', `MaleText_loc7`='¡Y quédate con el cambio, sucio animal!' WHERE `ID`=43432;
