UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도는 아무것도 아니지.', `MaleText_loc4`='我见过比你更强硬的废物。', `MaleText_loc5`='我經歷過更糟的。', `MaleText_loc7`='Me las he visto con boñigas más duras.' WHERE `ID`=43439;
