UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수는 언제나 달콤하지!', `MaleText_loc4`='复仇这道菜，配上“屁股开花”这小吃就完美了！', `MaleText_loc5`='用打屁股來報仇最棒了!', `MaleText_loc7`='¡La venganza es un plato que se sirve mejor con una paliza!' WHERE `ID`=43443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 위해 한 잔! 나를 위해 한 잔! 우린 절대 뜻을 함께한다네.$b$b하지만 배신한다면... 가만두지 않으리! 나를 위하여 건배!', `MaleText_loc4`='你一杯！我一杯！愿我们默契永相随。$b$b可要是没了默契……那你就去死吧！我再来一杯。', `MaleText_loc5`='這杯敬你!這杯敬我!願我們永遠不會吵架。$B$B要是我們吵起來了...你就滾蛋吧你!這杯再敬我。', `MaleText_loc7`='¡Arriba! ¡Abajo! ¡Al centro! ¡Y para dentro!$B$BY si tú no quieres... ¡TE FASTIDIAS! ¡Arriba! ¡Abajo!' WHERE `ID`=43444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 살 수 있는 술을 가지고 계신다고 들었습니다, 슬림.', `MaleText_loc4`='我听说你这儿有喝的东西卖，斯利姆。', `MaleText_loc5`='嘿，威士忌·狡黠，我聽說你那有喝的可以買。', `MaleText_loc7`='He oído que tienes bebidas que puedo comprar, Delgado.', `FemaleText_loc1`='제가 살 수 있는 술을 가지고 계신다고 들었어요, 슬림.', `FemaleText_loc4`='我听说你这儿有喝的东西卖，斯利姆。', `FemaleText_loc5`='嘿，威士忌·狡黠，我聽說你那有喝的可以買。', `FemaleText_loc7`='He oído que tienes bebidas que puedo comprar, Delgado.' WHERE `ID`=43445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 트림을 합니다.', `MaleText_loc4`='%s打了个响嗝儿。', `MaleText_loc5`='%s打了個嗝。', `MaleText_loc7`='%s eructa.' WHERE `ID`=43446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 구명정은 버려진 것 같습니다. 어쩌면 근처의 해적이 쓰던 걸지도 모릅니다.', `MaleText_loc4`='这艘救生船像是被丢弃了。也许它的主人会是附近的海盗？', `MaleText_loc5`='這艘救生艇似乎沒人使用。也許它是附近哪位海盜的?', `MaleText_loc7`='El bote salvavidas parece estar abandonado. ¿Quizá pertenezca a alguno de los piratas cercanos?' WHERE `ID`=43447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 아마 허클베리 스모츠 선장이 말한 그 구명정일 겁니다.', `MaleText_loc4`='这一定就是海克拜瑞·斯莫特船长提到的那艘救生船。', `MaleText_loc5`='這一定就是海克拜瑞·斯莫特船長說的那個救生船。', `MaleText_loc7`='Debe ser el bote salvavidas del que habló el capitán Hecklebury Smotts.' WHERE `ID`=43448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 잠시 회상에 잠겨 이 구명정을 써서 네골라쉬를 처치했을 때를 떠올립니다. 좋은 시절이었습니다.', `MaleText_loc4`='你用片刻时间默默怀念用这艘救生船击败奈古拉什的事。那可真是段美好的日子。', `MaleText_loc5`='你暫且停下手邊動作，默默回想起當時你用這艘救生艇擊敗奈古拉什的過程。那可真是美好的回憶啊。', `MaleText_loc7`='Te tomas un minuto de silencio para recordar el momento en el que usaste el bote salvavidas para derrotar a Negolash. Aquellos fueron buenos tiempos.' WHERE `ID`=43449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<구명정에 음식과 음료를 놓습니다.>', `MaleText_loc4`='<把食物和饮料放进救生船里。>', `MaleText_loc5`='<將食物和水放進救生船中。>', `MaleText_loc7`='<Pon la comida y la bebida en el bote salvavidas.>', `FemaleText_loc1`='<구명정에 음식과 음료를 놓습니다.>', `FemaleText_loc4`='<把食物和饮料放进救生船里。>', `FemaleText_loc5`='<將食物和水放進救生船中。>', `FemaleText_loc7`='<Pon la comida y la bebida en el bote salvavidas.>' WHERE `ID`=43450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아, 난 놈들의 이름이 왜 오크인지가 궁금해 죽겠어.', `MaleText_loc4`='你知道，我一直不明白为什么他们要叫自己兽人。', `MaleText_loc5`='你知道嗎，我一直在想，為什麼要把他們叫做獸人。', `MaleText_loc7`='Sabes, siempre me he preguntado por qué se llaman a sí mismos "orcos".' WHERE `ID`=43451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이름만으로도 막 지저분한 느낌이 들지 않아? 꼭 똥 싸는 모습을 나타내는 말 같다니까. 예를 들면 이런 거지.', `MaleText_loc4`='这是个非常不雅的词汇，你知道吗？我常把这个词和上大号联系在一起。比如说：', `MaleText_loc5`='實在是不太正確，你知道嗎?他們應該叫『臭屎』才對的。比如說:', `MaleText_loc7`='Es una palabra fea, ¿no crees? Es la palabra que yo utilizaría para referirme a algo relacionado con defecar. Por ejemplo:' WHERE `ID`=43452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순례자의 감사절에 푸짐한 저녁 식사를 하고, 구린내 나는 오크를 왕창 쌌다.', `MaleText_loc4`='在享用完感恩节大餐后，我美美地拉了坨又大又臭的大便。', `MaleText_loc5`='吃完旅人豐年祭的大餐，我挫了超大一坨的臭屎。', `MaleText_loc7`='Después de la cena de la Generosidad, solté un enorme y apestoso orco.' WHERE `ID`=43453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 도움이 되고자 이곳에 왔지만, 저들의 신뢰가 아직 우리까지 미치지는 않은 것 같습니다.', `MaleText_loc4`='我们来这儿是想要帮忙的，可看来他们对你的好感还没有延及我们。', `MaleText_loc5`='我們來這試著想幫忙，但看起來他們對你的歡迎並沒有延伸到我們身上。', `MaleText_loc7`='Hemos venido para intentar ayudar, pero al parecer que tú les caigas bien no significa que nosotros también.' WHERE `ID`=43454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 보고 싶었네, 댄포스.', `MaleText_loc4`='我真的很想念你，丹弗斯。', `MaleText_loc5`='我真的很想你，丹佛斯。', `MaleText_loc7`='De verdad que te he echado de menos, Danforth.' WHERE `ID`=43455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키샨하고 호숫골 다리로 낚시하러 갔던 때가 생각나는군. 거기서 키샨이 방귀를 한 방 시원하게 뀌었지. 오슬로는 그때 이후로 두고두고 키샨을 미워하더군...', `MaleText_loc4`='我记得有一次，基沙恩和我到湖畔镇的桥上钓鱼，然后基沙恩突然放了个屁。我想奥斯洛在那件事情上永远都不会原谅基沙恩……', `MaleText_loc5`='我還記得有一次，基沙恩和我在湖畔鎮大橋上釣魚，然後基沙恩放了個屁。那個屁臭到奧斯洛到現在都還不肯原諒基沙恩...', `MaleText_loc7`='Recuerdo una vez en la que Keeshan y yo estábamos pescando en el puente de Villa del Lago y Keeshan se tiró un pedo. Oslow jamás perdonó a Keeshan por aquello...' WHERE `ID`=43456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 어디서 들었을지 모르지만, 검은바위 오크들이 키샨의 아내를 살해했다네. 그 이후로 키샨은 완전히 다른 사람이 됐어. 키샨의 인생에서 해가 저물었다고나 할까. 어둠... 완전한 어둠만이 남게 되었지.', `MaleText_loc4`='你知道，黑石兽人夺走了基沙恩的妻子。在那件事情发生后他就像变了个人似的。仿佛他生命中的太阳瞬间陨落。只剩下黑暗，$g老兄:女士;。纯粹的黑暗。', `MaleText_loc5`='你知道嘛，$g兄弟:小姐;，基沙恩的太太就是被黑石獸人害死的。從那天之後他整個人就變了，好像他生命裡的太陽已經下山，只剩下夜晚。漆黑的夜晚。', `MaleText_loc7`='Keeshan perdió a su mujer a manos de los orcos Roca Negra, sabes. Después de aquello, nunca fue el mismo. Era como si el sol se hubiera puesto en su vida. Oscuridad, $gseñor:señora;. Pura oscuridad.' WHERE `ID`=43457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들은 우리를 불곰 중대라고 불렀다네. 괴물 처치가 필요할 때면 항상 우리가 나서서... 피를 봐야 했지.', `MaleText_loc4`='他们把我们叫做B连。当有杀戮任务时，我们负责让血……流成河。', `MaleText_loc5`='我們被稱為第二連隊。當我們收到抹殺的命令，我們就讓目標血濺四地。', `MaleText_loc7`='Nos llamaban la Compañía Bravo. Cuando hacía falta matar cosas, nosotros nos dedicábamos a derramar... la sangre.' WHERE `ID`=43458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메스너는 화염 마법의 달인이야. 바비큐 요리를 할 때면 항상 그를 초대하곤 하지.', `MaleText_loc4`='梅森纳是火焰法术的大师。我们每次烧烤都会邀请他来助阵。', `MaleText_loc5`='梅斯納是火焰的魔法大師。我們每當有烤肉派對就會邀請他。', `MaleText_loc7`='Messner es el genio de la magia de fuego. Le invitamos a todas nuestras barbacoas.' WHERE `ID`=43459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 참고로 요르겐센은 정말 소심한 성기사라네. 그 녀석 앞에선 자네도 말조심하지 않으면, 녀석이 울음을 터뜨릴지도 몰라.', `MaleText_loc4`='顺便说一句，约根森是位真正的雅士。他是位圣骑士，所以在他身边说话时要小心点儿，否则你很可能会令他抓狂。', `MaleText_loc5`='喬更森是個小帥哥。他是個聖騎士，所以在他旁邊的時候講話最好小心一點，否則你可能會把他弄哭。', `MaleText_loc7`='A todo esto, Jorgensen es realmente delicado. Es un paladín, así que ten cuidado con lo que dices o es posible que le hagas llorar.' WHERE `ID`=43460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린이 돌아왔다는 말이 있던데, 사실인가? 미안하지만 내가 요즘 소식에 어두워서 말이야.', `MaleText_loc4`='我听说瓦里安·乌瑞恩回来了。是真的吗？不好意思，我有点儿闭塞了。', `MaleText_loc5`='我聽說瓦里安·烏瑞恩回來了，是真的嗎?不好意思，我的消息不太靈通。', `MaleText_loc7`='He oído que Varian Wrynn ha vuelto. ¿Es verdad? Lo siento, estoy un poco desinformado.' WHERE `ID`=43461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은마루 산맥 사람들이 정말 치졸하다는 생각이 들지 않던가? 나도 그 멍청한 솔로몬의 마을 회관에 확 불이라도 놓고 싶다는 생각이 들 때가 많아.', `MaleText_loc4`='你有没有注意到赤脊山那儿的人有多尖刻？有时我真觉得我要一把火烧了所罗门那蠢货的城镇大厅。', `MaleText_loc5`='你沒注意到住在赤脊山的人都很刻薄嗎?我有時真想拿把火把所羅門那王八蛋的市政廳給燒了。', `MaleText_loc7`='¿Nunca te has dado cuenta de lo sarcásticos que son los que viven en Crestagrana? A veces siento la tentación de pegarle fuego al Concejo de ese imbécil de Solomon.' WHERE `ID`=43462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러야 합니다, 고르툴. 이자를 풀어주세요.', `FemaleText_loc4`='赶快，格索乌。解开$g他的:她的;镣铐。', `FemaleText_loc5`='快點，戈瑟爾。解開$g他:她;。', `FemaleText_loc7`='Date prisa, Gothul. Deshaz sus ataduras.' WHERE `ID`=43463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 자네의 장비를 빼내 왔네. 상황이 어떤지는 충분히 봤겠지.', `FemaleText_loc4`='$n，我已为你找回了装备。我想你已经看到你所需要看到的一切。', `FemaleText_loc5`='我還幫你把裝備拿回來了，$n。我想你應該已經全部看夠了。', `FemaleText_loc7`='$n, he recuperado tu equipo. Creo que ya has visto todo lo que necesitas ver.' WHERE `ID`=43464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸이 안 좋아요. 평소보다 더 안 좋다고요. 이번 주 들어 빛의 힘이 약해지기라도 한 것 같아요. 아마 뭘 잘못 먹었겠죠. 오크 음식은 생각만 해도 욕지기가 나네요.', `MaleText_loc4`='我感到很虚弱。我是说比平时还要虚弱。这星期的圣光像是又无力了许多。也许和我吃的东西有关。兽人的食物让我觉得恶心。', `MaleText_loc5`='我覺得很虛弱。我是說，比平常還要更虛弱。好像聖光的力量這個禮拜也變弱了。有可能只是我吃壞了肚子。獸人的食物老是害我拉肚子。', `MaleText_loc7`='Me siento débil. Quiero decir, más de lo normal. Como si esta semana la Luz fuera menos poderosa. Quizá sea solo algo que he comido. La comida de orco me sienta fatal.' WHERE `ID`=43465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크를 처치하는 키샨의 모습을 본 적 있나요? 정말 볼 만한 광경이라니까요.', `MaleText_loc4`='你见过基沙恩消灭兽人的情景吗？那可真是壮观啊，$g老兄:女士;。', `MaleText_loc5`='你有看過基沙恩殺獸人的樣子嗎?場面可精采的咧，$g先生:女士;。', `MaleText_loc7`='¿Alguna vez has visto a Keeshan matar un orco? Es algo digno de ver, $gseñor:señora;.' WHERE `ID`=43466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억하게, $n. 모든 용아귀 부족이 자네의 적은 아니라네!', `FemaleText_loc4`='记住，$n。并非所有的龙喉成员都是你的敌人！', `FemaleText_loc5`='記住，$n。並非所有的龍喉獸人都是你的敵人!', `FemaleText_loc7`='Recuerda, $n. No todos los Faucedraco son tus enemigos.' WHERE `ID`=43467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 동료들이 다시 모이게 되었다는 사실이 믿어지지 않네요. 모두 당신 덕분입니다, $n.', `MaleText_loc4`='真是难以置信，我们居然又把过去的队伍集结在一起了。这都要感谢你，$n。', `MaleText_loc5`='不敢相信我們這些老隊友又重聚了。這都要謝謝你，$n。', `MaleText_loc7`='No puedo creer que volvamos a reunir al viejo grupo. Todo gracias a ti, $n.' WHERE `ID`=43468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 호드를 떠났다고 하더군요. 사실인가요?', `MaleText_loc4`='我听说萨尔离开了部落。是真的吗？', `MaleText_loc5`='我聽說索爾離開部落了。是真的嗎?', `MaleText_loc7`='He oído que Thrall ha abandonado la Horda. ¿Es cierto?' WHERE `ID`=43469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아요, 헬스크림이 호드로 돌아왔다는 이야기를 검은바위 오크들이 거듭 하더라고요. 그게 무슨 얘기죠? 헬스크림은 죽지 않았나요?', `MaleText_loc4`='你知道，我一直听那些黑石兽人说，关于地狱咆哮返回部落的事。那究竟是怎么回事？地狱咆哮不是死了吗？', `MaleText_loc5`='你知道，我一直聽到黑石獸人在講什麼地獄吼重回部落了。那到底是怎麼回事?地獄吼不是早就死了嗎?', `MaleText_loc7`='Sabes, no dejo de oír rumores entre los orcos Roca Negra de que Grito Infernal regresa a la Horda. ¿De qué va todo eso? ¿Grito Infernal no está muerto?' WHERE `ID`=43470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마 제가 이 팀에서 가장 중요한 사람일걸요? 성기사이기도 하고, 또 뭐, 이런저런 이유가 있어요.', `MaleText_loc4`='我可能是这队伍中最重要的成员了——我的圣骑士和所有其它身份。', `MaleText_loc5`='我應該是這個隊伍裡最重要的角色，因為我是個聖騎士。', `MaleText_loc7`='Soy el miembro más importante de este grupo, ya que soy un paladín y todo eso.' WHERE `ID`=43471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 녀석들이 우리 솜씨를 맛볼 때까지 기다려 보게. 불곰 중대 현역 복귀다!', `MaleText_loc4`='等这些兽人注意到我们。B连重操旧业！', `MaleText_loc5`='看我們怎樣教訓這些獸人。第二連隊重出江湖啦!', `MaleText_loc7`='Espera a que esos orcos se vean las caras con nosotros. La Compañía Bravo, ¡VUELVE A ESTAR EN ACTIVO!' WHERE `ID`=43472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 파도의 왕좌로 순간이동시켜 주십시오!', `MaleText_loc4`='我在小队中，并已准备好传送到潮汐王座！', `MaleText_loc5`='我已經組好隊伍，而且準備好傳送到海潮王座了!', `MaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme al Trono de las Mareas!', `FemaleText_loc1`='저와 파티원 모두 준비되었습니다. 파도의 왕좌로 순간이동시켜 주십시오!', `FemaleText_loc4`='我在小队中，并已准备好传送到潮汐王座！', `FemaleText_loc5`='我已經組好隊伍，而且準備好傳送到海潮王座了!', `FemaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme al Trono de las Mareas!' WHERE `ID`=43473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그 스톰윈드의 끝내주는 아가씨는 어떻게 됐어? 이름이 여군주 프레스톨이었나?', `MaleText_loc4`='那么暴风城里那个小可爱怎么样了？她叫女伯爵普瑞斯托。', `MaleText_loc5`='暴風城裡的那個辣妹怎麼不見了?叫普瑞斯托女士的那個。', `MaleText_loc7`='¿Qué pasó con ese bomboncito de Ventormenta? Se llamaba Lady Prestor.' WHERE `ID`=43474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군. 엉덩이가 아파. 왜 그런지 모르겠네.', `MaleText_loc4`='真奇怪。我的屁股好疼。疼得莫名其妙。', `MaleText_loc5`='真奇怪，我的屁股好痛，但不確定為什麼。', `MaleText_loc7`='Es raro. Me duele el culo. Y no estoy seguro de por qué.' WHERE `ID`=43475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도의 왕좌는 79에서 81 레벨의 플레이어들이 진입하여 초기 테스트할 수 있습니다. 이 던전은 많은 부분 작업 중에 있으며, 최종 우두머리 몬스터는 만나볼 수 없습니다. 파도의 왕좌로 순간이동하기 전에 전체 공격대가 갖춰져 있는지 확인하시기 바랍니다.

파도의 왕좌에서 나오려면, 던전의 일반적인 출구를 빠져나와 달라란으로 순간이동하게 됩니다. 죽어서 다시 살아나게 되면, 제가 있는 곳으로 순간이동해 돌아오게 될 겁니다.', `MaleText_loc4`='现在可以参与潮汐王座的初始测试了，这是位于瓦丝琪尔的一座79-81级地下城。这座地下城目前仍处于开发过程中，与最终首领的战斗尚无法进行。请在传送至地下城之前组满队伍。集合石目前对该地下城不可用。

若要离开潮汐王座，只需从位于地下城内的普通出口离开即可，你将被自动传送至达拉然。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。', `MaleText_loc5`='海潮王座現在已可進行測試。海潮王座位於瓦許伊爾，是一座等級79-81的地城。本地城依然在建構中，最終首領亦尚未置入地城裡。本地城的集合石功能尚未建構完成，因此請先組好完整隊伍再傳送進地城。

如要離開海潮王座，請從地城內正常的出口離開，你就會被傳送到達拉然。倘若不幸死亡並已釋放靈魂，你可以從這位NPC處傳送回去。', `MaleText_loc7`='El Trono de las Mareas, una mazmorra de nivel 79-81 en Vashj''ir, ya está disponible para pruebas. Antes de teletransportarte a la mazmorra, asegúrate de que el grupo está formado. Las rocas de encuentro para esta mazmorra todavía no están disponibles.

Para abandonar El Trono de las Mareas, simplemente sal por la salida normal dentro de la mazmorra y serás teletransportado a Dalaran. Si mueres y liberas espíritu, puedes teletransportarte de nuevo con este PNJ.' WHERE `ID`=43476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키샨은 좋은 친구라네, $n. 우리 중 누구라도 그를 위해서라면 목숨을 바칠 수 있어.', `MaleText_loc4`='基沙恩是个好人，$n。我们所有人都甘愿为他卖命。', `MaleText_loc5`='基沙恩是個好人，$n。我們每個人都願意把性命交給他。', `MaleText_loc7`='Keeshan es un buen hombre, $n. Cualquiera de nosotros daría su vida por él.' WHERE `ID`=43477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 일이 다 끝나면, 길게 휴가를 갈 생각이야.', `MaleText_loc4`='等这一切都尘埃落定之后，我要度假休息段日子。', `MaleText_loc5`='等這一切結束之後，我要去度個假。', `MaleText_loc7`='Cuando todo esto termine, me iré de vacaciones.' WHERE `ID`=43478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파도의 왕좌로 절 보내주십시오!', `MaleText_loc4`='送我回到潮汐王座！', `MaleText_loc5`='送我回海潮王座!', `MaleText_loc7`='¡Llévame de vuelta al Trono de las Mareas!', `FemaleText_loc1`='파도의 왕좌로 절 보내주십시오!', `FemaleText_loc4`='送我回到潮汐王座！', `FemaleText_loc5`='送我回海潮王座!', `FemaleText_loc7`='¡Llévame de vuelta al Trono de las Mareas!' WHERE `ID`=43479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키샨은 우리 생명의 은인이야. 모두의 목숨을 수백 번은 구해 줬을걸.', `MaleText_loc4`='我们的命都属于基沙恩。他已经救过我们无数次了。', `MaleText_loc5`='我們都欠基沙恩一命。他救了我們不知道幾次了。', `MaleText_loc7`='Todos le debemos nuestras vidas a Keeshan. Nos ha salvado el trasero cientos de veces.' WHERE `ID`=43480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업이 마법사라 좋은 점도 있지. 하지만 세탁비 하나는 정말 끔찍하다고.', `MaleText_loc4`='当法师有当法师的好处，可那高昂的洗衣账单可真让人头痛。', `MaleText_loc5`='作為一個法師是有優勢的，但要付天價的洗衣費。', `MaleText_loc7`='Ser un mago tiene sus ventajas, pero las facturas de la lavandería se ponen siempre por las nubes.' WHERE `ID`=43481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 참, 호숫골에 있는 다리는 어떻게 됐어? 오슬로가 완성하긴 했나?', `MaleText_loc4`='那湖畔镇的那座桥后来怎么样了？奥斯洛把它造完了吗？', `MaleText_loc5`='那麼，湖畔鎮的橋現在狀況如何?奧斯洛到底蓋好了沒?', `MaleText_loc7`='Entonces, ¿qué pasa con el puente de Villa del Lago? ¿Oslow terminó de construirlo en algún momento?' WHERE `ID`=43482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일이 끝나면 달라란으로 갈 생각이야. 그 아름답던 도시를 살려내는 데 도움을 주고 싶어.', `MaleText_loc4`='等这一切都结束后，我也许会去达拉然。帮他们重新把那座城市复建得风生水起。', `MaleText_loc5`='等這件事結束之後，我想我應該會去一趟達拉然。幫他們把整座城弄浮起來。', `MaleText_loc7`='Creo que cuando esto termine iré a Dalaran. Les ayudaré a levantar esa ciudad para que vaya viento en popa.' WHERE `ID`=43483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화장실 좀 가야겠어.', `MaleText_loc4`='我需要用下洗手间。', `MaleText_loc5`='我需要使用洗手間。', `MaleText_loc7`='Tengo que ir al baño.' WHERE `ID`=43484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불곰 중대가 돌아왔으니 오크 녀석들 제삿날이 머지않았어.', `MaleText_loc4`='一旦B连重新回来投入工作，这些兽人必会猛然觉醒。', `MaleText_loc5`='等第二連隊回來時，這些獸人就會皮開肉綻了。', `MaleText_loc7`='Cuando la Compañía Bravo vuelva a estar en activo, esos orcos van a tener un despertar muy movidito.' WHERE `ID`=43485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유명한 노겐포저의 비약 팔아요!$B$B천연 재료로 만들어 직접 발효시킨 뒤 병에 담았답니다! 이곳 가젯잔에서만 구하실 수 있어요. 맛있는 건 두말할 것도 없답니다!', `FemaleText_loc4`='世界闻名的诺格弗格药剂此处有售！$B$B由纯天然材料萃取炼制而成，只在加基森当地装瓶销售！而且口感顶呱呱——这是当然的！', `FemaleText_loc5`='世界聞名的諾格弗格藥劑在此開賣!$B$B由各種天然原料手工調製，在加基森本地裝瓶販售。而且當然啦，口味絕佳!', `FemaleText_loc7`='¡Aquí se vende el mundialmente famoso elixir de Tragonublo!$B$BHecho en casa con ingredientes naturales, embotellado y vendido aquí mismo, en Gadgetzan. ¡Y está riquísimo, por supuesto!' WHERE `ID`=43486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노겐포저로 하겠습니다!', `MaleText_loc4`='我要诺格弗格！', `MaleText_loc5`='給我一份諾格弗格藥劑!', `MaleText_loc7`='¡Haz el mío, Tragonublo!', `FemaleText_loc1`='노겐포저로 하겠습니다!', `FemaleText_loc4`='我要诺格弗格！', `FemaleText_loc5`='給我一份諾格弗格藥劑!', `FemaleText_loc7`='¡Haz el mío, Tragonublo!' WHERE `ID`=43487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 말로리악. 네가 실험실이라 부르는 그 감옥 같은 곳에서 마침내 나와 줘서 기쁘군. 이번엔 뭘 가져왔나?', `MaleText_loc4`='啊，马洛拉克。你可算从那间被你叫做实验室的隔离屋走出来了，你这次有什么成果？', `MaleText_loc5`='啊，瑪洛里亞克。你終於從你那個所謂的實驗室出來了。這次你又有什麼成果啦?', `MaleText_loc7`='Ah, Maloriak. Qué cortés de tu parte salir de ese laboratorio que te acapara. ¿Qué tienes esta vez?' WHERE `ID`=43488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣기 좋은 소리로군. 말해 봐라.', `MaleText_loc4`='当然可以，我洗耳恭听。', `MaleText_loc5`='當然了，我洗耳恭聽。', `MaleText_loc7`='Adelante, ilústrame.' WHERE `ID`=43489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 이 실험은 완전히 실패한 것 같군. 저놈은 눈이 멀어 버린 것 같다! 놈을 봐라!', `MaleText_loc4`='看来你的实验失败了。那小龙已经完全瞎了！你看看他。', `MaleText_loc5`='看來你的實驗失敗了。那隻幼龍已經完全失明了。看看牠。', `MaleText_loc7`='Parece que tu experimento ha fallado. ¡Esa cría está totalmente ciega! Mírala.' WHERE `ID`=43490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보란 말이다!', `MaleText_loc4`='看看他！', `MaleText_loc5`='看看牠!', `MaleText_loc7`='¡MÍRALO!' WHERE `ID`=43491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 잠깐.', `MaleText_loc4`='不，还没有。', `MaleText_loc5`='不，先不要。', `MaleText_loc7`='No, aún no.' WHERE `ID`=43492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 화풀이 상대로 삼으려는 그 녀석이... 쓸모 있을지도 모르겠다.', `MaleText_loc4`='你这失败的作品也许……对我……还有点儿价值。', `MaleText_loc5`='你感到懊惱的這個東西對我而言還有點...用處。', `MaleText_loc7`='Este objeto de tu disgusto puede resultar... valioso... para mí.' WHERE `ID`=43493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러가 봐라, 한심한 놈. 다음엔 어떤 비참한 결과를 보여줄지 기대하마.', `MaleText_loc4`='走吧，可悲的炼金师。我急切地期待着你的下一次失败。', `MaleText_loc5`='去吧，可悲的鍊金師。我等著你下一回的失敗。', `MaleText_loc7`='Vete, alquimista patético. Espero ansioso tu próximo fracaso.' WHERE `ID`=43494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심려를 끼쳐 드려 참으로 죄송합니다, 주군이시여. 하지만 이번엔 대단히 흥미를 보이실 만한 결과가 있습니다!', `MaleText_loc4`='打扰了您，我深表歉意，我的主人。但我相信，我这儿有您非常感兴趣的东西！', `MaleText_loc5`='為打擾到您致上最衷心的歉意，主人。但我相信我有您會非常感興趣的東西!', `MaleText_loc7`='Mis sinceras disculpas por la molestia, mi señor. ¡Pero creo que tengo algo que le interesará mucho!' WHERE `ID`=43495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입죠!', `MaleText_loc4`='是的，是的！', `MaleText_loc5`='是的，是的!', `MaleText_loc7`='¡Sí, sí!' WHERE `ID`=43496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다양한 용족의 피에서 갖가지 요소를 추출해 연고를 하나 만들어냈습니다. 이 연고를 바르면 아주 특별한 시각을 지니게 됩니다!', `MaleText_loc4`='我从各种巨龙军团成员的血液里精炼出萃取物，制成药膏，可以使涂抹者获得视野之外的视野！', `MaleText_loc5`='我提取了各種巨龍的血液媒介並製造了一種能使人擁有全知力量的藥膏!', `MaleText_loc7`='¡Con los agentes extraídos de la sangre de varios Vuelos creé un bálsamo que le dará a su portador una visión excepcional!' WHERE `ID`=43497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오! 실험 번호 25463-D의 결과물입니다!', `MaleText_loc4`='我授予你实验代号——25463-D！', `MaleText_loc5`='我為你呈現實驗體編號25463-D!', `MaleText_loc7`='¡Les presento el experimento 25463-D!' WHERE `ID`=43498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 일이?! 당장 녀석을 처리하겠습니다!', `MaleText_loc4`='这怎么可能？！我马上解决他！', `MaleText_loc5`='怎麼會這樣?!我會立刻處理掉他!', `MaleText_loc7`='¡¿Cómo pudo ser?! ¡Lo despacharé inmediatamente!' WHERE `ID`=43502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 베풀어 주십시오, 주인님.', `MaleText_loc4`='我乞求你的仁慈，大人。', `MaleText_loc5`='主人，求你原諒。', `MaleText_loc7`='Suplico clemencia, mi señor.' WHERE `ID`=43503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과는 거래할 수 없소, $c. 대족장님의 명령이오.', `MaleText_loc4`='我不能和你做交易，$c。这是酋长的命令。', `MaleText_loc5`='這位$c，我不能跟你做生意。大酋長的命令。', `MaleText_loc7`='No puedo hacer negocios contigo, $c. Órdenes del Jefe de guerra.', `FemaleText_loc1`='당신과는 거래할 수 없습니다, $c님. 대족장님의 명령입니다.', `FemaleText_loc4`='我不能和你做交易，$c。这是酋长的命令。', `FemaleText_loc5`='這位$c，我不能跟你做生意。大酋長的命令。', `FemaleText_loc7`='No puedo hacer negocios contigo, $c. Órdenes del Jefe de guerra.' WHERE `ID`=43504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신한테는 아무것도 팔 수 없소.', `MaleText_loc4`='我这儿没什么东西可以卖给你。', `MaleText_loc5`='我沒有任何東西可以賣給你。', `MaleText_loc7`='No tengo nada que me permitan venderte.', `FemaleText_loc1`='당신한테는 아무것도 팔 수 없습니다.', `FemaleText_loc4`='我这儿没什么东西可以卖给你。', `FemaleText_loc5`='我沒有任何東西可以賣給你。', `FemaleText_loc7`='No tengo nada que me permitan venderte.' WHERE `ID`=43505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼지시오, $c! 내가 당신과 거래했다고 집행자들이 오해하면 곤란하오...', `MaleText_loc4`='走开，$c！我可不想让执行者看见我在和你做交易……', `MaleText_loc5`='走開，$c!我不想讓執行者他們看到我在跟你做生意...', `MaleText_loc7`='¡Piérdete, $c! No quiero que los déspotas me vean haciendo negocios contigo...', `FemaleText_loc1`='저리 가세요, $c님! 제가 당신과 거래했다고 집행자들이 오해하면 곤란합니다...', `FemaleText_loc4`='走开，$c！我可不想让执行者看见我在和你做交易……', `FemaleText_loc5`='走開，$c!我不想讓執行者他們看到我在跟你做生意...', `FemaleText_loc7`='¡Piérdete, $c! No quiero que los déspotas me vean haciendo negocios contigo...' WHERE `ID`=43506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가시오. 내가 호드의 일원과 이야기하는 걸 대족장님이 보시면 경을 칠 거요.', `MaleText_loc4`='滚开，我不想让酋长发现我在跟部落的人说话。', `MaleText_loc5`='走開，我不想讓大酋長知道我在跟部落的人講話。', `MaleText_loc7`='Largo, no quiero que el Jefe de guerra se entere de que he estado hablando con la Horda.', `FemaleText_loc1`='저리 가세요. 제가 호드의 일원과 이야기하는 걸 대족장님이 보시면 경을 칠 거예요.', `FemaleText_loc4`='滚开，我不想让酋长发现我在跟部落的人说话。', `FemaleText_loc5`='走開，我不想讓大酋長知道我在跟部落的人講話。', `FemaleText_loc7`='Largo, no quiero que el Jefe de guerra se entere de que he estado hablando con la Horda.' WHERE `ID`=43507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에게 팔 물건 따윈 없소. 불만 있소? 그럼 대족장님께 이야기하시오!', `MaleText_loc4`='我不会把商品卖给部落。你不满意？那去找酋长吧！', `MaleText_loc5`='我的東西不賣給部落的人。不滿意?去跟大酋長告狀啊!', `MaleText_loc7`='Mis mercancías no están a la venta para la Horda. ¿No te gusta? ¡Pues quéjate al Jefe de Guerra!', `FemaleText_loc1`='호드에게 팔 물건 따윈 없습니다. 불만 있나요? 그럼 대족장님께 이야기하세요!', `FemaleText_loc4`='我不会把商品卖给部落。你不满意？那去找酋长吧！', `FemaleText_loc5`='我的東西不賣給部落的人。不滿意?去跟大酋長告狀啊!', `FemaleText_loc7`='Mis mercancías no están a la venta para la Horda. ¿No te gusta? ¡Pues quéjate al Jefe de Guerra!' WHERE `ID`=43508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르 대족장님께서 호드와 거래하지 말라고 명령하셨소.$B$B<화난 듯이 바닥에 침을 뱉고는 당신과 대화하길 거부하는 상인>', `MaleText_loc4`='莫格霍尔酋长不许我们和部落做生意。$B$B<商人暴怒地朝地上吐了口口水，拒绝再对这话题有任何回应。>', `MaleText_loc5`='大酋長莫格下令我們不准跟部落的人做生意。$B$B<商人在地上啐了一口，十分生氣，但拒絕再發表任何評論。>', `MaleText_loc7`='El jefe de guerra Mor''ghor nos ha ordenado que no hagamos negocios con la Horda.$B$B<El mercader escupe al suelo, enfurecido, pero se niega a hablar más del tema.>', `FemaleText_loc1`='모르고르 대족장님께서 호드와 거래하지 말라고 명령하셨어요.$B$B<화난 듯이 바닥에 침을 뱉고는 당신과 대화하길 거부하는 상인>', `FemaleText_loc4`='莫格霍尔酋长不许我们和部落做生意。$B$B<商人暴怒地朝地上吐了口口水，拒绝再对这话题有任何回应。>', `FemaleText_loc5`='大酋長莫格下令我們不准跟部落的人做生意。$B$B<商人在地上啐了一口，十分生氣，但拒絕再發表任何評論。>', `FemaleText_loc7`='El jefe de guerra Mor''ghor nos ha ordenado que no hagamos negocios con la Horda.$B$B<El mercader escupe al suelo, enfurecido, pero se niega a hablar más del tema.>' WHERE `ID`=43509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 기분 그렇게 좋지 않아.', `MaleText_loc4`='我感觉不太好……', `MaleText_loc5`='歐弗不舒服...', `MaleText_loc7`='Yo no sentir bien.' WHERE `ID`=43512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신을 도울 수 없소, $c. 우리 와이번을 호드가 이용하게 해주면 대족장 모르고르가 날 처형할 거요.$B$B하지만 언젠가는 그도 종말을 맞을 거요...', `MaleText_loc4`='我帮不了你的忙，$c。要是我敢把我们的双足飞龙借给部落使用，莫格霍尔酋长会把我处死的。$B$B总有一天他会得到他应得的……', `MaleText_loc5`='我幫不了你，$c。要是我讓部落的人搭乘我們的雙足飛龍，大酋長莫格會把我的頭給砍了。$B$B總有一天他會有報應的...', `MaleText_loc7`='No puedo ayudarte, $c. El jefe de guerra Mor''ghor me ejecutaría si permitiera que la Horda utilizara uno de nuestros jinetes del viento.$B$BAlgún día recibirá lo que se merece...' WHERE `ID`=43513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 필멸의 세상 너머를 볼 수 있지요!', `MaleText_loc4`='超越一切凡人的感知力！', `MaleText_loc5`='超越凡人世界的感知能力!', `MaleText_loc7`='¡Y sentidos ajenos a los mortales!' WHERE `ID`=43514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유레카!', `MaleText_loc4`='有了！', `MaleText_loc5`='太棒了!', `MaleText_loc7`='¡Eureka!' WHERE `ID`=43515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장이 우리를 부르고 있는 것 같군요.', `MaleText_loc4`='看来我们还有场胜仗要打。', `MaleText_loc5`='看來有場戰爭等我們去打贏。', `MaleText_loc7`='Parece que tenemos una guerra que ganar.' WHERE `ID`=43516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저승사자 나가신다!', `MaleText_loc4`='痛苦号列车来了！', `MaleText_loc5`='狠角色上場了!', `MaleText_loc7`='¡SE ACERCA UN MUNDO DE DOLOR!' WHERE `ID`=43517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조니가 돌아왔다, 얘들아!', `MaleText_loc4`='强尼回来了，宝贝儿！耶！', `MaleText_loc5`='約翰·基沙恩回來啦，寶貝!耶!', `MaleText_loc7`='¡JOHNNY HA VUELTO! ¡SÍ, SEÑOR!' WHERE `ID`=43518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...방금 신비한 개인 조수에 대해 말씀하셨습니까?', `MaleText_loc4`='呃……你刚提到了什么私人奥术助手？', `MaleText_loc5`='呃...你有提到什麼個人秘法助手嗎?', `MaleText_loc7`='Eh... ¿has dicho algo sobre un Ayudante Arcano personal?', `FemaleText_loc1`='...방금 신비한 개인 조수에 대해 말씀하셨습니까?', `FemaleText_loc4`='呃……你刚提到了什么私人奥术助手？', `FemaleText_loc5`='呃...你有提到什麼個人秘法助手嗎?', `FemaleText_loc7`='Eh... ¿has dicho algo sobre un Ayudante Arcano personal?' WHERE `ID`=43519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이들아! 여왕에게서 도망치면 끔찍한 결과가 있으리라!', `MaleText_loc4`='懦夫！面对龙巢之母或是万劫不复！', `MaleText_loc5`='懦夫!面對黑龍公主，不然就面對更糟的下場!', `MaleText_loc7`='¡Cobardes! ¡Enfrenten a la madre del linaje o SUFRAN las consecuencias!' WHERE `ID`=43520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전기가 튀며 파지직하는 소리가 납니다!', `MaleText_loc4`='空气中激荡的电流噼啪作响！', `MaleText_loc5`='電流劈啪作響的聲音響起了!', `MaleText_loc7`='¡El aire crepita cargado de electricidad!' WHERE `ID`=43521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 관측병을 대신할 수 있는 건 없지만, 지금 이곳에는 산악경비대원들이 필요하네. 당분간은 그 노움들이 만들어준 관측 로봇에 기대는 수밖에...', `MaleText_loc4`='真人观察者是无可取代的，但我现在需要那些巡山人来帮忙。我们只能暂时依靠那些小个子的侏儒观察机器人了……', `MaleText_loc5`='活生生的觀察員還是無法取代的，但是我需要讓這些巡山員留在這裡。所以，現在我們只能暫且仰賴那些地精小機器人...', `MaleText_loc7`='Los observadores de carne y hueso no pueden ser sustituidos, pero necesito a esos montaraces aquí. Tendremos que confiar en esos pequeños robots gnomos por ahora...' WHERE `ID`=43522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따스한 햇볕이 없다는 점만 빼면 여기도 꽤 지낼 만한 곳입니다.', `MaleText_loc4`='这地方还不赖，前提是你不过分专注于那“阳光”。', `MaleText_loc5`='這地方還不賴，只要你不介意「陽光」這回事的話。', `MaleText_loc7`='Este lugar no está tan mal si no te importa que no haya eso que llaman "luz del sol".' WHERE `ID`=43523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메스너, 출발하자.', `MaleText_loc4`='送我们出去，梅森纳。', `MaleText_loc5`='咱們出航吧，梅斯納。', `MaleText_loc7`='Sácanos, Messner.' WHERE `ID`=43524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 조니!', `MaleText_loc4`='没问题，强尼！', `MaleText_loc5`='沒問題，強尼!', `MaleText_loc7`='¡Ya lo tienes, Johnny!' WHERE `ID`=43525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 왔어! 모두들 내려!', `MaleText_loc4`='我们在这儿，所有人都出去！', `MaleText_loc5`='我們來了。所有人離開!', `MaleText_loc7`='¡Estamos aquí, todos fuera!' WHERE `ID`=43526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 난 다시 일하러 가야 해.', `MaleText_loc4`='请原谅，我得继续工作了。', `MaleText_loc5`='抱歉，我得回去忙我的工作了。', `MaleText_loc7`='Disculpa, tengo que volver al trabajo.' WHERE `ID`=43527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전츠, 빚을 받으러 왔습니다. 어서 돈을 주십시오.', `MaleText_loc4`='琼兹，我是来讨债的。给钱吧。', `MaleText_loc5`='強斯，我是來收帳的。付錢。', `MaleText_loc7`='Juntz, he venido a cobrar una deuda. Paga.', `FemaleText_loc1`='전츠, 빚을 받으러 왔어요. 어서 돈을 주세요.', `FemaleText_loc4`='琼兹，我是来讨债的。给钱吧。', `FemaleText_loc5`='強斯，我是來收帳的。付錢。', `FemaleText_loc7`='Juntz, he venido a cobrar una deuda. Paga.' WHERE `ID`=43528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고릴라는 환상적인 생물체입니다. 도박에 돈을 모두 탕진하고 "바다늑대" 맥킨리의 명단에 오르는 바보 같은 나이트 엘프보다 훨씬 똑똑하죠.', `MaleText_loc4`='猩猩可真是令人着迷的生物。比暗夜精灵要好多了，那些家伙就只会干蠢事……比如在赌场上输个精光，还害自己登上“海狼”马克基雷的黑名单。', `MaleText_loc5`='猩猩是很神奇的生物。比夜精靈強多了，不像他們會幹出蠢事，譬如...賭錢輸個精光，被海狼麥克基雷列為追殺討債的目標。', `MaleText_loc7`='Los gorilas son criaturas fascinantes. Mejor que elfos de la noche que no hacen más que tonterías como... apostarse todo el dinero y pasar a formar parte de la lista de Lobo de Mar MacKinley de objetivos a atizar.' WHERE `ID`=43529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 제가 왜 여기 왔는지 아시겠군요. 어서 빚을 갚으십시오.', `MaleText_loc4`='那你知道我来这里的原因了。好吧小腹，给钱吧。', `MaleText_loc5`='你知道我是來幹什麼的。好了，腹肌男，付錢吧。', `MaleText_loc7`='Entonces ya sabes por qué he venido. Venga, Ombligo, suelta la pasta.', `FemaleText_loc1`='그럼 제가 왜 여기 왔는지 아시겠네요. 어서 빚을 갚으세요.', `FemaleText_loc4`='那你知道我来这里的原因了。好吧小腹，给钱吧。', `FemaleText_loc5`='你知道我是來幹什麼的。好了，腹肌男，付錢吧。', `FemaleText_loc7`='Entonces ya sabes por qué he venido. Venga, Ombligo, suelta la pasta.' WHERE `ID`=43530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 어떻게 찾았지!?', `MaleText_loc4`='你是怎么找到我的？！', `MaleText_loc5`='你是怎樣找到我的!?', `MaleText_loc7`='¿Cómo me has encontrado?' WHERE `ID`=43531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 한 푼도 없습니다! 저리 가십시오!', `MaleText_loc4`='我身无分文！走开！', `MaleText_loc5`='我一毛錢也沒有!走開!', `MaleText_loc7`='¡No tengo dinero! ¡Lárgate!' WHERE `ID`=43532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 봐라, $r. 안 그래도 시비 걸고 싶던 참인데 말이야.', `MaleText_loc4`='继续，$r。给我个理由。', `MaleText_loc5`='來啊，$r。正好給我的藉口。', `MaleText_loc7`='Venga, $r. Dame una excusa.' WHERE `ID`=43533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르 대족장님이 여기 책임자시다. 잊지 마라.', `MaleText_loc4`='这儿可是莫格霍尔酋长说了算。别忘了这一点。', `MaleText_loc5`='大酋長莫格是這的老大。永遠別忘了。', `MaleText_loc7`='El jefe de guerra Mor''ghor es el que está al mando por estos lares. No lo olvides.' WHERE `ID`=43534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<붉게 눈을 번득이는 집행자>$B$B같잖은 너희 호드가 우릴 공격해 줬으면 좋겠군. 피를 보고 싶어서 몸이 근질근질한데 말이야, $c!', `MaleText_loc4`='<执行者的眼中闪着红光。>$B$B我倒希望你们这些可怜的兽人来攻击我们。我很久没畅快地挥洒热血了，$c！', `MaleText_loc5`='<執行者的雙眼閃過紅光。>$B$B我很希望你的可悲部落攻擊我們，我手很癢，等不及要看鮮血四濺了，$c!', `MaleText_loc7`='<Los ojos del déspota brillan con un tono rojo.>$B$BEspero que tu patética Horda intente atacarnos. ¡No puedo esperar a derramar un poco de sangre, $c!' WHERE `ID`=43535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 분노! 이 힘! 평생 내가 이렇게 강하게 느껴지는 건 처음이다.$B$B곧 모든 용아귀 부족이 우리와 같은 것을 느낄 테지.', `MaleText_loc4`='那愤怒！那力量！我一生中从未感到如此强壮。$B$B很快，整个龙喉部族都将有同样的感觉。', `MaleText_loc5`='怒火!力量!我這輩子從來沒有這麼強壯的感覺。$B$B不久，龍喉氏族所有的人都會跟我有一樣的感覺。', `MaleText_loc7`='¡La furia! ¡El poder! Nunca me he sentido tan fuerte en toda mi vida.$B$BPronto, TODOS los Faucedraco se sentirán como yo.' WHERE `ID`=43536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깝죽거리지 마라, $c.$B$B<당신이 달려들길 기대하며 허리께로 손을 가져가 칼을 뽑을 준비를 하는 집행자>', `MaleText_loc4`='不要自取其辱，$c。$B$B<执行者握住剑柄的手指又紧了紧，就等你先动手了。>', `MaleText_loc5`='別玩小花樣，$c。$B$B<執行者握著刀柄的手變緊了，等著你做出什麼事。>', `MaleText_loc7`='No intentes hacer nada raro, $c.$B$B<El déspota flexiona los dedos cerca de la empuñadura de su espada, ansioso de que le hagas una escenita.>' WHERE `ID`=43537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르 대족장님이 용아귀 부족을 다시 한번 영광의 길로 이끄실 것이다!$B$B한심한 너희 호드 따위는 필요 없다.', `MaleText_loc4`='莫格霍尔酋长将率领龙喉部族再次崛起！$B$B我们用不着你们这群没用的部落。', `MaleText_loc5`='大酋長莫格會復興龍喉!$B$B我們不需要你的可悲部落。', `MaleText_loc7`='¡El jefe de guerra Mor''ghor hará que los Faucedraco sean grandes de nuevo!$B$BNo necesitamos a tu patética Horda.' WHERE `ID`=43538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉개 버려라!', `MaleText_loc4`='粉碎！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡MACHACAR!' WHERE `ID`=43539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽여라!', `MaleText_loc4`='杀戮！', `MaleText_loc5`='殺吧!', `MaleText_loc7`='¡MATAR!' WHERE `ID`=43540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴해라!', `MaleText_loc4`='毁灭！', `MaleText_loc5`='摧毀!', `MaleText_loc7`='¡DESTRUIR!' WHERE `ID`=43541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어찌해야 하겠소? 대족장님께서는 당연히 우리가 항구를 쓸어버리길 바라실 거요!', `MaleText_loc4`='我们现在要怎么做？酋长肯定想让我们用武力席卷港口！', `MaleText_loc5`='我們現在該怎麼辦?大酋長肯定會要我們硬攻打下這座港的!', `MaleText_loc7`='¿Qué hacemos ahora? ¡Estoy seguro de que el Jefe de Guerra querría que tomáramos el puerto a la fuerza!' WHERE `ID`=43542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇겠지. 그리고 우리가 이길지도 모르오. 하지만 그 대가가 얼마나 크겠소? 어쩌면 $n에게 더 나은 계획이 있을지도 모르오...', `MaleText_loc4`='也许吧。也许我们能取胜，但代价会有多大？说不定$n有更好的主意……', `MaleText_loc5`='也許吧。也許我們會贏，但代價呢?說不定$n會有更好的計畫...', `MaleText_loc7`='Quizá. Y quizá ganáramos, pero ¿a qué precio? Puede que $n tenga un plan mejor…' WHERE `ID`=43543;
