UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특대 해적 모자가 필요합니다. 시혼의 명령입니다.', `MaleText_loc4`='我需要一顶超大海盗帽。是海角的命令。', `MaleText_loc5`='我需要一頂特大號的海賊帽。海角的命令。', `MaleText_loc7`='Necesito un sombrero pirata extra grande. Órdenes de Cuernomarino.', `FemaleText_loc1`='특대 해적 모자가 필요해요. 시혼의 명령이에요.', `FemaleText_loc4`='我需要一顶超大海盗帽。是海角的命令。', `FemaleText_loc5`='我需要一頂特大號的海賊帽。海角的命令。', `FemaleText_loc7`='Necesito un sombrero pirata extra grande. Órdenes de Cuernomarino.' WHERE `ID`=43576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시혼에게 이게 마지막 모자라고 전해주게. 뿔 때문에 이 예쁜 모자에 구멍을 내야 한다니... 가슴이 찢어지는군!', `MaleText_loc4`='告诉他这是最后一顶了。在漂亮的帽子上戳洞，这可让可怜的纳尔克伤透了心！', `MaleText_loc5`='告訴他這是最後一頂了。這叫納爾克真是傷心啊，竟然得在他漂亮的帽子上挖兩個牛角洞!', `MaleText_loc7`='Dime que este es el último. ¡Al pobre Narkk se le rompe el corazón al tener que hacer más agujeros para cuernos en estos hermosos sombreros!' WHERE `ID`=43577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 가지고 계십니까?', `MaleText_loc4`='你找来了什么？', `MaleText_loc5`='你有什麼貨色?', `MaleText_loc7`='¿Qué tienes?', `FemaleText_loc1`='뭘 가지고 계세요?', `FemaleText_loc4`='你找来了什么？', `FemaleText_loc5`='你有什麼貨色?', `FemaleText_loc7`='¿Qué tienes?' WHERE `ID`=43578;
