UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리카락과 모자를 가져왔습니다. 함장님.', `MaleText_loc4`='这是头颅和帽子，舰队指挥官。', `MaleText_loc5`='這是頭和帽子，艦隊指揮官。', `MaleText_loc7`='Aquí tienes la cabeza y el sombrero, maestro de flota.', `FemaleText_loc1`='머리카락과 모자를 가져왔어요. 함장님.', `FemaleText_loc4`='这是头颅和帽子，舰队指挥官。', `FemaleText_loc5`='這是頭和帽子，艦隊指揮官。', `FemaleText_loc7`='Aquí tienes la cabeza y el sombrero, maestro de flota.' WHERE `ID`=43589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 하겠습니다.', `MaleText_loc4`='你说了算。', `MaleText_loc5`='你說了算。', `MaleText_loc7`='Tú eres el jefe.', `FemaleText_loc1`='그렇게 해야죠.', `FemaleText_loc4`='你说了算。', `FemaleText_loc5`='你說了算。', `FemaleText_loc7`='Tú eres el jefe.' WHERE `ID`=43590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금도 괜찮긴 한데, 좀 걷어차 주면 왠지 더 타우렌 털처럼 보일 것 같긴 하네요. 음, 저처럼 거칠고 야성미 넘치는 타우렌의 머리카락처럼 말입니다. 어떻게 생각하십니까?', `MaleText_loc4`='看起来不错，但是我认为要是能把它弄皱些就更好了。你知道，要给人一种经历过战斗的感觉。你说呢？', `MaleText_loc5`='看起來不錯。但是我覺得把它再打兩下的話，看起來應該會更棒。你知道的，弄出個有打過架的假象。你們覺得怎樣?', `MaleText_loc7`='Esto tiene buena pinta, pero creo la tendrá aún mejor si la apaleamos un poquito. Ya sabes, como si hubiera habido una pelea. ¿Qué opinas?' WHERE `ID`=43591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='댄포스, 보고해.', `MaleText_loc4`='丹弗斯，报告。', `MaleText_loc5`='丹佛斯，報告。', `MaleText_loc7`='Danforth, informa.' WHERE `ID`=43592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 오크들이 돌망루 요새로 이어지는 다리를 날려버렸어. 정면 공격은 불가능해!', `MaleText_loc4`='黑石兽人炸毁了通往石堡要塞的桥梁。正面交战是不可能了。', `MaleText_loc5`='黑石部族的獸人把到石望要塞的橋樑炸爛了。不可能進行正面突擊。', `MaleText_loc7`='Los orcos Roca Negra han volado el puente de Fuerte Petravista. Un ataque frontal resulta imposible.' WHERE `ID`=43593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라카우어?', `MaleText_loc4`='卡拉克尔？', `MaleText_loc5`='克洛克考爾?', `MaleText_loc7`='¿Krakauer?' WHERE `ID`=43594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조니, 적진으로 침투하기 위한 방법은 두 가지가 있어. 뭐, 시체가 되어 들어가는 방법까지 합하면 세 가지군.', `MaleText_loc4`='有两种方式可以深入敌后，约翰尼。如果算上死的话，总共有三种。', `MaleText_loc5`='有兩個方法可以繞到敵人的後面，強尼。如果把死亡算進去就是三個。', `MaleText_loc7`='Hay dos formas de introducirnos tras las líneas enemigas, Johnny. Tres si cuentas la de estar muerto.' WHERE `ID`=43595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째는 북쪽 앨더의 제재소를 통과하는 방법인데, 그러려면 피에 굶주린 늑대 떼를 먼저 처리해야 할 것 같군. 두 번째는 남쪽 약탈의 계곡을 통과하는 방법이고.', `MaleText_loc4`='向北穿过奥瑟尔伐木场，但我们得遭遇嗜血的座狼大军，或是向南穿过撕裂者山谷。', `MaleText_loc5`='往北穿過奧瑟爾伐木場，但是我們得殺過一大群兇狠的座狼。或者是往南經過撕裂者山谷。', `MaleText_loc7`='Hacia el norte por el Molino de Alther, pero tendremos que atravesar un ejército de huargos sedientos de sangre o ir al sur por el Valle de Render.' WHERE `ID`=43596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요르겐센, 약탈의 계곡은 어떤가?', `MaleText_loc4`='约根森，你对撕裂者山谷有把握吗？', `MaleText_loc5`='喬更森，撕裂者山谷的狀況如何?', `MaleText_loc7`='Jorgensen, ¿qué sabemos del Valle de Render?' WHERE `ID`=43597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 오크들이 지천으로 깔려 있어, 조니. 여긴 주탑과 두 개의 작은 오두막으로 나뉘어 있는데, 사실상 함정이나 마찬가지야.
', `MaleText_loc4`='那鬼地方到处都是黑石兽人，约翰尼。在必经之路上有一座主塔，还有两间稍小一些的木屋。那可是死亡陷阱。', `MaleText_loc5`='強尼，那個該死的地方到處都是黑石獸人。制扼點有一座哨塔，另外還有兩間小屋。那裡是個死亡陷阱。', `MaleText_loc7`='Hay Roca Negra por todas partes, Johnny. Una torre principal en el desfiladero y dos cabañas más pequeñas. Es una ratonera.\\' WHERE `ID`=43598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함정이라고? 메스너, 방법이 하나 있어. 시포리움이 좀 필요하겠는걸.', `MaleText_loc4`='死亡陷阱，嗯？梅森纳，我有计划了。得用到些爆盐。', `MaleText_loc5`='死亡陷阱是嗎?梅斯納，我有個計畫。但是我需要一些爆鹽炸藥。', `MaleText_loc7`='Una ratonera, ¿eh? Messner, tengo un plan. Necesitaré un poco de seforio.' WHERE `ID`=43599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시포리움? 대체 그걸 어디서 구해오라는 거야, 조니?', `MaleText_loc4`='爆盐？我要上哪儿去找那鬼东西，约翰尼？', `MaleText_loc5`='爆鹽炸藥?強尼，我要到哪裡去生爆鹽炸藥出來?', `MaleText_loc7`='¿Seforio? ¿De dónde diablos voy a sacar seforio, Johnny?' WHERE `ID`=43600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거야 내 알 바 아니지, 메스너. 까라면 까라고.', `MaleText_loc4`='这就不是我要考虑的问题了，梅森纳。总之要找到。', `MaleText_loc5`='不是我的問題，梅斯納。去給我生出來就對了。', `MaleText_loc7`='No es problema mío, Messner. Tú tráemelo.' WHERE `ID`=43601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 장비를 챙기고 전장으로 나갈 준비를 하십시오.', `MaleText_loc4`='$n，把你的东西收拾好。我要派你上战场了。', `MaleText_loc5`='$n，褲帶綁緊一點。我要派你上場了。', `MaleText_loc7`='$n, recoge tus cosas y prepárate. Te mando al campo de batalla.' WHERE `ID`=43602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼룩을 너무 오랫동안 남겨두지 마십시오!', `MaleText_loc4`='别让污点存在太久！', `MaleText_loc5`='不要讓髒污留太久!', `MaleText_loc7`='¡No dejes que las manchas se queden ahí durante mucho tiempo!' WHERE `ID`=43603;
