UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑판에서 얼룩을 찾았습니다!', `MaleText_loc4`='你在甲板上发现了一个污点！', `MaleText_loc5`='你在甲板上發現了一塊髒污!', `MaleText_loc7`='¡Has visto una mancha en la cubierta!' WHERE `ID`=43605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼룩이 두 개 더 생겼습니다! 계속 청소하십시오!', `MaleText_loc4`='又出现了两个污点！继续清洁！', `MaleText_loc5`='又出現了兩個髒污!繼續拖地!', `MaleText_loc7`='¡Aparecen dos manchas más! ¡Sigue limpiando!' WHERE `ID`=43606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼룩이 더 빠르게 생기기 시작합니다!', `MaleText_loc4`='污点出现得越来越快了！', `MaleText_loc5`='髒污開始出現得越來越快了!', `MaleText_loc7`='¡Ahora las manchas aparecen con más rapidez!' WHERE `ID`=43607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑판이 너무 더러워졌습니다. 다른 대걸레를 잡고 다시 한 번 도전하십시오.', `MaleText_loc4`='甲板被毁了。再拿把拖把重新尝试吧。', `MaleText_loc5`='甲板毀掉了。拿起另一支拖把，再試一次。', `MaleText_loc7`='La cubierta está perdida. Consigue otra mopa e inténtalo de nuevo.' WHERE `ID`=43608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형제들은 강하다. 하지만 소극적이지.$B$B변화라는 것은 행동, 논쟁, 그리고 폭력 없이는 일어나지 않는 법이다. 우리 적들이 이를 이해하는지는 모르겠으나, 어쨌든 그들은 이에 맞게 행동한다. 하지만 우리 형제들은 소극적인 본성 때문에 이 새로운 적 앞에서 약해지고 있지.$B$B나는 그렇지 않다. 나는 변화가 두렵지 않다. 나는 대지를 가르고 산을 옮길 것이다. 변화를 받아들일 것이다.', `MaleText_loc4`='我的兄弟们很强壮，但却总是非常被动。$B$B没有运动、没有竞争、没有暴力，就不会产生变化。我们的敌人深谙此道，不管他们是不是完全意识到了这一点。我兄弟们被动的天性使他们在这些新的敌人面前显得脆弱而无力。$B$B别把我算在内。我不惧怕改变。我愿意撕裂大地，挪移群山。我热爱改变。', `MaleText_loc5`='我的弟兄們很強壯，但是我的弟兄們太被動了。$B$B改變不會憑空發生，改變必然會有變遷、衝突，以及暴力。我們的敵人就是這樣，不論他們自己是否有察覺。我弟兄們被動的天性害他們變得虛弱，無法對抗這些新的敵人。$B$B但是我不一樣。我不害怕改變。我會撕裂大地，移平高山。我會擁抱改變。', `MaleText_loc7`='Mis hermanos son fuertes, pero también pasivos.$B$BEl cambio no sucede sin movimiento, controversia y violencia. Nuestros enemigos viven esto, sean conscientes de ello o no. La naturaleza pasiva de mis hermanos les hace débiles y vulnerables ante esos enemigos.$B$BYo no. Yo no tengo miedo del cambio. Desgarraré la tierra y moveré montañas. Yo abrazo el cambio.' WHERE `ID`=43609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대걸레를 들었으니 닦아낼 얼룩을 찾으십시오!', `MaleText_loc4`='你已经拿到了拖把，现在赶快去清除污点！', `MaleText_loc5`='拖把給你了，看到髒污就用力擦!', `MaleText_loc7`='¡Ya tienes tu mopa, ahora busca manchas que haya que limpiar!' WHERE `ID`=43610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 남아서 바위 트로그의 잔여물을 마저 처리하겠네.', `FemaleText_loc4`='我留下来确认他们剩下的实体也被消灭了。', `FemaleText_loc5`='我留下來確保他們剩下的東西都會被摧毀。', `FemaleText_loc7`='Me quedo para asegurarme de que el resto sea destruido.' WHERE `ID`=43611;
