UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장! 정정당당하게 빼돌린 운향귤이란 말이다!', `MaleText_loc4`='呀！那些酸橙是我光明正大得来的！', `MaleText_loc5`='是啊!我是正當地偷走那些萊姆的!', `MaleText_loc7`='¡Jarrr! ¡He mangao esas limas honradamente!', `FemaleText_loc1`='젠장! 정정당당하게 빼돌린 운향귤이란 말이야!', `FemaleText_loc4`='呀！那些酸橙是我光明正大得来的！', `FemaleText_loc5`='是啊!我是正當地偷走那些萊姆的!', `FemaleText_loc7`='¡Jarrr! ¡He mangao esas limas honradamente!' WHERE `ID`=43625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 신참 녀석! 어딜 도망가려고!', `MaleText_loc4`='啊！给我回来，你这喝泔水的小崽子！', `MaleText_loc5`='啊!給我回來，你這蠢豬頭!', `MaleText_loc7`='¡Arrr! ¡Vuelve aquí, grumetillo tragalimas!', `FemaleText_loc1`='이 신참 녀석! 어딜 도망가!', `FemaleText_loc4`='啊！给我回来，你这喝泔水的小崽子！', `FemaleText_loc5`='啊!給我回來，你這蠢豬頭!', `FemaleText_loc7`='¡Arrr! ¡Vuelve aquí, grumetillo tragalimas!' WHERE `ID`=43626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료에게 운향귤차를 만들어주려고 했던 거야! 난 결백해!', `MaleText_loc4`='我正想给我的伙伴们做点儿酸橙汽水！我发誓！', `MaleText_loc5`='我只是要為他們做些萊姆汁而已!我發誓!', `MaleText_loc7`='¡Solo iba a hacel limonada pa los broders! ¡Lo juro!', `FemaleText_loc1`='동료에게 운향귤차를 만들어주려고 했던 것뿐이야! 난 결백해!', `FemaleText_loc4`='我正想给我的伙伴们做点儿酸橙汽水！我发誓！', `FemaleText_loc5`='我只是要為他們做些萊姆汁而已!我發誓!', `FemaleText_loc7`='¡Solo iba a hacel limonada pa los broders! ¡ Lo juro!' WHERE `ID`=43627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운향귤을 훔치는 행위는 그만두는 게 좋을 거다!', `MaleText_loc4`='死人别想偷酸橙！', `MaleText_loc5`='死人不會偷萊姆!', `MaleText_loc7`='¡Los hombres mueltos no roban limas!', `FemaleText_loc1`='운향귤을 훔치는 행위는 그만두는 게 좋을 거다!', `FemaleText_loc4`='死人别想偷酸橙！', `FemaleText_loc5`='死人不會偷萊姆!', `FemaleText_loc7`='¡Los hombres mueltos no roban limas!' WHERE `ID`=43628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귤에서 당장 손 떼지 못해?!', `MaleText_loc4`='再练练偷酸橙的本事吧，你这下流的无赖！', `MaleText_loc5`='不准再偷萊姆了，卑鄙的混蛋!', `MaleText_loc7`='¡Amarra tus artes de robalimas, perro de agua dulce!', `FemaleText_loc1`='내 귤에서 당장 손 떼지 못해?!', `FemaleText_loc4`='再练练偷酸橙的本事吧，你这下流的无赖！', `FemaleText_loc5`='不准再偷萊姆了，卑鄙的混蛋!', `FemaleText_loc7`='¡Amarra tus artes de robalimas, perro de agua dulce!' WHERE `ID`=43629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼. 내 운향귤은 안 돼!', `MaleText_loc4`='不，别碰我的酸橙，听见没有！', `MaleText_loc5`='不，不是我偷的，我沒有!', `MaleText_loc7`='¡No, digo que mis limas, no!', `FemaleText_loc1`='안 돼. 내 운향귤은 안 돼!', `FemaleText_loc4`='不，别碰我的酸橙，听见没有！', `FemaleText_loc5`='不，不是我偷的，我沒有!', `FemaleText_loc7`='¡No, digo que mis limas, no!' WHERE `ID`=43630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전하가 충전됨에 따라 오닉시아의 몸에서 방전이 일어납니다.', `FemaleText_loc4`='随着奥妮克希亚体内电荷的增加，在她身体四周开始出现能量电弧。', `FemaleText_loc5`='電流逐漸增強，能量在奧妮克希亞的屍身上奔竄。', `FemaleText_loc7`='A medida que aumenta su carga eléctrica, la energía forma un arco a través del cuerpo de Onyxia.' WHERE `ID`=43631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오닉시아의 몸에 충전된 전하량이 위험 수준에 다다르면서 방전이 점점 심해집니다!', `FemaleText_loc4`='随着奥妮克希亚体内的电荷积聚到危险程度，电弧也在不断加强！', `FemaleText_loc5`='奧妮克希亞身上的電流達到了危險等級，電弧變得越來越強!', `FemaleText_loc7`='¡Los arcos voltaicos se intensifican a medida que la carga eléctrica de Onyxia alcanza niveles peligrosos!' WHERE `ID`=43632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작은 번개가 오닉시아의 피부를 타고 흐릅니다. 전기 에너지가 극에 달했습니다!', `FemaleText_loc4`='微小的闪电灼烧着奥妮克希亚的皮肤。她体内的电荷已积聚到濒临迸发的阶段！', `FemaleText_loc5`='一道道小型閃電在奧妮克希亞的表皮上奔竄。她身上的電流已經達到了致命的等級了!', `FemaleText_loc7`='Rayos en miniatura se desatan sobre la piel de Onyxia. ¡Su carga eléctrica ha alcanzado un punto crítico!' WHERE `ID`=43633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주홍빛 장막호로 돌아가야겠어. 거기서 봅세.', `MaleText_loc4`='我应该返回红雾号了。到那儿再见。', `MaleText_loc5`='我該回去赤紅之霧了。我在那裡等你。', `MaleText_loc7`='Debería regresar a El Velo Carmesí. Te veo allí.' WHERE `ID`=43634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 이 자객들을 처치하게. 벌써 저 앞에 몇 명 보이는군.', `MaleText_loc4`='让我们把这些忍者干掉，老大。我已经在前方看见一些了。', `MaleText_loc5`='老大，我們來把這些忍者幹掉吧。我已經看到有幾個在前面了。', `MaleText_loc7`='Carguémonos a esos ninjas, jefe. Ya veo algunos ahí delante.' WHERE `ID`=43635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 소리지?', `MaleText_loc4`='那是什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué es eso?', `FemaleText_loc1`='무슨 소리야?', `FemaleText_loc4`='那是什么？', `FemaleText_loc5`='那是什麼?', `FemaleText_loc7`='¿Qué es eso?' WHERE `ID`=43636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 그 소리 들었어?', `MaleText_loc4`='你听见了吗？', `MaleText_loc5`='你聽見了嗎?', `MaleText_loc7`='¿Has oído eso?', `FemaleText_loc1`='지금 그 소리 들었어?', `FemaleText_loc4`='你听见了吗？', `FemaleText_loc5`='你聽見了嗎?', `FemaleText_loc7`='¿Has oído eso?' WHERE `ID`=43637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 살았다! 어서 도망쳐!', `MaleText_loc4`='我们自由了！逃命去吧！', `MaleText_loc5`='我們自由了!快逃命啊!', `MaleText_loc7`='¡Somos libres! ¡CORRED PARA SALVAR LA VIDA!', `FemaleText_loc1`='이제 살았어요! 달아나요!', `FemaleText_loc4`='我们自由了！逃命去吧！', `FemaleText_loc5`='我們自由了!快逃命啊!', `FemaleText_loc7`='¡Somos libres! ¡CORRED PARA SALVAR LA VIDA!' WHERE `ID`=43638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거야 원 벌집을 쑤신 꼴이라고요, $n 님!$B$B이 상황을 해결할 계획이 있으시길 빕니다. 크로그의 전사들이 용아귀 부족을 마구 해치우고 있습니다만, 한 발짝 나아갈 때마다 우리 또한 큰 희생을 치르고 있습니다.', `MaleText_loc4`='我们捅了马蜂窝了，$n！$B$B希望你已经有了应对的计划。克罗格的战士们正在铲除龙喉，可我们每前进一寸都在遭受惨重的损失……', `MaleText_loc5`='我們捅到蜂窩了，$n!$B$B希望你已經有收拾殘局的計畫。克羅格的戰士打得龍喉氏族節節敗退，但是每攻下一吋土地，我們同樣得付出慘痛的損失...', `MaleText_loc7`='¡Hemos agitado el nido de avispas, $n!$B$BEspero que tengas un plan para poner fin a esto. Los guerreros de Krogg están destrozando a los Faucedraco, pero estamos sufriendo grandes bajas por cada centímetro de tierra que ganamos...' WHERE `ID`=43639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 나도 언젠간 죽겠지...', `MaleText_loc4`='我终有一天会死，女海巫……', `MaleText_loc5`='海巫，我總有天會死掉...', `MaleText_loc7`='Algún día moriré, bruja…' WHERE `ID`=43640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 오늘은 아니다!', `MaleText_loc4`='……但绝不是今天！', `MaleText_loc5`='...但絕不是今天!', `MaleText_loc7`='¡... pero hoy no!' WHERE `ID`=43641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 있으세요! 우리는 수가 적습니다!', `MaleText_loc4`='靠紧点！我们的人已经很少了。', `MaleText_loc5`='靠近點!我們人已經太少了!', `MaleText_loc7`='¡No se alejen! ¡Ya somos pocos!' WHERE `ID`=43642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰일 날 뻔했습니다! 돌아다니지 마십시오!', `MaleText_loc4`='你差点就走散了！不要掉队！', `MaleText_loc5`='你差點迷路了!不要亂跑!', `MaleText_loc7`='¡Casi perecemos! ¡No se alejen!' WHERE `ID`=43643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오십시오! 혼자서는 죽은 목숨입니다!', `MaleText_loc4`='跟着我！在这儿掉队就死定了！', `MaleText_loc5`='跟著我!你無法獨自存活!', `MaleText_loc7`='¡Síganme! ¡Perecerán sin remedio solos!' WHERE `ID`=43644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우릴 방해하다니... 목숨으로 대가를 치러라!', `MaleText_loc4`='你的干涉会让你付出生命的代价，$r！', `MaleText_loc5`='你的干預會讓你喪命，$r!', `MaleText_loc7`='¡Ssu interferencia les cosstará la vida!' WHERE `ID`=43645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군수품 오두막에 시포리움을 설치하는 데 성공했습니다.', `MaleText_loc4`='你已成功将爆盐炸弹安放在军需营帐处。', `MaleText_loc5`='你成功將爆鹽炸彈設置在軍火存放小屋。', `MaleText_loc7`='Has plantado con éxito el seforio en la cabaña del arsenal.' WHERE `ID`=43646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 탑에 시포리움을 설치하는 데 성공했습니다.', `MaleText_loc4`='你已成功将爆盐炸弹安放在黑石塔楼处。', `MaleText_loc5`='你成功將爆鹽炸彈設置在黑石哨塔。', `MaleText_loc7`='Has plantado con éxito el seforio en la Torre Roca Negra.' WHERE `ID`=43647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 이곳에 볼일이 없을 텐데!', `MaleText_loc4`='这与你无关，$r！', `MaleText_loc5`='你不該在這攪和，$r!', `MaleText_loc7`='¡Ssssalgan de aquí!' WHERE `ID`=43648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물이 널 맛있게 먹어치울 것이다, 무른피부야!', `MaleText_loc4`='软皮人，你会成为那只野兽的可口点心！', `MaleText_loc5`='你會是野獸的佳餚，細皮嫩肉!', `MaleText_loc7`='¡La besstia los ssaboreará, seres blandosss!' WHERE `ID`=43649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 무리를 호위해 테라제인의 옥좌로 갈 준비가 됐습니다.', `MaleText_loc4`='我已准备好将一队元素护送过开阔地。', `MaleText_loc5`='我已經準備好要護送一群元素穿過這片空地。', `MaleText_loc7`='Estoy listo para escoltar a un grupo de elementales hasta el otro lado de la apertura.', `FemaleText_loc1`='정령 무리를 호위해 테라제인의 옥좌로 갈 준비가 됐습니다.', `FemaleText_loc4`='我已准备好将一队元素护送过开阔地。', `FemaleText_loc5`='我已經準備好要護送一群元素穿過這片空地。', `FemaleText_loc7`='Estoy lista para escoltar a un grupo de elementales hasta el otro lado de la apertura.' WHERE `ID`=43650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잽싸게 움직여라. 바위용은 쉽게 포기하지 않는다.', `MaleText_loc4`='迅速些，$c。石龙不会这么轻易的屈服。', `MaleText_loc5`='皮繃緊點，$c。石龍們不會輕易善罷干休。', `MaleText_loc7`='Sé raudo. Los dragones de piedra no se dejarán vencer.' WHERE `ID`=43651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\INV_MISC_ENGGIZMOS_20.BLP:16|t불곰 중대 야전 장비를 지금 작동시키십시오.$B|Tinterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t위장 도구를 사용하여 파티원이 은신 상태가 되어야 합니다.', `MaleText_loc4`='现在激活你的B连战地工具。|TInterface\\Icons\\INV_MISC_ENGGIZMOS_20.BLP:16|t$B用伪装使你的小队成员隐形。|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t', `MaleText_loc5`='立刻使用你的第二連隊野戰包。|TInterface\\Icons\\INV_MISC_ENGGIZMOS_20.BLP:16|t$B使用「偽裝」來隱藏隊伍的行蹤。|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t', `MaleText_loc7`='Activa tu Paquete de campo de la Comañía Bravo.|TInterfaceIconsINV_MISC_ENGGIZMOS_20.BLP:16|t$BUsa Camuflaje para pasar a tu grupo a sigilo.|TInterfaceIconsSPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t' WHERE `ID`=43652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약탈의 계곡에 접근하고 있습니다. 강한 오크들이 기다리고 있으니, 반드시 |TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t위장 도구를 사용해야 합니다!
', `MaleText_loc4`='我们已接近撕裂者山谷。这些兽人很难对付！一定要将自己伪装好！|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t', `MaleText_loc5`='我們來到撕裂者山谷了。這裡的獸人很難搞!確認你已經偽裝好了!|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t', `MaleText_loc7`='Nos acercamos al Valle de Render. ¡Esos orcos son duros! ¡Asegúrate de ir camuflado!|TInterfaceIconsSPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t' WHERE `ID`=43653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 요르겐센이 몰래 잠입할 수 있도록 |TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:16|t교란 도구를 사용하여 적의 주의를 분산시켜야 합니다.

', `MaleText_loc4`='分散敌人的注意力，以便使约根森和你能悄悄过去。|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:16|t', `MaleText_loc5`='吸引敵人的注意，讓你和喬更森可以神不知鬼不覺地溜進去。|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:16|t', `MaleText_loc7`='Crea una distracción para que Jorgensen y tú podáis escabulliros sin ser vistos.|TInterfaceIconsABILITY_ROGUE_BLOODYEYE.BLP:16|t' WHERE `ID`=43654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나의 대상을 처리해야 할 때도 있습니다. 그럴 때는 적의 뒤쪽에서 |TInterface\\Icons\\SPELL_NATURE_SLEEP.BLP:16|t마취제를 사용하십시오.
', `MaleText_loc4`='!有时你只需要解决一个目标。在敌人背后使用麻醉！|TInterface\\Icons\\SPELL_NATURE_SLEEP.BLP:16|t', `MaleText_loc5`='有時候你只需要解決一個目標。在敵人的背後使用麻醉藥劑!|TInterface\\Icons\\SPELL_NATURE_SLEEP.BLP:16|t', `MaleText_loc7`='A veces, lo que tienes que hacer es simplemente eliminar al objetivo. ¡Utiliza el cloroformo cuando estés detrás del enemigo!|TInterfaceIconsSPELL_NATURE_SLEEP.BLP:16|t' WHERE `ID`=43655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족이 자유를 찾는 걸 도와주러 온 거요?$B$B잴라와 이야기하시오. 그녀가 저항군을 지휘하고 있소!', `MaleText_loc4`='你是来帮龙喉重获自由吗？$B$B去和扎伊拉谈谈——她在协调我们的反抗行动！', `MaleText_loc5`='你是來協助龍喉氏族取回我們自由的嗎?$B$B去找札伊拉—她正在安排我們的反抗活動!', `MaleText_loc7`='¿Has venido para ayudar a los Faucedraco a recuperar su libertad?$B$B¡Habla con Zaela, es ella la que está coordinando la resistencia!' WHERE `ID`=43656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항구를 포기하자고요? 모르고르 때문에 정신 나간 겁니까? 이 공격은 절호의 기회입니다. 앞으로 우리의 운명을 스스로 결정하고 싶다면 이 기회를 놓쳐선 안 된다고요. 잠깐! 호드의 $n|1이;가; 오고 있습니다!', `FemaleText_loc4`='放弃港口？莫格霍尔把你的理智都打没了吗？这次攻击是我们夺回命运掌控权的最好机会——等等！让我们先见见来自部落的$n！', `FemaleText_loc5`='放棄這座港?你是被莫格給打壞腦袋了嗎?這場攻擊是奪回我們自己命運的最佳機會—慢著!部落的$n來了!', `FemaleText_loc7`='¿Abandonar el puerto? ¿Es que Mor''ghor te ha arrancado todo el sentido común? Este ataque es nuestra mejor oportunidad para ser dueños de nuestro destino... ¡Espera! ¡Aquí viene $n, de la Horda!' WHERE `ID`=43657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유 마법을 써도 어째 옛날처럼 짜릿한 기분이 들지 않아요. $n, 무슨 말인지 아시겠어요?', `MaleText_loc4`='我的治疗确实不具备原先那样的“吸引力”，$n。你明白我在说什么吗？', `MaleText_loc5`='我的治療已經沒有以前的那種「勁道」了，$n。你懂我在說什麼嗎?', `MaleText_loc7`='Mis sanaciones ya no tienen el impulso que tenían antes, $n. Entiendes lo que quiero decir, ¿no?' WHERE `ID`=43658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사 노릇 하기도 쉽지가 않아요. 요즘 빛의 힘에 문제가 있다는 생각이 많이 들거든요. 어떤 날은 잠에서 깨면 힘이 약해졌다는 느낌이 들지 뭐예요.', `MaleText_loc4`='作为圣骑士可真不是件容易的事情。圣光是如此难以驾驭。有些天当我醒来时，感觉就像我所有的能量都被弱化了。', `MaleText_loc5`='當個聖騎士真的很不容易。聖光叫人難以捉摸。有些時候我才一覺醒來，就覺得我全部的能力都被弱化了。', `MaleText_loc7`='Ser un paladín es duro. La Luz tiene un comportamiento tan errático. Algunos días me despierto y es como si mis poderes se hubieran debilitado.' WHERE `ID`=43659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 꽉 잡으시오. 나보다 더 유능한 뱃사공은 없으니!', `MaleText_loc4`='呀，抓紧了，朋友，再没有比我更好的划手了！', `MaleText_loc5`='耶，抓緊一點，寶貝，沒有比我更厲害的划手啦!', `MaleText_loc7`='¡Jarrr, aguanta, broder, no hay ningún remero tan capas como yo!' WHERE `ID`=43660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글쎄요, 어쩌면 남의 떡이 정말 더 커 보이는지도 모르죠. 그거 아세요? 크라카우어와 댄포스는 정말 끝내주게 강한 전사에요. 어쩌면 저도 성기사 노릇은 때려치우고 전사 훈련이나 받는 게 나을지도 모르겠네요.', `MaleText_loc4`='我不知道，也许对岸的草真的更绿些？你明白吗？卡拉克尔和丹弗斯真是一流的战士。也许我也该放弃这圣骑士的身份，考虑转行做战士。', `MaleText_loc5`='不曉得，也許別人碗裡的菜真的比較香。你知道嗎?克洛克考爾和丹佛斯他們當戰士真的好威啊。搞不好我該放棄聖騎士，重新練成戰士。', `MaleText_loc7`='No lo sé, quizá es cierto que la hierba siempre es más verde donde el vecino, ¿sabes? Krakauer y Danforth sí que reparten buenas tortas como guerreros. Quizá deba abandonar esta tontería de ser paladín e intentar convertirme en un guerrero.' WHERE `ID`=43661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린이 검은 금을 발견했다고 말하는 곳으로 가는 중이오. 그 금은 이제 우리 붉은해적단의 것이라오!', `MaleText_loc4`='我们要扬帆前往那群地精声称发现黑金子的地方。那些金子属于血帆海盗！', `MaleText_loc5`='我們要去哥布林說他們找到黑金的地方。那是我們血帆海盜的了!', `MaleText_loc7`='Nos dirihimos a donde los goblins diheron que habían encontrao oro negro. ¡Ese oro pertenece a los Velasangre!' WHERE `ID`=43662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 놈들 처치하는 속도는 메스너 따라갈 사람이 없어요. 저도 그렇게 할 수 있으면 좋겠다는 생각을 자주 하지요. 왜 저는 화염구를 쓰지 못할까요? 빛의 힘이 화염구와는 친하지 않은 이유가 뭘까요?', `MaleText_loc4`='梅森纳能如此迅速地干掉坏人。我真希望自己杀敌的速度能和他媲美。为什么我不能发出火球？圣光与火球相比优势在哪里？', `MaleText_loc5`='梅斯納殺壞蛋殺超快的。真希望我也能殺得跟他一樣快。我為什麼不能射火球呢?聖光到底對火球有什麼意見?', `MaleText_loc7`='Messner mata a los malos con tanta rapidez. Ojalá yo pudiera ser tan rápido matando. ¿Por qué no puedo disparar bolas de Fuego? ¿Qué tiene la LUZ en contra de las bolas de Fuego?' WHERE `ID`=43663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배는 내가 맡을 테니 당신은 낡아빠진 대포를 맡으시오... 그리고 옷을 어디 묶어두지는 마시오... 적에게 다가가면 내가 알아서 속도를 줄일 테니!', `MaleText_loc4`='我驾驶，你来操控老滑膛。别把你的衣服打成结……等我们接近时我会减速的！', `MaleText_loc5`='我來開船，你來弄舊衝擊火砲。不要緊張... 等靠近的時候我會放慢速度!', `MaleText_loc7`='Yo llevo el timón y tú manehas al Viejo Explo. Y no te cagues en los calsones... ¡Iré más despasio a medida que nos acerquemos!' WHERE `ID`=43664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했소! 어서 쏘시오!', `MaleText_loc4`='到了！任意开火！', `MaleText_loc5`='我們來啦!自由開火!', `MaleText_loc7`='¡Ya hemos llegado! ¡Fuego a discreción!' WHERE `ID`=43665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 됐으면... 발사 시작!', `MaleText_loc4`='准备……开火！', `MaleText_loc5`='預備...開火!', `MaleText_loc7`='¡Apunten...! ¡Fuego!' WHERE `ID`=43666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 양쪽에 있소! 저놈들을 넵튤론의 사물함에 넣어버리는 거요!', `MaleText_loc4`='两翼都是敌人！送他们去见耐普图隆！', `MaleText_loc5`='他們就在我們的兩邊!送他們去奈普圖隆的棺材!', `MaleText_loc7`='¡Están a ambos laos! ¡Mándalos direstos al fondo del mal!' WHERE `ID`=43667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키샨은 지난번에 저와 같은 상대라면 5명이 한꺼번에 덤벼도 물리칠 수 있다고 하더군요. 전 왜 이리 약할까요?', `MaleText_loc4`='有一次，基沙恩告诉我，他能同时把五个我打倒。我为什么这么弱？', `MaleText_loc5`='有一次，基沙恩說他可以一次幹掉五個我。唉，我怎麼會這麼弱啊?', `MaleText_loc7`='Una vez, Keeshan me dijo que podía cargarse a cinco de una sola vez. ¿Por qué soy tan débil?' WHERE `ID`=43668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 금은 우리 것이오! 어서 발사하시오!', `MaleText_loc4`='那金子是我们的！开火，这是命令！', `MaleText_loc5`='黑金是我們的!開火，我說開火!', `MaleText_loc7`='¿Ese oro es nuehtro! ¡Yo digo, abre fuego!' WHERE `ID`=43669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 위장한 상태를 유지하세요. 약탈의 계곡 오크들이 우릴 보면 아마 가만히 있지 않을 거예요.', `MaleText_loc4`='随时确认我们是否处于伪装状态。要是被撕裂者山谷的兽人发现，我们两个就都没命了。', `MaleText_loc5`='確認要打開偽裝功能。要是被撕裂者山谷的獸人發現，我們就死定了。', `MaleText_loc7`='Asegúrate de que vayamos siempre camuflados. Los orcos del Valle de Render nos matarán si nos ven.' WHERE `ID`=43670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 쏘시오!', `MaleText_loc4`='撤退，照我说的做！', `MaleText_loc5`='撤退!我說撤退!', `MaleText_loc7`='¡Yo digo, retirada!' WHERE `ID`=43671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 목표에 쏘시오!', `MaleText_loc4`='下次再打！', `MaleText_loc5`='再下一個!', `MaleText_loc7`='¡Vamos al siguiente!' WHERE `ID`=43672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 공격을 거두시오! 이동하겠소!', `MaleText_loc4`='暂停攻击！我们撤！', `MaleText_loc5`='停止攻擊!我們要前進!', `MaleText_loc7`='¡Deja de atacal! ¡Nos movemos!' WHERE `ID`=43673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위장하고 적 뒤편으로 돌아가면 눈에 띌 가능성이 훨씬 적어요..', `MaleText_loc4`='在伪装状态下，当我们处于敌人身后时更难被发现。', `MaleText_loc5`='偽裝的時候，躲在敵人的「背後」能讓我們更不容易被發現。', `MaleText_loc7`='Mientras estemos camuflados, resultará más difícil que nos detecten cuando estemos DETRÁS de una criatura.' WHERE `ID`=43674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 저쪽에 고블린이 더 보이는군!', `MaleText_loc4`='喂！我在那边看见更多地精！', `MaleText_loc5`='呦嘿!我看到那邊還有更多哥布林!', `MaleText_loc7`='¡Eh! ¡Hay má goblins de esos pol ahí!' WHERE `ID`=43675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섣불리 오크의 주의를 분산시키려 시도하면 역효과가 나서 오히려 오크들을 경계하게 만들 수도 있어요. 그러면 오크들이 적극적으로 우릴 찾아 나서겠죠. 은신을 감지할 수 있는 오크들과는 적당한 거리를 유지하는 편이 좋아요.', `MaleText_loc4`='有时分散注意力的行为会引发反效果，让兽人们变得多疑。在那种情况下，兽人们会主动寻找我们。最好离那些具备侦测隐形能力的兽人远一点儿。', `MaleText_loc5`='有時候，分散注意可能會引起反效果，讓獸人起疑，開始積極地尋找我們。萬一發生了這種狀況，最好跟偵測潛行的獸人保持遠一點的安全距離。', `MaleText_loc7`='A veces una distracción puede causar el efecto contrario y hacer que los orcos sospechen algo. En esos casos, los orcos nos buscarán activamente. Es mejor permanecer bien lejos de cualquier orco capaz de detectar sigilo.' WHERE `ID`=43676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 알겠소. 해안가로 돌아가겠소.', `MaleText_loc4`='遵命，长官。正在逆行返回海岸。', `MaleText_loc5`='是的，長官!準備回岸。', `MaleText_loc7`='Señol, sí, señol. Virando y regresando a tierra.' WHERE `ID`=43677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 완수하기 직전에 오크 한 마리와 마지막으로 마주치게 되는 때도 있어요. 그런 때는 마취제가 최선의 해결책이죠. 마취제를 사용하려면 적 뒤편에서 접근해야 한다는 사실만 꼭 기억해 두세요.', `MaleText_loc4`='有时我们会遇见落单的兽人，这时胜利距我们只有一步之遥。在这种情况下通常会用到麻醉。需要记住的是，若要使用麻醉，我们必须位于敌人身后。', `MaleText_loc5`='偶爾會有個落單的獸人擋住我們的勝利，通常這就是使用麻醉藥劑的最佳時機。但是要記住，我們得躲在敵人後方才能使用麻醉藥劑。', `MaleText_loc7`='De vez en cuando nos encontramos con un orco solitario que se interpone entre nosotros y la victoria. En esos casos, lo mejor es utilizar el cloroformo. Recuerda que para utilizarlo tenemos que estar detrás del enemigo.' WHERE `ID`=43678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 거라도 있소?', `MaleText_loc4`='啊，你需要什么？', `MaleText_loc5`='嘿，你要啥?', `MaleText_loc7`='¡Jarrr, sí! ¿Qué nesesitas?' WHERE `ID`=43679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구! 닻을 올리고 돛을 바로 세우시오. 싸움에 임하는 마음가짐으로 바다로 나서야 하오! 오늘 우리는 망할 투자개발회사의 장치를 날려버리고 놈들을 물고기 밥으로 만들 것이오! 당신에게 지옥을 선사하기 전에, 어서 올라타시오!', `MaleText_loc4`='嗨朋友！升锚整帆，放下舱口盖准备出海！今天我们要毁掉风险投资公司那些该死的装置，把它们统统丢进海里喂鱼！赶紧行动，别让我对你动手！', `MaleText_loc5`='呦，兄弟們!起錨揚帆，釘好艙門，準備出海啦!今天我們要去打沈風險投資公司該死的機器，把他們通通丟進海裡餵鯊魚!動作快，誰拖拖拉拉我就揍誰!', `MaleText_loc7`='Hola, broder. ¡Leva el ancla, arría la mayor, cierra las escotillas y zarpemos! ¡Hoy hundiremos esos malditos inventos de Ventura y Cía. y los enviaremos direstos a servir de comida pa los peces! ¡Ahora sube a bordo antes de que te pase la mancha negra!', `FemaleText_loc1`='친구! 닻을 올리고 돛을 바로 세우시오. 싸움에 임하는 마음가짐으로 바다로 나서야 하오! 오늘 우리는 망할 투자개발회사의 장치를 날려버리고 놈들을 물고기 밥으로 만들 것이오! 당신에게 지옥을 선사하기 전에, 어서 올라타시오!', `FemaleText_loc4`='嗨朋友！升锚整帆，放下舱口盖准备出海！今天我们要毁掉风险投资公司那些该死的装置，把它们统统丢进海里喂鱼！赶紧行动，别让我对你动手！', `FemaleText_loc5`='呦，兄弟們!起錨揚帆，蓋好艙門，準備出海啦!今天我們要去打沈風險投資公司該死的機器，把他們通通丟進海裡餵鯊魚!動作快，誰拖拖拉拉我就揍誰!', `FemaleText_loc7`='Hola, broder. ¡Leva el ancla, arría la mayor, cierra las escotillas y zarpemos! ¡Hoy hundiremos esos malditos inventos de Ventura y Cía. y los enviaremos direstos a servir de comida pa los peces! ¡Ahora sube a bordo antes de que te pase la mancha negra!' WHERE `ID`=43680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배... 배가 필요해.', `MaleText_loc4`='我……我需要一艘船。', `MaleText_loc5`='我...我需要一艘船。', `MaleText_loc7`='Necesito... un... barco.', `FemaleText_loc1`='배... 배가 필요해.', `FemaleText_loc4`='我……我需要一艘船。', `FemaleText_loc5`='我...我需要一艘船。', `FemaleText_loc7`='Necesito... un... barco.' WHERE `ID`=43681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF768EBD시포리움 폭약이 준비됐습니다. 군수품 오두막과 검은바위 탑에 접근해야 합니다.|r|TInterface\\Icons\\INV_MISC_BOMB_04.BLP:24|t
', `MaleText_loc4`='|cFF768EBD我已经准备好爆盐炸弹。我们要前往军需营帐和塔楼处。|r|TInterface\\Icons\\INV_MISC_BOMB_04.BLP:24|t', `MaleText_loc5`='|cFF768EBD我已經準備好爆鹽炸藥。我們得去炸掉軍火小屋和哨塔。|r|TInterface\\Icons\\INV_MISC_BOMB_04.BLP:24|t', `MaleText_loc7`='|cFF768EBDTengo listas las cargas de seforio. Tenemos que llegar a la cabaña del arsenal y a la torre.|r|TInterfaceIconsINV_MISC_BOMB_04.BLP:24|t' WHERE `ID`=43682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정독 중', `MaleText_loc4`='查看中', `MaleText_loc5`='閱讀中', `MaleText_loc7`='Examinando', `FemaleText_loc1`='정독 중', `FemaleText_loc4`='查看中', `FemaleText_loc5`='閱讀中', `FemaleText_loc7`='Examinando' WHERE `ID`=43683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그로그주 통입니다. 해적이 죽고 못 산다는 그로그주가 들어 있습니다.', `MaleText_loc4`='一桶烈酒。正对海盗的胃口。', `MaleText_loc5`='一桶烈酒。海盜最愛這貨色。', `MaleText_loc7`='Un barril de grog. A los piratas les encanta.' WHERE `ID`=43684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그로그주 통입니다. 해적이 죽고 못 산다는 그로그주가 들어 있습니다.$b$b병 입구는 코르크 마개로 살짝 막혀 있습니다.', `MaleText_loc4`='一桶烈酒。正对海盗的胃口。$b$b桶口的软木塞好像塞得不太紧。', `MaleText_loc5`='一桶烈酒。海盜最愛這貨色。$B$B軟木塞好像堵得不是很緊。', `MaleText_loc7`='Un barril de grog. A los piratas les encanta.$b$bParece que el corcho no encaja bien en la boca del barril.' WHERE `ID`=43685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<코르크 마개를 살살 뽑아 조금 엽니다.>', `MaleText_loc4`='<轻推木塞。>', `MaleText_loc5`='<把軟木塞弄掉。>', `MaleText_loc7`='<Presiona el corcho.>', `FemaleText_loc1`='<코르크 마개를 살살 뽑아 조금 엽니다.>', `FemaleText_loc4`='<轻推木塞。>', `FemaleText_loc5`='<把軟木塞弄掉。>', `FemaleText_loc7`='<Presiona el corcho.>' WHERE `ID`=43686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통에서 그로그주가 새어나옵니다. 해적들이 매우 화를 낼 상황입니다.', `MaleText_loc4`='酒从桶里漏了出来。这将会激怒很多海盗。', `MaleText_loc5`='烈酒從桶子裡漏了出來。有很多海盜會因為沒酒喝而非常不開心。', `MaleText_loc7`='El grog desborda el barril. Esto no le va a gustar a muchos piratas.' WHERE `ID`=43687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화약통입니다. 폭발하기 쉽습니다.', `MaleText_loc4`='一桶火药粉。爆破性极强。', `MaleText_loc5`='一桶火藥。一觸即發。', `MaleText_loc7`='Un barril de pólvora. Altamente explosivo.' WHERE `ID`=43688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화약통입니다. 옆에 물 주전자가 있습니다.', `MaleText_loc4`='一桶火药粉。旁边还放着一大罐水。', `MaleText_loc5`='一桶火藥。旁邊就擺了一大瓶水。', `MaleText_loc7`='Un barril de pólvora. Hay una jarra de agua al lado.' WHERE `ID`=43689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<화약에 물을 쏟습니다.>', `MaleText_loc4`='<把水倒在火药上。>', `MaleText_loc5`='<把水倒進火藥。>', `MaleText_loc7`='<Vierte agua en la pólvora.>', `FemaleText_loc1`='<화약에 물을 쏟습니다.>', `FemaleText_loc4`='<把水倒在火药上。>', `FemaleText_loc5`='<把水倒進火藥。>', `FemaleText_loc7`='<Vierte agua en la pólvora.>' WHERE `ID`=43690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화약이 완전히 물에 젖었습니다. 당분간은 그 누구도 대포에 이 화약을 쓸 수 없을 겁니다.', `MaleText_loc4`='火药粉完全被浸湿了。短时间内不会再有人用这火药粉发射炮弹了。', `MaleText_loc5`='火藥全都濕了。這下子沒人可用它們來發射大砲了。', `MaleText_loc7`='La pólvora está totalmente empapada. Nadie va a usarla para disparar cañones tan pronto.' WHERE `ID`=43691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 상자입니다. 포탄으로 가득 차있습니다.', `MaleText_loc4`='一个巨大的箱子，里面装满了炮弹。', `MaleText_loc5`='巨大的箱子，裝了滿滿的砲彈。', `MaleText_loc7`='Un cajón enorme, lleno hasta rebosar de balas de cañón.' WHERE `ID`=43692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 상자입니다. 포탄으로 가득 차있습니다. 옆에 식용유가 다소곳이 놓여 있습니다.', `MaleText_loc4`='一个巨大的箱子，里面装满了炮弹。旁边还放着一罐看似毫不相干的烹饪用油。', `MaleText_loc5`='巨大的箱子，裝了滿滿的砲彈。旁邊擺著一罐烹飪用油。', `MaleText_loc7`='Un cajón enorme, lleno hasta rebosar de balas de cañón. Hay una lata de grasa para cocinar al lado.' WHERE `ID`=43693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포탄에 식용유를 뿌립니다.>', `MaleText_loc4`='<用油涂抹炮弹。>', `MaleText_loc5`='<把油倒到砲彈上。>', `MaleText_loc7`='<Echa la grasa a las balas de cañón.>', `FemaleText_loc1`='<포탄에 식용유를 뿌립니다.>', `FemaleText_loc4`='<用油涂抹炮弹。>', `FemaleText_loc5`='<把油倒到砲彈上。>', `FemaleText_loc7`='<Echa la grasa a las balas de cañón.>' WHERE `ID`=43694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무거운 금속 포탄이 온통 식용유 범벅이 되었습니다. 피랠론의 해적들이 이걸 옮기려면 꽤 골치 아플 겁니다.', `MaleText_loc4`='你在这些重型金属炮弹表面涂满了油。菲尔拉伦的手下肯定很难把它们装填上去。', `MaleText_loc5`='你把油倒到沉重的金屬砲彈上。菲爾拉倫的船員在裝砲彈的時候肯定得吃上一番苦頭。', `MaleText_loc7`='Echas grasa por todos los pesados proyectiles de metal. La tripulación de Firallon va a pasar un mal rato cargándolos.' WHERE `ID`=43695;
