UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저격병 둘은 여기서 갑판을 엄호하라. 나머지는 밧줄을 이용해 모두 아래쪽으로 내려가라. 적에게 지옥을 보여주자!', `FemaleText_loc4`='让两个狙击手待在后面，掩护甲板。其他人，顺着绳子下去。让他们下地狱去吧！', `FemaleText_loc5`='我要兩個神槍手留下來掩護甲板。其他的人，利用繩索下去擊退敵人。讓他們下地獄吧!', `FemaleText_loc7`='Que dos tiradores expertos se queden y cubran la cubierta. Los demás, bajen por las sogas. ¡Destrócenlos!' WHERE `ID`=43698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보일러실에 폭발물을 설치했다. 적의 접근을 막아라!', `FemaleText_loc4`='我们在锅炉室里放了炸弹，现在先挡下他们！', `FemaleText_loc5`='我們在熔爐室內有炸彈。現在先擋下他們再說!', `FemaleText_loc7`='Tenemos los explosivos en el cuarto del caldero. ¡Manténganlos alejados!' WHERE `ID`=43699;
