UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 절대 붉은해적단을 배신하지 않을 거다. 이 풋내기 놈아!', `MaleText_loc4`='我才不会抛弃同伴，你这条只会摇尾乞怜的狗！', `MaleText_loc5`='我永遠不會離開血帆海盜，你這個聞死臭魚的!', `MaleText_loc7`='¡Nunca abandonaré los Bucaneros, especie de anacoluto de agua dulce!' WHERE `ID`=43707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너나 검을 뽑아라, 이 비열한 악당 자식아!', `MaleText_loc4`='管好你自己吧，你这专爱鹰身人的无赖！', `MaleText_loc5`='拔出武器吧，你這鷹身人仰慕者!', `MaleText_loc7`='¡Desenvaina tu asero, arrapieso besa arpías!' WHERE `ID`=43708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 퍼런 멀록같은 놈! 난 절대 배신하지 않을 거다!', `MaleText_loc4`='我才不会倒戈，你这长着绿鳃的鱼人！', `MaleText_loc5`='你這綠鰓魚人，我是絕對不會改投陣營的!', `MaleText_loc7`='¡Nunca cambiaré de bando, ehpantajo múrloc de agallas verdes!' WHERE `ID`=43709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반란이라고? 내가 진짜 반란이 뭔지 보여주지, 이 술 먹은 꼬막 같은 놈아!', `MaleText_loc4`='反叛？我让你看看什么叫反叛，你这弱不禁风的醉鬼！', `MaleText_loc5`='叛變?老醉鬼，我來告訴你什麼才叫叛變!', `MaleText_loc7`='¿Motín? ¡Yo te daré motín, mejillón charlatán relleno!' WHERE `ID`=43710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 손 좀 봐주지, 이 포탄 폭탄 맞은 얼굴아!', `MaleText_loc4`='让我来送你一程，你这只配跟炮弹接吻的大饼脸！', `MaleText_loc5`='我要一刀斃了你，你這個跟大砲親來親去的變態!', `MaleText_loc7`='¡Te atravesaré, papanatas de carnaval!' WHERE `ID`=43711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 넵튤론의 사물함에 던져버리겠다. 이 썩은 불가사리 같은 놈아!', `MaleText_loc4`='我要送你去见耐普图隆，你这条笨重的大河豚！', `MaleText_loc5`='我要把你送進奈普圖隆的棺材，死河豚胖子!', `MaleText_loc7`='¡Te mandaré diresto al fondo del mal, filibustero de tres ojos!' WHERE `ID`=43712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기 밥으로 만들어주마, 이 역겨운 트로그같은 놈아!', `MaleText_loc4`='我要拿你去喂鱼，你这下三滥的穴居人！', `MaleText_loc5`='我要把你抓去餵魚，該死的穴居怪!', `MaleText_loc7`='¡Servirás de comida pa los peces, mamarracho mequetrefe!' WHERE `ID`=43713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 눈알을 뽑아버리겠다! 이 겁쟁이 뱀장어 같은 놈아!', `MaleText_loc4`='我要把你的天灵盖刺穿，你这条没种的鳗鱼！', `MaleText_loc5`='我要把你眼珠子挖出來，死沒骨氣的軟鰻魚!', `MaleText_loc7`='¡Voy a reventalte las escotillas, rizópodo gordinflón merluzo!' WHERE `ID`=43714;
