UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르를 끌어내리는 걸 도와주러 왔소?', `MaleText_loc4`='你是来帮忙对付莫格霍尔的吗？', `MaleText_loc5`='你是來幫助我們推翻莫格的嗎?', `MaleText_loc7`='¿Has venido a ayudarnos a derrocar a Mor''ghor?' WHERE `ID`=43722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 우릴 도와줄 거라고 잴라가 말했소! 내가 뭘 하면 되겠소?', `MaleText_loc4`='扎伊拉说部落需要援助！我能做些什么？', `MaleText_loc5`='札伊拉告訴我們說部落會來幫忙!我可以做什麼?', `MaleText_loc7`='¡Zaela nos dijo que la Horda nos ayudaría! ¿Qué puedo hacer?' WHERE `ID`=43723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구는 필요 없소. 칼을 내게 주고, 누굴 해치우면 되는지만 말해주시오.', `MaleText_loc4`='不用给我盔甲。一把刀就够了，告诉我要杀谁。', `MaleText_loc5`='不必給我盔甲。只要給我把刀子，告訴我要去殺誰就好。', `MaleText_loc7`='No me des ninguna armadura. Solo dame una espada y dime a quién matar.' WHERE `ID`=43724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 왔군! 용아귀 부족도 이제 자격이 있는 자를 지도자로 삼을 때요.', `MaleText_loc4`='部落来了！是时候发挥领袖的作用了！', `MaleText_loc5`='部落來了!該是我們擁有真正的領導人的時候了。', `MaleText_loc7`='¡Ha venido la Horda! Ya era hora de que tuviésemos un líder de verdad por aquí.' WHERE `ID`=43725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 당신 곁에서 싸우겠소, $c. 우릴 도와준 걸 후회하지 않을 거요!', `MaleText_loc4`='我会与你并肩作战，$c。你不会后悔帮助我们的！', `MaleText_loc5`='我會跟你並肩作戰，$c。你絕對不會後悔幫了我們的!', `MaleText_loc7`='Lucharé a tu lado, $c. ¡No lamentarás habernos ayudado!' WHERE `ID`=43726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 함께 싸웁시다! 이 검을 받고 전사가 되어 주십시오.', `MaleText_loc4`='与我一同战斗！拿起这把刀，像战士一样厮杀！', `MaleText_loc5`='和我一起作戰!拿起武器，當個真正的戰士。', `MaleText_loc7`='¡Lucha conmigo! Blande esa espada y sé un guerrero.', `FemaleText_loc1`='저와 함께 싸웁시다! 이 검을 받고 전사가 되어 주세요.', `FemaleText_loc4`='与我一同战斗！拿起这把刀，像战士一样厮杀！', `FemaleText_loc5`='和我並肩作戰!拿起武器，當個真正的戰士。', `FemaleText_loc7`='¡Lucha conmigo! Blande esa espada y sé un guerrero.' WHERE `ID`=43727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락한 오크 놈들, 좀 봐줄까 했는데 오늘은 날이 아니군.', `MaleText_loc4`='看来今天不是个戒杀兽人的好日子。', `MaleText_loc5`='看來我選錯了停止殺魔獄獸人的日子了。', `MaleText_loc7`='Parece que he elegido un mal día para dejar de matar orcos viles.', `FemaleText_loc1`='타락한 오크 놈들, 좀 봐줄까 했는데 오늘은 날이 아니군요.', `FemaleText_loc4`='看来今天不是个戒杀兽人的好日子。', `FemaleText_loc5`='看來我選錯了停止殺魔獄獸人的日子了。', `FemaleText_loc7`='Parece que he elegido un mal día para dejar de matar orcos viles.' WHERE `ID`=43728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 심판의 날이오, $c!', `MaleText_loc4`='今天是审判日，$c！', `MaleText_loc5`='報仇的時候到了，$c!', `MaleText_loc7`='¡Hoy se hará justicia, $c!', `FemaleText_loc1`='오늘은 심판의 날입니다, $c님!', `FemaleText_loc4`='今天是审判日，$c！', `FemaleText_loc5`='報仇的時候到了，$c!', `FemaleText_loc7`='¡Hoy se hará justicia, $c!' WHERE `ID`=43729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 데려가 주시오! 난 싸울 준비가 됐소!', `MaleText_loc4`='算我一个，教官！我做好战斗的准备了！', `MaleText_loc5`='教練，讓我上場!我已經準備好了!', `MaleText_loc7`='¡Cuenta conmigo, entrenador! ¡Estoy listo para luchar!', `FemaleText_loc1`='절 데려가 주세요! 전 싸울 준비가 됐어요!', `FemaleText_loc4`='算我一个，教官！我做好战斗的准备了！', `FemaleText_loc5`='教練，讓我上場!我已經準備好了!', `FemaleText_loc7`='¡Cuenta conmigo, entrenador! ¡Estoy lista para luchar!' WHERE `ID`=43730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르고르의 독재는 오늘 끝날 거요.', `MaleText_loc4`='今天莫格霍尔的暴行即将终结。', `MaleText_loc5`='莫格的暴政就到今天為止了。', `MaleText_loc7`='Hoy se acabará la tiranía de Mor''ghor.', `FemaleText_loc1`='모르고르의 독재는 오늘 끝날 겁니다.', `FemaleText_loc4`='今天莫格霍尔的暴行即将终结。', `FemaleText_loc5`='莫格的暴政就到今天為止了。', `FemaleText_loc7`='Hoy se acabará la tiranía de Mor''ghor.' WHERE `ID`=43731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이거요, $c! 혁명을 일으키는 거요.', `MaleText_loc4`='没错，$c！革命开始了！', `MaleText_loc5`='就是這樣，$c!革命要開始了。', `MaleText_loc7`='¡Eso es, $c! ¡La revolución ha llegado!', `FemaleText_loc1`='바로 이거죠, $c님! 혁명을 일으키는 겁니다.', `FemaleText_loc4`='没错，$c！革命开始了！', `FemaleText_loc5`='就是這樣，$c!革命要開始了。', `FemaleText_loc7`='¡Eso es, $c! ¡La revolución ha llegado!' WHERE `ID`=43732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c! 잴라가 말하길 호드가 무기를 지원해 줬다던데. 뭘 가지고 왔소?', `MaleText_loc4`='$c！扎伊拉说部落为我们准备了武器。有些什么呢？', `MaleText_loc5`='$c!札伊拉說部落會提供武器給我們。你帶來了什麼?', `MaleText_loc7`='¡$c! Zaela dijo que la Horda nos daría armas. ¿Tú qué tienes?', `FemaleText_loc1`='$c님! 잴라가 말하길 호드가 무기를 지원해 줬다던데요. 뭘 가지고 오셨죠?', `FemaleText_loc4`='$c！扎伊拉说部落为我们准备了武器。有些什么呢？', `FemaleText_loc5`='$c!札伊拉說部落會提供武器給我們。你帶來了什麼?', `FemaleText_loc7`='¡$c! Zaela dijo que la Horda nos daría armas. ¿Tú qué tienes?' WHERE `ID`=43733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오!', `MaleText_loc4`='嗨，你好！', `MaleText_loc5`='呦呴!', `MaleText_loc7`='¡Ah del barco!' WHERE `ID`=43734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺽다리 존 코퍼, 난폭파도 해적단은 공격할 준비가 된 건가?', `MaleText_loc4`='长牙约翰·库珀，“急浪船帮”做好战斗准备了吗？', `MaleText_loc5`='長腳約翰·庫伯，驟潮號的船員準備好開戰了嗎?', `MaleText_loc7`='John Copper el Largo, ¿está la Tripulación Fuertemarea lista para la batalla?', `FemaleText_loc1`='꺽다리 존 코퍼, 난폭파도 해적단은 공격할 준비가 된 건가?', `FemaleText_loc4`='长牙约翰·库珀，“急浪船帮”做好战斗准备了吗？', `FemaleText_loc5`='長腳約翰·庫伯，驟潮號的船員準備好開戰了嗎?', `FemaleText_loc7`='John Copper el Largo, ¿está la tripulación Fuertemarea lista para la batalla?' WHERE `ID`=43735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그렇습니다! 우린 길니아스에서 너무 오랜 시간을 기다렸습니다. 이제 검에 피를 묻힐 준비가 되었습니다!', `MaleText_loc4`='是的，$g 阁下: 女士;！我们已经在吉尔尼斯蓄势已久。我们渴望鲜血！', `MaleText_loc5`='是，$g長官:長官;!我們已在吉爾尼斯等待太久了。我們已經準備好要血債血還!', `MaleText_loc7`='¡Sí, $gseñor:señora;! Hemos esperado la hora propicia en Gilneas demasiado tiempo. ¡Estamos listos para la masacre!' WHERE `ID`=43736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 얼굴에 뭐라도 묻었소?', `MaleText_loc4`='你在看什么，$r？', `MaleText_loc5`='你在看什麼看，$r?', `MaleText_loc7`='¿Qué miras, $r?' WHERE `ID`=43737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난폭파도 해적단에 대해 아는 대로 말해봐.', `MaleText_loc4`='关于“急浪船帮”，你能告诉我什么？', `MaleText_loc5`='可以告訴我驟潮號船員的什麼事情嗎?', `MaleText_loc7`='¿Qué me puedes contar sobre la Tripulación Fuertemarea?', `FemaleText_loc1`='난폭파도 해적단에 대해 아는 대로 말해봐.', `FemaleText_loc4`='关于“急浪船帮”，你能告诉我什么？', `FemaleText_loc5`='可以告訴我驟潮號船員的什麼事情嗎?', `FemaleText_loc7`='¿Qué me puedes contar sobre la Tripulación Fuertemarea?' WHERE `ID`=43739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 한 때 바다를 주름잡았습니다... 그 망할 그레이메인이 길니아스의 항구를 닫게 하기 전까지만 해도 말이죠! 그놈만 아니었다면, 우린 늑대인간이 되지 않았을 텐데...', `MaleText_loc4`='我们曾在海上自由驰骋……直到该死的格雷迈恩国王把吉尔尼斯海港给封了！要不是因为他，我们就不会……', `MaleText_loc5`='本來我們還可以自由的遨遊大海...直到該死的葛雷邁恩國王把吉爾尼斯的港口全都封了!要不是因為他，我們也不會...', `MaleText_loc7`='Solíamos vagar por los mares... ¡Hasta que ese maldito del rey Cringris cerró los puertos de Gilneas! Si por él fuera, estaríamos todos...' WHERE `ID`=43740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='需要我帮忙吗？', `FemaleText_loc5`='需要幫忙嗎?', `FemaleText_loc7`='¿Puedo ayudarte?' WHERE `ID`=43741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 공격 계획을 잊어버린 건 아니겠지?', `MaleText_loc4`='你知道作战计划，对吧？', `MaleText_loc5`='你知道戰鬥計畫是什麼，對吧?', `MaleText_loc7`='¿Conoces el plan de ataque, no?', `FemaleText_loc1`='설마 공격 계획을 잊어버린 건 아니겠지?', `FemaleText_loc4`='你知道作战计划，对吧？', `FemaleText_loc5`='你知道戰鬥計畫是什麼，對吧?', `FemaleText_loc7`='¿Conoces el plan de ataque, no?' WHERE `ID`=43742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가 있겠습니까. 선장님이 신호를 보내면 북쪽에서 공격해 들어가는 게 우리 계획이지요. 난폭파도 해적단이 무법항을 쓸어버릴 겁니다! 워우우우우!!!!', `FemaleText_loc4`='是，$g阁下:女士;。我们根据您的信号指示从北面发起攻击。 “急浪船帮”将荡涤藏宝海湾！喔啰！！！', `FemaleText_loc5`='是的，$g長官:長官;。等你號令一下，我們就從北方展開攻擊。驟潮號會血洗藏寶海灣!耶!!!!', `FemaleText_loc7`='Sí, $gseñor:señora;. Atacamos desde el norte a tu señal. ¡El Fuertemarea invadirá Bahía del Botín! ¡¡¡¡Arrr!!!!' WHERE `ID`=43743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 지원하고 치유해 주시면 좋겠습니다! 이 전쟁망치를 받고 주술사가 되어 주십시오.', `MaleText_loc4`='快来帮助和治疗我！拿起这把战锤，有点萨满祭司的样子。', `MaleText_loc5`='支援和治療我!拿起這把戰錘，當個薩滿。', `MaleText_loc7`='¡Cúbreme y sáname! Toma este martillo de guerra y sé un chamán.', `FemaleText_loc1`='절 지원하고 치유해 주시면 좋겠어요! 이 전쟁망치를 받고 주술사가 되어 주세요.', `FemaleText_loc4`='快来帮助和治疗我！拿起这把战锤，有点萨满祭司的样子。', `FemaleText_loc5`='支援和治療我!拿起這把戰錘，當個薩滿。', `FemaleText_loc7`='¡Cúbreme y sáname! Toma este martillo de guerra y sé un chamán.' WHERE `ID`=43744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집사람이 실종됐소! 도와주시오!', `MaleText_loc4`='我的另一半走丢了！快帮帮我！', `MaleText_loc5`='我的配偶失蹤了!請幫幫我!', `MaleText_loc7`='¡Mi esposa ha desaparecido! ¡Ayuda!', `FemaleText_loc1`='우리 남편이 실종됐어요! 도와주세요!', `FemaleText_loc4`='我的另一半走丢了！快帮帮我！', `FemaleText_loc5`='我的配偶失蹤了!請幫幫我!', `FemaleText_loc7`='¡Mi marido ha desaparecido! ¡Ayuda!' WHERE `ID`=43745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 사람들이 사라지고 있소, 솔로몬. 이제 어쩔 셈이오?', `MaleText_loc4`='镇民正在不断消失，所罗门。你打算怎么办？', `MaleText_loc5`='有鎮民失蹤了，所羅門。你有什麼打算?', `MaleText_loc7`='Los ciudadanos están desapareciendo, Solomon. ¿Qué vas a hacer al respecto?', `FemaleText_loc1`='마을 사람들이 사라지고 있어요, 솔로몬. 이제 어떻게 하실 건가요?', `FemaleText_loc4`='镇民正在不断消失，所罗门。你打算怎么办？', `FemaleText_loc5`='有鎮民失蹤了，所羅門。你有什麼打算?', `FemaleText_loc7`='Los ciudadanos están desapareciendo, Solomon. ¿Qué vas a hacer al respecto?' WHERE `ID`=43746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 차리시오, 집정관! 놀의 공격이 평상시와는 다르단 말이오!', `MaleText_loc4`='该醒醒了，长官！这次不是普通的豺狼人攻击！', `MaleText_loc5`='該醒醒了，鎮長!這不是普通的豺狼人攻擊!', `MaleText_loc7`='¡Es hora de despertar, magistrado! ¡No se trata un ataque gnoll normal!', `FemaleText_loc1`='정신 차리세요, 집정관님! 놀의 공격이 평상시와는 달라요!', `FemaleText_loc4`='该醒醒了，长官！这次不是普通的豺狼人攻击！', `FemaleText_loc5`='該醒醒了，鎮長!這不是普通的豺狼人攻擊!', `FemaleText_loc7`='¡Es hora de despertar, magistrado! ¡No se trata un ataque gnoll normal!' WHERE `ID`=43747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에 요청한 지원군은 언제 도착합니까?', `MaleText_loc4`='我们从暴风城请来的援兵呢？', `MaleText_loc5`='我們跟暴風城要求的援助到底在哪裡?', `MaleText_loc7`='¿Dónde está la ayuda que pedimos a Ventormenta?', `FemaleText_loc1`='스톰윈드에 요청한 지원군은 언제 도착하나요?', `FemaleText_loc4`='我们从暴风城请来的援兵呢？', `FemaleText_loc5`='我們跟暴風城要求的援助到底在哪裡?', `FemaleText_loc7`='¿Dónde está la ayuda que pedimos a Ventormenta?' WHERE `ID`=43748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병이라는 사람들이 겨우 놀 몇 마리도 처리하지 못하는데, 대체 우리가 세금을 왜 내야 하는 거요?', `MaleText_loc4`='要是你的卫兵连豺狼人都阻挡不了，那我们为什么要交税给你？', `MaleText_loc5`='要是你的衛兵連豺狼人都擋不住的話，我們交稅是交假的啊?', `MaleText_loc7`='¿Para qué pagamos impuestos si los guardias no pueden protegernos de los gnolls?', `FemaleText_loc1`='경비병이라는 사람들이 겨우 놀 몇 마리도 처리하지 못하는데, 우리가 세금을 왜 내야 하나요?', `FemaleText_loc4`='要是你的卫兵连豺狼人都阻挡不了，那我们为什么要交税给你？', `FemaleText_loc5`='要是你的衛兵連豺狼人都擋不住的話，我們交稅是交假的啊?', `FemaleText_loc7`='¿Para qué pagamos impuestos si los guardias no pueden protegernos de los gnolls?' WHERE `ID`=43749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠을 자던 아이들이 납치당했단 말이오! 무슨 말이라도 해 보시오, 솔로몬!', `MaleText_loc4`='我的孩子在睡梦中被劫走了！我想要知道真相，所罗门！', `MaleText_loc5`='我的孩子們在睡覺的時候被抓走了!我要答案，所羅門!', `MaleText_loc7`='¡Han secuestrado a mis hijos mientras dormían! ¡EXIJO RESPUESTAS, SOLOMON!', `FemaleText_loc1`='잠을 자던 아이들이 납치됐어요! 무슨 말이라도 해 보세요, 집정관님!', `FemaleText_loc4`='我的孩子在睡梦中被劫走了！我想要知道真相，所罗门！', `FemaleText_loc5`='我的孩子們在睡覺的時候被抓走了!我要答案，所羅門!', `FemaleText_loc7`='¡Han secuestrado a mis hijos mientras dormían! ¡EXIJO RESPUESTAS, SOLOMON!' WHERE `ID`=43750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 무슨 조치를 취하지 않으면, 나부터 당장 들고일어날 거요, 솔로몬!', `MaleText_loc4`='你最好赶紧采取行动，不然暴乱是难免的了，所罗门！', `MaleText_loc5`='你最好趕緊採取行動，不然就要發生暴動了，所羅門!', `MaleText_loc7`='¡Más te vale hacer algo rápido o pronto tendrás un motín entre manos, Solomon!', `FemaleText_loc1`='당장 무슨 조치를 취하지 않으면, 저부터도 당장 들고일어나겠어요, 집정관님!', `FemaleText_loc4`='你最好赶紧采取行动，不然暴乱是难免的了，所罗门！', `FemaleText_loc5`='你最好趕緊採取行動，不然就要發生暴動了，所羅門!', `FemaleText_loc7`='¡Más te vale hacer algo rápido o pronto tendrás un motín entre manos, Solomon!' WHERE `ID`=43751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀이 지금껏 이렇게 공격적인 때가 없었소. 대체 무슨 일이 일어나고 있는 거요, 솔로몬? 말해 보시오!', `MaleText_loc4`='豺狼人从没这么放肆过。到底怎么了，所罗门？快告诉我们！', `MaleText_loc5`='豺狼人從來沒有這麼大膽。到底是怎麼回事，所羅門?告訴我們!', `MaleText_loc7`='Los gnolls nunca habían sido tan agresivos. ¿Qué sucede, Solomon? ¡Dinos!', `FemaleText_loc1`='지금까지 놀이 이렇게 공격적으로 행동한 적이 없었어요. 대체 무슨 일이 일어나고 있는 거죠, 솔로몬? 말해 보시라고요!', `FemaleText_loc4`='豺狼人从没这么放肆过。到底怎么了，所罗门？快告诉我们！', `FemaleText_loc5`='豺狼人從來沒有這麼大膽。到底是怎麼回事，所羅門?告訴我們!', `FemaleText_loc7`='Los gnolls nunca habían sido tan agresivos. ¿Qué sucede, Solomon? ¡Dinos!' WHERE `ID`=43752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 여기서 얼마나 기다려야 우리 말을 들어주겠소?', `MaleText_loc4`='我们得在这儿站多久，才会有人听到我们的恳求？', `MaleText_loc5`='要在這邊站上多久我們的要求才會被聽進去?', `MaleText_loc7`='¿Cuánto tiempo debemos estar aquí para que se escuchen nuestras súplicas?', `FemaleText_loc1`='대체 여기서 얼마나 기다려야 우리 말을 들어주실 건가요?', `FemaleText_loc4`='我们得在这儿站多久，才会有人听到我们的恳求？', `FemaleText_loc5`='要在這邊站上多久我們的要求才會被聽進去?', `FemaleText_loc7`='¿Cuánto tiempo debemos estar aquí para que se escuchen nuestras súplicas?' WHERE `ID`=43753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 빨리빨리 좀 합시다!', `MaleText_loc4`='快让这该死的队伍动起来！', `MaleText_loc5`='前面排隊的都不動是怎樣!', `MaleText_loc7`='¡Que esta línea siga moviéndose!', `FemaleText_loc1`='거기 빨리빨리 좀 하자고요!', `FemaleText_loc4`='快让这该死的队伍动起来！', `FemaleText_loc5`='動起來!該死的隊伍動起來!', `FemaleText_loc7`='¡Que esta línea siga moviéndose!' WHERE `ID`=43754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔로몬, 이 아무짝에도 쓸모없는 사람 같으니라고!', `MaleText_loc4`='你一无是处，所罗门！', `MaleText_loc5`='你一點用也沒有，所羅門!', `MaleText_loc7`='¡No sirves para nada, Solomon!', `FemaleText_loc1`='솔로몬, 이 아무짝에도 쓸모없는 사람 같으니!', `FemaleText_loc4`='你一无是处，所罗门！', `FemaleText_loc5`='你一點用也沒有，所羅門!', `FemaleText_loc7`='¡No sirves para nada, Solomon!' WHERE `ID`=43755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재선은 꿈도 꾸지 마시오, 집정관!', `MaleText_loc4`='你别想连任了，地方官！', `MaleText_loc5`='你別妄想連任了，鎮長!', `MaleText_loc7`='¡No te puedes olvidar de las reelecciones, magistrado!', `FemaleText_loc1`='재선은 꿈도 꾸지 마세요, 집정관!', `FemaleText_loc4`='你别想连任了，地方官！', `FemaleText_loc5`='你別妄想連任了，鎮長!', `FemaleText_loc7`='¡No te puedes olvidar de las reelecciones, magistrado!' WHERE `ID`=43756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의가 없다면 평화도 없다!', `MaleText_loc4`='没有正义，没有和平！', `MaleText_loc5`='沒有正義，沒有和平!', `MaleText_loc7`='¡Si no hay justicia, no habrá paz!', `FemaleText_loc1`='정의가 없으면 평화도 없어요!', `FemaleText_loc4`='没有正义，没有和平！', `FemaleText_loc5`='沒有正義，沒有和平!', `FemaleText_loc7`='¡Si no hay justicia, no habrá paz!' WHERE `ID`=43757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 이 놀 녀석들을 어떻게 하지 않으면, 우리가 나서겠소!', `MaleText_loc4`='要是你不对这些豺狼人采取行动，我们要动手了！', `MaleText_loc5`='你再不想辦法解決這些豺狼人，我們就要自己來了!', `MaleText_loc7`='¡Si no haces nada con los gnoll, nosotros lo haremos!', `FemaleText_loc1`='당장 저 놀들을 어떻게 하지 않으면, 우리가 나서겠어요!', `FemaleText_loc4`='要是你不对这些豺狼人采取行动，我们要动手了！', `FemaleText_loc5`='你再不想辦法解決這些豺狼人，我們就要自己來了!', `FemaleText_loc7`='¡Si no haces nada con los gnoll, nosotros lo haremos!' WHERE `ID`=43758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주시오! 우리 가족도 이제 나밖에 남지 않았단 말이오. 다들 납치당했다고!', `MaleText_loc4`='快帮帮我！我全家只剩我一个了。其它人都被劫走了！', `MaleText_loc5`='請幫幫我!我全家就只剩下我一個人而已，他們全部都被綁架了!', `MaleText_loc7`='¡Ayudadme! Soy el único miembro que queda de mi familia. ¡Los han secuestrado a todos!', `FemaleText_loc1`='도와주세요! 우리 가족도 이제는 저밖에 남지 않았어요. 다들 납치당했다고요!', `FemaleText_loc4`='快帮帮我！我全家只剩我一个了。其它人都被劫走了！', `FemaleText_loc5`='請幫幫我!我全家就只剩下我一個人而已，他們全部都被綁架了!', `FemaleText_loc7`='¡Ayudadme! Soy el único miembro que queda de mi familia. ¡Los han secuestrado a todos!' WHERE `ID`=43759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관두시오, 솔로몬. 내 가족은 내가 직접 찾아내겠소.', `MaleText_loc4`='不指望你了，所罗门。我会自己找到我的家人。', `MaleText_loc5`='不指望你了，所羅門。我會自己找到我的家人。', `MaleText_loc7`='¡Olvídalo, Solomon! Encontraré a mí familia yo solo.', `FemaleText_loc1`='그만두세요, 솔로몬. 제 가족은 제가 직접 찾아내겠어요.', `FemaleText_loc4`='不指望你了，所罗门。我会自己找到我的家人。', `FemaleText_loc5`='不指望你了，所羅門。我會自己找到我的家人。', `FemaleText_loc7`='¡Olvídalo, Solomon! Encontraré a mí familia yo sola.' WHERE `ID`=43760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 한심한 반란은 여기서 끝이다!', `MaleText_loc4`='这场可悲的革命，到此为止了！', `MaleText_loc5`='這場可笑的革命到此結束!', `MaleText_loc7`='¡Esta revolución patética acaba ya!' WHERE `ID`=43761;
