UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<레빌가즈 남작의 개인 물품임. 어떤 상황에서도 절대 건드리지 말 것!>', `MaleText_loc4`='<大财主里维加兹的私人宝物。任何时候都不要乱动！>', `MaleText_loc5`='<大財主里維加茲的私人股票。無論如何都不許碰!>', `MaleText_loc7`='<Reserva privada del Barón Revilgaz. ¡No tocar bajo ninguna circunstancia!>' WHERE `ID`=43771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신에게 물어라, $n. 이 행동이 투자개발회사에 이익을 가져다줄 수 있는지.', `MaleText_loc4`='问问你自己，$n——这对风险投资公司有利吗？', `MaleText_loc5`='問問你自己，$n:這對風險投資公司有好處嗎?', `MaleText_loc7`='Plantéatelo, $n: ¿es bueno para Ventura y Cía.?', `FemaleText_loc1`='자신에게 물어라, $n. 이 행동이 투자개발회사에 이익을 가져다줄 수 있는지.', `FemaleText_loc4`='问问你自己，$n——这对风险投资公司有利吗？', `FemaleText_loc5`='問問你自己，$n:這對風險投資公司有好處嗎?', `FemaleText_loc7`='Plantéatelo, $n: ¿es bueno para Ventura y Cía.?' WHERE `ID`=43772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 스랄이 생각하는 것보다 더 그롬을 닮았네. 악마의 피가 없어도 말이야.', `MaleText_loc4`='虽然没有恶魔之血，但你却比自己所想的更像你父亲。', `MaleText_loc5`='我想你比自己想的更像你的父親，雖然你體內沒有流著惡魔之血。', `MaleText_loc7`='Eres como tu padre, más de lo que pensabas; aun sin la sangre del demonio.' WHERE `ID`=43773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 이건 나 같은 늙은이가 걱정할 일이지. 자넨 아직 배울 게 많네. 가서 검은창 부족을 돕게. 우린 곧 다시 만나게 될 게야.', `MaleText_loc4`='把这些担忧留给老家伙们。而你还有很多东西要学。去帮助暗矛的族人吧。相信我们很快就会再见面的。', `MaleText_loc5`='但這些是老人該擔心的。你還有很多該學的。去幫助暗矛的人民吧。我相信我們很快就會再見面的。', `MaleText_loc7`='Pero la reflexión requiere una mente adulta. Tú tienes mucho que aprender. Ve a ayudar a los Lanza Negra. Volveremos a hablar pronto.' WHERE `ID`=43774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가볍게 결정한 게 아니라네, 볼진. 우리의 동맹이 흔들릴 것임을 아네. 호드가 되돌릴 수 없을 만큼 변하리란 것도 아네. 하지만, 호드에 필요한 인물이 바로 가로쉬임을 확신하기에 그를 선택했네.', `MaleText_loc4`='我做出这个决定并不轻松。我知道，我们的盟友将因此承受磨难。部落将发生无可挽回的改变。但我相信，加尔鲁什正是部落现在所需要的人。', `MaleText_loc5`='這不是個輕率的決定，沃金。我知道我們的同盟將會受難，我也知道部落將會永遠的改變，但我對這個決定有信心，部落就是需要卡爾洛斯這種人。', `MaleText_loc7`='Lo reflexioné mucho antes de decidirme. Sé que nuestras alianzas lo sufrirán. Sé que la Horda cambiará irreversiblemente. Pero tomé esta decisión seguro de que Garrosh es exactamente lo que necesita la Horda.' WHERE `ID`=43775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와 다른 지도자들이 우리 호드의 분열을 보고만 있지는 않겠지. 난 그대들을 믿네.', `MaleText_loc4`='我相信你和其他领袖不会让我们的族人因此而分裂。你们有足够的力量。', `MaleText_loc5`='我信任你和其他的領導者們不會因此讓部落分裂。我對你的力量有信心。', `MaleText_loc7`='Confío en que tú y los otros líderes no permitirán que esto nos divida. Tienen la fuerza para ello.' WHERE `ID`=43776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 난 스랄이 언젠가 우리에게 돌아오길 바라네. 지금은 미래에서 암울함과 피비린내밖에 느낄 수가 없군.', `MaleText_loc4`='但，我还是希望萨尔终有一天能够回来。现在我眼中的未来只剩下了暴力和血腥。', `MaleText_loc5`='但，我希望有一天索爾會回來。目前看來我們的未來非常嚴酷和血腥。', `MaleText_loc7`='Pero guardo la esperanza de que Thrall regrese un día. Ahora el futuro es sombrío y sangriento.' WHERE `ID`=43777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가게. 검은창 부족을 명예롭게 해 주게. 수많은 전투가 우리를 기다리고 있네. 그리고 자네는 어느 전투에서든 중요한 역할을 할 게야.', `MaleText_loc4`='去吧，让暗矛部族以你为傲。我们前方还有很多战斗。我相信你会和我们一起走到底。', `MaleText_loc5`='去吧，讓暗矛感到驕傲。我們眼前有許多場戰爭，而你將在它們之中佔有一席之地。', `MaleText_loc7`='Vayan. Honren a la Lanza Negra. Hay muchas guerras por delante, estoy seguro de que participarán en todas.' WHERE `ID`=43778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아아아아아아아아!', `MaleText_loc4`='啊啊啊！', `MaleText_loc5`='啊啊啊啊啊啊啊啊啊!', `MaleText_loc7`='¡AAAAAAAHHHHHHHHHHHHHHHHH!' WHERE `ID`=43779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아!', `MaleText_loc4`='啊啊啊！', `MaleText_loc5`='啊啊啊啊啊!', `MaleText_loc7`='¡AAAAAAAAAAAHH!' WHERE `ID`=43780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요오오오오오오!', `MaleText_loc4`='救——命！', `MaleText_loc5`='救命啊啊啊啊啊啊!', `MaleText_loc7`='¡AYUDAAAAAA!' WHERE `ID`=43781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 맙소사. 놈들이 왔네! 아아아아아악!', `MaleText_loc4`='喔上帝，他们来了！啊——！', `MaleText_loc5`='噢，天啊，他們來了!啊啊啊啊啊!', `MaleText_loc7`='¡MADREEEE, ESTÁN AQUÍ! ¡AHHHHHHHH!' WHERE `ID`=43782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적이다! 아아아아아아아!', `MaleText_loc4`='海盗！啊——！', `MaleText_loc5`='海盜!啊啊啊啊啊!', `MaleText_loc7`='¡PIRATAS! ¡AAAAAHHHHH!' WHERE `ID`=43783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조니, 우리가 방금 붉은마루 산맥의 절반을 폭파시켜 버렸다는 사실을 알고는 있는거야?', `MaleText_loc4`='强尼，你意识到我们刚才把半个赤脊山给炸毁了，对吧？', `MaleText_loc5`='強尼，你知道我們才剛把半個赤脊山都給炸了，對吧?', `MaleText_loc7`='Johnny, ¿te das cuenta de que solo hemos derrotado a la mitad de los Crestagrana, verdad?' WHERE `ID`=43784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 공황 상태에 빠질 시간이에요!', `MaleText_loc4`='各位，恐慌时间到了！', `MaleText_loc5`='全部的人，現在應該開始害怕了!', `MaleText_loc7`='¡AHORA ES EL MOMENTO DE QUE CUNDA EL PÁNICO!' WHERE `ID`=43785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은마루 산맥은 회복할 거야. 오크 녀석들은 그러지 못할 테지만...', `MaleText_loc4`='赤脊山将会得到治愈，可那群兽人当然不会……', `MaleText_loc5`='赤脊山過一陣子就會沒事了，但獸人他們可就死透了...', `MaleText_loc7`='Crestagrana sanará, pero los orcos seguro que no...' WHERE `ID`=43786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무서워요!', `MaleText_loc4`='我好怕！', `MaleText_loc5`='我怕死了!', `MaleText_loc7`='¡TENGO MIEDO!' WHERE `ID`=43787;
