UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 가호가 함께하길.', `MaleText_loc4`='愿圣光保护你， $c。', `MaleText_loc5`='願聖光保護你，$c。', `MaleText_loc7`='Que la Luz te proteja, $c.', `FemaleText_loc1`='빛의 가호가 함께하길.', `FemaleText_loc4`='愿圣光保护你， $c。', `FemaleText_loc5`='願聖光保護你，$c。', `FemaleText_loc7`='Que la Luz te proteja, $c.' WHERE `ID`=43832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양의 빛이 지혜로 가는 길을 밝게 비춥니다. 오늘은 저와 함께 어떤 길을 걷겠습니까?', `MaleText_loc4`='太阳的光辉照耀着通往智慧的道路。我们今天要去哪儿，朋友？', `MaleText_loc5`='日光照亮智慧之道。朋友，今日我等將踏向何處?', `MaleText_loc7`='La luz del Sol ilumina el camino a la sabiduría. ¿Por dónde quieres caminar hoy, $gamigo mío:amiga mía;?', `FemaleText_loc1`='태양의 빛이 지혜로 가는 길을 밝게 비춥니다. 오늘은 저와 함께 어떤 길을 걷겠습니까?', `FemaleText_loc4`='太阳的光辉照耀着通往智慧的道路。我们今天要去哪儿，朋友？', `FemaleText_loc5`='日光照亮智慧之道。朋友，今日我等將踏向何處?', `FemaleText_loc7`='La luz del Sol ilumina el camino a la sabiduría. ¿Por dónde quieres caminar hoy, $gamigo mío:amiga mía;?' WHERE `ID`=43833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양의 빛이 당신을 보호하길.', `MaleText_loc4`='愿太阳的光辉守护你，$c。', `MaleText_loc5`='願日光保護你，$c。', `MaleText_loc7`='Que la luz del Sol te proteja, $c.', `FemaleText_loc1`='태양의 빛이 당신을 보호하길.', `FemaleText_loc4`='愿太阳的光辉守护你，$c。', `FemaleText_loc5`='願日光保護你，$c。', `FemaleText_loc7`='Que la luz del Sol te proteja, $c.' WHERE `ID`=43834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 더러운 물질을 없애야겠군...', `MaleText_loc4`='现在，摧毁这些可恶的东西……', `MaleText_loc5`='是時候消滅這個有害物質...', `MaleText_loc7`='Ahora destruyamos esta sustancia…' WHERE `ID`=43835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아!', `MaleText_loc4`='啊！！！', `MaleText_loc5`='啊啊啊啊!', `MaleText_loc7`='¡Arrghhhhh!' WHERE `ID`=43836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비되면 비행을 시작하겠다.', `MaleText_loc4`='等所有人都准备好，我们就出发。', `MaleText_loc5`='等大家都準備好我們就立刻出發。', `MaleText_loc7`='Despegaremos cuando todo el mundo esté listo.' WHERE `ID`=43837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 참아라, 친구. 곧 공격할 테니까.', `MaleText_loc4`='耐心点儿，朋友们。我们很快就会出击。', `MaleText_loc5`='耐心點，朋友們。我們很快就會出擊。', `MaleText_loc7`='Paciencia, amigo. Pronto atacaremos.' WHERE `ID`=43838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려라, 친구. 준비가 되면 적들을 공격할 테니까.', `MaleText_loc4`='别着急，朋友。等大家都准备好，我们就会出击。', `MaleText_loc5`='暫且勒住馬匹，朋友們。我們等準備周全了再發動攻擊。', `MaleText_loc7`='No te pongas nervioso, camarada. Atacaremos cuando estemos listos.' WHERE `ID`=43839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 모일 때까지 조금 기다리지. 함께 갈 사람들이 필요하니까.', `MaleText_loc4`='给大家集合的时间。我们需要找些人跟我们一起去。', `MaleText_loc5`='大家先休息一下。我們還要再等幾個人過來。', `MaleText_loc7`='Vamos a esperar a que se reúnan todos. Necesitaremos que un buen puñado de gente venga con nosotros.' WHERE `ID`=43840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세찬물결 굽이는 서쪽에 있다.', `MaleText_loc4`='蚀沙荒漠就在西边。', `MaleText_loc5`='沖蝕之境在這的西邊。', `MaleText_loc7`='El Tramo Rozado está al oeste.' WHERE `ID`=43841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낭비하지 않았습니다, 바위 어머니시여. 저것은 매우 유용합니다.', `MaleText_loc4`='这不是浪费，石母。它派上了不小的用场。', `MaleText_loc5`='沒有浪費，石母。他非常的有用。', `MaleText_loc7`='No es desperdicio, Madre Pétrea. Ha sido muy útil.' WHERE `ID`=43842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행동을 볼 때, 여기 온 이유에 대한 저것의 이야기가 사실일 수도 있습니다.', `MaleText_loc4`='它站在这个地方的原因也许正如它所说的那样。', `MaleText_loc5`='他想告訴我們他在這的原因跟他所說的一模一樣。', `MaleText_loc7`='Es lógico que esté aquí exactamente por las razones que dice.' WHERE `ID`=43843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신뢰를 얻으려면 갈 길이 멀다. 어쨌든 페이나이트는 가져왔군. 시작이 좋구나.', `MaleText_loc4`='你有许多需要证明的事情。但看样子，你已经带来了那块石头。这是个好的开始。', `MaleText_loc5`='你還有很多需要證明的。但看來你把石頭帶來了。那是個好的開始。', `MaleText_loc7`='Tú tienes mucho que probar. Pero trajiste la piedra. Es un comienzo excelente.' WHERE `ID`=43844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 발 앞에 그걸 내려놓아라.', `MaleText_loc4`='将这块石头放在我面前的地上。', `MaleText_loc5`='把石頭擺在我面前的地上。', `MaleText_loc7`='Coloca la piedra en el suelo de delante de mí.' WHERE `ID`=43845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 바위 군주도 이미 내 이야길 들었다.', `MaleText_loc4`='我已经给其他石领主送去了消息。', `MaleText_loc5`='其他的岩石領主已經聽到我所說的了。', `MaleText_loc7`='Los otros Señores de Piedra ya me escucharon.' WHERE `ID`=43846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 호의를 증명하는 인장을 너에게 주겠다. 내 믿음이 헛되지 않길 바란다.', `MaleText_loc4`='拿上这枚徽记，它代表了我对你的祝福。现在我只能祈祷自己没有错信你。', `MaleText_loc5`='帶著這個代表了我的祝福的徽記。我希望我所付出的信任是正確的。', `MaleText_loc7`='Ten este sello como testimonio de mi buena voluntad. Espero haber depositado bien mi confianza.' WHERE `ID`=43847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 것에 시간을 낭비하고 있었더냐, 디아만트?', `FemaleText_loc4`='岱亚曼塔，这就是让你浪费时间的东西？', `FemaleText_loc5`='這就是讓你浪費時間在他身上的人嗎，戴門?', `FemaleText_loc7`='¿Este es el que te quita todo tu tiempo, Diamant?' WHERE `ID`=43848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 네가 저들의 행동을 책임져라, 바위 군주여. 저들의 저의가 드러나는 날이 오면, 난 너에게 책임을 물을 것이다.', `FemaleText_loc4`='那么你将对它的行为担负起责任来，石领主。当它的真实意图显露之后，你将必须给我一个解释。', `FemaleText_loc5`='那你就必須為他的行為負責，石領主。當他真正的目的浮現時，你便會是我要找的人。', `FemaleText_loc7`='Entonces te harás cargo de sus acciones, Señor de Piedra. Tú serás el que responda ante mí cuando se muestre como es.' WHERE `ID`=43849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 육체의 소유자여, 여기서 넌 완전히 바위에 둘러싸여 있다는 사실을 한 번쯤 되새겨 봐라. 네가 걷는 이 대지 자체도 내 명을 따른다.', `FemaleText_loc4`='至于你，血肉之躯。考虑一下你现在的处境吧。你的身躯被重重岩石所包围，你脚下的大地屈从于我的意志。', `FemaleText_loc5`='而你，凡人，想想你現在身處於四面八方都是岩石的地方。連你行走於腳下的大地都可在我的意志下彎曲。', `FemaleText_loc7`='Y tú, carne, considera por un momento que estás completamente rodeado de roca. Hasta el suelo que pisas obedece a mi voluntad.' WHERE `ID`=43850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 배신하면 도망갈 곳은 어디에도 없다. 내가 네 몸을 으스러뜨릴 것이다. 뼈마디가 하나하나 부서지는 소리가 들릴 만큼 천천히.', `FemaleText_loc4`='如果你背叛了我们，你就将无路可逃。我会缓慢地摧毁你的身体，倾听你每一片骨头碎裂的声音。', `FemaleText_loc5`='如果你背叛我們，你將無處可逃。我會慢慢的碾碎你的身體，慢到可以聽到每根骨頭的斷裂聲。', `FemaleText_loc7`='Si nos traicionas, no tendrás escapatoria. Aplastaré tu cuerpo tan lentamente que oirás como se quiebra cada uno de tus huesos.' WHERE `ID`=43851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즐거운 대화였다.', `FemaleText_loc4`='这次谈话很愉快。', `FemaleText_loc5`='我很高興有這次的談話。', `FemaleText_loc7`='Qué bueno que hablamos.' WHERE `ID`=43852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체의 소유자여, 자신을 증명하고 싶은가? 무너지는 심연은 북동쪽에 있다. 네가 찾는 돌은 그 안에 있지.', `MaleText_loc4`='你要来证明你自己吗？碎岩之渊在东北方。你要找的石头就在那里。', `MaleText_loc5`='你是來證明自己的嗎，凡人?破碎深淵就在這的東北邊。你要找的石頭就在那。', `MaleText_loc7`='¿Has venido a probar tu valía, carne? Las Profundidades Desmoronadas están al noreste,  y allí la piedra que buscas.' WHERE `ID`=43853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 수정을 내리쳐라. 함께 여왕 바위용을 상대해야 한다.', `MaleText_loc4`='准备好了就敲打水晶，我们将共同面对龙母。', `MaleText_loc5`='準備好就敲擊那個水晶，讓我們一同面對育母。', `MaleText_loc7`='Ataca los cristales cuando estés listo y enfrentaremos juntos a la Madre de Linaje.' WHERE `ID`=43854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 넌 너무 오랫동안 바위 어머니의 감시에서 벗어났다. 이제 제자리로 돌아올 때다.', `MaleText_loc4`='你远离了石母的注视，石龙。是时候让你回到你的位置了。', `MaleText_loc5`='你離石母的凝視太遠了，龍族。是時候讓你回到你該去的地方了。', `MaleText_loc7`='Te has apartado de la mirada de la Madre Pétrea, dragón. Es hora de que te pongamos en tu lugar.' WHERE `ID`=43855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕이 항복했다. 흠... 잘했다, 육체의 소유자여.', `MaleText_loc4`='她屈服了。干得好，血肉之躯。', `MaleText_loc5`='她屈服了。嗯...做得好，凡人。', `MaleText_loc7`='Se rinde. Bien hecho, carne.' WHERE `ID`=43856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어째서 너희는 육체를 가진 저것들을 믿어야 한다고 날 설득하려고 드느냐?', `FemaleText_loc4`='你正在尝试说服我，这些血肉之躯应该得到我的信任。', `FemaleText_loc5`='你站在這，試著說服我可以信任這些凡人。', `FemaleText_loc7`='Tratas de convencerme de que estos seres de carne merecen mi confianza.' WHERE `ID`=43857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 그야말로 타락의 화신이다. 피부를 보면 바로 알 수 있는 것을.', `FemaleText_loc4`='他们就是堕落的化身，确是如此。他们的皮肤就说明了一切。', `FemaleText_loc5`='他們完全是腐壞的化身。就連他們自己的皮囊都在尖叫。', `FemaleText_loc7`='Son la encarnación misma de la corrupción. Su piel la destila.' WHERE `ID`=43858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은 황혼의 망치단처럼 오로지 힘을 탐한다. 그런데도 저들이 우릴 배반하지 않을 거라고? 내가 너희를 바보로 길렀더냐?', `FemaleText_loc4`='他们只会寻求力量，与暮光别无二致。但你却信心十足的认为他们不会背叛我们。我养大了一个蠢货？', `FemaleText_loc5`='他們想要的只有力量，就跟暮光一樣。但你們卻信心滿滿地說他們不會背叛我們。是我把你們一手帶大變成蠢貨的嗎?', `FemaleText_loc7`='Sólo buscan poder, como el Crepúsculo. Pero tú estás seguro de que no nos atacarán. ¿Yo los crié así de tontos?' WHERE `ID`=43859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들이 바위 트로그를 처치했다지? 그걸로 날 설득할 셈이냐? 그다지 대단한 일도 아니거늘.', `FemaleText_loc4`='哼，它们杀掉了石头穴居人，你觉得这能打动我？这不算什么功绩。', `FemaleText_loc5`='他們殺死了岩石穴居怪，哥西克?這應該改變我的想法?這根本微不足道。', `FemaleText_loc7`='¿Mataron a troggs de piedra, Gorik? ¿Eso debería persuadirme? No es un gran logro.' WHERE `ID`=43860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 생각은 어떠냐, 보덴? 이 "용사"라는 것 말이다.', `FemaleText_loc4`='你的看法呢？博登，你怎么看这个“勇士”？', `FemaleText_loc5`='你，波登。你在這個「勇士」身上看到了什麼?', `FemaleText_loc7`='¿Y tú, Boden? ¿Qué le ves a este "campeón"?' WHERE `ID`=43861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다고 해도 바보도 가끔은 써먹을 데가 있는 법이지. 그래서 내가 너희를 곁에 두는 것이고.', `FemaleText_loc4`='也许你说的对。即使是蠢货也能有些用处。我不是照样留下了你。', `FemaleText_loc5`='很可能是這樣沒錯，就連蠢貨也有他的用處。我不也留下了你們。', `FemaleText_loc7`='Eso podrá ser. Hasta los tontos tienen uso. Decidí conservarlos.' WHERE `ID`=43862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 침입자에게 좋은 감정은 없습니다. 하지만 저 육체의 소유자들은 진홍 벌판에서 온갖 더러운 것들을 처리했습니다.', `MaleText_loc4`='我不喜欢入侵者，石母，但这些血肉之躯不辞辛苦地清理掉了赤红岩床上的污秽。', `MaleText_loc5`='我也不喜歡入侵者，石母，但這些人兜了好一大圈清除了赤紅瀚洋的腐臭敗類。', `MaleText_loc7`='No me gustan los intrusos, Madre Pétrea, pero estos carnes se esforzaron mucho por purificar la Superficie Carmesí. ' WHERE `ID`=43863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 황혼의 망치단과 다릅니다. 굳이 저들을 방해할 이유가 없습니다.', `MaleText_loc4`='他们不是暮光之锤的人。我不相信他们会是敌人。', `MaleText_loc5`='他們不屬於暮光。我沒有理由阻止他們前進。', `MaleText_loc7`='No son el Crepúsculo. No veo por qué oponernos a sus metas.' WHERE `ID`=43864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이방인과 말을 섞지 않지만, 그들의 용사가 무너지는 심연 깊숙이 발을 들이고는 상처 하나 없이 돌아오는 걸 똑똑히 봤습니다. 그가 유능한 건 분명합니다.', `MaleText_loc4`='我还没有和那些外来者交谈过，但是我已经见证了他们的勇士深入碎岩之渊，并毫发未损地回来。它的能力毋庸置疑。', `MaleText_loc5`='我沒跟那些陌生人說到話，但我目睹了他們勇敢地踏入破碎深淵後毫髮無傷地回來。這完全是可能的。', `MaleText_loc7`='No he hablado con los extraños, pero fui testigo de cómo el campeón se adentró en las Profundidades Desmoronadas y volvió ileso. Está claro que es capaz.' WHERE `ID`=43865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 그 용사는 두려움도 망설임도 없이 바위용과 그들의 여왕을 상대했습니다. 가장 강인한 거인도 주저하는 일을 그 용사는 용감히 해치웠습니다.', `MaleText_loc4`='这名勇士还直面了石龙和石龙主母，它们曾令最强大的巨人退缩，这个血肉之躯却没有丝毫的恐惧和犹豫。', `MaleText_loc5`='這個勇士同時面對了石龍和它們的育母卻沒有一絲的恐懼和質疑。我曾看過最強壯的巨人畏縮，但這凡人卻沒有。', `MaleText_loc7`='Este campeón también se enfrentó a los Dragones de Piedra y su Madre de Linaje sin un dejo de duda o miedo. He visto a los gigantes más fuertes vacilar donde este carne no.' WHERE `ID`=43866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생각은 이미 아시겠지요, 바위 어머니시여.', `MaleText_loc4`='您知道我的立场，石母。', `MaleText_loc5`='你知道我的立場，石母。', `MaleText_loc7`='Sabes mi posición, Madre Pétrea.' WHERE `ID`=43867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 존재라고 생각하지 않습니다. 여기가 자기 고향인 양 겁 없이 돌아다니는 바보 같은 존재일 뿐입니다. 곧 목숨을 잃게 될 것입니다.', `MaleText_loc4`='驱使它的并非勇气。它仿佛将这里当作了自己的家园，冲锋在我的身前。它只是个傻瓜，迟早会送命。', `MaleText_loc5`='讓它前進的不是勇氣。它從我面前走過，就像這裡是他家一樣。它是個笨蛋。很快，它就會害死自己。', `MaleText_loc7`='No lo mueve la valentía. Anduvo ante mí como si este lugar fuera su hogar. Qué tonto. Pronto hará que lo maten.' WHERE `ID`=43868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희가 얘기한 용사가 왔구나.', `FemaleText_loc4`='勇士归来了。', `FemaleText_loc5`='咱們的勇士終於來啦。', `FemaleText_loc7`='Llegó el "campeón".' WHERE `ID`=43869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 작구나. 정말 연약해. 육체의 소유자여, 네가 아직 살아 있다는 게 신기하구나.', `FemaleText_loc4`='这么小。这么软。真好奇你是如何坚持到现在的，血肉之躯。', `FemaleText_loc5`='真小，真脆弱。我很好奇你怎樣在這裡活到現在的，凡人。', `FemaleText_loc7`='Tan pequeño. Tan blando. Que hayas durado tanto aquí abajo es asombroso, carne.' WHERE `ID`=43870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만큼 능력이 뛰어나다는 뜻인가?', `FemaleText_loc4`='或者说，这正显示出了你的能力？', `FemaleText_loc5`='又或許這是你實力的證明?', `FemaleText_loc7`='¿O será un testimonio de tus habilidades?' WHERE `ID`=43871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 모든 것이 세계 기둥 파편을 얻기 위함이라고? 네놈들은 대체 그걸로 뭘 하려는 것이냐?', `FemaleText_loc4`='你做的这些就只是为了世界之柱的碎片？你们这些萨满究竟想拿它做什么？', `FemaleText_loc5`='一切就為了一塊世界之柱的碎片?你們這些薩滿到底想用它做什麼?', `FemaleText_loc7`='¿Todo esto por una pieza del Pilar Mundial? ¿Qué piensas hacer con ella, chamán?' WHERE `ID`=43872;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='메우고 나면 어쩔 테냐? 심원의 영지를 떠날 것이냐?', `FemaleText_loc4`='然后呢？你们就会安静地离开深岩之洲？', `FemaleText_loc5`='然後呢?你會把地深之源交給它的居民嗎?', `FemaleText_loc7`='¿Y entonces qué? ¿Les dejarás Infralar a sus ciudadanos?' WHERE `ID`=43873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만큼은 개념이 있다니 다행이구나.', `FemaleText_loc4`='你至少有些洞察力。', `FemaleText_loc5`='我很高興至少你的理解力還可以。', `FemaleText_loc7`='Qué bueno que seas así de perceptivo.' WHERE `ID`=43874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 이렇게 하라. 우리는 황혼의 이교도를 공격하여 이 세계에서 데스윙의 이름을 들먹이는 놈들을 싹 쓸어버릴 것이다. 대지 고리회도 공격에 참여하라.', `FemaleText_loc4`='我的提议是：我们会向暮光教派进军，将死亡之翼的名讳从这个世界中彻底抹消掉。你们大地之环，将随我而战。', `FemaleText_loc5`='這是我的建議:我們向暮光邪教進軍，消滅任何掛著死亡之翼之名，氾濫於這個國度的教徒。你的陶土議會將與我們一起前進。', `FemaleText_loc7`='Te propongo algo: marchemos al Culto Crepuscular y extingamos la mera mención del nombre de Alamuerte. Tu Anillo de la Tierra nos acompañará.' WHERE `ID`=43875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희가 그리한다면, 고르직을 시켜서 세계 기둥 파편을 사원으로 보내주겠다.', `FemaleText_loc4`='如果你能做到，我就会派格尔西克将世界之柱的碎片送到神殿去。', `FemaleText_loc5`='如果你照做，我就會讓哥西克帶著我們的世界之柱碎片到神殿去。', `FemaleText_loc7`='Hazlo y enviaré a Gorsik al templo con nuestra pieza del Pilar Mundial.' WHERE `ID`=43876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='균열을 봉인하고, 이곳을 떠나라.', `FemaleText_loc4`='封印那道裂隙，然后离开。', `FemaleText_loc5`='修復好裂縫後離開這裡。', `FemaleText_loc7`='Sellaremos la fisura y nos iremos.' WHERE `ID`=43877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='인사는 나중에 해라. 우리는 병력을 모으는 대로 황혼의 낭떠러지로 진군할 것이다. 전장에서 보도록 하지.', `FemaleText_loc4`='留着你的感谢。当我们的部队集结完毕之后就向暮光绝壁进军。我期待在战场上见到你。', `FemaleText_loc5`='不用那麼早道謝。我們的軍隊一旦集結完畢就會向暮光絕壁進軍。期待你在戰場上的表現。', `FemaleText_loc7`='No agradezcas. Marcharemos sobre el Precipicio Crepuscular cuando estemos listos. Espero verte en el campo de batalla.' WHERE `ID`=43878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 데스윙이 아제로스에 만든 균열을 닫으려고 왔습니다. 이쪽 세계의 구멍을 메우려면 세계 기둥을 복원해야 합니다.', `MaleText_loc4`='我们前来封住死亡之翼留下的裂隙。我们需要世界之柱来修复这一侧的裂口。', `MaleText_loc5`='我們到這是來封印死亡之翼帶給艾澤拉斯的大裂縫。我們需要世界之柱來修復洞的這一邊。', `MaleText_loc7`='Vinimos a sellar la brecha que Alamuerte dejó en Azeroth. Necesitamos el Pilar Mundial para repararla de este lado.' WHERE `ID`=43879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 환영받지 않는 곳에 머물 생각은 없습니다.', `MaleText_loc4`='我们会离开。我们无意继续留在不受欢迎之地。', `MaleText_loc5`='我們會離開。我們沒有意願留在不受歡迎的地方。', `MaleText_loc7`='Nos iremos. No queremos estar donde no nos quieren.' WHERE `ID`=43880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀하신 대로 따르겠습니다. 바위 어머니시여, 감사합니다.', `MaleText_loc4`='我们会照做的。感谢您，石母。', `MaleText_loc5`='我們會照辦的。我們都很感謝你，石母。', `MaleText_loc7`='Pues haremos exactamente eso. Gracias,  Madre Pétrea.' WHERE `ID`=43881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지가 널 처단하러 왔다, 이교도여!', `FemaleText_loc4`='大地来夺你性命了，邪教！', `FemaleText_loc5`='大地來回收你們了，邪教徒!', `FemaleText_loc7`='¡La tierra viene por ustedes, culto!' WHERE `ID`=43882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절대로 네놈들을 봐주지 않겠다. 너흴 보살피던 데스윙은 이제 여기 없다!', `FemaleText_loc4`='你的入侵将不会被原谅。死亡之翼不会再在这里庇护你了。', `FemaleText_loc5`='你們的入侵是不可原諒的。你們的褓姆死亡之翼已經不在這裡了。', `FemaleText_loc7`='Su ofensa no será perdonada. Alamuerte ya no está aquí para consentirlos.' WHERE `ID`=43886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='땅이 널 삼키러 오는 것을 보며 벌벌 떨어라!', `FemaleText_loc4`='在即将吞噬你的大地之前畏缩吧！', `FemaleText_loc5`='顫抖吧!隆起的大地將吞噬你們!', `FemaleText_loc7`='¡La tierra misma se levanta para tragarlos!' WHERE `ID`=43887;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했다. 사원으로 돌아가라. 약속대로 고르직이 그리로 갈 것이다.', `FemaleText_loc4`='干得好，$r。返回神殿吧，格尔西克会在那儿等着你。', `FemaleText_loc5`='做得好。回到神殿，哥西克將會在那，如同當初所說的。', `FemaleText_loc7`='Bien hecho. Vuelvan al templo, Gorsik los verá allí, como se prometió.' WHERE `ID`=43888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지에 온 걸 환영한다.', `MaleText_loc4`='欢迎来到深岩之洲，邪教徒。', `MaleText_loc5`='歡迎來到地深之源，教徒。', `MaleText_loc7`='Bienvenido a Infralar, cultista.' WHERE `ID`=43889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떠냐, 이교도여? 날 줄은 아느냐?', `MaleText_loc4`='你呢，邪教徒？你会飞吗？', `MaleText_loc5`='那你呢，教徒?你知道怎麼飛嗎?', `MaleText_loc7`='¿Qué hay de ti, cultista? ¿Sabes volar?' WHERE `ID`=43891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 방해되지? 솔직히 말해봐. 방해하려고 하는 짓이니까.', `MaleText_loc4`='你觉得我很强大？听着，精彩的还在后面。', `MaleText_loc5`='你認為我很強勢嗎?老實說。我就是要強勢。', `MaleText_loc7`='¿Te parezco imponente? Sé sincero. Yo creo que sí.' WHERE `ID`=43892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 이 모자란 놈들아.', `MaleText_loc4`='逃不掉的，小子们。', `MaleText_loc5`='盡量的跑吧，兔崽子們。', `MaleText_loc7`='Corran, crías.' WHERE `ID`=43893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋대로 우리 암벽 위에 자리를 잡다니. 그 무지한 행동 때문에 너희는 파멸할 것이다.', `MaleText_loc4`='你们把居所建造在我们的岩石上面。你们的无知只会导致你们的毁灭。', `MaleText_loc5`='你們在我們的石臉上蓋房子。你們的無知將是你們死亡的原因。', `MaleText_loc7`='Construyeron su morada en nuestras narices de roca. Morirán por su ignorancia.' WHERE `ID`=43894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 곧 내 발에 달라붙은 쓰레기 신세가 될 것이다.', `MaleText_loc4`='很快，你们这些家伙就会变成我脚底下的一块污渍。', `MaleText_loc5`='很快，你們便會成為我腳底的一灘污血。', `MaleText_loc7`='Pronto no serás más que una mancha en mi pie.' WHERE `ID`=43895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈 좀 보게... 두 발로 당당히 대지를 딛고 서서는 감히 내게 도전하려 하는군.', `MaleText_loc4`='看看这个东西……勇敢的站在大地之上，以为能够挑战我。', `MaleText_loc5`='看看這隻...勇敢的站在他腳下的土地上，認為有能力挑戰我。', `MaleText_loc7`='Mira a éste... parado todo valiente, la tierra bajo sus pies, pensando en desafiarme.' WHERE `ID`=43896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배짱 하나는 인정할 만 하구나.', `MaleText_loc4`='你的恶臭真刺鼻，人类。', `MaleText_loc5`='你真是有勇無謀啊，人類。', `MaleText_loc7`='Aún te queda fuerza, humano.' WHERE `ID`=43897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항해 봤자, 이미 넌 죽은 목숨이다.', `MaleText_loc4`='你会成为一具顽强的尸体。', `MaleText_loc5`='你會是具很堅固的屍體。', `MaleText_loc7`='Eres un cadáver muy tenaz.' WHERE `ID`=43898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작고 연약한데도 꽤 용감하군.', `MaleText_loc4`='又小又脆弱，却又如此勇敢。', `MaleText_loc5`='又小又脆弱，卻有如此勇氣。', `MaleText_loc7`='Tanta valentía siendo tan pequeño y frágil.' WHERE `ID`=43899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체의 소유자여, 바위용이 왔다! 올라타라!', `MaleText_loc4`='石龙就在这儿，凡人。赶快！', `MaleText_loc5`='石龍們來了，凡人，快抓住它們!', `MaleText_loc7`='Los Dragones de Piedra están aquí, carne. ¡Vuela!' WHERE `ID`=43900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 어머니 따위는 데스윙 님에게 장난감이지.', `MaleText_loc4`='死亡之翼自会对付你的石母。', `MaleText_loc5`='死亡之翼將會處理好你們的「石母」。', `MaleText_loc7`='Alamuerte hará pedazos a tu Madre Pétrea.' WHERE `ID`=43901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 깊고 어두운 구멍 속에서도 황혼이 너를 덮칠 것이다.', `MaleText_loc4`='暮光将笼罩你，即使在这漆黑深邃的洞穴中。', `MaleText_loc5`='就算在這黑暗深洞中，暮光也將吞沒你。', `MaleText_loc7`='El crepúsculo caerá sobre ustedes, aún en este agujero oscuro.' WHERE `ID`=43902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아...', `MaleText_loc4`='啊……', `MaleText_loc5`='呃啊...', `MaleText_loc7`='Agh...' WHERE `ID`=43903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간이 배 밖으로 나왔군.', `MaleText_loc4`='这是不自量力，伙计。', `MaleText_loc5`='你這傢伙有點想太多了。', `MaleText_loc7`='Es demasiado para ti, hombre.' WHERE `ID`=43904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에서는 제법인데. 하하! 과연 하늘에서는 어떨까?', `MaleText_loc4`='你在地面行动自如，到了空中又如何呢？', `MaleText_loc5`='你在地面上沒問題，但在空中咧?', `MaleText_loc7`='Andas bien por la tierra. Pero ¿qué hay de los cielos?' WHERE `ID`=43905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거보단 빨라야 할 텐데!', `MaleText_loc4`='你还得再快点才行！', `MaleText_loc5`='你要更靈活一點才可以!', `MaleText_loc7`='¡Tendrás que ser más rápido!' WHERE `ID`=43906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈에게서 떨어지지 마라, 야수야! 공중에서 해치워 버려!', `MaleText_loc4`='继续攻击，野兽们！把他们在空中撕碎！', `MaleText_loc5`='攻擊他們，野獸們!將他們從空中撕裂!', `MaleText_loc7`='¡Sigan sobre ellos, bestias! ¡Bájenlos!' WHERE `ID`=43907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 충분히 논 것 같다.', `MaleText_loc4`='我可是受够你了，伙计。', `MaleText_loc5`='我已經受夠你了，老兄。', `MaleText_loc7`='Estoy cansado de ti, hombre.' WHERE `ID`=43908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 안 돼...', `MaleText_loc4`='不！不……', `MaleText_loc5`='不!不...', `MaleText_loc7`='¡No! Nooooo...' WHERE `ID`=43909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테라제인이 드디어 우리에게 맞설 생각인가 보군.', `FemaleText_loc4`='塞拉赞恩终于攒足了勇气来挑战我们，是吧？', `FemaleText_loc5`='瑟拉贊恩終於膽敢挑戰我們了，對嗎?', `FemaleText_loc7`='¿Así que Therazane juntó el coraje para enfrentarnos, eh?' WHERE `ID`=43910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이 와, 귀여운 것. 제대로 해보자고.', `FemaleText_loc4`='靠近点，亲爱的。我有些小小的看法。', `FemaleText_loc5`='靠近一點，親愛的。我想說一件事。', `FemaleText_loc7`='Acércate, querida. Tengo algo que probar.' WHERE `ID`=43911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오... 희망이 없다는 거, 알고 있겠지? 데스윙 님은 이미 깨어났어. 네 세상은 끝장이라고.', `FemaleText_loc4`='你意识到一切都毫无希望了，对吧？死亡之翼已经崛起了，你的世界注定毁灭。', `FemaleText_loc5`='你瞭解希望是不存在的，對吧?死亡之翼回來了。你的世界完了。', `FemaleText_loc7`='Te das cuenta que no hay esperanza, ¿no? Alamuerte se ha levantado. Tu mundo está condenado.' WHERE `ID`=43912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아하하하! 오, 더 가까이 와야지. 난 쫓아다닐 가치가 있다고.', `FemaleText_loc4`='跟紧点，亲爱的。我值得你的追逐。', `FemaleText_loc5`='跟緊我，寶貝。追我是不會後悔的。', `FemaleText_loc7`='No te alejes, hermoso. Sígueme y lo valdrá.' WHERE `ID`=43913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기, 난 그렇게 쉬운 여자가 아니야. 다음을 기약하자고.', `FemaleText_loc4`='没那么容易，甜心。也许下一次。', `FemaleText_loc5`='我沒那麼隨便，甜心。下次吧。', `FemaleText_loc7`='No soy tan fácil, dulce. En otra ocasión, quizás.' WHERE `ID`=43914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[서투른 공용어] 여기서 죽어라.', `MaleText_loc4`='[Broken Common]在此受死吧。', `MaleText_loc5`='[拙劣的通用語]來這裡送死。', `MaleText_loc7`='[En lengua común con dificultad] Aquí muerte para ustedes.' WHERE `ID`=43915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 부족 전쟁 기계가 네 시체로 배를 채울 것이다.', `MaleText_loc4`='你们的尸体正好可以拿来当黑石战争机器的好燃料。', `MaleText_loc5`='你的屍體會變成黑石軍隊的養分。', `MaleText_loc7`='Sus cuerpos alimentarán la máquina de guerra de los Roca Negra.' WHERE `ID`=43916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 용서하십시오... 제가 주인님의 명을 따르지 못했습니다.', `MaleText_loc4`='请原谅我，主人……我让你失望了。', `MaleText_loc5`='原諒我，主人...我讓你失望了。', `MaleText_loc7`='Perdóname maestro... Te he fallado.' WHERE `ID`=43917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크쯤이야 누워서 떡 먹기지.', `MaleText_loc4`='杀戮就像呼吸一样自然。', `MaleText_loc5`='殺人跟呼吸一樣簡單。', `MaleText_loc7`='Matar me resulta tan natural como respirar.' WHERE `ID`=43918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불곰 중대의 이름으로 행운을 비네.', `MaleText_loc4`='B连为你带来最美好的祝愿。', `MaleText_loc5`='第二連隊祝你一切順利。', `MaleText_loc7`='Saludos de la Compañía Bravo.' WHERE `ID`=43919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 당하고 다시 일어나진 못할 거야.', `MaleText_loc4`='他别想再站起来了。', `MaleText_loc5`='這下子他可起不來了。', `MaleText_loc7`='De esta sí que no se va a recuperar.' WHERE `ID`=43920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아!', `MaleText_loc4`='啊——！', `MaleText_loc5`='啊啊啊啊啊啊啊啊!', `MaleText_loc7`='¡AHHHHHHHHHH!' WHERE `ID`=43921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아아!', `MaleText_loc4`='啊啊啊——！', `MaleText_loc5`='啊啊啊啊啊啊啊啊啊啊啊啊啊!', `MaleText_loc7`='¡AAAAAAHHHHHHHHHHHHHHH!' WHERE `ID`=43922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 기둥의 마지막 조각을 손에 넣었다! 이제 조각을 합치기만 하면 이 세계가 아제로스와 함께 붕괴하는 것을 막을 수 있다!', `MaleText_loc4`='世界之柱的最后一块碎片被复原了！我们必须将它们重组到一起以阻止这个世界向艾泽拉斯崩塌。', `MaleText_loc5`='世界之柱的最後一塊碎片終於取回了!我們現在只要把它拼湊回去，就能夠阻止這個界域崩塌到艾澤拉斯。', `MaleText_loc7`='¡El último pedazo del Pilar del Mundo ha sido descubierto! Solo tenemos que unirlos para evitar que este reino se hunda en Azeroth.' WHERE `ID`=43923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모여라, 형제자매여! 임무를 완수하고 자랑스럽게 스랄 님에게 돌아가자!', `MaleText_loc4`='整队，兄弟姐妹们！让我们履行自己的职责，载誉回到萨尔的面前！', `MaleText_loc5`='集合，兄弟姊妹們!讓我們完成任務，凱旋返回索爾身邊!', `MaleText_loc7`='¡Recolectar, hermanos y hermanas! ¡Cumplamos con nuestro deber y regresemos con Thrall victoriosos!' WHERE `ID`=43924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 어떤 적이라도 능히 물리칠 수 있음을 잘 보여주었네. 젊은 영웅이여, 자네가 의식을 보호해 주면 영광이겠네.', `MaleText_loc4`='你已经证明了你有能力击败任何敌人。有你作为仪式的守卫让我倍感荣幸，年轻的英雄。', `MaleText_loc5`='你已經證明了具有擊敗任何敵人的本事。年輕的英雄，如果你願意在儀式期間協助戒備，我將非常榮幸。', `MaleText_loc7`='Has demostrado que eres capaz de derrotar a cualquier enemigo. Sería un honor que montaras guardia durante el ritual, joven valiente.' WHERE `ID`=43925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 암살자들이 우리를 공격한다! 놈들이 의식을 방해하게 두지 마라!', `MaleText_loc4`='暮光的刺客就要过来了！不能让他们打断这个仪式！', `MaleText_loc5`='暮光刺客來襲!別讓他們中斷了儀式!', `MaleText_loc7`='¡Los asesinos Crepusculares nos atacan! ¡Que no interrumpan el ritual!' WHERE `ID`=43926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 로바리우스...', `MaleText_loc4`='不——！洛瓦留斯……', `MaleText_loc5`='不!洛瓦歷斯...', `MaleText_loc7`='¡Nooo! Lorvarius...' WHERE `ID`=43927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이... 밀려나고 있다. 힘을 내라, 형제들이여! 적들이 다시 돌아오기 전에 의식을 끝내야 한다!', `MaleText_loc4`='他们在……下沉。继续努力，兄弟们！我们必须在他们返回之前完成仪式！', `MaleText_loc5`='他們的攻勢...緩下來了。打起精神來，弟兄們!我們務必在他們返回之前完成儀式!', `MaleText_loc7`='Están... flaqueando. ¡Reanuden sus esfuerzos, hermanos! ¡Debemos completar el ritual antes de que regresen!' WHERE `ID`=43928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실패하고... 말았구나...', `MaleText_loc4`='我……失败了……', `MaleText_loc5`='我...失敗了...', `MaleText_loc7`='He... fallado.' WHERE `ID`=43929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 암살자들을 처리해 주게!', `MaleText_loc4`='别让刺客靠近我！', `MaleText_loc5`='別讓刺客接近我!', `MaleText_loc7`='¡Quitadme a estos asesinos de encima!' WHERE `ID`=43930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 돌아왔네! 전투 준비!', `MaleText_loc4`='他们回来了！准备战斗！', `MaleText_loc5`='他們回來了!備戰!', `MaleText_loc7`='¡Han regresa''o! ¡A las armas!' WHERE `ID`=43931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀를 막게! 아직 의식을 끝낼 희망이 있어!', `MaleText_loc4`='阻止她！我们还能继续完成仪式！', `MaleText_loc5`='阻止她!我們還是可以完成結合!', `MaleText_loc7`='¡Párenla! ¡Aún podemos completar la fijación!' WHERE `ID`=43932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 감사합니다...', `MaleText_loc4`='感谢元素…', `MaleText_loc5`='感謝元素...', `MaleText_loc7`='Agradezcan a los elementos…' WHERE `ID`=43933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐네! 의식을 끝냈어.', `MaleText_loc4`='完成了！仪式结束了！', `MaleText_loc5`='完成了!工程結束了。', `MaleText_loc7`='¡Hecho está! Estamos acabados.' WHERE `ID`=43934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 기둥을 복구했으니, 이 세계는 안전하네. 이젠 이 세계 바깥쪽의 상처를 돌봐야겠지.', `MaleText_loc4`='世界之柱复原了，这个世界安全了。该去治疗地表上的伤痕了。', `MaleText_loc5`='修復了柱子後，這個國度也就安全了。我們必須處理地表上的傷口。', `MaleText_loc7`='Con el pilar restaurado, el reino está a salvo.  Ahora debemos sanar la superficie.' WHERE `ID`=43935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심한 부상을 입었습니다... 버틸 수가 없습니다...', `MaleText_loc4`='我伤得很重……我坚持不住了……', `MaleText_loc5`='我的傷勢太重...我沒辦法...', `MaleText_loc7`='Estoy gravemente herido... No aguanto más...' WHERE `ID`=43937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 이야기도 여기서 끝이다.', `FemaleText_loc4`='你的传说将在此终结，萨满。', `FemaleText_loc5`='你的故事在此結束，薩滿。', `FemaleText_loc7`='Aquí termina tu historia, chamán.' WHERE `ID`=43938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙 님이 너희에게 파멸을 내리실 것이다. 그리고 오늘, 난 그분의 칼이 되리라!', `FemaleText_loc4`='死亡之翼会给尘世的所有秩序带来毁灭。到那一天，我将成为他的利刃！', `FemaleText_loc5`='死亡之翼將會為你的秩序帶來全面的毀滅。而今天，我將成為他的劍刃!', `FemaleText_loc7`='Alamuerte traerá destrucción a toda tu orden. ¡Y hoy YO seré su espada!' WHERE `ID`=43939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 하하하하하...', `FemaleText_loc4`='哈哈……', `FemaleText_loc5`='哈...', `FemaleText_loc7`='Ja...' WHERE `ID`=43940;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낭떠러지에서 쓴맛을 보고도 아직 정신을 차리지 못했구나, 이교도여.', `FemaleText_loc4`='我们毁掉你们的要塞时，你们就该接受警告的，异教徒。', `FemaleText_loc5`='在我們摧毀你們的絕壁時，你們就該瞭解到了，邪教徒。', `FemaleText_loc7`='Debiste darte cuenta cuando destruimos tu precipicio, cultista.' WHERE `ID`=43941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마하트, 떨거지들을 처리해라. 멍청한 여사제는 내가 상대하지.', `FemaleText_loc4`='玛哈特，杀掉这些教徒。我会去对付那愚蠢的女祭司。', `FemaleText_loc5`='瑪哈特，殺死這些烏合之眾。我會對付這愚蠢的女祭司。', `FemaleText_loc7`='Ma''haat, masacra a esta gentuza. Yo me encargo de la sacerdotisa.' WHERE `ID`=43942;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌아오다니, 죽고 싶은 게로구나.', `FemaleText_loc4`='你敢回来就必死无疑。', `FemaleText_loc5`='回來便註定了你的死亡。', `FemaleText_loc7`='Haber vuelto será fatal para ti.' WHERE `ID`=43943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식이 거의 끝났다!', `FemaleText_loc4`='仪式几乎就要完成了！', `FemaleText_loc5`='儀式馬上就要完成了!', `FemaleText_loc7`='¡El ritual eh''tá casi completado!' WHERE `ID`=43944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 바위 어머니시여. 함께해서 참으로...', `FemaleText_loc4`='感谢你，石母。这是我的荣幸……', `FemaleText_loc5`='感謝你，石母。我們很榮幸有...', `FemaleText_loc7`='Gracias, Madre Pétrea. Ha sido un honor haber…' WHERE `ID`=43945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 약속을 지켰다, 대지치유사여. 그러니 너희에게 노여워하진 않겠다.', `FemaleText_loc4`='你证明了你所言不虚，大地治愈者。为此，你将免遭大地之怒。', `FemaleText_loc5`='你證明了你所說的，癒地者。為此，我們的怒火將不會降臨在你身上。', `FemaleText_loc7`='Has cumplido con tu palabra, Ensalmador. Por ello no sufrirás nuestra ira.' WHERE `ID`=43946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부상자들이 좀 나으면, 여길 떠남으로써 감사를 표하라.', `FemaleText_loc4`='你的伤势愈合了，就离开吧，也算是感谢我。', `FemaleText_loc5`='等你的傷兵集合好，你可以用離開來表達對我的謝意。', `FemaleText_loc7`='Cuando tus heridos puedan caminar, agradéceme yéndote.' WHERE `ID`=43947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 어서 뒤에 있는 궁극의 축구탄 제복을 입고 부두로 내려가 주세요. 스랄 님을 도와 무역왕에게 본때를 보여주시라고요!', `FemaleText_loc4`='$n，穿上你身后那套终极足球炸弹制服，到下方的码头那里去。帮助萨尔对付贸易大王！', `FemaleText_loc5`='$n，跳進你背後的終極足球炸彈戰鬥裝，然後趕快去碼頭幫索爾踹貿易親王!', `FemaleText_loc7`='$n, métete en el uniforme de bombalón supremo que tienes detrás de ti y baja al muelle. ¡Ayuda a Thrall a barrer el suelo con el Príncipe mercante!' WHERE `ID`=43948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높은 분이 직접 선물을 전해주면 항상 기분이 좋다고. 지금 당장 풀어봐야지!', `MaleText_loc4`='副总亲自送礼物来，真是让我感到荣幸。我马上就要打开它！', `MaleText_loc5`='收到副手送的禮物真叫人開心，我立刻就打開!', `MaleText_loc7`='Siempre es agradable recibir un regalo entregado en mano por el segundo al mando. ¡Lo abriré ahora mismo!' WHERE `ID`=43949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야!', `MaleText_loc4`='哎呦！', `MaleText_loc5`='噢!', `MaleText_loc7`='¡AYYY!' WHERE `ID`=43950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 대포는 주홍빛 장막호에 화력을 집중하라!', `MaleText_loc4`='所有火炮！对准红雾号开火！', `MaleText_loc5`='所有火砲!對赤紅之霧開火!', `MaleText_loc7`='¡Todos los cañones! ¡Abran fuego sobre El Velo Carmesí!' WHERE `ID`=43951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고야, 알았어! 무슨 말인지 알았다고!', `MaleText_loc4`='好的，好的！我明白她的意思了！', `MaleText_loc5`='好了，好了!我懂你意思了!', `MaleText_loc7`='¡Está bien, está bien! ¡Recibí el mensaje!' WHERE `ID`=43952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배신자! 네게 배를 넘겨야 할 바에야 차라리 죽음을 택하겠다!', `MaleText_loc4`='叛徒！除非我死，否则别想让我向你投降！', `MaleText_loc5`='叛徒!我就算死了也不會把船交給你!', `MaleText_loc7`='¡Traidor! ¡Moriría antes de entregarte mi barco!' WHERE `ID`=43953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 아주 볼만한 광경이 될 거예요!', `FemaleText_loc4`='哈哈！这下可热闹了！', `FemaleText_loc5`='哈哈!真是太痛快了!', `FemaleText_loc7`='¡Ja, ja! ¡Esto va a ser la bomba!' WHERE `ID`=43954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오! 놈들이 옵니다!', `MaleText_loc4`='小心！他们来了！', `MaleText_loc5`='小心!他們來了!', `MaleText_loc7`='¡Cuidado! ¡Ahí vienen!' WHERE `ID`=43955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 당신의 도움이 필요합니다!', `MaleText_loc4`='$n，我需要你的帮助！', `MaleText_loc5`='$n，我需要你的幫忙!', `MaleText_loc7`='¡$n, voy a necesitar tu ayuda!' WHERE `ID`=43956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 바위 트로그! 저쪽입니다!', `MaleText_loc4`='该死的石头穴居人！在那儿！', `MaleText_loc5`='該死，岩石穴居怪!在那邊!', `MaleText_loc7`='¡Maldición, troggs de piedra! ¡Por aquí!' WHERE `ID`=43957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그들이 옵니다!', `MaleText_loc4`='石头穴居人来了！', `MaleText_loc5`='岩石穴居怪來了!', `MaleText_loc7`='¡Se acercan troggs de piedra!' WHERE `ID`=43958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맘껏 발사하십시오!', `MaleText_loc4`='随意开火！', `MaleText_loc5`='自由開火!', `MaleText_loc7`='¡Fuego a discreción!' WHERE `ID`=43959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 다음으로 이 투석기 맛을 보겠느냐?!', `MaleText_loc4`='现在轮到谁挨打了？！', `MaleText_loc5`='現在是誰會被痛扁一頓啊?!', `MaleText_loc7`='¡¿Ahora quién va a recibir una paliza?!' WHERE `ID`=43960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이 우리 국왕 폐하를 빼앗았으니, 난 너희들의 생명을 빼앗겠다!', `MaleText_loc4`='带走了我的国王。我要带走你悲惨的生命！', `MaleText_loc5`='你抓走了我的國王，我就要奪走你可悲的性命!', `MaleText_loc7`='¡Te llevaste a mi rey, yo me llevaré tu mísera vida!' WHERE `ID`=43961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 몰려옵니다! 무슨 수를 써서라도 투석기를 지키십시오!', `MaleText_loc4`='他们来了！不惜一切代价保护投石车！', `MaleText_loc5`='他們來了!不計代價保護好投石車!', `MaleText_loc7`='¡Ahí vienen! ¡Proteged las catapultas a toda costa!' WHERE `ID`=43962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 반지... 우리 가문의 반지를 지닌 사람이 누구지... 틸로아, 당신이오?', `MaleText_loc4`='我的戒指……谁拿走了我的家族戒指……蒂罗亚，是你吗？', `MaleText_loc5`='我的戒指...誰拿走我的家傳戒指... 蒂羅亞，是你嗎?', `MaleText_loc7`='Mi anillo... ¿Quién tiene el anillo de mi familia... Tilloa, eres tú?' WHERE `ID`=43963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토비아스...', `MaleText_loc4`='图比亚斯……', `MaleText_loc5`='托比亞斯...', `MaleText_loc7`='Tobias...' WHERE `ID`=43964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 사실이다, 내 동생아. 한 마디 한 마디가 모두 사실이야. 믿지 못했느냐?', `MaleText_loc4`='全是真的，兄弟。每个字都是真的。你有所怀疑吗？', `MaleText_loc5`='是真的，兄弟。句句屬實。怎麼，你懷疑嗎?', `MaleText_loc7`='Todo es cierto, hermano. Cada palabra. ¿Lo dudabas?' WHERE `ID`=43965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형님!', `MaleText_loc4`='兄弟！', `MaleText_loc5`='兄弟!', `MaleText_loc7`='¡Hermano!' WHERE `ID`=43966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형님, 사실이 아니라고 말해 주세요. 형님이 살인자일 리가 없다고 말씀해 주세요!', `MaleText_loc4`='告诉我那不是真的，兄弟。告诉我你没杀人！', `MaleText_loc5`='告訴我，這不是真的。告訴我你不是殺人兇手!', `MaleText_loc7`='Dime que no es verdad, hermano. ¡Dime que no has muerto siendo un asesino!' WHERE `ID`=43967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이유는 너도 잘 알고 있을 텐데!', `MaleText_loc4`='你知道原因！', `MaleText_loc5`='你知道為什麼!', `MaleText_loc7`='¡Sabes por qué!' WHERE `ID`=43968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 계속 가볼까요?', `MaleText_loc4`='好吧，我们行动吧。', `MaleText_loc5`='好吧，繼續前進。', `MaleText_loc7`='Bien. Sigamos.' WHERE `ID`=43969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추지 말고 이동해야 합니다!', `MaleText_loc4`='我们必须继续前进！', `MaleText_loc5`='我們得繼續前進!', `MaleText_loc7`='¡Tenemos que seguir!' WHERE `ID`=43970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이동하시죠. 바위 트로그가 달라붙지 않게만 조심해 주십시오.', `MaleText_loc4`='我们出发吧。尽量离那些石头穴居人远一点儿。', `MaleText_loc5`='我們出發吧。不要讓那些岩石穴居怪傷害到我們。', `MaleText_loc7`='Vamos. Acabemos con esos troggs de piedra.' WHERE `ID`=43971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전초지 북쪽 경계에 빨리 도착하면 도착할수록, 가시바위 잔여지를 더 빨리 초토화할 수 있습니다.', `MaleText_loc4`='我们越快赶到前线的另一侧，就能越快把针石熔渣场毁成碎石堆。', `MaleText_loc5`='我們越快趕到前線的另一邊，我們越快可以把針岩熔渣夷為平地。', `MaleText_loc7`='Cuanto antes lleguemos al otro lado del frente de batalla, antes reduciremos la Fosa Rocaguja a escombros.' WHERE `ID`=43972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 왜?! 어떻게 그럴 수가 있습니까?', `MaleText_loc4`='可是为什么？！你怎么可以？', `MaleText_loc5`='可是為什麼?!你怎麼可以?', `MaleText_loc7`='¿Pero porqué? ¿Cómo has podido?' WHERE `ID`=43973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이동합니다!', `MaleText_loc4`='出去！', `MaleText_loc5`='出發!', `MaleText_loc7`='¡En marcha!' WHERE `ID`=43974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛이 어떠냐, 이 돌대가리 트로그들아?!', `MaleText_loc4`='感觉怎么样，你这石头穴居人渣滓？！', `MaleText_loc5`='感覺怎麼樣啊，臭岩石穴居怪?!', `MaleText_loc7`='¿¡Qué tal eso, miserable trogg de piedra!?' WHERE `ID`=43975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 예! 투석기가 나가신다. 모두 비켜라!', `MaleText_loc4`='喔耶！在我们强大的投石车面前战栗吧！', `MaleText_loc5`='喔耶!看我們的投石車的厲害!', `MaleText_loc7`='¡Oh, sí! ¡Temblad ante el poder de nuestras catapultas!' WHERE `ID`=43976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그 녀석들, 우리가 누군줄 알고 감히!', `MaleText_loc4`='你们这群石头穴居人根本不知道将要到来的是什么！', `MaleText_loc5`='你們這些岩石穴居怪根本不曉得我的厲害!', `MaleText_loc7`='¡Los troggs de piedra no tienen ni idea de la que se avecina!' WHERE `ID`=43977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 너도 그런 분노를 느껴봤을 거야. 너무나 잔혹하고 비열해서 누군가를 갈기갈기 난도질하고 싶어지는 그런 분노를...', `MaleText_loc4`='你当然感到愤怒。愤怒的情绪是如此邪恶和凶狠，会让你想要把人撕成碎片……', `MaleText_loc5`='你一定感受到了那種憤怒。強大無比的憤怒，恨不得找個人來撕成碎片...', `MaleText_loc7`='Seguro que has sentido ira. Una ira tan intensa y cruel que te ha hecho sentir ganas de hacer pedazos a alguien...' WHERE `ID`=43978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 지금 그런 분노가 느껴지지 않니?', `MaleText_loc4`='你难道现在没有感觉到吗？', `MaleText_loc5`='你現在感覺到了嗎?', `MaleText_loc7`='¿Lo sientes ahora?' WHERE `ID`=43979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐... 안돼! 그만둬!', `MaleText_loc4`='不……不！快停下！', `MaleText_loc5`='不...不!住口!', `MaleText_loc7`='¡No... NO! ¡DETENTE!' WHERE `ID`=43980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 알겠지... 너와 나는 그렇게 다르지 않아...', `MaleText_loc4`='你看，兄弟……我们并没有多大的差异……', `MaleText_loc5`='你看，兄弟...我們其實沒差多少...', `MaleText_loc7`='Ves, hermano... No somos tan diferentes...' WHERE `ID`=43981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐...', `MaleText_loc4`='不……', `MaleText_loc5`='不...', `MaleText_loc7`='No...' WHERE `ID`=43982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공할 확률이 얼마나 낮은지는 상관이 없네. 이 숲 속에서 벌어지고 있는 끔찍한 난리 통에 늑대인간을 단 한 명이라도 구할 수 있다면, 우리의 노력도 헛되지는 않겠지.', `MaleText_loc4`='我不在乎成功率会有多低。只要我们能从这丛林的疯狂与凶残中救出一只狼人，我们的努力就都没有白费。', `MaleText_loc5`='我不管成功的機率有多低。就算只能夠解救一個狼人脫離森林裡殘暴瘋狂的生活，我們的努力就不算白費。', `MaleText_loc7`='No me importa el éxito que tengamos. Si salvamos a un solo huargen de la ferocidad y demencia de los bosques, nuestros esfuerzos estarán recompensados.' WHERE `ID`=43983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망자들이 구원을 갈망하고 있어요. 고통에 찬 그들의 비명이 바람을 타고 울려 퍼지고 있네요.', `FemaleText_loc4`='亡者在乞求慰藉。他们的痛苦在风中回响。', `FemaleText_loc5`='哭嚎的亡者尋求安息，他們的苦痛在風中迴盪。', `FemaleText_loc7`='Los muertos claman en busca de alivio. El viento lleva los ecos de su angustia.' WHERE `ID`=43984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병은 나가 봐라.', `MaleText_loc4`='守卫，请退下。', `MaleText_loc5`='守衛們，先下去。', `MaleText_loc7`='Guardias, salgan.' WHERE `ID`=43985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말하지. 그냥 얘기나 하자고 그대를 부른 건 아니다.', `MaleText_loc4`='我得承认，请你来此并非为了自我介绍和寒暄。', `MaleText_loc5`='我必須承認，我們帶你來這不是為了閒話家常或施以款待。', `MaleText_loc7`='Debo admitir que no te hemos traído para estas formalidades.' WHERE `ID`=43986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빙빙 돌리지 않겠다. 부탁하고 싶은 게 있다.', `MaleText_loc4`='且让我直奔主题。我们有事相求于你。', `MaleText_loc5`='我直接講重點。我們需要你幫我們做一件事。', `MaleText_loc7`='Iré directo al grano. Tenemos que pedirte algo.' WHERE `ID`=43987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스 안에 반역자가 있다... 인맥이 좋은 자 같고.', `MaleText_loc4`='在我们的城里有一名叛徒。蓄谋已久的叛徒。', `MaleText_loc5`='我們之中有一個叛徒，一個有很多人脈的人。', `MaleText_loc7`='Hay un traidor entre nosotros. Alguien con conexiones.' WHERE `ID`=43988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 반역자가 남자라고 추정하고 있습니다. 노련한 파수꾼이 그를 쫓았는데, 아마도 들킨 것 같아요.', `FemaleText_loc4`='我们其中一名最好的哨兵前去追踪"他"——我们假设那是名男子——但她似乎暴露了。', `FemaleText_loc5`='我們派了一位最優秀的女哨兵去追他 - 我們推測那應該是個男的 - 但她似乎被這叛徒給發現了。', `FemaleText_loc7`='Una de nuestros mejores centinelas le seguía el rastro, aunque al parecer él la descubrió. Damos por sentado que es un hombre.' WHERE `ID`=43989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 아침 순찰대가 그녀의 시체를 발견했습니다. 바로 이 도시 안에서 말이에요.', `FemaleText_loc4`='今天早上，她被我们的巡逻队发现了。她就在我们自己的城市里被谋杀了。', `FemaleText_loc5`='她的屍體今天早上被巡邏隊發現了。慘死在我們自己的城裡。', `FemaleText_loc7`='Las patrullas la encontraron esta mañana. Asesinada dentro de nuestra ciudad.' WHERE `ID`=43990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구를 믿어야 할지 모르겠습니다. 그대는 새로운 얼굴이고, 아는 사람이 별로 없습니다. 그게 이 사건에선 강점이지요.', `FemaleText_loc4`='很难分辨谁能够信任。你刚到此地不久……对此一无所知。也许你能胜任这次调查。', `FemaleText_loc5`='很難分辨到底誰是敵是友。因為你新來乍到...認得你的人還不多，所以這件案子交由你來調查反而比較有利。', `FemaleText_loc7`='Es difícil saber en quién se puede confiar. Tú acabas de llegar... no te conoce nadie. En este caso, eso juega a nuestro favor.' WHERE `ID`=43991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 반역자를 쫓는 데 그대의 도움이 필요하다. 어떤가?', `MaleText_loc4`='我们需要你的帮助，追捕这名叛徒。你愿意吗？', `MaleText_loc5`='我們需要你幫忙抓出這個叛徒，你願意嗎?', `MaleText_loc7`='Necesitamos que lo encuentres por nosotros. ¿Lo harás?' WHERE `ID`=43992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말씀드릴 게 하나 더 있습니다. 우리 쪽에서도 그대를 도울 이가 있어야겠지요.', `FemaleText_loc4`='还有一件事。我们安排了一名自己的人随你一同调查。', `FemaleText_loc5`='還有一件事情。我們安排了一位哨兵來陪你一起進行調查。', `FemaleText_loc7`='Una cosa más. Hemos decidido que uno de nosotros te acompañará.' WHERE `ID`=43993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='릴로리엔을 소개합니다.', `FemaleText_loc4`='这位是莉莉奥瑞伦。', `FemaleText_loc5`='這位是莉莉蘿芮蘭。', `FemaleText_loc7`='Esta es Lillorilen.' WHERE `ID`=43994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='릴리라고 불러 주세요.', `FemaleText_loc4`='请叫我莉莉。', `FemaleText_loc5`='請叫我莉莉就好。', `FemaleText_loc7`='Llámame Lilly.' WHERE `ID`=43995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살해당한 파수꾼은 바로 릴리의 자매입니다. 릴리는 믿으셔도 됩니다.', `FemaleText_loc4`='我们之前提到的那位哨兵是莉莉的姐妹。她可以信任。', `FemaleText_loc5`='遇害的那位哨兵正是莉莉的姊姊，你可以信任她。', `FemaleText_loc7`='La centinela de la que te he hablado era la hermana de Lilly. Puedes confiar en ella.' WHERE `ID`=43996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반역자를 반드시 잡겠습니다. 걱정하지 마십시오, 대여사제님.', `FemaleText_loc4`='我们会抓住那名叛徒的，女祭司。您无需担心。', `FemaleText_loc5`='不必擔心，我們一定會揪出這位叛徒的，牧師。', `FemaleText_loc7`='Encontraremos al traidor, sacerdotisa. No te preocupes.' WHERE `ID`=43997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 그대를 믿습니다. 하지만 조심하세요.', `FemaleText_loc4`='我相信你会的，但请一定小心。', `FemaleText_loc5`='我相信你一定會的，但是請務必要小心。', `FemaleText_loc7`='Confío en que lo harás, ten cuidado.' WHERE `ID`=43998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸움도 제대로 못 해보고 당한 모양이군요.', `FemaleText_loc4`='…这看上去几乎没有搏斗的痕迹。', `FemaleText_loc5`='...看來她好像絲毫沒有掙扎反抗的跡象。', `FemaleText_loc7`='... Parece como si apenas hubiera habido pelea.' WHERE `ID`=43999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니답지 않은 일입니다. 위험을 느꼈다면 필사적으로 싸웠을 사람이에요.', `FemaleText_loc4`='这很反常。当危险临近之时，她一定会全力一搏。', `FemaleText_loc5`='這實在很不像她。要是她知道會有危險，她肯定會拼死反抗。', `FemaleText_loc7`='No es propio de ella. Si hubiera sabido que corría peligro, habría luchado con uñas y dientes.' WHERE `ID`=44000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신을 잃은 채로 끌려 온 걸까요? 언니는 반역자의 꼬리를 잡았다고 생각했는데...', `FemaleText_loc4`='你认为那个杀手偷袭了她？即使她认为她发现了他的踪迹？', `FemaleText_loc5`='你覺得她是在無預警的狀況下遇害的嗎?雖然她以為自己已經發現了那位叛徒的蹤跡?', `FemaleText_loc7`='¿Crees que él la cogió por sorpresa? ¿A pesar de que ella pensara que le seguía el rastro?' WHERE `ID`=44001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샅샅이 살펴봅시다. 여기 어딘가에 그놈을 추적할 실마리가 있을 겁니다.', `FemaleText_loc4`='别放过任何细节。这里一定有什么线索能帮助我们捉到那个凶手。', `FemaleText_loc5`='提高警覺。這附近必定有留下什麼線索可以幫我們追出他的下落。', `FemaleText_loc7`='Abre bien los ojos. En alguna parte tiene que haber alguna pista que nos ayude a encontrarlo.' WHERE `ID`=44002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 찾으신 게 있나요?', `FemaleText_loc4`='你找到什么了？', `FemaleText_loc5`='你有發現什麼嗎?', `FemaleText_loc7`='¿Has encontrado algo?' WHERE `ID`=44003;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진흙 묻은 잎사귀라...', `FemaleText_loc4`='一片沾泥的叶子……', `FemaleText_loc5`='一片沾了泥巴的葉子...', `FemaleText_loc7`='Una hoja manchada de barro...' WHERE `ID`=44004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 잠깐 잎사귀 냄새를 맡습니다.', `FemaleText_loc4`='%s轻轻闻了闻那片叶子。', `FemaleText_loc5`='%s聞了一下這片葉子。', `FemaleText_loc7`='%s olisquea la hoja brevemente.' WHERE `ID`=44005;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녹잎이잖아! 운이 좋군요.', `FemaleText_loc4`='翠羽树叶！真是好运。', `FemaleText_loc5`='碧翠葉!真是幸運。', `FemaleText_loc7`='¡Hojaverde! Esto resulta afortunado.' WHERE `ID`=44006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 식물은 다르나서스 특정 지역에서만 자랍니다. 살인범의 신발에 딸려 왔는지도 몰라요.', `FemaleText_loc4`='在达纳苏斯只有一个地方长有这种树。也许我们要找的凶手就是在那里沾上这片树叶的。', `FemaleText_loc5`='達納蘇斯只有一個地方有長這種植物。或許這葉子是黏在兇手的靴子上被帶過來的。', `FemaleText_loc7`='Solo crece en un área concreta de Darnassus. Quizá nuestro asesino la trajo aquí pegada en una bota.' WHERE `ID`=44007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 찾는 건물은 장인의 정원에 있습니다. 어서 가 보죠.', `FemaleText_loc4`='我们要找的那栋建筑就在工匠区。我们走。', `FemaleText_loc5`='我們要找的那棟建築位在工匠區。我們走吧。', `FemaleText_loc7`='El edificio que buscamos está en el Bancal del Artesano. Vamos.' WHERE `ID`=44008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨로라는 저보다 몇 살 위예요.', `FemaleText_loc4`='维罗拉比我要大上几岁。', `FemaleText_loc5`='維羅拉比我大了幾歲。', `FemaleText_loc7`='Valora era varios años mayor que yo.' WHERE `ID`=44009;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근 몇 달간 저희는 어딘가 이상했습니다. 아니, 모든 이가 그랬죠.', `FemaleText_loc4`='过去这几个月我们一同经历了一段困难的时光。我猜所有人都是。', `FemaleText_loc5`='這幾個月我們的脾氣都有點暴躁，但我想大家都一樣。', `FemaleText_loc7`='Estos últimos meses han sido duros. Para todos, supongo.' WHERE `ID`=44010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런 기분 아시나요? 뭔가 잊어버린 것 같은데, 그게 뭔가 중요한 사실인 듯한 기분 말이에요. 말퓨리온 님이 돌아오신 이후로 우리 모두 그런 기분이랍니다.', `FemaleText_loc4`='你是否有过这种体验，某件事情你明知十分重要，却怎么也想不起来？似乎自从玛法里奥回来之后，所有人都变成了这样。', `FemaleText_loc5`='你有沒有過那種感覺，有些事情你明明知道它很重要，可是卻偏偏想不起來?自從瑪法里恩回來後我們大家都有這種感覺。', `FemaleText_loc7`='¿Nunca te ha pasado que no puedes recordar algo, pero sabes que es importante? Es lo que nos sucede a nosotros desde que regresó Malfurion.' WHERE `ID`=44011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가끔은 끔찍한 장면이 머릿속을 스쳐 지나갑니다. 한밤중에 그림자가 우리를 공격하거나, 마귀가 서로 공격하는 모습 같은 게요.', `FemaleText_loc4`='有时候我的眼前会闪过恐怖的镜像。阴影在黑夜中吞噬我们。亲友反目，自相残杀。', `FemaleText_loc5`='有時候我會瞥見一些恐怖的畫面，陰森的影子在黑夜裡襲擊我們，親朋好友反目成仇，互相攻擊。', `FemaleText_loc7`='A veces me vienen imágenes horribles. Sombras que nos asaltan en la noche. Amigos que se vuelven unos contra otros.' WHERE `ID`=44012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말로 표현하기 어렵군요. 말퓨리온 님이 돌아왔으니, 모든 게 해결돼야 맞는 건데. 텔드랏실도 용의 위상들에게... 그중 일부에게라도 축복을 받았고.', `FemaleText_loc4`='这些很难用语言形容。一切都应该变好的。玛法里奥回来了。泰达希尔终于得到了巨龙的祝福…某些巨龙的祝福。', `FemaleText_loc5`='很難具體講清楚。照理講，一切應該都變得很美好才對。瑪法里恩回來了，然後泰達希爾終於獲得了守護巨龍們的祝福...嗯，儘管不是全體的祝福。', `FemaleText_loc7`='Es difícil expresarlo con palabras. Todo debería ser maravilloso. Malfurion ha regresado. Por fin Teldrassil ha sido bendecido por los dragones Aspectos... Al menos por algunos.' WHERE `ID`=44013;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데 전 뭐랄까... 왠지 삶의 일부를 잃어버린 기분입니다. 희미해졌달까? 꿈속을 걷는 것처럼요.', `FemaleText_loc4`='但我总觉得……觉得我生命中的某些东西不见了，消逝了。仿佛梦境终于醒来。', `FemaleText_loc5`='但我猜我只是覺得...我覺得我的人生好像缺了一角。就這麼消逝了，彷彿從夢中醒來。', `FemaleText_loc7`='Pero supongo que siento... como si un pedazo de mi vida hubiera desaparecido. Borrada. Como al despertar de un sueño.' WHERE `ID`=44014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상당히 힘겨운 감정이었어요. 하지만 그런 데 영향을 받다니. 언니에게... 더 잘해 줬어야 했는데.', `FemaleText_loc4`='我不应当让这种失常影响到我。我……我应该比我的姐妹们要好受一些。', `FemaleText_loc5`='應該是壓力的關係，但是我不該讓壓力影響到我。我...我應該要對我姊姊更好一點的。', `FemaleText_loc7`='Siento la tensión, pero no debería haber dejado que me afectara. Debí... ser mejor hermana.' WHERE `ID`=44015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쯤 해서 한탄은 그만두지요. 여기가 그 건물입니다. 살펴보죠.', `FemaleText_loc4`='我的懊恼到此为止。这就是那座建筑。让我们进去调查一下。', `FemaleText_loc5`='抱歉，我講太多自己的憾事了。就是這棟建築，我們去看看吧。', `FemaleText_loc7`='Basta de lamentos. Este es el edificio. Registrémoslo.' WHERE `ID`=44016;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 도시를 방문하는 사람들이 머무는 곳입니다. 그 누구라도 여기 머물렀을 수 있어요.', `FemaleText_loc4`='这些房间通常会提供给造访城市的客人。任何人都有可能会居住在这里。', `FemaleText_loc5`='這些房間通常是提供給來到本城的訪客住的。事實上，任何人都有可能住過這裡。', `FemaleText_loc7`='Estas son las habitaciones para los invitados de la ciudad. Cualquiera habría podido alojarse aquí.' WHERE `ID`=44017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠해안 지도로군요. 아우버다인에서 로르다넬... 그리고 다른 여러 안식처로 통하는 길이 그려져 있습니다.', `FemaleText_loc4`='这是一张黑海岸的地图。上面绘有从奥伯丁通往洛达内尔的小径……还有几条路通往其他的安全藏身处。', `FemaleText_loc5`='這是一張黑海岸的地圖。上面畫有從奧伯丁到洛丹諾的幾條路線...還有其他幾個安全的居住地。', `FemaleText_loc7`='Es un mapa de la Costa Oscura. Hay caminos que parten de Auberdine hacia Lor''danel... y hacia otros refugios seguros.' WHERE `ID`=44018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모종의 공격 계획일까요? 아우버다인은 대격변이 처음으로 대지를 뒤흔들었을 때 완전히 파괴됐습니다. 아무 가치가 없다고요.', `FemaleText_loc4`='这是某种攻击计划？奥伯丁已经被大灾变的动荡撕碎了。那儿能有什么价值？', `FemaleText_loc5`='難道這是攻擊計畫嗎?可是，奧伯丁已經在大災變爆發的時候遭受重創，誰還會想去攻擊那裡呢?', `FemaleText_loc7`='¿Puede ser un plan de ataque? Auberdine fue saqueada durante los primeros coletazos del Cataclismo. ¿Para quién tendría valor algo así?' WHERE `ID`=44019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩌면 탈출 계획서일 수도 있겠군요.', `FemaleText_loc4`='我认为这些可能是逃跑路线。', `FemaleText_loc5`='我想，這應該是逃亡路線才對。', `FemaleText_loc7`='Supongo que podrían ser rutas de escape.' WHERE `ID`=44020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해변을 가로지르는 길에 동그라미가 있습니다. 이리로 가서 뭔가 실마리가 있는지 찾아보죠.', `FemaleText_loc4`='这条穿过海滩的路线被圈了起来。我们赶快前往那个地方，看看能不能有什么发现。', `FemaleText_loc5`='穿過岸邊的這條路線畫了個圈，我們過去那邊看看是否有任何線索。', `FemaleText_loc7`='La ruta que cruza la playa está marcada. Vayamos allí y veamos qué podemos encontrar.' WHERE `ID`=44021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 티란데 님과 말퓨리온 님께 지금까지 알아낸 걸 보고하겠어요. 되도록 빨리 올 테니 해변에서 만나지요.', `FemaleText_loc4`='我会向泰兰德和玛法里奥报告我们的进展。我会尽快与你在海滩会合。', `FemaleText_loc5`='我得先去跟泰蘭妲和瑪法里恩通報我們的調查進展，然後我會盡快在岸邊那兒跟你會合。', `FemaleText_loc7`='Voy a informar a Tyrande y a Malfurion de nuestros avances. Me reuniré contigo en la playa en cuanto pueda.' WHERE `ID`=44022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 바로 그리로 가보세요. 조심하시고요.', `FemaleText_loc4`='你最好径直过去，但千万留心。', `FemaleText_loc5`='你最好直接趕去那裡，但是請務必小心。', `FemaleText_loc7`='Será mejor que vayas allí directamente, ten cuidado.' WHERE `ID`=44023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬이시여! 피난민들이 기습을 당했군요... 배신당했어요...', `FemaleText_loc4`='以艾露恩之名！他们都遭到了伏击…这是背叛…', `FemaleText_loc5`='伊露恩啊!他們全遭到偷襲...被出賣了...', `FemaleText_loc7`='¡Por Elune! Fueron emboscados... traicionados...' WHERE `ID`=44024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반역자가 꾸민 짓일 겁니다! 대학살을 도왔다고요.', `FemaleText_loc4`='那个叛徒策划了一切！他是这场屠杀的帮凶。', `FemaleText_loc5`='是這個叛徒協助策劃的!他協助屠殺了他們。', `FemaleText_loc7`='¡El traidor ayudó a planear esto! Ayudó a masacrarlos.' WHERE `ID`=44025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈은 부상을 당했군요. 흔적을 찾을 수 있을 듯합니다.', `FemaleText_loc4`='他受伤了。我想我能追踪这些血迹。', `FemaleText_loc5`='他受傷了。我想我應該可以找出他的蹤跡。', `FemaleText_loc7`='Fue herido. Creo que puedo seguir el rastro.' WHERE `ID`=44026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽입니다! 제게서 떨어지지 마세요.', `FemaleText_loc4`='这边！跟着我。', `FemaleText_loc5`='這邊!跟我走。', `FemaleText_loc7`='¡Por aquí! No te alejes de mí.' WHERE `ID`=44027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲 가장자리를 따라 다시 마을로 향하는 흔적이 여러 개 있습니다. 하지만 반역자의 흔적인지 확신할 수 없군요.', `FemaleText_loc4`='这边有一些新鲜的痕迹，沿着森林的边缘一直延伸到了镇上。但很难讲是不是他留下的。', `FemaleText_loc5`='有道新的足跡沿著森林的邊緣走回鎮上。但很難確定到底是不是他的。', `FemaleText_loc7`='Hay huellas recientes que recorren la linde del bosque hacia la ciudad. Sin embargo, es difícil saber si son de él.' WHERE `ID`=44028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여길 보세요! 핏자국입니다. 이 길이 맞아요.', `FemaleText_loc4`='这儿！一块血迹。我们的方向是正确的。', `FemaleText_loc5`='這裡!有血跡。我們走對了。', `FemaleText_loc7`='¡Aquí! Una mancha de sangre. Vamos por el buen camino.' WHERE `ID`=44029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경비병 코앞을 지나가? 뻔뻔한 놈...', `FemaleText_loc4`='就在守卫的眼皮下？自信的杂种…', `FemaleText_loc5`='我們衛兵的身邊?這混帳真有自信...', `FemaleText_loc7`='¿Justo delante de nuestros guardias? Escoria insolente...' WHERE `ID`=44030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파수꾼! 부상당한 나이트 엘프가 이 길을 지나갔소?', `FemaleText_loc4`='哨兵！你有没有看到一个受伤的暗夜精灵经过？', `FemaleText_loc5`='哨兵!你有見到一位受傷的夜精靈經過這邊嗎?', `FemaleText_loc7`='¡Centinela! ¿Has visto pasar a un elfo de la noche herido?' WHERE `ID`=44031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네. 폭포 쪽으로 갔습니다. 상처를 치료하고 가라고 그렇게 말해도 듣는 척도 안 하더군요.', `FemaleText_loc4`='是的。朝瀑布那边去了。我劝他疗好伤再走，可他不听。', `FemaleText_loc5`='有。朝瀑布去了。我有勸他先處理一下傷口，但是他不理我。', `FemaleText_loc7`='Sí, cerca de la cascada. Intenté convencerle para que le trataran las heridas, pero no me hizo caso.' WHERE `ID`=44032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 갑시다, 친구여!', `FemaleText_loc4`='过来，朋友，赶快！', `FemaleText_loc5`='走吧，朋友。動作快!', `FemaleText_loc7`='Ven, camarada. ¡Rápido!' WHERE `ID`=44033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저깁니다! 같이 있는 자는 누구죠?', `FemaleText_loc4`='在那里！他在和谁说话？', `FemaleText_loc5`='那邊!跟他碰面的人是誰?', `FemaleText_loc7`='¡Ahí! ¿Quién es ese con el está reunido?' WHERE `ID`=44034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='움직입시다!', `FemaleText_loc4`='我们行动！', `FemaleText_loc5`='我們走吧!', `FemaleText_loc7`='¡Movámonos!' WHERE `ID`=44035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것들이 어디로 갔지?', `FemaleText_loc4`='……他们去了哪里？', `FemaleText_loc5`='...他們去哪兒了?', `FemaleText_loc7`='¿... adónde han ido?' WHERE `ID`=44036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지상으로는 빠져나갈 길이 없습니다. 어쩌면 놈들은...', `FemaleText_loc4`='他们从地面上逃不掉，难道他们……', `FemaleText_loc5`='陸路已經無處可逃，除非他們是...', `FemaleText_loc7`='No han podido escapar por tierra. Quizá han...' WHERE `ID`=44037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늑대인간도 수영을 할 줄 알았으면 좋겠군요.', `FemaleText_loc4`='我希望你会游泳，狼人。', `FemaleText_loc5`='狼人，希望你會游泳。', `FemaleText_loc7`='Espero que sepas nadar, huargen.' WHERE `ID`=44038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오셨군요. 다행입니다.', `FemaleText_loc4`='真高兴你成功了。', `FemaleText_loc5`='很高興你游過來了。', `FemaleText_loc7`='Me alegro de que lo consiguieras.' WHERE `ID`=44039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들은 바로 저 위에 있습니다. 물소리가 우리 발걸음 소리를 가려줄 거예요. 준비되면 말씀하시죠.', `FemaleText_loc4`='他们就在头顶上。流水应该能掩盖我们接近的声音。当你准备好就告诉我。', `FemaleText_loc5`='他們就在前面。流水的聲音應該可以掩護我們。你準備好了就告訴我。', `FemaleText_loc7`='Están ahí delante. El sonido del agua ocultará el nuestro. Avísame cuando quieras ponerte en marcha.' WHERE `ID`=44040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끝내 버립시다.', `FemaleText_loc4`='让我们结束这一切。', `FemaleText_loc5`='做個了結吧。', `FemaleText_loc7`='Acabemos con esto.' WHERE `ID`=44041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 이교도를 맡을 테니, 그대가 반역자를 처리하세요.', `FemaleText_loc4`='我会对付邪教徒。你处理那个叛徒。', `FemaleText_loc5`='我來對付教徒，你去處理那個叛徒。', `FemaleText_loc7`='Yo me encargo del cultor. Tú, del traidor.' WHERE `ID`=44042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈을 놓치지 마세요!', `FemaleText_loc4`='别让他逃走了！', `FemaleText_loc5`='別讓他跑了!', `FemaleText_loc7`='¡NO dejes que escape!' WHERE `ID`=44043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐. 제가 끝장내겠습니다.', `FemaleText_loc4`='别动，让我结果他。', `FemaleText_loc5`='停。讓我殺了他。', `FemaleText_loc7`='Espera. Déjame acabar con él.' WHERE `ID`=44044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 릴리. 그를 죽이지 마세요.', `FemaleText_loc4`='不，莉莉，别杀他。', `FemaleText_loc5`='不，莉莉。不要殺他。', `FemaleText_loc7`='No, Lilly. No lo mates.' WHERE `ID`=44045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만... 전... 네, 대여사제님. 뜻대로 하겠습니다.', `FemaleText_loc4`='但…我…是的，我的女士，如你所愿。', `FemaleText_loc5`='可是...我...是，祭司。遵命。', `FemaleText_loc7`='Pero... yo... sí, mi señora. Como desees.' WHERE `ID`=44046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데나타리온, 왜 그랬지? 넌 항상 희망에 찬 아이였지 않느냐?', `MaleText_loc4`='为什么，德纳萨里安？我看着你长大，你心中曾经充满希望。', `MaleText_loc5`='為什麼，德納薩里安?我從小看著你長大，你的心中曾經充滿希望。', `MaleText_loc7`='Denatharion, ¿por qué? Te conozco desde que eras un niño. Con el corazón lleno de esperanza.' WHERE `ID`=44047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망? 판드랄 님이 품었던 희망 같은 것 말인가? 우리에게 불멸의 삶을, 영광을 되찾아 주겠다는 희망?', `MaleText_loc4`='希望？就像范达尔希望为我族赢回往日的荣耀？重新得到不朽的生命？', `MaleText_loc5`='希望?就像范達爾要帶領我們重歸榮耀的希望嗎?就像恢復永生的希望嗎?', `MaleText_loc7`='¿Esperanza? ¿Cómo la que albergaba Fandral por recuperar la gloria de nuestro pueblo? ¿Recuperar la inmortalidad?' WHERE `ID`=44048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 질투에 눈이 멀어 그분께 유죄를 선고하고 비밀 감옥으로 보냈지. 아주 열심이더군. 네 형제에게 그랬던 것처럼 말이다.', `MaleText_loc4`='因为你的嫉妒，你对他判刑，将他关进你的秘密监狱，如同对你的亲兄弟所做的一样。', `MaleText_loc5`='而你因為出於嫉妒，竟然將他定罪，並且打入你的秘密監獄。急切得就像當年你對待你自己的親弟弟那樣!', `MaleText_loc7`='Con tus celos, lo condenaste y lo enviaste a tu prisión secreta. Tan ansioso como cuando lo hiciste con tu propio hermano.' WHERE `ID`=44049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동족 사이에서 내 자리를 찾을 수 없다면, 내가 어디로 가야 하겠나, "샨도"?', `MaleText_loc4`='如果我不能在我的族人之中找到一个家，我还能去哪里，“导师”？', `MaleText_loc5`='要是我無法在自己的族人間找到一個家，那我還能上哪兒去找呢，「師尊」?', `MaleText_loc7`='Si no puedo encontrar mi hogar entre mi propio pueblo, ¿adónde debo dirigirme, "Shand''do"?' WHERE `ID`=44050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고민스러운 표정으로 몸을 돌립니다.', `MaleText_loc4`='%s转过身，看上去非常不安。', `MaleText_loc5`='%s滿面憂愁地轉了過去。', `MaleText_loc7`='%s se aparta, claramente perturbado.' WHERE `ID`=44051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='릴리, 죄수를 파수꾼에게 데려가세요. 법도에 따라 처분을 내릴 것입니다.', `FemaleText_loc4`='莉莉，请将这名犯人带给哨兵，我们将公正的对待他。', `FemaleText_loc5`='莉莉，請把這位人犯帶回去交給哨兵，好讓我們可以適當地審理他。', `FemaleText_loc7`='Lilly, lleva a nuestro prisionero con los centinelas para que podamos tratar con él como es debido.' WHERE `ID`=44052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 대여사제님.', `FemaleText_loc4`='当然，我的女士。', `FemaleText_loc5`='是，祭司。', `FemaleText_loc7`='Por supuesto, mi señora.' WHERE `ID`=44053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 늑대인간이여, 그대는 오늘 정말 대단한 일을 해주었습니다.', `FemaleText_loc4`='还有你，我亲爱的狼人，今天你可帮了我们一个大忙。', `FemaleText_loc5`='至於你，狼人朋友，你今天為了我們立下了大功一件。', `FemaleText_loc7`='Y tú, querido huargen, hoy has hecho mucho por nosotros.' WHERE `ID`=44054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비록 드러내진 않았지만, 말퓨리온은 그대들이 오는 것에 대해 많이 걱정했지요.', `FemaleText_loc4`='玛法里奥也许不会把他的想法挂在嘴边，但他却一直在关注着你的族人。', `FemaleText_loc5`='瑪法里恩雖然沒有公開說出來，但其實他非常掛心你們狼人的現身。', `FemaleText_loc7`='Quizá Malfurion no lo diga en voz alta, pero estaba muy preocupado por el futuro de tu gente.' WHERE `ID`=44055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말퓨리온은 그대들이 받은 저주와 그 때문에 생길 수 있는 끔찍한 일들에 대해 잘 알고 있습니다. 어쩌면 어느 정도는 자책하고 있는지도 모르고요.', `FemaleText_loc4`='他非常了解你们所遭受的诅咒和它的可怕影响。对此他也对自己怀有几分自责。', `FemaleText_loc5`='他很清楚你們身上的詛咒及其可怕的隱慮，他甚至認為他自己也得為這件事情擔點責任。', `FemaleText_loc7`='Conoce muy bien tu maldición y las cosas terribles que ésta supone. Incluso puede que se sienta responsable hasta cierto punto.' WHERE `ID`=44056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 그대 덕분에 말퓨리온이 걱정을 좀 덜겠군요. 그대는 고귀함과 자제력을 보여주었습니다. 어쩌면 말퓨리온이 기대했던 것보다도 더 많이.', `FemaleText_loc4`='我想今天你已经消除了他的疑虑。你显示出的高贵和自律也许已经超出了他期待。', `FemaleText_loc5`='我想今天你應該已解決了他心頭的部分憂慮，因為你展現出了高尚的情操和高度的自制力，甚至遠超乎了他的想像。', `FemaleText_loc7`='Creo que hoy has apaciguado algunas de sus preocupaciones. Has mostrado nobleza y control. Quizá más de la que él creía posible.' WHERE `ID`=44057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진심으로 감사합니다.', `FemaleText_loc4`='真心地感谢你。', `FemaleText_loc5`='我衷心感謝你。', `FemaleText_loc7`='Gracias. De corazón.' WHERE `ID`=44058;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여길 떠날 준비가 되면 말씀하세요.', `FemaleText_loc4`='当你准备离开这儿时请一定告诉我。', `FemaleText_loc5`='等你準備離開此處時便告知我。', `FemaleText_loc7`='Avísame cuando quieras marcharte.' WHERE `ID`=44059;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 보니 정말 기쁘군요, 친구여.', `FemaleText_loc4`='很高兴再次见到你，朋友。', `FemaleText_loc5`='很高興又見面了，朋友。', `FemaleText_loc7`='Me alegro de verte de nuevo, camarada.' WHERE `ID`=44060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 폭포 앞에 있는 얀시에게 가져가십시오. 그 무식한 인간은 제 머리카락이 아닐 거라곤 상상도 못할 겁니다.', `MaleText_loc4`='把那个带给扬希——就在瀑布边上。那个无知的人类不会知道那不是我。', `MaleText_loc5`='把那個帶回去給楊希，就在瀑布旁邊。那個蠢人類根本不會曉得那不是我。', `MaleText_loc7`='Llévaselo de vuelta a Yancey, al lado de la cascada. Ese humano ignorante no tendrá ni idea de que no soy yo.' WHERE `ID`=44061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비천한 벌레들 같으니. 모르고르 밀쳐내기 맛을 봐라!', `MaleText_loc4`='可怜的虫子。准备面对莫格霍尔猛击吧！', `MaleText_loc5`='卑微的小蟲，準備迎接莫格猛擊!', `MaleText_loc7`='Gusanos patéticos. ¡Prepárense para sufrir el Embate de Mor''ghor!' WHERE `ID`=44062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그레고리를 소개합니다.', `FemaleText_loc4`='这位是格雷戈里。', `FemaleText_loc5`='這位是葛列格里。', `FemaleText_loc7`='Este es Gregory.' WHERE `ID`=44063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다.', `MaleText_loc4`='为您效劳。', `MaleText_loc5`='謹供差遣。', `MaleText_loc7`='A tu servicio.' WHERE `ID`=44064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그레고리는 길니아스에서 온 우리의 새로운 동맹입니다. 이번 사건에 관련되어 있을 리가 없지요. 그래서 그레고리를 믿기로 했습니다.', `FemaleText_loc4`='他是我们的新盟友，从吉尔尼斯而来。很容易就能推断出他并未牵涉进此事，我们能够相信他。', `FemaleText_loc5`='葛列格里是來自吉爾尼斯的一位新盟友。很顯然地，他跟這件事情不可能有關，所以我們決定信任他。', `FemaleText_loc7`='Gregory es uno de nuestros nuevos aliados de Gilneas. Está claro que no puede estar implicado en esto, así que hemos decidido confiar en él.' WHERE `ID`=44065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역자를 반드시 잡겠습니다. 걱정하지 마십시오, 대여사제님.', `MaleText_loc4`='我们定会捉住那名叛徒的，我尊敬的女士。您无需担忧。', `MaleText_loc5`='不必擔心，我們一定會揪出這位叛徒的，牧師。', `MaleText_loc7`='Encontraremos al traidor, mi señora. No te preocupes.' WHERE `ID`=44066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움도 제대로 못 해보고 당한 모양이군.', `MaleText_loc4`='…这看上去几乎没有搏斗的痕迹。', `MaleText_loc5`='...看來她好像絲毫沒有掙扎反抗的跡象。', `MaleText_loc7`='...Parece como si apenas hubiera habido pelea.' WHERE `ID`=44067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수꾼이 이렇게 쉽게 당하기도 하나? 무시무시한 전사들이라고 들었는데.', `MaleText_loc4`='一名哨兵会如此容易地被击倒？我以为她们都是精锐的战士。', `MaleText_loc5`='哨兵的成員真的會這麼容易就被殺掉嗎?我還以為他們全都是武藝高超的戰士。', `MaleText_loc7`='¿Una centinela habría caído tan fácilmente? Creía que eran guerreras fieras.' WHERE `ID`=44068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 믿는 이에게 당해 의식을 잃은 채로 끌려 왔는지도 모르겠군.', `MaleText_loc4`='也许她被偷袭了。也许…她完全信任那个杀手。', `MaleText_loc5`='也許她是在無預警的狀況下遇害的。說不定那個叛徒就是這麼地受到大家的信任。', `MaleText_loc7`='Quizá la cogió por sorpresa. Quizá él sea alguien en quien ella confiara.' WHERE `ID`=44069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샅샅이 살펴보자. 여기 어딘가에 그놈을 추적할 실마리가 있을 것이다.', `MaleText_loc4`='别放过任何细节。这里一定有什么线索能帮助我们捉到那个凶手。', `MaleText_loc5`='提高警覺。這附近必定有留下什麼線索可以幫我們追出他的下落。', `MaleText_loc7`='Abre bien los ojos. En alguna parte tiene que haber alguna pista que nos ayude a encontrarlo.' WHERE `ID`=44070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 찾은 거라도 있나?', `MaleText_loc4`='你找到什么了？', `MaleText_loc5`='你有發現什麼嗎?', `MaleText_loc7`='¿Has encontrado algo?' WHERE `ID`=44071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 묻은 잎사귀라...', `MaleText_loc4`='一片沾泥的叶子……', `MaleText_loc5`='一片沾了泥巴的葉子...', `MaleText_loc7`='Una hoja con barro...' WHERE `ID`=44072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 잠깐 잎사귀 냄새를 맡습니다.', `MaleText_loc4`='%s轻轻闻了闻那片叶子。', `MaleText_loc5`='%s聞了一下這片葉子。', `MaleText_loc7`='%s huele la hoja brevemente.' WHERE `ID`=44073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단히 독특한 냄새로군. 근처에는 이런 냄새가 나는 식물은 없는 듯한데.', `MaleText_loc4`='一种特别的气味。附近区域里没有东西会发出这种味道。', `MaleText_loc5`='很特殊的氣味。這附近似乎沒有和它相似的氣味。', `MaleText_loc7`='Un olor muy peculiar. No parece que haya nada similar por esta zona.' WHERE `ID`=44074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새를 추적해 보겠다. 이 나뭇잎이 살인자에게 딸려 여기까지 왔기를 바라자.', `MaleText_loc4`='我应该能追踪这些痕迹。希望是那个杀手留下的。', `MaleText_loc5`='我應該有辦法追出它的來源。希望這是那個兇手帶過來的。', `MaleText_loc7`='Con esto debería ser capaz de seguir un rastro. Esperemos que el asesino la trajera aquí.' WHERE `ID`=44075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 북동쪽으로 이어지는군. 괜찮으면 따라와라.', `MaleText_loc4`='这些足迹延向了东北方。请跟着我。', `MaleText_loc5`='氣味來自於東北方。麻煩請跟著我走。', `MaleText_loc7`='El rastro conduce al noreste. Sígueme.' WHERE `ID`=44076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 오랫동안 길니아스에서만 살았다. 집이라 부를 곳을 쉽게 찾을 수 없을 듯해서 많이 두려웠지.', `MaleText_loc4`='长久以来，我对吉尔尼斯之外的世界一无所知。我深恐我们再也没办法找到一个可以称之为家园的地方了。', `MaleText_loc5`='長久以來，我對吉爾尼斯以外的其他地方都一無所知。原本我還很擔心，我們恐怕無法在短時間內再尋得一個可以稱之為家的地方。', `MaleText_loc7`='Durante mucho tiempo solo he conocido Gilneas. Temía que ya no encontraríamos un sitio al que llamar hogar.' WHERE `ID`=44077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데 님과 말퓨리온 님은 우리를 따뜻하게 맞아 주셨다. 오랫동안 소식이 끊긴 가족인 것처럼... 이상하지만 편안한 기분이었지.', `MaleText_loc4`='泰兰德和玛法里奥张开双臂接纳了我们。就好象我们是失散已久的家人。这很奇怪…也很令人宽慰。', `MaleText_loc5`='沒想到泰蘭妲和瑪法里恩卻敞開雙臂熱情地歡迎我們，好像我們是失散已久的家人那樣。感覺雖然有點奇怪，但是又很窩心。', `MaleText_loc7`='Tyrande y Malfurion nos acogieron con los brazos abiertos. Casi como si fuéramos parte de la familia. Fue extraño y reconfortante.' WHERE `ID`=44078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 혼란스러운 수군거림이 들려오더군... 심지어 불만이 담긴 듯도 한.', `MaleText_loc4`='但我也听到了一些传言…困惑的传言…甚至是反对的声音。', `MaleText_loc5`='但是我有聽到一些耳語...困惑的耳語...甚至是不滿的耳語。', `MaleText_loc7`='Pero oigo murmullos... murmullos de confusión... quizás, incluso murmullos de desacuerdo.' WHERE `ID`=44079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 된 일인지 말퓨리온 님께 물었더니, 그분께서는 최근 이 도시가 비극을 겪었다고 하셨다. 많은 이가 죽고, 한 지도자가 붙잡혔다고.', `MaleText_loc4`='我向玛法里奥问起此事，他告诉了我这座城市近来经历的悲剧。一名领袖被劫走了，许多生命逝去了。', `MaleText_loc5`='我向瑪法里恩問了這件事情，他說這座城市才剛遭逢了一件重大的悲劇。有一位領導者因此而被帶走，而且還有許多人犧牲了寶貴的性命。', `MaleText_loc7`='Pregunté a Malfurion sobre esto, y dijo que la ciudad había sufrido una tragedia recientemente. Que uno de los líderes desapareció y se perdieron vidas.' WHERE `ID`=44080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분은 시민들의 속삭임 이상의 뭔가를 알고 계시는 듯하다. 이 반역자가 도시에 남은 마지막 문제라고 확신하고 계시지. 대격변은 제외하고 말이다.', `MaleText_loc4`='他似乎比那些低语的平民所知更多，他确信这名叛徒是达纳苏斯最后的麻烦，除了大灾变。', `MaleText_loc5`='他知道的彷彿不只是互相耳語的市民們而已，而且他好像很肯定這位叛徒是達納蘇斯這場動亂的最後一個問題，除了大災變的動亂之外。', `MaleText_loc7`='Creo que sabe más que los ciudadanos que murmuran y parece convencido de que ese traidor es lo único que queda de los problemas de la ciudad, aparte del Cataclismo.' WHERE `ID`=44081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 현명함은 물론 진솔함에도 감명을 받았다. 그러니 그분의 말씀을 그대로 믿을 것이다. 더 자세히 알고는 싶지만, 내게 그럴 자격은 없지.', `MaleText_loc4`='玛法里奥的智慧和诚实令我折服。我相信了他的说法。也许还有其他的答案，但与我无关。', `MaleText_loc5`='瑪法里恩給我的印象是，他是個既睿智又坦白的人。我相信他所講的話，雖然我希望能知道更多的答案，但以我的立場實在不方便過問太多。', `MaleText_loc7`='Creo que Malfurion es sabio y sincero. Creo en su palabra. Me gustaría tener más respuestas, pero no debo preguntar.' WHERE `ID`=44082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 많이 떠들었군. 냄새는 여기에서 시작됐다. 이 건물 전체가 아까 찾은 그 잎사귀로 뒤덮여 있어.', `MaleText_loc4`='闲聊到此为止。足迹一直延伸到了这里。这座建筑里的植物长满了我们之前找到的那种叶子。', `MaleText_loc5`='抱歉，我太囉唆了。嗯，氣味就是從這裡飄出來的。這整棟建築都種著這種植物，葉子跟我們找到的這片是一樣的。', `MaleText_loc7`='Basta de divagaciones. El rastro termina aquí. Ese edificio está cubierto de plantas con hojas como la que hemos encontrado.' WHERE `ID`=44083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='객실이로군. 우리 중 몇몇도 여기 어디에 묵었지.', `MaleText_loc4`='这是客房。有些客房被提供给了我的族人。', `MaleText_loc5`='客房。我們有些人也有來住過這裡。', `MaleText_loc7`='Las habitaciones de invitados. Algunos de los míos se alojaron aquí.' WHERE `ID`=44084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이가 사용한 방이라, 범인을 추적하는 덴 별 도움이 안 되겠군. 일단 들어가 보지.', `MaleText_loc4`='太多人曾使用过这个地方，我们无从分辨气味。也许我们能在里边找到些线索。', `MaleText_loc5`='住過的人太多，很難就此推測真兇到底是誰。但也許我們還可以在裡面找到些什麼。', `MaleText_loc7`='Las utiliza mucha gente y no nos dirán nada especial. Quizá encontremos algo dentro.' WHERE `ID`=44085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 찾았나?', `MaleText_loc4`='你找到什么了？', `MaleText_loc5`='你有發現什麼嗎?', `MaleText_loc7`='¿Has encontrado algo?' WHERE `ID`=44086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠해안 지도로군. 루테란 마을에 도착하기 전에 이 장소를 얼핏 봤다.', `MaleText_loc4`='一张黑海岸的地图。在到达鲁瑟兰村之前不久我才见过这些地方。', `MaleText_loc5`='黑海岸的地圖。在抵達魯瑟蘭村之前我有看到這個地方。', `MaleText_loc7`='Un mapa de la Costa Oscura. Vi este lugar justo antes de llegar a la Aldea Rut''theran.' WHERE `ID`=44087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우버다인에서 다른 곳으로 이어지는 길이 그려져 있군. 피난 계획처럼 보이는데.', `MaleText_loc4`='上面标注了一些路线，从奥伯丁出发，数个目的地。看起来像是撤离计划。', `MaleText_loc5`='畫了好幾條從從奧伯丁通往別地方的路線。看起來很像是逃脫計畫。', `MaleText_loc7`='Hay rutas que parten de esta Auberdine hacia diversos lugares. Parece un plan de evacuación.' WHERE `ID`=44088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽 해변을 가로지르는 경로에 동그라미가 있다. 어떻게 거기 가는지 아는가?', `MaleText_loc4`='这条通往西部海滩的路线被圈了起来。你知道怎么去那个地方吗？', `MaleText_loc5`='越過西側海岸的路線有畫了個圈。你對那邊的地形熟嗎?', `MaleText_loc7`='La ruta que cruza la playa occidental está marcada. ¿Sabes llegar allí?' WHERE `ID`=44089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 사실이든 밝혀내면 보고하겠다고 말퓨리온 님께 약속했다. 재빨리 보고하고 올 테니 해변에서 보지.', `MaleText_loc4`='我向玛法里奥作过承诺，无论有任何进展都将向他报告。我将尽快与你在海滩碰头。', `MaleText_loc5`='我答應過瑪法里恩，一有任何進展就會通知他。我會盡快跟你在海灘那兒碰面。', `MaleText_loc7`='He prometido a Malfurion que le informaría de cualquier avance. Me reuniré contigo en la playa en cuanto pueda.' WHERE `ID`=44090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 바로 그리로 가 보아라. 조심하고.', `MaleText_loc4`='你最好径直过去，但千万留心。', `MaleText_loc5`='你最好直接趕去那裡，但是請務必小心。', `MaleText_loc7`='Será mejor que vayas allí directamente, pero ten cuidado.' WHERE `ID`=44091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 끔찍한 학살이라니. 계획적인 습격인 듯하다. 이 정령들을 부리는 자는 누구일까...', `MaleText_loc4`='这是一场屠杀。一次有计划的伏击？这些元素的目标到底是谁？', `MaleText_loc5`='這簡直是一場屠殺。這是早有預謀的偷襲?這些元素究竟聽令於誰?', `MaleText_loc7`='Esto es una masacre. ¿Una emboscada? ¿A quién sirven esos elementales?' WHERE `ID`=44092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 반역자를 반드시 잡고 말겠다. 내 약속하지.', `MaleText_loc4`='我们要找到那个叛徒。我发誓。', `MaleText_loc5`='我保證，我們一定會逮到這個叛徒。', `MaleText_loc7`='Atraparemos a ese traidor. Lo prometo.' WHERE `ID`=44093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 부상을 당했군. 쉽게 추적할 수 있겠어.', `MaleText_loc4`='他受伤了。我很容易就能找到他的痕迹。', `MaleText_loc5`='他受傷了。我可以輕鬆地追出他的行蹤。', `MaleText_loc7`='Está herido. Puedo seguir su rastro fácilmente.' WHERE `ID`=44094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이다! 내게서 떨어지지 마라.', `MaleText_loc4`='这边！跟着我。', `MaleText_loc5`='這邊!跟我走。', `MaleText_loc7`='¡Por aquí! No te alejes de mí.' WHERE `ID`=44095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈의 흔적이 아직 뚜렷하군. 그리 멀리 있진 않을 것이다.', `MaleText_loc4`='他的痕迹还很新鲜。我们距离他不远了。', `MaleText_loc5`='他的味道還很強。我們的距離並不遠。', `MaleText_loc7`='El rastro es reciente. No estamos muy lejos.' WHERE `ID`=44096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가자, 친구여!', `MaleText_loc4`='过来，朋友，赶快！', `MaleText_loc5`='走吧，朋友。動作快!', `MaleText_loc7`='Ven, camarada. ¡Rápido!' WHERE `ID`=44097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기군! 같이 있는 자는 누구지?', `MaleText_loc4`='在那里！他在和谁说话？', `MaleText_loc5`='那邊!跟他碰面的人是誰?', `MaleText_loc7`='¡Ahí! ¿Quién es ese con el está reunido?' WHERE `ID`=44098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이자!', `MaleText_loc4`='我们行动！', `MaleText_loc5`='我們走吧!', `MaleText_loc7`='¡Movámonos!' WHERE `ID`=44099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것들이 어디로 갔지?', `MaleText_loc4`='……他们去了哪里？', `MaleText_loc5`='...他們去哪兒了?', `MaleText_loc7`='... ¿adónde han ido?' WHERE `ID`=44100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상으로는 빠져나갈 길이 없어 보인다. 어쩌면 놈들은...', `MaleText_loc4`='他们从地面上逃不掉，难道他们……', `MaleText_loc5`='陸路已經無處可逃，除非他們是...', `MaleText_loc7`='No han podido escapar por tierra. Quizá han...' WHERE `ID`=44101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수영은 할 줄 알겠지?', `MaleText_loc4`='希望你知道怎样游泳。', `MaleText_loc5`='我希望你會游泳。', `MaleText_loc7`='Espero que sepas nadar.' WHERE `ID`=44102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했군. 다행이다.', `MaleText_loc4`='真高兴你成功了。', `MaleText_loc5`='很高興你游過來了。', `MaleText_loc7`='Me alegro de que lo consiguieras.' WHERE `ID`=44103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 바로 저 위에 있다. 물소리가 우리 발걸음 소리를 가려 줄 것이다. 준비되면 이야기해라.', `MaleText_loc4`='他们就在头顶上。流水应该能掩盖我们接近的声音。当你准备好就告诉我。', `MaleText_loc5`='他們就在前面。流水的聲音應該可以掩護我們。你準備好了就告訴我。', `MaleText_loc7`='Están ahí delante. El sonido del agua ocultará el nuestro. Avísame cuando quieras ponerte en marcha.' WHERE `ID`=44104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내 버리자.', `MaleText_loc4`='让我们结束这一切。', `MaleText_loc5`='做個了結吧。', `MaleText_loc7`='Acabemos con esto.' WHERE `ID`=44105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이교도를 맡을 테니, 네가 반역자를 처리해라.', `MaleText_loc4`='我会对付邪教徒。你处理那个叛徒。', `MaleText_loc5`='我來對付教徒，你去處理那個叛徒。', `MaleText_loc7`='Yo me encargo del cultor. Tú, del traidor.' WHERE `ID`=44106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 벗어난 줄 알았나?', `MaleText_loc4`='没那么快，叛徒。', `MaleText_loc5`='上哪兒去啊，叛徒。', `MaleText_loc7`='No tan rápido, traidor.' WHERE `ID`=44107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 빠져나갈 순 없을 것이다. 할 말은 신전에 가서 해라.', `MaleText_loc4`='你不会这么容易就得到解脱。你还要等着月神殿的发落。', `MaleText_loc5`='你已經無處可逃了，乖乖跟我們回神殿。', `MaleText_loc7`='No saldrás de esta fácilmente. Debes responder ante el templo.' WHERE `ID`=44108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랍군요, 그레고리. 그대가 자신을 이렇게 잘 통제할 줄은 몰랐습니다.', `FemaleText_loc4`='令人印象深刻，格雷戈里。我必须承认，我从未料想过你能如此克制。', `FemaleText_loc5`='葛列格里，你真叫我刮目相看。我得承認，其實我沒料想到你能有這麼高的自制力。', `FemaleText_loc7`='Estoy impresionada, Gregory. Debo admitir que no esperaba tanto autocontrol.' WHERE `ID`=44109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼 길을 오는 동안 많은 이가 저희에 대해 그와 비슷한 이야기를 했습니다. 혹시라도 제가 오해를 불러일으킬 행동을 했다면 죄송합니다.', `MaleText_loc4`='我的族人们绝不是徒有虚名，我的女士。如果给您留下了任何疑虑，我都向您致歉。', `MaleText_loc5`='祭司，我們同胞也是歷經了好一番努力才有這樣的成果。要是有給您惹出了任何的麻煩，我在這邊向您致歉。', `MaleText_loc7`='Mi gente ha progresado mucho en ese aspecto, mi señora. Discúlpame si te he dado motivos para dudarlo.' WHERE `ID`=44110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그레고리, 죄수를 파수꾼에게 데려가 주세요. 법도에 따라 처분을 내릴 것입니다.', `FemaleText_loc4`='格雷戈里，请将这名凡人带给哨兵，我们将公正的对待他。', `FemaleText_loc5`='葛列格里，請把這位人犯帶回去交給哨兵，好讓我們可適當地審理他。', `FemaleText_loc7`='Gregory, lleva a nuestro prisionero con las centinelas para que podamos tratar con él como es debido.' WHERE `ID`=44111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 대여사제님.', `MaleText_loc4`='当然，我的女士。', `MaleText_loc5`='是的，祭司。', `MaleText_loc7`='Por supuesto, mi señora.' WHERE `ID`=44112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 나의 친구여, 그대는 오늘 정말 대단한 일을 해주었습니다.', `FemaleText_loc4`='至于你，我亲爱的朋友，今天你可帮了我们一个大忙。', `FemaleText_loc5`='至於你，朋友，你今天為了我們立下了大功一件。', `FemaleText_loc7`='Y tú, camarada, hoy has hecho mucho por nosotros.' WHERE `ID`=44113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도시 안에서 처음 보는 인물을 신뢰하기란 쉬운 일이 아닙니다. 그대는 참으로 어려운 시기에 우리에게 왔지요.', `FemaleText_loc4`='要让我们信赖一位新人着实不易。你恰好在这个危急时刻造访了我们。', `FemaleText_loc5`='對我們夜精靈而言，要全心信任一位新來乍到的外人並非一件容易的事情。尤其，你又是在這個動盪的時刻來到此處。', `FemaleText_loc7`='Resulta difícil confiar en alguien que acaba de llegar a la ciudad. Has venido a nosotros en un momento desesperado.' WHERE `ID`=44114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 다행히도, 그대는 명예롭고 훌륭하게 일을 처리해 주었어요.', `FemaleText_loc4`='这真是我们的幸运，你显示出了高尚的荣誉感和奉献精神。', `FemaleText_loc5`='還好，我們相當幸運，你已證明了你是個深具榮譽感與責任感的勇士。', `FemaleText_loc7`='Afortunadamente para nosotros, has resultado ser valiente y honorable.' WHERE `ID`=44115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 보니 정말 기쁘군, 친구여.', `MaleText_loc4`='很高兴再次见到你，朋友。', `MaleText_loc5`='很高興又見面了，朋友。', `MaleText_loc7`='Me alegro de verte de nuevo, camarada.' WHERE `ID`=44116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이리 빨리 돌아오셨소?', `MaleText_loc4`='这么快就回来了？', `MaleText_loc5`='這麼快又回來了?', `MaleText_loc7`='¿De vuelta tan pronto?' WHERE `ID`=44117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와이번이 한 마리 더 필요합니다.', `MaleText_loc4`='是的——我需要另一只双足飞龙。', `MaleText_loc5`='是的。我還需要一隻雙足飛龍。', `MaleText_loc7`='Sí, necesito otro jinete del viento.', `FemaleText_loc1`='와이번이 한 마리 더 필요해요.', `FemaleText_loc4`='是的——我需要另一只双足飞龙。', `FemaleText_loc5`='是的。我還需要一隻雙足飛龍。', `FemaleText_loc7`='Sí, necesito otro jinete del viento.' WHERE `ID`=44118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 밖으로 나가 네놈들의 덫에 걸려들 것 같으냐! 여기서 나와 맞서 봐라, 겁쟁이들아!', `MaleText_loc4`='别想把我骗到外面，我不会中你的陷阱！就在这里面对我吧，懦夫！', `MaleText_loc5`='我才不會被騙出去落進你的陷阱!懦夫，在這裡面對我!', `MaleText_loc7`='¡No saldré para caer en tu trampa! ¡Enfréntate a mí aquí, cobarde!' WHERE `ID`=44119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게, $n. 그 함선에 오래 있으면 안돼... 포탄 몇 발이면 바로 침몰할 거야.', `MaleText_loc4`='在外多加小心，$n。你不会想要在那艘船上待很久……再来几发炮弹她就会沉了。', `MaleText_loc5`='自己小心點，$n，你不會想在那艘船上待太久的...挨個幾發砲彈它就會沈了。', `MaleText_loc7`='Ten cuidado, $n. No querrás estar en ese barco mucho tiempo... Unas bolas de cañón más y pronto se hundirá.' WHERE `ID`=44120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아아! 모르고르의 분노에 맞서 보아라!', `MaleText_loc4`='呜哇！感受莫格霍尔的愤怒吧！', `MaleText_loc5`='呃啊啊啊!面對莫格的憤怒!', `MaleText_loc7`='¡Rghaaaa! ¡Enfréntense a la furia de Mor''ghor!' WHERE `ID`=44121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단단히 각오해라! 모르고르 밀쳐내기!', `MaleText_loc4`='准备受罚吧！莫格霍尔猛击！', `MaleText_loc5`='準備接受懲罰!莫格猛擊!', `MaleText_loc7`='¡Prepárense para su castigo! ¡Embate de Mor''ghor!' WHERE `ID`=44122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동족을 오랫동안 괴롭혔던 어둠에서 영원히 벗어나리란 희망 말이지요.', `MaleText_loc4`='我们终将自长久萦绕的阴影中获得解脱。', `MaleText_loc5`='我們同胞已被這陰影籠罩太久了，希望能就此擺脫它。', `MaleText_loc7`='La esperanza de liberarnos de la sombra para siempre le ha sido negada a mi pueblo durante mucho tiempo.' WHERE `ID`=44123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베른호가 곧 도착합니다! 무장을 갖추고 정렬하세요, 여러분!', `MaleText_loc4`='凡尔纳号很快就要到了！拿起武器整队备战，兄弟们！', `MaleText_loc5`='維恩號就快抵達了!兄弟們，收好裝備，排好隊伍!', `MaleText_loc7`='¡El Verne está a punto de llegar! ¡Preparad las armas y a formar!' WHERE `ID`=44124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베른호가 정박했습니다. 모두 올라타세요!', `MaleText_loc4`='凡尔纳号已经到达。全体登船！', `MaleText_loc5`='維恩號靠岸了。全體上船!', `MaleText_loc7`='El Verne ha atracado. ¡Todos a bordo!' WHERE `ID`=44125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간이 주저하고 있습니다!', `MaleText_loc4`='狼人凝视着迟疑了！', `MaleText_loc5`='狼人瞪大眼睛，遲疑了一下!', `MaleText_loc7`='¡El huargen mira y duda!', `FemaleText_loc1`='늑대인간이 주저하고 있습니다!', `FemaleText_loc4`='狼人凝视着迟疑了！', `FemaleText_loc5`='狼人瞪大眼睛，遲疑了一下!', `FemaleText_loc7`='¡El huargen mira y duda!' WHERE `ID`=44126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 안에는 전쟁의 피가 끓고 있어!', `MaleText_loc4`='战斗是我的天性！', `MaleText_loc5`='我流著戰爭之血!', `MaleText_loc7`='¡LA GUERRA CORRE POR MIS VENAS!' WHERE `ID`=44127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 네가 자초한 일이다!', `MaleText_loc4`='这是你自找的！', `MaleText_loc5`='這是你自找的!', `MaleText_loc7`='¡Te lo has buscado!' WHERE `ID`=44128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 내버려 뒀어야지.', `MaleText_loc4`='不来惹我们就没事了。', `MaleText_loc5`='不該來招惹我們的。', `MaleText_loc7`='Deberías habernos dejado en paz.' WHERE `ID`=44129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥 맛을 봐라!', `MaleText_loc4`='感受雷霆的怒吼吧！', `MaleText_loc5`='嚐嚐雷電!', `MaleText_loc7`='¡SIENTE EL TRUENO!' WHERE `ID`=44130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네까짓 게!', `MaleText_loc4`='你无足轻重！', `MaleText_loc5`='你不算什麼!', `MaleText_loc7`='¡No eres nada!' WHERE `ID`=44131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게 고통을 주게 될 날을 손꼽아 기다려 왔다!', `MaleText_loc4`='你的痛苦让我感到兴奋不已！', `MaleText_loc5`='你越痛苦我越興奮!', `MaleText_loc7`='¡Tu dolor me estimula!' WHERE `ID`=44132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상은 어느새 지옥이 되어버렸습니다, $n.', `MaleText_loc4`='这个世界已经毁灭了，$n。', `MaleText_loc5`='全世界都完了，$n。', `MaleText_loc7`='El mundo se ha ido al infierno, $n.' WHERE `ID`=44133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크가 없던 시절이 생각나는군요. 상상이 갑니까? 저 빌어먹을 오크가 없는 세상이!', `MaleText_loc4`='我还记得曾几何时，在这个世界上没有兽人。你能想象吗？没有那些该死的兽人！', `MaleText_loc5`='我記得以前還沒有獸人的時候。你能想像嗎?沒有該死的獸人!', `MaleText_loc7`='Recuerdo una época en la que no había orcos. ¿Te lo imaginas? ¡Sin un maldito orco!' WHERE `ID`=44134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 다시 평화가 찾아올지도 모르지요. 그때쯤이면 제 똥은 황금으로 변해 있을 겁니다.', `MaleText_loc4`='也许有一天我们能重享和平。也许我能在上厕所时拉出金子来。', `MaleText_loc5`='說不定哪天我們會有真正的和平。說不定連我都會拉黃金。', `MaleText_loc7`='Quizá algún día tengamos paz de nuevo. Y quizá algún día yo cague oro.' WHERE `ID`=44135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이번 일이 다 끝나면, 제가 술이라도 한 잔 사겠습니다.', `MaleText_loc4`='等这一切都结束之后，我要请你喝一杯，$n。', `MaleText_loc5`='等這一切結束之後，我會請你喝一杯，$n。', `MaleText_loc7`='Cuando todo esto pase, te invitaré a unos tragos, $n.' WHERE `ID`=44136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 얘기했었던가요? 불곰 중대의 일원이 된 것을 환영합니다, $n.', `MaleText_loc4`='要是我之前没对你说过，$n，欢迎来到B连。', `MaleText_loc5`='忘了剛剛有沒有跟你講過。$n，歡迎加入第二連隊。', `MaleText_loc7`='Si no te lo he comentado antes, $gbienvenido:bienvenida; a la Compañía Bravo, $n.' WHERE `ID`=44137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 그래도 꽤 괜찮은 사람입니다, $n. 돈만 긁어모으려 하는 스톰윈드 출신 양아치들과는 달라요.', `MaleText_loc4`='你很好，$n。不像暴风城里那些一无是处、只知敛财的政治家。', `MaleText_loc5`='你還算可以啦，$n。不像暴風城裡那些死要錢的混蛋政客。', `MaleText_loc7`='Vales la pena, $n. No como estos políticos incompetentes y avariciosos de Ventormenta.' WHERE `ID`=44138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기도 일단 정리를 마치면 재건을 시작할 수 있겠지요. 사람들이 이 요새를 불곰 중대에 기증할지도 모릅니다. 그러면 불곰 요새라고 이름을 붙이겠습니다!', `MaleText_loc4`='等我们把这里清理干净，也许我们会开始重建这地方。可能他们会把它交给B连。我们可以管它叫B连要塞！', `MaleText_loc5`='說不定等我們清乾淨這個地方以後，我們可以開始重建它。說不定他們還會把它交給第二連隊，然後我們就可以把它叫做:第二連隊堡壘!', `MaleText_loc7`='Después de que limpiemos este lugar, puedes que empecemos a reconstruirlo. A lo mejor se lo dan a la Compañía Bravo. ¡Lo llamaremos: Fortín Bravo!' WHERE `ID`=44139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 들지 않아... 일이 너무 쉽게 풀린 것 같아.', `MaleText_loc4`='我不喜欢这个……感觉太简单了。', `MaleText_loc5`='我不喜歡這樣...感覺太輕鬆了。', `MaleText_loc7`='No me gusta... Demasiado fácil.' WHERE `ID`=44140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='댄포스를 어디서 찾아냈는지 $n한테 얘기 들었어, 조니? 아무래도 오크들이 녀석에게 무슨 짓을 한 것 같아.', `MaleText_loc4`='$n告诉过你我们是怎么找到丹弗斯的吗，约翰尼？我想那群兽人也许对他做过不恰当的事。', `MaleText_loc5`='強尼，$n沒有告訴你我們是怎樣找到丹佛斯的嗎?我想獸人可能有不恰當地碰觸了他。', `MaleText_loc7`='¿Te dijo $n cómo encontramos a Danforth, Johnny? Creo que los orcos lo tocaron de forma inapropiada.' WHERE `ID`=44141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크라면 이제 지긋지긋해. 몽땅 해치워 버리면 스랄 녀석이 알아서 하겠지.', `MaleText_loc4`='我已经对兽人感到厌倦了。我们应该把他们全都杀死，然后让萨尔慢慢甄选。', `MaleText_loc5`='討厭獸人。我們得殺光他們，再讓索爾去幫他們收屍。', `MaleText_loc7`='Estoy $gcansado:cansada; de los orcos. Tenemos que matarlos a todos y que Thrall se las apañe.' WHERE `ID`=44142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구 내 딸 소식을 들은 사람 없나요? 달시?', `MaleText_loc4`='谁有我女儿达希的消息？', `MaleText_loc5`='誰有聽到我女朋友的消息?達希?', `MaleText_loc7`='¿Sabéis algo de Darcy? ¿Mi Darcy?' WHERE `ID`=44143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 일이 끝나면, 아이언포지로 갈 생각이야. 아이언포지에서 가장 맛있는 술독에 빠져 친절한 드워프 아가씨랑 연애라도 해봐야지.', `MaleText_loc4`='等我们结束这里的事情，我想我会前往铁炉堡。尝尝铁炉堡最富盛名的美酒，再见见那些友善的矮人姑娘。', `MaleText_loc5`='等這兒的事情結束了，我應該會跑一趟鐵爐堡，去喝他個幾大杯的鐵爐堡美酒，然後再找幾個親切矮人姑娘。', `MaleText_loc7`='Cuando terminemos aquí creo que iré a Forjaz. Me haré con unas cuantas pintas de la mejor cerveza de la ciudad y con algunas jóvenes enanas amistosas.' WHERE `ID`=44144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쏘기 딱 좋은 위치다! 탄환을 더 줘!', `MaleText_loc4`='射击视野良好！再来点弹药！', `MaleText_loc5`='從我這裡可以清楚的瞄準!給我更多彈藥!', `MaleText_loc7`='¡Lo tengo en la mira! ¡Denme más municiones!' WHERE `ID`=44145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었지! 탄환이 떨어지지 않게 해라!', `MaleText_loc4`='你也听到了！保持机枪的弹幕！', `MaleText_loc5`='你們都聽到了!把那把槍裝滿彈藥!', `MaleText_loc7`='¡Lo oyeron! ¡Que a esa arma no le falten municiones!' WHERE `ID`=44146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡Sí, señor!' WHERE `ID`=44147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 걸 두고 과녁이 풍부한 환경이라고 하는 거지!', `MaleText_loc4`='这才叫“目标不计其数”嘛！', `MaleText_loc5`='這才能稱為砲手的天堂嘛!', `MaleText_loc7`='¡A esto le llamo tener objetivos en bandeja!' WHERE `ID`=44148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포를 쏠 때는 부디 조심하십시오...', `MaleText_loc4`='发射那些炮弹要小心…', `MaleText_loc5`='射出那些砲彈時要小心...', `MaleText_loc7`='Disparen esos cartuchos con cuidado…' WHERE `ID`=44149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넵튤론의 부하들을 적으로 돌리면 안 됩니다!', `MaleText_loc4`='不能让耐普图隆的亡魂把我们当成敌人！', `MaleText_loc5`='不能讓奈普圖隆的亡魄把我們當成敵人!', `MaleText_loc7`='¡Que las ánimas de Neptulon no nos vean como enemigos!' WHERE `ID`=44150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 소용돌이로 가는 걸 막아라!', `MaleText_loc4`='别让那些纳迦靠近裂口！', `MaleText_loc5`='別讓那些納迦靠近坑洞!', `MaleText_loc7`='¡Alejen del cráter a esos nagas!' WHERE `ID`=44151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 물의 세계에 자리를 잡으면 절대 쫓아낼 수 없다!', `MaleText_loc4`='如果他们在水元素位面站住了脚，我们就麻烦了！', `MaleText_loc5`='如果他們在水之界域找到立足點，我們會無法把他們趕出去!', `MaleText_loc7`='¡Si se afianzan en ese llano de agua, nunca los sacaremos!' WHERE `ID`=44152;
