UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기폭 장치 조정...', `MaleText_loc4`='校准引信……', `MaleText_loc5`='校準導火線...', `MaleText_loc7`='Calibrando fusible…' WHERE `ID`=44154;
