UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포격 개시!', `MaleText_loc4`='开始射击！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Abran fuego!' WHERE `ID`=44156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='呜哈！', `MaleText_loc5`='喔耶!', `MaleText_loc7`='¡Yajuu!' WHERE `ID`=44157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 위대하신 넵튤론은 어디에 있소?!', `MaleText_loc4`='萨满，那个强大的耐普图隆在哪？！', `MaleText_loc5`='偉大的奈普圖隆到哪去了，薩滿?', `MaleText_loc7`='¡¿Dónde está Neptulon, chamán?!' WHERE `ID`=44158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 왜 그의 영역을 지켜 줘야 하오?', `MaleText_loc4`='为什么要我们守卫他的领土？', `MaleText_loc5`='為什麼我們卡在這裡替他防守他的領域?', `MaleText_loc7`='¿Por qué tenemos que proteger sus dominios?' WHERE `ID`=44159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령계의 군주란 순수한 혼돈으로 이루어진 존재입니다.', `MaleText_loc4`='元素位面的领主们都是纯粹的混沌存在，纳兹戈林。', `MaleText_loc5`='元素界域的領主們是純粹混沌的存在，納茲格寧姆。', `MaleText_loc7`='Los señores de los planos elementales son seres de caos puro, Nazgrim.' WHERE `ID`=44160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 그들의 행동을 예측할 수 없지요...', `MaleText_loc4`='没人能判断他们的动机……', `MaleText_loc5`='沒有人能察覺到他們的動機...', `MaleText_loc7`='Nadie comprende sus motivos…' WHERE `ID`=44162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 바다뱀에게 집 빼앗기기 싫으면 빨리 모습을 드러내는 게 좋을 텐데...', `MaleText_loc4`='呸！除非他想让他家里塞满这些纳迦，否则他最好赶紧出现……', `MaleText_loc5`='嘖!除非他想要他老家被這些納迦淹沒，否則他最好快點亮相...', `MaleText_loc7`='¡Bah! Si no quiere que su hogar sea arrasado por estas serpientes, que se muestre…' WHERE `ID`=44163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 저렇게 크지! 저게 대체 뭐야?', `MaleText_loc4`='看看那些玩意儿的大小！那是些什么东西？', `MaleText_loc5`='看看那些東西的尺寸!那些是什麼啊?', `MaleText_loc7`='¡Mira el tamaño de esas cosas! ¿Qué SON?' WHERE `ID`=44164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가가 고대 신의 하수인에게 도움을 청했군요.', `MaleText_loc4`='纳迦得到了上古之神奴仆的帮助。', `MaleText_loc5`='納迦找到了上古之神的爪牙幫忙。', `MaleText_loc7`='Los nagas tienen la ayuda de los esbirros del Dios Antiguo.' WHERE `ID`=44165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 모든 것을 파괴하는 일그러진 존재입니다.', `MaleText_loc4`='扭曲的怪物们一心要毁灭全部生灵。', `MaleText_loc5`='那些邪惡的東西想要毀滅所有的生物。', `MaleText_loc7`='Criaturas malditas que buscan la destrucción de todo ser vivo.' WHERE `ID`=44166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에, 에헤헤헤헤... 물어봐서 죄송해요...', `MaleText_loc4`='呃，抱歉，我不该问的……', `MaleText_loc5`='我不該問的...', `MaleText_loc7`='Por qué pregunté…' WHERE `ID`=44167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 척 보기에도 정령 수가 적군.', `MaleText_loc4`='那些元素完全寡不敌众啊。', `MaleText_loc5`='元素顯然已經寡不敵眾。', `MaleText_loc7`='Los elementales son muchos menos.' WHERE `ID`=44168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영 가망이 없어 보이는데...', `MaleText_loc4`='他们一点机会都没有……', `MaleText_loc5`='他們毫無勝算。', `MaleText_loc7`='No tienen chances…' WHERE `ID`=44169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들에게서 절망이 느껴집니다.', `MaleText_loc4`='我感觉到了绝望。', `MaleText_loc5`='我感覺他們走投無路了。', `MaleText_loc7`='Siento desesperación en ellas.' WHERE `ID`=44170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주지 않으면, 끝장입니다.', `MaleText_loc4`='没有援助，他们必败。', `MaleText_loc5`='沒有援軍的話，他們會失敗。', `MaleText_loc7`='Sin ayuda, fallarán.' WHERE `ID`=44171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불곰 중대, 다들 모였나...', `MaleText_loc4`='B连，全体出席并作为……', `MaleText_loc5`='第二連隊，全員到齊...', `MaleText_loc7`='La Compañía Bravo, todos presentes y listos...' WHERE `ID`=44172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들의 콩알만 한 머리로 이 정도 규모의 침략 계획을 세울 수 있다고 생각했는가?', `MaleText_loc4`='你真相信以兽人的脑子能制定出如此大规模的入侵计划？', `MaleText_loc5`='你真的相信獸人有那個腦袋發動這等規模的攻擊行動?', `MaleText_loc7`='¿En serio crees que los orcos tienen el cerebro necesario para planear una invasión de esta magnitud?' WHERE `ID`=44173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 상관없지. 그 질긴 목숨도 이제 끝이다. 너희는 스톰윈드로의 진군을 장식하기 위해 데스윙 님께 바치는 약소한 제물이 될 테니까!', `MaleText_loc4`='不要紧。你现在就要死了，作为在我们进军暴风城之时献给死亡之翼的卑微供品。', `MaleText_loc5`='無所謂。你馬上就要死了，在我們開始向暴風城進軍的時候當作獻給死亡之翼的一份小小祭禮。', `MaleText_loc7`='No importa. Ahora vas a morir, como una mísera ofrenda a Alamuerte al comienzo de nuestra marcha sobre Ventormenta.' WHERE `ID`=44174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 주인님의 분노를 맛봐라! 여기가 너희 무덤이 되리라!', `MaleText_loc4`='被主人的怒火吞没吧！快来受死！', `MaleText_loc5`='滋養主人的怒火!來受死吧!', `MaleText_loc7`='¡Alimenta la ira del maestro! ¡VEN Y MUERE!' WHERE `ID`=44175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희와 놀아주기도 이제 지겹구나!', `MaleText_loc4`='我对这些游戏感到厌烦了！', `MaleText_loc5`='我已厭倦了這些遊戲!', `MaleText_loc7`='¡Me estoy cansando de estos jueguecitos!' WHERE `ID`=44176;
