UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 싸우기보단 양조를 하고 싶습니다!$b$b운이 좋으면 둘 다 할 수 있겠죠? 네?', `MaleText_loc4`='我宁可去酿酒也不愿意打架！$B$B可要是走运的话，也许我两项工作都能胜任，呃？', `MaleText_loc5`='我寧可釀酒勝過打架!$B$B但是運氣好的話，說不定我兩者都可以兼顧?', `MaleText_loc7`='¡Preferiría estar fabricando cerveza en vez de luchando!$B$BPero con un poco de suerte podré hacer las dos cosas, ¿eh?' WHERE `ID`=44236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 하이잘로 가야 한다! 아직은 희망이 있어!', `MaleText_loc4`='趁一切还有转机，让我们快去海加尔吧！', `MaleText_loc5`='在我們還能改變戰果時趕快去海加爾吧!', `MaleText_loc7`='¡Vamos a Hyjal, que todavía podemos cambiar las cosas!' WHERE `ID`=44237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지 않다.', `MaleText_loc4`='那可不太好。', `MaleText_loc5`='那不好。', `MaleText_loc7`='Eso no e'' bueno.' WHERE `ID`=44238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅의 축복이 당신과 함께하길...', `FemaleText_loc4`='这片土地的祝福与你同在。', `FemaleText_loc5`='願大地祝福你。', `FemaleText_loc7`='Que la bendición de la tierra caiga sobre ti.' WHERE `ID`=44239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지는 대지의 세계일세. 데스윙이 처음 패배했을 때 피신한 곳도 바로 이곳이지.', `MaleText_loc4`='深岩之洲是大地的国度。死亡之翼在第一次被击败之后逃到了这里。', `MaleText_loc5`='地深之源是土之領域，當年死亡之翼初次被擊敗後就是撤退到此處躲藏。', `MaleText_loc7`='Infralar es el reino de la tierra. Aquí es donde se retiró Alamuerte cuando fue derrotado por primera vez.' WHERE `ID`=44240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙의 추종자들이 바로 이 사원 안에서 놈이 힘을 회복하는 것을 도왔네. 강력한 엘레멘티움 판을 데스윙의 피부에 덧씌웠지.', `MaleText_loc4`='他的追随者就是在这座神殿里侍奉他，为他恢复力量。坚固的源质盔甲被镶嵌到了他的躯壳上。', `MaleText_loc5`='他的追隨者協助他在這座神殿裡恢復力量，並且在他的身上安裝了強大而堅固的源質甲片。', `MaleText_loc7`='Sus seguidores le ayudaron a recuperar las fuerzas dentro de este templo. Le injertaron en la piel placas de poderoso elementium.' WHERE `ID`=44241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 아제로스로 돌아가면서 두 세계 사이에는 크나큰 균열이 생겼네. 이 균열이 바로 우리 세계를 위협하는 대격변을 초래한 것이지.', `MaleText_loc4`='死亡之翼重返艾泽拉斯时给两个世界留下了巨大的裂隙。这道裂口是造成大灾变的主要原因，威胁了我们世界的存亡。', `MaleText_loc5`='死亡之翼重返艾澤拉斯，在這兩個世界之間劃開了一道巨大的裂隙。而這道裂口就是差點毀掉我們土地的那場大災變的主因。', `MaleText_loc7`='El regreso de Alamuerte a Azeroth causó una gran falla entre los dos mundos. Esta brecha es la fuerza que ha provocado el Cataclismo que amenaza con destruir nuestras tierras.' WHERE `ID`=44242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님께서는 아제로스 쪽의 균열을 안정시키려고 온 힘을 다하고 계시네. 우리는 여기 심원의 영지 쪽 균열을 안정시키려 애쓰는 것이고.', `MaleText_loc4`='萨尔在艾泽拉斯一侧使用他的全部力量稳定着这道裂隙。我们也在这边尽力维持裂隙的稳定。', `MaleText_loc5`='索爾正在竭盡所能從艾澤拉斯那一側穩住這道裂隙，而我們這裡也是同樣在想辦法要使它安定下來。', `MaleText_loc7`='Thrall está utilizando todo su poder para estabilizar la falla del lado de Azeroth. Nosotros hacemos lo que podemos para estabilizarla de este lado.' WHERE `ID`=44243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙은 심원의 영지를 벗어나며 우리 세계에만 상처를 준 게 아닐세. 티탄이 만든 강력한 바위가 바로 이 방 안에 있었지만, 그때 조각나고 말았지. 바로 세계 기둥일세.', `MaleText_loc4`='死亡之翼离开这里的时候不仅仅伤害了我们的世界，在这个神殿里原本存放着的一块泰坦制造的魔法巨石也随之破碎了。', `MaleText_loc5`='死亡之翼的脫逃不只重創了我們的世界。這房間裡原本還有一塊由泰坦所創造的魔法石，叫做世界之柱，而它也在這場災變中破損了。', `MaleText_loc7`='La huida de Alamuerte no perjudicó tan solo a nuestro mundo. Antes de que la brecha la destruyera, esta sala solía guardar una poderosa piedra creada por los titanes. Se la conocía como el Pilar del Mundo.' WHERE `ID`=44244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름만 세계 기둥이 아니라네. 세계 기둥은 이 사원만 떠받치고 있었던 게 아니니까. 그것을 복원하지 않으면 심원의 영지가 아제로스 안으로 무너질 걸세. 양쪽 세계가 처참하게 함께 붕괴하는 것이지.', `MaleText_loc4`='世界之柱——可不止是个响亮的名字，它不仅承受着这座神殿的重量。如果它没有被复原，那么整个深岩之洲都向艾泽拉斯崩溃，这将会给两个世界都带来灭绝性的后果。', `MaleText_loc5`='它之所以叫「世界之柱」是有原因的，因為它支撐的不僅是這座神殿的重量而已，若是不盡快將它重建的話，整個地深之源將會崩塌壓進艾澤拉斯，對兩個世界造成難以估計的毀滅。', `MaleText_loc7`='No era tan solo un nombre, porque el Pilar del Mundo soportaba mucho más que el peso de este templo. Debe ser reconstruido o todo Infralar caerá sobre Azeroth con consecuencias desastrosas para ambos mundos.' WHERE `ID`=44245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 기둥이 조각나면서 조각 세 개의 행방이 묘연해졌네. 그 조각들을 되찾지 않으면 우리 세계는 파멸하고 말 걸세.', `MaleText_loc4`='世界之柱碎裂之后，有三块碎片遗失了。我们必须找到这些碎片，否则，我们的世界将迎来末日。', `MaleText_loc5`='世界之柱崩塌後有三塊碎片遺失，我們務必將它們尋回，否則我們的世界就完了。', `MaleText_loc7`='Los tres fragmentos se perdieron cuando el Pilar del mundo se partió. Debemos recuperarlos o nuestros mundos estarán perdidos.' WHERE `ID`=44246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 곰팡이 괴물들을 전초지에서 몰아내야 하네. 놈들은 너무 강력해!', `MaleText_loc4`='我们必须让那些真菌恶魔远离前线。它们太强大了！', `MaleText_loc5`='我們不能讓那些真菌懼獸靠近前線，它們太強大了!', `MaleText_loc7`='Debemos mantener a esos terrores fúngicos lejos del frente de batalla. ¡Son demasiado poderosos!' WHERE `ID`=44247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아바마마가 근처에 계시다. 난 알 수 있어! 적 방어선을 뚫고 아바마마를 구해야 한다!', `MaleText_loc4`='我父亲就在附近，我能感觉到！我们必须突破他们的防线，救出我的父亲！', `MaleText_loc5`='我父親就在附近，我知道!我們一定得衝破他們的防線，把他救出來!', `MaleText_loc7`='Mi padre está cerca, ¡lo sé! ¡Debemos atravesar sus defensas y rescatarlo!' WHERE `ID`=44248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈이 운명의 불타는 기둥을 시전하기 시작합니다!', `MaleText_loc4`='古加尔开始施放末日之烈焰轴心！', `MaleText_loc5`='丘加利開始施展毀滅火柱!', `MaleText_loc7`='¡Cho''gall comienza a lanzar Pilar llameante de fatalidad!' WHERE `ID`=44249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용돌이 근처에 잠수함을 대라!', `MaleText_loc4`='让我们尽量接近那个坑洞！', `MaleText_loc5`='盡可能讓我們降落在坑洞附近!', `MaleText_loc7`='¡Déjanos tan cerca del cráter como puedas!' WHERE `ID`=44250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샨드리스가 그녀의 활을 하늘로 들어 올립니다!', `FemaleText_loc4`='珊蒂斯弯弓对准了群星！', `FemaleText_loc5`='珊蒂斯朝群星高舉她的弓!', `FemaleText_loc7`='¡Shandris alza su arco hacia las estrellas!' WHERE `ID`=44251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 불타버려라, 이 비열한 악당들아!', `MaleText_loc4`='烧吧！烧吧，你们这群可怜虫！', `MaleText_loc5`='燒吧!燒吧，你們這些廢物!', `MaleText_loc7`='¡Arded! ¡Arded, sabandijas!' WHERE `ID`=44252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬이시여, 제 화살을 인도해 주소서!', `FemaleText_loc4`='艾露恩，指引我的箭矢！', `FemaleText_loc5`='伊露恩，指引我的箭!', `FemaleText_loc7`='¡Elune, guía mis flechas!' WHERE `ID`=44253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 고용하실 것이라면 제대로 찾아오신 겁니다.', `MaleText_loc4`='如果你想要骑乘狮鹫，那你就来对地方了。', `MaleText_loc5`='想雇個獅鷲獸?你來對地方了。', `MaleText_loc7`='Si quieres alquilar un grifo, has venido al lugar adecuado.' WHERE `ID`=44254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 파도의 주인이여... 너의 통치도 이젠 끝에 다다랐다!', `FemaleText_loc4`='波涛之王，你的统治已经到头了！', `FemaleText_loc5`='你的統治就要結束了，浪潮之王!', `FemaleText_loc7`='¡Tu reinado llega a su fin, Señor de las Olas!' WHERE `ID`=44255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 지나면, 너의 소중한 왕좌는 폐허가 될 것이다!', `FemaleText_loc4`='再过不久，你宝贵的王座就会成为一片废墟！', `FemaleText_loc5`='你寶貝的王座很快就會崩壞了!', `FemaleText_loc7`='¡Tu preccciosssso trono estará en ruinasss!' WHERE `ID`=44256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 머리는 우리 여왕님께서 장난감으로 삼으리라...', `FemaleText_loc4`='你那章鱼脑袋将成为献给女王的战利品……', `FemaleText_loc5`='你長了觸鬚的頭，會是女王最新的戰利品...', `FemaleText_loc7`='Tu cabeza tentaculada, un mero trofeo para mi reina…' WHERE `ID`=44257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하하하... 넌 지금 내 영지에 들어와 있다!', `MaleText_loc4`='你们在我的国度里，毒蛇！', `MaleText_loc5`='你現在是在我的領域，毒蛇!', `MaleText_loc7`='¡Ahora estás en MI reino, serpiente!' WHERE `ID`=44258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그따위 공격에 그냥 당할 줄 알았더냐?', `MaleText_loc4`='你以为我对这种袭击毫无防备？', `MaleText_loc5`='你以為我對這樣的襲擊會毫無防備?', `MaleText_loc7`='¿Creíste que no estaría preparado para tal asalto?' WHERE `ID`=44259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 파멸이 가까이 있다. 손 뻗으면 닿을 곳에...', `MaleText_loc4`='净化你们的方法就近在咫尺…', `MaleText_loc5`='你們要的淨化方法已經垂手可得...', `MaleText_loc7`='El método de tu purificación está a la mano…' WHERE `ID`=44260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동시에 영원히 닿을 수 없는 곳에. 으하하하...', `MaleText_loc4`='……但你们却永远找不到。', `MaleText_loc5`='...但是你們永遠也無法得到。', `MaleText_loc7`='...y al mismo tiempo inalcanzable.' WHERE `ID`=44261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으... 샅샅이 뒤져라, 나의 군대여! 바다사냥꾼의 덫을 찾아내라!', `FemaleText_loc4`='搜查这个地方，我的军团！把猎潮者的陷阱找出来！', `FemaleText_loc5`='我的軍團，清洗這個地方!找出獵潮者的陷阱!', `FemaleText_loc7`='¡Busquen, mis legiones! ¡Busquen la trampa de Cazamareas!' WHERE `ID`=44262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 두려움을 모르는 내 부관들이로군.', `MaleText_loc4`='啊，我无畏的协助者，对吧？', `MaleText_loc5`='啊 - 我無所畏懼的助手們，對吧。', `MaleText_loc7`='Aah... Mis temerarios asistentes, ¿no?' WHERE `ID`=44263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 여기까지 오다니 괜한 짓을 했다.', `MaleText_loc4`='你们也许会后悔来到这里。', `MaleText_loc5`='你們可能會後悔來到這裡。', `MaleText_loc7`='Tal vez lamenten su presencia aquí.' WHERE `ID`=44264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 물을 정화하면, 저 역겨운 것들은 혼란에 빠져 우왕좌왕할 것이다! 보아라!', `MaleText_loc4`='在我净化这片水域时，那些污秽的仆从定会拼命阻挠我。小心！', `MaleText_loc5`='等我淨化這些水，骯髒的僕人們一定會被驚動。小心點!', `MaleText_loc7`='Al purificar estas aguas, los sirvientes de la mugre se agitarán. ¡Cuidado!' WHERE `ID`=44265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 역겨운 것들이 나를 더럽힌다!', `MaleText_loc4`='啊……他们的污秽玷污了我！', `MaleText_loc5`='唉呀...我受不了他們的臭味!', `MaleText_loc7`='Puaj...  ¡Su mugre me mancha!

' WHERE `ID`=44266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이... 빠져나간다...', `MaleText_loc4`='我开始……厌烦了……', `MaleText_loc5`='我開始...無聊了...', `MaleText_loc7`='Estoy... cansado.

' WHERE `ID`=44267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들! 도움이 좀 돼 봐라...', `MaleText_loc4`='蠢货！派上点儿用场……', `MaleText_loc5`='笨蛋!能不能幫上忙...', `MaleText_loc7`='¡Imbéciles! Sirvan para algo…

' WHERE `ID`=44268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조바심 내지 마라. 물이 거의 정화됐다.', `MaleText_loc4`='耐心点，客人们。这片水域快被净化了。', `MaleText_loc5`='有點耐心，客人們。這些水已經快要淨化完了。', `MaleText_loc7`='Paciencia, invitados. Las aguas ya casi están limpias.

' WHERE `ID`=44269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수가 돌아왔다! 놈이 물을 오염시키게 두면 안 된다!', `MaleText_loc4`='那头怪兽回来了！绝对不能让它污染我的水域！', `MaleText_loc5`='那頭怪物回來了!不能讓牠污染我的水!', `MaleText_loc7`='¡La bestia ha vuelto! ¡Que no contamine mis aguas!

' WHERE `ID`=44270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순수한 물의 힘을 느껴 보아라!', `MaleText_loc4`='见证这纯水之力吧！', `MaleText_loc5`='看看純淨之水的力量吧!', `MaleText_loc7`='¡Contemplen el poder del agua pura!


' WHERE `ID`=44271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 모두 정화되었다! 그 힘을 마셔라!', `MaleText_loc4`='我的水域净化了！汲取它的力量吧！', `MaleText_loc5`='我的水已經淨化了!喝下它們的力量吧!', `MaleText_loc7`='¡Mis aguas están limpias! ¡Beban de su poder!
' WHERE `ID`=44272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 너희 족속은 믿을 수가 없어.', `MaleText_loc4`='你们这种人……不可信任。', `MaleText_loc5`='你們這些種族...是不能信任的。', `MaleText_loc7`='No se puede... confiar... en su especie.




' WHERE `ID`=44273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 내 영지에 있을 자격이 없다...', `MaleText_loc4`='我的国度容不下你……', `MaleText_loc5`='你們不配進入我的領域...', `MaleText_loc7`='No merecen mi dominio…



' WHERE `ID`=44274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 따위를 신경 쓰다니... 실수였다...', `MaleText_loc4`='关注你们……简直浪费精力……', `MaleText_loc5`='我不該...浪費注意力在你們身上...', `MaleText_loc7`='Desperdicié mi atención... en ustedes…


' WHERE `ID`=44275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 내 영지에서 역겨움을 모조리 씻어냈구나.', `MaleText_loc4`='终于把污秽从我的国度中清除了。', `MaleText_loc5`='我領域中的邪惡腐臭終於被清除了。', `MaleText_loc7`='Mi reino ha sido limpiado de la vil mugre.

' WHERE `ID`=44276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너희는 물러가도 좋다.', `MaleText_loc4`='你们可以自行离开了。', `MaleText_loc5`='你們隨時可以離開。', `MaleText_loc7`='Pueden partir cuando gusten.' WHERE `ID`=44277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요! 얼마나 더 견딜 수 있을지 모를 상황이었어요.', `FemaleText_loc4`='谢谢！我不知道我们还能活多久。', `FemaleText_loc5`='謝謝你!不然我實在不知道我們還能夠撐多久。', `FemaleText_loc7`='¡Gracias! No sé cuánto tiempo más podríamos haber sobrevivido.' WHERE `ID`=44278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 우리가 제 마법을 봉쇄하고 있었거든요.', `FemaleText_loc4`='这个笼子困住了我的魔法。', `FemaleText_loc5`='那個籠牢抑制住了我的魔法。', `FemaleText_loc7`='Esa jaula estaba reprimiendo mi magia.' WHERE `ID`=44279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜찮으시면, 우리 먼저 반란군 야영지로 순간이동하겠습니다. 감사는 나중에 드리죠.', `FemaleText_loc4`='如果你不介意，我要把我们传送回反抗军营地了。我们会稍后再向你表达我们的谢意。', `FemaleText_loc5`='請見諒，我要先把我們傳送回反抗軍營地。稍後再親自向你致謝。', `FemaleText_loc7`='Si no te importa, voy a teletransportarnos de vuelta al Asentamiento Rebelde. Te daremos las gracias en persona más adelante.' WHERE `ID`=44280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모르고르! 반쯤 악마가 된 쓰레기 같은 네 부하들과 아웃랜드에 머물렀어야지. 여기에 너의 자리는 없다.', `FemaleText_loc4`='莫格霍尔！你应该和你那些恶魔混血渣滓一起死在外域！这儿没有你的容身之处。', `FemaleText_loc5`='莫格!你應該和你其他的半惡魔雜碎一起待在外域。你沒有出現在這的權力。', `FemaleText_loc7`='¡Mor''ghor! Debiste quedarte en Terrallende con el resto de tus semidemonios. No perteneces a este lugar.' WHERE `ID`=44281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호.', `MaleText_loc4`='喔，嚯。', `MaleText_loc5`='呀呼。', `MaleText_loc7`='Yuju.' WHERE `ID`=44282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 자유다! 이 자유의 달콤함이여!', `MaleText_loc4`='自由！甜美无比的自由！', `MaleText_loc5`='自由!自由萬歲!', `MaleText_loc7`='¡Libertad! ¡Dulce, dulce libertad!' WHERE `ID`=44283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날카로운 전투의 외침이 전장에 메아리칩니다!', `FemaleText_loc4`='震耳欲聋的战吼在要塞中回荡！', `FemaleText_loc5`='一聲響亮的戰吼迴盪厄運之槌!', `FemaleText_loc7`='¡Un grito de guerra penetrante resuena por La Masacre!' WHERE `ID`=44284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 너무 강하다! 후퇴하라!', `FemaleText_loc4`='他太强了！撤退！', `FemaleText_loc5`='他太強了!撤退!', `FemaleText_loc7`='¡Es demasiado fuerte! ¡Retirada!' WHERE `ID`=44285;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 우리를 어디로 데려가든, 우리는 당당히 고개를 들고 우리의 피를 순수하게 지킬 것이다. 널 쓰러뜨려 속이 시원하군. 오늘 용아귀 부족에게 새로운 날이 열렸다.', `FemaleText_loc4`='无论带往何方，我们都会昂着头，维持血脉的纯净。总算摆脱你了，莫格霍尔。今天就是龙喉氏族的新生黎明。', `FemaleText_loc5`='不管部落帶我們去哪，我們都將昂首而立並保持血統的純正。終於甩掉莫格這個包袱。今天就是龍喉的新生之日!', `FemaleText_loc7`='Adonde nos lleve la Horda, mantendremos la frente en alto y la sangre pura. Buena suerte, Mor''ghor. Un nuevo Faucedraco comienza hoy.' WHERE `ID`=44286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잴라... 멍청한 배신자 같으니... 호드에게 영혼을 팔아넘겼나? 너와 내가 무엇이 그리 다르냐? 그래, 헬스크림 편에 붙어 보아라. 너희가 어찌 될지 두고 보자.', `MaleText_loc4`='扎伊拉……愚蠢的叛徒……你把灵魂出卖给了部落？你和我有什么区别？去追随地狱咆哮吧，看他能带你们走向何方。', `MaleText_loc5`='札伊拉...愚蠢的叛徒...妳將妳的靈魂賣給了部落?妳跟我有什麼不同?讓妳的人跟隨地獄吼，看他能帶你們走多遠。', `MaleText_loc7`='Zaela... traidora... ¿Has vendido tu alma a la Horda? ¿Somos tan diferentes? Prueba tu suerte con Grito Infernal. A ver a dónde te lleva.' WHERE `ID`=44287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공이야. 단단히 붙잡게, 지터스.', `MaleText_loc4`='起作用了。用力抓住他，基特斯。', `MaleText_loc5`='有效了。把他抓好，基特斯。', `MaleText_loc7`='Está funcionando. Sujétalo, Alterio.' WHERE `ID`=44288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저는 못해요...', `MaleText_loc4`='我……我不能……', `MaleText_loc5`='我...我沒辦法...', `MaleText_loc7`='No... No puedo...' WHERE `ID`=44289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장, 지터스! 단단히 잡으라고!', `MaleText_loc4`='该死的，基特斯，我说了，抓住！', `MaleText_loc5`='該死，基特斯，我說抓好!', `MaleText_loc7`='¡Maldita sea, Alterio! ¡He dicho que lo SUJETES!' WHERE `ID`=44290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지터스...', `MaleText_loc4`='基特斯……', `MaleText_loc5`='基特斯...', `MaleText_loc7`='Alterio...' WHERE `ID`=44291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지터스!', `MaleText_loc4`='基特斯！', `MaleText_loc5`='基特斯!', `MaleText_loc7`='¡ALTERIO!' WHERE `ID`=44292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 기억이 나는군... 이게 모두 네 탓이야!', `MaleText_loc4`='我记起来了……这全都是你的错！', `MaleText_loc5`='我想起來了...這全都是你的錯!', `MaleText_loc7`='Ya me acuerdo... ¡Es todo culpa tuya!' WHERE `ID`=44293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 그늘숲에 늑대인간을 불러들였어! 네가 암흑 기수들을 내 농장에 데려왔고, 내 가족이 살해되는 동안 숨어만 있었다고!', `MaleText_loc4`='你把狼人带到了暮色森林！你将黑暗骑士引到了我的农场，任由他们杀死我的家人，你却躲了起来！', `MaleText_loc5`='是你把狼人帶來暮色森林!是你帶黑騎兵到我的農場，然後在他們屠殺我全家的時候自己躲起來!', `MaleText_loc7`='¡Tú trajiste a los huargen al Bosque del Ocaso! ¡Tú condujiste a los jinetes oscuros a mi granja, y te ocultaste mientras asesinaban a mi familia!' WHERE `ID`=44294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 인생이 이 꼴이 된 것도 모두 빌어먹을 네놈의 잘못이야! 죽여버리겠어!', `MaleText_loc4`='我生命中每一道痛苦的伤痕都是你造成的！我应该杀掉你！', `MaleText_loc5`='我人生每一分每一毫的痛苦通通都是你該死的錯!我該殺了你才對!', `MaleText_loc7`='¡Cada momento de sufrimiento de mi vida ES POR TU MALDITA CULPA! ¡DEBERÍA MATARTE!' WHERE `ID`=44295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 이제 그를 놓아줘야 자네가 짐승이 아닌 존재라는 사실을 증명할 수 있네, 내 친구여.', `MaleText_loc4`='如果你要证明自己和那些野兽不同，就必须放他走，我的朋友。', `MaleText_loc5`='朋友，放走他才是唯一能區分你現在是人是獸的關鍵。', `MaleText_loc7`='Dejarle vivir es lo único que te va a separar de las bestias, amigo.' WHERE `ID`=44296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지터스, 네가 갚아줘야 할 빚이 아주 많아. 이렇게 쉽게 끝장을 내 주지는 않겠어.', `MaleText_loc4`='基特斯，你有许多东西需要补偿。我不会轻易放过你的。', `MaleText_loc5`='你要彌補的東西可多了，基特斯，我不會這麼簡單就放過你。', `MaleText_loc7`='Tienes mucho que expiar, Alterio. No voy a dejar que te libres.' WHERE `ID`=44297;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정한 힘을 보여주마!', `FemaleText_loc4`='我要让你看看什么是真正的力量！', `FemaleText_loc5`='讓你見識真正的力量!', `FemaleText_loc7`='¡Te enseñaré lo que es el poder de verdad!' WHERE `ID`=44298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올한이 자신의 힘을 집중합니다!', `FemaleText_loc4`='奥哈恩凝聚了她的力量！', `FemaleText_loc5`='奧赫集中她的力量!', `FemaleText_loc7`='¡Orhan concentra su poder!' WHERE `ID`=44299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작하지...', `MaleText_loc4`='开始了……', `MaleText_loc5`='開始了...', `MaleText_loc7`='Allá vamos...' WHERE `ID`=44300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌라나르에 오신 것을 환영해요, $c님. 요리법이나 기본 요리재료가 필요하면 언제든지 말씀해주세요.', `FemaleText_loc4`='欢迎来到多兰纳尔，$c。如果你需要菜谱或者基础的烹调材料，就请来找我。', `FemaleText_loc5`='歡迎來到多蘭納爾，$c。若是需要任何食譜或食材，敬請告訴我。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a Dolanaar, $c. Avísame si necesitas recetas o ingredientes básicos de cocina.' WHERE `ID`=44301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 그럼 이걸 여기에 넣고...', `MaleText_loc4`='好了，我们把这个加在这里……', `MaleText_loc5`='好吧，我們把這個加進去...', `MaleText_loc7`='Vale, añadimos esto...' WHERE `ID`=44302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원심분리하면...', `MaleText_loc4`='离心分离……', `MaleText_loc5`='做點離心處理...', `MaleText_loc7`='Centrifugamos...' WHERE `ID`=44303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공입니다! 이걸 보십시오!', `MaleText_loc4`='好了！看看这个！', `MaleText_loc5`='耶!看看這個!', `MaleText_loc7`='¡Bingo! ¡Mira esto!' WHERE `ID`=44304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕 바위용이 항복의 표시로 머리를 굽힙니다.', `MaleText_loc4`='石龙主母低下头表示投降。', `MaleText_loc5`='石龍育母低頭降服。', `MaleText_loc7`='La madre de linaje de dragones pétreos inclina la cabeza en señal de rendición.' WHERE `ID`=44305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먹을 걸 찾으시는 게 아니었으면 좋겠네요, $c님.', `FemaleText_loc4`='希望你不是在找东西吃，$c。', `FemaleText_loc5`='我希望你不是在找什麼吃的，$c。', `FemaleText_loc7`='Espero que no estuvieras buscando algo para comer, $c.' WHERE `ID`=44306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바보 같은 놀음을 끝내 주지!', `MaleText_loc4`='停止你的愚行！', `MaleText_loc5`='我已經受夠了!', `MaleText_loc7`='¡Basta de tonterías!' WHERE `ID`=44307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 상대하겠다!', `MaleText_loc4`='我们会解决他们！', `MaleText_loc5`='我們會解決他們!', `MaleText_loc7`='¡Nos encargaremos!' WHERE `ID`=44308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 또 뵙네요.', `FemaleText_loc4`='再次问好。', `FemaleText_loc5`='又見面了。', `FemaleText_loc7`='Hola de nuevo.' WHERE `ID`=44309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부르셨나요?', `FemaleText_loc4`='你找我？', `FemaleText_loc5`='你找我?', `FemaleText_loc7`='¿Has llamado?' WHERE `ID`=44310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 도와드릴까요?', `FemaleText_loc4`='需要什么？', `FemaleText_loc5`='需要什麼嗎?', `FemaleText_loc7`='¿Necesitas algo?' WHERE `ID`=44311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕 바위용이 다가옵니다.', `MaleText_loc4`='石龙主母靠近了。', `MaleText_loc5`='石龍育母接近了。', `MaleText_loc7`='La madre de linaje de dragones pétreos se acerca.' WHERE `ID`=44312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 살아 계시오! 해변에서 그분을 찾아냈소. 어서 나오시오! 이 마을은 우리 것이오!', `MaleText_loc4`='$n！酋长他还活着——他在海岸那边被救了。快出来。这座城镇一定是我们的了！', `MaleText_loc5`='$n!大酋長!他還活著!他在海岸獲救了。來外面，快點!城鎮是我們的了!', `MaleText_loc7`='¡El Jefe de Guerra! ¡Está vivo! Lo rescataron en la costa. ¡Salgan, rápido! ¡El pueblo es nuestro!' WHERE `ID`=44313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림 님, 저는 용아귀 부족의 잴라라고 합니다. 당신의 사람들이 우리를 압제에서 해방해 주었습니다. 우리는 당신의 도구입니다. 용아귀 부족은 기꺼이 당신의 명을 따르겠습니다. 호드를 위하여!', `FemaleText_loc4`='地狱咆哮，我是龙喉氏族的扎伊拉。你的人民使我们从暴君的手中重获自由。我们是你的武器。龙喉氏族之力听你号令。为了部落！', `FemaleText_loc5`='地獄吼，我是龍喉的札伊拉。你的人民將我們由暴權中解放。我們歸屬於你。龍喉的力量將在你的命令下綻放。為了部落!', `FemaleText_loc7`='Grito Infernal, soy Zaela de los Faucedracos. Tu gente ha liberado a la mía de la tiranía. Somos sus instrumentos. La fuerza de los Faucedracos  es suya. ¡Por la Horda!' WHERE `ID`=44314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작할 준비가 되면 한결같은 테라스와 이야기하십시오.', `MaleText_loc4`='当你准备开始时就去找坚定者特尔拉斯对话。', `MaleText_loc5`='等你準備好要開始的時候就去通知穩定的特拉斯。', `MaleText_loc7`='Habla con Terrath el Firme cuando estés $glisto:lista; para empezar.' WHERE `ID`=44315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하하! 물론 난 멀쩡하다! 황혼의 용 따위에게 내가 쓰러질 것 같은가?', `MaleText_loc4`='是的，我还活着！没有暮光龙能击败我。', `MaleText_loc5`='沒錯，我活著!沒有任何一隻暮光龍能與我抗衡。', `MaleText_loc7`='¡Sí, estoy vivo! Ningún Dragón Crepuscular detendrá a este orco.' WHERE `ID`=44316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거기 있구나. 용아귀 부족의 여전사여! 어서, 가까이 오라.', `MaleText_loc4`='啊，是龙喉氏族的女武士。让我好好看看你的脸。', `MaleText_loc5`='啊，她在那。龍喉的戰鬥侍女。讓我看看你的臉。', `MaleText_loc7`='Ah, ahí está. La doncella de batalla del Faucedraco. Déjame ver tu rostro.' WHERE `ID`=44317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피와 영광을, 영웅이여! 호드는 그대를 환영한다. 그대의 부족은 시험에 들 것이다. 우리와 함께 황혼의 망치단 잔당을 쓸어내고 이 해안가를 완전히 장악해야 하니까. 하지만... 먼저 끝낼 일이 있다.', `MaleText_loc4`='鲜血与荣耀，英雄。部落欢迎你。你们的能力将在消灭暮光之锤，夺取这片海岸的战争中受到考验。但首先……还有些事情要处理。', `MaleText_loc5`='鮮血與榮耀，英雄。部落歡迎你們。你的人民將受到考驗，我們將抹消暮光之錘並奪取這個偏遠的海岸。但首先...有事情要先處理。', `MaleText_loc7`='Sangre y honor, héroe. La Horda te da la bienvenida. Tu gente será puesta a prueba en la aniquilación del Martillo Crepuscular y la reclamación de esta costa distante. Pero primero... los asuntos pendientes.' WHERE `ID`=44318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 덤벼라! *킁킁* $r의 역겨운 냄새가 여기까지 나는군.', `MaleText_loc4`='来吧！*哼哼*我在这里就能闻到你的$r臭气。', `MaleText_loc5`='出來面對我!*吸氣*我在這兒就聞得到你的$r臭味了。', `MaleText_loc7`='¡Ven y enfréntate a mí! *bufido* Puedo oler tu peste de $r desde aquí.' WHERE `ID`=44319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤나 인상적이었다만...', `MaleText_loc4`='令人印象深刻……', `MaleText_loc5`='令人印象深刻的表現...', `MaleText_loc7`='Qué impresionante...' WHERE `ID`=44320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 여기서 끝이다.', `MaleText_loc4`='……事已至此。', `MaleText_loc5`='...能來到這裡。', `MaleText_loc7`='...haber llegado hasta aquí.' WHERE `ID`=44321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 진정한 힘을 보여주지...', `MaleText_loc4`='现在，见证真正的力量吧！', `MaleText_loc5`='現在，見證真正的力量...', `MaleText_loc7`='Ahora, contemplen el poder…' WHERE `ID`=44322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소의 분노를 느껴 봐라!', `MaleText_loc4`='……感受元素的愤怒！', `MaleText_loc5`='...元素的憤怒!', `MaleText_loc7`='¡...la furia de los elementos!' WHERE `ID`=44323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n? 왜 이제야 오느냐. 무슨 일이 있었더냐? 이건 아바마마의 목숨이 걸린 일이다!', `MaleText_loc4`='$n？你早就该来了。是什么拖住了你？我的父亲正生命垂危！', `MaleText_loc5`='$n?你總算來了。怎麼會這麼慢?我父親的生命有危險!', `MaleText_loc7`='¿$n? Ya era hora de que vinieras. ¿Por qué te has retrasado? ¡La vida de mi padre corre peligro!' WHERE `ID`=44324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잡았다! 내가 바깥일을 하는 동안 오잉키 씨가 내 뒤처리를 할 수 있도록 시켜야겠어.', `FemaleText_loc4`='我决定了！这次外出冒险时，我要让呼噜先生帮我拉怪。', `FemaleText_loc5`='我成功了!我得叫豬豬先生在我出去冒險的時候幫忙看著我。', `FemaleText_loc7`='¡Lo he conseguido! Tengo que pedirle a Gruñiditos que me proteja mientras me voy de aventuras.' WHERE `ID`=44325;
