UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 제 애완동물인 오잉키 씨를 데리고 나가고 싶어요!', `FemaleText_loc4`='嘿，你好啊。我想要领出我的宠物——呼噜先生！', `FemaleText_loc5`='嗨，你好，我想要把我的寵物豬豬先生帶出來，求求你!', `FemaleText_loc7`='¡Oye, me gustaría sacar a mi mascota Gruñiditos, por favor!' WHERE `ID`=44327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오잉키 씨! 너무너무 불쌍한 오잉키 씨...', `FemaleText_loc4`='呼噜先生！可怜的，可怜的呼噜先生……', `FemaleText_loc5`='豬豬先生!豬豬先生，好可憐，好可憐...', `FemaleText_loc7`='¡Gruñiditos! Pobre, pobre Gruñiditos...' WHERE `ID`=44328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오잉키 씨! 내게 돌아와요 오잉키 씨!', `FemaleText_loc4`='呼噜先生！！回到我这里来，呼噜先生！', `FemaleText_loc5`='豬豬先生!!回來啊，豬豬先生!', `FemaleText_loc7`='¡¡Gruñiditos!! ¡Vuelve a mí, Gruñiditos!' WHERE `ID`=44329;
