UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아... 오잉키 씨가 도망쳤어요! 커다랗고 매력적인 친구였는데, 여기에 우리랑 같이 있다가 방금 없어졌어요. 놓쳐서 미안해요.', `MaleText_loc4`='对了……他逃走了！他真是个又肥又多汁的家伙，但他刚从我们这儿逃走了。真遗憾。', `MaleText_loc5`='對...他跑走了!他又大又肥，而且他才剛剛從我們這裡跑走。我好難過。', `MaleText_loc7`='¡Eso! ¡Se ha escapado! Es un chico grande y jugoso y se nos acaba de escapar. Lo siento, señorita.' WHERE `ID`=44331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버논이 노릇노릇하게 구워지는 돼지를 보지 못하도록 감추며 애써 주위를 둘러봅니다.', `MaleText_loc4`='维尔隆紧张地看着周围，努力不去看烤肉架上的那头猪。', `MaleText_loc5`='沃農緊張地左顧右盼，目光刻意避開了烤架上的豬。', `MaleText_loc7`='Vernon mira a su alrededor, nervioso. Se cuida mucho de mirar al cerdo del espetón.' WHERE `ID`=44332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='록타르 오가르! 이 젊은 $r $c|1이;가; 에체야키를 제압했다! 이자의 공적으로 호드의 강대함을 대신하리라!', `FemaleText_loc4`='Lok-tar ogar！这个年轻的$r$c战胜了埃其亚基。$g他:她;的行动显示了新部落的力量！', `FemaleText_loc5`='為了部落的榮耀!這位年輕的$r$c擊敗了埃其亞基，$g他的:她的;行動展現了我們新部落的力量!', `FemaleText_loc7`='¡Lok''tar ogar! $gEste:Esta; joven $r $c ha dominado al gran Echeyakee. ¡Que sus acciones sean una prueba del poder de la nueva Horda!' WHERE `ID`=44333;
