UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 길니아스 전투에 참전할 만큼 강하지 않습니다. 더욱 많은 경험을 쌓아 다시 돌아오십시오.', `MaleText_loc4`='你的能力还不足以参加吉尔尼斯之战。当你的经验更丰富之后再回来吧。', `MaleText_loc5`='你的等級還不足以參加吉爾尼斯之戰的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no tienes la fuerza necesaria para entrar en La Batalla por Gilneas. Vuelve cuando hayas ganado más experiencia.', `FemaleText_loc1`='아직 길니아스 전투에 참전할 만큼 강하지 않습니다. 더욱 많은 경험을 쌓아 다시 돌아오십시오.', `FemaleText_loc4`='你的能力还不足以参加吉尔尼斯之战。当你的经验更丰富之后再回来吧。', `FemaleText_loc5`='你的等級還不足以參加吉爾尼斯之戰的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no tienes la fuerza necesaria para entrar en La Batalla por Gilneas. Vuelve cuando hayas ganado más experiencia.' WHERE `ID`=44340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 울창한 밀림. 오랜만에 마을 밖으로 나오니 참 좋군, 안 그래?', `MaleText_loc4`='啊，丛林。知道吗，能够偶尔离开城市真是一件好事情。', `MaleText_loc5`='啊，叢林。你知道嗎，偶爾離開一下城鎮也是不錯的?', `MaleText_loc7`='Ah, la jungla. A veces viene bien salir un poco de la ciudad, ¿no crees?' WHERE `ID`=44341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아직 쌍둥이 봉우리에서 싸울 수 있을 만큼 강하지 못합니다. 좀 더 경험을 쌓은 후에 다시 오십시오.', `MaleText_loc4`='你的能力还不足以参加双子峰的战斗。当你的经验更丰富之后再回来吧。', `MaleText_loc5`='你的等級還不足以參加雙子峰的戰鬥。等你獲得更多經驗的時候再回來。', `MaleText_loc7`='Todavía no eres lo bastante fuerte para luchar en las Cumbres Gemelas. Vuelve cuando hayas ganado más experiencia.', `FemaleText_loc1`='당신은 아직 쌍둥이 봉우리에서 싸울 수 있을 만큼 강하지 못합니다. 좀 더 경험을 쌓은 후에 다시 오십시오.', `FemaleText_loc4`='你的能力还不足以参加双子峰的战斗。当你的经验更丰富之后再回来吧。', `FemaleText_loc5`='你的等級還不足以參加雙子峰的戰鬥。等你獲得更多經驗的時候再回來。', `FemaleText_loc7`='Todavía no eres lo bastante fuerte para luchar en las Cumbres Gemelas. Vuelve cuando hayas ganado más experiencia.' WHERE `ID`=44342;
