UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이 거인과 바위 트로그들 머리 위로 날아가는 게 좋을 거야. 이들 사이로 낮게 날아서는 안 되네.', `MaleText_loc4`='$n，你要从这些巨人和石腭怪的头顶上飞过去。不要试图从他们中间穿过去。', `MaleText_loc5`='$n，你最好是飛過這些巨人和岩石穴居怪，別想從他們中間騎過去。', `MaleText_loc7`='$n, vuela sobre aquellos gigantes y troggs de piedra. No intentes cabalgar entre ellos.' WHERE `ID`=44350;
