UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 원소를 모욕했다. 우리가 네놈들의 비참한 삶을 끝장낸대도 할 말이 없을 것이다!', `MaleText_loc4`='你让元素蒙羞。小心一点，否则你可就要小命不保了！', `MaleText_loc5`='你們讓元素為之蒙羞。不要讓我們有藉口結束你們卑微的性命!', `MaleText_loc7`='Son una deshonra para los elementos. ¡No nos den una excusa para acabar con sus patéticas vidas!', `FemaleText_loc1`='너희는 원소를 모욕했다. 우리가 네놈들의 비참한 삶을 끝장낸대도 할 말이 없을 것이다!', `FemaleText_loc4`='你让元素蒙羞。小心一点，否则你可就要小命不保了！', `FemaleText_loc5`='你們讓元素為之蒙羞。不要讓我們有藉口結束你們卑微的性命!', `FemaleText_loc7`='Son una deshonra para los elementos. ¡No nos den una excusa para acabar con sus patéticas vidas!' WHERE `ID`=44362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 군주는 당신이 견디려고 하는 고통을 매 순간 느끼게 될 겁니다.', `MaleText_loc4`='你们的主人会感觉到你们所经受的每一点痛苦。', `MaleText_loc5`='你們的領主將會完全感受到你即將承受的痛苦。', `MaleText_loc7`='Tu señor sentirá cada segundo del dolor que estás a punto de sufrir.' WHERE `ID`=44363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽으면 죽었지 살아서 잡히진 않을 것이다!', `MaleText_loc4`='别想活着捉住我！', `MaleText_loc5`='你永遠無法活捉我!', `MaleText_loc7`='¡Nunca me cogerás vivo!' WHERE `ID`=44364;
