UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음이 있는 자들은 그분을 섬길 것이다! 으아아!!', `MaleText_loc4`='忠诚的信徒将侍奉在他身边！啊！！！', `MaleText_loc5`='忠誠者會在「他」的身邊服侍!咿呀呀呀呀!!!', `MaleText_loc7`='¡Los fieles servirán a su lado! ¡¡Aaaaagh!!' WHERE `ID`=44366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 감옥도 날 가둘 순 없다!!', `MaleText_loc4`='任何牢狱都困不住我！！', `MaleText_loc5`='沒有牢房關得住我!!', `MaleText_loc7`='¡Ninguna prisión puede retenerme!' WHERE `ID`=44367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 $n 맞지? 가즈로가 자네를 강 상류로 데려다 주라고 부탁했었어! 갈 준비가 되면 올라타라고!', `MaleText_loc4`='你是$n，对吗？加兹鲁维让我带你到这条河上游去！准备好出发以后就跳进来吧。', `MaleText_loc5`='你是$n沒錯吧?加茲魯維叫我送你到河的上游!準備好要出發就跳上來吧。', `MaleText_loc7`='Eres $n, ¿verdad? Gazlowe me ha dicho que te lleve río arriba. Sube cuando estés $glisto:lista;.' WHERE `ID`=44368;
