UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음대로 도망가지 못할 겁니다.', `MaleText_loc4`='他不会去任何地方。', `MaleText_loc5`='他哪兒都別想去。', `MaleText_loc7`='No va a ir a ninguna parte.' WHERE `ID`=44372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 이곳을 벗어나지 못합니다. 리암 왕자님께서 명령하셨습니다.', `MaleText_loc4`='任何人都不许离开，这是利亚姆王子的命令。', `MaleText_loc5`='通通不准離開。這是黎姆王子的命令。', `MaleText_loc7`='Nadie puede salir. Son órdenes del príncipe Liam.' WHERE `ID`=44373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲 속에 무언가가 돌아다니고 있으니 이곳을 벗어나면 위험합니다.', `MaleText_loc4`='现在离开并不安全。这片森林中潜伏着可怕的东西。', `MaleText_loc5`='有不明的東西潛伏在樹林裡，離開此處並不是個安全的舉動。', `MaleText_loc7`='No es seguro salir, hay algo merodeando por el bosque.' WHERE `ID`=44374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있으십시오. 모든 일이 차질 없이 진행 중입니다.', `MaleText_loc4`='保持冷静。一切都在控制之中。', `MaleText_loc5`='冷靜，一切都在我們的掌握之中。', `MaleText_loc7`='Mantén la calma. Lo tenemos todo bajo control.' WHERE `ID`=44375;
