UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수 있습니까!', `MaleText_loc4`='你不能对我们这样做！', `MaleText_loc5`='你不能這樣對我們!', `MaleText_loc7`='¡No puedes hacernos esto!', `FemaleText_loc1`='어떻게 이럴 수 있어요!', `FemaleText_loc4`='你不能对我们这样做！', `FemaleText_loc5`='你不能這樣對我們!', `FemaleText_loc7`='¡No puedes hacernos esto!' WHERE `ID`=44377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이들이 폭풍협곡에 혼자 있습니다! 아이들에게 가 봐야 한단 말입니다!', `MaleText_loc4`='我的孩子们还在风谷村里，没有人照顾！我必须去找到他们！', `MaleText_loc5`='我的孩子都在颶谷村!我得去照顧他們!', `MaleText_loc7`='¡Mis hijos están solos en Valletormenta! ¡Tengo que ir por ellos!', `FemaleText_loc1`='아이들이 폭풍협곡에 혼자 있어요! 아이들에게 가 봐야 해요!', `FemaleText_loc4`='我的孩子们还在风谷村里，没有人照顾！我必须去找到他们！', `FemaleText_loc5`='我的孩子都在颶谷村!我得去照顧他們!', `FemaleText_loc7`='¡Mis hijos están solos en Valletormenta! ¡Tengo que ir por ellos!' WHERE `ID`=44378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어난 겁니까? 지붕 위에서 뭔가를 본 것 같은데 말이죠.', `MaleText_loc4`='出了什么事？我仿佛看到有什么东西在房顶上。', `MaleText_loc5`='發生什麼事情?我好像看到屋頂上有東西。', `MaleText_loc7`='¿Qué está pasando? Me ha parecido ver algo por los tejados.', `FemaleText_loc1`='무슨 일이 일어난 건가요? 지붕 위에서 뭔가를 본 것 같아요.', `FemaleText_loc4`='出了什么事？我仿佛看到有什么东西在房顶上。', `FemaleText_loc5`='發生什麼事情?我好像看到屋頂上有東西。', `FemaleText_loc7`='¿Qué está pasando? Me ha parecido ver algo por los tejados.' WHERE `ID`=44379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네, 무슨 일인가?', `MaleText_loc4`='朋友，你需要什么？', `MaleText_loc5`='嘿，老兄，你需要什麼?', `MaleText_loc7`='Ey, colega, ¿qué necesitas?' WHERE `ID`=44380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스키지가 하드렌치 은신처까지 가는 비용을 미리 드렸다고 하더군요. 지금 출발하고 싶습니다.', `MaleText_loc4`='斯奇兹说他已经为我前往硬钳避世乐园的旅途付过钱了。我想现在出发。', `MaleText_loc5`='史基茲說他已經幫我付好了飛往硬心藏匿處的錢。我準備好出發了。', `MaleText_loc7`='Skeezy dice que ya ha pagado mi vuelo al Escondrijo Malallave. Estoy listo para partir.', `FemaleText_loc1`='스키지가 하드렌치 은신처까지 가는 비용을 미리 드렸다고 하더군요. 지금 출발하고 싶어요.', `FemaleText_loc4`='斯奇兹说他已经为我前往硬钳避世乐园的旅途付过钱了。我想现在出发。', `FemaleText_loc5`='史基茲說他已經幫我付好了飛往硬心藏匿處的錢。我準備好出發了。', `FemaleText_loc7`='Skeezy dice que ya ha pagado mi vuelo al Escondrijo Malallave. Estoy lista para partir.' WHERE `ID`=44381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 경계하게, $c. 이 듀로타조차 적의 습격에서 안전한 곳은 아닐세.', `MaleText_loc4`='睁大眼睛，$c。即使是杜隆塔尔也难免会潜藏着敌人。', `MaleText_loc5`='睜大你的雙眼，$c。就連杜洛塔也正受到敵人的威脅。', `MaleText_loc7`='Mantén los ojos abiertos, $c. Ni siquiera en Durotar estamos a salvo de nuestros enemigos.' WHERE `ID`=44382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드릴까요, $n 님?', `MaleText_loc4`='$n，什么事？', `MaleText_loc5`='什麼，$n?', `MaleText_loc7`='¿Sí, $n?' WHERE `ID`=44383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울프레드가 탐험가 연맹 발굴현장까지 가는 비용을 미리 드렸다고 하더군요. 지금 출발하고 싶습니다.', `MaleText_loc4`='乌尔弗雷德说他已经为我前往探险者协会挖掘场的旅行付过钱了。我想现在出发。', `MaleText_loc5`='伍爾佛萊德說他已經向探險者協會挖掘場支付了我這次的旅費。我準備好上路了。', `MaleText_loc7`='Wulfred dice que ya ha pagado mi viaje a la Excavación de la Liga de Expedicionarios. Estoy listo para partir.', `FemaleText_loc1`='울프레드가 탐험가 연맹 발굴현장까지 가는 비용을 미리 드렸다고 하더군요. 지금 출발하고 싶어요.', `FemaleText_loc4`='乌尔弗雷德说他已经为我前往探险者协会挖掘场的旅行付过钱了。我想现在出发。', `FemaleText_loc5`='伍爾佛萊德說他已經向探險者協會挖掘場支付了我這次的旅費。我準備好上路了。', `FemaleText_loc7`='Wulfred dice que ya ha pagado mi viaje a la Excavación de la Liga de Expedicionarios. Estoy lista para partir.' WHERE `ID`=44384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐험가 연맹은 이 세상의 숨겨진 비밀을 밝혀내기 위해 존재해왔다. 대격변은 대부분의 사람들에게 엄청난 피해를 입혔지만, 우리에겐 지금껏 알려지지 않았던 정보와 부를 가져다주었다.', `MaleText_loc4`='探险者协会的组建是为了发掘出隐藏在这个世界各个角落的秘密。大灾变对这个世界造成了巨大的破坏，但数不清的古代遗迹和宝藏也因此有机会重现天日。', `MaleText_loc5`='探險者協會的存在是為了揭露這個世界的秘密。', `MaleText_loc7`='La Liga de Expedicionarios existe para descubrir los secretos ocultos de este mundo. Aunque el Cataclismo fue devastador para la mayoría de la gente, para nosotros ha supuesto acceso a cantidades inimaginables de información y tesoros.' WHERE `ID`=44385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘유! 조금 전 길은 꽤 고생스러웠어. 그렇지만 이제부터는 순풍을 타고 잘 갈 수 있을 거야.', `MaleText_loc4`='吆，我们的确是遇到了一点麻烦，不过剩下的旅途就应该是一帆风顺了。', `MaleText_loc5`='呼，剛剛是有點驚險，但接下來應該不會有任何危險了。', `MaleText_loc7`='Bueno, eso ha estado cerca, pero el resto del viaje debería ser coser y cantar.' WHERE `ID`=44386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='햇볕이 따뜻하게 내리쬐는 날 듀로타의 향기를 맡으며 편안하게 배를 타는 것만큼 기분 좋은 일은 없지.', `MaleText_loc4`='乘着一艘温暖、舒适的小艇泛舟杜隆塔尔真是一大乐事。', `MaleText_loc5`='坐著溫暖舒適的小船，聞著杜洛塔的氣味，啊...沒有比這更棒的享受了。', `MaleText_loc7`='No hay nada como el olor de Durotar durante un viaje en barco cálido y agradable.' WHERE `ID`=44387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이 지역이 이렇게 아름다운 여행을 할 때 위험한 일에 빠질 수도 있는 곳이야.', `MaleText_loc4`='在这样美好的旅程中，出现一些失误也是难免的事。', `MaleText_loc5`='這麼棒的旅程，你不禁會懷疑待會兒是不是會出什麼差錯。', `MaleText_loc7`='Aquí es donde uno se espera que algo vaya mal en un viaje tan estupendo como este.' WHERE `ID`=44388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 내게 이렇게 물어보더라고. "호튼, 왜 강 상류와 하류 사이로 배를 몰고 다니나?" 그럼 내가 이렇게 물어보곤 하지. "자네들도 한번 해보지그래?"... 물론 이건 받아칠 말이 없을 때 하는 말이긴 해.', `MaleText_loc4`='大家总是说：“荷尔登，为什么你要在这条河上行船？”我则问他们：“为什么你们不这样做？”……然后，呃，往往就没有然后了。', `MaleText_loc5`='大家老是在講，「荷頓，你怎麼不弄艘船在這條河的上下游開來開去呢?」然後我就反問他們「那你怎麼不咧?」...這時候通常我就會詞窮講不出話了。', `MaleText_loc7`='Todo el mundo me dice: "Horton, ¿por qué llevas un barco río arriba y río abajo?", y yo les pregunto: "¿Y por qué tú no?"... Ahí es donde me suelo quedar sin réplicas ingeniosas.' WHERE `ID`=44389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하차 지점 근처에서 세워줄게. 노즐팟의 전초기지로 가려면 서쪽 길을 쭉 따라가면 돼.', `MaleText_loc4`='我们很快就会停下来了。然后你沿着大路向西前进，就能到达诺兹波克的哨站了。', `MaleText_loc5`='我們就快到達你的目的地了。沿著路往西一直走就會抵達管壺前哨。', `MaleText_loc7`='Nos acercamos a tu parada. Sigue el camino hacia el oeste para llegar a la Avanzada de Ollaboquilla.' WHERE `ID`=44390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 문이 닫힌 겁니까?', `MaleText_loc4`='为什么大门紧关着？', `MaleText_loc5`='城門為什麼關著?', `MaleText_loc7`='¿Por qué están cerradas las puertas?', `FemaleText_loc1`='왜 문이 닫힌 건가요?', `FemaleText_loc4`='为什么大门紧关着？', `FemaleText_loc5`='城門為什麼關著?', `FemaleText_loc7`='¿Por qué están cerradas las puertas?' WHERE `ID`=44391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 소리 들으셨습니까?', `MaleText_loc4`='你听到了吗？', `MaleText_loc5`='你聽到了嗎?', `MaleText_loc7`='¿Has oído eso?', `FemaleText_loc1`='이 소리 들으셨나요?', `FemaleText_loc4`='你听到了吗？', `FemaleText_loc5`='你聽到了嗎?', `FemaleText_loc7`='¿Has oído eso?' WHERE `ID`=44392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 이곳을 벗어나야만 합니다! 울부짖는 소리가 매일 밤 더 커지고 있단 말입니다.', `MaleText_loc4`='我们必须离开这里！嚎叫声每晚都在变得更大。', `MaleText_loc5`='我們一定得離開這裡!吼叫的聲音每天晚上都越來越大聲。', `MaleText_loc7`='¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.', `FemaleText_loc1`='어서 이곳을 벗어나야만 해요! 울부짖는 소리가 매일 밤 더 커지고 있단 말이에요.', `FemaleText_loc4`='我们必须离开这里！嚎叫声每晚都在变得更大。', `FemaleText_loc5`='我們一定得離開這裡!吼叫的聲音每天晚上都越來越大聲。', `FemaleText_loc7`='¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.' WHERE `ID`=44393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병들이 길니아스 시는 안전하다고 말했었는데...', `MaleText_loc4`='他们对我们说，吉尔尼斯城是安全的……', `MaleText_loc5`='他們跟我們講說吉爾尼斯城是安全的...', `MaleText_loc7`='Nos dijeron que la Ciudad de Gilneas estaría a salvo...', `FemaleText_loc1`='경비병들이 길니아스 시는 안전하다고 말했었는데...', `FemaleText_loc4`='他们对我们说，吉尔尼斯城是安全的……', `FemaleText_loc5`='他們跟我們講說吉爾尼斯城是安全的...', `FemaleText_loc7`='Nos dijeron que la Ciudad de Gilneas estaría a salvo...' WHERE `ID`=44394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 포로들과 여기 있도록. 수상한 짓은 하지 마라.', `MaleText_loc4`='和其他人一起留在这里，不要擅自行动。', `MaleText_loc5`='和其他人待在這，別自作聰明嘗試什麼花樣。', `MaleText_loc7`='Quédate aquí con los demás y no intentes ningún truco.', `FemaleText_loc1`='다른 포로들과 여기 있도록. 수상한 짓은 하지 마라.', `FemaleText_loc4`='和其他人一起留在这里，不要擅自行动。', `FemaleText_loc5`='和其他人待在這，別自作聰明嘗試什麼花樣。', `FemaleText_loc7`='Quédate aquí con los demás y no intentes ningún truco.' WHERE `ID`=44395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 넘어오지 못하게 하십시오!', `MaleText_loc4`='别让他们突破阵线！', `MaleText_loc5`='別讓他們穿過防線!', `MaleText_loc7`='¡Que no rompan el frente!' WHERE `ID`=44396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍협곡을 위하여! 길니아스를 위하여!', `MaleText_loc4`='为了风谷村！为了吉尔尼斯！', `MaleText_loc5`='為了颶谷!為了吉爾尼斯!', `MaleText_loc7`='¡Por Valletormenta! ¡Por Gilneas!' WHERE `ID`=44397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 더러운 야수 놈들!', `MaleText_loc4`='去死吧，恶心的怪物！', `MaleText_loc5`='死吧，骯髒的野獸', `MaleText_loc7`='¡Muere, bestia inmunda!' WHERE `ID`=44398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간 침략자가 폭풍협곡 파수병에게 으르렁거립니다.', `MaleText_loc4`='对着风谷村防御者咆哮。', `MaleText_loc5`='向颶谷防衛者咆哮。', `MaleText_loc7`='gruñe al defensor de Valletormenta.' WHERE `ID`=44399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 전사만 가르치오, $c|1이여;여;. 다른 곳으로 가보시오.', `MaleText_loc4`='我只对战士进行训练，$c。你得去别处找找。', `MaleText_loc5`='我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', `MaleText_loc7`='Yo solo entreno a los guerreros, $c. Tendrás que buscar en otra parte.', `FemaleText_loc1`='저는 전사만 가르칩니다, $c님. 다른 곳으로 가보세요.', `FemaleText_loc4`='我只对战士进行训练，$c。你得去别处找找。', `FemaleText_loc5`='我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', `FemaleText_loc7`='Yo solo entreno a los guerreros, $c. Tendrás que buscar en otra parte.' WHERE `ID`=44400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련받을 준비가 되었소, 전사여?', `MaleText_loc4`='你准备好接受训练了吗，战士？', `MaleText_loc5`='準備接受訓練了嗎，戰士?', `MaleText_loc7`='¿Estás $glisto:lista; para la instrucción, $gguerrero:guerrera;?', `FemaleText_loc1`='훈련받을 준비가 되었소, 전사여?', `FemaleText_loc4`='你准备好接受训练了吗，战士？', `FemaleText_loc5`='準備接受訓練了嗎，戰士?', `FemaleText_loc7`='¿Estás $glisto:lista; para la instrucción, $gguerrero:guerrera;?' WHERE `ID`=44401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사히 빠져나와서 다행이군, $n.', `MaleText_loc4`='真高兴看到你成功了，$n。', `MaleText_loc5`='很高興你成功了，$n。', `MaleText_loc7`='Me alegra ver que has sobrevivido, $n.' WHERE `ID`=44402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘의 파이를 보여 주십시오.', `MaleText_loc4`='让我看看今天的馅饼有哪些选择。', `MaleText_loc5`='給我看看今天的特色派是什麼。', `MaleText_loc7`='Enséñame los pasteles del día.', `FemaleText_loc1`='오늘의 파이를 보여 주세요.', `FemaleText_loc4`='让我看看今天的馅饼有哪些选择。', `FemaleText_loc5`='給我看看今天的特色派是什麼。', `FemaleText_loc7`='Enséñame los pasteles del día.' WHERE `ID`=44403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 파이가 케이크보다 더 좋습니까?', `MaleText_loc4`='为什么是馅饼而不是蛋糕？', `MaleText_loc5`='為什麼是派不是蛋糕?', `MaleText_loc7`='¿Por qué pastel y no tarta?', `FemaleText_loc1`='왜 파이가 케이크보다 더 좋나요?', `FemaleText_loc4`='为什么是馅饼而不是蛋糕？', `FemaleText_loc5`='為什麼是派不是蛋糕?', `FemaleText_loc7`='¿Por qué pastel y no tarta?' WHERE `ID`=44404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파이가 케이크보다 훨씬 맛있다는 건 누구나 다 아는 사실이오! 이런 중요한 사실을 $c들 사이에 널리 알려주지 않겠소?', `MaleText_loc4`='馅饼比蛋糕要高级多了！这简直是人尽皆知！难道像你这样有身份的$c竟不知道这么重要的事？', `MaleText_loc5`='派比蛋糕要好吃多了，大家都知道!像你這樣身分地位的$C，難道連這麼重要的事情也不曉得嗎?', `MaleText_loc7`='El pastel le da mil vueltas a la tarta. ¡Todo el mundo lo sabe! ¿$gUn:Una; $c de tu calibre no debería estar al tanto de estas cosas?' WHERE `ID`=44405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다.', `MaleText_loc4`='我会记住的。', `MaleText_loc5`='我會記住的。', `MaleText_loc7`='Lo tendré en cuenta.', `FemaleText_loc1`='잘 알겠어요.', `FemaleText_loc4`='我会记住的。', `FemaleText_loc5`='我會記住的。', `FemaleText_loc7`='Lo tendré en cuenta.' WHERE `ID`=44406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 흥미로운 얘기라도 들었나, $n? 내 정체를 밝혀냈으니 이젠 죽어 줘야겠다.', `MaleText_loc4`='听到什么有趣的消息了吗，$n？你要是敢泄露与我有关的半点儿消息，就等死吧。', `MaleText_loc5`='有聽到什麼好玩的嗎，$n?揭露我的代價就是你的性命。', `MaleText_loc7`='¿Has oído algo interesante, $n? Tu pequeña revelación sobre mí está a punto de costarte la vida.' WHERE `ID`=44407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군. 호드는 나날이 약해지고 있어...', `MaleText_loc4`='真是可悲。部落变得一天比一天弱……', `MaleText_loc5`='真可悲，部落每天都變得越來越弱...', `MaleText_loc7`='Patético. La Horda se debilita por momentos...' WHERE `ID`=44408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단은 곳곳에 요원을 심어 두었다! 날 죽여 봤자 더 많은 이가 내 자리를 채울 것이야!', `MaleText_loc4`='暮光之锤的耳目无所不在！杀了我，马上会有无数人接替我的工作！', `MaleText_loc5`='暮光之錘的間諜到處都是!就算殺了我也還會有一打人來頂替我的位置!', `MaleText_loc7`='¡El Martillo Crepuscular tiene agentes por todas partes! ¡Mátame y una docena ocupará mi lugar!' WHERE `ID`=44409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지닌 예지력... 나는 미래를 보았다... 어떤 일이 닥칠지 보았어...', `MaleText_loc4`='我的预视能力……我看到了未来……我看到了将要发生的一切……', `MaleText_loc5`='我預言的能力...我看見了未來...我已見識到即將發生之事...', `MaleText_loc7`='Mis poderes de visión... Contemplé el futuro... He visto lo que está por venir...' WHERE `ID`=44410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상이 무너진다. 내가 본 공포를 너도 보았더라면...', `MaleText_loc4`='这个世界分崩离析。要是你能看到我所目睹的恐怖之景……', `MaleText_loc5`='世界分崩離析。要是你能見到我所見識的恐怖景象...', `MaleText_loc7`='Este mundo se desmorona. Si pudieras ver los horrores que he visto...' WHERE `ID`=44411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하는 건 미친 짓이지. 하지만 저항은... 아예 불가능하다!', `MaleText_loc4`='效命是疯狂的，可反抗……是不可能的！', `MaleText_loc5`='服侍是瘋狂，反抗是...不可能的!', `MaleText_loc7`='Someterse es una locura, pero la rebelión... ¡es imposible!' WHERE `ID`=44412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 망치단이 어디 숨든지 간에 우리는 놈들을 무찌를 겁니다. 정령계도 놈들의 안식처가 되지는 못할 거예요.', `FemaleText_loc4`='不管暮光之锤的信徒们藏到哪里，我们都将击败他们。就连元素位面也不是他们安全的避风港。', `FemaleText_loc5`='不論暮光之錘的人躲藏在哪裡，我們都會擊敗他們。就算躲到元素界域去也沒有用。', `FemaleText_loc7`='Derrotaremos al Martillo Crepuscular allí donde se esconda. Ni siquiera en los planos elementales encontrarán refugio los de su calaña.' WHERE `ID`=44413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소환수는 여기에서 기다려야 합니다. 검은바위 늑대 대장을 조심하십시오! |Tinterface\\Icons\\SPELL_NATURE_TIMESTOP.BLP:24|t', `MaleText_loc4`='你应该让宠物等在这里。小心黑石狼骑首领！|TInterface\\Icons\\SPELL_NATURE_TIMESTOP.BLP:24|t', `MaleText_loc5`='你應該叫你的寵物在這邊等你。小心黑石座狼隊長!|TInterface\\Icons\\SPELL_NATURE_TIMESTOP.BLP:24|t', `MaleText_loc7`='Deberías hacer que tu mascota te espere aquí. ¡Cuidado con el capitán de huargos Roca Negra! |TInterfaceIconsSPELL_NATURE_TIMESTOP.BLP:24|t' WHERE `ID`=44414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지말고 소환수에게 따라오라는 명령을 내리십시오! |Tinterface\\Icons\\ABILITY_TRACKING.BLP:24|t', `MaleText_loc4`='别忘了命令你的宠物跟着你！|TInterface\\Icons\\ABILITY_TRACKING.BLP:24|t', `MaleText_loc5`='別忘記叫你的寵物緊緊跟隨你! |TInterface\\Icons\\ABILITY_TRACKING.BLP:24|t', `MaleText_loc7`='¡No olvides ordenarle a tu mascota que te siga! |TInterfaceIconsABILITY_TRACKING.BLP:24|t' WHERE `ID`=44415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙은 세계 기둥을 파괴하면서, 자네의 세계와 우리 세계 사이에 균열을 발생시켰네. 이 포자와 곰팡이들도 그 결과로 생겨난 것들이지.$B$B우리가 어떤 조치를 취할 수 있을지 한번 보세.', `MaleText_loc4`='当死亡之翼毁掉世界之柱时，他打开了一道位于你我世界间的裂隙。这些孢子与菌类就是后果之一。$B$B让我们看看能否共同解决它们。', `MaleText_loc5`='當死亡之翼破壞世界之柱時，他在你我的世界之間撕開了一道裂隙，而這些孢子和蕈類就是災變後的產物。$B$B讓我們看看，是否有辦法一起把他們解決掉吧。', `MaleText_loc7`='Cuando Alamuerte destruyó el Pilar del Mundo, abrió una brecha entre su mundo y el nuestro. Estos hongos y esporas son una consecuencia.$b$bA ver si podemos encargarnos de este asunto juntos.' WHERE `ID`=44416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁 수호자 데려가는 걸 잊지 말게, $n.', `MaleText_loc4`='别忘了抓个战争卫士，$n。', `MaleText_loc5`='別忘了要帶個戰爭守護者，$n。', `MaleText_loc7`='No te olvides de subirte a un guardián de guerra, $n.' WHERE `ID`=44417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불곰 중대 야전 장비를 작동시켰습니다. 행동 단축바에서 새로운 능력을 사용할 수 있습니다.$b$b불곰 중대 야전 장비의 작동을 중단하려면 다시 한 번 사용하십시오.', `MaleText_loc4`='B连战地工具现已激活。在你的动作条上已有可用的新技能。$B关闭B连战地工具即可停用。', `MaleText_loc5`='第二連隊野戰包啟用中，快捷列上已有新的能力可供使用。$B切換第二連隊野戰包即可停用其功能。', `MaleText_loc7`='Paquete de campo de la Compañía Bravo ACTIVADO. Hay nuevas facultades disponibles en tu barra de acción.$b$bAcciona el paquete de campo de la Compañía Bravo para DESACTIVARLO.', `FemaleText_loc1`='불곰 중대 야전 장비를 작동시켰습니다. 행동 단축바에서 새로운 능력을 사용할 수 있습니다.$b$b불곰 중대 야전 장비의 작동을 중단하려면 다시 한 번 사용하십시오.', `FemaleText_loc4`='B连战地工具现已激活。在你的动作条上已有可用的新技能。$B关闭B连战地工具即可停用。', `FemaleText_loc5`='第二連隊野戰包啟用中，快捷列上已有新的能力可供使用。$B切換第二連隊野戰包即可停用其功能。', `FemaleText_loc7`='Paquete de campo de la Compañía Bravo ACTIVADO. Hay nuevas facultades disponibles en tu barra de acción.$b$bAcciona el paquete de campo de la Compañía Bravo para DESACTIVARLO.' WHERE `ID`=44418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불곰 중대 야전 장비를 작동시켰습니다. 행동 단축바에서 시포리움 설치가 가능합니다.$b$b불곰 중대 야전 장비의 작동을 중단하려면 다시 한 번 사용하십시오.', `MaleText_loc4`='B连战地工具现已激活。在你的动作条上已出现放置爆盐技能。$B关闭B连战地工具即可停用。', `MaleText_loc5`='第二連隊野戰包啟用中。快捷列上已有「設置爆鹽炸藥」可供使用。$B切換第二連隊野戰包即可停用其功能。', `MaleText_loc7`='Paquete de campo de la Compañía Bravo ACTIVADO. Ahora Plantar seforio está disponible en tu barra de acción.$b$bAcciona el paquete de campo de la Compañía Bravo para DESACTIVARLO.', `FemaleText_loc1`='불곰 중대 야전 장비를 작동시켰습니다. 행동 단축바에서 시포리움 설치가 가능합니다.$b$b불곰 중대 야전 장비의 작동을 중단하려면 다시 한 번 사용하십시오.', `FemaleText_loc4`='B连战地工具现已激活。在你的动作条上已出现放置爆盐技能。$B关闭B连战地工具即可停用。', `FemaleText_loc5`='第二連隊野戰包啟用中。快捷列上已有「設置爆鹽炸藥」可供使用。$B切換第二連隊野戰包即可停用其功能。', `FemaleText_loc7`='Paquete de campo de la Compañía Bravo ACTIVADO. Ahora Plantar seforio está disponible en tu barra de acción.$b$bAcciona el paquete de campo de la Compañía Bravo para DESACTIVARLO.' WHERE `ID`=44419;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기, $n 님!', `FemaleText_loc4`='你好，$n！', `FemaleText_loc5`='嗨，$n!', `FemaleText_loc7`='¡Hola, $n!' WHERE `ID`=44420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌배, 이 겁쟁이 같으니! 그 덩치가 아깝구나!', `MaleText_loc4`='石胆，你这懦夫！找个和你体型一样大的人交手吧！', `MaleText_loc5`='石臟，你這懦夫!找個跟你一樣塊頭的打架對象吧!', `MaleText_loc7`='¡Tripapétrea, serás cobarde! ¡Métete con alguien de tu tamaño!' WHERE `ID`=44421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 이 사슬을 풀지 못할까! 네놈을 가루로 만들어 버리겠다!', `MaleText_loc4`='赶快把我身上这些锁链弄掉！我要把你碾碎！', `MaleText_loc5`='解開我的鎖鍊!我要把你打碎!', `MaleText_loc7`='¡Quítame estas cadenas! ¡Te haré papilla!' WHERE `ID`=44422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플린트! 여기에서 나가거라! 그는 너무 강력하다!', `MaleText_loc4`='弗林特！快走开！他太强大了！', `MaleText_loc5`='弗林特!離開這裡!他太強大了!', `MaleText_loc7`='¡Sílex! ¡Sal de ahí! ¡Es demasiado poderoso!' WHERE `ID`=44423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 냄새나고 더러운 바위 트로그 같으니! 너는 절대로 세계 기둥 조각을 손에 넣을 수 없다!', `MaleText_loc4`='不得好死的臭气熏天的石头穴居人！你们永远别想知道我把世界之柱的碎片藏在哪儿！', `MaleText_loc5`='該死的臭岩石穴居怪!你絕對拿不到世界之柱碎片!', `MaleText_loc7`='¡Maldito y apestoso trogg de piedra! ¡Nunca conseguirás el fragmento del Pilar del Mundo!' WHERE `ID`=44424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다, 돌배. 정의의 사도가 등장했으니까!', `MaleText_loc4`='你太迟了，石胆。大名鼎鼎的骑兵已经到了！', `MaleText_loc5`='你太遲了，石臟。援軍已經抵達了!', `MaleText_loc7`='Demasiado tarde, Tripapétrea. Ha llegado la caballería, como quien dice.' WHERE `ID`=44425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님. 뭐 필요하신 거라도 있으세요?', `FemaleText_loc4`='你好啊，$c。想要买点儿什么吗？', `FemaleText_loc5`='哈囉，$c。要買點東西嗎?', `FemaleText_loc7`='Hola, $c. ¿Quieres comprar algo?' WHERE `ID`=44426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 사슬에서 풀려나기만 해봐라. 세상 그 어떤 것이 날 막아도 돌배 네놈만은 꼭 처치하겠다!', `MaleText_loc4`='等我挣脱这些锁链，元素位面中没有任何力量能阻止我杀了你，石胆！', `MaleText_loc5`='等我掙脫了這鎖鍊，元素界域將沒有任何東西能阻止我殺掉你，石臟!', `MaleText_loc7`='¡No hay nada en ningún plano elemental que me impida matarte en cuanto me libre de estas cadenas, Tripapétrea!' WHERE `ID`=44427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦기 전에 날 풀어 줘라! 세계 기둥이 이렇게 망가진 상태로는 심원의 영지도 오래 버틸 수 없다!', `MaleText_loc4`='快放了我，否则就来不及了！要是没有完整的世界之柱，深岩之洲撑不了多久！', `MaleText_loc5`='立刻釋放我，不然到時候就來不及了!世界之柱破損，地深之源無法再撐多久了!', `MaleText_loc7`='¡Libérame antes de que sea demasiado tarde! ¡Infralar no puede sobrevivir mucho tiempo si el Pilar del Mundo no está intacto!' WHERE `ID`=44428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 지금 무슨 일을 벌이는지 아느냐, 돌배! 나를 가둬 놓음으로써 넌 심원의 영지와 우리 모두를 파멸로 몰아넣고 있단 말이다!', `MaleText_loc4`='你还没意识到你在做什么，石胆！你囚禁我，这是在把深岩之洲和我们所有人都推向万劫不复！', `MaleText_loc5`='你不知道自己在做什麼，石臟!把我銬在這裡，你會害死地深之源和我們所有人!', `MaleText_loc7`='¡No sabes lo que haces, Tripapétrea! ¡Al tenerme prisionero estás condenando a Infralar, y a todos nosotros!' WHERE `ID`=44429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 이렇게 반가울 데가! 이리 와서 나를 좀 돕게나, 괜찮겠나?', `MaleText_loc4`='$n！你可真是稀客啊。快过来帮帮我，好吗？', `MaleText_loc5`='$n!真高興看到你。過來這裡幫我一把，好嗎?', `MaleText_loc7`='¡$n! Dichosos los ojos. Ven aquí y échame una mano, ¿quieres?' WHERE `ID`=44430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 두 개를 섞고...', `MaleText_loc4`='我们只需把这两个混在一起……', `MaleText_loc5`='我們只要把這兩樣混在一起...', `MaleText_loc7`='Mezclamos estas dos cosas...' WHERE `ID`=44431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...천천히 휘저어 주는 거예요...', `MaleText_loc4`='……稍微搅一搅……', `MaleText_loc5`='...稍微搖它個幾下...', `MaleText_loc7`='...lo agitamos un poco...' WHERE `ID`=44432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...연금술, 연금술, 연금술...', `MaleText_loc4`='……炼金术，炼金术，炼金术……', `MaleText_loc5`='...鍊金術啊，鍊金術啊，鍊金術啊...', `MaleText_loc7`='...alquimia, alquimia, alquimia...' WHERE `ID`=44433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그리고 견본에 물약을 넣고...', `MaleText_loc4`='……然后，我们把药水放到样本上……', `MaleText_loc5`='...然後，我們把藥水倒到樣本上...', `MaleText_loc7`='...y aplicamos la poción a la muestra...' WHERE `ID`=44434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 끝났습니다. 당신이 가져오신 물질은 대략... 15만 년 전의 물건이라고? 이건 뭐지!? 실험을 더 해봐야겠네요.', `MaleText_loc4`='好了。你给我带来的物质大约是……十五万年前的？什么？！我还得再进行另一个实验。', `MaleText_loc5`='好了。你帶來給我的物質大約是...150,000年前的?什麼!?我得再做個測試才行。', `MaleText_loc7`='Ahí tienes. La sustancia que me has traído tiene aproximadamente... ¿150000 años? ¡¿Qué?! Voy a tener que realizar otra prueba.' WHERE `ID`=44435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구루바시 부족은 학카르와 함께 사라졌습니다. 우리 잔달라 부족도 대부분 고향으로 가버렸고요.$b$b이제 줄구룹을 감시하는 건 저, 차발, 그리고 밤발라의 검은창 부족의 몫입니다.', `FemaleText_loc4`='古拉巴什已经灭亡，连同哈卡一起。我大多数的赞达拉同胞都回到了他们的故乡。$b$b现在，守卫祖尔格拉布的重任就落在了我，查巴尔和邦巴拉暗矛巨魔的肩上。', `FemaleText_loc5`='古拉巴什部族已隨著哈卡一同滅亡。我贊達拉的同伴們大多已返回了他們的故鄉。$b$b如今只剩下我、查巴爾，還有班姆巴拉島的暗矛部族在看守祖爾格拉布。', `FemaleText_loc7`='Los Gurubashi están muertos, y Hakkar con ellos. La mayoría de mis compañeros Zandalar han vuelto a su hogar.$b$bAhora somos nosotros, Chabal, los Lanza Negra de Bambala y yo, los que debemos vigilar Zul''Gurub.' WHERE `ID`=44436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메이위키, 잔질을 추적하다 무슨 일을 하고 있었나 잊어버렸습니다. 다음에 어디로 가야 하는지 알려주시겠습니까?', `MaleText_loc4`='梅维克，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？', `MaleText_loc5`='梅維基，我本來在追捕贊吉爾，但是我忘記該怎麼做了。可以給我提個醒，接下來我該去哪裡嗎?', `MaleText_loc7`='Maywiki, estaba dando caza a Zanzil y me he olvidado de lo que estaba haciendo. ¿Me puedes recordar adónde tengo que ir ahora?', `FemaleText_loc1`='메이위키, 잔질을 추적하다 무슨 일을 하고 있었나 잊어버렸어요. 다음에 어디로 가야 하는지 알려주시겠어요?', `FemaleText_loc4`='梅维克，我光顾着追踪赞吉尔，忘了自己该干的事儿了。你能提醒我接下来要去哪儿吗？', `FemaleText_loc5`='梅維基，我本來在追捕贊吉爾，但是我忘記該怎麼做了。可以給我提個醒，接下來我該去哪裡嗎?', `FemaleText_loc7`='Maywiki, estaba dando caza a Zanzil y me he olvidado de lo que estaba haciendo. ¿Me puedes recordar adónde tengo que ir ahora?' WHERE `ID`=44437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고대 토템은 박쥐 모양을 하고 있습니다. 이 고대 토템은 박쥐 모양을 하고 있습니다. 메이위키가 말한 그 토템이 확실합니다.', `MaleText_loc4`='这根古老的图腾有着蝙蝠的造型。这一定就是梅维克说的那根图腾。', `MaleText_loc5`='這個古老的圖騰被做成了蝙蝠的造型，它應該就是梅維基提到的那個圖騰。', `MaleText_loc7`='Este antiguo tótem tiene la forma de un murciélago. Debe de ser el tótem del que hablaba Maywiki.' WHERE `ID`=44438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄 유물은 대체로 아무 반응이 없어요. 잔질의 혼합물도 별 효과가 없을 것으로 추정되지만... 한번 실험해 봅시다!', `MaleText_loc4`='这些泰坦圣物基本毫无活动力。像赞吉尔药剂这样的东西应该不会产生任何效果。让我们试试看！', `MaleText_loc5`='泰坦文物大多是無反應的，像贊吉爾的混合物這類的東西應該不會有任何作用才對。我們來試看看吧!', `MaleText_loc7`='Los artefactos de los Titanes son en su mayor parte inertes. Algo como la mezcla de Zanzil no debería tener ningún efecto. ¡Vamos a probar!' WHERE `ID`=44439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 반응은... 예상 못 했네요.', `MaleText_loc4`='这很……出乎意料。', `MaleText_loc5`='那倒是...挺意外的。', `MaleText_loc7`='Eso... No me lo esperaba.' WHERE `ID`=44440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이봐요, $n 님.', `MaleText_loc4`='哦，嗨，$n。', `MaleText_loc5`='哦，嗨，$n。', `MaleText_loc7`='Ah, hola, $n.' WHERE `ID`=44441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 덕분에 나와 내 아들이 살았네.', `MaleText_loc4`='你救了我和我儿子。', `MaleText_loc5`='你救了我和我兒子。', `MaleText_loc7`='Nos has salvado a mí y a mi hijo.' WHERE `ID`=44442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 우리 백성 모두 자네에게 감사를 표하는 바이네.', `MaleText_loc4`='我和我的人民都对你感激不已。', `MaleText_loc5`='我和我們全族的人都感謝你。', `MaleText_loc7`='Cuentas con mi gratitud y la de mi gente.' WHERE `ID`=44443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 좋은 소식을 파이리움 로드스톤에게 전하게. 그럼 이따 돌난로에서 만나겠네.', `MaleText_loc4`='把好消息带回给燃钢·磁石。我们很快就会在巨石之炉再见面。', `MaleText_loc5`='將好消息帶回黃鐵·磁石，我們等會兒回石爐再見。', `MaleText_loc7`='Llévale las buenas noticias a Pirium Magnetita. Te veremos en el Hogar Pétreo dentro de poco.' WHERE `ID`=44444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 영웅은 대지 고리회를 대표해서 왔습니다. 중간 파편이 필요하다고 합니다.', `MaleText_loc4`='这位英雄是代表大地之环来的。他们需要中部碎片。', `MaleText_loc5`='這位英雄是陶土議會的代表，他們需要中間段的碎片。', `MaleText_loc7`='Este campeón representa al Anillo de la Tierra. Necesita el fragmento central.' WHERE `ID`=44445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 여기서 뭐하는 거예요?', `MaleText_loc4`='嘿！你在那下面干什么呢？', `MaleText_loc5`='嘿!你在那下面做什麼?', `MaleText_loc7`='¡Oye! ¿Qué haces aquí abajo?' WHERE `ID`=44446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 사다리 위로 올라오세요! 저 트롤은 그다지 상냥해 보이지 않네요!', `MaleText_loc4`='快，抓住梯子！那巨魔看起来可不太友善！', `MaleText_loc5`='快點，抓住繩梯!那個食人妖看起來不怎麼友善!', `MaleText_loc7`='¡Rápido, agárrate a la escalera! ¡Ese trol tiene cara de pocos amigos!' WHERE `ID`=44447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자가 혼자 떠나 버렸네. 큰일이야!', `MaleText_loc4`='那王子跑了。糟透了！', `MaleText_loc5`='王子跑走了，這真是太糟糕了!', `MaleText_loc7`='El príncipe ha salido corriendo. ¡Esto no es bueno!' WHERE `ID`=44448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네.$B$B뭡니까? 저리 가세요.', `MaleText_loc4`='Zub zub。$B$B什么？走开。', `MaleText_loc5`='喳喳。$B$B幹嘛?走開。', `MaleText_loc7`='Zub zub.$b$b¿Qué? Fuera.' WHERE `ID`=44449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네.$B$B뭡니까? 두 번이나 대답해 드렸는데 아직도 모자랍니까, $c님?', `MaleText_loc4`='Zub zub。$B$B什么？两声Zub对你来说还不够吗，$c？Zub zub。', `MaleText_loc5`='喳喳。$B$B怎麼?喳兩聲還不夠嗎，$c?', `MaleText_loc7`='Zub zub.$b$B¿Qué? ¿Dos zubs no son bastantes para ti, $c?' WHERE `ID`=44450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 저한테 그런 걸 물어보세요? 전 황혼의 망치단에 대해 아는 게 없는데요.', `MaleText_loc4`='干嘛问我？我又不了解暮光之锤。', `MaleText_loc5`='幹嘛問我?我對暮光之錘一無所知。', `MaleText_loc7`='¿Por qué me preguntas a mí? No sé nada del Martillo Crepuscular.' WHERE `ID`=44451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<땀을 흘리며 경련을 일으키는 일꾼>$B$B전... 그런 뜻이... 엄, 큰일 났네!', `MaleText_loc4`='<劳工一边流汗一边抽搐。>$B$B我……我是说……呃，真糟！', `MaleText_loc5`='<獸人苦工開始冒汗，渾身扭來扭去。>$B$B我是說...我的意思是...呃，壞壞!', `MaleText_loc7`='<El peón empieza a sudar y a retorcerse.>$b$bHe sido... Quiero decir... ¡eh, malo!' WHERE `ID`=44452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<공포에 질려 눈이 휘둥그레지는 일꾼>$B$B안 돼! 사우라노크 님이 오그리마의 새로운 이교도 지도자라는 걸 알아내셨다고요? 저한테는 아무도 모른다고 말씀하셨는데!
', `MaleText_loc4`='<劳工的瞳孔因恐惧而放大。>$B$B不！你发现萨乌拉诺克是奥格瑞玛新的教派领袖？他告诉我他的秘密是安全的！', `MaleText_loc5`='<苦工害怕地睜大了眼睛。>$B$B不!你發現了索拉諾克是奧格瑪城的教徒新首領?他告訴我他的秘密是安全的!', `MaleText_loc7`='<Los ojos del peón se abren aterrorizados.>$b$b¡No! ¿Has descubierto que Sauranok es el nuevo líder cultor de Orgrimmar? ¡Me dijo que su secreto estaba a salvo!' WHERE `ID`=44453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 어... 전 그런 말 안 했어요! 너무해요!', `MaleText_loc4`='等等——啊——你在套我的话！这不公平！', `MaleText_loc5`='慢著，呃 - 你不要亂解釋我的話!不公平!', `MaleText_loc7`='Espera, eh, ¡has puesto palabras en mi boca! ¡No es justo!' WHERE `ID`=44454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 하늘길에 이교도가 침투했다는 이야기에 대해 아는 거 있나?', `MaleText_loc4`='秘密教派已经渗入奥格瑞玛航运线了吗？', `MaleText_loc5`='有教徒秘密滲透了奧格瑪航路?', `MaleText_loc7`='¿Una secta secreta se ha infiltrado en la ruta aérea de Orgrimmar?', `FemaleText_loc1`='오그리마 하늘길에 이교도가 침투했다는 이야기에 대해 아는 거 있나?', `FemaleText_loc4`='秘密教派已经渗入奥格瑞玛航运线了吗？', `FemaleText_loc5`='有教徒秘密滲透了奧格瑪航路?', `FemaleText_loc7`='¿Una secta secreta se ha infiltrado en la ruta aérea de Orgrimmar?' WHERE `ID`=44455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이교도라고만 했지 황혼의 망치단이라는 말은 안 했는데...', `MaleText_loc4`='我可没提到什么暮光之锤。是你说的暮光之锤。', `MaleText_loc5`='我可沒說暮光之錘。暮光之錘是「你」說的。', `MaleText_loc7`='Yo no he dicho "Martillo Crepuscular". TÚ has dicho "Martillo Crepuscular".', `FemaleText_loc1`='난 이교도라고만 했지 황혼의 망치단이라는 말은 안 했는데...', `FemaleText_loc4`='我可没提到什么暮光之锤。是你说的暮光之锤。', `FemaleText_loc5`='我可沒說暮光之錘。暮光之錘是「你」說的。', `FemaleText_loc7`='Yo no he dicho "Martillo Crepuscular". TÚ has dicho "Martillo Crepuscular".' WHERE `ID`=44456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 이교도 지도자가 누구인지 알고 있다.', `MaleText_loc4`='我对你们的教派领袖了解得一清二楚。', `MaleText_loc5`='我知道你們教徒首領的所有事情。', `MaleText_loc7`='Lo sé todo sobre el maestro de tu secta.', `FemaleText_loc1`='너희의 이교도 지도자가 누구인지 알고 있다.', `FemaleText_loc4`='我对你们的教派领袖了解得一清二楚。', `FemaleText_loc5`='我知道你們教徒首領的所有事情。', `FemaleText_loc7`='Lo sé todo sobre el maestro de tu secta.' WHERE `ID`=44457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 그게 사실이군? 사우라노크가 정말로 반역자였어!', `MaleText_loc4`='这么说来是真的了？萨乌拉诺克真的背叛了部落！', `MaleText_loc5`='所以是真的?索拉諾克真的是叛徒!', `MaleText_loc7`='¿Entonces es cierto? ¡Sauranok es culpable de traición!', `FemaleText_loc1`='그럼 그게 사실이군? 사우라노크가 정말로 반역자였어!', `FemaleText_loc4`='这么说来是真的了？萨乌拉诺克真的背叛了部落！', `FemaleText_loc5`='所以是真的?索拉諾克真的是叛徒!', `FemaleText_loc7`='¿Entonces es cierto? ¡Sauranok es culpable de traición!' WHERE `ID`=44458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 멍청한 놈.', `MaleText_loc4`='安静点，白痴。', `MaleText_loc5`='閉嘴，白癡。', `MaleText_loc7`='Silencio, imbécil.' WHERE `ID`=44459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네!', `MaleText_loc4`='Zub zub！', `MaleText_loc5`='喳喳!', `MaleText_loc7`='¡Zub zub!' WHERE `ID`=44460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마는 그 어느 때보다도 강합니다!', `MaleText_loc4`='奥格瑞玛变得比以往更强大！', `MaleText_loc5`='奧格瑪比以前更強大!', `MaleText_loc7`='¡Orgrimmar es más fuerte que nunca!' WHERE `ID`=44461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요?', `MaleText_loc4`='我能帮什么忙吗？', `MaleText_loc5`='我能幫忙嗎?', `MaleText_loc7`='¿Puedo ayudar?' WHERE `ID`=44462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님!$B$B오그리마 하늘길은 세상의 중심이죠. 북쪽 비행선 탑승장에서는 가시덤불 골짜기나 언더시티로 갈 수 있고요, 남쪽 비행선 탑승장에서는 썬더 블러프나 저 멀리 노스렌드로 갈 수 있답니다.$B$B와이번 조련사 도라스는 칼림도어 어느 곳으로든 당신을 보내줄 수 있어요. 적어도 당신이 이미 가본 지역이라면 어디든 말이죠.', `MaleText_loc4`='你好啊，$c！奥格瑞玛是世界航运的枢纽。北飞艇塔能把你送往荆棘谷和幽暗城。南飞艇塔会带你去雷霆崖或直达诺森德。$B$B飞行管理员多拉斯会送你畅游卡利姆多各地——至少能把你送到你已经去过的地方。', `MaleText_loc5`='哈囉，$c!$B$B奧格瑪的航道是世界的中心樞紐，北飛艇塔可以帶你前往荊棘谷或幽暗城，南飛艇塔可以前往雷霆崖，或是一路飛往北裂境。$B$B飛行管理員朵拉斯可以帶你前往卡林多各地 - 呃，至少你有去過的地方都可以。', `MaleText_loc7`='¡Hola, $c!$b$bEl espacio aéreo de Orgrimmar es el centro del mundo. El zepelín del norte te llevará a Tuercespina o a Entrañas. La torre del sur te llevará a Cima del Trueno o hasta Rasganorte.$b$bEl maestro de vuelo Doras te puede enviar a cualquier punto de Kalimdor... Bueno, al menos a cualquier sitio que ya hayas explorado.' WHERE `ID`=44463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도요? 전 모르는 일인데요. 하지만 수상한 녀석들이 남쪽 비행선 탑승장 주변을 얼쩡거리는 건 봤습니다.', `MaleText_loc4`='教派？我不知道。不过似乎有些可疑分子在南飞艇塔附近晃来晃去。', `MaleText_loc5`='教徒?我不曉得。不過，我是有看到幾個鬼鬼祟祟的傢伙在南飛艇塔那附近徘徊。', `MaleText_loc7`='¿Una secta? No sé, pero he visto a unos tipos sospechosos cerca de la torre de zepelín sur.' WHERE `ID`=44464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 아무것도 몰라요! 다른 일꾼하고 얘기하세요.', `MaleText_loc4`='我什么都不知道！去问别人吧。', `MaleText_loc5`='我什麼都不知道!去問別人。', `MaleText_loc7`='¡Yo no sé nada! Pregúntale a otro.' WHERE `ID`=44465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도요? 남쪽 비행선 탑승장에서 뭔가 모임이 있는 걸 봤는데, 그자들인가요?', `MaleText_loc4`='秘密教派？是不是在南飞艇塔底下集会的那些人？', `MaleText_loc5`='秘密教派?是我在南飛艇塔底下看到有人在那裡聚會的嗎?', `MaleText_loc7`='¿Una secta secreta? ¿Son esos tipos que se reúnen en la base de la torre de zepelín sur?' WHERE `ID`=44466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도요? 남쪽 비행선 탑승장 근처를 어슬렁거리는 섬뜩한 오크들이 혹시 이교도인가요?', `MaleText_loc4`='秘密教派？有些鬼祟的兽人在南飞艇塔附近游荡，这事儿跟你没关系吧？', `MaleText_loc5`='神秘教派?你不會跟南飛艇塔附近那些鬼鬼祟祟的獸人是一夥的吧?', `MaleText_loc7`='¿Una secta secreta? No tendrás nada que ver con esos orcos de mal aspecto que merodean por la torre de zepelín sur, ¿no?' WHERE `ID`=44467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 너무 멍청해서 이교도 같은 건 못 해요. 비행선에서 떨어진 이래 쭉 그랬죠. 아, 떨어지면서 프로펠러에도 부딪혔어요. 바위 위로 떨어졌고요. 의사들이 금속 바가지로 머리를 고쳐 줬어요. 동그랗고 단단하라고요.$B$B<주먹으로 머리를 탁 치는 일꾼>$B$B그랬더니 어느 날 벼락이 떨어지더라고요.', `MaleText_loc4`='我这么蠢，根本加入不了教派。自从我从飞艇的后部摔下来就成这样了。我被螺旋桨打到。然后掉到了一块石头上。他们用一只金属大碗把我的头固定住，以让它变得又圆又硬。$B$B<他用拳头敲了敲自己的头。>$B$B然后闪电就来了。', `MaleText_loc5`='我太笨了，不能加入教派。我從飛艇摔下來，被旋槳打到，然後又掉到石頭上。他們用一個金屬碗裝在我頭上，又圓又硬的。$B$B<他用拳頭在自己的頭上敲了幾下。>$B$B然後閃電就來了。', `MaleText_loc7`='Soy demasiado tonto para estar en una secta. Lo he sido desde que me caí de la bodega de un zepelín. Me golpeé con, cómo se llama, la hélice. Y caí sobre una roca. Me arreglaron la cabeza con una ensaladera de metal para que fuera redonda y dura.$b$b<Se golpea en el cráneo con el puño.>$b$bY entonces cayó el rayo.' WHERE `ID`=44468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽 비행선 탑승장 안에서 이상한 오크들이 노상 수군거리던데요. 제가 가까이 가면 항상 입을 다물고요.', `MaleText_loc4`='南飞艇塔里一直能听到兽人在诡异地窃窃私语。每当我走近，他们就立即不说话了。', `MaleText_loc5`='我經常聽到南飛艇塔裡面有奇怪的獸人在竊竊私語的聲音，可是我只要一靠近他們就會閉口不講話。', `MaleText_loc7`='Hay unos orcos extraños que suelen estar cuchicheando dentro de la torre de zepelín sur. Siempre se callan cuando me acerco.' WHERE `ID`=44469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 몰라요.$B$B때리지 마세요!', `MaleText_loc4`='我不知道。$B$B别打我！', `MaleText_loc5`='我不知道。$B$B不要打我!', `MaleText_loc7`='No sé.$b$b¡No me pegues!' WHERE `ID`=44470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 파란 말이다! 멈추지 말란 말이야!', `MaleText_loc4`='快点挖！再快点！不许停！', `MaleText_loc5`='挖快點!快點!不准停!', `MaleText_loc7`='¡Cavar más rápido! ¡Más rápido! ¡No parar!' WHERE `ID`=44471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 파라! 돌덩이 같은 놈들아! 영원한 평화를 위해!', `MaleText_loc4`='快挖！矿工们！为了永远的和平！', `MaleText_loc5`='挖呀!石頭人!一直一直挖!', `MaleText_loc7`='¡Cavar! ¡Hombres roca! ¡Por paz eterna!' WHERE `ID`=44472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 돌덩이 같은 놈! 우리가 시키는 대로 하란 말이야!', `MaleText_loc4`='讨厌的矿工！照我们说的去做！', `MaleText_loc5`='石頭人不乖!聽我們的話!', `MaleText_loc7`='¡Hombres roca malos! ¡Hacer lo que nosotros decir!' WHERE `ID`=44473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광석을 캐라! 돌덩이 같은 놈들아! 빨리 광석을 캐란 말이야!', `MaleText_loc4`='挖矿石！矿工们快点儿挖矿石！', `MaleText_loc5`='挖礦!石頭人趕快挖礦!', `MaleText_loc7`='¡Excavar mineral! ¡Hombres roca excavar mineral ya!' WHERE `ID`=44474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌덩이 같은 놈들이 너무 게으르군! 왜 이렇게 게을러터진 거야?!', `MaleText_loc4`='这些矿工太懒了！矿工为什么会这么懒？！', `MaleText_loc5`='石頭人太懶惰!石頭人為什麼懶惰?!', `MaleText_loc7`='¡Hombres roca muy vagos! ¿Por qué hombres roca tan vagos?' WHERE `ID`=44475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌덩이 같은 놈들이 일하지 않으면 코볼트가 더 괴롭혀 줄 테다!', `MaleText_loc4`='矿工们赶快挖，不然狗头人再让你们吃鞭子！', `MaleText_loc5`='石頭人挖，不然狗頭人打!', `MaleText_loc7`='¡Hombres roca cavar o kóbolds pegar más!' WHERE `ID`=44476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송하지만 당신께 가르쳐 드릴 수 있는 게 없어요.', `FemaleText_loc4`='对不起，可我无法对你进行训练。', `FemaleText_loc5`='抱歉，可是我沒有辦法訓練你。', `FemaleText_loc7`='Lo siento, pero no puedo ofrecerte instrucción.' WHERE `ID`=44477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법사의 길을 가는 것은 정말 험난합니다. 많은 사람이 우리를 이해하지 못하니까요. 우리와 같은 마법사들조차도 그 능력을 받아들이려고 많은 노력을 기울인답니다.', `FemaleText_loc4`='选择成为法师就是选择走上一条布满荆棘的险途。许多人都不理解我们。就连我们自己人都在艰难地接受我们的艺术。', `FemaleText_loc5`='選擇法師之道等同於選擇了一條艱苦的道路，因為許多人並不了解我們，而且連我們族人也還在適應接受我們。', `FemaleText_loc7`='Elegir el camino del mago es elegir un camino de gran dificultad. Muchos no nos comprenden. A nuestra propia gente le cuesta aceptar nuestras artes.' WHERE `ID`=44478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아바마마! 소자가 사슬을 풀어드리겠나이다.', `MaleText_loc4`='父亲！让我帮你除去那些锁链。', `MaleText_loc5`='父親!讓我解開你的枷鎖。', `MaleText_loc7`='¡Padre! Deja que te libere de esas cadenas.' WHERE `ID`=44479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 아이언포지를 도우려고 온 건가요? 아니면 온종일 저만 쳐다보려고 온 건가요?', `FemaleText_loc4`='你是来帮助铁炉堡的吗，还是要整天看着我发呆？', `FemaleText_loc5`='你是來協助鐵爐堡的，還是來跟我大眼瞪小眼的?', `FemaleText_loc7`='¿Has venido para ayudar a Forjaz, o para mirarme todo el día?' WHERE `ID`=44480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오염된 노움들이 뒤집어질 일이로군요! 정말 눈물 나게 반갑네요. 입구 쪽에 있는 용암 벌레 때문에 아무도 여기 못 들어올 줄 알았는데. 여기까지 오셨으니 절 좀 도와주실 수도 있겠죠?', `MaleText_loc4`='真是活见麻疯侏儒了！见到你真是太好了。我原本还在担心前面那只熔岩巨虫会把来访者都吓跑了。既然你来了，就来帮我一把。', `MaleText_loc5`='我的跳跳痲瘋地精啊!真高興見到你，我本來還很擔心前面那隻大熔岩蟲嚇跑訪客咧。既然你人都來了，就幫我個忙吧。', `MaleText_loc7`='¡Por los saltos de los gnomos parias! Dichosos los ojos. Temía que el gusano de magma gigante de ahí fuera asustara a los visitantes. Ya que estás aquí, me puedes echar una mano.' WHERE `ID`=44481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도 우리 열쇠가 필요하시겠지요? 잠깐, 얘기하지 마십시오. 제 뒤에서 씩씩거리며 자는 저 끔찍한 괴물이 열쇠를 집어삼킨 거죠?', `MaleText_loc4`='我想你得找把钥匙才能打开这笼子。等等，你该不是想告诉我，我身后那个吓人的怪物把钥匙给吃了？是吗？', `MaleText_loc5`='我想你應該會需要這個籠子的鑰匙吧?慢著，先別說。我後面那隻鬼吼鬼叫的怪物把它給吃了，對吧?', `MaleText_loc7`='Supongo que necesitas una llave para esta jaula, ¿no? Espera, no me lo digas. El horrible monstruo baboso que tengo a mis espaldas se la comió, ¿verdad?', `FemaleText_loc1`='아마도 우리 열쇠가 필요하시겠지요? 잠깐, 얘기하지 마세요. 제 뒤에서 씩씩거리며 자는 저 끔찍한 괴물이 열쇠를 집어삼킨 거죠?', `FemaleText_loc4`='我想你得找把钥匙才能打开这笼子。等等，你该不是想告诉我，我身后那个吓人的怪物把钥匙给吃了？是吗？', `FemaleText_loc5`='我想你應該會需要這個籠子的鑰匙吧?慢著，先別說。我後面那隻鬼吼鬼叫的怪物把它給吃了，對吧?', `FemaleText_loc7`='Supongo que necesitas una llave para esta jaula, ¿no? Espera, no me lo digas. El horrible monstruo baboso que tengo a mis espaldas se la comió, ¿verdad?' WHERE `ID`=44482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 내 백성들 모두 자네에게 진심으로 감사를 표하는 바네, $n.', `MaleText_loc4`='我们必须尽快找到世界之柱的中部碎片，返回大地神殿。', `MaleText_loc5`='我和我的同胞們衷心向你致上永恆的感謝，$n。', `MaleText_loc7`='Cuentas con mi gratitud eterna y la de mi gente, $n.' WHERE `ID`=44483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s|1이;가; 자신을 도울 |cFFFF0000타락의 추종자|r를 소환합니다!
', `MaleText_loc4`='|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s开始召唤|cFFFF0000腐蚀信徒|r来协助他！', `MaleText_loc5`='|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s開始召喚|cFFFF0000腐化中的擁護者|r來協助他!', `MaleText_loc7`='|TInterfaceIconsability_rogue_shadowdance.blp:20|t¡%s comienza a invocar |cFFFF0000partidarios en corrupción|r para que le ayuden!' WHERE `ID`=44484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C 친구, 이쪽이네.', `MaleText_loc4`='$n，到这儿来。', `MaleText_loc5`='$C，這邊。', `MaleText_loc7`='$C, por aquí.' WHERE `ID`=44485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 기둥 중간 파편이 있던 장소가 파헤쳐져 있고 파편은 보이지 않습니다!', `MaleText_loc4`='世界之柱的中部碎片已经被挖出来，然后不知所踪了！', `MaleText_loc5`='雖然世界之柱的中段碎片已經被挖出，但是目前下落不明!', `MaleText_loc7`='¡Han desenterrado el fragmento central del Pilar del Mundo y ha desaparecido!' WHERE `ID`=44486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주무실 곳이 필요하면 공짜로 침대를 제공해 드릴 수 있습니다. 아주 편하진 않지만, 어차피 잠을 오래 주무시는 분 같지도 않군요.', `MaleText_loc4`='要是你想休息，我能为你提供免费床位。虽然不怎么舒服，不过你也不像是个会花很多时间睡觉的人。', `MaleText_loc5`='想休息的話，我可以免費提供你一張床。不算很舒適，但我看你好像也沒怎麼睡的樣子。', `MaleText_loc7`='Si quieres descansar, te puedo ofrecer un catre. No es muy cómodo, pero tampoco parece que duermas mucho.', `FemaleText_loc1`='주무실 곳이 필요하면 공짜로 침대를 제공해 드릴게요. 아주 편하진 않지만, 어차피 잠을 오래 주무시는 분 같지도 않네요.', `FemaleText_loc4`='要是你想休息，我能为你提供免费床位。虽然不怎么舒服，不过你也不像是个会花很多时间睡觉的人。', `FemaleText_loc5`='想休息的話，我可以免費提供你一張床。不算很舒適，但我看你好像也沒怎麼睡的樣子。', `FemaleText_loc7`='Si quieres descansar, te puedo ofrecer un catre. No es muy cómodo, pero tampoco parece que duermas mucho.' WHERE `ID`=44487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 던 알가즈로 가던 중 놀들이 강 한가운데에서 트레샤돈을 사냥하는 것을 보았습니다. 그러고 보니 강아지 비슷하게 생긴 놈들이 창을 쓰는 걸 보신 적이 없죠? 그렇다면 한번 가서 구경해 보십시오!', `MaleText_loc4`='在我从丹奥加兹赶来的路上，我看见一只豺狼人正在湖心捕猎蛇颈龙。要是你从没见过狗使长矛的滑稽样，那你可有眼福了！', `MaleText_loc5`='在我從丹奧加茲來到這邊的路上，我看到有隻狗頭人在湖裡捕獵蛇頸龍。要是你從來沒看過狗拿長矛的樣子，你一定要去開開眼界!', `MaleText_loc7`='Cuando venía de Dun Algaz vi a un gnoll cazando trillanodontes en mitad de un lago. Si nunca has visto a un perro intentar usar una lanza, ¡te espera una sorpresa!' WHERE `ID`=44488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대랩터 여왕이 랩터 마루 깊숙한 곳에 자신의 알을 지키며 산다고 합니다.', `MaleText_loc4`='他们说迅猛龙女王就住在恐龙岭深处，守着她那些龙蛋。', `MaleText_loc5`='聽說迅猛龍的族母就住在恐龍嶺的深處，保護她的蛋。', `MaleText_loc7`='Dicen que la matriarca raptor vive en lo más profundo de la Colina del Raptor, protegiendo sus huevos.' WHERE `ID`=44489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 전에 웰가르의 발굴현장에 올라갔었습니다... 에... 그러니까 죽은 랩터의 뼈에서 티탄의 유물을 훔치려고 말이죠. 그런데 거기서 그놈을 봤습니다! 살투스가 살아 있더란 말입니다!

뭐, 언데드이니까 명확히는 살아 있는 게 아니지만, 그놈이 거기 있었단 말입니다. 살투스가 있었다고요!', `MaleText_loc4`='几天前我正在维尔加那儿……从迅猛龙尸骨堆里搜寻……泰坦圣物，然后我看见他了！萨尔图斯还活着！

好吧，他本来就是亡灵，说活着好像不太恰当，但反正他还在。萨尔图斯还在！', `MaleText_loc5`='幾天前我在維爾加挖掘場試著要....從迅猛龍的骨頭堆裡...呃...解放幾樣泰坦文物，然後我就看到了他!薩爾圖斯還活著! 

好吧，他變成了不死怪物，所以他並不算活著，但是他真的還在。薩爾圖斯還在!', `MaleText_loc7`='Fui a la Excavación de Whelgar hace unos días para... eh... liberar... algunas reliquias de los titanes de los huesos de los raptores muertos, ¡y lo vi! ¡Sarldente está vivo!

Bueno, es un no-muerto, así que supongo que no está vivo, pero existe. ¡Sarldente existe!' WHERE `ID`=44490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족은 성난송곳니 야영지를 몰아내려고 벌써 동쪽으로 짐마차를 타고 갔습니다. 그들은 공격을 지휘할 강력한 전사 두 명을 불러왔습니다. 만약 그들에게 도전해보고 싶다면, 그들이 작전과 전략을 구상하고, 오크다운 사악한 일을 꾸미는 야영장으로 가서 그들을 찾아보십시오.', `MaleText_loc4`='龙喉部族正在试图把势力扩大到怒牙营地以外的地方，并已对东边的车队发起了突袭。他们找来了两位强大的战士领军。要是你愿意接受挑战的话，你也许能在营地找到他们——那群正在策划密谋和从事其它邪恶活动的兽人。', `MaleText_loc5`='龍喉氏族正企圖擴張怒牙營地，而且已經在騷擾攻擊東邊往來的商隊。他們有兩位強壯的戰士在率領攻擊行動，若是你想接受挑戰的話，應該可以在怒牙營地裡找到他們。他們八成正忙著在計畫什麼邪惡的、獸人的事情。', `MaleText_loc7`='Los Faucedraco intentan salir del Campamento Dentellada y ya están asaltando una caravana al este. Han llamado a dos poderosos guerreros que lideran la carga. Si te apetece un desafío, puede que los encuentres en el campamento planeando, maquinando y haciendo más fechorías propias de los orcos.' WHERE `ID`=44491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슬레이트, 대지 가름 도끼가 당신에게 돌아왔습니까?', `MaleText_loc4`='岩幔国王，裂地之斧回到你手里了吗？', `MaleText_loc5`='史雷特，你的裂地之斧拿回來了沒?', `MaleText_loc7`='Pizarra, ¿ha vuelto aquí el hacha de hendimiento terrestre?', `FemaleText_loc1`='슬레이트, 대지 가름 도끼가 당신에게 돌아왔나요?', `FemaleText_loc4`='岩幔国王，裂地之斧回到你手里了吗？', `FemaleText_loc5`='史雷特，你的裂地之斧拿回來了沒?', `FemaleText_loc7`='Pizarra, ¿ha vuelto aquí el hacha de hendimiento terrestre?' WHERE `ID`=44492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 돌아왔네. 좀 더 조심히 다루게.$B$B왕의 도끼를 잃어 버려야 쓰겠나?', `MaleText_loc4`='是的。用它的时候要更加小心些。', `MaleText_loc5`='是啊，回來了。下回請小心點。$B$B我們可不想把國王的斧頭給搞丟了!', `MaleText_loc7`='Sí, así es. Intenta tener más cuidado con ella.$b$b¡No queremos perder el hacha del Rey!' WHERE `ID`=44493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신을 도울 수 없습니다. 상급 $c|1을;를; 찾아가십시오.', `MaleText_loc4`='我这里没有你要学的东西。去找$c训练师吧。', `MaleText_loc5`='我幫不上忙，請你去找一位$c訓練師。', `MaleText_loc7`='No puedo ayudarte con tu instrucción. Buscas un instructor $c.', `FemaleText_loc1`='저는 당신을 도울 수 없어요. 상급 $c|1을;를; 찾아가세요.', `FemaleText_loc4`='我这里没有你要学的东西。去找$c训练师吧。', `FemaleText_loc5`='我幫不上忙，請你去找一位$c訓練師。', `FemaleText_loc7`='No puedo ayudarte con tu instrucción. Buscas un instructor $c.' WHERE `ID`=44494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련받으러 오셨습니까, 사냥꾼님?', `MaleText_loc4`='你是来接受训练的吗，猎人？', `MaleText_loc5`='你是來接受訓練的嗎，獵人?', `MaleText_loc7`='¿Has venido para entrenar, $gcazador:cazadora;?', `FemaleText_loc1`='훈련받으러 오셨습니까, 사냥꾼님?', `FemaleText_loc4`='你是来接受训练的吗，猎人？', `FemaleText_loc5`='你是來接受訓練的嗎，獵人?', `FemaleText_loc7`='¿Has venido para entrenar, $gcazador:cazadora;?' WHERE `ID`=44495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 도움이 필요하다!', `MaleText_loc4`='Lok''tar！我们需要你的帮助！', `MaleText_loc5`='勇士!我們需要你的幫助!', `MaleText_loc7`='¡Lok''tar! ¡Necesitamos tu ayuda!' WHERE `ID`=44496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 멀록, 당신들의 도움으로 우리의 계획은 성공할 거야. 우리 코볼트 친구들이 광석을 아주 많이 구해줄 거라고...', `MaleText_loc4`='有了你们强大力量的支持，鱼人们，我们的计划必将取得成功。我们的狗头人朋友们会给我们挖出许多许多的矿石……', `MaleText_loc5`='有了你的力量，還有魚人，計畫一定會成功。我們的狗頭人朋友會幫我們挖好許多的礦...', `MaleText_loc7`='Con su fuerza, múrlocs, nuestro plan tendrá éxito. Nuestros amigos kóbolds excavarán muchos minerales...' WHERE `ID`=44497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 우리 놀이 만든 튼튼한 구리 무기로 무장하면, 그 누구도 멀록을 막을 수 없을 거야!', `MaleText_loc4`='并且，装备上出自豺狼人之手、由无坚不摧黄铜所铸造的武器，你们这些鱼人定将势不可挡！', `MaleText_loc5`='帶著狗頭人打造的無堅不摧的銅製武器，你們魚人將會橫掃一切!', `MaleText_loc7`='¡...Y, con las armas que forjen los gnolls con cobre indestructible, los múrlocs seréis imparables!' WHERE `ID`=44498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐였지? 그리고 도대체 이 냄새는 뭐야?', `MaleText_loc4`='那是什么？那见鬼的味道又是什么？', `MaleText_loc5`='那是什麼?那到底是什麼鬼味道?', `MaleText_loc7`='¿Qué ha sido eso? ¿Y qué demonios es ese olor?' WHERE `ID`=44499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...왜 그런 눈으로 날 쳐다보는 거야?', `MaleText_loc4`='……你干嘛那样看着我？', `MaleText_loc5`='...你為什麼要那樣看我?', `MaleText_loc7`='¿...Por qué me miráis así?' WHERE `ID`=44500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 후회하지 마! 이번이 마지막 기회라고, 이 붕어대가리야!', `MaleText_loc4`='你会后悔的！这是你唯一的机会，你这呆鱼！', `MaleText_loc5`='你會後悔的!這是你唯一的機會，你們這些蠢魚頭!', `MaleText_loc7`='¡Se arrepentirán! ¡Es su última oportunidad, necios asardinados!' WHERE `ID`=44501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아악! 이 망할 놈의 배신! 대충 눈치챘지만, 너무 갑작스럽잖아!', `MaleText_loc4`='噶啊啊啊——！诅咒你突然的背叛！诅咒你必然的背叛！', `MaleText_loc5`='啊啊啊啊呀!詛咒你們既突然又必然的反叛啊!', `MaleText_loc7`='¡AAAGH! ¡MALDITA SEA TU REPENTINA PERO INEVITABLE TRAICIÓN!' WHERE `ID`=44502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으에에에에에에! 도망가자!', `MaleText_loc4`='呃——！快跑！', `MaleText_loc5`='咿咿咿咿咿咿!逃啊!', `MaleText_loc7`='¡AAAAAAA! ¡CORRED!' WHERE `ID`=44503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*킁킁*', `MaleText_loc4`='*嗅一嗅*', `MaleText_loc5`='*聞一聞*', `MaleText_loc7`='*sniff sniff*' WHERE `ID`=44504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아옭옳옳옳옳옳옳옳옳.', `MaleText_loc4`='Rrglrglrglrglrgl。', `MaleText_loc5`='咕嚕咕嚕咕。', `MaleText_loc7`='Rrglrglrglrglrgl.' WHERE `ID`=44505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아옭옳옳옳옳옳옳옳옳!', `MaleText_loc4`='Rrglrglrglrglrgl！', `MaleText_loc5`='咕嚕咕嚕咕!', `MaleText_loc7`='¡Rrglrglrglrglrgl!' WHERE `ID`=44506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아옭옳옳옳옳옳옳옳옳!!', `MaleText_loc4`='RRGLRGLRGLRGLRLR！！', `MaleText_loc5`='嚕嚕咕嚕咕咕嚕咕嚕咕嚕!!', `MaleText_loc7`='¡¡RRGLRGLRGLRGLRLR!!' WHERE `ID`=44507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고고학은 사실을 추구하는 학문이다. 진실을 추구하는 게 아니라.', `MaleText_loc4`='考古学探究的是事实，而非真理。', `MaleText_loc5`='考古學研究的是事實，不是真理。', `MaleText_loc7`='La arqueología es la búsqueda de hechos, no de la verdad.' WHERE `ID`=44508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진실에 관심 있는 학생들은 커디 노드링거 교수의 철학 수업을 찾아가도록.', `MaleText_loc4`='如果你对真理感兴趣，卡迪·诺德林格主讲的哲学班就在大厅的另一端。', `MaleText_loc5`='如果你有興趣的是真理，那麼卡迪·諾林格的哲學課就在隔壁。', `MaleText_loc7`='Si lo que te interesa es la verdad, la clase de filosofía de Cuddy Nordlinger está al final del pasillo.' WHERE `ID`=44509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 잃어버린 도시나 이국적인 여행, 보물 발굴 따위는 잊어도 좋다.', `MaleText_loc4`='快忘了你那些关于失落的城市、奇妙的旅行以及把世界挖个底朝天的想法吧。', `MaleText_loc5`='所以請忘掉那些什麼失落的城市、異國的旅遊，還有到全世界探勘挖掘等等的可笑念頭。', `MaleText_loc7`='Así que olvídate de todas esas ideas sobre ciudades perdidas, viajes exóticos y excavaciones por todo el mundo.' WHERE `ID`=44510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지도를 따라 땅속에 묻힌 보물을 찾는 일은 없다. 또 지도상에 "X" 표시로 특정 위치를 나타내는 일도 절대 없다.', `MaleText_loc4`='你不能凭借地图来发掘那些深埋于地下的财宝，而且“X”永远、从来都不代表正确的位置。', `MaleText_loc5`='不會有地圖帶領你找出埋藏的寶藏，更不會有人在地上上劃個「X」來提示你。', `MaleText_loc7`='No habrá mapas que te conduzcan a un tesoro enterrado y "X" nunca, nunca marca el punto correcto.' WHERE `ID`=44511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고고학의 70퍼센트는 도서관에서 이루어진다. 바로 연구와 독서 작업이다.', `MaleText_loc4`='考古学有70%%是在图书馆里完成的。要研究。要阅读。', `MaleText_loc5`='考古學的研究有百分之七十是在圖書館裡頭進行。找資料、讀資料。', `MaleText_loc7`='El setenta por ciento de la arqueología se lleva a cabo en la biblioteca. Investigando. Leyendo.' WHERE `ID`=44512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신화를 있는 그대로 받아들여선 안 된다.', `MaleText_loc4`='我们不能把神话与票面价值划等号。', `MaleText_loc5`='神話往往不只是故事而已。', `MaleText_loc7`='No podemos permitirnos tomarnos la mitología al pie de la letra.' WHERE `ID`=44513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에헴! 흠... 아, 다음 주 주제는 "타나리스"다. 마본 리벳시커가 22년에 무너진 기둥을 발굴한 때부터 살펴보겠다.', `MaleText_loc4`='呃哼！嗯……啊，下一周——“塔纳利斯”。从玛尔冯·瑞文斯克在公元22年挖出破碎石柱的事情讲起。', `MaleText_loc5`='呃哼!好的...啊，下個禮拜是:塔納利斯。從22年瑪爾馮·瑞文斯克在破碎石柱的挖掘工作講起。', `MaleText_loc7`='¡Ejem! Bueno... Eh, la semana que viene: "Tanaris". Empezamos con la excavación del Pilar Partido por parte de Marvon Buscarroblones en el año 22.' WHERE `ID`=44514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 앞으로 한 시간 반 동안 도서관에서 책을 좀 보고 있을 테니, 혹시 물어보고 싶은 게 있으면 찾아오도록.', `MaleText_loc4`='我将在接下来的一个半小时里留在这儿做研究，要是谁有问题可以来找我。', `MaleText_loc5`='如果有人有問題要找我的話，接下來這一個半小時我都會在這邊做研究。', `MaleText_loc7`='Si alguien tiene algún problema en la siguiente hora y media, estaré aquí mismo, investigando.' WHERE `ID`=44515;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 해리슨 존스를 보며 속눈썹을 깜빡거립니다.', `FemaleText_loc4`='%s对着哈里森·琼斯眨着睫毛。', `FemaleText_loc5`='%s對哈里遜·瓊斯眨著她的眼睫毛。', `FemaleText_loc7`='%s bate las pestañas ante Harrison Jones.' WHERE `ID`=44516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고레크, 조율된 결속의 마법석을 새로 얻고 싶습니다.', `MaleText_loc4`='拉葛雷克，你能再给我一块调和过的禁锢符文石吗？', `MaleText_loc5`='勒苟雷克，你可以再給我一個同調的禁錮符石嗎?', `MaleText_loc7`='L''ghorek, ¿me puedes dar otra piedra rúnica armonizada de Vínculo?', `FemaleText_loc1`='고레크, 조율된 결속의 마법석을 새로 얻고 싶어요.', `FemaleText_loc4`='拉葛雷克，你能再给我一块调和过的禁锢符文石吗？', `FemaleText_loc5`='勒苟雷克，你可以再給我一個同調的禁錮符石嗎?', `FemaleText_loc7`='L''ghorek, ¿me puedes dar otra piedra rúnica armonizada de Vínculo?' WHERE `ID`=44517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것을... 잃어버리지... 말라.', `MaleText_loc4`='尽量……别丢了……那个。', `MaleText_loc5`='盡量不要...弄丟...那個。', `MaleText_loc7`='INTENTA... NO PERDER... ESTA.' WHERE `ID`=44518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웃습니다.', `FemaleText_loc4`='%s大笑起来。', `FemaleText_loc5`='%s哈哈大笑。', `FemaleText_loc7`='%s se ríe.' WHERE `ID`=44519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고고학을 훈련하러 왔습니까?', `MaleText_loc4`='你是来这儿学习考古的吗？', `MaleText_loc5`='你是來學習考古學的嗎?', `MaleText_loc7`='¿Has venido para recibir instrucción en arqueología?', `FemaleText_loc1`='고고학을 훈련하러 왔습니까?', `FemaleText_loc4`='你是来这儿学习考古的吗？', `FemaleText_loc5`='你是來學習考古學的嗎?', `FemaleText_loc7`='¿Has venido para recibir instrucción en arqueología?' WHERE `ID`=44520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 위습이 좋아요! 정말 예쁘다니까요!', `FemaleText_loc4`='我喜欢这些小精灵！真是太可爱了！', `FemaleText_loc5`='我好喜歡這些幽光!他們真是漂亮!', `FemaleText_loc7`='¡Me encantan los fuegos fatuos! ¡Son tan bonitos!' WHERE `ID`=44521;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용히 하렴, 이사라. 그렇게 떠들다가는 우리 둘 다 죽을지도 몰라.', `FemaleText_loc4`='安静点，伊莎娜。你的噪音快把我们吵死了。', `FemaleText_loc5`='安靜，伊薩拉，你這樣喋喋不休會害我們送命。', `FemaleText_loc7`='Silencio, Issara. Tu parloteo acabará por matarnos.' WHERE `ID`=44522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 성소 전당으로 침투했다!', `FemaleText_loc4`='入侵者已经攻破了圣殿大厅！', `FemaleText_loc5`='入侵者已突破了我們的神聖殿堂!', `FemaleText_loc7`='¡Los invasores han atravesado las puertas del sagrario!' WHERE `ID`=44523;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나, 이 멍청이들아! 적이 쳐들어왔다!', `FemaleText_loc4`='快醒醒你这傻瓜！我们被攻击了！', `FemaleText_loc5`='快醒醒，你們這樣笨蛋!我們遭到攻擊了!', `FemaleText_loc7`='¡Despierten, necios! ¡Nos atacan!' WHERE `ID`=44524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네더가드에 오신 걸 환영해요, $c님. 절 "왕언니"라고 불러 주세요. 당신을 돌봐 드리려고 여기 있는 거니까요.', `FemaleText_loc4`='欢迎来到守望堡，$c。你可以叫我“妈妈”，我会好好照顾你。', `FemaleText_loc5`='歡迎來到守望堡，$c。我是摩爾通媽媽，我負責在此照料你。', `FemaleText_loc7`='Bienvenido a Nethergarde, $c. Llámame "Mamá", estoy aquí para cuidar de ti.' WHERE `ID`=44525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대풍수사님, 의식을 치를 준비가 되었습니다.', `MaleText_loc4`='高阶地占师，我已为仪式做好了准备。', `MaleText_loc5`='大地卜師，我已經準備好進行儀式了。', `MaleText_loc7`='Archigeomántico, estoy listo para el ritual.', `FemaleText_loc1`='대풍수사님, 의식을 치를 준비가 되었어요.', `FemaleText_loc4`='高阶地占师，我已为仪式做好了准备。', `FemaleText_loc5`='大地卜師，我已經準備好進行儀式了。', `FemaleText_loc7`='Archigeomántico, estoy lista para el ritual.' WHERE `ID`=44526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음의 품에서 우리는 다시 태어난다.', `FemaleText_loc4`='死亡，令我们重生。', `FemaleText_loc5`='在死亡中，我們得以重生。', `FemaleText_loc7`='Renacemos en la muerte.' WHERE `ID`=44527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어비시온이 강력한 암흑 회오리를 시전하려 합니다. 대피하십시오!', `MaleText_loc4`='艾比希昂正在施放威力强大的暗影新星，快躲起来！', `MaleText_loc5`='艾碧希翁正在施展一道強大的暗影新星，尋找掩護!', `MaleText_loc7`='Abismion está lanzando una poderosa Nova de las Sombras. ¡Ponte a cubierto!' WHERE `ID`=44528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어비시온의 싸늘한 시체에서 첫 번째 세계 기둥 파편이 떨어집니다!', `MaleText_loc4`='只要杀了艾比希昂，就能拿到第一块世界之柱碎片！', `MaleText_loc5`='第一塊世界之柱碎片從艾碧希翁毫無生氣的屍體上落下!', `MaleText_loc7`='¡El primer fragmento del Pilar del Mundo cae del cuerpo sin vida de Abismion!' WHERE `ID`=44529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어비시온이 덫에 걸렸습니다! 계속 움직이면서 어비시온의 공격을 피하십시오.', `MaleText_loc4`='艾比希昂被困住了！保持移动以躲避他的攻击！', `MaleText_loc5`='艾碧希翁被困住了!保持移動，避開他的攻擊。', `MaleText_loc7`='¡Abismion está atrapado! No dejes de moverte para evitar sus ataques.' WHERE `ID`=44530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 아나? 상관없다. 네 뼈를 으스러뜨릴 테니까!', `MaleText_loc4`='我们认识吗？不要紧。我会压碎你的骨头！', `MaleText_loc5`='我有認識你嗎?隨便，我要打碎你的骨頭!', `MaleText_loc7`='¿Yo conocerte? No importar. ¡Yo aplastar tus huesos!' WHERE `ID`=44531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애애애애애애애...... 또 이렇겐!', `MaleText_loc4`='不——！别再来了！', `MaleText_loc5`='不不不不不不....不要又來一次!', `MaleText_loc7`='NOOOOOOOOOoooooo....... ¡Otra vez no!' WHERE `ID`=44532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈렌디스 초소 공격 지역을 벗어나면 안 됩니다!', `MaleText_loc4`='你必须待在塔伦迪斯营地攻击区域内！', `MaleText_loc5`='你必須待在塔倫迪斯營地的攻擊範圍裡!', `MaleText_loc7`='¡Debes permanecer en el interior de la zona de ataque de Punta Talrendis!' WHERE `ID`=44533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁한다! 다른 용들도 그물에서 풀어다오!', `MaleText_loc4`='拜托！把其他人也放出来！', `MaleText_loc5`='求求你!救救其他被網子困住的同伴!', `MaleText_loc7`='¡Por favor! ¡Libera a los demás de las redes!' WHERE `ID`=44534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 모두 풀어주면 그림 바톨 안에서 너희를 위해 날겠노라!', `MaleText_loc4`='一旦我们重获自由，我们将与你一同飞过格瑞姆巴托！', `MaleText_loc5`='等我們全都自由了，我們就會跟你一起飛越格瑞姆巴托!', `MaleText_loc7`='¡Cuando estemos todos libres, volaremos contigo por Grim Batol!' WHERE `ID`=44535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌연변이 고블린의 촉수가 떨어져 나가 땅 위를 기어갑니다!', `MaleText_loc4`='变异地精的触角掉了下来，在地上滚动！', `MaleText_loc5`='變種哥布林的觸鬚掙脫了，在地上爬來爬去!', `MaleText_loc7`='¡Los tentáculos del goblin mutante se liberan y se deslizan por el suelo!' WHERE `ID`=44536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 상급 $c|1을;를; 찾아가야겠군. 나는 자네에게 가르칠 게 없다네.', `MaleText_loc4`='你得去找别的训练师，$c。我帮不了你。', `MaleText_loc5`='我沒法子幫你，$c。你得去找別的訓練師。', `MaleText_loc7`='Vas a tener que busca''te otro instru''tor, $c. No puedo ayuda''te.' WHERE `ID`=44537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배우고 싶은 게 있으면 언제든 오게.', `MaleText_loc4`='需要接受训练可随时回来找我。', `MaleText_loc5`='需要訓練隨時來找我。', `MaleText_loc7`='Vuelve cuando necesites instru''ción.' WHERE `ID`=44538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조람가르 전초기지는 나의 지휘 아래 적의 공격에 맞서는 강력한 새 요새가 될 것이다!$B$B호드의 영광을 위하여!', `MaleText_loc4`='在我的坚守下，佐拉姆加一定会成为御敌入侵的新壁垒。$B$B为了部落的荣耀！', `MaleText_loc5`='佐拉姆加將在我的監督之下成為對抗敵人的新堡壘。$B$B榮耀歸於部落!', `MaleText_loc7`='Bajo mi liderazgo, Zoram''gar se convertirá en un nuevo bastión de poder contra nuestros enemigos.$b$b¡Gloria a la Horda!' WHERE `ID`=44539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이여;여;, 그대와 같은 영웅이 우리와 함께하신다니 영광입니다.', `FemaleText_loc4`='真荣幸能有你这样的英雄与我们同在，$n。', `FemaleText_loc5`='能有你這樣的英雄是我們的榮耀，$n。', `FemaleText_loc7`='Es un honor tener a $gun héroe:una heroína; como tú entre nosotros, $n.' WHERE `ID`=44540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 안 돼, 안 돼... 내 가족은 데려갔을지 몰라도, 내 땅은 못 가져가!', `MaleText_loc4`='不，不，不……你毁了我的家庭，但你别想夺走我的土地！', `MaleText_loc5`='不，不，不...你奪走了我的家人，但是你不能奪走我的土地!', `MaleText_loc7`='No, no, no... Me arrebataste a mi familia, ¡pero no me arrebatarás mi tierra!' WHERE `ID`=44541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라, $r!', `MaleText_loc4`='快回来，$r！', `MaleText_loc5`='退後，$r!', `MaleText_loc7`='¡Vuelve, $r!' WHERE `ID`=44542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우릴 내버려두지 않는 거냐?', `MaleText_loc4`='你能不能别来骚扰我们？', `MaleText_loc5`='為什麼你不肯放過我們?', `MaleText_loc7`='¿Por qué no nos dejas en paz?' WHERE `ID`=44543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주방에서 썩 꺼져!', `MaleText_loc4`='滚出我的厨房！', `MaleText_loc5`='從我的廚房滾出去!', `MaleText_loc7`='¡Sal de mi cocina!' WHERE `ID`=44544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 축복받은 삶을 살아온 게 분명하네, $n. 포세이큰과 연금술 학회의 일원으로 부활한 걸 보면 말일세... 내게 이보다 더 좋은 운명은 없을 걸세.', `MaleText_loc4`='我想我真是太好命了，$n。以被遗忘者和皇家药剂师协会成员的身份重回这个世界……我的命可真是好得无可挑剔。', `MaleText_loc5`='我生前必定做了很多善事，$n。竟然能以被遺忘者和藥劑師學會成員的身分重返這個世界...真是再適合我不過了。', `MaleText_loc7`='He debido llevar una vida estupenda, $n. Volver al mundo como Renegado y como miembro de la Sociedad de Boticarios... No podría haber deseado un destino más apropiado.' WHERE `ID`=44545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날... 놓아줘...', `MaleText_loc4`='放……我……走……', `MaleText_loc5`='讓...我...走...', `MaleText_loc7`='Déjame... marchar...' WHERE `ID`=44546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 죽음은... 잠시... 늦어질 뿐이다...', `MaleText_loc4`='你只是……在拖延……你的死期……', `MaleText_loc5`='你只是...拖延了...你的毀滅...', `MaleText_loc7`='Solo... prolongas... tu sufrimiento...' WHERE `ID`=44547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 불타오를... 것이다...', `MaleText_loc4`='你……将……燃尽……', `MaleText_loc5`='你...會被...燒死...', `MaleText_loc7`='Arderás...' WHERE `ID`=44548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈...', `MaleText_loc4`='混乱……', `MaleText_loc5`='混沌...', `MaleText_loc7`='Caos...' WHERE `ID`=44549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두... 부질없는... 짓이다...', `MaleText_loc4`='别白费……力气了……', `MaleText_loc5`='你的努力...徒勞無功...', `MaleText_loc7`='Tus esfuerzos... son inútiles...' WHERE `ID`=44550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드루이드들과 파수꾼들은 따로 있는 걸 선호합니다만, 항상 함께 일을 잘 해왔답니다.$B$B사생활을 중시하는 것일 뿐 서로 질색하는 건 아니랍니다.', `FemaleText_loc4`='德鲁伊和哨兵们喜欢各干各的，但我们的合作总是很默契。$B$B各自为政并不代表合不来。', `FemaleText_loc5`='德魯伊和哨兵雖然彼此保持獨立，但我們一直合作得很好。$B$B不要把獨立誤解成排斥。', `FemaleText_loc7`='Los druidas y las centinelas preferimos vivir por separado, pero siempre hemos trabajado bien juntos.$B$BNunca confundas la intimidad con la animadversión.' WHERE `ID`=44551;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참 아름다운 도시지 않나요? 전성기 때 길니아스도 그랬죠.$B$B우리도 그렇듯 그런 때는 지났어요. 대지와 대지의 비밀만 남았을 뿐이에요.$B$B$n 님, 드루이드의 길을 배우고자 하시나요?', `FemaleText_loc4`='真是座美丽的城市，对吧？这里当时叫做吉尔尼斯。$B$B但这都已经过去了，总有一天，我们也将成为历史。只有大地与她的秘密会永远留存。$B$B你是否愿意探究呢，$n？', `FemaleText_loc5`='這座城很漂亮是吧?吉爾尼斯曾經也是。$B$B但是這些俗事之物都會消失，包括我們也一樣。唯有大地和她的秘密會留下。$B$B你願意學習嗎，$n?', `FemaleText_loc7`='Es una ciudad hermosa, ¿no crees? Gilneas también lo fue, en su época.$b$bPero esas cosas pasan, como pasaremos $gnosotros:nosotras;. Solo quedarán la tierra y sus secretos.$b$b¿Estás $gdispuesto:dispuesta; a aprender, $n?' WHERE `ID`=44552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 이 정도는 되어야 활력 있다고 할 수 있지! 모든 물약이 이런 성능을 보였으면 좋겠군!', `MaleText_loc4`='那才叫做吸引力！我希望我们所有的药水都能产生那样的效果！', `MaleText_loc5`='這才「帶勁兒」嘛!希望我們所有的藥水都這麼夠味!', `MaleText_loc7`='¡ESO sí que es brío! ¡Ojalá todas nuestras pociones hicieran lo mismo!' WHERE `ID`=44553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비탑으로 올라가라!', `MaleText_loc4`='爬上哨塔！', `MaleText_loc5`='爬上衛兵哨塔!', `MaleText_loc7`='¡Sube por las torres!' WHERE `ID`=44554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포격할 때 저주받은 광석을 직접 사용하라!', `MaleText_loc4`='用被诅咒的矿石来引导炮火的攻击！', `MaleText_loc5`='使用厄運礦石來引導砲火!', `MaleText_loc7`='¡Utiliza la mena detestable para dirigir el fuego de la artillería!' WHERE `ID`=44555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 가시멧돼지는 너무 위험한 존재라 외부의 혼란에 휘말리게 내버려 둘 수는 없네, $r. 내 토템도 녀석들을 그리 오랫동안 막을 수는 없을 것 같군.$B$B자연의 이치에 반하는 놈들의 변화를 당장 막아야 하네.', `MaleText_loc4`='与外部冲突相比，激怒这里的野猪人太危险了，$r。我的图腾不能永远把他们挡在外面。$B$B我们必须终止他们侵害自然的行为。', `MaleText_loc5`='因外界的衝突而激怒這裡的野豬人實在太過危險，$r。我的圖騰無法永遠將他們阻絕。$B$B我們必須要阻止他們這種違背自然的惡行。', `MaleText_loc7`='Los jabaespines son demasiado peligrosos como para detenernos en conflictos exteriores, $r. Mi tótem no los mantendrá a raya eternamente.$b$bDebemos poner fin a sus transgresiones contra la naturaleza.' WHERE `ID`=44556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 함대 전체와 같이 왔구먼, $n! 그것도 성난 난폭파도 해적단 무리까지!$b$b자네가 전투태세를 갖췄길 바라네. 저 친구들은 분명히 단단히 무장하고 왔을 테니 말이야.', `MaleText_loc4`='看来你带来了整支舰队啊，$n！还找来一群愤怒的急浪成员！$b$b但愿你已经做好了战斗的准备，因为这些家伙可不是吃素的。', `MaleText_loc5`='看來你把整個艦隊通通一起帶來了，$n!連發飆的驟潮號都來了!$b$b我希望你已經準備好了，這些傢伙顯然是有備而來。', `MaleText_loc7`='¡Parece que te has traído toda la flota, $n! ¡Y una manada de Fuertemarea furiosos, por si fuera poco!$b$bEspero que te hayas preparado para la batalla, porque estos tipos vienen armados.' WHERE `ID`=44557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 지긋지긋하군! 수가 너무 많아!$b$b<잠시 한숨 돌리기 위해 말을 멈추는 시혼 함장>$b$b내가 무슨 말을 하는 거야? 별로 안 남았잖아! 이거나 먹어라, 더러운 똥개들아!', `MaleText_loc4`='我已经老了！他们人数太多了！$b$b<舰队指挥官卡拉·海角停下来喘了口气。>$b$b我在说什么？他们人数太少了！去死吧，你们这群下贱的杂种！', `MaleText_loc5`='我年紀大了、受不了了!他們的數量太多了!$b$b<艦隊指揮官海角停下來喘口氣。>$b$b我在說什麼啊?來再多也不夠我殺!混帳，看我的厲害!', `MaleText_loc7`='¡Me estoy haciendo viejo para estas cosas! ¡Son demasiados!$b$b<El maestro de flota Cuernomarino se detiene para recobrar el aliento.>$b$b¿Qué estoy diciendo? ¡Son demasiado pocos! ¡TOMEN ESTO, CHUCHOS ASQUEROSOS!' WHERE `ID`=44558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우우우! 아우우우! 해적이야말로 나를 위한 삶이라네.', `MaleText_loc4`='啊啊啊啊——噢噢噢噢！啊啊啊啊——噢噢噢噢！海盗即吾命。', `MaleText_loc5`='啊嗚!啊嗚!海盜生活我最愛。', `MaleText_loc7`='¡Aaaa-uuuuu! ¡Aaaa-uuuuu! Un gran pirata soy.' WHERE `ID`=44559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 약탈하고, 강탈하고, 양을 훔치고 싸운다네. 울부짖자 동료들이여. 아우우우우!', `MaleText_loc4`='我们抢劫，我们掠夺，我们无恶不作，干杯吧水手们——噢噢噢！', `MaleText_loc5`='我搶劫、我土匪，我偷羊又打架。吃吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Saqueamos, desvalijamos, robamos ovejas y luchamos,  aullen, compañeros. ¡Aaaa-uuuuu!' WHERE `ID`=44560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 유괴하고 유린하고 달빛아래서 분노한다네. 동료들이여 쭉 들이키세, 아우우우!', `MaleText_loc4`='我们借着月光去劫掠，去破坏，去席卷，干杯吧水手们，啊啊啊啊——噢噢噢！', `MaleText_loc5`='我綁票、我砸爛，我在月光下還抓狂。喝吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Secuestramos y asolamos y a la luna aullamos, beban compañeros. ¡Aaaa-uuuuu!' WHERE `ID`=44561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 무리의 우두머리, 우리는 무법자, 우리는 길니아스에서 왔다네. 울부짖자 동료들이여. 아우우우우!', `MaleText_loc4`='!我们是主宰，我们是玩客，我们来自吉尔尼斯，干杯吧水手们，啊啊啊啊——噢噢噢！', `MaleText_loc5`='我老大、我跟班，我來自吉爾尼斯。叫吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Somos alfas, somos chulos, y de Gilneas venimos, aullen compañeros. ¡Aaaa-uuuuu!' WHERE `ID`=44562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무법항을 접수하지 못하면 피랠론이 영영 자손을 못 보게 해 준다네, 울부짖자 동료들이여. 아우우우우!', `MaleText_loc4`='我们要夺下藏宝海湾，否则菲尔拉伦会要我们好看，怒吼吧，水手们，啊啊啊啊——噢噢噢！', `MaleText_loc5`='我們要拿下藏寶海灣，否則菲爾拉倫會狠狠教訓我們。吼吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Tomaremos Bahía del Botín o Firallon nos esterilizará, aullen, compañeros. ¡Aaaa-uuuuu!' WHERE `ID`=44563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 병 걸린 늑대, 우리는 헝클어진 털의 늑대, 우리는 늑대인간이라네, 울부짖자 동료들이여. 아우우우우!', `MaleText_loc4`='我们肮脏，我们邋遢，我们是狼人，干杯吧水手们，啊啊啊啊——噢噢噢！', `MaleText_loc5`='我毛毛、我髒髒，我狼人最愛叫。叫吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Somos sarnosos y pulgosos, somos huargen, qué te crees, aullen compañeros- ¡Aaa-uuuuuu!' WHERE `ID`=44564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새 맡고, 찢고, 물어뜯는 우리는 늑대인간이라네, 노래 부르세 동료들이여. 아우우우우!', `MaleText_loc4`='我们发现他们标记他们撕碎他们咀嚼他们，大声唱吧水手们，啊啊啊啊——噢噢噢！', `MaleText_loc5`='我會聞、我會抓，我剁來煮肉湯。唱吧兄弟!啊嗚嗚嗚!', `MaleText_loc7`='Los olemos y los marcamos y les arrancamos las tripas, canten compañeros. ¡Aaaa-uuuuu!' WHERE `ID`=44565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 그럴 리가요! 이런 간단한 기계 장치 따위에서야 쉽게 벗어날 수 있지만 제가 너무 바빠서 말이죠. 아세요? 일전에 제가 야수의 뱃속에서 몇 달을 보냈는데...', `MaleText_loc4`='什么？当然不是！这么简单的装置根本困不住我，可我没时间。看见没，就在不久前我还在一只猛兽的肚子里住了好几个月……', `MaleText_loc5`='什麼?當然不是!我輕輕鬆鬆就可以逃出這個簡單的東西，我只是太忙了而已。告訴你，前陣子我才在一頭巨獸的肚子裡待了幾個月...', `MaleText_loc7`='¿Qué? ¡Claro que no! Podría escapar de este sencillo artilugio sin dificultad, pero estoy demasiado ocupado. Verás, hace un tiempo pasé unos meses en el estómago de una bestia...' WHERE `ID`=44566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 붙잡혀 계셨죠. 저도 생각납니다. 이상하게도 지금 상황과 지나치게 비슷하군요.', `MaleText_loc4`='根据我的回忆，你被困住了。这情形相似得不可思议。', `MaleText_loc5`='我記得，你是被困住了。情況實在太雷同了。', `MaleText_loc7`='Estabas atrapado, creo recordar. Esta situación parece curiosamente similar.', `FemaleText_loc1`='네, 붙잡혀 계셨죠. 저도 생각납니다. 이상하게도 지금 상황과 지나치게 비슷하군요.', `FemaleText_loc4`='根据我的回忆，你被困住了。这情形相似得不可思议。', `FemaleText_loc5`='我記得，你是被困住了。情況實在太雷同了。', `FemaleText_loc7`='Estabas atrapado, creo recordar. Esta situación parece curiosamente similar.' WHERE `ID`=44567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 노리고 알아낸 거라고는 할 수 없지만, 어쨌든 제가 정말 대단한 사실을 발견했답니다. 저 야수는 뭘 집어삼켜도 전혀 탈이 안 나는 것 같아요.', `MaleText_loc4`='这并非出于完全自愿，可我有个令人难以置信的大发现。这野兽看来能消化一切，而且从不会产生不良反应。', `MaleText_loc5`='不全然是自願的，但是我發現了一件了不起的事情。那隻巨獸好像有辦法消化掉任何的東西，而且完全沒有不良的後果。', `MaleText_loc7`='No fue estrictamente voluntario, pero descubrí algo increíble. La bestia parecía ser capaz de consumir casi cualquier cosa sin efectos adversos.' WHERE `ID`=44568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예를 들자면... 용암 방열복 입은 노움 같은 거 말이죠?', `MaleText_loc4`='比如说，身穿熔岩装的侏儒。', `MaleText_loc5`='譬如，穿著熔岩服的地精。', `MaleText_loc7`='Gnomos en trajes de lava, por ejemplo.', `FemaleText_loc1`='예를 들자면... 용암 방열복 입은 노움 같은 거 말이죠?', `FemaleText_loc4`='比如说，身穿熔岩装的侏儒。', `FemaleText_loc5`='譬如，穿著熔岩服的地精。', `FemaleText_loc7`='Gnomos en trajes de lava, por ejemplo.' WHERE `ID`=44569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악에 받친 남작 게돈이 최후의 힘을 모아 당신을 살아 있는 폭탄으로 만들었습니다! 동료에게서 떨어지십시오!', `MaleText_loc4`='作为复仇计划的最后一步，迦顿男爵把你变成了一枚活动炸弹！离你的同伴远一点儿！', `MaleText_loc5`='作為報仇的最後手段，迦頓男爵把你變成了一顆活炸彈!遠離你的同伴!', `MaleText_loc7`='¡Como acto final de venganza, el barón Geddon te ha convertido en una bomba con patas! ¡Aléjate de tus aliados!' WHERE `ID`=44570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 소인족 투구를 썼으니 저들은 분명히 속아 넘어갈 거예요. 적어도 잠깐은요. 마을로 돌아가세요!', `FemaleText_loc4`='那个俾格米头盔应该能蒙住他们，至少能拖住一阵子。快回城！', `FemaleText_loc5`='那個俾格米盔帽應該騙得過他們，至少可以暫時騙一下。回城鎮吧!', `FemaleText_loc7`='Ese yelmo de pigmeo debería engañarlos, al menos por un tiempo. ¡Vuelve al pueblo!' WHERE `ID`=44571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거죠. 실험 삼아 저놈이 흘린 담즙을 이 방열복에 발라 봤는데...

<목소리가 잦아드는 핑클>

저기, 혹시 제 무두질용 손칼 어디선가 못 보셨나요? 제가 어디 이상한 데 놔뒀나 봐요.', `MaleText_loc4`='没错。我拿粘在我衣服上的残留消化液做了几个实验……

<芬克跑题了>

我说，你没见过我那把剥皮刀吧？我不知道放哪儿了。', `MaleText_loc5`='沒錯。我對還沾在我熔岩服上面的消化液做了點測試，然後...

<芬克拉長了語氣>

對了，你有沒有看到我的剝皮刀，有嗎?我好像把它搞丟了。', `MaleText_loc7`='Exacto. He realizado algunas pruebas en los residuos de fluido digestivo que cubrían mi traje y...

<Finkle pierde el hilo>

Dime, ¿has visto mi cuchillo para desollar por alguna parte? No sé dónde lo he dejado.' WHERE `ID`=44572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄, 아니요. 못 봤습니다. 무슨 얘기를 하고 계셨죠?', `MaleText_loc4`='不。我，呃，我没看见。你刚才说什么？', `MaleText_loc5`='沒有。我...呃...沒看到。你剛剛本來是要說?', `MaleText_loc7`='No, eh... No lo he visto. ¿Decías?', `FemaleText_loc1`='엄, 아니요. 못 봤어요. 무슨 얘기를 하고 계셨죠?', `FemaleText_loc4`='不。我，呃，我没看见。你刚才说什么？', `FemaleText_loc5`='沒有。我...呃...沒看到。你剛剛本來是要說?', `FemaleText_loc7`='No, eh... No lo he visto. ¿Decías?' WHERE `ID`=44573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 맞아요. 담즙 얘길 하고 있었죠. 놀라운 물질이더군요. 담즙과 함께 적당한 촉매만 사용하면 무엇이든 간에 말 그대로 불멸의 존재로 변한답니다. 그간 새로 프로그래밍한 담즙로봇 800으로 담즙을 모아서 실험했는데, 이번엔 정말 제대로 된 혼합액을 만들었다고 자부해요. 이제 혼합액을 적당한 생명체에게 실험해 보기만 하면 돼요. 자원자가 필요한데, 혹시 생각 있으세요?

<갑자기 목소리가 작아지는 핑클> 아, 위에서 정의한 "불멸의 존재"에게는 특정한 제한 조건이 따른다는 점 유의하시고요...', `MaleText_loc4`='哦是的，胆汁——真是种奇妙的物质。只要加上适当的催化剂，就能把与其接触到的任何物质变为不朽的存在*。我已经用我最可靠的胆汁喷洒机800采集到了这种物质，而且这次肯定取得了比例正确的混合物。现在缺少的只是几个志愿者，帮我找个合适的生物进行实验。你觉得怎么样，朋友？

*请注意“不朽”也是有局限的。', `MaleText_loc5`='哦，對了，膽汁。真是太神奇了。只要有適當的觸媒，它可以讓所有塗上這種膽汁東西變成不老不死（註）。我已經用重新設定好程式的「好膽 800」收集了一些，而且我確定這回我調配的方子肯定是對的。我只是需要幾個自願者幫我在合適的生物上進行測試。你覺得如何啊，朋友?

註:受某特條件之限制。', `MaleText_loc7`='Ah, sí, la bilis. Es fascinante. Con los catalizadores adecuados, hace que todo a lo que se aplica se vuelva prácticamente inmortal *. He estado recolectando con mi Bilistrón 800 reprogramado y esta vez estoy seguro de haber encontrado la mezcla correcta. Solo necesito unos pocos voluntarios para probarlo contra una criatura apropiada. ¿Qué me dices?

*Inmortalidad sujeta a ciertas restricciones.' WHERE `ID`=44574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송해요. 가르쳐 드릴 수 있는 게 없어요.', `FemaleText_loc4`='走开。我没能力也没兴趣教你什么。', `FemaleText_loc5`='走開。我沒這個本事，也沒這個心情指導你。', `FemaleText_loc7`='Largo. No tengo ni la capacidad ni la paciencia para instruirte.' WHERE `ID`=44575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적들의 부정하는 힘을 사용하는 방법을 배우도록 도와드릴게요.', `FemaleText_loc4`='我会教你学会运用令敌人无可抵挡的力量。', `FemaleText_loc5`='我會幫助你學習被我們敵人所阻絕的力量。', `FemaleText_loc7`='Te ayudaré a controlar los poderes que nuestros enemigos quieren negarnos.' WHERE `ID`=44576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제한 조건이요? 그게 뭡니까?', `MaleText_loc4`='局限？什么局限？', `MaleText_loc5`='條件?什麼條件?', `MaleText_loc7`='¿Restricciones? ¿Qué restricciones?', `FemaleText_loc1`='제한 조건이요? 그게 뭔데요?', `FemaleText_loc4`='局限？什么局限？', `FemaleText_loc5`='條件?什麼條件?', `FemaleText_loc7`='¿Restricciones? ¿Qué restricciones?' WHERE `ID`=44577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끔찍한 일입니다, 듀락! 헬스크림 님께서는 우리 배후에는 악마가 꿍꿍이가 있다고 확신하고 계십니다! 이제 어떻게 해야 합니까?', `MaleText_loc4`='这太可怕了，杜莱克！地狱咆哮坚信在我们这里潜藏着一个恶魔！我们该怎么办？！', `MaleText_loc5`='糟糕了，杜雷克!地獄吼相信我們這裡的事情是有惡魔在搞鬼!我們該怎麼辦?!', `MaleText_loc7`='¡Esto es terrible, Durak! ¡Grito Infernal está convencido de que hay un demonio tras nuestras acciones! ¿Qué podemos hacer?', `FemaleText_loc1`='정말 끔찍한 일이에요, 듀락! 헬스크림 님께서는 우리 배후에는 악마가 꿍꿍이가 있다고 확신하고 계세요! 이제 어떻게 해야 하죠?', `FemaleText_loc4`='这太可怕了，杜莱克！地狱咆哮坚信在我们这里潜藏着一个恶魔！我们该怎么办？！', `FemaleText_loc5`='糟糕了，杜雷克!地獄吼相信我們這裡的事情是有惡魔在搞鬼!我們該怎麼辦?!', `FemaleText_loc7`='¡Esto es terrible, Durak! ¡Grito Infernal está convencido de que hay un demonio tras nuestras acciones! ¿Qué podemos hacer?' WHERE `ID`=44578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 관여하셨다고 했나, 자네?', `MaleText_loc4`='你说地狱咆哮也牵涉其中了？', `MaleText_loc5`='你說，連地獄吼都扯進來了?', `MaleText_loc7`='¿Dices que Grito Infernal está involucrado?' WHERE `ID`=44579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 그렇다면 이제 한 가지 일만 남았군...', `MaleText_loc4`='嗯，那就只剩下一件事可干了……', `MaleText_loc5`='好吧，只剩下一件事情而已...', `MaleText_loc7`='Bueno, en ese caso solo queda una cosa por hacer...' WHERE `ID`=44580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간들이 계속해서 덤벼들고 있네! 놈들을 막아내야만 해! 길니아스의 시민들을 최대한 많이 구해내야만 한단 말이네!', `MaleText_loc4`='他们在不断地冲过来！把他们击退！我们必须尽力救出更多的吉尔尼斯人！', `MaleText_loc5`='他們還在來!擊退他們!我們要盡全力救出更多的吉爾尼斯百姓!', `MaleText_loc7`='¡Vienen más! ¡Recházenlos! ¡Tenemos que asegurarnos de que se salvan tantos gilneanos como sea posible!' WHERE `ID`=44581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 일이 내 생각보다 훨씬 빨리 일어났군.', `MaleText_loc4`='这一切来得比我预想中要早。', `MaleText_loc5`='我不喜歡這樣，事情發生得太快了。', `MaleText_loc7`='Todo esto está pasando antes de lo que me gustaría.' WHERE `ID`=44582;
