UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상업 지구에 있는 교역의 전당과 드워프 지구에 있는 스톰윈드 경매장, 두 곳의 경매장이 있습니다.', `MaleText_loc4`='总共有两个：一个是贸易区的交易者大厅，另一个是矮人区的暴风城拍卖行。', `MaleText_loc5`='總共有兩個:貿易區的貿易大廳，還有位在矮人區的暴風城拍賣場。', `MaleText_loc7`='Hay dos: la Sala de mercaderes en el Distrito de Mercaderes y la Casa de subastas de Ventormenta en el Distrito de los Enanos.', `FemaleText_loc1`='상업 지구에 있는 교역의 전당과 드워프 지구에 있는 스톰윈드 경매장, 두 곳의 경매장이 있습니다.', `FemaleText_loc4`='总共有两个：一个是贸易区的交易者大厅，另一个是矮人区的暴风城拍卖行。', `FemaleText_loc5`='總共有兩個:貿易區的貿易大廳，還有位在矮人區的暴風城拍賣場。', `FemaleText_loc7`='Hay dos: la Sala de mercaderes en el Distrito de Mercaderes y la Casa de subastas de Ventormenta en el Distrito de los Enanos.' WHERE `ID`=44588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이런 게 우리가 호드와 함께했을 때 나타났으면 하는 자세라고!', `MaleText_loc4`='这才是部落人该有的精神！', `MaleText_loc5`='等我們加入部落的時候，我就是要看到這種精神!', `MaleText_loc7`='¡Ese es el espíritu que esperaba ver cuando nos unimos a la Horda!' WHERE `ID`=44589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 영혼이 또 있군! 느낌이 아주 좋은데...', `MaleText_loc4`='又一个勇敢者！我对这个很有信心……', `MaleText_loc5`='又是一位勇氣十足的傢伙!我對這傢伙有種不錯的預感...', `MaleText_loc7`='¡Otra alma valiente! Con esta tengo un buen presentimiento...' WHERE `ID`=44590;
