UPDATE `locales_broadcast_text` SET `MaleText_loc1`='담즙로봇이 움직이기 시작하더니 고약한 냄새가 나는 물질을 방출합니다.', `MaleText_loc4`='胆汁喷洒机恢复运作，并开始喷射一种恶臭的物质。', `MaleText_loc5`='「好膽」機器人開始活動，並且噴出一種惡臭的物質。', `MaleText_loc7`='El Bilistrón se activa y empieza a emitir una sustancia de olor asqueroso.' WHERE `ID`=44593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장은 북쪽 단 근처, 드워프 지구의 최북단 구역에서 찾을 수 있습니다.', `MaleText_loc4`='你能在矮人区的最北边，城北降落点的附近找到那间拍卖行。', `MaleText_loc5`='它就在矮人區最北邊的小廣場，靠近城北平台那裡。', `MaleText_loc7`='La encontrarás en la parte norte del Distrito de los Enanos, cerca de la Puerta del Norte.', `FemaleText_loc1`='경매장은 북쪽 단 근처, 드워프 지구의 최북단 구역에서 찾을 수 있습니다.', `FemaleText_loc4`='你能在矮人区的最北边，城北降落点的附近找到那间拍卖行。', `FemaleText_loc5`='它就在矮人區最北邊的小廣場，靠近城北平台那裡。', `FemaleText_loc7`='La encontrarás en la parte norte del Distrito de los Enanos, cerca de la Puerta del Norte.' WHERE `ID`=44594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에는 상업 지구에 있는 스톰윈드 회계사무소와 드워프 지구에 있는 스톰윈드 왕실 은행, 두 곳의 은행이 있습니다.', `MaleText_loc4`='暴风城共有两个银行——分别是位于贸易区的暴风城会计室和位于矮人区的暴风城皇家银行。', `MaleText_loc5`='城裡有兩家銀行:貿易區的暴風城會計室，還有位在矮人區的暴風城皇家銀行。', `MaleText_loc7`='Hay dos bancos en la ciudad: la Contaduría de Ventormenta en el Distrito de Mercaderes, y el Banco Real de Ventormenta en el Distrito de los Enanos.', `FemaleText_loc1`='스톰윈드에는 상업 지구에 있는 스톰윈드 회계사무소와 드워프 지구에 있는 스톰윈드 왕실 은행, 두 곳의 은행이 있습니다.', `FemaleText_loc4`='暴风城共有两个银行——分别是位于贸易区的暴风城会计室和位于矮人区的暴风城皇家银行。', `FemaleText_loc5`='城裡有兩家銀行:貿易區的暴風城會計室，還有位在矮人區的暴風城皇家銀行。', `FemaleText_loc7`='Hay dos bancos en la ciudad: la Contaduría de Ventormenta en el Distrito de Mercaderes, y el Banco Real de Ventormenta en el Distrito de los Enanos.' WHERE `ID`=44595;
