UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 가장 유명한 여관은 상업 지구의 황금 장미와 드워프 지구의 황금 술통이랍니다.', `MaleText_loc4`='暴风城最热门的两个旅店分别坐落于贸易区与矮人区——镶金玫瑰旅店与黄金酒桶旅店。', `MaleText_loc5`='暴風城兩家最受歡迎的旅店分別坐落在貿易區和矮人區:鑲金玫瑰和黃金酒桶。', `MaleText_loc7`='Las dos posadas más populares de Ventormenta están en el Distrito de los Mercaderes y en el de los Enanos: La Rosa Áurea y El Tonel Dorado.', `FemaleText_loc1`='스톰윈드의 가장 유명한 여관은 상업 지구의 황금 장미와 드워프 지구의 황금 술통이랍니다.', `FemaleText_loc4`='暴风城最热门的两个旅馆分别坐落于贸易区与矮人区——镶金玫瑰旅店与黄金酒桶旅店。', `FemaleText_loc5`='暴風城兩家最受歡迎的旅店分別坐落在貿易區和矮人區:鑲金玫瑰和黃金酒桶。', `FemaleText_loc7`='Las dos posadas más populares de Ventormenta están en el Distrito de los Mercaderes y en el de los Enanos: La Rosa Áurea y El Tonel Dorado.' WHERE `ID`=44602;
