UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 술통은 드워프 지구의 북쪽 구역에 있습니다. 분수 바로 오른쪽이지요.', `MaleText_loc4`='黄金酒桶旅店位于矮人区的北部，就在喷泉旁边。', `MaleText_loc5`='黃金酒桶位於矮人區的北側，就在噴泉旁邊。', `MaleText_loc7`='El Tonel Dorado está en la zona norte del Distrito de los Enanos, justo al lado de la fuente.', `FemaleText_loc1`='황금 술통은 드워프 지구의 북쪽 구역에 있습니다. 분수 바로 오른쪽이지요.', `FemaleText_loc4`='黄金酒桶旅店位于矮人区的北部，就在喷泉旁边。', `FemaleText_loc5`='黃金酒桶位於矮人區的北側，就在噴泉旁邊。', `FemaleText_loc7`='El Tonel Dorado está en la zona norte del Distrito de los Enanos, justo al lado de la fuente.' WHERE `ID`=44605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 곳곳에 우체통이 깔렸습니다. 경매장, 은행 혹은 여관 앞에서도 찾아보실 수 있습니다.', `MaleText_loc4`='邮箱在城中随处可见。你在任何一间拍卖行、银行以及旅店门外都能找到。', `MaleText_loc5`='城裡到處都有郵箱。你可以在拍賣場、銀行還有旅店門口找到一個。', `MaleText_loc7`='Hay buzones repartidos por toda la ciudad. Puedes encontrar uno enfrente de todas las casas de subastas, bancos o posadas.', `FemaleText_loc1`='스톰윈드 곳곳에 우체통이 깔렸습니다. 경매장, 은행 혹은 여관 앞에서도 찾아보실 수 있습니다.', `FemaleText_loc4`='邮箱在城中随处可见。你在任何一间拍卖行、银行以及旅店门外都能找到。', `FemaleText_loc5`='城裡到處都有郵箱。你可以在拍賣場、銀行還有旅店門口找到一個。', `FemaleText_loc7`='Hay buzones repartidos por toda la ciudad. Puedes encontrar uno enfrente de todas las casas de subastas, bancos o posadas.' WHERE `ID`=44606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드에는 깊은굴 지하철부터 스톰윈드 왕궁까지 흥미로운 장소가 많습니다.$B$B어디를 찾으십니까?', `MaleText_loc4`='暴风城有许多特色景点，从矿道地铁到暴风要塞。$B$B你想去哪里呢？', `MaleText_loc5`='暴風城有許多有趣的景點，從礦道地鐵到暴風要塞，應有盡有。$B$B你想要去哪裡?', `MaleText_loc7`='Ventormenta cuenta con muchos lugares interesantes, como el Tranvía Subterráneo o el Castillo de Ventormenta.$b$b¿Qué buscabas?', `FemaleText_loc1`='스톰윈드에는 깊은굴 지하철부터 스톰윈드 왕궁까지 흥미로운 장소가 많답니다.$B$B어디를 찾으시나요?', `FemaleText_loc4`='暴风城有许多特色景点，从矿道地铁到暴风要塞。$B$B你想去哪里呢？', `FemaleText_loc5`='暴風城有許多有趣的景點，從礦道地鐵到暴風要塞，應有盡有。$B$B你想要去哪裡?', `FemaleText_loc7`='Ventormenta cuenta con muchos lugares interesantes, como el Tranvía Subterráneo o el Castillo de Ventormenta.$b$b¿Qué buscabas?' WHERE `ID`=44607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지와 드워프 지구에 야수 관리인이 있습니다.', `MaleText_loc4`='在旧城区与矮人区都能找到兽栏管理员。', `MaleText_loc5`='舊城區和矮人區都有獸欄管理員。', `MaleText_loc7`='Hay maestros de establos tanto en el Casco Antiguo como en el Distrito de los Enanos.', `FemaleText_loc1`='구 시가지와 드워프 지구에 야수 관리인이 있습니다.', `FemaleText_loc4`='在旧城区与矮人区都能找到兽栏管理员。', `FemaleText_loc5`='舊城區和矮人區都有獸欄管理員。', `FemaleText_loc7`='Hay maestros de establos tanto en el Casco Antiguo como en el Distrito de los Enanos.' WHERE `ID`=44608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 지구 야수 관리인', `MaleText_loc4`='矮人区兽栏管理员', `MaleText_loc5`='矮人區獸欄管理員', `MaleText_loc7`='Maestro de establos del Distrito de los Enanos', `FemaleText_loc1`='드워프 지구 야수 관리인', `FemaleText_loc4`='矮人区兽栏管理员', `FemaleText_loc5`='矮人區獸欄管理員', `FemaleText_loc7`='Maestro de establos del Distrito de los Enanos' WHERE `ID`=44609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지 야수 관리인', `MaleText_loc4`='旧城区兽栏管理员', `MaleText_loc5`='舊城區獸欄管理員', `MaleText_loc7`='Maestro de establos del Casco Antiguo', `FemaleText_loc1`='구 시가지 야수 관리인', `FemaleText_loc4`='旧城区兽栏管理员', `FemaleText_loc5`='舊城區獸欄管理員', `FemaleText_loc7`='Maestro de establos del Casco Antiguo' WHERE `ID`=44610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카린은 구 시가지의 뒤쪽 문을 통해 스톰윈드의 동쪽 끝에서 만날 수 있습니다.', `MaleText_loc4`='卡琳就在暴风城的最东边，穿过旧城区后部的门就能找到她。', `MaleText_loc5`='卡利在暴風城的最東邊，穿過舊城區後面的門口就能看到他。', `MaleText_loc7`='Puedes encontrar a Karin en la zona más al este de Ventormenta, al otro lado de las puertas que hay al fondo del Casco Antiguo.', `FemaleText_loc1`='카린은 구 시가지의 뒤쪽 문을 통해 스톰윈드의 동쪽 끝에서 만날 수 있습니다.', `FemaleText_loc4`='卡琳就在暴风城的最东边，穿过旧城区后部的门就能找到她。', `FemaleText_loc5`='卡利在暴風城的最東邊，穿過舊城區後面的門口就能看到他。', `FemaleText_loc7`='Puedes encontrar a Karin en la zona más al este de Ventormenta, al otro lado de las puertas que hay al fondo del Casco Antiguo.' WHERE `ID`=44611;
