UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='파도여, 고맙습니다. 돌아오셨군요! 다른 사람들은 모두 퇴각했습니다. 우리도 여기서 나가야 합니다!', `FemaleText_loc4`='感谢海浪的庇护，你终于回来了！别人都已经撤退，我们得离开这儿！', `FemaleText_loc5`='感謝浪潮，你回來了!其他人已經撤退了，我們得趕緊離開這裡!', `FemaleText_loc7`='¡Alabadas sean las olas, has vuelto! Los demás ya han huido, ¡tenemos que salir de aquí!' WHERE `ID`=44613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가 여사제가 지원군을 소환하는 의식을 거의 마치려고 합니다!', `MaleText_loc4`='纳迦女祭司们仿佛在召唤无穷无尽的援军！', `MaleText_loc5`='納迦女祭司像是在召喚永無止境的援軍!', `MaleText_loc7`='¡La sacerdotisa naga parece estar invocando una oleada casi interminable de refuerzos!' WHERE `ID`=44614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='습격은 그다지 피해를 주지 못했습니다. 나가들이 진형을 다시 가다듬었습니다!', `MaleText_loc4`='突袭似乎毫无效果。他们又稳住阵脚了！', `MaleText_loc5`='這場攻擊好像沒有造成任何的傷害。他們又重組好陣形了!', `MaleText_loc7`='Parece que el asalto apenas ha causado daño alguno. ¡Ya han vuelto a formar!' WHERE `ID`=44615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 너무 많더군요... 우리가 한 공격은 겨우 진형을 흐트러뜨렸을 뿐입니다. 많은 사람이 죽었어요! 일이 터지고야 말 거예요...', `FemaleText_loc4`='他们人数太多了……面对我们的袭击几乎毫发无损。而我们已经损失惨重！必须得想个办法……', `FemaleText_loc5`='太多了...我們的攻擊好像只是搔癢一樣，無法對他們造成實質的損傷。而且，我們損失太多人了!一定要想想辦法...', `FemaleText_loc7`='Había demasiados... Parece que nuestro asalto apenas ha afectado a sus filas. Hemos perdido tantos hombres... Tiene que haber servido para algo...' WHERE `ID`=44616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야수 놈들을 지옥으로 날려버리자!!', `MaleText_loc4`='把这些畜生打回地狱！', `MaleText_loc5`='把這些野獸轟回地獄!', `MaleText_loc7`='¡Devolved estas bestias al infierno!' WHERE `ID`=44617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 계속 몰려온다! 현 위치를 사수하라!', `MaleText_loc4`='一波接一波！坚守阵地！', `MaleText_loc5`='他們又繼續來了!堅守崗位!', `MaleText_loc7`='¡No dejan de venir! ¡Aguanten!' WHERE `ID`=44618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 저지하라! 길니아스를 위하여!', `MaleText_loc4`='击退他们！为了吉尔尼斯！', `MaleText_loc5`='擋住他們!吉爾尼斯萬歲!', `MaleText_loc7`='¡Resistid! ¡Por Gilneas!' WHERE `ID`=44619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각자의 위치를 최대한 사수하라!', `MaleText_loc4`='尽全力死守你们的阵地！', `MaleText_loc5`='盡全力堅守崗位!', `MaleText_loc7`='¡Mantengan sus posiciones todo el tiempo que puedan!' WHERE `ID`=44620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라가!', `MaleText_loc4`='上天啰！', `MaleText_loc5`='上去!', `MaleText_loc7`='¡Arriba!' WHERE `ID`=44621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격받고 있네!', `MaleText_loc4`='我们遭到攻击了！', `MaleText_loc5`='我們遭到攻擊了!', `MaleText_loc7`='¡Nos atacan!' WHERE `ID`=44622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가는 포기하지 않을 걸세. 동료를 찾아 함께 싸워야 하네.', `MaleText_loc4`='纳迦不会就此罢休。我们得集结盟友的力量，把他们彻底击退！', `MaleText_loc5`='納迦他們不會就此放棄。我們得找出我們的朋友，化被動為主動。', `MaleText_loc7`='Los nagas no se rendirán. Tenemo'' que encontrar a nueh''tros amigos y lucha'' junto a ellos.' WHERE `ID`=44623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 에루낙을 따라가겠습니다... 혼자서라도요!', `MaleText_loc4`='我去找埃鲁纳克……必要的话我只能自己去！', `MaleText_loc5`='我要追隨伊魯納克進去...就算只有我一個人也得去!', `MaleText_loc7`='Voy tras Erunak... ¡Solo, si es necesario!' WHERE `ID`=44624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렘트래블 님께서는 거의 40여 년간 고고학계에서 영웅이셨어요. 그분이 일화들을 기억하실 수 있다면... 오, 그분이 얘기해 주셨을 이야기들...', `MaleText_loc4`='雷塔维在过去的近四十年里一直都是考古界的英雄。要是他还记得它们，哦，他要讲的那些故事……', `MaleText_loc5`='雷姆塔維爾是考古學界近40年來的英雄人物。要是他想得起來的話，哦，故事一定超精采的...', `MaleText_loc7`='Tripirrem ha sido un héroe del mundo de la arqueología desde hace casi 40 años. Ah, las historias que podría contar, si pudiera recordarlas...' WHERE `ID`=44625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그를 따라가야 할 것 같군.$b$b이대로 헬스크림 님을 뵙는 것보다야 낫겠지...', `MaleText_loc4`='嗯，我想我应该跟他进去。$b$b再没有比在这时候去面对地狱咆哮更坏的事情了……', `MaleText_loc5`='好吧，看來我也應該跟著他進去裡面。$b$b反正不會有比面對地獄吼更糟糕的了...', `MaleText_loc7`='Bueno, supongo que podría ir tras él.$b$bNo puede ser peor que presentarse ante Grito Infernal después de esto...' WHERE `ID`=44626;
