UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 파괴된 공원과 더불어 그 안에 있던 애처롭고 운이 없었던 영혼들인 나이트 엘프 대부분을 찾는 거라면... 가장 좋은 방법은 드워프 지구 바로 밖에 있는 옛 셀레스틴을 찾는 걸 겁니다.$B$B북쪽 단에서부터 아래로 이어지는 계단이 있습니다. 그곳에서 그녀의 작은 집을 볼 수 있습니다.', `MaleText_loc4`='暴风城花园,连带着住在花园里的大部分暗夜精灵都一起被摧毁了。那些可怜又不幸的灵魂啊！所以你最好还是到矮人区外边去找老塞莱斯廷吧。$B$B在城北降落点有通往下方的阶梯……你在那儿就能看见她的小屋。', `MaleText_loc5`='暴風城的花園已經被毀，而且許多位夜精靈也因此而不幸喪生。現在最有可能找到老塞雷斯坦的地方就在矮人區的外面。$B$B城北廣場有道往下的樓梯...你可以在那邊看到他的小屋。', `MaleText_loc7`='Tras la destrucción del parque de Ventormenta (y de la muerte de la mayoría de los elfos de la noche que vivían dentro, pobres desgraciados), tu mejor alternativa es buscar a la vieja Celestina, justo fuera del Distrito de los Enanos.$b$bHay unas escaleras que bajan de la Puerta del Norte... Puedes ver su cabaña desde allí.', `FemaleText_loc1`='스톰윈드의 파괴된 공원과 더불어 그 안에 있던 애처롭고 운이 없었던 영혼들인 나이트 엘프 대부분을 찾는 거라면... 가장 좋은 방법은 드워프 지구 바로 밖에 있는 옛 셀레스틴을 찾는 걸 겁니다.$B$B북쪽 단에서부터 아래로 이어지는 계단이 있습니다. 그곳에서 그녀의 작은 집을 볼 수 있습니다.', `FemaleText_loc4`='暴风城花园,连带着住在花园里的大部分暗夜精灵都一起被摧毁了。那些可怜又不幸的灵魂啊！所以你最好还是到矮人区外边去找老塞莱斯廷吧。$B$B在城北降落点有通往下方的阶梯……你在那儿就能看见她的小屋', `FemaleText_loc5`='暴風城的花園已經被毀，而且許多位夜精靈也因此而不幸喪生。現在最有可能找到老塞雷斯坦的地方就在矮人區的外面。$B$B城北廣場有道往下的樓梯...你可以在那邊看到他的小屋。', `FemaleText_loc7`='Tras la destrucción del parque de Ventormenta (y de la muerte de la mayoría de los elfos de la noche que vivían dentro, pobres desgraciados), tu mejor alternativa es buscar a la vieja Celestina, justo fuera del Distrito de los Enanos.$b$bHay unas escaleras que bajan de la Puerta del Norte... Puedes ver su cabaña desde allí.' WHERE `ID`=44630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지의 사령부와 드워프 지구에서 사냥꾼 훈련을 받을 수 있습니다.', `MaleText_loc4`='在旧城区指挥部与矮人区里都能找到猎人训练师。', `MaleText_loc5`='矮人區和舊城區的指揮所裡頭都有獵人訓練師。', `MaleText_loc7`='Hay unos cazadores entrenándose en el Centro de Mando del Casco Antiguo y en el Distrito de los Enanos.', `FemaleText_loc1`='구 시가지의 사령부와 드워프 지구에서 사냥꾼 훈련을 받을 수 있습니다.', `FemaleText_loc4`='在旧城区指挥部与矮人区里都能找到猎人训练师。', `FemaleText_loc5`='矮人區和舊城區的指揮所裡頭都有獵人訓練師。', `FemaleText_loc7`='Hay unos cazadores entrenándose en el Centro de Mando del Casco Antiguo y en el Distrito de los Enanos.' WHERE `ID`=44631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 지구 상급 사냥꾼', `MaleText_loc4`='矮人区猎人训练师', `MaleText_loc5`='矮人區獵人訓練師', `MaleText_loc7`='Instructor de cazadores del Distrito de los Enanos', `FemaleText_loc1`='드워프 지구 상급 사냥꾼', `FemaleText_loc4`='矮人区猎人训练师', `FemaleText_loc5`='矮人區獵人訓練師', `FemaleText_loc7`='Instructor de cazadores del Distrito de los Enanos' WHERE `ID`=44632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지 상급 사냥꾼', `MaleText_loc4`='旧城区猎人训练师', `MaleText_loc5`='舊城區獵人訓練師', `MaleText_loc7`='Instructor de cazadores del Casco Antiguo', `FemaleText_loc1`='구 시가지 상급 사냥꾼', `FemaleText_loc4`='旧城区猎人训练师', `FemaleText_loc5`='舊城區獵人訓練師', `FemaleText_loc7`='Instructor de cazadores del Casco Antiguo' WHERE `ID`=44633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지의 동쪽 문 바로 바깥에서 상급 사냥꾼들 여럿을 만날 수 있습니다.', `MaleText_loc4`='你在旧城区的东门外总能看到几位猎人。', `MaleText_loc5`='舊城區的東門外面經常會有些獵人在那邊。', `MaleText_loc7`='Siempre hay un grupo de cazadores justo en el exterior de la puerta este del Casco Antiguo.', `FemaleText_loc1`='구 시가지의 동쪽 문 바로 바깥에서 상급 사냥꾼들 여럿을 만날 수 있습니다.', `FemaleText_loc4`='你在旧城区的东门外总能看到几位猎人。', `FemaleText_loc5`='舊城區的東門外面經常會有些獵人在那邊。', `FemaleText_loc7`='Siempre hay un grupo de cazadores justo en el exterior de la puerta este del Casco Antiguo.' WHERE `ID`=44634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공원', `MaleText_loc4`='花园', `MaleText_loc5`='花園', `MaleText_loc7`='El Parque', `FemaleText_loc1`='공원', `FemaleText_loc4`='花园', `FemaleText_loc5`='花園', `FemaleText_loc7`='El Parque' WHERE `ID`=44635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공원이요?$B$B거긴 폐허가 되었습니다. 못 들으셨나요? 거대한 용인 데스윙이 스톰윈드로 날아들어 와 도시를 파괴했습니다.$B$B솔직히 데스윙이 왜 모든 걸 파괴하지 않았는진 모르겠습니다. 하지만 우리는 모두 빛의 이름으로 그가 모두 파괴하지 않을 걸 감사하게 생각합니다.', `MaleText_loc4`='花园……？$B$B已经变成废墟了。你没听说吗？巨龙死亡之翼从暴风城上空掠过，顺便把它给毁了。$B$B老实说，我不懂他为什么没夷平整座城市，但感谢圣光，幸好他没这么干。', `MaleText_loc5`='花園...?$B$B花園已經毀了，你沒聽說嗎?巨龍死亡之翼在飛過暴風城上空的時候把那裡給毀了。$B$B坦白講，不曉得他為什麼沒有把整座城都給毀了，但是我們全都很感謝聖光，還好他沒有這麼做。', `MaleText_loc7`='¿El Parque?$b$bEstá en ruinas. ¿No te has enterado? El gran dragón Alamuerte sobrevoló Ventormenta y lo destruyó a su paso.$b$bNo estoy seguro de por qué no destruyó toda la ciudad, la verdad, pero todos le agradecemos a la Luz que no lo hiciera.', `FemaleText_loc1`='공원이요?$B$B거긴 폐허가 되었습니다. 못 들으셨나요? 거대한 용인 데스윙이 스톰윈드로 날아들어 와 도시를 파괴했습니다.$B$B솔직히 데스윙이 왜 모든 걸 파괴하지 않았는진 모르겠습니다. 하지만 우리는 모두 빛의 이름으로 그가 모두 파괴하지 않을 걸 감사하게 생각합니다.', `FemaleText_loc4`='花园……？$B$B已经变成废墟了。你没听说吗？巨龙死亡之翼从暴风城上空掠过，顺便把它给毁了。$B$B老实说，我不懂他为什么没夷平整座城市，但感谢圣光，幸好他没这么干。', `FemaleText_loc5`='花園...?$B$B花園已經毀了，你沒聽說嗎?巨龍死亡之翼在飛過暴風城上空的時候把那裡給毀了。$B$B坦白講，不曉得他為什麼沒有把整座城都給毀了，但是我們全都很感謝聖光，還好他沒有這麼做。', `FemaleText_loc7`='¿El Parque?$b$bEstá en ruinas. ¿No te has enterado? El gran dragón Alamuerte sobrevoló Ventormenta y lo destruyó a su paso.$b$bNo estoy segura de por qué no destruyó toda la ciudad, la verdad, pero todos le agradecemos a la Luz que no lo hiciera.' WHERE `ID`=44636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 왕궁', `MaleText_loc4`='暴风要塞', `MaleText_loc5`='暴風要塞', `MaleText_loc7`='Castillo de Ventormenta', `FemaleText_loc1`='스톰윈드 왕궁', `FemaleText_loc4`='暴风要塞', `FemaleText_loc5`='暴風要塞', `FemaleText_loc7`='Castillo de Ventormenta' WHERE `ID`=44637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁은 스톰윈드의 북쪽에 있습니다.$B$B북쪽 운하를 따라가면 왕궁의 마당으로 이어지는 도개교를 발견할 겁니다.', `MaleText_loc4`='要塞位于暴风城北部。$B$B沿着运河向北前行，你就会看到一座吊桥……通往要塞庭院。', `MaleText_loc5`='要塞坐落在暴風城北。$B$B只要沿著運河往北走，你就會經過一座吊橋...通往要塞的中庭。', `MaleText_loc7`='El castillo está en la zona norte de Ventormenta.$b$bSigue los canales hacia el norte y acabarás cruzando un puente levadizo. Conduce al patio del castillo.', `FemaleText_loc1`='왕궁은 스톰윈드의 북쪽에 있습니다.$B$B북쪽 운하를 따라가면 왕궁의 마당으로 이어지는 도개교를 발견할 겁니다.', `FemaleText_loc4`='要塞位于暴风城北部。$B$B沿着运河向北前行，你就会看到一座吊桥……通往要塞庭院。', `FemaleText_loc5`='要塞坐落在暴風城北。$B$B只要沿著運河往北走，你就會經過一座吊橋...通往要塞的中庭。', `FemaleText_loc7`='El castillo está en la zona norte de Ventormenta.$b$bSigue los canales hacia el norte y acabarás cruzando un puente levadizo. Conduce al patio del castillo.' WHERE `ID`=44638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 지하감옥', `MaleText_loc4`='监狱', `MaleText_loc5`='監獄', `MaleText_loc7`='Las Mazmorras', `FemaleText_loc1`='스톰윈드 지하감옥', `FemaleText_loc4`='监狱', `FemaleText_loc5`='監獄', `FemaleText_loc7`='Las Mazmorras' WHERE `ID`=44639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감옥이라고요? 왜 그곳으로 가고 싶어 하는 겁니까? 지하감옥은 스톰윈드의 중앙에 있습니다. 바로 마법사 지구의 북동쪽이지요.$B$B정말로 그곳으로 가려는 거라면, 조심하십시오. 폭동이 일어났다는 얘기를 들었습니다.', `MaleText_loc4`='监狱？你干吗要去那儿？就在城中央，法师区的东北部。$B$B你要是真去可一定要小心。听说最近发生了不少暴动事件。', `MaleText_loc5`='監獄?為什麼你會想要去那裡?它位在暴風城的正中間，就在法師區的東北邊。$B$B假如你真的想去那裡的話，請多加小心，我有聽到暴動的消息。', `MaleText_loc7`='¿La prisión? ¿Para qué ibas a querer ir allí? Está en el centro de la ciudad, justo al noreste del Barrio de los Magos.$b$bSi vas a ir de verdad, ten cuidado. Han llegado noticias de unos disturbios.', `FemaleText_loc1`='감옥이라고요? 왜 그곳으로 가고 싶어 하는 겁니까? 지하감옥은 스톰윈드의 중앙에 있습니다. 바로 마법사 지구의 북동쪽이지요.$B$B정말로 그곳으로 가려는 거라면, 조심하십시오. 폭동이 일어났다는 얘기를 들었습니다.', `FemaleText_loc4`='监狱？你干吗要去那儿？就在城中央，法师区的东北部。$B$B你要是真去可一定要小心。听说最近发生了不少暴动事件。', `FemaleText_loc5`='監獄?為什麼你會想要去那裡?它位在暴風城的正中間，就在法師區的東北邊。$B$B假如你真的想去那裡的話，請多加小心，我有聽到暴動的消息。', `FemaleText_loc7`='¿La prisión? ¿Para qué ibas a querer ir allí? Está en el centro de la ciudad, justo al noreste del Barrio de los Magos.$b$bSi vas a ir de verdad, ten cuidado. Han llegado noticias de unos disturbios.' WHERE `ID`=44640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐마차가 공격에 노출됐다. 내가 뒤돌아서야겠군!', `MaleText_loc4`='车队没有防护——我回来了！', `MaleText_loc5`='商隊沒有受到保護—我要回頭!', `MaleText_loc7`='¡La caravana está desprotegida! ¡Yo me vuelvo!' WHERE `ID`=44641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송하지만, 전 당신을 가르쳐 드릴 수 없어요.', `FemaleText_loc4`='对不起，我无法对你进行训练。', `FemaleText_loc5`='很抱歉，我無法訓練你。', `FemaleText_loc7`='Lo siento, no puedo enseñarte.' WHERE `ID`=44642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 도와드릴까요, $c님?', `FemaleText_loc4`='我能帮你什么忙吗，$c？', `FemaleText_loc5`='有什麼我能幫忙的嗎，$c?', `FemaleText_loc7`='¿Cómo puedo ayudarte, $c?' WHERE `ID`=44643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 전부터 아제로스 곳곳에서 정령이 소란을 일으키고 있다는 보고를 받고 있습니다. 분명히 자연적인 현상이 아님에도 저희는 아직 문제의 정확한 원인을 찾지 못했지요. 몇 가지 이론이 제기되었지만 모두 확실치 않습니다.$B$B정령들의 수상한 움직임에 주의를 기울여야 합니다. 그리고 혹시 유용한 정보를 발견하게 되면 우리 대지 고리회 사절에게 알려 주십시오. 저희 대지 고리회 사절은 아무 대도시에서나 찾을 수 있습니다.$B$B몸조심하십시오. 아무래도 곧 소동이 일어날 것 같습니다.', `MaleText_loc4`='近来我们不断收到在艾泽拉斯各地出现元素扰动的报告。消息表明这并不完全是自然现象，但我们还没能追溯到源头。尽管已经有一些猜测，可现在下定论还为时过早。$B$B提高警惕，在冒险途中留心任何可疑的元素活动。要是你找到任何有价值的信息，请及时告知大地之环使者。你在任何主城都能与我们取得联系。$B$B睁大双眼。危机在临近。', `MaleText_loc5`='我們已陸陸續續接到了不少的報告，說有元素在艾澤拉斯各地騷動。而且我們的情報來源還指出，它們並非全是自然發生的現象，只是我們尚未找出明確的成因。我們是有一些理論，但依舊缺乏明確的答案。$B$B當你在外旅行冒險的時候，請睜大眼睛注意是否有任何可疑的元素活動。假如你發現了任何值得關注的消息，請告知陶土議會的特使。我們在各大主城都有派駐代表。$B$B請你睜大眼睛，動亂正在醞釀。', `MaleText_loc7`='Hace tiempo que recibimos informes de perturbaciones elementales por todo Azeroth. Nuestras fuentes indican que no se trata de un fenómeno del todo natural, pero no hemos sido capaces de determinar el origen. Tenemos algunas teorías, pero nada concreto.$B$BEstate al tanto por si ves cualquier actividad elemental sospechosa mientras viajas. Si encuentras algo digno de mención, cuéntaselo a un emisario del Anillo de la Tierra. Puedes encontrarnos en cualquier capital.$B$BTen cuidado. Se acercan problemas.', `FemaleText_loc1`='얼마 전부터 아제로스 곳곳에서 정령이 소란을 일으키고 있다는 보고를 받고 있습니다. 분명히 자연적인 현상이 아님에도 저희는 아직 문제의 정확한 원인을 찾지 못했지요. 몇 가지 이론이 제기되었지만 모두 확실치 않습니다.$B$B정령들의 수상한 움직임에 주의를 기울여야 합니다. 그리고 혹시 유용한 정보를 발견하게 되면 우리 대지 고리회 사절에게 알려 주십시오. 저희 대지 고리회 사절은 아무 대도시에서나 찾을 수 있습니다.$B$B몸조심하십시오. 아무래도 곧 소동이 일어날 것 같습니다.', `FemaleText_loc4`='近来我们不断收到在艾泽拉斯各地出现元素扰动的报告。消息表明这并不完全是自然现象，但我们还没能追溯到源头。尽管已经有一些猜测，可现在下定论还为时过早。$B$B提高警惕，在冒险途中留心任何可疑的元素活动。要是你找到任何有价值的信息，请及时告知大地之环使者。你在任何主城都能与我们取得联系。$B$B睁大双眼。危机在临近。', `FemaleText_loc5`='我們已陸陸續續接到了不少的報告，說有元素在艾澤拉斯各地騷動。而且我們的情報來源還指出，它們並非全是自然發生的現象，只是我們尚未找出明確的成因。我們是有一些理論，但依舊缺乏明確的答案。$B$B當你在外旅行冒險的時候，請睜大眼睛注意是否有任何可疑的元素活動。假如你發現了任何值得關注的消息，請告知陶土議會的特使。我們在各大主城都有派駐代表。$B$B請你睜大眼睛，動亂正在醞釀。', `FemaleText_loc7`='Hace tiempo que recibimos informes de perturbaciones elementales por todo Azeroth. Nuestras fuentes indican que no se trata de un fenómeno del todo natural, pero no hemos sido capaces de determinar el origen. Tenemos algunas teorías, pero nada concreto.$B$BEstate al tanto por si ves cualquier actividad elemental sospechosa mientras viajas. Si encuentras algo digno de mención, cuéntaselo a un emisario del Anillo de la Tierra. Puedes encontrarnos en cualquier capital.$B$BTen cuidado. Se acercan problemas.' WHERE `ID`=44644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루가 다르게 아제로스의 정령계가 불안정한 상태가 되어가고 있네. 이런 현상의 원인이 바로 여기 나그란드에 있지. 드레노어가 파괴되었을 때 정령계가 분열되었고, 아직도 정령계는 완전히 회복하지 못했다네. 자연적으로 균열이 생겨났고 이는 심각하게 손상된 세계를 상징하지.$B$B이와 똑같은 붕괴 현상이 아제로스에 발생하고 있다는 사실은 불안한 현상일 뿐만 아니라 세계가 아직 한 번도 겪지 못한 파괴의 전조일 수도 있다네.$B$B$n, 아웃랜드를 탐험하다가 발견하는 어떤 정보라도 내게 알려주게.$B$B나는 여기서 정령을 연구하며 아제로스의 정령계를 다시 안정시킬 방법을 찾아야 하니... 너무 늦기 전에 말일세.', `MaleText_loc4`='随着时间的推移，艾泽拉斯的元素变得越发躁动。平息这躁动的关键就在此地——纳格兰。当德拉诺分崩离析之时，所有元素位面都陷入了极大的混乱之中，再也没有恢复平静。这里的裂隙是自然形成的，也彰显着大地所遭受的重创。$B$B在艾泽拉斯看到像这样的崩裂之景并不仅会让人心神不宁，还可能预示着一场前所未见的大毁灭将降临在这个世界上。$B$B$n，把你在外域找到的任何有用信息都带回来给我。$B$B我必须花些时间来解决这里的元素问题，想办法让艾泽拉斯的元素再次平静下来……再晚就来不及了。', `MaleText_loc5`='艾澤拉斯的元素正一天比一天變得更加兇暴。它們會變成這樣的原因就在這，納葛蘭。當德拉諾被摧毀時，所有的元素界域都遭到了牽連，沒有被治癒。這裡的裂隙是自然形成的，象徵了這個受到嚴重創傷的世界。$B$B看到艾澤拉斯也開始出現這種跡象是非常令人不安的，這可以是這世界即將遭受前所未有的災難前的一個徵兆。$B$B$n，把任何你在外域看到或找到的情報告知於我。$B$B我必須待在這觀察這些元素，尋找能夠安撫艾澤拉斯元素的方法...在還來得及之前。', `MaleText_loc7`='Los elementos de Azeroth se alteran más con cada día que pasa. La clave de la perturbación está aquí, en Nagrand. Cuando Draenor se quebró, todos los planos elementales cayeron en un gran caos del que nunca se han recuperado. Las fallas del lugar se forman naturalmente y son señal de un mundo gravemente dañado.$B$BVer el mismo tipo de perturbación en Azeroth no es solo preocupante; podría ser el inicio de un tipo de destrucción que el mundo no ha experimentado jamás.$B$B$n, tráeme toda la información que encuentres mientras viajas por Terrallende.$B$BYo debo quedarme con los elementos, para investigar una forma de calmarlos de nuevo en Azeroth... Antes de que sea demasiado tarde.' WHERE `ID`=44645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 점점 더 심각해지는 아제로스 정령계의 붕괴 현상에 대한 해결책을 찾고 있어요. 여기 나그란드에서도 똑같은 균열이 생겨났지만, 이는 드레노어의 붕괴에 따른 직접적인 결과입니다. 균열은 쇠약해진 행성과 정령계의 격변을 상징하지요.$B$B하지만 아제로스의 현상에는 뚜렷한 이유가 없습니다.$B$B아제로스를 탐험하다 어떤 정보라도 발견하면 우리에게 알려주세요. 우리는 여기서 정령들과 계속 대화하며 아제로스의 정령을 진정시킬 방법을 찾아야 하니까요... 너무 늦기 전에 말입니다.', `MaleText_loc4`='我们在设法让艾泽拉斯日渐躁动的元素重归平静。这里——在纳格兰，我们看到了同样的裂隙正在形成，但这些是作为德拉诺破碎的直接后果而出现的。它们是星球日渐衰弱和元素位面产生巨变的标志。$B$B但是，在艾泽拉斯，却找不到令人信服的解释。$B$B当你在外域冒险时，要是你能找到任何与这些裂隙相关的信息，记得来告知我们。我们将继续在此与元素对话，争取找到能使艾泽拉斯元素平静下来的办法……再晚就来不及了。', `MaleText_loc5`='在納葛蘭，我們正為了越來越多元素的騷亂尋求解決之道。我們曾經看過一樣的裂隙，直接的結果就是德拉諾被夷為平地。已經有徵兆顯示出星球的弱化和元素界域的動亂。$B$B但在艾澤拉斯，我們還是沒有辦法提出合理的解釋。$B$B如果你在外域的旅程中發現任何與這些裂隙有關的消息，請讓我們知道。我們會繼續在這與元素們溝通，尋求一個安撫艾澤拉斯元素的方法...在還來得及之前。', `MaleText_loc7`='Estamos intentando encontrar una solución para las perturbaciones elementales de Azeroth. Aquí, en Nagrand, se forman las mismas fallas, pero son consecuencia directa de la destrucción de Draenor. Es señal de un planeta debilitado, y de un plano elemental sumido en el caos.$B$BEn Azeroth, por otra parte, no tienen explicación razonable.$B$BSi encuentras cualquier información sobre estas fallas mientras viajas por Terrallende, cuéntanoslo. Nosotros seguiremos hablando con los elementos de la zona y buscando una forma de calmar a los de Azeroth... Antes de que sea demasiado tarde.' WHERE `ID`=44646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공', `MaleText_loc4`='珠宝加工', `MaleText_loc5`='珠寶設計', `MaleText_loc7`='Joyería', `FemaleText_loc1`='보석세공', `FemaleText_loc4`='珠宝加工', `FemaleText_loc5`='珠寶設計', `FemaleText_loc7`='Joyería' WHERE `ID`=44647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 상업 지구와 대운하 사이에 있는 덴만가 보석상에 당신이 찾는 모든 게 있을 겁니다.', `MaleText_loc4`='位于贸易区与运河间的登曼家族珠宝，你在那里应该可以找到所有想要找的东西。', `MaleText_loc5`='丹門家族珠寶店，位於北貿易區和運河之間，那應該有你想要的東西。', `MaleText_loc7`='Los joyeros de la familia Denman, entre el lado norte del Distrito de los Mercaderes y los Canales, deberían tener todo lo que buscas.', `FemaleText_loc1`='북쪽 상업 지구와 대운하 사이에 있는 덴만가 보석상에 당신이 찾는 모든 게 있을 겁니다.', `FemaleText_loc4`='位于贸易区与运河间的登曼家族珠宝，你在那里应该可以找到所有想要找的东西。', `FemaleText_loc5`='丹門家族珠寶店，位於北貿易區和運河之間，那應該有你想要的東西。', `FemaleText_loc7`='Los joyeros de la familia Denman, entre el lado norte del Distrito de los Mercaderes y los Canales, deberían tener todo lo que buscas.' WHERE `ID`=44648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고고학', `MaleText_loc4`='考古学', `MaleText_loc5`='考古學', `MaleText_loc7`='Arqueología', `FemaleText_loc1`='고고학', `FemaleText_loc4`='考古学', `FemaleText_loc5`='考古學', `FemaleText_loc7`='Arqueología' WHERE `ID`=44649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 왕궁의 왕실 도서관에 있는 해리슨 존스가 밖으로 나가 있지 않을 땐 고고학을 가르쳐 준답니다.', `MaleText_loc4`='除了外出实地考察外，哈里森·琼斯平时都在暴风要塞的皇家图书馆里教授考古学。', `MaleText_loc5`='哈里遜·瓊斯如果沒有出去進行調查，他都會在暴風要塞的皇家圖書館裡教授考古學。', `MaleText_loc7`='Cuando no trabaja sobre el terreno, Harrison Jones enseña arqueología en el Archivo Real del Castillo de Ventormenta.', `FemaleText_loc1`='스톰윈드 왕궁의 왕실 도서관에 있는 해리슨 존스가 밖으로 나가 있지 않을 땐 고고학을 가르쳐 준답니다.', `FemaleText_loc4`='除了外出实地考察外，哈里森·琼斯平时都在暴风要塞的皇家图书馆里教授考古学。', `FemaleText_loc5`='哈里遜·瓊斯如果沒有出去進行調查，他都會在暴風要塞的皇家圖書館裡教授考古學。', `FemaleText_loc7`='Cuando no trabaja sobre el terreno, Harrison Jones enseña arqueología en el Archivo Real del Castillo de Ventormenta.' WHERE `ID`=44650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 기술 상인들은 언제나 각 기술 전문가들 근처에서 만날 수 있습니다. 다른 상인들은 스톰윈드 전역에 흩어져 있습니다.$B$B어떤 물건을 찾으시나요?', `MaleText_loc4`='专业技能供应商总是待在对应的专业技能训练师附近。其它商贩则遍布暴风城的各个角落。$B$B你要买什么？', `MaleText_loc5`='專業技能商人一定能在相應的訓練師附近找到。其他的商人則散佈於暴風城各個角落。$B$B你在找的是什麼?', `MaleText_loc7`='Los vendedores de profesión siempre se encuentran cerca de sus respectivos instructores. Los demás vendedores están repartidos por todo Ventormenta.$b$b¿Qué buscas?', `FemaleText_loc1`='전문 기술 상인들은 언제나 각 기술 전문가들 근처에서 만날 수 있습니다. 다른 상인들은 스톰윈드 전역에 흩어져 있습니다.$B$B어떤 물건을 찾으시나요?', `FemaleText_loc4`='专业技能供应商总是待在对应的专业技能训练师附近。其它商贩则遍布暴风城的各个角落。$B$B你要买什么？', `FemaleText_loc5`='專業技能商人一定能在相應的訓練師附近找到。其他的商人則散佈於暴風城各個角落。$B$B你在找的是什麼?', `FemaleText_loc7`='Los vendedores de profesión siempre se encuentran cerca de sus respectivos instructores. Los demás vendedores están repartidos por todo Ventormenta.$b$b¿Qué buscas?' WHERE `ID`=44651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사의 전당', `MaleText_loc4`='勇士大厅', `MaleText_loc5`='勇士大廳', `MaleText_loc7`='La Sala de los Campeones', `FemaleText_loc1`='용사의 전당', `FemaleText_loc4`='勇士大厅', `FemaleText_loc5`='勇士大廳', `FemaleText_loc7`='La Sala de los Campeones' WHERE `ID`=44652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사의 전당은 구 시가지의 남동쪽 끝에 있습니다.$B$B명예와 정복 병참장교들을 그곳에서 찾을 수 있습니다.', `MaleText_loc4`='勇士大厅位于旧城区的东南端。$B$B荣誉与战利品军需官就在那里。', `MaleText_loc5`='勇士大廳位於舊城區東南邊的盡頭。$B$B榮譽紋章與征服點數軍需官都在裡頭。', `MaleText_loc7`='La Sala de los Campeones se encuentra en el extremo sureste del Casco Antiguo.$b$bAllí encontrarás a los intendentes de honor y conquista.', `FemaleText_loc1`='용사의 전당은 구 시가지의 남동쪽 끝에 있습니다.$B$B명예와 정복 병참장교들을 그곳에서 찾을 수 있습니다.', `FemaleText_loc4`='勇士大厅位于旧城区的东南端。$B$B荣誉与战利品军需官就在那里。', `FemaleText_loc5`='勇士大廳位於舊城區東南邊的盡頭。$B$B榮譽紋章與征服點數軍需官都在裡頭。', `FemaleText_loc7`='La Sala de los Campeones se encuentra en el extremo sureste del Casco Antiguo.$b$bAllí encontrarás a los intendentes de honor y conquista.' WHERE `ID`=44653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의와 용맹 병참장교', `MaleText_loc4`='英雄及勇气军需官', `MaleText_loc5`='正義與勇氣點數軍需官', `MaleText_loc7`='Intendentes de justicia y valor', `FemaleText_loc1`='정의와 용맹 병참장교', `FemaleText_loc4`='英雄及勇气军需官', `FemaleText_loc5`='正義與勇氣點數軍需官', `FemaleText_loc7`='Intendentes de justicia y valor' WHERE `ID`=44654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지의 남동쪽 문 바로 밖에 있는 사령부에서 병참장교들을 만날 수 있습니다.', `MaleText_loc4`='军需官就在位于旧城区东南门外的指挥部里。', `MaleText_loc5`='在指揮所裡，就在舊城區東南門的外面，軍需官就在那邊。', `MaleText_loc7`='Encontrarás a los intendentes en el Centro de mando, justo antes de la puerta sureste del Casco Antiguo.', `FemaleText_loc1`='구 시가지의 남동쪽 문 바로 밖에 있는 사령부에서 병참장교들을 만날 수 있습니다.', `FemaleText_loc4`='军需官就在位于旧城区东南门外的指挥部里。', `FemaleText_loc5`='在指揮所裡，就在舊城區東南門的外面，軍需官就在那邊。', `FemaleText_loc7`='Encontrarás a los intendentes en el Centro de mando, justo antes de la puerta sureste del Casco Antiguo.' WHERE `ID`=44655;
