UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마구간지기', `MaleText_loc4`='养马人', `MaleText_loc5`='馬匹飼養師', `MaleText_loc7`='Criador de caballos', `FemaleText_loc1`='마구간지기', `FemaleText_loc4`='养马人', `FemaleText_loc5`='馬匹飼養師', `FemaleText_loc7`='Criador de caballos' WHERE `ID`=44657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구 시가지의 남동쪽 문을 지나면 마구간이 있습니다. 그곳에서 마구간지기와 전문 기수를 만나실 수 있습니다.', `MaleText_loc4`='马厩就在旧城区东南门边上。你在那里能找到骑术训练师与养马人。', `MaleText_loc5`='舊城區的東南城門外就有一座馬廄，騎術訓練師和馬匹飼養師都在那裡。', `MaleText_loc7`='Hay establos justo al otro lado de las puertas sureste del Casco Antiguo. Allí encontrarás un instructor de equitación y un criador de caballos.', `FemaleText_loc1`='구 시가지의 남동쪽 문을 지나면 마구간이 있습니다. 그곳에서 마구간지기와 전문 기수를 만나실 수 있답니다.', `FemaleText_loc4`='马厩就在旧城区东南门边上。你在那里能找到骑术训练师与养马人。', `FemaleText_loc5`='舊城區的東南城門外就有一座馬廄，騎術訓練師和馬匹飼養師都在那裡。', `FemaleText_loc7`='Hay establos justo al otro lado de las puertas sureste del Casco Antiguo. Allí encontrarás un instructor de equitación y un criador de caballos.' WHERE `ID`=44658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 조련사', `MaleText_loc4`='狮鹫管理员', `MaleText_loc5`='獅鷲獸養殖師', `MaleText_loc7`='Cuidador de grifos', `FemaleText_loc1`='그리핀 조련사', `FemaleText_loc4`='狮鹫管理员', `FemaleText_loc5`='獅鷲獸養殖師', `FemaleText_loc7`='Cuidador de grifos' WHERE `ID`=44659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출격실로 갈 수만 있으면 좋겠어요. 그 어여쁜 비행기가 정말 딱 한 대만 있으면, 제 손으로 놈리건을 되찾을 수 있어요! 물론 B.E 버랙허스가 눈알이 빠지도록 겁에 질리게 할 수 있고요!$B$B낙하산이 더 필요하세요? 낙하지점 근처에 있는 상자에 몇 개 보관해 뒀어요.', `MaleText_loc4`='要是我能到得了发射台，再给我一架那种美轮美奂的飞机——只需一架，我就能夺回诺莫瑞根，并把“坏脾气”巴拉克斯的眼镜给吓得掉下来！$B$B如果你还需要降落伞的话，我们在降落点附近的箱子里存了一些。', `MaleText_loc5`='要是我能去發射台就好了。給我一架漂亮的空中寶貝，一架就夠了，我一定可以奪回諾姆瑞根，而且把怪怪頭嚇得連護目鏡都掉下來!$B$B如果你需要另外一副降落傘，我們在降落區的箱子裡面有幾套後備的。', `MaleText_loc7`='Si pudiera llegar al Aeropuerto... Dame una, solo una, de esas preciosas máquinas voladoras y podría recuperar Gnomeregan y darle un susto de muerte a M. E. Barrecus al mismo tiempo.$b$bSi necesitas otro paracaídas, tenemos algunos en los cofres cercanos a los puntos de lanzamiento.' WHERE `ID`=44660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 조련사를 찾을 수 있는 상업 지구 끝자락의 그리핀 횃대를 아십니까?$B$B와일드해머 드워프 둘이 그곳에서 모여 그리핀 비행 요금을 받습니다. 게다가 그들이 당신에게 짐승을 탈 수 있도록 훈련시켜줄 수도 있지요.', `MaleText_loc4`='你知道贸易区那边的狮鹫栖息地吗，就是飞行管理员所在的地方？$B$B有几个蛮锤矮人正在那儿饲养和贩售狮鹫，他们还能教你学会骑乘这种坐骑。', `MaleText_loc5`='你知道獅鷲獸棲息處其實是在貿易區嗎?就在飛行管理員那裡。$B$B有兩位蠻錘氏族的矮人在那邊飼養和販賣獅鷲獸，甚至還能訓練你該怎樣駕馭牠們。', `MaleText_loc7`='¿Conoces la percha de grifo del Distrito de Mercaderes, donde suele estar el maestro de vuelo?$b$bAllí hay un par de enanos Martillo Salvaje que crían y venden grifos, y hasta te pueden enseñar a montarlos.', `FemaleText_loc1`='비행 조련사를 찾을 수 있는 상업 지구 끝자락의 그리핀 횃대를 아십니까?$B$B와일드해머 드워프 둘이 그곳에서 모여 그리핀 비행 요금을 받습니다. 게다가 그들이 당신에게 짐승을 탈 수 있도록 훈련시켜줄 수도 있지요.', `FemaleText_loc4`='你知道贸易区那边的狮鹫栖息地吗，就是飞行管理员所在的地方？$B$B有几个蛮锤矮人正在那儿饲养和贩售狮鹫，他们还能教你学会骑乘这种坐骑。', `FemaleText_loc5`='你知道獅鷲獸棲息處其實是在貿易區嗎?就在飛行管理員那裡。$B$B有兩位蠻錘氏族的矮人在那邊飼養和販賣獅鷲獸，甚至還能訓練你該怎樣駕馭牠們。', `FemaleText_loc7`='¿Conoces la percha de grifo del Distrito de Mercaderes, donde suele estar el maestro de vuelo?$b$bAllí hay un par de enanos Martillo Salvaje que crían y venden grifos, y hasta te pueden enseñar a montarlos.' WHERE `ID`=44661;
