UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 쉴 수 있을 거라 생각했지 뭡니까. 어리석게도요.', `MaleText_loc4`='我想我恐怕得稍微休息一会儿。我可真没用。', `MaleText_loc5`='我以為還可以休息一會兒呢。太天真了。', `MaleText_loc7`='Y yo que pensaba que podría descansar un poco. Qué tonto.', `FemaleText_loc1`='좀 쉴 수 있을 거라 생각했지 뭡니까. 어리석게도요.', `FemaleText_loc4`='我想我恐怕得稍微休息一会儿。我可真没用。', `FemaleText_loc5`='我以為還可以休息一會兒呢。太天真了。', `FemaleText_loc7`='Y yo que pensaba que podría descansar un poco. Qué tonta.' WHERE `ID`=44673;
