UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 바위 어머니와 한편이 되어 싸울 수 있어 정말 기쁩니다.', `MaleText_loc4`='我真高兴这次竟然能和石母并肩作战。', `MaleText_loc5`='很高興聽到這回我們能夠和石母一起並肩作戰。', `MaleText_loc7`='Me alegra saber que esta vez lucharemos junto a la Madre Pétrea en persona.', `FemaleText_loc1`='이번엔 바위 어머니와 한편이 되어 싸울 수 있어 정말 기쁩니다.', `FemaleText_loc4`='我真高兴这次竟然能和石母并肩作战。', `FemaleText_loc5`='很高興聽到這回我們能夠和石母一起並肩作戰。', `FemaleText_loc7`='Me alegra saber que esta vez lucharemos junto a la Madre Pétrea en persona.' WHERE `ID`=44679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그쪽 야영지가 계속 눈에 밟히던 참이었습니다. 이번엔 확실히 처리하죠.', `MaleText_loc4`='那营地一直在试图得到我们的关注。我们去解决这件事。', `MaleText_loc5`='我們早就該去處理掉那個營地了。做個了結吧。', `MaleText_loc7`='Ese campamento nos está pidiendo atención a gritos. Hagámoslo.', `FemaleText_loc1`='그쪽 야영지가 계속 눈에 밟히던 참이었습니다. 이번엔 확실히 처리하죠.', `FemaleText_loc4`='那营地一直在试图得到我们的关注。我们去解决这件事。', `FemaleText_loc5`='我們早就該去處理掉那個營地了。做個了結吧。', `FemaleText_loc7`='Ese campamento nos está pidiendo atención a gritos. Hagámoslo.' WHERE `ID`=44680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 듣고 싶던 말입니다. 가시죠.', `MaleText_loc4`='这正是我想要听到的。出发吧。', `MaleText_loc5`='正合我意。走吧。', `MaleText_loc7`='Justo lo que quería oír. Vamos.', `FemaleText_loc1`='제가 듣고 싶던 말입니다. 가시죠.', `FemaleText_loc4`='这正是我想要听到的。出发吧。', `FemaleText_loc5`='正合我意。走吧。', `FemaleText_loc7`='Justo lo que quería oír. Vamos.' WHERE `ID`=44681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다. 바로 그쪽으로 가겠습니다.', `MaleText_loc4`='明白。我这就去。', `MaleText_loc5`='瞭解。我會立刻趕到那裡。', `MaleText_loc7`='Entendido. Ahora mismo voy.', `FemaleText_loc1`='잘 알겠습니다. 바로 그쪽으로 가겠습니다.', `FemaleText_loc4`='明白。我这就去。', `FemaleText_loc5`='瞭解。我會立刻趕到那裡。', `FemaleText_loc7`='Entendido. Ahora mismo voy.' WHERE `ID`=44682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축복받은 태양의 온기가 너의 핏속을 흐른다!', `MaleText_loc4`='让太阳温暖的祝福像暖流一般流遍你的全身！', `MaleText_loc5`='日光的暖意在你體內流動!', `MaleText_loc7`='¡La calidez bendita del sol corre por tus venas!' WHERE `ID`=44683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 파편 가까이 못 오게 해라!', `MaleText_loc4`='别让他们接近碎片！', `MaleText_loc5`='你不能讓他們靠近碎片!', `MaleText_loc7`='¡No dejar llegar al fragmento!' WHERE `ID`=44684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 죽여! 다 죽여!', `MaleText_loc4`='杀掉他们！把他们全都杀死！', `MaleText_loc5`='殺死他們!殺光光!', `MaleText_loc7`='¡Matar! ¡Matarlos a todos!' WHERE `ID`=44685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없애 버려라! 난 파편을 바위 어머니께 가져간다.', `MaleText_loc4`='碾碎他们！我去把碎片送到石母手里。', `MaleText_loc5`='摧毀他們!我把碎片帶給石母。', `MaleText_loc7`='¡Aplastadlos! Yo llevaré el fragmento a la Madre Pétrea.' WHERE `ID`=44686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 기둥은 우리의 것이다!', `MaleText_loc4`='我们控制世界之柱！', `MaleText_loc5`='我們控制著世界之柱!', `MaleText_loc7`='¡Controlamos el Pilar del Mundo!' WHERE `ID`=44687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단은 무시해라! 걔네는 멍청하다. 다른 녀석들을 처치해라, 당장!', `MaleText_loc4`='别去管暮光之锤渣滓！他们都是蠢货。去杀那边那个，赶快！', `MaleText_loc5`='不要管暮光之錘!他們笨笨的。殺死另一個，快點!', `MaleText_loc7`='¡Ignorar Martillo Crepuscular! Ser tontos. ¡Matar al otro, ahora!' WHERE `ID`=44688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들, 나한테 세계 기둥 파편 가져갈 생각 마라!', `MaleText_loc4`='你休想从我手里夺走世界之柱的碎片！', `MaleText_loc5`='你從我這裡拿不走世界之柱碎片!', `MaleText_loc7`='¡Tú no quitarme fragmento del Pilar del Mundo!' WHERE `ID`=44689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중간 파편을 테라제인 님께서 드리면 기뻐하실 거다.', `MaleText_loc4`='塞拉赞恩一定会很高兴取得中部碎片的。', `MaleText_loc5`='瑟拉贊恩會很高興拿到中間碎片。', `MaleText_loc7`='Therazane contenta de recuperar fragmento central.' WHERE `ID`=44690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모조리 없애라! 놈들을 없애고 대지의 사원 공격에 합류한다!', `MaleText_loc4`='干掉它们！我们得尽快加入大地神殿的战斗！', `MaleText_loc5`='打扁他們!然後我們一起去打大地神殿!', `MaleText_loc7`='¡Aplastarlos! ¡Y luego unirnos al ataque contra el Templo de la Tierra!' WHERE `ID`=44691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 오우거대가리 멍청이는 어디 있지?', `FemaleText_loc4`='那个长着食人魔脑袋的小丑来了吗？', `FemaleText_loc5`='那個巨魔頭的丑角在哪?', `FemaleText_loc7`='¿Dónde está el bufón con cara de ogro?' WHERE `ID`=44695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호랑이도 제 말 하면 온다더니...', `FemaleText_loc4`='啊，说到就到了……', `FemaleText_loc5`='啊，說鬼，鬼就到...', `FemaleText_loc7`='Ah, aquí está…' WHERE `ID`=44696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 일이 아니면 각오해야 할 거야, 실바나스. 내가 이 저주받은 땅의 썩은 악취를 얼마나 싫어하는지 알면서도 날 여기까지 부른 이유가 뭐지?', `MaleText_loc4`='事情最好足够重要，希尔瓦娜斯。你知道我有多讨厌这鬼地方和这里的恶臭。你找我来想要干什么？', `MaleText_loc5`='這件事最好很重要，希瓦娜斯。你知道我有多厭惡這個地方和它的臭味。你找我做什麼?', `MaleText_loc7`='Dime que es algo importante, Sylvanas. Sabes cómo odio este lugar y su peste inmunda. ¿Por qué me has llamado?' WHERE `ID`=44699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그보다는... 저 스컬지 괴물들이 여기서 뭘 하고 있는 건가?', `MaleText_loc4`='更重要的是，那些天灾恶魔在这儿干什么？', `MaleText_loc5`='更重要的是，那些天譴軍團的惡魔在這裡做什麼?', `MaleText_loc7`='Y lo que es más importante, ¿qué hace aquí la Plaga?' WHERE `ID`=44700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장, 와줘서 고맙소.', `FemaleText_loc4`='酋长，你终于来了。', `FemaleText_loc5`='大酋長，很高興你平安到來。', `FemaleText_loc7`='Jefe de Guerra, me alegra verlo.' WHERE `ID`=44701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕이 쓰러진 지금, 스컬지 중에서 나름 뛰어난 지성을 지닌 무리도... 실업자 신세라오. 대족장이 고상하게 ''괴물''이라고 말한 저들은 발키르라고 하는데, 이제는 나를 따르고 있지...', `FemaleText_loc4`='巫妖王倒下之后，许多更为难缠的天灾军团士兵都变成了……散兵游勇。这些“恶魔”——真是个雅致的称呼——叫做瓦格里。他们现在听从我的命令……', `FemaleText_loc5`='在巫妖王死了以後，許多比較具有智慧的天譴軍就...失業了。那些被你巧妙地稱之為惡魔的族類叫做華爾琪。他們現在聽命於我了...', `FemaleText_loc7`='Con la muerte del Rey Exánime, la parte más inteligente de la Plaga terminó... desempleada. La Plaga que ves son las val''kyr. Ahora están bajo mi control…' WHERE `ID`=44702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 그리고 저들 때문에 대족장을 보자고 했소.', `FemaleText_loc4`='……而她们就是我要求见你的部分理由。', `FemaleText_loc5`='...他們是我請求跟你見面的原因之一。', `FemaleText_loc7`='...y son en parte la razón por la que pedí verte.' WHERE `ID`=44703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요점만 말해라, 실바나스.', `MaleText_loc4`='有话快说，希尔瓦娜斯。', `MaleText_loc5`='繼續，希瓦娜斯。', `MaleText_loc7`='Ve al grano, Sylvanas.' WHERE `ID`=44704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠소, 대족장. 내가 포세이큰을 구원할 방법을 찾았소!', `FemaleText_loc4`='遵命，酋长。我解决了被遗忘者一直以来的困境！', `FemaleText_loc5`='好吧，大酋長。我已經解決被遺忘者的困境了!', `FemaleText_loc7`='Muy bien, Jefe de Guerra. ¡He resuelto el apuro de los Renegados!' WHERE `ID`=44705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 포세이큰은 자식을 낳을 수가 없지.', `FemaleText_loc4`='作为一个种族，我们被遗忘者没有繁衍后代的能力。', `FemaleText_loc5`='身為一個種族，我們被遺忘者無法進行繁衍。', `FemaleText_loc7`='Los Renegados no podemos procrearnos.' WHERE `ID`=44706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 발키르의 도움이 있다면, 우리도 죽은 자들의 시체를 되살려, 새로운 포세이큰을 만들 수 있소.', `FemaleText_loc4`='但是，现在有了瓦格里的帮助，我们能够将新的生命赋予那些倒下的人类。', `FemaleText_loc5`='在華爾琪的幫助下，我們現在可以取得死者的屍體並創造新的被遺忘者。', `FemaleText_loc7`='Con la ayuda de las val''kyr, ahora podemos tomar los cadáveres de los caídos y crear nuevos Renegados.' WHERE `ID`=44707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아가타, 직접 보여 드려라!', `FemaleText_loc4`='阿加莎，让酋长看看！', `FemaleText_loc5`='亞加薩，讓大酋長看看!', `FemaleText_loc7`='¡Agatha, muéstrale al Jefe!' WHERE `ID`=44709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맙소사!', `MaleText_loc4`='这太扭曲了！', `MaleText_loc5`='怪物!', `MaleText_loc7`='¡QUÉ ABERRACIÓN!' WHERE `ID`=44713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스... 지금 네가 한 짓은 자연의 법칙에 위배되는 일이다. 역겹구나. 이 말 밖에 나는 달리 할 말이 없다.', `MaleText_loc4`='你在此所做的一切，希尔瓦娜斯……违背了自然的规律。恶心是我唯一能用来形容它的词。', `MaleText_loc5`='你在這裡做了什麼，希瓦娜斯...這違反了自然法則。我唯一能用來形容它的字眼就是噁心。', `MaleText_loc7`='Lo que has hecho, Sylvanas... va en contra de las leyes de la naturaleza. Sólo tengo una palabra para ello: repugnante.' WHERE `ID`=44714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장, 새로운 포세이큰이 태어나지 않으면 우린 멸망할 것이오... 그땐 길니아스와 로데론 북부도 적의 것이 될 테고.', `FemaleText_loc4`='酋长，没有新的被遗忘者，我的子民将会灭绝……我们对吉尔尼斯和北洛丹伦的统治也将瓦解。', `FemaleText_loc5`='大酋長，沒有這些新的被遺忘者加入，我的人民會滅絕。我們對吉爾尼斯和北羅德隆的掌握會崩潰。', `FemaleText_loc7`='Jefe, sin estos Renegados nuevos, mi gente se extinguiría... Perderíamos el control de Gilneas y el norte de Lordaeron.' WHERE `ID`=44715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실바나스, 이 짓의 의미를 한 번이라도 생각한 적이 있느냐?', `MaleText_loc4`='你考虑过这意味着什么吗，希尔瓦娜斯？', `MaleText_loc5`='你有想過這樣做代表什麼嗎，希瓦娜斯。', `MaleText_loc7`='¿Acaso has pensado en lo que significa, Sylvanas? ' WHERE `ID`=44716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 이런 네가 리치 왕과 다른 점은 뭔가?', `MaleText_loc4`='现在的你，和巫妖王又有什么分别？', `MaleText_loc5`='現在，你和巫妖王之間有什麼區別?', `MaleText_loc7`='¿Qué diferencia hay entre tú y el Rey Exánime ahora?' WHERE `ID`=44717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연한 걸 묻는군, 대족장. 난 호드를 섬기지.', `FemaleText_loc4`='答案还不明显吗，酋长？我为部落效忠。', `FemaleText_loc5`='這還不明顯嗎，大酋長?我為部落而戰。', `FemaleText_loc7`='¿No es obvio, Jefe de Guerra? Yo sirvo a la Horda.' WHERE `ID`=44718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 잘난 입을 함부로 놀리지 마라!', `MaleText_loc4`='小心你的伶牙俐齿，贱人。', `MaleText_loc5`='別耍嘴皮，臭女人。', `MaleText_loc7`='Cuidado con lo que dices, perra.' WHERE `ID`=44719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로무쉬, 여기 남아서 우리 밴시 여왕님을 잘 보살펴 드리도록 해라. 이번 일의 결과는 다음에 내게 직접 상세히 보고해야 한다.', `MaleText_loc4`='克鲁姆什，你留下来“守卫”女妖之王，确保她受到“彻底”的保护。下次见面时我希望看到一份完整的报告。', `MaleText_loc5`='克洛姆什，你留下來確保女妖之王受到完善的「保護」。下次碰面我要聽取完整的報告。', `MaleText_loc7`='Cromush, quédate y asegúrate de que la Reina Alma en Pena esté bien "protegida". Preparen un informe completo para la próxima reunión.' WHERE `ID`=44720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억해라, 실바나스. 언젠가는 우리 모두 창조주의 발아래 엎드려 심판을 받아야 하지. 자네는 남들보다 먼저 그분을 찾아뵐지도 모르겠군...', `MaleText_loc4`='记住，希尔瓦娜斯，终有一天，我们都将站在造物主面前接受审判。你的审判日也许比别人来得更早……', `MaleText_loc5`='記住，希瓦娜斯，我們最終都會站在造物者面前並面對審判。你的那天可能會比其他人更早來臨...', `MaleText_loc7`='Recuerda, Sylvanas, a todos nos llega la hora de ser juzgados por nuestro creador. Tu turno podría llegar antes de lo esperado…' WHERE `ID`=44721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 움직이세요, $n. 당신이 일을 마치기 전에 모그레인이 우릴 발견하면, 모든 게 헛수고가 될 거예요.', `FemaleText_loc4`='动作快，$n。要是莫格莱尼在你完成前注意到我们，一切努力就白费了。', `FemaleText_loc5`='動作快，$n。要是工作還沒做好就被莫格萊尼發現，你的努力會全部白費。', `FemaleText_loc7`='Date prisa, $n. Tu trabajo no habrá servido para nada si Mograine nos descubre antes de que hayas terminado.' WHERE `ID`=44728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 내 도시에 침투했다. 놈들은 멋대로 세력을 뻗쳐 어느새 핵심 인사들까지 타락시켰지. 황혼의 고원에 있는 놈들의 요새를 공격하기 전에, 난 먼저 스톰윈드를 놈들의 책략에서 안전한 곳으로 만들어야 한다.$B$B내겐 도시를 돌아다니며 도시 안팎에서 벌어지는 일들을 잘 보고 들을 사람이 더 많이 필요하다. 그대처럼 경험 많은 $c|1은;는; 참으로 귀중한 인재이지.$B$B스톰윈드를 도울 준비가 되었는가?', `MaleText_loc4`='暮光之锤已经渗入了我的城市。如果没人去制止他们，城市就将彻底覆灭。在围剿他们位于高地的据点前，我必须确认暴风城不会成为他们阴谋的牺牲品。$B$B我需要在城里安插更多脚踏实地、忠心不二的耳目。像你这样经验丰富的$c，作用是无可估量的。你准备好帮助暴风城了吗？', `MaleText_loc5`='暮光之錘已滲透進我的王都。要是坐視不理的話，他們必然會造成整座城的沈淪墮落。在我們出兵攻打暮光高地之前，我必須先確保暴風城已經安全，不再受到他們陰謀毒計的破壞。$B$B我需要更紮實的情報，需要在城裡部署更可信的眼線。而像你這樣經驗豐富的$c正是最可貴的人才。$B$B你已經準備好要為暴風城效命了嗎?', `MaleText_loc7`='El Martillo Crepuscular se ha infiltrado en mi ciudad. Si no hacemos algo, la corromperán desde dentro. Antes de asaltar su base en las Tierras Altas, debo asegurarme de que Ventormenta está a salvo de sus maquinaciones.$b$bNecesito más pies en el suelo, ojos y oídos de confianza en la ciudad. $gUn:Una; $c $gexperimentado:experimentada; como tú sería una aportación incalculable.$b$b¿Estás $gpreparado:preparada; para contribuir a la causa de Ventormenta?' WHERE `ID`=44729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지와 세계 기둥에 대해 좀 더 말씀해 주십시오.', `MaleText_loc4`='告诉我更多关于深石荒野和世界之柱的事。', `MaleText_loc5`='告訴我更多關於地深之源和世界之柱的事情。', `MaleText_loc7`='Háblame de Infralar y del Pilar del Mundo.', `FemaleText_loc1`='심원의 영지와 세계 기둥에 대해 좀 더 말씀해 주십시오.', `FemaleText_loc4`='告诉我更多关于深岩之洲和世界之柱的事。', `FemaleText_loc5`='告訴我更多關於地深之源和世界之柱的事情。', `FemaleText_loc7`='Háblame de Infralar y del Pilar del Mundo.' WHERE `ID`=44730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이름은 프론클이 아니라고!', `MaleText_loc4`='我的名字不叫弗朗科！', `MaleText_loc5`='我的名字不叫佛隆寇!', `MaleText_loc7`='¡No me llamo Fronkle!' WHERE `ID`=44731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽으로 전환!', `MaleText_loc4`='左转！', `MaleText_loc5`='左轉!', `MaleText_loc7`='¡Gira a la izquierda!' WHERE `ID`=44732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 거북이 조심해!', `MaleText_loc4`='小心那只龟！', `MaleText_loc5`='當心那隻海龜!', `MaleText_loc7`='¡Cuidado con esa tortuga!' WHERE `ID`=44733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔딱팔딱 거리는 키메로크 찹스테이크를 먹을 거야! 아주 싱싱한 걸로!', `MaleText_loc4`='我要来一份铁板奇美拉肉排，双倍调料！', `MaleText_loc5`='我要吃超美味奇美拉肉片，要雙份!', `MaleText_loc7`='¡Tomaré las costillas de quimera picantes, extra picantes!' WHERE `ID`=44734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프롱클이라고 부르지 마!', `MaleText_loc4`='别再叫我弗朗科了！', `MaleText_loc5`='別再叫我佛隆寇!', `MaleText_loc7`='¡Deja de llamarme Fronkle!' WHERE `ID`=44735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다이빙! 다이빙! 다이빙!', `MaleText_loc4`='俯冲！俯冲！俯冲！', `MaleText_loc5`='潛水!潛水!潛水!', `MaleText_loc7`='¡Sumérgete! ¡Sumérgete! ¡Sumérgete!' WHERE `ID`=44736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='십자군이여, 포세이큰의 힘 앞에 무릎을 꿇어라!', `FemaleText_loc4`='战栗吧，十字军，在被遗忘者的力量面前战栗吧！', `FemaleText_loc5`='戰慄吧，十字軍，見識我們被遺忘者的力量!', `FemaleText_loc7`='¡Temblad, cruzados, ante el poder de los Renegados!' WHERE `ID`=44737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 따르겠습니다, 대족장님!', `MaleText_loc4`='遵命，酋长！', `MaleText_loc5`='遵命，大酋長!', `MaleText_loc7`='¡Como ordenes, Jefe de Guerra!' WHERE `ID`=44738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='식인 칼날촉수들이여, 우리 용사들을 위해 앞뜰을 사수하라!', `FemaleText_loc4`='血肉撕裂者们，为我们的勇士们守好前庭！', `FemaleText_loc5`='血肉撕裂者，為我們的勇士守住前庭!', `FemaleText_loc7`='¡Desgarradores de carne, aguantad el patio frontal para nuestros campeones!' WHERE `ID`=44739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붉은십자군 수도원은 이제 포세이큰의 것이다!', `FemaleText_loc4`='血色修道院现在的主人是被遗忘者！', `FemaleText_loc5`='血色修道院是被遺忘者的了!', `FemaleText_loc7`='¡Ahora el Monasterio Escarlata pertenece a los Renegados!' WHERE `ID`=44740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸자인 적이 당신의 병사들을 학살하는 모습을 보니 기분이 어떻소, 심문관?', `FemaleText_loc4`='看着自己的人死在夙敌手上，这感觉怎么样啊，检察官？', `FemaleText_loc5`='看著自己的手下被你們的死敵屠殺的感覺如何啊，審判官?', `FemaleText_loc7`='¿Qué se siente al ver a tus hombres masacrados por tus peores enemigos, inquisidor?' WHERE `ID`=44741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 스톰윈드에 오신 걸 환영합니다.', `MaleText_loc4`='欢迎来到暴风城，$c。', `MaleText_loc5`='歡迎來到暴風城，$c。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Ventormenta, $c.' WHERE `ID`=44742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 평가해 보는 안두인>$B$B$n 인가요? 당신이 이룬 업적의 일부 내용을 왕실에서 얘기한 적이 있지요.$B$B노스렌드에서 임무는 어땠나요? 세계수를 봤나요? 바쉬르 얘기가 진짜던가요? 물어보고 싶은 게 많아요!', `MaleText_loc4`='<安度因上下打量了你>$B$B$n，对吧？你的一些英勇事迹已经被广为传诵。$B$B在诺森德奋战的感觉还好吗？你见到世界之树了吗？那些关于瓦丝琪尔的传闻是真的吗？我有太多问题要问了！', `MaleText_loc5`='<安杜因上下打量著你。>$B$B你就是$n?大家在宮廷裡經常會聊到你的英勇事蹟。$B$B在北裂境服役的感覺如何?你有看到世界之樹嗎?瓦許伊爾的故事是真的嗎?我有好多的問題!', `MaleText_loc7`='<Anduin te analiza.>$b$b¿$n, verdad? Algunos de tus triunfos han sido la comidilla de la corte.$b$b¿Cómo fue servir en Rasganorte? ¿Has visto el Árbol del Mundo? ¿Son ciertas las historias sobre Vashj''ir? ¡Tengo tantas preguntas...!' WHERE `ID`=44743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 함께 가시죠, 왕자님.', `MaleText_loc4`='请跟我来，殿下。', `MaleText_loc5`='請跟我來，殿下。', `MaleText_loc7`='Ven conmigo, alteza.', `FemaleText_loc1`='저와 함께 가시죠, 왕자님.', `FemaleText_loc4`='请跟我来，殿下。', `FemaleText_loc5`='請跟我來，殿下。', `FemaleText_loc7`='Ven conmigo, alteza.' WHERE `ID`=44744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 예견이나 했겠나, 애송이?', `MaleText_loc4`='你能预料到吗，傻瓜？', `MaleText_loc5`='笨蛋，那你有預見到這個嗎?', `MaleText_loc7`='¿Has previsto esto, idiota?' WHERE `ID`=44745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드가 된다는 게 어떤 기분일까 늘 궁금했어요. 곰으로 변신하면 당신이 입고 있는 옷은 어떻게 되는 건가요?', `MaleText_loc4`='我一直想知道当个德鲁伊是什么感觉。当你变熊时你的衣服去哪儿了呢？', `MaleText_loc5`='我一直很好奇當德魯伊是什麼感覺。你變熊的時候衣服都到哪裡去了?', `MaleText_loc7`='Siempre me he preguntado cómo sería ser un druida. ¿Qué pasa con tu ropa cuando te conviertes en oso?' WHERE `ID`=44746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사냥꾼이시군요? 아버지께서 가르쳐주신 덕분에 저도 활은 꽤 잘 다룬답니다.', `MaleText_loc4`='这么说你是个猎人？我父亲教会了我怎样和弓打交道。', `MaleText_loc5`='原來你是獵人?我的射箭技術也被我父親訓練得不錯。', `MaleText_loc7`='¿Así que eres $gun cazador:una cazadora;? Mi padre me ha instruido bastante bien en el tiro con arco.' WHERE `ID`=44747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 마법사로군요. 제이나 프라우드무어처럼요. 마법을 공부한 지는 얼마나 되셨나요? 무척 어려운 학문 같던데요.', `MaleText_loc4`='你和吉安娜·普罗德摩尔一样，是个法师？你研习奥术有多久了？那玩意儿看起来可挺难学的。', `MaleText_loc5`='你是法師，跟珍娜·普勞德摩爾一樣?你已經學習多久了?要懂魔法好像很難的樣子。', `MaleText_loc7`='¿Eres $gun mago:una maga;, como Jaina Valiente? ¿Cuánto hace que estudias las artes arcanas? Parecen tan difíciles...' WHERE `ID`=44748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 성기사인가요? 폴드라곤 대영주도 성기사였지요. 그는 제게 상당히 많은 걸 가르쳐 주었습니다. 전... 아직도 그가 그리워요.', `MaleText_loc4`='你是个圣骑士？大领主弗塔根曾经也是。他教过我不少东西。我……我还是很想念他。', `MaleText_loc5`='你是聖騎士?大領主弗塔根也是。他教了我好多事情。我...我還是好想他。', `MaleText_loc7`='¿Eres $gun:una; paladín? El alto señor Fordragón también lo era. Me enseñó muchísimas cosas. Yo... todavía lo echo de menos.' WHERE `ID`=44749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 사제가 되려고 공부하고 있답니다. 언젠가 당신처럼 강력한 사제가 되었으면 좋겠어요.', `MaleText_loc4`='我本人正在被受训成为一名牧师。希望有一天我也能变得和你一样强大。', `MaleText_loc5`='我也正在接受牧師的訓練。希望有一天我能變得跟你一樣厲害。', `MaleText_loc7`='Estoy estudiando para ser sacerdote. Espero que algún día pueda ser tan poderoso como tú.' WHERE `ID`=44750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 정말 기쁘군요. 스톰윈드의 도적과 이야기해 보는 건 처음이거든요. 도적은 늘 조용하고 비밀스러워서 말이죠...', `MaleText_loc4`='这可太棒了，我还从没和暴风城里的潜行者交谈过。他们总是那么的安静和神秘……', `MaleText_loc5`='太棒了。我從來沒有跟暴風城的盜賊講過話。他們都好安靜，而且神秘兮兮的樣子...', `MaleText_loc7`='Qué bien, nunca tengo ocasión de hablar con los pícaros de Ventormenta. Siempre son tan silenciosos y reservados...' WHERE `ID`=44751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사가 되면 어떤가요? 전에 스랄 님을 만나본 적이 있어요. 제 아버님께서는 그분을 믿지 않으시지만, 매우 현명한 분 같아 보였어요.', `MaleText_loc4`='当萨满祭司是什么感觉？我和萨尔有过一面之缘。我父亲不太信任他，但他看起来还是相当睿智的。', `MaleText_loc5`='當薩滿的感覺如何呢?我有見過索爾一次。雖然我父王並不信任他，但他似乎相當明智。', `MaleText_loc7`='¿Cómo es ser chamán? Una vez conocí a Thrall. Mi padre no confía en él, pero parecía muy sabio.' WHERE `ID`=44752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 흑마법사가 되기란 어려운 일이겠지요. 혹시 부리던 악마를 제어하지 못하게 될까 봐 걱정했던 적은 없으세요?', `MaleText_loc4`='成为一名出色的术士想必很难。你有没有担心过，要是你的恶魔失控了怎么办？', `MaleText_loc5`='要成為一位強大的術士必定很不容易。難道你都不會擔心你的惡魔會失去控制嗎?', `MaleText_loc7`='Ser un brujo poderoso tiene que ser difícil. ¿No te da miedo perder el control de uno de tus demonios?' WHERE `ID`=44753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 제가 봤던 전사들 중에서도 가장 인상이 사나우세요, $n 님!', `MaleText_loc4`='你是我所见过的长相最凶狠的战士之一，$n！', `MaleText_loc5`='你是我見過樣子最兇狠的戰士，$n!', `MaleText_loc7`='¡Eres $guno de los guerreros:una de las guerreras; más feroces que he visto jamás, $n!' WHERE `ID`=44754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 당신이 칠흑의 요새 전투를 마치고 처음 아버지를 뵈러 오셨을 때를 기억합니다. 아직 저희와 함께해 주셔서 기쁘군요.', `MaleText_loc4`='$n，我记得你第一次来见我父亲，是在黑锋要塞战役结束之后。真高兴你仍与我们同在。', `MaleText_loc5`='$n，我還記得你在黯黑堡之戰結束後第一次來晉見我父親的時候。很高興你依然與我們站在同一陣線。', `MaleText_loc7`='$n, recuerdo cuando viniste a ver a mi padre por primera vez tras la batalla por el Bastión de Ébano. Me alegro de que sigas con nosotros.' WHERE `ID`=44755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 귀여우신 분! 제 등에 로션 좀 발라주실래요?', `FemaleText_loc4`='嗨，小可爱！介意帮我涂点儿防护霜吗？', `FemaleText_loc5`='嗨，小可愛!要不要來幫我衣服沒蓋到的地方擦點乳液啊?', `FemaleText_loc7`='¡Hola, bombón! ¿Quieres ponerme loción en las zonas expuestas?' WHERE `ID`=44756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몹쓸 놈들! 더러운 놈들! 마귀 같으니! 여기에서 당장 꺼져라!', `MaleText_loc4`='亵渎者！恶棍！魔鬼！离开这座神殿！', `MaleText_loc5`='骯髒、污染、邪惡的靈魂! 快滾出去!', `MaleText_loc7`='¡Desecradores! ¡Miserables! ¡Fuera de aquí!' WHERE `ID`=44757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 신에게 보내주마.', `MaleText_loc4`='我送你去见你的神明。', `MaleText_loc5`='與你的偽神相聚吧。', `MaleText_loc7`='Los envío a su deidad.' WHERE `ID`=44758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 목숨은 제물로 받겠다!', `MaleText_loc4`='你的生命将成为我的祭品。', `MaleText_loc5`='我把這當成獻祭的生命收下了!', `MaleText_loc7`='¡Tomo esta vida como una ofrenda!' WHERE `ID`=44759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 불타는 빛이여... 날 데려가 주오.', `MaleText_loc4`='炽热之光……请接纳我。', `MaleText_loc5`='炙熱的陽光...帶我走吧。', `MaleText_loc7`='Rayos de luz... tómenme.' WHERE `ID`=44760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴지느냐? 축복받은 태양의 온기가...', `MaleText_loc4`='你能感受到太阳温暖的祝福吗……？', `MaleText_loc5`='感覺到了嗎?陽光所帶來的溫暖祝福...?', `MaleText_loc7`='¿Lo sienten? ¿La tibieza bendita del sol...?' WHERE `ID`=44761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 제어할 수 없는 것을 두려워하지. 하지만, 두려움은 제어할 수 있는가?', `MaleText_loc4`='无法控制的事物令你恐惧，但你能控制你的恐惧吗？', `MaleText_loc5`='你們害怕自己無法控制的東西。但你們可以控制恐懼嗎?', `MaleText_loc7`='Le temen a lo que no pueden controlar. Pero ¿pueden controlar su miedo?' WHERE `ID`=44762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 맞이해라!', `MaleText_loc4`='拥抱末日吧！', `MaleText_loc5`='擁抱死亡!', `MaleText_loc7`='¡Acepten el fin!' WHERE `ID`=44763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이해하겠느냐?', `MaleText_loc4`='你现在醒悟了吗？', `MaleText_loc5`='現在懂了沒啊?', `MaleText_loc7`='¿Ahora lo entienden?' WHERE `ID`=44764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 증오에... 몸을 맡겨라...', `MaleText_loc4`='是的！驾驭……你的……仇恨。', `MaleText_loc5`='就是這樣! 駕馭...你的...憎恨...', `MaleText_loc7`='¡Sí! Exploten... su... odio.' WHERE `ID`=44765;
