UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 삶의 희미한 빛은, 꺼졌다.', `FemaleText_loc4`='你的生命光辉，就快熄灭了。', `FemaleText_loc5`='你的生命之火，已熄滅。', `FemaleText_loc7`='El brillo tenue de su vida, extinto.' WHERE `ID`=44773;
