UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 광채가... 사그라진다.', `FemaleText_loc4`='我的光辉……黯淡了。', `FemaleText_loc5`='我的光芒...正在消退。', `FemaleText_loc7`='Mi lustre... palidece.' WHERE `ID`=44776;
