UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 벌레들이 배를 채우겠군...', `MaleText_loc4`='虫群又有腐肉吃了……', `MaleText_loc5`='腐屍群的數量...又將增加了...', `MaleText_loc7`='Más carroña para el enjambre...' WHERE `ID`=44778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지로 돌아가라.', `MaleText_loc4`='尘归尘，土归土。', `MaleText_loc5`='塵歸塵。', `MaleText_loc7`='Polvo al polvo.' WHERE `ID`=44779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프타는... 이젠...', `MaleText_loc4`='塔赫……不复存在了……', `MaleText_loc5`='普塔...不再...存在...', `MaleText_loc7`='Ptah... ya... no existe…' WHERE `ID`=44780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 진동한다!', `MaleText_loc4`='大地，颤抖吧！', `MaleText_loc5`='顫抖吧!大地!', `MaleText_loc7`='¡La tierra TIEMBLA!' WHERE `ID`=44781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들아, 돌아가라! 전당을 어지럽히지 마라!', `MaleText_loc4`='退回去，入侵者！这里的殿堂绝不允许亵渎！', `MaleText_loc5`='打道回府吧，侵略者!這個大廳不該被打擾!', `MaleText_loc7`='¡Márchense, intrusos! ¡No perturben estas salas!' WHERE `ID`=44782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오만불손하게 군 벌이다.', `MaleText_loc4`='这一切都是因为你的傲慢。', `MaleText_loc5`='這是你自做自受。', `MaleText_loc7`='Un producto de su propia insolencia.' WHERE `ID`=44783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을 한 거냐...', `MaleText_loc4`='你都……干了些……什么？', `MaleText_loc5`='你們...會...後悔的...', `MaleText_loc7`='¿Qué... han... hecho?' WHERE `ID`=44784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이시여, 신성한 방패를 내려 주소서!', `MaleText_loc4`='光之信标啊，将你的庇护赐予我！', `MaleText_loc5`='光明之塔，賜予我你的庇護吧!', `MaleText_loc7`='¡Faros de luz, bríndenme su égida!' WHERE `ID`=44785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후회는 없다.', `MaleText_loc4`='我不会为此后悔。', `MaleText_loc5`='我一點也不同情你。', `MaleText_loc7`='Sin arrepentimientos.' WHERE `ID`=44786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들과는 잘 지내고 있겠지? 안두인은 그저 수줍음이 많을 뿐이다.', `MaleText_loc4`='我相信你和我儿子相处得不错？安度因唯一不具备的特质就是内向。', `MaleText_loc5`='相信你跟我兒子處得應該還不錯吧?安杜因可不是會怕生的那種人。', `MaleText_loc7`='¿Supongo que mi hijo y tú os lleváis bien? Anduin es cualquier cosa menos tímido.' WHERE `ID`=44787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 정거장은 포세이큰 전초지입니다! 모두 내리십시오!', `MaleText_loc4`='终点站——被遗忘者先锋军到了！所有人都下去！', `MaleText_loc5`='最後一站，被遺忘者戰事前線!所有人下船!', `MaleText_loc7`='¡Última parada, el Frente Renegado! ¡TODO EL MUNDO FUERA!', `FemaleText_loc1`='마지막 정거장은 포세이큰 전초지입니다! 모두 내리세요!', `FemaleText_loc4`='终点站——被遗忘者先锋军到了！所有人都下去！', `FemaleText_loc5`='最後一站，被遺忘者戰事前線!所有人下船!', `FemaleText_loc7`='¡Última parada, el Frente Renegado! ¡TODO EL MUNDO FUERA!' WHERE `ID`=44788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드가 안전해지면, 우리는 이 싸움을 황혼의 고원에서 계속해 나갈 것이다.', `MaleText_loc4`='等守住了暴风城，就该轮到我们把战火烧到暮光高地了！', `MaleText_loc5`='等暴風城安全了，我們就會出兵攻打暮光高地。', `MaleText_loc7`='Cuando Ventormenta esté a salvo, trasladaremos esta batalla a las Tierras Altas.' WHERE `ID`=44789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 여행은 편도 여행이라네. 아마 돌아오는 수레에는 타고 싶다는 생각이 안 들거야.', `MaleText_loc4`='这是单程旅行，孩子，而且你一定不会想要乘坐另一辆车回来。', `MaleText_loc5`='孩子，這是一趟單程之旅。而且，你絕對不會想搭另一輛車回來的。', `MaleText_loc7`='Este es un viaje solo de ida, $gchico:chica;, y te aseguro que no quieres volver en el otro carro.', `FemaleText_loc1`='이번 여행은 편도 여행이죠. 아마 돌아오는 수레에는 타고 싶다는 생각이 안 드실 거예요.', `FemaleText_loc4`='这是单程旅行，孩子，而且你一定不会想要乘坐另一辆车回来。', `FemaleText_loc5`='孩子，這是一趟單程之旅。而且，你絕對不會想搭另一輛車回來的。', `FemaleText_loc7`='Este es un viaje solo de ida, $gchico:chica;, y te aseguro que no quieres volver en el otro carro.' WHERE `ID`=44790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이단자여, 썩 꺼져라! 여긴 너희가 올 곳이 아니다!', `MaleText_loc4`='离开这里，异教徒！这里不欢迎你们！', `MaleText_loc5`='滾開，異教徒!你們在此不受歡迎!', `MaleText_loc7`='¡Váyanse, infieles, no son bienvenidos!' WHERE `ID`=44791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음은... 그저 시작에 불과해!', `MaleText_loc4`='死亡仅仅只是开始！', `MaleText_loc5`='死亡只是個開始!', `MaleText_loc7`='¡La muerte es sólo el comienzo!' WHERE `ID`=44792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안식이 함께하기를.', `MaleText_loc4`='愿你终获安宁。', `MaleText_loc5`='願你安息吧。', `MaleText_loc7`='Que encuentren la paz.' WHERE `ID`=44793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 널 데려가리라!', `MaleText_loc4`='天堂才是你的归宿！', `MaleText_loc5`='上天堂去吧!', `MaleText_loc7`='¡Que los cielos los lleven!' WHERE `ID`=44794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에 무릎 꿇고 참회해라!', `MaleText_loc4`='在我面前下跪忏悔吧！', `MaleText_loc5`='跪在我面前懺悔吧!', `MaleText_loc7`='¡Arrodíllense y arrepiéntanse!' WHERE `ID`=44795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 탑승하십시오! 다음 정거장은 공동묘지입니다.', `MaleText_loc4`='都上来！下一站——瑟伯切尔。', `MaleText_loc5`='全體上船!下一站:瑟伯切爾。', `MaleText_loc7`='¡TODOS A BORDO! Próxima parada: El Sepulcro.', `FemaleText_loc1`='모두 탑승하세요! 다음 정거장은 공동묘지입니다.', `FemaleText_loc4`='都上来！下一站——瑟伯切尔。', `FemaleText_loc5`='全體上船!下一站:瑟伯切爾。', `FemaleText_loc7`='¡TODOS A BORDO! Próxima parada: El Sepulcro.' WHERE `ID`=44796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 탑승하십시오! 마지막 정거장은 포세이큰 전초지입니다.', `MaleText_loc4`='全体登车！最后一站——被遗忘者先锋军！', `MaleText_loc5`='全體上船!最後一站:被遺忘者戰事前線!', `MaleText_loc7`='¡TODOS A BORDO! Próxima parada: El Frente Renegado.', `FemaleText_loc1`='모두 탑승하세요! 마지막 정거장은 포세이큰 전초지입니다.', `FemaleText_loc4`='全体登车！最后一站——被遗忘者先锋军！', `FemaleText_loc5`='全體上船!最後一站:被遺忘者戰事前線!', `FemaleText_loc7`='¡TODOS A BORDO! Próxima parada: El Frente Renegado.' WHERE `ID`=44797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 해라, 필멸의 존재여. 네놈은 결코 오쿨루스를 이길 수 없다!', `MaleText_loc4`='把握机会吧，凡人。奥库鲁斯永远都不会被打败！', `MaleText_loc5`='你們時日無多了，凡人。你們絕對無法擊敗奧庫魯斯!', `MaleText_loc7`='Tomen su tiempo, mortales. ¡Nunca derrotarán al Occulus!' WHERE `ID`=44798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 오만하고... 건방질 수가...', `MaleText_loc4`='如此傲慢……如此无礼……', `MaleText_loc5`='如此傲慢....如此妄為...', `MaleText_loc7`='Qué insolencia... Qué arrogancia...' WHERE `ID`=44799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 시간의 흐름을 지배한다! 무한의 용군단은 패할 수가 없단 말이다!', `MaleText_loc4`='我们掌控时间的进退流返！永恒之龙是不可战胜的！', `MaleText_loc5`='我們掌控了時間的起落與流動!恆龍軍團是不會被擊敗的!', `MaleText_loc7`='¡Controlamos el ir y venir del tiempo! ¡Es imposible derrotar al Vuelo Infinito!' WHERE `ID`=44800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 형제여, 그대의 시간이 얼마 남지 않았다! 영원의 모래로 상실되기 전에 나와 함께하자!', `MaleText_loc4`='我曾经的弟兄们，你们没有时间了！加入我们吧，趁还没有迷失在永恒之沙里！', `MaleText_loc5`='我舊日的弟兄啊，你們的來日所剩無多!在被永恆的時光之沙掩埋之前，加入我們吧!', `MaleText_loc7`='¡Mis antiguos hermanos, su hora se acerca! ¡Unanse a nosotros antes de que se pierdan en las arenas de la eternidad!' WHERE `ID`=44801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 모래가 네놈이 파멸할 때를 세고 있다!', `MaleText_loc4`='时间之沙能算出你离死亡还有多远！', `MaleText_loc5`='時間之沙即將數盡你們的滅亡之日!', `MaleText_loc7`='¡Las arenas del tiempo cuentan los días que quedan para su aniquilación!' WHERE `ID`=44802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노즈도르무의 아이들아, 내 말에 귀 기울여라! 시간의 단편은 헤아릴 수 없고, 우리 또한 헤아릴 수 없이 많다! 너는 우리 모두를 절대 이길 수 없다!', `MaleText_loc4`='诺兹多姆的子嗣们，听我说！时间的层面无穷无尽，我们的兵力无法计数！你无法、也不可能击败我们所有人！', `MaleText_loc5`='諾茲多姆的子嗣啊，聽我一勸!時光摺曲無窮無盡，我等為數多不可計!你們永遠不會、永遠不可能，將我們全數擊敗!', `MaleText_loc7`='¡Hijos de Nozdormu, escuchadme! ¡Las ondas del tiempo son innumerables y nosotros somos muchos! ¡No nos venceréis! ¡No podéis vencernos!' WHERE `ID`=44803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이교도가 우릴 공격하고 있어요! 유예의 방으로 가 아군을 도와야 해요!', `FemaleText_loc4`='邪教徒来了！安息之厅需要帮手！', `FemaleText_loc5`='教徒攻過來了!我們在緩刑室需要協助!', `FemaleText_loc7`='¡La secta se nos echa encima! ¡Necesitamos ayuda en la Cámara del Descanso!' WHERE `ID`=44804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 덕분에 아킬다라의 우상을 되찾을 수 있었네, $n! 이리 가까이 오게. 아칼다라의 축복받은 바람으로 자네를 진타알로 깊숙한 곳까지 보내줄 테니!', `MaleText_loc4`='多亏你的帮忙，$n，阿基尔达拉神像又回到了我们手中！快过来，让我带你承着她的祝福，前往辛萨罗深处！', `MaleText_loc5`='謝謝你，$n，我們已經奪回了阿奇達拉塑像!過來這裡，乘著她的祝福之風，我送你深入辛薩羅!', `MaleText_loc7`='¡Gracias a ti, $n hemos recupera''o el ídolo de Akil''darah! ¡Ven aquí y te llevaré a lo más profundo de Jintha''Alor sobre la'' alas de su bendición!' WHERE `ID`=44805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 내륙지에 있는 독수리의 혼이 우리 편이 되었네, $n.$B$B썩은가지 부족으로부터 아킬다라의 우상을 되찾은 이상, 이제 자네를 진타알로의 상층으로 순식간에 이동시킬 수 있어! 놈들의 심장부에 비수를 꽂게!', `MaleText_loc4`='辛特兰的鹰之魂已与我们同在，$n。$B$B有了从邪枝那里取回的神像，我就能直接把你传送到辛萨罗的上层。直击他们的要害！', `MaleText_loc5`='辛特蘭的鷹之魂已與我們同在，$n。$B$B在她的塑像從邪枝食人妖的手中解脫之後，我可以直接將你傳送到辛薩羅上層的那裡。直導虎穴!', `MaleText_loc7`='El eh''píritu del águila de las Tierras Altas ahora eh''tá de nueh''tro la''o, $n.$B$BAhora que su ídolo ya no eh''tá en manos de los Vilrama, puedo tranh''portah''te hah''ta él en la pah''te alta de Jintha''Alor. ¡Un golpe directo al corazón!' WHERE `ID`=44806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 제 상점에 오신 걸 환영해요.$B$B어유, 참 멋지시네요! 하지만 모습을 좀 바꿔보실 생각이라면, 아무 의자에나 그냥 앉으시면 된답니다.', `FemaleText_loc4`='嗨。欢迎光临我的美发沙龙。$B$B你看起来容光焕发！但如果你想换个造型的话，就随便找把椅子坐下来好了。', `FemaleText_loc5`='嗨，歡迎光臨我的沙龍。$B$B你看起來棒透了!但如果你有想要換換外觀的心情的話，請直接找張椅子坐下吧。', `FemaleText_loc7`='Hola. $gBienvenido:Bienvenida; a mi salón.$b$b¡Tienes un aspecto estupendo! Pero si te apetece un cambio, siéntate directamente en una de las sillas.' WHERE `ID`=44807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뾰족부리는 맹금의 봉우리에서도 최고로 치는 그리핀입니다. 이 녀석이 당신을 진타알로의 꼭대기로 보내줄 겁니다. 그러면 순식간에 정원 상층을 공격할 수 있겠죠.', `MaleText_loc4`='沙普比克是鹰巢山最出色的狮鹫。它会把你直接送到辛萨罗顶部，我们就能以迅雷不及掩耳之势直取顶层平台。', `MaleText_loc5`='沙普比克是鷹巢山最棒的獅鷲獸。他會載你到辛薩羅上面，我們三兩下就會打下頂層平台。', `MaleText_loc7`='Picofilado es el mejor grifo de todo Pico Nidal. Te llevará justo a lo más alto de Jintha''Alor y tomaremos la parte alta sin esfuerzo.' WHERE `ID`=44808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 걸 찾아야 합니다. 우리의 생존이 그 일에 달렸으니까요.', `FemaleText_loc4`='我们必须夺回属于我们的东西。我们的生死存亡在此一举。', `FemaleText_loc5`='我們必須奪下屬於我們的東西。我們的生死存亡端賴於此。', `FemaleText_loc7`='Debemos recuperar lo que nos pertenece. Nuestra supervivencia depende de ello.' WHERE `ID`=44809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진타알로의 꼭대기로 가야겠습니다. 뾰족부리에 타야 할 시간이군요!', `MaleText_loc4`='我需要前往辛萨罗顶部。该沙普比克出场了！', `MaleText_loc5`='我得前往辛薩羅的最上面。是乘坐沙普比克的時候了!', `MaleText_loc7`='Tengo que ir a lo alto de Jintha''Alor. ¡Hora de montar en Picoafilado!', `FemaleText_loc1`='진타알로의 꼭대기로 가야 해요. 뾰족부리에 타야 할 시간이네요!', `FemaleText_loc4`='我需要前往辛萨罗顶部。该沙普比克出场了！', `FemaleText_loc5`='我得前往辛薩羅的最上面。該是乘坐沙普比克的時候了!', `FemaleText_loc7`='Tengo que ir a lo alto de Jintha''Alor. ¡Hora de montar en Picoafilado!' WHERE `ID`=44810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아나스타샤, 바짝 붙어 있거라. 곧 뭔가 재밌는 걸 하러 갈 거니까 말이야.', `FemaleText_loc4`='靠近点儿，安娜斯塔西娅。我们一起找点儿乐子。', `FemaleText_loc5`='安娜塔西亞，請跟著我。我們要去做很好玩的事情。', `FemaleText_loc7`='Anastasia, no te alejes, por favor. Pronto iremos a hacer algo divertido.' WHERE `ID`=44811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 윌리엄과 크리스티와 같이 놀 거란다. 어떠니?', `FemaleText_loc4`='威廉和冬娜过会儿会成为你的玩伴。这听起来如何？', `FemaleText_loc5`='等一下就去找威廉和多娜玩，你覺得怎麼樣?', `FemaleText_loc7`='Luego hemos quedado para jugar con William y Donna. ¿Qué te parece?' WHERE `ID`=44812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아나야, 며칠 전에 꼬마 티미를 봤단다. 새끼 고양이 어떠니?', `FemaleText_loc4`='我前几天遇见小提米了，安娜。你想要养只小猫吗？', `FemaleText_loc5`='安娜，那天我有看到小提米。你想不想養隻小貓?', `FemaleText_loc7`='El otro día vi al pequeño Timmy, Ana. ¿Quieres un gatito?' WHERE `ID`=44813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아가야, 호수가 얼어붙자마자 얼음지치기를 하러 갈 거란다.', `FemaleText_loc4`='等湖面一冻上，我们就去溜冰，宝贝儿。', `FemaleText_loc5`='寶貝，湖一結冰我們就去溜冰。', `FemaleText_loc7`='Iremos a patinar sobre hielo en cuanto se congele el lago, cielo.' WHERE `ID`=44814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 태초의 고귀한 기원으로 돌아가리라!', `MaleText_loc4`='血色十字军将荣返故里！', `MaleText_loc5`='血色十字軍將重返它的神聖根源!', `MaleText_loc7`='¡La Cruzada Escarlata regresará a sus nobles raíces!' WHERE `ID`=44815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼬마 알렉시스의 머리를 땋아 줄 거란다. 얘야, 네 머리도 땋아 줄까?', `FemaleText_loc4`='我们准备帮小安蒂编辫子了。你要编吗，宝贝儿？', `FemaleText_loc5`='我們等一下要去幫小安蒂綁辮子。你也想要綁辮子嗎?', `FemaleText_loc7`='Pronto le vamos a hacer las trenzas a la pequeña Andi. ¿Quieres que hagamos las tuyas también, tesoro?' WHERE `ID`=44816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아나야, 10분 더 지나면 씻어야 한단다. 네가 좋아하는 메뉴가 있는데 바로 치즈 듬뿍 마카로니란다.', `FemaleText_loc4`='安娜，再给你10分钟，然后快点洗漱。我们为你准备了你最爱吃的——通心面与奶酪。', `FemaleText_loc5`='安娜，再十分鐘，你就要去洗手了。今天是你最喜歡的起司漢堡。', `FemaleText_loc7`='Ana, diez minutos más, y luego tienes que lavarte. Vamos a preparar tu plato favorito: macarrones con queso.' WHERE `ID`=44817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아나야, 잠시 항구에 내려가 보는 건 어떠니?', `FemaleText_loc4`='安娜，想不想去港口玩会儿？', `FemaleText_loc5`='安娜，等等想不想去港口走走?', `FemaleText_loc7`='Ana, ¿qué te parece bajar al puerto dentro de un rato?' WHERE `ID`=44818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내일은 왕자 님의 머리를 다듬어 드릴 거란다. 아나야, 가서 왕자님을 뵙고 싶니?', `FemaleText_loc4`='我明天要去帮王子殿下理发。你愿意来见见他吗，安娜？', `FemaleText_loc5`='明天我要幫王子剪頭髮。安娜，你要不要來看他?', `FemaleText_loc7`='Mañana voy a cortarle el pelo al príncipe. ¿Te gustaría venir y conocerlo, Ana?' WHERE `ID`=44819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암울해 보이는 건 알지만, 우리의 적은 그들이 한 짓의 대가를 치를 것이오. 내가 그들이 대가를 치르도록 할 것이란 말이오.', `MaleText_loc4`='我知道情势非常严峻，但我们的敌人一定会为他们的恶行付出代价。我保证。', `MaleText_loc5`='我知道情勢不太樂觀，但是我們的敵人一定得為他們的惡行付出代價。我一定會要他們付出代價的。', `MaleText_loc7`='Sé que pinta mal, pero nuestros enemigos pagarán por lo que han hecho. Me aseguraré de que sea así.' WHERE `ID`=44820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 같은 존재도 저런 멍청이에게 사로잡힐 정도인데 여기까지 오다니, 당신은 매우 용감한 존재임이 틀림없습니다.

할푸스의 주의를 끌고 저를 옭아맨 사슬을 끊어 주신다면 당신 곁에서 함께 싸우겠습니다.

일정 지역 안에서 시간의 흐름을 늦추는 저의 능력은 원시거룡의 화염구 포화를 피하는 데 도움이 될 겁니다.', `MaleText_loc4`='如果连像我这样的人都会被那呆子抓住，那你必须得是个绝对的勇士才能来此冒险。

要是你能转移哈尔弗斯的注意力，帮我挣脱锁链，我就能与你并肩作战。

我能使指定区域内的时间流驶速度变慢，从而使原龙巨兽的火球弹幕无法命中你。', `MaleText_loc5`='你真是勇氣十足，竟然敢冒險闖進這裡頭，因為連我都被那個大傢伙給抓住了。

只要你能夠引開哈福斯的注意，破壞銬住我的鎖鍊，我就可以和你一同並肩作戰。

我的招式可以讓一塊區域內的時間流動變慢，協助你避開元龍巨獸的火球彈幕。', `MaleText_loc7`='Si ese patán inútil puede capturar a alguien como yo, entonces debes de ser muy valiente para aventurarte por aquí.

Si consigues distraer a Halfus y romper las cadenas que me atan, entonces lucharé a tu lado.

Mi capacidad de ralentizar el paso del tiempo en un área te ayudará a esquivar la Tromba de bolas de Fuego del protobehemoth.' WHERE `ID`=44821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 조련사 탈론액스 님의 명령을 받았습니다! 폭풍깃털 전초기지로 보내주십시오!', `MaleText_loc4`='狮鹫管理员沙拉克·鹰斧派我前往风暴之羽哨站！', `MaleText_loc5`='獅鷲獸管理員沙拉克·鷹斧已下令送我到風暴之羽崗哨!', `MaleText_loc7`='¡El maestro de grifos Garracha me ha ordenado que vaya a la Avanzada Tempespluma!', `FemaleText_loc1`='그리핀 조련사 탈론액스 님의 명령을 받았어요! 폭풍깃털 전초기지로 보내주세요!', `FemaleText_loc4`='狮鹫管理员沙拉克·鹰斧派我前往风暴之羽哨站！', `FemaleText_loc5`='獅鷲獸管理員沙拉克·鷹斧已下令送我到風暴之羽崗哨!', `FemaleText_loc7`='¡El maestro de grifos Garracha me ha ordenado que vaya a la Avanzada Tempespluma!' WHERE `ID`=44822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 좋아요!', `FemaleText_loc4`='真棒！', `FemaleText_loc5`='了不起!', `FemaleText_loc7`='¡Genial!' WHERE `ID`=44823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러시던가요.', `FemaleText_loc4`='管它呢。', `FemaleText_loc5`='隨便。', `FemaleText_loc7`='Pues vaya.' WHERE `ID`=44824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요.', `FemaleText_loc4`='酷。', `FemaleText_loc5`='酷。', `FemaleText_loc7`='Bien.' WHERE `ID`=44825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 엄마... 신난다!', `FemaleText_loc4`='呀，天哪……呜！', `FemaleText_loc5`='耶，媽媽...呀呼!', `FemaleText_loc7`='¡Sí, mamá! ¡Yuju!' WHERE `ID`=44826;
