UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 알았어요.', `FemaleText_loc4`='喔呀，啊哈。', `FemaleText_loc5`='哦，好吧。', `FemaleText_loc7`='Ya, ajá.' WHERE `ID`=44828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았어요.', `FemaleText_loc4`='好。', `FemaleText_loc5`='好吧。', `FemaleText_loc7`='Vale.' WHERE `ID`=44829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네!', `FemaleText_loc4`='哈！', `FemaleText_loc5`='好!', `FemaleText_loc7`='¡Sí!' WHERE `ID`=44830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말을 걸었을 때만 대답하게.', `FemaleText_loc4`='不该你说话时别多嘴。', `FemaleText_loc5`='有人問你話你才准開口。', `FemaleText_loc7`='Hablarás cuando te dirijan la palabra.' WHERE `ID`=44831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오주마트가 돌아왔다! 안 돼!! [임시]', `MaleText_loc4`='厄祖玛特回来了！哦不~[PH]', `MaleText_loc5`='Ozumat is back! Oh noes~ [PH]', `MaleText_loc7`='Ozumat is back! Oh noes~ [PH]' WHERE `ID`=44832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 짓도 지긋지긋하군... 이제 놀아 볼까! [임시]', `MaleText_loc4`='够了……准备开始！', `MaleText_loc5`='Enough of this... ITS GO TIME! [PH]', `MaleText_loc7`='Enough of this... ITS GO TIME! [PH]' WHERE `ID`=44833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이겼다! 여기 선물이 있다. 고맙다. [임시]', `MaleText_loc4`='我们赢了！这儿有点奖品，谢谢。', `MaleText_loc5`='We win! Heres some loot, thx. [PH]', `MaleText_loc7`='We win! Heres some loot, thx. [PH]' WHERE `ID`=44834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 정말 상대하기 힘든 녀석이었습니다.', `MaleText_loc4`='谢谢。那家伙可真难缠！', `MaleText_loc5`='謝謝。那隻野獸真是難搞!', `MaleText_loc7`='Gracias. ¡Menuda bestia!', `FemaleText_loc1`='고마워요. 정말 상대하기 힘든 녀석이었어요.', `FemaleText_loc4`='谢谢。那家伙可真难缠！', `FemaleText_loc5`='謝謝。那隻野獸真是難搞!', `FemaleText_loc7`='Gracias. ¡Menuda bestia!' WHERE `ID`=44835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 짐승이 정말 난데없이 나타났습니다!', `MaleText_loc4`='那家伙简直神出鬼没！', `MaleText_loc5`='那隻野獸不知道從哪裡冒出來的!', `MaleText_loc7`='¡Esa bestia ha salido de la nada!', `FemaleText_loc1`='그 짐승이 정말 난데없이 나타났어요!', `FemaleText_loc4`='那家伙简直神出鬼没！', `FemaleText_loc5`='那隻野獸不知道從哪裡冒出來的!', `FemaleText_loc7`='¡Esa bestia ha salido de la nada!' WHERE `ID`=44836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 더러운 늑대인간 녀석! 네 시체에 침을 뱉어주마!', `MaleText_loc4`='狼人渣滓！我要朝你的尸体吐口水！', `MaleText_loc5`='可惡的狼人!我要在你的屍體上吐口水!', `MaleText_loc7`='¡Escoria huargen! ¡Escupo sobre tu cadáver!', `FemaleText_loc1`='이 더러운 늑대인간 녀석! 네 시체에 침을 뱉어주마!', `FemaleText_loc4`='狼人渣滓！我要朝你的尸体吐口水！', `FemaleText_loc5`='可惡的狼人!我要在你的屍體上吐口水!', `FemaleText_loc7`='¡Escoria huargen! ¡Escupo sobre tu cadáver!' WHERE `ID`=44837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅을 차지하려면 녀석들은 나부터 쓰러뜨려야 할 거요!', `MaleText_loc4`='想夺走我们的土地，没那么容易！', `MaleText_loc5`='我們不會把土地拱手奉送給他們!', `MaleText_loc7`='¡No tomarán nuestra tierra sin luchar!', `FemaleText_loc1`='우리 땅을 차지하려면 녀석들은 나부터 상대해야 할 거예요!', `FemaleText_loc4`='想夺走我们的土地，没那么容易！', `FemaleText_loc5`='我們不會把土地拱手奉送給他們!', `FemaleText_loc7`='¡No tomarán nuestra tierra sin luchar!' WHERE `ID`=44838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 영웅이시여!', `MaleText_loc4`='谢谢你，英雄！', `MaleText_loc5`='謝謝你，英雄!', `MaleText_loc7`='¡Gracias, $ghéroe:heroína;!', `FemaleText_loc1`='고마워요, 영웅님!', `FemaleText_loc4`='谢谢你，英雄！', `FemaleText_loc5`='謝謝你，英雄!', `FemaleText_loc7`='¡Gracias, $ghéroe:heroína;!' WHERE `ID`=44839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지배자의 관문에 뭐 그리 중요한 게 있는지 알아보려고 해요.$B$B그 황혼의 얼간이 녀석들, 분명히 뭔가 쓸데없는 짓을 벌이고 있을 거라고요. 불공평해요! 단서를 따라 여기까지 왔는데 가까이 가지도 못하고 있으니.', `FemaleText_loc4`='我们在设法弄清真主之门那里究竟有什么重要的事情在发生。$B$B但我可以确保，那些暮光之锤败类一定不会干什么好事。太反常了！我们一路追随线索而来，现在却连靠近都做不到。', `FemaleText_loc5`='我們正努力要釐清主宰之門那邊到底有什麼重要性。$B$B我只知道暮光之錘的那些混蛋肯定在醞釀著什麼詭計。啊，不公平!我們大老遠追著線索跑來這裡，結果根本沒辦法靠近。', `FemaleText_loc7`='Intentamos averiguar qué hay que sea tan importante en la Puerta de los Maestros.$b$bEstoy segura de que esos idiotas del Martillo no traman nada bueno. ¡No es justo! Hemos llegado hasta aquí siguiendo una pista y ahora no podemos ni acercarnos.' WHERE `ID`=44840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 하늘의 주인이다. 내 자식들을 위협한 자는 고통을 받으리라.', `FemaleText_loc4`='我是天穹之主，谁胆敢威胁我的孩子，就必须付出代价。', `FemaleText_loc5`='我乃統御九天之蒼穹女王，凡威脅我子民者都將受到制裁。', `FemaleText_loc7`='Soy la señora de los cielos, y aquellos que amenacen a mis hijos sufrirán.' WHERE `ID`=44841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n! 썬더 블러프가 자네에게 큰 빚을 졌군.', `MaleText_loc4`='干得好，$n！雷霆崖欠你一份人情。', `MaleText_loc5`='幹得好，$n!雷霆崖欠你一個人情。', `MaleText_loc7`='¡Bien hecho, $n! Cima del Trueno está en deuda contigo.', `FemaleText_loc1`='고맙네, $n! 썬더 블러프가 자네에게 큰 빚을 졌군.', `FemaleText_loc4`='干得好，$n！雷霆崖欠你一份人情。', `FemaleText_loc5`='幹得好，$n!雷霆崖欠你一個人情。', `FemaleText_loc7`='¡Bien hecho, $n! Cima del Trueno está en deuda contigo.' WHERE `ID`=44842;
