UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했습니다, $n! 아이언포지가 당신에게 빚을 지었군요.', `MaleText_loc4`='干得好，$n！铁炉堡欠你一份人情。', `MaleText_loc5`='幹得好，$n!鐵爐堡欠你一個人情。', `MaleText_loc7`='¡Bien hecho, $n! Forjaz está en deuda contigo.', `FemaleText_loc1`='수고했습니다, $n! 아이언포지가 당신에게 빚을 지었군요.', `FemaleText_loc4`='干得好，$n！铁炉堡欠你一份人情。', `FemaleText_loc5`='幹得好，$n!鐵爐堡欠你一個人情。', `FemaleText_loc7`='¡Bien hecho, $n! Forjaz está en deuda contigo.' WHERE `ID`=44844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $n. 썬더 블러프의 진정한 영웅이자 수호자여! 모두 $n의 용감하고 위대한 업적을 길이길이 기억하라!', `MaleText_loc4`='向你致敬，$n，真正的勇士，雷霆崖的守护者！每个人都该永远铭记$n的英勇事迹！', `MaleText_loc5`='$n萬歲!一個真正的勇士，同時也是雷霆崖的救星!所有人都會記得$n的英勇事蹟!', `MaleText_loc7`='¡Tres hurras por $n, un verdadero campeón y sostén de Cima del Trueno! ¡Que nadie olvide jamás las valientes hazañas de $n!', `FemaleText_loc1`='어서 오게, $n. 썬더 블러프의 진정한 영웅이자 수호자여! 모두 $n의 용감하고 위대한 업적을 길이길이 기억하라!', `FemaleText_loc4`='向你致敬，$n，真正的勇士，雷霆崖的守护者！每个人都该永远铭记$n的英勇事迹！', `FemaleText_loc5`='$n萬歲!一個真正的勇士，同時也是雷霆崖的救星!所有人都會記得$n的英勇事蹟!', `FemaleText_loc7`='¡Tres hurras por $n, un verdadero campeón y sostén de Cima del Trueno! ¡Que nadie olvide jamás las valientes hazañas de $n!' WHERE `ID`=44845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 모두 오그리마의 진정한 영웅, $n의 이름을 기억하라!', `MaleText_loc4`='Lok''tar！所有人都不该忘却这个名字——$n，奥格瑞玛真正的勇者！向你致敬，$n！', `MaleText_loc5`='為了部落!讓$n名留千史，這位奧格瑪真正的英雄!$n萬歲!', `MaleText_loc7`='¡Lok''tar! ¡Que nadie olvide jamás el nombre de $n, un verdadero campeón de Orgrimmar! ¡Tres hurras por $n!', `FemaleText_loc1`='록타르! 모두 오그리마의 진정한 영웅, $n의 이름을 기억하라!', `FemaleText_loc4`='Lok''tar！所有人都不该忘却这个名字——$n，奥格瑞玛真正的勇者！向你致敬，$n！', `FemaleText_loc5`='為了部落!讓$n名留千史，這位奧格瑪真正的英雄!$n萬歲!', `FemaleText_loc7`='¡Lok''tar! ¡Que nadie olvide jamás el nombre de $n, un verdadero campeón de Orgrimmar! ¡Tres hurras por $n!' WHERE `ID`=44846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $n. 아이언포지의 진정한 영웅이자 수호자여! 모두 $n의 용감하고 위대한 업적을 길이길이 기억하라!', `MaleText_loc4`='向你致敬，$n，真正的勇士，铁炉堡的守护者！每个人都该永远铭记$n的英勇事迹！', `MaleText_loc5`='$n萬歲!一個真正的勇士，同時也是鐵爐堡的救星!所有人都會記得$n的英勇事蹟!', `MaleText_loc7`='¡Tres hurras por $n, un verdadero campeón y sostén de Forjaz! ¡Que nadie olvide jamás las valientes hazañas de $n!', `FemaleText_loc1`='어서 오게, $n. 아이언포지의 진정한 영웅이자 수호자여! 모두 $n의 용감하고 위대한 업적을 길이길이 기억하라!', `FemaleText_loc4`='向你致敬，$n，真正的勇士，铁炉堡的守护者！每个人都该永远铭记$n的英勇事迹！', `FemaleText_loc5`='$n萬歲!一個真正的勇士，同時也是鐵爐堡的救星!所有人都會記得$n的英勇事蹟!', `FemaleText_loc7`='¡Tres hurras por $n, un verdadero campeón y sostén de Forjaz! ¡Que nadie olvide jamás las valientes hazañas de $n!' WHERE `ID`=44847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다... 제련장인 찾는 걸 도와드리고 싶은 마음입니다.', `MaleText_loc4`='谢谢你……真希望我能帮你找到铸炉之主。', `MaleText_loc5`='謝謝你...真希望我能幫你找到鍛造大師。', `MaleText_loc7`='Gracias... Ojalá pudiera ayudarte a encontrar al maestro de forja.' WHERE `ID`=44848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인은 끔찍한 살인마입니다. 정말 제련장인을 찾아나설 생각인가요?', `MaleText_loc4`='铸炉之主是个杀人狂魔。你确定想要去找他吗？', `MaleText_loc5`='鍛造大師是個恐怖的兇手。你確定要去找他嗎?', `MaleText_loc7`='El maestro de forja es un asesino terrible. ¿Seguro que quieres ir en su busca?' WHERE `ID`=44849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 맞아요... 제련장인에 대해 좀 알아요! 막 이야기를 엿들었는데, 지금 이 야영지에 없다고 했어요.', `MaleText_loc4`='啊，是的……我知道铸炉之主！我刚才不小心听说他现在不在里边。', `MaleText_loc5`='啊，對...我知道那個鍛造大師!我剛聽說現在他人不在營地裡頭。', `MaleText_loc7`='Ah, sí... ¡Conozco al maestro de forja! Acabo de oír que no se encuentra en el campamento ahora mismo.' WHERE `ID`=44850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인과 황혼의 망치단 수뇌부 간의 회합이 있을 겁니다. 믿어 주세요. 썩은 빵조각을 주고 얻은 정보라고요!', `MaleText_loc4`='铸炉之主正在和暮光官员会面。相信我，这是我用变质面包换来的小道消息！', `MaleText_loc5`='鍛造大師去見暮光之錘的首領了。相信我，這是我用一條乾掉的麵包換來的情報!', `MaleText_loc7`='El maestro de forja está reunido con la cúpula Crepuscular. Créeme, ¡he cambiado una barra de pan rancio por este cotilleo!' WHERE `ID`=44851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 제련장인에 대해 아는 게 없어요. 이제 당신이 왔다는 그 안전한 곳이 어딘지 말해 주세요.', `MaleText_loc4`='我不认识什么铸炉之主。快告诉我你是从什么安全的地方来的？', `MaleText_loc5`='什麼鍛造大師的事情我通通不知道。好了，告訴我，你來的那個安全地方是在哪裡!', `MaleText_loc7`='No sé nada de ningún maestro de forja. ¡Ahora dime dónde está ese lugar seguro del que has venido!' WHERE `ID`=44852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인이 회합에 대한 정보를 적어 놓은 책이 야영지가 한눈에 보이는 탑 안에 있다는 얘기를 들었습니다.', `MaleText_loc4`='我听说铸炉之主把会面纪要夹在一本书中，藏在一座可俯瞰营地的塔里。', `MaleText_loc5`='我聽說鍛造大師有把他的會議行程寫在一本書裡，擺在俯瞰營地的那座塔裡。', `MaleText_loc7`='He oído que el maestro de forja guarda las notas de sus reuniones en un libro en la torre que se alza sobre el campamento.' WHERE `ID`=44853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 트윈이라고 부르세요. 모위도 절 그렇게 부르죠.$B$B우리가 똑같이 생겼다니 무슨 말씀이세요. 시력이 안 좋으세요? 모위는 노움이란 말이에요, 노움! 우린 행동을 함께해요. 특히 싸울 때 말이죠.$B$B제 이름에 대해서는... 혹시 와일드해머 브루워 얘기 못 들어 보셨어요? 한잔하면서 얘기할까요?', `FemaleText_loc4`='请叫我孪生姐妹。莫维就是这么称呼我的。$B$B不，我们长的不像。你瞎了吗？看在圣光的份上——她可是个侏儒！不过我们行事方式很像。尤其是在打架的时候。$B$B至于我的名字……你听说过鼎鼎大名的蛮锤布鲁尔家族吗？想不想来杯佳酿？', `FemaleText_loc5`='叫我雙胞胎吧。摩維都是這樣叫我的。$B$B沒有，我們長得一點也不像。你是瞎了嗎?拜託，她是個地精好不好!我們是動作像，尤其戰鬥的時候。$B$B至於我的名字...你難道沒聽過鼎鼎大名的蠻錘釀酒師布魯爾?還要不要跟我來拼一杯看看?', `FemaleText_loc7`='Llámame Gemela. Así es como me llama Mowi.$B$BNo, no nos parecemos en nada. ¿Es que estás $gcegato:cegata;? ¡Ella es una gnoma, por la Luz! Actuamos bastante parecido. Sobre todo cuando luchamos.$B$BEn cuanto a mi nombre... ¿Es que nunca has oído hablar de los famosos cerveceros Martillo Salvaje? ¿Te apetece una pinta?' WHERE `ID`=44854;
