UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황폐의 혼합물을 사용하여 모든 멀록을 처치해야 합니다!$B$B|r|Tinterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `MaleText_loc4`='用凋零化合药剂消灭所有鱼人！$B$B|r|TInterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `MaleText_loc5`='用荒疫混合物消滅所有的魚人!$B$B|r|TInterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `MaleText_loc7`='¡Elimina a todos los múrlocs con el brebaje de añublo!$B$B|r|TInterfaceIconsINV_ALCHEMY_POTION_05.BLP:24|t', `FemaleText_loc1`='황폐의 혼합물을 사용하여 모든 멀록을 처치해야 합니다!$B$B|r|Tinterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `FemaleText_loc4`='用凋零化合药剂消灭所有鱼人！$B$B|r|TInterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `FemaleText_loc5`='用荒疫混合物消滅所有的魚人!$B$B|r|TInterface\\Icons\\INV_ALCHEMY_POTION_05.BLP:24|t', `FemaleText_loc7`='¡Elimina a todos los múrlocs con el brebaje de añublo!$B$B|r|TInterfaceIconsINV_ALCHEMY_POTION_05.BLP:24|t' WHERE `ID`=44902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰 고위 사령부로 돌아갑니다!$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `MaleText_loc4`='返回被遗忘者统帅部！$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `MaleText_loc5`='返回被遺忘者高階指揮所!$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `MaleText_loc7`='¡Volviendo al Alto Mando Renegado!$B$B|r|TInterfaceIconsACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `FemaleText_loc1`='포세이큰 고위 사령부로 돌아갑니다!$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `FemaleText_loc4`='返回被遗忘者统帅部！$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `FemaleText_loc5`='返回被遺忘者高階指揮所!$B$B|r|TInterface\\Icons\\ACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t', `FemaleText_loc7`='¡Volviendo al Alto Mando Renegado!$B$B|r|TInterfaceIconsACHIEVEMENT_ZONE_SILVERPINE_01.BLP:24|t' WHERE `ID`=44903;
