UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 그 박쥐 무사히 데려오는 편이 좋을거야!', `MaleText_loc4`='你最好把那只蝙蝠毫发无伤地带来，$n！', `MaleText_loc5`='你最好把蝙蝠給我完整無缺地送回來，$n!', `MaleText_loc7`='¡Más te vale devolver ese murciélago de una pieza, $n!' WHERE `ID`=44906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르투나가 강력한 주문을 준비합니다. 안전한 곳으로 대피하십시오!', `MaleText_loc4`='洛苏娜正在准备施放一个强大的法术——快躲好！', `MaleText_loc5`='洛舒娜正在準備一道強大的法術—快找掩護躲起來!', `MaleText_loc7`='Lorthuna está preparando un hechizo poderoso. ¡Cúbrete!', `FemaleText_loc1`='로르투나가 강력한 주문을 준비합니다. 안전한 곳으로 대피하십시오!', `FemaleText_loc4`='洛苏娜正在准备施放一个强大的法术——快躲好！', `FemaleText_loc5`='洛舒娜正在準備一道強大的法術—快找掩護躲起來!', `FemaleText_loc7`='Lorthuna está preparando un hechizo poderoso. ¡Cúbrete!' WHERE `ID`=44907;
