UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도에 대한 건 아무것도 몰라요! 돌아가서 일하게 해 주세요...', `MaleText_loc4`='我对教派一无所知！快放我回去工作吧……', `MaleText_loc5`='我不知道什麼邪教的事情!請讓我回去工作...', `MaleText_loc7`='¡No sé nada de ninguna secta! Déjame volver al trabajo, por favor...' WHERE `ID`=44909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화... 화... 황혼의 마... 망치단이라고요? 저한테 그들이 접근하지 못하게 해 주세요!', `MaleText_loc4`='暮——暮——暮光之——之锤？离我远点！', `MaleText_loc5`='暮—暮—暮光之—之錘?要他們離我遠一點!', `MaleText_loc7`='¿Ma-ma-martillo Cre-crepuscular? ¡No dejes que se me acerquen!' WHERE `ID`=44910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 끝장내겠다는 그 정신 나간 이교도들 말인가요? 뭔가 들으면, 당신에게 가장 먼저 알려 드리죠!', `MaleText_loc4`='什么？那个疯狂的世界末日教派？要是我听说了什么，我会第一个告诉你的！', `MaleText_loc5`='嗯?那個什麼世界末日的瘋子教派?我要是有聽到什麼，我一定會第一個告訴你!', `MaleText_loc7`='¿Qué, esa secta de locos apocalípticos? ¡Si oigo algo, serás $gel primero:la primera; en saberlo!' WHERE `ID`=44911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 뭘 바라시는 건가요? 전 그저 허드렛일이나 하는 일꾼일 뿐이라고요!', `MaleText_loc4`='你要问我什么？我是个只会干活的傻瓜！', `MaleText_loc5`='你要問我什麼?我只是來搬箱子的!', `MaleText_loc7`='¿Y a mí qué me cuentas? ¡Yo solo transporto cajas!' WHERE `ID`=44912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 그를 발견했을 때 이미 죽어 있었다고요! 맹세해요! 뭐... 아... 황혼의 망치단이요? 아니요, 그런 친구들에 대해선 모르는데요.', `MaleText_loc4`='我发誓在我找到他的时候他已经死了！什么——喔——暮光之锤？不，我什么也不知道。', `MaleText_loc5`='我發誓，我發現那個傢伙的時候他就已經死了!什麼—哦—暮光之錘?沒有，我什麼也不知道。', `MaleText_loc7`='¡Juro que ese tipo ya estaba muerto cuando lo encontré! ¿Qué? Ah, ¿el Martillo Crepuscular? De eso no sé nada.' WHERE `ID`=44913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나도 들은 적 없어요! 맹세해요!', `MaleText_loc4`='我什么也没听说。我发誓！', `MaleText_loc5`='我什麼也沒聽說。我發誓!', `MaleText_loc7`='No he oído nada, ¡lo juro!' WHERE `ID`=44914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 결백하다고요, 결백해요! 대격변은 제 잘못이 아니란 말이에요!', `MaleText_loc4`='我是无辜的！无辜的听到没有！大灾变不是我的错！', `MaleText_loc5`='我是無辜的。我說真的，我是無辜的!這場大災變不是我的錯!', `MaleText_loc7`='Soy inocente. Inocente, ¿me oyes? ¡El Cataclismo no fue culpa mía!' WHERE `ID`=44915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야아아아아!', `MaleText_loc4`='呀！', `MaleText_loc5`='耶啊!', `MaleText_loc7`='¡Yarrr!', `FemaleText_loc1`='야아아아아!', `FemaleText_loc4`='呀！', `FemaleText_loc5`='耶啊!', `FemaleText_loc7`='¡Yarrr!' WHERE `ID`=44916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만!', `MaleText_loc4`='停！', `MaleText_loc5`='停!', `MaleText_loc7`='¡Alto ahí!', `FemaleText_loc1`='그만!', `FemaleText_loc4`='停！', `FemaleText_loc5`='停!', `FemaleText_loc7`='¡Alto ahí!' WHERE `ID`=44917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이!', `MaleText_loc4`='啊哈！', `MaleText_loc5`='喂!', `MaleText_loc7`='¡Ah del barco!', `FemaleText_loc1`='어이!', `FemaleText_loc4`='啊哈！', `FemaleText_loc5`='喂!', `FemaleText_loc7`='¡Ah del barco!' WHERE `ID`=44918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 여기서 환영받지 못한다, 암네나르.', `FemaleText_loc4`='这里不欢迎你，亚门纳尔。', `FemaleText_loc5`='亞門納爾，這裡不歡迎你。', `FemaleText_loc7`='Tu presencia no es bien recibida aquí, Amnennar.' WHERE `ID`=44920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s|1이;가; |cFFFF0000|Hspell:83445|h[충격파]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s开始施放|cFFFF0000|Hspell:83445|h[震荡波]！|h|r', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s開始施展|cFFFF0000|Hspell:83445|h[衝擊波]!|h|r', `MaleText_loc7`='|TInterfaceIconsspell_nature_earthquake.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:83445|h[Ola de choque]!|h|r' WHERE `ID`=44921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 저주받은 땅에 무슨 볼일로 오셨나요?', `FemaleText_loc4`='是什么把你带到这片受诅咒的土地上来的？', `FemaleText_loc5`='你來這個受詛咒的地方做什麼?', `FemaleText_loc7`='¿Qué te trae a estas tierras malditas?' WHERE `ID`=44922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 땅속에서 티탄의 차원문을 발견했습니다. 이 차원문을 활성화하려는 것 같습니다.', `MaleText_loc4`='暮光之锤挖出了泰坦界门，而且似乎正在试图激活它。', `MaleText_loc5`='暮光之錘挖掘出了一個泰坦甬道之門，而且他們好像正試圖要啟動它。', `MaleText_loc7`='El Martillo Crepuscular ha desenterrado una puerta de los titanes y parece que están intentando activarla.' WHERE `ID`=44923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕이 전사했으니 제게 남겨진 것이라고는 저의 본분뿐이군요. 가족도 없고, 친구도 없습니다... 오직 이것뿐이군요.$b$b전쟁 말입니다.', `MaleText_loc4`='巫妖王既死，我所拥有的就只剩下责任。没有家人，没有朋友……只有这个。$b$b战争。', `MaleText_loc5`='在巫妖王死後，我唯一剩下的就只有責任。我沒有家人、沒有朋友...就只有這場...$b$b戰爭。', `MaleText_loc7`='Tras la muerte del Rey Exánime, todo lo que me queda es el deber. Ya no existe la familia, ya no existen los amigos. Solo existe una cosa.$b$bLa guerra.' WHERE `ID`=44924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 별로 쓸만한 정보가 없군요.', `MaleText_loc4`='嗯……这儿没有有用的信息。', `MaleText_loc5`='嗯...沒什麼有用的情報。', `MaleText_loc7`='Mmmm... Aquí no hay información útil.' WHERE `ID`=44925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 정말 백성을 잘 다루시는군요, $n 님. 그들은 당신을 무서워하면서도 경외한답니다.', `MaleText_loc4`='你可真擅长和人打交道啊，$n。人们惧怕你，却又尊敬你。', `MaleText_loc5`='你對人真的很有一套，$n。他們對你又怕又敬。', `MaleText_loc7`='Tú sí que sabes tratar a la gente, $n. Te temen y te respetan.' WHERE `ID`=44926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 아무래도 쓸데없는 짓 같지 않나요? 일꾼들은 아무것도 모른다고요!', `MaleText_loc4`='你不觉得这是在浪费时间吗？这些工人一无所知！', `MaleText_loc5`='你不覺得這只是在捕風捉影嗎?這些工人根本什麼都不知道!', `MaleText_loc7`='¿No te parece que estamos perdiendo el tiempo? ¡Estos obreros no saben nada!' WHERE `ID`=44927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가즈리디안이 더 있다고? 도대체 자네는 내가 왜 그 지긋지긋한 물건을 더 가지고 싶어한다고 생각하는 건가? 한 9,000개쯤 가지고 있는데, 전혀 안 팔린단 말이야! 왜 나는 커다란 뱀 동상이라면 누구라도 좋아할 거라고 생각한 거지? 쳇!', `MaleText_loc4`='更多加兹瑞迪安？你为什么觉得我还愿意要更多这玩意？我已经积压了九千个了，一个都卖不出去！我竟然以为有人会对这种超大块头的毒蛇雕像感兴趣！啊呸！', `MaleText_loc5`='還有更多加茲瑞迪安?你為什麼會覺得我還需要更多這些個鬼東西?我已經堆了快九千個了，而且根本賣不出去!我怎麼會蠢到以為大家會想要買大隻蛇的雕像?呃啊!', `MaleText_loc7`='¿MÁS Ghaz''ridian? ¿Qué te hace pensar que podría querer MÁS de esos trastos infernales? Tengo más de nueve mil, ¡y no se venden! ¿Por qué pensé que nadie querría una estatua de una serpiente descomunal? ¡Bah!' WHERE `ID`=44928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사막유랑단과 그들의 지도자인 칼리프 스콜피드스팅이 남쪽으로 가는 걸 봤어. 조심해야 할 거야. 놈들은 조금 더 강해진 것 같이 보이더라고!', `MaleText_loc4`='我看见废土强盗和他们的领袖——卡利夫·斯科比斯汀往南边去了。多加小心，他们看起来更强大了！', `MaleText_loc5`='我看到廢土強盜和他們的頭子卡利夫·斯科比斯汀從這邊往南去了。小心一點，他們好像變得更難纏了!', `MaleText_loc7`='Vi a los Vagayermos y a su líder, Califa Escorpijón, dirigiéndose hacia el sur. Cuidado, ¡parecía que se habían endurecido un poco!' WHERE `ID`=44929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 본 벌레 중 가장 거대한 벌레가 저 실리시드 곤충집 한쪽을 돌아다니는 걸 봤어. 아니면 양쪽이거나 말이야. 아무래도 열사병이 오나봐... 저기 있는 모래 고양이가 자네도 보이나?', `MaleText_loc4`='我见到一只你前所未见的大虫子，就在那其中一个——要不就是两个异种蝎虫巢附近徘徊。我想我快要中暑了……你看见那边那只沙猫没？', `MaleText_loc5`='我在其中一個異種蟲巢看到一隻超級大隻的蟲，從來沒見過那麼大隻的。咦，還是是兩隻?我好像有點快中暑了...你有沒有看到在那邊的沙貓?', `MaleText_loc7`='Vi al bicho más grande que te puedas imaginar paseándose por una de esas colmenas silítidas. O quizá fueran las dos. Creo que el calor me está afectando... ¿Tú puedes ver a ese gato de arena de ahí?' WHERE `ID`=44930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용에 대해서는 아는 게 별로 없지만, 하루는 거대하고 무섭게 생긴 용이 저기 있는 시간의 동굴 입구 근처에서 나타나더라고. 그 용은 계속 어떤 것에 대해 고함을 질러댔는데... 그게 뭐더라... 우리가 알고 있는 시간에 종말 어쩌고저쩌고했는데? 그다지 신경 쓰이지는 않더라고.', `MaleText_loc4`='我对龙没什么研究，可有一天，突然有一只又大又可怕的龙出现在那边——就在时光之穴入口附近。他不停的叫嚷着……说什么来着……我们所知的时间尽头？我还真没怎么注意听。', `MaleText_loc5`='我對龍瞭解不多，但是某一天有隻大傢伙忽然出現在那邊，就是那個時光之穴的入口。他一直在喊什麼...什麼末日...什麼...時間到了之類的?我反正沒有特別注意。', `MaleText_loc7`='No sé mucho de dragones, pero el otro día apareció uno grande y temible por allí, cerca de la entrada a las Cavernas del Tiempo. No dejaba de gritar algo sobre... A ver si me acuerdo... ¿el fin del tiempo tal y como lo conocemos? No estaba prestando mucha atención.' WHERE `ID`=44931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 오랜 친구인 프롱클이 가젯잔으로 왔어야 하는데, 그 친구와 나머지 빌지워터 승무원들이 탄 배가 도착하지 않았어. 어떤 정신 나간 고블린이 멀리 남쪽에 추락한 비행선 근처에 매달려 있다는 소문을 들었는데... 혹시...?', `MaleText_loc4`='我一位名叫Frokle的老友原本是要前往加基森，可他和船上的所有锈水船员却从来都没有抵达。我听说在遥远的南边，有一伙疯狂的地精潜伏在一架被击落的飞行器附近，会不会是……？', `MaleText_loc5`='我有個叫做佛隆寇的老朋友，他本來是要來加基森的，可是他和污水企業的其他船員們一直都沒有抵達。我聽說在南邊遠處有個瘋掉的哥布林在一架墜毀的飛行器旁邊晃來晃去，莫非就是...?', `MaleText_loc7`='Un viejo amigo mío llamado Frokle venía en dirección a Gadgetzan, pero no han llegado ni él ni el resto de la tripulación Pantoque que pilotaba el barco. He oído rumores de un goblin loco que se encuentra cerca de una máquina voladora derriba al sur del todo, ¿podría ser...?' WHERE `ID`=44932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특허 출원 중인 센티파르 실리시드 과자의 잠재적 이윤 가치를 알아보던 도중에 모래 언덕 사이에서 부서진 짐마차를 발견했어. 나는 이렇게 생각했지. "이야, 공짜로 짐마차가 생겼구나!"라고 말이야. 적어도 자네가 이제껏 본 것 중에 가장 커다란 바실리스크가 나타나기 전까지는 그랬지. 그래서 나는 모든 걸 놓아두고 도망칠 수밖에 없었다고!', `MaleText_loc4`='我在沙丘那边分析森提帕尔异种蝎小吃（专利申请中）的潜在利润时，发现了一辆破旧的货车。于是我想，“嘿，免费货车哎！”后来就出现了那只你前所未见的大蜥蜴，害得我只能空手而逃！', `MaleText_loc5`='當我在研究「森提帕爾異種蟲點心」—專利申請中—的獲利性的時候，我在沙丘當中看到了一輛損毀的推車。我對自己說，「嘿，免費的推車!」結果話才說完，一隻我所見過最大隻的蜥蜴就這麼冒出來了，害我只好空手跑回來!', `MaleText_loc7`='"Me encontré un carro roto entre las dunas cuando estaba estudiando los beneficios potenciales de los Aperitivos de Silítido Centipaar (pendiente de patente). Me dije: "Oye, ¡carro gratis!". ¡Pero entonces el basilisco más grande que has visto en tu vida apareció y tuve que dejarlo todo atrás!' WHERE `ID`=44933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 거대한 흙더미가 모래언덕 아래 주변으로 움직이는 걸 본 적이 있나? 놈들은 아제로스에서는 보이지 않았던 땅굴 벌레와 같은 종에 속하는 것들이라고! 저 사나운 것들은 자네같이 노련한 모험가가 배움을 통해 경험을 쌓을 대상으로는 아주 적절하지.', `MaleText_loc4`='你见过那些会在沙丘地下窜来窜去的大土堆吗？它们是隧道虫的一种，艾泽拉斯大陆上可从来没出现过这玩意儿！要是能和它们斗上一场，对向你这样经验丰富的冒险家来说，一定是次难得的学习机会。', `MaleText_loc5`='你有看過在沙丘底下四處移動的那些土堆嗎?它們是一種艾澤拉斯從來沒見過的掘地蟲品種!我相信如果能跟它們打上一架，對你這種老練的冒險者來講肯定是個很棒的學習經驗。', `MaleText_loc7`='¿Has visto esos grandes montones de tierra que se mueven debajo de las dunas? ¡Pertenecen a un tipo de gusano tunelador que no se ha visto nunca en Azeroth! Estoy seguro de que luchar contra uno sería una gran experiencia de aprendizaje para $gun aventurero experimentado:una aventurera experimentada; como tú.' WHERE `ID`=44934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변이 일어났을 때, 아제로스의 정령들에 감겨 있던 연결고리들이 심각하게 약해졌지. 그 정령 중 하나인 아쿠에멘타스는 더는 속박받지 않고 있어. 아쿠에멘타스가 남쪽바다 해적단을 위해 중대한 문제를 일으키고 있다더라고!', `MaleText_loc4`='大灾变发生时，艾泽拉斯元素间的连结大大弱化了。其中一个元素——亚奎门塔斯，获得了自由。我听说他正在给南海海盗制造不小的麻烦！', `MaleText_loc5`='當大災變發生時，束縛艾澤拉斯元素的連結大幅度地弱化了。其中一個元素，亞奎門塔斯，已經不再受到監禁了。我聽說它正為南海那群人帶來很大的災難!', `MaleText_loc7`='Cuando se desencadenó el Cataclismo, los vínculos que atan a los elementales de Azeroth se debilitaron considerablemente. Uno de ellos, Aquamentas, ya no está aprisionado. ¡He oído que les está dando muchos problemas a los tipos de los Mares del Sur!' WHERE `ID`=44935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽으면 죽었지 잡히나 봐라!', `MaleText_loc4`='你别想活捉我！', `MaleText_loc5`='你絕對無法活捉我的!', `MaleText_loc7`='¡Nunca me cogerás vivo!' WHERE `ID`=44936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이를 대신해 뭔가 모으러 가시는 일이 흔한가요? 영웅이 할 일은 끝이 없군요.', `MaleText_loc4`='你经常替人找东西吗？我以为英雄的时间总是很宝贵呢。', `MaleText_loc5`='你經常被人叫去幫忙收集東西嗎?英雄的事情還真是忙不完啊。', `MaleText_loc7`='¿La gente te suele mandar a recoger sus cosas a menudo? Supongo que el trabajo de un héroe no se acaba nunca.' WHERE `ID`=44937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발물이 죄다 사라졌다고요?! $n 님, 뭔가 사악한 일이 벌어지고 있는 게 확실합니다.', `MaleText_loc4`='我们所有的炸药都不见了？！$n，这里一定正在酝酿着什么邪恶的事情。', `MaleText_loc5`='什麼，全部的炸藥都不見了!?$n，這當中肯定有古怪。', `MaleText_loc7`='¿Han desaparecido todos nuestros explosivos? $n, no cabe duda de que aquí está pasando algo siniestro.' WHERE `ID`=44938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<화장실은 조용합니다.>', `MaleText_loc4`='<厕所里一片死寂。>', `MaleText_loc5`='<廁所靜悄悄的。>', `MaleText_loc7`='<La letrina está en silencio.>' WHERE `ID`=44939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요릭, 안에 있습니까? 준비 됐습니다! 출발!', `MaleText_loc4`='尤瑞克，你在里面吗？我可要动手啦！我们上！', `MaleText_loc5`='尤瑞克，你在裡面嗎?我已經準備好了!我們走吧!', `MaleText_loc7`='Yorick, ¿estás ahí? ¡Estoy listo! ¡Vámonos!', `FemaleText_loc1`='요릭, 안에 있나요? 준비 됐어요! 출발!', `FemaleText_loc4`='尤瑞克，你在里面吗？我可要动手啦！我们上！', `FemaleText_loc5`='尤瑞克，你在裡面嗎?我已經準備好了!我們走吧!', `FemaleText_loc7`='Yorick, ¿estás ahí? ¡Estoy lista! ¡Vámonos!' WHERE `ID`=44940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 어리석은 것들아. 파멸의 품으로. 오늘이 바로 종말의 날이다!', `MaleText_loc4`='来吧蠢货们。拥抱死亡吧。你们的末日到了！', `MaleText_loc5`='來呀笨蛋。來送死呀。末日來臨了!', `MaleText_loc7`='Vengan, necios. Vengan a la muerte. ¡Ha llegado el fin de sus días!' WHERE `ID`=44941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄의 차원문이 거의 다 열렸다. 우리는 톨비르를 도와 울둠을 개조하고, 아제로스의 모든 생명체를 제거할 것이다.', `MaleText_loc4`='泰坦界门即将完全开启。我们将协助托维尔重塑奥丹姆，毁灭艾泽拉斯的一切生灵！', `MaleText_loc5`='泰坦甬道之門即將開啟。我們將協助托維爾重設奧丹姆，一舉消滅艾澤拉斯上的所有生命!', `MaleText_loc7`='La puerta de los titanes casi está abierta. ¡Ayudaremos a los Tol''vir a reconfigurar Uldum y propiciaremos el fin de toda vida en Azeroth!' WHERE `ID`=44942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 군주님을 위해 우린 긴 시간 동안 쉬지 않고 일했다. 그분의 이름으로 우리의 모든 것을 바치자. 종말의 날, 우리는 그분의 화염을 마음껏 누리리라!', `MaleText_loc4`='我们已对死亡之翼大人效忠已久。让我们为他献出所有，在末日到来之时沐浴在他的烈焰之中！', `MaleText_loc5`='我們已經為主人死亡之翼辛勤工作了好一段時間。奉他之名，獻出一切，於世界終末之日沐浴在他的烈焰之下!', `MaleText_loc7`='Hemos trabajado mucho y muy duro para nuestro señor, Alamuerte. ¡Sacrifiquémoslo todo en su nombre para que podamos envolvernos en sus llamas en el final de los días!' WHERE `ID`=44943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 군주님께서 영원의 샘을 산산조각내신 덕에 울둠의 방어벽이 무너졌다. 모두 준비해라. 우리는 차원문을 향해 전진할 것이다.', `MaleText_loc4`='死亡之翼大人对永恒之井的破坏，削弱了奥丹姆的防御。做好准备。我们很快就将穿越界门！', `MaleText_loc5`='死亡之翼大人在撕裂永恆之井時也一併破壞了奧丹姆的防禦機制。做好準備，不久我們即將揮軍穿過甬道之門!', `MaleText_loc7`='La destrucción del Pozo de la Eternidad por parte de Lord Alamuerte ha desarmado las defensas de Uldum. Preparaos. ¡Pronto atravesaremos la Puerta!' WHERE `ID`=44944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n?', `FemaleText_loc4`='你好吗，$n？', `FemaleText_loc5`='你好嗎，$n?', `FemaleText_loc7`='¿Qué tal, $n?' WHERE `ID`=44945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전, 마지막 대전쟁이 발발하기 전에 우리 아버지께서는 북마루 벌목지를 운영하셨습니다. 벌목지 운영은 아버님의 천직이었기에 당신께서는 그 일에 헌신하셨지요. 그러던 중 전쟁이 일어나자 우린 스톰윈드로 도망쳐야 했습니다. 아버님의 고통은 이루 말할 수 없었지요.$B$B그렇지만 스컬지들이 사라지고 붉은십자군이 철수한 덕분에... 북마루는 다시 우리 것이 되었습니다.', `MaleText_loc4`='很久以前，在上一场大战还没开始的时候，我的父亲经营着北山伐木场。那是他的生命，他为之投入了全部的精力。然后战火袭来，我们逃去了暴风城——这个决定令他痛苦万分。$B$B但如今，天灾军团的威胁已经消除，血色十字军也已被击退……北山伐木场终于又回到了我们手中。', `MaleText_loc5`='很久以前，跟獸人的第一次大戰還沒爆發的時候，北山伐木場是我父親在經營的。伐木場是他的生命，而他也樂在其中。後來戰爭爆發了，雖然百般不願意，我們還是得逃到暴風城去避難。$B$B如今天譴軍離開了，血色十字軍也逃走了...北山伐木場總算又是我們的了。', `MaleText_loc7`='Hace mucho tiempo, antes de la última gran guerra, mi padre dirigía el Aserradero Crestanorte. Era su vida y estaba dedicado a él. Entonces llegó la guerra y, muy a su pesar, tuvimos que huir a Ventormenta.$b$bSin embargo, ahora que la Plaga ha desaparecido y la Cruzada Escarlata ha huido... Crestanorte vuelve a ser nuestro.' WHERE `ID`=44946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상상할 수도 없는 거대한 힘이 나를 차원문으로 인도하는구나! 음하하하하하하!', `MaleText_loc4`='超乎想象的力量通过我传到界门！呜哈哈哈哈哈哈！', `MaleText_loc5`='無法想像的力量流經我身上傳向甬道之門!嗚哈哈哈哈哈!', `MaleText_loc7`='¡Un poder inimaginable me recorre y va hacia la puerta! ¡Muaaaaajajajajajaja!' WHERE `ID`=44947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 설명문을 해독하라. 곧 차원문을 활성화할 것이다.', `MaleText_loc4`='正在解读最后的指令。我们很快就能激活界门！', `MaleText_loc5`='解開最後的程序。不出一個鐘頭我們就能啟動甬道之門!', `MaleText_loc7`='Descifren las instrucciones finales. ¡Activaremos la Puerta en una hora!' WHERE `ID`=44948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리들 가운데 침입자가 있다. 침입자를 제거하라! 그 무엇도 데스윙 군주님의 계획을 방해해선 안 된다!', `MaleText_loc4`='我们中间出现了入侵者。干掉他们！谁也别想破坏死亡之翼大人的计划！', `MaleText_loc5`='有入侵者出現了。消滅他們!不得讓任何東西干擾死亡之翼大人的計畫!', `MaleText_loc7`='Hay un intruso entre nosotros. ¡Destrúyanlo! ¡Nada debe interferir con el plan de Lord Alamuerte!' WHERE `ID`=44949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 데스윙 님을 섬기는 건 사실이지만, 동시에 그분보다 더 큰 힘도 섬긴다는 사실을 잊지 마라!', `MaleText_loc4`='我们的确效忠于死亡之翼，可我们同时也效忠于更强大的存在。别忘了这一点！', `MaleText_loc5`='沒錯，我們服侍死亡之翼，但我們也服侍更高的力量。不要忘記!', `MaleText_loc7`='Es cierto que servimos a Alamuerte, pero también servimos a un poder superior. ¡Nunca lo olvidéis!' WHERE `ID`=44950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 별로 없네. 크롤리가 곧 도착할 거야. 출발하게!', `FemaleText_loc4`='我们没有多少时间了。克罗雷马上就要到了。开始吧！', `FemaleText_loc5`='我們沒多少時間。克羅雷很快就會抵達。走吧!', `FemaleText_loc7`='No tenemos mucho tiempo. Crowley vendrá en cualquier momento. ¡Vamos!' WHERE `ID`=44951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손가락으로 찌르지 마십시오!', `MaleText_loc4`='快住手，伙计。', `MaleText_loc5`='別再戳了，老兄!', `MaleText_loc7`='¡Deja de incordia'', colega!' WHERE `ID`=44952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간지럽단 말입니다!', `MaleText_loc4`='嘿，痒死了，伙计！', `MaleText_loc5`='嘿，很癢耶，老兄!', `MaleText_loc7`='¡Eso me hace co''quillas, colega!' WHERE `ID`=44953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 시작하죠!', `MaleText_loc4`='好了，出发！', `MaleText_loc5`='好啦，我走了!', `MaleText_loc7`='¡Venga, allá voy!' WHERE `ID`=44954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기! 장식장 안에 숨어! 난 그 옆의 그림자 속에 숨겠네.', `FemaleText_loc4`='那边！躲进衣橱里！我会躲在你旁边的阴暗处。', `FemaleText_loc5`='那邊!躲進衣櫥!我躲在你旁邊暗暗的地方。', `FemaleText_loc7`='¡AHÍ! ¡Ocúltate en el ropero! Yo me esconderé entre las sombras a tu lado.' WHERE `ID`=44955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 다 됐습니다!', `MaleText_loc4`='准备出发，伙计！', `MaleText_loc5`='準備走了，老兄!', `MaleText_loc7`='¡E''toy li''to, colega!' WHERE `ID`=44956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이바르 님, 제 제안에 대해 생각은 좀 해 보셨습니까?', `MaleText_loc4`='你又考虑过我的提议了吗，伊瓦？', `MaleText_loc5`='伊瓦，我的提議你有沒有再考慮考慮?', `MaleText_loc7`='¿Has pensado en mi propuesta, Ivar?' WHERE `ID`=44957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서부 역병지대로 돌아가지 않으면 야생마가 당신을 걷어차 버릴 것입니다!', `MaleText_loc4`='返回西瘟疫之地，否则你的野马将把你踢下去！', `MaleText_loc5`='返回西瘟疫之地，否則野馬會把你踢下來!', `MaleText_loc7`='¡Vuelve a las Tierras de la Peste del Oeste o tu caballo mesteño te desmontará!' WHERE `ID`=44958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 와서 내가 왜 너를 믿어야 하지, 크롤리? 넌 우릴 버렸어. 우리가 죽어가도록 내버려 뒀다고.', `MaleText_loc4`='我们现在为什么要相信你，克罗雷？你抛弃了我们。任由我们自生自灭。', `MaleText_loc5`='為什麼要相信你，克羅雷?你拋棄了我們，放我們自生自滅。', `MaleText_loc7`='¿Por qué iba a confiar en ti ahora, Crowley? Nos abandonaste. Nos diste por muertos.' WHERE `ID`=44959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁에서 승리하려면 당신의 도움이 필요하기 때문이지요. 우리 종족이 힘을 합쳐야 합니다! 그렇지 않으면 포세이큰이 우릴 짓밟을 겁니다.', `MaleText_loc4`='我们若想打赢这一仗，就需要你的帮助。眼下必须团结一致！否则，被遗忘者会把我们全都消灭。', `MaleText_loc5`='我們需要你的幫助才有辦法贏得這場戰爭。要是所有的獸群不團結起來的話，我們一定會讓被遺忘者給消滅掉。', `MaleText_loc7`='Necesitamos tu ayuda para ganar esta guerra. ¡Nuestras manadas deben unirse! Si no, los Renegados nos destruirán.' WHERE `ID`=44960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종족의 우두머리는 바로 당신입니다, 이바르 님. 다른 늑대인간들 모두 당신의 명령이라면 따를 겁니다.', `MaleText_loc4`='你真了不起，伊瓦。银松森林其余所有狂野之灵都将听命于你。', `MaleText_loc5`='伊瓦，你是老大。銀松森林所有的狼群都會聽你號令。', `MaleText_loc7`='Eres el líder de la manada, Ivar. Los demás ferales de Argénteos harán lo que ordenes.' WHERE `ID`=44961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 녀석의 전쟁 따위는 나와 아무 상관이 없어, 크롤리.', `MaleText_loc4`='我对你的战争不感兴趣，克罗雷。', `MaleText_loc5`='我不在乎你的戰爭，克羅雷。', `MaleText_loc7`='No me importa tu guerra, Crowley.' WHERE `ID`=44962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만...', `MaleText_loc4`='可是……', `MaleText_loc5`='但是...', `MaleText_loc7`='Pero...' WHERE `ID`=44963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이 무슨 짓을 하는지는 나도 직접 경험했지. 사실이야, 놈들은 우릴 사냥하고... 무방비 상태의 우리 동족들을 학살하더군.', `MaleText_loc4`='可我亲眼目睹过被遗忘者的卑鄙行径。这是真的。他们追杀我们……杀死那些毫无还手之力的无辜民众。', `MaleText_loc5`='我親眼見識過被遺忘者幹的事情。的確，他們會逐一獵殺我們...殺掉毫無防備能力的人。', `MaleText_loc7`='He visto de primera mano de lo que son capaces los Renegados. Es verdad. Nos cazan... Masacran a los indefensos.' WHERE `ID`=44964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면... 도와주실 건가요?', `MaleText_loc4`='那你会帮忙？', `MaleText_loc5`='所以你願意幫忙?', `MaleText_loc7`='¿Entonces nos ayudarás?' WHERE `ID`=44965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 무리를 모아보겠네. 우리는...', `MaleText_loc4`='是，我将收拾行装……我们……', `MaleText_loc5`='嗯。我會召集我的狼群，然後我們...', `MaleText_loc7`='Sí, reuniré a mi manada... Nosotros...' WHERE `ID`=44966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 냄새를 맡습니다.', `MaleText_loc4`='%s对着空气嗅了嗅。', `MaleText_loc5`='%s聞了幾下。', `MaleText_loc7`='%s olisquea el aire.' WHERE `ID`=44967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 누군가 우릴 감시하는 것 같다, 크롤리. 너도 많이 물러졌군... 아마 그레이메인 탓이겠지.', `MaleText_loc4`='看来我们受到了监视，克罗雷。你的性格如此软弱……这应该是格雷迈恩的错。', `MaleText_loc5`='好像有人在偷聽我們講話，克羅雷。你的警覺性變差了... 應該是葛雷邁恩害的。', `MaleText_loc7`='Parece que nos observan, Crowley. Te has ablandado... Seguramente será culpa de Cringris.' WHERE `ID`=44968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 쥐새끼 같은 놈!', `MaleText_loc4`='奸诈的小崽子！', `MaleText_loc5`='混帳小東西!', `MaleText_loc7`='¡Cachorro traicionero!' WHERE `ID`=44969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첩자여, 무슨 할 말이라도 있느냐?', `MaleText_loc4`='你还有什么话说，间谍？', `MaleText_loc5`='你有什麼話要說，間諜?', `MaleText_loc7`='¿Qué dices ahora, espía?' WHERE `ID`=44970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는... 밴시 여왕님을 위해... 목숨을 바쳤다.', `FemaleText_loc4`='我或生……或死……都效忠于女妖之王。', `FemaleText_loc5`='我為女妖之王而生...為女妖之王...而死。', `FemaleText_loc7`='Vivo... y muero... para la Reina alma en pena.' WHERE `ID`=44971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 말해 주길 기다렸다...', `MaleText_loc4`='我就知道你会这么说……', `MaleText_loc5`='我猜你也是會這麼講...', `MaleText_loc7`='Esperaba que dijeras eso...' WHERE `ID`=44972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 무리를 준비시키겠다. 시간은 조금 걸리겠지만, 함께하도록 하지... 적어도 당분간은 말이야.', `MaleText_loc4`='我会整理行装。把他们全都集结起来需要花点时间，可我们愿意加入……至少目前如此。', `MaleText_loc5`='我會去召集獸群所有的成員，但是可能要花點準備時間。我們會加入你們...暫時的。', `MaleText_loc7`='Prepararé la manada. Llevará un tiempo reunirlos a todos, pero nos uniremos... Por ahora.' WHERE `ID`=44973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 없애 버리겠다!', `MaleText_loc4`='你死定了！', `MaleText_loc5`='你們將會被消滅掉!', `MaleText_loc7`='¡Te destruiré!' WHERE `ID`=44974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽, 당했소!', `MaleText_loc4`='我被击中了！', `MaleText_loc5`='我被打中了!', `MaleText_loc7`='¡ME HAN DADO!' WHERE `ID`=44975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 돌아오셨군요! 중간 파편을 갖고 오신 건가요?', `FemaleText_loc4`='$n，你回来了！那是中部碎片吗？', `FemaleText_loc5`='$n，你回來了!那就是中段的碎片嗎?', `FemaleText_loc7`='¡$n, has vuelto! ¿Eso es el fragmento central?' WHERE `ID`=44976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암호화된 계획서가 더 필요합니다.', `MaleText_loc4`='我需要更多加密计划书。', `MaleText_loc5`='我需要更多的加密計畫。', `MaleText_loc7`='Necesito más planes encriptados.', `FemaleText_loc1`='암호화된 계획서가 더 필요합니다.', `FemaleText_loc4`='我需要更多加密计划书。', `FemaleText_loc5`='我需要更多的加密計畫。', `FemaleText_loc7`='Necesito más planes encriptados.' WHERE `ID`=44977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?! 내 바람의 마법에 면역이란 말인가?', `MaleText_loc4`='什么？！你竟然对我的空气法术免疫？', `MaleText_loc5`='什麼?!你對我的風魔法免疫?', `MaleText_loc7`='¡¿Cómo?! ¿Eres inmune a mi magia de aire?' WHERE `ID`=44978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 불화살이 안 통하다니! 좋아할 것 없다, 이 벌레 같은 녀석아. 내가 네 숨통을 끊는다는 사실엔 변함없으니!', `MaleText_loc4`='我的火焰箭居然没用！不要紧，你这自鸣得意的小虫子。我一定会把你毁掉！', `MaleText_loc5`='我的火焰箭沒有效!沒關係，你這傲慢的小蟲子。我還是一樣會把你消滅掉!', `MaleText_loc7`='¡Mi Descarga de Fuego es inútil! Da igual, insecto petulante. ¡Te destruiré!' WHERE `ID`=44979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 물의 주문이 소용없다니! 어떻게 이럴 수가?', `MaleText_loc4`='你竟然免疫我的水系法术！这怎么可能？', `MaleText_loc5`='你對我的水系法術也免疫!這怎麼可能?', `MaleText_loc7`='¡Eres inmune a mi hechizo de agua! ¿Cómo es posible?' WHERE `ID`=44980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고... 고맙소.', `MaleText_loc4`='谢……谢谢你。', `MaleText_loc5`='謝...謝謝你。', `MaleText_loc7`='G... gracias.' WHERE `ID`=44981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 저를 도와주러 오신 겁니까?', `MaleText_loc4`='嘿老兄！你是来帮赞吉吉出去的吗？', `MaleText_loc5`='呦，老兄!你是來幫贊基奇忙的嗎?', `MaleText_loc7`='¡Oye, colega! ¿Has venido a echa''le una mano a Zen''Kiki?' WHERE `ID`=44982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 젠키키. 나가서 전투 훈련 좀 해보는 게 어떻겠습니까?', `MaleText_loc4`='是，赞吉吉。让我们去操练下战斗技巧。', `MaleText_loc5`='對，贊基奇。我們來做點戰鬥練習吧。', `MaleText_loc7`='Sí, Zen''Kiki. Vamos a practicar algo de combate.', `FemaleText_loc1`='그래요, 젠키키. 나가서 전투 훈련이나 해보는 게 어때요?', `FemaleText_loc4`='是，赞吉吉。让我们去操练下战斗技巧。', `FemaleText_loc5`='對，贊基奇。我們來做點戰鬥練習吧。', `FemaleText_loc7`='Sí, Zen''Kiki. Vamos a practicar algo de combate.' WHERE `ID`=44983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 재미있군요! 드루이드라는 건 참 좋은데요!', `MaleText_loc4`='这可真有趣，老兄！我喜欢做德鲁伊！', `MaleText_loc5`='真是太好玩了，老兄!我愛死當德魯伊了!', `MaleText_loc7`='¡E''to é genial, colega! ¡Me encanta ser druida!' WHERE `ID`=44984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠키키, 잠깐 치유사의 처소로 돌아가 있는 게 어떻겠습니까?', `MaleText_loc4`='赞吉吉，为什么你不先回治愈者营地去呢？', `MaleText_loc5`='贊基奇，你要不要回治癒者崗哨一下?', `MaleText_loc7`='Zen''Kiki, ¿por qué no vuelves a la Finca de los Ensalmadores un rato?', `FemaleText_loc1`='젠키키, 잠깐 치유사의 처소로 돌아가 있는 게 어때요?', `FemaleText_loc4`='赞吉吉，为什么你不先回治愈者营地去呢？', `FemaleText_loc5`='贊基奇，你要不要回治癒者崗哨一下?', `FemaleText_loc7`='Zen''Kiki, ¿por qué no vuelves a la Finca de los Ensalmadores un rato?' WHERE `ID`=44985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 숨을 헐떡거립니다.', `MaleText_loc4`='%s喘了一口气。', `MaleText_loc5`='%s倒抽一口氣。', `MaleText_loc7`='%s contiene un grito.', `FemaleText_loc1`='%s|1이;가; 숨을 헐떡거립니다.', `FemaleText_loc4`='%s喘了一口气。', `FemaleText_loc5`='%s倒抽一口氣。', `FemaleText_loc7`='%s contiene un grito.' WHERE `ID`=44986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 대체 뭐 하는 곳일까요? 으, 냄새가...', `MaleText_loc4`='这是什么地方？呃，还有那股味道……', `MaleText_loc5`='這是什麼地方?噢，這個味道...', `MaleText_loc7`='¿Qué es este sitio? Puaj, ese olor...' WHERE `ID`=44987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 제단에서 모종의 의식이 행해졌군요. 벨렌이 언젠가 얘기해준 이교도의 가입 의식과 비슷합니다. 온통 피범벅이군요. 역겨워요.', `MaleText_loc4`='这座祭坛上曾举行过某种仪式，看起来像是范伦曾经说过的那种异教徒入会仪式。血腥又令人作呕。', `MaleText_loc5`='有人在這個祭壇進行了某種儀式。看起來像是一種費倫有跟我說過的異教徒入會儀式。很血腥。很噁心。', `MaleText_loc7`='En este altar se ha practicado algún tipo de ritual. Se parece a ese ritual pagano de iniciación del que me habló Velen. Sangriento y asqueroso.' WHERE `ID`=44988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이런... 잠깐... $n 님, 뒤를 보세요!', `MaleText_loc4`='你以为是——等等——$n，小心身后！', `MaleText_loc5`='你覺得是誰—慢著—$n，小心你後面!', `MaleText_loc7`='¿Qué te parece? Espera... ¡$n, detrás de ti!' WHERE `ID`=44989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 갈까요, 대장님?', `MaleText_loc4`='要去哪里，船长？', `MaleText_loc5`='搬去哪裡，船長?', `MaleText_loc7`='¿Dónde ir, capitán?' WHERE `ID`=44990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘지 않아요. 좀 무겁지만, 나 괜찮아요.', `MaleText_loc4`='还不算太糟。也许有点儿重，可我能行。', `MaleText_loc5`='沒那麼糟。有點重，我還可以。', `MaleText_loc7`='No es tan malo. Quizá un poco pesado, pero yo estar bien.' WHERE `ID`=44991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우! 좀 살살 던지실래요, 대장님?', `MaleText_loc4`='嚄！也许有点儿软，船长？', `MaleText_loc5`='呃!船長，可能是有一點點懶散了吧?', `MaleText_loc7`='¡AU! ¿Quizá lanza un poco más suave, capitán?' WHERE `ID`=44992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무거워... 아무것도 안 보여...', `MaleText_loc4`='好重……什么也看不见。', `MaleText_loc5`='重...沒想到這麼重。', `MaleText_loc7`='Pesado... no puede ver nada.' WHERE `ID`=44993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님도 한 상자 들래요?', `MaleText_loc4`='也许船长也搬了个箱子？', `MaleText_loc5`='船長要不要也來搬一個?', `MaleText_loc7`='¿Quizá capitán carga con una caja también?' WHERE `ID`=44994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 이 상자들 너무 무거워... 떨어질지도 몰라요!', `MaleText_loc4`='呃……这些箱子太重了。要掉地上了！', `MaleText_loc5`='呼...這些箱子太重了。可能會掉下來!', `MaleText_loc7`='Agh... esas cajas muy pesadas. ¡Quizá caer!' WHERE `ID`=44995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 도와줘요!', `MaleText_loc4`='船长，我需要帮助！', `MaleText_loc5`='船長，新兵需要幫忙!', `MaleText_loc7`='¡Capitán, cachorro necesita ayuda!' WHERE `ID`=44996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무거워서 탈장될 것 같아... 대장님, 그런데 탈장이 뭐죠?', `MaleText_loc4`='我快得疝气了。船长，什么叫疝气？', `MaleText_loc5`='這會害我疝氣。船長，疝氣是什麼?', `MaleText_loc7`='Esto darme hernia. Capitán, ¿qué es hernia?' WHERE `ID`=44997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 이런 거 하고 싶지 않아! 잠깐! 아냐, 이런 거 하고 싶어요.', `MaleText_loc4`='这可不包括在我的职责范围内！等等！是的，这是在我的职责范围内。', `MaleText_loc5`='我沒有簽名同意要來幹這個!慢著!對耶，我是真的有簽名的。', `MaleText_loc7`='¡YO NO ALISTARME PARA ESTO! ¡ESPERA! Sí, yo alistarme para esto.' WHERE `ID`=44998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발요, 대장님, 상자 내려놓으면 안 돼요?', `MaleText_loc4`='拜托了，船长，我能把箱子放下吗？', `MaleText_loc5`='拜託，船長。我可以把箱子放下來嗎?', `MaleText_loc7`='Por favor, capitán, ¿poder dejar la caja?' WHERE `ID`=44999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 보여! 어디로 가지?! 어떻게 해?!', `MaleText_loc4`='看不见了！往哪边走？！要干吗？！', `MaleText_loc5`='看不見!去哪裡!?做什麼?!', `MaleText_loc7`='¡NO PODER VER! ¡¿DÓNDE IDO?! ¡¿QUÉ HACIENDO?!' WHERE `ID`=45000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 나를... 죽여줘...', `MaleText_loc4`='杀了……我……吧……', `MaleText_loc5`='請...殺了...我...', `MaleText_loc7`='Por favor... matarme...' WHERE `ID`=45001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 아파. 수박만한 똥이 나올 때처럼 아파.', `MaleText_loc4`='这可真痛苦。简直赶上肚痛腹泻了。', `MaleText_loc5`='這個好痛。跟便便從旁邊出來的時候一樣。', `MaleText_loc7`='Esto duele mucho. Como vez que caca salir de lado.' WHERE `ID`=45002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이건 너무... 너무... 나... 너무 많아!', `MaleText_loc4`='到此为止！这是我的……上……上限了……不行了！', `MaleText_loc5`='不要!這樣是最...那個最...最大了...這樣子太痛了!', `MaleText_loc7`='¡MÁS NO! ESTO ES MÁXI... MÁXIMO... YO... ¡ESTO SER DEMASIADO!' WHERE `ID`=45003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요... 하나 더 있습니다!', `MaleText_loc4`='小心——我又发现一个！', `MaleText_loc5`='小心!他們又來了!', `MaleText_loc7`='¡Cuidado! ¡Veo otro!' WHERE `ID`=45004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞서 싸우세요. 저는 이 보호막을 오래 유지할 수 없습니다!', `MaleText_loc4`='把他们击退——我快撑不住了！', `MaleText_loc5`='快點反擊!我無法維持這個護盾太久!', `MaleText_loc7`='¡Contraataca! ¡No puedo sostener este escudo mucho tiempo!' WHERE `ID`=45005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 해내셨군요. 놈들이 도망가는 것 같습니다.', `MaleText_loc4`='$n，你成功了。他们看来在逃窜了。', `MaleText_loc5`='$n，你辦到了。看來他們好像逃走了。', `MaleText_loc7`='$n, lo has logrado. Parece que salen huyendo.' WHERE `ID`=45006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 녀석들은 역시 믿을 수가 없어! 모조리 쓸어 버려!', `MaleText_loc4`='我就知道那群渣滓不值得信任！击碎他们！', `MaleText_loc5`='我就知道不能相信這些小東西!打爛他們!', `MaleText_loc7`='¡Sabía que no se podía confiar en los alfeñiques! ¡Aplástenlos!' WHERE `ID`=45007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 너무 많잖아!', `MaleText_loc4`='啊——！敌人太多了！', `MaleText_loc5`='啊啊啊!他們數量太多了!', `MaleText_loc7`='¡Agh! ¡Hay muchísimos!' WHERE `ID`=45008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭동을 벌이시겠다? 힘은 이렇게 쓰는 거야!', `MaleText_loc4`='你们这群小鬼想要暴动？我要让你们瞧瞧厉害！', `MaleText_loc5`='臭矮子想亂來?看我的厲害!', `MaleText_loc7`='¿Quieren sublevarse, perros? ¡Yo les enseñaré!' WHERE `ID`=45009;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제련장인님! 적이 당신의 일을 방해했다는 소식을 들었습니다. 파편은 지금 어디 있습니까?', `FemaleText_loc4`='铸炉之主！我被告知敌人打断了你的行动。现在，碎片在哪里？', `FemaleText_loc5`='鍛造大師!我被告知敵人干擾了你的工作。碎片在哪裡?', `FemaleText_loc7`='¡Maestro de forja! Me informaron que el enemigo ha desbaratado tus operaciones. ¿Dónde está el fragmento?' WHERE `ID`=45010;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨습니다. 바위심장부로 오셔서 다음 지시를 받으십시오.', `FemaleText_loc4`='很好。在巨石之核里和我碰头，等待我的进一步指示。', `FemaleText_loc5`='幹得好。到石岩之心跟我碰面，聽取更進一步的指示。', `FemaleText_loc7`='Bien hecho. Búscame en El Núcleo de Piedra para más instrucciones.' WHERE `ID`=45011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 높은 곳에 친구가 있다고만 해두죠, 제련장인님.', `FemaleText_loc4`='我就直说吧，铸炉之主，我们有些很有势力的朋友。', `FemaleText_loc5`='這樣說吧，我們在高層有些好朋友，鍛造大師。', `FemaleText_loc7`='Digamos que tenemos amigos influyentes, maestro de forja.' WHERE `ID`=45012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이 파편을 맡고 있습니다, 대여사제님.', `MaleText_loc4`='碎片现在在巨龙手上，夫人。', `MaleText_loc5`='那個碎片已在龍的手裡了，女士。', `MaleText_loc7`='El fragmento se encuentra en custodia del dragón.' WHERE `ID`=45013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호호호호호! 즉시 그리하겠습니다!', `MaleText_loc4`='是，夫人。马上就去！', `MaleText_loc5`='沒問題，女士。馬上辦!', `MaleText_loc7`='Claro, señora. ¡Inmediatamente!' WHERE `ID`=45014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 여쭤보고 싶은 게 있습니다만... 어떻게 파편을 손에 넣은 겁니까? 어떻게 들키지도 않고 적진에 침투할 수 있었던 거죠?', `MaleText_loc4`='呃，要是您不介意，我想问问。我们是怎么找回碎片的？又是怎么悄悄地渗透进了敌人阵营的？', `MaleText_loc5`='不介意我問的話，我想知道我們是如何取得那個碎片的?我們是怎麼在敵人不知道的情況下滲透到他們內部的?', `MaleText_loc7`='Si no te molesta que pregunte. ¿Cómo logramos recuperar el fragmento? ¿Cómo nos infiltramos en las fuerzas del enemigo sin que lo sepan?' WHERE `ID`=45015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리서 육중한 날갯짓 소리가 들립니다. 돌비늘 우두머리가 다가옵니다!', `MaleText_loc4`='远处传来巨大翅膀的扇动声。龙母来了！', `MaleText_loc5`='你聽見遠處傳來巨大的翅膀拍擊的聲音。族母飛來了!', `MaleText_loc7`='Oyes un pesado batir de alas en la distancia. ¡La matriarca se acerca!' WHERE `ID`=45016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, $n 님, 이 조그만 사건에 대해선 아버지께 말씀드리지 않기로 하죠. 누가 제 목숨을 노렸다는 사실을 알면 절 다시는 왕궁에서 내보내지 않으실 겁니다...', `MaleText_loc4`='嘿$n，别让那次小伏击的事传到我父亲耳朵里。要是他发现我竟敢冒这种险，我就再也别想踏出要塞一步……', `MaleText_loc5`='嘿，$n，請不要把這個小小的埋伏事件告訴我爸爸。要是他知道有人想要暗殺我的話，我就再也別想走出那座堡壘了...', `MaleText_loc7`='Oye, $n, no hace falta decirle nada a mi padre sobre esa emboscada de nada. Si se entera de que han intentado matarme nunca me dejará salir del castillo...' WHERE `ID`=45017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='술에 안 취한 사람이 누가 있지, 토록?', `FemaleText_loc4`='谁没喝醉，托罗克？', `FemaleText_loc5`='誰沒有喝醉，托洛卡?', `FemaleText_loc7`='¿Quién no está borracho, Torok?' WHERE `ID`=45018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 포함해서요?', `MaleText_loc4`='包括我？', `MaleText_loc5`='有算我嗎?', `MaleText_loc7`='¿Yo incluido?' WHERE `ID`=45019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래.', `FemaleText_loc4`='是的。', `FemaleText_loc5`='有。', `FemaleText_loc7`='Sí.' WHERE `ID`=45020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<딸꾹!> 저... 보자... 제가 알기론, 없습니다. 모두들 취해서 정신줄을 놨습니다, 제독님... 신참 선원들만 빼고요... <딸꾹!>', `MaleText_loc4`='<嗝儿！>嗯……让我们瞧瞧……看来没人例外啊。整船的人都醉得找不着北了，长官……除了那些新兵……<嗝儿！>', `MaleText_loc5`='<嗝!>呃...我看看...我算了一下，沒半個人。全部的船員都醉到翻了，上將...除了那些新手... <嗝!>', `MaleText_loc7`='<¡Hic!>Bueno... Vamos a ver... Que yo sepa, nadie. Toda la tripulación está como una cuba, almirante... Excepto los cachorros de mar... <¡Hic!>' WHERE `ID`=45021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림 님께 부끄러운 모습을 보여드리느니, 이곳을 불태워 버리겠다!', `FemaleText_loc4`='在我被地狱咆哮的目光盯得无地自容前，我要把这地方烧成灰烬！', `FemaleText_loc5`='在我還沒有在地獄吼的面前遭辱之前，我會放火把這個地方燒光!', `FemaleText_loc7`='¡Reduciré este lugar a cenizas antes de quedar humillada a ojos de Grito Infernal!' WHERE `ID`=45022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신참 오크 선원이 사라졌습니다, 제독님. 혹시 다른 선원을 데려가도 되겠습니까?', `MaleText_loc4`='我忘记把sea pup放哪儿了，长官。你还能再借我一个吗？', `MaleText_loc5`='跟著我的那個菜鳥不知跑到哪裡去了，上將。你還有人手可以借調給我嗎?', `MaleText_loc7`='No me acuerdo de dónde he dejado mi cachorro de mar, almirante. ¿Me puedes dejar otro?', `FemaleText_loc1`='신참 오크 선원이 사라졌어요, 제독님. 혹시 다른 선원을 데려가도 될까요?', `FemaleText_loc4`='我忘记把sea pup放哪儿了，长官。你还能再借我一个吗？', `FemaleText_loc5`='跟著我的那個菜鳥不知跑到哪裡去了，上將。你還有人手可以借調給我嗎?', `FemaleText_loc7`='No me acuerdo de dónde he dejado mi cachorro de mar, almirante. ¿Me puedes dejar otro?' WHERE `ID`=45023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우!', `MaleText_loc4`='喔！', `MaleText_loc5`='噢!', `MaleText_loc7`='¡AY!' WHERE `ID`=45024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디다 놔? 떨어진다! 도와줘!', `MaleText_loc4`='放哪儿？要掉地上了！快来帮忙！', `MaleText_loc5`='放哪裡?他們掉下去了!救命啊!', `MaleText_loc7`='¿Dónde pongo? ¡Se caen! ¡AYUDA!' WHERE `ID`=45025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여깁니다. 사무엘슨의 서류는 삼 층 어딘가에 있을 거예요. 나선 계단을 따라 쭉 올라갑시다.', `MaleText_loc4`='就是这里了。萨缪尔森的文件应该在三楼，沿着旋转楼梯一路上去就能找到。', `MaleText_loc5`='就是這裡。山繆森的檔案應該在三樓，從迴轉樓梯一路上去。', `MaleText_loc7`='Es aquí. Los archivos de Samuelson deberían estar en el tercer piso, al final de la escalera de caracol.' WHERE `ID`=45027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있군요. 왕자가 서류를 좀 살펴보겠다는데 뭐라고 할 사람은 여기 아무도 없을 겁니다.', `MaleText_loc4`='我们走。殿下想要看些文件，这个理由应该不会引起任何人的怀疑。', `MaleText_loc5`='我們走吧。王子想在這兒查幾個檔案，應該是不會有人質疑才對。', `MaleText_loc7`='Vamos. A nadie le extrañará que el Príncipe quiera ojear unos archivos.' WHERE `ID`=45028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠...', `MaleText_loc4`='嗯……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmmm...' WHERE `ID`=45029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 말도 안 됩니다. 황혼의 망치단과 관련된 서류는 전혀 없어요. 사무엘슨이 대체 뭘 꾸미는 거죠?', `MaleText_loc4`='完全不对。这儿根本没有任何与暮光之锤有关的东西。萨缪尔森在玩什么把戏？', `MaleText_loc5`='太奇怪了，這裡竟然沒有任何關於暮光之錘的東西。山繆森到底在玩什麼把戲?', `MaleText_loc7`='No entiendo nada. Aquí no se dice nada sobre el Martillo Crepuscular. ¿A qué está jugando Samuelson?' WHERE `ID`=45030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위하여!', `MaleText_loc4`='为了联盟！', `MaleText_loc5`='為了聯盟!', `MaleText_loc7`='¡Por la Alianza!' WHERE `ID`=45042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=45043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 진절머리가 나는군. 저주받은 자들의 교단은 안돌할이 필요치 않다. 이 쓸모없는 도시는 너희 마음대로 해라.', `MaleText_loc4`='够了。诅咒教派不需要安多哈尔。就把这座毫无价值的城市留给你们吧。', `MaleText_loc5`='夠了。詛咒神教並不需要安多哈爾，這座沒用的廢城就交給你們去搶吧。', `MaleText_loc7`='Ya es suficiente. El Culto de los Malditos no necesita Andorhal. Podéis disputaros esta ciudad inútil.' WHERE `ID`=45044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜티라! 자네가 여기 로데론에 있다는 소문은 들었네.', `MaleText_loc4`='库尔迪拉！我听到传闻说你在洛丹伦。', `MaleText_loc5`='寇爾提拉!我有聽說你人在羅德隆的傳言。', `MaleText_loc7`='¡Koltira! Había oído rumores de que habías venido a Lordaeron.' WHERE `ID`=45045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 들었군, 타사리안. 날 다시 한 번 죽일 기회를 자네에게 주고 싶었거든.', `MaleText_loc4`='你听得没错，萨萨里安。我想再给你一个杀死我的机会。', `MaleText_loc5`='傳言是對的，薩沙理安。我想要再給你一次殺掉我的機會。', `MaleText_loc7`='Eran ciertos, Thassarian. Quería darte otra oportunidad de matarme.' WHERE `ID`=45046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s大笑起来。', `MaleText_loc5`='%s放聲大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=45047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 바로 지금인 것 같군.', `MaleText_loc4`='看来情形可能真会如你所说。', `MaleText_loc5`='看來是會走到那地步沒錯。', `MaleText_loc7`='Puede que no quede otro remedio.' WHERE `ID`=45048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 수도 있지... 하지만 오늘은 아니라네. 스컬지가 물러났으니 나도 병력을 철수해 전열을 가다듬을 계획이라네.', `MaleText_loc4`='嗯，可能会……但不是今天。既然已扫除了天灾军团的威胁，我准备重新集结我的军队。', `MaleText_loc5`='沒錯，是有可能...但不是今天。既然天譴軍已經離開，我打算撤退部隊，進行重整。', `MaleText_loc7`='Puede, pero no será hoy. Ahora que nos hemos librado de la Plaga, tengo previsto retirar mis tropas y reagruparme.' WHERE `ID`=45049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네. 그렇다면 나도 그렇게 하지.', `MaleText_loc4`='我明白了。那么我也会这么做。', `MaleText_loc5`='瞭解。那麼我也會這麼做。', `MaleText_loc7`='Entiendo. En ese caso, yo haré lo mismo.' WHERE `ID`=45050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지만 콜티라, 자네는 우리가 이제 형제가 아니라는 사실을 받아들여야만 하네. 자네는 호드의 일원이고, 나는 얼라이언스의 일원이잖나.', `MaleText_loc4`='可你必须清楚，库尔迪拉——我们的兄弟情已尽。你现在是部落的一员，而我效忠于联盟。', `MaleText_loc5`='但是你必須知道，寇爾提拉:我們已經不是兄弟了，如今你是部落的成員，而我則屬於聯盟。', `MaleText_loc7`='Pero no lo olvides, Koltira: ya no somos hermanos. Ahora eres miembro de la Horda y yo de la Alianza.' WHERE `ID`=45051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 어차피 이 안돌할 전투에서 격돌할 것이네. 그리고 단 한 사람만이 이 전장에서 승리해 걸어나갈 수 있을 것이라네.', `MaleText_loc4`='最终，我们将为安多哈尔而战，我们之中只有一人能载誉离开这个战场。', `MaleText_loc5`='最後，我們終究會在這場安多哈爾之戰中交手，而且到時候我倆只有一人能勝利離開這處戰場。', `MaleText_loc7`='Algún día llevaremos a cabo esta lucha por Andorhal, y solo uno de nosotros podrá abandonar el campo de batalla victorioso.' WHERE `ID`=45052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 나도 잘 알고 있네. 그러니 내가 자네에게 한 수 접어주리라고는 생각하지도 말게나.', `MaleText_loc4`='是的，我知道。而且我不认为我会对你手下留情。', `MaleText_loc5`='是的，我知道。別以為到時候我會輕易饒了你。', `MaleText_loc7`='Sí, lo sé. Pero no creas que me contendré contigo.' WHERE `ID`=45053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s大笑起来。', `MaleText_loc5`='%s大笑。', `MaleText_loc7`='%s ríe.' WHERE `ID`=45054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네. 기대하고 있겠네.', `MaleText_loc4`='非常好。我翘首期待着。', `MaleText_loc5`='很好。我期待那一天的到來。', `MaleText_loc7`='Muy bien. Lo espero con ansia.' WHERE `ID`=45055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 일어난 일에 관해서 그 누구에게도 말해서는 안 됩니다, $n. 이건 당신 직속상관의 명령임을 유념하십시오.', `MaleText_loc4`='不要和任何人提起今天的协议，$n。把这看做是你直属长官所下达的命令。', `MaleText_loc5`='你不准告訴任何人我們今天的決議，$n。把這當作是你直屬長官所下達的命令。', `MaleText_loc7`='No debes contarle a NADIE el acuerdo al que hemos llegado hoy, $n. Considéralo una orden de tu superior directo.' WHERE `ID`=45056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 마티아스와 이야기를 나누는 동안 전 왕실로 돌아가 사무엘슨을 지켜보겠습니다. 몸조심하세요!', `MaleText_loc4`='我要返回王座大厅，监视萨缪尔森的一举一动。多加小心！', `MaleText_loc5`='我回王座大廳去盯著山繆森，你負責去問馬迪亞斯。注意自身安全!', `MaleText_loc7`='Volveré a la Sala del Trono y vigilaré a Samuelson mientras tú hablas con Mathias. ¡Ten cuidado!' WHERE `ID`=45059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 거대한 덤불병아리는 대체 뭐야?', `MaleText_loc4`='怎么会有那么大的灌木小鸡？', `MaleText_loc5`='那個大大大大大隻的雞是怎麼回事?', `MaleText_loc7`='Eeeey, ¿qué pasha con eshe pollo de matorral gigaaaaaaante?' WHERE `ID`=45061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저걸 보니 배가 고프잖아... 왜 저렇게 큰건데? 당신 바보야? 닭을 저렇게 크게 만들다니... 생각이 있는거야?', `MaleText_loc4`='让我感到饥肠辘辘了……为什么那么大呢？是白痴还是什么？居然把小鸡弄得那么大……是谁干的？', `MaleText_loc5`='害我好餓...它怎麼會那麼大?你是白癡還是傻子?把雞弄得那麼大...是誰弄的?', `MaleText_loc7`='Me eshtá dando hambre... ¿Por qué esh taaaaan grande? ¿Eresh idiota o algo ashí? Hacer un pollo tan grande... ¿Quién haría esho?' WHERE `ID`=45062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이군... 놈들 때문에 저렇게 커진 거야... 저 멍청하게 기다란 목 좀 보라고. 목을 콱 졸라주고 싶어!', `MaleText_loc4`='是被遗忘者干的……是他们……真是太大了……看看它那蠢笨的大脖子。我真想一把掐死它！', `MaleText_loc5`='就是...被遺忘者弄的...它好大啊...看看它又大又笨的脖子，我好想給它一把掐死!', `MaleText_loc7`='Losh Renegadosh lo hacen... ellosh, shí... Esh tan grande... Mira eshe enorme y eshtúpido cuello. ¡Me dan ganash de apretárshelo y ashfixiarlo hashta la muerte!' WHERE `ID`=45063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 닭에 손을 대면, 한밤중에 네 잠자리를 찾아가 죽여버릴 테다. 무슨 말인지 알겠어?', `MaleText_loc4`='敢碰我的小鸡，我就让你在梦里去见阎王。听懂没有？', `MaleText_loc5`='敢碰我的雞一下，我就在你睡的時候殺了你。聽清楚了嗎?', `MaleText_loc7`='Si tocas mi pollo te mataré mientras duermes. ¿Queda claro?' WHERE `ID`=45069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 그녀가 옵니다!', `MaleText_loc4`='她来了，老大！', `MaleText_loc5`='她來了，老大!', `MaleText_loc7`='¡Aquí viene, jefe!' WHERE `ID`=45075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한가하게 수다나 떨 시간이란 거의 없습니다. 우리 백성은 위기에 처했으며 신도레이들 모두 복구 작업에 담당해야 할 역할이 있습니다.', `FemaleText_loc4`='没时间闲聊了。我们的人民正处于水深火热之中，每个辛多雷成员都肩负着重任。', `FemaleText_loc5`='沒有時間閒聊了。我們的族人正遭逢危機，每一位辛多雷都必須為重建工作盡一份心力。', `FemaleText_loc7`='No hay tiempo para charlar. Nuestra gente está en crisis y todos los sin''dorei tienen un papel en nuestra restauración.' WHERE `ID`=45076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티에 오신 걸 환영합니다!', `MaleText_loc4`='欢迎参加派对，$g老兄:女士;！', `MaleText_loc5`='歡迎參加派對，$g 先生:女士;!', `MaleText_loc7`='¡Te doy la bienvenida a la fiesta, $gamigo:nena;!' WHERE `ID`=45077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구. 이 비만... 거미들을 처치해 볼까요? 말로 하니 영 느낌이 살지 않는 이름이군요...', `MaleText_loc4`='谢谢你，朋友。让我们去杀几个超大号的……蜘蛛。我觉得是个好主意。', `MaleText_loc5`='謝謝你，朋友。讓我們先去殺幾隻過大的...蜘蛛。嗯，在我腦袋裡聽起來比較好聽說。', `MaleText_loc7`='Gracias, camarada. Matemos algunas arañas superdesarrolladas... Sonaba mejor en mi cabeza.' WHERE `ID`=45078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 거미의 우두머리를 찾아서, 끝장내 버려야 합니다!', `MaleText_loc4`='我们要找出幕后主使，结果了她！', `MaleText_loc5`='我們必須找到那隻族母，把她解決掉!', `MaleText_loc7`='¡Debemos encontrar a la matriarca de esta operación y acabar con ella!' WHERE `ID`=45079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술이 필요해!', `MaleText_loc4`='给我来杯酒！', `MaleText_loc5`='我需要喝一杯!', `MaleText_loc7`='¡Necesito una copa!' WHERE `ID`=45080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신에게 대장기술을 가르쳐 드릴 수 있고, 필요한 도구도 제공할 수 있습니다.$b$b어떻게 도와드릴까요?', `MaleText_loc4`='我能指导你锻造的技巧，并向你提供必要的工具。$B$B需要我帮忙吗？', `MaleText_loc5`='我可以傳授你鍛造的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `MaleText_loc7`='Puedo instruirte en herrería y conseguirte las herramientas necesarias.$b$b¿En qué te puedo ayudar?', `FemaleText_loc1`='저는 당신에게 대장기술을 가르쳐 드릴 수 있고, 필요한 도구도 제공할 수 있습니다.$b$b어떻게 도와드릴까요?', `FemaleText_loc4`='我能指导你锻造的技巧，并向你提供必要的工具。$B$B需要我帮忙吗？', `FemaleText_loc5`='我可以教導你鍛造的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `FemaleText_loc7`='Puedo instruirte en herrería y conseguirte las herramientas necesarias.$b$b¿En qué te puedo ayudar?' WHERE `ID`=45085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신에게 약초채집 기술을 가르쳐 드리거나 낚싯대와 유용한 물품을 제공해 드릴 수 있습니다.$b$b어떻게 도와드릴까요?', `MaleText_loc4`='我能指导你钓鱼的技巧，并向你提供渔具和各种物资。$B$B需要我帮忙吗？', `MaleText_loc5`='我可以指導你如何釣魚，也可以賣你釣魚竿和補給品。$B$B你需要什麼?', `MaleText_loc7`='Puedo enseñarte a pescar y venderte cañas de pescar y suministros.$b$b¿En qué puedo ayudarte?', `FemaleText_loc1`='저는 당신에게 약초채집 기술을 가르쳐 드리거나 낚싯대와 유용한 물품을 제공해 드릴 수 있습니다.$b$b어떻게 도와드릴까요?', `FemaleText_loc4`='我能指导你钓鱼的技巧，并向你提供渔具和各种物资。$B$B需要我帮忙吗？', `FemaleText_loc5`='我可以指導你如何釣魚，也可以賣你釣魚竿和補給品。$B$B你需要什麼?', `FemaleText_loc7`='Puedo enseñarte a pescar y venderte cañas de pescar y suministros.$b$b¿En qué puedo ayudarte?' WHERE `ID`=45086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 영혼은 나의 것이다.', `FemaleText_loc4`='你的灵魂属于我。', `FemaleText_loc5`='你的靈魂是我的。', `FemaleText_loc7`='Tu alma me pertenece.' WHERE `ID`=45087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나라, 포세이큰!', `FemaleText_loc4`='起来吧，被遗忘者！', `FemaleText_loc5`='起來，被遺忘者!', `FemaleText_loc7`='¡Álzate, Renegado!' WHERE `ID`=45088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸자여, 너는 이제 밴시 여왕님을 섬긴다.', `FemaleText_loc4`='你现在效忠于女妖之王了，凡人。', `FemaleText_loc5`='你現在是女妖之王的人啦，凡人。', `FemaleText_loc7`='Ahora sirves a la Reina alma en pena, mortal.' WHERE `ID`=45089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음은 시작일 뿐이다.', `FemaleText_loc4`='死亡仅仅只是开始！', `FemaleText_loc5`='死亡只是個開始。', `FemaleText_loc7`='La muerte no es más que el principio.' WHERE `ID`=45090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 일어나 포세이큰이 되어라!', `FemaleText_loc4`='起来吧，$n！加入被遗忘者吧！', `FemaleText_loc5`='起來，$n!成為被遺忘者!', `FemaleText_loc7`='¡Levántate, $n! ¡Conviértete en $gun Renegado:una Renegada;!' WHERE `ID`=45091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간을 낭비하지 마라, $n. 밴시 여왕님을 기다리시게 해서는 안 된다.', `FemaleText_loc4`='别耽误时间了，$n。我们不该让女妖之王久等。', `FemaleText_loc5`='不要浪費時間，$n。我們不能讓女妖之王等我們。', `FemaleText_loc7`='No pierdas el tiempo, $n. No debemos hacer esperar a la Reina alma en pena.' WHERE `ID`=45092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 주인은 바뀌었지만, 힘을 향한 채울 수 없는 갈망은 마찬가지구나.', `FemaleText_loc4`='不同的主人，对力量的无尽贪欲却是一样。', `FemaleText_loc5`='不同的主人，對力量卻相同地擁有無止境的饑渴。', `FemaleText_loc7`='Distinto señor, pero la misma sed insaciable de poder.' WHERE `ID`=45093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 미래에 파멸이 보인다, $n.', `FemaleText_loc4`='我感受到了你将面临的毁灭，$n。', `FemaleText_loc5`='我感覺到你的未來是個毀滅，$n。', `FemaleText_loc7`='Veo destrucción en tu futuro, $n.' WHERE `ID`=45094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 온기가 정말 역겹군.', `FemaleText_loc4`='这里的温暖感觉令我恶心。', `FemaleText_loc5`='這個地方的溫暖讓我噁心。', `FemaleText_loc7`='El calor de este lugar me pone enferma.' WHERE `ID`=45095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노스렌드의 얼어붙은 황무지가 그립구나.', `FemaleText_loc4`='我向往诺森德的冰冻荒原。', `FemaleText_loc5`='我懷念北裂境的冰封荒野。', `FemaleText_loc7`='Echo de menos los baldíos helados de Rasganorte.' WHERE `ID`=45096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='느껴지나, $n? 어둠이 우릴 감싸고 있다.', `FemaleText_loc4`='你感觉到了吗，$n？黑暗在席卷我们。', `FemaleText_loc5`='你感覺到了嗎，$n?黑暗籠罩著我們。', `FemaleText_loc7`='¿Puedes sentirlo, $n? La oscuridad nos rodea.' WHERE `ID`=45097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삶은 아무 의미가 없어. 우리가 진짜 시험을 받게 되는 곳은 바로 사후 세계지.', `FemaleText_loc4`='生命是毫无意义的。我们在死后才会面临真正的考验。', `FemaleText_loc5`='生命是沒有意義的。死後的世界才是真正的考驗。', `FemaleText_loc7`='La vida carece de sentido. La verdadera prueba es la otra vida.' WHERE `ID`=45098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 통해 밴시 여왕님은 세상 모두를 살피신다...', `FemaleText_loc4`='通过我，女妖之王看得见一切……', `FemaleText_loc5`='透過我，女妖之王全都看見了...', `FemaleText_loc7`='A través de mí, la Reina alma en pena lo ve todo...' WHERE `ID`=45099;
