UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 죽음이니... 영원의 존재다.', `MaleText_loc4`='我是永恒……我是死亡。', `MaleText_loc5`='我是永恆的...我就是死亡。', `MaleText_loc7`='Soy eterno... Soy la muerte.', `FemaleText_loc1`='나는 죽음이니... 영원의 존재다.', `FemaleText_loc4`='我是永恒……我是死亡。', `FemaleText_loc5`='我是永恆的...我就是死亡。', `FemaleText_loc7`='Soy eterna... Soy la muerte.' WHERE `ID`=45109;
