UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 무슨 짓을 한 거야!?', `MaleText_loc4`='你对我做了什么！？', `MaleText_loc5`='你對我做了什麼!?', `MaleText_loc7`='¿Qué me has hecho?', `FemaleText_loc1`='내게 무슨 짓을 한 거지!?', `FemaleText_loc4`='你对我做了什么！？', `FemaleText_loc5`='你對我做了什麼!?', `FemaleText_loc7`='¿Qué me has hecho?' WHERE `ID`=45112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가증스러운 반역자, 암흑 주교가 숨을 거두자 그를 둘러싼 보호막이 사라집니다.', `MaleText_loc4`='随着那个可耻的叛徒咽下最后一口气，黑主教的护盾终于消散了。', `MaleText_loc5`='黑主教的護盾就此散去，可悲的叛徒呼出了他的最後一口氣。', `MaleText_loc7`='El escudo de El Obispo Negro se disipa cuando el miserable traidor exhala por última vez.' WHERE `ID`=45113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 새로운 주인을 경배하라!', `FemaleText_loc4`='向你的新主人俯首致敬吧！', `FemaleText_loc5`='向你的新主人鞠躬致敬!', `FemaleText_loc7`='¡Inclínate ante tu nueva maestra!' WHERE `ID`=45114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나 우리의 적을 파괴하라!', `FemaleText_loc4`='起来，摧毁我们的敌人！', `FemaleText_loc5`='起身消滅我們的敵人!', `FemaleText_loc7`='¡Levántate y destruye a nuestros enemigos!' WHERE `ID`=45115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다! 이제 변신술은 그만해야겠군요... 치유술이나 배워야겠습니다!', `MaleText_loc4`='感谢你帮助我，朋友！我已经不想再变形了……现在我要努力提高我的治疗术水平！', `MaleText_loc5`='謝謝你幫了我一把，老兄!我不要再玩變身的把戲了...我還是專心練習醫療的本事就好!', `MaleText_loc7`='¡Gracias por ayuda''me, colega! Ya no más cambios de fo''ma para mí... ¡Voy a pra''ticar mi sanación!' WHERE `ID`=45116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 게임이 시작됐군! 하지만 체스로 치면 넌 그저 졸병이고 나는... 암흑 주교다!', `MaleText_loc4`='这场棋局已经开始！而你只不过是一个卒子。我则是……黑主教！', `MaleText_loc5`='遊戲已經開始!不過你僅僅是個小卒，而我則是...黑主教!', `MaleText_loc7`='¡Comienza el juego! Pero tú no eres más que un mero peón, mientras que yo soy... ¡El Obispo Negro!' WHERE `ID`=45117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임 끝이군.', `MaleText_loc4`='将军。', `MaleText_loc5`='將軍。', `MaleText_loc7`='Jaque mate.' WHERE `ID`=45118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 어린 자여. 고귀한 영혼을 다시 보니 기쁘구나.$B$B혈투의 전장, 과거에 엘드레탈라스라고 불렸던 이곳은 속속들이 부패했다. 나는 어둠과 혼돈의 세력에 형제들이 쓰러지는 모습을 보았다. 그 공포를 영원히 없앨 수만 있다면 많은 이가 이곳을 잿더미로 만드는 쪽을 택하겠지.$B$B그러나 필멸의 존재여, 혈투의 전장은 살릴 가치가 있는 곳이다. 나를 도와다오. 함께라면 이곳에서 자취를 감춘 엄청난 힘을 선한 목적으로 불러일으킬 수 있을 것이다. 그 옛날과 마찬가지로 말이다.', `MaleText_loc4`='你好，年轻人，真高兴能再见到一个高贵的灵魂。$B$B埃德萨拉已经彻底堕落，成为了今日的厄运之槌。我亲眼看着我的同胞们败倒在黑暗和混乱力量的脚下。可能许多人都认为，只有把这里彻底夷为平地，才能永远结束盘踞在这里的恐怖。$B$B但厄运之槌还是值得拯救的，凡人。帮帮我，也许我们的共同努力能够重新唤醒这里巨大的善良力量，让久远以前的美好时代重新回来。', `MaleText_loc5`='你好，年輕人，很高興能又見到像你這樣具有高尚情操的人士。$B$B厄運之槌原本叫埃德薩拉斯，它是個已經徹底腐化的地方。我見到我的弟兄們墮入黑暗與混沌的力量，而且有許多人想把這個地方夷為平地，徹底終結它的恐怖。$B$B但是厄運之槌依然值得拯救，凡人。幫助我，釋放失落在此的龐大力量為善用，如同長遠之前那樣。', `MaleText_loc7`='Saludos, joven. Me alegro de volver a ver un alma noble.$b$bLa Masacre, antes Eldre''thalas, está corrupta hasta el tuétano. He visto a mis hermanos sucumbir ante las fuerzas del caos y la oscuridad. Muchos arrasarían este lugar por completo para eliminar sus horrores para siempre.$b$bPero La Masacre se merece la salvación, mortal. Ayúdame, y quizá entre los dos podamos desatar el inmenso poder que se perdió aquí para las fuerzas del bien, como sucedía hace tanto tiempo.' WHERE `ID`=45119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신에게 낚시 기술을 가르쳐 드리고 유용한 물품을 제공해 드릴 수도 있습니다.$b$b어떻게 도와드릴까요?', `MaleText_loc4`='我能指导你钓鱼的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？', `MaleText_loc5`='我可以傳授你釣魚的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `MaleText_loc7`='Puedo enseñarte a pescar y ofrecerte suministros útiles.$b$b¿En qué te puedo ayudar?', `FemaleText_loc1`='저는 당신에게 약초채집 기술을 가르쳐 드리고 유용한 물품을 제공해 드릴 수도 있습니다.$b$b어떻게 도와드릴까요?', `FemaleText_loc4`='我能指导你钓鱼的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？', `FemaleText_loc5`='我可以傳授你釣魚的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `FemaleText_loc7`='Puedo enseñarte a pescar y ofrecerte suministros útiles.$b$b¿En qué te puedo ayudar?' WHERE `ID`=45120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신에게 약초채집 기술을 가르쳐 드리고 유용한 물품을 제공해 드릴 수도 있습니다.$b$b어떻게 도와드릴까요?', `MaleText_loc4`='我能指导你草药学的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？', `MaleText_loc5`='我可以傳授你草藥學的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `MaleText_loc7`='Puedo enseñarte herboristería y ofrecerte suministros útiles.$b$B¿En qué te puedo ayudar?', `FemaleText_loc1`='저는 당신에게 약초채집 기술을 가르쳐 드리고 유용한 물품을 제공해 드릴 수도 있습니다.$b$b어떻게 도와드릴까요?', `FemaleText_loc4`='我能指导你草药学的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？', `FemaleText_loc5`='我可以傳授你草藥學的技藝，以及提供必要的工具。$B$B有什麼需要我幫忙的嗎?', `FemaleText_loc7`='Puedo enseñarte herboristería y ofrecerte suministros útiles.$b$B¿En qué te puedo ayudar?' WHERE `ID`=45121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 자손이여, 어떻게 도와드릴까?', `MaleText_loc4`='大地之子，需要我的帮助吗？', `MaleText_loc5`='大地之子，有什麼需要我幫忙的嗎?', `MaleText_loc7`='¿Cómo pue''o ayudah''te, $ghijo:hija; de la Tierra?', `FemaleText_loc1`='대지의 자손이여, 어떻게 도와드릴까?', `FemaleText_loc4`='大地之子，需要我的帮助吗？', `FemaleText_loc5`='大地之子，有什麼需要我幫忙的嗎?', `FemaleText_loc7`='¿Cómo pue''o ayudah''te, $ghijo:hija; de la Tierra?' WHERE `ID`=45122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀림은 어둡고, 땅은 기름지네.$b$b$c|1이여;여;, 대지의 정령이 그대를 지켜주길.', `MaleText_loc4`='丛林中暗影重重，但它的土地肥沃丰茂。$B$B愿大地之灵眷顾你，$c。', `MaleText_loc5`='叢林幽暗，其土肥沃。$B$B願大地之靈看護著你，$c。', `MaleText_loc7`='Oh''cura es la jungla, pero fértil la tierra.$B$BQue los eh''píritus de la tierra cuiden de ti, $c.', `FemaleText_loc1`='밀림은 어둡고, 땅은 기름지네.$b$b$c|1이여;여;, 대지의 정령이 그대를 지켜주길.', `FemaleText_loc4`='丛林中暗影重重，但它的土地肥沃丰茂。$B$B愿大地之灵眷顾你，$c。', `FemaleText_loc5`='叢林幽暗，其土肥沃。$B$B願大地之精魂看護著你，$c。', `FemaleText_loc7`='Oh''cura es la jungla, pero fértil la tierra.$B$BQue los eh''píritus de la tierra cuiden de ti, $c.' WHERE `ID`=45123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 정령에 대한 가르침을 받고 싶습니다.', `MaleText_loc4`='我希望了解更多关于大地之灵的秘密，请训练我。', `MaleText_loc5`='我想要學習更多關於大地之靈的奧秘，請你教導我。', `MaleText_loc7`='Quiero aprender más secretos de los espíritus de la tierra. Entréname, por favor.', `FemaleText_loc1`='대지의 정령에 대한 가르침을 받고 싶습니다.', `FemaleText_loc4`='我希望了解更多关于大地之灵的秘密，请训练我。', `FemaleText_loc5`='我想要學習更多關於大地之靈的奧秘，請你教導我。', `FemaleText_loc7`='Quiero aprender más secretos de los espíritus de la tierra. Entréname, por favor.' WHERE `ID`=45124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고르독은 다그톨 싫어한다. 그래서 다그톨이 고르독 처치했다. 멍청한 나무랑 염소 인간들도 다그톨 싫어한다. 그래서 다그톨은 놈들도 처치하고 싶다.$B$B조그만 $r|1은;는; 다그톨 좋아하나? 다그톨이 주인님을 위해 이곳을 손에 넣는 걸 도와줄 텐가? 아니면 다그톨이 너도 처치해야 하나?$B$B멍청한 나무가 대사 다그톨 계속 쳐다본다...', `MaleText_loc4`='戈多克们不喜欢达戈索尔，所以他杀了他们。那些愚蠢的树和山羊人也不喜欢达戈索尔，所以他也想杀光他们。$B$B小$r喜欢达戈索尔吗？是不是愿意帮助他征服这个地方？还是达戈索尔也要杀掉你？$B$B愚蠢的树一直在盯着大使达戈索尔……', `MaleText_loc5`='戈多克不喜歡達格索，所以達格索殺戈多克。笨笨樹還有羊羊人不喜歡達格索，所以達格索也想殺他們。$B$B小小$r喜歡達格索，要幫他為主人把這個地方拿下來?還是達格索也要殺你?$B$B笨笨樹一直盯著達格索大使...', `MaleText_loc7`='A los Gordok no gustar Dagg''thol, así que él matarlos. A los estúpidos árboles y a los hombres cabra no gustar Dagg''thol, así que él querer matarlos también.$B$B¿A $r alfenique gustar Dagg''thol y ayudarle a tomar este lugar para maestro? ¿O Dagg''thol tener que matarte también?$B$BEl estúpido árbol seguir mirando a emabajador Dagg''thol...' WHERE `ID`=45125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재고는 완전히 바닥난 데다 길은 오크가 막았습니다. 제 팔자가 그렇지요, 뭐.', `MaleText_loc4`='我已经彻底弹尽粮绝了，而道路又遭到了兽人的封锁，我的运气可真好啊！', `MaleText_loc5`='我的補給完全用光，道路又被獸人給封鎖了。運氣真是遭透了!', `MaleText_loc7`='Me he quedado sin suministros y los orcos han cortado el camino, ¡vaya suerte la mía!' WHERE `ID`=45126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 온다!', `MaleText_loc4`='他们来了！', `MaleText_loc5`='他們來了!', `MaleText_loc7`='¡Ya vienen!', `FemaleText_loc1`='그들이 와요!', `FemaleText_loc4`='他们来了！', `FemaleText_loc5`='他們來了!', `FemaleText_loc7`='¡Ya vienen!' WHERE `ID`=45127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르십시오, 주인님! 적들이 쳐들어왔습니다!', `MaleText_loc4`='快，陛下！敌人杀上来了！', `MaleText_loc5`='快點，大人!敵人攻過來了!', `MaleText_loc7`='¡Rápido, mi señor! ¡El enemigo nos pisa los talones!', `FemaleText_loc1`='서두르세요, 주인님! 적들이 쳐들어왔어요!', `FemaleText_loc4`='快，陛下！敌人杀上来了！', `FemaleText_loc5`='快點，大人!敵人攻過來了!', `FemaleText_loc7`='¡Rápido, mi señor! ¡El enemigo nos pisa los talones!' WHERE `ID`=45128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<퉁명스럽게 목례를 하는 상사>', `MaleText_loc4`='<少校略点了一下头。>', `MaleText_loc5`='<少校點了個頭。>', `MaleText_loc7`='<El Mayor asiente con sequedad.>' WHERE `ID`=45129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이렇게 빨리 돌아오셨습니까, $n 님? 부두일꾼에게서 뭐라도 알아내셨나요?', `MaleText_loc4`='$n，这么快就回来了？有没有从码头工人那里得到什么消息？', `MaleText_loc5`='這麼快就回來了，$n?有沒有從碼頭工人那兒問出些什麼?', `MaleText_loc7`='Qué pronto has vuelto, $n. ¿Te han contado algo los trabajadores de embarcadero?' WHERE `ID`=45130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났다, 사무엘슨. 우린 너의 정체를 안다. 그리고 네가 대성당에 설치한 폭탄도 이미 처리했지.', `MaleText_loc4`='结束了，萨缪尔森。我们知道你的身份，你要在教堂中实行的小阴谋已经破产了。', `MaleText_loc5`='結束了，山繆森。我們知道你是誰，而且你在教堂的小陰謀也被我阻止了。', `MaleText_loc7`='Se ha acabado, Samuelson. Sabemos quién eres y he desbaratado tu pequeño plan de la catedral.', `FemaleText_loc1`='다 끝났다, 사무엘슨. 우린 너의 정체를 안다. 그리고 네가 대성당에 설치한 폭탄도 이미 처리했지.', `FemaleText_loc4`='结束了，萨缪尔森。我们知道你的身份，你要在教堂中实行的小阴谋已经破产了。', `FemaleText_loc5`='結束了，山繆森。我們知道你是誰，而且你在教堂的小陰謀也被我阻止了。', `FemaleText_loc7`='Se ha acabado, Samuelson. Sabemos quién eres y he desbaratado tu pequeño plan de la catedral.' WHERE `ID`=45131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커피 남은 것 좀 없나?', `MaleText_loc4`='我们一点咖啡都没有了？', `MaleText_loc5`='我們到底還有沒有咖啡?', `MaleText_loc7`='¿No nos queda NADA de café?' WHERE `ID`=45132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 왜 항상 끝에 이런 임무를 맡을까?', `MaleText_loc4`='我怎么总是得到这样的安排？', `MaleText_loc5`='為什麼我老是接到這樣的工作?', `MaleText_loc7`='¿Cómo me las arreglo para acabar con estas misiones?' WHERE `ID`=45133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단서를 찾으라고? 단서야 있지. 오크라는. 또 다른 단서도 있어. 오크는 냄새가 난다는 사실이야.', `MaleText_loc4`='寻找线索？这里倒是有一个线索：兽人。还有另一个线索：兽人气味。', `MaleText_loc5`='在找線索?線索一就是:那是獸人。線索二是:獸人很臭。', `MaleText_loc7`='¿Buscar pistas? Aquí tienes una pista: fueron los orcos. Otra pista: los orcos apestan.' WHERE `ID`=45134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 일어나 한 잔 걸치면 좋을 시간이라는 느낌이 팍 오는군.', `MaleText_loc4`='我的肚子告诉我，现在应该是我们立即行动，开始痛饮的时候了。', `MaleText_loc5`='我的肚子告訴我，我們該開始行動，開始喝酒啦。', `MaleText_loc7`='Mi instinto me dice que es hora de pasar a la acción y ponernos a beber.' WHERE `ID`=45135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 땅이라니, 얼마나 잘 어울리는 이름인지. 이곳을 저주해. 이 요새도 저주해. 똑같이 생긴 다른 요새도 저주한다고.', `MaleText_loc4`='诅咒之地——真是个合适的名字。诅咒这个地方，诅咒这座城堡，我还要诅咒另一座一模一样的城堡。', `MaleText_loc5`='詛咒之地...多麼恰當的地名啊。詛咒這個地方，詛咒這個堡壘，詛咒另一個同樣的堡壘。', `MaleText_loc7`='Las Tierras Devastadas, qué nombre más apropiado. Maldito sea este lugar, maldita la fortaleza y maldita la otra fortaleza idéntica.' WHERE `ID`=45136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞이 안 보여요!', `MaleText_loc4`='我看不见！', `MaleText_loc5`='我看不見!', `MaleText_loc7`='¡No puedo ver!' WHERE `ID`=45137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탁자 아래쪽은 정말 더럽기 짝이 없네요!', `MaleText_loc4`='这张桌子的反面真的很脏！', `MaleText_loc5`='這張桌子的下面「真的」很髒!', `MaleText_loc7`='¡La parte de debajo de esta mesa está MUY sucia!' WHERE `ID`=45138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톤필드 부인이 저 창문 걸쇠를 고쳤는지 궁금하네요...', `MaleText_loc4`='我很好奇，斯通菲尔德妈妈到底能不能修好那扇窗子上的锁……', `MaleText_loc5`='斯通菲爾德媽媽不知道有沒有去修那扇窗子的鎖...', `MaleText_loc7`='Me pregunto si la vieja Pedregosa llegaría a arreglar el cierre de aquella ventana...' WHERE `ID`=45139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 땅이라니, 얼마나 잘 어울리는 이름인지. 이곳을 저주해. 이 요새도 저주해. 똑같이 생긴 다른 요새도 저주한다고.', `MaleText_loc4`='兽人！是兽人！不，等等，还是Krolan的肚子。', `MaleText_loc5`='獸人!是獸人!不，慢著，又只是克洛蘭的肚子而已。', `MaleText_loc7`='¡Orcos! ¡Vienen los orcos! No, espera, vuelve a ser solo el estómago de Krolan.' WHERE `ID`=45140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그렇다, $c|1이여;여;. 모두 사실이다. 부끄럽지는 않다. 내가 복종한 힘 앞에서는 필멸의 왕들이 벌레처럼 보일 정도니까.', `MaleText_loc4`='是的……是的，$c。这全都是真的。我并不为此感到羞愧。和我所侍奉的力量相比，凡间的国王只不过是一些蛆虫而已。', `MaleText_loc5`='對...是的，$c。全都是真的，而且我絲毫不以為恥。我所臣服的力量足以讓凡間所有君王都如螻蟻般卑微。', `MaleText_loc7`='Sí... Sí, $c. Es todo cierto. No me avergüenzo. Los poderes ante los que me inclino hacen que los reyes mortales parezcan insectos.' WHERE `ID`=45141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네가 싫어, 노브시.', `MaleText_loc4`='我恨你，诺比西。', `MaleText_loc5`='我恨你，諾布希。', `MaleText_loc7`='Te odio, Nobsy.' WHERE `ID`=45142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 좀 이상합니다, 사령관님. 멀록 지느러미 수프가 잘못되었나 봅니다.', `MaleText_loc4`='我的肚子里有一种奇怪的感觉，指挥官。你觉得会是那种鱼人鳍汤在作怪吗？', `MaleText_loc5`='我肚子有點不太舒服，長官。你覺得會不會是那個魚人鰭湯的關係?', `MaleText_loc7`='Tengo una sensación extraña en el estómago, Comandante. ¿Crees que podría ser la sopa de aleta de múrloc?' WHERE `ID`=45143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적어도 아이언포지에 부인을 두고 오지는 않으셨잖습니까. 제가 없을 때 마누라가 뭘 할지 상상도 못하겠습니다. 광석을 본 여자들이 어떻게 하는지 잘 아시잖습니까.', `MaleText_loc4`='至少你不必把老婆丢在铁炉堡。我真无法想象，没有我在身边，她到底会怎么样。你对女人永远无法像对矿石那样了解。', `MaleText_loc5`='至少你不必把老婆留在鐵爐堡。我無法想像，我不在身邊她到底要怎樣過日子。你知道的，女人對礦石的那個樣子。', `MaleText_loc7`='Al menos no has dejado a una mujer en Forjaz. No quiero ni imaginar qué estará haciendo sin mí. Ya sabes cómo son las mujeres cuando las dejas solas con el mineral.' WHERE `ID`=45144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에노하르가 우리한테 맥주 몇 통 선심 쓸 것 같습니까? 그러면 정신을 집중해서 전략을 짜는 데 도움이 될 텐데요.', `MaleText_loc4`='你觉得恩诺哈尔会不会给我们送几桶酒来？这样至少可以让我们的精神振作一些。', `MaleText_loc5`='你覺得恩諾哈爾會願意弄幾桶酒給我們嗎?幫我們專心思考策略。', `MaleText_loc7`='¿Crees que Enohar está dispuesto a buscarnos algunos barriles de cerveza? Ayuda a concentrarse en las estrategias, sabes...' WHERE `ID`=45145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 갑자기 숨겨두었던 단검을 꺼냅니다!', `MaleText_loc4`='%s突然抽出了一把暗藏的匕首！', `MaleText_loc5`='%s忽然抽出了一柄隱藏的匕首!', `MaleText_loc7`='¡%s saca repentinamente una daga oculta!' WHERE `ID`=45146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 아직 끝난 게 아니다. 왕에게 죽음을!', `MaleText_loc4`='我还没有完蛋呢。要死的是国王！', `MaleText_loc5`='但是我還沒徹底失敗。國王去死吧!', `MaleText_loc7`='Pero aún no estoy acabado. ¡Muerte al Rey!' WHERE `ID`=45147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어비시온이 다가오고 있습니다. 준비하십시오!', `MaleText_loc4`='艾比希昂来了。做好准备！', `MaleText_loc5`='艾碧希翁來了。做好準備!', `MaleText_loc7`='Abismion se acerca. ¡Prepárate!' WHERE `ID`=45148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 당했어요! 혼자서라도 녀석을 처치하세요!', `FemaleText_loc4`='我不行了！你只能靠自己的力量打败他了！', `FemaleText_loc5`='我不行了!你得靠自己的力量擊敗他!', `FemaleText_loc7`='¡He caído! ¡Debes derrotarlo por tu cuenta!' WHERE `ID`=45149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 조심하세요!', `MaleText_loc4`='父亲，小心！', `MaleText_loc5`='父王，小心!', `MaleText_loc7`='¡Padre, cuidado!' WHERE `ID`=45150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 아버지를 신의 권능: 보호막으로 보호합니다.', `MaleText_loc4`='%s施放真言术：盾以保护他的父亲。', `MaleText_loc5`='%s以真言術:盾保護他父親。', `MaleText_loc7`='%s protege a su padre con Palabra de poder: escudo.' WHERE `ID`=45151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 감히 어딜 방해해? 아직 변신이 안 끝났단 말이다!', `MaleText_loc4`='不！休想干扰我！我的变化还没有结束！', `MaleText_loc5`='不!我不會讓你插手干預的!我的轉變還沒有完成!', `MaleText_loc7`='¡No! ¡No dejaré que interfieras! ¡Mi transformación aún no se ha completado!' WHERE `ID`=45152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 고맙습니다!', `MaleText_loc4`='谢谢你救了我！', `MaleText_loc5`='謝謝你救了我!', `MaleText_loc7`='¡Gracias por salvarme!', `FemaleText_loc1`='구해줘서 고마워요!', `FemaleText_loc4`='谢谢你救了我！', `FemaleText_loc5`='謝謝你救了我!', `FemaleText_loc7`='¡Gracias por salvarme!' WHERE `ID`=45153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 밖으로 도망쳐야겠습니다!', `MaleText_loc4`='我要离开这儿！', `MaleText_loc5`='我得離開這裡!', `MaleText_loc7`='¡Tengo que salir de aquí!', `FemaleText_loc1`='도시 밖으로 도망쳐야겠어요!', `FemaleText_loc4`='我要离开这儿！', `FemaleText_loc5`='我得離開這裡!', `FemaleText_loc7`='¡Tengo que salir de aquí!' WHERE `ID`=45154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 고맙습니다!', `MaleText_loc4`='我自由了！谢谢你！', `MaleText_loc5`='我自由了!謝謝你!', `MaleText_loc7`='¡Soy libre! ¡Gracias!', `FemaleText_loc1`='자유다! 고마워요!', `FemaleText_loc4`='我自由了！谢谢你！', `FemaleText_loc5`='我自由了!謝謝你!', `FemaleText_loc7`='¡Soy libre! ¡Gracias!' WHERE `ID`=45155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 안에서 죽는 줄만 알았습니다.', `MaleText_loc4`='我以为我要死在那里面了。', `MaleText_loc5`='我還以為我一定會死在裡面了。', `MaleText_loc7`='Pensaba que iba a morir aquí.', `FemaleText_loc1`='저 안에서 죽는 줄 알았네요.', `FemaleText_loc4`='我以为我要死在那里面了。', `FemaleText_loc5`='我還以為我一定會死在裡面了。', `FemaleText_loc7`='Pensaba que iba a morir aquí.' WHERE `ID`=45156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 와서 정말 다행입니다.', `MaleText_loc4`='还好我遇到了你。', `MaleText_loc5`='還好有你出現。', `MaleText_loc7`='Qué suerte que hayas venido.', `FemaleText_loc1`='당신이 와서 정말 다행이에요.', `FemaleText_loc4`='还好我遇到了你。', `FemaleText_loc5`='還好有你出現。', `FemaleText_loc7`='Qué suerte que hayas venido.' WHERE `ID`=45157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘드레탈라스를 구하는 데 열중하고 있기에, 지금은 다른 일에 신경 쓸 겨를이 없습니다. 전쟁, 다툼, 충성 따위는 이 도시가 안전해지기 전까지는 아무 의미도 없습니다.', `MaleText_loc4`='现在我唯一关心的就是修复埃德萨拉。在这座城市平安无事之前，其它所有事情，战争、冲突、忠诚，对我都没有意义。', `MaleText_loc5`='我一心只在乎挽回埃德薩拉斯的榮光，無瑕顧及其他所有的俗務:戰爭、衝突，結盟，通通都不重要，直到這座城市安全為止。', `MaleText_loc7`='Redimir Eldre''thalas me importa demasiado como para ocuparme de ningún otro asunto. La guerra, el conflicto, la lealtad, nada importa hasta que la ciudad esté a salvo.' WHERE `ID`=45158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 가호가 있기를.', `MaleText_loc4`='愿光明拥抱你。', `MaleText_loc5`='願聖光籠罩你。', `MaleText_loc7`='Que la Luz te ampare.' WHERE `ID`=45159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게, $n. 치유사의 처소에 있는 선량한 이들에게 내 안부 좀 전해 주게나.', `MaleText_loc4`='再见，$n。请将我的问候转达给治愈者营地的好人们。', `MaleText_loc5`='再見了，$n。請幫我向治癒者崗哨的大家問好。', `MaleText_loc7`='Adiós, $n. Transmite mis saludos a los hombres y mujeres de la Finca de los Ensalmadores.' WHERE `ID`=45160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰이 당신네 방어선을 뚫었소, 집정관.', `MaleText_loc4`='被遗忘者已经攻破了你的防线，镇长。', `MaleText_loc5`='長官，被遺忘者已經突破你的防線了。', `MaleText_loc7`='Los Renegados han atravesado las defensas, magistrado.' WHERE `ID`=45161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시간이 없소.', `MaleText_loc4`='时间紧迫。', `MaleText_loc5`='你沒有時間了。', `MaleText_loc7`='Se te ha acabado el tiempo.' WHERE `ID`=45162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결정을 내려야 하오!', `MaleText_loc4`='你必须马上做出决定！', `MaleText_loc5`='務必做出決定!', `MaleText_loc7`='¡Hay que tomar una decisión!' WHERE `ID`=45163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 목숨을 버리고 포세이큰의 종으로 다시 태어나거나...', `MaleText_loc4`='死在战场上，成为被遗忘者的奴仆，或者……', `MaleText_loc5`='戰死沙場，然後被復活為被遺忘者的臣僕，或是...', `MaleText_loc7`='Muere en combate y álzate como sirviente de los Renegados, o...' WHERE `ID`=45164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니면 내 피를 마시고 늑대인간으로 다시 태어나시오. 그러면 포세이큰의 타락한 힘에 면역이 될 수 있소.
', `MaleText_loc4`='喝下我的血，作为狼人重生，只有这样才不会堕落成为被遗忘者。', `MaleText_loc5`='喝下我的血，重生為狼人，不必再懼怕被遺忘者的毒害。', `MaleText_loc7`='Bebe mi sangre y renace como huargen, inmune a la depravación de los Renegados.' WHERE `ID`=45165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 도와 포세이큰을 무찌르고 얼라이언스를 위해 로데론을 탈환합시다!', `MaleText_loc4`='帮助我们消灭被遗忘者，为联盟夺回洛丹伦！', `MaleText_loc5`='協助我們消滅被遺忘者，奪回羅德隆。聯盟萬歲!', `MaleText_loc7`='¡Ayúdanos a acabar con los Renegados y retomar Lordaeron para la Alianza!' WHERE `ID`=45166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간이 되느니 차라리 죽음을 택하겠소. 하지만 죽음을 통해서도 이 잔혹한 전쟁에서 벗어날 수 없으니...', `MaleText_loc4`='我们宁死也不愿变成狼人。但我们也知道，即使是死亡也无法让我们逃避这场残暴的战争……', `MaleText_loc5`='我們寧可死也不要變成狼人，但現在居然連死都無法逃脫這場戰爭的殘害...', `MaleText_loc7`='Preferiríamos morir antes que convertirnos en huargen, pero dado que ni siquiera la muerte nos libraría de las atrocidades de esta guerra...' WHERE `ID`=45167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수를 택하겠소!', `MaleText_loc4`='我们选择复仇！', `MaleText_loc5`='我們選擇復仇!', `MaleText_loc7`='¡Elegimos la venganza!' WHERE `ID`=45168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멀미는 안 했으면 좋겠군요. 균열을 통과하려면 속이 튼튼해야 하지요.', `FemaleText_loc4`='希望你的意志够强！穿越裂口的旅程可不适合弱者。', `FemaleText_loc5`='希望你的心臟夠強!穿越裂口不是意志薄弱的人能辦到的。', `FemaleText_loc7`='Espero que tengas buen estómago. Viajar a través de la brecha no es apto para débiles.' WHERE `ID`=45169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 혼돈의 소용돌이 중심입니다. 아제로스와 심원의 영지 사이에 난 균열이죠. 세상을 산산조각내려는 위협적인 모습을 보세요!', `FemaleText_loc4`='我们正处在大漩涡的中心，这道裂隙分隔了深岩之洲和艾泽拉斯。看着它把你们的世界撕成碎片吧！', `FemaleText_loc5`='我們在地深之源和我們世界之間的裂縫，也就是大漩渦的中央，眼睜睜地看著它把我們的世界撕裂!', `FemaleText_loc7`='Estamos en el corazón de la Vorágine, la falla entre Infralar y Azeroth. ¡Observa cómo amenaza con desgarrar nuestro mundo!' WHERE `ID`=45170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄 님과 다른 이들이 잘 막아주길 기대해 봅시다.', `FemaleText_loc4`='但愿我们进入裂隙之后萨尔他们能够维持住它！', `FemaleText_loc5`='希望你在裡面時，索爾和其他人能撐下去。', `FemaleText_loc7`='Ojalá Thrall y los demás puedan contenerla mientras estás dentro.' WHERE `ID`=45171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 갑니다! 긴장하세요!', `FemaleText_loc4`='要进去了！做好准备！', `FemaleText_loc5`='就是這裡，坐穩了!', `FemaleText_loc7`='¡Allá vamos! ¡Prepárate!' WHERE `ID`=45172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙의 더러운 흔적을 심원의 영지에서 깨끗하게 쓸어버리겠다. 황혼의 망치단 하수인들도 함께 말이지.', `FemaleText_loc4`='死亡之翼的污染，连同他的暮光教徒都将被彻底从深岩之洲中清除干净！', `FemaleText_loc5`='我們會將死亡之翼的餘毒還有他的暮光教徒，通通從地深之源抹除。', `FemaleText_loc7`='La mácula de Alamuerte será eliminada de Infralar, junto con los cultores Crepusculares.' WHERE `ID`=45173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 톨 바라드 방어에 성공했습니다!', `MaleText_loc4`='联盟成功地守住了托尔巴拉德！', `MaleText_loc5`='聯盟成功守住了托巴拉德!', `MaleText_loc7`='¡La Alianza ha defendido Tol Barad con éxito!' WHERE `ID`=45174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 좋아요!', `FemaleText_loc4`='你成功了！很好！', `FemaleText_loc5`='你成功了!很好!', `FemaleText_loc7`='Lo has conseguido. Bien.' WHERE `ID`=45175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 대지의 사원입니다. 심원의 영지에서 가장 중요한 건물이지요.', `FemaleText_loc4`='这是大地神殿。它是深岩之洲最重要的建筑物。', `FemaleText_loc5`='這是大地神殿。這是地深之源最重要的建築。', `FemaleText_loc7`='Este es el Templo de la Tierra. Es la estructura más importante de Infralar.' WHERE `ID`=45176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 신이시여, 황혼의 주인이시여... 저에게 힘을 주소서!', `MaleText_loc4`='暗影诸神，暮光的君主们……赐予我力量吧！', `MaleText_loc5`='暗影諸神，暮光諸王...賜予我力量!', `MaleText_loc7`='¡Dioses de la sombra, señores del crepúsculo... denme fuerza!' WHERE `ID`=45177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그가 공격해 옵니다!', `MaleText_loc4`='石头穴居人正在进攻！', `MaleText_loc5`='岩石穴居怪開始攻擊了!', `MaleText_loc7`='¡Los troggs de piedra atacan!' WHERE `ID`=45178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그가 추가로 몰려옵니다. 투석기를 보호하십시오!', `MaleText_loc4`='还有更多的石头穴居人杀过来。保卫投石车！', `MaleText_loc5`='出現更多岩石穴居怪了，守住投石機!', `MaleText_loc7`='Vienen más troggs de piedra. ¡Defiende la catapulta!' WHERE `ID`=45179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사원 안엔 티탄이 만든 바위가 있었어요. 세계 기둥이라 알려진 이름 그대로였죠. 그 기둥이 심원의 영지에 있는 모든 자기력과 원소의 힘을 떠받들었으니까요.', `FemaleText_loc4`='这儿曾经有块泰坦制造的石头，被称作世界之柱。如同其字面意思，它承载了深岩之洲世界所有的元素之力和磁吸引力。', `FemaleText_loc5`='這裡原本有顆泰坦製造的石頭，叫做世界之柱。這個名字很貼切，它背負著整個地深之源所有的元素和磁場。', `FemaleText_loc7`='Antes solía albergar una piedra creada por los Titanes, se llamaba el Pilar del Mundo. Era un nombre literal, soportaba el peso de todas las fuerzas elementales y magnéticas de Infralar.' WHERE `ID`=45180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그의 마지막 공격인 것 같습니다. 목적지가 얼마 남지 않았습니다!', `MaleText_loc4`='看起来，这是石头穴居人最后的一波攻击了。你的胜利已经近在眼前了！', `MaleText_loc5`='看來是岩石穴居怪的最後一波攻勢了。你的目的地就在繞過那個轉角的地方!', `MaleText_loc7`='Parece una última maniobra desesperada de los troggs de piedra. ¡Tu destino está a la vuelta de la esquina!' WHERE `ID`=45181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙이 천장을 뚫고 올라가면서 두 세계 간에 균열이 생겼고, 세계 기둥도 산산조각이 났습니다. 이 기둥을 원상복구하지 않으면, 심원의 영지는 아제로스와 함께 붕괴하고 말아요.', `FemaleText_loc4`='死亡之翼冲破了穹顶，在两个世界间制造了裂隙，世界之柱也裂成了碎片。如果我们不能让世界之柱复原，那么整个深岩之洲都会崩溃。', `FemaleText_loc5`='當死亡之翼穿破上面的穹蒼時，它被粉碎了，還在兩個世界中製造了一個裂縫。如果我們不修復世界之柱，整個地深之源會垮在艾澤拉斯上。', `FemaleText_loc7`='Se rompió en pedazos cuando Alamuerte atravesó la cúpula y provoco la falla entre los dos mundos, todo Azeroth caerá sobre Infralar si no restauramos el Pilar del Mundo.' WHERE `ID`=45182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망쳐...', `FemaleText_loc4`='跑……', `FemaleText_loc5`='快跑...', `FemaleText_loc7`='Corre...' WHERE `ID`=45184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서!', `FemaleText_loc4`='跑啊！', `FemaleText_loc5`='快跑!', `FemaleText_loc7`='¡CORRE!' WHERE `ID`=45185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첫 번째 기둥 파편은 호드의 폭풍 강타호에 실려 이곳으로 오던 중이었습니다. 그런데 도중에 추락했죠.', `FemaleText_loc4`='第一块碎片本应由一艘名叫风暴之怒的部落炮艇给我们送来。但它始终没抵达。', `FemaleText_loc5`='第一個碎片本來是由一個稱為風暴之怒的部落砲艇護送過來。它一直沒抵達。', `FemaleText_loc7`='El primer fragmento nos lo iba a entregar una nave de guerra de la Horda, la Furia de la tormenta. Nunca llegó aquí.' WHERE `ID`=45186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 최대한 피해를 막으려고 사원에서 애쓰는 중입니다. 안으로 가서 마루트 님과 얘기해 보세요. 이곳 책임자시죠.', `FemaleText_loc4`='我们控制了这座神殿，并在竭力抑制它受到的伤害。到神殿里和玛鲁特谈谈，下面由他负责。', `FemaleText_loc5`='我們已經控制住神殿了，正在盡全力降低傷害。請進去和瑪魯特談談，這裡是他負責指揮。', `FemaleText_loc7`='Hemos tomado el control del templo y contenemos todo el daño que podemos. Entra y habla con Maruut; él está al mando.' WHERE `ID`=45187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 톨 바라드 방어에 성공했습니다!', `MaleText_loc4`='部落成功地守住了托尔巴拉德！', `MaleText_loc5`='部落成功守住了托巴拉德!', `MaleText_loc7`='¡La Horda ha defendido Tol Barad con éxito!' WHERE `ID`=45188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 톨 바라드 점령에 성공했습니다!', `MaleText_loc4`='联盟成功地占领了托尔巴拉德！', `MaleText_loc5`='聯盟成功攻佔了托巴拉德!', `MaleText_loc7`='¡La Alianza ha tomado Tol Barad con éxito!' WHERE `ID`=45189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 톨 바라드 점령에 성공했습니다!', `MaleText_loc4`='部落成功地占领了托尔巴拉德！', `MaleText_loc5`='部落成功攻佔了托巴拉德!', `MaleText_loc7`='¡La Horda ha tomado Tol Barad con éxito!' WHERE `ID`=45190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두 그대를 믿습니다.', `FemaleText_loc4`='我们全都指望你了。', `FemaleText_loc5`='接下來就靠你了。', `FemaleText_loc7`='Todos contamos contigo.' WHERE `ID`=45191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알골라스 말 샬넬... 어둠이 덮친다...', `MaleText_loc4`='Al''golath mal shal''nel……黑暗吞噬……', `MaleText_loc5`='啊哥拉斯 馬爾 夏爾奈爾... 黑暗吞噬...', `MaleText_loc7`='Al''golath mal shal''nel... La oscuridad consume...' WHERE `ID`=45192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이쪽으로. 녀석들을 불시에 덮치도록 하지.', `FemaleText_loc4`='这边走，$n。我们要让他们大吃一惊。', `FemaleText_loc5`='走這邊，$n。我們去殺他們個措手不及。', `FemaleText_loc7`='Por aquí, $n. Los pillaremos por sorpresa.' WHERE `ID`=45193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지에서 난리가 났을 때 저도 거기 있었답니다.$B$B아버지께서 제가 왕궁을 떠나는 걸 저렇게 꺼리시는 것도 당연해요.', `MaleText_loc4`='接管铁炉堡的时候，我也在场——那时真是一片混乱。$B$B所以当我离开城堡的时候，父亲会采取这样的保护措施也就不奇怪了。', `MaleText_loc5`='接管的那段期間我人在鐵爐堡...當時簡直是一片亂。$B$B難怪在我離開城堡的時候父親會那麼擔心。', `MaleText_loc7`='Estaba en Forjaz durante la invasión. Fue un caos.$b$bNo me extraña que padre se ponga tan protector cuando salgo del castillo.' WHERE `ID`=45194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에서 벗어나야 합니다!', `MaleText_loc4`='我们要离开这里！', `MaleText_loc5`='我們一定得離開這裡!', `MaleText_loc7`='¡Tenemos que salir de aquí!' WHERE `ID`=45195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 대체 뭐였지?', `MaleText_loc4`='那是什么东西？', `MaleText_loc5`='那是什麼鬼東西?', `MaleText_loc7`='¿Pero qué era eso?' WHERE `ID`=45196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음?', `MaleText_loc4`='嗯？', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Mm?' WHERE `ID`=45197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아서 여기까지 오다니? 혈투의 전장을 당당히 누비시는 걸 보니, 참으로 대단한 영웅이신가 봅니다.', `MaleText_loc4`='你怎么能活着走到这里？你一定就是那个来对抗厄运之槌的英雄。', `MaleText_loc5`='你怎麼有辦法徒步活著來到這裡?你必定是個勇敢的英雄，竟然冒險來到厄運之槌。', `MaleText_loc7`='¿Cómo has conseguido llegar a pie con vida? Debes de ser $gun gran héroe:una gran heroína; para aventurarte por La Masacre.' WHERE `ID`=45198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 출발할까요!', `MaleText_loc4`='好了，我们出发！', `MaleText_loc5`='好吧，我們走!', `MaleText_loc7`='¡Bien, allá vamos!' WHERE `ID`=45199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게. 이제 걱정은 잠시 잊으라고!$b$b몸과 영혼에 휴식을!', `MaleText_loc4`='进来，朋友……暂时把你的担忧放到一边去吧！$B$B让自己的灵魂和躯体都好好休息一下。', `MaleText_loc5`='進來吧，老兄...暫且忘掉你的憂愁!$B$B讓身體休息休息，讓心靈休息休息。', `MaleText_loc7`='Ven, colega... ¡Olvi''a tus preocupaciones durante un rato!$B$BDeh''cansa el cuerpo, deh''cansa el alma.', `FemaleText_loc1`='어서 오게, 이제 걱정은 잠시 잊으라고!$b$b몸과 영혼에 휴식을!', `FemaleText_loc4`='进来，朋友……暂时把你的担忧放到一边去吧！$B$B让自己的灵魂和躯体都好好休息一下。', `FemaleText_loc5`='進來吧，老兄...暫且忘掉你的憂愁!$B$B讓身體休息休息，讓心靈休息休息。', `FemaleText_loc7`='Ven, colega... ¡Olvi''a tus preocupaciones durante un rato!$B$BDeh''cansa el cuerpo, deh''cansa el alma.' WHERE `ID`=45200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 처음부터 밴시 여왕은 아니었다.', `FemaleText_loc4`='我并非一直是女妖之王，$n。', `FemaleText_loc5`='我並非生來就是女妖之王，$n。', `FemaleText_loc7`='No siempre fui la Reina Alma en Pena.' WHERE `ID`=45201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 내 백성들도 포세이큰은 아니었고.', `FemaleText_loc4`='我的人民也并非一直是被遗忘者。', `FemaleText_loc5`='我的人民也並非生來就是被遺忘者。', `FemaleText_loc7`='Y mi gente no siempre fueron los Renegados.' WHERE `ID`=45202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오래전, 이 땅은 로데론의 북부 왕국으로 테레나스 메네실 국왕의 지배를 받았다.', `FemaleText_loc4`='曾经，这片土地属于北部王国洛丹伦，由泰瑞纳斯·米奈希尔国王统治。', `FemaleText_loc5`='很久以前，羅德隆的北方王國涵蓋了這片大地，由泰瑞納斯·米奈希爾國王所統治。', `FemaleText_loc7`='Hace mucho, esta tierra comprendía los reinos norteños de Lordaeron, regidos por Terenas Menethil.' WHERE `ID`=45203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테레나스에겐 아서스라는 아들이 있었지.', `FemaleText_loc4`='泰瑞纳斯有一个儿子，名叫阿尔萨斯。', `FemaleText_loc5`='泰瑞納斯有個兒子叫做阿薩斯。', `FemaleText_loc7`='Terenas tuvo un hijo, Arthas.' WHERE `ID`=45204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스... 그 이름을 입에 올리는 것만으로도 내 몸이 분노로 떨리는군.', `FemaleText_loc4`='阿尔萨斯…单是说出他的名字就会让我的身体因愤怒而颤抖。', `FemaleText_loc5`='阿薩斯...就連提到他的名字都會讓我的身體因憤怒而顫抖。', `FemaleText_loc7`='Arthas... sólo nombrarlo hace que me crispe de ira.' WHERE `ID`=45205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테레나스의 아들, 아서스는 서리한이라고 알려진 저주받은 검을 손에 넣었지.', `FemaleText_loc4`='这个幼稚的男人，阿尔萨斯，亲手拔出了一把名为霜之哀伤的邪剑。', `FemaleText_loc5`='這個年輕人，阿薩斯，給自己弄了一把受詛咒的劍，名叫做霜之哀傷。', `FemaleText_loc7`='Este joven, Arthas, se adueñó de una espada maldita llamada Agonía de Escarcha.' WHERE `ID`=45206;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서리한으로 아서스는 자신의 아버지를 살해했고, 이 땅과 그 위의 모든 생명을 처참하게 파괴했다!', `FemaleText_loc4`='手持霜之哀伤，阿尔萨斯杀死了亲生父亲，并毁掉了这片土地和所有的生物。', `FemaleText_loc5`='透過霜之哀傷，阿薩斯殺死了自己的父親並毀掉了這片土地，把所有的生者也都殺死了!', `FemaleText_loc7`='¡Mediante Agonía de Escarcha, Arthas mató a su propio padre y devastó esta tierra y a todo ser vivo en ella!' WHERE `ID`=45207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 고향 쿠엘탈라스가 아서스와 그 부하들의 손에 짓밟히던 때, 나도 아서스의 칼에 죽음을 맞아야 했다.', `FemaleText_loc4`='阿尔萨斯和他的军队肆虐了我的家园奎尔萨拉斯，杀死我的人民，并给我带来了死亡。', `FemaleText_loc5`='我自己的死亡就是阿薩斯親手所為，當時他和他的軍隊正在攻擊我的故鄉，奎爾薩拉斯，並殺害我的人民。', `FemaleText_loc7`='Mi propia muerte llegó en sus manos, cuando con su ejército saqueó mi tierra natal, Quel''Thalas, y asesinó a mi gente.' WHERE `ID`=45208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 잔인했던 아서스는 내 영혼을 육체에서 끊어냈고... 결국 나는 밴시로 되살아나 스컬지의 일원이 되었지.', `FemaleText_loc4`='阿尔萨斯的残忍没有止境，他将我的灵魂抽离了身体，把我变成女妖，以侍奉他的天灾军团。', `FemaleText_loc5`='在他無可言喻的冷酷之下，阿薩斯把我的靈魂從身體抽出，使我以女妖的形態復生，來服侍他的天譴軍團。', `FemaleText_loc7`='En toda su crueldad, Arthas separó mi espíritu y mi cuerpo y me convirtió en un alma en pena para que sirva a su Plaga.' WHERE `ID`=45209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스컬지 전쟁 기계에 희생된 사람들은 모두 비슷한 운명을 맞았다.', `FemaleText_loc4`='被天灾的战争机器杀死的每个人都遭遇了同样的厄运。', `FemaleText_loc5`='所有在天譴軍團手下死去的人都面臨了相似的命運。', `FemaleText_loc7`='Y todo el que moría por culpa de la Plaga sufría un destino similar.' WHERE `ID`=45210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심연의 불꽃으로 네 영혼을 씻어내라!', `FemaleText_loc4`='在这深渊的火焰中净化你的灵魂吧！', `FemaleText_loc5`='在深淵的烈火裡淨化你的靈魂!', `FemaleText_loc7`='¡Purificar sus almas en las llamas del abismo!' WHERE `ID`=45211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 회개하라! 막을 수 없는 파멸 앞에 모두 회개하라!', `FemaleText_loc4`='忏悔吧，凡人们！在这无法阻止的大毁灭之前忏悔吧！', `FemaleText_loc5`='懺悔吧，凡人!在無可阻擋的毀滅之前懺悔吧!', `FemaleText_loc7`='¡Arrepentíos, mortales! ¡Arrepentíos ante la aniquilación imparable!' WHERE `ID`=45212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우월하신 자 앞에 고개 숙여라. 그러면 이 하찮은 세상이 무너질 때 살아남으리라!', `FemaleText_loc4`='拜服于强者脚下，你也许还能在这个渺小世界的毁灭中逃过一死！', `FemaleText_loc5`='向你的上者臣服，或許你仍有機會活過這卑微世界的毀滅浩劫!', `FemaleText_loc7`='¡Inclínense ante sus superiores, y quizá sobrevivan a la destrucción de este mísero mundo!' WHERE `ID`=45214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿지 않는 자를 바쳐라! 살게라스의 이름으로!', `FemaleText_loc4`='以萨格拉斯的名义！没有信仰的人只能成为祭品！', `FemaleText_loc5`='奉薩格拉斯之名!獻祭這位無信者!', `FemaleText_loc7`='¡Sacrificad a los escépticos! ¡En el nombre de Sargeras!' WHERE `ID`=45215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위대한 군주 살게라스께서 너희의 배신, 욕망, 완전한 파괴까지 지켜보신다!', `FemaleText_loc4`='伟大的君主萨格拉斯将看到你的背叛，你的欲望，还有你彻底的毁灭！', `FemaleText_loc5`='薩格拉斯大君的雙眼看見了你的背叛，你的欲望，你的徹底毀滅!', `FemaleText_loc7`='¡Los ojos del gran señor Sargeras pueden ver su traición, sus deseos, su destrucción absoluta!' WHERE `ID`=45216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음의 품에서, 모두 영혼 없는 언데드로 되살아났지.', `FemaleText_loc4`='死后，我们变成了没有思想的亡灵。', `FemaleText_loc5`='在死亡後，他們重生為無腦的不死族。', `FemaleText_loc7`='Tras morir, revivían como no muertos sin voluntad.' WHERE `ID`=45217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 아서스도 무적은 아니더군! 날이 지날수록 그의 힘은 약해졌고, 저주받은 이들에 대한 지배력도 약해졌지.', `FemaleText_loc4`='但阿尔萨斯并非不可战胜！他的力量日渐衰竭，他对受诅者意志的掌控也弱化了。', `FemaleText_loc5`='但是阿薩斯並非無敵的!隨著每一天過去，他的力量都在削弱 - 他對被詛咒者的意志掌握越來越弱。', `FemaleText_loc7`='¡Pero Arthas no era invencible! Cada día que pasaba, su poder disminuía, como su control sobre los malditos.' WHERE `ID`=45218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침내 아서스가 한껏 약해졌을 때, 내가 공격했다!', `FemaleText_loc4`='在阿尔萨斯最虚弱的时候，我发起了进攻！', `FemaleText_loc5`='就在阿薩斯最虛弱的時候我進行了攻擊!', `FemaleText_loc7`='¡Cuando Arthas se encontraba más débil, ataqué!' WHERE `ID`=45219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 놈은 죗값을 치러야 할 때가 되자, 벌레같은 목숨을 부지하려고 노스렌드의 얼어붙은 황무지로 도망쳤지.', `FemaleText_loc4`='阿尔萨斯赎罪的时刻眼看就要到来，但那只蛆虫逃脱了命运的制裁，回到了诺森德的冰冻废土。', `FemaleText_loc5`='雖然他贖罪的時刻來了，但那隻蟲子成功逃離敗亡的命運，回到了北裂境的冰凍荒原。', `FemaleText_loc7`='Y aunque su hora había llegado, el gusano logró escapar a su destino y regresó a los páramos helados de Rasganorte.' WHERE `ID`=45220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스가 사라진 후, 로데론의 언데드 군단을 통제하던 힘도 사라졌다. 나는 내 시체를 되찾고 나서 이곳에 남겨진 스컬지를 해방시켰다.', `FemaleText_loc4`='随着阿尔萨斯一同消失的还有他对洛丹伦众多亡灵的思想控制。我恢复了身体，并让剩下的天灾亡灵也获得了自由。', `FemaleText_loc5`='阿薩斯離開後，他對羅德隆大量不死族身上的控制也隨之消失。在取回我的身體後，我釋放了存留下來的天譴軍團。', `FemaleText_loc7`='Al irse, Arthas perdió el control que tenía sobre las masas no-muertas de Lordaeron. Tras recuperar mi cuerpo, liberé a la Plaga restante.' WHERE `ID`=45221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리치 왕으로 잘 알려진 잔악한 아서스의 손아귀에서, 그렇게 우리 포세이큰의 저주가 시작됐다.', `FemaleText_loc4`='阿尔萨斯后来成为了巫妖王，凭着对他的共同仇恨，被遗忘者诞生了。', `FemaleText_loc5`='阿薩斯 -- 後來成為巫妖王的人 -- 從他的冷酷和絕情中，被遺忘者誕生了。', `FemaleText_loc7`='De la crueldad e impiedad de Arthas, el hombre que luego sería el Rey Exánime, nacieron los Renegados.' WHERE `ID`=45222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 존재의 이유... 우리는 리치 왕을 처단하기 위해 살아왔지. 그래서 호드와 힘을 합쳤고, 복수를 위한 여행을 떠났었다.', `FemaleText_loc4`='我们的目的—我们唯一的目的便是毁灭巫妖王。我们加入了部落，并踏上了通往救赎的远征。', `FemaleText_loc5`='我們的目標...我們唯一的目的就是要消滅巫妖王。我們投入了部落的懷抱並開始了我們的救贖之路。', `FemaleText_loc7`='Nuestra meta... nuestro único fin era destruir al Rey Exánime. Nos unimos a la Horda y comenzamos nuestro camino a la redención.' WHERE `ID`=45223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제... 리치 왕은 죽었고, 우리는 돌아왔군.', `FemaleText_loc4`='现在，巫妖王被消灭了，我们回到了这片土地。', `FemaleText_loc5`='現在，巫妖王已死，而我們也回來了。', `FemaleText_loc7`='Ahora, el Rey Exánime está muerto y hemos vuelto.' WHERE `ID`=45224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아서 로데론을 고향이라 불렀던 사람들에게, 죽음 뒤에도 고향은 이곳뿐이지.', `FemaleText_loc4`='这些人民将这片土地称为家园，生亦如此，死亦如此。', `FemaleText_loc5`='在生時曾把這片土地稱為家園的人們，在死後仍是如此。', `FemaleText_loc7`='Los que llamaron hogar a estas tierras en vida también lo hacen en la muerte.' WHERE `ID`=45225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 얼라이언스는 우리를 인정하지 않아. 그들은 이 왕국을 세운 사람들의 정당한 요구를 무시하며, 이 땅이 자기들 것이라고 주장한다.', `FemaleText_loc4`='但联盟不承认我们的主权。他们声称这片土地属于他们，妄图将它从王国的创立者们手中夺走。', `FemaleText_loc5`='但是聯盟並不認同我們的權利。他們宣稱這片土地屬於他們，並嘗試要使這個王國創始人所做的宣稱無效。', `FemaleText_loc7`='Pero la Alianza no reconoce nuestros derechos. Dicen que esta tierra es suya e invalidan los reclamos de los fundadores de este reino.' WHERE `ID`=45226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 내버려 두지 않겠어... 절대로!', `FemaleText_loc4`='我绝不允许…绝不！', `FemaleText_loc5`='我不容許這樣的事...絕不!', `FemaleText_loc7`='Nunca permitiré eso... ¡Nunca!' WHERE `ID`=45227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로데론은 포세이큰의 것이야... 언제나, 또 영원히!
', `FemaleText_loc4`='洛丹伦永远属于被遗忘者，永远。', `FemaleText_loc5`='羅德隆是屬於被遺忘者的。會永遠這樣下去。', `FemaleText_loc7`='Lordaeron le pertenece a los Renegados.... eternamente.' WHERE `ID`=45228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 귀하고 강력한 물품을 판매합니다.', `FemaleText_loc4`='我提供的材料都是罕见而且强大的。', `FemaleText_loc5`='我提供的材料既罕見又強大。', `FemaleText_loc7`='Los materiales que te ofrezco son raros y poderosos.' WHERE `ID`=45229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 너의 능력을 증명했다. 아주 뛰어난 능력이지. 우리를 대신해 소용돌이벌레를 처리해다오. 무너지는 심연으로 들어가라. 우리는 심연으로 들어갈 수 없지만 너라면 가능할 것이다.', `MaleText_loc4`='你已经证明了自己的实力和才智。我相信你将成为打败旋岩虫的英雄。那是我们无法完成的任务。你要深入碎岩之渊，那里是我们唯一无法通过的地方。', `MaleText_loc5`='你已證明了你的本事，而且足智多謀。我想你應該有能力消滅我們一直無法打贏的渦旋蟲。你應該有本事深入我們唯一無法進入的破碎深淵。', `MaleText_loc7`='Has demostrado ser capaz y tener recursos. Creo que tú llevarás a los gusaespirales a la batalla allá donde nosotros no podemos. Tú te adentrarás en las Profundidades Desmoronadas, el único lugar al que no podemos ir.' WHERE `ID`=45230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥불로 녹여주마!', `MaleText_loc4`='地狱之火！', `MaleText_loc5`='煉獄!', `MaleText_loc7`='¡FUEGO!' WHERE `ID`=45231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 군단이 모두 정복하리라!', `MaleText_loc4`='军团战无不胜！', `MaleText_loc5`='燃燒軍團將征服一切!', `MaleText_loc7`='¡La legión lo conquistará todo!' WHERE `ID`=45232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라, 파괴의 부하들아. 이 세계를 뒤틀린 황천의 불꽃으로 씻어내라!', `MaleText_loc4`='前进，毁灭的奴仆们，让这个世界彻底陷入下界位面扭曲的烈火之中！', `MaleText_loc5`='去吧，毀滅的兵卒們，讓這個世界沐浴在扭曲虛空的烈火裡!', `MaleText_loc7`='¡Salid, esbirros de la destrucción, y bañad este mundo en las llamas del Vacío Abisal!' WHERE `ID`=45233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 너희에게 닥칠 죽음 때문에 하늘까지 어두워지는구나!', `MaleText_loc4`='天空被黑暗笼罩，你们的灭亡已经临近！', `MaleText_loc5`='天日無光，毀滅降臨!', `MaleText_loc7`='¡El cielo se oscurece con su inminente muerte!' WHERE `ID`=45234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 때가 왔다! 전진하라, 이 저주받은 땅의 겁먹은 백성에게 종말을 안겨줘라!', `MaleText_loc4`='时间到了！进军，将毁灭带给这片被诅咒的土地，带给那些怯懦的生灵！', `MaleText_loc5`='時候到了!前進!讓毀滅降臨在這座詛咒之島的驚慌居民身上!', `MaleText_loc7`='¡Ha llegado la hora! ¡Caminad, y llevad la destrucción a los habitantes aterrorizados de esta tierra devastada!' WHERE `ID`=45235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애! 가서 골드마인에게 죽을 각오하라고 전해라! 우리 계약은 끝났다고!', `MaleText_loc4`='不！你告诉金矿那个蠢地精，他死定了！我们的合同完了！', `MaleText_loc5`='不!你去告訴金礦他死定了!我們的合約結束了!', `MaleText_loc7`='¡NOOOO! ¡Dile a Minaoro que es goblin muerto! ¡Nuestro contrato ha terminado!' WHERE `ID`=45236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌비늘 우두머리가 덫에 걸렸습니다! 끊임없이 움직이면서 그녀의 공격을 피하십시오!', `MaleText_loc4`='石鳞主母被困住了！注意不断变换位置，躲避她的攻击！', `MaleText_loc5`='石鱗族母被困住了!保持移動，避開她的攻擊!', `MaleText_loc7`='¡La matriarca Escama Pétrea está atrapada! ¡No dejes de moverte para evitar sus ataques!' WHERE `ID`=45237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지? 아, 나 여기 싫은데. 잠깐... 넌 수습생 골드마인이 아니잖아!', `MaleText_loc4`='深岩之洲？我痛恨这个地方。等等……你不是见习萨满金矿！', `MaleText_loc5`='地深之源?我痛恨這個地方。慢著...你不是學徒金礦!', `MaleText_loc7`='¿Infralar? Odio este lugar. Espera... ¡No eres el iniciado Minaoro!' WHERE `ID`=45238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 뭘 원하는지 알겠어. 느낌이 온다고!', `MaleText_loc4`='我知道你在找什么。我能感觉到它！', `MaleText_loc5`='我知道你的目的是什麼，我可以感覺得到!', `MaleText_loc7`='Sé lo que buscas. ¡Puedo sentirlo!' WHERE `ID`=45239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 계약 위반이라고! 죽어라, $r 녀석아!', `MaleText_loc4`='这不是我的合同！死吧，$r！', `MaleText_loc5`='這不在我的合同裡!死吧，$r!', `MaleText_loc7`='¡Esto no estaba en mi contrato! ¡Muere, $r!' WHERE `ID`=45240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 골드마인? 제가 불의 토템을 잘못 설치한 것 같습니다.', `MaleText_loc4`='哦，金矿，我似乎是找不到你的火焰图腾了。', `MaleText_loc5`='呃，金礦，我好像弄丟了你的火焰圖騰。', `MaleText_loc7`='Eh, Minaoro, creo que he perdido tu tótem de fuego.', `FemaleText_loc1`='저기... 골드마인? 제가 불의 토템을 잘못 설치한 것 같습니다.', `FemaleText_loc4`='哦，金矿，我似乎是找不到你的火焰图腾了。', `FemaleText_loc5`='呃，金礦，我好像弄丟了你的火焰圖騰。', `FemaleText_loc7`='Eh, Minaoro, creo que he perdido tu tótem de fuego.' WHERE `ID`=45241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 토템이 넘쳐난다는 생각은 말라고!', `MaleText_loc4`='我可不是火焰图腾做的，这你知道！', `MaleText_loc5`='你知道的，我又不是火焰圖騰做的!', `MaleText_loc7`='Los tótems de fuego no crecen en los árboles, ¿sabes?' WHERE `ID`=45242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웰던은 벼락 맞을 겁쟁이에 지나지 않소. 그 녀석은 스컬지에게서 도망치더니 영웅인 양 감히 이곳으로 왔단 말이지?$B$B흥!', `MaleText_loc4`='维尔顿只不过是个该死的懦夫。他刚刚逃得一条活命，现在却装成一副英雄的样子跑到这里来了？$B$B呸！', `MaleText_loc5`='威爾頓不過只是個該死的懦夫。他明明在天譴軍團攻擊的時候逃走了，現在竟然還有臉裝英雄跑回來?$B$B我呸!', `MaleText_loc7`='Weldon no es más que un maldito cobarde. Huyó de la Plaga, ¿y ahora se atreve a venir como si fuera un héroe?$b$b¡Bah!' WHERE `ID`=45243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉시가 하는 말일랑은 듣지 마십시오. 그자는 역병이 닥쳐왔을 때 머무른 멍청이였습니다. 지금의 그를 보십시오. 그자는 이곳의 다른 누더기 녀석들보다 나을 게 없단 말입니다.$B$B속 태우지 마십시오. 우린 바로브 가문의 생존한 마지막 후손들을 위해 스칼로맨스와 그 주위 지역을 다시 차지할 겁니다. 정당한 후계자들을 위해 말입니다.', `MaleText_loc4`='不要听阿莱克斯瞎说。瘟疫袭来的时候他却不知道逃走，那只能说明他的愚蠢。看看他现在的样子——和这里的其他憎恶没有两样。$B$B别担心，我们会夺回通灵学院和它周围的土地。把它们交给巴罗夫最后一个活着的儿子。他才是这里的合法继承人。', `MaleText_loc5`='不要相信阿萊克斯講的每一句話，他是自己太蠢才會在瘟疫來襲的時候留下來。現在你看看他，根本沒有比這地方其他的怪物好到哪裡去。$B$B但是不用擔心，我們會奪回通靈學院還有周遭的土地，交還給巴羅夫家唯一的生還者，也是最正當的繼承人。', `MaleText_loc7`='No escuches nada de lo que diga Alexi. Fue un idiota al quedarse durante la peste, y ahora míralo: no es mejor que las demás abominaciones del lugar.$b$bNo te preocupes, recuperaremos Scholomance y las tierras circundantes para el último hijo viviente de Barov: su heredero legítimo.' WHERE `ID`=45244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='콜티라! 그대의 여왕이 왔다!', `FemaleText_loc4`='库尔迪拉！你的女王在召唤你！', `FemaleText_loc5`='寇爾提拉!女王要召見你!', `FemaleText_loc7`='¡Koltira! ¡Tu Reina te convoca!' WHERE `ID`=45245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님. 당신께... 안돌할을 바치겠습니다.', `MaleText_loc4`='陛下。我将……安多哈尔献给您。', `MaleText_loc5`='殿下，我為您奉上... 安多哈爾。', `MaleText_loc7`='Alteza. Te entrego... Andorhal.' WHERE `ID`=45246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불경한 짓은 그만해라. 내가 언더시티 밖에서 일어나는 모든 일에 대해 아무것도 모른다고 생각하는 것이냐?', `FemaleText_loc4`='你这个傲慢的家伙。你以为我是个瞎子？看不见幽暗城外面发生的一切？', `FemaleText_loc5`='休得無禮。莫非真你以為我對幽暗城外的一切事物俱無所知嗎?', `FemaleText_loc7`='Basta con tu insolencia. ¿Crees que no veo nada de lo que pasa fuera de Entrañas?' WHERE `ID`=45247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 여왕님, 그래도 우리는 전쟁에서 이겼습니다!', `MaleText_loc4`='我……陛下，我们胜利了！', `MaleText_loc5`='我...陛下，可是我們獲勝了!', `MaleText_loc7`='Pero... ¡Majestad, salimos victoriosos!' WHERE `ID`=45248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대 덕분은 아니다. 안돌할은 며칠 전 스컬지에게 승리했던 그때에 우리 것이 돼야 했었으니까 말이다.', `FemaleText_loc4`='别想得到我的感谢。当我们击败天灾军团的时候，安多哈尔就已经应该属于我们了。', `FemaleText_loc5`='哼，是啊，還真得感謝你。但是早在好幾天前我們擊敗天譴軍的時候，安多哈爾就該是我們的了!', `FemaleText_loc7`='No gracias a ti. Deberíamos haber tomado Andorhal hace días, cuando derrotamos a la Plaga.' WHERE `ID`=45249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='콜티라, 그대의 비밀은 알고 있다. 얼라이언스의 죽음의 기사 타사리안과 친분이 있다는 것을 말이지.', `FemaleText_loc4`='我知道你的秘密，库尔迪拉。我知道你和联盟死亡骑士萨萨里安之间的友谊。', `FemaleText_loc5`='我對你的秘密瞭若指掌，寇爾提拉。我很清楚你和那個聯盟死亡騎士薩沙理安之間的私交情誼。', `FemaleText_loc7`='Conozco tu secreto, Koltira. Estoy al corriente de tu amistad con el caballero de la Muerte de la Alianza, Thassarian.' WHERE `ID`=45250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여... 여왕님...', `MaleText_loc4`='陛……陛下……', `MaleText_loc5`='陛...陛下...', `MaleText_loc7`='M-majestad...' WHERE `ID`=45251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아서스는 죽음의 기사를 탄생시킬 때 잘못한 게 분명하군. 그대는 아직도 나약하다.', `FemaleText_loc4`='阿尔萨斯在创造死亡骑士的时候就已经必败无疑了。你还很软弱。', `FemaleText_loc5`='阿薩斯在創造他的死亡騎士團的時候顯然是大大地失敗了。因為你還是那麼地弱。', `FemaleText_loc7`='Es evidente que Arthas fracasó al crear a sus caballeros de la Muerte. Aún eres débil.' WHERE `ID`=45252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다행스럽게도 그대를 도와줄 이를 알고 있다... 그대가 가는 언더시티 아래에서 이 나약함을 없애버리도록.', `FemaleText_loc4`='幸运的是，我的部下可以帮助你……消除你的软弱。到到幽暗城下面去吧。', `FemaleText_loc5`='還好，我有些幫手可以協助你...消去這個弱點。你就到幽暗城底下去吧。', `FemaleText_loc7`='Por suerte, tengo agentes que pueden... "eliminar" tu debilidad. Lleváoslo al subsuelo de Entrañas.' WHERE `ID`=45253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님, 안 됩니다!', `MaleText_loc4`='不！', `MaleText_loc5`='不!', `MaleText_loc7`='¡No!' WHERE `ID`=45254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉬잇... 조용히 해라. 죽음의 기사여. 그대와의 일이 끝나고 나면, 두려움은 사라질 것이다.', `FemaleText_loc4`='嘘……安静，死亡骑士。当我了结你的时候，你的恐惧也将不复存在。', `FemaleText_loc5`='噓...安靜點，死亡騎士。等我處理好你的問題之後，你的恐懼就會消失了。', `FemaleText_loc7`='Shh... Silencio, caballero de la Muerte. Cuando haya terminado contigo, ya no sentirás miedo.' WHERE `ID`=45255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사 인사는 나중에 해도 된다.', `FemaleText_loc4`='到那时，你就会感谢我了。', `FemaleText_loc5`='到時候再來謝我。', `FemaleText_loc7`='Luego me darás las gracias.' WHERE `ID`=45256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 폭탄을 다시 훔쳐 가려는 건 아니겠지?', `MaleText_loc4`='你不会是又想偷我的炸药吧，是吗？', `MaleText_loc5`='你不會是又想來偷我的炸藥了吧?', `MaleText_loc7`='No estarás pensando en volver a robarme los explosivos, ¿no?' WHERE `ID`=45257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 한번 둘러보시오!$b$b이게 바로 고고학자의 꿈이라오...', `MaleText_loc4`='看看这地方！$b$b这是考古学家的梦想……', `MaleText_loc5`='看看這個地方!$b$b簡直就是考古學家朝思暮想之處...', `MaleText_loc7`='¡Mira este sitio!$b$bEs el sueño de todo arqueólogo...' WHERE `ID`=45258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 내 폭탄을 들고 달아나는 일이 없도록 해 주지 않겠소?', `MaleText_loc4`='这次可不要偷走我的炸药了，好吗？', `MaleText_loc5`='這回可不可以不要再拿了我的炸藥就跑，好不好?', `MaleText_loc7`='¿Te parece si esta vez no te largas con mis explosivos?' WHERE `ID`=45259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 잠깐 쉬면서 이야기나 나누고 싶소만, 여기 폭탄들이 알아서 움직여 주지는 않아서 말이오...', `MaleText_loc4`='我很想停下来聊一会儿，但这些炸药可不会自己走路……', `MaleText_loc5`='我也很希望可以停下來好好聊個天，可是這些炸藥又沒有長腳，不會自己移動...', `MaleText_loc7`='Me encantaría quedarme y charlar un rato, pero estos explosivos no se van a trasladar solos...' WHERE `ID`=45260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g멋진:사랑스러운; 영웅께서 돌아오셨군!$B$B혹시 오다가다 용암이빨 못 봤나?$B$B<걱정스러운 표정을 짓는 수습생>', `MaleText_loc4`='赢取胜利的英雄回来了！$B$B你还没有见到熔岩之牙？$B$B<这名见习萨满露出担忧的神情。>', `MaleText_loc5`='勝利的英雄歸來了!$B$B你有沒有看到熔齒啊?$B$B<新兵看起來有些擔心。>', `MaleText_loc7`='¡$gEl héroe:La heroína; triunfante ha vuelto!$b$bNo habrás visto a Dientemagma por ahí, ¿no?$b$b<El iniciado parece preocupado.>' WHERE `ID`=45261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 저를 계속 뚫어지게 봐도 제가 예뻐지지는 않아요.', `FemaleText_loc4`='好好看看，我有没有变漂亮些？', `FemaleText_loc5`='再看啊沒關係，反正我又不會就這樣變美。', `FemaleText_loc7`='Tú sigue mirando, pero más guapa no me voy a volver.' WHERE `ID`=45262;
