UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열은 사라지고 썬더 블러프는 안전하네! 이 차원문들이 놈들의 두 번째 공격 계획이 분명하네.$b$b서두르게! 차원문으로! 주도권을 잡았을 때 계속 공격해야 하네!', `MaleText_loc4`='裂隙已经被关闭，雷霆崖安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！', `MaleText_loc5`='元素裂隙已經關閉，雷霆崖安全了!這些個傳送門必定是他們後半段的攻擊行動。$B$B動作快!進入傳送門!我們必須趁勝追擊!', `MaleText_loc7`='¡Las fallas han caído y Cima del Trueno está a salvo! Los portales deben de ser la segunda mitad de su ataque.$B$B¡Rápido! ¡Al portal! ¡Debemos atacar ahora que llevamos ventaja!' WHERE `ID`=45267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='DEBUG Event Sent - North - Horde Neutral', `MaleText_loc4`='DEBUG Event Sent - North - Horde Neutral', `MaleText_loc5`='DEBUG事件送出 - 北 - 部落中立', `MaleText_loc7`='DEBUG Event Sent - North - Horde Neutral' WHERE `ID`=45268;
