UPDATE `locales_broadcast_text` SET `MaleText_loc1`='DEBUG Event Sent - North - Horde Win', `MaleText_loc4`='DEBUG Event Sent - North - Horde Win', `MaleText_loc5`='DEBUG事件送出 - 北 - 部落獲勝', `MaleText_loc7`='DEBUG Event Sent - North - Horde Win' WHERE `ID`=45271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 모단 호수에 진흙덩이만 남을 때까지 물을 빼 가든 말든, 우리는 이곳을 지키기 위해 계속 싸울 것이네.', `MaleText_loc4`='他们会吸干洛克湖，直到那里只剩下一点泥巴，但我们还是要英勇奋战以保卫它。', `MaleText_loc5`='就算他們把湖水都抽光，害它變成了泥濘的沼澤，我們也還是要奮戰到底守住它。', `MaleText_loc7`='Pueden drenar el lago hasta que no sea más que una gota de barro, que nosotros seguiremos luchando por él.' WHERE `ID`=45272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 잠시 시간 좀 내주실 수 있나요?', `FemaleText_loc4`='$n，能占用一下你的时间吗？', `FemaleText_loc5`='$n，能撥空和我談談嗎?', `FemaleText_loc7`='$n, ¿puedes dedicarme un momento de tu tiempo?' WHERE `ID`=45273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 알고 있는 비밀을 자네에게 알려주면 자네의 영혼이 폭파할지도 모른다네, $c 친구.$b$b내 말 믿게. 다른 이를 찾아보는 게 좋을 거야.', `MaleText_loc4`='我能告诉你的秘密会让你的灵魂四分五裂，$c。$B$B相信我：你应该去别人那里接受训练。', `MaleText_loc5`='我要跟你分享的秘密會把你嚇得魂飛魄散，$c。$B$B相信我:你會想去找別人談訓練的事情的。', `MaleText_loc7`='Los secretos que poseo te harían jirones el alma, $c.$b$bCréeme: mejor habla con otra persona sobre tu instrucción.', `FemaleText_loc1`='내가 알고 있는 비밀을 자네에게 알려주면 자네의 영혼이 폭파할지도 모른다네, $c 친구.$b$b내 말 믿게. 다른 이를 찾아보는 게 좋을 거야.', `FemaleText_loc4`='我能告诉你的秘密会让你的灵魂四分五裂，$c。$B$B相信我：你应该去别人那里接受训练。', `FemaleText_loc5`='我要跟你分享的秘密會把你嚇得魂飛魄散，$c。$B$B相信我:你會想去找別人談訓練的事情的。', `FemaleText_loc7`='Los secretos que poseo te harían jirones el alma, $c.$b$bCréeme: mejor habla con otra persona sobre tu instrucción.' WHERE `ID`=45274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 저 바깥의 어둠 속에 얼마나 사악하고 끔찍한 존재들이 떠돌아다니는지 알고 있다네. 자네의 영혼을 미치게 할 그런 존재들 말이야.$b$b우린 알고 있고, 자네는 우리가 알고 있는 사실을 배우러 온 거겠지?', `MaleText_loc4`='有多少人知道，外界的黑暗中到底隐藏着怎样的恐怖……那是能够让灵魂发疯的诡谲之物！$B$B我们一直都很清楚这一点。而你也想来此一探究竟，对么？', `MaleText_loc5`='誰知道黑暗的外界裡會有什麼深沉又可怕的東西...會把人嚇到失魂落魄的東西?$B$B可是「我們」知道。而且，你來就是想知道「更多」的，對不對?', `MaleText_loc7`='¿Quién sabe qué cosas oh''curas y horribles se retueh''cen en la oh''curidad eh''terior? ¿Cosas que con solo veh''las volverían loco a un hombre?$b$bNosotros lo sabemos. Y has venido p''a saber más, ¿verdad?', `FemaleText_loc1`='우린 저 바깥의 어둠 속에 얼마나 사악하고 끔찍한 존재들이 떠돌아다니는지 알고 있다네. 자네의 영혼을 미치게 할 그런 존재들 말이야.$b$b우린 알고 있고, 자네는 우리가 알고 있는 사실을 배우러 온 거겠지?', `FemaleText_loc4`='有多少人知道，外界的黑暗中到底隐藏着怎样的恐怖……那是能够让灵魂发疯的诡谲之物！$B$B我们一直都很清楚这一点。而你也想来此一探究竟，对么？', `FemaleText_loc5`='誰知道黑暗的外界裡會有什麼深沉又可怕的東西...會把人嚇到失魂落魄的東西?$B$B可是「我們」知道。而且，你來就是想知道「更多」的，對不對?', `FemaleText_loc7`='¿Quién sabe qué cosas oh''curas y horribles se retueh''cen en la oh''curidad eh''terior? ¿Cosas que con solo veh''las volverían loco a un hombre?$b$bNosotros lo sabemos. Y has venido p''a saber más, ¿verdad?' WHERE `ID`=45275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $n. 알려지지 않은 마법을 배우러 온 건가?', `MaleText_loc4`='你好，$n。你想要学习隐秘的艺术吗？', `MaleText_loc5`='你好，$n。你是來這裡學習不為人知的技藝的嗎?', `MaleText_loc7`='Saludos, $n. ¿Has veni''o p''a aprender las Ah''tes Oh''curas?', `FemaleText_loc1`='어서 오게, $n. 알려지지 않은 마법을 배우러 온 건가?', `FemaleText_loc4`='你好，$n。你想要学习隐秘的艺术吗？', `FemaleText_loc5`='你好，$n。你是來這裡學習隱藏的技藝的嗎?', `FemaleText_loc7`='Saludos, $n. ¿Has veni''o p''a aprender las Ah''tes Oh''curas?' WHERE `ID`=45276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 안녕하십니까.

안타깝게도, 그 세계의 비밀은 당신이 닿을 수 없는 곳에 있습니다. 시간, 운명, 불타는 별과 차디찬 어둠이 놓인... 이러한 것의 진실은 절대 아실 수 없습니다!', `MaleText_loc4`='你好，$c。

真是可悲啊，你最终还是无法了解这个世界的辛秘：时间、命运、燃烧的星辰和凄冷的黑暗……你永远也无法知道这终极的真实了！', `MaleText_loc5`='你好，$c。

真可惜，世界的奧秘無法為你所知:時間，命運，燃燒的恆星，還有橫亙其間的冰冷的、冰冷的黑暗...你永遠無法得知此等事物的真相!', `MaleText_loc7`='Saludos, $c.

Es una pena, que los secretos del mundo te eh''tén veda''os: el tiempo, el deh''tino, las eh''trellas ah''dientes y la fría, fría oh''curidad que hay entre ambas... ¡Nunca conocerás la veh''dad de tales cosas!', `FemaleText_loc1`='$c님, 안녕하십니까.

안타깝게도, 그 세계의 비밀은 당신이 닿을 수 없는 곳에 있습니다. 시간, 운명, 불타는 별과 차디찬 어둠이 놓인... 이러한 것의 진실은 절대 아실 수 없습니다!', `FemaleText_loc4`='你好，$c。

真是可悲啊，你最终还是无法了解这个世界的辛秘：时间、命运、燃烧的星辰和凄冷的黑暗……你永远也无法知道这终极的真实了！', `FemaleText_loc5`='你好，$c。

真可惜，世界的奧秘無法為你所知:時間，命運，燃燒的恆星，還有橫亙其間的冰冷的、冰冷的黑暗...你永遠無法得知此等事物的真相!', `FemaleText_loc7`='Saludos, $c.

Es una pena, que los secretos del mundo te eh''tén veda''os: el tiempo, el deh''tino, las eh''trellas ah''dientes y la fría, fría oh''curidad que hay entre ambas... ¡Nunca conocerás la veh''dad de tales cosas!' WHERE `ID`=45277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 알려 주십시오, $n.', `MaleText_loc4`='准备好了就告诉我，$n。', `MaleText_loc5`='你準備好了就告訴我，$n。', `MaleText_loc7`='Avísame cuando estés $glisto:lista;, $n.' WHERE `ID`=45278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 치를 준비가 되면 나에게 알려주게, $n.', `MaleText_loc4`='准备好进行仪式之后就告诉我，$n。', `MaleText_loc5`='你準備好進行儀式就告訴我，$n。', `MaleText_loc7`='Avísame cuando estés $glisto:lista; para el ritual, $n.' WHERE `ID`=45279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이에 있는 비술사를 처치하라.', `MaleText_loc4`='消灭最靠近的无名者。', `MaleText_loc5`='殺掉最近的秘法師。', `MaleText_loc7`='Mata al místico más cercano.' WHERE `ID`=45280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비나 해라, $r!', `MaleText_loc4`='准备去死吧，$r！', `MaleText_loc5`='準備受死吧，$r!', `MaleText_loc7`='¡Prepárate para morir, $r!' WHERE `ID`=45281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 제게 그냥 알려주기만 하면 됩니다!그러면 제가 새를 불러 드리겠습니다!', `MaleText_loc4`='当你准备好的时候，只需要告诉赞吉吉就可以了！我会为你弄一只鸟下来！', `MaleText_loc5`='準備好了就跟贊基奇說一聲。我會把其中一隻鳥叫下來給你!', `MaleText_loc7`='¡Avisa a Zen''Kiki cuando estés $glih''to:lih''ta;! ¡Traeré uno de esos pájaros pa'' ti!' WHERE `ID`=45282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아악!!', `MaleText_loc4`='嗨！！', `MaleText_loc5`='啊咿咿咿咿咿!!', `MaleText_loc7`='¡AYYYIEEE!!', `FemaleText_loc1`='아아아아악!!', `FemaleText_loc4`='嗨！！', `FemaleText_loc5`='啊咿咿咿咿咿!!', `FemaleText_loc7`='¡AYYYIEEE!!' WHERE `ID`=45283;
