UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 속으로 들어가시오! 어서!', `MaleText_loc4`='赶快，$n！到箱子里去！', `MaleText_loc5`='快，$n!到箱子裡面!', `MaleText_loc7`='¡Rápido, $n! ¡A los baúles!' WHERE `ID`=45286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $g 용감한: 아름다운; $c 친구. 어떤 도움이 필요하신가?', `MaleText_loc4`='你好，$g勇敢的:美丽的;$c。我能为你做些什么？', `MaleText_loc5`='你好，$g 勇敢的:美麗的;$c。請問需要我為你服務嗎?', `MaleText_loc7`='Buenos días, $ggallardo:hermosa; $c. ¿Cómo puedo ayudarte?' WHERE `ID`=45287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 뭔가 이상한 일은 없었습니까? 대장간에 새로 온 손님은 없었는지요?', `MaleText_loc4`='最近你有没有注意到一些奇怪的事情？铁匠铺里有没有来过什么新顾客？', `MaleText_loc5`='最近有沒有注意到什麼異常現象?鐵匠鋪有任何新客人嗎?', `MaleText_loc7`='¿Has visto algo extraño últimamente? ¿Algún cliente nuevo en la herrería?', `FemaleText_loc1`='요즘 뭔가 이상한 일은 없었나요? 대장간에 새로 온 손님은 없었고요?', `FemaleText_loc4`='最近你有没有注意到一些奇怪的事情？铁匠铺里有没有来过什么新顾客？', `FemaleText_loc5`='最近有沒有注意到什麼異常現象?鐵匠鋪有任何新客人嗎?', `FemaleText_loc7`='¿Has visto algo extraño últimamente? ¿Algún cliente nuevo en la herrería?' WHERE `ID`=45288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음, 어디 한번 보자... 저쪽에 있는 광산에서 노역꾼 몇 명이 뛰쳐나오는 걸 봤소. 거미에 대해 뭐라고 하더군. 새 손님이라고 했소? 아, 제랄리가 있었소. 아름답고 젊은 노움이지. 지난주에 자기 키보다 두 배는 큰 도끼를 사갔소. 아, 그리고 비스프 님께서 방어구를 구하러 오신 적이 있었소. 그분께서 왜 판금 갑옷이 필요한지는 확실히 모르겠다오...', `MaleText_loc4`='嗯，让我想想……我看见几个苦工从那边的矿井里跑出去了。嘴里念叨着蜘蛛还是什么的。新客户？嗯，有位年轻可爱的侏儒小姐，名叫杰拉莉，她上星期买了把比她大一倍的斧子。喔，魔导师毕斯普来咨询过护甲。不知道他要板甲做什么……', `MaleText_loc5`='嗯，我想想...我看到有些苦工從那邊的礦坑跑走，說什麼有蜘蛛還是什麼的。至於新的客人?嗯，是有個可愛的地精小妞，叫做潔洛莉的，上禮拜買了一把有她兩倍大的斧頭。哦，魔導師畢斯普也有來問盔甲的事情，但是我不曉得他要鎧甲是幹嘛用的...', `MaleText_loc7`='Vamos a ver... Vi unos braceros que salieron corriendo de la mina de allá. Decían algo de una araña. ¿Clientes nuevos? Bueno, está Jeralee, esa gnoma joven y encantadora que la semana pasada trajo un hacha que le doblaba la altura. Ah, y el magus Bisp vino a pedir una armadura. No sé para qué querría una armadura de placas...' WHERE `ID`=45289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요?', `MaleText_loc4`='我能帮你吗？', `MaleText_loc5`='我能幫忙嗎?', `MaleText_loc7`='¿Puedo ayudarte?' WHERE `ID`=45290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 뭔가 이상한 낌새 같은 건 없었습니까? 새 손님이 와서 의심 가는 물건을 사거나 그러지는 않았습니까?', `MaleText_loc4`='最近你有没有注意到一些奇怪的事情？有没有来过什么新顾客，买走什么可疑的东西？', `MaleText_loc5`='最近有沒有注意到什麼異常現象?任何新的客人，購買任何可疑的東西?', `MaleText_loc7`='¿Has visto algo extraño últimamente? ¿Algún cliente nuevo que pidiera algo sospechoso?', `FemaleText_loc1`='요즘 뭔가 이상한 낌새 같은 건 없었나요? 새 손님이 와서 의심 가는 물건을 사거나 그러지는 않았나요?', `FemaleText_loc4`='最近你有没有注意到一些奇怪的事情？有没有来过什么新顾客，买走什么可疑的东西？', `FemaleText_loc5`='最近有沒有注意到什麼異常現象?任何新的客人，購買任何可疑的東西?', `FemaleText_loc7`='¿Has visto algo extraño últimamente? ¿Algún cliente nuevo que pidiera algo sospechoso?' WHERE `ID`=45291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가요? 이거 무슨 심문 같은 겁니까? 당신은 폴드링 대영주님의 내무부 소속은 아니군요. 그렇지요?$b$b글쎄요, 뭐 저는 숨길 게 없습니다. 일단 제 장부를 살펴보지요. 지난주에 마이너 부관님께 예복을 팔았는데, 조금 이상한 느낌이 들기는 했습니다. 또 다른 게... 비스프 님께서 가죽조끼를 12벌 사가셨는데, 이유는 말해주지 않으셨습니다. 아, 그리고 프라이어 벌링햄이 하드렌치 은신처에 여행 갈 때 쓴다며 수영복을 미리 사러 왔었습니다. 뭐 이 정도군요.$b$b자, 이제 죄송하지만 저는 이만 가보겠습니다. 손님이 오셔서요!', `MaleText_loc4`='这算什么，审问吗？你不是弗丁的内部事务处理人员吧？$b$b嗯，反正我也没什么可隐瞒的。让我翻翻我的记录。上星期米纳尔中尉从我这儿买了件舞会礼服，这让我感到有些奇怪。还有……魔导师毕斯普买了几件皮上衣，也没说出什么原因。喔，弗拉尔·伯林汉姆来为他的硬钳避世乐园之旅订购泳衣。就这些。$b$b要是你不介意的话，我得招呼客人了！', `MaleText_loc5`='這是幹嘛，問話取供嗎?你不會是弗丁的什麼內部事務調查員的吧?$b$b隨便，反正我也沒什麼好隱瞞的。讓我看一下我的帳冊...上禮拜我賣了一套舞會禮服給邁納中尉，我覺得是有點奇怪。還有什麼...魔導師畢斯普買了十多套皮甲衣，而且原因不明。哦，還有柏林翰修士跑來買了泳裝，說是去硬心的藏匿處度假要用的。好了，就這樣啦。$b$b我還有別的客人要招呼呢!', `MaleText_loc7`='¿Qué es esto, un interrogatorio? ¿No estarás con los tíos de asuntos internos de Vadín?$b$bBueno, no tengo nada que ocultar. Deja que mire el registro. La semana pasada le vendí un vestido de noche al teniente Myner, lo que me pareció un poco raro. Qué más... El magus Bisp compró varias docenas de chalecos de cuero, pero no supo decirme para qué las quería. Ah, y el fraile Burlingham vino para comprarse trajes de baño para su viaje al Escondrijo Malallave. Eso es todo.$b$bAhora, si no te importa, ¡tengo clientes!' WHERE `ID`=45292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님!', `FemaleText_loc4`='你好，$c！', `FemaleText_loc5`='嗨，你好，$c!', `FemaleText_loc7`='¡Hola, $c!' WHERE `ID`=45293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 부인. 요즘 재미있는 소식이라도 들은 게 있습니까?', `MaleText_loc4`='你好，女士。最近有没有听到过什么有趣的传闻？', `MaleText_loc5`='女士你好。請問最近有聽到什麼有趣的傳言嗎?', `MaleText_loc7`='Hola, señora. ¿Algún rumor interesante últimamente?', `FemaleText_loc1`='안녕하세요, 부인. 요즘 재미있는 소식이라도 들은 게 있나요?', `FemaleText_loc4`='你好，女士。最近有没有听到过什么有趣的传闻？', `FemaleText_loc5`='女士你好。請問最近有聽到什麼有趣的傳言嗎?', `FemaleText_loc7`='Hola, señora. ¿Algún rumor interesante últimamente?' WHERE `ID`=45294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='글쎄요, 어디보자... 비스프 님은 마법사 탑에 혼자 들어앉아서 새로운 주문인가 뭔가를 연구하고 있다는 소문들 들었어요.$b$b델 가론이 은퇴한 뒤에 그의 농장으로 다시 돌아가려고 한다는 소식도 들었고요. 그러고 보니 벌써 떠났을 수도 있겠네요.$b$b아, 그리고 어떤 $r $c|1이;가; 마을을 돌아다니면서 사람들에게 귀찮은 질문을 한다는 소문을 들었어요!$b$b농담이랍니다. 제가 말씀드린 게 도움이 되면 좋겠네요.', `FemaleText_loc4`='嗯，让我们瞧瞧。我听说魔导师毕斯普最近一直把自己关在塔顶，好像是在研究什么新法术之类的东西。$b$b德尔·盖罗恩正准备退休，回农场养老。事实上他可能已经离开了。$b$b喔，我还听说有个什么$r$c在城镇附近游荡，拉住人们问东问西！$b$b只是和你开个玩笑，宝贝儿。希望这些信息能帮到你。', `FemaleText_loc5`='嗯，讓我想想看。我聽說魔導師畢斯普最近都窩在他的塔樓上面，研究什麼新法術還是新東西的。$b$b然後我聽說戴爾·蓋羅恩正計畫想退休，回他的農場去種田。事實上，他說不定已經離開了。$b$b哦，我還聽說有個$r的$c在鎮上跑來跑去，到處打聽各式各樣討人厭的問題!$b$b哈哈，只是跟你開玩笑的。希望這些情報能幫得上你的忙。', `FemaleText_loc7`='A ver... He oído que el magus Bisp está pasando mucho tiempo encerrado en su torre, trabajando en un hechizo nuevo o algo así.$b$bHe oído que Del Gahrron estaba pensando en jubilarse y volver a su granja. De hecho, a lo mejor ya se ha ido.$b$bAh, y me han contado que hay $gun:una; $r $c husmeando por la ciudad y haciéndole a la gente toda clase de preguntas aburridas.$b$bSolo era una broma, cielo. Espero que la información te sea de ayuda.' WHERE `ID`=45295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 가호가 있기를. 이 좋은 날에 어떤 도움이 필요하신 건가요?', `MaleText_loc4`='愿光明眷顾你，孩子。在这样美好的日子里，我能为你做些什么？', `MaleText_loc5`='願聖光照耀你，孩子。今天有什麼需要我幫忙的嗎?', `MaleText_loc7`='Que la Luz te ampare, hijo. ¿Qué puedo hacer por ti en este día tan estupendo?' WHERE `ID`=45296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하스글렌에서 보급품을 훔쳐간 것으로 의심되는 자를 찾고 있습니다. 제게 알려주실 것이라도 없으십니까?', `MaleText_loc4`='我正在寻找一个曾经在壁炉谷偷窃物资的贼。有什么线索么？', `MaleText_loc5`='我在尋找某個可能從壁爐谷偷走了一些補給品的嫌疑犯。有任何線索可以提供給我嗎?', `MaleText_loc7`='Estoy buscando a alguien que podría haber robado suministros de Vega del Amparo. ¿Tienes alguna pista?', `FemaleText_loc1`='하스글렌에서 보급품을 훔쳐간 것으로 의심되는 자를 찾고 있답니다. 제게 알려주실 것이라도 없으신가요?', `FemaleText_loc4`='我正在寻找一个曾经在壁炉谷偷窃物资的贼。有什么线索么？', `FemaleText_loc5`='我在尋找某個可能從壁爐谷偷走了一些補給品的嫌疑犯。有任何線索可以提供給我嗎?', `FemaleText_loc7`='Estoy buscando a alguien que podría haber robado suministros de Vega del Amparo. ¿Tienes alguna pista?' WHERE `ID`=45297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑맞은 보급품이라고요? 어디 생각 좀 해볼게요...$b$b다리아라는 사제가 지난주 미사가 끝나고 남은 포도주를 모두 가져갔었는데, 제가 부탁한 대로 그것들을 다 버리지 않았던 건 알아요. 하지만 곧 반성할 거라고 믿어요.$b$b<당신에게 한쪽 눈을 깜박이는 알푸스>$b$b그리고 마법사 중 한 명이 이번 주에 비정상적으로 많은 양의 고해성사를 했다는 말을 들었어요... 이름이 뭐라고 했더라? 크리스프? 리스프? 하여튼 이것 비슷한 이름이었어요.$b$b자, 이제 그만 가 보세요.', `MaleText_loc4`='被盗的补给品？嗯，让我想想……$b$b我知道有个叫达莉亚的祭司，在上星期活动结束后把剩下的酒都拿走了，并没有照我说的放回来。不过我相信她很快就会前来为此道歉的。$b$b<阿尔法斯朝你眨了眨眼。>$b$b我还听到那个法师……叫什么来着……克里斯普？还是利斯普？差不多就是这名字吧。他这礼拜一反常态地做了不少次忏悔。$b$b好了，快走开吧。', `MaleText_loc5`='偷走補給品?嗯，容我想想...$b$b我知道有個叫做妲莉安的牧師在上禮拜的祈禱會結束後偷走了剩下的全部葡萄酒，但是我並沒有揭發這件事情，因為我相信她很快就會來道歉認錯。$b$b<阿爾佛斯對你眨眨眼睛。>$b$b這個禮拜還有個法師很不尋常地找我做了許多次的告解...他叫什麼名字來著?克斯普?利斯普?差不多那樣子。$b$b好了，去忙你的吧。', `MaleText_loc7`='¿Suministros robados? Déjame pensar...$b$bSé que una sacerdotisa llamada Daria se llevó todo el vino después del servicio, pero no lo tiró tal y como se lo pedí. Pero creo que pedirá disculpas muy pronto.$b$b<Alphus te guiña el ojo.>$b$bTambién he escuchado una cantidad extraordinaria de confesiones de uno de los magos... ¿Cómo se llamaba? ¿Crisp? ¿Lisp? Algo así.$b$bYa puedes seguir con lo tuyo.' WHERE `ID`=45298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭐, 뭘 하는 겁니까? 지금 당신이 은빛십자군의 공무를 방해하는 걸 모르시는 겁니까!?', `MaleText_loc4`='你……你在这里做什么，$r？难道你看不出，你已经干扰了银色北伐军的官方行动？！', `MaleText_loc5`='你...你在這上頭做什麼，$r?你不曉得你正在干擾銀白十字軍的重要公務嗎!?', `MaleText_loc7`='¿Q-qué haces aquí, $r? ¡¿No ves que estás interfiriendo con ASUNTOS OFICIALES DE LA CRUZADA ARGENTA?!' WHERE `ID`=45299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 있는 놀들에 대해 당신이 아는 게 있는지 궁금할 뿐입니다. 놈들이 강령술을 행하도록 누군가가 보급품을 보내줘서 말이지요.', `MaleText_loc4`='我只是在奇怪，你对南边的那些豺狼人到底有些什么了解。有人正在利用它们施行巫术。', `MaleText_loc5`='我只是好奇，你對南邊的那些豺狼人有何見解。有人在供應他們練習死靈法術的物品。', `MaleText_loc7`='Me preguntaba qué sabes de los gnolls del sur. Alguien les ha estado dando suministros para practicar la nigromancia.', `FemaleText_loc1`='남쪽에 있는 놀들에 대해 당신이 아는 게 있는지 궁금할 뿐이에요. 놈들이 강령술을 행하도록 누군가가 보급품을 보내줘서 말이죠.', `FemaleText_loc4`='我只是在奇怪，你对南边的那些豺狼人到底有些什么了解。有人正在利用它们施行巫术。', `FemaleText_loc5`='我只是好奇，你對南邊的那些豺狼人有何見解。有人在供應他們練習死靈法術的物品。', `FemaleText_loc7`='Me preguntaba qué sabes de los gnolls del sur. Alguien les ha estado dando suministros para practicar la nigromancia.' WHERE `ID`=45300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 계획을 방해했으니 목숨을 그 대가로 치르게 될 것이다! 이 하찮은 쓰레기 같은 놈!', `MaleText_loc4`='竟敢阻挠我的计划，你将为此付出生命的代价，你这个可怜的渣滓！', `MaleText_loc5`='卑微的垃圾，竟然膽敢破壞我的計畫，用你的生命來付出代價吧!', `MaleText_loc7`='¡Pagarás con tu vida por interferir en mis planes, escoria miserable!' WHERE `ID`=45301;
