UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니 말씀이 맞았습니다... 이제 절대로 은빛십자군 같은 건 꿈도 꾸지 않을 겁니다.', `MaleText_loc4`='妈妈说得对……我永远也没办法进入银色北伐军。', `MaleText_loc5`='媽說的對...我「永遠」無法加入銀白十字軍。', `MaleText_loc7`='Mamá tenía razón... NUNCA entraré en la Cruzada Argenta.', `FemaleText_loc1`='어머니 말씀이 맞았어요... 이제 절대로 은빛십자군 같은 건 꿈도 꾸지 않을 거예요.', `FemaleText_loc4`='妈妈说得对……我永远也没办法进入银色北伐军。', `FemaleText_loc5`='媽說的對...我「永遠」無法加入銀白十字軍。', `FemaleText_loc7`='Mamá tenía razón... NUNCA entraré en la Cruzada Argenta.' WHERE `ID`=45314;
