UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고블린식 통구이를 굽습니다! 잔치 준비를 하세요!', `MaleText_loc4`='%s点燃了地精烤肉野餐的篝火！准备好加入聚会吧！', `MaleText_loc5`='%s點燃哥布林烤肉!準備開始派對!', `MaleText_loc7`='¡%s enciende la barbacoa goblin! ¡Prepárate para la fiesta!', `FemaleText_loc1`='%s|1이;가; 고블린식 통구이를 굽습니다! 잔치 준비를 하세요!', `FemaleText_loc4`='%s点燃了地精烤肉野餐的篝火！准备好加入聚会吧！', `FemaleText_loc5`='%s點燃哥布林烤肉!準備開始派對!', `FemaleText_loc7`='¡%s enciende la barbacoa goblin! ¡Prepárate para la fiesta!' WHERE `ID`=45316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 얼마나 자주 성공하는지 알면 당신도 깜짝 놀랄 거요.', `MaleText_loc4`='它发挥作用的频繁程度一定会让你吃惊的。', `MaleText_loc5`='你會很驚訝那個成功的機率有多高。', `MaleText_loc7`='Te sorprendería lo bien que funciona.' WHERE `ID`=45317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서판 조각 입수', `MaleText_loc4`='举起', `MaleText_loc5`='舉起', `MaleText_loc7`='Alzando', `FemaleText_loc1`='서판 조각 입수', `FemaleText_loc4`='举起', `FemaleText_loc5`='舉起', `FemaleText_loc7`='Alzando' WHERE `ID`=45318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드와 전투를 벌이고 항구로 기어들어올 때까진 함선이 대체로 온전했습니다. 저희는 높은 둑의 그늘에 숨어 닻을 내리고 다른 함선과 조우하길 기다리고 있었지요.$B$B그때 나가가 나타났습니다.$B$B비늘 덮인 번쩍이는 손으로 닻줄을 잡고 기어올라왔지요... 그리고 비명을 지르는 우리 병사들을 바닷속 깊은 곳으로 끌고 들어갔습니다...$B$B여기는 저주받은 바닷가입니다, $n 님. 저주받았다고요.', `MaleText_loc4`='在我们与部落交战之后，我们的舰队在进入港口的时候还保持了大致完整的规模。我们在滩头堡的阴影中起锚，重新集结。$B$B就在此时，纳迦出现了。$B$B无数只覆盖着闪光鳞片的手攀住锚链……将人们拖入水中，让他们尖叫着沉入深渊……$B$B这是被诅咒的海岸，$n。被诅咒了。', `MaleText_loc5`='當我們的艦隊結束跟部落的遭遇戰，緩緩開進來港口的時候，大致上都還是完整無損的。然後，我們下錨停在高岸堡的下方進行重整。$B$B結果，納迦就來了。$B$B長滿亮亮鱗片的手沿著船錨的鐵鍊爬上來...把受驚尖叫的船員拖進深海...$b$b啊，這是個詛咒的海岸，$n，詛咒的海岸啊。', `MaleText_loc7`='La flota estaba intacta en su mayor parte cuando se arrastró hasta el puerto después de nuestro enfrentamiento con la Horda. Echamos el ancla al abrigo de Bancalto para reagruparnos.$B$BEntonces vinieron los nagas.$B$BManos escamadas y brillantes que trepaban por las cadenas de las anclas... y arrastraban a los hombres a las profundidades mientras estos no dejaban de gritar...$B$BSon costas malditas, $n. Malditas.' WHERE `ID`=45319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치하세요, $c님! 쓰러진 이들을 기리며, 최대한 많은 나가를 없애버리세요.', `MaleText_loc4`='消灭他们，$c！摧毁尽可能多的纳迦，为逝去者报仇。', `MaleText_loc5`='殺掉他們，$c!殺掉越多的納迦越好，為陣亡的將士們報仇。', `MaleText_loc7`='¡Extermínalos, $c! Destruye tantos nagas como puedas para honrar a los caídos.' WHERE `ID`=45320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕이 우리 위에 있다! 두려워할 것 없다, 육체의 소유자여. 내가 "한결같은" 테라스인 데는 다 이유가 있다...', `MaleText_loc4`='龙女王飞到了我们头顶上！别害怕，年轻人，我被称为“坚定者”可是有来由的……', `MaleText_loc5`='那隻育母飛到我們上頭啦!不要害怕，人家會叫我「沉穩的特拉斯」是有原因的...', `MaleText_loc7`='¡La madre de linaje vuela sobre nosotros! ¡No temas, ser de carne, me llaman "el Firme" por una razón...' WHERE `ID`=45321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 사이를 옮겨 다니며 여왕의 시선을 끄십시오!', `MaleText_loc4`='从一块石头跳到另一块石头上，吸引龙女王的注意力！', `MaleText_loc5`='在岩石間跳躍，吸引育母的注意!', `MaleText_loc7`='¡Salta de roca a roca para atraer la atención de la madre de linaje!' WHERE `ID`=45322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 실패해선 안 됩니다, $n 님. 여러 세계의 미래가 걸린 일입니다.', `MaleText_loc4`='我们不能失败，$n。许多个世界的未来都将由这场战斗而决定。', `MaleText_loc5`='我們絕對不能失敗，$n。許多個世界的未來都會受到波及。', `MaleText_loc7`='No podemos fallar, $n. Está en juego el futuro de varios mundos.' WHERE `ID`=45323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 상자 못 가져가!', `MaleText_loc4`='别想拿走箱子！', `MaleText_loc5`='你不准拿箱子!', `MaleText_loc7`='¡Tú no llevar caja!' WHERE `ID`=45324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다... 덕분에 앞으로 몇 시간은 바위에 부딪히지 않고 비행선을 조종할 수 있을 것 같습니다. 물론 장담할 순 없지만요.', `MaleText_loc4`='谢谢……这样的话，我们还可以坚持几个小时，不跑进岩石里去。但那以后，我就没办法做任何保证了。', `MaleText_loc5`='謝謝...這讓我們有多幾個小時的時間不會碰到那些岩石。但是之後就不保證了。', `MaleText_loc7`='Gracias... Esto evitará que nos estrellemos contra las rocas en las próximas dos horas. Después de eso, no hay garantías.' WHERE `ID`=45325;
