UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 $r 같으니! 방해한 대가를 치르게 해 주마!', `MaleText_loc4`='你这个没脑子的$r！你要为你的行为付出代价！', `MaleText_loc5`='沒腦袋的$r!你得為你的多管閒事付出代價!', `MaleText_loc7`='¡$R $ginsensato:insensata;! ¡Pagarás por tu intromisión!' WHERE `ID`=45340;
