UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열이 사라지고 오그리마는 이제 안전하오! 이 차원문들이 놈들의 두 번째 공격 계획일 거요.$b$b서두르시오! 차원문으로! 승기를 잡았을 때 계속해서 공격해야 하오!', `MaleText_loc4`='裂隙已经被关闭，奥格瑞玛安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！', `MaleText_loc5`='元素裂隙已經關閉，奧格瑪安全了!這些傳送門必定是他們後半段的攻擊行動。$B$B動作快!進入傳送門!我們必須趁勝追擊!', `MaleText_loc7`='¡Las fallas han caído y Orgrimmar está a salvo! Los portales deben de ser la segunda mitad de su ataque.$B$B¡Rápido! ¡Al portal! ¡Debemos atacar ahora que llevamos ventaja!' WHERE `ID`=45342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번 내 행동에 무례함이 있었다면 용서해라. 아바마마가 너무 걱정되어서 그만. 이제 우리 친구 되는 거다?', `MaleText_loc4`='我为刚刚的无礼行为道歉。因为我非常担心我的父亲。我们是朋友，对不对？', `MaleText_loc5`='我為先前的失禮向你道歉，因為我實在很擔心我父親。我們還是朋友吧?', `MaleText_loc7`='Disculpa mi brusquedad anterior. Estaba preocupado por mi padre. ¿Amigos?' WHERE `ID`=45343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 책임지고 자네가 세계 기둥 중간 파편을 얻게 해 주겠네.', `MaleText_loc4`='我一定会让你得到世界之柱中端的残片。', `MaleText_loc5`='我會幫你們取得世界之柱的中間碎片。', `MaleText_loc7`='Me aseguraré de que consigas el fragmento central del Pilar del Mundo.' WHERE `ID`=45344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 이 사후 세계에서 어떻게 도와드릴까요?', `MaleText_loc4`='在死亡之后，我还能帮你些什么？', `MaleText_loc5`='我要如何在此來生中協助你?', `MaleText_loc7`='¿Cómo puedo serte de ayuda en la otra vida?', `FemaleText_loc1`='제가 이 사후 세계에서 어떻게 도와드릴까요?', `FemaleText_loc4`='在死亡之后，我还能帮你些什么？', `FemaleText_loc5`='我要如何在此來生中協助你?', `FemaleText_loc7`='¿Cómo puedo serte de ayuda en la otra vida?' WHERE `ID`=45345;
