UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 오는군요. 오, 바다의 사악한 유혹이여...', `MaleText_loc4`='她来了。哦，海洋的邪恶荡妇……', `MaleText_loc5`='她來了。哦，這可惡的海上妖婦啊...', `MaleText_loc7`='Aquí viene. Oh, maldita seductora del mar...' WHERE `ID`=45348;
