UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 목소리를 들어선 안 돼!', `MaleText_loc4`='不要听她的声音！', `MaleText_loc5`='不要聽她的聲音!', `MaleText_loc7`='¡No escuchéis su voz!' WHERE `ID`=45350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀를 보지 마... 루비처럼 붉고... 부드러운... 감각적인 입술! 오오...', `MaleText_loc4`='不要看她那……红宝石般的……柔软的……肉欲的双唇！哦……', `MaleText_loc5`='千萬不要看她...紅寶石一樣的...柔軟的...性感的嘴唇!哦...', `MaleText_loc7`='No miréis sus labios... rojos como rubíes... suaves... sensuales... Ay...' WHERE `ID`=45351;
