UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상자는 무기와 갑옷을 담아놓는 데 쓰였던 것 같습니다.', `MaleText_loc4`='看起来，这只箱子的功用应该是储存武器和盔甲。', `MaleText_loc5`='這個箱子看來像是存放武器和盔甲的。', `MaleText_loc7`='Parece que este cajón se ha utilizado para almacenar armas y armaduras.' WHERE `ID`=45354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='덕분에 한숨 돌릴 수 있게 되었습니다. 도와 주셔서 감사합니다!', `FemaleText_loc4`='真高兴能有机会喘一口气。谢谢你的帮助！', `FemaleText_loc5`='很高興能有機會喘口氣。謝謝幫忙!', `FemaleText_loc7`='Me alegro de haber tenido la oportunidad de recuperar el aliento. ¡Gracias por tu ayuda!' WHERE `ID`=45355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 놈들을 처리하지 못할 줄 아셨나요? 작다고 무시하시면 곤란합니다. 어쨌든, 도와 주셔서 고맙습니다.', `MaleText_loc4`='你以为我对付不了他们？不要因为我矮就瞧不起我。不管怎样，还是要感谢你的帮忙。', `MaleText_loc5`='你以為我會對付不了他們?別讓我的個頭給騙了。不過，我還是很謝謝你的幫忙。', `MaleText_loc7`='¿Pensabas que no podría encargarme de ellos? No dejes que te engañe mi tamaño. En fin, gracias por tu ayuda.' WHERE `ID`=45356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나니 반갑네요! 도와주셔서 감사해요. 조금만 쉬면 금방 괜찮아질 거예요.', `FemaleText_loc4`='真高兴能再见到你！感谢你的帮忙。我再过一会儿就能站起来了。', `FemaleText_loc5`='真高興又見到你!謝謝你的幫忙。我再歇一會兒就會起來。', `FemaleText_loc7`='¡Me alegro de volver a verte! Gracias por tu ayuda. Me recuperaré en un momento.' WHERE `ID`=45357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가면을 쓴 채로는 아무것도 볼 수 없어. 하지만, 주인에게는 비밀로 할 거야.', `MaleText_loc4`='戴上这副面具，我什么都看不见。但我可不会告诉她这个。', `MaleText_loc5`='戴上這個面具根本什麼都看不見，但是我可不打算把這點告訴她。', `MaleText_loc7`='No veo un pimiento con esta máscara, pero no pienso decírselo a ELLA.' WHERE `ID`=45358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기와... 갑옷은... 적에게 승리를 쟁취하는 데 중요한 역할을 하지. 아무리 용맹하고 강력한 전사라도 이것들 없이는 무방비상태니까 말이야.$B$B인생을 사는 동안 나는 전설의 무기라고 불리는 것들을 많이 만들었다네. 아제로스 전체를 돌아다녀 봐도 내 것처럼 좋은 건 없을 거야. 이 무기와 방어구는 내 형제들의 성공에 중요한 역할을 하고 있네.', `MaleText_loc4`='武器……盔甲……这些都是取得胜利的关键。任何一名战士，无论他是多么强壮，都很难周全地保护自己。$B$B$r，我曾经打造过许多传奇的武器和护甲，你在全艾泽拉斯也无法找到能和它们比拟的杰出作品。它们正是我的同胞赢取胜利的关键。', `MaleText_loc5`='武器...防具...這些東西都是致勝的關鍵。所有的戰士，不管多麼強壯，只要少了它們就會難以自保。$B$B在我年輕的時候我也打造了不少傳奇性的裝備，$r，而且你在全艾澤拉斯都找不到跟他們同樣了不起的。因為他們都是我的弟兄們得以成功的關鍵。', `MaleText_loc7`='Armas... Armadura... Son las claves de la victoria. Todos los guerreros, incluso los más fuertes, están indefensos sin ellas.$b$bEn mis tiempos creé muchas leyendas, $r. No verás nada igual en todo Azeroth. Son la clave del éxito de mis hermanos.' WHERE `ID`=45359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸서리는 항상 농부 되고 싶었다.', `MaleText_loc4`='血肚一直想当个农夫。', `MaleText_loc5`='勾里一直想要當農夫。', `MaleText_loc7`='Gory siempre quiso ser granjero.' WHERE `ID`=45360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸서리 햇빛 아래 있어서 행복하다.', `MaleText_loc4`='血肚站在太阳底下真高兴。', `MaleText_loc5`='勾里喜歡曬太陽。', `MaleText_loc7`='Gory contento de estar al sol.' WHERE `ID`=45361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸서리 농장 일 돕고 싶다. 몸서리는 낫도 있다!', `MaleText_loc4`='血肚想帮忙干农活。血肚已经准备好镰刀了！', `MaleText_loc5`='勾里想要到農場幫忙。勾里已經有自己的鐮刀!', `MaleText_loc7`='Gory quiere ayudar en la granja. ¡Gory ya tiene guadaña!' WHERE `ID`=45362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸서리 풀 잘 못 심는다. 그런데 베는 건 자신 있다.', `MaleText_loc4`='血肚不太擅长耕种，可血肚超级擅长收割。', `MaleText_loc5`='勾里種田種不好，但是勾里割草很厲害。', `MaleText_loc7`='A Gory no se le da bien plantar, pero a Gory se le da MUY bien segar.' WHERE `ID`=45363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 돕고 싶다면, 저와 제 친구들이 전투 훈련하는 것을 도와주십시오.', `MaleText_loc4`='如果你真的想帮忙，你可以帮我和我的朋友们进行一些格斗练习。', `MaleText_loc5`='你若是真的想幫忙的話，你可以幫我和我的朋友們做點戰鬥的練習。', `MaleText_loc7`='Si de verdad quieres ayudar, puedes ayudarnos a mis amigos y a mí con algo de práctica de combate.', `FemaleText_loc1`='정말 돕고 싶다면, 저와 제 친구들이 전투 훈련하는 것을 도와주세요.', `FemaleText_loc4`='如果你真的想帮忙，你可以帮我和我的朋友们进行一些格斗练习。', `FemaleText_loc5`='你若是真的想幫忙的話，你可以幫我和我的朋友們做點戰鬥的練習。', `FemaleText_loc7`='Si de verdad quieres ayudar, puedes ayudarnos a mis amigos y a mí con algo de práctica de combate.' WHERE `ID`=45364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속칭 성기사란 놈들이 지나가지 못하게 막아서 프라스 샤비의 그 유명한 담배가 스트라솔름 안에 남았는지 확인할 수가 없네! 스컬지보다 나은 데가 하나도 없는 놈들이야.$B$B우리끼리니까 하는 말이지만, ''빛의 결사단''인지 뭔지 그냥 속 빈 강정 같아. 안이 텅텅 빈 강정 말이야!', `MaleText_loc4`='那些所谓的圣骑士不让我通过。这样我就没办法去确认那些传说中弗拉斯·希亚比的著名烟草在斯坦索姆是否还有一些遗存！要我说，他们比天灾怪物好不了多少。$B$B这话我也就对你说说，我相信他们那个所谓的“圣光兄弟会”根本就是一场骗局。一个精心设计的阴谋！', `MaleText_loc5`='這些所謂的聖騎士不放我過去，害我沒辦法進斯坦索姆去看弗拉斯·希亞比知名的傳奇煙草是否還有剩下!在我看來，他們根本沒比天譴軍團好到哪裡去。$B$B偷偷跟你說，我覺得他們的什麼「聖光兄弟會」根本是卡唬爛，只是騙人的漂亮口號罷了!', `MaleText_loc7`='"¡Esos supuestos "paladines" no me dejan pasar para ver si queda algo del famoso tabaco de Fras Siabi en Stratholme! Son igual de malos que la Plaga, si quieres mi opinión.$b$bEntre tú y yo, creo que su "Hermandad de la Luz" es un fraude. ¡Una complicada conspiración, hazme caso!' WHERE `ID`=45365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 싶다고? 좋다. 몸서리 싸운다.', `MaleText_loc4`='你想打架吗？好吧，血肚跟你打。', `MaleText_loc5`='你要打架?好吧，勾里打架。', `MaleText_loc7`='¿Quieres luchar? Vale, Gory lucha.' WHERE `ID`=45366;
