UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 존스 박사님!', `MaleText_loc4`='我准备好了，琼斯博士！', `MaleText_loc5`='我已經準備好了，瓊斯博士!', `MaleText_loc7`='¡Estoy listo, doctor Jones!', `FemaleText_loc1`='준비됐어요, 존스 박사님!', `FemaleText_loc4`='我准备好了，琼斯博士！', `FemaleText_loc5`='我已經準備好了，瓊斯博士!', `FemaleText_loc7`='¡Estoy lista, doctor Jones!' WHERE `ID`=45392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기는 많이 들었습니다, $n 님. 지금 세상에는 그 어느 때보다 당신 같은 분이 필요합니다.', `MaleText_loc4`='我听说过许多关于你的事情，$n。这个世界比以往更加需要像你这样的人。', `MaleText_loc5`='我聽說過你的很多事蹟，$n。這個世界此刻十分需要像你這樣的人。', `MaleText_loc7`='He oído hablar mucho de ti, $n. El mundo necesita gente como tú, ahora más que nunca.' WHERE `ID`=45393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포테스키가 자네를 구해준 오늘을 영원히 기억하게. 자, 어서 뛰어! 실바나스 님께 돌아가!', `MaleText_loc4`='记住这一天——是Forteski救了你。快跑吧！回到希尔瓦娜斯那里去！', `MaleText_loc5`='好好記住，今天就是佛泰斯基救了你一命的大日子。快滾吧!滾回去找希瓦娜斯!', `MaleText_loc7`='Recuerda este día como el día en que Forteski te salvó el pellejo. ¡Ahora corre! ¡Vuelve con Sylvanas!' WHERE `ID`=45394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구.$b$b소환수를 우리에 집어넣고 싶은 건가? 아니면 잃어버린 동료를 찾고 있었나?', `MaleText_loc4`='嗨，朋友。$B$B你是想要拴住你的宠物吗？还是在寻找一个丢失的同伴？', `MaleText_loc5`='嘿呀，老兄。$B$B你想要寄放你的寵物，還是想要找回失去的夥伴?', `MaleText_loc7`='Hey, hola, colega.$b$bSaludos, $c. ¿Quieres guardar a tus mah''cotas o recuperar a un compañero perdi''o?', `FemaleText_loc1`='이봐요, 친구.$b$b소환수를 우리에 집어넣고 싶은 건가요? 아니면 잃어버린 동료를 찾고 있었나요?', `FemaleText_loc4`='嗨，朋友。$B$B你是想要拴住你的宠物吗？还是在寻找一个丢失的同伴？', `FemaleText_loc5`='嘿呀，老兄。$B$B你想要寄放你的寵物，還是想要找回失去的夥伴?', `FemaleText_loc7`='Hey, hola, colega.$b$bSaludos, $c. ¿Quieres guardar a tus mah''cotas o recuperar a un compañero perdi''o?' WHERE `ID`=45395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구.$b$b잃어버린 동료를 찾고 있는 건가?', `MaleText_loc4`='嗨，朋友。$B$B你需要找回一个丢失的同伴吗？', `MaleText_loc5`='嘿呀，老兄。$B$B你需要人幫忙找回失去的夥伴?', `MaleText_loc7`='Hey, hola, colega.$B$B¿Necesitas ayuda pa'' recuperar a un compañero perdi''o?', `FemaleText_loc1`='이봐요, 친구.$b$b잃어버린 동료를 찾고 있는 건가요?', `FemaleText_loc4`='嗨，朋友。$B$B你需要找回一个丢失的同伴吗？', `FemaleText_loc5`='嘿呀，老兄。$B$B你需要人幫忙找回失去的夥伴?', `FemaleText_loc7`='Hey, hola, colega.$B$B¿Necesitas ayuda pa'' recuperar a un compañero perdi''o?' WHERE `ID`=45396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, $c 친구. 자네한테는 차원문을 이해할만한 정신적인 능력이 없는 것 같네.', `MaleText_loc4`='抱歉，$c。$B$B我不认为你有能力掌握传送门魔法的真髓。', `MaleText_loc5`='抱歉，$c。$B$B我想你應該沒有足以理解傳送魔法之本質的心智能力。', `MaleText_loc7`='Lo siento, $c.$b$bNo creo que tengas la mente adecua''a pa'' entender la naturaleza de la magia del poh''tal.', `FemaleText_loc1`='미안해요, $c님. 당신한테는 차원문을 이해할만한 정신적인 능력이 없는 것 같군요.', `FemaleText_loc4`='抱歉，$c。$B$B我不认为你有能力掌握传送门魔法的真髓。', `FemaleText_loc5`='抱歉，$c。$B$B我想你應該沒有足以理解傳送魔法之本質的心智能力。', `FemaleText_loc7`='Lo siento, $c.$b$bNo creo que tengas la mente adecua''a pa'' entender la naturaleza de la magia del poh''tal.' WHERE `ID`=45397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보게, 친구.$b$b자네가 준비되었다면 여기로 다시 돌아올 수 있는 순간이동 기술을 가르쳐 줄 수 있네만...', `MaleText_loc4`='嗨，朋友。$B$B如果你准备好了，我能教你如何开启一道返回这里的传送门……', `MaleText_loc5`='嘿呀，老兄。$B$B要是你準備好了，我可以教導你如何召喚一個能通往這裡的傳送門...', `MaleText_loc7`='Hey, hola, colega.$B$BSi eh''tás $glih''to:lih''ta;, puedo enseñah''te cómo invocar un poh''tal pa'' regresar a ese lugar...', `FemaleText_loc1`='이 봐요, 친구.$b$b당신이 준비되었다면 여기로 다시 돌아올 수 있는 순간이동 기술을 가르쳐 줄 수 있습니다만...', `FemaleText_loc4`='嗨，朋友。$B$B如果你准备好了，我能教你如何开启一道返回这里的传送门……', `FemaleText_loc5`='嘿呀，老兄。$B$B要是你準備好了，我可以教導你如何召喚一個能通往這裡的傳送門...', `FemaleText_loc7`='Hey, hola, colega.$B$BSi eh''tás $glih''to:lih''ta;, puedo enseñah''te cómo invocar un poh''tal pa'' regresar a ese lugar...' WHERE `ID`=45398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장과 은행은 골짜기 중앙의 높은 건물 꼭대기에 있습니다.$B$B지지와 마카부를 찾아보십시오.', `MaleText_loc4`='拍卖行和银行就位于山谷中部那高耸入云的建筑顶部，伙计。$B$B去找泽基和Makavu吧。', `MaleText_loc5`='拍賣場和銀行在谷地中間那個高大建築的最上面，老兄。$B$B去找茲吉和瑪卡於。', `MaleText_loc7`='La casa de subah''tas y el banco eh''tán en lo alto de ese gran edificio en medio del valle, colega.$B$BBuh''ca a Aziji y a Makavu.', `FemaleText_loc1`='경매장과 은행은 골짜기 중앙의 높은 건물 꼭대기에 있습니다.$B$B지지와 마카부를 찾아보십시오.', `FemaleText_loc4`='拍卖行和银行就位于山谷中部那高耸入云的建筑顶部，伙计。$B$B去找泽基和Makavu吧。', `FemaleText_loc5`='拍賣場和銀行在谷地中間那個高大建築的最上面，老兄。$B$B去找茲吉和瑪卡於。', `FemaleText_loc7`='La casa de subah''tas y el banco eh''tán en lo alto de ese gran edificio en medio del valle, colega.$B$BBuh''ca a Aziji y a Makavu.' WHERE `ID`=45399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시잠비를 만나고 싶으신게로군요.$B$B골짜기 가운데에 있는 높은 건물 안에 있습니다.', `MaleText_loc4`='你得去找斯加姆比，伙计。$B$B她就在山谷中部那座高高的建筑里。', `MaleText_loc5`='老兄，希賈姆畢就是你要找的人。$B$B她在谷地中間那棟高樓裡面。', `MaleText_loc7`='Es a Sijambi a quien buh''cas, colega.$B$BLa encontrará'' en el gran edificio en el centro del valle.', `FemaleText_loc1`='시잠비를 만나고 싶으신게로군요.$B$B골짜기 가운데에 있는 높은 건물 안에 있습니다.', `FemaleText_loc4`='你得去找斯加姆比，伙计。$B$B她就在山谷中部那座高高的建筑里。', `FemaleText_loc5`='老兄，希賈姆畢就是你要找的人。$B$B她在谷地中間那棟高樓裡面。', `FemaleText_loc7`='Es a Sijambi a quien buh''cas, colega.$B$BLa encontrará'' en el gran edificio en el centro del valle.' WHERE `ID`=45400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기 여관 바로 바깥쪽에 있습니다.$B$B가운데에 있는 높은 건물이지요.', `MaleText_loc4`='就在这座山谷的旅店外面，朋友。$B$B就是山谷中部的那座高大的建筑物。', `MaleText_loc5`='就在這座谷地的旅店外面，老兄。$B$B中間最高的那一棟樓。', `MaleText_loc7`='Juh''to fuera de la posada del valle, colega.$B$BEs el gran edificio en el centro.', `FemaleText_loc1`='골짜기 여관 바로 바깥쪽에 있습니다.$B$B가운데에 있는 높은 건물이지요.', `FemaleText_loc4`='就在这座山谷的旅店外面，朋友。$B$B就是山谷中部的那座高大的建筑物。', `FemaleText_loc5`='就在這座谷地的旅店外面，老兄。$B$B中間最高的那一棟樓。', `FemaleText_loc7`='Juh''to fuera de la posada del valle, colega.$B$BEs el gran edificio en el centro.' WHERE `ID`=45401;
