UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여! 무기를 들어라! 이들이 우리의 땅을 파괴하려 한다!', `MaleText_loc4`='兄弟姐妹们，拿起刀剑来！他们正在摧毁这片沃土！', `MaleText_loc5`='兄弟姊妹們，拿起武器!他們正在破壞我們的家園!', `MaleText_loc7`='¡A las armas, hermanos y hermanas! ¡Están destruyendo nuestra tierra!', `FemaleText_loc1`='형제자매여! 무기를 들어라! 이들이 우리의 땅을 파괴하려 한다!', `FemaleText_loc4`='兄弟姐妹们，拿起刀剑来！他们正在摧毁这片沃土！', `FemaleText_loc5`='兄弟姊妹們，拿起武器!他們正在破壞我們的家園!', `FemaleText_loc7`='¡A las armas, hermanos y hermanas! ¡Están destruyendo nuestra tierra!' WHERE `ID`=45417;
