UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔디와 질아야는 골짜기의 가운데 있는 건물 북쪽에서 일합니다.$B$B필요한 일이 무엇이든 간에 도움을 받을 수 있습니다.', `MaleText_loc4`='加迪和希尔拉亚就在这座山谷中心建筑北边的一座小屋里工作。$B$B他们能提供你所需要的帮助，朋友。', `MaleText_loc5`='加迪和希爾拉亞工作的地方就在精神谷中央建築的北邊。$B$B你需要什麼他們都可以幫你，老兄。', `MaleText_loc7`='Jandi y Zeal''aya trabajan en una cabaña juh''to al norte del edificio central del valle.$b$bPueden ayudah''te con todo lo que necesites, colega.', `FemaleText_loc1`='잔디와 질아야는 골짜기의 가운데 있는 건물 북쪽에서 일합니다.$B$B필요한 일이 무엇이든 간에 도움을 받을 수 있습니다.', `FemaleText_loc4`='加迪和希尔拉亚就在这座山谷中心建筑北边的一座小屋里工作。$B$B他们能提供你所需要的帮助，朋友。', `FemaleText_loc5`='加迪和希爾拉亞工作的地方就在精神谷中央建築的北邊。$B$B你需要什麼他們都可以幫你，老兄。', `FemaleText_loc7`='Jandi y Zeal''aya trabajan en una cabaña juh''to al norte del edificio central del valle.$b$bPueden ayudah''te con todo lo que necesites, colega.' WHERE `ID`=45435;
