UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기 가운데에 있는 건물 동쪽으로 가면 작은 섬이 있는데 늙은이 움베토는 거기에 있답니다.', `MaleText_loc4`='老恩姆贝托就在位于山谷中部建筑东面的一座小岛上。', `MaleText_loc5`='老昂貝托就在精神谷中央建築東邊的小島上。', `MaleText_loc7`='Encontrarás al Viejo Umbehto en la pequeña isla al este del edificio central de valle.', `FemaleText_loc1`='골짜기 가운데에 있는 건물 동쪽으로 가면 작은 섬이 있는데 늙은이 움베토는 거기에 있답니다.', `FemaleText_loc4`='老恩姆贝托就在位于山谷中部建筑东面的一座小岛上。', `FemaleText_loc5`='老昂貝托就在精神谷中央建築東邊的小島上。', `FemaleText_loc7`='Encontrarás al Viejo Umbehto en la pequeña isla al este del edificio central de valle.' WHERE `ID`=45443;
