UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후주와 센토가 도와줄 수 있겠군요.$B$B골짜기 가운데에 있는 건물로 가서 만나보십시오.', `MaleText_loc4`='Huju和克森图能帮上你的忙。$B$B去山谷的中央建筑里找他们吧，伙计。', `MaleText_loc5`='胡鳩和克森圖有你要的東西。$B$B他們就在精神谷中央建築裡面，老兄。', `MaleText_loc7`='Huju y Xen''to pueden encah''gah''se.$b$bLos encontrarás en el edificio central del valle, colega.', `FemaleText_loc1`='후주와 센토가 도와줄 수 있겠군요.$B$B골짜기 가운데에 있는 건물로 가서 만나보십시오.', `FemaleText_loc4`='Huju和克森图能帮上你的忙。$B$B去山谷的中央建筑里找他们吧，伙计。', `FemaleText_loc5`='胡鳩和克森圖有你要的東西。$B$B他們就在精神谷中央建築裡面，老兄。', `FemaleText_loc7`='Huju y Xen''to pueden encah''gah''se.$b$bLos encontrarás en el edificio central del valle, colega.' WHERE `ID`=45448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무릎을 꿇어라, 얼라이언스여! 포세이큰의 강대함 앞에 무릎을 꿇으란 말이다!', `FemaleText_loc4`='跪倒吧，联盟！在被遗忘者强大的力量之前跪倒吧！', `FemaleText_loc5`='跪倒吧，聯盟!跪倒在強大的被遺忘者面前!', `FemaleText_loc7`='¡Arrodíllate, Alianza! ¡Arrodíllate ante la fuerza de los Renegados!' WHERE `ID`=45449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳건히 버티세요, $c님. 이건 당신을 위한 조치입니다.', `MaleText_loc4`='紧紧抓住，$c。这样你才能保护好自己。', `MaleText_loc5`='堅持到底，$c。這是為了保護你自己。', `MaleText_loc7`='Agárrate fuerte, $c. Es por tu propia seguridad.' WHERE `ID`=45451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 공동의 적인 그림토템 부족과 싸우는 높새바람 봉우리의 타우렌을 도우러 드루이드와 파수꾼으로 구성된 소규모 부대가 왔습니다.', `MaleText_loc4`='我们的一些德鲁伊和斥候组成了一支小队伍，前来援助乱风岗的牛头人，对抗我们共同的敌人：恐怖图腾部族。', `MaleText_loc5`='一小群的我們、德魯伊，還有哨兵，一起前來協助亂風崗的牛頭人對抗我們共同的敵人:恐怖圖騰部族。', `MaleText_loc7`='Un pequeño grupo de druidas y centinelas hemos venido para ayudar a los tauren del Poblado Viento Libre contra nuestro enemigo común: el clan Tótem Siniestro.' WHERE `ID`=45452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽 첨탑이 심하게 손상되었습니다!', `MaleText_loc4`='东部尖塔受到了重创！', `MaleText_loc5`='東部尖塔受到嚴重的破壞了!', `MaleText_loc7`='¡El Fortín del Este ha sufrido grandes daños!' WHERE `ID`=45453;
