UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산티쉬와 뱀은 골짜기 가운데에 있는 건물 주변을 슬금슬금 돌아다닙니다.', `MaleText_loc4`='克萨迪斯和他的蛇群就在这座山谷的中心建筑周围游荡，朋友。', `MaleText_loc5`='克薩迪斯跟他的蛇就在精神谷中間那棟房子裡面爬來爬去，老兄。', `MaleText_loc7`='Xan''tish y sus serpientes andan arrah''trándose po'' los alrede''ores del edificio central del valle, colega.', `FemaleText_loc1`='산티쉬와 뱀은 골짜기 가운데에 있는 건물 주변을 슬금슬금 돌아다닙니다.', `FemaleText_loc4`='克萨迪斯和他的蛇群就在这座山谷的中心建筑周围游荡，朋友。', `FemaleText_loc5`='克薩迪斯跟他的蛇就在精神谷中間那棟房子裡面爬來爬去，老兄。', `FemaleText_loc7`='Xan''tish y sus serpientes andan arrah''trándose po'' los alrede''ores del edificio central del valle, colega.' WHERE `ID`=45455;
