UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림토템 부족 놈들은 물이 밀려들어 오자마자 우릴 공격했습니다! 마치 이 일을 예상했다는 듯이 말이죠.$b$b놈들은 자신의 악행에 대한 응징을 받게 될 것입니다.', `FemaleText_loc4`='当大水涌入的时候，他们对我们发动了攻击！就好象他们早已知道了那场洪水的爆发。$B$B他们要为他们犯下的罪行付出代价。', `FemaleText_loc5`='水一沖進來，他們就對我們發動了攻擊!好像早就知道了會發生什麼事情。$B$B他們一定要為他們幹的事情付出代價。', `FemaleText_loc7`='¡Nos atacaron cuando entraron las aguas! Fue como si ya supieran que iba a pasar.$b$bTodos deberían sufrir por lo que han hecho.' WHERE `ID`=45460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너 또한 나를 섬기리라!', `FemaleText_loc4`='你也将侍奉我！', `FemaleText_loc5`='你也一樣必須臣服!', `FemaleText_loc7`='¡Tú también servirás!' WHERE `ID`=45461;
