UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다, $n. 날 바짝 따라오시오.', `MaleText_loc4`='我们行动，$n。尽量靠近我。', `MaleText_loc5`='走吧，$n。跟緊一點。', `MaleText_loc7`='Vamos, $n. No te alejes.' WHERE `ID`=45475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오. 여기선 뭘 만나게 될지 아무도 모르니까...', `MaleText_loc4`='保持警惕，$n。谁也不知道我们在这里会碰到什么……', `MaleText_loc5`='保持警覺。無法預料會在下面這邊碰到什麼...', `MaleText_loc7`='Mantente alerta. No hay forma de saber con qué nos podemos encontrar aquí abajo...' WHERE `ID`=45476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 재료가 필요하다면 내게 오시오. 좋은 재료를 많이 가지고 있소이다.', `MaleText_loc4`='如果你需要材料，尽可以在我这里挑选。', `MaleText_loc5`='你需要藥材的話，我有齊全的貨色供你選擇。', `MaleText_loc7`='Si necesitas componentes, tengo una selección completa a tu disposición.' WHERE `ID`=45477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 훈련을 받을 수 없습니다.', `MaleText_loc4`='我不能训练你，朋友。', `MaleText_loc5`='我無法提供你訓練，朋友。', `MaleText_loc7`='No puedo ofrecerte ningún entrenamiento, $gamigo:amiga;.', `FemaleText_loc1`='당신은 훈련을 받을 수 없습니다.', `FemaleText_loc4`='我不能训练你，朋友。', `FemaleText_loc5`='我無法提供你訓練，朋友。', `FemaleText_loc7`='No pue''o ofreceh''te inh''trucción, colega.' WHERE `ID`=45478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달숲에 오신 $c님을 환영합니다. 이곳의 신성한 평화만 깨지 않으신다면, 누구든 환영입니다.', `MaleText_loc4`='欢迎来到月光林地，$c。这里的大门对所有愿意坚守神圣和平的人敞开着。', `MaleText_loc5`='歡迎到月光林地，$c。這裡歡迎所有的人，只要你能尊重此地的寧靜祥和。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Claro de la Luna, $c. Todos son bienvenidos aquí, siempre que respeten la paz sagrada.', `FemaleText_loc1`='달숲에 오신 $c님을 환영합니다. 이곳의 신성한 평화만 깨지 않으신다면, 누구든 환영입니다.', `FemaleText_loc4`='欢迎来到月光林地，$c。这里的大门对所有愿意坚守神圣和平的人敞开着。', `FemaleText_loc5`='歡迎到月光林地，$c。這裡歡迎所有的人，只要你能尊重此地的寧靜祥和。', `FemaleText_loc7`='Te doy la bienvenida a Claro de la Luna, $c. Todos son bienvenidos aquí siempre y cuando respeten la paz sagrada.' WHERE `ID`=45479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네가 원한다면, 기술 훈련뿐만 아니라 내게는 자네 마음속으로부터 특성을 지울 수 있는 능력이 있다네. 하지만 이 절차를 거칠 때마다 다시 반복하기는 더 어려워진다는 사실을 염두에 두게. 따라서 점점 더 큰 비용을 치러야 하지.', `FemaleText_loc4`='要是你愿意的话，除了训练之外，我还可以用自己的力量将天赋从你的头脑中抹去。我要警告你的是，你每经历一次这样的过程，执行这过程的难度就会增加一分，而且所需的费用也会随之上升。', `FemaleText_loc5`='要是你願意的話，除了訓練之外，我還可以用自己的力量將天賦從你的頭腦中抹去。我要警告你的是，你每經歷一次這樣的過程，執行這過程的難度就會增加一分，因此所需的費用也會隨之上升。', `FemaleText_loc7`='Si lo deseas, además de la instrucción, tengo el poder de borrar el conocimiento de tus talentos de tu mente. Te advierto que cada vez que realizas este proceso es más difícil y, por lo tanto, es más caro.' WHERE `ID`=45480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 드디어... 풀려났다!', `MaleText_loc4`='我自由了。', `MaleText_loc5`='我。已。降。世。', `MaleText_loc7`='SOY. LIBRE.' WHERE `ID`=45481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람 속의 모래 알갱이 같은 놈.', `MaleText_loc4`='不过是风尘中的沙土。', `MaleText_loc5`='你不過是風中的塵埃。', `MaleText_loc7`='Sólo son polvo en el viento.' WHERE `ID`=45482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남국의 바람이여, 불어라! 와서 네 주인을 도와라!', `MaleText_loc4`='呼啸的南风，助你的主人一臂之力吧！', `MaleText_loc5`='南方之風，來協助你的主人!', `MaleText_loc7`='¡Vientos del sur, vengan en ayuda de su amo!' WHERE `ID`=45483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이... 나를 부르는구나...', `MaleText_loc4`='天空……在召唤……', `MaleText_loc5`='天空...正在招手...', `MaleText_loc7`='El cielo... llama...' WHERE `ID`=45484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍을 맞이해라!', `MaleText_loc4`='承受这场风暴！', `MaleText_loc5`='嚐嚐風暴的厲害吧!', `MaleText_loc7`='¡Sufran la tormenta!' WHERE `ID`=45485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 도시는 파묻히고, 자연이 너희 목숨을 취하리라!', `MaleText_loc4`='你们的城市将被埋葬，你们的生命将归于元素！', `MaleText_loc5`='你們的城市將被掩埋，你們的生命將被元素奪取!', `MaleText_loc7`='¡Enterraré su ciudad, los elementos tomarán sus vidas!' WHERE `ID`=45486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘몰아치는 폭풍 앞에 몸서리쳐라!', `MaleText_loc4`='在风暴中颤抖吧！', `MaleText_loc5`='在風暴中顫抖吧!', `MaleText_loc7`='¡Témanle a la tempestad!' WHERE `ID`=45487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 견본에 대해 알아보려면 시간이 좀 더 필요합니다, $n. 분석이 끝나면 제가 다시 말씀드리겠습니다.', `MaleText_loc4`='我需要一些时间来研究这些样品，$n。等我完成了分析，我会再和你谈谈。', `MaleText_loc5`='我需要一些時間來研究這些樣本，$n。等我分析完成之後，我會再找你談談。', `MaleText_loc7`='Necesitaré algo de tiempo para estudiar estas muestras, $n. Hablaré contigo cuando haya completado mi análisis.' WHERE `ID`=45488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 전쟁에서 이기고 있소, $n. 농부들이 계속해서 포세이큰의 측면을 압박하면 곧 놈들을 제압할 수 있을 것이오.', `MaleText_loc4`='$n，我们赢得了这场战斗。只要那些农夫还在被遗忘者的侧翼位置大杀大砍，我们就一定能击溃他们。', `MaleText_loc5`='我們就快要打贏這一仗了，$n。只要那些農夫們繼續騷擾被遺忘者的側翼，我們就會擊敗他們。', `MaleText_loc7`='Estamos ganando esta batalla, $n. Si esos granjeros siguen diezmando los flancos de los Renegados, los superaremos.' WHERE `ID`=45489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말이 너무 앞섰군, $n. 당신이 도와주고 있는데도 우리 병사들에게 상황이 조금 암울하게 돌아가고 있소.', `MaleText_loc4`='我有些言之过早了，$n。虽然有你的支援，但我们的部队似乎还是陷入了困境。', `MaleText_loc5`='我話講得太快了，$n。即使有了你的支援，我們部隊在此地的前景依然不太樂觀。', `MaleText_loc7`='He hablado antes de tiempo, $n. Incluso con tu apoyo la cosa no pinta bien para nuestras tropas.' WHERE `ID`=45490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들은 몰라도 농부들에게 맞서 싸울 계획은 세우지 못했습니다. 이 농부들이 우리 측면을 물고 늘어지는 중이라 안돌할을 점령하는 임무가 더뎌지고 있습니다.', `MaleText_loc4`='我还没有计划要同时与士兵和农夫作战。如果这些农夫继续骚扰我们的侧翼，我们将有可能无法集中力量完成我们的任务：攻占安多哈尔。', `MaleText_loc5`='我沒有料想到必須跟士兵作戰的同時，還有農夫要打。如果繼續放任這些農夫騷擾我們的側翼，我們就有可能會失焦於眼前的首要任務:攻佔安多哈爾。', `MaleText_loc7`='No tenía previsto luchar contra soldados y granjeros a la vez. Con esos granjeros reduciendo nuestros flancos corremos el riesgo de perder de vista la misión: tomar Andorhal.' WHERE `ID`=45491;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 방식으로 전쟁에서 이기다니! 누군가가 저 죽음의 기사에게 군사 전략을 좀 가르쳐줘야겠구나.', `FemaleText_loc4`='这就是你们赢得战争的方法！真应该有人教导一下那个死亡骑士该如何运用军事策略。', `FemaleText_loc5`='對嘛，這樣才能打勝仗!總得有人教一下那個死亡騎士什麼才叫軍事策略。', `FemaleText_loc7`='¡Así se gana una guerra! Alguien debería enseñarle algo de estrategia militar a ese caballero de la Muerte.' WHERE `ID`=45492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이시누 알라, $c님. 행운이 그대와 함께하길.', `FemaleText_loc4`='向你致敬，$c。愿好运伴随你。', `FemaleText_loc5`='(達納蘇斯語)祝你好運，$c。', `FemaleText_loc7`='Ishnu-alah, $c. Que la fortuna te sonría.' WHERE `ID`=45493;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 다시 뵙겠습니다. 야만스러운 그림토템 부족에게 명예가 무엇인지 보여줍시다.', `FemaleText_loc4`='我很快就会与你汇合。我们要让那些恐怖图腾的野人明白，什么是光荣。', `FemaleText_loc5`='我很快就會重新加入你。我們要教恐怖圖騰這些野蠻的傢伙瞭解何謂榮譽的意義。', `FemaleText_loc7`='Pronto me reuniré contigo. Les enseñaremos el significado del honor a esos salvajes Tótem Siniestro.' WHERE `ID`=45494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건... 혹시 발키르?', `MaleText_loc4`='那是一个……瓦格里吗？', `MaleText_loc5`='那是個...華爾琪嗎?', `MaleText_loc7`='¿Eso es... una Val''kyr?' WHERE `ID`=45495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네치 오와치, $c님. 반갑습니다, 그리고 감사합니다.', `MaleText_loc4`='Nechi owachi，$c。向你致敬并表示感谢。', `MaleText_loc5`='嗨，$c。謝謝你。', `MaleText_loc7`='Nechi owachi, $c. Hola y gracias.' WHERE `ID`=45496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 다시 뵙겠습니다. 함께 그림토템 부족 겁쟁이들에게 공포의 의미를 가르쳐줍시다!', `MaleText_loc4`='我很快就会与你汇合，我们要让那些恐怖图腾的懦夫明白什么是恐惧。', `MaleText_loc5`='我很快就會重新加入你。我們一起讓恐怖圖騰這些懦夫知道什麼叫做恐懼!', `MaleText_loc7`='Pronto me reuniré contigo. ¡Juntos enseñaremos el significado del miedo a esos cobardes Tótem Siniestro!' WHERE `ID`=45498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌이 그랬단 말입니다! 우리가 일을 잘 처리하면 제게 치유술을 가르쳐주겠다고 말이죠! 자, 가시죠!', `MaleText_loc4`='那个牛头人告诉我，如果我干得好，她就会教我治疗的技艺！我们开始吧，朋友！', `MaleText_loc5`='牛頭人說只要我們把事情做好，她就會教我如何進行醫療!走吧，老兄!', `MaleText_loc7`='¡La tauren dice que me enseñará a sanar si hacemos un buen trabajo! ¡Vamos, colega!' WHERE `ID`=45499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광산 안에 들어가지 마십시오!', `MaleText_loc4`='不要走进那里！', `MaleText_loc5`='不要進去那裡面!', `MaleText_loc7`='¡No vayas por ahí!', `FemaleText_loc1`='광산 안에 들어가지 마세요!', `FemaleText_loc4`='不要走进那里！', `FemaleText_loc5`='不要進去那裡面!', `FemaleText_loc7`='¡No vayas por ahí!' WHERE `ID`=45500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까.', `MaleText_loc4`='你好啊。', `MaleText_loc5`='你好。', `MaleText_loc7`='Buenos días.', `FemaleText_loc1`='안녕하세요.', `FemaleText_loc4`='你好啊。', `FemaleText_loc5`='你好。', `FemaleText_loc7`='Buenos días.' WHERE `ID`=45501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에... 뭐지? 누구야? 대체 무슨 일이죠?', `MaleText_loc4`='嗯……什么？谁？出什么事了？', `MaleText_loc5`='呃 - 什麼?是誰?到底發生了什麼事情?', `MaleText_loc7`='Eh... ¿Qué? ¿Quién? ¿Qué está pasando?' WHERE `ID`=45502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소, $n. 당신이 찾아온 막대가 뭘 보여줄지 한 번 봅시다.', `MaleText_loc4`='好的，$n。让我们看看你到底有怎样的能力。', `MaleText_loc5`='好吧，$n。該是看看你這根法杖能告訴我們些什麼的時候了。', `MaleText_loc7`='Muy bien, $n. A ver qué nos dice este bastón tuyo.' WHERE `ID`=45503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 이제 차원문을 통해 돌아가야 하네. 오그리마에서 처리해야 할 일이 많으니.', `MaleText_loc4`='Lok''tar！现在就让我们从刚才我们通过的那道传送门回去吧……在奥格瑞玛还有许多工作在等着我。', `MaleText_loc5`='勝利!讓我們從原本的傳送門回去吧!奧格瑪還有很多的事情在等我處理。', `MaleText_loc7`='¡Lok''tar! Regresemos por ese portal que dejamos atrás... Me espera mucho trabajo en Orgrimmar.' WHERE `ID`=45504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 수고했네. 이 괴물을 통과시켜 보내려 했던 차원문을 통해 돌아갑시다! 썬더 블러프에서 내가 처리해야 할 일이 많으니.', `MaleText_loc4`='干得好，英雄们。这个传送门本来是为这怪物准备的，现在就让我们通过它回去吧！在雷霆崖还有许多工作在等着我。', `MaleText_loc5`='做得好，英雄們。讓我們使用原本要讓這怪物穿過的傳送門回去吧!雷霆崖還有很多的事情在等我處理。', `MaleText_loc7`='Bien hecho, héroes. ¡Regresemos por el mismo portal por el que querían enviar a esta bestia! Me espera mucho trabajo en Cima del Trueno.' WHERE `ID`=45505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수고했네, 영웅들. 이제 차원문을 통해 돌아갈 시간이네... 아이언포지에서 처리해야 할 일이 많으니.', `MaleText_loc4`='干得好，英雄们。现在就让我们从刚才我们通过的那道传送门回去吧……在铁炉堡还有许多工作在等着我。', `MaleText_loc5`='做得好，英雄們。讓我們使用原本的傳送門回去吧!鐵爐堡還有很多的事情在等我處理。', `MaleText_loc7`='Bien hecho, héroes. Regresemos por ese portal que dejamos atrás... Me espera mucho trabajo en Forjaz.' WHERE `ID`=45506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련 중', `MaleText_loc4`='训练', `MaleText_loc5`='訓練', `MaleText_loc7`='Instrucción', `FemaleText_loc1`='훈련 중', `FemaleText_loc4`='训练', `FemaleText_loc5`='訓練', `FemaleText_loc7`='Instrucción' WHERE `ID`=45509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<폭발하기 전까지는 믿을 수 있는 성능!>$B$B<전문 기술을 배우고 싶거나 자동판매기를 이용하시려면 돈을 넣으십시오.>', `MaleText_loc4`='<在爆炸前，质量均可保证！>$B$B<塞入钱款，即可得到专业训练和售卖服务。>', `MaleText_loc5`='<爆炸壞掉之前都誠信可靠的品質!>$B$B<如欲使用專業技能訓練及販售服務，請插入紙鈔。>', `MaleText_loc7`='<¡Calidad digna de confianza hasta que termine el explosivo!>$b$b<Insertar pasta para recibir instrucción de profesiones y servicios de venta.>' WHERE `ID`=45510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심연에서... 나와 함께하라.', `FemaleText_loc4`='和我……共赴深渊吧。', `FemaleText_loc5`='和我一同...進入深淵。', `FemaleText_loc7`='Únete a mí... en las profundidades.' WHERE `ID`=45511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈을 내고 전문 기술 훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受主要专业技能的训练。', `MaleText_loc5`='我想要購買主要的專業技能訓練。', `MaleText_loc7`='Me gustaría comprar instrucción de profesión primaria.', `FemaleText_loc1`='돈을 내고 전문 기술 훈련을 받고 싶어요.', `FemaleText_loc4`='我要接受主要专业技能的训练。', `FemaleText_loc5`='我想要購買主要的專業技能訓練。', `FemaleText_loc7`='Me gustaría comprar instrucción de profesión primaria.' WHERE `ID`=45512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 기술 자동 판매기 접속', `MaleText_loc4`='使用专业售卖机', `MaleText_loc5`='操作專業技能自動販賣機。', `MaleText_loc7`='Acceder a la máquina expendedora de profesiones', `FemaleText_loc1`='전문 기술 자동 판매기 접속', `FemaleText_loc4`='使用专业售卖机', `FemaleText_loc5`='操作專業技能自動販賣機。', `FemaleText_loc7`='Acceder a la máquina expendedora de profesiones' WHERE `ID`=45513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하시면 여기서 휴식을 취하셔도 됩니다. 대지의 사원은 이제 안전합니다.', `MaleText_loc4`='如果你愿意，可以在这里休息。现在大地神殿由我们管理。', `MaleText_loc5`='想要的話，你可以在這裡休息。如今大地神殿是在我們的照管之下。', `MaleText_loc7`='Si lo deseas, puedes descansar aquí. Ahora el Templo de la Tierra está bajo nuestra supervisión.' WHERE `ID`=45514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적절한 기술을 사용하면 못 고칠 게 없어요, $n 님. 물론 오작동, 합선, 비협조적인 환자 등등 일을 더욱 재미있게 만드는 상황은 언제나 발생하기 마련이죠.', `FemaleText_loc4`='有了适合的技术，你能修好任何东西，$n。当然，我总会会遇到各种故障、短路和不配合的病人。它们为我带来了不少乐趣。', `FemaleText_loc5`='只要有恰當的科技，什麼東西都能修得好，$n。當然啦，隨時還是會有什麼故障的、短路的，還有不合作的顧客來讓事情保持新鮮。', `FemaleText_loc7`='Con la tecnología adecuada se puede arreglar cualquier cosa, $n. Claro que siempre hay disfunciones, cortocircuitos y pacientes que se niegan a cooperar, para darle vida al asunto.' WHERE `ID`=45515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간들링은 강력합니다. 하지만 걱정하지 마십시오. 당신이 그자와 싸우기 시작하면 바로 제가 합류하겠습니다.', `MaleText_loc4`='加丁是强大的。但不必担心。当你和他的战斗展开之后，我就会来支援你。', `MaleText_loc5`='加丁確實是很厲害，但是不必擔心，你們一跟他開戰我就會隨後加入戰局。', `MaleText_loc7`='Gandling es fuerte, pero no te preocupes. Me uniré a ti poco después de que empieces a luchar con él.' WHERE `ID`=45516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='높새바람 봉우리 타우렌을 지원하고 그림토템 부족을 몰아내려면 할 일이 너무나 많지만 우리에게 주어진 시간은 너무나 짧군요.$b$b토르 일리사르데라날! 적들이여 각오하라!', `FemaleText_loc4`='为了支援乱风岗的牛头人，击退恐怖图腾部族，我们有许多事情要做，却没有多少时间。$B$BTor ilisar''thera''nal！让我们的敌人知道恐惧！', `FemaleText_loc5`='如果要協助亂風崗的牛頭人擊退恐怖圖騰部族，我們該做的事情還很多，可是時間卻很少。$B$B(達納蘇斯語)讓我們的敵人聞風喪膽!', `FemaleText_loc7`='Si queremos ayudar a los tauren del Poblado Viento Libre y rechazar a los Tótem Siniestro, tenemos mucho por hacer y muy poco tiempo para hacerlo.$b$b¡Tor ilisar''thera''nal! ¡Que tiemblen nuestros enemigos!' WHERE `ID`=45517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림토템 부족의 공격을 받아주는 것도 이번이 마지막입니다. 놈들이 잘못을 뉘우칠 줄 모르니 짐승 다루듯 처치해야겠지요.$b$b대지모신이시여, 우릴 용서하소서...', `MaleText_loc4`='这是恐怖图腾最后一次向我们发动进攻了。既然他们不可能明白自己的错误，我们就要像消灭野兽一样摧毁他们。$B$B愿大地母亲原谅我们。', `MaleText_loc5`='這將會是恐怖圖騰對我們的最後一次攻擊了。既然我們無法教會他們認清他們的錯誤方式，那我們也只好把他們當成野獸般消滅掉。$B$B願大地之母原諒我們。', `MaleText_loc7`='Es la última vez que los Tótem Siniestro nos atacan. Ya que no quieren aprender de sus errores, los destruiremos como a bestias.$b$bQue la Madre Tierra nos perdone.' WHERE `ID`=45518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령의 정기를 한 병 더 주시겠습니까?', `MaleText_loc4`='可以再给我一瓶元素灵契吗？', `MaleText_loc5`='可以再給我一瓶元素靈契嗎?', `MaleText_loc7`='¿Me puedes dar otro vial de sapta elemental?', `FemaleText_loc1`='정령의 정기를 한 병 더 주실 수 있나요?', `FemaleText_loc4`='可以再给我一瓶元素灵契吗？', `FemaleText_loc5`='可以再給我一瓶元素靈契嗎?', `FemaleText_loc7`='¿Me puedes dar otro vial de sapta elemental?' WHERE `ID`=45519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화 토템을 하나 더 주시겠습니까?', `MaleText_loc4`='可以再给我一个净化图腾吗？', `MaleText_loc5`='可以再給我一個淨化圖騰嗎?', `MaleText_loc7`='¿Me puedes dar otro tótem de limpieza?', `FemaleText_loc1`='정화 토템을 하나 더 주시겠어요?', `FemaleText_loc4`='可以再给我一个净化图腾吗？', `FemaleText_loc5`='可以再給我一個淨化圖騰嗎?', `FemaleText_loc7`='¿Me puedes dar otro tótem de limpieza?' WHERE `ID`=45520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신을 내려다보는 바위 어머니의 시선이 강렬합니다. 마치 당신의 영혼을 꿰뚫어 보는 것 같습니다.>$B$B나의 딸 테라드라스는 연인 재타르를 잃은 슬픔에 테라모크의 수정 동굴 속에 몸을 숨겼다. 하지만 바위도 눈물도 없는 존재들이 동굴로 쳐들어와 슬픔에 빠진 내 딸을 무참히 살해했지.$B$B그날, 내가 육체의 저주에 걸린 존재를 신뢰해야 할 이유도 함께 사라졌다. 그런데도 아직도 넌 뻔뻔하게 잘 버티고 있군.$B$B언젠가 너의 능력이 쓸모없어지는 날이 올 것이다.', `FemaleText_loc4`='<石母凝视着你。她的目光仿佛穿过你的肉体，正在望着你的灵魂。>$B$B我的女儿——瑟莱德丝，将自己隔绝在泰拉莫克水晶洞穴深处，终日为挚爱扎尔塔的离去而心伤。就在那里，突然闯进了一群没心没肺的畜生，将正沉浸在哀思之中的她杀死。$B$B要是有任何理由能让我对长着血肉之躯的凡人心存信任，这理由也已在那天消逝。而在你傲慢的态度里，我看到了坚持。$B$B总有一天，你也会变得毫无用处。', `FemaleText_loc5`='<石母低頭盯著你，望穿了你，彷彿直接凝視著你的靈魂深處。>$B$B我的女兒瑟萊德絲，離群索居獨自在泰拉莫克水晶洞穴裡哀悼她所失去的至愛札爾塔，結果卻不幸慘遭既無石又無心的入侵者殺害。$B$B就算我曾經有任何該信任受到血肉詛咒之生物的理由，自那天之後便全部徹底消失了。然而，你這狂傲自大的東西竟然還是厚顏無恥地來找我了。$B$B終有一日，你會再無利用價值。', `FemaleText_loc7`='<La Madre Pétrea te mira. Mira a través de ti. Como si estuviera escrutando tu alma.>$B$BMi hija, Theradras, se aisló en las profundidades de las Cavernas de Cristal de Terramok para llorar a su amor perdido, Zaetar. Allí, seres sin corazón ni piedra la atacaron y la destrozaron mientras estaba inmersa en su pesar.$B$BSi alguna vez he tenido razones para confiar en una criatura afligida por la maldición de la carne, aquel día las perdí todas. Y, sin embargo, en tu arrogancia, persistes.$B$BAlgún día, sobrevivirás a tu utilidad.' WHERE `ID`=45521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 부름을 받고 왔습니다,바위 어머니시여.', `MaleText_loc4`='我听从你的召唤而来，石母。', `MaleText_loc5`='我依你的召喚而來了，石母。', `MaleText_loc7`='Respondo a tu llamada, Madre Pétrea.', `FemaleText_loc1`='당신의 부름을 받고 왔습니다,바위 어머니시여.', `FemaleText_loc4`='我听从你的召唤而来，石母。', `FemaleText_loc5`='我依你的召喚而來了，石母。', `FemaleText_loc7`='Respondo a tu llamada, Madre Pétrea.' WHERE `ID`=45522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 황혼 해안의 상륙 거점을 차지했습니다.', `MaleText_loc4`='联盟控制了暮光海岸的滩头阵地。', `MaleText_loc5`='聯盟現在已經控制了暮光海岸灘頭。', `MaleText_loc7`='La Alianza se ha hecho con el control de la cabeza de playa de las Orillas Crepusculares.' WHERE `ID`=45523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 황혼 해안의 상륙 거점을 차지했습니다.', `MaleText_loc4`='部落控制了暮光海岸的滩头阵地。', `MaleText_loc5`='部落現在已經控制了暮光海岸灘頭。', `MaleText_loc7`='La Horda se ha hecho con el control de la cabeza de playa de las Orillas Crepusculares.' WHERE `ID`=45524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마라. 떨어뜨리지 않겠다.', `FemaleText_loc4`='不必害怕。我不会让你掉下去的。', `FemaleText_loc5`='不必害怕，我不會讓你摔落。', `FemaleText_loc7`='No temas. No te dejaré caer.' WHERE `ID`=45525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 톨 바라드 밖에서 작동하도록 허가되지 않은 차량입니다. 즉시 돌아가십시오.', `MaleText_loc4`='警告：此交通工具不可在托尔巴拉德以外使用。现在返回。', `MaleText_loc5`='警告:這台載具並未獲得在托巴拉德以外地區的操作許可。請立刻返回。', `MaleText_loc7`='Atención: No está permitido operar este vehículo fuera de Tol Barad. Da la vuelta.' WHERE `ID`=45526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안한데 친구, 훈련은 다른 데서 알아보라고.', `MaleText_loc4`='抱歉，朋友。你只能去别的地方寻找训练机会了。', `MaleText_loc5`='抱歉，朋友，你得去別的地方接受訓練。', `MaleText_loc7`='Lo siento, $gamigo:amiga;. Tendrás que buscar instrucción en otra parte.' WHERE `ID`=45527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 기부하면, 사제의 도를 배울 수 있는데 말이야.', `MaleText_loc4`='只要一点捐赠，我就能教导你牧师的技艺。', `MaleText_loc5`='只要小額的奉獻，我可以訓練你牧師的相關技藝。', `MaleText_loc7`='Por una pequeña donación puedo instruirte en las artes del sacerdocio.' WHERE `ID`=45528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 너희 보물 못 가져간다!!!', `MaleText_loc4`='啊！不许拿走那宝物！！！', `MaleText_loc5`='呃啊!你不准拿走寶藏!!!', `MaleText_loc7`='¡Buaaaah! ¡Tú no llevarte tesoro!' WHERE `ID`=45529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끼야아아!!!', `MaleText_loc4`='啊！！！', `MaleText_loc5`='咕哇哇哇哇哇!!!', `MaleText_loc7`='¡Gaaaaaaah!' WHERE `ID`=45530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요, $c|1이여;여;?', `FemaleText_loc4`='我能帮你些什么，$c？', `FemaleText_loc5`='有什麼我能幫忙的嗎，$c?', `FemaleText_loc7`='¿Puedo ayudarte, $c?' WHERE `ID`=45531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품 좀 있습니까?', `MaleText_loc4`='你这儿有什么补给品吗？', `MaleText_loc5`='你有賣任何補給品嗎?', `MaleText_loc7`='¿Tienes suministros?', `FemaleText_loc1`='보급품 좀 있습니까?', `FemaleText_loc4`='你这儿有什么补给品吗？', `FemaleText_loc5`='你有賣任何補給品嗎?', `FemaleText_loc7`='¿Tienes suministros?' WHERE `ID`=45532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 수리해 주실 수 있습니까?', `MaleText_loc4`='你能修理设备吗？', `MaleText_loc5`='你會修理裝備嗎?', `MaleText_loc7`='¿Puedes reparar equipo?', `FemaleText_loc1`='장비를 수리해 주실 수 있습니까?', `FemaleText_loc4`='你能修理设备吗？', `FemaleText_loc5`='你會修理裝備嗎?', `FemaleText_loc7`='¿Puedes reparar equipo?' WHERE `ID`=45533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 못 해요. 하지만 저기 있는 대지치유사 도로스와 이야기해 보세요. 폐허가 된 황혼의 야영지를 살펴보는 저 덩치 큰 드레나이 보이시죠?', `FemaleText_loc4`='嗯，你可以和那边的大地治愈者多罗斯谈谈……就是那名大个子的德莱尼。你可以在暮光营地的左侧找到他。', `FemaleText_loc5`='不會。但是你可以跟那邊的癒地者多洛斯談談...在看著暮光營地殘骸的那個大塊頭的德萊尼。', `FemaleText_loc7`='No, pero puedes hablar con el ensalmador de la tierra Doros... Ese draenei tan grande ahí, el que observa los restos del campamento Crepuscular.' WHERE `ID`=45534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 야영지에 온전한 것이라곤 거의 남지 않았습니다. 그래도 우리가 사용할만한 게 있을지도 모르죠.$B$B제게 원하는 게 있으십니까, $r|1이여;여;?', `MaleText_loc4`='他们的营地几乎被彻底摧毁了。不过我们还是从那片废墟中找到了一些可用的东西。$B$B你需要些什么，$r？', `MaleText_loc5`='雖然他們的營地已經沒多少完整的東西，但說不定還是有我們可以利用的東西。$B$B你來找我有事嗎，$r?', `MaleText_loc7`='Solo una pequeña parte de su campamento ha quedado intacta. Pero podría haber algo que nos sea de utilidad.$b$b¿Querías algo de mí, $r?' WHERE `ID`=45535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 드릴 수 있는 건 없습니다.$B$B하지만 헤그리드가 황혼의 보급품을 모아 아군에 지급하고 있습니다. 그녀와 이야기해 보십시오.', `MaleText_loc4`='我这里没有你要找的东西。$B$B不过赫格莉德正在收集暮光补给品，供我们自己使用。你也许应该找她谈一谈。', `MaleText_loc5`='我沒有東西可以給你。$B$B但是希格瑞德一直在收集暮光補給品來補充我們的庫存，或許你可以去找她談談。', `MaleText_loc7`='No puedo ayudarte.$b$bHegrid, por otra parte, ha estado reuniendo suministros Crepusculares para reforzar los nuestros. Puedes hablar con ella.' WHERE `ID`=45536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했소, 영웅들이여. 발나자르는 참으로 오랫동안 세상을 위협했지. 놈은 우리의 가장 큰 두 적, 스컬지와 붉은십자군 양쪽 다에 관련되어 있었소. 놈을 제때 처리하지 못했다면 되살아난 자들의 세력이 커져 이 전투에서 우리를 위협할 수도 있었지.', `MaleText_loc4`='干得好，英雄们。长久以来，巴纳扎尔一直都是我们的威胁。最让我们头痛的两个敌人——天灾军团和血色十字军的出现都与他有关。如果我们对他的复活放任不管，也许战争的天平会朝不利于我们的方向倾斜。', `MaleText_loc5`='幹得好啊，英雄們。巴納札爾這個威脅已經存在太久了，在天譴軍團和血色十字軍這兩個我們的死敵中他都有份。而且要是讓復活軍團有時間繼續腐化擴散的話，局勢或許還會對我們更加不利。', `MaleText_loc7`='Bien hecho, héroes. Hacía demasiado tiempo que Balnazzar era una amenaza. Movía hilos en la Plaga y en la Cruzada Escarlata, dos de nuestros mayores enemigos. Los Alzados podrían haber cambiado las tornas en nuestra contra, si hubieran tenido tiempo de prosperar.' WHERE `ID`=45537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도, 발나자르는 아직 죽지 않았소. 필멸의 세계에서 패배한 공포의 군주는 그저 뒤틀린 황천으로 돌아갈 뿐이오. 놈은 언젠가 다시 돌아올 거요. 어쩌면 자신의 형제인 바리마트라스, 데서록과 다시 힘을 합칠지도 모르고.', `MaleText_loc4`='巴纳扎尔并没有被真正消灭，这一点实在是让人感到懊丧。在物质位面击败一名恐惧魔王，只能让它返回到扭曲虚空中去。总有一天，他会回来，甚至有可能再度与他的兄弟瓦里玛萨斯和迪瑟洛克联手。', `MaleText_loc5`='可惜的是，巴納札爾並不算真正被消滅。在凡界擊敗驚懼領主只能將它趕回扭曲虛空而已。將來有一天他還會重返，說不定甚至會和他的惡魔弟兄瓦里瑪薩斯與戴瑟洛克重新合作。', `MaleText_loc7`='Por desgracia, aún no hemos acabado con Balnazzar. Matar a un Señor del Terror en el plano mortal no hace más que enviarlo de vuelta a El Vacío Abisal. Algún día volverá, quizá reunido con sus hermanos Varimathras y Detheroc.' WHERE `ID`=45538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단은 스트라솔름의 반을 점령했다는 사실에 만족해야 할 것이오. 은빛 성기사단의 옛 성채를 되찾은 셈이니까 말이오. 여기엔 은빛 성기사단의 수많은 보물이 있소. 또한, 이로써 우리는 다음 공격을 진행할 든든한 발판을 마련했소.', `MaleText_loc4`='到现在为止，我们已经恢复了对斯坦索姆这半边的控制，我们应该为此感到高兴。这座白银之手的堡垒终于回到了它的主人手中。这里有数不清的财富，而且我们现在还拥有了展开下一次进攻的坚固阵地。', `MaleText_loc5`='至於現在，我們已經奪回了斯坦索姆這半邊的掌控權，並且應當為此而喝采。白銀之手騎士團昔日的堡壘總算回歸到它真正的主人手裡。這裡面有騎士團數不清的寶藏，而且我們現在也有了個安全的根據地可以發動下一波的攻勢。', `MaleText_loc7`='Por ahora hemos recuperado el control de esta mitad de Stratholme, y deberíamos alegrarnos de ello. El antiguo Bastión de la Mano de Plata ha vuelto a manos de sus dueños legítimos. Aquí residen innumerables tesoros de la orden, y ahora tenemos una ubicación fortificada desde la que lanzar nuestro siguiente asalto.' WHERE `ID`=45539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 여기서 당신들의 역할이 중요하오, 영웅들이여. 스트라솔름 전투는 아직 끝나지 않았소. 이 지역을 떠나 동부방벽 관문으로 가시오. 그곳은 업무용으로 사용되던 스트라솔름 출입구요. 군주 아우리우스 리븐데어가 지배하는 스컬지 지역으로 통하는 입구는 거기 하나뿐이오. 놈을 무찌르면, 스트라솔름을 완전히 되찾을 수 있소.', `MaleText_loc4`='这里正需要你们，英雄们。斯坦索姆之战还没有结束。你们应该向东进发，前往东墙大门。那里是这座城市的出入口，也是能够进入瑞文戴尔男爵的天灾军团领地的唯一通道。如果我们能把他打败，斯坦索姆将再一次完全属于我们。', `MaleText_loc5`='英雄們，而這正是需要你們效力的地方。斯坦索姆之戰尚未結束。離開這塊區域，前往東邊的東牆大門。那是這座城的後門，也是通往天譴軍團的奧里爾斯·瑞文戴爾領主所佔據的區域的唯一入口。只要我們能打敗他，斯坦索姆就將再度回到我們的手中。', `MaleText_loc7`='Ahí entran ustedes, héroes. La guerra por Stratholme aún no ha acabado. Abandonen esta zona y viajen al este, hasta la Puerta de la Muralla del Este. Es la puerta de servicio de la ciudad, y la última apertura restante del dominio infestado por la Plaga de Lord Aurius Osahendido. Si lo derrotamos, Stratholme será nuestra una vez más.' WHERE `ID`=45540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알론서스 교회에서 다시 봅시다. 빛의 수호자 우서 경이 빛의 성기사단에 입단한 성스러운 장소라오. 그래서 스컬지도 그 건물은 건드릴 수 없지. 도시의 남은 반을 공격할 때 그곳을 우리의 작전 기지로 삼을 것이오. 당신들의 도움이 있다면, 스트라솔름은 성스러운 빛의 수도이자 로데론의 새로운 시작이 될 것이오.', `MaleText_loc4`='我会在阿隆索斯礼拜堂等你。那里是乌瑟尔·光明使者加入白银之手的地方。也是唯一一座天灾怪物们无法触碰的建筑物。那里将成为我们进攻另外一半城市时的桥头堡。有了你的帮助，斯坦索姆一定会成为圣光之都，洛丹伦新生的起点。', `MaleText_loc5`='我跟你在阿隆索斯教堂碰面，那裡是當年光明使者烏瑟加入騎士團的聖地，也是天譴軍團唯一無法碰觸破壞的建築。我們將利用它來作為斯坦索姆城另外一側的前線基地。希望在你的協助之下，斯坦索姆將成為聖光之都，成為羅德隆的嶄新起點。', `MaleText_loc7`='Me reuniré con ustedes en la Capilla de Alonsus. Es el lugar sagrado en el que Uther el Iluminado entró en la orden de la Mano de Plata. Es el único edifico que la Plaga no puede tocar, y será la base de operaciones de nuestra avanzada en esa mitad de la ciudad. Con su ayuda, Stratholme se convertirá en la capital de la Luz y en un nuevo comienzo para Lordaeron.' WHERE `ID`=45541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 파멸의 역병은 아무 쓸모가 없습니다.', `MaleText_loc4`='这种枯萎病是没用的。', `MaleText_loc5`='這個荒疫根本沒用。', `MaleText_loc7`='Este añublo es inútil.', `FemaleText_loc1`='이 파멸의 역병은 아무 쓸모가 없어요.', `FemaleText_loc4`='这种枯萎病是没用的。', `FemaleText_loc5`='這個荒疫根本沒用。', `FemaleText_loc7`='Este añublo es inútil.' WHERE `ID`=45542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 쓰레기를 누구한테 시험해본 겁니까? 멀록?', `MaleText_loc4`='他们是用什么测试这种废物的？鱼人？', `MaleText_loc5`='他們到底是用什麼來測這個垃圾的?魚人嗎?', `MaleText_loc7`='¿En qué han probado esta basura? ¿En múrlocs?', `FemaleText_loc1`='이 쓰레기를 누구한테 시험해본 거죠? 멀록?', `FemaleText_loc4`='他们是用什么测试这种废物的？鱼人？', `FemaleText_loc5`='他們到底是用什麼來測這個垃圾的?魚人嗎?', `FemaleText_loc7`='¿En qué han probado esta basura? ¿En múrlocs?' WHERE `ID`=45543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아아아!!! 오우가 너희 악어한테 먹인다!!!', `MaleText_loc4`='啊呀！！！把你喂鳄鱼！！！', `MaleText_loc5`='嗚哇!!!奧各要抓你餵鱷魚!', `MaleText_loc7`='¡¡¡Bwagauugh!!! ¡¡¡Augh darte de comer a los crocoliscos!!!' WHERE `ID`=45544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 약해서 아무 짝에도 쓸모가 없습니다. 놈들 속도를 늦추지도 못한다니!', `MaleText_loc4`='没用的垃圾。甚至没办法让他们慢一点。', `MaleText_loc5`='摻水的廢物，連讓他們速度變慢也沒有。', `MaleText_loc7`='Es una porquería aguada. Ni siquiera los ralentiza.', `FemaleText_loc1`='너무 약해서 아무 쓸모도 없어요. 놈들 속도를 늦추지도 못한다니까요!', `FemaleText_loc4`='没用的垃圾。甚至没办法让他们慢一点。', `FemaleText_loc5`='摻水的廢物，連讓他們速度變慢也沒有。', `FemaleText_loc7`='Es una porquería aguada. Ni siquiera los ralentiza.' WHERE `ID`=45545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈의 "규제" 때문에 전쟁에 지게 생겼습니다. 이번엔 또 뭘 규제할까요? 나무로 된 칼만 써야 할까요???', `MaleText_loc4`='我们就要因为各种“规章”而输掉这场战争了。下一步又会怎样？难道我们只能挥挥木剑了吗？', `MaleText_loc5`='我們會因為這些「規定」而輸掉這一仗。接下來還有什麼?只能用木劍???', `MaleText_loc7`='Vamos a perder esta guerra con tanta "regulación". ¿Qué será lo siguiente? ¿Solo podremos luchar con espadas de madera?', `FemaleText_loc1`='그놈의 "규제" 때문에 전쟁에 지게 생겼어요. 이번엔 또 뭘 규제할까요? 나무로 된 칼만 써야 하려나요???', `FemaleText_loc4`='我们就要因为各种“规章”而输掉这场战争了。下一步又会怎样？难道我们只能挥挥木剑了吗？', `FemaleText_loc5`='我們會因為這些「規定」而輸掉這一仗。接下來還有什麼?只能用木劍???', `FemaleText_loc7`='Vamos a perder esta guerra con tanta "regulación". ¿Qué será lo siguiente? ¿Solo podremos luchar con espadas de madera?' WHERE `ID`=45546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 전쟁 중이잖습니까? 쓸 수 있는 무기를 모두 써서 적들을 처치하는 게 우리 임무 아닐까요?', `MaleText_loc4`='这是一场战争，对不对？我们应该用我们的武器消灭敌人，不是吗？', `MaleText_loc5`='這是一場戰爭，對吧?我們不是應該要能用我們的武器殺掉敵人嗎?', `MaleText_loc7`='Es una guerra, ¿no? Se supone que tenemos que poder matar al enemigo con nuestras armas, ¿no?', `FemaleText_loc1`='우린 지금 전쟁 중이잖아요? 쓸 수 있는 무기를 모두 써서 적들을 처치하는 게 우리 임무 아닌가요?', `FemaleText_loc4`='这是一场战争，对不对？我们应该用我们的武器消灭敌人，不是吗？', `FemaleText_loc5`='這是一場戰爭，對吧?我們不是應該要能用我們的武器殺掉敵人嗎?', `FemaleText_loc7`='Es una guerra, ¿no? Se supone que tenemos que poder matar al enemigo con nuestras armas, ¿no?' WHERE `ID`=45547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너를 두 동강 내 버릴 테다!', `FemaleText_loc4`='把你打倒一定是一件令人愉快的事！', `FemaleText_loc5`='能把你劈成兩半真是一件樂事!', `FemaleText_loc7`='¡Será un placer partirte por la mitad!' WHERE `ID`=45548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 누구야? 만신창이 겁쟁이와 간섭쟁이 외부인이잖아?', `FemaleText_loc4`='看看我们这里都有些什么人？一个被打败的懦夫和一个管闲事的外路人？', `FemaleText_loc5`='看看是誰來了?一個沒用的孬種和一個愛管閒事的外人?', `FemaleText_loc7`='¿Qué tenemos aquí? ¿Un cobarde vapuleado y $gun forastero entrometido:una forastera entrometida;?' WHERE `ID`=45549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧 그림토템 부족의 힘에 무릎 꿇게 될 것이다!', `FemaleText_loc4`='你们很快就会学会该如何拜倒在恐怖图腾的脚下！不过我却不一定会让你们活到那个时候。', `FemaleText_loc5`='你很快就會得知，最好趕緊向強大的恐怖圖騰臣服! ...如果我決定放你一命的話。', `FemaleText_loc7`='¡Pronto aprenderás a arrodillarte ante el poder de los Tótem Siniestro! Si te dejo vivir...' WHERE `ID`=45550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것 봐라, 네놈들에게도 자존심은 있다 이건가?', `FemaleText_loc4`='嗯，看样子你这种人还是有一点骨气的。', `FemaleText_loc5`='嘿嘿嘿，看來你們還是有點骨氣的。', `FemaleText_loc7`='Vaya, vaya, vaya. Parece que tenéis agallas después de todo.' WHERE `ID`=45551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='균열은 사라졌고 아이언포지는 안전하네! 이 차원문이 놈들의 두 번째 공격 수단이 분명하네.$b$b서두르게! 차원문으로 들어가게! 주도권을 잡았을 때 계속해서 공격해야 하네!', `MaleText_loc4`='裂隙已经被关闭，铁炉堡安全了！这些传送门一定与他们的下一步行动有关。$B$B赶快！进入传送门！我们必须乘胜追击！', `MaleText_loc5`='元素裂隙已經關閉，鐵爐堡安全了!這些傳送門必定是他們後半段的攻擊行動。$B$B動作快!進入傳送門!我們必須趁勝追擊!', `MaleText_loc7`='¡Las fallas han caído y Forjaz está a salvo! Los portales deben de ser la segunda mitad de su ataque.$B$B¡Rápido! ¡Al portal! ¡Debemos atacar ahora que llevamos ventaja!' WHERE `ID`=45552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨어진 걸 수집하는 것, 그게 나의 일이다.$B$B최근 거두어들일 게 많아졌다.', `MaleText_loc4`='别人丢下的东西，我都会收集起来。$B$B最近可是有不少东西需要收集。', `MaleText_loc5`='凡掉落者，我撿之。$B$B近日，有許多的東西可收集。', `MaleText_loc7`='Lo que se cae, yo lo recojo.$b$bÚltimamente ha habido muchas cosas por recuperar.' WHERE `ID`=45553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 할 수 없다. 난 오직 수집할 뿐이다.$B$B입딜이 널 도울 수 있을 것이다. 고치는 게 그의 전문이니까.', `MaleText_loc4`='我不能。我只负责收集。$B$B伊布迪尔应该能帮到你。他擅长修理。', `MaleText_loc5`='我不能。我只能收集。$B$B伊布迪爾或許可幫你。他的專長是治癒。', `MaleText_loc7`='No puedo. Yo me limito a recoger.$b$bEs posible que Ibdil pueda ayudarte. Su camino es el de ensalmador.' WHERE `ID`=45554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망가진 걸 고치는 것, 그게 나의 일이다.$B$B최근엔 너무 많은 것이 망가졌다. 너무나도 많은 것이.', `MaleText_loc4`='别人弄坏的东西，我都会修理好。$B$B最近可是有不少东西需要修理。实在是太多了。', `MaleText_loc5`='凡殘破者，我修之。$B$B近來，有許多的東西可修。非常多。', `MaleText_loc7`='Lo que se rompe, yo lo reparo.$b$bÚltimamente se han roto tantas cosas... Tantísimas cosas...' WHERE `ID`=45555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모가 선택한 자로군! 아직 눈치채지 못했나 보지? 먼저 너를 없애고 나서 네 친구도 없애주겠다!', `MaleText_loc4`='巫婆长老所选择的人！你还没意识到，是吗？我要先干掉你！还有你的朋友！', `MaleText_loc5`='長者欽點的人!你還不明白，對吧?我會先把你解決掉!你和你的朋友!', `MaleText_loc7`='¡$gElegido:Elegida; de la bruja anciana! Aún no te das cuenta, ¿verdad? ¡Acabaré contigo primero! ¡Contigo y con tu compinche!' WHERE `ID`=45557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마가타 님, 어째서 이방인을... 선택하셨습니까?', `MaleText_loc4`='她为什么会选择……一个外人？', `MaleText_loc5`='她為什麼會選上一位...外人?', `MaleText_loc7`='¿Por qué elegiría a $gun:una;... $gextraño:extraña;?' WHERE `ID`=45558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총 좀 더 쏠 수 없나요? 총알 날아가는 게 영 시원찮아 보입니다만...', `MaleText_loc4`='我们能再用大炮轰击一下吗？我觉得我们的炮火轰击还不够。', `MaleText_loc5`='我們可以再多開幾砲嗎?我覺得我們開的砲還是不夠多。', `MaleText_loc7`='¿Podemos disparar más cañones? Creo que no estamos disparando suficientes cañones.' WHERE `ID`=45559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그겁니다! 해변의 적을 모조리 쳐부수세요! 다 없어지고... 모래만 남게 말입니다.', `MaleText_loc4`='就是这样！轰平那片海滩！除了沙子，什么都不留。', `MaleText_loc5`='就是這樣!把海灘轟爛!除了沙子，什麼也不要剩下。', `MaleText_loc7`='¡Eso eso! ¡Pulveriza la playa! No dejes nada excepto... arena.' WHERE `ID`=45560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대를 계속 해변으로 보낼 거면, 총을 두 배로 많이 쏴야죠. 아, 물론 도움이 되자고 하는 말입니다.', `MaleText_loc4`='既然我们要派遣部队登上那片海滩，我们就应该用加倍猛烈的炮火轰击那里。如果你明白，就来帮忙吧。', `MaleText_loc5`='既然我們要派部隊到海灘上，我們就應該要加倍大砲的火力。你知道的，提供火力協助。', `MaleText_loc7`='Si vamos a seguir enviando tropas a la playa, deberíamos duplicar el fuego de artillería. Para ayudar, ya sabes.' WHERE `ID`=45561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포병이 더 필요합니다... 훨씬 더요! 아으, 전 정말 반도가 싫어요.', `MaleText_loc4`='炮火一定要更猛烈！我从来都不喜欢什么半岛。', `MaleText_loc5`='更多火砲...更多!反正我從來不喜歡這些半島。', `MaleText_loc7`='¡Más artillería, más! Nunca me han gustado las penínsulas.' WHERE `ID`=45562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가진 것 중에는 너에게 도움이 될 만한 게 없구나.$B$B드롬이라면 네가 관심을 둘만한 것을 갖고 있을 거다.', `MaleText_loc4`='我这里没有什么能帮到你的东西。$B$B也许德罗姆的收集品中会有一些能让你感兴趣的东西。', `MaleText_loc5`='我沒有東西可以供你使用。$B$B或許德隆收集的東西當中會有你感興趣的。', `MaleText_loc7`='No poseo nada que pudiera serte de utilidad.$b$bA lo mejor D''lom tiene algo que te interese en su colección.' WHERE `ID`=45563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요, $c님?', `FemaleText_loc4`='我能怎样帮你，$c？', `FemaleText_loc5`='你需要什麼，$c?', `FemaleText_loc7`='¿Cómo puedo ayudarte, $c?' WHERE `ID`=45564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 올 줄 알고 있었지. 주위에서 너와 아리카라와의 연관성에 대해 말하는 건 아무래도 상관없다. 모두 여기서 끝날 지어다!', `MaleText_loc4`='我知道你有自己的办法。我不在乎他们对于你和阿利卡拉的关系有着怎样的议论。那些话到我这里就结束了！', `MaleText_loc5`='我知道你準備要離開了。我不在乎他們說了你什麼，或是你和阿利卡拉有什麼關係。這件事現在就得結束!', `MaleText_loc7`='Sabía que estabas de camino. Me da igual lo que digan sobre ti o sobre tu relación con Arikara. ¡Esto acaba aquí!' WHERE `ID`=45565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 이렇게 끝나는 건가? 이곳 먹구름 봉우리에서?', `MaleText_loc4`='在黑云峰上，一切就这样结束了？', `MaleText_loc5`='經歷了那麼多事情，結局就是這樣嗎?在這暗雲峰上?', `MaleText_loc7`='Después de todo, ¿es así como acaba? ¿Aquí, en la Cumbre de la Nube Negra?' WHERE `ID`=45566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 주술사가 되면, 주술사가 얼마나 좋은지 알게 되지.$B$B불의 정령이 이렇게 유용할 줄은 몰랐어. 벌주기도 쉽고 말이야. 그냥 물만 좀 부으면 되니까.', `MaleText_loc4`='一旦你决定成为一名萨满祭司，就再无法回头了。$B$B我曾经严重低估了火元素的效用。而且它也很容易管束：只需要加水就可以了。', `MaleText_loc5`='一旦變成薩滿之後，你就不能回頭了。$B$B我完全低估了火元素的好用。要教訓它們也很容易:加水就行了。', `MaleText_loc7`='Cuando hayas probado el chamanismo, ya no querrás probar otra cosa.$b$bHabía subestimado totalmente la utilidad de los elementales de fuego. Y además son fáciles de meter en cintura: solo hay que añadir agua.' WHERE `ID`=45567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 고원 전역에서 우리 고리회를 공격해 많은 지역을 손에 넣었네. 여기가 마지막일세. 놈들이 대지에서 어떤 무시무시한 것을 불러내도, 여기마저 내줄 수는 없네.', `MaleText_loc4`='暮光之锤一直在这片高地的各处向我们发动进攻。现在他们已经占领了不少地方。这是我们最后的阵地了，我们可不打算把它丢给敌人，无论他们会从地底下召唤出多么恐怖的怪物来攻击我们。', `MaleText_loc5`='暮光之錘的人攻擊了我們位於高地各處的據點，但是他們自己也付出了相當大的代價。這裡是我們最後的一處據點，不論他們從大地召喚出什麼樣的恐怖怪物來襲擊我們，我們都不會放棄這裡。', `MaleText_loc7`='El Mah''tillo Crepuscular ha eh''ta''o asaltando nueh''tros anillos por todas las Tierras Altas, y han incorpora''o a muchos a sus filas en el proceso. Eh''te es el último que tenemos y no tenemos intención de rendirnos, sin impoh''tar los horrores que invoquen de la tierra pa'' atacarnos.' WHERE `ID`=45568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고모가 보냈다는 게 너였나? 널 보내 날 시험하시려나 보군. 네놈을 처치하고 내 가치를 다시 한번 증명하겠다.', `MaleText_loc4`='你就是我的姑妈派来的那个家伙？毫无疑问，这是一次测试。我会迅速地干掉你，再一次向她证明我的实力。', `MaleText_loc5`='你是我姨媽派來的?毫無疑問，這是個考驗。看我三兩下宰了你，再一次跟她證明我的能耐。', `MaleText_loc7`='¿Mi tía te ha enviado a ti? Una prueba, no cabe duda. Te mataré rápidamente y le demostraré una vez más que soy digno.' WHERE `ID`=45569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 고모님, 용서해 주십시오! 살려 주십시오!', `MaleText_loc4`='不！玛加萨，请原谅我！带我回去！', `MaleText_loc5`='不!瑪加薩，原諒我!帶我回去!', `MaleText_loc7`='¡NO! ¡Magatha, perdóname! ¡Tráeme de vuelta!' WHERE `ID`=45570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했네, $c! 이제 간단한 단서만 쫓아가면 될 거야.', `MaleText_loc4`='干得好，$c！你要做的就是依照线索采取行动。', `MaleText_loc5`='幹得好，$c!你可以跟隨簡單的線索。', `MaleText_loc7`='¡Bien hecho, $c! Sabes seguir pistas sencillas.' WHERE `ID`=45571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 부탁이니 가는 길에 아르낙을 처치하게. 가문의 수치가 된 녀석이니...', `MaleText_loc4`='哦，做点好事，顺便为我杀掉阿纳克吧，他已经成为了家族的耻辱。', `MaleText_loc5`='哦，請你行行好，順道幫我把阿納克給殺了吧。他已經變成了我們家族的一個恥辱。', `MaleText_loc7`='Ah, sé un tesoro y de paso mata a Arnak de mi parte. Se ha vuelto un poco embarazoso para la familia.' WHERE `ID`=45572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직이게, $n. 자네가 임무를 수행할 자격이 있는지 가늠할 마지막 시험이 남았네.', `MaleText_loc4`='快一点，小$n。我还要让你经历一场挑战，好看看你是否能得到这份光荣。', `MaleText_loc5`='好了，快去吧，小$n。還有一個挑戰在等著你，看看你是否有資格獲得這個榮譽。', `MaleText_loc7`='Date prisa, $gpequeño:pequeña; $n. Tengo otro reto para ver si eres $gdigno:digna; del honor.' WHERE `ID`=45573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 멍청이들은 대체 어디로 갔을까요?', `FemaleText_loc4`='那些呆子在哪里？', `FemaleText_loc5`='那些笨蛋瓜在哪裡?', `FemaleText_loc7`='¿Dónde están esos estúpidos?' WHERE `ID`=45574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지모신이시여 자비를 베푸소서!', `FemaleText_loc4`='愿大地母亲怜悯！', `FemaleText_loc5`='大地之母慈悲為懷!', `FemaleText_loc7`='¡Que la Madre Tierra tenga compasión!' WHERE `ID`=45575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 자리!', `MaleText_loc4`='射击！', `MaleText_loc5`='我坐前面!', `MaleText_loc7`='¡Copiloto!' WHERE `ID`=45576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야! 그런데 왜 네가 앞에 앉아서 가는 거야?', `MaleText_loc4`='嗨！为什么你要坐在前面？', `MaleText_loc5`='喂!為什麼你可以坐前面?', `MaleText_loc7`='¡Oye! ¿Por qué tú puedes ir delante?' WHERE `ID`=45577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 내기에서 이겼으니까. 그리고 내가 "내 자리"라고 먼저 말했으니까.', `MaleText_loc4`='因为我赢了我们的打赌。也因为我喊了“射击”。', `MaleText_loc5`='因為我打賭贏了。還有因為是我先喊的。', `MaleText_loc7`='Porque gané la apuesta. Y porque me he pedido copiloto.' WHERE `ID`=45578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 네가 이겼다고 누가 그러는데? 아직 점수는 비교해 보지도 않았잖아.', `MaleText_loc4`='谁说你赢了？我们还没有比较分数呢。', `MaleText_loc5`='是誰說你贏了?我們又還沒有開始比誰的多。', `MaleText_loc7`='¿Quién dice que hayas ganado la apuesta? Aún no hemos comparado los recuentos.' WHERE `ID`=45579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 난 좀비 다섯 마리 처치했어. 아주 커다란 놈들이었고. 넌 언데드 몇 마리나 잡았는데?', `MaleText_loc4`='好吧。我杀了五个僵尸。都是巨型僵尸。你干掉了多少亡灵？', `MaleText_loc5`='好吧。我宰了五隻殭屍，而且它們都很大隻。你殺了幾隻亡靈?', `MaleText_loc7`='Vale. He matado a cinco zombis. Y eran enormes. ¿A cuántos no-muertos has matado tú?' WHERE `ID`=45580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명히 여섯 마리였을 거야.', `MaleText_loc4`='我确信自己干掉了六个。', `MaleText_loc5`='我很肯定我幹掉了六隻。', `MaleText_loc7`='Estoy bastante seguro de que he matado a seis.' WHERE `ID`=45581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 네 마리밖에 못 잡았다는 데 내 전 재산을 걸겠어.', `MaleText_loc4`='我打赌你只杀了四个。', `MaleText_loc5`='我敢說你一定才殺了四隻而已。', `MaleText_loc7`='Apuesto a que solo has matado a cuatro.' WHERE `ID`=45582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어떻게 알았어?', `MaleText_loc4`='你……你怎么知道的？', `MaleText_loc5`='你...你怎麼知道?', `MaleText_loc7`='¿C... cómo lo has sabido?' WHERE `ID`=45583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몰랐지. 하지만 네 덕분에 이제 알았어!', `MaleText_loc4`='我不知道。是你告诉我的！', `MaleText_loc5`='我不知道，是你剛剛自己說的!', `MaleText_loc7`='No lo sabía. ¡Me lo acabas de decir!' WHERE `ID`=45584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 정말 언데드 사냥 어떻게 됐어? 얘기 좀 해봐.', `MaleText_loc4`='我是认真的，你们的僵尸狩猎进行得如何了？我很想听一听。', `MaleText_loc5`='好，說真的，你的不死怪打獵記究竟如何?我想聽故事。', `MaleText_loc7`='Venga, en serio, ¿cómo ha ido la caza de no-muertos? Quiero oír historias.' WHERE `ID`=45585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈? 내 말 무시하냐?', `MaleText_loc4`='吉德文？你不理我了？', `MaleText_loc5`='基德溫?你是不是故意不理我?', `MaleText_loc7`='¿Gidwin? ¿Me estás ignorando?' WHERE `ID`=45586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈... 너 화났구나. 그렇지?', `MaleText_loc4`='吉蒂……你生我的气了，是么？', `MaleText_loc5`='好啦，小基基...你在生我的氣對不對?', `MaleText_loc7`='Giddy... Te has enfadado conmigo, ¿verdad?' WHERE `ID`=45587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 어렸을 때 기억나? 왜 하루 온종일 트롤, 멀록, 그리고 여자아이들하고 싸우는 흉내 내면서 놀았었잖아.', `MaleText_loc4`='还记得我们小的时候么，吉德文？我们会用一整天的时间玩打败巨魔，打败鱼人，或者是打败女孩的游戏。', `MaleText_loc5`='還記得我們小時候嗎，基德溫?我們成天都在假裝跟食人妖、魚人，還有女孩子戰鬥。', `MaleText_loc7`='¿Te acuerdas de cuando éramos pequeños, Gidwin? Nos pasábamos todo el día jugando a luchar contra trols, o múrlocs, o niñas.' WHERE `ID`=45588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러지 마, 타레나.', `MaleText_loc4`='别这样，塔伦纳。', `MaleText_loc5`='別這麼做，塔瑞納爾。', `MaleText_loc7`='No lo hagas, Tarenar.' WHERE `ID`=45589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 붙인 이름이 있었는데... 뭐였지?', `MaleText_loc4`='我们给自己起了一个名字……是什么名字……？', `MaleText_loc5`='我們還幫自己取了個名字...叫什麼來著的?', `MaleText_loc7`='Nos llamábamos un nombre... ¿Cuál era?' WHERE `ID`=45590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 알고 있으면서 괜히 물어보지 마.', `MaleText_loc4`='你记得很清楚。', `MaleText_loc5`='你明明就還記得很清楚。', `MaleText_loc7`='Sabes exactamente cuál era.' WHERE `ID`=45591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐, 정말 진지하게 물어보는 거야. 완전히 잊어버렸다고.', `MaleText_loc4`='我是认真的。我完全忘记了。', `MaleText_loc5`='我是說真的，我真的忘記了。', `MaleText_loc7`='Lo digo en serio. Lo he olvidado por completo.' WHERE `ID`=45592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<한숨>... "성스러운 성기사들"이었어.', `MaleText_loc4`='<叹息>……“圣骑士党”', `MaleText_loc5`='<嘆氣>...「聖騎士好兄弟」。', `MaleText_loc7`='<Suspiro>... "Los Paladines Espadachines".' WHERE `ID`=45593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기드윈, 다음번에는 나랑 같이 앞에 앉아.', `FemaleText_loc4`='吉德文，下次你可以和我一起坐在前面。', `FemaleText_loc5`='基德溫，下回你可以到前面來跟我一起坐。', `FemaleText_loc7`='Gidwin, la próxima vez puedes sentarte delante conmigo.' WHERE `ID`=45594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 별로 그러고 싶지 않아. 여기 뒤쪽에서 새 친구와 함께 앉는 게 더 좋거든. 앞쪽에선 말 냄새가 나.', `MaleText_loc4`='也许我不想了。也许我更愿意和我的新朋友们坐在后面。前面有一股马味儿。', `MaleText_loc5`='說不定我不想去前面坐了。說不定我比較想跟這位新朋友一起坐後面。而且上面那兒有馬臭味。', `MaleText_loc7`='A lo mejor ya no me apetece. A lo mejor prefiero quedarme aquí sentado con mi flamante camarada. Ahí huele a caballo.' WHERE `ID`=45595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞쪽에 길 왼편으로 탑이 하나 보인다. 저기서 잠깐 쉬었다 가는 게 어때?', `FemaleText_loc4`='我在左边看到了一座塔楼。我们停下来休息一下如何？', `FemaleText_loc5`='左邊那兒有一座塔，我們停下來歇一會如何啊?', `FemaleText_loc7`='Nos acercamos a una torre por la izquierda. ¿Qué te parece si nos paramos y descansamos un rato?' WHERE `ID`=45596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 쉬고 나서 몇 분 지나지도 않았잖아! 그냥 희망의 빛 예배당으로 바로 가자!', `MaleText_loc4`='我们在几分钟前刚刚休息过！还是赶紧去圣光之愿礼拜堂吧！', `MaleText_loc5`='我們幾分鐘前才剛休息過!我們要直接去聖光之願禮拜堂!', `MaleText_loc7`='¡Hemos descansado hace unos minutos! ¡Sigamos hasta la Capilla de la Esperanza de la Luz!' WHERE `ID`=45597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 길이 워낙 험해서 그래, 기드윈. 말이 다치기라도 하면 안 되잖아.', `FemaleText_loc4`='这里的路很难走，吉德文。我可不想冒失去一匹马的危险。', `FemaleText_loc5`='這邊的路很不好走，基德溫。我可不希望冒險害馬受傷。', `FemaleText_loc7`='Estos caminos son duros, Gidwin. No quiero arriesgarme a perder un caballo.' WHERE `ID`=45598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 일은 없어. 한 번 보라고! 처음 출발했을 때랑 똑같이 씩씩한데 뭘!', `MaleText_loc4`='我们不会失去马的。看看它们！它们还和我们刚刚出发时一样精力充沛。', `MaleText_loc5`='我們才不會害馬受傷咧，你看看牠們!牠們就跟我們剛上路的時候一樣健康有力。', `MaleText_loc7`='No vamos a perder ningún caballo. ¡Míralos! Están igual que cuando hemos empezado.' WHERE `ID`=45599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기... 나는 피오나 말이 맞는 것 같아.', `MaleText_loc4`='确实，菲奥拉说得没错。', `MaleText_loc5`='事實上，我同意菲歐娜的看法。', `MaleText_loc7`='La verdad es que estoy de acuerdo con Fiona.' WHERE `ID`=45600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 더 기다린다고 해서 은빛십자군에 무슨 일이라도 있겠어? 그리고... 우리 손님도 마차에서 내리셔야 할 일이 있을지 모르잖아.', `MaleText_loc4`='我们就算是晚到一会儿，银色北伐军也不会着急的。而且……我们的客人也许很快就会想要下车了。', `MaleText_loc5`='銀白十字軍還可以再等我們一下下。況且...我們這位客人說不定很快就會想下車離開商隊了。', `MaleText_loc7`='La Cruzada Argenta puede esperarnos un poco más. Además... quizá alguien se quiera bajar pronto.' WHERE `ID`=45601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 왔어!', `FemaleText_loc4`='我们到了！', `FemaleText_loc5`='到了!', `FemaleText_loc7`='¡Aquí estamos!' WHERE `ID`=45602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카를린 님, 혹시 확장된 다로우골 연대기를 갖고 계십니까?', `MaleText_loc4`='卡林，你有达隆郡全史吗？', `MaleText_loc5`='卡林，你有達隆郡全史嗎?', `MaleText_loc7`='Carlin, ¿tienes las Crónicas ampliadas de Villa Darrow?', `FemaleText_loc1`='카를린 님, 혹시 확장된 다로우골 연대기를 갖고 계세요?', `FemaleText_loc4`='卡林，你有达隆郡全史吗？', `FemaleText_loc5`='卡林，你有達隆郡全史嗎?', `FemaleText_loc7`='Carlin, ¿tienes las Crónicas ampliadas de Villa Darrow?' WHERE `ID`=45603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 갖고 있소... 크로미가 필요하다고 했소? 아무래도 그럴 것 같군.$b$b자, 가져가도 좋소. 물론 한 번 읽어봐도 좋고. 그 책을 보시면 다로우골의 역사와 함께 수많은 사람을 죽음으로 이끌었던 사건에 대해서도 자세히 알게 될 거요.', `MaleText_loc4`='嗯，有的……克罗米需要这个？应该是吧。$b$b我可以把它给你，随你翻看。它会告诉你达隆郡的历史，以及导致那么多人死亡的许多事件细节。', `MaleText_loc5`='呃，有...是克羅米要的嗎?我想應該是她沒錯。$B$B好吧，我可以給你，請自行翻閱，裡頭記載了達隆郡的歷史，以及當年造成許多人死亡的那場不幸事件的詳情始末。', `MaleText_loc7`='Sí, ¿por qué? ¿Le hacen falta a Cromi? Me imagino que sí.$b$bSí, te las puedes quedar. Ojea las páginas sin temor. En su interior encontrarás la historia de Villa Darrow, y los detalles de los acontecimientos que condujeron a las muertes de tantísimos hombres.' WHERE `ID`=45604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 지원군이 도착했습니다.', `MaleText_loc4`='联盟援军到了。', `MaleText_loc5`='聯盟援軍已經抵達。', `MaleText_loc7`='Han llegado los refuerzos de la Alianza.', `FemaleText_loc1`='얼라이언스 지원군이 도착했습니다.', `FemaleText_loc4`='联盟援军到了。', `FemaleText_loc5`='聯盟援軍已經抵達。', `FemaleText_loc7`='Han llegado los refuerzos de la Alianza.' WHERE `ID`=45605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군, 영웅들이여! 스트라솔름은 우리 것이오! 이리 나오시오. 우리는 도살장 바로 바깥에서 기다리고 있소!', `MaleText_loc4`='英雄们，你们成功了！斯坦索姆是我们的了！来吧，我们就等在屠宰房外面！', `MaleText_loc5`='英雄們，你們辦到了!斯坦索姆是我們的了!來吧，我們就在屠宰房的外面等著!', `MaleText_loc7`='¡Lo habéis conseguido, héroes! ¡Stratholme es nuestra! ¡Venid, os esperamos delante del matadero!' WHERE `ID`=45606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시를 되찾는 데 당신들의 공이 가장 컸소. 리븐데어의 죽음은 역병지대에 새로운 시대가 도래함을 의미하는 것이오. 남은 스컬지는 쉽게 처리할 수 있을 거요. 이 땅이 마침내 다시 태어나는 거요.', `MaleText_loc4`='你们行动的目的是夺取这座城市。对于瘟疫之地，瑞文戴尔的死亡标志着一个新时代的到来。残存在这里的天灾军团很快就会被消灭干净。这片土地终将得到重生。', `MaleText_loc5`='你們的行動是我們得以成功奪回這座城的關鍵。瑞文戴爾的死亡代表著瘟疫之地的新時代即將展開。少數殘餘的天譴軍團很輕易就會被解決掉，這塊土地終於得以重生。', `MaleText_loc7`='Sus acciones han sido cruciales a la hora de recuperar la ciudad. La muerte de Osahendido marca el comienzo de una nueva era para las Tierras de la Peste. La Plaga restante no debería tardar en caer, y la tierra podrá renacer por fin.' WHERE `ID`=45607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스트라솔름을 재건하고 완전히 정화하는 데는 오랜 시간이 걸릴 수 있으나, 나는 기꺼이 이를 감당하고 스트라솔름을 변화시킬 것이오. 언젠가 은빛 성기사단 성채에서 무장한, 혹은 알론서스 교회에서 입단식을 치른 다음 빛의 수호자가 나올지도 모르지. 결과가 어떻든, 오늘 우리가 해낸 일은 언젠가 값진 열매를 맺을 것이오.', `MaleText_loc4`='斯坦索姆的彻底净化和重建还需要相当长的时间和巨大的精力，但我很高兴能亲身经历这个过程。也许在未来的某一天，我们能在这座白银之手的堡垒看到下一位伟大的圣光守卫者，亲眼见证他在阿隆索斯礼拜堂加入我们的队伍。无论以后会如何，我们在这里的工作总有一天会结下丰硕的果实。', `MaleText_loc5`='斯坦索姆或許還要好些時候才有辦法徹底淨化與重建，但至少我將樂於見其展開重建的工作。或許將來有一天我們會見到聖光的守護者駐紮在白銀之手堡壘裡，或是在阿隆索斯教堂裡獲得策封。不論將來結果如何，我們今天的努力的確獲得了重大的成果。', `MaleText_loc7`='Es probable que se tarde bastante tiempo en reconstruir y purificar Stratholme del todo, pero es un esfuerzo que supervisaré con gran placer. Quizás algún día veamos al próximo gran defensor de la Luz armado en el Bastión de la Mano de Plata, u ordenado en la Capilla de Alonsus.' WHERE `ID`=45608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사하오, 용감한 영웅들이여. 빛줄기는 아무리 두꺼운 어둠이라도 뚫고 지나갈 수 있다는 것을 아제로스에 보여줘서 고맙소.', `MaleText_loc4`='谢谢你们，勇敢的英雄们。谢谢你们向艾泽拉斯证明了，无论邪恶的力量多么恐怖，凶猛，不可阻遏，总有一线圣光会冲破黑暗，为我们带来希望。', `MaleText_loc5`='感謝諸位勇敢的英雄們。謝謝你們，讓艾澤拉斯全體人民百姓知道，不論黑暗的力量有多強大，聖光都有辦法穿透它。', `MaleText_loc7`='Gracias, valientes héroes. Gracias por demostrarle a Azeroth que una sola Luz puede atravesar hasta la oscuridad más abrumadora.' WHERE `ID`=45609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급의 중요성을 무시하지 말게. 전투를 승리로 이끄는 건 전사들이지만, 전쟁을 승리로 이끄는 건 보급품이라네.', `MaleText_loc4`='绝不要低估后勤供给的作用。战士们也许会赢得几次战斗，但只有足够的物资供应才能确保一场战争的胜利。', `MaleText_loc5`='千萬別低估了後勤管理與補給的重要性。戰鬥獲勝的關鍵或許在於將士，但戰爭獲勝的關鍵卻在於糧草補給。', `MaleText_loc7`='Nunca subestimes el poder de la buena gestión de suministros. Puede que los guerreros ganen las batallas, pero los suministros ganan la guerra.' WHERE `ID`=45610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물 고맙군. 자신의 가치를 증명해보게, $c!', `MaleText_loc4`='感谢你的礼物，让我们看看你有怎样的价值，$c！', `MaleText_loc5`='謝謝你的禮物。讓我瞧瞧你是否有資格，$c!', `MaleText_loc7`='Gracias por los obsequios. ¡Veamos si eres $gdigno:digna;, $c!' WHERE `ID`=45611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰! 내 천둥매를 죽일 셈인가!', `MaleText_loc4`='住手！你已经打败了我的风蛇。', `MaleText_loc5`='停!你已經打敗了我的風蛇。', `MaleText_loc7`='¡Basta! Has superado a mi serpiente alada.' WHERE `ID`=45613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 지금껏 황혼의 망치단의 포로로 잡혀 있었네.', `MaleText_loc4`='我被暮光之锤俘虏了。', `MaleText_loc5`='我淪為暮光之錘的階下囚。', `MaleText_loc7`='El Martillo Crepuscular me ha hecho prisionera.' WHERE `ID`=45614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디인지는 확실하지 않네. 마루둥지를 내려다보는 서편 기슭부터 수색을 시작하게.', `MaleText_loc4`='我不确定那是在哪里。一开始，是在他们西边的基地。那里能够俯瞰风巢。', `MaleText_loc5`='我不確定在哪裡，但不妨從他們俯瞰風巢的西側基地開始。', `MaleText_loc7`='No sé con certeza dónde. Empieza con la base del oeste, por encima de Nido Alto.' WHERE `ID`=45615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가서 그 환영을 다시 보고 싶습니다. 마법이 걸린 외날창을 아직 갖고 계십니까?', `MaleText_loc4`='我很想回去，再看看那种幻象。你还有那件魔法武器吗？', `MaleText_loc5`='我想要回去再看一遍其中某個影像。那把魔法刃還在你身上嗎?', `MaleText_loc7`='Me gustaría regresar y ver una de las visiones otra vez. ¿Todavía tienes la espada encantada?', `FemaleText_loc1`='돌아가서 그 환영을 다시 보고 싶어요. 마법이 걸린 외날창을 아직 갖고 계신가요?', `FemaleText_loc4`='我很想回去，再看看那种幻象。你还有那种魔法武器吗？', `FemaleText_loc5`='我想要回去再看一遍其中某個影像。那把魔法刃還在你身上嗎?', `FemaleText_loc7`='Me gustaría regresar y ver una de las visiones otra vez. ¿Todavía tienes la espada encantada?' WHERE `ID`=45616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복하라고? 그래, 우리 항복 문서는 네놈들 피로 써 주마.', `MaleText_loc4`='投降？我的投降书只能用他们的血来写。', `MaleText_loc5`='投降?我會用他們的鮮血來撰寫我們投降的條件。', `MaleText_loc7`='¿Rendirnos? Escribiré las condiciones de nuestra rendición con su sangre.' WHERE `ID`=45617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 편안하게 쉬실 수 있을지 모르겠군요, $c님. 이 오크들은 도무지 조용히 있는 법을 모르더라고요.', `MaleText_loc4`='我没办法保证你们能在这里得到平静的休息环境，$c。这些兽人根本不知道什么是平静。', `MaleText_loc5`='我無法保證你能夠不受干擾地休息，$c。這些獸人不知道何時才會離開。', `MaleText_loc7`='No puedo prometer que tu descanso sea tranquilo, $c. Estos orcos no saben cuándo dejarlo.', `FemaleText_loc1`='당신이 편안하게 쉬실 수 있을지 모르겠군요, $c님. 이 오크들은 도무지 조용히 있는 법을 모르더라고요.', `FemaleText_loc4`='我没办法保证你们能在这里得到平静的休息环境，$c。这些兽人根本不知道什么是平静。', `FemaleText_loc5`='我無法保證你能夠不受干擾地休息，$c。這些獸人不知道何時才會離開。', `FemaleText_loc7`='No puedo prometer que tu descanso sea tranquilo, $c. Estos orcos no saben cuándo dejarlo.' WHERE `ID`=45618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술 취한 오크 하나는 우스꽝스럽지요. 하지만 술 취한 오크가 한 부대라면 정말 너무 끔찍해서 다시는 보고 싶지 않습니다.', `MaleText_loc4`='一个喝醉的兽人很值得看一看。而一支喝醉的兽人军队则是我绝对不想看到的。', `MaleText_loc5`='一個喝醉酒的獸人是蠻值得看的場面。一狗票喝醉酒的獸人士兵卻是我再也不想看到的場面。', `MaleText_loc7`='Un orco borracho es algo digno de ver. Un ejército de orcos borrachos es algo que no quiero volver a ver jamás.', `FemaleText_loc1`='술 취한 오크 하나는 우스꽝스러워요. 하지만 술 취한 오크가 한 부대라면 정말 너무 끔찍해서 다시는 보고 싶지 않네요.', `FemaleText_loc4`='一个喝醉的兽人很值得看一看。而一支喝醉的兽人军队则是我绝对不想看到的。', `FemaleText_loc5`='一個喝醉酒的獸人是蠻值得看的場面。一狗票喝醉酒的獸人士兵卻是我再也不想看到的場面。', `FemaleText_loc7`='Un orco borracho es algo digno de ver. Un ejército de orcos borrachos es algo que no quiero volver a ver jamás.' WHERE `ID`=45619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 때가 오리라고 어머니께서 말씀하셨더라도, 저는 절대 믿지 않았을 겁니다.', `MaleText_loc4`='如果我妈妈告诉我会有这样的时代，我绝对不会相信她的话。', `MaleText_loc5`='就算我母親有跟我講過會發生像這樣的事情，當時我也不會相信她。', `MaleText_loc7`='Si mi madre me hubiera dicho que habría días como estos, no la habría creído.', `FemaleText_loc1`='이런 때가 오리라고 어머니께서 말씀하셨더라도, 저는 절대 믿지 않았을 거예요.', `FemaleText_loc4`='如果我妈妈告诉我会有这样的时代，我绝对不会相信她的话。', `FemaleText_loc5`='就算我母親有跟我講過會發生像這樣的事情，當時我也不會相信她。', `FemaleText_loc7`='Si mi madre me hubiera dicho que habría días como estos, no la habría creído.' WHERE `ID`=45620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, "백전노장"! 이름은 언제 바꿀 건가? 이 마을은 우리 두 사람이 같이 살 수 있을 만큼 넓지가 않아...', `MaleText_loc4`='嗨，“老水兵”，你什么时候能换个名字？这个小镇子可不应该有两个叫同样外号的……', `MaleText_loc5`='嘿，「老練的」，你什麼時候才要去換名字?這個小鎮沒大到容得下我們兩個...', `MaleText_loc7`='Hey, "Salado", ¿cuándo vas a ponerte un nombre nuevo? Esta ciudad no es suficientemente grande para los dos...', `FemaleText_loc1`='이봐요, "백전노장"! 이름은 언제 바꿀 거죠? 이 마을은 우리 두 사람이 같이 살 수 있을 만큼 넓지가 않다고요...', `FemaleText_loc4`='嗨，“老水兵”，你什么时候能换个名字？这个小镇子可不应该有两个叫同样外号的……', `FemaleText_loc5`='嘿，「老練的」，你什麼時候才要去換名字?這個小鎮沒大到容得下我們兩個...', `FemaleText_loc7`='Hey, "Salado", ¿cuándo vas a ponerte un nombre nuevo? Esta ciudad no es suficientemente grande para los dos...' WHERE `ID`=45621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 거기! 너! 야! 이봐! 요즘 어떻게 살아?', `MaleText_loc4`='嗨，那边！嗨！嗨！就是那边！去看看格尔加怎么样啦？', `MaleText_loc5`='嘿，那邊!嘿!嘿!那邊!最近怎麼樣啊，戈戈戈加加爾?', `MaleText_loc7`='¡Hey, aquí! ¡Hey! ¡Hey! ¿Qué tal va todo, Gororgararar?', `FemaleText_loc1`='이봐요, 거기! 당신! 요즘 어떻게 살아요?', `FemaleText_loc4`='嗨，那边！嗨！嗨！就是那边！去看看格尔加怎么样啦？', `FemaleText_loc5`='嘿，那邊!嘿!嘿!那邊!最近怎麼樣啊，戈戈戈加加爾?', `FemaleText_loc7`='¡Hey, aquí! ¡Hey! ¡Hey! ¿Qué tal va todo, Gororgararar?' WHERE `ID`=45623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! "백전노땅"! 어이, 그 보급품은 대체 왜... 어... 음... 거 상자가 참 많구만...', `MaleText_loc4`='呦喉！“老情歌”！看起来你们的物资……嗯……看来你还有许多箱子需要登记……', `MaleText_loc5`='呦呼!「老臉的」!嘿，你的那些貨物...那...哦...嗯...你有好多的箱子要紀錄...', `MaleText_loc7`='¡Eh, oye! ¡"Melosho"! Eh, Por qué tush shuminstrosh... Cuá... Oh... Um... Tienesh que llevar el control de un montón de cajash...', `FemaleText_loc1`='야호! "백전노땅"! 저기, 그 보급품은 대체 왜... 어... 음... 상자가 정말 많군요...', `FemaleText_loc4`='呦喉！“老情歌”！看起来你们的物资……嗯……看来你还有许多箱子需要登记……', `FemaleText_loc5`='呦呼!「老臉的」!嘿，你的那些貨物...那...哦...嗯...你有好多的箱子要紀錄...', `FemaleText_loc7`='¡Eh, oye! ¡"Melosho"! Eh, Por qué tush shuminstrosh... Cuá... Oh... Um... Tienesh que llevar el control de un montón de cajash...' WHERE `ID`=45624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 이봐! "영감"! 보급품을 잘 챙겨 놨어? 이렇게 좀 해봐. 이렇게, 저렇게...', `MaleText_loc4`='呸！呸！嗨！“胡椒”！你们要照顾好所有这些物资！有没有看见我刚才做了什么？部落……为了部落！', `MaleText_loc5`='噗嘶!噗嘶!嘿嘿!「老黏的」!你的東西到底收好了沒!', `MaleText_loc7`='¡Pssst! ¡Pssst! ¡Hey! ¡"Pimienta"! ¿Ya hash terminado de reunir losh shuministrosh en plan horda? ¿Hash vishto lo que acabo de hacer? Horda... ¡Por la Horda!', `FemaleText_loc1`='잠깐! 이봐요! "영감"! 보급품을 잘 챙겨 놨어요? 이렇게 좀 해보라고요. 이렇게, 저렇게...', `FemaleText_loc4`='呸！呸！嗨！“胡椒”！你们要照顾好所有这些物资！有没有看见我刚才做了什么？部落……为了部落！', `FemaleText_loc5`='噗嘶!噗嘶!嘿嘿!「老黏的」!你的東西到底收好了沒!', `FemaleText_loc7`='¡Pssst! ¡Pssst! ¡Hey! ¡"Pimienta"! ¿Ya hash terminado de reunir losh shuministrosh en plan horda? ¿Hash vishto lo que acabo de hacer? Horda... ¡Por la Horda!' WHERE `ID`=45625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"백발노땅"! 어이, "백발노땅"! 술을 더 가지러 간 줄 알았는데! 뭐 때문에 이렇게 오래 걸리는 거야?', `MaleText_loc4`='“麦芽”！嗨，“麦芽”！我还以为你会给我们带更多的酒来呢！你到底带来了什么？', `MaleText_loc5`='「老糊塗的」!嘿，「老糊塗的」!我還以為你要去弄多點酒來給我們!怎麼會拖那麼久?', `MaleText_loc7`='¡"Malty"! ¡Eh, "Malty"! ¡Creía que ibash a traernosh algo para beber! ¿Qué te entretiene?".', `FemaleText_loc1`='"백발노땅"! 이봐요, "백발노땅"! 술을 더 가지러 간 줄 알았는데! 뭐 때문에 이렇게 오래 걸리는 거죠?', `FemaleText_loc4`='“麦芽”！嗨，“麦芽”！我还以为你会给我们带更多的酒来呢！你到底带来了什么？', `FemaleText_loc5`='「老糊塗的」!嘿，「老糊塗的」!我還以為你要去弄多點酒來給我們!怎麼會拖那麼久?', `FemaleText_loc7`='¡"Malty"! ¡Eh, "Malty"! ¡Creía que ibash a traernosh algo para beber! ¿Qué te entretiene?".' WHERE `ID`=45626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"백전노장"이야! 내가 먼저 왔다고! 배에서 내려 육지에 가장 먼저 도착했다고! "백전노장" 이름은 내가 쓰겠어! 어이, 당신 야수는 어디에 있어?', `MaleText_loc4`='是“老水兵”！我先到了这里！是我先从船上跳到了这片陆地上！我才叫“老水兵”。嗨……你的宠物在哪里？', `MaleText_loc5`='是「老練的」!是我先來的!是我先下船上陸地的!我的名字就叫「老練的」。嘿...你的寵物咧?', `MaleText_loc7`='¡Esh "Salado"! ¡Yo he llegado primero! ¡He shido la primera en deshembarcar y tocar tierra! He gritado el nombre "Salado". Hey... ¿Dónde eshtá tu mashcota?', `FemaleText_loc1`='"백전노장"이에요! 제가 먼저 왔다고요! 배에서 내려 육지에 가장 먼저 도착했다고요! "백전노장" 이름은 내가 쓰겠어요! 저기, 당신 야수는 어디에 있죠?', `FemaleText_loc4`='是“老水兵”！我先到了这里！是我先从船上跳到了这片陆地上！我才叫“老水兵”。嗨……你的宠物在哪里？', `FemaleText_loc5`='是「老練的」!是我先來的!是我先下船上陸地的!我的名字就叫「老練的」。嘿...你的寵物咧?', `FemaleText_loc7`='¡Esh "Salado"! ¡Yo he llegado primero! ¡He shido la primera en deshembarcar y tocar tierra! He gritado el nombre "Salado". Hey... ¿Dónde eshtá tu mashcota?' WHERE `ID`=45627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아니라 당신 야수 걱정이나 하시지! 내 할 일은 내가 잘 알아서 하고 있으니까!', `MaleText_loc4`='也许你应该担心你的宠物，而不是我！我对工作一直都很尽职尽责！', `MaleText_loc5`='我看你該擔心的不是我，而是你的寵物才對!我的日子過得可好的咧!', `MaleText_loc7`='¡Quizásh deberíah precuparte por tu mashcota y no por mí! ¡Yo me eshtoy encargando de mis negociosh perfectamente, graciash!', `FemaleText_loc1`='내가 아니라 당신 야수 걱정이나 하시죠! 내 할 일은 내가 잘 알아서 하고 있으니까요!', `FemaleText_loc4`='也许你应该担心你的宠物，而不是我！我对工作一直都很尽职尽责！', `FemaleText_loc5`='我看你該擔心的不是我，而是你的寵物才對!我的日子過得可好的咧!', `FemaleText_loc7`='¡Quizásh deberíah precuparte por tu mashcota y no por mí! ¡Yo me eshtoy encargando de mis negociosh perfectamente, graciash!' WHERE `ID`=45628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"백전노장", 그건 내 이름이라고! 당신은 그냥 "전 야수를 맡을 수가 없어요"라고 솔직히 인정하라고. 도무지 사람들이 당신한테 왜 야수를 맡기는지 알 수가 없어.', `MaleText_loc4`='“老水兵”，这是我的名字！你的名字应该是“我管不住宠物”。我才不相信会有人敢把宠物交给你。', `MaleText_loc5`='「老練的」才是我的名字!你應該改名叫做「我照顧不了寵物」才對。真不敢相信，竟然有人會放心把寵物交給你。', `MaleText_loc7`='"Shalado."¡Ashí me llamo! Tu nombre debería sher "No puedo ocuparme de mi mashcota". ¡No puedo creer que alguien te confiara una beshtia!', `FemaleText_loc1`='"백전노장", 그건 내 이름이라고요! 당신은 그냥 "전 야수를 맡을 수가 없어요"라고 솔직히 인정하시죠? 도무지 사람들이 당신한테 왜 야수를 맡기는지 알 수가 없다니까요.', `FemaleText_loc4`='“老水兵”，这是我的名字！你的名字应该是“我管不住宠物”。我才不相信会有人敢把宠物交给你。', `FemaleText_loc5`='「老練的」才是我的名字!你應該改名叫做「我照顧不了寵物」才對。真不敢相信，竟然有人會放心把寵物交給你。', `FemaleText_loc7`='"Shalado."¡Ashí me llamo! Tu nombre debería sher "No puedo ocuparme de mi mashcota". ¡No puedo creer que alguien te confiara una beshtia!' WHERE `ID`=45629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 날 좀 귀찮게 하지 마. 부끄러운 녀석 같으니라고. 자기 야수 한 마리도 지키지 못하면서!', `MaleText_loc4`='嗨，别来打扰我。你可真是我们的羞耻。你甚至连自己的宠物都管不好！', `MaleText_loc5`='嘿，別再煩我了。你真是有夠丟臉的，連自己的寵物都照顧不了。', `MaleText_loc7`='Hey, bashta de incordiarme. Eres una deshgracia para todosh noshotros. ¡No shiquiera puedesh ocuparte de tus propiash mashcotas!', `FemaleText_loc1`='아, 정말, 절 귀찮게 하지 마세요. 자기 야수 한 마리도 지키지 못하다니, 부끄러운 줄 아세요!', `FemaleText_loc4`='嗨，别来打扰我。你可真是我们的羞耻。你甚至连自己的宠物都管不好！', `FemaleText_loc5`='嘿，別再煩我了。你真是有夠丟臉的，連自己的寵物都照顧不了。', `FemaleText_loc7`='Hey, bashta de incordiarme. Eres una deshgracia para todosh noshotros. ¡No shiquiera puedesh ocuparte de tus propiash mashcotas!' WHERE `ID`=45631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 쉬!!!! 좀 조용히 하면 당신 야수가 돌아올지도 몰라!', `MaleText_loc4`='嘘！嘘！！！如果你能安静一会儿，也许你的宠物就会回来找你了！', `MaleText_loc5`='噓!噓!!!!!說不定你好好安靜一會兒，你的寵物就會回來找你啦!', `MaleText_loc7`='¡Shhh! ¡¡¡SHHHH!!! ¡Quizásh shi te quedash inmóvil tu mashcota regreshe a ti!', `FemaleText_loc1`='쉿! 쉬!!!! 좀 조용히 하면 당신 야수가 돌아올지도 몰라요!', `FemaleText_loc4`='嘘！嘘！！！如果你能安静一会儿，也许你的宠物就会回来找你了！', `FemaleText_loc5`='噓!噓!!!!!說不定你好好安靜一會兒，你的寵物就會回來找你啦!', `FemaleText_loc7`='¡Shhh! ¡¡¡SHHHH!!! ¡Quizásh shi te quedash inmóvil tu mashcota regreshe a ti!' WHERE `ID`=45632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 야수! 안돼! 아... 내 야수가 틀림없이 여기 어디 있을 텐데...', `MaleText_loc4`='我的宠物！哦，不！嗯……我相信那个小东西应该就在这附近……', `MaleText_loc5`='我的寵物!哦，不!呃...我肯定那隻寵物應該在這兒附近的...', `MaleText_loc7`='¡Mi mashcota! ¡Oh, no! Eh... Eshtoy seguro de que esha mashcota anda por ahí en alguna parte...', `FemaleText_loc1`='내 야수! 안돼! 아... 내 야수가 틀림없이 여기 어디 있을 텐데...', `FemaleText_loc4`='我的宠物！哦，不！嗯……我相信那个小东西应该就在这附近……', `FemaleText_loc5`='我的寵物!哦，不!呃...我肯定那隻寵物應該在這兒附近的...', `FemaleText_loc7`='¡Mi mashcota! ¡Oh, no! Eh... Eshtoy seguro de que esha mashcota anda por ahí en alguna parte...' WHERE `ID`=45633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 정말 한심하긴. 난 내 야수를 세 번째 배에 남겨뒀다고!', `MaleText_loc4`='哈！你根本就什么都不知道。我把那个畜生放在第三艘船上了！', `MaleText_loc5`='哈!你果然什麼都不知道，我把那隻東西留在第三艘船了!', `MaleText_loc7`='¡JA! Esho demueshtra lo que shabes. ¡He dejado a esha alimaña en el tercer barco!', `FemaleText_loc1`='하! 정말 한심하긴. 전 제 야수를 세 번째 배에 남겨뒀어요!', `FemaleText_loc4`='哈！你根本就什么都不知道。我把那个畜生放在第三艘船上了！', `FemaleText_loc5`='哈!你果然什麼都不知道，我把那隻東西留在第三艘船了!', `FemaleText_loc7`='¡JA! Esho demueshtra lo que shabes. ¡He dejado a esha alimaña en el tercer barco!' WHERE `ID`=45634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 내 야수는 어디 있지? 없어졌어! 아, 걱정하지 마... 술 한 잔만 마시면 녀석이 어디로 갔는지 알 수 있을 거야.', `MaleText_loc4`='等等……我的宠物在哪里？它不见了！别慌……我只需要喝上一杯，就能想出它到哪里去了。', `MaleText_loc5`='慢著...我的寵物在哪裡?不見了!不要緊張...趕緊喝個一杯，我就會想起來他跑哪兒去了。', `MaleText_loc7`='Eshpera... ¿Dónde está mi mashcota? ¡Ha desaparecido! Vale, tranquilo... Solo necesito tomarme un trago rápido y podré averiguar dónde ha ido.', `FemaleText_loc1`='잠깐... 제 야수는 어디로 갔죠? 없어졌어요! 아, 걱정할 필요 없어요... 술을 한 잔 더 마시면 그 아이가 어디로 갔는지 알 수 있을 거예요.', `FemaleText_loc4`='等等……我的宠物在哪里？它不见了！别慌……我只需要喝上一杯，就能想出它到哪里去了。', `FemaleText_loc5`='慢著...我的寵物在哪裡?不見了!不要緊張...趕緊喝個一杯，我就會想起來他跑哪兒去了。', `FemaleText_loc7`='Eshpera... ¿Dónde está mi mashcota? ¡Ha desaparecido! Vale, tranquila... Solo necesito tomarme un trago rápido y podré averiguar dónde ha ido.' WHERE `ID`=45636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어차피 그 야수는 마음에 들지 않았다고. 게다가... 사람들이 다들 나한테 자기 야수를 못 줘서 안달인데 뭘. 한 마리 잃어버려도 상관없어. 아직 열 마리도 더 남았으니까!', `MaleText_loc4`='我一直都不喜欢那只宠物。而且……人们总是把他们的宠物给我。就算丢了一只，也没关系。我还有好几十只可以丢呢！', `MaleText_loc5`='反正我也不喜歡那隻寵物。更何況...隨時都會有人來把他們的寵物交給我。就算我搞丟了一隻，那也無所謂，我還有好幾十隻可以丟!', `MaleText_loc7`='De todash maneras, no me gushtaba esa mashcota. Ademásh... La gente pasha por aquí a todash horas y me da sus mashcotas. Si pierdo una, no importa, ¡tengo docenas más para perder!', `FemaleText_loc1`='어차피 그 야수는 마음에 들지 않았어요. 게다가... 사람들이 다들 제게 자기들 야수를 못 줘서 안달인데요, 뭘. 한 마리 잃어버려도 상관없어요. 아직 열 마리도 더 남았으니까요!', `FemaleText_loc4`='我一直都不喜欢那只宠物。而且……人们总是把他们的宠物给我。就算丢了一只，也没关系。我还有好几十只可以丢呢！', `FemaleText_loc5`='反正我也不喜歡那隻寵物。更何況...隨時都會有人來把他們的寵物交給我。就算我搞丟了一隻，那也無所謂，我還有好幾十隻可以丟!', `FemaleText_loc7`='De todash maneras, no me gushtaba esa mashcota. Ademásh... La gente pasha por aquí a todash horas y me da sus mashcotas. Si pierdo una, no importa, ¡tengo docenas más para perder!' WHERE `ID`=45637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 야수한테 술 심부름을 시켰어. 녀석이 한 수레 가득 무더 우유를 싣고 나타나면, 당신 배가 좀 아프겠는걸?', `MaleText_loc4`='我派我的宠物去找些酒回来。等它带回来一马车赛马酒，而你什么也得不到的时候，你就知道后悔了。', `MaleText_loc5`='我派我的寵物去幫我再弄點喝的來。等他拖著一車穆德的牛奶回來的時候，你就會後悔啦，因為你一口也喝不到。', `MaleText_loc7`='Envié a mi mashcota a que me trajera másh bebida. Te arrepentirásh cuanto vuelva con una carreta llena de batido proteico y tú no puedash probar nada.', `FemaleText_loc1`='제 야수는 술을 한 병 더 사러 갔어요. 그 아이가 무더 우유를 잔뜩 가지고 나타나면, 꽤 부러울 걸요?', `FemaleText_loc4`='我派我的宠物去找些酒回来。等它带回来一马车赛马酒，而你什么也得不到的时候，你就知道后悔了。', `FemaleText_loc5`='我派我的寵物去幫我再弄點喝的來。等他拖著一車穆德的牛奶回來的時候，你就會後悔啦，因為你一口也喝不到。', `FemaleText_loc7`='Envié a mi mashcota a que me trajera másh bebida. Te arrepentirásh cuanto vuelva con una carreta llena de batido proteico y tú no puedash probar nada.' WHERE `ID`=45638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 있다! 여기! 여기다!', `MaleText_loc4`='我想我看到他们了！这边！这边！', `MaleText_loc5`='我想我看到他們了!這裡!這裡!', `MaleText_loc7`='¡Creo que los veo! ¡AQUÍ! ¡AQUÍ!', `FemaleText_loc1`='놈들이 있어요! 여기! 여기예요!', `FemaleText_loc4`='我想我看到他们了！这边！这边！', `FemaleText_loc5`='我想我看到他們了!這裡!這裡!', `FemaleText_loc7`='¡Creo que los veo! ¡AQUÍ! ¡AQUÍ!' WHERE `ID`=45639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새가 난다!', `MaleText_loc4`='我能闻到你！', `MaleText_loc5`='我聞得到你!', `MaleText_loc7`='¡Puedo olerte!', `FemaleText_loc1`='냄새가 나는군!', `FemaleText_loc4`='我能闻到你！', `FemaleText_loc5`='我聞得到你!', `FemaleText_loc7`='¡Puedo olerte!' WHERE `ID`=45640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화롭게 항복하는 일이 없길 바라고 있었다!', `MaleText_loc4`='我们一直都在希望你不会轻易投降！', `MaleText_loc5`='我們還希望你不會乖乖投降呢!', `MaleText_loc7`='¡Esperábamos que no te rindieras sin luchar!', `FemaleText_loc1`='평화롭게 항복하는 일이 없길 바라고 있었단다!', `FemaleText_loc4`='我们一直都在希望你不会轻易投降！', `FemaleText_loc5`='我們還希望你不會乖乖投降呢!', `FemaleText_loc7`='¡Esperábamos que no te rindieras sin luchar!' WHERE `ID`=45641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 간다!', `MaleText_loc4`='我们正在找你！', `MaleText_loc5`='我們會去找你算帳!', `MaleText_loc7`='¡Vamos a por ti!', `FemaleText_loc1`='우리가 간다!', `FemaleText_loc4`='我们正在找你！', `FemaleText_loc5`='我們會去找你算帳!', `FemaleText_loc7`='¡Vamos a por ti!' WHERE `ID`=45642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치지는 못할걸!', `MaleText_loc4`='无路可逃了！', `MaleText_loc5`='你逃不掉的!', `MaleText_loc7`='¡NO HAY ESCAPATORIA!', `FemaleText_loc1`='도망칠 곳은 없다!', `FemaleText_loc4`='无路可逃了！', `FemaleText_loc5`='你逃不掉的!', `FemaleText_loc7`='¡NO HAY ESCAPATORIA!' WHERE `ID`=45643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 찾아내고야 말겠다, 이 괴물 녀석!', `MaleText_loc4`='我们会找到你的，怪物！', `MaleText_loc5`='我們會找到你的，怪物!', `MaleText_loc7`='¡Te encontraremos, monstruo!', `FemaleText_loc1`='꼭 찾아내고야 말겠다, 이 괴물아!', `FemaleText_loc4`='我们会找到你的，怪物！', `FemaleText_loc5`='我們會找到你的，怪物!', `FemaleText_loc7`='¡Te encontraremos, monstruo!' WHERE `ID`=45644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밴시 여왕님을 실망시킬 수는 없다.', `FemaleText_loc4`='我们绝不能让女妖之王失望。', `FemaleText_loc5`='我們絕不能讓女妖之王失望。', `FemaleText_loc7`='No debemos fallarle a la Reina alma en pena.' WHERE `ID`=45645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이유를 묻는 건 내 일이 아니네.', `FemaleText_loc4`='我的职责不是问为什么。', `FemaleText_loc5`='我的命令不容質疑。', `FemaleText_loc7`='No me corresponde cuestionarme el motivo.' WHERE `ID`=45646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰에 저항하는 자에게 죽음을!', `FemaleText_loc4`='敢于反抗被遗忘者的，只有死路一条！', `FemaleText_loc5`='跟被遺忘者作對的全都得死!', `FemaleText_loc7`='¡Muerte a todo aquel que se oponga a los Renegados!' WHERE `ID`=45647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고드프리는 상당히 대단한 인물인 것 같다. 여군주께서는 고드프리를 살려내기 위해 많은 것을 희생하셨다.', `FemaleText_loc4`='高弗雷一定是个非常特别的人。主人付出了巨大的代价，只是为了让他回来。', `FemaleText_loc5`='這個高佛雷絕非等閒之輩，女王為他的歸來付出了很大的犧牲。', `FemaleText_loc7`='Ese tal Godfrey debe de ser extraordinario. La señora ha sacrificado mucho por su retorno.' WHERE `ID`=45648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸자들... 그들이 나를 놀라게 하는군.', `FemaleText_loc4`='凡人……他们一直都让我感到惊讶。', `FemaleText_loc5`='凡人...他們總會讓我感到驚奇。', `FemaleText_loc7`='Mortales... Nunca dejan de sorprenderme.' WHERE `ID`=45649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 미천한 강아지들이 포세이큰의 힘에 저항할 수는 없다.', `FemaleText_loc4`='这些可怜的小狼崽不可能抵挡住被遗忘者的力量。', `FemaleText_loc5`='這些卑微的東西絕對阻擋不了我們被遺忘者。', `FemaleText_loc7`='Estos patéticos cachorros no pueden esperar resistir la fuerza de los Renegados.' WHERE `ID`=45650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밴시 여왕님은 모든 것을 보고 계시지.', `FemaleText_loc4`='女妖之王已经预见到了一切。', `FemaleText_loc5`='女妖之王預見了一切。', `FemaleText_loc7`='La Reina alma en pena lo ve todo.' WHERE `ID`=45651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 둘은 벌써 되살려 놓았으니, 고드프리가 마지막이 되겠군.', `FemaleText_loc4`='我们已经完成了另外两个目标。高弗雷是最后一个了。', `FemaleText_loc5`='其他兩個已經取回了，高佛雷是最後的一個。', `FemaleText_loc7`='Había otros dos que ya se han recuperado. Godfrey es el último.' WHERE `ID`=45652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고드프리는 길니아스를 방어하는 일에 자신의 목숨을 바쳤네. 늑대인간의 저주가 길니아스 전역에 번질 때, 그는 늑대인간의 공격을 막는 데 온 힘을 쏟았지.', `MaleText_loc4`='高弗雷毕生致力于守卫吉尔尼斯。当狼人诅咒在吉尔尼斯传播的时候，他将主要精力转向防御狼人的进攻。', `MaleText_loc5`='高佛雷畢生都在捍衛吉爾尼斯，而當狼人詛咒橫掃吉爾尼斯的時候，他把注意力轉移到了對抗狼人的襲擊。', `MaleText_loc7`='Godfrey se pasó la vida defendiendo Gilneas. Cuando la maldición huargen se extendió por Gilneas, se dedicó a rechazar el asalto de los huargen.' WHERE `ID`=45653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 왕마저 늑대인간의 저주에 걸렸다는 사실을 알게 되자, 고드프리는 한순간에 무너졌다고 하네. 그가 느꼈을 배신감을 상상이나 할 수 있겠나? 자신의 모든 것을 쏟아 말살하려 했던 바로 그 짐승이 바로 자신의 왕이었음을 깨달았을 때 말이네.', `MaleText_loc4`='我听说，当高弗雷知道他的国王也受到感染，精神上立刻遭到了沉重的打击。你能想象那种遭到背叛的感觉吗？他所效忠的国王成为了他势必要消灭的怪兽。', `MaleText_loc5`='我聽說高佛雷在得知他國王也被感染的真相時，整個人就崩潰了。你能想像他心中那種遭人背叛的感受嗎?他自己的國王竟然也是他畢生致力在獵殺的野獸?', `MaleText_loc7`='Me han dicho que Godfrey no pudo soportar enterarse de la aflicción de su Rey. ¿Te puedes imaginar lo traicionado que se debió sentir? ¿Qué su propio Rey sea una de las bestias que se ha pasado la vida entera matando?' WHERE `ID`=45654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고드프리가 우리의 마지막 비밀병기가 될 거네. 길니아스와 늑대인간에 대한 그의 지식을 빌릴 수 있다면, 우리가 실패하는 일은 없을 거야.', `MaleText_loc4`='高弗雷将成为我们的秘密王牌。依靠他对吉尔尼斯和狼人的知识，我们必将取得胜利。', `MaleText_loc5`='高佛雷將成為我們的王牌。有了他對吉爾尼斯和狼人的瞭解，我們必定可以獲勝。', `MaleText_loc7`='Godfrey será nuestro as en la manga. Con su conocimiento de Gilneas y de los huargen no podemos fallar.' WHERE `ID`=45655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들이 고드프리의 부관 두 명의 시체를 회수했네. 바로 애쉬버리 남작과 월든 경이라네.', `MaleText_loc4`='我的部下已经复活了高弗雷的两名副官：灰葬男爵和沃登勋爵。', `MaleText_loc5`='我的手下取回了高佛雷麾下兩員大將的屍體:艾胥柏利男爵和瓦爾登領主。', `MaleText_loc7`='Mis hombres han recuperado los cadáveres de dos de los tenientes de Godfrey: el barón Ashbury y Lord Walden.' WHERE `ID`=45656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고드프리가 우리 편에 선다면, 이 폭동을 완전히 짓밟을 수 있네!', `MaleText_loc4`='如果高弗雷站到我们这一边，我们一定能粉碎这场叛乱！', `MaleText_loc5`='有高佛雷加入我們，我們就能夠平息這場反抗!', `MaleText_loc7`='¡Con Godfrey de nuestro lado, aplastaremos esta rebelión!' WHERE `ID`=45657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이번 공격을 마치면, 얼라이언스는 결코 회복하지 못할 것이네!', `MaleText_loc4`='联盟将永远无法从我们的打击中恢复过来！', `MaleText_loc5`='這回我們要將聯盟打得不能翻身!', `MaleText_loc7`='¡La Alianza nunca se repondrá del golpe que estamos a punto de asestarle!' WHERE `ID`=45658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 인간이었던 시절 그 어느 때보다 나는 지금 더 살아 있음을 느끼네. 이게 바로 삶이야, $n. 이게 바로 살아 있는 느낌이라고!', `MaleText_loc4`='与作为人类时相比，我能够更加清晰地感受到生的活力。这才是生命，$n，这才是活着！', `MaleText_loc5`='我比我還是人類的時候更有活力。這才叫生命，$n。這才叫活著!', `MaleText_loc7`='Ahora me siento mucho más vivo que cuando era humano. ESTO es vida, $n. ¡Esto es vida!' WHERE `ID`=45659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마든지 덤벼라! 어둠의 여왕님께서 이끄는 전쟁 기계 앞에 너희는 모두 시체로 변하리라!', `MaleText_loc4`='让他们来吧！所有敌人都将被黑暗女王的战争机器摧毁！', `MaleText_loc5`='讓他們來吧!所有人都要臣服於黑暗女王的大軍!', `MaleText_loc7`='¡Que vengan! ¡Todos caerán ante la maquinaria de guerra de la Dama Oscura!' WHERE `ID`=45660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s가 늑대잡이 기름을 무기에 바릅니다.', `MaleText_loc4`='%s将破狼草油涂抹在他的武器上。', `MaleText_loc5`='%s為他的武器塗上禍狼油。', `MaleText_loc7`='%s cubre su arma con aceite aterralobos.' WHERE `ID`=45661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 마차를 함께 타고 가시겠습니까? 저희는 희망의 빛 예배당으로 가는 길입니다.', `MaleText_loc4`='想要与我们同行吗？我们正要去圣光之愿礼拜堂。', `MaleText_loc5`='要跟我們商隊一起走嗎?我們要去聖光之願禮拜堂。', `MaleText_loc7`='¿Te interesa unirte a nuestra caravana? Nos dirigimos a la Capilla de la Esperanza de la Luz.', `FemaleText_loc1`='저희 마차를 함께 타고 가시겠어요? 저희는 희망의 빛 예배당으로 가는 길이에요.', `FemaleText_loc4`='想要与我们同行吗？我们正要去圣光之愿礼拜堂。', `FemaleText_loc5`='要跟我們商隊一起走嗎?我們要去聖光之願禮拜堂。', `FemaleText_loc7`='¿Te interesa unirte a nuestra caravana? Nos dirigimos a la Capilla de la Esperanza de la Luz.' WHERE `ID`=45662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나도 그쪽으로 가는 길이라오. 주변 길에서 야생동물의 움직임이 심상치 않아서 여기 산마루 경비탑에 잠시 머무는 중이었지.$b$b이렇게 합시다. 이 부근의 길에서 야생동물을 처리해 준다면, 나도 당신과 함께 가겠소.', `MaleText_loc4`='嗯，我们正好顺路。是那些在道路上出没的怪兽让我无法成行，只能在皇冠哨卫这里耽误时日。$b$b我想和你做笔交易：帮我清除道路上的怪物，我就会加入你们的队伍。', `MaleText_loc5`='嗯，我也是要往那個方向走。因為這沿路上野獸的關係，害我耽擱在皇冠哨塔這裡。$b$b我有個提議:幫我把道路上野獸清空，我就加入你們。', `MaleText_loc7`='Bueno, voy en esa dirección. Solo me he demorado en la Torre de la Corona por la actividad de la fauna en los caminos.$b$bLes ofrezco un trato: ayúdenme a despejar el camino, y me uniré a su grupo.' WHERE `ID`=45663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사나운 야생동물들을 모두 처리해 줬으니, 나도 약속을 지켜야겠지. 어서 출발합시다!', `MaleText_loc4`='你们帮我消灭了道路上的那些凶狠的怪物。看样子，我已经没什么可抱怨的了。让我们出发吧！', `MaleText_loc5`='你已經幫我把路上那些兇猛的野獸都清掉了，所以我想我應該別無選擇了。我們走吧!', `MaleText_loc7`='Me han ayudado a despejar el camino de todos esos bichos desagradables, así que supongo que no tengo elección. ¡Andando!' WHERE `ID`=45664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그곳에서 나는 너무 오랜 시간을 보냈소. 아주 멋진 곳이고 거기서 봉사하는 일도 즐거웠지만, 이제는 여기 머무는 편이 좋을 것 같소.', `MaleText_loc4`='我已经在那个镇子里浪费了太长时间。那是一个不错的地方，我很享受在那里的生活。但我想，我更喜欢留在这里。', `MaleText_loc5`='我在那座鎮上花了太久的時間。那個地方雖然很棒，我也很喜歡那裡，但我還是寧可待在這裡。', `MaleText_loc7`='He pasado demasiado tiempo en ese pueblo. Es un sitio estupendo, y he disfrutado mi servicio allí, pero creo que prefiero quedarme aquí.' WHERE `ID`=45665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 아니, 절대 그럴 수 없소. 난 말이 무섭소.', `MaleText_loc4`='啊！不，我可不行。我害怕马。', `MaleText_loc5`='呃!不行，我永遠辦不到。我怕馬。', `MaleText_loc7`='¡Aj! Lo siento, no puedo. Me dan miedo los caballos.' WHERE `ID`=45666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙지만 괜찮아요! 나중에 갈게요. 과거에 갈까요? 어쨌든, 오늘은 정말 괜찮아요.', `FemaleText_loc4`='不！谢谢，也许将来有可能，也许过去也有可能，但绝不是今天。', `FemaleText_loc5`='不，謝了!以後有機會再說吧。還是過去。反正不是今天。', `FemaleText_loc7`='¡No, gracias! Quizá en el futuro. O en el pasado. Hoy no.' WHERE `ID`=45667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요, 그럴 수 없어요. 저는 여기 히포그리프 탑승장을 지키고 있어야 해요. 이 녀석들은 길이 잘 든 것처럼 보이긴 하지만, 24시간 내내 잘 지켜봐야 한답니다.', `FemaleText_loc4`='很抱歉，我不行。我的任务是看守这个角鹰兽哨站。这些角鹰兽看上去很驯顺，但它们的确需要二十四小时看管。', `FemaleText_loc5`='抱歉，我不可以。我被吩咐要看好這個角鷹獸哨站。這些角鷹獸雖然看似溫馴，但其實卻需要二十四小時全天看好牠們。', `FemaleText_loc7`='Lo siento, no puedo. Me han ordenado que vigile este puesto de hipogrifos. Estos bichos pueden parecer pacíficos, pero en realidad exigen vigilancia las veinticuatro horas del día.' WHERE `ID`=45668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세.', `MaleText_loc4`='向你致敬。', `MaleText_loc5`='你好。', `MaleText_loc7`='Saludos.' WHERE `ID`=45669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 무슨 일이오?', `MaleText_loc4`='你好，旅行者？', `MaleText_loc5`='有事嗎，旅行者?', `MaleText_loc7`='¿Sí, $gviajero:viajera;?' WHERE `ID`=45670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나게 되어 반갑습니다, $c님.', `FemaleText_loc4`='你好啊，$c。', `FemaleText_loc5`='又相遇了，$c。', `FemaleText_loc7`='Hola de nuevo, $c.' WHERE `ID`=45671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 뵙겠습니다.', `FemaleText_loc4`='这只是暂别。', `FemaleText_loc5`='再見了。', `FemaleText_loc7`='Adiós por ahora.' WHERE `ID`=45672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만날 때까지...', `MaleText_loc4`='我们会再见面的。', `MaleText_loc5`='下回再見。', `MaleText_loc7`='Hasta que nos volvamos a ver.' WHERE `ID`=45673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐마차 안에는 피오나와 동료들의 개인 소지품과 함께 상점에서 팔 물건이 상자에 담겨 있습니다.', `MaleText_loc4`='马车里放的都是装货物的箱子。还有菲奥拉和她的同伴们的一些私人物品。', `MaleText_loc5`='商隊的車上載著一箱箱的貨品，以及菲歐娜和她夥伴們的個人物品。', `MaleText_loc7`='Dentro de la caravana hay cajas de suministros para vendedores, junto con las pertenencias de Fiona y sus compañeros.' WHERE `ID`=45674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피오나의 짐마차에 타고 다음 목적지로 갑니다.', `MaleText_loc4`='乘菲奥拉的马车前往下一个目的地。', `MaleText_loc5`='登上菲歐娜的馬車到他們的下個目的地。', `MaleText_loc7`='Ve con la caravana de Fiona hasta su siguiente destino.', `FemaleText_loc1`='피오나의 짐마차에 타고 다음 목적지로 갑니다.', `FemaleText_loc4`='乘菲奥拉的马车前往下一个目的地。', `FemaleText_loc5`='登上菲歐娜的馬車到他們的下個目的地。', `FemaleText_loc7`='Ve con la caravana de Fiona hasta su siguiente destino.' WHERE `ID`=45675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 고고학자에게는 꿈만 같은 곳이오!$b$b제대로 발굴 작업을 할 시간이 있으면 얼마나 좋았을까!', `MaleText_loc4`='这个地方真是考古学家的梦想之地！$b$b真希望我能有时间进行一场彻底的考古发掘。', `MaleText_loc5`='這地方簡直就是考古學家朝思暮想之處!$b$b我真希望能有時間好好進行調查。', `MaleText_loc7`='¡Este lugar es el sueño de todo arqueólogo!$b$bOjalá hubiera tiempo para llevar a cabo una excavación como es debido.' WHERE `ID`=45676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 정말 끔찍한 땅입니다! 질척질척하고, 온통 나무 그루터기랑 바위 때문에 울퉁불퉁합니다. 새알심 넣은 팥죽처럼 말이죠. 진흙이 말 그대로 증기 전차를 삼켜 버린다고요.$B$B우리 장비가 전부 진흙탕 속에 빠져서는 호드한테 두들겨맞고 있단 말입니다!', `MaleText_loc4`='这里的地形真可怕！吸饱了地下水的泥土中混杂着许多树根和石块，就像一锅煮糊的麦片粥。黏软的泥浆甚至能把一辆蒸汽坦克吸进去。$B$B我们的设备全都陷在了泥里，还有部落的混蛋不停地给我们捣乱！', `MaleText_loc5`='這裡的地形真的太可怕了!地面跟海綿一樣，還有到處都是一堆堆的樹樁和石塊，活像發怒的燕麥粥。泥巴真的吞掉了一整台蒸汽坦克。$B$B我們的裝備全都陷在泥巴堆裡，害我們被部落打得落花流水!', `MaleText_loc7`='¡Este terreno es terrible! Suelo esponjoso lleno de bultos, piedras y tocones. Es como un cuenco de avena con tropezones. El lodo podría tragarse un tanque de vapor entero.$B$B¡Nuestro equipamiento está atascado en el barro y los de la Horda no dejan de golpearlo!' WHERE `ID`=45677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 어떻게 도와드리면 되겠습니까?', `MaleText_loc4`='我能帮什么忙？', `MaleText_loc5`='我能幫什麼忙嗎?', `MaleText_loc7`='¿Qué puedo hacer para ayudar?', `FemaleText_loc1`='제가 어떻게 도와드리면 될까요?', `FemaleText_loc4`='我能帮什么忙？', `FemaleText_loc5`='我能幫什麼忙嗎?', `FemaleText_loc7`='¿Qué puedo hacer para ayudar?' WHERE `ID`=45678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바쉬르로 돌아가시겠습니까?', `FemaleText_loc4`='你需要返回瓦丝琪尔吗？', `FemaleText_loc5`='你需要返回瓦許伊爾嗎?', `FemaleText_loc7`='¿Necesitas volver a Vashj''ir?' WHERE `ID`=45679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조셉 레드패스의 병사들과 함께 다로우골을 지켜야 합니다!', `MaleText_loc4`='帮助约瑟夫·卡林的部队守卫达隆郡！', `MaleText_loc5`='協助約瑟夫·卡林的部隊防守達隆郡!', `MaleText_loc7`='¡Ayuda a las tropas de Joseph Carlin a defender Villa Darrow!' WHERE `ID`=45680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다빌 라이트파이어를 보호해야 합니다!', `MaleText_loc4`='保护达维·莱法尔！', `MaleText_loc5`='保護達維·萊法爾!', `MaleText_loc7`='¡Protege a Davil Fuegoluz!' WHERE `ID`=45681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약탈자 호르구스가 나타났습니다! 빨리 처치해야 합니다!', `MaleText_loc4`='掠夺者霍古斯出现了，快消灭他！', `MaleText_loc5`='『劫毀者』霍古斯出現了!快點殺掉他!', `MaleText_loc7`='¡Ha aparecido Horgus el Devastador! ¡Mátalo rápidamente!' WHERE `ID`=45682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비대장 레드패스가 전장에 나타났습니다! 그를 보호해야 합니다!', `MaleText_loc4`='雷德帕斯队长出现在战场上了！保护他！', `MaleText_loc5`='雷德帕斯隊長出現在戰場上了!保護他!', `MaleText_loc7`='¡Ha aparecido el capitán Rutagrana en el campo de batalla! ¡Protégelo!' WHERE `ID`=45683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비대장 조셉 레드패스가 오염되었습니다! 빨리 처치해야 합니다!', `MaleText_loc4`='约瑟夫·雷德帕斯队长被腐蚀了！快杀死他！', `MaleText_loc5`='約瑟夫·雷德帕斯已經墮落了!快點殺掉他!', `MaleText_loc7`='¡Han corrompido al capitán Joseph Rutagrana! ¡Mátalo rápidamente!' WHERE `ID`=45684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다로우골 중앙에서 조셉 레드패스와 대화해야 합니다.', `MaleText_loc4`='同约瑟夫·雷德帕斯谈谈。他就在达隆郡中心。', `MaleText_loc5`='與達隆郡中央的約瑟夫·雷德帕斯交談。', `MaleText_loc7`='Habla con Joseph Rutagrana en el centro de Villa Darrow.' WHERE `ID`=45685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 물러나시오, $n. $g당신이:당신의 예쁜 얼굴이; 다치길 바라지는 않으니까.', `MaleText_loc4`='靠后站，$n。我们不想让你$g:这样漂亮的小东西;受伤。', `MaleText_loc5`='退後就對了，$n。我們可不希望害$g你:妳這美女;受傷。', `MaleText_loc7`='Apártate, $n. No queremos que una florecilla silvestre como tú se haga daño.' WHERE `ID`=45686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 바쉬르로 보내 주십시오.', `MaleText_loc4`='是的，请带我去瓦丝琪尔。', `MaleText_loc5`='是，請帶我去瓦許伊爾。', `MaleText_loc7`='Sí. Llévame a Vashj''ir, por favor.', `FemaleText_loc1`='네, 바쉬르로 보내 주세요.', `FemaleText_loc4`='是的，请带我去瓦丝琪尔。', `FemaleText_loc5`='是，請帶我去瓦許伊爾。', `FemaleText_loc7`='Sí. Llévame a Vashj''ir, por favor.' WHERE `ID`=45687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라지 마십시오. 저는 보기와는 다른 존재입니다.$B$B제 이름은 아크리도스트라즈입니다. 그냥 아크라이드라고 불러 주십시오. 저희 여왕님께서 네파리안을 막으라고 절 이리 보내셨지요. 저는 임무를 완수할 때까지 쉬지 않을 것입니다. 그러나 네파리안의 둥지를 지키는 적들을 저 혼자 감당할 수가 없군요.$B$B놈들을 처리하는 데 힘을 보태 준다면 알렉스트라자 님이 당신에게 호의를 보이실 것입니다. 어쩌면 그분의 이름을 모르실 수도 있겠지요. 하지만 그렇다고 해도, 언젠가 절 도와줘서 다행이라 생각할 날이 반드시 올 것입니다.', `MaleText_loc4`='别害怕。我其实并不像外表显示的这样可怕。$B$B我的名字是阿克莱多斯塔兹，你可以称呼我阿克莱德。我的女王派我到这里来阻止奈法利安。在任务完成之前，我绝不会休息。但这里还有一些敌人守卫着他的巢穴。仅凭我的力量是无法战胜他们的。$B$B请帮我消灭掉他们。阿莱克丝塔萨一定会因此而感激你。也许你还不知道这个名字，但我相信，你总有一天会因为今天帮助了我而感到庆幸。', `MaleText_loc5`='切莫驚慌，這外貌並非我的實體。$B$B我的名字叫做阿克瑞多斯塔茲，或者你也可以叫我阿克萊德。龍后派我來此阻止奈法利安，而在完成這任務之前我絕對不會停手。但是，我無法獨立對抗看守他巢穴的其他護衛。$B$B協助我解決他們，你將獲得雅立史卓莎的感謝。你或許還不曉得這個名字，但是相信我，將來有一天你必定會慶幸自己有幸得知她的名號。', `MaleText_loc7`='No te alarmes. No soy lo que parezco.$b$bMe llamo Acridostrasz, aunque puedes llamarme Acride. Mi Reina me ha enviado para detener a Nefarian, y no descansaré hasta que haya completado mi tarea. Sin embargo, hay más enemigos custodiando su guarida de los que puedo despachar solo.$b$bAyúdame a eliminarlos y obtendrás el favor de Alexstrasza. Es posible que no conozcas ese nombre, pero algún día te alegrarás de conocerlo. De eso estoy seguro.' WHERE `ID`=45688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 시작하겠소.', `MaleText_loc4`='我们开始吧。', `MaleText_loc5`='我們開始吧。', `MaleText_loc7`='Comencemos.' WHERE `ID`=45689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참관자가 더 필요하신 것 아닙니까?', `MaleText_loc4`='我们不需要再多找点儿见证人吗？', `MaleText_loc5`='我們不需要有更多的見證者嗎?', `MaleText_loc7`='¿No vamos a tener más testigos?' WHERE `ID`=45690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거창하게 일을 벌이고 싶지는 않소. 과장된 언동은 허영심만 부추길 뿐이오. 하지만 그대가 잔치라도 벌이길 원한다면...', `MaleText_loc4`='我不希望大肆张扬。如此轻率的举动代价高昂，而且仅仅能满足我们的虚荣心而已。但如果你希望庆祝一下的话……', `MaleText_loc5`='我並不希望大張旗鼓，這種愚蠢的舉止不僅代價昂貴，所滿足的也只有我們的虛榮心而已。但是如果你希望能辦一場慶典的話...', `MaleText_loc7`='No quiero hacer de esto un espectáculo. Semejantes frivolidades son costosas y solo obedecen a nuestra vanidad. Pero si deseas una celebración...' WHERE `ID`=45691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다. 대족장님, 이 정도면 충분한 것 같습니다.', `MaleText_loc4`='不，酋长，这就够了。', `MaleText_loc5`='不，大酋長，這就夠了。', `MaleText_loc7`='No, Jefe de Guerra, es suficiente.' WHERE `ID`=45692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 지금이 호드에게는 시련의 시기란 사실을 잘 알고 있을 것이오. 자원은 고갈되고, 땅은 황폐해지고 있소. 우리의 전사들에게는 휴식이 필요하오. 우리 호드가 번영하려면 이런 문제들이 해결되어야 하오.', `MaleText_loc4`='你知道眼下正是部落的困难时期。我们的补给日渐匮乏。我们的土地日益贫瘠。我们的战士们疲惫不堪。为了部落的利益，这些都是亟待解决的问题。', `MaleText_loc5`='你知道，部落正處於動盪不安的難關，我們的補給短缺，我們的土地荒蕪，我們的戰士急需歇息。這些都是為了部落的長治久安而必須面對的工作。', `MaleText_loc7`='Sabes que son tiempos difíciles para la Horda. Nuestros suministros escasean. Nuestras tierras son estériles. Nuestros guerreros necesitan descansar. Son tareas que debemos afrontar por el bien de la Horda.' WHERE `ID`=45693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서 우리의 성공적인 위업으로 모두가 기뻐하고 있는 줄로 아네만...', `MaleText_loc4`='人们会为我们在诺森德取得的成功而感到欣喜。', `MaleText_loc5`='人民對我們在北裂境的成功都感到欣喜萬分。', `MaleText_loc7`='La gente eh''tá contenta con nueh''tro éxito en Rasganorte.' WHERE `ID`=45694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"우리"의 위업이라 했소? 트롤이여, 당신은 노스렌드에서 호드가 거둔 승리에 조금도 보탬이 되지 않았소. 내가 전사들을 이끌고 리치 왕에 대적하는 동안 당신은 작은 섬 몇 개를 되찾느라 바쁘지 않았소.', `MaleText_loc4`='我们的成功？巨魔，部落在诺森德所取得的胜利与你毫无关系。当我带领我们的战士对抗巫妖王时，你只不过在忙着收回几个散落的岛屿。', `MaleText_loc5`='「我們」的成功?食人妖，部落在北裂境的勝利根本沒有你的功勞。當我率領戰士在和巫妖王對抗的時候，你不過是奪回了幾座零星的小島而已。', `MaleText_loc7`='¿"Nuestro" éxito? Trol, no has tenido nada que ver en las victorias de la Horda en Rasganorte. Mientras yo lideraba a nuestros guerreros contra el Rey Exánime, tú no hiciste más que recuperar un puñado de islotes.' WHERE `ID`=45695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말조심하게, 젊은이. 자네는...', `MaleText_loc4`='小心你的言行，年轻人。你不会——', `MaleText_loc5`='年輕人，小心你講的話。你不－', `MaleText_loc7`='Cuidado, joven. No...' WHERE `ID`=45696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬! 볼진! 둘 다 입 다무시오! 우린 지금 더 큰 문제를 눈앞에 두고 있단 말이오.', `MaleText_loc4`='加尔鲁什！沃金！注意你们的言辞。眼下还有更要紧的事情。', `MaleText_loc5`='卡爾洛斯!沃金!都別說了，我們還有更重要的事情得處理。', `MaleText_loc7`='¡Garrosh! ¡Vol''jin! Controlen sus lenguas. Tenemos problemas más importantes.' WHERE `ID`=45697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부족한 인내심을 용서하게. 대족장이여, 계속하게나.', `MaleText_loc4`='请原谅我的无礼。酋长，请继续。', `MaleText_loc5`='原諒我一時失態了，大酋長，請你繼續講吧。', `MaleText_loc7`='Perdona mi arrebato, Jefe de Guerra. Por favor, continúa.' WHERE `ID`=45698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에서의 성공적인 위업에도, 우리는 지금 칼과 도끼로는 해결할 수 없는 심각한 문제에 맞닥뜨리고 있소. 지진이 땅을 뒤흔들고, 정령들은 도시 주변을 휘젓고 다니며 파괴하고 있소. 우리의 영토, 아제로스가 고통에 울부짖는 소리가 메아리치고 있소.', `MaleText_loc4`='尽管我们在诺森德取得了成功，我们却面临着无法用刀剑解决的更大难题。地震使各地战栗不已。元素在乡间肆虐妄为。我能听见我们的大地——听见艾泽拉斯，在痛苦地哀号。', `MaleText_loc5`='儘管我們在北裂境的戰事獲得了成功，但是如今我們所面對的嚴重問題卻不是光靠刀劍與斧頭就能解決得了。地震撼動了每塊土地，元素在鄉野間肆虐。我聽到了我們的土地艾澤拉斯，發出了痛苦的吶喊。', `MaleText_loc7`='A pesar de nuestro éxito en Rasganorte, nos enfrentamos a problemas muy serios que no podemos resolver solo con el hacha y la espada. Los terremotos sacuden todas las regiones. Los elementales asolan la provincia. Puedo oír cómo nuestra tierra, Azeroth, grita de agonía.' WHERE `ID`=45699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 떠나셔야 하는 이유겠지요.', `MaleText_loc4`='这些就是你必须离开的原因。', `MaleText_loc5`='這些正是你必須要離開的原因。', `MaleText_loc7`='Por eso debes partir.' WHERE `ID`=45700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벨몬트, 너는 어떻게 할 텐가? 어떻게 돌아갈 생각인가?', `FemaleText_loc4`='你呢，贝尔蒙特？你要怎样回去？', `FemaleText_loc5`='那你呢，貝爾蒙特?你要怎樣回來?', `FemaleText_loc7`='¿Y qué será de ti, Belmont? ¿Cómo vas a volver?' WHERE `ID`=45701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 말게, 아투라. 늑대인간은 우리 냄새를 잃어버렸으니, 우리가 여기 있는지도 모를 거야.', `MaleText_loc4`='我不会有事的，阿尔苏拉。狼人不知道我们的气味。他们甚至可能不知道我们就在这里。', `MaleText_loc5`='我不會有事的，阿爾蘇拉。狼人已失去了我們的氣味，我甚至懷疑他們是否知道我們在這裡。', `MaleText_loc7`='Estaré bien, Arthura. Los huargen han perdido nuestro rastro. Dudo que sepan que estamos aquí.' WHERE `ID`=45702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너희 둘, 아니, 세 명보다 먼저 포세이큰 전초지에 도착할 수 있을 걸세.', `MaleText_loc4`='也许我能抢在你们两个……呃……三个前面回到被遗忘者先锋军。', `MaleText_loc5`='說不定我還會比你們兩個，呃，三個，更早回到被遺忘者戰事前線。', `MaleText_loc7`='Lo más probable es que llegue al Frente Renegado antes que ustedes dos, eh, tres.' WHERE `ID`=45703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 출발하게! 밴시 여왕님을 기다리게 해서는 안 돼.', `MaleText_loc4`='现在就行动！绝不能让女妖之王等待。', `MaleText_loc5`='出發吧!你們絕不能讓女妖之王久等。', `MaleText_loc7`='¡Ahora marchad! No debéis hacer esperar a la Reina alma en pena.' WHERE `ID`=45704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 자네와 자네 주머니 속에 있는 동전을 언제나 환영이라네.', `MaleText_loc4`='这里的大门永远都向你和你的钱敞开着。', `MaleText_loc5`='這裡「永遠」歡迎你和你的錢。', `MaleText_loc7`='Tu dinero y tú siempre sois bienvenidos.', `FemaleText_loc1`='여기서는 당신과 당신 주머니 속에 있는 동전을 언제나 환영합니다.', `FemaleText_loc4`='这里的大门永远都向你和你的钱敞开着。', `FemaleText_loc5`='這裡「永遠」歡迎你和你的錢。', `FemaleText_loc7`='Tu dinero y tú siempre sois bienvenidos.' WHERE `ID`=45705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았다, 벨몬트. 작별의 시간이군.', `FemaleText_loc4`='就这样吧，再见，贝尔蒙特。', `FemaleText_loc5`='就這樣吧。再見了，貝爾蒙特。', `FemaleText_loc7`='Así sea. Adiós, Belmont.' WHERE `ID`=45706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런... 꽉 잡아라!', `FemaleText_loc4`='天哪……抓紧！', `FemaleText_loc5`='哦天啊...抓緊了!', `FemaleText_loc7`='¡Ah! ¡Agárrate fuerte!' WHERE `ID`=45707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 형제들이여! 저 $r|1을;를; 공격하라!', `MaleText_loc4`='兄弟们！攻击这个$r！', `MaleText_loc5`='就是現在!弟兄們，攻擊那個$r!', `MaleText_loc7`='¡Ahora, hermanos! ¡Atacad $gal:a la; $r!' WHERE `ID`=45708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 싸울 필요는 없네, $r. 자네를 해칠 생각은 없어.', `MaleText_loc4`='你不需要和我作战，$r。我对你没有恶意。', `MaleText_loc5`='你不需要與我為敵，$r。我對你毫無惡意。', `MaleText_loc7`='No tienes por qué luchar conmigo, $r. No te deseo ningún mal.' WHERE `ID`=45709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 다시 한 번 치를 수 있겠습니까, 벡스툴?', `MaleText_loc4`='我可以再次接受你的测试吗，维克斯图？', `MaleText_loc5`='我可以再考一次嗎，維克斯圖爾?', `MaleText_loc7`='¿Puedo someterme a tu prueba de nuevo, Vex''tul?', `FemaleText_loc1`='시험을 다시 한 번 치를 수 있을까요, 벡스툴?', `FemaleText_loc4`='我可以再次接受你的测试吗，维克斯图？', `FemaleText_loc5`='我可以再考一次嗎，維克斯圖爾?', `FemaleText_loc7`='¿Puedo someterme a tu prueba de nuevo, Vex''tul?' WHERE `ID`=45710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호튼이 가까이에 있는 낡은 배로 움직입니다.', `MaleText_loc4`='荷尔登示意你到那艘破旧的小船旁边去。', `MaleText_loc5`='荷頓指著旁邊那艘搖搖晃晃的小艇。', `MaleText_loc7`='Horton señala el barco fluvial destartalado cercano.' WHERE `ID`=45711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하의 요청에 따라 이렇게 얼라이언스에 충성하는 전사를 모시게 되어 영광이네요.', `MaleText_loc4`='能够执行乌瑞恩国王的任务，帮助一位效忠于联盟的战士，这是我的光荣。', `MaleText_loc5`='能為如此忠於聯盟的戰士宣達烏瑞恩王的託付，是我的榮耀。', `MaleText_loc7`='Será un honor llevar a cabo la comisión del rey Wrynn para $gun guerrero:una guerrera; tan $gdedicado:dedicada; a la Alianza.' WHERE `ID`=45712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7의 친구는 저의 친구죠. 저에게 칼을 겨눌 사람에게 무기를 만들어 줄 생각은 없어요. 암요, 그렇고 말고요.', `MaleText_loc4`='任何军情七处的朋友也就是我的朋友。你大概不会想要站在我的刀锋所指的地方吧？', `MaleText_loc5`='軍情七處的朋友就是我的朋友。刀劍不長眼，你可不想被我的武器給劈著了，是吧?', `MaleText_loc7`='Todos los amigos del IV:7 son amigos míos. No quiero acabar viéndomelas con mi propia espada, ¿entiendes?' WHERE `ID`=45713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전차가 쓰레기 속에 처박혔는데, 증기 압력이 낮아서 어떻게 해볼 수가 없군. 정말 끔찍한 땅이야!$B$B우리 좀 꺼내줄 수 있겠나?', `MaleText_loc4`='她被困在了这堆垃圾里，而我已经失去了蒸汽动力。这里的地面太泥泞了！$B$B你能帮我们离开这里么？', `MaleText_loc5`='它被卡住了，而且我也沒有蒸汽動力了。這種地形簡直要人命啊!$B$B你可以幫我們脫困嗎?', `MaleText_loc7`='Se ha atascado en el lodo y he perdido presión de vapor. ¡Este terreno es una tortura!$b$b¿Puedes sacarnos de aquí?', `FemaleText_loc1`='전차가 쓰레기 속에 처박혔는데, 증기 압력이 낮아서 어떻게 해볼 수가 없군요. 정말 끔찍한 땅이에요!$B$B저희 좀 꺼내줄 수 있나요?', `FemaleText_loc4`='她被困在了这堆垃圾里，而我已经失去了蒸汽动力。这里的地面太泥泞了！$B$B你能帮我们离开这里么？', `FemaleText_loc5`='它被卡住了，而且我也沒有蒸汽動力了。這種地形簡直要人命啊!$B$B你可以幫我們脫困嗎?', `FemaleText_loc7`='Se ha atascado en el lodo y he perdido presión de vapor. ¡Este terreno es una tortura!$b$b¿Puedes sacarnos de aquí?' WHERE `ID`=45714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s|1이;가; |cFFFF0000|Hspell:82299|h[피 악화]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s开始施放|cFFFF0000|Hspell:82299|h[脓血]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s開始施展|cFFFF0000|Hspell:82299|h[潰爛血污]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_shadetruesight.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:82299|h[Infestar sangre]|h|r!' WHERE `ID`=45715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나 당연한 얘기지만, 빛을 섬기고 얼라이언스에 충성하는 강직한 분을 위해 일할 수 있어 정말 영광이에요.', `MaleText_loc4`='毋庸置疑，能够为圣光和联盟效忠肯定是一种无上的光荣。', `MaleText_loc5`='不用說，能為這麼一位傑出的聖光與聯盟的忠僕工作是我的榮幸。', `MaleText_loc7`='Huelga decir que es un honor trabajar para $gun súbdito:una súbdita; de la Luz y de la Alianza de semejante rectitud.' WHERE `ID`=45716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 부품이 좀 있습니다! 수리하시는 동안 제가 지켜 드리지요!', `MaleText_loc4`='这里有一些多余的零件。当你进行修理的时候，我会掩护你！', `MaleText_loc5`='這兒有一些備用的零件，我會在你進行維修的時候掩護你!', `MaleText_loc7`='Aquí tienes unas piezas de repuesto. ¡Te cubriré mientras realizas las reparaciones!', `FemaleText_loc1`='여기 부품이 좀 있습니다! 수리하시는 동안 제가 지켜 드리지요!', `FemaleText_loc4`='这里有一些多余的零件。当你进行修理的时候，我会掩护你！', `FemaleText_loc5`='這兒有一些備用的零件，我會在你進行維修的時候掩護你!', `FemaleText_loc7`='Aquí tienes unas piezas de repuesto. ¡Te cubriré mientras realizas las reparaciones!' WHERE `ID`=45717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네, 부하들이 작업하는 동안 전차를 지켜 주게! 난 전차를 움직일 방도를 찾아보겠네...', `MaleText_loc4`='嘿，在孩子们进行修理的时候一定要保护好坦克！我会努力让她动起来……', `MaleText_loc5`='對，在兄弟們忙著維修的時候保護好坦克!我會努力讓它再動起來...', `MaleText_loc7`='¡Sí, protege el tanque mientras los chicos reparan! Intentaré que se vuelva a mover...', `FemaleText_loc1`='좋아요, 부하들이 작업하는 동안 전차를 지켜 주세요! 전 전차를 움직일 방도를 찾아보지요...', `FemaleText_loc4`='嘿，在孩子们进行修理的时候一定要保护好坦克！我会努力让她动起来……', `FemaleText_loc5`='對，在兄弟們忙著維修的時候保護好坦克!我會努力讓它再動起來...', `FemaleText_loc7`='¡Sí, protege el tanque mientras los chicos reparan! Intentaré que se vuelva a mover...' WHERE `ID`=45718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가마솥에서 거품이 거칠게 부글거립니다.', `MaleText_loc4`='锅炉开始猛烈地冒起了气泡。', `MaleText_loc5`='大鍋劇烈著冒著泡泡。', `MaleText_loc7`='La caldera burbujea intensamente.' WHERE `ID`=45719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베티나가 말한 대로 용액을 한 방울만 넣습니다.', `MaleText_loc4`='按照贝蒂娜的要求，倒入一滴液体。', `MaleText_loc5`='依照貝蒂娜的要求，倒一滴進去。', `MaleText_loc7`='Poner una gota de líquido, como pidió Betina.', `FemaleText_loc1`='베티나가 말한 대로 용액을 한 방울만 넣습니다.', `FemaleText_loc4`='按照贝蒂娜的要求，倒入一滴液体。', `FemaleText_loc5`='依照貝蒂娜的要求，倒一滴進去。', `FemaleText_loc7`='Poner una gota de líquido, como pidió Betina.' WHERE `ID`=45720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플라스크 하나에 담긴 용액을 모두 넣습니다.', `MaleText_loc4`='倒入一整瓶液体。', `MaleText_loc5`='把整個燒瓶扔進去。', `MaleText_loc7`='Lanzar un frasco entero.', `FemaleText_loc1`='플라스크 하나에 담긴 용액을 모두 넣습니다.', `FemaleText_loc4`='倒入一整瓶液体。', `FemaleText_loc5`='把整個燒瓶扔進去。', `FemaleText_loc7`='Lanzar un frasco entero.' WHERE `ID`=45721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플라스크 12병을 모두 넣습니다.', `MaleText_loc4`='倒入全部12瓶液体。', `MaleText_loc5`='把全部12個燒瓶都扔進去。', `MaleText_loc7`='Lanzar los 12 frascos.', `FemaleText_loc1`='플라스크 12병을 모두 넣습니다.', `FemaleText_loc4`='倒入全部12瓶液体。', `FemaleText_loc5`='把全部12個燒瓶都扔進去。', `FemaleText_loc7`='Lanzar los 12 frascos.' WHERE `ID`=45722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신이 정령과 대화를 나누듯, 쇠붙이와 대화를 나눌 순 없어요. 그래도 이 무기를 유용하게 사용하셨으면 좋겠네요. 린 국왕 폐하와 선견자 노분도 님께서 당신에게 건 기대가 엄청나답니다.', `MaleText_loc4`='这些金属可不会像元素对你说话那样对我说话，但我希望你会发现这件武器值得你这样做。乌瑞恩国王和你们的先知都对你的能力有着很大的信心。', `MaleText_loc5`='元素們會跟你交談，但是金屬卻不會跟我說話。不過，我還是希望這把武器能和你的意。烏瑞恩王和你的先知都很信任你的能力。', `MaleText_loc7`='Los metales no me hablan de la misma forma que los elementos te hablan a ti, pero espero que esta arma te parezca digna. El rey Wrynn y tu clarividente tienen una gran confianza en tus habilidades.' WHERE `ID`=45723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 달빛강철로 작업한 지 한참 지났지만, 그 기술은 아직 기억하고 있죠. 데인, 모루로 와서 좀 거들어라.', `MaleText_loc4`='我上次加工月钢已经是多年以前的事情了，但我还没有忘记这个技术。丹恩，到铁砧旁去等我。', `MaleText_loc5`='我上回鑄造月鋼的武器已經是好多年前的事情了，但是我並沒有忘掉鑄造的技巧。丹恩，跟我到鐵砧這邊來。', `MaleText_loc7`='Hace años que no trabajo el acero lunar, pero no he olvidado la técnica. Dane, reúnete conmigo en el yunque.' WHERE `ID`=45724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 무기가 준비되었어요, $n 님. 이 무기를 휘두르는 당신의 모습이 얼라이언스를 따르는 모든 이에게 귀감이 되길 바랄게요.', `MaleText_loc4`='你的武器完成了，$n。用它去夺取光荣，为所有联盟的成员树立榜样吧。', `MaleText_loc5`='你的武器已經好了，$n。好好善用它，讓所有效忠聯盟的人都能把你當作效法的榜樣。', `MaleText_loc7`='Tu arma está terminada, $n. Blándela y da ejemplo a todos los súbditos de la Alianza.' WHERE `ID`=45725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 일도 일어나지 않습니다. 역병 가마솥의 내용물이 엉망이 되었을 수는 있지만, 눈으로 확인할 수는 없습니다. 어떻게 할까요?', `MaleText_loc4`='似乎什么事都没有发生。天灾之锅也许已经被毁掉了，但它看上去的确和以前没什么两样。你要怎样做？', `MaleText_loc5`='什麼事情都沒有發生。瘟疫大鍋或許已經被毀了，但是外表絲毫看不出任何不同。你要怎麼做?', `MaleText_loc7`='No parece suceder nada. Puede que la caldera de peste esté arruinada, pero no parece diferente. ¿Qué vas a hacer?' WHERE `ID`=45726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 일도 하지 않습니다. 베티나가 한 방울만 필요하다고 했습니다.', `MaleText_loc4`='什么都不做。贝蒂娜说过，只需要一滴就够了。', `MaleText_loc5`='什麼都不要做。貝蒂娜說只要一滴就夠了。', `MaleText_loc7`='No hacer nada. Betina dijo que una sola gota bastaría.', `FemaleText_loc1`='아무 일도 하지 않습니다. 베티나가 한 방울만 필요하다고 했습니다.', `FemaleText_loc4`='什么都不做。贝蒂娜说过，只需要一滴就够了。', `FemaleText_loc5`='什麼都不要做。貝蒂娜說只要一滴就夠了。', `FemaleText_loc7`='No hacer nada. Betina dijo que una sola gota bastaría.' WHERE `ID`=45727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 모두 준비되었소. 마그니, 무슨 문제로 이 모임을 요청한 건지 말해보시오.', `MaleText_loc4`='我们准备好了。麦格尼，是你召集了此次会议。是什么困扰着你？', `MaleText_loc5`='我們可以開始了。麥格尼，你召見我們來開這場會，你在擔心什麼?', `MaleText_loc7`='Estamos listos para continuar. Magni, tú has convocado esta reunión. ¿Qué te preocupa?' WHERE `ID`=45728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 지난 몇 주 동안 발생한 지진을 직접 몸으로 느꼈을 걸세. 그런데 무언가 석연치 않은 부분이 있네.', `MaleText_loc4`='你们肯定已经注意到在过去几周内发生的数次地震。这让我感到有些蹊跷。', `MaleText_loc5`='你們必定有注意到最近這幾個禮拜所發生的一連串地震。這些地震並不尋常。', `MaleText_loc7`='Sin duda habrás notado la cadena de terremotos que hemos sufrido estas últimas semanas. Pasa algo raro con ellos.' WHERE `ID`=45729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 무슨 뜻이죠?', `FemaleText_loc4`='什么意思？', `FemaleText_loc5`='這話是什麼意思?', `FemaleText_loc7`='¿A qué te refieres?' WHERE `ID`=45730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 드워프들은 대지와 연결되어 있네. 대지의 고통을 느낄 수 있지. 그런데 지금 대지가 울부짖고 있네. 이 지진은... 자연적 현상이지만, 동시에 초자연적이기도 하네. 그래서 이 문제를 논의하기 위해 그대들을 부른 거라네.', `MaleText_loc4`='我们矮人与大地之间存在着联结。我们能感觉到她的痛苦。而大地此刻正在哀号。这些地震……它们既是自然形成但也非全然如此。我想要将你们聚集在一起，共同商讨对策。', `MaleText_loc5`='我們矮人與大地緊密相連，我們可以感受到她的痛苦，而如今大地正在痛苦地吶喊。這些地震...它們既是正常的，也是異常的。我想要召集大家來一起討論這件事。', `MaleText_loc7`='Los enanos tenemos una conexión con la tierra. Podemos sentir su dolor, y ahora mismo está gritando. Estos terremotos... Son naturales y antinaturales al mismo tiempo. Quería reunirme con ustedes para hablar de ellos.' WHERE `ID`=45731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다르나서스에서도 대지가 무언가와 불화에 휩싸였음을 느낄 수 있었습니다.', `FemaleText_loc4`='即使是在达纳苏斯，我们都感到大地有些不对劲。', `FemaleText_loc5`='即便在達納蘇斯，我們也察覺到了大地確實有所異樣。', `FemaleText_loc7`='En Darnassus también hemos percibido que la tierra está alterada.' WHERE `ID`=45732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드에 있는 내 동생 브란에게서 연락을 받았네. 울두아르를 탐험하던 중 특이한 석판... 고대의 유물로 보이는 물건을 발견했다고 하더군.', `MaleText_loc4`='我在诺森德的兄弟布莱恩传来了消息。在他探索奥杜尔的过程中，他见到了一些很不寻常的石板……年代相当久远。', `MaleText_loc5`='我收到我弟弟在北裂境傳來的訊息，說他在奧杜亞探險的時候找到了幾個不尋常的石板...而且是非常古老的。', `MaleText_loc7`='Me ha llegado un mensaje de mi hermano Brann desde Rasganorte. Mientras exploraba Ulduar se ha encontrado con unas tablillas poco comunes... Algo antiguo.' WHERE `ID`=45733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 끔찍한 곳은 단 한 번도 우리에게 도움이 된 적이 없소.', `MaleText_loc4`='那鬼地方没出过什么好东西。', `MaleText_loc5`='那個可怕的地方不會有任何好事。', `MaleText_loc7`='Nada bueno ha salido de ese horrible lugar.' WHERE `ID`=45734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 생각을 바꾸게 될 걸세. 지금 브란이 석판을 이리로 가져오고 있네. 탐험가 연맹의 예비 보고서를 보면 석판이 지진 현상에 대한 해답을 찾는데 도움을 줄 수 있을 것이라고 적혀 있다네.', `MaleText_loc4`='这也许恰恰能改变你的看法。此时布莱恩正在将那些石板运送到这里。从探险者协会的初步报告看来，这些石板也许能帮我们理解这些地震背后的真相。', `MaleText_loc5`='這或許會改變你的看法。就在此時，布萊恩已經把石板送出來給我了。探險者協會初步的報告指出，它們或許能協助我們瞭解這些頻繁的地震究竟是怎麼一回事。', `MaleText_loc7`='Quizá esto te haga cambiar de opinión. Brann me ha enviado las tablillas y ahora mismo estarán de camino. Los informes preliminares de la Liga de Expedicionarios dicen que podrían ayudarnos a entender qué pasa con los terremotos.' WHERE `ID`=45735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 수석 연구원들도 지진 현상을 조사하고 있는데... 음, 주로 가상의 지각변동을 일으키면서 어떻게 건물의 골조를 유지할 수 있을지에 대한 연구에 몰두하고 있죠...
', `MaleText_loc4`='我们的顶尖人才一直在探究这些地震活动……嗯，我们主要是在模拟地壳构造转变的同时，研究如何稳固住建筑物的框架……', `MaleText_loc5`='我們的頂尖學者們已經在研究地震活動的相關問題...好吧，我們主要的研究重點是在如何強化建築的結構，同時也在模擬地殼的變動...', `MaleText_loc7`='Nuestras mentes más brillantes han estudiado la actividad sísmica... Bueno, en rigor hemos estudiado la seguridad estructural de los edificios al mismo tiempo que simulamos corrimientos tectónicos...' WHERE `ID`=45736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 거기서 이사해 나가신 건가요?', `FemaleText_loc4`='那就是你迁出来的原因吗？', `FemaleText_loc5`='這就是你們搬了出去的原因?', `FemaleText_loc7`='¿Por eso has abandonado Forjaz?' WHERE `ID`=45737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 그건 절대 아니죠! 정말 기막힌 우연의 일치라고나 할까. 놈리건이 우리 종족을 계속 욕보이고 있어요. 이젠 우리의 고향을 되찾아야 할 때가 된 거죠.', `MaleText_loc4`='哈，才不是呢！尽管这是个令人惊异的巧合。诺莫瑞根一直都在令我们的人民蒙羞。我们早该夺回自己的家园了。', `MaleText_loc5`='哈，並非如此!儘管這是個驚人的巧合。諾姆瑞根一直以來都讓我們地精蒙羞，我們早就應該要奪回我們的家園才對。', `MaleText_loc7`='¡Ja! Nada más lejos, aunque es una gran coincidencia. Gnomeregan ha sido y sigue siendo una gran vergüenza para nuestra gente. Ya va siendo hora de que recuperemos nuestro hogar.' WHERE `ID`=45738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 오히려 잘 된 일일수도 있으니 다행이군...땜장이왕, 당신과 당신 동족에겐 말이오. 하지만 우리 모두가 당신들처럼 왕국을 들어 옮길 수는 없소.', `MaleText_loc4`='嗯，局面在朝着……有利于你和你人民的方向转变，这很不错，大工匠。可并非我们所有人都能如此奢侈地将自己的王国迁走。', `MaleText_loc5`='嗯，很高興你和地精們都獲得了...更好的生活，大工匠。不過，我們可沒有遷移整個王國的餘裕啊。', `MaleText_loc7`='Bueno, está bien que las cosas hayan... ido a mejor para ti y para tu gente, Manitas Mayor. Pero no todos podemos permitirnos el lujo de mover nuestros reinos y llevárnoslos a otro sitio.' WHERE `ID`=45739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빈센트 고드프리 경, 이제 일어나라. 내 복수의 도구가 되어 다시 태어나라!', `FemaleText_loc4`='起来，文森特·高弗雷爵士，重生成为我复仇的工具吧！', `FemaleText_loc5`='起來吧，文森·高佛雷領主，重生為我復仇的使者吧!', `FemaleText_loc7`='Álzate, Lord Vincent Godfrey. ¡Renace como instrumento de mi venganza!' WHERE `ID`=45740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 다시 태어났다...', `MaleText_loc4`='我又活了……', `MaleText_loc5`='我重返人間...', `MaleText_loc7`='Vivo de nuevo...' WHERE `ID`=45741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 태어난 네 목숨은 나를 위해 바쳐라. 우리는 함께 늑대인간의 폭동을 진압하고 길니아스를 다시 포세이큰의 손에 되돌려 놓을 것이다.', `FemaleText_loc4`='重生的你将效忠于我，高弗雷。我们将一起粉碎狼人的叛乱，为被遗忘者夺回吉尔尼斯。', `FemaleText_loc5`='你重返人間來服侍我，高佛雷。我們將一同壓制狼人暴動，為被遺忘者重新奪下吉爾尼斯。', `FemaleText_loc7`='Vuelves para servirme, Godfrey. Juntos aplastaremos la insurrección de los huargen y retomaremos Gilneas para los Renegados.' WHERE `ID`=45742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 손이겠지...', `MaleText_loc4`='为了部落……', `MaleText_loc5`='為了部落...', `MaleText_loc7`='Para la Horda...' WHERE `ID`=45743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 그렇다...', `FemaleText_loc4`='是的，当然……', `FemaleText_loc5`='是，當然...', `FemaleText_loc7`='Sí, claro...' WHERE `ID`=45744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 다시 태어난 내가 얼마나 역설적인 존재인지는 나도 잘 알고 있소, 실바나스 여왕.', `MaleText_loc4`='那些讽刺我当前处境的话，我都已经听见了，希尔瓦娜斯女王。', `MaleText_loc5`='我充分了解如今我這樣子所代表的諷刺意味，希瓦娜斯女王。', `MaleText_loc7`='No se me escapa la ironía de lo que me he convertido, Lady Sylvanas.' WHERE `ID`=45745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 나의 생각은 변함이 없소. 늑대인간이 되느니 차라리 죽음을 택하겠소.', `MaleText_loc4`='但就像我说过的那样，死亡也要比变成狼人更好。', `MaleText_loc5`='不過，就像我常講的，寧死也不要變成狼人。', `MaleText_loc7`='Aunque, como siempre digo, mejor muerto que huargen.' WHERE `ID`=45746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 이번 경우에는, 늑대인간이 되느니 차라리 언데드를 택하겠다고 해야겠지.', `MaleText_loc4`='所以，亡灵要比狼人更好。', `MaleText_loc5`='或者我該說，寧當不死也不要當狼人。', `MaleText_loc7`='O, en este caso, mejor no-muerto que huargen.' WHERE `ID`=45747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병사들을 준비시켜라. 길니아스 해방전선이 그레이메인 성벽에 집결하고 있다. 스톰윈드의 지원병이 곧 도착할 테니, 단 일 분도 낭비할 수는 없다!', `FemaleText_loc4`='让你的部队做好准备。吉尔尼斯解放阵线正在格雷迈恩之墙集结。他们的援军很快也会从暴风城赶到。我们不能再浪费任何一分钟了。', `FemaleText_loc5`='動員你的手下。吉爾尼斯解放戰線的人集結在葛雷邁恩之牆，而且不久之後他們來自暴風城的援軍就會抵達。我們連一分鐘的時間都不能浪費。', `FemaleText_loc7`='Prepara a tus hombres. El Frente de Liberación de Gilneas se reúne en la Muralla de Cringris. Pronto llegarán los refuerzos de Ventormenta. No tenemos ni un minuto que perder.' WHERE `ID`=45748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부대로 하겠습니다, 밴시 여왕님.', `MaleText_loc4`='服从您的命令，女妖之王。', `MaleText_loc5`='如你所願，女妖之王。', `MaleText_loc7`='Como desees, Reina alma en pena.' WHERE `ID`=45749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갑옷이건 무기건, 필요한 것은 무엇이든 뒤쪽의 보급품 창고에서 가져가거라. 자, 이제 떠나라.', `FemaleText_loc4`='盔甲、武器，你所需要的一切都能在我身后的供给站找到。现在，行动吧。', `FemaleText_loc5`='武器、護具，不論你需要什麼，在我背後的補給站裡面通通都找得到。去吧。', `FemaleText_loc7`='Cualquier cosa que necesites, ya sean armas o armaduras, la encontrarás en el depósito de suministros a mis espaldas. Ahora vete.' WHERE `ID`=45750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 네가 나를 또 한 번 놀라게 하는군. 네 도움이 없었더라면 여기까지 올 수 없었겠지. 자, 나와 함께 걷지 않겠나...', `FemaleText_loc4`='你再一次地令我震惊，$n。没有你的帮助，我们绝对不会取得这样的成功。欢迎与我同行……', `FemaleText_loc5`='你又再度令我刮目相看，$n。若是沒有你的協助，我們絕對無法有這樣的進展。來，陪我走一走...', `FemaleText_loc7`='Me has vuelto a impresionar, $n. Sin tu ayuda no habríamos llegado tan lejos. Camina conmigo...' WHERE `ID`=45751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<전문 기술은 최대 두 개까지 배울 수 있습니다. 다음에서 원하는 항목을 선택하십시오.>', `MaleText_loc4`='<你可以学习最多两种主要专业技能。请从下列专业技能中选择：>', `MaleText_loc5`='<你至多可學習兩項主要專業技能。請從下列選單中挑選:>', `MaleText_loc7`='<Puedes aprender hasta dos profesiones primarias. Elige de entre las siguientes opciones:>' WHERE `ID`=45752;
