UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈을 내고 보조 기술 훈련을 받고 싶습니다.', `MaleText_loc4`='我要接受辅助专业技能训练。', `MaleText_loc5`='我想購買次要專業技能的訓練。', `MaleText_loc7`='Me gustaría comprar instrucción de profesión secundaria.', `FemaleText_loc1`='돈을 내고 보조 기술 훈련을 받고 싶어요.', `FemaleText_loc4`='我要接受辅助专业技能训练。', `FemaleText_loc5`='我想購買次要專業技能的訓練。', `FemaleText_loc7`='Me gustaría comprar instrucción de profesión secundaria.' WHERE `ID`=45761;
