UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<자료를 불러오는 도중에 오류가 발생했습니다... 더 자세한 사항은 의사 잽노즐과 상담하십시오.>', `MaleText_loc4`='<数据错误……请前往扎普诺兹医生处获取进一步指示。>', `MaleText_loc5`='<資料讀取錯誤....請洽詢砰鼻醫生。>', `MaleText_loc7`='<Error al recuperar información... Para más instrucciones acude a Doc Pinchamorros.>' WHERE `ID`=45766;
