UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 전차를 보호하십시오!', `MaleText_loc4`='守卫攻城坦克！', `MaleText_loc5`='防守攻城坦克!', `MaleText_loc7`='¡Defiende el tanque de asedio!' WHERE `ID`=45771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으, 망할. 제발, 제발 좀 돼라!', `MaleText_loc4`='啊，该死的。动起来，动起来啊！', `MaleText_loc5`='啊，可惡。快啊，快啊!', `MaleText_loc7`='Ah, maldición. ¡Venga, venga!', `FemaleText_loc1`='아으으, 망할. 제발, 제발 좀 돼라!', `FemaleText_loc4`='啊，该死的。动起来，动起来啊！', `FemaleText_loc5`='啊，可惡。快啊，快啊!', `FemaleText_loc7`='Ah, maldición. ¡Venga, venga!' WHERE `ID`=45772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지! 해냈네! 어서 여기서 빠져나가지.', `MaleText_loc4`='好啦！我们成功啦！让我们离开这里。', `MaleText_loc5`='好了!成功了!快點離開這裡。', `MaleText_loc7`='¡Bien! ¡Ya está! Vámonos de aquí.', `FemaleText_loc1`='그렇지! 해냈습니다! 어서 여기서 빠져나갑시다.', `FemaleText_loc4`='好啦！我们成功啦！让我们离开这里。', `FemaleText_loc5`='好了!成功了!快點離開這裡。', `FemaleText_loc7`='¡Bien! ¡Ya está! Vámonos de aquí.' WHERE `ID`=45773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 전차가 폭발합니다!', `MaleText_loc4`='攻城坦克爆炸了！', `MaleText_loc5`='攻城坦克爆炸了!', `MaleText_loc7`='¡El tanque de asedio explota!' WHERE `ID`=45774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공입니다! 이제 공성 전차를 후방으로 뺄 수 있습니다.', `MaleText_loc4`='成功了！攻城坦克能够撤退了。', `MaleText_loc5`='成功!攻城坦克得以撤退。', `MaleText_loc7`='¡Éxito! El tanque de asedio puede retirarse.' WHERE `ID`=45775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕 폐하의 명을 받드는 건 언제나 영광이죠. 바로 작업을 시작할게요.', `MaleText_loc4`='能够执行乌瑞恩国王的命令永远都是我的骄傲。我立刻就行动。', `MaleText_loc5`='能獲得烏瑞恩王的指派是我的榮幸。我會立刻著手進行。', `MaleText_loc7`='Una comisión del rey Wrynn siempre es un honor. Me pondré manos a la obra inmediatamente.' WHERE `ID`=45776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 바로 그림자송곳니 성채에 숨겨져 있던 희귀하고 강력한 재료를 되찾아오신 분이로군요.', `MaleText_loc4`='就是你进入影牙城堡，取得了藏在那里的罕见而且具有强大力量的材料？', `MaleText_loc5`='你就是冒險進入影牙城堡、取回藏在那兒的罕見強大材料的人?', `MaleText_loc7`='¿Así que fuiste tú quien se aventuró por el Castillo de Colmillo Oscuro para encontrar los materiales raros y poderosos que se encuentran en su interior?' WHERE `ID`=45777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 가져온 재료 중 하나는 새로운 지팡이에 강력한 집중 능력을 부여할 겁니다.', `MaleText_loc4`='在你从那座城堡中取得的物品里，有一件很适合做成强大的魔力核心，镶嵌在你的新法杖上。', `MaleText_loc5`='在你從影牙城堡取回的物品當中，有一樣可以拿來增強你新法杖的強大魔力。', `MaleText_loc7`='Entre los objetos que encontraste en el castillo hay uno que supondrá un potente catalizador para tu nuevo bastón.' WHERE `ID`=45778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예사라, 거기 있는 가루와 결정 좀 주겠소?', `MaleText_loc4`='杰萨拉，把那些灰尘和碎片给我。', `MaleText_loc5`='傑薩拉，把那些魔塵和裂片拿來給我。', `MaleText_loc7`='Jessara, pásame esos polvos y fragmentos.' WHERE `ID`=45779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소. 그런데 내가 그 두루마리를 어디다 뒀더라... 아, 그래! 여기 있군.', `MaleText_loc4`='我把那个卷轴放在哪里了？啊，是了，在这里……', `MaleText_loc5`='那個卷軸我放到哪兒去了?啊，對了，在這裡...', `MaleText_loc7`='¿Dónde he puesto ese pergamino...? Ah, así, aquí está...' WHERE `ID`=45780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 기다리셨습니다, $n. 자, 여기 당신의 지팡이입니다. 얼라이언스의 명예를 위해 유용하게 사용하길 바랍니다.', `MaleText_loc4`='终于完成了，$n，这是你的法杖。骄傲地挥舞它，为联盟而战吧。', `MaleText_loc5`='終於，$n，你的法杖已經好了。請善加利用它來為聯盟效力吧。', `MaleText_loc7`='Al fin, $n, aquí tienes tu bastón. Llévalo con orgullo en servicio de la Alianza.' WHERE `ID`=45781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이죠, 루칸. 자, 여기요.', `FemaleText_loc4`='当然，鲁坎。给你。', `FemaleText_loc5`='是，魯坎。東西在這裡。', `FemaleText_loc7`='Claro, Lucan. Aquí tienes.' WHERE `ID`=45782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겁도 없이 붉은용군단의 영지를 침범했군요, $r|1이여;여;.', `FemaleText_loc4`='你进入了红龙的统治领域。', `FemaleText_loc5`='你已進入了紅龍的領域，$r。', `FemaleText_loc7`='Has entrado en el dominio de los dragones Rojos, $r.' WHERE `ID`=45783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 새로운 동맹인 용아귀 부족의 요청에 따라 여기 온 것인지 어떤지 나는 모릅니다. 용아귀 부족 때문에 온 게 아니라고 해도 어차피 난 당신을 믿지 않고요.', `FemaleText_loc4`='我不知道你是不是为了响应你的新龙喉盟友的号召来到这里。即使不是，我也不会信任你。', `FemaleText_loc5`='我不知道你是否應你們新盟友龍喉氏族的號召而來，但就算你不是，我也不會就此信任你。', `FemaleText_loc7`='No sé si has venido por orden de tus nuevos aliados Faucedraco, y tampoco confiaría en ti aunque no fuera así.' WHERE `ID`=45784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에겐 다행스럽게도, 당신의 운명을 결정할 이는 내가 아닙니다. 나무 옆에서 캘렌이 당신을 기다리고 있습니다.', `FemaleText_loc4`='你很幸运，因为你的命运并不由我来决定。凯伦正在那棵树旁边等着你。', `FemaleText_loc5`='算你好運，你的命運並非交由我來斷定。凱倫在那棵樹旁等著你。', `FemaleText_loc7`='Por suerte para ti, no me corresponde a mí decidir tu destino. Calen te aguarda junto al árbol.' WHERE `ID`=45785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 비룡들이 당신을 주시할 것입니다. 그러니 말과 행동을 조심하는 게 좋을 겁니다, $r|1이여;여;.', `FemaleText_loc4`='我的龙会盯着你。记住，要谨言慎行，$r。', `FemaleText_loc5`='我的龍群會目不轉睛地注意著你，慎選你的言詞和舉動，$r。', `FemaleText_loc7`='Mis dracos estarán observándote. Elige tus palabras y actos con prudencia, $r.' WHERE `ID`=45786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신과 당신의 동맹들은 과거에 그림 바톨 관문에서 나의 동족을 공격했습니다. 우리가 목숨 걸고 지키겠다고 다짐한 신성한 맹세를 존중하지 않았어요. 그러니, 내게서 믿음을 기대하지 마십시오.', `FemaleText_loc4`='你和你的盟友曾经在格瑞姆巴托的大门前攻击我们。对于我们用生命保护的誓言，你们却毫无敬意。我不可能信任你。', `FemaleText_loc5`='你和你的盟友們過去曾在格瑞姆巴托攻擊我的同伴。你對我們誓死捍衛的神聖誓言毫無敬意，所以，我是絕對不會信任你的。', `FemaleText_loc7`='Tus aliados y tú atacasteis a los de mi raza en las puertas de Grim Batol. No habéis mostrado ningún respeto por el juramento sagrado que nosotros moriríamos por mantener. No obtendrás confianza alguna de mí.' WHERE `ID`=45787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 바로 울프가 말한, 린 국왕 폐하의 관심을 끈 유능한 사냥꾼이로군.', `MaleText_loc4`='你一定是乌尔夫所说的那位传奇猎人吧。就连乌瑞恩国王也在关注你。', `MaleText_loc5`='你必定是伍爾夫提到的那位天賦異稟的獵人，而且你還吸引到了烏瑞恩王的注意。', `MaleText_loc7`='Debes de ser $gese cazador:esa cazadora; con tanto talento que mencionó Wulf; $gese:esa; que ha llamado la atención del rey Wrynn.' WHERE `ID`=45788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 저주받은 성채에서 가져온 재료들로 분명히 훌륭한 활을 만들 수 있을 거요.', `MaleText_loc4`='你从那座被诅咒的古老城堡中取得的材料能够制作一张非常强大的弓。', `MaleText_loc5`='你從那座詛咒城堡收集而來的材料肯定可以做出一把出色的弓。', `MaleText_loc7`='Los materiales que reuniste en ese maldito castillo servirán para crear un arco magnífico.' WHERE `ID`=45789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분 나쁘게 할 생각은 없지만, 자네는 커다란 짐꾼 코도를 맞출 능력도 없는 것 같은데...$b$b우리 서로 시간 낭비하지 말고, 자네 직업에 맞는 상급자를 찾아보는 게 좋을 것 같네.', `MaleText_loc4`='我没有恶意，但我觉得你连一头科多兽的肚子都射不中。$B$B我们不应该再浪费彼此的时间了，去找一位合适的训练师吧。', `MaleText_loc5`='恕我直言，但是你恐怕連隻科多獸的側面都射不中。$B$B別浪費彼此的時間，去找個適合你的訓練師吧。', `MaleText_loc7`='Sin ofender, pero no tienes pinta de poder acertar a un kodo de lado.$b$b¿Qué te parece si dejamos de perder el tiempo y te vas a buscar al instructor adecuado?', `FemaleText_loc1`='기분 나쁘게 할 생각은 없지만, 당신은 커다란 짐꾼 코도를 맞출 능력도 없는 것 같은데요...$b$b우리 서로 시간 낭비하지 말고, 당신 직업에 맞는 상급자를 찾아보는 게 좋을 것 같네요.', `FemaleText_loc4`='我没有恶意，但我觉得你连一头科多兽的肚子都射不中。$B$B我们不应该再浪费彼此的时间了，去找一位合适的训练师吧。', `FemaleText_loc5`='恕我直言，但是你恐怕連隻科多獸的側面都射不中。$B$B別浪費彼此的時間，去找個適合你的訓練師吧。', `FemaleText_loc7`='Sin ofender, pero no tienes pinta de poder acertar a un kodo de lado.$b$b¿Qué te parece si dejamos de perder el tiempo y te vas a buscar al instructor adecuado?' WHERE `ID`=45790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네. 사격 연습할 준비가 된 건가?', `MaleText_loc4`='嗨，想进行瞄准练习么？', `MaleText_loc5`='呦，要來射幾箭嗎?', `MaleText_loc7`='Buenas. ¿Te apetece un poco de práctica de tiro?', `FemaleText_loc1`='반갑습니다. 사격 연습할 준비가 된 건가요?', `FemaleText_loc4`='嗨，想进行瞄准练习么？', `FemaleText_loc5`='呦，要來射幾箭嗎?', `FemaleText_loc7`='Buenas. ¿Te apetece un poco de práctica de tiro?' WHERE `ID`=45791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여기 있소, $n. 위대한 사냥꾼을 위한 강력한 활이오. 얼라이언스를 위해 유용하게 사용하길 바라오.', `MaleText_loc4`='给你，$n。一张强有力的弓才配得上你这样天才的猎人。用它为联盟建功立业吧。', `MaleText_loc5`='拿去吧，$n。良弓配良獵，請善用它來為聯盟效力。', `MaleText_loc7`='Aquí lo tienes, $n. Un gran arco para $gun gran cazador:una gran cazadora;. Úsalo bien en servicio de la Alianza.' WHERE `ID`=45794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $n. 훈련받으러 온 건가? 난 시간이 많지 않다고.', `MaleText_loc4`='嗨，$n。想要学习知识吗？我可没有一整天的时间跟你耗……', `MaleText_loc5`='嗨，$n。你是來上課的嗎?我可不是整天閒閒沒事...', `MaleText_loc7`='Hola, $n. ¿Has venido a por una lección? No tengo todo el día...', `FemaleText_loc1`='반갑습니다, $n. 훈련받으러 온 건가요? 전 시간이 많지 않다고요.', `FemaleText_loc4`='嗨，$n。想要学习知识吗？我可没有一整天的时间跟你耗……', `FemaleText_loc5`='嗨，$n。你是來上課的嗎?我可不是整天閒閒沒事...', `FemaleText_loc7`='Hola, $n. ¿Has venido a por una lección? No tengo todo el día...' WHERE `ID`=45795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 자네가 제대로 된 마법을 못 배운 게 내 잘못은 아니잖아!$b$b가서 상급 $c|1이나;나; 귀찮게 하라고.', `MaleText_loc4`='嘿，你学不会施法可不是我的错。

去找个$c训练师吧，好吗？', `MaleText_loc5`='嘿，你學不會法術又不是「我」的錯。

找個$c訓練師去煩，好嗎?', `MaleText_loc7`='Oye, no es culpa mía que no hayas aprendido hechicería como es debido.

Ve a ver a $gun:una; $c, ¿vale?', `FemaleText_loc1`='이봐요, 당신이 제대로 된 마법을 못 배운 게 내 잘못은 아니잖아요!$b$b가서 상급 $c|1이나;나; 귀찮게 하라고요.', `FemaleText_loc4`='嘿，你学不会施法可不是我的错。

去找个$c训练师吧，好吗？', `FemaleText_loc5`='嘿，你學不會法術又不是「我」的錯。

找個$c訓練師去煩，好嗎?', `FemaleText_loc7`='Oye, no es culpa mía que no hayas aprendido hechicería como es debido.

Ve a ver a $gun:una; $c, ¿vale?' WHERE `ID`=45796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 여기서 볼 일이 없을 텐데. 다른 데로 가보는 게 어떤가?', `MaleText_loc4`='这里没什么可看的，朋友。为什么不到别处去逛逛？', `MaleText_loc5`='這裡沒什麼好看的，老兄。去找別人吧，好嗎?', `MaleText_loc7`='Aquí no hay ná que ver, colega. Sigue andando, ¿quieres?', `FemaleText_loc1`='당신은 여기서 볼 일이 없을 텐데요. 다른 데로 가보시지요.', `FemaleText_loc4`='这里没什么可看的，朋友。为什么不到别处去逛逛？', `FemaleText_loc5`='這裡沒什麼好看的，老兄。去找別人吧，好嗎?', `FemaleText_loc7`='Aquí no hay ná que ver, colega. Sigue andando, ¿quieres?' WHERE `ID`=45797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 요즘 실력이 부쩍 늘었다고 하던데, 훈련이 필요한 건가?', `MaleText_loc4`='我听说你走了很远的路才来到这里，朋友。也许你需要更多一些训练？', `MaleText_loc5`='我大老遠就聽到你走過來的聲音了，老兄。看來你還需要更進一步的訓練?', `MaleText_loc7`='Te he oí''o venir deh''de un kilómetro, colega. ¿Igual necesitas un poco de instrucción?', `FemaleText_loc1`='요즘 당신의 실력이 부쩍 늘었다고 하던데, 훈련이 필요한 건가요?', `FemaleText_loc4`='我听说你走了很远的路才来到这里，朋友。也许你需要更多一些训练？', `FemaleText_loc5`='我大老遠就聽到你走過來的聲音了，老兄。看來你還需要更進一步的訓練?', `FemaleText_loc7`='Te he oí''o venir deh''de un kilómetro, colega. ¿Igual necesitas un poco de instrucción?' WHERE `ID`=45798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 자네 눈에는 내가 $c|1으로;로; 보이나?$b$b어서 내 눈앞에서 사라지라고!', `MaleText_loc4`='什么？我看上去像个$c吗？$B$B请让开一点，好吗？', `MaleText_loc5`='什麼?你以為我是個$c?$B$B請你走開好嗎?', `MaleText_loc7`='¿Qué? ¿Te parezco $gotro:otra; $c?$b$bVete de aquí, ¿estamos?', `FemaleText_loc1`='뭐라고요? 당신 눈에는 제가 $c|1으로;로; 보이나요?$b$b어서 내 눈앞에서 사라지라고!', `FemaleText_loc4`='什么？我看上去像个$c吗？$B$B请让开一点，好吗？', `FemaleText_loc5`='什麼?你以為我是個$c?$B$B請你走開好嗎?', `FemaleText_loc7`='¿Qué? ¿Te parezco $gotro:otra; $c?$b$bVete de aquí, ¿estamos?' WHERE `ID`=45799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아 보이는군, 친구.$b$b무슨 일인가? 훈련을 받고 싶은 건가?', `MaleText_loc4`='看起来很不错，小孩。$B$B你说什么？想进行训练？', `MaleText_loc5`='嗨，小子。$B$B最近怎樣?要來訓練一下嗎?', `MaleText_loc7`='Tienes buen aspecto, $gtío:tía;.$b$b¿Qué te cuentas? ¿Quieres entrenar un poco?', `FemaleText_loc1`='좋아 보이는군요.$b$b무슨 일인가요? 훈련을 받고 싶은 건가요?', `FemaleText_loc4`='看起来很不错，小孩。$B$B你说什么？想进行训练？', `FemaleText_loc5`='嗨，小子。$B$B最近怎樣?要來訓練一下嗎?', `FemaleText_loc7`='Tienes buen aspecto, $gtío:tía;.$b$b¿Qué te cuentas? ¿Quieres entrenar un poco?' WHERE `ID`=45800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 게 뭔가?$b$b미안하지만 $c인 자네에게는 가르쳐 줄 게 없네.', `MaleText_loc4`='你需要什么？$B$B太糟糕了。我可帮不了你，$c。', `MaleText_loc5`='你需要什麼嗎?$B$B可惜，我沒有東西可以教你，$c。', `MaleText_loc7`='¿Necesitas algo?$b$bPeor para ti. No tengo nada que contarte, $c.', `FemaleText_loc1`='필요한 게 뭔가요?$b$b미안하지만 $c인 당신에게는 가르쳐 줄 게 없네요.', `FemaleText_loc4`='你需要什么？$B$B太糟糕了。我可帮不了你，$c。', `FemaleText_loc5`='你需要什麼嗎?$B$B可惜，我沒有東西可以教你，$c。', `FemaleText_loc7`='¿Necesitas algo?$b$bPeor para ti. No tengo nada que contarte, $c.' WHERE `ID`=45801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"재미와 이윤을 위해 원소를 제어한다."$b$b그게 전부라네. 내 말 맞지? 자, 시작해 보자고.', `MaleText_loc4`='“为了乐趣和利润控制元素。”$B$B这就是重点所在，同意我的话吗？让我们开始吧。', `MaleText_loc5`='「好玩又好賺的元素操控法」。$B$B重點就是這樣，我說的沒錯吧?讓我們開始吧。', `MaleText_loc7`='"Controlar los elementos para obtener beneficios."$b$bDe eso va todo esto, ¿verdad? Pongámonos a trabajar.', `FemaleText_loc1`='"재미와 이윤을 위해 원소를 제어한다."$b$b그게 전부죠. 제 말 맞죠? 자, 시작해 보죠.', `FemaleText_loc4`='“为了乐趣和利润控制元素。”$B$B这就是重点所在，同意我的话吗？让我们开始吧。', `FemaleText_loc5`='「好玩又好賺的元素操控法」。$B$B重點就是這樣，我說的沒錯吧?讓我們開始吧。', `FemaleText_loc7`='"Controlar los elementos para obtener beneficios."$b$bDe eso va todo esto, ¿verdad? Pongámonos a trabajar.' WHERE `ID`=45802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여보게. 자네는 내가 뭘 가르치고 있는지 알고 싶지도 않을 거라네.$b$b아마 자네의 뇌가 녹아버릴 테니. 그냥 다른 데 가서 착하게 놀게.', `MaleText_loc4`='听着，你不会想知道我到底掌握着什么。$B$B别以为我在开玩笑。那种力量能融化你的大脑。去别的地方，找些好玩的事情吧。', `MaleText_loc5`='聽著，你連想都不會想知道我可以教你的是什麼東西。$B$B說真的，那會害你的腦袋融化掉。到別地方去找點簡單的題材吧。', `MaleText_loc7`='Escucha. No quieres ni saber el tipo de cosas que podría enseñarte.$b$bEn serio, te derretiría el cerebro. Vete a jugar por ahí.', `FemaleText_loc1`='이봐요. 당신은 내가 뭘 가르치고 있는지 알고 싶지도 않을 겁니다.$b$b아마 당신의 뇌가 녹아버릴 테니까 말입니다. 그냥 다른 데 가서 착하게 노십시오.', `FemaleText_loc4`='听着，你不会想知道我到底掌握着什么。$B$B别以为我在开玩笑。那种力量能融化你的大脑。去别的地方，找些好玩的事情吧。', `FemaleText_loc5`='聽著，你連想都不會想知道我可以教你的是什麼東西。$B$B說真的，那會害你的腦袋融化掉。到別地方去找點簡單的題材吧。', `FemaleText_loc7`='Escucha. No quieres ni saber el tipo de cosas que podría enseñarte.$b$bEn serio, te derretiría el cerebro. Vete a jugar por ahí.' WHERE `ID`=45803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 에너지가 얼마나 멋진지 아나? 값싸고, 재생 가능하고, 폭발력도 대단하지.$b$b물론 시간과 공간을 초월한, 상상할 수 없는 공포 때문에 영원한 의지를 잃어버릴 위험도 있지만, 위험을 감수할 만한 보상이 뒤따르지 않나!$B$B자, 무슨 일로 왔다고 했지?', `MaleText_loc4`='你会喜欢恶魔能量的：廉价，能够恢复，而且肯定能把你痛恨的东西炸碎。$B$B当然，你也会因此而必须面对一些东西——那种超越时间和空间的，难以想象的恐怖。你可能会因此而永远丢失你的心智。不过只有冒险才能得到巨大的回报！$B$B那么，你想让我教你些什么，嗯？', `MaleText_loc5`='你一定會超愛魔化能量的:便宜，可一用再用，而且肯定能炸掉東西。$B$B當然啦，你得冒著永遠失去自我意志給超越時空之難以想像之恐懼的後果，但是嘿嘿，有得必有失嘛!$B$B好啦，你來找我是要幹嘛呢?', `MaleText_loc7`='La energía vil lo tiene todo: es barata, es renovable y está garantizado que hará estallar cosas.$b$bEs verdad que te arriesgas a perder tu voluntad eterna ante los horrores inimaginables más allá de todo tiempo y espacio, pero oye, ¡riesgo y recompensa!$b$bMmmm, ¿por qué querías verme?', `FemaleText_loc1`='악마의 에너지가 얼마나 멋진지 아나? 값싸고, 재생 가능하고, 폭발력도 대단하지.$b$b물론 시간과 공간을 초월한, 상상할 수 없는 공포 때문에 영원한 의지를 잃어버릴 위험도 있지만, 위험을 감수할 만한 보상이 뒤따르지 않나!$B$B자, 무슨 일로 왔다고 했지?', `FemaleText_loc4`='你会喜欢恶魔能量的：廉价，能够恢复，而且肯定能把你痛恨的东西炸碎。$B$B当然，你也会因此而必须面对一些东西——那种超越时间和空间的，难以想象的恐怖。你可能会因此而永远丢失你的心智。不过只有冒险才能得到巨大的回报！$B$B那么，你想让我教你些什么，嗯？', `FemaleText_loc5`='你一定會超愛魔化能量的:便宜，可一用再用，而且肯定能炸掉東西。$B$B當然啦，你得冒著永遠失去自我意志給超越時空之難以想像之恐懼的後果，但是嘿嘿，有得必有失嘛!$B$B好啦，你來找我是要幹嘛呢?', `FemaleText_loc7`='La energía vil lo tiene todo: es barata, es renovable y está garantizado que hará estallar cosas.$b$bEs verdad que te arriesgas a perder tu voluntad eterna ante los horrores inimaginables más allá de todo tiempo y espacio, pero oye, ¡riesgo y recompensa!$b$bMmmm, ¿por qué querías verme?' WHERE `ID`=45804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 시작하노라. 용사들이여, 일어나라! 일어나 이 세 명을 시험에 들게 하라!', `MaleText_loc4`='试炼于此时开始。勇士们！奋勇拼杀，击败那三个敌人！', `MaleText_loc5`='試煉開始。起來吧，勇士們!起來，迎戰這三人!', `MaleText_loc7`='Que comience la prueba. ¡Alzaos, campeones! ¡Alzaos y enfrentaos a estos tres en combate!' WHERE `ID`=45805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸은 좀 푼 것 같군. 자, 진짜 시험은 이제부터다!', `MaleText_loc4`='热身结束了。现在，真正的试炼开始了！', `MaleText_loc5`='你已經做好暖身。現在，真正的試煉要開始了!', `MaleText_loc7`='El calentamiento ha terminado. ¡Ahora comienza la verdadera prueba!' WHERE `ID`=45806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란 대마법사의 유물을 가져가려면 우선 내 시체를 넘어야 할 거다!', `MaleText_loc4`='只有我死了，你才能从我的手中夺走达拉然大法师的遗物！', `MaleText_loc5`='你得殺了我才能從我手裡拿走達拉然大法師們的遺物!', `MaleText_loc7`='¡Tendréis que arrancar las reliquias de los archimagos de Dalaran de mis manos frías y muertas!' WHERE `ID`=45807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 필요는 없었어! 가족들을 다시 한번 보고 싶었을 뿐인데... 가족들과 이 선물을 함께 나누고 싶었는데!', `MaleText_loc4`='事情不应该这样！我只是想再见到我的家人……同他们分享这份礼物！', `MaleText_loc5`='事情不必走到這個地步!我只是想要再見我的家人一面...跟他們分享這個禮物!', `MaleText_loc7`='¡No tenía que haber sido así! Yo solo quiero volver a ver a mi familia... ¡compartir este don con ellos!' WHERE `ID`=45808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이 언데드 소굴에 우릴 내버려서 썩어 문드러지게 만든 놈들... 언젠가 그 대가를 치르게 될 거야...', `MaleText_loc4`='他们将为抛弃我们的行为付出代价。把我们丢在这里，任由我们在凶残的不死亡灵间腐烂……', `MaleText_loc5`='他們將得為遺棄我們而付出代價。把我們遺棄在這邊，跟這些兇殘的不死族一起...', `MaleText_loc7`='Pagarán por renegar de nosotros. Por dejarnos aquí para pudrirnos entre los no-muertos descerebrados...' WHERE `ID`=45809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 가보겠네. 여기 머물 이유가 없어. 비록 언데드이지만, 내 의지는 나의 것이지.', `MaleText_loc4`='我要走了。我没有理由留在这里。也许我是个亡灵，但我拥有属于自己的意志。', `MaleText_loc5`='我要走了。我沒有理由繼續待在這裡。雖然我成了不死怪物，但我依然擁有自主的意志。', `MaleText_loc7`='Ahora me voy. No tengo ninguna razón para seguir aquí. Es posible que sea un no-muerto, pero mi voluntad es mía.' WHERE `ID`=45810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 세상엔 푸른 초원에서 만나세, $n.', `MaleText_loc4`='我在另一个世界里的绿野上等你，$n。', `MaleText_loc5`='我到另外一邊的草原跟你再見，$n。', `MaleText_loc7`='Te veré en las verdes praderas del más allá, $n.' WHERE `ID`=45811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 정말 잘해줬다. 너희는 이제 나의 시험을 통과했다.', `MaleText_loc4`='干得好，英雄们。你们已经通过了我的战斗测试。', `MaleText_loc5`='幹得好，英雄們。你們已經通過了我的戰鬥測驗。', `MaleText_loc7`='Bien hecho, héroes. Habéis superado mi prueba de combate.' WHERE `ID`=45812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빕니다.', `MaleText_loc4`='祝你好运。', `MaleText_loc5`='祝好運。', `MaleText_loc7`='Buena suerte.', `FemaleText_loc1`='행운을 빌어요.', `FemaleText_loc4`='祝你好运。', `FemaleText_loc5`='祝好運。', `FemaleText_loc7`='Buena suerte.' WHERE `ID`=45813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 서둘러! 빨리 가자고!', `MaleText_loc4`='来吧，我们走！', `MaleText_loc5`='快點!我們走!', `MaleText_loc7`='¡Vamos ya!' WHERE `ID`=45814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레나, 이 멍청아! 예배당이 20미터도 안 남았는데 뭐하는 거야! 어서 가자!', `MaleText_loc4`='塔伦纳，你这个傻瓜！礼拜堂还在二十码以外！我们快走！', `MaleText_loc5`='塔瑞納爾，你這笨蛋!禮拜堂就在二十碼外的地方!快點走!', `MaleText_loc7`='¡No seas tonto, Tarenar! ¡La capilla está a veinte metros! ¡En marcha!' WHERE `ID`=45815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제쯤 출발할 거야, 타레나? 난 십자군에 들어가고 싶다고!', `MaleText_loc4`='我们能走了吗，塔伦纳？我想要加入北伐军！', `MaleText_loc5`='我們可以走了嗎，塔瑞納爾?我想要加入十字軍!', `MaleText_loc7`='¿Podemos irnos ya, Tarenar? ¡Quiero unirme a la Cruzada!' WHERE `ID`=45816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<웅웅 소리를 내는 차원문>', `MaleText_loc4`='<次元之门发出“嗡嗡”的响声。>', `MaleText_loc5`='<次元傳送門發出嗡嗡的聲音。>', `MaleText_loc7`='<El portal dimensional emite un zumbido.>' WHERE `ID`=45817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<호박색 농장 공간 차원문 사용>', `MaleText_loc4`='<使用安伯米尔次元传送门。>', `MaleText_loc5`='<使用安伯米爾次元傳送門。>', `MaleText_loc7`='<Utilizar el portal dimensional de Molino Ámbar.>', `FemaleText_loc1`='<호박색 농장 공간 차원문 사용>', `FemaleText_loc4`='<使用安伯米尔次元传送门。>', `FemaleText_loc5`='<使用安伯米爾次元傳送門。>', `FemaleText_loc7`='<Utilizar el portal dimensional de Molino Ámbar.>' WHERE `ID`=45818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경보를 울려라! 침입자가 차원문을 통과했다!', `MaleText_loc4`='拉响警报！入侵者穿过了传送门！', `MaleText_loc5`='敲響警鐘!入侵者突破傳送門了!', `MaleText_loc7`='¡HACED SONAR LAS ALARMAS! ¡UNOS INTRUSOS HAN ENTRADO EN EL PORTAL!' WHERE `ID`=45819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고... *콜록* 고맙습니다, 이방인이여.', `MaleText_loc4`='我……*咳嗽*谢谢你，陌生人。', `MaleText_loc5`='我...*咳嗽*我謝謝你，陌生人。', `MaleText_loc7`='Gr... Ejem... Gracias, $gdesconocido:desconocida;.' WHERE `ID`=45820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 생명의 은인입니다. 우리 동족은 데스윙에게 반역한 탓에 혹독한 대가를 치렀습니다.', `MaleText_loc4`='我欠你一条命。在和死亡之翼的战斗中，我的人民已经付出了高昂的代价。', `MaleText_loc5`='我欠你一命。為了對抗死亡之翼，我的族人們已付出了慘重的代價。', `MaleText_loc7`='Te debo la vida. Mi gente ha pagado un precio muy alto por desafiar a Alamuerte.' WHERE `ID`=45821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신처럼 친절한 분은 이야기 속에만 존재하는 줄 알았습니다, $r님. 당신 같은 분이 제 생명을 구해주실 줄은 꿈에도 몰랐습니다.', `MaleText_loc4`='$r，我以前只在故事里听到过你们。真没想到，我竟然会被你救了一命。', `MaleText_loc5`='我只有在故事裡聽過你們的存在，$r。沒想到我的性命竟然會被一位$r所拯救。', `MaleText_loc7`='Solo había oído hablar de tu raza en historias, $r. Nunca pensé que le debería la vida a uno de los tuyos.' WHERE `ID`=45822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여, 침입자를 처치하라! 차원의 방패가 파괴되어서는 안 된다!', `MaleText_loc4`='奴仆们，消灭入侵者！绝对不能让护盾被摧毁！', `MaleText_loc5`='手下們，消滅闖入者!護盾絕不能被破壞!', `MaleText_loc7`='¡Esbirros, destruid $gal intruso:a la intrusa;! ¡El escudo no debe desactivarse!' WHERE `ID`=45824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 절대 성공하지 못할 것이다, 이 괴물아!', `MaleText_loc4`='你不会成功的，怪物！', `MaleText_loc5`='你不會成功的，怪物!', `MaleText_loc7`='¡No lo conseguirás, monstruo!' WHERE `ID`=45825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는... 절대... 포기하지... 않아!', `MaleText_loc4`='我们……绝不……放弃！', `MaleText_loc5`='我們永遠...不會...放棄!', `MaleText_loc7`='¡Nunca... nos... rendiremos!' WHERE `ID`=45826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 전사들이 네 뼈를 짓밟을 것이다!', `MaleText_loc4`='联盟的军队将踏碎你们！', `MaleText_loc5`='聯盟的部隊會踩在你的骨頭上進軍!', `MaleText_loc7`='¡Los ejércitos de la Alianza desfilarán sobre sus huesos!' WHERE `ID`=45827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론은 얼라이언스의 것이다. 부질없이 발버둥치지 마라.', `MaleText_loc4`='洛丹伦属于联盟。你们只是在拖延无可阻挡的命运……', `MaleText_loc5`='羅德隆是聯盟的，你只是多拖延了些時間罷了...', `MaleText_loc7`='Lordaeron pertence a la Alianza. No hacéis sino retrasar lo inevitable...' WHERE `ID`=45828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴하라! 포세이큰이 되어서는 안 된다!', `MaleText_loc4`='跑啊！别让他们转变你！', `MaleText_loc5`='跑!別讓他們把你變了!', `MaleText_loc7`='¡CORRE! ¡NO PERMITAS QUE TE CONVIERTAN!' WHERE `ID`=45829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 타라고, $n. 출발!', `MaleText_loc4`='跳上来，$n。我们走！', `MaleText_loc5`='跳上來，$n。我們走!', `MaleText_loc7`='Sube, $n. ¡Vamos allá!' WHERE `ID`=45830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 그 얼라이언스가 저 용아귀 오크 놈들을 혼내주려고 여기 온 거면 좋겠군.', `MaleText_loc4`='希望你们联盟能给这里的龙喉兽人狠狠一击。', `MaleText_loc5`='我希望你們聯盟是來這兒給龍喉獸人一點教訓的。', `MaleText_loc7`='Espero que los de la Alianza hayáis venido para darles una buena paliza a los Faucedraco.' WHERE `ID`=45831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 여기 꽤 괜찮군. 책임자를 찾아낼 때까지 나랑 좀 같이 다니자고.', `MaleText_loc4`='这里的情况你已经很清楚了，朋友。跟我来，我们找出到底谁是这里的头领。', `MaleText_loc5`='你這邊弄得還不錯嘛，朋友。跟我來，我看看這裡是誰在管的。', `MaleText_loc7`='Tienes un buen tinglado aquí montado, colega. Ven conmigo mientras averiguo quién está al mando.' WHERE `ID`=45832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거야 원 놀랄 노자로군! 쿠르드란 와일드해머! 멀쩡하군. 살아 있었어!', `MaleText_loc4`='我简直无话可说了！库德兰·蛮锤就出现在我眼前。他还活着！', `MaleText_loc5`='我的老天啊!庫德蘭·蠻錘 - 貨真價實 - 他還活著!', `MaleText_loc7`='¡Que me ahorquen del árbol más cercano! Kurdran Martillo Salvaje en carne y hueso. ¡Estás vivo!' WHERE `ID`=45833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 의뢰하셨을 때 내가 했던 기대에 자네가 못 미친다는 점을 받아들여야겠네.', `MaleText_loc4`='必须承认，当我接到酋长的命令时，完全没有想到来的人会是你。', `MaleText_loc5`='我必須承認，你跟我當初收到大酋長的委託時所想像的不太一樣。', `MaleText_loc7`='Tengo que admitir que no eres lo que me esperaba cuando recibí la comisión del Jefe de Guerra.' WHERE `ID`=45834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님이 경의를 표하셨다면, 자네에게 틀림없이 무언가가 있을 테지. 그 무기를 들 수 있으면 가져가게.', `MaleText_loc4`='如果你能赢得酋长的尊敬，那么你一定是有些过人之处。如果你能拿起这件武器，它就是你的了。', `MaleText_loc5`='但既然你已贏得了大酋長的敬重，相信你必定有著過人之處。只要你能拿起這把武器，它就是你的了。', `MaleText_loc7`='Si te has ganado el respeto del Jefe de Guerra debe ser por algo. Si puedes levantar esta arma, es tuya.' WHERE `ID`=45835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적절한 무기를 곁에 둔다면 그렇게까지 기도문에 의지하지 않아도 된다네.', `MaleText_loc4`='也许当你拥有一件合适的武器，你就不需要过于依赖你的咒语了。', `MaleText_loc5`='說不定，只要有把像樣的武器，你就不必那麼倚賴你的法術啦。', `MaleText_loc7`='Quizá no te hagan falta tantos cánticos si tienes un arma como es debido.' WHERE `ID`=45836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 자네 같은 녀석들은 겉모양만 따지지. 걱정하지 말게. 자네 싸우는 방식에 어울리는 걸 만들어 주겠네.', `MaleText_loc4`='对于你这样的人，外表实在是一种欺骗。别担心，我会打造适合你的战斗风格的武器。', `MaleText_loc5`='不過，對你們這樣的人來講，外觀是看不準的。別擔心，我會做個適合你戰鬥風格的東西給你。', `MaleText_loc7`='Pero las apariencias pueden engañar con los de tu clase. No te preocupes, haré algo que se adapte a tu estilo de lucha.' WHERE `ID`=45837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지만, 확실히 재료가 중요하네. 이 작업이 끝나면, 좋은 무기가 자네 손에 들어갈 걸세. 그 재료의 힘을 이용하게 해줄 무기 말일세.', `MaleText_loc4`='你显然能够和元素进行顺畅的交流。等我的工作完成之后，你就会有一件精良的武器。它能帮助你充分施展元素的力量。', `MaleText_loc5`='不過，元素們顯然是會跟你互動的，而等我完工之後，你就會有一把精良的武器來駕馭他們的力量了。', `MaleText_loc7`='Pero salta a la vista que los elementos te hablan, y cuando termine tendrás una buena arma que te ayudará a controlar su poder.' WHERE `ID`=45838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 년 동안 달빛강철 작업은 하지 않았네만, 잊어버릴 만한 일은 아니지. 이봐 수습생들, 진짜 금속을 어떻게 다루는 지 보여주겠네!', `MaleText_loc4`='我已经有许多年没有加工过月钢了。不过这种技艺是不可能被忘记的。学徒们，是时候显示你们锻打真正金属的能耐了！', `MaleText_loc5`='我已經好多年沒碰月鋼了，還好這種東西可不是那麼簡單忘得掉的。徒弟們，給你們瞧瞧怎樣鍛鑄真正的金屬!', `MaleText_loc7`='Hace años que no trabajo el acero lunar, pero uno no se olvida de ese tipo de cosas. ¡Aprendices, es el momento de enseñaros cómo se trabaja el metal de verdad!' WHERE `ID`=45839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론일세, 친구. 와일드해머 부족은 어떤가? 자네와 할 얘기가 산더미같이 많다네!', `MaleText_loc4`='朋友，蛮锤部族的情况如何？我们有很多事情要谈！', `MaleText_loc5`='嗨，朋友。蠻錘氏族近來可好?有很多事情我們得好好談談!', `MaleText_loc7`='Así es, amigo. ¿Cómo les va a los clanes Martillo Salvaje? ¡Tenemos mucho de lo que hablar!' WHERE `ID`=45840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다리야, 이건 포기해. 너무 오래 걸린단 말이야!', `MaleText_loc4`='别管它了，Crablegs。这太费时间了！', `MaleText_loc5`='算了吧，蟹腿。太久了!', `MaleText_loc7`='Olvídalo, Patacangrejo. ¡Está tardando demasiado!' WHERE `ID`=45841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기가 다 됐네. 자네가 호드에 보여준 충성심에 대한 보상으로는 우리가 만든 무기가 제격이지. 왜 우리를 두려워해야 하는지 이 무기로 적에게 똑똑히 알려주게!', `MaleText_loc4`='你的武器完成了。正是因为你对部落的忠诚，我们才会将努力工作的成果赠送给你。用它来让我们的敌人胆战心寒吧！', `MaleText_loc5`='你的武器已經好了。我想你應該會對我們的成果感到滿意，足夠報答你對部落的忠誠。好好用它來提醒我們的敵人，為什麼他們應該要害怕我們!', `MaleText_loc7`='Tu arma está terminada. Creo que nuestra obra te parecerá una recompensa adecuada para tu lealtad hacia la Horda. ¡Úsala para recordarles a nuestros enemigos por qué nos tienen miedo!' WHERE `ID`=45842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원의 방벽이 무너졌다! 놈들을 잡아라! 밴시 여왕을 위하여!', `FemaleText_loc4`='空间障碍物被打破了！现在，展开进攻！为了女妖之王！', `FemaleText_loc5`='屏障破裂了!立刻幹掉他們!女妖之王萬歲!', `FemaleText_loc7`='¡La barrera dimensional se ha roto! ¡A POR ELLOS! ¡POR LA REINA ALMA EN PENA!' WHERE `ID`=45843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마법사여, 일어나라! 포세이큰으로 되살아나라!', `FemaleText_loc4`='起来，法师！重生为被遗忘者吧！', `FemaleText_loc5`='起來吧，法師!重生為被遺忘者!', `FemaleText_loc7`='¡Alzaos, magos! ¡Renaced como Renegados!' WHERE `ID`=45844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 대족장님의 충실한 종복이니 아무것도 받지 않는다네. 그분께서 지혜롭게 내 망치를 인도하실 뿐이지.', `MaleText_loc4`='即使我是酋长真正的忠仆，他也不会轻易给我奖励。他的智慧指引着我的战锤。', `MaleText_loc5`='大酋長不會輕易加恩於人。我是他忠貞不二的屬下，他的睿智指引著我的戰錘。', `MaleText_loc7`='Pero soy un leal súbdito del Jefe de Guerra y no otorga favores a la ligera. Su buen juicio guía mi martillo.' WHERE `ID`=45845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘리자는 참 예뻐요오오오... 정말 예뻐요오오오...', `FemaleText_loc4`='伊莉莎很美……真是很美……', `FemaleText_loc5`='伊莉莎好漂亮...好好好好漂亮...', `FemaleText_loc7`='Eliza essss bonita... Tan bonita...' WHERE `ID`=45846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 그리핀! 우리 번개야... 놈들이 내 그리핀을 쐈어! 그 더러운 짐승들이 하늘에서 내 사랑스러운 번개를 쐈다고!', `MaleText_loc4`='我的鸟！闪电——他们射中了她！那些肮脏的野兽从天空中射中了她！', `MaleText_loc5`='閃電!我的愛鳥被他們射下來了!那些個該死的東西把她從天上射下來了!', `MaleText_loc7`='¡Mi pájaro! Relámpago... ¡Le han disparado! ¡Esas apestosas bestias le han disparado desde el cielo!' WHERE `ID`=45847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾은 우리 번개. 회복하려면 시간이 좀 걸릴 게야.', `MaleText_loc4`='可怜的闪电。她需要一段时间才能复原。', `MaleText_loc5`='可憐的閃電，她得休養好一段時間才能恢復。', `MaleText_loc7`='Pobre Relámpago. Necesitará mucho tiempo para recuperarse.' WHERE `ID`=45848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 그래 본 적이 있는 저희는 지진이 얼마나 위험한지 알고 있습니다. 엑소다르의 불시착으로 오늘날까지도 땅이 흔들리고 있으니 말이오.', `MaleText_loc4`='还有那些对这些地震的危险性了解得一清二楚的人。我们唐突的着陆让埃索达时至今日都还在震颤。', `MaleText_loc5`='那些個真的明白這些地震有多危險的人。直到今日，艾克索達都還因為我們突如其來的抵達而震動不已。', `MaleText_loc7`='Y aquellos que sí nos lo permitimos sabemos lo peligrosos que pueden ser estos terremotos. A día de hoy el Exodar sigue temblando por nuestra abrupta llegada.' WHERE `ID`=45849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...한편으로는 이 "자동 진동 장치 2000"이라는 장치가 유용하게 쓰일 수도 있겠지만, 반면에 우리 노움들은 지진 때문에 던 모로의 산이 아이언포지로 무너져내리는 모습은 절대로 보고 싶지 않아요.', `MaleText_loc4`='……因为从好的方面说，这可能是个便利的装置——“摇晃器2000型”。可是另一方面，我们侏儒最不愿看到的就是丹莫罗群山崩塌，将铁炉堡压成碎片。', `MaleText_loc5`='...因為就另一角度來講，「搖一噸2000」是有可能會滿好用的啦。不過相對的，我們地精可也不希望丹莫洛的山垮下來把鐵爐堡給埋了。', `MaleText_loc7`='...Por un lado, podría ser un artilugio muy útil, el "Sacudetrón 2000". Por otro, lo último que queremos los gnomos es que las montañas de Dun Morogh se derrumben y aplasten Forjaz.' WHERE `ID`=45850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 날아갈 준비는 됐나?', `MaleText_loc4`='好吧。准备好飞翔了吗？', `MaleText_loc5`='好的，準備要起飛了嗎?', `MaleText_loc7`='¿Y bien? ¿$gListo:Lista; para volar?' WHERE `ID`=45851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 가시죠!', `MaleText_loc4`='我准备好了。开始吧！', `MaleText_loc5`='準備好了，走吧!', `MaleText_loc7`='Estoy listo. ¡Vamos!', `FemaleText_loc1`='준비됐어요. 가시죠!', `FemaleText_loc4`='我准备好了。开始吧！', `FemaleText_loc5`='準備好了，走吧!', `FemaleText_loc7`='Estoy lista. ¡Vamos!' WHERE `ID`=45852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 저희가 원한다고 해서 정말 주민들을 이동시킬 수 있을지조차도 확신할 수가 없네요. 심지어 사나운 정령들이 도시와 영토 여기저기서 모습을 보이고 있다는 얘기도 들리고 있어요. 다른 곳으로 이동하는 것이 좋은 방법이 아닐 수도 있습니다.', `FemaleText_loc4`='虽然我们想要组织人民进行迁移，但我不知道是否能做得到。我们已经接到报告，元素出现在各个地方，向我们发动袭击。无论城镇还是郊野，无一能够幸免。迁移也许不是个好选择。', `FemaleText_loc5`='我不曉得有沒有辦法把我們的人給組織起來，做好動身的準備。雖然我們很想，但是我們也接到了報告說隨處出現了許多不懷好意的元素怪物，有些是在野外，但有些就在城鎮裡。我們或許沒辦法如願離開。', `FemaleText_loc7`='No creo que pudiéramos organizar a nuestra gente y marcharnos aunque quisiéramos. También nos han informado de unos elementales hostiles que han aparecido en nuestras tierras; a veces en pueblos, a veces en el campo. Es posible que el traslado no sea una opción.' WHERE `ID`=45853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그나마 노움 똥만큼 작은 좋은 소식이 있긴 한데... 아! 미안하네, 맥카토크. 땅의 흔들림이 대지 고리회를 각성시킨 것이지. 심지어는 와일드해머 주술사들까지도 도움을 주겠다고 나서고 있으니 말일세.', `MaleText_loc4`='嗯，至少还有那么点儿好消息……无意冒犯，格尔宾。震颤似乎也引起了大地之环的注意。就连蛮锤萨满祭司都伸出了援手。', `MaleText_loc5`='還是有一點點的好消息啦...我沒有惡意，傑爾賓。地震好像喚醒了陶土議會。連那些個蠻錘薩滿都來幫忙了。', `MaleText_loc7`='Bueno, al menos hay una pequeña buena noticia... Sin ofender, Gelbin. Los temblores parecen haber despertado al Anillo de la Tierra. Hasta los chamanes Martillo Salvaje nos han ofrecido su ayuda.' WHERE `ID`=45854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩌면 이런 일들이 셴드랄라의 명가를 불러낸 것일 수도 있겠군요.', `FemaleText_loc4`='也许辛德拉的上层精灵也是因此赶来的。', `FemaleText_loc5`='說不定辛德拉的精靈貴族也是因為發生了這些事情才現身而來的。', `FemaleText_loc7`='Quizá sean también estos acontecimientos los que han provocado que los Altonato salgan de Shen''dralar.' WHERE `ID`=45855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 이 세상이 산산이 조각나고 있는 것 같습니다. 저는 이미 이런 증상을 본 적이 있지요... 드레노어에서 말입니다. 우리가 막을 수 없는 일일지도 모릅니다. 어쩌면 도망치는 것이 최고의 선택일 수도 있지요.', `MaleText_loc4`='这个世界仿佛正在破碎。我曾在德拉诺见过这些征兆……我们也许无力阻止这场灾难。逃生或许是我们最好的选择。', `MaleText_loc5`='這個世界彷彿要整個崩裂開了。我見識過這種跡象，就在德拉諾...也許我們真的無力阻止，只能夠設法逃離。', `MaleText_loc7`='Es como si este mundo se estuviera viniendo abajo. Ya he visto estos síntomas antes, en Draenor... Puede que no podamos detenerlos. Quizá la mejor opción sea la huida.' WHERE `ID`=45856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 시점에서 도망치는 방법을 고려하고 싶지는 않소. 다른 방법을 찾을 것이오. 울두아르의 석판이 우리에게 실마리를 가져다줄 수도 있소.', `MaleText_loc4`='逃生可不是我眼下愿意采纳的方案。我们会想出其它办法来的。也许这些来自奥杜尔的石板能帮我们更好的理解当前的困境。', `MaleText_loc5`='此刻我並不希望將逃離這個作法納入考量。我們一定得找出別種方法。或許，奧杜亞發現的這幾塊石板可以解答我們的疑惑。', `MaleText_loc7`='La huida no es una opción que esté dispuesto a considerar en este momento. Encontraremos otra forma. A lo mejor estas tablillas de Ulduar esclarecerán la situación.' WHERE `ID`=45857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든 최대한 빨리 해결책을 찾아야만 해요. 주민들은 두려움에 떨고 있고, 이교도들은 그 두려움을 이용하고 있으니까요.', `FemaleText_loc4`='希望我们能尽快找到答案。这里的人民惊惧不已，而教徒们正在利用他们的恐惧。', `FemaleText_loc5`='希望我們能夠很快就找到這些個答案。民眾都很害怕，而那些邪教徒也正在利用大家的恐懼。', `FemaleText_loc7`='Espero que encontremos esas respuestas pronto. La gente tiene miedo y los cultores se aprovechan de ello.' WHERE `ID`=45858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도는 문제를 악화시키기만 할 뿐이오. 세상의 종말이 왔다는 둥, 세계가 산고를 겪는 중이라는 둥... 모두 과장된 얘기지만, 대중들은 결코 그런 얘기를 무시할 수만은 없을 거요.', `MaleText_loc4`='这些教徒只是在使问题更加恶化。他们到处鼓吹末日论，或是宣扬世界正在遭受新生前的剧痛……他们极尽夸张之能事，让人们无法听而不闻。', `MaleText_loc5`='那些邪教徒只會讓問題變得更嚴重而已。他們到處散佈謠言，說什麼我們的世界就要毀滅了、世界正在歷經生產的陣痛...一般民眾很容易受到這些危言聳聽的言論的影響。', `MaleText_loc7`='Esos cultores no hacen más que agravar el problema. Predican el fin del mundo, o dicen que el mundo sufre los dolores del parto... Es una hipérbole que al pueblo le cuesta ignorar.' WHERE `ID`=45859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분명히 시련의 시기입니다. 무지로 말미암은 두려움이 사람들에게 어리석은 행동을 부추기고 있어요.', `FemaleText_loc4`='真是困难时期啊。对未知的恐惧会导致人们做出蠢事来。', `FemaleText_loc5`='局勢動盪不安。對未知事物的恐懼會讓人做出愚蠢的事情。', `FemaleText_loc7`='En verdad son tiempos difíciles. El miedo a lo desconocido impulsa a las personas a cometer estupideces.' WHERE `ID`=45860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해결책의 부재는 혼란을 가중시키고 있지요.', `MaleText_loc4`='而我们找不到答案，这只会激起人们更大的困惑。', `MaleText_loc5`='偏偏我們又一籌莫展、沒有答案，害事情變得更為混亂。', `MaleText_loc7`='Y nuestra falta de respuestas solo alimenta la confusión.' WHERE `ID`=45861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 사실이 우리가 문제의 핵심을 파헤쳐야 하는 이유라네. 울두아르의 석판이 우리를 올바른 길로 인도할 걸세. 브란이 그렇게 확신하고 그렇다면 나도 그렇게 확신한다네.', `MaleText_loc4`='所以我们更有理由对此追根究底。来自奥杜尔的石板将为我们指出正确的方向。布莱恩对这一点非常坚信。如果布莱恩坚信，那我也一样。', `MaleText_loc5`='所以我們更應該要加緊把真相給找出來。奧杜亞的這塊石板能為我們指出正確的方向，這點布萊恩非常肯定。而既然布萊恩這麼有信心，那我也相信他。', `MaleText_loc7`='Más razón todavía para que lleguemos al fondo del asunto. Esta tablilla de Ulduar nos conducirá en la dirección correcta. Brann está seguro. Y si Brann está seguro, yo estoy seguro.' WHERE `ID`=45862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지에 관해서라면 드워프와 논쟁하지 않는 것이 상책이지요. 브론즈비어드 형제가 석판이 대지의 문제를 해결하는데 도움을 줄 것이라고 확신한다면, 우리는 어떻게든 그들을 도와야 합니다.', `FemaleText_loc4`='我已经说过，凡是跟大地有关的事情都别跟矮人争。要是铜须家族的人相信这块石板能解决困扰大地的难题，那我们就该尽力支持他们。', `FemaleText_loc5`='我知道，凡是跟土地有關的事情都最好別跟矮人爭辯。如果你們銅鬚兄弟都相信這塊石板可以協助我們解決大地崩裂的問題，那我們一定全力支持到底。', `FemaleText_loc7`='Me cuidaré mucho de discutir sobre la tierra con un enano. Si los Barbabronce están seguros de que esta tablilla ayudará a solucionar los problemas de la tierra, entonces deberíamos apoyarlos sin dudarlo.' WHERE `ID`=45863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 위선적인 모험가들! 우릴 습격하려고 무기를 가져왔으면서, 모른 척하는 걸 보라지!', `FemaleText_loc4`='冒险者都是伪君子！难道你是刚刚在路边拣到了你的武器吗？', `FemaleText_loc5`='冒險者通通都是偽君子 !就像「你」才剛剛在路邊「找到」你的武器一樣!', `FemaleText_loc7`='¡Los aventureros son unos hipócritas! ¡Como si te hubieras encontrado tu arma en el suelo!' WHERE `ID`=45864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오그리마 어디를 가 봐도 더 좋은 총기는 못 찾으세요.', `FemaleText_loc4`='在奥格瑞玛的其它地方，你再也无法找到比这个更好的火器了。', `FemaleText_loc5`='你在奧格瑪別處絕對找不到比這更好的火器。', `FemaleText_loc7`='No encontrarás un arma de fuego mejor en todo Orgrimmar.' WHERE `ID`=45865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님이 오실 테니 기다리라고 오르막이 얘기해 주더군요.', `FemaleText_loc4`='奥玛克告诉我，你会来的，$n。', `FemaleText_loc5`='奧瑪克跟我說了你會過來，$n。', `FemaleText_loc7`='Ormak me dijo que vendrías, $n.' WHERE `ID`=45866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림자송곳니 성채에서 가져오신 이 재료는 평범한 물건이 아니에요. 그대 무기에 엄청난 힘을 불어넣을 거예요.', `FemaleText_loc4`='你从影牙城堡拿出来的这些材料绝非凡品。它们能够让你的武器具有强大的力量。', `FemaleText_loc5`='你從影牙城堡帶回來的東西可不是尋常之物，它們能讓你的武器獲得強大的威力。', `FemaleText_loc7`='Estos materiales que has traído del Castillo de Colmillo Oscuro no son nada comunes. Imbuirán tu arma con gran poder.' WHERE `ID`=45867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 활이 완성됐어요. $n 님이 호드를 위해 애쓰는 만큼 이 활도 그대를 위해 한몫해 주길 바라요.', `FemaleText_loc4`='你的弓完成了，$n。希望它能为你建立伟大的功勋，就如同你为部落建立的伟大功勋一样。', `FemaleText_loc5`='你的弓已經好了，$n。希望它對你的貢獻就如同你對部落的貢獻一樣大。', `FemaleText_loc7`='Tu arco está completo, $n. Espero que te sirva tan bien como tú has servido a la Horda.' WHERE `ID`=45868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자그, 내가 부탁했던 주문식과 시약 다른 데다 치웠나?', `MaleText_loc4`='夏格，你是不是把我要的那些配方和材料收起来了？', `MaleText_loc5`='夏格，我跟你要的那些配方跟藥材呢?', `MaleText_loc7`='Jhag, ¿has apartado esas fórmulas y componentes que te pedí?' WHERE `ID`=45869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여가 다 됐네. $n, 여기 자네 지팡이를 받게. 언제나 호드를 위해 써 주게나.', `MaleText_loc4`='这样应该就能完成附魔步骤了。$n，给你新的法杖。用它来为部落建功吧。', `MaleText_loc5`='付魔應該這樣就完成了。這就是你的新法杖，$n。好好善用它來為部落貢獻。', `MaleText_loc7`='Esto debería completar el encantamiento. Aquí tienes tu nuevo bastón, $n. Úsalo siempre en servicio de la Horda.' WHERE `ID`=45870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님, 여기 모아 왔습니다.', `MaleText_loc4`='主人，我已经为您把它们搜集好了。', `MaleText_loc5`='師父，我已經幫你收集好了。', `MaleText_loc7`='Te los he dejado aquí, maestro.' WHERE `ID`=45871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로가나르 말로는 그대가 그림자송곳니 성채에서 강력한 유물을 가져온다고 하더군요. 처음에는, 이 재료의 가치가 의심스럽긴 했지요.', `FemaleText_loc4`='洛甘纳尔说你会从影牙城堡带来强大的宝物。一开始，我还在怀疑你能弄些什么东西出来。', `FemaleText_loc5`='洛甘納爾說你會從影牙城堡帶回來強大的寶物，起初我還很質疑這些東西的價值。', `FemaleText_loc7`='Loganaar dijo que traerías unos poderosos artefactos del Castillo de Colmillo Oscuro. Al principio cuestioné el valor de tales materiales.' WHERE `ID`=45872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아무것도 말하지 않을 거다, 이 돼지 같은 $r 녀석아!', `MaleText_loc4`='我什么都不告诉你，$r混蛋！', `MaleText_loc5`='我什麼也不會告訴你，$r豬玀!', `MaleText_loc7`='¡No te diré nada, $gcerdo:cerda; $r!' WHERE `ID`=45873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손에 죽는 것 따위는 두렵지 않다, $r!', `MaleText_loc4`='我不害怕死亡和你的暴行，$r！', `MaleText_loc5`='$r，我才不怕死在你手下!', `MaleText_loc7`='¡No temo la muerte por tu mano, $r!' WHERE `ID`=45874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 드워프는 우리 손에 들어왔다! 이제 네 동료가 아니야!', `MaleText_loc4`='现在这个矮人属于我们了！滚开吧！', `MaleText_loc5`='現在這矮人是我們國王的了!不是你的!', `MaleText_loc7`='¡Ahora el enano es de los nuestros! ¡No de los tuyos!' WHERE `ID`=45875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='재료를 손에 넣고 보니, 로가나르가 말한 힘이 느껴지는군요. 이 재료라면 그대에게 딱 맞는 무기를 만들 수 있을 겁니다.', `FemaleText_loc4`='当我看到这些物品的时候，我就感觉到了洛甘纳尔所说的那种强大力量。它们可以被做成一件适合于你的精良武器。', `FemaleText_loc5`='如今東西已經在我手裡，我確實感應到了洛甘納爾所說的力量，而且可以用它們來為你打造出一把合適的武器。', `FemaleText_loc7`='Pero, ahora que tengo los objetos, percibo el poder del que hablaba Loganaar. Formarán un arma digna de ti.' WHERE `ID`=45876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병숲은 아주 넓지! 네 친구는 그 속으로 사라졌으니, 절대 찾지 못할 거다!', `MaleText_loc4`='病木林实在是太大了！你的朋友失踪了！你绝对不可能找到他！', `MaleText_loc5`='病木林太大了!你的朋友已經不見了!你永遠都找不到他!', `MaleText_loc7`='¡El Bosque de la Peste es demasiado grande! ¡Tu amigo está perdido! ¡Nunca lo encontrarás!' WHERE `ID`=45877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 드워프를 네게 돌려주는 일은 없을 거다!', `MaleText_loc4`='她绝对不会将那个矮人还给你！', `MaleText_loc5`='她絕對不會把那個矮人交給你!', `MaleText_loc7`='¡Ella nunca te devolverá al enano!' WHERE `ID`=45878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 $r 같으니! 드워프를 찾고 있다고? 아나스타리 남작부인이 아주 잘 숨겨두셨다!', `MaleText_loc4`='愚蠢的$r！你在找那个矮人？安娜丝塔丽已经妥善地把他藏起来了！', `MaleText_loc5`='愚蠢的$r!你要找那個矮人? 安娜絲塔麗男爵夫人把他藏得非常隱密!', `MaleText_loc7`='¡$gEstúpido:Estúpida; $r! ¿Buscas al enano? ¡La baronesa Anastari lo ha escondido bien!' WHERE `ID`=45879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 우릴 절대 막을 수 없어!', `MaleText_loc4`='你绝对无法阻止我们！', `MaleText_loc5`='你絕對阻止不了我們!', `MaleText_loc7`='¡Nunca nos detendrás!' WHERE `ID`=45880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아악...', `MaleText_loc4`='啊……', `MaleText_loc5`='呃啊...', `MaleText_loc7`='Argh...' WHERE `ID`=45881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 스컬지를 절대 막을 수 없어!', `MaleText_loc4`='你绝不可能阻止天灾！', `MaleText_loc5`='你絕對阻止不了天譴軍團!', `MaleText_loc7`='¡No se puede detener a la Plaga!' WHERE `ID`=45882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽는 것이 두렵지 않다, $r!', `MaleText_loc4`='死亡对我毫无意义，$r！', `MaleText_loc5`='死亡對我毫無意義，$r!', `MaleText_loc7`='¡La muerte no significa nada para mí, $r!' WHERE `ID`=45883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오... 마법부여가 제 기대보다 훨씬 더 성공적이군요.', `FemaleText_loc4`='哦，天哪……这次的作品甚至远比我想象的更加强大。', `FemaleText_loc5`='哦...我沒有料到，法術竟然成功了。', `FemaleText_loc7`='Oh, vaya... El encantamiento ha tenido un éxito que supera mis expectativas.' WHERE `ID`=45884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 지팡이를 수여함에 따라, 세나리온 의회는 그대에게 강력한 마력이 담긴 장비를 선사하는 것입니다.', `FemaleText_loc4`='议会将这支法杖给你，就是将一件拥有强大力量的宝物放在你手中，$n。你要用它来守卫我们所信奉的原则。', `FemaleText_loc5`='這柄法杖...議會可是給了你一件法力強大的物品啊，$n。請善用它來捍衛我們的理念。', `FemaleText_loc7`='Con este bastón el círculo te confía un objeto de gran poder, $n. Utilízalo para salvaguardar los principios de nuestra orden.' WHERE `ID`=45885;
