UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 등대를 공격했습니다! 방어하지 못하면 1분 안에 얼라이언스에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了灯塔！如果不赶快采取行动的话，联盟将在1分钟内占据它！', `MaleText_loc5`='$n攻佔了燈塔!如果沒有其他人採取行動的話，聯盟將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama el faro! ¡Si nadie acepta el desafío, la Alianza lo tomará en 1 minuto!' WHERE `ID`=45909;
