UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 원소의 힘을 빌려 스톰윈드에서 높은 둑으로 통하는 차원문을 열기로 약속했습니다. 하지만 황혼의 요새에서 원소의 흐름을 어지럽혀 일이 제대로 진척되지 않고 있어요.$B$B대체 저기서 어떤 미친 짓을 벌이고 있을까요?', `FemaleText_loc4`='我们已经做出保证，要打开一个从暴风城前往高地的元素通道。但暮光堡垒的干扰让我们无法成功。$B$B他们到底在那里发什么疯？', `FemaleText_loc5`='我們已承諾要開啟一道從暴風城通往暮光高地的元素傳送門，可是暮光堡壘卻在阻撓我們的進度。$B$B他們那邊到底發生了什麼瘋狂的怪事?', `FemaleText_loc7`='Nos hemos comprometido a abrir una puerta elemental desde Ventormenta hasta las Tierras Altas, pero las interferencias del Bastión Crepuscular dificultan nuestro trabajo.$b$b¿Qué locuras están llevando a cabo allá arriba?' WHERE `ID`=45911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약속된 시간이 오면, 그들이 바람과 물의 정령을 풀어놓을 것이다. 폭풍우로 도시를 휩쓸고 우리 주인님의 영광스러운 귀환을 위한 무대를 준비할 것이다!', `MaleText_loc4`='届时，他们将放出风水两种元素，用狂风暴雨吞没整座城市，为我们主人的荣归搭设舞台！', `MaleText_loc5`='等指定的時間一到，他們將會釋放出風元素和水元素，用暴風雨吞沒這座城市，為我主的盛大歸來譜奏出序章!', `MaleText_loc7`='Cuando llegue el momento, liberarán a los elementales de viento y agua. ¡Cubrirán la ciudad con una tormenta que allanará el camino para el glorioso retorno de nuestro maestro!' WHERE `ID`=45912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어나고 있는 거죠?', `MaleText_loc4`='发生什么事了？', `MaleText_loc5`='這是怎麼回事?', `MaleText_loc7`='¿Qué está pasando?', `FemaleText_loc1`='무슨 일이 일어나고 있는 건가요?', `FemaleText_loc4`='发生什么事了？', `FemaleText_loc5`='這是怎麼回事?', `FemaleText_loc7`='¿Qué está pasando?' WHERE `ID`=45913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체 무슨 일입니까?', `MaleText_loc4`='出了什么事？', `MaleText_loc5`='發生了什麼事情?', `MaleText_loc7`='¿Qué pasa?', `FemaleText_loc1`='이게 대체 무슨 일이죠?', `FemaleText_loc4`='出了什么事？', `FemaleText_loc5`='發生了什麼事情?', `FemaleText_loc7`='¿Qué pasa?' WHERE `ID`=45914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰병의 일지를 가져갑니다.', `MaleText_loc4`='取得斥候的日志。', `MaleText_loc5`='拿起斥候的日誌。', `MaleText_loc7`='Coge el diario del explorador.', `FemaleText_loc1`='정찰병의 일지를 가져갑니다.', `FemaleText_loc4`='取得斥候的日志。', `FemaleText_loc5`='拿起斥候的日誌。', `FemaleText_loc7`='Coge el diario del explorador.' WHERE `ID`=45915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제쯤 이 모든 게 끝날까요?', `MaleText_loc4`='什么时候才能结束？', `MaleText_loc5`='這要什麼時候才會結束?', `MaleText_loc7`='¿Cuándo acabará?', `FemaleText_loc1`='언제쯤 이 모든 게 끝날까요?', `FemaleText_loc4`='什么时候才能结束？', `FemaleText_loc5`='這要什麼時候才會結束?', `FemaleText_loc7`='¿Cuándo acabará?' WHERE `ID`=45916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지진이다!', `MaleText_loc4`='地震！', `MaleText_loc5`='地震!', `MaleText_loc7`='¡Terremoto!', `FemaleText_loc1`='지진이다!', `FemaleText_loc4`='地震！', `FemaleText_loc5`='地震!', `FemaleText_loc7`='¡Terremoto!' WHERE `ID`=45917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이제 죽었소!', `MaleText_loc4`='我们死定了！', `MaleText_loc5`='我們完了!', `MaleText_loc7`='¡Estamos perdidos!', `FemaleText_loc1`='우린 이제 죽었어요!', `FemaleText_loc4`='我们死定了！', `FemaleText_loc5`='我們完了!', `FemaleText_loc7`='¡Estamos perdidos!' WHERE `ID`=45918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 유적을 찾아냈다!$b$b유적 전체에 고대 건축물의 향기가 진동하는 곳이다.$b$b아, 오늘 시간이 이렇게 늦지만 않았어도, 즉시 그 방을 조사하기 시작할 텐데!$b$b오늘 밤은 잠을 이룰 수 없을 것만 같다...', `MaleText_loc4`='我发现了一个令人难以置信的地方！$b$b这里到处都闪耀着古代文明的光辉。$b$b如果不是因为今天太晚了，我真想立刻就对这座建筑展开调查！$b$b今晚估计我要睡不着觉了……', `MaleText_loc5`='我找到了一個不得了的地方!$b$b這整塊區域都迴盪著古老建築的共鳴。$b$b要不是現在天色已晚，我一定會立刻衝進裡頭進行調查!$b$b今晚要安心睡一覺可難囉...', `MaleText_loc7`='¡He encontrado un sitio increíble!$b$bToda la zona vibra con el zumbido de la arquitectura antigua.$b$bSi no fuera tan tarde, ¡saldría a investigar la cámara ahora mismo!$b$bEsta noche me va a costar conciliar el sueño...' WHERE `ID`=45919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 죽기 싫단 말입니다!', `MaleText_loc4`='我不想死！', `MaleText_loc5`='我不想死!', `MaleText_loc7`='¡No quiero morir!', `FemaleText_loc1`='아직은 죽기 싫어요!', `FemaleText_loc4`='我不想死！', `FemaleText_loc5`='我不想死!', `FemaleText_loc7`='¡No quiero morir!' WHERE `ID`=45920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이런 일이 일어나는 겁니까?', `MaleText_loc4`='为什么会这样？', `MaleText_loc5`='為什麼會發生這種事情?', `MaleText_loc7`='¿Por qué está pasando esto?', `FemaleText_loc1`='왜 이런 일이 일어나는 거죠?', `FemaleText_loc4`='为什么会这样？', `FemaleText_loc5`='為什麼會發生這種事情?', `FemaleText_loc7`='¿Por qué está pasando esto?' WHERE `ID`=45921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 멈추게 해주시오.', `MaleText_loc4`='拜托……阻止这一切吧。', `MaleText_loc5`='求求你...阻止它。', `MaleText_loc7`='Por favor... Haz que pare.', `FemaleText_loc1`='제발... 멈추게 해주세요.', `FemaleText_loc4`='拜托……阻止这一切吧。', `FemaleText_loc5`='求求你...阻止它。', `FemaleText_loc7`='Por favor... Haz que pare.' WHERE `ID`=45922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람과 파도여, 대지와 불이여... 스톰윈드로 길을 열어 주소서! 됐어요, $n 님!', `FemaleText_loc4`='以风、水、地、火之力……我们将前往暴风城，$n！', `FemaleText_loc5`='風與浪，地與火...吾等向暴風城而行，$n!', `FemaleText_loc7`='Por aire y olas, por tierra y fuego... ¡Nos vamos a Ventormenta, $n!' WHERE `ID`=45923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문이 열렸어요! 당신 덕분에, 이제 스톰윈드와 황혼의 고원을 빠르게 오갈 수 있습니다.', `FemaleText_loc4`='传送门打开了！感谢你的帮助，现在我们能够从暴风城迅速到达暮光高地了。', `FemaleText_loc5`='傳送門已經開啟了!感謝你的協助，我們總算可以快速從暴風城前往暮光高地。', `FemaleText_loc7`='¡Se ha abierto el portal! Gracias a tu esfuerzo, ahora podemos viajar entre Ventormenta y las Tierras Altas Crepusculares con rapidez.' WHERE `ID`=45924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 높이 날아오르는 것처럼 신나는 일도 없답니다.$B$B아, 하늘 높이 날아오르면서 전투를 벌이고는, 끝난 뒤에 한잔하는 건 빼고 말이죠!', `MaleText_loc4`='没有什么比在高空中翱翔更令人兴奋了。$B$B嗯，也许在飞翔时战斗会更好，最好在战斗之后还能喝上一杯上好的啤酒！', `MaleText_loc5`='沒有比在天空遨翔更叫人痛快的事情了。$B$B嗯，大概只輸給在天空裡邊遨翔邊戰鬥，還有之後的暢飲麥酒吧!', `MaleText_loc7`='No hay nada más emocionante que surcar el aire.$b$b¡Bueno, quizá surcar el aire mientras luchas, y luego tomarte una buena jarra de cerveza!' WHERE `ID`=45925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앵거스, 당신의 와일드해머 편대를 이끌고 SI:7 요원들을 낙하지점까지 호위해 주려고 왔습니다.', `MaleText_loc4`='安古斯，我来这里是为了领导蛮锤小队，空降军情七处的人员。', `MaleText_loc5`='安古斯，我是來帶領蠻錘部隊，還有載送軍情七處特務的。', `MaleText_loc7`='Angus, he venido para liderar el escuadrón Martillo Salvaje y desplegar a los agentes del IV:7.', `FemaleText_loc1`='앵거스, 당신의 와일드해머 편대를 이끌고 SI:7 요원들을 낙하지점까지 호위해 주려고 왔어요.', `FemaleText_loc4`='安古斯，我来这里是为了领导蛮锤小队，空降军情七处的人员。', `FemaleText_loc5`='安古斯，我是來帶領蠻錘部隊，還有載送軍情七處特務的。', `FemaleText_loc7`='Angus, he venido para liderar el escuadrón Martillo Salvaje y desplegar a los agentes del IV:7.' WHERE `ID`=45926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 진작 얘기하지 그러셨습니까? 절 대신해 황혼의 이교도 놈들에게 쓴맛을 보여주세요.', `MaleText_loc4`='为什么你不早说？替我给那些暮光异教徒狠狠来一下子，好不好？', `MaleText_loc5`='你怎麼不早說呢?連我的份一起給那些暮光教徒們一些顏色瞧瞧，可以吧?', `MaleText_loc7`='¡Vaya! ¿Por qué no lo has dicho antes? Dales una buena tunda a esos cultores Crepusculares de mi parte, ¿quieres?' WHERE `ID`=45927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 패배했다는 말은 들을 필요도 없소. 보시오... 놈들이 아직도 역병숲을 돌아다니고 있지 않소? 마치 요람에 매달리는 어린아이처럼, 그들은 오염된 땅에 집착하고 있소.$b$b이제 싸울 수밖에 없소. 내 숨이 멎는 순간까지, 난 놈들과 싸우겠소.', `MaleText_loc4`='如果有人告诉你天灾军团被打败了，不要信他的话。看看吧……难道他们不是仍然在病木林横行肆虐吗？他们死守着他们的腐蚀之地，如同儿童拼命抓住自己的小床。$b$b我别无选择，只能战斗。在我呼出最后一口气之前，我绝不会停止和他们的战斗。', `MaleText_loc5`='不要相信什麼天譴軍團已經被打敗的鬼話。你看...病木林不都還是它們嗎?它們死佔著這塊被腐化的地方，簡直就像死抓著毯子不放的小鬼一樣。$b$b我別無選擇，只能繼續戰鬥。在我嚥下最後一口氣之前，我都會繼續對抗它們。', `MaleText_loc7`='Que nadie te diga que hemos derrotado a la Plaga. Mira... ¿acaso no siguen vagando por el Bosque de la Peste? Se aferran a su tierra corrupta como un niño a su manta.$b$bNo tengo más opción que luchar. Lucharé contra ellos hasta el último suspiro.' WHERE `ID`=45928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이교도 집단을 조사하고 있습니다.', `MaleText_loc4`='我们正在调查这些邪教徒组织。', `MaleText_loc5`='我們正在調查這些邪教團體。', `MaleText_loc7`='Estamos investigando estos grupos de cultores.' WHERE `ID`=45929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 보고한 실종 신고를 조사하고 있습니다.', `MaleText_loc4`='我们正在调查你所提交的失踪人口报告。', `MaleText_loc5`='我們正在研究你所提交的失蹤人口報告。', `MaleText_loc7`='Estamos investigando el informe de persona desaparecida que presentaste.' WHERE `ID`=45930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 소식이 있으면 알려 드리겠습니다.', `MaleText_loc4`='一旦有消息，我们会即刻通知你。', `MaleText_loc5`='我們一有新的消息就會通知你。', `MaleText_loc7`='Te avisaremos en cuanto tengamos noticias.' WHERE `ID`=45931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 전력을 기울이고 있습니다.', `MaleText_loc4`='我们在竭尽所能。', `MaleText_loc5`='我們正在盡全力進行。', `MaleText_loc7`='Hacemos lo que podemos.' WHERE `ID`=45932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 이 상황을 잘 처리하고 있습니다.', `MaleText_loc4`='情况在我们的掌控之中。', `MaleText_loc5`='我們已經把局勢給穩住了。', `MaleText_loc7`='Lo tenemos todo bajo control.' WHERE `ID`=45933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간에도 저희는 이교도의 활동을 조사하고 있습니다.', `MaleText_loc4`='我们当下正在对邪教徒的活动进行调查。', `MaleText_loc5`='就在此刻，我們已經在調查邪教徒的活動了。', `MaleText_loc7`='Estamos investigando las actividades de los cultores ahora mismo.' WHERE `ID`=45934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 이런 실종 신고를 아주 중요하게 생각합니다.', `MaleText_loc4`='我们在以非常严肃的态度处理这些失踪人口报告，女士。', `MaleText_loc5`='女士，我們非常重視那些失蹤人口的報告。', `MaleText_loc7`='Nos tomamos estos informes de personas desaparecidas muy en serio, señora.' WHERE `ID`=45935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 전문가들이 이 문제를 조사하고 있습니다.', `MaleText_loc4`='我们派出了精英团队调查这些问题。', `MaleText_loc5`='我們已經派出了最精銳的人手去進行調查。', `MaleText_loc7`='Tenemos a nuestros mejores agentes investigando estos casos.' WHERE `ID`=45936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한가요?', `MaleText_loc4`='这里安全吗？', `MaleText_loc5`='安全嗎?', `MaleText_loc7`='¿Es seguro?', `FemaleText_loc1`='안전한가요?', `FemaleText_loc4`='这里安全吗？', `FemaleText_loc5`='安全嗎?', `FemaleText_loc7`='¿Es seguro?' WHERE `ID`=45937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두... 죽은 건가요?', `MaleText_loc4`='他们……他们全都死了？', `MaleText_loc5`='他們...全都死了嗎?', `MaleText_loc7`='¿Están... están todos muertos?', `FemaleText_loc1`='모두... 죽은 건가요?', `FemaleText_loc4`='他们……他们全都死了？', `FemaleText_loc5`='他們...全都死了嗎?', `FemaleText_loc7`='¿Están... están todos muertos?' WHERE `ID`=45938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 어둠 속에 숨어 있다가 갑자기 나타났습니다. 우린 손도 쓸 수 없었고요.', `MaleText_loc4`='他们从阴影中发动攻击。我们连反抗的机会都没有。', `MaleText_loc5`='他們從暗處展開偷襲，我們根本毫無反擊的機會。', `MaleText_loc7`='Atacaron desde las sombras. No tuvimos ninguna posibilidad.', `FemaleText_loc1`='놈들이 어둠 속에 숨어 있다가 갑자기 나타났어요. 우린 손도 쓸 수 없었다고요.', `FemaleText_loc4`='他们从阴影中发动攻击。我们连反抗的机会都没有。', `FemaleText_loc5`='他們從暗處展開偷襲，我們根本毫無反擊的機會。', `FemaleText_loc7`='Atacaron desde las sombras. No tuvimos ninguna posibilidad.' WHERE `ID`=45939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝장이라고 생각했습니다!', `MaleText_loc4`='我还以为自己死定了！', `MaleText_loc5`='我還以為我也完蛋了!', `MaleText_loc7`='¡Pensé que estaba acabado!', `FemaleText_loc1`='이제 끝장이라고 생각했어요!', `FemaleText_loc4`='我还以为自己死定了！', `FemaleText_loc5`='我還以為我也完蛋了!', `FemaleText_loc7`='¡Pensé que estaba acabada!' WHERE `ID`=45940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 말하는 영웅이 바로 당신이로군요. 감사합니다.', `MaleText_loc4`='你一定就是那个所有人都在谈论的英雄。谢谢你。', `MaleText_loc5`='你必定就是最近大家在談論的那位英雄，謝謝你。', `MaleText_loc7`='Tú debes de ser $gel héroe del:la heroína de la; que habla todo el mundo. Gracias.', `FemaleText_loc1`='사람들이 말하는 영웅이 바로 당신이군요. 고마워요.', `FemaleText_loc4`='你一定就是那个所有人都在谈论的英雄。谢谢你。', `FemaleText_loc5`='你必定就是最近大家在談論的那位英雄，謝謝你。', `FemaleText_loc7`='Tú debes de ser $gel héroe del:la heroína de la; que habla todo el mundo. Gracias.' WHERE `ID`=45941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 추잡한 이교도들이 내 아내를 앗아갔어! 내 아내는 우릴 남겨두고 너희가 지껄이는 터무니없는 ''세상의 종말''을 쫓아갔단 말이야!', `MaleText_loc4`='你们这群卑鄙的邪教徒夺走了我的丈夫！他就这样丢下我们，去追随你们所鼓吹的那些“末日论”鬼话了！', `MaleText_loc5`='你們這些可惡的邪教徒搶走了我的丈夫!害他拋棄了我們，去追隨你們胡扯的「世界末日」鬼話!', `MaleText_loc7`='¡Se han llevado a mi marido, cultores despreciables! ¡Nos ha abandonado porque quería presenciar esas tonterías del "fin del mundo" que predican!', `FemaleText_loc1`='너희 추잡한 이교도들이 내 남편을 앗아갔어! 내 남편은 우릴 남겨두고 너희가 지껄이는 터무니없는 ''세상의 종말''을 쫓아갔단 말이야!', `FemaleText_loc4`='你们这群卑鄙的邪教徒夺走了我的丈夫！他就这样丢下我们，去追随你们所鼓吹的那些“末日论”鬼话了！', `FemaleText_loc5`='你們這些可惡的邪教徒搶走了我的丈夫!害他拋棄了我們，去追隨你們胡扯的「世界末日」鬼話!', `FemaleText_loc7`='¡Se han llevado a mi marido, cultores despreciables! ¡Nos ha abandonado porque quería presenciar esas tonterías del "fin del mundo" que predican!' WHERE `ID`=45942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 사방에 깔렸습니다! 조심하십시오!', `MaleText_loc4`='他们到处都是！你一定要小心！', `MaleText_loc5`='他們到處都是!小心!', `MaleText_loc7`='¡Están POR TODAS PARTES! ¡CUIDADO!', `FemaleText_loc1`='놈들이 사방에 깔렸어요! 조심하세요!', `FemaleText_loc4`='他们到处都是！你一定要小心！', `FemaleText_loc5`='他們到處都是!小心!', `FemaleText_loc7`='¡Están POR TODAS PARTES! ¡CUIDADO!' WHERE `ID`=45943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 명령을 엿들었습니다... 생존자는 없다고 하더군요...', `MaleText_loc4`='我们听到了他们的命令……不留任何活口……', `MaleText_loc5`='我們偷聽到了他們的命令...不留活口...', `MaleText_loc7`='Hemos escuchado sus órdenes... Ningún superviviente...', `FemaleText_loc1`='그들의 명령을 엿들었어요... 생존자는 없었어요...', `FemaleText_loc4`='我们听到了他们的命令……不留任何活口……', `FemaleText_loc5`='我們偷聽到了他們的命令...不留活口...', `FemaleText_loc7`='Hemos escuchado sus órdenes... Ningún superviviente...' WHERE `ID`=45944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져버려! 내 남편을 빼앗아 간 걸로는 부족한 거냐? 또 뭘 바라는 거지?', `MaleText_loc4`='滚开！你们夺走了我的丈夫，这还不够吗？还想怎么样？', `MaleText_loc5`='滾開!你們搶走了我的丈夫還不夠嗎?你們到底還想要怎樣?', `MaleText_loc7`='¡Largo! ¿No les basta con haberse llevado a mi marido? ¿Qué más quieren?', `FemaleText_loc1`='꺼져버려! 내 남편을 빼앗아 간 걸로는 부족한 거냐? 또 뭘 바라는 거지?', `FemaleText_loc4`='滚开！你们夺走了我的丈夫，这还不够吗？还想怎么样？', `FemaleText_loc5`='滾開!你們搶走了我的丈夫還不夠嗎?你們到底還想要怎樣?', `FemaleText_loc7`='¡Largo! ¿No les basta con haberse llevado a mi marido? ¿Qué más quieren?' WHERE `ID`=45945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 그 사악한 이야기와 함께 이 도시에서 썩 사라져라! 이제 거짓 ''예언''으로 우리 주민들을 홀릴 수는 없다!', `MaleText_loc4`='带着你们邪恶的鬼话离开这座城市！别想再用虚假的“预言”骗走更多市民了！', `MaleText_loc5`='帶著你惡毒的訊息離開這座城!別再用虛假的「預言」騙走更多的市民了!', `MaleText_loc7`='¡Llévense su vil mensaje de esta ciudad! ¡No robarán más ciudadanos con sus falsas "profecías"!', `FemaleText_loc1`='당신의 그 사악한 이야기와 함께 이 도시에서 썩 사라지세요! 이제 거짓 ''예언''으로 우리 주민들을 홀릴 수는 없어요!', `FemaleText_loc4`='带着你们邪恶的鬼话离开这座城市！别想再用虚假的“预言”骗走更多市民了！', `FemaleText_loc5`='帶著你惡毒的訊息離開這座城!別再用虛假的「預言」騙走更多的市民了!', `FemaleText_loc7`='¡Llévense su vil mensaje de esta ciudad! ¡No robarán más ciudadanos con sus falsas "profecías"!' WHERE `ID`=45946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 녀석. 가서 엄마 젖이나 더 먹고 와라.', `MaleText_loc4`='懦弱的狗子。回到你妈妈那里去，好好地躲起来吧。', `MaleText_loc5`='沒種的懦夫，跑回去找你娘躲起來吧。', `MaleText_loc7`='Perro cobarde. Vuelve con tu mamá y escóndete.' WHERE `ID`=45947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님께서 이 잡종들을 살려두신다고? 쓸모없는 것들...', `MaleText_loc4`='黑暗女王会让这些渣滓活着？除非……', `MaleText_loc5`='黑暗女王饒了這些雜碎?沒用的...', `MaleText_loc7`='¿La Dama Oscura ha dejado vivir a estos chuchos? Son inútiles...' WHERE `ID`=45948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 거짓말로 많은 사람을 충분히 현혹하지 않았소! 가까이 오지 마시오!', `MaleText_loc4`='你们用谎言毒害的人还不够多吗？离我远点儿！', `MaleText_loc5`='你用謊言毒化的人心還不夠多嗎?離我遠一點!', `MaleText_loc7`='¿No has envenenado las mentes de bastantes hombres con tus mentiras? ¡Aléjate de mí!', `FemaleText_loc1`='당신의 거짓말로 많은 사람을 충분히 현혹하지 않았나요? 내게 가까이 오지 마세요!', `FemaleText_loc4`='你们用谎言毒害的人还不够多吗？离我远点儿！', `FemaleText_loc5`='你用謊言毒化的人心還不夠多嗎?離我遠一點!', `FemaleText_loc7`='¿No has envenenado las mentes de bastantes hombres con tus mentiras? ¡Aléjate de mí!' WHERE `ID`=45949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 여기 가둔 채 이곳에 불을 질러 버렸어야 했는데...', `MaleText_loc4`='我要把这个地方和他们一起烧光……', `MaleText_loc5`='我會把整個地方和裡面的人都一起燒掉...', `MaleText_loc7`='Yo le habría prendido fuego a todo este lugar con ellos dentro...' WHERE `ID`=45950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 겁쟁이들은 치욕스러운 생을 마감해야 한다. 정말 부끄러운 일이야.', `MaleText_loc4`='这些懦弱的士兵应该在羞耻中死掉。真是巨大的羞耻。', `MaleText_loc5`='這些個膽小的士兵死得不光不彩。這時太難堪了。', `MaleText_loc7`='Estos soldados acobardados deberían morir en la deshonra. Esto es una vergüenza.' WHERE `ID`=45951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 꺼지지 않으면 없애버리겠다!', `MaleText_loc4`='别让我看到你，否则我就对你执行死刑！', `MaleText_loc5`='從我面前滾開，否則我就砍死你!', `MaleText_loc7`='¡Sal de mi vista antes de que te ejecute!' WHERE `ID`=45952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g그:그녀;는 전투 중 사망했소. 잠시 묵념을 합시다...', `MaleText_loc4`='$g他:她;死在了战场上。低下你们的头……', `MaleText_loc5`='$g 他:她;是光榮戰死的。低下頭來...', `MaleText_loc7`='Ha muerto en combate. Inclinad la cabeza...' WHERE `ID`=45953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 안락사였소.', `MaleText_loc4`='这也是一种仁慈。', `MaleText_loc5`='這是仁慈安樂的死法', `MaleText_loc7`='Esta es una muerte piadosa.' WHERE `ID`=45954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이들은 돌아오지 못하는 법이지.', `MaleText_loc4`='懦夫不应该回家。', `MaleText_loc5`='懦夫是回不了家的。', `MaleText_loc7`='Los cobardes no se merecen volver a casa.' WHERE `ID`=45955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 벌레 녀석.', `MaleText_loc4`='没用的蛆虫。', `MaleText_loc5`='沒用的東西。', `MaleText_loc7`='Gusano despreciable.' WHERE `ID`=45956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이 반도를 차지할 겁니다, $c님.$B$B당신은 우리의 무기입니다.$B$B당신은 전쟁을 갈구하는, 죽음의 구도자입니다.', `MaleText_loc4`='$c，你将拥有这座半岛。$B$B你将成为一件武器。$B$B你将成为带来胜利的战争之神。', `MaleText_loc5`='你將擁有這座半島，$c。$B$B你將變成一把武器。$B$B你將成為死亡的使者，祈禱著戰爭的到來。', `MaleText_loc7`='Esta península te pertenecerá, $c.$B$BSerás un arma.$b$bSerás $gun:una; clérigo de la muerte y rezarás por la guerra.' WHERE `ID`=45957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거짓말은 집어치우고 날 평화롭게 내버려 두시오. 이미 이곳에 큰 피해를 주었지잖소!', `MaleText_loc4`='带着你的谎言滚吧，邪教徒。你对我们造成的伤害已经够多了！', `MaleText_loc5`='邪教徒，省省你的鬼話，不要來煩我。你們對這兒的傷害已經夠大了!', `MaleText_loc7`='Llévate tus mentiras y déjame en paz, cultor. ¡Ya han causado bastante daño!', `FemaleText_loc1`='거짓말은 집어치우고 날 평화롭게 내버려 두라고요. 이미 이곳에 큰 피해를 주었잖아요!', `FemaleText_loc4`='带着你的谎言滚吧，邪教徒。你对我们造成的伤害已经够多了！', `FemaleText_loc5`='邪教徒，省省你的鬼話，不要來煩我。你們對這兒的傷害已經夠大了!', `FemaleText_loc7`='Llévate tus mentiras y déjame en paz, cultor. ¡Ya han causado bastante daño!' WHERE `ID`=45958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 정말 많은 발견을 했다!$b$b그 방은 실제로 고대로부터 내려온 것이 틀림없다. 그뿐만 아니라, 지금은 훼손되어 있지만 엄청난 기계 장치가 방 안에 설치되어 있다.$b$b내일 더 자세히 조사해볼 생각이다.$b$b이번 발견으로 슈노츠도 날 눈여겨보게 될 것이다!$b$b이런 엄청난 발견을 했는데 날 진급시켜주지 않을 수 있을까?', `MaleText_loc4`='今天可真是成果丰硕！$b$b这座建筑果然有着古老的起源，里面还有年久失修的宏大装置。$b$b我明天再来详细调查一番。$b$b这个发现肯定会让Schnottz注意到我！$b$b经过这件事，他怎么能不嘉奖我呢？', `MaleText_loc5`='今天是收穫最豐富的一天!$b$b這個房間的確是遠古之源，擁有不可思議的機關結構，但看起來已經荒廢已久。$b$b我明天會多做些調查。$b$b這項發現一定可以強迫舒諾茲重視我!$b$b他沒理由在我發現了這個後還不讓我升職吧?', `MaleText_loc7`='¡Ha sido un día de lo más productivo!$b$bEfectivamente, la cámara es de origen antiguo y contiene un mecanismo magnífico que parece estar averiado.$b$bMañana investigaré más.$b$b¡Este descubrimiento debería bastar para que Schnottz se dé cuenta de que existo!$b$b¿Cómo podría negarme un ascenso después de esto?' WHERE `ID`=45959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 성각문양을 해독하려 씨름하느라 하루 온종일을 보냈다.$b$b$b   푸른 눈을 통해 별빛은$b              드러난다.$b$b   열 개의 파편과 하나의 막대, 그리고 장막을$b             사라진다.$b$b$b슈노츠가 한 허무맹랑한 약속은 잊어버리자!$b$b이 수수께끼를 풀 수만 있다면, 이 유적의 비밀은 모두 내 것이 된다!', `MaleText_loc4`='我花了一整天的时间去研究这些秘密符号：$b$b$b通过湛蓝的双眼星光$b在闪现。$b$b十块碎片一根棒，纱幕$b消失不见。$b$b$b忘了Schnottz和他那些虚无的承诺吧！$b$b要是我能破解这些密语，其中所包含的秘密就是我的！', `MaleText_loc5`='我花了一整天的時間在解讀這些象形文字:$b$b$b   藍色之眼中所見星光$b              出現。$b$b   十個碎片，一支節杖和迷霧$b消失。$b$b$b忘了舒諾茲的空洞承諾!$b$b只要我能解開這個謎語，一切的秘密都將屬於我!', `MaleText_loc7`='Me he peleado todo el día para obtener las cifras de esos jeroglíficos:$b$b$bA través del azul de los ojos se revela la luz de las estrellas.$b$b   Diez fragmentos, una vara y el velo$b             desaparece.$b$b$b¡Olvida a Schnottz y sus promesas vacías!$b$bSi consigo descifrar este acertijo, ¡sus secretos serán míos!' WHERE `ID`=45960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고하십시오!', `MaleText_loc4`='报告！', `MaleText_loc5`='報告!', `MaleText_loc7`='¡Informa!' WHERE `ID`=45961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈다!$b$b방을 장식하고 있던 물건에서 빼낸 사파이어를 사용해서 고글을 만들었다. 고글을 쓰면 보이지 않던 것을 볼 수 있다... 아주 놀라운 광경이다!$b$b운이 좋다면, 다음번 이 일지를 쓸 때쯤 나는 엄청난 부자가 되어 있을 것이다!', `MaleText_loc4`='我成功了！$b$b利用从这座建筑物的装饰上取得的蓝宝石，我拼出一副眼镜。我能够通过它看到……无比神奇的东西！$b$b运气好的话，我在写下一篇日记的时候就会是一个富翁了！', `MaleText_loc5`='我做到了!$b$b使用了用來裝飾房間的藍寶石，我做出了一個護目鏡。透過它，我可以看到些東西...驚人的東西!$b$b如果運氣好，我下次的發現將會創造一個非常有錢的人!', `MaleText_loc7`='¡Lo he logrado!$b$bHe elaborado un par de gafas utilizando los zafiros de los ornamentos de la cámara. Con ellas puedo ver cosas... ¡cosas maravillosas!$b$bCon un poco de suerte, ¡la próxima visita me hará rico!' WHERE `ID`=45962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 살펴보니, 이 사람은 죽은 지 몇 시간 정도밖에 지나지 않은 것 같습니다.', `MaleText_loc4`='经过一番快速的查看，你确定这个人刚刚死了几个小时。', `MaleText_loc5`='初步檢查後，你估計這個傢伙是在最近幾個小時當中死去的。', `MaleText_loc7`='Tras un análisis rápido, llegas a la conclusión de que esta persona ha muerto hace unas horas.' WHERE `ID`=45963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이... 너무 많습니다!', `MaleText_loc4`='他们……太多了！', `MaleText_loc5`='他們...數量太多了!', `MaleText_loc7`='¡Había... demasiados!', `FemaleText_loc1`='적이... 너무 많습니다!', `FemaleText_loc4`='他们……太多了！', `FemaleText_loc5`='他們...數量太多了!', `FemaleText_loc7`='¡Había... demasiados!' WHERE `ID`=45964;
