UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 인간 친구들을 낙하지점에 데려다 줍시다.', `MaleText_loc4`='让我们把这些人类送到降落点去。', `MaleText_loc5`='讓我們帶這些人類到空降點。', `MaleText_loc7`='Llevemos a estos humanos al punto de despliegue.', `FemaleText_loc1`='자, 인간 친구들을 낙하지점에 데려다 주지요.', `FemaleText_loc4`='让我们把这些人类送到降落点去。', `FemaleText_loc5`='讓我們帶這些人類到空降點。', `FemaleText_loc7`='Llevemos a estos humanos al punto de despliegue.' WHERE `ID`=45969;
