UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 잡으십시오. 좀 흔들릴 겁니다!', `MaleText_loc4`='抓紧。颠簸会非常剧烈！', `MaleText_loc5`='抓緊啦，會晃得很厲害!', `MaleText_loc7`='Agarraos bien. ¡Va a ser un viaje movido!', `FemaleText_loc1`='꽉 잡으세요. 좀 흔들릴 겁니다!', `FemaleText_loc4`='抓紧。颠簸会非常剧烈！', `FemaleText_loc5`='抓緊啦，會晃得很厲害!', `FemaleText_loc7`='Agarraos bien. ¡Va a ser un viaje movido!' WHERE `ID`=45971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나만 확실히 합시다... 우리는 당신네 운전수가 아닙니다!', `MaleText_loc4`='我要向你说明白……我们不是在为你们提供出租车服务！', `MaleText_loc5`='我要把話講清楚...我們可不是你的計程車!', `MaleText_loc7`='Que quede clara una cosa... ¡No somos su taxi!', `FemaleText_loc1`='하나만 확실히 하죠... 우리는 당신네 운전수가 아니에요!', `FemaleText_loc4`='我要向你说明白……我们不是在为你们提供出租车服务！', `FemaleText_loc5`='我要把話講清楚...我們可不是你的計程車!', `FemaleText_loc7`='Que quede clara una cosa... ¡No somos su taxi!' WHERE `ID`=45973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 사람들은 세상이 불타는 모습을 그저 바라보고만 싶어 하지. 또 어떤 사람들은 세상을 불태우는 사람이 되고 싶어 하지.', `MaleText_loc4`='有些人只想看着这个世界燃烧。而另一些人更要亲手把它点燃……', `MaleText_loc5`='有些只想見到世界起火燃燒，也些人則希望成為點火的那個人...', `MaleText_loc7`='Algunas personas solo quieren ver arder al mundo... Otras quieren ser las responsables de prenderle fuego.' WHERE `ID`=45974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불을 통해 우리는 이 세상의 불순한 존재들을 제거한다.', `MaleText_loc4`='通过熊熊烈火，我们净化了这片大地上的杂质。', `MaleText_loc5`='我們用火淨化這片土地上的所有污穢。', `MaleText_loc7`='Mediante el fuego purgamos las impurezas de esta tierra.' WHERE `ID`=45975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿더미로 돌아가라... 곧 길니아스도 더러운 늑대인간의 흔적도 사라지리라.', `MaleText_loc4`='一切化为灰烬……用不了多久，吉尔尼斯和狼人的污染都将不复存在。', `MaleText_loc5`='化為灰燼...不久之後，吉爾尼斯和狼人的詛咒都將化為一空。', `MaleText_loc7`='Reducida a cenizas... Pronto no quedará nada de Gilneas ni de la mácula de los huargen.' WHERE `ID`=45976;
