UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 수를 써서든, 초갈이 끔찍한 무기를 만들지 못하게 막아야 하오. 우리 자신을 희생해서라도.', `MaleText_loc4`='我们要不惜一切代价，阻止古加尔制造出他的终极武器，就算这意味着我们要牺牲自己的生命。', `MaleText_loc5`='我們務必不計任何代價阻止丘加利創造出他的終極武器，縱使必須犧牲我們的生命也無所謂。', `MaleText_loc7`='Debemos impedir que Cho''gall cree su arma definitiva, cueste lo que cueste, aunque tengamos que sacrificar nuestras vidas.' WHERE `ID`=45982;
