UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가는 살 좀 빼야 할 것 같은데, 친구.', `MaleText_loc4`='有人需要减重了，朋友。', `MaleText_loc5`='有人該減個肥啦，老兄。', `MaleText_loc7`='Sé de alguien que tiene que perder peso, colega.', `FemaleText_loc1`='누군가는 살 좀 빼야 할 것 같은데요, 친구.', `FemaleText_loc4`='有人需要减重了，朋友。', `FemaleText_loc5`='有人該減個肥啦，老兄。', `FemaleText_loc7`='Sé de alguien que tiene que perder peso, colega.' WHERE `ID`=45995;
