UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암살자는 무슨. 놈들에게 폭탄을 퍼부어야지!', `MaleText_loc4`='刺客？我们只需要在他们头顶上丢几颗火焰炸弹！', `MaleText_loc5`='刺客?我們該幹的，就是在他們的頭上丟幾顆炸彈!', `MaleText_loc7`='¿Asesinos? ¡Lo que tenemos que lanza''les son bombas!', `FemaleText_loc1`='암살자는 무슨. 놈들에게 폭탄을 퍼부어야죠!', `FemaleText_loc4`='刺客？我们只需要在他们头顶上丢几颗火焰炸弹！', `FemaleText_loc5`='刺客?我們該幹的，就是在他們的頭上丟幾顆炸彈!', `FemaleText_loc7`='¿Asesinos? ¡Lo que tenemos que lanza''les son bombas!' WHERE `ID`=45997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리가 운전수 노릇을 해야 하지? 알아서 거기 잠입할 순 없는 건가, 친구?', `MaleText_loc4`='我们为什么要提供出租车服务？难道你不能偷偷溜到那里去吗，朋友？', `MaleText_loc5`='老兄，幹嘛要我們載你?你就不能自己溜進去嗎?', `MaleText_loc7`='¿Por qué tenemos que hacer de taxi''tas? ¿No puedes e''cabullirte sin más, colega?', `FemaleText_loc1`='왜 우리가 운전수 노릇을 해야 하지요? 알아서 거기 잠입할 순 없는 건가요, 친구?', `FemaleText_loc4`='我们为什么要提供出租车服务？难道你不能偷偷溜到那里去吗，朋友？', `FemaleText_loc5`='老兄，幹嘛要我們載你?你就不能自己溜進去嗎?', `FemaleText_loc7`='¿Por qué tenemos que hacer de taxi''tas? ¿No puedes e''cabullirte sin más, colega?' WHERE `ID`=45998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 도착했군. 우린 여길 빠져나가겠네, 친구!', `MaleText_loc4`='好啦，好啦。我们离开这里，朋友！', `MaleText_loc5`='好的，我們要離開這裡啦，老兄!', `MaleText_loc7`='Bueno. ¡Nos vamos, colega!', `FemaleText_loc1`='좋아요, 도착했군요. 우린 여길 빠져나가겠습니다, 친구!', `FemaleText_loc4`='好啦，好啦。我们离开这里，朋友！', `FemaleText_loc5`='好的，我們要離開這裡啦，老兄!', `FemaleText_loc7`='Bueno. ¡Nos vamos, colega!' WHERE `ID`=45999;
