UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 돌아와서 일을 마칠 수 있도록 거인 놈들을 처치해 주게, 친구!', `MaleText_loc4`='你要消灭那些双头魔，这样我们才能回来完成工作，朋友！', `MaleText_loc5`='老兄，你去幹掉雙頭巨人，讓我們回來把事情辦完!', `MaleText_loc7`='¡Mata a esos ettins para que po''amos te''minar el trabajo, colega!', `FemaleText_loc1`='우리가 돌아와서 일을 마칠 수 있도록 거인 놈들을 처치해 주세요, 친구!', `FemaleText_loc4`='你要消灭那些双头魔，这样我们才能回来完成工作，朋友！', `FemaleText_loc5`='老兄，你去幹掉雙頭巨人，讓我們回來把事情辦完!', `FemaleText_loc7`='¡Mata a esos ettins para que po''amos te''minar el trabajo, colega!' WHERE `ID`=46001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박살의 땅에서 다시 보지.', `MaleText_loc4`='我们粉碎者据点见。', `MaleText_loc5`='回碎擊之地見啦。', `MaleText_loc7`='No'' vemos en Machacolpe.', `FemaleText_loc1`='박살의 땅에서 다시 보지요.', `FemaleText_loc4`='我们粉碎者据点见。', `FemaleText_loc5`='回碎擊之地見啦。', `FemaleText_loc7`='No'' vemos en Machacolpe.' WHERE `ID`=46002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에서 하늘을 누비며 적 머리 위에 폭탄을 꽝꽝 떨어뜨리는 것만큼 기분 좋은 일도 없지!$B$B아, 100킬로그램짜리 오크를 적의 머리 위에 떨어뜨리는 건 빼고 말이야. 안 그런가, 친구?', `MaleText_loc4`='没有任何事情能比飞到敌人头顶上，向他们“轰隆轰隆”地扔炸弹更痛快的了！$B$B把两百五十磅的兽人扔到敌人头顶上也不错。对不对，朋友？', `MaleText_loc5`='沒有比丟個轟轟炸彈在敵人頭上更爽的事啦!$B$B再不然，就是丟個兩百磅重的獸人下去，你說對吧，老兄?', `MaleText_loc7`='¡No hay na''a mejor que sobrevolar los enemigos y lanza''les bombas e''plosivas!$b$bO eso o dejar caer o''cos de ciento veinte kilos sobre sus cabezas, ¿eh, colega?' WHERE `ID`=46003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존존, 당신의 와이번 편대를 이끌고 코르크론 암살자들을 낙하지점까지 호위해 주려고 왔습니다.', `MaleText_loc4`='乔乔，我到这里来是为了领导你的双足飞龙小队，空降库卡隆刺客。', `MaleText_loc5`='喬喬，我是來帶領你的雙足飛龍小隊，還有載送柯爾克隆刺客的。', `MaleText_loc7`='Jon-Jon, he venido para liderar el escuadrón de jinetes del viento y desplegar a los asesinos Kor''kron.', `FemaleText_loc1`='존존, 당신의 와이번 편대를 이끌고 코르크론 암살자들을 낙하지점까지 호위해 주려고 왔어요.', `FemaleText_loc4`='乔乔，我到这里来是为了领导你的双足飞龙小队，空降库卡隆刺客。', `FemaleText_loc5`='喬喬，我是來帶領你的雙足飛龍小隊，還有載送柯爾克隆刺客的。', `FemaleText_loc7`='Jon-Jon, he venido para liderar el escuadrón de jinetes del viento y desplegar a los asesinos Kor''kron.' WHERE `ID`=46004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치유 물약을 마시겠습니다! 당분간은 다른 물약을 마실 수 없을 거예요!', `FemaleText_loc4`='我刚喝下一瓶治疗药水！暂时无法再使用药水了！', `FemaleText_loc5`='喝下醫療藥水!我得等上一陣子才能再喝一罐!', `FemaleText_loc7`='¡Estoy bebiendo una poción de sanación! ¡No podré utilizar otra hasta dentro de un rato!' WHERE `ID`=46005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 진작 얘기하지 그랬나? 황혼의 망치단 놈들에게 몇 방 먹여주고 돌아오거든 나랑 잔치를 벌이자고!$B$B나는 해변에 있는 작고 사랑스러운 오두막에서 우리 마나님이랑 오순도순 살고 있다네. 일 끝나면 들르게!', `MaleText_loc4`='嘿，你干嘛不早说？教训教训那群暮光之锤，回来之后我们好好庆祝一下！$B$B我跟我的夫人在海滩上筑了个温馨的小窝。记得来串门！', `MaleText_loc5`='嘿，你怎麼不這樣講咧?給暮光之錘的傢伙一點厲害瞧瞧，然後再回來跟我們一起慶祝!$B$B我跟我太太在海邊那裡有個不錯的小地方，記得要來啊!', `MaleText_loc7`='Hey, ¿por qué no lo dices y ya eh''tá? Les presentas a esos Crepusculares a tus dos amigos, los puños, ¡y luego te vienes aquí y nos vamos de fieh''ta!$B$BMi señora y yo nos hemos hecho con un lugar entrañable y acoge''or en la playa. ¡Pásate!' WHERE `ID`=46006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주 실바나스 님께서 잴라, 그리고 용아귀 부족과 호드 사이의 연락을 총괄하라고 내게 직접 지시를 내리셨네. 추측건대 실바나스 님과 새 대족장 가로쉬는 둘 사이에 생긴 골을 메우려고 애쓰는 것 같네.$B$B어쨌든, 우리를 위협하는 황혼의 망치단을 완벽하게 끝장내야 하네. 가장 중요한 건 초갈이 궁극의 무기를 만들지 못하게 막는 것이지.', `FemaleText_loc4`='风行者女王亲自派我来，作为部落的使者与扎伊拉和龙喉氏族联系。女王和那位新酋长加尔鲁什正在试图修复他们的关系。$B$B不管怎样，我们必须彻底结束暮光的威胁。而最重要的是，我们必须阻止古加尔制造出他的终极武器。', `FemaleText_loc5`='風行者女王親自指派我為部落使者，來和札伊拉與龍喉氏族聯繫。看來，她正在努力和新任的大酋長卡爾洛斯重修舊好。$B$B但是不管怎樣，我們務必得徹底終結這暮光之錘的威脅。更重要的是，我們一定要阻止丘加利創造出他的終極武器。', `FemaleText_loc7`='Lady Brisaveloz en persona me ha enviado para hacer de enlace de la Horda con Zaela y el clan Faucedraco. Parece que el nuevo Jefe de Guerra, Garrosh, y ella están intentando restaurar las relaciones.$b$bEn cualquier caso, debemos poner fin a la amenaza Crepuscular de una vez por todas. Pero lo más importante es impedir que Cho''gall cree su arma definitiva.' WHERE `ID`=46007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유 물약을 마시겠습니다! 당분간은 다른 물약을 마실 수 없을 거예요!', `MaleText_loc4`='我刚喝下一瓶治疗药水！暂时无法再使用药水了！', `MaleText_loc5`='喝下醫療藥水!我得等上一陣子才能再喝一罐!', `MaleText_loc7`='¡Estoy bebiendo una poción de sanación! ¡No podré utilizar otra hasta dentro de un rato!' WHERE `ID`=46008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\ability_warrior_charge.blp:20|t장군 움브리스가 |cFFFF0000$n|r|1을;를; 보고 |cFFFF0000|Hspell:74670|h[대공세]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t乌比斯将军注视着|cFFFF0000$n|r开始施放|cFFFF0000|Hspell:74670|h[迅猛突袭]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t昂布里斯將軍的視線停留在|cFFFF0000$n|r身上，並且開始施展|cFFFF0000|Hspell:74670|h[閃擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_charge.blp:20|t¡El general Umbriss fija la mirada |cFFFF0000$n|r y comienza a lanzar |cFFFF0000|Hspell:74670|h[Ataque relámpago]|h|r!' WHERE `ID`=46009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_shieldreflection.blp:20|t오즈룩이 |cFFFF0000|Hspell:78939|h[엘레멘티움 보루방패]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_shieldreflection.blp:20|t欧泽鲁克开始施放|cFFFF0000|Hspell:78939|h[源质壁垒]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_shieldreflection.blp:20|t 歐茲魯克施放了|cFFFF0000|Hspell:78939|h[源質壁壘]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_shieldreflection.blp:20|t¡Ozruk lanza |cFFFF0000|Hspell:78939|h[Baluarte de elementium]|h|r!' WHERE `ID`=46010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 자네가 와줘서 기쁘군, $n. 얘기할 게 많네.', `MaleText_loc4`='太好了！真高兴你在这里，$n。我们有许多事要谈。', `MaleText_loc5`='好極了!我很高興你到這兒來了，$n，有很多事情得跟你討論討論。', `MaleText_loc7`='¡Bien! Me alegro de que estés aquí, $n. Tenemos mucho de lo que hablar.' WHERE `ID`=46011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 말하지 않았나, 카시우스. $n|1은;는; 믿을 수 있다고 말이야.', `MaleText_loc4`='看，卡修斯，我早就和你说过，我们可以指望$n。', `MaleText_loc5`='看吧，卡蘇斯。我就跟你說了，$n是我們可以仰賴的人。', `MaleText_loc7`='¿Ves, Cassius? Te dije que podíamos contar con $n.' WHERE `ID`=46012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 와일드해머는 자부심 높은 부족이지. 자네도 얼라이언스에 대해 그런 자부심을 품고 있겠지, $n?', `MaleText_loc4`='我们蛮锤是一个光荣的部族。相信你在联盟中一定也有同样的光荣，$n。', `MaleText_loc5`='我們蠻錘可是非常自豪的。我相信你們應該也同樣以聯盟為傲吧，$n?', `MaleText_loc7`='Los Martillo Salvaje somos gente orgullosa. ¿Confío en que tengas el mismo orgullo por la Alianza, $n?' WHERE `ID`=46013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n|1이;가; 왔군! 전투는 어찌 되어 가나?', `MaleText_loc4`='我的$g男孩:女孩;回来了！$n，战况如何？', `MaleText_loc5`='好傢伙!戰鬥進行得怎麼樣啦，$n?', `MaleText_loc7`='¡$gEse:Esa; es mi $gchico:chica;! ¿Cómo va la lucha, $n?' WHERE `ID`=46014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나 반갑군, $n. 자네와 함께 싸울 날이 다시 오기를 고대하고 있다네.', `FemaleText_loc4`='真高兴又看到你了，$n。期待我们能再次并肩作战。', `FemaleText_loc5`='很高興再見到你，$n。我很期待再次和你一同並肩作戰。', `FemaleText_loc7`='Me alegro de volver a verte, $n. Estoy impaciente por volver a luchar a tu lado.' WHERE `ID`=46015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 망치단 놈들은 오래 버티지 못할 걸세. 용아귀 부족은 이때를 오랫동안 기다려 왔다네, $n.', `FemaleText_loc4`='那些暮光渣滓坚持不了多久了。龙喉氏族为此已经等待了太长的时间，$n。', `FemaleText_loc5`='這些暮光雜碎就快撐不住了。這一刻我們龍喉氏族已經等了很久，$n。', `FemaleText_loc7`='Esa escoria Crepuscular no podrá resistir más tiempo. El clan Faucedraco ha esperado mucho para esto, $n.' WHERE `ID`=46016;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 얘기했었지, 코즈윈. $n|1은;는; 믿음직하다네.', `FemaleText_loc4`='看，柯丝温，我早就和你说过，我们可以依靠$n。', `FemaleText_loc5`='看吧，寇茲文。我就跟你說了，$n是我們可以仰賴的人。', `FemaleText_loc7`='¿Ves, Cozwynn? Te dije que podíamos confiar en $n.' WHERE `ID`=46017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용아귀 부족은 당당히 호드와 함께하고 있네. 황혼 성채는 쓰러질 걸세, $n!', `FemaleText_loc4`='龙喉氏族与部落并肩作战，这是我们共同的荣耀。暮光堡垒一定会被攻陷，$n！', `FemaleText_loc5`='龍喉氏族很榮幸能和部落並肩作戰。暮光城塞必將陷落，$n!', `FemaleText_loc7`='Los Faucedraco pertenecen a la Horda con orgullo. ¡La Ciudadela Crepuscular caerá, $n!' WHERE `ID`=46018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불의 군주께서 반드시 이 아제로스에 종말을 가져올 것이다! 너희는 그분의 분노에 불타 버릴 것이다, 바보 같은 놈들!', `FemaleText_loc4`='炎魔之王终将为艾泽拉斯带来末日！你们将成为他怒火中的灰烬，蠢货！', `FemaleText_loc5`='終於，炎魔就要毀滅艾澤拉斯了!笨蛋，你們都將被他的怒火燒盡!', `FemaleText_loc7`='¡El Señor del Fuego propiciará por fin el final de Azeroth! ¡Arderéis con su furia, insensatos!' WHERE `ID`=46019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 어지럽군. 지금 이... 상태에 잘 적응하지 못하는 건가.', `MaleText_loc4`='我觉得有些混乱。我并不习惯这种……情况。', `MaleText_loc5`='我覺得有點不安。我實在不放心這樣的...狀況。', `MaleText_loc7`='Me siento algo descoyuntado. No me estoy adaptando bien a esta... condición.' WHERE `ID`=46020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤리? 나도 놈을 잘 알지. 그 저주가 이 땅에 휘몰아치기 전에는 그저 한 마리 보잘것없는 범죄자에 불과했어. 이제 위대한 늑대인간의 영웅이라고? 구역질 나는군...', `MaleText_loc4`='克罗雷？我认识他。在我们的国土遭受诅咒之前，他只不过是一名罪犯。而现在，他成为了伟大的狼人英雄？真令人作呕……', `MaleText_loc5`='克羅雷?我知道這個人。在我們這片土地被詛咒感染之前，他不過是個犯人罷了。現在他變成了偉大的狼人英雄?真詭異...', `MaleText_loc7`='¿Crowley? Le conocía. No era más que un criminal antes de que la maldición se apoderara de nuestra tierra. ¿Ahora es un gran héroe huargen? Repugnante...' WHERE `ID`=46021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드팽? 길니아스를 처음 공격한 것이 바로 블러드팽의 늑대인간 부족이었지. 이 괴물과 그의 무리는 그 뒤로 벌써 여러 해 동안 이 땅을 공포에 떨게 했다.', `MaleText_loc4`='血牙？首先对吉尔尼斯发动攻击的正是血牙的狼人。那个怪物和他的爪牙们已经在这片土地上横行肆虐了许多年。', `MaleText_loc5`='血牙?在吉爾尼斯初次遭到攻擊的時候，帶頭的正是血牙的狼人。這隻怪物和他的狼群已經肆虐這片土地多年了。', `MaleText_loc7`='¿Colmillo de Sangre? Cuando comenzaron los ataques contra Gilneas, eran los huargen de Colmillo de Sangre los que componían la vanguardia. Ese monstruo y su manada llevan años aterrorizando estas tierras.' WHERE `ID`=46022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말만 따르면, 별문제 없이 이 전쟁을 끝낼 수 있을 것이다. 로데론에서는 늑대인간의 흔적도 찾아볼 수 없게 될 테고.', `MaleText_loc4`='按照我说的去做，这场战争将顺利结束。当然，我们不应该太在意死在洛丹伦的那些狼人。', `MaleText_loc5`='照我的話去做，這場戰爭就會毫無意外地結束。除非，你要把羅德隆每隻狼人的死也當成意外。', `MaleText_loc7`='Haced lo que os digo y esta guerra concluirá sin incidentes. A no ser que consideréis la muerte de todos los huargen de Lordaeron como un incidente.' WHERE `ID`=46023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 "왕"이 그렇게 우릴 배신하리라고는 꿈에도 생각지 않았다. 자신이 늑대인간이라는 사실을 감추고 우릴 지배하다니... 정말 역겹군...', `MaleText_loc4`='我做梦也没有想到过我们的“国王”会背叛我们。只要想到他在统治我们的时候已经秘密地变成了一个狼人，我就想呕吐……', `MaleText_loc5`='我連作夢都沒有想過，我們「國王」竟然會這樣子背叛我們。光想到他隱瞞自己是狼人的身分在統治我們...太可惡了...', `MaleText_loc7`='Nunca soñé que nuestro "rey" pudiera traicionarnos como lo ha hecho. Y pensar que era un huargen en secreto mientras nos gobernaba... Me pone enfermo.' WHERE `ID`=46024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"다 끝났네, 고드프리..." 내가 절벽에서 뛰어내리기 직전에 그가 한 말이었지. 끝나지 않았다, 그레이메인! 나는 다시 태어났다!', `MaleText_loc4`='“结束了，高弗雷……”这就是他在我跳下悬崖之前对我说的最后一句话。格雷迈恩，没有结束！我又活了！', `MaleText_loc5`='「結束了，高佛雷...」在我跳下懸崖前夕他這麼對我說。事情沒有結束，葛雷邁恩!我又活著了!', `MaleText_loc7`='"Es el fin, Godfrey...". Eso es lo que me dijo justo antes de que saltara por el acantilado. ¡NO ES EL FIN, CRINGRIS! ¡VIVO DE NUEVO!' WHERE `ID`=46025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 우리는 늑대인간을 죽인 후 불에 태웠다. 확실히 끝장을 내기 위해서 말이야.', `MaleText_loc4`='当我们杀死狼人的时候，总会把它们烧死，这样才能确保它们不会重新活过来。', `MaleText_loc5`='我們殺掉狼人之後習慣會把屍體燒掉，以確保他們真的死透了。', `MaleText_loc7`='Solíamos quemar a los huargen tras matarlos... Para asegurarnos de que estaban muertos.' WHERE `ID`=46026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스는 신기루였다. 미래를 볼 수 있는 힘을 지닌 진정한 왕이라면 그 꿈을 이룰 수 있었겠지만... 그레이메인? 절대로 불가능하지...', `MaleText_loc4`='吉尔尼斯已经变成了一个不可能实现的梦。只有真正有眼光的人才能看清这一点……而格雷迈恩？绝不可能……', `MaleText_loc5`='吉爾尼斯是個不可能實現的夢。唯有真正有宏大願景的人才有辦法...至於葛雷邁恩?絕不可能...', `MaleText_loc7`='Gilneas fue un sueño imposible. Solo un hombre con verdadera visión podría haberlo llevado a cabo. ¿Pero Cringris? Jamás...' WHERE `ID`=46027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애쉬버리, 제발 뭐라도 좀 입게. 다리뼈가 다 튀어나왔잖은가.', `MaleText_loc4`='天哪，灰葬，看看你自己。你的腿骨都突出来了。', `MaleText_loc5`='艾胥柏利，拜託你遮一下好不好。你的腿骨都露出來了。', `MaleText_loc7`='Por lo que más quieras, Ashbury, cúbrete. Se te salen los huesos de las piernas.' WHERE `ID`=46028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 저주받은 고통은 내가 원했던 것이 아니오, 고드프리. "선물"이었다고. 기억하시나? 자, 이 "선물"이나 고맙게 즐기고 그냥 닥쳐주시오.', `MaleText_loc4`='我可不会让这种小麻烦来困扰我自己，高弗雷。记得么？这是一份“礼物”。现在，好好享受这份“礼物”，闭上嘴吧。', `MaleText_loc5`='這個痛苦的折磨可不是我自己要來的，高佛雷。它是個「恩賜」，你忘了嗎?好了，閉上嘴巴，乖乖享用這個「恩賜」吧。', `MaleText_loc7`='Yo no me he buscado esta endemoniada enfermedad, Godfrey. Fue un "don", ¿te acuerdas? Así que disfruta de mi "don" y cállate.' WHERE `ID`=46029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 빌어먹을 시체를 불태웠어야 했다.', `MaleText_loc4`='他们应该已经烧掉了我该死的尸体。', `MaleText_loc5`='他們應該要燒掉我的屍體才對。', `MaleText_loc7`='Deberían haber quemado mi maldito cadáver.' WHERE `ID`=46030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰 신세가 된 데도 좋은 점은 있지. 어디 보자... 말 그대로 물속에서 살 수도 있겠지. 육신을 가진 필멸자들보다 정확히 233%% 더 오래 물속에 머물 수 있으니까. 그래, 233%%. 내가 확인해 봤네.', `MaleText_loc4`='作为被遗忘者，自然有其好处。让我想想……我能活在水下面。比起有血肉的凡人，我的潜水时间要长233%%。没错，233%%，很值得惊叹吧。', `MaleText_loc5`='身為被遺忘者也是有好處啦。我看看...簡直可以直接住在水底下了，我潛水的時間比其他有血肉的種族要多上233%%。嘿，233%%耶!', `MaleText_loc7`='Ser un Renegado tiene sus ventajas. Déjame pensar... Prácticamente puedo vivir bajo el agua. Puedo permanecer sumergido un 233%% más de tiempo que un mortal de carne y hueso. Sí, puedes contarlo, un 233%%.' WHERE `ID`=46031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그리고 이제 정신 제어에도 당하는 법이 없지. 난 뇌가 없으니까!', `MaleText_loc4`='哦，现在我还能轻松地摆脱意识控制效果——因为我根本没有脑子！！！', `MaleText_loc5`='哦，現在我還可以擺脫心靈控制的效果--因為我沒有腦袋!', `MaleText_loc7`='Ah, y ahora puedo anular los efectos de control mental... ¡PORQUE NO TENGO CEREBRO!' WHERE `ID`=46032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 가장 멋진 부분은, 이제 다른 인간의 달콤한 살 맛을 알았지. 썩어가는 인간의 시체를 먹으면 힘이 솟아나더군. 그래, 아주... 아주 맛있더군...', `MaleText_loc4`='也许，最好的一件事就是我开始渴望其他人形生物的血肉了。吃掉他们腐烂的尸体能够让我获得力量，而且那种东西非常好吃……', `MaleText_loc5`='而且最棒的是，我還會飢渴想要吃其他人形生物的肉。啃食他們腐爛的屍體可以讓我獲得力量。沒錯，真-好-吃...', `MaleText_loc7`='Y, lo que quizá sea lo mejor, ahora siento un apetito por la carne de otros humanoides. Comerme sus cadáveres en putrefacción me aporta energía. Sí, el canibalismo es DE-LI-CIO-SO...' WHERE `ID`=46033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두 고드프리의 잘못이야.', `MaleText_loc4`='毫无疑问，这是高弗雷的错。', `MaleText_loc5`='這絕對是高佛雷的錯。', `MaleText_loc7`='Esto es culpa de Godfrey. Seguro.' WHERE `ID`=46034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 은빛소나무 숲을 사랑했지. 하지만 리치 왕이 미친 스컬지 부대를 풀어놓아 이 땅을 구더기가 들끓는 거대한 시체밭으로 만들어 놓은 후론 그럴 수 없었어. 이제 이 숲을 보기만 해도 내 초록색 피가 끓어오르는군.', `MaleText_loc4`='我一直都很喜爱银松森林——直到巫妖王放出他的天灾大军，将这片土地变成了一个腐烂的巨大尸坑。现在，每当我再看到它，血管里的绿色血液也禁不住要沸腾。', `MaleText_loc5`='我一直都很喜歡銀松森林，直到巫妖王派出了他的天譴軍團，將這片地方變成一個巨大的曝屍場。如今看到它這個樣子就讓我的綠色血液為之沸騰啊。', `MaleText_loc7`='Siempre me gustó Argénteos... Hasta que el Rey Exánime desplegó sus ejércitos de la Plaga y convirtió la tierra en una fosa putrefacta y enorme. Ahora solo verlo hace que me hierva la sangre verde.' WHERE `ID`=46035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡소리는 집어치워. 징징대는 소리를 들을 기분은 아니니까.', `MaleText_loc4`='说话简略一些。我可没心情听什么抱怨和闲聊。', `MaleText_loc5`='廢話少說。我沒有心情聽你在這邊哀嚎抱怨。', `MaleText_loc7`='No te enrolles. No estoy de humor para lloros ni divagaciones.' WHERE `ID`=46036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신이 이상해지고 있네. 똑바로 생각할 수가 없어...', `MaleText_loc4`='我失去理智了。我没办法让精神集中起来……', `MaleText_loc5`='我快要失去理智了。思緒變得越來越亂...', `MaleText_loc7`='Estoy perdiendo la cabeza. No puedo pensar con claridad...' WHERE `ID`=46037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 남은 감정은 분노뿐이네.', `MaleText_loc4`='现在我的体内只剩下了愤怒。', `MaleText_loc5`='憤怒是我唯一剩下的感覺。', `MaleText_loc7`='La ira es la única emoción que me queda.' WHERE `ID`=46038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수는 우리 것이지!', `MaleText_loc4`='我们要报仇！', `MaleText_loc5`='我們終將復仇!', `MaleText_loc7`='¡La venganza será nuestra!' WHERE `ID`=46039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 포세이큰 이상의 존재... 인간 이상의 존재라네. 어딘가 새로운... 뭔가... 다른 존재.', `MaleText_loc4`='我不仅仅是被遗忘者……不仅仅是一个人……我是某种全新的，某种……不同的。', `MaleText_loc5`='我不僅是被遺忘者...不僅是人類...我是全新的...我是不一樣的存在實體。', `MaleText_loc7`='Soy más que un Renegado... Soy más que un hombre... Soy algo nuevo. Algo... diferente.' WHERE `ID`=46040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내, 내게 무슨 일이 일어난 거지? 당신들은 누구요?', `MaleText_loc4`='出……？出了什么事？你们是谁？', `MaleText_loc5`='什麼?我發生了什麼事情?你們是誰?', `MaleText_loc7`='¿Qué...? ¿Qué me ha pasado? ¿QUIÉNES SOIS?' WHERE `ID`=46041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요! 살려줘요! 괴물들에게 붙잡혔어요!', `MaleText_loc4`='救命！救命！我被怪物捉住了！', `MaleText_loc5`='救命啊!救命啊!我被怪物抓走了!', `MaleText_loc7`='¡SOCORRO! ¡SOCORRO! ¡Me han capturado unos monstruos!' WHERE `ID`=46042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 우릴 기억하지 못하나, 뎀프시? 난 고드프리다. 여기 월든 경과 애쉬버리 남작이 함께 있다. 우리가 널 "구해"줬는데, 이게 감사의 표현이라고 하는 건가?', `MaleText_loc4`='哈！你不认识我们了，德姆西？我是高弗雷。在我身边的是沃登和灰葬男爵。我们刚刚“救了”你，而你却连句感谢的话都没有？', `MaleText_loc5`='哈!你不認得我們了嗎，丹普瑟?是我，高佛雷。我已經抓到了瓦爾登領主和艾胥柏利男爵。我們「拯救」了你，而這就是你對我們的感謝?', `MaleText_loc7`='¡JA! ¿No nos reconoces, Dempsey? Soy Godfrey. Tengo a Lord Walden y al barón Ashbury conmigo. ¿Te hemos "salvado" y así nos lo agradeces?' WHERE `ID`=46043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자여, 도둑질은 금지되어 있다!', `MaleText_loc4`='入侵者，停止你的盗窃行为！', `MaleText_loc5`='不能容許你的偷竊行為，侵入者!', `MaleText_loc7`='¡Tu robo está prohibido!' WHERE `ID`=46044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 땅에 발을 들여놓은 자여! 정화될지어다!', `MaleText_loc4`='你正踏在神圣的土地上！而你必须被彻底净化！', `MaleText_loc5`='你踏上了神聖之地!務必得將你淨化!', `MaleText_loc7`='¡Pisas tierra sagrada! ¡Debemos purificarte!' WHERE `ID`=46045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 봉사를 맹세했다. 너도 이제 그렇게 될 것이다.', `MaleText_loc4`='我们已经立下效忠的誓言，入侵者。你也必须一样。', `MaleText_loc5`='入侵者，我們皆已宣誓效忠，你也該如此。', `MaleText_loc7`='Hemos jurado servir. Y tú también lo harás.' WHERE `ID`=46048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가... 네가 나를 구했다고? 이 저주받을 괴물! 넌 괴물이야! 네 모습을 봐!', `MaleText_loc4`='你……你救了我？我是个被诅咒的怪物！你也是个被诅咒的怪物！看看你自己吧！', `MaleText_loc5`='你...你救了我?我是一隻受詛咒的怪物!你是一支受詛咒的怪物!看看你自己!', `MaleText_loc7`='Me habéis... ¿salvado? ¡Soy un maldito monstruo! ¡TÚ ERES UN MALDITO MONSTRUO! ¡MÍRATE!' WHERE `ID`=46049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별빛을 눈에 담은 사람은 그 빛을 보호하는 데 영원을 바쳐야 한다!', `MaleText_loc4`='那些珍爱星光的人必须永远保护它！', `MaleText_loc5`='凡仰望星光者皆需永世守護它!', `MaleText_loc7`='¡Aquellos que contemplan la luz estelar deben protegerla para siempre!' WHERE `ID`=46050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 한때는 도둑이었지만, 이제 별의 하수인이 되었다.', `MaleText_loc4`='我曾经是一名盗贼，现在则是群星的仆人。', `MaleText_loc5`='我曾經也是盜賊，如今卻為星光的僕人。', `MaleText_loc7`='Antes era ladrón; ahora soy un sirviente de las estrellas.' WHERE `ID`=46051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑이여, 영원한 하수인이 된 것을 환영한다.', `MaleText_loc4`='欢迎你接受这份永恒的任务，盗贼。', `MaleText_loc5`='盜賊，我歡迎你加入永恆的僕役。', `MaleText_loc7`='Te doy la bienvenida a una eternidad de servicio.' WHERE `ID`=46052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 언제나 줏대 없는 겁쟁이였지, 뎀프시.', `MaleText_loc4`='你一直都是个没骨气的懦夫，德姆西。', `MaleText_loc5`='你本來就一直是個沒種的懦夫，丹普瑟。', `MaleText_loc7`='Siempre has sido un auténtico cobarde, Dempsey.' WHERE `ID`=46053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 여기가 아수라장이 되면 당신 스스로 뒷문을 열고 도망갈 수는 없습니다. 주점 단골들을 처치해서 경비병이 문을 열게 하거나, 병사 락노트가 술에 취해 난동을 피우게 하거나, 스패즈링이 혹시 열쇠를 가지고 있는지 알아보는 수밖에 없지요!', `FemaleText_loc4`='你在引发混乱之后，无法自行打开后门逃走。你可以选择的方案有：杀死酒吧客人，让卫兵打开后门；或者让罗克诺特下士喝醉，这样他会进行破坏；或者是看看普拉格的身上有没有钥匙！', `FemaleText_loc5`='一旦騷動開始之後，你就沒有辦法自己打開後門逃脫了。你只能殺掉酒吧客人讓守衛來開門、灌醉士兵羅克諾特讓他亂砸東西，或者是看看史帕齊林身上有沒有鑰匙!', `FemaleText_loc7`='¡No podrás abrir la puerta de atrás para escapar una vez hayas desatado el caos. ¡Tendrás que hacer que los guardias lo hagan por ti matando a los clientes del bar, emborrachar al soldado Sinroca para que cause daños en el local o averiguar si Aropatoso lleva la llave encima!' WHERE `ID`=46054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 돌아왔습니다. 그는 그림 바톨과 고원의 여러 지역을 손에 넣었지요. 데스윙을 막기엔 제가 너무 약하다는 자괴감이 들 정도입니다.$B$B곧 우리 여왕님께서 도착하실 겁니다. 그리고 우리는, 한때 대지의 수호자였던 그자를 물리칠 것입니다.', `MaleText_loc4`='死亡之翼回来了，他已经控制了格瑞姆巴托和这片高地的很大一部分。我已经无力阻止他了。$B$B我们的女王很快就会到来，我们将齐心协力，把那个曾经的大地守护者赶回他应在的位置上。', `MaleText_loc5`='死亡之翼又回來了。他奪下了格瑞姆巴托和大半塊的高地，而且我感覺根本無力阻止他。$B$B但不久之後我們龍后就會抵達，然後我們將一起協力將這位墮落的大地守護者埋回大地。', `MaleText_loc7`='Alamuerte ha regresado. Ha tomado Grim Batol y gran parte de las Tierras Altas, y me veo prácticamente impotente para detenerlo.$b$bPronto llegará nuestra reina, y juntos pondremos al antiguo Guardián de la Tierra en su sitio.' WHERE `ID`=46055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3...', `MaleText_loc4`='3……', `MaleText_loc5`='3...', `MaleText_loc7`='3...' WHERE `ID`=46056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2...', `MaleText_loc4`='2……', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=46057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1...', `MaleText_loc4`='1……', `MaleText_loc5`='1...', `MaleText_loc7`='1...' WHERE `ID`=46058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 일이지?!', `MaleText_loc4`='那是什么？！', `MaleText_loc5`='那是什麼?!', `MaleText_loc7`='¡¿QUÉ HA SIDO ESO?!' WHERE `ID`=46059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 온통 안개뿐인데!', `MaleText_loc4`='除了雾气之外，这里什么都没有！', `MaleText_loc5`='這兒除了霧以外什麼都沒有!', `MaleText_loc7`='¡AQUÍ NO HAY NADA MÁS QUE ESTA NIEBLA!' WHERE `ID`=46060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸워라! 내가 위로 올라가서 초갈 님에게 보고하겠다!', `MaleText_loc4`='继续战斗！我要到顶上去和古加尔谈谈！', `MaleText_loc5`='繼續作戰!我要去上面找丘加利講話!', `MaleText_loc7`='¡SIGAN LUCHANDO! ¡YO VOY A SUBIR A HABLAR CON CHO''GALL!' WHERE `ID`=46061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 오랫동안 검은무쇠 부족을 지켜보았습니다... 놈들을 몰아내고 제 땅을 되찾길 바라며, 계획하며, 꿈꾸면서요.$B$B검은바위 산은 놈들에게 줘버려도 됩니다. 화산이 다시 분출하여 놈들을 다 쓸어갔으면 좋겠어요. 제가 원하는 건 지금은 불타는 평원이라 불리는 지역입니다. 붉은마루 산맥에 있는 제 땅을 놈들의 대군주가 파괴해 버렸지요.$B$B$C님, 저는 제 땅에 남은 가능성을 만천하에 보여줄 것입니다. 놈들이 남긴 죽음과 협잡 위에, 평화와 정의가 넘치는 왕국을 건설할 것입니다. 저는 임무를 다했습니다. 이제 전 당연한 저의 권리를 되찾고자 싸우려고 여기 왔습니다.$B$B그것을 위해서라면 기꺼이 목숨을 내던질 것입니다.', `FemaleText_loc4`='我监视黑铁矮人已经有很长时间了……我谋划，期待，希望着能有机会驱逐他们，夺回我的家园。$B$B他们可以保留黑石山。我希望那座山会再次爆发，彻底毁灭他们。我想得到现在被称为燃烧平原的那个地方，那里本来是赤脊山脉中属于我的那一部分，却被他们的烈焰统治者摧毁了。$B$B$C，我要让全世界知道，我的国土上到底蕴含着怎样的力量。我会在他们留下的死亡与欺诈之上建立一个和平公正的王国。我的守望已经结束。现在我要奋勇作战，夺回应属于我的东西。$B$B为此，我将不惜牺牲自己的生命。', `FemaleText_loc5`='我對黑鐵矮人已經觀察了好長一段時間...默默在策劃，希望能有機會把他們趕走，奪回我的土地。$B$B黑石山就留給他們吧，我希望它會再度噴發把他們全都殺光。我想要奪回的是現在稱之為燃燒平原的地方，那裡原本是屬於我的赤脊山領土，但後來被他們的火焰主宰給毀掉了。$B$B$C，我要讓這個世界知道我在我的領土上所遺留的潛力，我要在他們所留下的死亡與詭計之上打造出一個和平與正義的王國。該結束觀望了，我要來奪回原本就屬於我的東西。$B$B就算會犧牲性命也在所不惜。', `FemaleText_loc7`='Llevo mucho tiempo observando a los Hierro Negro... Maquinando, esperando, deseando tener la oportunidad de expulsarlos y recuperar mi tierra.$b$bPueden quedarse con la Montaña Roca Negra. Espero que vuelva a entrar en erupción y se los lleve a todos. Quiero lo que ahora se llaman Las Estepas Ardientes, mi parte de las Montañas Crestagrana que destruyó su señor ígneo.$b$b$C, voy a enseñarle al mundo el potencial que aún le queda a mi tierra. Levantaré un reino de paz y justicia sobre la muerte y el engaño que dejan tras de sí. Mi vigilia ha terminado. He venido para luchar por lo que me pertenece por derecho.$b$bY estoy dispuesta a morir por ello.' WHERE `ID`=46062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암살자들! 모두 썰어버리겠다!', `MaleText_loc4`='刺客！我要把你们的牙齿都打出来！', `MaleText_loc5`='刺客!我要把你剁成碎肉!', `MaleText_loc7`='¡ASESINOS! ¡Os cortaré en rodajas!' WHERE `ID`=46063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 빚은 꼭 갚아 주겠다, 추악하고 더러운 마녀야!', `MaleText_loc4`='别想逃脱惩罚，你这个丑陋，恶心的巫婆！', `MaleText_loc5`='你絕對逃不掉的，你這個醜八怪臭巫婆!', `MaleText_loc7`='¡Nunca podrás salirte con la tuya en este asunto, bruja apestosa y horrorosa!' WHERE `ID`=46064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래? 어떻게 갚을 건데, 이 드워프 꼬맹이 녀석아? 여긴 널 구해줄 사람도 없어.', `MaleText_loc4`='哦，真的？你还能做些什么，矮人？这里可没有人能救你。', `MaleText_loc5`='哦，是嗎?那麼你到底要怎麼做呢，矮人?這兒可沒有人會來救你。', `MaleText_loc7`='¿Ah sí? ¿Y qué vas a hacer exactamente, enano? Aquí no hay nadie para salvarte.' WHERE `ID`=46065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지 않아, 밴시. 우리가 기드윈을 되찾으러 왔다.', `MaleText_loc4`='你错了，女妖。我们就是要带吉德文回去的。', `MaleText_loc5`='你錯了，女妖。我們是來帶基德溫回去的。', `MaleText_loc7`='Te equivocas, alma en pena. Hemos venido a rescatar a Gidwin.' WHERE `ID`=46066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 둘 뿐이냐? 상대도 안 되는 녀석들이...', `MaleText_loc4`='就你们两个？你们根本没有机会。', `MaleText_loc5`='就你們兩個?你們一點勝算也沒有。', `MaleText_loc7`='¿Solo ustedes dos? No tienen ninguna posibilidad.' WHERE `ID`=46067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 생각해 보시지.', `MaleText_loc4`='我可不敢苟同。', `MaleText_loc5`='我可不敢苟同。', `MaleText_loc7`='Lamento discrepar.' WHERE `ID`=46068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌격!', `MaleText_loc4`='冲啊！', `MaleText_loc5`='衝啊!', `MaleText_loc7`='¡A la carga!' WHERE `ID`=46069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 부족한테 군사 용어를 설명하기가 얼마나 어려운지 모른다고. 왜 있잖아, "전천후 사격"이라던가 "제압 사격" 같은 거.$B$B다행히 "사망자 집중 지역"에 대해서는 설명할 필요가 없더군... 그러니까... 알아서 잘 해치우더란 말이지.', `MaleText_loc4`='很难向龙喉兽人解释“火力覆盖”和“压制炮火”这样的概念。$B$B幸运的是，他们很清楚什么是“杀”和……嗯……“杀光”。', `MaleText_loc5`='很難跟龍喉氏族解釋何謂「射界」或「壓制火力」的觀念。$B$B還好，他們對於「殺傷區」倒是理解得很清楚，還有...呃，「殺戮」。', `MaleText_loc7`='Es difícil explicar a los Faucedraco conceptos como "campo de fuego" o "ráfaga disuasoria".$b$bAfortunadamente, cuentan con una sólida comprensión de "zonas a matar" y... eh... "asesinato".' WHERE `ID`=46070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 해변을 방어하는 데 필요한 지원군을 요청했소. 그랬더니 호드가 이 조그만 난쟁이들과 이들이 만든 자그마한 금속 기계를 보내 주더군.$B$B<무시하는 눈초리로 주변의 고블린들을 바라보는 그랄록>', `MaleText_loc4`='我请求援军来帮我们守住海滩。结果部落就派来了这群小不点儿和他们的小金属管。$B$B<格拉洛克不屑地看了看身边的地精。>', `MaleText_loc5`='我請求增派援軍協助我們守住這片海灘，結果部落竟然派了這些拿著小金屬管子的小個頭過來。$B$B<葛拉羅克不屑地看著旁邊的哥布林。>', `MaleText_loc7`='He pedido refuerzos para que nos ayuden a mantener la playa, y la Horda me envía a estos hombrecitos con sus tubos de metal.$b$b<Gralok observa a los goblins cercanos con desdén.>' WHERE `ID`=46071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디, 밴시 여왕이 보낸 암살자들인가?', `FemaleText_loc4`='女妖之王派遣了刺客？', `FemaleText_loc5`='所以，女妖之王已派出了刺客?', `FemaleText_loc7`='¿Así que la Reina alma en pena ha enviado asesinos?' WHERE `ID`=46072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르나, 옛 친구가 반갑지 않아?', `MaleText_loc4`='罗娜，这就是你向老朋友问候的方式？', `MaleText_loc5`='羅娜，這就是你接待老朋友的方式嗎?', `MaleText_loc7`='Lorna, ¿así es como saludas a los viejos amigos?' WHERE `ID`=46073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고드프리? 소문이 사실이었군.', `FemaleText_loc4`='高弗雷？那么，那些传闻是真的了？', `FemaleText_loc5`='高佛雷?原來謠言是真的。', `FemaleText_loc7`='¿Godfrey? Así que los rumores son ciertos.' WHERE `ID`=46074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원한 때문에 당신의 왕국을 배신하겠다는 건가?', `FemaleText_loc4`='你真的要背叛你的王国？', `FemaleText_loc5`='你竟然為了私人恩怨出賣國家?', `FemaleText_loc7`='¿Traicionas a tu reino solo por rencor?' WHERE `ID`=46075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 왕국이라고? 그따위 것은 이제 존재하지 않아.', `MaleText_loc4`='我的王国？我的王国已经不复存在了。', `MaleText_loc5`='國家?我的國家早就滅亡了。', `MaleText_loc7`='¿Mi reino? Mi reino ya no existe.' WHERE `ID`=46076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 아버지와 그레이메인이 모두 망쳐놓았지. 아니, 살인 괴물들이 자유롭게 풀려났을 때 길니아스는 사라지고 말았어. 영원히.', `MaleText_loc4`='这就是你的父亲和格雷迈恩所做的一切……不，当他们允许那些怪兽肆意作恶的时候，吉尔尼斯就已经死了。', `MaleText_loc5`='而且就是你父親和葛雷邁恩一手促成的...不，吉爾尼斯在他們默許那些兇殘的野獸隨意肆虐的時候就已經滅亡了。', `MaleText_loc7`='Tu padre y Cringris se encargaron de eso... No, Gilneas murió cuando ellos dejaron que las bestias asesinas camparan a su antojo. Libres.' WHERE `ID`=46077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 무기를 내려놓고 항복해라. 널 죽이러 온 건 아니니까. 아직은.', `MaleText_loc4`='现在，放下武器投降吧。我们来这里不是为了杀你。至少现在还不是。', `MaleText_loc5`='放下武器投降吧，我們不是來殺你的。至少目前還不是。', `MaleText_loc7`='Ahora deja las armas y ríndete. No he venido para matarte. Todavía...' WHERE `ID`=46078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하! 곱게 물러날 생각은 없다! 죽어라!', `FemaleText_loc4`='哈！那就先杀了我再说吧！去死吧！', `FemaleText_loc5`='哈!你得先殺了我!死吧!', `FemaleText_loc7`='¡JA! ¡Tendrás que matarme! ¡MUERE!' WHERE `ID`=46079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 의식을 잃습니다.', `FemaleText_loc4`='%s失去了知觉。', `FemaleText_loc5`='%s失去意識昏倒了。', `FemaleText_loc7`='%s pierde el conocimiento.' WHERE `ID`=46080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 여기가 아수라장이 되면 자네 스스로 뒷문을 열고 도망갈 수는 없네. 주점 단골들을 처치해서 경비병이 문을 열게 하거나, 병사 락노트가 술에 취해 난동을 피우게 하거나, 스패즈링이 혹시 열쇠를 가지고 있는지 알아보는 수밖에 없지!', `FemaleText_loc4`='你在引发混乱之后，无法自行打开后门逃走。你可以选择的方案有：杀死酒吧客人，让卫兵打开后门；或者让罗克诺特下士喝醉，这样他会进行破坏；或者是看看普拉格的身上有没有钥匙！', `FemaleText_loc5`='一旦騷動開始之後，你就沒有辦法自己打開後門逃脫了。你只能殺掉酒吧客人讓守衛來開門、灌醉士兵羅克諾特讓他亂砸東西，或者是看看史帕齊林身上有沒有鑰匙!', `FemaleText_loc7`='¡No podrás abrir la puerta de atrás para escapar una vez hayas desatado el caos. ¡Tendrás que hacer que los guardias lo hagan por ti matando a los clientes del bar, emborrachar al soldado Sinroca para que cause daños en el local o averiguar si Aropatoso lleva la llave encima!' WHERE `ID`=46081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 요새는 단단히 방어되고 있지만, 우리 적이 사방에서 다가오고 있네. 고원 안쪽으로 진군하기 전에 해변을 더 확실히 확보하는 게 좋을 것이야.', `FemaleText_loc4`='这座要塞相当坚固，但我们的敌人从四面八方攻击我们。我们必须先在海岸上站稳脚跟，才能向内陆挺进。', `FemaleText_loc5`='這座要塞雖然固若金湯，但是敵人卻從四面八方逐步逼近。我們最好能先鞏固好岸邊的陣地，然後再往內陸推進。', `FemaleText_loc7`='El fortín está fortificado, pero nuestros enemigos se acercan por todas partes. Lo más inteligente sería asegurarnos de controlar la costa antes de avanzar tierra adentro.' WHERE `ID`=46082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전선을 유지하라!', `MaleText_loc4`='守住阵线！', `MaleText_loc5`='堅守防線!', `MaleText_loc7`='¡Mantened el frente!' WHERE `ID`=46083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러! 발각되기 전에 포세이큰 전초지로 가야 한다!', `MaleText_loc4`='赶快！我们必须在被发现之前返回被遗忘者先锋军！', `MaleText_loc5`='動作快!我們得在形跡敗露之前趕回被遺忘者戰事前線!', `MaleText_loc7`='¡Rápido! ¡Tenemos que volver al Frente Renegado antes de que nos descubran!' WHERE `ID`=46084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅에서 온 정령이시여, 나를 당신의 분노로 채우소서!', `MaleText_loc4`='火焰之地的英灵，让你的愤怒充满我的身躯！', `MaleText_loc5`='火源之界的魂靈啊，將你的怒火灌注在我身上吧!', `MaleText_loc7`='¡Espíritus de las Tierras de Fuego llénenme con su ira!' WHERE `ID`=46085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 카르가스 블레이드피스트를 예전 모습, 자랑스러운 호드의 전사로서 기억할 거요. 그는 지금껏 살았던 가장 뛰어난 전사 중 하나였지. 심지어 얼라이언스도 이 사실을 알고 있소.$B$B우리는 그의 영광스러운 이름을 따서 카르가스 원정대란 이름을 지었소. 나는 그 이름에 어울리게 카르가스 원정대를 이끌 거요. 우리는 호드를 위해 검은무쇠 드워프를 몰아내고, 당연히 호드의 영토인 검은바위 산과 주변의 모든 지역을 점령할 것이오.$B$B당신은 타우릿산을 치는 대족장님의 날카로운 검이 되어야 하오. 이 명예로운 임무를 자랑스럽게 짊어지시오.', `MaleText_loc4`='我们将永远纪念卡加斯·刃拳，为了他曾经为部落所做的一切。他是有史以来最优秀的战士之一。即使是联盟也不能否认这一点。$B$B卡加斯远征军以他为名，也以他为荣。我们将在他的名义下，驱逐黑铁矮人，夺回黑石山以及其周围区域。这些都是应该属于部落的国土。$B$B你将成为酋长对抗索瑞森的有力武器。这也是属于你的巨大光荣。', `MaleText_loc5`='我們永遠都不會忘記卡加斯·刃拳，他是部落有史以來最傑出的戰士，即便是聯盟的人也不能否認這點。$B$B卡加斯遠征軍就是為了紀念他的榮耀戰績而取名的，而且我絕對不會讓他的名號蒙羞。我們會趕走黑鐵矮人，把黑石山和四周的地區全部搶下來，因為這本來就該是部落的。$B$B你將成為大酋長對抗索瑞森的武器，你應該自豪能獲得這份殊榮。', `MaleText_loc7`='Siempre recordaremos a Kargath Garrafilada por lo que significó para la Horda. Fue uno de los mejores guerreros que jamás ha habido, y hasta la Alianza lo reconoce.$b$bLa Fuerza Expedicionaria de Kargath se llama así en su honor y tengo la intención de estar a la altura del nombre. Expulsaremos a los enanos Hierro Negro y tomaremos la Montaña Roca Negra y todas las zonas colindantes para la Horda, a la que pertenecen legítimamente.$b$bSerás la espada del Jefe de Guerra contra Thaurissan. Acepta el honor con orgullo.' WHERE `ID`=46086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘담의 정령이시여... 제 부름에 응하소서!', `MaleText_loc4`='天空之牆的英灵，听从我的召唤！', `MaleText_loc5`='天空之牆的魂靈啊，聽我號令!', `MaleText_loc7`='¡Espíritus del Muro Celeste, escuchad mi llamada!' WHERE `ID`=46087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심원의 영지에서 온 정령이여, 당신의 힘을 주소서!', `MaleText_loc4`='深岩之洲的英灵，给予我你的力量！', `MaleText_loc5`='地深之源的魂靈啊，賜予我你們的力量!', `MaleText_loc7`='¡Espíritus de Infralar denme su fuerza!' WHERE `ID`=46088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 잘 돌아왔어요. 이제 한 시름 놓게 됐네요.$b$b당신도 함께 돌아오셨다니, 정말 기쁘네요! 저희와 함께 가시겠어요?', `FemaleText_loc4`='看样子，他们已经找到了回家的路。我终于放心了。$b$b你也回来了！有兴趣加入我们吗？', `FemaleText_loc5`='看來他們已經找到了回家的路，真讓我鬆了一口氣。$b$b你也回來吧!有興趣加入我們嗎?', `FemaleText_loc7`='Parece que han encontrado el camino de vuelta a casa. Qué alivio.$b$b¡Y tú también has vuelto! ¿Te interesa unirte a nosotros?' WHERE `ID`=46089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아 참, 저희 마차 안에 있는 물건은 언제든 빌려 가셔도 괜찮아요... 다 쓰신 뒤에 돌려주시기만 하면요!', `FemaleText_loc4`='顺便说一句，马车里的物资随你使用……只要你在用完之后把它们拿回来！', `FemaleText_loc5`='對了，歡迎你借用在商隊裡找到的任何補給品...只要你事情辦完之後能把它們帶回來!', `FemaleText_loc7`='Por cierto, si quieres puedes tomar prestado cualquier suministro que encuentres dentro de la caravana... ¡Siempre y cuando lo devuelvas cuando hayas terminado!' WHERE `ID`=46090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가 희망의 빛 예배당에 상점을 내고 싶어요. 저는 비록 전사는 아니지만, 나름대로 예배당에 도움을 줄 수 있는 방법이 있겠죠.', `FemaleText_loc4`='我希望能有一天，在圣光之愿礼拜堂建起一座商店。我对战斗不在行，但这并不意味着我就不能帮上任何忙。', `FemaleText_loc5`='將來我想在聖光之願禮拜堂開一家店。雖然我不是什麼厲害的戰士，但那可不表示我無法為理念貢獻一己之力。', `FemaleText_loc7`='Algún día me gustaría establecerme en la Capilla de la Esperanza de la Luz. No soy buena luchadora, pero eso no quiere decir que no pueda contribuir a la causa.' WHERE `ID`=46091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 친구들과 여행한 지는 얼마 되지 않았지만, 벌써 둘 중 하나라도 없으면 여행길이 어떨지 상상할 수도 없네요.', `FemaleText_loc4`='那些男孩和我只是一同旅行了很短一段时间，但我已经无法想象没有他们相伴的生活了。', `FemaleText_loc5`='雖然孩子們只跟我一起旅行了一小段時間，我已經無法想像如果少了他們任何一個人我的日子得怎樣過下去。', `FemaleText_loc7`='Hace poco que los chicos y yo viajamos juntos, pero ya me cuesta imaginar la vida sin cualquiera de ellos.' WHERE `ID`=46092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마차 안의 어떤 물건이든 마음 놓고 사용하세요. 우리가 쓰는 물건만 아니라면 언제든 빌려 가셔도 좋아요.', `FemaleText_loc4`='希望你随意使用我的马车里的物品。只要不是我们正在使用的物品，你都可以借走。', `FemaleText_loc5`='希望你已經有好好善加利用我商隊裡面的東西了，既然我們沒有在用，不如就借給你用吧。', `FemaleText_loc7`='Espero que estés usando los objetos de la caravana. Si no los estamos utilizando nosotros, puedes tomarlos prestados.' WHERE `ID`=46093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딜 저렇게 뛰어가는 거죠?!', `FemaleText_loc4`='为什么他会那样逃走？！', `FemaleText_loc5`='他幹嘛要那樣子跑掉?!', `FemaleText_loc7`='¡¿Por qué se ha ido así como así?!' WHERE `ID`=46094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그를 찾아주겠다고 약속해 주세요, $n 님.', `FemaleText_loc4`='向我保证，你一定会找到他，$n。', `FemaleText_loc5`='答應我，你一定會找到他，$n。', `FemaleText_loc7`='Prométeme que lo encontrarás, $n.' WHERE `ID`=46095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<걱정하고 있는 피오나. 대화할 기분이 아닌 것처럼 보입니다.>', `FemaleText_loc4`='<菲奥拉显得非常不安，没有半点说话的心情。>', `FemaleText_loc5`='<菲歐娜相當不安，似乎沒有心情跟人講話。>', `FemaleText_loc7`='<Fiona está bastante alterada. No parece estar de humor para hablar.>' WHERE `ID`=46096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 뵙게 되어 반갑군요, $n 님!', `FemaleText_loc4`='很高兴能再见到你，$n！', `FemaleText_loc5`='真高興又見到你，$n!', `FemaleText_loc7`='¡Me alegro de volver a verte, $n!' WHERE `ID`=46097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 그냥 놀러 오신 건가요, 아니면 사고 싶은 게 있으세요?', `FemaleText_loc4`='嗨，$n！你是来这里看望我们，还是要买些东西？', `FemaleText_loc5`='嗨，$n!你是來參觀而已，還是想買點東西?', `FemaleText_loc7`='¡Hola, $n! ¿Has venido de visita, o quieres comprar algo?' WHERE `ID`=46098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머... 누구신가 했네요!', `FemaleText_loc4`='哈哈，看看谁来了！', `FemaleText_loc5`='呵呵呵...看看是誰來啦!', `FemaleText_loc7`='Vaya, vaya... ¡Mira quién está aquí!' WHERE `ID`=46099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 멈춰 있다니, 정말 말도 안 돼! 우리에겐 할 일이 있다고!', `MaleText_loc4`='真无法相信，我们竟然就这样停下了！我们在这里还有任务要完成呢！', `MaleText_loc5`='我不敢相信，我們竟然停下來了!我們在這兒還有責任未了啊!', `MaleText_loc7`='¡No me puedo CREER que nos paremos! ¡Tenemos trabajo!' WHERE `ID`=46100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜들 출발하지 않는 거야? 빨리 떠나지 않는다면 나 혼자라도 가겠어!', `MaleText_loc4`='为什么我们还不离开？如果你们不走，我就要自己走了。', `MaleText_loc5`='為什麼我們還不離開呢?要是我們再不出發的話，我已經做好了一個人自己走的準備。', `MaleText_loc7`='¿Por qué no nos hemos ido aún? Estoy por irme por mi cuenta si no salimos ya.' WHERE `ID`=46101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 기다리는 거야, 피오나?', `MaleText_loc4`='出了什么事，菲奥拉？', `MaleText_loc5`='為什麼要停住，菲歐娜?', `MaleText_loc7`='¿Cuál es el problema, Fiona?' WHERE `ID`=46103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 기드윈... 심호흡을 하고...', `MaleText_loc4`='好了，吉德文……深呼吸……', `MaleText_loc5`='好了，基德溫...深呼吸...', `MaleText_loc7`='Venga, Gidwin... Respira hondo...' WHERE `ID`=46104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 $R 같으니! 바다가 네놈의 시체를 삼킬 것이다.', `MaleText_loc4`='$R！你的尸体会被扔进大海。', `MaleText_loc5`='$R!你的屍體將餵給大海。', `MaleText_loc7`='¡$R! Tu cadáver alimentará al mar.' WHERE `ID`=46105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박격포 집중 포화가 곧 쏟아집니다!', `MaleText_loc4`='迫击炮弹幕！', `MaleText_loc5`='砲火來襲!', `MaleText_loc7`='¡Tromba de mortero entrante!' WHERE `ID`=46106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰병의 안경을 가져갑니다.', `MaleText_loc4`='拿起这名斥候的眼镜。', `MaleText_loc5`='拿起斥候的眼鏡。', `MaleText_loc7`='Coge las gafas del explorador.', `FemaleText_loc1`='정찰병의 안경을 가져갑니다.', `FemaleText_loc4`='拿起这名斥候的眼镜。', `FemaleText_loc5`='拿起斥候的眼鏡。', `FemaleText_loc7`='Coge las gafas del explorador.' WHERE `ID`=46107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 쓸모없는 블러드 엘프 같으니! 우리에겐 완수해야 할 의무가 있는데, 저 녀석이 시간만 낭비하고 있잖아!', `MaleText_loc4`='没用的血精灵！我们还有任务，而他却在浪费我们的时间！', `MaleText_loc5`='那個沒用的血精靈!我們有「責任」要忙，而他只是在浪費我們的時間!', `MaleText_loc7`='¡Elfo de sangre inútil! ¡Tenemos TRABAJO, y nos hace perder el tiempo!' WHERE `ID`=46108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 말도 안 되는 일을 참아야 하는지 모르겠네. 저 녀석은 뭐든 진지하게 받아들이는 법이 없다니까!', `MaleText_loc4`='我不知道为什么要容忍他。他从来没有对一件事认真过。', `MaleText_loc5`='不曉得我幹嘛要忍受他的鬼扯，他從來不把事情當一回事。', `MaleText_loc7`='No sé por qué aguanto sus tonterías. Nunca se toma nada en serio.' WHERE `ID`=46109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티로서스 경께서 우리를 노스데일로 보내셨는데! 대체 왜 여기서 건방진 네루비안들 때문에 시간을 낭비하는 거냐고?!', `MaleText_loc4`='泰罗索斯亲自派我们前往北谷！为什么我们却要和那些猖狂的蛛魔浪费时间？！', `MaleText_loc5`='泰羅索斯親自派我們到北谷!我們為何要浪費時間在這些狂傲的奈幽蟲族身上?!', `MaleText_loc7`='¡El mismo Neófitus nos envió a Vallenorte! ¡¿Por qué perdemos el tiempo con trepas nerubianos?!' WHERE `ID`=46110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 기다리게 하면 내 망치로 한 대 때려줘야겠어.', `MaleText_loc4`='如果他再耽搁我们，我就把锤子敲到他的脑袋上。', `MaleText_loc5`='要是他害我們還得繼續等下去的話，我就要拿錘子狠狠往他頭上砸下去。', `MaleText_loc7`='Le voy a tirar el martillo a la cabeza si nos hace esperar más.' WHERE `ID`=46111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈이 가까운 곳에 있군... 난 느낄 수 있소. 성기사의 직감이라고나 할까?', `MaleText_loc4`='吉德文就在附近……我知道。这是圣骑士的直觉。', `MaleText_loc5`='基德溫在附近...我就是知道。這是聖騎士的直覺。', `MaleText_loc7`='Gidwin está cerca... Lo sé. Intuición de paladín.' WHERE `ID`=46112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니를 대신해 복수하고 싶습니다!

어머니를 해한 괴물의 주의를 끌고, 저희를 이 우리에서 풀어 주십시오. 그러면 당신의 곁에서 싸우겠습니다.

적이 가하는 피해를 줄여 주는 저희의 능력은 원시거룡의 그을리는 숨결을 견디는 데 도움이 될 겁니다.', `MaleText_loc4`='我们一定要为母亲复仇！

是那个怪物杀了她，转移他的注意力，把我们从笼子里放出去，我们就会与你并肩作战。

我们能减少敌人造成的伤害，帮你顶住原龙巨兽的灼热气息。', `MaleText_loc5`='我們一定要為媽媽報仇!

吸引殺掉她的那隻怪物的注意，把我們從籠子裡放出來，我們就會和你一起並肩作戰。

我們有辦法降低敵人所造成的傷害，保護你不被元龍巨獸的焦炎之息給殺死。', `MaleText_loc7`='¡Debemos vengar a nuestra madre!

Distrae al monstruo que la mató, libéranos de esta jaula y lucharemos a tu lado.

Nuestra capacidad de reducir el daño que inflige un enemigo te ayudará a sobrevivir el Aliento agostador del protobehemoth.' WHERE `ID`=46113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 같은 존재도 저런 멍청이에게 사로잡힐 정도인데 여기까지 오다니, 당신은 매우 용감한 존재임이 틀림없습니다.

할푸스의 주의를 끌고 저를 옭아맨 사슬을 끊어 주신다면 당신 곁에서 함께 싸우겠습니다.

적의 눈을 멀게 하는 저의 능력은 할푸스가 시도하는 광란의 공격을 견디는 데 도움이 될 겁니다.', `MaleText_loc4`='就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。

如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。

我可以让一个敌人失明，这一定能帮助你抵抗哈尔弗斯的狂乱攻击。', `MaleText_loc5`='你真是勇氣十足，竟然敢冒險闖進這裡頭，因為連我都被那個大傢伙給抓住了。

只要你能夠引開哈福斯的注意，破壞銬住我的鎖鍊，我就可以和你一同並肩作戰。

我的招式可以暫時使敵人的眼睛盲目，協助你承受哈福斯的狂亂突襲。', `MaleText_loc7`='Si ese patán inútil puede capturar a alguien como yo, entonces debes de ser muy valiente para aventurarte por aquí.

Si consigues distraer a Halfus y romper las cadenas que me atan, entonces lucharé a tu lado.

Mi capacidad de cegar los ojos de un enemigo te ayudará a aguantar el Asalto frenético de Halfus.' WHERE `ID`=46114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 같은 존재도 저런 멍청이에게 사로잡힐 정도인데 여기까지 오다니, 당신은 매우 용감한 존재임이 틀림없습니다.

할푸스의 주의를 끌고 저를 옭아맨 사슬을 끊어 주신다면 당신 곁에서 함께 싸우겠습니다.

적을 잠깐 동안 마비시키는 저의 능력은 할푸스가 가하는 악의의 일격을 멈추는 데 도움이 될 겁니다.', `MaleText_loc4`='就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。

如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。

我可以让一个敌人暂时麻痹，这一定能帮助你抵抗哈尔弗斯的致伤打击。', `MaleText_loc5`='你真是勇氣十足，竟然敢冒險闖進這裡頭，因為連我都被那個大傢伙給抓住了。

只要你能夠引開哈福斯的注意，破壞銬住我的鎖鍊，我就可以和你一同並肩作戰。

我的招式可以暫時麻痺敵人的身體，讓你在遭受哈福斯的致死打擊之後獲得喘息的機會。', `MaleText_loc7`='Si ese patán inútil puede capturar a alguien como yo, entonces debes de ser muy valiente para aventurarte por aquí.

Si consigues distraer a Halfus y romper las cadenas que me atan, entonces lucharé a tu lado.

Mi capacidad de paralizar temporalmente el cuerpo de un enemigo te aliviará frente a los Golpes malévolos de Halfus.' WHERE `ID`=46115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 같은 존재도 저런 멍청이에게 사로잡힐 정도인데 여기까지 오다니, 당신은 매우 용감한 존재임이 틀림없습니다.

할푸스의 주의를 끌고 저를 옭아맨 사슬을 끊어 주신다면 당신 곁에서 함께 싸우겠습니다.

저는 맹렬한 폭풍우로 할푸스를 휘감아, 그가 암흑 회오리를 시전하지 못하게 방해할 것입니다.', `MaleText_loc4`='就连我这样的人都会被那个蠢笨的呆子捉住。而你却能一直闯到这里，你一定是个非常勇敢的家伙。

如果你能转移哈尔弗斯的注意力，并且打断捆绑我的锁链，我就会和你一同战斗。

我能够用狂乱的暴风缠住一名敌人，这一定能影响哈尔弗斯施放暗影新星。', `MaleText_loc5`='你真是勇氣十足，竟然敢冒險闖進這裡頭，因為連我都被那個大傢伙給抓住了。

只要你能夠引開哈福斯的注意，破壞銬住我的鎖鍊，我就可以和你一同並肩作戰。

我會施展強烈的暴風雨術，不讓哈福斯順利施放出他的暗影新星。', `MaleText_loc7`='Si ese patán inútil puede capturar a alguien como yo, entonces debes de ser muy valiente para aventurarte por aquí.

Si consigues distraer a Halfus y romper las cadenas que me atan, entonces lucharé a tu lado.

Mi capacidad de envolver al enemigo en una tempestad entorpecerá los intentos de Halfus de desatar Novas de las Sombras.' WHERE `ID`=46116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거기 여행자, 안녕하신가? 여기 이 선량한 고블린이 뭐 도와줄 일이 없을까?$b$b난 여기 은빛십자군 사람들처럼 스컬지를 끔찍이도 싫어해서 희망의 빛 예배당에 머물고 있다고. 비행선이 추락해서 부끄럽게 여기로 도망친 건 절대로 아니야! 아무렴!$b$b아이고, 또 말실수를 하기 전에 그만 입을 다물어야겠어!', `MaleText_loc4`='哦，啊……你好，善良的旅行者！我这个好地精能为你做些什么？$b$b我向你保证，我会独自来到圣光之愿礼拜堂，是因为我像这些银色北伐军一样痛恨天灾军团。绝对不是因为我在一次令人羞愧的飞艇坠毁事故中逃跑了！$b$b嗯，我要闭嘴了。俗话说，言多必失嘛。', `MaleText_loc5`='哦，啊...哈囉，旅行者!請問今日可有我這哥布林能為您效勞之處呢?$b$b我向您保證，我到聖光之願禮拜堂這兒來完全是出自於我對天譴軍團的痛恨，就跟銀白十字軍這兒的人是完全一模一樣的，絕對不是因為我要逃離什麼難堪的飛艇墜毀事件!$b$b我得趕緊閉嘴了，免得越描越黑!', `MaleText_loc7`='Oh, ah... ¡Hola, $gbuen viajero:buena viajera;! ¿Qué puede hacer este humilde goblin por ti?$b$bTe aseguro que me encuentro en la Capilla de la Esperanza de la Luz exclusivamente por mi odio hacia la Plaga, que comparto con la Cruzada Argenta, ¡rotundamente no porque me esté escondiendo de un vergonzoso accidente de zepelín!$b$bAhora voy a dejar de hablar, antes de incriminarme más.' WHERE `ID`=46117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 괜찮은 생각이구먼, $r. 생각 좀 해 봐야겠는걸...$b$b좋아, 생각 끝! 나도 함께 가자고. 아무래도 희망의 빛 예배당에 너무 오래 있었다는 생각이 들어서 말이야. 엉덩이에 불이 붙은 노움처럼, 이제 좀 뛰어야겠어! 하하!', `MaleText_loc4`='你提供了一个有趣的选择，$r。我会好好考虑一下。$b$b好吧，我考虑好了。我会与你同行。也许我在圣光之愿礼拜堂已经待了太长时间。我已经准备好要行动了！呵呵！', `MaleText_loc5`='你的出現倒是提供了一種有趣的選擇，$r。我會把這點納入考量。$b$b好吧，我已經想過了。沒問題，我可以加入你。反正我在聖光之願禮拜堂也已經待得太久了。嘿嘿，我可得像在男廁小便斗前，把腳踮高尿尿的地精一樣加倍小心了!', `MaleText_loc7`='Resultas una opción interesante, $r. Lo pensaré.$b$bVale, ya lo he pensado. Claro que me uniré a ti. Sea como sea ya llevo demasiado tiempo en la Capilla de la Esperanza de la Luz. ¡Como un gnomo en un orinal, voy a tener que ponerme de puntillas! ¡Je, je, je!' WHERE `ID`=46118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 몸을 숨길 곳이 필요하시면, 저희 마차에 타고 가십시오.', `MaleText_loc4`='如果你想找个地方躲起来，那么尽可以到我们的马车上来。', `MaleText_loc5`='你知道的，要是你想找個地方避風頭，歡迎加入我們的商隊。', `MaleText_loc7`='Ya sabes, si buscas un lugar en el que esconderte, puedes unirte a nuestra caravana.', `FemaleText_loc1`='저, 몸을 숨길 곳이 필요하시면, 저희 마차에 타고 가세요.', `FemaleText_loc4`='如果你想找个地方躲起来，那么尽可以到我们的马车上来。', `FemaleText_loc5`='你知道的，要是你想找個地方避風頭，歡迎加入我們的商隊。', `FemaleText_loc7`='Ya sabes, si buscas un lugar en el que esconderte, puedes unirte a nuestra caravana.' WHERE `ID`=46119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 혹시 마차 몰 사람이 필요하면 여기 비질한테 시켜만 달라고.', `MaleText_loc4`='嗨，老板，如果你需要有人帮你赶马车，就和老比吉尔说一声。', `MaleText_loc5`='嘿，老大。如果需要人幫忙駕馭商隊，跟老比吉爾說一聲就行了。', `MaleText_loc7`='Hola, $gjefe:jefa;. Si necesitas que alguien conduzca la caravana, tú díselo al viejo Beezil.' WHERE `ID`=46120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발굽전사들이여! 네 족장을 지켜라!', `MaleText_loc4`='践踏者，守卫你们的酋长！', `MaleText_loc5`='踐踏者，保護酋長!', `MaleText_loc7`='¡Vapuleadores, defended a su Gran jefe!' WHERE `ID`=46121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학살자들아, 나를 지원하라!', `MaleText_loc4`='劫掠者们，到我的身边来！', `MaleText_loc5`='劫奪者，到我這兒集合!', `MaleText_loc7`='¡Atracadores, a mi lado!' WHERE `ID`=46122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흙점쟁이들아, 저놈들을 돌과 화염 속에 묻어버려라!', `MaleText_loc4`='地卜师，用岩石和烈火埋葬他们！', `MaleText_loc5`='地卜師，用石塊和火焰埋沒他們!', `MaleText_loc7`='¡Geománticos, cubridlos de piedras y llamas!' WHERE `ID`=46123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='T.A.D. 장비가 주 목표물에 조준을 완료했습니다!', `FemaleText_loc4`='让T.A.D.单位对准优先目标！', `FemaleText_loc5`='T.A.D.單位攻擊首要目標!', `FemaleText_loc7`='¡Las unidades T.A.D. tienen los objetivos prioritarios!' WHERE `ID`=46124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='2차 목표 공격!', `FemaleText_loc4`='对准次级目标！', `FemaleText_loc5`='攻擊次要目標!', `FemaleText_loc7`='¡Fijando objetivos secundarios!' WHERE `ID`=46125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑이여, 네 범죄의 죗값을 치르게 될 것이다!', `MaleText_loc4`='你将为自己的罪行受到惩罚，盗贼！', `MaleText_loc5`='小偷，你的犯行將會受到制裁!', `MaleText_loc7`='¡Recibirás tu castigo por esta transgresión, $gladrón:ladrona;!' WHERE `ID`=46126;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이놈은 고대의 그림토템 부족으로부터 힘을 얻고 있습니다! 이 괴물을 없애려면 그 힘의 근원부터 없애야 합니다!', `FemaleText_loc4`='这个怪物正在从恐怖图腾的先祖那里汲取能量！我们必须让那些逝者安息，才能真正打败这个怪物！', `FemaleText_loc5`='那隻怪物正在從恐怖圖騰的先祖們那裡吸收力量!我們一定要讓他們安息，才有辦法擊敗這隻怪獸!', `FemaleText_loc7`='¡Esta criatura está obteniendo poder de los ancestros Tótem Siniestro! ¡Debemos acabar con ellos si queremos derrotar a la bestia!' WHERE `ID`=46127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑습니다, $n 님. 당신이 관문 공격을 준비하는 동안 요원들이 여기 몇 명 더 숨어들어 왔습니다.$B$B마티아스 단장님과 어디서 접선하기로 했는지 보여 드리겠습니다.$B$B<황혼 성채 지도를 그리고는 접선 지점을 가리키는 분대 지휘관>$B$B준비되면 알려 주십시오. 함께 저기 올라가는 겁니다.', `MaleText_loc4`='真高兴又看见你了，$n。当你准备对大门发动进攻的时候，我们中的一些人也潜入到这里。$B$B我们计划在这里与肖尔大师碰面。$B$B<那名小队长拿出一张暮光堡垒的地图，指出那个地点。>$B$B等你准备好之后就告诉我，我们将并肩作战。', `MaleText_loc5`='很高興又見到你，$n。在你忙著部署進攻那道門的準備工作時，我們又多溜了幾個人進來。$B$B讓我告訴你我們預定和肖爾碰面的地方。$B$B<小隊長拿出一張暮光城塞的地圖，指著集合的地點。>$B$B準備好了就跟我說一聲，我們一起出發。', `MaleText_loc7`='Me alegro de verte de nuevo, $n. Hemos colado a unos cuantos más de los nuestros mientras estabas preparando las Puertas para el ataque.$B$BTe enseñaré dónde vamos a reunirnos con el maestro Shaw.$B$B<El líder de escuadrón saca un mapa de la Ciudadela Crepuscular y señala el lugar.>$B$BAvísame cuando estés $glisto:lista; y nos dirigiremos hacia allá juntos.' WHERE `ID`=46128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 준비됐습니다, 사령관님. 가시죠.', `MaleText_loc4`='我准备好了，指挥官，我们出发吧。', `MaleText_loc5`='我已經準備好了，指揮官。我們出發吧。', `MaleText_loc7`='Estoy listo, Comandante. Adelante.', `FemaleText_loc1`='전 준비됐어요, 사령관님. 가시죠.', `FemaleText_loc4`='我准备好了，指挥官，我们出发吧。', `FemaleText_loc5`='我已經準備好了，指揮官。我們出發吧。', `FemaleText_loc7`='Estoy lista, Comandante. Adelante.' WHERE `ID`=46129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=46130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 포탄을 먹여 줘라!', `MaleText_loc4`='让他们尝尝厉害！', `MaleText_loc5`='讓他們知道厲害!', `MaleText_loc7`='¡Dales fuerte!' WHERE `ID`=46131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날려 버려라!', `MaleText_loc4`='消灭他们！', `MaleText_loc5`='炸掉他們!', `MaleText_loc7`='¡Que salten por los aires!' WHERE `ID`=46132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뻥 터트려라!', `MaleText_loc4`='小心爆炸！', `MaleText_loc5`='要爆炸了!', `MaleText_loc7`='¡Fuego en el agujero!' WHERE `ID`=46133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 생명체는 고대 그림토템으로부터 힘을 얻고 있습니다! 이 괴물들을 쓰러뜨리려면 놈들부터 없어야 합니다!
', `MaleText_loc4`='这个怪物正在从恐怖图腾先祖那里吸取力量！如果我们要打败这个怪兽，就必须让恐怖图腾先祖安息下来！', `MaleText_loc5`='那隻怪物正在從恐怖圖騰的先祖們那裡吸收力量!我們一定要讓他們安息，才有辦法擊敗這隻怪獸!', `MaleText_loc7`='¡Esta criatura está obteniendo poder de los ancestros Tótem Siniestro! ¡Debemos acabar con ellos si queremos derrotar a la bestia!' WHERE `ID`=46134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 어수선해도 신경 쓰지 마세요. 아직 자리 잡는 중이니까요.$B$B그 때문에 즐기지 못해서야 되겠어요? 긴장 푸세요, 돈도 좀 쓰시고요... 환전업자와 세탁소부터 이국적인 마실거리와 상급 낚시꾼까지 다 있으니까요.$B$B누구 때문에 골치가 아프신가요? 그냥 ''제게만'' 살짝 알려 주세요. 처리해 드릴게요.$B$B저는 모두... 처리하는 미다거든요.', `FemaleText_loc4`='这里还有点乱，我们还在收拾，请别介意。$B$B你可以尽情在这里享受！放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。$B$B如果有人给你麻烦，就来找我，我会为你处理的。$B$B我是米达……大老板米达。', `FemaleText_loc5`='這裡亂糟糟的，請不要在意，我們還處於準備階段。$B$B但是可別因為這樣就放棄了享受點樂子的機會!花點小錢，放輕鬆...從錢幣兌換，洗衣服務，特殊風味的飲品，到釣魚訓練師，各種服務應有盡有。$B$B要是有人找你麻煩?你只要告訴我，我就會幫你搞定。$B$B我是米達...這兒的老闆。', `FemaleText_loc7`='Ignora todo este follón, todavía estamos instalándonos.$B$B¡Que esto no te impida pasarlo bien! Relájate, gasta un poco de pasta... Tenemos de todo, desde cambio de moneda y servicio de lavandería hasta bebidas exóticas e instructores de pesca.$B$BY si alguien te causa problemas. Me lo cuentas a MÍ, y yo me ocuparé.$B$BSoy Mida... la jefa.' WHERE `ID`=46135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 둘러보세요... 경기가 아주 제대로 일어나는 중이에요!$B$B갤리윅스가 아즈샤라 촌구석에 있는 그 휘황찬란한 궁전에 쓸 벽지를 고르느라 시간을 허비하는 동안 저는 곳곳을 쑤시고 다니며 돈을 두 배로 늘려드렸죠.$B$B제 말 좀 들어 보세요. 회계실, 무역 사무소, 건축과 보수, 군수사업, 보급로까지...$B$B수송 얘기까지 시작하면 날밤을 새워도 모자랄 걸요! 오크는 싸움은 되는데, 물건을 나르는 데는 영 꽝이에요. 우리 애들은 절반의 비용으로 두 배는 빠르게 나를 수 있는데! 음... 오는 도중에 터지지만 않는다면 그렇단 얘기죠, 히히.$B$B어쨌든요! 편하게 지내세요, 네? 즐기면서 돈도 좀 쓰시고요... 환전업자와 세탁소부터 이국적인 마실거리와 상급 낚시꾼까지 다 있으니까요.', `FemaleText_loc4`='看看这里……这里的生意是多么兴旺啊！$B$B当加里维克斯还为他在艾萨拉荒地的花哨宫殿选墙纸的时候，我已经在为老大挣取双倍的利润了。$B$B听我说：数数这里的房子、货栈、各种建筑和维护设施；看看这里的战争工事和补给线……$B$B这一切都还只是刚刚开始！兽人能打仗，但他们不懂得后勤运输。我的人搞运输的速度比他们快两倍，成本却只有他们的一半！好吧……前提是运输途中不出意外。$B$B不管怎样！在这里你可以尽情享受。放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。', `FemaleText_loc5`='你看看...生意好得不得了!$B$B就在加里維克斯忙著為他那個在鳥不生蛋的艾薩拉的別墅挑選壁紙的同時，我已經在為加老大狂賺猛賺兩倍的錢了。$B$B你聽我說:帳房、交易廳、建設和維修，戰爭的物資，補給線...$b$b更不用說還有運輸的費用!獸人是很會打，可是他們不會搬運貨物，而且我的船只要一半的價格就有兩倍快的運送速度!呃...是說如果沒有在半路就炸掉的話啦，嘿嘿。$B$B反正!放輕鬆一下，找點樂子，花點小錢，這兒從錢幣兌換，洗衣服務，特殊風味的飲品，到釣魚訓練師，各種服務應有盡有。', `FemaleText_loc7`='Mira alrededor... ¡El negocio FLORECE!$B$BMientras Gallywix pierde el tiempo con el papel de pared personalizado para su pomposo palacio en algún lugar perdido de Azshara, yo hago el doble de pasta llevando algunas cosas para el Gran G.$B$BComo te digo: contadurías, salas de mercaderes, construcción y mantenimiento, trabajos de guerra, líneas de suministros... $B$B¡Y todavía no he HABLADO del tránsito! Los orcos pueden luchar, pero no pueden mover mercancías. ¡El barco de mis chicos es el doble de rápido por la mitad de precio! Bueno... si no explota a medio camino, je, je, je.$B$B¡Da igual! Descansa, ¿eh? Diviértete, gasta... Tenemos de todo, desde cambio de moneda y servicio de lavandería hasta bebidas exóticas e instructores de pesca.' WHERE `ID`=46136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길동무가 있다는 건 언제나 즐거운 일이라오. 이렇게 멀리까지 여행을 하노라면 외로울 때가 있거든.', `MaleText_loc4`='旅途中有人作伴的感觉真好。否则一路上孤孤单单的。', `MaleText_loc5`='有個人作伴旅行真不錯。一個人趕路還蠻孤單的。', `MaleText_loc7`='Es bueno tener compañeros de viaje. La carretera es muy solitaria por estos lares.' WHERE `ID`=46137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n.', `MaleText_loc4`='你好啊，$n。', `MaleText_loc5`='你好，$n。', `MaleText_loc7`='Saludos, $n.' WHERE `ID`=46138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전진하라, $n! 얼라이언스의 개를 물리치고 포세이큰을 위해 로데론을 점령하라! 호드를 위하여!', `FemaleText_loc4`='$n，前进！我们会击退联盟狗，为被遗忘者占领洛丹伦！为了部落！', `FemaleText_loc5`='衝啊，$n!我們要把聯盟狗打回去，為被遺忘者守住羅德隆!為了部落!', `FemaleText_loc7`='¡Adelante, $n! ¡Rechazaremos a los perros de la Alianza y tomaremos Lordaeron para los Renegados! ¡Por la Horda!' WHERE `ID`=46139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 안돼요.$B$B두목님 벌목기를 재조정해야 하거든요.$B$B좀처럼 걸어 다닐 생각을 안 한다니까요. 늙은 할망구같이 말이에요. 특히나 대족장을 만나러 갈 때는 더 유난을 떨죠.', `MaleText_loc4`='现在还不行，$g小伙子:姑娘;。$B$B我还要调试老板的伐木机。$B$B她可不喜欢像那些老木头一样徒步在城周围走来走去，特别是在她要去对付那个酋长的时候。', `MaleText_loc5`='現在還不行。$B$B我得重新調校好老大的伐木機。$B$B她不喜歡跟個老呆子一樣用走的在城裡晃來晃去，尤其，是她要去見大酋長的時候。', `MaleText_loc7`='Ahora no, colega.$B$BTengo que volver a poner a punto la trituradora de la jefa.$B$BNo le gusta tener que andar por la ciudad a pie como un si fuera una bobalicona, ESPECIALMENTE si tiene que hacer tratos con el Jefe de Guerra.' WHERE `ID`=46140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 도시는 잿더미로 변하고, 너희 삶은 황폐해지리라!', `FemaleText_loc4`='我要把你们的城市夷平，把你们碾碎！', `FemaleText_loc5`='我要毀掉你們的城市，收拾你們的性命!', `FemaleText_loc7`='¡Reduciré sus ciudades a polvo y arruinaré sus vidas!' WHERE `ID`=46141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무기를 버리고 항복하라!', `FemaleText_loc4`='放下武器投降！', `FemaleText_loc5`='放下武器，就此投降!', `FemaleText_loc7`='¡Abandonad las armas y rendíos!' WHERE `ID`=46142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녀석들의 모습을 보라, $P. 쥐새끼처럼 허둥대며 자신의 최후를 향해 머리를 들이미는 꼴을. 크롤리와 블러드팽도 이게 얼마나 부질없는 짓인지 깨달을 것이다.', `FemaleText_loc4`='看看他们，$P。他们像老鼠一样来回奔窜，瞎着眼睛朝他们的末日冲过去。克罗雷和血牙肯定知道这是多么没有意义！', `FemaleText_loc5`='看看他們，$p。他們有如奔竄的鼠輩，一頭奔向他們的毀滅。相信克羅雷和血牙必能看出這只是無謂的掙扎!', `FemaleText_loc7`='Míralos, $p. Salen corriendo como ratas que van directas hacia su perdición. ¡Espero que Crowley y Colmillo de Sangre vean la futilidad de todo esto!' WHERE `ID`=46143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그레이메인 성벽으로 가라! 그러면 놈들도 어쩔 수 없이 움직일 테니...', `FemaleText_loc4`='格雷迈恩之墙！我们要把他们逼入绝境。', `FemaleText_loc5`='攻向葛雷邁恩之牆!我們要主動逼擊他們。', `FemaleText_loc7`='¡A la Muralla de Cringris! Les obligaremos a actuar.' WHERE `ID`=46144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 나는 나그란드에 있는 정령들의 조언을 구하기 위해 떠날 것이오. 그들은 이런 일을 이미 겪었고 지금 우리 세계에 나타나고 있는 많은 증상을 이미 목격했소.', `MaleText_loc4`='是的，我将动身前往纳格兰，去了解那里的元素。它们也遭受着痛苦，并且见到了许多像这样的征兆。', `MaleText_loc5`='是的，我打算前往納葛蘭向那裡的元素求教。它們曾經受盡苦難，見過許多同樣的徵兆。', `MaleText_loc7`='Sí, parto hacia Nagrand para estudiar los elementos del lugar. Ellos han visto y sufrido muchos de estos mismos síntomas.' WHERE `ID`=46145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 떠나있을 생각이신가?', `MaleText_loc4`='你准备去多久？', `MaleText_loc5`='你打算要離開多久?', `MaleText_loc7`='¿Cuánto tiempo estarás fuera?' WHERE `ID`=46146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 정보를 얻으려면 어느 정도 시간이 필요할 거요. 너무 오래 걸리지는 않으리라 믿지만, 몇 주, 어쩌면 몇 달이 될 수도 있소.', `MaleText_loc4`='也许要花些时间才能弄清我必须要了解的。我相信我不会离开很久，但可能也要几个星期——甚至几个月。', `MaleText_loc5`='可能要花點時間才能找到答案。我相信我應該不會離開太久，但或許要幾個禮拜，甚至幾個月。', `MaleText_loc7`='Puede que tarde un tiempo en averiguar lo que debo. Confío en no ausentarme mucho, pero podría tardar semanas... o meses.' WHERE `ID`=46147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 없는 동안, 가로쉬 헬스크림, 그대에게 호드를 이끌 것을 지시하오. 그대에게는 이런 혼란의 시기에 부족에게 필요한 힘과 용기가 있소.', `MaleText_loc4`='在我离开的这段日子里，我命令你——加尔鲁什·地狱咆哮，担任部落的领袖。你凭借力量与勇气一定能率领我们的人民在这困难时期生存下去。', `MaleText_loc5`='我不在的這段時間，卡爾洛斯·地獄吼，我要你代替我率領部落。在此艱難重重的時刻，你擁有率領我們全體度過難關的力量與勇氣。', `MaleText_loc7`='En mi ausencia te nombro a ti, Garrosh Grito Infernal, líder de la Horda. Tienes la fuerza y el coraje que nuestra gente necesita para sobrevivir estos tiempos difíciles.' WHERE `ID`=46148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광입니다. 대족장님, 하지만 이 몸은 아직 지도자로서는 준비가 부족합니다.', `MaleText_loc4`='我很荣幸，酋长。但我还没准备好担任统治者。', `MaleText_loc5`='我深感榮耀，大酋長。可是我擔心自己還沒有做好身為領袖的準備。', `MaleText_loc7`='Es un honor, Jefe de Guerra. Pero no creo que esté preparado para llevar la vida de un gobernante.' WHERE `ID`=46149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 혼자가 아니오. 그대에게는 케른, 아이트리그, 볼진과 같은 조언가가 있소. 이들이 그대를 도울 것이오.', `MaleText_loc4`='你并非孤身一人。会有顾问从旁协助你——凯恩、伊崔格和沃金，他们会指引你的。', `MaleText_loc5`='你並不孤單。你有很多人可以諮詢:凱恩，伊崔格，沃金，他們都會很樂意提供你建議與協助。', `MaleText_loc7`='No estarás solo. Tendrás consejeros: Cairne, Eitrigg, Vol''jin. Ellos te guiarán.' WHERE `ID`=46150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 조만간 떠나야 하지만, 나도 그전에 그대에게 가르침을 주겠소.', `MaleText_loc4`='而且尽管我很快就要离开，我也可以指点你一些。', `MaleText_loc5`='雖然我即將離開，我也還是可以盡量多指導你。', `MaleText_loc7`='Y, aunque partiré en breve, yo también puedo instruirte.' WHERE `ID`=46151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 이교도 문제를 해결해보는 것이 좋은 연습이 될 수 있겠군. 주민들이 무슨 일인지도 모른 채 두려움에 떨고 있으니.', `MaleText_loc4`='就先拿这群邪教徒小试牛刀吧。人们恐慌不已。他们不知道发生了什么事。', `MaleText_loc5`='解決這些教徒的問題或許是個不錯的第一項測試。大家都很恐慌，他們不曉得到底發生了什麼事情。', `MaleText_loc7`='Una buena prueba sería que te encargaras de lo'' cultores. La gente tiene miedo. No saben qué eh''tá pasando.' WHERE `ID`=46152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리도 무슨 일인지 확실히 모르지 않소. 이교도를 붙잡아 입을 다물게 해야겠소? 그러면 주민들의 노여움을 사게 될 것이오... 그렇다고 이대로 이교도가 주민들에게 거짓과 공포를 확산하게 놔둘 수도 없고...', `MaleText_loc4`='可就连我们也不知道这究竟是怎么一回事。我们该不该把这些邪教徒抓起来，让他们闭嘴？但那会激怒剩下的人……尽管如此，我们决不允许教派恣意散播恐惧与谎言……', `MaleText_loc5`='可是連我們都無法確知近來所發生的一切事情。難道我們就該逮捕這些教徒，以強硬的手段消弭他們的發言嗎?那麼做有可能反而會激怒其他的人...但無論如何，我們的確不能坐視那些教徒繼續散佈恐慌與謊言...', `MaleText_loc7`='Pero ni siquiera nosotros sabemos lo que está pasando. ¿Deberíamos capturar a los cultores y forzar su silencio? La gente podría montar en cólera... Pero no podemos permitir que las sectas extiendan el miedo y las mentiras...' WHERE `ID`=46153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 지도자다운 생각을 하는군, 가로쉬. 항상 문제의 모든 면을 검토해야 하오. 조언자들에게 자문하고 자신 있게 행동하시오.', `MaleText_loc4`='现在你已经像统治者那样思考了，加尔鲁什。你必须全面地分析问题。听听你顾问的意见，信心满满地展开行动吧。', `MaleText_loc5`='很好，卡爾洛斯，這就是身為領袖該有的氣度和想法。思考問題的時候一定要面面俱到。多多徵詢顧問們的意見，然後堅定自信地去執行。', `MaleText_loc7`='Ya estás pensando como un líder, Garrosh. Debes observar el problema desde todas las perspectivas. Consulta con tus consejeros y actúa con seguridad.' WHERE `ID`=46154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 그대를 도울 것이오, 가로쉬. 나도 그대를 돕겠소. 그리고 반드시 주민들의 공포를 없애고 정령을 달랠 수 있는 해결책을 찾아오겠소.', `MaleText_loc4`='他们会帮你的，加尔鲁什。我也会帮你。我一定会找到我们要找的答案，来消除人们的恐惧，安抚躁动的元素。', `MaleText_loc5`='他們都會協助你，卡爾洛斯，而且我也會幫你。我一定會找出答案，消弭大眾的恐慌，撫平元素們的傷痛。', `MaleText_loc7`='Te ayudarán, Garrosh, al igual que yo. Encontraré las respuestas que necesitamos para aliviar el miedo de la gente y calmar a los elementos.' WHERE `ID`=46155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 절대 실망하게 하지 않겠습니다. 온 힘을 다해 부족을 이끌고 그대가 말한 조언자들에게 자문하겠습니다. 그대가 내게 엄청난 영광을 베풀어 주었다는 사실을 잘 알고 있습니다. 반드시 노력하여 기대를 저버리지 않겠습니다.', `MaleText_loc4`='我不会让你失望的，酋长。我会尽我所能管理好部落，并与你推荐的顾问多加沟通。我深知你所赋予我的是一份极大的荣耀，我会全力以赴，让自己无愧于此。', `MaleText_loc5`='我不會讓你失望的，大酋長。我必定會竭盡所能領導部落，並且遵照你的建議多多徵詢顧問們的意見。我明白你這麼做對我而言是多麼大的一份榮耀，我一定會不辱使命。', `MaleText_loc7`='No te fallaré, Jefe de Guerra. Gobernaré lo mejor que pueda, y consultaré con los consejeros que me recomiendas. Sé que me otorgas un gran honor, y me esforzaré en ser digno del mismo.' WHERE `ID`=46156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. 그럼 이만 끝내겠소.', `MaleText_loc4`='那就这样吧。', `MaleText_loc5`='那就這麼決定了。', `MaleText_loc7`='Entonces no hay más que hablar.' WHERE `ID`=46157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 호드를 위해 힘써주시오.', `MaleText_loc4`='确保你所做的一切都是为了部落。', `MaleText_loc5`='願你所作所為皆是為了部落。', `MaleText_loc7`='Que todo lo que hagas sea por el bien de la Horda.' WHERE `ID`=46158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Ho''da!' WHERE `ID`=46159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=46160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=46161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 역병숲 깊은 곳까지 찾아오는 사람은 별로 없소. 그나마도 대부분은 누더기골렘이지.$b$b내게 부탁할 게 있소?', `MaleText_loc4`='在病木林深处很少会有访客。通常都是憎恶。$b$b我能帮你什么忙吗？', `MaleText_loc5`='在這病木林深處裡可沒有多少訪客會來看我。頂多只有憎惡怪罷了。$B$B有什麼事情是我可以幫得上的呢?', `MaleText_loc7`='No suelo recibir muchos visitantes tan al interior del Bosque de la Peste. Abominaciones, más que nada.$b$b¿Te puedo ayudar en algo?' WHERE `ID`=46162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배의 제독은 해전 중에 숨을 거두었소. 나는 이 배를 요새로 전환했지.$B$B없으면 없는 대로 어떻게든 해야 하지 않겠소, $c.', `MaleText_loc4`='将军在上一次海战中不幸遇难。我把他的舰船改造成了堡垒。$B$B这只是个应急方案，$c。', `MaleText_loc5`='上將是在我們上次的出航中遇難的。如今我已經將這艘船改裝成了一座堡壘。$B$B資源有限，我們得物盡其用，$c。', `MaleText_loc7`='El Almirante murió durante nuestro último encuentro naval. He convertido este barco en una fortaleza.$b$bEstamos improvisando, $c.' WHERE `ID`=46163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하시오. 헬스크림 님께서 당신을 지켜보고 계시오, $n!', `MaleText_loc4`='记住——地狱咆哮的双眼在注视着你，$n！', `MaleText_loc5`='記住:地獄吼的雙眼在盯著你，$n!', `MaleText_loc7`='Recuerda: ¡los ojos de Grito Infernal te vigilan, $n!' WHERE `ID`=46164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 가져온 서판의 성각문자를 보면 이 장치를 다시 작동시키는 방법이 있다고 하오.$b$b그 방법만 알아내면 되는데...', `MaleText_loc4`='从石板上的秘密符文看来，有办法让这装置重新焕发活力。$b$b我们只需要想出该如何做……', `MaleText_loc5`='你這塊石板上的象形文字指出有個方法可以讓這個裝置再度發揮作用。$B$B我們只需要想通到底該怎麼做...', `MaleText_loc7`='Los jeroglíficos de tus tablillas indican que hay una forma de hacer que este mecanismo vuelva a funcionar.$b$bSolo tenemos que descubrir cómo...' WHERE `ID`=46165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞서 들어온 병사가 신호탄을 설치하는 데는 성공했지만, 결국 발사하지 못하고 목숨을 잃었습니다.$b$b이제 당신의 능력을 보여줄 시간입니다.', `MaleText_loc4`='看来你的前人已经把信号弹搭好了，但还没来得及发射。$b$b现在看你的了，$n。', `MaleText_loc5`='看來你的前任者還有時間點燃信號彈，可是他們還沒有被發射出去。$B$B這正是你發光發熱的時候了，$n。', `MaleText_loc7`='Al parecer tu predecesor tuvo tiempo de colocar las bengalas, pero todavía no han sido lanzadas.$b$bAquí tienes tus minutos de fama, $n.' WHERE `ID`=46166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호탄을 모두 발사했습니다.', `MaleText_loc4`='信号弹发射器已清空。', `MaleText_loc5`='信號彈發射器已經空了。', `MaleText_loc7`='El lanzador de bengalas ha sido vaciado.' WHERE `ID`=46167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가트... 적어도 우리가 다 내리고 나서 배를 분해해 줬으면 좋겠군.', `MaleText_loc4`='果仁……你能不能等我们下了船，再把它拆散？', `MaleText_loc5`='葛納加特...你可不可以等我們下船了再來拆船?', `MaleText_loc7`='Gnugat... ¿Te importaría esperar hasta que hayamos SALIDO del barco antes de intentar desmontarlo?' WHERE `ID`=46168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가트, 지금 자신이 밟고 서 있는 배를 분해해 버리는 게 현명한 행동이라고 생각하나?', `MaleText_loc4`='果仁，你觉得把你现在正坐的船拆烂，这明智吗？', `MaleText_loc5`='葛納加特，拆掉你正在坐的船真的是一件好事嗎?', `MaleText_loc7`='Gnugat, ¿me lo parece a mí o estás intentando desguazar un barco bajo tus propios pies?' WHERE `ID`=46170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가트, 자네 고블린들이 이 배를 조금만 더 뜯어내면 배가 파도 속으로 곤두박질치고 말 걸세!', `MaleText_loc4`='果仁，你们这些地精要是再拆一块这船的支承架，它就要窜到海里冲浪去了！', `MaleText_loc5`='葛納加特，你的哥布林要是再拆掉這艘船的任何東西，它就要沈下去了!', `MaleText_loc7`='Gnugat, si tus goblins siguen quitando los soportes de este barco, ¡caerá a la arena!' WHERE `ID`=46171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 금이라고, 친구!', `MaleText_loc4`='时间就是金钱，我的朋友！', `MaleText_loc5`='時間就是金錢，朋友!', `MaleText_loc7`='¡El tiempo es oro, colega!' WHERE `ID`=46172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아만 있다고 돈이 벌리는 건 아니라고, 록타르.', `MaleText_loc4`='富贵险中求，Rok''tar。', `MaleText_loc5`='怕死就賺不到錢啦，洛克塔。', `MaleText_loc7`='Nadie saca dinero manteniéndose con vida, Rok''tar.' WHERE `ID`=46173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르, 생각해 보라고. 이 금속 덩어리를 누가 더 원하겠어? 자네? ... 아니면 최고 입찰자?', `MaleText_loc4`='谁更需要这块金属，洛克塔尔？是你……还是出价最高的人？', `MaleText_loc5`='反正誰還需要這一大塊廢鐵，洛克塔?是你? ...還是出價最高的買家?', `MaleText_loc7`='¿A quién le hace más falta este pedazo de metal, Rok''tar? ¿A ti... o al mejor postor?' WHERE `ID`=46174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고원의 나무들은 무진장 튼튼하지. 어떤 건 말 그대로... 돌덩이라고. 도무지 이해할 수가 없어.$B$B나무를 베려고 다이아몬드톱니 벌목기를 보냈는데, 얼라이언스가 벌목기를 계속 때려 부수고 있어.', `MaleText_loc4`='这片高地上的树木质都很坚硬。它们之中有一些……甚至是石头。我也不明白这究竟是为什么。$B$B为了砍伐这些木材，我们在伐木机上装备了钻石刀刃。但联盟却总是在破坏那些伐木机。', `MaleText_loc5`='高地這邊的樹木材質都非常的堅固，有些甚至就是...石頭。雖然我不懂，但是無所謂。$B$B我們有鑽石刀刃的伐木機可以採收它們，但是聯盟的人總在破壞我們的伐木機。', `MaleText_loc7`='Los árboles de las Tierras Altas están hechos de madera sólida, y algunos... de piedra. No pretendo entenderlo.$b$bTenemos trituradoras con hojas de diamante para la recolección, pero la Alianza no deja de estropearlas.' WHERE `ID`=46175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작해 보자고, 젊은 친구. 내가 제대로 실력 발휘해 보지.', `MaleText_loc4`='好吧，$g小子:姑娘;，来让我们好好看看。', `MaleText_loc5`='我們走吧，讓你看看事情是怎樣辦的。', `MaleText_loc7`='Allá vamos, $gtío:nena;. Aprende cómo se hacen las cosas.', `FemaleText_loc1`='우후, $g자기:아가씨;! 잠깐 물러나서 제가 어떤 마법을 부리는지 보세요.', `FemaleText_loc4`='呦喉，$g小甜心:姑娘;！退开一点，看看这场魔法吧。', `FemaleText_loc5`='呦呼，寶貝!站到一邊去，看我的厲害。', `FemaleText_loc7`='¡Hola, $ghermoso:compañera;! Apártate y disfruta de la magia.' WHERE `ID`=46176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 공격하면 날 지켜 줘야 해.', `MaleText_loc4`='万一我们遭到伏击，记得掩护我。', `MaleText_loc5`='顧好我的屁股，免得我們被人偷捅了。', `MaleText_loc7`='Cúbreme las espaldas por si nos tienden una emboscada.', `FemaleText_loc1`='누가 공격하면 절 지켜 주셔야 해요.', `FemaleText_loc4`='万一我们遭到伏击，记得掩护我。', `FemaleText_loc5`='顧好我的屁股，免得我們被人偷捅了。', `FemaleText_loc7`='Cúbreme las espaldas por si nos tienden una emboscada.' WHERE `ID`=46177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 벌목기는 수리할 수 있을 듯합니다. 신호를 쏘아 올립니다...', `MaleText_loc4`='看样子，这台伐木机还是可以修理的。你打个信号弹……', `MaleText_loc5`='這台伐木機好像還修得好的樣子。你去發射個信號...', `MaleText_loc7`='Parece que esta trituradora se puede reparar. Disparas una señal...' WHERE `ID`=46178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, $n. 자네가 관문 공격을 준비하는 동안 암살자들이 여기 몇 명 더 숨어들었네.$B$B가로나와 어디서 접선하기로 했는지 보여 주지.$B$B<황혼 성채 지도를 그리고는 접선 지점을 가리키는 분대 지휘관>$B$B준비되면 알려 주게. 함께 저기 올라가는 걸세.', `MaleText_loc4`='向你致敬，$n。当你准备对大门发动进攻的时候，我们中的一些人也潜入到这里。$B$B我们计划在这里与迦罗娜汇合。$B$B<那名小队长拿出一张暮光堡垒的地图，指出那个地点。>$B$B等你准备好之后就告诉我，我们将一同行动。', `MaleText_loc5`='你好，$n。在你忙著部署進攻那道門的準備工作時 ，我們又多溜了幾個人進來。$B$B讓我告訴你我們預定和迦羅娜碰面的地方。$B$B<小隊長拿出一張暮光城塞的地圖，指著集合的地點。>$B$B準備好了就跟我說一聲，我們一起出發。', `MaleText_loc7`='Throm-Ka, $n. Hemos colado a unos cuantos más de los nuestros mientras estabas preparando las Puertas para el ataque.$B$BTe enseñaré dónde vamos a reunirnos con Garona.$B$B<El líder de escuadrón saca un mapa de la Ciudadela Crepuscular y señala el lugar.>$B$BAvísame cuando estés $glisto:lista; y nos dirigiremos hacia allá juntos.' WHERE `ID`=46179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇, 몰라. 너무 망가져서 못 고치겠다고. 나 간다!', `MaleText_loc4`='好吧，别管它了。这东西已经没希望了。我要离开这里！', `MaleText_loc5`='好吧，算了!這個東西已經沒救了。我要離開這裡啦!', `MaleText_loc7`='Bueno, pues nada. Este trasto está estropeado sin remedio. ¡Yo me largo!', `FemaleText_loc1`='에잇, 몰라요. 너무 망가져서 못 고치겠어요. 전 갑니다!', `FemaleText_loc4`='好吧，别管它了。这东西已经没希望了。我要离开这里！', `FemaleText_loc5`='好吧，算了!這個東西已經沒救了。我要離開這裡啦!', `FemaleText_loc7`='Bueno, pues nada. Este trasto está estropeado sin remedio. ¡Yo me largo!' WHERE `ID`=46180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈다고! 자, 이제 이 걸작을 움직여 볼까...', `MaleText_loc4`='我们做到了！来，我们要让这个杰作动起来……', `MaleText_loc5`='成功了!讓我們把這個傑作給發動起來...', `MaleText_loc7`='¡Lo logramos! Vamos a arrancar esta obra maestra...', `FemaleText_loc1`='해냈다고요! 자, 이제 이 걸작을 움직여 볼까요...', `FemaleText_loc4`='我们做到了！来，我们要让这个杰作动起来……', `FemaleText_loc5`='成功了!讓我們把這個傑作給發動起來...', `FemaleText_loc7`='¡Lo logramos! Vamos a arrancar esta obra maestra...' WHERE `ID`=46181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직여야 합니다, $n 님. 경사로를 따라 올라가서 바로 마티아스 단장님께 갑시다.', `MaleText_loc4`='我们应该行动了，$n。攀上这段阶梯，然后直接去找肖尔大师。', `MaleText_loc5`='我們該走了，$n。從坡道上去，然後直接去找肖爾。', `MaleText_loc7`='Deberíamos ponernos en marcha, $n. Rampa arriba y directos a ver al maestro Shaw.' WHERE `ID`=46182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음톱니 벌목기... 가동! 시스템 무결성 검사. 57퍼센트가 겨우 작동 중입니다.', `MaleText_loc4`='死亡锯刃……被激活！系统完整性检测：百分之五十七正常。', `MaleText_loc5`='死亡之刃...啟動!檢查系統完整度:百分之57正常。', `MaleText_loc7`='Hojamuerte... ¡activada! Comprobación de integridad del sistema: 57%, nominal.' WHERE `ID`=46183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 기준으로는 상당히 훌륭한 수준입니다.', `MaleText_loc4`='这东西的确很符合锈水标准。', `MaleText_loc5`='以污水企業的標準來說還真不錯。', `MaleText_loc7`='Pues no está mal para el criterio Pantoque.' WHERE `ID`=46184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이동식 로켓포를 배치합니다!', `MaleText_loc4`='移动火箭平台展开！……好啊。', `MaleText_loc5`='設置機動火箭發射平台!...喔耶。', `MaleText_loc7`='¡Despliega las plataformas de los cohetes móviles...! Oh, sí.' WHERE `ID`=46185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 인간이여! 새로운 신 앞에 무릎 꿇고 스테인리스 강철 발굽을 핥아라!', `MaleText_loc4`='来吧，人类！来舔舔你们的新神的不锈钢靴子！', `MaleText_loc5`='來吧，人類!舔舔你的新神明的不銹鋼靴子吧!', `MaleText_loc7`='¡VENGAN, HUMANOS! ¡LAMAN LAS BOTAS DE ACERO INOXIDABLE DE SU NUEVO DIOS!' WHERE `ID`=46186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 뭔가 이상한 소리가...', `MaleText_loc4`='等等！你有没有听到些什么？', `MaleText_loc5`='等等!你有沒有聽到什麼?', `MaleText_loc7`='¡Espera! ¿Has oído algo?' WHERE `ID`=46187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크롤리, 네 졸개들은 모두 내 병력 앞에 무릎을 꿇었다. 너의 패배다!', `FemaleText_loc4`='克罗雷，你的部众已在我强大的军队面前落败了。你输了！', `FemaleText_loc5`='克羅雷，你的部隊已經被我的大軍給擊潰了。你輸了!', `FemaleText_loc7`='Crowley, tus tropas han caído ante mi magnífico ejército. ¡Has perdido!' WHERE `ID`=46188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 끝나지 않았다, 실바나스. 아직은 아니다.', `MaleText_loc4`='还没结束，希尔瓦娜斯。还早呢。', `MaleText_loc5`='還沒結束呢，希瓦娜斯。還沒有。', `MaleText_loc7`='No es el fin, Sylvanas. Aún no.' WHERE `ID`=46189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거짓의 왕좌에 올라앉은 네 왕은 널 도우려는 생각이 전혀 없는데, 너는 경솔하게 모두의 목숨을 버리려 하는구나.', `FemaleText_loc4`='你鲁莽地葬送人民的生命，而你们的国王却端坐在由谎言铸成的王座上，连手指头都不曾动过一下。', `FemaleText_loc5`='你毫不假思索地派你的百姓們前來送死，而你們自己的國王卻繼續安穩地坐在他的王座上，連動根手指頭幫個忙也沒有。', `FemaleText_loc7`='Sacrificas las vidas de tu gente con frivolidad mientras tu propio rey permanece sentado en su trono de mentiras, sin levantar siquiera un dedo para ayudarte.' WHERE `ID`=46190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금껏 스러져간 수많은 목숨과 맞바꿀 만큼 길니아스가 소중한가? 앞으로도 사라질 목숨만큼이나 중요한가? 넌 이길 수 없다.', `FemaleText_loc4`='吉尔尼斯值得让那么多人失去生命吗？还有更多将要失去的生命？你赢不了的。', `FemaleText_loc5`='吉爾尼斯真的值得那些已經死去，還有即將犧牲的生命嗎?你們毫無勝算。', `FemaleText_loc7`='¿Merece Gilneas las vidas que se han perdido? ¿Las vidas que se perderán? No puedes ganar.' WHERE `ID`=46191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 목숨은 이미 버렸다!', `MaleText_loc4`='我们将奋战至死！', `MaleText_loc5`='我們寧死不屈!', `MaleText_loc7`='¡Moriremos intentándolo!' WHERE `ID`=46193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 딸도 그런가? 어쩌면 넌 그녀를 구할 수 있었을지도 모르겠다. 네 피를 나눠줬더라면... 하지만 넌 그러지 않았다. 왜지?', `FemaleText_loc4`='那你的女儿呢？你本可以救她……你本可以为她献出你的鲜血，可是你没有。为什么？', `FemaleText_loc5`='那你女兒呢?你原本可以救得了她的...你可以用你的血來給她，可是你卻沒有。為什麼?', `FemaleText_loc7`='¿Y tu hija? Podrías haberla salvado... Podrías haberle ofrecido tu sangre, pero no lo hiciste. ¿Por qué?' WHERE `ID`=46194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르나?! 무슨... 내 딸은 어디에 있나?! 로르나에게 무슨 짓을 한 거냐?!', `MaleText_loc4`='罗娜？什么……她在哪儿？！你对她做了什么？！', `MaleText_loc5`='羅娜?什麼...她在哪裡!?你對她做了什麼!?', `MaleText_loc7`='¿LORNA? ¿Qué...? ¡¿Dónde está?! ¡¿Qué le habéis hecho?!' WHERE `ID`=46195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무 짓도 하지 않았다. 아직은...', `FemaleText_loc4`='暂时还没做什么……', `FemaleText_loc5`='目前，還沒有...', `FemaleText_loc7`='Nada, de momento...' WHERE `ID`=46196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네게 선택의 기회를 주겠다. 나는 가질 수 없었던 기회를 말이다.', `FemaleText_loc4`='我现在给你个选择的机会——这机会我可不曾获得过。', `FemaleText_loc5`='我現在給你一個選擇的機會。我自己可從來沒被人給過這樣的機會。', `FemaleText_loc7`='Te presento una elección... Una elección que nunca me ofrecieron a mí.' WHERE `ID`=46197;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무조건 항복하면 로르나의 목숨은 살려주겠다.', `FemaleText_loc4`='我要用罗娜的性命，换取你无条件的投降。', `FemaleText_loc5`='只要你無條件投降，我就把羅娜的性命還給你。', `FemaleText_loc7`='Te ofrezco la vida de Lorna a cambio de tu rendición incondicional.' WHERE `ID`=46198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 생각해 봐라, 크롤리. 내 제안을 거부하면 네 딸은 언데드가 되어 날 섬길 것이다. 영원히.', `FemaleText_loc4`='仔细想想再回答我，克罗雷。如果你拒绝我，那么她就将变成我不死的奴仆——直到永远。', `FemaleText_loc5`='想清楚你的回答，克羅雷。拒絕我，她就會永遠成為我的僕人，死後亦然。', `FemaleText_loc7`='Elige tus próximas palabras con prudencia, Crowley. Si me rechazas, ella me servirá en la no-muerte... para siempre.' WHERE `ID`=46199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그녀를 데려와라, 고드프리!', `FemaleText_loc4`='把她带上来，高弗雷！', `FemaleText_loc5`='帶她過來，高佛雷!', `FemaleText_loc7`='¡Tráela, Godfrey!' WHERE `ID`=46200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜만이군, 친구.', `MaleText_loc4`='你好啊，老朋友！', `MaleText_loc5`='嗨，老朋友!', `MaleText_loc7`='¡Hola, viejo amigo!' WHERE `ID`=46202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고드프리! 너, 이 벌레만도 못한 배신자!', `MaleText_loc4`='高弗雷！你这虚伪的蛆虫！', `MaleText_loc5`='高佛雷!你這個無恥的叛徒!', `MaleText_loc7`='¡GODFREY! ¡Gusano traidor!' WHERE `ID`=46203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르나... 나는... 그녀를 풀어줘라. 퇴각 나팔을 불겠다.', `MaleText_loc4`='罗娜……我……快放了她。我会下令撤兵。', `MaleText_loc5`='羅娜...我...放開她。我會下令撤退。', `MaleText_loc7`='Lorna... Yo... Liberadla. Anunciaré la retirada.' WHERE `ID`=46204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담하지 마라, 크롤리, 이 멍청한 녀석아!', `MaleText_loc4`='你不是认真的吧，克罗雷。你这可怜的混蛋！', `MaleText_loc5`='你不是認真的吧，克羅雷。你這個可悲的混蛋!', `MaleText_loc7`='No puedes hablar en serio, Crowley. ¡Miserable cobarde!' WHERE `ID`=46205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그녀를 풀어줘라, 고드프리.', `FemaleText_loc4`='放了她，高弗雷。', `FemaleText_loc5`='放開她，高佛雷。', `FemaleText_loc7`='Suéltala, Godfrey.' WHERE `ID`=46206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 여왕님.', `MaleText_loc4`='当然，主人。', `MaleText_loc5`='遵命，女王。', `MaleText_loc7`='Por supuesto, señora.' WHERE `ID`=46207;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 이곳을 떠나라. 그리고 다시는 돌아오지 마라.', `FemaleText_loc4`='现在你可以离开了，克罗雷，永远别再回来。', `FemaleText_loc5`='離開這裡，克羅雷，永遠不准回來。', `FemaleText_loc7`='Ahora vete, Crowley, y no vuelvas nunca.' WHERE `ID`=46208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로데론은 포세이큰의 땅이다.', `FemaleText_loc4`='洛丹伦属于被遗忘者。', `FemaleText_loc5`='羅德隆是屬於被遺忘者的。', `FemaleText_loc7`='Lordaeron pertenece a los Renegados.' WHERE `ID`=46209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 딸아, 이 아비를 용서하렴...', `MaleText_loc4`='原谅我，女儿……', `MaleText_loc5`='原諒我，女兒...', `MaleText_loc7`='Perdóname, hija...' WHERE `ID`=46210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드의 병사들이여! 우리가 승리했다! 로데론은...', `FemaleText_loc4`='部落的战士们！我们胜利了！洛丹伦是……', `FemaleText_loc5`='部落的將士們!我們獲勝了!羅德隆是...', `FemaleText_loc7`='¡SOLDADOS DE LA HORDA! ¡HEMOS OBTENIDO LA VICTORIA! LORDAERON ES...' WHERE `ID`=46211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 죽습니다.', `FemaleText_loc4`='%s倒下了。', `FemaleText_loc5`='%s死了。', `FemaleText_loc7`='%s muere.' WHERE `ID`=46212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓이냐, 고드프리!', `MaleText_loc4`='你干了什么，高弗雷！', `MaleText_loc5`='你做了什麼，高佛雷!', `MaleText_loc7`='¡GODFREY! ¡¿QUÉ HAS HECHO?!' WHERE `ID`=46213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래전에 해야 했던 일이다, 이 더러운 짐승 계집아.
', `MaleText_loc4`='干了件我早该完成的事，你这龌龊的怪物。', `MaleText_loc5`='很久以前就該這樣做了，你這可憎的野獸。', `MaleText_loc7`='Algo que deberías haber hecho hace mucho tiempo, animal repugnante.' WHERE `ID`=46214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스는 내 것이다. 그리고 곧 로데론의 나머지도 내 것이 되리라!', `MaleText_loc4`='吉尔尼斯是我的，很快，整个洛丹伦都会是我的！', `MaleText_loc5`='吉爾尼斯是我的，不久之後全羅德隆也是我的!', `MaleText_loc7`='¡Gilneas me pertenece, y pronto Lordaeron también!' WHERE `ID`=46215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 네 여군주를 따라 저승길로 가라!', `MaleText_loc4`='现在，跟你的主人一起下地狱吧！', `MaleText_loc5`='跟你的女主人一起死吧!', `MaleText_loc7`='¡AHORA ÚNETE A TU SEÑORA EN LA MUERTE!' WHERE `ID`=46216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴하라, 형제들이여! 그림자송곳니 성채로!', `MaleText_loc4`='撤退，弟兄们！回影牙！', `MaleText_loc5`='撤退，弟兄們!到影牙城堡!', `MaleText_loc7`='¡ATRÁS, HERMANOS! ¡A COLMILLO OSCURO!' WHERE `ID`=46217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 힘이 이 땅을 그 뿌리까지 흔들어 놓을 것이다!', `MaleText_loc4`='这片土地将因我们的毁灭之势而战栗，而颤抖！', `MaleText_loc5`='我們的毀滅將會撼動這片大地!', `MaleText_loc7`='¡Esta tierra temblará y se sacudirá bajo nuestra destrucción!' WHERE `ID`=46218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려내... 살려내라!', `MaleText_loc4`='快弄好她……弄好她！', `MaleText_loc5`='快救她...快救她!', `MaleText_loc7`='Salvadla... ¡SALVADLA!' WHERE `ID`=46219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 그녀에게 귀속되어 있다, 자매들이여...', `FemaleText_loc4`='我们束缚于她，姐妹们……', `FemaleText_loc5`='姊妹們，我們與她魂魄相連...', `FemaleText_loc7`='Estamos vinculadas a ella, hermanas...' WHERE `ID`=46220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러면 우리는 파괴될 것이다, 자매여...', `FemaleText_loc4`='这会毁了我们的，姐妹们……', `FemaleText_loc5`='那麼做會害我們魂飛魄散，姊妹...', `FemaleText_loc7`='Nos destruirá, hermana...' WHERE `ID`=46221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그것이 우리의 신성한 의무이다. 서약을 봉인했고, 계약을 맺었다.', `FemaleText_loc4`='这是我们神圣的职责。契约已经缔造，交易已经达成……', `FemaleText_loc5`='那是我們神聖的職責。契約已經定下，交易已經談妥...', `FemaleText_loc7`='Es nuestro deber sagrado. El pacto fue sellado, el trato hecho...' WHERE `ID`=46222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 그 의무를 다하겠다.', `FemaleText_loc4`='那就接受吧。', `FemaleText_loc5`='那就動手吧。', `FemaleText_loc7`='Que así se haga, entonces.' WHERE `ID`=46223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오직... 어둠만이 보였다.', `FemaleText_loc4`='我的眼前……只有黑暗。', `FemaleText_loc5`='我只見到...黑暗。', `FemaleText_loc7`='Solo vi... oscuridad.' WHERE `ID`=46224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 내가 무를 향해 흘러가는 동안 찬란한 빛이 나타났다. 그리고 또 다른 빛과, 또 다른 빛이... 나의 친애하는 발키르여.', `FemaleText_loc4`='正当我朝着虚无漂移时，一道亮光出现了，然后又一道，再一道……我亲爱的瓦格里。', `FemaleText_loc5`='就在我飄向無盡的虛空的同時，一道明亮的光芒忽然出現，然後又一道、又一道...我摯愛的華爾琪。', `FemaleText_loc7`='Y cuando me deslicé hacia la nada, apareció una luz brillante, y luego otra, y otra... Mis queridas Val''kyr.' WHERE `ID`=46225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의혹의 그림자를 넘어, 나는 이제야 알았다. 발키르야 말로 우리의 미래라는 사실을.', `FemaleText_loc4`='我现在明白了——并且坚信不疑——瓦格里是我们的未来。', `FemaleText_loc5`='如今我明白了--毫無一絲懷疑--華爾琪就是我們的未來。', `FemaleText_loc7`='Ahora sé, más allá de toda duda, que las Val''kyr son nuestro futuro.' WHERE `ID`=46226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 로데론을 위한 싸움을 멈추지 않겠다. 절대로...', `FemaleText_loc4`='我们永远不会放弃洛丹伦。永远不会……', `FemaleText_loc5`='我們永遠不會放棄攻下羅德隆。永遠不會...', `FemaleText_loc7`='Nunca dejaremos de luchar por Lordaeron. Nunca...' WHERE `ID`=46227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 쪽 사람들이 와일드해머 드워프들과 좋은 관계를 유지한 지도 꽤 긴 시간이 흘렀습니다.$B$B이 땅이 지킬 가치가 있는 땅이라 판단한 소수는 이곳에 정착했지요.', `MaleText_loc4`='我的人民长久以来都和蛮锤部族保持着良好的关系。$B$B我们当中有少数人在此定居。那些人把这片土地看作是值得守护的家园。', `MaleText_loc5`='我們跟蠻錘氏族維持了好一段的良好關係。$B$B我們有少數人來這裡定居了，凡是住下來的人都認為這裡是值得捍衛的家園。', `MaleText_loc7`='Mi gente ha tenido una buena relación con los Martillo Salvaje desde hace un tiempo.$b$bAlgunos nos hemos asentado aquí... aquellos que hemos descubierto que esta tierra es un hogar que merece la pena defender.' WHERE `ID`=46228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더럽고 냄새나는 오크 놈들아! 새끼들을 놓아줘라!', `MaleText_loc4`='卑鄙的兽人，卑鄙！放了那些小崽子！', `MaleText_loc5`='下流、下流的獸人!把那些幼龍交出來!', `MaleText_loc7`='¡Sucios, sucios orcos! ¡Soltad a esos miserables!' WHERE `ID`=46229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고원으로 도망가지는 못할 거다! 오크 놈들아!', `MaleText_loc4`='你们别想逃离高地，兽人！', `MaleText_loc5`='你無法逃離高地的，獸人!', `MaleText_loc7`='¡No podéis huir de las tierras altas, orcos!' WHERE `ID`=46230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흉악한 놈들! 더러운 반역자들아!', `MaleText_loc4`='残忍的渣滓！虚伪的混蛋！', `MaleText_loc5`='該死的東西!可惡的傢伙!', `MaleText_loc7`='¡Escoria asesina! ¡Basura traicionera!' WHERE `ID`=46231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타올라라! 그리고 고통받아라!', `MaleText_loc4`='燃烧吧！燃烧吧，痛苦吧！', `MaleText_loc5`='燒吧!在烈焰中哀嚎吧!', `MaleText_loc7`='¡Arded! ¡ARDED Y SUFRID!' WHERE `ID`=46233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라올 테면 따라와 봐!', `MaleText_loc4`='够胆子的话就跟我走！', `MaleText_loc5`='有膽量就跟上來!', `MaleText_loc7`='¡O estás con nosotros o en contra! ¡Sígueme si te atreves!' WHERE `ID`=46234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전략적 후퇴를 해야겠군!', `MaleText_loc4`='该战略性撤退了！', `MaleText_loc5`='是戰略撤退的時候了!', `MaleText_loc7`='¡Hora de la retirada!' WHERE `ID`=46235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 이러다가 후회할걸!', `MaleText_loc4`='你会为此后悔的！', `MaleText_loc5`='你會後悔的!', `MaleText_loc7`='¡Lo lamentarás!' WHERE `ID`=46238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 경고했었지?', `MaleText_loc4`='别说我没有警告你！', `MaleText_loc5`='別說我沒警告你!', `MaleText_loc7`='¿No te lo advertí?' WHERE `ID`=46239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감옥에 있으면서 중요한 걸 하나 배웠어. 아, 밥에서 콩 골라내는 법은 빼고 말이야. 바로 생존이지롱!!!', `MaleText_loc4`='监狱生活给我上了一堂很重要的课，如果算上要把肥皂捏稳那就是两堂，是的！生存第一！', `MaleText_loc5`='監牢教了我一件很重要的事，好吧，加上把肥皂拿穩算兩件，但沒錯!就是如何生存!', `MaleText_loc7`='¡Si hay algo que aprendí de la cárcel, además de no soltar nunca el jabón, es SOBREVIVIR!' WHERE `ID`=46240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 때려주기 딱 좋은 자리에 섰군!', `MaleText_loc4`='啊哈！我就是想把你引到这儿来！', `MaleText_loc5`='啊哈!我就是要把你引到這!', `MaleText_loc7`='¡Ajá! ¡Te tengo donde te quería!' WHERE `ID`=46241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 밀하우스 마나스톰 님의 진정한 힘을 보아라!', `MaleText_loc4`='现在……见识米尔豪斯·法力风暴的全部力量吧！', `MaleText_loc5`='現在...見證米歐浩斯·曼納斯頓完全的力量吧!', `MaleText_loc7`='¡Siente el poder del Molino Tormenta de Maná!' WHERE `ID`=46242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 병사들! 무모하고, 거만하지. (필멸자들이 이리 종종, 저리 종종.) 너희는 수도 적고... 이미 너무 늦었어. (소용없어. 희망 없어. 없어. 없어.)', `MaleText_loc4`='联盟士兵！非常大胆，非常傲慢。（匆忙，匆忙，匆忙的凡人。）你们势单力孤，而且来得太迟了。（无助而无望的，无助而无望的。）', `MaleText_loc5`='聯盟士兵!真是大膽，真是勇敢。(凡人手忙腳亂，手忙腳亂。)你們的數量太少，而且一切也太晚了。 (無助和絕望，無助和絕望。)', `MaleText_loc7`='¡Soldados de la Alianza! Tan osados, tan caballerosos. (Mortales escurridizos, escurridizos.) Son pocos y llegan tarde. (Desvalidos y desahuciados, desvalidos y desahuciados.)' WHERE `ID`=46243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈!', `MaleText_loc4`='古加尔！', `MaleText_loc5`='丘加利!', `MaleText_loc7`='¡Cho''gall!' WHERE `ID`=46244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 없애라!', `MaleText_loc4`='杀了他！', `MaleText_loc5`='殺了他!', `MaleText_loc7`='¡Mátenlo!' WHERE `ID`=46245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈투자드의 지배를 벗어나고 리치 왕의 몰락을 지켜본 지금, 이 희망찬 시기에도 빛의 결사단은 남아 있습니다.', `FemaleText_loc4`='即使是在克尔苏加德统治结束后这光明的日子里，在巫妖王战败之后——兄弟会仍生生不息。', `FemaleText_loc5`='即便在科爾蘇加德統治結束、在巫妖王殞歿之後的光明日子裡，兄弟會依然長存。', `FemaleText_loc7`='Incluso en estos días luminosos tras el reinado de Kel''Thuzad, tras la caída del Rey Exánime... La Hermandad sobrevive.' WHERE `ID`=46246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계의 심장에는 아무도 들어갈 수 없다!', `MaleText_loc4`='没人能接近世界之心！', `MaleText_loc5`='沒有人可以穿過世界之心!', `MaleText_loc7`='¡No pasarán al Centro del mundo!' WHERE `ID`=46247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 순환이 완성되었다.', `MaleText_loc4`='轮回完成了。', `MaleText_loc5`='輪迴已完成。', `MaleText_loc7`='Se completó el ciclo.' WHERE `ID`=46248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸에 부딪히고, 부서져라! 대지의 강력함을 느껴 보아라!', `MaleText_loc4`='被我的身躯碾碎。感受大地的力量！', `MaleText_loc5`='以我的身軀摧毀你們。感受大地之力!', `MaleText_loc7`='Quiébrate sobre mi cuerpo. ¡Siente la fuerza de la tierra!' WHERE `ID`=46249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자가 쓰러졌다. 세계의 심장이 위험에 노출됐다!', `MaleText_loc4`='保护者倒下了。世界之心暴露了！', `MaleText_loc5`='一位保護者倒下了。世界之心有危險了!', `MaleText_loc7`='Ha caído un protector. ¡El Centro del mundo, expuesto!' WHERE `ID`=46250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 죽음 때문에 셀 수 없이 많은 이가 목숨을 잃을 것이다. 다... 너희의 책임이야...', `FemaleText_loc4`='无数人将随我的死亡而倒下。重担……落到你们……肩上了。', `FemaleText_loc5`='我的死亡只會帶來更多的死亡。這個重擔現在換你來背了。', `FemaleText_loc7`='Tras mi muerte, habrá infinitas más. El peso está en tus hombros ahora.' WHERE `ID`=46251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병사여, 추종자여, 세계파괴자의 아이들이여, 내 부름을 들어라! 아버지의 신성한 전당이 더럽혀지고 말았다! 침입자를 처치하라!', `FemaleText_loc4`='仆从们，信徒们，灭世者之子，我在此召唤你们！我们父亲的神圣大厅已经被玷污了！杀死入侵者！', `FemaleText_loc5`='爪牙們，隨從們，諸界毀滅者之子們，我在呼喚你們!我們父親的神聖殿堂被污染了!殺死入侵者!', `FemaleText_loc7`='¡Esbirros, hijos del Rompemundos, vengan a mí! ¡Las salas santificadas de nuestro padre han sido contaminadas! ¡Maten a los intrusos!' WHERE `ID`=46252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙 님께서 내게 허락하신 힘을 보아라! 대지의 분노를 느껴라!', `FemaleText_loc4`='见证死亡之翼赋予我的强大力量吧！感受大地之怒！', `FemaleText_loc5`='見證死亡之翼賜予的力量吧!感受大地之怒!', `FemaleText_loc7`='¡Siente el poder de Alamuerte en mí! ¡La furia de la tierra!' WHERE `ID`=46253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신께 바칩니다, 주인님.', `FemaleText_loc4`='主人，请收下祭品。', `FemaleText_loc5`='收下祭品吧，主人。', `FemaleText_loc7`='Un sacrificio para usted, amo.' WHERE `ID`=46254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상은 불꽃 속에서 다시 태어나리라!', `FemaleText_loc4`='这个世界将在烈焰中重生！', `FemaleText_loc5`='世界會在火焰中重生!', `FemaleText_loc7`='¡El mundo renacerá en llamas!' WHERE `ID`=46255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학카르에게는 많은 이름이 있습니다. 어떤 이는 학카르를 혈신이라 부르고, 또 어떤 이는 영혼약탈자라고 부르지요. 이름이야 어쨌든, 학카르는 우리 세상에 악의를 품은 엄청난 힘의 소유자입니다.$B$B저는 오래전 이 사원을 발견하고 슬픔의 늪 아래로 가라앉혔지요. 안타깝게도 이 행동이 오히려 아탈라이 부족을 도운 것 같습니다. 아무에게도 방해받지 않고 학카르를 소환할 수 있게 되었으니까요. 사원을 감시하는 임무를 띤 많은 용이 타락했고, 영혼약탈자는 날이 갈수록 더욱 뚜렷한 존재가 되고 있습니다.$B$B저 혼자서는 놈을 막을 수 없습니다. 하지만 함께라면 이 미친 짓을 끝낼 여유가 있을지도 모르지요.', `MaleText_loc4`='哈卡有许多尽为人知的名字。有人叫他血神，另一些人则直白地把他称作夺灵者。抛开名衔不说，他是这个世界上强大力量与邪恶意图的化身。$B$B我早先发现了这座神庙，并将它沉到了悲伤沼泽的下方。不幸的是，我们似乎只是在帮助阿塔莱——确保他们召唤哈卡的计划能在不受干扰的环境下实施。许多负责守卫神庙的巨龙都已被腐化，夺灵者的气息却一天天变得更为强烈。$B$B我无法凭自己的力量阻止他们。但如果我们合作，也许能有足够的时间终止他们的疯狂举动。', `MaleText_loc5`='哈卡有許多的名號，有些人稱他為『血神』，有些人直接稱他為『奪魂者』。但不論其稱號為何，他的確具有強大的力量，而且對這世界心懷不軌。$B$B我們綠龍很早便發現了這座神殿，並將它沈入悲傷沼澤底下。然而不幸的是，我們反倒幫了那些阿塔萊祭司的忙，讓他們可以毫不受外界干擾地繼續召喚哈卡。奪魂者的力量日漸增強，許多負責看守這座神廟的龍都受到其邪力影響而腐化墮落了。$B$B雖然我無法獨自阻止他們，但只要能結合我們的力量，我們或許還有足夠的時間可阻止這一場瘋狂的惡夢。', `MaleText_loc7`='Hakkar recibe muchos nombres. Algunos le llaman el Dios de la Sangre, otros simplemente se refieren a él como el Cazador de Almas. Títulos aparte, es una entidad de enorme poder que alberga malignas intenciones hacia nuestro mundo.$B$BMi vuelo descubrió su templo y lo hundió en el Pantano de las Penas. Desafortunadamente, lo único que hicimos fue ayudar a los Atal''ai a que sus esfuerzos por invocar a Hakkar pudieran seguir adelante sin distracciones. Muchos de los dragones encargados de guardar el templo han sido corrompidos y la presencia del Cazador de Almas crece cada día que pasa.$B$BNo puedo detenerles solo. Juntos, sin embargo, quizá tengamos tiempo suficiente para detener esta locura.' WHERE `ID`=46256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주 실바나스 윈드러너를 최전선까지 수행해야 합니다.', `FemaleText_loc4`='护送希尔瓦娜斯·风行者穿过战斗前线。', `FemaleText_loc5`='陪同希瓦娜斯·風行者女士越過前線。', `FemaleText_loc7`='Acompaña a Lady Sylvanas Brisaveloz por el Frente de Batalla.' WHERE `ID`=46257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(처치해! 모두 처치해 버려!)', `MaleText_loc4`='（消灭！把他们全都消灭！）', `MaleText_loc5`='(幹掉它!把它們全部幹掉!)', `MaleText_loc7`='(¡Acábenlos! ¡A todos!)' WHERE `ID`=46258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 살덩이들!', `MaleText_loc4`='可怜的血肉之躯！', `MaleText_loc5`='可悲的血肉之軀!', `MaleText_loc7`='¡Carne patética!' WHERE `ID`=46259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 짐승들! 나도 한때 너희와 같았지. (옛날 주인님. 작고 배고파.) 너희는 필멸의 껍데기에 집착하며... (피와 뼈, 눈물 주머니.) 너희의 보잘것없음을 애써 외면하지.', `MaleText_loc4`='部落的走狗！我曾经像你们一样。（老主人弱小又饥饿。）你们无法摆脱凡人的躯壳……（血泪白骨的肉袋）……却竭力否认自身的渺小。', `MaleText_loc5`='部落的廢物!我曾像你一樣。(我們的老主人，又小又饑渴。)你們穿著凡人的外殼... (裝著鮮血骨頭眼淚的包包)...不肯面對你們的弱小。', `MaleText_loc7`='¡Escoria de la Horda! Yo fui como ustedes. (Nuestros antiguos amos, hambrientos.) Se aferran a sus cáscaras mortales... (Bolsas de sangre y huesos y lágrimas.) ...buscando negar su insignificancia.' WHERE `ID`=46260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직이세, $n. 경사로를 올라 가로나에게 가야 하네.', `MaleText_loc4`='我们快点行动吧，$n。上台阶直接去找迦罗娜。', `MaleText_loc5`='我們快點走吧，$n。從坡道上去，然後直接去找迦羅娜。', `MaleText_loc7`='Vamos rápido, $n. Subamos la rampa y vayamos directos a Garona.' WHERE `ID`=46261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 스톰윈드 위를 지나가는 와중에 스톰윈드 공원이 파괴되었소. 당분간은 다르나서스로 돌아가 있으려 하오.', `MaleText_loc4`='死亡之翼途径暴风城，为花园区留下了满目疮痍。我们只得暂时返回达纳苏斯。', `MaleText_loc5`='由於暴風城花園區在死亡之翼飛過城市上空時被毀掉了，我們將暫且返回達納蘇斯。', `MaleText_loc7`='Tras la destrucción del Parque de Ventormenta a causa del vuelo de Alamuerte sobre la ciudad, vamos a volver a Darnassus por un tiempo.' WHERE `ID`=46262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명가가 돌아왔고, 그들과 함께 몇백 년 동안 사라졌던 기술이 함께 돌아왔습니다.$b$b제가 분석해 드릴 물건이 있습니까?', `MaleText_loc4`='上层精灵回来了，还带回了失落已久的神秘法术。$B$B你有什么需要我检视的东西吗？', `MaleText_loc5`='精靈貴族已然歸來，並且帶回了失傳百千年之久的魔法技藝。$B$B你有東西要我查驗嗎?', `MaleText_loc7`='Los Altonato han regresado, y con ellos hechizos que llevaban siglos perdidos para el mundo.$b$b¿Tienes algo que quieras que examine?', `FemaleText_loc1`='명가가 돌아왔고, 그들과 함께 몇백 년 동안 사라졌던 기술이 함께 돌아왔습니다.$b$b제가 분석해 드릴 물건이 있습니까?', `FemaleText_loc4`='上层精灵回来了，还带回了失落已久的神秘法术。$B$B你有什么需要我检视的东西吗？', `FemaleText_loc5`='精靈貴族已然歸來，並且帶回了失傳百千年之久的魔法技藝。$B$B你有東西要我查驗嗎?', `FemaleText_loc7`='Los Altonato han regresado, y con ellos hechizos que llevaban siglos perdidos para el mundo.$b$b¿Tienes algo que quieras que examine?' WHERE `ID`=46263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이템을 재연마하겠습니다.', `MaleText_loc4`='重铸一件物品。', `MaleText_loc5`='重鑄一項物品。', `MaleText_loc7`='Reforjar un objeto.', `FemaleText_loc1`='아이템을 재연마하겠습니다.', `FemaleText_loc4`='重铸一件物品。', `FemaleText_loc5`='重鑄一項物品。', `FemaleText_loc7`='Reforjar un objeto.' WHERE `ID`=46264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재연마가 뭔가요?', `MaleText_loc4`='什么是重铸？', `MaleText_loc5`='什麼是重鑄?', `MaleText_loc7`='¿Qué es reforjar?', `FemaleText_loc1`='재연마가 뭔가요?', `FemaleText_loc4`='什么是重铸？', `FemaleText_loc5`='什麼是重鑄?', `FemaleText_loc7`='¿Qué es reforjar?' WHERE `ID`=46265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 재연마사는 아이템의 마법 효과를 변경할 수 있습니다. 이 복잡한 절차가 재연마라고 알려져 있습니다.$b$b재연마를 통해 무기, 방어구, 장신구의 두 번째 속성을 감소하여 다른 두 번째 속성을 추가할 수 있습니다. 이런 방법으로 자신의 역할과 기술에 적합하게 장비의 속성을 변경할 수 있습니다.$b$b예를 들어, 어떤 아이템에 적중을 높여주는 속성이 있는데, 당신은 그보다 빠른 공격 속도를 원한다면, 마법 재연마사에게 비용을 내고 아이템의 적중을 낮추는 대신 가속을 높일 수 있습니다.', `MaleText_loc4`='奥术重铸师能更改一件物品的魔法效果，这种奇术就叫重铸。$B$B通过重铸，武器、防具或珠宝原有的某种次要属性将被移除，以为其添加新的次要属性。通过这种方式，使用者可以对其装备进行自定义，以更好地与其角色和技能相匹配。$B$B例如，如果某样物品可使你更准确地命中敌人，但你却更想获得更快的攻击速度，则可花费若干费用，通过奥术重铸师重铸这件物品，降低命中而提高急速。', `MaleText_loc5`='秘法重鑄師能夠調校一件物品的魔法效力，這種複雜的魔法程序就叫做「重鑄」。$B$B經由重鑄的過程，可以降低任何武器、護具或珠寶的某一次要屬性，轉而增加一項額外的次要屬性。也就是說，你可以透過這種方式來調整自身的裝備，讓它們更符合你的角色定位與技能的需求。$B$B舉例而言，若有一件裝備可提升你對敵人的命中率，但是你卻寧可它提升的是你的攻擊速度，那麼這時候秘法重鑄師—在酌收適當費用之後—便可以幫你重鑄這件物品，降低其命中，轉而提高你的加速。', `MaleText_loc7`='Los reforjadores Arcanos pueden modificar los efectos mágicos de un objeto; esta compleja magia se conoce como reforjar.$b$bMediante este proceso, un atributo secundario de un arma, una pieza de armadura o una joya se puede reducir para añadir un atributo secundario adicional. De esta forma, es posible personalizar el equipo para que se adapte a tu clase y facultades.$b$bPor ejemplo, si un objeto mejora tu probabilidad de golpear a los enemigos pero preferirías atacar más rápido, un reforjador Arcano podría, por el precio adecuado, reforjar ese objeto para que tuviera menos índice de golpe pero más índice de celeridad.', `FemaleText_loc1`='마법 재연마사는 아이템의 마법 효과를 변경할 수 있습니다. 이 복잡한 절차가 재연마라고 알려져 있습니다.$b$b재연마를 통해 무기, 방어구, 장신구의 두 번째 속성을 감소하여 다른 두 번째 속성을 추가할 수 있습니다. 이런 방법으로 자신의 역할과 기술에 적합하게 장비의 속성을 변경할 수 있습니다.$b$b예를 들어, 어떤 아이템에 적중을 높여주는 속성이 있는데, 당신은 그보다 빠른 공격 속도를 원한다면, 마법 재연마사에게 비용을 내고 아이템의 적중을 낮추는 대신 가속을 높일 수 있습니다.', `FemaleText_loc4`='奥术重铸师能更改一件物品的魔法效果，这种奇术就叫重铸。$B$B通过重铸，武器、防具或珠宝原有的某种次要属性将被移除，以为其添加新的次要属性。通过这种方式，使用者可以对其装备进行自定义，以更好地与其角色和技能相匹配。$B$B例如，如果某样物品可使你更准确地命中敌人，但你却更想获得更快的攻击速度，则可花费若干费用，通过奥术重铸师重铸这件物品，降低命中而提高急速。', `FemaleText_loc5`='秘法重鑄師能夠調校一件物品的魔法效力，這種複雜的魔法程序就叫做「重鑄」。$B$B經由重鑄的過程，可以降低任何武器、護具或珠寶的某一次要屬性，轉而增加一項額外的次要屬性。也就是說，你可以透過這種方式來調整自身的裝備，讓它們更符合你的角色定位與技能的需求。$B$B舉例而言，若有一件裝備可提升你對敵人的命中率，但是你卻寧可它提升的是你的攻擊速度，那麼這時候秘法重鑄師—在酌收適當費用之後—便可以幫你重鑄這件物品，降低其命中，轉而提高你的加速。', `FemaleText_loc7`='Los reforjadores Arcanos pueden modificar los efectos mágicos de un objeto; esta compleja magia se conoce como reforjar.$b$bMediante este proceso, un atributo secundario de un arma, una pieza de armadura o una joya se puede reducir para añadir un atributo secundario adicional. De esta forma, es posible personalizar el equipo para que se adapte a tu clase y facultades.$b$bPor ejemplo, si un objeto mejora tu probabilidad de golpear a los enemigos pero preferirías atacar más rápido, un reforjador Arcano podría, por el precio adecuado, reforjar ese objeto para que tuviera menos índice de golpe pero más índice de celeridad.' WHERE `ID`=46266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 재연마사를 찾는다면, 마법사 지구 바로 밖에 있는 마법부여 가게 안에서 명가의 마법사가 있을 겁니다.', `MaleText_loc4`='如果你想要找奥术重铸师重铸物品，可以去法师区外的附魔商店，那里有一位上层精灵法师可以帮上你的忙。', `MaleText_loc5`='若是你要找位秘法重鑄師，在法師區外頭的附魔商店裡就有一位精靈貴族法師。', `MaleText_loc7`='Si buscas un reforjador Arcano que reforje tus objetos, hay un mago Altonato dentro de la tienda de encantamiento justo en el exterior del Barrio de los Magos.', `FemaleText_loc1`='마법 재연마사를 찾는다면, 마법사 지구 바로 밖에 있는 마법부여 가게 안에서 명가의 마법사가 있을 겁니다.', `FemaleText_loc4`='如果你想要找奥术重铸师重铸物品，可以去法师区外的附魔商店，那里有一位上层精灵法师可以帮上你的忙。', `FemaleText_loc5`='若是你要找位秘法重鑄師，在法師區外頭的附魔商店裡就有一位精靈貴族法師。', `FemaleText_loc7`='Si buscas un reforjador Arcano que reforje tus objetos, hay un mago Altonato dentro de la tienda de encantamiento justo en el exterior del Barrio de los Magos.' WHERE `ID`=46267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재연마', `MaleText_loc4`='重铸', `MaleText_loc5`='重鑄', `MaleText_loc7`='Reforjar', `FemaleText_loc1`='재연마', `FemaleText_loc4`='重铸', `FemaleText_loc5`='重鑄', `FemaleText_loc7`='Reforjar' WHERE `ID`=46268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 불공평해!!', `MaleText_loc4`='这一点儿都不公平！！', `MaleText_loc5`='這太不公平了!!', `MaleText_loc7`='¡Esto no parece justo!' WHERE `ID`=46269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내가 이렇게 지저분한 꼭대기에 앉아야 하는 건데?!', `MaleText_loc4`='我为什么就非得坐在顶上，跟这堆东西挤在一起？！', `MaleText_loc5`='我幹嘛得坐在這些個東西上面?!', `MaleText_loc7`='¿Por qué tengo que quedarme con todo esto?' WHERE `ID`=46270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 가장 용감해서 그런 거야, 기드윈.', `FemaleText_loc4`='因为你最勇敢，宝贝儿。', `FemaleText_loc5`='親愛的，因為你是最勇敢的啊。', `FemaleText_loc7`='Porque eres el más valiente, cielo.' WHERE `ID`=46271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 키가 작아서 그런 거라고.', `MaleText_loc4`='因为你个子矮。', `MaleText_loc5`='因為你最矮。', `MaleText_loc7`='Porque eres bajito.' WHERE `ID`=46272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야! 여기 가방을 네 머리 위로 떨어뜨릴 수도 있어, 타레나.', `MaleText_loc4`='嘿！我可真该把这些东西砸到你头上，塔伦纳。', `MaleText_loc5`='嘿!我要弄倒個箱子砸到你頭上，塔瑞納爾。', `MaleText_loc7`='¡Oye! Debería tirarte uno de estos cajones a la cabeza, Tarenar.' WHERE `ID`=46273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='널 앞자리에 태워주겠다고 약속했던 건 아는데, 기드윈, 이렇게 나이 드신 손님을 태우게 됐잖아. 미안해.', `FemaleText_loc4`='我知道我答应让你坐在前排，吉德文，可我们这儿有位年长的客人。真对不起。', `FemaleText_loc5`='我知道我跟你答應過了說你可以坐前座，阿基。但是很抱歉，我們有位年長的客人。', `FemaleText_loc7`='Sé que te había prometido el asiento de delante, Giddy, pero tenemos un invitado mayor. Lo siento.' WHERE `ID`=46274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피오나, 조심하는 게 좋아. 기드윈은 너한테 뽀뽀하고 싶어서 앞자리에 앉으려는 거니까.', `MaleText_loc4`='菲奥拉，我必须提醒你——吉德文之所以想要坐到前排，就是为了亲你的脸。', `MaleText_loc5`='菲歐娜，我得警告你:基德溫要坐前座是因為他想要偷親你。', `MaleText_loc7`='Fiona, te lo advierto: Gidwin solo quiere sentarse delante porque quiere besarte.' WHERE `ID`=46275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야! 조용히 해, 이 바보야. 보아하니 네가 피오나한테 뽀뽀하고 싶은 모양이구나.', `MaleText_loc4`='喔闭嘴，你这白痴。恐怕是你想要亲她一百遍吧。', `MaleText_loc5`='噢，閉嘴，你這笨蛋。我看是「你」才想要親她一百遍吧。', `MaleText_loc7`='Oh, cállate, estúpido. Seguro que TÚ quieres besarla al menos cien veces.' WHERE `ID`=46276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니거든!', `MaleText_loc4`='住口！', `MaleText_loc5`='才沒有!', `MaleText_loc7`='¡Pues no!' WHERE `ID`=46277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어험! 아, 태워줘서 고맙소, 피오나 양. 이렇게 한 번쯤 편하게 여행하는 것도 좋구려.', `MaleText_loc4`='啊咳！我，啊，很感谢你能让我搭便车，菲奥拉女士。偶尔歇歇脚也不错。', `MaleText_loc5`='呃哼!我，呃，謝謝你們願意載我一程，菲歐娜女士。很高興有個機會能歇歇腿。', `MaleText_loc7`='¡Ejem! Muchas, eh, gracias por el viaje, señora Fiona. Es un alivio descansar los pies por una vez.' WHERE `ID`=46278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 길에서 보통 혼자 다니시나요?', `FemaleText_loc4`='你经常一个人走在这些路上吗？', `FemaleText_loc5`='你通常都是自己一個人用走的嗎?', `FemaleText_loc7`='¿Sueles recorrer estos caminos solo?' WHERE `ID`=46279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 내가 젊었을 때는 이 길도 지나다니기 쉬웠었지. 요즘은 더 조심해야 한다오.', `MaleText_loc4`='嗯，是的，不过在我年轻时更容易些。这些日子我得加倍小心才行。', `MaleText_loc5`='是的。年輕的時候是沒什麼難，但現在，我就得多小心了。', `MaleText_loc7`='Sí, en efecto, aunque era más fácil cuando era joven. Hoy en día debo tener más cuidado.' WHERE `ID`=46280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실례가 되지 않는다면 알려주세요. 무슨 일을 하시기에 그렇게 많이 걸어 다니시죠?', `MaleText_loc4`='要是你不介意的话——我很好奇，你是做什么的，需要走那么多路？', `MaleText_loc5`='請容我好奇問一下，你是做什麼的，怎麼會需要走這麼多的路呢?', `MaleText_loc7`='Si se puede saber, ¿a qué te dedicas para que te haga falta andar tanto?' WHERE `ID`=46281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 은빛십자군의 탑 다섯 곳을 관리한다오. 대부분은 수리하고 정비하는 일이고, 마법도 약간 사용하지.', `MaleText_loc4`='我负责照看五座银色塔楼。主要就是修理和维护之类的，有时还涉及一些简单的魔法工作。', `MaleText_loc5`='我負責巡視銀白十字軍的那五座塔，清潔維修之類的，還有一些簡單的魔法。', `MaleText_loc7`='Mantengo las cinco torres Argenta. Reparaciones y mantenimiento, más que nada, y algún trabajo mágico.' WHERE `ID`=46282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적절히 보살펴 주지 않으면, 역병지대의 건물들은... 무너져 내리거든.', `MaleText_loc4`='要是照看不当的话，瘟疫之地的建筑就会……没入时间的洪流中。', `MaleText_loc5`='要是沒有好好照顧，瘟疫之地的建築物很容易就會...逐漸崩毀。', `MaleText_loc7`='Sin el cuidado adecuado, los edificios de las Tierras de la Peste tienden a... pudrirse.' WHERE `ID`=46283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀한 일이군요.', `MaleText_loc4`='真是高尚的工作。', `MaleText_loc5`='偉大的工作。', `MaleText_loc7`='Una noble tarea.' WHERE `ID`=46284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만족스러운 일이라오. 내 손으로 직접 일하는 게 난 언제나 즐겁더군.', `MaleText_loc4`='这让我很有满足感。我喜欢靠自己的双手工作。', `MaleText_loc5`='是還蠻有成就感的。我喜歡動動雙手親自做點事情。', `MaleText_loc7`='Lo encuentro satisfactorio. Me gusta trabajar con las manos.' WHERE `ID`=46285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말이 나왔으니 말인데, 수리할 물건이 있으면 내게 말해주시오. 도와줄 수 있으니까.', `MaleText_loc4`='顺便说一句——要是你们需要修理工的话，记得通知我。我随时愿意效劳。', `MaleText_loc5`='對了，要是你們有任何東西需要修理的話，請告訴我，我可以幫你們。', `MaleText_loc7`='Por cierto, si alguno de ustedes necesita que repare algo, díganmelo. Estoy a su servicio.' WHERE `ID`=46286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 아르거스 님도 은빛십자군의 일원이신가요?', `MaleText_loc4`='这么说来，你是银色黎明的成员咯？', `MaleText_loc5`='所以，你是銀白十字軍的人?', `MaleText_loc7`='Así que formas parte de la Cruzada Argenta, ¿eh?' WHERE `ID`=46287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희를 좀 추천해 주실 수 없으세요? 저희도 십자군에 들어가려 하고 있거든요.', `MaleText_loc4`='那也许你能为我们美言几句？我们正想加入这个组织。', `MaleText_loc5`='你可以幫我們美言幾句嗎?我們也想要加入。', `MaleText_loc7`='¿Crees que podrías recomendarnos? Tenemos intención de unirnos a la orden.' WHERE `ID`=46288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 나는 이제 희망의 빛 예배당에는 자주 들르지 않지만, 여러분이 거기 도착하거든 맥스 티로서스한테 내가 보냈다고 얘기하시오.', `MaleText_loc4`='没问题。虽然我现在不常去圣光之愿礼拜堂了，但你们到那儿之后，可以告诉玛克斯·泰罗索斯是我派你们去的。', `MaleText_loc5`='沒問題。雖然我已經很少去聖光之願了，但是你們到的時候可以跟麥斯·泰羅索斯說是我推薦你們的。', `MaleText_loc7`='Desde luego. Ya no voy a la Capilla de la Esperanza de la Luz muy a menudo, pero cuando lleguéis decidle a Max Neófitus que os envío.' WHERE `ID`=46289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야... 그 분과 서로 이름을 부를 만큼 친한 사이신가요?', `MaleText_loc4`='哇哦……他允许你叫他玛克斯？', `MaleText_loc5`='哇...他跟你這麼熟啊?', `MaleText_loc7`='¡Ah! ¿...te deja llamarle Max?' WHERE `ID`=46290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가씨, 날 저 앞에 있는 빛의 방패 경비탑에 내려줄 수 있겠소? 거기 잠깐 들러야 할 일이 있소.', `MaleText_loc4`='女士，你介意让我在圣光之盾哨塔那里下车吗？就在前面。我得在这儿停一下。', `MaleText_loc5`='女士，你方便在光盾哨塔那兒放我下車嗎?就在前面而已。我得在這裡下車。', `MaleText_loc7`='Señora, ¿te importa dejarme en la Torre del Escudo de la Luz, justo enfrente? Tengo que bajarme aquí.' WHERE `ID`=46291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 내려 드려야죠, 아르거스 님. 걱정하지 마세요, 일 마치실 때까지 기다려 드릴게요.', `FemaleText_loc4`='当然，我不仅会把你放下，海毕肯大人。我们还很乐意在这儿等你回来。', `FemaleText_loc5`='沒問題。我們不只願意放你下車，海畢肯先生。我們還很樂意繼續等你。', `FemaleText_loc7`='Claro que no voy a dejarte sin más, maestro Altofaro. Estaremos encantados de esperarte.' WHERE `ID`=46292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애애애! 또 쉬어 간다니!', `MaleText_loc4`='不——！又停车了！', `MaleText_loc5`='不不不!再停一次!', `MaleText_loc7`='¡NOOOOOO! ¡Nos hemos vuelto a parar!' WHERE `ID`=46293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망의 빛 예배당은 이제 얼마 남지 않았소, 젊은 성기사. 한번 걸어가 보는 건 어떻겠소?', `MaleText_loc4`='圣光之愿礼拜堂就在前面了，年轻的圣骑士。介意步行吗？', `MaleText_loc5`='聖光之願並不遠，年輕的聖騎士。我們用走的好嗎?', `MaleText_loc7`='La Esperanza de la Luz está cerca, joven paladín. ¿Te puedo sugerir ir andando?' WHERE `ID`=46294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸어간다고요...?', `MaleText_loc4`='步行，呃……？', `MaleText_loc5`='用走的，呃...?', `MaleText_loc7`='¿Andando, eh...?' WHERE `ID`=46295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈을 그렇게 보내다니, 정말 믿을 수 없어!', `MaleText_loc4`='我真不敢相信我竟然让吉德文跑了！', `MaleText_loc5`='我不敢相信，我竟然讓基德溫就那樣跑掉了!', `MaleText_loc7`='¡No me puedo creer que Gidwin haya echado a correr de tal forma!' WHERE `ID`=46296;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 잘못이 아니야, 타레나. 기드윈이 스스로 간 거야. 아무도 막을 수 없었어.', `FemaleText_loc4`='这不是你的错，塔伦纳。是他自己要跑的。我们谁都阻止不了他。', `FemaleText_loc5`='不是你的錯，塔瑞納爾。他是自己跑掉的，我們沒有人可以阻止他。', `FemaleText_loc7`='No es culpa tuya, Tarenar. Se ha ido por su propia voluntad. No podíamos detenerlo.' WHERE `ID`=46297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈이 죽었다고 확신할 수는 없소. 그냥 어딘가로 떠나버린 걸지도 모르지 않소.', `MaleText_loc4`='我们不能确定他是不是被杀了。也许只是跑到别处去了。', `MaleText_loc5`='我們無法確定他已經被殺。說不定他只是跑去了哪個地方而已。', `MaleText_loc7`='No podemos estar seguros de que lo hayan matado. A lo mejor se ha escapado a algún sitio.' WHERE `ID`=46298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다, 이 기도서 없이 떠날 녀석이 아니라고요! 항상 이 책에 얼굴을 묻고 공부했었거든요.', `MaleText_loc4`='不，他决不会丢下自己的祈祷书。他总是把脸埋在那本书里，学个没完。', `MaleText_loc5`='不，他絕對不會丟下他的祈禱書!他隨時隨地都在研究閱讀那本書。', `MaleText_loc7`='No, ¡nunca se dejaría su libro de oraciones! Siempre estaba ensimismado con ese libro, estudiando.' WHERE `ID`=46299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 공부하고, 그렇게 더 뛰어난 사람이 되려고 노력했었어요.', `MaleText_loc4`='他总是在学习，总是想要变得更好。', `MaleText_loc5`='他一直都在讀，一直在努力要變得更好。', `MaleText_loc7`='Siempre estaba estudiando, siempre intentaba mejorar.' WHERE `ID`=46300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 더더욱 그가 아직 살아 있다고 생각해야 하겠군.', `MaleText_loc4`='那我们更有理由相信，他还活着。', `MaleText_loc5`='所以我們更有理由相信他人還活著。', `MaleText_loc7`='Más razón para creer que sigue vivo.' WHERE `ID`=46301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기드윈과 같은 성기사라면 죽음의 기사가 되어서도 능력을 발휘할 수 있소. 그를 제압할 정도의 스컬지라면 그 사실을 잘 알고 있겠지.', `MaleText_loc4`='像吉德文那样的圣骑士绝对是死亡骑士的好胚子。天灾军团任何强大到足以将他击败的成员都会看出这一点。', `MaleText_loc5`='像基德溫這樣的聖騎士正是死亡騎士的最佳人選。任何有本事擊敗他的天譴軍團的成員都應該知道這點。', `MaleText_loc7`='Un paladín como Gidwin sería un valioso caballero de la Muerte. Cualquier miembro de la Plaga lo bastante fuerte para derrotarlo lo sabría.' WHERE `ID`=46302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딘가에 잡혀 있을 가능성이 크군. 죽음의 의식을 기다리면서 말이야.', `MaleText_loc4`='他很有可能就被囚禁在某处，等待死亡仪式的开始。', `MaleText_loc5`='很可能他被困在某處了，等著準備進行死亡儀式。', `MaleText_loc7`='Seguro que lo retienen en algún lado, esperando un ritual de muerte.' WHERE `ID`=46303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말인가요? 어쩜, 좋은 소식이네요!', `FemaleText_loc4`='真的？这可是天大的好消息！', `FemaleText_loc5`='真的?真是好消息!', `FemaleText_loc7`='¿En serio? ¡Es una buena noticia!' WHERE `ID`=46304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 사실은 몹시 나쁜 소식이에요. 하지만 반대의 경우를 생각해 보면...', `FemaleText_loc4`='嗯，事实上，这是个相当坏的消息，不过总比死了好……', `FemaleText_loc5`='呃，其實這應該是很壞的消息才對。但好歹人還沒死...', `FemaleText_loc7`='Bueno, es una noticia bastante mala, pero teniendo en cuenta las alternativas...' WHERE `ID`=46305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 이 길로 가야 그를 찾을 수 있을 것 같소. 스트라솔름이나 역병숲으로 끌려갔을 가능성이 크니까.', `MaleText_loc4`='我们要是想要找到他，朝这个方向前进就对了。他很可能被带去了斯坦索姆，或是病木林。', `MaleText_loc5`='我們得先找出正確的方向才有可能找到他。他很可能是被帶到斯坦索姆，或者病木林去了。', `MaleText_loc7`='Si queremos encontrarlo, vamos en la dirección correcta. Lo más probable es que se lo llevaran a Stratholme, o posiblemente al Bosque de la Peste.' WHERE `ID`=46306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 모두 사악한 악의 힘이 깃든 장소지. 나도 들어가기를 가장 꺼리는 곳이고.', `MaleText_loc4`='这两个地方都被强大的邪恶气息所笼罩。是我最不愿意去的地方。', `MaleText_loc5`='那兩個都是很邪惡的地方，也是我最不想去的地方。', `MaleText_loc7`='Ambos son lugares de gran maldad. Esta es la parte de mi trayecto que más temo.' WHERE `ID`=46307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 혼자 들어갈 수 있을지 모르겠어요.', `MaleText_loc4`='我不确定我是否已经做好了只身一人进去的准备。', `MaleText_loc5`='我不曉得我有沒有辦法獨自進去。', `MaleText_loc7`='No sé si estoy preparado para entrar solo.' WHERE `ID`=46308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 혼자가 아냐, 타레나. 지금까지처럼 우리가 힘을 보태줄 테니까. 게다가 너도 꽤 실력 있는 성기사잖아.', `FemaleText_loc4`='你不是只身一人，塔伦纳。你一路上结交了许多盟友。除此之外，你自己本身就是个技艺高超的圣骑士。', `FemaleText_loc5`='你並不是一個人，塔瑞納爾，你已經結識了好幾位夥伴。況且，你本身就是個優秀的聖騎士。', `FemaleText_loc7`='No estás solo, Tarenar. Has encontrado aliados por el camino. Además, tú mismo eres un paladín muy capaz.' WHERE `ID`=46309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가? 실력이 있다고? 아냐, 절대 아냐. 기드윈은 꽤 괜찮은 성기사였어. 매일 밤늦게까지 연습하느라 잠을 설쳤던 것도 그 녀석이었잖아...', `MaleText_loc4`='我，技艺高超？不，不，吉德文才是个出色的圣骑士。他每天夜里都不眠不休地苦苦操练……', `MaleText_loc5`='優秀，我?不、不、不，基德溫才是個優秀的聖騎士。他才是每天晚上都熬夜好幾個鐘頭在練習的人...', `MaleText_loc7`='¿Yo, capaz? No, no, Gidwin era el paladín bueno. Él era el que se pasaba las noches en vela, entrenando...' WHERE `ID`=46310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 하지만 너도 항상 걔를 따라잡았잖아. 연습도 하지 않고 말이야.', `FemaleText_loc4`='……可你却能始终与他齐头并进。在没有操练的情况下。', `FemaleText_loc5`='...但是一直追上他程度的人卻是你。而且不必苦練。', `FemaleText_loc7`='...pero tú eras el que le seguía el ritmo constantemente. Sin entrenar.' WHERE `ID`=46311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 둘 싸우는 모습을 봤었어, 타레나. 넌 천부적인 재능이 있어. 기드윈은 아무리 연습해도 따라갈 수 없는 재능.', `FemaleText_loc4`='你们两个的战斗技艺我都见过，塔伦纳。你有着与生俱来的天赋——在这一点上，吉德文永远也赶不上你。', `FemaleText_loc5`='我看過你們兩個互相比劃，塔瑞納爾。你有一種天生的本事--你遠遠勝過基德溫。', `FemaleText_loc7`='Os he visto luchar a los dos, Tarenar. Tienes un talento natural, uno mayor del que Gidwin tendrá jamás.' WHERE `ID`=46312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 그게 자넬 떼어놓고 떠난 이유인지도 모르겠군.', `MaleText_loc4`='也许这就是他独自离去的原因。', `MaleText_loc5`='也許那正是他之所以自己一個人離開的緣故。', `MaleText_loc7`='Quizá por eso se fue sin ti.' WHERE `ID`=46313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말씀이세요?', `MaleText_loc4`='你的意思是？', `MaleText_loc5`='你這話是什麼意思?', `MaleText_loc7`='¿A qué te refieres?' WHERE `ID`=46314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 기드윈이 자기도 자네만큼 재능이 있음을 증명하고 싶었는지도 모르겠다는 말이오.', `MaleText_loc4`='也许他觉得自己需要证明，他和你一样天赋异禀。', `MaleText_loc5`='也許他需要證明自己也跟你一樣有天份。', `MaleText_loc7`='Quizá pensaba que debía demostrar que tenía tanto talento como tú.' WHERE `ID`=46315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 제 잘못이에요. 기드윈을 찾아야 해요. 찾아서 오해를 풀어야 한다고요.', `MaleText_loc4`='这一切都是我的错。我必须找到他，弥补这些过失。', `MaleText_loc5`='這一切都是我的錯。我一定得找到他，好好解決這件事情。', `MaleText_loc7`='Es todo culpa mía. Tengo que encontrarlo, tengo que arreglarlo todo.' WHERE `ID`=46316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 잘못이라고 할 수는 없네, 타레나. 하지만 기드윈을 구해야 한다는 말에는 동의하지.', `MaleText_loc4`='我不认为这是你的错，塔伦纳。可我不会阻止你去救吉德文。', `MaleText_loc5`='我不認為那是你的錯，塔瑞納爾。但是別讓那阻礙你拯救基德溫的決心。', `MaleText_loc7`='Yo no diría que sea culpa tuya, Tarenar, pero no dejes que eso te impida salvar a Gidwin.' WHERE `ID`=46317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 가지만 확실히 하지, $r. 내가 여기 있는 이유는 단 하나뿐이다. 초갈을 없애는 것이지!$B$B네가 할 일은 놈이 궁극의 무기를 완성하지 못하게 하는 것이다. 예상컨대 그 무기는 고대 신의 힘이 담긴 유물일 것이다.', `FemaleText_loc4`='我们别拐弯抹角了，$r。我来这儿的目的只有一个——那就是消灭古加尔！$B$B你的任务就是阻止他造出终极武器。那可能是个灌注了上古之神力量的强大神器。', `FemaleText_loc5`='讓我們把話講清楚，$r。我在這兒的目標只有一個:殺掉丘加利!$B$B而你的工作則是要阻止他完成他的終極武器。那應該使是用上古之神的力量所創造出來的強大法器。', `FemaleText_loc7`='Quiero dejar clara una cosa, $r. Solo he venido con un objetivo: ¡matar a Cho''gall!$b$bTu trabajo es impedir que termine la creación de su arma definitiva. Es un artefacto que supuestamente se está creando con el poder de un dios antiguo.' WHERE `ID`=46318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 안에서 고대 신의 힘이 담긴 유물, 일종의 무기가 하나 제작되고 있습니다. 그게 무엇인지 정확히는 모르나, 초갈이 무기를 완성하기 전에 어떻게든 저지해야 합니다.$B$B이 일보다 중요한 건 하나도 없습니다. 어떤 희생이 있더라도 성공해야 합니다. 심지어 당신과 내가 희생된다고 하더라도요.', `MaleText_loc4`='有个神器——那是种武器，正在被注入上古之神的力量。我们不知道它究竟在哪儿，可我们必须赶在古加尔完成之前找到它。$B$B其它任何事都是次要的。任何人的生命都是可以牺牲的，包括你和我。', `MaleText_loc5`='有一件法器，一種武器，是用上古之神的力量鑄造出來的。我們不清楚它到底是什麼，但是我們必須在丘加利完成它之前弄到它。$B$B所有其他的事情都不重要，所有人的性命都可以犧牲，包括你和我。', `MaleText_loc7`='Hay un artefacto, un arma, que se está forjando con el poder de un dios antiguo. No sabemos qué es exactamente, pero tenemos que alcanzarlo antes de que Cho''gall lo complete.$b$bTodo lo demás es secundario. Todo el mundo es prescindible, incluidos tú y yo.' WHERE `ID`=46319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 폐허에서 하늘을 날 땐 조심하십시오. 황혼의 비룡은 날아다니는 사냥감을 특히 좋아하더군요.', `MaleText_loc4`='在这片废墟上空飞行可要多加小心，$g年轻人:小姑娘;。暮光飞龙尤其喜欢会飞的东西。', `MaleText_loc5`='飛到這片遺跡上空的時候要特別提高警覺，$g小夥子:小姑娘;。暮光飛龍特別喜歡咬會飛的東西。', `MaleText_loc7`='No te recomiendo sobrevolar estas ruinas, $gchaval:chavala;. A los dracos Crepusculares les gustan las cosas que vuelan.' WHERE `ID`=46320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화 작업을 시작합니다...', `MaleText_loc4`='净化程序启动……', `MaleText_loc5`='開始進行淨化程序...', `MaleText_loc7`='Comenzando secuencia de descontaminación...' WHERE `ID`=46323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화 작업 완료. 운반 대기 중입니다.', `MaleText_loc4`='净化已完成。等待送交。', `MaleText_loc5`='淨化完畢。準備運送。', `MaleText_loc7`='Descontaminación completada. Esperando entrega.' WHERE `ID`=46324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고, 시스템이 과열되었습니다. 곧 작동을 정지합니다!', `MaleText_loc4`='警告，系统已过载。故障即将发生！', `MaleText_loc5`='警告。系統超載。即將故障!', `MaleText_loc7`='Aviso: sobrecarga del sistema. ¡Fallo inminente!' WHERE `ID`=46325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다!', `MaleText_loc4`='是，是！', `MaleText_loc5`='哎，哎!', `MaleText_loc7`='¡Sí, señor!' WHERE `ID`=46326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 불태워 재로 만드리라!', `MaleText_loc4`='全都烧成灰烬！', `MaleText_loc5`='把他們全部燒成灰!', `MaleText_loc7`='¡Reduci''los a cenizas!' WHERE `ID`=46327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아! 불꽃놀이 할 시간이다!', `MaleText_loc4`='点燃引线，兄弟们！', `MaleText_loc5`='夥伴們，點燃引信!', `MaleText_loc7`='¡Quema'' las mechas, muchachos!' WHERE `ID`=46328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 보물이 해적의 가장 친한 친구인지 보여주지!', `MaleText_loc4`='我们要让你知道，为什么财宝是海盗最好的朋友！', `MaleText_loc5`='我們會讓你知道，寶藏為什麼是海盜最好的朋友!', `MaleText_loc7`='¡Vamos a enseña''os por qué un tesoro es el mejo'' amigo de un pirata!' WHERE `ID`=46329;
