UPDATE `locales_broadcast_text` SET `MaleText_loc1`='읔! 더러운 바다 쥐새끼 같으니라고, 내 보물 앞에서 썩 사라져!', `MaleText_loc4`='呃！离我的宝贝远点儿，你这龌龊的海老鼠！', `MaleText_loc5`='哎!臭海賊，離我的寶藏遠一點!', `MaleText_loc7`='¡Eh! ¡No le ponga'' las manos encima a mi tesoro, apeh''tosa rata marina!' WHERE `ID`=46337;
