UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼간이 같은 초갈에게 그렇게 성스러운 임무를 맡긴 우리가 바보였지! 침입자 놈들아, 내가 직접 상대해 주마!', `FemaleText_loc4`='把如此神圣的使命交给古加尔那种傻瓜真是太蠢了！我会亲自解决你们这些入侵者！', `FemaleText_loc5`='我們把這神聖的使命交給丘加利真是個大錯誤!我會自己收拾你們這些入侵者!', `FemaleText_loc7`='¡Qué tontos fuimos al confiar este deber sagrado al imbécil de Cho''gall! ¡Yo me encargaré de ustedes!' WHERE `ID`=46340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 위생로봇이... 내 자랑거리였는데!', `MaleText_loc4`='不，别碰净化者……那是我的骄傲与乐趣所在！', `MaleText_loc5`='不...自動清潔機...它是我的驕傲和喜悅啊!', `MaleText_loc7`='No, el Sanitron no... ¡Era mi orgullo!' WHERE `ID`=46341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으! 또 이곳이야, 또! 다음 구조대에서는 새로운 장소를 배정해달라고 해야지...', `MaleText_loc4`='啊！我可不要再这样了！我已经提出请求，要参加下一次的探险……', `MaleText_loc5`='呃啊!又來了!下次的行動我一定要申請個新的工作站台...', `MaleText_loc7`='¡Agh! ¡Otra vez no! La próxima expedición voy a pedir un nuevo destino...' WHERE `ID`=46342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 새끼들이 배불리 먹겠군!', `FemaleText_loc4`='我的孩子们会啃光你们的骨头！', `FemaleText_loc5`='我的孩子們會以你們的骨頭為糧食!', `FemaleText_loc7`='¡Mi linaje se comerá sus huesos!' WHERE `ID`=46343;
