UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거 짜증 나는군. 주위를 둘러보아라. 내 알이 보이느냐? 내 그들에게 생명력을 불어넣었지. 하지만 그 힘은 나의 것이며, 내 뜻대로 사용할 수 있다. 이제 너희가 상상도 할 수 없는 힘을 보여주마!', `FemaleText_loc4`='我已经厌倦了。看见你们立足的这片巢群了吗？我的力量正是滋养它们的活力。但这些生命力量永远属于我。面对这超越认知的力量吧！', `FemaleText_loc5`='我不耐煩了。看到在你們旁邊的這個巢穴了嗎?裡面的火花是我孕育的，但那個生命能量永遠都是屬於我的。看清楚了，這種超出你理解能力的力量!', `FemaleText_loc7`='Me harté. ¿Ven esa garra donde se paran? He nutrido la chispa en su interior, pero esa fuerza vital siempre será mía. ¡Vean, poder que jamás comprenderán!' WHERE `ID`=46345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 근데 누가 진짜지?', `MaleText_loc4`='啊，可哪个才是真的？', `MaleText_loc5`='啊，但是哪一個才是真的咧?', `MaleText_loc7`='Ah, ¿pero cual e'' el verdadero?' WHERE `ID`=46346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 가엽군요. 분명히 많이 지쳤을 겁니다.$B$B저기 음식과 음료가 있으니 가져다 드십시오. 그리고 이곳은 편안히 쉴 수 있을 만큼 안전합니다.', `MaleText_loc4`='我可怜的宝贝儿，你一定累坏了。$B$B这儿有食物和饮料，要是你愿意的话，可以放心地在这儿休息。', `MaleText_loc5`='可憐的人，你一定累壞了。$B$B如果你需要，我們這有食物和水，也可在這休息，這是安全的。', `MaleText_loc7`='Pobre cosita, tienes que estar $gagotado:agotada;.$B$BSi quieres, ahí hay comida y bebida, y es seguro descansar aquí.', `FemaleText_loc1`='가엽기도 해라. 분명히 많이 지쳤을 거예요.$B$B저기 음식과 음료가 있으니 가져다 드세요. 그리고 이곳은 편안히 쉴 수 있을 만큼 안전하답니다.', `FemaleText_loc4`='我可怜的宝贝儿，你一定累坏了。$B$B这儿有食物和饮料，要是你愿意的话，可以放心地在这儿休息。', `FemaleText_loc5`='可憐的人，你一定累壞了。$B$B如果你需要，我們這有食物和水，也可在這休息，這是安全的。', `FemaleText_loc7`='Pobre cosita, tienes que estar $gagotado:agotada;.$B$BSi quieres, ahí hay comida y bebida, y es seguro descansar aquí.' WHERE `ID`=46348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹을 걸 찾으십니까, $c님?$B$B아니면 지친 뼈를 잠시 쉬게 할 곳이라도?', `MaleText_loc4`='想吃点儿什么吗，$c？$B$B还是你只想找个地方放松一会儿？', `MaleText_loc5`='想吃點東西嗎，$c?$B$B還是只想歇歇你一身的累骨頭?', `MaleText_loc7`='¿Buscas algo para comer, $c?$B$B¿O tan solo un lugar donde descansar un rato tus cansados huesos?', `FemaleText_loc1`='먹을 걸 찾으시나요, $c님?$B$B아니면 지친 뼈를 잠시 쉬게 할 곳이라도?', `FemaleText_loc4`='想吃点儿什么吗，$c？$B$B还是你只想找个地方放松一会儿？', `FemaleText_loc5`='想吃點東西嗎，$c?$B$B還是只想歇歇你一身的累骨頭?', `FemaleText_loc7`='¿Buscas algo para comer, $c?$B$B¿O tan solo un lugar donde descansar un rato tus cansados huesos?' WHERE `ID`=46349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런, 누가 여기 왔다니 반갑군! 여긴 지금 미쳐 돌아가고 있어! 평소보다 더!', `MaleText_loc4`='喔伙计，终于有人来了！这下面简直疯狂透顶！比疯狂还要疯狂！', `MaleText_loc5`='哦，天啊，我真是太高興這裡有人了!下面那邊真是有夠瘋狂的!比平常更瘋狂!', `MaleText_loc7`='¡Oh, vaya, me alegro de que haya alguien aquí! ¡Las cosas están muy MAL ahí abajo! ¡Peor de lo normal!' WHERE `ID`=46350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼... 이 세상은... 내 것이다...', `MaleText_loc4`='不……这个世界……属于我……', `MaleText_loc5`='不...世界...是我的...', `MaleText_loc7`='No... el mundo e''... mío...' WHERE `ID`=46352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 중립을 지키는 유명한 스팀휘들 무역회사를 대표해 수렁진흙탕에 온 걸 환영해! 우린 동부 왕국에서 해변 휴양지와 군대급 무기를 동시에 갖춘 유일한 회사지.$B$B남쪽에서는 사소한 전쟁이 일어나고 있을지 모르지, 하지만 이 벽 안은 재미와 여흥밖에 없어. 그러니 긴장 풀라고. 푹 쉬면서 술이나 한 두잔 걸치되 사고는 치지 말고 지내... 아니면 우리 투사들이 "중립 지역"의 뜻을 머리통에 확실히 새겨줄 테니까.', `MaleText_loc4`='我仅代表卓绝而永保中立的热砂集团——欢迎来到沼桨镇！我们是东部王国独一无二的滨海度假胜地与军用武器补给港。$B$B也许你们这些家伙刚刚在南面不远处经历了战火的洗礼，可在这围墙之内，只有欢声笑语。忘了肩头的重担吧，来歇会儿，喝上两杯，但切记别找麻烦……否则我这儿的彪悍卫兵会让你们明白什么叫做“中立地域”。', `MaleText_loc5`='謹代表名聲卓越而且永遠中立的熱砂企業，歡迎你來到沼槳!我們是東部王國唯一的濱海休閒勝地兼軍武級兵工廠。$B$B雖然往南不遠你們還在打仗，但是這圈圍牆裡頭就只有遊戲和歡笑。放鬆心情，度個小假，喝杯小酒，然後不要惹麻煩...否則我的保鏢們就會提醒你「中立領土」是什麼意思。', `MaleText_loc7`='En nombre del ilustre y siempre neutral Cártel Bonvapor, ¡$gbienvenido:bienvenida; a Chapaleos! Nos enorgullecemos de ser el único complejo de vacaciones en la playa y almacén de armamento militar de los Reinos del Este.$b$bUstedes tendrán su guerra dando ídem en el sur, pero tras estos muros todo es fiesta y diversión. Así que date un respiro, descansa un poco, tómate una copa o dos y no te metas en líos... O mis truhanes le recordarán a tu cráneo lo que significa "territorio neutral".' WHERE `ID`=46353;
