UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동 전문 기계공학자 토르벤 잽블라스트입니다!', `MaleText_loc4`='托尔本·光爆，传送应对方案工程师为您效劳！', `MaleText_loc5`='全方位傳送解決方案工程師托爾班·速轟，在此為您服務!', `MaleText_loc7`='Torben Pumzas: ¡ingeniero de soluciones de teletransporte a tu servicio!' WHERE `ID`=46358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_hunter_mastermarksman.blp:20|t%s|1이;가; |cFFFF0000$n|r에게 시선을 고정하고|cFFFF0000|Hspell:79501|h [목표 설정]|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_hunter_mastermarksman.blp:20|t%s注视着|cFFFF0000$n|r开始施放|cFFFF0000|Hspell:79501|h [获取目标]！|r', `MaleText_loc5`='|TInterface\\Icons\\ability_hunter_mastermarksman.blp:20|t%s雙眼緊緊盯著|cFFFF0000$n|r並且開始準備|cFFFF0000|Hspell:79501|h [鎖定目標]!|r', `MaleText_loc7`='|TInterfaceIconsability_hunter_mastermarksman.blp:20|t¡%s fija la mirada en |cFFFF0000$n|r y comienza a lanzar|cFFFF0000|Hspell:79501|h [Adquiriendo objetivo]!|r' WHERE `ID`=46359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지상으로 보내주십시오, 토르벤.', `MaleText_loc4`='送我回到地表，托尔本。', `MaleText_loc5`='送我到地面，托爾班。', `MaleText_loc7`='Envíame a la superficie, Torben.', `FemaleText_loc1`='지상으로 보내주세요, 토르벤.', `FemaleText_loc4`='送我回到地表，托尔本。', `FemaleText_loc5`='送我到地面，托爾班。', `FemaleText_loc7`='Envíame a la superficie, Torben.' WHERE `ID`=46360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여기 상자 안에 소인족이 두 명 들어갔잖아. 이제 둘 사이의 공간을 노리고 조심스럽게 상자를 잘라버리기만 하면 되는 거야.', `MaleText_loc4`='好的，现在盒子里已经装了两个俾格米人。你要做的就是小心劈砍，对准他们之间的空隙。', `MaleText_loc5`='好，箱子裡面躲了兩個小俾格米。簡單來講，你只要小心一點，瞄準他們中間的空隙砍下去就好了。', `MaleText_loc7`='Vale, tienes dos pigmeos en la caja. Ahora solo tienes que cortarla con cuidado, apuntando al espacio que hay entre los dos.' WHERE `ID`=46361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게요?', `MaleText_loc4`='像这样？', `MaleText_loc5`='就像這樣?', `MaleText_loc7`='¿Así?' WHERE `ID`=46362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아니지! 멋이 없잖아? 동작을 큼지막하게 해야 한다고!', `MaleText_loc4`='不，不！你怎么一点表现力都没有？要讲究舞台艺术！', `MaleText_loc5`='不對，不對!你的劍術到底練到那邊去了?太誇張了!', `MaleText_loc7`='¡No, no! ¿No tienes sentido del espectáculo? ¡Un poco de teatro!' WHERE `ID`=46363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 힘을 다해서! 상자를 정말 반으로 쪼개! 이렇게!', `MaleText_loc4`='要运用你的力量！真真正正地把这箱子劈成两半，看好了！', `MaleText_loc5`='多用點力氣!把那個箱子打成兩半，看好啦!', `MaleText_loc7`='¡Ponle toda tu fuerza! ¡Parte esa caja por la mitad, mira!' WHERE `ID`=46364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아아아압!', `MaleText_loc4`='GWAAAAAAAAAAAAH！', `MaleText_loc5`='呃啊啊啊啊啊!', `MaleText_loc7`='¡YIAAAAAAAA!' WHERE `ID`=46365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 혹시 지금...?', `MaleText_loc4`='你刚才……？', `MaleText_loc5`='你剛剛是不是..?', `MaleText_loc7`='¿Acabas de...?' WHERE `ID`=46366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그런 것 같은데.', `MaleText_loc4`='嗯，我想是的。', `MaleText_loc5`='我想是的。', `MaleText_loc7`='Sí, creo que sí.' WHERE `ID`=46367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이런...', `MaleText_loc4`='喔……我的天……', `MaleText_loc5`='哦...哦...天啊...', `MaleText_loc7`='Ay... Ay madre...' WHERE `ID`=46368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소인족이 몇 명 더 필요하겠네.', `MaleText_loc4`='看来我们得再找几个俾格米人了。', `MaleText_loc5`='看來我們得再去找幾個俾格米了。', `MaleText_loc7`='Creo que vamos a necesitar más pigmeos.' WHERE `ID`=46369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문 사이의 행동 트리거를 위해 경로를 매끄럽게 만드는 시험입니다.', `MaleText_loc4`='动作触发间隙法术平滑测试。', `MaleText_loc5`='我是個動作觸發器的路徑平滑化測試，中間插入法術。', `MaleText_loc7`='I am a path smoothing test for action trigger splines with spells inbetween.' WHERE `ID`=46370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이벤트 사이의 행동 트리거를 위해 경로를 매끄럽게 만드는 시험입니다.', `MaleText_loc4`='动作触发间隙事件平滑测试。', `MaleText_loc5`='我是個動作觸發器的路徑平滑化測試，中間插入事件。', `MaleText_loc7`='I am a path smoothing test for action trigger splines with events inbetween.' WHERE `ID`=46371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문 사이의 이벤트 생성을 위해 경로를 매끄럽게 만드는 시험입니다.', `MaleText_loc4`='事件生成间隙法术平滑测试。', `MaleText_loc5`='我是個生成事件的路徑平滑化測試，中間插入法術。', `MaleText_loc7`='I am a path smoothing test for spawn event splines with spells inbetween.' WHERE `ID`=46372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이벤트 사이의 이벤트 생성을 사용하는 연쇄 행동 시험입니다.', `MaleText_loc4`='事件生成间隙事件平滑测试。', `MaleText_loc5`='我是個使用生成事件的連鎖動作測試，中間插入事件。', `MaleText_loc7`='I am a chain actions test using spawn event splines with events inbetween.' WHERE `ID`=46373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와.$B$B소환수를 우리에 넣으러 온 거야? 아니면 잃어버린 동료를 찾으러 온 거야?', `MaleText_loc4`='你好啊。$B$B你是来存放宠物，还是在寻找失踪的同伴？', `MaleText_loc5`='呦。$B$B你是來寄放寵物的，還是來尋找失蹤的夥伴?', `MaleText_loc7`='Hey.$B$B¿Has venido a guardar a tus mascotas o buscas a un compañero perdido?', `FemaleText_loc1`='어서 와.$B$B소환수를 우리에 넣으러 온 건가? 아니면 잃어버린 동료를 찾으러 온 거야?', `FemaleText_loc4`='你好啊。$B$B你是来存放宠物，还是在寻找失踪的同伴？', `FemaleText_loc5`='呦。$B$B你是來寄放寵物的，還是來尋找失蹤的夥伴?', `FemaleText_loc7`='Hey.$B$B¿Has venido a guardar a tus mascotas o buscas a un compañero perdido?' WHERE `ID`=46374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와.$B$B잃어버린 동료를 찾으러 온 거야?', `MaleText_loc4`='你好啊。$B$B你是在寻找失踪的同伴？', `MaleText_loc5`='呦。$B$B你是要尋找失蹤的夥伴?', `MaleText_loc7`='Hey.$B$B¿Buscas a un compañero perdido?', `FemaleText_loc1`='어서 와.$B$B잃어버린 동료를 찾으러 온 거야?', `FemaleText_loc4`='你好啊。$B$B你是在寻找失踪的同伴？', `FemaleText_loc5`='呦。$B$B你是要尋找失蹤的夥伴?', `FemaleText_loc7`='Hey.$B$B¿Buscas a un compañero perdido?' WHERE `ID`=46375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 안전하게 지상으로 이동하면 더 여유롭게 이야기할 수 있을 겁니다.', `MaleText_loc4`='等我们安全回到地表之后，会有大把的时间供我们交谈。', `MaleText_loc5`='等我們安全回到地表之後，我們會有時間再好好談談。', `MaleText_loc7`='Tendremos tiempo para hablar cuando volvamos a la superficie sanos y salvos.' WHERE `ID`=46376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 둘, 어서 움직여. 일이 끝나려면 12통이 더 있어야 해!', `FemaleText_loc4`='你们两个快一点。在一切完成之前，我还想再装满十二只桶呢！', `FemaleText_loc5`='快點啊，你們兩個。還要再弄好十二桶我們才能收工!', `FemaleText_loc7`='Vamos, ustedes dos. ¡Quiero otra docena de barriles llenos antes de irnos!' WHERE `ID`=46377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 액체지만 돈이나 마찬가지야. 한 방울까지 모아와!', `FemaleText_loc4`='啊，液体黄金。每一滴都要收集好！', `FemaleText_loc5`='啊，液體黃金。一滴都不要漏掉!', `FemaleText_loc7`='Ah, oro líquido. ¡Reunid hasta la última gota!' WHERE `ID`=46378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아침에 풍겨오는 천연 그대로의 냄새가 좋아. 이 냄새, 아시겠지만, 시큼한 황 냄새가... 사방에 가득하거든요. 바로... 돈 냄새가 말이에요.', `FemaleText_loc4`='我喜欢早晨的这种清新气味。当然，就是这种硫磺的酸气……这里全都是这种气味。闻起来就像是……金钱的气味。', `FemaleText_loc5`='我最愛飄在清晨裡的原油氣味。那種味道，你知道的，帶點刺鼻的硫磺味...瀰漫整個地方。啊，聞起來就是...錢的味道。', `FemaleText_loc7`='Me encanta el olor a crudo por la mañana. Ese olor, ya sabes, como a azufre agrio... Todo este sitio. Huele a... beneficios.' WHERE `ID`=46379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물에서 통으로. 움직여! 시간은 금이라고. 다들 알면서.', `FemaleText_loc4`='来自于清水，被灌入桶中。赶快！时间就是金钱。', `FemaleText_loc5`='從水裡弄出來，裝進桶子裡。動作快!時間就是金錢，你知道的。', `FemaleText_loc7`='Del agua a los barriles. ¡Moveos! El tiempo es oro, ¿sabéis?' WHERE `ID`=46380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 바로 짭짤하다고 하는 일이지. 이봐! 거기 흘렸잖아.', `FemaleText_loc4`='这就是我所说的利润精华。嗨！你漏掉了一些，就在那里。', `FemaleText_loc5`='這才叫做大賺特賺啊。嘿!你漏掉了，在那邊。', `FemaleText_loc7`='¡A ESO le llamo recoger hasta el último beneficio! ¡EH! Te has dejado un poco por ahí.' WHERE `ID`=46381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 살아나가고 싶다면 저 방사능에 오염된 노움들의 공격을 돌파해야 합니다!', `MaleText_loc4`='如果我们要活着离开这里，就必须从这群无意识的麻疯侏儒中间冲过去！', `MaleText_loc5`='想要活著離開這裡，我們就得突破那些瘋狂的麻瘋地精!', `MaleText_loc7`='¡Tenemos que abrirnos paso entre esos gnomos parias si queremos salir vivos de aquí!' WHERE `ID`=46382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대원들의 마지막 순간이동 신호기를 가지고 생존자들을 놈리건 밖으로 내보내 주십시오. 도와주셔서 감사합니다. 저와 부하들은 우리 힘으로 이곳을 빠져나갈 수 있을 겁니다.', `MaleText_loc4`='拿上我们最后的传送信标，带这些幸存者离开这里。谢谢你帮助我们，我们应该能自己从这里冲杀出去。', `MaleText_loc5`='帶著小隊最後的傳送信標，送那些倖存者離開此處。感謝你的協助，我和手下應該有辦法從這裡殺出去。', `MaleText_loc7`='Coge la última baliza de teletransporte del escuadrón y saca de aquí a esos supervivientes. Gracias a tu ayuda, mis hombres y yo deberíamos poder salir de aquí luchando.' WHERE `ID`=46383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소. 나는 태더란 블러드워처라고 하오. 살아오면서 마법 수련에 많은 시간을 쏟았고, 비슷한 생각을 지닌 블러드 엘프를 모아 성물회를 조직했지.$B$B그대도 알다시피 이 세계에는 강력한 고대의 유물이 많이 흩어져 있소. 나는 이 유물들을 모아 동족을 중독에서 해방하고 규합해, 한때 그랬던 것처럼 자긍심 높은 불굴의 민족으로 재탄생시키려고 하오.$B$B마법은 배척할 게 아니라 받아들여야 하는 어떤 것이오. 그리고, 내 장담하건대 제대로 된 가르침만 있다면 타락할 염려 없이 마법의 힘을 사용할 수 있소.$B$B반쯤 파괴된 우리의 수도, 아직도 버젓이 서 있는 선스트라이더의 동상, 이 세계에서뿐만이 아니라 다른 세계에서도 거듭된 우리의 실수... 지금은 얼라이언스의 다른 종족은 물론 호드까지도 우리를 조롱하고 있소.$B$B더는 아니 되오.', `MaleText_loc4`='你好，我名叫泰瑟兰·血望者。我将一生中最好的时光都用来进行巫术的训练，并召集与我志同道合的血精灵，组成了神圣遗物学会。$B$B要知道，在这个世界的各个角落里埋藏着许多古老、强大的宝物。我打算利用这些宝物将我的族人从他们堕落的嗜好中解救出来，让他们重新团结为一体，成为往日那个光荣而坚强的种族。$B$B我可以向你保证，魔法是可以接触的。只要得到适当的教导，任何人都能使用这种力量并且免于因它而堕落。$B$B现在，联盟的各个种族，甚至是部落的人都在嘲笑我们遭受重创的首都，仍然矗立的逐日者雕像，和我们在世界各处一次又一次遭受的挫折。$B$B但这种情况不会再继续下去了。', `MaleText_loc5`='你好，我叫做泰瑟連·血腥看守者。我這一生都在致力於研習魔法，以及招募志同道合的血精靈成立「聖匣守護者」。$B$B你看，這個世界到處都埋藏著古老而強大的遺物，我計畫利用它們來戒除我們族人的成癮症狀，將他們重新統合為過去那個堅定而自豪的精靈族。$B$B我向你保證，只要透過適當的訓練，魔法絕對是值得擁抱的，同時也是個能夠不受腐化影響而施展的力量。$B$B現在我們的處境十分悲慘，聯盟的其他種族，甚至連部落，都在嘲笑我們半毀的首都，至今依然屹立的逐日者雕像，以及各地方一次又一次的挫敗。$B$B再也不會發生了。', `MaleText_loc7`='Saludos, me llamo Tae''thelan Mirasangre. Llevo casi toda una vida entrenándome en las artes de la hechicería y reuniendo a los elfos de sangre del mismo parecer para formar El Relicario.$b$bPor todo el mundo hay reliquias antiguas y poderosas que pienso usar para liberar a mi gente de su adicción y para unirlos de nuevo como la raza orgullosa e indómita que fuimos antaño.$b$bLa magia es algo que se debe asimilar, y una fuerza que se puede utilizar sin caer en la corrupción con la enseñanza adecuada.$b$bLas demás razas de la Alianza e incluso de la Horda se burlan de nosotros por nuestra capital medio en ruinas, las estatuas de Caminante del Sol que siguen en pie y un error tras otro por todo el mundo.$b$bSe acabó.' WHERE `ID`=46384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 도와주세요!', `MaleText_loc4`='请救救我！', `MaleText_loc5`='請幫幫我!', `MaleText_loc7`='¡Ayúdame, por favor!' WHERE `ID`=46385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 죽고 싶지는 않아요!', `MaleText_loc4`='我不想死在这里！', `MaleText_loc5`='我不想死在下面這裡!', `MaleText_loc7`='¡No quiero morir aquí abajo!' WHERE `ID`=46386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 저를 먹게 놓아두지 마세요!', `MaleText_loc4`='不要让它们吃掉我！', `MaleText_loc5`='不要讓他們把我吃了!', `MaleText_loc7`='¡No dejes que me coman!' WHERE `ID`=46387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 도와주세요! 누구라도 괜찮아요!', `MaleText_loc4`='有人吗！有人能救救我吗？！', `MaleText_loc5`='來人啊!救命啊!', `MaleText_loc7`='¡Que alguien me ayude!' WHERE `ID`=46388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 죽기에는 너무 젊단 말이에요!', `MaleText_loc4`='我还很年轻，还不想死！', `MaleText_loc5`='我還年輕，我不想死啊!', `MaleText_loc7`='¡Soy demasiado joven para morir!' WHERE `ID`=46389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 정말 이곳에서 죽고 말 거예요. 안 그래요?', `MaleText_loc4`='我真的要死在这里了吗？', `MaleText_loc5`='難道我真的得死在這下面了嗎?', `MaleText_loc7`='Voy a morir aquí abajo, ¿verdad?' WHERE `ID`=46390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요! 혼자 힘으로 빠져나가기에는 제가 너무 약해요!', `MaleText_loc4`='救命！我已经没力气了。', `MaleText_loc5`='救命啊!我沒力氣，沒辦法出去啊。', `MaleText_loc7`='¡Socorro! Estoy demasiado débil para salir por mí mismo.' WHERE `ID`=46391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀수업자의 흉터에서 나가 아다라에게 신호를 보내십시오.', `MaleText_loc4`='离开走私者洞穴，向埃达尔拉发信号', `MaleText_loc5`='離開走私者之痕去通報阿達拉', `MaleText_loc7`='Abandona la Cicatriz del Contrabandista para hacer señales a Adarrah.', `FemaleText_loc1`='밀수업자의 흉터에서 나가 아다라에게 신호를 보내십시오.', `FemaleText_loc4`='离开走私者洞穴，向埃达尔拉发信号', `FemaleText_loc5`='離開走私者之痕去通報阿達拉', `FemaleText_loc7`='Abandona la Cicatriz del Contrabandista para hacer señales a Adarrah.' WHERE `ID`=46392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 해마의 기분이 매우 안 좋은 것 같습니다.', `MaleText_loc4`='深渊海马看上去非常不高兴。', `MaleText_loc5`='深淵海馬似乎很不開心。', `MaleText_loc7`='El caballito de mar abisal parece muy descontento.' WHERE `ID`=46393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사테크!', `MaleText_loc4`='啊呀！', `MaleText_loc5`='Satekh!', `MaleText_loc7`='¡Satekh!' WHERE `ID`=46394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카데쉬!', `MaleText_loc4`='嘿呀！', `MaleText_loc5`='Kadesh!', `MaleText_loc7`='¡Kadesh!' WHERE `ID`=46395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오사디!', `MaleText_loc4`='啊哈！', `MaleText_loc5`='Osadi!', `MaleText_loc7`='¡Osadi!' WHERE `ID`=46396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='근처 잔해에서 구할 수 있는 걸 좀 가져왔지만, 여기에 머무르는 것도 한계가 있어요.', `FemaleText_loc4`='我把附近残骸里能抢救的东西都抢救出来了，现在我已经坚持不住了……', `FemaleText_loc5`='我已經盡力從附近的殘骸收集些東西來用，但是我也只能撐上那麼久而已...', `FemaleText_loc7`='He recuperado lo que he podido del naufragio cercano, pero solo puedo permanecer sumergida durante un tiempo limitado...' WHERE `ID`=46397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 무한히 감사드립니다.', `MaleText_loc4`='永远地感谢你。', `MaleText_loc5`='我對你永懷感謝。', `MaleText_loc7`='Tienes mi gratitud eterna.' WHERE `ID`=46398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단을 살려 두지 않겠습니다.', `MaleText_loc4`='还有暮光之锤的暴徒没消灭干净。', `MaleText_loc5`='還有好些暮光之錘要殺。', `MaleText_loc7`='Aún quedan miembros del Martillo Crepuscular por matar.' WHERE `ID`=46399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 노예가 아니다!', `MaleText_loc4`='我已经不再被奴役了！', `MaleText_loc5`='我自由了!', `MaleText_loc7`='¡Ya no soy un esclavo!' WHERE `ID`=46400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수의 시간이다, 필멸의 존재들아!', `MaleText_loc4`='现在是复仇的时候了，凡人们！', `MaleText_loc5`='復仇的時刻到了，凡人!', `MaleText_loc7`='¡Es la hora de la venganza, mortales!' WHERE `ID`=46401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 감사의 표시로 당신을 강화시켜 드렸습니다. 정말 감사합니다.', `MaleText_loc4`='这一点微小的礼物完全无法表达我的感激之情。谢谢你！', `MaleText_loc5`='謝謝你，這只是表現心意的一點小東西。', `MaleText_loc7`='No es más que una muestra de agradecimiento. Muchas gracias.' WHERE `ID`=46402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실례하겠습니다. 절 구속했던 놈들과 볼일이 좀 있어서요.', `MaleText_loc4`='请原谅，我得去和那些奴役我的家伙“谈谈”了。', `MaleText_loc5`='抱歉，我得去找抓我的人聊聊。', `MaleText_loc7`='Discúlpame. Tengo que hablar con ciertos antiguos captores.' WHERE `ID`=46403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 조그만 황혼의 이교도들아. 너희의 종말이 다가왔다!', `MaleText_loc4`='跑吧，渺小的暮光教徒们。你们的末日就要到了！', `MaleText_loc5`='跑吧，沒用的暮光教徒。你們的末日近了!', `MaleText_loc7`='Corran, pequeños cultores Crepusculares. ¡Su hora se acerca!' WHERE `ID`=46404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향에 돌아가기 전에 복수를 좀 즐겨야겠습니다.', `MaleText_loc4`='在我回家之前，还要进行一点小小的复仇。', `MaleText_loc5`='該是我回家前先報點仇的時候了。', `MaleText_loc7`='Es hora de un poco de venganza antes de volver a casa.' WHERE `ID`=46405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 이 고통을 너희에게도 맛보여 주겠다, $r.', `MaleText_loc4`='你们一族注定要承受这一切，$r。', `MaleText_loc5`='你們必將為此而遭受懲罰，$r。', `MaleText_loc7`='Tu raza sufrirá por esto, $r.' WHERE `ID`=46406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마귀들과 손을 잡으려는 것이냐? 언젠가 저들과 함께 너도 불태워 주마!', `MaleText_loc4`='你和这些魔鬼结盟了？你也将会有被焚毁的一天！', `MaleText_loc5`='你竟然和這些惡魔同謀?終有一天你也將被烈火吞噬!', `MaleText_loc7`='¿Te alías con estos monstruos? ¡Tú también arderás algún día!' WHERE `ID`=46407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<온몸에 상처를 입은 거대한 검은 비룡이 악의 넘치는 눈길로 당신을 내려다봅니다. 눈도 깜빡이지 않습니다.>', `MaleText_loc4`='<黑色的巨龙身上布满了伤口。他一直盯着你，眼睛里闪烁着凶恶的光芒。>', `MaleText_loc5`='<巨大的黑龍渾身是傷，目光兇狠地低頭盯著你，雙眼眨也不眨。>', `MaleText_loc7`='<El enorme draco negro, cubierto de heridas abiertas, te observa con ojos llenos de malicia. No parpadea.>' WHERE `ID`=46408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<흉포한 검은 비룡이 자신을 구속한 사슬을 잡아당깁니다. 거리를 유지하는 게 좋겠습니다.>', `MaleText_loc4`='<凶恶的黑色巨龙拼命扯拽着捆缚他的锁链。你最好还是离他远一些。>', `MaleText_loc5`='<兇猛的黑龍扯緊綁住它的鎖鍊。你最好別靠太近。>', `MaleText_loc7`='<El feroz draco negro tensa las cadenas que lo atan. Es mejor mantener las distancias.>' WHERE `ID`=46409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사슬로 날 영원히 구속할 수는 없다, $c|1이여;여;. 내가 놈들에게 복수할 때 네가 주변에 없기를 빌어라.', `MaleText_loc4`='我不可能永远困在这里，$c。你最好现在就祈祷，祈祷当我复仇的时候，你不会在我面前。', `MaleText_loc5`='禁錮我的枷鎖並非亙久不破，$c?你最好祈禱當我得以復仇的時候，你已不在近處。', `MaleText_loc7`='Las ligaduras que me atan no son permanentes, $c. Reza para no estar cerca cuando obtenga mi venganza.' WHERE `ID`=46410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용은 소나 돼지 같은 평범한 동물이 아니오. 용은 자연의 힘이요. 강력하고... 원초적인.$B$B용을 자신의 의지로 제어하는 것은 세상을 길들이는 것과 같지.$B$B그리고 그들의 고삐를 손에 쥐는 것은 운명을 손에 쥐는 것과 같소.', `MaleText_loc4`='龙并不是猪和牛那样简单的野兽。他们是一种自然的力量。强大……原始的力量。$B$B让他们服从你，就是要驾驭这个世界。$B$B能够支配他们，你也就支配了命运的力量。', `MaleText_loc5`='龍可不是尋常的牲畜野獸，他們象徵著原始而強大的自然之力。$B$B能夠馴服他們就等於駕馭了這個世界。$B$B能夠駕馭他們就等於把命運握在了你的手裡。', `MaleText_loc7`='Los dragones no son meras bestias, como los cerdos o el ganado. Son una fuerza de la naturaleza. Poderosos... Primigenios.$b$bSometerlos a tu voluntad es subyugar el mundo.$b$bTomar sus riendas es tener tu propio destino en tus manos.' WHERE `ID`=46411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 무역회사 전쟁 이후로 물약을 만들고 있어요. 조만간 그만둘 계획도 없고요.$B$B이 세상에 구매자가 남아 있는 한, 이 늙은 바바는 언제나 물약을 팔 준비가 되어 있어요.', `FemaleText_loc4`='自从这场企业联合战争开始以前，我就在进行各种药剂混合工作了。我现在并不打算停止这行当。$B$B只要还有买家，芭芭就不愁没生意做！', `FemaleText_loc5`='早在企業大戰之前我就一直在調配藥水，而且短期內我也沒打算就此收手。$B$B只要有人想買，我老巴巴隨時都有東西可賣!', `FemaleText_loc7`='Llevo mezclando pociones desde las guerras de cárteles, y no pienso parar ahora.$b$bMientras haya un comprador, ¡la vieja Baba tendrá unas rebajas listas!' WHERE `ID`=46412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화력이 엄청나더군. 어쩌면 이 조그만 꼬마 고블린도 보이는 것과는 달리 능력이 좀 있는 모양이오.', `MaleText_loc4`='他们的火力相当强劲。也许我们不应该小看那些地精矬子。', `MaleText_loc5`='這可真是強大的火力。看來這些小不隆咚的哥布林還真是不可貌相啊。', `MaleText_loc7`='Eso sí que ha sido potencia de fuego. A lo mejor estos pequeños goblins son más de lo que parecen.' WHERE `ID`=46413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해마가 미끼에 한눈이 팔린 틈을 타 해마에 올라타십시오!', `MaleText_loc4`='在海马分神的时候抓住它！', `MaleText_loc5`='趁海馬分心的時候抓住牠!', `MaleText_loc7`='¡Agarra el caballito de mar mientras está distraído!', `FemaleText_loc1`='해마가 미끼에 한눈이 팔린 틈을 타 해마에 올라타십시오!', `FemaleText_loc4`='在海马分神的时候抓住它！', `FemaleText_loc5`='趁海馬分心的時候抓住牠!', `FemaleText_loc7`='¡Agarra el caballito de mar mientras está distraído!' WHERE `ID`=46414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다, $n! 이제부터 물속 여행이 좀 더 쉬워질 것입니다.', `MaleText_loc4`='干得好，$n！相信从这里开始，你在波涛下的旅程将会变得更加顺畅。', `MaleText_loc5`='幹得好，$n!我想你接下來的海底之旅應該會平順多了吧。', `MaleText_loc7`='¡Bien hecho, $n! Supongo que a partir de ahora tus viajes bajo las olas serán mucho más suaves.' WHERE `ID`=46415;
