UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 가자, 제군들. 우리 마을을 되찾자!', `MaleText_loc4`='好了，孩子们，我们要夺回自己的家园！', `MaleText_loc5`='上啊，奪回我們的家園!', `MaleText_loc7`='¡Vamos, chicos, recuperemos nuestros hogares!' WHERE `ID`=46417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서로 좀 예의 바르게 굴 수도 있었을 텐데... 안타깝군요!', `FemaleText_loc4`='我们本可以用文明的手段解决这一问题，但我不打算这样！', `FemaleText_loc5`='我們是可以文明一點...但是我不要!', `FemaleText_loc7`='¡Podríamos haberlo resuelto de forma civilizada, pero no...!' WHERE `ID`=46418;
