UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장히 확신하시는군요.', `MaleText_loc4`='你看起来很笃定。', `MaleText_loc5`='你好像很肯定。', `MaleText_loc7`='Pareces muy seguro.', `FemaleText_loc1`='굉장히 확신하시는군요.', `FemaleText_loc4`='你看起来很笃定。', `FemaleText_loc5`='你好像很肯定。', `FemaleText_loc7`='Pareces muy seguro.' WHERE `ID`=46422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하지! 벌써 네 번이나 겪었는데.', `MaleText_loc4`='哦，$g小伙子:姑娘;！已经4次了。', `MaleText_loc5`='當然啦，$g小夥子:小姑娘;!我已經走過四次了。', `MaleText_loc7`='¡Oh, sí, $gmozo:moza;! Ya la he pasado 4 veces.' WHERE `ID`=46423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 겪고 싶다는 말씀으로 들리는데요...', `MaleText_loc4`='我以为你又要走了……', `MaleText_loc5`='然後我猜你又要再走一遍了...', `MaleText_loc7`='Y supongo que vas a volver...', `FemaleText_loc1`='다시 겪고 싶다는 말씀으로 들리는데요...', `FemaleText_loc4`='我以为你又要走了……', `FemaleText_loc5`='然後我猜你又要再走一遍了...', `FemaleText_loc7`='Y supongo que vas a volver...' WHERE `ID`=46424;
