UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 수 없군요. 그럼 가시죠.', `MaleText_loc4`='嗯，就这么干吧。', `MaleText_loc5`='好吧，那就走吧。', `MaleText_loc7`='Bueno, pues vamos a ello.', `FemaleText_loc1`='할 수 없군요. 그럼 가시죠.', `FemaleText_loc4`='嗯，就这么干吧。', `FemaleText_loc5`='好吧，那就走吧。', `FemaleText_loc7`='Bueno, pues vamos a ello.' WHERE `ID`=46426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그런 자세야!', `MaleText_loc4`='就是这种感觉！', `MaleText_loc5`='就是這樣!', `MaleText_loc7`='¡Ese es el espíritu!' WHERE `ID`=46427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 놈들에게 우리가 어떤 드워프인지 보여주자고. 얼마든지 오라고 해!', `MaleText_loc4`='没错，给他们点颜色瞧瞧。让他们来吧！', `MaleText_loc5`='沒錯，給他們點顏色瞧瞧，讓他們知道我們的厲害!', `MaleText_loc7`='¡Eso es, que se enteren de quienes somos. Dejad que vengan!' WHERE `ID`=46428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬리가 자네더러 날 끌고 오라고 했나 본데, 그냥 잊어버리라고. 난 저 황혼의 망치단 놈들을 혼내 줘야 하니까.', `MaleText_loc4`='如果是凯莉派你来抓我回去，那她可要失望了。这里还有许多暮光暴徒没消灭干净呢。', `MaleText_loc5`='如果是基莉派你來把我弄回去的，那就免了。還有暮光的傢伙要教訓。', `MaleText_loc7`='Si te ha enviado Keely para que me convenzas de que regrese, puedes ir olvidándote. Hay unos cuantos del Martillo Crepuscular que piden una paliza a gritos.' WHERE `ID`=46429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 금방 돌아가지, 젊은이. 아까우니까 딱 한 번만 더 하고...', `MaleText_loc4`='我很快就会回来的，$g小伙子:小姑娘;。为了能过上好日子，还得再走一趟。', `MaleText_loc5`='我很快就會回去啦，$g小夥子:小姑娘;。再一個就好，當作紀念。', `MaleText_loc7`='En breve me pondré en marcha de regreso, $gmuchacho:muchacha;. Una vez más por los viejos tiempos.' WHERE `ID`=46430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겨우 이 정도냐?!', `MaleText_loc4`='你就这点能耐？！', `MaleText_loc5`='你的本事就只有這樣?!', `MaleText_loc7`='¡¿Eso es todo lo que tenéis?!' WHERE `ID`=46431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케이든의 도끼가 네놈들 목을 기다리고 있다!', `MaleText_loc4`='凯登弄到了一把刻着你的名字的斧头！', `MaleText_loc5`='凱登已經磨好斧頭等著招呼你啦!', `MaleText_loc7`='¡Cayden tiene un hacha con tu nombre en ella!' WHERE `ID`=46432;
