UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많이 숨어 있는 거 다 알고 있다. 어서 나와!', `MaleText_loc4`='我知道，你们的小窟窿里还藏着你的同伙……', `MaleText_loc5`='我知道你們還有人躲在你們的小洞洞裡面...', `MaleText_loc7`='Sé que hay más de los suyos escondidos en esos pequeños agujeros...' WHERE `ID`=46434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 여긴 사방이 반짝이는 것들로 가득합니다!$b$b발굴 작업 중에 제가 뭘 발견했는지 보십시오...$b$b바로 수중 호흡 모자입니다!
', `MaleText_loc4`='哈！这个地方到处都是好东西！$b$b看看我在这里挖出了什么……$b$b一顶呼吸帽子！', `MaleText_loc5`='嗚呼!這裡到處都是亮亮!$b$b看看我在這裡挖到了什麼...$b$b是一頂呼吸帽!', `MaleText_loc7`='¡Ueeeee! ¡Todo este lugar brilla!$b$bEcha un vistazo a lo que he encontrado cavando justo aquí...$b$b¡Es un sombrero de respirar!' WHERE `ID`=46435;
