UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r님. 저는 녹색용군단의 군주 이타리우스라고 합니다.$B$B이 신전의 친족들을 악에서 구하기 위해 왔습니다. 저를 도와주시겠습니까?', `MaleText_loc4`='你好，$r。我是绿龙军团的伊萨里奥斯勋爵。$B$B我带着善良的意愿来到这里，要从这座神殿的邪恶中解救我的同族。你愿意帮助我吗？', `MaleText_loc5`='你好，$r。我乃綠龍軍團的伊薩里奧斯領主。$B$B我到此處是為了幫助我族同伴掙脫這神殿裡的邪惡影響。你願意協助我嗎?', `MaleText_loc7`='Saludos, $r. Soy Lord Itharius del Vuelo Verde.$B$BHe venido a liberar a los míos del mal que mora dentro de este templo, y espero hacerlo para siempre. ¿Me ayudarás?' WHERE `ID`=46462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈이 올 줄 알고 있었다. 아무도 내게 맞설 수 없다. 너도 마찬가지야!', `FemaleText_loc4`='我知道你会来。没有人能与我对抗，即便是你也不行！', `FemaleText_loc5`='我就知道你一定會來。沒有人拒絕得了我，連你也一樣!', `FemaleText_loc7`='Sabía que vendrías. Nadie puede resistirse a mí, ¡ni siquiera tú!' WHERE `ID`=46463;
