UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심해군주 진자타르가 전투에 참여했습니다!', `MaleText_loc4`='深水领主金加塔尔进入了战场！', `MaleText_loc5`='深淵領主金加塔加入戰鬥了!', `MaleText_loc7`='¡El Señor de las profundidades Zin''jatar ha entrado en la batalla!' WHERE `ID`=46486;
