UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재가 되었군!', `MaleText_loc4`='灰烬！', `MaleText_loc5`='灰燼!', `MaleText_loc7`='¡CENIZAS!' WHERE `ID`=46488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이... 꺼졌다!', `MaleText_loc4`='火焰……熄灭了！', `MaleText_loc5`='火焰...熄滅!', `MaleText_loc7`='¡FUEGO... APAGADO!' WHERE `ID`=46489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 이름으로 명한다. 물러서라!', `MaleText_loc4`='以国王的名义，后退！', `MaleText_loc5`='以國王之名，退後!', `MaleText_loc7`='¡Atrás, en el nombre del Rey!' WHERE `ID`=46490;
