UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨라! 놈들이 지나가게 둬선 안 된다!', `MaleText_loc4`='守住战线！不要让他们通过！', `MaleText_loc5`='守住陣線!別讓他們穿過!', `MaleText_loc7`='¡Sostened el frente! ¡No les dejéis pasar!' WHERE `ID`=46492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='델워터 교도소장님, 이럴 게 아니라 놈들을 압박해야 합니다!', `MaleText_loc4`='典狱官塞尔沃特，我们需要向前推进！', `MaleText_loc5`='典獄官塞爾沃特，我們必須往前推進!', `MaleText_loc7`='¡Celador Thelagua, tenemos que avanzar!' WHERE `ID`=46493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장님, 아직 조치를 취할 수 있을 때 어서 행동해야 합니다!', `MaleText_loc4`='我们必须行动，趁我们还能采取行动的时候！', `MaleText_loc5`='我們得趁還可以的時候趕緊展開行動!', `MaleText_loc7`='¡Debemos actuar ahora que podemos!' WHERE `ID`=46494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 날 소개하지. 나는 란돌프 몰로크이고, 오늘 너희를 모두 없앨 것이다.', `MaleText_loc4`='请让我做一下自我介绍。我是兰多菲·摩洛克。今天，我会把你们杀光。', `MaleText_loc5`='請容我自我介紹一下。我叫藍道夫·摩洛克，而且今天我就要把你們全部殺掉。', `MaleText_loc7`='Permitidme que me presente. Me llamo Randolph Moloch y hoy os mataré a todos.' WHERE `ID`=46495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아까운 목숨을 낭비하는군.', `MaleText_loc4`='这种对生命的浪费实在是可惜。', `MaleText_loc5`='可惜啊，虛擲生命。', `MaleText_loc7`='Qué trágica pérdida de vida.' WHERE `ID`=46496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 원대한 계획이, 완벽한 책략이! 물거품이 되었군!', `MaleText_loc4`='我宏大的谋略，绝妙的计划！都完了！', `MaleText_loc5`='我偉大的計畫，我宏遠的擘畫!全毀了!', `MaleText_loc7`='¡Mis maquinaciones épicas, mis grandes planes! ¡Perdidos!' WHERE `ID`=46497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침착해라, 제군들... 침착해...', `MaleText_loc4`='稳住……稳住……', `MaleText_loc5`='弟兄們，預備...預備...', `MaleText_loc7`='Esperad, muchachos... esperad...' WHERE `ID`=46498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격 대기! 델워터 교도소장의 명령이다. 쏘지 마라... 아직은.', `MaleText_loc4`='停火！这是典狱官的命令……禁止射击……', `MaleText_loc5`='停火!典獄官下令...停火...先暫停。', `MaleText_loc7`='¡Alto el fuego! Órdenes del celador... Nada de disparos... De momento.' WHERE `ID`=46499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게서 눈을 떼지 마라. 경비병 쪽으로 움직이는 놈들은 처치해 버려라.', `MaleText_loc4`='紧盯着他们。如果有任何异动，他们就死定了。', `MaleText_loc5`='緊緊盯好他們。要是他們敢對守衛動手，他們就死定了。', `MaleText_loc7`='Mantenerlos en sus miras. Si intentan cualquier cosa con los guardias, están muertos.' WHERE `ID`=46500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 잃지 마십시오. 곧 살아서 이곳을 나가게 될 겁니다.', `MaleText_loc4`='待在我身边。我们一定会把你弄出去的。', `MaleText_loc5`='跟著我，你一定可以離開這裡的。', `MaleText_loc7`='Quédate conmigo. Conseguirás salir de aquí.', `FemaleText_loc1`='의식을 잃지 마세요. 곧 살아서 이곳을 나가게 될 거예요.', `FemaleText_loc4`='待在我身边。我们一定会把你弄出去的。', `FemaleText_loc5`='跟著我，你一定可以離開這裡的。', `FemaleText_loc7`='Quédate conmigo. Conseguirás salir de aquí.' WHERE `ID`=46501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주실 분이 오고 있습니다.', `MaleText_loc4`='你会得到援助的。', `MaleText_loc5`='我們會去找人來幫你。', `MaleText_loc7`='Vamos a buscarte algo de ayuda.', `FemaleText_loc1`='도와주실 분이 오고 있어요.', `FemaleText_loc4`='你会得到援助的。', `FemaleText_loc5`='我們會去找人來幫你。', `FemaleText_loc7`='Vamos a buscarte algo de ayuda.' WHERE `ID`=46502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 치료 중입니다... 금방 괜찮아질 겁니다.', `MaleText_loc4`='你做得很好……你会没事的。', `MaleText_loc5`='做得很好...你一定不會有事的。', `MaleText_loc7`='Lo estás haciendo bien... todo irá bien.', `FemaleText_loc1`='지금 치료 중이니까... 금방 괜찮아질 거예요.', `FemaleText_loc4`='你做得很好……你会没事的。', `FemaleText_loc5`='做得很好...你一定不會有事的。', `FemaleText_loc7`='Lo estás haciendo bien... todo irá bien.' WHERE `ID`=46503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀어주는 중', `MaleText_loc4`='解救', `MaleText_loc5`='釋放', `MaleText_loc7`='Liberando', `FemaleText_loc1`='풀어주는 중', `FemaleText_loc4`='解救', `FemaleText_loc5`='釋放', `FemaleText_loc7`='Liberando' WHERE `ID`=46504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가는 저 앞 수중 동굴로 도망쳤소. 놈들에게 자비를 보이지 마시오, $c 친구.', `MaleText_loc4`='纳迦逃出了前面的隧道。绝不要对他们有任何怜悯，$c。', `MaleText_loc5`='納迦從前方的隧道逃走了。不要放過他們，$c!', `MaleText_loc7`='Los nagas han huido por el túnel de ahí delante. No les muestres piedad, $c.' WHERE `ID`=46505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신에게 영원히 감사할 것입니다, $n.', `FemaleText_loc4`='我永远都感谢你，$n。', `FemaleText_loc5`='我對你永懷感激，$n。', `FemaleText_loc7`='Te estoy eternamente agradecida, $n.' WHERE `ID`=46506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비룡들은 내가 처리하겠습니다. 당신은 나머지 황혼의 망치단 쓰레기들에게 주의를 기울이세요.', `FemaleText_loc4`='我会去对付那些龙。你只需要处理那些暮光垃圾就行了。', `FemaleText_loc5`='龍交給我來處理，你去對付其他的暮光人渣。', `FemaleText_loc7`='Yo me encargaré de los dracos. Tú preocúpate del resto de basura Crepuscular.' WHERE `ID`=46507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대의원회의 투표에서 만장일치로 찬성이라는 결과가 나와야만 람카헨은 네페르세트에 전쟁을 선포할 것이오.$B$B지금으로서는 가능성이 희박하오. 하지만 형도 이제 데스윙의 부하들과는 이성적인 대화가 불가능하다는 사실을 알아야 하오.', `MaleText_loc4`='只有当最高议会全体表决通过的时候，拉穆卡恒才会对尼斐塞特发动战争。$B$B我们的机会不大，但我的兄弟必须明白，死亡之翼的盟军绝对不会讲任何道理。', `MaleText_loc5`='唯有高階議會獲得一致的決議，蘭姆卡韓才會對奈斐賽特開戰。$B$B局勢對我們相當不利，但是必須讓我的弟兄們明白，要和死亡之翼的同黨講道理是不可能的。', `MaleText_loc7`='Los Ramkahen solo declararán la guerra a los Neferset si el voto del Alto Consejo es unánime.$b$bLas probabilidades van en nuestra contra, pero mi hermano tiene que entender que no se puede razonar con los aliados de Alamuerte.' WHERE `ID`=46508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 한 놈이 있다. 잡아라!', `MaleText_loc4`='来了一个——抓住他！', `MaleText_loc5`='那邊有一個--去抓它!', `MaleText_loc7`='¡Ahí hay uno! ¡Atrapadlo!', `FemaleText_loc1`='저기 한 놈이 있다. 잡아라!', `FemaleText_loc4`='来了一个——抓住他！', `FemaleText_loc5`='那邊有一個--去抓它!', `FemaleText_loc7`='¡Ahí hay uno! ¡Atrapadlo!' WHERE `ID`=46509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지 같은 드워프 놈들이 없는지 잘 살펴라.', `MaleText_loc4`='睁大了眼睛，别放过那些矮人猪。', `MaleText_loc5`='招子放亮點，不要漏看了那些矮人豬。', `MaleText_loc7`='Mantened los ojos bien abiertos por si véis algún asqueroso enano.', `FemaleText_loc1`='돼지 같은 드워프 놈들이 없는지 잘 살펴라.', `FemaleText_loc4`='睁大了眼睛，别放过那些矮人猪。', `FemaleText_loc5`='招子放亮點，不要漏看了那些矮人豬。', `FemaleText_loc7`='Mantened los ojos bien abiertos por si veis algún asqueroso enano.' WHERE `ID`=46510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 그대인가요? 부디 이 사슬을 끊어 주십시오.', `FemaleText_loc4`='$n，是你吗？请帮我摆脱这些锁链。', `FemaleText_loc5`='$n，是你嗎?請解開鎖鍊放開我。', `FemaleText_loc7`='$n, ¿eres tú? Por favor, libérame de estas cadenas.' WHERE `ID`=46511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우리 그리핀을 붙잡았다! 용아귀 놈들에게 자비를 보이지 마라!', `MaleText_loc4`='他们抓住了我们的同伴！绝不要对龙喉有任何怜悯！', `MaleText_loc5`='他們逮到我們的人了!不要饒過龍喉的傢伙!', `MaleText_loc7`='¡Tienen a uno de los nuestros! ¡Sin piedad para los Faucedraco!' WHERE `ID`=46512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 이리 넘겨라, 구역질 나는 짐승 놈들아! 와일드해머!', `MaleText_loc4`='交出那只鸟，你们这些肮脏的野兽。为蛮锤而战！！', `MaleText_loc5`='把鳥交出來，該死的畜生。蠻錘萬歲!!', `MaleText_loc7`='Entregadme el pájaro, apestosas bestias. ¡¡MARTILLO SALVAJE!!' WHERE `ID`=46513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네페르세트의 악당들과 한패인가? 그 손을 더럽히기 싫어서 너를 보냈나? 어서 말해봐!', `MaleText_loc4`='你和那些尼斐塞特 杂碎是一伙的？是不是他们派你来干什么肮脏的勾当？快说！', `MaleText_loc5`='你跟奈斐賽特的垃圾是同一國的?是他們派你來幹這些齷齪勾當的?說!', `MaleText_loc7`='¿Estás con la escoria Neferset? ¿Te han enviado para hacer su trabajo sucio? ¡Habla!' WHERE `ID`=46514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타헤트를 찾고 있습니다. 우선 사슬을 풀어 드리겠습니다.', `MaleText_loc4`='我正在找塔赫特。我这就帮你摆脱这些锁链。', `MaleText_loc5`='我是來尋找塔黑特的。讓我先把你的鎖鍊解開。', `MaleText_loc7`='Busco a Tahet. Vamos a quitarte esas cadenas.', `FemaleText_loc1`='타헤트를 찾고 있어요. 우선 사슬을 풀어 드릴게요.', `FemaleText_loc4`='我正在找塔赫特。我这就帮你摆脱这些锁链。', `FemaleText_loc5`='我是來尋找塔黑特的。讓我先把你的鎖鍊解開。', `FemaleText_loc7`='Busco a Tahet. Vamos a quitarte esas cadenas.' WHERE `ID`=46515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 그렇게 안 좋은 건 아닙니다...$b$b제겐 아직 수중 호흡 모자가 있으니까요!
', `MaleText_loc4`='还不算太糟糕……$b$b我还有我的呼吸帽子！', `MaleText_loc5`='沒有那麼糟...$b$b我的呼吸帽還在!', `MaleText_loc7`='No es tan malo...$b$b¡Todavía tengo mi sombrero de respirar!' WHERE `ID`=46516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀 구출하기', `MaleText_loc4`='援救狮鹫', `MaleText_loc5`='拯救獅鷲獸', `MaleText_loc7`='Rescata al grifo' WHERE `ID`=46517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사로잡은 전리품 지키기', `MaleText_loc4`='守卫夺取的战利品', `MaleText_loc5`='防守被俘虜的獎賞', `MaleText_loc7`='Defiende la presa capturada' WHERE `ID`=46518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 $C! 놈들의 반격을 막아내는 걸 도와주시오.', `MaleText_loc4`='你！$C！帮我们挡住敌人的反攻。', `MaleText_loc5`='你!$C!來幫我們防守阻擋反擊。', `MaleText_loc7`='¡Tú, $c! Ayúdanos a defendernos ante un contraataque.', `FemaleText_loc1`='거기 $C! 놈들의 반격을 막아내는 걸 도와주게.', `FemaleText_loc4`='你！$C！帮我们挡住敌人的反攻。', `FemaleText_loc5`='你!$C!來幫我們防守阻擋反擊。', `FemaleText_loc7`='¡Tú, $c! Ayúdanos a defendernos ante un contraataque.' WHERE `ID`=46519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 네페르세트 경비병이 오고 있소! 내가 놈들의 머리통을 부숴놓을 테니 내 가까이에서 싸우시오!', `MaleText_loc4`='等等！尼斐塞特卫兵冲过来了！和我一同战斗，好好教训他们一顿！', `MaleText_loc5`='慢著!奈斐賽特的衛兵來了!在我們身邊作戰，讓我也有機會打爆他們的頭!', `MaleText_loc7`='¡Espera! ¡Aquí vienen los guardias Neferset! ¡Lucha cerca de mí para que pueda machacarles el cráneo!' WHERE `ID`=46520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 자유를 찾았군. 이방인이여, 정말 고맙소. 타헤트는 이미 다른 곳으로 이송되었소. 카이마스라는 잔인한 네페르세트 장군이 그를 데려갔지.', `MaleText_loc4`='终于自由了。感谢你，陌生人。塔赫特已经不在这里了。一个残忍的尼斐塞特将军带走了他。那个将军的名字叫凯玛斯。', `MaleText_loc5`='終於自由了。謝謝你，陌生人。塔黑特已經不在這裡，一位殘酷的奈斐賽特將領，叫做凱瑪斯的，把他給抓走了。', `MaleText_loc7`='Libre al fin. Gracias, $gdesconocido:desconocida;. Tahet ya no está aquí. Se lo llevó un cruel señor de la guerra Neferset llamado Caimas.' WHERE `ID`=46521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오. 카이마스는 죄수에게 끔찍한 짓거리를 한다더군... 자기가 키우는 야수와 강제로 결투를 시킨다든가? 최악의 상황을 대비하는 게 좋을 거요, 친구.', `MaleText_loc4`='我必须警告你。凯玛斯对待囚犯非常残忍……他最喜欢强迫囚徒们与他豢养的怪兽进行决斗。也许你要做最坏的打算，朋友。', `MaleText_loc5`='我得警告你，凱瑪斯對待囚犯的手段非常殘暴...他會逼人犯和他養的野獸作戰。朋友，你要先做好最壞的打算。', `MaleText_loc7`='Debo advertírtelo. Caimas les hace cosas horribles a sus prisioneros... Les obliga a luchar contra sus bestias mascotas. Prepárate para lo peor, $gamigo:amiga;.' WHERE `ID`=46522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라! 얼라이언스가 와일드해머를 돕고 있다!', `MaleText_loc4`='注意了——联盟正在帮助蛮锤矮人！', `MaleText_loc5`='小心--聯盟正在幫助蠻錘的人!', `MaleText_loc7`='¡Cuidado! ¡La Alianza ayuda a los Martillo Salvaje!', `FemaleText_loc1`='조심해라! 얼라이언스가 와일드해머를 돕고 있다!', `FemaleText_loc4`='注意了——联盟正在帮助蛮锤矮人！', `FemaleText_loc5`='小心--聯盟正在幫助蠻錘的人!', `FemaleText_loc7`='¡Cuidado! ¡La Alianza ayuda a los Martillo Salvaje!' WHERE `ID`=46523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 네페르세트 집행자에게서 열쇠를 집어 듭니다.', `MaleText_loc4`='%s从尼斐塞特执行者身上拣起一把钥匙。', `MaleText_loc5`='%s從奈斐賽特執行者身上檢起一把鑰匙。', `MaleText_loc7`='%s recoge una llave del déspota Neferset.' WHERE `ID`=46524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 와일드해머의 승리로군!', `MaleText_loc4`='又一个愿意帮助蛮锤战斗的朋友！', `MaleText_loc5`='又幫蠻錘多幹掉一個啦!', `MaleText_loc7`='¡Uno más para los Martillo Salvaje!', `FemaleText_loc1`='또다시 와일드해머의 승리로군!', `FemaleText_loc4`='又一个愿意帮助蛮锤战斗的朋友！', `FemaleText_loc5`='又幫蠻錘多幹掉一個啦!', `FemaleText_loc7`='¡Uno más para los Martillo Salvaje!' WHERE `ID`=46525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!
', `MaleText_loc4`='喂！', `MaleText_loc5`='嗨!', `MaleText_loc7`='¡Ah, del barco!' WHERE `ID`=46526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구속의 손아귀로 들어가 나가들을 먹어 치우십시오!', `MaleText_loc4`='冲进关押所，消灭纳迦！', `MaleText_loc5`='騎進繫留場，把納迦吞掉!', `MaleText_loc7`='¡Ve a los Rediles de Encierro y DEVORA nagas!' WHERE `ID`=46527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 군대에 그대들의 도움이 필요하다!', `MaleText_loc4`='部落的战争机器需要你！', `MaleText_loc5`='部落的作戰部隊需要你!', `MaleText_loc7`='¡La máquina de guerra de la Horda te necesita!' WHERE `ID`=46528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계수를 구하러 오셨습니까? 하이잘 산이 지금 불타고 있습니다!', `MaleText_loc4`='你是来这里助战的吗？海加尔山必将燃起熊熊大火！', `MaleText_loc5`='你是來幫忙的嗎?海加爾山失火了!', `MaleText_loc7`='¿Has venido para contribuir a la causa? ¡El Monte Hyjal arde!' WHERE `ID`=46529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사절이여, 저를 달숲으로 보내 주시겠습니까?', `MaleText_loc4`='能不能派我去月光林地，使者？', `MaleText_loc5`='特使，可以請你把我傳送到月光林地嗎?', `MaleText_loc7`='¿Podrías enviarme a Claro de la Luna?', `FemaleText_loc1`='사절이여, 저를 달숲으로 보내 주시겠어요?', `FemaleText_loc4`='能不能派我去月光林地，使者？', `FemaleText_loc5`='特使，可以請你把我傳送到月光林地嗎?', `FemaleText_loc7`='¿Podrías enviarme a Claro de la Luna?' WHERE `ID`=46530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독과 그의 병력들은 이전에 당신이 정찰갔었던 기지를 차지하기 위해 돌격해 나갔습니다. 가서 그들을 만나는 게 좋겠습니다.', `FemaleText_loc4`='将军和他的部队正要去攻取一座已经由你进行过侦查的基地。你应该去与他们汇合。', `FemaleText_loc5`='上將已率領他的部隊推進去攻佔你先前為他偵察的其中一座基地。你應該過去見他。', `FemaleText_loc7`='El almirante y sus tropas avanzaron para tomar una de las bases que habías explorado para ellos con anterioridad. Deberías ir a reunirte con ellos.' WHERE `ID`=46531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대왕 오징어 녀석, 어림도 없었죠. 베른호는 벌써 재무장을 하고 다시 나갈 준비를 마쳤어요... 지금은 기다리죠.$B$B녀석은 돌아올 거예요.$B$B두고 보자고요.', `MaleText_loc4`='那只巨型鱿鱼就要完蛋了。凡尔纳已经重整装备，准备再次上阵……现在，我们只需要耐心等待。$B$B它会回来的。$B$B你就看着吧。', `MaleText_loc5`='那隻大烏賊一點勝算也沒有。維恩號已經重新填裝好，準備再發射了...現在我們只要再等等就好了。$B$B它還會再來的。$B$B你等一下就知道了。', `MaleText_loc7`='Ese calamar gigante no tuvo ninguna oportunidad. El Verne ya está rearmado y listo para la batalla... solo tenemos que esperar.$B$BVolverá.$B$BYa lo verás.' WHERE `ID`=46532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 잘해줬다. 장비를 챙기고 이 자리를 뜨자.', `MaleText_loc4`='大家干得好。现在，各就各位，我们准备行动。', `MaleText_loc5`='大家幹得好。稍微收拾一下你們的裝備，準備出發了。', `MaleText_loc7`='Muy buen trabajo a todos. Tomen un tiempo para recoger su equipo y marchémonos.' WHERE `ID`=46533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러면 좀 바빠질 거다!', `MaleText_loc4`='这会让你有事可干！', `MaleText_loc5`='這可夠你忙得了!', `MaleText_loc7`='¡Esto te mantendrá $gocupado:ocupada;!' WHERE `ID`=46534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 용아귀 부족이다!', `MaleText_loc4`='龙喉！', `MaleText_loc5`='龍喉氏族!', `MaleText_loc7`='¡FAUCEDRACO!', `FemaleText_loc1`='우리는 용아귀 부족이다!', `FemaleText_loc4`='龙喉！', `FemaleText_loc5`='龍喉氏族!', `FemaleText_loc7`='¡FAUCEDRACO!' WHERE `ID`=46535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 악어를 떼어내려면 위로 뛰어야 합니다!', `MaleText_loc4`='跳起来，甩掉那些小鳄鱼！', `MaleText_loc5`='跳起來甩掉小鱷魚!', `MaleText_loc7`='¡Salta para librarte de los crocoliscos jóvenes!' WHERE `ID`=46536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라와라. 언덕 위 어딘가에서 더 큰 전투가 벌어지고 있다.', `MaleText_loc4`='来吧。这座山脊上的战斗还没结束呢。', `MaleText_loc5`='走吧。上頭那邊還有更多的亂子。', `MaleText_loc7`='Ven. Hay más caos en la cresta, por todas partes.', `FemaleText_loc1`='따라와라. 언덕 위 어딘가에서 더 큰 전투가 벌어지고 있다.', `FemaleText_loc4`='来吧。这座山脊上的战斗还没结束呢。', `FemaleText_loc5`='走吧。上頭那邊還有更多的亂子。', `FemaleText_loc7`='Ven. Hay más caos en la cresta, por todas partes.' WHERE `ID`=46537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 이곳을 방문하는 자는 많지 않은데...$B$B잠시 앉으십시오.', `FemaleText_loc4`='啊……来这里拜访我的人并不多。$B$B请多坐一会儿吧。', `FemaleText_loc5`='啊...我這邊很難得有訪客。$B$B請坐一會吧。', `FemaleText_loc7`='Ah... No suelo tener muchos visitantes.$B$BPor favor, sentaos un rato.' WHERE `ID`=46538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에서 당신을 필요로 한다. 영웅의 부름에 답하라!', `MaleText_loc4`='联盟需要你。响应英雄的号召吧！', `MaleText_loc5`='聯盟需要你。回應英雄的召喚!', `MaleText_loc7`='La Alianza te necesita. ¡Responde a la llamada del heroísmo!' WHERE `ID`=46539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 할 일을 하는군.', `MaleText_loc4`='我们完成了这个工作。', `MaleText_loc5`='現在我們來把事情做完。', `MaleText_loc7`='Ahora terminamos el trabajo.', `FemaleText_loc1`='드디어 할 일을 하는군.', `FemaleText_loc4`='我们完成了这个工作。', `FemaleText_loc5`='現在我們來把事情做完。', `FemaleText_loc7`='Ahora terminamos el trabajo.' WHERE `ID`=46540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 운이 좋은 녀석이군! 내 애완동물이 네놈을 고깃덩이로 만들어줄 거다!', `MaleText_loc4`='呸！只是运气好而已！我的宠物会把你撕个粉碎！', `MaleText_loc5`='哼!只是走運罷了!我的寵物會把你們幹掉!', `MaleText_loc7`='¡Bah! ¡Pura suerte! ¡Mis mascotas te harán picadillo!' WHERE `ID`=46541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이제 지겹다!', `MaleText_loc4`='够了！我已经厌烦你了！', `MaleText_loc5`='夠了!我開始覺得你很煩了!', `MaleText_loc7`='¡Basta! ¡Ya me he cansado de ti!' WHERE `ID`=46542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세계수를 구하러 오셨나요? 하이잘 산이 지금 불타고 있어요!', `FemaleText_loc4`='你是来这里助战的吗？海加尔山必将燃起熊熊大火！', `FemaleText_loc5`='你是來幫忙的嗎?海加爾山失火了!', `FemaleText_loc7`='¿Has venido para contribuir a la causa? ¡El Monte Hyjal arde!' WHERE `ID`=46543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을을 샅샅이 뒤져라. 생존자를 남기지 마라!', `MaleText_loc4`='搜索这座城镇，消灭一切幸存者！', `MaleText_loc5`='搜索鎮上，殺掉所有生還者!', `MaleText_loc7`='Registrad el pueblo. ¡Matad a todos los supervivientes!', `FemaleText_loc1`='마을을 샅샅이 뒤져라. 생존자를 남기지 마라!', `FemaleText_loc4`='搜索这座城镇，消灭一切幸存者！', `FemaleText_loc5`='搜索鎮上，殺掉所有生還者!', `FemaleText_loc7`='Registrad el pueblo. ¡Matad a todos los supervivientes!' WHERE `ID`=46544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! $n 님! 이쪽입니다...', `MaleText_loc4`='喂！$n！到这里来……', `MaleText_loc5`='噓!$n!這邊...', `MaleText_loc7`='¡Psst! ¡$n! Por aquí...' WHERE `ID`=46545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카이마스를 악어 알 쪽으로 유인해야 합니다! 자신이 직접 밟지 않도록 조심하세요!', `MaleText_loc4`='引诱凯玛斯到鳄鱼蛋旁边去，但你可不要踩上那些鳄鱼蛋！', `MaleText_loc5`='將凱瑪斯引向鱷魚蛋!小心自己不要踩到!', `MaleText_loc7`='¡Atrae a Caimas hasta los huevos de crocolisco sin que tú los pises!' WHERE `ID`=46546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벽을 넘어라. 이얍!', `MaleText_loc4`='上城墙，冲啊！', `MaleText_loc5`='跨過這道牆，上!', `MaleText_loc7`='¡Por encima del muro, ARRIBA!' WHERE `ID`=46547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광을 위해! 명예를 위해! 썬더마를 위해!', `MaleText_loc4`='为了荣誉！为了光荣！为了桑德玛尔！', `MaleText_loc5`='榮耀!正義!桑德瑪!', `MaleText_loc7`='¡Por la gloria! ¡Por el honor! ¡POR BRAMAL!' WHERE `ID`=46548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌무더기가 되어 버린 저 집은 다섯 세대 동안이나 우리 가족의 보금자리였습니다.$B$B반드시 되찾고 말 겁니다.$B$B수적으로 열세이긴 하지만... 우리는 와일드해머니까요! 저희와 함께하시겠습니까?', `MaleText_loc4`='远处的那片碎石堆曾经是我们家族传承了五代的产业。$B$B我们正在把它夺回来。$B$B敌人的数量远远超过我们……但我们是蛮锤氏族！你愿意帮助我们吗？', `MaleText_loc5`='那片亂石頭堆就是我家傳五個世代的農場。$B$B我們一定要把它奪回來。$B$B雖然我們的人數處於劣勢...但我們是蠻錘矮人!你要跟我一起上嗎?', `MaleText_loc7`='Ese montón de escombros de ahí fue el hogar de mi familia durante cinco generaciones.$b$bY lo recuperaremos.$b$bNos superan en número... ¡Pero somos Martillo Salvaje! ¿Estás conmigo?' WHERE `ID`=46549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='好的！', `MaleText_loc5`='走吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='갑시다!', `FemaleText_loc4`='好的！', `FemaleText_loc5`='走吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=46550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽고 깨끗한 승리로군!', `MaleText_loc4`='不工作的人不美丽！', `MaleText_loc5`='三兩下輕鬆解決，打得他們落花流水!', `MaleText_loc7`='¡Un trabajo sencillo, y no demasiado bonito!', `FemaleText_loc1`='좋다, 망치는 그렇게 내리치는 거지!', `FemaleText_loc4`='没错，锤子就应该这样挥舞，先生们！', `FemaleText_loc5`='是的，兄弟們，錘子就是這樣用的!', `FemaleText_loc7`='¡Sí, así es como se maneja el martillo, caballeros!' WHERE `ID`=46551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다! 내가 집을 살펴보는 동안 모두 저 더러운 놈들의 시체를 태워라.', `MaleText_loc4`='好啊！在我搜索这片古老的家园时，把那些肮脏的尸体都烧光吧。', `MaleText_loc5`='沒錯!把這些髒東西的屍體燒掉，我到老農場裡巡一巡。', `MaleText_loc7`='¡Bien! Quema los cuerpos de esta escoria mientras registro la antigua casa.' WHERE `ID`=46552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 망할 자식들... 놈들이 내 집을 엉망으로 만들었어!', `MaleText_loc4`='哦，那些地狱的渣滓。它们把这个地方全都毁了！', `MaleText_loc5`='啊，該死的東西，這裡被他們給弄得亂七八糟!', `MaleText_loc7`='Ay, por la resaca del infierno. ¡Han destrozado el lugar!' WHERE `ID`=46553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적은 달성했다. 모두 철수한다. 다른 곳에서 놈들을 다시 혼내주자.', `MaleText_loc4`='我们已经得到了我们所需要的。现在撤离。我们会在别的地方再次狠狠地打击他们。', `MaleText_loc5`='好歹我們達到目的了。走吧，我們去別的地方再痛扁他們。', `MaleText_loc7`='Tenemos lo que necesitamos. Vámonos. Les atacaremos de nuevo en algún otro sitio.' WHERE `ID`=46554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가십시오, 친구여! 보물 사냥, 즐거웠습니다!', `MaleText_loc4`='再见，朋友！祝你猎宝收获多多！', `MaleText_loc5`='再見啦，朋友!祝你尋寶順利!', `MaleText_loc7`='¡Adiós, $gamigo:amiga;! ¡Feliz caza del tesoro!' WHERE `ID`=46555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더마로 소식을 전해야겠군.', `MaleText_loc4`='我会将这个消息带到桑德玛尔。', `MaleText_loc5`='我會把這個消息送到桑德瑪。', `MaleText_loc7`='Transmitiré la noticia a Bramal.', `FemaleText_loc1`='썬더마로 소식을 전해야겠군.', `FemaleText_loc4`='我会将这个消息带到桑德玛尔。', `FemaleText_loc5`='我會把這個消息送到桑德瑪。', `FemaleText_loc7`='Transmitiré la noticia a Bramal.' WHERE `ID`=46556;
