UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸만한 게 있는지 뒤져 봐라. 서둘러라. 놈들이 곧 공격할 것이다.', `MaleText_loc4`='彻底搜索这片区域，收集一切可用的物资。迅速行动——他们很快又要发动攻击了。', `MaleText_loc5`='四處找找有沒有東西可以用。動作快，他們很快又會發動攻擊。', `MaleText_loc7`='Peina la zona en busca de cualquier cosa que nos resulte útil. Rápido... nos atacarán de nuevo.', `FemaleText_loc1`='쓸만한 게 있는지 뒤져 봐라. 서둘러라. 놈들이 곧 공격할 것이다.', `FemaleText_loc4`='彻底搜索这片区域，收集一切可用的物资。迅速行动——他们很快又要发动攻击了。', `FemaleText_loc5`='四處找找有沒有東西可以用。動作快，他們很快又會發動攻擊。', `FemaleText_loc7`='Peina la zona en busca de cualquier cosa que nos resulte útil. Rápido... nos atacarán de nuevo.' WHERE `ID`=46562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 확실히 기억합니다. 맑고 화창한 날이었죠...', `MaleText_loc4`='我记得很清楚。那是一个阳光灿烂的日子……', `MaleText_loc5`='我記得很清楚。那天非常晴朗明亮...', `MaleText_loc7`='Lo recuerdo bien. Era un día claro y soleado...' WHERE `ID`=46563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 그냥 제 할 일을 하고 있었는데, 갑자기 데스윙이 나타났죠!', `MaleText_loc4`='那时我正专心于自己的工作，突然之间，死亡之翼出现了！', `MaleText_loc5`='我正在忙我自己的事情，然後忽然間，死亡之翼就出現了!', `MaleText_loc7`='Yo iba a lo mío cuando, de repente... ¡apareció Alamuerte!' WHERE `ID`=46564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 다짐했습니다. "저 용 대가리에 주먹을 한 방 먹여주겠어!"', `MaleText_loc4`='我对自己说，“我要一拳砸扁那头龙的脸！”', `MaleText_loc5`='我告訴自己，「我要在那頭龍的臉上狠很揍一拳!」', `MaleText_loc7`='Y me dije a mí mismo: "¡Voy a darle un puñetazo a ese dragón en toda la cara!"' WHERE `ID`=46565;
