UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 불행히도 대격변이 화난 정령들을 잔뜩 깨웠죠.', `MaleText_loc4`='不幸的是，这场大灾变释放出无数愤怒的元素。', `MaleText_loc5`='不幸的是，這場大災變也釋放出了一大票憤怒的元素。', `MaleText_loc7`='Desafortunadamente, el Cataclismo liberó a un puñado de elementales muy enfadados.' WHERE `ID`=46567;
