UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 세금도 착실히 냈으니 도시에 들어갈 권리가 있단 말이오!', `MaleText_loc4`='作为一名纳税公民，我有权利访问这座城市！', `MaleText_loc5`='身為一個誠實納稅的好公民，我有進城的權利!', `MaleText_loc7`='¡Como súbdito que paga sus impuestos, tengo derecho a visitar la ciudad!', `FemaleText_loc1`='난 세금도 착실히 냈으니까 도시에 들어갈 권리가 있다고요!', `FemaleText_loc4`='作为一名纳税公民，我有权利访问这座城市！', `FemaleText_loc5`='身為一個誠實納稅的好公民，我有進城的權利!', `FemaleText_loc7`='¡Como súbdito que paga sus impuestos, tengo derecho a visitar la ciudad!' WHERE `ID`=46587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕께서 왜 자기 시민을 두려워하시는 거지?', `MaleText_loc4`='乌瑞恩国王为什么会害怕他自己的人民？', `MaleText_loc5`='烏瑞恩國王為什麼要害怕他自己的百姓?', `MaleText_loc7`='¿Qué teme el rey Wrynn de su propia gente?', `FemaleText_loc1`='린 국왕께서 왜 자기 시민을 두려워하시는 거죠?', `FemaleText_loc4`='乌瑞恩国王为什么会害怕他自己的人民？', `FemaleText_loc5`='烏瑞恩國王為什麼要害怕他自己的百姓?', `FemaleText_loc7`='¿Qué teme el rey Wrynn de su propia gente?' WHERE `ID`=46588;
