UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥브라이드 치안대장을 나오라고 해! 이건 엄연히 불법 행위라고!', `MaleText_loc4`='我要和治安官玛克布莱德谈谈！这样对待我简直太无礼了！', `MaleText_loc5`='這太過份了!叫治安官瑪克布萊德出來!', `MaleText_loc7`='¡Quiero hablar con el alguacil McBride! ¡Esto es un ultraje!', `FemaleText_loc1`='맥브라이드 치안대장을 불러줘요! 이건 엄연히 불법 행위라고요!', `FemaleText_loc4`='我要和治安官玛克布莱德谈谈！这样对待我简直太无礼了！', `FemaleText_loc5`='這太過份了!叫治安官瑪克布萊德出來!', `FemaleText_loc7`='¡Quiero hablar con el alguacil McBride! ¡Esto es un ultraje!' WHERE `ID`=46590;
