UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 얘기해주십시오, 텔두린.', `MaleText_loc4`='再和我说说那个故事，塞尔杜林。', `MaleText_loc5`='再跟我說一遍那個故事，塞爾杜林。', `MaleText_loc7`='Vuelve a contarme esa historia, Theldurin.', `FemaleText_loc1`='다시 한 번 얘기해주세요, 텔두린.', `FemaleText_loc4`='再和我说说那个故事，塞尔杜林。', `FemaleText_loc5`='再跟我說一遍那個故事，塞爾杜林。', `FemaleText_loc7`='Vuelve a contarme esa historia, Theldurin.' WHERE `ID`=46593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐, 아냐, 그게 아니잖아, 텔두린. 얘기를 해주려면 똑바로 해줘야지!', `MaleText_loc4`='不，不，不，塞尔杜林。你把故事讲错了！', `MaleText_loc5`='不不不，塞爾杜林，你說錯故事了!', `MaleText_loc7`='No, no, no, Theldurin. ¡Estás contando mal la historia!' WHERE `ID`=46594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 저는 이쪽으로 안 갔는데... 제가 얘기를 잘못한 것 같습니다.', `MaleText_loc4`='嗯……我走的不是这个方向。我想我的确是把故事讲错了。', `MaleText_loc5`='嗯...我沒有走這個方向...我好像說錯故事了。', `MaleText_loc7`='Mmm... No fui en esta dirección. Creo que estoy contando mal la historia.' WHERE `ID`=46595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씹어먹을 뼈가 더 있군...', `MaleText_loc4`='还有更多的骨头要啃……', `MaleText_loc5`='有更多的骨頭可以啃了...', `MaleText_loc7`='Más huesos para roer...' WHERE `ID`=46596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?! 이게 무슨 일입니까?! 불가능한 일입니다! 놈의 시체가 바로 여기에 있는데! 혹시...', `MaleText_loc4`='什么？！那是什么？！不可能！他的身体就在这里！除非……', `MaleText_loc5`='什麼?!那是什麼?!不可能!他的屍體剛剛還在這裡!除非...', `MaleText_loc7`='¡¿Qué?! ¡¿Qué ha sido eso?! ¡Imposible! ¡Su cuerpo está aquí mismo! A no ser...' WHERE `ID`=46597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 눈이 빛나기 시작합니다. 신속히 안전한 곳으로 피하십시오!', `MaleText_loc4`='%s的眼睛开始发光了。赶快找掩护！', `MaleText_loc5`='%s的眼睛開始發亮。快找掩護!', `MaleText_loc7`='Los ojos de %s empiezan a brillar. ¡Ponte a cubierto, rápido!' WHERE `ID`=46598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주도로를 확보해라. 여기서부터 놈들을 밀고 나갈 것이다.', `MaleText_loc4`='坚守主路。这是我们的主攻击方向。', `MaleText_loc5`='守住主要道路。我們可以從這裡發動我們的主要攻勢。', `MaleText_loc7`='Toma el control de la carretera principal. Desde ahí podremos lanzar nuestro gran asalto.' WHERE `ID`=46599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 이건 진짜 들창코가 분명합니다. 허리띠에 제 눈이 매달려 있으니까요. 여기서 벌어진 일에서는 엄청난 암흑의 기운이 느껴지는군요. 놈은... 우리가 이해할 수 없을 만큼 강력합니다.', `MaleText_loc4`='英雄们，我知道他是真正的霍格。我看到我的眼睛就挂在他的腰带上。那其中包含着一段非常黑暗的往事。他的力量……已经超出了我们的理解范畴……', `MaleText_loc5`='英雄們，我知道這隻才是真正的霍格，因為我看見了我的眼珠子掛在他的腰帶上。這代表的是，底下這邊的確發生了非常邪惡的事情。他的力量...遠遠超乎了我們的理解...', `MaleText_loc7`='Héroes, sé que este es el Hogger auténtico. Veo mi ojo que le cuelga del cinturón. Las implicaciones de lo que ha tenido lugar aquí abajo son muy oscuras. Su poder... va más allá de nuestra comprensión...' WHERE `ID`=46600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 뭔가 쏴버리고 싶어요!', `FemaleText_loc4`='爸爸让我射击！', `FemaleText_loc5`='爸比讓我射東西!', `FemaleText_loc7`='¡Papá me deja disparar cosas!' WHERE `ID`=46601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시오! 자기 차례를 기다리란 말이오...', `MaleText_loc4`='镇定！我们要尽快查清楚每一个人……', `MaleText_loc5`='冷靜!我們一定會照顧到大家...', `MaleText_loc7`='¡Cálmate! Atenderemos a todo el mundo...', `FemaleText_loc1`='진정하세요! 자기 차례를 기다리라고요...', `FemaleText_loc4`='镇定！我们要尽快查清楚每一个人……', `FemaleText_loc5`='冷靜!我們一定會照顧到大家...', `FemaleText_loc7`='¡Cálmate! Atenderemos a todo el mundo...' WHERE `ID`=46602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소리를 지르면 지를수록 시간은 더 오래 걸릴 겁니다.', `MaleText_loc4`='你们大喊大叫只能耽误更多时间。', `MaleText_loc5`='你越是亂喊一通，我們就要花上越久的時間才能解決這件事。', `MaleText_loc7`='Cuanto más grites, más tardaremos en resolver esto.', `FemaleText_loc1`='소리를 지르면 지를수록 시간은 더 오래 걸릴 겁니다.', `FemaleText_loc4`='你们大喊大叫只能耽误更多时间。', `FemaleText_loc5`='你越是亂喊一通，我們就要花上越久的時間才能解決這件事。', `FemaleText_loc7`='Cuanto más grites, más tardaremos en resolver esto.' WHERE `ID`=46603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 또 와일드해머 놈들인가? 바보들이 죽고 싶어서 환장했군!', `MaleText_loc4`='什么？还有更多蛮锤矮人？那些傻瓜真是不想活了！', `MaleText_loc5`='什麼?更多的蠻錘矮人?這些笨蛋根本是想找死!', `MaleText_loc7`='¿Qué? ¿MÁS Martillo Salvaje? ¡Estos locos desean morir!' WHERE `ID`=46604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피오나 님, 어떤 물건을 살 수 있는지 보여주십시오.', `MaleText_loc4`='让我看看你都出售些什么，菲奥拉。', `MaleText_loc5`='讓我瞧瞧你在賣些什麼，菲歐娜。', `MaleText_loc7`='Enséñame qué tienes a la venta, Fiona.', `FemaleText_loc1`='피오나 님, 어떤 물건을 살 수 있는지 보여주세요.', `FemaleText_loc4`='让我看看你都出售些什么，菲奥拉。', `FemaleText_loc5`='讓我瞧瞧你在賣些什麼，菲歐娜。', `FemaleText_loc7`='Enséñame qué tienes a la venta, Fiona.' WHERE `ID`=46605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이다. 흩어지지 말도록!', `MaleText_loc4`='这边走。聚在一起，别走散了！', `MaleText_loc5`='這邊，不要分開了!', `MaleText_loc7`='Por aquí. ¡Permaneced juntos!', `FemaleText_loc1`='이쪽이다. 흩어지지 말도록!', `FemaleText_loc4`='这边走。聚在一起，别走散了！', `FemaleText_loc5`='這邊，不要分開了!', `FemaleText_loc7`='Por aquí. ¡Permaneced juntos!' WHERE `ID`=46606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히들 하세요! 어떻게든 최대한 빨리 해결해 볼 테니까.', `MaleText_loc4`='不要吵！我们会尽快做好甄别工作。', `MaleText_loc5`='安靜一點!我們會盡快解決這件事情。', `MaleText_loc7`='¡Baja la voz! Lo arreglaremos en cuanto podamos.', `FemaleText_loc1`='조용히들 하세요! 어떻게든 최대한 빨리 해결해 볼 테니까요.', `FemaleText_loc4`='不要吵！我们会尽快做好甄别工作。', `FemaleText_loc5`='安靜一點!我們會盡快解決這件事情。', `FemaleText_loc7`='¡Baja la voz! Lo arreglaremos en cuanto podamos.' WHERE `ID`=46607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하지 않으면 지하감옥에 가둬버릴 겁니다!', `MaleText_loc4`='如果你们不安静些，你们今晚就要在监狱里待着了！', `MaleText_loc5`='你要是再不冷靜下來的話，你就得整晚都窩在監獄裡!', `MaleText_loc7`='¡Si no te tranquilizas, pasarás la noche en las Mazmorras!', `FemaleText_loc1`='진정하지 않으면 지하감옥에 가둬버릴 거예요!', `FemaleText_loc4`='如果你们不安静些，你们今晚就要在监狱里待着了！', `FemaleText_loc5`='你要是再不冷靜下來的話，你就得整晚都窩在監獄裡!', `FemaleText_loc7`='¡Si no te tranquilizas, pasarás la noche en las Mazmorras!' WHERE `ID`=46608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침착하십시오, 여러분. 저희한테 소리 지른다고 해결될 문제가 아닙니다.', `MaleText_loc4`='耐心一些，公民们。冲我们叫嚷不会让情况有任何改善。', `MaleText_loc5`='市民們，請有點耐性。對著我們大吼大叫是無法改變現狀的。', `MaleText_loc7`='Tened paciencia, ciudadanos. Gritarnos no va a cambiar nada.', `FemaleText_loc1`='침착하십시오, 여러분. 저희한테 소리 지른다고 해결될 문제가 아닙니다.', `FemaleText_loc4`='耐心一些，公民们。冲我们叫嚷不会让情况有任何改善。', `FemaleText_loc5`='市民們，請有點耐性。對著我們大吼大叫是無法改變現狀的。', `FemaleText_loc7`='Tened paciencia, ciudadanos. Gritarnos no va a cambiar nada.' WHERE `ID`=46609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하께서는 도시를 안전하게 지키려고 최선의 선택을 하신 겁니다.', `MaleText_loc4`='国王只是在采取必要措施确保城市的安全。', `MaleText_loc5`='國王之所以這麼做都是為了確保暴風城的安全。', `MaleText_loc7`='El Rey solo hace lo que considera necesario para garantizar la seguridad de la ciudad.', `FemaleText_loc1`='국왕 폐하께서는 도시를 안전하게 지키려고 최선의 선택을 하신 겁니다.', `FemaleText_loc4`='国王只是在采取必要措施确保城市的安全。', `FemaleText_loc5`='國王之所以這麼做都是為了確保暴風城的安全。', `FemaleText_loc7`='El Rey solo hace lo que considera necesario para garantizar la seguridad de la ciudad.' WHERE `ID`=46610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 문을 닫아버리면 아무도 못 들어올 텐데...', `MaleText_loc4`='我们只需要把大门关上，就没有人能进来了……', `MaleText_loc5`='我大可把門給關起來，然後就沒有人進得來...', `MaleText_loc7`='Podría cerrar las puertas, y entonces no entraría nadie...', `FemaleText_loc1`='그냥 문을 닫아버리면 아무도 못 들어올 텐데...', `FemaleText_loc4`='我们只需要把大门关上，就没有人能进来了……', `FemaleText_loc5`='我大可把門給關起來，然後就沒有人進得來...', `FemaleText_loc7`='Podría cerrar las puertas, y entonces no entraría nadie...' WHERE `ID`=46611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치고 폴짝 뛸 노릇이군! 힘들게 심원의 영지를 구원하고 왔더니, 이건 또 뭐냐고?$B$B고약한 황혼의 망치단을 상대해야 한다니!$B$B그래도 자네가 일을 바로잡으러 왔으니 참말 다행이군!', `MaleText_loc4`='真是一团乱！我们刚刚从拯救深岩之洲的战斗中回来，却看到了这种场面？$B$B可憎的暮光之锤！$B$B幸好你在这里，把他们解决掉了！', `MaleText_loc5`='亂七八糟!我們才剛拯救完地深之源回來，結果又是什麼?$B$B暮光之錘的臭混蛋!$B$B還好有你在這兒幫我們解決這檔事!', `MaleText_loc7`='¡Vaya desastre! Volvemos de salvar Infralar, ¿y qué nos encontramos?$b$b¡Al Martillo Crepuscular de las narices!$b$b¡Menos mal que estabas aquí para arreglarlo todo!' WHERE `ID`=46612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 골드마인. 그 짜릿한 탈것을 타 봅시다.', `MaleText_loc4`='金矿先生，我已经准备好进行这次狂野驾驶了。', `MaleText_loc5`='金礦先生，我已經準備好狂飆了。', `MaleText_loc7`='Señor Minaoro, estoy listo para ese viaje salvaje.', `FemaleText_loc1`='좋아요, 골드마인. 그 짜릿한 탈것을 타 봅시다.', `FemaleText_loc4`='金矿先生，我已经准备好进行这次狂野驾驶了。', `FemaleText_loc5`='金礦先生，我已經準備好狂飆了。', `FemaleText_loc7`='Señor Minaoro, estoy lista para ese viaje salvaje.' WHERE `ID`=46613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들은 우리한테 이럴 권한이 없소!', `MaleText_loc4`='你们没有权力把我们挡在外面！', `MaleText_loc5`='你沒有權力把我們留置在外面!', `MaleText_loc7`='¡No tienen derecho a dejarnos fuera!', `FemaleText_loc1`='당신들은 우리한테 이럴 권한이 없다고요!', `FemaleText_loc4`='你们没有权力把我们挡在外面！', `FemaleText_loc5`='你沒有權力把我們留置在外面!', `FemaleText_loc7`='¡No tienen derecho a dejarnos fuera!' WHERE `ID`=46614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 도시나 호드에 잘못한 게 없는데...', `MaleText_loc4`='我们对这座城市和它的国王绝对没有恶意……', `MaleText_loc5`='我們沒有做出任何對不起這座城市或部落的事情...', `MaleText_loc7`='No hemos cometido ninguna falta contra la ciudad o la Horda...', `FemaleText_loc1`='우린 도시나 호드에 잘못한 게 없는데...', `FemaleText_loc4`='我们对这座城市和它的国王绝对没有恶意……', `FemaleText_loc5`='我們沒有做出任何對不起這座城市或部落的事情...', `FemaleText_loc7`='No hemos cometido ninguna falta contra la ciudad o la Horda...' WHERE `ID`=46615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들여보내 주시오. 손님들이 날 기다리고 있단 말이오.', `MaleText_loc4`='你们必须让我进去，我的客人们还在等着呢。', `MaleText_loc5`='你們一定得放我進去，我的客人還在等我。', `MaleText_loc7`='Tienen que dejarme entrar, me esperan mis clientes.', `FemaleText_loc1`='들여보내 줘요. 손님들이 날 기다리고 있단 말이에요.', `FemaleText_loc4`='你们必须让我进去，我的客人们还在等着呢。', `FemaleText_loc5`='你們一定得放我進去，我的客人還在等我。', `FemaleText_loc7`='Tienen que dejarme entrar, me esperan mis clientes.' WHERE `ID`=46616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 년 동안 호드를 위해 일했는데 결국 그에 대한 보답이 이건가?', `MaleText_loc4`='我已经为部落效力多年，立下无数功劳，而我现在只能受到这样的待遇？', `MaleText_loc5`='我多年來忠心耿耿效忠部落，這就是我獲得的下場?', `MaleText_loc7`='He servido a la Horda durante años, ¿y así es como me tratáis?', `FemaleText_loc1`='몇 년 동안 호드를 위해 일했는데 결국 그에 대한 보답이 이건가요?', `FemaleText_loc4`='我已经为部落效力多年，立下无数功劳，而我现在只能受到这样的待遇？', `FemaleText_loc5`='我多年來忠心耿耿效忠部落，這就是我獲得的下場?', `FemaleText_loc7`='He servido a la Horda durante años, ¿y así es como me tratáis?' WHERE `ID`=46617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지도자들은 왜 우리를 못 들어가게 하는 건가?', `MaleText_loc4`='为什么我们的领袖要把我们挡在外面？', `MaleText_loc5`='首領們為什麼把我們留在外面?', `MaleText_loc7`='¿Por qué nuestros líderes no nos dejan entrar?', `FemaleText_loc1`='지도자들은 왜 우리를 못 들어가게 하는 거요?', `FemaleText_loc4`='为什么我们的领袖要把我们挡在外面？', `FemaleText_loc5`='首領們為什麼把我們留在外面?', `FemaleText_loc7`='¿Por qué nuestros líderes no nos dejan entrar?' WHERE `ID`=46618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리한테 이럴 순 없다고!', `MaleText_loc4`='你们不能这样对待我们！', `MaleText_loc5`='你不能這樣對待我們!', `MaleText_loc7`='¡No pueden tratarnos así!', `FemaleText_loc1`='우리한테 이럴 순 없다고!', `FemaleText_loc4`='你们不能这样对待我们！', `FemaleText_loc5`='你不能這樣對待我們!', `FemaleText_loc7`='¡No pueden tratarnos así!' WHERE `ID`=46619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 말도 안 된다고!', `MaleText_loc4`='这太粗暴了！', `MaleText_loc5`='這太過份了!', `MaleText_loc7`='¡Esto es un ultraje!', `FemaleText_loc1`='이건 말도 안 된다고!', `FemaleText_loc4`='这太粗暴了！', `FemaleText_loc5`='這太過份了!', `FemaleText_loc7`='¡Esto es un ultraje!' WHERE `ID`=46620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주위엔 힘있는 친구들이 많은데, 내가 이런 대우를 받았다는 걸 알면 가만있지 않을 거요!', `MaleText_loc4`='我有掌握权柄的朋友。如果他们听到我被这样对待，肯定不会高兴的！', `MaleText_loc5`='我有很多位高權重的朋友，你們這樣對待我，他們可是會不高興的!', `MaleText_loc7`='Tengo amigos poderosos, ¡y no les gustará oír que me han tratado así!', `FemaleText_loc1`='내 주위엔 힘있는 친구들이 많은데, 내가 이런 대우를 받았다는 걸 알면 가만있지 않을 거요!', `FemaleText_loc4`='我有掌握权柄的朋友。如果他们听到我被这样对待，肯定不会高兴的！', `FemaleText_loc5`='我有很多位高權重的朋友，你們這樣對待我，他們可是會不高興的!', `FemaleText_loc7`='Tengo amigos poderosos, ¡y no les gustará oír que me han tratado así!' WHERE `ID`=46621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시오! 자기 차례를 기다리란 말이오...', `MaleText_loc4`='镇定！我们要尽快查清楚每一个人……', `MaleText_loc5`='冷靜!我們一定會照顧到大家...', `MaleText_loc7`='¡Cálmate! Atenderemos a todo el mundo...', `FemaleText_loc1`='진정하시오! 자기 차례를 기다리란 말이오...', `FemaleText_loc4`='镇定！我们要尽快查清楚每一个人……', `FemaleText_loc5`='冷靜!我們一定會照顧到大家...', `FemaleText_loc7`='¡Cálmate! Atenderemos a todo el mundo...' WHERE `ID`=46622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소리를 지르면 지를수록, 시간은 더 오래 걸릴 거요.', `MaleText_loc4`='你们大喊大叫只能耽误更多时间。', `MaleText_loc5`='你越是亂喊一通，我們就要花上越久的時間才能解決這件事。', `MaleText_loc7`='Cuanto más grites, más tardaremos en resolver esto.', `FemaleText_loc1`='소리를 지르면 지를수록, 시간은 더 오래 걸릴 거요.', `FemaleText_loc4`='你们大喊大叫只能耽误更多时间。', `FemaleText_loc5`='你越是亂喊一通，我們就要花上越久的時間才能解決這件事。', `FemaleText_loc7`='Cuanto más grites, más tardaremos en resolver esto.' WHERE `ID`=46623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히들 하시오! 어떻게든 최대한 빨리 해결해 볼 테니.', `MaleText_loc4`='不要吵！我们会尽快做好甄别工作。', `MaleText_loc5`='安靜一點!我們會盡快解決這件事情。', `MaleText_loc7`='¡Baja la voz! Lo arreglaremos en cuanto podamos.', `FemaleText_loc1`='조용히들 하시오! 어떻게든 최대한 빨리 해결해 볼 테니.', `FemaleText_loc4`='不要吵！我们会尽快做好甄别工作。', `FemaleText_loc5`='安靜一點!我們會盡快解決這件事情。', `FemaleText_loc7`='¡Baja la voz! Lo arreglaremos en cuanto podamos.' WHERE `ID`=46624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하지 않으면, 체포된 이교도와 같이 가둬둘 것이오!', `MaleText_loc4`='如果你们不安静些，你们就要和那些被拘捕的邪教徒关在一起了。', `MaleText_loc5`='你要是再不冷靜下來的話，你就得跟那些被逮捕的教徒窩在一起。', `MaleText_loc7`='Si no te tranquilizas, acabarás en el calabozo con los demás cultores arrestados.', `FemaleText_loc1`='진정하지 않으면, 체포된 이교도와 같이 가둬둘 것이오!', `FemaleText_loc4`='如果你们不安静些，你们就要和那些被拘捕的邪教徒关在一起了。', `FemaleText_loc5`='你要是再不冷靜下來的話，你就得跟那些被逮捕的教徒窩在一起。', `FemaleText_loc7`='Si no te tranquilizas, acabarás en el calabozo con los demás cultores arrestados.' WHERE `ID`=46625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시오, 형제자매여. 우리에게 소리를 지른다고 해결될 문제가 아니오!', `MaleText_loc4`='耐心一些，市民们。冲我们叫嚷不会让情况有任何改善。', `MaleText_loc5`='市民們，請有點耐性。對著我們大吼大叫是無法改變現狀的。', `MaleText_loc7`='Tened paciencia, ciudadanos. Gritarnos no va a cambiar nada.', `FemaleText_loc1`='진정하시오, 형제자매여. 우리에게 소리를 지른다고 해결될 문제가 아니오!', `FemaleText_loc4`='耐心一些，市民们。冲我们叫嚷不会让情况有任何改善。', `FemaleText_loc5`='市民們，請有點耐性。對著我們大吼大叫是無法改變現狀的。', `FemaleText_loc7`='Tened paciencia, ciudadanos. Gritarnos no va a cambiar nada.' WHERE `ID`=46626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 도시를 안전하게 지키기 위해 온 힘을 다하고 있는 거요!', `MaleText_loc4`='我们只是在采取必要措施确保城市的安全。', `MaleText_loc5`='我們這麼做只是為了確保本城的安全。', `MaleText_loc7`='Solo hacemos lo necesario para garantizar la seguridad de la ciudad.', `FemaleText_loc1`='우리는 도시를 안전하게 지키기 위해 온 힘을 다하고 있는 거요!', `FemaleText_loc4`='我们只是在采取必要措施确保城市的安全。', `FemaleText_loc5`='我們這麼做只是為了確保本城的安全。', `FemaleText_loc7`='Solo hacemos lo necesario para garantizar la seguridad de la ciudad.' WHERE `ID`=46627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절차를 빨리 끝내고 싶으면 서류를 미리 순서대로 준비해 두시오!', `MaleText_loc4`='如果你想要加快速度，那就认真准备好自己的文件！', `MaleText_loc5`='如果你想加快整個流程，請你先把相關的文件準備好。', `MaleText_loc7`='¡Si quieres agilizar el proceso, asegúrate de que tienes los papeles en regla!', `FemaleText_loc1`='절차를 빨리 끝내고 싶으면 서류를 미리 순서대로 준비해 두시오!', `FemaleText_loc4`='如果你想要加快速度，那就认真准备好自己的文件！', `FemaleText_loc5`='如果你想加快整個流程，請你先把相關的文件準備好。', `FemaleText_loc7`='¡Si quieres agilizar el proceso, asegúrate de que tienes los papeles en regla!' WHERE `ID`=46628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 날 보호해 줘야 한다고, $n. 난 무기도 토템도 없는 불쌍한 신세니까 말이야!', `MaleText_loc4`='你必须保护我，$n。没有了武器和图腾，我完全没有自卫的能力！', `MaleText_loc5`='你一定得要保護我，$n。少了我的武器和圖騰，我根本無力自保!', `MaleText_loc7`='Vas a tener que protegerme, $n. Sin mis armas y tótems, ¡estoy indefenso!' WHERE `ID`=46629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='란돌프 몰로크가 사라집니다!', `MaleText_loc4`='兰多菲·摩洛克消失了！', `MaleText_loc5`='藍道夫·摩洛克消失了!', `MaleText_loc7`='¡Randolph Moloch desaparece!' WHERE `ID`=46630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들창코가 분노합니다!', `MaleText_loc4`='霍格愤怒了！', `MaleText_loc5`='霍格狂暴了!', `MaleText_loc7`='¡Hogger entra en frenesí!' WHERE `ID`=46631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할타르가 죽었다! 나팔을 불어라! 이 기쁜 소식을 높은 둑에서 썬더마까지 퍼뜨려라!', `MaleText_loc4`='哈索尔死了！吹响号角，将消息从滩头堡传往桑德玛尔！', `MaleText_loc5`='哈爾薩爾死了!吹響號角，讓高岸堡到桑德瑪的人都知道這個消息!', `MaleText_loc7`='¡Halthar ha muerto! Tocad las trompetas, ¡y haced correr la noticia desde Bancalto hasta Bramal!', `FemaleText_loc1`='할타르가 죽었다! 나팔을 불어라! 이 기쁜 소식을 높은 둑에서 썬더마까지 퍼뜨려라!', `FemaleText_loc4`='哈索尔死了！吹响号角，将消息从滩头堡传往桑德玛尔！', `FemaleText_loc5`='哈爾薩爾死了!吹響號角，讓高岸堡到桑德瑪的人都知道這個消息!', `FemaleText_loc7`='¡Halthar ha muerto! Tocad las trompetas, ¡y haced correr la noticia desde Bancalto hasta Bramal!' WHERE `ID`=46632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 놈들 실력이 고작 이 정도라면, 황혼의 고원은 곧 우리 차지가 되겠군.', `MaleText_loc4`='如果这些矮人只能召集起这么一点力量，这座高地很快就会是我们的了。', `MaleText_loc5`='如果矮人們的本事就只有這樣的話，那麼高地很快就會是我們的了。', `MaleText_loc7`='Si esto es lo mejor que pueden hacer esos enanos, las Tierras Altas pronto serán nuestras.' WHERE `ID`=46633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 잘 살펴라. 멍청한 놈들이니 다시 공격해올지도 모른다.', `MaleText_loc4`='一定要注意监视这些道路。那些蠢货有可能会再次发动攻击。', `MaleText_loc5`='守好道路。他們說不定會蠢到又再發動一次攻擊。', `MaleText_loc7`='Vigilad los caminos. Puede que sean lo bastante estúpidos para intentar otro asalto.' WHERE `ID`=46634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 놈들은 이 광장을 끊임없이 공격하고 있소, $n. 하지만 놈들은 절대로 날 이길 수 없을 거요. 잘 보고 배우시오.', `MaleText_loc4`='蛮锤矮人不停地向这里发动猛攻，$n。但他们赢不了我。好好学着吧。', `MaleText_loc5`='蠻錘矮人的攻勢雖然兇猛，$n。但是他們永遠無法打敗我。好好見識見識。', `MaleText_loc7`='Los Martillo Salvaje han asaltado constantemente esta plaza, $n. Pero nunca me derrotarán. Mira y aprende.' WHERE `ID`=46635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... *콜록* 내 생명의 은인이시군요. 이방인이여, 감사합니다.', `MaleText_loc4`='我……*咳嗽*我欠你一条命，陌生人。谢谢你。', `MaleText_loc5`='我... *咳嗽* 我欠你一命，陌生人。謝謝你。', `MaleText_loc7`='Yo... *tose*, te debo la vida. Gracias.' WHERE `ID`=46636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안됐지만 네 친구는 당분간 깨어나지 못할 거다. 난 내 악어에게 줄 먹이는 항상 완전히 기절시켜 두거든. 모름지기 식사는 기분 좋게 해야 하니까 말이야.', `MaleText_loc4`='恐怕你的朋友不会很快就醒过来。我一直都把我的鳄鱼喂得很饱。我不喜欢看到它们为了食物而争斗。', `MaleText_loc5`='你朋友恐怕不會那麼快就醒來。通常我都會在我鱷魚的食物裡下藥，因為我不喜歡看他們掙扎的樣子。', `MaleText_loc7`='Me temo que tu amigo no se despertará pronto. Siempre sedo los alimentos de mis crocoliscos. Odio verles pelearse con la comida.' WHERE `ID`=46637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 너만은 예외로 삼아 주마. 악어들을 내보내라! 식사 시간이다!', `MaleText_loc4`='但也许我会给你一个例外。放鳄鱼出来！喂食时间到了！', `MaleText_loc5`='但也許我會對你破例。放鱷魚出來!餵食的時間到了!', `MaleText_loc7`='Pero quizá haga una excepción contigo. ¡Suelten a los crocoliscos! ¡ES HORA DE COMER!' WHERE `ID`=46638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝이냐? 이렇게 시시하게 끝내면 섭섭한데!', `MaleText_loc4`='就是这样？你要做到的不应该只有这些！', `MaleText_loc5`='就這樣?你的本事應該不只這樣吧!', `MaleText_loc7`='¿Eso es todo? ¡Tienes que tener algo mejor que eso!' WHERE `ID`=46639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 잠자는 케이든 둔왈트의 코털을 건드렸겠다!', `MaleText_loc4`='不要惹凯登·顿沃德生气！', `MaleText_loc5`='凱登·登瓦德不是好惹的!', `MaleText_loc7`='¡Nadie se mete con Cayden Montocre!' WHERE `ID`=46640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇! 분명히 어딘가엔 좀 남아 있을 텐데...', `MaleText_loc4`='呸！这里应该有一些的……', `MaleText_loc5`='哼!這邊一定還有才對...', `MaleText_loc7`='¡Bah! Tiene que haber algo por aquí...' WHERE `ID`=46641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둔왈트 가문의 그 하고많은 건물 중에서 왜 하필 여길 때려 부순 거냐고?!', `MaleText_loc4`='顿沃德有许多房子，为什么偏偏是这一座？！', `MaleText_loc5`='登瓦德這麼多房子，為什麼偏偏是這個?!', `MaleText_loc7`='De todos los edificios de Montocre, ¡¿por qué este?!' WHERE `ID`=46642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 심해도 너무 심하잖아! 황혼의 망치단 놈들, 오늘 이 짓의 대가를 치르게 될 거다!', `MaleText_loc4`='他们干得太过份了！今天一定要有一些暮光暴徒付出生命的代价！', `MaleText_loc5`='他們太過火了!今天暮光之錘的傢伙有人要死啦!', `MaleText_loc7`='¡Han ido demasiado lejos! ¡Hoy van a morir algunos Crepusculares!' WHERE `ID`=46643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주에 무슨 죄가 있다고?! 대체 왜 맥주를 건드린 거냐고?! 짐승 같은 놈들!', `MaleText_loc4`='啤酒？！为什么他们要毁掉这些啤酒？！怪物！', `MaleText_loc5`='酒?!他們為什麼要把酒給毀了?!可惡透了!', `MaleText_loc7`='¡¿La cerveza?! ¡¿Por qué destruirían la cerveza?! ¡Monstruos!' WHERE `ID`=46644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피도 눈물도 없는 맥주 혐오자, 야만적인 부랑아들 같으니! 내 눈에 띄면 가만두지 않겠어!', `MaleText_loc4`='没有灵魂的，不喜欢啤酒的，粗蠢的混蛋！你们可别让我看见！', `MaleText_loc5`='死沒靈魂的、討厭喝酒的、沒教養的混球!你最好躲遠一點!', `MaleText_loc7`='¡Malditos desalmados odiacerveza, vagabundos incultos! ¡Más os vale esconderos!' WHERE `ID`=46645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달콤하고 맛있는 내 맥주가... 전부... 없어졌어... 이런 끔찍한 일이...', `MaleText_loc4`='我甜美的啤酒啊……都没了……太恐怖了……', `MaleText_loc5`='我香甜美味的麥酒...全都沒了...太可怕了...', `MaleText_loc7`='Toda mi preciosa y dulce cerveza... desaparecida... el horror...' WHERE `ID`=46646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아... 목말라...', `MaleText_loc4`='真……渴啊……', `MaleText_loc5`='好...渴...啊...', `MaleText_loc7`='Tengo tanta... sed...' WHERE `ID`=46647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에오인, 여기 물이 찰랑거리는 우물이 있습니다만...', `MaleText_loc4`='伊欧因，那里有一口满是清水的井。', `MaleText_loc5`='伊歐因，那邊就有一口井。', `MaleText_loc7`='Eoin, hay un pozo lleno justo ahí.', `FemaleText_loc1`='에오인, 여기 물이 찰랑거리는 우물이 있습니다만...', `FemaleText_loc4`='伊欧因，那里有一口满是清水的井。', `FemaleText_loc5`='伊歐因，那邊就有一口井。', `FemaleText_loc7`='Eoin, hay un pozo lleno justo ahí.' WHERE `ID`=46648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이라고요?! 당신 바봅니까?! 난 맥주가 필요하다고요!', `MaleText_loc4`='水？！你疯了吗？！我要的是啤酒！', `MaleText_loc5`='水?!你耳朵聾啦?!我要的是酒!', `MaleText_loc7`='¡¿Agua?! ¡¿Es que eres idiota?! ¡Necesito CERVEZA!' WHERE `ID`=46649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 정말 받아들일 수 없습니다.', `MaleText_loc4`='我真没有必要这么听话。', `MaleText_loc5`='我不該遭受這種待遇的。', `MaleText_loc7`='No debería tener que someterme a esto.', `FemaleText_loc1`='이건 정말 받아들일 수 없어요.', `FemaleText_loc4`='我真没有必要这么听话。', `FemaleText_loc5`='我不該遭受這種待遇的。', `FemaleText_loc7`='No debería tener que someterme a esto.' WHERE `ID`=46650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 제가 왜 여기 와 있는지 설명할 수 있습니다.', `MaleText_loc4`='我可以解释自己为什么会在这里。', `MaleText_loc5`='我可以解釋我為什麼會在這裡。', `MaleText_loc7`='Puedo explicar por qué estoy aquí.', `FemaleText_loc1`='전 제가 왜 여기 와 있는지 설명할 수 있어요.', `FemaleText_loc4`='我可以解释自己为什么会在这里。', `FemaleText_loc5`='我可以解釋我為什麼會在這裡。', `FemaleText_loc7`='Puedo explicar por qué estoy aquí.' WHERE `ID`=46651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아무것도 감출 게 없소.', `MaleText_loc4`='我没有什么可隐瞒的。', `MaleText_loc5`='我沒什麼好隱瞞的。', `MaleText_loc7`='No tengo nada que ocultar.', `FemaleText_loc1`='전 아무것도 감출 게 없어요.', `FemaleText_loc4`='我没有什么可隐瞒的。', `FemaleText_loc5`='我沒什麼好隱瞞的。', `FemaleText_loc7`='No tengo nada que ocultar.' WHERE `ID`=46652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 서두를 수 없습니까? 저는 갈 곳이 있단 말입니다.', `MaleText_loc4`='你能快一点吗？我还要赶路呢。', `MaleText_loc5`='能不能快一點?我還得去別的地方。', `MaleText_loc7`='¿Podrías darte prisa? Tengo una cita.', `FemaleText_loc1`='좀 서두를 수 없나요? 저는 갈 곳이 있다고요.', `FemaleText_loc4`='你能快一点吗？我还要赶路呢。', `FemaleText_loc5`='能不能快一點?我還得去別的地方。', `FemaleText_loc7`='¿Podrías darte prisa? Tengo una cita.' WHERE `ID`=46653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 그럼 전 이만 가보겠습니다.', `MaleText_loc4`='谢谢你。我要上路了。', `MaleText_loc5`='謝謝你。我這就動身。', `MaleText_loc7`='Gracias, me voy ahora mismo.', `FemaleText_loc1`='고마워요. 그럼 전 이만 가볼게요.', `FemaleText_loc4`='谢谢你。我要上路了。', `FemaleText_loc5`='謝謝你。我這就動身。', `FemaleText_loc7`='Gracias, me voy ahora mismo.' WHERE `ID`=46654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 난 아무 짓도 안 했다고!', `MaleText_loc4`='这是什么？我什么都没做！', `MaleText_loc5`='這是怎麼回事?我什麼也沒做啊!', `MaleText_loc7`='¿Qué? ¡Yo no he hecho nada!', `FemaleText_loc1`='이게 뭐죠? 난 아무 짓도 안 했다고요!', `FemaleText_loc4`='这是什么？我什么都没做！', `FemaleText_loc5`='這是怎麼回事?我什麼也沒做啊!', `FemaleText_loc7`='¿Qué? ¡Yo no he hecho nada!' WHERE `ID`=46655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 시민 여러분, 여러분도 아시다시피 위협적인 이교도 집단이 우리의 도시를 파괴하려 하고 있습니다. 린 국왕 폐하께서는 이 이교도 집단이 모두 사라질 때까지 스톰윈드로 들어오고자 하는 모든 이들에게 수색과 심문에 응할 것을 명하셨습니다.', `MaleText_loc4`='暴风城的公民们，就像你们知道的那样，一个危险的邪教正在图谋颠覆我们的城市。乌瑞恩国王下达命令，在彻底摧毁那个邪教之前，要进入暴风城的人必须接受搜查和询问。', `MaleText_loc5`='暴風城的市民們，你們都知道，有個危險的邪教正陰謀不軌企圖破壞我們的城市。在徹底消滅這個邪教之前，烏瑞恩國王下令凡意圖進入暴風城的人都必須接受搜身與盤問。', `MaleText_loc7`='Ciudadanos de Ventormenta, como bien sabéis, una peligrosa secta amenaza con destruir nuestra ciudad. Hasta que hayamos acabado con dicho grupo, el rey Wrynn decreta que todos los que quieran entrar en Ventormenta tendrán que someterse a registros y preguntas.', `FemaleText_loc1`='스톰윈드 시민 여러분, 여러분도 아시다시피 위협적인 이교도 집단이 우리의 도시를 파괴하려 하고 있습니다. 린 국왕 폐하께서는 이 이교도 집단이 모두 사라질 때까지 스톰윈드로 들어오고자 하는 모든 이들에게 수색과 심문에 응할 것을 명하셨습니다.', `FemaleText_loc4`='暴风城的公民们，就像你们知道的那样，一个危险的邪教正在图谋颠覆我们的城市。乌瑞恩国王下达命令，在彻底摧毁那个邪教之前，要进入暴风城的人必须接受搜查和询问。', `FemaleText_loc5`='暴風城的市民們，你們都知道，有個危險的邪教正陰謀不軌企圖破壞我們的城市。在徹底消滅這個邪教之前，烏瑞恩國王下令凡意圖進入暴風城的人都必須接受搜身與盤問。', `FemaleText_loc7`='Ciudadanos de Ventormenta, como bien sabéis, una peligrosa secta amenaza con destruir nuestra ciudad. Hasta que hayamos acabado con dicho grupo, el rey Wrynn decreta que todos los que quieran entrar en Ventormenta tendrán que someterse a registros y preguntas.' WHERE `ID`=46656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 맥주에서 그 더러운 손을 치우지 못할까, 이 망할 맥주 혐오자 놈들아!', `MaleText_loc4`='别动我的啤酒，你这个肮脏的，不喜欢啤酒的怪物！', `MaleText_loc5`='別碰我的麥酒，骯髒下流的東西!', `MaleText_loc7`='¡Quiten sus manos de mi cerveza, miserables odia cervezas impuros!' WHERE `ID`=46658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 없군요. 들어가세요.', `MaleText_loc4`='一切正常，你可以走了。', `MaleText_loc5`='一切正常。你可以走了。', `MaleText_loc7`='Todo bien, puedes entrar.', `FemaleText_loc1`='이상 없군요. 들어가세요.', `FemaleText_loc4`='一切正常，你可以走了。', `FemaleText_loc5`='一切正常。你可以走了。', `FemaleText_loc7`='Todo bien, puedes entrar.' WHERE `ID`=46659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어가도 좋습니다.', `MaleText_loc4`='你可以进城了。', `MaleText_loc5`='你可以進城了。', `MaleText_loc7`='Puedes acceder a la ciudad.', `FemaleText_loc1`='들어가도 좋아요.', `FemaleText_loc4`='你可以进城了。', `FemaleText_loc5`='你可以進城了。', `FemaleText_loc7`='Puedes acceder a la ciudad.' WHERE `ID`=46660;
