UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 이교도의 로브 아닙니까! 경비병!', `MaleText_loc4`='这是一件邪教徒长袍，卫兵！', `MaleText_loc5`='那是教徒的衣服。守衛!', `MaleText_loc7`='Esa es una toga de cultor. ¡Guardia!', `FemaleText_loc1`='이건 이교도의 로브 아닌가요?! 경비병!', `FemaleText_loc4`='这是一件邪教徒长袍，卫兵！', `FemaleText_loc5`='那是教徒的衣服。守衛!', `FemaleText_loc7`='Esa es una toga de cultor. ¡Guardia!' WHERE `ID`=46664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 물건을 가지고 계시는군요. 당신은 들여보낼 수 없습니다.', `MaleText_loc4`='这看上去很可疑，我不能让你进城。', `MaleText_loc5`='這看起來有點可疑，我不能放你進去。', `MaleText_loc7`='Esto parece sospechoso. No puedo dejarte pasar.', `FemaleText_loc1`='수상한 물건을 가지고 계시는군요. 당신은 들여보낼 수 없습니다.', `FemaleText_loc4`='这看上去很可疑，我不能让你进城。', `FemaleText_loc5`='這看起來有點可疑，我不能放你進去。', `FemaleText_loc7`='Esto parece sospechoso. No puedo dejarte pasar.' WHERE `ID`=46665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 이교도의 문학 작품이군요. 당신이 스톰윈드에 들어갈 방법은 수갑을 차고 들어가는 방법뿐입니다.', `MaleText_loc4`='这是邪教文书。我要用锁链捆住你，再把你牵进暴风城。', `MaleText_loc5`='這是邪教的文獻。你等著被銬押進暴風城吧。', `MaleText_loc7`='Esto es un texto de cultor. Solo entrarás en Ventormenta con esposas.', `FemaleText_loc1`='이건 이교도의 문학 작품이군요. 당신이 스톰윈드에 들어갈 방법은 수갑을 차고 들어가는 방법뿐입니다.', `FemaleText_loc4`='这是邪教文书。我要用锁链捆住你，再把你牵进暴风城。', `FemaleText_loc5`='這是邪教的文獻。你等著被銬押進暴風城吧。', `FemaleText_loc7`='Esto es un texto de cultor. Solo entrarás en Ventormenta con esposas.' WHERE `ID`=46666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단 메달? 경비병!', `MaleText_loc4`='暮光之锤的徽章？卫兵！', `MaleText_loc5`='暮光之錘的勳章?守衛!', `MaleText_loc7`='¿Un medallón del Martillo Crepuscular? ¡Guardia!', `FemaleText_loc1`='황혼의 망치단 메달? 경비병!', `FemaleText_loc4`='暮光之锤的徽章？卫兵！', `FemaleText_loc5`='暮光之錘的勳章?守衛!', `FemaleText_loc7`='¿Un medallón del Martillo Crepuscular? ¡Guardia!' WHERE `ID`=46667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 이교도의 선전물 아닙니까! 당신을 체포합니다.', `MaleText_loc4`='这是邪教的宣传文稿。你被捕了。', `MaleText_loc5`='邪教的宣傳品。你被逮捕了!', `MaleText_loc7`='Esto es propaganda de los cultores. Estás bajo arresto.', `FemaleText_loc1`='이건 이교도의 선전물 아닙니까! 당신을 체포합니다.', `FemaleText_loc4`='这是邪教的宣传文稿。你被捕了。', `FemaleText_loc5`='邪教的宣傳品。你被逮捕了!', `FemaleText_loc7`='Esto es propaganda de los cultores. Estás bajo arresto.' WHERE `ID`=46668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이교도의 물건을 가지고 있어서 도시로 들여보낼 수 없습니다.', `MaleText_loc4`='你竟然私带邪教文卷，我不能让你进城。', `MaleText_loc5`='你身上有教徒的東西，我不能夠放你進城。', `MaleText_loc7`='No puedo dejarte entrar en la ciudad con estos artículos de cultor.', `FemaleText_loc1`='당신은 이교도의 물건을 가지고 있어서 도시로 들여보낼 수 없습니다.', `FemaleText_loc4`='你竟然私带邪教文卷，我不能让你进城。', `FemaleText_loc5`='你身上有教徒的東西，我不能夠放你進城。', `FemaleText_loc7`='No puedo dejarte entrar en la ciudad con estos artículos de cultor.' WHERE `ID`=46669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수상한 쪽지는 뭐죠? 경비병, 이 사람을 감금하세요.', `MaleText_loc4`='这些可疑的文件是什么？卫兵，监押这个人。', `MaleText_loc5`='這些可疑的文件是什麼?衛兵，把這位市民拘留起來。', `MaleText_loc7`='¿Qué son estos papeles sospechosos? Guardia, arresta a este ciudadano.', `FemaleText_loc1`='이 수상한 쪽지는 뭐죠? 경비병, 이 사람을 감금하세요.', `FemaleText_loc4`='这些可疑的文件是什么？卫兵，监押这个人。', `FemaleText_loc5`='這些可疑的文件是什麼?衛兵，把這位市民拘留起來。', `FemaleText_loc7`='¿Qué son estos papeles sospechosos? Guardia, arresta a este ciudadano.' WHERE `ID`=46670;
