UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 돈이 얼마나 되는지 고블린에게 세어보라고는 해도, 지키라고는 하지 말게.', `MaleText_loc4`='地精可以帮你把钱数得一清二楚，但你绝对要小心他们。', `MaleText_loc5`='你可以放心讓哥布林幫你數錢，只是不能放心讓他們幫你保管。', `MaleText_loc7`='Puedes confiar en un goblin para CONTAR tus monedas, pero no para CUIDARLAS.', `FemaleText_loc1`='자네 돈이 얼마나 되는지 고블린에게 세어보라고는 해도, 지키라고는 하지 말게.', `FemaleText_loc4`='地精可以帮你把钱数得一清二楚，但你绝对要小心他们。', `FemaleText_loc5`='你可以放心讓哥布林幫你數錢，只是不能放心讓他們幫你保管。', `FemaleText_loc7`='Puedes confiar en un goblin para CONTAR tus monedas, pero no para CUIDARLAS.' WHERE `ID`=46682;
