UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 이겼다고 생각하지 마라.', `MaleText_loc4`='不要以为你们已经赢了。', `MaleText_loc5`='別以為你們已經贏了。', `MaleText_loc7`='No os penséis que habéis ganado.' WHERE `ID`=46685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시는 무너질 것이다!', `MaleText_loc4`='这座城市即将陷落！', `MaleText_loc5`='這座城終將陷落!', `MaleText_loc7`='¡Esta ciudad caerá!' WHERE `ID`=46686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 손 놓아라! 더러운 충복 같으니.', `MaleText_loc4`='别碰我，你们这些愚忠的渣滓。', `MaleText_loc5`='放開我，死忠的走狗。', `MaleText_loc7`='Quítame las manos de encima, escoria del gobierno.' WHERE `ID`=46687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 안돼요. 멍청한 $r 같으니...', `FemaleText_loc4`='不，不，蠢$r……', `FemaleText_loc5`='不，不，你這笨$r...', `FemaleText_loc7`='No, no, $gestúpido:estúpida; $r...' WHERE `ID`=46688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹부인은 아무도 탈 수 없어요!', `FemaleText_loc4`='没人能骑我的驼背淑女！', `FemaleText_loc5`='沒有人可以搭乘女士號!', `FemaleText_loc7`='¡Nadie monta a Lady!' WHERE `ID`=46689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 받은 후 누군가 여기 피신했던 것 같지만, 부리부리의 흔적은 없습니다.', `MaleText_loc4`='在那次攻击之后，有些人逃难到了这里，但他们之中并没有尖喙。', `MaleText_loc5`='攻擊結束後有人在這裡躲了一會兒，但還是沒有比克的蹤影。', `MaleText_loc7`='Alguien se refugió aquí tras el ataque, pero no hay señales de Pico.' WHERE `ID`=46690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청난 학살의 흔적이 여기저기 남아 있지만, 부리부리의 흔적은 없습니다.', `MaleText_loc4`='这里满是血腥之气。但没有尖喙的踪迹。', `MaleText_loc5`='這裡血腥味好重。沒有比克的蹤影。', `MaleText_loc7`='Esta sala apesta a masacre. No hay rastro de Pico.' WHERE `ID`=46691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽 건물들은 완전히 폐허가 되었습니다. 부리부리가 숨을 곳은 없어 보입니다.', `MaleText_loc4`='这些建筑物完全被毁了。尖喙不可能藏身在这里。', `MaleText_loc5`='這整棟建築全都毀了。這兒沒有比克可以躲的地方。', `MaleText_loc7`='Estos edificios están totalmente destruidos. No hay ningún sitio en el que Pico pudiera estar escondiéndose.' WHERE `ID`=46692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야! 어디 있어, 부리부리야?', `MaleText_loc4`='尖喙！你在哪里，尖喙？', `MaleText_loc5`='比克!你在哪裡，比克?', `MaleText_loc7`='¡Pico! ¿Dónde estás, Pico?' WHERE `ID`=46693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야! 도넬리한테 돌아와. 도넬리가 지켜 줄게!', `MaleText_loc4`='尖喙！到东尼利这里来。东尼利会保护你！', `MaleText_loc5`='比克!回來找多涅爾利。多涅爾利會保護你!', `MaleText_loc7`='¡Pico! Vuelve con Donnelly. ¡Donnelly te mantendrá a salvo!' WHERE `ID`=46694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아와, 부리부리야! 다치면 안 돼!', `MaleText_loc4`='回来，尖喙！不要受伤了！', `MaleText_loc5`='回來啊，比克!不要受傷了啊!', `MaleText_loc7`='¡Vuelve, Pico! ¡No te hagas daño!' WHERE `ID`=46695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야! 제발 숨지 마. 어서 나오라고!', `MaleText_loc4`='尖喙！不要再躲着了。现在就出来！', `MaleText_loc5`='比克!不要再躲了。立刻就出來!', `MaleText_loc7`='¡Pico! Ya basta de esconderse. ¡Sal ahora mismo!' WHERE `ID`=46696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 동행이 생긴 것 같습니다. 부리부리를 도넬리에게 데려다 줘야겠습니다.', `MaleText_loc4`='你似乎是有了一名同伴。你应该带他回东尼利那里去。', `MaleText_loc5`='你好像結識了一位夥伴。你應該帶他回去找多涅爾利。', `MaleText_loc7`='Parece que te has encontrado un compañero. Deberías llevárselo de vuelta a Donnelly.' WHERE `ID`=46697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 드워프의 시체는 심하게 손상되어 있습니다. 황혼의 망치단은 살육을 즐기는 게 분명합니다.', `MaleText_loc4`='这具矮人的尸体被严重地损毁了。暮光之锤一定都是些以屠杀为乐的疯子。', `MaleText_loc5`='這個矮人死狀十分悽慘，暮光之錘的人必定以凌虐他為樂。', `MaleText_loc7`='El cuerpo de este enano está gravemente apaleado. Está claro que el Martillo Crepuscular se ensaña cuando mata.', `FemaleText_loc1`='이 드워프의 시체는 심하게 손상되어 있습니다. 황혼의 망치단은 살육을 즐기는 게 분명합니다.', `FemaleText_loc4`='这具矮人的尸体被严重地损毁了。暮光之锤一定都是些以屠杀为乐的疯子。', `FemaleText_loc5`='這個矮人死狀十分悽慘，暮光之錘的人必定以凌虐他為樂。', `FemaleText_loc7`='El cuerpo de este enano está gravemente apaleado. Está claro que el Martillo Crepuscular se ensaña cuando mata.' WHERE `ID`=46698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 $c|1을;를; 없애라!', `MaleText_loc4`='消灭联盟$c！', `MaleText_loc5`='殺掉聯盟的$c!', `MaleText_loc7`='¡Matad $gal:a la; $c de la Alianza!', `FemaleText_loc1`='여기 얼라이언스 $c|1이;가; 있다!', `FemaleText_loc4`='这边——这里有个联盟$c！', `FemaleText_loc5`='在那邊--聯盟的$c!', `FemaleText_loc7`='¡Allí! ¡$gUn:Una; $c de la Alianza!' WHERE `ID`=46699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 황혼의 망치단 자식들, 조금은 인정해 줘야겠습니다... 기술은 없어도 머릿수를 믿고 끈질기게 밀어붙이더군요. 마지막으로 우리와 한바탕 할 땐 봐줄 만했습니다.', `MaleText_loc4`='我必须承认那些暮光暴徒并非无能之辈……也许他们缺乏战斗技巧，但他们的数量和坚韧完全可以弥补这个缺陷。在我们的上一次战斗中，他们的确取得了一些战果。', `MaleText_loc5`='不得不承認暮光之錘的這些傢伙是有本事...他們雖然戰技很差，數量和決心倒是很驚人。在我們上次交手的時候，他們狠狠地佔了我們一次上風。', `MaleText_loc7`='La verdad es que tengo que reconocer los méritos de esos Crepusculares... Lo que carecen en habilidad, lo suplen con su tenacidad y su número. Nos han hecho sudar en la última pelea.' WHERE `ID`=46700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 둔왈트 드워프는 돌처럼 굳건합니다. 문제는 몸만 그런 게 아니라 머리도 그런 경향이 있다는 거죠. 제 형제들이 종종 이 명성을 드높이려 들어서 골치가 아파요.', `FemaleText_loc4`='顿沃德家族以刚强悍勇著称，但他们的脑子并不怎么灵光。我很担心我的兄弟们会把他们的名誉和生命浪费在一些不必要的地方。', `FemaleText_loc5`='登瓦德家的人都是硬漢，連腦袋瓜也特別「硬」。我擔心我家兄弟拿他們名聲當賭注的頻率未免稍微太高了一些些。', `FemaleText_loc7`='La familia Montocre es muy dura, pero dejan que se les suba a la cabeza. Me temo que mis hermanos ponen a prueba su reputación demasiado a menudo.' WHERE `ID`=46701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 일해라, 검은무쇠 돼지들아!', `MaleText_loc4`='工作卖力一些，黑铁狗子们！', `MaleText_loc5`='給我認真一點，黑鐵雜種!', `MaleText_loc7`='¡Trabajen más duro, perros Hierro Negro!' WHERE `ID`=46702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘레멘티움을 더 캐라고! 당장!', `MaleText_loc4`='我还要更多源质！动作快一点！', `MaleText_loc5`='還要更多的源質礦!動作快!', `MaleText_loc7`='¡Más elementium! ¡Ya!' WHERE `ID`=46703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈 님이 네놈들의 작고 연약한 몸뚱이를 괴롭히며 즐거워하실 것이다!', `MaleText_loc4`='古加尔会大笑着把你生吞活剥！', `MaleText_loc5`='丘加利會把你的心臟從你卑微渺小的身子挖出來，一邊笑一邊吃掉!', `MaleText_loc7`='¡Cho''gall te arrancará el corazón de tu cuerpo pequeño y esmirriado y se reirá mientras se lo come!' WHERE `ID`=46704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업 속도를 높이지 않으면 네놈들의 몸뚱이를 잿더미로 만들어 버리겠다!', `MaleText_loc4`='如果你们再这样慢吞吞的，我就把你们变成一堆灰烬！', `MaleText_loc5`='再不加緊工作，我就要把你化成灰燼!', `MaleText_loc7`='¡Te reduciré a cenizas si no trabajas más rápido!' WHERE `ID`=46705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미가 엘레멘티움을 먹어치우게 두지 마라!', `MaleText_loc4`='不要让那些蜘蛛把源质吃掉！', `MaleText_loc5`='別讓那些蜘蛛把源質礦吃了!', `MaleText_loc7`='¡No dejes que esas arañas se coman el elementium!' WHERE `ID`=46706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 그래, 너 말이다! 이리 와라. 당장 파묻어 주겠어!', `MaleText_loc4`='嗨，你！是的，就是你！到这里来。我要把你活埋！', `MaleText_loc5`='我看到你了!沒錯，就是你!過來，我要把你給埋了!', `MaleText_loc7`='¡Te veo! ¡Sí, a ti! Ven aquí. ¡Voy a enterrarte!' WHERE `ID`=46707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 요새에 엘레멘티움을 더 많이 바쳐야 한다!', `MaleText_loc4`='暮光堡垒需要更多源质！', `MaleText_loc5`='為暮光堡壘挖更多的源質礦!', `MaleText_loc7`='¡Más elementium para El Bastión del Crepúsculo!' WHERE `ID`=46708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 드워프 놈들이 잘하는 거라곤 채광뿐이지!', `MaleText_loc4`='你们这帮矮人只配挖矿！', `MaleText_loc5`='你們矮人不是最會挖礦的嗎!', `MaleText_loc7`='¡La minería es lo único para lo que servís los enanos!' WHERE `ID`=46709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르의 아들이 당신을 도와 주러 왔습니다. 하지만 그가 던지는 바위는 조심하십시오.', `MaleText_loc4`='一个柯尔之子来帮助你了，但你要小心他的大石头！', `MaleText_loc5`='一位柯爾之子前來協助你了，請小心他的巨石!', `MaleText_loc7`='Un Hijo de Kor ha venido para ayudarte, ¡pero cuidado con sus rocas!' WHERE `ID`=46710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s|1이;가; |cFFFF0000|Hspell:86840|h[파멸의 불길]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s开始施放|cFFFF0000|Hspell:86840|h[噬体烈焰]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s開始施展|cFFFF0000|Hspell:86840|h[吞噬烈焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightflamebreath.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:86840|h[Llamas devoradoras]|h|r!' WHERE `ID`=46711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s|1이;가; |cFFFF0000|Hspell:86059|h[깊은 숨]|h|r을 들이쉽니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s进行了一次|cFFFF0000|Hspell:86059|h[深呼吸]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s開始進行|cFFFF0000|Hspell:86059|h[深呼吸]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightfire.blp:20|t¡%s toma un |cFFFF0000|Hspell:86059|h[Aliento profundo]|h|r!' WHERE `ID`=46712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s|1이;가; |cFF00EEFF|Hspell:86622|h[사로잡힌 마법]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s开始施放|cFF00EEFF|Hspell:86622|h[噬体魔法]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s開始施展|cFF00EEFF|Hspell:86622|h[侵噬魔法]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_holy_consumemagic.blp:20|t¡%s comienza a lanzar |cFF00EEFF|Hspell:86622|h[Trago de magia]|h|r!' WHERE `ID`=46713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s|1이;가; |cFF00EEFF|Hspell:86408|h[현란한 파괴]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s开始施放|cFF00EEFF|Hspell:86408|h[眩光毁灭]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s開始施展|cFF00EEFF|Hspell:86408|h[炫光毀滅]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightpyroblast.blp:20|t¡%s comienza a lanzar |cFF00EEFF|Hspell:86408|h[Destrucción deslumbrante]|h|r!' WHERE `ID`=46714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='喂！', `MaleText_loc5`='喂!', `MaleText_loc7`='¡Ah del barco!' WHERE `ID`=46715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 우리 형제들은 빨리 싸우고 싶어 몸이 근질근질한가 봅니다. 이만큼 기다리게 하는 것도 보통 일이 아니었습니다.$B$B자, 함께 싸우실 거죠?', `MaleText_loc4`='哈！我的兄弟们正渴望着一战。我已经无法再阻止他们了。$B$B你要参加这一战吗？', `MaleText_loc5`='哈!我的弟兄們早就迫不及待想動手了，我可是好不容易才叫他們忍到現在這麼久。$B$B也要算你一份嗎?', `MaleText_loc7`='¡Ja! Mis hermanos se mueren de ganas de pelear. Apenas he conseguido contenerlos hasta ahora.$b$b¿Te apuntas?' WHERE `ID`=46716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단을 둔왈트답게 환영해 주자고, 형제들!', `MaleText_loc4`='兄弟们，让我们给他一个正式的顿沃德式欢迎！', `MaleText_loc5`='兄弟們，讓他們見識見識，什麼叫登瓦德式的歡迎!', `MaleText_loc7`='¡Vamos a darles una bienvenida propia de los Montocre, hermanos!' WHERE `ID`=46717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하죠.', `MaleText_loc4`='我参加。', `MaleText_loc5`='也算我一份。', `MaleText_loc7`='Me apunto.', `FemaleText_loc1`='당연하죠.', `FemaleText_loc4`='我参加。', `FemaleText_loc5`='也算我一份。', `FemaleText_loc7`='Me apunto.' WHERE `ID`=46718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 알려 주십시오. 빠를수록 좋습니다... 케이든이 좀 사나워진 것 같아서요.', `MaleText_loc4`='准备好以后就告诉我。越快越好——凯登已经有些迫不及待了。', `MaleText_loc5`='準備好了就跟我說一聲。越快越好，凱登看起來有點兇。', `MaleText_loc7`='Avísame cuando estés $glisto:lista;. Mejor temprano que tarde, Cayden tiene una pinta un poco agresiva.' WHERE `ID`=46719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 그리 쉽게 잡을 순 없을 거다! 아탈라이가 일어날 테니...', `MaleText_loc4`='别想这么容易就抓住我！阿塔莱即将崛起……', `MaleText_loc5`='要打敗我沒那麼容易!阿塔萊即將再起...', `MaleText_loc7`='¡No vas a cogerme tan rápi''o! Atal''ai se alzará...' WHERE `ID`=46720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀의 왕을 무찌르시다니, 당신들은 진정한 영웅입니다. 엘윈 숲과 서부 몰락지대에 사는 모든 사람이 앞으로 오랫동안 당신의 승리를 칭송할 것입니다. 감사합니다.', `MaleText_loc4`='你们竟然战胜了豺狼人之王。你们真是伟大的英雄。在今后的许多年中，全艾尔文森林和西部荒野的人都会津津乐道你们的伟大胜利。谢谢你们。', `MaleText_loc5`='你真是個偉大的英雄!你消滅那隻豺狼人之王的英雄事蹟必將在艾爾文森林和西部荒野的百姓口中傳頌多年。謝謝你。', `MaleText_loc7`='Son realmente unos grandes héroes por haber derrotado al rey de los gnolls. Por todo el Bosque de Elwynn y los Páramos de Poniente la gente ensalzará su triunfo durante años. Gracias.' WHERE `ID`=46721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 모두 다시 작업을 시작해라!', `MaleText_loc4`='赶快回去工作！', `MaleText_loc5`='大家回去工作吧!', `MaleText_loc7`='¡Volvamos al trabajo, gente!', `FemaleText_loc1`='자, 모두 다시 작업을 시작해라!', `FemaleText_loc4`='赶快回去工作！', `FemaleText_loc5`='大家回去工作吧!', `FemaleText_loc7`='¡Volvamos al trabajo, gente!' WHERE `ID`=46722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배는 저절로 만들어지는 게 아니다!', `MaleText_loc4`='这些船可不会自行完成建造！', `MaleText_loc5`='這些船可不會自動拼裝建造起來!', `MaleText_loc7`='¡Esos barcos no se van a construir solos!', `FemaleText_loc1`='배는 저절로 만들어지는 게 아니다!', `FemaleText_loc4`='这些船可不会自行完成建造！', `FemaleText_loc5`='這些船可不會自動拼裝建造起來!', `FemaleText_loc7`='¡Esos barcos no se van a construir solos!' WHERE `ID`=46723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작업장에서는 최고 품질의 결과물만 용납된다. 업무량을 두 배로 늘려라!', `MaleText_loc4`='我期待着我的工人们能够显示出最杰出的造船工艺。给我加倍拿出力量来！', `MaleText_loc5`='我希望我的手下們能做出最精良的品質。加倍努力!', `MaleText_loc7`='Exijo artesanía de la más alta calidad a mi personal. ¡Redobla tus esfuerzos!', `FemaleText_loc1`='내 작업장에서는 최고 품질의 결과물만 용납된다. 업무량을 두 배로 늘려라!', `FemaleText_loc4`='我期待着我的工人们能够显示出最杰出的造船工艺。给我加倍拿出力量来！', `FemaleText_loc5`='我希望我的手下們能做出最精良的品質。加倍努力!', `FemaleText_loc7`='Exijo artesanía de la más alta calidad a mi personal. ¡Redobla tus esfuerzos!' WHERE `ID`=46724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 종말이 다가오고 있다.', `MaleText_loc4`='你的时间就要结束了。', `MaleText_loc5`='你的死期到了。', `MaleText_loc7`='Tu tiempo se acaba.', `FemaleText_loc1`='너희의 종말이 다가오고 있다.', `FemaleText_loc4`='你的时间就要结束了。', `FemaleText_loc5`='你的死期到了。', `FemaleText_loc7`='Tu tiempo se acaba.' WHERE `ID`=46725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맘대로 생각해라, 하지만 내 말이 옳았다는 것을 알게 될 것이다.', `MaleText_loc4`='随你怎么想吧，但你会看到，我才是对的。', `MaleText_loc5`='你儘管笑吧，待會兒你就知道我們講的一點也沒錯。', `MaleText_loc7`='Ríete todo lo que quieras, pero acabarás por ver que teníamos razón.', `FemaleText_loc1`='맘대로 생각해라, 하지만 내 말이 옳았다는 것을 알게 될 것이다.', `FemaleText_loc4`='随你怎么想吧，但你会看到，我才是对的。', `FemaleText_loc5`='你儘管笑吧，待會兒你就知道我們講的一點也沒錯。', `FemaleText_loc7`='Ríete todo lo que quieras, pero acabarás por ver que teníamos razón.' WHERE `ID`=46726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 비록 지금 실패했지만, 나의 주인님께서 이 도시에 복수의 비를 내리실 때 다시 날 자유롭게 하시리라.', `MaleText_loc4`='也许我现在是陷入了困境，但是当主人的复仇之雨在这座城市上洒落的时候，我必将重获自由。', `MaleText_loc5`='雖然現在我被困住了，但是等我的主人在這座城降下毀滅之時，他就會還我自由。', `MaleText_loc7`='Puede que ahora esté atado, pero mi maestro me liberará cuando su venganza arrase esta ciudad.', `FemaleText_loc1`='나는 비록 지금 실패했지만, 나의 주인님께서 이 도시에 복수의 비를 내리실 때 다시 날 자유롭게 하시리라.', `FemaleText_loc4`='也许我现在是陷入了困境，但是当主人的复仇之雨在这座城市上洒落的时候，我必将重获自由。', `FemaleText_loc5`='雖然現在我被困住了，但是等我的主人在這座城降下毀滅之時，他就會還我自由。', `FemaleText_loc7`='Puede que ahora esté atada, pero mi maestro me liberará cuando su venganza arrase esta ciudad.' WHERE `ID`=46727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 승천의 길을 걷고 있다. 하찮고 야심 찬 영웅이 나를 멈출 수는 없다.', `MaleText_loc4`='我已经踏上成神的道路，那种狂妄而卑微的英雄不可能阻挡我。', `MaleText_loc5`='我已踏上超越凡俗之道，絕不容你這等懷抱英雄夢的傢伙來阻止我。', `MaleText_loc7`='Estoy en el camino de la ascensión, y ningún aspirante a héroe me detendrá.', `FemaleText_loc1`='나는 승천의 길을 걷고 있다. 하찮고 야심 찬 영웅이 나를 멈출 수는 없다.', `FemaleText_loc4`='我已经踏上成神的道路，那种狂妄而卑微的英雄不可能阻挡我。', `FemaleText_loc5`='我已踏上超越凡俗之道，絕不容你這等懷抱英雄夢的傢伙來阻止我。', `FemaleText_loc7`='Estoy en el camino de la ascensión, y ningún aspirante a héroe me detendrá.' WHERE `ID`=46728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝나는 건 너의 삶이다. 내 삶은 이제부터 시작이다.', `MaleText_loc4`='你的生命即将终结，而我的则刚刚开始。', `MaleText_loc5`='死期將近的人是你，我的命還長著呢。', `MaleText_loc7`='Es tu vida la que está a punto de terminar; la mía no ha hecho más que empezar.', `FemaleText_loc1`='끝나는 건 너의 삶이다. 내 삶은 이제부터 시작이다.', `FemaleText_loc4`='你的生命即将终结，而我的则刚刚开始。', `FemaleText_loc5`='死期將近的人是你，我的命還長著呢。', `FemaleText_loc7`='Es tu vida la que está a punto de terminar; la mía no ha hecho más que empezar.' WHERE `ID`=46729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 풀어놓은 비전 마력을 억눌려야 합니다!', `MaleText_loc4`='我们必须控制住被我们释放出来的奥术能量。', `MaleText_loc5`='我們得控制住先前被我們給釋放出來的秘法能量!', `MaleText_loc7`='¡Debemos contener el poder Arcano que hemos liberado!', `FemaleText_loc1`='우리가 풀어놓은 비전 마력을 억눌려야 합니다!', `FemaleText_loc4`='我们必须控制住被我们释放出来的奥术能量。', `FemaleText_loc5`='我們得控制住先前被我們給釋放出來的秘法能量!', `FemaleText_loc7`='¡Debemos contener el poder Arcano que hemos liberado!' WHERE `ID`=46730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력이 더 생성되는 걸 그냥 둘 순 없습니다!', `MaleText_loc4`='我们不能让奥术能量进一步积累了！', `MaleText_loc5`='不能讓秘法能量再繼續累積下去了!', `MaleText_loc7`='¡No podemos permitir que el poder Arcano se acumule aún más!', `FemaleText_loc1`='비전 마력이 더 생성되는 걸 그냥 둘 순 없습니다!', `FemaleText_loc4`='我们不能让奥术能量进一步积累了！', `FemaleText_loc5`='不能讓秘法能量再繼續累積下去了!', `FemaleText_loc7`='¡No podemos permitir que el poder Arcano se acumule aún más!' WHERE `ID`=46731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프나 악마들이 눈치채기 전에 그 마법을 흘러버려야 합니다.', `MaleText_loc4`='我们必须在精灵或魔鬼注意到这股能量之前让它消散。', `MaleText_loc5`='必須在這股能量被精靈或惡魔察覺之前，把它消散掉。', `MaleText_loc7`='Debemos disipar este poder antes de que lo perciban los elfos o los demonios.', `FemaleText_loc1`='엘프나 악마들이 눈치채기 전에 그 마법을 흘러버려야 해요.', `FemaleText_loc4`='我们必须在精灵或魔鬼注意到这股能量之前让它消散。', `FemaleText_loc5`='必須在這股能量被精靈或惡魔察覺之前，把它消散掉。', `FemaleText_loc7`='Debemos disipar este poder antes de que lo perciban los elfos o los demonios.' WHERE `ID`=46732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 진실을 깨닫는 순간에는 이미 늦었을 것이다.', `MaleText_loc4`='当你察觉到真实情况的时候，一切都已经太晚了。', `MaleText_loc5`='等你發覺真相的時候就已經太遲了。', `MaleText_loc7`='Para cuando comprendas la verdad ya será demasiado tarde.', `FemaleText_loc1`='네가 진실을 깨닫는 순간에는 이미 늦었을 것이다.', `FemaleText_loc4`='当你察觉到真实情况的时候，一切都已经太晚了。', `FemaleText_loc5`='等你發覺真相的時候就已經太遲了。', `FemaleText_loc7`='Para cuando comprendas la verdad ya será demasiado tarde.' WHERE `ID`=46733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 약해지고 있다. 날 지원하라, 형제들이여!', `MaleText_loc4`='我的力量正在消褪……兄弟们，支援我！', `MaleText_loc5`='我的力量衰減了!兄弟們，快來支援我!', `MaleText_loc7`='Mi poder se debilita... ¡Ayudadme, hermanos!', `FemaleText_loc1`='내 힘이 약해지고 있다. 날 지원하라, 형제들이여!', `FemaleText_loc4`='我的力量正在消褪……兄弟们，支援我！', `FemaleText_loc5`='我的力量衰減了!兄弟們，快來支援我!', `FemaleText_loc7`='Mi poder se debilita... ¡Ayudadme, hermanos!' WHERE `ID`=46734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에서 당신네는 뭘 하고 있었던 겁니까?', `MaleText_loc4`='你们在这座城市里做些什么？', `MaleText_loc5`='你和其他人在城裡做什麼?', `MaleText_loc7`='¿Qué estabais haciendo dentro de la ciudad?', `FemaleText_loc1`='도시에서 당신네는 뭘 하고 있었던 겁니까?', `FemaleText_loc4`='你们在这座城市里做些什么？', `FemaleText_loc5`='你和其他人在城裡做什麼?', `FemaleText_loc7`='¿Qué estabais haciendo dentro de la ciudad?' WHERE `ID`=46735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란을 옮기는 데 필요했던 마법은 너무 컸습니다! 영원히 그 마법을 억제할 순 없습니다.', `MaleText_loc4`='移动达拉然的魔法太强大了！我们没办法一直压制住它！', `MaleText_loc5`='移動達拉然所耗費的魔力太過龐大了!我們無法永遠抑止住它!', `MaleText_loc7`='¡La magia necesaria para trasladar Dalaran fue demasiada! ¡No podemos retenerlo eternamente!', `FemaleText_loc1`='달라란을 옮기는 데 필요했던 마법은 너무 컸어요! 영원히 그 마법을 억제할 순 없어요.', `FemaleText_loc4`='移动达拉然的魔法太强大了！我们没办法一直压制住它！', `FemaleText_loc5`='移動達拉然所耗費的魔力太過龐大了!我們無法永遠抑止住它!', `FemaleText_loc7`='¡La magia necesaria para trasladar Dalaran fue demasiada! ¡No podemos retenerlo eternamente!' WHERE `ID`=46736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란의 마법사들은 아제로스에서 가장 강력합니다! 우린 패하지 않을 겁니다!', `MaleText_loc4`='达拉然的法师们是艾泽拉斯最强大的法师！我们不会失败的！', `MaleText_loc5`='達拉然的魔法師是全艾澤拉斯最強大的!我們絕不會失敗!', `MaleText_loc7`='¡Los magos de Dalaran son los más poderosos de todo Azeroth! ¡No podemos fracasar!', `FemaleText_loc1`='달라란의 마법사들은 아제로스에서 가장 강력해요! 우린 패하지 않을 거예요!', `FemaleText_loc4`='达拉然的法师们是艾泽拉斯最强大的法师！我们不会失败的！', `FemaleText_loc5`='達拉然的魔法師是全艾澤拉斯最強大的!我們絕不會失敗!', `FemaleText_loc7`='¡Los magos de Dalaran son los más poderosos de todo Azeroth! ¡No podemos fracasar!' WHERE `ID`=46737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력이 다시 생성되고 있는 게 느껴집니다! 대마법사께 알려야 합니다!', `MaleText_loc4`='我能感觉到奥术能量再一次开始积累！一定要警告大法师！', `MaleText_loc5`='我可以感應到秘法能量又開始增強了!得趕緊去警告大法師!', `MaleText_loc7`='¡Puedo sentir que las energías arcanas se vuelven a acumular! ¡Debemos avisar al archimago!', `FemaleText_loc1`='비전 마력이 다시 생성되고 있는 게 느껴져요! 대마법사께 알려야 해요!', `FemaleText_loc4`='我能感觉到奥术能量再一次开始积累！一定要警告大法师！', `FemaleText_loc5`='我可以感應到秘法能量又開始增強了!得趕緊去警告大法師!', `FemaleText_loc7`='¡Puedo sentir que las energías arcanas se vuelven a acumular! ¡Debemos avisar al archimago!' WHERE `ID`=46738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔이 무겁군요...', `MaleText_loc4`='我的胳膊累了……', `MaleText_loc5`='我的手好累...', `MaleText_loc7`='Tengo el brazo cansado...', `FemaleText_loc1`='팔이 무겁군요...', `FemaleText_loc4`='我的胳膊累了……', `FemaleText_loc5`='我的手好累...', `FemaleText_loc7`='Tengo el brazo cansado...' WHERE `ID`=46739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 주인님의 예언을 실현하러 왔다. 의식은 이미 시작되었고, 우리는 너희가 멈출 수 없을 만큼 수가 많다.', `MaleText_loc4`='我们已经将主人的预言变为现实。仪式已经开始了，而且我们数量众多，你不可能阻止我们。', `MaleText_loc5`='我們前來實現主人的預言。儀式已經開始，而且你們寡不敵眾，根本無法阻止得了我們。', `MaleText_loc7`='Vinimos para realizar la profecía del maestro. Los rituales ya han comenzado y somos demasiado numerosos como para que podáis detenernos a todos.', `FemaleText_loc1`='우리는 주인님의 예언을 실현하러 왔다. 의식은 이미 시작되었고, 우리는 너희가 멈출 수 없을 만큼 수가 많다.', `FemaleText_loc4`='我们已经将主人的预言变为现实。仪式已经开始了，而且我们数量众多，你不可能阻止我们。', `FemaleText_loc5`='我們前來實現主人的預言。儀式已經開始，而且你們寡不敵眾，根本無法阻止得了我們。', `FemaleText_loc7`='Vinimos para realizar la profecía del maestro. Los rituales ya han comenzado y somos demasiado numerosos como para que podáis detenernos a todos.' WHERE `ID`=46740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 뵙게 되어 영광입니다, 감독관님. 저도 의식을 돕고 싶습니다.', `MaleText_loc4`='很高兴能回来，先知。我想为仪式的完成而出力。', `MaleText_loc5`='能回來真好，監督者。我想要協助進行儀式。', `MaleText_loc7`='Me alegro de volver, supervisor. Quiero ayudar a realizar el ritual.', `FemaleText_loc1`='다시 뵙게 되어 영광입니다, 감독관님. 저도 의식을 돕고 싶습니다.', `FemaleText_loc4`='很高兴能回来，先知。我想为仪式的完成而出力。', `FemaleText_loc5`='能回來真好，監督者。我想要協助進行儀式。', `FemaleText_loc7`='Me alegro de volver, supervisor. Quiero ayudar a realizar el ritual.' WHERE `ID`=46741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들에게 붙잡힌 줄 알고 걱정했습니다. 의식에서 당신을 빼놓을 수는 없죠.', `FemaleText_loc4`='我们很担心你会被抓住，但我绝不想把你排除在传送门仪式之外。', `FemaleText_loc5`='我們還在擔心你是不是被抓走了呢。不過，傳送門的儀式是不會把你漏掉的。', `FemaleText_loc7`='Temimos que te hubieran capturado, pero ni se me pasaría por la cabeza excluirte del ritual del portal.' WHERE `ID`=46742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 책을 가져가서 의식을 연습하세요. 정확하게 읽지 않으면 정령들이 차원문을 제때 통과하지 못하니 조심해야 합니다.', `FemaleText_loc4`='拿起这本书，完成仪式。每一个步骤都要完美无缺，否则元素就不会在正确的时间通过传送门。', `FemaleText_loc5`='收下這本書，練習裡面記載的儀式。連一個字也不能唸錯，否則元素們就不會在正確的時機離開這些傳送門。', `FemaleText_loc7`='Toma este libro y practica el ritual. Debe realizarse a la perfección o los elementales no abandonarán los portales en el momento adecuado.' WHERE `ID`=46743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 황혼 룬을 파괴했군! 이런 룬이 세 개 더 있을 거야. 그리고 그 룬들이 전부 동굴 안쪽에 있는 화염 차원문과 연결돼 있을 거라고.', `MaleText_loc4`='你摧毁了他们的大地符文！我打赌，他们一定还有另外三个符文，而且那些符文一定都连接在这道火焰传送门的后面。', `MaleText_loc5`='你破壞了他們的大地符文!我敢打賭應該還有三個才對，而且應該都和後頭的火焰傳送門有關。', `MaleText_loc7`='¡Has destruido su runa de la tierra! Apuesto a que hay otras tres más. Y apuesto a que están todas vinculadas al portal de fuego de atrás.' WHERE `ID`=46744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물과 바람의 정령이여. 그대들을 위한 길을 준비했으니 와서 스톰윈드를 파괴하소서.', `MaleText_loc4`='疾风与洪水的远古之力，我已经为你们打通了道路。来摧毁暴风城吧。', `MaleText_loc5`='風與水之先祖啊，我已經為你們鋪好了道路，前來將暴風城夷為平地吧!', `MaleText_loc7`='Ancestros de viento y agua, he preparado su camino. Vengan y arrasen Ventormenta.', `FemaleText_loc1`='물과 바람의 정령이여. 그대들을 위한 길을 준비했으니 와서 스톰윈드를 파괴하소서.', `FemaleText_loc4`='远古的疾风与洪水，我已经为你们打通了道路。来摧毁暴风城吧。', `FemaleText_loc5`='風與水之先祖啊，我已經為你們鋪好了道路，前來將暴風城夷為平地吧!', `FemaleText_loc7`='Ancestros de viento y agua, he preparado su camino. Vengan y arrasen Ventormenta.' WHERE `ID`=46745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬을 전부 파괴하는 게 좋겠어. 일단 등에 꽂힌 파편부터 좀 빼고...', `MaleText_loc4`='我们要把他们全部毁灭。但首先，我需要把那块弹片从我的背上取出来。', `MaleText_loc5`='我們最好能把它們全數毀掉。但首先，我得先把我背上的碎片給弄出來。', `MaleText_loc7`='Deberíamos destruirlas todas. Pero antes tengo que sacarme la metralla del trasero.' WHERE `ID`=46746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 물에 젖었나? 난 완전히 물에 빠진 생쥐 꼴이 됐다고! 좋아, 다음 룬은 바람의 룬이라는 데 얼마나 걸래?', `MaleText_loc4`='你身上湿了吗？我简直湿透了！好吧，你觉得下一个风之力的符文会是什么样子？', `MaleText_loc5`='你有沒有濕?我全身都濕透了!好了，下個符文肯定是跟風有關的，你要不要拿什麼來賭?', `MaleText_loc7`='¿Te has mojado? ¡Yo estoy empapado! Venga, ¿qué te apuestas a que la siguiente runa está armonizada con el aire?' WHERE `ID`=46747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 바람이 어찌나 강한지 머리카락이 순식간에 다 말랐네. 덕분에 비행기 보조 엔진에 대한 기똥찬 아이디어가 떠올랐다고!', `MaleText_loc4`='该死的风把我的头发都吹干了。不过它让我有了一个关于飞行器引擎的伟大灵感！', `MaleText_loc5`='強風把我的頭髮都吹乾了。這倒是給了我一個主意，那個多出來的飛行器引擎也可以拿來吹頭髮!', `MaleText_loc7`='Ese soplo de aire me ha secado el pelo que da gusto. ¡Me ha dado una gran idea para un motor de máquina voladora de repuesto!' WHERE `ID`=46748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리가 도넬리를 보고는 기뻐서 꽥꽥 소리를 냅니다!', `MaleText_loc4`='看到东尼利，尖喙发出欢快的叫声！', `MaleText_loc5`='比克看到多涅爾利，高興地叫了起來!', `MaleText_loc7`='¡Pico cacarea de alegría al ver a Donnelly!' WHERE `ID`=46749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우하하하, 이게 마지막 룬이었다고! 황혼의 망치단 자식들아, 이제 원소의 힘을 사용할 수 없을 거다!', `MaleText_loc4`='啊哈哈哈，这是他们最后的符文了！暮光崽子们，你们的元素之力都完蛋了！', `MaleText_loc5`='啊哈哈哈哈，這是最後一個符文啦!暮光混球，你們沒有元素的力量可以用啦!', `MaleText_loc7`='¡Ja, ja, ja, esa era la última de sus runas! Tontos Crepusculares, ¡no más poder elemental para ustedes!' WHERE `ID`=46750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야, 집으로 돌아가. 도넬리가 갈 때까지 킬리가 잘 돌봐 줄 거야.', `MaleText_loc4`='尖喙，回家去找凯莉。她会保护你，直到东尼利回来。', `MaleText_loc5`='回家去找基莉，比克。在多涅爾利回去之前，她會先保護你。', `MaleText_loc7`='Vuelve a casa con Keely, Pico. Ella te mantendrá a salvo hasta que Donnelly vuelva.' WHERE `ID`=46751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보라고! 저쪽에 저게 뭐지?', `MaleText_loc4`='什么！那里是什么？', `MaleText_loc5`='慢著!那個是什麼?', `MaleText_loc7`='¡Espera! ¿Qué es eso de ahí?' WHERE `ID`=46752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암이빨?! 안 돼애애애애!', `MaleText_loc4`='熔岩之牙？！不！！！', `MaleText_loc5`='熔齒?!不!', `MaleText_loc7`='¿Dientemagma? ¡NOOOOO!' WHERE `ID`=46753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 어딜 감히 도망가려고!', `MaleText_loc4`='你要到哪里去，小家伙？！', `MaleText_loc5`='你以為你是要上哪兒去啊，小子?!', `MaleText_loc7`='¡¿Adónde te crees que vas, hijo?!' WHERE `ID`=46754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드마인! 내가 잊었다고 생각했느냐?! 전에 말했듯이 반드시 너에게 복수하고 말 것이다!', `MaleText_loc4`='金矿！你以为我忘记了吗？！！我告诉过你，我要复仇！！！', `MaleText_loc5`='金礦!你以為我會忘得了嗎?!我就說了，我一定會報仇的!!!', `MaleText_loc7`='¡MINAORO! ¡¿CREES QUE ME HE OLVIDADO?! ¡¡TE DIJE QUE OBTENDRÍA MI VENGANZA!!' WHERE `ID`=46755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요! 여깁니다!', `MaleText_loc4`='救命！在这边！', `MaleText_loc5`='救命! 在上面!', `MaleText_loc7`='¡Auxilio! ¡Arriba!' WHERE `ID`=46756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 당신의 눈에서 안개를 걷어내 드릴게요. 자, 저희의 포로를 보세요.', `FemaleText_loc4`='现在我要移去你眼前的迷雾。看着吧，我们的俘虏。', `FemaleText_loc5`='現在我將移除你眼前的迷霧。看啊，我們的俘虜。', `FemaleText_loc7`='Ahora retiraré la niebla de tus ojos. Observa, cautivo.' WHERE `ID`=46757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙이 광기에 사로잡힌 지금, 우리 붉은용군단은 그의 수하에서 검은용군단을 구해내야 합니다. 우리는 반드시 검은용군단을 그들 본연의 모습으로 되돌릴 것입니다. 위대한 대지의 수호자로 말입니다.', `FemaleText_loc4`='死亡之翼已经彻底被自己的疯狂征服了。而我们红龙必须趁这个机会把黑龙从他的眼皮底下偷走。我们要让黑龙恢复他们往日的样子，成为大地的守护者。', `FemaleText_loc5`='死亡之翼已經陷入瘋狂，我們紅龍必須趁此機會偷走在他之下的黑龍們。而且我們會將黑龍重新塑造為他們原本所該扮演的角色:大地的守護者。', `FemaleText_loc7`='La locura de Alamuerte lo embarga, y nosotros, los dragones Rojos, debemos aprovechar la oportunidad de robarle sus dragones Negros. Los reformaremos a lo que siempre debieron ser: los guardianes de la tierra.' WHERE `ID`=46758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지쳐서 쓰러집니다.', `MaleText_loc4`='%s力竭倒下了。', `MaleText_loc5`='%s精疲力竭地倒下了。', `MaleText_loc7`='%s cae presa del agotamiento.' WHERE `ID`=46759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 일어나는 것 같습니다!', `MaleText_loc4`='%s显出要醒过来的样子！', `MaleText_loc5`='%s似乎要醒來了!', `MaleText_loc7`='¡%s parece que se está despertando!' WHERE `ID`=46760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!', `MaleText_loc4`='进攻！', `MaleText_loc5`='衝啊!', `MaleText_loc7`='¡Ataca!' WHERE `ID`=46761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둔왈트다운 전투였습니다. 당신이 맘에 들어요.', `MaleText_loc4`='你就像顿沃德家族的一员。我喜欢你。', `MaleText_loc5`='有登瓦德家的架勢。我喜歡你。', `MaleText_loc7`='Como un Montocre. Me gustas.' WHERE `ID`=46762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 멍청한 녀석! 이건 신성한 의식이라고!', `MaleText_loc4`='你这个傻瓜！这是一场仪式，不是在做饭！', `MaleText_loc5`='你這笨蛋!這是不容出錯的儀式，不是煮菜的食譜!', `MaleText_loc7`='¡Necio! ¡Es un ritual, no una receta!' WHERE `ID`=46763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 배반당했다! 여기서는 네가 이겼을지 몰라도, 의식은 반드시 성공할 것이다!', `MaleText_loc4`='我们被背叛了！你也许赢了这一次，但我们的仪式终将完成！', `MaleText_loc5`='我們被人出賣了!就算現在是你贏了，但儀式還是一定會成功的!', `MaleText_loc7`='¡Nos han traicionado! ¡Puede que hayas ganado esta vez, pero el ritual tendrá éxito!' WHERE `ID`=46764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 아직 쓸만한 장비가 많이 남아 있다. 산개해서 재빠르게 움직여라! 용아귀 부족이 가까이 있다.', `MaleText_loc4`='这里还有很多可供我们使用的设备。立刻散开。加快速度！龙喉兽人已经很近了。', `MaleText_loc5`='這邊有很多裝備是我們還可以用的。散開，打起精神!龍喉氏族的傢伙就在附近。', `MaleText_loc7`='Hay mucho equipo que aún podemos utilizar. Desplegaos. ¡Y daos prisa! Los Faucedraco andan cerca.', `FemaleText_loc1`='쓸만한 물건들을 재빨리 챙겨라. 용아귀 부족이 언제 들이닥칠지 모른다!', `FemaleText_loc4`='拿走一切能拿得动的东西，赶快离开。龙喉兽人随时都有可能出现！', `FemaleText_loc5`='隨便抓個東西趕緊離開，龍喉的傢伙隨時都會出現!', `FemaleText_loc7`='Coged los suministros que podáis y daos prisa. ¡Los Faucedraco pueden aparecen en cualquier momento!' WHERE `ID`=46765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 놈들이 없는지 잘 살펴라.', `MaleText_loc4`='提高警惕，小心龙喉兽人。', `MaleText_loc5`='招子放亮一點，隨時注意龍喉的傢伙。', `MaleText_loc7`='Mantened los ojos abiertos por si vuelven los Faucedraco.', `FemaleText_loc1`='용아귀 놈들이 없는지 잘 살펴라.', `FemaleText_loc4`='提高警惕，小心龙喉兽人。', `FemaleText_loc5`='招子放亮一點，隨時注意龍喉的傢伙。', `FemaleText_loc7`='Mantened los ojos abiertos por si vuelven los Faucedraco.' WHERE `ID`=46766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물과 비림의 정령이여. 그대들을 위한 길을 좀비했으니 와서 스톰윈드를 파괴마소서!', `MaleText_loc4`='小麦与水的远古之力，我已经为你们打通了道路。来摧毁暴风城吧！', `MaleText_loc5`='轟與水之先祖啊，我已經為你們鋪好了道路，前來將暴風城夷為平地吧!', `MaleText_loc7`='Cabestros de sarmiento y agua, he preparado su comino. ¡Vengan y sazonen Ventormenta!', `FemaleText_loc1`='물과 비림의 정령이여. 그대들을 위한 길을 좀비했으니 와서 스톰윈드를 파괴마소서!', `FemaleText_loc4`='小麦与水的远古之力，我已经为你们打通了道路。来摧毁暴风城吧！', `FemaleText_loc5`='轟與水之先祖啊，我已經為你們鋪好了道路，前來將暴風城夷為平地吧!', `FemaleText_loc7`='Cabestros de sarmiento y agua, he preparado su comino. ¡Vengan y sazonen Ventormenta!' WHERE `ID`=46767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경비병들, $n 님을 본보기로 삼아 적에게서 스톰윈드를 지켜내세요.', `FemaleText_loc4`='士兵们，你们要学习$n，誓死保卫暴风城，抵抗敌人的进攻。', `FemaleText_loc5`='各位衛兵，$n就是你們最好的榜樣，看看他是怎樣奮力保護暴風城不受敵人侵襲的。', `FemaleText_loc7`='Guardias, tomad a $n como ejemplo a la hora de defender Ventormenta de sus enemigos.' WHERE `ID`=46768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 그 이교도들은 스톰윈드를 폐허로 만들 작정입니다. 경비병 여러분, 우리 도시와 왕을 지키기 위해 방심하지 않아야 할 것입니다. $n 님이 했던 것처럼 말입니다!', `FemaleText_loc4`='这些邪教徒已经决意要毁灭暴风城。我们必须时刻保持警惕，守卫我们的城市和国王，就像$n所做的那样！', `FemaleText_loc5`='但是這些教徒已鐵了心要將暴風城夷為平地。兄弟們，為了保護我們的首都與國王，我們務必以$n為榜樣，提高警戒!', `FemaleText_loc7`='Pero estos cultores están decididos a llevar a Ventormenta a la ruina. ¡Hombres, debemos permanecer en guardia por nuestra ciudad y nuestro Rey, como lo ha estado $n!' WHERE `ID`=46769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 둘 다 불태워 주마!', `MaleText_loc4`='你们都将被烧毁！', `MaleText_loc5`='燒死你們兩個!', `MaleText_loc7`='¡AMBOS ARDERÁN!' WHERE `ID`=46770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 충실하게 스톰윈드를 섬깁니다!', `MaleText_loc4`='我们将为暴风城奉献我们的全部忠诚，女士！', `MaleText_loc5`='女士，我們誓死效忠暴風城!', `MaleText_loc7`='¡Servimos fielmente a Ventormenta, mi señora!', `FemaleText_loc1`='저희는 충실하게 스톰윈드를 섬깁니다!', `FemaleText_loc4`='我们将为暴风城奉献我们的全部忠诚，女士！', `FemaleText_loc5`='女士，我們誓死效忠暴風城!', `FemaleText_loc7`='¡Servimos fielmente a Ventormenta, mi señora!' WHERE `ID`=46771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도 반역자들이라고 했소? 거리에서 놈들을 몰아내 줘서 고맙소.', `MaleText_loc4`='还有邪教叛徒？能把他们抓起来实在是一件好事。', `MaleText_loc5`='還有邪教的叛徒?幹得好，把他們趕出我們的街道。', `MaleText_loc7`='¿Más cultores traidores? Buen trabajo al sacarlos de las calles.' WHERE `ID`=46772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제야 돌아오셨군요! 우린 당신이 놈들에게 붙잡힌 줄 알고 걱정하고 있었습니다.', `FemaleText_loc4`='你终于回来了！我们已经开始担心你被逮捕了。', `FemaleText_loc5`='你終於回來了!我們還在擔心你是不是被逮捕了呢。', `FemaleText_loc7`='¡Por fin has vuelto! Empezábamos a pensar que te habían arrestado.' WHERE `ID`=46773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 못생긴 녀석을 팔면 야자를 몇 개나 얻을 수 있을까?', `MaleText_loc4`='我们能用那个丑家伙换几个椰子？', `MaleText_loc5`='我們能幫醜傢伙弄到多少個椰子?', `MaleText_loc7`='¿Cuántos cocos podemos conseguir por el feo?' WHERE `ID`=46774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥에 처박힌 소감이 어떠냐, 땅딸보야!', `MaleText_loc4`='吃土去吧，矮子！', `MaleText_loc5`='吃土吧，臭矮子!', `MaleText_loc7`='¡Muerde el polvo, tapón!' WHERE `ID`=46775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얌전히 죽어 있어라.', `MaleText_loc4`='去死吧。', `MaleText_loc5`='給我乖乖死在這裡。', `MaleText_loc7`='Ahora quédate ahí muerto.' WHERE `ID`=46776;
