UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, $n 님. 용아귀 놈들이 곧 쳐들어올 겁니다!', `MaleText_loc4`='提高警惕，$n。龙喉就要进攻了！', `MaleText_loc5`='注意，$n，龍喉獸人準備攻過來了!', `MaleText_loc7`='Atención, $n. ¡Los Faucedraco están a punto de atacar!', `FemaleText_loc1`='조심하세요, $n 님. 용아귀 놈들이 곧 쳐들어올 겁니다!', `FemaleText_loc4`='提高警惕，$n。龙喉就要进攻了！', `FemaleText_loc5`='注意，$n，龍喉獸人準備攻過來了!', `FemaleText_loc7`='Atención, $n. ¡Los Faucedraco están a punto de atacar!' WHERE `ID`=46782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕배기를 휩쓸어라! 와일드해머를 없애 버려라!', `MaleText_loc4`='攻占山脊！消灭蛮锤矮人！', `MaleText_loc5`='掃蕩山脊!殺光蠻錘矮人!', `MaleText_loc7`='¡Barred la montaña! ¡Matad a los Martillo Salvaje!', `FemaleText_loc1`='언덕배기를 휩쓸어라! 와일드해머를 없애 버려라!', `FemaleText_loc4`='攻占山脊！消灭蛮锤矮人！', `FemaleText_loc5`='掃蕩山脊!殺光蠻錘矮人!', `FemaleText_loc7`='¡Barred la montaña! ¡Matad a los Martillo Salvaje!' WHERE `ID`=46783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠간 잡고 말 테다, 골드마인!', `MaleText_loc4`='我会抓住你的，金矿！', `MaleText_loc5`='我會逮到你的，金礦!', `MaleText_loc7`='¡TE ATRAPARÉ, MINAORO!' WHERE `ID`=46784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 짓이냐?!', `MaleText_loc4`='以古加尔的名义，你在干什么？！', `MaleText_loc5`='看在丘加利的份上，你到底是在幹什麼?!', `MaleText_loc7`='En el nombre de Cho''gall, ¡¿qué estás haciendo?!' WHERE `ID`=46785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문이 열리고 너희의 소중한 도시는 사라져버릴 것이다!', `MaleText_loc4`='传送门将开启，你们宝贵的城市将被夷为平地！', `MaleText_loc5`='傳送門就要開啟，你心愛的城市即將被夷為平地!', `MaleText_loc7`='¡Los portales se abrirán y tu preciosa ciudad será arrasada!' WHERE `ID`=46786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 믿음직한 남쪽바다 럼주처럼 내 몸을 기운 나게 해 주는 건 없지!', `MaleText_loc4`='只有这种带劲的南海朗姆酒能让我的骨头暖和起来！', `MaleText_loc5`='還是老牌的南海蘭姆酒最能溫暖我這身骨頭啦!', `MaleText_loc7`='¡Nada calienta los huesos como este estupendo ron de los Mares del Sur!', `FemaleText_loc1`='이 믿음직한 남쪽바다 럼주처럼 내 몸을 기운 나게 해 주는 건 없지!', `FemaleText_loc4`='只有这种带劲的南海朗姆酒能让我的骨头暖和起来！', `FemaleText_loc5`='還是老牌的南海蘭姆酒最能溫暖我這身骨頭啦!', `FemaleText_loc7`='¡Nada calienta los huesos como este estupendo ron de los Mares del Sur!' WHERE `ID`=46787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아흐!', `MaleText_loc4`='啊！', `MaleText_loc5`='呀!', `MaleText_loc7`='¡Yarg!', `FemaleText_loc1`='아흐!', `FemaleText_loc4`='啊！', `FemaleText_loc5`='呀!', `FemaleText_loc7`='¡Yarg!' WHERE `ID`=46788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요호, 요호! 해적은 나의 삶!', `MaleText_loc4`='呦喉，呦喉，我应该去干海盗！', `MaleText_loc5`='呦呵，呦呵，我最愛當海賊!', `MaleText_loc7`='¡Yo ho, yo ho, un gran pirata soy!', `FemaleText_loc1`='요호, 요호! 해적은 나의 삶!', `FemaleText_loc4`='呦喉，呦喉，我应该去干海盗！', `FemaleText_loc5`='呦呵，呦呵，我最愛當海賊!', `FemaleText_loc7`='¡Yo ho, yo ho, un gran pirata soy!' WHERE `ID`=46789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 치르게 될 것이다, 배반자여!', `MaleText_loc4`='你要为此付出代价，叛徒！', `MaleText_loc5`='你會付出代價的，叛徒!', `MaleText_loc7`='¡Pagarás por esto, traidor!' WHERE `ID`=46790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 네가 이겼다고 생각하겠지만, 결국은 황혼의 망치단이 승리할 것이다!', `MaleText_loc4`='你以为你已经赢了，但暮光的力量才能取得最终胜利！', `MaleText_loc5`='你以為你已經贏了，但是暮光的力量終究還是會獲勝的!', `MaleText_loc7`='Crees que has ganado, ¡pero las fuerzas Crepusculares acabarán por triunfar!' WHERE `ID`=46791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 놈들이 계속해서 쳐들어오면, 우리가 계속해서 눕혀 주자!', `MaleText_loc4`='没错！他们可以不断地杀过来，而我们将一次又一次地把他们打趴下！', `MaleText_loc5`='沒錯!他們繼續來沒關係，反正我們也會繼續痛宰他們!', `MaleText_loc7`='¡Eso es! ¡Si siguen viniendo, nosotros seguiremos echándolos!', `FemaleText_loc1`='오크란 바로 이렇게 다루는 거다, 제군들.', `FemaleText_loc4`='这就是对付兽人的办法，男孩们。', `FemaleText_loc5`='兄弟們，那樣對付獸人就對啦。', `FemaleText_loc7`='ASÍ es como se trata con un orco, chicos.' WHERE `ID`=46792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 다시 일을 시작하자. 재빨리 움직이면 다음 공격이 들어오기 전에 작업을 마무리할 수 있을 것이다.', `MaleText_loc4`='好了，去工作吧。如果我们的速度够快，我们就能在敌人再次发动攻击之前完成这里的任务。', `MaleText_loc5`='好了，繼續幹活兒。動作快的話，還可以在下次攻擊之前把這邊的東西弄完。', `MaleText_loc7`='Venga, de vuelta al trabajo. Si nos damos prisa acabaremos antes del siguiente ataque.', `FemaleText_loc1`='좋다, 다시 일을 시작하자. 재빨리 움직이면 다음 공격이 들어오기 전에 작업을 마무리할 수 있을 것이다.', `FemaleText_loc4`='好了，去工作吧。如果我们的速度够快，我们就能在敌人再次发动攻击之前完成这里的任务。', `FemaleText_loc5`='好了，繼續幹活兒。動作快的話，還可以在下次攻擊之前把這邊的東西弄完。', `FemaleText_loc7`='Venga, de vuelta al trabajo. Si nos damos prisa acabaremos antes del siguiente ataque.' WHERE `ID`=46793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르자. 썬더마에서 이 보급품을 애타게 기다리고 있다.', `MaleText_loc4`='快一点，桑德玛尔需要这些物资。', `MaleText_loc5`='動作快，桑德瑪需要這些補給品。', `MaleText_loc7`='Démonos prisa, Bramal necesita estos suministros.', `FemaleText_loc1`='서두르자. 썬더마에서 이 보급품을 애타게 기다리고 있다.', `FemaleText_loc4`='快一点，桑德玛尔需要这些物资。', `FemaleText_loc5`='動作快，桑德瑪需要這些補給品。', `FemaleText_loc7`='Démonos prisa, Bramal necesita estos suministros.' WHERE `ID`=46794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군! 감히 와일드해머 부족을 공격하는 용아귀 오크 놈들에게 본때를 보여 줬어.', `MaleText_loc4`='我们完成了！现在那些龙喉兽人如果想要伏击蛮锤氏族，我们会给他们一点颜色看看。', `MaleText_loc5`='我們辦到了!給龍喉的那些傢伙一個教訓，看他們還敢不敢偷襲我們蠻錘氏族。', `MaleText_loc7`='¡Lo hemos conseguido! Así aprenderán esos Faucedraco a tender emboscadas a los Martillo Salvaje.', `FemaleText_loc1`='해냈군! 감히 와일드해머 부족을 공격하는 용아귀 오크 놈들에게 본때를 보여 줬어.', `FemaleText_loc4`='我们完成了！现在那些龙喉兽人如果想要伏击蛮锤氏族，我们会给他们一点颜色看看。', `FemaleText_loc5`='我們辦到了!給龍喉的那些傢伙一個教訓，看他們還敢不敢偷襲我們蠻錘氏族。', `FemaleText_loc7`='¡Lo hemos conseguido! Así aprenderán esos Faucedraco a tender emboscadas a los Martillo Salvaje.' WHERE `ID`=46795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상은 불완전해! 처음부터 다시 시작해야 해!', `MaleText_loc4`='这个世界充满了瑕疵！我们必须开始一个全新的世界！', `MaleText_loc5`='這個世界太不完美!我們必須重新開始!', `MaleText_loc7`='¡Este mundo es imperfecto! ¡Debemos comenzar de nuevo!' WHERE `ID`=46796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠의 비밀은 오직 우리만의 것이다!', `MaleText_loc4`='奥丹姆的秘密只能属于我们！', `MaleText_loc5`='奧丹姆的秘密只屬於我們!', `MaleText_loc7`='¡Los secretos de Uldum serán solo para nosotros!' WHERE `ID`=46797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 막을 순 없어! 무덤 아래의 힘이 바로 우리 것이 될 테니까!', `MaleText_loc4`='你不可能阻止我们！我们将释放这片坟墓下面所埋藏的能量！', `MaleText_loc5`='你阻止不了我們!我們將取得埋藏在這座陵墓之下的秘密!', `MaleText_loc7`='¡No puedes detenernos! ¡Controlamos el poder de las tumbas!' WHERE `ID`=46798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 가로막는 자들을 모두 없애버리겠다!', `MaleText_loc4`='我们将毁灭所有反对我们的人！', `MaleText_loc5`='我們將消滅所有的阻礙者!', `MaleText_loc7`='¡Destruiremos a todo aquel que se oponga a nosotros!' WHERE `ID`=46799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 내 칼에 와일드해머의 피를 묻혔군.', `MaleText_loc4`='我的剑上又多了一道凹痕。', `MaleText_loc5`='我的劍上又可以多刻一條殺敵的記號了。', `MaleText_loc7`='Otra muesca en mi espada.', `FemaleText_loc1`='다시 승리했다! 허리띠에 매달 턱수염이 하나 늘었군.', `FemaleText_loc4`='又一场胜利！我的腰带上又能多挂几把胡子了。', `FemaleText_loc5`='我們又贏了!又多了幾條鬍子可以掛在腰帶上。', `FemaleText_loc7`='¡Otro triunfo! Otras barbas que colgar del cinturón.' WHERE `ID`=46800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 와일드해머 드워프를 그리핀에서 끌어내리고 놈들이 어떻게 싸우나 보라지. 그리핀 빼면 시체인 놈들!', `MaleText_loc4`='哈！把蛮锤矮人赶下他们的狮鹫，看看他们能怎样战斗。这帮无用的家伙！', `MaleText_loc5`='哈!把蠻錘的廢物從獅鷲獸的背上趕下來，看看他們打的是什麼架。爛透了!', `MaleText_loc7`='¡Ja! Bajen a esos Martillo Salvaje de sus grifos y miren la resistencia que oponen. ¡Nada!' WHERE `ID`=46801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가자. 내 칼이 우는구나.', `MaleText_loc4`='我们上吧，我的剑刃已经在渴望着战斗了。', `MaleText_loc5`='走吧，我的利刃飢渴了。', `MaleText_loc7`='Vamos. Mi hoja está hambrienta.' WHERE `ID`=46802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났군. 이 지역을 완전히 짓밟아라. 돌아와도 얻을 것이 없도록 싹 쓸어버려라!', `MaleText_loc4`='结束了。把这个地方彻底摧毁。不要留下任何东西！', `MaleText_loc5`='結束了。徹底清空這個地方，別留下任何東西給他們!', `MaleText_loc7`='Está hecho. Arrasen todo el lugar. ¡Que no les quede nada para lo que volver!', `FemaleText_loc1`='끝났군. 이 지역을 완전히 짓밟아라. 돌아와도 얻을 것이 없도록 싹 쓸어버려라!', `FemaleText_loc4`='结束了。把这个地方彻底摧毁。不要留下任何东西！', `FemaleText_loc5`='結束了。徹底搜索把這個地方，別留下任何東西給他們!', `FemaleText_loc7`='Está hecho. Arrasen todo el lugar. ¡Que no les quede nada para lo que volver!' WHERE `ID`=46803;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<다가가자 윙윙거리며 지잉 소리를 내는 제어장치>', `FemaleText_loc4`='<当你靠近这座控制台的时候，它发出一阵“嗡嗡”声。>', `FemaleText_loc5`='<主控台在你接近的時候發出嗡嗡嗡的聲音。>', `FemaleText_loc7`='<La consola zumba y ronronea a medida que te acercas.>' WHERE `ID`=46804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 알들은 모두 갖다 버려야겠네요... 잠깐! 좋은 생각이 떠올랐어요.', `MaleText_loc4`='我想，我们只能把这些丢掉了……等等！我突然有了个主意。', `MaleText_loc5`='看來我們大概只能把這些東西給丟了... 慢著!我想到了一個主意。', `MaleText_loc7`='Supongo que tendremos que tirarlos... ¡ESPERA! Creo que tengo una idea.' WHERE `ID`=46805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요, 아주 기발한 생각이라고요.', `MaleText_loc4`='是的，绝对是个好主意。', `MaleText_loc5`='沒錯，一個好主意。', `MaleText_loc7`='Sí, decididamente es una idea.' WHERE `ID`=46806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후바-후바!', `MaleText_loc4`='好啊，好啊！', `MaleText_loc5`='讚啦!', `MaleText_loc7`='¡Auuu!' WHERE `ID`=46807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 다리에 모터라도 달아 드려야겠어요!', `MaleText_loc4`='你能从那些腿上弄一个垫片下来！', `MaleText_loc5`='在那幾根腳上弄個晃來晃去的洗衣機也不怕!', `MaleText_loc7`='¡Esas patas están para comérselas!' WHERE `ID`=46809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음파의 진동수만큼 흔들어 주세요!', `MaleText_loc4`='要以正弦波的幅度晃动它，宝贝！', `MaleText_loc5`='上下搖得跟正弦波一樣也沒關係，寶貝!', `MaleText_loc7`='¡Muévete como una onda sinusoide, nena!' WHERE `ID`=46810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='TXR-5000입니다!', `MaleText_loc4`='它是TXR-5000！', `MaleText_loc5`='它就是TXR-5000!', `MaleText_loc7`='¡Es el TXR-5000!' WHERE `ID`=46811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='200마력, 이중 연소 엔진에 개량된 유량축전기까지! 짜잔!', `MaleText_loc4`='200马力，双重燃烧引擎，修正流体电容！开动！', `MaleText_loc5`='200匹馬力，雙內燃機引擎，外加改良過的通量電容器!喔耶!', `MaleText_loc7`='¡Motor de combustión doble de 200 caballos con condensadores de flujo modificados! ¡ZOING!' WHERE `ID`=46812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개처럼 멋진 파란색인 줄은 몰랐습니다! 끝내주네요!!', `MaleText_loc4`='我没想到它竟然还快如闪电！太惊人了！！', `MaleText_loc5`='沒想到竟然還有閃電藍的!太讚了!!', `MaleText_loc7`='¡No sabía que los hicieran en azul eléctrico! ¡¡INCREÍBLE!!' WHERE `ID`=46813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개량된 다리 관절을 보세요! 비포장도로 주행 시에도 최고의 성능을 보여줍니다!', `MaleText_loc4`='检测修正的腿部关节！完美适应各种路况！', `MaleText_loc5`='看看這新型的腿部關節!最適合越野奔馳!', `MaleText_loc7`='¡Mira las articulaciones modificadas de las piernas! ¡Perfectas para el terreno agreste!' WHERE `ID`=46814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 곡선을 두 눈으로 음미해 보고 싶군요!', `MaleText_loc4`='我要检查这些曲线！', `MaleText_loc5`='我想要體驗看看它的曲線!', `MaleText_loc7`='¡Ya me gustaría peritar esas curvas!' WHERE `ID`=46815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장엄함은... 영웅급입니다!!!', `MaleText_loc4`='真是……伟大！！！', `MaleText_loc5`='太...完美了!!!', `MaleText_loc7`='Es... tan... ¡¡ÉPICO!!' WHERE `ID`=46816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기로 개조한 상어라고? 왜 저런 생각을 못 했을까?!', `MaleText_loc4`='武装鲨鱼？为什么我没有想到这个？！', `MaleText_loc5`='裝武器的鯊魚?我怎麼會沒有想到呢?', `MaleText_loc7`='¿Tiburones con armas? ¡¿Cómo no se me había ocurrido?!' WHERE `ID`=46817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 즐기세요!!!', `MaleText_loc4`='厉害！！！', `MaleText_loc5`='搖滾吧!!!', `MaleText_loc7`='¡¡TOMA YA!!' WHERE `ID`=46818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는걸!', `MaleText_loc4`='真精彩！', `MaleText_loc5`='了不起!', `MaleText_loc7`='¡Brillante!' WHERE `ID`=46819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 사로잡은 자들이 데스윙과 동맹을 맺었소, $r.', `MaleText_loc4`='抓住我们的人和死亡之翼结盟了，$r。', `MaleText_loc5`='抓住我們的人已經跟死亡之翼結盟了，$r。', `MaleText_loc7`='Nuestros captores se han aliado con Alamuerte, $r.' WHERE `ID`=46820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비는 필요치 않소. 당신의 힘을 보여주시오.', `MaleText_loc4`='他们没有任何怜悯之心，你安心受死吧。', `MaleText_loc5`='他們已沒有任何的慈悲之心，所以...認命吧。', `MaleText_loc7`='No les queda piedad alguna. Resígnate.' WHERE `ID`=46821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수 세기 동안 아무도 건드리지 않은 듯한 거대한 조각상이 굳건하게 서 있습니다.', `MaleText_loc4`='这座笨重的雕像立在这里，已经有许多个世纪没有被碰触过了。', `MaleText_loc5`='巨大的雕像矗立不動，不知已多少世紀沒人碰過。', `MaleText_loc7`='La enorme estatua permanece inerte, sin tocar desde hace siglos.' WHERE `ID`=46822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상은 오래된 것이 분명하지만 전혀 손상되지 않은 것 같습니다.', `MaleText_loc4`='虽然这座雕像已经非常古老了，却没有任何被风蚀损坏的痕迹。', `MaleText_loc5`='這座雕像顯然十分古老，但是它卻絲毫沒有受歲月侵蝕的跡象。', `MaleText_loc7`='Aunque esta estatua es claramente muy antigua, no parece haber decaído en absoluto con los siglos.' WHERE `ID`=46823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<홈에 졸을 끼워 넣습니다.>', `MaleText_loc4`='<将人偶放在缺口上。>', `MaleText_loc5`='<把兵卒放進小凹槽。>', `MaleText_loc7`='<Coloca el peón en la ranura.>', `FemaleText_loc1`='<홈에 졸을 끼워 넣습니다.>', `FemaleText_loc4`='<将人偶放在缺口上。>', `FemaleText_loc5`='<把兵卒放進小凹槽。>', `FemaleText_loc7`='<Coloca el peón en la ranura.>' WHERE `ID`=46824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 시민 여러분, 여러분도 아시다시피 위협적인 이교도 집단이 우리의 도시를 파괴하려 하고 있습니다. 노스렌드의 영웅이자 부족의 자랑스러운 용사이신 가로쉬 대족장님께서는 이 이교도 집단이 모두 사라질 때까지 오그리마로 들어오려는 모든 이들에게 수색과 심문에 응할 것을 명하셨습니다.', `MaleText_loc4`='奥格瑞玛的市民们，如你们所知，一个危险的邪教正在图谋分裂我们的城市。诺森德英雄，兽人的勇士，加尔鲁什·地狱咆哮酋长下达命令，在彻底摧毁那个邪教之前，要进入奥格瑞玛的人必须接受搜查和询问。', `MaleText_loc5`='奧格瑪的市民們，你們都知道，有個危險的邪教正陰謀不軌企圖破壞我們的城市。在徹底消滅這個邪教之前，大酋長卡爾洛斯·地獄吼－北裂境英雄;部落首席勇士，下令凡意圖進入奧格瑪的人都必須接受搜身與盤問。', `MaleText_loc7`='Ciudadanos de Orgrimmar, como bien sabéis, una peligrosa secta amenaza con destruir nuestra ciudad. Hasta que hayamos acabado con dicho grupo, el Jefe de Guerra Garrosh Grito Infernal, héroe de Rasganorte y campeón del pueblo, decreta que todos los que quieran entrar en Orgrimmar tendrán que someterse a registros y preguntas.', `FemaleText_loc1`='오그리마 시민 여러분, 여러분도 아시다시피 위협적인 이교도 집단이 우리의 도시를 파괴하려 하고 있습니다. 노스렌드의 영웅이자 부족의 자랑스러운 용사이신 가로쉬 대족장님께서는 이 이교도 집단이 모두 사라질 때까지 오그리마로 들어오려는 모든 이들에게 수색과 심문에 응할 것을 명하셨습니다.', `FemaleText_loc4`='奥格瑞玛的市民们，如你们所知，一个危险的邪教正在图谋分裂我们的城市。诺森德英雄，兽人的勇士，加尔鲁什·地狱咆哮酋长下达命令，在彻底摧毁那个邪教之前，要进入奥格瑞玛的人必须接受搜查和询问。', `FemaleText_loc5`='奧格瑪的市民們，你們都知道，有個危險的邪教正陰謀不軌企圖破壞我們的城市。在徹底消滅這個邪教之前，大酋長卡爾洛斯·地獄吼－北裂境英雄;部落首席勇士，下令凡意圖進入奧格瑪的人都必須接受搜身與盤問。', `FemaleText_loc7`='Ciudadanos de Orgrimmar, como bien sabéis, una peligrosa secta amenaza con destruir nuestra ciudad. Hasta que hayamos acabado con dicho grupo, el Jefe de Guerra Garrosh Grito Infernal, héroe de Rasganorte y campeón del pueblo, decreta que todos los que quieran entrar en Orgrimmar tendrán que someterse a registros y preguntas.' WHERE `ID`=46825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='색깔을 보니 이게 감독관이 분명합니다.$b$b조각상에는 당신의 졸이 딱 맞을 것 같은 홈이 있습니다.', `MaleText_loc4`='根据颜色判断，这一定就是戒卫。$b$b你在它上面找到一个小缺口，与你的棋卒轮廓正好吻合。', `MaleText_loc5`='從顏色來看，這必定就是那個「衛兵」。$b$b你看到了一個可能放得下你的兵卒的小凹槽。', `MaleText_loc7`='A juzgar por su color, este tiene que ser El Guardián.$b$bPuedes ver una pequeña hendidura en la que podría encajar tu peón.' WHERE `ID`=46826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은색 조각상이 당신이 가지고 있는 파수꾼의 졸과 많이 닮았습니다.$b$b조각상에는 당신의 졸과 크기가 똑같은 홈이 있습니다.', `MaleText_loc4`='这座红色雕像很像是你带在身上的哨卫的棋卒。$b$b这座雕像上有一个小缺口，正好与你的棋卒形状相吻合。', `MaleText_loc5`='這個紅色的雕像跟你手中的哨兵兵卒看起來很像。$b$b雕像上有個小凹槽，大小跟你的兵卒差不多。', `MaleText_loc7`='Esta estatua roja se parece mucho al peón de centinela que tienes en la mano.$b$bLa estatua tiene una pequeña hendidura del mismo tamaño que tu peón.' WHERE `ID`=46827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 대지의 정령이여. 그대들을 위한 길을 준비했으니 와서 오그리마를 파괴하소서.', `MaleText_loc4`='烈火与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。', `MaleText_loc5`='火與大地的先祖啊，我已經為你們鋪好了道路，前來將奧格瑪夷為平地吧!', `MaleText_loc7`='Ancestros de fuego y tierra, he preparado su camino. Vengan y arrasen Orgrimmar.', `FemaleText_loc1`='불과 대지의 정령이여. 그대들을 위한 길을 준비했으니 와서 오그리마를 파괴하소서.', `FemaleText_loc4`='烈火与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。', `FemaleText_loc5`='火與大地的先祖啊，我已經為你們鋪好了道路，前來將奧格瑪夷為平地吧!', `FemaleText_loc7`='Ancestros de fuego y tierra, he preparado su camino. Vengan y arrasen Orgrimmar.' WHERE `ID`=46828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 돼지의 정령이여. 그대들을 위한 길을 좀비했으니 와서 파괴하마를 오그리소서!', `MaleText_loc4`='面粉与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。', `MaleText_loc5`='吼與大地的先祖啊，我已經為你們鋪好了道路，前來將奧格瑪夷為平地吧!', `MaleText_loc7`='Cabestros de huevo y tierra, he preparado su comino. ¡Vengan y sazonen Orgrimmar!', `FemaleText_loc1`='불과 돼지의 정령이여. 그대들을 위한 길을 좀비했으니 와서 파괴하마를 오그리소서!', `FemaleText_loc4`='面粉与大地的远古之力，我已经为你们打通了道路。来摧毁奥格瑞玛吧。', `FemaleText_loc5`='吼與大地的先祖啊，我已經為你們鋪好了道路，前來將奧格瑪夷為平地吧!', `FemaleText_loc7`='Cabestros de huevo y tierra, he preparado su comino. ¡Vengan y sazonen Orgrimmar!' WHERE `ID`=46829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 여깁니다. 새로 알아낸 게 있습니까? 뒤를 밟힌 건 아니겠지요?', `MaleText_loc4`='$n，你有什么可以报告的？你被跟踪了吗？', `MaleText_loc5`='$n，這邊。有沒有什麼新消息?有沒有被人跟蹤?', `MaleText_loc7`='$n, por aquí. ¿Qué tienes que informar? ¿Te han seguido?' WHERE `ID`=46830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦기 전에 초갈이 만드는 불가사의한 무기에 대해 모든 걸 알아내야 합니다.', `MaleText_loc4`='我们需要及时弄清楚古加尔神秘武器的一切信息。', `MaleText_loc5`='我們必須趁著時勢尚未太遲之前，挖掘出和丘加利的神秘武器相關的所有情報。', `MaleText_loc7`='Tenemos que saberlo todo sobre esa arma misteriosa de Cho''gall antes de que sea demasiado tarde.' WHERE `ID`=46831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 편이라곤 당신과 나, 그리고 광산에 있는 대지 고리회 두 명이 전부인 듯하군요. 발각되기 전에 재빨리 일을 진행해야 합니다, $n 님.', `MaleText_loc4`='看样子，这个矿洞里只有你、我和那两个大地之环成员。我们要加快速度，$n，在被发现前完成任务。', `MaleText_loc5`='看來就只剩下你跟我，還有礦坑那兩個陶土議會的傢伙。動作快，$n，趁我們還沒有被發現。', `MaleText_loc7`='Parece que solo estamos tú, yo y esos dos miembros del Anillo de la Tierra de la mina. Actuemos rápido, $n, antes de que nos descubran.' WHERE `ID`=46832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 작전에 투입되니 좋군요. 오랫동안 스톰윈드에 틀어박혀 있었던 터라 새로운 기분이 듭니다.', `MaleText_loc4`='真高兴能回到原野上。这里比暴风城的那些鸽子笼舒服多了。', `MaleText_loc5`='能夠親自參與行動的感覺真不錯。改變一下步調，比一直窩在暴風城好多了。', `MaleText_loc7`='Es bueno volver al campo. Es un cambio de aires después de estar encerrado en Ventormenta todo el tiempo.' WHERE `ID`=46833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈과 해골분쇄자를 어차피 상대해야 한다면 되도록 빨리 싸우는 게 차라리 나을 겁니다. 마음의 준비는 되셨습니까, $n 님?', `MaleText_loc4`='我们迟早都要与古加尔和碎颅者正面作战。你要参加这场战争吗，$n？', `MaleText_loc5`='我們寧可早一點把丘加利和碎顱氏族的問題給解決掉。你要一起加入嗎，$n?', `MaleText_loc7`='Vamos a tener que encargarnos de Cho''gall y Trituracráneos más temprano que tarde. ¿Estás $gdispuesto:dispuesta;, $n?' WHERE `ID`=46834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 임무를 완수하고 살아남지 못할지도 모릅니다, $n 님. 그게 마음에 안 들거든 언제든 떠나셔도 좋습니다. 물론 저는 당신이 남아 주길 바라지만요.', `MaleText_loc4`='希望你已经为这个有去无回的任务做好了准备，$n。你随时都可以退出，但我还是希望你能与我们并肩奋战。', `MaleText_loc5`='這或許是個無法回頭的任務，$n。若是你覺得自己還沒準備好，你隨時都可以走開 - 雖然我希望你不要。', `MaleText_loc7`='Podría ser una misión sin retorno, $n. Si no te sientes $gcómodo:cómoda; con eso, puedes irte en cualquier momento, aunque preferiría que no lo hicieras.' WHERE `ID`=46835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 여기 일을 전부 처리해야 황혼의 요새에 대한 마지막 공격을 시작할 수 있습니다.', `MaleText_loc4`='在对暮光堡垒发动最后的进攻之前，我们需要处理好这里的一切问题。', `MaleText_loc5`='我們必須先把外邊的事情都解決掉，然後才能夠對暮光堡壘發動最後的攻擊。', `MaleText_loc7`='Tenemos que encargarnos de todo ahí fuera antes de lanzar el asalto final sobre El Bastión del Crepúsculo.' WHERE `ID`=46836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 절 단원으로 끌어들이려고 했다는 거 아십니까? 정말입니다.', `MaleText_loc4`='我有没有告诉过你，暮光之锤曾经想要征募我？千真万确。', `MaleText_loc5`='我有沒有跟你說過，那時候暮光之錘竟然想要吸收我加入的故事?是真的。', `MaleText_loc7`='¿Te he contado la historia de cuando el Martillo Crepuscular intentó reclutarme? Verdad de la buena.' WHERE `ID`=46837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기엔 너와 나뿐이다, $r. 한시라도 빨리 초갈을 처치하고 싶으니 어서 여기 일을 끝내자.', `FemaleText_loc4`='这话别告诉别人，$r。让我们赶快把这里的问题解决掉。这样我就能去干掉古加尔了。', `FemaleText_loc5`='就只剩你跟我了，$r。趕緊把這件事情解決掉，讓我可以去把丘加利給宰了。', `FemaleText_loc7`='Solo quedamos tú y yo, $r. Vamos a acabar con esto para que pueda ir a matar a Cho''gall.' WHERE `ID`=46838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세 개라고? 다섯 개는 충분할 것 같다, 이 바보야!', `MaleText_loc4`='三个？他至少值五个椰子，很轻松……蠢货！', `MaleText_loc5`='三?他應該要付五才對，簡單...笨蛋!', `MaleText_loc7`='¿TRES? Habrían pagado cinco encantados... ¡Tonto!' WHERE `ID`=46839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요.', `FemaleText_loc4`='你好。', `FemaleText_loc5`='你好。', `FemaleText_loc7`='Saludos.' WHERE `ID`=46840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 당신을 보게 되다니 기쁘군요, $n. 많은 우리 동지들이 대족장의 군대에 붙잡혔기에, 우린 당신을 다시는 보지 못할 거라 생각했답니다.', `FemaleText_loc4`='很高兴能在这里又看到你，$n。我们已经有许多兄弟姐妹落在了酋长的手里。我们还以为永远也见不到你了。', `FemaleText_loc5`='很高興又見面了，$n。有好多弟兄都被大酋長的部隊給困住了，我們還以為再也見不到你。', `FemaleText_loc7`='Nos alegramos de volver a verte, $n. Con tantos de nuestros hermanos en manos de las fuerzas del Jefe de Guerra, pensábamos que no volveríamos a verte.' WHERE `ID`=46841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기다. 뭔가 알아냈나? 뒤를 밟힌 건 아니겠지, $n?', `FemaleText_loc4`='有什么发现吗，$n？有没有被跟踪？', `FemaleText_loc5`='這邊!有找到什麼嗎?有沒有被人跟蹤，$n?', `FemaleText_loc7`='Estoy aquí. ¿Has descubierto algo? ¿Te han seguido, $n?' WHERE `ID`=46842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초갈이 만드는 불가사의한 무기에 대해 모든 걸 알아내야 한다. 되도록 빨리!', `FemaleText_loc4`='我们需要尽快搞清楚古加尔到底在制造一种什么样的武器！', `FemaleText_loc5`='我們必須挖掘出丘加利正在製作的武器的所有相關情報，而且動作要快!', `FemaleText_loc7`='¡Tenemos que saberlo todo sobre esa arma en la que está trabajando Cho''gall, y rápido!' WHERE `ID`=46843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 황혼의 망치단 놈들은 앞날에 닥칠 고통에 대해 전혀 모르고 있다.', `FemaleText_loc4`='那些暮光白痴根本不知道他们在制造什么样的灾难。', `FemaleText_loc5`='這些暮光蠢蛋根本不曉得會有什麼樣的痛苦在等著他們。', `FemaleText_loc7`='Esos idiotas Crepusculares no tienen ni idea de la que se les avecina.' WHERE `ID`=46844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초갈은 계속해서 황혼의 요새 안에 처박혀 있군. 밖에서 놀기로 마음을 고쳐먹어 주면 좋겠는데.', `FemaleText_loc4`='古加尔一直藏在暮光堡垒里。真希望他能出来，好好和我们玩一玩。', `FemaleText_loc5`='丘加利就躲在暮光堡壘裡頭，我希望他會出來跟我們玩玩。', `FemaleText_loc7`='Cho''gall se mantiene oculto dentro de El Bastión del Crepúsculo. Espero que decida salir a jugar.' WHERE `ID`=46845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목숨을 잃을 수도 있는 임무이다. 불만은 없었으면 좋겠군, $n.', `FemaleText_loc4`='希望你已经为这个有去无回的任务做好了准备，$n。', `FemaleText_loc5`='我希望你已經準備好要進行這個無法回頭的任務了，$n。', `FemaleText_loc7`='Espero que estés $glisto:lista; para una misión sin retorno, $n.' WHERE `ID`=46846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있는 이교도와 놈들의 지도자를 전부 처치해야 황혼의 요새를 공략할 수 있다.', `FemaleText_loc4`='我们需要消灭所有邪教徒和他们的领袖，这样我们才能占领暮光堡垒。', `FemaleText_loc5`='我們得先殺光這些教徒和他們的首領，才有辦法攻下這座暮光堡壘。', `FemaleText_loc7`='Tenemos que matar a todos esos cultores y a sus jefes antes de asaltar El Bastión del Crepúsculo.' WHERE `ID`=46847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한때 초갈 놈은 단 한 마디 마법의 단어로 날 멋대로 지배했다. 그러곤 그다지 자랑스럽지 않은 여러 가지 일을 저지르게 했지. 놈에게 10배로 되갚아줄 것이다. 그리고 넌 내 복수를 도와야 한다, $n!', `FemaleText_loc4`='古加尔曾经用一个魔法咒语控制了我的心神，让我做了许多令我深感羞耻的事情。我要让他付出十倍的代价。而你要帮助我，$n！', `FemaleText_loc5`='丘加利曾經只要唸出一句魔法咒語就可以控制住我，而且他還叫我去做了許多見不得人的下流勾當。我要十倍奉還給他，而且你一定要幫我，$n!', `FemaleText_loc7`='Antes Cho''gall podía controlar mi mente con solo pronunciar una palabra mágica. Me obligó a hacer muchas cosas de las que no estoy nada orgullosa. Me las pagará con creces, ¡y tú me ayudarás, $n!' WHERE `ID`=46848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가라! 더러운 이교도 같으니.', `MaleText_loc4`='来吧，肮脏的邪教徒。', `MaleText_loc5`='走吧，該死的教徒。', `MaleText_loc7`='En marcha, basura cultora.', `FemaleText_loc1`='어서 가라! 더러운 이교도 같으니.', `FemaleText_loc4`='来吧，肮脏的邪教徒。', `FemaleText_loc5`='走吧，該死的教徒。', `FemaleText_loc7`='En marcha, basura cultora.' WHERE `ID`=46849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소. 내가 선두에 서서 마차를 목적지까지 안내하겠소. 후방에서 우릴 노리는 적이 없도록 처리해 주시오. 모든 준비를 마치면 다시 이야기합시다.', `MaleText_loc4`='好的，我会让这辆马车直达目的地。你留在后面，扫除我们的一切踪迹。准备好以后就告诉我。', `MaleText_loc5`='好，我會帶領商隊前往我們的目的地，你留在後面確保沒有人追過來。等你準備好了就跟我說一聲。', `MaleText_loc7`='Vale, encabezaré la caravana hasta su destino. Tú quédate atrás y asegúrate de que la retaguardia está despejada. Avísame cuando estés $glisto:lista;.' WHERE `ID`=46850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 의심하다니.', `MaleText_loc4`='你怎么敢质问我？', `MaleText_loc5`='你竟敢質疑我。', `MaleText_loc7`='Cómo te atreves a interrogarme.', `FemaleText_loc1`='감히 날 의심하다니.', `FemaleText_loc4`='你怎么敢质问我？', `FemaleText_loc5`='你竟敢質疑我。', `FemaleText_loc7`='Cómo te atreves a interrogarme.' WHERE `ID`=46851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 의심을 받다니 모욕적이군요.', `MaleText_loc4`='你的质问损害了我的荣誉。', `MaleText_loc5`='你的質問玷污了我的名譽。', `MaleText_loc7`='Insultas mi honor con tus pesquisas.', `FemaleText_loc1`='이런 의심을 받다니 모욕적이군요.', `FemaleText_loc4`='你的质问损害了我的荣誉。', `FemaleText_loc5`='你的質問玷污了我的名譽。', `FemaleText_loc7`='Insultas mi honor con tus pesquisas.' WHERE `ID`=46852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아무것도 감출 게 없소.', `MaleText_loc4`='我没有什么可隐瞒的。', `MaleText_loc5`='我沒什麼好隱瞞的。', `MaleText_loc7`='No tengo nada que ocultar.', `FemaleText_loc1`='난 아무것도 감출 게 없소.', `FemaleText_loc4`='我没有什么可隐瞒的。', `FemaleText_loc5`='我沒什麼好隱瞞的。', `FemaleText_loc7`='No tengo nada que ocultar.' WHERE `ID`=46853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수색을 빨리 끝내주십시오. 서둘러 가야 할 곳이 있으니까.', `MaleText_loc4`='搜查快一点，我还要赶时间呢。', `MaleText_loc5`='搜快一點，我還有別的地方要去。', `MaleText_loc7`='Registra rápido, tengo una cita.', `FemaleText_loc1`='수색을 빨리 끝내주세요. 서둘러 가야 할 곳이 있으니까요.', `FemaleText_loc4`='搜查快一点，我还要赶时间呢。', `FemaleText_loc5`='搜快一點，我還有別的地方要去。', `FemaleText_loc7`='Registra rápido, tengo una cita.' WHERE `ID`=46854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광 도구는 가져왔길 바랍니다. 여기보다 고대의 보물을 파내기 좋은 곳은 없으니까요.', `MaleText_loc4`='希望你带来了矿工锄，朝圣者。没有任何地方能比这里更适合挖掘古代宝藏了。', `MaleText_loc5`='希望你有把採礦鎬帶在身上。沒有比這裡更適合挖掘古代寶藏的地方了。', `MaleText_loc7`='Espero que hayas traído un pico, $gperegrino:peregrina;. No hay un lugar mejor para excavar tesoros antiguos.' WHERE `ID`=46855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 문제없군요. 들어가도 좋습니다.', `MaleText_loc4`='看上去没有问题，你可以走了。', `MaleText_loc5`='一切正常。你可以走了。', `MaleText_loc7`='Todo parece estar en regla, puedes irte.', `FemaleText_loc1`='모두 문제없네요. 들어가도 좋아요.', `FemaleText_loc4`='看上去没有问题，你可以走了。', `FemaleText_loc5`='一切正常。你可以走了。', `FemaleText_loc7`='Todo parece estar en regla, puedes irte.' WHERE `ID`=46856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시에 들어가도 좋습니다.', `MaleText_loc4`='你可以进城了。', `MaleText_loc5`='你可以進城了。', `MaleText_loc7`='Puedes acceder a la ciudad.', `FemaleText_loc1`='도시에 들어가도 좋아요.', `FemaleText_loc4`='你可以进城了。', `FemaleText_loc5`='你可以進城了。', `FemaleText_loc7`='Puedes acceder a la ciudad.' WHERE `ID`=46857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마에 들어가도 좋습니다.', `MaleText_loc4`='你可以进入奥格瑞玛了。', `MaleText_loc5`='你可以進入奧格瑪。', `MaleText_loc7`='Eres libre de entrar en Orgrimmar.', `FemaleText_loc1`='오그리마에 들어가도 좋아요.', `FemaleText_loc4`='你可以进入奥格瑞玛了。', `FemaleText_loc5`='你可以進入奧格瑪。', `FemaleText_loc7`='Eres libre de entrar en Orgrimmar.' WHERE `ID`=46858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 문제없군요. 가봐도 좋습니다.', `MaleText_loc4`='一切都没问题。你可以走了。', `MaleText_loc5`='都很正常，你可以走了。', `MaleText_loc7`='Todo en orden. Puedes pasar.', `FemaleText_loc1`='모두 문제없군요. 가봐도 좋습니다.', `FemaleText_loc4`='一切都没问题。你可以走了。', `FemaleText_loc5`='都很正常，你可以走了。', `FemaleText_loc7`='Todo en orden. Puedes pasar.' WHERE `ID`=46859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 없군요. 들어가십시오.', `MaleText_loc4`='没有问题，可以走了。', `MaleText_loc5`='檢查完畢，你可以走了。', `MaleText_loc7`='De acuerdo, puedes pasar.', `FemaleText_loc1`='이상 없네요. 들어가세요.', `FemaleText_loc4`='没有问题，可以走了。', `FemaleText_loc5`='檢查完畢，你可以走了。', `FemaleText_loc7`='De acuerdo, puedes pasar.' WHERE `ID`=46860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 그럼 전 이만 가보겠습니다.', `MaleText_loc4`='谢谢，我走了。', `MaleText_loc5`='謝謝你，那我走了。', `MaleText_loc7`='Gracias, me voy ahora mismo.', `FemaleText_loc1`='감사합니다. 그럼 전 이만 가볼게요.', `FemaleText_loc4`='谢谢，我走了。', `FemaleText_loc5`='謝謝你，那我走了。', `FemaleText_loc7`='Gracias, me voy ahora mismo.' WHERE `ID`=46861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도의 로브 아닙니까? 경비병!', `MaleText_loc4`='一件邪教徒的长袍，卫兵！', `MaleText_loc5`='那是教徒的衣服。守衛!', `MaleText_loc7`='Esa es una toga de cultor. ¡Guardia!', `FemaleText_loc1`='이교도의 로브 아닌가요? 경비병!', `FemaleText_loc4`='一件邪教徒的长袍，卫兵！', `FemaleText_loc5`='那是教徒的衣服。守衛!', `FemaleText_loc7`='Esa es una toga de cultor. ¡Guardia!' WHERE `ID`=46862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 물건이군요. 당신은 들여보내 드릴 수 없습니다.', `MaleText_loc4`='这看起来很可疑，我不能让你进去。', `MaleText_loc5`='這看起來有點可疑，我不能放你進去。', `MaleText_loc7`='Esto parece sospechoso. No puedo dejarte pasar.', `FemaleText_loc1`='수상한 물건이군요. 당신은 들여보내 드릴 수 없네요.', `FemaleText_loc4`='这看起来很可疑，我不能让你进去。', `FemaleText_loc5`='這看起來有點可疑，我不能放你進去。', `FemaleText_loc7`='Esto parece sospechoso. No puedo dejarte pasar.' WHERE `ID`=46863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 이교도의 문학 작품이군요. 당신이 오그리마에 들어갈 방법은 수갑을 차고 들어가는 방법뿐입니다.', `MaleText_loc4`='这是邪教文书，你只能戴着镣铐进奥格瑞玛了。', `MaleText_loc5`='這是邪教的文獻。你等著被銬押進奧格瑪吧。', `MaleText_loc7`='Esto es un texto de cultor. La única forma de que entres en Orgrimmar es cargado de cadenas.', `FemaleText_loc1`='이건 이교도의 문학 작품이군요. 당신이 오그리마에 들어갈 방법은 수갑을 차고 들어가는 방법뿐입니다.', `FemaleText_loc4`='这是邪教文书，你只能戴着镣铐进奥格瑞玛了。', `FemaleText_loc5`='這是邪教的文獻。你等著被銬押進奧格瑪吧。', `FemaleText_loc7`='Esto es un texto de cultor. La única forma de que entres en Orgrimmar es cargado de cadenas.' WHERE `ID`=46864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단 메달? 경비병!', `MaleText_loc4`='暮光之锤的徽章？卫兵！', `MaleText_loc5`='暮光之錘的勳章?守衛!', `MaleText_loc7`='¿Un medallón del Martillo Crepuscular? ¡Guardia!', `FemaleText_loc1`='황혼의 망치단 메달? 경비병!', `FemaleText_loc4`='暮光之锤的徽章？卫兵！', `FemaleText_loc5`='暮光之錘的勳章?守衛!', `FemaleText_loc7`='¿Un medallón del Martillo Crepuscular? ¡Guardia!' WHERE `ID`=46865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 이교도 선전물이군요. 당신을 체포합니다.', `MaleText_loc4`='邪教的宣传手册。你被逮捕了！', `MaleText_loc5`='邪教的宣傳品。你被逮捕了!', `MaleText_loc7`='Esto es propaganda de los cultores. ¡Estás bajo arresto!', `FemaleText_loc1`='이건 이교도 선전물이군요. 당신을 체포합니다.', `FemaleText_loc4`='邪教的宣传手册。你被逮捕了！', `FemaleText_loc5`='邪教的宣傳品。你被逮捕了!', `FemaleText_loc7`='Esto es propaganda de los cultores. ¡Estás bajo arresto!' WHERE `ID`=46866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 이교도의 물건을 가지고 있어서 오그리마로 들여보낼 수 없습니다.', `MaleText_loc4`='我不能让你带着这些邪教文章进入奥格瑞玛。', `MaleText_loc5`='你身上有教徒的東西，我不能夠放你進城。', `MaleText_loc7`='No puedo dejarte entrar en Orgrimmar con estos artículos de cultor.', `FemaleText_loc1`='당신은 이교도의 물건을 가지고 있어서 오그리마로 들여보낼 수 없습니다.', `FemaleText_loc4`='我不能让你带着这些邪教文章进入奥格瑞玛。', `FemaleText_loc5`='你身上有教徒的東西，我不能夠放你進城。', `FemaleText_loc7`='No puedo dejarte entrar en Orgrimmar con estos artículos de cultor.' WHERE `ID`=46867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수상한 쪽지는 뭐지? 경비병, 이 사람을 감금하게.', `MaleText_loc4`='这些可疑的文件是什么？卫兵，监押这个人。', `MaleText_loc5`='這些可疑的文件是什麼?衛兵，把這位市民拘留起來。', `MaleText_loc7`='¿Qué son estos papeles sospechosos? Guardia, arresta a este ciudadano.', `FemaleText_loc1`='이 수상한 쪽지는 뭐죠? 경비병, 이 사람을 감금하세요.', `FemaleText_loc4`='这些可疑的文件是什么？卫兵，监押这个人。', `FemaleText_loc5`='這些可疑的文件是什麼?衛兵，把這位市民拘留起來。', `FemaleText_loc7`='¿Qué son estos papeles sospechosos? Guardia, arresta a este ciudadano.' WHERE `ID`=46868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지? 난 아무 짓도 안 했다고!', `MaleText_loc4`='这是什么？我什么都没做！', `MaleText_loc5`='幹什麼?我什麼也沒做啊!', `MaleText_loc7`='¿Qué? ¡Yo no he hecho nada!', `FemaleText_loc1`='이게 뭐지? 난 아무 짓도 안 했다고!', `FemaleText_loc4`='这是什么？我什么都没做！', `FemaleText_loc5`='幹什麼?我什麼也沒做啊!', `FemaleText_loc7`='¿Qué? ¡Yo no he hecho nada!' WHERE `ID`=46869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 모두 갖추고 준비가 되면 내게 말해 주시오, $n.', `MaleText_loc4`='装完车，做好准备之后就告诉我，$n。', `MaleText_loc5`='都準備好了就跟我說一聲，$n。', `MaleText_loc7`='Avísame cuando estés $gcargado y listo:cargada y lista;, $n.' WHERE `ID`=46870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발합시다!', `MaleText_loc4`='我们出发！', `MaleText_loc5`='走吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='출발하세요!', `FemaleText_loc4`='我们出发！', `FemaleText_loc5`='走吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=46871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 정령의 저주를 받을 것이다!', `MaleText_loc4`='元素诅咒你！', `MaleText_loc5`='元素詛咒你!', `MaleText_loc7`='¡Que los elementos te maldigan!' WHERE `ID`=46872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 대족장의 개일 뿐이라고!', `MaleText_loc4`='你只是酋长的一条狗！', `MaleText_loc5`='你只不過是大酋長的走狗!', `MaleText_loc7`='¡No eres más que el perro del Jefe de Guerra!' WHERE `ID`=46873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 칼날단이 몰락한 이후, 우리 검귀들은 자신과 종족 모두를 악마의 지배에서 건져내겠다고 맹세했다네.$B$B그 일은 끝났을지 모르지만, 아직 난 충분한 명예를 얻지 못했지.$B$B호드를 위해 싸울걸세. 다른 전사들도 그리하도록 훈련할 테고. 전장에서 영광스럽게 죽는 그날까지 말이야. 이게 유일하게 내가 가고자 하는 길일세.$B$B자네는 훈련받을 준비가 되었나?', `MaleText_loc4`='在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。$B$B好吧，你准备好进行训练了吗？', `MaleText_loc5`='在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有污點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。$B$B那麼，你準備好接受訓練了嗎?', `MaleText_loc7`='Tras la caída del clan Filo Ardiente, los maestros del acero juramos liberarnos a nosotros y a nuestra gente del control demoníaco.$b$bLo conseguimos, pero mi honor aún no está satisfecho.$b$bLucharé por la Horda, y entrenaré a otros guerreros para que hagan lo mismo, hasta que muera gloriosamente en la batalla. Es el único camino que seguiré.$b$b¿Y bien? ¿Estás $glisto:lista; para la instrucción?', `FemaleText_loc1`='불타는 칼날단이 몰락한 이후, 우리 검귀들은 자신과 종족 모두를 악마의 지배에서 건져내겠다고 맹세했다네.$B$B그 일은 끝났을지 모르지만, 아직 난 충분한 명예를 얻지 못했지.$B$B호드를 위해 싸울걸세. 다른 전사들도 그리하도록 훈련할 테고. 전장에서 영광스럽게 죽는 그날까지 말이야. 이게 유일하게 내가 가고자 하는 길일세.$B$B자네는 훈련받을 준비가 되었나?', `FemaleText_loc4`='在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。$B$B好吧，你准备好进行训练了吗？', `FemaleText_loc5`='在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有污點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。$B$B那麼，你準備好接受訓練了嗎?', `FemaleText_loc7`='Tras la caída del clan Filo Ardiente, los maestros del acero juramos liberarnos a nosotros y a nuestra gente del control demoníaco.$b$bLo conseguimos, pero mi honor aún no está satisfecho.$b$bLucharé por la Horda, y entrenaré a otros guerreros para que hagan lo mismo, hasta que muera gloriosamente en la batalla. Es el único camino que seguiré.$b$b¿Y bien? ¿Estás $glisto:lista; para la instrucción?' WHERE `ID`=46874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파리가 또 하나 거미줄에 걸려들었군...', `MaleText_loc4`='又一只落进蜘蛛网的苍蝇……', `MaleText_loc5`='又一隻飛蟲撲進了蜘蛛的網...', `MaleText_loc7`='Otra mosca cae en la tela de araña...', `FemaleText_loc1`='파리가 또 하나 거미줄에 걸려들었군...', `FemaleText_loc4`='又一只落进蜘蛛网的苍蝇……', `FemaleText_loc5`='又一隻飛蟲撲進了蜘蛛的網...', `FemaleText_loc7`='Otra mosca cae en la tela de araña...' WHERE `ID`=46875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들 덕분에 가짜 두목이 쓰러졌군.', `MaleText_loc4`='假首脑终于被消灭了，感谢你们，冒险者。', `MaleText_loc5`='冒險者，謝謝你們打敗了那位假的首腦。', `MaleText_loc7`='El falso líder ha caído gracias a ustedes, aventureros.' WHERE `ID`=46876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 칼날단이 몰락한 이후, 우리 검귀들은 자신과 종족 모두를 악마의 지배에서 건져내겠다고 맹세했다네.$B$B그 일은 끝났을지 모르지만, 아직 난 충분한 명예를 얻지 못했지.$B$B호드를 위해 싸울걸세. 다른 전사들도 그리하도록 훈련할 테고. 전장에서 영광스럽게 죽는 그날까지 말이야. 이게 유일하게 내가 가고자 하는 길일세.', `MaleText_loc4`='在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。', `MaleText_loc5`='在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有污點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。', `MaleText_loc7`='Tras la caída del clan Filo Ardiente, los maestros del acero juramos liberarnos a nosotros y a nuestra gente del control demoníaco.$b$bLo conseguimos, pero mi honor aún no está satisfecho.$b$bLucharé por la Horda, y entrenaré a otros guerreros para que hagan lo mismo, hasta que muera gloriosamente en la batalla. Es el único camino que seguiré.', `FemaleText_loc1`='불타는 칼날단이 몰락한 이후, 우리 검귀들은 자신과 종족 모두를 악마의 지배에서 건져내겠다고 맹세했다네.$B$B그 일은 끝났을지 모르지만, 아직 난 충분한 명예를 얻지 못했지.$B$B호드를 위해 싸울걸세. 다른 전사들도 그리하도록 훈련할 테고. 전장에서 영광스럽게 죽는 그날까지 말이야. 이게 유일하게 내가 가고자 하는 길일세.', `FemaleText_loc4`='在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。', `FemaleText_loc5`='在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有污點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。', `FemaleText_loc7`='Tras la caída del clan Filo Ardiente, los maestros del acero juramos liberarnos a nosotros y a nuestra gente del control demoníaco.$b$bLo conseguimos, pero mi honor aún no está satisfecho.$b$bLucharé por la Horda, y entrenaré a otros guerreros para que hagan lo mismo, hasta que muera gloriosamente en la batalla. Es el único camino que seguiré.' WHERE `ID`=46877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바네사 밴클리프는 아직 음모를 꾸미며 어딘가에 숨어 있네. 다행히도 이 기지 없이는 그녀도 강력한 얼라이언스 앞에서 크게 힘을 쓸 수는 없네.', `MaleText_loc4`='梵妮莎·范克里夫仍然在逃，谋划与我们对抗。但没有了这个基地，她已经无法对联盟造成威胁了。', `MaleText_loc5`='凡妮莎·范克里夫至今依然逍遙法外，圖謀不利於我們的詭計。還好，失去了這座基地之後，她應當再也無力對抗聯盟的力量了。', `MaleText_loc7`='Vanessa VanCleef sigue ahí fuera, en alguna parte, maquinando contra nosotros. Afortunadamente, sin esta base está prácticamente impotente ante la fuerza de la Alianza.' WHERE `ID`=46878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 폐광을 정리하기 시작하면, 일이 제대로 되도록 주의를 기울이겠네. 운이 따르면 이곳은 다시 예전처럼 유명한 금 광산이 되겠지. 그리고, 저 가짜 두목에 대해 한 마디 하자면...', `MaleText_loc4`='当我们清理死亡矿井的时候，我会提高警惕，防备任何可能发生的意外。希望我们能尽快让它恢复成往日那座著名的金矿。至于说那个首脑的命运……', `MaleText_loc5`='等開始清理死亡礦坑的時候，我一定會多加小心。希望礦坑可以盡快重新運作，恢復成以前那個著名的金礦坑。至於那個黑幫首腦的下落...', `MaleText_loc7`='Me aseguraré de tener los ojos abiertos cuando empecemos a limpiar las Minas de la Muerte. Con suerte podremos volver a utilizarla como la famosa mina de oro que fue en una época. En cuanto al destino del principal...' WHERE `ID`=46879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 쿠키란 게...', `MaleText_loc4`='这就是……', `MaleText_loc5`='反正...', `MaleText_loc7`='Así es...' WHERE `ID`=46880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 잘 부스러지는 법이지.', `MaleText_loc4`='……曲奇粉碎的方式。', `MaleText_loc5`='...人生就是這樣。', `MaleText_loc7`='... la vida.' WHERE `ID`=46881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역자들이라... 구덩이에 처넣게! 거기가 놈들이 원래 있어야 할 곳이니까.', `MaleText_loc4`='还有叛徒？把他们扔进大坑里去，那才是他们应该待的地方！', `MaleText_loc5`='還有叛徒?把他們關起來!', `MaleText_loc7`='¿Más traidores? ¡Llévalos al pozo, donde tienen que estar!' WHERE `ID`=46882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇠 우리 안에서 동전이나 물건을 내주는 일보다 호드의 은행과 보물을 지키는 일이 훨씬 맘에 든다네.$B$B저 연필이나 굴리는 고블린과 일을 바꿔 해보라면 아주 잠깐이라 해도 절대 응하지 않겠네.', `MaleText_loc4`='守卫部落的银行和财宝要比呆在一个铁笼子里分派钱币，收发物品有意思多了。$B$B我可不会和那些只知道耍笔杆子的地精交换工作。', `MaleText_loc5`='看守銀行和部落的財寶遠比躲在鐵籠裡收發錢幣和物品來得有意義多了。$B$B我一點也不想跟那些成天拿筆算錢記帳的哥布林交換工作。', `MaleText_loc7`='Proteger el banco y los tesoros de la Horda es mucho más satisfactorio que dispensar monedas y suministros comerciales dentro de una jaula de hierro.$b$bNo me cambiaría por uno de esos chupatintas goblins ni por un segundo.', `FemaleText_loc1`='쇠 우리 안에서 동전이나 물건을 내주는 일보다 호드의 은행과 보물을 지키는 일이 훨씬 맘에 든다네.$B$B저 연필이나 굴리는 고블린과 일을 바꿔 해보라면 아주 잠깐이라 해도 절대 응하지 않겠네.', `FemaleText_loc4`='守卫部落的银行和财宝要比呆在一个铁笼子里分发钱币，收发物品有意思多了。$B$B我可不会和那些只知道耍笔杆子的地精交换工作。', `FemaleText_loc5`='看守銀行和部落的財寶遠比躲在鐵籠裡收發錢幣和物品來得有意義多了。$B$B我一點也不想跟那些成天拿筆算錢記帳的哥布林交換工作。', `FemaleText_loc7`='Proteger el banco y los tesoros de la Horda es mucho más satisfactorio que dispensar monedas y suministros comerciales dentro de una jaula de hierro.$b$bNo me cambiaría por uno de esos chupatintas goblins ni por un segundo.' WHERE `ID`=46883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자를 찾아내라! 놈이 북쪽 어딘가에서 몰래 돌아다니는 걸 알고 있다!', `MaleText_loc4`='找到闯入者！我知道他们就藏在北边！', `MaleText_loc5`='把那些侵入者揪出來!我知道他們有人偷偷摸摸地躲在北邊那裡!', `MaleText_loc7`='¡Encontrad a los intrusos! ¡Sé que tienen a alguien infiltrándose por el norte!' WHERE `ID`=46884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='툭 튀어나온 그 흐리멍덩한 눈을 크게 뜨지 못할까! 우리 사이에 침입자가 있다.', `MaleText_loc4`='把你们的水泡眼睁大一点！我们中间有入侵者。', `MaleText_loc5`='把你眼珠子放亮一點!有入侵者混入了我們。', `MaleText_loc7`='¡Mantengan sus ojos débiles y carnosos abiertos! Hay intrusos entre nosotros.' WHERE `ID`=46885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈 님의 영광을 위해 더 열심히 일해라!', `MaleText_loc4`='为了古加尔的的荣耀，工作得更卖力一些！', `MaleText_loc5`='為了丘加利的榮耀，更認真一點!', `MaleText_loc7`='¡Trabajad más por la gloria de Cho''gall!' WHERE `ID`=46886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사이에 이방인이 숨어 있다!', `MaleText_loc4`='我感觉到我们中间有一个外人！', `MaleText_loc5`='我感覺到了，有一個外人混了進來!', `MaleText_loc7`='¡Percibo a alguien entre nosotros que no encaja!' WHERE `ID`=46887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 무기가 완성될 것이다. 머지않아 어디서도 와일드해머와 용아귀 부족을 찾아볼 수 없게 되리라.', `MaleText_loc4`='这件武器很快就能完成了。蛮锤矮人和龙喉兽人都将不复存在。', `MaleText_loc5`='武器已快要完成，蠻錘和龍喉氏族末日將近。', `MaleText_loc7`='El arma se completará pronto. Los Martillo Salvaje y los Faucedraco están a punto de extinguirse.' WHERE `ID`=46888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병력을 모아 호수로 가라. 오늘이 가기 전에 백작부인 베랄을 해치워 버려라!', `MaleText_loc4`='集结一支部队，到湖边去。我要让瓦拉尔女伯爵活不过今天！', `MaleText_loc5`='募集人手到湖那邊去。我希望能在今天把女伯爵維羅消滅掉!', `MaleText_loc7`='Reúne una tropa y ve al lago. ¡Quiero que destruyas a la condesa Verrall antes de que acabe el día!' WHERE `ID`=46889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단에게 힘을!', `MaleText_loc4`='暮光之锤的力量，无人能挡！', `MaleText_loc5`='暮光之錘的力量!', `MaleText_loc7`='¡Poder para el Martillo Crepuscular!' WHERE `ID`=46890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박살의 땅과 승리자 거점을 공격할 준비를 해라!', `MaleText_loc4`='准备进攻粉碎者据点和胜利者岗哨！', `MaleText_loc5`='準備攻擊碎擊之地和勝利者崗哨!', `MaleText_loc7`='¡Prepárate para atacar Machacolpe y Paso del Invicto!' WHERE `ID`=46891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 아버지가 나를 저 항구 너머로 쏴주라고 하시는군.', `MaleText_loc4`='你的爸爸说要把我射过这片海湾。', `MaleText_loc5`='你爸爸說要發射我越過這個灣。', `MaleText_loc7`='Tu papá dice que me dispares al otro lado de la bahía.', `FemaleText_loc1`='너희 아버지가 날 저 항구 너머로 쏴주라고 하신단다.', `FemaleText_loc4`='你的爸爸说要把我射过这片海湾。', `FemaleText_loc5`='你爸爸說要發射我越過這個灣。', `FemaleText_loc7`='Tu papá dice que me dispares al otro lado de la bahía.' WHERE `ID`=46892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키건 대장님, 서쪽의 균열에서 정령이 더 몰려오고 있습니다.', `MaleText_loc4`='科甘长官。更多的元素正从裂隙西侧涌过来。', `MaleText_loc5`='基岡，長官，傳送門的西側有更多的元素怪突破出現了。', `MaleText_loc7`='Keegan, señor. Más elementales se abren paso por el lado oeste de la falla.', `FemaleText_loc1`='키건 대장님, 서쪽의 균열에서 정령이 더 몰려오고 있습니다.', `FemaleText_loc4`='科甘长官。更多的元素正从裂隙西侧涌过来。', `FemaleText_loc5`='基岡，長官，傳送門的西側有更多的元素怪突破出現了。', `FemaleText_loc7`='Keegan, señor. Más elementales se abren paso por el lado oeste de la falla.' WHERE `ID`=46893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛!', `MaleText_loc4`='是，长官！', `MaleText_loc5`='是，長官!', `MaleText_loc7`='¡Sí, señor!', `FemaleText_loc1`='옛!', `FemaleText_loc4`='是，长官！', `FemaleText_loc5`='是，長官!', `FemaleText_loc7`='¡Sí, señor!' WHERE `ID`=46894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이언을 찾아가게. 이언이 모은 그리핀 기수를 다 내보내서 놈들이 마을까지 오지 못하게 해.', `MaleText_loc4`='找到伊安。保护他召集的狮鹫骑士，和他们一同去挡住敌人，不要让敌人到达这个镇子。', `MaleText_loc5`='去找伊安，叫他出動所有的獅鷲騎士去攔截它們，別讓它們抵達鎮上。', `MaleText_loc7`='Encuentra a Iain. Controla a los jinetes de grifos que hayan conseguido reunir y detenlos antes de que lleguen a la ciudad.', `FemaleText_loc1`='이언을 찾아가게. 이언이 모은 그리핀 기수를 다 내보내서 놈들이 마을까지 오지 못하게 해.', `FemaleText_loc4`='找到伊安。保护他召集的狮鹫骑士，和他们一同去挡住敌人，不要让敌人到达这个镇子。', `FemaleText_loc5`='去找伊安，叫他出動所有的獅鷲騎士去攔截它們，別讓它們抵達鎮上。', `FemaleText_loc7`='Encuentra a Iain. Controla a los jinetes de grifos que hayan conseguido reunir y detenlos antes de que lleguen a la ciudad.' WHERE `ID`=46895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부팅 작업 완료. 목표 탐색 중...', `MaleText_loc4`='启动程序完毕。扫描目标……', `MaleText_loc5`='啟動程序完成。物件掃瞄中...', `MaleText_loc7`='Protocolo de inicio completado. Escaneando objetivo...' WHERE `ID`=46896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표물 확인. 검색 중...', `MaleText_loc4`='目标确认。扫描……', `MaleText_loc5`='物件辨識完成。進行掃瞄...', `MaleText_loc7`='Objetivo identificado. Escaneando...' WHERE `ID`=46897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 물체 발견. 예상 결과: 아제로스의 고대 신. 이상 물체 제거 시도...', `MaleText_loc4`='异常察觉。可能来源：艾泽拉斯上古之神。尝试排除异常……', `MaleText_loc5`='偵測到異常。可能來源:艾澤拉斯上古之神。嘗試移除異常...', `MaleText_loc7`='Anomalía detectada. Fuente probable: dios antiguo de Azeroth. Intentando expulsar anomalía...' WHERE `ID`=46898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 물체 제거 완료. 이전 단계 반복 중...', `MaleText_loc4`='异常排除。重复子程序……', `MaleText_loc5`='異常已移除。重複附屬程序...', `MaleText_loc7`='Anomalía expulsada. Repitiendo subprotocolo...' WHERE `ID`=46899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상 물체 제거 완료. 남은 재료 재조립 중...', `MaleText_loc4`='异常排除。重组剩余物料……', `MaleText_loc5`='異常已移除。重組剩餘素材...', `MaleText_loc7`='Anomalía expulsada. Recomponiendo material restante...' WHERE `ID`=46900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표 수집 완료. 변칙 발견되지 않음.', `MaleText_loc4`='可用目标编译。无异常。', `MaleText_loc5`='可行之主體已完成。無發現異常。', `MaleText_loc7`='Sujeto viable recompuesto. No se han detectado anomalías.' WHERE `ID`=46901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사용자 지정 프로토콜 완료. 대기 프로토콜 재가동.', `MaleText_loc4`='用户目标程序完成。停滞程序重新启动。', `MaleText_loc5`='使用者物件程序完成。重新啟動靜滯程序。', `MaleText_loc7`='Protocolo de objetivo de usuario completado. Protocolo de estasis reactivado.' WHERE `ID`=46902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸해골의 강대한 힘 앞에 무릎을 꿇어라!', `MaleText_loc4`='我将召唤末日枯骨的力量，在恐惧中颤抖吧！', `MaleText_loc5`='驚慌顫抖吧，看我召來強大的毀滅之顱!', `MaleText_loc7`='¡Tiembla de terror mientras convoco al poderoso Craneomuerte!', `FemaleText_loc1`='파멸해골의 강대한 힘 앞에 무릎을 꿇어라!', `FemaleText_loc4`='我将召唤末日枯骨的力量，在恐惧中颤抖吧！', `FemaleText_loc5`='驚慌顫抖吧，看我召來強大的毀滅之顱!', `FemaleText_loc7`='¡Tiembla de terror mientras convoco al poderoso Craneomuerte!' WHERE `ID`=46903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 거대한 크기를 보라! 필멸자여, 두렵지 아니한가? 이렇게 거대한 파멸의 화신을 본 적이 있는가?', `MaleText_loc4`='看看它有多么巨大！你不害怕吗，凡人？你是否见到过如此伟大的毁灭之力？', `MaleText_loc5`='看看它龐大的體型!你是不是害怕啦，凡人?你有見勢過如此驚人的毀滅之力嗎?', `MaleText_loc7`='¡Contempla su increíble tamaño! ¿No tienes miedo, mortal? ¿Alguna vez has visto una muerte de semejante magnitud?', `FemaleText_loc1`='저 거대한 크기를 보라! 필멸자여, 두렵지 아니한가? 이렇게 거대한 파멸의 화신을 본 적이 있는가?', `FemaleText_loc4`='看看它有多么巨大！你不害怕吗，凡人？你是否见到过如此伟大的毁灭之力？', `FemaleText_loc5`='看看它龐大的體型!你是不是害怕啦，凡人?你有見勢過如此驚人的毀滅之力嗎?', `FemaleText_loc7`='¡Contempla su increíble tamaño! ¿No tienes miedo, mortal? ¿Alguna vez has visto una muerte de semejante magnitud?' WHERE `ID`=46904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물, 고개를 숙여라. 내가 충직한 늑대병정 부대를 소환하겠다!', `MaleText_loc4`='战栗吧，怪物，看我召唤出一支机械狼人的大军！', `MaleText_loc5`='恐懼吧，怪物，看我召喚出一整個狼怪大軍!', `MaleText_loc7`='¡Tiembla, monstruo, mientras invoco un auténtico ejército de loboides!', `FemaleText_loc1`='이 괴물, 고개를 숙여라. 내가 충직한 늑대병정 부대를 소환하겠다!', `FemaleText_loc4`='战栗吧，怪物，看我召唤出一支机械狼人的大军！', `FemaleText_loc5`='恐懼吧，怪物，看我召喚出一整個狼怪大軍!', `FemaleText_loc7`='¡Tiembla, monstruo, mientras invoco un auténtico ejército de loboides!' WHERE `ID`=46905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 늑대병정이 너를 포위하고 있다! 어쩌겠느냐? 어디로 도망치겠는가?', `MaleText_loc4`='现在，你已经被机械狼人包围了！你还能做些什么？你能逃到哪里去？', `MaleText_loc5`='現在你已經被狼怪包圍了!你要怎麼辦啊?你能逃到哪兒去啊?', `MaleText_loc7`='¡Ahora te rodean los loboides! ¿Qué harás? ¿Adónde puedes huir?', `FemaleText_loc1`='이제 늑대병정이 너를 포위하고 있다! 어쩌겠느냐? 어디로 도망치겠는가?', `FemaleText_loc4`='现在，你已经被机械狼人包围了！你还能做些什么？你能逃到哪里去？', `FemaleText_loc5`='現在你已經被狼怪包圍了!你要怎麼辦啊?你能逃到哪兒去啊?', `FemaleText_loc7`='¡Ahora te rodean los loboides! ¿Qué harás? ¿Adónde puedes huir?' WHERE `ID`=46906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라, 이 배은망덕한 정령아. 내가 얼마나 잘해줬는데!', `MaleText_loc4`='接受这个吧，忘恩负义的元素。我为你们付出的一切努力都白费了！', `MaleText_loc5`='不知感激的元素怪，虧我還為你做了這麼多事情。看招!', `MaleText_loc7`='Chúpate esa, elemental ingrato. ¡Después de todo lo que he hecho por ti!' WHERE `ID`=46907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하하하, 내게 불을 사용해? 지금 장난치는 것이냐?', `MaleText_loc4`='啊哈哈哈哈哈哈，开火？真的？', `MaleText_loc5`='啊哈哈哈哈哈，火?真的?', `MaleText_loc7`='¡JA, JA, JA, JA, JA! ¿FUEGO? ¿EN SERIO?' WHERE `ID`=46908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 네 친구를 처리하고 나면 다음은 네 차례다!', `MaleText_loc4`='我干掉你的朋友之后，下一个目标就是你！', `MaleText_loc5`='等我解決了你這位朋友之後，下一個就是你!', `MaleText_loc7`='¡TÚ SERÁS EL SIGUIENTE EN CUANTO TERMINE CON TU AMIGO!' WHERE `ID`=46909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래? 음... 놈을 잡아!!!', `MaleText_loc4`='哦，是吗？嗯……抓住他！！！', `MaleText_loc5`='哦是嗎?呃...幹掉他!!!', `MaleText_loc7`='¿Ah, sí? Eh... ¡¡por él!!' WHERE `ID`=46910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 시원하구나, 허풍쟁이 자식아. 콩알탄도 하나 못 터트릴 어설픈 불의 정령 같으니! 내가 다시는 널 소환하나 보자!', `MaleText_loc4`='终于摆脱了，你这个狂妄的，被烤熟的，痴迷爆炸的纵火狂！看我还会不会再召唤你！', `MaleText_loc5`='走得好!你這個吹過大的、考半熟的，想爆炸的爛東西!看我下次還要不要召喚你!', `MaleText_loc7`='¡Hasta nunca, pretencioso y contrahecho aspirante a ignición de bomba! ¡Ya veremos si alguna vez TE invoco de nuevo!' WHERE `ID`=46911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 이제 놈에게서 조종기를 얻어서 차원문에 사용하고 여길 빠져나가자고.', `MaleText_loc4`='好吧，让我们从他身上找到控制器，用这道传送门离开这里。', `MaleText_loc5`='好，讓我們把他身上的控制器拆下來，然後用傳送門離開這裡。', `MaleText_loc7`='Venga, vamos a quitarle el mando y utilizar el portal para salir de aquí.' WHERE `ID`=46912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게... 대체 무슨 일이지?', `MaleText_loc4`='这……这是什么？', `MaleText_loc5`='這...這是什麼?', `MaleText_loc7`='¿Qué... qué es esto?' WHERE `ID`=46913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 죽었는데! 황혼의 망치단이 날 살해했어.', `MaleText_loc4`='我死了！被暮光之锤杀死了。', `MaleText_loc5`='我死了!被暮光之錘給幹掉了。', `MaleText_loc7`='¡Estoy muerto! Asesinado por el Martillo Crepuscular.' WHERE `ID`=46914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수의 정령이 자네를 이곳으로 보냈군. 알고 싶은 게 있는 게야...', `MaleText_loc4`='洛克之灵派你到这里。你要寻找信息。', `MaleText_loc5`='是湖之精靈派你來打探消息的。', `MaleText_loc7`='El espíritu del lago te ha enviado aquí. Buscas información.' WHERE `ID`=46915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 우리를 붙잡아서 노예로 삼았네. 무기를 만들게 했지.', `MaleText_loc4`='他们捉住并奴役我们，逼迫我们制造一件武器。', `MaleText_loc5`='他們捕捉並且奴役了我們，逼我們製作一樣武器。', `MaleText_loc7`='Nos capturaron y esclavizaron. Nos pusieron a trabajar en un arma.' WHERE `ID`=46916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특별한 무기였네... 초갈을 위한 유물이었지.', `MaleText_loc4`='那是一件特殊的东西……一件古加尔所需要的东西。', `MaleText_loc5`='某種特別的計畫...為丘加利打造一件法器。', `MaleText_loc7`='Un proyecto especial... Un artefacto para Cho''gall.' WHERE `ID`=46917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 지금까지 만든 것 중 최고의 작품을 만들어냈네. 그리고 그 보답으로... 이렇게 됐지.', `MaleText_loc4`='我们被告知，我们将因为自己最伟大的工作而得到奖励，但我们……只得到了这样的下场。', `MaleText_loc5`='我們理當因為我們的辛勤付出與絕佳的成果而獲得獎賞，結果我們卻是...這樣。', `MaleText_loc7`='Nos iban a dar una recompensa por el mejor trabajo que jamás hubiéramos hecho, y nos la dieron... Esta.' WHERE `ID`=46918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 그 무기에 고대 신의 힘을 불어넣었네.', `MaleText_loc4`='他们将一位上古之神的力量注入这件武器。', `MaleText_loc5`='他們為它灌注了一位上古之神的力量。', `MaleText_loc7`='La imbuyeron con el poder de un dios antiguo.' WHERE `ID`=46919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 찾는 무기는... 황혼의 망치라고 하네.', `MaleText_loc4`='这件你正在寻找的武器被称为暮光神锤。', `MaleText_loc5`='你要找的武器叫做暮光神錘。', `MaleText_loc7`='El arma que buscas se llama el Martillo del Crepúsculo.' WHERE `ID`=46920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 날 그냥 내버려 두게. 빛이 보이는군...', `MaleText_loc4`='现在，走吧，我已看到了圣光……', `MaleText_loc5`='讓我靜一靜吧。我看見了聖光....', `MaleText_loc7`='Ahora déjame. Veo la Luz...' WHERE `ID`=46921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 힘... 너무 강해서... 나는... 더 이상... 버틸 수 없다...', `MaleText_loc4`='这股力量……太强大了……我坚持……不下去了……', `MaleText_loc5`='力量...太強大了...我快要...撐不住了...', `MaleText_loc7`='El poder... es demasiado... No puedo... aguantar más...' WHERE `ID`=46922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백작부인이 네놈들에게 귀찮은 일을 떠맡겼군? 육체의 소유자여, 네놈을 없애고 나서 백작부인도 처리해 주마!', `MaleText_loc4`='她派你来完成这个肮脏的任务，对不对？杀掉你之后，我自然会去对付她！', `MaleText_loc5`='是女伯爵派你來幹她的齷齪勾當，對不對?等我宰了你之後我再去對付她!', `MaleText_loc7`='Te ha enviado a hacer su trabajo sucio, ¿verdad? ¡Me encargaré de la condesa cuando te haya matado, ser de carne!' WHERE `ID`=46923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깨끗하기 그지없던 이 호수와 주변의 땅에 얼마 전 황혼의 망치단이 침범했다.$B$B놈들은 호수를 오염시켰지. 내 놈들을 몰아내고 다시 호수를 정화할 것이다.', `FemaleText_loc4`='不久之前，暮光之锤侵入了这片曾经质朴清澈的水域和它周围的岛屿。$B$B他们污染了我的湖水。我要彻底驱逐他们，这样我才能净化这片湖泊。', `FemaleText_loc5`='不久之前，暮光之錘入侵了這片原本純淨無瑕的水域以及周遭的土地。$B$B他們玷污了我的湖水，我希望能將他們逐走，好讓我重新淨化這座湖。', `FemaleText_loc7`='Hace poco el Martillo Crepuscular invadió estas aguas antes prístinas y las tierras que las rodean.$b$bHan contaminado mi lago, y quiero que se vayan para que pueda volver a purificarlo.' WHERE `ID`=46924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 아태릭 가까이에 있는 비전 마귀를 처치해서 차원의 방패에 과부하가 걸리게 해야 합니다!', `MaleText_loc4`='摧毁大法师阿塔瑞克身边的奥术魔，让防护盾过载！', `MaleText_loc5`='消滅大法師阿塔瑞克身邊的秘法惡魔，讓護盾超載!', `MaleText_loc7`='¡Destruye malignos Arcanos cerca del archimago Ataeric para sobrecargar el escudo!' WHERE `ID`=46925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 받으세요!', `MaleText_loc4`='尝尝这个吧！', `MaleText_loc5`='看招!', `MaleText_loc7`='¡Toma esto!', `FemaleText_loc1`='이걸 받으세요!', `FemaleText_loc4`='尝尝这个吧！', `FemaleText_loc5`='看招!', `FemaleText_loc7`='¡Toma esto!' WHERE `ID`=46926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 선장님.', `MaleText_loc4`='遵命，长官。', `MaleText_loc5`='是的，長官。', `MaleText_loc7`='Afirmativo, señor.' WHERE `ID`=46927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 오크와 인간이 처음으로 서로의 피를 본 장소에요. 남쪽으로 1Km도 안 되는 곳에 스토나드가 있어요. 오크가 우리 땅을 침략하기 위해 최초로 결집한 곳이죠.$B$B우리가 오크의 존재도 모르던 시절에 놈들은 여기서 병력을 모았지요. 서쪽의 작은 얼라이언스 마을 공격을 시작으로, 최초의 세 전쟁이 시작된 곳도 바로 여기고요.$B$B그곳은 제가 자란 마을이었어요. 저를 구하기 위해 부모님이 목숨을 바친 곳이죠.$B$B하지만 저는 한을 풀기 위해 이곳에 온 게 아니에요... 바로 전쟁에서 이기기 위해 이곳에 온 거예요.', `FemaleText_loc4`='这片土地是兽人和人类第一次展开大规模战争的地方。南边不到一里远就是斯通纳德。兽人在那里首次集结，入侵我们的国土。$B$B就是在这里，他们在我们不知不觉间聚集起大规模的军队。就是在这里，他们攻击西边的联盟小镇，拉开了三次兽人战争的序幕。$B$B那是我的城镇，为了救我，我的父母都死在了那里。$B$B但我来这里不是为了复仇……我是要赢得一场战争。', `FemaleText_loc5`='這裡正是獸人與人類初次灑下彼此血液的地方。斯通納德就在南方不到一哩之處，那是獸人初次集結入侵我們國土的地方。$B$B他們在此聚集大軍，而當時我們根本還不曉得他們的存在。也就是在這裡，他們揭開了前後三次大戰的序幕，首度對此處西邊的一座聯盟小鎮發動攻擊。$B$B我所居住的小鎮，我父母為拯救我而死的小鎮。$B$B但是，我不是來平息積怨的...我是要來打贏這場戰爭的。', `FemaleText_loc7`='Esta es la tierra en la que los orcos y los humanos derramaron la sangre del otro por primera vez. A un kilómetro de aquí yace Rocal, donde los orcos se agruparon por primera vez para invadir nuestras tierras.$b$bFue allí donde reunieron sus ejércitos antes de que supiéramos que existían. Fue allí donde comenzaron la primera de tres guerras cuando atacaron un pueblecito de la Alianza al oeste.$b$bMi pueblo. El pueblo en el que mis padres murieron para salvarme.$b$bPero no he venido para obtener venganza... He venido para ganar una guerra.' WHERE `ID`=46928;
