UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 움직여라. 주위를 경계하도록. 여기서 놈들을 막아내지 못하면 다음 차례는 썬더마다!', `MaleText_loc4`='来吧，小子们，在这里组织防御。我们要把敌人挡在这里，否则桑德玛尔就危险了！', `MaleText_loc5`='來吧，部屬好防線，在這裡守住，否則下個就輪到桑德瑪了!', `MaleText_loc7`='Vamos, chicos, estableced un perímetro. ¡Los rechazamos aquí o Bramal será el siguiente!' WHERE `ID`=46933;
