UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억!!! 너... 대체 무슨 짓을...?', `MaleText_loc4`='啊！！！什么……你怎么……？', `MaleText_loc5`='啊!!!什麼...你是怎麼...?', `MaleText_loc7`='¡Gah! ¿Qué...? ¿Cómo has...?' WHERE `ID`=46941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트위즐플럭스! 대체 무슨 미친 짓을 꾸미고 있는 거야? 네가 요청한 추가 인원을 데려왔는데, 여기서 대체 무슨... 연구를 한다는 거지? 미친 짓거리뿐이잖아!', `MaleText_loc4`='焊钩！你在发什么疯？我们带来了你需要的人员，但这里……根本没有什么研究工作。这里只有疯狂！', `MaleText_loc5`='推茲爾福勒克斯!你到底在幹什麼瘋狂的勾當?我們照你的要求帶了更多的人過來，可是這裡根本...沒有在做研究，只有瘋狂的行徑!', `MaleText_loc7`='¡Tornaflujo! ¿Has perdido la cordura? Hemos traído el personal adicional que solicitaste, pero aquí... ¡no hay ninguna investigación! ¡Solo locura!' WHERE `ID`=46942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨...???? 아아악...', `MaleText_loc4`='什么……？？？？啊……', `MaleText_loc5`='什麼????呃啊啊啊...', `MaleText_loc7`='¿¿¿¿Pero qué...???? AGGHGHhh...' WHERE `ID`=46943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니라고! 너희 모두 너무 늦었다! 모두 우리와 하나가 되어 이 세상을 뒤집어 놓을 비밀을 발굴하게 될 것이다!', `MaleText_loc4`='蠢货！对他们来说，一切都已经太晚了。对你们所有人来说都太晚了！你们要和我们一起发掘出这个将毁灭世界的秘密！', `MaleText_loc5`='笨蛋!他們已經來不及了，而且你們也全都來不及了!你們必須加入我們，跟我們一起挖掘出會震驚這個世界的秘密!', `MaleText_loc7`='¡Necios! Es demasiado tarde para ellos. ¡Es demasiado tarde para todos ustedes! ¡Se unirán a nosotros, y juntos desenterraremos secretos que desharán el mundo!' WHERE `ID`=46944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너... 다음은 네 차례다!', `MaleText_loc4`='而你……是下一个！', `MaleText_loc5`='接下來...就是你!', `MaleText_loc7`='Y ahora te toca... ¡a ti!' WHERE `ID`=46945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 처음 보는 얼굴이군요. 당신도 집을 잃었나요? 괜찮으면 제 곁에 앉으시지요.', `FemaleText_loc4`='嗨！以前没有见过你。你也失去了家园吗？如果你愿意，可以和我坐在一起。', `FemaleText_loc5`='嗨!你是新來的。你也失去了你家嗎?願意的話，你可以跟我坐一起。', `FemaleText_loc7`='¡Hola! Eres $gnuevo:nueva;. ¿Tú también has perdido tu casa? Puedes sentarte a mi lado si quieres.' WHERE `ID`=46946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머나, 이럴 수가! 정말 감사해요! 이게 저한테 얼마나 중요한 물건인지 모르실 거예요. 참으로 친절한 분이시군요!', `FemaleText_loc4`='哦，天哪！真的是非常感谢你。你不知道这对我有多么重要。你真是最好的人！', `FemaleText_loc5`='哦我的天啊!真是太～～感謝你了!你不知道這對我的意義有多麼重大。你真的是太棒了!', `FemaleText_loc7`='¡Guau! ¡Muchísimas gracias! No tienes ni idea de lo que esto significa para mí. ¡Eres un encanto!' WHERE `ID`=46947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 와일드해머 드워프가 아닌데... 무슨 일로 여기 오셨죠? 정말 안 좋은 때를 골라서 오셨군요.', `FemaleText_loc4`='你肯定不是蛮锤的人。为什么要到这里来？不管怎样，你在这个时候跑到这里来，只能说是你的运气不好。', `FemaleText_loc5`='你肯定不是蠻錘的人。是什麼風把你吹來的?不過，你來得還真不是時候。', `FemaleText_loc7`='Está claro que no eres Martillo Salvaje. ¿Qué te trae por aquí? Has elegido un momento pésimo, eso desde luego.' WHERE `ID`=46948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건... 내 장미잖아! 카일린에게 들으셨나요? 정말 어떻게 감사해야 할지 모르겠군요. 그리운 내 집의 향기를 다시는 맡지 못할 줄 알았는데...', `FemaleText_loc4`='什……我的玫瑰？！是凯林告诉你的吗？真不知该怎样感谢你。我还以为自己再也闻不到家乡的气息了……', `FemaleText_loc5`='什麼...我的玫瑰?!是凱林跟你說的嗎?我真的是太感謝你了。我還以為這輩子再也聞不到家的味道了...', `FemaleText_loc7`='¿Qué...? ¡¿Mis rosas?! ¿Te lo ha contado Cailin? Nunca podré agradecértelo lo suficiente. Pensé que nunca volvería a oler mi hogar...' WHERE `ID`=46949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 젊은 $g총각:처자;.', `MaleText_loc4`='很高兴见到你，年轻的$g先生:女士;。', `MaleText_loc5`='很高興認識你，年輕人。', `MaleText_loc7`='Un placer conocerte, joven.' WHERE `ID`=46950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니...?!', `MaleText_loc4`='什么……？？', `MaleText_loc5`='搞什麼—??', `MaleText_loc7`='¿Qué...?' WHERE `ID`=46951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가족의 망치잖아?! 어째서 자네가 이런 수고를... 아니, 이유가 뭐든 상관없네. 우리 가족은 언제나 자넬 환영할 걸세. 식탁에 항상 자네 자리를 마련해 두겠어. 고맙네.', `MaleText_loc4`='我家的锤子？！怎么会在你这里……没关系，我不在乎这个，锤子回来了才是最重要的。我们永远都欢迎你，我们家的桌旁永远都有你的位置。谢谢你。', `MaleText_loc5`='我家的錘子啊?!到底是什麼東西把你給迷住了...算了，我不在乎。我們家永遠歡迎你，會為你保留一個席位。謝謝你。', `MaleText_loc7`='¡¿El martillo de mi familia?! ¿Qué te podría haber impulsado a...? No importa, me da igual. Siempre serás $gbienvenido:bienvenida; en nuestra casa. Te guardaremos un sitio en nuestra mesa. Gracias.' WHERE `ID`=46952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 안돼애애애!', `MaleText_loc4`='不……！', `MaleText_loc5`='不...不!', `MaleText_loc7`='No... ¡Nooooo!' WHERE `ID`=46953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌지워터 무역회사를 위하여! 으스러진 손을 위하여! 호드를 위하여!', `FemaleText_loc4`='为了锈水财阀！为了碎手军团！为了部落！', `FemaleText_loc5`='污水企業萬歲!破碎之手萬歲!部落萬歲!', `FemaleText_loc7`='¡Por el Cártel Pantoque! ¡Por la Mano Destrozada! ¡POR LA HORDA!' WHERE `ID`=46954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 어떻게 된 거지?', `MaleText_loc4`='我出了什么事？', `MaleText_loc5`='我是怎麼了?', `MaleText_loc7`='¿Qué me está pasando?' WHERE `ID`=46955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허에서 이걸 찾았습니다. 카일린이 당신 물건이라고 하던데요...', `MaleText_loc4`='我在这片废墟中找到了这个。凯林告诉我，这是你的……', `MaleText_loc5`='我在遺跡裡找到了這個。凱林跟我說它是你的東西...', `MaleText_loc7`='He encontrado esto en las ruinas. Cailin me ha dicho que es tuyo...', `FemaleText_loc1`='폐허에서 이걸 찾았어요. 카일린이 당신 물건이라고 하던데요...', `FemaleText_loc4`='我在这片废墟中找到了这个。凯林告诉我，这是你的……', `FemaleText_loc5`='我在遺跡裡找到了這個。凱林跟我說它是你的東西...', `FemaleText_loc7`='He encontrado esto en las ruinas. Cailin me ha dicho que es tuyo...' WHERE `ID`=46956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하!', `MaleText_loc4`='哈哈哈！', `MaleText_loc5`='哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja!' WHERE `ID`=46957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거, 당신 물건 맞지요, 미아라?', `MaleText_loc4`='相信这些应该是你的，米艾拉。', `MaleText_loc5`='我想這些東西應該是你的，米耶拉。', `MaleText_loc7`='Creo que son tuyas, Meara.', `FemaleText_loc1`='이거, 당신 물건 맞지요, 미아라?', `FemaleText_loc4`='相信这些应该是你的，米艾拉。', `FemaleText_loc5`='我想這些東西應該是你的，米耶拉。', `FemaleText_loc7`='Creo que son tuyas, Meara.' WHERE `ID`=46958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 잘못 본 게 아니라면, 이 물건은 당신 것 같은데요.', `MaleText_loc4`='如果我没弄错，这应该是你的。', `MaleText_loc5`='如果我沒弄錯的話，這應該是你的。', `MaleText_loc7`='Si no me equivoco, esto te pertenece.', `FemaleText_loc1`='제가 잘못 본 게 아니라면, 이 물건은 당신 것 같은데요.', `FemaleText_loc4`='如果我没弄错，这应该是你的。', `FemaleText_loc5`='如果我沒弄錯的話，這應該是你的。', `FemaleText_loc7`='Si no me equivoco, esto te pertenece.' WHERE `ID`=46959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저흰 놈들의 존재를 눈치채지 못했습니다... 놈들은 갑자기 고원 전역을 한꺼번에 공격했지요. 땅에서 불쑥 솟아나오고 공중을 휩쓸었습니다. 그리핀 편대 대부분이 흩어졌고, 너무나도 많은 훌륭한 드워프가 목숨을 잃었지요.$B$B키건이 우리를 이렇게 이끌어 주지 않았다면 우리에겐 전혀 희망이 없었을 겁니다. 전 그에게 목숨을 빚졌어요. 적어도 지금은 조금이나마 희망이 있으니까요.', `MaleText_loc4`='他们在我们没有察觉的时候偷袭了我们……同时对高地各处发动了攻击。他们破地而出，又从空中俯冲而下。大部分狮鹫都受惊逃走了。许多优秀的矮人白白牺牲。$B$B如果不是科甘及时将我们召集起来，重整了队伍，我们可能早已经被围歼了。是他救了我的命。至少现在，我们还有反击的机会。', `MaleText_loc5`='他們偷襲了我們...同時對整個高地發動攻擊，從地面冒出來，從天空撲下來。大多數的獅鷲獸都被擊傷了，而且有太多矮人也因此喪失了他們寶貴的性命。$B$B要是基岡沒有將我們給重新組織起來的話，我們可就真的完蛋了。我欠那個傢伙一命。至少，我們現在還有一線希望。', `MaleText_loc7`='Nos pillaron por sorpresa... Atacaron todas las tierras altas a la vez, salieron del suelo, cayeron del cielo. La mayoría de los grifos se separaron y muchos enanos buenos perdieron la vida.$b$bApenas habría habido esperanza si Keegan no nos hubiera reunido. Le debo la vida. Al menos ahora tenemos una posibilidad.' WHERE `ID`=46960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실히 이 지역 분은 아닌 듯한데... 뭐 어쨌든 상관없습니다. 누구든 간에 여기서 자기 역할만 확실히 해준다면, 전 기꺼이 그자를 위해 목숨을 걸 겁니다.', `MaleText_loc4`='你肯定不是本地人。不过这对我来说没什么关系。无论是谁，只要真心愿意帮助我们，我都会和他生死与共。', `MaleText_loc5`='你肯定不是本地人。但是無所謂，任何人只要肯認真盡好自己的本分，我都願意為他們賭上自己的性命。', `MaleText_loc7`='Está claro que no eres de aquí, pero a mí no me importa. Arriesgaré mi vida por todo aquel que esté contribuyendo.' WHERE `ID`=46961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계 조종 변환기를 사용하여 트위즐플럭스의 로봇을 정지시켜야 합니다!', `MaleText_loc4`='使用机械控制干扰器让焊钩的机械机甲无法运作！', `MaleText_loc5`='使用機甲控制干擾器來關掉推茲爾福勒克斯的載具!', `MaleText_loc7`='¡Utiliza el codificador meca-control para inutilizar el vehículo de Tornaflujo!' WHERE `ID`=46962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 오래전에 저주받은 우리 형제들을 연구하고, 이들의 고통을 치료할 방법을 찾기 위해 이곳으로 왔네.$B$B막투르는 그런 나를 두 팔 벌려 환영했어. 이곳에 살면서, 그는 내 가장 친한 친구가 됐지.$B$B그리고 지금, 그런 막투르가 내 눈앞에서 죽어가고 있네...', `MaleText_loc4`='我很久以前就来到这里，研究我们受到诅咒的兄弟，寻找治疗他们的办法。$B$B玛格图尔热情地欢迎我。我住在这里的时候，他成为了我最亲密的朋友。$B$B而现在，他躺在我面前，奄奄一息……', `MaleText_loc5`='我很久之前就來這邊研究我們受了詛咒的弟兄，尋找能夠治療他們的方法。$B$B瑪格圖爾張開雙臂歡迎我，而且後來還變成了我最要好的朋友。$B$B但如今，就在我的眼前，他就快死了...', `MaleText_loc7`='Vine aquí hace mucho para estudiar a nuestros hermanos malditos, en busca de una cura para su aflicción.$b$bMagtoor me recibió con los brazos abiertos. Desde que vivo aquí se ha convertido en mi mejor amigo.$b$bY ahora se está muriendo ante mis ojos...' WHERE `ID`=46963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 실망시켰군, 친구여. 미안하네.', `MaleText_loc4`='很抱歉，我辜负了你，我的朋友。', `MaleText_loc5`='我讓你失望了，朋友。我真的很抱歉。', `MaleText_loc7`='Te he fallado, amigo mío. Lo lamento muchísimo.' WHERE `ID`=46964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 때가 온 것뿐이야, 아분. 이건 누구의 잘못도 아닐세...', `MaleText_loc4`='该我了，阿弗恩。没有人应受责备……', `MaleText_loc5`='我的大限到了，艾弗恩。這不是任何人的錯...', `MaleText_loc7`='Ha llegado mi hora, Avuun. No es culpa de nadie...' WHERE `ID`=46965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...', `FemaleText_loc4`='……', `FemaleText_loc5`='...', `FemaleText_loc7`='...' WHERE `ID`=46966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 관상을 보아하니 돈이 좀 되겠는데. 대학살의 도가니에서 한판 해 보는 게 어때?', `MaleText_loc4`='看上去，你能为我们挣不少钱。去杀戮熔炉里转一圈如何，朋友？', `MaleText_loc5`='朋友，你看來好像有本事幫我們賺點錢的樣子。要不要進「兇殘之爐」競技場去打一場啊?', `MaleText_loc7`='Me das la impresión de que podrías ayudarnos a ganar dinero. ¿Qué te parece una vuelta en el Crisol de Matanza, colega?' WHERE `ID`=46967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암 불길을 피하십시오!', `MaleText_loc4`='躲开熔岩！', `MaleText_loc5`='避開熔岩浪潮!', `MaleText_loc7`='¡Evita las oleadas de lava!' WHERE `ID`=46968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 고원은 전부 다 용아귀 부족의 것이다! 이 구덩이도 마찬가지야!', `MaleText_loc4`='这片高地全都属于龙喉氏族，这个大坑也不例外！', `MaleText_loc5`='整座高地都是龍喉氏族的，就連這兒也一樣!', `MaleText_loc7`='¡Todas las tierras altas pertenecen a los Faucedraco, incluido este foso!' WHERE `ID`=46969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 여동생도 너희보다는 낫겠다. 이게 무슨 투기장이야? 보육원이지!', `MaleText_loc4`='我的小妹妹也能把你们都打趴下。这里不是竞技场。这里根本就是个托儿所！', `MaleText_loc5`='連我小妹都能打敗你們全部的人。這根本不是競技場，這是托兒所!', `MaleText_loc7`='Mi hermanita pequeña podría darles una paliza a todos. ¡Esto no es una arena, esto es una guardería!' WHERE `ID`=46970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 처치하면 네 몸뚱이 준다고 칼더 아빠가 약속했다!', `MaleText_loc4`='卡尔德说，如果我杀了你，我就能得到你的零件！', `MaleText_loc5`='考德爾說，要是我宰了你，我就可以分到你的一部分!', `MaleText_loc7`='¡Calder me ha dicho que si te mato, puedo quedarme con tus miembros!' WHERE `ID`=46971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 애송이들아. 이 아름다운 저녁에, 그렇게까지 놀랍지는 않은 놀라움을 하나 선사해 주지.', `MaleText_loc4`='你们好，伙计们，今晚，我为你们准备了一个不应该让你们太吃惊的惊喜。', `MaleText_loc5`='嗨，夥計們，今晚我有個不算太驚喜的驚喜要給你們。', `MaleText_loc7`='Vaya, hola, chicos. Tengo una sorpresa no muy sorprendente para ustedes esta noche.' WHERE `ID`=46972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 황혼의 불꽃 아래 정화되리라!', `MaleText_loc4`='这片土地应该在暮光烈焰中被净化！', `MaleText_loc5`='該以暮光之火淨化這片土地!', `MaleText_loc7`='¡La Llama del Crepúsculo purgará esta tierra!' WHERE `ID`=46973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 그냥 여기다 두고...', `FemaleText_loc4`='我会把这个留在这里。', `FemaleText_loc5`='我先把這個留在這兒。', `FemaleText_loc7`='Dejaré esto aquí.' WHERE `ID`=46974;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 알을 가지러...', `FemaleText_loc4`='现在该去找蛋了……', `FemaleText_loc5`='然後，去拿蛋...', `FemaleText_loc7`='Ahora, a por el huevo...' WHERE `ID`=46975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 귀여운 아가, 잘 있었니?', `FemaleText_loc4`='我的小宝贝怎么样了？', `FemaleText_loc5`='我的小寶貝怎麼樣啦?', `FemaleText_loc7`='¿Cómo está mi bebé?' WHERE `ID`=46976;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안돼... 너... 넌! 안돼!', `FemaleText_loc4`='不……是……是你！不！', `FemaleText_loc5`='不...是...是你!不!', `FemaleText_loc7`='No... Eres... ¡Eres tú! ¡NO!' WHERE `ID`=46977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 녀석... 나는 네가 필멸자들과 무슨 일을 꾸미는지 모두 알고 있다.', `MaleText_loc4`='你这个莽撞的小崽子……我知道你和那个凡人想要干什么。', `MaleText_loc5`='不自量力的小龍...我知道你和這些個凡人在打什麼主意。', `MaleText_loc7`='Cría insolente... Sé exactamente lo que estáis tramando tu mortal y tú.' WHERE `ID`=46979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 용이여, 죽을 각오는 되었느냐?', `MaleText_loc4`='准备好去死了吗，龙？', `MaleText_loc5`='準備受死了嗎，小龍?', `MaleText_loc7`='¿Estás lista para morir, dragona?' WHERE `ID`=46980;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 죽어도 되지만... 제발 알에게는 자비를...', `FemaleText_loc4`='是的，只是……请饶过这颗蛋。', `FemaleText_loc5`='是。請您...請您大發慈悲，饒了這些蛋。', `FemaleText_loc7`='Sí... Solo te pido que tengas piedad con el huevo.' WHERE `ID`=46981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비?!', `MaleText_loc4`='饶过？！', `MaleText_loc5`='饒?!', `MaleText_loc7`='¡¿Piedad?!' WHERE `ID`=46982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비란 없다! 모두 불로 심판받을 것이다!', `MaleText_loc4`='我什么也不会饶！你要为自己的冒犯而被烧为灰烬，龙！', `MaleText_loc5`='我才不會饒!死吧!', `MaleText_loc7`='¡NO HABRÁ PIEDAD! ¡ARDERÁS POR ESTO, DRAGONA!' WHERE `ID`=46983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라, 쥐새끼야! (벌레! 작고 약해!)', `MaleText_loc4`='回去，蛆虫！（软弱，渺小的虫子！）', `MaleText_loc5`='退下，害蟲!(蟲子!又小又弱!)', `MaleText_loc7`='¡Atrás, alimaña! (¡Insectos! ¡Débiles y pequeños!)' WHERE `ID`=46984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라, 필멸자여. 너에게 파멸을 안겨줄 도구를 보아라. (망치, 지하에 계신 신의 손.) 녹아내린 피로... (주인님의 선물! 주인님의 선물!) 마지막 폭풍의 제단에서 만든...', `MaleText_loc4`='看哪，凡人，这件造物便是你们的末日。（这战锤，是下界诸神之手。）用熔火之血铸造……（……主人的礼物。他的礼物！）在最后的风暴祭坛锻造。', `MaleText_loc5`='看吧，凡人，看著毀滅你們的工具吧!(錘子，下帝之手。)由熔火之血打造... (─主人給的禮物。他的禮物!)在最後一座暴風祭壇上成形。', `MaleText_loc7`='Mortal, contempla el instrumento de tu fin. (El martillo, la mano de los Dioses Abajo.) Forjado con sangre fundida... (...obsequio del amo. ¡Su obsequio!) Moldeado sobre el Último Altar de Tormenta.' WHERE `ID`=46985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치를. (황혼의 망치를!) 죽음의 위상, 그분의 뜻에 따라 만들어진, 세상을 산산조각낼 무기지. 네가 다룰 물건이 아니다. (침입자를 없애라!) 모두 없애라!', `MaleText_loc4`='暮光神锤。（暮光神锤！）它由死亡的化身赐予。是世界的破坏者。不是你能使用的。（消灭入侵者！）把他们杀光！', `MaleText_loc5`='暮光神錘。 (暮光神錘!)由死亡化身所下令，它將是摧毀世界的武器。這不是你所能揮動的武器。(殺死入侵者!)殺光他們!', `MaleText_loc7`='El Martillo del Crepúsculo. (¡El Martillo del Crepúsculo!) Encomendado por el Aspecto de la Muerte. Es el quebrador de mundos. Tú no puedes blandirlo. (¡Maten a los intrusos!) ¡Mátenlos a todos!' WHERE `ID`=46986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 님께서 시작하신 일은... (아무도 못 막아!) 아무도! 비참하기 그지없는 네놈들은 물론! (놈들의 최후를 보여줘.)', `MaleText_loc4`='死亡之翼开始行动了……（……没人能够阻止。）没有人！尤其是你们这些可怜虫（让他们，让他们彻底完蛋！）', `MaleText_loc5`='死亡之翼正在進行的─(...沒人可以阻止。) 沒有人!尤其是你們這些雜碎。(給他們看，他們的末日。)', `MaleText_loc7`='Lo que Alamuerte ha iniciado... (...nadie puede pararlo.) ¡Nadie! Menos ustedes, miserables. (Muéstrenles. ¡Muéstrenles su fin!)' WHERE `ID`=46987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웅장한 대학살의 도가니가 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!', `MaleText_loc4`='伟大的杀戮熔炉正在等着你，$n。记住，当战斗开始的时候，你将无法离开竞技场。你的结局非赢即死！', `MaleText_loc5`='偉大的兇殘之爐競技場正在等著你，$n。切記，一旦戰鬥開始了，你就得待在競技場的場地裡頭。不是勝利就是死亡!', `MaleText_loc7`='Te espera el gran Crisol de Matanza, $n. Recuerda, una vez empieza la pelea, tienes que permanecer en la arena. ¡GANA O MUERE!' WHERE `ID`=46988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 새로운 이야기가 시작됩니다. 대학살의 도가니에서 펼쳐지는 삶과 죽음의 드라마를 지켜보십시오! 이번에 $n의 상대는... 무지 뚱뚱한 오우거? 잠깐, 이게 뭐야?! 뭐? 시간이 없어서 이렇게밖에 못 썼다고? 그러고는 무슨 월급을 받겠다는 거야?!', `MaleText_loc4`='女士们，先生们，我们共聚在杀戮熔炉，再次见证生与死的伟大战斗！在这一轮中，我们将看到$n与……一个真正的肥食人魔对战？等等，这是真的？！我们就只能看到这个？我付钱给你是为了什么？', `MaleText_loc5`='女士先生們，我們又再度來到此處。生與死的精采掙扎即將在兇殘之爐競技場內展開!這一回合要和$n對決的是...一隻真的很肥的巨魔?等一下，這不是在搞笑吧?!什麼?臨時就只找得到這種選手?我付錢請你到底是幹什麼的?', `MaleText_loc7`='Aquí estamos de nuevo, damas y caballeros. ¡El épico conflicto entre vida y muerte en el Crisol de Matanza! En esta ronda tenemos a $n contra... ¿un orco bien gordo? ¡¿Cómo, en serio?! ¿Esto es lo mejor que hemos encontrado con poca antelación? ¿Para qué les pago?' WHERE `ID`=46989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하여튼, 전투를 시작합니다!', `MaleText_loc4`='不管怎样，让战斗开始吧！', `MaleText_loc5`='隨便啦，決鬥開始!', `MaleText_loc7`='¡Qué más da! ¡Que empiece la pelea!' WHERE `ID`=46990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 곧 시작됩니다! 잔인한 용아귀 부족, 비룡잡이 토르그와 $n의 대결입니다! 잔인한 상대 맞겠죠?! 뭐, 확실하진 않습니다만... 우리에게 자신들의 옛 싸움터를 내준 데 감사하는 뜻에서 그냥 그렇다고 쳐 주죠. 피비린내나는 한판을 기대해 봅시다!', `MaleText_loc4`='战斗就要开始了！$n对凶狠的龙喉兽人——“托格·掠龙者”！嗯，我想他应该是很凶狠的，虽然现在还很难说。既然他们让我们管理他们的老竞技场，我就把他放了出来。因为这里需要一些真正精彩的战斗！', `MaleText_loc5`='決鬥即將展開!由$n對決龍喉氏族最兇狠的獸人，托爾格·剝龍者!好啦，我覺得他應該是很兇狠才對啦—不過其實這也很難講，因為是龍喉氏族的傢伙把這個舊競技場給我們用，我才讓他參加的。好好流點血給我們瞧瞧吧!', `MaleText_loc7`='¡El combate está a punto de comenzar! ¡$n contra el sañoso Faucedraco, Torg Cazadraco! Bueno, CREO que es sañoso, es difícil de decir. Solo le he dejado pasar porque nos traspasaron esta vieja arena. ¡Ojalá haya sangre!' WHERE `ID`=46991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 이번엔 특별히 "조그만" 놀라움을 준비했습니다! 작은 고추가 매운 법! 잔인한 와일드해머 드워프... 설리 니캐퍼와 $n의 대결을 지켜보십시오!', `MaleText_loc4`='接下来为大家准备了个特别的节目！你们在这家伙面前简直渺小如微尘！$n对决凶残的蛮锤斗士……萨利·碎膝！！！', `MaleText_loc5`='各位觀眾!這回我特別安排了個「小」東西要給大家!告訴你們，你們連這個一半身高的傢伙的一半都比不上!由$n對決最兇、最狠的蠻錘矮人:蘇利·碎膝者!', `MaleText_loc7`='¡Esta vez tengo una PEQUEÑA sorpresa para ustedes, amigos! ¡No eres la mitad de hombre que este medio-hombre! ¡¡¡$n contra el despiadado SULLY CORTARRÓTULAS de los Martillo Salvaje!!!' WHERE `ID`=46992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 경기는 정말로 짧을 겁니다! 네, 네, 쓸데없는 소리는 이만 줄이지요. 피의 향연을 즐기십시오!', `MaleText_loc4`='这一战必定会速战速决！好吧，好吧，我说完了。血战开始！', `MaleText_loc5`='相信這場比賽肯定也只要一半的時間就會打完了!好了，好了，我說完了。開始屠殺吧!', `MaleText_loc7`='¡Esta pelea seguro que será de CORTA duración! Está bien, está bien, ya termino. ¡Que empiece el baño de sangre!' WHERE `ID`=46993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 천재 포세이큰 과학자, 칼더 그레이가 제게 연락해 엄청난 투사를 제공하겠다는 제안을 했습니다. 지난 모든 용사들의 가장 훌륭한 특징을 말 그대로 "합쳐 놓은" 투사를요! 제가 얼마나 놀랐을지 상상이 가십니까? 칼더의 창조물과 싸워볼 기회를 세상 어느 용사가 거부할 수 있겠습니까?!', `MaleText_loc4`='想象一下，当我遇到那个被遗忘者天才卡尔德·格雷的时候，是多么惊讶。他说，他制造出了一名战士，那名战士拥有以前所有勇士的全部最优秀的能力……真的会有这样的战士！有谁能拒绝向卡尔德的造物挑战的机会？！', `MaleText_loc5`='各位請想像一下，當考德爾·葛雷這位被遺忘者的鬼才主動來找我的時候，當時我有多麼驚訝。而且他還帶來了一位「真的」結合了許多歷屆冠軍勇士精髓的參賽者!誰能夠拒絕得了如此難得的機會，挑戰考德爾的創作?!', `MaleText_loc7`='Imagínense mi sorpresa cuando el genio Renegado, Calder Gray, se puso en contacto conmigo y me propuso un combatiente que reúne las mejores características de nuestros anteriores campeones... ¡LITERALMENTE! ¡¿Quién podría negarse a desafiar la CREACIÓN DE CALDER?!' WHERE `ID`=46994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 말이 있습니다... 꺾지 못할 상대와는 차라리 함께하라고요! 이 자리에서 패배한 도전자는 선택의 여지도 없이 상대와 함께해야 합니다! 아아, 찬란한 대학살의 도가니여!', `MaleText_loc4`='你知道他们所说的……如果不能击败他们，就加入他们！除此之外，你将别无选择！杀戮熔炉，我是如此热爱你。', `MaleText_loc5`='你知道俗話是怎麼說的...打不贏人家，就加入人家!可惜，這回恐怕你沒有這個機會啦!兇殘之爐，我愛你!', `MaleText_loc7`='Ya saben lo que dicen... Si no puedes vencerlos, ¡únete a ellos! ¡En este caso, no hay alternativa! Crisol de Matanza, cuánto te quiero.' WHERE `ID`=46995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리 멀지 않은 그곳, 한때 길니아스라고 불린 짓밟힌 땅에서 우리의 용사가 분연히 일어났습니다! $n|1과;와; 친구들은 단단히 준비해야 할 겁니다. 특히 이번 상대에게 보름달을 보여 주는 건 금기라는 사실을 명심하십시오!', `MaleText_loc4`='从遥远的吉尔尼斯废墟中传出阵阵吼声，我们的勇士来了！把裤子穿好，$n，你不会想让他看到两轮满月吧！', `MaleText_loc5`='來自有點遙遠而且毀得差不多的吉爾尼斯，誕生了我們這位勇士!拉好你的褲頭，$n，千萬別讓這傢伙看到你跟滿月一樣圓的屁股!', `MaleText_loc7`='¡Nuestro siguiente campeón procede del desastre relativamente distante que antes fuera Gilneas! ¡Que no se te caigan los pantalones, $n, no quieres que este tipo vea la luna llena!' WHERE `ID`=46996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 어디서나 여러분 주위에 범죄가 끊이지 않도록 불철주야 노력하는 황혼의 망치단, 오늘도 예외는 아닙니다! 오늘의 마지막 투사는 바로 저 황혼의 요새에서 나온 인물입니다... 뭐, 무슨 상관이겠습니까!', `MaleText_loc4`='暮光之锤：随时随地愿意为实现各种邪恶计划出力，今天也不例外！我们的终极战士向大家致敬！他们来自不远处的暮光堡垒……或者那是暮光城堡……管他呢，谁会在乎这个！', `MaleText_loc5`='暮光之錘:隨時隨地都願意扮演壞人。當然啦，今天也不例外!我們最後一位參戰者就來自不算太遠的暮光城堡!還是暮光堡壘...啊，隨便啦!', `MaleText_loc7`='El Martillo Crepuscular: dispuestos a entregar planes malvados en cualquier sitio, en cualquier momento. ¡Y hoy no es una excepción! ¡Nuestro combatiente final procede del no muy distante Bastión del Crepúsculo! ¿O era El Bastión Crepuscular...? ¡Bah, qué más da!' WHERE `ID`=46997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오! 승부가 났습니다! 승리자가 결정됐어요! 힘찬 박수로 축하해 주십시오!', `MaleText_loc4`='有人赢了——赢了赢了赢了赢了！我们有了一位胜利者！干得漂亮！', `MaleText_loc5`='冠—冠—冠—冠軍!冠軍誕生了!幹得好啊!', `MaleText_loc7`='¡V-V-V-VICTORIA! ¡Tenemos $gun ganador:una ganadora;! ¡Buen trabajo y todo eso!' WHERE `ID`=46998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! 새로운 용사가 대학살의 도가니를 접수했습니다! 어중이떠중이로 이루어진 어설픈 무리에게 거칠고 우람하고 악랄한 우리 투사들이 패배하고 말았어요! 참으로 극적입니다!', `MaleText_loc4`='难以置信！新的杀戮勇士诞生了！！！我们高大的，凶恶的，力大无穷的挑战者被一个衣衫褴褛的无名之辈打败了！真是个不可思议的结局！', `MaleText_loc5`='不敢相信!新的兇殘勇士誕生了!!!我們又大又壞又猛的挑戰者被一群不起眼的無名小卒給打敗了!了不起!', `MaleText_loc7`='¡NO ME LO PUEDO CREER! ¡¡TENEMOS UN NUEVO CAMPEÓN DE MATANZA!! ¡Nuestro campeón grande y robusto ha caído ante una panda de alfeñiques! ¡Un final espectacular!' WHERE `ID`=46999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 아프게 하지 마!', `MaleText_loc4`='不要伤害霍格！', `MaleText_loc5`='不要傷害霍格!', `MaleText_loc7`='¡No hacer daño a Hogger!' WHERE `ID`=47000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 복종한다. 호드를 위하여!', `MaleText_loc4`='我们听命，血卫士。为了部落！', `MaleText_loc5`='我們必須服從命令，血衛士。為了部落!', `MaleText_loc7`='Obedecemos, guardia de sangre. ¡Por la Horda!', `FemaleText_loc1`='우리는 복종한다. 호드를 위하여!', `FemaleText_loc4`='我们听命，血卫士。为了部落！', `FemaleText_loc5`='我們必須服從命令，血衛士。為了部落!', `FemaleText_loc7`='Obedecemos, guardia de sangre. ¡Por la Horda!' WHERE `ID`=47001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 오그리마를 이끌고 파멸의 이교도에 맞서 싸웠다.', `MaleText_loc4`='嗯，$n领导了奥格瑞玛对抗末日教教徒的战斗。', `MaleText_loc5`='士兵們，$n已經率領奧格瑪的部隊在對抗那些末日教徒。', `MaleText_loc7`='Brutos, $n ha encabezado la lucha de Orgrimmar contra los cultores del día del Juicio Final.' WHERE `ID`=47002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이교도의 공격은 아직 끝나지 않았다. 모두에게 경비병의 숫자를 배로 늘리고 수상한 자는 무조건 체포하라고 전하라. 이는 대족장님께서 직접 하신 명령이다.', `MaleText_loc4`='邪教徒并没有停止进攻。将命令传出去：安排两倍的卫兵，逮捕任何有嫌疑的人。这是酋长亲自下达的命令！', `MaleText_loc5`='教徒並沒有放棄攻擊。傳令下去:加強守衛，逮捕任何可疑份子。這是大酋長親自下達的命令!', `MaleText_loc7`='Los cultores no han cesado en sus ataques. Que corra la voz: duplicad la guardia y arrestad a todo sospechoso. ¡Estas órdenes vienen del mismísimo Jefe de Guerra!' WHERE `ID`=47003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 검을 쥐십시오, 여행자여!', `MaleText_loc4`='握紧你的武器，冒险者！', `MaleText_loc5`='冒險者，停手!', `MaleText_loc7`='¡Contén tu acero!' WHERE `ID`=47004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마커스 조나단 장군님이시다!', `MaleText_loc4`='马库斯·乔纳森将军！', `MaleText_loc5`='馬庫斯·喬納森將軍!', `MaleText_loc7`='¡El general Marcus Jonathan!', `FemaleText_loc1`='마커스 조나단 장군님이시다!', `FemaleText_loc4`='马库斯·乔纳森将军！', `FemaleText_loc5`='馬庫斯·喬納森將軍!', `FemaleText_loc7`='¡El general Marcus Jonathan!' WHERE `ID`=47005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와!', `MaleText_loc4`='喔！', `MaleText_loc5`='哇!', `MaleText_loc7`='¡Guau!', `FemaleText_loc1`='우와!', `FemaleText_loc4`='喔！', `FemaleText_loc5`='哇!', `FemaleText_loc7`='¡Guau!' WHERE `ID`=47006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야수는 갈퀴발 놀 무리를 이끌며 엘윈 숲에서 놀의 침략을 종식시키는 데 실마리가 될 것이다.', `MaleText_loc4`='这个怪物是河爪豺狼人的头领，如果要结束豺狼人对艾尔文入侵，也许就要从他下手。', `MaleText_loc5`='這隻畜生是河爪豺狼人的首領，也是終結豺狼人威脅艾爾文森林的關鍵。', `MaleText_loc7`='Esta bestia encabeza la banda de los gnolls Zarparrío y podría ser la clave para acabar con las agresiones de los gnolls en Elwynn.' WHERE `ID`=47007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린 국왕 폐하의 이름으로 들창코를 수감하도록 한다.', `MaleText_loc4`='以国王瓦里安·乌瑞恩的名义，我们将对他予以监管。', `MaleText_loc5`='奉瓦里安·烏瑞恩國王之令，我們要將他逮捕。', `MaleText_loc7`='Lo hemos arrestado en nombre del rey Varian Wrynn.' WHERE `ID`=47008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안드로매스, 우릴 지하감옥으로 이동시켜 주시오.', `MaleText_loc4`='安多玛斯，带我们去监狱。', `MaleText_loc5`='安多瑪斯，帶我們去監獄。', `MaleText_loc7`='Llévanos a las Mazmorras, Andromath.' WHERE `ID`=47009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 그리핀은 부상을 당한 듯합니다. 어쩌면 치유 주문이나 응급치료를 통해 그리핀을 일으킬 수 있을지도 모릅니다.', `MaleText_loc4`='看上去，这头狮鹫受了伤。也许治疗或急救技能可以让它重新站起来。', `MaleText_loc5`='這隻獅鷲獸彷彿受傷了。或許可用醫療術或急救讓牠重新站起來。', `MaleText_loc7`='El grifo parece herido. Quizá la sanación o los primeros auxilios puedan devolverle la salud.' WHERE `ID`=47010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀이 당신의 옷자락에서 익숙한 냄새를 맡은 듯 뚫어지게 당신을 바라봅니다.', `MaleText_loc4`='狮鹫专注地看着你。它显然是从你的衣服上闻到了熟悉的气味。', `MaleText_loc5`='獅鷲獸目不轉睛地看著你，顯然是在你的衣服聞到了熟悉的味道。', `MaleText_loc7`='El grifo te observa atentamente; está claro que percibe un olor familiar en tu ropa.' WHERE `ID`=47011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 그리핀은 덫에 걸렸습니다. 하지만 조금만 도와주면 쉽게 덫을 부수고 움직일 수 있을 듯합니다.', `MaleText_loc4`='这头狮鹫似乎是被困住了。不过看上去，它应该能轻松地挣脱身上的束缚。', `MaleText_loc5`='這隻獅鷲獸似乎是被困住了，但是要破壞牠的枷鎖好像不難。', `MaleText_loc7`='El grifo parece atrapado, pero sus ataduras parecen fáciles de romper.' WHERE `ID`=47012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 힘이 1갭니다!', `MaleText_loc4`='你有1层神圣能量！', `MaleText_loc5`='你獲得1道聖能!', `MaleText_loc7`='¡Tienes 1 Poder Sagrado!' WHERE `ID`=47013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 힘이 2갭니다!', `MaleText_loc4`='你有2层神圣能量！', `MaleText_loc5`='你獲得2道聖能!', `MaleText_loc7`='¡Tienes 2 Poderes Sagrados!' WHERE `ID`=47014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 힘이 3갭니다!', `MaleText_loc4`='你有3层神圣能量！', `MaleText_loc5`='你獲得3道聖能!', `MaleText_loc7`='¡Tienes 3 Poderes Sagrados!' WHERE `ID`=47015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀이 까맣게 탄 고원 자작나무 냄새를 맡게 합니다.', `MaleText_loc4`='让狮鹫嗅一下这块焦黑的高地桦木。', `MaleText_loc5`='讓獅鷲獸聞一聞燒焦的高地樺木。', `MaleText_loc7`='Deja que el grifo huela el abedul de las Tierras Altas carbonizado.', `FemaleText_loc1`='그리핀이 까맣게 탄 고원 자작나무 냄새를 맡게 합니다.', `FemaleText_loc4`='让狮鹫嗅一下这块焦黑的高地桦木。', `FemaleText_loc5`='讓獅鷲獸聞一聞燒焦的高地樺木。', `FemaleText_loc7`='Deja que el grifo huela el abedul de las Tierras Altas carbonizado.' WHERE `ID`=47016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자작나무를 내밀자 그리핀의 몸에 힘이 들어가고 눈이 초롱초롱해집니다.', `MaleText_loc4`='当这片黑暗向狮鹫蔓延过去的时候，狮鹫绷紧了肌肉，眼神也变得犀利明亮。', `MaleText_loc5`='獅鷲獸一聞到樹皮的味道，眼神和肌肉立刻緊繃了起來。', `MaleText_loc7`='Los músculos del grifo se tensan y sus ojos se entrecierran en cuanto le enseñas la corteza.' WHERE `ID`=47017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호오, 집중 공격 이벤트를 통과했군! 난 빠지겠다!
', `MaleText_loc4`='你竟然穿过了那条通道！我暴露了！', `MaleText_loc5`='呦，你通過挑戰了!我要閃了!', `MaleText_loc7`='¡Eh, vete tú por la vereda! ¡Yo me largo!' WHERE `ID`=47018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 고통은 영원하다!', `FemaleText_loc4`='我的痛苦是永恒的！', `FemaleText_loc5`='我的苦痛永無終結!', `FemaleText_loc7`='¡Mi sufrimiento es eterno!' WHERE `ID`=47019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀이 깊은 감사가 담긴 눈길로 당신을 바라봅니다.', `MaleText_loc4`='狮鹫看着你，眼睛里充满了感激之情。', `MaleText_loc5`='獅鷲獸滿心感謝地看著你。', `MaleText_loc7`='El grifo te mira con auténtica gratitud.' WHERE `ID`=47020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이세라의 모습이 당신 앞에서 형상화됩니다.', `FemaleText_loc4`='伊瑟拉的幻象在你面前逐渐变得清晰真实。', `FemaleText_loc5`='一道伊瑟拉的幻象浮現在你的面前。', `FemaleText_loc7`='Una visión de Ysera se materializa ante ti.' WHERE `ID`=47021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 그대는 늑대 고대정령을 풀어 주고, 그의 어두운 그림자를 물리쳤다. 그대의 활약이 이미 꿈속 곳곳을 울리고 있다. 고맙구나. 하지만 아직도 해야 할 일이 더 남았다...', `FemaleText_loc4`='$n，你释放了狼魂先祖，并击败了他的影子。你的行动已经在梦境中产生了反响，谢谢你。但你还有更多的事要去做……', `FemaleText_loc5`='$n，你釋放了狼之先祖並且擊敗了他的暗影。你的英雄之舉已在夢境中產生迴盪。感謝你。但是，還有更多的挑戰...', `FemaleText_loc7`='$n, has liberado al ancestro lobo y derrotado a su sombra. Tus actos ya resuenan por el Sueño... Gracias. Pero aún quedan cosas por hacer...' WHERE `ID`=47022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<눈앞에 나타난 이세라의 환영이 마치 꿈에서처럼 흔들립니다. 주위에 이 환영을 볼 수 있는 자는 없지만, 환영은 당신의 존재를 인지하고 있습니다.>', `FemaleText_loc4`='<伊瑟拉的影像在你的眼前闪动，仿佛一切都是在梦中。再没有其他人看见她在这里。而那幻象显然也感觉到了你的存在。>', `FemaleText_loc5`='<伊瑟拉影像在你眼前浮動擺盪，有如夢中。其他人都沒有看到她出現在這裡，但是這幻象卻感應到了你的存在。>', `FemaleText_loc7`='<La imagen de Ysera parpadea frente a tus ojos, como si fuera un sueño. Nadie más la ve, pero la visión percibe tu presencia.>' WHERE `ID`=47023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덫을 부수자 그리핀이 신이 난 듯 소리를 지릅니다.', `MaleText_loc4`='当你将这头狮鹫解救出来的时候，它发出了欢快的叫声。', `MaleText_loc5`='當你釋放牠自由的時候，獅鷲獸高興地叫了起來。', `MaleText_loc7`='El grifo grita de alegría cuando lo liberas.' WHERE `ID`=47024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르톨라가 우리의 편에 서서 싸우기로 했군. 그대는 현명하다, $n. 거북이 고대정령의 신뢰를 얻기란 정말 어려운 일이지. 그는 우리의 듬직한 친구가 되어 줄 것이다.', `FemaleText_loc4`='托尔托拉已经在为我们而战了。你拥有巨大的智慧，$n。要赢得这位古老神祗的信任是非常困难的。而现在，他将成为我们可以依赖的力量。', `FemaleText_loc5`='托爾托拉已現身與我們一同奮戰。你展現出了不凡的智慧，$n，要贏得先祖的信任並不容易。他將是一位可靠的戰友。', `FemaleText_loc7`='Así que Tortolla se ha alzado para luchar a nuestro lado. Eres $gsabio:sabia;, $n; no es fácil ganarse la confianza del ancestro. Será un aliado inquebrantable.' WHERE `ID`=47025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘의 수호자가 다시 높이 날아올랐구나! 힘이 나는 소식이구나, $n. 하지만 아직도 할 일이 많이 남았다. 이젠 다른 곳으로 주의를 돌려야 하느니라...', `FemaleText_loc4`='天空的守卫者再次展翅翱翔了！这真是令人振奋的消息，$n。但我们还有很多事要做。我们现在必须把注意力转到别的地方……', `FemaleText_loc5`='天空的守護者又再度展翅遨翔!這真是振奮人心的好消息，$n。不過，我們還是有許多的挑戰要克服，必須將注意力轉移到別的地方...', `FemaleText_loc7`='¡La guardiana de los cielos ha alzado el vuelo una vez más! Es una noticia alentadora, $n. Pero queda mucho por hacer, y debemos dirigir nuestra atención a otras partes...' WHERE `ID`=47026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<당신 앞에 꿈과 같은 이세라의 환영이 떠 있습니다. 그녀의 주의는 분산된 상태입니다. 잠시 후, 그녀가 당신을 보며 입을 엽니다.>$B$B오랫동안 아비아나는 내 꿈의 주위를 배회했다. 그녀가 과연 우리에게 돌아올지 확신할 수 없었지. 시간이 지나면서 그녀의 영혼이 혹시 어둡게 물든 건 아닐까 두렵구나...$B$B하지만 지금은 하이잘 산의 운명을 결정할 더 중요한 일들이 우릴 기다리고 있다.', `FemaleText_loc4`='<伊瑟拉的幻象如同梦一般飘落在你面前。一开始，她的心思似乎并不在你身上。过了一会儿，她才注意到你。>$B$B许多年以来，艾维娜一直在我的梦境边缘闪动。我想知道，她会不会回来。但我也害怕她的灵魂因为过去那段岁月而变得黑暗……$B$B不管怎样，如果我们真的要拯救这座山脉，就必须关注一些更紧迫的事情。', `FemaleText_loc5`='<伊瑟拉的影像如夢似幻地浮現在你的面前，然而她彷彿有些分神，過了一會兒之後才開始對你說話。>$B$B許多年來，艾維娜一直在我夢境的邊緣載沈載浮，連我都開始懷疑她是否能回到我們身邊，而且我擔心她的靈魂已隨著時間的流逝而逐漸墮落...$b$b但是，如果要拯救這座山的話，我們還有其他更迫切的危機要處理。', `FemaleText_loc7`='<Una visión onírica de Ysera flota frente a ti; su atención está dividida. Tras un momento, se dirige a ti.>$B$BDurante muchos años, Aviana revoloteó en la periferia de mis sueños. Me preguntaba si alguna vez volvería con nosotros. Temo que su espíritu se haya oscurecido con el paso del tiempo...$B$BPero tenemos problemas más inmediatos si queremos salvar este monte.' WHERE `ID`=47027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 방해하게 둘 것 같으냐! 주인님을 기다리게 해선 안 돼! 또 실패하면 안 돼!', `MaleText_loc4`='不能受到干扰！我们不能让主人久等！决不能再次失败！', `MaleText_loc5`='不能有干擾!不能讓主人等候!不能再失敗!', `MaleText_loc7`='¡No habrá interrupciones! ¡No haré esperar a mi amo! ¡No puedo fallar!' WHERE `ID`=47028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낭비는 금물!', `MaleText_loc4`='一点儿也不浪费……', `MaleText_loc5`='一點都不會浪費...', `MaleText_loc7`='Nada se desperdicia…' WHERE `ID`=47029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살을 모으고, 뼈를 거둔다!', `MaleText_loc4`='剥去皮肉，收割内脏！', `MaleText_loc5`='撕裂肉體，收割內臟!', `MaleText_loc7`='¡Quiten la carne, tomen los órganos!' WHERE `ID`=47030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같은 천재는 다시 없을 거...', `MaleText_loc4`='再也不会有像我这样的……', `MaleText_loc5`='不會再有人像我...', `MaleText_loc7`='Nunca habrá otro como yo...' WHERE `ID`=47031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들은 지능이 낮은 대신 흉포함은 끝내주지!', `MaleText_loc4`='他们在智能方面的缺失能够用暴力来弥补！', `MaleText_loc5`='他們的狂暴可以彌補智力上的不足!', `MaleText_loc7`='¡Compensan la falta de inteligencia con ferocidad!' WHERE `ID`=47032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 내 실패작에도 못 미쳐!', `MaleText_loc4`='我的失败将是你的衰亡！', `MaleText_loc5`='我的失敗品會敲響你們的喪鐘!', `MaleText_loc7`='¡Mis fallas serán tu fin!' WHERE `ID`=47033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 이르지만 할 수 없지... 녀석들을 시험해 봐야겠군! 일급 실험체를 상대해 봐라!', `MaleText_loc4`='为时尚早，但别无选择……必须实验！来面对我的原型实验体吧！', `MaleText_loc5`='雖然太早，但沒選擇...必須測試他們!現在面對我的主要實驗體吧!', `MaleText_loc7`='Demasiado pronto, pero... ¡Deben probarse! ¡Enfrenten mis sujetos primarios!' WHERE `ID`=47034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 두뇌가 주먹으로 승화되었다나 할까! 얘들아, 해치워라!', `MaleText_loc4`='见见我的心血之作！原型实验体，吞噬他们！', `MaleText_loc5`='看看我腦袋所製造的力量!主要實驗體，吃光他們!', `MaleText_loc7`='¡El músculo de mis cerebros! ¡Sujetos primarios: devórenlos!' WHERE `ID`=47035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_POTION_24.BLP:20|t말로리악이 |cFFFF0000붉은색|r 약병을 가마솥 안에 던져넣습니다!', `MaleText_loc4`='|TInterface\\Icons\\INV_POTION_24.BLP:20|t马洛拉克将一只|cFFFF0000红瓶|r扔进了大锅里！', `MaleText_loc5`='|TInterface\\Icons\\INV_POTION_24.BLP:20|t瑪洛里亞克扔了個|cFFFF0000紅色|r瓶子到鍋子裡!', `MaleText_loc7`='|TInterfaceIconsINV_POTION_24.BLP:20|t¡Maloriak lanza un vial |cFFFF0000rojo|r a la caldera!' WHERE `ID`=47036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_POTION_20.BLP:20|t말로리악이 |cFF809FFE푸른색|r 약병을 가마솥 안에 던져넣습니다!', `MaleText_loc4`='|TInterface\\Icons\\INV_POTION_20.BLP:20|t马洛拉克将一只|cFF809FFE蓝瓶|r扔进了大锅里！', `MaleText_loc5`='|TInterface\\Icons\\INV_POTION_20.BLP:20|t瑪洛里亞克扔了個|cFF809FFE藍色|r瓶子到鍋子裡!', `MaleText_loc7`='|TInterfaceIconsINV_POTION_20.BLP:20|t¡Maloriak lanza un vial |cFF809FFEazul|r a la caldera!' WHERE `ID`=47037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_POTION_162.BLP:20|t말로리악이 |cFF33FF00초록색|r 약병을 가마솥 안에 던져넣습니다!', `MaleText_loc4`='|TInterface\\Icons\\INV_POTION_162.BLP:20|t马洛拉克将一只|cFF33FF00绿瓶|r扔进了大锅里！', `MaleText_loc5`='|TInterface\\Icons\\INV_POTION_162.BLP:20|t瑪洛里亞克扔了個|cFF33FF00綠色|r瓶子到鍋子裡!', `MaleText_loc7`='|TInterfaceIconsINV_POTION_162.BLP:20|t¡Maloriak lanza un vial |cFF33FF00verde|r a la caldera!' WHERE `ID`=47038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁한다, 용사들이여. 황혼의 망치단에게서 형제들을 구해다오!', `MaleText_loc4`='勇士们，求求你们，请从暮光之锤的手中救出我的兄弟吧！', `MaleText_loc5`='求求你，英雄，把我弟兄們從暮光之錘那兒救出來!', `MaleText_loc7`='¡Por favor, campeones! ¡Rescatad a mis hermanos del Martillo Crepuscular!' WHERE `ID`=47039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 용혈족을 막아야 한다! 다른 붉은용들도 구해다오. 우리가 너희를 돕겠다!', `MaleText_loc4`='一定要阻止暮光巨龙！请救出其他红龙。我们会帮助你的！', `MaleText_loc5`='務必阻止暮光龍人!救出其他的紅龍軍團，我們就會協助你!', `MaleText_loc7`='¡Hay que detener a los dragonantes Crepusculares! ¡Rescata al resto del Vuelo Rojo y te ayudaremos!' WHERE `ID`=47040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 이들은 이 비밀을 밝히려고 수세기 동안 명상에 빠지기도 했네, 아분. 난 그대에게 같은 운명을 주고 싶지 않네.', `MaleText_loc4`='阿弗恩，有些人花费了数十年的时间思考这个秘密。我并不希望同样的命运会落在你身上。', `MaleText_loc5`='有人花了數十年之久在思考這個謎題。艾弗恩，我並不希望你也落入同樣的下場。', `MaleText_loc7`='Hay quien se ha pasado décadas meditando sobre este misterio, Avuun. No quiero que sufras el mismo destino.' WHERE `ID`=47041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 그 누구의 고통도 원하지 않는다네. 하지만 아무런 저지 없이 우리 세상에 군림하지도 않지.', `MaleText_loc4`='圣光不愿意让任何人受苦，我的孩子。但在我们的国度里，它并不能决定一切。', `MaleText_loc5`='孩子，聖光並不希望任何人遭受苦難。然而祂卻非我們世界裡至高無上的唯一力量。', `MaleText_loc7`='La Luz no le desea sufrimiento a nadie, hijo mío. Pero no es la única fuerza de nuestro reino.' WHERE `ID`=47042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간에도, 빛과 어둠의 싸움이 점점 더 다가오고 있네. 이 싸움에는 우리 모두 휘말릴 것이며, 필멸자들의 고통은 이 분쟁 앞에선 모두 의미 없는 일이 될 것이야.', `MaleText_loc4`='现在，光明与黑暗之间的决战即将爆发。我们全都会受到召唤，参加这场大战。与它相比，所有凡间的痛苦都将变得毫无意义。', `MaleText_loc5`='即便就在此刻，光明與黑暗的最終對決也正逐漸逼近。我們沒有人能夠身在事外，而且在這場衝突之中，所有的凡間疾苦都將失去意義。', `MaleText_loc7`='La verdadera batalla entre las fuerzas de la Luz y la Oscuridad se acerca. Todos recibiremos la llamada para unirnos, y frente a este conflicto todo el sufrimiento mortal carecerá de significado.' WHERE `ID`=47043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막투르, 자네는 역경을 용감하게 잘 견뎌냈네. 빛의 품으로 돌아갈 준비가 되었는가?', `MaleText_loc4`='玛格图尔，你已经勇敢地接受了你的挑战。现在，你准备好回归圣光的怀抱了吗？', `MaleText_loc5`='瑪格圖爾，你勇敢地承受了所有的苦難折磨。你已經準備好要回歸聖光的懷抱了嗎?', `MaleText_loc7`='Magtoor, has soportado tu carga con valentía. ¿Estás listo para volver al amparo de la Luz?' WHERE `ID`=47044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 빛이 자네를 구원하고 감싸 줄 걸세.', `MaleText_loc4`='那么，愿圣光拯救你，激励你。', `MaleText_loc5`='那麼，願聖光拯救你，令你再起。', `MaleText_loc7`='Entonces, que la Luz te guíe y te eleve.' WHERE `ID`=47045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 말게, 아분. 방황하는 자가 모두 길을 잃은 것은 아니네.', `MaleText_loc4`='记住，阿弗恩，并非所有徘徊者都是迷失之人。', `MaleText_loc5`='切記，艾弗恩，並非所有迷途者都已失去。', `MaleText_loc7`='Recuerda, Avuun. No todo el que deambula está perdido.' WHERE `ID`=47046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지도 전혀 반응이 없군, 어째서지? 왜 빛은 무고한 자를 저버리는 거지?', `MaleText_loc4`='现在我仍是一无所获。为什么？为什么圣光会抛弃无辜者？', `MaleText_loc5`='到現在，還是一點效用都沒有。為什麼?聖光為何要遺棄無辜的人?', `MaleText_loc7`='Nada, ni siquiera ahora. ¿Por qué? ¿Por qué abandona la Luz a los inocentes?' WHERE `ID`=47047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언자 벨렌 님!', `MaleText_loc4`='先知维伦！', `MaleText_loc5`='預言者費倫!', `MaleText_loc7`='¡Profeta Velen!' WHERE `ID`=47048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...고맙습니다, 예언자 님. 우리 둘에게 큰 편안함을 안겨 주셨습니다. 전 막투르에 대한 믿음과 기억을 안은 채, 연구를 계속하겠습니다.', `MaleText_loc4`='……谢谢你，先知。你已经让我们得到了巨大的安慰。我会继续我的工作，这也是我对玛格图尔的纪念。', `MaleText_loc5`='...謝謝你，預言者。你給了我們極大的撫慰。我將繼續努力不懈，以紀念瑪格圖爾。', `MaleText_loc7`='...Gracias, Profeta. Nos has dado un gran consuelo a los dos. Continuaré mi trabajo, con fe y en memoria de Magtoor.' WHERE `ID`=47049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라! 이것 좀 봐요! 눈이 날고 있어요!', `MaleText_loc4`='嗨，看啊！它在飞！', `MaleText_loc5`='嘿，你看!它在飛耶!', `MaleText_loc7`='¡Mira! ¡Vuela!' WHERE `ID`=47050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예...', `MaleText_loc4`='是的……', `MaleText_loc5`='是的...', `MaleText_loc7`='Sí...' WHERE `ID`=47051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 정말 멋지지 않나요?$b$b좀 덥긴 하지만, 그래도 습하진 않아서 좋아요...', `FemaleText_loc4`='这里真不错。你不这样认为吗？$b$b也许是有一点热，但只是干热而已……', `FemaleText_loc5`='這裡真不賴，你不覺得嗎?$b$b雖然有點熱，但好歹是乾爽的熱...', `FemaleText_loc7`='Qué bien se está aquí, ¿verdad?$b$bIgual hace un poco de calor, pero es calor seco...' WHERE `ID`=47052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버지는 항상 덩치가 큰 녀석들은 힘이 좋지만 움직임이 둔하다고 말씀하셨소...$b$b아마 이 녀석은 만나보지 못한 게 분명하오!', `MaleText_loc4`='爸爸总是对我说，大家伙力气大，但速度慢……$b$b我相信爸爸一定没有见过这个家伙！', `MaleText_loc5`='爸爸經常跟我說，塊頭大的傢伙雖然力氣大，但是動作卻很遲鈍...$b$b我敢說我老爸一定沒見過這傢伙!', `MaleText_loc7`='Papá siempre me decía que los tipos grandes pegan fuerte pero se mueven despacio...$b$b¡Me da que papá no conocía a este tipo!' WHERE `ID`=47053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광기. 혼돈. 티탄의 작품이 박살나는 모습을 보고 싶다. 그러려면 주인님께서 돌아오실 때까지 살아 있어야겠지. 내 너를 돕겠다.', `MaleText_loc4`='疯狂。混乱。看到泰坦的作品没有完成时，我全身战栗。现在我只希望当主人回来的时候，自己还能活着。好了，我会帮助你的。', `MaleText_loc5`='瘋狂。混沌。雖然我樂見泰坦的心血俱化為流水，我仍希望在主人回歸之時自己依然健在。好吧，我幫你。', `MaleText_loc7`='Locura. Caos. Por mucho que me entusiasme ver la destrucción de la obra de los titanes, deseo seguir con vida cuando regrese el maestro. Te ayudaré.' WHERE `ID`=47054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<저 멀리 지옥불 쪽을 쳐다보다, 당신에게 다시 고개를 돌리는 블랙혼>', `MaleText_loc4`='<黑角望向地狱的远方，然后又将注意力转回到你身上。>', `MaleText_loc5`='<黑角望向遠處的火焰煉獄，然後才將注意力轉回你的身上。>', `MaleText_loc7`='<Cuerno Negro mira hacia el lejano infierno y luego centra su atención de nuevo en ti.>' WHERE `ID`=47055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 원한 건 조용하고 평화로운 삶뿐이었다!', `MaleText_loc4`='我只想得到一点平静与安宁！', `MaleText_loc5`='我要的只是一點安詳和寧靜而已!', `MaleText_loc7`='¡Solo quería un poco de paz y tranquilidad!' WHERE `ID`=47056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 필멸자들 같으니! 비전 마력을 네놈들의 지식수준으로 이해할 수 있을 것 같으냐! 마법을 조롱하는 그 행위에 종지부를 찍어주지!', `MaleText_loc4`='愚蠢的凡人！你根本无法理解自己正在玩弄怎样的奥术力量！而我将结束这出魔法的闹剧！', `MaleText_loc5`='愚蠢的凡人!你玩弄的可是超乎你理解能力之外的秘法能量!我要終結你這種嘲弄魔法的行為!', `MaleText_loc7`='¡Necios mortales! ¡Juegan con poderes arcanos que superan su comprensión! ¡Pondré fin a esta deshonra de la magia!' WHERE `ID`=47057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 이 어두운 곳에서 그대들은 혼자가 아닙니다!', `MaleText_loc4`='英雄们，你们并非在这黑暗之地孤军奋战！', `MaleText_loc5`='英雄們，你們在這黑暗之地並不孤獨的!', `MaleText_loc7`='¡Héroes, no están solos en esta oscuridad!' WHERE `ID`=47058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신타리아, 네 주인은 내게 큰 빚을 졌다. 오늘, 네 가죽으로 그 빚을 받겠다!', `MaleText_loc4`='辛萨尼亚！你的主人欠我一笔巨债——我要好好在你的身上讨回来！', `MaleText_loc5`='席恩瑟拉，你的主人欠我的可多了!我打算讓他用他配偶的皮來抵債!', `MaleText_loc7`='¡Sintaria! Tu Amo me debe mucho... ¡y pienso cobrármelo con la piel de su consorte!' WHERE `ID`=47059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 더러운 잡견들 때문에 펜리스 요새에서도 쫓겨났는데, 내 야영지에서도 쫓겨나지는 못한다!', `MaleText_loc4`='那些肮脏的笨蛋强迫我离开了芬里斯城堡，我绝不会再被赶出我的营地！', `MaleText_loc5`='那些該死的狗雜種把我趕出了芬里斯城堡，但是我可不會再從我的營地被趕出去了!', `MaleText_loc7`='Esos chuchos inmundos me echaron del Castillo de Fenris. ¡No me echarán también de mi campamento!' WHERE `ID`=47060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여왕에게 경의를 표하라!', `FemaleText_loc4`='向女王致敬！', `FemaleText_loc5`='為女王歡呼!', `FemaleText_loc7`='¡Alabada sea la reina!' WHERE `ID`=47061;
