UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연한 결과다!', `MaleText_loc4`='这是必然结果。', `MaleText_loc5`='這是無發避免的!', `MaleText_loc7`='¡Fue inevitable!' WHERE `ID`=47063;
