UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라! 다시 덤벼 보란 말이다!', `MaleText_loc4`='站起来！你敢吗？', `MaleText_loc5`='爬起來啊!你敢嗎!', `MaleText_loc7`='¡Vuelve a levantarte! ¡Te desafío!' WHERE `ID`=47066;
