UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너에게 어느 정도 믿음을 보일 것이야.', `MaleText_loc4`='他们会对你保持一定程度的信任。', `MaleText_loc5`='他們在某種程度上將會信任你。', `MaleText_loc7`='Deben de confiar un poco más en ti.' WHERE `ID`=47069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최소한 네가 시험을 받을 수 있는 정도는 말이다.', `MaleText_loc4`='这至少能让你得到证明自己的机会。', `MaleText_loc5`='至少足夠給你機會證明自己。', `MaleText_loc7`='Al menos como para que pruebes tu valía.' WHERE `ID`=47070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 용사는 자신의 목적과 능력을 증명했습니다.', `MaleText_loc4`='这位勇士已经证明了自己的决心和能力。', `MaleText_loc5`='這個勇士證明了自己的能力和決心。', `MaleText_loc7`='Este campeón demostró ser atento y capaz.' WHERE `ID`=47071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 그들을 믿지 못할 이유가 없습니다.', `MaleText_loc4`='我认为，我们没有理由不信任它。', `MaleText_loc5`='我沒有理由不相信他。', `MaleText_loc7`='No veo por qué negarle confianza.' WHERE `ID`=47072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 잘 띄지 않는 대리석 석판입니다.', `MaleText_loc4`='一块不显眼的大理石板。', `MaleText_loc5`='一塊毫不起眼的大理石板。', `MaleText_loc7`='Una losa de mármol normal y corriente.' WHERE `ID`=47073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상을 석판에 올려놓습니다.', `MaleText_loc4`='将雕像放在这块石板上。', `MaleText_loc5`='把雕像放在石板上。', `MaleText_loc7`='Coloca la estatua en la losa.', `FemaleText_loc1`='조각상을 석판에 올려놓습니다.', `FemaleText_loc4`='将雕像放在这块石板上。', `FemaleText_loc5`='把雕像放在石板上。', `FemaleText_loc7`='Coloca la estatua en la losa.' WHERE `ID`=47074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 잘 띄지 않는 석판입니다.', `MaleText_loc4`='一块不显眼的石板。', `MaleText_loc5`='一塊毫不起眼的石板。', `MaleText_loc7`='Una losa de piedra normal y corriente.' WHERE `ID`=47075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리우스가 쓰러졌습니다!', `MaleText_loc4`='塞纳留斯死了！', `MaleText_loc5`='塞納留斯被擊敗了!', `MaleText_loc7`='¡Cenarius ha caído!' WHERE `ID`=47076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 거대한 고대정령은 아직 조심스럽긴 하지만, 당신을 동료로 여기고 말을 합니다.>', `MaleText_loc4`='<这位巨大的远古半神仍然对你保持着警惕，但他已经像对待盟友一样和你说话了。>', `MaleText_loc5`='<體型碩大的先祖雖然對你依舊有所保留，但講話時還是把你當作盟友看待。>', `MaleText_loc7`='<El gigantesco ancestro recela de ti, pero te habla como a un aliado.>' WHERE `ID`=47077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단으로 돌아가서 전투에 참가하십시오!', `MaleText_loc4`='回去参加战斗！', `MaleText_loc5`='快給我上來，加入戰鬥!', `MaleText_loc7`='¡Sube ahí y vuelve al combate!', `FemaleText_loc1`='제단으로 돌아가서 전투에 참가하십시오!', `FemaleText_loc4`='回去参加战斗！', `FemaleText_loc5`='回上面那邊，加入戰鬥!', `FemaleText_loc7`='¡Sube ahí y vuelve al combate!' WHERE `ID`=47078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 온 바다를 정복할 것이다. 그러고 나서, 우리는 바다를 넘어 나아가리라.', `FemaleText_loc4`='海洋将完全属于我们，远大征程才刚刚开始。', `FemaleText_loc5`='整個海洋將屬於我們，然後我們會征服更多地方。', `FemaleText_loc7`='Todos los océanos serán nuestros y entonces iremos por más.' WHERE `ID`=47079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 스토나드에 도착하자마자 헬그럼을 제자로 삼았죠. 저의 매몰찬 교육 아래, 그는 전보다 더 뛰어난 추적자이자 제 하나뿐인 동반자가 되었어요.$B$B전 제가 강하다고 생각했어요. 그 무엇도 제 의지를 부술 순 없다고 믿었죠. 하지만 인간이 헬그럼... 제 짝에게 칼날을 박아 넣는 모습을 보았을 때... 제가 얼마나 잘못된 생각을 하고 있었는지 깨달았어요.', `FemaleText_loc4`='当我到达斯通纳德的时候，我还带着赫格拉姆。在我严厉的教导下，他成为了一名比以前更优秀的追踪者……也是我唯一的同伴。$B$B我以为自己很强。我以为任何痛苦都不可能让我的灵魂倒下。但是，当我看到那些人类的刀剑刺穿赫格拉姆，杀死了我的同伴……我发现自己彻底错了。', `FemaleText_loc5`='抵達斯通納德之後，我便將赫格拉姆收入門下。在我嚴厲的鍛鍊之下，他變成了一位比以往更加傑出的斥候...同時也是我唯一的夥伴。$B$B我原本以為自己已經夠堅強，不會再受到任何苦難折磨的打擊。可是當我見到人類的利刃刺入赫格拉姆... 刺入我的夥伴的時候...我才發現自己錯得有多麼離譜。', `FemaleText_loc7`='Acogí a Helgrum bajo mi protección cuando llegué a Rocal. Bajo mi severa mirada se convirtió en un rastreador mejor de lo que era antes... y en mi único compañero.$b$bMe creía fuerte. Pensaba que ningún sufrimiento podría quebrar mi espíritu. Cuando vi a los humanos clavar sus espadas en Helgrum... en mi compañero... Descubrí lo equivocada que estaba.' WHERE `ID`=47080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라갈 나무를 찾으십시오.', `MaleText_loc4`='找到一棵树去爬。', `MaleText_loc5`='找一顆樹爬', `MaleText_loc7`='Encuentra un árbol al que subirte' WHERE `ID`=47081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 곰을 잡으십시오.', `MaleText_loc4`='抓住一只熊崽。', `MaleText_loc5`='抓一隻幼熊', `MaleText_loc7`='Agarra un cachorro de oso' WHERE `ID`=47082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무 꼭대기로 올라가십시오.', `MaleText_loc4`='爬到树顶。', `MaleText_loc5`='爬到樹頂', `MaleText_loc7`='Sube hasta la copa del árbol' WHERE `ID`=47083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 곰을 던지십시오!', `MaleText_loc4`='抛下熊崽！', `MaleText_loc5`='把幼熊扔下去!', `MaleText_loc7`='¡Lanza el cachorro de oso!' WHERE `ID`=47084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 람카헨의 왕자 나둔이오. 네페르세트 부족은 나머지 톨비르 부족을 배신했소.$B$B내가 탈출할 수 있게 도와주시오. 람카헨의 국왕인 내 형을 설득하여 이 배신자들과 전쟁을 치러야 하오!', `MaleText_loc4`='我是拉穆卡恒的纳顿亲王。尼斐塞特部族已经公然与其他托维尔为敌。$B$B请帮我逃出这里，这样我就能说服我的兄弟，也就是我们的国王向这些叛徒发动战争！', `MaleText_loc5`='我是蘭姆卡韓的納登親王。奈斐賽特部族已經背叛了其他的托維爾人。$B$B協助我逃離這裡，這樣我才能夠勸說我的兄弟，也就是我們的國王，對這些叛徒開戰!', `MaleText_loc7`='Soy el príncipe Nadun de Ramkahen. La tribu Neferset se ha rebelado contra los demás Tol''vir.$b$b¡Ayúdame a escapar para que pueda presionar a mi hermano, el rey, para que les declare la guerra a estos traidores!' WHERE `ID`=47085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 람카헨의 왕자 나둔이오. 우리 일족은 톨비르... 아니, 정확히 말하자면 톨비르의 후예라오.$B$B네페르세트 사람들도 육신과 피로 이루어진 우리와 마찬가지 사람이었지만...$B$B데스윙과 함께 모든 게 달라졌소.', `MaleText_loc4`='我是拉穆卡恒的纳顿亲王。我的人民来自于托维尔……或者严格来说，是托维尔人的后代。$B$B尼斐塞特人本来也像我们一样有血有肉……$B$B但在死亡之翼到来之后，一切都改变了。', `MaleText_loc5`='我是納登親王。我們蘭姆卡韓是托維爾... 或者該說，是托維爾的後裔才對。$B$B奈斐賽特原本也跟我們一樣是血肉之軀...$b$b直到死亡之翼現身。', `MaleText_loc7`='Soy el Príncipe Nadun de Ramkahen. Mi gente son Tol''vir... o desciende de los Tol''vir, para ser exactos.$b$bLa gente de Neferset era como nosotros, de carne y hueso...$b$bHasta que llegó Alamuerte.' WHERE `ID`=47086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 우리가 과거의 영광을 되찾을 기회를 줬소. 다시 진정한 톨비르가 될 수 있는 기회를...$B$B하지만... 우리가 그에게 충성을 맹세해야 한다는 조건이 있었소.', `MaleText_loc4`='他承诺会让我们恢复往日的光荣……再次成为真正的托维尔人。$B$B但条件是……我们必须发誓向他效忠。', `MaleText_loc5`='他提供了我們全體一個回復往日榮光的機會...再度成為真正的托維爾。$B$B但條件是...我們必須向他宣誓效忠。', `MaleText_loc7`='Nos ofreció a todos la oportunidad de recuperar nuestra antigua gloria... de volver a ser verdaderos Tol''vir.$b$bPero solo si le jurábamos lealtad.' WHERE `ID`=47087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 울둠의 비밀을 지키는 수호자요. 모래 밑... 피라미드 아래에는 위대한 힘이 잠들어 있소.$B$B새로운 세계를 창조하고 이 모든 세상을 파괴할 수 있는 힘이오.$B$B하지만 우리가 도와주지 않는다면 그도 이 힘을 손에 넣을 수는 없소.', `MaleText_loc4`='我们是了奥丹姆秘密的守护者。在无尽的沙海中……在巍峨的金字塔下……那里埋藏着无比强大的力量。$B$B那是足以形成和破坏整个世界的力量。$B$B但如果没有我们，他就无法使用这种力量。', `MaleText_loc5`='我們是捍衛奧丹姆秘密的守衛者。在這滾滾黃沙之下...在金字塔群之下...藏著極為強大的力量。$B$B足以毀滅一整個世界的力量。$B$B但是，少了我們的協助，他就無法取得這股力量。', `MaleText_loc7`='Somos los guardianes de los secretos de Uldum. Bajo la arena... bajo las pirámides... existe un gran poder.$b$bEl poder para crear y destruir todo un mundo.$b$bPero no puede acceder a este poder sin nosotros.' WHERE `ID`=47088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 데스윙은 한 부족을 손에 넣었소. 바로 네페르세트요.$B$B오르시스는 명백히 저항했소.$B$B람카헨은 평화적인 해결책을 찾아보려 했지만, 데스윙과 그 일당의 편에 서지 않은 사람에게 평화란 있을 수 없소.', `MaleText_loc4`='他已经让尼斐塞特部族成为了他的奴仆。$B$B奥西斯明确地摆出了挑战的姿态。$B$B拉穆卡恒竭力想找到一个和平解决的方法，但对于死亡之翼和他的盟军，和平是绝不存在的。', `MaleText_loc5`='如今他已成功吸收了奈斐賽特族的人。$B$B奧爾希斯已清楚表明了對抗的立場。$B$B我們蘭姆卡韓試著想找出和平的解決之道，但是要跟死亡之翼與他的黨羽和談根本是不可能的。', `MaleText_loc7`='Tiene a una de las tribus de su lado, los Neferset.$b$bOrsis ha dejado patente su rebeldía.$b$bLos Ramkahen han intentado encontrar una solución pacífica, pero la paz con Alamuerte y sus aliados es imposible.' WHERE `ID`=47089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 풀어주시오.$B$B날 풀어주면 우리 백성을 모아 데스윙에 저항하겠소.$B$B그걸로는 충분하지 않다면, 날 풀어주는 대가로 당신에게 막대한 부를 안겨주겠소. 이래 봬도 나는 람카헨의 왕자니까 말이오.', `MaleText_loc4`='把我解救出来。$B$B这样我们就能召集我的人民，共同对抗死亡之翼。$B$B如果你觉得这还不够，我还会给你丰厚的酬劳。毕竟，我是一位亲王。', `MaleText_loc5`='釋放我。$B$B釋放我，讓我們去說服我的族人們一同挺身對抗死亡之翼。$B$B若是這樣的理由還不夠的話，你也將獲得豐厚的財寶。畢竟，我還是一位王子。', `MaleText_loc7`='Libérame.$b$bLibérame para que juntos podamos reunir a mi gente contra Alamuerte.$b$bSi eso no es razón suficiente, te recompensaré con grandes riquezas. Soy un príncipe, al fin y al cabo.' WHERE `ID`=47090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구십니까?', `MaleText_loc4`='你是谁？', `MaleText_loc5`='你是誰?', `MaleText_loc7`='¿Quién eres?', `FemaleText_loc1`='누구신가요?', `FemaleText_loc4`='你是谁？', `FemaleText_loc5`='你是誰?', `FemaleText_loc7`='¿Quién eres?' WHERE `ID`=47091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 여기까지 왔는데도 당신을 해치지 않았다는 말씀이십니까?', `MaleText_loc4`='死亡之翼来到了这里，却没有把你们都杀光？', `MaleText_loc5`='死亡之翼有來過這裡，而且沒有把你們全部殺光?', `MaleText_loc7`='¿Alamuerte vino aquí y no os mató a todos?', `FemaleText_loc1`='데스윙이 여기까지 왔는데도 당신을 해치지 않았다고요?', `FemaleText_loc4`='死亡之翼来到了这里，却没有把你们都杀光？', `FemaleText_loc5`='死亡之翼有來過這裡，而且沒有把你們全部殺光?', `FemaleText_loc7`='¿Alamuerte vino aquí y no os mató a todos?' WHERE `ID`=47092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙에게 왜 당신이 필요합니까?', `MaleText_loc4`='为什么他会需要你们？', `MaleText_loc5`='他要你幫他做什麼?', `MaleText_loc7`='¿Por qué os necesita?', `FemaleText_loc1`='데스윙에게 왜 당신이 필요하지요?', `FemaleText_loc4`='为什么他会需要你？', `FemaleText_loc5`='他要你幫他做什麼?', `FemaleText_loc7`='¿Por qué os necesita?' WHERE `ID`=47093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 당신의 일족 모두가 데스윙과 동맹을 맺은 건 아닙니까?', `MaleText_loc4`='这样说来，你们并没有全都与他结盟？', `MaleText_loc5`='所以，並不是全部的人都已經向他效忠?', `MaleText_loc7`='¿Así que no toda tu gente se ha aliado con él?', `FemaleText_loc1`='그렇다면 당신의 일족 모두가 데스윙과 동맹을 맺은 건 아닌가요?', `FemaleText_loc4`='这样说来，你们并没有全都与他结盟？', `FemaleText_loc5`='所以，並不是全部的人都已經向他效忠?', `FemaleText_loc7`='¿Así que no toda tu gente se ha aliado con él?' WHERE `ID`=47094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 제가 어떻게 도와드리면 되겠습니까?', `MaleText_loc4`='同意。那么你想让我干什么？', `MaleText_loc5`='同意。那麼你現在要我做什麼?', `MaleText_loc7`='Estoy de acuerdo. ¿Qué quieres de mí?', `FemaleText_loc1`='알겠어요. 제가 어떻게 도와드리면 될까요?', `FemaleText_loc4`='同意。那么你想让我干什么？', `FemaleText_loc5`='同意。那麼你現在要我做什麼?', `FemaleText_loc7`='Estoy de acuerdo. ¿Qué quieres de mí?' WHERE `ID`=47095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서! 비행기를 타시오!', `MaleText_loc4`='赶快！到飞机里面去！', `MaleText_loc5`='快!快上飛機!', `MaleText_loc7`='¡Rápido! ¡Al avión!' WHERE `ID`=47096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 용봉탕 잔치를 준비합니다!', `MaleText_loc4`='$n准备了一场烤全龙盛宴！', `MaleText_loc5`='$n準備了一餐炙烤龍肉盛宴!', `MaleText_loc7`='¡$n prepara un festín de dragón a la parrilla!', `FemaleText_loc1`='$n|1이;가; 용봉탕 잔치를 준비합니다!', `FemaleText_loc4`='$n准备了一场烤全龙盛宴！', `FemaleText_loc5`='$n準備了一餐炙烤龍肉盛宴!', `FemaleText_loc7`='¡$n prepara un festín de dragón a la parrilla!' WHERE `ID`=47097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 해산물 대잔치를 준비합니다!', `MaleText_loc4`='$n准备了一场海鲜盛宴！', `MaleText_loc5`='$n準備了一餐海鮮珍饈盛宴!', `MaleText_loc7`='¡$n prepara un festín de marisco magnífico!', `FemaleText_loc1`='$n|1이;가; 해산물 대잔치를 준비합니다!', `FemaleText_loc4`='$n准备了一场海鲜盛宴！', `FemaleText_loc5`='$n準備了一餐海鮮珍饈盛宴!', `FemaleText_loc7`='¡$n prepara un festín de marisco magnífico!' WHERE `ID`=47098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애처롭군.', `MaleText_loc4`='可怜。', `MaleText_loc5`='可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=47099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 전진해라. 내 부하들이 이 딱한 뼈다귀 자루를 처리할 것이다.', `MaleText_loc4`='继续前进。我的部下会处理这只悲惨的尸骨袋。', `MaleText_loc5`='繼續前進。我的手下會解決掉這個沒用的東西。', `MaleText_loc7`='Sigue adelante. Mis hombres se desharán de esta patética bolsa de huesos.' WHERE `ID`=47100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은송곳니 광전사들이 마구 군침을 흘리기 시작합니다.', `MaleText_loc4`='血牙狂战士们开始大流口水。', `MaleText_loc5`='血牙狂戰士開始流出大量的唾液。', `MaleText_loc7`='Los rabiosos Colmillo de Sangre empiezan a salivar copiosamente.' WHERE `ID`=47101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자제해라! 고드프리를 처치하는 것이 우리의 가장 중요한 임무이다. 전리품을 즐기는 건 나중으로 미뤄라!', `MaleText_loc4`='控制住你们自己！我们在这里唯一的目标是高弗雷的脑袋！其它战利品以后再拿！', `MaleText_loc5`='克制一點!我們是為了高佛雷的人頭而來的，晚點再來分贓!', `MaleText_loc7`='¡Controlaos! Hemos venido a por la cabeza de Godfrey por encima de todo. ¡Disfrutaréis del botín de guerra más tarde!' WHERE `ID`=47102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 끝장내려면 계속 밀고 나가야 한다. 따라와라. 내가 안마당 문을 열 테니 우리의 공격을 선두에서 지휘하라.', `MaleText_loc4`='如果我们要干掉他，就必须全力向前推进。跟着我，我会打开院子的大门，让你们可以展开全面突击。', `MaleText_loc5`='我們得繼續推進才能夠終結他的存在。跟我來，我會打開中庭，讓你可以率領我們的突擊。', `MaleText_loc7`='Tenemos que seguir adelante si queremos acabar con él. Sígueme, abriré el patio para que puedas encabezar el asalto.' WHERE `ID`=47103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치해! 당장! 어서 가!', `MaleText_loc4`='冲啊！上啊！冲冲冲！', `MaleText_loc5`='逮住他們!!快點!上、上、上!', `MaleText_loc7`='¡¡Atrápenlos!! ¡Ahora! ¡Venga, venga, venga!' WHERE `ID`=47104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신께 모든 생산 및 채집 기술의 기초에 대해 알려 드릴 수 있습니다. 딱 기초만 말이죠.

그 이상을 배우고 싶다면 해당 기술에 전념하는 전문가를 찾아가야 합니다.

누구나 2개의 전문 기술을 배울 수 있습니다. 생산 기술만 2개, 채집 기술만 2개, 아니면 각각 1개씩 배울 수도 있습니다.

고고학, 요리, 응급치료, 낚시 등의 보조 기술에는 제한이 없어서 원하는 만큼 많은 보조 기술을 배울 수 있습니다.', `MaleText_loc4`='我可以教导你任何最基础的采集和生产技能，仅此而已。

如果你要学习初级以上的技能，你就需要去访问专门掌握某一个技能的大师。

你最多可以学习两个主要专业技能：两个采集技能；或者两个生产技能；或者是采集、生产技能各一个。

考古学、烹饪、急救和钓鱼是辅助技能，不会占用你的主要专业技能的学习位置。你可以学习全部辅助技能。', `MaleText_loc5`='我可以傳授你任何採集類與生產類專業技能的基礎技能，但也僅此而已。

若是想學習比「初級技能」更深入的內容，你就得去尋訪各個不同技能的專業訓練師。

每個人最多只能學習二種專業技能，其組合可以是兩種採集類技能，兩種生產類技能，或是各學一類。

至於考古學、烹飪、急救，以及釣魚則屬於「次要技能」，並不算在二個專業技能的數量限制之內，你想全部都學起來也可以。', `MaleText_loc7`='Te puedo enseñar lo más básico de cualquier profesión de recolección o producción, pero eso es todo.

Si quieres aprender habilidades más allá del nivel de aprendiz, tendrás que ir a ver a un especialista dedicado a una única profesión.

Puedes aprender hasta dos profesiones: dos de recolección, dos de producción, o una de cada.

Las habilidades secundarias como arqueología, cocina, primeros auxilios y pesca no cuentan para estas dos profesiones; puedes aprender tantas profesiones secundarias como quieras.', `FemaleText_loc1`='저는 당신께 모든 생산 및 채집 기술의 기초에 대해 알려 드릴 수 있습니다. 딱 기초만 말이죠.

그 이상을 배우고 싶다면 해당 기술에 전념하는 전문가를 찾아가야 합니다.

누구나 2개의 전문 기술을 배울 수 있습니다. 생산 기술만 2개, 채집 기술만 2개, 아니면 각각 1개씩 배울 수도 있습니다.

고고학, 요리, 응급치료, 낚시 등의 보조 기술에는 제한이 없어서 원하는 만큼 많은 보조 기술을 배울 수 있습니다.', `FemaleText_loc4`='我可以教导你任何最基础的采集和生产技能，仅此而已。

如果你要学习初级以上的技能，你就需要去访问专门掌握某一个技能的大师。

你最多可以学习两个主要专业技能：两个采集技能；或者两个生产技能；或者是采集、生产技能各一个。

考古学、烹饪、急救和钓鱼是辅助技能，不会占用你的主要专业技能的学习位置。你可以学习全部辅助技能。', `FemaleText_loc5`='我可以傳授你任何採集類與生產類專業技能的基礎技能，但也僅此而已。

若是想學習比「初級技能」更深入的內容，你就得去尋訪各個不同技能的專業訓練師。

每個人最多只能學習二種專業技能，其組合可以是兩種採集類技能，兩種生產類技能，或是各學一類。

至於考古學、烹飪、急救，以及釣魚則屬於「次要技能」，並不算在二個專業技能的數量限制之內，你想全部都學起來也可以。', `FemaleText_loc7`='Te puedo enseñar lo más básico de cualquier profesión de recolección o producción, pero eso es todo.

Si quieres aprender habilidades más allá del nivel de aprendiz, tendrás que ir a ver a un especialista dedicado a una única profesión.

Puedes aprender hasta dos profesiones: dos de recolección, dos de producción, o una de cada.

Las habilidades secundarias como arqueología, cocina, primeros auxilios y pesca no cuentan para estas dos profesiones; puedes aprender tantas profesiones secundarias como quieras.' WHERE `ID`=47105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채집 기술에 대해 알려 주십시오.', `MaleText_loc4`='和我说说采集技能。', `MaleText_loc5`='請為我介紹採集類技能。', `MaleText_loc7`='Háblame de las profesiones de recolección.', `FemaleText_loc1`='채집 기술에 대해 알려 주세요.', `FemaleText_loc4`='和我说说采集技能。', `FemaleText_loc5`='請為我介紹採集類技能。', `FemaleText_loc7`='Háblame de las profesiones de recolección.' WHERE `ID`=47106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생산 기술에 대해 알려 주십시오.', `MaleText_loc4`='和我说说生产技能。', `MaleText_loc5`='請為我介紹生產類技能。', `MaleText_loc7`='Háblame de las profesiones de producción.', `FemaleText_loc1`='생산 기술에 대해 알려 주세요.', `FemaleText_loc4`='和我说说生产技能。', `FemaleText_loc5`='請為我介紹生產類技能。', `FemaleText_loc7`='Háblame de las profesiones de producción.' WHERE `ID`=47107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채집 기술을 배우면 약초, 광물, 보석을 캐내고 짐승의 가죽을 벗기는 등의 작업 등을 통해 생산 기술에 필요한 원료를 직접 구할 수 있습니다.

채집한 원료는 관련된 생산 기술 작업에 직접 사용하거나 그냥 경매장에 등록해서 팔 수도 있습니다.', `MaleText_loc4`='采集技能让你能够获得生产技能所需的原始材料：采集草药；开采矿石、石料和宝石；或者从野兽的尸体上剥去皮革。

你可以用自己采集来的原料支持你的生产技能需求，或者是在拍卖行中出售你采集来的原料。', `MaleText_loc5`='採集類技能可助你取得生產類專業技能所需的原料，包括採集藥草，挖取礦物、石頭與珠寶，或者是剝取獸皮。

你可以利用採集類技能來支援相關的生產類技能，或是直接將原料拿到拍賣場出售。', `MaleText_loc7`='Las profesiones de recolección te permiten adquirir materias primas para las profesiones secundarias: puedes recoger hierbas, extraer minerales, piedras y joyas, o desollar bestias para obtener su pellejo.

Puedes suministrar lo que recolectes a una profesión de producción relacionada, o vender las materias primas en la casa de subastas.', `FemaleText_loc1`='채집 기술을 배우면 약초, 광물, 보석을 캐내고 짐승의 가죽을 벗기는 등의 작업 등을 통해 생산 기술에 필요한 원료를 직접 구할 수 있습니다.

채집한 원료는 관련된 생산 기술 작업에 직접 사용하거나 그냥 경매장에 등록해서 팔 수도 있습니다.', `FemaleText_loc4`='采集技能让你能够获得生产技能所需的原始材料：采集草药；开采矿石、石料和宝石；或者从野兽的尸体上剥去皮革。

你可以用自己采集来的原料支持你的生产技能需求，或者是在拍卖行中出售你采集来的原料。', `FemaleText_loc5`='採集類技能可助你取得生產類專業技能所需的原料，包括採集藥草，挖取礦物、石頭與珠寶，或者是剝取獸皮。

你可以利用採集類技能來支援相關的生產類技能，或是直接將原料拿到拍賣場出售。', `FemaleText_loc7`='Las profesiones de recolección te permiten adquirir materias primas para las profesiones secundarias: puedes recoger hierbas, extraer minerales, piedras y joyas, o desollar bestias para obtener su pellejo.

Puedes suministrar lo que recolectes a una profesión de producción relacionada, o vender las materias primas en la casa de subastas.' WHERE `ID`=47108;
