UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계공학을 가르쳐 주십시오.', `MaleText_loc4`='我要学习工程学。', `MaleText_loc5`='請教導我工程學。', `MaleText_loc7`='Instrúyeme en ingeniería.', `FemaleText_loc1`='기계공학을 가르쳐 주세요.', `FemaleText_loc4`='我要学习工程学。', `FemaleText_loc5`='請教導我工程學。', `FemaleText_loc7`='Instrúyeme en ingeniería.' WHERE `ID`=47119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳건히 버텨라. 우리 와일드해머는 마지막 그 순간까지 싸운다!', `MaleText_loc4`='坚守阵地。蛮锤氏族战至最后一息也不后退！', `MaleText_loc5`='守住原地，我們蠻錘矮人絕對會死戰到底!', `MaleText_loc7`='No cedan terreno. ¡Los Martillo Salvaje lucharemos hasta el final!' WHERE `ID`=47120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저, 그날은 날씨가 맑지 않았어요. 데스윙이 나타났을 때 구름이 하늘을 뒤덮고 있었죠.', `MaleText_loc4`='首先，死亡之翼出现的时候没有太阳，而是阴云满空。', `MaleText_loc5`='首先，那並不是大晴天。死亡之翼出現的時候，其實是多雲的陰天。', `MaleText_loc7`='En primer lugar, no hacía sol. Estaba nublado cuando apareció Alamuerte.' WHERE `ID`=47121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 용 녀석이 저를 본 게 분명해요. 갑자기 돌아서더니 구름 속으로 사라져버렸거든요.', `MaleText_loc4`='那头胆小的龙一定是看见我了，因为他转过头，又钻进了黑云里。', `MaleText_loc5`='那頭孬種的黑龍肯定是看到我了，因為他掉頭就跑，飛進雲裡躲起來。', `MaleText_loc7`='Ese dragón cobarde debió verme, porque se dio la vuelta y desapareció entre las nubes.' WHERE `ID`=47122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운 좋게도, 마침 저는 세상 축소 장치를 만들고 있었죠.', `MaleText_loc4`='幸运的是，我一直在修补我的世界缩小设备。', `MaleText_loc5`='還好，我一直在實驗我的世界縮小裝置。', `MaleText_loc7`='Por suerte, había estado trasteando con mi dispositivo encogedor del mundo.' WHERE `ID`=47123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"내가 구름 속에서 널 찾아낼 거다, 버러지 같은 놈아! 그리고 칼림도어로 날려보내 주지!"', `MaleText_loc4`='“我会在那堆云里找到你的，你这只大虫子！”我吼道：“然后我就会把你丢到卡利姆多去！”', `MaleText_loc5`='「臭蟲子，我會把你從雲裡面揪出來的!」我大聲喊說:「然後我要把你扔到卡林多!」', `MaleText_loc7`='"¡Te encontraré en esas nubes, gusano!", le grité. "¡Y luego te lanzaré hasta Kalimdor!".' WHERE `ID`=47124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 구름 속에서 널 찾아낼 거다, 버러지 같은 놈아!', `MaleText_loc4`='我会在那堆云里找到你的，你这只大虫子！', `MaleText_loc5`='臭蟲子，我會把你從雲裡面揪出來的!', `MaleText_loc7`='¡Te encontraré en esas nubes, gusano!' WHERE `ID`=47125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 칼림도어로 날려보내 주지!', `MaleText_loc4`='然后我就会把你丢到卡利姆多去！', `MaleText_loc5`='然後我要把你扔到卡林多!', `MaleText_loc7`='¡Y luego te lanzaré hasta Kalimdor!' WHERE `ID`=47126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 전 구름이 손에 닿을 때까지 세상을 작게 만들기로 했어요.$b$b|TInterface\\Icons\\inv_helmet_47.blp:32|t', `MaleText_loc4`='我决定继续收缩世界，直到我能摸到那些云彩。$b$b|TInterface\\Icons\\inv_helmet_47.blp:32|t', `MaleText_loc5`='我決定繼續縮小這個世界，直到我可以把手伸到雲裡面。$b$b|TInterface\\Icons\\inv_helmet_47.blp:32|t', `MaleText_loc7`='Decidí seguir encogiendo el mundo hasta que pudiera alcanzar las nubes.$b$b|TInterfaceIconsinv_helmet_47.blp:32|t' WHERE `ID`=47127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고위주술사가 나타났군... 폭풍 구름이 보인다. 놈을 해치우고 해골은 전리품으로 삼자!', `MaleText_loc4`='高阶萨满祭司就在这里——我能看到那团暴风云。干掉他，我们也许能从他身上弄到一个漂亮的战利品！', `MaleText_loc5`='高階薩滿在此。我看見了暴風雲團了。擊垮他，拿他的頭來當戰利品!', `MaleText_loc7`='El alto chamán está aquí, puedo ver las nubes de tormenta. ¡Aplastadlo y llevémonos su calavera como trofeo!', `FemaleText_loc1`='고위주술사가 나타났군... 폭풍 구름이 보인다. 놈을 해치우고 해골은 전리품으로 삼자!', `FemaleText_loc4`='高阶萨满祭司就在这里——我能看到那团暴风云。干掉他，我们也许能从他身上弄到一个漂亮的战利品！', `FemaleText_loc5`='高階薩滿在此。我看見了暴風雲團了。擊垮他，拿他的頭來當戰利品!', `FemaleText_loc7`='El alto chamán está aquí, puedo ver las nubes de tormenta. ¡Aplastadlo y llevémonos su calavera como trofeo!' WHERE `ID`=47128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생산 기술을 배우면 천연 재료를 사용해서 당신이 직접 사용하거나 동료에게 선물하거나 경매장에 등록해서 팔 수 있는 아이템을 생산할 수 있습니다.

생산 기술은 보통 채집 기술과 짝을 이루는데, 이를 통해 원하는 재료를 직접 채집할 수 있습니다. 아니면 간단하게 경매장을 통해 원하는 재료를 사들이는 방법도 있습니다.', `MaleText_loc4`='生产技能让你可以将采集到的原始材料加工成各种有用的物品。你可以自行使用这些物品；或者将它们赠予你的同伴；或者在拍卖行出售它们。

每一项生产技能通常都会有与之相对应的采集技能，这样你就可以用自己采集的原料支持你的生产技能。不过你也可以在拍卖行购买自己所需要的原料。', `MaleText_loc5`='生產類專業技能可讓你將各種原物料製作成物品，供應自己或朋友使用，或是拿到拍賣場出售。

選擇生產類技能時通常會搭配一個相對應的採集類專業技能，以利自行取得所需的製作原料;不過，若是要完全透過拍賣場來購買原料其實也是可行的。', `MaleText_loc7`='Las profesiones de producción te permiten transformar materias primas en objetos que puedes usar, dar a tus amigos o vender en la casa de subastas.

Se suelen compaginar con profesiones de recolección, para poder recoger tus propias materias primas, pero también se pueden comprar los materiales en la casa de subastas.', `FemaleText_loc1`='생산 기술을 배우면 천연 재료를 사용해서 당신이 직접 사용하거나 동료에게 선물하거나 경매장에 등록해서 팔 수 있는 아이템을 생산할 수 있습니다.

생산 기술은 보통 채집 기술과 짝을 이루는데, 이를 통해 원하는 재료를 직접 채집할 수 있습니다. 아니면 간단하게 경매장을 통해 원하는 재료를 사들이는 방법도 있습니다.', `FemaleText_loc4`='生产技能让你可以将采集到的原始材料加工成各种有用的物品。你可以自行使用这些物品；或者将它们赠予你的同伴；或者在拍卖行出售它们。

每一项生产技能通常都会有与之相对应的采集技能，这样你就可以用自己采集的原料支持你的生产技能。不过你也可以在拍卖行购买自己所需要的原料。', `FemaleText_loc5`='生產類專業技能可讓你將各種原物料製作成物品，供應自己或朋友使用，或是拿到拍賣場出售。

選擇生產類技能時通常會搭配一個相對應的採集類專業技能，以利自行取得所需的製作原料;不過，若是要單純透過拍賣場來購買原料其實也是可行的。', `FemaleText_loc7`='Las profesiones de producción te permiten transformar materias primas en objetos que puedes usar, dar a tus amigos o vender en la casa de subastas.

Se suelen compaginar con profesiones de recolección, para poder recoger tus propias materias primas, pero también se pueden comprar los materiales en la casa de subastas.' WHERE `ID`=47129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초채집을 배우면 야생에서 약초의 위치를 확인해서 채집할 수 있습니다. 이렇게 채집한 약초는 연금술이나 주문각인 재료로 사용하거나 경매장에 등록해서 팔 수 있습니다.

숙련된 약초채집가는 대지에 대한 지식으로 자신을 치유할 수도 있습니다.', `MaleText_loc4`='草药学让你能在原野上找到并采集草药。草药可以在拍卖行出售，或者作为炼金术和铭文技能的原料。

技艺高超的草药师还能利用他们对于大地的知识进行自我治疗。', `MaleText_loc5`='草藥學能讓你尋找與採集野外的藥草，然後拿到拍賣場出售，或是用來支援鍊金術或銘文學。

技巧純熟的草藥師亦可發揮他們對於大地的知識來醫療自己。', `MaleText_loc7`='La herboristería te permite encontrar y recoger hierbas salvajes. Se pueden vender en la casa de subastas o aprovechar para suministrar las profesiones de alquimia o inscripción.

Los herboristas cualificados también pueden utilizar su conocimiento de la tierra para sanarse.', `FemaleText_loc1`='약초채집을 배우면 야생에서 약초의 위치를 확인해서 채집할 수 있습니다. 이렇게 채집한 약초는 연금술이나 주문각인 재료로 사용하거나 경매장에 등록해서 팔 수 있습니다.

숙련된 약초채집가는 대지에 대한 지식으로 자신을 치유할 수도 있습니다.', `FemaleText_loc4`='草药学让你能在原野上找到并采集草药。草药可以在拍卖行出售，或者作为炼金术和铭文技能的原料。

