UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재봉술에 대해 알려주십시오.', `MaleText_loc4`='和我说说裁缝。', `MaleText_loc5`='請為我介紹裁縫。', `MaleText_loc7`='Háblame de la sastrería.', `FemaleText_loc1`='재봉술에 대해 알려주세요.', `FemaleText_loc4`='和我说说裁缝。', `FemaleText_loc5`='請為我介紹裁縫。', `FemaleText_loc7`='Háblame de la sastrería.' WHERE `ID`=47152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니? 용아귀 부족이 더 있군! 바싹 붙어라... 놈들이 사방에서 몰려온다!', `MaleText_loc4`='什么？更多的龙喉兽人？收紧队形，绝对不要散开——他们正从四面八方攻过来！', `MaleText_loc5`='什麼?還有更多龍喉氏族的傢伙?別走遠，他們從四面八方包圍過來了!', `MaleText_loc7`='¿Qué? ¿MÁS Faucedraco? No te alejes, ¡vienen por todas partes!' WHERE `ID`=47153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 아주 작게 만든 다음에 저는 구름 속에 숨은 데스윙 사냥을 시작했어요.$b$b|TInterface\\Icons\\spell_frost_arcticwinds.blp:32|t', `MaleText_loc4`='一旦这个世界收缩到足够小，我就会开始在云端猎捕死亡之翼。$b$b|TInterface\\Icons\\spell_frost_arcticwinds.blp:32|t', `MaleText_loc5`='等世界變得夠小的時候，我就要開始在雲裡面獵捕死亡之翼。$b$b|TInterface\\Icons\\spell_frost_arcticwinds.blp:32|t', `MaleText_loc7`='Cuando el mundo fue lo bastante pequeño, empecé a darle caza a Alamuerte por las nubes.$b$b|TInterfaceIconsspell_frost_arcticwinds.blp:32|t' WHERE `ID`=47154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 잘 싸워줬다! 망치에 흠집이 늘어날수록 썬더마는 더욱 안전해진다는 사실을 기억해라.', `MaleText_loc4`='大家打得好！我的锤子上又多了几道刮痕，而威胁桑德玛尔的龙喉兽人又少了一些。', `MaleText_loc5`='打得漂亮啊!雖然我的錘子又多了幾個缺口，但是又少了幾個龍喉威脅桑德瑪。', `MaleText_loc7`='¡Buena pelea, chicos! Unas cuantas muescas más en mi martillo y unos cuantos Faucedraco menos para amenazar Bramal.' WHERE `ID`=47155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주도로를 감시해라. 멍청한 용아귀 놈들이 또 공격을 감행할 것이다.', `MaleText_loc4`='守住主路。愚蠢的龙喉兽人一定会再次发动进攻的。', `MaleText_loc5`='守住主要通道，龍喉的傢伙有可能真的會笨到再來試一次。', `MaleText_loc7`='Vigilad el camino principal. Esos Faucedraco son lo bastante tontos como para volver a intentarlo.' WHERE `ID`=47156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간 사냥꾼들아, 붉은송곳니 일족이 너희를 잡으러 간다!', `MaleText_loc4`='血牙是为你们而来的，狼人猎手们！', `MaleText_loc5`='血牙找上你了，狩狼獵人!', `MaleText_loc7`='¡Los Colmillo de Sangre vienen por ustedes, cazadores huargen!' WHERE `ID`=47157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저쪽으로 가면 나오는 큰 방에 스프링베일이 있다, 영웅들이여.', `MaleText_loc4`='指挥官斯普林瓦尔就在那座大厅里，英雄们。', `MaleText_loc5`='指揮官斯普林瓦爾就在那座大廳裡，英雄。', `MaleText_loc7`='El comandante Vallefont está al final de ese pasillo, héroes.' WHERE `ID`=47158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머의 고위주술사를 물리쳤군. 우리 쪽 피해 상황을 파악해라. 피투성이 협곡에서 우리의 승전보를 기다린다!', `MaleText_loc4`='那个蛮锤高阶萨满祭司已经完了。计算一下我们的死伤。溅血谷地一定在等待着我们胜利的消息！', `MaleText_loc5`='蠻錘的高階薩滿掛點了。統計一下死傷，然後讓整個鮮血峽谷都知道我們勝利了!', `MaleText_loc7`='El alto chamán de los Martillo Salvaje está acabado. Contad nuestros muertos. ¡Garganta de Sangre estará ansiosa por saber de nuestro triunfo!', `FemaleText_loc1`='와일드해머의 고위주술사를 물리쳤군. 우리 쪽 피해 상황을 파악해라. 피투성이 협곡에서 우리의 승전보를 기다린다!', `FemaleText_loc4`='那个蛮锤高阶萨满祭司已经完了。计算一下我们的死伤。溅血谷地一定在等待着我们胜利的消息！', `FemaleText_loc5`='蠻錘的高階薩滿掛點了。統計一下死傷，然後讓整個鮮血峽谷都知道我們勝利了!', `FemaleText_loc7`='El alto chamán de los Martillo Salvaje está acabado. Contad nuestros muertos. ¡Garganta de Sangre estará ansiosa por saber de nuestro triunfo!' WHERE `ID`=47160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 곧 다시 몰려올 것이다. 피투성이 협곡으로 돌아가자.', `MaleText_loc4`='他们很快就会回来。我们回溅血谷地去。', `MaleText_loc5`='他們很快還會再回來。我們回鮮血峽谷吧。', `MaleText_loc7`='Volverán pronto. Volvamos a Garganta de Sangre.', `FemaleText_loc1`='놈들이 곧 다시 몰려올 것이다. 피투성이 협곡으로 돌아가자.', `FemaleText_loc4`='他们很快就会回来。我们回溅血谷地去。', `FemaleText_loc5`='他們很快還會再回來。我們回鮮血峽谷吧。', `FemaleText_loc7`='Volverán pronto. Volvamos a la Garganta de Sangre.' WHERE `ID`=47161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지면에 떨어진 유성을 사용하여 %s에게 치명타를 날려야 합니다!', `MaleText_loc4`='使用流星，对%s造成致命一击！', `MaleText_loc5`='利用地上的隕石對%s發動致命的攻擊!', `MaleText_loc7`='¡Usa el meteorito en el suelo para lanzar un ataque crítico sobre %s!', `FemaleText_loc1`='지면에 떨어진 유성을 사용하여 %s에게 치명타를 날려야 합니다!', `FemaleText_loc4`='使用流星，对%s造成致命一击！', `FemaleText_loc5`='利用地上的隕石對%s發動致命的攻擊!', `FemaleText_loc7`='¡Usa el meteorito en el suelo para lanzar un ataque crítico sobre %s!' WHERE `ID`=47162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름을 전부 다 뒤졌는데도 데스윙을 찾을 수 없었어요.', `MaleText_loc4`='我已经搜查了每一片云，但就是找不到死亡之翼。', `MaleText_loc5`='我已經找遍了每一朵雲，可是我還是找不到死亡之翼。', `MaleText_loc7`='Busqué en todas las nubes, pero no pude encontrar a Alamuerte.' WHERE `ID`=47163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 문득 깨달았죠. 녀석이 태양 뒤에 숨어 있다는 사실을요. 그래서 하늘 위를 봤죠.', `MaleText_loc4`='这时我意识到：他正藏在太阳里。我向上望过去。', `MaleText_loc5`='這時候我才忽然想到:他躲在太陽裡。於是我抬頭往上看。', `MaleText_loc7`='Entonces me di cuenta: se estaba escondiendo en el sol. Alcé la vista.' WHERE `ID`=47164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지하실에서 왠지 불길한 기운이 느껴집니다...', `FemaleText_loc4`='对于这个地下室，你有一种很不好的感觉……', `FemaleText_loc5`='這個地下室讓你有一種很不好的預感...', `FemaleText_loc7`='Este sótano te da mala espina...' WHERE `ID`=47165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양에 손을 심하게 뎄지만, 전 녀석의 끈적끈적한 목을 쥐어 잡았어요.', `MaleText_loc4`='太阳严重地灼伤了我，但我的双手终于抓住了他黏滑的脖子。', `MaleText_loc5`='太陽燙得我超難受的，不過我還是用雙手抓住了他黏呼呼的脖子。', `MaleText_loc7`='El sol me quemó intensamente, pero lo agarré por su cuello resbaladizo.' WHERE `ID`=47166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고 나서 힘을 모은 다음에, 서쪽을 바라보고 놈을 칼림도어로 던져버렸어요.', `MaleText_loc4`='我聚集起全部力量，转向西方，将他朝卡利姆多扔了过去。', `MaleText_loc5`='我鼓起全身的力氣，面向西方，然後把他扔到卡林多。', `MaleText_loc7`='Reuní todas mis fuerzas, me giré al oeste y lo lancé hasta Kalimdor.' WHERE `ID`=47167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 맥주 맛 좀 한 번 봐요.', `MaleText_loc4`='你一定要试试这种啤酒。', `MaleText_loc5`='這個啤酒你一定要喝喝看。', `MaleText_loc7`='Deberías probar esta cerveza.' WHERE `ID`=47168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 얘기해주십시오, 루시앙.', `MaleText_loc4`='再和我聊聊那个故事，卢希恩。', `MaleText_loc5`='再跟我說一遍那個故事，盧希恩。', `MaleText_loc7`='Cuéntame esa historia otra vez, Lucien.', `FemaleText_loc1`='다시 한 번 얘기해주세요, 루시앙.', `FemaleText_loc4`='再和我聊聊那个故事，卢希恩。', `FemaleText_loc5`='再跟我說一遍那個故事，盧希恩。', `FemaleText_loc7`='Cuéntame esa historia otra vez, Lucien.' WHERE `ID`=47169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 있니, 겁쟁이 용아?', `MaleText_loc4`='龙，你在哪里？', `MaleText_loc5`='臭黑龍，你在哪裡?', `MaleText_loc7`='¿Dónde estás, dragón?' WHERE `ID`=47170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 숨어 있니?', `MaleText_loc4`='你藏在这团云里吗？', `MaleText_loc5`='你有沒有藏在這朵雲裡面?', `MaleText_loc7`='¿Te escondes en esta nube?' WHERE `ID`=47171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루시앙이 널 찾아낼 거다!', `MaleText_loc4`='卢希恩要抓住你！', `MaleText_loc5`='盧希恩會逮到你的!', `MaleText_loc7`='¡Lucien va a por ti!' WHERE `ID`=47172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랐지, 요놈아! 이런, 제길!', `MaleText_loc4`='吃惊吧，龙！哦，哼！', `MaleText_loc5`='找到你了，臭黑龍!啊，討厭。', `MaleText_loc7`='¡Sorpresa, dragón! Oh, vaya.' WHERE `ID`=47173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 숨었나?', `MaleText_loc4`='你在哪里？', `MaleText_loc5`='你在哪裡?', `MaleText_loc7`='¿Dónde estás?' WHERE `ID`=47174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리는 못 갔을 텐데...', `MaleText_loc4`='他不可能逃得太远……', `MaleText_loc5`='他不可能跑太遠的...', `MaleText_loc7`='No puede haber ido muy lejos...' WHERE `ID`=47175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 용 녀석을 찾으면 칼림도어로 날려버리겠어!', `MaleText_loc4`='等我找到那条龙，我就把它扔到卡利姆多去。', `MaleText_loc5`='等我找到那頭龍的時候，我要把他丟到卡林多。', `MaleText_loc7`='Cuando encuentre a ese dragón, lo voy a lanzar hasta Kalimdor.' WHERE `ID`=47176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙, 난 네가 정말 싫어!', `MaleText_loc4`='我恨你，死亡之翼。', `MaleText_loc5`='我恨你，死亡之翼。', `MaleText_loc7`='Te odio, Alamuerte.' WHERE `ID`=47177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우, 루시앙. 자네 지금 당장 술을 끊어야겠는데!', `MaleText_loc4`='喔，卢希恩。你绝对不能再喝了。', `MaleText_loc5`='哇，盧希恩，你不能再喝了。現在就停。', `MaleText_loc7`='Oye, Lucien. Tienes que parar de beber AHORA MISMO.' WHERE `ID`=47178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일하러 온 것이 아니라면 우릴 방해하지 말고 여기서 떠나시오.', `MaleText_loc4`='如果你不打算工作，那就离我们的发掘场远一些。', `MaleText_loc5`='假如你不是來工作的，那麼請離開我們的挖掘現場。', `MaleText_loc7`='Si no has venido a trabajar, te ruego que abandones la excavación.' WHERE `ID`=47179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 거기 잘생긴 양반.', `MaleText_loc4`='嘿，帅哥！', `MaleText_loc5`='嘿，你好!', `MaleText_loc7`='Hola, tío bueno.', `FemaleText_loc1`='이봐요, 거기 잘생긴 아저씨.', `FemaleText_loc4`='嘿，帅哥！', `FemaleText_loc5`='嘿，你好!', `FemaleText_loc7`='Hola, tío bueno.' WHERE `ID`=47180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 탈 자리는 있는 건가, 자기?', `MaleText_loc4`='还有地方吗，甜心？', `MaleText_loc5`='親愛的，還有多載個人的位置嗎?', `MaleText_loc7`='¿Te sobra sitio, cielo?', `FemaleText_loc1`='내가 탈 자리는 있는 거야, 자기?', `FemaleText_loc4`='还有地方吗，甜心？', `FemaleText_loc5`='親愛的，還有多載個人的位置嗎?', `FemaleText_loc7`='¿Te sobra sitio, cielo?' WHERE `ID`=47181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나하고 같은 방향으로 가시나?', `MaleText_loc4`='跟我走吗？', `MaleText_loc5`='能搭個便車嗎?', `MaleText_loc7`='¿Vamos en la misma dirección?', `FemaleText_loc1`='저와 같은 방향으로 가시나요?', `FemaleText_loc4`='跟我走吗？', `FemaleText_loc5`='能搭個便車嗎?', `FemaleText_loc7`='¿Vamos en la misma dirección?' WHERE `ID`=47182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 예쁜 아가씨 좀 태워주시겠나?', `MaleText_loc4`='一位淑女能够上马驰骋一番吗？', `MaleText_loc5`='方便載淑女一程嗎?', `MaleText_loc7`='¿Hay sitio para una señorita?', `FemaleText_loc1`='이 예쁜 아가씨 좀 태워주시겠어요?', `FemaleText_loc4`='一位淑女能够上马驰骋一番吗？', `FemaleText_loc5`='方便載淑女一程嗎?', `FemaleText_loc7`='¿Hay sitio para una señorita?' WHERE `ID`=47183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 아주 멋져 보입니다, 마르텍.', `MaleText_loc4`='马特克，你今天看上去很英俊。', `MaleText_loc5`='你今天看起來特別帥，馬特克。', `MaleText_loc7`='Hoy estás muy apuesto, Martek.', `FemaleText_loc1`='오늘 아주 멋져 보이네요, 마르텍.', `FemaleText_loc4`='马特克，你今天看上去很英俊。', `FemaleText_loc5`='你今天看起來特別帥，馬特克。', `FemaleText_loc7`='Hoy estás muy apuesto, Martek.' WHERE `ID`=47184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 마르텍, 같이 좀 탈 수 있겠습니까?', `MaleText_loc4`='哦，马特克，我能和你一起驰骋吗？', `MaleText_loc5`='哦，馬特克，我可以跟你一起坐嗎?', `MaleText_loc7`='Ooh, Martek, ¿puedo ir contigo?', `FemaleText_loc1`='오, 마르텍, 같이 좀 탈 수 있을까요?', `FemaleText_loc4`='哦，马特克，我能和你一起驰骋吗？', `FemaleText_loc5`='哦，馬特克，我可以跟你一起坐嗎?', `FemaleText_loc7`='Ooh, Martek, ¿puedo ir contigo?' WHERE `ID`=47185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마르텍, 당신은 내가 아는 오크 중에 제일 용감한 오크입니다.', `MaleText_loc4`='马特克，你是我所知道的最勇敢的兽人。', `MaleText_loc5`='馬特克，你是我所見過最勇敢的獸人。', `MaleText_loc7`='Martek, eres el orco más valiente que conozco.', `FemaleText_loc1`='마르텍, 당신은 내가 아는 오크 중에 제일 용감한 오크랍니다.', `FemaleText_loc4`='马特克，你是我所知道的最勇敢的兽人。', `FemaleText_loc5`='馬特克，你是我所見過最勇敢的獸人。', `FemaleText_loc7`='Martek, eres el orco más valiente que conozco.' WHERE `ID`=47186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 구해주게, 마르텍! 난 당신이 필요하다고!', `MaleText_loc4`='救救我，马特克！我需要你！', `MaleText_loc5`='救救我，馬特克!我需要你!', `MaleText_loc7`='¡Sálvame, Martek! ¡Te necesito!', `FemaleText_loc1`='날 구해줘요, 마르텍! 난 당신이 필요해요!', `FemaleText_loc4`='救救我，马特克！我需要你！', `FemaleText_loc5`='救救我，馬特克!我需要你!', `FemaleText_loc7`='¡Sálvame, Martek! ¡Te necesito!' WHERE `ID`=47187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타시오, 예쁜 아가씨.', `MaleText_loc4`='上来，宝贝。', `MaleText_loc5`='上車吧，寶貝。', `MaleText_loc7`='Sube, nena.', `FemaleText_loc1`='타시오, 예쁜 아가씨.', `FemaleText_loc4`='上来，宝贝。', `FemaleText_loc5`='上車吧，寶貝。', `FemaleText_loc7`='Sube, nena.' WHERE `ID`=47188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월든의 악취가 느껴진다. 놈의 피냄새로 이곳을 채우자!', `MaleText_loc4`='我闻到了沃登的臭气。今天他难逃一死！', `MaleText_loc5`='我聞到瓦爾登的臭味了。空氣裡都是他的血的味道!', `MaleText_loc7`='He encontrado el hedor de Walden. ¡Saturad el aire con su sangre!' WHERE `ID`=47189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈다귀 냄새가 나는데...', `MaleText_loc4`='骨头？', `MaleText_loc5`='骨頭?', `MaleText_loc7`='¿Huesos?' WHERE `ID`=47190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 길로 가면 도시 안으로 더 깊숙이 들어갈 뿐입니다. 선적실을 향해 남쪽으로 계속 가십시오.', `FemaleText_loc4`='这条路通向城市的更深处。继续朝南，向装载室走。', `FemaleText_loc5`='這條路只通往城裡的更深處，繼續往南走，前往裝載室。', `FemaleText_loc7`='Este camino solo lleva al interior de la ciudad. Sigue yendo al sur hacia la Zona de Carga.' WHERE `ID`=47191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 용 대가리에 주먹을 한 방 먹여주겠어!', `MaleText_loc4`='我要一拳砸在那头龙的脸上！', `MaleText_loc5`='我要在那頭龍的臉上狠狠揍一拳!', `MaleText_loc7`='¡Voy a darle un puñetazo a ese dragón en toda la cara!' WHERE `ID`=47192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='我们出发吧！', `MaleText_loc5`='快走!', `MaleText_loc7`='¡Movámonos!' WHERE `ID`=47193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 느낌이 좋지 않소...', `MaleText_loc4`='我对此有一种不祥的感觉……', `MaleText_loc5`='我有一種不好的預感...', `MaleText_loc7`='Esto me da mala espina...' WHERE `ID`=47194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클레이가 지휘하는 투석기 중 하나가 전초지에서 고장났다고 하네. 클레이에게 가서 부품을 받게나. 그리고 고장난 투석기를 수리하여 다시 전투에 투입시키게, $n.', `MaleText_loc4`='克莱的一支投石机部队在前线被击溃了。$n，我需要你从他那里取得一些零件，让那架投石机重新投入战斗！', `MaleText_loc5`='克雷有組投石車在前線被破壞了。$n，我要你去跟他拿一些零件，然後去讓那架投石車恢復戰力!', `MaleText_loc7`='Uno de los equipos de catapulta de Berilo se ha quedado tirado en el frente de batalla por una avería, $n. ¡Necesito que les lleves algunas piezas para que la catapulta vuelva a la batalla!' WHERE `ID`=47195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소, $c.$b$b요즘은 여기까지 찾아주는 사람이 별로 없어서 말이오.', `MaleText_loc4`='真是荣幸，$c。$b$b这些日子里，来我们这里的人实在是太少了。', `MaleText_loc5`='真是榮幸，$c。$b$b最近我們都沒什麼客人來。', `MaleText_loc7`='Vaya, vaya, qué placer, $c.$b$bÚltimamente recibimos tan pocas visitas.' WHERE `ID`=47196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 반갑소!$b$b사실 오늘 찾아올 사람이 있는 줄은 몰랐었소.', `FemaleText_loc4`='真是令人惊讶！$b$b没想到今天会有人来……', `FemaleText_loc5`='真是意外啊!$b$b我們可沒料到今日會有訪客...', `FemaleText_loc7`='¡Qué sorprrresa!$b$bNo esperrrábamos a nadie hoy...' WHERE `ID`=47197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 온 날, 하늘에서는 피가 비처럼 쏟아지고 있었소.', `MaleText_loc4`='死亡之翼到来的那一天，血雨腥风，好不可怕。', `MaleText_loc5`='死亡之翼現身之日，天空降下了血雨。', `MaleText_loc7`='El día que vino Alamuerte llovió sangre del cielo.' WHERE `ID`=47198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 나는 예쁜 아가씨들한테 내 오토바이를 보여주고 있었던 것 같소.', `MaleText_loc4`='那时我应该正在向一些辣妹展示我的摩托车。', `MaleText_loc5`='我記得，當時我正在跟幾位帥哥辣妹展示我帥氣的摩托車。', `MaleText_loc7`='Creo que les estaba enseñando mi moto a unas chavas buenas en aquel momento.' WHERE `ID`=47199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 나타나자, 그녀들은 겁에 질렸소. 그런데 오토바이에는 한 명을 태울 자리밖에 없었던 거요.', `MaleText_loc4`='死亡之翼一出现，她们都被吓坏了，但我只能救走她们之中的一个。', `MaleText_loc5`='死亡之翼的出現把他們全部都嚇壞了，可是我的座位只能載走一個人而已。', `MaleText_loc7`='Cuando apareció Alamuerte se asustaron mucho, pero solo tenía sitio para rescatar a una de ellas.' WHERE `ID`=47200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 나는 오크를 선택했소.', `MaleText_loc4`='当然，我选择了兽人。', `MaleText_loc5`='不用說，我選擇了獸人。', `MaleText_loc7`='Evidentemente, elegí a la orco.' WHERE `ID`=47201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 나는 인간을 선택했소.', `MaleText_loc4`='当然，我选择了人类。', `MaleText_loc5`='不用說，我選擇了人類 。', `MaleText_loc7`='Evidentemente, elegí a la humana.' WHERE `ID`=47202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 나는 나이트 엘프를 선택했소.', `MaleText_loc4`='当然，我选择了暗夜精灵。', `MaleText_loc5`='不用說，我選擇了夜精靈。', `MaleText_loc7`='Evidentemente, elegí a la elfa de la noche.' WHERE `ID`=47203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 나는 블러드 엘프를 선택했소.', `MaleText_loc4`='当然，我选择了血精灵。', `MaleText_loc5`='不用說，我選擇了血精靈。', `MaleText_loc7`='Evidentemente, elegí a la elfa de sangre.' WHERE `ID`=47204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 떨어지는 바위를 피하며 협곡을 가로질러 갔소.', `MaleText_loc4`='我们在山谷中飞驰，一边还要注意躲避落石。', `MaleText_loc5`='我們騎到峽谷裡面，小心避開落石。', `MaleText_loc7`='Condujimos por el cañón, con cuidado de esquivar las rocas que caían.' WHERE `ID`=47205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협곡 끝에 도착했을 때, 나는 내 오토바이가 날 수 있다는 사실이 떠올랐소.', `MaleText_loc4`='当我到达山谷尽头的时候，我才想起我的摩托车是能飞的。', `MaleText_loc5`='等我抵達峽谷盡頭的時候，我才想起我的摩托車其實是會飛的。', `MaleText_loc7`='Cuando llegamos al final del cañón, recordé que mi moto puede volar.' WHERE `ID`=47206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 일찍 기억해냈다면 좋았을 것을...', `MaleText_loc4`='如果我能早一些想起来，情况一定会好得多。', `MaleText_loc5`='要是我有早點想起來就好了。', `MaleText_loc7`='Habría venido bien saberlo antes.' WHERE `ID`=47207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 나는 협곡 북쪽에 있는 산꼭대기로 날아갔소.', `MaleText_loc4`='我飞到了山谷北边的柱子顶端。', `MaleText_loc5`='於是，我飛到了峽谷北邊那根大石柱的上面。', `MaleText_loc7`='Volé hasta lo alto del pilar que hay justo al norte del cañón.' WHERE `ID`=47208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산꼭대기에 놈이 있었소. 데스윙 말이오. 최고의 결투가 펼쳐질 시간이 왔던 것이오.', `MaleText_loc4`='在那里，我看见了：死亡之翼。最终的决斗到来了。', `MaleText_loc5`='在那上面，我看到了他:死亡之翼。終極對決的時刻終於來臨。', `MaleText_loc7`='En lo alto del pilar, lo vi: Alamuerte. Había llegado el momento del enfrentamiento final.' WHERE `ID`=47209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰, 텔두린! 이건 내 얘기라고!', `MaleText_loc4`='嗨，住嘴，塞尔杜林！这是我的故事！', `MaleText_loc5`='嘿，慢著，塞爾杜林!這是我要講的故事!', `MaleText_loc7`='¡Para, Thaldurin! ¡Esta es mi historia!' WHERE `ID`=47210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 얘길 방해하지 말라고!', `MaleText_loc4`='闭上嘴！别打断我！', `MaleText_loc5`='閉嘴!不要吵!', `MaleText_loc7`='¡Ya basta, chicos! ¡Dejen de interrumpir!' WHERE `ID`=47211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들 때문에 당신은 내가 데스윙을 칼싸움에서 어떻게 해치웠는지 못 듣게 된 거요. 내 잘못이 아니오.', `MaleText_loc4`='好吧，你听不到我是怎样用匕首打败死亡之翼的。这是你的损失。', `MaleText_loc5`='隨便啦，哼。你聽不到我怎樣用小刀打敗死亡之翼了。你的損失。', `MaleText_loc7`='Muy bien. Entonces no sabrán cómo derroté a Alamuerte en una pelea de navajas. Ustedes se lo pierden.' WHERE `ID`=47212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아가는 동안, 그 사랑스러운 오크 아가씨와 나는 아름다운 시간을 보냈소.', `MaleText_loc4`='我一边飞翔，一边与那个可爱的兽人度过了温柔的一刻。', `MaleText_loc5`='在飛行的時候，我跟這位可愛的獸人共度了一小段的美好時光。', `MaleText_loc7`='Durante el vuelo, disfruté de un momento de ternura con la encantadora orco.' WHERE `ID`=47213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아가는 동안, 그 매혹적인 아가씨와 나는 아름다운 시간을 보냈소.', `MaleText_loc4`='我一边飞翔，一边与那个诱人的人类度过了温柔的一刻。', `MaleText_loc5`='在飛行的時候，我跟這位漂亮的人類共度了一小段的美好時光。', `MaleText_loc7`='Durante el vuelo, disfruté de un momento de ternura con la hermosa humana.' WHERE `ID`=47214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아가는 동안, 나는 고마워서 어찌할 줄 모르는 그 나이트 엘프 아가씨와 아름다운 시간을 보냈소.', `MaleText_loc4`='我一边飞翔，一边与那个优雅的暗夜精灵度过了温柔的一刻。', `MaleText_loc5`='在飛行的時候，我跟這位心懷感激的年輕夜精靈共度了一小段的美好時光。', `MaleText_loc7`='Durante el vuelo, disfruté de un momento de ternura con la joven y agradecida elfa de la noche.' WHERE `ID`=47215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아가는 동안, 나는 그 늘씬한 블러드 엘프 아가씨와 아름다운 시간을 보냈소.', `MaleText_loc4`='我一边飞翔，一边与那个窈窕的血精灵度过了温柔的一刻。', `MaleText_loc5`='在飛行的時候，我跟這位高大的血精靈共度了一小段的美好時光。', `MaleText_loc7`='Durante el vuelo, disfruté de un momento de ternura con la despampanante elfa de sangre.' WHERE `ID`=47216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 일을 방해하다니.', `MaleText_loc4`='你干扰我的工作了，$c。', `MaleText_loc5`='你干擾到我的工作了，$c。', `MaleText_loc7`='Interrumpes mi trabajo, $c.' WHERE `ID`=47217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님을... 실망시키고 말았구나...', `MaleText_loc4`='我……辜负了主人……', `MaleText_loc5`='我讓...主人失望了...', `MaleText_loc7`='Le he fallado... Al maestro...' WHERE `ID`=47218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만났군, 존스 박사! 네가 이 지역에서 열심히 발굴 작업을 해준 덕에 내 임무가 훨씬 쉽게 끝났다.', `MaleText_loc4`='啊，琼斯博士，那位著名的考古学家！感谢你在这里所做的一切，我的任务现在轻松多了。', `MaleText_loc5`='我們又見面了，瓊斯博士!多謝你在這邊的努力，讓我的任務變得簡單多了。', `MaleText_loc7`='¡Nos encontrrramos de nuevo, doktorrr Jones! Grrracias a tu trrrabajo en esta rrregión, mi misión será mucho más sencilla.' WHERE `ID`=47219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 광고판이 하나 더 필요합니다.', `MaleText_loc4`='我还需要一块灾难预言公告板。', `MaleText_loc5`='我還需要一塊末日訊息板。', `MaleText_loc7`='Necesito otro tablón de mensajes del día del Juicio Final.', `FemaleText_loc1`='파멸의 광고판이 하나 더 필요합니다.', `FemaleText_loc4`='我还需要一块灾难预言公告板。', `FemaleText_loc5`='我還需要一塊末日訊息板。', `FemaleText_loc7`='Necesito otro tablón de mensajes del día del Juicio Final.' WHERE `ID`=47220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 모여라. 마을을 돌아봐야 한다. 자, 출발!', `MaleText_loc4`='聚集在一起。我们成功了。让我们开始吧！', `MaleText_loc5`='靠緊一點，準備要幹了。上啊!', `MaleText_loc7`='Acercaos. Vamos a hacerlo. ¡Adelante!' WHERE `ID`=47221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됩니다! 당신을 사랑합니다, 마르텍!', `MaleText_loc4`='不！我爱你，马特克！', `MaleText_loc5`='不!我愛你，馬特克!', `MaleText_loc7`='¡No! ¡Te quiero, Martek!', `FemaleText_loc1`='안 돼요! 당신을 사랑한다고요, 마르텍!', `FemaleText_loc4`='不！我爱你，马特克！', `FemaleText_loc5`='不!我愛你，馬特克!', `FemaleText_loc7`='¡No! ¡Te quiero, Martek!' WHERE `ID`=47222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜? 대체 왜 절 버린 겁니까?', `MaleText_loc4`='为什么？为什么你要离开我？', `MaleText_loc5`='為什麼?為什麼你要離開我?', `MaleText_loc7`='¿Por qué? ¿Por qué me abandonas?', `FemaleText_loc1`='왜? 대체 왜 절 버린 건가요?', `FemaleText_loc4`='为什么？为什么你要离开我？', `FemaleText_loc5`='為什麼?為什麼你要離開我?', `FemaleText_loc7`='¿Por qué? ¿Por qué me abandonas?' WHERE `ID`=47223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당신을 사랑했습니다, 마르텍!', `MaleText_loc4`='我爱你，马特克！', `MaleText_loc5`='我愛你，馬特克!', `MaleText_loc7`='¡Yo te quería, Martek!', `FemaleText_loc1`='난 당신을 사랑했어요, 마르텍!', `FemaleText_loc4`='我爱你，马特克！', `FemaleText_loc5`='我愛你，馬特克!', `FemaleText_loc7`='¡Yo te quería, Martek!' WHERE `ID`=47224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 알고 지낸 것만으로도 행복했습니다, 마르텍.', `MaleText_loc4`='很高兴能够在活着的时候认识你，马特克。', `MaleText_loc5`='很高興活著的時候能認識你，馬特克。', `MaleText_loc7`='Me alegro de haber vivido para conocerte, Martek.', `FemaleText_loc1`='당신을 알고 지낸 것만으로도 행복했어요, 마르텍.', `FemaleText_loc4`='很高兴能够在活着的时候认识你，马特克。', `FemaleText_loc5`='很高興活著的時候能認識你，馬特克。', `FemaleText_loc7`='Me alegro de haber vivido para conocerte, Martek.' WHERE `ID`=47225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게, 마르텍.', `MaleText_loc4`='再见，马特克。', `MaleText_loc5`='再見了，馬特克。', `MaleText_loc7`='Adiós, Martek.', `FemaleText_loc1`='잘 가요, 마르텍.', `FemaleText_loc4`='再见，马特克。', `FemaleText_loc5`='再見了，馬特克。', `FemaleText_loc7`='Adiós, Martek.' WHERE `ID`=47226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 잠깐 쉬자고. 힘을 회복하도록.', `MaleText_loc4`='在这里休息一会儿，恢复一下力量。', `MaleText_loc5`='在這裡歇一會兒，恢復你的力氣。', `MaleText_loc7`='Descansa aquí un momento. Reúne fuerzas.' WHERE `ID`=47227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삶의 마지막 순간을 마르텍과 함께했으니, 전 편히 숨을 거둘 수 있습니다.', `MaleText_loc4`='知道我最后的时刻能够和马特克在一起，我就能安心地死去了。', `MaleText_loc5`='最後的一刻是跟馬特克在一起，我可以死而無憾了。', `MaleText_loc7`='Puedo morir en paz, sabiendo que pasaré mis últimos momentos con Martek.', `FemaleText_loc1`='삶의 마지막 순간을 마르텍과 함께했으니, 전 편히 숨을 거둘 수 있어요.', `FemaleText_loc4`='知道我最后的时刻能够和马特克在一起，我就能安心地死去了。', `FemaleText_loc5`='最後的一刻是跟馬特克在一起，我可以死而無憾了。', `FemaleText_loc7`='Puedo morir en paz, sabiendo que pasaré mis últimos momentos con Martek.' WHERE `ID`=47228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 함께한 꿈 같던 그 여름날을 잊지 못할 겁니다, 마르텍.', `MaleText_loc4`='我永远也不会忘记那段与你共渡的美好夏日，马特克。', `MaleText_loc5`='我永遠不會忘記我們共度的那個美好夏日，馬特克。', `MaleText_loc7`='Nunca olvidaré aquel verano mágico que compartimos, Martek.', `FemaleText_loc1`='우리가 함께한 꿈 같던 그 여름날을 잊지 못할 거예요, 마르텍.', `FemaleText_loc4`='我永远也不会忘记那段与你共渡的美好夏日，马特克。', `FemaleText_loc5`='我永遠不會忘記我們共度的那個美好夏日，馬特克。', `FemaleText_loc7`='Nunca olvidaré aquel verano mágico que compartimos, Martek.' WHERE `ID`=47229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 마르텍이 나를 선택했다고!', `MaleText_loc4`='好啊！马特克选择了我！', `MaleText_loc5`='耶!馬特克選了我!', `MaleText_loc7`='¡Sí! ¡Martek me ha elegido a mí!', `FemaleText_loc1`='야호! 마르텍이 나를 선택했어!', `FemaleText_loc4`='好啊！马特克选择了我！', `FemaleText_loc5`='耶!馬特克選了我!', `FemaleText_loc7`='¡Sí! ¡Martek me ha elegido a mí!' WHERE `ID`=47230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 일어나자! 민간인이 없는지 주의를 기울여라. 썬더마를 위하여!', `MaleText_loc4`='好了！睁大眼睛，关照好平民。我们行动。为了桑德玛尔！', `MaleText_loc5`='好了!睜大眼睛注意一般民眾。出發了。為了桑德瑪!', `MaleText_loc7`='¡Muy bien! Mantened los ojos abiertos por si hay civiles. Vámonos. ¡Por Bramal!' WHERE `ID`=47231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 수 있는 일은 다 했다. 썬더마로 돌아가자!', `MaleText_loc4`='我们已经做了我们能做的一切。现在，让我们回桑德玛尔吧！', `MaleText_loc5`='在這兒我們能做的都已經做了，回桑德瑪吧!', `MaleText_loc7`='Hemos hecho lo que hemos podido. ¡Volvamos a Bramal!' WHERE `ID`=47232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 인정해야겠습니다. 이 야심 차고 건방진 녀석에게 흥미를 느꼈었다는 사실을요.$b$b뭐랄까, 성급히 결론을 내리고 싶지는 않지만, 꺼림칙한 소문을 들었습니다.$b$b하지만 그가 다른 꿍꿍이가 있는지 없는지, 시간이 지나면 자연히 알게 될 겁니다.', `MaleText_loc4`='必须承认，我对这个野心勃勃的小狂徒有了些兴趣。$b$b我不会急于做出判断，但我要告诉你，我已经听到了一些令人不安的谣言。$b$b时间会告诉我，他的动机是否正当。', `MaleText_loc5`='我得承認，我對這個雄心勃勃的臭屁小鬼還蠻有興趣的。$b$b但是，我不會這麼快就驟下定論，而且我也聽到了一些不利於他的傳言。$b$b時間會證明他的動機是否正直...', `MaleText_loc7`='Admito que siento curiosidad por este pequeño emprendedor.$b$bOdio los prejuicios, no te creas, pero he oído algunos rumores inquietantes.$b$bEl tiempo dirá si sus intenciones son justas.' WHERE `ID`=47233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 정말 대단한 발굴현장 아닙니까?', `MaleText_loc4`='这里的效率真高，你说呢？', `MaleText_loc5`='真是個了不起的行動，你說是吧?', `MaleText_loc7`='Menuda operación, ¿no te parece?' WHERE `ID`=47234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저게 뭐지?!', `MaleText_loc4`='这……是什么？！', `MaleText_loc5`='那...那是什麼東西?!', `MaleText_loc7`='¡¿Qué es esa cosa?!', `FemaleText_loc1`='석상이 살아 있다고?!', `FemaleText_loc4`='雕像活了？！', `FemaleText_loc5`='雕像是活的?!', `FemaleText_loc7`='¡¿La estatua está viva?!' WHERE `ID`=47235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠! 네놈이 무슨 짓을 꾸미는지 알고 있다! 절대 데스윙이 성궤를 손에 넣도록 내버려 두지는 않겠어!', `MaleText_loc4`='我知道你在找什么，司克诺兹！只要有我在，死亡之翼永远也别想得到那只箱子！', `MaleText_loc5`='我知道你在打什麼主意，舒諾茲!只要有我在，這個法櫃絕對不會落入死亡之翼的手裡!', `MaleText_loc7`='¡Sé lo que estás tramando, Schnottz! ¡Alamuerte nunca tendrá el arca, no si yo puedo evitarlo!' WHERE `ID`=47236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단한 발굴현장입니다. 이번 발굴을 지휘하고 있는 슈노츠에 대해 어떻게 생각하십니까?', `MaleText_loc4`='的确是效率惊人。你对我们主人有什么看法？', `MaleText_loc5`='的確是個了不起的行動。請問你對我們的計畫主持人有何看法?', `MaleText_loc7`='Toda una operación, desde luego. ¿Qué opinas de nuestro anfitrión?', `FemaleText_loc1`='정말 대단한 발굴현장이네요. 이번 발굴을 지휘하고 있는 슈노츠에 대해 어떻게 생각하세요?', `FemaleText_loc4`='的确是效率惊人。你对我们主人有什么看法？', `FemaleText_loc5`='的確是個了不起的行動。請問你對我們的計畫主持人有何看法?', `FemaleText_loc7`='Toda una operación, desde luego. ¿Qué opinas de nuestro anfitrión?' WHERE `ID`=47237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼음 주먹 받아라!', `MaleText_loc4`='寒冰之拳！', `MaleText_loc5`='冰霜之拳!', `MaleText_loc7`='¡Puños de hielo!' WHERE `ID`=47238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃 주먹 받아라!', `MaleText_loc4`='烈焰之拳！', `MaleText_loc5`='火焰之拳!', `MaleText_loc7`='¡Puños de fuego!' WHERE `ID`=47239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 이 별 볼 일 없는 늙은이들을 찾아온 건가?', `MaleText_loc4`='你怎么会来找我们这些衰老又疲惫的沙漠狗子？', `MaleText_loc5`='是什麼風把你吹過來找我們這群沙漠老狗的啊?', `MaleText_loc7`='¿Qué te trae a la compañía de unos viejos e inútiles perros del desierto como nosotros?' WHERE `ID`=47240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라! 용아귀 부족의 매복이다!', `MaleText_loc4`='小心——龙喉兽人有埋伏！', `MaleText_loc5`='小心!龍喉氏族的偷襲!', `MaleText_loc7`='¡Atención! ¡Emboscada de los Faucedraco!' WHERE `ID`=47241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 얘기해주십시오, 마르텍.', `MaleText_loc4`='再把那个故事为我讲一遍，马特克。', `MaleText_loc5`='再跟我說一遍那個故事，馬特克。', `MaleText_loc7`='Vuelve a contarme esa historia, Martek.', `FemaleText_loc1`='다시 한 번 얘기해주세요, 마르텍.', `FemaleText_loc4`='再把那个故事为我讲一遍，马特克。', `FemaleText_loc5`='再跟我說一遍那個故事，馬特克。', `FemaleText_loc7`='Vuelve a contarme esa historia, Martek.' WHERE `ID`=47242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖의 사막에서 그자의 부하들과 마주친 적이 있었는데, 상당히 호전적이었습니다.', `MaleText_loc4`='我已经在战场上遭遇了他的一些部下。他们的能力相当强大。', `MaleText_loc5`='我有在外頭碰過他的一些手下，他們有很強的敵意。', `MaleText_loc7`='Me he encontrado con algunos de sus sicarios en el campo. Han sido bastante hostiles.', `FemaleText_loc1`='밖의 사막에서 그자의 부하들과 마주친 적이 있었는데, 상당히 호전적이었어요.', `FemaleText_loc4`='我已经在战场上遭遇了他的一些部下。他们的能力相当强大。', `FemaleText_loc5`='我有在外頭碰過他的一些手下，他們有很強的敵意。', `FemaleText_loc7`='Me he encontrado con algunos de sus sicarios en el campo. Han sido bastante hostiles.' WHERE `ID`=47243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랄 일도 아니군요.$b$b이상한 점이 너무 많아 도저히 모른 체할 수가 없습니다...$b$b고고학 유적지에 왜 이렇게 무기가 많을까요? 또 발굴한 유물은 어떻게 될까요? 누구의 허락을 받고 이렇게 발굴이 이루어지고 있을까요?$b$b빠른 시일 내에 답이 나올 것 같지는 않지만, 아무래도 내가 직접 알아봐야겠습니다.', `MaleText_loc4`='我并不吃惊。$b$b我也不可能忽略这么多的问题……$b$b为什么一个考古发掘场里会有这么多武器？这与埋藏在地下的宝物有什么关系吗？这里的发掘人员到底效忠于谁？$b$b我还没有找到这些问题的答案。我想，我得自己去寻找真相。', `MaleText_loc5`='我一點也不意外。$b$b疑點太多了，我無法忽視...$b$b考古挖掘要帶這麼多的武器做什麼?挖出來的文物又做了什麼樣的處理?而這場考古行動又是誰授權指使的?$b$b答案並不明朗，看來我得自己去挖掘出來。', `MaleText_loc7`='No me sorprende.$b$bNo puedo pasar por alto tantas preguntas...$b$b¿Por qué tantas armas en una excavación arqueológica? ¿Qué se hace con las reliquias que se desentierran? ¿Con qué autoridad se está llevando a cabo el trabajo?$b$bLas respuestas no llegan. Supongo que tendré que descubrirlas por mí mismo.' WHERE `ID`=47244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 정 그렇다면, 너와 네 친구가 더는 우리 일을 방해하지 않도록 정리를 해줘야겠군.', `MaleText_loc4`='所以，我们必须确保你和你的朋友不会插手这件事。', `MaleText_loc5`='既然如此，我們就得確保你和你的朋友們無法插手。', `MaleText_loc7`='Bueno, en ese caso, debemos asegurarnos de que tú y tus amigos desaparescan del paisaje.' WHERE `ID`=47245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니라고!$b$b저리 꺼져!$b$b내가 정신을 집중하고 있는 게 안 보이나?', `MaleText_loc4`='白痴！$b$b快滚开！$b$b难道你看不出来，我正在集中精神吗？', `MaleText_loc5`='白癡!$b$b給我走開!你看不出來我正在想事情嗎?', `MaleText_loc7`='¡Idiota!$b$b¡Largo de aquí!$b$b¿Acaso no ves que estoy concentrándome?' WHERE `ID`=47246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 고마워하며 발을 구릅니다.', `MaleText_loc4`='石巨人发出“隆隆”的声音，仿佛是在表示感谢。', `MaleText_loc5`='岩石怪轟隆隆地表達謝意。', `MaleText_loc7`='El guijarro hace un ruido sordo de gratitud.' WHERE `ID`=47247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 잠시 어리둥절해 하더니 곧 도망갑니다.', `MaleText_loc4`='石巨人显示出困惑的神情，过了一会儿，他跑开了。', `MaleText_loc5`='岩石怪迷惘了一陣子，然後才跑開。', `MaleText_loc7`='El guijarro parece confuso durante un momento antes de salir corriendo.' WHERE `ID`=47248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 고맙다는 표시로 수정을 달그락거립니다.', `MaleText_loc4`='石巨人敲击着他的水晶，表达谢意。', `MaleText_loc5`='岩石怪發出水晶敲擊的聲響，向你致謝。', `MaleText_loc7`='El guijarro hace repicar sus cristales en señal de agradecimiento.' WHERE `ID`=47249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 신기하다는 듯 당신을 올려다봅니다.', `MaleText_loc4`='石巨人带着怀疑的神情看着你。', `MaleText_loc5`='岩石怪疑惑地抬頭看著你。', `MaleText_loc7`='El guijarro alza la vista y te observa con curiosidad.' WHERE `ID`=47250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 웃음을 지으려고 하자 뭔가 깨지는 소리가 크게 들립니다.', `MaleText_loc4`='石巨人尝试着露出微笑，你听到一阵响亮的岩石撞击声。', `MaleText_loc5`='岩石怪咧嘴微笑，你聽到砰地一聲巨響。', `MaleText_loc7`='Oyes un sonoro rechinar cuando el guijarro intenta sonreír.' WHERE `ID`=47251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 행복에 겨워 쿵 하고 바닥에 쓰러집니다.', `MaleText_loc4`='石巨人高兴地击打着地面。', `MaleText_loc5`='岩石怪高興地在地上猛踩。', `MaleText_loc7`='El guijarro golpea el suelo con alegría.' WHERE `ID`=47252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 고맙다며 자갈 부딪치는 소리를 크게 냅니다.', `MaleText_loc4`='石巨人发出一阵满足而沉重的叹息声。', `MaleText_loc5`='岩石怪發出低沉的巨響，表達謝意。', `MaleText_loc7`='El guijarro ofrece un largo y pedregoso suspiro de agradecimiento.' WHERE `ID`=47253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌멩이 정령이 자유를 되찾은 기쁨에 멀리 내달립니다.', `MaleText_loc4`='石巨人兴奋地奔跑着，为自己重获自由而激动不已。', `MaleText_loc5`='新獲得的自由讓岩石怪欣喜萬分，蹦蹦跳跳地走遠了。', `MaleText_loc7`='El guijarro corretea hacia el horizonte, emocionado por su recién encontrada libertad.' WHERE `ID`=47254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마르텍, 얘기를 방해한 건 미안하지만, 사실 내가 자네 얘기를 백 배는 더 재밌게 만들어 준 거라고. 내가 한잔 살게.', `MaleText_loc4`='抱歉打扰你，马特克。虽然你已经得到了承认……是我让你的故事精彩了五十倍。下次也应该让我露露脸了。', `MaleText_loc5`='抱歉打斷了你，馬特克。但是你得承認...你的故事被我講了至少精采五十倍。好啦，下次喝酒換我請客。', `MaleText_loc7`='Siento la interrupción, Martek, pero tienes que admitirlo... He hecho que tu historia sea cincuenta veces mejor. Invito a la siguiente ronda.' WHERE `ID`=47255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글럽톡이 너희한테 비전 마력 보여준다!', `MaleText_loc4`='格拉布托克让你看看奥术的力量！', `MaleText_loc5`='格魯巴托克讓你看看秘法的力量!', `MaleText_loc7`='¡Glubtok te mostrará el poder del arcano!' WHERE `ID`=47256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 건배합시다, 친구여!$b$b여기 펼쳐진 광경을 눈여겨보십시오.$b$b아시다시피, 이 땅은 여러 세기 동안 감춰져 있었습니다.', `MaleText_loc4`='听我说！朋友，举起望远镜！$b$b好好看看这里。$b$b要知道，在漫长的岁月里，这个地方一直被隐藏着。', `MaleText_loc5`='注意!朋友，舉起酒杯!$b$b好好看清楚這裡。$b$b你知道，這整塊地方已經隱藏了不知道多少年。', `MaleText_loc7`='¡Voto a bríos! ¡Brindemos, amigo!$b$bAdmira las vistas.$b$bToda esta región ha estado oculta durante siglos, ¿sabes?' WHERE `ID`=47257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 초대한 저 사람에 대해 뭐 알고 계신 것이 있습니까?', `MaleText_loc4`='你对我们慷慨的主人有些什么了解，阁下？', `MaleText_loc5`='先生，請問你對我們這位大方的東道主瞭解多少?', `MaleText_loc7`='¿Qué sabes de nuestro generoso anfitrión, señor?', `FemaleText_loc1`='우릴 초대한 저 사람에 대해 뭐 알고 계신 것이 있나요?', `FemaleText_loc4`='你对我们慷慨的主人有些什么了解，阁下？', `FemaleText_loc5`='先生，請問你對我們這位大方的東道主瞭解多少?', `FemaleText_loc7`='¿Qué sabes de nuestro generoso anfitrión, señor?' WHERE `ID`=47258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금껏 저 사람이 발굴한 보물을 한 번 보십시오!$b$b그가 사용하는 방법은 딱히 마음에 들지 않을 때도 있지만, 결과만큼은 부정할 수 없습니다...$b$b우울한 생각은 하지 말아야지요. 그건 신사에게 적합한 태도가 아니랍니다.', `MaleText_loc4`='看看他积聚的财富！$b$b他的手段经常会让我感到不舒服，但这个结果却是无法否认的……$b$b不要去想那些令人不快的事情了。要知道，这样也不礼貌。', `MaleText_loc5`='你看看，他累積了多少財寶!$b$b雖然我對他的手段並不完全認同，但是這樣的成果還真是無法否認...$b$b最好別動什麼壞念頭，朋友。你知道的，那樣很沒禮貌。', `MaleText_loc7`='¡Bueno, mira los tesoros que ha acumulado!$b$bNo siempre me siento cómodo con sus métodos, pero los resultados son innegables...$b$bMejor no demorarnos en pensamientos desagradables. Es de mala educación, ya sabes.' WHERE `ID`=47259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 무슨 일로 여기까지 오셨습니까?', `MaleText_loc4`='嗯，你怎么会来到这里的？', `MaleText_loc5`='嗯...是什麼風把你吹到這邊來的?', `MaleText_loc7`='Mmm, ¿y qué te trae por estos lares?', `FemaleText_loc1`='저, 무슨 일로 여기까지 오셨나요?', `FemaleText_loc4`='嗯，你怎么会来到这里的？', `FemaleText_loc5`='嗯...是什麼風把你吹到這邊來的?', `FemaleText_loc7`='Mmm, ¿y qué te trae por estos lares?' WHERE `ID`=47260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미래를 적절히 예측했기 때문이지요!$b$b저기 우리 작달막한 모피 장수 친구가 보물을 충분히 파내면 아제로스에서 가장 영향력 있는 인물이 되지 않겠습니까?$b$b그런 일을 대비해서 여기서 얼굴도장을 확실히 찍으려는 거지요.', `MaleText_loc4`='好好想想，我亲爱的$g男孩:女孩;！$b$b一旦我们野心勃勃的小毛皮商发掘出足够的财宝，他就会成为艾泽拉斯最有影响力的角色。$b$b如果这一天到来，我们都会有一个令人满意的地位。', `MaleText_loc5`='想一想，親愛的$g孩子:女孩;!$b$b等我們這位熱情的小皮貨商挖到足夠的財寶，他就會晉身艾澤拉斯最有影響力的人。$b$b到那時候，我們也都會跟著升官發財。', `MaleText_loc7`='¡La especulación, $gquerido amigo:querida amiga;!$b$bEn cuanto nuestro querido comerciante haya desenterrado suficientes tesoros, será una de las figuras más influyentes de Azeroth.$b$bTodos estaremos bien situados cuando llegue el momento.' WHERE `ID`=47261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 아직 우릴 보지 못했소. 서두르시오. 아직은 놈들을 막을 수 있소!', `MaleText_loc4`='他们没有注意到我们。赶快，也许我们还能阻止他们！', `MaleText_loc5`='他們還沒注意到我們。動作快，說不定我們還來得及阻止他們!', `MaleText_loc7`='Aún no nos han descubierto. ¡Date prisa, a lo mejor todavía podemos detenerlos!' WHERE `ID`=47262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만날 줄 알았다, 슈노츠.', `MaleText_loc4`='我们应该会再见的，司克诺兹。', `MaleText_loc5`='我就知道我會再碰到你，舒諾茲。', `MaleText_loc7`='Imaginé que te vería de nuevo, Schnottz.' WHERE `ID`=47263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠, 어딜 도망가려고!', `MaleText_loc4`='没这么快，司克诺兹！', `MaleText_loc5`='沒那麼快，舒諾茲!', `MaleText_loc7`='¡No tan rápido, Schnottz!' WHERE `ID`=47264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히!', `MaleText_loc4`='永远！', `MaleText_loc5`='永永遠遠!', `MaleText_loc7`='¡Perrrmanentemente!' WHERE `ID`=47265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남아 그 잘난 성궤를 만날 일은 없을 거다, 존스!', `MaleText_loc4`='别想活着看到你那个宝贵的箱子了，琼斯！', `MaleText_loc5`='你沒那條命可以看到你心愛的法櫃了，瓊斯!', `MaleText_loc7`='¡No vivirrrás lo suficiente para verrr el arka, Jones!' WHERE `ID`=47266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 여기야말로 정말 멋진 곳이 아니겠습니까?$b$b마음이 통하는 사람들과 미지의 세계를 여행한다니...$b$b이보다 나은 일이 어디 있을까요?', `MaleText_loc4`='不就是这里吗？$b$b与志同道合的伙伴一同探索这个世界从未被开发过的角落？$b$b还有什么能比这样更好的？', `MaleText_loc5`='這不就是我們夢寐以求的地方嗎?$b$b跟有同樣興趣的夥伴一起冒險遊歷世界各個不為人知的角落?$b$b還有什麼比這更好的事情?', `MaleText_loc7`='¿A que no hay nada mejor?$b$bExplorar los rincones más recónditos del mundo con compañeros de gustos similares...$b$b¿Qué más se podría pedir?' WHERE `ID`=47267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그렇습니다! 그런데 여기 사령관과는 어떻게 만나셨습니까?', `MaleText_loc4`='的确！你是怎样找到元首的，朋友？', `MaleText_loc5`='的確!然後你是怎樣找到指揮官的，朋友?', `MaleText_loc7`='¡Ya lo creo! ¿Y qué piensas del Comandante, amigo?', `FemaleText_loc1`='정말 그래요! 그런데 여기 사령관과는 어떻게 만나셨지요?', `FemaleText_loc4`='的确！你是怎样找到元首的，朋友？', `FemaleText_loc5`='的確!然後你是怎樣找到指揮官的，朋友?', `FemaleText_loc7`='¡Ya lo creo! ¿Y qué piensas del Comandante, amigo?' WHERE `ID`=47268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생각에는 조금 지나치게 활기가 넘치는 것 같긴 합니다만, 사실 세상에는 그런 사람도 필요한 법이지요.$b$b그런데 그건 왜 물어보시는 겁니까?
', `MaleText_loc4`='对于我来说，他有些太活泼了。但我想，这个世界需要各种各样的人。$b$b你为什么要问这个？', `MaleText_loc5`='我是覺得他有點過於激動。$b$b但我想，一樣米養百種人。$b$b你問這幹嘛?', `MaleText_loc7`='Es un poco efusivo para mi gusto, pero en el mundo tiene que haber de todo, supongo.$b$b¿Por qué lo preguntas?' WHERE `ID`=47269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요석 거대괴수를 파괴해야 합니다!', `MaleText_loc4`='摧毁黑曜石巨像！', `MaleText_loc5`='摧毀黑曜巨像!', `MaleText_loc7`='¡Destruye el coloso obsidiana!', `FemaleText_loc1`='흑요석 거대괴수를 파괴해야 합니다!', `FemaleText_loc4`='摧毁黑曜石巨像！', `FemaleText_loc5`='摧毀黑曜巨像!', `FemaleText_loc7`='¡Destruye el coloso obsidiana!' WHERE `ID`=47270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이나, 여기 경비병들도... 조금 지나치게 진지한 모습입니다.', `MaleText_loc4`='他的部队，这些卫兵……看上去倒是有些强大。', `MaleText_loc5`='他的部隊，這些守衛...氣氛是有點過於緊張。', `MaleText_loc7`='Sus tropas, estos guardias... Todo parece un poco intenso.', `FemaleText_loc1`='병사들이나, 여기 경비병들도... 조금 지나치게 진지한 모습이지요.', `FemaleText_loc4`='他的部队，这些卫兵……看上去倒是有些强大。', `FemaleText_loc5`='他的部隊，這些守衛...氣氛是有點過於緊張。', `FemaleText_loc7`='Sus tropas, estos guardias... Todo parece un poco intenso.' WHERE `ID`=47271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 말씀이신지 알겠습니다.$b$b있잖아요, 전 그저 시야를 조금 넓히고 싶어서 여기까지 왔을 뿐입니다. 세상을 두 눈으로 보고 뭐 그런 목적으로요.$b$b다른 사람들의 일에는 크게 신경 쓰고 싶지 않습니다.$b$b그래도 만나뵙게 되어 반가웠습니다.
', `MaleText_loc4`='我明白你的意思，我想……$b$b说实话，我来这里只是因为想要看看这个世界和各种奇异的事物，让我的知识面扩大一些。$b$b对于其他人的事情，我并不是很关心。$b$b不过还是很高兴见到你。', `MaleText_loc5`='我想，我大概瞭解你的意思...$b$b我來這裡只是想擴展一下我的眼界。你知道，看看這個世界什麼的。$b$b其實我不是很在乎其他人發生了什麼事情。$b$b不過，很高興認識你。', `MaleText_loc7`='Creo que sé a qué te refieres...$b$bLa verdad, solo estoy aquí porque quiero expandir mis horizontes, ver mundo y esas cosas.$b$bNo me preocupan mucho los asuntos de los demás.$b$bPero me alegro de conocerte.' WHERE `ID`=47272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오르는 빛 광선을 피해!', `MaleText_loc4`='不要碰到那些高热光线！', `MaleText_loc5`='避開那個光束!', `MaleText_loc7`='¡Evitad los rayos de luz abrasadora!' WHERE `ID`=47273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='강렬하게 아름다운 날씨 아닌가요, $c님?', `FemaleText_loc4`='这里的风景真美，不是吗，$c？', `FemaleText_loc5`='此地氣候甚佳，你說是吧，$c?', `FemaleText_loc7`='Un tiempo exquisito, ¿no te parece, $n?' WHERE `ID`=47274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 나가야겠어!', `MaleText_loc4`='我要离开这里！', `MaleText_loc5`='我要離開這裡!', `MaleText_loc7`='¡Yo me largo!', `FemaleText_loc1`='당장 나가야겠어!', `FemaleText_loc4`='我要离开这里！', `FemaleText_loc5`='我要離開這裡!', `FemaleText_loc7`='¡Yo me largo!' WHERE `ID`=47275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇습니다. 여기서 즐겁게 지내고 계십니까?', `MaleText_loc4`='啊，是的。在这里的时光你是怎样渡过的？', `MaleText_loc5`='啊，是的。你在這裡過得還愉快嗎?', `MaleText_loc7`='Ah, sí. ¿Qué tal te lo estás pasando por aquí?', `FemaleText_loc1`='아, 그렇네요. 여기서 즐겁게 지내고 계신가요?', `FemaleText_loc4`='啊，是的。在这里的时光你是怎样渡过的？', `FemaleText_loc5`='啊，是的。你在這裡過得還愉快嗎?', `FemaleText_loc7`='Ah, sí. ¿Qué tal te lo estás pasando por aquí?' WHERE `ID`=47276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 정말 멋졌어요!$b$b사령관님은 아주 자신감에 넘치시고, 그리고 그 말투는 또 어찌나 멋진지! 솔직히 말해서 정말 매력적인 분이세요.$b$b그 분 결혼하셨는지 혹시 알고 계세요?', `FemaleText_loc4`='实在是太棒了！$b$b元首是如此自信，还有他的声音！必须承认，他的样子真是有魅力。$b$b你知道他结婚了吗？', `FemaleText_loc5`='哦，真的很棒!$b$b指揮官好有自信!還有他的口音，我得承認，實在是太迷人了。$b$b你知道他結婚了沒?', `FemaleText_loc7`='¡Es estupendo!$b$bEl Comandante está muy seguro de sí mismo, ¡y qué acento! Admito que es cautivador.$b$b¿Sabes si está casado?' WHERE `ID`=47277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 잘 모르겠습니다. 그 사람에 대해서 더 말씀해주실 건 없습니까?', `MaleText_loc4`='嗯……我不确定。关于他，你还能告诉我一些什么事情？', `MaleText_loc5`='嗯...我不曉得。還能告訴我關於他的什麼事情嗎?', `MaleText_loc7`='Eh... No sé. ¿Qué más me puedes contar sobre él?', `FemaleText_loc1`='어... 잘 모르겠네요. 그 사람에 대해서 더 말씀해주실 건 없나요?', `FemaleText_loc4`='嗯……我不确定。关于他，你还能告诉我一些什么事情？', `FemaleText_loc5`='嗯...我不曉得。還能告訴我關於他的什麼事情嗎?', `FemaleText_loc7`='Eh... No sé. ¿Qué más me puedes contar sobre él?' WHERE `ID`=47278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 지역에서 발굴된 유물에 신비한 힘이 깃들어 있다는 소문이 돌더라고요!$b$b사령관님은 아마 그런 유물에 매력을 느끼시는 것 같아요...', `FemaleText_loc4`='有传闻说，这里的一些古物具有神秘的力量！$b$b他似乎已经对这些东西彻底着迷了……', `FemaleText_loc5`='據說這邊的某些遺物藏有神秘的力量!$b$b他好像對這些東西十分著迷...', `FemaleText_loc7`='¡Dicen que algunas reliquias de la zona contienen un poder místico!$b$bParece que esas cosas le fascinan...' WHERE `ID`=47279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관이 모집하고 있는 부대는 어떻습니까? 지나치게 규모가 크지 않습니까?', `MaleText_loc4`='你怎么看他手下的部队？看起来很厉害吧？', `MaleText_loc5`='你對他所帶來的這些部隊有何看法?是不是有點太過頭了呢?', `MaleText_loc7`='¿Qué piensas de las tropas que está armando? Es un poco excesivo, ¿no?', `FemaleText_loc1`='사령관이 모집하고 있는 부대는 어때요? 지나치게 규모가 크지 않나요?', `FemaleText_loc4`='你怎么看他手下的部队？看起来很厉害吧？', `FemaleText_loc5`='你對他所帶來的這些部隊有何看法?是不是有點太過頭了呢?', `FemaleText_loc7`='¿Qué piensas de las tropas que está armando? Es un poco excesivo, ¿no?' WHERE `ID`=47280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송해요, $c님.$b$b그런 문제는 잘 몰라서요. 솔직히 말해서, 그다지 잘 알고 싶지도 않거든요.', `FemaleText_loc4`='很抱歉，$c。$b$b对此我真的没什么了解，所以我没什么可说的。', `FemaleText_loc5`='很抱歉，$c。$b$b我真的所知不多，無法跟你討論這個話題。而且我希望這個話題就此打住。', `FemaleText_loc7`='Lo siento, $c.$b$bNo sé lo bastante sobre esas cosas como para hablar de ellas, y prefiero que siga así.' WHERE `ID`=47281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디, 자네가 그렇게 소문이 자자한 $r $c인가? 응?', `MaleText_loc4`='你就是我经常听说的那个$r$c？', `MaleText_loc5`='這位就是我耳聞已久、大名鼎鼎的$r$c嗎?', `MaleText_loc7`='Así que $geste es el:esta es la; $r $c de la que tanto he oído hablarrr, ¿hmmm?' WHERE `ID`=47282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건을 밝혀라, $r.', `MaleText_loc4`='说说你的情况，$r。', `MaleText_loc5`='說明你的來意，$r。', `MaleText_loc7`='Di qué te trrrae por aquí, $r.' WHERE `ID`=47283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 너를 지켜보고 있다, $r...', `MaleText_loc4`='我们正在注意你，$r……', `MaleText_loc5`='我們在看著你，$r...', `MaleText_loc7`='Te obserrrfamos, $r...' WHERE `ID`=47284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 항상 지켜본다고!', `MaleText_loc4`='……一直在注意！', `MaleText_loc5`='...隨時隨地都在看!', `MaleText_loc7`='...¡siemprrre obserfamos!' WHERE `ID`=47285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='졸트릭과 멀리 떨어져 있어 싸울 수 없다면, 비룡 올라타기! 능력을 사용하십시오:

|Tinterface\\Icons\\ability_vehicle_launchplayer.blp:64|t', `MaleText_loc4`='如果佐尔奇克不在你的攻击范围内，就使用你的“跃向幼龙！”技能：

|TInterface\\Icons\\ability_vehicle_launchplayer.blp:64|t', `MaleText_loc5`='若是你無法從遠處迎戰佐特里克，那就使用你的跳換飛龍!技能:

