UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용의 입은 여기 황야의 땅에 얼라이언스가 거점 확보를 위해 처음으로 자리 잡은 장소입니다. 스톰윈드와 던 모로 사이에 있음에도 황야의 땅은 예전부터 호드의 영토였지요.$b$b이제 변화를 가져오려면 우리의 의지를 확고히 다져야 해요. 신 카르가스를 공격 중인 용들도 우리가 목적을 달성하는 데 방해가 되지는 않습니다.', `FemaleText_loc4`='巨龙峡口是联盟在荒芜之地建立的第一个立足点。虽然荒芜之地位于暴风城和丹莫罗中间，但在传统上，它一直是部落的势力范围。$b$b现在这一情况已经发生了改变，我们需要确立自己的权属地位。当然，那头龙对新卡加斯的进攻也不会干扰我们的计划。', `FemaleText_loc5`='龍之口的設置是為了讓聯盟在荒蕪之地能有個真正的立足之處。荒蕪之地雖然位於暴風城和丹莫洛之間，過去卻一直是部落的地盤。$b$b如果要改變這個現狀的話，我們得先開始強化我們在此地的影響力。當然，龍群攻擊新卡加斯的事件對我們的目標也並非沒有幫助。', `FemaleText_loc7`='Boca del Dragón se estableció para darle a la Alianza su primera base de verdad en las Tierras Inhóspitas. A pesar de su emplazamiento entre Ventormenta y Dun Morogh, tradicionalmente las Tierras Inhóspitas han sido territorio de la Horda.$b$bSi queremos que eso cambie algún día, tenemos que empezar a hacernos respetar. Huelga decir que los ataques de los dragones contra Nuevo Kargath no le vienen mal a nuestra causa.' WHERE `ID`=47287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 검은용군단이 신 카르가스에 공격을 퍼붓고 있다는 소식에 당신만큼 많이 놀랐습니다. 고른은 고집이 세서 누구의 도움도 받지 않으려 합니다.$b$b그렇다고 해도, 고위 검사관 블러드워처 님은 제게 일이 지저분해지지 않도록 유심히 지켜보라고 지시하셨습니다.', `MaleText_loc4`='得知黑龙要与新卡加斯对抗，我像你一样感到惊讶。高恩非常顽固，拒绝任何人的帮助。$b$b即使这样，高阶考察者泰瑟兰·血望者还是要求我时刻注意新卡加斯的情况，以确保局势对我们不会太……糟糕。', `MaleText_loc5`='我和你一樣驚訝，沒想到黑龍竟然會攻擊新卡加斯。而且高恩非常頑固，竟然拒絕了任何的協助。$b$b即使如此，高階審查員血腥看守者還是要求我只能在遠處監看，以確保事情不會變得太...難看。', `MaleText_loc7`='Me quedé tan sorprendido como tú al descubrir que el Vuelo Negro ejecuta su voluntad contra Nuevo Kargath. Gorn es muy terco y rechaza cualquier ayuda.$b$bEn cualquier caso, el alto examinador Mirasangre me ha pedido que observe desde lejos, para asegurarnos de que las cosas no se ponen... feas.' WHERE `ID`=47288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라제인의 돌난로 공격 계획을 반드시 저지해야 하네.$B$B테라제인이 돌난로를 공격하면 세계 기둥 중간 파편이 그녀의 손에 들어갈 거야.', `MaleText_loc4`='我们必须阻止塞拉赞恩的军队进攻巨石之炉。$B$B否则他们就有可能偷走世界之柱的中部残片。', `MaleText_loc5`='我們必須阻止瑟拉贊恩的部隊攻擊石爐。$B$B要是他們成功了，他們將會竊走世界之柱的中間碎片。', `MaleText_loc7`='Debemos impedir que las tropas de Therazane ataquen el Hogar Pétreo.$b$bSi lo hacen, robarán el fragmento central del Pilar del Mundo.' WHERE `ID`=47289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 힘이 빠져나갑니다...', `MaleText_loc4`='英雄们！我的力量消褪了……', `MaleText_loc5`='英雄們!我的力量在衰退....', `MaleText_loc7`='Héroes, mi poder decae...' WHERE `ID`=47290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 약해지는 걸로 보이느냐? 멍청한 놈!', `FemaleText_loc4`='你以为就这么简单？愚蠢！', `FemaleText_loc5`='你以為這樣就佔了上風?愚蠢!', `FemaleText_loc7`='¿Crees que es debilidad? ¡Tonto!' WHERE `ID`=47291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만! 알의 생명력을 이렇게 빨아들이면 우리 연구가 몇 달은 늦춰질 것이다. 너희를 상대하는 데 이런 방법을 쓴다는 걸 영광으로 여겨라. 이제 죽어라!', `FemaleText_loc4`='够了！汲取这力量之源将使几个月的努力白费。你们应该为自己担得起这份损耗而感到自豪！现在……死吧！', `FemaleText_loc5`='夠了!使用這個力量泉源將讓我們的計畫延遲幾個月。你應該為讓我消耗這個力量而感到光榮。現在...死吧!', `FemaleText_loc7`='¡Suficiente! Recurrir a esta fuente nos retrasará meses. Siéntanse honrados de merecer tal costo. Ahora... ¡mueran!' WHERE `ID`=47292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈앞이 흐려지는군요... 이걸 받으십시오. 마지막 힘을 다했습니다. 부디 승리하십시오. 저를 위해... 이 세상을 위해 복수해 주십시오...', `MaleText_loc4`='火焰即将熄灭，勇士们……带上我最后的力量。继承我未竟的事业。替我复仇。替这个世界复仇……', `MaleText_loc5`='火已經快熄滅了，勇士們...拿著這個，我剩餘的力量。從我倒下的地方站起。為我報仇...為世界報仇...', `MaleText_loc7`='El fuego se apaga, campeones... Tomen, el poder que me queda. Triunfen donde fracasé. Vénguenme. Venguen al mundo...' WHERE `ID`=47293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 희생자로군! 이 녀석과는 거의 일을 끝냈던 차다.', `MaleText_loc4`='又一个白白牺牲的家伙！我几乎已经能让他开口了。', `MaleText_loc5`='新的受害者!反正我跟這傢伙也快玩完了。', `MaleText_loc7`='¡Una nueva víctima! ¡Yo casi haber terminado ya con esta de todas maneras!' WHERE `ID`=47294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 영웅 $n|1을;를; 맞이하라! 만세!', `MaleText_loc4`='全体向$n欢呼！万岁！', `MaleText_loc5`='所有人歡呼，$n!喔耶!', `MaleText_loc7`='¡Tres hurras por $n!' WHERE `ID`=47295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세!', `MaleText_loc4`='万岁！', `MaleText_loc5`='喔耶!', `MaleText_loc7`='¡Hurra!' WHERE `ID`=47296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장하다!', `MaleText_loc4`='的确！', `MaleText_loc5`='沒錯!', `MaleText_loc7`='¡Eso es!' WHERE `ID`=47297;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐 필요하신 거라도 있습니까?', `FemaleText_loc4`='有什么需要吗？', `FemaleText_loc5`='需要些什麼嗎?', `FemaleText_loc7`='¿Necesitas algo?' WHERE `ID`=47298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황야의 땅으로 가는 배를 타고 싶습니다.', `MaleText_loc4`='我需要一艘前往荒芜之地的小船。', `MaleText_loc5`='請讓我搭船到荒蕪之地，謝謝。', `MaleText_loc7`='Un viaje en barco hasta las Tierras Inhóspitas, por favor.', `FemaleText_loc1`='황야의 땅으로 가는 배를 타고 싶어요.', `FemaleText_loc4`='我需要一艘前往荒芜之地的小船。', `FemaleText_loc5`='請讓我搭船到荒蕪之地，謝謝。', `FemaleText_loc7`='Un viaje en barco hasta las Tierras Inhóspitas, por favor.' WHERE `ID`=47299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하고, 잠자고, 폭파하고! 이보다 더 행복한 삶은 없을 거라고.', `MaleText_loc4`='我们钓鱼，我们睡觉，我们炸飞各种东西。还有什么生活能比这样更好？', `MaleText_loc5`='我們整天釣魚、睡覺、爆炸東西。還有什麼比這更好的?', `MaleText_loc7`='Pescamos, dormimos y volamos cosas por los aires. ¿Hay algo mejor?' WHERE `ID`=47300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동부 역병지대로 가는 배가 있습니까?', `MaleText_loc4`='我能乘船去东瘟疫之地吗？', `MaleText_loc5`='請問我可以搭個便船到東瘟疫之地嗎?', `MaleText_loc7`='¿Podría viajar en barco hasta las Tierras de la Peste del Este, por favor?', `FemaleText_loc1`='동부 역병지대로 가는 배가 있나요?', `FemaleText_loc4`='我能乘船去东瘟疫之地吗？', `FemaleText_loc5`='請問我可以搭個便船到東瘟疫之地嗎?', `FemaleText_loc7`='¿Podría viajar en barco hasta las Tierras de la Peste del Este, por favor?' WHERE `ID`=47301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='6분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在六分钟后到达。', `MaleText_loc5`='飛艇將在六分鐘後抵達。', `MaleText_loc7`='Llegada del zepelín en seis minutos.' WHERE `ID`=47302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在五分钟后到达。', `MaleText_loc5`='飛艇將在五分鐘後抵達。', `MaleText_loc7`='Llegada del zepelín en cinco minutos.' WHERE `ID`=47303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='4분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在四分钟后到达。', `MaleText_loc5`='飛艇將在四分鐘後抵達。', `MaleText_loc7`='Llegada del zepelín en cuatro minutos.' WHERE `ID`=47304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在三分钟后到达。', `MaleText_loc5`='飛艇將在三分鐘後抵達。', `MaleText_loc7`='Llegada del zepelín en tres minutos.' WHERE `ID`=47305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在两分钟后到达。', `MaleText_loc5`='飛艇將在二分鐘後抵達。', `MaleText_loc7`='Llegada del zepelín en dos minutos.' WHERE `ID`=47306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 안에 비행선이 도착합니다.', `MaleText_loc4`='飞艇将在一分钟后到达。1分钟。', `MaleText_loc5`='飛艇將在一分鐘後抵達。一分鐘', `MaleText_loc7`='Llegada del zepelín en un minuto. Un minuto.' WHERE `ID`=47307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 듀로타의 창을 기다리나? 자넨 축복받은 거라고, 호드 병사!', `MaleText_loc4`='你这是要准备登上杜隆塔尔之矛号，对吧？你就要遭人嫉妒了，部落士兵！', `MaleText_loc5`='要來搭乘杜洛塔之矛，是吧?部落陸戰隊員，所有的人都會嫉妒你!', `MaleText_loc7`='Vas a subir a la Lanza de Durotar, ¿eh? ¡Te envidio, aeronauta de la Horda!' WHERE `ID`=47308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항공학의 역사가 다시 쓰이는 새 시대에, 지평선을 가르고 하늘을 뚫는 선풍적인 비행선을 경험하는 거란 말이지.', `MaleText_loc4`='你们的新飞艇将飞跃地平线，开启航空学上的新纪元。', `MaleText_loc5`='你即將在地平線上劃開新局，登上航空科技創新的嶄新紀元。', `MaleText_loc7`='Estás a punto de rasgar el horizonte a bordo de una nueva era sensacional de innovaciones aeronáuticas.' WHERE `ID`=47309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로타의 창은 거창하고 비효율적인 "물리 법칙"이란 놈과 예산을 가차없이 무시하는 대담한 구조를 지니고 있지.', `MaleText_loc4`='真正的工程学根本不会在乎什么财政预算和那些愚蠢而低效率的“物理法则”。', `MaleText_loc5`='大膽採用最激進的工程技術，完全不顧預算的考量，以及那些沒效率又累贅的「物理法則」。', `MaleText_loc7`='Se ha diseñado arriesgadamente con una despreocupación implacable hacia los límites presupuestarios y esos obstáculos poco eficientes que llamamos "leyes de la física".' WHERE `ID`=47310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 도착하기를 기다리는 동안, 내 조수와 함께 이 놀라운 비행선의 기능 몇 개를 가볍게 보여주지.', `MaleText_loc4`='在你们等待它的到来时，我和我的助手会先讲解一下这艘非凡航空器的特别功能。', `MaleText_loc5`='在你等候它的到來時，我和助理將簡單扼要地為你展示這艘超級飛艇的幾個驚人特點。', `MaleText_loc7`='Mientras aguardas su llegada, mi ayudante y yo te explicaremos en breve algunas de las características de esta nave prodigiosa.' WHERE `ID`=47311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 알다시피, 공기에는 무게가 없다고. 따라서 공기보다 가벼운 비행선을 만들려면 규칙을 몇 개 무시해야 하지.', `MaleText_loc4`='大家都知道，空气的重量极小。所以，为了建造一艘比空气还要轻的飞船，我们就必须改变一些规则。', `MaleText_loc5`='你知道，空氣是沒有重量的。所以要做出一艘比空氣還輕的飛船，我們就得打破幾個常規。', `MaleText_loc7`='Como bien sabes, el aire no pesa nada. Así que para crear una nave más ligera que el aire hemos tenido que romper algunas reglas.' WHERE `ID`=47312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듀로타의 창에는 엄청나게 열을 가한 가연성 가스가 비행선이 터질 만큼 꽉꽉 채워져 있다고.', `MaleText_loc4`='杜隆塔尔之矛号里面充满了过热的易燃气体。', `MaleText_loc5`='杜洛塔之矛灌著滿到快爆開的超高熱可燃性氣體。', `MaleText_loc7`='La Lanza de Durotar está llena a rebosar de un gas sobrecalentado e inflamable.' WHERE `ID`=47313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 기술자들은 비행선이 지닌 높은 고도에서의 불안정성, 그리고 그 결과로 생긴 비용 절감 효과를 톡톡히 누렸지.', `MaleText_loc4`='锈水工程师们充分利用了这种气体固有的高度不稳定性和低成本优点。', `MaleText_loc5`='污水企業的工程師們就是利用它位在高空時的不穩定性，以及因此而產生的低成本。', `MaleText_loc7`='Los ingenieros Pantoque han sacado provecho a su inestabilidad inherente a gran altitud y el bajo coste resultante.' WHERE `ID`=47314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 언제 폭발할지 모를 가스의 불안정성을 완화하려고 엄청난 압력을 적용했어.', `MaleText_loc4`='我们对这种气体施加巨大的压强，降低了这种气体的爆炸性。', `MaleText_loc5`='我們利用「超」高壓的封存處理，降低了氣體可能會爆炸的不穩定性。', `MaleText_loc7`='Hemos mitigado la inestabilidad explosiva del gas sometiéndolo a una presión INMENSA.' WHERE `ID`=47315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러기 위해선 지속적으로 가스를 분출하는 안전밸브를 몇 개 없애야 했고 말이야.', `MaleText_loc4`='为了实现这一点，我们还去掉了一些总是让气体喷出去的安全阀。', `MaleText_loc5`='但是為了這麼做，我們不得不拿掉幾個老是爆開的安全閥門。', `MaleText_loc7`='Para hacerlo fue necesario eliminar unas cuantas válvulas de seguridad que no dejaban de saltar.' WHERE `ID`=47316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 맞아. 그래야지. 주행 거리와 탑재량을 극대화하려고, 최신식 엔진과 전통적이라고는 할 수 없는 특이한 혼합 로켓 연료를 사용했지.', `MaleText_loc4`='哦，是了。为了让飞艇的续航力和有效载荷达到最大化，我们还为它殿堂级的伟大引擎调配了一种非正统的火箭燃料。', `MaleText_loc5`='哦，對了。為了最大化它的航程和裝載量，我們還為最尖端的引擎調配了一種非正統的火箭燃料。', `MaleText_loc7`='Ya lo creo. Para maximizar tanto el alcance como la carga, hemos ideado una mezcla poco ortodoxa de combustibles de cohete para motores de última generación.' WHERE `ID`=47317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워낙에 고밀도 에너지를 지닌 물체라서 아주 작은 자극에도 연소하기 시작한다고.', `MaleText_loc4`='这种燃料中蕴含着极为强大的能量，只要一点刺激，就有可能发生爆燃。', `MaleText_loc5`='它的濃縮能量非常強大，只要一丁點的刺激就會燃燒。', `MaleText_loc7`='Está tan denso de energía que puede prender fuego a la menor provocación.' WHERE `ID`=47318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매우 불안정한 물질이기 때문에 함부로 움직이면 안 된다고. 엄... 날아가는 것도 물론이고.', `MaleText_loc4`='这种物质有很强的爆炸性，它也许不应该被挪动，更不要说是……飞行了。', `MaleText_loc5`='這個東西非常不穩定，最好別亂動它。更別說是...帶著它飛來飛去了。', `MaleText_loc7`='Esta sustancia es tan volátil que probablemente no debería moverse... y mucho menos echar a volar.' WHERE `ID`=47319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 자네가 탈 비행선은 대해를 똑바로 가로질러 가지.', `MaleText_loc4`='今天你们的航线是直接跨越大海。', `MaleText_loc5`='你今天的航線將直接越過無盡之海。', `MaleText_loc7`='Tu ruta de hoy te llevará directamente al otro lado del mar.' WHERE `ID`=47320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거칠고 거대한 회색 파도가 높이 솟아오르는 곳이라고. 얼음장 같은 차가운 바닷물 속엔 굶주린 바다 생물이 살고 말이야.', `MaleText_loc4`='这是一个辽阔而残酷的世界，充斥于其中的是灰色的惊涛骇浪，极度凛冽的寒风，还有各种庞大的海洋怪兽。', `MaleText_loc5`='那是一片遼闊的、無情的、無盡的、灰色的滔天巨浪，有著凍死人的低溫，還有兇狠的海中生物。', `MaleText_loc7`='Una extensión enorme y despiadada de altas olas grises, temperaturas heladas y fauna marina hambrienta.' WHERE `ID`=47321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 믿으라고, 친구, 알약으로 유도한 빠르고 깔끔한 죽음이 저체온증이나 상어에게 물어뜯기는 길고 고통스러운 과정을 거치는 것보단 훨씬 나을 거야.', `MaleText_loc4`='相信我，朋友，通过服药获得的迅速死亡远比在经受漫长的寒冷之后再被鲨鱼撕碎要好得多。', `MaleText_loc5`='相信我，朋友，你會寧可服毒自殺死得痛快，也不要經歷痛苦的失溫過程，然後又被鯊魚給分屍咬死。', `MaleText_loc7`='Créeme, colega, una muerte causada por un veneno rápido es preferible al proceso largo y agonizante de la hipotermia y del posterior descuartizamiento por parte de los tiburones.' WHERE `ID`=47322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛이 어떤지 어떻게 아느냐고는 묻지 말라고.', `MaleText_loc4`='不要问我们怎么会知道它们的味道。', `MaleText_loc5`='不要問我們為什麼會知道牠們嚐起來的味道。', `MaleText_loc7`='No preguntes cómo sabemos qué sabor tienen.' WHERE `ID`=47323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 가는 도중에 비행선이 공격받아도, 공황 상태에 빠지는 건 바람직하지 못해.', `MaleText_loc4`='如果你们的飞艇在途中遭到攻击，惊慌失措肯定是不明智的。', `MaleText_loc5`='萬一飛艇在半途中遭受攻擊，也請不要驚慌。', `MaleText_loc7`='Si atacan al zepelín durante el vuelo, el pánico es desaconsejable.' WHERE `ID`=47324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급 상황에 대비해 갑판에 대포를 몇 개 배치해 두었으니 잘 찾아보라고.', `MaleText_loc4`='你们应该迅速找到并操作安装在甲板上的火炮，对抗敌人的进攻。', `MaleText_loc5`='甲板上有好幾門的防空砲就是為了這種緊急狀況而設置的。', `MaleText_loc7`='En su lugar, busca los cañones ubicados en cubierta precisamente para esas ocasiones.' WHERE `ID`=47325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 대포가 어떻게 작동하는지 시연해 주게.', `MaleText_loc4`='格瑞里，给他们演示该如何操作甲板火炮。', `MaleText_loc5`='格里利，教他們一下防空砲怎樣操作。', `MaleText_loc7`='Greely, enséñanos cómo funcionan los cañones.' WHERE `ID`=47326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조작법은 단순하다고. 목표물을 겨누고 방아쇠를 당기면 되지. 뭐, 안 겨눠도 상관없어. 무슨 일이 생기든 내 알 바 아니니까.', `MaleText_loc4`='只要瞄准，再扣动扳机。或者不瞄准也行。你会怎么干和我可没有任何关系。', `MaleText_loc5`='只要瞄準，然後扣下扳機...算了，還是別瞄準。我已經不想跟這個扯上任何關係。', `MaleText_loc7`='No hay más que apuntar y apretar el gatillo. O no apuntar. Yo me lavo las manos con todo el asunto.' WHERE `ID`=47327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 설마 빌지워터 항구 쪽으로 그냥 되는 대로 막 쏘고 있는 건 아니겠지?', `MaleText_loc4`='格瑞里，你不会在锈水港随意开火吧？', `MaleText_loc5`='格里利，你不會是隨便在對著污水港開砲吧?', `MaleText_loc7`='Greely, no estarás disparando ese trasto al azar en Puerto Pantoque, ¿verdad?' WHERE `ID`=47328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별로 그럴 일은 없을 것 같지만, 엄청난 사고에도 즉시 떼죽임당하지 않고 살아남는다면 말이야...', `MaleText_loc4`='如果发生了灾难性的事故，船上却还有幸存者，当然这种情况的可能性不大……', `MaleText_loc5`='若是災難性的嚴重故障罕見地沒有將全部的人瞬間殺光的話...', `MaleText_loc7`='En el caso poco probable de que un fallo catastrófico no mate al instante a todos los pasajeros...' WHERE `ID`=47329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난간을 따라 낙하산이 쭉 나타날 거라고.', `MaleText_loc4`='……船栏旁边能找到一些降落伞。', `MaleText_loc5`='...幾個降落傘將會沿著扶手出現。', `MaleText_loc7`='...unos paracaídas aparecerán junto a las barandillas.' WHERE `ID`=47330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불붙은 비행선에서 탈출하고 싶다면 그냥 가까이 있는 낙하산을 하나 움켜잡으면 돼. 마른 땅에 떨어지길 기도하면서 말이야.', `MaleText_loc4`='只需要抓住身边的降落伞，跳离燃烧的飞艇。然后希望自己能平安落在陆地上就行了。', `MaleText_loc5`='趕緊抓個離你最近的降落傘，然後從顯然已經在燃燒的飛艇跳下去即可。希望這時已經是在陸地上空。', `MaleText_loc7`='No tienes más que tomar el paracaídas más cercano para salir volando del zepelín ardiente. Y caer en tierra firme, con un poco de suerte.' WHERE `ID`=47331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 낙하산이 어떻게 작동하는지 시연해 주겠나?', `MaleText_loc4`='格瑞里，你要不要示范一下我们的降落伞是如何工作的？', `MaleText_loc5`='格里利，你能否示範一下我們的降落傘該如何操作?', `MaleText_loc7`='Greely, ¿quieres explicar cómo funcionan los paracaídas?' WHERE `ID`=47332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그럼 관두게. 듀로타의 창이 곧 도착할 것 같군.', `MaleText_loc4`='很好，杜隆塔尔之矛号差不多要到达了。', `MaleText_loc5`='好的，我看見杜洛塔之矛已經快抵達了。', `MaleText_loc7`='Muy bien. Veo que la Lanza de Durotar casi ha llegado.' WHERE `ID`=47333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 안전이나 행복 따위 이제 내가 알 바 아니야.', `MaleText_loc4`='你们的安全和福祉已经与我无关了。', `MaleText_loc5`='你的安全和健康將不再是我的問題。', `MaleText_loc7`='Tu seguridad y bienestar ya no son preocupación mía en absoluto.' WHERE `ID`=47334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 고원에서 즐겁게 지내라고!', `MaleText_loc4`='祝你有一趟刺激的高地之旅！', `MaleText_loc5`='祝攻打高地愉快!', `MaleText_loc7`='¡Que te diviertas asaltando las Tierras Altas!' WHERE `ID`=47335;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안락함이니 승객의 안전이니 하는 것에는 단 1코퍼도 낭비하지 않았다고요!', `FemaleText_loc4`='不要在舒适和安全方面浪费一个钱！', `FemaleText_loc5`='沒有浪費半毛錢在個人安全與舒適上!', `FemaleText_loc7`='¡No hemos derrochado ni un céntimo en comodidad ni seguridad personal!' WHERE `ID`=47336;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 아주 가차없이 무시해 버렸죠!', `FemaleText_loc4`='我们把没用的废物都省掉了！', `FemaleText_loc5`='打破得有夠徹底!', `FemaleText_loc7`='¡Las hemos roto bien rotas!' WHERE `ID`=47337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 아낀 돈은 우리 계좌로 옮겼고요.', `FemaleText_loc4`='我们一省再省。', `FemaleText_loc5`='我們把省下來的錢留給自己。', `FemaleText_loc7`='Lo que ahorramos, nos lo quedamos nosotros.' WHERE `ID`=47338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가슴에 손을 얹고 생각해 보세요. 헐거워서 자꾸 빠지는 안전밸브가 무슨 소용이겠어요? 별로 안전에 도움이 될 것 같지 않잖아요?', `FemaleText_loc4`='你自己想一想：一个总是漏气的“安全”阀有什么用？我感觉这种东西一点也不安全。', `FemaleText_loc5`='問問你自己:會一直爆開的「安全」閥是有什麼屁用?聽起來就不怎麼安全了。', `FemaleText_loc7`='Hazte esta pregunta: ¿para qué sirve una válvula "de seguridad" si no deja de saltar? A mí no me suena muy seguro.' WHERE `ID`=47339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엔진에 대해서도 설명해 주시지 그래요?', `FemaleText_loc4`='和他们说说引擎，老板。', `FemaleText_loc5`='老大，跟他們講講引擎的事情。', `FemaleText_loc7`='Habla de los motores, jefe.' WHERE `ID`=47340;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 그 혼합 연료를 "파멸의 주스"라고 부르죠.', `FemaleText_loc4`='我们称它为“末日果汁”。', `FemaleText_loc5`='我們把它叫做「毀滅之油」。', `FemaleText_loc7`='Lo llamamos "el jugo de la muerte".' WHERE `ID`=47341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심지어 말소리에도 반응한답니다.', `FemaleText_loc4`='当然，只是口头上说说。', `FemaleText_loc5`='即使只是口頭上的刺激。', `FemaleText_loc7`='Incluso verbal.' WHERE `ID`=47342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화재가 발생했을 때 승무원들이 재빨리 조치할 수 있도록, 연료통을 놓는 위치를 승무원들의 공간에서 객실 아래로 변경했답니다.', `FemaleText_loc4`='为了保证在失火时能够让全体船员迅速做出反应，燃料箱已经从船员区挪到了乘客舱室下方。', `FemaleText_loc5`='為了確保發生火警時船員能快速反應，燃料槽已經從船員區挪走，改裝到乘客艙的下方。', `FemaleText_loc7`='Para garantizar una respuesta rápida en caso de incendio, el almacenamiento se ha alejado de la cabina de la tripulación y se ha colocado bajo el compartimento de los pasajeros.' WHERE `ID`=47343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리야 없겠지만, 혹시라도 바다에 "비상 착륙"을 하게 되면 좌석 아래에 손을 뻗어 보세요. 승객 여러분의 편의를 위해 청산가리 알약이 준비되어 있으니까요.', `FemaleText_loc4`='飞艇落在海面上的可能性不大。不过，如果发生了这样的事情，请伸手到椅垫下面，你可以在那里找到一粒专门为您准备的氰化物胶囊。', `FemaleText_loc5`='如果發生了罕見的水上「著陸」事件，坐墊底下就有個氰化物膠囊方便你取用。', `FemaleText_loc7`='En el caso poco probable de un amerizaje "forzoso", busca debajo de tu asiento, donde se ha colocado una cápsula de cianuro para tu comodidad.' WHERE `ID`=47344;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아몬드에 알레르기가 있으신 분들을 위해, 알약은 다양한 맛으로 준비해 뒀어요.', `FemaleText_loc4`='为了避免您对氰化物的杏仁味过敏，我们特意为胶囊添加了各种调味剂。', `FemaleText_loc5`='至於那些對杏仁過敏的人，我們的氰化物膠囊還有提供多種不同的口味。', `FemaleText_loc7`='Para los alérgicos a las almendras, nuestras cápsulas de cianuro vienen en una amplia gama de sabores.' WHERE `ID`=47345;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공짜 땅콩도 준비되어 있으니 함께 즐기세요.', `FemaleText_loc4`='您还能找到一袋免费赠送的花生。', `FemaleText_loc5`='飛行途中還有一袋免費的花生小點心。', `FemaleText_loc7`='También hay una bolsa de cacahuetes gratuita.' WHERE `ID`=47346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사방에서 마구잡이로 날아오는 녹아내린 금속이야말로 가연성 열기구 함대를 지키는 가장 좋은 수단이지요!', `FemaleText_loc4`='朝各个方向随机掷出熔融金属，只有这样才能让一支由易燃飞船组成的舰队确保绝对安全！', `FemaleText_loc5`='要保護易燃的飛船艦隊的最佳辦法，就是到處亂發射融化的金屬破片!', `FemaleText_loc7`='¡Nada garantiza mejor la seguridad de una flota de dirigibles inflamables que disparar metal fundido al azar en todas direcciones!' WHERE `ID`=47347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기꺼이요!', `FemaleText_loc4`='非常愿意！', `FemaleText_loc5`='我的榮幸!', `FemaleText_loc7`='¡Con gusto!' WHERE `ID`=47348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 우리 집도 맞힐 수 있답니다!', `FemaleText_loc4`='我能从这里击中我的房子！', `FemaleText_loc5`='我可以從這裡打到我家!', `FemaleText_loc7`='¡Puedo darle a mi casa desde aquí!' WHERE `ID`=47349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가요.', `FemaleText_loc4`='不。', `FemaleText_loc5`='沒有。', `FemaleText_loc7`='No.' WHERE `ID`=47350;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아닐 거예요.', `FemaleText_loc4`='也许。', `FemaleText_loc5`='也許吧。', `FemaleText_loc7`='Quizá.' WHERE `ID`=47351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금은 그럴지도요...', `FemaleText_loc4`='偶尔会。', `FemaleText_loc5`='有一點。', `FemaleText_loc7`='Un poquito.' WHERE `ID`=47352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저흰 이 낙하산을 "비상 무경사로 상륙 장치"라고 부르죠.', `FemaleText_loc4`='我们称它为“紧急无坡道离船装置”。', `FemaleText_loc5`='我們把這叫做「緊急無滑梯登陸裝置」。', `FemaleText_loc7`='Los llamamos "Dispositivos de evacuación de emergencia libres de rampas".' WHERE `ID`=47353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헉, 절대로 안 돼요! 지금 저보고 죽으라는 건가요?', `FemaleText_loc4`='哦，天哪，不！这些东西都是死亡陷阱！', `FemaleText_loc5`='嘿，我才不要咧!那些東西是死亡陷阱!', `FemaleText_loc7`='¡Para nada! ¡Esos trastos son trampas mortales!' WHERE `ID`=47354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빌지워터 항만의 모든 이를 대신해 인사드리죠...', `FemaleText_loc4`='我们留在锈水港的全体人员……', `FemaleText_loc5`='來自污水碼頭全體的...', `FemaleText_loc7`='De parte de todos nosotros en Muelle Pantoque...' WHERE `ID`=47355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 고원에서 즐겁게 지내세요!', `FemaleText_loc4`='祝你有一趟刺激的高地之旅！', `FemaleText_loc5`='祝攻打高地愉快!', `FemaleText_loc7`='¡Que te diviertas asaltando las Tierras Altas!' WHERE `ID`=47356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자 룬을 피해야 합니다!', `MaleText_loc4`='别碰那些暗影符文！', `MaleText_loc5`='避開暗影符文!', `MaleText_loc7`='¡Evita las runas de las Sombras!', `FemaleText_loc1`='그림자 룬을 피해야 합니다!', `FemaleText_loc4`='别碰那些暗影符文！', `FemaleText_loc5`='避開暗影符文!', `FemaleText_loc7`='¡Evita las runas de las Sombras!' WHERE `ID`=47357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해서 수집하는 중', `MaleText_loc4`='小心收集', `MaleText_loc5`='小心收集', `MaleText_loc7`='Recolección cuidadosa', `FemaleText_loc1`='조심해서 수집하는 중', `FemaleText_loc4`='小心收集', `FemaleText_loc5`='小心收集', `FemaleText_loc7`='Recolección cuidadosa' WHERE `ID`=47358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장... 땅 상태를 보니 투기는 확실히 포기해야겠군.', `MaleText_loc4`='该死的……失去潜在收入的后果是灾难性的。', `MaleText_loc5`='該該該死死死死死死死...損失潛在的收益實在太慘了。', `MaleText_loc7`='Joooo... La pérdida de los ingresos potenciales es devastadora.' WHERE `ID`=47359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 찾는 물건은 곧 내 차지가 될 거다, 존스 박사!', `MaleText_loc4`='你正在找的那东西很快就会属于我了，琼斯博士！', `MaleText_loc5`='你要找的東西很快就會變成我的了，瓊斯博士!', `MaleText_loc7`='¡Eso que buskas prrronto será mío, doktor Jones!' WHERE `ID`=47360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글럽톡 간다!', `MaleText_loc4`='格拉布托克，好了吗？', `MaleText_loc5`='格魯巴托克好了嗎?', `MaleText_loc7`='¿Glubtok listo?' WHERE `ID`=47361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응, 가자!', `MaleText_loc4`='动手吧！', `MaleText_loc5`='咱們動手吧!', `MaleText_loc7`='¡Hagámoslo!' WHERE `ID`=47362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력!!!', `MaleText_loc4`='奥术力量！', `MaleText_loc5`='秘法力量!', `MaleText_loc7`='¡¡¡PODER ARCANO!!!' WHERE `ID`=47363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포세이큰에게 무릎을 꿇다니, 크롤리는 늑대인간의 수치다. 내가 이끄는 늑대인간 무리가 놈들에게 우리의 진정한 모습을, 그리고 우리가 가져오는 무한한 공포를 보여주리라!', `MaleText_loc4`='克罗雷竟然向被遗忘者屈服了。他真是我们一族的耻辱。我们要让他们看看什么才是真正的狼人，要让他们尝尝我们无情的怒火！', `MaleText_loc5`='克羅雷這個可恥的傢伙，竟然向被遺忘者臣服了。我的狼群會讓他知道狼人的真正面貌，以及我們所具有的兇暴怒火!', `MaleText_loc7`='Crowley es una vergüenza para nosotros por entregarse a los Renegados. Mi manada les enseñará el verdadero rostro de los huargen, ¡y la furia implacable que acompaña a nuestra presencia!' WHERE `ID`=47364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것도 자물쇠라고! 우릴 저지하고 싶다면 훨씬 더 애써야 할 텐데, 고드프리...', `MaleText_loc4`='就这把烂锁？真可笑！想要打败我们，高弗雷可得再争气点才行啊。', `MaleText_loc5`='多麼可憐的鎖啊!高佛雷要是想擊敗我們，他還得更努力一些才行。', `MaleText_loc7`='¡Qué cerrojo más patético! Godfrey va a tener que esforzarse más si quiere derrotarnos.' WHERE `ID`=47365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 너의 종말이 다가왔다, 고드프리!', `MaleText_loc4`='你的死期到了，高弗雷！', `MaleText_loc5`='你的死期終於到了，高佛雷!', `MaleText_loc7`='¡Tu hora ha llegado al fin, Godfrey!' WHERE `ID`=47366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 유명한 "용아귀 부족의 현자"를 만나러 여기까지 먼 길을 왔다. 칼을 꽂기 전에 초갈의 검은 심장을 한번 들여다보고 싶었지.$B$B하지만 그녀는 아무 쓸모가 없군. 온통 수수께끼만 지껄여 대니... 어쩌면 네가 도움이 될지도 모르겠다.', `FemaleText_loc4`='我赶了这么远的路，就是为了和著名的“龙喉先知”谈一谈。在毁灭古加尔之前，我想看清楚他的黑心里面到底有什么。$B$B但她没告诉我任何有意义的东西。我只得到了一堆谜语。也许你能帮助我。', `FemaleText_loc5`='我千里迢迢跑來找大名鼎鼎的「龍喉先知」，因為我想在挖出丘加利的心臟之前，先看看他的心裡到底在想什麼。$B$B然而她只會滿口的謎語和詩句，對我跟本毫無幫助。或許，你反倒能幫得上忙。', `FemaleText_loc7`='He viajado hasta aquí para hablar con la famosa "Vidente de los Faucedraco". Quería mirar en el interior del corazón de Cho''gall antes de arrancárselo.$b$bPero no me sirve. Es todo rimas y acertijos. A lo mejor tú puedes ayudarme.' WHERE `ID`=47367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성궤는 바로 이 폐허 너머에 있소.$b$b어서 갑시다!', `MaleText_loc4`='那个箱子就在废墟里。$b$b我们行动！', `MaleText_loc5`='法櫃就在這片遺跡的那邊。$b$b我們走!', `MaleText_loc7`='El arca está justo más allá de esas ruinas.$b$B¡Vamos!' WHERE `ID`=47368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 갑시다!', `MaleText_loc4`='我准备好了。出发吧！', `MaleText_loc5`='我準備好了。我們走吧!', `MaleText_loc7`='Estoy listo. ¡Vamos!', `FemaleText_loc1`='준비됐어요. 출발하세요!', `FemaleText_loc4`='我准备好了。出发吧！', `FemaleText_loc5`='我準備好了。我們走吧!', `FemaleText_loc7`='Estoy lista. ¡Vamos!' WHERE `ID`=47369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 너무 오랫동안 마법의 비밀을 무시한 채 살아왔네.$B$B자네도 그런 이유로 가르침을 받으러 온 건가?', `MaleText_loc4`='我们已经太久忽略了奥术的秘密。$B$B你是来学习这个秘密的吗？', `MaleText_loc5`='我們對秘法的秘密已忽視了太久。$B$B你也是來學習的嗎?', `MaleText_loc7`='Hemos dado la espalda a los secretos de lo Arcano durante demasiado tiempo.$b$b¿Tú también has venido a aprender?', `FemaleText_loc1`='우린 너무 오랫동안 마법의 비밀을 무시한 채 살아왔네.$B$B자네도 그런 이유로 가르침을 받으러 온 건가?', `FemaleText_loc4`='我们已经太久忽略了奥术的秘密。$B$B你是来学习这个秘密的吗？', `FemaleText_loc5`='我們對秘法的秘密已忽視了太久。$B$B你也是來學習的嗎?', `FemaleText_loc7`='Hemos dado la espalda a los secretos de lo Arcano durante demasiado tiempo.$b$b¿Tú también has venido a aprender?' WHERE `ID`=47370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 너무 오랫동안 마법의 비밀을 무시한 채 살아왔네.$B$B안타깝지만 자네에게는 계속해서 비밀로 남겨질 수밖에 없겠군.', `MaleText_loc4`='我们已经太久忽略了奥术的秘密。$B$B可惜的是，它对你来说只能是个秘密。', `MaleText_loc5`='我們對秘法的秘密已忽視了太久。$B$B遺憾的是，它們對你而言將依然是個秘密。', `MaleText_loc7`='Hemos dado la espalda a los secretos de lo Arcano durante demasiado tiempo.$b$bPor desgracia, para ti seguirán siendo un secreto.', `FemaleText_loc1`='우린 너무 오랫동안 마법의 비밀을 무시한 채 살아왔네.$B$B안타깝지만 자네에게는 계속해서 비밀로 남겨질 수밖에 없겠군.', `FemaleText_loc4`='我们已经太久忽略了奥术的秘密。$B$B可惜的是，它对你来说只能是个秘密。', `FemaleText_loc5`='我們對秘法的秘密已忽視了太久。$B$B遺憾的是，它們對你而言將依然是個秘密。', `FemaleText_loc7`='Hemos dado la espalda a los secretos de lo Arcano durante demasiado tiempo.$b$bPor desgracia, para ti seguirán siendo un secreto.' WHERE `ID`=47371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대괴수 뒤로 가야 합니다!', `MaleText_loc4`='从巨像背后攻击它！', `MaleText_loc5`='躲到巨像的後面!', `MaleText_loc7`='¡Ponte detrás del coloso!', `FemaleText_loc1`='거대괴수 뒤로 가야 합니다!', `FemaleText_loc4`='从巨像背后攻击它！', `FemaleText_loc5`='躲到巨像的後面!', `FemaleText_loc7`='¡Ponte detrás del coloso!' WHERE `ID`=47372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하와... 왕자님을 구해 줘서 고맙네, $n.', `MaleText_loc4`='感谢你救出了国王……还有王子，$n。', `MaleText_loc5`='謝謝你救了國王...還有王子，$n。', `MaleText_loc7`='Gracias por rescatar al Rey... Y al príncipe, $n.' WHERE `ID`=47373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 친구가 있다는 게 어떤 느낌인지 알았다, $n.', `MaleText_loc4`='你让我明白了朋友的意义，$n。', `MaleText_loc5`='你教會了我何謂朋友的意義，$n。', `MaleText_loc7`='Me has enseñado lo que significa tener amigos, $n.' WHERE `ID`=47374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 해냈군그래. 자넨 자네 종족의 자랑이야.', `MaleText_loc4`='我见证了你的成功，$n。你是你们一族的骄傲。', `MaleText_loc5`='你辦到了，$n。你真是你們種族的表率。', `MaleText_loc7`='Veo que lo has conseguido, $n. Eres un honor para tu raza.' WHERE `ID`=47375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 이상도 없습니다, 사령관님.', `MaleText_loc4`='边界安全了，指挥官。', `MaleText_loc5`='外圍已經安全了，指揮官。', `MaleText_loc7`='El perímetro está controlado, Comandante.', `FemaleText_loc1`='아무 이상도 없어요, 사령관님.', `FemaleText_loc4`='边界安全了，指挥官。', `FemaleText_loc5`='外圍已經安全了，指揮官。', `FemaleText_loc7`='El perímetro está controlado, Comandante.' WHERE `ID`=47376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 휘곤해!', `MaleText_loc4`='我累了！', `MaleText_loc5`='我累爆了!', `MaleText_loc7`='¡Estoy agotado!', `FemaleText_loc1`='아, 휘곤해!', `FemaleText_loc4`='我累了！', `FemaleText_loc5`='我累爆了!', `FemaleText_loc7`='¡Estoy agotada!' WHERE `ID`=47377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격하라, 형제들이여! 늑대인간 무리의 분노가 어떤 것인지 보여 줘라!', `MaleText_loc4`='进攻，兄弟们！让他感受到狼群的怒火！', `MaleText_loc5`='兄弟們，攻擊!讓他們感受到狼群的憤怒!', `MaleText_loc7`='¡Atacad, hermanos! ¡Que sienta la furia de la manada!' WHERE `ID`=47378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, $c 친구.$B$B차원문을 이해하기에는 마법에 대한 자네의 지식이 부족한 것 같네.', `MaleText_loc4`='抱歉，$c。$B$B你对奥术的掌握还不够强大，还无法理解传送门魔法。', `MaleText_loc5`='抱歉，$c。$B$B你對魔法的理解還不夠完整，無法學習傳送法術。', `MaleText_loc7`='Lo siento, $c.$b$bTu comprensión de lo Arcano no es lo bastante fuerte como para asimilar la magia del portal.', `FemaleText_loc1`='미안하네, $c 친구.$B$B차원문을 이해하기에는 마법에 대한 자네의 지식이 부족한 것 같네.', `FemaleText_loc4`='抱歉，$c。$B$B你对奥术的掌握还不够强大，还无法理解传送门魔法。', `FemaleText_loc5`='抱歉，$c。$B$B你對魔法的理解還不夠完整，無法學習傳送法術。', `FemaleText_loc7`='Lo siento, $c.$b$bTu comprensión de lo Arcano no es lo bastante fuerte como para asimilar la magia del portal.' WHERE `ID`=47379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 마법의 학생이군.$B$B원한다면 내가 차원문 마법을 가르쳐 줄 수 있네.', `MaleText_loc4`='你也是一名奥术的研究者？$B$B我可以教导你传送门魔法的技艺，如果你想学的话。', `MaleText_loc5`='你也是一位研習秘法的學徒?$B$B如果你想學的話，我可以教你如何開啟傳送門的法術。', `MaleText_loc7`='También estudias las artes arcanas, ¿verdad?$b$bPuedo enseñarte la magia del portal, si quieres.', `FemaleText_loc1`='자네도 마법의 학생이군.$B$B원한다면 내가 차원문 마법을 가르쳐 줄 수 있네.', `FemaleText_loc4`='你也是一名奥术的研究者？$B$B我可以教导你传送门魔法的技艺，如果你想学的话。', `FemaleText_loc5`='你也是一位研習秘法的學徒?$B$B如果你想學的話，我可以教你如何開啟傳送門的法術。', `FemaleText_loc7`='También estudias las artes arcanas, ¿verdad?$b$bPuedo enseñarte la magia del portal, si quieres.' WHERE `ID`=47380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 아주 좋아. 그러면 기록을 마지막으로 한 번만 확인해 보자고.', `MaleText_loc4`='很好。让我查看一下上次做的笔记……', `MaleText_loc5`='嗯...這樣子啊...讓我再看最後一次我的筆記...', `MaleText_loc7`='De acuerrrdo, entonces. Deja que comprrruebe mis notas una última vez...' WHERE `ID`=47381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 음... 그래, 그래... 아주 간단하군...
', `MaleText_loc4`='嗯，是的，是的……够简单……', `MaleText_loc5`='嗯 - 嗯...對，對...很簡單...', `MaleText_loc7`='Mmmm-hmmmm, sí... fastante simple...' WHERE `ID`=47382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 고블스! 이제 시작할 준비가 됐다! 이리 와!', `MaleText_loc4`='哦，哥培尔！我们已经准备好了！来吧，来吧！', `MaleText_loc5`='喔，咯咯!我們準備好要開始了!來吧，來吧!', `MaleText_loc7`='¡Oh, Gluber! ¡Estamos listos para empezarrr! ¡Ven, ven!' WHERE `ID`=47383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금이라도 전리품을 원한다면 서두르는 게 좋을 것이다.', `MaleText_loc4`='如果你还想参加战斗，那最好快一点。', `MaleText_loc5`='想分到寶藏的話你最好動作快點。', `MaleText_loc7`='Será mejor que te des prisa si quieres echar mano de los restos.' WHERE `ID`=47384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려, 고블스! 모두 물러서!', `MaleText_loc4`='坚持住，哥培尔！所有人都向后站！', `MaleText_loc5`='慢著，咯咯!所有人後退!', `MaleText_loc7`='¡Aguanta, Gluber! ¡Todos atrrrás!' WHERE `ID`=47385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전하 충전이 끝나기 전에 폭풍 방패를 사용하십시오!

|TInterface\\Icons\\spell_nature_lightningshield.blp:32|t', `MaleText_loc4`='在静电充能结束前使用你的暴风护盾！

|TInterface\\Icons\\spell_nature_lightningshield.blp:32|t', `MaleText_loc5`='在靜電衝擊結束前使用你的風暴之盾!

