UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지!?', `MaleText_loc4`='什么！？', `MaleText_loc5`='什麼!?', `MaleText_loc7`='¿¡Qué!?' WHERE `ID`=47388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 뭐가 잘못된 거지? 하라는 대로 정확히 따라 했는데...', `MaleText_loc4`='到底发生了什么错误！我严格依照每一个细节……', `MaleText_loc5`='到底是出了啥麼差錯?我每個細節都確實做到了...', `MaleText_loc7`='¿Qué ha podido irrr mal? He seguido hasta el último detalle...' WHERE `ID`=47389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 이게 뭐야?!', `MaleText_loc4`='等等！这是什么！？', `MaleText_loc5`='等一下!這是啥麼!?', `MaleText_loc7`='¡Esperrra un segundo! ¡¿Qué es esto?!' WHERE `ID`=47390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 우상을 여덟 개만 가져왔잖아!', `MaleText_loc4`='你只是给我带来了八个雕像！', `MaleText_loc5`='你只拿了八個塑像給我!', `MaleText_loc7`='¡Solo me has trrraído ocho ídolos!' WHERE `ID`=47391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 의식에는 정확히 아홉 개가 필요하다니까!!', `MaleText_loc4`='这个仪式需要九个！！', `MaleText_loc5`='這個儀式說要有九個!!', `MaleText_loc7`='¡El rrritual indica específicamente que hacen falta nuefe!' WHERE `ID`=47392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아홉 개! 아홉! 아홉 개라고!!', `MaleText_loc4`='九个！九个！九个！九个！九个！！！', `MaleText_loc5`='九!九!九!九!九!!!!', `MaleText_loc7`='¡¡NUEFE!! ¡NUEFE! ¡NUEFE! ¡¡NUEFE!!' WHERE `ID`=47393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 내 눈앞에서 꺼져! 제길...', `MaleText_loc4`='滚开，别让我看到你！混……', `MaleText_loc5`='給我滾開，滾開!噢...', `MaleText_loc7`='¡Larrrgo de mi fista! Auch...' WHERE `ID`=47394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 고블스...', `MaleText_loc4`='我可怜的哥培尔……', `MaleText_loc5`='我可憐的咯咯...', `MaleText_loc7`='Mi pobrrre Gluber...' WHERE `ID`=47395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 몸을 공격하고 살아남을 것 같으냐!', `MaleText_loc4`='敢惹老子就是死路一条！', `MaleText_loc5`='沒有人能在攻擊了偉大的加里維克斯之後還能活下來!', `MaleText_loc7`='¡Nadie ataca al Gran G y vive!' WHERE `ID`=47396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라!', `MaleText_loc4`='干掉你！', `MaleText_loc5`='宰了你!', `MaleText_loc7`='¡CÓMETELO!' WHERE `ID`=47397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 밖에서 무슨 일이 일어난 거야?', `MaleText_loc4`='以地狱的名义，这里到底发生了什么？', `MaleText_loc5`='這邊到底是發生了什麼事情?', `MaleText_loc7`='¿Qué demonios está pasando aquí?' WHERE `ID`=47398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음대로 언덕에 발을 들였지만, 절대 살아서 돌아갈 수 없을 것이다.', `MaleText_loc4`='你也许能活着走进这座山，但我保证你没办法活着出来。', `MaleText_loc5`='你或許能活著進入這片山丘，但是我向你保證，你絕對無法活著離開。', `MaleText_loc7`='Puedes entrar en esta colina con vida, pero te aseguro que no saldrás con vida.', `FemaleText_loc1`='마음대로 언덕에 발을 들였지만, 절대 살아서 돌아갈 수 없을 것이다.', `FemaleText_loc4`='你也许能活着走进这座山，但我保证你没办法活着出来。', `FemaleText_loc5`='你或許能活著進入這片山丘，但是我向你保證，你絕對無法活著離開。', `FemaleText_loc7`='Puedes entrar en esta colina con vida, pero te aseguro que no saldrás con vida.' WHERE `ID`=47399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨 바라드는 내 것이다!', `MaleText_loc4`='托尔巴拉德是我的，是我的！', `MaleText_loc5`='托巴拉德是我的，是我的!', `MaleText_loc7`='¡Tol Barad es mío! Mío, ¿me oyes?', `FemaleText_loc1`='톨 바라드는 내 것이다!', `FemaleText_loc4`='托尔巴拉德是我的，是我的！', `FemaleText_loc5`='托巴拉德是我的，是我的!', `FemaleText_loc7`='¡Tol Barad es mío! Mío, ¿me oyes?' WHERE `ID`=47400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 노력하면 섬을 차지할 수 있을 것이다. 모두 용기를 잃지 마라! 우리는 내일 아침이 밝는 대로 출발한다.', `MaleText_loc4`='只要最后一击，这座岛就是我们的了。振作起来，我们将在早晨开始行动。', `MaleText_loc5`='再發動最後一次攻擊，這座島就是我們的了。打起精神，明天天一亮我們就出動。', `MaleText_loc7`='Un último empujón y la isla será nuestra. Ánimo, chicos, saldremos mañana a primera hora.', `FemaleText_loc1`='조금만 더 노력하면 섬을 차지할 수 있을 것이다. 모두 용기를 잃지 마라! 우리는 내일 아침이 밝는 대로 출발한다.', `FemaleText_loc4`='只要最后一击，这座岛就是我们的了。振作起来，我们将在早晨开始行动。', `FemaleText_loc5`='再發動最後一次攻擊，這座島就是我們的了。打起精神，明天天一亮我們就出動。', `FemaleText_loc7`='Un último empujón y la isla será nuestra. Ánimo, chicos, saldremos mañana a primera hora.' WHERE `ID`=47401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라! 네가 누구든 간에! 잊어버린 언덕은... 내 것이다!', `MaleText_loc4`='无论你是谁，给我滚开！遗忘丘是我的……我的！', `MaleText_loc5`='不管你是誰，走開!遺忘之丘是我的...我的!', `MaleText_loc7`='¡Vete, quienquiera que seas! La Colina del Olvido es mía... ¡Mía!', `FemaleText_loc1`='사라져라! 네가 누구든 간에! 잊어버린 언덕은... 내 것이다!', `FemaleText_loc4`='无论你是谁，给我滚开！遗忘丘是我的……我的！', `FemaleText_loc5`='不管你是誰，走開!遺忘之丘是我的...我的!', `FemaleText_loc7`='¡Vete, quienquiera que seas! La Colina del Olvido es mía... ¡Mía!' WHERE `ID`=47402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문이 왜 닫혀 있는지 모르겠다, 영웅들이여. 내 무리가 지금쯤이면 이미 고드프리를 처리했을 텐데...', `MaleText_loc4`='我不知道为什么这扇门关上了，英雄们。我的狼群现在应该已经干掉高弗雷了……', `MaleText_loc5`='英雄們，我不知道為什麼這扇門是關住的，我的狼群這時候應該已經把高佛雷給解決了才對...', `MaleText_loc7`='No sé por qué está cerrada la puerta, héroes. Mi manada ya debería haberse encargado de Godfrey...' WHERE `ID`=47403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 시간만 죽일 수는 없지! 행동할 시간이다!', `MaleText_loc4`='我们不会再袖手旁观了！现在是采取行动的时候！', `MaleText_loc5`='我們不會再束手旁觀!行動的時候到了!', `MaleText_loc7`='¡Ya está bien de permanecer mano sobre mano! ¡Ha llegado el momento de actuar!' WHERE `ID`=47404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미 물러나라! 돌머리가 간다!', `MaleText_loc4`='小心蜘蛛！隆克来了！', `MaleText_loc5`='小心蜘蛛!郎克來了!', `MaleText_loc7`='¡Cuidado, araña! ¡Aquí viene Ñoño!' WHERE `ID`=47405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리 지금 거미 탄다!', `MaleText_loc4`='隆克骑着蜘蛛！', `MaleText_loc5`='郎克騎蜘蛛!', `MaleText_loc7`='¡Ahora Ñoño montar araña!' WHERE `ID`=47406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미에 탈 시간이다!', `MaleText_loc4`='蜘蛛肚子时间！', `MaleText_loc5`='蜘蛛肚肚時間!', `MaleText_loc7`='¡Hora de la tripita de la araña!' WHERE `ID`=47407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미 너 가만히 있어!', `MaleText_loc4`='停住别动，蜘蛛！', `MaleText_loc5`='你不要動，蜘蛛!', `MaleText_loc7`='¡Estate quieta, araña!' WHERE `ID`=47408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 돌머리가 거미 탄다!', `MaleText_loc4`='隆克要骑你了！', `MaleText_loc5`='郎克要騎你了!', `MaleText_loc7`='¡Ahora Ñoño montarte!' WHERE `ID`=47409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하!', `MaleText_loc4`='哈哈哈！', `MaleText_loc5`='哈哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja!' WHERE `ID`=47410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 독주머니 있다.', `MaleText_loc4`='我弄些毒液给你。', `MaleText_loc5`='我有一些毒給你。', `MaleText_loc7`='Tengo un poco de veneno para ti.' WHERE `ID`=47411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리 배에 독주머니 있다.', `MaleText_loc4`='隆克用他的肚子给你弄了些毒液。', `MaleText_loc5`='郎克用他的肚肚拿一些毒給你。', `MaleText_loc7`='Ñoño conseguirte un poco de veneno con su tripita.' WHERE `ID`=47412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤지? 독 때문에 거미 안 죽여도 된다. 그냥 타면 되잖아.', `MaleText_loc4`='看到了吗？要取得毒液不需要杀蜘蛛，只需要骑上它。', `MaleText_loc5`='看吧?不用殺蜘蛛拿毒。騎一騎就好了。', `MaleText_loc7`='¿Ves? No matar araña por veneno. Solo montar.' WHERE `ID`=47413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미가 돌머리 배에 독 남겨놨다. 필요해?', `MaleText_loc4`='蜘蛛在隆克的肚子上留下了一些毒液。你想要吗？', `MaleText_loc5`='蜘蛛在郎克肚肚上留了一些毒，你要嗎?', `MaleText_loc7`='La araña dejar un poco de veneno en la tripita de Ñoño. ¿Tú querer?' WHERE `ID`=47414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 독 가져왔다.', `MaleText_loc4`='给，我为你弄到了。', `MaleText_loc5`='拿去，這個給你。', `MaleText_loc7`='Toma, yo conseguirte esto.' WHERE `ID`=47415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 돌머리 배에서 독 닦아내면 된다.', `MaleText_loc4`='你可以从隆克的肚子上把毒液刮下来。', `MaleText_loc5`='嗯，你可以從郎克的肚肚刮毒下來。', `MaleText_loc7`='Toma, puedes quitar veneno de tripita de Ñoño.' WHERE `ID`=47416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 너희를 방해하지 못하게 하겠다. 가라, 영웅들이여! 고드프리를 없애라!', `MaleText_loc4`='我掩护你们。上啊，英雄们！消灭高弗雷！', `MaleText_loc5`='我去確保沒有東西會來插手干預。去吧，英雄們!殺掉高佛雷!', `MaleText_loc7`='Me aseguraré de que nadie interfiera. ¡Ahora marchaos, héroes! ¡Matad a Godfrey!' WHERE `ID`=47418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쉽게도 저는 도와드릴 수가 없습니다, $r님. 하지만 캘린 스틸윙이라면 틀림없이 도움이 될 겁니다.', `MaleText_loc4`='恐怕我没办法帮你，$r，但我相信凯琳·斯蒂文可以。', `MaleText_loc5`='我恐怕幫不了你，$r，但是我相信凱琳·鋼翼應該可以。', `MaleText_loc7`='Me temo que no puedo ayudarte, $r, pero seguro que Khaelyn Alacerada sí.', `FemaleText_loc1`='아쉽게도 저는 도와드릴 수가 없습니다, $r님. 하지만 캘린 스틸윙이라면 틀림없이 도움이 될 겁니다.', `FemaleText_loc4`='恐怕我没办法帮你，$r，但我相信凯琳·斯蒂文可以。', `FemaleText_loc5`='我恐怕幫不了你，$r，但是我相信凱琳·鋼翼應該可以。', `FemaleText_loc7`='Me temo que no puedo ayudarte, $r, pero seguro que Khaelyn Alacerada sí.' WHERE `ID`=47419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쉽게도 저는 도와드릴 수가 없습니다, $r님. 하지만 조지아라면 틀림없이 도움이 될 겁니다.', `MaleText_loc4`='恐怕我没办法帮你，$r，但我相信乔吉亚可以。', `MaleText_loc5`='我恐怕幫不了你，$r，但是我相信喬吉亞應該可以。', `MaleText_loc7`='Me temo que no puedo ayudarte, $r, pero seguro que Georgia sí.', `FemaleText_loc1`='아쉽게도 저는 도와드릴 수가 없습니다, $r님. 하지만 조지아라면 틀림없이 도움이 될 겁니다.', `FemaleText_loc4`='恐怕我没办法帮你，$r，但我相信乔吉亚可以。', `FemaleText_loc5`='我恐怕幫不了你，$r，但是我相信喬吉亞應該可以。', `FemaleText_loc7`='Me temo que no puedo ayudarte, $r, pero seguro que Georgia sí.' WHERE `ID`=47420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다, 젊은 양반! 이제 놈들의 지도자를 공격할 땝니다!', `MaleText_loc4`='干得好，$g小伙子:姑娘;！现在去干掉他们的头领吧！', `MaleText_loc5`='幹得好，$g小子:小妞;!現在攻擊他們的首領!', `MaleText_loc7`='¡Buen trabajo, $gchaval:chavala;! ¡Ahora a por su líder!', `FemaleText_loc1`='잘하셨어요, 젊은 양반! 이제 놈들의 지도자를 공격할 때로군요!', `FemaleText_loc4`='干得好，$g小伙子:姑娘;！现在去干掉他们的头领吧！', `FemaleText_loc5`='幹得好，$g小子:小妞;!現在攻擊他們的首領!', `FemaleText_loc7`='¡Buen trabajo, $gchaval:chavala;! ¡Ahora a por su líder!' WHERE `ID`=47421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으어어... 너무... 세다아아아...', `MaleText_loc4`='力量……太强了……', `MaleText_loc5`='太...多...力量啦!!!', `MaleText_loc7`='¡¡DEMASIADO... PODER!!!' WHERE `ID`=47422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 있는 가고일이 생명을 얻습니다!', `MaleText_loc4`='附近的石像鬼活过来了！', `MaleText_loc5`='附近的一隻石像鬼醒來了!', `MaleText_loc7`='¡Una gárgola cercana vuelve a la vida!' WHERE `ID`=47423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리 뭐 죽이는 거 다 지겹다! 돌머리 이제 그만할래!', `MaleText_loc4`='隆克厌倦了杀戮！隆克退出！', `MaleText_loc5`='郎克不想殺了!郎克不玩了!', `MaleText_loc7`='¡Ñoño cansado de todas estas muertes! ¡Ñoño lo deja!' WHERE `ID`=47424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리 진짜 모험하러 떠날 거다!', `MaleText_loc4`='隆克要去进行真正的冒险！', `MaleText_loc5`='郎克要去找真正的冒險!', `MaleText_loc7`='¡Ñoño irse a buscar aventuras de verdad!' WHERE `ID`=47425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 사용한 이 역병은 아주 특별하다네. 고드프리의 부하들은 역병 때문에 성채를 떠날 수 없지만, 우리는 역병에 전혀 영향을 받지 않고 포세이큰의 이름으로 진군할 수 있지!', `MaleText_loc4`='我们散播的这种特殊魔法会让高弗雷的军队无法离开城堡。我们却可以自由地调动部队冲杀进去，为被遗忘者夺下它！', `MaleText_loc5`='我們在散佈的這個特別的瘟疫能阻止高佛雷的部隊離開這座城堡，但是我們被遺忘者依然可以派遣部隊去奪下它!', `MaleText_loc7`='Esta peste especial que estamos esparciendo impedirá que las tropas de Godfrey salgan del castillo, ¡pero permitirá que las nuestras entren para tomarlo para los Renegados!' WHERE `ID`=47426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 용아귀 항구에 상륙한 것을 확인했습니다, 주인님. 놈들이 움직이고 있습니다.', `MaleText_loc4`='我们确认部落已经出现在了龙喉港，主人。他们组建了一支大军。', `MaleText_loc5`='主人，已經確定部落出現在龍喉港。他們是一夥的。', `MaleText_loc7`='Hemos confirmado la presencia de la Horda en el Puerto Faucedraco, amo. Ahora están en liga.' WHERE `ID`=47427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요원들은 정체를 들켜 죽고 말았습니다, 주인님.', `MaleText_loc4`='我们的密探都被除掉了，主人。', `MaleText_loc5`='我們的間諜們都被殺死了，主人。', `MaleText_loc7`='Descubrieron y asesinaron a nuestros agentes, amo.' WHERE `ID`=47428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 상륙했습니다, 주인님. 바닷가에 많은 수가 모여 있습니다.', `MaleText_loc4`='联盟已经登陆了，主人，他们集结在岸边，数量众多。', `MaleText_loc5`='聯盟已經登陸了，主人，以大量的人數聚集在海岸邊。', `MaleText_loc7`='La Alianza ha llegado, y sus amplias filas cubren la costa.' WHERE `ID`=47429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라지는 건 없다. (달라지는 건 없다. 없어. 다 없애. 없애.)', `MaleText_loc4`='这什么也改变不了。（什么都没改变，碾碎他们，碾碎。）', `MaleText_loc5`='這不會有任何改變。(不會有任何任何改變。碾碎他們，碾碎。)', `MaleText_loc7`='No cambia nada. (Nada, no cambia nada. Aplástenlos, aplasten.)' WHERE `ID`=47430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드의 요원들이 소식을 보냈나? (스톰윈드! 눈! 눈이 도시를 들여다본다.) 눈을 가져와라.', `MaleText_loc4`='我们在暴风城的探子如何了？（暴风城！这只眼睛看到了那座城市的中心。）把眼睛拿给我。', `MaleText_loc5`='我們在暴風城的間諜們呢?(暴風城!眼睛，眼睛看破城市的一切。)將「眼睛」帶給我。', `MaleText_loc7`='¿Y nuestros agentes en Ventormenta? (¡Ventormenta! El Ojo, el Ojo ve el centro de la ciudad.) Tráiganme el Ojo.' WHERE `ID`=47431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 요원들이 소식을 보냈나? (바위와 모래에 둘러싸인 도시. 우린 본다! 눈이 도시를 본다.) 눈을 가져와라.', `MaleText_loc4`='我们在奥格瑞玛的探子如何了？（城市被岩石沙砾吞没，但眼睛能看到它的核心）把眼睛拿给我。', `MaleText_loc5`='我們在奧格瑪的間諜們呢?(城市被岩石和沙子吞沒，我們看到了!眼睛看到了城市的未來。)將「眼睛」帶給我。', `MaleText_loc7`='¿Y nuestros agentes en Orgrimmar? (Ciudad cubierta de piedra y arena, ¡la vemos! El Ojo ve su corazón.) Tráiganme el Ojo.' WHERE `ID`=47432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(신성 모독이다! 신성 모독, 역겨워, 미워, 미워...) 상관없다. 한쪽 눈이 감기면, 다른 쪽 눈이 열린다. (주인님은 다 본다! 주인님은 다 안다!) 우리는 적의 심장을 들여다본다. 놈들은 약해. 눈을 가져와라. 당장.', `MaleText_loc4`='（混蛋，可恶的混蛋，恨，恨啊……）没关系。一只眼睛闭上，另一只会睁开。（主人无所不知！主人无所不见！）我们将洞悉敌人的内心。他们是软弱的。给我眼睛。给我眼睛。', `MaleText_loc5`='(褻瀆!褻瀆...噁心...恨恨...)無所謂。當一隻眼睛闔上時，另一隻便會打開。(主人看清一切!主人無所不知!)我們可以窺視敵人的心意，因為他們脆弱。「眼睛」，給我。', `MaleText_loc7`='(¡Blasfemia! Blasfemia, asco, odio, odio...) No importa. Un Ojo se cierra, pero otro se abre. (¡El Amo lo ve todo! ¡El Amo lo sabe todo!) Veremos los corazones del enemigo porque son débiles. El Ojo. Ya.' WHERE `ID`=47433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 뻗었다!', `MaleText_loc4`='干掉那个了！', `MaleText_loc5`='那傢伙爆了!', `MaleText_loc7`='¡Explotado!' WHERE `ID`=47434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전하 흐름 시전이 끝나기 전에 피하십시오!

|Tinterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `MaleText_loc4`='在静电熔合爆炸前躲开！|TInterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `MaleText_loc5`='在靜電竄流爆炸前移動離開!

|TInterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `MaleText_loc7`='¡Aléjate antes de que explote el flujo estático!

|TInterfaceIconsability_vehicle_electrocharge.blp:32|t', `FemaleText_loc1`='전하 흐름 시전이 끝나기 전에 피하십시오!

|Tinterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `FemaleText_loc4`='在静电熔合爆炸前躲开！|TInterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `FemaleText_loc5`='在靜電竄流爆炸前移動離開!

|TInterface\\Icons\\ability_vehicle_electrocharge.blp:32|t', `FemaleText_loc7`='¡Aléjate antes de que explote el flujo estático!

|TInterfaceIconsability_vehicle_electrocharge.blp:32|t' WHERE `ID`=47435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 어둠이 이 세상을 덮는다... (어둠. 온통 어두워.) 우리 적은 서로 싸운다. 고원 여기저기서. 바보들 같으니. (피다, 피.) 잠깐! 다른 놈이 있다!', `MaleText_loc4`='主人的暗影笼罩了这个世界……（黑暗，彻底的黑暗。）我们的敌人在高地上互相残杀。一群蠢货。（鲜血，鲜血。）等等！这儿有别人！', `MaleText_loc5`='主人的影子籠罩著這個世界...(黑暗，完全黑暗。)我們的敵人在高地的另一邊互相殘殺。蠢貨們。(血，血。)慢著!還有一個!', `MaleText_loc7`='La sombra del Amo cubre este mundo… (Oscuridad, todo oscuridad.) Nuestros enemigos pelean entre sí por toda Tierra Alta. Tontos. (Sangre, sangre.) ¡ESPEREN! ¡Hay otro!' WHERE `ID`=47436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자가 눈을 엿보고 있다! (으히히히히! 조그만 게 용감해!) 네가 보인다, 작은 자여! 눈이 보는 것을 보고 싶으냐? 응? (보여줘! 다 보여줘!)', `MaleText_loc4`='凡人竟敢偷窥这只眼睛！（勇敢的小玩具。）我看到你了！你想看看这眼睛看到的东西？（看看！给他们看看！）', `MaleText_loc5`='一個凡人竟敢凝視眼睛!(勇敢的小玩物。)我看到你了，弱小的人!你想知道眼睛中所看到的是什麼，對吧?(快出來!快出來!)', `MaleText_loc7`='¡Un mortal se atreve a mirar por el ojo! (Juguetito intrépido.) ¡Te veo, pequeñito! Quieres ver lo que ve el Ojo, ¿no? (¡Muéstralo! ¡Muéstralo todo!)' WHERE `ID`=47437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈이 다가오는 것을 봐라. (광기, 광기, 진정한 행복!) 마음에 드는 광경이냐, 필멸자여? (으하하하하하!)', `MaleText_loc4`='见证混沌的降临吧。（疯狂，疯狂，疯狂！）喜欢你看到的吗，凡人？', `MaleText_loc5`='準備迎接混沌。(瘋狂，瘋狂，上天堂!)你喜歡你所見的嗎，凡人?', `MaleText_loc7`='Contempla el caos venidero. (¡Locura, locura, gozo!) ¿Te gusta lo que ves, mortal?' WHERE `ID`=47438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(주인님이 너 본다! 다 본다! 주인님이 원해. 원해...)', `MaleText_loc4`='（主人看见你了！看见了！看见了！他想要！想要想要……）', `MaleText_loc5`='(主人看到你了!他看到!他看到!他要!他要他要他要他要...)', `MaleText_loc7`='(¡El amo te ve! ¡Él ve! ¡Él ve! El quiere, el quiere, quiere y quiere...)' WHERE `ID`=47439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각했던 것보다 훨씬 훌륭한 솜씨를 보여주는군.', `MaleText_loc4`='你的作战能力比我料想的更强。', `MaleText_loc5`='你的戰技比我想的還厲害。', `MaleText_loc7`='Tu destreza en combate es mayor de lo que esperaba.' WHERE `ID`=47440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 좋네. 안마당 문을 열고 계속 전진하지!', `MaleText_loc4`='很好，让我们打开院子的大门，这样就能继续我们的任务了！', `MaleText_loc5`='很好，讓我們打開中庭的門，繼續執行任務!', `MaleText_loc7`='Muy bien. ¡Abramos la puerta del patio para que podamos continuar con nuestra misión!' WHERE `ID`=47441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자물쇠를 여는 게 그리 어렵진 않을 걸세.', `MaleText_loc4`='这把锁应该能轻易地打开。', `MaleText_loc5`='這個鎖應該很容易就可以打開。', `MaleText_loc7`='Esta cerradura no debería ser difícil de forzar.' WHERE `ID`=47442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐네!', `MaleText_loc4`='我们走！', `MaleText_loc5`='搞定!', `MaleText_loc7`='¡Ya está!' WHERE `ID`=47443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 햇빛이 가려지게 거기 잠깐만 서 계실래요?$b$b그래 주시면 정말 고맙겠어요...', `MaleText_loc4`='你是否介意用你的暗影将太阳封锁一会儿？$b$b这样会很不错……', `MaleText_loc5`='嘿，可不可以幫個忙站過去擋一下陽光?$b$b那樣舒服多了...', `MaleText_loc7`='Oye, ¿te importaría tapar el sol con tu sombra un momento?$b$bEstaría genial...' WHERE `ID`=47444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아요, 난 오늘 어째 일할 마음이 안 들어요.', `MaleText_loc4`='要知道，今天我并不是很想工作。', `MaleText_loc5`='你知道嗎，我今天實在沒心情工作。', `MaleText_loc7`='Hoy no me apetece mucho trabajar, ¿sabes?' WHERE `ID`=47445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 너무 더워서 도무지 일할 수가 없어요. 게다가 이런 제복까지 입고 있으니 말이에요.', `MaleText_loc4`='在这里工作实在是太热了——特别是还要穿着这身制服。', `MaleText_loc5`='這邊實在熱到沒辦法工作 - 尤其是穿著這個制服。', `MaleText_loc7`='Aquí fuera hace demasiado calor para trabajar, especialmente con estos uniformes.' WHERE `ID`=47446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 와서 일하면 엄청난 부자가 될 수 있다는 약속을 했었단 말이에요.$b$b말도 안 되는 소리!', `MaleText_loc4`='他们向我承诺过，可以在这里得到巨大的财富。$b$b这可真是个不错的笑话！', `MaleText_loc5`='是他們跟我說可以賺大錢我才來這邊的。$b$b真是笑話!', `MaleText_loc7`='Me prometieron una fortuna considerable por venir hasta aquí.$b$b¡Menudo fraude!' WHERE `ID`=47447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사람들이 우리를 개처럼 부려 먹고 있는데, 우린 돈도 얼마 못 받는다고요!', `MaleText_loc4`='他们让我们像狗一样工作。我们却什么也没得到！', `MaleText_loc5`='我們被操得跟狗一樣，結果卻什麼也沒有分到!', `MaleText_loc7`='¡Nos tienen explotados como perros y no nos dan nada a cambio!' WHERE `ID`=47448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠는 우리가 일한 덕분에 떼돈을 벌고 있는데... 우리 몫은 어디 있나요?', `MaleText_loc4`='司克诺兹因为我们发了大财……但我们呢？！', `MaleText_loc5`='我們幫舒諾茲賺大錢...但是我們的錢呢?!', `MaleText_loc7`='Schnottz está amasando una fortuna a nuestra costa... ¡¿Dónde está la nuestra?!' WHERE `ID`=47449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으름 피울 생각은 그만둬! 일정이 늦어지고 있어...', `MaleText_loc4`='别偷懒了！你已经跟不上进度了……', `MaleText_loc5`='偷懶夠了!你們工作進度落後了...', `MaleText_loc7`='¡Basta de vagancia! Llevas retraso...', `FemaleText_loc1`='게으름 피울 생각은 그만둬! 일정이 늦어지고 있어...', `FemaleText_loc4`='别偷懒了！你已经跟不上进度了……', `FemaleText_loc5`='偷懶夠了!你們工作進度落後了...', `FemaleText_loc7`='¡Basta de vagancia! Llevas retraso...' WHERE `ID`=47450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일을 하려고 여기까지 온 건 아닌데...', `MaleText_loc4`='我可没有为这种事签过字……', `MaleText_loc5`='這跟當初講好的不一樣...', `MaleText_loc7`='No me alisté para esto...' WHERE `ID`=47451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스를 떠나지 말았어야 했어요.', `MaleText_loc4`='我根本就不应该离开塔纳利斯。', `MaleText_loc5`='我真不該離開塔納利斯。', `MaleText_loc7`='Nunca debería haberme ido de Tanaris.' WHERE `ID`=47452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사막유랑단으로 살 때가 좋았지...', `MaleText_loc4`='我就像废土一样快乐。', `MaleText_loc5`='當廢土強盜的時候還比較快活些。', `MaleText_loc7`='Era más feliz cuando era un Vagayermos.' WHERE `ID`=47453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러거나 말거나. 우리가 언제 일정을 맞춘 적이 있었나요?', `MaleText_loc4`='是啊，是啊。我们什么时候没有耽误过进度？', `MaleText_loc5`='是啊是啊，我們的工作進度有什麼時候是沒落後的?', `MaleText_loc7`='Ya, ya. ¿Y cuándo no llevamos retraso?' WHERE `ID`=47454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저 미친 녀석 말은 듣지 않겠어요!', `MaleText_loc4`='我绝不再为这种疯子工作了！', `MaleText_loc5`='我不要再為那個瘋子工作了!', `MaleText_loc7`='¡Voy a dejar de trabajar para ese maníaco!' WHERE `ID`=47455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 좀 저 독재자에게 전해 주시라고요!', `MaleText_loc4`='你帮我带个口信给那个暴君！', `MaleText_loc5`='有句話請你幫我轉告那個暴君!', `MaleText_loc7`='¡Quiero que le entregues un mensaje a ese tirano!' WHERE `ID`=47456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 온 뒤로 봉급을 받은 적이 없어요! 이곳도 이제 지긋지긋해요!
', `MaleText_loc4`='自从我到这里之后，就没有得到过任何报酬！我已经厌倦了这个地方！', `MaleText_loc5`='到這兒之後我就沒有再領過工資了!我已經受夠了這個地方!', `MaleText_loc7`='¡No me han pagado desde que llegué! ¡Me voy de este sitio!' WHERE `ID`=47457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 더운 데 일할 수는 없어요!
', `MaleText_loc4`='我一直被迫在高温环境中工作！', `MaleText_loc5`='我不想在這種高溫下工作了。!', `MaleText_loc7`='¡Ya estoy harto de trabajar con este calor!' WHERE `ID`=47458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠의 거짓말에 속아 넘어갔다니, 정말 믿을 수가 없어요! 이딴 일은 그만두겠어요!', `MaleText_loc4`='真无法想象，我竟然会相信司克诺兹的谎言！跑到了这里！', `MaleText_loc5`='不敢相信，我竟然被舒諾茲的謊話給騙了!我要離開這裡!', `MaleText_loc7`='¡No me puedo creer que me tragara las mentiras de Schnottz! ¡Yo me largo!' WHERE `ID`=47459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 뭔가 대단한 걸 시전하고 있습니다! 막아야 해요!', `MaleText_loc4`='他要有大动作了！阻止他！', `MaleText_loc5`='他在施展什麼東西!阻止他!', `MaleText_loc7`='¡Va a lanzar algo grande! ¡Detenlo!', `FemaleText_loc1`='놈이 뭔가 대단한 걸 시전하고 있군요! 막아야 해요!', `FemaleText_loc4`='他要有大动作了！阻止他！', `FemaleText_loc5`='他在施展什麼東西!阻止他!', `FemaleText_loc7`='¡Va a lanzar algo grande! ¡Detenlo!' WHERE `ID`=47460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블스가 여기 있었다면 기분이 어땠겠나?$b$b응?', `MaleText_loc4`='你觉得哥培尔如果在这里，会怎么看你？嗯？', `MaleText_loc5`='你覺得咯咯會對你有什麼看法，如果他還在的話?$b$b嗯?', `MaleText_loc7`='¿Cómo crrrees que se sentiría Gluber si estufiera aquí?$b$b¿Hmm?' WHERE `ID`=47461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식이 그렇게 엉망으로 끝났으니, 넌 내게 큰 빚을 졌어, $r.$b$b그리고 난 받을 빚은 잊지 않는 사람이거든!', `MaleText_loc4`='现在那个仪式完蛋了。你欠我一大笔债，$r。$b$b我会让你还的！', `MaleText_loc5`='這是儀式失敗之後你欠我的，$r。$b$b而且我要跟你討債了!', `MaleText_loc7`='Después de la catástrrrofe del rrritual, me lo defes, $r.$b$b¡Y tengo pensado cobrrrarme la deuda!' WHERE `ID`=47462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 조용히 하십시오. 저 친구들이 다음 교대까지 쉴 수 있는 시간은 30분뿐입니다. 당신이 방해하게 두지는 않겠습니다.', `MaleText_loc4`='保持安静。他们只有三十分钟休息时间，我不能让你打扰他们。', `MaleText_loc5`='安靜一點。他們只有三十分鐘的休息時間，我不希望你去吵他們。', `MaleText_loc7`='Guarda silencio. Solo tienen turnos de descanso de treinta minutos, y no dejaré que los molestes.', `FemaleText_loc1`='여기선 조용히 하세요. 저 친구들이 다음 교대까지 쉴 수 있는 시간은 30분뿐입니다. 당신이 방해하게 두지는 않겠어요.', `FemaleText_loc4`='保持安静。他们只有三十分钟休息时间，我不能让你打扰他们。', `FemaleText_loc5`='安靜一點。他們只有三十分鐘的休息時間，我不希望你去吵他們。', `FemaleText_loc7`='Guarda silencio. Solo tienen turnos de descanso de treinta minutos, y no dejaré que los molestes.' WHERE `ID`=47463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 우리의 탈출을 자축하는 의미에서 한잔 마시고 있습니다. 지금까지 생각해 봤는데...$b$b우릴 공격한 그 난쟁이들이 죗값을 치르도록 해야 합니다!$b$b제대로 대응하지 못하면, 아무런 방어 태세 없이 이곳에 발을 들이는 모험가들이 모두 노예로 팔려갈지도 모릅니다. 물론 더 나쁜 일이 생길 수도 있고요!', `MaleText_loc4`='听着，自从我们逃出来之后，我稍微庆祝了一下，喝了几杯。然后我一直在想……$b$b那些攻击我们的小人应该得到正义的惩罚！$b$b如果我们不为此做些事情，那么每一个没有准备就进入那个地方的探险家都会变成奴隶被卖掉，或者遭遇更可怕的事情！', `MaleText_loc5`='聽著，在我們逃走之後，我是有喝了點小酒慶祝一下。然後我一直在想...$b$b偷襲我們的那些小傢伙一定得受到教訓!$b$b否則的話，每個毫無防備來到這邊的探險者都會被賣去當奴隸，甚至更慘!', `MaleText_loc7`='Escucha, desde que escapamos me he estado tomando un par de copas de celebración, y se me ha ocurrido...$b$b¡Debemos llevar a esos hombrecitos que nos asaltaron ante la justicia!$b$bSi no hacemos algo, entonces todos los exploradores desprevenidos que pongan un pie en este sitio van a acabar vendidos como esclavos... ¡o algo peor!' WHERE `ID`=47464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 차원문으로 들어가면 톨 바라드로 갈 수 있습니다.', `MaleText_loc4`='这道传送门对面就是托尔巴拉德。', `MaleText_loc5`='穿過這道傳送門，托巴拉德在等著你。', `MaleText_loc7`='Al otro lado de este portal te espera Tol Barad.', `FemaleText_loc1`='이 차원문으로 들어가면 톨 바라드로 갈 수 있습니다.', `FemaleText_loc4`='这道传送门对面就是托尔巴拉德。', `FemaleText_loc5`='穿過這道傳送門，托巴拉德在等著你。', `FemaleText_loc7`='Al otro lado de este portal te espera Tol Barad.' WHERE `ID`=47465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어. 자, 이제 역병을 퍼뜨리고 다음 지역으로...', `MaleText_loc4`='太好了。在这个地区播散过魔法之后，就转移到……', `MaleText_loc5`='太好了。現在，把瘟疫施放在這個地方，然後移到 -', `MaleText_loc7`='Excelente. Ahora, apestaremos la zona y pasaremos a...' WHERE `ID`=47466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로무쉬! 여기서 무얼 하고 있소? 이것은 비밀 작전이오!', `MaleText_loc4`='克鲁姆什！你在这里干什么？这是一次秘密行动！', `MaleText_loc5`='克洛姆什!你在做什麼?這是秘密行動!', `MaleText_loc7`='¡Cromush! ¿Qué estás haciendo aquí? ¡Esta es una operación encubierta!' WHERE `ID`=47467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잘못 기억하는 게 아니라면, 대족장님께서 전면적인 역병 사용을 완전히 금지하셨던 것 같소만. 그 어떤 상황에서라도 말이오.', `MaleText_loc4`='如果我没有理解错误，酋长是严格禁止这种魔法被全面使用的，无论在什么样的情况下。', `MaleText_loc5`='除非是我弄錯了，但是大酋長有特別交代，不論在何種狀況之下都禁止使用高濃度的瘟疫。', `MaleText_loc7`='Si no me equivoco, el Jefe de Guerra prohíbe expresamente el uso de la peste pura, sin importar las circunstancias.' WHERE `ID`=47468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사과드리오, 크로무쉬. 하지만 정말 아무런 문제도 없소. 우리는 효력을 엄청나게 약화시킨 역병을 사용하고 있소.', `MaleText_loc4`='很抱歉，克鲁姆什，但我可以向你保证，我们的行动绝无问题。我们使用的是一种效能被减弱的魔法。', `MaleText_loc5`='抱歉，克洛姆什，但是我向你保證絕對不會有問題的，我們用的是極度稀釋過的瘟疫。', `MaleText_loc7`='Mis disculpas, Cromush, pero te aseguro que no hay ningún problema. Utilizamos una peste extremadamente diluida.' WHERE `ID`=47469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 쫓아오려고 하는 늑대인간을 겁주는 정도밖에 효력이 없는 역병이라오. 전혀 위험하지 않소.', `MaleText_loc4`='实际上，这种魔法顶多只能吓唬一下那些狼人，让他们不敢追踪我们到这里来。它是完全无害的。', `MaleText_loc5`='事實上，它的目的只是要嚇嚇那些狼人不要再追我們而已。它是完全無害的。', `MaleText_loc7`='De hecho, solo sirve para que los huargen no se atrevan a seguirnos hasta aquí. Es totalmente inofensiva.' WHERE `ID`=47470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 당신의 임무에 내가 동행을 청해도 거절하지 않으리라 믿소.', `MaleText_loc4`='那么我相信，如果我陪同你完成这个任务，你是不会介意的。', `MaleText_loc5`='那麼我相信你應該不會介意我陪你一起執行任務才對。', `MaleText_loc7`='Entonces no te importará que te acompañe en esta misión.' WHERE `ID`=47471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 경고하겠소, 벨몬트. 거짓말을 하고 있음이 밝혀지면...', `MaleText_loc4`='我警告你，贝尔蒙特。如果我发现你在说谎……', `MaleText_loc5`='我警告你，貝爾蒙特，要是我發現你在說謊的話...', `MaleText_loc7`='Te lo advierto, Belmont. Si descubro que mientes...' WHERE `ID`=47472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 대족장님의 분노를 몸소 느껴야 할 거요.', `MaleText_loc4`='你将第一个承受酋长的怒火。', `MaleText_loc5`='你將會親自見識到大酋長的憤怒。', `MaleText_loc7`='Conocerás de primera mano la ira del Jefe de Guerra.' WHERE `ID`=47473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 처치하면 여주인께서 상금을 주시겠지!', `MaleText_loc4`='只要干掉你们，女主人就会大大的奖赏我。', `MaleText_loc5`='拿下你們的頭，女主人會付我很多錢!', `MaleText_loc7`='¡La maestra me pagará mucho por sus cabezas!' WHERE `ID`=47474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뻥 날리자! 하하하하!', `MaleText_loc4`='炸弹来啦！哈哈哈哈哈！', `MaleText_loc5`='開炸啦!', `MaleText_loc7`='¡Bombas fuera!' WHERE `ID`=47475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미련퉁이야! 던져!
', `MaleText_loc4`='准备好了吗，傻大个？扔吧！', `MaleText_loc5`='好了嗎歐弗?丟吧!', `MaleText_loc7`='¿Listo, bobi? ¡Tira!
' WHERE `ID`=47476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자 주제에! 감히 우리 성소에 발을 들이다니! (불신자. 이단자! 모두 불타버려!)
 너희는 돌아갈 수 없는 죽음의 문턱을 넘어섰다. (활활 타라! 이단자는 불타라.)', `MaleText_loc4`='凡人！你们胆敢侵入我们的内部圣殿。（无信者。异教徒！烧吧，烧吧。）
你们既然越过了界线，就别想回头。（烧吧，烧吧，异教徒燃烧吧。）', `MaleText_loc5`='凡人們!你們竟敢侵入我們聖所的內部。(不信者。異教徒!燒啊...燒啊)
你們越過了界線，已經無法回頭了。(燒啊，燒啊，燒光異教徒。', `MaleText_loc7`='¡Mortales! Osan invadir nuestro sagrario. (Escépticos. ¡Herejes! Ardan, ardan...)
 Pasaron un umbral del que no habrá regreso. (Ardan, ardan, los heréticos arderán.)' WHERE `ID`=47477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할푸스! 잘 듣거라! (주인님이 부른다. 주인님이 원한다.) 비밀을 보호하라, 할푸스. 침입자들을 처단하라. (명예를 위해 처단하고 배고파서 처단한다.)', `MaleText_loc4`='哈尔弗斯！听我号令！（主人在召唤，主人想要）保护我们的秘密，哈尔弗斯。消灭入侵者。（为主人的荣耀，为主人的欲望，杀！）', `MaleText_loc5`='哈福斯!聽好!(主人在呼喚，主人要)保護我們的秘密，哈福斯。消滅入侵者。(為了祂的榮耀和飢餓屠殺。)', `MaleText_loc7`='¡Halfus! ¡Escúchame! (El Amo llama, el Amo desea...) Protege nuestros secretos, Halfus. Destruye a los intrusos. (Maten por Su gloria. Maten por Su ansia.)' WHERE `ID`=47478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이오. 우리는 언제나 호드에게 가장 이득이 되는 방향으로 행동하오, 장군. 이 영웅들은 우리를 위해 스프링베일을 처치하러 가려던 참이었소.', `MaleText_loc4`='当然，长官。我们有最让部落感兴趣的东西。这些英雄刚刚要继续进军，为我们消灭斯普林瓦尔。', `MaleText_loc5`='但當然啦，我們會把部落的最佳利益擺在心裡，長官。這幾位英雄正準備要繼續行動，幫我們殺掉斯普林瓦爾 。', `MaleText_loc7`='Pero, claro. Lo único que tenemos en mente son los intereses de la Horda, señor. Esos héroes estaban a punto de matar a Vallefont para nosotros.' WHERE `ID`=47479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼!', `MaleText_loc4`='不……不！', `MaleText_loc5`='不...不!', `MaleText_loc7`='No... ¡NO!' WHERE `ID`=47480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살점과 근육, 약골들이 날뛰는군. 감히 주인님께 반항하다니... 비틀비틀 장님처럼 방황하네. 얽히고설킨 운명과 혼돈.', `MaleText_loc4`='血肉之躯，虽弱犹荣。他们竟胆敢窥视主人的秘密？他们盲目的挣扎求索，发现命运交织于混沌。', `MaleText_loc5`='血肉和筋骨，脆弱卻驕傲。主人的計畫他們敢阻撓?他們又跌又撞又笨又瞎。才發現自身命運自顧不暇。', `MaleText_loc7`='Carne y nervios, débiles pero orgullosos. Irán tras el amo, será monstruoso. Se acercan a los tumbos y se hunden, donde destino y caos se funden.' WHERE `ID`=47481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='월든 경 주변 지역을 확보하라고 내 부하들을 먼저 지붕 위로 보냈네.', `MaleText_loc4`='我已经派我的部下到屋顶上去，守住沃登勋爵周围的区域。', `MaleText_loc5`='我會派人前進到屋頂上，封住瓦爾登領主周遭的區域。', `MaleText_loc7`='He enviado a mis hombres a los tejados para que aseguren la zona alrededor de Lord Walden.' WHERE `ID`=47482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 거기까지 가는 길에 있는 소규모 병력은 누군가 알아서 처리해 줘야겠지.', `MaleText_loc4`='当然，总得有人去处理这两个地方之间的那支小军队。', `MaleText_loc5`='當然啦，還是得先有人解決掉這裡和那邊中間的小部隊。', `MaleText_loc7`='Pero claro está, alguien va a tener que encargarse del pequeño ejército que hay entre allí y aquí.' WHERE `ID`=47483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음추적자 사령관 벨몬트가 미소 짓습니다.', `MaleText_loc4`='死亡猎手指挥官贝尔蒙特咧嘴一笑。', `MaleText_loc5`='亡靈哨兵指揮官貝爾蒙特笑了起來。', `MaleText_loc7`='El comandante Mortacechador Belmont sonríe.' WHERE `ID`=47484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 형제들이여, 황혼이 깃들었다! (길어진 그림자, 끝없는 밤.) 데스윙 님이 세상을 가르셨으니... (한 번 열린 문은 닫히지 않아.) 진정한 주인들이 돌아오리라. (주인님이 오신다, 오신다, 오신다.)', `MaleText_loc4`='混沌的兄弟们，暮光已至！（暗影延伸，无尽的黑夜。）死亡之翼割裂了世界。（门一打开就无法关闭。）以便让真正的主人返回。（主人来了。他来了，他来了。）', `MaleText_loc5`='混沌的兄弟們，暮光已來臨!(暗影延伸，夜晚無盡。)死亡之翼已經割裂世界。(門一旦開了就不再關。)使它真正的主人得以回歸。(主人要來了，快了快了。)', `MaleText_loc7`='¡Hermanos del caos, llega el Crepúsculo! (Las sombras crecen en las noches eternas.) Alamuerte ha hendido este mundo. (Las puertas nunca se cierran.) Para que sus Amos regresen. (Viene el Amo, aquí viene.)' WHERE `ID`=47485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔다, 병사들이여! 고드프리가 바로 앞에 있다! 자비를 보이지 마라! 우리는...', `MaleText_loc4`='时间到了，士兵们！高弗雷就在前面！不要有任何怜悯之心。我们要……', `MaleText_loc5`='士兵們，時候到了!高佛雷就在前方!殺無赦!我們 -', `MaleText_loc7`='¡Ha llegado la hora, soldados! ¡Godfrey está justo al frente! ¡No tengan piedad! Luchamos...' WHERE `ID`=47486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!!!', `MaleText_loc4`='为部落而战！！！', `MaleText_loc5`='為了部落而戰!!!', `MaleText_loc7`='¡¡...POR LA HORDA!!' WHERE `ID`=47487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸의 존재들. 똥 된장도 구분 못 하는 어리석은 것들. (멍청이, 멍청이.)', `MaleText_loc4`='凡人，你们不过是在替我们筛选真正的虔诚者。（微不足道，微不足道。）', `MaleText_loc5`='凡人們，你們只是把粗糠過濾掉而已!(不夠格，不夠格。)', `MaleText_loc7`='Mortales, sólo separaron el grano de la paja. (Indignos, indignos.)' WHERE `ID`=47488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들도 재미를 보고 싶다면 서두르는 게 좋을 게야.', `MaleText_loc4`='如果不想错过所有这些乐趣，最好快一点。', `MaleText_loc5`='不想錯過樂子的話你就得加快動作。', `MaleText_loc7`='Será mejor que te des prisa si quieres formar parte de la diversión.' WHERE `ID`=47489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 부름에 응답하라! 이단자들을 즉시 처단하라!', `MaleText_loc4`='听从他的召唤！干掉异教徒！', `MaleText_loc5`='傾聽他的呼喚!趕走異教徒!', `MaleText_loc7`='¡Oigan Su llamado! ¡Eliminen a los herejes!' WHERE `ID`=47490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 이 저주받을 녀석! 1분 내로 돌아올 테니까 기다려. 두고 보자고!', `MaleText_loc4`='啊！诅咒你！给我小心了，我再过一分钟就会回来！', `MaleText_loc5`='呃啊!可惡!看好了，我馬上就會起來!', `MaleText_loc7`='¡Aaagh! ¡Maldita sea! ¡Volveré en un minutos, ya verás!' WHERE `ID`=47491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 꺼져, 꼬마야. 날 귀찮게 하지 마!', `MaleText_loc4`='快走开，小子，你惹到我了！', `MaleText_loc5`='走開，小鬼，你吵到我了!', `MaleText_loc7`='¡Vete de aquí, $gchaval:chavala;. ¡Me estás molestando!' WHERE `ID`=47492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 알라마 그림을 소개해 드리겠습니다.', `MaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，阿拉玛尔·格里姆。', `MaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:阿拉瑪爾·格里姆。', `MaleText_loc7`='Sígueme, $n, y te presentaré a tu instructor, Alamar Grimm.', `FemaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 알라마 그림을 소개해 드릴게요.', `FemaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，阿拉玛尔·格里姆。', `FemaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:阿拉瑪爾·格里姆。', `FemaleText_loc7`='Sígueme, $n, y te presentaré a tu instructor, Alamar Grimm.' WHERE `ID`=47493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알라마, 당신에게 $n|1을;를; 소개해 드리고 싶습니다. 최근 놈리건에서 빠져나왔지요.', `MaleText_loc4`='阿拉玛尔，请允许我向你介绍$n，他刚从诺莫瑞根逃出来。', `MaleText_loc5`='阿拉瑪爾，我跟你介紹一下，這位是$n，剛從諾姆瑞根逃出來的。', `MaleText_loc7`='Alamar, me gustaría presentarte a $n. Acaba de escapar de Gnomeregan.', `FemaleText_loc1`='알라마, 당신에게 $n|1을;를; 소개해 드리고 싶어요. 최근 놈리건에서 빠져나왔답니다.', `FemaleText_loc4`='阿拉玛尔，请允许我向你介绍$n，他刚从诺莫瑞根逃出来。', `FemaleText_loc5`='阿拉瑪爾，我跟你介紹一下，這位是$n，剛從諾姆瑞根逃出來的。', `FemaleText_loc7`='Alamar, me gustaría presentarte a $n. Acaba de escapar de Gnomeregan.' WHERE `ID`=47494;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 숲에 악이 만연하는 게 우리 명가 때문임을 잘 알아요.$B$B그러나 또한, 자신의 실수를 보상하려고 애쓴 명가의 일원이 저뿐이지는 않습니다. 제가 도울 수 있게 융통성을 발휘해준 에메랄드 의회에 감사드려요.', `FemaleText_loc4`='我很清楚，出现在这座森林中的恶魔是因为我们一族犯下的错误。$B$B我应该不是第一个想要对此进行弥补的上层精灵。感谢翡翠议会能够不计前嫌，接受我的帮助。', `FemaleText_loc5`='我非常清楚這片森林裡的惡魔污染或可歸因於我同胞們的誤失。$B$B但我並非首位意圖彌補這一切的精靈貴族，同時我也很感謝翡翠議會願意捐棄成見，允許我來提供協助。', `FemaleText_loc7`='Soy muy consciente de que la presencia demoníaca de este bosque se le puede achacar a mi raza.$b$bPero tampoco soy la primera Altonato que intenta expiarse, y le agradezco al Círculo Esmeralda que tenga el pragmatismo de aceptar mi ayuda.' WHERE `ID`=47495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 선택받은 존재다. (널 부르신다, 주인님은 널 알아.) 살점으로 빚어지고... (살점!) 피로 정화된... (피!) 불멸의 존재!', `MaleText_loc4`='你们是他的天选者。（他在召唤你，他认识你。）生有肉体（肉体），鲜血净涤（鲜血），注定获得不朽！', `MaleText_loc5`='你們就是被他所選中的對象。(他呼喚著你，他認識你。)生具肉體 - (血肉)由血淨化 - (鮮血)註定會不朽!', `MaleText_loc7`='Ustedes son Sus elegidos… (Los llama, los conoce.) Nacidos de la carne… (Carne.) Purificados con sangre… (Sangre.) ¡Destinados a la inmortalidad!' WHERE `ID`=47496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치단의 형제들이여, 내게 오라! (놈들의 의지가 살아 있다.) 불신자들이 아직 살아 있다. 놈들을 처치하라! (놈들의 뼈를 부수고 의지를 꺾어라.)', `MaleText_loc4`='暮光之锤的兄弟，来吧！（他们的意志仍属于自己。）无信者还没倒下。毁灭他们！（粉碎身体，粉碎意志。）', `MaleText_loc5`='暮光之錘的兄弟們，來吧!(他們的意志沒人在乎。)不信者還在。消滅他們!(摧毀他們身體，摧毀他們意志。)', `MaleText_loc7`='¡Hermanos del Martillo, a mí! (Su voluntad aún es suya.) Los escépticos siguen en pie. ¡Destrúyanlos! (Aplasta sus cuerpos y voluntad.)' WHERE `ID`=47497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차라리... 그냥 죽는 게 낫겠어...', `MaleText_loc4`='这……比死亡……更可怕……', `MaleText_loc5`='這比...死亡...還要更慘...', `MaleText_loc7`='Esto es... peor... que la muerte...' WHERE `ID`=47498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 뭐가 이렇게 축축해!?', `MaleText_loc4`='啊！为什么你湿了！？', `MaleText_loc5`='呃!你為什麼是「濕」的!?', `MaleText_loc7`='¡Agh! ¡¿Por qué chorreas!?' WHERE `ID`=47499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 문이 닫혀 있지? 실바나스 님이시여... 대체 무슨 일이 생긴 거지...', `MaleText_loc4`='为什么这道门关上了？以希尔瓦娜斯的名义，这里到底发生了什么……', `MaleText_loc5`='門為什麼是關的?這兒到底是怎麼回事...', `MaleText_loc7`='¿Por qué está cerrada la puerta? En el nombre de Sylvanas, ¿qué está pasando aquí...?' WHERE `ID`=47500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이... 희미하게... 죽는 건가? 아니야, 그냥 잠드는 것뿐이야...', `MaleText_loc4`='生命……消褪……死亡？不，只是入睡……', `MaleText_loc5`='光...黯淡...熄滅? 不，只是沉睡了...', `MaleText_loc7`='La luz... se va... ¿me muero? No, solo duermo...' WHERE `ID`=47501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로무쉬! 무슨 일이오?', `MaleText_loc4`='克鲁姆什！出了什么事？', `MaleText_loc5`='克洛姆什!怎麼回事?', `MaleText_loc7`='¡Cromush! ¿Qué ha pasado?' WHERE `ID`=47502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회가 스톰윈드 왕궁 북서쪽 호수의 작은 섬 위에 세계 곳곳으로 통하는 차원문을 만들었습니다.

