UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비겁한 자식이... 병사들을 죽이고... 내게... 독을...', `MaleText_loc4`='那些懦夫……让我中了毒……杀了他们……', `MaleText_loc5`='那個懦夫...殺了他們...對我...下毒...', `MaleText_loc7`='Cobarde... los mató... y... me envenenó...' WHERE `ID`=47504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='편견이나 고대의 원한이 우리의 임무를 막지 못하게 하세요, 칼도레이. 이곳에서의 일이 끝나고 나면 그런 일로 다투거나 의심할 시간은 충분할 테니까요.', `FemaleText_loc4`='不要让偏见和古老的仇恨干扰我们的任务，卡多雷。等到我们把这里的事情做完，会有足够的时间争吵和怀疑。', `FemaleText_loc5`='別讓偏見與古老的仇怨干擾了我們在此處的任務，卡多雷。等這裡的事情辦完之後，再來爭吵與猜疑吧。', `FemaleText_loc7`='No permitas que los prejuicios o los antiguos rencores interfieran con nuestra misión, kaldorei. Habrá tiempo de sobra para las rencillas y las miradas de desconfianza cuando hayamos terminado.' WHERE `ID`=47505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 어디서 웬 오우거가...', `MaleText_loc4`='他……是……从哪里……来的……', `MaleText_loc5`='他...是從...哪裡..來的...', `MaleText_loc7`='De... dónde... vino...' WHERE `ID`=47506;
