UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 고드프리를 처치하게! 무엇도 자네들을 방해하지 못하게 하겠네!', `MaleText_loc4`='英雄们，你们必须消灭高弗雷！我会掩护你们，确保你们不受干扰！', `MaleText_loc5`='英雄們，你們一定得殺掉高佛雷!我會確保沒有東西來干擾你們!', `MaleText_loc7`='¡Héroes, deben matar a Godfrey! ¡Me aseguraré de que nada interfiera!' WHERE `ID`=47511;
