UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하사관님, $n|1을;를; 소개해 드립니다. 우리가 놈리건에서 생존자들을 구출하는 것을 도와주셨습니다.', `MaleText_loc4`='军士，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。', `MaleText_loc5`='中士，容我向你介紹$n，$g他:她;幫我們在諾姆瑞根救了許多生還者。', `MaleText_loc7`='Sargento, permíteme que te presente a $n, quien nos ha ayudado a rescatar a los supervivientes de Gnomeregan.', `FemaleText_loc1`='하사관님, $n|1을;를; 소개해 드릴게요. 우리가 놈리건에서 생존자들을 구출하는 것을 도와주셨답니다.', `FemaleText_loc4`='军士，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。', `FemaleText_loc5`='中士，容我向你介紹$n，$g他:她;幫我們在諾姆瑞根救了許多生還者。', `FemaleText_loc7`='Sargento, permíteme que te presente a $n, quien nos ha ayudado a rescatar a los supervivientes de Gnomeregan.' WHERE `ID`=47517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발리오나, 테랄리온, 놈들을 처치하라.', `MaleText_loc4`='瓦里昂娜，瑟纳利昂，送他们上路。', `MaleText_loc5`='瓦莉歐娜，瑟拉里恩，解決掉他們吧。', `MaleText_loc7`='Valiona, Theralion, pónganlos en su lugar.' WHERE `ID`=47518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 켈시 스틸스파크를 소개해 드리겠습니다.', `MaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，凯尔希·钢烁。', `MaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:凱爾希·鋼火。', `MaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, Kelsey Chispacero.', `FemaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 켈시 스틸스파크를 소개해 드릴게요.', `FemaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，凯尔希·钢烁。', `FemaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:凱爾希·鋼火。', `FemaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, Kelsey Chispacero.' WHERE `ID`=47519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='켈시, $n|1을;를; 소개해 드리겠습니다. 우리가 놈리건에서 생존자들을 구출해내는 것을 도와주신 분입니다.', `MaleText_loc4`='凯尔希，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。', `MaleText_loc5`='凱爾希，容我向你介紹$n，$g他:她;幫我們在諾姆瑞根救了許多生還者。', `MaleText_loc7`='Kelsey, permíteme que te presente a $n, quien nos ha ayudado a rescatar a los supervivientes de Gnomeregan.', `FemaleText_loc1`='켈시, $n|1을;를; 소개해 드릴게요. 우리가 놈리건에서 생존자들을 구출해내는 것을 도와주신 분이랍니다.', `FemaleText_loc4`='凯尔希，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。', `FemaleText_loc5`='凱爾希，容我向你介紹$n，$g他:她;幫我們在諾姆瑞根救了許多生還者。', `FemaleText_loc7`='Kelsey, permíteme que te presente a $n, quien nos ha ayudado a rescatar a los supervivientes de Gnomeregan.' WHERE `ID`=47520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테 말씀하신 거다, 발리오나. 나는 바쁜 몸이라 누굴 공격할 시간이 없다.', `MaleText_loc4`='主人显然是在跟你说话，瓦里昂娜。我可没空去攻击谁。', `MaleText_loc5`='主人顯然是在跟你說話，瓦莉歐娜。我根本沒空攻擊任何人。', `MaleText_loc7`='Es claro que el amo te hablaba a ti, Valiona. Yo estoy demasiado ocupado.' WHERE `ID`=47521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 쓸모없는 놈이라 했나? 어머니가 왜 날 제일 좋아하시는지 보여주지!', `MaleText_loc4`='你竟敢说我没用！好好看着，为什么我是母亲最宠爱的孩子！', `MaleText_loc5`='你竟敢說我是廢物!你馬上會知道為什麼母親最喜歡我!', `MaleText_loc7`='¡Te atreves a llamarme inútil! ¡Verás por qué soy la favorita de mi madre!' WHERE `ID`=47522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님 말씀 못 들었나, 테랄리온! 저놈들을 없애!', `MaleText_loc4`='照主人说的做，瑟纳利昂！杀了他们！', `MaleText_loc5`='瑟拉里恩，聽從主人的命令!殺光他們!', `MaleText_loc7`='¡Obedece a tu amo, Theralion! ¡Mátalos!' WHERE `ID`=47523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테랄리온, 이 쓸모없는 놈. 으아아아아!', `MaleText_loc4`='你可真没用，瑟纳利昂！啊——啊！', `MaleText_loc5`='你這個廢物，瑟拉里恩!', `MaleText_loc7`='¡Qué inútil eres, Theralion!' WHERE `ID`=47524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 여기 있다. 작은 드워프한테 훔친 거야.', `MaleText_loc4`='给，这是我从小矮人那里偷来的。', `MaleText_loc5`='拿去，我跟小小矮人偷來的。', `MaleText_loc7`='Mira, yo robar esto de enanito.' WHERE `ID`=47525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 친구 잠깐 졸릴 거야. 돌머리가 안다. 돌머리도 그랬었어.', `MaleText_loc4`='他要睡上一会儿了。隆克知道。隆克以前也是这样。', `MaleText_loc5`='他會想睡覺一下。郎克知道。郎克有做過。', `MaleText_loc7`='Él dormir un rato. Ñoño saber. Ñoño hacer esto antes.' WHERE `ID`=47526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다. 너 드워프 물건 가져가도 된다.', `MaleText_loc4`='给，这是矮人的东西。', `MaleText_loc5`='拿去，你可以拿走矮人的東西。', `MaleText_loc7`='Toma, quedarte cosas del enano.' WHERE `ID`=47527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 드워프 물건 가져가. 안 죽여도 돼.', `MaleText_loc4`='拿到矮人的东西就行。不需要杀掉他们。', `MaleText_loc5`='你拿走矮人的東西。不用殺殺。', `MaleText_loc7`='Toma cosas del enano. No hacer falta matar.' WHERE `ID`=47528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앉는 거 죽이는 거보다 쉬워.', `MaleText_loc4`='坐下总比战斗容易。', `MaleText_loc5`='坐坐比殺殺簡單。', `MaleText_loc7`='Sentar más fácil que matar.' WHERE `ID`=47529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있다.', `MaleText_loc4`='给你。', `MaleText_loc5`='拿去吧。', `MaleText_loc7`='Ahí tienes.' WHERE `ID`=47530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 빕시 프로스트플링어를 소개해 드리겠습니다.', `MaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，贝西·冰雹。', `MaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:畢普希·霜擲。', `MaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, Bipsi Lanzaescarcha.', `FemaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 빕시 프로스트플링어를 소개해 드릴게요.', `FemaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，贝西·冰雹。', `FemaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:畢普希·霜擲。', `FemaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, Bipsi Lanzaescarcha.' WHERE `ID`=47531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빕시, 이분은 $n|1이라고;라고; 합니다. 가장 최근에 놈리건에서 올라온 생존자죠.', `MaleText_loc4`='贝西，请允许我为你介绍$n，最近从诺莫瑞根出来的生还者之一。', `MaleText_loc5`='畢普希，這位是$n，最近剛從諾姆瑞根逃出來的。', `MaleText_loc7`='Bipsi, te presento a $n, $guno:una; de $glos últimos:las últimas; supervivientes en salir de Gnomeregan.', `FemaleText_loc1`='빕시, 이분은 $n|1이라고;라고; 해요. 가장 최근에 놈리건에서 올라온 생존자랍니다.', `FemaleText_loc4`='贝西，请允许我为你介绍$n，最近从诺莫瑞根出来的生还者之一。', `FemaleText_loc5`='畢普希，這位是$n，最近剛從諾姆瑞根逃出來的。', `FemaleText_loc7`='Bipsi, te presento a $n, $guno:una; de $glos últimos:las últimas; supervivientes en salir de Gnomeregan.' WHERE `ID`=47532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 "의사" 코그스핀을 소개해 드리겠습니다.', `MaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，“怪医”克斯宾', `MaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:『醫生』科士賓。', `MaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, "Doc" Rotadiente.', `FemaleText_loc1`='따라오세요, $n. 당신을 가르쳐줄 "의사" 코그스핀을 소개해 드릴게요.', `FemaleText_loc4`='跟我来，$n。我会把你介绍给你的训练师，“怪医”克斯宾', `FemaleText_loc5`='跟我來，$n，我介紹你的訓練師給你認識:『醫生』科士賓。', `FemaleText_loc7`='Sígueme, $n, y te presentaré a tu instructora, "Doc" Rotadiente.' WHERE `ID`=47533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코그스핀 님, 이분은 $n|1이라고;라고; 합니다. 네빈의 구조대가 놈리건의 생존자들을 많이 구해내도록 도와주신 분이죠.', `MaleText_loc4`='医生，请允许我为你介绍$n，他帮助内温的队伍从诺莫瑞根救出了许多幸存者。', `MaleText_loc5`='醫生，這位是$n，$g他:她;幫納文的團隊從諾姆瑞根救了不少生還者出來。', `MaleText_loc7`='Doc, te presento a $n. Ha ayudado al equipo de Nevin a rescatar a varios supervivientes de Gnomeregan.', `FemaleText_loc1`='코그스핀 님, 이분은 $n|1이라고;라고; 해요. 네빈의 구조대가 놈리건의 생존자들을 많이 구해내도록 도와주신 분이랍니다.', `FemaleText_loc4`='医生，请允许我为你介绍$n，他帮助内温的队伍从诺莫瑞根救出了许多幸存者。', `FemaleText_loc5`='醫生，這位是$n，$g他:她;幫納文的團隊從諾姆瑞根救了不少生還者出來。', `FemaleText_loc7`='Doc, te presento a $n. Ha ayudado al equipo de Nevin a rescatar a varios supervivientes de Gnomeregan.' WHERE `ID`=47534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 좀 여기서 꺼내줘! 여기 엘프 냄새가 나!', `MaleText_loc4`='我们离开这里！这里有一股精灵味！', `MaleText_loc5`='放我出去!這裡有精靈的臭味!', `MaleText_loc7`='¡Sácame de aquí! ¡Huele a ELFOS!' WHERE `ID`=47535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이비가 날 팔아먹었군! 이 자식이 날 팔아먹은 거야!', `MaleText_loc4`='尼比出卖了我！他出卖了我！', `MaleText_loc5`='尼比出賣了我!他出賣了我!!!', `MaleText_loc7`='¡Niby me ha vendido! ¡ME HA VENDIDO!' WHERE `ID`=47536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러지 마! 나에겐 나만의 영혼의 조각이 있단 말이야!', `MaleText_loc4`='你不能这样做！我有我自己的灵魂碎片！', `MaleText_loc5`='你不能這麼做!我有我自己的靈魂裂片!', `MaleText_loc7`='¡No puedes hacer eso! ¡Tengo mi propio fragmento de alma!' WHERE `ID`=47537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(가까이, 더 가까이... 얼굴을 우리에게 보여줘. 모두 그분 앞에 무릎 꿇게 될 거야.)', `MaleText_loc4`='（近点儿，再近点儿。让我们看看你们的脸。所有人都将屈从于他的力量。）', `MaleText_loc5`='(來近一點，近一點。讓我們看看你的臉。一切都將臣服在他的力量下。)', `MaleText_loc7`='(Acérquense, acérquense. Déjennos ver sus rostros. La voluntad se postra ante Su poder.)' WHERE `ID`=47538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 머저리처럼 그렇게 흔들고 다녀야겠어?!', `MaleText_loc4`='别像个白痴一样的摇晃袋子行吗？！', `MaleText_loc5`='你「一定」要表現得跟個白癡一樣嗎?!', `MaleText_loc7`='¡¿TIENES que menearte por ahí como si fueras un idiota!?' WHERE `ID`=47539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 왜 이렇게 뜨거워! 아, 내 발이었구나.', `MaleText_loc4`='这里可真烫！等等，那是我的脚。', `MaleText_loc5`='裡面燒起來了!等等，只是我的腳而已。', `MaleText_loc7`='¡Aquí dentro está ardiendo! Espera, es solo mi pie.' WHERE `ID`=47540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가게만 해주면 세 가지 소원을 들어줄게! 내가 맹세해!', `MaleText_loc4`='放我出去，我会让你实现三个愿望！我发誓！', `MaleText_loc5`='放我出去，我會實現你三個願望!我發誓!', `MaleText_loc7`='¡Déjame salir y te concederé tres deseos! ¡Lo juro!' WHERE `ID`=47541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아홉, 아홉, 아홉 개! 아니야! 내 말이 그렇게 어려워?!', `MaleText_loc4`='九个，九个，九个！到底有什么会这样难以理解？！', `MaleText_loc5`='九!九!九!!!!到底有啥麼難懂的?!', `MaleText_loc7`='¡Nuefe, nuefe, NUEFE! ¡¿Acaso es tan difícil de entenderrr?!' WHERE `ID`=47542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방첨탑의 비밀은 곧 내 것이 될 거라고!', `MaleText_loc4`='我将得到允诺之箱的秘密……然后，我将得到整个世界！', `MaleText_loc5`='方尖碑的秘密很快就會是我的了!', `MaleText_loc7`='¡Los secrrretos del obelisco pronto serrrán míos!' WHERE `ID`=47543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬릭스가 $n의 가슴에 폭탄을 답니다!', `MaleText_loc4`='赫利克斯在$n的身上安了一颗炸弹！', `MaleText_loc5`='赫利克斯把一個炸彈裝到$n的胸口!', `MaleText_loc7`='¡Helix pega una bomba al pecho de $n!' WHERE `ID`=47544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약속의 성궤도 이제 거의 내 손에 들어왔어!', `MaleText_loc4`='应许约柜……就要是我的了！', `MaleText_loc5`='應許法櫃...就快要落入我的手中了!', `MaleText_loc7`='¡El arrrka de la promesa está a mi alcance!' WHERE `ID`=47545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물이 아주 멋지게 쌓여가고 있어... 곧 나를 막을 수 있는 자는 아무도 없을 거야!', `MaleText_loc4`='这些财宝可真漂亮……用不了多久，就没有人能阻挡我了！', `MaleText_loc5`='財寶堆得越來越高...很快就沒有人能阻止我了!', `MaleText_loc7`='El tesorrro se amontona dentrrro, tan ordenadamente... ¡Pronto no habrrrá nada que me detenga!' WHERE `ID`=47546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변 덕분에 내겐 좋은 일만 생기는군.', `MaleText_loc4`='这场大灾变可真是合我的胃口。', `MaleText_loc5`='這場大災變真是我的大好時機。', `MaleText_loc7`='Todo esto del Cataclismo me ha rrresultado muy ventajoso.' WHERE `ID`=47547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n의 겁쟁이 같은 행동을 눈치채고 번개를 뿌립니다!', `MaleText_loc4`='%s感觉到$n的怯懦，便释放出一道闪电！', `MaleText_loc5`='%s察覺到了$n的懦弱，射出一道閃電!', `MaleText_loc7`='¡%s siente la cobardía de $n y desata una explosión de relámpagos!' WHERE `ID`=47548;
