UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 말할게! 다 말하면 되잖아! 그 냄새나는 가방이나 좀 치워!', `MaleText_loc4`='我会说的，我会说的！我什么都说！赶快把这个怪味袋子从我面前拿开！', `MaleText_loc5`='我說，我說!我什麼都說!不要再拿那個香水袋子套我了!', `MaleText_loc7`='¡Hablaré, hablaré! ¡Cualquier cosa! ¡Pero aleja esa bolsa perfumada de mí!' WHERE `ID`=47554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 온 줄도 눈치채지 못한 채 똑바로 앞을 보고 꼿꼿이 서 있는 뮬란 그리핀 기수>', `MaleText_loc4`='<穆兰狮鹫骑士纹丝不动，双目凝视前方，仿佛完全没有意识到你的出现。>', `MaleText_loc5`='<穆蘭獅鷲騎士佇立不動，目光凝視前方，絲毫不理會你。>', `MaleText_loc7`='<El jinete de grifos Mullan permanece inmóvil, con los ojos fijos hacia delante, como si no hubiera notado tu presencia.>', `FemaleText_loc1`='<당신이 온 줄도 눈치채지 못한 채 똑바로 앞을 보고 꼿꼿이 서 있는 뮬란 그리핀 기수>', `FemaleText_loc4`='<穆兰狮鹫骑士纹丝不动，双目凝视前方，仿佛完全没有意识到你的出现。>', `FemaleText_loc5`='<穆蘭獅鷲騎士佇立不動，目光凝視前方，絲毫不理會你。>', `FemaleText_loc7`='<El jinete de grifos Mullan permanece inmóvil, con los ojos fijos hacia delante, como si no hubiera notado tu presencia.>' WHERE `ID`=47555;
