UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거야 원, 투지가 불끈 솟는 말이로군요!', `MaleText_loc4`='这是明显的挑衅！', `MaleText_loc5`='那肯定是要打架的話!', `MaleText_loc7`='¡Esas son TOTALMENTE palabras de pelea!', `FemaleText_loc1`='이거야 원, 투지가 불끈 솟는 말이로군요!', `FemaleText_loc4`='这是明显的挑衅！', `FemaleText_loc5`='那肯定是要打架的話!', `FemaleText_loc7`='¡Esas son TOTALMENTE palabras de pelea!' WHERE `ID`=47557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가족을 모두 대피시키십시오! 놈들이 여기 있는 사람 모두를 해치고 있습니다!', `MaleText_loc4`='让你们的妻子躲起来！让你们的孩子躲起来！他们会杀掉这里所有的人！', `MaleText_loc5`='把老婆藏起來!把小孩藏起來!他們在殺這邊全部的人!', `MaleText_loc7`='¡Escondan a sus mujeres! ¡Escondan a sus hijos! ¡Aquí arriba están matando a todo el mundo!' WHERE `ID`=47558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 모두를 해치고 있습니다! 당장 막아야 합니다! 이렇게요!!', `MaleText_loc4`='他们要杀死所有人！要摧毁一切！就像这样！', `MaleText_loc5`='他們到處亂跑在殺人!把人踩死!就像這樣!!', `MaleText_loc7`='¡Están corrrriendo y matando todo lo que se mueve! ¡Pisoteándolo! ¡¡Así de fácil!!' WHERE `ID`=47559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 지금 당장!', `MaleText_loc4`='当然，先生！马上就办！', `MaleText_loc5`='是，長官!馬上!', `MaleText_loc7`='¡Porrr supuesto, señorrr! ¡Inmediatamente!' WHERE `ID`=47560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕궁 교역소에서 성물회 일원을 찾아보시오. 분명히 그들 중에 당신을 도울 고고학자가 있을 것이오.', `MaleText_loc4`='在皇家贸易区找到神圣遗物学会。毫无疑问，那个组织中的诸多考古学家之一会在那里帮助你。', `MaleText_loc5`='到皇家交易所去找聖匣守護者的人，他們那兒有許多位考古者，應該可以幫得了你。', `MaleText_loc7`='Busca El Relicario en el Intercambio Real. Sin duda alguno de los numerosos arqueólogos de la organización andará por allí y podrá ayudarte.', `FemaleText_loc1`='왕궁 교역소에서 성물회 일원을 찾아보시오. 분명히 그들 중에 당신을 도울 고고학자가 있을 것이오.', `FemaleText_loc4`='在皇家贸易区找到神圣遗物学会。毫无疑问，那个组织中的诸多考古学家之一会在那里帮助你。', `FemaleText_loc5`='到皇家交易所去找聖匣守護者的人，他們那兒有許多位考古者，應該可以幫得了你。', `FemaleText_loc7`='Busca El Relicario en el Intercambio Real. Sin duda alguno de los numerosos arqueólogos de la organización andará por allí y podrá ayudarte.' WHERE `ID`=47561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 기다리고 있소? 당장 나가서 놈들을 막으시오!', `MaleText_loc4`='你还在等什么？赶快去阻止他们！', `MaleText_loc5`='你還在等什麼?滾過去阻止他們!', `MaleText_loc7`='¿A qué estás esperando? ¡Sal ahí fuera y detenlos!' WHERE `ID`=47562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 좋습니다! 이번엔 당신이 이겼습니다.', `MaleText_loc4`='太好了，太好了！你赢了。', `MaleText_loc5`='好!好，這回算你贏了。', `MaleText_loc7`='¡Vale! Vale. Tú ganas esta vez.', `FemaleText_loc1`='좋아요. 좋다고요! 이번엔 당신이 이겼어요.', `FemaleText_loc4`='太好了，太好了！你赢了。', `FemaleText_loc5`='好!好，這回算你贏了。', `FemaleText_loc7`='¡Vale! Vale. Tú ganas esta vez.' WHERE `ID`=47563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='높은 지위의 성물회 구성원만 금고실의 위치를 알고 있습니다.$B$B어떤 이들은 금고실은 우리가 속한 차원에 존재하지 않는다고도 합니다.', `FemaleText_loc4`='只有神圣遗物学会最高阶的成员知道我们的大殿堂在哪里。$B$B甚至有人说，大殿堂根本就不存在于这个位面……', `FemaleText_loc5`='只有聖匣守護者最高階的成員知道我們組織的大藏寶庫位在何處。$B$B有人說它根本不在我們所存在的次元裡...', `FemaleText_loc7`='Solo los miembros de mayor rango del Relicario saben dónde está la Gran Cámara de nuestra orden.$b$bHay quien dice que ni siquiera está en este plano de la existencia...' WHERE `ID`=47564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더글라스 님이 보냈다고요? 매운맛 좀 보라는 게죠.', `MaleText_loc4`='道格拉斯就派你过来挨揍了？', `MaleText_loc5`='杜格拉斯是派你過來討打的嗎?', `MaleText_loc7`='¿Te ha enviado Duglas para que te den un repaso?', `FemaleText_loc1`='더글라스 님이 보냈다고요? 매운맛 좀 보라는 게죠.', `FemaleText_loc4`='道格拉斯就派你过来挨揍了？', `FemaleText_loc5`='杜格拉斯是派你過來討打的嗎?', `FemaleText_loc7`='¿Te ha enviado Duglas para que te den un repaso?' WHERE `ID`=47565;
