UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저랑 한판 하고 싶으신 눈친데요...', `MaleText_loc4`='看上去，你想要从我这里得到些什么……', `MaleText_loc5`='你好像很想嚐嚐我拳頭的樣子...', `MaleText_loc7`='Tienes pinta de querer desafiarme...', `FemaleText_loc1`='저랑 한판 하고 싶으신 눈친데요...', `FemaleText_loc4`='看上去，你想要从我这里得到些什么……', `FemaleText_loc5`='你好像很想嚐嚐我拳頭的樣子...', `FemaleText_loc7`='Tienes pinta de querer desafiarme...' WHERE `ID`=47567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 맞고 싶으신 모양입니다만?', `MaleText_loc4`='想受惩罚吗？', `MaleText_loc5`='想接受點懲罰嗎?', `MaleText_loc7`='¿Buscas pelea?', `FemaleText_loc1`='좀 맞고 싶으신 모양입니다만?', `FemaleText_loc4`='想受惩罚吗？', `FemaleText_loc5`='想接受點懲罰嗎?', `FemaleText_loc7`='¿Buscas pelea?' WHERE `ID`=47568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역사? 문화? 그런 건 학자와 서기의 몫이오.$B$B우리 성물회는... 현재와 미래에만 관심이 있소.$B$B우리는 잃어버린 유물, 재산, 지식 등을 찾아내서 획득하고 수집해서 누군가 그런 것들을 우리를 상대로 사용하지 못하도록 막을 뿐이오. 힘은 그것을 가장 적절하게 사용할 수 있는 자에게만 허락되는 것이오. 동감하지 않소?', `MaleText_loc4`='历史？文化？这些都是学者和抄写员关心的事情。$B$B我们神圣遗物学会关心的是……当前，或者也许是未来。$B$B我们发现、获取并收藏失落的宝物、财富和学识，以确保它们不会被别人利用来对抗我们。毕竟，力量只属于能够充分利用它的人……难道你不同意吗？', `MaleText_loc5`='歷史?文化?嘖，那是尋常學者和文人的領域。$B$B我們聖匣守護者關注的是...現在，可能還有未來。$B$B我們發現，取得，並且囤積失落的文物、財富，以及知識，以確保這些東西無法被拿來對付我們。畢竟，力量最好還是歸於那些最善於使用它的人手中...你也同意吧?', `MaleText_loc7`='¿Historia? ¿Cultura? Bah. Ese es el campo de los eruditos y los escribas.$b$bLos del Relicario nos preocupamos de... lo inmediato, y quizá lo futuro.$b$bDescubrimos, adquirimos y almacenamos artefactos perdidos, tesoros y sabiduría para que nadie los pueda utilizar contra nosotros. Después de todo, el poder pertenece a quien le daría mejor uso... ¿no estás de acuerdo?' WHERE `ID`=47569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부인을 대피시키십시오! 아이들도 보호해야 합니다! 나... 남편도 대피시키시고요! 놈들이 여기 있는 사람 모두를 해치고 있습니다!', `MaleText_loc4`='让你们的妻子躲起来！让你们的孩子躲起来！让你们的丈夫躲起来！！他们会杀掉这里所有的人！', `MaleText_loc5`='把老婆藏起來!把孩子藏起來!把老公藏起來!!他們在這裡大開殺戒了!', `MaleText_loc7`='¡Escondan a sus mujeres! ¡Escondan a sus hijos! ¡E-escondan a sus marrridos! ¡Aquí arriba están matando a todo el mundo!' WHERE `ID`=47570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 날 이 해적들로부터 구할 거야, 말 거야?!', `MaleText_loc4`='$n，你要从那些海盗手中拯救我们，否则还能怎样？！', `MaleText_loc5`='$n，你到底要不要把我們從這些海盜的手中救走?!', `MaleText_loc7`='$n, ¡¿vas a salvarnos de esos piratas o qué?!' WHERE `ID`=47571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 이 해적들로부터 구해주시면 안 될까요, 친애하는 $n 님?!', `FemaleText_loc4`='我是否能请求你从那些海盗手中拯救我们，亲爱的$n？！', `FemaleText_loc5`='親愛的$n，把我們從這些海盜的手中救走吧?!', `FemaleText_loc7`='¡¿Podría sugerir que nos salves de esos piratas, $gquerido:querida; $n?!' WHERE `ID`=47572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미련한 놈들을 상대하는데 미련퉁이는 필요 없지!', `MaleText_loc4`='有你们这些蠢货，我就不需要他了！', `MaleText_loc5`='只要解決你們這些蠢蛋，我就不需要他了!', `MaleText_loc7`='¡No lo necesito si te tengo a TI, bobo!' WHERE `ID`=47573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애걔, 10 코퍼? 처치해도 보람이 없네.', `MaleText_loc4`='才10个铜币？杀你还真不划算！', `MaleText_loc5`='只有10銅?你們根本不值得殺!', `MaleText_loc7`='¿Sólo 10 cobres? ¡Ni vale la pena matarte!' WHERE `ID`=47574;
