UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가인 호새크 찾나 보다. 마법사 지구 남쪽 부분에 있지. 내곽에 말이다.', `MaleText_loc4`='你想找胡萨克大师？他就在内环法师区南部。', `MaleText_loc5`='你要找的人是霍沙克大師。他在法師區的南邊，內環的位置。', `MaleText_loc7`='Buscas al maestro Hossack. Está en la parte sur del Barrio de los Magos, en el círculo interior.', `FemaleText_loc1`='대가인 호새크 찾나 보다. 마법사 지구 남쪽 부분에 있지. 내곽에 말이다.', `FemaleText_loc4`='你想找胡萨克大师？他就在内环法师区南部。', `FemaleText_loc5`='你要找的人是霍沙克大師。他在法師區的南邊，內環的位置。', `FemaleText_loc7`='Buscas al maestro Hossack. Está en la parte sur del Barrio de los Magos, en el círculo interior.' WHERE `ID`=47577;
