UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아담 호새크를 찾나 보군. 남쪽 마법사 지구 내곽에 있는 사무실로 가면 만날 수 있네.$B$B발굴하러 가지 않았다면, 틀림없이 거기 있을 걸세.', `MaleText_loc4`='你会想要找到亚当·胡萨克的。他在内环法师区南部有一个办公室。$B$B如果他没有在外面进行探索工作，他应该就在那里。', `MaleText_loc5`='你想找的人是亞當·霍沙克。他在法師區南側內環的地方有個辦事處。$B$B只要他沒有出去探險，他應該都會待在那裡。', `MaleText_loc7`='Buscas a Adam Hossack. Su despacho está en el lado sur del Barrio de los Magos, en el círculo interior.$b$bSi no ha salido a explorar, seguramente esté allí.', `FemaleText_loc1`='아담 호새크를 찾나 보군. 남쪽 마법사 지구 내곽에 있는 사무실로 가면 만날 수 있네.$B$B발굴하러 가지 않았다면, 틀림없이 거기 있을 걸세.', `FemaleText_loc4`='你会想要找到亚当·胡萨克的。他在内环法师区南部有一个办公室。$B$B如果他没有在外面进行探索工作，他应该就在那里。', `FemaleText_loc5`='你想找的人是亞當·霍沙克。他在法師區南側內環的地方有個辦事處。$B$B只要他沒有出去探險，他應該都會待在那裡。', `FemaleText_loc7`='Buscas a Adam Hossack. Su despacho está en el lado sur del Barrio de los Magos, en el círculo interior.$b$bSi no ha salido a explorar, seguramente esté allí.' WHERE `ID`=47579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사할 거리가 끊이질 않는군.', `MaleText_loc4`='总有一些新东西需要调查。', `MaleText_loc5`='隨時都有新的事物可調查。', `MaleText_loc7`='Siempre hay algo nuevo que investigar.' WHERE `ID`=47580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할 말이 있거든 빨리 하게.', `FemaleText_loc4`='快一点。', `FemaleText_loc5`='有話快說。', `FemaleText_loc7`='Date prisa.' WHERE `ID`=47581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무엇도 밴시 여왕님의 분노를 막을 수 없네.', `MaleText_loc4`='任何人都无法阻挡女妖之王的怒火。', `MaleText_loc5`='女妖之王的憤怒無人可擋。', `MaleText_loc7`='Nada puede detener la cólera de la Reina alma en pena.' WHERE `ID`=47582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은송곳니 일족은 승리할 것이다.', `MaleText_loc4`='血牙将会崛起。', `MaleText_loc5`='血牙狼族終將獲勝。', `MaleText_loc7`='Los Colmillo de Sangre prevalecerán.' WHERE `ID`=47583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 아이스크림 제국을 확장할 때가 왔네요.$B$B티굴과 폴로르! 너흰 이제 끝장이다!', `MaleText_loc4`='我的冰激凌帝国将迅速发展壮大。提古勒和弗洛尔就要完了！', `MaleText_loc5`='該是擴張我的冰淇淋帝國的時候了。提古勒和弗洛爾準備倒閉吧!', `MaleText_loc7`='Hora de expandir mi imperio de helados.$b$b¡Tigule y Foror caerán!' WHERE `ID`=47584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오라, 필멸자여. (나약한 애송이들...) 이 성소에 발을 들인 자는 많지 않다. (맨손으로 불을 잡으려 드는 멍청이들!)', `MaleText_loc4`='欢迎你们，凡人。（脆弱之子。）鲜少有人能亲临这内部圣殿。（他们就要引火上身了！）', `MaleText_loc5`='歡迎，凡人們。(脆弱的孩子們。)很少有人親眼見過聖所的內部。(他們玩火自焚!)', `MaleText_loc7`='Bienvenidos, mortales. (Niñitos frágiles.) Pocos han visto este sagrario interior. (¡Buscan tocar el fuego!)' WHERE `ID`=47585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 보이나, 초갈? 곧 너를 잡으러 갈 것이다! 한 머리가 지켜보는 앞에서 다른 머리를 잘라내 주겠어!', `FemaleText_loc4`='看到我了吗，古加尔？我是来找你的！我要在你眼前砍掉你的头！', `FemaleText_loc5`='你看見我了嗎，丘加利?我要來找你算帳了!我要把你的頭給硬生生扭下來!', `FemaleText_loc7`='¿Me ves ahora, Cho''gall? ¡Voy a por ti! ¡Te voy a arrancar la cabeza mientras la otra mira!' WHERE `ID`=47586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 바로 선택받은 자들이 운명을 실현하는 곳이다. (영원으로!) 그리고 너희도 여기서 운명을 실현할 것이다. (육신의 파멸, 육신의 파멸!)', `MaleText_loc4`='天选者在此洞悉到他们的宿命。（永生不灭。）而你们也将在此直面你们的宿命。（终结血肉，终结血肉！）', `MaleText_loc5`='受選者都是在這裡了解到他們的宿命。(永劫不復。)你也會在這裡了解到你的。(血肉的末日。血肉的末日!)', `MaleText_loc7`='Aquí, los elegidos cumplen su destino. (Únanse a la eternidad.) Y aquí cumplirán el suyo. (El fin de la carne. ¡El fin de la carne!)' WHERE `ID`=47587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 형제들이여! 망치가 너희를 부르고 있다! (불, 물, 대지, 바람.) 필멸자의 껍데기를 벗어 던져라. (불, 물, 대지, 바람!) 새로운 모습으로 태어나라. 지금부터 영원히! (불타고, 물에 빠지고, 부서지고, 질식하고.) 너희가 얻은 능력으로 불신자들을 처치해라. (불타고, 물에 빠지고, 부서지고, 질식하고! 으하하하하!!)', `MaleText_loc4`='兄弟们！暮光之锤在呼唤你们！（火、水、土、气）蜕下你凡人的躯壳。(火、水、土、气）在此拥抱新的形态，直到永远！（燃烧、淹溺、碾压、窒息）用你们获得的恩赐消灭那些无信者。（燃烧、淹溺、碾压、窒息）！！', `MaleText_loc5`='兄弟們!暮光之錘在呼喚你們!(火水地風。)留下你們的凡人之軀。(火水地風。)從此以後，擁抱你們的新形態!(燒死淹死壓死悶死。)並使用你們的新力量來消滅不信者。(燒死淹死壓死悶死!!)', `MaleText_loc7`='¡Hermanos del Crepúsculo! ¡El Martillo los llama! (Fuego, agua, tierra, aire.) Dejen atrás sus corazas mortales. (Fuego, agua, tierra, aire.) ¡Abracen sus formas nuevas hasta la eternidad! (Quemen, ahoguen, aplasten y sofoquen.) ¡Y usen sus dones para destruir a los escépticos! (¡¡Quemen, ahoguen, aplasten y sofoquen!!)' WHERE `ID`=47588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 평정심을 잃지 마십시오.', `MaleText_loc4`='一定要保持镇定。', `MaleText_loc5`='隨時保持冷靜。', `MaleText_loc7`='Permanece estable siempre.' WHERE `ID`=47589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실바나스를 위하여!', `FemaleText_loc4`='为了希尔瓦娜斯！', `FemaleText_loc5`='希瓦娜斯萬歲!', `FemaleText_loc7`='¡Por Sylvanas!' WHERE `ID`=47590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 필멸자들아... (나약한 침입자들!) 너희가 행한 어떤 행위도, (작은 신의 탄생!) 이봐! 내가 지금 말하고 있잖아. (말, 말, 말. 주인님은 죽음을 원하지.) 모두 혼돈에 휩싸인다. 모두 파괴될 것이다. (혼돈, 혼돈!) 너희가 오늘 벌인 일은 아무것도 바꿀 수 없다. (혼돈, 혼돈, 모두 끝이야.) 하지만 너희는 너무 많은 것을 목격했다. 너희의 마지막 순간이다!', `MaleText_loc4`='愚蠢的凡人——（篡位者之子！）你的所为毫无意义——（劣等神之种！）你不要打断我说话。（听啊，听啊，听啊。主人渴望杀戮。）万物归于混沌。万物终将消亡。（混乱，混乱！）你今日的努力也无济于事。（混乱，混乱，一切都将终结）没有凡人能活着见证这一切。你的末日到了。', `MaleText_loc5`='愚蠢的凡人- (篡位者的孩子們!)你所做的都沒辦法 - (次級神的後代!)我正在說話!(說了，說了，說了。主人要殺人。)一切都歸於混沌。一切都會毀滅。(混沌，混沌!)你們今天做的一切改變不了什麼。(混沌，混沌，一切都會終結。)沒有凡人能見你所見還活下來。迎接你的死亡!', `MaleText_loc7`='Tontos mortales... (¡Niños del usurpador!) Nada de lo que han hecho ha... (¡Engendro de un dios inferior!) ¿Me DEJAN hablar? (Palabras, palabras, palabras. El Amo quiere muertes.) TODO será caos. TODO será destruido. (¡Caos, caos!) Lo que han hecho no cambia nada. (Caos, caos, todo se termina.) Ningún mortal que vea lo que ustedes vieron vivirá. Su fin ha llegado.' WHERE `ID`=47591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기록이 아주 엉망이야. 아루갈이 천재였던 건지 천치였던 건지 구별이 안 되는군.', `MaleText_loc4`='这些记录非常散乱。我无法判断阿鲁高到底是个天才，还是个彻头彻尾的傻瓜。', `MaleText_loc5`='這些筆記亂七八糟的，我實在不曉得阿魯高到底是天才還是白癡。', `MaleText_loc7`='Estas notas tienen una organización pésima. No sé distinguir si Arugal era un genio o solamente un estúpido.' WHERE `ID`=47592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아루갈 녀석, 조금은 인정해 줘야겠어. 녀석의 연구는 참으로 참신하군.', `MaleText_loc4`='我必须承认，阿鲁高的研究相当新颖。', `MaleText_loc5`='我不得不佩服阿魯高，他的有些研究觀點是挺有新意的。', `MaleText_loc7`='Arugal se merece cierto mérito, sus líneas de investigación fueron bastante innovadoras.' WHERE `ID`=47593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠진 기록, 망가진 장비, 오염된 표본! 어떻게 이런 환경에서 연구를 할 수가 있지?!', `MaleText_loc4`='散落的书页，残破的装备，被污染的样品！怎么会有人在这种环境里工作！', `MaleText_loc5`='遺失的書頁，損壞的設備，不純的樣本!在這種狀況下到底該怎樣做研究啊!', `MaleText_loc7`='¡Páginas que faltan, equipo roto, muestras contaminadas! ¿Cómo se puede trabajar en semejantes condiciones!' WHERE `ID`=47594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도서관에 있는 자료들은 내 연구에도 꽤 도움이 되겠어.', `MaleText_loc4`='这些藏书对我的研究非常有用。', `MaleText_loc5`='這間圖書室對我的研究應該相當有幫助。', `MaleText_loc7`='Esta biblioteca será útil para mi propia investigación.' WHERE `ID`=47595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 절단기 5000 작동 개시. 모든 시스템, 겨우 작동.', `MaleText_loc4`='死神5000型已就绪。系统全部正常。', `MaleText_loc5`='敵人收割者5000已啟動。所有系統就緒。', `MaleText_loc7`='Revientaenemigos 5000 en línea. Sistemas adecuados.' WHERE `ID`=47596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울다만 같은 곳에는 우리 드워프의 불가사의한 과거를 밝혀 줄 비밀이 숨겨져 있지요!', `MaleText_loc4`='像奥达曼这样的地方肯定隐藏着关系到我们一族过去的秘密！', `MaleText_loc5`='像奧達曼這樣的地方隱藏著我們族人歷史之謎的秘密!', `MaleText_loc7`='¡Los sitios como Uldaman contienen secretos sobre los misterios del pasado de mi gente!' WHERE `ID`=47597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보호막을 파괴하려면 이드라케스 여군주를 처치하십시오!', `MaleText_loc4`='消灭埃卓凯丝海妖，摧毁护盾！', `MaleText_loc5`='殺掉艾德拉奇斯仕女，破壞護盾!', `MaleText_loc7`='¡Mata a las maestras Idra''kess para destruir el escudo!' WHERE `ID`=47598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네스피라가 깨어나고 있습니다! 네스피라 점액으로 이드라케스를 처치하십시오.', `MaleText_loc4`='奈瑟匹拉正在醒过来！用奈瑟匹拉流体怪消灭埃卓凯丝。', `MaleText_loc5`='奈斯畢拉醒來了!使用奈斯畢拉體液來殺掉艾德拉奇斯。', `MaleText_loc7`='¡Nespirah se despierta! Utiliza el fluido de Nespirah para matar Idra''kess.' WHERE `ID`=47599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 찾는 시체는 데들로우 웜우드로군. 그는 주로 마을 남쪽 끝에 있다네.', `MaleText_loc4`='戴德洛·沃姆伍德就是你想要找的那具尸体。他经常会在这个镇子的南端。', `MaleText_loc5`='你要找的屍體就叫迪羅·蟲林。他通常位在本鎮的南邊。', `MaleText_loc7`='Dedlow Ajenjo es el cadáver que buscas. Suele andar por la zona sur de la ciudad.', `FemaleText_loc1`='자네가 찾는 시체는 데들로우 웜우드로군. 그는 주로 마을 남쪽 끝에 있다네.', `FemaleText_loc4`='戴德洛·沃姆伍德就是你想要找的那具尸体。他经常会在这个镇子的南端。', `FemaleText_loc5`='你要找的屍體就叫迪羅·蟲林。他通常位在本鎮的南邊。', `FemaleText_loc7`='Dedlow Ajenjo es el cadáver que buscas. Suele andar por la zona sur de la ciudad.' WHERE `ID`=47600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브릴의 유일한 요리사는 마을 한가운데 있네.$B$B그가 왜 거기 나와 있는지는 모르겠지만 분명히 자기가 만든 요리는 팔지 않을 거라네. 우린 그가 어디서 그렇게 신선한 생고기를 구해오는지도 모르겠다네.$B$B어쨌든 행운을 비네.', `MaleText_loc4`='布瑞尔唯一的厨师就在这个镇子的中心位置。$B$B我们不知道他为什么会在那里。而且他不出售任何他烹制的东西。我们也不知道他用来烹调的生肉都是从哪里来的。$B$B嗯，这些都是小事。祝你好运。', `MaleText_loc5`='布瑞爾唯一的廚師就在鎮中央的地方。$B$B其實我們不曉得他在那邊幹什麼，因為他沒有在賣他煮的任何東西，然後我們也不知道他的新鮮生肉都是從哪裡弄來的。$B$B反正，沒差啦。祝你好運。', `MaleText_loc7`='El único chef de Rémol está en el centro de la ciudad.$b$bNo sabemos por qué está ahí, nunca vende nada de lo que hace. Tampoco sabemos de dónde saca tanta carne fresca.$b$bBueno, da igual. Buena suerte.', `FemaleText_loc1`='브릴의 유일한 요리사는 마을 한가운데 있네.$B$B그가 왜 거기 나와 있는지 모르겠지만 분명히 자기가 만든 요리는 팔지 않을 거라네. 우린 그가 어디서 그렇게 신선한 생고기를 구해오는지도 모르겠다네.$B$B어쨌든 행운을 비네.', `FemaleText_loc4`='布瑞尔唯一的厨师就在这个镇子的中心位置。$B$B我们不知道他为什么会在那里。而且他不出售任何他烹制的东西。我们也不知道他用来烹调的生肉都是从哪里来的。$B$B嗯，这些都是小事。祝你好运。', `FemaleText_loc5`='布瑞爾唯一的廚師就在鎮中央的地方。$B$B其實我們不曉得他在那邊幹什麼，因為他沒有在賣他煮的任何東西，然後我們也不知道他的新鮮生肉都是從哪裡弄來的。$B$B反正，沒差啦。祝你好運。', `FemaleText_loc7`='El único chef de Rémol está en el centro de la ciudad.$b$bNo sabemos por qué está ahí, nunca vende nada de lo que hace. Tampoco sabemos de dónde saca tanta carne fresca.$b$bBueno, da igual. Buena suerte.' WHERE `ID`=47601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이스크림 좀 주십시오, 브리블스워프 님!', `MaleText_loc4`='冰激淋，布里维普。我要冰激淋！', `MaleText_loc5`='冰淇淋，布里維普。我需要冰淇淋!', `MaleText_loc7`='Helado, Bridatuer. ¡Necesito helado!', `FemaleText_loc1`='아이스크림 좀 주세요, 브리블스워프 님!', `FemaleText_loc4`='冰激淋，布里维普。我要冰激淋！', `FemaleText_loc5`='冰淇淋，布里維普。我需要冰淇淋!', `FemaleText_loc7`='Helado, Bridatuer. ¡Necesito helado!' WHERE `ID`=47602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 집게발을 드러내며 앞으로 몸을 기울입니다!', `MaleText_loc4`='%s向前倒下，暴露出他的钳子！', `MaleText_loc5`='%s往前撲倒，露出他的鉗子!', `MaleText_loc7`='¡%s cae hacia delante y deja expuestas sus tenazas!' WHERE `ID`=47603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 조금 바쁩니다, $c님. 뭘 도와드릴까요?', `MaleText_loc4`='我有点忙，$c。你要什么？', `MaleText_loc5`='我這兒有點忙，$c。你要做什麼?', `MaleText_loc7`='Estoy un poco ocupado, $c. ¿Qué quieres?' WHERE `ID`=47604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 도와드릴 거라도 있습니까?', `MaleText_loc4`='我能帮你些什么？', `MaleText_loc5`='我能幫上什麼忙嗎?', `MaleText_loc7`='¿Puedo ayudarte en algo?' WHERE `ID`=47605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까.', `MaleText_loc4`='嗯。', `MaleText_loc5`='是。', `MaleText_loc7`='Sí.' WHERE `ID`=47606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 춤추지 않으시겠습니까?', `MaleText_loc4`='想加入我们的舞蹈吗？', `MaleText_loc5`='要來一起跳個舞嗎?', `MaleText_loc7`='¿Te apetece unirte a nuestro baile?', `FemaleText_loc1`='함께 춤추실래요?', `FemaleText_loc4`='想加入我们的舞蹈吗？', `FemaleText_loc5`='要來一起跳個舞嗎?', `FemaleText_loc7`='¿Te apetece unirte a nuestro baile?' WHERE `ID`=47607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 비룡을 공격해 약화시키십시오!', `MaleText_loc4`='攻击并削弱黑色幼龙！', `MaleText_loc5`='攻擊，削弱黑龍!', `MaleText_loc7`='¡Ataca y debilita al draco negro!' WHERE `ID`=47608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증속 엔진 활성화.', `MaleText_loc4`='超速引擎已激活。', `MaleText_loc5`='加速驅動引擎已啟動。', `MaleText_loc7`='Motor de sobrecarga activado.' WHERE `ID`=47609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 종족 중 생각이 깨인 건 너희 부족뿐인 것 같군. 나둔 왕자를 붙잡아 준 데 대한 보답으로, 너희들의 천부적인 권리, 그리고 그 이상을 선물로 주겠다!', `MaleText_loc4`='你们部族只剩下你们还有些理智。既然你们将纳顿亲王交给我们，作为回礼，我将你们生来就应该继承的东西赐予你，另外，我还会赐予你们更多强大的礼物！', `MaleText_loc5`='你似乎是你們全族當中腦袋唯一還正常的。為了獎勵你把納登親王帶來給我們，我將賜予你超乎你所應得的贈禮!', `MaleText_loc7`='Ustedes son los últimos de su tribu con algo de sentido común. ¡Como recompensa por darnos al príncipe Nadun, les otorgo el don que es su derecho de nacimiento y más aún!' WHERE `ID`=47610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 창조주는 너희를 실패작으로 만들었다... 결함 있는 너희 종족은 육신의 저주에 굴복했지! 데스윙 군주님의 선물이 너희를 다시 완벽한 존재로 만들어줄 것이다!', `MaleText_loc4`='你们的造物主辜负了你们……听任你们被束缚在这种被诅咒的残缺肉体之中！但死亡之翼君王的赠礼却能让你们重新拥有完美的身体！', `MaleText_loc5`='你們的造物主失敗了...害你們受到血肉詛咒的影響而變得殘缺!但是，死亡之翼大人的贈禮能讓你們重歸完美!', `MaleText_loc7`='Sus hacedores les han fallado... ¡Su raza imperfecta ha sucumbido a la maldición de la carne! ¡El don de Lord Alamuerte les devolverá la perfección!' WHERE `ID`=47611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 높이 올라가려면 빠르게 날개짓을 하십시오!', `MaleText_loc4`='迅速拍打你的翅膀，重新恢复高度！', `MaleText_loc5`='快速拍動翅膀，重新爬升高度!', `MaleText_loc7`='¡Mueve tus alas rápidamente para recuperar altitud!' WHERE `ID`=47612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오크는 심하게 상처입었습니다.', `MaleText_loc4`='这个兽人受了重伤。', `MaleText_loc5`='這個獸人受了重傷。', `MaleText_loc7`='Este orco está gravemente herido.', `FemaleText_loc1`='이 오크는 심하게 상처입었습니다.', `FemaleText_loc4`='这个兽人受了重伤。', `FemaleText_loc5`='這個獸人受了重傷。', `FemaleText_loc7`='Este orco está gravemente herido.' WHERE `ID`=47613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음으로 오크를 고통에서 해방해 줍니다.', `MaleText_loc4`='结束这个兽人的痛苦。', `MaleText_loc5`='了結這個獸人的苦難。', `MaleText_loc7`='Acaba con el sufrimiento del orco.', `FemaleText_loc1`='죽음으로 오크를 고통에서 해방해 줍니다.', `FemaleText_loc4`='结束这个兽人的痛苦。', `FemaleText_loc5`='了結這個獸人的苦難。', `FemaleText_loc7`='Acaba con el sufrimiento del orco.' WHERE `ID`=47614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다만, 친구, 나는 보기보다 바쁜 사람이오.$b$b보시다시피 사령관님이 이 지역에서 발굴하신 내역을 문서로 만드는 임무를 맡았거든.$b$b정말 깊이 있는 고고학 자료가 될 거요.', `MaleText_loc4`='请原谅，朋友，但我的确是很忙。$b$b我受命为这一地区指挥官的发现进行公证。$b$b这些发现具有极为重大的意义！', `MaleText_loc5`='抱歉，朋友，但我其實是很忙的。$b$b你看，我得負責紀錄指揮官在這邊找到的所有發現。$b$b肯定會很浩瀚深奧的!', `MaleText_loc7`='Discúlpame, $gamigo:amiga;, pero estoy más ocupado de lo que parece.$b$bMe han encargado documentar los descubrimientos del Comandante en la región, ¿sabes?$b$b¡Seguro que son de lo más profundos!' WHERE `ID`=47615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 일도 많지만, 난 지금 슈노츠 사령관의 전기에 중점을 두고 있소.$b$b미안하지만 실례해야겠소.', `MaleText_loc4`='我有一个重要的任务，那就是为司克诺兹元首撰写传记。$b$b请原谅。', `MaleText_loc5`='除此之外，我還在幫指揮官舒諾茲撰寫一份個人傳記。$b$b抱歉，我得去忙了。', `MaleText_loc7`='Estoy trabajando en un artículo biográfico para el Comandante Schnottz, entre otras cosas.$b$bTendrás que disculparme.' WHERE `ID`=47616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리가 마땅히 지녀야 하는 힘, 그리고 그 이상의 힘을 네게 주겠다!', `MaleText_loc4`='我要赐予你的不仅是我们生来便应继承的力量，还有其它更加强大的礼物！', `MaleText_loc5`='我賜予你我們與生俱來的力量...以及其他更強更大的力量!', `MaleText_loc7`='¡Yo te confiero el poder que es nuestro derecho de nacimiento... Y más!' WHERE `ID`=47617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 남풍의 힘이 있다면, 우리는 이 도시를 되찾아 어느 누구도 침입할 수 없게 봉인할 수 있으리라!', `MaleText_loc4`='借助南风的力量，我们将夺回这座城市，让那些入侵我们国土的敌人再无法染指于它！', `MaleText_loc5`='以南風之力，我們將奪回這座城市，並且守住它，不讓任何外人闖入我們的領土!', `MaleText_loc7`='¡Y con los poderes del Viento del Sur, reclamaremos esta ciudad y la sellaremos para cerrarla a aquellos que quieren penetrar en nuestro territorio!' WHERE `ID`=47618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 투지는 아직 죽지 않았다!', `MaleText_loc4`='仗还没有打完呢，渣滓们。', `MaleText_loc5`='混帳，我還是能打的。', `MaleText_loc7`='Todavía puedo dar guerra, escoria.', `FemaleText_loc1`='내 투지는 아직 죽지 않았다!', `FemaleText_loc4`='仗还没有打完呢，渣滓们。', `FemaleText_loc5`='混帳，我還是能打的。', `FemaleText_loc7`='Todavía puedo dar guerra, escoria.' WHERE `ID`=47619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상당한 오크가 일어날 수 있게 도와줍니다.', `MaleText_loc4`='帮助受伤的兽人站起来。', `MaleText_loc5`='扶受傷的獸人起來。', `MaleText_loc7`='Ayuda al orco herido a levantarse.', `FemaleText_loc1`='부상당한 오크가 일어날 수 있게 도와줍니다.', `FemaleText_loc4`='帮助受伤的兽人站起来。', `FemaleText_loc5`='扶受傷的獸人起來。', `FemaleText_loc7`='Ayuda al orco herido a levantarse.' WHERE `ID`=47620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 크롬가르 부대에 물품을 조달한다네.', `MaleText_loc4`='我向克罗姆加的军队提供各种装备。', `MaleText_loc5`='我供應裝備給克羅姆加部隊。', `MaleText_loc7`='Yo proveo el equipo del ejército Krom''gar.' WHERE `ID`=47621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병참장교님, 어떤 물품이 있는지 보여주십시오.', `MaleText_loc4`='让我看看你的货物，军需官。', `MaleText_loc5`='軍需官，讓我看看你有什麼東西。', `MaleText_loc7`='Enséñame tu mercancía, intendente.', `FemaleText_loc1`='병참장교님, 어떤 물품이 있는지 보여주세요.', `FemaleText_loc4`='让我看看你的货物，军需官。', `FemaleText_loc5`='軍需官，讓我看看你有什麼東西。', `FemaleText_loc7`='Enséñame tu mercancía, intendente.' WHERE `ID`=47622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돈... 냄새가 나는군요!', `FemaleText_loc4`='闻起来像……黄金！', `FemaleText_loc5`='味道聞起來像...黃金!', `FemaleText_loc7`='¡Huele a... oro!' WHERE `ID`=47623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightnova.blp:20|t%s|1이;가; |cFFFF0000|Hspell:86788|h[의식 상실]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightnova.blp:20|t%s施放|cFFFF0000|Hspell:86788|h[眩晕]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightnova.blp:20|t%s施展了|cFFFF0000|Hspell:86788|h[昏天暗地]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightnova.blp:20|t¡%s lanza |cFFFF0000|Hspell:86788|h[Desmayo]|h|r!' WHERE `ID`=47624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼마 전에 유물을 잔뜩 배에 싣고 있는 모습을 봤습니다.$b$b그렇게 많은 황금을 한번에 본 일은 처음이었어요!', `FemaleText_loc4`='不久前，我看见他们向那些船上运送了一些古物。$b$b我还从没有见到过那么多黄金被堆在一起！', `FemaleText_loc5`='前幾日我看到他們把一批文物裝上了船。$b$b我這輩子從來沒看過那麼多的黃金擺在一起!', `FemaleText_loc7`='Les vi subir un cargamento de artefactos a los barcos el otro día.$b$b¡Nunca había visto tanto oro junto!' WHERE `ID`=47625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 년 전, 와이번을 연구하려다 이들에게 고립된 적이 있었습니다. 하지만 한 번 살아나간 후로, 전 이곳으로 돌아와 와이번들을 보호하기로 결심했죠.$B$B대격변이 닥치고 황혼의 망치단은 이 신성한 생명체를 모두 잡아들이거나, 심한 경우엔 죽이기까지 하고 있습니다.', `MaleText_loc4`='数年以前，当我打算去研究双足飞龙的时候，却被困在了这里。一旦我恢复了自由，我就决心回去保护它们。$B$B现在，大灾变席卷了整个世界，暮光之锤开始大肆捕捉这些珍贵的野兽，甚至不惜对它们造成毁灭性的打击。', `MaleText_loc5`='多年前，我在試圖研究雙足飛龍時意外被困在這裡，可是我一自由之後，我就決定還要回來保護他們。$B$B如今災變降臨，暮光之錘的惡徒又在捕捉這些高貴的飛獸，甚至在撲殺他們。', `MaleText_loc7`='Hace años me quedé atrapado aquí mientras trataba de estudiar los jinetes del viento. Pero cuando recuperé la libertad decidí volver para protegerlos.$b$bAhora se ha desencadenado el Cataclismo y el Martillo Crepuscular está capturando a todas estas criaturas sagradas, o peor, matándolas.' WHERE `ID`=47626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 호드와 얼라이언스 사이의 전쟁에는 큰 관심이 없습니다. 제게 중요한 것은 마루둥지의 신성한 와이번을 구하는 것이죠.$B$B꼭 와이번을 위해서가 아니라고 해도, 이들이 황혼의 망치단에게 잡히는 건 막아주십시오, $r님.', `MaleText_loc4`='我不在乎部落和联盟之间的战争。对我来说，最重要的是拯救风巢的双足飞龙。$B$B至少，我要阻止它们落进暮光之锤的手中，$r。', `MaleText_loc5`='我不在乎部落和聯盟之間的戰爭。重要的是，我們必須要拯救珍貴的風巢雙足飛龍。$B$B$r，就算不是為了他們，那麼至少也該遏阻他們繼續落入暮光之錘的手裡。', `MaleText_loc7`='No me importan las guerras entre la Horda y la Alianza. Lo que importa es salvar los jinetes del viento sagrados de Nido Alto.$b$bSi no por ellos, al menos por evitar que caigan en manos del Martillo Crepuscular, $r.' WHERE `ID`=47627;
