UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 침입자가 저를 데려가려고 합니다!', `MaleText_loc4`='入侵者！有入侵者要救我！', `MaleText_loc5`='入侵者!入侵者想要救我!', `MaleText_loc7`='¡$gIntruso:Intrusa;! ¡$gUn intruso:Una intrusa; intenta rescatarme!', `FemaleText_loc1`='침입자다! 침입자가 저를 데려가려고 해요!', `FemaleText_loc4`='入侵者！有入侵者要救我！', `FemaleText_loc5`='入侵者!入侵者想要救我!', `FemaleText_loc7`='¡$gIntruso:Intrusa;! ¡$gUn intruso:Una intrusa; intenta rescatarme!' WHERE `ID`=47637;
