UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 대장조합이 구하러 올 줄 알았습니다!', `MaleText_loc4`='我就知道， 瑟银兄弟会一定会来救我们！', `MaleText_loc5`='我就知道瑟銀兄弟會的人會來救我們!', `MaleText_loc7`='¡Sabía que la Hermandad del Torio no nos defraudaría!', `FemaleText_loc1`='토륨 대장조합이 구하러 올 줄 알았어요!', `FemaleText_loc4`='我就知道， 瑟银兄弟会一定会来救我们！', `FemaleText_loc5`='我就知道瑟銀兄弟會的人會來救我們!', `FemaleText_loc7`='¡Sabía que la Hermandad del Torio no nos defraudaría!' WHERE `ID`=47639;
