UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전 제한 작동 정지. 대재앙 시스템 오류 임박.', `MaleText_loc4`='安全限制：离线。灾难性系统崩溃即将到来。', `MaleText_loc5`='安全裝置:關閉。即將出現災難性系統錯誤。', `MaleText_loc7`='Restricciones de seguridad desactivadas. Falla total de sistema inminente.' WHERE `ID`=47642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임계 온도 돌파. 시스템 오류. 2번 포트에 통밀 막힘 현상. 작동 종료.', `MaleText_loc4`='已超出过热临界值，系统崩溃，有小麦堵在2号端口内，关机中。', `MaleText_loc5`='過熱限度已超過，系統錯誤，二號端口雜物阻塞，關機中。', `MaleText_loc7`='Umbral de recalentamiento excedido, falla del sistema, obstrucción en puerto 2, apagándose.' WHERE `ID`=47643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선반에 있는 창을 잡으십시오.', `MaleText_loc4`='从架子上抓起一根长矛。', `MaleText_loc5`='從架子抓一支火矛', `MaleText_loc7`='Coge una lanza de un expositor' WHERE `ID`=47644;
