UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대공작을 저지하러 왔나?', `MaleText_loc4`='你是要来阻止大公吗？', `MaleText_loc5`='你是來阻止大公爵的?', `MaleText_loc7`='¿Has venido para detener al archiduque?' WHERE `ID`=47647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 해보겠습니다! 말토류스와 아르쿠스를 불러내 보죠!', `MaleText_loc4`='我们行动，把玛托留斯和阿卡库斯干掉！', `MaleText_loc5`='動手吧!我們去解決掉瑪托留斯和阿爾庫斯!', `MaleText_loc7`='¡Hagámoslo! ¡Acabemos con Maltorius y Arkkus!', `FemaleText_loc1`='한번 해볼게요! 말토류스와 아르쿠스를 불러내 보죠!', `FemaleText_loc4`='我们行动，把玛托留斯和阿卡库斯干掉！', `FemaleText_loc5`='動手吧!我們去解決掉瑪托留斯和阿爾庫斯!', `FemaleText_loc7`='¡Hagámoslo! ¡Acabemos con Maltorius y Arkkus!' WHERE `ID`=47648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 말이 좀 통하는군! 내가 황혼의 망치단 녀석을 맡을 테니, 자네는 작은 드워프 놈을 상대하게나.', `MaleText_loc4`='你说的对！我去对付那个暮光混蛋。你对付那个小矮人。', `MaleText_loc5`='這才像話!我負責暮光之錘的傢伙，你去專心對付那個小矮子。', `MaleText_loc7`='¡Ahora nos entendemos! Yo me encargo del tío Crepuscular. Tú ocúpate del enano.' WHERE `ID`=47649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 지키고 있게, $n. 우리는 말토류스, 아르쿠스와 싸우기에 앞서 그들이 다시 돌아올 때까지 기다릴 것이라네.', `MaleText_loc4`='提高警惕，$n。我们要等玛托留斯和阿卡库斯回来，然后迎头痛击他们。', `MaleText_loc5`='慢點，$n。我們必須等瑪托留斯和阿爾庫斯回來，我們才能夠跟他們開打。', `MaleText_loc7`='Aguanta, $n. Tenemos que esperar a que vuelvan Maltorius y Arkkus antes de poder luchar.' WHERE `ID`=47650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 고기 덩어리 같으니! 용아귀 부족의 진정한 힘을 느껴 봐라!', `MaleText_loc4`='可怜的酒囊饭袋！好好看着龙喉的强大力量吧！', `MaleText_loc5`='沒用的東西!看看龍喉氏族真正的力量!', `MaleText_loc7`='¡Patéticos sacos de carne! ¡Sentid la verdadera fuerza de los Faucedraco!' WHERE `ID`=47651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 짐승 놈들, 흙바닥에 한 번 더 처박혀 봐야 정신을 차리겠군!', `MaleText_loc4`='也许你们这些肮脏的动物想要尝尝泥土的味道！', `MaleText_loc5`='也許你們這些下賤的畜生想要再嚐嚐泥土的滋味!', `MaleText_loc7`='¡A lo mejor quieren volver a morder el polvo, sucios animales!' WHERE `ID`=47652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 큰 주먹 맛이 어떠냐!', `MaleText_loc4`='这就是你所说的严厉手段！', `MaleText_loc5`='這才叫做重拳出擊!', `MaleText_loc7`='¡Eso es lo que se suele llamar tener manos pesadas!' WHERE `ID`=47653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약해졌습니다. 이제 그를 추방하십시오!', `MaleText_loc4`='%s被削弱了！现在驱逐他！', `MaleText_loc5`='%s被弱化了!立刻放逐他!', `MaleText_loc7`='¡%s está debilitado! ¡Hazlo desaparecer ahora!' WHERE `ID`=47654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날심장이 울부짖어 감사의 마음을 표현합니다.', `MaleText_loc4`='哈特拉斯发出感激的吼声。', `MaleText_loc5`='撕心者大聲喝謝。', `MaleText_loc7`='Cuorevaja resuella apreciativo.' WHERE `ID`=47655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼!!! 어떻게 이런 일이! 나... 는... 불사의 존재란 말이다...!', `MaleText_loc4`='不！这不可能！我……是……永生不死……！', `MaleText_loc5`='不!這不可能!我...是...不會...死的...!', `MaleText_loc7`='¡NOOOO! ¡NO PUEDE SER! ¡YO... SOY... INMORTAL...!' WHERE `ID`=47656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하기는! 너는 나를 이길 수 없다! 나는 계속 되살아날 테니까 말이야...', `MaleText_loc4`='蠢货！你们不可能打败我！我还会回来的……', `MaleText_loc5`='蠢人!你們是擊敗不了我的!我必定會再度重返...', `MaleText_loc7`='¡Necios! ¡No pueden derrotarme! Acabaré volviendo...' WHERE `ID`=47657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어깨를 당당히 펴게, $n. 이 떨거지들이 문제를 일으키지 않게 하고. 누가 상관인지 제대로 보여주는 거야!', `FemaleText_loc4`='要高傲地昂起头，$n。不能允许这些小矬子们给你制造任何麻烦。让他们知道，谁才是老板！', `FemaleText_loc5`='挺起胸膛，亮出你的自信，$n。不要讓這些小混混給你添麻煩。要他們知道誰才是老大!', `FemaleText_loc7`='Mantén la cabeza alta, $n. No dejes que esos estúpidos te den la lata. ¡Enséñales quién manda!' WHERE `ID`=47658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 한 명 오는군! 기운이 넘쳐 보이는데. 위엄을 유지하게, $n. 긴장하지 말고.', `FemaleText_loc4`='我看见有个家伙过来了！看上去像个真正的胜利者。保持冷静，$n。保持冷静。', `FemaleText_loc5`='有一個來了!這個看起來不錯。保持冷靜，$n。保持冷靜。', `FemaleText_loc7`='¡Ahora veo que llega uno! Parece un verdadero ganador. Mantén la calma, $n. Mantén la calma.' WHERE `ID`=47659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 이봐! 도와줘!', `MaleText_loc4`='嗨！嗨！救命！', `MaleText_loc5`='嗨!嗨!幫幫忙!', `MaleText_loc7`='¡HOLA! ¡HOLA! ¡AYUDA!' WHERE `ID`=47660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 나 새로 왔어! 날개 달린 크고 하얗고 빛나는 존재가 날 살려줬지! 이제 난 밴시 여왕을 섬겨! 만세!$B$B도와줘!$B$B안녕!', `MaleText_loc4`='嗨！我还是个新人！是生着一双大翅膀的，发着白光的一个大怪物让我活过来的！我效忠于女妖之王！嘿！$B$B救命！$B$B嗨！', `MaleText_loc5`='嗨!我是新來的!大大亮亮有翅膀的東西把我復活了!我效忠女妖之王!耶!$B$B幫幫忙!$B$B嗨!', `MaleText_loc7`='¡HOLA! ¡SOY NUEVO! ¡UNA CRIATURA ALADA GRANDE Y LUMINOSA ME HA DADO LA VIDA! ¡SIRVO A LA REINA ALMA EN PENA! ¡YUJU!$B$B¡SOCORRO!$B$B¡HOLA!' WHERE `ID`=47661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 가서 한숨 푹 주무시고 오시는 게 좋겠습니다. 제가 당신께 시킬 일은 없을 것 같네요.', `MaleText_loc4`='也许你应该去打个盹，或者干些别的。我不知道这里有没有工作能给你。', `MaleText_loc5`='也許你該去打個盹還是幹嘛的。我不曉得還有沒有工作可以給你。', `MaleText_loc7`='Igual deberías echarte un sueñecito o algo. No sé si tengo trabajo para ti.', `FemaleText_loc1`='어디 가서 한숨 푹 주무시고 오시는 게 좋겠네요. 제가 당신께 시킬 일은 없을 것 같아요.', `FemaleText_loc4`='也许你应该去打个盹，或者干些别的。我不知道这里有没有工作能给你。', `FemaleText_loc5`='也許你該去打個盹還是幹嘛的。我不曉得還有沒有工作可以給你。', `FemaleText_loc7`='Igual deberías echarte un sueñecito o algo. No sé si tengo trabajo para ti.' WHERE `ID`=47662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어! 고마워! 그럼 그냥 여기서 기다릴게! 고마워! 좋아!', `MaleText_loc4`='好啊！谢谢！我就在这里等你！谢谢！好的！', `MaleText_loc5`='好!謝啦!那我就在旁邊這裡等你!謝啦!好耶!', `MaleText_loc7`='¡VALE! ¡GRACIAS! ¡ESPERARÉ AQUÍ CONTIGO! ¡GRACIAS! ¡VALE!' WHERE `ID`=47663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만요. 방금 일이 생겼습니다. 이 종이에 적혀 있죠? 청금석 광산으로 가셔서 키튼 대장에게 보고해야 한다고요. 남동쪽은 저쪽입니다. *남동쪽을 가리키는 당신*.', `MaleText_loc4`='等一下。这里似乎有什么东西。是了，就在这张纸上。你需要到东南方的碧玉矿洞去，向那里的凯东上尉报告。你要一直向东南走*你向东南方指过去*。', `MaleText_loc5`='等一下。剛好有事情要做了。沒錯，就寫在這疊紙上。你得到東南邊的碧玉礦坑去找吉頓隊長報到。東南邊就是這個方向。<你伸手指向東南方。>', `MaleText_loc7`='Espera un segundo. Sí, parece que acaba de surgir algo. Justo en esta hoja de papel. Tienes que dirigirte al sureste, a Mina Azur, y presentarte ante el capitán Keyton. El sureste está por ahí. <Señalas hacia el sureste.>', `FemaleText_loc1`='잠깐만요. 방금 일이 생겼어요. 이 종이에 적혀 있죠? 청금석 광산으로 가셔서 키튼 대장에게 보고해야 한다고요. 남동쪽은 저쪽이에요. *남동쪽을 가리키는 당신*.', `FemaleText_loc4`='等一下。这里似乎有什么东西。是了，就在这张纸上。你需要到东南方的碧玉矿洞去，向那里的凯东上尉报告。你要一直向东南走*你向东南方指过去*。', `FemaleText_loc5`='等一下。剛好有事情要做了。沒錯，就寫在這疊紙上。你得到東南邊的碧玉礦坑去找吉頓隊長報到。東南邊就是這個方向。<你伸手指向東南方。>', `FemaleText_loc7`='Espera un segundo. Sí, parece que acaba de surgir algo. Justo en esta hoja de papel. Tienes que dirigirte al sureste, a Mina Azur, y presentarte ante el capitán Keyton. El sureste está por ahí. <Señalas hacia el sureste.>' WHERE `ID`=47664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽이라고! 알겠어! 고마워! 안녕! 고마워!', `MaleText_loc4`='向北！明白了！谢谢！再见！谢谢！', `MaleText_loc5`='北邊!知道了!謝啦!再見!謝啦!', `MaleText_loc7`='¡NORTE! ¡ENTENDIDO! ¡GRACIAS! ¡HASTA LUEGO! ¡GRACIAS!' WHERE `ID`=47665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 녀석, 포세이큰이 된 지 얼마 안 된 것 같은데, 조금... 음... 멍청해 보이는군. 정신을 차리려면 시간이 좀 걸릴 거야.', `FemaleText_loc4`='这些新的被遗忘者实在是有些……嗯……愚蠢。他们还需要一段时间适应。', `FemaleText_loc5`='新來的被遺忘者經常會有點...呃...呆呆的。往往要過一段時間他們的腦子才會完全「醒」起來。', `FemaleText_loc7`='Los Renegados nuevos suelen ser un poco... eh... estúpidos. Suelen tardar un tiempo en aclimatarse.' WHERE `ID`=47666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런... 또 저 녀석이군. 내가 잘 아는 놈이야. 여기 올 이유도 없는 놈이지. 워낙 밑바닥 인생이라서 이곳에 딱히 볼일도 없으면서 근처를 돌아다니며 무력한 자들에게 빌붙곤 하거든. 놈에게 농락당하지 말게.', `FemaleText_loc4`='哦，好啊……这个也不是。我知道这个兽人。他不做什么正经事，只是在这里四处晃荡，靠敲诈欺凌为生。别让他吓唬了你。', `FemaleText_loc5`='哦，拜託...又是這傢伙。我認識這個獸人。他在這邊根本已經沒事幹了，可是他太沒種，只喜歡在這邊晃來晃去欺負弱小。千萬別讓他爬到你頭上。', `FemaleText_loc7`='Oh, genial... Otra vez no. Conozco a este orco. No se le ha perdido nada aquí, pero como es un patán inútil le gusta pasearse por la zona y aprovecharse de los débiles. No dejes que te amilane.' WHERE `ID`=47667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르가 어떤 놈을 요리해줄까?!', `MaleText_loc4`='你能闻出那个家伙在烧什么吗？', `MaleText_loc5`='你瞭解勝利的意思嗎?!', `MaleText_loc7`='¡¿HUELES QUÉ LOK''TAR ESTÁ COCINANDO?!' WHERE `ID`=47668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호라! 보아하니 말 위에 세워둘 얼간이가 모자랐나 보군, 다살리아. 여태 본 녀석 중에서도 제일 약해 보이는데?', `MaleText_loc4`='哈！看上去你已经没有什么白痴可以放在这匹马背上了，达萨利亚。这个家伙实在是太弱了。', `MaleText_loc5`='哈!達薩利亞，你們已經沒有其他的白痴可以擺到這匹馬的背上了嗎?而這傢伙還是最弱的一個。', `MaleText_loc7`='¡JA! Parece que se te están acabando los idiotas para subir a este caballo, Darthalia. $gEste:Esta; es $gel:la; más débil que he visto.' WHERE `ID`=47669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 줄 일은 뭔가, 약골 녀석아?! 그냥 얼라이언스 놈들이 숨어 있는 곳을 말해라. 내가 싹 쓸어줄 테니!', `MaleText_loc4`='小家伙，你今天给我弄到了些什么？！给我指出那些联盟的藏身之地，我会好好照顾他们！', `MaleText_loc5`='今天有什麼任務要給我啊，廢物?!告訴我聯盟躲在哪裡，我就會去捅光他們!', `MaleText_loc7`='¡¿Qué tienes para mí hoy, medianías?! ¡Enséñame dónde se esconden los de la Alianza y los DOMINARÉ!' WHERE `ID`=47670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 몸속에 흐르는 피를 꽁꽁 얼려 주마!', `MaleText_loc4`='我要冻结你的血液！', `MaleText_loc5`='我會凍結你們血管裡的血!', `MaleText_loc7`='¡Congelaré la sangre de sus venas!' WHERE `ID`=47671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 빙하 작용을 시전합니다!', `MaleText_loc4`='%s开始施放冻结！', `MaleText_loc5`='%s開始施展「結冰」!', `MaleText_loc7`='¡%s comienza a lanzar Helar!' WHERE `ID`=47672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 리치 왕의 몰락을 직접 지켜봤다. 티탄의 창조물은 내 무적의 도끼 아래 무너졌고... 노스렌드의 야수들과 맞설 때는 은빛십자군의 선봉에 서서 홀로 승리를 이끌었지. 이제 난 궁극의 도전을 원해. 언덕마루 구릉지는 왕을 쓰러뜨린 자 오르쿠스에게 어떤 도전을 선사할 수 있나???', `MaleText_loc4`='我见证了巫妖王的毁灭。泰坦的造物被我强大的战斧摧毁。得到号令的时候，我一个人与诺森德的怪物们对战，凭一己之力为银色北伐军赢得了巨大的胜利。现在，我来接受这场终极挑战。希尔斯布莱德丘陵能为弑君者奥尔库斯献上些什么？？？', `MaleText_loc5`='我見證了巫妖王的殞落。我的利斧砍倒了泰坦的創造物。我孤身對抗北裂境猛獸，為銀白十字軍贏得勝利。現在，我來尋找最究極的挑戰。希爾斯布萊德丘陵有什麼任務要交給弒王者歐庫斯???', `MaleText_loc7`='He visto la caída del Rey Exánime. Las creaciones de los titanes han caído ante mi poderosa hacha. Cuando me llamaron a filas, yo solo lideré la victoria de la Cruzada Argenta contra las bestias de Rasganorte. Ahora, busco el desafío final. ¿¿¿Qué podría ofrecer Laderas de Trabalomas al matarreyes Orkus???' WHERE `ID`=47673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 보아하니 남녘해안에 조금 문제가 있는 것 같습니다. 늑대인간 반역자에 관련된 일이었는데. 그 문제를 해결해 주시겠습니까?', `MaleText_loc4`='嗯……南海镇显然是遇到了些麻烦。狼人在这里发动了叛乱。你愿意帮助我对付他们吗？', `MaleText_loc5`='嗯...南海鎮顯然出了些亂子。有狼人在起事之類的。也許你可以去幫幫他們?', `MaleText_loc7`='Mm... Según parece, tienen problemas en Costasur. Algo que ver con insurgentes huargen. ¿Igual puedes ayudar con eso?', `FemaleText_loc1`='음... 보아하니 남녘해안에 조금 문제가 있는 것 같네요. 늑대인간 반역자에 관련된 일이었는데. 그 문제를 해결해 주시는 건 어떨까요?', `FemaleText_loc4`='嗯……南海镇显然是遇到了些麻烦。狼人在这里发动了叛乱。你愿意帮助我对付他们吗？', `FemaleText_loc5`='嗯...南海鎮顯然出了些亂子。有狼人在起事之類的。也許你可以去幫幫他們?', `FemaleText_loc7`='Mm... Según parece, tienen problemas en Costasur. Algo que ver con insurgentes huargen. ¿Igual puedes ayudar con eso?' WHERE `ID`=47674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역자라고? 내가 죽거나 팔다리라도 잃을 수 있는 임무인가?', `MaleText_loc4`='你说有入侵者？我会有生命危险吗？我会被肢解吗？', `MaleText_loc5`='你說有狼人在起事?那我會有遭到死亡或傷殘的風險嗎?', `MaleText_loc7`='¿Insurgentes, dices? ¿Hay riesgo de muerte o desmembramiento para mí?' WHERE `ID`=47675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요.', `MaleText_loc4`='没有。', `MaleText_loc5`='完全不會。', `MaleText_loc7`='Ninguno.', `FemaleText_loc1`='아니요.', `FemaleText_loc4`='没有。', `FemaleText_loc5`='完全不會。', `FemaleText_loc7`='Ninguno.' WHERE `ID`=47676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 임무를 받아들이겠다! 당연하지!', `MaleText_loc4`='奥尔库斯会成功的！没错！', `MaleText_loc5`='好!那就交給歐庫斯吧!', `MaleText_loc7`='¡Entonces Orkus LO HARÁ! ¡SÍ!' WHERE `ID`=47677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 남동쪽으로 가십시오. 동쪽보단 남쪽으로 좀 더 치우쳐 가시고요. 아마 물가 근처일 겁니다.', `MaleText_loc4`='好的，谢谢。只要向东南偏南前进。也许就在海岸边。', `MaleText_loc5`='好啦，謝謝。趕快往東南方出發就對了。南南東才對。大概在海邊那裡。', `MaleText_loc7`='Vale, gracias. Tú solo sigue hacia el sureste. Más sur que este. Probablemente más allá de la costa.', `FemaleText_loc1`='좋아요. 남동쪽으로 가세요. 동쪽보단 남쪽으로 좀 더 치우쳐 가시고요. 아마 물가 근처일 거예요.', `FemaleText_loc4`='好的，谢谢。只要向东南偏南前进。也许就在海岸边。', `FemaleText_loc5`='好啦，謝謝。趕快往東南方出發就對了。南南東才對。大概在海邊那裡。', `FemaleText_loc7`='Vale, gracias. Tú solo sigue hacia el sureste. Más sur que este. Probablemente más allá de la costa.' WHERE `ID`=47678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 겁쟁아. 그 뼈다귀 말 위에 앉아 오르쿠스가 호드의 영광을 드높이는 모습을 지켜보도록! 천 개의 해골을 들고 돌아오마!', `MaleText_loc4`='是的，懦弱的任务提供者。在你的白马背上好好坐着吧。奥尔库斯则会为部落夺取光荣！我会带着一千个俘虏回来！', `MaleText_loc5`='沒問題，給任務的膽小鬼。你就繼續乖乖坐在你的白骨馬上，等歐庫斯把榮耀獻給部落!我會帶回來一千顆頭顱!', `MaleText_loc7`='Sí, $gasignador:asignadora; de misiones, quédate sobre tu caballo bayo mientras Orkus aporta gloria a la Horda. ¡Volveré con un millar de cráneos!' WHERE `ID`=47679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시는 안 보고 싶군. 확 물에 빠져버렸으면 좋겠어.', `FemaleText_loc4`='现在只能希望他永远不要回来了。也许他会淹死？', `FemaleText_loc5`='希望他永遠不會回來。說不定他會淹死?', `FemaleText_loc7`='Esperemos que no vuelva nunca. A lo mejor se ahogará.' WHERE `ID`=47680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젠장. 난 몰라. 이 녀석은 자네 혼자 상대하게, $p.', `FemaleText_loc4`='啊，废物。你要自己对付这个家伙了，$P。', `FemaleText_loc5`='噢，糟了。這傢伙你自己看著辦，$p。', `FemaleText_loc7`='Ah, maldición. Arréglatelas por tu cuenta con este, $p.' WHERE `ID`=47681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조니 잘나스가 도착했습니다, 천한 자여. 제게 당신의 하찮은 임무를 주십시오. 오직 좁쌀만 한 열정과 책임의식으로... 제 지도에 있는 길보다 복잡한 길 안내는 완전히 무시한 채로... 임무를 수행해 보이겠습니다.', `MaleText_loc4`='强尼·傲森来了，真庸俗。把你们无聊那些小任务交给我吧，我会记得在恰当的时间以恰当的方式去去完成它们的。不过，如果你们给的任务描述比我的地图标记还要复杂，我可就完全没兴趣了。', `MaleText_loc5`='庸俗之輩，『棒透了』強尼來了。把你那些俗不可耐的任務交給我吧，我會心不在焉地將它們做完，而且除了看地圖的提示之外完全不顧你在說明什麼複雜的東西。', `MaleText_loc7`='Ha llegado Johnny Fenómeno, $giletrado:iletrada;. Ofréceme tus tareas cotidianas para que pueda completarlas con poco más que un ligero entusiasmo, y con toda seguridad ignorando sin contemplaciones cualquier indicación que ofrezcas que sea más compleja de lo que puede mostrar mi mapa.' WHERE `ID`=47682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천한 자여, 저를 보십시오. 저는 머리부터 발끝까지 아제로스의 가장 위대한 영웅들이 직접 선사한 계승템을 착용하고 있습니다.$B$B이제 당신의 모습을 보십시오.$B$B그리고 제 모습을 보십시오.$B$B그렇습니다. 이 말은 별로 만들어졌습니다. 당신의 평범한 탈것과는 격이 다르죠.$B$B자, 아까 그 모자라 보이던 오크에게나 어울릴 법한 한심한 임무를 준비해 오신 거겠지요?', `MaleText_loc4`='看着我，农夫。我全身从头顶到脚趾可都是珍贵的传家宝。是艾泽拉斯历史上最伟大的英雄们给我的礼物。$B$B现在看看你自己。$B$B再看看我。$B$B当然，这匹马可是用晨星做成的。$B$B你为我准备了什么无聊的任务？你们的任务其实只应当由没脑子的兽人去完成。', `MaleText_loc5`='仔細看看我，鄉巴佬。我全身都是家傳寶物，由艾澤拉斯有史以來最偉大的英雄們贈與給我的。$B$B現在看看你自己。$B$B好了，趕快再看我一下。$B$B沒錯，這匹馬全身都是星星。$B$B你為我準備了些什麼無意義的、只適合給低能獸人做的任務串啊?', `MaleText_loc7`='Mírame, $gplebeyo:plebeya;. Mi cuerpo está cubierto de reliquias, de pies a cabeza, que me han entregado los mayores héroes que Azeroth ha conocido jamás.$b$bAhora mírate.$b$bRápido, vuelve a mirarme.$b$bSí, este caballo está hecho de ESTRELLAS.$b$b¿Qué serie de tareas inútiles propias de un orco retrasado me has preparado?' WHERE `ID`=47683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 북동쪽에 있는 진흙 농장에 작은 문제가 생긴 것 같습니다. 감독관 스틸워터를 도우십시오.', `MaleText_loc4`='嗯，我们在东北方的药渣农场的确遇到了一些麻烦。你一定能帮上看守者斯蒂沃特的忙。', `MaleText_loc5`='好吧，我們在東北方的淤泥農場那邊出了點問題。你可以去幫管理員斯蒂沃特的忙。', `MaleText_loc7`='Bueno, tenemos algunos problemas en Los Campos de Lodo situados al noreste de aquí. Al celador Aguaserena le vendría bien tu ayuda.', `FemaleText_loc1`='음, 북동쪽에 있는 진흙 농장에 작은 문제가 생긴 것 같네요. 감독관 스틸워터를 도와주세요.', `FemaleText_loc4`='嗯，我们在东北方的药渣农场的确遇到了一些麻烦。你一定能帮上看守者斯蒂沃特的忙。', `FemaleText_loc5`='好吧，我們在東北方的淤泥農場那邊出了點問題。你可以去幫管理員斯蒂沃特的忙。', `FemaleText_loc7`='Bueno, tenemos algunos problemas en Los Campos de Lodo situados al noreste de aquí. Al celador Aguaserena le vendría bien tu ayuda.' WHERE `ID`=47684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 좋습니다. 또 다른 일 없습니까?', `MaleText_loc4`='好啊，好啊，还有什么？', `MaleText_loc5`='好吧，好吧。還有什麼?', `MaleText_loc7`='Ya, ya, ¿y qué más?' WHERE `ID`=47685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 다입니다.', `MaleText_loc4`='就是这些。', `MaleText_loc5`='就這樣。', `MaleText_loc7`='Eso es todo.', `FemaleText_loc1`='그게 다예요.', `FemaleText_loc4`='就是这些。', `FemaleText_loc5`='就這樣。', `FemaleText_loc7`='Eso es todo.' WHERE `ID`=47686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 다라고요? 겨우 하나? 지금 농담하시는 겁니까? 곰 발바닥 모으는 일이라도 없습니까? 예를 들어 당신이 살짝 환각을 유발하는 물약을 마시고 위대한 신의 계시를 받아야 하니 그 재료인 희귀한 꽃을 찾아와라, 뭐 그런 식의 일도 없는 겁니까? 요즘 성질 더러운 땅다람쥐들이 슬슬 나대기 시작해서 지역 주민에게 점점 불만이 쌓이는 상황인데도, 이들에게 정의의 심판을 내리지 않겠단 말씀이신가요? 정말입니까?', `MaleText_loc4`='就这些？一个任务？你一定是在开玩笑。这里没有狗熊要猎捕吗？也许我可以去采集某种罕见的花卉，让你能够用来调配致幻剂，喝下去以后让你能看到伟大的预兆？也许本地有令人困扰的地鼠捣乱，需要予以惩治？没有？什么都没有？', `MaleText_loc5`='就這樣?才一個任務?你一定在開玩笑。沒有什麼熊屁股肉要收集?沒有什麼罕見花朵要採來給你煉製幻覺藥劑、喝了之後會看到恐怖大災變的預言景象?還是說有什麼討人厭的、壞脾氣的地鼠在鬧事，需要好好教訓以給個公道?沒有?都沒有?', `MaleText_loc7`='¿Eso es todo? ¿Una misión? Menuda chanza. ¿No hay culos de oso por recoger? ¿Quizá quieras que recoja una extraña flor con la que podrías elaborar un tónico ligeramente alucinógeno que beberías y te proporcionaría visiones de un gran apocalipsis? ¿Quizá la población local de husmeadores medianamente molestos y de mal genio se están soliviantando y hay que llevarlos a la justicia? ¿No? ¿Nada?' WHERE `ID`=47687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그게 답니다, 조니 잘나스 님. 임무를 맡거나 포기하거나 마음대로 하십시오!', `MaleText_loc4`='就是这些，强尼·傲森。不愿意接受就走吧！', `MaleText_loc5`='就這樣!『棒透了』強尼!要接不接隨便你!', `MaleText_loc7`='ESO ES TODO, JOHNNY FENÓMENO. LO TOMAS O LO DEJAS.', `FemaleText_loc1`='정말 그게 다예요, 조니 잘나스 님. 임무를 맡거나 포기하거나 마음대로 하세요!', `FemaleText_loc4`='就是这些，强尼·傲森。不愿意接受就走吧！', `FemaleText_loc5`='就這樣!『棒透了』強尼!要接不接隨便你!', `FemaleText_loc7`='ESO ES TODO, JOHNNY FENÓMENO. LO TOMAS O LO DEJAS.' WHERE `ID`=47688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 지금은 그 임무 하나만 하겠습니다. 다만, 제가 자잘한 임무를 더 찾길 바라십시오. 못 찾으면 다시 올 겁니다. 토론장에 당신에 대한 악평을 퍼뜨릴 거고요.', `MaleText_loc4`='既然你请求我完成的这个任务，我会为你完成的，任务提供者。你最好祈祷我能再找到一些这种小任务去完成。否则我在公共论坛可不会说你的什么好话。', `MaleText_loc5`='好吧，任務給予者，我這就去做你所交辦的這「一」件任務。你最好祈禱我能接到其他的跑腿任務，否則我一定會再回來找你。而且我向你保證，我在討論板上發表的意見絕對會毫不客氣。', `MaleText_loc7`='Haré esta ÚNICA cosa que me pides, $gasignador:asignadora; de misiones. Reza para que encuentre más tareas insignificantes que cumplir, o volverás a saber de mí, y te aseguro que mis comentarios en los foros de la opinión pública serán de lo más rotundos.' WHERE `ID`=47689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 드워프들은 쓸모가 없는 놈들이로구나! 승천을 바라며 라그나로스 님을 찾아왔으면서도 아무것도 바칠 게 없다니!', `MaleText_loc4`='你们这些矮人真是没用！你们来找拉格纳罗斯，想得到拉格纳罗斯的赠礼，但你们却拿不出任何东西作为奉献！', `MaleText_loc5`='你們矮人全是廢物!妄想獲得拉格納羅斯的賜福，可是竟然沒有任何東西可以獻上!', `MaleText_loc7`='¡Sois inútiles, enanos! ¡Venís a Ragnaros en busca de ascensión, pero no tenéis nada que ofrecer a cambio!' WHERE `ID`=47690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸뚱이와 삽을 제외하고는 바칠 게 없군. 그러니 네놈들은 땅이나 파게 될 것이다.', `MaleText_loc4`='没有任何奉献，除了你们的力气和铲子。所以你们就用力挖吧。', `MaleText_loc5`='沒有東西可以獻上，除了你們的勞力和鏟子。既然如此，你們就挖吧。', `MaleText_loc7`='Nada excepto sus espaldas y sus palas. Así que cavarán.' WHERE `ID`=47691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넓고, 또 깊게 파거라. 세상 아래에 불로 가득 찬 곳을 찾도록 말이야. 내 형제들이 자유를 절실히 바라고 있다.', `MaleText_loc4`='挖大坑，挖深坑。找出世界下方的火焰之地。我的兄弟姐妹正渴望着得到自由。', `MaleText_loc5`='挖寬一點、挖深一點。挖出埋在這世界底下的火焰之境。我的弟兄姊妹們渴望獲得自由。', `MaleText_loc7`='Cavad ancho, cavad profundo. Buscad los lugares de fuego que hay bajo el mundo. Mis hermanos y hermanas ansían la libertad.' WHERE `ID`=47692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공하면 너도 결국 승천할 것이다. 하지만 실패하면 불에 타죽겠지.', `MaleText_loc4`='如果成功，你们将得到升腾。失败的话，你们都将被烧成灰烬。', `MaleText_loc5`='成功，或許你們還有機會獲得炎魔的祝福。失敗，那就活該燒死吧!', `MaleText_loc7`='Conseguidlo, y podrías obtener la ascensión después de todo. Fracasad, y arderéis.' WHERE `ID`=47693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 대장조합이라고 들어보셨습니까? 물론 우리가 이글거리는 협곡이나 검은바위 나락에 있는 드워프들과 아주 많이 비슷해 보일 수도 있지만, 제 말을 믿어주십시오. 우리는 그들과 같은 점이 하나도 없습니다.$b$b저 악당 놈들은 땅을 한참이나 깊게 파놓고 나서는 이제 더욱 사악한 힘의 소유자인 불의 군주 라그나로스를 섬기고 있습니다. 다행히 우리는 놈들과 달리 자유 의지를 지닌 드워프지요. 비록 놈들이 말썽을 피우지 못하게 하느라 너무 바빠서 그걸 다른 데 발휘할 여유가 없기는 하지만 말입니다.', `MaleText_loc4`='有没有听说过瑟银兄弟会？当然，我们可能很像山谷中和黑石深渊里的那些矮人。但相信我：我们和他们根本不是一种人。$b$b那些恶棍挖得太深。现在，他们愚昧地侍奉着一股黑暗的力量——拉格纳罗斯，炎魔君主。我们很高兴自己能有独立的意志。虽然在大多数时间里，我们不得不将自己的全部精力都用来弥补那些恶棍所犯下的罪行。', `MaleText_loc5`='有聽過瑟銀兄弟會嗎?對，雖然我們跟峽谷還有黑石深淵裡頭的那些矮人長得很像，但是請相信我:我們真的跟他們完全不一樣。$b$b那些混蛋在地底挖得太深，現在已經遭到邪惡力量—炎魔拉格納羅斯的奴役。很高興我們並沒有落到跟他們一樣的下場，失去獨立自主的意識，儘管絕大多數的時候我們都得忙著預防和阻止他們引起的麻煩。', `MaleText_loc7`='¿Alguna vez has oído hablar de la Hermandad del Torio? Es posible que nos parezcamos mucho a esos enanos de la garganta, o de las Profundidades de Roca Negra, pero créeme: somos totalmente diferentes.$b$bEsas sabandijas cavaron demasiado, y ahora sirven a una fuerza más oscura: Ragnaros, el Señor del Fuego. A nosotros nos gusta ser más independientes de voluntad y propósito, aunque la mayoría de las veces nuestro propósito es evitar los líos que crean ellos.' WHERE `ID`=47694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 장비를 수리해주실 수 있겠습니까, 부리안?', `MaleText_loc4`='你能修好我的设备吗，布里安？', `MaleText_loc5`='可以幫我修一下裝備嗎，布瑞恩?', `MaleText_loc7`='¿Crees que podrías reparar mi equipo, Burrian?', `FemaleText_loc1`='제 장비를 수리해주실 수 있나요, 부리안?', `FemaleText_loc4`='你能修好我的设备吗，布里安？', `FemaleText_loc5`='可以幫我修一下裝備嗎，布瑞恩?', `FemaleText_loc7`='¿Crees que podrías reparar mi equipo, Burrian?' WHERE `ID`=47695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르거스 님, 제 장비를 수리해 주실 수 있습니까?', `MaleText_loc4`='你能修好我的设备吗，阿古斯？', `MaleText_loc5`='可以修一下我的裝備嗎，阿古斯?', `MaleText_loc7`='¿Me podrías reparar el equipo, Argus?', `FemaleText_loc1`='아르거스 님, 제 장비를 수리해 주실 수 있나요?', `FemaleText_loc4`='你能修好我的设备吗，阿古斯？', `FemaleText_loc5`='可以修一下我的裝備嗎，阿古斯?', `FemaleText_loc7`='¿Me podrías reparar el equipo, Argus?' WHERE `ID`=47696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 나락에 있는 검은무쇠 놈들이 내게 트집 잡을 건 아무것도 없네. 여기 토륨 거점에 있는 이들도 그렇고 말이야.$b$b나는 가능하면 혼자서 일한다네. 그게 내가 좋아하는 방식이고 말이야. 물론 값을 올바르게 치러준다면야, 다른 쪽 이야기도 들어줄 용의는 있네만...', `MaleText_loc4`='黑石的黑铁矮人和瑟银哨塔的那些男孩都和我没关系。$b$b我是中立的，而且我喜欢这样。当然，只要出价合适，我会帮助任何人……', `MaleText_loc5`='黑石山的黑鐵矮人跟我一點關係也沒有。瑟銀哨塔的那些小鬼也一樣。$b$b我完全獨立，而且我就喜歡這樣。當然，只要價格合理，兩邊的話我都願意聽...', `MaleText_loc7`='Los Hierro Negro de Roca Negra no me llegan ni a la suela del zapato. Al igual que los chicos del Puesto del Torio.$b$bSoy tan independiente como el que más, y me gusta que sea así. Eso sí, por el precio adecuado escucharé al bando que sea...' WHERE `ID`=47697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러는 거야? 왜 죽였어!!', `MaleText_loc4`='为什么你要这么干？为什么你要杀戮？', `MaleText_loc5`='你為什麼那樣?為什麼要殺?', `MaleText_loc7`='¿Por qué hacer eso? ¿Por qué matar?' WHERE `ID`=47698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽이는 거 그만해! 돌머리 안 좋아한다!', `MaleText_loc4`='不要再杀了！隆克不喜欢！', `MaleText_loc5`='住手不要殺!郎克不喜歡!', `MaleText_loc7`='¡Tú dejar de matar ya! ¡Ñoño no gustar!' WHERE `ID`=47699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 죽이지 마!', `MaleText_loc4`='不！不要杀！', `MaleText_loc5`='不要!不要殺!', `MaleText_loc7`='¡No! ¡No matar!' WHERE `ID`=47700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 누구 죽이면 돌머리 기분 안 좋다.', `MaleText_loc4`='你杀戮的时候，隆克感觉受了伤。', `MaleText_loc5`='在你殺的同時也傷到了郎克的心。', `MaleText_loc7`='Al matar, tú herir sentimientos de Ñoño.' WHERE `ID`=47701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 돌머리랑 같이 있을 때 누구 죽이지 마.', `MaleText_loc4`='请不要在隆克身边杀戮。', `MaleText_loc5`='拜託。郎克在的時候不要殺。', `MaleText_loc7`='Por favor, no matar delante de Ñoño.' WHERE `ID`=47702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 왜 죽이는 거야?', `MaleText_loc4`='哦，不！为什么你要杀它？', `MaleText_loc5`='哦，不要!為什麼你殺它?', `MaleText_loc7`='¡Oh, no! ¿Por qué matarlo?' WHERE `ID`=47703;
