UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r, 지금은 와이번을 제공할 수 없다. 가로쉬 님의 명으로 나이트 엘프 녀석들이 괴멸되기 전까지는 이 와이번들을 군사용으로만 이용할 수 있다.', `MaleText_loc4`='现在还不是飞出去的时候，$r。根据加尔鲁什的命令，要等到暗夜精灵被彻底清除之后，这些双足飞龙才能被用于军事行动。', `MaleText_loc5`='現在全面禁止飛出去，$r。卡爾洛斯下的命令，這些雙足飛龍只供軍事用途，直到消滅所有夜精靈為止。', `MaleText_loc7`='No están saliendo vuelos, $r. Por orden de Garrosh, estos jinetes del viento son solo para uso militar hasta que hayamos exterminado a los elfos de la noche.' WHERE `ID`=47709;
