UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나아가라, 아름다운 나의 천사여! 아아, 아이를 떠나보내는 마음이 어찌나 슬픈지...', `MaleText_loc4`='前进，我美丽的天使！唉，孩子离巢的时候，总是让人感到伤心的时刻，不是么？', `MaleText_loc5`='去吧，我美麗的天使!啊，自己的孩子離巢的時候總是特別令人感傷，你說是吧?', `MaleText_loc7`='¡Ve, mi bello ángel! Ah, es tan triste cuando los hijos abandonan el nido, ¿verdad?' WHERE `ID`=47729;
