UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가... 내 창조물이! 하늘을 가릴 만큼 커지지도 않았는데! 연구 일지를 다시 살펴보는 게 좋겠군...', `MaleText_loc4`='什么……我的创造物！它甚至没有飞上过天空！我最好检查一下我的笔记……', `MaleText_loc5`='什麼...我的傑作!連把天空遮住都沒有!我最好再看一下我的筆記...', `MaleText_loc7`='¿Qué...? ¡Mi creación! ¡Ni siquiera ha oscurecido el cielo! Mejor repaso mis notas...' WHERE `ID`=47731;
