UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가야, 이제 네 최고의 기술을 사용할 시간이다!', `MaleText_loc4`='该是发动最后一击的时候了，亲爱的！', `MaleText_loc5`='親愛的，是發動你的終極攻擊的時候了!', `MaleText_loc7`='¡Es hora de tu ataque definitivo, cariño!' WHERE `ID`=47736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 슈노츠라는 친구에게 투자한 것이 현명했음이 드러나고 있습니다.$b$b이 사업에 초창기부터 참가했던 일이 얼마나 다행인지 모르겠군요.', `MaleText_loc4`='事实证明这个司克诺兹是个明智的投资对象。$b$b看来我的洞察力的确是超强的。', `MaleText_loc5`='這個叫舒諾茲的傢伙已證明了是個明智的投資。$b$b很高興我在一開始就入股了。', `MaleText_loc7`='Ese tal Schnottz está demostrando ser una buena inversión.$b$bMenos mal que tuve la sensatez de incorporarme desde el principio.' WHERE `ID`=47737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버님께서 항상 말씀하셨듯, 성공적인 투자가가 되기 위해서는 기민한 두뇌와 날카로운 본능, 그리고 한결같은 용기가 필요합니다.$b$b전 틀림없이 이 발굴 작업에서 풍기는 성공의 향기를 맡았었지요.', `MaleText_loc4`='就像父亲一直说的那样，要成为一名成功的投资人，必须具有精明的头脑，敏锐的直觉和无尽的勇气。$b$b必须承认，我能在一哩以外就能闻到投资的机会。', `MaleText_loc5`='就像我爸經常講的，投資就是要快、狠、準，放膽子去幹。$b$b告訴你，我老早在幾公里外就聞到了這個投資機會。', `MaleText_loc7`='Como siempre decía mi padre, hacen falta una mente astuta, unos instintos agudos y un coraje infalible para convertirse en un inversor próspero.$b$bAdmito que vi venir esta oportunidad de lejos.' WHERE `ID`=47738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 말고 원래 주 무기로 바꾸십시오!', `MaleText_loc4`='不要忘记更换你的主武器！', `MaleText_loc5`='別忘了換掉你的主手武器!', `MaleText_loc7`='¡No te olvides de reponer tu arma principal!' WHERE `ID`=47739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가, 아니, 무언가가 대사님을 해친 모양이오!', `MaleText_loc4`='大使似乎是因为某个人或某件事而遇害了！', `MaleText_loc5`='不知道是什麼人還是什麼東西把大使給殺了!', `MaleText_loc7`='¡Algo o alguien se ha cargado al embajador!' WHERE `ID`=47740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단언하건대, 이런 놀음도 여기서 끝이다. 때가 되었군... 내 안의 야수가 등장할 때가!', `MaleText_loc4`='我对这一切已经受够了。现在该是让……野兽之心出来的时候了！', `MaleText_loc5`='我已經受夠了。時候到了，該叫出我...心中的野獸!', `MaleText_loc7`='Me atrevo a decir que ya he tenido suficiente. Hora de desatar... ¡LA BESTIA INTERIOR!' WHERE `ID`=47741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 누가 이런 짓을 했을까요?', `MaleText_loc4`='谁会干这种事？', `MaleText_loc5`='誰會幹出這種事情?', `MaleText_loc7`='¿Quién podría haber hecho algo así?', `FemaleText_loc1`='대체 누가 이런 짓을 했을까요?', `FemaleText_loc4`='谁会干这种事？', `FemaleText_loc5`='誰會幹出這種事情?', `FemaleText_loc7`='¿Quién podría haber hecho algo así?' WHERE `ID`=47742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 알겠습니까?$b$b그 분은 이번 발굴 작업에서 핵심적인 인물이셨는데... 하지만 그걸로는 아무것도 알아낼 수 없습니다.', `MaleText_loc4`='谁能知道？$b$b他已经成为了这个行动的关键，但这不能证明任何事。', `MaleText_loc5`='誰知道?$b$b他在這個行動裡變得越來越重要了，但這還是證明不了什麼。', `MaleText_loc7`='¿Quién sabe?$b$bSe estaba volviendo bastante crítico con esta operación, pero eso no demuestra nada.' WHERE `ID`=47743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 이번 살인사건을 조사해 주시겠습니까?', `MaleText_loc4`='你愿意调查这起谋杀案吗？', `MaleText_loc5`='你願意去調查這宗謀殺案嗎?', `MaleText_loc7`='¿Investigarás su asesinato?', `FemaleText_loc1`='당신이 이번 살인사건을 조사해 주시겠어요?', `FemaleText_loc4`='你愿意调查这起谋杀案吗？', `FemaleText_loc5`='你願意去調查這宗謀殺案嗎?', `FemaleText_loc7`='¿Investigarás su asesinato?' WHERE `ID`=47744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 말인가요?$b$b아, 전 정말 그럴 자격이... 어, 아니, 그러지 않는 게 좋겠습니다.', `MaleText_loc4`='谁，我？$b$b为什么？我觉得自己没有资格，嗯……不，我想我应该拒绝。', `MaleText_loc5`='誰?我?$b$b可是，我覺得自己好像沒這個資格。呃...不，我想最好不要。', `MaleText_loc7`='¿Quién, yo?$b$bVaya, no me considero cualificado para... eh... No, creo que no.' WHERE `ID`=47745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 그러면 적어도 이번 사건에 대해 기록을 해 주시겠습니까?', `MaleText_loc4`='好吧，你至少能把它记录下来吧，对不对？', `MaleText_loc5`='好吧，但是至少你「會」把這件事情給寫下來吧?', `MaleText_loc7`='Bueno, al menos ESCRIBIRÁS sobre el tema, ¿no?', `FemaleText_loc1`='음, 그러면 적어도 이번 사건에 대해 기록은 해 주시겠지요?', `FemaleText_loc4`='好吧，你至少能把它记录下来吧，对不对？', `FemaleText_loc5`='好吧，但是至少你「會」把這件事情給寫下來吧?', `FemaleText_loc7`='Bueno, al menos ESCRIBIRÁS sobre el tema, ¿no?' WHERE `ID`=47746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 뭐라고?! 아, 저는...$b$b이렇게 흥미로운 발굴 작업이 이루어지고 있는 와중에 그런 문제에 초점을 맞추는 게 과연 적절할지 모르겠습니다.$b$b당신도 알다시피 꽤 불쾌한 이야기가 될 테니까요.', `MaleText_loc4`='什……什么？！嗯，我……$b$b正在展开的发掘工作是如此令人兴奋，现在却要把注意力集中在这种事情上，我想这可能不合适。$b$b你也知道，这只能是一个令人困扰的故事。', `MaleText_loc5`='什—什麼?!呃，我...$b$b在這麼刺激的挖掘過程當中，我不曉得把精神擺在這種事情上是否恰當。$b$b你知道的，這種故事還蠻嚇人的。', `MaleText_loc7`='¿Q-qué? Bueno, yo...$b$bEn mitad de una excavación tan emocionante, no creo que sea apropiado centrarse en una cosa como esa.$b$bSería una historia muy perturbadora, ¿entiendes?' WHERE `ID`=47747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소... 손대지 마세요...$b$b이게 대체 무슨 일이지요?!', `FemaleText_loc4`='别……别碰我……$b$b出了什么事？！', `FemaleText_loc5`='不—不要碰我...$b$b發生了什麼事情?!', `FemaleText_loc7`='No... No me toques...$b$b¡¿Qué está pasando?!' WHERE `ID`=47748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 진정하십시오. 괜찮습니까?', `MaleText_loc4`='镇定。你还好吗？', `MaleText_loc5`='冷靜點。你還好嗎?', `MaleText_loc7`='Cálmate. ¿Estás bien?', `FemaleText_loc1`='일단 진정하세요. 괜찮으신가요?', `FemaleText_loc4`='镇定。你还好吗？', `FemaleText_loc5`='冷靜點。你還好嗎?', `FemaleText_loc7`='Cálmate. ¿Estás bien?' WHERE `ID`=47749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요! 당연히 안 괜찮지요!$b$b나, 나는 한 번도 진짜 시체를 본 적이 없었어요...', `FemaleText_loc4`='不！我当然不好！$b$b以前我从没见过尸体……', `FemaleText_loc5`='不!我當然不好!$b$b我—我從來沒有看過真正的屍體...', `FemaleText_loc7`='¡No! ¡Claro que no estoy bien!$b$bN-nunca había visto un cadáver de verdad...' WHERE `ID`=47750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 일어났는지 목격했습니까?', `MaleText_loc4`='你明白发生了什么事吗？', `MaleText_loc5`='你有看到剛剛發生的事情?', `MaleText_loc7`='¿Has visto lo que ha pasado?', `FemaleText_loc1`='무슨 일이 일어났는지 목격하셨나요?', `FemaleText_loc4`='你明白发生了什么事吗？', `FemaleText_loc5`='你有看到剛剛發生的事情?', `FemaleText_loc7`='¿Has visto lo que ha pasado?' WHERE `ID`=47751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 사람이 병영에서 갑자기 비틀거리며 나타났어요.$b$b난 도와달라고 비명을 질렀지만, 경비병들은 쳐다보지도 않더군요!', `FemaleText_loc4`='他就从那座兵营里跌跌撞撞地爬了出来。$b$b我尖叫着寻求援助，但那些卫兵甚至不看我一眼！', `FemaleText_loc5`='他剛從軍營跌跌撞撞跑了出來。$b$b我大聲叫人幫忙，可是衛兵根本連看都不看我一眼!', `FemaleText_loc7`='Salió dando tumbos del cuartel.$b$bPedí ayuda a gritos, ¡pero los guardias ni me miraron!' WHERE `ID`=47752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 잠깐 누워서 쉬는 편이 좋겠습니다.', `MaleText_loc4`='也许你应该躺一会儿。', `MaleText_loc5`='也許你該去躺一下。', `MaleText_loc7`='Quizá debieras echarte un rato.', `FemaleText_loc1`='가서 잠깐 누워서 쉬는 편이 좋겠어요.', `FemaleText_loc4`='也许你应该躺一会儿。', `FemaleText_loc5`='也許你該去躺一下。', `FemaleText_loc7`='Quizá debieras echarte un rato.' WHERE `ID`=47753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네.$b$b그거 정말 좋은 생각이네요.', `FemaleText_loc4`='是的。$b$b听起来像是个好主意。', `FemaleText_loc5`='沒錯。$b$b真是個好主意。', `FemaleText_loc7`='Sí.$b$bParece una buena idea.' WHERE `ID`=47754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 나의 종복이여, 너희의 주인을 도와라!', `MaleText_loc4`='我的天！仆人们，帮帮你们的主人！！', `MaleText_loc5`='我的天啊!男僕，快來幫你們主人!!', `MaleText_loc7`='¡Cielos! ¡Sirvientes, ayuden a su señor!' WHERE `ID`=47755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 여기서 그만두지! 이제 손에 피를 묻힐 시간이다!', `MaleText_loc4`='玩够了！现在该是下手的时候了！', `MaleText_loc5`='好，玩夠了!該是我雙手染血的時候了!', `MaleText_loc7`='¡Ya basta de juegos! ¡Hora de mancharme las manos!' WHERE `ID`=47756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자리를 잡아라, 애송이들아. 대학살이란 게 무엇인지 내가 가르쳐 주지!', `MaleText_loc4`='赶快坐好，小伙子们。我要让你们知道什么才是真正的战斗！', `MaleText_loc5`='大家找張椅子坐好，我來教教你們什麼才叫真正的兇殘!', `MaleText_loc7`='Tomen asiento, chicos. ¡Permítanme que los prepare para un poco de masacre de verdad!' WHERE `ID`=47757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료들이 통로를 확보했습니다. 주 격실에 있는 사람들을 돕는 일에 집중해 주십시오.', `MaleText_loc4`='我们的人已经守住了通道。现在要集中全力帮助主室中的人了。', `MaleText_loc5`='走道的敵人已經都被我們的人解決掉了。把重點放在協助還在主大廳裡的人。', `MaleText_loc7`='Nuestros hombres tienen el control de la pasarela. Concéntrate en ayudar a los que están en la sala principal.' WHERE `ID`=47758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s|1이;가; |cFF1CF2FE$n|r에게|cFF1CF2FE|Hspell:79888|h [번개 전도체]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s施放|cFF1CF2FE|Hspell:79888|h [闪电导体]|h|r，目标为|cFF1CF2FE$n|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s對|cFF1CF2FE$n|r施展|cFF1CF2FE|Hspell:79888|h [避雷針]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_staticshock.blp:20|t¡%s lanza|cFF1CF2FE|Hspell:79888|h [Pararrayos]|h|r a |cFF1CF2FE$n|r!' WHERE `ID`=47759;
