UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 내 명령을 따라라! 날 태워라!', `MaleText_loc4`='巨龙，听从我的命令！接住我！', `MaleText_loc5`='龍啊，聽我命令! 抓住我!', `MaleText_loc7`='¡Dragón, harás lo que te ordeno! ¡Atrápame!' WHERE `ID`=47767;
