UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 너를 못 죽이면 내가 그렇게 해 주지!', `MaleText_loc4`='如果他们没有杀掉你，就由我来亲自动手吧！', `MaleText_loc5`='如果他們不殺你，我會親自動手!', `MaleText_loc7`='¡Si ellos no te matan, lo haré yo!' WHERE `ID`=47769;
