UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이와크 마크 오우, 이와크 막 싸아크. 이와크 마 쉬픈.', `MaleText_loc4`='Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg''fhn.', `MaleText_loc5`='(聽不懂的胡言亂語)', `MaleText_loc7`='Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg''fhn.' WHERE `ID`=47773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플라크 겟! 어둠은 항상 굶주려 있다!', `MaleText_loc4`='F''lakh ghet！黑暗的饥饿永无止尽！', `MaleText_loc5`='(胡言亂語)!暗影的飢渴是無法滿足的!', `MaleText_loc7`='¡F''lakh ghet! ¡El hambre de la sombra es insaciable!' WHERE `ID`=47774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 대포는 해안가를 향하고 있습니다. 갓 넣은 화약과 기폭 장치도 준비되어 있습니다.$B$B정말 편리하군요!', `MaleText_loc4`='这门大炮直指海岸，而且炮膛里已经填满了弹药，安放好了引信。$B$B这可真方便啊！', `MaleText_loc5`='這門大砲像是已經直接瞄準著岸邊的，而且火藥和引信也都換好裝好了。$B$B多方便啊!', `MaleText_loc7`='Este cañón parece apuntar directamente a la costa, tiene una carga de pólvora recién aplicada y la mecha ya está lista.$b$b¡Qué conveniente!' WHERE `ID`=47775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어가서 불을 붙이겠습니다! 뭐 잘못될 거 있겠어요?', `MaleText_loc4`='我要让它响起来！现在还能有什么问题？', `MaleText_loc5`='我要進去發射它!能出什麼差錯?', `MaleText_loc7`='¡Me meteré dentro y lo dispararé! ¿Qué podría ir mal?', `FemaleText_loc1`='들어가서 불을 붙일게요! 뭐 잘못될 거 있겠어요?', `FemaleText_loc4`='我要让它响起来！现在还能有什么问题？', `FemaleText_loc5`='我要進去發射它!能出什麼差錯?', `FemaleText_loc7`='¡Me meteré dentro y lo dispararé! ¿Qué podría ir mal?' WHERE `ID`=47776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 이거 처리 못 하면 트롱구스 매 맞는다.', `MaleText_loc4`='不！索朗格斯干不好就又要挨鞭子了！', `MaleText_loc5`='不!瑟隆葛斯不幹掉你們又會被鞭打的!', `MaleText_loc7`='¡NO! ¡Látigos a Throngus si no termina!' WHERE `ID`=47777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롱구스가 네 몸 쓸 거다. 어디에 쓰지...', `MaleText_loc4`='索朗格斯会为你找个好去处的……', `MaleText_loc5`='瑟隆葛斯用得上你的屍體...應該吧...', `MaleText_loc7`='Throngus usar tu cadáver en cuerpo. En algún lado…' WHERE `ID`=47778;
