UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽는 거... 괜찮다. 제일 좋은 건 아니지만, 실패하고 매 맞는 것보단...', `MaleText_loc4`='死亡……虽然不是最好的选择，但总比失败以后活着好。', `MaleText_loc5`='死亡...好選擇。也許不是最好的，但總比失敗地活著好。', `MaleText_loc7`='Muerte... Elegir bien. No es lo mejor, pero mejor que fallar y vivir.' WHERE `ID`=47780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하, 이건 절대로 못 뚫을 거다!', `MaleText_loc4`='你无法突破这防御！', `MaleText_loc5`='你不會穿過防禦!', `MaleText_loc7`='¡Tú no pasar defensas!' WHERE `ID`=47781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으헤헤, 이건 아플 거다!', `MaleText_loc4`='哦，尝尝什么叫疼！', `MaleText_loc5`='噢，這會很痛喔!', `MaleText_loc7`='¡Uy, esto DOLER!' WHERE `ID`=47782;
