UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 부하들이 내 명령을 기다린다. 네놈들이 어쩌겠다는 거냐?', `MaleText_loc4`='我的奴仆何止成千上万。你有什么机会战胜我？', `MaleText_loc5`='我還有數以百萬計的手下。你有機會嗎?', `MaleText_loc7`='Un millón más esperan mis órdenes. ¿Qué chances tienen?' WHERE `ID`=47784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 저녁밥이다!', `MaleText_loc4`='爬虫们，你们的晚餐来了！', `MaleText_loc5`='害蟲，你的晚餐等著呢!', `MaleText_loc7`='¡Alimañas, su cena los espera!' WHERE `ID`=47785;
