UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼이여, 훈련을 받으러 온 건가?', `MaleText_loc4`='你是来接受训练的吗，猎人？', `MaleText_loc5`='你是要來接受訓練的嗎，獵人?', `MaleText_loc7`='¿Has venido para entrenarte, $gcazador:cazadora;?', `FemaleText_loc1`='사냥꾼이여, 훈련을 받으러 온 건가?', `FemaleText_loc4`='你是来接受训练的吗，猎人？', `FemaleText_loc5`='你是要來接受訓練的嗎，獵人?', `FemaleText_loc7`='¿Has venido para entrenarte, $gcazador:cazadora;?' WHERE `ID`=47789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예, 대장님. 에... 그런데 이걸 어디 끼우는 거죠?', `FemaleText_loc4`='没问题，头儿。呃……我要把它插在哪儿？', `FemaleText_loc5`='是，老大。呃...我放到哪兒去了?', `FemaleText_loc7`='Entendido, jefe. Esto... ¿dónde la pongo?' WHERE `ID`=47790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 거기... 잠깐... 열쇠구멍이 어디 있는 거야? 이게 대체 뭐냐고?', `MaleText_loc4`='就把它插在……等等……锁眼在哪里？真是 一团乱！', `MaleText_loc5`='你只要把它放進...慢著...鑰匙孔在那裡?這是在搞什麼飛機?', `MaleText_loc7`='Ponla justo en la... Espera... ¿dónde está la cerradura? ¿Qué chanchullo es este?' WHERE `ID`=47791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇, 집어치워. 티커, 네 차례다!', `MaleText_loc4`='拧它。钟摆，你来！', `MaleText_loc5`='可惡。提克爾，換你上!', `MaleText_loc7`='Qué más da. ¡Tictac, te toca!' WHERE `ID`=47792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 착수하겠습니다, 대장님!', `MaleText_loc4`='好的，头儿！', `MaleText_loc5`='馬上辦，老大!', `MaleText_loc7`='¡Ahora mismo, jefe!' WHERE `ID`=47793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이런 짓을 하고 있다니 믿기지가 않는군. 대공작 칼신더의 존재가 우리 모두를 위협하고 있다는 건 알지만, 그게 정말인지도 모르잖나? 그리고 이런 일은 대지 고리회인가 뭔가 하는 자들이 전문인 것 같은데. 안 그런가?$b$b왜 항상 토륨 대장조합이 나서야 하는 거지?', `MaleText_loc4`='真难以相信，我们竟然在做这个。我知道，卡尔烬德的出现会让我们全都受到威胁。但这是真的吗？统治这里的不是大地之环吗？还是别的什么组织？$b$b为什么瑟银兄弟会要如此大动干戈？', `MaleText_loc5`='真不敢相信我們竟然在幹這種事情。我知道卡爾希德對大家都造成了極大的威脅，可是，真的嗎?這難道不該是陶土議會還是哪個組織的事情嗎?$b$b為什麼每次都要瑟銀兄弟會來收拾?', `MaleText_loc7`='No puedo creer que estemos haciendo esto. Ya sé que la presencia de Rescoldo es una amenaza para todos nosotros, pero... ¿en serio? ¿No os parece el terreno del Anillo de la Tierra o algo así?$b$b¿Por qué siempre tiene que ser la Hermandad del Torio la que tiene que ir a salvar el mundo?' WHERE `ID`=47794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄 설치 완료했습니다. 이제 떨어지시는 게 좋겠습니다!', `MaleText_loc4`='炸药已经准备好了。足够的力量能摆平一切！', `MaleText_loc5`='炸藥裝好了。趕快閃人!', `MaleText_loc7`='Las cargas están listas. ¡Quizá quieras alejarte un poco!' WHERE `ID`=47795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택할 수 있는 건 죽음뿐...', `MaleText_loc4`='死亡是我唯一的选择。', `MaleText_loc5`='死亡是我唯一的選擇。', `MaleText_loc7`='La muerte es mi única opción.' WHERE `ID`=47796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기막히게 해냈군. 열쇠는 무슨 얼어 죽을 놈의 열쇠...', `MaleText_loc4`='像是个魔法符咒。钥匙又有什么用……', `MaleText_loc5`='輕鬆搞定。誰需要鑰匙啊...', `MaleText_loc7`='De maravilla. Quién quiere llaves...' WHERE `ID`=47797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞길을 막는 자 살아남지 못하리라!', `MaleText_loc4`='挡我道者必死无疑！', `MaleText_loc5`='擋我路者死!', `MaleText_loc7`='¡Destruiré todo en mi camino!' WHERE `ID`=47798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격해라, 이 겁쟁이들아!', `MaleText_loc4`='快进攻，你们这些胆小的爬虫！', `MaleText_loc5`='快上啊，你們這些膽小的害蟲!', `MaleText_loc7`='¡Ataquen, alimañas cobardes!' WHERE `ID`=47799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 회오리 방패를 가까이 끌어당깁니다!', `MaleText_loc4`='%s收回了他的旋风之盾！', `MaleText_loc5`='%s收起了她的颶風之盾!', `MaleText_loc7`='¡%s retira su Escudo de ciclón!' WHERE `ID`=47800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 거점에 온 것을 환영하네. 나는 감독관으로서 토륨 대장조합에서 일어나는 모든 일을 책임지고 있다네. 우리가 주로 하는 일은 채광과 대장, 그리고 가벼운 경계 임무지만, 최근 들어 우리는 부득이하게도... 군사조직에 더욱 가깝게 변모했다네.', `MaleText_loc4`='欢迎来到瑟银哨塔。作为这里的工头，我负责管理瑟银兄弟会的一切行动。我们的主要工作是采矿，锻造，还有一些辅助性的守卫工作。但最近我们越来越向军事化发展了……这实在是没有必要。', `MaleText_loc5`='歡迎來到瑟銀哨塔。身為監督者，我負責統籌瑟銀兄弟會在此處的所有活動。雖然主要在忙的事情不外乎採礦、鍛造，還有些守衛排班的事情，但是最近我們開始越來越像個軍事組織了...迫於需要。', `MaleText_loc7`='Bienvenido al Puesto del Torio. Como supervisor, soy responsable de todas las actividades de la Hermandad del Torio. Aunque tales actividades suelen ser la minería, la herrería y algún que otro turno de guardia, últimamente nos hemos vuelto una organización más marcial... Por necesidad.' WHERE `ID`=47801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿가루 채석장 내부로 이렇게 깊숙이까지 들어왔군, $n. 이제 임무를 완수할 때가 왔네.', `MaleText_loc4`='$n，我们已经进入了熔渣之池。现在该是最终完成工作的时候了。', `MaleText_loc5`='我們已經推進到了熔渣之池，$n。現在該是把事情做個了結的時候了。', `MaleText_loc7`='Hemos llegado hasta aquí, en la Fosa de la Escoria, $n. Ahora toca terminar el trabajo.' WHERE `ID`=47802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네라면 언제든지 환영이네, $n.', `MaleText_loc4`='$n，我们任何时候都欢迎你。', `MaleText_loc5`='我們隨時都歡迎你，$n。', `MaleText_loc7`='Siempre serás $gbienvenido:bienvenida; entre nosotros, $n.' WHERE `ID`=47803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 임시 마법 흡수장을 생성합니다!', `MaleText_loc4`='%s施放了不稳定的接地场！', `MaleText_loc5`='%s召喚出了一道臨時的接地力場!', `MaleText_loc7`='¡%s invoca un campo derribador temporal!' WHERE `ID`=47804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 것들! 흑요암이여, 일어나라! 그리고 침입자를 처치하라!', `MaleText_loc4`='蠢货。奥比斯顿！起来，消灭入侵者！', `MaleText_loc5`='一群笨蛋。奧比斯頓!起來，消滅這些闖入者!', `MaleText_loc7`='Necios. ¡Obsidion! ¡Levántate y destruye a los intrusos!' WHERE `ID`=47805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑소다르는 내 간청에 답하지 않았네, $n. 불쌍한 막투르를 도울 자는 자네밖에 없어.', `MaleText_loc4`='埃索达没有回应我的请求，$n。恐怕只有你才能帮可怜的玛格图尔。', `MaleText_loc5`='艾克索達沒有理會我的請求，$n。恐怕只有你才幫得了可憐的瑪格圖爾。', `MaleText_loc7`='El Exodar no ha respondido a mis súplicas, $n. Me temo que solo tú puedes ayudar al pobre Magtoor.' WHERE `ID`=47806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 막투르의 죽음을 기억하며 연구를 계속하겠네.', `MaleText_loc4`='我会为了玛格图尔继续研究下去。', `MaleText_loc5`='為了瑪格圖爾，我會繼續完成我的追尋。', `MaleText_loc7`='Proseguiré con mi investigación en memoria de Magtoor.' WHERE `ID`=47807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 도와줄 거라도 있습니까?', `MaleText_loc4`='有什么需要我们帮忙的吗？', `MaleText_loc5`='我們幫得上什麼忙嗎?', `MaleText_loc7`='¿Podemos hacer algo para ayudar?', `FemaleText_loc1`='우리가 도와줄 거라도 있나요?', `FemaleText_loc4`='有什么需要我们帮忙的吗？', `FemaleText_loc5`='我們幫得上什麼忙嗎?', `FemaleText_loc7`='¿Podemos hacer algo para ayudar?' WHERE `ID`=47808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대나 제가 도와줄 거라도 있습니까?', `MaleText_loc4`='我和我的军队能帮上什么忙吗？', `MaleText_loc5`='有任何我或者我的部隊可以幫得上忙的嗎?', `MaleText_loc7`='¿Hay algo que podamos hacer mis tropas o yo?', `FemaleText_loc1`='우리 부대나 제가 도와줄 거라도 있나요?', `FemaleText_loc4`='我和我的军队能帮上什么忙吗？', `FemaleText_loc5`='有任何我或者我的部隊可以幫得上忙的嗎?', `FemaleText_loc7`='¿Hay algo que podamos hacer mis tropas o yo?' WHERE `ID`=47809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 더 도울 방법은 없습니까, 니카?', `MaleText_loc4`='真的没什么需要我们帮忙了吗，尼卡？', `MaleText_loc5`='你確定我們真的都幫不上忙嗎，尼卡?', `MaleText_loc7`='¿Seguro que no hay nada más que podamos hacer, Neeka?', `FemaleText_loc1`='우리가 더 도울 방법은 없나요, 니카?', `FemaleText_loc4`='真的没什么需要我们帮忙了吗，尼卡？', `FemaleText_loc5`='你確定我們真的都幫不上忙嗎，尼卡?', `FemaleText_loc7`='¿Seguro que no hay nada más que podamos hacer, Neeka?' WHERE `ID`=47810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬그럼을 위해 우리가 할 수 있는 게 있습니까?', `MaleText_loc4`='我们一点儿都帮不到赫格拉姆吗？', `MaleText_loc5`='我們沒辦法幫赫格拉姆做點什麼嗎?', `MaleText_loc7`='¿No hay nada que podamos hacer por Helgrum?', `FemaleText_loc1`='헬그럼을 위해 우리가 할 수 있는 게 있나요?', `FemaleText_loc4`='我们一点儿都帮不到赫格拉姆吗？', `FemaleText_loc5`='我們沒辦法幫赫格拉姆做點什麼嗎?', `FemaleText_loc7`='¿No hay nada que podamos hacer por Helgrum?' WHERE `ID`=47811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자리를 지키고 얼라이언스 떨거지들이 가까이 오지 못하게 막으십시오.', `MaleText_loc4`='坚守阵地，别让任何联盟渣滓靠近我们。', `MaleText_loc5`='守好你的崗位，別讓任何聯盟的垃圾接近我們。', `MaleText_loc7`='Sigan en sus puestos, y mantengan a la escoria de la Alianza lejos de nosotros.', `FemaleText_loc1`='자리를 지키고 얼라이언스 떨거지들이 가까이 오지 못하게 막으세요.', `FemaleText_loc4`='坚守阵地，别让任何联盟渣滓靠近我们。', `FemaleText_loc5`='守好你的崗位，別讓任何聯盟的垃圾接近我們。', `FemaleText_loc7`='Sigan en sus puestos, y mantengan a la escoria de la Alianza lejos de nosotros.' WHERE `ID`=47812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자리를 지키고 언제라도 공격해 들어올 수 있는 얼라이언스에 주의하십시오.', `MaleText_loc4`='坚守阵地，小心任何伺机进犯的联盟。', `MaleText_loc5`='堅守崗位，注意任何可能來犯的聯盟。', `MaleText_loc7`='Mantened el terreno y estad alerta por si la Alianza intenta atacar.', `FemaleText_loc1`='자리를 지키고 언제라도 공격해 들어올 수 있는 얼라이언스에 주의하세요.', `FemaleText_loc4`='坚守阵地，小心任何伺机进犯的联盟。', `FemaleText_loc5`='堅守崗位，注意任何可能來犯的聯盟。', `FemaleText_loc7`='Mantened el terreno y estad alerta por si la Alianza intenta atacar.' WHERE `ID`=47813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 얼라이언스가 공격해 올 수 있으니 유의하십시오. 우리가 이들을 고통스럽게 하면 다시 공격해 올 것입니다.', `MaleText_loc4`='留意联盟。要是他们胆敢再来进犯，我们一定要让他们好看。', `MaleText_loc5`='注意是否還有聯盟的傢伙。他們要是敢再來的話，就要讓他們知道厲害。', `MaleText_loc7`='Cuidado con la Alianza. Les haremos sufrir si intentan otro ataque.', `FemaleText_loc1`='더 많은 얼라이언스가 공격해 올 수 있으니 유의하세요. 우리가 이들을 고통스럽게 하면 다시 공격해 올 거예요.', `FemaleText_loc4`='留意联盟。要是他们胆敢再来进犯，我们一定要让他们好看。', `FemaleText_loc5`='注意是否還有聯盟的傢伙。他們要是敢再來的話，就要讓他們知道厲害。', `FemaleText_loc7`='Cuidado con la Alianza. Les haremos sufrir si intentan otro ataque.' WHERE `ID`=47814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 얼라이언스 공격이 들어올 수 있으니 모두 방어 태세를 갖추십시오.', `MaleText_loc4`='所有人，全力防范联盟的攻击。', `MaleText_loc5`='所有人提高警覺，注意聯盟是否還有再發動攻擊。', `MaleText_loc7`='Aseguraos de que estáis todos preparados para futuros ataques de la Alianza.', `FemaleText_loc1`='더 많은 얼라이언스 공격이 들어올 수 있으니 모두 방어 태세를 갖추세요.', `FemaleText_loc4`='所有人，全力防范联盟的攻击。', `FemaleText_loc5`='所有人提高警覺，注意聯盟是否還有再發動攻擊。', `FemaleText_loc7`='Aseguraos de que estáis todos preparados para futuros ataques de la Alianza.' WHERE `ID`=47815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히히... 히히히... 하하하!', `MaleText_loc4`='嘿嘿……嘿嘿嘿……哈哈哈！', `MaleText_loc5`='嘻嘻..嘻嘻嘻...哈哈哈!', `MaleText_loc7`='Ji, ji... Ji, ji, ji... ¡Ja, ja, ja!' WHERE `ID`=47816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 밖에서 네 소리를 들을 수도 있단 말이야, 바보야!', `MaleText_loc4`='嘘！会被他们听见的，呆瓜！', `MaleText_loc5`='噓!笨蛋，會被他們聽到!', `MaleText_loc7`='¡Shh! ¡Te van a oír, tonto!' WHERE `ID`=47817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 바보라고 부르지 마, 바보야!', `MaleText_loc4`='不许叫我呆瓜，你这呆瓜！', `MaleText_loc5`='別叫我笨蛋，笨蛋!', `MaleText_loc7`='¡No me llames tonto, tonto!' WHERE `ID`=47818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아오! 이제 우리 모습이 보일 거야!', `MaleText_loc4`='嗷！现在他们发现我们了！', `MaleText_loc5`='呃啊!被他們看到了啦!', `MaleText_loc7`='¡Ay! ¡Ahora pueden vernos!' WHERE `ID`=47819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='튀어!', `MaleText_loc4`='快跑！', `MaleText_loc5`='跑!', `MaleText_loc7`='¡Corre!' WHERE `ID`=47820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 야수여. 너는 이제 용아귀 부족의 것이다.', `MaleText_loc4`='没错，野兽。你现在听命于龙喉氏族了。', `MaleText_loc5`='沒錯，野獸。你現在是屬於龍喉氏族的了。', `MaleText_loc7`='Así es, bestia. Ahora perteneces a los Faucedraco.' WHERE `ID`=47821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하지 않는다면, 너를 갈기갈기 찢어 버릴 것이다.', `MaleText_loc4`='要是你不听话，我们就把你砍成碎片。', `MaleText_loc5`='要是你不聽話，我們就會把你大卸八塊。', `MaleText_loc7`='Y si no obedeces, te cortaremos en trocitos.' WHERE `ID`=47822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='인상적이군. 약해진 비룡을 완벽하게 지배할 수 있다니.', `FemaleText_loc4`='很好。趁那家伙处于虚弱状态，完成对它的控制。', `FemaleText_loc5`='幹得好。趁野獸變弱的時候徹底控制住牠。', `FemaleText_loc7`='Impresionante. Una dominación total del animal mientras está debilitado.' WHERE `ID`=47823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말해 보시오, 그대가 사용한 그 부적이 무엇이오?', `FemaleText_loc4`='告诉我，你用的是什么魔法？', `FemaleText_loc5`='告訴我，你用的這個魔法物品是什麼?', `FemaleText_loc7`='Cuéntame, ¿qué embelesamiento estás utilizando?' WHERE `ID`=47824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 사슬이라고 하오. 사용자가 자신의 의지를 마치 육체적 힘처럼 휘두를 수 있게 해주는 물건이지.', `MaleText_loc4`='恶魔之链。它能将我们的意志转换为战斗力。', `MaleText_loc5`='惡魔鎖鍊。它會把我們意識投射出來，就像有形之物一樣。', `MaleText_loc7`='La cadena del Demonio. Proyecta nuestra voluntad como una fuerza física.' WHERE `ID`=47825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드라고? 난 호드를 경멸하오! 우리의 적은 약하고 분열되어 있소! 그런데도 헬스크림 따위와 거래를 하다니! 용아귀 부족은 독립적인 부족이오!', `MaleText_loc4`='部落？我呸你个部落！我们的敌人是一盘无力的散沙，你却跟地狱咆哮讲条件？龙喉无人能及！', `MaleText_loc5`='部落?我去你的部落!我們的敵人弱小微不足道，而你竟然和地獄吼在打交道?龍喉氏族是獨立的!', `MaleText_loc7`='¿La Horda? ¡ESCUPO a tu Horda! Nuestros enemigos son débiles y están divididos, ¿y aun así negocian con Grito Infernal? ¡Los Faucedraco están solos!' WHERE `ID`=47826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 증명해 보이겠소. 썬더마에 있는 와일드해머 부족을 공격하겠소.', `MaleText_loc4`='我会证明给你看。我会向桑德玛尔的蛮锤部族发起攻击。', `MaleText_loc5`='我會證明給你看。我會打敗桑德瑪的蠻錘矮人。', `MaleText_loc7`='Te lo demostraré. Atacaré a los Martillo Salvaje en Bramal.' WHERE `ID`=47827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 승리를 거두고 돌아오면, 용아귀 부족이 누구를 "대족장"이라고 부르는지 봅시다.', `MaleText_loc4`='当我凯旋而归时，我们倒看看龙喉的族人管谁叫“酋长”。', `MaleText_loc5`='等我凱旋歸來的時候，我們再來看看龍喉氏族到底要叫誰「大酋長」。', `MaleText_loc7`='Cuando regrese victorioso ya veremos a quién llaman los Faucedraco "Jefe de Guerra".' WHERE `ID`=47828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 어떻게 온 거지? 내가 직접 널 부숴주겠다!', `MaleText_loc4`='你是怎么进来的？我要杀了你！', `MaleText_loc5`='你是怎樣混過來的?看我殺了你!', `MaleText_loc7`='¿Cómo has llegado aquí? ¡Te destruiré!' WHERE `ID`=47829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 비룡기수 편대와 호드의 지원만 있으면 우리는 황혼의 요새를 공격할 수 있을 거요.', `FemaleText_loc4`='在龙骑士与部落的支持下，我们可以对暮光堡垒发起攻击。', `FemaleText_loc5`='有了你的飛龍騎兵和部落的支援，我們就可以對暮光堡壘發動攻擊。', `FemaleText_loc7`='Con tu flota de jinetes de draco y el apoyo de la Horda, podemos asaltar El Bastión del Crepúsculo.' WHERE `ID`=47830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역심이 담긴 말을 한마디만 더 하면 내 그대에게 분수를 가르쳐 줄 것이오, 나크랄.', `FemaleText_loc4`='再敢口出妄言，我就会送你到你该去的地方，纳克拉尔。', `FemaleText_loc5`='你敢再說一句不忠的話，我就當場宰了你，納克拉爾。', `FemaleText_loc7`='Otra palabra traicionera y te pondré en tu sitio, Narkrall.' WHERE `ID`=47831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나크랄! 내게 도전하고 싶다면 지금 이 자리에서 그리하시오. 바보 같은 전투로 우리 병력을 낭비하지 마시오!', `FemaleText_loc4`='纳克拉尔！要是你想挑战我，就在这儿解决。不要把我们的兵力浪费在愚蠢的征讨上。', `FemaleText_loc5`='納克拉爾!要挑戰我，現在就來吧。不要害我們的部隊白白犧牲。', `FemaleText_loc7`='¡Narkrall! Si quieres desafiarme, hazlo aquí. No malgastes nuestras fuerzas en una cruzada sin sentido.' WHERE `ID`=47832;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 구해주시다니 고마워요, $n 님.$B$B이제 마가타를 풀어주고 버섯구름 봉우리에서 황혼의 망치단을 뿌리 뽑아봐요.', `FemaleText_loc4`='多谢你让我重获自由，$n。$B$B现在让我们看看能不能救出玛加萨，并终结暮光之锤在千针石林的罪恶行径。', `FemaleText_loc5`='謝謝你救了我，$n，我欠你一份大恩情。$B$B現在，我們去看看有沒有辦法釋放瑪加薩，終結暮光之錘在千針石林的陰謀。', `FemaleText_loc7`='Te debo mucho por mi libertad, $n.$b$bAhora veamos si podemos liberar a Magatha y poner fin al Martillo Crepuscular en Las Mil Agujas.' WHERE `ID`=47833;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 안녕하세요. 이쪽은 안전하답니다.', `FemaleText_loc4`='嘿你好啊。这下面没问题了。', `FemaleText_loc5`='嗨，下面這邊都沒問題了。', `FemaleText_loc7`='Hola. Todo despejado aquí abajo.' WHERE `ID`=47834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌입니다! 물속으로 뛰어들어 떨쳐내십시오!', `MaleText_loc4`='蜜蜂！快跳进水里把它们甩掉！', `MaleText_loc5`='蜜蜂!跳進水裡躲開它們!', `MaleText_loc7`='¡ABEJAS! ¡Métete en el agua para espantarlas!', `FemaleText_loc1`='벌입니다! 물속으로 뛰어들어 떨쳐내십시오!', `FemaleText_loc4`='蜜蜂！快跳进水里把它们甩掉！', `FemaleText_loc5`='蜜蜂!跳進水裡躲開它們!', `FemaleText_loc7`='¡ABEJAS! ¡Métete en el agua para espantarlas!' WHERE `ID`=47835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 맞서라, $r|1이여;여;, 그리고 군단의 분노를 느껴라!', `MaleText_loc4`='面对我，$r，感受军团的愤怒吧！', `MaleText_loc5`='面對我，$r，見識軍團的憤怒!', `MaleText_loc7`='¡Enfréntate a mí, $r, y prueba la ira de la legión!' WHERE `ID`=47836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 늑대인간들은 우리 포로일세. 놈들의 목숨은 총사령관님 손에 달렸지.', `MaleText_loc4`='这些狼人是我们的阶下囚。它们将由最高统帅部来发落。', `MaleText_loc5`='這些狼人是我們的囚犯，他們的生死全操在我們最高指揮部的手裡。', `MaleText_loc7`='Estos huargen son nuestros prisioneros. Su destino está en las manos del Alto Mando.' WHERE `ID`=47837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비룡에 올라타십시오!', `MaleText_loc4`='跳到龙背上来！', `MaleText_loc5`='跳到龍背上!', `MaleText_loc7`='¡Súbete al draco!' WHERE `ID`=47842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 게 뭐냐? 그 웃는 얼굴에 망치 자국 내주기 전에 어서 내 앞에서 썩 꺼져!', `MaleText_loc4`='你想干什么，小矮子？趁我还没拿锤子把你的笑脸砸扁，赶紧从我面前消失！', `MaleText_loc5`='你要做什麼，廢物?從我面前滾開，省得我用戰錘把你的笨蛋笑臉給敲掉!', `MaleText_loc7`='¿Qué quieres, mequetrefe? ¡Sal de mi vista antes de que te borre esa sonrisa de la cara con mi martillo!' WHERE `ID`=47843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흐느끼는 제비꽃을 써서 우리의 목소리를 연결했습니다... 이제 우리의 목소리가 제데나르의 가장 깊은 곳에서든, 어둠의 요새에서든 당신께 들릴 겁니다.', `FemaleText_loc4`='我会把我们的话语封存在悲泣的紫罗兰中……就算是在加德纳尔和暗影堡的最深处，也能听到我们的声音。', `FemaleText_loc5`='我會用這泣鳴紫羅蘭來傳遞我們的話...所以即使你位在加德納爾和暗影堡的最深處，也依然聽得到我們的聲音。', `FemaleText_loc7`='Utilizaré la violeta sollozante para vincular nuestras palabras... Nuestras voces llegarán a ti incluso en las profundidades de Jaedenar y Guarida Sombría.' WHERE `ID`=47844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 $r 따위가 내 타고난 권리를 막을 순 없다!', `MaleText_loc4`='无能的$r别想夺走我的天赋特权！', `MaleText_loc5`='你這卑微的$r不能否決我與生俱來的權力!', `MaleText_loc7`='¡$gNingún patético:Ninguna patética; $r me negará lo que me pertenece por derecho de nacimiento!' WHERE `ID`=47845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드리면 되겠소?', `MaleText_loc4`='我能帮你什么忙吗，$g帅哥:美女;？', `MaleText_loc5`='我可以幫上什麼忙嗎，$g帥哥:美女;?', `MaleText_loc7`='¿En qué te puedo ayudar, $gguapetón:hermosa;?' WHERE `ID`=47846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 난 굉장히 바쁘다고.', `MaleText_loc4`='什么事？我很忙，防卫者。', `MaleText_loc5`='做什麼?我很忙的，防禦者。', `MaleText_loc7`='¿Qué quieres? Estoy muy ocupado, $gdefensor:defensora;.' WHERE `ID`=47847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 황혼의 망치단에게서 관문을 빼앗았소. 용들이 기회를 제공해 줬다고 할 수 있지. 이 기회를 헛되이 하지 않도록 애써야 하오.', `MaleText_loc4`='巨龙给了我们从暮光之锤手中夺取大门的机会。我们一定要善加利用。', `MaleText_loc5`='龍群幫我們爭取到了從暮光之錘手中奪下大門的難得機會，我們可千萬別浪費了。', `MaleText_loc7`='Los dragones nos han proporcionado una oportunidad de tomar las puertas del Martillo Crepuscular. Haríamos bien en aprovecharla.' WHERE `ID`=47848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협곡으로 전진할 준비가 됐습니다. 고블린 분대는 준비되었습니까?', `MaleText_loc4`='我随时可以前往峡谷。小队准备好了吗？', `MaleText_loc5`='我已經準備好朝峽谷裡推進。哥布林戰隊準備好了嗎?', `MaleText_loc7`='Estoy listo para seguir adelante por el cañón. ¿El escuadrón goblin está preparado?', `FemaleText_loc1`='협곡으로 전진할 준비가 됐습니다. 고블린 분대는 준비되었나요?', `FemaleText_loc4`='我随时可以前往峡谷。小队准备好了吗？', `FemaleText_loc5`='我已經準備好朝峽谷裡推進。哥布林戰隊準備好了嗎?', `FemaleText_loc7`='Estoy lista para seguir adelante por el cañón. ¿El escuadrón goblin está preparado?' WHERE `ID`=47849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 준비를 마치고 당신을 기다리고 있었소, $c.', `MaleText_loc4`='他们已经在等你了，$c。', `MaleText_loc5`='他們已經在等你了，$c。', `MaleText_loc7`='Te han estado esperando, $c.' WHERE `ID`=47850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(주인님을 위한 피를!)', `MaleText_loc4`='（鲜血献给主人！）', `MaleText_loc5`='(鮮血!給主人!)', `MaleText_loc7`='(¡Sangre para el amo!)' WHERE `ID`=47851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것이 너희의 운명이다.', `MaleText_loc4`='这就是你的宿命。', `MaleText_loc5`='這就是你的宿命。', `MaleText_loc7`='Así es su destino.' WHERE `ID`=47852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 살덩이들!', `MaleText_loc4`='可悲的血肉之躯！', `MaleText_loc5`='可悲的肉體!', `MaleText_loc7`='¡Carne patética!' WHERE `ID`=47853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(처치해! 모두 처치해버려!)', `MaleText_loc4`='（干掉他，干掉他们所有人！）', `MaleText_loc5`='(快點!快把他們都幹掉!)', `MaleText_loc7`='(¡Acábenlos! ¡A todos!)' WHERE `ID`=47854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 받아들여라.', `MaleText_loc4`='拥抱死亡吧。', `MaleText_loc5`='擁抱你的死亡。', `MaleText_loc7`='Sientan su fin.' WHERE `ID`=47855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에게 힘을 다오!', `MaleText_loc4`='给我你的力量！', `MaleText_loc5`='給我你們的力量!', `MaleText_loc7`='¡Dame tu fuerza!' WHERE `ID`=47856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치의 힘을 느껴 보아라!', `MaleText_loc4`='见证暮光之锤的力量！', `MaleText_loc5`='見證暮光之錘的力量!', `MaleText_loc7`='¡Sientan el poder del martillo!' WHERE `ID`=47857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(멈춰. 망치의 시간이다!)', `MaleText_loc4`='（停。巨锤惩击！）', `MaleText_loc5`='(停。錘人時間!)', `MaleText_loc7`='(Y ahora... ¡el martillo! )' WHERE `ID`=47858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! (그분의 의지에 모두 굴복한다. 그분의 왕국에서 혼돈이 찾아온다.) 그래, 그 말대로다.', `MaleText_loc4`='够了！（为主人碾碎所有血肉，从主人的王国，混乱降临。）对——如他所言。', `MaleText_loc5`='夠了!(血肉都在他意志下屈服。渾沌，來自他的王國。)是的 - 如他所言。', `MaleText_loc7`='¡Suficiente! (La carne acude a Su voluntad. De Su reino brota la maldad.) Eso, lo que dijo él.' WHERE `ID`=47859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(무한한 고통!)', `MaleText_loc4`='（无尽的折磨！）', `MaleText_loc5`='(無盡的苦痛!)', `MaleText_loc7`='(¡Sufrimiento infinito!)' WHERE `ID`=47860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(캬하하하하하!)', `MaleText_loc4`='（*喷鼻息*）', `MaleText_loc5`='(*鼻息*)', `MaleText_loc7`='(*Resoplido*)' WHERE `ID`=47861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 너희의 나약한 세상의 운명을 보라!', `MaleText_loc4`='看看你们这脆弱世界的命运！', `MaleText_loc5`='見證你們卑微世界的宿命!', `MaleText_loc7`='¡Contemplen el destino de su mundo!' WHERE `ID`=47862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(더. 더!)', `MaleText_loc4`='更多。更多！', `MaleText_loc5`='更多。更多!', `MaleText_loc7`='Más. ¡Más!' WHERE `ID`=47863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(어서 와, 형제들! 희망을 집어삼켜!)', `MaleText_loc4`='（来吧，弟兄们！饱餐希望吧！）', `MaleText_loc5`='(來吧，兄弟們!享用希望!)', `MaleText_loc7`='(¡Vengan, hermanos! ¡Devórenlos!)' WHERE `ID`=47864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 또 한 놈이 있다! $r 자식을 없애라!', `MaleText_loc4`='又来一个！杀了那个$r！', `MaleText_loc5`='還有一個!殺了這$r!', `MaleText_loc7`='¡Ahí hay $gotro:otra;! ¡Matad $gal:a la; $r!', `FemaleText_loc1`='당장 거길 떠나라, $r 자식아!', `FemaleText_loc4`='又来一个！杀了那个$r！', `FemaleText_loc5`='滾開這裡，垃圾$r!', `FemaleText_loc7`='¡Aléjate de ahí, escoria $r!' WHERE `ID`=47865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(더. 더 많이 보내.)', `MaleText_loc4`='（更多。他们想要更多。）', `MaleText_loc5`='(更多，他們需要更多。)', `MaleText_loc7`='(Más. Necesitan más.)' WHERE `ID`=47866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가... 와일드해머 부족을 지켜 주고 있소...', `MaleText_loc4`='联盟……他们在守卫蛮锤……', `MaleText_loc5`='聯盟...他們在保護蠻錘的...', `MaleText_loc7`='La Alianza... Defienden a los Martillo Salvaje...' WHERE `ID`=47867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 이럴 순 없어... (운명의 시간이 왔다!) 나의 힘... (자존심하곤! 피범벅인데도 떠드네! 들어봐!) 나의 정신... (우린 그분의 영광을 위해 산다!) 무슨 일이... 일어나는 거냐... (새벽은 가고 황혼의 그림자가 다가온다. 광란이여 오라, 파괴여 오라, 영원한 밤이여 오라!)', `MaleText_loc4`='兄弟，这不可能……（定数已到！）我的力量……（多么骄傲！他在用鲜血昭告！快听！）我的精神……（我们为他的荣耀而效忠！）究竟……是怎么了……（黎明已逝，迎来了暮光之影。来吧疯狂，来吧浩劫，来吧，无尽的黑夜！）', `MaleText_loc5`='兄弟，不可能...(命運已經來臨!)我的力量...(很高傲!有血他才說話!聽!)我的思緒...(為了他的榮耀，我們侍奉!)發生...什麼事了...(曙光退去，暮光之影降臨。來吧狂亂，來吧浩劫，來吧無盡的夜晚!)', `MaleText_loc7`='Hermano, no puede ser... (¡Llega su destino!) Mi fuerza… (¡Tan orgulloso! ¡Habla de sangre! ¡Escuchen!) Mi mente... (¡Servimos a Su gloria!) ¿Qué... ocurre...? (Se va el amanecer. Llega el crepúsculo. ¡Vengan, locura, devastación, noche infinita!)' WHERE `ID`=47868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초계 분대 도착!', `MaleText_loc4`='小队报告情况。', `MaleText_loc5`='小隊報到。', `MaleText_loc7`='Escuadrón informando.' WHERE `ID`=47869;
