UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 이 은혜는 잊지 않겠습니다.', `MaleText_loc4`='谢谢你。我不会忘记你的恩情。', `MaleText_loc5`='謝謝你。我不會忘記的。', `MaleText_loc7`='Gracias. No lo olvidaré.', `FemaleText_loc1`='감사합니다. 이 은혜는 잊지 않을게요.', `FemaleText_loc4`='谢谢你。我不会忘记你的恩情。', `FemaleText_loc5`='謝謝你。我不會忘記的。', `FemaleText_loc7`='Gracias. No lo olvidaré.' WHERE `ID`=47874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빕니다. 구해주셔서 진심으로 감사드립니다.', `MaleText_loc4`='祝你好运。我很感激。', `MaleText_loc5`='我感激在心。祝你好運。', `MaleText_loc7`='Buena suerte. Te lo agradezco.', `FemaleText_loc1`='행운을 빌어요. 구해주시다니 진심으로 감사드려요.', `FemaleText_loc4`='祝你好运。我很感激。', `FemaleText_loc5`='我感激在心。祝你好運。', `FemaleText_loc7`='Buena suerte. Te lo agradezco.' WHERE `ID`=47875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대모, 마가타 그림토템을 찾아오셨습니까? 황혼의 망치단이 동쪽에 가두고 있을 겁니다.', `MaleText_loc4`='你们是来找巫婆长老玛加萨·恐怖图腾的吗？他们把她关在东边了。', `MaleText_loc5`='你是來找長者瑪加薩·恐怖圖騰的嗎?他們把她關在東邊那裡。', `MaleText_loc7`='¿Has venido a por la bruja anciana, Magatha Tótem Siniestro? La retienen al este.', `FemaleText_loc1`='대모, 마가타 그림토템을 찾아오셨어요? 황혼의 망치단이 동쪽에 가두고 있을 거예요.', `FemaleText_loc4`='你们是来找巫婆长老玛加萨·恐怖图腾的吗？他们把她关在东边了。', `FemaleText_loc5`='你是來找長者瑪加薩·恐怖圖騰的嗎?他們把她關在東邊那裡。', `FemaleText_loc7`='¿Has venido a por la bruja anciana, Magatha Tótem Siniestro? La retienen al este.' WHERE `ID`=47876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이교도들은 미쳤습니다. 세상에 종말을 불러오려는 것 같습니다!', `MaleText_loc4`='这些邪教徒简直疯了。他们要毁灭整个世界！', `MaleText_loc5`='這些教徒都瘋了。他們想要引起世界末日!', `MaleText_loc7`='Esos cultores están locos. ¡Intentan desencadenar el fin del mundo!', `FemaleText_loc1`='이 이교도들은 미쳤어요. 세상에 종말을 불러오려는 것 같아요!', `FemaleText_loc4`='这些邪教徒简直疯了。他们要毁灭整个世界！', `FemaleText_loc5`='這些教徒都瘋了。他們想要引起世界末日!', `FemaleText_loc7`='Esos cultores están locos. ¡Intentan desencadenar el fin del mundo!' WHERE `ID`=47877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 저를 제물로 바쳐 정령을 더 소환하는 데 쓰려고 했습니다!', `MaleText_loc4`='他们要献祭我，以召唤更多元素！', `MaleText_loc5`='他們打算要獻祭我以召喚出更多的元素!', `MaleText_loc7`='¡Iban a sacrificarme para invocar más elementales!', `FemaleText_loc1`='놈들은 저를 제물로 바쳐 정령을 더 소환하는 데 쓰려고 했어요!', `FemaleText_loc4`='他们要献祭我，以召唤更多元素！', `FemaleText_loc5`='他們打算要獻祭我以召喚出更多的元素!', `FemaleText_loc7`='¡Iban a sacrificarme para invocar más elementales!' WHERE `ID`=47878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 몫까지 복수해 주십시오.', `MaleText_loc4`='替我复仇。', `MaleText_loc5`='去幫我報仇吧。', `MaleText_loc7`='Véngate en mi nombre.', `FemaleText_loc1`='제 몫까지 복수해 주세요.', `FemaleText_loc4`='替我复仇。', `FemaleText_loc5`='去幫我報仇吧。', `FemaleText_loc7`='Véngate en mi nombre.' WHERE `ID`=47879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우연히 놈들의 대화를 들었는데, 동쪽에 있는 기지에서 뭔가 큰 걸 소환할 준비가 되었다고 하더군요!', `MaleText_loc4`='我听到了他们的交谈。他们正准备在东边的基地里召唤什么大家伙！', `MaleText_loc5`='我有偷聽到他們的話。他們正準備要在東邊的基地那裡召喚出某種強大的東西!', `MaleText_loc7`='Les he oído hablar. ¡Se están preparando para invocar algo grande en su base del este!', `FemaleText_loc1`='우연히 놈들의 대화를 들었는데, 동쪽에 있는 기지에서 뭔가 큰 걸 소환할 준비가 되었다고 하더군요!', `FemaleText_loc4`='我听到了他们的交谈。他们正准备在东边的基地里召唤什么大家伙！', `FemaleText_loc5`='我有偷聽到他們的話。他們正準備要在東邊的基地那裡召喚出某種強大的東西!', `FemaleText_loc7`='Les he oído hablar. ¡Se están preparando para invocar algo grande en su base del este!' WHERE `ID`=47880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 많은 희생과 파괴가 있었습니다. 놈들을 끝장내주십시오!', `MaleText_loc4`='已经有太多人丧命。太多的毁灭。终结他们的恶行！', `MaleText_loc5`='太多的死亡...太多的毀滅。請你結束這一切!', `MaleText_loc7`='Ha habido demasiada muerte. Demasiada destrucción. ¡Acaba con ellos!', `FemaleText_loc1`='너무 많은 희생과 파괴가 있었어요. 놈들을 끝장내주세요!', `FemaleText_loc4`='已经有太多人丧命。太多的毁灭。终结他们的恶行！', `FemaleText_loc5`='太多的死亡...太多的毀滅。請你結束這一切!', `FemaleText_loc7`='Ha habido demasiada muerte. Demasiada destrucción. ¡Acaba con ellos!' WHERE `ID`=47881;
