UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예, 아직 괜찮아요.', `FemaleText_loc4`='嗯，还不错。', `FemaleText_loc5`='嗯，還好。', `FemaleText_loc7`='Sí, estamos bien.' WHERE `ID`=47888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 괜찮아요. 이제 모두 괜찮아졌어요. 고마워요. 그쪽은 어떠세요?', `FemaleText_loc4`='我们很好。我们现在都很好，谢谢你。你怎么样？', `FemaleText_loc5`='我們沒事。謝謝你，我們在這邊都沒事。那你呢?', `FemaleText_loc7`='Estamos bien. Estamos muy bien, gracias. ¿Cómo estás tú?' WHERE `ID`=47889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소, $c.$b$b요즘은 여기까지 찾아오는 사람은 별로 없소.', `MaleText_loc4`='看到你真高兴，$c。$b$b我们最近少有访客。', `MaleText_loc5`='真是榮幸，$c。$b$b最近我們都沒什麼客人。', `MaleText_loc7`='Un placer, $c.$b$bÚltimamente vemos muy pocos visitantes.' WHERE `ID`=47890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 반갑소!$b$b사실 오늘 누가 찾아오리라고는 생각지 않았었소...', `MaleText_loc4`='真意外！$b$b我们以为不会有人来……', `MaleText_loc5`='真是意外!$b$b我們可沒料到今天還有客人...', `MaleText_loc7`='¡Qué sorpresa!$b$bHoy no esperábamos a nadie...' WHERE `ID`=47891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 끝났다. (모두의 운명.)', `MaleText_loc4`='都结束了。（万物的命运。）', `MaleText_loc5`='一切都結束了。(一切的命運。)', `MaleText_loc7`='Se acabó. (El destino de todo.)' WHERE `ID`=47892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여... 우린 패배했다. (하지만 주인님이... 아직 말씀을... 화나셨어... 주인님...?)', `MaleText_loc4`='兄弟，我们败了。（可主人……我还能听到……愤怒……主人……？）', `MaleText_loc5`='兄弟，我們輸了。(但主人...我還是能聽到...很生氣...主人...?)', `MaleText_loc7`='Hermano, estamos destrozados. (Pero el Amo... Lo escucho... Enojado... ¿Amo...?)' WHERE `ID`=47893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 우린 실패했다. 놈들을 그녀의 손에 맡기자... (주인님은 놈들이 그녀 곁에 가는 거 싫어하셔... 형제여...? 주인님이 화나셨어...)', `MaleText_loc4`='兄弟，我们败了。让她解决他们。（主人不想让他们靠近她……兄弟？主人怒不可遏……）', `MaleText_loc5`='兄弟，我們輸了。讓她終結他們吧。(主人不想讓他們接近她...兄弟?主人氣炸了...)', `MaleText_loc7`='Hermano, estamos destrozados. Déjala acabarlos. (El Amo los quiere lejos de ella... ¿Hermano? El Amo está furioso...)' WHERE `ID`=47894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네가 바로 소문이 자자한 $r $c인가 보군. 그렇지?$b$b너도 알다시피, 아직 방첨탑을 하나 더 활성화시켜야 해...$b$b이 고대의 장치를 완벽하게 복구할 때가 왔을 때, 자네도 그 위업에 참가할 수 있을까? 우리 후손들이 널 기억할까?$b$b그건 다 네가 얼마나 열심히 협력하는가에 달려 있다고!', `MaleText_loc4`='这就是那个大名鼎鼎的$r$c，嗯？$b$b如你所知，还有一个尚未被激活的方尖碑……$b$b当复原这古老装置的时机到来时，你会在那里吗？历史会记住你吗？$b$b这取决于你是否愿意合作！', `MaleText_loc5`='原來，這就是最近我一直聽到的那位$r$c，嗯?$b$b你知道，這裡有一個方尖碑還沒有被啟動....$b$b等到復原這座古老裝置的時機成熟時，你會在那裡嗎?歷史會記得你嗎?$b$b那就要看你願不願意配合了!', `MaleText_loc7`='Así que $geste es el:esta es la; $r $c sobre $gel:la; que tanto he oído hablarrr, ¿hmmm?$b$bComo sabes, todavía queda un obelisco porrr activarrr...$b$bCuando llegue el momento de restaurrrar este antiguo mecanismo, ¿estarrrás allí? ¿Te recordarrrá la historia?$b$b¡Eso dependerrrá de tu foluntad de cooperar!' WHERE `ID`=47895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 지도자의 책무와 역할에 아직 익숙하지 않네. 나크랄이 이렇게 반항할 줄 미리 눈치챘어야 했는데, 대비는커녕 그가 저지른 일을 수습하고 있다니.$B$B가로쉬 헬스크림은 어떻게 호드를 이끄는지 궁금하군. 호드처럼 다양한 세력이 모인 집단을 이끄는 걸 보면 엄청난 힘의 소유자일 테지... 그를 좀 더 자세히 알고 싶군.', `FemaleText_loc4`='我没有担当领袖的经验。我应该预见到纳克拉尔的叛逆。而我却只能收拾他留下的烂摊子。$B$B我不知道加尔鲁什·地狱咆哮是如何做到的。他一定具备过人的力量，才能将如此多样化的部落大军凝聚在一起……我愿意更加深入地了解他。', `FemaleText_loc5`='領導的重擔對我而言仍然相當陌生。我應該早料到納克拉爾的反叛是遲早會發生的才對，結果我卻坐視不理，到如今才在收拾他引起的爛攤子。$B$B我不曉得卡爾洛斯·地獄吼是怎樣辦到的，他必定擁有堅強的意志和力量才能讓如此分歧的部落團結在一起...我很想要多瞭解他一些。', `FemaleText_loc7`='No estoy acostumbrada a la carga del liderazgo. Debería haber visto venir la insubordinación de Narkrall, pero en vez de eso tengo que arreglar la que ha montado.$b$bNo sé cómo lo hace Garrosh Grito Infernal. Debe poseer una gran fuerza para mantener unida una entidad tan diversa como la Horda... Me gustaría conocerle más.' WHERE `ID`=47896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s|1이;가; 자신을 도울 |cFFFF0000어둠에 물든 창조물|r을 소환합니다!
', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s开始召唤|cFFFF0000黑暗造物|r来协助他！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s開始召喚|cFFFF0000暗色觸鬚|r來協助他!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_shadesofdarkness.blp:20|t¡%s empieza a invocar |cFFFF0000Creaciones oscurecidas|r para que le ayuden!' WHERE `ID`=47897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠에 있는 소용돌이 누각은 82에서 84 레벨의 플레이어들이 진입하여 초기 테스트할 수 있습니다. 이 던전은 작업 중에 있습니다. 소용돌이 누각으로 순간이동하기 전에 전체 공격대가 갖춰져 있는지 확인하시기 바랍니다.

소용돌이 누각에서 나오려면, 귀환석을 사용하거나 기타 귀환할 수 있는 수단을 사용하여 다른 지역으로 순간이동해야 합니다. 죽어서 다시 살아나게 되면, 제가 있는 곳으로 순간이동해 돌아오게 될 겁니다.', `MaleText_loc4`='现在可以参与旋云之巅的初始测试了，这是位于奥丹姆的一座82-84级地下城。这座地下城目前仍处于开发过程中。请在传送至地下城之前组满队伍。

若要离开旋云之巅，必须使用炉石或类似方式传送出去。如果你在战斗中死亡并释放灵魂，你则需要通过该NPC传送回地下城。', `MaleText_loc5`='漩渦尖塔現在已開放進行測試。漩渦尖塔位於奧丹姆，是一座等級82-84的地城。本地城依然在建構中，請先組好完整隊伍再傳送進地城。

如要離開漩渦尖塔，你必須透過爐石或類似的方式傳送離開。倘若不幸死亡並已釋放靈魂，你可以從這位NPC處傳送回去。', `MaleText_loc7`='La Cumbre del Vórtice, una mazmorra de nivel 82-84 en Uldum, ya está disponible para las pruebas iniciales. La mazmorra es un trabajo en curso. Forma un grupo completo antes de teletransportarte a la mazmorra.

Para abandonar La Cumbre del Vórtice, debes teletransportarte con una piedra de hogar o algún método similar. Si mueres y liberas, deberías volver mediante este PNJ.' WHERE `ID`=47898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(운명의 갈고리가 불신자들을 붙잡는다!)', `MaleText_loc4`='（命运的利爪死死拽住那些无信者！）', `MaleText_loc5`='命運之爪抓住了那些不信者!', `MaleText_loc7`='(¡Las garras del destino asfixian a los herejes!)' WHERE `ID`=47899;
