UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 대체 무슨 짓을 저지른 거지? (아직 안 돼!)', `MaleText_loc4`='我们卷入了何种疯狂？（还远远不够！）', `MaleText_loc5`='我們引發什麼瘋狂的事了?(還不夠!)', `MaleText_loc7`='¿Qué locura hemos creado? (¡Aún no alcanza!)' WHERE `ID`=47901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는... 견딜 수가 없다... (형제여, 이제 막 시작했잖아!)', `MaleText_loc4`='我……再也受不了了……（兄弟，这才刚刚开始！）', `MaleText_loc5`='我...堅持不住了...(兄弟，這只是剛開始!)', `MaleText_loc7`='No… soportaré mucho más… (¡Hermano, apenas comienza!)' WHERE `ID`=47902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(주인님의 눈은 과거와 미래를 봐! 전부 다 본다고!)', `MaleText_loc4`='（主人的双眼能看穿过去与未来，不是吗！）', `MaleText_loc5`='(主人的眼睛看透過去和未來的一切!)', `MaleText_loc7`='(¡El ojo del maestro ve todo lo que fue y será, o no!)' WHERE `ID`=47903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 소용돌이 누각으로 순간이동시켜 주십시오!', `MaleText_loc4`='我在小队中，并已准备好传送到旋云之巅！', `MaleText_loc5`='我已經組好隊伍，而且準備好傳送到漩渦尖塔了!', `MaleText_loc7`='¡Ya estoy en mi grupo y estoy listo para teletransportarme a La Cumbre del Vórtice!', `FemaleText_loc1`='저와 파티원 모두 준비되었습니다. 소용돌이 누각으로 순간이동시켜 주십시오!', `FemaleText_loc4`='我在小队中，并已准备好传送到旋云之巅！', `FemaleText_loc5`='我已經組好隊伍，而且準備好傳送到漩渦尖塔了!', `FemaleText_loc7`='¡Ya estoy en mi grupo y estoy lista para teletransportarme a La Cumbre del Vórtice!' WHERE `ID`=47904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 소용돌이 누각으로 보내주십시오!', `MaleText_loc4`='送我回到旋云之巅！', `MaleText_loc5`='送我回漩渦尖塔!', `MaleText_loc7`='¡Llévame de vuelta a La Cumbre del Vórtice!', `FemaleText_loc1`='저를 소용돌이 누각으로 보내주세요!', `FemaleText_loc4`='送我回到旋云之巅！', `FemaleText_loc5`='送我回漩渦尖塔!', `FemaleText_loc7`='¡Llévame de vuelta a La Cumbre del Vórtice!' WHERE `ID`=47905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 황혼의 망치단에게서 관문을 빼앗았습니다. 용들이 기회를 제공해 줬다고 할 수 있지요. 이 기회를 헛되이 하지 않도록 애써야 합니다.', `MaleText_loc4`='巨龙给了我们从暮光之锤手中夺取大门的机会，我们一定要善加利用。', `MaleText_loc5`='龍群幫我們爭取到了從暮光之錘手中奪下大門的難得機會，我們可千萬別浪費了。', `MaleText_loc7`='Los dragones nos han proporcionado una oportunidad de tomar las puertas del Martillo Crepuscular. Haríamos bien en aprovecharla.' WHERE `ID`=47906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협곡으로 전진할 준비가 됐습니다. 높은 둑 분대는 준비되었습니까?', `MaleText_loc4`='我随时可以前往峡谷。小队准备好了吗？', `MaleText_loc5`='我已經準備好朝峽谷裡推進。隊員們準備好了嗎?', `MaleText_loc7`='Estoy listo para avanzar por el cañón. ¿El escuadrón ya está listo?', `FemaleText_loc1`='협곡으로 전진할 준비가 됐습니다. 높은 둑 분대는 준비되었나요?', `FemaleText_loc4`='我随时可以前往峡谷。小队准备好了吗？', `FemaleText_loc5`='我已經準備好朝峽谷裡推進。隊員們準備好了嗎?', `FemaleText_loc7`='Estoy lista para avanzar por el cañón. ¿El escuadrón ya está listo?' WHERE `ID`=47907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자여, 네 영혼이 드러났구나!', `MaleText_loc4`='向我敞开灵魂，凡人。', `MaleText_loc5`='我收下你的靈魂了，凡人。', `MaleText_loc7`='Entrégame tu alma, mortal.' WHERE `ID`=47908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대는 이미 집합했습니다. 당신이 그림 바톨로 가는 길을 확보해 주리라 믿습니다. 절 실망시키지 마십시오.', `MaleText_loc4`='他们已经集结完毕。我相信你能守住通往格瑞姆巴托的道路。别让我失望。', `MaleText_loc5`='他們已經集合好了。我相信你一定能清出通往格瑞姆巴托的路。別讓我失望了。', `MaleText_loc7`='Ya están reunidos. Confío en ti para que asegures la ruta a Grim Batol. No me decepciones.' WHERE `ID`=47909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아... 역시 끼어들지 말았어야 했어...', `MaleText_loc4`='我就知道不该插手……', `MaleText_loc5`='我就知道我不該介入的...', `MaleText_loc7`='No debí involucrarme en esto...' WHERE `ID`=47910;
