UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르스가 오는군, $n! 내가 악마의 사슬로 그를 지배하는 동안 공격하게.', `FemaleText_loc4`='他来了，$n！把他打败，让我用恶魔之链控制住他。', `FemaleText_loc5`='他來了，$n!趁我使用惡魔鎖鍊控制住他的時候打倒他。', `FemaleText_loc7`='¡Aquí viene, $n! Tú dale mientras yo le domino con la cadena del Demonio.' WHERE `ID`=47917;
