UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언팬츠 박사님은 탐험가의 전당에 있어요.', `MaleText_loc4`='可以在探险者大厅内找到学者教授铁裤。', `MaleText_loc5`='鐵褲教授人應該在探險者大廳裡。', `MaleText_loc7`='Encontrarás al bueno del Doktor Profesor Pantahierro en la Sala de los Expedicionarios.', `FemaleText_loc1`='아이언팬츠 박사님은 탐험가의 전당에 있어요.', `FemaleText_loc4`='可以在探险者大厅内找到学者教授铁裤。', `FemaleText_loc5`='鐵褲教授人應該在探險者大廳裡。', `FemaleText_loc7`='Encontrarás al bueno del Doktor Profesor Pantahierro en la Sala de los Expedicionarios.' WHERE `ID`=47933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 시스템 무효화. 동력 저하...', `MaleText_loc4`='防御系统瘫痪。能源衰减……', `MaleText_loc5`='防禦系統已被摧毀。動力關閉中...', `MaleText_loc7`='Sistemas defensivos eliminados. Apagando…' WHERE `ID`=47934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='김블의 가게에서 마법 재연마사를 찾을 수 있을 거예요. 대용광로에 있는 그리핀 조련사 바로 오른쪽에 시슬퍼즈의 신비한 이야기에서 말입니다.$B$B그가 당신을 잘 가르쳐 줄 겁니다.', `MaleText_loc4`='在吉布的商店——草须魔法用品店里有一位奥术重铸师，就在大锻炉的狮鹫管理员附近。$B$B他属于早已失落的上层精灵一族。但他可以帮上你的忙。', `MaleText_loc5`='你在吉布的草鬚魔法用品店裡就能找到一位秘法重鑄師，在大鍛爐的獅鷲獸管理員那邊。$B$B他也是個消失很久的精靈貴族，但是他可以幫你搞定。', `MaleText_loc7`='Encontrarás un reforjador Arcano en la tienda de Gimble, Arcanería Cardopelusa, justo al lado del maestro de grifos en La Gran Fundición.$b$bEs uno de esos Altonato antaño exiliados, pero puedes confiar en él.', `FemaleText_loc1`='김블의 가게에서 마법 재연마사를 찾을 수 있을 거예요. 대용광로에 있는 그리핀 조련사 바로 오른쪽에 시슬퍼즈의 신비한 이야기에서 말입니다.$B$B그가 당신을 잘 가르쳐 줄 겁니다.', `FemaleText_loc4`='在吉布的商店——草须魔法用品店里有一位奥术重铸师，就在大锻炉的狮鹫管理员附近。$B$B他属于早已失落的上层精灵一族。但他可以帮上你的忙。', `FemaleText_loc5`='你在吉布的草鬚魔法用品店裡就能找到一位秘法重鑄師，在大鍛爐的獅鷲獸管理員那邊。$B$B他也是個消失很久的精靈貴族，但是他可以幫你搞定。', `FemaleText_loc7`='Encontrarás un reforjador Arcano en la tienda de Gimble, Arcanería Cardopelusa, justo al lado del maestro de grifos en La Gran Fundición.$b$bEs uno de esos Altonato antaño exiliados, pero puedes confiar en él.' WHERE `ID`=47935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르스와 싸울 준비가 됐습니다!', `MaleText_loc4`='我已经准备好与托斯交战了！', `MaleText_loc5`='我準備好要跟托斯開戰了!', `MaleText_loc7`='¡Estoy listo para luchar contra Torth!', `FemaleText_loc1`='토르스와 싸울 준비가 됐어요!', `FemaleText_loc4`='我已经准备好与托斯交战了！', `FemaleText_loc5`='我準備好要跟托斯開戰了!', `FemaleText_loc7`='¡Estoy lista para luchar contra Torth!' WHERE `ID`=47936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 당신. 저 좀 밖으로 꺼내주시겠습니까?', `MaleText_loc4`='嘿，你好。你能把我从这儿弄出去吗？', `MaleText_loc5`='嘿，你。你能帶我離開這裡嗎?', `MaleText_loc7`='Oye, tú. ¿Puedes sacarme de aquí?', `FemaleText_loc1`='거기, 당신. 저 좀 밖으로 꺼내주시겠어요?', `FemaleText_loc4`='嘿，你好。你能把我从这儿弄出去吗？', `FemaleText_loc5`='嘿，你。你能帶我離開這裡嗎?', `FemaleText_loc7`='Oye, tú. ¿Puedes sacarme de aquí?' WHERE `ID`=47937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 도와주시지 않겠습니까?', `MaleText_loc4`='能帮个小忙吗？', `MaleText_loc5`='能幫個忙嗎?', `MaleText_loc7`='¿Puedes echarme una mano?', `FemaleText_loc1`='좀 도와주시지 않을래요?', `FemaleText_loc4`='能帮个小忙吗？', `FemaleText_loc5`='能幫個忙嗎?', `FemaleText_loc7`='¿Puedes echarme una mano?' WHERE `ID`=47938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 창살 밖에 있는 걸 행운으로 생각하십시오!', `MaleText_loc4`='你真该庆幸自己待在这些铁栅栏的另一侧！', `MaleText_loc5`='你運氣很好，你人是在酒吧的另外一邊!', `MaleText_loc7`='¡Tienes suerte de estar al otro lado de las rejas!', `FemaleText_loc1`='이 창살 밖에 있는 걸 행운으로 생각하세요!', `FemaleText_loc4`='你真该庆幸自己待在这些铁栅栏的另一侧！', `FemaleText_loc5`='你運氣很好，你人是在酒吧的另外一邊!', `FemaleText_loc7`='¡Tienes suerte de estar al otro lado de las rejas!' WHERE `ID`=47939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 좀 나가게 해주십시오!', `MaleText_loc4`='放我出去！', `MaleText_loc5`='讓我離開這裡!', `MaleText_loc7`='¡Sácame de aquí!', `FemaleText_loc1`='저 좀 나가게 해줘요!', `FemaleText_loc4`='放我出去！', `FemaleText_loc5`='讓我離開這裡!', `FemaleText_loc7`='¡Sácame de aquí!' WHERE `ID`=47940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 뭘 하실 생각입니까?', `MaleText_loc4`='你想把我怎么样？', `MaleText_loc5`='你要對我做什麼?', `MaleText_loc7`='¿Qué vas a hacer conmigo?', `FemaleText_loc1`='저한테 뭘 하실 생각이세요?', `FemaleText_loc4`='你想把我怎么样？', `FemaleText_loc5`='你要對我做什麼?', `FemaleText_loc7`='¿Qué vas a hacer conmigo?' WHERE `ID`=47941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신. 제 교도관 좀 처치해주십시오!', `MaleText_loc4`='你，说你呢。干掉我的看守！', `MaleText_loc5`='嘿，就是你。過來。來殺掉我的獄卒!', `MaleText_loc7`='Tú, sí, tú. ¡Ven y mata al carcelero!', `FemaleText_loc1`='거기 당신. 제 교도관 좀 처치해주세요!', `FemaleText_loc4`='你，说你呢。干掉我的看守！', `FemaleText_loc5`='嘿，就是你。過來。來殺掉我的獄卒!', `FemaleText_loc7`='Tú, sí, tú. ¡Ven y mata al carcelero!' WHERE `ID`=47942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 조종할 수는 없다!', `MaleText_loc4`='我是不会被控制的！', `MaleText_loc5`='我不會受人擺佈!', `MaleText_loc7`='¡No me manipularás!' WHERE `ID`=47943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토르스의 의지는... 너무 강하군!', `FemaleText_loc4`='他的意志——太强大了！', `FemaleText_loc5`='他的意志—太強了!', `FemaleText_loc7`='Su voluntad... ¡Es demasiado fuerte!' WHERE `ID`=47944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기 중앙 요새에 블러드 엘프가 있네. 벨록이라고 실버문 대표단의 한 명이지. 그가 바로 자네가 찾는 자일세.', `MaleText_loc4`='在力量谷的中部要塞里有位血精灵，是银月城贝洛克代表团的成员。他就是你要找的人。', `MaleText_loc5`='在力量谷的中央要塞裡有一位血精靈，他是銀月城派來的，叫做貝洛克。他就是你要找的人。', `MaleText_loc7`='Hay un elfo de sangre en la fortaleza central del Valle de la Fuerza, Belloc, que forma parte de una delegación de Lunargenta. Él es el hombre que buscas.', `FemaleText_loc1`='힘의 골짜기 중앙 요새에 블러드 엘프가 있네. 벨록이라고 실버문 대표단의 한 명이지. 그가 바로 자네가 찾는 자일세.', `FemaleText_loc4`='在力量谷的中部要塞里有位血精灵，是银月城贝洛克代表团的成员。他就是你要找的人。', `FemaleText_loc5`='在力量谷的中央要塞裡有一位血精靈，他是銀月城派來的，叫做貝洛克。他就是你要找的人。', `FemaleText_loc7`='Hay un elfo de sangre en la fortaleza central del Valle de la Fuerza, Belloc, que forma parte de una delegación de Lunargenta. Él es el hombre que buscas.' WHERE `ID`=47945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사들은 어둠의 틈에서 찾을 수 있을 걸세. 어둠의 틈으로 가는 입구는 두 개가 있네. 하나는 힘의 골짜기와 지혜의 골짜기 사이에 있고, 다른 하나는 골목길에 있다네.', `MaleText_loc4`='可以在暗影裂口里找到那些法师。共有两个入口，一个位于力量谷与智慧谷中间，另一个在暗巷区。', `MaleText_loc5`='法師們應該是在暗影裂口裡。那邊有兩個入口:一個在力量谷和智慧谷的中間，另一個是在暗巷區。', `MaleText_loc7`='Los magos se encuentran en el Circo de las Sombras. Hay dos entradas: una entre los valles de la Fuerza y la Sabiduría, y otra en la Calle Mayor.', `FemaleText_loc1`='마법사들은 어둠의 틈에서 찾을 수 있을 걸세. 어둠의 틈으로 가는 입구는 두 개가 있네. 하나는 힘의 골짜기와 지혜의 골짜기 사이에 있고, 다른 하나는 골목길에 있다네.', `FemaleText_loc4`='可以在暗影裂口里找到那些法师。共有两个入口，一个位于力量谷与智慧谷中间，另一个在暗巷区。', `FemaleText_loc5`='法師們應該是在暗影裂口裡。那邊有兩個入口:一個在力量谷和智慧谷的中間，另一個是在暗巷區。', `FemaleText_loc7`='Los magos se encuentran en el Circo de las Sombras. Hay dos entradas: una entre los valles de la Fuerza y la Sabiduría, y otra en la Calle Mayor.' WHERE `ID`=47946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 굴복하지... 않을 것이다!', `MaleText_loc4`='我……决不……从命！', `MaleText_loc5`='我...不會...屈服!', `MaleText_loc7`='¡Yo... no... serviré!' WHERE `ID`=47947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇다면 죽음을 맞이해라.', `FemaleText_loc4`='那你就去死吧。', `FemaleText_loc5`='那麼你就會死。', `FemaleText_loc7`='Entonces morirás.' WHERE `ID`=47948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='결국 이리되었군. 끝났네.', `FemaleText_loc4`='好吧。结束了。', `FemaleText_loc5`='好吧。結束了。', `FemaleText_loc7`='Que así sea. Está hecho.' WHERE `ID`=47949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예비 갱도에서 만나세, $n. 서쪽으로 강을 건너 날아간 후 산등성이에 있는 작은 동굴을 찾게...', `FemaleText_loc4`='到咽喉洞与我见面，$n。向西飞，飞过那条河，然后沿着山脊寻找一个小山洞……', `FemaleText_loc5`='到水道和我碰面，$n。往西邊飛，越過河流，沿著山脊線的一個小山洞...', `FemaleText_loc7`='Reúnete conmigo en La Garganta, $n. Vuela hacia el oeste, cruza el río y busca una pequeña cueva a lo largo de la línea de cresta...' WHERE `ID`=47950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작전 종료.', `MaleText_loc4`='合作愉快。', `MaleText_loc5`='做的好。', `MaleText_loc7`='Ha estado bien trabajar contigo.' WHERE `ID`=47951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 보자고!', `MaleText_loc4`='后会有期！', `MaleText_loc5`='再見!', `MaleText_loc7`='¡Nos vemos!' WHERE `ID`=47952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 꽤 마음에 듭니다. 저기서 죽지 않게 조심하세요.', `MaleText_loc4`='我有点儿喜欢你。可别送了命。', `MaleText_loc5`='我還蠻喜歡你的，當心別被宰了。', `MaleText_loc7`='Creo que me caes bien. Intenta que no te maten ahí fuera.', `FemaleText_loc1`='당신이 꽤 마음에 들어요. 저기서 죽지 않게 조심하세요.', `FemaleText_loc4`='我有点儿喜欢你。可别送了命。', `FemaleText_loc5`='我還蠻喜歡你的，當心別被宰了。', `FemaleText_loc7`='Creo que me caes bien. Intenta que no te maten ahí fuera.' WHERE `ID`=47953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디투크, 이 망나니 같은 녀석! 잠깐... 네 해독 장치에 무슨 문제지?', `MaleText_loc4`='迪萨克，你这讨厌鬼！等等……你的编码装置出什么问题了？', `MaleText_loc5`='迪梭克，你這個小混帳!慢著...你的解碼裝置怎麼了?', `MaleText_loc7`='¡Deethuk, eres un mocoso! Espera... ¿Qué le pasa a tu dispositivo codificado?', `FemaleText_loc1`='디투크, 이 망나니 같은 녀석! 잠깐... 네 해독 장치에 무슨 문제지?', `FemaleText_loc4`='迪萨克，你这讨厌鬼！等等……你的编码装置出什么问题了？', `FemaleText_loc5`='迪梭克，你這個小混帳!慢著...你的解碼裝置怎麼了?', `FemaleText_loc7`='¡Deethuk, eres un mocoso! Espera... ¿Qué le pasa a tu dispositivo codificado?' WHERE `ID`=47954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응? 뭐라고?', `MaleText_loc4`='嗯？什么？', `MaleText_loc5`='啥?什麼?', `MaleText_loc7`='¿Eh? ¿Qué?' WHERE `ID`=47955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹독골렘 유닛 방어막 시스템 작동 개시.', `MaleText_loc4`='剧毒金刚单位防护系统已就绪。', `MaleText_loc5`='啟動烈毒號護盾系統。', `MaleText_loc7`='Sistemas de escudos de la unidad Toxitron en línea.' WHERE `ID`=47956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 당신이 잘 해내 줘서 기쁘군요.', `MaleText_loc4`='$n！真高兴你做到了。', `MaleText_loc5`='$n!很高興你安然無恙。', `MaleText_loc7`='¡$n! Me alegro de que lo lograras.' WHERE `ID`=47957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 적을 학살할 준비를 합니다!', `MaleText_loc4`='%s准备屠杀他的敌人！', `MaleText_loc5`='%s準備屠殺他的敵人!', `MaleText_loc7`='¡%s se prepara para masacrar a sus enemigos!' WHERE `ID`=47958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 숨을 쉬어라!', `MaleText_loc4`='咽气吧！', `MaleText_loc5`='嚥下最後一口氣吧!', `MaleText_loc7`='¡Inhalen su último respiro!' WHERE `ID`=47959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나마... 테랄리온 녀석도 죽어서 다행이야...', `MaleText_loc4`='至少……瑟纳利昂和我一起倒下……', `MaleText_loc5`='至少...有瑟拉里恩陪葬...', `MaleText_loc7`='Al menos... Theralion muere conmigo...' WHERE `ID`=47960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테랄리온, 내가 전당에 불을 뿜겠다. 놈들의 퇴로를 막아라!', `MaleText_loc4`='瑟纳利昂，我去包抄门厅。堵住他们的退路！', `MaleText_loc5`='瑟拉里恩，我的火會淹沒整個通道。擋住他們的退路!', `MaleText_loc7`='Theralion, derrumbaré la cámara. ¡Cubre su escape!' WHERE `ID`=47961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼을 맞이해라!', `MaleText_loc4`='进入暮光吧！', `MaleText_loc5`='進入暮光!', `MaleText_loc7`='¡Ven, crepúsculo!' WHERE `ID`=47962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, $r.$b$b의식이 실패한 이후로 슈노츠 님의 기분이 썩 좋지 않으니까.', `MaleText_loc4`='小心点儿，$r。$b$b仪式失败以后，司克诺兹的脾气一直非常糟糕。', `MaleText_loc5`='小心點，$r。$b$b在儀式失敗以後，舒諾茲的心情就很惡劣。', `MaleText_loc7`='Cuidado, $r.$b$bSchnottz está de muy mal humor después del incidente del ritual fallido.' WHERE `ID`=47963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사가 자신이 흘린 피의 웅덩이 안에 시체가 되어 누워 있습니다.$b$b대사의 찢어진 옷을 통해 크고 깊은 이빨 자국을 여럿 볼 수 있습니다.$b$b비전문가의 눈으로 봐도 그 상처는 불에 그슬린 듯 보이고, 일부는 검게 탄 곳도 있습니다.', `MaleText_loc4`='大使倒在血泊中。$b$b在他破烂的衣服之下，你发现一排巨大而凹深的齿印。$b$b更令人不解的是，伤口仿佛是烧蚀而成，有些地方还有焦黑的痕迹。', `MaleText_loc5`='大使躺臥在他自己的血泊之中。$b$b在他被撕裂開來的衣服底下，你看到了一排很深的齒痕。$b$b更奇怪的是，這個傷口有被燒過的跡象，有些地方甚至還燒焦了。', `MaleText_loc7`='El embajador yace muerto sobre un charco de su propia sangre.$b$bA través de su ropa rasgada puedes ver una fila de marcas de dientes enormes y profundas.$b$bY lo que es más raro, las heridas parecen cauterizadas, incluso calcinadas en algunos sitios.' WHERE `ID`=47964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 약해졌습니다! 족쇄를 써서 사로잡으십시오!', `MaleText_loc4`='%s陷入了虚弱状态！快用镣铐抓住他们！', `MaleText_loc5`='%s變弱了!用你的鐐銬抓住他們!', `MaleText_loc7`='¡%s se debilita! ¡Captúralo con tus grilletes!', `FemaleText_loc1`='%s|1이;가; 약해졌습니다! 족쇄를 써서 사로잡으십시오!', `FemaleText_loc4`='%s陷入了虚弱状态！快用镣铐抓住他们！', `FemaleText_loc5`='%s變弱了!用你的鐐銬抓住他們!', `FemaleText_loc7`='¡%s se debilita! ¡Captúralo con tus grilletes!' WHERE `ID`=47965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<남자는 당신에게 눈길도 한 번 주지 않습니다. 당신과 대화를 나눌 생각이 전혀 없어 보입니다.>', `MaleText_loc4`='<那人几乎当你不存在。他显然没兴趣和你多说什么。>', `MaleText_loc5`='<這個人連理都不理你，他顯然一點也不想跟你說話。>', `MaleText_loc7`='<El hombre apenas se percata de tu presencia. Es evidente que no le interesa hablar contigo.>' WHERE `ID`=47966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관문돌을 사용해라. 당장 이걸 열도록.', `MaleText_loc4`='打破门石。把它打开。', `MaleText_loc5`='去用門石把這東西打開。', `MaleText_loc7`='Saca la piedra de puerta. Abre esta cosa.' WHERE `ID`=47967;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즉시 실행하겠습니다. 에... 돌을 끼울 데가 안 보이는데요?', `FemaleText_loc4`='马上，长官。呃……我找不到插孔？', `FemaleText_loc5`='馬上辦，長官。呃...好像沒有地方可以放進去?', `FemaleText_loc7`='Ahora mismo, señor. Eh... No veo ninguna ranura donde ponerla...' WHERE `ID`=47968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 세상에 쉬운 일이 없단 말이지. 상관없다. 다른 준비도 해 왔으니.', `MaleText_loc4`='这当然不容易做到，对吧？没关系，我们有备而来。', `MaleText_loc5`='事情總是不容易，對吧?還好，我們準備周全。', `MaleText_loc7`='Nunca lo ponen fácil, ¿verdad? No pasa nada, hemos venido preparados.' WHERE `ID`=47969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭파해 버려. 폭탄만 적당히 있으면 안 되는 게 없지.', `MaleText_loc4`='把它炸开。这点问题用炸药就能解决。', `MaleText_loc5`='把它炸開。沒有什麼問題是炸藥解決不了的。', `MaleText_loc7`='Hacedla estallar. No hay ningún problema que no se pueda solucionar con explosivos.' WHERE `ID`=47970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예!', `MaleText_loc4`='就绪。', `MaleText_loc5`='馬上處理。', `MaleText_loc7`='Ahora mismo.' WHERE `ID`=47971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄 설치 완료했습니다. 이제 떨어지시는 게 좋겠습니다!', `MaleText_loc4`='炸药已就位。闲杂人等不要靠近！', `MaleText_loc5`='炸藥裝好了。趕快離開!', `MaleText_loc7`='Las cargas están listas. ¡Quizá quieras alejarte un poco!' WHERE `ID`=47972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 보고 싶던 광경이지. 관문돌은 무슨 얼어 죽을 관문돌...', `MaleText_loc4`='这才像样。谁会需要这碍手碍脚的门石啊……', `MaleText_loc5`='這才是我想看到的。誰需要什麼門石的啊...', `MaleText_loc7`='Eso es lo que me gusta ver. De todas maneras, quién necesita una piedra de puerta...' WHERE `ID`=47973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공수부대?!', `MaleText_loc4`='伞兵？！', `MaleText_loc5`='傘兵?!', `MaleText_loc7`='¡¿Paracaidistas?!' WHERE `ID`=47974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관! 뒤에 놈리건 공수부대가 나타났다!', `MaleText_loc4`='长官，你身后！诺莫瑞根伞兵！', `MaleText_loc5`='指揮官，你後面! 諾姆瑞根傘兵!', `MaleText_loc7`='¡Comandante, detrás de ti! ¡Paracaidistas de Gnomeregan!', `FemaleText_loc1`='사령관! 뒤에 놈리건 공수부대가 나타났다!', `FemaleText_loc4`='长官，你身后！诺莫瑞根伞兵！', `FemaleText_loc5`='指揮官，你後面! 諾姆瑞根傘兵!', `FemaleText_loc7`='¡Comandante, detrás de ti! ¡Paracaidistas de Gnomeregan!' WHERE `ID`=47975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗! 뒤에! 거울이다!', `MaleText_loc4`='快看！你身后！镜子！', `MaleText_loc5`='看!你後面!一面鏡子!', `MaleText_loc7`='¡Mira, detrás de ti! ¡Un espejo!', `FemaleText_loc1`='앗! 뒤에! 거울이다!', `FemaleText_loc4`='快看！你身后！镜子！', `FemaleText_loc5`='看!你後面!一面鏡子!', `FemaleText_loc7`='¡Mira, detrás de ti! ¡Un espejo!' WHERE `ID`=47976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거울이라고? 어쩜 좋아라!', `MaleText_loc4`='镜子？太棒了！', `MaleText_loc5`='鏡子?真神奇!', `MaleText_loc7`='¿Un espejo? ¡Maravilloso!' WHERE `ID`=47977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비켜라, $r.$b$b너 따위는 내가 알 바가 아니다.', `MaleText_loc4`='继续前进，$r。$b$b你的存在对我毫无意义。', `MaleText_loc5`='走吧，$r。$b$b你對我一點也不重要。', `MaleText_loc7`='Sigue andando, $r.$b$bTu presencia no me interesa.' WHERE `ID`=47978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 쳐다보지도 않고 코웃음 치는 사절>$b$b가서 자네 할 일이나 하게, $r.', `MaleText_loc4`='<密使冷笑着，看都不看你一眼。>$b$b忙你自己的事去吧，$r。', `MaleText_loc5`='<大使連看都不看你，只是冷笑一聲。>$b$b去做你自己的事情，$r。', `MaleText_loc7`='<El emisario hace una mueca sin mirarte.>$b$bOcúpate de tus asuntos, $r.' WHERE `ID`=47979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사업이 엉망입니다!$b$b끔찍하게 으르렁거리는 소리가 이 지역 전체에 울려 퍼지고 있어요.$b$b불쌍한 사람...$b$b실례하겠습니다. 정말 한잔 마셔야겠네요.', `MaleText_loc4`='太可怕了！$b$b整个地区都在回响着令人毛骨悚然的咆哮声。$b$b可怜的家伙……$b$b请原谅——我想我得来一杯。', `MaleText_loc5`='糟糕透了!$b$b有一道可怕的咆哮聲，好像整個地方都聽得到。$b$b可憐的傢伙...$b$b抱歉我得走了—我想我得去喝一杯。', `MaleText_loc7`='¡Un asunto terrible!$b$bHubo un rugido horroroso que pareció reverberar por toda la región.$b$bPobre hombre...$b$bPerdóname, creo que necesito un trago.' WHERE `ID`=47980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 봤는지 확실하지가 않습니다.$b$b무슨 일이 일어나는 건지 깨닫기도 전에 끝나버렸으니까요.', `MaleText_loc4`='我不确定自己究竟看见了什么。$b$b在我意识到发生什么之前，就已经结束了。', `MaleText_loc5`='我不確定我到底看到了什麼。$b$b因為我連狀況都還沒搞清楚，事情就已經結束了。', `MaleText_loc7`='No estoy seguro de lo que vi.$b$bSe acabó antes de que me diera cuenta de lo que estaba pasando.' WHERE `ID`=47981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 안타까운 일입니다!$b$b어서 여길 정리하는 게 어떨까요?$b$b자꾸 쓸데없이 안 좋은 일을 생각나게 하니까요...', `MaleText_loc4`='真是太不幸了！$b$b让我们把这清理干净，好吗？$b$b如果不是万分必要，这种事情绝不能再发生……', `MaleText_loc5`='太不幸了!$b$b但是這件事就到此為止，好嗎?$b$b不該再把事情給鬧大了...', `MaleText_loc7`='¡Qué desafortunado!$b$bLimpiemos esto, ¿bien?$b$bNo me gustaría tener que hacer más de esto de lo que es necesario...' WHERE `ID`=47982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사람에게 무슨 일이 일어났는지 알고 싶지 않으십니까?', `MaleText_loc4`='你不想知道那人怎么了吗？', `MaleText_loc5`='你不想知道那傢伙發生了什麼嗎?', `MaleText_loc7`='¿No quieres saber lo que le pasó al tipo?', `FemaleText_loc1`='저 사람에게 무슨 일이 일어났는지 알고 싶지 않으세요?', `FemaleText_loc4`='你不想知道那人怎么了吗？', `FemaleText_loc5`='你不想知道那傢伙發生了什麼嗎?', `FemaleText_loc7`='¿No quieres saber lo que le pasó al tipo?' WHERE `ID`=47983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 궁금하긴 합니다. 하지만 이미 엎질러진 물이잖아요.$b$b괜히 사람들을 동요시키고 싶지 않습니다. 그건 신중하지 못한 일이라고요!', `MaleText_loc4`='我当然很好奇，但过去的就让它过去吧。$b$b我们可不该再引起什么不必要的恐慌。那可一点儿都不明智！', `MaleText_loc5`='我當然會好奇，可是事情都已經發生了。$b$b我們要小心一點，不要再造成無謂的恐慌!', `MaleText_loc7`='Tengo curiosidad, desde luego, pero lo hecho hecho está.$b$bNo queremos despertar un pánico innecesario. ¡No sería prudente en absoluto!' WHERE `ID`=47984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 걱정하는 건 이번 작업에서 벌어들일 당신 몫뿐입니까?', `MaleText_loc4`='看来你在乎的只是自身的利害关系？', `MaleText_loc5`='在這項計畫中你只關心自己所投資的錢而已?', `MaleText_loc7`='¿Lo único que te interesa es tu parte de la operación?', `FemaleText_loc1`='당신이 걱정하는 건 이번 작업에서 벌어들일 당신 몫뿐인가요?', `FemaleText_loc4`='看来你在乎的只是自身的利害关系？', `FemaleText_loc5`='在這項計畫中你只關心自己所投資的錢而已?', `FemaleText_loc7`='¿Lo único que te interesa es tu parte de la operación?' WHERE `ID`=47985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴리가요!$b$b내 말은, 물론 내 전재산이 여기 달렸긴 하지요... 그리고 솔직히 사람들이 동요한다고 해서 무슨 도움이 되겠습니까?', `MaleText_loc4`='当然不是！$b$b我的意思是说，我确实把全部家当都押在了这儿……可老实说，一场公共危机对大家都没好处吧？', `MaleText_loc5`='當然不是!$b$b我是說，我在這兒的投資確實是受到了波及...而且坦白講，引起公開的危機到底是會對誰有好處?', `MaleText_loc7`='¡Claro que no!$b$bQuiero decir, sí que arriesgo toda mi fortuna... Pero sinceramente, ¿cómo se beneficiaría nadie de que hubiera una crisis pública?' WHERE `ID`=47986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 일이 벌어지고 있는 겁니까!?$b$b저 사람 상처는 보셨나요?!$b$b대체 어떤 괴물이 그런 짓을 했을까요?
', `MaleText_loc4`='发生了什么事？！$b$b你看见那人身上的伤口吗？！$b$b会是什么样的怪物干的？', `MaleText_loc5`='這是怎麼回事!?$b$b你有看到這個人的傷口嗎?!$b$b到底是什麼怪物咬的?', `MaleText_loc7`='¡¿Qué está pasando ahí fuera?!$b$b¡¿Has visto las heridas de ese hombre?!$b$b¿Qué tipo de monstruo hace algo así?' WHERE `ID`=47987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 심호흡을 하십시오. 뭐라도 본 건 없습니까?', `MaleText_loc4`='深呼吸。你看见什么了吗？', `MaleText_loc5`='只要深呼吸一口氣。你有看到什麼嗎?', `MaleText_loc7`='Toma aire. ¿Has visto algo?', `FemaleText_loc1`='잠깐 심호흡을 하세요. 뭐라도 본 건 없나요?', `FemaleText_loc4`='深呼吸。你看见什么了吗？', `FemaleText_loc5`='只要深呼吸一口氣。你有看到什麼嗎?', `FemaleText_loc7`='Toma aire. ¿Has visto algo?' WHERE `ID`=47988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없어요. 하지만 아무것도 보지 않아도 우리 모두 죽게 될 거라는 사실은 알겠어요!$b$b무슨 말인지 아시겠어요?!
', `MaleText_loc4`='不，我什么都不用看也知道，我们全都要死了！$b$b你听懂没有？！', `MaleText_loc5`='沒有，但是我不用看就知道我們全都要死了!$b$b有聽到我講的話嗎?!', `MaleText_loc7`='No, ¡pero no me hace falta para saber que todos vamos a MORIR!$b$b¡¿Me oyes?!' WHERE `ID`=47989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오... 그렇게 당황하면 상황이 악화될 뿐입니다.', `MaleText_loc4`='放松……恐慌只会让一切变得更糟。', `MaleText_loc5`='放輕鬆點...恐慌只會讓事情變得更糟。', `MaleText_loc7`='Relájate... Perder los nervios solo empeora las cosas.', `FemaleText_loc1`='진정하세요... 그렇게 당황하면 상황이 악화될 뿐이에요.', `FemaleText_loc4`='放松……恐慌只会让一切变得更糟。', `FemaleText_loc5`='放輕鬆點...恐慌只會讓事情變得更糟。', `FemaleText_loc7`='Relájate... Perder los nervios solo empeora las cosas.' WHERE `ID`=47990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말은 쉽게 하시네요.$b$b하지만 전 이런 일이 체질에 맞지 않아요! 당장 여기서 나가야 해요!
', `MaleText_loc4`='你说的倒容易。$b$b我承受不了这么多！我得赶紧想办法离开！', `MaleText_loc5`='你說的可輕鬆。$b$b我不是幹這種事情的料!我要想辦法離開這裡!', `MaleText_loc7`='Para ti es fácil decirlo.$b$b¡Yo no estoy preparado para esto! ¡Tengo que encontrar una forma de salir de aquí!' WHERE `ID`=47991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<넋이 나간 듯 멍하니 당신을 바라보는 여배우>', `FemaleText_loc4`='<这名演员面无表情地看着你。>', `FemaleText_loc5`='<小明星茫然地看著你。>', `FemaleText_loc7`='<La estrella te mira inexpresiva.>' WHERE `ID`=47992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 달라란에서 온 마법 재연마사인 대마법사 프랫은 이곳의 마법부여사인 라비니아 크로와 함께 일한다네. 그 둘은 연금술 실험실에 있네.', `MaleText_loc4`='奥术重铸师，大法师普拉特最近刚刚从达拉然来到这里，他通常和本地的附魔师拉文尼亚·克洛文一起工作。在炼金房里可以找到他们。', `MaleText_loc5`='大法師普拉特是最近剛從達拉然過來的一位秘法重鑄師，他通常都在鍊金房裡跟本地的附魔師拉玟妮雅·克洛威在一起工作。', `MaleText_loc7`='El archimago Pratt, un reforjador Arcano llegado recientemente de Dalaran, suele trabajar con Lavinia Crowe, la encantadora local. Los dos están en el Apothecarium.', `FemaleText_loc1`='최근에 달라란에서 온 마법 재연마사인 대마법사 프랫은 이곳의 마법부여사인 라비니아 크로와 함께 일한다네. 그 둘은 연금술 실험실에 있네', `FemaleText_loc4`='奥术重铸师，大法师普拉特最近刚刚从达拉然来到这里，他通常和本地的附魔师拉文尼亚·克洛文一起工作。在炼金房里可以找到他们。', `FemaleText_loc5`='大法師普拉特是最近剛從達拉然過來的一位秘法重鑄師，他通常都在鍊金房裡跟本地的附魔師拉玟妮雅·克洛威在一起工作。', `FemaleText_loc7`='El archimago Pratt, un reforjador Arcano llegado recientemente de Dalaran, suele trabajar con Lavinia Crowe, la encantadora local. Los dos están en el Apothecarium.' WHERE `ID`=47993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 마디로 가르쳐 주지, $r.$b$b그냥 여기서 우리 일을 방해하지 말라고.', `MaleText_loc4`='我的建议很简单，$r。$b$b别在这儿碍事。', `MaleText_loc5`='我給你的建議很簡單，$r。$b$b就是不要在這邊礙事。', `MaleText_loc7`='Mi consejo es muy sencillo, $r.$b$bNo nos incordies.' WHERE `ID`=47994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 돌아온 명가의 일원을 찾으시는군요.$B$B그들의 마법 재연마사 중 한 명이 마법부여사인 탈라단과 시간을 보내고 있답니다. 장인의 정원에서 그들을 찾아보시기 바랍니다.', `MaleText_loc4`='啊，你是在找那个归返的上层精灵。$B$B有位奥术重铸师正和附魔师塔兰丹一起工作。可以在工匠区找到他们。', `MaleText_loc5`='啊，你要找的是歸來的精靈貴族。$B$B他們有一位秘法重鑄師正在和附魔師塔蘭丹做研究，你可以在工匠區找到他們。', `MaleText_loc7`='Ah, buscas a los Altonato que han regresado.$b$bUna de sus reforjadoras Arcanas ha estado visitando a Taladan, el encantador. Búscalos en el Bancal del Artesano.', `FemaleText_loc1`='아, 돌아온 명가의 일원을 찾으시는군요.$B$B그들의 마법 재연마사 중 한 명이 마법부여사인 탈라단과 시간을 보내고 있답니다. 장인의 정원에서 그들을 찾아보시기 바랍니다.', `FemaleText_loc4`='啊，你是在找那个归返的上层精灵。$B$B有位奥术重铸师正和附魔师塔兰丹一起工作。可以在工匠区找到他们。', `FemaleText_loc5`='啊，你要找的是歸來的精靈貴族。$B$B他們有一位秘法重鑄師正在和附魔師塔蘭丹做研究，你可以在工匠區找到他們。', `FemaleText_loc7`='Ah, buscas a los Altonato que han regresado.$b$bUna de sus reforjadoras Arcanas ha estado visitando a Taladan, el encantador. Búscalos en el Bancal del Artesano.' WHERE `ID`=47995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 도울 수 있는 싫증난 해몬이라는 학자가 있답니다. 달의 신전에서 그를 찾을 수 있을 겁니다. 그는 돌아온 명가의 일원들과 자주 담화를 나눈답니다.', `MaleText_loc4`='有位名叫隐世者汉蒙的学者可以帮上你的忙。你可以在月神殿理找到他，他通常在那里和归返的上层精灵交谈。', `MaleText_loc5`='有一位學者叫做『疲倦不堪』的漢孟德可以幫你的忙。你可以在月神殿裡找到他，他經常在那邊和歸來的精靈貴族講話。', `MaleText_loc7`='Hay un erudito, Hammon el Hastiado, que puede ayudarte. Lo encontrarás en el Templo de la Luna, suele estar charlando con uno de los Altonato que han regresado.', `FemaleText_loc1`='그대를 도울 수 있는 싫증난 해몬이라는 학자가 있답니다. 달의 신전에서 그를 찾을 수 있을 겁니다. 그는 돌아온 명가의 일원들과 자주 담화를 나눈답니다.', `FemaleText_loc4`='有位名叫隐世者汉蒙的学者可以帮上你的忙。你可以在月神殿理找到他，他通常在那里和归返的上层精灵交谈。', `FemaleText_loc5`='有一位學者叫做『疲倦不堪』的漢孟德可以幫你的忙。你可以在月神殿裡找到他，他經常在那邊和歸來的精靈貴族講話。', `FemaleText_loc7`='Hay un erudito, Hammon el Hastiado, que puede ayudarte. Lo encontrarás en el Templo de la Luna, suele estar charlando con uno de los Altonato que han regresado.' WHERE `ID`=47996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 서로 아는 사이던가? 아니라고? 황혼의 망치단에 온 걸 환영한다.', `MaleText_loc4`='我们认识吗？不？欢迎来到暮光之锤。', `MaleText_loc5`='我認識你嗎?不認識?歡迎加入暮光之錘。', `MaleText_loc7`='¿Te conozco? ¿No? $gBienvenido:Bienvenida; al Martillo Crepuscular.', `FemaleText_loc1`='우리 서로 아는 사이던가? 아니라고? 황혼의 망치단에 온 걸 환영한다.', `FemaleText_loc4`='我们认识吗？不？欢迎来到暮光之锤。', `FemaleText_loc5`='我認識你嗎?不認識?歡迎加入暮光之錘。', `FemaleText_loc7`='¿Te conozco? ¿No? $gBienvenido:Bienvenida; al Martillo Crepuscular.' WHERE `ID`=47997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 시간이 임박했다!', `MaleText_loc4`='末日即将来临！', `MaleText_loc5`='末日即將來臨!', `MaleText_loc7`='¡Se acercan los últimos días!', `FemaleText_loc1`='파멸의 시간이 임박했다!', `FemaleText_loc4`='末日即将来临！', `FemaleText_loc5`='末日即將來臨!', `FemaleText_loc7`='¡Se acercan los últimos días!' WHERE `ID`=47998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑옷에 피가 묻어 있군, 괜찮나?', `MaleText_loc4`='你的护甲上沾了点儿血。你还好吧？', `MaleText_loc5`='你的護甲上沾了點血跡。你還好嗎?', `MaleText_loc7`='Hay un poco de sangre en tu armadura. ¿Estás bien?', `FemaleText_loc1`='갑옷에 피가 묻어 있군, 괜찮나?', `FemaleText_loc4`='你的护甲上沾了点儿血。你还好吧？', `FemaleText_loc5`='你的護甲上沾了點血跡。你還好嗎?', `FemaleText_loc7`='Hay un poco de sangre en tu armadura. ¿Estás bien?' WHERE `ID`=47999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병인가? 사령관님께 보고는 했나?', `MaleText_loc4`='新兵？你向指挥官报到了吗？', `MaleText_loc5`='新來的?你去跟指揮官報到過了嗎?', `MaleText_loc7`='¿$gUn nuevo:Una nueva; recluta? ¿Ya te has presentado ante el Comandante?', `FemaleText_loc1`='신병인가? 사령관님께 보고는 했나?', `FemaleText_loc4`='新兵？你向指挥官报到了吗？', `FemaleText_loc5`='新來的?你去跟指揮官報到過了嗎?', `FemaleText_loc7`='¿$gUn nuevo:Una nueva; recluta? ¿Ya te has presentado ante el Comandante?' WHERE `ID`=48000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 그롬-그롬 본 적 없나? 한 이 정도 키의 오크 말이야. 없다고?$B$B흠. 최근 아무도 못 봤다고 하던데. 아마 탈영했겠지.', `MaleText_loc4`='嘿，你没见过格罗姆-格罗姆那家伙吧？是个兽人，大约这么高。没有吗？$B$B嗯。大家都有阵子没见过他了。看来又擅离职守了。', `MaleText_loc5`='嘿，你有沒有看到格羅—格羅?獸人，大概這麼高。沒看到?$B$B嗯。大家好像都一陣子沒看到他了。八成是私自跑走了。', `MaleText_loc7`='Hey, no habrás visto a Grom-Grom, ¿verdad? Un orco, así de alto. ¿No?$B$BHmmm. Hace tiempo que no le ha visto nadie. Probablemente haya desertado.', `FemaleText_loc1`='이봐, 그롬-그롬 본 적 없나? 한 이 정도 키의 오크 말이야. 없다고?$B$B흠. 최근 아무도 못 봤다고 하던데. 아마 탈영했겠지.', `FemaleText_loc4`='嘿，你没见过格罗姆-格罗姆那家伙吧？是个兽人，大约这么高。没有吗？$B$B嗯。大家都有阵子没见过他了。看样子又擅离职守了。', `FemaleText_loc5`='嘿，你有沒有看到格羅—格羅?獸人，大概這麼高。沒看到?$B$B嗯。大家好像都一陣子沒看到他了。八成是私自跑走了。', `FemaleText_loc7`='Hey, no habrás visto a Grom-Grom, ¿verdad? Un orco, así de alto. ¿No?$B$BHmmm. Hace tiempo que no le ha visto nadie. Probablemente haya desertado.' WHERE `ID`=48001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마른땅 동쪽에 뭔가 큰 게 만들어지고 있어.$B$B그게 뭔지는 모르겠지만, 빨리 끝나서 더 나은 곳으로 재배치됐으면 좋겠군.', `MaleText_loc4`='在东边的凋零法阵中正酝酿着什么大事。$B$B不论是什么，都希望能早点儿结束，我们可以到环境更好的地方去。', `MaleText_loc5`='東邊的枯萎之地好像發生了什麼大事。$B$B但不管是什麼事情，我都希望它能夠早點結束，然後我們可以重新派駐到其他更好的地方。', `MaleText_loc7`='Algo gordo se está cociendo en la Gangrena, hacia el este.$B$BSea lo que sea, espero que termine pronto y que nos destinen a un lugar mucho más agradable.', `FemaleText_loc1`='마른땅 동쪽에 뭔가 큰 게 만들어지고 있어.$B$B그게 뭔지는 모르겠지만, 빨리 끝나서 더 나은 곳으로 재배치됐으면 좋겠군.', `FemaleText_loc4`='在东边的凋零法阵中正酝酿着什么大事。$B$B不论是什么，都希望能早点儿结束，我们可以到环境更好的地方去。', `FemaleText_loc5`='東邊的枯萎之地好像發生了什麼大事。$B$B但不管是什麼事情，我都希望它能夠早點結束，然後我們可以重新派駐到其他更好的地方。', `FemaleText_loc7`='Algo gordo se está cociendo en la Gangrena, hacia el este.$B$BSea lo que sea, espero que termine pronto y que nos destinen a un lugar mucho más agradable.' WHERE `ID`=48002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 부릅뜨고 있어. 아까 사람들을 공격하고 다니던 괴한이 아직 돌아다니고 있다는 말이 있으니까.', `MaleText_loc4`='保持警惕。他们说早先那个到处袭击平民的怪人可能还在附近。', `MaleText_loc5`='張大你的眼睛。據說先前攻擊人的怪物有可能還在這附近。', `MaleText_loc7`='Abre bien los ojos. Dicen que ese monstruo que hace poco ha estado atacando a gente podría seguir por aquí.', `FemaleText_loc1`='눈 부릅뜨고 있어. 아까 사람들을 공격하고 다니던 괴한이 아직 돌아다니고 있다는 말이 있으니까.', `FemaleText_loc4`='保持警惕。他们说早先那个到处袭击平民的怪人可能还在附近。', `FemaleText_loc5`='張大你的眼睛。據說先前攻擊人的怪物有可能還在這附近。', `FemaleText_loc7`='Abre bien los ojos. Dicen que ese monstruo que hace poco ha estado atacando a gente podría seguir por aquí.' WHERE `ID`=48003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마가타 그림토템을 여기 포로로 붙잡아두고 있다니, 뭔가 이상하지 않아? 마가타의 토템이 모두 파괴됐다는 건 다행이지만.$B$B케른 블러드후프를 중독 시킨 게 그녀라는 말까지 들었어... 마가타가 우리 편이었으면 좋겠군.', `MaleText_loc4`='我们居然把玛加萨·恐怖图腾囚禁在此，这不奇怪吗？好在她所有的图腾都被摧毁了。$B$B我甚至听说她毒害了凯恩·血蹄。希望她是站在我们这边的。', `MaleText_loc5`='我們把瑪加薩·恐怖圖騰俘虜在這裡不是很奇怪嗎?還好她的所有圖騰都已經被摧毀了。$B$B我甚至還聽說她對凱恩·血蹄下毒。希望她跟我們是在同一邊的。', `MaleText_loc7`='¿No es extraño que tengamos a Magatha Tótem Siniestro retenida aquí? Menos mal que destruyeron todos sus tótems.$b$bHe oído que incluso envenenó a Cairne Pezuña de Sangre. Ojalá estuviera en nuestro bando.', `FemaleText_loc1`='마가타 그림토템을 여기 포로로 붙잡아두고 있다니, 뭔가 이상하지 않아? 마가타의 토템이 모두 파괴됐다는 건 다행이지만.$B$B케른 블러드후프를 중독 시킨 게 그녀라는 말까지 들었어... 마가타가 우리 편이었으면 좋겠군.', `FemaleText_loc4`='我们居然把玛加萨·恐怖图腾囚禁在此，这不奇怪吗？好在她所有的图腾都被摧毁了。$B$B我甚至听说她毒害了凯恩·血蹄。希望她是站在我们这边的。', `FemaleText_loc5`='我們把瑪加薩·恐怖圖騰俘虜在這裡不是很奇怪嗎?還好她的所有圖騰都已經被摧毀了。$B$B我甚至還聽說她對凱恩·血蹄下毒。希望她跟我們是在同一邊的。', `FemaleText_loc7`='¿No es extraño que tengamos a Magatha Tótem Siniestro retenida aquí? Menos mal que destruyeron todos sus tótems.$b$bHe oído que incluso envenenó a Cairne Pezuña de Sangre. Ojalá estuviera en nuestro bando.' WHERE `ID`=48004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리 중간층에 있는 돈스트라이더의 마법부여점에서 블러드 엘프 마법 재연마사인 헤림을 만나 보십시오. 그녀가 그대를 도울 수 있을 겁니다.', `MaleText_loc4`='在位于中部高地的附魔店里有位名叫赫琳的血精灵奥术重铸师。她能帮上你的忙。', `MaleText_loc5`='你可以在中部高地的晨行者附魔商店 找到一位血精靈秘法重鑄師，叫做赫莉姆。她應該有辦法幫你。', `MaleText_loc7`='Encontrarás una reforjadora Arcana, la elfa de sangre Herim, en Encantadores Caminalba, en el alto central. Ella podrá ayudarte.', `FemaleText_loc1`='봉우리 중간층에 있는 돈스트라이더의 마법부여점에서 블러드 엘프 마법 재연마사인 헤림을 만나 보십시오. 그녀가 그대를 도울 수 있을 겁니다.', `FemaleText_loc4`='在位于中部高地的附魔店里有位名叫赫琳的血精灵奥术重铸师。她能帮上你的忙。', `FemaleText_loc5`='你可以在中部高地的晨行者附魔商店 找到一位血精靈秘法重鑄師，叫做赫莉姆。她應該有辦法幫你。', `FemaleText_loc7`='Encontrarás una reforjadora Arcana, la elfa de sangre Herim, en Encantadores Caminalba, en el alto central. Ella podrá ayudarte.' WHERE `ID`=48005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 공포가 느껴지는군...', `MaleText_loc4`='我能嗅到你的恐惧……', `MaleText_loc5`='我聞得到你的恐懼。', `MaleText_loc7`='Huelo su miedo...' WHERE `ID`=48006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 심장을 꺼내 주마!', `MaleText_loc4`='我要把你的心挖出来！', `MaleText_loc5`='我會把你的心臟挖出來!', `MaleText_loc7`='¡Les arrancaré el corazón del pecho!' WHERE `ID`=48007;
