UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피 맛을 보니 더 배고파지는군.', `MaleText_loc4`='你的鲜血只会刺激我的欲望！', `MaleText_loc5`='你的血只會使我更加飢餓!', `MaleText_loc7`='¡Su sangre sólo incrementa mi hambre!' WHERE `ID`=48009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분을... 찾아봤자... 이미 때는 늦었어...', `MaleText_loc4`='等你……找到她……一切都太迟了……', `MaleText_loc5`='等你找到她...已經太晚了...', `MaleText_loc7`='No... NO la encontrarán... a tiempo…' WHERE `ID`=48010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전선을 관리하라고 크로그 장군님께서 날 여기로 보냈소. 하지만 병사는 아직 하나도 보내 주지 않았다오.$B$B여길 좀 둘러보시오! 오우거도 있고, 황혼의 망치단도 있지. 하지만 내겐... 아무것도 없소.', `MaleText_loc4`='督军克罗格派我到这里来固守战线。但他至今都没有派任何士兵给我。$B$B看看这个地方！对面有食人魔，有暮光之锤。我们这边却……啥也没有。', `MaleText_loc5`='督軍克羅格派我來前線這裡督戰，可是卻還沒有派給我任何士兵。$B$B看看這個地方!有巨魔，有暮光之錘，然後我...什麼都沒有。', `MaleText_loc7`='El señor de la guerra Krogg me ha enviado para controlar el frente, pero aún no me ha enviado ningún soldado.$b$b¡Mira este sitio! Tengo ogros. Tengo Martillo Crepuscular. Y no tengo... nada.' WHERE `ID`=48011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 여기야!', `MaleText_loc4`='$n！到这里来！', `MaleText_loc5`='$n!這裡!', `MaleText_loc7`='¡$n! ¡Aquí!' WHERE `ID`=48012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이리 와! 어서 오라고!', `MaleText_loc4`='这边，$n！过来！过来！', `MaleText_loc5`='這邊，$n!來!來!', `MaleText_loc7`='¡Por aquí, $n! ¡Vamos! ¡Vamos!' WHERE `ID`=48013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러, $n! 시간이 얼마 없어!', `MaleText_loc4`='赶快，$n！没多少时间了！', `MaleText_loc5`='快點，$n!時間不多了!', `MaleText_loc7`='¡Rápido, $n! ¡Queda poco tiempo!' WHERE `ID`=48014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어서 오라고! 공성 전차에 올라타! 당장!', `MaleText_loc4`='过来，$n！到攻城坦克里来！马上！', `MaleText_loc5`='快點，$n!坐上攻城坦克!快!', `MaleText_loc7`='¡Vamos, $n! ¡Métete en el tanque de asedio! ¡AHORA!' WHERE `ID`=48015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만 년이 지나 마침내 자유로워졌다. 하지만 우리 친형조차 날 문제아로 생각하지! 형에게 내 진정한 힘을 보여주겠다! 악마들이 날 막을 순 없다는 걸 보여주겠다!', `MaleText_loc4`='过了一万年，我终于自由了。但我的亲哥哥仍然认为我是个恶棍！我要让他看看我真正的力量！我要让他知道，恶魔不能控制我！', `MaleText_loc5`='被囚禁了一萬年才重獲自由，而我兄長竟仍視我為惡徒!我要讓他知道我真正的力量，我要讓他知道惡魔並無法操控我!', `MaleText_loc7`='Soy libre, diez mil años después, ¡pero mi propio hermano me cree un villano! ¡Le demostraré mi verdadero poder! ¡Le demostraré que los demonios no tienen ningún control sobre mí!' WHERE `ID`=48016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그것 때문인가, 악마사냥꾼이여? 그 의지가 자신에게서 나왔다고 확신하는가?', `MaleText_loc4`='你确定，恶魔猎手？你确定自己拥有独立的意志？', `MaleText_loc5`='你確定嗎，惡魔獵人?你確定你擁有自主的意志嗎?', `MaleText_loc7`='¿Estás seguro, cazademonios? ¿Seguro que tu voluntad te pertenece?' WHERE `ID`=48017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 악취가 풍기는군, 인간이여. 내게 접근한 걸 후회하게 될 거다.', `MaleText_loc4`='你这是自寻死路，人类。你会后悔遇到我。', `MaleText_loc5`='人類，你身上有死亡的惡臭。你會後悔靠近我的。', `MaleText_loc7`='Apestas a muerte, humano. Lamentarás haberte acercado a mí.' WHERE `ID`=48018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 덤벼라. 우리 실력이 대등하단 걸 보여주지.', `MaleText_loc4`='好吧。你会发现，我们势均力敌。', `MaleText_loc5`='來吧，你會發現，我跟你可是不相上下。', `MaleText_loc7`='Ven, entonces. Verás que estamos igualados.' WHERE `ID`=48019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러다가는 평생 싸우겠군. 네가 진정 원하는 게 뭐냐?', `MaleText_loc4`='我们会永远这样战斗下去。而你真正想要的又是什么？', `MaleText_loc5`='我們可以就這樣繼續一直打下去。但是你究竟想要什麼?', `MaleText_loc7`='Podríamos seguir luchando eternamente. ¿Qué es lo que quieres de verdad?' WHERE `ID`=48020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 언데드 군대를 조종하는 공포의 군주는 티콘드리우스라고 한다. 놈은 굴단의 해골이라는 강력한 흑마법사의 유물을 지니고 있지.', `MaleText_loc4`='统率这支亡灵大军的恐惧魔王名叫提克迪奥斯。他拥有一件强大的战争宝物，被称为古尔丹之颅。', `MaleText_loc5`='指揮這支亡靈軍隊的驚懼領主名叫提克迪奧斯，他擁有一件強大的術士法器，叫做古爾丹之顱。', `MaleText_loc7`='El Señor del Terror que lidera este ejército de no-muertos se llama Tichondrius. Controla un poderoso artefacto brujo llamado Calavera de Gul''dan.' WHERE `ID`=48021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유물이 이 숲을 오염시킨 원흉이다.', `MaleText_loc4`='正是它腐蚀了这片森林。', `MaleText_loc5`='而腐化了這片森林的正是這樣東西。', `MaleText_loc7`='Es el responsable de la corrupción de estos bosques.' WHERE `ID`=48022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 왜 그걸 훔치려 하는가?', `MaleText_loc4`='你想让我偷取它。为什么？', `MaleText_loc5`='你要我去偷走它。為什麼?', `MaleText_loc7`='Y quieres que lo robe. ¿Por qué?' WHERE `ID`=48023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오토 그레이하이드는 장로의 봉우리에 위치한 장로의 전당에 있습니다. 그곳에서 그를 찾으십시오. 당신을 도와줄 것입니다.', `MaleText_loc4`='欧托·灰皮通常都在长者高地的长者大厅。你可以在那里找到他。他会帮助你的。', `MaleText_loc5`='歐托·灰皮大多都在長者高地的長者大廳裡。去那邊找他，他會幫你。', `MaleText_loc7`='Otoh Pellejogris pasa mucho tiempo en la Sala de los Ancestros, en el Alto de los Ancestros. Encuéntralo y te ayudará.', `FemaleText_loc1`='오토 그레이하이드는 장로의 봉우리에 위치한 장로의 전당에 있어요. 그곳에서 그를 찾으세요. 당신을 도와줄 거예요.', `FemaleText_loc4`='欧托·灰皮通常都在长者高地的长者大厅。你可以在那里找到他。他会帮助你的。', `FemaleText_loc5`='歐托·灰皮大多都在長者高地的長者大廳裡。去那邊找他，他會幫你。', `FemaleText_loc7`='Otoh Pellejogris pasa mucho tiempo en la Sala de los Ancestros, en el Alto de los Ancestros. Encuéntralo y te ayudará.' WHERE `ID`=48024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개인적으로 티콘드리우스를 좋아하지 않는다고만 말해두지. 그리고 내가 섬기는 주인님도... 군단이 몰락하면 더 큰 이득을 취하실 거고.', `MaleText_loc4`='我对提克迪奥斯没什么好感。我侍奉的那个主人……将从军团的溃灭中获得不少好处。', `MaleText_loc5`='姑且這麼說吧，我並不喜歡提克迪奧斯，而我所侍奉的主人...亦將從燃燒軍團的覆滅中得利。', `MaleText_loc7`='Digamos que Tichondrius no me entusiasma, y al señor al que sirvo le... beneficiaría la caída de la Legión.' WHERE `ID`=48025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수렵의 봉우리에 태양길잡이 오두막이 있을 겁니다.', `MaleText_loc4`='你可以在猎人高地找到烈日行者集会所。', `MaleText_loc5`='你可以在獵人高地上找到日行者的小屋。', `MaleText_loc7`='Encontrarás el Refugio del Caminasol en el Alto de los Cazadores.', `FemaleText_loc1`='수렵의 봉우리에 태양길잡이 오두막이 있을 겁니다.', `FemaleText_loc4`='你可以在猎人高地找到烈日行者集会所。', `FemaleText_loc5`='你可以在獵人高地上找到日行者的小屋。', `FemaleText_loc7`='Encontrarás el Refugio del Caminasol en el Alto de los Cazadores.' WHERE `ID`=48026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로의 봉우리에 있는 현자들이 그대를 도와줄 겁니다. 그곳에 있는 장로의 전당에서 그들을 찾아보십시오.', `MaleText_loc4`='长者高地的先知们会帮助你。你可以在那里的长者大厅中找到他们。', `MaleText_loc5`='長者高地的先知們可以幫得了你，他們就在那邊的長者大廳裡。', `MaleText_loc7`='Los videntes del Alto de los Ancestros te ayudarán. Búscalos en la Sala de los Ancestros.', `FemaleText_loc1`='장로의 봉우리에 있는 현자들이 그대를 도와줄 겁니다. 그곳에 있는 장로의 전당에서 그들을 찾아보십시오.', `FemaleText_loc4`='长者高地的先知们会帮助你。你可以在那里的长者大厅中找到他们。', `FemaleText_loc5`='長者高地的先知們可以幫得了你，他們就在那邊的長者大廳裡。', `FemaleText_loc7`='Los videntes del Alto de los Ancestros te ayudarán. Búscalos en la Sala de los Ancestros.' WHERE `ID`=48027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성기사', `MaleText_loc4`='圣骑士', `MaleText_loc5`='聖騎士', `MaleText_loc7`='Paladín', `FemaleText_loc1`='성기사', `FemaleText_loc4`='圣骑士', `FemaleText_loc5`='聖騎士', `FemaleText_loc7`='Paladín' WHERE `ID`=48028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대모가 자신의 손목을 문지르며 당신을 향해 이를 드러내고 웃습니다.', `FemaleText_loc4`='巫婆长老揉搓着她的手腕，露出牙齿向你笑了笑。', `FemaleText_loc5`='女長者摸摸她的雙腕，露齒朝你笑了笑。', `FemaleText_loc7`='La bruja anciana se frota las muñecas mientras te sonríe brevemente.' WHERE `ID`=48029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈이 없어도 나는 적을 볼 수 있다. 너희가 풍기는 악취와 시끄러운 발걸음 소리만으로도 충분해!', `MaleText_loc4`='我无须用双眼来发现我的敌人。沉重的脚步声和恶臭已经让你们暴露了！', `MaleText_loc5`='我不需要用眼睛觀察我的敵人。笨拙的腳步聲和臭味已經暴露了你們的行蹤!', `MaleText_loc7`='Sin ojos también veo a mis enemigos. ¡Sus pasos torpes y su peste los delata!' WHERE `ID`=48030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈은 있으되 진실은 보지 못하는 것들. 모든 것의 종말을 받아들여라!', `MaleText_loc4`='空有双眼，却看不见真相。拥抱这一切的终结吧！', `MaleText_loc5`='對事實視而不見。擁抱一切的終結吧!', `MaleText_loc7`='Ven todo menos la verdad. ¡Abracen el fin de todo!' WHERE `ID`=48031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네가 여기까지 왔다니 놀랍군.', `FemaleText_loc4`='你们竟然能做到这个地步，我很惊讶。', `FemaleText_loc5`='我很訝異你竟然能深入到此處。', `FemaleText_loc7`='Me sorprende que hayas llegado hasta aquí.' WHERE `ID`=48032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에서 죽음이 널 기다린다.', `MaleText_loc4`='死亡在黑暗中等着你！', `MaleText_loc5`='死亡在黑暗裡等待著!', `MaleText_loc7`='¡La muerte aguarda en la oscuridad!' WHERE `ID`=48033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비참한 생이... 마침내 끝나는구나.', `MaleText_loc4`='这个可悲的存在终于完结了。', `MaleText_loc5`='這個可悲的存在終於結束了。', `MaleText_loc7`='Esta vida miserable llega a su fin.' WHERE `ID`=48034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 구해줘서 고맙다고 말해야겠지. 그게 옳은 선택이었는지는 두고 봐야 할 것 같지만 말이야.', `FemaleText_loc4`='我想，我应该感谢你救了我。我们很快就会知道你的这个决定是否明智。', `FemaleText_loc5`='我想我是該謝謝你救了我。我們很快就會知道，你是否認為這是個明智的決定。', `FemaleText_loc7`='Supongo que debería agradecerte que me hayas liberado. Pronto veremos si te parece que fue una decisión correcta.' WHERE `ID`=48035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 불길에서 도망갈 수는 없다!', `MaleText_loc4`='你们在灼热的烈焰面前无处可逃！', `MaleText_loc5`='你們無法躲過炙熱的火焰!', `MaleText_loc7`='¡No pueden ocultarse de la llama!' WHERE `ID`=48036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동쪽의 길을 따라가다 황혼의 마른땅 밖에서 날 만나게.', `FemaleText_loc4`='沿这条路向东走，我们在暮光凋零法阵外碰头。', `FemaleText_loc5`='到暮光枯萎之地的外面跟我碰面，就在往東邊的路上。', `FemaleText_loc7`='Reúnete conmigo justo al borde del Quebranto Crepuscular, por el camino del este.' WHERE `ID`=48037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 도망가라! 발을 디딜 때마다 맥박은 빨라지지. 점점 더 크게 울리는구나... 귀청이 터질 것만 같군! 넌 달아날 수 없다!', `MaleText_loc4`='对，跑吧！每跑一步你的心跳都会加快。这心跳声，洪亮如雷，震耳欲聋。你逃不掉的！', `MaleText_loc5`='沒錯，逃吧!每一步都會讓你的心跳加速。跳得轟隆作響...震耳欲聾。你逃不掉的!', `MaleText_loc7`='¡Sí, corran! Sus corazones se acelerarán. Los latidos, estruendosos... Casi ensordecedores. ¡No escaparán!' WHERE `ID`=48038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 마법 재연마사인 여마력사 피라가 그대를 도와줄 수 있을 거요. 그녀는 그녀의 마법부여 수습생들과 세다나와 함께 태양 궁정 멀리에서 찾을 수 있을 거요.', `MaleText_loc4`='这座城里的奥术重铸师灌魔者菲娜能帮助你。通常她会和逐日王庭外的瑟丹娜及其学徒们在一起。', `MaleText_loc5`='本城的秘法重鑄師是女巫師費菈，她可以幫得了你。她通常是在陽光庭院裡跟她的學徒希丹娜在討論事情。', `MaleText_loc7`='La reforjadora Arcana de la ciudad, la encantadora Fira, te ayudará. La mayoría de las veces se la suele ver con Sedana y sus aprendices de encantamiento, en el exterior de la Corte del Sol.', `FemaleText_loc1`='실버문의 마법 재연마사인 여마력사 피라가 그대를 도와줄 수 있을 거요. 그녀는 그녀의 마법부여 수습생들과 세다나와 함께 태양 궁정 멀리에서 찾을 수 있을 거요.', `FemaleText_loc4`='这座城里的奥术重铸师灌魔者菲娜能帮助你。通常她会和逐日王庭外的瑟丹娜及其学徒们在一起。', `FemaleText_loc5`='本城的秘法重鑄師是女巫師費菈，她可以幫得了你。她通常是在陽光庭院裡跟她的學徒希丹娜在討論事情。', `FemaleText_loc7`='La reforjadora Arcana de la ciudad, la encantadora Fira, te ayudará. La mayoría de las veces se la suele ver con Sedana y sus aprendices de encantamiento, en el exterior de la Corte del Sol.' WHERE `ID`=48039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 고약한 족쇄로부터 날 풀어줄 암호를 찾아오게.', `FemaleText_loc4`='找到密码，把我从这些恶魔骨头中放出来！', `FemaleText_loc5`='去把密碼找出來，幫我解開這該死的枷鎖!', `FemaleText_loc7`='¡Encuentra los códigos para liberarme de estas ataduras infernales!' WHERE `ID`=48040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스의 명가 중 한 명인 마법 재연마사는 엑소더스의 마법부여사들과 함께 일합니다. 수정 전당의 보석세공사 맞은 편에서 그들 모두를 찾을 수 있을 겁니다.', `MaleText_loc4`='一名属于达纳苏斯上层精灵的奥术重铸师正和埃索达的附魔师们呆在一起。你可以在水晶大厅中珠宝加工师的对面找到他们。', `MaleText_loc5`='有位達納蘇斯的精靈貴族是個秘法重鑄師，來到這邊和艾克索達的附魔師合作。你可以到水晶大廳裡找到他們，就在珠寶匠的對面。', `MaleText_loc7`='Una representante de los Altonato de Darnassus, una reforjadora Arcana, está trabajando con los encantadores de El Exodar. Los verás a todos en la Sala de Cristal, frente a los joyeros artesanos.', `FemaleText_loc1`='다르나서스의 명가 중 한 명인 마법 재연마사는 엑소더스의 마법부여사들과 함께 일합니다. 수정 전당의 보석세공사 맞은 편에서 그들 모두를 찾을 수 있을 겁니다.', `FemaleText_loc4`='一名属于达纳苏斯上层精灵的奥术重铸师正和埃索达的附魔师们呆在一起。你可以在水晶大厅中珠宝加工师的对面找到他们。', `FemaleText_loc5`='有位達納蘇斯的精靈貴族是個秘法重鑄師，來到這邊和艾克索達的附魔師合作。你可以到水晶大廳裡找到他們，就在珠寶匠的對面。', `FemaleText_loc7`='Una representante de los Altonato de Darnassus, una reforjadora Arcana, está trabajando con los encantadores de El Exodar. Los verás a todos en la Sala de Cristal, frente a los joyeros artesanos.' WHERE `ID`=48041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 저 녀석들을 해치우는 데 전념해!', `MaleText_loc4`='不要忘记使用它！', `MaleText_loc5`='開砲交給你!', `MaleText_loc7`='¡Tú te encarrrgas de matarrrr!' WHERE `ID`=48042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 망해버렸소, $c|1이여;여;!', `MaleText_loc4`='全都下地狱了，$c！', `MaleText_loc5`='場面失控了，$c!', `MaleText_loc7`='¡Todo se está yendo al infierno, $c!' WHERE `ID`=48043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디야를 찾으십니까? 그녀는 나루의 보좌에 있는 영상 사이를 돌아다니는데, 기꺼이 당신을 도와줄 겁니다.', `MaleText_loc4`='如果你要找蒂亚，她经常在纳鲁之座的幻象中流连。她一定很愿意帮助你。', `MaleText_loc5`='去找迪亞，她會很樂意幫你。她通常會在那魯之座的投射影像那附近。', `MaleText_loc7`='Buscas a Diya, que se pasea entre las imágenes que hay alrededor del Trono de los Naaru. Estará encantada de ayudarte.', `FemaleText_loc1`='디야를 찾으십니까? 그녀는 나루의 보좌에 있는 영상 사이를 돌아다니는데, 기꺼이 당신을 도와줄 겁니다.', `FemaleText_loc4`='如果你要找蒂亚，她经常在纳鲁之座的幻象中流连。她一定很愿意帮助你。', `FemaleText_loc5`='去找迪亞，她會很樂意幫你。她通常會在那魯之座的投射影像那附近。', `FemaleText_loc7`='Buscas a Diya, que se pasea entre las imágenes que hay alrededor del Trono de los Naaru. Estará encantada de ayudarte.' WHERE `ID`=48044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운전은 내가 맡을 테니까!', `MaleText_loc4`='我来负责驾驶！', `MaleText_loc5`='開車交給我!', `MaleText_loc7`='¡Yo me encarrrrgo de conducirrr!' WHERE `ID`=48045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 동굴은 저주받았습니다. 끔찍한 기운으로 가득 차 있어요.$B$B황혼의 망치단은 산꼭대기에 기지를 세우면서 자신들에게 쓸모없는 이들을 이 동굴에 몰아넣었지요. 한때 이곳에 거했던 검은 비룡의 먹이로 말입니다.$B$B그들은 절대로 동굴을 나오지 않습니다. 심지어 영혼 상태로도요.', `FemaleText_loc4`='这些洞可都是鬼窟，伙计。里面全都是最可怕的魂能。$B$B当暮光之锤盘踞在这座山顶的时候，那些被他们淘汰的人都被扔进了这些山洞。成为了以这些山洞为巢穴的黑龙的食物。$B$B这些洞里从没有活人走出来，就连那些灵魂也逃不出来。', `FemaleText_loc5`='這裡的洞穴有鬼，老兄，有很不好的魂能。$B$B以前暮光之錘在山頂上的時候，他們認為沒資格的人都會被丟進山洞。丟進裡面，當作以前住在這裡的黑龍的食物。$B$B進去的人從來沒有出來過。連靈魂都出不來。', `FemaleText_loc7`='Es''tas cuevas eh''tán embuja''as, colega. Repletas del peor yuyu.$B$BEn los tiempos en los que el Mah''tillo Crepuscular se asentó en lo alto de la montaña, los indignos eran arroja''os a eh''tas cavernas. En La Garganta. Como alimento pa'' los dracos negros que en otros tiempos anidaron allí.$B$BNunca jamás se volvió a ver a esa gente. Ni siquiera sus eh''píritus.' WHERE `ID`=48046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네, $c|1이여;여;!', `FemaleText_loc4`='你好，$c！', `FemaleText_loc5`='你好，$c!', `FemaleText_loc7`='¡Saludos, $c!' WHERE `ID`=48047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사루스 님, 제 거미를 잃어버렸습니다. 한 마리 더 받을 수 있을까요?', `MaleText_loc4`='萨露丝，我的蜘蛛丢了。能再给我一只吗？', `MaleText_loc5`='薩魯斯，我弄丟了我的蜘蛛。可以再給我一隻嗎?', `MaleText_loc7`='Sarus, se me ha perdido la araña. ¿Me puedes dar otra?', `FemaleText_loc1`='사루스 님, 제 거미를 잃어버렸네요. 한 마리 더 받을 수 있을까요?', `FemaleText_loc4`='萨露丝，我的蜘蛛丢了。能再给我一只吗？', `FemaleText_loc5`='薩魯斯，我弄丟了我的蜘蛛。可以再給我一隻嗎?', `FemaleText_loc7`='Sarus, se me ha perdido la araña. ¿Me puedes dar otra?' WHERE `ID`=48048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐구자 보두로는 고난의 거리 내에 있는 상인의 시장에서 종종 보이곤 합니다. 그곳에서 그를 찾아보시기 바랍니다.', `MaleText_loc4`='搜寻者波杜鲁通常都在贫民窟的集市里。要找他就去那里吧。', `MaleText_loc5`='『追尋者』波度羅經常會出現在陰鬱城的商店街。是我的話我就會去那裡找他。', `MaleText_loc7`='A Boduro el Buscador se le suele ver en el bazar de los mercaderes, dentro del Bajo Arrabal. Yo lo buscaría por ahí.', `FemaleText_loc1`='탐구자 보두로는 고난의 거리 내에 있는 상인의 시장에서 종종 보이곤 합니다. 그곳에서 그를 찾아보시기 바랍니다.', `FemaleText_loc4`='搜寻者波杜鲁通常都在贫民窟的集市里。要找他就去那里吧。', `FemaleText_loc5`='『追尋者』波度羅經常會出現在陰鬱城的商店街。是我的話我就會去那裡找他。', `FemaleText_loc7`='A Boduro el Buscador se le suele ver en el bazar de los mercaderes, dentro del Bajo Arrabal. Yo lo buscaría por ahí.' WHERE `ID`=48049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명가의 대마법사인 아라니르 스타싱어는 재연마의 대가랍니다. 그대를 돕도록 그를 설득해 보셔도 좋겠네요.

그는 달라란 북서쪽에 있는 마법사 교역소 바로 외곽에 있는 마법부여 전문점의 마법부여사들과 자신의 작품에 관하여 토론하는 모습을 종종 볼 수 있으니 그리로 가서 그를 찾아보세요.', `MaleText_loc4`='上层精灵大法师埃兰希尔·星歌是一位奥术重铸大师……你也许能请求他帮助你。

他通常会在达拉然西北的魔法商业区外面，和简单附魔中的那些人讨论他的魔法技艺。', `MaleText_loc5`='精靈貴族大法師艾倫希爾·星歌者是一位精通秘法重鑄的大師...你或許能說服他幫幫你。

他經常會跟完全附魔商店的人在討論事情，就在達拉然西北邊的魔導師貿易區外面。', `MaleText_loc7`='Aranhir Vocestrella, el archimago Altonato, es un maestro de la reforja Arcana... A lo mejor lo puedes convencer para que te ayude.

A menudo se le ve charlando de su arte con el personal de Simplemente Encantador, justo en el exterior del Mercado de Magos al noroeste de Dalaran.', `FemaleText_loc1`='명가의 대마법사인 아라니르 스타싱어는 재연마의 대가랍니다. 그대를 돕도록 그를 설득해 보셔도 좋겠네요.

그는 달라란 북서쪽에 있는 마법사 교역소 바로 외곽에 있는 마법부여 전문점의 마법부여사들과 자신의 작품에 관하여 토론하는 모습을 종종 볼 수 있으니 그리로 가서 그를 찾아보세요.', `FemaleText_loc4`='上层精灵大法师埃兰希尔·星歌是一位奥术重铸大师……你也许能请求他帮助你。

他通常会在达拉然西北的魔法商业区外面，和简单附魔中的那些人讨论他的魔法技艺。', `FemaleText_loc5`='精靈貴族大法師艾倫希爾·星歌者是一位精通秘法重鑄的大師...你或許能說服他幫幫你。

他經常會跟完全附魔商店的人在討論事情，就在達拉然西北邊的魔導師貿易區外面。', `FemaleText_loc7`='Aranhir Vocestrella, el archimago Altonato, es un maestro de la reforja Arcana... A lo mejor lo puedes convencer para que te ayude.

A menudo se le ve charlando de su arte con el personal de Simplemente Encantador, justo en el exterior del Mercado de Magos al noroeste de Dalaran.' WHERE `ID`=48050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이 엘프 마법사이자 학자인 다리네스는 달라란의 가장 학식있는 고고학자에다가... 가장 사교적이랍니다.$B$B그녀는 달라란 중앙에서 바로 북쪽에 있는 요술쟁이 휴게실에서 자주 볼 수 있답니다. 그곳에서 분위기를 즐기거나 거친 여행자들에 대하여 고용자나 후원자들과 논하곤 한답니다.', `MaleText_loc4`='高等精灵法师和学者——达瑞妮斯是这座城里最博学的考古学家……也是最喜交际的人。$B$B她通常呆在魔术旅馆里，就在城中心的北边。她喜欢那里的气氛，常常会与魔术旅馆的老板和客人们谈论她在荒野中的冒险生活。', `MaleText_loc5`='高等精靈博學者法師達莉諾絲是本城最學識淵博的考古學家...而且也是最善於交際的人。$B$B她通常都待在戲法旅舍，就在市中心的北方，在那邊享受氣氛，還有跟店主和投資人討論她驚奇的冒險故事。', `MaleText_loc7`='La elfa noble Dariness, maga y académica, es la arqueóloga más erudita de la ciudad... y la más sociable.$b$bSe la suele ver en el Salón Juego de Manos, justo al norte del centro de la ciudad, disfrutando del ambiente o contando sus increíbles aventuras a los dueños y a los parroquianos.', `FemaleText_loc1`='하이 엘프 마법사이자 학자인 다리네스는 달라란의 가장 학식있는 고고학자에다가... 가장 사교적이랍니다.$B$B그녀는 달라란 중앙에서 바로 북쪽에 있는 요술쟁이 휴게실에서 자주 볼 수 있답니다. 그곳에서 분위기를 즐기거나 거친 여행자들에 대하여 고용자나 후원자들과 논하곤 한답니다.', `FemaleText_loc4`='高等精灵法师和学者——达瑞妮斯是这座城里最博学的考古学家……也是最喜交际的人。$B$B她通常呆在魔术旅馆里，就在城中心的北边。她喜欢那里的气氛，常常会与魔术旅馆的老板和客人们谈论她在荒野中的冒险生活。', `FemaleText_loc5`='高等精靈博學者法師達莉諾絲是本城最學識淵博的考古學家...而且也是最善於交際的人。$B$B她通常都待在戲法旅舍，就在市中心的北方，在那邊享受氣氛，還有跟店主和投資人討論她驚奇的冒險故事。', `FemaleText_loc7`='La elfa noble Dariness, maga y académica, es la arqueóloga más erudita de la ciudad... y la más sociable.$b$bSe la suele ver en el Salón Juego de Manos, justo al norte del centro de la ciudad, disfrutando del ambiente o contando sus increíbles aventuras a los dueños y a los parroquianos.' WHERE `ID`=48051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|C00ff0000키마이론의 대학살에 담즙로봇이 정지했습니다|r!', `MaleText_loc4`='|c00FF0000奇美隆的屠杀让胆汁喷洒机离线了！|r', `MaleText_loc5`='|c00FF0000奇瑪隆的大屠殺把「好膽」打得停機了!|r', `MaleText_loc7`='|c00FF0000¡La Masacre de Chimaeron ha desactivado el Bilistrón!|r' WHERE `ID`=48052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|c0000FF00담즙로봇이 다시 가동됩니다|r!', `MaleText_loc4`='|c0000FF00胆汁喷洒机恢复联线了！|r', `MaleText_loc5`='|c0000FF00「好膽」恢復運作了!|r', `MaleText_loc7`='|c0000FF00¡El Bilistrón se ha reactivado!|r' WHERE `ID`=48053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선수를 치겠다 이거죠, 좋아요. 출구로 들어가세요...', `FemaleText_loc4`='哦，原来是你抢在我前面了。通过这个传送门离开吧……', `FemaleText_loc5`='我懂了，搶先我一步是吧。你的出口在等著...', `FemaleText_loc7`='Veo que te me has adelantado. Tu salida aguarda...' WHERE `ID`=48054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼... 안돼! 여긴 내 영토야! 네가 가지게 둘 순 없... 어...', `MaleText_loc4`='不……不！这是我的地盘！你不能占据……它……', `MaleText_loc5`='不...不!這是我的領域!你不能擁有...它...', `MaleText_loc7`='No...¡NO! ¡Este es mi dominio! No puedes... tenerlo...' WHERE `ID`=48055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 필멸자여... 네 시체 위에 새 제국을 세우겠다!', `MaleText_loc4`='可怜的凡人……我会在你的尸体上建立一个新的帝国！', `MaleText_loc5`='悲賤的凡人...我會在你的屍體上建立一個新的帝國!', `MaleText_loc7`='Patético mortal... ¡Levantaré un nuevo imperio sobre tu cadáver!' WHERE `ID`=48056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워! 안녕! 대장님께 드릴 인간 좀 붙잡아보자!', `MaleText_loc4`='谢谢！嗨！让我们为队长收集些人类！', `MaleText_loc5`='謝啦!嗨!讓我們弄幾個人類給隊長!', `MaleText_loc7`='¡GRACIAS! ¡HOLA! ¡VAMOS A REUNIR ALGUNOS HUMANOS PARA EL CAPITÁN!' WHERE `ID`=48057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몬나스를 광산 밖으로 안전하게 호위해야 합니다. 몬나스가 거미줄 속의 인간에게 다가가지 못하게 하십시오.', `MaleText_loc4`='护送杜马斯安全地离开矿洞。不要让杜马斯靠近那些被网住的人类。', `MaleText_loc5`='護送杜瑪斯安全離開礦坑。別讓杜瑪斯靠近被網住的人類。', `MaleText_loc7`='Escolta a Dumass hasta que salga de la mina. Aléjalo de los humanos enredados.' WHERE `ID`=48058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 이리 오래 걸려? 난 갈래! 안녕!', `MaleText_loc4`='你怎么耽搁了这么久？我要走了！再见！', `MaleText_loc5`='為什麼拖這麼久?我要走了!再見!', `MaleText_loc7`='¿POR QUÉ TARDAS TANTO? ¡ME VOY! ¡ADIÓS!' WHERE `ID`=48059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 대장님 제가 돌아왔습니다! 만세!', `MaleText_loc4`='耶！队长，我回来了！万岁！', `MaleText_loc5`='耶!隊長，我回來了!萬歲!', `MaleText_loc7`='¡YUJU! ¡CAPITÁN, HE VUELTO! ¡HURRA!' WHERE `ID`=48060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래. 끝내주네. $P|1이;가; 광산 탈출을 도와줬나 보군. 피할 수 없는 네 비극적인 죽음이 잠시 미뤄졌다니 기뻐서 돌아가시겠다. 자, 이제 당장 떠나는 게 어때? 타렌 제분소에서 너 같은 포세이큰을 찾고 있다고 들었는데, 몬나스.', `MaleText_loc4`='喔，这太好了。真高兴看到那个$P帮助你离开了矿洞，让你不可避免的悲剧性死亡能够再延迟一段时间。现在你为什么不跑了？我听说塔伦米尔正在找像你一样的被遗忘者，杜马斯。', `MaleText_loc5`='對，是啊，真棒。我好—高興看到$P能幫你離開礦坑，延後了你可悲而必然的死亡。好了，快離開這裡吧。我聽說塔倫米爾正在尋找像你這樣的被遺忘者，杜瑪斯。', `MaleText_loc7`='Vaya, qué bien, oye. Estoy EXTASIADO de ver que $P te ha ayudado a salir de la mina y ha pospuesto tu trágica e inevitable muerte. Ahora, ¿por qué no te largas? He oído que en Molino Tarren buscan Renegados igualitos a ti, Dumass.' WHERE `ID`=48061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렌 제분소! 불모의 땅에 있는 그곳 말씀이시죠! 당장 갈게요! 고마워요!', `MaleText_loc4`='塔伦米尔！好啊！就是那个在贫瘠之地的塔伦米尔吗！我要走了！谢谢！', `MaleText_loc5`='塔倫米爾!好!在貧瘠之地對不對!我這就出發!謝啦!', `MaleText_loc7`='¡MOLINO TARREN! ¡VALE! ¿ESO ESTÁ EN LOS BALDÍOS? ¡AHORA VOY! ¡GRACIAS!' WHERE `ID`=48062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 쓰러뜨리고 나서 처치해! 그러고 족쇄를 채워!', `MaleText_loc4`='把他们打倒，消灭他们！给他们戴上镣铐！', `MaleText_loc5`='打倒他們、殺掉他們!然後銬起來!', `MaleText_loc7`='¡PRIMERO DALES UNA PALIZA, LUEGO LOS MATAS! ¡Y LUEGO LES PONES LOS GRILLETES!' WHERE `ID`=48063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것쯤이야!', `MaleText_loc4`='这很容易！没错！', `MaleText_loc5`='太簡單了!真的!', `MaleText_loc7`='¡ESTO ES FÁCIL! ¡SÍ!' WHERE `ID`=48064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 하나 있다!', `MaleText_loc4`='这里有一个！', `MaleText_loc5`='這裡有一個!', `MaleText_loc7`='¡AHÍ HAY UNO!' WHERE `ID`=48065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 사람들이 왜 이리 많지?!?', `MaleText_loc4`='这些人是怎么跑到这里来的？！', `MaleText_loc5`='這些人是怎樣跑進來這裡的?!?', `MaleText_loc7`='¡¿CÓMO HA ENTRADO TANTA GENTE AQUÍ?!' WHERE `ID`=48066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석 화난 것 같은데!', `MaleText_loc4`='这家伙发怒了！', `MaleText_loc5`='這一個很生氣!', `MaleText_loc7`='¡ESTE ESTÁ ENFADADO!' WHERE `ID`=48067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음부터 이곳에 아름다운 농장이 있었던 건 아닐세, $c. 굳은 결의와 의지가 있었기에 낙후된 인간 농장을 로데론에서 가장 크고 생산성 높은 진흙과 버섯 재배지로 만들 수 있었지.$B$B그런데 이 많은 노력이 단순 사고 하나로 수포로 돌아가게 생겼어!', `MaleText_loc4`='这片广阔的田野原本并非如此，$c。是我们凭借坚定的决心和意志力，将人类腐朽的农场变成为洛丹伦最大，最丰饶的药渣田和蘑菇种植园。$B$B现在，所有这一切都可能因为一场小小的事故而将化为乌有！', `MaleText_loc5`='這片壯觀的農場不是憑空冒出來的，$c。是透過了不屈不撓的決心和努力，我們好不容易才把這片殘破的人類農場變成羅德隆最大最豐富的淤泥和蘑菇田。$B$B可是現在，只因為一件小小的意外，我們卻可能會失去這一切!', `MaleText_loc7`='Estos gloriosos campos no siempre han estado aquí, $c. Solo gracias a la determinación y a la fuerza conseguimos convertir los decrépitos campos de los humanos en la mayor y más productiva plantación de setas y fango de Lordaeron.$b$b¡Y ahora podríamos perderlo todo debido a un simple accidente!' WHERE `ID`=48068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 원래 농부였어!', `MaleText_loc4`='我曾经是一名农夫！', `MaleText_loc5`='我以前是農夫!', `MaleText_loc7`='¡ANTES ERA GRANJERO!' WHERE `ID`=48069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기도 하나 있다!', `MaleText_loc4`='那边有一个！', `MaleText_loc5`='那邊有一個!', `MaleText_loc7`='¡HAY UNO POR AHÍ!' WHERE `ID`=48070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 인간들 좀 위험해 보이는데!', `MaleText_loc4`='这些人类看起来很危险！', `MaleText_loc5`='這些人類看起來好危險!', `MaleText_loc7`='¡ESOS HUMANOS PARECEN PELIGROSOS!' WHERE `ID`=48071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해줘서 고마워!', `MaleText_loc4`='谢谢你救了我！', `MaleText_loc5`='謝謝你救了我!', `MaleText_loc7`='¡GRACIAS POR RESCATARME!' WHERE `ID`=48072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 깨어났을 때, 밴시 여왕님이 거대한 갈색 오크와 대화하는 걸 봤어!', `MaleText_loc4`='当我醒过来的时候，我看见女妖之王正在和一个高大的褐色兽人交谈！', `MaleText_loc5`='在我醒來的時候，我有看到女妖之王在跟一個棕皮膚的獸人大塊頭在講話!', `MaleText_loc7`='¡CUANDO ME DESPERTÉ VI A LA REINA ALMA EN PENA HABLANDO CON UN ORCO GRANDE Y MARRÓN!' WHERE `ID`=48073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 우리 편이야?', `MaleText_loc4`='谁是我们的朋友？', `MaleText_loc5`='誰是我們的朋友?', `MaleText_loc7`='¿QUIÉNES SON NUESTROS AMIGOS?' WHERE `ID`=48074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 혹시 밴시 여왕님이 늑대인간을 모조리 죽였을 때 은빛소나무 숲에 있었니?!', `MaleText_loc4`='当女妖之王杀死了所有狼人的时候，你在银松森林吗？', `MaleText_loc5`='女妖之王幹掉所有的狼人的時候，你有在銀松森林嗎!?', `MaleText_loc7`='¡¿ESTABAS EN ARGÉNTEOS CUANDO LA REINA ALMA EN PENA MATÓ A TODOS LOS HUARGEN?!' WHERE `ID`=48075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 커집니다...', `MaleText_loc4`='变得更大……', `MaleText_loc5`='變大...', `MaleText_loc7`='Crece...' WHERE `ID`=48076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 더 커집니다...', `MaleText_loc4`='变得更加巨大……', `MaleText_loc5`='變更大...', `MaleText_loc7`='Crece aún más...' WHERE `ID`=48077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발하기 직전인 것 같습니다!', `MaleText_loc4`='看样子，他就要爆炸了！', `MaleText_loc5`='他快要爆炸了!', `MaleText_loc7`='¡Parece que está a punto de explotar!' WHERE `ID`=48078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부순다!', `MaleText_loc4`='毁灭！', `MaleText_loc5`='消滅!', `MaleText_loc7`='¡DESTRUIR!' WHERE `ID`=48079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기가 굴단의 해골이 보관된 곳이군! 이 보잘것없는 악마들만으로는 날 막을 수 없을 것이다!', `MaleText_loc4`='这里就是收藏古尔丹之颅的地方！这些低贱的恶魔不可能阻止我！', `MaleText_loc5`='這裡就是保存古爾丹之顱的地方!這些不起眼的惡魔阻止不了我奪走它!', `MaleText_loc7`='¡Aquí es donde guardan la calavera de Gul''dan! ¡Esos irrisorios demonios no me impedirán recuperarla!' WHERE `ID`=48080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 악마들이 이 숲을 타락시킬 순 없을 거다. 하지만, 만약 날 위해 이 힘을 취한다면, 아키몬드의 그 어떤 부관보다도 강해질 테지.', `MaleText_loc4`='现在，至少恶魔们不会再腐蚀森林了。但如果我能够掌握这种力量，我将比阿克蒙德的任何部下都更加强大。', `MaleText_loc5`='至少，森林不會再受到惡魔的腐化了。可是如果我把這股力量佔為己有，我將變得比阿克蒙德的任何手下都來得強大。', `MaleText_loc7`='Al menos ahora los demonios ya no corromperán los bosques... Pero si reclamo este poder para mí, me volveré más fuerte que cualquiera de los tenientes de Archimonde.' WHERE `ID`=48081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아... 이 힘은 내가 취하겠다!', `MaleText_loc4`='是的……这种力量应该属于我！', `MaleText_loc5`='對...這力量本應屬於我!', `MaleText_loc7`='Sí... ¡El poder debería ser mío!' WHERE `ID`=48082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 난 완전해졌다!', `MaleText_loc4`='啊，如此强大的力量！', `MaleText_loc5`='我終於完整了!', `MaleText_loc7`='¡Ahora estoy completo!' WHERE `ID`=48083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁜 기운은 당신에게 아무 영향도 미치지 못합니다.', `FemaleText_loc4`='不要害怕坏魂能，$g甜心:女孩;。', `FemaleText_loc5`='壞東西害不了你，$g小子:小妞;。', `FemaleText_loc7`='El mal yuyu no tiene na''a contra ti, $gencanto:muchacha;.' WHERE `ID`=48084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가십시오, $c님. 이 동굴 안에는 엄청난 어둠이 도사리고 있습니다. 그냥 좀 어두침침하다 이런 얘기가 아닙니다.', `MaleText_loc4`='回去吧，$c。这座洞窟里隐藏着某种真正的黑暗。我说的可不是那种因为缺少照明而产生的黑暗。', `MaleText_loc5`='回頭喔，$c。這個洞穴裡頭很黑暗，而且不是火把的亮光就能趕走的那種黑暗。', `MaleText_loc7`='Vuelve por donde has veni''o, $c. Dentro de esa cueva habrá mucha oscuridad, y no eh''toy hablando precisamente de la falta de luz.' WHERE `ID`=48085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 친구! 빛은 가져오셨지요? 무슨 일이 생기든 간에 그걸 꽉 잡고 계셔야 합니다.$B$B준비됐다고 말씀만 하시면 영혼의 세계로 들여보내 드리지요. 거기 가시면 영혼들이 당신을 쫓으며 어둠 속으로 끌어들이려 할 겁니다.$B$B그런 고약한 영혼들에게는 빛을 비추세요!', `MaleText_loc4`='就是这个，朋友！你得到那灵魂之光了？一定要紧握住它，无论发生什么事情都不要松手。$B$B说出那个词，然后我就让你进入灵魂领域。那些灵魂会来找你，竭尽全力将你拖入黑暗。$B$B这时你就要用这灵魂之光去照耀那些污秽！', `MaleText_loc5`='就是這裡，老兄!你有亮光?不管發生什麼事情，千萬拿好。$B$B開口說一聲，我就把你送進靈魂國度。靈魂，它們會來找你，要把你拉進去黑暗裡面。$B$B用亮光把壞東西趕走!', `MaleText_loc7`='¡Eso es, colega! ¿Tienes la luz? Pase lo que pase no la sueltes. $B$BDi la palabra y te pondré en el reino de los eh''píritus. Los eh''píritus vendrán a por ti y te intentarán arrah''trar hacia la oscuridad.$B$B¡Ciégalos con esa luz!' WHERE `ID`=48086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어려운 일을 해주셨군요, 친구. 이제 이 동굴은 안전합니다.$B$B잘만 꾸미면 아늑한 공간이 될 거예요. 그렇게 생각하지 않습니까? 가면을 좀 걸어 놓으면 어떨까요?', `MaleText_loc4`='那些脏东西已经被清除了，朋友。这座洞穴现在安全了。$B$B这个地方很适合成为一个家。你觉得如何？也许还缺几个面具？', `MaleText_loc5`='壞事情結束了，老兄。這個洞穴現在安全了。$B$B這個地方拿來當家還不錯。你覺得怎樣?還是要多擺幾個面具?', `MaleText_loc7`='Hemos termina''o con el trabajo sucio, colega. Ahora eh''ta cueva eh''tá a salvo.$B$BEh''te lugar puede conveh''tirse en un buen hogar, ¿no crees? ¿Con unas cuantas máscaras más?' WHERE `ID`=48087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아무것도 두려워하지 않는군요, $c님!$B$B부누가 바깥에서 당신을 기다리고 있습니다.', `MaleText_loc4`='你可真是无所畏惧，$c！$B$B布努正在外面等着你。', `MaleText_loc5`='你什麼都不要怕，$c!$B$B布努在外面等你。', `MaleText_loc7`='¡No tienes mie''o de nada, $c!$B$BBuunu te eh''perará fuera.' WHERE `ID`=48088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶다고요? 아뇨, 안돼요. 잘못 찾아왔어요.', `MaleText_loc4`='你要接受训练？我可帮不了你。我可不是你要找的人。', `MaleText_loc5`='你要找人訓練你?不，我沒辦法。我不是你要找的訓練師。', `MaleText_loc7`='¿Buscas instrucción? Mala suerte, no soy tu tío.', `FemaleText_loc1`='훈련을 받고 싶다고요? 아뇨, 안돼요. 잘못 찾아왔어요.', `FemaleText_loc4`='你要接受训练？我可帮不了你。我可不是你要找的人。', `FemaleText_loc5`='你要找人訓練你?不，我沒辦法。我不是你要找的訓練師。', `FemaleText_loc7`='¿Buscas instrucción? Mala suerte, no soy tu chica.' WHERE `ID`=48089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받으러 왔습니까?', `MaleText_loc4`='你要接受训练，大个子？', `MaleText_loc5`='大塊頭，在找人訓練嗎?', `MaleText_loc7`='¿Quieres instrucción, truhán?', `FemaleText_loc1`='훈련을 받으러 왔습니까?', `FemaleText_loc4`='你要接受训练，大个子？', `FemaleText_loc5`='大塊頭，在找人訓練嗎?', `FemaleText_loc7`='¿Quieres instrucción, truhán?' WHERE `ID`=48090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선적실로 가려면 저를 따라오십시오, $n.', `MaleText_loc4`='我会带你去装载室，$n。', `MaleText_loc5`='跟我到裝載室，$n。', `MaleText_loc7`='Puedes seguirme hasta la Zona de Carga, $n.', `FemaleText_loc1`='선적실로 가려면 저를 따라오세요, $n.', `FemaleText_loc4`='我会带你去装载室，$n。', `FemaleText_loc5`='跟我到裝載室，$n。', `FemaleText_loc7`='Puedes seguirme hasta la Zona de Carga, $n.' WHERE `ID`=48091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴 안에 있는 세 제단을 찾아가십시오.', `MaleText_loc4`='去这座洞里的三座祭坛。', `MaleText_loc5`='走到洞穴裡的三個神殿', `MaleText_loc7`='Vete a los tres santuarios dentro de la cueva' WHERE `ID`=48092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 빛을 비추어 영혼을 추방하십시오!', `MaleText_loc4`='将灵魂之光对准鬼魂来驱散他们！', `MaleText_loc5`='以靈魂之光瞄準鬼魂，把它們趕走!', `MaleText_loc7`='¡Dirige tu Luz de las almas hacia los espíritus y hazlos desaparecer!' WHERE `ID`=48093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임시 - 퀘스트 미완성', `MaleText_loc4`='Placeholder - Quest Not Yet Implemented', `MaleText_loc5`='Placeholder - Quest Not Yet Implemented', `MaleText_loc7`='Placeholder - Quest Not Yet Implemented' WHERE `ID`=48094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 우첵!', `MaleText_loc4`='我准备好了，尤彻克！', `MaleText_loc5`='我準備好了，烏徹克!', `MaleText_loc7`='¡Estoy listo, Uchek!', `FemaleText_loc1`='준비됐어요, 우첵!', `FemaleText_loc4`='我准备好了，尤彻克！', `FemaleText_loc5`='我準備好了，烏徹克!', `FemaleText_loc7`='¡Estoy lista, Uchek!' WHERE `ID`=48095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 속삭임이 들려오지 않는군요, $n 님. 동굴 안에서 무슨 일이 있었습니까?', `FemaleText_loc4`='我听不见低语声了，$n。洞里发生了什么事？', `FemaleText_loc5`='我沒有再聽到怪聲音了，$n。洞裡面發生了什麼?', `FemaleText_loc7`='Ya no oigo los susurros, $n. ¿Qué ha ocurri''o en esa cueva?' WHERE `ID`=48096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버섯구름 봉우리에 그나마 남은 것조차 완전히 파괴되는 걸 보고 싶나?$B$B싫다고?$B$B그렇다면 내 명령을 따르는 게 좋을 걸세.', `FemaleText_loc4`='你想看着千针石林彻底毁灭吗？$B$B不想？$B$B那就照我说的做。', `FemaleText_loc5`='你想要看到殘缺不全的千針石林被徹底毀滅嗎?$B$B不想?$B$B那就乖乖照我的話去做。', `FemaleText_loc7`='¿Quieres ser testigo de la total destrucción de lo que queda de Las Mil Agujas?$B$B¿No?$B$BEntonces haz exactamente lo que te ordeno.' WHERE `ID`=48097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 침입한 대가를 치르게 될 것이다!', `MaleText_loc4`='你要为你的入侵付出代价！', `MaleText_loc5`='你要為擅闖的結果付出代價!', `MaleText_loc7`='¡Pagarás por esta intrusión!' WHERE `ID`=48098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 생존자들을 여기로 모아 오염을 제거한답니다. 오염만 제거하면 지상으로 나가는 건 금방이라고요!', `FemaleText_loc4`='我们就是在这儿集合幸存者，准备对他们进行净化。距离地表没多远了！', `FemaleText_loc5`='這裡就是我們集合生還者進行消毒的地方。然後從那邊到地面只有短短的一小段距離而已!', `FemaleText_loc7`='Aquí es donde reunimos a los supervivientes para prepararlos para la descontaminación. Desde aquí, ¡solo queda un viajecito para llegar a la superficie!' WHERE `ID`=48099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에서 경계를 늦추지 말라고 따로 말할 필요는 없겠죠?', `MaleText_loc4`='我相信我不必提醒你，在这儿要保持警惕。', `MaleText_loc5`='我想我應該不必提醒你，在底下這邊得多加小心了吧。', `MaleText_loc7`='Seguro que no hace falta recordarte que te mantengas alerta aquí abajo.' WHERE `ID`=48100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄수가 탈출했다! 처치하라!', `MaleText_loc4`='有个囚犯逃跑了！杀了$g他:她;！', `MaleText_loc5`='有個犯人逃走了!殺掉$g他:她;!', `MaleText_loc7`='¡Ha escapado $gun prisionero:una prisionera;! ¡$gMatadlo:Matadla;!' WHERE `ID`=48101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리 가지는 못할 거다!', `MaleText_loc4`='你走不远的！', `MaleText_loc5`='你逃不了多遠的!', `MaleText_loc7`='¡No llegarás muy lejos!' WHERE `ID`=48102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 님의 이름 아래 네 피를 뿌려주마!', `MaleText_loc4`='以死亡之翼之名，我要让你见不到明天早上的太阳！', `MaleText_loc5`='以死亡之翼之名，我要你鮮血四濺!', `MaleText_loc7`='¡Derramaré tu sangre en el nombre de Alamuerte!' WHERE `ID`=48103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예로 사는 게 체질에 맞지 않다면, 시체로 한 번 살아보라고!', `MaleText_loc4`='要是奴役不适合你，那死亡一定适合！', `MaleText_loc5`='當奴隸不適合你，當死人比較適合!', `MaleText_loc7`='¡Si la esclavitud no es lo tuyo, a lo mejor la muerte sí!' WHERE `ID`=48104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육신을 가진 자가 얼마나 약한지 알려주마!', `MaleText_loc4`='我要让你看到血肉之躯的软弱！', `MaleText_loc5`='讓你知道血肉之軀的孱弱!', `MaleText_loc7`='¡Te demostraré la debilidad de la carne!' WHERE `ID`=48105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠에 발을 들여놓은 걸 후회하게 될 거다!', `MaleText_loc4`='你会后悔踏足奥丹姆的！', `MaleText_loc5`='你會祈禱自己從未踏進奧丹姆!', `MaleText_loc7`='¡Desearás no haber puesto un pie en Uldum!' WHERE `ID`=48106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_felrainoffire.blp:20|t%s|1이;가; |cFFFF0000|Hspell:88972|h[지옥 화염폭풍]|h|r|1을;를; 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_felrainoffire.blp:20|t%s开始施放|cFFFF0000|Hspell:88972|h[邪火风暴]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_felrainoffire.blp:20|t%s開始施展|cFFFF0000|Hspell:88972|h[魔化火颶]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_felrainoffire.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:88972|h[Tormenta de Fuego vil]|h|r!' WHERE `ID`=48107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 알겠어. 근데 좀 이상하군.$B$B어떻게 자신의 거룻배를 잃어버릴 수 있지, $n 선장?', `MaleText_loc4`='嗯，我明白了。这可真奇怪。$B$B谁会把赛艇弄丢呢，长官？', `MaleText_loc5`='好，我知道了。真奇怪。$B$B誰把他們的小艇給弄丟了，隊長?', `MaleText_loc7`='Sí, ya lo entiendo. Es raro.$B$B¿Quién pierde su barco fluvial, capitán?' WHERE `ID`=48108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 거룻배를 통째로 잃어버릴 수 있나요, $n 님?', `FemaleText_loc4`='怎么会有人能把整条赛艇弄丢呢，$n？', `FemaleText_loc5`='到底要怎樣才有辦法把一整艘小艇給弄丟，$n?', `FemaleText_loc7`='¿Y exactamente cómo se pierde un barco fluvial entero, $n?' WHERE `ID`=48109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에선 모든 일이 순조롭게 진행되고 있네!', `MaleText_loc4`='这里的一切都完全是光明正大的！', `MaleText_loc5`='這裡每樣東西都越來越棒了!', `MaleText_loc7`='¡Por aquí todo va como la seda!' WHERE `ID`=48110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 이 말은 정말 하고 싶지 않았지만... 나도꽁꽁 극저온대포를 잃어버린 것 같습니다.', `MaleText_loc4`='呃……这可真难开口，可是……我恐怕把激冻冰弹给弄丢了。', `MaleText_loc5`='呃...我很不想講，但是...我好像把驚聲尖嘯冷凍火砲給弄丟了。', `MaleText_loc7`='Eh... Odio decirlo, pero... Creo que he perdido el Criocañón E-lado.', `FemaleText_loc1`='음... 이 말은 정말 하고 싶지 않았지만... 나도꽁꽁 극저온대포를 잃어버린 것 같아요.', `FemaleText_loc4`='呃……这可真难开口，可是……我恐怕把激冻冰弹给弄丢了。', `FemaleText_loc5`='呃...我很不想講，但是...我好像把驚聲尖嘯冷凍火砲給弄丟了。', `FemaleText_loc7`='Eh... Odio decirlo, pero... Creo que he perdido el Criocañón E-lado.' WHERE `ID`=48111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 뭐라고요? 아, 괜찮아요.$B$B여기 남는 걸 받으세요.', `MaleText_loc4`='等一下……什么？呃，没关系。$B$B这还有个备用的。', `MaleText_loc5`='慢著...什麼?嗯，好吧。$B$B這是我備用的。', `MaleText_loc7`='Espera... ¿qué? Eh, claro.$b$bAquí tienes el de repuesto.' WHERE `ID`=48112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 드워프는 우리 철천지원수요. 놈들이 죽거나, 우리가 죽거나 둘 중 하나지.', `MaleText_loc4`='蛮锤矮人是我们不共戴天的仇敌。不是他们死，就是我们亡。', `MaleText_loc5`='蠻錘矮人是我們的死敵。有他們就沒有我們。', `MaleText_loc7`='Los Martillo Salvaje son nuestros enemigos mortales. Es o ellos o nosotros.' WHERE `ID`=48113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 정말 당신이 생각한 것 중 가장 멍청하고... 말도 안 되고... 우스꽝스러운 계획이에요, 버드!', `FemaleText_loc4`='这是你所想出的最低能……最愚蠢……最可笑的计划，巴德！', `FemaleText_loc5`='霸德，這是你所想過最最白爛、最誇張、最荒謬的計畫!', `FemaleText_loc7`='¡Este es el plan más absurdo... lunático... y ridículo que se te ha ocurrido nunca, Budd!' WHERE `ID`=48114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래도 계획이라고는 이것뿐이니 어쩔 수 없겠죠.', `FemaleText_loc4`='可这恐怕是我们唯一可用的计划。', `FemaleText_loc5`='可是這好像是我們唯一的計畫了。', `FemaleText_loc7`='Pero supongo que es el único plan que tenemos.' WHERE `ID`=48115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네? 어딜 잡으라고요?', `FemaleText_loc4`='我还能怎么办呢？', `FemaleText_loc5`='我又抓到什麼了?', `FemaleText_loc7`='¿Qué decías que tengo que agarrar?' WHERE `ID`=48116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미련퉁이가 때려줄 거야!', `MaleText_loc4`='巨怪碾碎你！！', `MaleText_loc5`='歐弗打打!', `MaleText_loc7`='¡¡BOBO APLASTA!!' WHERE `ID`=48117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내... 자유를 찾았군. 충분한 보상을 해 주겠소, 친구들이여.', `MaleText_loc4`='终于……自由了。你们将获得十分可观的奖励，朋友们。', `MaleText_loc5`='終於...自由了。朋友，你們的獎賞一定會相當可觀。', `MaleText_loc7`='Libre... Por fin. Su recompensa será considerable, amigos.' WHERE `ID`=48118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 접근 방식은... 정도를 벗어나 있긴 하오. 하지만 화재 때문에 연기가 날 테니, 놈들에게는 우리 모습이 검은 윤곽으로만 보일 거요.', `MaleText_loc4`='你们的点子实在是……出人意料。但烈焰浓烟的遮掩下，我想他们只能看见你们的轮廓。', `MaleText_loc5`='你的方法相當...不正統。但是我想，火堆煙那麼大，他們應該只看得到你的側影而已。', `MaleText_loc7`='Tu enfoque es... poco ortodoxo. Por otra parte, supongo que con el humo del fuego solo verán sus siluetas.' WHERE `ID`=48119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 봐!!! 내가 맨타우로스가 되었다니!!!', `MaleText_loc4`='快看我！！！！我是猛犸人！！！', `MaleText_loc5`='你看!!!!我在扮人馬!!!', `MaleText_loc7`='¡MÍRAME! ¡SOY UN MANATAURO!' WHERE `ID`=48120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹부인은 아무도 탈 수 없어요!', `FemaleText_loc4`='没人能骑我的驼背淑女！', `FemaleText_loc5`='不准騎在小姐上!', `FemaleText_loc7`='¡Nadie navega en al Lady!' WHERE `ID`=48121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 소리는 그만둬요, 버드. 조용히 하라고요!!', `FemaleText_loc4`='闭上你的臭嘴，巴德。闭上！！', `FemaleText_loc5`='閉上你的笨嘴，霸德。閉嘴!!', `FemaleText_loc7`='Cierra tu maldita boca, Budd. ¡¡CIÉRRALA!!' WHERE `ID`=48122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='我们走！', `MaleText_loc5`='走吧!', `MaleText_loc7`='¡Vamos!' WHERE `ID`=48123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 족속을 상대할 때도 자신만만할 수 있을지 한번 보겠다. 공포의 군주여.', `MaleText_loc4`='让我们看看你在自己的同类面前能有多自信，恐惧魔王。', `MaleText_loc5`='讓我們瞧瞧你在對抗自己同族的時候是否也同樣這麼有自信，驚懼領主。', `MaleText_loc7`='Vamos a ver cómo te las apañas con alguien de tu propia especie, Señor del Terror.' WHERE `ID`=48124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거야!$b$b저 멍청이들이 나머지는 처리하겠지.$b$b기지로 돌아가자!', `MaleText_loc4`='好了！$b$b剩下的就交给那些小矮子去处理！$b$b我们回基地！', `MaleText_loc5`='就這樣!$b$b讓下人來清理剩下的。$b$b我們回基地去!', `MaleText_loc7`='¡Eso es!$b$bLos mequetrefes limpiarán el resto.$B$B¡Nosotros regresamos a la base!' WHERE `ID`=48125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이스크림이 왔어요! 달콤하고, 시원하고, 맛이 일품인 아이스크림이 왔어요!', `MaleText_loc4`='冰淇淋！来吃美味、冰爽、香甜、可口的冰淇淋啰！', `MaleText_loc5`='冰淇淋!快來吃冰冰涼涼、又甜又好吃的冰淇淋喔!', `MaleText_loc7`='¡Helado! ¡Helado sabroso, frío, dulce y delicioso!' WHERE `ID`=48126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리블스워프의 아이스크림 제국에 신제품이 나왔어요! 이제 모두 두 가지 맛!', `MaleText_loc4`='布里维普的冰淇淋帝国。现有两种口味！', `MaleText_loc5`='布里維普冰淇淋帝國!現在推出兩種口味!', `MaleText_loc7`='El Imperio de los Helados de Bridatuer. ¡Ahora ofrecemos DOS sabores!' WHERE `ID`=48127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리블스워프의 신제품 바삭바삭한 실리더스 아이스크림을 맛보세요. 진짜 실리더스가 통째로 들어 있어요. 재료를 속이면 삼대가 망합니다!', `MaleText_loc4`='试试布里维普的全新异种蝎嚼嚼乐冰淇淋吧。混合真正的异种蝎肉块。绝无人工仿制品！', `MaleText_loc5`='來試試布里維普的異種香脆冰淇淋。滿口真實飽滿的異種風味。僅此一家、別無分號!', `MaleText_loc7`='Prueba el nuevo helado Crocante Silítico de Bridatuer. Lleno a rebosar de auténtico silítido. ¡Rechaza imitaciones!' WHERE `ID`=48128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이스크림, 사탕, 풍선껌 팝니다!', `MaleText_loc4`='冰淇淋，糖果，泡泡糖！', `MaleText_loc5`='冰淇淋、糖果、泡泡糖!', `MaleText_loc7`='¡Helados, caramelos, chicles!' WHERE `ID`=48129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고가 아니면 만족하지 마십시오. 브리블스워프의 아이스크림을 드세요!', `MaleText_loc4`='只求最好，决不将就。认准布里维普牌！', `MaleText_loc5`='要吃就吃最好的，要吃就吃布里維普冰淇淋!', `MaleText_loc7`='Elige lo mejor para comer. ¡Bridatuer!' WHERE `ID`=48130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 놔두시오.', `MaleText_loc4`='别打扰我。', `MaleText_loc5`='不要吵我。', `MaleText_loc7`='Déjame en paz.' WHERE `ID`=48131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계절을 불문하고 대호평 중입니다. 브리블스워프의 바삭바삭 실리더스를 드셔 보세요!', `MaleText_loc4`='真是炎热得出奇啊。来尝尝布里维普的异种蝎嚼嚼乐冰淇淋吧！', `MaleText_loc5`='大熱天喔!來試試布里維普的異種香脆冰淇淋!', `MaleText_loc7`='Hace demasiado calor para esta estación. ¡Es hora de toma un Crocante Silítico de Bridatuer!' WHERE `ID`=48132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 살인 행각을 끝내기 위해 왔습니다.', `MaleText_loc4`='我来此终止你的杀戮行为。', `MaleText_loc5`='我要來終結你的殺戮。', `MaleText_loc7`='He venido para acabar con tus asesinatos.', `FemaleText_loc1`='당신의 살인 행각을 끝내기 위해 왔어요.', `FemaleText_loc4`='我来此终止你的杀戮行为。', `FemaleText_loc5`='我要來終結你的殺戮。', `FemaleText_loc7`='He venido para acabar con tus asesinatos.' WHERE `ID`=48133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브리블스워프의 아이스크림, 후식으로 딱이에요!', `MaleText_loc4`='布里维普牌冰淇淋，甜点的完美诠释！', `MaleText_loc5`='最好吃的都在布里維普!', `MaleText_loc7`='Bridatuer, ¡es mejor que beber!' WHERE `ID`=48134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애들은 브리블스워프의 아이스크림 한 입 먹겠다고 난리가 났습니다!', `MaleText_loc4`='孩子们全都无法抵挡布里维普牌冰淇淋的诱惑！', `MaleText_loc5`='全世界的小朋友都搶著要吃的布里維普冰淇淋!', `MaleText_loc7`='¡Todos los niños se mueren por el helado de Bridatuer!' WHERE `ID`=48135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 자여! 지금 무슨 짓을 하고 있는지 아시오?', `MaleText_loc4`='盲目的蠢货！你根本不知道自己在干什么！', `MaleText_loc5`='瞎了眼的笨蛋!你根本不曉得自己在幹嘛!', `MaleText_loc7`='¡Necio insensato! ¡No tienes ni idea de lo que estás haciendo!' WHERE `ID`=48136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 무기를 내려놓으시오!', `MaleText_loc4`='够了！快住手！', `MaleText_loc5`='夠了!住手!', `MaleText_loc7`='¡Basta! ¡Detén tu mano!' WHERE `ID`=48137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 비겁한 짓 배후에 누가 있는지 알아내겠어!$b$b그 후에는...', `MaleText_loc4`='我会查出谁才是这懦夫行为的背后主使！$b$b然后……', `MaleText_loc5`='我會揪出這個懦弱的舉動的背後主使者是誰!$b$b等我找到的時候....', `MaleText_loc7`='¡Descubrrriré quién está detrrrás de este acto cofarde!$b$bY cuando lo haga...' WHERE `ID`=48138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF진흙 농장에 문제가 생겼네...|r', `MaleText_loc4`='|cFFFFFFFF药渣农场遇到了麻烦……|r', `MaleText_loc5`='|cFFFFFFFF淤泥農場有麻煩了...|r', `MaleText_loc7`='|cFFFFFFFFHay problemas en Los Campos de Lodo...|r' WHERE `ID`=48139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 정말 네게 뭔가 말해야 할 때가 오면, 아마 달아나는 게 좋을 거다.', `MaleText_loc4`='要是真到了我有话对你说的时候，你应该转身就跑。', `MaleText_loc5`='要是萬一我真的有什麼話要跟你講，你應該快跑。', `MaleText_loc7`='Si alguna vez llega un día en el que tenga algo que decirte, echa a correr.' WHERE `ID`=48140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 정말 주변에 어떤 사람들이 있는지도 모르고 그냥 멍청하게 여기저기 들쑤시고 있구나, $r.', `MaleText_loc4`='你只是愚笨地在这里蹒跚而行，$r，全然不知自己已被什么样的军队包围。', `MaleText_loc5`='你愚蠢地在此擅闖，$r，完全不明白圍繞著你的是什麼力量。', `MaleText_loc7`='Andas por aquí dando traspiés, $r, ignorante de las fuerzas que te rodean.' WHERE `ID`=48141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 안에 두려움을 품고 있다, 필멸자여.$b$b난 느낄 수 있다.', `MaleText_loc4`='你心中充满了恐惧，凡人。$b$b我能感觉到。', `MaleText_loc5`='凡人，恐懼在你心中。$b$b我聞得出來。', `MaleText_loc7`='Hay miedo en ti, mortal.$b$bPuedo olerlo.' WHERE `ID`=48142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건을 밝히시오. 최대한 간단하게.', `MaleText_loc4`='有话就说吧。尽量简短些。', `MaleText_loc5`='說明你的來意。可以的話，請長話短說。', `MaleText_loc7`='Di lo que tengas que decir. Sé breve, si es posible.' WHERE `ID`=48143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파오리스 왕께서 당신에게 네페르세트의 활동에 대해 물어보라고 말씀하셨습니다.', `MaleText_loc4`='国王法奥瑞斯派我来了解尼斐塞特的情况。', `MaleText_loc5`='法歐瑞斯王派我來問你奈斐賽特的活動跡象。', `MaleText_loc7`='El rey Phaoris me ha enviado para preguntarte por la actividad de los Neferset.', `FemaleText_loc1`='파오리스 왕께서 당신에게 네페르세트의 활동에 대해 물어보라고 말씀하셨어요.', `FemaleText_loc4`='国王法奥瑞斯派我来了解尼斐塞特的情况。', `FemaleText_loc5`='法歐瑞斯王派我來問你奈斐賽特的活動跡象。', `FemaleText_loc7`='El rey Phaoris me ha enviado para preguntarte por la actividad de los Neferset.' WHERE `ID`=48144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 이방인에게 정보를 수집하라는 지시를 내리셨다고? 아무래도 자네가 바로 그... 뭐라고 하더라... $R? 그래, 나둔 왕자를 구출한 바로 그 $r인가보군.$B$B어쨌든, 여기 북쪽 끝에선 네페르세트의 악당들을 코빼기도 본 적이 없다. 하지만 그 밖의 다른 귀찮은 존재들은 많지.', `MaleText_loc4`='国王派了个陌生人来收集情报？我想你一定是那个……什么来着？$R？对，就是救出纳顿亲王的那个$r。$B$B不管怎样，我在这遥远的北部没察觉到任何尼斐塞特渣滓的活动迹象。不过在这儿倒有许多其它闲事需要处理。', `MaleText_loc5`='國王派個陌生人來為他收集情報?我想你必定就是那個...叫什麼來著?$R?對，那個救了納登親王的$r。$B$B好，言歸正題。在北邊這麼遠的地方我還沒有看到任何奈斐賽特的跡象。但是，我們依然有許多其他的問題要處理。', `MaleText_loc7`='¿El rey envía a $gun forastero:una forastera; para reunir información? Supongo que eres... ¿Cómo se decía? ¿$R? Sí, tú rescataste al príncipe Nadun.$b$bEn cualquier caso, no he visto ninguna señal de la escoria Neferset tan al norte. Pero no nos faltan molestias que resolver.' WHERE `ID`=48145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 이야기는 많이 들었소, $n. 우릴 도와주기 위해 왔소?', `MaleText_loc4`='我听说过你，$n。你是来帮助我们的吗？', `MaleText_loc5`='我有聽說過你，$n。你是來幫我們的嗎?', `MaleText_loc7`='He oído hablar de ti, $n. ¿Has venido a ayudarnos?' WHERE `ID`=48146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 도와드릴 수 있을지도 모릅니다. 네페르세트가 이 일을 꾸몄습니까?', `MaleText_loc4`='我也许能帮上忙。尼斐塞特和此事有关吗？', `MaleText_loc5`='我也許能幫得上忙。這些事情是奈斐賽特在搞鬼的嗎?', `MaleText_loc7`='Es posible que pueda ayudar. ¿Están los Neferset detrás de esto?', `FemaleText_loc1`='제가 도와드릴 수 있을지도 몰라요. 네페르세트가 이 일을 꾸몄나요?', `FemaleText_loc4`='我也许能帮上忙。尼斐塞特和此事有关吗？', `FemaleText_loc5`='我也許能幫得上忙。這些事情是奈斐賽特在搞鬼的嗎?', `FemaleText_loc7`='Es posible que pueda ayudar. ¿Están los Neferset detrás de esto?' WHERE `ID`=48147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 이건 평범한 사막유랑단 약탈자들 짓이오.$B$B놈들이 서쪽에서 더 조직화된 단체를 꾸리고 있다는 소문이 돌더군. 놈들은 정말 야만적인 폭력을 저지르고 있소.', `MaleText_loc4`='不。这就是废土强盗的杰作。$B$B据说他们加入了西边一个组织更为严密的团伙。他们的暴力行径野蛮至极。', `MaleText_loc5`='不。這只是普通的廢土強盜惹出的麻煩。$B$B據說他們打算要加入西方一個更有組織的團體。而且，他們非常的粗暴殘忍。', `MaleText_loc7`='No. Esto es obra de bandidos Vagayermos comunes.$b$bSe rumorea que se van a unir a un grupo más militarizado al oeste. Su violencia es barbárica.' WHERE `ID`=48148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 여기 도착했다는 말을 전해 들었습니다. 정말 이상한 존재로군요.$B$B저와 잠깐 이야기를 나누시겠습니까?', `MaleText_loc4`='我听说你在城里。你可真是个奇怪的家伙。$B$B想和我谈谈？', `MaleText_loc5`='我聽說了你在城裡的事情。你真是個奇異的生物。$B$B你有事要找我?', `MaleText_loc7`='He oído que andabas por aquí. Qué criatura más extraña eres.$b$b¿Deseas hablar conmigo?' WHERE `ID`=48149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 최근 네페르세트의 활동에 대해 듣고 싶어하십니다.', `MaleText_loc4`='国王想了解尼斐塞特近来的动态。', `MaleText_loc5`='國王希望能得知最近是否有奈斐賽特活動的消息。', `MaleText_loc7`='El rey desea información sobre las actividades recientes de los Neferset.', `FemaleText_loc1`='왕께서 최근 네페르세트의 활동에 대해 듣고 싶어하세요.', `FemaleText_loc4`='国王想了解尼斐塞特近来的动态。', `FemaleText_loc5`='國王希望能得知最近是否有奈斐賽特活動的消息。', `FemaleText_loc7`='El rey desea información sobre las actividades recientes de los Neferset.' WHERE `ID`=48150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네페르세트는 요즘 움직이지 않고 있습니다. 하지만 최근 오르시스가 사상 최악의 거대한 모래 폭풍에 의해 피해를 입었다는 보고를 받았습니다.$B$B제가 직접 이 소식을 왕께 보고할 생각이었습니다만, 당신이 전해주실 수도 있겠군요.', `MaleText_loc4`='不，尼斐塞特没什么行动。可我刚刚收到消息，一场前所未见的强大沙尘暴袭击了奥西斯城。$B$B我正准备亲自将消息带给国王，看来你可以帮忙转达一下。', `MaleText_loc5`='沒有。沒聽到什麼奈斐賽特的消息。不過，我倒是剛聽說了奧爾希斯城遭到有史以來最大的沙塵暴襲擊。$B$B我正準備要派人去通報國王，但也許你可以幫我轉達這消息。', `MaleText_loc7`='No, no ha habido movimientos de los Neferset, pero acabo de recibir noticias de que la ciudad de Orsis se ve afectada por la mayor tormenta de arena jamás vista.$b$bEstaba a punto de enviar un mensaje al rey, pero quizá tú le puedas transmitir la información.' WHERE `ID`=48151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 축구탄 제복을 다시 입게 해주시겠습니까?', `MaleText_loc4`='格瑞里，你能让我重新穿上足球炸弹制服吗？', `MaleText_loc5`='格里利，能幫忙再把我弄進足球炸彈戰鬥裝嗎?', `MaleText_loc7`='Greely, ¿puedes volver a meterme en ese uniforme de bombalón?', `FemaleText_loc1`='그릴리, 축구탄 제복을 다시 입게 해주시겠어요?', `FemaleText_loc4`='格瑞里，你能让我重新穿上足球炸弹制服吗？', `FemaleText_loc5`='格里利，能幫忙再把我弄進足球炸彈戰鬥裝嗎?', `FemaleText_loc7`='Greely, ¿puedes volver a meterme en ese uniforme de bombalón?' WHERE `ID`=48152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지의 수호자, 그리고 그의 아이들이 언젠가는 죄악에서 구원되리란 희망을 오랫동안 버리지 않았습니다. 하지만, 어느 순간 우리도 깨닫고, 인정할 수밖에 없었지요. 검은용들이 이 세상에 행한 파괴는 어떤 속죄로도 보상할 수 없다는 사실을 말입니다.$B$B그래서 어쩔 수 없이 이 일에 끼어들게 되었습니다.', `FemaleText_loc4`='长久以来，我们都仍希望能挽救大地看守者和他的子嗣。在某些时候，我们必须要明智地意识到，任何程度的弥补都抵不过这些巨龙对这个世界所造成的伤害。$B$B在某些时候，我们被迫要插手。', `FemaleText_loc5`='原本我們還一直期待，總有辦法能夠挽救大地看守者和他的後裔。但有時候，我們必須要有足夠的智慧認清事實，這群惡龍對世界所造成的傷害與毀滅確實早已罪不可赦。$B$B有時候，我們必得現身干預。', `FemaleText_loc7`='Hace mucho tiempo que albergamos la esperanza de redimir al Guardián de la Tierra y a sus hijos. Tarde o temprano debemos tener la sabiduría necesaria para darnos cuenta de que no existe redención capaz de expiar la destrucción que esos dragones están extendiendo por el mundo.$b$bTarde o temprano tendremos que intervenir.' WHERE `ID`=48153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼용을 따라 흑요석 둥지에 들어가야 합니다.', `MaleText_loc4`='跟随幼龙进入黑曜石巢穴。', `MaleText_loc5`='跟著黑曜幼龍進入黑曜龍穴。', `MaleText_loc7`='Sigue a las crías por la Guarida Obsidiana.', `FemaleText_loc1`='새끼용을 따라 흑요석 둥지에 들어가야 합니다.', `FemaleText_loc4`='跟随幼龙进入黑曜石巢穴。', `FemaleText_loc5`='跟著黑曜幼龍進入黑曜龍穴。', `FemaleText_loc7`='Sigue a las crías por la Guarida Obsidiana.' WHERE `ID`=48154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 출발하시지요.', `MaleText_loc4`='好吧，我们走。', `MaleText_loc5`='好，走吧。', `MaleText_loc7`='Muy bien, vamos allá.', `FemaleText_loc1`='좋아요. 출발하세요.', `FemaleText_loc4`='好吧，我们走。', `FemaleText_loc5`='好，走吧。', `FemaleText_loc7`='Muy bien, vamos allá.' WHERE `ID`=48155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라와! 할 일이 아주 많아!', `MaleText_loc4`='跟上！还有许多事情要做！', `MaleText_loc5`='跟著我!還有很多事情要做!', `MaleText_loc7`='¡Sígueme! ¡Hay mucho por hacerrr!' WHERE `ID`=48156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장! 이건 폭동이야!', `MaleText_loc4`='混蛋！太过分了！', `MaleText_loc5`='噢!真是太過份了!', `MaleText_loc7`='¡Auch! ¡Esto es un escándalo!' WHERE `ID`=48157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 도적놈들을 데려다가 역사적인 일을 할 수 있게 해줬더니, 이런 식으로 은혜를 갚는다고?', `MaleText_loc4`='带了这么一群蹩脚的强盗来，你能得到什么？他们只不过是历史笑柄！', `MaleText_loc5`='你找了一群乖戾的強盜來，帶領他們闖出一番會名留千史的事業，這就是他們對你的回報?', `MaleText_loc7`='Tomas a un grrrupo de bandidos miserrrables y los convierrrtes en parte de algo histórrrico ¿y así es como te lo agradecen?' WHERE `ID`=48158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신의 배후에 어떤 놈이 있는지 알아내고 말 테다. 너, 나를 도와서 이번 일을 해줘야겠어!', `MaleText_loc4`='我一定会查明，这背叛的幕后主使究竟是谁，而你要帮助我！', `MaleText_loc5`='我一定要把背後搞鬼的人給揪出來，而且你絕對要幫我!', `MaleText_loc7`='Voy a descubrrrir quién está detrás de esta traición, ¡y tú vas a ayudarrrme!' WHERE `ID`=48159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일은 너나 내가 감당할 수 없는 일이야... 어느 누구도 감당할 수 없다고!', `MaleText_loc4`='这件事要比你我重要得多……比任何人想象中都重要得多！', `MaleText_loc5`='這件事情比你比我都還重要...比任何人所知道的都還重要!', `MaleText_loc7`='Este trrrabajo es más importante que tú o yo... ¡Más importante que cualquierrra!' WHERE `ID`=48160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어설픈 암살자들은 지금 누굴 상대하는지 전혀 모르고 있어!', `MaleText_loc4`='这群羽翼未丰的刺客不知道他们是在和谁打交道！', `MaleText_loc5`='這些半吊子的刺客根本不曉得他們惹到了什麼!', `MaleText_loc7`='¡Esos aspirrrantes a asesino no safen con quién se están jugando los cuarrrtos!' WHERE `ID`=48161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 곧, 놈들도 알게 될 거야... 그리고 그때는 두려움에 떨 테지!', `MaleText_loc4`='他们很快就会明白……而那时，他们将在恐惧中战栗！', `MaleText_loc5`='不用多久，他們就會知道...到時候，他們就會嚇到屁滾尿流!', `MaleText_loc7`='Pronto aprrrenderán... Y cuando lo hagan, ¡temblarrrán!' WHERE `ID`=48162;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 여기까지 오지 말았어야 했는데!', `FemaleText_loc4`='喔……我真希望我没到这儿来！', `FemaleText_loc5`='噢...我真希望我從沒來過這地方!', `FemaleText_loc7`='Oh... ¡Ojalá nunca hubiera venido a este lugar!' WHERE `ID`=48163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌다 이런 일에 휘말리게 되었을까요?!
', `MaleText_loc4`='我是怎么卷进来的？！', `MaleText_loc5`='我怎麼會牽扯上這種事情啊?!', `MaleText_loc7`='¡¿Cómo me he metido en esto?!' WHERE `ID`=48164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 들뜬 나머지 눈에 뵈는 게 없었습니다.$b$b이런 일이 생기리라는 걸 진작 알았어야 하는데...', `MaleText_loc4`='我被兴奋冲昏了头。$b$b我早该感觉到的……', `MaleText_loc5`='我被一時的興奮給蒙蔽了。$b$b我早就該看出來了...', `MaleText_loc7`='Me cegó la emoción.$b$bDebería haberlo visto venir hace siglos...' WHERE `ID`=48165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생 모은 재산이... 사라졌습니다.$b$b이제 아무 희망도 남아 있지 않아요.', `MaleText_loc4`='我一生的财富都……没了。$b$b我的生活已经毫无希望了。', `MaleText_loc5`='我畢生的積蓄...全沒了。$b$b我的人生是黑白的了。', `MaleText_loc7`='La fortuna de mi vida... Desaparecida.$b$bYa no me queda esperanza.' WHERE `ID`=48166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 견딜 수 없어요.$b$b내게 용기가 조금만 더 있었더라면... <훌쩍>', `FemaleText_loc4`='这太难以承受了。$b$b真希望我有勇气……<啜泣>。', `FemaleText_loc5`='我沒有辦法接受這樣的事情。$b$b真希望我當時有勇氣... <哭泣>。', `FemaleText_loc7`='Todo esto es insoportable.$b$bOjalá tuviera el valor para... <sollozo>.' WHERE `ID`=48167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 정답을 모두 알고 있으리라고 생각했어요.$b$b난... 그러길 바랐죠.$b$b그는 자기주장과는 전혀 다른 사람이었어요.$b$b내가 바보였지요.', `MaleText_loc4`='我以为他所做的一切都是正确的。$b$b我……满怀希望。$b$b但他完全不是他自我标榜的那种人。$b$b我真是个傻瓜。', `MaleText_loc5`='我還以為他什麼答案都有了。$b$b我...那麼的期待。$b$b結果，他根本不是他自己講的那個樣子。$b$b我真是太笨了。', `MaleText_loc7`='Creí que tenía todas las respuestas.$b$bTuve... esperanza.$b$bNo es para nada como se pintaba.$b$bHe sido un tonto.' WHERE `ID`=48168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해마가 참을성 있게 떠 있습니다.', `MaleText_loc4`='海马稳稳的漂浮着。', `MaleText_loc5`='海馬耐心地漂著。', `MaleText_loc7`='El caballito de mar flota pacientemente.' WHERE `ID`=48169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈 수 있는 곳을 보여주십시오.', `MaleText_loc4`='让我看看我能去哪儿。', `MaleText_loc5`='讓我看看我可以去哪裡。', `MaleText_loc7`='Enséñame a dónde puedo ir.', `FemaleText_loc1`='갈 수 있는 곳을 보여주세요.', `FemaleText_loc4`='让我看看我能去哪儿。', `FemaleText_loc5`='讓我看看我可以去哪裡。', `FemaleText_loc7`='Enséñame a dónde puedo ir.' WHERE `ID`=48170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 네스피라에 가야 합니다.', `MaleText_loc4`='我要前往奈瑟匹拉。', `MaleText_loc5`='我要去奈斯畢拉。', `MaleText_loc7`='Tengo que ir a Nespirah.', `FemaleText_loc1`='저는 네스피라에 가야 해요.', `FemaleText_loc4`='我要前往奈瑟匹拉。', `FemaleText_loc5`='我要去奈斯畢拉。', `FemaleText_loc7`='Tengo que ir a Nespirah.' WHERE `ID`=48171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삽을 사용해 인간 묘목의 머리를 흙 속에 때려 넣습니다.|TInterface\\Icons\\INV_MISC_SHOVEL_01.BLP:24|t$B$B또는$B$B[마우스 오른쪽 클릭] 인간 묘목을 흙 속에서 구해냅니다.|Tinterface\\Cursor\\SKINALLIANCE.BLP:24|t$B$B옳은 일을 하십시오.', `MaleText_loc4`='试着用铲子来清除食人花苗。|TInterface\\Icons\\INV_MISC_SHOVEL_01.BLP:24|t$B$B或者$B$B[右键点击]食人花苗将它们拔出来|TInterface\\Cursor\\SKINALLIANCE.BLP:24|t$B$B作出正确的选择。', `MaleText_loc5`='使用鏟子敲擊人類幼苗的頭。|TInterface\\Icons\\INV_MISC_SHOVEL_01.BLP:24|t$B$B或者$B$B[右鍵點擊]人類幼苗，將他們從土裡救出來。|TInterface\\Cursor\\SKINALLIANCE.BLP:24|t$B$B做正確的事情。', `MaleText_loc7`='Utiliza la pala para aplastar las cabezas de los esquejes humanos.|TInterfaceIconsINV_MISC_SHOVEL_01.BLP:24|t$B$BO BIEN$B$BHaz [clic derecho] en el esqueje humano para liberarlo de la tierra.|TInterface\Cursor\SKINALLIANCE.BLP:24|t$B$BHaz lo correcto.' WHERE `ID`=48172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어쩌면 당신은 사악한 자가 아닐지도...', `MaleText_loc4`='也……也许你也没那么坏……', `MaleText_loc5`='看來...你並沒有那麼糟糕...', `MaleText_loc7`='A... A lo mejor no sois todos malos, después de todo...', `FemaleText_loc1`='어... 어쩌면 당신은 사악한 자가 아닐지도...', `FemaleText_loc4`='也……也许你也没那么坏……', `FemaleText_loc5`='看來...你並沒有那麼糟糕...', `FemaleText_loc7`='A... A lo mejor no sois todos malos, después de todo...' WHERE `ID`=48173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨을 구해주셔서 감사합니다. 큰 신세를 졌군요.', `MaleText_loc4`='谢谢你救了我。我欠你份人情。', `MaleText_loc5`='謝謝你救我一命。我欠你一份人情。', `MaleText_loc7`='Gracias por salvarme la vida. Tengo una deuda de gratitud contigo.', `FemaleText_loc1`='제 목숨을 구해주셔서 감사합니다. 큰 신세를 졌군요.', `FemaleText_loc4`='谢谢你救了我。我欠你份人情。', `FemaleText_loc5`='謝謝你救我一命。我欠你一份人情。', `FemaleText_loc7`='Gracias por salvarme la vida. Tengo una deuda de gratitud contigo.' WHERE `ID`=48174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜는 평생 잊지 않겠습니다, $r님.', `MaleText_loc4`='我会记得你的恩情，$r。', `MaleText_loc5`='我不會輕易忘記這份恩情，$r。', `MaleText_loc7`='No olvidaré esta amabilidad fácilmente, $r.', `FemaleText_loc1`='이 은혜는 평생 잊지 않겠어요, $r님.', `FemaleText_loc4`='我会记得你的恩情，$r。', `FemaleText_loc5`='我不會輕易忘記這份恩情，$r。', `FemaleText_loc7`='No olvidaré esta amabilidad fácilmente, $r.' WHERE `ID`=48175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노... 놈은 우릴 곡물처럼 땅에 심어 버렸습니다! 스틸워터는 미쳤어요! 도망칠 수 있을 때 얼른 도망치십시오!', `MaleText_loc4`='这……他们把我们像庄稼一样种到土里！斯蒂沃特简直疯了！趁还来得及，赶紧离开这儿！', `MaleText_loc5`='它...它們把人當植物一樣種進土裡!斯蒂沃特瘋了!趁還活命的時候趕快逃走!', `MaleText_loc7`='Él... Nos han plantado en la tierra como si fuéramos semillas! ¡Aguaserena está loco! ¡Vete de aquí mientras puedas!', `FemaleText_loc1`='노... 놈은 우릴 곡물처럼 땅에 심어 버렸어요! 스틸워터는 미쳤어요! 도망칠 수 있을 때 얼른 도망치세요!', `FemaleText_loc4`='这……他们把我们像庄稼一样种到土里！斯蒂沃特简直疯了！趁还来得及，赶紧离开这儿！', `FemaleText_loc5`='它...它們把人當植物一樣種進土裡!斯蒂沃特瘋了!趁還活命的時候趕快逃走!', `FemaleText_loc7`='Él... Nos han plantado en la tierra como si fuéramos semillas! ¡Aguaserena está loco! ¡Vete de aquí mientras puedas!' WHERE `ID`=48176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 모두 죽였습니다! 모두 죽였다고요!', `MaleText_loc4`='他杀了所有人！所有人！', `MaleText_loc5`='他把大家都殺光了!殺光了!', `MaleText_loc7`='¡Los ha matado a todos! ¡A TODOS!', `FemaleText_loc1`='놈이 모두 죽였어요! 모두 죽였다고요!', `FemaleText_loc4`='他杀了所有人！所有人！', `FemaleText_loc5`='他把大家都殺光了!殺光了!', `FemaleText_loc7`='¡Los ha matado a todos! ¡A TODOS!' WHERE `ID`=48177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 당신이 비료밭에 머리만 내놓고 파묻히신다면, 반드시 도와드리겠습니다.', `MaleText_loc4`='要是你被埋在没颈的粪池里，我肯定会拉你一把。', `MaleText_loc5`='要是你也被埋進施了糞肥的田裡，我一定會去救你的。', `MaleText_loc7`='Si alguna vez te encuentras $gmetido:metida; hasta el cuello en un campo de heces y orina, me aseguraré de echarte una mano.', `FemaleText_loc1`='만약 당신이 비료밭에 머리만 내놓고 파묻히신다면, 반드시 도와드리겠어요.', `FemaleText_loc4`='要是你被埋在没颈的粪池里，我肯定会拉你一把。', `FemaleText_loc5`='要是你也被埋進施了糞肥的田裡，我一定會去救你的。', `FemaleText_loc7`='Si alguna vez te encuentras $gmetido:metida; hasta el cuello en un campo de heces y orina, me aseguraré de echarte una mano.' WHERE `ID`=48178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 신선한 고기다...', `MaleText_loc4`='啊，新鲜的肉！', `MaleText_loc5`='啊...新鮮的肉!', `MaleText_loc7`='¡Ah, carne fresca!' WHERE `ID`=48179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 문서로 연루된 트롤 첩자 몇 명이 밝혀졌습니다. 그들은 이미 죽은 목숨이나 마찬가지입니다. 포상금을 받으십시오. 그리고 현명하게 쓰시기 바랍니다. 전부 스톰윈드 주민의 귀한 세금에서 나온 돈이니까요.', `MaleText_loc4`='这些文件包含了几个巨魔间谍的信息。他们的脑袋一定保不住了。拿上你的奖金合理使用吧，这可都是暴风城纳税人的钱。', `MaleText_loc5`='這幾份文件可以追查出好幾個食人妖間諜。他們準備要人頭落地了。收下你的報酬，省著點花—這都是暴風城百姓的稅金。', `MaleText_loc7`='Estos documentos implican a varios espías trols. Considéralos ejecutados. Toma tu compensación y gástala con prudencia, se les ha sustraído a los ciudadanos de Ventormenta.' WHERE `ID`=48180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 문서로 연루된 오크 첩자 몇 명이 밝혀졌습니다. 이 반역 행위를 처리하기 위해 최고의 암살자들이 파견될 것입니다. 포상금을 받고 현명하게 쓰시기 바랍니다. 전부 스톰윈드 주민의 귀한 세금에서 나온 돈이니까요.', `MaleText_loc4`='这些文件包含了几个兽人间谍的信息。我们最优秀的杀手将会被派去终结他们的背叛行径。拿上你的奖金合理使用吧，这可都是暴风城纳税人的钱。', `MaleText_loc5`='這幾份文件可以追查出好幾個獸人間諜。我們會派出最頂尖的刺客去收拾他們。收下你的報酬，省著點花—這都是暴風城百姓的稅金。', `MaleText_loc7`='Estos documentos implican a varios espías orcos. Enviaremos a nuestros mejores asesinos por esta traición. Toma tu compensación y gástala con prudencia, se les ha sustraído a los ciudadanos de Ventormenta.' WHERE `ID`=48181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정보를 주시다니 영광입니다. 마침내 도시 내부의 첩자를 발견한 것 같군요... 이 부랑자는 우리가 조만간 처형하겠습니다. 포상금을 받으십시오. 잘해주셨습니다!', `MaleText_loc4`='由你为我们送来这份消息可真是荣幸。看来我们终于找到了那个潜伏在城市中的间谍……一个流浪汉。他很快就会被处决。请拿上你的奖励，干得好！', `MaleText_loc5`='謝謝你為我們帶來這寶貴的情報。看來我們終於把城裡的間諜給揪出來了...某個馬上就會被我們抓去砍頭的遊民。你做得非常好!去領取你的獎賞吧。', `MaleText_loc7`='Nos honras al entregarnos esta información. Parece que por fin hemos encontrado al espía de la ciudad... Un hombre sin techo al que ejecutaremos en breve. Toma tu recompensa, ¡has hecho bien!' WHERE `ID`=48182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 맙소사... 누가 제 빵을 먹고 배탈이 났다고요? 어떻게 그런 일이? 부탁입니다. 제 벌이는 변변찮지만, 그래도 도울 수 있었으면 좋겠습니다.', `MaleText_loc4`='喔我的天……居然有人因吃我的面包而生病了？这怎么可能？拜托了，希望我这微薄的收入能解决这困局。', `MaleText_loc5`='天啊...我的麵包害人家吃了不舒服?這怎麼可能?求求你，希望我微薄的收入能夠彌補得了。', `MaleText_loc7`='Oh, vaya... ¿Alguien se ha puesto enfermo por culpa de mi pan? ¿Cómo es posible? Espero que mis míseras ganancias puedan ayudar.' WHERE `ID`=48183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 모든 물품은 상세한 검사와 정확한 배송 과정을 거칩니다! 국왕 폐하의 서명이 없었다면 한 푼도 못 받았을 줄 아십시오.', `MaleText_loc4`='我们所有的物品都经过了仔细的检查，运送环节也十分严谨！如果这不是由国王本人签署的，你一分钱也别想拿到。', `MaleText_loc5`='我們所有的東西都有經過仔細的檢驗，而且出貨時間毫無延誤!要是沒有國王本人的簽名，你連一毛都拿不到。', `MaleText_loc7`='¡Toda nuestra mercancía se inspecciona con cuidado y se empaqueta con precisión! Si esto no llevara la firma del mismísimo Rey no verías ni una moneda.' WHERE `ID`=48184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 토할 거 같아요. 어떻게 제가 고객님의 귀를 자르고도 몰랐을까요? 이 돈을 가져가서 의사에게 다시 붙이라고 하세요.', `MaleText_loc4`='喔……我想我要吐了。我怎么可能把人家的耳朵切下来却浑然不觉？快拿上这点钱找个医生，把耳朵接上去吧。', `MaleText_loc5`='噢...我好像快不行了。我怎麼可能會完全沒發現，自己竟然割掉了人家的耳朵?拜託請收下這筆錢，找個醫生把它接回去。', `MaleText_loc7`='Oh... Creo que voy a vomitar. ¿Cómo podría haberle cortado la oreja a alguien sin darme cuenta? Llévale este dinero a un sanador para que la cosa.' WHERE `ID`=48185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누군가 말에서 떨어질 때마다 제가 책임을 질 순 없습니다. 어떻게 국왕 폐하의 서명을 받았는지는 모르겠지만, 돈을 가져가시고 다시는 제 말들에 책임을 뒤집어씌우지 마십시오!', `FemaleText_loc4`='我可不能每次都为别人从他们的坐骑上摔落而负责。我不知你是怎么盖到官方印章的，但请你拿上酬劳走开吧，别再来质疑我的马匹了！', `FemaleText_loc5`='不能只要有人從馬背上摔下來就要找我負責吧!我不知道你是怎樣弄到這個官印的，把錢拿走，不要再懷疑我的馬了!', `FemaleText_loc7`='No pueden hacerme responsable cada vez que alguien se cae de su montura. No sé cómo has conseguido el sello oficial, ¡pero toma tu pago y no vuelvas a cuestionar mis caballos!' WHERE `ID`=48186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험하게 노시는군요... 일단 돈은 가져가십시오. 하지만 제가 지켜 보고 있다는 사실은 잊지 마십시오.
', `MaleText_loc4`='你在玩儿火……这是给你的钱，但请记住，我一直在监视着你。', `MaleText_loc5`='你玩的可是非常危險的遊戲...暫且拿走你的錢，但是我會隨時盯著你。', `MaleText_loc7`='Estás jugando con fuego... Por ahora quédate con tu oro, pero recuerda que te estoy observando.' WHERE `ID`=48187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 전에 비슷한 돈을 낸 것 같은데...
', `MaleText_loc4`='我发誓我刚刚才付过一次这样的罚金……', `MaleText_loc5`='我發誓我才剛交過一筆跟這一樣的罰款...', `MaleText_loc7`='Juraría que acabo de pagar una multa como esta...' WHERE `ID`=48188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 돈 자루가 우편물 안에 있을 겁니다! 근무 중인데 사람을 보내 가져가려 하다니 모욕적이군요.', `MaleText_loc4`='我会把她那几个金币寄给她的！居然在我忙碌的时候派人来取钱，这太无礼了。', `MaleText_loc5`='她那袋金幣應該已經在郵件裡了!實在是欺人太甚，她竟然在我工作的時候派人來跟我拿。', `MaleText_loc7`='¡Su bolsa de oro está en el buzón! Es un insulto que envíe a alguien a cobrarme mientras trabajo.' WHERE `ID`=48189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에일 맥주 속에서 쥐가 나왔단 소린 들어봤지만, 빵 속에서 나왔단 소린 처음 들었습니다. 부... 부탁이니 원하는 대로 가져가시고 소문만 내지 말아주십시오.', `MaleText_loc4`='我听说过有老鼠被卡在啤酒瓶里，可从没听过夹在面包里。求——求——求你了，要什么尽管拿去，别和任何人提起这件事。', `MaleText_loc5`='我聽說過酒瓶裡有老鼠的事情，但是從來沒聽說麵包裡也會有老鼠的。拜—拜託，你要拿什麼都可以，就是不要告訴別人。', `MaleText_loc7`='Ya había oído hablar de ratones atrapados en botellas de cerveza, pero nunca en pan. T-te lo ruego, cógelo todo y no se lo cuentes a nadie.' WHERE `ID`=48190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 자른 돈은 환불해주지 않는 게 원칙이지만, 당신께 끔찍한 일을 저질렀다는 점은 인정할 수밖에 없네요. 사과할게요.', `MaleText_loc4`='我很少会在给人理发后把钱退回去，可我必须承认——你的发型真是个败笔。我道歉。', `MaleText_loc5`='我幫人做頭髮通常是不接受退款的，但是我承認，我確實沒有把你剪得很好。抱歉。', `MaleText_loc7`='No suelo admitir devoluciones en los cortes de pelo, pero admito que con el tuyo hice un estropicio. Perdón.' WHERE `ID`=48191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그날 밤에 당신께 조랑말을 약속했다니 제가 많이 취했었나 봅니다. 이 돈을 가져가시고 기분 푸세요, 네?', `FemaleText_loc4`='我那晚肯定是喝醉了，才会答应给你一匹小马。拿着你的钱，别难过，好吗？', `FemaleText_loc5`='那天晚上我答應要給你一匹小馬的時候，我肯定是喝得相當醉了。拿走你的錢，不傷感情，好嗎?', `FemaleText_loc7`='Debía de estar bastante achispada la noche que te prometí un poni. Coge tu dinero y quedamos en paz, ¿vale?' WHERE `ID`=48192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 이런 건 다 우편으로 처리하는데...', `MaleText_loc4`='我们平常都是通过邮寄的方式解决……', `MaleText_loc5`='這種事情我們通常都是透過郵件在處理的...', `MaleText_loc7`='Normalmente solemos hacerlo por correo...' WHERE `ID`=48193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와. 우리가 이런 걸 팔고 있었는지도 몰랐습니다.', `MaleText_loc4`='哇哦。我甚至都没意识到我们居然卖出过这种东西。', `MaleText_loc5`='哇，我根本不知道我們有在賣這種東西。', `MaleText_loc7`='Vaya. Ni siquiera sabía que vendiéramos este tipo de cosas.' WHERE `ID`=48194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 모두 나를 따라 어... 자연스럽게 행동하세요.', `MaleText_loc4`='好吧大家。跟我来，而且，呃……自然点儿。', `MaleText_loc5`='好了，大家注意。跟著我走，然後，呃...表現自然一點就對了。', `MaleText_loc7`='Atención todo el mundo. Síganme y... eh... Actúen con naturalidad.' WHERE `ID`=48195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 탁자엔 관심이 가는 게 없습니다.', `MaleText_loc4`='桌上没什么令你感兴趣的东西。', `MaleText_loc5`='桌上沒什麼值得注意的東西。', `MaleText_loc7`='No hay nada de interés en la mesa.' WHERE `ID`=48196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 보급품 더미가 탁자에 있습니다. 늑대 가죽부터 시작하기로 마음먹습니다.', `MaleText_loc4`='桌上放着几堆货物。你决定先从座狼皮开始。', `MaleText_loc5`='桌上有幾堆補給品。你決定先拿座狼皮。', `MaleText_loc7`='Hay varios montones de suministros sobre la mesa. Decides empezar con los pellejos de huargo.' WHERE `ID`=48197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일전에 수집한 늑대 가죽 무더기가 보입니다. 이 가죽 무더기는 복장 대부분을 구성하는 재료로 쓰일 겁니다.', `MaleText_loc4`='你看到了自己早先收集到的那堆座狼皮。这些将被用来为你做衣服。', `MaleText_loc5`='你看到了幾疊你之前收集的座狼皮。這些皮革可以拿來縫製你要的偽裝。', `MaleText_loc7`='Ves los montones de pellejos de huargo que has recogido antes. Se usarán para el grueso de tu disfraz.' WHERE `ID`=48198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넘겨다보니, 당신이 용암 구덩이에서 모은 흑요석 섞인 진흙이 보입니다. 이 진흙은 당신 변장을 물들이는 데 쓰일 겁니다.', `MaleText_loc4`='往旁边看去，映入眼帘的是你从熔岩层收集来的黑曜斑点软泥。这些将被用来为你的伪装服染色。', `MaleText_loc5`='仔細翻找之後，你看到了之前從熔岩床收集而來的黑曜石粒泥。這可以用來染製你所需要的偽裝。', `MaleText_loc7`='Al pasear la vista, ves el barro con motas de obsidiana que recogiste del lecho de lava. Se usará para teñir tu disfraz.' WHERE `ID`=48199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 변장을 한데 꿰매는 데 쓰일 약간의 실이 보입니다.', `MaleText_loc4`='最后，你看到了一些线团，将被用来缝制伪装服。', `MaleText_loc5`='最後，你終於看到了幾卷縫線，可以拿回去把偽裝縫起來。', `MaleText_loc7`='Por último, ves algo de hilo, que se utilizará para coser todo el disfraz.' WHERE `ID`=48200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 물품을 모았습니다. 물품을 조합하려면 테랄론 다이어니들에게 가져가십시오.', `MaleText_loc4`='你已经集齐了物品。把它们带给萨拉隆·巨钉来完成组合。', `MaleText_loc5`='你已經收集好材料了。帶去給賽拉隆·恐針組合起來。', `MaleText_loc7`='Has reunido tus suministros. Llévaselos a Thelaron Malaguja para montarlos.' WHERE `ID`=48201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 한 장 가져가기', `MaleText_loc4`='拿一张皮。', `MaleText_loc5`='拿走一張皮。', `MaleText_loc7`='Coge un pellejo.', `FemaleText_loc1`='가죽 한 장 가져가기', `FemaleText_loc4`='拿一张皮。', `FemaleText_loc5`='拿走一張皮。', `FemaleText_loc7`='Coge un pellejo.' WHERE `ID`=48202;
