UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 네 장 가져가기', `MaleText_loc4`='拿四张皮。', `MaleText_loc5`='拿走四張皮。', `MaleText_loc7`='Coge cuatro pellejos.', `FemaleText_loc1`='가죽 네 장 가져가기', `FemaleText_loc4`='拿四张皮。', `FemaleText_loc5`='拿走四張皮。', `FemaleText_loc7`='Coge cuatro pellejos.' WHERE `ID`=48205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 한 움큼 가져가기', `MaleText_loc4`='拿一捧软泥。', `MaleText_loc5`='拿走一把泥巴。', `MaleText_loc7`='Coge un puñado de barro.', `FemaleText_loc1`='진흙 한 움큼 가져가기', `FemaleText_loc4`='拿一捧软泥。', `FemaleText_loc5`='拿走一把泥巴。', `FemaleText_loc7`='Coge un puñado de barro.' WHERE `ID`=48206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 두 움큼 가져가기', `MaleText_loc4`='拿两捧软泥。', `MaleText_loc5`='拿走二把泥巴。', `MaleText_loc7`='Coge dos puñados de barro.', `FemaleText_loc1`='진흙 두 움큼 가져가기', `FemaleText_loc4`='拿两捧软泥。', `FemaleText_loc5`='拿走二把泥巴。', `FemaleText_loc7`='Coge dos puñados de barro.' WHERE `ID`=48207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 세 움큼 가져가기', `MaleText_loc4`='拿三捧软泥。', `MaleText_loc5`='拿走三把泥巴。', `MaleText_loc7`='Coge tres puñados de barro.', `FemaleText_loc1`='진흙 세 움큼 가져가기', `FemaleText_loc4`='拿三捧软泥。', `FemaleText_loc5`='拿走三把泥巴。', `FemaleText_loc7`='Coge tres puñados de barro.' WHERE `ID`=48208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙 네 움큼 가져가기', `MaleText_loc4`='拿四捧软泥。', `MaleText_loc5`='拿走四把泥巴。', `MaleText_loc7`='Coge cuatro puñados de barro.', `FemaleText_loc1`='진흙 네 움큼 가져가기', `FemaleText_loc4`='拿四捧软泥。', `FemaleText_loc5`='拿走四把泥巴。', `FemaleText_loc7`='Coge cuatro puñados de barro.' WHERE `ID`=48209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실뭉치 한 개 가져가기', `MaleText_loc4`='拿一团线。', `MaleText_loc5`='拿走一捲線。', `MaleText_loc7`='Coge una bobina de hilo.', `FemaleText_loc1`='실뭉치 한 개 가져가기', `FemaleText_loc4`='拿一团线。', `FemaleText_loc5`='拿走一捲線。', `FemaleText_loc7`='Coge una bobina de hilo.' WHERE `ID`=48210;
