UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 조사', `MaleText_loc4`='调查皮革。', `MaleText_loc5`='調查皮革。', `MaleText_loc7`='Examina los pellejos.', `FemaleText_loc1`='가죽 조사', `FemaleText_loc4`='调查皮革。', `FemaleText_loc5`='調查皮革。', `FemaleText_loc7`='Examina los pellejos.' WHERE `ID`=48214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑을 잡았다 이건가. 여기 포상금을 받게!', `MaleText_loc4`='你抓到了小偷。享用酬劳吧！', `MaleText_loc5`='好吧，你是逮到了個小偷。好好享用你的賞金吧!', `MaleText_loc7`='Así que has atrapado a un ladrón. ¡Disfruta de la recompensa!' WHERE `ID`=48215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 죽은 도적에게서 획득한 돈은 자네 것으로 보이는군. 운도 좋아...', `MaleText_loc4`='看来我们从那死去盗贼身上找到的金币归你了。你可真走运……', `MaleText_loc5`='看來我們從死掉的盜賊身上取回的金幣好像就是你的。你的運氣還真好...', `MaleText_loc7`='Parece que el oro que recuperamos de aquel pícaro muerto era tuyo. Qué suerte tienes...' WHERE `ID`=48216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이자를 잘못 계산했을 리 없네... 왜냐면 우린 이자를 안 주거든! 그래도 재판장을 왔다 갔다 하려니 귀찮군. 그냥 내 사비를 줄 테니 가져가게.', `MaleText_loc4`='我不会算错该付的利息……因为一分都没有！跟坐牢相比，我宁可付钱——拿去吧。', `MaleText_loc5`='我不可能會算錯你的利息...因為我們根本就沒有在發利息!我寧願給錢也不要上法庭，我用我自己的錢付你。', `MaleText_loc7`='No he calculado mal tu interés... ¡Porque no damos interés! Prefiero pagar a someterme a juicio, así que toma mi dinero personal.' WHERE `ID`=48217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반올림하고 남은 잔돈이 모인 계좌라.. 천잰데?', `MaleText_loc4`='我们赚的所有钱都在这儿了……真棒。', `MaleText_loc5`='所有被我們四捨五入掉的零頭...太聰明了。', `MaleText_loc7`='Un registro de todas las fracciones de cobre que redondeamos... Brillante.' WHERE `ID`=48218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 뭐가 묻어 있었다고요? 돈을 이렇게 냈는데... 재봉사에게 제 의식용 로브에는 아무 문제가 없어야 할 거라고 전하십시오.', `FemaleText_loc4`='他们这是派谁来了？回去告诉那裁缝，最好用从我这儿拿走的钱，把我的礼服做得完美无缺。', `FemaleText_loc5`='你說他們穿了什麼?告訴裁縫師，我的禮袍一定要完美無缺，值得她對我收取的每一分錢。', `FemaleText_loc7`='¿Que tenían qué? Dile a mi sastre que más le vale que mi vestido ceremonial esté perfecto, con todo lo que me está cobrando.' WHERE `ID`=48219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 이걸 전부 팔다니 믿을 수 없군요. 이따 잠시 들러 사들이겠습니다.', `FemaleText_loc4`='我真不敢相信你竟然在这儿卖那些东西。我会顺路拜访厨师来把它们带走。', `FemaleText_loc5`='我不敢相信，你竟然會在這裡賣那些東西。晚點我會去廚師那裡拿貨。', `FemaleText_loc7`='No me puedo creer que vendas eso aquí, de todos los sitios posibles. Luego me pasaré por el cocinero para recogerlo.' WHERE `ID`=48220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도박을 끊어야겠군. 카드는 더 이상 안하겠다고 전하시오.', `MaleText_loc4`='我真该戒赌了。告诉他们我不会再玩了。', `MaleText_loc5`='我真應該要戒賭了。告訴他們，我不再打牌了。', `MaleText_loc7`='En serio, tengo que dejar de jugar. Diles que no me repartan más cartas.' WHERE `ID`=48221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도박을 끊어야겠군. 카드는 더 이상 안하겠다고 전하시오.', `MaleText_loc4`='我真该戒赌了。告诉他们我不会再玩了。', `MaleText_loc5`='我真應該要戒賭了。告訴他們，我不再打牌了。', `MaleText_loc7`='En serio, tengo que dejar de jugar. Diles que no me repartan más cartas.' WHERE `ID`=48222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 지난주에 분명히 168시간 일했소... 하지만 서류상 출근 시간이 기록되지 않았다면 당신 말이 맞겠지.', `MaleText_loc4`='我知道我上星期总共工作了一百六十八个小时……可如果查不到我的考勤记录，也许你是对的。', `MaleText_loc5`='我記得上禮拜我工作了168小時...但是既然文件上說我沒有打卡，你講的應該沒錯。', `MaleText_loc7`='Yo sé que trabajé ciento sesenta y ocho horas la semana pasada... Pero si los papeles dicen que no fiché, igual tienes razón.' WHERE `ID`=48223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요! 제 특제 무쇠솥의 품질 보증 기간을 한 달 늘릴 수 있게 되어 기쁘네요.', `FemaleText_loc4`='非常感谢！我生铁锅的保修期能再延长一个月，这太令人高兴了。', `FemaleText_loc5`='太感謝了!我很高興可以把我鑄鐵鍋的保固期延長一個月。', `FemaleText_loc7`='¡Muchísimas gracias! Me alegro de haber podido extender la garantía de mis cazuelas de hierro colado un mes más.' WHERE `ID`=48224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제... 남동생이 죽었다고요? 제게 남동생이 있었다니... 이 돈으로 장례를 잘 치러주세요.', `FemaleText_loc4`='我的……兄弟死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。', `FemaleText_loc5`='我...弟弟死了?無法相信，我跟他竟然從來沒見過面。請收下這筆錢，好好安葬他。', `FemaleText_loc7`='¿Mi... hermano ha muerto? No me puedo creer que nunca lo conociera. Toma este dinero y dale un buen funeral.' WHERE `ID`=48225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제... 여동생이 죽었다고요? 제게 여동생이 있었다니... 이 돈으로 장례를 잘 치러주세요.', `FemaleText_loc4`='我的……姐妹死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。', `FemaleText_loc5`='我...妹妹死了?無法相信，我跟她竟然從來沒見過面。請收下這筆錢，好好安葬她。', `FemaleText_loc7`='¿Mi... hermana ha muerto? No me puedo creer que nunca la conociera. Toma este dinero y dale un buen funeral.' WHERE `ID`=48226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제... 삼촌이 죽었다고요? 제게 삼촌이 있었다니... 이 돈으로 장례를 잘 치러주세요.', `FemaleText_loc4`='我的……叔叔死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。', `FemaleText_loc5`='我...叔叔死了?無法相信，我跟他竟然從來沒見過面。請收下這筆錢，好好安葬他。', `FemaleText_loc7`='¿Mi... tío ha muerto? No me puedo creer que nunca lo conociera. Toma este dinero y dale un buen funeral.' WHERE `ID`=48227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제... 고모가 죽었다고요? 제게 고모가 있었다니... 이 돈으로 장례를 잘 치러주세요.', `FemaleText_loc4`='我的……阿姨死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。', `FemaleText_loc5`='我...阿姨死了?無法相信，我跟她竟然從來沒見過面。請收下這筆錢，好好安葬她。', `FemaleText_loc7`='¿Mi... tía ha muerto? No me puedo creer que nunca la conociera. Toma este dinero y dale un buen funeral.' WHERE `ID`=48228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르시스에서 당신이 무슨 일을 했는지 들었소. 당신과 함께 싸울 수 있다니 영광이오.', `MaleText_loc4`='我听说了你在奥西斯的事迹。很荣幸能与你并肩作战。', `MaleText_loc5`='我聽說了你在奧爾希斯城的豐功偉業。很榮幸能和你一起並肩作戰。', `MaleText_loc7`='Me han contado lo que hiciste en Orsis. Será un honor luchar a tu lado.' WHERE `ID`=48229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 오직 나둔 왕자님을 구출한 $r, 당신의 명령만을 따르겠소.', `MaleText_loc4`='我只听命于一个$r——就是曾救出纳顿亲王的那个。', `MaleText_loc5`='救了納登親王的$r是唯一我願意服從其命令的$r。', `MaleText_loc7`='$gEl:La; $r que rescató al príncipe Nadun es $gel único:la única; $r $gdel:de la; que aceptaría órdenes.' WHERE `ID`=48230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리도 뭔가 행동으로 보여줄 때가 됐소.', `MaleText_loc4`='我们该开始着手做些什么了。', `MaleText_loc5`='我們該開始做點什麼了。', `MaleText_loc7`='Ya era hora de que empezáramos a hacer algo.' WHERE `ID`=48231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요하다면 맨손으로라도 람카헨을 지켜내겠소!', `MaleText_loc4`='要是到了逼不得已的境地，我就算赤手空拳也要保卫拉穆卡恒！', `MaleText_loc5`='就算赤手空拳，我也要誓死捍衛蘭姆卡韓!', `MaleText_loc7`='¡Defenderé Ramkahen con las manos desnudas, si es necesario!' WHERE `ID`=48232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅은 우리가 지키겠소!', `MaleText_loc4`='我们会守卫自己的土地！', `MaleText_loc5`='我們要保護我們的土地!', `MaleText_loc7`='¡Defenderemos nuestras tierras!' WHERE `ID`=48233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 소문이 사실이라면, 네페르세트와의 전쟁에서 나도 기꺼이 당신과 함께하겠소!', `MaleText_loc4`='如果关于你的那些传闻都是真的，陌生人，我会非常愿意与你一同对抗尼斐塞特！', `MaleText_loc5`='倘若你的傳言是真的，陌生人，我很樂意加入你一起對抗奈斐賽特!', `MaleText_loc7`='¡Si los rumores sobre ti son ciertos, $gforastero:forastera;, estaré encantado de unirme a la lucha contra los Neferset!' WHERE `ID`=48234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 위장복을 만드는 데 가죽이 충분하지 않습니다.', `MaleText_loc4`='这些皮革根本不够作出一套像样的伪装服。', `MaleText_loc5`='這裡沒有足夠的皮革可縫製出恰當的偽裝。', `MaleText_loc7`='Aquí no hay pellejo suficiente para un buen disfraz ni de lejos.' WHERE `ID`=48235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 진흙이 너무 많군요. 이 진흙을 다 쓰면 당신의 위장복은 너무 검고 질척거릴 겁니다.', `MaleText_loc4`='好吧，软泥实在太多了。你的伪装服一定会又黑又粘。', `MaleText_loc5`='好吧，泥巴太多。你偽裝的顏色看起來太深太髒了。', `MaleText_loc7`='A ver, aquí hay demasiado barro. Tu disfraz será demasiado oscuro y tendrá grumos.' WHERE `ID`=48236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 늑대 가죽을 너무 많이 가져오셨잖아요!', `MaleText_loc4`='你带来的座狼皮太多了，$n！', `MaleText_loc5`='你帶太多張座狼皮來給我了，$n!', `MaleText_loc7`='¡Me has traído demasiados pellejos de huargo, $n!' WHERE `ID`=48237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 변장을 적절히 칠하려면 진흙이 더 필요할 겁니다.', `MaleText_loc4`='我们还需要更多软泥来为你的伪装服染色。', `MaleText_loc5`='我們需要更多泥巴來為你的偽裝染上正確的顏色。', `MaleText_loc7`='Vamos a necesitar más barro para darle un buen color a tu disfraz.' WHERE `ID`=48238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙과 가죽은 적당히 받았습니다만, 이걸 한데 묶을 실타래가 충분하지 않습니다.', `MaleText_loc4`='我已经有了适量的软泥和皮革，可用来缝制的线还不够。', `MaleText_loc5`='我已經有適量的泥巴和皮革，可是沒有足夠的線將它們縫製起來。', `MaleText_loc7`='Tengo las cantidades adecuadas de barro y pellejos, pero no tengo suficiente hilo para coserlo todo.' WHERE `ID`=48239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠! 나머지 재료들은 모두 적당합니다만, 실타래가 너무 많습니다!', `MaleText_loc4`='啊！万事俱备，可线太多了！', `MaleText_loc5`='啊!什麼都很好，就是線太多了!', `MaleText_loc7`='¡Ay! Todo lo demás pinta bien, ¡pero hay demasiado hilo!' WHERE `ID`=48240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이건 완벽하군요! 이 변장은 제 걸작입니다요!', `MaleText_loc4`='这……这太完美了！这件伪装服简直是我的旷世杰作！', `MaleText_loc5`='這...這太完美了!這件偽裝是我的傑作!', `MaleText_loc7`='Esto... ¡Esto es perfecto! ¡Este disfraz será mi obra maestra!' WHERE `ID`=48241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은무쇠 부족 전체에서 저보다 더 기술 좋은 장인은 찾을 수 없을 겁니다!$b$b망치질, 단조질, 채광질 다 빌어먹으라죠! 내게 필요한 금속이라곤 바늘과 골무 하나씩뿐입니다!', `MaleText_loc4`='在整个黑铁部族中，你再也找不到比我技巧更高超的工匠了！$b$b什么敲打、锻造、采掘，都见鬼去吧！一根缝针、一个顶针就是我所需要的全部金属！', `MaleText_loc5`='在黑鐵矮人裡你絕對找不到比我更棒的工匠了!$b$b去他東東的敲敲打打和挖挖!我需要的金屬就只有那麼一根針和一個頂針套!', `MaleText_loc7`='¡No encontrarás a un artesano mejor que yo entre todos los Hierro Negro!$b$b¡Al infierno con los picos, las palas y los martillos! ¡La aguja y el dedal son todo el metal que necesito!' WHERE `ID`=48242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽 몇 장, 진흙, 실뭉치를 가져왔습니다.', `MaleText_loc4`='我带来了一些皮革、软泥和缝线。', `MaleText_loc5`='我帶了些座狼皮、泥巴，還有線來給你。', `MaleText_loc7`='Te he traído pellejos, barro e hilo.', `FemaleText_loc1`='가죽 몇 장, 진흙, 실뭉치를 가져왔습니다.', `FemaleText_loc4`='我带来了一些皮革、软泥和缝线。', `FemaleText_loc5`='我帶了些座狼皮、泥巴，還有線來給你。', `FemaleText_loc7`='Te he traído pellejos, barro e hilo.' WHERE `ID`=48243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 뭘 가져오신 겁니까?', `MaleText_loc4`='你给我带来了什么？', `MaleText_loc5`='你帶什麼東西來給我?', `MaleText_loc7`='¿Qué me has traído?' WHERE `ID`=48244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 계집애 좀 닥치게 해줘!', `MaleText_loc4`='快来人让这小姑娘闭嘴！', `MaleText_loc5`='誰來叫這個小女孩閉嘴!', `MaleText_loc7`='¡Que alguien haga callar a esta niña!' WHERE `ID`=48245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인형 줄까, 꼬마야? 그러면 좀 기분이 나아지겠니?', `MaleText_loc4`='你想要个洋娃娃吗，小女孩？那样会不会好一点儿？', `MaleText_loc5`='你想要洋娃娃嗎，小女孩?那樣心情會不會好一點?', `MaleText_loc7`='¿Quieres una muñeca, pequeña? ¿Te consolaría?' WHERE `ID`=48246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 죽이거나 여자애를 죽이거나 얼른 선택해!', `MaleText_loc4`='杀了我，要不就杀了那小女孩！', `MaleText_loc5`='殺了我，或是殺了這女孩!', `MaleText_loc7`='¡MÁTAME A MÍ O A LA NIÑA!' WHERE `ID`=48247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 혹시 스틸워터의 계략인가? 날 죽이기 전에 고문하려는 건가?', `MaleText_loc4`='这是斯蒂沃特的计划？在他杀死我之前，还要如此折磨我？', `MaleText_loc5`='這是斯蒂沃特的詭計嗎?先折磨我，然後再殺了我?', `MaleText_loc7`='¿Este es el plan de Aguaserena? ¿Torturarme antes de matarme?' WHERE `ID`=48248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 망설이나! 스틸워터! 차라리 날 죽이라고! 지금 당장!', `MaleText_loc4`='你还在等什么呢斯蒂沃特！杀了我啊！动手啊！', `MaleText_loc5`='斯蒂沃特，你還在等什麼!殺了我!來動手啊!', `MaleText_loc7`='¡A QUÉ ESPERAS, AGUASERENA! ¡MÁTAME! ¡HAZLO YA!' WHERE `ID`=48249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 더 울 생각이니?', `MaleText_loc4`='你还要哭多久？', `MaleText_loc5`='你還要再哭多久?', `MaleText_loc7`='¿Cuánto más vas a llorar?' WHERE `ID`=48250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받을 용아귀 놈들!$B$B놈들이 우리 그리핀을 죽이고, 우리 가족들을 공격하고, 우리 땅을 빼앗았습니다. 세상이 무너져내리는 이런 때에도 놈들은 계속해서 우리를 공격하고 있어요.$B$B당신네 얼라이언스가 와일드해머를 돕고 싶다면, 우리 마음을 얻을 방법은 단 하나뿐입니다. 용아귀 부족을 저지해 주세요.', `MaleText_loc4`='该死的龙喉渣滓！$B$B他们屠戮我们的鸟禽，攻击我们的亲人，夺取我们的土地。就在这世界分崩离析之时，他们还在袭击我们的家园。$B$B要是你们这群联盟想要获取蛮锤的帮助，就只有一条途径能让我们颔首——阻——止——龙喉。', `MaleText_loc5`='該死的龍喉氏族!$B$B他們殺了我們的獅鷲獸，攻擊我們的家人，搶走我們的土地。甚至連世界都崩塌了，他們也還是一樣沒放棄攻擊我們的家園。$B$B聯盟想要獲得蠻錘氏族的協助，很簡單，只有一個方法:阻止。龍喉。氏族。', `MaleText_loc7`='¡Malditos sean los Faucedraco!$b$bMatan a nuestros pájaros, atacan a nuestras familias, toman nuestras tierras. Incluso mientras el mundo se derrumba a nuestro alrededor ellos siguen asaltando nuestras casas.$b$bSi tu Alianza quiere la ayuda de los Martillo Salvaje, solo hay una forma de convencernos. Detened. A. Los. Faucedraco.' WHERE `ID`=48251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<잔에서 눈을 떼는 블런디>$B$B네, 맞습니다. 고위주술사님은 썬더마 폐허를 되찾으려고 전쟁터에 나가서 싸우고 계시죠. 저는 "하급주술사"입니다.$B$B고위주술사님이 자기가 없는 동안 썬더마의 모든 주... 술을 책임지라고 저한테 말씀하셨죠.', `MaleText_loc4`='<布朗迪抬眼看了看你。>$B$B啊，是的。高阶萨满正在战场上拼杀，为夺回桑德玛尔废墟而努力。我就是人们口中的“低阶萨满”。$B$B在他离开的这段日子里，他让我留下处理桑德玛尔的萨满事务……', `MaleText_loc5`='<布朗第的目光從酒杯挪到你身上。>$B$B對，沒錯。高階薩滿在戰場上奮戰，努力要奪回桑德瑪遺跡。我是大家口中的「低階薩滿」。$B$B他不在的時候就是留我在這裡照料桑德瑪所有的薩滿...事情。', `MaleText_loc7`='<Blundy mira por encima de sus copas.>$B$BSí, es cierto. El Alto chamán está fuera, en el campo de batalla, luchando por reconquistar las Ruinas de Bramal. Yo soy lo que se llama un "chamán inferior".$B$BMientras él esté fuera, me ha dejado aquí para que me ocupe de todos los asuntos chamanísticos de Bramal...' WHERE `ID`=48252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='썬더마는 와일드해머 부족의 마지막 보루입니다. 이 작은 마을이 피난민으로 가득 차는 사이, 우리 형제들은 계속해서 싸워나가고 있어요.', `FemaleText_loc4`='桑德玛尔是蛮锤的最后一处堡垒了。我们狭小的城镇中挤满了难民，而我的兄弟此时正在奋力作战。', `FemaleText_loc5`='桑德瑪是蠻錘矮人最後的據點。我兄弟正在努力奮戰，而我們的小鎮裡則滿滿都是難民。', `FemaleText_loc7`='Bramal es el último punto fuerte de los Martillo Salvaje. Mi hermano intenta seguir en la batalla mientras nuestra pequeña ciudad se llena de refugiados.' WHERE `ID`=48253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으으윽...', `MaleText_loc4`='呃……', `MaleText_loc5`='呃啊...', `MaleText_loc7`='Urrrrrrgh...' WHERE `ID`=48254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크어어어억!', `MaleText_loc4`='HLORRHGH！', `MaleText_loc5`='嚇噢!', `MaleText_loc7`='¡HLORRHGH!' WHERE `ID`=48255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입 크게 벌리세요, 타우렌 아저씨! 히포그리프도 삼킬 만큼 크게!', `FemaleText_loc4`='小心，牛头人先生！角鹰兽来了！', `FemaleText_loc5`='打開，牛頭人先生!角鷹獸回巢了!', `FemaleText_loc7`='¡Haz sitio, señor tauren! ¡Aquí viene el hipogrifo directo a su percha!' WHERE `ID`=48256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 자네! 그래, 자네, $c! 감독관 스틸워터가 날 마음대로 붙잡고 이렇게 가둬두었네. 밖으로 나가게 해주면 모두 설명하지.', `MaleText_loc4`='那边那个！对，说你呢，$c！我被看守者斯蒂沃特强行抓来并关在了这里。把我从这笼子里弄出去，我会向你说明一切。', `MaleText_loc5`='嘿!對，$c，就是你!管理員斯蒂沃特硬把我抓過來，非法關在這裡。把我從籠裡放出來，我會把一切解釋給你聽。', `MaleText_loc7`='¡EH, TÚ! ¡Sí, tú, $c! He sido capturado en contra de mi voluntad y hecho prisionero ilegalmente por el celador Aguaserena. Sácame de esta jaula y te lo explicaré todo.' WHERE `ID`=48257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='냐옹아... 냐옹아! 정말 미안해, 냐옹아! 날 이렇게 두고 떠나지 마!', `FemaleText_loc4`='猫咪……猫咪！我真的很抱歉，猫咪！快回来！别这样离开我！', `FemaleText_loc5`='小貓咪...貓咪!對不起，小貓咪!回來!不要這樣拋棄我!', `FemaleText_loc7`='¡Kitty... KITTY! ¡LO SIENTO MUCHO, KITTY! ¡VUELVE! ¡NO ME DEJES ASÍ!' WHERE `ID`=48258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼용의 시체에서 황혼의 정수가 흘러나옵니다...', `MaleText_loc4`='暮光精华开始自雏龙的尸体中升腾……', `MaleText_loc5`='暮光精華開始從幼龍的屍體上冒出來....', `MaleText_loc7`='La esencia crepuscular empieza a burbujear y a salir del cadáver de la cría...' WHERE `ID`=48259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정수가 합쳐지자 %s|1이;가; 되살아납니다!', `MaleText_loc4`='混合精华使%s复活了！', `MaleText_loc5`='%s被混合的精華復活了!', `MaleText_loc7`='¡%s revive gracias a la combinación de esencias!' WHERE `ID`=48260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s 시체가 거품처럼 황혼의 정수로 흩어집니다.', `MaleText_loc4`='%s的尸体分解成为升腾的暮光精华。', `MaleText_loc5`='%s的屍體逐漸分解成泡沫狀的暮光精華。', `MaleText_loc7`='El cuerpo de %s se desintegra y se convierte en espumosa esencia crepuscular.' WHERE `ID`=48261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 높은 둑 전진 부대에서 나왔습니다. 여기 썬더마의 와일드해머 드워프를 우리 편으로 끌어들이려고요.$B$B아마도 제가 이들에게 도움을 줄 수 있을 것 같은데요, 나 원 참 기가 차서... 이 친구들, 삼환식 재분극 장치도 하나 안 가지고 있다니까요? 단 한 개도요!$B$B대체 어떻게 지금까지 헤쳐나온 걸까요?', `MaleText_loc4`='我是来自滩头堡的先遣单位，正在试图说服桑德玛尔的蛮锤部族。$B$B我想我能帮助他们，但令人难以置信的是，他们竟然没有一个三环交流极向转换装置？一个都没有！$B$B他们这些日子到底是过来的？', `MaleText_loc5`='我來自高岸堡的先遣部隊，我們是要來贏得桑德瑪的蠻錘矮人的支持。$B$B我是幫得了他們啦，但是你能相信嗎，他們竟然連一個三循環交流電再極化裝置也沒有?一個也沒有!$B$B他們怎麼過得下這種日子?', `MaleText_loc7`='Formo parte de la unidad de avanzada de Bancalto e intento ganarme a los Martillo Salvaje, aquí en Bramal.$b$bCreo que puedo ayudarles, ¿pero te puedes creer que no tienen un solo dispositivo de repolarización de corriente alterna tricíclica? ¡Ni uno!$b$bPero, ¿cómo se las arreglan?' WHERE `ID`=48262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 연습을 끝낸다고요? 알았어요. 나중에 뵙죠.', `MaleText_loc4`='我们这么快就完成练习了？很好，回头见。', `MaleText_loc5`='我們這麼快就練習結束了?好吧，我們晚點見。', `MaleText_loc7`='¿Ya hemos terminado de practicar? ¿Tan pronto? Muy bien, nos vemos luego.' WHERE `ID`=48263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $c님! 저는 높은 둑 전진 부대에서 나왔습니다. 여기 썬더마의 와일드해머 드워프를 우리 편으로 끌어들이려고요.$B$B와일드해머 그리핀 기수들은 용아귀 비룡기수를 하늘에서 끌어내리느라 골머리를 앓고 있어요. 제가 그 일에 도움이 될 기계를 하나 구상했는데, 완성하려면 이런저런 물품이 필요하답니다. 상당히 많이요.$B$B절 도와주실 수 있을까요?', `MaleText_loc4`='你好啊，$c！我是来自滩头堡的先遣侦察单位，尽力说服桑德玛尔的蛮锤部族。$B$B他们的狮鹫骑士正被龙喉的龙骑士们纠缠得团团转。我设计了一个奇妙的装置来帮助他们，可我缺少一些物品。许多物品。$B$B你能帮我吗？', `MaleText_loc5`='你好，$c!我來自高岸堡的先遣斥候部隊，而我們來此的目的是要贏得桑德瑪的蠻錘矮人的支持。$B$B他們的獅鷲騎士和龍喉的飛龍騎士陷入了苦戰。我想出了個裝置，應該可以派得上用場。但是我需要很多的補給品，很多很多的補給品。$B$B你可以幫忙嗎?', `MaleText_loc7`='¡Saludos, $c! Soy de la unidad de exploración avanzada de Bancalto y estoy intentando ganarme a los Martillo Salvaje aquí, en Bramal.$B$BA los jinetes de grifos les está costando mucho acabar con esos jinetes de dracos Faucedraco. Tengo un plano para un artilugio que podrá ayudar, pero necesito una serie de suministros. Un montón.$B$B¿Puedes ayudarme?' WHERE `ID`=48264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오세요!', `MaleText_loc4`='我来了，$n$g阁下:女士;！', `MaleText_loc5`='我來了，$n$g長官:長官;!', `MaleText_loc7`='¡Aquí estoy, $gseñor:señora; $n!' WHERE `ID`=48265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동정은 필요 없다, $C.', `MaleText_loc4`='我不需要你的怜悯，$C。', `MaleText_loc5`='我不需要你的同情，$C。', `MaleText_loc7`='No necesito tu piedad, $c.', `FemaleText_loc1`='동정은 필요 없다, $C.', `FemaleText_loc4`='我不需要你的怜悯，$C。', `FemaleText_loc5`='我不需要你的同情，$C。', `FemaleText_loc7`='No necesito tu piedad, $c.' WHERE `ID`=48266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 언데드 군대를 조종하는 공포의 군주는 티콘드리우스라고 한다. 놈은 굴단의 해골이라는 강력한 흑마법사의 유물을 지니고 있지. 그 유물이 이 숲을 오염시킨 원흉이다.', `MaleText_loc4`='领导这支亡灵大军的恐惧魔王名叫提克迪奥斯。他控制着一个名为古尔丹之颅的强大术士神器。那就是这片森林堕落的根源。', `MaleText_loc5`='指揮這支亡靈軍隊的驚懼領主名叫提克迪奧斯，他擁有一件強大的術士法器，叫做古爾丹之顱，而腐化了這片森林的正是這樣東西。', `MaleText_loc7`='El Señor del Terror que lidera este ejército de no-muertos se llama Tichondrius. Controla un poderoso artefacto brujo llamado Calavera de Gul''dan. Es el responsable de la corrupción de estos bosques.' WHERE `ID`=48267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러다가는 평생 싸우겠군. 네가 진정 원하는 게 뭐냐?', `MaleText_loc4`='我们可以像这样一直战斗下去。你究竟想要什么？', `MaleText_loc5`='我們可以就這樣繼續一直打下去。但是你究竟想要什麼?', `MaleText_loc7`='Podríamos seguir luchando eternamente. ¿Qué es lo que quieres de verdad?' WHERE `ID`=48268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도끼를 받아라, 비겁한 놈!', `MaleText_loc4`='尝尝我的斧子吧，懦夫！', `MaleText_loc5`='懦夫，嚐嚐我的斧頭!', `MaleText_loc7`='¡Prueba mi hacha, cobarde!', `FemaleText_loc1`='내 도끼를 받아라, 비겁한 놈!', `FemaleText_loc4`='尝尝我的斧子吧，懦夫！', `FemaleText_loc5`='懦夫，嚐嚐我的斧頭!', `FemaleText_loc7`='¡Prueba mi hacha, cobarde!' WHERE `ID`=48269;
