UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요! 저도 막 도와드리려던 참이었어요! 그런데 혼자서도 잘하시더라고요.', `FemaleText_loc4`='干得好！我正准备要动手帮你呢！但看来你已经都搞定了。', `FemaleText_loc5`='幹得好!我正準備要來幫你，可是你好像已經把局面控制住了。', `FemaleText_loc7`='¡Bien hecho! Estaba a punto de intervenir, pero parecía que lo tenías bajo control.' WHERE `ID`=48274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 뒤에 사슬로 묶인 고양이처럼 생긴 생물이 우리와 이야기를 나누고 싶은 모양이에요. 어쩌면 우릴 도와줄지도 몰라요. 하지만 조심하셔야 해요.', `FemaleText_loc4`='锁在后面的那只像猫一样的家伙好像有话要说。也许他能帮到我们……但一定要小心。', `FemaleText_loc5`='被困在那裡的半人半虎生物似乎很想和你講話。也許他幫得了我們...但是要小心。', `FemaleText_loc7`='Esa criatura felina que tienen atada ahí detrás tiene pinta de querer hablar. A lo mejor puede ayudarnos... Pero ten cuidado.' WHERE `ID`=48275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선실 안에 희미한 형체가 나타납니다!', `MaleText_loc4`='船舱里出现一个模糊的人影！', `MaleText_loc5`='一道陰暗的人影出現在船艙裡!', `MaleText_loc7`='¡Una figura sombría aparece en el camarote del barco!' WHERE `ID`=48276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 영상을 잘 보게. 자네에게 놈리건 작전에 대해 알려주고 싶은 게 좀 있다네.', `MaleText_loc4`='看看这个全息平台。我想让你对诺莫瑞根行动有所了解。', `MaleText_loc5`='看看這張全像顯影桌。我來告訴你行動:諾姆瑞根的一些事情。', `MaleText_loc7`='Echa un vistazo a esta holoplataforma. Quiero enseñarte un par de cosas sobre Operación: Gnomeregan.' WHERE `ID`=48277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기서 발견한 사실에 대해 연구를 해봐야겠소, $n.', `MaleText_loc4`='我需要进一步研究我们的发现，$n。', `MaleText_loc5`='我要好好研究研究我們在這邊發現的東西，$n。', `MaleText_loc7`='Voy a tener que investigar lo que hemos descubierto aquí, $n.' WHERE `ID`=48278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장치가 만들어 내는 힘을 우리가 어떻게 써야 할지는 아무도 모른다오.', `MaleText_loc4`='我们不知该如何利用这些装置所能产生的能量。', `MaleText_loc5`='無法預料我們究竟能怎樣利用這些東西所產生的能量。', `MaleText_loc7`='A saber cómo podríamos utilizar la energía que crean estos mecanismos.' WHERE `ID`=48279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='람카헨에서 다시 만납시다. 앞으로 어떻게 해야 할지 알려주겠소.', `MaleText_loc4`='等我知道下一步该如何进行时，会通知你的。', `MaleText_loc5`='到蘭姆卡韓找我，我會再告訴你我們的下一步該怎麼走。', `MaleText_loc7`='Reúnete conmigo en Ramkahen y te diré cuál será nuestro siguiente paso.' WHERE `ID`=48280;
