UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘들아, 먹어치워라! 야들야들한 살덩이로 배를 채워라!', `FemaleText_loc4`='吃吧，孩子们！尽情享用他们肥美的躯壳吧！', `FemaleText_loc5`='吃吧，孩子們!好好享用他們肥嫩的軀殼吧!', `FemaleText_loc7`='¡Coman, niños! ¡Llénense con su carne!' WHERE `ID`=48282;
