UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이대로 넘기진 않아, 보라야. 놈들에게 꼭 복수할 거야! 반드시 복수할 거라고!', `MaleText_loc4`='这件事决不会就这么算了，烁影。他们要付出代价！全都要付出代价！', `MaleText_loc5`='我不會放過他們的，閃閃。他們會付出代價!他們會付出代價!', `MaleText_loc7`='No dejaré que se salgan con la suya, Centella. ¡Pagarán por esto! ¡Pagarán!' WHERE `ID`=48284;
