UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 결과: 당혹스러운 실패. 새로운 방식을 전투 체계에 정립 중.', `MaleText_loc4`='战斗结果：可耻的失败。正在将新策略整合进战斗方案中。', `MaleText_loc5`='作戰結果:難堪失敗。整合新作戰模組。', `MaleText_loc7`='Resultado de la batalla: fracaso vergonzoso. Incorporando nuevos métodos al régimen de batalla.' WHERE `ID`=48288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배. 수치심 단계: 상. 다음 전투를 위해 전략 조절 중.', `MaleText_loc4`='战败。可耻等级：高。正在调整未来战斗的作战策略。', `MaleText_loc5`='遭受失敗。羞愧等級:高。調整未來作戰策略。', `MaleText_loc7`='Derrotado. Nivel de vergüenza: alto. Ajustando estrategia para batallas futuras.' WHERE `ID`=48289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 조합의 친구여.', `MaleText_loc4`='你好啊，兄弟会的朋友。', `MaleText_loc5`='你好，兄弟會的朋友。', `MaleText_loc7`='Saludos, $gamigo:amiga; de la Hermandad.' WHERE `ID`=48290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골렘아, 난 너의 전투 훈련을 도와주러 왔단다.', `MaleText_loc4`='我是来此帮你进行作战训练的，魔像。', `MaleText_loc5`='我是來幫助你進行戰鬥訓練的，魔像。', `MaleText_loc7`='He venido para ayudarte con tu instrucción de combate, gólem.', `FemaleText_loc1`='골렘아, 난 너의 전투 훈련을 도와주러 왔단다.', `FemaleText_loc4`='我是来此帮你进行作战训练的，魔像。', `FemaleText_loc5`='我是來幫助你進行戰鬥訓練的，魔像。', `FemaleText_loc7`='He venido para ayudarte con tu instrucción de combate, gólem.' WHERE `ID`=48291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 네 간섭의 결과물이다!', `MaleText_loc4`='看看你多管闲事的后果吧！', `MaleText_loc5`='看看被你亂搞的結果!', `MaleText_loc7`='¡Observa el resultado de tu intromisión!' WHERE `ID`=48292;
