UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련 단계 충분함. 경비 임무로 돌아갑니다. 감사합니다.', `MaleText_loc4`='训练水平已达到要求。继续执行守卫任务。谢谢你。', `MaleText_loc5`='訓練等級足夠。返回守衛任務。謝謝你。', `MaleText_loc7`='Nivel de instrucción suficiente. Volviendo a las tareas de guardia. Gracias.' WHERE `ID`=48295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망가진 기계의 선체에서 재활용할 수 있는 부품 몇 개를 찾았습니다. 한 개의 부품만 가져갈 수 있을 것 같습니다.', `MaleText_loc4`='你在那被摧毁家伙的身体里发现了几个可回收的部件。看来你只能回收一个部件。', `MaleText_loc5`='你在魔像毀損的殘骸裡找到了幾個還可堪使用的零件，但是你恐怕只能夠拿走一個零件。', `MaleText_loc7`='Encuentras algunas piezas que se pueden recuperar del cascarón en ruinas de la criatura. Al parecer solo podrás recuperar una pieza.' WHERE `ID`=48296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='융해촉진제 배출 거름망을 줍습니다.', `MaleText_loc4`='回收排能滤网。', `MaleText_loc5`='拿走熔焊排氣過濾器。', `MaleText_loc7`='Recupera la criba con escape fundente.', `FemaleText_loc1`='융해촉진제 배출 거름망을 줍습니다.', `FemaleText_loc4`='回收排能滤网。', `FemaleText_loc5`='拿走熔焊排氣過濾器。', `FemaleText_loc7`='Recupera la criba con escape fundente.' WHERE `ID`=48297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요석 피스톤을 줍습니다.', `MaleText_loc4`='回收黑曜石活塞。', `MaleText_loc5`='拿走黑曜石活塞。', `MaleText_loc7`='Recupera el pistón de obsidiana.', `FemaleText_loc1`='흑요석 피스톤을 줍습니다.', `FemaleText_loc4`='回收黑曜石活塞。', `FemaleText_loc5`='拿走黑曜石活塞。', `FemaleText_loc7`='Recupera el pistón de obsidiana.' WHERE `ID`=48298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토륨 변속자루를 줍습니다.', `MaleText_loc4`='回收瑟银齿轮轴。', `MaleText_loc5`='拿走瑟銀齒輪軸。', `MaleText_loc7`='Recupera la charnela de torio.', `FemaleText_loc1`='토륨 변속자루를 줍습니다.', `FemaleText_loc4`='回收瑟银齿轮轴。', `FemaleText_loc5`='拿走瑟銀齒輪軸。', `FemaleText_loc7`='Recupera la charnela de torio.' WHERE `ID`=48299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 마력 핵을 줍습니다. 희귀한 겁니다!', `MaleText_loc4`='回收石能核心。这些可是稀有物品！', `MaleText_loc5`='拿走石製能量核心。這東西很罕見!', `MaleText_loc7`='Recupera el núcleo de poder pétreo. ¡Son raros!', `FemaleText_loc1`='바위 마력 핵을 줍습니다. 희귀한 겁니다!', `FemaleText_loc4`='回收石能核心。这些可是稀有物品！', `FemaleText_loc5`='拿走石製能量核心。這東西很罕見!', `FemaleText_loc7`='Recupera el núcleo de poder pétreo. ¡Son raros!' WHERE `ID`=48300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응, 뭡니까?', `MaleText_loc4`='呃，什么？', `MaleText_loc5`='啊，什麼?', `MaleText_loc7`='Eh, ¿qué?' WHERE `ID`=48301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼른 짐 싸십시오, $n 님! 황혼의 고원으로 가야죠. 준비되셨습니까?', `MaleText_loc4`='整理行装，$n！我们即将前往暮光高地。你准备好了吗？', `MaleText_loc5`='打包好你的行李，$n!我們要去暮光高地了。準備好了嗎?', `MaleText_loc7`='¡Haz las maletas, $n! Nos vamos a las Tierras Altas Crepusculares. ¿Estás $glisto:lista;?' WHERE `ID`=48302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 준비됐습니다, 플린트로크. 황혼의 고원으로 데려가 주십시오!', `MaleText_loc4`='我准备好了，弗林特洛克。带我前往高地！', `MaleText_loc5`='我準備好了，燧鎖。帶我去高地!', `MaleText_loc7`='Estoy listo, Cierrasílex. ¡Llévame a las Tierras Altas!', `FemaleText_loc1`='전 준비됐어요, 플린트로크. 황혼의 고원으로 데려가 주세요!', `FemaleText_loc4`='我准备好了，弗林特洛克。带我前往高地！', `FemaleText_loc5`='我準備好了，燧鎖。帶我去高地!', `FemaleText_loc7`='Estoy lista, Cierrasílex. ¡Llévame a las Tierras Altas!' WHERE `ID`=48303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 신이시여! 이제 바지를 입을 테니 뒤로 돌게.', `MaleText_loc4`='感谢辰星！现在请转过身去，让我穿上。', `MaleText_loc5`='感謝天上繁星!好，轉過來，讓我把他們放上去。', `MaleText_loc7`='¡Gracias a las estrellas! Ahora date la vuelta para que pueda ponérmelos.', `FemaleText_loc1`='감사합니다, 신이시여! 이제 바지를 입을 테니 뒤로 돌게.', `FemaleText_loc4`='感谢辰星！现在请转过身去，让我穿上。', `FemaleText_loc5`='感謝天上繁星!好，轉過來，讓我把他們放上去。', `FemaleText_loc7`='¡Gracias a las estrellas! Ahora date la vuelta para que pueda ponérmelos.' WHERE `ID`=48304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 황혼의 고원에서 얼라이언스의 공동 작전을 지휘하게 되었네.$B$B독립적인 와일드해머 부족이 아직 이 고원 여기저기에 흩어져 살고 있다네. 만약 얼라이언스의 깃발 아래 그들을 모을 수 있다면, 아무도 우리를 막을 수 없을 걸세! 적이 사방에서 몰려오고 있네. 싸울 준비는 됐겠지, $c?', `MaleText_loc4`='我奉命担任暮光高地联盟联合行动的总指挥。$B$B特立独行的蛮锤部族仍散落在这附近的乡间各地。要是我们能将他们集结于联盟的战旗之下，就将变得势不可挡！可敌人正从四面八方逼近。希望你已经做好了迎战的准备，$c。', `MaleText_loc5`='我負責指揮聯盟部隊在暮光高地的協同作戰。$B$B獨立的蠻錘氏族依然零星散佈在鄉間各處，要是我們能說服他們加入聯盟，那就沒有東西能阻止我們了!可是，敵人正從四面八方包圍而來。我希望你已經做好了戰鬥的準備，$c。', `MaleText_loc7`='Me han puesto al mando de las operaciones conjuntas de la Alianza en las Tierras Altas Crepusculares.$b$bTodavía quedan clanes independientes de los Martillo Salvaje desperdigados por la zona. Si podemos unirlos bajo el estandarte de la Alianza, ¡nada podrá detenernos! Pero nuestros enemigos se acercan por todos lados. Espero que estés $glisto:lista; para la batalla, $c.' WHERE `ID`=48305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라이던!? 살아있었나?', `MaleText_loc4`='林度恩？！还活着？', `MaleText_loc5`='林度恩!?還活著?', `MaleText_loc7`='¡¿Lydon?! ¿Vivo?' WHERE `ID`=48306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 자네가 누구 편인지 알겠군, $n!', `MaleText_loc4`='我现在知道你在为谁效命了，$n！', `MaleText_loc5`='現在我知道你效忠的是誰了，$n!', `MaleText_loc7`='¡Ahora sé a quién le debes lealtad, $n!' WHERE `ID`=48307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고, 제니? 난 우리 사이에 뭔가 통하는 게 있었다고 생각했는데... 내 가슴을 또다시 무너뜨리는군.', `MaleText_loc4`='你呢，珍妮？我原以为在我们之间存在着某种联结。这是你最后一次伤我的心。', `MaleText_loc5`='還有你，潔妮?我還以為我們彼此仰慕呢。這是你最後一次害我心碎了。', `MaleText_loc7`='¿Y tú, Jenny? Creí que teníamos una conexión. Me has roto el corazón por última vez.' WHERE `ID`=48308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관 스틸워터, 너는 미쳤다. 우리 삶의 방식을 위협하는 놈이지. 어둠의 여왕님의 권한으로, 너에게 포세이큰 법에서 가장 가혹한 처벌... 바로 진정한 죽음을 내리겠다.', `MaleText_loc4`='看守者斯蒂沃特，你这疯子，你这威胁我们生活的毒瘤。奉黑暗女王之命，我来此对你施以被遗忘者律法所允许的最严厉惩罚——真正的死亡。', `MaleText_loc5`='管理員斯蒂沃特，你已經失去理智，而且對我們的生命安全造成了重大的威脅。奉黑暗女王親自下達之命令，我謹此對你下達被遺忘者律法中最嚴厲之刑罰—真正的死亡。', `MaleText_loc7`='Celador Aguaserena, estás trastornado y eres un peligro para tu propia vida. Por la autoridad que me ha conferido la Dama Oscura en persona, te condeno a la pena más dura que permite la ley Renegada: la muerte verdadera.' WHERE `ID`=48309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어리석은 놈을 도왔던 모든 배신자들도 같은 처벌을 받게 될 것이다!', `MaleText_loc4`='还有你们——与这蠢货同流合污的叛徒渣滓！', `MaleText_loc5`='並一體適用所有支持這蠢貨的叛徒!', `MaleText_loc7`='¡Y lo mismo va por toda la escoria traidora que ha apoyado a este loco!' WHERE `ID`=48310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎을 꿇어라!', `MaleText_loc4`='跪下！', `MaleText_loc5`='跪下!', `MaleText_loc7`='¡ARRODÍLLATE!' WHERE `ID`=48311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 위협이라고? 내가 미쳤다고?!', `MaleText_loc4`='我是威胁？我是疯子？！', `MaleText_loc5`='我是個威脅?我很瘋狂?!', `MaleText_loc7`='¿SOY UNA AMENAZA? ¿ESTOY TRASTORNADO?' WHERE `ID`=48312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이곳에 창조한 건 혁명이다! 포세이큰이 번성할 새로운 방법이지. 마법의 요정이 시체에 반짝이는 행복 가루를 뿌려대는 방식으로 번성하겠다고? 어림도 없다!', `MaleText_loc4`='我在这儿创造的一切叫做进化！这才是引领被遗忘者走向兴盛的正途，你以为往尸体上撒点亮闪闪的魔法粉尘就够了吗！', `MaleText_loc5`='我這裡所創造的是一種進化方式!這是讓被遺忘者興旺起來的方法，而不是透過一些有翅膀的魔法精靈灑些粉在屍體上!', `MaleText_loc7`='¡Lo que he creado es la evolución! ¡ASÍ es como prosperarán los Renegados, no gracias a un hada mágica que rocíe polvos chispeantes sobre unos cadáveres!' WHERE `ID`=48313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여라! 놈들은 다음 연구 재료로 쓸 것이다!', `MaleText_loc4`='杀光他们！正好可以把他们当做下次研究的实验对象！', `MaleText_loc5`='把他們全部殺光!他們會成為我們下一個研究的實驗體!', `MaleText_loc7`='¡Matadlos a todos! ¡Harán las veces de sujetos para nuestro próximo proyecto!' WHERE `ID`=48314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 왔어, 누나!', `MaleText_loc4`='我回来了，姐妹！', `MaleText_loc5`='我回來了，姊妹!', `MaleText_loc7`='¡Estoy de vuelta, hermanita!', `FemaleText_loc1`='나 왔어, 누나!', `FemaleText_loc4`='我回来了，姐妹！', `FemaleText_loc5`='我回來了，姊妹!', `FemaleText_loc7`='¡Estoy de vuelta, hermanita!' WHERE `ID`=48315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하느님 감사합니다! 무사히 돌아와서 정말... 바지는 왜 거꾸로 입었니?', `MaleText_loc4`='感谢上帝！见到你真高兴……你裤子怎么穿反了？', `MaleText_loc5`='謝天謝地!很高興見到...你的褲子為什麼穿反了?', `MaleText_loc7`='¡Gracias al cielo! Me alegro tanto de ver... ¿Por qué llevas los pantalones al revés?', `FemaleText_loc1`='하느님 감사합니다! 무사히 돌아와서 정말... 바지는 왜 거꾸로 입었니?', `FemaleText_loc4`='感谢上帝！见到你真高兴……你裤子怎么穿反了？', `FemaleText_loc5`='謝天謝地!很高興見到...你的褲子為什麼穿反了?', `FemaleText_loc7`='¡Gracias al cielo! Me alegro tanto de ver... ¿Por qué llevas los pantalones al revés?' WHERE `ID`=48316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야호!$b$b언젠가 한 번 더 해봐야겠소!$b$b자, 나는 연구를 하러 가봐야겠소. 준비되면 다시 얘기하리다.', `MaleText_loc4`='喔！$b$b我们一定要再这么干一次！$b$b好了，我要继续去做研究了。等我准备好了，我会来找你的。', `MaleText_loc5`='喔耶!$b$b我們要找時間再試一次!$b$b好吧，我要回去繼續研究了。等我準備好，我會再跟你說的。', `MaleText_loc7`='¡Guajuuuu!$b$b¡Tenemos que repetirlo alguna vez!$b$bBueno, me voy a investigar un poco. Me reuniré contigo cuando esté listo.' WHERE `ID`=48317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 아직은 아니오.', `MaleText_loc4`='不……还不行。', `MaleText_loc5`='不..還沒。', `MaleText_loc7`='No... aún no.' WHERE `ID`=48318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 잡종들아! 내가 너희 모두를 재빨리 죽여줘야겠구나!', `FemaleText_loc4`='你们这群愚蠢的杂种！我真该用鞭子把你们全都抽死！', `FemaleText_loc5`='你們這些蠢雜種!我要把你們鞭打到死!', `FemaleText_loc7`='¡Chuchos estúpidos! ¡Debería mataros a todos a azotes!' WHERE `ID`=48319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 늑대들은 쓸모가 없어! 쓸데가 없단 말이다!', `FemaleText_loc4`='你们这群蠢货毫无用处！毫无用处！', `FemaleText_loc5`='你們這些狼真沒用!沒用!!', `FemaleText_loc7`='¡Los lobos sois inútiles! ¡Inútiles!' WHERE `ID`=48320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 역겨운 똥개 녀석들, 내 채찍 맞을 즐겨야 할 거다!', `FemaleText_loc4`='你们这些卑劣的杂种最好尝尝我鞭子的滋味！', `FemaleText_loc5`='你們這些臭死人的傢伙最好喜歡我鞭子的滋味!', `FemaleText_loc7`='¡Espero que os guste el sabor de mi látigo, perros asquerosos!' WHERE `ID`=48321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피를 보게 해 주마, 약하기 짝이 없는 말라깽이 녀석들!', `FemaleText_loc4`='我要让你们鲜血四溅，你们这群没用的瘦皮囊！', `FemaleText_loc5`='我會讓你們這幾袋骨頭流出血來!', `FemaleText_loc7`='¡Os haré sangrar, sacos de huesos debiluchos!' WHERE `ID`=48322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='징징거리는 소리 그만해라, 쓸모없는 늑대 녀석들아!', `FemaleText_loc4`='别在呜咽了，没用的东西！', `FemaleText_loc5`='別再唉唉叫了，你們這些沒用的狼!', `FemaleText_loc7`='¡Dejad de quejaros, lobos inútiles!' WHERE `ID`=48323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겼다고 생각했나? 아직이다! 내 새로운 모습에 떨지나 마라!', `MaleText_loc4`='你以为你赢了？再想想吧！在我全新的形态面前战栗吧！', `MaleText_loc5`='你以為你們贏了嗎?看清楚吧!站在我的新形態面前顫抖吧!', `MaleText_loc7`='¿Crees que has ganado? ¡PIÉNSALO DE NUEVO! ¡Observa mi nueva forma y tiembla!' WHERE `ID`=48324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아! 우... 움직일 수가 없다!', `FemaleText_loc4`='啊！我……我动不了了！', `FemaleText_loc5`='啊!我...我動不了!', `FemaleText_loc7`='¡Ah! No... ¡No puedo moverme!' WHERE `ID`=48325;
