UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 사술을 걸어 버릴 테야! 너에게 사술을 걸어 버릴 테야! 너에게 사술을 걸어 버릴 테야!', `MaleText_loc4`='诅咒你！诅咒你！诅咒你！', `MaleText_loc5`='給你咒咒!給你咒咒!', `MaleText_loc7`='¡TE MALDIGO! ¡TE MALDIGO! ¡TE MALDIGO!' WHERE `ID`=48329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 고를로프 움직일 수가 없다! 고를로프 떨어진다!', `MaleText_loc4`='喔咦！葛洛普动不了了！格尔洛普要倒下了！', `MaleText_loc5`='噢喔!戈洛普不能動!戈洛普會跌倒!', `MaleText_loc7`='¡OWIE! ¡GORLOP NO PODER MOVERSE! ¡GORLOP CAER!' WHERE `ID`=48330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 거기 당신! 보물 갖고 싶어? 금이랑 반짝이 어디 가면 있는지 오우는 알지. 오우 따라서 톨비르의 잃어버린 도시 갈 테야? 오우 안 훔친다고 약속한다.', `MaleText_loc4`='嘿！说你呢！想发财吗？奥弗知道哪儿有金币和财宝。跟奥弗去托维尔失落之城走一趟怎么样？奥弗保证不偷不抢。', `MaleText_loc5`='嘿!你!你要寶藏嗎?奧各知道哪裡找得到金幣和珠寶。要跟奧各去托維爾的失落之城嗎?奧各答應不偷東西。', `MaleText_loc7`='¡EH! ¡Tú! ¿Tú querer tesoro? Augh sabe dónde conseguir oros y cosas brillantes. ¿Seguir a Augh a la Ciudad Perdida de Tol''vir? Augh promete no robar.' WHERE `ID`=48331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우라니, 왠지 믿음직한 이름이군요. 안내해 주십시오!', `MaleText_loc4`='奥弗这名字听起来值得信任。带路吧！', `MaleText_loc5`='奧各聽起來像是個值得信任的名字。帶路吧!', `MaleText_loc7`='Augh es un nombre que me inspira confianza. ¡Indícame el camino!', `FemaleText_loc1`='오우라니, 왠지 믿음직한 이름이군요. 안내해 주세요!', `FemaleText_loc4`='奥弗这名字听起来值得信任。带路吧！', `FemaleText_loc5`='奧各聽起來像是個值得信任的名字。帶路吧!', `FemaleText_loc7`='Augh es un nombre que me inspira confianza. ¡Indícame el camino!' WHERE `ID`=48332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격하게 윤내는 중', `MaleText_loc4`='全力完善中', `MaleText_loc5`='精神旺盛地擦拭著', `MaleText_loc7`='Puliendo vigorosamente', `FemaleText_loc1`='격하게 윤내는 중', `FemaleText_loc4`='全力完善中', `FemaleText_loc5`='精神旺盛地擦拭著', `FemaleText_loc7`='Puliendo vigorosamente' WHERE `ID`=48333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 용암 뜨겁다.', `MaleText_loc4`='这熔岩可真烫。', `MaleText_loc5`='這裡熔岩燙燙。', `MaleText_loc7`='Esta lava caliente.' WHERE `ID`=48334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고를로프 다른 용암도 뜨거운지 궁금한데?', `MaleText_loc4`='格尔洛普不知别的熔岩是不是也这么烫？', `MaleText_loc5`='戈洛普不知道其他熔岩也燙燙嗎?', `MaleText_loc7`='Gorlop preguntarse si la otra lava también caliente.' WHERE `ID`=48335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 자네를 죽음의 문턱에서 끌어냈네, $G형제여:자매여;. 자네의 도움이 필요하네!', `MaleText_loc4`='是我把你从死亡线上拉了回来，$G兄弟:姐妹;。我们现在需要你的帮助！', `MaleText_loc5`='我把你從死亡邊緣救回來，$G兄弟:姊妹;。我們需要你的幫助!', `MaleText_loc7`='Te traigo de regreso del filo de la muerte, $ghermano:hermana;. ¡Necesitamos tu ayuda!' WHERE `ID`=48336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 지금껏 온갖 뒤틀린 일들을 해왔소. 하지만 당신이 하려는 일은 내가 상상조차 하지 못할 일이오.', `MaleText_loc4`='我干过一些相当变态的事，可你在这儿的所作所为就连我也望尘莫及。', `MaleText_loc5`='我做過一些相當扭曲的事情，但是你在這裡做的，甚至超過了我能接受的限度。', `MaleText_loc7`='He hecho cosas bastante retorcidas, pero lo que estás haciendo aquí se pasa de la raya hasta para mí.' WHERE `ID`=48337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 당신이 이놈들을 자유롭게 놔준다 해도 아무에게도 말 안 하겠소.', `MaleText_loc4`='知道吗，你可以就这么放了他们。我不会告诉任何人。', `MaleText_loc5`='你知道嗎，你可以放他們走就好。我不會告訴別人。', `MaleText_loc7`='Probablemente podrías liberarlos sin más, ¿sabes? No se lo diré a nadie.' WHERE `ID`=48338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만하시오! 내 로브에 피가 튀지 않소.', `MaleText_loc4`='够了！你把血弄得我全身都是。', `MaleText_loc5`='夠了喔!你弄得我的袍子上都沾滿了血。', `MaleText_loc7`='¡YA BASTA! Me estás manchando la toga de sangre.' WHERE `ID`=48339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 문제가 좀 있는 것 같군.', `MaleText_loc4`='你有问题。', `MaleText_loc5`='你的問題不小。', `MaleText_loc7`='Tienes problemas.' WHERE `ID`=48340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역겹군. 머리가 없으면 아무 쓸모도 없소.', `MaleText_loc4`='真恶心。这些没有头的家伙对我们毫无价值。', `MaleText_loc5`='真噁心。他們沒有頭的話，對我們一點用處都沒有。', `MaleText_loc7`='Repugnante. No nos sirven sin cabeza.' WHERE `ID`=48341;
