UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 아주 나쁜 사람입니다.', `MaleText_loc4`='你真是个坏人。', `MaleText_loc5`='你是個很壞的人。', `MaleText_loc7`='Eres muy mala persona.' WHERE `ID`=48346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 당신의 도움에 감사하오, $n. 하지만 이 고통이 끝나기 전에 더 큰 빚을 지게 될 것만 같아 두렵소.', `MaleText_loc4`='感谢你所做的一切，$n。可在我们彻底通过这次考验前，恐怕我会欠你更多人情。', `MaleText_loc5`='我很感謝你做的一切，$n。但是我擔心在這場苦難結束之前，我還會欠你更多。', `MaleText_loc7`='Te agradezco lo que has hecho, $n. Pero me temo que quedaré aún más en deuda contigo antes de que termine este asunto.' WHERE `ID`=48347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...', `MaleText_loc4`='……', `MaleText_loc5`='...', `MaleText_loc7`='...', `FemaleText_loc1`='...', `FemaleText_loc4`='……', `FemaleText_loc5`='...', `FemaleText_loc7`='...' WHERE `ID`=48348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 품위 있는 모습으로 돌아갈 수 있어!', `MaleText_loc4`='现在我可以带着尊严回去了！', `MaleText_loc5`='現在我可以有尊嚴地回去了!', `MaleText_loc7`='¡Ahora puedo volver con dignidad!', `FemaleText_loc1`='이제 품위 있는 모습으로 돌아갈 수 있어!', `FemaleText_loc4`='现在我可以带着尊严回去了！', `FemaleText_loc5`='現在我可以有尊嚴地回去了!', `FemaleText_loc7`='¡Ahora puedo volver con dignidad!' WHERE `ID`=48349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 적은 이 도시 전체를 모래로 덮어버릴 수도 있다. 애석하게도 우리의 역사는 이런 전쟁을 대비할 수 있는 가르침을 주지 않았다.', `MaleText_loc4`='我们的敌人能把整座城市用沙土掩埋。我们的传统并未让我们做好应对此战的准备。', `MaleText_loc5`='我們的敵人可以把整座城市埋進沙裡。我們的傳統方式沒讓我們準備好這樣的戰爭。', `MaleText_loc7`='Nuestros enemigos pueden enterrar ciudades enteras en la arena. Nuestras tradiciones no nos han preparado para semejante guerra.' WHERE `ID`=48350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 지나면, 이곳을 재건하여 과거의 영광을 되찾을 걸세. 거슬리는 인간들은 모조리 쓸어버리고 말이야.', `MaleText_loc4`='我们终将重建这里，并使其复现往日的荣光——除去那些麻烦的人类。', `MaleText_loc5`='隨著時間過去，我們可以重建這個地方並回復它從前的光芒。這次不包括那些煩人的人類。', `MaleText_loc7`='Con el tiempo reconstruiremos este lugar y le devolveremos su antigua gloria... Sin esos engorrosos humanos.' WHERE `ID`=48351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 끔찍한 섬을 점령했으니 정리 작업을 시작해야겠소. 우릴 좀 도와주겠소, $n?', `MaleText_loc4`='既然我们已经夺取了这座该死的岛屿，我们就得做些什么来让它变得像模像样。你能帮帮我们吗，$n？', `MaleText_loc5`='現在我們既然佔領了這座可悲的島嶼，我們需要做些工作來整頓一番。你能幫我們嗎，$n?', `MaleText_loc7`='Ahora que hemos capturado esta maldita isla, tenemos que ponernos manos a la obra para dejarla en condiciones. ¿Puedes ayudarnos, $n?', `FemaleText_loc1`='이제 이 끔찍한 섬을 점령했으니 정리 작업을 시작해야겠소. 우릴 좀 도와주겠소, $n?', `FemaleText_loc4`='既然我们已经夺取了这座该死的岛屿，我们就得做些什么来让它变得像模像样。你能帮帮我们吗，$n？', `FemaleText_loc5`='現在我們既然佔領了這座可悲的島嶼，我們需要做些工作來整頓一番。你能幫我們嗎，$n?', `FemaleText_loc7`='Ahora que hemos capturado esta maldita isla, tenemos que ponernos manos a la obra para dejarla en condiciones. ¿Puedes ayudarnos, $n?' WHERE `ID`=48352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 모두가 한창 얘기하는 저 D 구역을 나는 썩 좋아하지 않소. 우리가 저곳을 사용하려면 먼저 처리해야 할 일이 있소.', `MaleText_loc4`='我对那个人人交口谈论的恶魔监狱不感兴趣。不过我们确实得先完成些任务才能让这地方为己所用。', `MaleText_loc5`='我並不喜歡那個大家都在談論的D區。但是在我們開始使用它之前，我們的確有些工作得進行。', `MaleText_loc7`='No soy un fanático de ese Bloque D del que habla todo el mundo. Sin embargo, hay algunas tareas que tenemos que completar antes de que podamos usarlo.', `FemaleText_loc1`='요즘 모두가 한창 얘기하는 저 D 구역을 나는 썩 좋아하지 않소. 우리가 저곳을 사용하려면 먼저 처리해야 할 일이 있소.', `FemaleText_loc4`='我对那个人人交口谈论的恶魔监狱不感兴趣。不过我们确实得先完成些任务才能让这地方为己所用。', `FemaleText_loc5`='我並不喜歡那個大家都在談論的D區。但是在我們開始使用它之前，我們的確有些工作得進行。', `FemaleText_loc7`='No soy una fanática de ese Bloque D del que habla todo el mundo. Sin embargo, hay algunas tareas que tenemos que completar antes de que podamos usarlo.' WHERE `ID`=48353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 깊은 구멍에 대한 얘기를 들었을 것이오. 아직 못 들었다면 이제 그곳에 대해 많은 사실을 알게 될 것이오.', `MaleText_loc4`='我想你应该已经听说那个洞了，$r。如果还没有，那你很快就会听到许多与其有关的事情。', `MaleText_loc5`='我猜你現在已經聽說過那個洞了，$r。如果還沒有，你很快就會聽到一大堆關於它的事情。', `MaleText_loc7`='Supongo que a estas alturas ya habrás oído hablar del agujero, $r. Si no, pronto vas a saber mucho sobre él.', `FemaleText_loc1`='당신도 깊은 구멍에 대한 얘기를 들었을 것이오. 아직 못 들었다면 이제 그곳에 대해 많은 사실을 알게 될 것이오.', `FemaleText_loc4`='我想你应该已经听说那个洞了，$r。如果还没有，那你很快就会听到很多与其有关的事情。', `FemaleText_loc5`='我猜你現在已經聽說過那個洞了，$r。如果還沒有，你很快就會聽到一大堆關於它的事情。', `FemaleText_loc7`='Supongo que a estas alturas ya habrás oído hablar del agujero, $r. Si no, pronto vas a saber mucho sobre él.' WHERE `ID`=48354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨 바라드에 온 걸 환영합니다. 허비할 시간이 없으니 바로 일을 시작해야겠군요.', `MaleText_loc4`='欢迎来到托尔巴拉德，$c。时间紧迫，我们开始吧。', `MaleText_loc5`='歡迎來到托巴拉德，$c。我們在浪費時間，趕快開始工作吧。', `MaleText_loc7`='$gBienvenido:Bienvenida; a Tol Barad, $c. Nos falta tiempo, así que a trabajar.', `FemaleText_loc1`='톨 바라드에 온 걸 환영합니다. 허비할 시간이 없으니 바로 일을 시작해야겠군요.', `FemaleText_loc4`='欢迎来到托尔巴拉德，$c。时间紧迫，我们开始吧。', `FemaleText_loc5`='歡迎來到托巴拉德，$c。我們在浪費時間，趕快開始工作吧。', `FemaleText_loc7`='$gBienvenido:Bienvenida; a Tol Barad, $c. Nos falta tiempo, así que a trabajar.' WHERE `ID`=48355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사악한 악마야! 내 동생에게 무슨 짓을 한 거냐?', `MaleText_loc4`='无耻的恶魔！你对我兄弟做了什么？', `MaleText_loc5`='骯髒的惡魔!你對我的兄弟做了什麼?', `MaleText_loc7`='¡Demonio infecto! ¿Qué has hecho con mi hermano?' WHERE `ID`=48356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을 팔아넘긴 대가로 말이냐? 넌 이제 내 동생이 아니다! 이곳에서 썩 사라져라! 그리고 다시는 이 땅에 발을 들이지 마라!', `MaleText_loc4`='以你的灵魂为代价？你再也不是我的兄弟了！离开这里，永远不要再踏上我们的土地！', `MaleText_loc5`='用你的靈魂為代價?你不是我的兄弟!滾出這個地方，別再踏上我們的土地!', `MaleText_loc7`='¿A costa de tu alma? ¡No eres mi hermano! ¡Abandona este lugar, y no vuelvas a poner un pie en nuestras tierras!' WHERE `ID`=48357;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 일리단. 어째서 그런 짓을?', `FemaleText_loc4`='不！伊利丹，你怎么可以？', `FemaleText_loc5`='不!伊利丹，你為什麼這麼做?', `FemaleText_loc7`='¡No! Illidan, ¿cómo has podido?' WHERE `ID`=48358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나야, 형! 이런 모습이지만...', `MaleText_loc4`='是我，玛法里奥。这就是我现在的样子。', `MaleText_loc5`='是我，瑪法里恩。我變成了這副德性。', `MaleText_loc7`='Soy yo, Malfurion. Esto es en lo que me he convertido.' WHERE `ID`=48359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드의 우두머리를 처치했어. 시간이 지나면 숲도 회복될 거야.', `MaleText_loc4`='亡灵的首领已被消灭，森林的伤痛终将痊愈。', `MaleText_loc5`='不死族的領袖已經被殺了，森林會隨著時間痊癒。', `MaleText_loc7`='El líder de los no-muertos ha caído, y los bosques se curarán con el tiempo.' WHERE `ID`=48360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소원대로 해주지... 형.', `MaleText_loc4`='就这样吧……兄弟。', `MaleText_loc5`='好吧...兄弟。', `MaleText_loc7`='Que así sea... hermano.' WHERE `ID`=48361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니? 넌... 넌 누구냐?', `MaleText_loc4`='什么？你是……谁？', `MaleText_loc5`='什麼?你是...誰?', `MaleText_loc7`='¿Qué? ¿Quién... eres?' WHERE `ID`=48362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 전쟁에 뛰어들기로 한 게 아니네, $n. 전쟁이 우리에게 왔지.$B$B우린 이를 대비하는 데 필요한 일을 해야만 하네.', `MaleText_loc4`='我们没有选择战争，$n。是战争选择了我们。$B$B我们必须竭尽全力去应对。', `MaleText_loc5`='我們並沒有選擇戰爭，$n。是戰爭降臨在我們身上。$B$B我們得做好必要的準備。', `MaleText_loc7`='No elegimos ir a la guerra, $n. La guerra viene a nosotros.$b$bDebemos hacer todo lo posible por estar preparados.' WHERE `ID`=48363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 보이는 건가...', `MaleText_loc4`='它能看见我们……', `MaleText_loc5`='它看見我們...', `MaleText_loc7`='Nos ve...' WHERE `ID`=48364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞을 보지 못하게 해주지!', `MaleText_loc4`='把它的眼睛挖出来！', `MaleText_loc5`='把它的眼睛挖出來!', `MaleText_loc7`='¡Arrancadle los ojos!' WHERE `ID`=48365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무에게도 말하지 못하게 해주마!', `MaleText_loc4`='你别想告诉任何人！', `MaleText_loc5`='你不會跟任何人說!', `MaleText_loc7`='¡No se lo contarás a nadie!' WHERE `ID`=48366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다...', `MaleText_loc4`='入侵者……', `MaleText_loc5`='入侵者...', `MaleText_loc7`='Intruso...' WHERE `ID`=48367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 보지 못해, 이 커다란 보라색 눈알 자식아! 아, 다 집어치웁시다, $n 님.', `MaleText_loc4`='别盯着我看，你这紫眼睛的大胖脸！啊，全都炸光，$n。', `MaleText_loc5`='不要再盯著我看了，你這紫眼大臉的傢伙!啊，我不管了，$n。', `MaleText_loc7`='¡Deja de mirarme, monstruo de ojos saltones! Ah, a la porra con todo, $n.' WHERE `ID`=48368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 오크들하고 계약하긴 쉽지가 않다고. 이봐, 무슨 뜻인지 잘 알잖아! 검은바위 오크란 말이야! 그자들은 아그라마르보다 더 많은 전투를 치른 데다가 그것도 검은무쇠 부족이 만든 산에 진 치고 있다고! 와우!', `MaleText_loc4`='跟黑石兽人达成约定可不是件容易的事儿。我是说，拜托！是黑石兽人哎！这些家伙所经历的战争比阿格拉玛还要多，而且他们还住在黑铁矿堆成的山上！酷毙了！', `MaleText_loc5`='和黑石的獸人簽約很不容易。想想看，黑石獸人!這些傢伙經歷的戰鬥比阿格拉瑪還多，而且他們可是坐在一座黑鐵構成的山上!油水可肥了!', `MaleText_loc7`='No está resultando fácil conseguir un contrato con los orcos Roca Negra. ¡Venga, hombre! ¡Los orcos Roca Negra! Esos tipos han estado en más batallas que Aggramar. Y por si fuera poco viven en una montaña hecha de hierro negro. ¡Oigo cómo la caja hace cliiiing!' WHERE `ID`=48369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 죽으면 이야기가 달라지겠지!', `MaleText_loc4`='你的死亡将使一切变得不同！', `MaleText_loc5`='等你死了以後，結果就不一樣了!', `MaleText_loc7`='¡Tu muerte será una cosa totalmente diferente!' WHERE `ID`=48370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드의 모습으로 변장한 악마인 너를 처단하겠다, 나바락스... 설사 그게 네 진짜 이름이라고 해도!', `MaleText_loc4`='你被控是个乔装打扮的恶魔，纳瓦雷克斯……如果那是你的真名！', `MaleText_loc5`='你被指控是由惡魔所偽裝的，納瓦拉克斯...我們甚至不知道那是不是你的真名!', `MaleText_loc7`='Se te acusa de ser un demonio disfrazado, Navarax... ¡Si ese es tu verdadero nombre!', `FemaleText_loc1`='대드루이드의 모습으로 변장한 악마인 너를 처단하겠다, 나바락스... 설사 그게 네 진짜 이름이라고 해도!', `FemaleText_loc4`='你被控是个乔装打扮的恶魔，纳瓦雷克斯……如果那是你的真名！', `FemaleText_loc5`='你被指控是由惡魔所偽裝的，納瓦拉克斯...我們甚至不知道那是不是你的真名!', `FemaleText_loc7`='Se te acusa de ser un demonio disfrazado, Navarax... ¡Si ese es tu verdadero nombre!' WHERE `ID`=48371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용암 군주와 대결해 보고 싶습니다.', `MaleText_loc4`='我要跟你的熔岩领主打一场。', `MaleText_loc5`='我想要和你們的熔岩領主單挑!', `MaleText_loc7`='Me gustaría desafiar al señor del magma a un combate.', `FemaleText_loc1`='당신의 용암 군주와 대결해 보고 싶어요.', `FemaleText_loc4`='我要跟你的熔岩领主打一场。', `FemaleText_loc5`='我想要和你們的熔岩領主單挑!', `FemaleText_loc7`='Me gustaría desafiar al señor del magma a un combate.' WHERE `ID`=48372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이십니까?', `MaleText_loc4`='嗯，孩子？', `MaleText_loc5`='什麼事，我的孩子?', `MaleText_loc7`='¿Sí, $ghijo mío:hija mía;?' WHERE `ID`=48373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아주 때맞춰 등장했군!$b$b내 생각엔, 우리와 저 슈노츠라는 친구의 악연이 끝난 것 같지 않소.', `MaleText_loc4`='幸好我及时出现了！$b$b我想我们还没见到那最后一个司克诺兹成员。', `MaleText_loc5`='我到的正是時候!$b$b我猜我們還會再見到那個叫舒諾茲的傢伙。', `MaleText_loc7`='¡Qué suerte que yo apareciera cuando lo hice!$b$bSupongo que todavía no hemos visto el final de ese tal Schnottz.' WHERE `ID`=48374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 친구들. 도전자가 왔다! 우리가 잡아 놓은 작은 친구가 뭘 할 수 있는지 대중들께 보여줄 시간이다!', `MaleText_loc4`='好吧兄弟们，我们有挑战者了！是时候让将军见识下我们小俘虏的本事！', `MaleText_loc5`='好吧孩子們，我們有挑戰者了!讓我們將軍看看咱們的小囚犯有什麼能耐!', `MaleText_loc7`='¡Muy bien, muchachos, tenemos un contendiente! ¡Es hora de enseñarle al general lo que puede hacer nuestro pequeño cautivo!' WHERE `ID`=48375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애! 내 아가가...', `MaleText_loc4`='不——！我的宝贝儿……', `MaleText_loc5`='不!我的寶寶...', `MaleText_loc7`='¡Nooooo! Mi bebé...' WHERE `ID`=48376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노분도! 안 돼애애!', `MaleText_loc4`='努波顿！不——！', `MaleText_loc5`='諾柏多!不!!!', `MaleText_loc7`='¡NOBUNDO! ¡NOOOO!' WHERE `ID`=48377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 수호자여, 너는 오늘 죽을 것이다! 그리고 $n|1이;가; 그 장면을 똑똑히 볼 것이다!', `MaleText_loc4`='今天就是你的死期，大地守护者！$n会亲自解决你！', `MaleText_loc5`='今天就是你的忌日，大地守護者!$n會確保這一點!', `MaleText_loc7`='¡Hoy morirás, Guardián de la Tierra! ¡$n se encargará de ello!' WHERE `ID`=48379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라... 어떻게 이런 일이... 이럴 수는 없어...', `MaleText_loc4`='阿格娜……这不可能……这太过火了……', `MaleText_loc5`='阿格拉...這不可能...這太超過了...', `MaleText_loc7`='Aggra... No puede ser... Esto ha ido demasiado lejos.' WHERE `ID`=48380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라도 좀 해 보게, 쓸모없는 $r 같으니. 내 동료들이 자네를 위해 목숨을 바치고 있네!', `MaleText_loc4`='快做点儿什么，你这没用的$r。我的盟友在为你献出生命！', `MaleText_loc5`='做些什麼，你這個沒用的$r。我的盟友正在為你犧牲生命!', `MaleText_loc7`='Haz algo, $r inútil. ¡Mis aliados están dando sus vidas por ti!' WHERE `ID`=48381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀른이 쓰러졌구나! 그리고 대지 고리회도 그와 함께 죽었다.', `MaleText_loc4`='穆恩死了！大地之环也随他一同消亡了。', `MaleText_loc5`='穆倫倒下了!陶土議會也隨著他消滅了!', `MaleText_loc7`='¡Muln cae! Y el Anillo de la Tierra muere con él.' WHERE `ID`=48382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 우리 모두를 실망시켰네, $n. 데스윙이 이겼네. 이 세상은 이제 끝장일세.', `MaleText_loc4`='你令我们所有人失望了，$n。死亡之翼赢了。世界的末日已至。', `MaleText_loc5`='你讓我們全部人失望了，$n。死亡之翼贏了。這個世界註定要毀滅了。', `MaleText_loc7`='Nos has fallado a todos, $n. Alamuerte ha ganado. El mundo está condenado.' WHERE `ID`=48383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나세요! 우리에겐 당신이 필요합니다, $n 님!', `MaleText_loc4`='快醒醒！我们需要你，$n！', `MaleText_loc5`='起來!我們需要你，$n!', `MaleText_loc7`='¡Despierta! ¡Te necesitamos, $n!', `FemaleText_loc1`='일어나세요! 우리에겐 당신이 필요합니다, $n 님!', `FemaleText_loc4`='快醒醒！我们需要你，$n！', `FemaleText_loc5`='起來!我們需要你，$n!', `FemaleText_loc7`='¡Despierta! ¡Te necesitamos, $n!' WHERE `ID`=48384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암 군주가 지금 좀... 내켜하지 않는다고. 주위에 있게나. 일 이 분 이상 안 걸릴 거야.', `MaleText_loc4`='熔岩领主现在有点儿……不对劲。别走远，这用不了一两分钟的时间。', `MaleText_loc5`='熔岩領主他...現在有點不適。稍微等一下，應該過一兩分鐘就好了。', `MaleText_loc7`='El señor del magma está un poco... indispuesto en este momento. No te vayas, no tardará más de un minuto o dos.' WHERE `ID`=48385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 포위당했네! 방어가 너무나도 강력하군. $n! 일어나게!', `MaleText_loc4`='我们被包围了！它的防御太强大了。$n！快醒醒！', `MaleText_loc5`='我們被包圍了!它的防禦太強了。$n!快起來!', `MaleText_loc7`='¡Estamos rodeados! Sus defensas son demasiado fuertes. ¡$n! ¡Despierta!' WHERE `ID`=48386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하! 잘했네!', `MaleText_loc4`='啊哈哈！干得好！', `MaleText_loc5`='啊哈哈哈!幹得好!', `MaleText_loc7`='¡Ja, ja, ja! ¡Bien hecho!' WHERE `ID`=48387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크의 말을 들어라. 틀린 말은 아니니.', `MaleText_loc4`='听听那个兽人的话。他说得有理。', `MaleText_loc5`='聽聽這個獸人說的話。他說得有道理。', `MaleText_loc7`='Escucha al orco. Tiene razón.' WHERE `ID`=48388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 위상에게 맞서는 전투에 참가할 위대한 영웅이 바로 너인가?', `MaleText_loc4`='你就是那个前来对抗死亡的化身的伟大勇士？', `MaleText_loc5`='你就是來和死亡化身作戰的偉大勇士?', `MaleText_loc7`='¿Tú eres $gel gran campeón:la gran campeona; que ha venido a luchar contra el Aspecto de la Muerte?' WHERE `ID`=48389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 종말을 안겨 준다는 영웅이 바로 너인가?', `MaleText_loc4`='你就是那个要将我毁灭的大英雄？', `MaleText_loc5`='你就是能消滅我的英雄?', `MaleText_loc7`='¿Tú eres $gel héroe:la heroína; que iba a ejecutar mi caída?' WHERE `ID`=48390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무력하구나. 넌 그 바위를 떠날 수조차 없어.', `MaleText_loc4`='你可真没用。你甚至不能离开那块石头。', `MaleText_loc5`='你根本就軟弱無助。你甚至無法離開那塊石頭。', `MaleText_loc7`='Estás $gindefenso:indefensa;. Ni siquiera puedes abandonar esa roca.' WHERE `ID`=48391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 동족을 실망시켰다. 넌 아제로스의 모든 생명을 실망시켰다. 바로 너 때문에, 네가 아는 모든 이가 죽을 것이다... 끔찍하고 고통스럽게.', `MaleText_loc4`='你令你的种族失望。你令艾泽拉斯的所有生灵蒙羞。因为你，你所认识的每个人都将死去……可怖而痛苦地死去。', `MaleText_loc5`='你讓你們的種族失望了。你讓艾澤拉斯的全體生命都失望了。因為你，所有你認識的事物都會死去...痛苦而恐怖地死去。', `MaleText_loc7`='Has fallado a tu raza. Has fallado a toda la vida de Azeroth. Por tu culpa, todas las personas que has conocido jamás morirán... horrible y dolorosamente.' WHERE `ID`=48392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 오아시스를 향해 출발해야 하오, $n.$b$b떠날 준비는 됐소?', `MaleText_loc4`='我们得动身前往绿洲了，$n。$b$b你准备好出发了吗？', `MaleText_loc5`='我們需要前往綠洲，$n。$b$b你準備好了嗎?', `MaleText_loc7`='Tenemos que llegar al oasis, $n.$b$b¿Estás $glisto:lista; para partir?' WHERE `ID`=48393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<마치 당신을 바라보듯, 나뭇잎을 당신 쪽으로 기울이는 새싹>', `MaleText_loc4`='<秧苗的叶子指向你，仿佛在注视着你所在的方向。>', `MaleText_loc5`='<幼苗把它的葉子轉向你，就像是在往你的方向看似的。>', `MaleText_loc7`='<El esqueje inclina sus hojas hacia ti, como si estuviera mirando en tu dirección.>' WHERE `ID`=48394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중하시오, $n.$b$b슈노츠보다 먼저 약속의 성궤를 찾아야 하오!', `MaleText_loc4`='集中精神，$n。$b$b我们必须赶在司克诺兹的前面拿到应许约柜！', `MaleText_loc5`='專心，$n。$b$b我們必須趕在舒諾茲之前抵達應許法櫃!', `MaleText_loc7`='Concéntrate, $n.$b$b¡Tenemos que conseguir el Arca de la promesa antes que Schnottz!' WHERE `ID`=48395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내부자의 소행이 틀림없어!$b$b모든 사람을 의심해야 한다고!', `MaleText_loc4`='这显然是内鬼干的！$b$b谁也摆脱不了嫌疑！', `MaleText_loc5`='這一定是內應搞的鬼!$b$b所有人都有嫌疑!', `MaleText_loc7`='¡Está claro tenemos un topo entre nosotrrros!$b$b¡Nadie está lifre de sospecha!' WHERE `ID`=48396;
