UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 이제 당신과 그 사자가 무슨 일을 할 수 있는지 봅시다.', `MaleText_loc4`='很好，让我们看看你和你的狮子们能做些什么。', `MaleText_loc5`='好吧。咱們看看你和你的獅子能做些什麼。', `MaleText_loc7`='De acuerdo. Veamos qué pueden hacer tus leones y tú.', `FemaleText_loc1`='좋아요. 이제 당신과 그 사자가 무슨 일을 할 수 있는지 보자고요.', `FemaleText_loc4`='很好，让我们看看你和你的狮子们能做些什么。', `FemaleText_loc5`='好吧。咱們看看你和你的獅子能做些什麼。', `FemaleText_loc7`='De acuerdo. Veamos qué pueden hacer tus leones y tú.' WHERE `ID`=48441;
