UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 머리로 바위 쳤으면 좋겠나?', `MaleText_loc4`='你想让我拿你的脑袋去砸石头？', `MaleText_loc5`='你要我用你的頭打石頭?', `MaleText_loc7`='¿Quieres yo hacerte golpear roca con la cabeza?' WHERE `ID`=48444;
