UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 마지막입니다! 놈들이 최후의 공격을 벌이고 있습니다. 이젠 도망갈 곳도 없습니다. 우리는 썬더마를 지켜내거나, 아니면 망치를 손에 쥔 채로 전사할 것입니다.$B$B와일드해머를 위하여!!', `MaleText_loc4`='该来的还是来了！他们正在发起最后的猛攻。我们已无路可退。唯有坚守桑德玛尔或手握战锤而死。$B$B为了蛮锤部族！！', `MaleText_loc5`='來了!他們要進行最終的進攻了。我們無處可逃。我們必須守住桑德瑪，不然就握著錘子死去吧。$B$B為了蠻錘!', `MaleText_loc7`='¡Ya está! Van a realizar su asalto final. No hay lugar al que huir. Defenderemos Bramal o moriremos con el martillo en la mano.$b$b¡¡Por los Martillo Salvaje!!' WHERE `ID`=48446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으름뱅이 코볼트 맛있게 생겼다!', `MaleText_loc4`='磨洋工的家伙总能令我胃口大开！', `MaleText_loc5`='慢吞吞的狗頭人看起來真好吃!', `MaleText_loc7`='¡Kóbold lento tener pinta sabrosa!' WHERE `ID`=48447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 양초 한 상자 있다! 너 바위 잘 부수면 하나 줄지도 모른다!', `MaleText_loc4`='我有一大盒蜡烛！要是你们好好干，我也许会分你们几根！', `MaleText_loc5`='我有一整盒蠟燭!石頭打得好就給你一些!', `MaleText_loc7`='¡Yo tener una caja entera de velas! ¡Quizá darte alguna si tú golpear roca bien!' WHERE `ID`=48448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 주먹 맛 보고 싶나? 당장 바위 부숴라!', `MaleText_loc4`='你想挨揍吗？赶紧挖矿！', `MaleText_loc5`='你想被扁嗎?快打死石頭!', `MaleText_loc7`='¿Tú querer que te de puñetazo? ¡Has hecho morir a roca!' WHERE `ID`=48449;
