UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언의 영상이 먹구름이 낀 듯 흐릿하군... 여기 이 강물처럼.', `MaleText_loc4`='视野一片模糊……跟这些水一样。', `MaleText_loc5`='景象一片模糊...就跟這些被污染的水源一樣。', `MaleText_loc7`='Las visiones son turbias... como estas aguas.' WHERE `ID`=48471;
