UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자?! 화염술사, 놈들을 불태워라! 이단자들에게 라그나로스 화염의 뜨거운 맛을 보여줘라!', `MaleText_loc4`='入侵者？！炎术师，烧光他们！让那些无信仰者看看拉格纳罗斯烈焰的力量！', `MaleText_loc5`='入侵者?!火占師，燒死他們!讓這些異教徒見識拉格納羅斯的火焰!', `MaleText_loc7`='¡¿Intrusos?! ¡Quémalos, piromántico! ¡Muestra a esos herejes el poder de la LLAMA DE RAGNAROS!' WHERE `ID`=48479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염술사여, 불의 군주에 대한 너의 충성심을 잘 알고 있다.', `MaleText_loc4`='炎魔之王不会忽视你的忠心，炎术师。', `MaleText_loc5`='火占師，你們對炎魔的忠心侍奉並沒有白費。', `MaleText_loc7`='Tu leal servicio al Señor del Fuego no ha pasado desapercibido, piromántico.' WHERE `ID`=48480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 용맹스러운 공격에 대한 소문이 주인님의 귀에까지 들어갔다. 초갈 님도 매우 기뻐하고 계신다.', `MaleText_loc4`='你在地表立下的英勇战功甚至都已经传到了我们主人的耳中；古加尔本人非常满意。', `MaleText_loc5`='你在地面上大膽的攻擊已經傳到我們主人的耳裡;丘加利非常高興。', `MaleText_loc7`='Las historias sobre tus valientes ataques en la superficie han llegado incluso a oídos de nuestro maestro; Cho''gall está muy satisfecho.' WHERE `ID`=48481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 계속하라. 놈들의 도시를 재로 바꿔 버려라! 신성한 불꽃과 함께!', `MaleText_loc4`='我们要继续进攻，直到他们的首都化为灰烬！在圣火中狂欢吧！', `MaleText_loc5`='讓我們繼續攻擊，把他們的首都化為灰燼!沉浸在神聖的火焰中!', `MaleText_loc7`='Que continúe el asalto. ¡Reduce su capital a cenizas! ¡Regocíjate en la llama sagrada!' WHERE `ID`=48482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 저주받을 필멸자여! 모두 부질없는 짓이다!', `MaleText_loc4`='不！诅咒你，凡人！你的一切挣扎都是徒劳的！', `MaleText_loc5`='不!我詛咒你，凡人!你們的掙扎是無謂的!', `MaleText_loc7`='¡NOOOO! ¡Te maldigo, mortal! ¡LUCHAS EN VANO!' WHERE `ID`=48483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 불의 군주의 불꽃에 녹아버릴 것이다!', `MaleText_loc4`='你必将葬身于炎魔之王的烈焰之中！', `MaleText_loc5`='你們終將毀在炎魔的火裡!', `MaleText_loc7`='¡Morirás en la Llama del Señor del Fuego!' WHERE `ID`=48484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사자님, 불의 군주의 뜻대로 이루어질 것입니다,', `MaleText_loc4`='炎魔之王的意志必将实现，总大使。', `MaleText_loc5`='炎魔旨意必達，總大使。', `MaleText_loc7`='Que se cumpla la voluntad del Señor del Fuego, gran embajador.' WHERE `ID`=48485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령에 맞서 싸우는 자들이 있다는 소문이 있지만, 우린 더 많은 정령을 불러낼 것입니다.', `MaleText_loc4`='有传闻说，一些英雄将元素打退了，但我们还会召唤更多元素。', `MaleText_loc5`='聽說有些英雄正在對抗元素，但是我們會召喚更多出來。', `MaleText_loc7`='Corren rumores de héroes que luchan contra los elementales, pero nosotros invocaremos más.' WHERE `ID`=48486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 시간 안에 그들의 소중한 도시는 모두 재로 변할 것입니다.', `MaleText_loc4`='再过一个小时，这座城市将只剩下灰烬。', `MaleText_loc5`='不出一個鐘頭，他們的寶貝城市就會只剩下灰燼!', `MaleText_loc7`='En cuestión de una hora, de su preciosa ciudad no quedarán más que CENIZAS.' WHERE `ID`=48487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암아귀의 머리가 가까이 있습니다!', `MaleText_loc4`='你已经能碰到熔喉的脑袋了！', `MaleText_loc5`='你已經很接近熔喉的頭部了!', `MaleText_loc7`='¡Estás a punto de alcanzar la cabeza de Faucemagma!', `FemaleText_loc1`='용암아귀의 머리가 가까이 있습니다!', `FemaleText_loc4`='你已经能碰到熔喉的脑袋了！', `FemaleText_loc5`='你已經很接近熔喉的頭部了!', `FemaleText_loc7`='¡Estás a punto de alcanzar la cabeza de Faucemagma!' WHERE `ID`=48488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 이교도들이 드루이드를 눈여겨보고 있던 것 같군요!$B$B소용돌이치고 있는 차원문을 통해 거친심장 거점이 보일 겁니다. 안으로 들어가면 야영지로 돌아갈 수 있죠.$B$B일단 이곳에서의 볼일이 끝나면 재빨리 탈출하는 게 좋을 겁니다.', `MaleText_loc4`='看来邪教徒盯上了那些德鲁伊！$B$B你可以通过这旋转的传送门看到野性之心哨站。穿过传送门就能返回营地。$B$B等这里的工作结束后，便可藉此快速离开。', `MaleText_loc5`='看來教徒們已經注意到德魯伊了!$B$B你可以透過傳送門的漩渦看見野性之心營地!穿過它肯定能把你帶回營地。$B$B等你在這裡的事情辦妥，這會是快速離開的好方法。', `MaleText_loc7`='¡Parece que los cultores pusieron sus miras en los druidas!$B$BPuedes ver el Alto de Corazón Salvaje a través del remolino del portal. Si lo atraviesas, te llevará al campamento en un viaje sin retorno.$B$BUna vez termines tus asuntos aquí, esta sería una buena forma de salir de aquí rápidamente.', `FemaleText_loc1`='보아하니 이교도들이 드루이드를 눈여겨보고 있던 것 같군요!$B$B소용돌이치고 있는 차원문을 통해 거친심장 거점이 보일 겁니다. 안으로 들어가면 야영지로 돌아갈 수 있죠.$B$B일단 이곳에서의 볼일이 끝나면 재빨리 탈출하는 게 좋을 겁니다.', `FemaleText_loc4`='看来邪教徒盯上了那些德鲁伊！$B$B你可以通过这旋转的传送门看到野性之心哨站。穿过传送门就能返回营地。$B$B等这里的工作结束后，便可藉此快速离开。', `FemaleText_loc5`='看來教徒們已經注意到德魯伊了!$B$B你可以透過傳送門的漩渦看見野性之心營地!穿過它肯定能把你帶回營地。$B$B等你在這裡的事情辦妥，這會是快速離開的好方法。', `FemaleText_loc7`='¡Parece que los cultores pusieron sus miras en los druidas!$B$BPuedes ver el Alto de Corazón Salvaje a través del remolino del portal. Si lo atraviesas, te llevará al campamento en un viaje sin retorno.$B$BUna vez termines tus asuntos aquí, esta sería una buena forma de salir de aquí rápidamente.' WHERE `ID`=48489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어가 거친심장 거점으로 돌아갑니다.', `MaleText_loc4`='穿过传送门，返回野性之心哨站。', `MaleText_loc5`='穿過傳送門回到野性之心營地。', `MaleText_loc7`='Cruza el portal y regresa al Alto de Corazón Salvaje.', `FemaleText_loc1`='차원문으로 들어가 거친심장 거점으로 돌아갑니다.', `FemaleText_loc4`='穿过传送门，返回野性之心哨站。', `FemaleText_loc5`='穿過傳送門回到野性之心營地。', `FemaleText_loc7`='Cruza el portal y regresa al Alto de Corazón Salvaje.' WHERE `ID`=48490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 진흙괴물들이 당신의 간섭에 부정적으로 반응하기 시작합니다.', `MaleText_loc4`='你的戳刺引起了枯萎软泥怪的消极反抗。', `MaleText_loc5`='荒疫軟泥怪對你的刺激開始產生負面的反應。', `MaleText_loc7`='Las babosas de añublo empiezan a reaccionar negativamente a tus empujones.', `FemaleText_loc1`='역병 진흙괴물들이 당신의 간섭에 부정적으로 반응하기 시작합니다.', `FemaleText_loc4`='你的戳刺引起了枯萎软泥怪的消极反抗。', `FemaleText_loc5`='荒疫軟泥怪對你的刺激開始產生負面的反應。', `FemaleText_loc7`='Las babosas de añublo empiezan a reaccionar negativamente a tus empujones.' WHERE `ID`=48491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 진흙괴물들이 화를 내기 시작합니다!', `MaleText_loc4`='枯萎软泥怪发怒了！', `MaleText_loc5`='荒疫軟泥怪開始生氣了!', `MaleText_loc7`='¡Las babosas de añublo empiezan a ENFADARSE!', `FemaleText_loc1`='역병 진흙괴물들이 화를 내기 시작합니다!', `FemaleText_loc4`='枯萎软泥怪发怒了！', `FemaleText_loc5`='荒疫軟泥怪開始生氣了!', `FemaleText_loc7`='¡Las babosas de añublo empiezan a ENFADARSE!' WHERE `ID`=48492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병 진흙괴물들이 당신의 목숨을 노리기 시작했습니다!', `MaleText_loc4`='枯萎软泥怪想要吸你的血！', `MaleText_loc5`='荒疫軟泥怪想要你的鮮血!', `MaleText_loc7`='¡Las babosas de añublo quieren tu sangre!', `FemaleText_loc1`='역병 진흙괴물들이 당신의 목숨을 노리기 시작했습니다!', `FemaleText_loc4`='枯萎软泥怪想要吸你的血！', `FemaleText_loc5`='荒疫軟泥怪想要你的鮮血!', `FemaleText_loc7`='¡Las babosas de añublo quieren tu sangre!' WHERE `ID`=48493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 가지가 생명으로 가득 찬 게 느껴지는군요. 얼른 이 생명을 땅에 돌려주고 싶어요.', `MaleText_loc4`='我能感觉到我的枝桠焕发着无尽的生命力。我已经迫不及待想要让它重返大地的怀抱。', `MaleText_loc5`='我可以感覺到枝葉充滿了生命。我等不及要把它還給大地了。', `MaleText_loc7`='Puedo sentir que mis ramas se llenan de vida. No puedo esperar a devolverla a la tierra.' WHERE `ID`=48494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 대공주님, 이제 여기에 남아 계시면 안 됩니다. 얘기 못 들으셨습니까?', `MaleText_loc4`='您已经不再被困于此地了，伟大的公主。您还不知道吗？', `MaleText_loc5`='尊貴的公主，您已經不必再被囚禁於此了。您沒有聽說嗎?', `MaleText_loc7`='Ya no estás obligada a permanecer aquí, gran princesa. ¿Acaso no has oído nada?' WHERE `ID`=48495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈이 깊어지면서 티탄의 안식처가 약해지고 있습니다. 이제 이 감옥은 당신을 지켜줄 수 없습니다.', `MaleText_loc4`='这些泰坦的地穴已经随着混乱力量的日渐强大而被削弱了。这座牢狱已经无法再束缚您。', `MaleText_loc5`='混沌四起，泰坦的地庫日漸衰頹。這座監獄已經關不住你了。', `MaleText_loc7`='Las cámaras de los titanes se debilitan a medida que florece el caos. Esta prisión ya no puede encerrarte más tiempo.' WHERE `ID`=48496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 공주마마. 그럼 저는 이만...', `MaleText_loc4`='非常好。只要您同意，公主。', `MaleText_loc5`='是。請容我先告退了，公主。', `MaleText_loc7`='Muy bien. Con tu permiso, princesa.' WHERE `ID`=48497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말조심하라, 데스윙의 하수인이여. 내가 바보인 줄 아느냐!?', `FemaleText_loc4`='小心说话，死亡之翼的奴才。你以为我是个傻瓜吗？', `FemaleText_loc5`='死亡之翼的僕人，注意你講話的口氣。難道你以為我是笨蛋嗎?!', `FemaleText_loc7`='Cuida tus palabras, sirviente de Alamuerte. ¡¿Crees que soy estúpida?!' WHERE `ID`=48498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테라모크는 나의 고향이지 감옥이 아니다. 내가 사랑하던 이들의 흔적이 모두 여기 남아 있다.', `FemaleText_loc4`='泰拉莫克是我的家园，而不是我的牢狱。造就它的正是我曾经钟爱的一切。', `FemaleText_loc5`='泰拉莫克是我的家，不是我的監獄。我的至愛的遺體就在此處。', `FemaleText_loc7`='Terramok es mi hogar, no mi prisión. Los restos de mis seres queridos así lo indican.' WHERE `ID`=48499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 실망하지 마라, 오우거여. 나는 계속해서 너와 너희... 부족을 도울 것이다.', `FemaleText_loc4`='不过不必失望，食人魔。我会继续帮助你和你的……教派。', `FemaleText_loc5`='但是不必擔心，巨魔。我會繼續協助你和你的...教派。', `FemaleText_loc7`='Pero no desesperes, ogro. Seguiré ayudándoos a ti y a tu... culto.' WHERE `ID`=48500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든, 위의 세상에서 분쟁이 일어난 것을 보니 기쁘군... 흔들리고, 산산이 조각나고, 으스러지고...', `FemaleText_loc4`='毕竟，我很喜欢在上面的世界造成冲突与战争……我喜欢震撼，粉碎，吞噬和摧毁……', `FemaleText_loc5`='畢竟，我樂見上方的世界陷入紛亂...震動，並且因碎裂而被吞噬...', `FemaleText_loc7`='Después de todo, me complace causar conflictos en el mundo superior... Agitar, destruir, devorar y aplastar...' WHERE `ID`=48501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...하지만 난 여기 남을 것이다, 영원히.', `FemaleText_loc4`='……但我会留在这里，永远如是。', `FemaleText_loc5`='...但是我將繼續留在此處，永永遠遠。', `FemaleText_loc7`='... pero debo permanecer aquí, para siempre.' WHERE `ID`=48502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가라.', `FemaleText_loc4`='走吧。', `FemaleText_loc5`='離開吧。', `FemaleText_loc7`='Vete.' WHERE `ID`=48503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_key_12.blp:32|t화끈한 개조차 열쇠를 사용하여 차에 탑승하고, 이지, 에이스, 고버를 태우고 돌아와야 합니다.', `MaleText_loc4`='使用改装跑车的钥匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t进入你的跑车，并搭载你的朋友小静、王牌和大胖。', `MaleText_loc5`='使用酷炫改裝車的鑰匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t來進入你的車。去載你的朋友，伊茲、愛司和古柏。', `MaleText_loc7`='Utiliza las llaves del bólido |TInterfaceIconsinv_misc_key_12.blp:32|t para subirte al coche. Recoge a tus amigos Izzy, As y Gargajo.', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_key_12.blp:32|t화끈한 개조차 열쇠를 사용하여 차에 탑승하고, 이지, 에이스, 고버를 태우고 돌아와야 합니다.', `FemaleText_loc4`='使用改装跑车的钥匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t进入你的跑车，并搭载你的朋友小静、王牌和大胖。', `FemaleText_loc5`='使用酷炫改裝車的鑰匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t來進入你的車。去載你的朋友，伊茲、愛司和古柏。', `FemaleText_loc7`='Utiliza las llaves del bólido |TInterfaceIconsinv_misc_key_12.blp:32|t para subirte al coche. Recoge a tus amigos Izzy, As y Gargajo.' WHERE `ID`=48504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢，长官！', `MaleText_loc5`='謝啦，老大!', `MaleText_loc7`='¡Gracias, $gjefe:jefa;!', `FemaleText_loc1`='고마워요!', `FemaleText_loc4`='谢谢，长官！', `FemaleText_loc5`='謝啦，老大!', `FemaleText_loc7`='¡Gracias, $gjefe:jefa;!' WHERE `ID`=48505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 시간 동안 부상자가 없었습니다. 신기록이네요!', `MaleText_loc4`='我们在过去的一小时内没有收到负伤报告。这可是项新纪录！', `MaleText_loc5`='我們已經一個小時沒發生意外了。這是個新記錄!', `MaleText_loc7`='¡Ha pasado una hora y no tenemos ninguna herida de la que informar! ¡Es un nuevo récord!', `FemaleText_loc1`='한 시간 동안 부상자가 없었어요. 신기록이네요!', `FemaleText_loc4`='我们在过去的一小时内没有收到负伤报告。这可是项新纪录！', `FemaleText_loc5`='我們已經一個小時沒發生意外了。這是個新記錄!', `FemaleText_loc7`='¡Ha pasado una hora y no tenemos ninguna herida de la que informar! ¡Es un nuevo récord!' WHERE `ID`=48506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치료비가 월급에서 공제되는 건 아니겠죠?', `MaleText_loc4`='我希望这不用我掏腰包！', `MaleText_loc5`='我希望這不用我來付帳!', `MaleText_loc7`='¡Espero que esto no esté saliendo de mi bolsillo!', `FemaleText_loc1`='치료비가 월급에서 공제되는 건 아니겠죠?', `FemaleText_loc4`='我希望这不用我掏腰包！', `FemaleText_loc5`='我希望這不用我來付帳!', `FemaleText_loc7`='¡Espero que esto no esté saliendo de mi bolsillo!' WHERE `ID`=48507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 치료하는 게 확실히 의료보험료를 내는 것보다 낫네요!', `MaleText_loc4`='这样的治疗服务绝对对得起那昂贵的医疗保险！', `MaleText_loc5`='這個治療的玩意兒真的比付醫療保險划算!', `MaleText_loc7`='¡Ya lo creo que esas cosas de sanación son mucho mejor que tener que pagar un seguro médico!', `FemaleText_loc1`='이렇게 치료하는 게 확실히 의료보험료를 내는 것보다 낫네요!', `FemaleText_loc4`='这样的治疗服务绝对对得起那昂贵的医疗保险！', `FemaleText_loc5`='這個治療的玩意兒真的比付醫療保險划算!', `FemaleText_loc7`='¡Ya lo creo que esas cosas de sanación son mucho mejor que tener que pagar un seguro médico!' WHERE `ID`=48508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무역왕 갤리윅스 밑에서는 복지 혜택이 정말 최악이에요. 당신이 어서 새 무역왕이 되시면 좋겠어요!', `MaleText_loc4`='在贸易大王加里维克斯手下工作简直是炼狱。希望你能成为新的贸易$g大王:女王;！', `MaleText_loc5`='在貿易親王加里維克斯之下工作的條件真的很差。我希望你能成為新的貿易$g親王:女王;!', `MaleText_loc7`='El Príncipe mercante mantiene unas condiciones de trabajo terribles. ¡Espero que tú seas $gel nuevo Príncipe mercante:la nueva Princesa mercante;!', `FemaleText_loc1`='무역왕 갤리윅스 밑에서는 복지 혜택이 정말 최악이에요. 당신이 어서 새 무역왕이 되시면 좋겠어요!', `FemaleText_loc4`='在贸易大王加里维克斯手下工作简直是炼狱。希望你能成为新的贸易$g大王:女王;！', `FemaleText_loc5`='在貿易親王加里維克斯底下工作的條件真的很差。我希望你能變成新的貿易$g親王:女王;!', `FemaleText_loc7`='El Príncipe mercante mantiene unas condiciones de trabajo terribles. ¡Espero que tú seas $gel nuevo Príncipe mercante:la nueva Princesa mercante;!' WHERE `ID`=48509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평상시 같으면 그 정도 폭발은 아무것도 아니었을 텐데요. 아무래도 누군가 폭약과 카자마이트의 혼합 비율을 반대로 한 것 같아요.', `MaleText_loc4`='通常，我面对那样的爆炸只会一笑了之，可我认为有人把硝基和卡亚矿石混合比例搞错了。', `MaleText_loc5`='通常我對這種程度的爆炸一點都不在乎，但是我想這次有人把硝化甘油和卡迦邁的比例搞錯了。', `MaleText_loc7`='Normalmente no le daría mayor importancia a una explosión como esa, pero creo que alguien la ha fastidiado con la mezcla de nitro y kaja''mita.', `FemaleText_loc1`='평상시 같으면 그 정도 폭발은 아무것도 아니었을 텐데요. 아무래도 누군가 폭약과 카자마이트의 혼합 비율을 반대로 한 것 같아요.', `FemaleText_loc4`='通常，我面对那样的爆炸只会一笑了之，可我认为有人把硝基和卡亚矿石混合比例搞错了。', `FemaleText_loc5`='通常我對這種程度的爆炸一點都不在乎，但是我想這次有人把硝化甘油和卡迦邁的比例搞錯了。', `FemaleText_loc7`='Normalmente no le daría mayor importancia a una explosión como esa, pero creo que alguien la ha fastidiado con la mezcla de nitro y kaja''mita.' WHERE `ID`=48510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 모두 정신 나간 호바트 그래플해머 잘못이라고요! 그놈은 당장 해고해 버리고 조수를 진급시켜야 해요!', `MaleText_loc4`='都是霍巴特·钩锤那疯子的错！应该有人站出来把他炒掉，让他的助手升职！', `MaleText_loc5`='都是因為那個瘋狂的荷巴爾特·繫錘的錯!得有人把他炒了，讓他的助手升職!', `MaleText_loc7`='¡Ha sido culpa de ese loco de Hobart Martillazos! ¡Alguien debería despedir a ese tipo y ascender a su ayudante!', `FemaleText_loc1`='이게 모두 정신 나간 호바트 그래플해머 잘못이라고요! 그놈은 당장 해고해 버리고 조수를 진급시켜야 해요!', `FemaleText_loc4`='都是霍巴特·钩锤那疯子的错！应该有人站出来把他炒掉，让他的助手升职！', `FemaleText_loc5`='都是因為那個瘋狂的荷巴爾特·繫錘的錯!得有人把他炒了，讓他的助手升職!', `FemaleText_loc7`='¡Ha sido culpa de ese loco de Hobart Martillazos! ¡Alguien debería despedir a ese tipo y ascender a su ayudante!' WHERE `ID`=48511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 위해서라면 이 한목숨쯤 초개같이 폭발과 함께 날려버리리라는 사실, 알고 계시죠?!', `MaleText_loc4`='你知道，老板，为了公司，我很愿意在你的监督下把我自己炸飞！', `MaleText_loc5`='你知道我會很高興為了公司炸死自己，只要當家的人是你，老闆!', `MaleText_loc7`='¡Ya sabes que contigo al mando, jefe, me dejaría saltar por los aires por la compañía sin dudar!', `FemaleText_loc1`='당신을 위해서라면 이 한목숨쯤 초개같이 폭발과 함께 날려버리리라는 사실, 알고 계시죠?!', `FemaleText_loc4`='你知道，老板，为了公司，我很愿意在你的监督下把我自己炸飞！', `FemaleText_loc5`='你知道我會很高興為了公司炸死自己，只要當家的人是你，老闆!', `FemaleText_loc7`='¡Ya sabes que contigo al mando, jefe, me dejaría saltar por los aires por la compañía sin dudar!' WHERE `ID`=48512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적들은 쓰러지리라!', `FemaleText_loc4`='我们的敌人将要毁灭！', `FemaleText_loc5`='我們的敵人會被消滅!', `FemaleText_loc7`='¡Nuestros enemigos caerán!' WHERE `ID`=48513;
