UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로데론은 우리의 것이다!', `FemaleText_loc4`='洛丹伦是我们的了！', `FemaleText_loc5`='羅德隆屬於我們!', `FemaleText_loc7`='¡Lordaeron es nuestra!' WHERE `ID`=48515;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈부시고 강력한 힘이 샘솟는구나!', `FemaleText_loc4`='真是辉煌而美丽的力量啊！', `FemaleText_loc5`='如此光輝、美麗的力量!', `FemaleText_loc7`='¡Semejante poder, hermoso y glorioso!' WHERE `ID`=48516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰에게 승리를!', `FemaleText_loc4`='胜利属于被遗忘者！', `FemaleText_loc5`='被遺忘者萬歲!', `FemaleText_loc7`='¡Victoria para los Renegados!' WHERE `ID`=48517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 이게 뭔가? 내가 바쁜 게 보이지 않는 건가?', `MaleText_loc4`='什么事，小子？你看不见我正忙着吗？', `MaleText_loc5`='什麼事，卑微的下人?沒看到我在忙嗎?', `MaleText_loc7`='¿Qué ocurre, subordinado? ¿No ves que estoy ocupado?' WHERE `ID`=48518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이 좁은 곳에 이 흑마법사 녀석들하고 갇혀 있는 건 참을 수가 없군. 녀석들 관리는 자이룬의 일이지 내 일이 아니란 말일세!$b$b전투가 시작되기까지 기다릴 수가 없군. 내 용들과 밖으로 나가야겠어.', `MaleText_loc4`='我可不愿意和这些术士们一起被困在这里。这是克希鲁恩的工作，不是我的！$b$b我已经等不及要参加战斗了。我需要出去，和我的龙在一起。', `MaleText_loc5`='我無法忍受和這些術士待在一起。這是希倫的工作，不是我的!$B$B我等不及這場戰鬥快點開始。我需要去外面，和我的龍在一起。', `MaleText_loc7`='No puedo soportar estar aquí encerrado con todos estos brujos. ¡Esto es trabajo de Xi''lun, no mío!$b$bEstoy deseando que comience la batalla. Necesito estar fuera con mis dragones.' WHERE `ID`=48519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 누군지 봐라! 곤봉잡이로군!', `MaleText_loc4`='看看这是谁！是持棍人$g他自己:她自己;！', `MaleText_loc5`='看看這是誰啊!背棍子的傢伙$g他:她;本人!', `MaleText_loc7`='¡Mira quién está aquí! ¡$gEl:La; del garrote en persona!' WHERE `ID`=48520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 정말 대단한 인물이군요. 야수는 최후를 맞이했습니다. 이제 여기서 빠져나가지요.', `FemaleText_loc4`='你可真是位骁勇善战的勇士。那怪物已经被解决了。我们离开这里吧。', `FemaleText_loc5`='你的力量真的不容小覷。那隻野獸已經完了。咱們離開吧。', `FemaleText_loc7`='Tengo que admitir que eres una fuerza a tener en cuenta. Hemos terminado con la bestia. Salgamos de aquí.' WHERE `ID`=48521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 친구! 달라 아가씨는 당신 같은 여행자가 안전하고 편안하게 머물 수 있게 도우라며 절 만드셨죠!$B$B부관 클렁키가 전하는 촌구석에서의 안전 수칙을 잘 들으세요! 야호!', `MaleText_loc4`='你好啊，朋友！达尔拉女士命我确保你们这群朝圣者都能享受到美好而安全的旅程！$B$B听听克朗奇警官的本地安全提示吧！呀嘿！', `MaleText_loc5`='你好啊，夥伴!達爾拉小姐要我確保你們這些旅人都安全無虞!$B$B記得聽聽副隊長克朗奇純樸熱情的安全建議!咿哈!', `MaleText_loc7`='¡Qué hay, $gsocio:socia;! La señorita Darla me ha fortalecido para que me asegure de que ustedes, pequeños peregrinos, no sufran ningún peligro!$B$B¡Presten atención a los sencillos consejos sobre seguridad del ayudante de alguacil Torpolatón!' WHERE `ID`=48522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 경호원 중 최고다!', `MaleText_loc4`='我是最好的守卫！', `MaleText_loc5`='我是最棒的保鏢!', `MaleText_loc7`='¡Yo ser el mejor guardaespaldas!' WHERE `ID`=48523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다! 내가 최고다!', `MaleText_loc4`='不，是我！', `MaleText_loc5`='我才是!', `MaleText_loc7`='¡No, yo!' WHERE `ID`=48524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 나쁜 놈들 때려줄 판자 가지고 있다!', `MaleText_loc4`='我有一根大棒子，能把一切都砸扁！', `MaleText_loc5`='我有個大板子可以打人!', `MaleText_loc7`='¡Yo tener una gran tabla para golpear cosas!' WHERE `ID`=48525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 판자엔 못도 박혔다!', `MaleText_loc4`='我的大棒子上还有根钉子！', `MaleText_loc5`='我的板子裡面有釘子!', `MaleText_loc7`='¡Y la mía tener un clavo!' WHERE `ID`=48526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 판자에 박힌 못이 더 크다!', `MaleText_loc4`='我有一根更大的钉子！', `MaleText_loc5`='我有更大的釘子!', `MaleText_loc7`='¡Mi clavo ser más grande!' WHERE `ID`=48527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 판자에 박힌 못엔 녹도 슬었다!', `MaleText_loc4`='我有一根生锈的钉子！', `MaleText_loc5`='我的釘子是生鏽的!', `MaleText_loc7`='¡El mío estar OXIDADO!' WHERE `ID`=48528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 위험한데...', `MaleText_loc4`='这真危险。', `MaleText_loc5`='那很危險。', `MaleText_loc7`='Eso ser peligroso.' WHERE `ID`=48529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 놈들만 때려줄 거니까 괜찮다.', `MaleText_loc4`='只是打坏人用的。', `MaleText_loc5`='只用來對付壞人。', `MaleText_loc7`='Solo ser para los tipos malos.' WHERE `ID`=48530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 문 감시하는 건 내가 최고다.', `MaleText_loc4`='但我才是最好的看门卫兵。', `MaleText_loc5`='但是我看門是最厲害的。', `MaleText_loc7`='Pero yo ser mejor para vigilar esa puerta.' WHERE `ID`=48531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다! 그것도 내가 최고다!', `MaleText_loc4`='不，我才是！', `MaleText_loc5`='我才是!', `MaleText_loc7`='¡No, yo ser!' WHERE `ID`=48532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅이 고통받고... 분노하고 있다!', `MaleText_loc4`='大地在痛苦着……咆哮着！', `MaleText_loc5`='這片大地正在受苦...而且十分憤怒!', `MaleText_loc7`='¡La tierra sufre... y se llena de IRA!' WHERE `ID`=48534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 이번 전투를 시작할 준비가 거의 끝났네. 토르그이조그, 왜 그러나? 왜 자네 엉덩이를 그렇게 가리고 있는 건가?', `MaleText_loc4`='我们就快准备好开战了，兄弟们。索基佐格，有什么事吗？你为什么那样遮住自己的屁股？', `MaleText_loc5`='我們已經快要準備好面對這場戰鬥了，兄弟們。索伊佐格，你怎麼了?幹嘛摀著你的屁股?', `MaleText_loc7`='Ya casi estamos listos para comenzar la batalla, hermanos. Thorg''izog, ¿qué ocurre? ¿Por qué te tapas el trasero de esa forma?' WHERE `ID`=48535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 아무것도 아닐세... 그냥... 뱃 속에 뭔가 크게 잘못된 것 같아서 말이야. 내가 먹은 뭔가 때문인 것 같네.', `MaleText_loc4`='什么？没理由……我……我的肚子很难受。我想我是吃错了东西。', `MaleText_loc5`='什麼?沒事...只是...我的胃有很大的問題。我想大概吃壞肚子了。', `MaleText_loc7`='¿QUÉ? Por nada... Es solo que... mi estómago anda un poco mal. Creo que es algo que he comido.' WHERE `ID`=48536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 군대를 이끌 수 있겠나? 자네 하사관 중에서 한 명을 진급시켜야 하지 않겠나?', `MaleText_loc4`='你还能指挥你的部下吗？是否需要暂时把指挥权交给你的一名副官？', `MaleText_loc5`='你還能領導你的部隊吧?你要不要晉升你一個士官?', `MaleText_loc7`='¿Todavía puedes ponerte el frente de tus tropas? ¿Necesitas que ascienda a uno de tus sargentos?' WHERE `ID`=48537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티만이 잿빛 기둥에서 떨어졌네. 오타나는 늑대들에게 먹혔네. 고를로프는 용암에 떨어졌고. 그리고 내 하사관들 대부분이 기이한 곤봉질 사건으로 살해당했네.', `MaleText_loc4`='提曼从灰烬之柱掉下去摔死了。欧萨娜被狼吃了。格尔洛普掉进了熔岩里。我的大部分副官也都在各种各样诡异的事故中丧生。', `MaleText_loc5`='提曼從灰燼之柱掉下去了。歐桑娜被狼吃掉了。戈洛普掉進熔岩了。我手下多數的士官都因為很怪的意外而死。', `MaleText_loc7`='Timan cayó del Pilar de Ceniza. Othana fue devorada por los lobos. Gorlop se hundió en la lava. Y la mayoría de mis sargentos murieron en un extraño accidente con un garrote.' WHERE `ID`=48538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네. 음, 자네가 할 수 있는 한 최선을 다하게. 그리고 니랄라크, 자네 왜 그렇게 까맣고 연기가 펄펄 나는 건가?', `MaleText_loc4`='我明白了。那你尽力吧。尼纳拉克，你怎么像刚从烤炉里跑出来一样？', `MaleText_loc5`='了解。好吧，你們盡力吧。尼洛拉克，你為什麼整個人變得烏漆抹黑，還在冒煙?', `MaleText_loc7`='Entiendo. Bueno, hazlo lo mejor que puedas. Y Neeralak, ¿por qué estás negro y humeas?' WHERE `ID`=48539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 배달한 그 임프들... 녀석들이 깨어나더니 모두에게 화염구를 쏴 댔었네! 혼란 그 자체였어!', `MaleText_loc4`='你送来的那些小鬼……他们一醒过来，就开始向所有人丢火球！一切都乱套了！', `MaleText_loc5`='那些你送來的小鬼...牠們醒來了，然後開始對所有人發射火球!整個亂成一團!', `MaleText_loc7`='Esos diablillos que enviaste... ¡se despertaron y empezaron a lanzar bolas de Fuego a todo el mundo! ¡Fue el caos!' WHERE `ID`=48540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배달됐다고? 일어났다고? 도대체 무슨 소리를 하는 건가? 화염족에게 공격당한 건가?', `MaleText_loc4`='送来的？醒过来了？你在说什么啊？你是被小鬼袭击了吗？', `MaleText_loc5`='送來?醒來?你在說什麼?你被小鬼攻擊了?', `MaleText_loc7`='¿Que envié? ¿Se despertaron? ¿De qué estás hablando? ¿Fuisteis atacados por flamantes?' WHERE `ID`=48541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임프든 화염족이든 뭐가 됐든 말이야! 난 흑마법사 잡일 따위는 모르겠다고. 악마들 모두 나한텐 똑같이 보인단 말일세!', `MaleText_loc4`='小恶魔，小鬼，谁知道是什么！我对术士的玩意儿一无所知。恶魔在我看来全都一样！', `MaleText_loc5`='伊普斯?小鬼?管他的!我不知道那些術士的垃圾玩意兒!對我來說惡魔不就都長那樣!', `MaleText_loc7`='¡Diablillos, flamantes, lo que sea! ¡No tengo ni idea de todas esas tonterías de brujos! ¡Para mí todos los demonios son iguales!' WHERE `ID`=48542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가, 난 다른 일들을 처리하느라 바빴네. 저 두 무리의 적들이 최전방을 쓸고 다닐 때 내 용들 여럿이 죽어버렸네.', `MaleText_loc4`='而且，我还在忙着处理其它问题。当那两个敌人横扫前线的时候，我的几十头龙都死了。', `MaleText_loc5`='而且，我還忙著解決其他問題。那兩個敵人在前線衝殺時，我的龍群死了一大片!', `MaleText_loc7`='Además, he estado ocupando encargándome de otros asuntos. Cuando esos dos enemigos arrasaron nuestro frente de batalla murieron docenas de mis dragones.' WHERE `ID`=48543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들 둘 다 실패자로군. 하지만 상관없네. 지옥의 군주가 우리 편인 이상, 보병들이나 용들 따윈 필요 없을 걸세. 보게!', `MaleText_loc4`='你们全都是废物。但这没关系：我们有一个深渊领主，所以我们不需要士兵和龙。给我看着吧！', `MaleText_loc5`='你們都很失敗。不過無所謂，有著深淵領主在我們這邊，我們根本不需要士兵或龍群!看吧!', `MaleText_loc7`='Los dos sois un desastre. Pero no importa: tenemos a un señor del foso de nuestro lado, y no necesitaremos soldados de infantería NI dragones. ¡Observad!' WHERE `ID`=48544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나, 둘, 셋, 넷, 손가락 전쟁을 선언하네!', `MaleText_loc4`='一、二、三、四，拇指大战开始了！', `MaleText_loc5`='一，二，三，四，拇指大戰開始囉!', `MaleText_loc7`='¡Uno, dos, tres, cuatro, declaro una guerra de pulgares!' WHERE `ID`=48545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥의 군주가 우리를 공격하기 전에 지배의 수정구를 재빨리 사용하게.', `MaleText_loc4`='赶快使用统御宝珠，不要让那个深渊领主来打我们。', `MaleText_loc5`='現在快點使用統御寶珠，免得深淵領主造反!', `MaleText_loc7`='Y ahora rápido, utiliza el orbe de dominación antes de que el señor del foso regrese con nosotros.' WHERE `ID`=48546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무... 것도 하지 않잖아! 지옥의 군주가 풀려났다니!', `MaleText_loc4`='它……它没有用！深渊领主不受控制了！', `MaleText_loc5`='這...這不管用啊!深淵領主失控了!', `MaleText_loc7`='¡No... no hace nada! ¡El señor del foso está suelto!' WHERE `ID`=48547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥의 군주가 풀려났다! 우린 망했어! 후퇴하라!', `MaleText_loc4`='深渊领主不受控制了！我们完蛋了！快撤！', `MaleText_loc5`='深淵領主失控了!我們完蛋了!快撤退!', `MaleText_loc7`='¡El señor del foso está suelto! ¡Estamos perdidos! ¡Retirada!' WHERE `ID`=48548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서, 모두 저 용들에게 달려가라! 전 군대, 용 쪽으로 가라! 용들이 우릴 구해줄 거다!', `MaleText_loc4`='赶快，所有人都向龙靠近！所有部队，全速向龙奔跑！那些龙是我们的救星！', `MaleText_loc5`='快點，所有人跑去那些龍那裡!全軍往龍群前進!龍群能救我們!', `MaleText_loc7`='¡Rápido, corred todos hacia esos dragones! ¡A todas las tropas! ¡A los dragones! ¡Los dragones nos salvarán!' WHERE `ID`=48549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용들 부른 적 없는데...', `MaleText_loc4`='我从没有召唤过龙……', `MaleText_loc5`='我從來沒叫過任何龍來助陣...', `MaleText_loc7`='Nunca he llamado a ningún dragón...' WHERE `ID`=48550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철벽 알순다르와 다른 상급 전사들은 주조소 근처에서 원정순찰대 광장을 바라보는 곳에서 찾을 수 있습니다.', `MaleText_loc4`='捍卫者阿尔苏达和其他战士训练师都在那个能俯瞰远行者广场的地方，就是靠近锻造师所在的那个地方。', `MaleText_loc5`='你可以在鑄造廠附近的遠行者廣場找到『壁壘』艾爾蘇達和其他戰士訓練師們。', `MaleText_loc7`='Es posible encontrar a Alsudar el Bastión y a los otros instructores de guerreros vigilando la Plaza del Errante desde la fundición cercana.', `FemaleText_loc1`='철벽 알순다르와 다른 상급 전사들은 주조소 근처에서 원정순찰대 광장을 바라보는 곳에서 찾을 수 있습니다.', `FemaleText_loc4`='捍卫者阿尔苏达和其他战士训练师都在那个能俯瞰远行者广场的地方，就是靠近锻造师所在的那个地方。', `FemaleText_loc5`='你可以在鑄造廠附近的遠行者廣場找到『壁壘』艾爾蘇達和其他戰士訓練師們。', `FemaleText_loc7`='Es posible encontrar a Alsudar el Bastión y a los otros instructores de guerreros vigilando la Plaza del Errante desde la fundición cercana.' WHERE `ID`=48551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 존경하는 손님들이 오셨군!', `MaleText_loc4`='啊，我们尊敬的客人来了！', `MaleText_loc5`='啊，我們的貴客上門了。', `MaleText_loc7`='¡Ah, nuestros estimados invitados han llegado!' WHERE `ID`=48552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍과 상처와 피에 뒤덮인 우리의 도전자를 보십시오... 모두 저 새로운 승자를 축하해 줍시다!', `MaleText_loc4`='这家伙全身都是割伤、瘀伤和血污。看样子，我们有了一个新的胜利者！', `MaleText_loc5`='遍體鱗傷，血肉模糊...看起來我們有了新的勝利者!', `MaleText_loc7`='Maltrecho, herido y cubierto de sangre... ¡parece que tenemos un nuevo ganador!' WHERE `ID`=48553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 상대를 박살 내 버린 우리의 승리자를 보십시오! 바로 지금 다음 판 베팅을 시작합니다! 흐름을 놓치지 마십시오.', `MaleText_loc4`='女士们，先生们，这些斗士已经取得了胜利！下一场的赌盘现在开始！让我们的钱舞动起来吧。', `MaleText_loc5`='先生女士們，這些肢解者們獲得了勝利!下一輪的下注開始了!快快下注!', `MaleText_loc7`='¡Damas y caballeros, estos campeones de la desmembración han salido VICTORIOSOS! ¡Desde ahora se aceptan apuestas para la siguiente ronda! Qué empiece a fluir el dinero.' WHERE `ID`=48554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍하지만 아름다운 경기! 이 굴그토크는 언제나 여러분이 바라는 장면을 보여 드립니다. 아제로스에서 가장 극적인 대학살! 만족하셨다면 박수로 화답해 주십시오!', `MaleText_loc4`='痛苦，但是美丽！古尔戈索克将满足你们的欲望！这是艾泽拉斯最有观赏性的角斗场。朋友们，让我感受到你们的热情吧！', `MaleText_loc5`='痛苦的美學!葛爾薩克會給你所要的!艾澤拉斯最棒的屠殺表演!表現一下你們的熱情吧!', `MaleText_loc7`='¡Doloroso pero hermoso! ¡Gurgthock les da lo que quieren! ¡El mejor espectáculo de masacre de todo Azeroth! ¡Gente, muéstrenme su amor!' WHERE `ID`=48555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오오오오! 정말 끔찍한 광경이로군요! 놀라운 승리입니다! 멋들어지게 처리했어요!', `MaleText_loc4`='哦！！！看看这混乱的一切！真是令人震惊的胜利！他到底有着怎样的力量！', `MaleText_loc5`='噢噢噢噢!看看那堆血肉模糊的東西!贏得真漂亮!看看穿過他的東西!', `MaleText_loc7`='¡OOOOOOOH! ¡Miren esa masacre! ¡Una victoria alucinante! ¡Vaya forma de atravesarlo con eso!' WHERE `ID`=48556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이러시면 안 되죠, 도전자 여러분! 그렇게 쉽게 이겨 버리면 관객분들이 흥미를 잃습니다! 비극적인 장면을 좀 연출해 주십시오, 도전자 여러분!', `MaleText_loc4`='呸，你就不能拖拖他的后腿？如果你让这一切显得太容易，人们就不会给我钱了！再加一些戏剧效果吧，好吗？！', `MaleText_loc5`='嘖，你幹嘛不拖久一點!看起來太輕而易舉，大家就不會多付錢!加點戲劇性的效果，可以嗎?', `MaleText_loc7`='¡Bah, podrías haber hecho que durara un poco más! ¡La gente no me paga cuando lo haces parecer tan fácil! ¡Échale un poco de teatro, ¿vale?!' WHERE `ID`=48557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 청소 회사에서 사람 불러야겠습니다. 경기장이 피로 엉망이 됐군요!', `MaleText_loc4`='喔！叫清洁人员来。他们真是把那个挑战者弄得一团糟！', `MaleText_loc5`='嘩!叫清潔隊進來!他們把那個挑戰者弄得很慘!', `MaleText_loc7`='¡VAYA! Llamad al equipo de limpieza. ¡Han dejado a ese contendiente para el arrastre!' WHERE `ID`=48558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴! 지배! 학살! 깔끔한 절단! 도전자 여러분이 제 취향을 딱 아시는군요!', `MaleText_loc4`='摧毁！统治！征服！美妙的胜利！你所做的正是我的最爱！', `MaleText_loc5`='摧毀!完勝!摧殘!可口的肢解方式!你做的正是我想要的效果!', `MaleText_loc7`='¡DESTRUIDO! ¡DOMINADO! ¡DIEZMADO! ¡DELICIOSAMENTE DESCUARTIZADO! ¡Lo habéis hecho justo como me gusta!' WHERE `ID`=48559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 이 위에서도 느껴지는 강력한 한 방이었습니다! 승자가 확실히 가려졌군요. 투기장을 적시는 희생자의 피가 이를 증명합니다!', `MaleText_loc4`='我感觉到有一个倒下了！我们有了胜利者。而场内的一片狼藉正说明了战况是多么惨烈。', `MaleText_loc5`='我從觀眾席上都能感覺到有多痛!我想我們的勝利者出現了，而分散在競技場周圍的肢體也不得不同意這一點!', `MaleText_loc7`='¡He sentido eso desde las gradas! ¡Creo que tenemos un nuevo ganador, muchachos, y los trozos de cuerpo que hay desperdigados por la arena lo atestiguan!' WHERE `ID`=48560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 그들의 작고 허약한 고향을 못살게 굴었다고 몹시 화가 나 있겠지.', `MaleText_loc4`='毫无疑问，他们生气了，因为我碰了一下他们脆弱的小家园。', `MaleText_loc5`='我對他們脆弱的小家園所做的事情。肯定讓他們相當憤慨。', `MaleText_loc7`='No me cabe duda de que estarán indignados porque yo la haya tomado con sus frágiles y diminutos hogares.' WHERE `ID`=48561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들에게 최대한의 예의를 보이며 환영하라. 그들의 뼈는 결국 여기에 오래, 아주 오랫동안 남게 될 것이니...', `MaleText_loc4`='一定要以最大的热情欢迎他们，不是么 ？毕竟，他们要留在这里很长，很长的时间……', `MaleText_loc5`='絕對要好好「歡迎」他們一下，是吧?畢竟，他們的屍骨會在這裡待上很久，很久...', `MaleText_loc7`='Procurad que se sientan BIENVENIDOS, ¿hmmm? Después de todo, sus huesos yacerán aquí durante mucho, MUCHO tiempo...' WHERE `ID`=48562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심각한 문제가 아니라면 제가 여기 왔겠습니까?', `MaleText_loc4`='如果不是形势严峻，我会出现在这里吗？', `MaleText_loc5`='如果不嚴重的話，我會在這裡嗎?', `MaleText_loc7`='¿Estaría aquí si esto no fuera grave?' WHERE `ID`=48563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 얘기는 이미 들었습니다. 그대의 세계를 구하기 위해, 우리에게서 가르침을 받으려고 여기에 왔다지요? 게야 대모님께서 그대를 가르치는 임무를 제게 맡기셨습니다. 그러니 이제부터는 제 말을 따라야 합니다, 고엘.', `FemaleText_loc4`='我听说过你。你来此拯救你的世界，从我们这里学习知识。盖亚安祖母命我指导你，因此，你必须听我的话，古伊尔。', `FemaleText_loc5`='我聽說過你。你是來這裡拯救你的世界，來向我們學習。主母吉雅派我教導你，因此，你必須聽我的，高爾。', `FemaleText_loc7`='Ya he oído hablar de ti. Has venido para salvar tu mundo; para aprender del nuestro. La abuela Geyah me ha encargado que te instruya y por eso me escucharás, Go''el.' WHERE `ID`=48564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이라 부르라고 하지 않았습니까.', `MaleText_loc4`='我告诉过你，请叫我萨尔。', `MaleText_loc5`='我告訴過你，叫我索爾。', `MaleText_loc7`='Te he dicho que me llames Thrall.' WHERE `ID`=48565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그랬지요, 고엘. 스랄은 호드의 지도자이지만, 지금 그대는 그 지위로 여기 와 있는 게 아닙니다. 그대 자신을 보십시오. 그대가 입고 있는 옷을...', `FemaleText_loc4`='嗯，我知道，古伊尔。萨尔是部落的领袖，可你并非以那样的身份来到这里。看看你自己——看看你这身打扮……', `FemaleText_loc5`='是的，我知道，高爾。索爾是部落的領袖，但是你並非以那樣的身分來到這裡的。看看你自己...看看你的穿著...', `FemaleText_loc7`='Sí, lo sé, Go''el. Thrall es el líder de la Horda, pero no estás aquí en calidad de eso. Mírate. Mira lo que llevas puesto...' WHERE `ID`=48566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지식과 가르침을 찾아 여기로 왔다고 하더니, 전투 복장을 하고 있군요. 그래서 저는 사명을 다하기 위한, 그대와 그대의 의지에 의문을 갖는 것입니다.', `FemaleText_loc4`='你说你是来寻求知识与理解，可你却身穿战甲。因此，我质疑你与你的意愿——你是否已准备好完成必须完成的任务。', `FemaleText_loc5`='你說你來這裡學習知識並增進了解，但是你的穿著卻比較適合戰鬥。這也是為什麼我質疑你，還有你是否有意願執行必須做的事情。', `FemaleText_loc7`='Dices que has venido en busca de conocimiento, pero vas vestido para la guerra. Por eso pongo en duda tu disposición para hacer lo que hay que hacer.' WHERE `ID`=48567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복장이요?! 이젠 제 복장까지 들먹이시는 겁니까? 지금 제 복장의 가치에 대해 논하잔 말입니까?', `MaleText_loc4`='我的衣服？！现在这变成了重要话题？难道我的着装也有争论的价值？', `MaleText_loc5`='我的衣著?!這就是現在所要著重的嗎?我們得針對我的衣著爭論?', `MaleText_loc7`='¡¿Mi ropa?! ¿A eso viene todo esto? ¿Estamos discutiendo sobre si mi ropa es apropiada o no?' WHERE `ID`=48568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 문제가 무엇인지 복장에서 드러나니까 하는 말입니다. 당신이 가르침을 구하려고 이곳에 왔음을 의심하는 건 아닙니다. 하지만 그러려면 몸과 마음을 다해야지요.', `MaleText_loc4`='着装只不过是潜在问题的外在表现而已。我毫不怀疑你来此学习的诚意，可你必须在精神与外貌上都做好充分的准备。', `MaleText_loc5`='衣著僅是一個更大的問題的表象。我不懷疑你是來學習的，但是你必須同時在精神上和形式上都全心投入。', `MaleText_loc7`='La ropa no es más que una manifestación de un problema mayor. No me cabe duda de que has venido a aprender, pero debes comprometerte a ello tanto en espíritu como en forma.' WHERE `ID`=48569;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드워프가 한 말이 사실입니다. 정령들과 교감하려면 진실한 마음이 필요합니다.', `FemaleText_loc4`='那矮人说得没错。如果你希望与元素交流，你就必须具备发自内心的诚意。', `FemaleText_loc5`='矮人說的是事實。如果你想要和元素交流，你必須打從心底去做。', `FemaleText_loc7`='El enano dice la verdad. Si deseas entrar en comunión con los elementos, debes hacerlo desde el corazón.' WHERE `ID`=48570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 진실한 마음, 땅과 부족을 사랑하는 그 진실한 마음이 그대를 여기로 이끈 것입니다. 절대로 무기나 갑옷이 아니지요.', `FemaleText_loc4`='是你的心，是你对家园与人民的热爱把你引到了这里。不是你的战甲，也不是你的武器。', `FemaleText_loc5`='你的心，你對你們土地和人民的熱愛是引領你來此的原因。不是因為你的盔甲或你的武器。', `FemaleText_loc7`='Tu corazón, tu amor por tu tierra y tu pueblo, eso es lo que te ha traído aquí. No han sido tu armadura ni tus armas.' WHERE `ID`=48571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 본래의 목적을 잊지 않도록 온전히 전념해야 합니다.', `MaleText_loc4`='萨尔，你必须将自己的全部身心投入于其中。', `MaleText_loc5`='索爾，你必須為了目的完全投入自己。', `MaleText_loc7`='Thrall, debes entregarte por entero a la causa.' WHERE `ID`=48572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라가 비난하는 눈초리로 가반을 노려봅니다.', `MaleText_loc4`='阿格娜用不满的目光瞥了加文一眼。', `MaleText_loc5`='阿格拉給了迦文一個不滿的眼神。', `MaleText_loc7`='Aggra lanza a Gavan una mirada de reproche.', `FemaleText_loc1`='아그라가 비난하는 눈초리로 가반을 노려봅니다.', `FemaleText_loc4`='阿格娜用不满的目光瞥了加文一眼。', `FemaleText_loc5`='阿格拉給了迦文一個不滿的眼神。', `FemaleText_loc7`='Aggra lanza a Gavan una mirada de reproche.' WHERE `ID`=48573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘, 언제까지나 대족장과 주술사의 길을 동시에 걸을 순 없습니다. 언젠가는 한쪽 길에 전념해야 할 테니까요. 그 시기가 빠르게 가까워져 옵니다.', `FemaleText_loc4`='古伊尔。你不能继续在酋长与萨满这两种身份间徘徊。总有一天，你必须让自己做出选择。这一天很快就会到来。', `FemaleText_loc5`='高爾。你不能繼續在大酋長和薩滿的角色之間搖擺。當時刻來臨，你終究得選擇完全投入其中一個。而那個時刻正在飛快的接近中。', `FemaleText_loc7`='Go''el. No puedes seguir debatiéndote entre ser un Jefe de Guerra o un chamán. Llegará el momento en el que deberás comprometerte con un papel por entero. Ese momento se acerca a marchas forzadas.' WHERE `ID`=48574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 분의 의견 모두 잘 들었고 조언 감사합니다.', `MaleText_loc4`='你们两个的话我都听过了，感谢你们的忠告。', `MaleText_loc5`='我聽到你們兩個人說的話，而且很感謝你們的建議。', `MaleText_loc7`='He oído lo que los dos tenían que decir y estoy agradecido por su consejo.' WHERE `ID`=48575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 진실을 이해하려면, 그리고 새로운 변화를 가져오려면 온전히 한 길에 전념해야 한다는 사실을 깨달았습니다. 이제 그 사실을 겸허히 받아들여야겠습니다.', `MaleText_loc4`='如果我想要了解所发生的一切，如果我想要发挥作用，我就必须全身心地投入，必须真心服从。', `MaleText_loc5`='如果我了解得沒錯，如果我要改變局勢，我的奉獻必須是絕對的。我必須投入。', `MaleText_loc7`='Si quiero entender lo que está ocurriendo, si quiero marcar la diferencia, mi entrega debe ser absoluta. Debo someterme.' WHERE `ID`=48576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건... 단지... 시작에 불과하다, 필멸자들아! 너희는... 모두 죽을 것이다!', `MaleText_loc4`='这……只是……开始，凡人们！你们……全都要死！', `MaleText_loc5`='凡人，這...只是個...開始!你們會全部...死光!', `MaleText_loc7`='¡Esto... no es más... que el principio, mortales! ¡TODOS... MORIRÉIS!' WHERE `ID`=48577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 해야 할 일이 많습니다. 도울 준비는 되셨습니까?', `MaleText_loc4`='这里还有很多事情要做，$r。你做好帮忙的准备了吗？', `MaleText_loc5`='這附近還有很多事情得處理，$r。你準備好來幫忙了嗎?', `MaleText_loc7`='Hay mucho que hacer por aquí, $r. ¿Estás $glisto:lista; para ayudar?', `FemaleText_loc1`='여기서는 해야 할 일이 많습니다. 도울 준비는 되셨습니까?', `FemaleText_loc4`='这里还有很多事情要做，$r。你做好帮忙的准备了吗？', `FemaleText_loc5`='這附近還有很多事情得處理，$r。你準備好來幫忙了嗎?', `FemaleText_loc7`='Hay mucho que hacer por aquí, $r. ¿Estás $glisto:lista; para ayudar?' WHERE `ID`=48578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바라딘 주둔지에 온 걸 환영하오. 지금은 보잘것없어 보이겠지만 우리가 조금만 노력하면 이곳을 멋진 주둔지로 만들 수 있을 것이오.', `MaleText_loc4`='欢迎来到巴拉丁营地。我知道现在这里还完全不像是一座营地，但只要经过一番努力营建，我们就能让这里初具规模了。', `MaleText_loc5`='歡迎來到巴拉丁營地。我知道這裡現在看起來不怎麼樣，但只要稍微努力一番，我們就能把這裡整頓得很像樣。', `MaleText_loc7`='Bienvenido al Campamento de Baradin. Ya sé que no parece gran cosa ahora mismo, pero con un poco de trabajo duro podremos poner en forma este sitio.', `FemaleText_loc1`='바라딘 주둔지에 온 걸 환영하오. 지금은 보잘것없어 보이겠지만 우리가 조금만 노력하면 이곳을 멋진 주둔지로 만들 수 있을 것이오.', `FemaleText_loc4`='欢迎来到巴拉丁营地。我知道现在这里还完全不像是一座营地，但只要经过一番努力营建，我们就能让这里初具规模了。', `FemaleText_loc5`='歡迎來到巴拉丁營地。我知道這裡現在看起來不怎麼樣，但只要稍微努力一番，我們就能把這裡整頓得很像樣。', `FemaleText_loc7`='Bienvenido al Campamento de Baradin. Ya sé que no parece gran cosa ahora mismo, pero con un poco de trabajo duro podremos poner en forma este sitio.' WHERE `ID`=48579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 승부가 났습니다. 도전자들이 저 멍멍이를 확실히 쓰러뜨렸습니다! 대학살의 도가니 최고의 용사가 이렇게 무너지나요!', `MaleText_loc4`='不可否认——他们真的干掉了那条狗！我们的前任冠军也只不过是这个水平而已！', `MaleText_loc5`='這是無庸置疑的，他們把那條狗搞定了!我們的前任冠軍也不怎麼樣嘛!', `MaleText_loc7`='¡No se puede negar... que han acabado con ese perro! ¡Vaya ex campeón!' WHERE `ID`=48580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 할 일이 끊임없이 생기는 것 같습니다. 정말 이상하게도 매일 새벽 3시면 새로운 임무가 도착하고 있습니다.', `MaleText_loc4`='看样子，我们在这里永远都有事要做。新的命令会在每天凌晨三点到达。这可真是奇怪。', `MaleText_loc5`='看起來這裡有做不完的事。每天凌晨三點都會有新的命令，真的很奇怪。', `MaleText_loc7`='Al parecer siempre hay cosas que hacer por aquí. Han llegado nuevas órdenes a las tres de la mañana, es muy raro.', `FemaleText_loc1`='여기서는 할 일이 끊임없이 생기는 것 같습니다. 정말 이상하게도 매일 새벽 3시면 새로운 임무가 도착하고 있습니다.', `FemaleText_loc4`='看样子，我们在这里永远都有事要做。新的命令会在每天凌晨三点到达。这可真是奇怪。', `FemaleText_loc5`='看起來這裡有做不完的事。每天凌晨三點都會有新的命令，真的很奇怪。', `FemaleText_loc7`='Al parecer siempre hay cosas que hacer por aquí. Han llegado nuevas órdenes a las tres de la mañana, es muy raro.' WHERE `ID`=48581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 우리의 도전자들을 상대할 자가 아직 한 명 더 남아 있습니다. 자, 돈을 거십시오!', `MaleText_loc4`='看样子，我们又有了一个新的挑战者。现在，大家下注吧！', `MaleText_loc5`='看起來我們還有一個挑戰者要面對，所以快點下注吧!', `MaleText_loc7`='Al parecer hay otro contendiente al que tenemos que hacer frente, así que ¡quiero ver esas apuestas!' WHERE `ID`=48582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 호드까지 우리를 집요하게 괴롭히고 있소. 우리는 마치 두 종류의 전투를 한 번에 치르고 있는 것 같소.', `MaleText_loc4`='部落对这里发动了凶狠的攻击。我们要在同一时间内进行两场战争。', `MaleText_loc5`='部落在這裡非常的頑強。感覺上我們像是同時在打兩場仗。', `MaleText_loc7`='La Horda ha sido implacable ahí fuera. Es como si estuviéramos luchando en dos batallas a la vez.', `FemaleText_loc1`='이제는 호드까지 우리를 집요하게 괴롭히고 있소. 우리는 마치 두 종류의 전투를 한 번에 치르고 있는 것 같소.', `FemaleText_loc4`='部落对这里发动了凶狠的攻击。我们要在同一时间内进行两场战争。', `FemaleText_loc5`='部落在這裡非常的頑強。感覺上我們像是同時在打兩場仗。', `FemaleText_loc7`='La Horda ha sido implacable ahí fuera. Es como si estuviéramos luchando en dos batallas a la vez.' WHERE `ID`=48583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분 모두 열과 성을 다해 이자를 미워하시겠지요. 하지만 이자 또한 자신의 증오를 여러분께 기꺼이 퍼부을 것입니다. 최후의... 경기를... 시작합니다!!!', `MaleText_loc4`='你们全都热衷于痛恨他。而他也喜欢向你们表达他的恨意。让……战斗……开始吧！！！', `MaleText_loc5`='你們都很愛仇視他，而他也會很樂意把仇恨灑向大家。讓我們...見血吧!', `MaleText_loc7`='A todos les encantará odiarlo, y él está contento de devolverles su odio. ¡¡QUE... EMPIECE... LA CARNICERÍA!!' WHERE `ID`=48584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 멋진 물건들을 둘러보세요.', `MaleText_loc4`='好好欣赏一下我精美的藏品吧。', `MaleText_loc5`='看看我的好東西。', `MaleText_loc7`='Disfruta de mis finas mercancías.' WHERE `ID`=48585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $n. 덕분에 고통이 사라졌습니다.', `MaleText_loc4`='谢谢你，$n。我受到的折磨终于结束了。', `MaleText_loc5`='謝謝你，$n。我的折磨終於結束了。', `MaleText_loc7`='Gracias, $n. Mi tormento ha llegado a su fin.', `FemaleText_loc1`='고맙습니다, $n. 덕분에 고통이 사라졌습니다.', `FemaleText_loc4`='谢谢你，$n。我受到的折磨终于结束了。', `FemaleText_loc5`='謝謝你，$n。我的折磨終於結束了。', `FemaleText_loc7`='Gracias, $n. Mi tormento ha llegado a su fin.' WHERE `ID`=48586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주가 끝났습니다!', `MaleText_loc4`='诅咒结束了！', `MaleText_loc5`='詛咒結束了!', `MaleText_loc7`='¡La maldición termina!', `FemaleText_loc1`='저주가 끝났습니다!', `FemaleText_loc4`='诅咒结束了！', `FemaleText_loc5`='詛咒結束了!', `FemaleText_loc7`='¡La maldición termina!' WHERE `ID`=48587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내, 고통이 사라졌습니다...', `MaleText_loc4`='终于，痛苦停止了……', `MaleText_loc5`='終於，苦痛停止了...', `MaleText_loc7`='Finalmente cesa la agonía...', `FemaleText_loc1`='마침내, 고통이 사라졌습니다...', `FemaleText_loc4`='终于，痛苦停止了……', `FemaleText_loc5`='終於，苦痛停止了...', `FemaleText_loc7`='Finalmente cesa la agonía...' WHERE `ID`=48588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분. 와일드해머가 걸어온 삶의 방식이 위협받고 있습니다. 지금처럼 서로 고립된 채 상대하기엔 우리의 적이 너무 많습니다. 우리는 힘을 합쳐야 합니다!', `MaleText_loc4`='朋友们。蛮锤正在受到致命的威胁。我们的敌人太强大了。我们只凭一己之力无法与他们对抗。我们必须团结起来！', `MaleText_loc5`='朋友們。蠻錘的生活方式受到了威脅。我們的敵人太多，我們不能再被各個擊破。我們必須團結!', `MaleText_loc7`='Amigos. El estilo de vida de los Martillo Salvaje se ve amenazado. Nuestros enemigos son muy numerosos y nosotros no podemos permitirnos seguir aislados los unos de los otros. ¡Debemos unirnos!' WHERE `ID`=48589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 비밀의회의 힘이 극에 달합니다!', `MaleText_loc4`='风之议会即将获得全部力量！', `MaleText_loc5`='風之議會的力量已經接近顛峰!', `MaleText_loc7`='¡El Cónclave del Viento está a punto de alcanzar su fuerza máxima!' WHERE `ID`=48590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 몸은 참으로 훌륭하군! 내 약속하지. 이 마취제를 조금만 들이키면, 깨어날 땐 지금보다 10배는 더 강하고 100배는 더... 계획적으로 조화를 이룬 모습이 될 걸세.', `MaleText_loc4`='你们的身体条件都很出色！如果你们愿意吸点儿这种麻醉剂，我保证当你们醒来时会比现在强壮10倍，凝聚力比现在强……100倍。', `MaleText_loc5`='你們的身體十分驚人。如果你們願意喝下一點點麻醉藥劑，我保證你們醒來時會比現在強十倍，而且會比現在更為...團結百倍。', `MaleText_loc7`='¡Sus cuerpos son magníficos! Si estuvieran dispuestos a aspirar ligeramente el aroma de este cloroformo, les prometo que los despertará 10 veces más fuertes y 100 veces más... unificados con ese propósito.' WHERE `ID`=48591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싫다고? 그래... 어쨌든 내 제안은 아직 유효하네. 마음이 바뀌면 언제든 들르게. 자네가 꿈에 그리던 모습으로 손봐 줄 테니.', `MaleText_loc4`='不愿意？好吧……这项提议永远有效。欢迎随时到我这里来，我很乐意提供你们梦寐以求的大变身。', `MaleText_loc5`='不要?好吧...我的提議仍然有效。你任何時候都能來找我，我會給你一直想要的美容。', `MaleText_loc7`='¿No? Bueno... Mi oferta sigue en pie. Vengan cuando quieran y estaré más que contento de facilitarles las mejoras con las que han soñado.' WHERE `ID`=48592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!', `MaleText_loc4`='%s开始从剩下的风领主身上获得力量！', `MaleText_loc5`='%s開始從剩下的風領主那裡取得力量!', `MaleText_loc7`='¡%s empieza a extraer fuerza de los señores del viento que quedan!' WHERE `ID`=48593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 좀 진정하시고...', `MaleText_loc4`='绅士们，请……', `MaleText_loc5`='先生們，麻煩一下...', `MaleText_loc7`='Señores, por favor...' WHERE `ID`=48594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 이거 예상했던 것보다 더 어렵군요.', `MaleText_loc4`='啊！这比我想象的更难。', `MaleText_loc5`='嘖!這比我想像中還要難。', `MaleText_loc7`='¡Ay! Esto será más difícil de lo que creía.' WHERE `ID`=48595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 남아 있는 바람의 군주에게서 힘을 모으기 시작합니다!', `MaleText_loc4`='%s开始从剩下的风领主身上获得力量！', `MaleText_loc5`='%s開始從剩下的風領主那裡取得力量!', `MaleText_loc7`='¡%s empieza a extraer fuerza del señor del viento que queda!' WHERE `ID`=48596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 딱 파이어비어드다운 소리만 하는군. 그 오동통한 코끝보다 멀리 있는 건 하나도 보질 못하니... 우린 용아귀 놈들과 뒤엉켜서 싸우고 있었다고. 그런데 자네가 그리핀 하나라도 보내줬나? 아니!', `MaleText_loc4`='喔，这可真符合焰须的身份，对自己大鼻子以外的一切都视而不见。我们在龙喉那被逼得走投无路。可你有派过一只鸟来帮忙吗？没有！', `MaleText_loc5`='噢，這真是典型的火鬍啊，除了自己肥大的鼻子啥都看不到。我們跟龍喉已經在割喉戰了。你們有派隻鳥過來幫忙嗎?沒有!', `MaleText_loc7`='¡Oh, es tan típico de un Barbafuego no ver más allá de su gruesa nariz! ¡Estamos metidos hasta el cuello entre los Faucedraco! ¿Pero has mandado un solo pájaro a ayudarnos? ¡NO!' WHERE `ID`=48597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도저히 참을 수가 없군. 우리 썬더마는 파이어비어드가 있는 얼라이언스엔 들어가지 않습니다. 할 말은 이것뿐입니다!', `MaleText_loc4`='我不必接受这个。有焰须归附的联盟和我将无半点儿干系。我的话到此为止！', `MaleText_loc5`='我受夠了。我不想要再繼續留在跟火鬍結盟的聯盟了。這就是我的最後決定!', `MaleText_loc7`='No pienso aguantar esto. No formaré parte de ninguna Alianza que cuente con un Barbafuego. ¡He dicho!' WHERE `ID`=48598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 합친다고요? 지금 와서 말입니까? 황혼의 망치단 주술사들이 바닷가에 있는 우리 요새를 짓밟을 때 썬더마가 힘을 보태준 것 같지는 않은데요.', `MaleText_loc4`='团结？现在？就连那群暮光萨满祭司攻破我们位于海岸上的要塞时，桑德玛尔人都没能真正团结起来。', `MaleText_loc5`='團結?現在嗎?桑德瑪的人在暮光之錘的薩滿把我們海邊的堡壘拆掉時可一點都不團結啊。', `MaleText_loc7`='¿Unidad? ¿Ahora? Los Bramal no estaban uniéndose precisamente cuando los chamanes Crepusculares destrozaron nuestra fortaleza en la orilla.' WHERE `ID`=48599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더마, 여기가 신성한 땅만 아니었으면 내가 자넬 비 오는 날 먼지 나게 패줬을 거야!', `MaleText_loc4`='桑德玛尔，如果我们不是站在这片神圣的土地上，我就会把你一拳击飞，这地上留下的只有你的鞋！', `MaleText_loc5`='桑德瑪，如果我們現在站的地方不是聖地，我會用我的拳頭用力扁你，用力到你只剩鞋子留在地上!', `MaleText_loc7`='¡Bramal, si no estuviéramos en suelo sagrado te pegaría tan fuerte que lo único que quedaría de ti sobre el suelo serían tus zapatos!' WHERE `ID`=48600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 오! 그래! 내 감각이 이제야 돌아왔군! 사악한 인간 마법사가 내 정신에 저주를 건 게 틀림없어. 빨리 육지로 올라가세! 카샤가 다쳤어!', `MaleText_loc4`='喔……喔！太好了！奥尔库斯恢复了神智！那个该死的人类法师肯定诅咒了奥尔库斯的灵魂。我们必须赶快前往海岸！卡莎受伤了！', `MaleText_loc5`='噢...噢!沒錯!歐庫斯恢復神智了!那個該死的人類法師一定是詛咒了歐庫斯的大腦。我們必須快點去海岸!卡沙受傷了!', `MaleText_loc7`='¡Oh... OH! ¡Orkus ha recuperado la cordura! Ese maldito mago humano ha tenido que maldecir la mente de Orkus. ¡Rápido, tenemos que llegar a la orilla! ¡Kasha está herida!' WHERE `ID`=48601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카샤! 이리 오거라! 난 무사하다!', `MaleText_loc4`='卡莎！到我这儿来！我没事！', `MaleText_loc5`='卡沙!來我這!我很好!', `MaleText_loc7`='¡Kasha! ¡Ven a mí! ¡Estoy bien!' WHERE `ID`=48602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카샤! 안돼!', `MaleText_loc4`='卡莎！不！！', `MaleText_loc5`='卡沙!不要!', `MaleText_loc7`='¡KASHA! ¡¡NO!!' WHERE `ID`=48603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러다 죽겠어!$B$B*꼬르륵*$B$B살려줘!', `MaleText_loc4`='我要死啦！$B$B*呃呃*$B$B救命！', `MaleText_loc5`='我會死的!$B$B*吞*$B$B救命啊!', `MaleText_loc7`='¡No sobreviviré!$B$B*GULP*$b$b¡AYÚDAME!' WHERE `ID`=48604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발이 땅에 닿는 것 같습니다, 오르쿠스 님. 여긴 얕은 물가예요. 그냥 서서 육지로 걸어오시면 됩니다.', `MaleText_loc4`='你能站起来，奥尔库斯。这里只是浅水。赶快走到岸上去吧。', `MaleText_loc5`='你又不是吊在半空，歐庫斯。這是淺水。站起來走向岸邊就行了。', `MaleText_loc7`='Tus pies tocan el suelo, Orkus. Son aguas poco profundas. Simplemente ponte de pie y camina a la orilla.', `FemaleText_loc1`='발이 땅에 닿는 것 같은데요, 오르쿠스 님. 여긴 얕은 물가예요. 그냥 서서 육지로 걸어오시면 돼요.', `FemaleText_loc4`='你能站起来，奥尔库斯。这里只是浅水。赶快走到岸上去吧。', `FemaleText_loc5`='你又不是吊在半空，歐庫斯。這是淺水。站起來走向岸邊就行了。', `FemaleText_loc7`='Tus pies tocan el suelo, Orkus. Son aguas poco profundas. Simplemente ponte de pie y camina a la orilla.' WHERE `ID`=48605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르쿠스에게 그가 얕은 물 속에 서 있다고 설명해야 합니다.|Tinterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc4`='向奥尔库斯说明，他只是站在浅水里。|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc5`='跟歐庫斯解釋他站的地方是淺水。|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc7`='Explica a Orkus que está en aguas poco profundas.|TInterface\GossipFrame\GOSSIPGOSSIPICON.blp:32|t' WHERE `ID`=48606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림 바톨이 무너진 이래, 우리 와일드해머는 진정 힘을 합쳤던 적이 없네. 저 다양한 가문들은 여기 고원에서 세상에 잊힌 채 모두 자기들 방식대로 살아왔지.$B$B저들이 협력하게 하는 건 쉽지 않을 걸세.', `MaleText_loc4`='自从格瑞姆巴托陷落之后，我们蛮锤部族就再也没有真正团结起来。在这高地之上，被世界所遗忘，各个部族都已选择了各自的生存方式。$B$B若想将他们重新凝聚在一起可不是件容易的事。', `MaleText_loc5`='自從格瑞姆巴托失陷後，我們蠻錘就從來都沒有真正再團結統一了。在高地這裡，被整個世界所遺忘，不同的氏族都各自為政。$B$B要把他們全部都聚集起來不是件簡單的事。', `MaleText_loc7`='Desde la caída de Grim Batol, los Martillo Salvaje nunca hemos estado unidos de verdad. En las Tierras Altas hemos olvidado al resto del mundo, y los diferentes clanes han seguido sus propios caminos.$B$BReunirlos de nuevo no va a ser fácil.' WHERE `ID`=48607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $n, 나도 바깥에서 그 안타까운 대화를 들었네.$B$B옛 와일드해머 형제들이 스스로 협력하는 방법을 찾아내길 바랐건만, 영 가망이 없어 보이는군.$B$B자네와 내가 뭔가 창의적인 해결책을 찾아내야 해.', `MaleText_loc4`='是的$n，我已经了解外间所发生的悲惨事件的全貌。$B$B我原本希望我那群蛮锤兄弟们能自行解决，可看来不行。$B$B你和我必须想些有创意的办法。', `MaleText_loc5`='是的，$n，我已經聽說了發生在這裡的悲慘事情。$B$B我本來希望我的老蠻錘兄弟們能自己解決掉，但是看起來是不會發生了。$B$B你跟我必須要有點創意才行。', `MaleText_loc7`='Sí, $n, lo he oído todo desde aquí.$B$BEsperaba que mis antiguos hermanos del Martillo Salvaje pudieran resolver sus problemas, pero parece ser que no es posible.$B$BTú y yo vamos a tener que ponernos creativos.' WHERE `ID`=48608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 저와 함께 가시지요, $n.', `MaleText_loc4`='来！跟我走，$n。', `MaleText_loc5`='來吧，跟我一起走走，$n。', `MaleText_loc7`='¡Vamos! Ven conmigo, $n.' WHERE `ID`=48609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 아름다운 땅입니다. 그렇지 않나요?', `MaleText_loc4`='这片土地可真美啊，不是吗？', `MaleText_loc5`='這真是片美麗的土地，不是嗎?', `MaleText_loc7`='Esta es una tierra hermosa, ¿no crees?' WHERE `ID`=48610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상 모든 곳에 위험이 도사리고 있다는 사실을 잊어버리고, 이런 아름다움을 당연하게 받아들이기가 쉽습니다.', `MaleText_loc4`='当危险无处不在的时候，它们也就变成家常便饭了。', `MaleText_loc5`='在危機四伏的時刻，我們很容易就把這一切視為理所當然。', `MaleText_loc7`='Es muy fácil darlo todo por sentado cuando el peligro nos aguarda en cada esquina.' WHERE `ID`=48611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구와 적을 구별하기가 쉽지 않은 때도 있지요...', `MaleText_loc4`='当面对敌友难分的情境时……', `MaleText_loc5`='當很難分辨敵我的時候...', `MaleText_loc7`='Cuando resulta difícil distinguir a amigo de enemigo...' WHERE `ID`=48612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 언젠가 그 모든 일은 바뀝니다, $n. 그리고 오직 미래를 보는 눈을 지닌 사람만이 그런 시대를 맞이할 수 있을 겁니다.', `MaleText_loc4`='但终有一天，这一切都会改变，$n。当那一天到来的时候，那些看到幻象的人才会有所准备。', `MaleText_loc5`='但這有一天會整個改變的，$n。當一切改變時，只有具有遠見的人會有所準備。', `MaleText_loc7`='Pero eso cambiará algún día, $n. Y cuando ese día llegue, los que tenemos visión estaremos preparados.' WHERE `ID`=48613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠은 보물로 가득합니다, 친구.', `MaleText_loc4`='奥丹姆里蕴藏着丰富的财宝，我的朋友。', `MaleText_loc5`='奧丹姆藏了很多寶藏，朋友。', `MaleText_loc7`='Uldum tiene muchos tesoros, camarada.' WHERE `ID`=48614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일부는 평범한 사람이라도 알아볼 수 있지만, 나머지는 진가를 볼 수 있는 지혜를 필요로 합니다.', `MaleText_loc4`='有些就连那些最天真的人都能发现，而要想找到另一些，则需要具备非凡的智慧。', `MaleText_loc5`='有些就算是平凡人都能看得出來，而有些則需要智慧。', `MaleText_loc7`='Algunos son fáciles de descubrir incluso para los hombres más simples, pero otros requieren sabiduría para verlos.' WHERE `ID`=48615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리라 님께서 널 지원하라고 명령하셨다. 만약 옵시디아가 여기 있다면, 네가 그녀를 처치할 수 있도록 내가 주의를 끌겠다.', `MaleText_loc4`='莉拉让我来留心你们的身后。如果欧比斯迪在这儿的话，我会吸引住她，然后就要由你们来解决她了。', `MaleText_loc5`='麗菈派我來照看你們。如果奧希蒂亞在這裡，我會引開她的注意力，讓你可以解決她。', `MaleText_loc7`='Lira me ha enviado para vigilar tus espaldas. Si Obsidia está aquí, yo la distraeré mientras tú acabas con ella.' WHERE `ID`=48616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠이 언젠가 위험한 황야가 아닌 관광객을 끌어모으는 명소로 변해갈 모습이 눈에 선하네요!', `MaleText_loc4`='这里有古老废墟与庄严金字塔，危机遍布的奥丹姆荒野，一定能变成观光者向往的天堂！', `MaleText_loc5`='我可以預見奧丹姆有天會從危險的荒野變成吸引遊客的磁石!', `MaleText_loc7`='¡Preveo que algún día Uldum pasará de ser un peligroso lugar salvaje a un imán para los turistas!' WHERE `ID`=48617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요오오오!', `MaleText_loc4`='救命！', `MaleText_loc5`='救命啊啊啊啊!', `MaleText_loc7`='¡Ayuuuuuuda!' WHERE `ID`=48618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 모든 사람이 이곳의 불가사의를 두 눈으로 직접 보러 찾아올 테지요.', `MaleText_loc4`='人们从艾泽拉斯各地赶来，向她的奇迹致敬。', `MaleText_loc5`='人們會從艾澤拉斯的各地前來欣賞她的美麗。', `MaleText_loc7`='La gente vendrá de todas partes de Azeroth para asombrarse ante sus maravillas.' WHERE `ID`=48619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜린 님이 회합에 출석하느라 자리를 비운 사이 출렁배 오우거들이 썬더마를 휩쓸었습니다. 그러고는 패니를 붙잡아서 언덕으로 도망가 버렸어요!', `MaleText_loc4`='黏肠食人魔趁科林离开之机，攻入了桑德玛尔。他们把范妮劫走了！', `MaleText_loc5`='噁腸巨魔趁柯林在高峰會時攻擊了桑德瑪。他們把芬妮拐走了，跑進了丘陵地!', `MaleText_loc7`='Los ogros Tripal invadieron Bramal mientras Colin estaba aquí, en la cima. ¡Secuestraron a Fanny y corrieron a las colinas!' WHERE `ID`=48620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그 사람들이 경탄하며 바라볼 수 있는 나만의 불가사의를 만들 계획입니다.', `MaleText_loc4`='我计划亲自创造出一个奇迹，让他们全都看看……', `MaleText_loc5`='我計畫自己製造一個奇觀讓他們瞧瞧...', `MaleText_loc7`='Tengo planeado crear una maravilla propia para que todos la contemplen anonadados...' WHERE `ID`=48621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콜린 님은 썬더마 일족을 이끌고 출렁배 동굴을 총공격할 준비를 하고 있습니다.', `MaleText_loc4`='科林正在集结桑德玛尔部众，准备对黏肠的洞窟发起全面攻击。', `MaleText_loc5`='柯林正在聚集桑德瑪的軍隊，準備大舉進攻噁腸巨魔谷地。', `MaleText_loc7`='Colin está reuniendo a los Bramal para lanzar un ataque total a Foso Tripal.' WHERE `ID`=48622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 또 웬 소란이지?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這裡，這是啥?', `MaleText_loc7`='Mira, ¿qué es esto?' WHERE `ID`=48623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF난 부둣가의 화장실을 쓰고 나오는 길이었지. 그때...|r', `MaleText_loc4`='|cFFFFFFFF那时，我刚刚使用完码头上的设备……|r', `MaleText_loc5`='|cFFFFFFFF我已經使用完甲板上的設備，當..|r', `MaleText_loc7`='|cFFFFFFFFJusto había terminado de utilizar las instalaciones de los muelles cuando...|r' WHERE `ID`=48624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='읔, 냄새가 고약해... 내 배가 큰 걸 요리했나 보군. 그렇지 않고서야 이런 냄새가 날 순 없지.', `MaleText_loc4`='呃，他们一定在煮粪便吃——不然这气味没法解释。', `MaleText_loc5`='呃，那些部落的傢伙一定是在煮大便...不然不會這麼臭。', `MaleText_loc7`='Agh, seguro que el lok''tar ha estado cocinando un pedazo de estiércol, lo que explicaría el olor.' WHERE `ID`=48625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$B$B|cFFFFFFFF화장실에서 나왔을 때, 난 놈들을 발견했네! 오르쿠스가 볼일을 볼 땐 조용한 걸 좋아한다는 사실을 기억해두게.|r$B', `MaleText_loc4`='$B$B|cFFFFFFFF我从厕所出来的时候看见他们了！要注意的是，奥尔库斯在做事的时候喜欢安静。|r$B', `MaleText_loc5`='$B$B|cFFFFFFFF當我從廁所出來時，我看到他們!應注意的是，歐庫斯在執行任務時喜歡安靜。|r$B', `MaleText_loc7`='$B$B|cFFFFFFFFCuando salí del excusado exterior, ¡los vi! Debí haberme dado cuenta de que Orkus prefiere guardar silencio cuando está cumpliendo con su deber.|r$B' WHERE `ID`=48626;
