UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 발린다. 이바르 블러드팽이란 작자는 어디서 만나기로 했지? 그건 그렇고, 이 역겨운 냄새는 대체 뭐야?', `MaleText_loc4`='哎，琳达，我们要在哪里跟这个名叫伊瓦·血牙的家伙碰面？而且以铜须的名义——这难闻的气味到底是怎么回事？', `MaleText_loc5`='喂，琳達，我們和這個叫伊瓦·血牙的傢伙要在哪裡碰面啊?還有，以銅鬚之名啊，那股惡臭是怎麼回事?', `MaleText_loc7`='Eh, Linda, ¿dónde vamos a reunirnos con ese tal Ivar Colmillo de Sangre? Y en nombre de Barbabronce, ¿qué es eso que apesta?' WHERE `ID`=48635;
