UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지?! 우릴 쳐다볼 때의 그 굶주린 눈빛이란... 등을 보이기도 무섭다니까!', `MaleText_loc4`='我知道！瞧他看你时那双饥渴的眼睛，我就全都知道了。真不知道他背着我的时候会干出什么来！', `MaleText_loc5`='沒錯沒錯!他會用飢餓的眼神盯著你。我連轉身背對他都不敢!', `MaleText_loc7`='¡Lo sé! Cuando te mira con esos ojos hambrientos. ¡Incluso me da miedo darle la espalda!', `FemaleText_loc1`='그렇지?! 우릴 쳐다볼 때의 그 굶주린 눈빛이란... 등을 보이기도 무섭다니까!', `FemaleText_loc4`='我知道！瞧他看你时那双饥渴的眼睛，我就全都知道了。真不知道他背着我的时候会干出什么来！', `FemaleText_loc5`='沒錯沒錯!他會用飢餓的眼神盯著你。我連轉身背對他都不敢!', `FemaleText_loc7`='¡Lo sé! Cuando te mira con esos ojos hambrientos. ¡Incluso me da miedo darle la espalda!' WHERE `ID`=48638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들은 서쪽 해안에 있는 속죄의 섬에 모이고 있습니다. 거기서 그들을 만날 겁니다, 장군님.', `FemaleText_loc4`='他们聚集在西边海中的赎罪岛上。我们要去那里见他们，将军。', `FemaleText_loc5`='他們在贖罪島上集結，就在我們的西邊，靠近海岸。我們要在那裡跟他們碰面，將軍。', `FemaleText_loc7`='Están reuniéndose en la Isla del Purgatorio, justo al oeste de aquí, frente a la costa. Debemos encontrarnos con ellos allí, general.' WHERE `ID`=48639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 냄새는... *공기 중의 냄새를 맡는 발린다* 저쪽에서 나는 것 같습니다...', `FemaleText_loc4`='这股气味……*巴琳达用力抽抽鼻子*，我想它应该是从那里来的……', `FemaleText_loc5`='至於這個味道...*貝琳達嗅了嗅* 我想是從那裡飄過來的...', `FemaleText_loc7`='En cuanto al olor... *Balinda olfatea el aire* Creo que viene de ahí...' WHERE `ID`=48640;
