UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오시지! 따끔하게 한 방 먹여줄 테니!', `FemaleText_loc4`='来吧！让我狠狠给你一下子，兽人！', `FemaleText_loc5`='來這啊!我會好好扁你一頓，獸人!', `FemaleText_loc7`='¡Ven aquí! ¡Voy a darte una tunda, orco!' WHERE `ID`=48665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋다, 오크 자식아. 문신이 닳아 없어지도록 패주마!', `FemaleText_loc4`='没错，兽人。我要把你的魂打飞！', `FemaleText_loc5`='就是這樣，獸人。我會扁你扁到你的刺青都磨光!', `FemaleText_loc7`='Eso es orco. ¡Voy a darte tal paliza que se te borrarán los tatuajes!' WHERE `ID`=48666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나한테 맞아 볼래, 오크 자식아? 내가 흙바닥에 처박아 주지!', `FemaleText_loc4`='我会让你闭嘴，兽人。我会把你埋进土里！', `FemaleText_loc5`='我會解決你，獸人。你會趴在地上吃土!', `FemaleText_loc7`='Voy a hacerte caer, orco. ¡Te haré besar el suelo!' WHERE `ID`=48667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰개의 효과가 사라지고 있습니다!$b$b몸을 숨기세요!', `MaleText_loc4`='隐形即将失效！$b$b快找掩护！', `MaleText_loc5`='障蔽效果即將失效!$b$b尋找掩蔽!', `MaleText_loc7`='¡Está desapareciendo el efecto del embozo!$b$b¡Ponte a cubierto!' WHERE `ID`=48668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 진흙주둥이꽃을 구해왔다, 카샤. 이걸 먹으면 나을 거다.', `MaleText_loc4`='卡莎，$n给你带来了泥头花。吃掉它，你就能痊愈了。', `MaleText_loc5`='$n為你帶來泥嘴花了，卡沙。吃下去，你就會康復。', `MaleText_loc7`='$n te ha traído flores morrobarro, Kasha. Cómelas y te curarás.' WHERE `ID`=48669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 카샤에게 진흙주둥이꽃을 먹입니다.', `MaleText_loc4`='%s将泥头花喂给卡莎。', `MaleText_loc5`='%s餵食卡沙泥嘴花。', `MaleText_loc7`='%s da de comer a Kasha las flores morrobarro.' WHERE `ID`=48670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카샤, 속죄의 섬으로 가자! 천둥처럼 날자꾸나!', `MaleText_loc4`='为了赎罪岛，卡莎！像雷霆一样驰骋吧！', `MaleText_loc5`='去贖罪島，卡沙!乘雲踏電而去!', `MaleText_loc7`='¡A LA ISLA DEL PURGATORIO, KASHA! ¡CABALGA COMO EL TRUENO!' WHERE `ID`=48671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야만스러운 놈들이 제가 잠시 없는 틈에 우리 마을을 공격했습니다! 와일드해머의 심판이 어떤 것인지 보여 주겠어요. 아주 똑똑히!', `MaleText_loc4`='这群畜生妄想趁我转身之机偷袭我的城镇？！我要让他们知道什么叫蛮锤的正义！', `MaleText_loc5`='這些野蠻人以為可以趁我不注意時攻擊我的城鎮?他們即將嘗到蠻錘的正義怒火!', `MaleText_loc7`='¿¡Esos brutos creen que pueden ATACAR mi ciudad mientras no estoy mirando!? ¡Van a saborear la justicia Martillo Salvaje, ya lo creo que sí!' WHERE `ID`=48672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페즈 홉노브 님이 비용을 지불하신 걸로 압니다. 강철나무 공터로 날아가고 싶습니다.', `MaleText_loc4`='我刚刚代表费兹·霍布诺布去过铁木工程营。', `MaleText_loc5`='菲茲·赫柏納授權我以他的名義前往鐵木空地。', `MaleText_loc7`='Tengo una montura esperándome para ir a Claro de Troncoferro en nombre de Fez Placasnob.', `FemaleText_loc1`='페즈 홉노브 님이 비용을 지불하셨을 거예요. 강철나무 공터로 날아가고 싶어요.', `FemaleText_loc4`='我刚刚代表费兹·霍布诺布去过铁木工程营。', `FemaleText_loc5`='菲茲·赫柏納授權我以他的名義前往鐵木空地。', `FemaleText_loc7`='Tengo una montura esperándome para ir a Claro de Troncoferro en nombre de Fez Placasnob.' WHERE `ID`=48673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만약 우리가 생산량을 증가시키지 못하면, 호드가 이 전쟁에서 패배할 수도 있어요. 만약 호드가 전쟁에서 패배하면, 우린 길바닥에 나 앉게 될 거고, 최악으로는 목숨을 잃겠죠.$B$B이런 말을 하고 싶진 않았지만, 당신이 바람속삭임 숲에서 들었을 봉사활동이 우리 생명을 보장하진 않아요. 열심히 일해 호드가 승리하길 바라는 수밖에...', `FemaleText_loc4`='如果我们不尽最大可能提高生产效率，部落也许就要输掉这场战争了。如果部落输了，我们可就死定了。$B$B我不想打碎你的幻想。但你在语风林地听到的那些美妙的玩意可救不了我们……能救我们的只有勤奋的工作。', `FemaleText_loc5`='如果我們不儘快提高產量，部落可能會輸掉這場戰爭。如果部落輸掉這場戰爭，最好的狀況是抱頭鼠竄，最壞的狀況就是會死。$B$B我很不願意告訴你真相，但是你在語風林地聽到的那些動聽的故事可救不了我們...但是努力的工作也許可以。', `FemaleText_loc7`='Si no aumentamos la producción todo lo que podamos, puede que la Horda pierda la guerra. Si la Horda pierde la guerra, nos harán prisioneros o peor, nos matarán.$B$BOdio tener que ser yo quien te lo diga pero las cosas bonitas que hayas podido escuchar en Arboleda Susurravientos no nos salvarán... Pero puede que el trabajo duro sí lo haga.' WHERE `ID`=48674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF이렇게 $n, 오르쿠스, 카샤는 속죄의 섬으로 날아가는데...|r', `MaleText_loc4`='|cFFFFFFFF$n, 奥尔库斯和卡莎飞向了赎罪岛……|r', `MaleText_loc5`='|cFFFFFFFF$n，歐庫斯和卡沙已經飛去贖罪島了...|r', `MaleText_loc7`='|cFFFFFFFF$n, Orkus y Kasha han volado hacia Isla del Purgatorio...|r', `FemaleText_loc1`='|cFFFFFFFF이렇게 $n, 오르쿠스, 카샤는 속죄의 섬으로 날아가는데...|r', `FemaleText_loc4`='|cFFFFFFFF$n, 奥尔库斯和卡莎飞向了赎罪岛……|r', `FemaleText_loc5`='|cFFFFFFFF$n，歐庫斯和卡沙已經飛去贖罪島了...|r', `FemaleText_loc7`='|cFFFFFFFF$n, Orkus y Kasha han volado hacia Isla del Purgatorio...|r' WHERE `ID`=48675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요!$b$b미제리안은 당신의 변장을 간파할 수 있습니다!', `MaleText_loc4`='小心！$b$b麦泽利安能看穿你的伪装！', `MaleText_loc5`='注意!$b$b米澤里安可以看穿你的偽裝!', `MaleText_loc7`='¡CUIDADO!$b$b¡Myzerian puede ver a través de tu disfraz!' WHERE `ID`=48676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 필살기를 쓸 때인가... 뛰어어어어어어어어어어어어!', `MaleText_loc4`='表演我拿手好戏的时刻到了……跑——！', `MaleText_loc5`='是時候做我最擅長的事了...逃啊啊啊啊啊!!', `MaleText_loc7`='Ha llegado la hora de hacer lo que mejor se me da. ¡Correeeeeeeeer!' WHERE `ID`=48677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배선 조작 중', `MaleText_loc4`='破坏', `MaleText_loc5`='破壞中', `MaleText_loc7`='Saboteando', `FemaleText_loc1`='배선 조작 중', `FemaleText_loc4`='破坏', `FemaleText_loc5`='破壞中', `FemaleText_loc7`='Saboteando' WHERE `ID`=48678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 나 지금 어디지?!', `MaleText_loc4`='哇噢！我这是在哪儿？', `MaleText_loc5`='哇賽!我在哪?', `MaleText_loc7`='¡Guau! ¡¿Dónde estoy?!' WHERE `ID`=48679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 때려! 이제 고블린처럼 행동할 시간인가!', `MaleText_loc4`='够了！该像个地精的样子了！', `MaleText_loc5`='夠了!是時候表現得像個哥布林了!', `MaleText_loc7`='¡Ya está bien! ¡Hora de actuar como un goblin!' WHERE `ID`=48680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어! 알았으니 두 번 때리지 마!', `MaleText_loc4`='你不用告诉我两遍！', `MaleText_loc5`='你不需要跟我說第二次!', `MaleText_loc7`='¡No hace falta que me lo digas dos veces!' WHERE `ID`=48681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어! 알았어!', `MaleText_loc4`='我知道了！我知道了！', `MaleText_loc5`='知道了，知道了!', `MaleText_loc7`='¡Lo tengo! ¡Lo tengo!' WHERE `ID`=48682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 심호흡하고... 심호흡하고!', `MaleText_loc4`='深呼吸……深呼吸！', `MaleText_loc5`='深呼吸...深呼吸!', `MaleText_loc7`='¡Respira profundamente... respira profundamente!' WHERE `ID`=48683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮아!', `MaleText_loc4`='我没事！', `MaleText_loc5`='我還好!', `MaleText_loc7`='¡Estoy bien!' WHERE `ID`=48684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 막자고!', `MaleText_loc4`='保持镇静！', `MaleText_loc5`='鎮靜點!', `MaleText_loc7`='¡Recomponte!' WHERE `ID`=48685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그거 기분 괜찮은데!', `MaleText_loc4`='这感觉挺不错！', `MaleText_loc5`='其實感覺還不賴!', `MaleText_loc7`='¡Eso me ha sentado muy bien!' WHERE `ID`=48686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르쿠스와 함께 속죄의 섬으로 가겠나?', `MaleText_loc4`='你会将奥尔库斯护送至赎罪岛吗？', `MaleText_loc5`='你願意陪歐庫斯前往贖罪島嗎?', `MaleText_loc7`='¿Acompañarás a Orkus a Isla del Purgatorio?' WHERE `ID`=48687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 카샤의 곁을 떠나지 않을 걸세.', `MaleText_loc4`='我不会离开卡莎半步。', `MaleText_loc5`='我不會離開卡沙身邊的。', `MaleText_loc7`='No dejará a Kasha.' WHERE `ID`=48688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속죄의 섬으로 가겠습니다.', `MaleText_loc4`='我准备好前往赎罪岛了。', `MaleText_loc5`='我準備好前往贖罪島了。', `MaleText_loc7`='Estoy listo para ir a Isla del Purgatorio.', `FemaleText_loc1`='속죄의 섬으로 가요.', `FemaleText_loc4`='我准备好前往赎罪岛了。', `FemaleText_loc5`='我準備好前往贖罪島了。', `FemaleText_loc7`='Estoy lista para ir a Isla del Purgatorio.' WHERE `ID`=48689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 스승님의 기억과 과거의 진실을 직접 보여주기 위해 여기에 왔소.', `MaleText_loc4`='我来这里是为了见证主人的回忆，还有过往的真实。', `MaleText_loc5`='我來此見證我主人的記憶，以及過去的真相。', `MaleText_loc7`='He venido para ser testigo de la memoria de mi maestro y de la verdad del pasado.' WHERE `ID`=48690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?!', `MaleText_loc4`='这儿发生了什么事？！', `MaleText_loc5`='這裡發生了什麼事?', `MaleText_loc7`='¡¿Qué pasa aquí?!' WHERE `ID`=48691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드님... 세상에 어떻게 이런 일이...?', `MaleText_loc4`='大德鲁伊……究竟是……？', `MaleText_loc5`='大德魯伊...怎麼會...?', `MaleText_loc7`='El archidruida... ¿cómo demonios...?' WHERE `ID`=48692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다... 다른 이들에게 알려야겠습니다. 지금 당장 여사냥꾼 셀루라를 찾아가십시오.', `MaleText_loc4`='我……我必须告诉其它人。你立刻去找女猎手塞露拉。', `MaleText_loc5`='我...我必須告訴其他人。你最好趕快找到女獵手瑟魯娜。', `MaleText_loc7`='Debo... informar a los demás. Tú deberías buscar a la cazadora Selura ahora mismo.' WHERE `ID`=48693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 다가옵니다. 이동 명령을 사용하여 람카헨 용사를 남쪽 언덕으로 움직여야 합니다.$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t', `MaleText_loc4`='敌人在靠近。用移动技能将拉穆卡恒勇士移至南方坡道。$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t', `MaleText_loc5`='敵人正在接近。使用移動技能來將蘭姆卡韓勇士移動到南邊的斜坡上。$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t', `MaleText_loc7`='El enemigo se acerca. Utiliza la habilidad Mover para mover a los campeones Ramkahen a la rampa del sur.$B$B|TInterfaceIconsmisc_arrowleft.blp:64|t' WHERE `ID`=48694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수를 활용하여 보병을 지원해야 합니다. 연발 불화살을 발사하면 대부분의 적 무리를 처치할 수 있습니다.$B$B|TInterface\\Icons\\ability_searingarrow.blp:64|t', `MaleText_loc4`='用弓箭手支援步兵。几支火焰箭就能干掉大部分敌人。$B$B|TInterface\\Icons\\ability_searingarrow.blp:64|t', `MaleText_loc5`='使用弓箭手來支援你的步兵。幾輪火箭的射擊可以解決大多數的敵人。$B$B|TInterface\\Icons\\ability_searingarrow.blp:64|t', `MaleText_loc7`='Utilizar a tus arqueros para apoyar a la infantería. Unas cuantas oleadas de flechas flamígeras derribarán a la mayoría de los grupos.$B$B|TInterfaceIconsability_searingarrow.blp:64|t' WHERE `ID`=48695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발각되었나!', `MaleText_loc4`='我被发现了！', `MaleText_loc5`='我被發現了!', `MaleText_loc7`='¡Nos han descubierto!', `FemaleText_loc1`='발각되었나!', `FemaleText_loc4`='我被发现了！', `FemaleText_loc5`='我被發現了!', `FemaleText_loc7`='¡Nos han descubierto!' WHERE `ID`=48696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가증스러운 $r 녀석!', `MaleText_loc4`='该死的$r！', `MaleText_loc5`='可悲的$r!', `MaleText_loc7`='¡$gMaldito:Maldita; $r!', `FemaleText_loc1`='가증스러운 $r 녀석!', `FemaleText_loc4`='该死的$r！', `FemaleText_loc5`='可悲的$r!', `FemaleText_loc7`='¡$gMaldito:Maldita; $r!' WHERE `ID`=48697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 어둠의 기운으로 가득하군. 반드시 정화해야 해!', `MaleText_loc4`='这地方充满邪恶的气息。它必须得到净化！', `MaleText_loc5`='這個地方充滿了邪惡的氣息!必須淨化這裡!', `MaleText_loc7`='Este lugar apesta a maldad. ¡Debe ser purgado!' WHERE `ID`=48698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적에게 포위되는 경우, 태양의 광휘 기술을 사용하면 아군을 치료하고 적군에게 큰 피해를 입힙니다..$B$B|TInterface\\Icons\\spell_holy_divineprovidence.blp:64|t', `MaleText_loc4`='如果招架不住，记得使用烈日照佑技能！这个技能将治疗你方单位，并给敌人造成巨大伤害。$B$B|TInterface\\Icons\\spell_holy_divineprovidence.blp:64|t', `MaleText_loc5`='如果你寡不敵眾，就使用太陽光輝技能!它會治療你的單位並對敵人造成可怕的傷害。$B$B|TInterface\\Icons\\spell_holy_divineprovidence.blp:64|t', `MaleText_loc7`='¡Utiliza tu facultad Radiancia del sol si te ves rodeado por el enemigo! Sanará a tus unidades e infligirá un terrible daño a tu oponente.$B$B|TInterfaceIconsspell_holy_divineprovidence.blp:64|t' WHERE `ID`=48699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어미늑대가 널 가만두지 않을 거다!', `MaleText_loc4`='狼巢之母会要了你的脑袋！', `MaleText_loc5`='你的頭會送到獸母手上的!', `MaleText_loc7`='¡La madre del cubil te arrancará la cabeza!', `FemaleText_loc1`='어미늑대가 널 가만두지 않을 거다!', `FemaleText_loc4`='狼巢之母会要了你的脑袋！', `FemaleText_loc5`='你的頭會送到獸母手上的!', `FemaleText_loc7`='¡La madre del cubil te arrancará la cabeza!' WHERE `ID`=48700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲에서 꺼져!', `MaleText_loc4`='离开这片森林！', `MaleText_loc5`='離開這片森林!', `MaleText_loc7`='¡Abandona el bosque!', `FemaleText_loc1`='이 숲에서 꺼져!', `FemaleText_loc4`='离开这片森林！', `FemaleText_loc5`='離開這片森林!', `FemaleText_loc7`='¡Abandona el bosque!' WHERE `ID`=48701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간과 드워프가 힘을 합치다니... 대체 어떻게 이런 일이?', `MaleText_loc4`='狼人和矮人合作……这个世界怎么变成了这样？', `MaleText_loc5`='狼人和矮人肩並肩工作...這世界怎麼變這樣子了?', `MaleText_loc7`='Huargen y enanos trabajando juntos... ¿En qué se ha convertido este mundo?' WHERE `ID`=48702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 조각내 버리겠다!', `MaleText_loc4`='我要把你撕碎！', `MaleText_loc5`='我會把你撕成碎片!', `MaleText_loc7`='¡Te haré picadillo!', `FemaleText_loc1`='널 조각내 버리겠다!', `FemaleText_loc4`='我要把你撕碎！', `FemaleText_loc5`='我會把你撕成碎片!', `FemaleText_loc7`='¡Te haré picadillo!' WHERE `ID`=48703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으르릉...', `MaleText_loc4`='呃……', `MaleText_loc5`='吼...', `MaleText_loc7`='Grrrr...', `FemaleText_loc1`='으르릉...', `FemaleText_loc4`='呃……', `FemaleText_loc5`='吼...', `FemaleText_loc7`='Grrrr...' WHERE `ID`=48704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약골이라 불러 미안하군, $n. 처음엔 당연히 다살리아의 앞잡이일 줄 알았거든.', `MaleText_loc4`='抱歉，$n，我不该对你如此不敬。当我们第一次见面的时候，我还以为你只是达萨利亚的一个爪牙。', `MaleText_loc5`='我不該說你渺小的，$n。我們剛見面時我以為你是達薩莉亞的爪牙之一。', `MaleText_loc7`='Siento haberte llamado enclenque, $n. Cuando nos conocimos creí que no eras más que otro de los peones de Darthalia.' WHERE `ID`=48705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네와 난 이제 친구네.', `MaleText_loc4`='$n，我们是朋友。', `MaleText_loc5`='$n，我跟你是朋友。', `MaleText_loc7`='$n, tú y yo somos amigos.' WHERE `ID`=48706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬우스는 분쇄한다!', `MaleText_loc4`='克罗苏斯碎击！', `MaleText_loc5`='克羅蘇斯摧毀你!', `MaleText_loc7`='¡KROSHIUS APLASTAR!' WHERE `ID`=48707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 헬스크림이 그냥 위대한 대족장이라 생각하나? 아니면 역대 가장 위대한 대족장이라 생각하나?', `MaleText_loc4`='加尔鲁什·地狱咆哮：伟大的酋长还是最伟大的酋长？', `MaleText_loc5`='卡爾洛斯·地獄吼: 很棒的大酋長，還是最棒的大酋長?', `MaleText_loc7`='Garrosh Grito Infernal: ¿gran Jefe de Guerra o el más grande Jefe de Guerra?' WHERE `ID`=48708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오해하지 말게, $n. 스랄도 괜찮았어. 지도자로서 강인했거든. 하지만 호드를 이끌만한 자는 아니었던 것 같아. 특히 전쟁이 한창인 지금은 말이야!', `MaleText_loc4`='不要误会我，$n。我喜欢萨尔。他是一位强有力的领袖。但我不认为他适合领导部落，尤其是在一个战争的时代！', `MaleText_loc5`='別搞錯我的意思，$n，我喜歡索爾。他是個強大的領袖，但是我不認為他足以領導部落。尤其是在戰爭的時刻!', `MaleText_loc7`='No me entiendas mal, $n, me gusta Thrall. Era un líder fuerte, pero no creo que estuviera hecho para guiar a la Horda. ¡No en tiempo de guerra!' WHERE `ID`=48709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 바로크 사울팽을 만난 적 있다고 했었나? 그에게 내 우람한 가슴 근육 위에 친필서명을 해달라고 부탁했었지. 그러자 사울팽은 서명은커녕 내 뒤통수에 한 방 먹이더라고. 내가 가끔 깜박깜박하는 건 그 일 때문인 것 같아. 그래도 충분히 맞을 만한 가치가 있었어.', `MaleText_loc4`='我有没有和你说过我和萨鲁法尔相遇时的情景？那时我要他在我硕大的胸肌上签字。他却只是反手给了我一个巴掌，所以我现在经常会记不住事情。但这是值得的。', `MaleText_loc5`='我告訴過你我跟瓦洛克·薩魯法爾碰面那次的事情嗎?我叫他在我巨大的胸肌上簽名。他反手打了我一拳，這也是我現在偶爾會有點健忘的原因。非常值得。', `MaleText_loc7`='¿Alguna vez te he hablado de cuando conocí a Varok Colmillosauro? Le pedí que me firmara un autógrafo en mis enormes músculos pectorales. En vez de eso, él me dio una bofetada y por eso ahora a veces olvido las cosas. Pero mereció la pena de verdad.' WHERE `ID`=48710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린... 혈투의 전장에서 그가 싸우는 모습을 본 적 있지. 맨손으로 거친흉터 설인 다섯을 때려잡더군. 인간치곤 꽤 대단하지 않나?', `MaleText_loc4`='瓦里安·乌瑞恩……我见过他在厄运之槌对敌作战的骁勇身姿。他赤手空拳打死了五个深痕雪人。这对人类来说真是相当难得，不是吗？', `MaleText_loc5`='瓦里安·烏瑞恩...我有一次曾經在厄運之槌見到他戰鬥。他空手殺了五隻深痕雪人。對人類來說這相當不錯了，對吧?', `MaleText_loc7`='Varian Wrynn... Le vi luchar una vez en La Masacre. Mató a cinco yetis Cicatriz Feral con las manos desnudas. No está mal para un humano, ¿eh?' WHERE `ID`=48711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 보진 못했는데, 실바나스가 은빛소나무 숲에서 죽었는데, 그녀가 아끼던 발키르들이 목숨을 바쳐 되살렸다지? 이 이야기에 대해 아는 거 있나?', `MaleText_loc4`='我当时不在场，但我听说，希尔瓦娜斯死在了银松森林。而她所珍爱的瓦格里牺牲自己的生命，让她得以复活。你对此有所了解么？', `MaleText_loc5`='我沒在現場，但是聽說希瓦娜斯在銀松森林死去了，而她寶貝的華爾琪用她們自己的生命將她復活。你聽說過這件事嗎?', `MaleText_loc7`='Yo no estaba allí, pero oí que Sylvanas murió en el Bosque de Argénteos y que sus preciosas Val''kyr la resucitaron a cambio de sus propias vidas. ¿Sabes algo al respecto?' WHERE `ID`=48712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 이바르 블러드팽이 여기 있다면, 다리우스 크롤리는 어디 있지?', `MaleText_loc4`='如果伊瓦·血牙在这里，那达利乌斯·克罗雷又在哪里？', `MaleText_loc5`='如果伊瓦·血牙在這裡，達瑞亞斯·克羅雷又在哪?', `MaleText_loc7`='Si Ivar Colmillo de Sangre está aquí, ¿dónde está Darius Crowley?' WHERE `ID`=48713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대인간들이 작은 무리로 뭉쳐 다니던 때가 좋았어. 새로운 길니아스 늑대인간 연합은 조직적이어서 훨씬 상대하기 힘들거든.', `MaleText_loc4`='我喜欢散乱无序的狼人，你可以随意对他们大杀大砍。而这些新吉尔尼斯狼人联盟要难对付得多。', `MaleText_loc5`='我還是比較喜歡狼人是比較混亂的時候，一小群一小群的行動。這個新的吉爾尼斯狼人聯盟對付起來就麻煩了。', `MaleText_loc7`='Los huargen me gustaban más cuando no eran más un puñado de tipos de desorganizados que andaban en pequeñas manadas. Es mucho más difícil vérselas con esta nueva alianza de los huargen gilneanos.' WHERE `ID`=48714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네와 나 사이의 비밀인데. 리치 왕의 몰락을 직접 봤다는 건 거짓말이었어. 그리고... 음... 난 울두아르 근처에도 간 적 없어. 난... 음... 난 사실 던전 탐험가야. 그래, 난 동료들과 함께 던전을 탐험하곤 하지. 보수는 좋은데 그리 위험하진 않거든.', `MaleText_loc4`='$n，这话我只告诉你，我根本没有见到过巫妖王之死。其实……嗯……我从没有去过奥杜尔。我……嗯……我是地下城探险家。是的，我喜欢和朋友们一起探索地下城。这项事业的回报很丰厚，风险又很低。', `MaleText_loc5`='$n，這個別跟別人說喔，我從來都沒親眼見過巫妖王的隕落。而且...呃...我也沒去過奧杜亞。事實上，我...是個地城探險者。沒錯，我喜歡跟同伴一起探索地城。酬勞相當不錯，而且風險很低。', `MaleText_loc7`='$n, entre tú yo, nunca vi la caída del Rey Exánime. Y.. bueno... nunca he estado en Ulduar. Yo... bueno... soy un explorador de mazmorras. Sí. Prefiero explorar mazmorras con aliados. La paga es excelente y los riesgos mínimos.' WHERE `ID`=48715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕마루는 변했네. 내가 한창일 때, 언덕마루는 전쟁이 끊이지 않는 곳이었거든. 남녘해안의 인간과 드워프가 타렌 제분소의 호드를 끊임없이 공격했었지. 다로우 언덕의 교차로를 지날 때마다 천여 명이 서로 엉켜 격돌하는 모습을 볼 수 있던 때였어. 영광스러운 나날이었지. $n, 이런 날들도 덧없이 지나가는군.', `MaleText_loc4`='希尔斯布莱德已经变了。过去，这里曾经是战火连绵之地。南海镇的人类和矮人不停地向塔伦米尔的部落发动进攻。在很长一段日子里，当你望向达隆山的路口，就会看见上千人在奋死拼杀。那真是一段光荣岁月，$n——而那些岁月都已经悄然逝去了。', `MaleText_loc5`='希爾斯布萊德已經改變了。在我那個年代，希爾斯布萊德是個征戰不休的地方。南海鎮的人類和矮人不斷攻擊塔倫米爾的部落。那個時候，你可以在達隆山那裡的路口看到上千人在戰鬥。光輝的日子，$n...它們總是會過去的。', `MaleText_loc7`='Campos de Trabalomas ha cambiado. En mi época, Campos de Trabalomas era un lugar de constantes batallas. Los humanos y los enanos de Costasur atacaban constantemente a la Horda en Molino Tarren. Aquella era una época en la que nada más pasar el cruce de Colinas de Darrow podías ver a miles de personas inmersas en la batalla. Días gloriosos, $n... que ya han pasado.' WHERE `ID`=48716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 카샤를 얼음왕관에서 발견했네. 카샤는 죽어가고 있었어. 난 카샤를 어둠의 무기고로 데려갔고, 그곳의 죽음의 기사들이 카샤를 간호하고 체력을 회복시켰다네. 지금 우리는 최고의 단짝이야.', `MaleText_loc4`='我在冰冠冰川找到了卡莎。她身负重伤，奄奄一息。我设法将她带回了暗影拱顶，死亡骑士帮她逃脱了死神的魔爪。我们现在已经成为了彼此的挚友。', `MaleText_loc5`='我在寒冰皇冠發現卡沙。她受了重傷而垂危。我把她帶回了暗影穹殿，死亡騎士們幫忙使她康復。現在我們已經成為最好的朋友。', `MaleText_loc7`='Encontré a Kasha en Corona de Hielo. Estaba herida y se moría. Me las arreglé para traerla de vuelta a La Cámara de las Sombras, donde los caballeros de la muerte me ayudaron a devolverle la salud. Ahora somos los mejores amigos.' WHERE `ID`=48717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 소용돌이가 열려 우리 세상을 집어삼킬 수도 있다는 소문을 들었네. 그런 일을 감히 상상할 수 있나?', `MaleText_loc4`='我听说大漩涡已经打开了，将要吞掉整个世界。你能想象这种事情吗？', `MaleText_loc5`='我聽說大漩渦整個打開把世界吞沒的故事。你可以想像這樣的事情發生嗎?', `MaleText_loc7`='He oído historias de que La Vorágine se ha abierto y amenaza con devorar el mundo. ¿Puedes imaginar una cosa así?' WHERE `ID`=48718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 드워프와 늑대인간을 저지한다면, 우린 위대한 호드의 영웅으로 칭송받을 걸세!', `MaleText_loc4`='如果我们能阻止这些矮人和狼人，那我们就是部落的大英雄啦！', `MaleText_loc5`='如果我們阻止這些矮人和狼人，我們就會成為部落的英雄!', `MaleText_loc7`='¡Si detenemos a los enanos y a los huargen seremos aplaudidos como grandes héroes de la Horda!' WHERE `ID`=48719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름을 다루고 계신다면, 불똥이나 화염을 일으킬 수 있는 모든 것에 주의하십시오. 예를 들어, 초, 라이터, 마법사, 케스터의 상점, 그리고 부관 클렁키 말입니다!', `MaleText_loc4`='如果你的身上都是油，那一定要避开一切火星和明火，比如蜡烛、油灯、法师、凯斯特的铺子，还有克朗奇警官！', `MaleText_loc5`='如果你一直跟油搞在一塊兒，記得避開任何火花或火源，像是蠟燭、點火器、法師、凱斯特的店和副隊長克朗奇。', `MaleText_loc7`='¡Si has estado jugando con aceite, evita toda fuente de chispas o llamas como velas, encendedores, magos, la tienda de Kester y al ayudante de alguacil Torpolatón!' WHERE `ID`=48720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작업 중엔 항상 머리 보호구를 착용하십시오! 달라 아가씨가 언제 얼굴에 주먹을 날릴지 모르니까요!', `MaleText_loc4`='工作时一定要戴上护头设备！没有人知道达尔拉小姐什么时候会给你的脑袋来一下！', `MaleText_loc5`='工作中記得要一直戴著頭盔!你不知道達爾拉小姐何時會冒出來敲你的頭!', `MaleText_loc7`='¡Mientras estés trabajando lleva siempre protección en la cabeza! ¡Nunca sabes cuándo a la señorita Darla le dará por pegarte un cachete en la cara!' WHERE `ID`=48721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부관 클렁키는 우리 친구들이 모두 안전하고 즐거운 시간을 보내길 바랍니다. 언젠가 계약서에 적힌 노예 할당량을 채울 거라 믿으면서요! 어이쿠야!', `MaleText_loc4`='克朗奇警官希望能确保部下的安全和心情愉悦，他以为这样就能让他的部下按照合同的规定，对他唯命是从了！天哪！', `MaleText_loc5`='副隊長克朗奇要他所有的手下都安全，並擁有一段好時光，只要你能完成合約規定的勞役配額就行!天啊!', `MaleText_loc7`='¡El ayudante de alguacil Torpolatón quiere que todos ustedes, vaqueros, estén a salvo y pasen y un buen rato, siempre y cuando cumplan con su cuota de servidumbre estipulada por contrato! ¡Vaya!' WHERE `ID`=48722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피로가 몰려올 때는 산업 재해가 일어나기 쉽습니다, 친구! 교대 전에 최소 두 시간은 쉬세요!', `MaleText_loc4`='当你极度困乏的时候，工作就很容易出纰漏，朋友！换班时务必要保证至少两小时睡眠啊！', `MaleText_loc5`='當你累到一個不行，就很容易在工作上出錯，伙計!盡量在換班期間至少休息兩個小時!', `MaleText_loc7`='¡Cuando estás absolutamente cansado, es fácil fastidiarla en el trabajo, colega! ¡Asegúrate de descansar al menos dos horas entre turno y turno!' WHERE `ID`=48723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름 유출! 기름 유출! 누가 전원을 조작했나 봐요!', `MaleText_loc4`='漏油了！漏油了！有人把开关切了！', `MaleText_loc5`='漏油了!漏油了啊!有人動到開關了!', `MaleText_loc7`='¡Fuga de combustible! ¡FUGA DE COMBUSTIBLE! ¡Que alguien tire del botón!' WHERE `ID`=48724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 못 지나간다!', `MaleText_loc4`='谁也别想过去！', `MaleText_loc5`='不准通過!', `MaleText_loc7`='¡Nadie pasa!' WHERE `ID`=48725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 구해줘서 고마워! 하지만 펄리에겐 절대 말하지 마. 알겠지? 내가 직접 부수고 나왔다고 했거든!', `MaleText_loc4`='谢谢你救了我！不过能不能别告诉费尔莉？我说是我自己逃出来的！', `MaleText_loc5`='謝謝你救了我!不要告訴費爾利，好嗎?我說是我自己一個人搞定的!', `MaleText_loc7`='¡Gracias por salvarme! Pero no se lo cuentes a Ferli, ¿vale? ¡Le he dicho que salí por mí mismo!' WHERE `ID`=48726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제임스 할로우 님이 비용을 지불하신 걸로 압니다. 갈퀴가지 숲까지 날아가고 싶습니다.', `MaleText_loc4`='我已得到詹姆斯·哈劳的允许，要取得前往刺枝林地的坐骑。', `MaleText_loc5`='詹姆士·哈洛招待我免費前往刺枝林地。', `MaleText_loc7`='Tengo que viajar a Claro Ramaespolón por cortesía de James Hallow.', `FemaleText_loc1`='제임스 할로우 님이 비용을 지불하셨을 거예요. 갈퀴가지 숲까지 날아가고 싶어요.', `FemaleText_loc4`='我已得到詹姆斯·哈劳的允许，要取得前往刺枝林地的坐骑。', `FemaleText_loc5`='詹姆士·哈洛招待我免費前往刺枝林地。', `FemaleText_loc7`='Tengo que viajar a Claro Ramaespolón por cortesía de James Hallow.' WHERE `ID`=48727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮추고, 당신의 체취도 숨기시오.', `MaleText_loc4`='小点儿声，动作轻些。', `MaleText_loc5`='保持安靜，並讓你的氣味飄往下風處。', `MaleText_loc7`='Mantén bajo el tono de voz y tu olor en contra del viento.' WHERE `ID`=48728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 중 일부는 엘룬의 낫이 이 땅을 지나갔을 때부터 여기 살았소. 하지만 대부분은 길니아스의 몰락 때 고통받게 된 이들이지.$B$B우리는 자연의 길을 배우고 그 균형을 유지하기 위해 이 숲에 정착했소. 우리 저주받은 자들도 새롭게 살아가는 방법을 발견한 거요.', `FemaleText_loc4`='自从月神的镰刀第一次来到这里后，我们之中很少的一部分人住到了这个地方。他们大都承受了吉尔尼斯沉沦的劫难。$B$B我们一直居住在这片森林中，学习自然之道，并致力于维持它的平衡。在这片被诅咒的土地上，我们被诅咒的族人已经找到了一条新的人生之路。', `FemaleText_loc5`='我們當中的某些人自從伊露恩的鐮刀穿過之後就一直住在這片土地上。大部分的人都經歷了吉爾尼斯的陷落。$B$B我們在這片森林中定居下來，並學習自然之道，以及維持平衡的方式。在這個受詛咒的地方，我們這些受詛咒的人們找到了新的生活方式。', `FemaleText_loc7`='Algunos de nosotros hemos vivido en esta tierra desde que la Guadaña de Elune pasó por aquí por primera vez. La mayoría sufrimos por la caída de Gilneas.$B$BNos hemos instalado en este bosque para aprender las bondades de la naturaleza y mantener su equilibrio. En esta tierra maldita, nuestro pueblo maldito ha encontrado una nueva vida.' WHERE `ID`=48729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 방식대로 하자면 너흰 벌써 죽었을 거다. 역겨운 족속들.', `MaleText_loc4`='要是照我的意思，你早就死了。你这种家伙实在让我厌恶。', `MaleText_loc5`='如果是我作主，你早就死了。你們這些傢伙讓我覺得噁心。', `MaleText_loc7`='Si me hubiera salido con la mía, hace tiempo que estarías muerto. Tu especie me repugna.' WHERE `ID`=48730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 모조리 죽여 그 비참한 삶을 끝내주자고 고드프리 경을 설득했다만, 계속해서 안 된다고만 하더군. 그 말인즉슨, 더 끔찍한 고통이 너희를 기다리고 있다는 뜻이지!', `MaleText_loc4`='我一直在试图说服高弗雷，把你们彻底消灭，以结束你们的痛苦。但他总是拒绝我。那你们就继续受苦吧！', `MaleText_loc5`='我試圖說服高佛雷直接殺光你們來終結你們的痛苦，但是他一直阻止我。那就讓你們這些傢伙受更多的痛苦和折磨吧!', `MaleText_loc7`='Intento convencer a Godfrey de que los mate a todos y termine así con su miseria, pero él insiste en negarse. ¡Entonces recibirán más dolor y sufrimiento!' WHERE `ID`=48731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역겨운 자식.', `MaleText_loc4`='混蛋。', `MaleText_loc5`='畜生。', `MaleText_loc7`='Bastardo.' WHERE `ID`=48732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역자로 불명예스럽게 사느니 이 감옥에서 썩겠다.', `MaleText_loc4`='就算是烂在这座牢房里，也比作为耻辱的叛徒活下去更好。', `MaleText_loc5`='我寧可在這個牢籠裡面爛掉，也不願意身為可恥的叛徒活下去。', `MaleText_loc7`='Prefiero pudrirme en esta celda antes que vivir como un traidor sin honor.' WHERE `ID`=48733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 형제와 자매들이여, 오그리마가 공격받고 있도다! 무기를 들고 일어나 우리의 수도를 수호하라! 저 침략자들에 대항하는 전쟁을 벌일 수 없다면, 우리 도시를 강화할 방벽을 세우는 일을 도우라! 록타르 오가르!', `MaleText_loc4`='部落的兄弟姐妹们，奥格瑞玛正受到攻击！拿起你们的武器，保卫我们的首都！不能与入侵者正面作战的人，就来修筑工事，加固我们的城防！LOK''TAR OGAR！', `MaleText_loc5`='部落的兄弟姊妹們，奧格瑪受到攻擊了!舉起你們的武器並保衛你們的首都!如果你們無法跟入侵者抗衡，那就幫忙放置路障來強化我們城市的防禦!不勝即亡!', `MaleText_loc7`='¡Hermanos y hermanas de la Horda, están atacando Orgrimmar! ¡Tomad las armas y defended la capital! Si no podéis luchar contra los intrusos, entonces ayudad a colocar barricadas para fortificar nuestra ciudad! ¡LOK''TAR OGAR!' WHERE `ID`=48734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우!', `FemaleText_loc4`='喔！', `FemaleText_loc5`='噢嗚!', `FemaleText_loc7`='¡Woo!' WHERE `ID`=48735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님? 여기서 뭐 하시는 거죠? 그리고 당신 뒤에는 키건 파이어비어드인가요?', `FemaleText_loc4`='$n？你在这里干什么？你在听从科甘·焰须的命令？', `FemaleText_loc5`='$n?你在這裡幹嘛?你後面的那個人是基岡·火鬍嗎?', `FemaleText_loc7`='¿$n? ¿Qué haces aquí? Y ese que está detrás de ti, ¿no es Keegan Barbafuego?' WHERE `ID`=48736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 즐거운 시간 보내셨겠군요. 그렇죠?', `FemaleText_loc4`='在享受美好时光吗？', `FemaleText_loc5`='你倒是很慢條斯理的，對吧?', `FemaleText_loc7`='Te has tomado tu tiempo, ¿eh?' WHERE `ID`=48737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 더러운 손을 가만두질 못하더라고요. 그래서 좀 손봐 줬죠. 그럼 가지요. 여기서 볼일은 끝났어요.', `FemaleText_loc4`='他们有些不安分，所以我要处理一下。好了，我已经忙完了。', `FemaleText_loc5`='是啊，他們開始不安份，所以我得花點時間解決這個問題。走吧，我這裡沒什麼事情了。', `FemaleText_loc7`='Sí, la cosa se estaba poniendo peliaguda, así que me he ocupado de ellos. Vamos, aquí ya he terminado.' WHERE `ID`=48738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다! 당신을 구하러 왔습니다!', `MaleText_loc4`='是的！我们是来救你的！', `MaleText_loc5`='沒錯!我們來這裡救你了!', `MaleText_loc7`='¡Sí! ¡Hemos venido a rescatarte!' WHERE `ID`=48739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이... 오우거를 처치했군요!', `MaleText_loc4`='食人魔——消灭他们！', `MaleText_loc5`='那些巨魔...你殺死他們了!', `MaleText_loc7`='¡Los ogros! ¡Los has matado!' WHERE `ID`=48740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보셨습니까, $n 님? 세상에 저런 여자가 또 있을까요?!', `MaleText_loc4`='你看见了吗，$n？竟有这样的女人！', `MaleText_loc5`='你看到了嗎，$n?真是令人印象深刻的女人!', `MaleText_loc7`='¿Ves esto, $n? ¡Qué mujer!' WHERE `ID`=48741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 망할 오크들이 붉은마루를 다시 넘보지 못하게 할 겁니다!', `MaleText_loc4`='绝不让那些该死的兽人再入侵赤脊山！', `MaleText_loc5`='我不會再讓那些該死的獸人入侵赤脊山!', `MaleText_loc7`='¡No permitiré que esos malditos orcos invadan Crestagrana de nuevo!' WHERE `ID`=48742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 게 가망 없는 시도 같이 느껴집니다. 이번 계획에 많은 게 걸렸습니다. 붉은마루의 자유를 위해서 말입니다.', `MaleText_loc4`='这真是孤注一掷。我们把很多赌注都押在这个计划上了。赤脊山的自由就是其中之一。', `MaleText_loc5`='這整個感覺很遙不可及。這個計畫還有不少風險。像是赤脊山的自由就是其中之一。', `MaleText_loc7`='Me parece que es bastante arriesgado. Hay mucho en juego en este plan. Para empezar, la libertad de Crestagrana.' WHERE `ID`=48743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 고개 숙여, $n!', `MaleText_loc4`='停！下来，$n！', `MaleText_loc5`='停止!下來，$n!', `MaleText_loc7`='¡ALTO! ¡AL SUELO, $n!' WHERE `ID`=48744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게! 반다르, 발린다, 붉은송곳니도 근처에 있으니까.', `MaleText_loc4`='小心！范达尔、巴琳达和血牙也在那里。', `MaleText_loc5`='小心!范達爾、貝琳達和血牙也都在那裡。', `MaleText_loc7`='¡CUIDADO! Vanndar, Balinda y Colmillo de Sangre también están aquí.' WHERE `ID`=48745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끌잡이 거점에 왔군요. 쓸모 있는 이가 되도록 최선을 다하세요.', `MaleText_loc4`='你已到达凿握据点，$g小伙子:小姑娘;。最好能发挥你的价值。', `MaleText_loc5`='你抵達鑿柄了，$g小伙子:小姑娘;。做點有用的事情吧。', `MaleText_loc7`='Has llegado a Cincelada, $gmuchacho:muchacha;. Será mejor que hagas algo útil.' WHERE `ID`=48746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저길 보게, 지도가 펼쳐진 탁자 근처 말이야! 스톰파이크 전투모병관이 얼라이언스 전투 계획서를 가지고 있어!', `MaleText_loc4`='看那边，地图桌附近！联盟进攻计划在雷矛战斗大师手里！', `MaleText_loc5`='看那裡，靠近地圖桌那裡!雷矛戰鬥大師有聯盟的戰鬥計畫!', `MaleText_loc7`='¡Mira ahí, cerca de la mesa del mapa! ¡El maestro de batalla Pico Tormenta tiene los planes de batalla de la Alianza!' WHERE `ID`=48747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사에 우호적인 고블린이 되셔야 제가 타는 법을 가르쳐 드릴 수 있어요.', `MaleText_loc4`='你必须先得到锈水财阀地精的友谊，我才会教你骑术。', `MaleText_loc5`='在我教你騎術之前，你必須與污水企業聯合的哥布林達到友好的聲望才行。', `MaleText_loc7`='Es necesario que los goblins del Cártel Pantoque te consideren $gamistoso:amistosa; para que pueda enseñarte a montar.', `FemaleText_loc1`='빌지워터 무역회사에 우호적인 고블린이 되셔야 제가 타는 법을 가르쳐 드릴 수 있어요, 아가씨.', `FemaleText_loc4`='你必须先得到锈水财阀地精的友谊，我才会教你骑术。', `FemaleText_loc5`='在我教你騎術之前，你必須與污水企業聯合的哥布林達到友好的聲望才行。', `FemaleText_loc7`='Es necesario que los goblins del Cártel Pantoque te consideren $gamistoso:amistosa; para que pueda enseñarte a montar.' WHERE `ID`=48748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사에 확고한 고블린이 되셔야 제가 타는 법을 가르쳐 드릴 수 있어요.', `MaleText_loc4`='你必须先得到锈水财阀地精的承认，我才会教你骑术。', `MaleText_loc5`='在我教你騎術之前，你必須與污水企業聯合的哥布林達到崇拜的聲望才行。', `MaleText_loc7`='Es necesario que los goblins del Cártel Pantoque te consideren $gun exaltado:una exaltada; para que pueda enseñarte a montar.', `FemaleText_loc1`='빌지워터 무역회사에 확고한 고블린이 되셔야 제가 타는 법을 가르쳐 드릴 수 있어요, 아가씨.', `FemaleText_loc4`='你必须先得到锈水财阀地精的承认，我才会教你骑术。', `FemaleText_loc5`='在我教你騎術之前，你必須與污水企業聯合的哥布林達到崇拜的聲望才行。', `FemaleText_loc7`='Es necesario que los goblins del Cártel Pantoque te consideren $gun exaltado:una exaltada; para que pueda enseñarte a montar.' WHERE `ID`=48749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈 준비가 되셨나요?', `MaleText_loc4`='准备好进行骑乘了？', `MaleText_loc5`='你準備好上路了嗎?', `MaleText_loc7`='¿Estás $gpreparado:preparada; para montar?', `FemaleText_loc1`='탈 준비가 되셨나요?', `FemaleText_loc4`='准备好进行骑乘了，宝贝？', `FemaleText_loc5`='你準備好上路了嗎?', `FemaleText_loc7`='¿Estás $gpreparado:preparada; para montar?' WHERE `ID`=48750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 위장복이 벗겨졌습니다!', `MaleText_loc4`='你的黑石伪装掉了！', `MaleText_loc5`='你的黑石偽裝脫落了!', `MaleText_loc7`='¡Has perdido el disfraz de Roca Negra!', `FemaleText_loc1`='검은바위 위장복이 벗겨졌습니다!', `FemaleText_loc4`='你的黑石伪装掉了！', `FemaleText_loc5`='你的黑石偽裝脫落了!', `FemaleText_loc7`='¡Has perdido el disfraz de Roca Negra!' WHERE `ID`=48751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내게 계획이 있네.', `MaleText_loc4`='我……我有自己的计划。', `MaleText_loc5`='我...我有自己的計畫。', `MaleText_loc7`='Tengo un... plan.' WHERE `ID`=48752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 탁자 근처의 경비대원을 처치하고 나머지 세 명을 유인하겠네.', `MaleText_loc4`='我会干掉桌旁的卫兵，吸引那三个家伙的注意力。', `MaleText_loc5`='我會殺掉桌子旁的警衛，然後我會吸引那三個傢伙的注意力。', `MaleText_loc7`='Mataré al guardia de la mesa y luego llamaré la atención del trío.' WHERE `ID`=48753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 정신이 내게 팔려 있을 때, 자네가 경비대원의 시체에서 전투 계획서를 빼내게. 자네가 계획서를 집는 걸 보는 즉시 카샤를 불러내서 태워줄 테니.', `MaleText_loc4`='我来吸引他们的注意力，你去守卫的尸体上找计划书。只要你一拿到计划书，我就会叫卡莎来接你离开。', `MaleText_loc5`='等我吸引了他們的注意力，你就從警衛的屍體上拿走計畫。我一看到你拿到計畫，我就會叫卡沙接應你。', `MaleText_loc7`='Mientras les distraigo, tú recupera los planos del cadáver del guardia. Llamaré a Kasha para que te recoja tan pronto vea que tienes los planos.' WHERE `ID`=48754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 걱정하지 말게, $n. 나... 오르쿠스는... 괜찮을 거야.', `MaleText_loc4`='不要担心奥尔库斯，$n。我……我会好起来的。', `MaleText_loc5`='不用擔心歐庫斯，$n。我...我會沒事的。', `MaleText_loc7`='No te preocupes por Orkus, $n. Yo... estaré bien.' WHERE `ID`=48755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위 트로그... 이곳의 기생충 같은 놈들이지.', `MaleText_loc4`='石头穴居人……深渊的害虫。', `MaleText_loc5`='岩石穴居怪...地底的毒物。', `MaleText_loc7`='Troggs de piedra... las alimañas de las profundidades.' WHERE `ID`=48756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 말하게. 바로 시작할 테니!|Tinterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc4`='准备好就来告诉我，我们即刻出发！|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc5`='等你準備好就告訴我，我們就出發!|TInterface\\GossipFrame\\GOSSIPGOSSIPICON.blp:32|t', `MaleText_loc7`='¡Avísame cuando estés $glisto:lista; y empezaremos!|TInterface\GossipFrame\GOSSIPGOSSIPICON.blp:32|t' WHERE `ID`=48757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐나? 어서 움직이게, $n. 놈들을 얼마나 묶어둘 수 있을지 모르겠어! 계획서를 손에 넣고 어서 떠나!', `MaleText_loc4`='准备好了么？你必须马上行动，$n。我不知道还能挡住他们多久！拿上计划，快走！', `MaleText_loc5`='你準備好了嗎?你必須趕快行動，$n。我不知道我還能抵擋他們多久!取得計畫然後離開!', `MaleText_loc7`='¿Vamos allá? Tendrás que actuar rápido, $n. ¡No sé cuánto tiempo podré retenerlos! ¡Consigue los planos y sal de aquí!' WHERE `ID`=48758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 오르쿠스. 시작합시다!', `MaleText_loc4`='我准备好了，奥尔库斯。让我们开始吧！', `MaleText_loc5`='我準備好了，歐庫斯。咱們動手吧!', `MaleText_loc7`='Estoy listo, Orkus. ¡Hagámoslo!', `FemaleText_loc1`='준비됐어요, 오르쿠스. 시작합시다!', `FemaleText_loc4`='我准备好了，奥尔库斯。让我们开始吧！', `FemaleText_loc5`='我準備好了，歐庫斯。咱們動手吧!', `FemaleText_loc7`='Estoy lista, Orkus. ¡Hagámoslo!' WHERE `ID`=48759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구. 자네하고 거래를 할 수 있었으면 좋겠어. 정말로 말이야. 하지만 먼저 자네가 빌지워터 무역회사와 우호적인 관계가 되어야 할 거야.', `MaleText_loc4`='我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的友谊。', `MaleText_loc5`='我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和污水企業聯合達到友好的聲望才行。', `MaleText_loc7`='Desearía poder hacer un trato, camarada, de verdad, pero primero es necesario que en el Cártel Pantoque te consideren $gamistoso:amistosa;.', `FemaleText_loc1`='이봐, 친구. 자네하고 거래를 할 수 있었으면 좋겠어. 정말로 말이야. 하지만 먼저 자네가 빌지워터 무역회사와 우호적인 관계가 되어야 할 거야.', `FemaleText_loc4`='我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的友谊。', `FemaleText_loc5`='我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和污水企業聯合達到友好的聲望才行。', `FemaleText_loc7`='Desearía poder hacer un trato, camarada, de verdad, pero primero es necesario que en el Cártel Pantoque te consideren $gamistoso:amistosa;.' WHERE `ID`=48760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 위장복을 잃어버렸습니다, 대령님. 하나 더 얻을 수 있을까요?', `MaleText_loc4`='上校，我的黑石伪装丢了。能再给我一件么？', `MaleText_loc5`='我的黑石偽裝沒了，上校。我可以再要一個嗎?', `MaleText_loc7`='He perdido mi disfraz de Roca Negra, coronel. ¿Puedes darme otro?', `FemaleText_loc1`='검은바위 위장복을 잃어버렸습니다, 대령님. 하나 더 얻을 수 있을까요?', `FemaleText_loc4`='上校，我的黑石伪装丢了。能再给我一件么？', `FemaleText_loc5`='我的黑石偽裝沒了，上校。我可以再要一個嗎?', `FemaleText_loc7`='He perdido mi disfraz de Roca Negra, coronel. ¿Puedes darme otro?' WHERE `ID`=48761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구. 자네하고 거래를 할 수 있었으면 좋겠어. 정말로 말이야. 하지만 먼저 자네가 빌지워터 무역회사와 확고한 관계가 되어야 할 거야.', `MaleText_loc4`='我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的承认。', `MaleText_loc5`='我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和污水企業聯合達到崇拜的聲望才行。', `MaleText_loc7`='Desearía poder hacer un trato, camarada, de verdad, pero primero es necesario que en el Cártel Pantoque te consideren $gun exaltado:una exaltada;.', `FemaleText_loc1`='이봐, 친구. 자네하고 거래를 할 수 있었으면 좋겠어. 정말로 말이야. 하지만 먼저 자네가 빌지워터 무역회사와 확고한 관계가 되어야 할 거야.', `FemaleText_loc4`='我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的承认。', `FemaleText_loc5`='我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和污水企業聯合達到崇拜的聲望才行。', `FemaleText_loc7`='Desearía poder hacer un trato, camarada, de verdad, pero primero es necesario que en el Cártel Pantoque te consideren $gun exaltado:una exaltada;.' WHERE `ID`=48762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 나는 빌지워터 세발차 영업사원 칼 워서톤이야. 자네 맘에 쏙 드는 세발차를 한번 골라 보라고!$B$B돌풍을 일으키며 달리는 세발차... 목숨을 걸어야 할 만큼 위험하게 빠른 세발차... 자네가 자랑스러워할 수 있는 세발차를 말이야! 맘에 드는 세발차를 찾았으면 거래를 시작해보자고.', `MaleText_loc4`='呦！我是锈水三轮摩托经销商卡尔·万金。$B$B欢迎随便看看。选出您最中意的三轮摩托！$B$B一辆无比拉风的三轮摩托……一辆充满危险气息而又无惧死亡的三轮摩托……一辆为您带来荣光的三轮摩托！$B$B选好就来找我，我们来谈谈价格。', `MaleText_loc5`='嗨!我是考爾·沃瑟頓，污水機動車。$B$B別客氣，到處看看吧。選出你真正想要的機動車!$B$B一輛騎起來很爽的機動車...一輛危險而在生死邊緣遊轉的機動車...一輛能讓你感到驕傲的機動車!$B$B等你決定了，跟我說一聲，我們可以馬上成交。', `MaleText_loc7`='¡Eh! Soy Kall Valemil, de Triciclos Pantoque.$B$BAdelante, echa un vistazo a la mercancía. ¡Elige el triciclo que desees de VERDAD!$B$B¡Un triciclo que sea la caña de montar... un triciclo que sea peligroso y que desafíe a la muerte... un triciclo del que puedas estar $gORGULLOSO:ORGULLOSA;!$B$BAvísame cuando lo veas y llegaremos a un trato.', `FemaleText_loc1`='이봐! 나는 빌지워터 세발차 영업사원 칼 워서톤이야. 자네 맘에 쏙 드는 세발차를 한번 골라 보라고!$B$B돌풍을 일으키며 달리는 세발차... 목숨을 걸어야 할 만큼 위험하게 빠른 세발차... 자네가 자랑스러워할 수 있는 세발차를 말이야! 맘에 드는 세발차를 찾았으면 거래를 시작해보자고.', `FemaleText_loc4`='呦！我是锈水三轮摩托经销商卡尔·万金。$B$B欢迎随便看看。选出您最中意的三轮摩托！$B$B一辆无比拉风的三轮摩托……一辆充满危险气息而又无惧死亡的三轮摩托……一辆为您带来荣光的三轮摩托！$B$B选好就来找我，我们来谈谈价格。', `FemaleText_loc5`='嗨!我是考爾·沃瑟頓，污水機動車。$B$B別客氣，到處看看吧。選出你真正想要的機動車!$B$B一輛騎起來很爽的機動車...一輛危險而在生死邊緣遊轉的機動車...一輛能讓你感到驕傲的機動車!$B$B等你決定了，跟我說一聲，我們可以馬上成交。', `FemaleText_loc7`='¡Eh! Soy Kall Valemil, de Triciclos Pantoque.$B$BAdelante, echa un vistazo a la mercancía. ¡Elige el triciclo que desees de VERDAD!$B$B¡Un triciclo que sea la caña de montar... un triciclo que sea peligroso y que desafíe a la muerte... un triciclo del que puedas estar $gORGULLOSO:ORGULLOSA;!$B$BAvísame cuando lo veas y llegaremos a un trato.' WHERE `ID`=48763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르가 어떤 놈을 요리해줄까?!', `MaleText_loc4`='你能闻到那煮的是什么吗？！', `MaleText_loc5`='你聞到那些部落在煮的東西了嗎?!', `MaleText_loc7`='¡¿HUELES QUÉ LOK''TAR ESTÁ COCINANDO?!' WHERE `ID`=48764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 계획서를 가지고 떠나!', `MaleText_loc4`='拿起计划赶快走！', `MaleText_loc5`='拿到計畫然後快走!!', `MaleText_loc7`='¡RECUPERA LOS PLANOS Y VAMOS!' WHERE `ID`=48765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 따스하게 깜박이며, 감사의 뜻으로 $n에게 자신의 힘을 일부 부여합니다.', `MaleText_loc4`='%s温暖地闪动着，将自身能量的一部分赠与$n，以表谢意。', `MaleText_loc5`='%s溫暖地閃爍著，把自己力量的一部分灌注給$n以表示感謝。', `MaleText_loc7`='El %s parpadea calurosamente y ofrece a $n una porción de su poder como agradecimiento.' WHERE `ID`=48766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 정말 화약통 같은 여잡니다. 파이어비어드 가문에 딱 어울려요! 썬더마 드워프들이 이 결합을 찬성할까요?', `MaleText_loc4`='她就像火药桶一样一碰就炸！所以她一定能生出最优秀的焰须战士来！你认为桑德玛尔会答应吗？', `MaleText_loc5`='她是真正的火藥桶。她會是很棒的火鬍成員!你認為桑德瑪那群傢伙會放人嗎?', `MaleText_loc7`='Es como un barril de pólvora. ¡Será una Barbafuego de primera! ¿Crees que los Bramal lo aceptarán?' WHERE `ID`=48767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"대마법사 프랫 님"이라고요? 격식 따윈 집어치우십시오. 몸과 함께 허영심도 죽은 지 오래입니다. 대충 "찰스"라고 부르든가 하십시오.', `MaleText_loc4`='“大法师普拉特”？去它浮云般的虚名，我的虚荣心已经随我一通消亡了。叫“查尔斯”，或是简单地称作“查斯”就行了，谢谢。', `MaleText_loc5`='大法師普拉特?讓正式的禮節見鬼去吧，我的虛榮心已經隨著我其他的部份死去了。叫我查理斯或查斯都行，謝謝。', `MaleText_loc7`='¿"Archimago Pratt"? Ignoremos las formalidades. Mi vanidad murió con el resto de mi cuerpo. "Charles" e incluso más sencillo, "Chaz" servirá, gracias.' WHERE `ID`=48768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카샤, $P|1을;를; 여기서 데리고 나가!', `MaleText_loc4`='卡莎，带$P离开这里！', `MaleText_loc5`='卡沙，把$P帶離這裡!', `MaleText_loc7`='¡KASHA, SACA A $P DE AQUÍ!' WHERE `ID`=48769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 움직이시오. 여긴 위험한 것이 많으니까.', `MaleText_loc4`='我们得继续前进。这儿充满危险。', `MaleText_loc5`='咱們繼續走吧。在這裡有不小的風險。', `MaleText_loc7`='Sigamos en marcha. Nos jugamos mucho aquí.' WHERE `ID`=48770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 신경 쓰지 마, 카샤! 어서 가!', `MaleText_loc4`='别管我，卡莎！快走！', `MaleText_loc5`='不用管我，卡沙!快走!', `MaleText_loc7`='¡OLVÍDATE DE MÍ, KASHA! ¡VETE!' WHERE `ID`=48771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카... 카샤... 날 데리러 와줬구나...', `MaleText_loc4`='卡……卡莎……你……为了我回来……', `MaleText_loc5`='卡沙...你為了我...而回來...', `MaleText_loc7`='K... Kasha... has... vuelto a por mí...' WHERE `ID`=48772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내 평생 자네 같은 친구는 없었네. 자네는 날 구해줬어, $p. 그것도 여러 번이나... 이... 이기적으로 들릴 순 있겠지만, 자네에게 꼭 부탁하고 싶은 게 있네.', `MaleText_loc4`='我……我从没有见过像你这样的人。你不止一次地救了我，$P。我……我知道这样做很自私，但我还有事求你帮我去做。', `MaleText_loc5`='我...我從來沒認識過像你這樣的人。你救了我，$p。不只一次。我...我知道這很自私，但是我有個請求。', `MaleText_loc7`='Nunca... he conocido a nadie como tú, $p. Me has salvado. Yo... ya sé que es egoísta pero tengo que pedirte algo.' WHERE `ID`=48773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한 곳으로 갈 수 있게... 도와주게...', `MaleText_loc4`='安全的地方……', `MaleText_loc5`='某個安全的地方...', `MaleText_loc7`='Algún lugar seguro...' WHERE `ID`=48774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성소 안에 있는 맥그래프 부자와 이야기하는 걸 잊지 마세요. 그들이 의식을 주관할 거예요.', `FemaleText_loc4`='一定要迈格拉夫一家人谈谈。他们就在庇护所里。他们会在那里安排这场仪式的。', `FemaleText_loc5`='記得跟聖堂裡面那些姓麥葛拉夫的人說說話。他們正在協調儀式的事情。', `FemaleText_loc7`='Asegúrate de hablar con los MacGraff dentro del santuario. Estarán orquestando las ceremonias.' WHERE `ID`=48775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 절 구하러 온 건가요? 그럼 어서 가자고요!', `MaleText_loc4`='你真的是来救我的？太棒了，我们走！', `MaleText_loc5`='你準備好要救我了嗎?太好了，咱們出發吧!', `MaleText_loc7`='¿De verdad has venido a rescatarme? ¡Pues vamos!', `FemaleText_loc1`='정말 절 구하러 온 건가요? 그럼 어서 가자고요!', `FemaleText_loc4`='你真的是来救我的？太棒了，我们走！', `FemaleText_loc5`='你準備好要救我了嗎?太好了，咱們出發吧!', `FemaleText_loc7`='¿De verdad has venido a rescatarme? ¡Pues vamos!' WHERE `ID`=48776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저 혼자 말을 타고 가면 될 것 같아요. 고마워요!', `MaleText_loc4`='我想，我能骑这匹马走完剩下的路。谢谢！', `MaleText_loc5`='我想我可以騎那匹馬完成剩下的路程。謝謝你!', `MaleText_loc7`='Creo que puedo utilizar ese caballo para el resto del camino. ¡Gracias!', `FemaleText_loc1`='이제 저 혼자 말을 타고 가면 될 것 같아요. 고마워요!', `FemaleText_loc4`='我想，我能骑这匹马走完剩下的路。谢谢！', `FemaleText_loc5`='我想我可以騎那匹馬完成剩下的路程。謝謝你!', `FemaleText_loc7`='Creo que puedo utilizar ese caballo para el resto del camino. ¡Gracias!' WHERE `ID`=48777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 넌 오르쿠스가 만난 친구 중 제일 좋은 녀석이야. *기침하는 오르쿠스*', `MaleText_loc4`='你是奥尔库斯所结识过最好的朋友，$P。*奥尔库斯咳了起来*', `MaleText_loc5`='你是歐庫斯有生以來最好的朋友，$p。*歐庫斯咳了幾聲*', `MaleText_loc7`='Tú eres el mejor amigo que Orkus ha tenido nunca, $p. *Orkus tose*' WHERE `ID`=48778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카샤의 뒤를 부탁하네. 이 녀석이 추운 곳에서 살 수 있게 해주게.', `MaleText_loc4`='请照顾卡莎。一定要让她生活在够冷的地方。', `MaleText_loc5`='請照顧卡沙。讓她找個寒冷的地方定居。', `MaleText_loc7`='Por favor, cuida de Kasha. Asegúrate de que encuentre un lugar frío donde vivir.' WHERE `ID`=48779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플레임스타 님! 제가 이 용들을 자기들 종족에게 돌려보낼 수 있습니다. 제가 이들을 돌보지요.', `MaleText_loc4`='焰星！我可以送这些龙回归它们的族群。让我来照顾他们。', `MaleText_loc5`='燎星!我可以把這些龍送回去找牠們的同伴。讓我接手吧。', `MaleText_loc7`='¡Llamaestrella! Yo puedo devolver a esos dragones con los suyos. Deja que cuide de ellos.' WHERE `ID`=48780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하는 대로 하게. 저 용들이 다치지만 않으면 되네.', `MaleText_loc4`='如你所愿。只要确保它们不受到伤害。', `MaleText_loc5`='如你所願。小心別讓牠們受到傷害就好。', `MaleText_loc7`='Como desees. Asegúrate de que no reciben ningún daño.' WHERE `ID`=48781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 위장복 잃어버리지 말게!', `MaleText_loc4`='不要忘记伪装！', `MaleText_loc5`='別忘了那個偽裝!', `MaleText_loc7`='¡No te olvides del disfraz!' WHERE `ID`=48782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 공모자가 자네 계획에 대한 정보를 내게 줬네. 전장에서 보지... 정령의 재로 칠하고 말이야.', `MaleText_loc4`='你的同谋者已经把你们的计划告诉了我。我们战场上见……涂满元素余烬的战场。', `MaleText_loc5`='你的共謀者已經告訴我你的計畫。我會在戰場上跟你相見...用元素的灰燼為塗料。', `MaleText_loc7`='Tu conspirador me ha informado de tu plan. Te veré en el campo de batalla... pintado con las cenizas de los elementales.' WHERE `ID`=48783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, 이리 와서 먹어라! 내가 아끼는 병사가 모두 충분히 먹을 만큼의 늑대 고기를 가져왔다!', `MaleText_loc4`='来，孩子，我们吃吧！我最喜欢的战士为大家带来了足够的狼肉！', `MaleText_loc5`='來吧孩子們，咱們開動吧!我最喜歡的士兵帶來了夠所有人吃的座狼肉!', `MaleText_loc7`='¡Venga, muchachos, comamos! ¡Mi soldado favorito ha traído huargo suficiente para todos!' WHERE `ID`=48784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 잠자는 이 임프 들을 저쪽에 그냥 놔두면 되겠지? 이것들이 정말... 임프인가? 이런!', `MaleText_loc4`='我猜，我只需要……把这些睡着的小鬼留在这里？这些……是小鬼吗？嘿！', `MaleText_loc5`='我想，我就把...那些沉睡中的小鬼留在這裡就好了?那些...是小鬼沒錯吧?嘎!', `MaleText_loc7`='Supongo que debería... dejar a los diablillos dormidos justo ahí, ¿no? ¿Pero son diablillos siquiera? ¡Gah!' WHERE `ID`=48785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알다시피 난 몇 분 후에 강력한 의식을 거행하는 데 이 수정구를 사용할 작정이다. 아무한테도 말하지 말라고... 난 지옥의 군주를 소환할 거다. 붉은마루는 검은바위에게 복종하게 될 거란 말이다!', `MaleText_loc4`='你知道，几分钟后，我就将用这个宝珠开始一场强大的仪式。别告诉任何人……我要召唤的是一位深渊领主。赤脊山将屈从于黑石部族的力量！', `MaleText_loc5`='你知道吧，過幾分鐘我就要用這顆球來進行一個強大的儀式。不要跟其他人說...我打算召喚一個深淵領主。赤脊山將會向黑石臣服!', `MaleText_loc7`='Sabes, en unos minutos voy a utilizar este orbe para realizar un poderoso ritual. No se lo digas a nadie, pero voy a invocar a un señor del foso. ¡Crestagrana se arrodillará ante los Roca Negra!' WHERE `ID`=48786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존스 박사님, 준비되면 출발하십시오!', `MaleText_loc4`='准备好了，琼斯博士！', `MaleText_loc5`='我準備好了，瓊斯博士!', `MaleText_loc7`='¡Listo cuando tú lo estés, doctor Jones!', `FemaleText_loc1`='존스 박사님, 준비되면 출발하세요!', `FemaleText_loc4`='准备好了，琼斯博士！', `FemaleText_loc5`='我準備好了，瓊斯博士!', `FemaleText_loc7`='¡Lista cuando tú lo estés, doctor Jones!' WHERE `ID`=48787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 살아남지 못할 거다, 오크 녀석! 네가 록타르를 외치는 것도 이번이 마지막이다!', `MaleText_loc4`='这次无路可逃了，兽人！你已经喊完了最后一句兽人口号！', `MaleText_loc5`='這次你逃不掉了，獸人!你再喊「為了部落」也沒用了!', `MaleText_loc7`='¡Esta vez no podrás escaparte, orco! ¡Has cantado tu último lok''tar!' WHERE `ID`=48788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋소, $n. 나를 따라오시오!', `MaleText_loc4`='$n，跟着我！', `MaleText_loc5`='好吧，$n。跟著我!', `MaleText_loc7`='Está bien, $n. ¡Sígueme!' WHERE `ID`=48789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포에 설치되어 있던 덫이 폭발합니다!', `MaleText_loc4`='火炮与一个爆炸陷阱连在了一起！', `MaleText_loc5`='這個火砲上面搭了一個爆炸陷阱!', `MaleText_loc7`='¡Había una trampa explosiva instalada en el cañón!' WHERE `ID`=48790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 예감에 의하면...', `MaleText_loc4`='我的内心告诉我……', `MaleText_loc5`='我的直覺告訴我...', `MaleText_loc7`='Mi instinto me dice...' WHERE `ID`=48791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 이쪽이오!', `MaleText_loc4`='……这边！', `MaleText_loc5`='...在這一邊!', `MaleText_loc7`='¡... que es por aquí!' WHERE `ID`=48792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 걸리지 않을 거요.', `MaleText_loc4`='应该很快就好。', `MaleText_loc5`='這只要一下子就好。', `MaleText_loc7`='Esto no debería llevarnos más de un momento.' WHERE `ID`=48793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='담즙로봇이 상황 종료 신호를 보내고는 완전히 정지합니다.', `MaleText_loc4`='胆汁喷洒机发出了肯定的信号，永久地关闭了。', `MaleText_loc5`='好膽800發出確認的信號，然後永遠地關機了。', `MaleText_loc7`='El Bilistrón hace señales afirmativas y se apaga de forma permanente.' WHERE `ID`=48794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암호 입력 완료. 장치를 활성화합니다.', `MaleText_loc4`='密码接受。系统激活。', `MaleText_loc5`='密碼正確。啟動機關。', `MaleText_loc7`='Códigos aceptados. Activando mecanismo.' WHERE `ID`=48795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅을 흐르는 열기에 타버려라!', `MaleText_loc4`='在火焰之地的流火中被烧毁吧！', `MaleText_loc5`='在火源之界的液態火焰中燃燒吧!', `MaleText_loc7`='¡Arde en el calor líquido de las Tierras de Fuego!' WHERE `ID`=48796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? 그 손에 든 건 뭐요?', `MaleText_loc4`='发生了什么事？你手里拿的是什么？', `MaleText_loc5`='發生什麼事了?你手裡拿了什麼東西?', `MaleText_loc7`='¿Qué ha ocurrido? ¿Qué es eso que tienes en las manos?' WHERE `ID`=48797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 얼라이언스 전투 계획서를 읽습니다.', `MaleText_loc4`='%s仔细查看联盟作战计划。', `MaleText_loc5`='%s閱讀了聯盟的戰鬥計畫。', `MaleText_loc7`='%s lee el plan de batalla de la Alianza.' WHERE `ID`=48798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그... 그가 이걸 얻기 위해 목숨을 바쳤다고?', `MaleText_loc4`='他……为了把这个送来而牺牲了？', `MaleText_loc5`='他...為了把這個送來這裡而死?', `MaleText_loc7`='¿Murió... para traer esto aquí?' WHERE `ID`=48799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 오르쿠스의 시신을 일으킵니다.', `MaleText_loc4`='%s举起奥尔库斯没有生命的躯体。', `MaleText_loc5`='%s把歐庫斯毫無生氣的身體抬了起來。', `MaleText_loc7`='%s levanta el cuerpo sin vida de Orkus.' WHERE `ID`=48800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르쿠스의 죽음을 슬퍼하지 마시오. 그는 호드의 영웅으로서, 긍지를 잃지 않고 영광스러운 죽음을 맞이했으니.', `MaleText_loc4`='不要为奥尔库斯哀伤。他带着荣誉与自豪……而死。他是部落的英雄。', `MaleText_loc5`='不要為歐庫斯感到哀傷。他的死亡充滿了榮譽...和驕傲。他是以部落英雄的身分而死。', `MaleText_loc7`='No llores por Orkus. Murió con honor... con orgullo. Murió siendo un héroe de la Horda.' WHERE `ID`=48801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로데론에서 칼림도어까지, 모두가 그의 이름을 칭송할 거요. 모두가 호드의 쓰러진 영웅을 기리며 영광의 노래를 부를 거요.', `MaleText_loc4`='从洛丹伦到卡利姆多，他们都将知道他的名字，唱起光荣的歌曲，颂扬这位牺牲的部落英雄。', `MaleText_loc5`='從羅德隆到卡林多，他們會知道他的名字，會唱頌榮耀之歌，讚美部落這位倒下的英雄。', `MaleText_loc7`='Su nombre será famoso desde Lordaeron hasta Kalimdor, y cantarán canciones en su honor que encumbrarán al caído campeón de la Horda.' WHERE `ID`=48802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 활약으로 수백 명, 아니 수천 명의 목숨을 구할 수 있었소. 당신도 호드의 진정한 영웅 대접을 받을 만하오, $n.', `MaleText_loc4`='要知道，你所做的一切将拯救数百——也许是数千条生命。你同时也是部落真正的大英雄，$n。', `MaleText_loc5`='知道你所做的會拯救上百條，甚至上千條生命。你也是部落真正的英雄，$n。', `MaleText_loc7`='Lo que habéis hecho salvará cientos, quizá miles de vidas. Tú también eres un verdadero héroe de la Horda, $n.' WHERE `ID`=48803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 정도면 오랜만에 쉽게 끝난 것 같군.', `MaleText_loc4`='嗯，改变进行得非常顺利。', `MaleText_loc5`='好吧，難得這次進行得很順利。', `MaleText_loc7`='Bueno, eso ha ido muy bien para variar.' WHERE `ID`=48804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 그럴 리가 없지. 당연히 이럴 줄 알았어야 하는데...', `MaleText_loc4`='太好便会有失真实。我本该知道的。', `MaleText_loc5`='好得讓人不敢置信。我早就該知道。', `MaleText_loc7`='Demasiado bueno para ser verdad. Tendría que habérmelo imaginado.' WHERE `ID`=48805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 어려운 방법을 택해야 할 것 같소. 갑시다!', `MaleText_loc4`='看来我们要费一番功夫才行。我们走！', `MaleText_loc5`='看來我們得用比較困難的方法來搞定了。咱們走吧!', `MaleText_loc7`='¡Al parecer tendremos que hacerlo por las malas! ¡Vamos!' WHERE `ID`=48806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 작동 실패. 내부 정보가 손상되었습니다.$b$b방어 장치를 구축합니다.', `MaleText_loc4`='系统宕机。发现内部数据破坏。$b$b构建防御机制。', `MaleText_loc5`='系統失敗。發現內部資料損毀。$b$b防禦機制架構中。', `MaleText_loc7`='Fallo de sistema. Detectada corrupción de datos internos.$b$bConstruyendo mecanismo de defensa.' WHERE `ID`=48807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 장치 구축 중.', `MaleText_loc4`='构建防御系统。', `MaleText_loc5`='防禦機制架構中。', `MaleText_loc7`='Construyendo mecanismo de defensa.' WHERE `ID`=48808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘도 내 분노로 타오른다!', `MaleText_loc4`='就连天空也要在我的怒火中燃烧！', `MaleText_loc5`='連天空都因我的憤怒燃燒!', `MaleText_loc7`='¡Incluso los cielos arden con mi furia!' WHERE `ID`=48809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 골짜기의 남동쪽 끝에 있는 큰 건물 꼭대기에 있습니다.', `MaleText_loc4`='他们就在这座山谷东南尽头那座高大的建筑物顶上。', `MaleText_loc5`='他們在谷的東南邊那棟很高的建築物頂樓。', `MaleText_loc7`='Eh''tan en lo alto del gran edificio en el extremo sureste del valle.', `FemaleText_loc1`='그들은 골짜기의 남동쪽 끝에 있는 큰 건물 꼭대기에 있습니다.', `FemaleText_loc4`='他们就在这座山谷东南尽头那座高大的建筑物顶上。', `FemaleText_loc5`='他們在谷的東南邊那棟很高的建築物頂樓。', `FemaleText_loc7`='Eh''tan en lo alto del gran edificio en el extremo sureste del valle.' WHERE `ID`=48810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문각인', `MaleText_loc4`='铭文', `MaleText_loc5`='銘文學', `MaleText_loc7`='Inscripción', `FemaleText_loc1`='주문각인', `FemaleText_loc4`='铭文', `FemaleText_loc5`='銘文學', `FemaleText_loc7`='Inscripción' WHERE `ID`=48811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_whirlwind.blp:20|t전투 절단기 5000이 |cFFFF0000|Hspell:88481|h[증속]|h|r을 활성화합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_whirlwind.blp:20|t死神5000型启动|cFFFF0000|Hspell:88481|h[超速]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_whirlwind.blp:20|t敵人收割者5000開始啟動|cFFFF0000|Hspell:88481|h[急速運轉]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_whirlwind.blp:20|t ¡Siegaenemigos 5000 comienza a activar |cFFFF0000|Hspell:88481|h[Ultravelocidad]|h|r!' WHERE `ID`=48812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시를 배우러 왔나? 아니면 낚시용품을 사러 온 건가?', `MaleText_loc4`='朋友，你是来学习钓鱼的？还是来买东西的？', `MaleText_loc5`='你來這裡學釣魚嗎，老兄?還是來買釣魚用品?', `MaleText_loc7`='¿Quieres aprender a peh''car, colega? ¿O quizá has veni''o a comprar material para haceh''lo?', `FemaleText_loc1`='낚시를 배우러 왔나? 아니면 낚시용품을 사러 온 건가?', `FemaleText_loc4`='朋友，你是来学习钓鱼的？还是来买东西的？', `FemaleText_loc5`='你來這裡學釣魚嗎，老兄?還是來買釣魚用品?', `FemaleText_loc7`='¿Quieres aprender a peh''car, colega? ¿O quizá has veni''o a comprar material para haceh''lo?' WHERE `ID`=48813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 수정을 처리하시오, $n! 그러면 작동을 멈출 거요!', `MaleText_loc4`='砸烂那些水晶，$n！这应该能让它关闭！', `MaleText_loc5`='擊碎那些水晶，$n!那樣應該可以使它停止!', `MaleText_loc7`='¡Destruye esos cristales, $n! ¡Eso debería apagarlo!' WHERE `ID`=48815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈들. 이 필멸의 세계에서 해는 이미 졌다. 혼돈이 다가온다. 종말을 받아들이고 편히 쉬어라.', `MaleText_loc4`='凡人世界的夕阳已经落幕。平静接受你的末日，暮光的时刻来临了！', `MaleText_loc5`='這個凡人的世界已夕陽西下，笨蛋。迎接你們的死亡吧，因為黃昏正要來臨!', `MaleText_loc7`='El sol se ha puesto en este mundo mortal. Acepten su final, ha llegado el crepúsculo.' WHERE `ID`=48816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워워! 사냥 시작이군!', `MaleText_loc4`='发现目标！狩猎开始！', `MaleText_loc5`='獵物出現!開始打獵嘍!', `MaleText_loc7`='¡A la carga! ¡Comienza la caza!' WHERE `ID`=48817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥이 너무 시시하군.', `MaleText_loc4`='这可不是运动，而是杀戮。', `MaleText_loc5`='那樣殺得太難看了。', `MaleText_loc7`='Esa muerte no ha supuesto ningún desafío.' WHERE `ID`=48818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 것.', `MaleText_loc4`='可怜的家伙。', `MaleText_loc5`='糟糕透頂。', `MaleText_loc7`='Patético.' WHERE `ID`=48819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 천것들에게 잡히다니, 내 꼴이 우스워졌군...', `MaleText_loc4`='竟然被低等平民杀掉了，真是滑稽……', `MaleText_loc5`='被低賤的平民殺死，真慘啊...', `MaleText_loc7`='Asesinado por plebeyos de baja estofa. Qué chistoso...' WHERE `ID`=48820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 이 저주받은 곳을 떠나라!', `MaleText_loc4`='立刻离开这个诅咒之地！', `MaleText_loc5`='立刻離開這個被詛咒的地方!', `MaleText_loc7`='¡Abandona inmediatamente este lugar maldito!' WHERE `ID`=48821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 속박이 풀렸습니다! 이제 억눌렸던 힘을 모두 사용할 수 있습니다.', `MaleText_loc4`='%s的束缚正在松开！全能量开启。', `MaleText_loc5`='%s的束縛被解開了!力量已達顛峰。', `MaleText_loc7`='¡Se han soltado las ataduras de %s! Poderes completos desbloqueados.' WHERE `ID`=48822;
