UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이바르 녀석, 자기 부하들이 참패하자 용병 무리를 보냈군. 상관없다. 너희의 여정은 고통 속에 끝날 것이다.', `MaleText_loc4`='伊瓦的部队遭受了惨败。所以他现在又派来了佣兵。没关系，你们就要在巨大的痛苦中彻底被毁灭了。', `MaleText_loc5`='伊瓦的手下失敗得很徹底，所以他改派傭兵來了。無所謂，你的旅途在此要痛苦地結束了。', `MaleText_loc7`='La manada de Ivar fracasó miserablemente, así que ahora envía mercenarios. No importa, tu viaje termina en agonía.' WHERE `ID`=48834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희도 망할 실바나스가 보낸 놈들이겠지? 상관없다. 너희의 여정은 고통 속에 끝날 것이다.', `MaleText_loc4`='那个该死的希尔瓦娜斯又派你来了？没关系，来迎接你痛苦的末日吧。', `MaleText_loc5`='你也是希瓦娜斯那個臭女人派來的，對吧?無所謂，你的旅途在此要痛苦地結束了。', `MaleText_loc7`='Esa maldita Sylvanas te envía, ¿verdad? No importa, tu viaje termina en agonía.' WHERE `ID`=48835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 잡으러 온 전문 암살자라는 것들이 이 정도 실력이라니. 우습지도 않군.', `MaleText_loc4`='这就是被派来杀我的刺客？真可笑。', `MaleText_loc5`='派來暗殺我的刺客只有這樣的水準?笑死人了。', `MaleText_loc7`='¿Esta es la calidad de los asesinos que han enviado a matarme? Me parto de risa.' WHERE `ID`=48836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 짓은 싫증도 안 난단 말이지.', `MaleText_loc4`='谋杀永远也不会过时。', `MaleText_loc5`='謀殺還真的是歷久彌新啊。', `MaleText_loc7`='El asesinato nunca pasa de moda.' WHERE `ID`=48837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨끗이 죽여 줘서 고맙군. 나는 너희에게 그리하지 않았을 텐데...', `MaleText_loc4`='感谢你让我死得这么痛快，要不是你，我永远也做不到……', `MaleText_loc5`='感謝你給我一個痛快。我自己就不會這樣做...', `MaleText_loc7`='Te agradezco que me hayas matado limpiamente. Yo no hubiera hecho lo mismo...' WHERE `ID`=48838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 잘 들으시오!$b$b저 수정을 처리하면 피조물의 움직임이 멈출 거요.', `MaleText_loc4`='听着！$b$b拿走那些水晶会让构造体失去能量。', `MaleText_loc5`='聽著!$B$B破壞那些水晶應該可以抽走那個傀儡的力量。', `MaleText_loc7`='¡Escucha!$b$bSi destruimos esos cristales, agotaremos al ensamblaje.' WHERE `ID`=48839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠와 그의 병사들에게 들키지 않고 성궤에 접근해야 하오.', `MaleText_loc4`='我们必须拿到那个箱子，同时又不能惊动司克诺兹和他的手下。', `MaleText_loc5`='我們必須在前往法櫃的同時不驚動舒諾茲和他的手下。', `MaleText_loc7`='Tenemos que llegar a la cofa sin poner sobre aviso a Schnotzz y a sus muchachos.' WHERE `ID`=48840;
