UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_key_12.blp:32|t화끈한 개조차를 타고 용병 노략꾼을 처치한 후 전리품을 챙겨야 합니다.', `MaleText_loc4`='使用你的改装跑车|TInterface\\Icons\\inv_misc_key_12.blp:32|t追上受雇的抢掠者，夺取他们偷走的物品。', `MaleText_loc5`='使用你的酷炫改裝車|TInterface\\Icons\\inv_misc_key_12.blp:32|t來輾過受雇的強奪者，並取得他們的財物。', `MaleText_loc7`='Utiliza tu bólido |TInterfaceIconsinv_misc_key_12.blp:32|t para ir hasta los despojadores contratados y hacerte con su botín.', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_key_12.blp:32|t화끈한 개조차를 타고 용병 노략꾼을 처치한 후 전리품을 챙겨야 합니다.', `FemaleText_loc4`='使用你的改装跑车|TInterface\\Icons\\inv_misc_key_12.blp:32|t追上受雇的抢掠者，夺取他们偷走的物品。', `FemaleText_loc5`='使用你的酷炫改裝車|TInterface\\Icons\\inv_misc_key_12.blp:32|t來輾過受雇的強奪者，並取得他們的財物。', `FemaleText_loc7`='Utiliza tu bólido |TInterfaceIconsinv_misc_key_12.blp:32|t para ir hasta los despojadores contratados y hacerte con su botín.' WHERE `ID`=48844;
