UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 자유다! 넵튤론 님의 이름으로 할라질을 처치하자, $n. 놈은 사원 안에 숨어 있다.', `MaleText_loc4`='我自由了！让我们以耐普图隆的名义去消灭海纳泽尔吧，$n。他就藏在这座神殿里。', `MaleText_loc5`='我自由了!讓我們以奈普圖隆之名殺死海拉希爾吧，$n。他就在神殿之中。', `MaleText_loc7`='¡Soy libre! ¡Matemos a Hallazeal en nombre de Neptulon, $n! Suele merodear en el interior del templo.', `FemaleText_loc1`='나는 자유다! 넵튤론 님의 이름으로 할라질을 처치하자, $n. 놈은 사원 안에 숨어 있다.', `FemaleText_loc4`='我自由了！让我们以耐普图隆的名义去消灭海纳泽尔吧，$n。他就藏在这座神殿里。', `FemaleText_loc5`='我自由了!讓我們以奈普圖隆之名殺死海拉希爾吧，$n。他就在神殿之中。', `FemaleText_loc7`='¡Soy libre! ¡Matemos a Hallazeal en nombre de Neptulon, $n! Suele merodear en el interior del templo.' WHERE `ID`=48867;
