UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀이 필요합니다, 거스룸 님. 서부 역병지대로 가야 해요. 국왕 폐하께 제 도움이 필요합니다!', `MaleText_loc4`='我需要一头狮鹫，戈斯鲁姆。我要前往西瘟疫之地。我的国王需要我！', `MaleText_loc5`='我需要一頭獅鷲獸，戈斯魯姆。我要去西瘟疫之地。我的國王需要我!', `MaleText_loc7`='Necesito un grifo, Guthrun. Me dirijo a las Tierras de la Peste del Oeste. ¡Mi rey me necesita!', `FemaleText_loc1`='그리핀이 필요해요, 거스룸 님. 서부 역병지대로 가야 해요. 국왕 폐하께 제 도움이 필요하거든요!', `FemaleText_loc4`='我需要一头狮鹫，戈斯鲁姆。我要前往西瘟疫之地。我的国王需要我！', `FemaleText_loc5`='我需要一頭獅鷲獸，戈斯魯姆。我要去西瘟疫之地。我的國王需要我!', `FemaleText_loc7`='Necesito un grifo, Guthrun. Me dirijo a las Tierras de la Peste del Oeste. ¡Mi rey me necesita!' WHERE `ID`=48878;
