UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박쥐가 필요합니다, 켈렌 님. 서부 역병지대로 가야 해요. 어둠의 여왕님께 제 도움이 필요합니다!', `MaleText_loc4`='我需要一只蝙蝠，凯伦。我要去西瘟疫之地。黑暗女王需要我！', `MaleText_loc5`='我需要一頭蝙蝠，凱雷恩。我要去西瘟疫之地。黑暗女王需要我!', `MaleText_loc7`='Necesito un murciélago, Kellen. Me dirijo a las Tierras de la Peste del Oeste. ¡La Dama Oscura me necesita!', `FemaleText_loc1`='박쥐가 필요해요, 켈렌 님. 서부 역병지대로 가야겠어요. 어둠의 여왕님께 제 도움이 필요하거든요!', `FemaleText_loc4`='我需要一只蝙蝠，凯伦。我要去西瘟疫之地。黑暗女王需要我！', `FemaleText_loc5`='我需要一頭蝙蝠，凱雷恩。我要去西瘟疫之地。黑暗女王需要我!', `FemaleText_loc7`='Necesito un murciélago, Kellen. Me dirijo a las Tierras de la Peste del Oeste. ¡La Dama Oscura me necesita!' WHERE `ID`=48888;
