UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티모시, 안돌할로 갈 박쥐가 필요합니다. 어둠의 여왕님께서 저를 필요로 하십니다!', `MaleText_loc4`='我需要一只蝙蝠，提摩西。我要去安多哈尔。黑暗女王需要我！', `MaleText_loc5`='我需要一頭蝙蝠，提摩西。我要前往安多哈爾。黑暗女王需要我!', `MaleText_loc7`='Necesito un murciélago, Timothy. Me dirijo a Andorhal. ¡La Dama Oscura me necesita!', `FemaleText_loc1`='티모시, 안돌할로 갈 박쥐가 필요해요. 어둠의 여왕님께서 저를 필요로 하세요!', `FemaleText_loc4`='我需要一只蝙蝠，提摩西。我要去安多哈尔。黑暗女王需要我！', `FemaleText_loc5`='我需要一頭蝙蝠，提摩西。我要前往安多哈爾。黑暗女王需要我!', `FemaleText_loc7`='Necesito un murciélago, Timothy. Me dirijo a Andorhal. ¡La Dama Oscura me necesita!' WHERE `ID`=48890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비빌파즈, 안돌할로 갈 그리핀이 필요합니다. 왕께서 저를 필요로 하십니다!', `MaleText_loc4`='我需要一头狮鹫，比比尔法兹。我要去安多哈尔。我的国王需要我！', `MaleText_loc5`='我需要一頭獅鷲獸，比比爾法茲。我要前往安多哈爾。我的國王需要我!', `MaleText_loc7`='Necesito un grifo, Bibilfaz. Me dirijo a Andorhal. ¡Mi rey me necesita!', `FemaleText_loc1`='비빌파즈, 안돌할로 갈 그리핀이 필요해요. 왕께서 저를 필요로 하세요!', `FemaleText_loc4`='我需要一头狮鹫，比比尔法兹。我要去安多哈尔。我的国王需要我！', `FemaleText_loc5`='我需要一頭獅鷲獸，比比爾法茲。我要前往安多哈爾。我的國王需要我!', `FemaleText_loc7`='Necesito un grifo, Bibilfaz. Me dirijo a Andorhal. ¡Mi rey me necesita!' WHERE `ID`=48891;
