UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 아래로 누가 오리라고 생각지 않았어요. 와서 저와 같이 있어 주세요. 아니면 나갈 길을 찾으시는 중인가요?', `FemaleText_loc4`='我没想到这里还会有人。你打算作我的同伴，还是只想找一条路出去？', `FemaleText_loc5`='我沒想到下面會有人。你是來陪我的，還是只是要找出去的路?', `FemaleText_loc7`='No esperaba a nadie aquí abajo. ¿Has venido a hacerme compañía o simplemente buscas la salida?' WHERE `ID`=48894;
