UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF언덕마루의 네 손가락 지형 중 두 번째 손가락인 코란의 비수요.|r', `MaleText_loc4`='|cFFFFFFFF考兰之匕，希尔斯布莱德四根手指的第二根。|r', `MaleText_loc5`='|cFFFFFFFF考蘭之匕是希爾斯布萊德四指的第二個營地。|r', `MaleText_loc7`='|cFFFFFFFFDaga de Corrahn, el segundo de los cuatro dedos de Campos de Trabalomas.|r' WHERE `ID`=48901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF언덕마루의 네 손가락 지형 중 세 번째 손가락인 마루터기요.|r', `MaleText_loc4`='|cFFFFFFFF山头营地，希尔斯布莱德四根手指的第三根。|r', `MaleText_loc5`='|cFFFFFFFF山頭營地是希爾斯布萊德四指的第三個營地。|r', `MaleText_loc7`='|cFFFFFFFFLa Punta, el tercero de los cuatro dedos de Campos de Trabalomas.|r' WHERE `ID`=48902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF언덕마루의 네 손가락 지형 중 마지막 손가락인 가빈 절벽이오.|r', `MaleText_loc4`='|cFFFFFFFF加文高地，希尔斯布莱德四根手指的第四根，即最后一根。|r', `MaleText_loc5`='|cFFFFFFFF加文高地是希爾斯布萊德四指的第四個營地。|r', `MaleText_loc7`='|cFFFFFFFFSaliente de Gavin, el cuarto de los cuatro dedos de Campos de Trabalomas.|r' WHERE `ID`=48903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF스톰파이크 놈들은 SI:7 첩보원들의 지원을 받고 있소. 이곳은 스톰파이크의 정찰용 전초기지로 쓰이지.|r', `MaleText_loc4`='|cFFFFFFFF雷矛卫队已经得到了军情七处的援助。这就是他们的侦查前哨站。|r', `MaleText_loc5`='|cFFFFFFFF雷矛已徵求軍情七處總部特工的協助。這是他們的偵察前哨站。|r', `MaleText_loc7`='|cFFFFFFFFLos Pico Tormenta han conseguido la ayuda de los operativos IV:7. Esta es su avanzada de exploración.|r' WHERE `ID`=48904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소화액에 녹아내리고 있습니다! 대지 고리회 주술사의 도움을 받으십시오!', `MaleText_loc4`='你正在逐步消融！赶快去找大地之环萨满救你！', `MaleText_loc5`='你正在融化!尋找陶土議會薩滿的幫助!', `MaleText_loc7`='¡Te estás disolviendo! ¡Busca la ayuda de un chamán del Anillo de la Tierra!', `FemaleText_loc1`='소화액에 녹아내리고 있습니다! 대지 고리회 주술사의 도움을 받으십시오!', `FemaleText_loc4`='你正在逐步消融！赶快去找大地之环萨满救你！', `FemaleText_loc5`='你正在融化!尋找陶土議會薩滿的幫助!', `FemaleText_loc7`='¡Te estás disolviendo! ¡Busca la ayuda de un chamán del Anillo de la Tierra!' WHERE `ID`=48905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF스톰파이크는 이곳을 병사들을 위한 작전 기지로 쓰고 있소.|r', `MaleText_loc4`='|cFFFFFFFF雷矛卫队将这里作为士兵的前锋营地。|r', `MaleText_loc5`='|cFFFFFFFF雷矛將此作為其軍隊的前線基地。|r', `MaleText_loc7`='|cFFFFFFFFLos Pico Tormenta están utilizando esto como campamento base avanzado para sus soldados.|r' WHERE `ID`=48906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF스톰파이크는 이곳에서 병사를 훈련하고, 우리를 처치할 새로운 방법을 모색한다오.|r', `MaleText_loc4`='|cFFFFFFFF他们在这里训练部队，传授给士兵各种最新和最激进的技能，好让他们来杀我们。|r', `MaleText_loc5`='|cFFFFFFFF他們在這裡訓練他們的軍隊，教導他們使用刺激的新手法來殺害我們。|r', `MaleText_loc7`='|cFFFFFFFFAquí entrenan a sus ejércitos y les enseñan nuevas y excitantes formas de asesinarnos.|r' WHERE `ID`=48907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF가장 견고한 수비를 자랑하는 손가락 지형이오. 놈들의 끔찍한 공성 기계가 조립되는 곳이지.|r', `MaleText_loc4`='|cFFFFFFFF那些手指都得到了严密守卫。而且他们恐怖的攻城器械正在这里集结。|r', `MaleText_loc5`='|cFFFFFFFF防守最好的營地。他們恐怖的攻城機具就是在這裡組裝的。|r', `MaleText_loc7`='|cFFFFFFFFY están bien protegidos por los dedos. Su terribles máquinas de asedio están reunidas aquí.|r' WHERE `ID`=48908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFFFFFF이 손가락들은 마치 우리 숨통을 조이는 스톰파이크의 손아귀와 같소. 이들을 반드시 파괴해야 하오.|r', `MaleText_loc4`='|cFFFFFFFF这些手指合在一起，如同雷矛卫队将我们紧紧攥住的拳头。必须将它们摧毁。|r', `MaleText_loc5`='|cFFFFFFFF這幾根手指頭就代表著雷矛部隊對我們的包圍掌握。所以，一定要消滅它們。|r', `MaleText_loc7`='|cFFFFFFFFTodos los dedos juntos representan la garra de los Pico Tormenta cerrándose sobre nosotros. Tienen que ser destruidos.|r' WHERE `ID`=48909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더마에 미녀가 있어', `MaleText_loc4`='在桑德玛尔，流传着一个故事', `MaleText_loc5`='有則故事傳自桑德瑪，', `MaleText_loc7`='En Bramal se cuenta la historia' WHERE `ID`=48910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 아리따움 널리 널리 퍼졌네.', `MaleText_loc4`='故事里讲述了一位美艳无俦的女郎', `MaleText_loc5`='美麗的少女氣質幽雅。', `MaleText_loc7`='de una belleza destinada para la gloria.' WHERE `ID`=48911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부드러운 녹색이 고운, 별처럼 빛나는 두 눈.', `MaleText_loc4`='柔美的脸上，一双翡翠般的眼睛里闪烁着智慧的光芒', `MaleText_loc5`='綠色的眼眸，美麗的臉龐。', `MaleText_loc7`='Suaves y verdes ojos, enmarcaban sus dulces sonrojos.' WHERE `ID`=48912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들은 그녀의 이름을 부르지. 오, 패니.', `MaleText_loc4`='人们呼喊着她的名字，“范妮”。', `MaleText_loc5`='芬妮芬妮 人人愛。', `MaleText_loc7`='La gente gritaba "Fanny", llena de euforia.' WHERE `ID`=48913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무정한 그녀, 수많은 구혼자를 외면했지.', `MaleText_loc4`='无数人在追求她，却得不到她明眸一瞥', `MaleText_loc5`='豪邁火鬍氣宇非凡，', `MaleText_loc7`='Por sus pretendientes no se dejaba impresionar,' WHERE `ID`=48914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 마음을 움직인 건 단 하나, 위대한 파이어비어드의 고백.', `MaleText_loc4`='直到强大的焰须得到她心灵的皈依', `MaleText_loc5`='英雄氣概他技壓群雄。', `MaleText_loc7`='hasta que vio a Barbafuego y amor empezó a profesar.' WHERE `ID`=48915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘도 감동시키는 사랑의 맹세.', `MaleText_loc4`='我们英雄的爱直达天堂', `MaleText_loc5`='哦芬妮芬妮，妳情歸何處?', `MaleText_loc7`='Nuestro héroe a los cielos clamó su amor' WHERE `ID`=48916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑의 여신에게 축복받은 행운아들만 읊는 아름다운 독백.', `MaleText_loc4`='满溢的祝福，世间罕有', `MaleText_loc5`='真心赤誠，要把你感動。', `MaleText_loc7`='tan profundo que a cualquier otro podría trastornar.' WHERE `ID`=48917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 고원에 환호성이 울려 퍼지네.', `MaleText_loc4`='现在，让欢呼驱散暮光', `MaleText_loc5`='歡呼慶賀暮光退散，', `MaleText_loc7`='Que la alegría el crepúsculo aleje.' WHERE `ID`=48918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 부족이 다시 결합했노라!', `MaleText_loc4`='蛮锤团结一致！', `MaleText_loc5`='蠻錘矮人齊心團結!', `MaleText_loc7`='¡Y que se unan los Martillo Salvaje!' WHERE `ID`=48919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑은 모든 것을 정복하노니, 모두 부름에 응하라.', `MaleText_loc4`='响应这号召，证明爱情能征服一切', `MaleText_loc5`='真愛無敵，收復我高地，', `MaleText_loc7`='¡A la llamada, todo lo puede el amor de tu amada!' WHERE `ID`=48920;
