UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선명한 녹색의 두 눈. 한 번 보면 누구나 정분.', `MaleText_loc4`='有着翡翠般的眼睛和能夹死男人的大腿', `MaleText_loc5`='水汪汪眼睛，白嫩嫩大腿。', `MaleText_loc7`='Verdes eran sus ojos, y fuertes sus muslos, no flojos.' WHERE `ID`=48936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패니, 그 유혹적인 이름.', `MaleText_loc4`='“范妮”这是多么完美的名字。', `MaleText_loc5`='芬妮芬妮摸兩把。', `MaleText_loc7`='Y se llamaba "Fanny", la de pelo zanahoria.' WHERE `ID`=48937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총각 파이어비어드가 구혼에 나섰네.', `MaleText_loc4`='老焰须在追求她', `MaleText_loc5`='火鬍老頭一眼看上，', `MaleText_loc7`='El viejo Barbafuego se puso al acecho.' WHERE `ID`=48938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한쪽 무릎 꿇고 사랑 고백을 했네.', `MaleText_loc4`='他单膝跪下，立下皈依的誓言：', `MaleText_loc5`='跪下求婚他大膽示愛:', `MaleText_loc7`='Cayó de rodillas para su amor profesar:' WHERE `ID`=48939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"오, 패니. 요염한 패니. 나와 결혼해 주겠소?"', `MaleText_loc4`='“哦，范妮，我的范妮，能不能嫁给我？”', `MaleText_loc5`='哦芬妮芬妮，妳嫁不嫁我?', `MaleText_loc7`='"Oh, Fanny, cásate conmigo, acógeme en tu pecho."' WHERE `ID`=48940;
