UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 고원에 환호성이 울려 퍼지네.', `MaleText_loc4`='现在，让欢呼驱散暮光', `MaleText_loc5`='歡呼慶賀暮光退散，', `MaleText_loc7`='Que la alegría el crepúsculo aleje.' WHERE `ID`=48942;
