UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파이어비어드와 패니는 최고의 궁합!', `MaleText_loc4`='焰须和他的范妮紧抱在一起。', `MaleText_loc5`='芬妮火鬍送入洞房。', `MaleText_loc7`='Que Fanny y Barbafuego son un gran fichaje.' WHERE `ID`=48945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 알지 못한다! 나는 그걸 알아내야만 했어! 그래야만 했다고!', `MaleText_loc4`='你不明白！我必须研究它。必须！', `MaleText_loc5`='你不懂!我得研究它。我必須這麼做!', `MaleText_loc7`='¡No lo entiendes! Tenía que estudiarlo. ¡TENÍA que estudiarlo!' WHERE `ID`=48946;
