UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼼짝없이 이 냄새 나는 괴물의 저녁밥이 되는 줄 알았습니다!', `MaleText_loc4`='我还以为自己注定要成为这头臭怪物的大餐了！', `MaleText_loc5`='我還以為我會成為這隻臭野獸的晚餐勒!', `MaleText_loc7`='¡Estaba convencido de que sería la cena de esa bestia apestosa!', `FemaleText_loc1`='꼼짝없이 이 냄새 나는 괴물의 저녁밥이 되는 줄 알았습니다!', `FemaleText_loc4`='我还以为自己注定要成为这头臭怪物的大餐了！', `FemaleText_loc5`='我還以為我會成為這隻臭野獸的晚餐勒!', `FemaleText_loc7`='¡Estaba convencida de que sería la cena de esa bestia apestosa!' WHERE `ID`=48948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다.', `FemaleText_loc4`='晚上好。', `FemaleText_loc5`='你好啊。', `FemaleText_loc7`='Buenas noches.' WHERE `ID`=48949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 백성들도 그대를 반겨준 것이면 좋겠군요. 지금은 모두 힘든 시기를 겪고 있어 백성들이 예전같이 친절하지 않을까 걱정입니다.', `FemaleText_loc4`='希望我的人能够给予你适当的欢迎。这是个艰难的时代，恐怕没有多少人还会在乎礼貌和优雅了。', `FemaleText_loc5`='希望我的人民對你很友善。這是沉重的時刻，所以我擔心他們的脾氣不太好。', `FemaleText_loc7`='Espero que mi gente haya sabido daros la bienvenida. Vivimos tiempos oscuros, así que me temo que su buena voluntad se ve ensombrecida por otros problemas.' WHERE `ID`=48950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮습니다, 대여사제님. 이곳에 있는 우리에게 주신 모든 것에 깊이 감사드립니다.', `MaleText_loc4`='没关系，祭司大人。您为我们所提供的一切已经让我们感激不尽了。', `MaleText_loc5`='別放心上，祭司。我們非常感謝你在此提供的一切。', `MaleText_loc7`='No hay de qué, sacerdotisa. Todos te estamos muy agradecidos por todo lo que nos has ofrecido.' WHERE `ID`=48951;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 예전에 대화를 나누었을 때, 그대는 은혜를 갚겠다고 하셨지요. 제 생각보다 이르게 그대에게 은혜를 갚도록 해야 할지도 모르겠습니다.', `FemaleText_loc4`='你曾经承诺过会还我的人情。现在，我只能让你履行你的承诺了。', `FemaleText_loc5`='我們上次談話時，你提到要償還人情。也許我得比想像中更早地用掉這個人情。', `FemaleText_loc7`='La última vez que hablamos, te ofreciste a devolverme el favor. Me temo que tendré que reclamártelo antes de lo que me hubiera gustado.' WHERE `ID`=48952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로르다넬에 문제가 생겼습니다. 루테란에서 물 건너에 있는 우리 마을이지요.', `FemaleText_loc4`='在洛达内尔，我们的一座与鲁瑟兰隔水相望的村子里出现了一些很糟糕的情况。', `FemaleText_loc5`='洛丹諾發生了一些問題，它是我們位在魯瑟蘭村對岸的一座小村莊。', `FemaleText_loc7`='Hay problemas en Lor''danel, una aldea nuestra que queda justo al otro lado de las aguas, enfrente de Rut''theran.' WHERE `ID`=48953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 종족 중 누구라도 살려둔다면 칼림도어에 있는 우리에게 전쟁이 닥쳐오지 않을까 걱정입니다.', `FemaleText_loc4`='希望你能支援我们一些人手。在卡利姆多爆发的战争正逐步蚕食着我们。', `FemaleText_loc5`='我想詢問你們是否還有人手可以幫忙。我擔心戰爭的腳步正逼近卡林多。', `FemaleText_loc7`='Espero que puedan enviar a alguno de los ustedes. Me temo que la guerra se cierne sobre nosotros en Kalimdor.' WHERE `ID`=48954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 일에 최적임자를 알고 있으니 즉시 보내드리겠습니다, 대여사제님.', `MaleText_loc4`='我知道完成这种任务最适合的人选。我会立刻派遣他们过去，祭司大人。', `MaleText_loc5`='我知道有完美的人選能做到這件事。我會立刻派他們過來，女祭司。', `MaleText_loc7`='Conozco a las personas adecuadas para esa tarea. Las enviaré inmediatamente, sacerdotisa.' WHERE `ID`=48955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 겐. 그대의 백성들에게서 그러한 침착함과 평정함을 보게 되어 정말 기쁩니다. 어쩌면 그대에게 내린 저주가 그대를 한정 짓지는 않고 있는 것 같군요.', `MaleText_loc4`='谢谢你，吉恩。很高兴能看到你的人民会如此镇定从容。也许你们受到的诅咒并没有真正伤害到你们的心灵。', `MaleText_loc5`='謝謝你，吉恩。我很高興從你的人民身上看到如此的鎮靜和沉著。也許，你們身上的詛咒並不代表你們所有的特質。', `MaleText_loc7`='Gracias, Genn. Me alegra ver que tu pueblo mantiene la calma y la compostura. Quizá tu maldición no sea definitiva después de todo.' WHERE `ID`=48956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티란데 대여사제님! 이렇게 오실 줄은 몰랐어요. 만나서 반갑습니다.', `FemaleText_loc4`='泰兰德大人！没想到你会来。晚上好。', `FemaleText_loc5`='高階祭司泰蘭妲!你好，沒想到會見到你。', `FemaleText_loc7`='¡Sacerdotisa Tyrande! No te esperábamos. Buenas noches.' WHERE `ID`=48957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 이만 가보겠습니다. 다시 한 번 모두 환영합니다.', `FemaleText_loc4`='我们就要离开了。再次欢迎你们所有人。', `FemaleText_loc5`='那我們先離開了。再一次歡迎你們的到來。', `FemaleText_loc7`='Nos marchamos. Bienvenidos a todos, de nuevo.' WHERE `ID`=48958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게, 젊은이. 길 아래엔 늑대가 들끓고 길 위엔 오크 놈들이 숨어 있다네. $c 하나쯤은 눈 깜짝할 사이에 죽는 수가 있어.', `MaleText_loc4`='小心，$g小伙子:姑娘;。下方有无数座狼，而兽人就潜伏在路口。一个$c在这里随时都有可能丧命。', `MaleText_loc5`='當心啊，$g小伙子:小姑娘;。遊盪在下面的座狼和上面的獸人之間，就連$c都能讓$g他:她;自己橫死在這裡。', `MaleText_loc7`='Cuidado $gmuhacho:muchacha;. Entre los huargos de ahí abajo y los orcos que acechan en el paso, $gun:una; $c podría acabar bien $gmuerto:muerta;.' WHERE `ID`=48959;
