UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 길을 걷지 않는 자로군! $r, 당신은 이곳에 속하지 않았다.', `MaleText_loc4`='你并非行走于黑暗道路上的人！你不属于这里，$r。', `MaleText_loc5`='你並非走黑暗之路的人!你不屬於這裡，$r。', `MaleText_loc7`='¡No formas parte del sendero oscuro! No deberías estar aquí. $r.' WHERE `ID`=48967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 당신을 삼킬 것이오. 당신은 공허의 힘과 마주할 준비가 안 됐소.', `MaleText_loc4`='暗影将吞噬你。你还没有准备好面对虚空。', `MaleText_loc5`='暗影將會吞噬你。你還沒準備好要面對虛空。', `MaleText_loc7`='Las sombras te consumirán. Te falta experiencia para enfrentarte al vacío.' WHERE `ID`=48968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사악한 것이 새 로브에 온통 얼룩을 만들었어요!', `MaleText_loc4`='这个脏东西让我的新袍子上全是污渍！', `MaleText_loc5`='那個臭東西害我的新袍子上沾滿汙漬了!', `MaleText_loc7`='¡Esa cosa nauseabunda me ha manchado mi toga nueva!', `FemaleText_loc1`='저 사악한 것이 새 로브에 온통 얼룩을 만들었어요!', `FemaleText_loc4`='这个脏东西让我的新袍子上全是污渍！', `FemaleText_loc5`='那個臭東西害我的新袍子上沾滿汙漬了!', `FemaleText_loc7`='¡Esa cosa nauseabunda me ha manchado mi toga nueva!' WHERE `ID`=48969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈 님께 네놈들의 머리를 바치겠다! 하나도 남김없이!', `MaleText_loc4`='古加尔想要你们全部的脑袋！', `MaleText_loc5`='丘加利會砍下你們的頭!全部的人!', `MaleText_loc7`='¡Cho''gall los destrozará! ¡A TODOS!' WHERE `ID`=48970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡들이 오늘 배불리 먹겠군!', `MaleText_loc4`='龙群今晚能饱餐一顿了！', `MaleText_loc5`='幼龍們今晚將飽餐一頓!', `MaleText_loc7`='¡Los vermis comerán bien!' WHERE `ID`=48971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥의 고통이 너를 기다린다!', `MaleText_loc4`='承受被诅咒者的重负吧！', `MaleText_loc5`='承受被詛咒者的重擔吧!', `MaleText_loc7`='¡Los malditos te pesarán!' WHERE `ID`=48972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아... 어지럽군...', `MaleText_loc4`='我……觉得……很晕。', `MaleText_loc5`='我...好...暈。', `MaleText_loc7`='Me... siento... mareado.', `FemaleText_loc1`='아아... 어지럽군...', `FemaleText_loc4`='我……觉得……很晕。', `FemaleText_loc5`='我...好...暈。', `FemaleText_loc7`='Me... siento... mareada.' WHERE `ID`=48973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 감사합니다! 당신이 쓰러졌을 땐 우리 모두 끝장이구나 싶었어요!', `MaleText_loc4`='谢谢你救了我！你昏过去的时候，我还以为我们都完了！', `MaleText_loc5`='謝謝你救了我!當你昏倒時，我還以為我們完蛋了!', `MaleText_loc7`='¡Gracias por salvarme! ¡Cuando te has desmayado he pensado que había llegado nuestro final!', `FemaleText_loc1`='구해 주셔서 감사합니다! 당신이 쓰러졌을 땐 우리 모두 끝장이구나 싶었어요!', `FemaleText_loc4`='谢谢你救了我！你昏过去的时候，我还以为我们都完了！', `FemaleText_loc5`='謝謝你救了我!當你昏倒時，我還以為我們完蛋了!', `FemaleText_loc7`='¡Gracias por salvarme! ¡Cuando te has desmayado he pensado que había llegado nuestro final!' WHERE `ID`=48974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밴시 거울로 밴시를 불러오십시오!', `MaleText_loc4`='用女妖之镜召唤来一个女妖！', `MaleText_loc5`='用女妖之鏡呼叫一名女妖!', `MaleText_loc7`='¡Llama a un alma en pena con el espejo alma en pena!', `FemaleText_loc1`='밴시 거울로 밴시를 불러오십시오!', `FemaleText_loc4`='用女妖之镜召唤来一个女妖！', `FemaleText_loc5`='用女妖之鏡呼叫一名女妖!', `FemaleText_loc7`='¡Llama a un alma en pena con el espejo alma en pena!' WHERE `ID`=48975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 놈의 심장을 쳐야 한다고 말했을 땐, 이렇게 뱃속으로 직접 들어가자는 뜻은 아니었어요...', `MaleText_loc4`='当我说要直击那个怪兽的心脏的时候，我可没有想要穿透它的肚子……', `MaleText_loc5`='當我說我們要攻擊野獸的心臟時，我沒想過要通過牠的胃...', `MaleText_loc7`='Cuando dije que debíamos golpear justo en el corazón de la bestia, no tenía en mente tener que pasar por su estómago...', `FemaleText_loc1`='제가 놈의 심장을 쳐야 한다고 말했을 땐, 이렇게 뱃속으로 직접 들어가자는 뜻은 아니었어요...', `FemaleText_loc4`='当我说要直击那个怪兽的心脏的时候，我可没有想要穿透它的肚子……', `FemaleText_loc5`='當我說我們要攻擊野獸的心臟時，我沒想過要通過牠的胃...', `FemaleText_loc7`='Cuando dije que debíamos golpear justo en el corazón de la bestia, no tenía en mente tener que pasar por su estómago...' WHERE `ID`=48976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 원소의 힘이 매우 강력하군요. 놈들이 고대 신의 하수인을 소환하는 곳으로 여기를 택한 것도 당연해요.', `MaleText_loc4`='元素的力量在这里非常强大。怪不得他们会选择在这里召唤上古之神的仆人。', `MaleText_loc5`='元素的力量在這裡非常強大。難怪他們選擇在這裡召喚上古之神的僕人。', `MaleText_loc7`='El poder de los elementos es intenso aquí. Por lo tanto no me extraña que fuera aquí donde decidieron invocar a un sirviente de los dioses antiguos.', `FemaleText_loc1`='이곳은 원소의 힘이 매우 강력하군요. 놈들이 고대 신의 하수인을 소환하는 곳으로 여기를 택한 것도 당연해요.', `FemaleText_loc4`='元素的力量在这里非常强大。怪不得他们会选择在这里召唤上古之神的仆人。', `FemaleText_loc5`='元素的力量在這裡非常強大。難怪他們選擇在這裡召喚上古之神的僕人。', `FemaleText_loc7`='El poder de los elementos es intenso aquí. Por lo tanto no me extraña que fuera aquí donde decidieron invocar a un sirviente de los dioses antiguos.' WHERE `ID`=48977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끔찍한 환상을 봤답니다... 하늘이 보이지 않고 온통 먼지만 가득한 곳... 제가 심원의 영지로 돌아간 줄 알았어요.', `MaleText_loc4`='我似乎看到一种可怕的景象——天空被遮蔽，到处都是尘泥……我还以为又回到了深岩之洲。', `MaleText_loc5`='我當時視野很差。天空被遮蓋了，灰塵滿天...我想我還是回地深之源的好。', `MaleText_loc7`='Tuve una visión horrible. No se veía el cielo y había tierra por todas partes. Creí... que había regresado a Infralar.', `FemaleText_loc1`='정말 끔찍한 환상을 봤답니다... 하늘이 보이지 않고 온통 먼지만 가득한 곳... 제가 심원의 영지로 돌아간 줄 알았어요.', `FemaleText_loc4`='我似乎看到一种可怕的景象——天空被遮蔽，到处都是尘泥……我还以为又回到了深岩之洲。', `FemaleText_loc5`='我當時視野很差。天空被遮蓋了，灰塵滿天...我想我還是回地深之源的好。', `FemaleText_loc7`='Tuve una visión horrible. No se veía el cielo y había tierra por todas partes. Creí... que había regresado a Infralar.' WHERE `ID`=48978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고원으로 진작에 돌아갔어야 했는데! 망할 "황혼"이 없었을 때 말이죠.', `MaleText_loc4`='现在该是我们返回高地的时候了！“暮光”必将终结。', `MaleText_loc5`='是時候回去高地了!暮光...去死吧。', `MaleText_loc7`='¡Ya era hora de que volviéramos a las Tierras Altas! Maldito sea el "Crepúsculo".', `FemaleText_loc1`='고원으로 진작에 돌아갔어야 했는데! 망할 "황혼"이 없었을 때 말이죠.', `FemaleText_loc4`='现在该是我们返回高地的时候了！“暮光”必将终结。', `FemaleText_loc5`='是時候回去高地了!暮光...去死吧。', `FemaleText_loc7`='¡Ya era hora de que volviéramos a las Tierras Altas! Maldito sea el "Crepúsculo".' WHERE `ID`=48979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왠지 엑소다르에서 이것과 비슷한 걸 봤다는 기분이 듭니다...', `MaleText_loc4`='我记得曾经在埃索达看到过与此类似的……', `MaleText_loc5`='我想我在艾克索達看過類似的東西...', `MaleText_loc7`='Creo que una vez vi algo parecido en El Exodar...', `FemaleText_loc1`='왠지 엑소다르에서 이것과 비슷한 걸 봤다는 기분이 듭니다...', `FemaleText_loc4`='我记得曾经在埃索达看到过与此类似的……', `FemaleText_loc5`='我想我在艾克索達看過類似的東西...', `FemaleText_loc7`='Creo que una vez vi algo parecido en El Exodar...' WHERE `ID`=48980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이가 대지 고리회와 세나리온 의회를 헷갈려 해요... 그래서 스랄 님에게 우리 단체 이름을 "대지 고리단"으로 바꾸자고 그렇게 말했는데.', `MaleText_loc4`='有许多人会把陶土议会和塞纳里奥议会混为一谈……我早就告诉过萨尔，我们应该改名为“大地之环”。', `MaleText_loc5`='很多人會把陶土議會和塞納里奧議會搞混。我告訴過索爾應該把我們改名為陶土協會。', `MaleText_loc7`='Muchos confunden el Anillo de la Tierra con el Círculo Cenarion. Le DIJE a Thrall que debíamos cambiarnos el nombre a "Cuadrado de la Tierra".', `FemaleText_loc1`='많은 이가 대지 고리회와 세나리온 의회를 헷갈려 해요... 그래서 스랄 님에게 우리 단체 이름을 "대지 고리단"으로 바꾸자고 그렇게 말했는데.', `FemaleText_loc4`='有许多人会把陶土议会和塞纳里奥议会混为一谈……我早就告诉过萨尔，我们应该改名为“大地之环”。', `FemaleText_loc5`='很多人會把陶土議會和塞納里奧議會搞混。我告訴過索爾應該把我們改名為陶土協會。', `FemaleText_loc7`='Muchos confunden el Anillo de la Tierra con el Círculo Cenarion. Le DIJE a Thrall que debíamos cambiarnos el nombre a "Cuadrado de la Tierra".' WHERE `ID`=48981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s|1이;가; |cFFFF0000|Hspell:90949|h[파멸의 불길]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s开始施放|cFFFF0000|Hspell:90949|h[噬体烈焰]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s開始施展|cFFFF0000|Hspell:90949|h[吞噬烈焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightflamebreath.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:90949|h[Llamas devoradoras]|h|r!' WHERE `ID`=48982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사와 드루이드는 매우 다르다고요. 우리 주술사가 야생 동물로 변신하는 걸 마지막으로 보신 게 언제죠? ... 아니, 신경 쓰지 마세요.', `MaleText_loc4`='萨满和德鲁伊之道截然不同。你什么时候看见过我们变成野兽？……算了。', `MaleText_loc5`='薩滿之道和德魯伊之道非常不同。你什麼時候見過我們變身為野獸?...當我沒說。', `MaleText_loc7`='Los caminos de un chamán y de un druida son muy diferentes. ¿Cuándo fue la última vez que viste a uno de nosotros transformarse en una bestia salvaje...? No importa.', `FemaleText_loc1`='주술사와 드루이드는 매우 다르다고요. 우리 주술사가 야생 동물로 변신하는 걸 마지막으로 보신 게 언제죠? ... 아니, 신경 쓰지 마세요.', `FemaleText_loc4`='萨满和德鲁伊之道截然不同。你什么时候看见过我们变成野兽？……算了。', `FemaleText_loc5`='薩滿之道和德魯伊之道非常不同。你什麼時候見過我們變身為野獸?...當我沒說。', `FemaleText_loc7`='Los caminos de un chamán y de un druida son muy diferentes. ¿Cuándo fue la última vez que viste a uno de nosotros transformarse en una bestia salvaje...? No importa.' WHERE `ID`=48983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 원소의 힘을 부리죠. 폭풍과 대지, 그리고 불! 뻥튀기한 닭 같은 모양새로 하늘에서 달빛을 불러내다니, 저는 그런 짓은 절대로 하지 않겠어요.', `MaleText_loc4`='我们操纵元素的力量。风暴、大地和火焰！我才不会穿成鸡仔一样，让月光从天空上射下来。', `MaleText_loc5`='我們能控制元素的力量。暴風，大地和火焰!我才不會穿得像特大號的雞，從天空呼叫月光束。', `MaleText_loc7`='Nosotros controlamos el poder de los elementos. ¡Tormenta, tierra y fuego! Nunca me vestiré como un pollo gigante ni lanzaré rayos de luna desde el cielo.', `FemaleText_loc1`='저희는 원소의 힘을 부리죠. 폭풍과 대지, 그리고 불! 뻥튀기한 닭 같은 모양새로 하늘에서 달빛을 불러내다니, 저는 그런 짓은 절대로 하지 않겠어요.', `FemaleText_loc4`='我们操纵元素的力量。风暴、大地和火焰！我才不会穿成鸡仔一样，让月光从天空上射下来。', `FemaleText_loc5`='我們能控制元素的力量。暴風，大地和火焰!我才不會穿得像特大號的雞，從天空呼叫月光束。', `FemaleText_loc7`='Nosotros controlamos el poder de los elementos. ¡Tormenta, tierra y fuego! Nunca me vestiré como un pollo gigante ni lanzaré rayos de luna desde el cielo.' WHERE `ID`=48984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 당신이 침묵하기를 원하십니다.', `MaleText_loc4`='主人会让你安静下来的。', `MaleText_loc5`='主人會讓你沉默。', `MaleText_loc7`='EL MAESTRO DESEA QUE GUARDES SILENCIO.' WHERE `ID`=48985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"저는 폭풍의 힘을 지배합니다!"라고 하면 참 멋있죠? 하지만 아침마다 정전기 때문에 고생이랍니다.', `MaleText_loc4`='我操纵风暴的力量。这听起来很强大，但我每天早晨醒来的时候，身上总是会窜起一道道静电火花。', `MaleText_loc5`='我能控制暴風之力。聽起來很酷，但是每天早上醒來都會被靜電電到。', `MaleText_loc7`='Yo controlo el poder de la tormenta. Suena impresionante, pero todas las mañanas te levantas con una gran carga de electricidad estática.', `FemaleText_loc1`='"저는 폭풍의 힘을 지배합니다!"라고 하면 참 멋있죠? 하지만 아침마다 정전기 때문에 고생이랍니다.', `FemaleText_loc4`='我操纵风暴的力量。这听起来很强大，但我每天早晨醒来的时候，身上总是会窜起一道道静电火花。', `FemaleText_loc5`='我能控制暴風之力。聽起來很酷，但是每天早上醒來都會被靜電電到。', `FemaleText_loc7`='Yo controlo el poder de la tormenta. Suena impresionante, pero todas las mañanas te levantas con una gran carga de electricidad estática.' WHERE `ID`=48986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 뇌에 주먹질하고 싶어 견딜 수가 없군요!', `MaleText_loc4`='我现在就想用双拳打碎那个上古之神的脑壳！', `MaleText_loc5`='我等不及要用我的拳頭痛扁那個上古之神的腦袋了!', `MaleText_loc7`='¡No puedo esperar a aplastar el cerebro de ese dios antiguo entre mis manos!', `FemaleText_loc1`='저 뇌에 주먹질하고 싶어 견딜 수가 없군요!', `FemaleText_loc4`='我现在就想用双拳打碎那个上古之神的脑壳！', `FemaleText_loc5`='我等不及要用我的拳頭痛扁那個上古之神的腦袋了!', `FemaleText_loc7`='¡No puedo esperar a aplastar el cerebro de ese dios antiguo entre mis manos!' WHERE `ID`=48987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진말로를 두려워하지 마십시오. 다른 누구의 것도 되지 않을 것입니다.', `MaleText_loc4`='不要害怕辛玛洛。它永远也不可能属于别人。', `MaleText_loc5`='不用擔心辛瑪洛。它永遠不會屬於別人。', `MaleText_loc7`='NO TEMAS POR ZIN-MALOR. NUNCA PERTENECERÁ A OTRO.' WHERE `ID`=48988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 복장에 어울리는 장착 무기 한 쌍을 찾는 게 얼마나 어려운 일인지 아십니까?', `MaleText_loc4`='你知道，想要找到一套能配上我的护甲的武器有多难吗？', `MaleText_loc5`='你知道要找到一組能配上我護甲的武器是有多麼地困難嗎?', `MaleText_loc7`='¿Sabes lo difícil que me ha resultado encontrar armas que fueran a juego con mi armadura?', `FemaleText_loc1`='이 복장에 어울리는 장착 무기 한 쌍을 찾는 게 얼마나 어려운 일인지 아십니까?', `FemaleText_loc4`='你知道，想要找到一套能配上我的护甲的武器有多难吗？', `FemaleText_loc5`='你知道要找到一組能配上我護甲的武器是有多麼地困難嗎?', `FemaleText_loc7`='¿Sabes lo difícil que me ha resultado encontrar armas que fueran a juego con mi armadura?' WHERE `ID`=48989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 주술사들은 제게 이렇게 말하곤 하죠. "불꽃은 보조 무기에만 있어야 해." 그게 대체 무슨 소립니까?', `MaleText_loc4`='其他萨满经常说：“只有你的副手应该喷火。”他们这么说是什么意思？', `MaleText_loc5`='以前其他薩滿都會跟我說，只有副手要冒出火舌。那到底是什麼意思?', `MaleText_loc7`='Otro chamán solía decir: "Solo tu arma debería arder." ¿De qué estaban hablando?', `FemaleText_loc1`='다른 주술사들은 제게 이렇게 말하곤 하죠. "불꽃은 보조 무기에만 있어야 해." 그게 대체 무슨 소립니까?', `FemaleText_loc4`='其他萨满经常说：“只有你的副手应该喷火。”他们这么说是什么意思？', `FemaleText_loc5`='以前其他薩滿都會跟我說，只有副手要冒出火舌。那到底是什麼意思?', `FemaleText_loc7`='Otro chamán solía decir: "Solo tu arma debería arder". ¿De qué estaban hablando?' WHERE `ID`=48990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 구해 주셔서 감사합니다, 젊은 양반. 정말 끔찍한 환상을 봤어요. 전 불꽃이 이글거리는 동굴에 갇혀 있었습니다. 그리고 몇 년 동안 계속해서 토템만 꽂고 성난 전사들만 죽어라 치유했지요. 그런데 주술사용 장비는 하나도 안 나오는 거예요.', `MaleText_loc4`='感谢你救了我，$g小伙子:姑娘;，我看到了非常可怕的情景。我被困在一个满是火焰的洞窟中，被迫不停地栽下图腾，治疗愤怒的战士，就这样连续许多年没有停止过，却始终没有见到一件萨满装备。', `MaleText_loc5`='謝謝你救了我，$g小伙子:小姑娘;。我預見了一個恐怖的景象。我被困在一個充滿火焰的山洞，被迫要插圖騰，治療怒氣衝天的戰士，最後還看不到半件薩滿用的裝備。', `MaleText_loc7`='Gracias por salvarme $gmuchacho:muchacha;, tuve una visión horrible. Estaba atrapado en una cueva de llamas y me obligaban a plantar tótems y a sanar a guerreros iracundos hasta el fin de los tiempos, sin una sola pieza de equipamiento de chamán.', `FemaleText_loc1`='절 구해 주셔서 감사합니다, 젊은 양반. 정말 끔찍한 환상을 봤어요. 전 불꽃이 이글거리는 동굴에 갇혀 있었습니다. 그리고 몇 년 동안 계속해서 토템만 꽂고 성난 전사들만 죽어라 치유했지요. 그런데 주술사용 장비는 하나도 안 나오는 거예요.', `FemaleText_loc4`='感谢你救了我，$g小伙子:姑娘;，我看到了非常可怕的情景。我辈困在一个满是火焰的洞窟中，被迫不停地栽下图腾，治疗愤怒的战士，就这样连续许多年没有停止过，却始终没有见到一件萨满装备。', `FemaleText_loc5`='謝謝你救了我，$g小伙子:小姑娘;。我預見了一個恐怖的景象。我被困在一個充滿火焰的山洞，被迫要插圖騰，治療怒氣衝天的戰士，最後還看不到半件薩滿用的裝備。', `FemaleText_loc7`='Gracias por salvarme $gmuchacho:muchacha;, tuve una visión horrible. Estaba atrapado en una cueva de llamas y me obligaban a plantar tótems y a sanar a guerreros iracundos hasta el fin de los tiempos, sin una sola pieza de equipamiento de chamán.' WHERE `ID`=48991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명력을 회복시키는 것은 원소의 질서를 회복하는 것과 같소.', `MaleText_loc4`='回复生命就是恢复元素的自然秩序。', `MaleText_loc5`='要回復生命，就是回復元素的自然秩序。', `MaleText_loc7`='Restaurar la vida es restaurar el orden natural de los elementos.', `FemaleText_loc1`='생명력을 회복시키는 것은 원소의 질서를 회복하는 것과 같소.', `FemaleText_loc4`='回复生命就是恢复元素的自然秩序。', `FemaleText_loc5`='要回復生命，就是回復元素的自然秩序。', `FemaleText_loc7`='Restaurar la vida es restaurar el orden natural de los elementos.' WHERE `ID`=48992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사의 치유는 복잡하기 그지없는 하나의 예술이오. 온종일 연쇄 치유만 하고 있을 수는 없지.', `MaleText_loc4`='萨满的治疗术是一种复杂的艺术。你不可能花一整天的时间来操纵治疗的能量。', `MaleText_loc5`='薩滿的治療是一種複雜的藝術。你總不能整天都在用治療鍊。', `MaleText_loc7`='La sanación chamanística es un arte muy completo. No puedes dedicarte a encadenar sanaciones todo el día.', `FemaleText_loc1`='주술사의 치유는 복잡하기 그지없는 하나의 예술이오. 온종일 연쇄 치유만 하고 있을 수는 없지.', `FemaleText_loc4`='萨满的治疗术是一种复杂的艺术。你不可能花一整天的时间来操纵治疗的能量。', `FemaleText_loc5`='薩滿的治療是一種複雜的藝術。你總不能整天都在用治療鍊。', `FemaleText_loc7`='La sanación chamanística es un arte muy completo. No puedes dedicarte a encadenar sanaciones todo el día.' WHERE `ID`=48993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사가 대지와 얼마나 긴밀한 연관을 맺고 있는지 아는 이는 많지 않소. 우리는 대지의 힘으로 상처를 치유하고, 우리 자신을 적에게서 보호하지.', `MaleText_loc4`='没有几个人能真正理解萨满与大地的联系。正是这种联系让伤口愈合，保护我们免于受到伤害。', `MaleText_loc5`='很少人真正能了解薩滿與大地之間的連結。它能使傷口癒合，並保護我們不受傷害。', `MaleText_loc7`='Muy pocos comprenden la conexión chamanística con la tierra. Cura heridas y nos protege del daño.', `FemaleText_loc1`='주술사가 대지와 얼마나 긴밀한 연관을 맺고 있는지 아는 이는 많지 않소. 우리는 대지의 힘으로 상처를 치유하고, 우리 자신을 적에게서 보호하지.', `FemaleText_loc4`='没有几个人能真正理解萨满与大地的联系。正是这种联系让伤口愈合，保护我们免于受到伤害。', `FemaleText_loc5`='很少人真正能了解薩滿與大地之間的連結。它能使傷口癒合，並保護我們不受傷害。', `FemaleText_loc7`='Muy pocos comprenden la conexión chamanística con la tierra. Cura heridas y nos protege del daño.' WHERE `ID`=48994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화 토템이 왜 금지되었는지 도무지 이유를 모르겠소. 사용해 봤자 어차피 사정거리 안에 들어오는 이도 없었는데.', `MaleText_loc4`='我不明白，他们为什么要禁止利用图腾进行净化。毕竟在净化范围内没有任何人。', `MaleText_loc5`='我不懂為什麼他們不讓我們用圖騰淨化。反正從來都沒有人在距離範圍內啊。', `MaleText_loc7`='No alcanzo a comprender por qué prohibieron la purificación totémica.', `FemaleText_loc1`='정화 토템이 왜 금지되었는지 도무지 이유를 모르겠소. 사용해 봤자 어차피 사정거리 안에 들어오는 이도 없었는데.', `FemaleText_loc4`='我不明白，他们为什么要禁止利用图腾进行净化。毕竟在净化范围内没有任何人。', `FemaleText_loc5`='我不懂為什麼他們不讓我們用圖騰淨化。反正從來都沒有人在距離範圍內啊。', `FemaleText_loc7`='No alcanzo a comprender por qué prohibieron la purificación totémica.' WHERE `ID`=48995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이제... 여기로 심장을 가져오십시오. 어떤 것이라도 상관없습니다. 살아 있거나, 차갑게 식은 거나 말이지요...', `FemaleText_loc4`='好吧…………这里的全都属于你。没关系，无论是有生命的、岩石的，还是……', `FemaleText_loc5`='好吧...你就拿一點這個，隨便都好，沒有關係，活的還是石頭的還是什麼的都一樣...', `FemaleText_loc7`='Muy bien... Tú recoge los trozos que haya aquí, cualquier trozo, no importa si está vivo, o es de piedra o qué...' WHERE `ID`=48996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지진흙 습지대로 갈 탈것이 필요합니다.', `MaleText_loc4`='我需要飞往尘泥沼泽。', `MaleText_loc5`='我需要飛到塵泥沼澤。', `MaleText_loc7`='Necesito volar a Marjal Revolcafango.', `FemaleText_loc1`='먼지진흙 습지대로 갈 탈것이 필요해요.', `FemaleText_loc4`='我需要飞往尘泥沼泽。', `FemaleText_loc5`='我需要飛到塵泥沼澤。', `FemaleText_loc7`='Necesito volar a Marjal Revolcafango.' WHERE `ID`=48997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그다음 사팔눈을 하고 엄지손가락을 하늘을 향해 드십시오. 그리고 아주 세게 누르십시오...', `FemaleText_loc4`='如果你让两只眼睛对起来，将拇指伸向天空，用力按过去……', `FemaleText_loc5`='如果你閉眼睛，大拇指朝上翹起來，真的很用力給它壓下去...', `FemaleText_loc7`='Y si cruzas los ojos, levantas los pulgares hacia el cielo y presionas fuerte DE VERDAD...' WHERE `ID`=48998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...그러면 가끔 에코가 빠져나온답니다! 바로 그렇게 말입니다.', `FemaleText_loc4`='魂精就有可能出现！就像这样。', `FemaleText_loc5`='...魂精有時候就會跑出來!就像那樣。', `FemaleText_loc7`='... ¡El E''ko aparecerá en algún momento! Así de fácil.' WHERE `ID`=48999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 이 선물 상자는 비어 있지만, 옛 친구들과 좋았던 시절을 생각나게 해 줍니다.', `MaleText_loc4`='虽然这些礼物并没有什么实际用处。但它们还是能让我想起那些老朋友和过去美好的时光。', `MaleText_loc5`='就算這些禮物是空的，它們會幫我想起老朋友和舊時光。', `MaleText_loc7`='A pesar de que estos presentes son vacíos, me ayudan a recordar a viejos amigos y tiempos mejores.' WHERE `ID`=49000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뇌가 공격받자 이소라스의 배가 마구 요동칩니다!', `MaleText_loc4`='当那个脑子受到进攻时，厄索拉斯的肚子也开始搅动起来！', `MaleText_loc5`='伊索拉斯之腦被攻擊時，它的胃開始劇烈的翻騰!', `MaleText_loc7`='¡El estómago de Iso''rath empieza a rugir cuando el cerebro es atacado!', `FemaleText_loc1`='뇌가 공격받자 이소라스의 배가 마구 요동칩니다!', `FemaleText_loc4`='当那个脑子受到进攻时，厄索拉斯的肚子也开始搅动起来！', `FemaleText_loc5`='伊索拉斯之腦被攻擊時，它的胃開始劇烈的翻騰!', `FemaleText_loc7`='¡El estómago de Iso''rath empieza a rugir cuando el cerebro es atacado!' WHERE `ID`=49001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보세요! 이게 뭐예요 도대체?!', `MaleText_loc4`='嘿！你们在干嘛？！', `MaleText_loc5`='嘿!搞什麼，老兄?!', `MaleText_loc7`='¡EH! ¡¿Qué demonios, $gtío:tía;?!' WHERE `ID`=49002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나치게 친한 척하고, 사려 깊지 못하고, 황소고집인 사람들 중에서...', `MaleText_loc4`='这些不可理喻，不知好歹，肆意妄为的家伙……', `MaleText_loc5`='那些黏答答，毫不體貼，又任性的...', `MaleText_loc7`='De todos los asquerosos, desconsiderados y cabezotas...' WHERE `ID`=49003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 길이라도 잃었니, 꼬마야?', `MaleText_loc4`='哈！你迷路了吗，小$g男孩:女孩;？', `MaleText_loc5`='哈!你迷路了嗎，$g小男孩:小女孩;?', `MaleText_loc7`='¡JA! ¿Te has perdido, $gchaval:chavala;?', `FemaleText_loc1`='하! 길이라도 잃었니, 꼬마야?', `FemaleText_loc4`='哈！你迷路了吗，小$g男孩:女孩;？', `FemaleText_loc5`='哈!你迷路了嗎，$g小男孩:小女孩;?', `FemaleText_loc7`='¡JA! ¿Te has perdido, $gchaval:chavala;?' WHERE `ID`=49004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 끝장이다, 친구! 언덕마루는 스톰파이크의 것이다!', `MaleText_loc4`='你们完蛋了，$g小子:小姑娘;！希尔斯布莱德是雷矛卫队的！', `MaleText_loc5`='你的時候到了，$g孩子:女孩;!雷矛要佔領希爾斯布萊德了!', `MaleText_loc7`='¡Se te acabó el tiempo, $gmuchacho:muchacha;! ¡Los Pico Tormenta están tomando Laderas de Trabalomas!', `FemaleText_loc1`='넌 끝장이다, 친구! 언덕마루는 스톰파이크의 것이다!', `FemaleText_loc4`='你们完蛋了，$g小子:小姑娘;！希尔斯布莱德是雷矛卫队的！', `FemaleText_loc5`='你的時候到了，$g孩子:女孩;!雷矛要佔領希爾斯布萊德了!', `FemaleText_loc7`='¡Se te acabó el tiempo, $gmuchacho:muchacha;! ¡Los Pico Tormenta están tomando Laderas de Trabalomas!' WHERE `ID`=49005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔 놈이냐?', `MaleText_loc4`='这又是什么？', `MaleText_loc5`='那這又是什麼?', `MaleText_loc7`='Entonces, ¿qué es esto?', `FemaleText_loc1`='뭔 놈이냐?', `FemaleText_loc4`='这又是什么？', `FemaleText_loc5`='那這又是什麼?', `FemaleText_loc7`='Entonces, ¿qué es esto?' WHERE `ID`=49006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 밧줄 좀 가져와!', `MaleText_loc4`='哈！得到了一根绳子！', `MaleText_loc5`='喂!拿根繩子!!', `MaleText_loc7`='¡EH! ¡CONSIGUE UNA CUERDA!', `FemaleText_loc1`='어이! 밧줄 좀 가져와!', `FemaleText_loc4`='哈！得到了一根绳子！', `FemaleText_loc5`='喂!拿根繩子!!', `FemaleText_loc7`='¡EH! ¡CONSIGUE UNA CUERDA!' WHERE `ID`=49007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기지를 잘못 찾아온 것 같군!', `MaleText_loc4`='你走错了地方！', `MaleText_loc5`='你跑錯營地了!', `MaleText_loc7`='¡Has entrado en el campamento equivocado!', `FemaleText_loc1`='기지를 잘못 찾아온 것 같군!', `FemaleText_loc4`='你走错了地方！', `FemaleText_loc5`='你跑錯營地了!', `FemaleText_loc7`='¡Has entrado en el campamento equivocado!' WHERE `ID`=49008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만반의 태세를 갖춰라, 병사들이여! 소페라 절벽 근처에서 적의 움직임이 포착됐다는 보고가 있다!', `MaleText_loc4`='士兵们，高度戒备！有报告说，在索菲亚高地附近发现了敌人的行踪！', `MaleText_loc5`='高度警戒，士兵們!有報告進來，說索菲亞高地附近有敵蹤!', `MaleText_loc7`='¡Alerta, soldados! Los informes indican algún tipo de actividad cerca de Saliente de Sofera!' WHERE `ID`=49009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 상황은 어떤가? 적의 움직임이라도 포착됐나?', `MaleText_loc4`='这里的情况如何？有什么行动吗？', `MaleText_loc5`='這裡的狀況怎樣?有什麼動靜嗎?', `MaleText_loc7`='¿Qué ves desde ahí? ¿Alguna actividad?' WHERE `ID`=49010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냉정을 유지하라, 병사들이여. 곧 이동하게 될 거다.', `MaleText_loc4`='保持冷静，士兵们。我们很快就要采取行动了。', `MaleText_loc5`='保持冷靜，士兵們。我們很快就會有動作了。', `MaleText_loc7`='Mantened la sangre fría, soldados. Pronto nos pondremos en marcha.' WHERE `ID`=49011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기는 정말 세계 최고로 잘생긴 남자친구예요. 아주 그냥 죽여줘요!', `FemaleText_loc4`='你是一个女孩所能梦想的最英俊的男朋友。所有女孩都会为你神魂颠倒，甜心！', `FemaleText_loc5`='你是女人夢寐以求的最帥男朋友。寶貝，迷死他們!', `FemaleText_loc7`='Eres el novio más guapo que cualquier chica podría desear. ¡Dales duro, cariño!' WHERE `ID`=49012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 아름다울 수가! 난 이 섬에서 가장 행복한 남자랍니다!', `MaleText_loc4`='看到你！我就知道我是这座岛上最幸运的男孩子！！！', `MaleText_loc5`='看看你!我是這座島上最幸運的男朋友了!', `MaleText_loc7`='¡Mírate! ¡¡¡Soy el novio con más suerte de la isla!!!' WHERE `ID`=49013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s|1이;가; |cFFFF0000|Hspell:87770|h[바람 폭발]|h|r을 시전합니다!', `MaleText_loc4`='|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s开始施放|cFFFF0000|Hspell:87770|h[阵风冲击]|h|r！', `MaleText_loc5`='|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s 開始施放|cFFFF0000|Hspell:87770|h[疾風爆發]|h|r!', `MaleText_loc7`='|TINTERFACEICONSSpell_Frost_WindWalkOn.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:87770|h[Ráfaga de viento]|h|r!' WHERE `ID`=49014;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 바로 위층으로 올라가 보시는 편이 좋겠어요. 무역왕 갤리윅스가 기다리고 있어요.', `FemaleText_loc4`='你最好快上楼去，老板。贸易大王加里维克斯正在等你。', `FemaleText_loc5`='你最好立刻上樓，老大。貿易親王加里維克斯正在等你。', `FemaleText_loc7`='Será mejor que subas las escaleras echando leches, $gjefe:jefa;. El príncipe mercante Gallywix te espera.' WHERE `ID`=49015;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 서둘러야 해요. 은행에 맡겨뒀던 돈을 꺼내오세요!', `FemaleText_loc4`='$n，你必须加紧行动，把你的钱从银行里拿出来！', `FemaleText_loc5`='$n，你得加快腳步，去把錢從銀行拿出來!', `FemaleText_loc7`='¡$n, tienes que darte prisa y sacar tu pasta del banco!' WHERE `ID`=49016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생산이 다시 시작되면 카자콜라를 더 가져다주겠다고 새시에게 꼭 좀 전해달라고.', `MaleText_loc4`='老板，告诉莎希，只要生产恢复，我就能为她提供更多的卡亚可乐。', `MaleText_loc5`='老闆，告訴賽希說等生產線恢復，我就會弄更多的卡迦可樂給她!', `MaleText_loc7`='$gJefe:Jefa;, dile a Sassy que le llevaré más Kaja''Cola en cuanto se reanude la producción.' WHERE `ID`=49017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 더 가져다주겠다고요? 우리 최고의 히트 상품을 매장에서 팔 수가 없는데 어떻게 당신이 $g무역왕:무역여왕;이 될 수가 있겠느냐고요?!!!', `FemaleText_loc4`='他能给我们弄到更多的卡亚可乐吗？如果我们不能让自己的头号商品摆满货架，又怎么能让你成为贸易大王？！！！', `FemaleText_loc5`='晚點會給我更多?第一名的產品都擺不上貨架，是要怎樣把你升成貿易$g親王:女王;?!!!', `FemaleText_loc7`='¿Me conseguirá más después? ¡¡¡¿Cómo vamos a conseguir que asciendas a $gPríncipe:Princesa; mercante si nuestro producto estrella falta en las estanterías?!!!' WHERE `ID`=49018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아, 이게 정말 마음에 드실 거예요!', `FemaleText_loc4`='哦，我想你会喜欢这个的，老板！', `FemaleText_loc5`='哦，你一定會喜歡這個的，老大!', `FemaleText_loc7`='¡Oooh, creo que esto te gustará, $gjefe:jefa;!' WHERE `ID`=49019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 오셨군요! 좋아요, 오늘 하루 $n 님을 잘 도와주세요. 파티를 시작하기 전에 처리할 일이 산더미처럼 쌓였으니까요!', `FemaleText_loc4`='他们在这里！好了，你们三个今天来帮$g他:她; ，在聚会开始之前，$G他:她;要做的事情可是不少呢！', `FemaleText_loc5`='都來了!很好，你們三個今天給我好好的幫$g他:她;忙。$G他:她;在派對開始前還有很多的事情要處理!', `FemaleText_loc7`='¡Ahí están! Está bien, hoy ustedes tres $gle:la; ayudarán. ¡Tiene que ocuparse de un montón de cosas antes de la fiesta!' WHERE `ID`=49020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에이스, 이지, 고버, 여러분은 $n 님을 잘 따라다니면서 저 멍청한 게으름뱅이들을 함께 혼쭐을 내 주세요!', `FemaleText_loc4`='王牌、小静、大胖，你们三个要跟着$n，帮助他处理那些坏家伙！', `FemaleText_loc5`='愛司，伊茲，古柏，你們三個好好跟著$n，幫忙$g他:她;解決那些賴帳的!', `FemaleText_loc7`='¡As, Izzy, Gargajo, acompañen a $n y ayúdenle a que se encargue de esos morosos!' WHERE `ID`=49021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행에서 돈을 충분히 찾으세요. 평소처럼 싸구려 옷을 사면 절대 안 돼요. 이번 파티는 정말 중요하다고요!', `MaleText_loc4`='一定要从那个银行里拿到足够的钱。我可不希望你还去买你平时喜欢穿的那种廉价衣服。这可是个重要的聚会！', `MaleText_loc5`='記得從銀行領多點錢出來。我不要你又買那些平常穿的便宜衣服。這個派對很重要!', `MaleText_loc7`='Asegúrate de sacar suficiente pasta del banco. No quiero que compres ropa barata de esa que llevas normalmente. ¡Esta fiesta es importante!' WHERE `ID`=49022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은행에서 돈을 잔뜩 찾으세요. 평소처럼 싸구려 옷을 사면 절대로 안 돼요, 자기. 이번 파티는 정말 중요하다고요!', `FemaleText_loc4`='一定要从那个银行里拿到足够的钱。我可不希望你还去买你平时喜欢穿的那种廉价衣服。这可是个重要的聚会！', `FemaleText_loc5`='記得從銀行領多點錢出來。我不要你又買那些平常穿的便宜衣服。這個派對很重要!', `FemaleText_loc7`='Asegúrate de sacar suficiente pasta del banco. No quiero que compres ropa barata de esa que llevas normalmente. ¡Esta fiesta es importante!' WHERE `ID`=49023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 잠깐 기다려요! 우리 $n이 여기 왔어. 바로 다음 무역왕이 될 사람이지!', `MaleText_loc4`='你们不得不等一等了！$n来了。$G他:她;将是下一任贸易大王！', `MaleText_loc5`='你們這些人安靜一點!$n在此。$G他:她;即將成為下一任的貿易$G親王:女王;!', `MaleText_loc7`='¡Eh, dejen lo que estén haciendo! $n está aquí. $gÉl:Ella; será $gel próximo príncipe mercante:la próxima princesa mercante;!' WHERE `ID`=49024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러줘. 어서 시합에 참가해야겠어. 하지만 그전에, 우선 벌목기 부품을 가져와야 해!', `MaleText_loc4`='你要快一点，孩子。我们要让你加入比赛。但首先，我们要给这台伐木机找好零件！', `MaleText_loc5`='你得快一點，孩子。我們會把你弄進去比賽裡面。但首先，我們得先拿到那個伐木機的零件!', `MaleText_loc7`='¡Date prisa, $gchaval:chavala;! Tenemos que meterte en el partido. Pero primero, ¡tenemos que conseguir las piezas de esa trituradora!' WHERE `ID`=49025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 저 벌목기를 타고 시합에서 이겨버리라고. 빌지워터 무역회사 사람들은 모두 자넬 믿고 있어!', `MaleText_loc4`='进入伐木机，赢得比赛。锈水财阀就指望你了！', `MaleText_loc5`='進去伐木機裡面，並贏得比賽。污水企業聯合就靠你了!', `MaleText_loc7`='Súbete a esa trituradora y gana el partido. ¡El Cártel Pantoque cuenta contigo!' WHERE `ID`=49026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 정말 소질이 대단하군. 그건 확실해! 저 용이 튀어나오면서 완전히 훼방을 놓은 게 문제지. 그래도 상관없어. 자네 덕분에 우린 모두 자랑스러우니까. 자, 이제 본사로 돌아가라고.', `MaleText_loc4`='你胜利了，孩子，这太好了！可惜的是，那头龙已经把一切都毁掉了。不过没关系。你的成就让我们感到自豪。现在，回总部去吧。', `MaleText_loc5`='你有真才實料，孩子。這是可以肯定的!可惜龍把這一切都毀了。無論如何，你讓我們感到驕傲。現在回去總部吧。', `MaleText_loc7`='Los tienes cuadrados, $gchaval:chavala;. Es una pena que apareciera ese dragón y lo estropeara todo. No importa. Nos sentimos orgullosos de ti. Ahora regresa al cuartel general.' WHERE `ID`=49027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 제가 가르쳐 드리는 고정 사격을 잘 배우고, 여기 있는 훈련용 허수아비에 시험 삼아 사용해 보기만 하면 됩니다.', `MaleText_loc4`='我会教你如何进行稳固射击，然后你就要在这些训练假人上练习这种技能了。', `MaleText_loc5`='你唯一需要做的就是讓我教你如何使用穩固射擊然後使用在這些訓練假人身上。', `MaleText_loc7`='Todo lo que tienes que hacer es dejar que te enseñe a utilizar el Disparo firme y después utilizarlo en esos muñecos de entrenamiento de ahí.' WHERE `ID`=49028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 얼음 회오리 주문을 시전하는 방법을 배워야 해. 그 다음에는 저기로 가서 뱀 녀석이 가지고 놀고 있는 훈련용 허수아비를 조각조각 부숴버리라고.', `MaleText_loc4`='你要做的就是学会如何施放冰霜新星。然后，到巴姆正在射击的那些训练假人那里去，冻裂它们。', `MaleText_loc5`='你唯一需要做的就是學會如何使用冰霜新星。然後去邦姆正在射的那些訓練假人那裡，對其中一個施放法術。', `MaleText_loc7`='Todo lo que tienes que hacer es aprender a lanzar Nova de escarcha. Después, dirígete a esos muñecos de entrenamiento de ahí contra los que está disparando Bamm y destruirlos.' WHERE `ID`=49029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 권능: 고통 주문을 배우고 나서, 이 근처에 있는 훈련용 허수아비에 사용하기만 하면 돼요!', `FemaleText_loc4`='你所要做的就是学习暗言术：痛，并使用在附近的训练假人身上！', `FemaleText_loc5`='你現在要做的，就是學會暗言術:痛，然後再把它施展在附近的訓練假人身上!', `FemaleText_loc7`='Todo lo que tienes que hacer es aprender Palabra de las Sombras: dolor, y después utilizarla sobre alguno de los muñecos de entrenamiento que hay aquí.' WHERE `ID`=49030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 제게서 절개를 배우시기만 하면 돼요. 그다음 저기 뱀 메가밤이 갖고 놀고 있는 훈련용 허수아비를 사악한 일격으로 공격하세요. 공격 후에는 절개를 사용해서 마무리 일격을 날리시고요!', `FemaleText_loc4`='我会教你如何施展刺骨技能。然后，你可以到巴姆正在射击的那些训练假人那里去，用影袭技能攻击其中的一个，再用刺骨技能干掉那个假人。', `FemaleText_loc5`='你現在要做的，就是讓我教教你怎樣施展「剔骨」。然後，到邦姆正在射擊的假人那裡，對它使出「邪惡攻擊」，接著再使用「剔骨」這個終結技。', `FemaleText_loc7`='Todo lo que tienes que hacer es dejar que te enseñe a Eviscerar. Después, dirígete a esos muñecos de entrenamiento contra los que está disparando Bamm y ataca con un Golpe siniestro. Una vez hecho eso, acaba con uno usando Eviscerar.' WHERE `ID`=49031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 일단 나한테 원시의 일격을 배우라고! 그리고 저기 뱀 메가밤이 갖고 놀고 있는 훈련용 허수아비에게 원시의 일격을 날려버려!', `MaleText_loc4`='我会教你如何进行根源打击。然后，你可以到巴姆正在射击的那些训练假人那里去，实践这个技能。', `MaleText_loc5`='你唯一需要做的就是讓我教你如何使用原始之擊，然後使用在邦姆正在射的那些訓練假人身上。', `MaleText_loc7`='Todo lo que tienes que hacer es dejar que te enseñe a ejecutar Golpe primigenio. Después utilízalo con los muñecos de entrenamiento contra los que está disparando Bamm.' WHERE `ID`=49032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 부패 주문을 시전하는 방법을 배워야 해. 그 다음에는 가서 뱀 메가밤이 갖고 노는 훈련용 허수아비에게 사용해! 화끈하게 부패시키라고!', `MaleText_loc4`='你要做的就是学会如何施放腐蚀术。然后，对巴姆正在射击的那些训练假人使用这个法术，腐蚀它们。', `MaleText_loc5`='你唯一需要做的就是學會如何使用腐化，然後使用在邦姆正在射的那些訓練假人身上。讓它腐化吧!', `MaleText_loc7`='Todo lo que tienes que hacer es dejar que te enseñe a lanzar el hechizo de Corrupción. Después utilízalo con los muñecos de entrenamiento contra los que está disparando Bamm. ¡Corrómpelos!' WHERE `ID`=49033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01에게 돌격을 배우시려면 동전을 넣어주십시오. 돌격을 배운 후에는 훈련용 허수아비에게 사용하십시오.', `MaleText_loc4`='塞入硬币，全能战士NX-01型会教你如何进行冲锋。然后你可以在训练假人身上进行实践。', `MaleText_loc5`='投入硬幣讓自動戰士NX-01教你如何衝鋒。然後使用在訓練假人身上。', `MaleText_loc7`='Inserta monedas en la Guerreromática NX-01 para recibir instrucción sobre cómo Cargar. Después utilízalo en los muñecos de entrenamiento.' WHERE `ID`=49034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별장에 들어가면 모자가 자동으로 작동되도록 설정해 드릴게요. 돼지만 피하세요!', `FemaleText_loc4`='你到了那幢小屋之后，我会将帽子设置成自动状态。小心一定要躲开那些猪！', `FemaleText_loc5`='等你抵達別墅以後，我會把它設定為自動啟動。你只要小心避開那些豬!', `FemaleText_loc7`='Pondré el almete en auto-activar una vez llegues a la villa. ¡Tú concéntrate en evitar a esos cerdos!' WHERE `ID`=49035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리바람 야영지로 가는 탈것이 필요합니다.', `MaleText_loc4`='我需要飞往寒风营地，请帮助我。', `MaleText_loc5`='我需要飛到冰風營地。', `MaleText_loc7`='Necesito volar a Campamento del Orvallo, por favor.', `FemaleText_loc1`='서리바람 야영지로 가는 탈것이 필요해요.', `FemaleText_loc4`='我需要飞往寒风营地，请帮助我。', `FemaleText_loc5`='我需要飛到冰風營地。', `FemaleText_loc7`='Necesito volar a Campamento del Orvallo, por favor.' WHERE `ID`=49036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보루로 가는 탈것이 필요합니다.', `MaleText_loc4`='我需要飞往亡灵壁垒，请帮助我。', `MaleText_loc5`='我需要飛到亡靈壁壘。', `MaleText_loc7`='Necesito volar a El Baluarte, por favor.', `FemaleText_loc1`='보루로 가는 탈것이 필요해요.', `FemaleText_loc4`='我需要飞往亡灵壁垒，请帮助我。', `FemaleText_loc5`='我需要飛到亡靈壁壘。', `FemaleText_loc7`='Necesito volar a El Baluarte, por favor.' WHERE `ID`=49037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 트롤들이 얼마나 뻔뻔스러운지 믿을 수가 없을 정도라니까! 내가 그렇게 잘 해줬는데 반란이라니!', `MaleText_loc4`='真无法相信这些巨魔的勇气。他们竟然敢造我的反！', `MaleText_loc5`='我無法相信那些食人妖的臉皮這麼厚!在我為他們做了這麼多之後，居然反叛了!', `MaleText_loc7`='No puedo creer las narices que tienen esos trols. ¡Se rebelan después de todo lo que hemos hecho por ellos!' WHERE `ID`=49038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 배짱 한 번 좋다!', `MaleText_loc4`='你可真有胆量，兄弟！', `MaleText_loc5`='你膽子真不小，老兄!', `MaleText_loc7`='¡Pero qué morro que tiene'', colega!' WHERE `ID`=49039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 저 커다란 용을 불러들여서 섬을 부쉈구나!', `MaleText_loc4`='你要消灭那头大坏龙，摧毁了那座岛！', `MaleText_loc5`='是你叫來了大壞龍，搞毀了這座島!', `MaleText_loc7`='¡Haz caer a ese maldito dragón enoh''me y deh''truye la isla!' WHERE `ID`=49040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 이제는 참지 않아!', `MaleText_loc4`='我可不打算再这样了，兄弟！', `MaleText_loc5`='我已經受夠了，老兄!', `MaleText_loc7`='¡No pienso aguantah''lo más, colega!' WHERE `ID`=49041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케잔은 트롤 거야!', `MaleText_loc4`='科赞是巨魔的！', `MaleText_loc5`='凱贊是食人妖的!', `MaleText_loc7`='¡Kezan pa los trols!' WHERE `ID`=49042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜! 난 해적들과 한편이 될 거야!', `MaleText_loc4`='别挡我的路，兄弟。我要加入海盗！', `MaleText_loc5`='滾一邊去，老兄。我要去加入海盜!', `MaleText_loc7`='¡Fuera de mi camino, tronco! ¡Me largo pa unirme a lo'' piratas!' WHERE `ID`=49043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 폭탄은 내 거야! 어디 누가 박살 나는지 한 번 볼까?!', `MaleText_loc4`='也许我应该把炸弹从你手里拿走。然后我们看看谁会爆炸！', `MaleText_loc5`='也許我從你這裡拿走炸彈然後看看是誰炸誰!', `MaleText_loc7`='¡Quizá os quite la'' bombas y ya veremos quién hace bum!' WHERE `ID`=49044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자마이트는 우리 거야! 우리가 피땀 흘려 캐낸 거야!', `MaleText_loc4`='这就是卡亚矿石！是我们挥洒血汗挖掘出来的宝物！', `MaleText_loc5`='卡迦邁是我們的!我們自己用血汗挖出來的!', `MaleText_loc7`='¡Eh''ta es nueh''tra kaja''mita! ¡Nosotros la excavamos con nueh''tro sudor y nueh''tra sangre!' WHERE `ID`=49045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 조그만 고블린들이 이제 피눈물 흘릴 차례야!', `MaleText_loc4`='小绿地精要流血了！', `MaleText_loc5`='你們這些綠色的哥布林會為所做的一切付出鮮血!', `MaleText_loc7`='¡Tu, pequeño y verde goblin, vas a sangrar por to''o lo que has hecho!' WHERE `ID`=49046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 이 멍청한 녀석아, 여기서 뭘 하는데? 가서 저 재수 없는 $n|1이;가; 오는지 지켜봐!$B$B가서 네 일이나 하라고!', `MaleText_loc4`='什么？你想要什么？你在开玩笑吗？现在跑去望风没有任何好处，$n！$B$B赶快回去工作！', `MaleText_loc5`='嗯?你想幹嘛，蠢蛋?看看$n那個壞傢伙!$B$B還不回去工作!', `MaleText_loc7`='¿Sí?¿Qué es lo que quieres, $gpringado:pringada;? ¡Sube a la atalaya en busca de $gese maldito:esa maldita; $n!$B$B¡Ahora vuelve al trabajo!' WHERE `ID`=49047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈것이 필요하세요? 타세요. 우린 수렁진흙탕으로 내려갈 겁니다. 편도 여행이에요.', `FemaleText_loc4`='想要驰骋一番吗，$g坏家伙:甜心;？来吧，我们要去沼桨镇。这可是一次单程旅行。', `FemaleText_loc5`='要搭便車嗎，$g寶貝:醜八怪;?上來。我們要去沼槳，而且這是一趟單程之旅。', `FemaleText_loc7`='¿Necesitas que te lleven $gbombón:montón de basura;? Sube. Nos dirigimos a Chapaleos, y es un viaje solo de ida.' WHERE `ID`=49048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 슬픔의 늪으로 내려갑시다!', `MaleText_loc4`='好了，我们去悲伤沼泽！', `MaleText_loc5`='好吧，咱們出發到悲傷沼澤吧!', `MaleText_loc7`='¡Está bien! ¡Bajemos al Pantano de las Penas!', `FemaleText_loc1`='좋아요! 슬픔의 늪으로 내려갑시다!', `FemaleText_loc4`='好了，我们去悲伤沼泽！', `FemaleText_loc5`='好吧，咱們出發到悲傷沼澤吧!', `FemaleText_loc7`='¡Está bien! ¡Bajemos al Pantano de las Penas!' WHERE `ID`=49049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영면의 안식처로 가는 급사를 호위하러 왔습니다.', `MaleText_loc4`='我来这里是为了护送去库斯海文的人。', `MaleText_loc5`='我是來送東西到柯特海文的。', `MaleText_loc7`='He venido para escoltar el envío hasta Kirthaven.', `FemaleText_loc1`='영면의 안식처로 가는 급사를 호위하러 왔습니다.', `FemaleText_loc4`='我来这里是为了护送去库斯海文的人。', `FemaleText_loc5`='我是來送東西到柯特海文的。', `FemaleText_loc7`='He venido para escoltar el envío hasta Kirthaven.' WHERE `ID`=49050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 똑바로 차리게, $n! 저 길엔 용아귀 부족이 득실거린다네.', `MaleText_loc4`='睁大眼睛，$n！这条路上全都是龙喉兽人。', `MaleText_loc5`='保持警覺，$n!那條路上到處都是龍喉!', `MaleText_loc7`='¡Abre bien los ojos, $n! El camino está abarrotado de Faucedraco.' WHERE `ID`=49051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 수송대가 갑니다!', `MaleText_loc4`='喔！我们有保镖了！', `MaleText_loc5`='噢耶!有人來護送我們了!', `MaleText_loc7`='¡Yujuuuuu! ¡Acabamos de conseguir un convoy!' WHERE `ID`=49052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자기가 영웅이라고 착각하는 필멸자 무리가 파괴된 전당에 들어왔군. 흥, 이번 "공격대"는 지난번 놈들보다는 괜찮았으면 좋겠어.', `MaleText_loc4`='做着英雄梦的凡人进入了破坏大厅。希望这次“袭击”能够比上次更精彩一点。', `MaleText_loc5`='自稱為英雄的凡人進入了破碎之廳。我真心期待這個「團隊」會比上一個有趣。', `MaleText_loc7`='Unos mortales que se creen HÉROES han entrado en la Cámara Partida. Oh, de verdad espero que esta "banda" al menos me divierta más que la última.' WHERE `ID`=49053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 만능골렘 방어 시스템이라. 오래전에는 이 시설이 드워프가 이룩한 엄청난 기술적 성과로 여겨졌지. 하지만 각 골렘의 공격에 대응할 방법이 너무 많은 게 문제야. 조금이라도 보는 재미가 있으려면 설계를 좀 손봐야 할 것 같군.', `MaleText_loc4`='嗯……“全能金刚防御系统”。几个世纪前，这些粗糙的魔像阵列组还被称为矮人技术的杰作，殊不知每个单独的魔像都能被轻易反制。我不得不亲自修正那些设计缺陷，才能让它们给我提供些娱乐。', `MaleText_loc5`='嗯...全能魔像防禦系統。幾個世紀前這個簡陋的製品曾被視為矮人最棒的技術成就，但是它的每種攻擊都有簡單的方法應付!若這個「全能魔像防禦系統」能逗我開心，我就願意改進那些設計缺陷。', `MaleText_loc7`='Hmmm... Sistema de Defensa de Omnitron. Hace siglos estos ensamblajes eran considerados como el mayor logro tecnológico de los enanos. Como existen tantos contraataques para los ataques de cada ensamblaje, tendré que rediseñar los planos para que me ofrezcan algo de entretenimiento.' WHERE `ID`=49054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈에게서 도망가고 싶겠지. 안 그런가? 안됐군.', `MaleText_loc4`='你想离它远点，是吗？太糟糕了。', `MaleText_loc5`='你想要離那個遠點，對吧?真可惜。', `MaleText_loc7`='Les gustaría poder dejar todo eso atrás, ¿no? Qué pena.' WHERE `ID`=49055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 드워프 놈들은 왜 그렇게 룬을 좋아하는지! 적을 도울 수도 있는 걸 도대체 왜 만들었는지 모르겠군.', `MaleText_loc4`='愚蠢的矮人，对符文愚蠢的痴迷！为什么你们要创造能够帮助敌人的东西？', `MaleText_loc5`='愚蠢的矮人，總是愛用符文!為什麼製造會幫到你敵人的東西呢?', `MaleText_loc7`='¡Estúpidos enanos y su fascinación por las runas! ¿Por qué construir algo que ayudará a tu enemigo?' WHERE `ID`=49056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하... 번개 전도체는 인원이 많을수록 효과가 좋지.', `MaleText_loc4`='闪电导体对集群目标的效果更好，对吧？', `MaleText_loc5`='避雷針用在人群裡效果最好，對吧?', `MaleText_loc7`='El conductor de relámpagos funciona mucho mejor sobre multitudes, ¿no?' WHERE `ID`=49057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹독골렘의 화학 물질로 다른 골렘에 피해를 줄 생각이었겠지? 영리한 계획이다만, 그렇게 둘 수는 없지.', `MaleText_loc4`='你打算使用剧毒金刚的化学能量摧毁其它魔像？聪明的计划。让我来帮你毁掉这个计划。', `MaleText_loc5`='你想用烈毒號的物質對付其他傀儡?聰明的計畫，我來搞砸它吧。', `MaleText_loc7`='¿Planeaban usar los químicos del Toxitron para dañar los otros ensamblajes? Un plan muy inteligente, permítanme arruinarlo.' WHERE `ID`=49058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 실수했군. 저런 한심한 이름을 가진 기계들에게... 재미있는 구경거리를 기대하다니.', `MaleText_loc4`='我早该知道，名字这么蠢的东西多半娱乐不了多久。', `MaleText_loc5`='我早該知道別指望名字這麼蠢的東西能提供足夠的娛樂性。', `MaleText_loc7`='Debería haberme dado cuenta de que no podía confiar en que me entretuviera una cosa con un nombre tan estúpido.' WHERE `ID`=49059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 방 바로 아래에 흐르는 용암 속에서 그 매혹적인 생명체를 찾아냈지. 용암아귀라면 한심한 네놈들에게 적당한 도전 거리가 될 것이다.', `MaleText_loc4`='我在这个房间下方的熔岩里找到了这个奇妙的样本。对你们这支可怜的小团队来说，熔喉应该是个“适度”的挑战。', `MaleText_loc5`='我在這個房間下面的熔岩裡找到這個有趣的樣本。熔喉應該可以提供你們可悲的小隊伍適當的挑戰。', `MaleText_loc7`='Encontré este fascinante espécimen en la lava justo debajo de esta sala. Faucemagma debería ser un desafío adecuado para gente tan patética como ustedes.' WHERE `ID`=49060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다시 생각해 보니 "적당한" 도전에 무슨 재미가 있겠나?', `MaleText_loc4`='转念一想，“适度”的挑战又有什么乐趣呢？', `MaleText_loc5`='話說回來，適當的挑戰有什麼樂趣?', `MaleText_loc7`='Pensándolo mejor, ¿qué tiene de divertido un desafío "adecuado"?' WHERE `ID`=49061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 이겼군. 참으로 실망스럽구나. 너희가 불구덩이 속에서 이리저리 뛰는 모습을 즐길 수도 있었는데.', `MaleText_loc4`='你们赢了？真……令人失望啊。我本以为可以目送你们葬身于火海中。', `MaleText_loc5`='你贏了?真...令人失望。我本來還想繼續看你們站在火裡面。', `MaleText_loc7`='¿Habéis ganado? Qué... decepción. Me habría gustado ver cómo seguíais debatiéndoos en el fuego un poco más.' WHERE `ID`=49062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 키마이론. 과학자로서 내 실력이 어떤지 잘 보여주는 생명체지. 오랜 시간 동안 녀석의 모습을 수없이 다시 만들고 변형했다. 보다시피 마지막 결과물은 참으로 훌륭하지.', `MaleText_loc4`='啊，奇美隆，这是我的科学力量的活证。我对他进行了多年的加工和改造，才有了现在这杰出的成果。', `MaleText_loc5`='啊，奇瑪隆，我科學成就的最佳見證。我多年來無數次重新塑造他的形態，而最終的結果看起來相當不錯。', `MaleText_loc7`='Ah, Chimaeron, un testimonio viviente de mi destreza como científico. Rehíce y retorcí su forma incontables veces a lo largo de los años, y el resultado final es algo digno de contemplar.' WHERE `ID`=49063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 기대했던 것과 달라서 놀랐겠지. 그렇지 않으냐? 내가 만든 일련의 "수정 사항"에 너희가 얼마나 잘 적응하는지 보자꾸나.', `MaleText_loc4`='哦，你们是否有些期待在战斗中出现一些变数？那么让我看看你们对“调整方案”的适应程度如何？', `MaleText_loc5`='噢，你本來期待會發生別的事情，對吧?咱們看看你怎麼應付這套新的調整，如何?', `MaleText_loc7`='Ah, estaban esperando que ocurriera otra cosa, ¿no? Veamos lo bien que se adaptan USTEDES luego de una nueva serie de "ajustes"…' WHERE `ID`=49064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 중요한 순간에 뭐 하는 짓이냐, 키마이론!', `MaleText_loc4`='立刻停止自相殴斗，奇美隆！', `MaleText_loc5`='立刻停止內鬨，奇瑪隆!', `MaleText_loc7`='¡Deja inmediatamente de luchar contigo mismo, Chimaron!' WHERE `ID`=49065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 전투가 좀 지루해졌군. 내가 분위기를 띄워 주지!', `MaleText_loc4`='这场战斗有一点乏味了，请让我给大家助助兴！', `MaleText_loc5`='這場戰鬥有點悶了，我來加點料吧!', `MaleText_loc7`='Esta lucha se ha puesto un poco sosa. ¡Permítanme que anime las cosas!' WHERE `ID`=49066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 저 실험체를 잃다니, 애석하군.', `MaleText_loc4`='失去这个实验品可真遗憾……', `MaleText_loc5`='嗯...就這樣毀了真可惜...', `MaleText_loc7`='Ha sido una pena perder ese experimento...' WHERE `ID`=49067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말로리악, 필멸의 존재들에게 지지 마라. 너만큼이라도 능력이 있는 놈은 만들기 어렵지.', `MaleText_loc4`='马洛拉克，尽量别输给那些凡人。“半称职”的帮手可是很难创造的。', `MaleText_loc5`='瑪洛里亞克，不要輸給這些凡人。能力差的僕人已經夠難製造了。', `MaleText_loc7`='Maloriak, intenta no perder contra esos mortales. Crear ayudantes semi competentes es algo TAN difícil.' WHERE `ID`=49068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼합물이 너무 약하구나, 말로리악! 좀 더... 센 게 필요해! 으하하하하하...', `MaleText_loc4`='你的混合剂太弱了，马洛拉克！他们需要更多的……“催化”！', `MaleText_loc5`='你的混合劑太弱了，瑪洛里亞克!需要多點...後勁!', `MaleText_loc7`='¡Tus mezclas son flojas, Maloriak! ¡Necesitan un poco más de... sustancia!' WHERE `ID`=49069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 축하한다! 너희가 달성한 놀라운 업적에 걸맞은 멋진 칭호를 하나 내려 주지. 지금부터 너희는 "멍청하고 무능하고 실망스러운 하수인들을 해치운 자"로 알려질 것이다.', `MaleText_loc4`='祝贺你们！为了嘉奖你们的惊人成就，请允许我授予你们一个合适的头衔。从今以后，你们就是“蠢货、无能者和饭桶喽罗的克星。”', `MaleText_loc5`='恭喜!讓我來頒發給你符合這個特殊成就的稱號。從現在起，你應該被稱為「愚蠢無能又令人失望的爪牙殺戮者」。', `MaleText_loc7`='¡Felicitaciones! Permitanme concederles un título acorde con su asombrosa proeza. A partir de ahora los conocerán como los "Destripadores de esbirros estúpidos, incompetentes y decepcionantes".' WHERE `ID`=49070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈물이 앞을 가리네요. 좋은 기억들이 참 많았는데... 돈벌이도 좋았고...', `FemaleText_loc4`='这么多美好的回忆，这么多丰厚的利润。我可不能袖手旁观。', `FemaleText_loc5`='我看不下去了。那麼多的美好回憶，那麼多的利潤...', `FemaleText_loc7`='No puedo soportar verlo. Tantos buenos recuerdos. Tantos beneficios.' WHERE `ID`=49071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 와일드해머의 친구여!$B$B영면의 안식처는 우리 동족에게 영적 수도입니다. 서로 다른 여러 가문이 평화롭게 한자리에 모이는 장소이고요.$B$B여기서 저희는 저 세상에 간 영웅들을 기리는 의식을 치른 후 천둥쐐기 산꼭대기에 영웅과 그의 그리핀을 함께 장사 지냅니다. 그들이 영원히 하늘을 누비게 해주는 거죠.', `MaleText_loc4`='欢迎，蛮锤的朋友们！$B$B库斯海文是我们一族的精神核心。在这里，不同的部族会在和平中聚首。$B$B在这里，我们共同哀悼逝去的英雄，将他们和他们的狮鹫埋葬在雷霆山的顶端。让他们与天空融为一体，永垂不朽。', `MaleText_loc5`='歡迎，蠻錘的朋友!$B$B柯特海文是我們人民靈魂信仰的中心，不同的部族能和平地共處。$B$B我們在此為死去的英雄獻上榮耀，然後才在雷擊山頂把他們的獅鷲獸和他們一起埋葬。在那裡，他們和天空一同度過永恆。', `MaleText_loc7`='¡Te doy la bienvenida, $gamigo:amiga; de los Martillo Salvaje!$B$BKirthaven es el centro espiritual de nuestro pueblo, el lugar donde los diferentes clanes pueden reunirse en paz.$B$BEs donde honramos a los héroes muertos antes de enterrarlos con sus grifos en lo alto del Monte del Rayo. Allí pueden pasar la eternidad en el cielo.' WHERE `ID`=49072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:91317|h[숭배]|h|r를 시전합니다!', `MaleText_loc4`='你开始施放|cFFFF0000|Hspell:91317|h[膜拜]|h|r！', `MaleText_loc5`='你開始施放|cFFFF0000|Hspell:91317|h[信奉]|h|r!', `MaleText_loc7`='¡Empiezas a lanzar |cFFFF0000|Hspell:91317|h[Adoración]|h|r!' WHERE `ID`=49073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아트라메데스, 눈처럼 귀도 먼 건 아니겠지? 어서 놈들을 모조리 처치해라.', `MaleText_loc4`='艾卓曼德斯，难道你不光瞎了，还是聋子？快干掉他们！', `MaleText_loc5`='亞特拉米德，你是又盲又聾嗎?快點殺光他們。', `MaleText_loc7`='Atramedes, ¿te estás volviendo sordo además de ciego? Date prisa y mátalos a todos.' WHERE `ID`=49074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아트라메데스, 적은 바로 저기에 있다!', `MaleText_loc4`='艾卓曼德斯，那些英雄就在那边！', `MaleText_loc5`='亞特拉米德，英雄們就在那!', `MaleText_loc7`='¡Atramedes, los héroes están justo AHÍ!' WHERE `ID`=49075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 방패들은 정말 귀찮군.', `MaleText_loc4`='这些盾牌确实讨厌。', `MaleText_loc5`='這些護盾比想像中麻煩。', `MaleText_loc7`='Esos escudos están resultando ser una gran molestia.' WHERE `ID`=49076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 오래전에 널 없애 버렸어야 했는데.', `MaleText_loc4`='你早就该被处理掉了。', `MaleText_loc5`='你早就該被處理掉了。', `MaleText_loc7`='Tenía que haberme librado de ti hace tiempo.' WHERE `ID`=49077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결혼이라고요? 두 가문이 결혼으로 맺어지고도 화해하지 못한다면 제 망치를 먹겠습니다!$B$B이번 결혼식은 최고로 멋지게 치러야 합니다, $n 님. 그러려면 당신 도움이 필요하고요. 와일드해머 속담에 이런 말이 있죠... 잠깐만요... 어떻게 시작하더라?', `MaleText_loc4`='一场婚礼？如果这还不能把这些家伙聚集在一起，我就吃掉我的锤子！$B$B我们需要让这场婚礼无比隆重盛大，$n，我们需要你的帮助。有一句蛮锤的老话……让我想想……那句话是怎么说的？', `MaleText_loc5`='一場婚禮，嗯?如果這沒辦法把那兩個傢伙送做堆，我就把我的錘子吃了!$B$B我們得讓這場婚禮非常盛大，$n，而我們需要你的幫忙。有一句古老的蠻錘諺語...我想想...是怎麼說的?', `MaleText_loc7`='Una boda, ¿eh? ¡Si eso no hace que estos se unan me comeré mi martillo!$B$BTenemos que hacer que esta boda sea espectacular, $n, y para eso necesitaremos tu ayuda. Hay un viejo dicho de los Martillo Salvaje... déjame pensar... ¿Cómo era?' WHERE `ID`=49078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 적이 쫓고 있는 것을 그냥 놈들에게 내어줘야 할지도 모르겠다... 우리 백성을 피바다로 내몰지 않으려면 말이야.', `MaleText_loc4`='也许我们应该把敌人要的东西给他们……这样至少可以让我们的人民免受血腥屠杀。', `MaleText_loc5`='也許我們應該直接給敵人他們要的東西...這樣我們的人就不需要流血了。', `MaleText_loc7`='Quizá debamos darle al enemigo lo que busca... Así le ahorraríamos a nuestra gente el derramamiento de sangre que se aproxima.' WHERE `ID`=49079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 원하는 게 그뿐이라면 전쟁을 피할 수 있을지도 모른다. 내 백성이 피를 흘리지 않을 수도 있어!', `MaleText_loc4`='如果这就是他们想要的，也许我们可以避免一场战争，可以阻止血流成河的惨祸发生！', `MaleText_loc5`='如果他們要的就是這個，也許真的可以避免戰爭。流血衝突可以完全避免掉!', `MaleText_loc7`='Si eso es todo lo que quiere, quizá podamos evitar la guerra. ¡Debemos evitar el derramamiento de sangre que se avecina!' WHERE `ID`=49080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 내 백성을 지켜야 한다. 놈들은 오르시스를 사막에 묻어버렸다. 그런 힘을 가진 적과 대체 어떻게 싸운단 말인가?', `MaleText_loc4`='我必须首先保护我的人民。我们的敌人已经将奥西斯埋葬在沙漠中。你怎么能和这样的力量作战？', `MaleText_loc5`='我必須優先保護我的人民。我們的敵人把奧爾希斯埋在沙漠裡了。我們如何和這樣的力量戰鬥。', `MaleText_loc7`='Primero debo actuar para proteger a mi pueblo. Nuestros enemigos enterraron Orsis en el desierto. ¿Cómo podemos luchar contra un poder de esas características?' WHERE `ID`=49081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 말이 옳다, 형제여... 하지만 짐이 왕이라고 해도 이런 결정을 혼자서 내릴 수는 없다. 이 문제를 대의원회에서 표결에 부쳐야 하겠다.', `MaleText_loc4`='你的话没有错，兄弟……但即使是国王也不可能独自做出决定。我会让高阶议会对此事进行投票。', `MaleText_loc5`='你說的話是事實，兄弟...但是即使是國王也無法獨自做出這樣的決定。我會把這個問題交給高階議會來投票。', `MaleText_loc7`='Tus palabras dicen la verdad, hermano... pero ni siquiera un rey puede tomar esa decisión solo. Lo someteré a la votación del Alto Consejo.' WHERE `ID`=49082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결혼이 성사됐군! 행복한 연인에게 줄 결혼 선물을 준비해야겠어. 뭔가 중요한 걸로 말일세.$B$B이 결혼식은 마지막 기회일세. 온 와일드해머 드워프의 미래가 이 단 한 번의 기회에 달렸다네!', `MaleText_loc4`='婚礼就要开始了！我需要为这快乐的一对准备一件礼物。一件非常重要的礼物。$B$B蛮锤的未来完全系于这最后一个将我们团结在一起的机会！', `MaleText_loc5`='這個婚禮辦定了!當然了，我需要替幸福的新人們準備禮物。某個重要的東西。$B$B蠻錘的未來真的得靠這最後的機會來把我們團結起來!', `MaleText_loc7`='¡La boda es un hecho! Voy a necesitar un regalo para los tortolitos, claro. Algo importante.$B$B¡El futuro de los Martillo Salvaje depende de esta última oportunidad de unirnos a todos!' WHERE `ID`=49083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초갈이 손짓하며 |cFF006EFD|Hspell:91303|h[개종]|h|r을 시전합니다!', `MaleText_loc4`='古加尔开始施展|cFF006EFD|Hspell:91303|h[变节]|h|r！', `MaleText_loc5`='丘加利招手並施放了|cFF006EFD|Hspell:91303|h[歸化]|h|r!', `MaleText_loc7`='¡Cho''gall hace señas y lanza |cFF006EFD|Hspell:91303|h[Conversión]|h|r!' WHERE `ID`=49084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 생각해 주시오, 파오리스. 데스윙은 홀의 힘을 사용하여 울둠의 비밀을 알아내고 막대한 파괴를 불러올 것이 틀림없소.', `MaleText_loc4`='希望你能重新考虑，法奥瑞斯。死亡之翼会使用节杖的力量，开启奥丹姆的秘密，制造恐怖异常的毁灭灾难。', `MaleText_loc5`='我請求你重新考慮，法歐瑞斯!死亡之翼會使用權杖的力量來解開奧丹姆之謎，並造成大規模的毀滅。', `MaleText_loc7`='Te conmino a que lo reconsideres, Phaoris. Alamuerte utilizaría el poder de los cetros para desentrañar los secretos de Uldum y desatar una gran destrucción.' WHERE `ID`=49085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 목숨을 버리고 싸워야 하오, 파오리스! 우리 종족은 이 땅을 지키기 위해 태어났소. 종족의 사명을 배신할 수는 없소.', `MaleText_loc4`='我们会战斗到死，法奥瑞斯！我们一族生来就是为了保卫这片土地。我们绝不会背叛我们的血脉传统。', `MaleText_loc5`='我們會死戰，法歐瑞斯!我們的種族是被創造來守護這片大地。我們絕不能背叛這個遺產。', `MaleText_loc7`='¡Lucharemos hasta la muerte, Phaoris! Nuestra raza fue creada para guardar esta tierra. No debemos traicionar ese legado.' WHERE `ID`=49086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 뜻을 따르겠소, 형제여. 이른 시일 내에 결정을 내릴 수 있기만을 바라겠소. 적은 기다리지 않을 것이오.', `MaleText_loc4`='我服从你的智慧，兄长。让我们祈祷决定能尽快被做出。敌人是不会等待我们的。', `MaleText_loc5`='我聽從你的智慧，兄弟。讓我們祈禱我們能很快做出決定。敵人是不會等我們的。', `MaleText_loc7`='Acato tu sabiduría, hermano. Recemos para que podamos tomar una decisión rápida. El enemigo no esperará.' WHERE `ID`=49087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이스크림 제국을 세우도록 도와주셨으니, 저의 다양하고 맛있는 혼합 아이스크림 중 하나는 꼭 맛보고 가세요!', `MaleText_loc4`='现在，你已经帮助我建立起了我的冰激凌帝国。请尽情享用我的诸多美味吧！', `MaleText_loc5`='現在既然你幫我建立了我的冰淇淋帝國，記得來嚐嚐我調配的許多好吃口味!', `MaleText_loc7`='¡Ahora que me has ayudado a establecer mi imperio del helado, saborea una de mis sabrosas recetas!' WHERE `ID`=49088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 지원을 요청하는 건가?', `MaleText_loc4`='你是来寻求帮助的？', `MaleText_loc5`='所以你來這裡尋求我們的幫助?', `MaleText_loc7`='¿Así que has venido en busca de nuestra ayuda?' WHERE `ID`=49089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기침합니다.', `MaleText_loc4`='%s咳嗽了起来。', `MaleText_loc5`='%s咳了幾聲。', `MaleText_loc7`='%s tose.' WHERE `ID`=49090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... *콜록* 난 오랫동안 살았네. 그동안 끔찍한 것들을 너무 많이 봤지.', `MaleText_loc4`='我……*咳嗽*我已经活了很长的时间，亲眼见过，亲手做过许多恐怖的事。', `MaleText_loc5`='我...*咳* 我已經活了很長一段時間了。在這段時間之中，我看過，也做過很多可怕的事情。', `MaleText_loc7`='Yo... *tose* vivo desde hace mucho tiempo. En ese periodo he visto y he hecho cosas terribles.' WHERE `ID`=49091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤잠을 설치게 하는... 그런 기억들이지.', `MaleText_loc4`='那是些让我在长夜无法入眠的事情。', `MaleText_loc5`='那些事情仍然會讓我在夜晚無法入眠。', `MaleText_loc7`='Cosas que todavía me mantienen despierto por las noches.' WHERE `ID`=49092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 내가 저지른 끔찍한 일들... 그리고 해친 자들... 난 그 모든 걸 기억한다네... 밤마다 이들과 마주하고... 후회한다네.', `MaleText_loc4`='对于我做过的那些事，我伤害过的那些人——我认识他们……我必须面对他们……带着我深深的自责。', `MaleText_loc5`='但是我所做過的這些可怕事情，和我所傷害的人...我認識他們，面對他們，而且為他們感到悔意。', `MaleText_loc7`='Pero esos actos terribles que he cometido y esa gente a la que he hecho daños... Les conozco... Les miro a la cara... y siento remordimientos por ellos.' WHERE `ID`=49093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 포세이큰... *콜록* 이들에게도 감정이란 게 있는가?', `MaleText_loc4`='但那些被遗忘者。*咳嗽*他们是怎样做的？', `MaleText_loc5`='但是被遺忘者。*咳* 他們有什麼感覺?', `MaleText_loc7`='Pero los Renegados. *tose* ¿Qué sienten?' WHERE `ID`=49094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들은 대지를 짓밟고 손 닿는 모든 것들을 파괴하지. 이들의 사악한 독 때문에 얼마나 많은 이들이 목숨을 잃었는가?', `MaleText_loc4`='他们蹂躏这片土地，摧毁他们所触及的一切。他们卑劣的毒药夺走了多少生命？', `MaleText_loc5`='他們在這片大地上肆虐，摧毀任何他們觸碰到的東西。多少生命在他們邪惡的毒藥下死去?', `MaleText_loc7`='Arrasan la tierra y destruyen todo lo que tocan. ¿Cuántas vidas se han perdido por sus viles venenos?' WHERE `ID`=49095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 많은 무고한 생명이 포세이큰 전쟁 기계 앞에 쓰러졌는가?', `MaleText_loc4`='有多少无辜者倒在被遗忘者的战争机器下？', `MaleText_loc5`='多少無辜的人在被遺忘者的戰爭機器前倒下?', `MaleText_loc7`='¿Cuántos inocentes han caído ante la maquinaria de guerra de los Renegados?' WHERE `ID`=49096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셀 수 없어... 셀 수 없을 만큼 많지... *콜록*', `MaleText_loc4`='数不清的……数不清的……*咳嗽*', `MaleText_loc5`='無數...無數的生命...*咳*', `MaleText_loc7`='Incontables... incontables vidas... *tose*' WHERE `ID`=49097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 나도 끔찍한 짓들을 저질렀어. 하지만 포세이큰을 지원하는 것만큼 끔찍한 짓은 하고 싶지 않네.', `MaleText_loc4`='是的……我做过可怕的事情，但我从不曾与被遗忘者沆瀣一气。', `MaleText_loc5`='是的...我做過可怕的事情，但是還沒可怕到協助被遺忘者。', `MaleText_loc7`='Sí... He hecho cosas terribles, pero nada sería tan terrible como ayudar a los Renegados.' WHERE `ID`=49098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직접 찾아올 용기도 없는 그 겁쟁이 오크에게 돌아가 전하게. 서리늑대 부족은 포세이큰을 지원하지 않을 거라고... 지금은 물론이고 앞으로도 그럴 일은 없을 거라고!', `MaleText_loc4`='你去告诉那个不敢来见我的软骨头兽人，霜狼氏族不会帮助被遗忘者。永远不会！', `MaleText_loc5`='你回去找那個沒骨氣，連見我都不敢的獸人，並告訴他霜狼氏族不會幫助被遺忘者。現在不會，以後也不會!', `MaleText_loc7`='Regresa junto a ese orco débil que no quiere venir a verme y dile que el clan Lobo Gélido no ayudará a los Renegados. ¡Ni ahora, ni nunca!' WHERE `ID`=49099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 썩 물러가게!', `MaleText_loc4`='滚吧！', `MaleText_loc5`='滾吧!', `MaleText_loc7`='¡VETE!' WHERE `ID`=49100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초소형 기계닭을 준비해!', `MaleText_loc4`='准备启动微型机动战鸡！', `MaleText_loc5`='準備微型機械雞!', `MaleText_loc7`='¡Prepara el micromecapollo!' WHERE `ID`=49101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 가까이에 있는데 소리까지 지를 필요는 없다고요, 호바트 박사님. 쉬!', `FemaleText_loc4`='别喊了，霍巴特，我就在这里。嘘！', `FemaleText_loc5`='不用吼那麼大聲，荷巴爾特。我人就站在這裡。真是的!', `FemaleText_loc7`='No es necesario que grites, Hobart, estoy aquí mismo. ¡Ains!' WHERE `ID`=49102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 초소형 기계닭 하나요. 이름을 너무 대충 붙인 거 아닌가요?', `FemaleText_loc4`='给你，一只“微型机动战鸡”。我一直都不明白，你是怎么想出这些怪名字的。', `FemaleText_loc5`='好了。一隻微型機械雞。真不曉得你是怎樣想出這些名字的。', `FemaleText_loc7`='Hala. Un micromecapollo. Nunca entenderé de dónde sacas esos nombres.' WHERE `ID`=49103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 심오한 뜻을 네가 어찌 알겠니, 그릴리. 그래서 넌 조수고, 난... 난 호바트 그래플해머란 말이야!', `MaleText_loc4`='你有许多事还不明白，我亲爱的格瑞里。正因为如此，你才是助手，而我……我是霍巴特·钩锤！', `MaleText_loc5`='你不懂的東西可多了，親愛的格里利。這就是為什麼你是助手，而我...我是荷巴爾特·繫錘!', `MaleText_loc7`='Hay muchas cosas que no entiendes, mi querida Greely. Por eso tú eres la ayudante y yo... ¡Yo soy Hobart Martillazos!' WHERE `ID`=49104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그릴리가 한숨을 쉬며 포기한 듯 고개를 끄덕입니다.', `FemaleText_loc4`='格瑞里叹息着，眨了眨眼。', `FemaleText_loc5`='格里利翻起白眼，嘆了一口氣。', `FemaleText_loc7`='Greely suspira y hace un gesto de fastidio.' WHERE `ID`=49105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 그래플해머 박사님.', `FemaleText_loc4`='是，钩锤博士。', `FemaleText_loc5`='是，繫錘博士。', `FemaleText_loc7`='Sí, doctor Martillazos.' WHERE `ID`=49106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 이제 초정밀 핵실험 단상에서 떨어지라고. 천천히 움직여 주면 좋겠어.', `MaleText_loc4`='太好了。现在，离开超级凹陷裂变测试平台，向后退。一定要慢。', `MaleText_loc5`='很好。現在離終極凹面可裂變測試平台遠一點。慢慢來，麻煩你。', `MaleText_loc7`='Excelente. Ahora retírate de la plataforma de prueba ultra cóncava fisionable. Lentamente, por favor.' WHERE `ID`=49107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군. 이제 극도로 불안정한 축소화 작업을 시작할 테니, 눈 크게 뜨고 지켜보라고.', `MaleText_loc4`='谢谢你。现在，你可以看着我如何稳定这种极度不稳定的微型化处理程序。', `MaleText_loc5`='謝謝。現在看我把極度不穩定的微型化過程穩定下來。', `MaleText_loc7`='Gracias. Ahora observa mientras estabilizo el altamente inestable proceso de miniaturización.' WHERE `ID`=49108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조수 그릴리가 고개를 절레절레 젓습니다.', `FemaleText_loc4`='助手摇了摇头。', `FemaleText_loc5`='助理搖了搖頭。', `FemaleText_loc7`='La asistente menea la cabeza.' WHERE `ID`=49109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사의 이윤을 갉아먹는 끔찍한 식료품 저장소 문제를 당장 해결해 주지!', `MaleText_loc4`='这个发明将会一劳永逸地解决困扰锈水财阀的食物短缺问题，带来无尽的利润！', `MaleText_loc5`='我要把食物儲藏的可怕問題轉變為污水企業聯合的金雞母!', `MaleText_loc7`='¡Voy a acabar con el terrible problema del almacenamiento de alimentos y me haré con los beneficios del Cártel Pantoque!' WHERE `ID`=49110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제 역사상 가장 위대한 고블린 땜장이로 이름을 날리게 될 거야! 그러면 아가미고블린 개발의 근무 태만 문제도 곧 잊혀지겠지?', `MaleText_loc4`='我很快就会成为前无古人，后无来者的，最伟大的地精工匠！另外，那个导致海地精产生的疏忽根本不值一提。', `MaleText_loc5`='我很快就會成為史上最受尊敬的哥布林工匠!', `MaleText_loc7`='¡Pronto me reverenciarán por ser el mayor goblin manitas de todos los tiempos! Además, ese caso de negligencia que tiene que ver con la creación de los gilgoblins no se sostiene.' WHERE `ID`=49111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스위치를 올려!', `MaleText_loc4`='打开开关！', `MaleText_loc5`='打開開關!', `MaleText_loc7`='¡Dale al botón!' WHERE `ID`=49112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그릴리가 헛기침을 합니다.', `FemaleText_loc4`='格瑞里咳嗽了一声。', `FemaleText_loc5`='格里利咳嗽不止。', `FemaleText_loc7`='Greely tose.' WHERE `ID`=49113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어, 저기, 박사님께서 조종기에 더 가까우신데요.', `FemaleText_loc4`='呃，没错，霍巴特，一切都在你的掌控之中。', `FemaleText_loc5`='呃，荷巴爾特，操控臺就在你前面。', `FemaleText_loc7`='Um. Hobart, tú estás en los controles.' WHERE `ID`=49114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래, 그릴리. 알려줘서 고마워.', `MaleText_loc4`='非常正确的回答，格瑞里。你通过了今天的突击小测验。', `MaleText_loc5`='非常正確，格里利。你通過今天的快問快答測驗了!', `MaleText_loc7`='Bastante bien. Greely. Has superado la prueba sorpresa de hoy.' WHERE `ID`=49115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 스위치를 켠다고!', `MaleText_loc4`='我我要打开开关了！', `MaleText_loc5`='我現在要打開開關了!', `MaleText_loc7`='¡Voy a darle al botón!' WHERE `ID`=49116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릴리, 느껴져? 드디어 내 성공이 손에 잡힐 듯 다가왔어!', `MaleText_loc4`='格瑞里，你看到了吗？我已经成功在握了！', `MaleText_loc5`='格里利，你感覺到了嗎?我成功的一刻即將來臨!', `MaleText_loc7`='Greely, ¿puedes sentirlo? ¡Mi gran momento está a punto de llegar!' WHERE `ID`=49117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 세계의 식료품 상점 주인이 사용료를 내고 내 기술을 쓰려고 하겠지!', `MaleText_loc4`='全世界的杂货店主都要给我利润抽成！', `MaleText_loc5`='世界各地的雜貨店老闆將付給我一部分的營收!', `MaleText_loc7`='¡Los dueños de tiendas de alimentación de todas partes tendrán que pagarme un porcentaje de sus beneficios!' WHERE `ID`=49118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내가 두 번째 스위치를 켜겠어!', `MaleText_loc4`='我要打开第二个开关了！', `MaleText_loc5`='我要打開第二個開關了!', `MaleText_loc7`='¡Voy a darle al segundo botón!' WHERE `ID`=49119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 뭔가 이상해!', `MaleText_loc4`='等等……有问题！', `MaleText_loc5`='等等...有點問題!', `MaleText_loc7`='Espera... ¡Algo va mal!' WHERE `ID`=49120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇죠? 호바트 박사님, 초소형 기계닭이 불안정해졌어요. 커지고 있다고요!', `FemaleText_loc4`='你在想什么？霍巴特，这只微型机动战鸡很不稳定。它在剧烈膨胀！', `FemaleText_loc5`='你覺得呢?荷巴爾特，微型機械雞更不穩定了，它在變大!', `FemaleText_loc7`='¿Eso crees? Hobart, el micromecapollo se está desestabilizando. ¡Está creciendo!' WHERE `ID`=49121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아... 안다고! 비상 정지 단추는 어딨지? 비상 정지 단추는?!', `MaleText_loc4`='我知道……我知道！超控开关？超控开关在哪儿？', `MaleText_loc5`='我知道...我知道!撤銷開關在哪?撤銷開關呢?', `MaleText_loc7`='¡Lo sé... lo sé! ¿Cómo se anula? ¡¿Dónde está el botón de control manual?!' WHERE `ID`=49122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오른쪽 끝에요! 서두르세요, 박사님! 폭발하려고 해요!', `FemaleText_loc4`='就是最右边的那个！赶快，霍巴特！它就要爆炸啦！', `FemaleText_loc5`='最右邊那個!快點，荷巴爾特!要爆蛋了!', `FemaleText_loc7`='¡Es el que está más a la derecha! ¡Date prisa, Hobart! ¡Va a explotar!' WHERE `ID`=49123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밑져야 본전이니, 한번 해 보자! 언제나 널 사랑했어, 그릴리 양.', `MaleText_loc4`='我要按啦，格瑞里，我一直都是爱你的！', `MaleText_loc5`='啊，管他去死!我一直都很愛你，格里利!', `MaleText_loc7`='Bueno, no tengo nada que perder. ¡Siempre te he amado, Greely!' WHERE `ID`=49124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 비상 정지 단추를 누를게!', `MaleText_loc4`='按下超控开关！', `MaleText_loc5`='現在就打開撤銷開關吧!', `MaleText_loc7`='¡Pasando al control manual!' WHERE `ID`=49125;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐죠?!!!', `FemaleText_loc4`='什么？！！！', `FemaleText_loc5`='什麼?!!!', `FemaleText_loc7`='¡¡¡¿QUÉ?!!!' WHERE `ID`=49126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 우리 아직 살아 있는 건가?', `MaleText_loc4`='我们还活着吗？', `MaleText_loc5`='我們還活著嗎?', `MaleText_loc7`='¿Seguimos vivos?' WHERE `ID`=49127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애 많이 쓰셨지만, 안타깝게도 아직 살아 있네요, 그래플해머 박사님.', `FemaleText_loc4`='我们还活着，钩锤博士，全靠你的努力。', `FemaleText_loc5`='對，我們還活著，繫錘博士。不過你差點就成功了。', `FemaleText_loc7`='Seguimos vivos, doctor Martillazos, a pesar de todos tus esfuerzos.' WHERE `ID`=49128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 그렇겠지, 친애하는 그릴리 양. 그리고 저길 보라고. 초소형 기계닭이 이제 완전히 안정화된 것 같아!', `MaleText_loc4`='当然，我亲爱的格瑞里。看看那个。微型机动战鸡的稳定性堪称完美！', `MaleText_loc5`='我們當然還活著，親愛的。而且看看那裡。微型機械雞的穩定化看起來完全地成功了!', `MaleText_loc7`='Bueno, claro que lo estamos, mi querida Greely. Y mira esto. ¡La estabilización del micromecapollo ha resultado ser un completo éxito!' WHERE `ID`=49129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호바트가 입을 떡 벌립니다.', `MaleText_loc4`='霍巴特的下巴撞到地上。', `MaleText_loc5`='荷巴爾特的下巴掉到地上。', `MaleText_loc7`='La mandíbula de Hobart golpea el suelo.' WHERE `ID`=49130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='박사님 얼굴에 있는 게 알인가요?', `FemaleText_loc4`='你脸上那是鸡蛋吗？', `FemaleText_loc5`='你臉上是雞蛋嗎?', `FemaleText_loc7`='¿Es huevo eso que tienes en la cara?' WHERE `ID`=49131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 ''언제나 절 사랑했다''는 말씀은 대체 뭔가요, 그래플해머 님?', `FemaleText_loc4`='好了，告诉我，“你一直都是爱我的”是什么意思，钩锤？', `FemaleText_loc5`='好了，剛剛那句「一直都很愛我」是怎麼回事啊，繫錘?', `FemaleText_loc7`='Bueno, ¿qué es eso de que "siempre me has amado", Martillazos?' WHERE `ID`=49132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 무슨 말을 하는 건지 털끝만치도 모르겠어, 그릴리 양.', `MaleText_loc4`='我根本不明白你在说什么，格瑞里小姐。', `MaleText_loc5`='我完全不懂你在說什麼，格里利小姐。', `MaleText_loc7`='No tengo ni la más mínima idea de lo que estás diciendo, señorita Greely.' WHERE `ID`=49133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 마찬가지예요, 박사님.', `FemaleText_loc4`='在这一点上，我们可以达成共识，博士。', `FemaleText_loc5`='這點我們倆都同意，博士。', `FemaleText_loc7`='Los dos estamos de acuerdo en eso, doctor.' WHERE `ID`=49134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 안녕하세요? 호바트 박사님과 저는 요즘 카자마이트가 바닥났을 때를 대비해서 아주 혁신적인 신제품을 만들고 있어요.$B$B사실 저기 광산 안에도 카자마이트가 얼마 남지 않았잖아요? 그리고 안타깝지만 카자마이트가 떨어지면 카자콜라도 더는 없을 테고요.', `FemaleText_loc4`='嗨，你还好吗，老板？霍巴特和我正在努力确保当卡亚矿石资源枯竭时，你还会有足够的库存产品。$B$B现在矿脉中的卡亚矿石只有这么多了，如果它们都被开采干净，我害怕卡亚可乐也就没有了。', `FemaleText_loc5`='嘿，最近過得怎樣啊，老大?荷巴爾特和我正在研究幾樣東西，讓你可以在將來卡迦邁礦挖光的時候還有充分的備用產品。$B$B礦坑裡面的礦藏就剩下那麼多了，等它全部挖光了，恐怕卡迦可樂也會跟著一起完蛋。', `FemaleText_loc7`='Eh. ¿Qué tal te va, $gjefe:jefa;? Hobart y yo estamos trabajando en algunas cosas que te asegurarán un buen suministro de productos fenomenales para cuando se termine la kaja''mita.$B$BMe temo que no queda mucho en las minas, y cuando se acabe, la Kaja''Cola desaparecerá con ella.' WHERE `ID`=49135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반가워, $n!$B$B내 천재적인 두뇌로 카자로 무역회사를 위해 만들어낸 제품들을 자네가 잊지 말아 줬으면 해.$B$B너무 많아서 전부 예를 들 수는 없겠지만 몇 가지 살펴보자면, 카자콜라, 꼬꼬댁 변신장치, 상자 마을, 떡대놀이용 정교한 모자, 케잔 무역 회사 고급 자동훈련기, 놀라운 G선, 절대 바람이 빠지지 않는 물놀이용 조랑말, 커다란 녀석들, 로봇전사 NX-01, 아가미고블린 등이 있지. 아, 마지막 아가미고블린은 취소할게. 변호사 말을 들어보니 아가미고블린 개발에는 일절 참여하지 않은 걸로 하라더군.$B$B어쨌든, 지금도 자네가 재미있어할 만한 물건을 몇 가지 만들고 있어. 여기 초소형 기계닭하고, 가칭 9번 실험체라고 하는 녀석이지.', `MaleText_loc4`='很高兴见到你，$n！$B$B我刚想问你是否对我带到卡亚罗贸易公司的这些产品感到满意？$B$B包括但不限于：卡亚可乐、变鸡器、胶囊盒、巨怪愚行天才帽、卡亚罗全能训练机豪华版、神奇地精射线、永不漏气的小马泳圈、大炸弹、NX-01型自动化战士和海地精。别对最后一个有任何想法。我只是奉命办事，与我无关。$B$B不管怎样，我现在还在研究几样新鲜玩意，你也许会有兴趣——比如微型机动战鸡和一个被我命名为九号实验品的小东西。', `MaleText_loc5`='很高興見到你，$n!$B$B我只是要確認一下，你對我帶到卡亞羅貿易公司的所有天才產品應該很滿意吧?$B$B這些包括，但不限於卡迦可樂、變形器、盒中鎮、我的蠢蛋絕妙偽裝帽、卡亞羅貿易公司訓練機器人豪華版、超級哥布林射線、絕不洩氣的小馬泳圈、大炸彈、自動戰士NX-01和吉爾哥布林。噢刪掉最後提到的那個。特別提醒一下，我跟他們一點關係都沒有。$B$B不管怎樣，我正在這裡製造一些其他你應該會有興趣的東西，例如微型機械雞和我稱為實驗體九號的東西。', `MaleText_loc7`='¡Me alegro de verte, $n!$B$BSolo quiero asegurarme de que sabes apreciar todos los productos que mi ingenio ha proporcionado a la sociedad comercial de Kajaro.$B$BEsto incluye, la Kaja''Cola, el Pollotizador, la Ciudad de Bolsillo, el almete de estupidez de cateto ingenioso, el Entrenatrón Deluxe SCK, los rayos goblins alucinantes, los ponis flotadores que nunca se desinflan, los Grandes, la Guerreromática NX-01 y los gilgoblins. Aunque esto último no fue un gran éxito. Siguiendo el consejo de mi abogado, afirmo que no tuve nada que ver con ellos.$B$BSea como sea, estoy trabajando en algunas cosas más que creo que podrían interesarte, como el micromecapollo y algo que yo llamo el Sujeto Nueve.' WHERE `ID`=49136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안색이 안 좋아 보이는군, 친구. 뭔가 이상해 보이는데.', `MaleText_loc4`='你看起来不太好，朋友。你肯定是出了什么问题。', `MaleText_loc5`='你看起來怪怪的，朋友。你身上有些不對勁。', `MaleText_loc7`='No tienes buen aspecto, colega. Te pasa algo.' WHERE `ID`=49137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 친구, 우리가 이걸 무사히 빠져나갈 수 있겠어요?', `MaleText_loc4`='嗨，$g朋友:姑娘;我们来搞定这个？', `MaleText_loc5`='嘿，$g先生:女士;，我們一定可以平安度過這一切，好嗎?', `MaleText_loc7`='Hey, $gseñor:señora;, ¿vamos a salir de esta de una pieza?' WHERE `ID`=49138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무래도 이게 끝인 것 같네요. 하지만 용기를 좀 내자고요.', `FemaleText_loc4`='看样子，这就是最后了，如果你有足够的胆量，那我也就有，$n。', `FemaleText_loc5`='看來這就是終點了，$n，但是我會跟你一樣勇敢的。', `FemaleText_loc7`='Parece que esto es el final, pero seré valiente si tú lo eres, $n.' WHERE `ID`=49139;
