UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<고버는 강한 척하고 있지만, 가슴 속 깊이 겁을 먹고 있다는 사실을 알 수 있습니다.>', `MaleText_loc4`='<大胖看起来很凶悍，但可以确认，他心里是害怕了。>', `MaleText_loc5`='<古柏看起來很勇敢，但是你可以看出他內心其實非常害怕。>', `MaleText_loc7`='<Gargajo se hace el duro, pero tú sabes que en el fondo está asustado.>' WHERE `ID`=49141;
