UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수라도 마실 수 있을 것 같군!', `MaleText_loc4`='我觉得自己能喝下一整座湖！', `MaleText_loc5`='我現在可以喝掉一整座湖的水!', `MaleText_loc7`='¡Creo que podría beberme un lago entero!', `FemaleText_loc1`='호수라도 마실 수 있을 것 같군!', `FemaleText_loc4`='我觉得自己能喝下一整座湖！', `FemaleText_loc5`='我現在可以喝掉一整座湖的水!', `FemaleText_loc7`='¡Creo que podría beberme un lago entero!' WHERE `ID`=49144;
