UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까!$b$b이 지역은 많은 변화가 있었습니다. 제가 다른 지역으로 보내드리지요.', `MaleText_loc4`='嘿伙计！$b$b这地方经历了许多改变。可以通过传送去往别处。', `MaleText_loc5`='嘿老兄!$b$b這個地方有很多的變動。傳送門會把你送到別的地方。', `MaleText_loc7`='¡Eh, colega!$b$bEh''ta zona ha sufri''o un montón de cambios. El teletranh''poh''tador te llevará a otro sitio.' WHERE `ID`=49149;
