UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000|Hspell:74040|h[휘몰아치는 불길]|h|r을 사용해 황혼의 망치단을 무찌르십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t使用|cFFFF0000|Hspell:74040|h[噬体烈焰]|h|r摧毁暮光之锤！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t使用|cFFFF0000|Hspell:74040|h[侵噬烈焰]|h|r來消滅暮光之錘!', `MaleText_loc7`='|TInterfaceIconsability_mage_firestarter.blp:20|t¡Utiliza |cFFFF0000|Hspell:74040|h[Trago de llamas]|h|r para destruir al Martillo Crepuscular!' WHERE `ID`=49153;
