UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이! 저리 꺼져.', `MaleText_loc4`='喂！走开！', `MaleText_loc5`='喂!滾一邊去，嗯?', `MaleText_loc7`='¡Eh! Lárgate, ¿quieres?' WHERE `ID`=49158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더럽고 냄새나는 와일드해머 놈. 이 드워프들이 널 드워프로 취급하지도 않는 거 알지? 그러면 넌 뭘까? 노움?', `MaleText_loc4`='臭气熏天的脏蛮锤。这些矮人只把别人当作半个矮人，不是吗？你又是什么？一个侏儒？', `MaleText_loc5`='又髒又臭的蠻錘。你知道這些矮人只把你當成半個矮人，對吧?所以你該算是什麼呢?地精嗎?', `MaleText_loc7`='Sucios y apestosos Martillo Salvaje. Tú sabes que esos enanos te consideran solo medio enano, ¿verdad? ¿En qué te convierte eso? ¿En un gnomo?', `FemaleText_loc1`='더럽고 냄새나는 와일드해머 놈. 이 드워프들이 널 드워프로 취급하지도 않는 거 알지? 그러면 넌 뭘까? 노움?', `FemaleText_loc4`='臭气熏天的脏蛮锤。这些矮人只把别人当作半个矮人，不是吗？你又是什么？一个侏儒？', `FemaleText_loc5`='又髒又臭的蠻錘。你知道這些矮人只把你當成半個矮人，對吧?所以你該算是什麼呢?地精嗎?', `FemaleText_loc7`='Sucios y apestosos Martillo Salvaje. Tú sabes que esos enanos te consideran solo medio enano, ¿verdad? ¿En qué te convierte eso? ¿En un gnomo?' WHERE `ID`=49159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?! 널 잘게 조각내 노움처럼 만들어주지!', `MaleText_loc4`='你说什么，萨莉？！我们之中像侏儒的只有你——等我把你砍成碎块之后，你就更像了！', `MaleText_loc5`='你說什麼，莎莉?!我們這群人當中唯一看起來像地精的只有你...等我把你切成碎片!', `MaleText_loc7`='¡¿Qué has dicho, Sally?! ¡De los dos el único que se parece a un gnomo eres tú, sobre todo después de que yo te corte en trocitos diminutos!' WHERE `ID`=49160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 덤벼, 애송아! 덤비라고!', `MaleText_loc4`='来吧，南希！我们走！', `MaleText_loc5`='來啊，南茜!快點啊!', `MaleText_loc7`='¡Entonces, venga, Nancy! ¡Vamos!' WHERE `ID`=49161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 난 바빠. 이럴 시간 있으면 포세이큰 점액을 찾아 목욕이나 하라고. 알겠어?', `MaleText_loc4`='我很忙，小子。为什么你不去找一池子被遗忘者的粘液，好好给自己洗个澡，嗯？', `MaleText_loc5`='我很忙，孩子。你怎麼不去找些被遺忘者肉醬然後洗個澡，嗯?', `MaleText_loc7`='Estoy ocupado, $gmuchacho:muchacha;. ¿Por qué no vas a buscar algo de baba Renegada y te das un baño, ¿eh?' WHERE `ID`=49162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실이었군. 네가 엄청난 겁쟁이란 소문은 안 믿으려 했는데, 이걸로 확실해졌어.', `MaleText_loc4`='那么，我猜这是真的了。我一直都不愿意相信，你竟然真的是个一肚子大便的白毛妖怪。但现在，我只能相信了。', `MaleText_loc5`='所以是真的了。我本來不想去相信你是個黃肚子，只會舔雪的傢伙，但現在看起來是無庸置疑的了。', `MaleText_loc7`='Entonces supongo que es cierto. No quería creer que fueses una rata cobarde, pero ahora no me cabe duda alguna.', `FemaleText_loc1`='사실이었군. 네가 엄청난 겁쟁이란 소문은 안 믿으려 했는데, 이걸로 확실해졌어.', `FemaleText_loc4`='那么，我猜这是真的了。我一直都不愿意相信，你竟然真的是个一肚子大便的白毛妖怪。但现在，我只能相信了。', `FemaleText_loc5`='所以是真的了。我本來不想去相信你是個黃肚子，只會舔雪的傢伙，但現在看起來是無庸置疑的了。', `FemaleText_loc7`='Entonces supongo que es cierto. No quería creer que fueses una rata cobarde, pero ahora no me cabe duda alguna.' WHERE `ID`=49163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 겁쟁이라고? 진짜 "겁쟁이"가 뭘 할 수 있는지 보여주마!', `MaleText_loc4`='你叫我什么？好吧，那我就让你看看“白毛妖怪”能干些什么！', `MaleText_loc5`='你說我是什麼?我要讓你看看「只會舔雪的傢伙」有什麼能耐!', `MaleText_loc7`='¿Qué me has llamado? ¡Voy a enseñarte lo que puede hacer un "chupa nieve"!' WHERE `ID`=49164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크러드비어드! 이 못생기고 콩알만 한 꼬마 녀석. 너처럼 콩알만 한 계집애도 죽음의 기사가 될 수 있는지 몰랐군. 리치 왕이 널 만들 때 수 채우려고 나쁜 재료도 사용한 거 아냐? 나라면 쓰레기통에 던져버렸을 텐데 말이야.', `MaleText_loc4`='渣胡？你只是个丑陋的小女孩。我还不知道他们会让小女孩也能成为死亡骑士。难道巫妖王这么着急扩充队伍吗？我要让你明白，你到底是个什么货色。', `MaleText_loc5`='渣鬍子?你只是個醜陋的小女孩。我甚至不知道他們會允許小女孩成為死亡騎士。難道巫妖王在製造你的時候是為了要用掉他的配額嗎?要換成是我就把你丟回去。', `MaleText_loc7`='¿Barbasucia? Eres una niñita muy fea. No sabía que dejaran que las niñitas se convirtieran en caballeros de la muerte. ¿Acaso el Rey Exánime estaba intentando alcanzar la cuota cuando te hizo o qué? Yo te habría rechazado.', `FemaleText_loc1`='크러드비어드! 이 못생기고 콩알만 한 꼬마 녀석. 너처럼 콩알만 한 계집애도 죽음의 기사가 될 수 있는지 몰랐군. 리치 왕이 널 만들 때 수 채우려고 나쁜 재료도 사용한 거 아냐? 나라면 쓰레기통에 던져버렸을 텐데 말이야.', `FemaleText_loc4`='渣胡？你只是个丑陋的小女孩。我还不知道他们会让小女孩也能成为死亡骑士。难道巫妖王这么着急扩充队伍吗？我要让你明白，你到底是个什么货色。', `FemaleText_loc5`='渣鬍子?你只是個醜陋的小女孩。我甚至不知道他們會允許小女孩成為死亡騎士。難道巫妖王在製造你的時候是為了要用掉他的配額嗎?要換成是我就把你丟回去。', `FemaleText_loc7`='¿Barbasucia? Eres una niñita muy fea. No sabía que dejaran que las niñitas se convirtieran en caballeros de la muerte. ¿Acaso el Rey Exánime estaba intentando alcanzar la cuota cuando te hizo o qué? Yo te habría rechazado.' WHERE `ID`=49165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴에 주먹을 날리기 전에 썩 꺼져!', `MaleText_loc4`='离开这里，否则我就只能狠狠教训你了！', `MaleText_loc5`='離開，不然我就把你的臉打歪!', `MaleText_loc7`='¡Vete o me veré obligado a pegarte en la cara!' WHERE `ID`=49166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 내게 시비를 걸다니... 생각보다 재미있겠군.', `MaleText_loc4`='哦，这一定会乐趣十足。', `MaleText_loc5`='噢，我要放肆地享受一下，雖然這不太應該。', `MaleText_loc7`='Oh, voy a disfrutar de esto mucho más de lo que debería.' WHERE `ID`=49167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 끝장내고 그 척추를 꺾어주마!', `MaleText_loc4`='我要让你明白，该把你的脑袋摆在什么地方！', `MaleText_loc5`='等我搞定你，你的頭會很穩地卡在你的雙腿之中!', `MaleText_loc7`='¡Cuando termine contigo, tu cabeza estará situada firmemente entre tus nalgas!' WHERE `ID`=49168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크아아! 너희 악어 어떻게 죽였지?!', `MaleText_loc4`='啊！你是怎么把鳄鱼干掉的？！', `MaleText_loc5`='嘎啊啊!你為什麼殺死鱷魚?!', `MaleText_loc7`='¡GAAAH! ¡¿Cómo tú matar crocolisco?!' WHERE `ID`=49169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우 똑똑하다! 너희 안 볼 때 오우가 보물 훔쳤다!', `MaleText_loc4`='奥弗很聪明！奥弗在你不注意的时候拿走了财宝！', `MaleText_loc5`='奧各聰明!奧各已經趁你不注意偷走寶藏!', `MaleText_loc7`='¡Augh listo! ¡Augh robar tesoro mientras tú no mirar!' WHERE `ID`=49170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우가 최고다! 오예!', `MaleText_loc4`='奥弗是老板了！哦耶！', `MaleText_loc5`='奧各是老大!喔耶!', `MaleText_loc7`='¡Augh ser el jefe! ¡Sí, señor!' WHERE `ID`=49171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 나빠?! 오우가 나빠!! 움!', `MaleText_loc4`='谁够坏！奥弗够坏！！呃！', `MaleText_loc5`='誰最壞?!奧各最壞!嗯!', `MaleText_loc7`='¡¿Quién malo?! ¡¡Augh malo!! ¡Ugn!' WHERE `ID`=49172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우가 너희 보물 훔쳤다. 움 움 움움!', `MaleText_loc4`='奥弗拿走了你的财宝。呃，呃，呃！', `MaleText_loc5`='奧各偷走你的寶藏!嗯嗯，嗯哼!', `MaleText_loc7`='Augh robar tu tesoro. ¡Uhn uhn uhnnn!' WHERE `ID`=49173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네? 뭘 원하시는데요?', `FemaleText_loc4`='什么？你想要什么？', `FemaleText_loc5`='嗯?你要幹嘛?', `FemaleText_loc7`='¿Sí? ¿Qué quieres?' WHERE `ID`=49174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 사람과는 말하지 않겠어요!', `FemaleText_loc4`='我不和废物说话！', `FemaleText_loc5`='我不跟$g垃圾:廢物;講話!', `FemaleText_loc7`='Yo no hablo con basura como tú.' WHERE `ID`=49175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 제 취향이 아니에요.', `FemaleText_loc4`='你和我不是一伙儿的，甜心。', `FemaleText_loc5`='親愛的，你跟我是不同等級的。', `FemaleText_loc7`='No estás a mi altura, encanto.' WHERE `ID`=49176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='학교 다닐 때도 당신하고는 말 한마디 한 적이 없는 것 같은데, 이제 와서 시작할 생각은 없네요.', `FemaleText_loc4`='我没有劝你回学校，现在我也不打算这么干。', `FemaleText_loc5`='以前我在學校就不跟你講話了，我相信現在也還是一樣。', `FemaleText_loc7`='No te hablaba en el colegio y te aseguro que no voy a empezar ahora.' WHERE `ID`=49177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어... 아주 재미있는 "의상"을 입고 있군요.', `FemaleText_loc4`='真有趣……我说的是你穿的这身“行头”。', `FemaleText_loc5`='你穿的...「衣服」還真有趣。', `FemaleText_loc7`='Es interesante ese... "modelito" que llevas puesto.' WHERE `ID`=49178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 한 잔 더 주세요. 빨리 가서 가져오시라고요.', `FemaleText_loc4`='是的，我要再来一杯。快一点。', `FemaleText_loc5`='對，再來一杯。動作快一點。', `FemaleText_loc7`='Sí. Me encantaría otra copa. Ve a por una y date prisa.' WHERE `ID`=49179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무역왕이 주최한 파티라고요! 초대받은 사람만 들어올 수 있는 파티!', `FemaleText_loc4`='这是贸易大王的聚会，甜心。只有受邀请的人才能参加！', `FemaleText_loc5`='甜心，這是貿易親王的派對。要有邀請函才可以!', `FemaleText_loc7`='Esta es la fiesta del Príncipe mercante, cielo. ¡Solo se entra con invitación!' WHERE `ID`=49180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이라고;라고; 하셨나요? 충고 하나 할게요. 여기 있다가 무역왕에게 들키지 마시라고요. 당신이 그 자리를 노리고 있다는 사실을 아니까요.$B$B다들 알고 있고 말고요.', `FemaleText_loc4`='$n，是你吗？送你一句话：不要让贸易大王抓住你。他知道你在盯着他的位子。$B$B所有人都知道。', `FemaleText_loc5`='你叫$n，對吧?給你個建議:別讓貿易親王在這邊逮到你。他知道你想要做掉他。$B$B大家都知道。', `FemaleText_loc7`='$n, ¿verdad? Un consejo: no permitas que el Príncipe mercante te vea por aquí. Sabe que quieres su puesto.$B$BTodo el mundo lo sabe.' WHERE `ID`=49181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='떡대 아냐?! 난 야만스럽게 주먹이나 쓰는 사람과는 말을 나누지 않아요. 어딜 감히!', `FemaleText_loc4`='蠢货？！我可不和如此无礼的人说话。你怎么敢这样！', `FemaleText_loc5`='什麼蠢蛋?!我不跟野蠻人講話!大膽!', `FemaleText_loc7`='¡¿Un cateto?! Yo no hablo con brutos. ¡Cómo te atreves!' WHERE `ID`=49182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 사람을 요새 뭐라고 부르지요? 떡대? 밥통고블린?$B$B짜증나서 두고 볼 수가 없네요. 당장 꺼져요.', `FemaleText_loc4`='我们应该管你这种家伙叫什么？蛮子？巨怪？$B$B我可受不了你这种人。赶快离开这里。', `FemaleText_loc5`='現在大家都把你們叫什麼?蠻卒?大哥布林?$B$B我搞不清楚。快滾吧。', `FemaleText_loc7`='¿Cómo los llamamos hoy en día? ¿Brutos? ¿Hobgolins?$B$BNo puedo soportarlo. Largo de aquí.' WHERE `ID`=49183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몸집도 크고 아주 튼튼한 사람이군요. 하지만 목욕 좀 하셔야겠어요. 가서 수영장에 뛰어들라고요!', `FemaleText_loc4`='你又大又强壮。但你需要好好洗个澡。赶快跳到池子里去吧。', `FemaleText_loc5`='你又大又壯，但是你需要洗個澡。跳到水池裡面。', `FemaleText_loc7`='Eres grande y fuerte. Pero necesitas darte un baño. Salta a la piscina.' WHERE `ID`=49184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 당신과는 얘기할 생각이 없어요!', `FemaleText_loc4`='哦，不，别和我说话！', `FemaleText_loc5`='哦，不，你不要只跟我講話!', `FemaleText_loc7`='¡Oh, no! ¡Te has atrevido a hablar conmigo!' WHERE `ID`=49185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 무슨 냄새죠? 아, 당신 냄새군요.$B$B저리 비켜요!', `FemaleText_loc4`='这里是什么气味？哦，是你啊。$B$B快给我躲远点！', `FemaleText_loc5`='什麼味道?哦，一定是你。$B$B走開!', `FemaleText_loc7`='¿A qué huele por aquí? Oh, eres tú.$B$B¡Lárgate!' WHERE `ID`=49186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이름이 뭐지요?$B$B당신 같은 떡대가 말을 할 수 없다는 게 참 다행이에요. 말을 할 수 있었다면, 아마 전 무역왕에게 당신이 얼마나 절 귀찮게 하는지 일러야 했을 테니까요.$B$B자, 비켜요!', `FemaleText_loc4`='你的名字叫什么？$B$B也许你这种蛮子还是当个哑巴比较好。否则我就只能向贸易大王投诉，告诉他你是多么令我讨厌。$B$B现在，离我远一点！', `FemaleText_loc5`='你叫什麼名字?$B$B還好你們這些蠻卒不會講話，否則我一定要告訴貿易親王你是怎樣騷擾我的。$B$B快走開!', `FemaleText_loc7`='¿Cómo te llamas?$B$BSupongo que está bien que los brutos no puedan hablar. De lo contrario, tendría que contarle al príncipe mercante que me habías hecho enfadar.$B$B¡Ahora fuera!' WHERE `ID`=49187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 한 번만 더 건드리면 언더마인으로 보내버릴 거예요!', `FemaleText_loc4`='再碰我一下，我就让他们送你去安德麦！', `FemaleText_loc5`='再碰我一下，我就叫人把你送去幽坑城!', `FemaleText_loc7`='¡Tócame una vez más y te aseguro que haré que te envíen a Minahonda!' WHERE `ID`=49188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 당신 정말 끔찍하군요! 왜 나한테 집적대는 건 항상 못생긴 사람뿐인 거지?!', `FemaleText_loc4`='哦，你可真让人讨厌！为什么来找我的总是你这种丑家伙？！', `FemaleText_loc5`='哦，你好噁心啊!為什麼來找我搭訕的都是長得醜的?!', `FemaleText_loc7`='Oh, ¡eres repugnante! ¡¿Por qué será que siempre son los feos los que intentan echarme la caña?!' WHERE `ID`=49189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어째 이거 느낌이 좋지 않아. 이제 무슨 수를 써서든 이 섬에서 벗어나는 게 현명할 것 같다고.$B$B난 무역왕의 상자 마을에 들어갈 수 있는지 확인해 봐야겠어.', `MaleText_loc4`='我有一种非常糟糕的感觉，$n。我觉得，你现在最聪明的选择就是想尽一切办法离开这座岛。$B$B让我看看能不能进入贸易大王的胶囊镇。', `MaleText_loc5`='我對這件事感覺非常不妙，$n。我覺得現在最聰明的作法是盡一切可能離開這座島。$B$B我想看看我能不能進入貿易親王的盒中鎮。', `MaleText_loc7`='Tengo un mal presentimiento sobre esto, $n. Creo que ahora lo más inteligente es que te largues de esta isla como puedas.$B$BYo veré si puedo llegar a la Ciudad de Bolsillo del Príncipe mercante.' WHERE `ID`=49190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산산조각을 내버리세요, 대장님!', `MaleText_loc4`='把他们轰成碎片，老板！', `MaleText_loc5`='把他們炸成碎片啊，老闆!', `MaleText_loc7`='¡Hazlos pedazos, $gjefe:jefa;!' WHERE `ID`=49191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되셨으면 좋겠네요! 이 블러드 엘프 배에 상상을 초월하는 고가의 최고급 고블린 부품을 써서 성능을 올렸거든요... 안타깝게도 큰 변화는 없었지만요. 뭐, 그래도 최선을 다할 거예요.', `MaleText_loc4`='希望你已经准备好了！我已经改装好了这艘血精灵船。用的都是金币能买到的最好的地精零件……也许效果还不是很好，但我会竭尽全力的。', `MaleText_loc5`='希望你已經準備好了!我已經用最棒最貴的哥布林配件來裝配這艘血精靈的船了。很遺憾，沒提升多少性能，但是能好一分是一分。', `MaleText_loc7`='¡Espero que estés $glisto:lista;! He tuneado este barco elfo de sangre con las mejores piezas goblin que el dinero podía comprar... Que no es decir mucho, la verdad, pero me apaño con lo que puedo conseguir.', `FemaleText_loc1`='준비되셨으면 좋겠네요! 이 블러드 엘프 배에 상상을 초월하는 고가의 최고급 고블린 부품을 써서 성능을 올렸거든요... 안타깝게도 큰 변화는 없었지만요. 뭐, 그래도 최선을 다할 거예요.', `FemaleText_loc4`='希望你已经准备好了！我已经改装好了这艘血精灵船。用的都是金币能买到的最好的地精零件……也许效果还不是很好，但我会竭尽全力的。', `FemaleText_loc5`='希望你已經準備好了!我已經用最棒最貴的哥布林配件來裝配這艘血精靈的船了。很遺憾，沒提升多少性能，但是能好一分是一分。', `FemaleText_loc7`='¡Espero que estés $glisto:lista;! He tuneado este barco elfo de sangre con las mejores piezas goblin que el dinero podía comprar... Que no es decir mucho, la verdad, pero me apaño con lo que puedo conseguir.' WHERE `ID`=49192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주가 곧 시작됩니다!', `MaleText_loc4`='比赛就要开始了！', `MaleText_loc5`='比賽就要開始了!', `MaleText_loc7`='¡La carrera está a punto de empezar!', `FemaleText_loc1`='경주가 곧 시작됩니다!', `FemaleText_loc4`='比赛就要开始了！', `FemaleText_loc5`='比賽就要開始了!', `FemaleText_loc7`='¡La carrera está a punto de empezar!' WHERE `ID`=49193;
