UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF00FF00출발!|r', `MaleText_loc4`='|cFF00FF00出发|r', `MaleText_loc5`='|cFF00FF00開始!|r', `MaleText_loc7`='|cFF00FF00¡Ya!|r', `FemaleText_loc1`='|cFF00FF00출발!|r', `FemaleText_loc4`='|cFF00FF00出发|r', `FemaleText_loc5`='|cFF00FF00開始!|r', `FemaleText_loc7`='|cFF00FF00¡Ya!|r' WHERE `ID`=49197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B$G아빠:엄마;...?', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B$G爸爸:妈妈;……？', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B$G爸爸:媽媽;...?', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$b$b$G¿Papá:Mamá;...?' WHERE `ID`=49198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 좋은 날일세, 파이어비어드. 와일드해머 부족은 영원히 하나가 될 게야!', `MaleText_loc4`='焰须，这是个大日子。蛮锤的团结不可阻挡！', `MaleText_loc5`='重要的一天，火鬍。蠻錘是勢不可當的!', `MaleText_loc7`='Un gran día, Barbafuego. ¡Los Martillo Salvaje unidos jamás serán vencidos!' WHERE `ID`=49199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 그렇게 될 걸세. 자, 결혼 선물을 받아 주게.', `MaleText_loc4`='不必怀疑。给你，请接受我的结婚礼物。', `MaleText_loc5`='從沒懷疑過這一點。來，讓我給你我的結婚禮物。', `MaleText_loc7`='No lo dudes. Toma, permíteme darte mi regalo de boda.' WHERE `ID`=49200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사랑하는 그리핀, 스카이리의 알일세. 이 알만 살아남았지. 부디 이 알을 잘 돌보고 존중해 주게. 스카이리의 새끼는 자네 것일세.', `MaleText_loc4`='这是我的狮鹫斯卡雷唯一留存下来的蛋。请尊重它，爱护它。斯卡雷的孩子将成为你的伙伴。', `MaleText_loc5`='我死去的獅鷲獸史蓋瑞僅存的蛋。用榮耀和細心照料它。它所生的孩子將屬於你。', `MaleText_loc7`='El único huevo superviviente de mi difunto grifo, Cielo''ree. Hónralo y cuida de él; su cría es tuya.' WHERE `ID`=49201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어허, 이 일에 대해 왈가왈부하지 말게. 알은 자네 것일세. 내가 이 결합에 얼마나 큰 의미를 두고 있는지 자네가 알아주길 바라네.', `MaleText_loc4`='我不想听到这样的话。这颗蛋是你的。它代表了我对于我们之间盟约的忠诚。', `MaleText_loc5`='我不想再多聽一個字。這顆蛋是你的。我要你看看我對這樣的結合願意做出多大的付出。', `MaleText_loc7`='No quiero oír ni una palabra. El huevo es tuyo. Quiero que seas consciente de lo comprometido que estoy con esta unión.' WHERE `ID`=49202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 와일드해머에게 얼라이언스가 얼마나 큰 의미를 두고 있는지도 말일세!', `MaleText_loc4`='而如何效忠于联盟是蛮锤的事情！', `MaleText_loc5`='以及聯盟有多願意為了蠻錘而付出!', `MaleText_loc7`='¡Y lo comprometida que está la Alianza con la causa de los Martillo Salvaje!' WHERE `ID`=49203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저길 보게. $n|1이;가; 신부를 인도해 식장으로 들어오는군!', `MaleText_loc4`='看啊，$n来了，还送来了你的新娘！', `MaleText_loc5`='啊，你看。$n來了，陪伴著你的新娘!', `MaleText_loc7`='Ah, mira. ¡Ahí viene $n acompañando a tu novia!' WHERE `ID`=49204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 말대로 되길 바라네, 쿠르드란. 오랜 친구여.', `MaleText_loc4`='希望你是对的，库德兰老朋友。', `MaleText_loc5`='我希望你是對的，庫德蘭，我的老友。', `MaleText_loc7`='Espero que tengas razón, Kurdran, viejo amigo.' WHERE `ID`=49205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠르드란... 안 되네. 그럴 순 없어! 스카이리는 전설일세. 내가 어찌...', `MaleText_loc4`='库德兰……不，我不能！斯卡雷是一个传奇，我不能……', `MaleText_loc5`='庫德蘭...不，我做不到!史蓋瑞是個傳說，我不能...', `MaleText_loc7`='¡Kurdran, no, no puedo aceptarlo! Cielo''ree era un leyenda, no puedo...' WHERE `ID`=49206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네. 정말 고맙네, 쿠르드란.', `MaleText_loc4`='谢谢你，库德兰。', `MaleText_loc5`='好的。謝謝你，庫德蘭。', `MaleText_loc7`='Sí. Gracias, Kurdran.' WHERE `ID`=49207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹세합니다.', `MaleText_loc4`='我愿意。', `MaleText_loc5`='我願意。', `MaleText_loc7`='Sí, quiero.' WHERE `ID`=49208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하객 여러분, 우리는 오늘 패니 썬더마와 키건 파이어비어드의 결합을 축하하러 이곳, 천둥쐐기 산자락에 모였습니다.', `MaleText_loc4`='女士们，先生们，我们聚集在雷霆山下，共同见证范妮·桑德玛尔和科甘·焰须的结合。', `MaleText_loc5`='先生女士們，我們在雷擊山的影子下聚集，來見證芬妮·桑德瑪和基岡·火鬍的結合。', `MaleText_loc7`='Damas y caballeros, estamos aquí reunidos a la sombra del Monte del Rayo para honrar la unión de Fanny Bramal con Keegan Barbafuego.' WHERE `ID`=49209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들의 결합이 바람처럼, 파도처럼, 바위처럼, 불꽃처럼 영원하기를.', `MaleText_loc4`='愿他们婚姻的誓言如同风、水、岩石和火焰一样，永生不息。', `MaleText_loc5`='願他們之間的聯繫如風、水、地、火一般永恆。', `MaleText_loc7`='Que su unión sea tan eterna como el viento, las olas, la piedra y el fuego.' WHERE `ID`=49210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키건과 패니, 두 분은 서로를 자신의 삶 안에 받아들이고 하나가 되어 영원히 함께할 것을 맹세합니까?', `MaleText_loc4`='科甘，范妮，你们是否愿意接受对方进入自己的生活，两个人成为一体，再不分开？', `MaleText_loc5`='基岡和芬妮，你們願意接受另一方進入你們的生活，兩位合二為一，永恆地結合嗎?', `MaleText_loc7`='Keegan y Fanny, ¿se aceptan el uno al otro en sus respectivas vidas, desean convertirse en uno, en una unión imperecedera?' WHERE `ID`=49211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면, 제게 부여된 권위에 의해... 제게 부여된 권위... 힘...', `MaleText_loc4`='那么，以我被赋予的权力……我被赋予的权力……', `MaleText_loc5`='既然如此，根據賦予我的力量...賦予我的力量...', `MaleText_loc7`='Entonces, por los poderes que me han otorgado... que me han otorgado...' WHERE `ID`=49212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 부여된 피와 암흑의 힘에 의해!', `MaleText_loc4`='……以鲜血和暗影！', `MaleText_loc5`='...以鮮血與暗影之名!', `MaleText_loc7`='... ¡LA SANGRE Y LA SOMBRA!' WHERE `ID`=49213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 이름으로 너희 생명을 취하겠다!!', `MaleText_loc4`='我将以主人的名义，吞噬你的生命！', `MaleText_loc5`='我會以主人之名，吞噬你的生命之血!', `MaleText_loc7`='¡¡Consumiré su sangrevida en nombre del maestro!!' WHERE `ID`=49214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맹세합니다.', `FemaleText_loc4`='我愿意。', `FemaleText_loc5`='我願意。', `FemaleText_loc7`='Sí, quiero.' WHERE `ID`=49215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B나는 배고프다... 고로 나는 존재한다.', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B我饿……是的，我饿。', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B我餓...故我在。', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$B$BTengo hambre... luego existo.' WHERE `ID`=49216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B$c|1이;가; 무슨 뜻이지요? 당신은 고블린 $g아빠:엄마;인가요?', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B“$c”是什么意思？你是地精族长吗？', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B「$c」是什麼意思?你是哥布林的$g族王:族母;嗎?', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$b$b¿Qué significa "$c"? ¿Eres $gel patriarca:la matriarca; goblin?' WHERE `ID`=49217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이다!', `MaleText_loc4`='是他们中的一个！', `MaleText_loc5`='是他們之一!', `MaleText_loc7`='¡Es uno de ellos!' WHERE `ID`=49218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡아라!', `MaleText_loc4`='抓住他！', `MaleText_loc5`='抓住他!', `MaleText_loc7`='¡A por él!' WHERE `ID`=49219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B사람들이 당신을 $n|1이라고;라고; 부르더군요. 그건 당신만의 고유한 식별자인가요, 아니면 명예 호칭인가요?', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B他们管你叫$n。这是你特有的名字吗，还是你的一个荣誉称号？', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B他們叫你$n。這是代表你的獨特稱呼，還是一種表示榮耀的稱號?', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$B$BTe llaman $n. ¿Es tu único significante o es un título honorario?' WHERE `ID`=49220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 막아라!', `MaleText_loc4`='停下来！', `MaleText_loc5`='阻止那個東西!', `MaleText_loc7`='¡Detened esa cosa!' WHERE `ID`=49221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아아악!!', `MaleText_loc4`='哇！！', `MaleText_loc5`='哇啊啊啊啊!', `MaleText_loc7`='¡¡Waaaaahhhhh!!' WHERE `ID`=49222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결혼식을 망치지 못하게 하십시오!', `MaleText_loc4`='拯救婚礼！', `MaleText_loc5`='保護婚禮的進行!', `MaleText_loc7`='¡SALVAD LA BODA!' WHERE `ID`=49223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B안녕하세요. 전 최근에 알에서 태어났습니다. 당신은 어디서 태어나셨나요?', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你好，我刚从一颗蛋里爬出来。你呢？', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B你好。我剛剛破殼而出。你呢?', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$B$BSaludos. He emergido recientemente de un huevo. ¿Y tú?' WHERE `ID`=49224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B당신이 고기로 요리를 만든다는 게 사실인가요? 궁금하네요.', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你真的要把你吃的肉烤熟吗？真奇怪。', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B你們真的會把肉煮熟來吃嗎?真好玩。', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$b$b¿Es cierto que cocinas la carne antes de comértela? Curioso.' WHERE `ID`=49225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B보호모를 안 쓰셨네요. 지적 능력이 떨어진다는 의미인가요?', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你没有戴头盔。这会让你的智力变弱吗？', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B你沒有頭盔。這會讓你的智能降低嗎?', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$B$BNo llevas yelmo. ¿Eso disminuye tus capacidades intelectuales?' WHERE `ID`=49226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<놀랍게도 말을 할 줄 아는 새끼 랩터>$B$B손끝이 뭉툭하고 둥그스름하군요. 그래서 별도의 장비를 들고 전투를 하는 건가요?$B$B재미있네요.', `MaleText_loc4`='<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你的指头尖又圆又钝。所以你要用别的东西进行战斗吗？$B$B真是有趣。', `MaleText_loc5`='<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B你的手指末端又圓又鈍。這就是你得攜帶這麼多東西協助你戰鬥的原因嗎?$B$B相當有趣。', `MaleText_loc7`='<Para tu sorpresa, la prole de raptor es capaz de comunicarse contigo.>$b$bTus dedos son torpes y blandos en sus extremos. ¿Por eso tienes que llevar otros complementos para utilizarlos en combate?$B$BQué interesante.' WHERE `ID`=49227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 경주가 시작됩니다, 친구! 경주로를 만들고 능력 있는 선수들과 계약하느라 바쁜 나날을 보내고 있어요.$B$B친구들에게 이 소식을 전하십시오!', `MaleText_loc4`='比赛就要开始了，$g小伙子:姑娘;！我们正在努力完成赛道的建造。而且我一直在忙着签下有能力的参赛者。$B$B多和你的朋友么说说我的需要吧！', `MaleText_loc5`='比賽要開始了，$g小伙子:小姑娘;!我們正努力要整理好賽道，而且我一直都在忙著要簽下一些不錯的參賽者。$B$B告訴你的朋友們吧!', `MaleText_loc7`='¡Se acerca el momento de las carreras, $gmuchacho:muchacha;! Estamos trabajando para preparar la pista y he estado ocupado apuntando a algunos participantes que merecían la pena.$B$B¡Corre la voz entre tus amigos!' WHERE `ID`=49228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 독사여! 네 주인을 섬겨라!', `MaleText_loc4`='深渊中的毒蛇！来侍奉你们的主人！', `MaleText_loc5`='深淵的蛇群啊!來協助你們的主人吧!', `MaleText_loc7`='¡Serpientes de las profundidades! ¡Acudan en ayuda de su maestro!' WHERE `ID`=49229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 나의 아이들아! 나를 지켜라!', `MaleText_loc4`='来吧，我的孩子们！保卫我！', `MaleText_loc5`='來吧，我的孩子們!保護我!', `MaleText_loc7`='¡Venid, hijos míos! ¡Defendedme!' WHERE `ID`=49230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?! 여기서 뭐 하는 거야?$B$B당장 이 섬에서 떠나야 해! 아니면 내 상자 마을 중 하나로 들어가는 편이 더 낫고!$B$B너무 오래 기다리지 말라고! 대격변이 시작됐어!', `MaleText_loc4`='$n？！你还在这里干什么？$B$B你必须离开这座岛，否则就进入我的胶囊镇！$B$B别再耽误时间了，我的孩子！浩劫就要降临在我们头上了！', `MaleText_loc5`='$n?!你還在這裡幹嘛?$B$B你得離開這座島嶼，或者更好的辦法是，進入我其中一個盒中鎮!$B$B不要等太久，$g小伙子:小姑娘;!大災變要來了!', `MaleText_loc7`='¡¿$n?! ¿Qué haces aquí todavía?$B$B¡Tienes que largarte de la isla o, mejor, métete en una de mis Ciudades de Bolsillo!$B$B¡No lo dejes para muy tarde, $gchaval:chavala;! ¡El Cataclismo está cerca!' WHERE `ID`=49231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 이 섬에서 떠나야 해! 그릴리! 어서 설계도를 챙기라고! 내 칫솔도 잊으면 안 돼!', `MaleText_loc4`='我们必须离开这座岛！赶快，格瑞里，拿上那些图纸！还有我的牙刷！', `MaleText_loc5`='我們必須離開這座島!快點，格里利，去把結構圖帶走!還有我的牙刷!', `MaleText_loc7`='¡Tenemos que salir de esta isla! ¡Rápido, Greely, coge los esquemas! ¡Y mi cepillo de dientes!' WHERE `ID`=49232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 짐을 싸라고! 당장 케잔을 탈출해야 해! 가장 가까운 상자 마을로 뛰어들자고! 상자 마을은 무역왕의 쾌속선에 실릴 테니까 말이야.', `MaleText_loc4`='把一切都打好包！我们必须想办法离开科赞！我们会跳进离这里最近的一个胶囊镇！他们会把胶囊镇装进贸易大王的游艇。', `MaleText_loc5`='把東西都打包好!我們必須想辦法離開凱贊!我們可以跳進最近的盒中鎮!他們會把它們裝進貿易親王的遊艇上!', `MaleText_loc7`='¡Haz las maletas! ¡Tenemos que encontrar la forma de salir de Kezan! ¡Nos meteremos en la Ciudad de Bolsillo más cercana! La subirán a bordo del yate del Príncipe mercante.' WHERE `ID`=49233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 하든지 간에 내 떡대놀이용 정교한 모자를 잃어버리게 만들진 말라고!', `MaleText_loc4`='千万要提醒我带上我的巨怪愚行天才帽！', `MaleText_loc5`='不管你要怎麼做，記得提醒我帶著我的蠢蛋絕妙偽裝帽!', `MaleText_loc7`='¡Hagas lo que hagas, no dejes que me olvide de mi almete de estupidez de cateto ingenioso!' WHERE `ID`=49234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙?! 대격변?! 망했다!! 카자로 산이 완전히 폭발하기 전에 어서 케잔을 빠져나가야 한다고!', `MaleText_loc4`='死亡之翼？！大灾变？！我们完蛋了！！我们必须在卡亚罗山爆炸之前离开科赞！！！', `MaleText_loc5`='死亡之翼?大災變?我們完蛋了!我們必須在卡亞羅山爆炸之前離開凱贊!', `MaleText_loc7`='¡¿Alamuerte?! ¡¿El Cataclismo?! ¡¡Estamos condenados!! ¡¡¡Tenemos que largarnos de Kezan antes de que el Monte Kajaro salte por los aires para siempre!!!' WHERE `ID`=49235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세관에서 9번 실험체를 어떻게 통과시키지? 그래! 상자 연구소에 담아두면 되겠네!', `MaleText_loc4`='我们该怎样让九号实验品通过海关？我知道了！把她装进胶囊实验室！', `MaleText_loc5`='我們怎麼把實驗體九號帶過海關?我知道了!把她裝進盒中實驗室!', `MaleText_loc7`='¿Cómo conseguiremos pasar a la Sujeto Nueve por las aduanas? ¡Ya sé! ¡Métela en el Laboratorio de Bolsillo!' WHERE `ID`=49236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 무너진다!', `MaleText_loc4`='天要塌下来了!', `MaleText_loc5`='天空要塌下來了!', `MaleText_loc7`='¡El cielo se cae!' WHERE `ID`=49237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파티? 믿을 수가 없군! 이 섬이 날아가게 생겼는데 파티라니?! 대체 무슨 생각인 거야?', `MaleText_loc4`='一个聚会？你能相信吗？整座岛都要爆炸了，他们却在进行聚会？！他们到底在想什么！！！', `MaleText_loc5`='派對?我有聽錯嗎?在整座島要爆炸的時候開派對?他們在想什麼啊?', `MaleText_loc7`='¿Una fiesta? ¿Te lo puedes creer? ¡¿La isla está a punto de explotar y montan una fiesta?! ¡¡En qué están pensando!!' WHERE `ID`=49238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐을 모두 챙길 시간이 없다고! 중요한 물건만 챙겨! 내가 폭발 방지 수중 G선 고글을 어디다 뒀더라?!', `MaleText_loc4`='没有时间把所有东西都收拾好了！只拿最重要的东西！我的防爆水下G射线护目镜哪里去了？！', `MaleText_loc5`='沒有時間把所有的東西都打包了!只拿重要的東西!我的水下防爆哥布林射線護目鏡呢?', `MaleText_loc7`='¡No hay tiempo suficiente para empaquetarlo todo! ¡Coge solo lo que sea importante! ¿Dónde he puesto mis gafas de rayos goblins submarinas y a prueba de explosiones?' WHERE `ID`=49239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='박사님 걱정은 하지 마세요. 그냥 지금 잠깐 풀이 죽어 있는 것뿐이니까요.$B$B대격변이 왜 하필 지금 찾아왔을까요? 호바트 박사님이 불쌍해요. 저 멋진 초소형 기계닭을 완성하기 직전이었거든요.', `FemaleText_loc4`='不必为霍巴特担心，老板。他只是有一点精神崩溃。$B$B对他来说，这场大灾变来得可以说非常不是时候。他就要完成微型机动战鸡的制造了。', `FemaleText_loc5`='不用擔心荷巴爾特，老大。他現在只是有點精神不振而已。$B$B大災變來得很不是時候，本來他就快要完成微型機械雞的研究了說。', `FemaleText_loc7`='No te preocupes por Hobart, $gjefe:jefa;. Ahora mismo está en medio de un ataque de nervios.$B$BEl Cataclismo no ha podido llegar en un peor momento para él. Estaba a punto de dar por terminado el micromecapollo.' WHERE `ID`=49240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 박사님. 설계도, 확인, 칫솔, 확인.', `FemaleText_loc4`='好的，博士。图纸，检查完毕。牙刷，检查完毕。', `FemaleText_loc5`='我在辦了，博士。設計圖，有了。牙刷，有了。', `FemaleText_loc7`='Estoy en ello, doctor. Esquemas, los tengo. Cepillo de dientes, lo tengo.' WHERE `ID`=49241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았어요, 알았다고요. 호바트 박사님, 우선 진정 좀 하세요. 혈압을 생각하시라고요! 얼굴빛이 청록색으로 변하고 있어요!', `FemaleText_loc4`='我会的，我会的。但霍巴特，你必须先平静下来。你的血压已经很高了！你全身都变成深绿色了！', `FemaleText_loc5`='我會的，我會的。可是荷巴爾特，你一定要冷靜下來。你的血壓!你變成深綠色了!', `FemaleText_loc7`='Lo haré, lo haré. Pero Hobart, tienes que tranquilizarte. ¡Piensa en tu tensión arterial! ¡Te estás poniendo verde!' WHERE `ID`=49242;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, 분명히 여기 어디서 봤는데... 그런데... 정말 사용하시려고요? 그 물건은 두 번 중 한 번은 떡대 환영을 보여주는 게 아니라 사용자를 아예 떡대로 변신시켜 버리잖아요. 그리고 그 사람은 폭발해 버린다고요!', `FemaleText_loc4`='嗯，我应该是在这里见过它，但你确定吗？那东西并不只是会将使用者的外形放大百分之五十，而是会把使用者变成怪物，然后还会让使用者爆炸！', `FemaleText_loc5`='嗯，我好像有在這附近看過，可是你確定嗎?那個東西有百分之五十的機率會把使用者變成蠻卒，而不只是投射出影像而已。然後他們還會爆炸!', `FemaleText_loc7`='Hmm, sé que lo he visto por aquí en alguna parte, pero... ¿estás seguro? El cincuenta por ciento del tiempo esa cosa transforma al usuario en un bruto en vez de proyectar una imagen de uno mismo. ¡Y después explota!' WHERE `ID`=49243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진정하지 않으면 머리가 터져버릴지도 몰라요! 너무 뻔한 이야기 아닌가요? 축구탄 시합 결승전에서 카자로 산에 마지막 결승골을 날리는 바로 그 순간에 용이 머리 위로 날아갔다니 말이에요.', `FemaleText_loc4`='如果你不冷静下来，你就要爆炸了！难道你不认为这样会比较方便吗？当足球炸弹最终被踢进卡亚罗山，胜负已定的时候，那头龙恰好飞过天空。', `FemaleText_loc5`='你再不冷靜下來就會爆炸!你不覺得這有點太巧了嗎?足球炸彈決賽關鍵得分踢進卡亞羅山的時候，那隻龍剛好就飛過來了?', `FemaleText_loc7`='¡Vas a explotar si no te tranquilizas! ¿No crees que ha sido mucha casualidad? ¿Que el dragón aparezca justo cuando en la final de bombalón se hizo lanzamiento de campo ganador directo al Monte Kajaro?' WHERE `ID`=49244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 상관없겠지요. 상자 마을이 아즈샤라에 떨어지도록 설정할게요. 저 작은 쿠션도 같이 챙겨야겠어요. 너무 귀엽잖아요!', `FemaleText_loc4`='我会立刻做好胶囊实验室在艾萨拉展开的标记。我会把她的小软垫和她放在一起。她是那么聪明可爱！', `FemaleText_loc5`='馬上辦。我會把盒中實驗室設定在艾薩拉使用。我也會把她的小軟墊一起帶走。她太可愛了!', `FemaleText_loc7`='Ahora mismo. Marcaré el Laboratorio de Bolsillo para que lo envíen directamente a Azshara. La empaquetaré con su pequeño cojín. ¡Es tan mona!' WHERE `ID`=49245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄밀히 말하면, 그건 사실이 아니에요, 박사님. 카자로 산과 같은 화산에서 튀어나오는 바위는 분출물이라고 해요. 무너지는 게 하늘이 아니라고요. 녹은 바위, 또는 다른 말로 퇴적한 화산재라고도 하죠. 떨어지는 동안 식어서 용암 폭탄이 되지요. 아주 적절한 명칭 아닌가요?', `FemaleText_loc4`='从技术上说，这是不现实的，博士。那是从卡亚罗山火山口中喷出的岩石，也就是火山喷出物，而不是天空。那些都是液化岩石和火山灰。它们会在降落时逐渐冷却，变成熔岩炸弹。这才是恰当的解释，不是吗？', `FemaleText_loc5`='就技術上來講，博士，那並不是真的。從卡亞羅山那樣的火山飛出來的岩石應該叫做「噴出物」才對。不是天空，是融化的岩石，或叫做「玄武岩」。在落下時逐漸冷卻，變成火山炸彈。非常貼切，你說對吧?', `FemaleText_loc7`='Técnicamente, eso no es cierto, doctor. Las rocas que salen despedidas de un volcán como el Monte Kajaro se denominan eyecciones. No es el cielo. Es roca fundida o tefra. Se enfría a medida que desciende y se convierte en bombas de lava. Muy apropiado, ¿no crees?' WHERE `ID`=49246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 제가 진짜 파티에 초대를 받았었다고요. 왜 항상 이런 일이 생겨서 파티에 갈 수 없게 되는 걸까요? 정말 음료 한 잔 생각이 간절하다니까요.', `FemaleText_loc4`='那是一场真正的聚会，而且我的确受到了邀请。为什么总是有意外发生，让我永远也无法走开？我应该好好喝上一杯的。', `FemaleText_loc5`='是啊，真的在開派對，而且還有發邀請函給我呢。為什麼老是會發生事情，害我都不能去?我好想去喝幾杯。', `FemaleText_loc7`='Sí, una fiesta a la que, además, me han invitado. ¿Por qué siempre ocurre algo que me impide asistir? Me vendría bien una copa.' WHERE `ID`=49247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어, 호바트 박사님, 지금 입고 있잖아요.', `FemaleText_loc4`='霍巴特，你正戴着它呢。', `FemaleText_loc5`='呃，荷巴爾特，你已經戴起來了。', `FemaleText_loc7`='Um, Hobart, las llevas puestas.' WHERE `ID`=49248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 폭탄... 해체할 수 있겠지? 그렇지? 매그루더?!', `MaleText_loc4`='你能去掉它，对不对，麦格鲁德？！', `MaleText_loc5`='你可以拆掉它對吧，瑪格路德?', `MaleText_loc7`='Puedes desactivarlo, ¡¿verdad, Magruder?!' WHERE `ID`=49249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠장... 이게 뭐야?', `MaleText_loc4`='圣……这到底是什么？', `MaleText_loc5`='老天...這是什麼鬼啊?', `MaleText_loc7`='Madre de... ¿Qué demonios es esto?' WHERE `ID`=49250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 농담 하십니까? 이 엄청난 선들을 보십시오! 수십만 개는 될 것 같은데... 딱 세 개까지가 제 한계입니다.
', `MaleText_loc4`='你在开玩笑吗？看看这东西！它里面一定有上百万根线。对我来说，三根线就已经足够了……', `MaleText_loc5`='你在開我玩笑嗎?看看這一團糟!看起來像是有一百萬條線!我是那種只能處理三條線的...', `MaleText_loc7`='¿Me tomas el pelo? ¡Mira esta porquería! Tiene como un millón de cables. Yo soy un tipo de tres cables como máximo...' WHERE `ID`=49251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치십시오!!!!!!
', `MaleText_loc4`='快跑！！！！！！', `MaleText_loc5`='逃啊!!!!', `MaleText_loc7`='¡¡¡¡¡¡CORRE!!!!!!' WHERE `ID`=49252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지께선 내가 코흘리개 꼬마일 때부터 원소를 존중하도록 가르치셨지. 대지와 불, 바람과 바다... 거기엔 엄청난 힘이 담겨 있다네, $c|1이여;여;.$B$B<눈을 빛내는 그런디>$B$B자네가 아는 것보다 더 큰 힘이.', `MaleText_loc4`='我还是小孩子的时候，我的父亲就已经在训练我该如何尊敬元素。大地和烈火，疾风和海洋——它们都具有无比强大的能量，$c。$B$B<格朗迪的眼睛里闪过一丝光芒。>$B$B那是你没有能力去认知的能量。', `MaleText_loc5`='當我還是個孩子時，我的父親就訓練我要尊敬元素。大地、火、風、水...它們擁有強大的力量，$c。$B$B<格蘭地的眼中閃爍著光芒。>$B$B比你想像中的還要強大。', `MaleText_loc7`='Desde que era un niño mi padre me ha enseñado a respetar los elementos. La tierra, el fuego, el viento y el mar... Poseen un gran poder, $c.$B$B<Grundy tiene un brillo en los ojos.>$B$BMás del que te imaginas.' WHERE `ID`=49253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차리고 있겠습니다, 그런디. 결혼식을 시작하시죠!', `MaleText_loc4`='我会时刻睁大双眼，格朗迪。让婚礼开始吧！', `MaleText_loc5`='我會注意的，格蘭地。開始進行婚禮吧!', `MaleText_loc7`='Mantendré los ojos bien abiertos, Grundy. ¡Que comience la boda!', `FemaleText_loc1`='정신 바짝 차리고 있겠습니다, 그런디. 결혼식을 시작하시죠!', `FemaleText_loc4`='我会时刻睁大双眼，格朗迪。让婚礼开始吧！', `FemaleText_loc5`='我會注意的，格蘭地。開始進行婚禮吧!', `FemaleText_loc7`='Mantendré los ojos bien abiertos, Grundy. ¡Que comience la boda!' WHERE `ID`=49254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르! 언덕마루는 우리 것이오!', `MaleText_loc4`='LOK''TAR！希尔斯布莱德是我们的！', `MaleText_loc5`='希爾斯布萊德屬於我們!為了部落!', `MaleText_loc7`='¡LOK''TAR! ¡CAMPOS DE TRABALOMAS ES NUESTRO!' WHERE `ID`=49255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식이 왔군!!!', `MaleText_loc4`='格罗尔纳要吃东西！', `MaleText_loc5`='葛羅納爾的食物啊啊啊!', `MaleText_loc7`='¡COMIDA PARA GROLNAR!' WHERE `ID`=49256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 배신자 네페르세트 부족과의 전쟁 문제를 논의하기 위해 모였다... 대의원회의 의원들이여, 모두 결론을 내렸는가?', `MaleText_loc4`='关于对抗尼斐塞特反叛部族的议案……高阶议会的成员有没有做出决定？', `MaleText_loc5`='對抗叛變部族奈斐賽特的戰爭...高階議會的每個成員都做出決定了嗎?', `MaleText_loc7`='En el asunto de la guerra contra la tribu rebelde de Neferset... ¿El Alto Consejo ha tomado una decisión?' WHERE `ID`=49257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 보고 감동의 눈물이나 흘리라고.', `FemaleText_loc4`='看吧，哭泣吧。', `FemaleText_loc5`='仔細看好了。', `FemaleText_loc7`='Mira y llora.' WHERE `ID`=49258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='봤지? 어떤 무기도 내 망치의 무시무시한 힘을 당해낼 수 없어.', `FemaleText_loc4`='看到了吗？什么也无法阻挡我的战锤的力量。', `FemaleText_loc5`='看吧?還是我的鐵錘最可靠。', `FemaleText_loc7`='¿Lo ves? Nada puede superar el poder aplastante de mis martillos.' WHERE `ID`=49259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 폐하. 람카헨의 칼은 전쟁에 찬성합니다. 폐하의 병사들은 전투 준비를 마치고 대기하고 있습니다.', `MaleText_loc4`='是的，陛下。拉穆卡恒之剑决议发动战争。您的军队已经整装待发。', `MaleText_loc5`='是的，陛下。蘭姆卡韓之劍贊成開戰。你的軍隊已經準備好了。', `MaleText_loc7`='Sí, su majestad. La Espada de Ramkahen vota a favor de la guerra. Tus ejércitos están listos para el combate.' WHERE `ID`=49260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='람카헨의 목소리 역시 전쟁에 찬성합니다.', `MaleText_loc4`='拉穆卡恒之声同样赞成发动战争。', `MaleText_loc5`='蘭姆卡韓之聲也投下戰爭的一票。', `MaleText_loc7`='La Voz de Ramkahen también vota a favor de la guerra.' WHERE `ID`=49261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='람카헨의 신념은... 기권하겠습니다.', `MaleText_loc4`='拉穆卡恒之心……弃权。', `MaleText_loc5`='蘭姆卡韓之信仰...棄權。', `MaleText_loc7`='La Fe de Ramkahen... se abstiene.' WHERE `ID`=49262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 몇 시간 동안, 저는 강물이 보여준 미래를 고통 속에 바라봤습니다.', `MaleText_loc4`='连续几个小时，我一直在为那河中的水流带给我的幻象而苦恼。', `MaleText_loc5`='整整好幾個小時，我因河流之水顯現給我看的景象而痛苦不已。', `MaleText_loc7`='Durante horas agonicé por las visiones que me mostraron las aguas del río.' WHERE `ID`=49263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 본 미래에서, 적과의 협상은 잠깐의 평화를 가져왔지만... 곧 끔찍한 배신과 파괴가 그 뒤를 이었습니다.', `MaleText_loc4`='在我看到的影像中，与敌人的谈判为我的人民带来了短暂的和平……随后就是可怕的出卖和毁灭。', `MaleText_loc5`='在我預見的景象中，與敵人的交涉帶給我們人民短暫的和平...接下來是可怕的背叛與毀滅。', `MaleText_loc7`='En mis visiones, las negociaciones con nuestro enemigo nos habían proporcionado una paz huidiza... seguida por una terrible traición y por una destrucción total.' WHERE `ID`=49264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 하나의 예언만이 어스레한 희망의 빛을 보여주었습니다. 그리고 그 예언에서는... 대의원회가 아닌 파오리스 폐하께서 직접 결정을 내리셨습니다.', `MaleText_loc4`='只有一个影像让我看到了一丝希望。在那里面……高阶议会没有做出你想要的决议，法奥瑞斯。', `MaleText_loc5`='只有一個景象提供了一點點希望之光。而在那個景象中...高階議會並沒有為你做出決定，法歐瑞斯。', `MaleText_loc7`='Tan solo una visión me ofreció un atisbo de esperanza. Y en esa visión... el Alto Consejo no tomó esta decisión por ti, Phaoris.' WHERE `ID`=49265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있소, $n... 약속의 성궤요!', `MaleText_loc4`='找到她了，$n……应许约柜！', `MaleText_loc5`='她來了，$n...應許法櫃!', `MaleText_loc7`='Aquí está, $n... ¡El Arca de la promesa!' WHERE `ID`=49266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했어, 존스 박사!', `MaleText_loc4`='干得好，琼斯博士！', `MaleText_loc5`='幹得好呀，瓊斯博士!', `MaleText_loc7`='¡Vien hecho, doktor Jones!' WHERE `ID`=49267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 성궤까지 데려와 준 것도 모자라 방어막까지 없애 줬어!', `MaleText_loc4`='你不仅让我找到了这个箱子，还去除了它的保护！', `MaleText_loc5`='你不只把我引領到法櫃之前，而且還移除了它的保護措施!', `MaleText_loc7`='¡No solo me has guiado hasta el arka, sino que además has eliminado las prrrotecciones!' WHERE `ID`=49268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가엾군...', `MaleText_loc4`='真是可怜啊……', `MaleText_loc5`='真可惜...', `MaleText_loc7`='Una pena...' WHERE `ID`=49269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너라면 내 조직에서도 꽤 중요한 직책을 맡을 수 있을 텐데... 아쉽게도 여기서 죽어줘야겠어.', `MaleText_loc4`='我真的很想让你在我的组织中得到一个崇高的职位，而不是杀死你。', `MaleText_loc5`='如果我不用殺死你，我可以在我的公司裡給你一個相當有威望的職位...', `MaleText_loc7`='Te ofrrrecería un puesto de prrrestigio dentro de mi orrrganización si no tuviera que matarte.' WHERE `ID`=49270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그전에 우선!', `MaleText_loc4`='但首先！', `MaleText_loc5`='但首先!', `MaleText_loc7`='¡Pero prrrimero!' WHERE `ID`=49271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 네가 그렇게 아끼던 존재의 파멸을 지켜보라고!', `MaleText_loc4`='你应该亲眼见证你所珍爱的东西被彻底摧毁！', `MaleText_loc5`='你得先親眼目睹你如此心愛的東西在眼前毀掉!', `MaleText_loc7`='¡Serrrás testigo de la destrrrucción de aquello que te es querido!' WHERE `ID`=49272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성궤!? 설마...', `MaleText_loc4`='约柜？！你不能……', `MaleText_loc5`='法櫃?你不是要...', `MaleText_loc7`='¡¿El arca?! No te atreverías...' WHERE `ID`=49273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 멍청한 녀석 같으니! 내가 정말 네 멍청한 상자 따위를 원했다고 생각해?', `MaleText_loc4`='哦，不要犯傻！我从没有想过要占有你的蠢箱子。', `MaleText_loc5`='噢，別傻了!我從來都沒有要你那個可笑的箱子。', `MaleText_loc7`='¡Oh, no seas idiota! Nunca quise quedarrrme con tu estúpida arka.' WHERE `ID`=49274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유물만 없으면 데스윙 님이 시초 재개 기계장치를 가동시킬 수 있어!', `MaleText_loc4`='那件宝物是唯一能阻止死亡之翼开启起源重组系统的东西！', `MaleText_loc5`='那項神器是唯一阻止死亡之翼啟動重組裝置的東西!', `MaleText_loc7`='¡Ese arrrtefacto es lo único que impide que Alamuerrrte actife el mecanismo de rrrecrreación!' WHERE `ID`=49275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분께서 복수에 대한 열망을 충족시키시고 나면, 난 내가 원하는 대로 아제로스를 지배할 수 있지!', `MaleText_loc4`='等到他的复仇欲望得到满足，我就能随心所欲地统治艾泽拉斯了！', `MaleText_loc5`='等他復仇的渴求滿足了以後，我就可以隨心所欲地統治艾澤拉斯!', `MaleText_loc7`='¡Una vez su ansia de venganza esté saciada, serrré lifre de gofernar Azeroth como yo crrrea oportuno!' WHERE `ID`=49276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 무슨 소리지?', `MaleText_loc4`='嗯？那是什么？', `MaleText_loc5`='嗯?那是什麼?', `MaleText_loc7`='¿Hmmm? ¿Qué ha sido eso?' WHERE `ID`=49277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알게 뭐야! 잠시 후에는 여기 아무것도 남지 않을 텐데!', `MaleText_loc4`='没关系！再过一会儿，这东西就彻底不复存在了！', `MaleText_loc5`='不重要!再一下子，這個東西就會連渣都不剩!', `MaleText_loc7`='¡No imporrrta! ¡Dentro de un instante no quedarrrá nada de todo esto!' WHERE `ID`=49278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 감으라고. 기분 좋은 광경은 아닐 거야...', `MaleText_loc4`='闭上你的眼睛，孩子。这可不会很好看……', `MaleText_loc5`='閉上眼睛，孩子。接下來會相當難看...', `MaleText_loc7`='Cierra los ojos, joven. Esto no va a ser agradable...' WHERE `ID`=49279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 성궤를 파괴하라! 저놈들도 함께 없애버려!', `MaleText_loc4`='现在！摧毁这只箱子！也将他们一同摧毁！', `MaleText_loc5`='現在!摧毀法櫃!還有他們!', `MaleText_loc7`='¡Ahorrra! ¡Destruye el arka! ¡Y a ellos con ella!' WHERE `ID`=49280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그 예언에서는 대의원회가 파오리스 폐하를 위해 그런 결정을 내린 것은 아니었습니다.', `MaleText_loc4`='在那里面……高阶议会没有做出你想要的决议，法奥瑞斯。', `MaleText_loc5`='而在那個景象中...高階議會並沒有為你做出決定，法歐瑞斯。', `MaleText_loc7`='Y en esa visión... el Alto Consejo no tomó esta decisión por ti, Phaoris.' WHERE `ID`=49281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그렇다고 마지못해 조약에 따라 전쟁을 일으킨다면, 이 나라가 더 일찍 종말을 맞이할 뿐입니다.', `MaleText_loc4`='但是战争，一场由不愿遵循协议的领袖发动的战争，会让我们的国家更快地灭亡。', `MaleText_loc5`='但是，由一個不甘願遵從協議的領袖所發起的戰爭，帶給我們王國的是更快速的滅亡。', `MaleText_loc7`='Pero la guerra, promovida por un líder que obedeció el protocolo a su pesar, aceleró aún más la desaparición de nuestra nación.' WHERE `ID`=49282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 심리철학자야. 머리로는 자네보다 한 수 위라는 뜻이지. 진단 받기 싫으면 얼른 움직여.', `MaleText_loc4`='我是一名哲人。这意味着我比你更聪明。现在，离开吧，不要等我废黜你的时候再后悔。', `MaleText_loc5`='我是個分析學家。這代表我比你聰明。在我開始分析你之前快走吧。', `MaleText_loc7`='Soy un psilósofo. Lo que significa que soy más listo que tú. Ahora muévete antes de que te diagnostique.' WHERE `ID`=49283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하, 네페르세트와의 국경 지대를 따라 소규모 전투가 벌어졌습니다. 송구스럽습니다만, 폐하의 동생분이 이끌던 순찰대도 거기 휘말렸습니다...', `MaleText_loc4`='我的君主，不久之前，尼斐塞特边境发生了一场小规模冲突，一支由您的兄弟率领的巡逻队被卷入其中……', `MaleText_loc5`='主君，奈斐賽特的邊境剛剛發生了一場遭遇戰。你的兄弟所帶領的巡邏隊也在其中...', `MaleText_loc7`='Mi señor, acaba de tener lugar una escaramuza a lo largo de la frontera de Neferset. Se ha visto implicada una patrulla... al frente de la cual iba tu hermano.' WHERE `ID`=49284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동생분께서는... 생명이 위독합니다, 폐하.', `MaleText_loc4`='他……受了重伤，陛下。', `MaleText_loc5`='他受到了...致命傷，長官。', `MaleText_loc7`='Ha resultado... mortalmente herido, señor.' WHERE `ID`=49285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날이 밝는 대로 네페르세트 도시를 공격한다.', `MaleText_loc4`='我们在天亮时进攻尼斐塞特城。', `MaleText_loc5`='我們在曙光初現的時刻進攻奈斐賽特城。', `MaleText_loc7`='Atacaremos la Ciudad de Neferset al alba.' WHERE `ID`=49286;
