UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고!$b$b그래, 이제 올 때가 됐다고 생각했습니다.$b$b벌써 며칠째 기다리고 있었으니까요.$b$b이런 무더위 속에 늙은 드워프를 남겨두다니... 저 녀석을 이렇게 가르치진 않았는데...', `MaleText_loc4`='啊！$b$b你来得正是时候。$b$b我已经等了你好几天了。$b$b竟然把一个老矮人丢在这个闷热的地方……就算是训练新兵也比这个好。', `MaleText_loc5`='噢!$b$b也該是你現身的時候了。$b$b我已經等你好幾天了。$b$b留一個老矮人在這裡冒汗...我兒子都比你像話。', `MaleText_loc7`='¡Ach! $b$bYa era hora de que aparecieras.$b$bLlevo días esperándote.$b$bDejar solo a un viejo enano para que se achicharre... He tenido aprendices mucho mejores que tú.' WHERE `ID`=49289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄을 설치했습니다! 갑판으로 올라가서 뛰어내리십시오!', `MaleText_loc4`='炸弹已经放好了！赶快跑到阳台上，跳下去！', `MaleText_loc5`='炸彈裝好了!逃到陽台然後跳下去!', `MaleText_loc7`='¡Las bombas están colocadas! ¡Corre al balcón para saltar y escapar!' WHERE `ID`=49290;
