UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 무덤은 이쪽에 있네. 나를 따라오게나, $n.', `MaleText_loc4`='灰影墓穴在这边，跟我来，$n。', `MaleText_loc5`='灰影墓穴在這個方向。跟著我，$n。', `MaleText_loc7`='El Sepulcro Sombrío está por aquí. Sígueme, $n.' WHERE `ID`=49295;
