UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 나 좀 도와주게나, $n! 모르도가 말한 물건을 찾을 수가 없다네!', `MaleText_loc4`='嗨，帮我一把，$n！我找不到摩尔多需要的那些物资了！', `MaleText_loc5`='喂，幫個忙啊，$n!我找不到摩爾多要的補給品!', `MaleText_loc7`='¡Eh, échame una mano, $n! ¡No puedo encontrar los suministros que necesitaba Mordo!' WHERE `ID`=49301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 보자... 물건이 어디에 있을까...', `MaleText_loc4`='让我看看……它们会在……', `MaleText_loc5`='咱們看看...它們會在哪呢...', `MaleText_loc7`='Veamos... Dónde podrían estar...' WHERE `ID`=49302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네! 자네가 물건을 찾았군. 모르도에게 되돌려 주세나.', `MaleText_loc4`='干得好！你找到它们了。我们把它们送到摩尔多那里去吧。', `MaleText_loc5`='幹得好!你找到了。咱們把這些帶回去給摩爾多吧。', `MaleText_loc7`='¡Buen trabajo! Los has encontrado. Se los llevaré a Mordo.' WHERE `ID`=49303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있는 친구가 턱이 떨어졌더군. 모르도가 고쳐줄 수 있나?', `MaleText_loc4`='我看到有人吃惊得下巴都掉下来了。不知道摩尔多能不能把他的下巴放回去？', `MaleText_loc5`='我看到上面有人的下巴掉了。也許摩爾多可以幫他處理一下?', `MaleText_loc7`='Vi a alguien al que se le cayó la mandíbula. ¿Quizá Mordo pueda arreglársela?' WHERE `ID`=49304;
