UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끄악... 저놈 꽤 화난 것 같은데요!', `MaleText_loc4`='呃，喔！他现在气急败坏了！', `MaleText_loc5`='呃喔!他看起來很生氣了!', `MaleText_loc7`='¡Oh oh! ¡Se lo ve enojado!' WHERE `ID`=49321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨어요, 여러분! 에, 저놈 몸속 어딘가에 열쇠가 있을 거예요. 어, 그냥... 조금 뒤져 보세요.', `MaleText_loc4`='干得好伙计们！钥匙应该就在他身体的某个地方。只要，呃，仔细找找，直到找到为止。', `MaleText_loc5`='幹得好啊!鑰匙應該在他的某個內臟。只要，呃，在這裡找一下應該就能找到了。', `MaleText_loc7`='¡Bien hecho, chicos! La llave tiene que estar en sus tripas. Ehm, tanteen por ahí adentro.' WHERE `ID`=49322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 고마워요! 전 더 놀라운 모험을 찾아 떠나렵니다!', `MaleText_loc4`='谢谢你们救了我！我要踏上更为刺激的冒险之旅了。', `MaleText_loc5`='謝謝你救了我!我要去進行更多驚人的冒險了。', `MaleText_loc7`='¡Gracias por liberarme! Me voy en busca de más aventuras.' WHERE `ID`=49323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀려나려면 고드름을 때리십시오!', `MaleText_loc4`='击打冰柱来挣脱束缚！', `MaleText_loc5`='攻擊冰柱來脫身!', `MaleText_loc7`='¡Golpea el carámbano para liberarte!' WHERE `ID`=49324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 풀려난 지도 6주가 지났네. 이제 족쇄를 풀 준비가 됐나?', `MaleText_loc4`='从你被释放到现在，已经过去六个星期了。你准备好告别那双镣铐了吗？', `MaleText_loc5`='自從你被釋放已經經過六個星期了。你準備好要解開束縛了嗎?', `MaleText_loc7`='Han pasado seis semanas desde que te soltaron. ¿Estás listo para que te quiten los grilletes?' WHERE `ID`=49325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새... 생각할 시간이 필요합니다. 너무... 너무 빨라요.', `MaleText_loc4`='我需要时间来好好想一想。还太……太早了。', `MaleText_loc5`='我需要時間思考。這...有點太早了。', `MaleText_loc7`='Necesito tiempo para pensar. Es... demasiado pronto.' WHERE `ID`=49326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='6주라고 하셨습니까? 전 던홀드에서 6년을 보냈다고요! 제 생활의 일부분이었던 뭔가를 그리 쉽게 던져버릴 수는 없습니다!', `MaleText_loc4`='六个星期？我在敦霍尔德待了整整六年！这玩意儿跟了我这么久，我怎么可能如此轻易就摆脱它！', `MaleText_loc5`='六個星期?我花了六年在敦霍爾德!你不可能要我輕易地丟下跟著我這麼久的東西吧!', `MaleText_loc7`='¿Seis semanas? ¡Pasé seis años en Durnholde! ¡No puedes esperar que me deshaga tan pronto de algo que ha sido parte de mi vida durante tanto tiempo!' WHERE `ID`=49327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 알고 싶은 건 이겁니다. 제 발목에 쇠공과 사슬이 묶여 있다 해도, 제가 괜찮다는데 왜 상관하십니까!?', `MaleText_loc4`='我想知道的是——我脚上绑着铁球和锁链，这关你什么事？！', `MaleText_loc5`='我想知道的是這個:你幹嘛介意我腳踝上有著鏈子和球!?', `MaleText_loc7`='Lo que quiero saber es: ¡¿A TI QUÉ TE IMPORTA SI LLEVO UNA BOLA Y UNA CADENA ATADAS AL TOBILLO?!' WHERE `ID`=49328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 문제는 제 문제로 한정시켜 봐주시면 안 되겠습니까? 왜 자꾸 테디를 연관지으시는 겁니까?', `MaleText_loc4`='你就不能从我的角度想想吗，医生？为什么总是关于泰迪？', `MaleText_loc5`='你不能只為了見我而見我嗎，博士?幹嘛總是要提到泰德?', `MaleText_loc7`='¿Es que no puedes venir a verme por verme, doc? ¿Es que siempre tiene que ser por Teddy?' WHERE `ID`=49329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싫다고 말했잖습니까, 젠장! 100번도 넘게 말한 것 같은데, 싫다고요!', `MaleText_loc4`='不，该死！第一百次的回答还是不！', `MaleText_loc5`='不要，該死的!我說了一百遍了，不要!!', `MaleText_loc7`='¡NO, MALDITA SEA! ¡Por enésima vez, NO!' WHERE `ID`=49330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 죽었을 때나 떼어주십시오.', `MaleText_loc4`='等我死了，你就可以随便拿掉它。', `MaleText_loc5`='等我死了，你就可以自己決定要不要把它拿下來。', `MaleText_loc7`='Podrás quitármelos cuando me muera.' WHERE `ID`=49331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 제가 처음 붙잡혔을 때는 테디를 싫어했습니다. 녀석은 제 피부 속으로 파고들었고, 제 자유를 앗아갔죠. 하지만 이건 알아주십시오, 선생님. 6년이나 지난 지금은 이 친구에게 묘한 감정이 느껴집니다.', `MaleText_loc4`='你知道吗，当我刚刚被抓住时，我恨透了泰迪。他钻进我的身体，让我不能自由移动。但我现在想告诉你的是——在共度六年之后，我必须承认，他已经成为我身体的一部分。', `MaleText_loc5`='你知道嗎，當我剛剛被抓的時候我很恨泰德。他鑽進我的皮膚，不讓我自由移動。但是我得告訴你，博士;花了六年的時間跟他在一起，我必須承認跟他產生了感情。', `MaleText_loc7`='Sabes, cuando me capturaron la primera vez odié a Teddy. Se me clavaba en la piel y me impedía moverme libremente. Pero déjame que te diga una cosa, doc: después de pasar seis años con un tipo puedo decir honestamente que siento algo por él.' WHERE `ID`=49332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 드럴과 같은 생각입니다, 선생님. 라번과 전 행복해요. 왜 저희를 갈라놓으려고 하십니까?', `MaleText_loc4`='我与德鲁尔同在，医生。我们在一起很快乐。为什么要拆散我们？', `MaleText_loc5`='我跟德盧爾一樣，博士。拉文恩跟我一起很開心。幹嘛想拆散我們?', `MaleText_loc7`='Estoy con Drull, doc. Laverne y yo somos felices juntos. ¿Por qué intentas separarnos?' WHERE `ID`=49333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나에게서 떨어져, 이 괴물아!', `FemaleText_loc4`='离我远点儿，你这怪物！', `FemaleText_loc5`='離我遠一點，你這個怪物!', `FemaleText_loc7`='¡No te acerques a mí, abominación!' WHERE `ID`=49334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언데드는 아제로스를 더럽히는 존재야! 네놈 같은 괴물들은 모두 사라져야 해!', `FemaleText_loc4`='亡灵是艾泽拉斯的腐蚀之源！你们这些家伙都该被毁灭！', `FemaleText_loc5`='不死族是艾澤拉斯大陸上的污點!你們的每一分子都該被消滅!', `FemaleText_loc7`='¡Los no-muertos están contaminando todo Azeroth! ¡Todos y cada uno de ustedes merecen ser destruidos!' WHERE `ID`=49335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 우리 친구들을 ''쇠공과 사슬''이라 부르지 말아주세요, 선생님.', `MaleText_loc4`='而且我们不喜欢你把我们的朋友称作“铁球和锁链”，医生。', `MaleText_loc5`='而且我們不喜歡你說我們的朋友是鏈子和球，博士。', `MaleText_loc7`='Y no nos gusta que te dirijas a nuestros amigos como "una bola y una cadena", doc.' WHERE `ID`=49336;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니야. 거짓말하지 마! 아버지가 날 보호해주실 거야!', `FemaleText_loc4`='不。你在撒谎！父亲会保护我的！', `FemaleText_loc5`='不!你在說謊!我父親會保護我!', `FemaleText_loc7`='No. ¡Mientes! ¡Mi padre me protegerá!' WHERE `ID`=49337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아갈 수 있다면 돌아가고 싶습니다. 던홀드에선 제 삶이 있었거든요. 나오기 직전엔 많이 맞아봤자 한 주에 한 번 정도 맞았으니 괜찮았습니다.', `MaleText_loc4`='如果可以的话，我宁可回去。我在敦霍尔德有自己的生活。其实我在那儿每个星期顶多挨一次打。', `MaleText_loc5`='如果可以我想要回去。我在敦霍爾德有我的生活。最壞的狀況下我最多每個星期只會被打一次。', `MaleText_loc7`='Yo volvería si pudiera. En Durnholde tenía una vida. Hacia el final solo me pegaban una vez a la semana COMO MUCHO.' WHERE `ID`=49338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 괴물이 아닙니다. 그저 언데드일 뿐이죠. 당신과 대화하고 싶습니다.', `MaleText_loc4`='我不是什么畸形的怪物，我只是个亡灵。我想和你谈谈。', `MaleText_loc5`='我不是怪物，我只是不死族。我只是要跟你說話。', `MaleText_loc7`='No soy una abominación, soy un simple no-muerto. Solo quiero hablar contigo.', `FemaleText_loc1`='전 괴물이 아니에요. 그저 언데드일 뿐이죠. 당신과 대화하고 싶어요.', `FemaleText_loc4`='我不是什么畸形的怪物，我只是个亡灵。我想和你谈谈。', `FemaleText_loc5`='我不是怪物，我只是不死族。我只是要跟你說話。', `FemaleText_loc7`='No soy una abominación, soy una simple no-muerta. Solo quiero hablar contigo.' WHERE `ID`=49339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴리안 님, 본인이 언데드란 사실을 모르시겠습니까?', `MaleText_loc4`='莉莉安，你有没有意识到自己也是个亡灵？', `MaleText_loc5`='莉莉安，你有意識到自己也是不死族嗎?', `MaleText_loc7`='Lilian, ¿te das cuenta de que tú también estás no-muerta?', `FemaleText_loc1`='릴리안 님, 본인이 언데드란 사실을 모르시겠나요?', `FemaleText_loc4`='莉莉安，你有没有意识到自己也是个亡灵？', `FemaleText_loc5`='莉莉安，你有意識到自己也是不死族嗎?', `FemaleText_loc7`='Lilian, ¿te das cuenta de que tú también estás no-muerta?' WHERE `ID`=49340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말해, 이 심리 치료도 조금 지겨워지기 시작했어요. 우린 괜찮습니다! 그냥 내버려 두세요.', `MaleText_loc4`='坦白说，我对这些治疗环节感到有些厌倦了。我们健康得很！我们只想离开。', `MaleText_loc5`='說實在的，我已經開始厭倦這些療程了。我們很好!讓我們離開吧。', `MaleText_loc7`='Francamente, estoy cansándome de estas sesiones de terapia. ¡Estamos bien! Deja que nos vayamos.' WHERE `ID`=49341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 내린 진단은 네 녀석들 모두 멍청이라는 걸세! 알겠나? 멍청이라고!', `MaleText_loc4`='我的官方诊断结果就是——你们简直是一对白痴！听到没有，白痴！', `MaleText_loc5`='我正式的診斷是，你們兩個都是白痴!我說的，是白痴!', `MaleText_loc7`='¡Mi diagnóstico oficial es que los dos sois idiotas! ¡IDIOTAS OS DIGO!' WHERE `ID`=49342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라. 이 괴물아. 한판 해보자는 건가? 그렇다면 내가 싸워주지.$b$b네놈 같은 괴물이라면 무조건 상대해 주마! 내 말 알아듣겠나?', `MaleText_loc4`='退后，怪物。想打架吗？因为我就是来大打一场的。$b$b我会把你们这些怪物都打得落花流水！听懂了吗？', `MaleText_loc5`='退下，怪物。你想要戰鬥嗎?因為我願意跟你戰鬥。$b$b我願意跟你任何一個爪牙戰鬥!聽清楚沒有?', `MaleText_loc7`='Atrás, monstruo. ¿Quieres luchar? Porque yo te haré frente.$b$b¡Yo les haré frente a todos ustedes! ¿Me oyes?' WHERE `ID`=49343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말인가?$b$b좋네. 자네와 함께하거나 자네가 속한 포세이큰의 일원이 되고 싶지는 않네. 직접 이끌 포세이큰을 내가 만든다면 모를까! 팔꿈치 살도 제대로 붙어 있는 포세이큰으로 말이야!', `MaleText_loc4`='喔，真的吗？$b$b好的。我不想与你和你的被遗忘者为伍。也许我会创造属于自己的被遗忘者！也许我会创造出肘部会动的被遗忘者！', `MaleText_loc5`='噢，真的嗎?$b$b好吧。我不想加入你和你的被遺忘者。也許我會建立自己的被遺忘者!也許我會發明有手肘的被遺忘者!', `MaleText_loc7`='Oh, ¿de verdad?$b$bEstupendo. No quiero unirme a ti y a tus Renegados. ¡Quizá deba fundar mis propios Renegados! ¡Quizá invente Renegados con codos!' WHERE `ID`=49344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누굴 보고 괴물이라고 하는 건가? 괴물은 자네일세! 나는 단지 죽은 사람일 뿐이야.', `MaleText_loc4`='你叫谁怪物？你才是怪物！我只是个死去的正常人。', `MaleText_loc5`='你叫誰怪物?你才是怪物!我只是一個死掉的人。', `MaleText_loc7`='¿A quién llamas monstruo? ¡Tú eres el monstruo! Yo solo soy un tipo que ha muerto.' WHERE `ID`=49345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우러 이곳에 온 것이 아닙니다. 당신과 대화를 나눠보라고 해서 온 것뿐입니다.', `MaleText_loc4`='我不是来打架的。我只是奉命前来与你交谈。', `MaleText_loc5`='我不是來戰鬥的。只是有人要我跟你談談。', `MaleText_loc7`='No he venido a luchar. Solo me han pedido que hable contigo.', `FemaleText_loc1`='싸우러 이곳에 온 게 아니에요. 당신과 대화를 나눠보라고 해서 온 것뿐이랍니다.', `FemaleText_loc4`='我不是来打架的。我只是奉命前来与你交谈。', `FemaleText_loc5`='我不是來戰鬥的。只是有人要我跟你談談。', `FemaleText_loc7`='No he venido a luchar. Solo me han pedido que hable contigo.' WHERE `ID`=49346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하고 싶은 대로 해도 좋습니다.', `MaleText_loc4`='你想做什么都可以。', `MaleText_loc5`='隨便你想怎麼做都行。', `MaleText_loc7`='Eres libre de hacer lo que quieras.', `FemaleText_loc1`='하고 싶은 대로 해도 좋아요.', `FemaleText_loc4`='你想做什么都可以。', `FemaleText_loc5`='隨便你想怎麼做都行。', `FemaleText_loc7`='Eres libre de hacer lo que quieras.' WHERE `ID`=49347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무... 무슨 일이 일어난 거지? 당신은 누구시오? 내게 무슨 일이 일어난 것이오?', `MaleText_loc4`='什么……发生什么事了？你是谁？我这是怎么了？', `MaleText_loc5`='什麼...發生了什麼事?你是誰?我發生了什麼事情?', `MaleText_loc7`='¿Qué... qué ocurre? ¿Quién eres tú? ¿Qué me ha ocurrido?' WHERE `ID`=49348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 죽었단 말이오?$b$b그렇소, 당신 말이 맞소. 나는 죽었소. 오크 때문이었다오... 그 오크가 내 손을 자른 뒤에 죽도록 놓아두었지.$b$b<손을 내려다보는 발드레드>$b$b...이건 내 손이 아니잖아! 내 손이 아니라고!!!', `MaleText_loc4`='我……死了？$b$b是的，你说得没错。我是死了。有个兽人……他切断了我的双手，任由我死去。$b$b<瓦德雷看着自己的手。>$b$b这不是我的手！这不是我的手！', `MaleText_loc5`='我...死了?$b$b對的，你說的沒錯。我死了。是一個獸人...他切斷我的雙手，然後留下我在那裡死去。$b$b<瓦德雷低頭看自己的手。>$b$b這不是我的手!這不是我的手啊!!!', `MaleText_loc7`='¿M... morí?$b$bSí, tienes razón. Morí. Fue un orco... Me cortó las manos y me abandonó a mi muerte.$b$b<Valdred se mira las manos.>$b$b¡Estas no son mis manos! ¡ESTAS NO SON MIS MANOS!' WHERE `ID`=49349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<다시 한 번 손을 내려다보는 발드레드>$b$b아무래도 이게 내 운명인가 보군. 하! 언데드 군단의 일원이라니. 어쨌든 내가 포세이큰을 위해 싸우는 처지가 될 줄은 정말 생각해본 적도 없소.$b$b<당신을 되돌아보는 발드레드>$b$b이제 뭘 해야 하오?', `MaleText_loc4`='<瓦德雷看着自己的手。>$b$b我想这就是我的命。哈！成为亡灵大军的一员。我怎么也没想到，自己最终竟然会为被遗忘者战斗。$b$b<他抬头看着你。>$b$b我现在还有什么选择？', `MaleText_loc5`='<瓦德雷又低頭看著自己的手。>$b$b這大概就是我的命運吧。哈!不死軍團的一分子。我從來沒想過我有一天會為被遺忘者而戰。$b$b<他抬頭望向你。.>$b$b我現在該做什麼?', `MaleText_loc7`='<Valdred se mira las manos.>$b$bEntonces supongo que es mi destino. ¡Ja! Soy parte de un ejército de no-muertos. La verdad es que nunca pensé que podría acabar luchando por los Renegados.$b$b<Te mira.>$b$b¿Qué hago ahora?' WHERE `ID`=49350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠소. 자, 그러면 어서 일하러 가십시다, $n! 어둠의 여왕님께서 우리를 필요로 하시지 않소. 안 그렇소?', `MaleText_loc4`='我明白了。那好，我们开始吧，$n！黑暗女王需要我们，对吗？', `MaleText_loc5`='明白了。那就這樣吧，開始工作了，$n!黑暗女王需要我們，對吧?', `MaleText_loc7`='Entiendo. Bueno, ¡pues manos a la obra, $n! La Dama Oscura nos necesita, ¿verdad?' WHERE `ID`=49351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억 안 나십니까? 당신은 죽었습니다.', `MaleText_loc4`='你不记得了吗？你死了。', `MaleText_loc5`='你不記得了嗎?你死了。', `MaleText_loc7`='¿No lo recuerdas? Moriste.', `FemaleText_loc1`='기억 안 나세요? 당신은 죽었어요.', `FemaleText_loc4`='你不记得了吗？你死了。', `FemaleText_loc5`='你不記得了嗎?你死了。', `FemaleText_loc7`='¿No lo recuerdas? Moriste.' WHERE `ID`=49352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오, 발드레드. 장의사 모르도가 새것으로 꿰매준 것 같습니다.', `MaleText_loc4`='别激动，瓦德雷。这可能是送葬者摩尔多为你缝上的新手。', `MaleText_loc5`='冷靜點，瓦德雷。管理員摩爾多大概替你縫上新的了。', `MaleText_loc7`='Tranquilízate, Valdred. Probablemente el enterrador Mordo te cosió unas nuevas.', `FemaleText_loc1`='진정하세요, 발드레드. 장의사 모르도가 새것으로 꿰매준 것 같아요.', `FemaleText_loc4`='别激动，瓦德雷。这可能是送葬者摩尔多为你缝上的新手。', `FemaleText_loc5`='冷靜點，瓦德雷。管理員摩爾多大概替你縫上新的了。', `FemaleText_loc7`='Tranquilízate, Valdred. Probablemente el enterrador Mordo te cosió unas nuevas.' WHERE `ID`=49353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장의사 모르도와 대화해보십시오. 그가 당신이 할 일을 알려줄 것입니다. 이게 제가 아는 전부입니다.', `MaleText_loc4`='你去问送葬者摩尔多。他会告诉你该怎么做。我知道的就这么多。', `MaleText_loc5`='你和管理員摩爾多談談。他會告訴你該做什麼。我只知道這麼多。', `MaleText_loc7`='Habla con el enterrador Mordo. Él te dirá lo que tienes que hacer. Eso es todo por ahora.', `FemaleText_loc1`='장의사 모르도와 대화해보세요. 그가 당신이 할 일을 알려줄 거예요. 이게 제가 아는 전부랍니다.', `FemaleText_loc4`='你去问送葬者摩尔多。他会告诉你该怎么做。我知道的就这么多。', `FemaleText_loc5`='你和管理員摩爾多談談。他會告訴你該做什麼。我只知道這麼多。', `FemaleText_loc7`='Habla con el enterrador Mordo. Él te dirá lo que tienes que hacer. Eso es todo por ahora.' WHERE `ID`=49354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 사교계에 처음 등장하는 파티라고요. 이제 무역왕이 될 준비를 하셔야지요, $n 님!$B$B빨리 나가서 멋진 모습을 보여주세요!', `FemaleText_loc4`='这是你的大型见面会。我们要让你成为贸易大王，$n！$B$B出去显示你的权威吧！', `FemaleText_loc5`='這是你的慶祝派對。我們會幫你當上貿易$G親王:女王;，$n!$B$B好了，出去展示你的東西吧!', `FemaleText_loc7`='Es tu gran fiesta de lanzamiento. ¡Todavía podemos convertirte en $gpríncipe: princesa; mercante, $n!$B$B¡Sal ahí y haz lo que sabes hacer!' WHERE `ID`=49355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해적이요?! 어서 처리하셔야 해요! 해적이 파티를 망치고 있다고요!', `FemaleText_loc4`='海盗？！你得来解决一下，长官！他们正在毁掉派对！', `FemaleText_loc5`='海盜?!老大，你一定要處理一下!他們會毀掉派對!', `FemaleText_loc7`='¡¿Piratas?! ¡$gJefe:Jefa; tienes que encargarte de esto! ¡Están arruinando la fiesta!' WHERE `ID`=49356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 잠깐만 기다리세요. 비행선이 근처에 오려면 1분쯤 걸릴 겁니다.', `MaleText_loc4`='抓紧了。飞艇将在片刻之后抵达。', `MaleText_loc5`='別那麼猴急。飛船得要幾分鐘才能轉回來。', `MaleText_loc7`='Ahora ten paciencia. El zepelín todavía tardará un minuto en llegar, más o menos.' WHERE `ID`=49357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 그건 너무 뻔하잖아요! 놈들이 미리 대비할 겁니다!', `MaleText_loc4`='呸，不出所料！他们会看到的！', `MaleText_loc5`='哈，太容易預料了!他們會猜到的!', `MaleText_loc7`='¡Bah, es predecible! ¡Lo verán venir!' WHERE `ID`=49358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 왔군요. 준비하세요!', `MaleText_loc4`='马上就要到了。做好准备！', `MaleText_loc5`='它快要到了。準備好!', `MaleText_loc7`='Ya casi ha llegado. ¡Prepárate!' WHERE `ID`=49359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어째 느낌이 좋지 않은데요.', `FemaleText_loc4`='这看起来可不怎么样，长官。', `FemaleText_loc5`='狀況不妙啊，老大。', `FemaleText_loc7`='Esto no tiene buena pinta, $gjefe:jefa;.' WHERE `ID`=49360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행선이 왔군요! 대포 안에 들어가세요! 어서! 준비하세요!', `MaleText_loc4`='她来了！准备好火炮，该死！随时开火！', `MaleText_loc5`='她到了!準備好火砲，該死!準備發射!', `MaleText_loc7`='¡Ya está aquí! ¡Métete en ese cañón, maldita sea! ¡Prepárate para disparar!' WHERE `ID`=49361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 수를 써서든 당장 1억 마카롱을 모아야 해요!', `FemaleText_loc4`='老板，我们会想尽一切办法为你集齐一万亿杏仁币的！', `FemaleText_loc5`='老大，我們會盡全力弄個幾百億鈔票給你的!', `FemaleText_loc7`='$gJefe:Jefa;, ¡tenemos que conseguirte un bazillón de macarrones como sea!' WHERE `ID`=49362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 볼 일을 서둘러 마치세요! 무역왕이 우리 모두를 버리고 출발하기 전에 당장 항구로 가야 해요!', `FemaleText_loc4`='我们得尽快结束这里的事情，把你送到码头，趁贸易大王还没把我们大家甩在身后！', `FemaleText_loc5`='我們得快點把這裡的事情弄好，讓你趕去碼頭，免得我們被貿易親王給全部遺棄了!', `FemaleText_loc7`='¡Tenemos que terminar aquí y llevarte al muelle antes de que el Príncipe mercante nos deje atrás a todos!' WHERE `ID`=49363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기, 안녕? 어... 우리 얘기 좀 해요... 조금만 이따가.$B$B알았죠?', `FemaleText_loc4`='嗨，宝贝儿。呃……我们得谈谈，不过不是现在。$B$B好吗？', `FemaleText_loc5`='嗨，寶貝。嗯...我們得談一談，但是晚一點。$B$B好嗎?', `FemaleText_loc7`='Hola, cariño. Um... Tenemos que hablar, pero más tarde.$B$B¿Vale?' WHERE `ID`=49364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 자기, 안녕? 그래요... 우리 얘기 좀 해요.$B$B조금만 이따가, 알았죠?', `MaleText_loc4`='喔，嗨，宝贝儿。对……我们得谈谈。$B$B稍后好吗？', `MaleText_loc5`='喔，嗨，小姑娘。嗯...我們需要談談。$B$B晚一點，好嗎?', `MaleText_loc7`='Oh, hola, bomboncito. Sí... tenemos que hablar.$b$b.Más tarde, ¿vale?' WHERE `ID`=49365;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무리 광고를 한다고 해도 여기서 빠져나갈 수는 없어요. 지금 필요한 건 1억 마카롱뿐이라고요!$B$B어서 돈을 마련해서 항구로 가세요! 당장이요!', `FemaleText_loc4`='市场营销搞得再好也没办法把我们从这座岛上弄出去。我们唯一的希望就是弄到一万亿杏仁币！$B$B你最好赶紧弄到那笔钱并且送到码头去！', `FemaleText_loc5`='再怎樣搞行銷也解決不掉。這個問題只有弄到鉅額的鈔票才能搞定!$B$B你一定要弄到這筆錢，立刻趕到碼頭!', `FemaleText_loc7`='Ninguna campaña de marketing por grande que sea va a sacarnos de esta. ¡Lo único que funcionará será un bazillón de macarrones!$B$B¡Tienes que conseguir esa pasta y correr a los muelles, cuanto antes!' WHERE `ID`=49366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 진영을 향해 기습하라! $n 님이 우리와 함께하니, 승리는 우리 것이다!', `MaleText_loc4`='收割他们！$n与我们同在——胜利毫无悬念！', `MaleText_loc5`='向他們的位置衝鋒!$n跟我們在一起...我們無疑會獲得勝利!', `MaleText_loc7`='¡Asalten sus posiciones! ¡$n está con nosotros, la victoria es segura!' WHERE `ID`=49367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 날 끝내라고 겁쟁이 부하를 대신 보냈군, 그렇지?', `MaleText_loc4`='他派来个懦夫想要干掉我，是不是？', `MaleText_loc5`='他從他那群懦夫中派了一個來殺我，對吧?', `MaleText_loc7`='Ha enviado a uno de sus cobardes para matarme, ¿verdad?', `FemaleText_loc1`='놈이 날 끝내라고 겁쟁이 부하를 대신 보냈군, 그렇지?', `FemaleText_loc4`='他派来个懦夫想要干掉我，是不是？', `FemaleText_loc5`='他從他那群懦夫中派了一個來殺我，對吧?', `FemaleText_loc7`='Ha enviado a uno de sus cobardes para matarme, ¿verdad?' WHERE `ID`=49368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아직 두 발로 서 있는 동안에 끝내 다오...', `MaleText_loc4`='趁我还站在这儿，赶快动手……', `MaleText_loc5`='在我站著的時候動手吧...', `MaleText_loc7`='Hazlo mientras siga en pie...', `FemaleText_loc1`='내가 아직 두 발로 서 있는 동안에 끝내 다오...', `FemaleText_loc4`='趁我还站在这儿，赶快动手……', `FemaleText_loc5`='在我站著的時候動手吧...', `FemaleText_loc7`='Hazlo mientras siga en pie...' WHERE `ID`=49369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=49370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 그대에게 무슨 짓을 한 거요, $n?', `MaleText_loc4`='$n，我到哪里都能认出那张脸……他们……他们对你做了什么，$n？', `MaleText_loc5`='$n，不管何地我都能認出這張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería esa cara en cualquier parte... ¿Qué...? ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있소... 도대체... 저들이 그대에게 무슨 짓을 한 거요, $n?', `FemaleText_loc4`='$n，我到哪里都能认出那张脸……他们……他们对你做了什么，$n？', `FemaleText_loc5`='$n，不管何地我都能認出這張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería esa cara en cualquier parte... ¿Qué...? ¿Qué te han hecho, $n?' WHERE `ID`=49371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기억하지 못하는군? 우리 둘 다 은빛소나무 숲에서 아루갈의 하수인이었소. 우린 오랜 세월 동안 그의 무자비한 고문을 견뎠지. 그림자송곳니 성채를 탈출하던 그 운명의 밤에, 바로 그대가 내 목숨을 구했소. 그대가 아니었다면 난 죽었을 거요. 그런 그대가! 그대는 내가 아는 모든 늑대인간 중 가장 고귀한 이였소. 놈들이 무슨 짓을 한 거요, $n? 어떻게 이런 일이 벌어질 수가 있소?', `MaleText_loc4`='你不记得我了吗？我们都曾是银松森林中阿鲁高的仆从。多年来一直忍受着他惨无人道的折磨。在改变命运的那一晚——我们从影牙城堡中逃离，是你救了我。如果没有你，我早就死了。是你！我所认识的最高贵的狼人！他们对你做了什么，$n？这怎么可能？', `MaleText_loc5`='你不記得我了?在銀松森林的時候，我們都是阿魯高的僕人。我們多年來一直受到他無情的折磨。在那個宿命的夜晚，我們逃出影牙城堡時是你救了我。沒有你，我早已經死了。你!我所認識最高貴的狼人。他們對你做的什麼，$n?怎麼會發生這種事?', `MaleText_loc7`='¿No te acuerdas de mí? Los dos éramos sirvientes de Arugal en el Bosque de Argénteos. Aguantamos su cruel tortura durante siglos. Fuiste tú el que me salvaste aquella fatídica noche cuando escapamos del Castillo de Colmillo Oscuro. Si no hubiera sido por ti, habría muerto. ¡TÚ! El huargen más noble que he conocido nunca. ¿Qué te han hecho, $n? ¿Cómo ha podido ocurrir esto?', `FemaleText_loc1`='날 기억하지 못하는군? 우리 둘 다 은빛소나무 숲에서 아루갈의 하수인이었소. 우린 오랜 세월 동안 그의 무자비한 고문을 견뎠지. 그림자송곳니 성채를 탈출하던 그 운명의 밤에, 바로 그대가 내 목숨을 구했소. 그대가 아니었다면 난 죽었을 거요. 그런 그대가! 그대는 내가 아는 모든 늑대인간 중 가장 고귀한 이였소. 놈들이 무슨 짓을 한 거요, $n? 어떻게 이런 일이 벌어질 수가 있소?', `FemaleText_loc4`='你不记得我了吗？我们都曾是银松森林中阿鲁高的仆从。多年来一直忍受着他惨无人道的折磨。在改变命运的那一晚——我们从影牙城堡中逃离，是你救了我。如果没有你，我早就死了。是你！我所认识的最高贵的狼人！他们对你做了什么，$n？这怎么可能？', `FemaleText_loc5`='你不記得我了?在銀松森林的時候，我們都是阿魯高的僕人。我們多年來一直受到他無情的折磨。在那個宿命的夜晚，我們逃出影牙城堡時是你救了我。沒有你，我早已經死了。你!我所認識最高貴的狼人。他們對你做的什麼，$n?怎麼會發生這種事?', `FemaleText_loc7`='¿No te acuerdas de mí? Los dos éramos sirvientes de Arugal en el Bosque de Argénteos. Aguantamos su cruel tortura durante siglos. Fuiste tú el que me salvaste aquella fatídica noche cuando escapamos del Castillo de Colmillo Oscuro. Si no hubiera sido por ti, habría muerto. ¡TÚ! El huargen más noble que he conocido nunca. ¿Qué te han hecho, $n? ¿Cómo ha podido ocurrir esto?' WHERE `ID`=49372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 등이야!', `MaleText_loc4`='啊，我的背！', `MaleText_loc5`='啊，我的背!', `MaleText_loc7`='¡Ah, mi espalda!' WHERE `ID`=49373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 늑대인간이었을 때의 모습을 떠올려 보시오, $g형제여:자매여;! 그대는 우리의 구세주였소! 굴복하지 마시오!', `MaleText_loc4`='记得你曾经是个多么伟大的狼人，$g兄弟:姐妹;！你是我们的救星！奋力战斗！', `MaleText_loc5`='快想起你曾經是什麼樣的狼人，$g兄弟:姊妹;!你是我們的救星!對抗它!', `MaleText_loc7`='¡Recuerda el huargen que fuiste una vez, $ghermano:hermana;! ¡Fuiste $gnuestro salvador:nuestra salvadora;! ¡Combátelo!', `FemaleText_loc1`='그대가 늑대인간이었을 때의 모습을 떠올려 보시오, $g형제여:자매여;! 그대는 우리의 구세주였소! 굴복하지 마시오!', `FemaleText_loc4`='记得你曾经是个多么伟大的狼人，$g兄弟:姐妹;！你是我们的救星！奋力战斗！', `FemaleText_loc5`='快想起你曾經是什麼樣的狼人，$g兄弟:姊妹;!你是我們的救星!對抗它!', `FemaleText_loc7`='¡Recuerda el huargen que fuiste una vez, $ghermano:hermana;! ¡Fuiste $gnuestro salvador:nuestra salvadora;! ¡Combátelo!' WHERE `ID`=49374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 그대가 그의 목적을 이루는 도구로 이용당해서는 안 되오. 그대는 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!', `MaleText_loc4`='听我说，$n。你必须对抗巫妖王的掌控。他是个恶魔，想要让这个世界——我们的世界——毁灭。别让他利用你实现自己的阴谋。你曾经是个英雄，现在也一定能不辱使命。战斗吧！结束他的掌控！', `MaleText_loc5`='聽我說，$n。你必須對抗巫妖王的控制。他是個怪物，想要看到這個世界，看到我們的世界變為廢墟。不要讓他利用你完成他的目標。你曾經是個英雄，你還能再度成為英雄。對抗它啊，該死!對抗他的控制!', `MaleText_loc7`='Escúchame, $n. Tienes que luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, en ruinas. No le permitas conseguir sus objetivos. Una vez fuiste $gun héroe:una heroína; y puedes serlo de nuevo. ¡Combátelo, maldita sea! ¡Combate su control!', `FemaleText_loc1`='내 말을 들으시오, $n. 리치 왕의 제어에서 벗어나야 하오. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라오. 그대가 그의 목적을 이루는 도구로 이용당해서는 안 되오. 그대는 영웅이었으며 다시 영웅이 될 수 있소. 싸우란 말이오, 제기랄! 그의 제어에서 벗어나시오!', `FemaleText_loc4`='听我说，$n。你必须对抗巫妖王的掌控。他是个恶魔，想要让这个世界——我们的世界——毁灭。别让他利用你实现自己的阴谋。你曾经是个英雄，现在也一定能不辱使命。战斗吧！结束他的掌控！', `FemaleText_loc5`='聽我說，$n。你必須對抗巫妖王的控制。他是個怪物，想要看到這個世界，看到我們的世界變為廢墟。不要讓他利用你完成他的目標。你曾經是個英雄，你還能再度成為英雄。對抗它啊，該死!對抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Tienes que luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, en ruinas. No le permitas conseguir sus objetivos. Una vez fuiste $gun héroe:una heroína; y puedes serlo de nuevo. ¡Combátelo, maldita sea! ¡Combate su control!' WHERE `ID`=49375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 길니아스를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.', `MaleText_loc4`='已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住吉尔尼斯，我们挚爱的家园。这个世界值得我们去拯救。', `MaleText_loc5`='我...我已經沒有時間了。我已經玩完了。給我個痛快，$n。動手吧，否則我們都會被殺掉。$n...記得吉爾尼斯，我們摯愛的家園。這個世界值得拯救。', `MaleText_loc7`='Ya... ya no me queda tiempo. Ha llegado mi fin. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Gilneas, nuestro amado hogar. Merece la pena salvar el mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없소. 난 이제 틀렸소이다. 날 죽여 주시오. 그러지 않으면 저들이 우리 둘 다 죽일 거요. $n... 길니아스를 기억하시오. 이 세상은 지켜낼 가치가 있는 곳이라오.', `FemaleText_loc4`='已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住吉尔尼斯，我们挚爱的家园。这个世界值得我们去拯救。', `FemaleText_loc5`='我...我已經沒有時間了。我已經玩完了。給我個痛快，$n。動手吧，否則我們都會被殺掉。$n...記得吉爾尼斯，我們摯愛的家園。這個世界值得拯救。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Ha llegado mi fin. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Gilneas, nuestro amado hogar. Merece la pena salvar el mundo.' WHERE `ID`=49376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!', `MaleText_loc4`='快动手，$n！结束我的痛苦！', `MaleText_loc5`='動手，$n!終結我的痛苦!', `MaleText_loc7`='¡Hazlo, $n! ¡Pon fin a mi sufrimiento!', `FemaleText_loc1`='어서 날 죽이시오, $n! 비참한 내 생명을 끊어달란 말이오!', `FemaleText_loc4`='快动手，$n！结束我的痛苦！', `FemaleText_loc5`='動手，$n!終結我的痛苦!', `FemaleText_loc7`='¡Hazlo, $n! ¡Pon fin a mi sufrimiento!' WHERE `ID`=49377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因伤死去。', `MaleText_loc5`='%s因傷而死。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因伤死去。', `FemaleText_loc5`='%s因傷而死。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=49378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 무슨 일이오? 왜 이렇게 오래 걸리지, $n?', `MaleText_loc4`='那里发生了什么事？怎么会这么久，$n？', `MaleText_loc5`='裡面發生了什麼事?為什麼花那麼久，$n?', `MaleText_loc7`='¿Qué ocurre aquí? ¿Qué es lo que te lleva tanto tiempo, $n?' WHERE `ID`=49379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀... 어떻게 다른 방식으로 해결할 순 없는 건가?', `MaleText_loc4`='我们……我们不能想想办法吗？', `MaleText_loc5`='我...我們不能想想辦法解決這一切嗎?', `MaleText_loc7`='¿No... no podemos encontrar otra solución?', `FemaleText_loc1`='좀... 어떻게 다른 방식으로 해결할 순 없는 건가?', `FemaleText_loc4`='我们……我们不能想想办法吗？', `FemaleText_loc5`='我...我們不能想想辦法解決這一切嗎?', `FemaleText_loc7`='¿No... no podemos encontrar otra solución?' WHERE `ID`=49380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다고... 그냥... 내가 일어날 동안만... 기다려 달라고...', `MaleText_loc4`='好，让我……让我……站……起来。', `MaleText_loc5`='好吧，讓...讓我...讓我先...先站起來。', `MaleText_loc7`='Está bien, d-deja... que me ponga... de p-pie.', `FemaleText_loc1`='좋다고... 그냥... 내가 일어날 동안만... 기다려 달라고...', `FemaleText_loc4`='好，让我……让我……站……起来。', `FemaleText_loc5`='好吧，讓...讓我...讓我先...先站起來。', `FemaleText_loc7`='Está bien, d-deja... que me ponga... de p-pie.' WHERE `ID`=49381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n?', `MaleText_loc4`='$n？', `MaleText_loc5`='$n?', `MaleText_loc7`='¿$n?', `FemaleText_loc1`='$n?', `FemaleText_loc4`='$n？', `FemaleText_loc5`='$n?', `FemaleText_loc7`='¿$n?' WHERE `ID`=49382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있다고... 도대체... 저들이 자네에게 무슨 짓을 한 거야, $n?', `MaleText_loc4`='$n，我到哪里都能认出那张脸……他们……他们对你做了什么，$n？', `MaleText_loc5`='$n，不管何地我都能認出這張臉...他們...他們對你做了什麼，$n?', `MaleText_loc7`='$n, reconocería esa cara en cualquier parte... ¿Qué...? ¿Qué te han hecho, $n?', `FemaleText_loc1`='$n, 어디서든 그 얼굴은 알아볼 수 있다고... 도대체... 저들이 자네에게 무슨 짓을 한 거야, $n?', `FemaleText_loc4`='$n，我到哪里都能认出那张脸……他们……他们对你做了什么，$n？', `FemaleText_loc5`='$n，不管何地我都能認出這張臉...他們...他們對你做了什麼，$n?', `FemaleText_loc7`='$n, reconocería esa cara en cualquier parte... ¿Qué...? ¿Qué te han hecho, $n?' WHERE `ID`=49383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 기억하지 못하는 거야, $n? 자네랑 나랑 케잔에서 사업 벌여서 많이도 말아먹었잖아. 그러다가 내가 카자콜라에 중독됐고, 자네가 날 구했지! 날 칼림도어로 데려와서 스팀휘들 무역회사에 들어가게 해줬고 말이야. 자넨 내가 아는 고블린 중 유일하게 착한 놈이라고. 그래서 내가 결국 은빛 여명회에 들어온 거야. 자네라면 분명히 이런 일을 하리라 생각했거든. 그런데 어떻게 자네가 이렇게 될 수가 있어?', `MaleText_loc4`='你不记得我了吗，$n？你我在科赞共度的那段日子里，我丢掉了一份又一份工作。后来我还染上了爱喝卡亚可乐的瘾，是你救了我！是你把我带到卡利姆多，加入了热砂集团。你是我所见过唯一善良的地精。正是出于对你的了解，我才落入银色黎明手中。你怎么会变成这样？', `MaleText_loc5`='你不記得我了，$n?我已經忘記當年在凱贊你跟我一起完成過多少任務了。然後我染上了喝卡迦可樂的惡習，是你救了我!是你帶我到卡林多加入熱砂企業。你是唯一我認識的好心哥布林。這就是為什麼我最後會加入銀色黎明，因為我知道如果是你就會這麼做。怎麼會發生這種事情在你身上?', `MaleText_loc7`='¿No te acuerdas de mí, $n? He perdido la cuenta de la cantidad de trabajos que tú y yo realizamos en los tiempos de Kezan. ¡Después me hice terriblemente adicto a la Kaja''Cola y tú me salvaste! Fuiste tú el que me llevó a Kalimdor para que me uniera al Cártel Bonvapor. Eras el único goblin bueno que conocía. Así es como terminé en el Alba Argenta, porque sabía que era lo que habrías hecho tú. ¿Cómo ha podido pasarte esto?', `FemaleText_loc1`='날 기억하지 못하는 거야, $n? 자네랑 나랑 케잔에서 사업 벌여서 많이도 말아먹었잖아. 그러다가 내가 카자콜라에 중독됐고, 자네가 날 구했지! 날 칼림도어로 데려와서 스팀휘들 무역회사에 들어가게 해줬고 말이야. 자넨 내가 아는 고블린 중 유일하게 착한 놈이라고. 그래서 내가 결국 은빛 여명회에 들어온 거야. 자네라면 분명히 이런 일을 하리라 생각했거든. 그런데 어떻게 자네가 이렇게 될 수가 있어?', `FemaleText_loc4`='你不记得我了吗，$n？你我在科赞共度的那段日子里，我丢掉了一份又一份工作。后来我还染上了爱喝卡亚可乐的瘾，是你救了我！是你把我带到卡利姆多，加入了热砂集团。你是我所见过唯一善良的地精。正是出于对你的了解，我才落入银色黎明手中。你怎么会变成这样？', `FemaleText_loc5`='你不記得我了，$n?我已經忘記當年在凱贊你跟我一起完成過多少任務了。然後我染上了喝卡迦可樂的惡習，是你救了我!是你帶我到卡林多加入熱砂企業。你是唯一我認識的好心哥布林。這就是為什麼我最後會加入銀色黎明，因為我知道如果是你就會這麼做。怎麼會發生這種事情在你身上?', `FemaleText_loc7`='¿No te acuerdas de mí, $n? He perdido la cuenta de la cantidad de trabajos que tú y yo realizamos en los tiempos de Kezan. ¡Después me hice terriblemente adicto a la Kaja''Cola y tú me salvaste! Fuiste tú el que me llevó a Kalimdor para que me uniera al Cártel Bonvapor. Eras el único goblin bueno que conocía. Así es como terminé en el Alba Argenta, porque sabía que era lo que habrías hecho tú. ¿Cómo ha podido pasarte esto?' WHERE `ID`=49384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 고블린이었을 때의 모습을 떠올려 보라고, 친구! 자넨 내 가장 친한 친구였잖아! 굴복하지 말라고!', `MaleText_loc4`='记得你曾经是个多么伟大的地精，$g兄弟:姐妹;！你曾是我最好的朋友！奋力战斗！', `MaleText_loc5`='快想起你曾經是什麼樣的哥布林，$g兄弟:姊妹;!你曾經是我最好的朋友!對抗它!', `MaleText_loc7`='¡Recuerda el goblin que fuiste una vez, $ghermano:hermana;! ¡Fuiste $gnuestro salvador:nuestra salvadora;! ¡Combátelo!', `FemaleText_loc1`='자네가 고블린이었을 때의 모습을 떠올려 보라고, 친구! 자넨 내 가장 친한 친구였잖아! 굴복하지 말라고!', `FemaleText_loc4`='记得你曾经是个多么伟大的地精，$g兄弟:姐妹;！你曾是我最好的朋友！奋力战斗！', `FemaleText_loc5`='快想起你曾經是什麼樣的哥布林，$g兄弟:姊妹;!你曾經是我最好的朋友!對抗它!', `FemaleText_loc7`='¡Recuerda el goblin que fuiste una vez, $ghermano:hermana;! ¡Fuiste $gnuestro salvador:nuestra salvadora;! ¡Combátelo!' WHERE `ID`=49385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 들으라고, $n. 리치 왕의 제어에서 벗어나야 해. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라고. 자네가 그의 목적을 이루는 도구로 이용당해서는 안 돼. 자넨 영웅이었고, 다시 영웅이 될 수 있다고. 싸우란 말이야, 제기랄! 그의 제어에서 벗어나라고!', `MaleText_loc4`='听我说，$n。你必须对抗巫妖王的掌控。他是个恶魔，想要让这个世界——我们的世界——毁灭。别让他利用你实现自己的阴谋。你曾经是个英雄，现在也一定能不辱使命。战斗吧！结束他的掌控！', `MaleText_loc5`='聽我說，$n。你必須對抗巫妖王的控制。他是個怪物，想要看到這個世界，看到我們的世界變為廢墟。不要讓他利用你完成他的目標。你曾經是個英雄，你還能再度成為英雄。對抗它啊，該死!對抗他的控制!', `MaleText_loc7`='Escúchame, $n. Tienes que luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, en ruinas. No le permitas conseguir sus objetivos. Una vez fuiste $gun héroe:una heroína; y puedes serlo de nuevo. ¡Combátelo, maldita sea! ¡Combate su control!', `FemaleText_loc1`='내 말 들으라고, $n. 리치 왕의 제어에서 벗어나야 해. 그는 이 세상을... 폐허로 된 우리의 세계를 보고자 하는 악마라고. 자네가 그의 목적을 이루는 도구로 이용당해서는 안 돼. 자넨 영웅이었고, 다시 영웅이 될 수 있다고. 싸우란 말이야, 제기랄! 그의 제어에서 벗어나라고!', `FemaleText_loc4`='听我说，$n。你必须对抗巫妖王的掌控。他是个恶魔，想要让这个世界——我们的世界——毁灭。别让他利用你实现自己的阴谋。你曾经是个英雄，现在也一定能不辱使命。战斗吧！结束他的掌控！', `FemaleText_loc5`='聽我說，$n。你必須對抗巫妖王的控制。他是個怪物，想要看到這個世界，看到我們的世界變為廢墟。不要讓他利用你完成他的目標。你曾經是個英雄，你還能再度成為英雄。對抗它啊，該死!對抗他的控制!', `FemaleText_loc7`='Escúchame, $n. Tienes que luchar contra el control del Rey Exánime. Es un monstruo que quiere ver este mundo, nuestro mundo, en ruinas. No le permitas conseguir sus objetivos. Una vez fuiste $gun héroe:una heroína; y puedes serlo de nuevo. ¡Combátelo, maldita sea! ¡Combate su control!' WHERE `ID`=49386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠... 내게 더 남은 시간이 없어. 난 이제 틀렸다고. 날 죽여 줘. 그러지 않으면 저들이 우리 둘 다 죽일 거야. $n... 우리의 고향, 케잔을 기억하라고. 이 세상은 지켜낼 가치가 있는 곳이야.', `MaleText_loc4`='已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住科赞，我们挚爱的家园。这个世界值得我们去拯救。', `MaleText_loc5`='我...我已經沒有時間了。我已經玩完了。給我個痛快，$n。動手吧，否則我們都會被殺掉。$n...記得凱贊，我們摯愛的家園。這個世界值得拯救。', `MaleText_loc7`='Ya... ya no me queda tiempo. Ha llegado mi fin. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Kezan nuestro amado hogar. Merece la pena salvar el mundo.', `FemaleText_loc1`='이젠... 내게 더 남은 시간이 없어. 난 이제 틀렸다고. 날 죽여 줘. 그러지 않으면 저들이 우리 둘 다 죽일 거야. $n... 우리의 고향, 케잔을 기억하라고. 이 세상은 지켜낼 가치가 있는 곳이야.', `FemaleText_loc4`='已经……已经来不及了。我完了。结束我吧，$n。否则他们会把我们俩都杀死。$n……记住科赞，我们挚爱的家园。这个世界值得我们去拯救。', `FemaleText_loc5`='我...我已經沒有時間了。我已經玩完了。給我個痛快，$n。動手吧，否則我們都會被殺掉。$n...記得凱贊，我們摯愛的家園。這個世界值得拯救。', `FemaleText_loc7`='Ya... ya no me queda tiempo. Ha llegado mi fin. Acaba conmigo, $n. Hazlo o nos matarán a los dos. $n... Recuerda Kezan nuestro amado hogar. Merece la pena salvar el mundo.' WHERE `ID`=49387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 날 죽여, $n! 비참한 내 생명을 끊어달란 말이야!', `MaleText_loc4`='快动手，$n！结束我的痛苦！', `MaleText_loc5`='動手，$n!終結我的痛苦!', `MaleText_loc7`='¡Hazlo, $n! ¡Pon fin a mi sufrimiento!', `FemaleText_loc1`='어서 날 죽여, $n! 비참한 내 생명을 끊어달란 말이야!', `FemaleText_loc4`='快动手，$n！结束我的痛苦！', `FemaleText_loc5`='動手，$n!終結我的痛苦!', `FemaleText_loc7`='¡Hazlo, $n! ¡Pon fin a mi sufrimiento!' WHERE `ID`=49388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `MaleText_loc4`='%s因伤死去。', `MaleText_loc5`='%s因傷而死。', `MaleText_loc7`='%s muere a causa de sus heridas.', `FemaleText_loc1`='%s|1이;가; 심한 부상으로 목숨을 잃습니다.', `FemaleText_loc4`='%s因伤死去。', `FemaleText_loc5`='%s因傷而死。', `FemaleText_loc7`='%s muere a causa de sus heridas.' WHERE `ID`=49389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야! 이리 내려와, 부리부리야!', `MaleText_loc4`='尖喙！到这儿来，尖喙！', `MaleText_loc5`='比克!下來這裡，比克!', `MaleText_loc7`='¡Pico! ¡Ven aquí abajo, Pico!' WHERE `ID`=49390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아으으, 이리 와, 부리부리야. 방금 그건 아무것도 아니야. 그냥... 큰 촉수일 뿐이라고. 도넬리가 지켜 줄게!', `MaleText_loc4`='啊，别怕尖喙。那只不过是个大大的……触手。东尼利会保护我们的！', `MaleText_loc5`='噢，幫幫忙，比克。那只是一隻很大的...觸鬚怪物。多涅爾利會保護你的!', `MaleText_loc7`='Ah, venga, Pico. No era más que un gran... cosa con tentáculos. ¡Donnelly se asegurará de que estés a salvo!' WHERE `ID`=49391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해, 부리부리야. 이리 오라니까!', `MaleText_loc4`='别怕，尖喙。回到这儿来！', `MaleText_loc5`='放輕鬆，比克。回來這裡!', `MaleText_loc7`='Tranquilo, Pico. ¡Vuelve aquí!' WHERE `ID`=49392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮아, 부리부리야. 도넬리한테 돌아와!', `MaleText_loc4`='你安全了，尖喙。到东尼利这儿来！', `MaleText_loc5`='你安全了，比克。回來多涅爾利這裡!', `MaleText_loc7`='Ahora estás a salvo, Pico. ¡Vamos a regresar con Donnelly!' WHERE `ID`=49393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리부리야. 부리부리야!', `MaleText_loc4`='尖喙。尖喙！', `MaleText_loc5`='比克。比克!', `MaleText_loc7`='Pico. ¡Pico!' WHERE `ID`=49394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암... 내가 자넬... 사랑하고말고... *딸꾹* 친형제처럼 말이야!', `MaleText_loc4`='我爱你伙计……（嗝儿）如同兄长！', `MaleText_loc5`='我很愛你啊...*嗝*就像兄弟一樣!', `MaleText_loc7`='Tíooooooooo, yo te quiero... *hic* ¡Como a un HERMANO!' WHERE `ID`=49395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮은 녀석이지... 파이어비어드... *끄윽* 괜찮은 녀석이고말고.', `MaleText_loc4`='你很好，焰须。（嗝儿）我喜欢你。', `MaleText_loc5`='你還不錯，火鬍。*嘔*你在我眼中相當不錯。', `MaleText_loc7`='No estás nada mal, Barbafuego. *urp* Te doy mi aprobación.' WHERE `ID`=49396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그게... 우리 와일드해머... 결혼식이지! 아무렴... *딸꾹* 정말... 끝내줬다고!', `MaleText_loc4`='我们蛮锤部族缔结百年之好……正像那样。（嗝儿）简直太美了！', `MaleText_loc5`='咱們蠻錘就是這樣...結婚的，就是這樣。*嗝*那真是美呆了!', `MaleText_loc7`='Así es como nos casamos... los Martillo Salvaje, sí. *hic* ¡Ha sido PRECIOSO!' WHERE `ID`=49397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*딸꾹* 이봐... 파이어비어드... 자네랑 나랑... 와일드해머... 영원하라!', `MaleText_loc4`='（嗝儿）你和我，焰须。蛮锤情谊永存。', `MaleText_loc5`='*嗝*你跟我，火鬍。永遠的蠻錘。', `MaleText_loc7`='*hic* Tú y yo, Barbafuego. Martillo Salvaje PARA SIEMPRE.' WHERE `ID`=49398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고! 이번 결혼식! 최고! *딸꾹*', `MaleText_loc4`='无与伦比的！婚礼！（嗝儿）', `MaleText_loc5`='最!讚!的!婚禮!*嗝*', `MaleText_loc7`='¡LA MEJOR BODA DE LA HISTORIA!*Hic*' WHERE `ID`=49399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머는 모두 함께... *딸꾹* 다 쓸어버린다!', `MaleText_loc4`='蛮锤朝夕共度，比肩杀敌！', `MaleText_loc5`='齊心的蠻錘是無堅不摧的!', `MaleText_loc7`='¡Los Martillo Salvaje que permanecen unidos, matan unidos!' WHERE `ID`=49400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 망치단 따위에게 내가 겁먹을 것 같으냐! 다 덤벼!', `FemaleText_loc4`='暮光之锤吓不倒我。尽管来吧！', `FemaleText_loc5`='暮光之錘我沒在怕的啦!放馬過來!', `FemaleText_loc7`='Los del Martillo Crepuscular no me asustan. ¡A por ellos!' WHERE `ID`=49401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와아아일드해머어어어!', `FemaleText_loc4`='蛮——锤！', `FemaleText_loc5`='蠻—錘—萬—歲!', `FemaleText_loc7`='¡Maaaartillooooooo Salvajeeeeee!' WHERE `ID`=49402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잡아라! 없애라!', `FemaleText_loc4`='抓住它！杀了它！', `FemaleText_loc5`='我瞭!我殺!', `FemaleText_loc7`='¡A por él! ¡Mátalo!' WHERE `ID`=49403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 준비됐네. 자네만 준비되면 결혼식을 시작하지! 황혼의 망치단 놈들이 무슨 짓을 벌일지 모르니 신랑과 신부는 내 곁에 두겠네.$B$B준비됐나?', `MaleText_loc4`='等你准备好，就可以开始了！我会紧跟新郎新娘，以防暮光之锤有任何图谋。$B$B你准备好了吗？', `MaleText_loc5`='等你準備好，我隨時可以開始!我會待在新郎新娘身邊，以免暮光之錘想搞什麼花樣。$B$B準備好了嗎?', `MaleText_loc7`='¡Estoy listo para empezar cuando tú lo estés! Mantendré cerca al novio y a la novia por si el Martillo Crepuscular intenta algo.$B$B¿$gPreparado:Preparada;?' WHERE `ID`=49404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑 파라오가 쓰러졌다! 불멸의 거대괴수도 장난감처럼 부서져 내린다!', `MaleText_loc4`='黑暗法老倒下了！他那不朽的巨像犹如玩具一般地打着滚！', `MaleText_loc5`='黑暗法老倒下了!他的不朽巨像有如玩具一樣散落在地!', `MaleText_loc7`='¡El Faraón oscuro ha caído! ¡Sus inmortales colosos se desmoronan como juguetes!' WHERE `ID`=49405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네페르세트 도시도 무너질 것이다! 공격하라!!!', `MaleText_loc4`='尼斐塞特城将要陷落！攻击！！！', `MaleText_loc5`='奈斐賽特城將會陷落!攻擊!', `MaleText_loc7`='¡La Ciudad de Neferset caerá! ¡¡ATAQUEN!!' WHERE `ID`=49406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄을 설치했습니다! 자리를 피하십시오!', `MaleText_loc4`='炸弹即将爆炸！都让开！', `MaleText_loc5`='炸彈安裝好了!快離開!', `MaleText_loc7`='¡La bomba está preparada! ¡Fuera!' WHERE `ID`=49407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발드레드 모레이, 임무 보고합니다!', `MaleText_loc4`='瓦德雷·莫莱前来报到，长官！', `MaleText_loc5`='瓦德雷·莫萊，前來報到，長官!', `MaleText_loc7`='¡Valdred Moray presentándose para el servicio, señor!' WHERE `ID`=49408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비의 총공격이 시작됐습니다!', `MaleText_loc4`='一大波僵尸正在靠近！', `MaleText_loc5`='一大群的殭屍正在接近中!', `MaleText_loc7`='¡Se acerca una gigantesca oleada de zombis!', `FemaleText_loc1`='좀비의 총공격이 시작됐습니다!', `FemaleText_loc4`='一大波僵尸正在靠近！', `FemaleText_loc5`='一大群的殭屍正在接近中!', `FemaleText_loc7`='¡Se acerca una gigantesca oleada de zombis!' WHERE `ID`=49409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 누군가 저 흉측한 놈을 없애 줬군. 정말 고맙다, 영웅들이여.', `MaleText_loc4`='终于有人帮我除掉了那只丑陋的害虫！向你致敬，“英雄”们。', `MaleText_loc5`='終於有人能解決那隻難看的蟲子!多虧你們了啊，「英雄們」。', `MaleText_loc7`='¡Al fin alguien que se encarga de esa peste! Les agradezco, "héroes".' WHERE `ID`=49410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 수리비만 잡아먹는 불량품, 쓰레기였어.', `MaleText_loc4`='这下不用再为那堆垃圾付修理费了。', `MaleText_loc5`='終於不用替那台常失靈的垃圾付修理費了。', `MaleText_loc7`='Esa chatarra era un gasto de reparación constante.' WHERE `ID`=49411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그렇게까지 할 필요는 없잖아!', `MaleText_loc4`='这次可真有点过分了。', `MaleText_loc5`='這樣就有點過分了。', `MaleText_loc7`='Eso no era necesario.' WHERE `ID`=49412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군. 내가 만든 가장 끔찍한 피조물을 파괴했구나. 아무도 그놈은 못 이길 줄 알았는데.', `MaleText_loc4`='了不起。你们毁掉了我最恐怖的造物之一。我原以为这是不可能的。', `MaleText_loc5`='了不起。你摧毀了我最可怕的創造物之一。我原本以為這是不可能辦到的事情。', `MaleText_loc7`='Impresionante. Has destruido una de mis creaciones más horrorosas. Algo que había creído imposible.' WHERE `ID`=49413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어차피 마음에 안 드는 놈이었어... 잘 처치했다!', `MaleText_loc4`='我们总是意见不合……终于摆脱他了！', `MaleText_loc5`='我們常常意見不和。總算擺脫他了!', `MaleText_loc7`='Nunca nos llevamos bien... ¡Hasta nunca pues!' WHERE `ID`=49414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 내 거처에 온 걸 환영한다! 이곳이 너희 마음에 들었으면 좋겠군. 여기서 너흰 내 실험의 실패작들을 마주하고, 결국엔 내 최고의 성공작도 보게 될 것이다!', `MaleText_loc4`='欢迎来到我的私家圣殿，英雄们！希望你们能有宾至如归的感觉。你们能在这里见到许多我的失败实验品，但最终将见证我最伟大的胜利！', `MaleText_loc5`='歡迎來到我私人的聖殿，英雄們!希望你們感到賓至如歸。在這裡你們會看到我許多的失敗品，最終還會看到我最偉大的勝利!', `MaleText_loc7`='¡Bienvenidos a mi sagrario, héroes! Espero que les guste su visita. ¡Aquí encontrarán mis experimentos fallidos y mi más grande triunfo!' WHERE `ID`=49415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕이 되살아났다! 자, 오닉시아를 맞이하라... 내 작품 중 최고라고 할 수 있지.', `MaleText_loc4`='见证龙巢之母——奥妮克希亚的重生！这也许是我最高的杰作。', `MaleText_loc5`='看看黑龍公主奧妮克希亞的重生!這大概是我最佳的傑作。', `MaleText_loc7`='¡La madre de linaje, Onyxia, RENACIDA! Quizás mi mejor creación.' WHERE `ID`=49416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑하는 나의 자매여, 배가 고픈가? 그럼 우리 적을 먹어치워라!', `MaleText_loc4`='我最亲爱的妹妹，你饿了吗？那就吃掉我们的敌人吧！', `MaleText_loc5`='我的妹妹，餓了嗎?以我們的敵人為食吧!', `MaleText_loc7`='Hermana, ¿tienes hambre? ¡DEVORA A NUESTROS ENEMIGOS!' WHERE `ID`=49417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑불길이 어떻게 뼈를 일으키는지 봐라! 저들은 내 명에 따라 싸우지!', `MaleText_loc4`='暗影烈焰为他们的骨骼注入了活力！他们为我而战！', `MaleText_loc5`='看到暗影之焰是如何活化他們的骨頭了嗎?他們都為我而戰!', `MaleText_loc7`='¡La llama de las sombras los reanima! ¡Luchan a mis órdenes!' WHERE `ID`=49418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살을 재로 만들어 주마!', `MaleText_loc4`='血肉化为灰烬！', `MaleText_loc5`='化為灰燼吧!', `MaleText_loc7`='¡Carne a ceniza!' WHERE `ID`=49419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받을 필멸자들! 내 소중한 작품을 이렇게 망치다니! 쓴맛을 봐야 정신을 차리겠군!', `MaleText_loc4`='诅咒你们，凡人！你们丝毫不尊重他人财产的行为必须受到严厉处罚！', `MaleText_loc5`='詛咒你們，凡人!如此冷酷地漠視他人的所有物必須受到嚴厲的懲罰!', `MaleText_loc7`='¡Malditos mortales! ¡Tal negligencia con las posesiones ajenas debe ser castigada!' WHERE `ID`=49420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수영은 할 줄 알겠지... 용암 속에서 말이다!', `MaleText_loc4`='希望你会游泳……在岩浆里！', `MaleText_loc5`='希望你知道怎樣在熔岩裡游泳!', `MaleText_loc7`='¡Naden... en lava ardiente!' WHERE `ID`=49421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='품위있는 집주인답게 행동하려 했건만, 네놈들이 도무지 죽질 않는군! 겉치레는 이제 집어치우자고. 그냥 모두 없애 버리겠어!', `MaleText_loc4`='我一直在尝试扮演好客的主人，可你们就是不肯受死！该卸下伪装了……杀光你们！', `MaleText_loc5`='我本來只想略盡地主之誼，但是你們就是不肯痛快的受死!是時候拋下一切的虛偽...殺光你們就好!', `MaleText_loc7`='¡He intentado ser un buen anfitrión, pero rehusaron morir! Hora de dejar de fingir y... ¡MATARLOS A TODOS!' WHERE `ID`=49422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들의 마음은... 조종하기 쉽지.', `MaleText_loc4`='凡人的心智……真是容易控制。', `MaleText_loc5`='凡人的心智...真是容易操弄。', `MaleText_loc7`='Mentes mortales... Tan manipulables.' WHERE `ID`=49423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 시간이었다!', `MaleText_loc4`='真是令人愉快！', `MaleText_loc5`='感謝你帶來的娛樂性!', `MaleText_loc7`='¡Ha sido un placer!' WHERE `ID`=49424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하!', `MaleText_loc4`='哈！', `MaleText_loc5`='哈!', `MaleText_loc7`='¡JA!' WHERE `ID`=49425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 죽고 싶었나?', `MaleText_loc4`='你真的只能接受。', `MaleText_loc5`='不想接受也得接受。', `MaleText_loc7`='Tienes que quererlo.' WHERE `ID`=49426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배가 이렇게 쓰디썼던가... 으아아...', `MaleText_loc4`='失败的滋味从未如此苦涩……', `MaleText_loc5`='失敗從來沒這麼苦澀過...呃...', `MaleText_loc7`='La derrota nunca fue tan amarga…' WHERE `ID`=49427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와줘서 고맙지만, 이젠 정말 죽어 줘야겠다!', `MaleText_loc4`='多谢你们专程赶来，但你们现在真的都该死了！', `MaleText_loc5`='謝謝你們大駕光臨，但到了你們該死的時候了!', `MaleText_loc7`='¡Agradezco su visita, pero ahora deben morir!' WHERE `ID`=49428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 그대가 이걸 봐주었으면 한다. 하지만 그대의 안전을 위해 떨어져 있어라. 캘렌, 너도.', `FemaleText_loc4`='凡人，我希望你能见证这一切，不过为了你的安全，站远一点。凯伦，你也是。', `FemaleText_loc5`='凡人，我要你見證這一切，但為了你自己的安全退後點。凱倫，你也一樣。', `FemaleText_loc7`='Mortal, quiero que atestigües esto, pero, por tu seguridad, no te acerques. Calen, tu también.' WHERE `ID`=49429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='캘렌, 네 삶은 너의 것이 아니다. 내가 쓰러지면 이 세상의 운명은 네가 책임져야 하느니라.', `FemaleText_loc4`='不要浪费你的生命，凯伦。一旦我失败，那么世界的命运将落在你的肩上。', `FemaleText_loc5`='你的生死由不得你，凱倫。如果我失敗，這個世界的命運就會落在你肩上。', `FemaleText_loc7`='Tu vida no es tuya, Calen, no puedes tirarla. Si yo fallara, el destino del mundo tal vez dependa de ti.' WHERE `ID`=49430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넬타리온, 고통스러운 선택이지만... 너에게 최후를 안겨야겠다. 말리고스에게 그랬듯이.', `FemaleText_loc4`='这令我痛苦，奈萨里奥——但我必须终结你，就像我终结玛里苟斯一样。', `FemaleText_loc5`='這讓我難過，奈薩里奧 - 但我必須終結你，就像我終結瑪里苟斯一樣。', `FemaleText_loc7`='Me duele, Neltharion, pero tengo que eliminarte, como a Malygos.' WHERE `ID`=49431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 눈에 보이는 건 옛 동료의 공허한 금속 껍데기와 쓰레기가 된 티탄의 선물뿐이다.', `FemaleText_loc4`='曾经的伟大盟友只剩这具空洞的金属躯壳，真是浪费泰坦的恩赐。', `FemaleText_loc5`='曾經強大的盟友現在只剩下空洞的金屬外殼，浪費泰坦所賜予的寶貴力量。', `FemaleText_loc7`='Veo la coraza hueca de quien antes fuera un gran aliado; el regalo de los Titanes, desperdiciado.' WHERE `ID`=49432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넬타리온! 네 모습을 보아라. 뒤틀린 기형의 모습을. 넌 무너지고 있어.', `FemaleText_loc4`='奈萨里奥！看看你自己。残缺。扭曲。你已支离破碎。', `FemaleText_loc5`='奈薩里奧!看看你自己!畸形。扭曲。你正在逐步破碎。', `FemaleText_loc7`='¡Neltharion! Mírate. Desfigurado. Retorcido. Te desmoronas.' WHERE `ID`=49433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지의 수호자는... 죽었다.', `FemaleText_loc4`='大地的守卫者……他死了。', `FemaleText_loc5`='大地守護者...他已經死了。', `FemaleText_loc7`='El Guardián de la Tierra... ha muerto.' WHERE `ID`=49434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넬타리온의 피는 저주받았어. 핏방울이 떨어진 곳엔... 천 년 동안 아무것도 자라지 못할 것이다.', `FemaleText_loc4`='黑龙守护者之血受到了诅咒。但凡所溅之处，一万年都长不出任何东西。', `FemaleText_loc5`='黑龍之血受到了詛咒。它流過的地方一萬年內寸草不生。', `FemaleText_loc7`='La sangre del aspecto negro está maldita. El suelo que toca queda infértil por diez mil años.' WHERE `ID`=49435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알렉스트라자가 고통에 신음합니다.', `FemaleText_loc4`='阿莱克丝塔萨痛苦的喘息着。', `FemaleText_loc5`='雅立史卓莎痛苦地掙扎。', `FemaleText_loc7`='Alexstrasza hace un gesto de dolor.' WHERE `ID`=49436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 어쨌든 끝났다. 이젠 그가 퍼뜨린 공포를 수습하는 일만 남았어.', `FemaleText_loc4`='但是都结束了，终于可以将他带来的恐惧尘封起来了。', `FemaleText_loc5`='但都結束了，我們現在可以開始收拾他所製造的災難了!', `FemaleText_loc7`='Pero se acabó. Ya podemos concentrarnos en contener los horrores que desató.' WHERE `ID`=49437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가 없어!', `FemaleText_loc4`='这不可能！', `FemaleText_loc5`='不可能!', `FemaleText_loc7`='¡Imposible!' WHERE `ID`=49438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='캘렌! 안 돼!', `FemaleText_loc4`='凯伦，不！', `FemaleText_loc5`='凱倫，不要!', `FemaleText_loc7`='¡Calen, no!' WHERE `ID`=49439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼!', `FemaleText_loc4`='不！', `FemaleText_loc5`='不!', `FemaleText_loc7`='¡No!' WHERE `ID`=49440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자! 내가 네 뜻대로 행동할 것 같은가? 난 이 세상을 파괴하고 말 것이다.', `MaleText_loc4`='生命的缚誓者！你以为我会听从你的号令？世界正待我毁灭。', `MaleText_loc5`='生命守縛者!你認為你可以隨意使喚我嗎?有個世界等著我去毀滅呢。', `MaleText_loc7`='¡Protectora! ¿Acaso crees que soy tu siervo? Tengo un mundo por destruir.' WHERE `ID`=49441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후를 안긴다고? 네가 생명의 어머니라고 생명을 거둘 수도 있을 것 같나?', `MaleText_loc4`='“终结”我？生命的缚誓者，你认为你能取走生命？', `MaleText_loc5`='「終結」我?生命守縛者，你以為你能決定生命的去留嗎?', `MaleText_loc7`='¿"Acabarme"? Protectora, ¿crees que las vidas son tuyas?' WHERE `ID`=49442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 이 세계의 진정한 주인에게 받은 새로운 선물을 보여주마!', `MaleText_loc4`='那么见证我的新力量，来自世界真主的恩赐！', `MaleText_loc5`='那就見證一下，由這個世界真正的主人賦予我的新能力吧。', `MaleText_loc7`='Ve mis nuevos dones, otorgados por los verdaderos amos de este mundo.' WHERE `ID`=49443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삶이 죽음으로 끝나듯이... 질서는 혼돈으로 끝나야 한다... 오너라! 내가 그랬듯이, 필연적인 종말을 받아들여라!', `MaleText_loc4`='如同生命终将归于死亡……秩序终将归于混沌……来吧！拥抱不可违抗的宿命！', `MaleText_loc5`='就像所有的生命終將以死亡終結，所有的秩序也必須以混亂結束...來吧!像我一樣擁抱不可避免的結果!', `MaleText_loc7`='Así como la vida termina en la muerte... el orden termina en el caos... ¡Ven! ¡Acepta lo inevitable como yo!' WHERE `ID`=49444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈들. 이 필멸의 세계에서 해는 이미 졌다. 혼돈이 다가온다. 종말을 받아들이고 편히 쉬어라.', `MaleText_loc4`='凡人世界的夕阳已经落幕，平静接受你的末日，暮光的时刻来临了。', `MaleText_loc5`='這個凡人的世界已夕陽西下，笨蛋。迎接你們的死亡吧，因為黃昏正要來臨!', `MaleText_loc7`='El sol se ha puesto en este mundo mortal. Acepten su final, ha llegado el crepúsculo.' WHERE `ID`=49445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 이렇게 당할 것 같으냐?', `MaleText_loc4`='你妄想困住我！？', `MaleText_loc5`='你想要困住我?', `MaleText_loc7`='¿Piensan atraparme?' WHERE `ID`=49446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 어머니 곁에 있겠습니다.', `MaleText_loc4`='我不会离你而去。', `MaleText_loc5`='我不會離開你。', `MaleText_loc7`='No dejaré su lado.' WHERE `ID`=49447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 어머니.', `MaleText_loc4`='是的，母亲。', `MaleText_loc5`='是的，母親。', `MaleText_loc7`='Sí, madre.' WHERE `ID`=49448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 놓쳐선 안 됩니다! 어서요! 저와 함께 갑시다!', `MaleText_loc4`='别让他们离开视线！快——跟着我！', `MaleText_loc5`='別讓他們脫離視線!快─跟我來!', `MaleText_loc7`='¡No los pierdan de vista! ¡Rápido... Vengan a mi!' WHERE `ID`=49449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이... 떨어졌습니다!', `MaleText_loc4`='那边——他们落下去了！', `MaleText_loc5`='看─他們倒下了!', `MaleText_loc7`='¡Allí! ¡Han caído!' WHERE `ID`=49450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니, 가만히 계세요. 상처가 심합니다.', `MaleText_loc4`='母亲，请别动。你伤得很重。', `MaleText_loc5`='母親，不要動，妳的傷口非常大。', `MaleText_loc7`='Madre, quieta. Tus heridas son serias.' WHERE `ID`=49451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이... 살아 있습니다!', `MaleText_loc4`='死亡之翼——他还活着！', `MaleText_loc5`='死亡之翼─他還活著!', `MaleText_loc7`='¡Alamuerte... vive!' WHERE `ID`=49452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자여, 용의 여왕님을 안전한 곳으로 모시고 가세요. 당장! 뛰세요! 어머니를 다른 곳으로 데려가세요!', `MaleText_loc4`='凡人，带上红龙女王，送她去安全的地方。现在！快跑！把她从这里带走！', `MaleText_loc5`='凡人，帶龍后走，帶她到安全的地方。快跑!現在!帶她離開這裡!', `MaleText_loc7`='Mortal, lleva a la reina dragón a un lugar seguro. ¡Ya! ¡CORRE! ¡Sácala de aquí!' WHERE `ID`=49453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 죽음의 위상을 막겠습니다. 어머니를 안전한 곳으로 데려가세요!', `MaleText_loc4`='我来拖住死亡的化身。带她去安全的地方。快走！', `MaleText_loc5`='我會拖延死亡的化身。保護她的安全，快走!', `MaleText_loc7`='Retrasaré al Aspecto de la Muerte. Llévala a un lugar seguro. ¡VE!' WHERE `ID`=49454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑군.', `MaleText_loc4`='再一次问好。', `MaleText_loc5`='又見面了。', `MaleText_loc7`='Hola otra vez.' WHERE `ID`=49455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 종소리 마을로 가는 길을 알고 있네. 나와 같이 가세나!', `MaleText_loc4`='我知道通往丧钟镇的路。跟我来！', `MaleText_loc5`='我知道去喪鐘鎮的路。跟我來!', `MaleText_loc7`='Conozco el camino a Camposanto. ¡Ven conmigo!' WHERE `ID`=49456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 자네 아직도 살아 있군. 이제 죽음경비병 살테인은 어디 있는 거지?', `MaleText_loc4`='很好，你还在。亡灵卫兵萨尔坦在哪儿？', `MaleText_loc5`='很好，你還在這裡。亡靈守衛薩爾坦到哪去了?', `MaleText_loc7`='Bien, todavía estás aquí. ¿Dónde está el Guarda de la Muerte Saltain?' WHERE `ID`=49457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 있군.', `MaleText_loc4`='啊，他在这儿呢。', `MaleText_loc5`='啊，他在這裡。', `MaleText_loc7`='Ah, aquí está.' WHERE `ID`=49458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직이세나, $n. 살테인이 이곳에서 시체를 좀 찾을 수 있을 거라고 했네.', `MaleText_loc4`='我们动身吧，$n。萨尔坦说我们会撞见一些尸体。', `MaleText_loc5`='咱們動身吧，$n。薩爾坦說我們會在上面找到更多屍體。', `MaleText_loc7`='Pongámonos en marcha, $n. Saltain dijo que encontraremos algunos cadáveres allí.' WHERE `ID`=49459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 앞에 시체가 좀 보이는 것 같군. 어서 가세, $n! 자네가 수색과 전투를 하게나. 내가 시체들을 옮기겠네.', `MaleText_loc4`='我想我在前方看见了一些尸体。走吧，$n！你负责搜寻和战斗。体力活儿交给我。', `MaleText_loc5`='我想我看到前面有些屍體。走吧，$n!你負責搜索和戰鬥，我負責搬運。', `MaleText_loc7`='Creo que veo algunos cadáveres allí delante. ¡Venga, $n! Tú buscas y luchas. Yo me encargo de cargar.' WHERE `ID`=49460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 던전에 도전할 용기가 있으십니까? 자세한 사항은 안에서 문의하십시오...', `MaleText_loc4`='认为你已经有能力应对艾泽拉斯地下城的挑战了？入内查究……', `MaleText_loc5`='你覺得有能力挑戰艾澤拉斯的地城嗎?詳情入內詢問...', `MaleText_loc7`='¿Crees que tienes lo que hay que tener para enfrentarte a los desafíos de las mazmorras de Azeroth? Pregunta dentro...' WHERE `ID`=49461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 파는 물건을 살펴보고 싶습니다, 야스민.', `MaleText_loc4`='我想看看你的货物，雅斯敏。', `MaleText_loc5`='我希望看看你有什麼貨物，亞絲閔。', `MaleText_loc7`='Me gustaría echar un vistazo a tus mercancías, Yasmin.', `FemaleText_loc1`='당신이 파는 물건을 살펴보고 싶어요, 야스민.', `FemaleText_loc4`='我想看看你的货物，雅斯敏。', `FemaleText_loc5`='我希望看看你有什麼貨物，亞絲閔。', `FemaleText_loc7`='Me gustaría echar un vistazo a tus mercancías, Yasmin.' WHERE `ID`=49462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 불쌍한 사람 같으니. 머리부터 발끝까지 모래에 뒤덮였군요! 여기 아름다운 오아시스에서 푹 쉬고 기운을 차리세요.', `MaleText_loc4`='哦可怜的小家伙，你从头到脚都裹满了沙子！在这片美丽的绿洲好好休息，恢复下体力吧。', `MaleText_loc5`='噢，你這可憐的傢伙，你從頭到腳都是沙!歡迎在這個美麗的綠洲休息並回復你的體力。', `MaleText_loc7`='¡Ay, $gpobrecito mío:pobrecita mía;, estás $gcubierto:cubierta; de arena de pies a cabeza! ¡Disfruta de este hermoso oasis libremente para rejuvenecerte un poco!', `FemaleText_loc1`='아이고, 불쌍한 사람 같으니. 머리부터 발끝까지 모래에 뒤덮였군요! 여기 아름다운 오아시스에서 푹 쉬고 기운을 차리세요.', `FemaleText_loc4`='哦可怜的小家伙，你从头到脚都裹满了沙子！在这片美丽的绿洲好好休息，恢复下体力吧。', `FemaleText_loc5`='噢，你這可憐的傢伙，你從頭到腳都是沙!歡迎在這個美麗的綠洲休息並回復你的體力。', `FemaleText_loc7`='¡Ay, $gpobrecito mío:pobrecita mía;, estás $gcubierto:cubierta; de arena de pies a cabeza! ¡Disfruta de este hermoso oasis libremente para rejuvenecerte un poco!' WHERE `ID`=49463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알렉스트라자 님이 곧 오실 겁니다. 이리 오세요. 성역을 준비해야 합니다.', `FemaleText_loc4`='阿莱克丝塔萨很快就会到来。来吧，让我们做好准备。', `FemaleText_loc5`='雅立史卓莎很快就會過來。走，我們先去把聖所設置好。', `FemaleText_loc7`='Alexstrasza estará aquí en breve. Vamos, prepararemos el santuario.' WHERE `ID`=49464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랫동안 잊힌 생명을 위해 불꽃이 타오르니, 살아있는 모든 것이 그들의 정수를 나누어 받으리라.', `FemaleText_loc4`='为殒落已久的生命燃起烈焰，他们的魂灵与所有鲜活的生命同在。', `FemaleText_loc5`='一道火焰獻給生命久逝者，其靈魂今與萬物生者同在。', `FemaleText_loc7`='Una llama arde por las vidas perdidas hace tiempo; su esencia se mezcla ahora con todas las cosas vivientes.' WHERE `ID`=49465;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다가올 생명을 위해 불꽃이 타오르니, 어린 영혼이 자궁에서 깨어나리라.', `FemaleText_loc4`='为即将降临的生命燃起烈焰，懵懂的灵魂在母体中苏醒。', `FemaleText_loc5`='一道火焰獻給生命未來者，其嫩幼靈魂在母親子宮中甦醒。', `FemaleText_loc7`='Una llama arde por las vidas que vendrán; almas nacientes que despiertan en los vientres.' WHERE `ID`=49466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 태어난 생명을 위해 불꽃이 타오르니, 젊음의 열정과 그들이 지닌 활기가 허락되리라.', `FemaleText_loc4`='为新诞的生命燃起烈焰，青春盛放的热情与蓬勃不息的活力。', `FemaleText_loc5`='一道火焰獻給生命初臨者，其年輕熱情，活力無限。', `FemaleText_loc7`='Una llama arde por las vida recién nacidas; por la pasión de la juventud y la energía que emanan.' WHERE `ID`=49467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 생명의 시작을 위해 불꽃이 타오르니, 세상을 만들고 바꾸려 애쓰는구나.', `FemaleText_loc4`='为正值盛年的生命燃起烈焰，奋力缔造和重塑这个世界。', `FemaleText_loc5`='一道火焰獻給生命盛旺者，其奉獻努力重塑世界。', `FemaleText_loc7`='Una llama arde por las vidas en todo su esplendor; que luchan por crear y remodelar el mundo.' WHERE `ID`=49468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 생명의 끝을 위해 불꽃이 타오르니, 그들의 일은 끝났으나 그 은혜는 영원하리라.', `FemaleText_loc4`='为即将凋零的生命燃起烈焰，他们的使命也许将要完成，但他们的贡献却会成为永恒。', `FemaleText_loc5`='一道火焰獻給生命臨終者，其業已成，其業永誌。', `FemaleText_loc7`='Una llama arde por las vidas que llegan a su final; su trabajo puede que esté hecho, pero su contribución será eterna.' WHERE `ID`=49469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생명의 순환계가 완성되었습니다. 모든 준비가 끝났어요.', `FemaleText_loc4`='生命的循环已经完成。一切都已就绪。', `FemaleText_loc5`='生命之環已經完整，一切準備完成。', `FemaleText_loc7`='Y así el círculo de la vida se completa. Todo está preparado.' WHERE `ID`=49470;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 알렉스트라자 님이 이리 오시는군요.', `FemaleText_loc4`='啊——阿莱克丝塔萨来了。', `FemaleText_loc5`='啊—雅立史卓莎來了。', `FemaleText_loc7`='Ah, ahí viene Alexstrasza.' WHERE `ID`=49471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 여기서 어디로 가야 하는지 모르겠네요. 이쪽으로 가보죠!', `MaleText_loc4`='嗯……我不记得该走哪条路了。我们试试这边吧！', `MaleText_loc5`='嗯...我不記得接下來的路怎麼走。我們試試這一邊吧!', `MaleText_loc7`='Hmm... No recuerdo por dónde se llega allí. ¡Probemos por este lado!', `FemaleText_loc1`='흠... 여기서 어디로 가야 하는지 모르겠네요. 이쪽으로 가보죠!', `FemaleText_loc4`='嗯……我不记得该走哪条路了。我们试试这边吧！', `FemaleText_loc5`='嗯...我不記得接下來的路怎麼走。我們試試這一邊吧!', `FemaleText_loc7`='Hmm... No recuerdo por dónde se llega allí. ¡Probemos por este lado!' WHERE `ID`=49472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 여긴 막다른 길인 것 같네요. 다른 쪽으로 가야겠어요.', `MaleText_loc4`='啊！这好像是死路。我们走另一条路试试看。', `MaleText_loc5`='靠!看起來是沒路走了。咱們回去試試另一邊。', `MaleText_loc7`='¡Bah! Parece un callejón sin salida. Probemos por el otro sitio.', `FemaleText_loc1`='윽! 여긴 막다른 길인 것 같네요. 다른 쪽으로 가야겠어요.', `FemaleText_loc4`='啊！这好像是死路。我们走另一条路试试看。', `FemaleText_loc5`='靠!看起來是沒路走了。咱們回去試試另一邊。', `FemaleText_loc7`='¡Bah! Parece un callejón sin salida. Probemos por el otro sitio.' WHERE `ID`=49473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이 계단은 왠지 믿음이 안 가네요. 안마당으로 돌아가서 다른 길이 있나 찾아보죠.', `MaleText_loc4`='嗯……这楼梯看起来也不怎么靠谱。我们返回庭院，研究下是否还有别的路可走。', `MaleText_loc5`='嗯...這個樓梯看起來有種不是很可靠的感覺。咱們回去庭院看看有沒有其他的路走。', `MaleText_loc7`='Hmmm... Esta escalera no tiene buena pinta en absoluto. Volvamos al patio y veamos si hay otra forma de salir.', `FemaleText_loc1`='흠... 이 계단은 왠지 믿음이 안 가네요. 안마당으로 돌아가서 다른 길이 있나 찾아보죠.', `FemaleText_loc4`='嗯……这楼梯看起来也不怎么靠谱。我们返回庭院，研究下是否还有别的路可走。', `FemaleText_loc5`='嗯...這個樓梯看起來有種不是很可靠的感覺。咱們回去庭院看看有沒有其他的路走。', `FemaleText_loc7`='Hmmm... Esta escalera no tiene buena pinta en absoluto. Volvamos al patio y veamos si hay otra forma de salir.' WHERE `ID`=49474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제대로 온 것 같네요! 여기가 나가는 길이 분명해요. 경비병이 엄청 많은 것 같으니까 저를 잘 지켜주셔야 해요!', `MaleText_loc4`='总算有进展了！走这条路肯定能出去。不过看来有不少卫兵在把守，我迫切需要你的帮助！', `MaleText_loc5`='現在終於有點眉目了!這一定是往出口的路。看起來有不少守衛，所以我真的需要你的幫忙!', `MaleText_loc7`='¡Ahora sí que vamos haciendo progresos! Por aquí se sale, estoy seguro. ¡Pero parece que hay un montón de guardias así que voy a necesitar que me ayudes a salir!', `FemaleText_loc1`='이제 제대로 온 것 같네요! 여기가 나가는 길이 분명해요. 경비병이 엄청 많은 것 같으니까 저를 잘 지켜주셔야 해요!', `FemaleText_loc4`='总算有进展了！走这条路肯定能出去。不过看来有不少卫兵在把守，我迫切需要你的帮助！', `FemaleText_loc5`='現在終於有點眉目了!這一定是往出口的路。看起來有不少守衛，所以我真的需要你的幫忙!', `FemaleText_loc7`='¡Ahora sí que vamos haciendo progresos! Por aquí se sale, estoy segura. ¡Pero parece que hay un montón de guardias así que voy a necesitar que me ayudes a salir!' WHERE `ID`=49475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선실문 위에서 바스락거리는 소리가 들립니다!', `FemaleText_loc4`='从舱门上方传来一阵响声！', `FemaleText_loc5`='你聽見艙門上面有道噪音!', `FemaleText_loc7`='¡Oyes el ruido de la puerta del camarote de arriba!' WHERE `ID`=49476;
