UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때가 오길 기다리면서, 부하들을 모으고, 적의 정신을 연구했지.', `FemaleText_loc4`='等待属于我的时机，建立我的军队，分析敌人的心理。', `FemaleText_loc5`='等待時機成熟，建立我的部隊，研究敵人的思考邏輯。', `FemaleText_loc7`='Esperando el momento, reuniendo fuerzas, estudiando las mentes de mis enemigos.' WHERE `ID`=49478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 맞붙어 싸우는 덴 영 소질이 없었어. 아버지완 달랐지.', `FemaleText_loc4`='肉搏战从来不是我的强项。我和我父亲不同。', `FemaleText_loc5`='我向來不擅長近身戰鬥，知道嗎?不像我爸爸。', `FemaleText_loc7`='Nunca fui muy buena en el combate cuerpo a cuerpo. A diferencia de mi padre.' WHERE `ID`=49479;
