UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='특히나 정신을 조종하는 맹독 말이지.', `FemaleText_loc4`='尤其是影响心智的剧毒。', `FemaleText_loc5`='尤其是會影響心智運作的毒。', `FemaleText_loc7`='Especialmente los que afectan a la mente.' WHERE `ID`=49481;
