UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다만, 지금은 다리가 부러진 새끼 용을 치료해 줘야 합니다. 잠시 후에 다시 오시겠습니까?', `MaleText_loc4`='抱歉，我必须要给一个龙宝宝接上断腿。你能过几分钟再回来吗？', `MaleText_loc5`='抱歉，我得幫隻小龍處理一下斷掉的腿骨。方便等一會兒再過來嗎?', `MaleText_loc7`='Perdona, tengo que entablillarle una pata rota a un bebé dragón. ¿Te importa volver dentro de un rato?', `FemaleText_loc1`='죄송합니다만, 지금은 다리가 부러진 새끼 용을 치료해 줘야 해요. 잠시 후에 다시 오시겠어요?', `FemaleText_loc4`='抱歉，我必须要给一个龙宝宝接上断腿。你能过几分钟再回来吗？', `FemaleText_loc5`='抱歉，我得幫隻小龍處理一下斷掉的腿骨。方便等一會兒再過來嗎?', `FemaleText_loc7`='Perdona, tengo que entablillarle una pata rota a un bebé dragón. ¿Te importa volver dentro de un rato?' WHERE `ID`=49490;
