UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 죄는 말할 것도 없고, 내 의식을 방해해서 고블스를 죽음에 이르게 했지!', `MaleText_loc4`='如果那些理由还不够的话，你还破坏了我的仪式，害哥培尔送了命！', `MaleText_loc5`='這還不夠，你還摧毀我的儀式，弄死了咯咯!', `MaleText_loc7`='¡Por si eso no fuerrra suficiente, saboteas mi rrritual y causas la muerrrte de Gluber!' WHERE `ID`=49492;
