UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너무 바빠서 이렇게 빨리 처치해 주는 걸 다행이라고 생각하라고.', `MaleText_loc4`='你应该感到庆幸，我没有时间让你为自己所犯下的罪行而饱受折磨。', `MaleText_loc5`='你很幸運，我沒空給你應得的折磨。', `MaleText_loc7`='Tienes mucha suerrrte de que esté demasiado ocupado parrra hacerrrte sufrir lo que te merrreces.' WHERE `ID`=49495;
