UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서부터는 내가 맡을게요, 친구들. 문제를 잘 처리했다고 주인님께 보고나 잘 해줘요.', `MaleText_loc4`='接下来我自己能行了，朋友。去把问题已经解决的消息报告给你的主人吧。', `MaleText_loc5`='我可以從這裡接手了，朋友們。向你們主人報告問題已經解決了。', `MaleText_loc7`='Yo puedo encarrrgarme a parrrtir aquí, amigos míos. Informen a su maestrrro de que yo me he encarrrgado del proflema.' WHERE `ID`=49497;
