UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 말이 사실이어야 할 거야, 슈노츠. 데스윙 님의 인내심이 한계에 다다르고 있으니까.', `MaleText_loc4`='最好不会再有，司克诺兹。死亡之翼的耐心就快消磨殆尽了。', `MaleText_loc5`='你最好確定不會，舒諾茲。死亡之翼已經沒什麼耐心了。', `MaleText_loc7`='Más te vale que no las haya, Schnottz. La paciencia de Alamuerte se agota.' WHERE `ID`=49499;
