UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 빨리 좀 작동하라고, 이 멍청한 고물아...', `MaleText_loc4`='嗷呦！来吧，你这家伙……', `MaleText_loc5`='噢!夠了吧，你這混...', `MaleText_loc7`='¡Ach! Ven aquí, miserable.' WHERE `ID`=49523;
