UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 이 얼마 만의 신선한 공기인가!', `MaleText_loc4`='啊哈！终于呼吸到新鲜空气了！', `MaleText_loc5`='哈!終於有新鮮空氣了!', `MaleText_loc7`='¡Ajá! ¡Por fin aire fresco!' WHERE `ID`=49529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에도 내가 너보다 한 발짝 빨랐구나, 얘야! 언제나 그렇지만.', `MaleText_loc4`='又比你早了两步，小子！一如既往。', `MaleText_loc5`='又比你快上兩步了，小子!一如往常。', `MaleText_loc7`='¡Voy dos pasos por delante de ti, júnior! Como siempre.' WHERE `ID`=49530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 차리는 게 좋을 거야! 다음번에는 내가 도와주지 않을 수도 있으니까 말이야.', `MaleText_loc4`='最好小心点儿，小伙子！下一次也许就没那么幸运正巧被我赶上了。', `MaleText_loc5`='最好振作點，小子!我下次不一定能在你身邊幫上你的忙。', `MaleText_loc7`='¡Será mejor que prestes más atención, camarada! Quizá la próxima vez no esté aquí para sacarte las castañas del fuego.' WHERE `ID`=49531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 구출하러 오셨습니까? 그럼 어서 갑시다!', `MaleText_loc4`='你能帮我出去吗？没理由闲着不动，我们走吧！', `MaleText_loc5`='你可以幫我離開這裡?那就沒理由在這裡站著，我們走吧!', `MaleText_loc7`='¿Puedes ayudarme a salir de aquí? Bueno, no existe ninguna razón para quedarnos por aquí, ¡vamos!', `FemaleText_loc1`='절 구출하러 오셨습니까? 그럼 어서 갑시다!', `FemaleText_loc4`='你能帮我出去吗？没理由闲着不动，我们走吧！', `FemaleText_loc5`='你可以幫我離開這裡?那就沒理由在這裡站著，我們走吧!', `FemaleText_loc7`='¿Puedes ayudarme a salir de aquí? Bueno, no existe ninguna razón para quedarnos por aquí, ¡vamos!' WHERE `ID`=49532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출구가 어느 쪽인지 기억이 안 나는군요. 저쪽으로 가봅시다.', `MaleText_loc4`='我不记得通向出口的路了。我们试试这条路。', `MaleText_loc5`='我不記得出去的路是哪一條。咱們試試那邊的通道。', `MaleText_loc7`='No recuerdo por dónde quedaba la salida. Probemos por esta puerta.', `FemaleText_loc1`='출구가 어느 쪽인지 기억이 안 나는군요. 저쪽으로 가봅시다.', `FemaleText_loc4`='我不记得通向出口的路了。我们试试这条路。', `FemaleText_loc5`='我不記得出去的路是哪一條。咱們試試那邊的通道。', `FemaleText_loc7`='No recuerdo por dónde quedaba la salida. Probemos por esta puerta.' WHERE `ID`=49533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 막다른 길인 것 같습니다. 저 침대가 편해 보이긴 하는데... 다른 길로 가봅시다.', `MaleText_loc4`='啊！这好像是死路。尽管这张床看上去无比舒适。我们走另一条路看看。', `MaleText_loc5`='靠!看起來是沒路走了。那張床看起來是挺舒服的樣子。咱們試試另一條路吧。', `MaleText_loc7`='Bah, es un callejón sin salida. Pero la cama sí que parece cómoda. Intentémoslo por el otro lado.', `FemaleText_loc1`='이런, 막다른 길인 것 같습니다. 저 침대가 편해 보이긴 하는데... 다른 길로 가봅시다.', `FemaleText_loc4`='啊！这好像是死路。尽管这张床看上去无比舒适。我们走另一条路看看。', `FemaleText_loc5`='靠!看起來是沒路走了。那張床看起來是挺舒服的樣子。咱們試試另一條路吧。', `FemaleText_loc7`='Bah, es un callejón sin salida. Pero la cama sí que parece cómoda. Intentémoslo por el otro lado.' WHERE `ID`=49534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 전혀 낯이 익지 않군요. 안마당으로 돌아가서 다른 길을 찾아봅시다. 저는 원래 긴 계단을 싫어합니다.', `MaleText_loc4`='这里看上去真是陌生。我们返回庭院吧，看看还有没有其它出路。我打从心底厌恶长长的楼梯。', `MaleText_loc5`='這裡看起來是完全陌生的地方。我們回去庭院看看有沒有其他路可以走。反正我本來就不喜歡太長的樓梯。', `MaleText_loc7`='Esto no me resulta familiar. Volvamos al patio y veamos si hay otro camino. De todas maneras, no me gustan las escaleras interminables.', `FemaleText_loc1`='여긴 전혀 낯이 익지 않군요. 안마당으로 돌아가서 다른 길을 찾아봅시다. 저는 원래 긴 계단을 싫어합니다.', `FemaleText_loc4`='这里看上去真是陌生。我们返回庭院吧，看看还有没有其它出路。我打从心底厌恶长长的楼梯。', `FemaleText_loc5`='這裡看起來是完全陌生的地方。我們回去庭院看看有沒有其他路可以走。反正我本來就不喜歡太長的樓梯。', `FemaleText_loc7`='Esto no me resulta familiar. Volvamos al patio y veamos si hay otro camino. De todas maneras, no me gustan las escaleras interminables.' WHERE `ID`=49535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 여기가 나가는 길이 분명합니다. 경비병이 많을 테니 조심하십시오.', `MaleText_loc4`='好了，一定是这条路。那边有几个守卫，多加小心。', `MaleText_loc5`='好啦，這一定是正確的路。有不少守衛，所以保持警覺。', `MaleText_loc7`='Vale, este es el buen camino, estoy seguro. Hay algunos guardias ahí delante así que abre bien los ojos.', `FemaleText_loc1`='그래요. 여기가 나가는 길이 분명합니다. 경비병이 많을 테니 조심하십시오.', `FemaleText_loc4`='好了，一定是这条路。那边有几个守卫，多加小心。', `FemaleText_loc5`='好啦，這一定是正確的路。有不少守衛，所以保持警覺。', `FemaleText_loc7`='Vale, este es el buen camino, estoy segura. Hay algunos guardias ahí delante así que abre bien los ojos.' WHERE `ID`=49536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저 혼자 말을 타고 가면 될 것 같습니다. 당신의 도움이 없었으면 절대 탈출하지 못했을 것입니다. 고맙습니다, $n.', `MaleText_loc4`='谢谢你，$n，我想我能骑上匹马，一径返回营地去。真是多亏了你的帮助。', `MaleText_loc5`='謝謝，$n，我想我可以騎其中一匹馬自己回去營地。如果不是你的幫忙，我沒辦法成功離開。', `MaleText_loc7`='Gracias, $n. Creo que tomaré uno de esos caballos y volveré al campamento. No lo habría conseguido sin tu ayuda.', `FemaleText_loc1`='고맙습니다, $n. 이제 저 혼자 말을 타고 가면 될 것 같습니다. 당신의 도움이 없었으면 절대 탈출하지 못했을 것입니다. 고맙습니다, $n.', `FemaleText_loc4`='谢谢你，$n，我想我能骑上匹马，一径返回营地去。真是多亏了你的帮助。', `FemaleText_loc5`='謝謝，$n，我想我可以騎其中一匹馬自己回去營地。如果不是你的幫忙，我沒辦法成功離開。', `FemaleText_loc7`='Gracias, $n. Creo que tomaré uno de esos caballos y volveré al campamento. No lo habría conseguido sin tu ayuda.' WHERE `ID`=49537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기서 만납시다, $n! 늦지 마세요!', `MaleText_loc4`='回头见，$n！别迟到！', `MaleText_loc5`='在那裡見囉，$n!別遲到喔!', `MaleText_loc7`='¡Te veo allí, $n! ¡No te retrases!' WHERE `ID`=49538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 자... 어디 한번 볼까요?', `MaleText_loc4`='来吧……让我们瞧瞧。', `MaleText_loc5`='好吧，現在...咱們看看...', `MaleText_loc7`='Bueno, eh... Veamos que hay aquí.' WHERE `ID`=49539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, $r.$b$b이제 모두 제자리에 있군요.', `MaleText_loc4`='好吧，$r。$b$b看起来一切都还不错。', `MaleText_loc5`='好吧，$r。$b$b看起來所有東西的位置都放在原處。', `MaleText_loc7`='Bien, $r.$b$bParece que todo está donde tiene que estar.' WHERE `ID`=49540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 브란. 이제 성궤를 작동시키십시오.', `MaleText_loc4`='我准备好了，布莱恩。去开启那个箱子吧。', `MaleText_loc5`='我準備好了，布萊恩。去啟動法櫃吧。', `MaleText_loc7`='Estoy listo, Brann. Ya puedes activar el arca.', `FemaleText_loc1`='준비됐어요, 브란. 이제 성궤를 작동시키세요.', `FemaleText_loc4`='我准备好了，布莱恩。去开启那个箱子吧。', `FemaleText_loc5`='我準備好了，布萊恩。去啟動法櫃吧。', `FemaleText_loc7`='Estoy lista, Brann. Ya puedes activar el arca.' WHERE `ID`=49541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 이게 누군가!', `MaleText_loc4`='呦，看看谁来了！', `MaleText_loc5`='哇，看看是誰來了!', `MaleText_loc7`='¡Bueno, mira quién está aquí!' WHERE `ID`=49542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $n! 내 새 장비 어떤가?', `MaleText_loc4`='你好，$n！你觉得我的新装备怎么样？', `MaleText_loc5`='嗨，$n!你覺得我的新裝備如何?', `MaleText_loc7`='¡Hola, $n! ¿Qué opinas de mi nuevo equipamiento?' WHERE `ID`=49543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 나를 죽음경비병으로 만들고 있다네. 믿어지나?', `MaleText_loc4`='他们想让我当个亡灵卫兵。你能相信吗？', `MaleText_loc5`='他們打算讓我當亡靈守衛。你相信嗎?', `MaleText_loc7`='Van a nombrarme Guardia de la Muerte. ¿Puedes creértelo?' WHERE `ID`=49544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 아무래도 여기 죽음의 종소리 마을에 머물 것 같네. 일이 잘 풀릴지는 모르겠지만... 누가 알겠나? 어둠의 여왕님을 직접 뵐 수 있을지도 모르는 일 아닌가.', `MaleText_loc4`='我也许会留在丧钟镇。如果一切顺利的话……谁知道呢？或许我会见到黑暗女王本人。', `MaleText_loc5`='我大概會留在喪鐘鎮這裡。如果一切順利...誰知道?也許我有機會能見到黑暗女王本人。', `MaleText_loc7`='Probablemente me quede aquí en Camposanto. Sin embargo, si las cosas marchan bien... ¿Quién sabe? Quizá llegue a conocer a la Dama Oscura en persona.' WHERE `ID`=49545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 어떤가? 사비스 님께서 자네를 칼스턴 영지로 보내겠다고 하시던데 말이네. 정말 막중한 임무를 주시는군, 안 그렇나?', `MaleText_loc4`='你呢？我听说萨维斯准备派你前往卡尔斯通庄园。重要任务，对吧？', `MaleText_loc5`='你呢?我聽說薩維斯要派你去考斯頓莊園。重要任務，嗯?', `MaleText_loc7`='¿Y qué hay de ti? He oído que Sarvis va a enviarte a los Dominios de Calston. Un misión importante, ¿eh?' WHERE `ID`=49546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 자네를 계속 붙잡고 있진 않겠네. 만나서 정말 반가웠네, $n. 곧 다시 만날 날이 올 걸세.', `MaleText_loc4`='嗯，快去做你的事吧。很高兴认识你，$n。希望我们很快就能再见面。', `MaleText_loc5`='好吧，我不浪費你時間了。很高興又碰到你，$n。希望我們能再度相會。', `MaleText_loc7`='Bueno, no te entretengo. Ha sido un placer, $n. Espero que nuestros caminos se crucen de nuevo.' WHERE `ID`=49547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신을 도울 황혼의 비룡을 부릅니다!', `MaleText_loc4`='%s召唤暮光幼龙来协助他！', `MaleText_loc5`='%s召喚了一頭暮光飛龍來協助他!', `MaleText_loc7`='¡%s convoca a un draco Crepuscular para que le ayude!' WHERE `ID`=49548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 여기에 머물며 이 거미들을 풀어주는 일에 온 힘을 다할게요. 도와주셔서 감사해요, $n.', `FemaleText_loc4`='我会留下，想办法释放这些蜘蛛。谢谢你的帮助，$n。', `FemaleText_loc5`='我會待在這和盡我所能地來解救這些蜘蛛。謝謝你的幫忙，$n。', `FemaleText_loc7`='Voy a quedarme y hacer lo que pueda para liberar esas arañas. Gracias por tu ayuda, $n.' WHERE `ID`=49549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도와주러 오신 건가요, $c님? 잠깐 저와 함께 머물러주세요.', `FemaleText_loc4`='你是来帮忙的，$c？让我们暂时待在一起。', `FemaleText_loc5`='你來提供幫助嗎，$c?讓我們先停留一會兒吧。', `FemaleText_loc7`='¿Has venido a ayudar, $c? Permanezcamos juntos durante un rato.' WHERE `ID`=49550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격에서 살아남았습니다!$B호두바위를 사용할 수 있습니다!', `MaleText_loc4`='你承受住了攻击！$B岩石坚果已解锁！', `MaleText_loc5`='你成功從攻擊中存活!$B岩果已解鎖!', `MaleText_loc7`='¡Has sobrevivido al ataque!$B¡Rocanuez desbloqueada!', `FemaleText_loc1`='공격에서 살아남았습니다!$B호두바위를 사용할 수 있습니다!', `FemaleText_loc4`='你承受住了攻击！$B岩石坚果已解锁！', `FemaleText_loc5`='你成功從攻擊中存活!$B岩果已解鎖!', `FemaleText_loc7`='¡Has sobrevivido al ataque!$B¡Rocanuez desbloqueada!' WHERE `ID`=49551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습 완료!$B$B해바라기를 사용할 수 있습니다.', `MaleText_loc4`='教学已完成！$B你已解锁向日葵。', `MaleText_loc5`='教學模式完成!$B你已將向日葵解鎖!', `MaleText_loc7`='¡Tutorial completado!$BHas desbloqueado el girasol.', `FemaleText_loc1`='연습 완료!$B$B해바라기를 사용할 수 있습니다.', `FemaleText_loc4`='教学已完成！$B你已解锁向日葵。', `FemaleText_loc5`='教學模式完成!$B你已將向日葵解鎖!', `FemaleText_loc7`='¡Tutorial completado!$BHas desbloqueado el girasol.' WHERE `ID`=49552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다!', `MaleText_loc4`='干得好！', `MaleText_loc5`='做得好!', `MaleText_loc7`='¡Buen trabajo!', `FemaleText_loc1`='잘하셨습니다!', `FemaleText_loc4`='干得好！', `FemaleText_loc5`='做得好!', `FemaleText_loc7`='¡Buen trabajo!' WHERE `ID`=49553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망가진 밸브를 폭발 접착띠로 잘 고쳐 달라고.', `MaleText_loc4`='用这卷爆破胶带把那些故障阀门封紧，酋长。', `MaleText_loc5`='用這個防爆膠帶來把有問題的閥門都封起來，老大。', `MaleText_loc7`='Utiliza esta cinta explosiva para sellar las válvulas defectuosas como es debido, $gjefe:jefa;.' WHERE `ID`=49554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더... 조금만... 세나리우스 님이 거의 다 도착하셨다!', `MaleText_loc4`='再坚持几分钟……塞纳留斯就快到了！', `MaleText_loc5`='再幾分鐘就好...塞納留斯就快到了!', `MaleText_loc7`='Solo unos minutos más... ¡Cenarius ya casi ha llegado!' WHERE `ID`=49555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다릴 시간이 없을 텐데. 적 증원군이 벌써 이곳을 향하고 있다.', `MaleText_loc4`='你也许没那么多时间。敌人的援军正在赶来。', `MaleText_loc5`='你沒有那麼多時間了。敵人的援軍正在趕過來。', `MaleText_loc7`='Quizá no tengas tanto tiempo. Los refuerzos del enemigo están de camino.' WHERE `ID`=49556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골드린! 사... 사실이었어... 고대정령들이 다시 우리 곁에서 걷는다!', `MaleText_loc4`='戈德林！看来是真的……远古之神又再次出现在我们身边！', `MaleText_loc5`='戈德林!所以傳言是真的...先祖們已經回歸了!', `MaleText_loc7`='¡Goldrinn! Entonces es cierto... ¡Los ancestros caminan entre nosotros de nuevo!' WHERE `ID`=49557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중앙선에 항아리덩굴을 지속적으로 심어 좀비가 다가오지 못하게 하십시오.', `MaleText_loc4`='在中间那条路上不断放置喷酸草来阻击僵尸。', `MaleText_loc5`='持續放置噴濺者在中線來對抗殭屍。', `MaleText_loc7`='Sigue situando escupidoras en el carril central para detener a los zombis.', `FemaleText_loc1`='중앙선에 항아리덩굴을 지속적으로 심어 좀비가 다가오지 못하게 하십시오.', `FemaleText_loc4`='在中间那条路上不断放置喷酸草来阻击僵尸。', `FemaleText_loc5`='持續放置噴濺者在中線來對抗殭屍。', `FemaleText_loc7`='Sigue situando escupidoras en el carril central para detener a los zombis.' WHERE `ID`=49558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양의 힘을 모으고 중앙선에 항아리덩굴을 심어 좀비와 싸우십시오!', `MaleText_loc4`='收集太阳能并在中间那条路上放置喷酸草以抗击僵尸！', `MaleText_loc5`='蒐集太陽能量並放置噴濺者在中線來打擊殭屍!', `MaleText_loc7`='¡Recoge poder del sol y sitúa escupidoras en el carril central para combatir a los zombis!', `FemaleText_loc1`='태양의 힘을 모으고 중앙선에 항아리덩굴을 심어 좀비와 싸우십시오!', `FemaleText_loc4`='收集太阳能并在中间那条路上放置喷酸草以抗击僵尸！', `FemaleText_loc5`='蒐集太陽能量並放置噴濺者在中線來打擊殭屍!', `FemaleText_loc7`='¡Recoge poder del sol y sitúa escupidoras en el carril central para combatir a los zombis!' WHERE `ID`=49559;
