UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해바라기를 심어 좀비 공격으로부터 생존하는 데 필요한 태양의 힘을 추가로 생성할 수 있습니다.', `MaleText_loc4`='种植向日葵以生成额外的太阳能，这将帮你抵挡僵尸的攻击。', `MaleText_loc5`='種植向日葵來製造更多的太陽能量，可以幫助你從殭屍的攻擊中存活。', `MaleText_loc7`='Planta girasoles para crear energía solar adicional, que te ayudará a sobrevivir a los ataques zombis.', `FemaleText_loc1`='해바라기를 심어 좀비 공격으로부터 생존하는 데 필요한 태양의 힘을 추가로 생성할 수 있습니다.', `FemaleText_loc4`='种植向日葵以生成额外的太阳能，这将帮你抵挡僵尸的攻击。', `FemaleText_loc5`='種植向日葵來製造更多的太陽能量，可以幫助你從殭屍的攻擊中存活。', `FemaleText_loc7`='Planta girasoles para crear energía solar adicional, que te ayudará a sobrevivir a los ataques zombis.' WHERE `ID`=49566;
