UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호두바위를 사용해 항아리덩굴과 해바라기를 보호해야 합니다.', `MaleText_loc4`='用岩石坚果保护喷酸草和向日葵。', `MaleText_loc5`='使用岩果來保護你的噴濺者和向日葵。', `MaleText_loc7`='Utiliza rocanueces y protege tus escupidoras y girasoles.', `FemaleText_loc1`='호두바위를 사용해 항아리덩굴과 해바라기를 보호해야 합니다.', `FemaleText_loc4`='用岩石坚果保护喷酸草和向日葵。', `FemaleText_loc5`='使用岩果來保護你的噴濺者和向日葵。', `FemaleText_loc7`='Utiliza rocanueces y protege tus escupidoras y girasoles.' WHERE `ID`=49600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허가 당신의 영혼을 빨아들인다. 천천히, 천천히 영혼을 즐기려 한다.', `MaleText_loc4`='虚空抽吸着你的灵魂。它心满意足地慢慢享用着。', `MaleText_loc5`='虛空在吞噬你的靈魂。它滿足於慢慢地進食。', `MaleText_loc7`='El vacío devora tu alma. Se deleita alimentándose lentamente.' WHERE `ID`=49601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롬오그가 우릴 공격했을 때, 놈은 라즈를 사슬로 꽁꽁 묶고는 |cff71d5ff|Hspell:75543|h[해골파쇄기]|h|r라는 엄청난 기술을 사용했어요! 다행히 전 놈이 기술을 날리기 전에 빠져나왔답니다!', `MaleText_loc4`='当我们被罗姆欧格伏击时，他用锁链将拉兹困住，然后用|cff71d5ff|Hspell:75543|h[碎颅]|h|r攻击他！幸好我在被他最后一击命中前走开了！', `MaleText_loc5`='我們被羅姆歐格埋伏攻擊時，他用鐵鍊圍住拉茲，然後用|cff71d5ff|Hspell:75543|h[碎顱]|h|r打他!我算幸運的了，在他發出最後一擊之前躲開了!', `MaleText_loc7`='¡Cuando sufrimos la emboscada de Rom''ogg, rodeó a Raz con cadena y luego le golpeó con |cff71d5ff|Hspell:75543|h[El Revientacalaveras]|h|r! ¡Afortunadamente, me moví antes de que cayera aquel golpe definitivo!' WHERE `ID`=49602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라앉은 도시에서, 그는 누워 꿈을 꾸고 있다.', `MaleText_loc4`='在那沉没的城市里，他陷入梦境。', `MaleText_loc5`='在沉沒之都中，他在夢境裡沉睡。', `MaleText_loc7`='En la ciudad sumergida, yace y sueña.' WHERE `ID`=49603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이크나스 크스리그 크이 므르운가 그르물라.', `MaleText_loc4`='Y''knath k''th''rygg k''yi mrr''ungha gr''mula。', `MaleText_loc5`='伊拿斯庫里格姆嘎哈格姆拉。', `MaleText_loc7`='Y''knath k''th''rygg k''yi mrr''ungha gr''mula.' WHERE `ID`=49604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 곳, 모든 것에는 영혼이 있다. 모든 영혼은 잡아먹을 수 있다.', `MaleText_loc4`='所有的地方，所有的事物都有灵魂。所有的灵魂都能被吞噬。', `MaleText_loc5`='在所有的地方，所有的東西都有靈魂。所有的靈魂都可以被吞噬。', `MaleText_loc7`='Todos los lugares, todas las cosas tienen almas. Todas las almas pueden ser devoradas.' WHERE `ID`=49605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실제와 가상을 딱 잘라 구분할 순 없다.', `MaleText_loc4`='在真实与虚幻之间没有明确的分界线。', `MaleText_loc5`='真實與非真實之間並沒有非常顯著的區別。', `MaleText_loc7`='No existe ninguna distinción clara entre lo real y lo irreal.' WHERE `ID`=49606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다고, $n!', `MaleText_loc4`='谢谢你，$n！', `MaleText_loc5`='謝謝，$n!', `MaleText_loc7`='¡Gracias, $n!', `FemaleText_loc1`='고마워요, $n 님!', `FemaleText_loc4`='谢谢你，$n！', `FemaleText_loc5`='謝謝，$n!', `FemaleText_loc7`='¡Gracias, $n!' WHERE `ID`=49607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니알로사의 땅에는 오직 잠이 있을 뿐.', `MaleText_loc4`='在尼奥罗萨的土地上，只有沉睡。', `MaleText_loc5`='在奈奧羅薩，只有沉睡。', `MaleText_loc7`='En la tierra de Ny''alotha solo existe el sueño.' WHERE `ID`=49608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 잠자며 꿈을 꾸는 것인가? 아니면 현실의 공포로부터 벗어나는 것인가?', `MaleText_loc4`='你在沉睡时做梦吗，或者是一种对现实恐惧的逃避？', `MaleText_loc5`='你在沉睡中會做夢，還是只是對現實中恐怖事物的一種逃避?', `MaleText_loc7`='¿Tú sueñas cuando duermes o es tan solo una forma de huir de los horrores de la realidad?' WHERE `ID`=49609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살았다!', `MaleText_loc4`='我得救了！', `MaleText_loc5`='我獲救了!', `MaleText_loc7`='¡Estoy salvado!', `FemaleText_loc1`='살았다!', `FemaleText_loc4`='我得救了！', `FemaleText_loc5`='我獲救了!', `FemaleText_loc7`='¡Estoy salvada!' WHERE `ID`=49610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니알로사의 잠자는 도시에는 광기의 존재만이 돌아다닌다.', `MaleText_loc4`='在沉睡之城尼奥罗萨中，只有疯狂在徘徊。', `MaleText_loc5`='在沉睡的城市奈奧羅薩中，四處行走的都是瘋狂的事物。', `MaleText_loc7`='En la ciudad durmiente de Ny''alotha solo caminan las cosas que están locas.' WHERE `ID`=49611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물놀이용 조랑말이군! 딱 필요한 순간인데!', `MaleText_loc4`='小马泳圈出现得太及时了！', `MaleText_loc5`='來得正是時候的小馬泳圈!', `MaleText_loc7`='¡Un poni flotador en cuestión de segundos!', `FemaleText_loc1`='물놀이용 조랑말이군요! 딱 필요한 순간인데!', `FemaleText_loc4`='小马泳圈出现得太及时了！', `FemaleText_loc5`='來得正是時候的小馬泳圈!', `FemaleText_loc7`='¡Un poni flotador en cuestión de segundos!' WHERE `ID`=49612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물에 빠져 죽는 줄 알았다고!', `MaleText_loc4`='我差点儿就淹死了！', `MaleText_loc5`='我本來一定會溺死的!', `MaleText_loc7`='¡Estaba condenado a ahogarme!', `FemaleText_loc1`='물에 빠져 죽는 줄 알았어요!', `FemaleText_loc4`='我差点儿就淹死了！', `FemaleText_loc5`='我本來一定會溺死的!', `FemaleText_loc7`='¡Estaba condenada a ahogarme!' WHERE `ID`=49613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 없이 잠자며 노려보는 깊은 산속의 집들은 늘 꿈을 꾼다. 집들을 파괴하는 것이 오히려 자비이리라.', `MaleText_loc4`='在林区深处静静沉睡与凝望着的房屋常常陷入梦境。把它们拆除无疑是善举。', `MaleText_loc5`='蠻荒地區那些安靜、沉睡、醒目的房子總是在做夢。把它們拆毀是一種慈悲。', `MaleText_loc7`='Las casas silenciosas, durmientes, que miran fijamente en esta región apartada siempre sueñan. Sería misericordioso derribarlas.' WHERE `ID`=49614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 구출됐군! 내가 얼마나 오래 개헤엄을 치고 있었는지 알아?', `MaleText_loc4`='是时候了！你知道我已经在这儿踩了多久水了？', `MaleText_loc5`='也該是時候了!你知道我在這裡淌多久的水了嗎?', `MaleText_loc7`='¡Ya era hora! ¿Sabes cuánto tiempo llevo aquí con los pies en el agua?', `FemaleText_loc1`='드디어 구출됐다! 제가 얼마나 오래 개헤엄을 치고 있었는지 아세요?', `FemaleText_loc4`='是时候了！你知道我已经在这儿踩了多久水了？', `FemaleText_loc5`='也該是時候了!你知道我在這裡淌多久的水了嗎?', `FemaleText_loc7`='¡Ya era hora! ¿Sabes cuánto tiempo llevo aquí con los pies en el agua?' WHERE `ID`=49615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별들은 바람을 휩쓸고, 사람들은 어둠 속에서 벌벌 떠네.', `MaleText_loc4`='辰星可驱散彻骨的寒意，让人们不会在黑暗中战栗。', `MaleText_loc5`='星星刮起冰冷的寒流，讓人們在黑暗中發抖。', `MaleText_loc7`='Las estrellas emiten corrientes frías que hacen que los hombres sientan escalofríos en la noche.' WHERE `ID`=49616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물놀이용 조랑말이 있으니 이제 혼자 돌아갈 수 있다고.', `MaleText_loc4`='有了小马泳圈，我就能回去了。', `MaleText_loc5`='有了小馬泳圈，我可以自己回去。', `MaleText_loc7`='Con el poni flotador puedo volver.', `FemaleText_loc1`='물놀이용 조랑말이 있으니 이제 혼자 돌아갈 수 있어요.', `FemaleText_loc4`='有了小马泳圈，我就能回去了。', `FemaleText_loc5`='有了小馬泳圈，我可以自己回去。', `FemaleText_loc7`='Con el poni flotador puedo volver.' WHERE `ID`=49617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니알로사는 오래되고, 끔찍하고, 셀 수 없이 많은 범죄의 도시이다.', `MaleText_loc4`='在尼奥罗萨这座城市中充满着不计其数的古老而又可怖的罪行。', `MaleText_loc5`='奈奧羅薩是一個古老、可怕、罪行難以計數的城市。', `MaleText_loc7`='Ny''alotha es una ciudad antigua, terrible, de innumerables crímenes.' WHERE `ID`=49618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음도 죽음을 피하지 못하리라.', `MaleText_loc4`='就连死神也会死亡。', `MaleText_loc5`='即使死亡本身都會死去。', `MaleText_loc7`='Incluso la muerte podría morir.' WHERE `ID`=49619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다고, 친구. 로켓 점프가 안 통하더라고.', `MaleText_loc4`='谢谢你，朋友。我的火箭跳失败了。', `MaleText_loc5`='謝謝，朋友。我的火箭跳躍失敗了。', `MaleText_loc7`='Gracias, $gamigo:amiga;. Mi salto de cohete me ha salido rana.', `FemaleText_loc1`='고마워요, 친구. 로켓 점프가 안 통하더라고요.', `FemaleText_loc4`='谢谢你，朋友。我的火箭跳失败了。', `FemaleText_loc5`='謝謝，朋友。我的火箭跳躍失敗了。', `FemaleText_loc7`='Gracias, $gamigo:amiga;. Mi salto de cohete me ha salido rana.' WHERE `ID`=49620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 기적 같은 일이!', `MaleText_loc4`='你可真是个奇迹般的劳动者，$n！', `MaleText_loc5`='你真是個奇蹟製造者啊，$n!', `MaleText_loc7`='¡Eres $gun trabajador milagroso:una trabajadora milagrosa;, $n!', `FemaleText_loc1`='이런 기적 같은 일이!', `FemaleText_loc4`='你可真是个奇迹般的劳动者，$n！', `FemaleText_loc5`='你真是個奇蹟製造者啊，$n!', `FemaleText_loc7`='¡Eres $gun trabajador milagroso:una trabajadora milagrosa;, $n!' WHERE `ID`=49621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 당신은 홀로 남을 것이다.', `MaleText_loc4`='你们最后都将是孤身一人。', `MaleText_loc5`='到了最後，你會是獨自一人。', `MaleText_loc7`='Al final estarás tú $gsolo:sola;.' WHERE `ID`=49622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물에 잠긴 신의 심장은 검은 얼음이다.', `MaleText_loc4`='那溺死之神的心有如黑冰。', `MaleText_loc5`='溺死的神祇，他的心是黑冰。', `MaleText_loc7`='El corazón del dios ahogado es hielo negro.' WHERE `ID`=49623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 숲에서 길 잃은 작은 양 한 마리 있으니.', `MaleText_loc4`='在那幽暗的密林里有一只迷途的小羊羔。', `MaleText_loc5`='在黑暗的樹林間，有一頭小羔羊迷路了。', `MaleText_loc7`='Hay un pequeño cordero perdido en los bosques oscuros.' WHERE `ID`=49624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 까마귀가 죽은 나무 위에서 내려다보고 있다. 그 그림자 밑에서는 모든 것이 숨을 멈춘다.', `MaleText_loc4`='巨鸦警惕的目光在枯木间游移。在他的阴影之下，听闻不到半点儿气息。', `MaleText_loc5`='巨鳥從死氣沈沈的樹上看著。在他的陰影之中，沒有任何生物的呼吸。', `MaleText_loc7`='Un grajo gigante observa desde los árboles muertos. Nada respira debajo de su sombra.' WHERE `ID`=49625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 그 꿈을 꾸었는가? 눈이 일곱 개 달린 검은 염소가 밖에서 쳐다보는 꿈을...', `MaleText_loc4`='你又做同样的梦了？长着七只眼睛的黑羊从外面投来炯炯的目光。', `MaleText_loc5`='你又做同樣的夢了嗎?一頭黑色的山羊，有著七隻眼睛，從外面注視著。', `MaleText_loc7`='¿Has tenido el sueño otra vez? Una cabra negra con siete ojos que observa desde el exterior.' WHERE `ID`=49626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘러보라. 그들은 모두 당신을 배신할 것이다. 비명을 지르며 검은 숲으로 도망가라.', `MaleText_loc4`='看看你的周围。他们全都会背叛你。尖叫着逃进漆黑的森林。', `MaleText_loc5`='看看四周。它們全都會背叛你。你會大喊著逃進黑暗的森林中。', `MaleText_loc7`='Mira alrededor. Todos te traicionarán. Huye al bosque negro sin dejar de gritar.' WHERE `ID`=49627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대양의 바닥에선 빛조차도 죽으리니.', `MaleText_loc4`='在深邃的洋底，就连圣光也必将熄灭。', `MaleText_loc5`='在海底，即使光線都無法抵達。', `MaleText_loc7`='En el fondo del océano incluso la luz debe morir.' WHERE `ID`=49628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 열어줘! 날 열어줘! 날 열어줘! 그래야만 당신은 평화를 알 수 있다.', `MaleText_loc4`='打开我！打开我！打开我！然后你才能获知平静的意义。', `MaleText_loc5`='打開我!打開我!打開我!這樣我就不會吵你。', `MaleText_loc7`='¡Ábreme! ¡Ábreme! ¡Ábreme! Solo entonces tendrás paz.' WHERE `ID`=49629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올가미덩굴 씨앗을 얻었습니다!', `MaleText_loc4`='你获得了窒息藤种子！', `MaleText_loc5`='你獲得了扼殺者藤蔓種子!', `MaleText_loc7`='¡Has ganado semillas de parra asfixiadora!', `FemaleText_loc1`='올가미덩굴 씨앗을 얻었습니다!', `FemaleText_loc4`='你获得了窒息藤种子！', `FemaleText_loc5`='你獲得了扼殺者藤蔓種子!', `FemaleText_loc7`='¡Has ganado semillas de parra asfixiadora!' WHERE `ID`=49630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 물고기들은 비밀을 모두 알고 있다. 그들은 추위를 안다. 그들은 어둠을 안다.', `MaleText_loc4`='鱼群知道所有的秘密。它们熟知寒冷。它们熟知黑暗。', `MaleText_loc5`='魚群知道所有的秘密。牠們了解那樣的冰冷。牠們了解那樣的黑暗。', `MaleText_loc7`='Los peces conocen todos los secretos. Conocen el frío. Conocen la oscuridad.' WHERE `ID`=49631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것은 바로 당신 뒤에 서 있다. 움직이지 마라. 숨 쉬지 마라.', `MaleText_loc4`='它就站在你身后。不要移动。不要呼吸。', `MaleText_loc5`='它正站在你的後面。不要動。不要呼吸。', `MaleText_loc7`='Está justo detrás de ti. No te muevas. No respires.' WHERE `ID`=49632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조의 고통스러운 영혼들이 침묵의 비명을 지르며 당신에게 매달린다. 얼핏 봐도 영혼의 수가 상당히 많다.', `MaleText_loc4`='先祖们饱受折磨的灵魂紧攫住你，无声地尖啸着。他们显然数量众多。', `MaleText_loc5`='你先祖們受盡折磨的靈魂還緊抓著你，在沉默中厲聲尖嘯。他們的人數看起來還真不少。', `MaleText_loc7`='Los espíritus atormentados de tus ancestros te acosan gritando en silencio. Al parecer, son bastantes.' WHERE `ID`=49633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇이 사람의 본성을 바꿀 수 있는가?', `MaleText_loc4`='什么能改变一个人的本性？', `MaleText_loc5`='什麼東西可以改變一個人的本性?', `MaleText_loc7`='¿Qué puede cambiar la naturaleza de un hombre?' WHERE `ID`=49634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구울이 바닥에 뭔가를 떨어뜨렸습니다!', `MaleText_loc4`='一只食尸鬼把什么东西丢到了地上！', `MaleText_loc5`='一個食屍鬼在地上丟了某種東西!', `MaleText_loc7`='¡Un necrófago ha dejado caer algo en el campo!', `FemaleText_loc1`='구울이 바닥에 뭔가를 떨어뜨렸습니다!', `FemaleText_loc4`='一只食尸鬼把什么东西丢到了地上！', `FemaleText_loc5`='一個食屍鬼在地上丟了某種東西!', `FemaleText_loc7`='¡Un necrófago ha dejado caer algo en el campo!' WHERE `ID`=49635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 저항한다. 당신의 목숨에 의미라도 있는 양 놓질 못하고 있다. 곧 알게 되리라.', `MaleText_loc4`='你顽强抗拒。你紧抓住自己的生命，仿佛真能改变一切。你会了解的。', `MaleText_loc5`='你在抵抗。你還緊抓著你的生命，以為那真的很重要。你會學到教訓的。', `MaleText_loc7`='Te resistes. Te aferras a tu vida como si importara algo. Ya aprenderás.' WHERE `ID`=49636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명은 약하고, 덧없고, 순식간에 끝나... 쉽게 망가지지.', `MaleText_loc4`='软弱，短暂，易碎，生命必将终结。', `MaleText_loc5`='生命十分軟弱、平庸、短暫...脆弱。', `MaleText_loc7`='La vida es débil, mortal, efímera... frágil.' WHERE `ID`=49637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후에 오는 것은 죽음이다. 죽음은 영원하지. 죽음은... 내 영역이다.', `MaleText_loc4`='死亡才是终途，死亡才是永恒，死亡……是我的领域。', `MaleText_loc5`='死亡是終點，死亡才是永恆的。死亡...是我的領域。', `MaleText_loc7`='La muerte es definitiva. Eterna. La muerte es... mi reino.' WHERE `ID`=49638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 보아라. 죽음의 화신, 세계를 파괴하는 자를 똑똑히 보란 말이다.', `MaleText_loc4`='面对我，面对死亡的化身，世界的毁灭者！', `MaleText_loc5`='看著我的同時，你就看到了死亡的化身，諸界的毀滅者。', `MaleText_loc7`='Contémplame y ve la muerte encarnada, el destructor de mundos.' WHERE `ID`=49639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축하한다, 모험가들이여.', `FemaleText_loc4`='恭喜你，冒险者。', `FemaleText_loc5`='冒險者，恭喜。', `FemaleText_loc7`='Felicidades, $gaventurero:aventurera;.' WHERE `ID`=49640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 읽습니다... <주의: 계속해서 읽으면 여러분이 여기 온 것을 바네사가 알게 됩니다!>', `MaleText_loc4`='继续阅读……<注意：这将使梵妮莎注意到你的存在！>', `MaleText_loc5`='繼續閱讀...<注意:這會讓凡妮莎知道你在這裡!>', `MaleText_loc7`='Sigue leyendo... <Nota: ¡Esto alertará a Vanessa de tu presencia!>', `FemaleText_loc1`='계속해서 읽습니다... <주의: 계속해서 읽으면 여러분이 여기 온 것을 바네사가 알게 됩니다!>', `FemaleText_loc4`='继续阅读……<注意：这将使梵妮莎注意到你的存在！>', `FemaleText_loc5`='繼續閱讀...<注意:這會讓凡妮莎知道你在這裡!>', `FemaleText_loc7`='Sigue leyendo... <Nota: ¡Esto alertará a Vanessa de tu presencia!>' WHERE `ID`=49641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙게도 내가 만든 덫 안으로 기어들어와 줬구나!', `FemaleText_loc4`='你已经径直走进了我的陷阱！', `FemaleText_loc5`='你直接掉進了我的圈套中!', `FemaleText_loc7`='¡Te las has arreglado para caer directamente en mi trampa!' WHERE `ID`=49642;
