UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급구조 물놀이용 조랑말은 많다고, $n. 바다에 빠진 우리 일꾼들한테 막 던져 줘.', `MaleText_loc4`='我有许多应急小马泳圈，$n。把它们扔给水中的劳工们。', `MaleText_loc5`='我還有很多緊急小馬泳圈，$n。請把它們丟給我們在水中的工人。', `MaleText_loc7`='Tengo un montón de ponis flotadores de emergencia, $n. Por favor, lánzaselos a nuestros trabajadores que están abajo, en el agua.' WHERE `ID`=49644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 크라즈작업장의 구세주!', `MaleText_loc4`='$n，卡拉兹工坊的救星！', `MaleText_loc5`='$n，克拉茲工坊的拯救者!', `MaleText_loc7`='¡$n, Salvador de La Krazzería!' WHERE `ID`=49645;
