UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시초의 전당은 여기서 바로 동쪽, 타나리스 사막 근처에 있습니다. 꽤 오래 걸어야 하니, 당장 출발하는 게 좋겠군요.', `MaleText_loc4`='起源大厅就在东面，靠近塔纳利斯沙漠。要走一阵子才能到，所以我们最好尽快动身。', `MaleText_loc5`='起源大廳就在這裡的東邊，靠近塔納利斯的沙漠。距離有點遠，所以我們最好趕快動身。', `MaleText_loc7`='Las Cámaras de los Orígenes yacen al este de aquí, cerca de las arenas del Desierto de Tanaris. Es una buena caminata, así que será mejor que te pongas en marcha.' WHERE `ID`=49651;
