UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 피곤해...', `MaleText_loc4`='我太累了……', `MaleText_loc5`='我好累...', `MaleText_loc7`='Estoy tan cansado...', `FemaleText_loc1`='너무 피곤해...', `FemaleText_loc4`='我太累了……', `FemaleText_loc5`='我好累...', `FemaleText_loc7`='Estoy tan cansada...' WHERE `ID`=49655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기본으로 지급되는 긴급구조 물놀이용 조랑말 조끼를 착용했어야 했는데...', `MaleText_loc4`='要是我没忘记穿上标准型紧急救生衣就好了。', `MaleText_loc5`='如果我記得穿我的標準式緊急小馬泳圈背心就好了。', `MaleText_loc7`='Ojalá me hubiera acordado de ponerme el chaleco de emergencia de poni flotador estándar.', `FemaleText_loc1`='기본으로 지급되는 긴급구조 물놀이용 조랑말 조끼를 착용했어야 했는데...', `FemaleText_loc4`='要是我没忘记穿上标准型紧急救生衣就好了。', `FemaleText_loc5`='如果我記得穿我的標準式緊急小馬泳圈背心就好了。', `FemaleText_loc7`='Ojalá me hubiera acordado de ponerme el chaleco de emergencia de poni flotador estándar.' WHERE `ID`=49656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 거기! 도와줘!', `MaleText_loc4`='嘿，说你呢！帮帮忙！', `MaleText_loc5`='喂!救命!', `MaleText_loc7`='¡Eh, tú! ¡Ayuda!', `FemaleText_loc1`='이봐요! 도와줘요!', `FemaleText_loc4`='嘿，说你呢！帮帮忙！', `FemaleText_loc5`='喂!救命!', `FemaleText_loc7`='¡Eh, tú! ¡Ayuda!' WHERE `ID`=49657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바닥에 쪽지가 한 장 떨어집니다!', `FemaleText_loc4`='一张便笺掉在了地上！', `FemaleText_loc5`='一張筆記掉到了地上!', `FemaleText_loc7`='¡Una nota cae al suelo!' WHERE `ID`=49658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 성궤 안에 너무 오랫동안 갇혀 있어서 그런지 아직도 허리가 쑤시는군요. 제가 좀 천천히 걷더라도 이해해 주시길.', `MaleText_loc4`='我被困住太久了，到现在仍然感到腰酸背痛。要是我动作有些慢的话，请原谅……', `MaleText_loc5`='我的背還是有點僵硬，卡在那個櫃子裡面這麼久。如果我有點緩慢，請別介意...', `MaleText_loc7`='Quizá esté un poco agarrotado tras pasar tanto tiempo dentro de ese baúl. Ten paciencia conmigo si voy un poco despacio...' WHERE `ID`=49659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테서 떨어지지 마세요! 언제 데스윙의 부하가 나타나서 우리를 곤경에 처하게 할지 아무도 모르니까요!', `MaleText_loc4`='跟紧了！你永远不会知道死亡之翼的爪牙会什么时候突然冲出来，让我们的行动提早夭折！', `MaleText_loc5`='靠近一點!你不知道死亡之翼的爪牙何時會飛過來提早終結我們的任務!', `MaleText_loc7`='¡Quédate cerca! ¡Nunca se sabe cuándo los agentes de Alamuerte andan cerca con la intención de poner un temprano final a nuestra misión!' WHERE `ID`=49660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 먼 길이 되겠지만, 크게 방해만 받지 않는다면 오늘이 가기 전에 도착할 수 있겠네요. 우리 음식은 좀 있나요?', `MaleText_loc4`='这可真是长途跋涉，不过如果我们能不受干扰的话，应该能在天黑以前到达目的地。你身上带吃的了吗？', `MaleText_loc5`='這個旅程有點遠，但是如果我們能避開不必要的騷擾，我們應該可以在晚上之前抵達。你身上有食物吧?', `MaleText_loc7`='Será un largo viaje, pero si conseguimos evitar cualquier hostilidad, deberíamos llegar al final del día. ¿Llevas algo de comida?' WHERE `ID`=49661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 당신 갈 길에 방해만 되고 있군요! 이렇게 천천히 걸어야 하다니... 웃음거리가 될 것만 같아요.', `MaleText_loc4`='我简直是在拖你后腿啊，$g小伙子:小姑娘;！这么慢的步伐……真是逗人发笑！', `MaleText_loc5`='我只是在拖慢你，$g小伙子:小姑娘;!走得這麼慢...總是很好笑!', `MaleText_loc7`='¡Tan solo te estaba tomando el pelo, $gmuchacho:muchacha;! ¡Cuando se camina a una marcha lenta siempre hay tiempo para unas risas!' WHERE `ID`=49662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 가세요. 이 원반의 암호를 풀자마자 거기로 당신을 찾아갈 테니.', `MaleText_loc4`='你继续前进。等我破解了这些磁盘，就去与你会合。', `MaleText_loc5`='你先走吧。等我解出這些圓盤的秘密，我就會跟你在那裡會合。', `MaleText_loc7`='Tú sigue. Me reuniré contigo en cuanto consiga desencriptar estos discos.' WHERE `ID`=49663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알드랏실 안에서 직업 상급자를 찾을 수 있을 것입니다, $n.', `MaleText_loc4`='你可以在奥达希尔找到训练师，$n。', `MaleText_loc5`='你可以在奧達希爾裡面找到訓練師的，$n。', `MaleText_loc7`='Encontrarás al instructor dentro de Aldrassil, $n.' WHERE `ID`=49664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그늘 거미굴은 북쪽에 있어요. 최근 들어 아주 위험해졌으니 조심하세요.', `FemaleText_loc4`='黑丝洞就在北面。多加小心，那里近来危机四伏。', `FemaleText_loc5`='影絲洞就在這的北邊。小心點，那裡一旦入夜便會變得危險。', `FemaleText_loc7`='La Gruta Narácnida queda al norte. Ten cuidado, últimamente se ha vuelto un lugar peligroso.' WHERE `ID`=49665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달샘은 북동쪽에 있는 연못의 다른 쪽과 언덕 위에 있어요.', `FemaleText_loc4`='月亮井在东北面，在水池另一侧的山上。', `FemaleText_loc5`='月井在東北邊，池子另一邊的山丘上。', `FemaleText_loc7`='La Poza de la Luna queda al noreste, al otro lado de la charca y colina arriba.' WHERE `ID`=49666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알드랏실로 가는 길은 바로 저기 보이는 곳에 있어요. 길을 따라 돌아 올라가 그 위에 있는 테나론을 만나보세요.', `FemaleText_loc4`='通往奥达希尔的梯道就在那边。盘旋而上就能找到特纳隆。', `FemaleText_loc5`='往奧達希爾的山坡就在眼前。去繞一繞和找到在上面的特納隆。', `FemaleText_loc7`='Desde ahí se puede ver la rampa que sube a Aldrassil. Súbela y encontrarás a Tenaron en lo más alto.' WHERE `ID`=49667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이베론이 앓던 독이 치유되었어요. 하지만 회복하려면 시간이 좀 걸릴 거예요.', `FemaleText_loc4`='埃沃隆身上的毒素已经散去，但还需要一些时间才能复原。', `FemaleText_loc5`='埃沃隆的毒已經清掉了，但還是必須花點時間才能完全康復。', `FemaleText_loc7`='El envenenamiento de Iverron está curado, pero le llevará un tiempo recuperarse del todo.' WHERE `ID`=49668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타락이 거미 몸 깊은 곳 안에 묻혀 있어요.', `FemaleText_loc4`='腐坏的种子已深植在他体内。', `FemaleText_loc5`='腐化已經埋藏在他的內心深處。', `FemaleText_loc7`='La corrupción está arraigada en lo más profundo de su interior.' WHERE `ID`=49669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거미들을 구할 방법이 없는 것은 분명하지만, 죽는 것을 보니 가슴이 아프네요.', `FemaleText_loc4`='他们当然已是无可挽回，但看着他们死去，还是令人感到心如刀绞。', `FemaleText_loc5`='他們絕對是罪不可赦的，但就這樣看著他們死去感覺還是不好受。', `FemaleText_loc7`='Con toda seguridad no se pueden redimir, pero a pesar de todo duele verles morir.' WHERE `ID`=49670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소중한 내 친구... 미안해요...', `FemaleText_loc4`='我亲爱的朋友们……我很抱歉……', `FemaleText_loc5`='我親愛的朋友...我很抱歉...', `FemaleText_loc7`='Mis queridos amigos... Lo siento mucho...' WHERE `ID`=49671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거미들의 몸은 죽어가지만, 영혼은 자비를 구하고 있어요.', `FemaleText_loc4`='他的躯体在渴求死亡，可他的灵魂却在渴求怜悯。', `FemaleText_loc5`='他的肉體哭求著死亡，但他的靈魂哭求著憐憫。', `FemaleText_loc7`='Su cuerpo clama la muerte, su alma pide clemencia a gritos.' WHERE `ID`=49672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타락은 이 거미들이 있는 곳보다도 더 멀리 퍼졌어요. 타락의 진정한 원인이 이 동굴 안에 없을까 봐 걱정이에요.', `FemaleText_loc4`='腐化的程度远非这些蜘蛛力量能及。我担心真正的源头并不在这洞穴之中。', `FemaleText_loc5`='腐化的範圍遠超過了這些蜘蛛。我想腐化真正的源頭恐怕不是在這洞穴中。', `FemaleText_loc7`='La corrupción va mucho más allá de esas arañas. Me temo que el verdadero origen no está dentro de esta cueva.' WHERE `ID`=49673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 저지르는 이 잔혹한 행위에 눈물이 흘러요. 정말 견딜 수가 없어요.', `FemaleText_loc4`='我为我们犯下的这些罪行而哭泣。简直令人难以忍受。', `FemaleText_loc5`='我為我們所犯的暴行感到悲傷。這簡直另人無法承受。', `FemaleText_loc7`='Lloro ante las atrocidades que cometemos. Es casi insoportable.' WHERE `ID`=49674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 정도로 심각한 타락이라면 외부에서 비롯될 수 있는 게 아니에요.', `FemaleText_loc4`='如此程度的腐化不可能源自外部。', `FemaleText_loc5`='如此深度的腐化不會是從外面而來的。', `FemaleText_loc7`='Una corrupción tan profunda no ha podido llegar desde el exterior.' WHERE `ID`=49675;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거미는 마치 태어날 때부터 몸 안에 이 타락을 가졌던 것처럼 보여요.', `FemaleText_loc4`='他体内的腐化仿佛是与生俱来的。', `FemaleText_loc5`='這腐化看起來就像他出生時就已經跟著他了。', `FemaleText_loc7`='Casi parece que hubiera nacido con esa corrupción en su interior.' WHERE `ID`=49676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 더 가르쳐 드릴 건 없어요. 지금은 동쪽에 있는 치유사의 처소로 가세요. 당신은 안돌할 전투가 시작되면 소환될 거예요. 콜티라가 너무 오래 기다리지 않으면 좋을 텐데...', `FemaleText_loc4`='我已经没有新东西要教你了。现在继续向东，前往治愈者营地吧。当安多哈尔之战打响之时，你将受到召唤。希望库尔迪拉没有等太久……', `FemaleText_loc5`='你已經完成了所有的訓練。你現在必須往東走，到治癒者崗哨。當安多哈爾之戰開始時會召喚你。希望寇爾提拉沒有等太久...', `FemaleText_loc7`='No puedo instruirte más. Por ahora, continúa al este hasta La Finca de los Ensalmadores. Serás $gconvocado:convocada; cuando comience la batalla por Andorhal. Con suerte, Koltira no esperará demasiado...' WHERE `ID`=49677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 막아냈습니다!$B$B호박 폭탄을 사용할 수 있습니다!', `MaleText_loc4`='你成功抵御了敌人的攻势！$B南瓜炸弹已解锁！', `MaleText_loc5`='你成功防禦了攻擊!$B南瓜炸彈已解鎖!', `MaleText_loc7`='¡Te has defendido del ataque!$B$B¡Bombas de calabaza desbloqueadas!', `FemaleText_loc1`='공격을 막아냈습니다!$B$B호박 폭탄을 사용할 수 있습니다!', `FemaleText_loc4`='你成功抵御了敌人的攻势！$B南瓜炸弹已解锁！', `FemaleText_loc5`='你成功防禦了攻擊!$B南瓜炸彈已解鎖!', `FemaleText_loc7`='¡Te has defendido del ataque!$B$B¡Bombas de calabaza desbloqueadas!' WHERE `ID`=49678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님께서 지켜보고 계시네.', `MaleText_loc4`='黑暗女王在注视着你。', `MaleText_loc5`='願黑暗女王照看你。', `MaleText_loc7`='Que la Dama Oscura cuide de ti.' WHERE `ID`=49679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증기 밸브를 움직여 탈출하십시오!', `MaleText_loc4`='打开气阀来释放你自己！', `MaleText_loc5`='啟動蒸汽閥來逃走!', `MaleText_loc7`='¡Activa las válvulas de vapor para salvarte!', `FemaleText_loc1`='증기 밸브를 움직여 탈출하십시오!', `FemaleText_loc4`='打开气阀来释放你自己！', `FemaleText_loc5`='啟動蒸汽閥來逃走!', `FemaleText_loc7`='¡Activa las válvulas de vapor para salvarte!' WHERE `ID`=49680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다, 여사냥꾼님. 우리 쪽의 신규 $c 중에 준비된 이가 아무도 없습니다. 아직 배울 게 너무 많아서 말입니다.', `MaleText_loc4`='抱歉，女猎手。我们的新$c都还没准备好。他们还有许多东西要学。', `MaleText_loc5`='很抱歉，女獵手。我們新的$c都還沒準備好。他們還有很多要學的。', `MaleText_loc7`='Lo siento, cazadora. $gNingún:Ninguna; $c está $gpreparado:preparada;. Todavía tienen que aprender mucho.' WHERE `ID`=49681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 우리 편을 들어주지 않을까 두렵군요, 일사레인. 서두르지 않는다면 전쟁이 텔드랏실까지 번질지도 모릅니다.', `FemaleText_loc4`='恐怕我们并没有时间优势，伊尔萨莱恩。如果我们不尽快开始行动，就连泰达希尔也将难逃战火的席卷。', `FemaleText_loc5`='我想我們恐怕沒有那麼多時間，伊爾薩萊恩。如果我們不有所行動，戰火便會延燒至泰達希爾。', `FemaleText_loc7`='Me temo que el tiempo no está de nuestra parte, Ilthalaine. Si no actuamos pronto, puede que la batalla llegue al mismo Teldrassil.' WHERE `ID`=49682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련은 그대에게 맡길게요, 일사레인. 이 일은 그대가 전문이니까요.', `FemaleText_loc4`='我们会让你继续你的训练，伊尔萨莱恩。在这方面你才是行家。', `FemaleText_loc5`='我們不打擾你的訓練了，伊爾薩萊恩。這是你的專門領域。', `FemaleText_loc7`='Te dejaremos con tu instrucción, Ilthalaine. Esta es tu área de conocimiento.' WHERE `ID`=49683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열심히 단련하세요, $n. 다음 달이 차오르기 전에 우리와 함께 싸워야 할지도 모르니까요.', `FemaleText_loc4`='好好学习吧，$n。在下个月满之夜到来之前，我们可能会需要你协同作战。', `FemaleText_loc5`='好好學，$n。我們在下次月圓時或許會需要你與我們並肩而戰。', `FemaleText_loc7`='Estudia duro, $n. Quizá necesitemos que luches a nuestro lado antes que llegue la próxima luna llena.' WHERE `ID`=49684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비가 바닥에 뭔가를 떨어뜨렸습니다!', `MaleText_loc4`='一只僵尸把什么东西丢到了地上！', `MaleText_loc5`='一個殭屍在地上丟了某種東西!', `MaleText_loc7`='¡Un zombi ha dejado caer algo en el campo!', `FemaleText_loc1`='좀비가 바닥에 뭔가를 떨어뜨렸습니다!', `FemaleText_loc4`='一只僵尸把什么东西丢到了地上！', `FemaleText_loc5`='一個殭屍在地上丟了某種東西!', `FemaleText_loc7`='¡Un zombi ha dejado caer algo en el campo!' WHERE `ID`=49685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽁꽁송이 씨앗을 얻었습니다!', `MaleText_loc4`='你获得了冻结草种子！', `MaleText_loc5`='你獲得了凍凍草的果實!', `MaleText_loc7`='¡Has ganado semillas de frisia!', `FemaleText_loc1`='꽁꽁송이 씨앗을 얻었습니다!', `FemaleText_loc4`='你获得了冻结草种子！', `FemaleText_loc5`='你獲得了凍凍草的果實!', `FemaleText_loc7`='¡Has ganado semillas de frisia!' WHERE `ID`=49686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈어요! 이제 제어실로 들어갑시다!', `MaleText_loc4`='我们成功了！控制室被攻破了！', `MaleText_loc5`='我們成功了!控制室突破!', `MaleText_loc7`='¡Lo logramos! ¡Hemos alcanzado la sala de control!' WHERE `ID`=49687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 좋아요! 이제 잠깐이면 됩니다...', `MaleText_loc4`='我们走！这下应该用不了多少时间了……', `MaleText_loc5`='噢，好啦!再等一下就行了...', `MaleText_loc7`='¡Allá vamos! Solo debería llevarnos un momento...' WHERE `ID`=49688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리우스 님! 좋습니다! 차원문이 작동하니 병력을 고스란히 전방으로 보낼 수 있습니다.', `MaleText_loc4`='塞纳留斯！太棒了！传送门一旦激活，我们就能畅通无阻地把军队送往前线。', `MaleText_loc5`='塞納留斯!太好了!只要這個傳送門持續作用，我們就可以自由地把兵力送到前線。', `MaleText_loc7`='¡Cenarius! ¡Excelente! Ahora que el portal está activo, podemos mover a nuestra fuerzas hasta las líneas del frente sin problemas.' WHERE `ID`=49689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 반갑습니다, 말로른의 아들이여! 그대의 힘은 아꼈다가 불의 군주를 공격하는 데 써야 합니다.', `MaleText_loc4`='你是这里最受欢迎的人，玛诺恩之子！我们必须保存你的力量，以使你能率领先头部队攻击炎魔之王。', `MaleText_loc5`='很高興能看到你，瑪洛尼之子!我們必須保存你的力量，讓你可以在對付炎魔時擔任主力。', `MaleText_loc7`='¡Eres más que bienvenido, hijo de Malorne! Debemos preservar tu poder para que puedas dirigir el ataque contra el Señor del Fuego.' WHERE `ID`=49690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 나에게 맡겨라.', `FemaleText_loc4`='交给我吧。', `FemaleText_loc5`='交給我。', `FemaleText_loc7`='Déjame eso a mí.' WHERE `ID`=49691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 죽었습니다!', `MaleText_loc4`='僵尸吃掉了你的脑子！', `MaleText_loc5`='殭屍吃了你的大腦!', `MaleText_loc7`='¡Los zombis se han comido tu cerebro!', `FemaleText_loc1`='당신은 죽었습니다!', `FemaleText_loc4`='僵尸吃掉了你的脑子！', `FemaleText_loc5`='殭屍吃了你的大腦!', `FemaleText_loc7`='¡Los zombis se han comido tu cerebro!' WHERE `ID`=49692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 저 와일드해머 놈들을 비행장에서 싹 치워버리세요!', `MaleText_loc4`='$n，把这群蛮锤渣滓赶出我的机场！', `MaleText_loc5`='$n，把這些蠻錘趕出我的機場!', `MaleText_loc7`='¡$n, saca a esos Martillo Salvaje de mi base aérea!' WHERE `ID`=49693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 저를 치유해줬으니 감사의 인사를 해야 한다고 들었습니다. 진심으로 감사드립니다.', `MaleText_loc4`='我听说多亏了你的帮助，我才得到了治愈。谢谢你。衷心地向你表示感谢。', `MaleText_loc5`='我聽說我能被治癒是仰賴了你的幫忙。謝謝你。真的很感謝你。', `MaleText_loc7`='He oído que es a ti a quien tengo que darte las gracias por sanarme. Gracias. De corazón.' WHERE `ID`=49694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 용들은? 놈들의 본거지에는 용들이 더 많을 것이다.', `MaleText_loc4`='那些暮光巨龙呢？从源头还会涌来更多。', `MaleText_loc5`='那些暮光龍呢?從他們來的地方一定還有更多。', `MaleText_loc7`='¿Qué hay de los dragones Crepusculares? Habrá más en el lugar del que han venido esos.' WHERE `ID`=49695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님.', `MaleText_loc4`='你好啊，$c。', `MaleText_loc5`='歡迎，$c。', `MaleText_loc7`='Saludos, $c.' WHERE `ID`=49696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 토템이 알을 타락시켜 왔어요! 더욱 커다란 위협이 닥칠 것 같아요. 나무옹이 일족은 아직도 정말 사악한 무언가에 의해 오염되어 있어요.', `FemaleText_loc4`='这个图腾正在腐蚀这些蛋！这后面很可能隐藏着一个更加巨大的威胁。瘤背一族仍然在遭受某种极端邪恶的污染。', `FemaleText_loc5`='這個圖騰一直在腐化卵!一個更大的危機似乎浮出了。瘤背還是在被什麼很邪惡的東西污染著。', `FemaleText_loc7`='¡Este tótem ha corrompido los huevos! Al parecer una amenaza mayor se avecina. Los Tuercepinos siguen corruptos por algo mucho más repugnante.' WHERE `ID`=49697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄청나게 간단한 임무였습니다. 크라즈작업장 상자 비행장을 설치하고, 평소 하던 조사 작업을 계속하는 거지요.$B$B그런데 왜 제 주변엔 멍청이만 있는 거냐고요!', `MaleText_loc4`='我们要做的，就是部署卡拉兹工坊微型机场，然后开始例行考察任务。$B$B我被白痴包围了！', `MaleText_loc5`='我們需要做的就是把克拉茲工坊的盒中機場打開，然後開始例行性的勘測任務。$B$B我的周圍全是白痴!', `MaleText_loc7`='Todo lo que teníamos que hacer era desplegar la base aérea de bolsillo de La Krazzería y comenzar con nuestra rutina de misiones de reconocimiento.$B$B¡Estoy rodeado de idiotas!' WHERE `ID`=49698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬그럼!', `FemaleText_loc4`='赫格拉姆！', `FemaleText_loc5`='赫格拉姆!', `FemaleText_loc7`='¡Helgrum!' WHERE `ID`=49699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니카, 넌 괜한 자책감 때문에 그러는 거야...', `MaleText_loc4`='羞愧才是你显得愚蠢的唯一缘由，尼卡……', `MaleText_loc5`='只有你的難為情是蠢話，尼卡...', `MaleText_loc7`='Tan solo eres tonta en tu vergüenza, Neeka...' WHERE `ID`=49700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 우리가 얼마나 강해져야 하는지 말해주곤 했지... 약해져선 안 된다고...', `MaleText_loc4`='你曾经告诉我，我们该如何变得坚强……你是如何无法负担软弱的代价……', `MaleText_loc5`='你曾經告訴我我們該如何堅強...你曾說你不能變得軟弱...', `MaleText_loc7`='Solías decirme que teníamos que ser duros... que no podías permitirte ser blanda...' WHERE `ID`=49701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 강했던 만큼, 내 품에선 연약한 여자였어. 언제나...', `MaleText_loc4`='不论你有多坚强，你在我的臂弯中却始终软弱。', `MaleText_loc5`='像你這樣堅強的人，你在我的雙臂中卻總是軟弱。', `MaleText_loc7`='Por muy dura que fueras, siempre fuiste blanda y suave en mis brazos.' WHERE `ID`=49702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강해져야 해, 니카. 내가 하늘에서 지켜볼게...', `MaleText_loc4`='坚强些，尼卡。我会注视着你……', `MaleText_loc5`='抬頭挺胸，尼卡。我會看顧你的。', `MaleText_loc7`='Sé fuerte, Neeka. Yo cuidaré de ti...' WHERE `ID`=49703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 강해져야 해, 니카. 내가 하늘에서 지켜볼게...', `FemaleText_loc4`='坚强些，尼卡。我会注视着你……', `FemaleText_loc5`='堅強點，尼卡。我會保護你的...', `FemaleText_loc7`='Sé fuerte, Neeka. Yo cuidaré de ti...' WHERE `ID`=49704;
