UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽의 비약 효력이 떨어졌습니다!', `MaleText_loc4`='噩梦药剂的效果消退了！', `MaleText_loc5`='夢魘藥劑失去藥效了!', `MaleText_loc7`='¡El Elixir de pesadilla deja de surtir efecto!', `FemaleText_loc1`='악몽의 비약 효력이 떨어졌습니다!', `FemaleText_loc4`='噩梦药剂的效果消退了！', `FemaleText_loc5`='夢魘藥劑失去藥效了!', `FemaleText_loc7`='¡El Elixir de pesadilla deja de surtir efecto!' WHERE `ID`=49714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가여운 글럽톡. 자신의 힘에 눈을 떴을 때, 살던 집이 가장 먼저 불타고 말았지.', `FemaleText_loc4`='可怜的格拉布托克。他每次施法都会烧掉自己的住处。', `FemaleText_loc5`='可憐的格魯巴托克。當他的力量展現時，他的巨魔山是第一個遭殃的地方。', `FemaleText_loc7`='Pobre Glubtok. Cuando se manifestaron sus poderes, su túmulo ogro fue lo primero en arder.' WHERE `ID`=49715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼 깊숙이 그가 가장 두려워했던 건... 자기 자신이었어.', `FemaleText_loc4`='在他的灵魂深处，令他最为惧怕的就是……他自己。', `FemaleText_loc5`='在他靈魂的深處，他最害怕的東西就是...他自己。', `FemaleText_loc7`='En el fondo de su alma, lo único que temía más que ninguna otra cosa era... a sí mismo.' WHERE `ID`=49716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하는가, $r|1이여;여;? 지식? 돈? 명예?$B$B난 비전 마법에 대한 더 폭넓은 깨달음을 얻길 원한다네. 지식을 좇는 내 여정은 아제로스를 셀 수 없을 만큼 여행하게 했고, 난 그때마다 이 세상이 주는 마법에 대한 새로운 사실을 배울 수 있었지.$b$b사실 다 농담이야! 난 돈 때문에 왔네.', `MaleText_loc4`='你在找寻什么，$r？知识？金钱？还是荣耀？$b$b对我而言，我总是希望能够进一步洞悉奥法艺术的真义。我对知识的渴求，已驱使我无数次地环游艾泽拉斯，而每一次我都会对这个世界上所蕴藏的神秘魔法有新的了解。$b$b逗你玩呢！其实我就是为了钱。', `MaleText_loc5`='你的目的是什麼，$r?知識?財富?榮耀?$b$b對我來說，我的目的是為了要更進一步了解魔法技藝。我對知識的追求無數次地把我帶往艾澤拉斯各地，而且每次我都學習到關於這個世界所擁有的新魔法。$b$b我開玩笑的!我只是為了錢才這麼做。', `MaleText_loc7`='¿Qué es lo que buscas, $r? ¿Conocimiento? ¿Dinero? ¿Honor?$b$bEn mi caso, siempre se ha tratado de conseguir una mayor iluminación en las artes arcanas. Mi misión en busca del conocimiento me ha llevado por todo Azeroth infinidad de veces, y cada vez he aprendido algo nuevo sobre la magia que este mundo tiene para ofrecer.$b$b¡Solo bromeaba! ¡Estoy en esto por la pasta!' WHERE `ID`=49717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시덤불 골짜기를 떠날 준비가 되었는가?', `MaleText_loc4`='你准备好离开荆棘谷了吗？', `MaleText_loc5`='你準備好離開荊棘谷了嗎?', `MaleText_loc7`='¿Estás $glisto:lista; para abandonar Vega de Tuercespina?' WHERE `ID`=49718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 차원문을 열어 주십시오, 아르만 님.', `MaleText_loc4`='是的。请准备传送吧，艾尔曼。', `MaleText_loc5`='是的，請準備傳送門，阿爾曼。', `MaleText_loc7`='Sí. Por favor, prepara el portal, Arman.', `FemaleText_loc1`='네, 차원문을 열어 주세요, 아르만 님.', `FemaleText_loc4`='是的。请准备传送吧，艾尔曼。', `FemaleText_loc5`='是的，請準備傳送門，阿爾曼。', `FemaleText_loc7`='Sí. Por favor, prepara el portal, Arman.' WHERE `ID`=49719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 무법항에서 벌어졌던 기묘한 사건을 조사하라는 상관의 명령을 받고 이곳에 왔습니다. 이 고블린 마을은 대격변의 해일을 놀라울 정도로 잘 견뎌냈고, 특히 고블린 기계공학이 명성을 떨치는 데 큰 공헌을 했죠. 그때의 충격에 이곳이 폭발하지 않았다니 정말이지 놀랍습니다.$B$B제 추측으론 이곳에 마법의 힘이 숨겨져 있진 않을까 생각합니다만... 어쩌면 이곳은 단순한 무법항 이상의 장소일지도 모릅니다, $c님...', `MaleText_loc4`='我奉命前来调查藏宝海湾近来出现的怪事。这座地精之城出人意料地经受住了一场巨大海啸的考验，鉴于其以地精工程学而著称的美名，这就更加令人觉得不可思议。没想到这地方居然没有被巨浪冲垮。$b$b我怀疑在这里有什么魔法力量在作怪。你对藏宝海湾的了解也许远远不够，$c……', `MaleText_loc5`='我的上級派我來調查藏寶海灣這裡的一些怪現象。這個哥布林城鎮相當成功地應付了一次海嘯，特別是在哥布林工程學的名聲之下...我很驚訝這個地方沒有在受到衝擊的當下整個爆炸。$b$b我懷疑這裡有著魔法力量的存在。藏寶海灣可能比你想像的還要更複雜，$c...', `MaleText_loc7`='He sido enviado aquí por mis superiores para investigar los extraños acontecimientos que han ocurrido en Bahía del Botín. Esta ciudad goblin aguantó un maremoto bastante bien, sobre todo teniendo en cuenta la reputación de la ingeniería goblin. Me sorprende que ese sitio no saltara por los aires.$b$bSospecho que quizá haya en juego fuerzas mágicas. Puede que en Bahía del Botín pase algo más gordo de lo que crees, $c...' WHERE `ID`=49720;
