UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도적은 모름지기 어둠 속에 숨는다지만, 헬릭스는 달랐지.', `FemaleText_loc4`='许多盗贼喜欢把自己藏在阴影中，赫利克斯是个例外。', `FemaleText_loc5`='大部份的盜賊都喜歡在暗處活動，但赫利克斯卻不同。', `FemaleText_loc7`='La mayoría de los pícaros prefieren camuflarse en las sombras, pero Helix no.' WHERE `ID`=49723;
