UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박 폭탄을 사용해 여러 좀비를 한꺼번에 공격하거나 강력한 좀비의 체력을 약화하십시오.', `MaleText_loc4`='用南瓜炸弹击败大批僵尸或弱化更强大敌人的战斗力。', `MaleText_loc5`='使用南瓜炸彈來擊敗大群的殭屍或削弱較強的殭屍。', `MaleText_loc7`='Utiliza bombas de calabaza para derrotar a los grandes grupos de zombis o debilitar a los más duros.', `FemaleText_loc1`='호박 폭탄을 사용해 여러 좀비를 한꺼번에 공격하거나 강력한 좀비의 체력을 약화하십시오.', `FemaleText_loc4`='用南瓜炸弹击败大批僵尸或弱化更强大敌人的战斗力。', `FemaleText_loc5`='使用南瓜炸彈來擊敗大群的殭屍或削弱較強的殭屍。', `FemaleText_loc7`='Utiliza bombas de calabaza para derrotar a los grandes grupos de zombis o debilitar a los más duros.' WHERE `ID`=49747;
