UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙이 승리했습니다! 알렉스트라자가 회복되면 다시 한 번 도전하십시오.', `FemaleText_loc4`='死亡之翼胜利了！等阿莱克丝塔萨复原后再次尝试吧。', `FemaleText_loc5`='死亡之翼獲勝了!等雅立史卓莎恢復後再試一次。', `FemaleText_loc7`='¡Alamuerte ha vencido! Inténtalo de nuevo cuando Alexstrasza se recupere.' WHERE `ID`=49758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알렉스트라자 님이 전투를 벌이는 데 필요한 생명의 순환계가 아직 준비되지 않았습니다. 제가 준비를 끝내면 다시 말씀해 주십시오.', `FemaleText_loc4`='还没为阿莱克丝塔萨准备好生命循环。等我准备就绪后，再来和我交谈。', `FemaleText_loc5`='尚未幫雅立史卓莎準備好生命之環。等我完成準備工作後，盡快再跟我講一次話。', `FemaleText_loc7`='El Círculo de la Vida todavía no está listo para Alexstrasza. Habla conmigo de nuevo en cuanto haya terminado con las preparaciones.' WHERE `ID`=49759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알렉스트라자 님은 이미 데스윙과 전투를 벌이고 계십니다! 서두르면 아직 그분을 도울 수 있을지도 모릅니다!', `FemaleText_loc4`='阿莱克丝塔萨已经在和死亡之翼交战了！如果你动作够快，也许还来得及帮忙！', `FemaleText_loc5`='雅立史卓莎已經在和死亡之翼交戰!如果動作快，你或許還有幫忙的機會!', `FemaleText_loc7`='¡Alexstrasza ya está luchando contra Alamuerte! ¡Si te das prisa, quizá estés a tiempo para ser de ayuda!' WHERE `ID`=49760;
