UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 막아냈습니다!$B$B감독관이 이 소식을 들으면 좋아할 것 같진 않습니다...', `MaleText_loc4`='你成功抵御了敌人的攻势！$B机构主管会不开心的……', `MaleText_loc5`='你防住攻擊了!$B管理員會很不高興的...', `MaleText_loc7`='¡Te has defendido del ataque!$BEl celador no estará muy contento...', `FemaleText_loc1`='공격을 막아냈습니다!$B$B감독관이 이 소식을 들으면 좋아할 것 같진 않습니다...', `FemaleText_loc4`='你成功抵御了敌人的攻势！$B机构主管会不开心的……', `FemaleText_loc5`='你防住攻擊了!$B管理員會很不高興的...', `FemaleText_loc7`='¡Te has defendido del ataque!$BEl celador no estará muy contento...' WHERE `ID`=49772;
