UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 타락비룡을 처치해 알렉스트라자를 도우십시오.', `MaleText_loc4`='通过消灭暮光腐蚀者来帮助阿莱克丝塔萨。', `MaleText_loc5`='殺死暮光墮落者來協助雅立史卓莎。', `MaleText_loc7`='Ayuda a Alexstrasza matando corruptores Crepusculares.' WHERE `ID`=49774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승강기를 2층으로 보냅니다.', `MaleText_loc4`='将升降梯升至第二层。', `MaleText_loc5`='叫電梯到二樓。', `MaleText_loc7`='Lleva el elevador al segundo piso.', `FemaleText_loc1`='승강기를 2층으로 보냅니다.', `FemaleText_loc4`='将升降梯升至第二层。', `FemaleText_loc5`='叫電梯到二樓。', `FemaleText_loc7`='Lleva el elevador al segundo piso.' WHERE `ID`=49775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승강기를 3층으로 보냅니다.', `MaleText_loc4`='将升降梯升至第三层。', `MaleText_loc5`='叫電梯到三樓。', `MaleText_loc7`='Lleva el elevador al tercer piso.', `FemaleText_loc1`='승강기를 3층으로 보냅니다.', `FemaleText_loc4`='将升降梯升至第三层。', `FemaleText_loc5`='叫電梯到三樓。', `FemaleText_loc7`='Lleva el elevador al tercer piso.' WHERE `ID`=49776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승강기를 보낼 곳을 선택합니다.', `MaleText_loc4`='选择目的地。', `MaleText_loc5`='選擇目的地。', `MaleText_loc7`='Elige un destino.', `FemaleText_loc1`='승강기를 보낼 곳을 선택합니다.', `FemaleText_loc4`='选择目的地。', `FemaleText_loc5`='選擇目的地。', `FemaleText_loc7`='Elige un destino.' WHERE `ID`=49777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 층으로 승강기를 소환합니다.', `MaleText_loc4`='将升降梯召唤至当前层。', `MaleText_loc5`='召喚電梯到目前所在的樓層。', `MaleText_loc7`='Llama al elevador al piso en el que estás.', `FemaleText_loc1`='현재 층으로 승강기를 소환합니다.', `FemaleText_loc4`='将升降梯召唤至当前层。', `FemaleText_loc5`='召喚電梯到目前所在的樓層。', `FemaleText_loc7`='Llama al elevador al piso en el que estás.' WHERE `ID`=49778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알렉스트라자가 부상당했습니다. 황혼의 타락비룡을 처치해 붉은 광선을 유지하지 않으면 그녀가 질 것입니다!', `FemaleText_loc4`='阿莱克丝塔萨受伤了。消灭暮光腐蚀者以保持红色光束，否则她将落败！', `FemaleText_loc5`='雅立史卓莎受傷了。殺死暮光墮落者來讓光束保持紅色，不然她將落敗!', `FemaleText_loc7`='Alexstrasza está herida. ¡Mata corruptores Crepusculares para que los rayos sigan rojos o perderá la batalla!' WHERE `ID`=49779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 크라즈 대포에 올라타서 폭풍발톱을 쏴버리세요. 꾸물거렸다간 저놈들이 여길 산산이 무너뜨릴 겁니다!', `MaleText_loc4`='$n，去用卡拉兹加农炮把那些雷爪狮鹫打下来，别让它们把这地方毁掉！', `MaleText_loc5`='$n，快去找一口克拉茲火砲，在那些風暴利爪還沒拆爛這個地方之前把牠們打下來!', `MaleText_loc7`='¡$n, consigue uno de los cañones de Krazz y derriba a esos garfatormenta antes de que hagan que este lugar se derrumbe sobre nosotros!' WHERE `ID`=49780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기에 맞았다는 걸 깨달았을 때 놈들 표정이 어땠는지 못 봐서 섭섭하군요.', `MaleText_loc4`='我真想看看当他们意识到自己是被你用这些破烂打下来时，脸上有什么表情。', `MaleText_loc5`='我真想看看當他們知道我們是用垃圾把牠們射下來時臉上的表情。', `MaleText_loc7`='Ojala les hubiera visto la cara cuando se dieron cuenta de que les estabas disparando con nuestra basura.' WHERE `ID`=49781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곤란할 데가! 이러다간 내 용암 벌레가 정말 질 수도 있겠군! 그럼... 내가 상황을 좀 바꿔 볼까?', `MaleText_loc4`='难以置信，你们竟然真要击败我的熔岩巨虫了！也许我可以帮你们……扭转局势。', `MaleText_loc5`='真難想像!看來你真有機會打敗我的蟲子!也許我可幫忙...扭轉戰局。', `MaleText_loc7`='¡Inconcebible! ¡Es posible que venzan a mi gusano de lava! Quizás yo pueda... desequilibrar la balanza.' WHERE `ID`=49782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 여명회 형제들의 희생을 잊어서는 안 됩니다. 그들은 여명이 찾아올 것을 믿었습니다. 안타깝게도 이 땅에 빛이 돌아오는 모습을 볼 때까지 살아남은 사람은 없었지만...', `MaleText_loc4`='银色黎明同胞兄弟们的牺牲必须被永远铭记。他们信仰黎明，尽管没人能活着看到圣光重新照亮这片土地。', `MaleText_loc5`='我銀色黎明的兄弟們所做出的犧牲絕對不能被遺忘。他們相信銀色黎明，雖然他們沒辦法活著見到聖光回到這片大地。', `MaleText_loc7`='Los sacrificios de mis hermanos de El Alba Argenta nunca deben ser olvidados. Ellos creían en el Amanecer, aunque ninguno vivió para ver el regreso de la Luz a estas tierras.' WHERE `ID`=49783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염 분출 공격을 사용하여 적이 화염에 휩싸이게 하세요!', `MaleText_loc4`='用烈焰喷射来让敌人葬身火海！', `MaleText_loc5`='使用烈焰噴洩攻擊使敵人被烈焰包圍!', `MaleText_loc7`='¡Utiliza el ataque Caño de llamas para que las llamas devoren al enemigo!', `FemaleText_loc1`='화염 분출 공격을 사용하여 적이 화염에 휩싸이게 하세요!', `FemaleText_loc4`='用烈焰喷射来让敌人葬身火海！', `FemaleText_loc5`='使用烈焰噴洩攻擊使敵人被烈焰包圍!', `FemaleText_loc7`='¡Utiliza el ataque Caño de llamas para que las llamas devoren al enemigo!' WHERE `ID`=49784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 그만 사라져라!', `FemaleText_loc4`='你的生命终结了！', `FemaleText_loc5`='你生命在此結束!', `FemaleText_loc7`='¡Ha llegado tu fin!' WHERE `ID`=49785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='합당한 대가를 치르면 빛이 언제나 당신을 지켜줄 거예요, $c님.', `MaleText_loc4`='只要你出得起钱，圣光就能永远保护你，$c。', `MaleText_loc5`='如果你付出足夠的代價，聖光會一直保護你的，$c。', `MaleText_loc7`='Si pagas el precio justo, la Luz siempre podrá protegerte, $c.', `FemaleText_loc1`='합당한 대가를 치르면 빛이 언제나 당신을 지켜줄 거예요, $c님.', `FemaleText_loc4`='只要你出得起钱，圣光就能永远保护你，$c。', `FemaleText_loc5`='如果你付出足夠的代價，聖光會一直保護你的，$c。', `FemaleText_loc7`='Si pagas el precio justo, la Luz siempre podrá protegerte, $c.' WHERE `ID`=49786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신한테 돈만 있으면 분명히 빛이 가르쳐줄 게 있을 거라고요.', `MaleText_loc4`='如果你口袋里有钱，我相信圣光一定能传授给你些什么。', `MaleText_loc5`='如果你有錢，我很確信聖光有東西可以教你。', `MaleText_loc7`='Si tienes el dinero, estoy seguro de que la Luz podrá enseñarte algo.', `FemaleText_loc1`='당신한테 돈만 있으면 분명히 빛이 가르쳐줄 게 있을 거라고요.', `FemaleText_loc4`='如果你口袋里有钱，我相信圣光一定能传授给你些什么。', `FemaleText_loc5`='如果你有錢，我很確信聖光有東西可以教你。', `FemaleText_loc7`='Si tienes el dinero, estoy segura de que la Luz podrá enseñarte algo.' WHERE `ID`=49787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오, $g형제:자매;님. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B우리는 영원한 균형의 수호자이며 말퓨리온 님이 우리를 지켜주십니다. 이 사실을 절대 잊지 마십시오.', `MaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，我将非常愿意将本领传授与你。$B$B在玛法里奥的注视下，我们现在和将来都会是平衡的保持者。永远牢记这一点。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B瑪法里恩在照看著我們，所以我們永遠是平衡的守衛者。別忘了這一點。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, y Malfurion vela por nosotros. Nunca lo olvides.', `FemaleText_loc1`='어서 오십시오, $g형제:자매;님. 이곳에 훈련을 받으러 온 것이라면 제가 기꺼이 가르쳐 드리겠습니다.$B$B우리는 영원한 균형의 수호자이며 말퓨리온 님이 우리를 지켜주십니다. 이 사실을 절대 잊지 마십시오.', `FemaleText_loc4`='欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，我将非常愿意将本领传授与你。$B$B在玛法里奥的注视下，我们现在和将来都会是平衡的保持者。永远牢记这一点。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B瑪法里恩在照看著我們，所以我們永遠是平衡的守衛者。別忘了這一點。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.$B$BSomos los protectores del equilibrio, ahora y siempre, y Malfurion vela por nosotros. Nunca lo olvides.' WHERE `ID`=49788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 우리의 지도자이신 말퓨리온 님께서 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', `MaleText_loc4`='我们的主人玛法里奥已从梦境中返回，$c。他是指引我们前进方向的灯塔之光，我们必须竭尽全力保护这道光芒。', `MaleText_loc5`='我們的主人瑪法里恩從夢境中歸來了，$c。他是替我們指引道路的光明燈塔，而我們必須盡一切所能來維持這盞光明。', `MaleText_loc7`='Nuestro maestro Malfurion ha regresado del Sueño, $c. Él es la luz del faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.', `FemaleText_loc1`='$c님, 우리의 지도자이신 말퓨리온 님께서 에메랄드의 꿈속에서 돌아오셨습니다. 그분은 우리의 길을 비추는 빛이십니다. 우리는 그 빛을 지키도록 온 힘을 다해야 합니다.', `FemaleText_loc4`='我们的主人玛法里奥已从梦境中返回，$c。他是指引我们前进方向的灯塔之光，我们必须竭尽全力保护这道光芒。', `FemaleText_loc5`='我們的主人瑪法里恩從夢境中歸來了，$c。他是替我們指引道路的光明燈塔，而我們必須盡一切所能來維持這盞光明。', `FemaleText_loc7`='Nuestro maestro Malfurion ha regresado del Sueño, $c. Él es la luz del faro que ilumina nuestro camino, y debemos hacer todo lo que sea posible para conservar esa luz.' WHERE `ID`=49789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 인정하죠. 당신들 덕분에 여기까지 온 겁니다.', `MaleText_loc4`='我得承认，没有你的帮助，我根本没法做到。', `MaleText_loc5`='我得承認，沒有你幫忙是不會成功的。', `MaleText_loc7`='Ah, admito que no habría podido hacerlo sin su ayuda.' WHERE `ID`=49790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 다 잘될 겁니다!', `MaleText_loc4`='好了。这应该能行！', `MaleText_loc5`='好了。這樣就可以了!', `MaleText_loc7`='¡Listo! ¡Debería funcionar!' WHERE `ID`=49791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자료 확인... 대기 중입니다.', `MaleText_loc4`='数据访问中……请稍候。', `MaleText_loc5`='存取資料...待命中。', `MaleText_loc7`='Accediendo a los datos... espere.' WHERE `ID`=49792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW.BLP:20|t%s|1이;가; 가마솥에 |cFF660099암흑|r 마법을 사용합니다!', `MaleText_loc4`='|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW.BLP:20|t%s朝锅里施放了|cFF660099黑暗|r魔法！', `MaleText_loc5`='|TInterface\\Icons\\INV_ELEMENTAL_PRIMAL_SHADOW.BLP:20|t%s丟了|cFF660099黑暗|r魔法到熔爐中!', `MaleText_loc7`='|TInterfaceIconsINV_ELEMENTAL_PRIMAL_SHADOW.BLP:20|t¡%s lanza magia |cFF660099oscura|r en el caldero!' WHERE `ID`=49793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시초 재개 장치 접근 권한을 재정의합니다.', `MaleText_loc4`='正在访问起源重组装置撤销系统。', `MaleText_loc5`='存取重組裝置覆蓋。', `MaleText_loc7`='Accediendo al control manual para reoriginación.' WHERE `ID`=49794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 얼른 원반 처리하고 접근 권한을 내놔라!', `MaleText_loc4`='好了，好了。快读取这圆盘，给我访问权限……', `MaleText_loc5`='好啦好啦。趕快讀完讓我能存取就對了...', `MaleText_loc7`='Sí, sí. Lee los discos y dame acceso de una vez...' WHERE `ID`=49795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정보 저장소 접근이 거부되었습니다. 시초 재개를 시작합니다.', `MaleText_loc4`='资料库访问拒绝。起源重组子程序已启动。', `MaleText_loc5`='寶庫存取拒絕連線。重組子程式啟動中。', `MaleText_loc7`='Acceso a la base de datos denegado. Subrutina de reoriginación iniciada.' WHERE `ID`=49796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 어어... 이거 곤란한데! 이거 정말 곤란하군...', `MaleText_loc4`='什么？！什么！这可不好！这可一点儿都不好……', `MaleText_loc5`='什麼?等等!噢這看起來不妙!非常的不妙...', `MaleText_loc7`='¿¡Qué!? ¡Esperen! ¡Eso es malol! ¡Es muy malo!' WHERE `ID`=49797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고!$b시초 재개 장치가 활성화되었습니다. 1분 후에 폭발합니다.', `MaleText_loc4`='警告！$b起源重组装置已激活。一分钟后爆炸。', `MaleText_loc5`='警告。重組裝置已啟動。一分鐘後進行引爆。', `MaleText_loc7`='Alerta. Dispositivo de reoriginación activado. Detonación en un minuto.' WHERE `ID`=49798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에, 1분이라고?! 자자자자, 브란! 생각해!', `MaleText_loc4`='一分钟？！快点，布莱恩！快想！', `MaleText_loc5`='一分鐘!?天啊，布萊恩!快思考!', `MaleText_loc7`='¡¿Un minuto?! ¡Vamos, Brann! ¡Piensa!' WHERE `ID`=49799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수동으로 조작해야겠습니다! 방법이 있을 거예요!', `MaleText_loc4`='我要靠手动拆开它！一定有办法的！', `MaleText_loc5`='我要用手動處理!一定有辦法的!', `MaleText_loc7`='¡Lo haré manualmente! ¡Tiene que haber una forma!' WHERE `ID`=49800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후에 폭발합니다.', `MaleText_loc4`='30秒后爆炸。', `MaleText_loc5`='三十秒後進行引爆。', `MaleText_loc7`='Detonación en treinta segundos.' WHERE `ID`=49801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 도화선이 보이는군요! 그런데 어느 걸 끊어야 하나? 어... 빨강? 파랑?', `MaleText_loc4`='好了！看到导爆线了！该切断哪根呢？红色？还是蓝色……？', `MaleText_loc5`='好啦!管線都在這了!我們要破壞哪一個?呃...紅色?還是藍色...?', `MaleText_loc7`='¡Bien! ¡Fusibles a la vista! ¿Ahora cuál hay que romper? ¿El rojo? ¿El azul...?' WHERE `ID`=49802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이구, 이거 정말 미치겠네!', `MaleText_loc4`='哎呀！我没法决定！', `MaleText_loc5`='唉呀!我決定不了!', `MaleText_loc7`='¡Ay! ¡No me decido!' WHERE `ID`=49803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 괴물들아! 우리가 널 짓밟아 주마!', `MaleText_loc4`='来吧，怪物们！我们将把你们粉碎！', `MaleText_loc5`='快點，怪物!我們會毀滅你們!', `MaleText_loc7`='¡Venga, monstruos! ¡Los aplastaremos!' WHERE `ID`=49804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요! 밑져야 본전이죠!', `MaleText_loc4`='好吧，只能这样了！', `MaleText_loc5`='好啦，死就死吧!', `MaleText_loc7`='¡Bueno, habrá que probar!' WHERE `ID`=49805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 네 녀석들만으로는 충분하지 않을 거다!', `MaleText_loc4`='你们这群臭狗完全不顶用！', `MaleText_loc5`='只有你們這些臭狗是不夠的!', `MaleText_loc7`='¡Tus apestosos perros no son suficientes!' WHERE `ID`=49806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 전투늑대들은 백 마리라도 더 없애주지!', `MaleText_loc4`='我要再消灭100只像你们这样的军用座狼！', `MaleText_loc5`='我會多殺死一百隻你們的作戰座狼!', `MaleText_loc7`='¡Mataré a cien más de tu huargos de batalla!' WHERE `ID`=49807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 늑대 따위는 스톰윈드의 힘에는 상대조차 되지 않는다!', `MaleText_loc4`='你们这群座狼在暴风城的力量面前简直就是渣！', `MaleText_loc5`='你們的座狼對上暴風城的力量根本是以卵擊石!', `MaleText_loc7`='¡Tus huargos no tienen nada que hacer contra el poder de Ventormenta!' WHERE `ID`=49808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원기 왕성해 보이는군, 친구들! 사방에 오크들과 늑대들이 있네!', `MaleText_loc4`='注意了弟兄们！周围到处都是兽人和座狼！', `MaleText_loc5`='大家有精神點!附近有獸人和座狼呢!', `MaleText_loc7`='¡Dense prisa, muchachos! ¡Hay orcos y huargos por todas partes!' WHERE `ID`=49809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 주위를 뛰어다니며 기대에 찬 눈빛으로 당신을 올려다봅니다. 당신을 기억하고 있는 게 틀림없습니다.', `MaleText_loc4`='佩波跳来跳去，充满希望地抬头望着你。他显然记得你是谁。', `MaleText_loc5`='小石岩跳來跳去並充滿希望地看著你。他顯然記得你。', `MaleText_loc7`='Guijarro da saltos a tu alrededor y te mira esperanzado. Está claro que se acuerda de ti.' WHERE `ID`=49810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 꼬마 친구! 여기서 나가자고.', `MaleText_loc4`='来吧小家伙，让我们离开这儿。', `MaleText_loc5`='來吧小傢伙，咱們離開這個地方。', `MaleText_loc7`='Venga, pequeño, salgamos de aquí.', `FemaleText_loc1`='안녕, 꼬마 친구! 여기서 나가자고.', `FemaleText_loc4`='来吧小家伙，让我们离开这儿。', `FemaleText_loc5`='來吧小傢伙，咱們離開這個地方。', `FemaleText_loc7`='Venga, pequeño, salgamos de aquí.' WHERE `ID`=49811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 돌 소리를 내며 고분고분 당신 옆으로 와 섭니다.', `MaleText_loc4`='佩波跳动着顺从地跟在你身边。', `MaleText_loc5`='小石岩的石塊緊張地抖動著，服從的跟在你旁邊。', `MaleText_loc7`='Las piedras de Guijarro dan saltitos mientras te sigue obedientemente.' WHERE `ID`=49812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 깡충깡충 행복하게 뛰며 저 멀리로 사라집니다.', `MaleText_loc4`='佩波欢快地上下弹跳着，消失在远方。', `MaleText_loc5`='小石岩開心地上下跳躍著，慢慢地消失在遠方。', `MaleText_loc7`='Guijarro da saltos feliz mientras desaparece en la distancia.' WHERE `ID`=49813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 이리저리 행복하게 돌아다니더니 저 멀리로 사라집니다.', `MaleText_loc4`='佩波欢快地四下跳跃着，消失在远方。', `MaleText_loc5`='小石岩開心地走來走去，然後消失在遠方。', `MaleText_loc7`='Guijarro da vueltas feliz y desaparece en la distancia.' WHERE `ID`=49814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 당신의 다리 주위를 행복하게 왔다 갔다 하더니 저 멀리로 뛰어갑니다.', `MaleText_loc4`='佩波欢快地在你腿边跳上跳下，然后飞也似地消失在远方。', `MaleText_loc5`='小石岩開心地磨蹭你的大腿，然後跑向遠方消失了。', `MaleText_loc7`='Guijarro se arrima feliz a tu pierna y después corre hasta perderse en la distancia.' WHERE `ID`=49815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌돌이가 고맙다는 듯 주위를 통통 뛰더니 저 멀리로 사라집니다.', `MaleText_loc4`='佩波充满感激地跃动着，然后消失在远方。', `MaleText_loc5`='小石岩感激地跳來跳去，然後消失在遠方。', `MaleText_loc7`='Guijarro salta a tu alrededor agradecido y desparece en la distancia.' WHERE `ID`=49816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 지금껏 해준 일을 생각해서... 이걸로 합시다!', `MaleText_loc4`='鉴于你们所做的一切，不如我们切断……', `MaleText_loc5`='不然這樣，為了感謝你做的一切，我們選...', `MaleText_loc7`='Qué tal si, en consideración a todo lo que han hecho, elegimos...' WHERE `ID`=49817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨강! 호드를 위하여!', `MaleText_loc4`='红色！为了部落！', `MaleText_loc5`='紅色!為了部落!', `MaleText_loc7`='¡EL ROJO! ¡Por la HORDA!' WHERE `ID`=49818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파랑! 얼라이언스를 위하여!', `MaleText_loc4`='蓝色！为了联盟！', `MaleText_loc5`='藍色!為了聯盟!', `MaleText_loc7`='¡El azul! ¡Por la Alianza!' WHERE `ID`=49819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시초 재개 장치 폭발이 중단되었습니다.', `MaleText_loc4`='起源重组装置爆炸进程已中断。', `MaleText_loc5`='重組裝置引爆程序已終止。', `MaleText_loc7`='Detonación del dispositivo de reoriginación abortada.' WHERE `ID`=49820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 빠져나가는 일은 생각보다 훨씬 어렵군.$B$B눈에 보이는 거라곤 하늘뿐인 여기서 대체 어디로 갈 수 있겠소?', `MaleText_loc4`='从这地方逃离比我预想中还要难。$B$B当视野之中看不到出路时，你该往哪里走？', `MaleText_loc5`='逃離這個地方比我想像中困難。$B$B如果舉目所及沒有路可以走，你能往哪去?', `MaleText_loc7`='Escapar de este lugar es mucho más difícil de lo que había imaginado.$B$B¿Adónde puedes ir cuando no hay ningún lugar al que ir a la vista?' WHERE `ID`=49821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호!', `MaleText_loc4`='哇呼——！', `MaleText_loc5`='哇呼!', `MaleText_loc7`='¡Yaaajuuu!' WHERE `ID`=49822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 아제로스를 또 지켜내는군요!', `MaleText_loc4`='艾泽拉斯又逃过了一劫！', `MaleText_loc5`='艾澤拉斯又平安度過一天!', `MaleText_loc7`='¡Azeroth vive para ver un nuevo día!' WHERE `ID`=49823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 아직도 수만 명이 탈출 장치 안에 갇혀 있다고. 이봐 윗분, 아 잠깐만. 이제는 윗분이 아니지. 어쨌든, 자네가 구해주지 않으면 모두 물에 빠져 죽고 만다고.', `MaleText_loc4`='对，有无数人还被困在逃生舱里，老大。喔，等一下。我想你已经不再是老大了。不管怎么说，如果你不赶快把他们放出来，他们都要变成水鬼了。', `MaleText_loc5`='是的，還有一堆人困在逃生艙裡，老闆。噢，等等。我想你已經不是老闆了。不管如何，如果你不把他們弄出來，他們全都會淹死在裡面的。', `MaleText_loc7`='Sí, hay toneladas de gente atrapada en las cápsulas de escape, pez gordo. Oh, espera. Supongo que ya no eres el pez gordo por aquí. De todas maneras, se ahogarán todos si no los sacas del agua.' WHERE `ID`=49824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 저는 당신을 도울 수 없습니다.', `MaleText_loc4`='我帮不了你，$c。', `MaleText_loc5`='我沒辦法幫你，$c。', `MaleText_loc7`='No puedo ayudarte, $c.', `FemaleText_loc1`='$c님, 저는 당신을 도울 수 없습니다.', `FemaleText_loc4`='我帮不了你，$c。', `FemaleText_loc5`='我沒辦法幫你，$c。', `FemaleText_loc7`='No puedo ayudarte, $c.' WHERE `ID`=49825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우아한 움직임이군요. 어떻게 도와드리면 좋겠습니까?', `MaleText_loc4`='你优雅地轻移着步伐，潜行者。我能帮你什么忙吗？', `MaleText_loc5`='你的動作優雅，盜賊。我能幫你什麼?', `MaleText_loc7`='Te mueves con agilidad, $gpícaro:pícara;. ¿Cómo puedo ayudarte?', `FemaleText_loc1`='우아한 움직임이군요. 어떻게 도와드릴까요?', `FemaleText_loc4`='你优雅地轻移着步伐，潜行者。我能帮你什么忙吗？', `FemaleText_loc5`='你的動作優雅，盜賊。我能幫你什麼?', `FemaleText_loc7`='Te mueves con agilidad, $gpícaro:pícara;. ¿Cómo puedo ayudarte?' WHERE `ID`=49826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 이 외딴 섬에서 살아남으려면 우리 폭탄이랑 연장이 몽땅 필요하다고요.', `FemaleText_loc4`='我们得用上所有炸弹和工具，才能在这荒岛上活下去，$n。', `FemaleText_loc5`='我們需要現有的所有炸彈和工具才有辦法在這荒蕪的島上存活下來，$n。', `FemaleText_loc7`='Necesitamos todas nuestras bombas y herramientas para sobrevivir en esta isla desierta, $n.' WHERE `ID`=49827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 저 거대랩터 새끼가 우리에게 무슨 해코지라도 하기 전에 처리하라고!', `MaleText_loc4`='$n，你必须在那些刺角雏龙逮到我们之前，把它们解决掉！', `MaleText_loc5`='$n，你得在那些小迅猛龍搞死我們之前先搞死牠們!', `MaleText_loc7`='¡$n, tienes que conseguir esas proles de teraptor antes de que nos pillen!' WHERE `ID`=49828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 절벽에서 어미가 울부짖는 소리 들었어? 근처에도 가지 말라고!', `MaleText_loc4`='你听到龙母在峭壁上的咆哮声没有？绕开她！', `MaleText_loc5`='你有聽見族母在峭壁上低吼的聲音嗎?離她遠一點!', `MaleText_loc7`='¿Has oído a la matriarca rugir desde lo alto del acantilado? ¡Aléjate de ella!' WHERE `ID`=49829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이들은 그 바나나를 엄청나게 좋아할 거야!', `MaleText_loc4`='那些香蕉一定会让猴子们乐翻天的！', `MaleText_loc5`='那些猴子會為那些香蕉而興奮不已的!', `MaleText_loc7`='¡Esos monos van a disfrutar mucho de esos plátanos!' WHERE `ID`=49830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여태 살면서 본 중에 최고로 멋진 광경이었어!', `MaleText_loc4`='那是我一生中所见过最美的东西了！', `MaleText_loc5`='那是我所見過最美的東西!', `MaleText_loc7`='¡Eso ha sido la cosa más hermosa que he visto nunca!' WHERE `ID`=49831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='댐윅은 바로 남동쪽에 있는 동굴 입구에서 만날 수 있어요.', `FemaleText_loc4`='戴姆维克就在东南方的洞穴入口处。', `FemaleText_loc5`='唐威克就在東南方的洞穴入口那。', `FemaleText_loc7`='Mechamojada esté en la entrada de la cueva, al sureste.' WHERE `ID`=49832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자마이트는 사라지고 원숭이 놈들은 영리해지다니! $n, 광부를 안전하게 보호해줘.', `MaleText_loc4`='卡亚矿石没了，这些猴子也因为矿石而变聪明了！保护好那个矿工，$n。', `MaleText_loc5`='卡迦邁讓那些猴子變聰明了!保護那個礦工的安全，$n。', `MaleText_loc7`='¡La kaja''mita ha vuelto inteligentes a los monos! Protege a los mineros, $n.' WHERE `ID`=49833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌지워터 무역회사를 대신하여, 이 광산은 내 소유임을 선포한다!', `MaleText_loc4`='以锈水财阀的名义，这里的矿是我的！', `MaleText_loc5`='我代表污水企業聯合宣告這個礦坑的所有權!', `MaleText_loc7`='En nombre del Cártel Pantoque, ¡reclamo esta mina para mí!' WHERE `ID`=49834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 모든 상황을 헤치고 살아남으려면 새 친구가 좀 필요해요. 오크들이 당신을 보자마자 바로 처치해버리지 않기만을 바라요.', `FemaleText_loc4`='我们要想保住性命，就需要结交一些新朋友。希望那些兽人不会一见面就把你干掉。', `FemaleText_loc5`='我們如果想生存下來就必須交些新的朋友。希望那些獸人不會看到你就把你給殺了。', `FemaleText_loc7`='Necesitamos algunos amigos si queremos sobrevivir a todo esto. Con suerte, los orcos no te matarán en cuanto te vean.' WHERE `ID`=49835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 일해서 무척 즐거웠습니다, 젊은 양반.$b$b언젠가 또 같이 일하게 된다면 영광이겠습니다.', `MaleText_loc4`='和你合作感觉很愉快，$g小伙子:小姑娘;。$b$b希望今后能与你再次携手。', `MaleText_loc5`='跟你一起行動非常愉快，$g小伙子:小姑娘;。$b$b希望有機會還能再一起合作。', `MaleText_loc7`='Ha sido todo un placer trabajar contigo, $gmuchacho:muchacha;.$b$bSerá un honor hacerlo de nuevo en otra ocasión.' WHERE `ID`=49836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 제값을 받기 위해 누구든 없앨 거다!', `MaleText_loc4`='只要酬劳高，我们能干掉任何人！', `MaleText_loc5`='只要價錢對了，我們可以殺死任何人!', `MaleText_loc7`='¡Por un precio justo mataremos a quien sea!', `FemaleText_loc1`='우린 제값을 받기 위해 누구든 없앨 거다!', `FemaleText_loc4`='只要酬劳高，我们能干掉任何人！', `FemaleText_loc5`='只要價錢對了，我們可以殺死任何人!', `FemaleText_loc7`='¡Por un precio justo mataremos a quien sea!' WHERE `ID`=49837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 친구와 만날 시간이다, 더러운 녀석!', `MaleText_loc4`='该加入你的朋友们了，亲吻泥土吧！', `MaleText_loc5`='是時候加入你的朋友了，親地板吧你!', `MaleText_loc7`='¡Hora de que te unas a tus amigos y beses el suelo!', `FemaleText_loc1`='네 친구와 만날 시간이다, 더러운 녀석!', `FemaleText_loc4`='该加入你的朋友们了，亲吻泥土吧！', `FemaleText_loc5`='是時候加入你的朋友了，親地板吧你!', `FemaleText_loc7`='¡Hora de que te unas a tus amigos y beses el suelo!' WHERE `ID`=49838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!!!', `MaleText_loc4`='死吧！！！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡¡¡MUERE!!!', `FemaleText_loc1`='죽어라!!!', `FemaleText_loc4`='死吧！！！', `FemaleText_loc5`='死吧!', `FemaleText_loc7`='¡¡¡MUERE!!!' WHERE `ID`=49839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이곳을 완전히 태워버릴 작정이다!', `MaleText_loc4`='我们要把这地方焚毁殆尽！', `MaleText_loc5`='我們會把這個地方焚燒殆盡!', `MaleText_loc7`='¡Vamos a quemar este lugar hasta que no queden más que cenizas!', `FemaleText_loc1`='우린 이곳을 완전히 태워버릴 작정이다!', `FemaleText_loc4`='我们要把这地方焚毁殆尽！', `FemaleText_loc5`='我們會把這個地方焚燒殆盡!', `FemaleText_loc7`='¡Vamos a quemar este lugar hasta que no queden más que cenizas!' WHERE `ID`=49840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 장난감 총 같은 놈은 정말 지긋지긋하군. 여기에 쏘게 해주마!', `MaleText_loc4`='受够你这些豌豆射手了。让它们往这儿打！', `MaleText_loc5`='你們這些只會射豆子的討厭傢伙。來射這個看看啊!', `MaleText_loc7`='Ya vale con tus pesados tiradores y sus pistolas de juguete. ¡Que disparen a esto a ver qué pasa!', `FemaleText_loc1`='그 장난감 총 같은 놈은 정말 지긋지긋하군. 여기에 쏘게 해주마!', `FemaleText_loc4`='受够你这些豌豆射手了。让它们往这儿打！', `FemaleText_loc5`='你們這些只會射豆子的討厭傢伙。來射這個看看啊!', `FemaleText_loc7`='Ya vale con tus pesados tiradores y sus pistolas de juguete. ¡Que disparen a esto a ver qué pasa!' WHERE `ID`=49841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심원의 영지는 요 몇 년 사이에 엄청나게 바뀌었습니다. 알아보기가 힘들 정도로 말이죠.$B$B하지만... 지금의 전 타락으로부터 자유롭답니다. 고대 신들이 드리웠던 타락의 그늘을 벗어났지요. 자유의 진정한 가치를 알려면, 가끔 자유를 빼앗겨 봐야 한다는 말이 맞는 것 같습니다.', `FemaleText_loc4`='深岩之洲近年来改变了许多。都快认不出来了。$B$B但是……我并没有被腐化。并没有受到远古之神的影响。看来有时只有在自由被剥夺的情况下，人们才能真正意识到它的珍贵。', `FemaleText_loc5`='地深之源在這幾年中改變很大，都已經快認不出來了。$B$B但是我...已經掙脫了腐化，已經掙脫了先祖眾神的污染和影響。看來有的時候你必須喪失了自由後才能瞭解它的可貴。', `FemaleText_loc7`='Infralar ha cambiado mucho en los años recientes. Apenas lo reconozco.$B$BSin embargo... aquí estoy, libre de la corrupción. Libre de la contaminante influencia de los dioses antiguos. Al parecer, a veces es necesario que te quiten la libertad para saber apreciarla en lo que vale.' WHERE `ID`=49842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고블린이여, 킬라그 고어팽은 서쪽 길 아래에 있을 거예요.', `FemaleText_loc4`='基拉格·血牙应该就在通向西边的路上，地精。', `FemaleText_loc5`='沿著這條路一直往西走應該就可以找到奇拉格·血牙了，哥布林。', `FemaleText_loc7`='Kilag Mandisangre debería estar en el sendero que va al oeste, goblin.' WHERE `ID`=49843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 솟구치는 불꽃을 시전합니다!', `MaleText_loc4`='%s开始施放烈焰升腾！', `MaleText_loc5`='%s開始施放烈焰高漲!', `MaleText_loc7`='¡%s empieza a lanzar Llamas crecientes!' WHERE `ID`=49844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 당신을 압니다. 그 오랜 시간 동안 저를 잠식해 오던 깊은 타락에 물들지 않도록 도와줘서 고맙습니다.$B$B내 고향 심원의 영지에 온 걸 환영합니다. 예전의 모습이라곤 거의 찾아볼 수 없지만, 이곳에서 전 자유로울 수 있습니다. 우리가 겪어야 했던 걸 생각하면 이제 다시는 자유를 당연한 것으로 여기지 않을 겁니다.$B$B당신이 왜 여기 있는진 모르겠습니다만, 이곳의 바위 벽 안에서 부디 원하는 걸 찾으시길 바랍니다. 몸 조심하십시오, $r|1이여;여;.', `FemaleText_loc4`='我认识你。我要感谢你。如果不是你，我可能还会深陷在已经将我吞噬无数个岁月的腐蚀力量中。$B$B欢迎来到我的家，深岩之洲。与曾经的深岩之洲相比，这里大概只能算是一个影子。但我现在是自由的。承受过那么多磨难之后，我已经深深地明白，自由是多么可贵。$B$B不知道你为什么会到这里来，但我希望你能在这高大的石墙中找到你所需要的一切。祝你平安，$n。', `FemaleText_loc5`='我認得你。我要謝謝你在腐化侵蝕了我那麼多年後幫助我重新獲得自由。$B$B歡迎來到我的家鄉:地深之源。現在的它就像是它原來的影子，但我在這是自由的。在我們經歷過之前的種種後，沒有人會再把現在的自由當成理所當然。$B$B我不知道你在這的原因是什麼，但我希望你能在這片石之壁中找到你想要的。祝你平安，$n。', `FemaleText_loc7`='Te conozco. Debo agradecerte a ti que me vea libre de la profunda corrupción que me consumió durante tantos años.$B$BTe doy la bienvenida a mi hogar. Infralar. Apenas es la sombra de lo que fue, pero aún y todo, aquí puedo ser libre. Después de lo que hemos tenido que sufrir, ya nunca menospreciaremos la libertad.$B$BNo sé por qué estás aquí, pero espero que encuentres lo que buscas dentro de los muros de roca de este lugar. Ten cuidado, $n.' WHERE `ID`=49845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 고블린이여, 그 잡초 제거기로 이 식물 좀 처리하게!', `MaleText_loc4`='用你的杂草清理者割倒这些植物，小地精！', `MaleText_loc5`='用你的割草機除掉那些植物，哥布林小子!', `MaleText_loc7`='¡Utiliza tu segador de malas hierbas para acabar con esas plantas, goblin!' WHERE `ID`=49846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 굴착기엔 녹이 좀 슬었지만, 아직 쓸만해 보입니다.', `MaleText_loc4`='这台挖掘机有些生锈了，可看起来还能使用。', `MaleText_loc5`='這個鑽地機有點生鏽了，不過看起來還能運作。', `MaleText_loc7`='Esta máquina topo está un poco oxidada pero parece que sigue operativa.' WHERE `ID`=49847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"험상궂은 주정뱅이 선술집 바로 너머"라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下带有“经过黑铁酒吧”标签的按钮。', `MaleText_loc5`='按下標註『黑鐵酒吧後面』的按鈕。', `MaleText_loc7`='Aprieta el botón señalado como "Pasa al Tragapenas".', `FemaleText_loc1`='"험상궂은 주정뱅이 선술집 바로 너머"라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下带有“经过黑铁酒吧”标签的按钮。', `FemaleText_loc5`='按下標註『黑鐵酒吧後面』的按鈕。', `FemaleText_loc7`='Aprieta el botón señalado como "Pasa al Tragapenas".' WHERE `ID`=49848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''거주지 안쪽''이라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下带有“进入住宅区”标签的按钮。', `MaleText_loc5`='按下標註『進入住宅區』的按鈕。', `MaleText_loc7`='Aprieta el botón señalado como "Al domicilio".', `FemaleText_loc1`='''거주지 안쪽''이라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下带有“进入住宅区”标签的按钮。', `FemaleText_loc5`='按下標註『進入住宅區』的按鈕。', `FemaleText_loc7`='Aprieta el botón señalado como "Al domicilio".' WHERE `ID`=49849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''입구''라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下带有“入口”标签的按钮。', `MaleText_loc5`='按下標註『入口』的按鈕。', `MaleText_loc7`='Aprieta el botón señalado como "Entrada".', `FemaleText_loc1`='''입구''라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下带有“入口”标签的按钮。', `FemaleText_loc5`='按下標註『入口』的按鈕。', `FemaleText_loc7`='Aprieta el botón señalado como "Entrada".' WHERE `ID`=49850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 주목. 내가 여기 있는 누구보다도 훨씬 더 부자라는 사실에 심심한 사의를 표하는 바야. 자네들이 일을 계속할 방법을 찾길 진심으로 바라.', `MaleText_loc4`='注意了。所有人注意了。我要向大家致以最诚挚的歉意——很抱歉，我所拥有的财富是你们所有人都比不了的。我真心希望你们能找到致富的通途。', `MaleText_loc5`='注意，注意，所有人注意。我想要誠心誠意地道歉，因為我比你們都有錢。我真的希望你們能找到理由活下去。', `MaleText_loc7`='Atención. Atención, todos. Me gustaría ofrecerlos mis más sinceras disculpas por ser mucho más rico que todos ustedes. Sinceramente espero que encuentren la manera de seguir así.' WHERE `ID`=49851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 자네들 모두 죽었다 깨나도 나처럼 부를 쌓을 수 없다는 걸 알고 살아가는 게 좋을 거야. 일을 계속하는 자네들이 아주 자랑스러워.', `MaleText_loc4`='你们真不简单。明知道永远不可能拥有与我等同的财富，却还能勇敢地继续自己的人生，这真是太难得了。我为你们坚持不懈的精神而感到骄傲。', `MaleText_loc5`='很好。你們能在知道永遠無法賺得比我多的情況下活下去。我對你們堅持下去的信念感到驕傲。', `MaleText_loc7`='Me alegro. Me alegro por todos ustedes que puedan seguir adelante con sus vidas sabiendo que nunca tendrán la riqueza que tengo yo. Estoy orgulloso de que lo soporten.' WHERE `ID`=49852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은...돈이 너무 많다는 게 상처가 되기도 해. 너무 외롭지. 내 옆에 있는 건 돈뿐이거든.', `MaleText_loc4`='有时候……有时候抱着这么多钱也不是什么好事儿。这感觉太孤单了。我穷得就只剩下钱。', `MaleText_loc5`='有時候...有時候我覺得擁有那麼多錢很痛苦。我窮得只剩錢了。', `MaleText_loc7`='A veces... A veces duele tener tanto dinero. Es muy solitario. Solo estamos yo y todo mi oro.' WHERE `ID`=49853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 언젠가 작은 꼬마 녀석이 와서는, 나중에 크면 나처럼 돈방석 위에 앉고 싶다고 말하던 일이 생각나는군. 어찌나 귀엽던지. 가서 하던 걸레질을 계속하고 게으름 피우지 말라고 했지. 정말이야.', `MaleText_loc4`='哈哈哈！这让我想起，曾经有个小男孩走到我面前告诉我，他想成为和我一样的富翁——有一天能端坐在属于自己的金山上。真是可爱的小家伙。我告诉他赶快回去拖地板，别再偷懒了。我是认真的。', `MaleText_loc5`='哈哈!這讓我想起曾經有個小男孩跑來跟我說他希望有天能像我一樣，坐在他自己的金幣堆上面。真是可愛。我叫他回去拖地板，不要再偷懶了。真是的。', `MaleText_loc7`='¡Jajajajajaja! Esto me recuerda a un muchachito que un día vino y me dijo que quería ser como yo y que algún día también estaría sentado en una montaña de oro. Era tan adorable. Le dije que se dedicara a fregar el suelo y dejara de vaguear. Es que, venga, hombre.' WHERE `ID`=49854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라에게 돌아가서 우리가 북서쪽으로 이동한다고 알려주게.', `MaleText_loc4`='回去告诉阿格娜，我们正在朝西北方向前进。', `MaleText_loc5`='回去找阿格拉，告訴她我們要往西北邊前進。', `MaleText_loc7`='Vuelve al lado de Aggra y dile que nos movemos hacia el noroeste.' WHERE `ID`=49855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들을 위해 만세 삼창을 불러주지! 로켓길을 계속 돌아다니면서 물건도 많이 사줘. 그게 바로 아제로스에서 가장 숭고한 업적에 이바지하는 길이지. 바로 내 주머니 말이야!', `MaleText_loc4`='为你们所有人三呼万岁！继续乘火箭车驰骋，从商贩手中抢购商品吧。你们正在为艾泽拉斯最高尚的事业贡献自己的力量——用金币塞满我的口袋！', `MaleText_loc5`='為你們全部的人歡呼三聲!繼續在那條火箭道上奔馳，從那些商人那裡買東西吧。你們正在貢獻給整個艾澤拉斯最高尚的東西:我的荷包!', `MaleText_loc7`='¡Tres hurras por todos ustedes! ¡Sigan utilizando la Cohetepista y comprando de esos vendedores. ¡Están contribuyendo a la causa más noble de todo Azeroth: mis bolsillos!' WHERE `ID`=49856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워. 모두들 터질 것 같은 내 거대한 금더미를 보러 와줬군. 날 볼 수 있다는 것 자체가 놀라운 특권으로 여겨질 거야.', `MaleText_loc4`='谢谢。谢谢你们特地前来瞻仰我这浩瀚的金币海洋。能见到我本人，相信你们一定感到无比荣幸。', `MaleText_loc5`='謝謝，謝謝你們全部都來瞻仰我這超大一堆的金子。能見到我本人想必絕對是超榮幸的啦!', `MaleText_loc7`='Gracias. Gracias a todos por venir y admirar mis enormes y sobresalientes montones de oro. Debéis sentiros tan privilegiados porque se os permita estar en mi presencia.' WHERE `ID`=49857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 정말... 심하게 완벽해. 이 총과 금덩이. 그리고 여자들을 보라고. 나처럼 되고 싶지 않은 사람이 세상에 있을까?', `MaleText_loc4`='我简直是……太……会享受了。看看这些枪。看看这些金币。看看这些美女。谁会不想成为我呢？', `MaleText_loc5`='我實在是...太...漂亮了。看看這些砲。看看這些錢。看看這些妞。有誰不想要當我啊?', `MaleText_loc7`='Soy tan... bueno... guapo. Mirad esas armas. Mirad ese oro. Mirad esas chicas. ¿Quién no querría ser como yo?' WHERE `ID`=49858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=49859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 골짜기를 지나 황량한 전망대로 가서 킬라그를 만나세요.', `FemaleText_loc4`='经由谷地返回，与荒野瞭望台的基拉格会面。', `FemaleText_loc5`='回到峽谷那在野生眺望與奇拉格見面。', `FemaleText_loc7`='Regresa por el valle y reúnete con Kilag en el Mirador Salvaje.' WHERE `ID`=49860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<임시: 끝내주는 동영상!>', `MaleText_loc4`='<PLACEHOLDER: Exciting Cinematic!>', `MaleText_loc5`='<PLACEHOLDER: Exciting Cinematic!>', `MaleText_loc7`='<PLACEHOLDER: Exciting Cinematic!>' WHERE `ID`=49861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 나한테 얘기하는 거야? 너, 나만큼 돈이 없잖아?$B$B가서 비슷한 족속들과 어울리라고.', `MaleText_loc4`='你为什么要跟我说话？跟我比起来你简直就是个穷光蛋。$B$B去找你的同类吧，伙计。', `MaleText_loc5`='你為什麼在跟我說話?你賺的錢跟我差遠了。$B$B回去跟你的同類打混吧，老兄。', `MaleText_loc7`='¿Por qué hablar conmigo? Tú no ganas tanto dinero como yo ni de cerca.$B$BVe a mezclarte con los de tu propia clase, colega.' WHERE `ID`=49862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바스티아를 타게! 브락스를 찾아보게!', `MaleText_loc4`='骑乘巴斯蒂亚！去找布拉克斯！', `MaleText_loc5`='騎巴斯堤亞!去找布拉克斯!', `MaleText_loc7`='¡Monta en Bastia! ¡Encuentra a Brax!' WHERE `ID`=49863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 무역왕이네요.', `FemaleText_loc4`='呃哦，是贸易大王。', `FemaleText_loc5`='呃，是貿易親王。', `FemaleText_loc7`='¡Oh, oh, es el Príncipe mercante!' WHERE `ID`=49864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠타브라, 당신이 소문의 그 드루이드들 중 한 명입니까? 오래전에 메아리 섬에 드루이드들이 있었습니까?', `MaleText_loc4`='岑塔布拉，你是传闻中提到的德鲁伊之一吗？回音群岛上许久之前就已经有德鲁伊存在了？', `MaleText_loc5`='贊塔布拉，你是傳聞中的其中一個德魯伊嗎?很久以前，在回音群島上有德魯伊嗎?', `MaleText_loc7`='Zen''tabra, ¿eres uno de los druidas de los rumores? ¿Hace mucho tiempo había druidas en las Islas del Eco?', `FemaleText_loc1`='젠타브라, 당신이 소문의 그 드루이드들 중 한 명입니까? 오래전에 메아리 섬에 드루이드들이 있었습니까?', `FemaleText_loc4`='岑塔布拉，你是传闻中提到的德鲁伊之一吗？回音群岛上许久之前就已经有德鲁伊存在了？', `FemaleText_loc5`='贊塔布拉，你是傳聞中的其中一個德魯伊嗎?很久以前，在回音群島上有德魯伊嗎?', `FemaleText_loc7`='Zen''tabra, ¿eres uno de los druidas de los rumores? ¿Hace mucho tiempo había druidas en las Islas del Eco?' WHERE `ID`=49865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<웃는 젠타브라>$B$B우리가 그 소문을 퍼뜨렸네. 잘라제인과 다른 이들이 우리의 흔적을 놓쳐 찾지 못하도록 하는 거지. 자네가 듣는 모든 걸 믿지는 말게나.$B$B우린 기술을 배우기 시작한 지 몇 년 밖에 되지 않았다네. 하지만 여러 가지로 우린 부름에 답할 준비를 하는 데 평생을 보냈지.', `FemaleText_loc4`='<岑塔布拉大笑起来。>$B$B是我们散播的那些谣言，朋友。目的是要让扎拉赞恩和其它人远离我们。别相信你所听到的任何事。$B$B不，我们刚接触那门艺术不久，几年前才开始学习。但从某种程度上来说，我们毕生都在准备响应召唤……', `FemaleText_loc5`='<贊塔布拉笑了笑。>$B$B傳言是我們散佈的，老兄。這可以讓札拉贊恩離我們遠一點。別聽到什麼就相信什麼。$B$B我們現在是公會的新人，幾年前才開始，都還在學習。但從某種角度上來說，我們畢生都在做準備...', `FemaleText_loc7`='<Zen''tabra ríe.>$B$BNosotros extendimos esos rumores, colega. Pa'' mantener a Zalazane y a los demás lejos de nosotros. No creas to''o lo que oyes.$B$BNo, somos nuevos en eh''te arte, lo aprendimos hace tan solo unos pocos años. Pero en cieh''to modo, hemos eh''tado to''a la vida preparándonos pa'' responder a la llama''a...' WHERE `ID`=49866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 드루이드이기 전엔 무엇이었나요?', `MaleText_loc4`='那么在你们成为德鲁伊之前，你们的身份又是什么呢？', `MaleText_loc5`='那你成為德魯伊之前是什麼?', `MaleText_loc7`='Entonces, ¿qué eran antes de ser druidas?', `FemaleText_loc1`='그렇다면 드루이드이기 전엔 무엇이었나요?', `FemaleText_loc4`='那么在你们成为德鲁伊之前，你们的身份又是什么呢？', `FemaleText_loc5`='那你成為德魯伊之前是什麼?', `FemaleText_loc7`='Entonces, ¿qué eran antes de ser druidas?' WHERE `ID`=49867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 중 일부는 로아의 사제였네. 바로 잘라제인처럼 전엔 의술사였지...$B$B<젠타브라의 시선이 남쪽으로 향하면서 그녀의 얼굴이 굳어집니다.>$B$B우린 영혼들이 우리에게 화가 났다고 생각했네. 잘라제인이 영혼들에게서 우릴 서서히 단절시키고 있다고 의심하지 못했네. 우린 그가 강하다는 걸 알았지만, 그리 강하리라곤... 그의 부두교 마법이 다른 섬에 영향을 미칠 무렵이 되었을 때, 우린 전혀 그를 막을 수가 없었네.', `FemaleText_loc4`='我们当中有些人曾是祭司或巫医。就像扎拉赞恩……$B$B<岑塔布拉的视线飘向南方，神色变得严峻。>$B$B我们以为是自己惹怒了神祗，完全没怀疑过是扎拉赞恩在慢慢阻断我们之间的联结。我们知道他很强大，但没想到竟会这么强……当他的巫毒妖术蔓延到其它岛屿时，我们已无力阻止他。', `FemaleText_loc5`='我們有些人曾經是羅亞牧師，就是巫醫，與札拉贊恩一樣...$b$b<贊塔布拉將臉面向南方時表情也變得凝重。>$B$B我們以為靈魂對我們生氣;我們沒有猜到是札拉贊恩慢慢地將我們與它們進行分裂。我們知道他的力量強大，但沒想到那麼強大...然後，當他的巫毒術到達了另一座島後，我們已經無力阻止他了。', `FemaleText_loc7`='Algunos éramos sacerdotes loa, médicos brujos. Como Zalazane...$B$B<El roh''tro de Zen''tabra se endurece y su mirada se dirige al sur.>$B$BCreímos que los eh''píritus eh''taban enfada''os con nosotros; no soh''pechábamos que era Zalazane el que poco a poco nos alejaba de ellos. Sabíamos que era fueh''te, pero no tan fueh''te... y pa'' cuando su vudú había alcanza''o las demás islas, ya no teníamos poder pa'' deteneh''lo.' WHERE `ID`=49868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘라제인에게서 어떻게 도망쳤습니까?', `MaleText_loc4`='你是怎么逃离扎拉赞恩的？', `MaleText_loc5`='你怎麼從札拉贊恩手下逃脫的?', `MaleText_loc7`='¿Cómo escapasteis de Zalazane?', `FemaleText_loc1`='잘라제인에게서 어떻게 도망쳤나요?', `FemaleText_loc4`='你是怎么逃离扎拉赞恩的？', `FemaleText_loc5`='你怎麼從札拉贊恩手下逃脫的?', `FemaleText_loc7`='¿Cómo escapasteis de Zalazane?' WHERE `ID`=49869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<눈을 감고 머리를 흔드는 젠타브라>$B$B볼진 님께서 모든 이들에게 도망치라고 하셨지. 우... 우린 부족원들을 너무나 실망시켰기에 볼 면목이 없었네. 그래서 우린 남쪽 야생의 정글 섬으로 도망쳤지.$B$B도망친 첫 번째 밤 우리 중 일부는 야생동물에게 목숨을 잃었네. 우린 도망친 섬의 중앙에 있는 깊은 동굴에서 안전을 찾았지만, 내 꿈은 평화롭지 않았네. 환영을 보았다는 말이네!', `FemaleText_loc4`='<岑塔布拉闭上双眼，摇了摇头。>$B$B当沃金号令所有人逃离时，我们……我们深感无颜面对宗族。于是我们逃向了南方，藏进了那片未开化的丛林群岛。$B$B那里的野兽当晚就夺去了我们几个同伴的生命。我们在岛屿中部的深邃洞穴中找到了栖身之所，但我在那里的梦境并不安宁——我看到了幻像！', `FemaleText_loc5`='<贊塔布拉閉上眼睛並搖了搖頭。>$B$B當沃金呼籲大家開始逃跑時，我們...我們無法在犯下如此重大的錯誤後面對氏族。所以，我們便往南跑，到了未受到污染的叢林島。$B$B第一晚，野生的大自然取走了我們幾個人的性命。我們在島中央的洞穴深處庇難，但我不斷地在做夢:我看到了一個景象!', `FemaleText_loc7`='<Zen''tabra cierra los ojos y niega con la cabeza.>$B$BCuando Vol''jin ordenó a to''o el mundo que huyera... nosotros no podíamos mirar a la tribu a la cara tras habeh''les falla''o tan miserablemente. Así que huimos al sur, hacia las salvajes islas de la jungla.$B$BLas bestias salvajes se llevaron a unos cuantos de nosotros aquella noche. Encontramos refugio en una profunda cueva en el centro de la ih''la, pero mis sueños no eran tan pacíficos: ¡Tuve una visión!' WHERE `ID`=49870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 환영의 내용은 무었이었습니까?', `MaleText_loc4`='什么幻像？', `MaleText_loc5`='什麼樣的景象?', `MaleText_loc7`='¿De qué trataba la visión?', `FemaleText_loc1`='그 환영의 내용은 무엇이었나요?', `FemaleText_loc4`='什么幻像？', `FemaleText_loc5`='什麼樣的景象?', `FemaleText_loc7`='¿De qué trataba la visión?' WHERE `ID`=49871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 곧 시작됩니다!', `MaleText_loc4`='战斗即将开始！', `MaleText_loc5`='戰鬥即將開始!', `MaleText_loc7`='¡La batalla está a punto de comenzar!' WHERE `ID`=49872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_flamebolt.blp:32|t 화염 작렬을 사용해 황혼의 암흑비룡을 불태우십시오.', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_flamebolt.blp:32|t用火焰冲击来焚烧暮光暗影幼龙。', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_flamebolt.blp:32|t使用你的火焰衝擊來攻擊暮光暗影飛龍。', `MaleText_loc7`='|TInterfaceIconsspell_fire_flamebolt.blp:32|t Utiliza tu Explosión de Fuego para incinerar dracos de las sombras Crepusculares.' WHERE `ID`=49873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<젠타브라의 고개가 갑자기 당신을 향해 돌아섭니다. 그녀의 눈이 빛나며 그녀의 미소가 엄니 주위로 넓게 퍼집니다.>$B$B그렇게 크고 넓은 정글은 처음 봤다네! 내 앞에 나타난 고대 랩터 로아가 잔달라 부족 이야기에 대해 말했지. 대사냥꾼인 공크 말이야!$B$B그 랩터 영혼이 내게 말하길, 에메랄드의 꿈이라 불리는 곳으로 내 영혼을 데려왔다더군. 그 랩터 영혼은 잘라제인의 마법으로 메아리 섬에 있는 다른 로아들처럼 갇혀 있었네. 하지만 고대 영혼인 공크는 내 영혼을 불러올 수 있었지. 잘라제인의 부두교 마법을 뚫고 말이야.', `FemaleText_loc4`='<岑塔布拉猛地转向你，她的眼睛闪烁着光彩，獠牙外露的大嘴现出微笑。>$B$B这真是我的记忆中最为广袤狂野的丛林！古老的迅猛龙之神，赞达拉传说中伟大的猎手贡克竟然出现在我面前！$B$B那位迅猛龙的英灵同我交谈，将我的灵魂带到了一个被称为翡翠梦境的地方。像回音群岛的其他神灵一样，那位英灵被扎拉赞恩的魔法困住了。但这位古老的英灵还是穿过扎拉赞恩的妖术，将我带到他身边。', `FemaleText_loc5`='<贊塔布拉的頭轉向了你，她的眼睛發出光芒，笑著露出了獠牙。>$B$B是一片叢生，我前所未見的茂盛和野生叢林!而且站在我面前的，是一隻先祖迅猛龍，只存在於贊達拉傳說中的偉大獵人:鋼克!$B$B迅猛龍之靈與我對話，跟我說他把我的靈魂帶到了一個叫做翡翠夢境的地方。鋼克的靈魂被困住了，就與其他在回音群島的羅亞一樣，被札拉贊恩的法術給困住了。但是鋼克，身為先祖之靈，可以穿過札拉贊恩的巫毒將我的靈魂帶到他那裡。', `FemaleText_loc7`='<La cabeza de Zen''tabra se gira hacia ti, con los ojos brillantes y una sonrisa amplia alrededor de sus colmillos.>$b$b¡Era la jungla más grande y salvaje que había vih''to nunca! Y ante mí eh''taba el antiguo loa raptor del que solo se hablaba en las hih''torias Zandalari. ¡Gonk, el Gran Cazado''!$B$BEl eh''píritu del raptor me habló y me dijo que había lleva''o mi eh''píritu a un lugar llamado el Sueño Esmeralda. La magia de Zalazane había atrapado su eh''píritu como el del otro loa en las Islas del Eco. Pero Gonk, al ser un eh''píritu muy antiguo, había si''o capaz de alcanzarme y llevar mi eh''píritu a su la''o, incluso a pesar del vudú de Zalazane.' WHERE `ID`=49874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_ravage.blp:32|t 적이 약해지면 마무리 일격으로 하늘에서 끝내 버리십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_ravage.blp:32|t当敌人虚弱时，用终结强击来将他们击落！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_ravage.blp:32|t當你的敵人弱化之後，用你的終結打擊來把他們從天空給解決掉!', `MaleText_loc7`='|TInterfaceIconsability_druid_ravage.blp:32|t ¡Cuando tus enemigos estén débiles, hazlos caer del cielo con tu Golpe final!' WHERE `ID`=49875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 영혼이 원한 게 뭡니까?', `MaleText_loc4`='魂灵想要什么？', `MaleText_loc5`='那個靈魂想要什麼?', `MaleText_loc7`='¿Qué quería el espíritu?', `FemaleText_loc1`='그 영혼이 원한 게 뭔가요?', `FemaleText_loc4`='魂灵想要什么？', `FemaleText_loc5`='那個靈魂想要什麼?', `FemaleText_loc7`='¿Qué quería el espíritu?' WHERE `ID`=49876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_healingway.blp:32|t 생명의 어머니의 은혜를 사용하면 다른 비룡을 치유하면서 자신의 생명력과 마나도 회복할 수 있습니다.', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_healingway.blp:32|t生命缚誓者的礼物将在为你回复生命和法力值的同时，治疗其它成员。', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_healingway.blp:32|t你用生命守縛者的恩惠可以治療其他人，同時回復你的生命和法力。', `MaleText_loc7`='|TInterfaceIconsspell_nature_healingway.blp:32|t Tu Favor de la Protectora sanará a otros mientras restaura tu salud y tu maná.' WHERE `ID`=49877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘라제인의 넋을 잃은 하수인들은 그 섬의 모든 야수들을 죽이고, 나무와 풀도 태워버렸네. 공크는 섬의 생명체들을 살리는 데 우리 도움이 필요했지. 하지만 우린 잘라제인의 힘에 막혀 로아의 힘을 끌어낼 수 없었고 공크는 자연의 모든 영혼들과 접촉하는 새로운 방법을 보여줬네. 한 번에 하나의 로아와 접촉하는 게 아니라 자연의 모든 영혼들과 함께하는 방법을 말일세.$B$B처음엔 힘들었지만 공크는 또한 에메랄드의 꿈에 어떻게 이를 수 있는지를 보여줬지. 영혼들과 대화를 나누고 그들에게 직접 배우기 위해서 말이야!', `FemaleText_loc4`='扎拉赞恩无意识的奴仆们正在这些岛屿上屠杀动物，烧毁植被。贡克需要我们去拯救这片群岛。因为扎拉赞恩的阻碍，我们还无法汲取神灵之力，所以贡克传授给我们一个新的方法，能够与所有自然之灵建立联系。我们将借助全部神灵的力量，而不再只是某一位单独的神灵。$B$B一开始，这样做会很难，朋友。但贡克已经让我们懂得，该如何进入翡翠梦境，直接与那里的神灵对话，向他们学习技艺！', `FemaleText_loc5`='札拉贊恩無腦的僕人們在殘殺島上的野獸，燃燒樹木和植物。鋼克需要我們去拯救島上的生物。但因為我們無法在札拉贊恩的淫威之下聚集羅亞的力量，鋼克教導了我們一個新的方法與所有自然界的元素進行連接，與它們直接合作，不再是一次聽從一個羅亞的意志。$B$B一開始很困難，是啊老兄，但鋼克告訴了我們如何進入翡翠夢境直接與靈魂對話和向它們學習!', `FemaleText_loc7`='Los sirvientes descerebra''os de Zalazane eh''taban matando to''as las beh''tias de las islas, quemando los árboles y las plantas también. Gonk necesitaba que salváramos la vida de las ih''las. Pero como desde que Zalazane eh''taba al mando no podíamos reunir poder suficiente de los loa, Gonk nos enseñó una nueva forma de conectar con TO''OS los eh''píritus de la naturaleza, pa'' trabajar CON los eh''píritus, no simplemente servir a un solo loa cada vez.$B$BAl principio resultó difícil, colega, sí, ¡pero Gonk nos enseñó cómo alcanzar el Sueño Esmeralda pa'' hablar con los eh''píritus y aprender directamente de ellos!' WHERE `ID`=49878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 로아들은 어떻게 반응했습니까?', `MaleText_loc4`='其他神灵对此有何反应？', `MaleText_loc5`='其他的羅亞有什麼反應?', `MaleText_loc7`='¿Cómo reaccionaron los demás loa?', `FemaleText_loc1`='다른 로아들은 어떻게 반응했나요?', `FemaleText_loc4`='其他神灵对此有何反应？', `FemaleText_loc5`='其他的羅亞有什麼反應?', `FemaleText_loc7`='¿Cómo reaccionaron los demás loa?' WHERE `ID`=49879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<웃는 젠타브라>$B$B다른 로아들 특히 시르밸라는 그 계획을 그리 신경 쓰지 않았네. 그들은 우리가 영혼들 모두와 함께가 아니라 한 번에 하나의 영혼과 함께하길 바랐지. 하지만 공크는 그들에게 강요했고, 그들은 잘라제인이 군림하는 동안 섬을 살릴 수 있는 유일한 방법은 그것뿐이라는 걸 알았지.$B$B공크도 다른 로아들을 그리 신경 쓰지 않았다고 생각하네. 그는 항상 우리가 그들에게 가르침을 받는 동안 다른 로아들을 괴롭혔네.', `FemaleText_loc4`='<岑塔布拉笑了。>$B$B其他神灵，特别是希瓦拉尔，对他的计划颇不以为然。他们仍然希望我们一次只敬拜他们之中的一位，而不是同时与全部神灵沟通。但贡克对他们施加了很大压力。而且他们都明白，这是从扎拉赞恩手中拯救群岛的唯一办法。$B$B我相信，贡克也不很在意其他神灵的意见。当我们在神灵那里进行学习的时候，他一直在嘲笑他们。', `FemaleText_loc5`='<贊塔布拉笑了。>$B$B其他的羅亞，特別是希瓦拉爾，對於這項計畫一點都不關心。他們仍然希望我們一個一個來，而不是一次和全部的靈魂。但是剛克使他們別無選擇，因為他們知道在札拉贊恩的統治之下，這是唯一拯救回音群島的方法。$B$B我一直在想，剛克其實對其他的羅亞也不怎麼在乎。在我們還在向其他羅亞學習的時候，他一直在逗他們。', `FemaleText_loc7`='<Zen''tabra ríe.>$B$BA los demás loa, eh''pecialmente a Shirvallah, no les preocupó demasia''o el plan. Seguían queriendo que trabajáramos solo pa'' uno de ellos al mismo tiempo, no con to''os los eh''píritus a la vez. Pero Gonk insih''tió y vieron que era la única forma de salvar las islas mientras Zalazane siguiera en el poder.$B$BCreo que a Gonk tampoco le impoh''taban mucho los demás loa. Mientras nosotros aprendíamos de ellos, Gonk no dejaba de tomah''les el pelo.' WHERE `ID`=49880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다음엔 무슨 일이 일어났습니까?', `MaleText_loc4`='然后发生了什么？', `MaleText_loc5`='後來發生了什麼事?', `MaleText_loc7`='¿Y qué ocurrió después?', `FemaleText_loc1`='그다음엔 무슨 일이 일어났나요?', `FemaleText_loc4`='然后发生了什么？', `FemaleText_loc5`='後來發生了什麼事?', `FemaleText_loc7`='¿Y qué ocurrió después?' WHERE `ID`=49881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 그 영혼들과 여러 날 함께 일해왔네. 하지만 우리 중 많은 이들은 이미 우리가 전에 섬긴 로아의 형태를 알고 있네. 쉽진 않았지만, 에메랄드의 꿈은 그 자체로 우리의 강력한 스승이었네. 그곳의 영혼들이 우릴 가르쳐 주었지.$B$B그렇다고 잘라제인으로부터 쉽게 안전을 유지했다는 건 아니네. 로아의 도움과 우리의 새로운 기술을 동원했지만, 잘라제인의 부두교 마법과 그의 넋을 잃은 하수인들에게 수년간 우리 형제와 자매들 일부를 잃었네. 하지만 우린 섬의 생명들을 지켜냈고, 검은창 부족과 볼진 님이 돌아오셨을 때, 어떻게 잘라제인을 없앨지를 알았지.', `FemaleText_loc4`='我们之中的许多人都一直在侍奉这些神灵，早已熟悉了他们的形态。但在同诸神灵交流的练习中，我们还是渡过了许多个月亮的轮回。这并不容易，幸好除了教导我们的神灵们之外，翡翠梦境本身就是一位强大的教师……它会让一切事情以更快的速度演进。$B$B扎拉赞恩对我们造成了巨大的威胁。虽然神灵们在帮助我们，让我们掌握了新的技艺。但在过去几年，他的妖术和他无脑的奴仆们还是杀死了几名我们的兄弟姐妹。但我们终于保住了这些岛屿上的生命。当沃金和暗矛部族回归时，我们知道，彻底消灭扎拉赞恩的日子到了。', `FemaleText_loc5`='我們已經跟那些靈魂合作好幾個月了，老兄。但是我們大部分的人早就知道我們以前服侍的羅亞是什麼形態。這並不簡單，但是翡翠夢境本身就是很厲害的老師，同時由靈魂他們教導你... 這讓一切的進展更快。$B$B這不代表要在札拉贊恩眼皮子底下進行這一切很簡單。即使我們用上新的花招，加上羅亞他們的鼎力相助，我們多年來還是被他的巫毒和他無腦的僕人殺死了一些兄弟姊妹。但是我們讓回音群島維持生機，而且當沃金和他的暗矛部族回來時，我們已經知道如何解決札拉贊恩了。', `FemaleText_loc7`='Hace muchas lunas que trabajamos con los eh''píritus, colega, pero muchos de nosotros ya conocíamos las formas de los loa a los que habíamos servi''o antes. No fue fácil, pero el Sueño Esmeralda es un poderoso maeh''tro, ya que tienes a todos los eh''píritus enseñándote a la vez... La verdad es que acelera bah''tante las cosas.$B$BEso no significa que fuera fácil mantenernos a salvo de Zalazane. Incluso con eh''tos nuevos trucos combina''os con la ayuda que nos proporcionaban los loa, perdimos a unos cuantos hermanos y hermanas a lo largos de los años, por culpa de su vudú y sus sirvientes descerebrados. Pero mantuvimos la vida de las islas y cuando Vol''jin y los Lanza Negra regresaron, supimos que conseguiríamos acabar con Zalazane.' WHERE `ID`=49882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로아들은 아직도 마찬가지 입장인가요?', `MaleText_loc4`='神灵们仍然在履行他们允诺的职责吗？', `MaleText_loc5`='所以羅亞仍然維持他們的承諾嗎?', `MaleText_loc7`='¿Y los loa siguen acatando el trato?', `FemaleText_loc1`='로아들은 아직도 마찬가지 입장인가요?', `FemaleText_loc4`='神灵们仍然在履行他们允诺的职责吗？', `FemaleText_loc5`='所以羅亞仍然維持他們的承諾嗎?', `FemaleText_loc7`='¿Y los loa siguen acatando el trato?' WHERE `ID`=49883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러네. 지금으로선 우리 종족에게 그리 많은 걸 가르쳐 줄 열망이 없네만, 그들은 우리를 도와 이 섬에서 생명을 번창하는 한 우릴 도와줄 걸세. 잘라제인이 죽고 나서 공크가 떠났을 때, 그는 만약 다른 로아들이 약속을 충실히 이행하지 않으면 우리에게 어떻게 그에게 연락을 취하는지 말해줬네.$B$B그런 일은 절대 일어나지 않길 바라지만... 만에 하나의 경우라면 우린 세나리온 의회와의 소통 창구를 열 걸세.$B$B<마구 탁탁 소리를 내는 젠타브라>$B$B으, 자네가 그 나이트 엘프의 얼굴을 봤어야 해...', `FemaleText_loc4`='是的，朋友，至少现在还是这样。他们对于教导更多我们的族人并不热心。但只要我们还在维护这些岛屿上的生命茁壮生长，他们就会继续帮助我们。当扎拉赞恩灭亡，贡克离开的时候，他告诉我们，如果其他神灵不遵守契约，该如何与他取得联系。$B$B我希望这样的事情永远不要发生……但为了以防万一，我们还是和塞纳里奥议会建立了联系。$B$B<岑塔布拉发出一阵狂野的笑声。>$B$B哦，你真应该看看那些暗夜精灵的表情……', `FemaleText_loc5`='是的，老兄，以現在來說是這樣。他們並沒有太過熱衷於教導我們，但是只要我們繼續讓群島繁榮下去，他們就會繼續幫助我們。在札拉贊恩死亡後，鋼克在離開前告訴我們，若其他的羅亞沒有維持說好的協議的話，該如何聯絡他。$B$B我希望事情不至於走到那個地步...但是為了保險起見，我們跟那個塞納里奧議會取得了聯絡。$B$B<贊塔布拉瘋狂地咯咯笑著。>$B$B噢，你應該看看那個夜精靈臉上的表情...', `FemaleText_loc7`='Por ahora sí, colega. Ya no quieren enseñarnos nada más a los de nueh''tra e h''pecie, pero nos ayudarán mientras conservemos la vida de las islas en pleno florecimiento. Cuando Gonk se marchó tras la caída de Zalazane, nos dijo cómo podíamos contactar con él si los demás loa decidían no cumplir el trato.$B$BEh''pero que nunca lleguemos a eso... Pero por si acaso, hemos empeza''o a relacionarnos con ese grupo del Círculo Cenarion.$B$B<Zen''tabra ríe socarronamente.>$B$BTenías que haber vih''to la cara de aquel elfo de la noche...' WHERE `ID`=49884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 병사 대부분이 네페르세트 영토에 침투하다가 목숨을 잃었소.$B$B내게는 그들의 희생이 헛되지 않게 할 책임이 있소.', `MaleText_loc4`='在渗入尼斐塞特边境的行动中，我大部分兄弟都倒下了。$B$B他们决不能白白牺牲，对此我责无旁贷。', `MaleText_loc5`='我的人幾乎都在滲透奈斐賽特邊境時被殺了。$B$B我的責任是確保他們的犧牲是值得的。', `MaleText_loc7`='Muchos de mis hombres murieron al intentar infiltrarse en las fronteras de Neferset.$B$BEs mi deber hacer que su sacrificio merezca la pena.' WHERE `ID`=49885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르라고, $n. 상자 마을을 설치해. 안에 우리 고블린이 갇혀 있단 말이야! 이런! 낙하산을 깜빡하고 안 줄 뻔했군.', `MaleText_loc4`='赶快，$n，部署胶囊盒。我们的人都被困在里面！哦！我差点忘了你的降落伞。', `MaleText_loc5`='快點，$n，趕快啟動盒中鎮。我們的人民都困在裡面!噢，我差點忘了你的降落傘。', `MaleText_loc7`='Rápido, $n, despliega la Ciudad de Bolsillo. ¡Nuestra gente está atrapada dentro! ¡Oh! Casi olvido el paracaídas.' WHERE `ID`=49886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정말 기나긴 하루로군요.', `MaleText_loc4`='这是我生命中最漫长的一天。', `MaleText_loc5`='這是我生命中最長的一日。', `MaleText_loc7`='Este es el día más largo de mi vida.' WHERE `ID`=49887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호바트 님은 바로 뒤에 계셔.', `MaleText_loc4`='霍巴特就在你身后，$g阁下:女士;。', `MaleText_loc5`='荷巴爾特就在你後面，$g老闆:老闆娘;。', `MaleText_loc7`='Hobart está justo detrás de ti, $gseñor:señora;.' WHERE `ID`=49888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$g형제:자매;여, 치유될 겁니다!', `MaleText_loc4`='痊愈吧，$g兄弟:姐妹;！', `MaleText_loc5`='復原吧，$g兄弟:姊妹;!', `MaleText_loc7`='¡Sánate, $ghermano:hermana;!' WHERE `ID`=49889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유의 손길이 그대에게 닿으리니!', `MaleText_loc4`='我在全力治疗你！', `MaleText_loc5`='我用我的雙手來治療你!', `MaleText_loc7`='¡Y YO DEJO CAER MIS MANOS SOBRE TI!' WHERE `ID`=49890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛에 몸을 맡기십시오!', `MaleText_loc4`='让圣光拥抱你！', `MaleText_loc5`='願聖光擁抱你!', `MaleText_loc7`='¡Que la Luz Sagrada te envuelva!' WHERE `ID`=49891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛의 힘으로 소생할 것입니다!', `MaleText_loc4`='在圣光的照耀下焕发新生！', `MaleText_loc5`='以聖光之名，復原吧!', `MaleText_loc7`='¡QUE LA LUZ TE RENUEVE!' WHERE `ID`=49892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$G형제:자매;여, 싸우세요!', `MaleText_loc4`='继续战斗，$G兄弟:姐妹;！', `MaleText_loc5`='堅持下去，$G兄弟:姊妹;!', `MaleText_loc7`='¡LUCHA, $GHERMANO:HERMANA;!' WHERE `ID`=49893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이건 정말 간단하기 짝이 없는 일이야. 이 폭죽을 야생 꼬꼬에 달기만 하라고. 그러면 이 조종기를 이용해서 그놈들을 우리 안으로 날려버릴 테니까.', `MaleText_loc4`='其实简单得很，$n。只要把这些焰火装到野生肉鸡身上，然后我会用这控制器帮它们飞进笼子。', `MaleText_loc5`='這真的很簡單，$n。只要把這些煙火裝到野生咯雞上，然後我就用這個控制器讓牠們飛進籠子裡面。', `MaleText_loc7`='Es bastante sencillo, $n. Simplemente coloca fuegos artificiales a las cloqueadoras salvajes y yo utilizaré este control para que vuelen hasta la jaula.' WHERE `ID`=49894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수사님, 저를 치유해 주십시오!', `MaleText_loc4`='我需要治疗，兄弟！', `MaleText_loc5`='我需要治療，兄弟!', `MaleText_loc7`='¡Me vendría bien que me sanaran, hermano!' WHERE `ID`=49895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팩스턴 님, 뭐 하시는 겁니까? 절 좀 치유해 주세요!', `MaleText_loc4`='发挥你的作用，快治疗我，帕克斯顿！', `MaleText_loc5`='幫上一點忙，治療我，帕克斯頓!', `MaleText_loc7`='¡Haz algo útil y sáname, Paxton!' WHERE `ID`=49896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요!', `MaleText_loc4`='救命！', `MaleText_loc5`='救命!', `MaleText_loc7`='¡AYUDA!' WHERE `ID`=49897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유가 필요합니다!', `MaleText_loc4`='我需要治疗！', `MaleText_loc5`='我需要治療!', `MaleText_loc7`='¡Necesito sanación!' WHERE `ID`=49898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제대로 된 알을 구해다 달라고.', `MaleText_loc4`='现在给我们找些真正的蛋来。', `MaleText_loc5`='現在弄點真正的蛋來吧。', `MaleText_loc7`='Ahora consigamos unos huevos de verdad.' WHERE `ID`=49899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 기계닭을 우습게 보지 말라고. 뭐니 뭐니 해도 호바트 그래플해머 님의 발명품이니 말이야!', `MaleText_loc4`='别小看那机动战鸡，$n。那毕竟是霍巴特·钩锤的发明！', `MaleText_loc5`='不要小看機械小雞，$n。不管怎麼說，這是荷巴爾特·繫錘的發明!', `MaleText_loc7`='No subestimes al mecapollo, $n. ¡Después de todo, es un invento de Hobart Martillazos!' WHERE `ID`=49900;
