UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순례자의 감사절은 잘 즐기고 계십니까, $n 님? 찾는 게 있거든 뭐든 말씀하십시오.', `MaleText_loc4`='你感受到弥散在感恩节空气中的幸福了吗，$n？如果你需要帮助，可以来找我。', `MaleText_loc5`='你喜歡今年的旅人豐年祭嗎，$n?如果你需要任何東西，跟我說一聲。', `MaleText_loc7`='¿Estás disfrutando de la Generosidad del Peregrino, $n? Avísame si necesitas que te ayude a encontrar algo.', `FemaleText_loc1`='순례자의 감사절은 잘 즐기고 계신가요, $n 님? 찾는 게 있거든 뭐든 말씀하세요.', `FemaleText_loc4`='你感受到弥散在感恩节空气中的幸福了吗，$n？如果你需要帮助，可以来找我。', `FemaleText_loc5`='你喜歡今年的旅人豐年祭嗎，$n?如果你需要任何東西，跟我說一聲。', `FemaleText_loc7`='¿Estás disfrutando de la Generosidad del Peregrino, $n? Avísame si necesitas que te ayude a encontrar algo.' WHERE `ID`=49902;
