UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 기계상어 쾌속-X 제어기로 가세요. 성가신 왕망치를 처리해 주세요.', `FemaleText_loc4`='$n，到X型蒸汽机械鲨鱼控制器那儿去。帮我们摆脱巨锤的威胁！', `FemaleText_loc5`='$n，快去機械鯊魚噴射X控制器那裡。幫我們解決錘子的威脅!', `FemaleText_loc7`='$n, hazte con el controlador de Mecatiburón Vapor-X. ¡Líbranos de la amenaza del Martillo!' WHERE `ID`=49911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순례자의 감사절이 다가오자 뭔가 사고 싶은 욕망이 막 솟으십니까, $c님? 그렇다면 제대로 찾아오신 겁니다!', `MaleText_loc4`='感恩节激发起你的购物欲了吗，$c？嗯，那你可来对地方了！', `MaleText_loc5`='旅人豐年祭有引起你的購買慾嗎，$c?那你來對地方了!', `MaleText_loc7`='¿Acaso la Generosidad del Peregrino ha influido en tus ganas de comprar, $c? Bien, ¡pues has llegado al lugar adecuado!', `FemaleText_loc1`='순례자의 감사절이 다가오자 뭔가 사고 싶은 욕망이 막 솟으세요, $c님? 그렇다면 제대로 찾아오신 거예요!', `FemaleText_loc4`='感恩节激发起你的购物欲了吗，$c？嗯，那你可来对地方了！', `FemaleText_loc5`='旅人豐年祭有引起你的購買慾嗎，$c?那你來對地方了!', `FemaleText_loc7`='¿Acaso la Generosidad del Peregrino ha influido en tus ganas de comprar, $c? Bien, ¡pues has llegado al lugar adecuado!' WHERE `ID`=49912;
