UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이시여, 당신에게 축복이 있기를!', `MaleText_loc4`='祝你好运，英雄！', `MaleText_loc5`='祝福你，英雄!', `MaleText_loc7`='¡Que la Luz te bendiga, héroe!' WHERE `ID`=49916;
