UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아서 다시 열심히 싸울 겁니다!', `MaleText_loc4`='生命不息，战斗不止！', `MaleText_loc5`='我為了另一天的戰鬥而生存!', `MaleText_loc7`='¡Vivo para luchar otro día!' WHERE `ID`=49918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 전 괜찮아요! 괜찮다고요!', `MaleText_loc4`='我……我很好！我很好！', `MaleText_loc5`='我...我很好!我很好!', `MaleText_loc7`='¡Estoy... estoy bien! ¡Estoy bien!' WHERE `ID`=49919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행복한 겨울맞이 축제 보내십시오, $n 님!', `MaleText_loc4`='冬幕节快乐，$n！', `MaleText_loc5`='冬幕節快樂，$n!', `MaleText_loc7`='¡Feliz Festival del Invierno, $n!', `FemaleText_loc1`='행복한 겨울맞이 축제 보내세요, $n 님!', `FemaleText_loc4`='冬幕节快乐，$n！', `FemaleText_loc5`='冬幕節快樂，$n!', `FemaleText_loc7`='¡Feliz Festival del Invierno, $n!' WHERE `ID`=49920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행복이 가득한 겨울맞이 축제 보내시길 빕니다, $c님!', `MaleText_loc4`='祝你冬幕节快乐，$c！', `MaleText_loc5`='祝你冬幕節快樂，$n!', `MaleText_loc7`='¡Feliz Festival del Invierno, $c!', `FemaleText_loc1`='행복이 가득한 겨울맞이 축제 보내시길 빌어요, $c님!', `FemaleText_loc4`='祝你冬幕节快乐，$c！', `FemaleText_loc5`='祝你冬幕節快樂，$n!', `FemaleText_loc7`='¡Feliz Festival del Invierno, $c!' WHERE `ID`=49921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 $n 님이 아니십니까! 모든 이들이 얘기하던 그 영웅! 감사합니다!', `MaleText_loc4`='你是$n！人人交口称赞的大英雄！谢谢你！', `MaleText_loc5`='你是$n!大家都在談論的英雄!謝謝你!', `MaleText_loc7`='¡Eres $n! ¡El héroe del que habla todo el mundo! ¡Gracias!' WHERE `ID`=49922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽한 겨울맞이 축제 선물을 찾고 계십니까, $c님? 아니면 자신을 위해 오신 건가요?', `MaleText_loc4`='你在寻找最棒的冬幕节礼物吗，$c，还是想要好好犒劳自己一番？', `MaleText_loc5`='在找完美的冬幕節禮物嗎，$c?還是只是來犒賞自己一番?', `MaleText_loc7`='¿Buscas el regalo perfecto para el Festival del Invierno, $c, o has venido para darte un capricho?', `FemaleText_loc1`='완벽한 겨울맞이 축제 선물을 찾고 계신가요, $c님? 아니면 자신을 위해 오신 건가요?', `FemaleText_loc4`='你在寻找最棒的冬幕节礼物吗，$c，还是想要好好犒劳自己一番？', `FemaleText_loc5`='在找完美的冬幕節禮物嗎，$c?還是只是來犒賞自己一番?', `FemaleText_loc7`='¿Buscas el regalo perfecto para el Festival del Invierno, $c, o has venido para darte un capricho?' WHERE `ID`=49923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 겨울맞이 축제 보내고 계시길 바랍니다, $n 님!', `MaleText_loc4`='希望你能拥有一个最幸福的冬幕节，$n！', `MaleText_loc5`='希望你的冬幕節過得愉快，$n!', `MaleText_loc7`='¡Espero que estés disfrutando de un maravilloso Festival del Invierno, $n!', `FemaleText_loc1`='즐거운 겨울맞이 축제 보내고 계시길 바라요, $n 님!', `FemaleText_loc4`='希望你能拥有一个最幸福的冬幕节，$n！', `FemaleText_loc5`='希望你的冬幕節過得愉快，$n!', `FemaleText_loc7`='¡Espero que estés disfrutando de un maravilloso Festival del Invierno, $n!' WHERE `ID`=49924;
