UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행복이 가득한 겨울맞이 축제 보내길 비오, $c|1이여;여;!', `MaleText_loc4`='祝你冬幕节快乐，$c！', `MaleText_loc5`='祝你冬幕節快樂，$n!', `MaleText_loc7`='¡Feliz Festival del Invierno, $c!', `FemaleText_loc1`='행복이 가득한 겨울맞이 축제 보내시길 빌어요, $c님!', `FemaleText_loc4`='祝你冬幕节快乐，$c！', `FemaleText_loc5`='祝你冬幕節快樂，$n!', `FemaleText_loc7`='¡Feliz Festival del Invierno, $c!' WHERE `ID`=49926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽한 겨울맞이 축제 선물을 찾고 있소, $c|1이여;여;? 아니면 자신을 위해 온 거요?', `MaleText_loc4`='你在寻找最棒的冬幕节礼物吗，$c，还是想要好好犒劳自己一番？', `MaleText_loc5`='在找完美的冬幕節禮物嗎，$c?還是只是來犒賞自己一番?', `MaleText_loc7`='¿Buscas el regalo perfecto para el Festival del Invierno, $c, o has venido para darte un capricho?', `FemaleText_loc1`='완벽한 겨울맞이 축제 선물을 찾고 계신가요, $c님? 아니면 자신을 위해 오신 건가요?', `FemaleText_loc4`='你在寻找最棒的冬幕节礼物吗，$c，还是想要好好犒劳自己一番？', `FemaleText_loc5`='在找完美的冬幕節禮物嗎，$c?還是只是來犒賞自己一番?', `FemaleText_loc7`='¿Buscas el regalo perfecto para el Festival del Invierno, $c, o has venido para darte un capricho?' WHERE `ID`=49927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 겨울맞이 축제 보내고 있길 바라오, $n!', `MaleText_loc4`='希望你能拥有一个最幸福的冬幕节，$n！', `MaleText_loc5`='希望你的冬幕節過得愉快，$n!', `MaleText_loc7`='¡Espero que estés disfrutando de un maravilloso Festival del Invierno, $n!', `FemaleText_loc1`='즐거운 겨울맞이 축제 보내고 계시길 바라요, $n 님!', `FemaleText_loc4`='希望你能拥有一个最幸福的冬幕节，$n！', `FemaleText_loc5`='希望你的冬幕節過得愉快，$n!', `FemaleText_loc7`='¡Espero que estés disfrutando de un maravilloso Festival del Invierno, $n!' WHERE `ID`=49928;
