UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멕스가 한 시장 조사를 보니 나가가 곧 침공한다더군!', `MaleText_loc4`='市场调研结果显示，纳迦即将发起入侵！', `MaleText_loc5`='梅格斯所主持的市場研究說明納迦的入侵即將來臨!', `MaleText_loc7`='¡El estudio de marketing que ha realizado Megs sugiere que la invasión naga es inminente!' WHERE `ID`=49934;
