UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상님들이 당신을 축복하길, 그리고 다가오는 해에 행운이 따르길 빕니다, $n 님.', `MaleText_loc4`='愿先祖护佑着你，$n，让你在新的一年中与好运相伴。', `MaleText_loc5`='願你的祖先保佑你，$n，並使你未來的一年有著好運氣。', `MaleText_loc7`='$n, que tus ancestros te bendigan y te den mucha suerte para el nuevo año.', `FemaleText_loc1`='조상님들이 당신을 축복하길, 그리고 다가오는 해에 행운이 따르길 빕니다, $n 님.', `FemaleText_loc4`='愿先祖护佑着你，$n，让你在新的一年中与好运相伴。', `FemaleText_loc5`='願你的祖先保佑你，$n，並使你未來的一年有著好運氣。', `FemaleText_loc7`='$n, que tus ancestros te bendigan y te den mucha suerte para el nuevo año.' WHERE `ID`=49936;
