UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 나가 놈아, 들리지? $n 님께서 우리 "협상"을 마무리 지으러 가신다!', `FemaleText_loc4`='你听见了吗，纳迦？$n正在赶来落实我们的“谈判”！', `FemaleText_loc5`='聽到了沒，納迦?$n$g他:她;正要過來搞定我們的「談判」!', `FemaleText_loc7`='¿Habéis oído eso, nagas? ¡$n viene de camino para llegar a un acuerdo en nuestras "negociaciones"!' WHERE `ID`=49938;
