UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽을 가지고 돌아오면 수익을 어떻게 나눌지 논의하자고. 90대 10이면 어떨까 싶은데.', `MaleText_loc4`='等你拿回那些皮子之后，我们就能讨论分成的问题了。我想，我九你一应该不错。', `MaleText_loc5`='我們可以等你把皮革帶回來再決定怎樣分錢。我想的是我九你一。', `MaleText_loc7`='Podemos hablar del reparto cuando regreses con los pellejos. Estoy pensando en noventa-diez.' WHERE `ID`=49948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거운 가을 축제로군요, $n 님!', `MaleText_loc4`='美酒节快乐，$n！', `MaleText_loc5`='啤酒節快樂，$n!', `MaleText_loc7`='¡Feliz Fiesta de la Cerveza, $n!', `FemaleText_loc1`='즐거운 가을 축제로군요, $n 님!', `FemaleText_loc4`='美酒节快乐，$n！', `FemaleText_loc5`='啤酒節快樂，$n!', `FemaleText_loc7`='¡Feliz Fiesta de la Cerveza, $n!' WHERE `ID`=49949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한여름 불꽃축제는 잘 즐기고 계십니까, $c님?', `MaleText_loc4`='享受到火焰节的乐趣了吗，$c？', `MaleText_loc5`='今年的仲夏火焰節慶還不錯吧，$c?', `MaleText_loc7`='¿Disfrutando del Festival de Fuego del Solsticio de Verano, $c?', `FemaleText_loc1`='한여름 불꽃축제는 잘 즐기고 계신가요, $c님?', `FemaleText_loc4`='享受到火焰节的乐趣了吗，$c？', `FemaleText_loc5`='今年的仲夏火焰節慶還不錯吧，$c?', `FemaleText_loc7`='¿Disfrutando del Festival de Fuego del Solsticio de Verano, $c?' WHERE `ID`=49950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물놀이용 조랑말은 누구나 좋아하죠. 유아용 와장창 폭탄 바로 다음으로 잘 팔리는 장난감이에요.', `FemaleText_loc4`='所有人都喜欢小马泳圈。紧随在不靠谱炸弹：未成年人版之后，它是我们这里的销量亚军。', `FemaleText_loc5`='每個人都愛小馬泳圈。這是我們目前除了毀壞炸彈嬰兒版之外銷售最快的玩具。', `FemaleText_loc7`='A todo el mundo le gustan los ponis flotadores. Es la mercancía que vendemos más rápido después de las Bombas Kabum: edición infantil.' WHERE `ID`=49951;
