UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 빌지워터 무역회사 섬멸포 하나에 올라타고 소인족을 쓸어버리세요!', `FemaleText_loc4`='$n，跳进B.C.消除者，把那些俾格米人消灭干净！', `FemaleText_loc5`='$n，快跳進其中一台B.C.殲滅者，並殺光那些俾格米!', `FemaleText_loc7`='¡$n, súbete a uno de esos Eliminadores B.C. y liquida a los pigmeos!' WHERE `ID`=49973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들과 제대로 한 판 붙어 주셔야 해요. $n 님, 소인족 마을 바깥쪽에서 이지를 찾아보세요.', `FemaleText_loc4`='如果你要和他们战斗，$n，你可以在他们的村外去找小静。', `FemaleText_loc5`='你得跟他們開戰，$n。在他們的村落外面找找伊茲。', `FemaleText_loc7`='Vas a tener que llevar la pelea hasta ellos, $n. Busca a Izzy en el exterior de su poblado.' WHERE `ID`=49974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 전 당신을 도울 수 없습니다.', `MaleText_loc4`='我帮不了你，$c。', `MaleText_loc5`='我無法幫助你，$c。', `MaleText_loc7`='No puedo ayudarte, $c.', `FemaleText_loc1`='$c님, 전 당신을 도울 수 없습니다.', `FemaleText_loc4`='我帮不了你，$c。', `FemaleText_loc5`='我無法幫助你，$c。', `FemaleText_loc7`='No puedo ayudarte, $c.' WHERE `ID`=49975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우아한 움직임이군요. 어떻게 도와드리면 좋겠습니까?', `MaleText_loc4`='能看出，你是一名技艺高超的潜行者。我能帮你些什么？', `MaleText_loc5`='你的行動優雅，盜賊。我能幫你什麼忙?', `MaleText_loc7`='Te mueves con agilidad, $gpícaro:pícara;. ¿Cómo puedo ayudarte?', `FemaleText_loc1`='우아한 움직임이군요. 어떻게 도와드릴까요?', `FemaleText_loc4`='能看出，你是一名技艺高超的潜行者。我能帮你些什么？', `FemaleText_loc5`='你的行動優雅，盜賊。我能幫你什麼忙?', `FemaleText_loc7`='Te mueves con agilidad, $gpícaro:pícara;. ¿Cómo puedo ayudarte?' WHERE `ID`=49976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 문서가 공중으로 날아갑니다!', `MaleText_loc4`='暮光文件飞散开了！', `MaleText_loc5`='暮光密件在空中飛過!', `MaleText_loc7`='¡Los documentos Crepusculares salen volando!' WHERE `ID`=49977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 작전은 제가 지휘합니다.$B$B우리 비행선이 잘 폭발한다느니 적이 우리보다 키가 크느니 하는 소리는 집어치우십시오. 우린 전문가고, 아무 문제 없이 일을 처리할 겁니다.', `MaleText_loc4`='我是这次行动的负责人。$B$B我可不想听到有人因为我们的运输工具爆炸，或者是敌人比我们高之类的无聊事情而抱怨。我们是专业人士，要一丝不苟地完成工作。', `MaleText_loc5`='我負責這次的行動。$B$B我不想聽到有人抱怨我們的運輸機爆炸或者敵人比我們高大之類的事情。我們非常專業，所以我們可以毫不眨眼地完成這項工作。', `MaleText_loc7`='Estoy al mando de esta operación.$B$BNo quiero oír sus tonterías sobre la explosión de nuestro transporte o que los enemigos son más altos que nosotros. Somos profesionales y vamos a cumplir con este trabajo sin una sola queja.' WHERE `ID`=49978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시하고, 똑똑하고, 전능하며, 증오로 넘치고, 칼을 휘두르고, 얼굴에 주먹을 날리고, 욕설을 던지며, 앞으로 봐도 뒤로 봐도 잘생긴, 버기 블랙하트 님을 보며 눈을 정화하라고.', `MaleText_loc4`='好好看着，这就是恐怖的，聪明的，无所不能的，满心憎恨的，高举利剑的，勇猛杀敌的，战无不胜的，还有最重要的一点——英俊无比的布尔吉·黑心。', `MaleText_loc5`='睜眼好好瞧瞧可怕、聰敏、強大、充滿仇恨、劍刃飛舞、專門打臉、最愛把人惹毛、而且又帥到爆的伯吉·黑心!', `MaleText_loc7`='Regocíjate ante el temible, inteligente, todopoderoso, odioso, gran espadachín, golpea caras, arroja insultos y, en general, guapísimo, Burgy Corazón Negro.' WHERE `ID`=49979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이야. 정화하라니까. 난 꽤 아름답다고.', `MaleText_loc4`='好好看看，我是多么美丽啊。', `MaleText_loc5`='說真的。睜大眼睛瞧瞧。我如此美麗。', `MaleText_loc7`='En serio. Regocíjate. Soy bastante guapo.' WHERE `ID`=49980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[DEBUG] I left combat!!!', `MaleText_loc4`='我离开了战斗！！！', `MaleText_loc5`='[DEBUG] 我離開戰鬥了!!!', `MaleText_loc7`='[DEBUG] ¡¡¡He abandonado el combate!!!', `FemaleText_loc1`='[DEBUG] I left combat!!!', `FemaleText_loc4`='我离开了战斗！！！', `FemaleText_loc5`='[DEBUG] 我離開戰鬥了!!!', `FemaleText_loc7`='[DEBUG] ¡¡¡He abandonado el combate!!!' WHERE `ID`=49983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감독관 스틸워터가 도착하기 전에 방어선을 구축하십시오!', `MaleText_loc4`='在看守者斯蒂沃特到来之前建立起防御！', `MaleText_loc5`='趁管理員斯蒂沃特抵達前設置好防禦!', `MaleText_loc7`='¡Construye algunas defensas antes de que llegue el celador Aguaserena!', `FemaleText_loc1`='감독관 스틸워터가 도착하기 전에 방어선을 구축하십시오!', `FemaleText_loc4`='在看守者斯蒂沃特到来之前建立起防御！', `FemaleText_loc5`='趁管理員斯蒂沃特抵達前設置好防禦!', `FemaleText_loc7`='¡Construye algunas defensas antes de que llegue el celador Aguaserena!' WHERE `ID`=49984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀비들에 휩싸이기 전에 감독관 스틸워터를 처치하십시오!', `MaleText_loc4`='在你被敌人压垮之前，一定要干掉看守者斯蒂沃特！', `MaleText_loc5`='在你被大軍淹沒前殺死管理員斯蒂沃特!', `MaleText_loc7`='¡Mata al celador Aguaserena antes de que te veas $gsuperado:superada;!', `FemaleText_loc1`='좀비들에 휩싸이기 전에 감독관 스틸워터를 처치하십시오!', `FemaleText_loc4`='在你被敌人压垮之前，一定要干掉看守者斯蒂沃特！', `FemaleText_loc5`='在你被大軍淹沒前殺死管理員斯蒂沃特!', `FemaleText_loc7`='¡Mata al celador Aguaserena antes de que te veas $gsuperado:superada;!' WHERE `ID`=49985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 여기까지다. 지금부터 우리의 진짜 힘을 보여주마!', `MaleText_loc4`='不要再犯傻了。该是进行手动操控的时候了！', `MaleText_loc5`='別再打混了!是時候我親自進行管理了!', `MaleText_loc7`='Ya está bien de marear la perdiz. ¡Es hora de que aquí haya una dirección activa!', `FemaleText_loc1`='장난은 여기까지다. 지금부터 우리의 진짜 힘을 보여주마!', `FemaleText_loc4`='不要再犯傻了。该是进行手动操控的时候了！', `FemaleText_loc5`='別再打混了!是時候我親自進行管理了!', `FemaleText_loc7`='Ya está bien de marear la perdiz. ¡Es hora de que aquí haya una dirección activa!' WHERE `ID`=49986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니?! 안돼! 이 정원은... 내... 거야...', `MaleText_loc4`='什么？不！这片草坪……是……我的……', `MaleText_loc5`='什麼?!不!這片草地...是...我的...', `MaleText_loc7`='¡¿Qué?! ¡No! Este césped... era... mío...', `FemaleText_loc1`='아니?! 안돼! 이 정원은... 내... 거야...', `FemaleText_loc4`='什么？不！这片草坪……是……我的……', `FemaleText_loc5`='什麼?!不!這片草地...是...我的...', `FemaleText_loc7`='¡¿Qué?! ¡No! Este césped... era... mío...' WHERE `ID`=49987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<의식을 잃은 SI:7 요원>', `MaleText_loc4`='<军情七处的密探失去了意识。>', `MaleText_loc5`='<軍情七處密探不省人事。>', `MaleText_loc7`='<El agente IV:7 está inconsciente.>' WHERE `ID`=49988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑이 본다. 발크와리 오그 샤다르. 종말이 다가온다!', `MaleText_loc4`='暗影所见。Bal''qwari Og Shadar。终结到来！', `MaleText_loc5`='暗影在凝視著。末日將臨!', `MaleText_loc7`='La sombra ve. Bal''qwari Og Shadar. ¡El final se acerca!', `FemaleText_loc1`='암흑이 본다. 발크와리 오그 샤다르. 종말이 다가온다!', `FemaleText_loc4`='暗影所见。Bal''qwari Og Shadar。终结到来！', `FemaleText_loc5`='暗影在凝視著。末日將臨!', `FemaleText_loc7`='La sombra ve. Bal''qwari Og Shadar. ¡El final se acerca!' WHERE `ID`=49989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일식이 일어난다. 흙과 재 사이로 어둠이 기어간다. 바다는 피로 물결 친다...', `MaleText_loc4`='太阳失去光芒。黑暗与灰烬覆盖大地。海洋如血般鲜红……', `MaleText_loc5`='日蝕正近。黑暗爬過了土與灰。海如血...', `MaleText_loc7`='El sol se eclipsa. La oscuridad se arrastra por la tierra y la ceniza. Los mares son como sangre...', `FemaleText_loc1`='일식이 일어난다. 흙과 재 사이로 어둠이 기어간다. 바다는 피로 물결 친다...', `FemaleText_loc4`='太阳失去光芒。黑暗与灰烬覆盖大地。海洋如血般鲜红……', `FemaleText_loc5`='日蝕正近。黑暗爬過了土與灰。海如血...', `FemaleText_loc7`='El sol se eclipsa. La oscuridad se arrastra por la tierra y la ceniza. Los mares son como sangre...' WHERE `ID`=49990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무한함의 심장에서 스며 나오는 펄펄 끓는 열기를 두려워하라... 보여주지 마! 내가 견딜 수 있는 것보다 더 많이 보았다!', `MaleText_loc4`='恐惧从永恒之心内蒸腾而出。别逼我看！我所看到的一切已经超出了我的承受极限！', `MaleText_loc5`='恐懼從無數之心滾滾而來...別逼我看!我看的已經超越我能承受的極限!', `MaleText_loc7`='El miedo arde desde el corazón del infinito... ¡No me hagas mirar! ¡He visto más de lo que puedo soportar!', `FemaleText_loc1`='무한함의 심장에서 스며 나오는 펄펄 끓는 열기를 두려워하라... 보여주지 마! 내가 견딜 수 있는 것보다 더 많이 보았다!', `FemaleText_loc4`='恐惧从永恒之心内蒸腾而出。别逼我看！我所看到的一切已经超出了我的承受极限！', `FemaleText_loc5`='恐懼從無數之心滾滾而來...別逼我看!我看的已經超越我能承受的極限!', `FemaleText_loc7`='El miedo arde desde el corazón del infinito... ¡No me hagas mirar! ¡He visto más de lo que puedo soportar!' WHERE `ID`=49991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도, 아무것도 아니다. 우리는 아무것도 아니다. 그것이 우리 심장을 붙들고 쥐어짠다.', `MaleText_loc4`='虚无，虚无，我们化为虚无。执掌一切者握住我们的心灵，攥紧了他的拳头。', `MaleText_loc5`='什麼都不是，什麼都不是，我們什麼都不是。抓緊者觸摸到我們的心臟並收緊了。', `MaleText_loc7`='Nada, nada, no somos nada. El que agarra toca nuestro corazón y cierra el puño.', `FemaleText_loc1`='아무것도, 아무것도 아니다. 우리는 아무것도 아니다. 그것이 우리 심장을 붙들고 쥐어짠다.', `FemaleText_loc4`='虚无，虚无，我们化为虚无。执掌一切者握住我们的心灵，攥紧了他的拳头。', `FemaleText_loc5`='什麼都不是，什麼都不是，我們什麼都不是。抓緊者觸摸到我們的心臟並收緊了。', `FemaleText_loc7`='Nada, nada, no somos nada. El que agarra toca nuestro corazón y cierra el puño.' WHERE `ID`=49992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋으실 대로 하십시오, $p. 전 에루낙 님을 따라가겠습니다!', `MaleText_loc4`='随你怎样，$p。我要去追埃鲁纳克！', `MaleText_loc5`='隨便你怎麼做，$p。我要去找伊魯納克!', `MaleText_loc7`='Haz lo que quieras, $n. ¡Yo iré a por Erunak!' WHERE `ID`=49993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길라리, 게스샤르. 길라리, 테코샤르. 그것은 본다. 그것은 안다.', `MaleText_loc4`='Gillari, geth''shar. Gillari, teko''shar，无所不见，无所不知。', `MaleText_loc5`='吉拉利蓋斯沙。吉拉利特寇沙。它看見。它知道。', `MaleText_loc7`='Gillari, geth''shar. Gillari, teko''shar. Él ve. Lo sabe.', `FemaleText_loc1`='길라리, 게스샤르. 길라리, 테코샤르. 그것은 본다. 그것은 안다.', `FemaleText_loc4`='Gillari, geth''shar. Gillari, teko''shar，无所不见，无所不知。', `FemaleText_loc5`='吉拉利蓋斯沙。吉拉利特寇沙。它看見。它知道。', `FemaleText_loc7`='Gillari, geth''shar. Gillari, teko''shar. Él ve. Lo sabe.' WHERE `ID`=49994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈은 뜨여 있으나 어둠밖에 보이지 않는다.', `MaleText_loc4`='我睁开双眼，却只见到黑暗。', `MaleText_loc5`='我的眼睛已經張開，但是只見到黑暗。', `MaleText_loc7`='Mi ojos están abiertos pero solo ven oscuridad.', `FemaleText_loc1`='눈은 뜨여 있으나 어둠밖에 보이지 않는다.', `FemaleText_loc4`='我睁开双眼，却只见到黑暗。', `FemaleText_loc5`='我的眼睛已經張開，但是只見到黑暗。', `FemaleText_loc7`='Mi ojos están abiertos pero solo ven oscuridad.' WHERE `ID`=49995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세스노스, 올고스, 그렐. 다가오는 자를 맞을 진언.', `MaleText_loc4`='Shethnoth, ol''goth, grell，这便是即将到来者的咒文。', `MaleText_loc5`='奢諾斯歐勾斯。這就是來者的禱文。', `MaleText_loc7`='Shethnoth, ol''goth, grell. Este es el mantra de aquellos que vienen.', `FemaleText_loc1`='세스노스, 올고스, 그렐. 다가오는 자를 맞을 진언.', `FemaleText_loc4`='Shethnoth, ol''goth, grell，这便是即将到来者的咒文。', `FemaleText_loc5`='奢諾斯歐勾斯。這就是來者的禱文。', `FemaleText_loc7`='Shethnoth, ol''goth, grell. Este es el mantra de aquellos que vienen.' WHERE `ID`=49996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선구자가 왔다. 세상이 한숨을 내쉰다.', `MaleText_loc4`='先驱者到来了。世界在颤抖。', `MaleText_loc5`='先驅者已降臨。世界為之震動。', `MaleText_loc7`='El heraldo ha llegado. El mundo tiembla.', `FemaleText_loc1`='선구자가 왔다. 세상이 한숨을 내쉰다.', `FemaleText_loc4`='先驱者到来了。世界在颤抖。', `FemaleText_loc5`='先驅者已降臨。世界為之震動。', `FemaleText_loc7`='El heraldo ha llegado. El mundo tiembla.' WHERE `ID`=49997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도르무스 낙타를 가져가겠다고? 안돼! 내 낙타야! 도르무스, 너 죽인다!!!', `MaleText_loc4`='你想要多尔穆斯骆驼？不！那是我的骆驼！多尔穆斯杀死你！！！', `MaleText_loc5`='你想搶多姆斯的駱駝?不!!我的駱駝!!多姆斯殺了你!!!', `MaleText_loc7`='¿Tú querer llevarte los camellos de Dormus? ¡NO! ¡MIS CAMELLOS! ¡¡¡DORMUS MATARTE!!!' WHERE `ID`=49998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 그 훈연기 안에 가까이 가지 마! 요전에도 어떤 불쌍한 $r|1이;가; 그랬다가 열기에 살아남지 못했다고.$b$b그 불쌍하고... 맛있는 $r 친구 같으니라고...', `MaleText_loc4`='嗨，一定不要走进那个冒烟的地方！上一个不幸的$r就是因为无法承受那里的高热而完蛋的。$b$b那可真是个可怜又美味的$r。', `MaleText_loc5`='嘿，小心不要走進那個烤架。上一個不幸的$r沒有在那樣的溫度下存活下來。$b$b那個可憐、好吃的$r。', `MaleText_loc7`='Ey, ¡será mejor que no te acerques a ese ahumador! $gEl último desafortunado:La última desafortunada; $r que lo hizo no sobrevivió al calor.$b$b$gEse:Esa; pobre y $gdelicioso:deliciosa; $r.' WHERE `ID`=49999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 에루낙 님을 따라가겠네. 자네가 진정한 $r|1이라면;라면; 자네 역시 따라올 거라 생각하네!', `MaleText_loc4`='我要去追埃鲁纳克，如果你真的是个$r，你一定也会来的！', `MaleText_loc5`='我要去追伊魯納克。$r，要是你有自己講的那麼厲害，那就一起來吧!', `MaleText_loc7`='Voy a ir a por Erunak y si eres la mitad de $r que dices que eres, ¡tú también vendrás!' WHERE `ID`=50000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 내 상태 좀 배려해주게나. 지난 며칠간 힘든 나날을 보냈으니 다른 말은 하지 않았으면 좋겠군.', `MaleText_loc4`='请不要让一个兽人认为你是蠢货。我这里的日子不好过，如果你能安静一点，我会很高兴的。', `MaleText_loc5`='拜託，麻煩請對獸人講話客氣點好嗎。我這幾天過得真的很辛苦，你那些評論還是自己留著就好。', `MaleText_loc7`='Por favor, sé comprensivo con el sufrimiento de un orco. Estoy teniendo un par de días muy malos y preferiría que te guardes tus comentarios para ti $gmismo:misma;.' WHERE `ID`=50001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈자르와 그 부하들을 처치하고 싶은 마음은 굴뚝 같지만, 누군가는 당신의 뒤를 봐 줘야 하지 않겠습니까...', `MaleText_loc4`='剿灭纳兹夏尔和她的爪牙是我最想去做的事，但我也需要有人掩护……', `MaleText_loc5`='我超想自己去幹掉納茲賈爾和她的手下，但是總有人得在後面掩護你...', `MaleText_loc7`='Nada me gustaría más que acabar con Naz''jar y sus esbirros, pero alguien tiene que cubrirte las espaldas...' WHERE `ID`=50002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 마녀의 목을 내 손으로 비틀고 싶은 마음은 굴뚝 같지만, 누군가는 당신의 뒤를 보호해야 하지 않겠습니까...$b$b$n, 절 실망시키지 마십시오!', `MaleText_loc4`='现在我最想去做的就是亲手消灭那个女巫。但我需要有人帮我挡住那些偷袭的纳迦……$b$b不要让我失望，$n！', `MaleText_loc5`='我超想自己去扭斷那個女妖婆的脖子，但是總有人得在背後幫你趕走納迦...$b$b別讓我失望了，$n!', `MaleText_loc7`='Nada me gustaría más que romperle el cuello a esa bruja, pero alguien tiene que mantener a esos nagas lejos de ti...$b$b¡No me falles, $n!' WHERE `ID`=50003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 일 처리하고 애들 빼자고요. 다른 작전도 많이 수행해야 하니까요.', `MaleText_loc4`='我们赶快将这里清理干净，把这些小子弄出去。我还有事要做。', `MaleText_loc5`='把事情作個了結，讓這些傢伙出發去。我還有個任務在等著呢。', `MaleText_loc7`='Limpiemos esto y saquemos esos cuerpos de aquí. Tengo otra operación en ciernes.' WHERE `ID`=50004;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈것이 얌전히 당신을 기다리고 있답니다. 어서 여길 뜨자고요!', `FemaleText_loc4`='你的座驾已经准备好了，朋友。让我们离开这个地方！', `FemaleText_loc5`='兄弟，就等你了。快點上來我們閃人了吧!', `FemaleText_loc7`='Tu montura te espera, camarada. ¡Salgamos de este lugar!' WHERE `ID`=50005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 몰아치십시오, 친구여.$b$b저도 힘을 되찾는 대로 나아가겠습니다.', `MaleText_loc4`='继续前进吧，朋友。$b$b等我的力量恢复以后，我会自己出去的。', `MaleText_loc5`='繼續前進，朋友。$b$b等我力量恢復了，我會自己想辦法出去的。', `MaleText_loc7`='Sigue adelante, $gamigo:amiga;.$b$bEncontraré la forma de salir cuando recupere las fuerzas.' WHERE `ID`=50006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저곳으로 가셔서 우리 주민을 구해 주세요!', `FemaleText_loc4`='$n，你一定要去把我们的人救出来！', `FemaleText_loc5`='$n，你一定要到裡面去救出我們的人!', `FemaleText_loc7`='¡$n, tienes que entrar ahí y rescatar a nuestra gente!' WHERE `ID`=50007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고블린 좀비라고요? 상자 마을에 경고해야 해요!', `FemaleText_loc4`='地精僵尸？一定要警告胶囊镇！', `FemaleText_loc5`='哥布林殭屍?要趕快警告盒中鎮!', `FemaleText_loc7`='¿Goblins zombis? ¡Tenemos que avisar a la Ciudad de Bolsillo!' WHERE `ID`=50008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 출발!', `MaleText_loc4`='好啊！我们走。', `MaleText_loc5`='好!我們走了。', `MaleText_loc7`='¡Sí! Nos vamos.' WHERE `ID`=50009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가뿐하죠... 안 그런가요...', `MaleText_loc4`='这……容易……', `MaleText_loc5`='慢慢...好的...', `MaleText_loc7`='Tranquilo... lo hace...' WHERE `ID`=50010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 좋습니다. 전 비행기 오래 타는 거 싫어한다고요. 그래서 보조 가열기에 불을 붙여 연료를 한 방에 전부 태워버릴 겁니다.', `MaleText_loc4`='告诉你，我要对燃烧引擎进行一次大改造，让它能一次烧光我们全部的燃料储备，把我们一下子轰到目的地去 ！', `MaleText_loc5`='好的。我最討厭長途飛行了，所以我要後燃器全開，一趟就把燃料給燒光光。', `MaleText_loc7`='Bien. Odio los vuelos muy largos en avión. Así que voy a echar mano de todos los repuestos de reactores y prenderé todos nuestros suministros de combustible de una sola vez.' WHERE `ID`=50011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 하시든 간에... 정신은 잃지 마세요!', `MaleText_loc4`='无论怎样……你可不要晕过去！', `MaleText_loc5`='隨便。只要你...別。昏。倒!', `MaleText_loc7`='Hagas lo que hagas... ¡No te desmayes!' WHERE `ID`=50012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀비는 느려요. 그놈들 사이로 곧장 뛰어들어갈 필요는 없지요. 놈들이 $n 님의 뇌를 먹어치우지 않게 조심하세요.', `FemaleText_loc4`='那些僵尸的速度很慢。你不必一直冲到他们里面去就能把他们逐一打倒。小心不要让他们吃到你的脑子，$n！', `FemaleText_loc5`='殭屍動作很慢，小心避開他們，別讓他們把你的腦子給吃了，$n!', `FemaleText_loc7`='Esos zombis son muy lentos. No hace falta que corras entre ellos. ¡No dejes que se te coman el cerebro, $n!' WHERE `ID`=50013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와줄까, $n?', `MaleText_loc4`='我能为你做些什么，$n？', `MaleText_loc5`='我能為你做什麼嗎，$n?', `MaleText_loc7`='¿Qué puedo hacer por ti, $n?' WHERE `ID`=50014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와줄까, $n? 훈련이 필요해?', `MaleText_loc4`='我能为你做些什么，$n？需要进行训练吗？', `MaleText_loc5`='我能為你做什麼嗎，$n?需要訓練?', `MaleText_loc7`='¿Qué puedo hacer por ti, $n? ¿Necesitas instrucción?' WHERE `ID`=50015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 좀비라고?$B$B그런데 훈련이 필요해?', `MaleText_loc4`='哦，僵尸？$B$B需要进行训练吗？', `MaleText_loc5`='天啊，殭屍?$B$B需要訓練?', `MaleText_loc7`='Oh, venga, ¿zombis?$B$B¿Necesitas instrucción?' WHERE `ID`=50016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 희생이 없진 않았지만, 헬스크림 님께서 나가 장군을 처치한 사실을 아시면 기뻐하실 걸세.', `MaleText_loc4`='虽然我们在这里蒙受了巨大的损失，但地狱咆哮知道纳迦将军被我们打败了，一定会很高兴的。', `MaleText_loc5`='雖然損失慘重，但是我們總算擊敗了納迦將軍，地獄吼還是會很滿意的。', `MaleText_loc7`='A pesar de nuestras bajas, Grito Infernal estará satisfecho al oír que hemos derrotado al general naga.' WHERE `ID`=50017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 좀비라고?', `MaleText_loc4`='哦，僵尸？', `MaleText_loc5`='天啊，殭屍?', `MaleText_loc7`='Oh, vaya, ¿zombis?' WHERE `ID`=50018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 잃은 것이 많지만, 어쨌든 나가 장군을 처치했으니 폐하께서 기뻐하실 것입니다.', `MaleText_loc4`='尽管我们的许多战士牺牲了，但国王如果知道我们击败了纳迦将军，一定会很高兴的。', `MaleText_loc5`='雖然損失慘重，但是我們總算擊敗了納迦將軍，國王還是會很滿意的。', `MaleText_loc7`='A pesar de nuestras bajas, el Rey estará satisfecho al oír que hemos derrotado al general naga.' WHERE `ID`=50019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 상자 마을을 멋지게 설치해줬더군.$B$B그런데. 훈련은 필요하지 않아?', `MaleText_loc4`='胶囊镇已经成功地安置下来了，$n。$B$B需要进行训练吗？', `MaleText_loc5`='設置盒中鎮幹得好，$n。$B$B需要點什麼訓練嗎?', `MaleText_loc7`='Buen trabajo desplegando la Ciudad de Bolsillo, $n.$B$B¿Necesitas instrucción?' WHERE `ID`=50020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 상자 마을을 멋지게 설치해줬더군.', `MaleText_loc4`='胶囊镇已经成功地安置下来了，$n。', `MaleText_loc5`='設置盒中鎮幹得好，$n。', `MaleText_loc7`='Buen trabajo desplegando la Ciudad de Bolsillo, $n.' WHERE `ID`=50021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 좀비 녀석들은 너무 느려. 이건 다 이긴 싸움이나 마찬가지야!$B$B떠나기 전에 훈련은 필요하지 않아?', `MaleText_loc4`='那些僵尸的速度很慢。射击他们就像打火鸡一样容易！$B$B现在你需要进行训练吗？', `MaleText_loc5`='殭屍動作超慢的，簡直比打火機還簡單!$B$B出發前要接受點什麼訓練嗎?', `MaleText_loc7`='Los zombis son tan lentos. ¡Eso de ahí fuera es un tiro al plato!$B$B¿Necesitas instrucción antes de que salgas ahí fuera?' WHERE `ID`=50022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 좀비 녀석들은 너무 느려. 이건 다 이긴 싸움이나 마찬가지야!', `MaleText_loc4`='那些僵尸的速度很慢。射击他们就像打火鸡一样容易！', `MaleText_loc5`='殭屍動作超慢的，簡直比打火雞還簡單!', `MaleText_loc7`='Los zombis son tan lentos. ¡Eso de ahí fuera es un tiro al plato!' WHERE `ID`=50023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 마을이라니. 멋져!$B$B$n, 훈련을 받고 싶지는 않아?', `MaleText_loc4`='一个胶囊镇，太好了！$B$B需要进行训练吗，$n？', `MaleText_loc5`='盒中鎮。太好了!$B$B需要什麼訓練嗎，$n?', `MaleText_loc7`='Una Ciudad de Bolsillo. ¡Bien!$B$B¿Necesitas instrucción, $n?' WHERE `ID`=50024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 마을이라니. 멋져!', `MaleText_loc4`='一个胶囊镇，太好了！', `MaleText_loc5`='盒中鎮。太好了!', `MaleText_loc7`='Una Ciudad de Bolsillo. ¡Bien!' WHERE `ID`=50025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계 주변에서는 조심하라고, $c 친구.', `MaleText_loc4`='我在那台机器旁边总是会保持十二分的小心，$c。', `MaleText_loc5`='我在那台機器的旁邊會特別小心，$c。', `MaleText_loc7`='Yo tendría cuidado cerca de esa máquina, $c.' WHERE `ID`=50026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해, 지난번에 기계를 사용한 $r처럼 되고 싶지 않으면 말이야.', `MaleText_loc4`='小心，上一个使用那台机器的$r结局相当悲惨，你可不要步他的后尘。', `MaleText_loc5`='小心點，你不會想變得跟上個用這台機器的$r一樣。', `MaleText_loc7`='Cuidado, no querrás terminar como $gel:la; $r que utilizó la máquina.' WHERE `ID`=50027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 기계는 쓰레기나 마찬가지야. 기계를 사용한 뒤 응급치료가 필요하거든 내게로 와, $c 친구.', `MaleText_loc4`='那台机器简直就是一堆垃圾。你用过它之后，可以到我这里来接受紧急治疗服务，$c。', `MaleText_loc5`='那台機器根本是垃圾。等你用好以後要治傷再來找我，$c。', `MaleText_loc7`='La máquina es un montón de chatarra. Pero una vez termines de utilizarla, ven a verme para lo que necesites relacionado con primero auxilios, $c.' WHERE `ID`=50028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 저 고장난 기계에 자네의 목숨과 팔다리를 걸 작정인가? 오그리마에는 훨씬 실력이 좋은 치료사들이 있을 텐데.', `MaleText_loc4`='你真的打算去鼓捣那台破烂机器，不惜拿自己的生命和肉体做赌注？在奥格瑞玛可是有许多可靠又可敬的训练师。', `MaleText_loc5`='你真的要冒生命危險去用那台該死的機器?奧格瑪還有其他名聲更好的訓練師。', `MaleText_loc7`='¿De verdad vas a arriesgar la vida y tus extremidades subiéndote a esa máquina hecha polvo? En Orgrimmar hay instructores mucho más reputados.' WHERE `ID`=50029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 감히 우리 고블린을 좀비로 바꾼 다음 고블린한테 던질 수 있어!$B$B저 위로 올라가서 그놈들 엉덩짝을 걷어차기 전에 훈련을 받아야 하지 않아?', `MaleText_loc4`='他们怎么敢把我们的人民变成僵尸，还让这些可怜人反过来攻击我们！$B$B你一定要去狠狠踢爆他们的屁股！在此之前，你需要进行训练吗？', `MaleText_loc5`='你竟敢把我們的人變成殭屍，然後來攻擊我們!$B$B出發去踹他們屁股之前，要先來點訓練嗎?', `MaleText_loc7`='¡Cómo se atreven a convertir a nuestra gente en zombis y a lanzarla contra nosotros!$B$B¿Necesitas instrucción antes de salir ahí a patearles el trasero?' WHERE `ID`=50030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 감히 우리 고블린을 좀비로 바꾼 다음 고블린한테 던질 수 있어!', `MaleText_loc4`='他们怎么敢把我们的人民变成僵尸，还让这些可怜人反过来攻击我们！', `MaleText_loc5`='你竟敢把我們的人變成殭屍，然後來攻擊我們!', `MaleText_loc7`='¡Cómo se atreven a convertir a nuestra gente en zombis y a lanzarla contra nosotros!' WHERE `ID`=50031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 타는 냄새가 나지 않아? 자네 신발은 확인해 봤나? 이 조각들을 맞출 수 있겠어, $c 친구?', `MaleText_loc4`='你闻到那股烧焦的气味了吗？有没有看到那双鞋？你能把这些线索拼合起来吗，$c？', `MaleText_loc5`='有沒有聞到燒焦味?有沒有看到鞋子?有沒有猜出來了，$c?', `MaleText_loc7`='¿Hueles la quemadura? ¿Ves los zapatos? ¿Puedes resolver este enigma, $c?' WHERE `ID`=50032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 응급치료 훈련을 받고 싶지 않은가? 만약 저 기계를 사용한다면, 자네에게 내 기술을 연습하게 될 거야, $c 친구.', `MaleText_loc4`='你确定不想进行急救训练？如果你真的用了那台机器，也许我能有机会在你身上实践一下我的技巧，$c。', `MaleText_loc5`='你確定真的不需要急救訓練?你要是用了那台機器，說不定我就有機會在你身上練習技能了，$c。', `MaleText_loc7`='¿Seguro que no necesitas instrucción en primeros auxilios? Si utilizas esa máquina puede que tenga la oportunidad de practicar mis habilidades contigo, $c.' WHERE `ID`=50033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 기계를 마지막으로 사용한 $c|1은;는; 장화가 그만...아니, 저 기계가 장화를 앗아가 버렸지.', `MaleText_loc4`='最后使用那台机器的$c只留下了靴子……或者不如说，是那台机器只留下了他们的靴子。', `MaleText_loc5`='上個使用那台機器的$c被踹了...或者說，那台機器弄走了他們的鞋子。', `MaleText_loc7`='$gEl último:La última; $c que utilizó esa máquina recibió una patada... ¡Y la máquina se quedó sus botas!' WHERE `ID`=50034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 시도해 봐야 합니다.', `MaleText_loc4`='我们需要再试一次。', `MaleText_loc5`='我們需要再試一次。', `MaleText_loc7`='Tenemos que darle otra oportunidad.', `FemaleText_loc1`='다시 한 번 시도해 봐야 해요.', `FemaleText_loc4`='我们需要再试一次。', `FemaleText_loc5`='我們需要再試一次。', `FemaleText_loc7`='Tenemos que darle otra oportunidad.' WHERE `ID`=50035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장화는 만지지 마! 당국에서 나오거든 보여주려고 증거를 수집하고 있거든.', `MaleText_loc4`='不要碰这些靴子！我正在等待权威人士来此收集证据。', `MaleText_loc5`='不要碰那雙靴子!我在等有關當局過來收集證物。', `MaleText_loc7`='¡No toques esas botas! Estoy esperando que aparezcan las autoridades para recoger las pruebas.' WHERE `ID`=50036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='융합 핵의 안정된 상태를 유지하는 데 제 처리 능력을 모두 동원하고 있습니다.$B$B부동 소수점 오류가 지난번 정비 기간에 처리되었길 바랍니다.', `MaleText_loc4`='保持聚变核心的稳定几乎耗尽了我的全部计算能力。$B$B现在我们只能希望那个浮点错误已经在我的上一次维护周期中被排除了。', `MaleText_loc5`='要讓核融合核心保持穩定已經佔去了我近乎所有的計算資源。$B$B希望上次維修的時候有正確解決掉浮點運算的錯誤。', `MaleText_loc7`='Mantener estable el núcleo de fusión me exige todos mis poderes computacionales.$B$BEsperemos que ese error de punto flotante se arreglara durante mi último ciclo de mantenimiento.' WHERE `ID`=50037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 마을이라니. 우린 세상에서 제일 위대한 땜장이가 아닐까?$B$B젊은 후배님, 훈련 좀 받아보겠어?', `MaleText_loc4`='一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？$B$B需要进行训练吗？我年轻的追随者？', `MaleText_loc5`='一座盒中鎮。你說我們是不是全世界最偉大的工匠啊?$B$B小學徒，需要什麼訓練嗎?', `MaleText_loc7`='Una Ciudad de Bolsillo. ¿Acaso no somos los mayores manitas de todo el mundo?$B$B¿Necesitas instrucción, mi joven $gprotegido:protegida;?' WHERE `ID`=50038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자 마을이라니. 우린 세상에서 제일 위대한 땜장이가 아닐까?', `MaleText_loc4`='一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？', `MaleText_loc5`='一座盒中鎮。你說我們是不是全世界最偉大的工匠啊?', `MaleText_loc7`='Una Ciudad de Bolsillo. ¿Acaso no somos los mayores manitas de todo el mundo?' WHERE `ID`=50039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 잘 만들었는데!', `MaleText_loc4`='真是出类拔萃的工艺！', `MaleText_loc5`='做得真棒!', `MaleText_loc7`='¡Eso es un buen trabajo!' WHERE `ID`=50040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음...흥미로운 부품을 사용했군.', `MaleText_loc4`='嗯……这样选择零件可真有趣。', `MaleText_loc5`='嗯...選用的零件很有意思。', `MaleText_loc7`='Hmm... Una interesante selección de piezas.' WHERE `ID`=50041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 이런 게 한 대 있으면 좋겠구먼!', `MaleText_loc4`='孩子，真希望我也有这样的座驾！', `MaleText_loc5`='啊，真希望以前我也能體驗一下!', `MaleText_loc7`='¡Tío, ojalá pudiera tener una montura como esa!' WHERE `ID`=50042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녀석은 오크의 힘을 가진 게 틀림없어.', `MaleText_loc4`='我打赌，这个孩子体内流淌着真正的兽人热血。', `MaleText_loc5`='我敢打賭這寶貝裡頭一定有什麼真正的獸人動力。', `MaleText_loc7`='Apuesto a que esta belleza tiene algo de poder orco real en su interior.' WHERE `ID`=50043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승차감이 좋을 것 같진 않지만, 밖에서 보기엔 멋지겠는걸.', `MaleText_loc4`='也许这样的座驾不会那么容易驾驭，但我打赌，它绝不会让你失望。', `MaleText_loc5`='這一趟應該不會太舒服平穩，可是我看起來一定很酷。', `MaleText_loc7`='Bueno, quizá no sea un viaje guapo, pero desde luego sí que pareceré un guaperas en esta montura.' WHERE `ID`=50044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃발 모양이 멋지군. 장식만 몇 개 더 추가하면 눈에 확 띄는 로켓이 되겠어.', `MaleText_loc4`='我们的成绩不错。我打赌，只要再增加一些部件，这支火箭一定能成为万众瞩目的焦点。', `MaleText_loc5`='這根旗子真的不錯。我敢說，再加幾個配件的話，這個火箭一定會更拉風。', `MaleText_loc7`='La bandera es un buen detalle. Apuesto a que unos cuantos accesorios más harían que este cohete llamara mucho la atención.' WHERE `ID`=50045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 좀비라고? 고블린 좀비라니! 저 소인족들 다 결딴내 버리라고, $n!$B$B떠나기 전에 훈련받고 싶나?', `MaleText_loc4`='地精僵尸？地精僵尸！$n，去消灭那些俾格米人！$B$B在你出发前，需要进行一些训练么？', `MaleText_loc5`='哥布林殭屍?哥布林殭屍!幹掉那些俾格米侏儒，$n!$B$B出發前需要什麼訓練嗎?', `MaleText_loc7`='¿Goblins zombis? ¡Goblins zombis! ¡Destroza a esos pigmeos, $n!$B$B¿Necesitas instrucción antes de que vayas?' WHERE `ID`=50046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 좀비라고? 고블린 좀비라니! 저 소인족들 다 결딴내 버리라고, $n!', `MaleText_loc4`='地精僵尸？地精僵尸！$n，去消灭那些俾格米人！', `MaleText_loc5`='哥布林殭屍?哥布林殭屍!幹掉那些俾格米侏儒，$n!', `MaleText_loc7`='¿Goblins zombis? ¡Goblins zombis! ¡Destroza a esos pigmeos, $n!' WHERE `ID`=50047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 계속 굴러가게 하는 일이니 멋지고 말고요!', `FemaleText_loc4`='干得漂亮，$n。是你让这个地方活起来了！', `FemaleText_loc5`='你把這地方弄起來了!做得好，$n!', `FemaleText_loc7`='¡Has hecho un buen trabajo haciendo que este lugar siga en marcha, $n!' WHERE `ID`=50048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 이 소인족 좀 어떻게 해 보세요!', `FemaleText_loc4`='一定要对那些俾格米人采取行动，$n！', `FemaleText_loc5`='你一定要想辦法解決這些俾格米侏儒，$n!', `FemaleText_loc7`='¡Tienes que hacer algo respecto a esos pigmeos, $n!' WHERE `ID`=50049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님을 찾으려고 애쓰는 이들에게 원하는 건 무엇이든 요구하던 때가 있었습니다. 하지만 지금은 스승님께서 아무나 수습생으로 받아들이시는 바람에 그들은 원하는 대로 스승님의 차원문을 들락거리고 있지요.$B$B제게는 상당히 거슬리는 일입니다만, 스승님의 명령에 거역할 생각은 없습니다. 그저 당신이 입고 있는 우스운 옷이나 그 한심한 면상을 보면서 즐거워할 따름이지요. 그것도 이젠 슬슬 질려갑니다...$B$B이렇게 수다를 떠는 것조차도 지겹다고요! 눈앞에서 당장 사라지십시오. 그 우울한 옷차림은 다른 사람한테나 가서 자랑하란 말입니다.', `MaleText_loc4`='曾经有一段时间，我可以对那些想要见我主人的家伙们予取予求。但现在，我的主人会接纳任何想成为他学生的人。他们能够通过他的传送门随意往来。$B$B我不会质疑他的命令，但这实在让我感到很苦恼。现在我的乐趣只剩下了让你们穿上可笑的衣服，或者看看你们的那副可怜相。但这些也已经让我感到无聊了……$B$B我对这种生活感到极度厌烦！走吧，赶快走。和别人去分享你的郁闷心情吧。', `MaleText_loc5`='以前呢，對那些要來找我主人的傢伙我隨便跟他們要什麼都可以。可是現在，他幾乎每個人都肯收為學徒，而且他們還可以自由使用他的傳送門。$B$B雖然我很不開心，可是我又不能質疑他的命令，所以我只能苦中作樂，嘲笑你身上怪裡怪氣的衣服，還有你一臉倒楣相的表情。不過那還是很無聊...$b$b連這樣跟你講話都很無聊!去去去!去找別人分享你差勁透頂的時尚品味。', `MaleText_loc7`='Hubo un tiempo en el que podía pedir lo que quisiera a aquellos que buscaban a mi maestro. Pero ahora, el maestro acepta a todo el mundo como aprendiz y pueden atravesar sus portales todas las veces que quieran.$B$BPara mí es molesto, pero no cuestiono sus órdenes. Ahora solo puedo solazarme riéndome de las ridículas prendas que ustedes visten o burlándome de sus patéticas expresiones. Pero incluso eso me aburre... $B$B¡Incluso esta charla me aburre! Vete. Largo. Comparte tu deprimente sentido de la estética con cualquier otro.' WHERE `ID`=50050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 조성하는 데 비용은 얼마나 청구하셨나요?$B$B수련에 돈 좀 써보시지 않겠어요?', `FemaleText_loc4`='你打算在这个地方花多少钱？$B$B想不想在训练方面进行一些消费？', `FemaleText_loc5`='弄這個地方你收了多少錢?$B$B要不要花點錢來學學東西?', `FemaleText_loc7`='¿Cuánto has cobrado por desplegar este sitio?$B$B¿Quieres gastar algo de esa pasta en instrucción?' WHERE `ID`=50051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 조성하는 데 비용은 얼마나 청구하셨나요?', `FemaleText_loc4`='你打算在这个地方花多少钱？', `FemaleText_loc5`='弄這個地方你收了多少錢?', `FemaleText_loc7`='¿Cuánto has cobrado por desplegar este sitio?' WHERE `ID`=50052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고블린이었든 아니든, 좀비란 성스러운 빛이 보기에는 혐오스러운 존재일 뿐이에요. 게다가, 그놈들에게선 한 푼도 안 나오거든요.$B$B지금까지는 나온 게 없어요.$B$B수련이 필요하신가요, $n 님?', `FemaleText_loc4`='不管是否产生于地精，僵尸在圣光的眼中永远都是憎恶的存在。而且，你绝对不可能和他们做买卖。$B$B至少现在还不行。$B$B需要进行训练吗，$n？', `FemaleText_loc5`='不管是哥布林或殭屍，在聖光的眼裡就是一種怪物。再說，它們根本沒有賺頭。$B$B至少現在還沒有。$B$B需要訓練嗎，$n?', `FemaleText_loc7`='Los zombis, sean goblins o no, son una abominación a los ojos de la Luz. Además, no se pueden sacar beneficios de ellos.$B$BAl menos, por ahora no.$B$B¿Necesitas instrucción, $n?' WHERE `ID`=50053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고블린이었든 아니든, 좀비란 성스러운 빛이 보기에는 혐오스러운 존재일 뿐이에요. 게다가, 그놈들에게선 한 푼도 안 나오거든요.$B$B지금까지는 나온 게 없어요.', `FemaleText_loc4`='不管是否产生于地精，僵尸在圣光的眼中永远都是憎恶的存在。而且，你绝对不可能和他们做买卖。$B$B至少现在还不行。', `FemaleText_loc5`='不管是哥布林或殭屍，在聖光的眼裡就是一種怪物。再說，它們根本沒有賺頭。$B$B至少現在還沒有。', `FemaleText_loc7`='Los zombis, sean goblins o no, son una abominación a los ojos de la Luz. Además, no se pueden sacar beneficios de ellos.$B$BAl menos, por ahora no.' WHERE `ID`=50054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오지 한복판에 도회지를 조성하다니. 멋져요!$B$B그런데 $n 님, 훈련이 필요하신가요?', `FemaleText_loc4`='荒野之中的城镇。我喜欢这样！$B$B需要进行训练吗，$n？', `FemaleText_loc5`='在荒郊野外弄出一座小城。我喜歡!$B$B需要什麼訓練嗎，$n?', `FemaleText_loc7`='Desplegar un paisaje urbano en medio de la naturaleza salvaje. ¡Me encanta!$B$B¿Necesitas instrucción, $n?' WHERE `ID`=50055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오지 한복판에 도회지를 조성하다니. 멋져요!', `FemaleText_loc4`='荒野之中的城镇。我喜欢这样！', `FemaleText_loc5`='在荒郊野外弄出一座小城。我喜歡!', `FemaleText_loc7`='Desplegar un paisaje urbano en medio de la naturaleza salvaje. ¡Me encanta!' WHERE `ID`=50056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북동쪽으로 가면 어글을 찾을 수 있습니다. 이걸로 만을 더 빠르게 건너실 수 있을 겁니다.', `MaleText_loc4`='你可以在东北方找到厄格尔罗。这样你就能更快地跨越这道海湾了。', `MaleText_loc5`='你可以在東北邊找到厄爾勾。這應該可以幫你更快跨越海灣。', `MaleText_loc7`='Encontrarás a Ergll al noreste. Esto te ayudará a cruzar más rápido la bahía.' WHERE `ID`=50057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몰래 좀비에 접근할 수 있겠어요? 가까이 가면 당신 뇌 냄새를 맡지 않을까요?$B$B이 근처에 있는 이들 절반에게는 걱정할 뇌가 아예 없지만요.$B$B$n 님, 수련이 필요하세요?', `FemaleText_loc4`='你能不能在暗中靠近僵尸？难道当你靠近的时候，他们闻不到你脑子的气味ie？$B$B不过，这里大概有半数人已经不必担心这种事了。$B$B需要进行训练吗，$n？', `FemaleText_loc5`='你有辦法潛行接近殭屍嗎?靠近的時候它們不是會聞到你腦漿的味道嗎?$B$B不過，這邊大概有一半的人不用煩惱這個問題。$B$B需要訓練嗎，$n?', `FemaleText_loc7`='¿Puedes acercarte sigilosamente a los zombis? ¿No huelen tu cerebro nada más acercarte?$B$BEntonces la mitad de la gente que anda por aquí no tiene que preocuparse de nada.$B$B¿Necesitas instrucción, $n?' WHERE `ID`=50058;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몰래 좀비에 접근할 수 있겠어요? 가까이 가면 당신 뇌 냄새를 맡지 않을까요?$B$B이 근처에 있는 이들 절반에게는 걱정할 뇌가 아예 없지만요.', `FemaleText_loc4`='你能不能在暗中靠近僵尸？难道当你靠近的时候，他们闻不到你脑子的气味ie？$B$B不过，这里大概有半数人已经不必担心这种事了', `FemaleText_loc5`='你有辦法潛行接近殭屍嗎?靠近的時候它們不是會聞到你腦漿的味道嗎?$B$B不過，這邊大概有一半的人不用煩惱這個問題。', `FemaleText_loc7`='¿Puedes acercarte sigilosamente a los zombis? ¿No huelen tu cerebro nada más acercarte?' WHERE `ID`=50059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01은 현재 작동하지 않습니다.', `MaleText_loc4`='全能战士NX-01型处于离线状态。', `MaleText_loc5`='自動戰士NX-01休眠中。', `MaleText_loc7`='Guerreromática NX-01 desconectada.' WHERE `ID`=50060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01이 부셔졌습니다!$B$B훈련을 더 받으려면 동전을 넣어 주십시오.', `MaleText_loc4`='全能战士NX-01型毁坏！$B$B塞进钱币，获取更多训练。', `MaleText_loc5`='自動戰士NX-01摧毀!$B$B請投入錢幣以進行訓練。', `MaleText_loc7`='¡Guerreromática NX-01, destruye!$B$BInserta monedas para recibir más instrucción sobre cómo dar órdenes.' WHERE `ID`=50061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01이 작동 중입니다.$B$B훈련을 더 받으려면 동전을 넣어 주십시오.', `MaleText_loc4`='全能战士NX-01型联线运行中！$B$B塞进钱币，获取更多训练。', `MaleText_loc5`='自動戰士NX-01啟動。$B$B請投入錢幣以進行訓練。', `MaleText_loc7`='Guerreromática NX-01 conectada.$B$BInserta monedas para recibir más instrucción sobre cómo dar órdenes.' WHERE `ID`=50062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로봇전사 NX-01은 현재 작동하지 않습니다.', `MaleText_loc4`='全能战士NX-01型处于离线状态。', `MaleText_loc5`='自動戰士NX-01休眠中。', `MaleText_loc7`='Guerreromática NX-01 desconectada.' WHERE `ID`=50063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깡패 같은 언데드 몇 놈 때문에 피신하기엔 여기에 너무 많은 걸 쏟아부었어.', `MaleText_loc4`='我已经走了这么远，绝不可能被几个亡灵混混吓退。', `MaleText_loc5`='我已經走到這一步了，不可能因為一些不死的怪物就放棄。', `MaleText_loc7`='He llegado demasiado lejos como para dejar que me persiga un puñado de matones no-muertos.', `FemaleText_loc1`='깡패 같은 언데드 몇 놈 때문에 피신하기엔 여기에 너무 많은 걸 쏟아부었어.', `FemaleText_loc4`='我已经走了这么远，绝不可能被几个亡灵混混吓退。', `FemaleText_loc5`='我已經走到這一步了，不可能因為一些不死的怪物就放棄。', `FemaleText_loc7`='He llegado demasiado lejos como para dejar que me persiga un puñado de matones no-muertos.' WHERE `ID`=50064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 비판할 줄 모르는 사람이 어딨겠어요, 아가씨들.', `MaleText_loc4`='女士们，每个人都可以有自己的看法。', `MaleText_loc5`='女士們，人人都是評論家。', `MaleText_loc7`='Todo el mundo sabe criticar, señoras.' WHERE `ID`=50065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천재란, 아무리 이상한 행동을 해도 감수할 줄 알아야 하죠.', `MaleText_loc4`='一个天才应该容忍别人的怪异举动。', `MaleText_loc5`='當你是天才，你就得忍受許多詭異的舉動。', `MaleText_loc7`='Cuando eres genio, tienes que aguantar un montón de cosas extrañas.' WHERE `ID`=50066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 얼마나 오랫동안 언데드의 공격을 버틸 수 있을지 알고 싶군.', `MaleText_loc4`='我想看看，在亡灵的连续攻势前，我能坚持多久。', `MaleText_loc5`='我想看看我能抵擋幾波不死的怪物。', `MaleText_loc7`='Quiero ver cuánto puedo aguantar contra oleadas de no-muertos.', `FemaleText_loc1`='내가 얼마나 오랫동안 언데드의 공격을 버틸 수 있을지 알고 싶군.', `FemaleText_loc4`='我想看看，在亡灵的连续攻势前，我能坚持多久。', `FemaleText_loc5`='我想看看我能抵擋幾波不死的怪物。', `FemaleText_loc7`='Quiero ver cuánto puedo aguantar contra oleadas de no-muertos.' WHERE `ID`=50067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮아요, 아가씨들...괜찮아요. 저 생물의 정수를 이미 제 그림에 담아냈어요.', `MaleText_loc4`='女士们，女士们……就是这样。我已经在我的绘画中捕捉到了那头怪物的精髓。', `MaleText_loc5`='女士們，女士們...不會怎樣的。我已經把這隻生物的精神捕捉在我的畫作裡。', `MaleText_loc7`='Señoras, señoras... Todo irá bien. Ya he capturado la esencia de la criatura en mi cuadro.' WHERE `ID`=50068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정들 마세요. 그저 제 그림을 바라보면서 예전의 좋은 시절을 떠올리든지, 아니면 절 바라보면서 행복한 미래를 꿈꿀 수도 있지 않겠어요?', `MaleText_loc4`='只需要这样就好，女士们。只要看看我的绘画，回忆一下那些更加美好的日子。或者你们可以看看我，想象一下更加美好的未来。', `MaleText_loc5`='沒事的，女士們。只要看看我的畫作，想想過去美好的日子。或者，只要看看我，想想未來美好的日子。', `MaleText_loc7`='Todo irá bien, señoras. Mirad mi cuadro y recordad días mejores. O simplemente podéis mirarme a mí e imaginar un futuro mejor.' WHERE `ID`=50069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 자신의 의견을 표현하는 방법 중 하나일 뿐이에요.', `MaleText_loc4`='嗯，这是你表达观点的一种方法。', `MaleText_loc5`='好吧，那也算是發表你意見的一種方法。', `MaleText_loc7`='Bueno, eso es una forma de dar tu opinión.' WHERE `ID`=50070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가씨들, 제발. 멧돼지는 제 작품 속에 살아 있다니까요? 작품을 보고 감동해서 그런 게 아니라면, 제발 울지 마세요.', `MaleText_loc4`='女士们，请注意，这头野猪将活在我的艺术中。请不要再抛洒泪水了，除非你们是被我的作品所感动。', `MaleText_loc5`='女士們，請聽我說。這隻野豬會繼續活在我的藝術裡。請不要再滴下任何一滴眼淚，除非是因為我的藝術感動了你。', `MaleText_loc7`='Señoras, por favor. El jabalí vivirá en mi arte. Por favor, no derraméis ni una lágrima más a no ser que sea mi arte el que os mueva a hacerlo.' WHERE `ID`=50071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 가서 좀비 놈들에게 빌지워터 해적구단의 맛을 제대로 보여주라고!', `MaleText_loc4`='去向那些僵尸展示一下锈水海盗队的精神，孩子！', `MaleText_loc5`='孩子，過去讓那些殭屍見識污水海盜隊的本事!', `MaleText_loc7`='¡Entra ahí y enseña a esos zombis de qué está hecho el Cártel Pantoque, $gchaval:chavala;!' WHERE `ID`=50072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 놀라운걸!', `FemaleText_loc4`='真是惊人啊！', `FemaleText_loc5`='太神奇了!', `FemaleText_loc7`='¡Es alucinante!' WHERE `ID`=50073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실물과 똑같아!', `FemaleText_loc4`='真是栩栩如生！', `FemaleText_loc5`='好逼真啊!', `FemaleText_loc7`='¡Parece que está vivo!' WHERE `ID`=50074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='완전히 똑같네!', `FemaleText_loc4`='简直和活的一样！', `FemaleText_loc5`='好像喔!', `FemaleText_loc7`='¡Es igualito!' WHERE `ID`=50075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아름다워!', `FemaleText_loc4`='真美啊！', `FemaleText_loc5`='真漂亮!', `FemaleText_loc7`='¡Es precioso!' WHERE `ID`=50076;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='충격적이야!', `FemaleText_loc4`='绝对是震古烁今的作品！', `FemaleText_loc5`='實在太驚人了!', `FemaleText_loc7`='¡Absolutamente asombroso!' WHERE `ID`=50077;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='색이 살아 있어!', `FemaleText_loc4`='这些色彩实在是太生动了！', `FemaleText_loc5`='好生動的色彩!', `FemaleText_loc7`='¡Los colores son tan alegres!' WHERE `ID`=50078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제까지 저렇게 아름다운 건 본 적이 없어!', `FemaleText_loc4`='我这一辈子都没有见过这么美的东西！', `FemaleText_loc5`='這輩子從來沒看過這麼美麗的東西!', `FemaleText_loc7`='¡Nunca he visto algo tan hermoso en toda mi vida!' WHERE `ID`=50079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 제 초상화도 그려줘요, 서지.', `FemaleText_loc4`='萨德希，我真想让你给我画幅像。', `FemaleText_loc5`='沙德希，你也該畫畫我。', `FemaleText_loc7`='Alguna vez deberías pintarme a mí, Sudsy.' WHERE `ID`=50080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊지 말고 소인족 지도자를 찾아봐. 가알, 말모, 텔로크야.', `MaleText_loc4`='记住，一定要找到那些俾格米头领：加奥、马奥默和塔卢可。', `MaleText_loc5`='別忘了，那三個俾格米首領:嘎爾，瑪爾摩，還有泰洛須。', `MaleText_loc7`='Recuerda, busca a los líderes de los pigmeos: Gaahl, Malmo y Teloch.' WHERE `ID`=50081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='땅에서 빛이 나는 흙더미를 찾아보세요.', `FemaleText_loc4`='在地面上寻找一堆堆发光的东西。', `FemaleText_loc5`='注意地上一堆堆會發亮的東西。', `FemaleText_loc7`='Busca en el suelo montones de materia brillante.' WHERE `ID`=50082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장화가 맘에 쏙 들 거야!', `MaleText_loc4`='你一定会爱上这个的！', `MaleText_loc5`='你一定會愛上這個!', `MaleText_loc7`='¡Esto te va a encantar!' WHERE `ID`=50083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈노츠는 정신이 나갔소! 난 절대 돌아가지 않겠어!', `MaleText_loc4`='那个司克诺兹是个疯子！我绝对不会回去！', `MaleText_loc5`='那個舒諾茲是瘋子!我永遠都不要回去!', `MaleText_loc7`='¡Ese Schnottz está loco! ¡Nunca pienso regresar!' WHERE `ID`=50084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그런 표정입니까? 당신이 조종했으면 더 잘했을 것 같아요?', `MaleText_loc4`='哦，难道你能做得更好吗？', `MaleText_loc5`='哦，說得好像你更厲害似的。', `MaleText_loc7`='Oh, ni que tú lo hubieras hecho mejor.' WHERE `ID`=50085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두를 필요 없다고. 자, 이 벌목기 장화를 뭐로 바꿀 수 있나 볼까? 흠.', `MaleText_loc4`='别着急，$g男孩:女孩;，现在，让我看看能怎样改造这台伐木机？嗯。', `MaleText_loc5`='慢慢來，$g小鬼:小女生;。好了，我能怎樣改造這雙伐木機靴呢?嗯。', `MaleText_loc7`='Tómate tu tiempo, $gmuchacho:muchacha;. Veamos, ¿en qué puedo convertir mi bota trituradora? Hmmm.' WHERE `ID`=50086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번에 로켓이 여러 발 발사되도록 장화포를 조정해뒀어. 대상 포착 설정은 완벽하게 해두었다고 자신해.', `MaleText_loc4`='我已经让这支地精火箭筒能够一次发射多枚火箭。相信我一定也能完美地校准它的瞄准系统。', `MaleText_loc5`='我已經有辦法讓靴箭筒一次射出好幾發火箭，而且我確定已經把瞄準系統調校得很完美了。', `MaleText_loc7`='He programado la botazuca para que lance varios cohetes por disparo. Estoy bastante seguro de que he calibrado el objetivo a la perfección.' WHERE `ID`=50087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $n.', `FemaleText_loc4`='你好，$n。', `FemaleText_loc5`='你好，$n。', `FemaleText_loc7`='Saludos, $n.' WHERE `ID`=50088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모은 용의 정수 모두... 그 힘이... 정말 기쁘게 해주는군!', `MaleText_loc4`='我已经收集了这么多龙类的精华……这种力量……真让人激动不已！', `MaleText_loc5`='我收集的所有龍之精華...這力量...太興奮了!', `MaleText_loc7`='Todas esas esencias de dragón que he recogido... el poder... ¡Resulta estimulante!' WHERE `ID`=50089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 이걸 빼앗아 갈 수는 없어! 지금도, 그리고 영원히!', `MaleText_loc4`='你不能把它拿走！任何时候都不能！', `MaleText_loc5`='你不能從我這裡奪走它!現在不行，永遠不行!', `MaleText_loc7`='¡No puedes quitarme esto! ¡Ni ahora, ni nunca!' WHERE `ID`=50090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플린트로크, 커다란 대포가 있다면 왜 그냥... 보통 대포알을 쏘지 않는 겁니까?', `MaleText_loc4`='弗林特洛克，如果我们有一门超级大炮，为什么我们不能……发射一颗炮弹？', `MaleText_loc5`='燧鎖，既然我們有這麼大個火砲，我們幹嘛不拿來發射...砲彈呢?', `MaleText_loc7`='Cierrasílex, si tenemos un enorme cañón gigante, ¿por qué no podemos disparar... una bala de cañón?' WHERE `ID`=50091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 여기 $p|1이;가; 나무 판때기를 와장창 조각내며 나타나서 아수라장 속에서 두 다리가 부러진 채로 갑판을 기어 다니기 시작한다고 생각해 보세요. 아무렴요. 놈들은 그런 건 상상도 못 할 겁니다!', `MaleText_loc4`='老$p曾经一下子轰碎了他们的船舱。让他们只能在硝烟、碎木和残骸中爬行。唉，他们可不会喜欢这样，绝对不会，长官！', `MaleText_loc5`='可是一旦$p轟穿了他們的船殼，木頭、鮮血還有黏液滿天飛、再用斷掉的雙腿爬上甲板的時候，哈哈，他們肯定料想不到會有這一招!', `MaleText_loc7`='Pero cuando $p, aquí presente, atraviese un mamparo en medio de una lluvia de astillas de madera, sangre y flema, y empiece a arrastrarse por la cubierta con ambas piernas rotas... Oh, sí, ¡ESO sí que no lo habrán visto venir, no señor!' WHERE `ID`=50092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 두 가지 특기가 있어. 작은 물건을 가져다가 크게 만들거나, 큰 걸 아주 작은 장소에 끼워 넣을 수 있다고.$b$b오늘은 어떤 게 필요한 거야?', `MaleText_loc4`='我主要研究两方面的问题：让微小的突然膨胀成巨大的；将巨大的放入微小的空间。$b$b今天你的需要又是什么？', `MaleText_loc5`='我的專長有兩項:把小東西爆炸變成大大的東西，還有把大東西弄進小小的地方。$b$b你今天需要哪一種?', `MaleText_loc7`='Me he especializado en dos cosas: en coger pequeñas cosas y hacerlas explotar en grandes cosas, y en hacer cosas grandes y que encajen en lugares minúsculos.$b$b¿Qué es lo que necesitas que haga hoy?' WHERE `ID`=50093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 죽은 오크를 위해 정의를 실현해 주세요.', `FemaleText_loc4`='为我们报仇，$n。', `FemaleText_loc5`='為我們的死者報仇，$n。', `FemaleText_loc7`='Reparte justicia por nuestros muertos, $n.' WHERE `ID`=50094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고블린 수류탄과 노움 지뢰의 한 판 대결이지요. $n 님, 누가 한 수 위인지 보여주세요!', `FemaleText_loc4`='地精手榴弹对地精陆战地雷。让他们看看谁更强，$n！', `FemaleText_loc5`='哥布林手榴彈對地精地雷。讓他們知道誰比較厲害，$n!', `FemaleText_loc7`='Granadas goblins contra minas terrestres gnomas. ¡Enséñales quién manda aquí, $n!' WHERE `ID`=50095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 죽은 자들을 대신해서 행동에 나서준 그대 덕에 우리는 명예를 얻었군요.', `FemaleText_loc4`='你为我们所做的一切，为我们带来了光荣，$n。', `FemaleText_loc5`='你為我們死者所做的事情令我們倍感榮幸，$n。', `FemaleText_loc7`='Nos honras con tus actos en nombre de nuestros muertos, $n.' WHERE `ID`=50096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깜빡했는데... 케잔에서 비행 수업은 들으셨던가요?', `FemaleText_loc4`='我忘记了……你在科赞上过飞行课吗？', `FemaleText_loc5`='我忘了...你在凱贊有沒有上過飛行課?', `FemaleText_loc7`='Lo he olvidado... ¿Diste lecciones de vuelo en Kezan?' WHERE `ID`=50097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소용없군요. 제 마법은 이 생물에 아무런 소용이 없습니다.', `FemaleText_loc4`='这没有用。我的魔法对这些怪物是无效的。', `FemaleText_loc5`='沒有用。我的魔法對這些生物毫無作用。', `FemaleText_loc7`='Ni sirve para nada. Mi magia no es efectiva con esas criaturas.' WHERE `ID`=50098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 서두르시는 게 좋겠어요. 붙잡혀 있는 이들이 어디 있는지 스랄 님이 아시나 봐요.', `FemaleText_loc4`='最好快一点，$n。我觉得那个萨尔应该知道大家都被囚禁在哪里。', `FemaleText_loc5`='動作快，$n。索爾好像有人被關在哪裡的消息。', `FemaleText_loc7`='Será mejor que te des prisa, $n. Creo que Thrall tiene noticias sobre dónde tienen retenida a nuestra gente.' WHERE `ID`=50099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달려라, 바스티아! $n|1을;를; 하늘 폭포와 노동광산으로 데려다 주려무나.', `MaleText_loc4`='快跑，巴斯蒂亚！带$n去天坠瀑布和矿坑。', `MaleText_loc5`='跑啊，巴斯堤亞!帶$n去天空瀑布和勞工礦坑。', `MaleText_loc7`='¡Corre, Bastia! ¡Lleva a $n a Cascadas del Cielo y a la Mina de Trabajos Forzados!' WHERE `ID`=50100;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넋이 나간 채 일을 계속하는 그릴리의 입에서 침이 약간 흘러내립니다.', `FemaleText_loc4`='格瑞里一边无意识地继续着劳作，一边说了一些昏乱的话。', `FemaleText_loc5`='格里利流了點口水，繼續做她的蠢工作。', `FemaleText_loc7`='Greely babea un poco mientras continúa con su mecánico trabajo.' WHERE `ID`=50101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 여기서 고블린을 구해내야 해요! 방법은 카자콜라 제로를 잔뜩 마시게 하는 거지요!', `FemaleText_loc4`='我们要让我们的人离开这里，$n！最关键的是要让他们喝下足够的卡亚零一度可乐！', `FemaleText_loc5`='我們得把我們的人從這裡弄走，$n!關鍵就是要他們喝下大量的卡迦可樂Zero-One!', `FemaleText_loc7`='¡Tenemos que sacar a nuestra gente de aquí, $n! ¡La clave está en hacerles beber un montón de Kaja''Cola Zero-Uno!' WHERE `ID`=50102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 북쪽 통로로 탈출해야 해요!', `FemaleText_loc4`='$n，我们需要从北部隧道逃出去！', `FemaleText_loc5`='$n，我們得從北方坑道逃出去!', `FemaleText_loc7`='¡$n, tenemos que escapar por el túnel del norte!' WHERE `ID`=50103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽉 잡으세요!', `FemaleText_loc4`='抓紧！', `FemaleText_loc5`='抓緊!', `FemaleText_loc7`='¡Aguanta!' WHERE `ID`=50104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스팀휘들 상어구단이 우리를 뭉개버리기 전에 처리해 주세요!', `FemaleText_loc4`='解决那些热砂港大鲨鱼队的队员，不要让他们碰到我们！', `FemaleText_loc5`='把熱砂鯊魚隊的傢伙解決掉，別讓他們給打敗了!', `FemaleText_loc7`='¡Líbrate de esos Tiburones Bonvapor antes de que nos derroten!' WHERE `ID`=50105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 궁극의 축구탄 제복을 만들어 주지. 하지만, 먼저 부품이 필요해. 아주 많이 말이야.', `MaleText_loc4`='孩子，我们会为你制造终极足球炸弹制服。但首先，我们需要 零件，非常非常多的零件。', `MaleText_loc5`='我們要幫你做一件足球炸彈戰鬥裝。但是首先，我們需要零件。很多的零件。', `MaleText_loc7`='Vamos a fabricarte el uniforme de bombalón supremo, $gchaval:chavala;. Pero primero, necesitamos las piezas. Un montón de piezas.' WHERE `ID`=50106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 자식이 그런 식으로 당신을 짓밟게 하면 안 되죠! 가서 마음을 훔쳐 오세요!', `FemaleText_loc4`='你不能让他就这样轻松地战胜你！孩子，你要直捣他的命门！', `FemaleText_loc5`='你不能就這樣放任他走掉!女孩，去把他的心搶過來!', `FemaleText_loc7`='¡No puedes permitir que te pase por encima de esa forma! ¡Ve a por su corazón, muchacha!' WHERE `ID`=50107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈은 늘 마음에 안 들었어. 당신 여자친구를 훔쳤잖아. 아주 속이 시원하군!', `MaleText_loc4`='我从来都不喜欢那个家伙。他偷走了你的女朋友。不过要我说，这对你也算是一种解脱！', `MaleText_loc5`='我從來不喜歡那傢伙。他偷走了你的女朋友。走得好!', `MaleText_loc7`='Nunca me gustó ese tipo. Te robó a la novia. Yo le diría, ¡hasta nunca!' WHERE `ID`=50108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쓴맛을 좀 보여줄 시간이에요!', `FemaleText_loc4`='该是搞些破坏的时候了！', `FemaleText_loc5`='該來搞點小破壞啦!', `FemaleText_loc7`='¡Es hora de hacer un poco de sabotaje!' WHERE `ID`=50109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 축구탄 제복을 가동하려면 기름이 필요해. 그것도 아주 많이!', `MaleText_loc4`='如果我们要让我们的足球炸弹制服动起来，就需要很多油，孩子！', `MaleText_loc5`='孩子，我們需要油料、很多的油料，才有辦法讓你的戰鬥裝發揮作用!', `MaleText_loc7`='Necesitamos combustible, y un montón además, si queremos poner en marcha tu uniforme de bombalón, $gchaval:chavala;.' WHERE `ID`=50110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축구탄 제복을 노예 구덩이로 가져가세요. $n 님, 어서요!', `FemaleText_loc4`='把这件足球炸弹制服送到奴隶营去，快一点，$n！', `FemaleText_loc5`='把足球炸彈戰鬥裝送去奴隸之坑。動作快，$n!', `FemaleText_loc7`='Lleva el uniforme de bombalón a Los Pozos de Esclavos. ¡Rápido, $n!' WHERE `ID`=50111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='철창에 부착할 단식 보조 로켓이라니. 다음에 내가 뭘 생각해낼지 기대되는군. 정말 난 천재라니까!', `MaleText_loc4`='在笼子上安装推进火箭。我的下一个构想又会是什么？我真是个天才！', `MaleText_loc5`='幫籠子弄上增壓火箭。我還會再想出什麼?我真是天才!', `MaleText_loc7`='Cohetes propulsores para jaulas. ¿Qué será lo que se me ocurra a continuación? ¡Soy un genio!' WHERE `ID`=50112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용병만큼 싫은 게 또 없다고. 명예를 모르는 놈들이거든!', `MaleText_loc4`='我最恨的就是雇佣兵。他们没有半点荣誉感！', `MaleText_loc5`='我最痛恨的就是傭兵。他們毫無榮譽感可言!', `MaleText_loc7`='No hay nada que odie más que a los mercenarios. ¡No tienen honor!' WHERE `ID`=50113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='처음엔 칩이랑 사귀려고 당신을 차더니 이제는 무역왕에게 갔네요! 절대로 $n 님에게 어울리는 여자가 아니에요.', `FemaleText_loc4`='她先是丢下你，投进奇普的怀里。现在，她又成了贸易大王的人！$n，你是个好人，她配不上你。', `FemaleText_loc5`='她先是為了奇普拋棄你，然後現在又換成貿易親王!她反正本來就配不上你，$n。', `FemaleText_loc7`='¡Primero te dejó por Locko, y ahora por el Príncipe mercante! Nunca fue lo suficientemente buena para ti, $n.' WHERE `ID`=50114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='캔디가 당신 남자 친구를 빼앗았잖아요! 본때를 보여줘야죠!', `FemaleText_loc4`='女孩，她偷走了你的人！你知道该怎么做！', `FemaleText_loc5`='她偷走了你的人，女朋友!你知道你該做什麼!', `FemaleText_loc7`='¡Ella te robó el novio, amiga! ¡Ya sabes lo que tienes que hacer!' WHERE `ID`=50115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 승리 아니면 죽음이다!', `MaleText_loc4`='非胜即死，$c！', `MaleText_loc5`='勝利或死亡，$c!', `MaleText_loc7`='¡Victoria o muerte, $c!' WHERE `ID`=50116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 전장에서 발견한 부상당한 스톰윈드 보병에게 |cFFFFFFFF[마우스 오른쪽 클릭]|r 하십시오.', `MaleText_loc4`='[右键点击] |cFFFFFFFF你在北方战场找到的负伤的暴风城步兵。|r', `MaleText_loc5`='[右鍵點擊] |cFFFFFFFF你在北方戰場找到受傷的暴風城步兵。|r', `MaleText_loc7`='[Clic derecho] |cFFFFFFFFen los soldados de infantería de Ventormenta heridos que encuentres en el campo norte.|r', `FemaleText_loc1`='북쪽 전장에서 발견한 부상당한 스톰윈드 보병에게 |cFFFFFFFF[마우스 오른쪽 클릭]|r 하십시오.', `FemaleText_loc4`='[右键点击] |cFFFFFFFF你在北方战场找到的负伤的暴风城步兵。|r', `FemaleText_loc5`='[右鍵點擊] |cFFFFFFFF你在北方戰場找到受傷的暴風城步兵。|r', `FemaleText_loc7`='[Clic derecho] |cFFFFFFFFen los soldados de infantería de Ventormenta heridos que encuentres en el campo norte.|r' WHERE `ID`=50117;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무덤에서 일어나 어둠의 여왕님을 섬겨라!', `FemaleText_loc4`='从坟墓中站起，向黑暗女王效忠！', `FemaleText_loc5`='從墳裡爬出來效忠黑暗女王!', `FemaleText_loc7`='¡Álzate de la tumba y sirve a la Dama Oscura!' WHERE `ID`=50118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밴시 여왕이신 실바나스 님의 이름으로... 네게 이 선물을 주겠다!', `FemaleText_loc4`='以女妖之王希尔瓦娜斯的名义，我将这份礼物赐予你！', `FemaleText_loc5`='奉女妖之王希瓦娜斯之名，我賜予你這道贈禮!', `FemaleText_loc7`='¡En nombre de Sylvanas, la Reina alma en pena, te concedo este don!' WHERE `ID`=50119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음의 영면에서 일어나 형제들과 함께하라!', `FemaleText_loc4`='从死亡的沉眠中醒来，加入你们的同胞之中！', `FemaleText_loc5`='離開死亡的懷抱，加入你的弟兄們!', `FemaleText_loc7`='¡Álzate del sopor de la muerte y únete a tus hermanos!' WHERE `ID`=50120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일어나라, 잠든 자여. 새로운 삶이 너를 기다린다.', `FemaleText_loc4`='醒来吧，沉睡者。新的生命正等待着你。', `FemaleText_loc5`='醒來吧，沉睡者。你的新生命在等著。', `FemaleText_loc7`='Despierta, durmiente. Tu nueva vida te aguarda.' WHERE `ID`=50121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 되살아났다. 그리고 밴시 여왕님께서는 너의 충성을 원하신다.', `FemaleText_loc4`='你已经重生于世。女妖之王要求你的效忠。', `FemaleText_loc5`='你被復活了。女妖之王要你效忠於她。', `FemaleText_loc7`='Has vuelto a la vida. La Reina alma en pena reclama tus servicios.' WHERE `ID`=50122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 이봐! 우리는 어쩌고?!', `MaleText_loc4`='哦，天哪！我们怎么办？！', `MaleText_loc5`='噢拜託!那我們呢?!', `MaleText_loc7`='¡Oh, venga, hombre! ¡¿Qué hay de nosotros?!', `FemaleText_loc1`='아니, 이봐요! 우리는 어쩌고요?!', `FemaleText_loc4`='哦，天哪！我们怎么办？！', `FemaleText_loc5`='噢拜託!那我們呢?!', `FemaleText_loc7`='¡Oh, venga, hombre! ¡¿Qué hay de nosotros?!' WHERE `ID`=50123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난치는 거지, 응? 단지 그걸 찾으러 여기까지 왔다고?!', `MaleText_loc4`='你在开玩笑？你到这里来，就是为了这个？！', `MaleText_loc5`='你在開玩笑，對嗎?你千里迢迢來這裡，只為了這個?!', `MaleText_loc7`='Bromeas, ¿verdad? ¡¿Has venido hasta aquí para ESO?!', `FemaleText_loc1`='장난치는 거죠, 네? 단지 그걸 찾으러 여기까지 왔다고요?!', `FemaleText_loc4`='你在开玩笑？你到这里来，就是为了这个？！', `FemaleText_loc5`='你在開玩笑，對嗎?你千里迢迢來這裡，只為了這個?!', `FemaleText_loc7`='Bromeas, ¿verdad? ¡¿Has venido hasta aquí para ESO?!' WHERE `ID`=50124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구. 얼마면 꺼내 줄래? 얼마면 되겠느냐고!!', `MaleText_loc4`='嗨，好汉，如果你能把我从这里弄出去，我会把老婆卖给你。她绝对不会介意的！', `MaleText_loc5`='嘿霸德，如果你能讓我離開這裡，我願意把我老婆賣給你。她不會介意的!', `MaleText_loc7`='Ey, colega, te vendo a mi mujer si me sacas de aquí. ¡A ella no le importará!', `FemaleText_loc1`='이봐요, 친구. 얼마면 꺼내 줄래요? 얼마면 되겠느냐고요!!', `FemaleText_loc4`='嗨，好汉，如果你能把我从这里弄出去，我会把老婆卖给你。她绝对不会介意的！', `FemaleText_loc5`='嘿霸德，如果你能讓我離開這裡，我願意把我老婆賣給你。她不會介意的!', `FemaleText_loc7`='Ey, colega, te vendo a mi mujer si me sacas de aquí. ¡A ella no le importará!' WHERE `ID`=50125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자, 당신에게 딱 맞는 턱을 가진 시체가 여기 어딘가 있었는데...', `MaleText_loc4`='让我们看看，我刚才还看见了一个很适合你的下巴……', `MaleText_loc5`='等等，我才剛看到一個下巴跟你很合的屍體...', `MaleText_loc7`='Pues acabo de ver un cadáver con una mandíbula que podría encajarte.' WHERE `ID`=50126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 되겠군. 턱을 잃어버리면 다시 돌아오시오.', `MaleText_loc4`='这样就没问题了。如果它再掉下来，就回来找我。', `MaleText_loc5`='這樣應該就行了。它要是掉下來了再找我。', `MaleText_loc7`='Eso debería servir. Vuelve si se te cae otra vez.' WHERE `ID`=50127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가... 감사합니다, 장... 의... 사님.', `MaleText_loc4`='感谢你，送葬者。', `MaleText_loc5`='謝—謝你，管—理員。', `MaleText_loc7`='G-gracias, e-enterrador.' WHERE `ID`=50128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 것의 종말이 다가온다!', `MaleText_loc4`='万物的终结即将来临！', `MaleText_loc5`='一切的終結正降臨在我們身上!', `MaleText_loc7`='¡El fin de todas las cosas se avecina!', `FemaleText_loc1`='모든 것의 종말이 다가온다!', `FemaleText_loc4`='万物的终结即将来临！', `FemaleText_loc5`='一切的終結正降臨在我們身上!', `FemaleText_loc7`='¡El fin de todas las cosas se avecina!' WHERE `ID`=50129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 힘을 보아라!', `MaleText_loc4`='见证主人的力量吧！', `MaleText_loc5`='見證主人的力量!', `MaleText_loc7`='¡Contempla los poderes del maestro!', `FemaleText_loc1`='주인님의 힘을 보아라!', `FemaleText_loc4`='见证主人的力量吧！', `FemaleText_loc5`='見證主人的力量!', `FemaleText_loc7`='¡Contempla los poderes del maestro!' WHERE `ID`=50130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이래 봤자 종말이 조금 늦춰질 뿐이다.', `MaleText_loc4`='你只是在拖延必将到来的结局。', `MaleText_loc5`='你只是拖延了無法避免的結局。', `MaleText_loc7`='Tan solo retrasas lo inevitable.', `FemaleText_loc1`='이래 봤자 종말이 조금 늦춰질 뿐이다.', `FemaleText_loc4`='你只是在拖延必将到来的结局。', `FemaleText_loc5`='你只是拖延了無法避免的結局。', `FemaleText_loc7`='Tan solo retrasas lo inevitable.' WHERE `ID`=50131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 황혼의 은혜를 입은 몸이다.', `MaleText_loc4`='我被暮光照耀。', `MaleText_loc5`='我沐浴在暮光之中。', `MaleText_loc7`='Me deleito en el crepúsculo.', `FemaleText_loc1`='나는 황혼의 은혜를 입은 몸이다.', `FemaleText_loc4`='我被暮光照耀。', `FemaleText_loc5`='我沐浴在暮光之中。', `FemaleText_loc7`='Me deleito en el crepúsculo.' WHERE `ID`=50132;
