UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 시선이 느껴지지 않느냐?! 그분은 모든 걸 보고 계신다!', `MaleText_loc4`='难道你没有感觉到主人的注视吗？！他的眼睛不会放过我们之中的任何一个！', `MaleText_loc5`='你看見主人的目光了嗎?他看著我們所有人!', `MaleText_loc7`='¡¿No sientes la mirada del maestro?! ¡Nos observa a todos!', `FemaleText_loc1`='주인님의 시선이 느껴지지 않느냐?! 그분은 모든 걸 보고 계신다!', `FemaleText_loc4`='难道你没有感觉到主人的注视吗？！他的眼睛不会放过我们之中的任何一个！', `FemaleText_loc5`='你看見主人的目光了嗎?他看著我們所有人!', `FemaleText_loc7`='¡¿No sientes la mirada del maestro?! ¡Nos observa a todos!' WHERE `ID`=50137;
