UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기운이 남아돌거든 황혼의 망치단에게 써야지, 이놈들아! 우리가 아니라!', `MaleText_loc4`='在暮光之锤身上浪费你的力量吧，怪物！', `MaleText_loc5`='把你們的精力浪費在暮光之錘身上，而不是我們，怪物!', `MaleText_loc7`='¡Dirige tus energías hacia el Martillo Crepuscular, monstruo, no hacia nosotros!', `FemaleText_loc1`='기운이 남아돌거든 황혼의 망치단에게 써야지, 이놈들아! 우리가 아니라!', `FemaleText_loc4`='在暮光之锤身上浪费你的力量吧，怪物！', `FemaleText_loc5`='把你們的精力浪費在暮光之錘身上，而不是我們，怪物!', `FemaleText_loc7`='¡Dirige tus energías hacia el Martillo Crepuscular, monstruo, no hacia nosotros!' WHERE `ID`=50162;
