UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 얼라이언스의 것이다, 호드 놈들아! 썩 꺼져!', `MaleText_loc4`='这片土地属于联盟，部落怪物！离开这里！', `MaleText_loc5`='這個島嶼是聯盟的，可悲的部落!你們快滾吧!', `MaleText_loc7`='¡Esta tierra pertenece a la Alianza, estiércol de la Horda! ¡Fuera de aquí!', `FemaleText_loc1`='이 땅은 얼라이언스의 것이다, 호드 놈들아! 썩 꺼져!', `FemaleText_loc4`='这片土地属于联盟，部落怪物！离开这里！', `FemaleText_loc5`='這個島嶼是聯盟的，可悲的部落!你們快滾吧!', `FemaleText_loc7`='¡Esta tierra pertenece a la Alianza, estiércol de la Horda! ¡Fuera de aquí!' WHERE `ID`=50168;
