UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘 높은 곳에서 싸울 때는 근거리에서 사용할 수 있는 기술이 가장 효과적일 것입니다. 갈고리를 이용해 주홍빛 하늘비룡의 등 위로 올라간 뒤, 주변의 흑요석 불길날개에게 옮겨가십시오.', `FemaleText_loc4`='你的远程技巧很适合在高处进行战斗。用你的钩子跃到一头朱红啸天龙的背上，然后从那里射击盘旋的火翼龙。', `FemaleText_loc5`='你的遠程攻擊技巧非常適合高空上的作戰。先利用你的鉤子騎上朱紅嘯天者，然後在天空上殺掉盤旋的炎翼飛龍。', `FemaleText_loc7`='Tu habilidad a distancia resultará más efectiva para la pelea más arriba. Utiliza tus ganchos para subir a uno de los vociferadores de cielo Bermellón, y desde allí derriba a los piroala que vuelan en círculos.' WHERE `ID`=50182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비룡은 치명상을 입어 곧 추락할 것입니다! 어서 다른 비룡에게로 이동하십시오!

|TInterface\\Icons\\inv_misc_hook_01.blp:32|t', `MaleText_loc4`='你骑乘的幼龙受到了致命伤害，就要跌落下去了！赶快转移到另一头幼龙身上！

|TInterface\\Icons\\inv_misc_hook_01.blp:32|t', `MaleText_loc5`='你身下的龍受到了致命的重傷，即將墜落!快點換到另一頭龍!

|TInterface\\Icons\\inv_misc_hook_01.blp:32|t', `MaleText_loc7`='¡El draco sobre el que vuelas está mortalmente herido y a punto de caer! ¡Rápido, cámbiate a otro draco!

|TInterfaceIconsinv_misc_hook_01.blp:32|t' WHERE `ID`=50183;
