UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바네사가 독약병을 마구 던집니다! 어서 위로 올라가십시오!', `FemaleText_loc4`='梵妮莎开始抛掷毒药瓶了！赶快爬上去！', `FemaleText_loc5`='凡妮莎開始扔擲毒藥瓶!快點往上爬!', `FemaleText_loc7`='¡Vanessa comienza a lanzar viales de veneno! ¡Trepa rápido!' WHERE `ID`=50191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 늑대인간에게 물렸습니다. 별일 아닐 수도 있지만, 조금 따끔거리는 것은 확실합니다.$B$B|Tinterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t', `MaleText_loc4`='你被狼人咬了。可能这没什么，但肯定会有些痛。$B$B|TInterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t', `MaleText_loc5`='你被一隻狼人咬到了。或許沒什麼大礙，但的確是有點痛。$B$B|TInterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t', `MaleText_loc7`='Te ha mordido un huargen. Probablemente no sea nada, pero vaya si escuece.$B$B|TInterfaceIconsINV_Misc_monsterfang_02.blp:32|t' WHERE `ID`=50192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒷문 쪽에 궤짝이 하나 나타납니다!', `MaleText_loc4`='后门附近出现了一只箱子！', `MaleText_loc5`='一個箱子出現在後門入口處!', `MaleText_loc7`='¡Se ve un baúl cerca de la entrada de atrás!', `FemaleText_loc1`='뒷문 쪽에 궤짝이 하나 나타납니다!', `FemaleText_loc4`='后门附近出现了一只箱子！', `FemaleText_loc5`='一個箱子出現在後門入口處!', `FemaleText_loc7`='¡Se ve un baúl cerca de la entrada de atrás!' WHERE `ID`=50193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무... 내게 무슨 일이? 내게 왜 이런 짓을 한 거야?', `MaleText_loc4`='我……我出了什么事？为什么你要这样对我？', `MaleText_loc5`='我...我發生了什麼事情?你為什麼要這樣對我?', `MaleText_loc7`='¿Qué... qué me está ocurriendo? ¿Por qué me has hecho esto?' WHERE `ID`=50194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽었지만, 죽은 채 다시 돌아왔다!', `MaleText_loc4`='我应该是死了，就算是死了，我也会回来！', `MaleText_loc5`='我早該死去，就讓我回歸死亡吧!', `MaleText_loc7`='¡Debería estar muerto y a la muerte regresaré!' WHERE `ID`=50195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 실바나스 여왕님이 한 건가?', `MaleText_loc4`='这是希尔瓦娜斯女王干的？', `MaleText_loc5`='這是希瓦娜斯女王幹的?', `MaleText_loc7`='¿Esto es obra de Lady Sylvanas?' WHERE `ID`=50196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 손아귀에서 날 구한 이건 대체 무슨 마법이란 말인가?', `MaleText_loc4`='是什么样的魔法，竟然能挡住死亡之手？', `MaleText_loc5`='這是什麼魔法，竟然能鬆開死亡的掌握?', `MaleText_loc7`='¿Qué clase de magia es la que rechaza la mano de la muerte?' WHERE `ID`=50197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기... 기억이 안 나... 왜 내게 이런 짓을?', `MaleText_loc4`='我……我想不起来了……为什么你们要这样做？', `MaleText_loc5`='我...我不記得...你為什麼要這麼做?', `MaleText_loc7`='Yo... No recuerdo... ¿Por qué has hecho esto?' WHERE `ID`=50198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕님은 날 어디에 쓰시려는 거지?', `MaleText_loc4`='我对黑暗女王有什么用？', `MaleText_loc5`='黑暗女王需要我做什麼?', `MaleText_loc7`='¿Para qué me necesita la Dama Oscura?' WHERE `ID`=50199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밴시 여왕님이 내게 기회를 주셨으니, 이에 마땅히 응하리라.', `MaleText_loc4`='如果女妖之王给我这样的机会，我很愿意向她效忠。', `MaleText_loc5`='既然女妖之王給了這個機會，我會很樂意效忠於她。', `MaleText_loc7`='Si la Reina alma en pena me ha ofrecido esta oportunidad, la serviré con gusto.' WHERE `ID`=50200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이렇게 되고 싶지 않았어! 날 내버려 둬!', `MaleText_loc4`='我从不想要这样！别来碰我！', `MaleText_loc5`='這不是我要的!放過我!', `MaleText_loc7`='¡Yo nunca pedí esto! ¡Déjame solo!' WHERE `ID`=50201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 우리 할머니도 그 정도는 하겠군.', `MaleText_loc4`='哈！你的动作倒真像是我的老祖母。', `MaleText_loc5`='哈!你扔的跟我老奶奶一樣。', `MaleText_loc7`='¡Ja! Te quejas como mi abuela.' WHERE `ID`=50202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 보고 배우라고, 애송이.', `MaleText_loc4`='仔细看着，好好学，孩子。', `MaleText_loc5`='仔細看好啦，小鬼。', `MaleText_loc7`='Mira y aprende, cachorro.' WHERE `ID`=50203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽함이 무엇인지 보여주지.', `MaleText_loc4`='好好看看什么是完美。', `MaleText_loc5`='看看什麼才叫完美。', `MaleText_loc7`='Prepárate para ser testigo de la perfección.' WHERE `ID`=50204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘지 않군... 병든 코도의 넓은 등짝 정도는 맞힐 수 있겠어.', `MaleText_loc4`='还不赖……你也许还能打中生病科多兽的大肚子。', `MaleText_loc5`='不壞嘛...大概還打得到生病的科多獸側面吧。', `MaleText_loc7`='No está mal... Quizá seas capaz de acertar en la parte más ancha de un kodo enfermizo.' WHERE `ID`=50205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑바로 시원하게 날아가는군.', `MaleText_loc4`='这样应该是可以了。', `MaleText_loc5`='這個會直接穿過去。', `MaleText_loc7`='Este va a atravesarlo.' WHERE `ID`=50206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 저 화살을 화살대부터 깔끔하게 둘로 쪼갤 수 있다는 데 2실버 걸지.', `MaleText_loc4`='和你赌两个银币，我能把一支箭从中间劈开。', `MaleText_loc5`='賭兩塊銀幣我可以把箭桿子弄裂開。', `MaleText_loc7`='Van dos de plata a que puedo partir esa flecha en dos.' WHERE `ID`=50207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 용들은 빠릿빠릿하게 잘들 하는군요. 어중이떠중이들이 잔뜩 모여서 자기들이 뭘 해야 하는지나 제대로 알까 싶었는데 말입니다.$B$B뭐, 어쨌든 상관없습니다. 제 부하들이 밀고 나가서 뭐든 처리할 수 있으니까요. 그냥 일할 곳만 좀 있으면 됩니다.', `MaleText_loc4`='这些龙并不糊涂。不过我不确定这些小崽子是否都知道他们要干什么。$B$B当然，我们这里是不会有问题的。我的小子们会冲在最前面，把一切都搞定。我们所需要的只是一个施展拳脚的地方。', `MaleText_loc5`='這些龍可不是好惹的，而且我不曉得是不是全部的小鬼都知道他們是來幹嘛的。$B$B不過沒關係，我們不會有事的。我的手下可以帶頭衝鋒，把這件事情搞定。我們只需要一點工作的空間。', `MaleText_loc7`='Esos dragones no están ahí para pasar el rato. No estoy seguro de que todos esos desgraciados sepan para qué están aquí.$B$BPero estaremos bien. Mis muchachos y yo iremos a la cabeza de la carga y terminaremos este trabajo. Todo lo que necesitamos es un poquito de espacio para trabajar.' WHERE `ID`=50208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비를 마친 후 제단을 건드리면 시작할 수 있습니다.', `MaleText_loc4`='你准备好开始之后，就触碰祭坛。', `MaleText_loc5`='等你準備好了，碰觸祭壇就會開始。', `MaleText_loc7`='Cuando estés $glisto:lista;, toca el altar para empezar.' WHERE `ID`=50209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험이 시작되면, 발아래서 주기적으로 그림자가 풀려나 주변의 차원문으로 이동하여 흐느끼는 영혼을 소환합니다.', `MaleText_loc4`='当试炼开始的时候，来自你脚下的暗影将周期性地突破禁制，进入附近的传送门，召唤来一个泣灵。', `MaleText_loc5`='等試煉開始之後，你的影子會不時掙脫，前往附近的傳送門去召喚出一個哀泣的靈魂。', `MaleText_loc7`='Cuando comience la prueba, sombra de debajo de ti se liberarán periódicamente y llegarán hasta un portal cercano para invocar a una alma sollozante.' WHERE `ID`=50210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐느끼는 영혼은 당신을 놀라게 할 수 있지만, 그들의 움직임을 예측하는 것은 어렵지 않습니다. 땅 위에 흩어진 룬 덫으로 영혼을 유인하십시오.', `MaleText_loc4`='泣灵也许很可怕，但它们的行动在某种程度上还是可以预期的。将它们引诱进铺设在地面上的符文陷阱里。', `MaleText_loc5`='哀泣的靈魂或許很可怕，但它們的行為模式還是可預期。把它們引誘到地上各處的符文陷阱。', `MaleText_loc7`='Las almas sollozantes quizá den miedo, pero son bastante predecibles. Atráelas hasta las trampas de runas que hay diseminadas por el suelo.' WHERE `ID`=50211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐느끼는 영혼을 덫에 가들 때마다 그림자 미끼 효과를 하나씩 얻게 됩니다.', `MaleText_loc4`='每次你成功地困住一个泣灵，都将得到一层暗影诱饵。', `MaleText_loc5`='每當你成功地困住一個哀泣的靈魂時，你就能獲得一份暗影誘餌。', `MaleText_loc7`='Cada vez que atrapes una alma sollozante con éxito, recibirás una acumulación de Cebo de sombras.' WHERE `ID`=50212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자 미끼 효과는 흐느끼는 영혼에게 공격당할 때마다 하나씩 사라집니다.', `MaleText_loc4`='每次你被泣灵击中，都将失去一层暗影诱饵。', `MaleText_loc5`='而每當你被哀泣的靈魂擊中時，你會失去一份暗影誘餌。', `MaleText_loc7`='Cada vez que una alma sollozante te golpee, perderás una acumulación de cebo de sombras.' WHERE `ID`=50213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자 미끼 효과가 20번 중복되면 시험에 통과하게 됩니다.', `MaleText_loc4`='积累20层暗影诱饵，就能完成试炼。', `MaleText_loc5`='取得20份暗影誘餌以通過此試煉。', `MaleText_loc7`='Consigue 20 acumulaciones de cebo de sombras para completar la prueba.' WHERE `ID`=50214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=50215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 초마다 주변의 룬 여러 개에 불이 붙습니다.', `MaleText_loc4`='每隔几秒钟，附近的许多符文都将起火爆炸。', `MaleText_loc5`='每隔幾秒鐘，許多附近的符文就會爆發出火焰。', `MaleText_loc7`='Cada pocos segundos, muchos de las runas cercanas explotarán en llamaradas.' WHERE `ID`=50216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각 룬이 타오를 때마다 주변에 있는 하나 이상의 룬으로 불화살이 발사되어, 해당 룬이 다음 회에 타오르게 만듭니다.', `MaleText_loc4`='每个爆炸的符文都会射出一股火焰箭，击中附近的一个或多个符文，使其成为下一批爆炸的符文。', `MaleText_loc5`='每個符文爆發時都會朝附近的某一個或甚至多個符文射出一道火焰，觸發該符文成為下個即將啟動引燃的符文。', `MaleText_loc7`='A medida que cada runa explote, una descarga de fuego llegará hasta una o más runas cercanas y provocará que sean las siguientes en explotar.' WHERE `ID`=50217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 룬이 불화살에 맞지 않는지를 잘 살펴보면 다음 폭발 시 안전한 곳을 찾을 수 있습니다.', `MaleText_loc4`='如果你仔细观察这些火焰箭，确认那些没有被击中的符文，你就能在下一次爆炸中找到安全位置。', `MaleText_loc5`='只要你仔細觀察火焰的射向，看清楚哪些符文沒有被火燒到，就能找出下次爆發時的安全地點。', `MaleText_loc7`='Si observas esas descargas con cuidado para ver qué runas quedan intactas, encontrarás refugios seguros para las próximas explosiones.' WHERE `ID`=50218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 검은 연기가 피어오르는 룬이 있는데, 이 룬은 다음 폭발 시 불에 타지 않습니다.', `MaleText_loc4`='偶尔会有符文冒起黑烟，这样的符文将不会在随后的爆炸中起火爆炸。', `MaleText_loc5`='某些時候，部分符文會熄滅冒出黑煙，阻止它們在下次爆發時噴出火焰。', `MaleText_loc7`='De vez en cuando, un humo negro emanará de algunas runas. Eso evitará que entren en combustión durante la siguiente explosión.' WHERE `ID`=50219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이 붙지 않은 상태로 룬 안에 머물르는 동안, 불춤 효과가 10번 중복되면 시험에 통과하게 됩니다.', `MaleText_loc4`='待在符文中，注意不要被火焰击中，直到你积累了10层火焰之舞，完成这个试炼。', `MaleText_loc5`='待在符文陣裡而不被火焰擊中，累積10道火舞即可完成此試煉。', `MaleText_loc7`='Permanece dentro de las runas sin que te alcance el fuego hasta que obtengas diez acumulaciones de danza del fuego.' WHERE `ID`=50220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬에서 너무 오래 벗어나 있거나 연속으로 여러 번 불에 맞으면 처음부터 다시 시작해야 하므로 주의하십시오.', `MaleText_loc4`='注意：离开符文太长时间，或者连续被多重火焰击中，会让你重新开始这场试炼。', `MaleText_loc5`='注意:離開符文陣過久，或是被多道火焰同時擊中，都將迫使你重新開始。', `MaleText_loc7`='Cuidado: si permaneces fuera de las runas durante mucho tiempo o recibes el impacto de múltiples explosiones seguidas, tendrás que volver a empezar.' WHERE `ID`=50221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고원 여기저기에 얼어붙은 구슬이 흩어져 있습니다. 구슬 근처에 다가가면 얼음의 정수 효과를 얻게 됩니다.', `MaleText_loc4`='冰霜宝珠分布在这片高地上，如果你接触它们，就会得到冰之精华。', `MaleText_loc5`='這片高原上散佈著許多冰霜之球，而你只要靠近它們就能獲得一道寒冰精華。', `MaleText_loc7`='Diseminados por toda la meseta encontrarás orbes congelados que te darán montones de esencia de hielo si te acercas a ellos.' WHERE `ID`=50222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변을 돌아다시는 서리 불꽃을 피하지 못하면, 피해를 입고 얼음의 정수 효과를 잃게 됩니다.', `MaleText_loc4`='避开旋转的冰霜烧灼效果，否则你就会受到伤害，并失去一层冰之精华。', `MaleText_loc5`='避開迴旋移動的寒冰燃體，否則你將受到傷害，並失去一道寒冰精華。', `MaleText_loc7`='Evita los efectos rotativos de la quemadura de escarcha o recibirás daño y perderás un montón de esencia de hielo.' WHERE `ID`=50223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에 있는 냉기 룬을 건드리면 공중으로 튀어 오르며, 이는 유리하거나 불리하게 작용할 수 있습니다.', `MaleText_loc4`='如果你碰到地面上的冰霜符文，就会被抛向空中。这对你也许会有好处，也许会是个麻烦。', `MaleText_loc5`='地上的冰霜符文會把你彈飛到空中，這可能會幫到你、也可能會害到你。', `MaleText_loc7`='Las runas de escarcha del suelo te harán volar por los aires si las tocas, lo que puede ser una bendición o un inconveniente.' WHERE `ID`=50224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙은 땅에 너무 가까이 다가가면 이동하기가 더욱 어려워집니다.', `MaleText_loc4`='不要靠那片寒冰之地太近，否则你会发现自己移动起来非常艰难。', `MaleText_loc5`='別太靠近冰凍的地面，否則你的移動將會變得更為困難。', `MaleText_loc7`='No te acerques demasiado al suelo helado o verás que tus movimientos se vuelven significativamente más difíciles.' WHERE `ID`=50225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빠르게 움직이고 생각하며 위험을 피하는 동안, 얼음의 정수 효과가 20번 중복되면 시험에 통과하게 됩니다.', `MaleText_loc4`='一定要动作敏捷，考虑周全，远离危险，收集20层冰之精华，完成此次试炼。', `MaleText_loc5`='動作快，想清楚，遠遠避開危險，收集20道寒冰精華以通過此試煉。', `MaleText_loc7`='Sé ágil, piensa antes de actuar y no te acerques mucho a los peligros; y obtén 20 acumulaciones de esencia de hielo para completar la prueba.' WHERE `ID`=50226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 봉우리의 능선에는 6개의 단상이 흩어져 있으며, 이를 건드리면 몸에 마력이 충전됩니다.', `MaleText_loc4`='在奥术之巅凸出的平台上分布着6个基座，如果你碰触它们，就能得到它们的能量。', `MaleText_loc5`='共有7個臺座散佈在秘法之巔的岩棚上，碰觸之後可使你獲得能量充沛的效果。', `MaleText_loc7`='Diseminados por el borde del Pináculo Arcano hay 6 pedestales que te energizarán si los tocas.' WHERE `ID`=50228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에 있는 마력 장치를 사용해 비전 봉우리를 오르는 동안 단상을 모두 건드리십시오.', `MaleText_loc4`='使用地面上的能量垫，上升至奥术之巅，碰触沿途的全部基座。', `MaleText_loc5`='利用地面上的能量板爬上秘法之巔，並且碰觸沿路所有的臺座。', `MaleText_loc7`='Utiliza esos bloques de energía y asciende por el Pináculo Arcano tocando todos los pedestales que te encuentres por el camino.' WHERE `ID`=50229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이동을 멈추면 비전력 폭발이 일어나 아래쪽에 있는 물 속으로 빠질 수 있습니다.', `MaleText_loc4`='任何时候都不要停在某处不动，否则你就有可能被奥术爆炸击中，落进下方的水中。', `MaleText_loc5`='持續保持移動，否則你可能會被秘法爆破擊中而摔落下方的水裡。', `MaleText_loc7`='No dejes de moverte o correrás el riesgo de que te alcance una detonación arcana que te hará caer a las aguas que hay abajo.' WHERE `ID`=50230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물 속에 빠져도 실망할 필요는 없습니다. 첫 번째 단상으로 헤엄쳐 돌아간 다음 다시 시작하면 됩니다.', `MaleText_loc4`='如果你落进下方的水中，不要气馁。游回到第一个平台那里，重新开始吧。', `MaleText_loc5`='但就算摔進了水裡也不必氣餒，游泳回到第一個岩棚即可重新開始。', `MaleText_loc7`='Si caes en el agua, no te desanimes. Nada hasta el primer saliente y empieza de nuevo.' WHERE `ID`=50231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 봉우리 꼭대기에 도달하는 동안 충만함 효과를 6번 얻으면 시험에 통과하게 됩니다.', `MaleText_loc4`='到达奥术之巅的顶部，积累6层充能，完成试炼。', `MaleText_loc5`='累積6道能量充沛的效果抵達秘法之巔即可通過此一考驗。', `MaleText_loc7`='Para completar la prueba llega a lo más alto del Pináculo Arcano con 6 acumulaciones de energizados.' WHERE `ID`=50232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발물 애호가들에 의해 발견된, 폭발물 애호가들을 위한, 그림 같은 점화등 바닷가마을에 온 걸 환영해, 친구.', `MaleText_loc4`='欢迎来到熔光码头，这座风景如画的海滨小城是爆炸狂们为爆炸狂建造的家园。', `MaleText_loc5`='歡迎來到熔絲火光海邊營地，一座如詩如畫的海濱小鎮，由爆破狂專門為爆破狂而建立的。', `MaleText_loc7`='Te doy la bienvenida a El Diodo de Mar, una pintoresca ciudad costera fundada por amantes de los explosivos para amantes de los explosivos.' WHERE `ID`=50233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 귀환 장소로 설정합니다.', `MaleText_loc4`='我要让这里成为我的家。', `MaleText_loc5`='我想要住在這裡。', `MaleText_loc7`='Me gustaría convertir esto en mi hogar.', `FemaleText_loc1`='이곳을 귀환 장소로 설정합니다.', `FemaleText_loc4`='我要让这里成为我的家。', `FemaleText_loc5`='我想要住在這裡。', `FemaleText_loc7`='Me gustaría convertir esto en mi hogar.' WHERE `ID`=50234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼, 시작해 보십시오!', `MaleText_loc4`='好了，跳上去！', `MaleText_loc5`='好，那就開始吧!', `MaleText_loc7`='¡Bueno, entonces arriba!' WHERE `ID`=50235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서리의 시험은 어떻게 진행됩니까?', `MaleText_loc4`='冰霜试炼是如何进行的？', `MaleText_loc5`='霜之試煉是如何進行的?', `MaleText_loc7`='¿Cómo funciona la Prueba de de Escarcha?' WHERE `ID`=50236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확히 어떤 원리입니까?', `MaleText_loc4`='严格来说，它是怎样进行的？', `MaleText_loc5`='這究竟是如何進行的?', `MaleText_loc7`='¿Cómo funciona esto exactamente?' WHERE `ID`=50237;
