UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다. 부하들을 시켜 여기서부터 밀고 나가지요. 계속 전진해서 마지막 문도 확보하십시오.', `MaleText_loc4`='干得好。我会让部下继续前进，拿下最后一道门。', `MaleText_loc5`='做得好。我會叫手下繼續從這邊推進向前，拿下最後一道門。', `MaleText_loc7`='Buen trabajo. Haré que los hombres sigan avanzando desde aquí. Adelántate y toma la última puerta.' WHERE `ID`=50240;
