UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='촉수를 조심하세요! 엄청나게 멀리까지 뻗는답니다.', `FemaleText_loc4`='小心那些触须！被它们碰到是非常可怕的。', `FemaleText_loc5`='小心那些觸手!它們的攻擊範圍非常大。', `FemaleText_loc7`='¡Cuidado con esos tentáculos! Su alcance es increíble.' WHERE `ID`=50244;
