UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 자크, 자네가 데리고 있는 폭파물 분석가의 평균 수명이 얼마나 되는 것 같아?', `MaleText_loc4`='嗨，扎克，你的爆破分析师平均寿命是多少？', `MaleText_loc5`='嘿，札克，你那些爆破分析師的平均壽命是多少?', `MaleText_loc7`='Eh, Zak, ¿cuál es la esperanza de vida de uno de tus analistas de explosivos?' WHERE `ID`=50246;
