UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 개발된 특급 엘레멘티움 폭약과 함께라면... 알고 싶지도 않을 거라고.', `MaleText_loc4`='那种超能量源质炸药？你不会想知道的……', `MaleText_loc5`='負責超易燃的源質火藥粉的嗎?你不會想知道的...', `MaleText_loc7`='¿Con esa explosiva pólvora de elementium de gran potencia? Será mejor que no lo sepas...' WHERE `ID`=50248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭉치화염! 내 새끼들이 네 부드러운 살을 마음껏 즐길 것이다!', `FemaleText_loc4`='烽焰！你软弱的肉体将成为我的幼崽们最好的食物！', `FemaleText_loc5`='罪火!你軟嫩的鮮肉會變成我幼龍們的大餐!', `FemaleText_loc7`='¡Fardollama! ¡Tu carne tierna será un alimento apropiado para mis crías!' WHERE `ID`=50249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 아이들아! 깨어나서 저놈들의 살을 맛보아라!', `MaleText_loc4`='来吧，我的孩子们！苏醒过来，享受这丰美的血肉吧！', `MaleText_loc5`='來吧，我的孩子們!醒來，吃光他們的血肉!', `MaleText_loc7`='¡Venid, hijos míos! ¡Despertad y daos un festín con su carne!', `FemaleText_loc1`='오너라, 아이들아! 깨어나서 저놈들의 살을 맛보아라!', `FemaleText_loc4`='来吧，我的孩子们！苏醒过来，享受这丰美的血肉吧！', `FemaleText_loc5`='來吧，我的孩子們!醒來，吃光他們的血肉!', `FemaleText_loc7`='¡Venid, hijos míos! ¡Despertad y daos un festín con su carne!' WHERE `ID`=50250;
