UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 혈관을 흐르는 불꽃에 휘감겨라!', `MaleText_loc4`='沐浴在大地的烈焰之血中吧！', `MaleText_loc5`='沐浴在燃燒的大地之血中吧!', `MaleText_loc7`='¡Sumérgete en la sangre ardiente de la tierra!', `FemaleText_loc1`='대지의 혈관을 흐르는 불꽃에 휘감겨라!', `FemaleText_loc4`='沐浴在大地的烈焰之血中吧！', `FemaleText_loc5`='沐浴在燃燒的大地之血中吧!', `FemaleText_loc7`='¡Sumérgete en la sangre ardiente de la tierra!' WHERE `ID`=50252;
