UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 개인적인 감정은 없지만, 죽어줘야겠어.', `MaleText_loc4`='嗨，我们没有私人仇恨，但你还是要死。', `MaleText_loc5`='嘿，跟私人恩怨無關，可是你非死不可。', `MaleText_loc7`='Hey, no es nada personal, pero vas a morir.' WHERE `ID`=50256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 아니면 당신이 죽어야 하니, 기왕이면 당신이 죽는 편이 좋겠지.', `MaleText_loc4`='不是你死就是我活，朋友。当然，最后肯定是我活。', `MaleText_loc5`='不是我就是你，兄弟，而且絕對不會是我。', `MaleText_loc7`='Es tú o yo, colega, y no voy a ser yo.' WHERE `ID`=50257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 힘을 다해 보라고. 내가 빨리 없애 줄 테니.', `MaleText_loc4`='把你的一切都给我，我会让你死个痛快。', `MaleText_loc5`='使出你的全力吧，反正我很快就能搞定你了。', `MaleText_loc7`='Dame todo lo que tengas, y haré que sea rápido.' WHERE `ID`=50258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 널 없애라는 명령을 받았어. 돈을 받았으니 밥값은 해야지.', `MaleText_loc4`='我已经得到命令，要置你于死地。而且看样子，你也没钱收买我。', `MaleText_loc5`='我接到命令說你非死不可，而且你可不是付我帳單的人。', `MaleText_loc7`='Tengo órdenes que me dicen que tienes que morir, y tú no eres el que paga mis facturas.' WHERE `ID`=50259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모래 속에서 아주 푹 쉬라고...', `MaleText_loc4`='到沙子里睡觉去吧……', `MaleText_loc5`='你該躺進土裡睡個長覺了....', `MaleText_loc7`='Es hora de que te eches una larga siesta en la arena...' WHERE `ID`=50260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일로 돈을 벌다니 즐겁군.', `MaleText_loc4`='我喜欢这样挣钱。', `MaleText_loc5`='我最愛領錢辦這種事。', `MaleText_loc7`='Me encanta que me paguen por esto.' WHERE `ID`=50261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쳇, 이런 일을 할 만큼 돈을 많이 받는 건 아닌데.', `MaleText_loc4`='呸，挣这点钱可不够我花的。', `MaleText_loc5`='哼，領的錢根本不值得搞這種事情。', `MaleText_loc7`='Bah, no me pagan suficiente para esto.' WHERE `ID`=50262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 마을 사람을 괴물로 만들고 있습니다!', `MaleText_loc4`='他们把我们的族人变成了怪物！！', `MaleText_loc5`='他們正在把我們的人民變成怪物!!', `MaleText_loc7`='¡¡Están convirtiendo a la gente en MONSTRUOS!!', `FemaleText_loc1`='놈들이 마을 사람을 괴물로 만들고 있어요!', `FemaleText_loc4`='他们把我们的族人变成了怪物！！', `FemaleText_loc5`='他們正在把我們的人民變成怪物!!', `FemaleText_loc7`='¡¡Están convirtiendo a la gente en MONSTRUOS!!' WHERE `ID`=50263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 막아내십시오! 생존자들을 보호해야만 합니다!', `MaleText_loc4`='挡住他们！我们必须保护幸存者！', `MaleText_loc5`='阻擋他們!我們必須保護倖存的人!', `MaleText_loc7`='¡Haganlos retroceder! ¡Debemos proteger a los supervivientes!', `FemaleText_loc1`='놈들을 막아내세요! 생존자들을 보호해야만 해요!', `FemaleText_loc4`='挡住他们！我们必须保护幸存者！', `FemaleText_loc5`='阻擋他們!我們必須保護倖存的人!', `FemaleText_loc7`='¡Haganlos retroceder! ¡Debemos proteger a los supervivientes!' WHERE `ID`=50264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 눈을 보지 마십시오! 당신이 예전에 알던 사람이 아닙니다!', `MaleText_loc4`='别看他们的眼睛！他们已经不再是你曾经熟悉的那些人了！', `MaleText_loc5`='不要看他們的眼睛!他們已經不是你所認識的人了!', `MaleText_loc7`='¡No les miren a los ojos! ¡Ya no queda nada de las personas que conocían!', `FemaleText_loc1`='놈들의 눈을 보지 마세요! 당신이 예전에 알던 사람이 아니에요!', `FemaleText_loc4`='别看他们的眼睛！他们已经不再是你曾经熟悉的那些人了！', `FemaleText_loc5`='不要看他們的眼睛!他們已經不是你所認識的人了!', `FemaleText_loc7`='¡No les miren a los ojos! ¡Ya no queda nada de las personas que conocían!' WHERE `ID`=50265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아비아나의 제단에 오신 걸 환영합니다, $c|1이여;여;. 이곳은 세계의 꼭대기, 하늘과 맞닿은 곳입니다.', `MaleText_loc4`='欢迎来到艾维娜圣殿，$c。在这里，我们安坐于毗邻苍穹的世界之巅。', `MaleText_loc5`='歡迎來到艾維娜聖壇，$c。我們坐落在世界之顛，伸手即可觸碰天空。', `MaleText_loc7`='Te doy la bienvenida al Santuario de Aviana, $c. Aquí estamos en lo más alto del mundo y tocamos el cielo.' WHERE `ID`=50266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n 님! 다시 만났군요. 기억나시나요? 전에 아웃랜드에서 빠른 폭풍날개로 변신하는 걸 도운 적이 있는데.$B$B<표정이 굳어지며 고개를 흔드는 모르디스. 주름진 눈이 슬퍼 보입니다.>$B$B요즘 젊은 드루이드들은... 너무 쉽게 배운단 말이죠.', `MaleText_loc4`='啊，$n！我们又见面了。我曾经帮助你在外域实现了迅速飞行。$B$B<莫希斯紧咬住牙关，摇了摇头。他衰弱的双眼中充满了哀伤。>$B$B今天这些年轻的德鲁伊……他们太过轻易就获得了这种能力。', `MaleText_loc5`='啊，$n!我們又見面了。我曾經在外域幫你取得迅捷飛行形態。$B$B<莫西斯閉緊嘴巴搖了搖頭，眼神憔悴而悲傷。>$B$B現在的這些年輕德魯伊...他們輕輕鬆鬆就能拿到。', `MaleText_loc7`='¡Ah, $n! Nos encontramos de nuevo. Yo te ayudé a conseguir tu forma de vuelo presto en Terrallende.$B$B<Morthis tensa la mandíbula y menea la cabeza. Sus ojos mustios están tristes.>$B$BLos jóvenes druidas de hoy en día... lo tienen demasiado fácil.' WHERE `ID`=50267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 저는 편지를 많이 받는답니다. 대부분 쓸모없는 내용이긴 하지만요. 하지만 그런 것 중 하나가 당신 같은 $c에게 도움이 될 수도 있죠. 여기 눈망루 마을 앞으로 온 편지가 있어요. 세상의 머나먼 구석에서 도움을 요청하고 있군요.$b$b다음에 갈 곳이 생긴 것 같지 않나요? 자, 그럼 어디 한번 볼까요...', `FemaleText_loc4`='我有许多信件，$n。其中大多数都是垃圾，但有一些对于像你这样有能力的$c来说的确会有些用处。这里有几封寄到永望镇的信，要在世界的这个遥远角落中寻找帮助。$b$b说实话，我觉得我根本没法选择自己的道路！好吧，让我们看看……', `FemaleText_loc5`='我收到好多的郵件，$n。大部分都是垃圾，但還是有一些對你這種有用的$c是有用的。這裡有幾封要送往永望鎮的，要在世界偏僻的角落裡尋找幫助。$b$b好像你還真的可以選接下來要去哪裡似的!好吧，讓我再看看...', `FemaleText_loc7`='Suelo recibir mucho correo, $n. La mayor parte es correo basura, pero a veces llega algo que podía resultarle útil a $gun:una; $c servicial como tú. Aquí hay un par de cartas enviadas a Vista Eterna en las que se dice que buscan ayuda en los rincones más alejados del mundo.$b$b¡Casi es como si pudieras elegir adónde ir a continuación! Veamos...' WHERE `ID`=50268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 석상이 참 골치를 썩이네요. 저는 기중기와 폭탄을 적절히 사용하면 물 밖으로 꺼낼 수 있을 거로 생각했어요. 그런데 현장감독은 이 경사로로 굴리는 방식으로 옮겨야 안전하다고 우겼죠.$B$B근데 이걸 보세요... 각도가 다 틀어졌어요. 그래요, 저 위로 옮겼다고 쳐요. 그다음엔 뭘 어떻게 하겠다는 거죠?$B$B아무래도 여기 오래 있을 것 같은 불길한 예감이 들어요. 아주 오래 말이에요...', `FemaleText_loc4`='这尊雕像实在是让人头痛。我本来设想，我们能用一台起重机和几次定向爆破让它浮出水面。但维克认为我们应该采取更加安全和能够减少损伤的办法，就是沿这道斜坡把它滚上去。$B$B现在可好了……我们把它的角度全都弄错了。就算我们把它弄到顶上，又能怎样？$B$B我有一种很糟糕的感觉，我们要在这里耽搁很长时间，很长很长的时间……', `FemaleText_loc5`='那個雕像真的太難搞定了。本來我以為弄個炸藥還是起重機之類的就可以把它從水裡吊起來，但是威克說用這個斜坡道把它拖上來會比較安全，而且損傷比較小。$B$B結果現在你看看...角度整個錯了。然後等我們把它弄上來以後，又該怎麼辦咧?$B$B我有一種不祥的預感，我們會在這裡耗上很久。很久很久...', `FemaleText_loc7`='Esa estatua está resultando ser dura de pelar. Pensé que podríamos subirla y sacarla del agua con una grúa y unos explosivos bien colocados. Pero Wick creyó que la dañaríamos menos si la hacíamos rodar por esta rampa.$B$BAhora mírala... La hemos colocado en mal ángulo. Y una vez la llevemos hasta lo más alto, ¿entonces qué?$B$BTengo la impresión de que vamos a quedarnos aquí una buena temporada. Una buena temporada de verdad...' WHERE `ID`=50269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 항구에서 일도 훌륭히 마무리했겠다, 이 드워프 석공이 이젠 절 좀 가만히 놔둬야 정상 아닙니까?...$B$B전 이 석상을 경사로를 통해 최대한 빨리 옮긴 다음, 제자리에 갖다 놓고 싶을 뿐입니다. 그런데 이 여자는 한 발자국 움직일 때마다 불만을 쏟아냅니다. 이 여자는 똑같은 말만 합니다. 뭐, 폭파물을 사용하면 다 해결된다나요? 이건 완전히 노움이나 고블린하고 일하는 느낌입니다. 그나마 노움이나 고블린은 술 냄새라도 안 나지.$B$B우리 인부들을 보십시오. 기강이라곤 눈 씻고도 찾아볼 수 없습니다. 왜 그런지 아십니까? 이 여자가 사사건건 참견을 하기 때문입니다!$B$B태도 불량에 게으른 인부들... 이건 절대 쉽게 해결될 문제가 아닙니다.', `MaleText_loc4`='按理说，既然我在暴风城港口做了这么多漂亮的工作，这个矮人总应该能对我有一点尊敬了……$B$B我只是想让这尊雕像沿斜坡而上，尽快复位。但她对于工作的每一步都抱怨个不停。实际上，她对每一个问题的解决办法都只有爆炸。我觉得她简直就是个侏儒或者地精。至少侏儒和地精还要比她更淡定一些。$B$B看看我们的工作队伍，简直一点纪律都没有。你知道是为什么？全都是因为她在捣乱！$B$B糟糕的态度，懒惰的工人……这样下去，工作根本没办法迅速完成。', `MaleText_loc5`='本來還以為暴風港的事情處理得那麼漂亮以後，我對這個矮人應該可以放心一點... $B$B我只是要把這個雕像拖上來，盡快弄回原來位置而已。可是不管做什麼她都有得抱怨，而且她對每種問題的解決辦法都是把它給炸了。感覺好像我是在跟個地精還是哥布林共事，而且至少他們還不會天天醉醺醺的咧。$B$B看看我們的工作人員，一點紀律也沒有。原因你知道嗎?就是她在扯我後腿!$B$B態度不佳，工人懶惰...效率一點也沒有辦法快起來。', `MaleText_loc7`='Pensaba que después de hacer tan buen trabajo en el Puerto de Ventormenta podría tomarme un respiro de esa enana... $B$BYo solo quiero subir esa estatua por la rampa para ponerla en su sitio lo más rápido posible. Pero ella tiene quejas para todo. Su solución para todos los problemas es hacerlo saltar por los aires. Es como si estuviera trabajando con un gnomo o un goblin. Pero por lo menos ellos estarían sobrios.$B$BMira a nuestro equipo, no hay disciplina. ¿Sabes por qué? ¡Porque socava mi autoridad!$B$BMala actitud, un equipo de vagos... Esto no va a ser tan fácil de arreglar después de todo.' WHERE `ID`=50270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세나리온 의회는 역사가 깁니다. 우리 트롤들은 최근에 합류했죠.', `MaleText_loc4`='塞纳里奥议会已经有很长的历史了，朋友。而我们巨魔才刚刚成为其中的一员。', `MaleText_loc5`='塞納里奧議會已經存在很久，老兄。我們食人妖是新加入的成員。', `MaleText_loc7`='Hace tiempo que exih''te el Círculo Cenarion, tron. Los trols somo'' nuevos en el grupo.' WHERE `ID`=50271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 쿠키란 게...', `MaleText_loc4`='我想，这就是……', `MaleText_loc5`='我想所謂人生...', `MaleText_loc7`='Supongo que así es...' WHERE `ID`=50272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래 잘 부스러지는 법이지.', `MaleText_loc4`='……就是这样了。', `MaleText_loc5`='...也就是這樣子吧。', `MaleText_loc7`='... la vida.' WHERE `ID`=50273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비겁한 인간 녀석은 이미 꽁무니를 뺐군!', `FemaleText_loc4`='那个可怜的人类逃走了！', `FemaleText_loc5`='可惡的人類跑掉了!', `FemaleText_loc7`='¡El humano lastimero ha escapado!' WHERE `ID`=50274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겁쟁이 같으니!', `FemaleText_loc4`='懦夫！', `FemaleText_loc5`='懦夫!', `FemaleText_loc7`='¡COBARDE!' WHERE `ID`=50275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t 결혼식 하객들이 |cFFFF0000|Hspell:91978|h[차가운 발]|h|r에 걸렸습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t婚礼团队遭受了|cFFFF0000|Hspell:91978|h[临阵畏缩]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t這場婚禮宴會受到|cFFFF0000|Hspell:91978|h[臨陣退縮]的影響|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_frost_frostnova.blp:20|t ¡El séquito nupcial sufre de |cFFFF0000|Hspell:91978|h[Pies fríos]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t 결혼식 하객들이 |cFFFF0000|Hspell:91978|h[차가운 발]|h|r에 걸렸습니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t婚礼团队遭受了|cFFFF0000|Hspell:91978|h[临阵畏缩]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_frost_frostnova.blp:20|t這場婚禮宴會受到|cFFFF0000|Hspell:91978|h[臨陣退縮]的影響|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_frost_frostnova.blp:20|t ¡El séquito nupcial sufre de |cFFFF0000|Hspell:91978|h[Pies fríos]|h|r!' WHERE `ID`=50276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 큰 무기는 이 마을에서는 불법일 텐데...', `MaleText_loc4`='携带一件这么大的武器在这个镇上是不合法的……', `MaleText_loc5`='那麼大把的武器在本鎮應該是違法的吧...', `MaleText_loc7`='No creo que un arma así de grande sea legal en esta ciudad...' WHERE `ID`=50277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 뭔데 상관이야! 난 크기에 상관없이 내 맘에 드는 무기를 사용할 거라고!', `MaleText_loc4`='别想吓唬我！我随便用多么大的武器都可以！', `MaleText_loc5`='你算老幾?老子想用多大把就用多大把!', `MaleText_loc7`='¿Y quién te crees que eres? ¡Yo utilizaré el arma más grande que me dé la gana!' WHERE `ID`=50278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 감시자라고, 너도 잘 알 텐데! 문제를 일으키지 않는 게 좋을 거야. 수상한 행동을 하면 내가 바로...', `MaleText_loc4`='你要明白，我是这里的长官！你最好别惹麻烦，因为你逃不过我的眼睛……', `MaleText_loc5`='我算老幾?你明明知道我是這裡的看守者!你最好是不要給我惹任何麻煩，你只要一想搞鬼我就會知道...', `MaleText_loc7`='¡Yo soy el celador y lo sabes! Más te vale que no armes jaleo, porque sé que en el momento en el que intentes cualquier cosa...' WHERE `ID`=50279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='러셀 브라워가 결혼 축가를 연주하기 시작합니다! 러셀 가까이 가서 재생 효과를 받으십시오!', `MaleText_loc4`='罗素·布鲁尔开始演奏婚礼颂曲！靠近他，就能得到他施放的恢复效果！', `MaleText_loc5`='羅賽爾·布羅爾開始演奏婚禮進行曲!靠近他來獲得回復性的效果!', `MaleText_loc7`='¡Russell Brower comienza a tocar un himno nupcial! ¡Quédate cerca de él para recibir sus efectos regeneradores!', `FemaleText_loc1`='러셀 브라워가 결혼 축가를 연주하기 시작합니다! 러셀 가까이 가서 재생 효과를 받으십시오!', `FemaleText_loc4`='罗素·布鲁尔开始演奏婚礼颂曲！靠近他，就能得到他施放的恢复效果！', `FemaleText_loc5`='羅賽爾·布羅爾開始演奏婚禮進行曲!靠近他來獲得回復性的效果!', `FemaleText_loc7`='¡Russell Brower comienza a tocar un himno nupcial! ¡Quédate cerca de él para recibir sus efectos regeneradores!' WHERE `ID`=50280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 무서워라! 너무 무서워서 바지에 오줌쌀 것 같네!', `MaleText_loc4`='哦，不是那样！看啊，我正在我的靴子里震动……', `MaleText_loc5`='喔，別這樣!你看，我的腳開始發抖了...', `MaleText_loc7`='¡Oh, eso no! Mira, estoy temblando en mis botas...' WHERE `ID`=50281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 잘 알다시피, 이제 다시 파괴 시험을 치르려 한다고.', `MaleText_loc4`='就像你们所知道的那样，我们就要开始下一轮密集毁坏测试了。', `MaleText_loc5`='你們大部分的人都已經知道，我們即將開始新一輪密集的爆破測試。', `MaleText_loc7`='Como ya saben muchos de ustedes, estamos a punto de empezar otra ronda intensiva de pruebas de demoliciones.' WHERE `ID`=50282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭파물 분석가 7명 중 6명이 폭파물 분석가 II가 되기 전에 숨을 거둔다는 것이 사실이긴 하지.', `MaleText_loc4`='这可不容易。实际上，每七名分析师里有六个无法活着晋升到二级爆破分析师。', `MaleText_loc5`='任務難度很高。是真的，每七個分析員當中會有六個沒命升成爆破分析師 II。', `MaleText_loc7`='No será fácil. Es cierto que seos de cada siete analistas no vivirán para llegar a ser Analista de demoliciones II.' WHERE `ID`=50283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 중요한 사실은 우리가 모두 폭발을 사랑해서 여기 모였다는 거야!', `MaleText_loc4`='有一件不能忘记的重要事情，就是我们汇聚在这里，只因为我们都热爱爆炸！', `MaleText_loc5`='但是，別忘了最重要的一件事情:我們會來這裡，就是因為我們熱愛爆破!', `MaleText_loc7`='¡Es importante recordar que todos estamos aquí porque amamos las explosiones!' WHERE `ID`=50284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 우리 모두 멋진 폭발을 일으켜 보자고!', `MaleText_loc4`='所以，我们要让每一次爆炸都有极高的质量！', `MaleText_loc5`='所以請大家一起努力，讓每次爆炸都是精采的爆炸!', `MaleText_loc7`='¡Así que hagamos que cada bombazo sea una explosión de primera calidad!' WHERE `ID`=50285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t해방된 야수가 |cFFFF0000|Hspell:93717|h[어둠의 오라]|h|r를 내뿜기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t脱缰野兽开始释放|cFFFF0000|Hspell:93717|h[黑影光环]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t 釋放的野獸將釋出|cFFFF0000|Hspell:93717|h[黑暗光環]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_holy_prayerofshadowprotection.blp:20|t ¡La bestia desatada empieza a emitir |cFFFF0000|Hspell:93717|h[Aura de la Oscuridad]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t해방된 야수가 |cFFFF0000|Hspell:93717|h[어둠의 오라]|h|r를 내뿜기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t脱缰野兽开始释放|cFFFF0000|Hspell:93717|h[黑影光环]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_holy_prayerofshadowprotection.blp:20|t 釋放的野獸將釋出|cFFFF0000|Hspell:93717|h[黑暗光環]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_holy_prayerofshadowprotection.blp:20|t ¡La bestia desatada empieza a emitir |cFFFF0000|Hspell:93717|h[Aura de la Oscuridad]|h|r!' WHERE `ID`=50286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 네 톱니관절 고릴라, 나한테 있지롱!', `FemaleText_loc4`='哈哈！我得到了你的发条猩猩！', `FemaleText_loc5`='哈哈!我拿到了你的發條玩具大猩猩!', `FemaleText_loc7`='¡Ja, ja! ¡Tengo tu gorila de juguete!' WHERE `ID`=50287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 톱니관절 고릴라가 공원도 훌쩍 뛰어넘을 수 있을까?', `FemaleText_loc4`='我想知道，你的发条猩猩能不能跳过这座花园！', `FemaleText_loc5`='不知道你的發條玩具大猩猩能不能跳過整個花園!', `FemaleText_loc7`='¡Me pregunto si tu gorila de juguete puede saltar hasta el otro lado del parque!' WHERE `ID`=50288;
