UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고성능 엘레멘티움 폭발물이 완성 단계에 있지.', `MaleText_loc4`='新的一批高能源质炸药就要完成了。', `MaleText_loc5`='下一批的高爆源質炸藥就快要完成了。', `MaleText_loc7`='Estamos a punto de completar el siguiente envío de explosivos de elementium de gran potencia.' WHERE `ID`=50296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이번 연구로 우리가 더 작은 폭탄에 더 많은 폭발 가루를 넣을 방법을 찾을 수 있길 간절히 바라고 있다고.', `MaleText_loc4`='希望这个突破性的进展能让我们在更小的炸弹中装入更多的炸药。', `MaleText_loc5`='希望這次的突破能讓我們製造出體積更小、威力更大的炸彈。', `MaleText_loc7`='Espero que esto sea el avance que nos permitirá meter más poder explosivo en una bomba más pequeña.' WHERE `ID`=50297;
