UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 폴짝이 고장내면 안 돼! 나빴어!', `MaleText_loc4`='你不能弄坏跳跳！我不许你这样！', `MaleText_loc5`='你最好不要弄壞跳跳!不公平!', `MaleText_loc7`='¡Más te vale que no rompas a Jum-jump! ¡No es justo!' WHERE `ID`=50300;
