UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리를 그렇게 비틀지 마! 그쪽으로 구부러지는 거 아니야!', `MaleText_loc4`='别再拧他的腿了，它们不能弯成那样！', `MaleText_loc5`='不要再扭他的腿了，它們本來就不能那樣彎!', `MaleText_loc7`='Deja de retorcerle las piernas. ¡No están hechas para doblarlas de esa manera!' WHERE `ID`=50303;
