UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만, 그만! 그렇게 하면 다리가 고장나!', `MaleText_loc4`='停下！你要把他的腿掰断了！', `MaleText_loc5`='住手!你會弄斷它的腿!', `MaleText_loc7`='¡Para! ¡Vas a arrancarle las piernas!' WHERE `ID`=50305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박사님이 너무 겸손하시네. 폭발 가루를 얼마나 많이 넣을 수 있는지 벌써 알고 계실 텐데.', `MaleText_loc4`='那位博士一直都很谦虚。他很清楚该填充多少炸药，甚至不会有一粒的误差。', `MaleText_loc5`='博士太謙虛了。他最清楚該放多少火藥粉了，連差一粒都不會錯。', `MaleText_loc7`='El buen doctor es muy modesto. Sabe perfectamente cuánta pólvora hay que poner en la carga, hasta el último grano.' WHERE `ID`=50306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더마에 다시 와 주셔서 감사합니다, $n 님. 여기저기서 아직 전투가 벌어지고 있지만, 얼라이언스와 함께라면 우리는 유리한 고지를 차지할 수 있을 겁니다.', `MaleText_loc4`='欢迎回到桑德玛尔，$n。战火已经遍及这里的每一个角落，但只要有联盟的帮助，我相信我们一定能占据上风。', `MaleText_loc5`='歡迎回到桑德瑪，$n。戰火依然在各地沿燒，但是有了聯盟的協助，相信我們應該可以佔得上風。', `MaleText_loc7`='De nuevo te doy la bienvenida a Bramal, $n. Las luchas continúan por toda la comarca, pero creo que con la ayuda de la Alianza podremos ganarles por la mano.' WHERE `ID`=50307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 크게 울부짖으며 강력한 발 구르기 공격을 합니다!', `MaleText_loc4`='%s怒吼着，发动了一次凶猛的践踏攻击！', `MaleText_loc5`='%s發出兇狠的咆哮，準備使出驚人的踐踏攻擊!', `MaleText_loc7`='¡%s ruge salvajemente e inicia un enorme ataque pisotón!' WHERE `ID`=50308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박사님은 엄청난 성공을 거둘 거란 걸 이미 알고 계신다고!', `MaleText_loc4`='他已经知道，这将是一次决定性的胜利！', `MaleText_loc5`='他已經知道這一定會超級成功的!', `MaleText_loc7`='¡Él ya sabe que tendrá un éxito aplastante!' WHERE `ID`=50309;
