UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에오인의 잔을 사용해 생명력을 보충하십시오!', `MaleText_loc4`='使用伊欧因的酒杯回复你的生命值！', `MaleText_loc5`='使用伊歐因的酒杯來回復你的生命值!', `MaleText_loc7`='¡Utiliza la jarra de Eoin para reponer tu salud!', `FemaleText_loc1`='에오인의 잔을 사용해 생명력을 보충하십시오!', `FemaleText_loc4`='使用伊欧因的酒杯回复你的生命值！', `FemaleText_loc5`='使用伊歐因的酒杯來回復你的生命值!', `FemaleText_loc7`='¡Utiliza la jarra de Eoin para reponer tu salud!' WHERE `ID`=50311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $c. 우리 와일드해머는 친구에게 박하게 굴지 않는다네.', `MaleText_loc4`='你好，$c。我们蛮锤绝对不会亏待朋友。', `MaleText_loc5`='你好，$c。我們蠻錘矮人會提供獎勵給朋友。', `MaleText_loc7`='Saludos, $c. Nosotros, los Martillo Salvaje, sabemos recompensar a nuestros amigos.' WHERE `ID`=50312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아즈샤라 님께서 여왕이시던 시절, 이곳은 엘프 왕족의 도시였어요. 이 도시에는 오래전에 사라진 전설을 찾아 줄 열쇠와 엄청난 역사적 가치를 지닌 유물이 숨어 있죠.', `FemaleText_loc4`='当艾萨拉还是精灵女王的时候，这里正是精灵皇室的都城之一。这里埋藏着让上古知识重现天日的关键，以及极具历史价值的古代遗物。', `FemaleText_loc5`='在艾薩拉還是女王的時候，這裡曾經是精靈們的一座王都。這座城裡埋藏著解開古老學識的關鍵，以及歷史價值無可估計的文物。', `FemaleText_loc7`='Esta era una de las ciudades reales de los elfos en la época en la que Azshara era reina. En esta ciudad yace escondida la clave del conocimiento perdido hace largo tiempo y de artefactos de valor histórico inimaginable.' WHERE `ID`=50313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부대장님께서 병력을 이끌고 그대가 전에 정찰했던 기지 하나를 공격하러 가셨습니다. 그곳으로 가서 부대장님을 만나십시오.', `FemaleText_loc4`='队长和他的部队已经出发去夺取你曾经为他进行过侦查的一座基地了。你应该赶快去与他们会合。', `FemaleText_loc5`='船長已帶著他的部隊往前推進，要去攻佔你先前幫他偵察的其中一座基地。你應該去和他們會合。', `FemaleText_loc7`='El capitán y sus tropas avanzaron para tomar una de las bases que habías explorado anteriormente para él. Deberías ir a reunirte con ellos.' WHERE `ID`=50314;
