UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사 바틀릿이 이곳에 그리핀 횃대를 마련해 놨습니다. 탈것을 구하는 중이라면, 그와 대화해 보십시오.', `MaleText_loc4`='勇敢的巴特利在这个镇子里建立了狮鹫栖息地。如果你要骑乘狮鹫，就去找他吧。', `MaleText_loc5`='勇敢的巴特勒在這裡鎮上設置了獅鷲獸的巢。如果你想要搭乘，跟他說一聲。', `MaleText_loc7`='Bartlett el Valiente ha montado una percha de grifos en la ciudad. Si necesitas ir a alguna parte, mejor habla con él.', `FemaleText_loc1`='용사 바틀릿이 이곳에 그리핀 횃대를 마련해 놨습니다. 탈것을 구하는 중이라면, 그와 대화해 보십시오.', `FemaleText_loc4`='勇敢的巴特利在这个镇子里建立了狮鹫栖息地。如果你要骑乘狮鹫，就去找他吧。', `FemaleText_loc5`='勇敢的巴特勒在這裡鎮上設置了獅鷲獸的巢。如果你想要搭乘，跟他說一聲。', `FemaleText_loc7`='Bartlett el Valiente ha montado una percha de grifos en la ciudad. Si necesitas ir a alguna parte, mejor habla con él.' WHERE `ID`=50328;
