UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단을 작동시켜 원소의 축복을 받을 수 있습니다. 어둠의 제단은 피하십시오!', `MaleText_loc4`='启动祭坛，获得元素的祝福，但一定要避开致命的暗影祭坛！', `MaleText_loc5`='啟動祭壇來獲得元素的祝福，但是別碰致命的暗影祭壇!', `MaleText_loc7`='¡Activa todos los altares para obtener las bendiciones de los elementos, pero evita el altar de la sombra mortal!', `FemaleText_loc1`='제단을 작동시켜 원소의 축복을 받을 수 있습니다. 어둠의 제단은 피하십시오!', `FemaleText_loc4`='启动祭坛，获得元素的祝福，但一定要避开致命的暗影祭坛！', `FemaleText_loc5`='啟動祭壇來獲得元素的祝福，但是別碰致命的暗影祭壇!', `FemaleText_loc7`='¡Activa todos los altares para obtener las bendiciones de los elementos, pero evita el altar de la sombra mortal!' WHERE `ID`=50333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 잃은 동료의 몸을 오른쪽 클릭하여 일으키십시오!', `MaleText_loc4`='右键点击倒下同伴的躯体，让他们复活！', `MaleText_loc5`='用右鍵點選你倒下同伴的身體來把他們救起來!', `MaleText_loc7`='¡Revive a tu compañero caído haciendo clic derecho en su cuerpo inconsciente!', `FemaleText_loc1`='의식을 잃은 동료의 몸을 오른쪽 클릭하여 일으키십시오!', `FemaleText_loc4`='右键点击倒下同伴的躯体，让他们复活！', `FemaleText_loc5`='用右鍵點選你倒下同伴的身體來把他們救起來!', `FemaleText_loc7`='¡Revive a tu compañero caído haciendo clic derecho en su cuerpo inconsciente!' WHERE `ID`=50334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 이미 가망이 없다.', `FemaleText_loc4`='你已经完了。', `FemaleText_loc5`='你已經輸了。', `FemaleText_loc7`='Ya has perdido.' WHERE `ID`=50335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곰팡이송곳니는 강력하다!!!', `MaleText_loc4`='霉牙最厉害！', `MaleText_loc5`='模牙強壯!', `MaleText_loc7`='¡MOLDECOLMILLO FUERTE!' WHERE `ID`=50336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머를 위하여!', `MaleText_loc4`='为了蛮锤！', `MaleText_loc5`='為了蠻錘!', `MaleText_loc7`='¡Por los Martillo Salvaje!', `FemaleText_loc1`='와일드해머를 위하여!', `FemaleText_loc4`='为了蛮锤！', `FemaleText_loc5`='為了蠻錘!', `FemaleText_loc7`='¡Por los Martillo Salvaje!' WHERE `ID`=50337;
