UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 목숨을 바쳐서라도 네놈을 처치하겠다.', `FemaleText_loc4`='我要杀了你，否则就是我被你杀掉。', `FemaleText_loc5`='我要殺了你，就算我會死也無所謂。', `FemaleText_loc7`='Te mataré o moriré intentándolo.' WHERE `ID`=50339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 잃은 쿠르드란의 몸에서 와일드해머 뿔피리가 떨어집니다!', `MaleText_loc4`='蛮锤号角从库德兰的身上掉落下来！', `MaleText_loc5`='蠻錘的號角從庫德蘭昏迷不醒的身上掉了出來!', `MaleText_loc7`='¡El cuerno de los Martillo Salvaje cae del cuerpo inconsciente de Kurdran!', `FemaleText_loc1`='의식을 잃은 쿠르드란의 몸에서 와일드해머 뿔피리가 떨어집니다!', `FemaleText_loc4`='蛮锤号角从库德兰的身上掉落下来！', `FemaleText_loc5`='蠻錘的號角從庫德蘭昏迷不醒的身上掉了出來!', `FemaleText_loc7`='¡El cuerno de los Martillo Salvaje cae del cuerpo inconsciente de Kurdran!' WHERE `ID`=50340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='死吧！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡Muere!' WHERE `ID`=50341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드라고요? 이 근처에서 드루이드는 보지 못했습니다. 그래도 스톰윈드에서는 드루이드를 찾을 수 있을 겁니다. 스톰윈드에 있는 경비병에게 문의해 보세요.', `MaleText_loc4`='德鲁伊？我在这里从没有见过德鲁伊。不过我相信，你能在暴风城找到他们。你应该问问暴风城的卫兵。', `MaleText_loc5`='德魯伊?我沒在這裡見過德魯伊。雖然我確定你在暴風城可以找到。你可以在暴風城問問守衛。', `MaleText_loc7`='¿Druidas? No he visto druidas por aquí. Aunque estoy seguro de que podrías encontrar alguno en Ventormenta. Deberías preguntar a un guardia en Ventormenta.', `FemaleText_loc1`='드루이드라고요? 이 근처에서 드루이드는 보지 못했습니다. 그래도 스톰윈드에서는 드루이드를 찾을 수 있을 겁니다. 스톰윈드에 있는 경비병에게 문의해 보세요.', `FemaleText_loc4`='德鲁伊？我在这里从没有见过德鲁伊。不过我相信，你能在暴风城找到他们。你应该问问暴风城的卫兵。', `FemaleText_loc5`='德魯伊?我沒在這裡見過德魯伊。雖然我確定你在暴風城可以找到。你可以在暴風城問問守衛。', `FemaleText_loc7`='¿Druidas? No he visto druidas por aquí. Aunque estoy segura de que podrías encontrar alguno en Ventormenta. Deberías preguntar a un guardia en Ventormenta.' WHERE `ID`=50342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 잃은 잴라의 몸에서 용아귀 북이 떨어집니다!', `MaleText_loc4`='龙喉战鼓从扎伊拉身上掉落下来！', `MaleText_loc5`='龍喉的鼓從札伊拉昏迷不醒的身上掉了出來!', `MaleText_loc7`='¡El tambor de los Faucedraco cae del cuerpo inconsciente de Zaela!', `FemaleText_loc1`='의식을 잃은 잴라의 몸에서 용아귀 북이 떨어집니다!', `FemaleText_loc4`='龙喉战鼓从扎伊拉身上掉落下来！', `FemaleText_loc5`='龍喉的鼓從札伊拉昏迷不醒的身上掉了出來!', `FemaleText_loc7`='¡El tambor de los Faucedraco cae del cuerpo inconsciente de Zaela!' WHERE `ID`=50343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 시체를 화살받이로 만들어 주지!', `MaleText_loc4`='我要让利箭插满你的全身！', `MaleText_loc5`='我會用箭把你的屍體射成針氈!', `MaleText_loc7`='¡Llenaré sus cuerpos de flechas!' WHERE `ID`=50344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 고통을 느끼면 난 해방감을 느껴.', `MaleText_loc4`='你的痛苦就是我的慰藉。', `MaleText_loc5`='你的痛苦就是我的解脫。', `MaleText_loc7`='Tu dolor es mi libertad.' WHERE `ID`=50345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 뿔피리를 불어 증원군을 부르십시오!', `MaleText_loc4`='吹响蛮锤号角，召唤援军！', `MaleText_loc5`='吹蠻錘的號角來呼喚援軍!', `MaleText_loc7`='¡Sopla el cuerno de los Martillo Salvaje para pedir refuerzos!', `FemaleText_loc1`='와일드해머 뿔피리를 불어 증원군을 부르십시오!', `FemaleText_loc4`='吹响蛮锤号角，召唤援军！', `FemaleText_loc5`='吹蠻錘的號角來呼喚援軍!', `FemaleText_loc7`='¡Sopla el cuerno de los Martillo Salvaje para pedir refuerzos!' WHERE `ID`=50346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용아귀 북을 쳐서 증원군을 부르십시오!', `MaleText_loc4`='敲响龙喉战鼓，召唤援军！', `MaleText_loc5`='擊打龍喉的鼓來呼喚援軍!', `MaleText_loc7`='¡Toca el tambor de los Faucedraco para pedir refuerzos!', `FemaleText_loc1`='용아귀 북을 쳐서 증원군을 부르십시오!', `FemaleText_loc4`='敲响龙喉战鼓，召唤援军！', `FemaleText_loc5`='擊打龍喉的鼓來呼喚援軍!', `FemaleText_loc7`='¡Toca el tambor de los Faucedraco para pedir refuerzos!' WHERE `ID`=50347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은십자군은 아직 끝나지 않았다! 언데드의 모습도 우리에겐 장애가 되지 않는다!', `MaleText_loc4`='血色十字军还没有完！亡灵只不过是一个小小的挫折！', `MaleText_loc5`='血色十字軍沒有結束!不死只是一時的挫敗!', `MaleText_loc7`='¡La Cruzada Escarlata no ha terminado! ¡La no-muerte es un mero contratiempo!' WHERE `ID`=50348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈은 너무 강합니다! 제단을 이용하는 방법을 알아내 우리를 도와주십시오!', `MaleText_loc4`='他太强大了！你要想办法用这些祭坛为我们扳回优势！', `MaleText_loc5`='他太強大了!你必須想辦法使用祭壇為我們帶來優勢!', `MaleText_loc7`='¡Es demasiado poderoso! ¡Tienes que encontrar la manera de utilizar esos altares para darnos un poco de ventaja!', `FemaleText_loc1`='놈은 너무 강합니다! 제단을 이용하는 방법을 알아내 우리를 도와주십시오!', `FemaleText_loc4`='他太强大了！你要想办法用这些祭坛为我们扳回优势！', `FemaleText_loc5`='他太強大了!你必須想辦法使用祭壇為我們帶來優勢!', `FemaleText_loc7`='¡Es demasiado poderoso! ¡Tienes que encontrar la manera de utilizar esos altares para darnos un poco de ventaja!' WHERE `ID`=50349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지는 다시 일어날 것이다... 새로운 어둠의 군주... 익스라와 함께!', `MaleText_loc4`='天灾军团将再次崛起，他们将得到新的黑暗主人……埃克斯拉尔！', `MaleText_loc5`='天譴軍團終將再起，聽命於全新的主人...伊克斯拉爾!', `MaleText_loc7`='La Plaga se alzará de nuevo, bajo las órdenes de un nuevo maestro oscuro... ¡Ix''lar!' WHERE `ID`=50350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상자다! 여기 부상자가 있습니다! 되도록 빨리 그를 일으켜 주십시오!', `MaleText_loc4`='有人倒下了！我们有人倒下了！尽快让他站起来！', `MaleText_loc5`='有人員傷亡!我們有個人員傷亡!儘快把他救起來!', `MaleText_loc7`='¡Hombre caído! ¡Tenemos un hombre caído! ¡Consigue que regrese a la batalla tan pronto como puedas!', `FemaleText_loc1`='부상자다! 여기 부상자가 있습니다! 되도록 빨리 그를 일으켜 주십시오!', `FemaleText_loc4`='有人倒下了！我们有人倒下了！尽快让他站起来！', `FemaleText_loc5`='有人員傷亡!我們有個人員傷亡!儘快把他救起來!', `FemaleText_loc7`='¡Hombre herido! ¡Tenemos un hombre herido! ¡Consigue que regrese a la batalla tan pronto como puedas!' WHERE `ID`=50351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠르드란이 쓰러졌습니다! 당신이 그를 일으켜주지 않으면 우린 끝장입니다!', `MaleText_loc4`='库德兰倒下了！快点让他恢复过来，继续战斗，否则我们就完了！', `MaleText_loc5`='庫德蘭倒下了!你必須想辦法讓他重新加入戰鬥，否則我們就完蛋了!', `MaleText_loc7`='¡Kurdran ha caído! ¡Tienes que conseguir que regrese a la batalla o será nuestro final!', `FemaleText_loc1`='쿠르드란이 쓰러졌습니다! 당신이 그를 일으켜주지 않으면 우린 끝장입니다!', `FemaleText_loc4`='库德兰倒下了！快点让他恢复过来，继续战斗，否则我们就完了！', `FemaleText_loc5`='庫德蘭倒下了!你必須想辦法讓他重新加入戰鬥，否則我們就完蛋了!', `FemaleText_loc7`='¡Kurdran ha caído! ¡Tienes que conseguir que regrese a la batalla o será nuestro final!' WHERE `ID`=50352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르!', `MaleText_loc4`='Lok''tar ogar！', `MaleText_loc5`='(獸人語)不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar!', `FemaleText_loc1`='록타르 오가르!', `FemaleText_loc4`='Lok''tar ogar！', `FemaleText_loc5`='(獸人語)不勝即亡!', `FemaleText_loc7`='¡Lok''tar ogar!' WHERE `ID`=50353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벤자민 폭스워디와 그의 야수인 꾀돌이는 이곳 황금골에 있는 대장간 뒤편에서 찾을 수 있습니다. 그 친구가 당신을 도와줄 수 있다면 가서 만나보시는 게 좋겠습니다.', `MaleText_loc4`='本杰明·福柯沃斯和他的宠物“狡猾”就在闪金镇铁匠铺的后面。也许你应该去看看他能不能帮你。', `MaleText_loc5`='你可以在閃金鎮鐵匠鋪的後面找到班傑明·佛克斯沃西和他的寵物，狡猾。也許你可以去看看他願不願意幫你。', `MaleText_loc7`='Encontrarás a Benjamin Tratazorro y a su mascota Astuto justo detrás del herrero aquí mismo, en Villadorada. Quizá deberías ir a ver si puede ayudarte.', `FemaleText_loc1`='벤자민 폭스워디와 그의 야수인 꾀돌이는 이곳 황금골에 있는 대장간 뒤편에서 찾을 수 있습니다. 그 친구가 당신을 도와줄 수 있다면 가서 만나보시는 게 좋겠습니다.', `FemaleText_loc4`='本杰明·福柯沃斯和他的宠物“狡猾”就在闪金镇铁匠铺的后面。也许你应该去看看他能不能帮你。', `FemaleText_loc5`='你可以在閃金鎮鐵匠鋪的後面找到班傑明·佛克斯沃西和他的寵物，狡猾。也許你可以去看看他願不願意幫你。', `FemaleText_loc7`='Encontrarás a Benjamin Tratazorro y a su mascota Astuto justo detrás del herrero aquí mismo, en Villadorada. Quizá deberías ir a ver si puede ayudarte.' WHERE `ID`=50354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 놈들, 네 눈알을 파내 주마...', `MaleText_loc4`='我要狠狠地教训你，孬种……', `MaleText_loc5`='沒用的東西，我會把你的眼珠子挖出來...', `MaleText_loc7`='Te arrancaré los ojos, enclenque...' WHERE `ID`=50355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가동.', `MaleText_loc4`='启动。', `MaleText_loc5`='啟動。', `MaleText_loc7`='Activado.' WHERE `ID`=50356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈은 너무 강합니다! 제단을 사용해 원소의 힘을 빌리지 않으면 우리에겐 희망이 없습니다!', `MaleText_loc4`='他太强大了！利用祭坛来操纵元素能量，也许我们还能有取胜的机会！', `MaleText_loc5`='他太強大了!快使用祭壇運用元素的力量，我們也許還有機會!', `MaleText_loc7`='¡Es demasiado poderoso! ¡Utiliza los altares para dominar los poderes de los elementos y quizá tengamos una oportunidad!', `FemaleText_loc1`='놈은 너무 강하군! 제단을 사용해 원소의 힘을 빌리지 않으면 우리에겐 희망이 없네!', `FemaleText_loc4`='他太强大了！利用祭坛来操纵元素能量，也许我们还能有取胜的机会！', `FemaleText_loc5`='他太強大了!快使用祭壇運用元素的力量，我們也許還有機會!', `FemaleText_loc7`='¡Es demasiado poderoso! ¡Utiliza los altares para dominar los poderes de los elementos y quizá tengamos una oportunidad!' WHERE `ID`=50357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상자를 되살려 주십시오! 어서요!', `MaleText_loc4`='你必须去照顾伤员！赶快！', `MaleText_loc5`='你必須儘快照料傷員!快點!', `MaleText_loc7`='¡Debes atender a los heridos! ¡Rápido!', `FemaleText_loc1`='부상자를 일으켜 주게! 어서!', `FemaleText_loc4`='你必须去照顾伤员！赶快！', `FemaleText_loc5`='你必須儘快照料傷員!快點!', `FemaleText_loc7`='¡Debes atender a los heridos! ¡Rápido!' WHERE `ID`=50358;
