UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 주술사 말입니까? 이곳 황금골엔 없습니다.$B$B하지만 스톰윈드의 드워프 지구에 와일드해머 드워프들이라면 당신을 도와줄 수 있을 겁니다.', `MaleText_loc4`='萨满训练师？闪金镇可没有这种人。$B$B不过暴风城矮人区的蛮锤矮人也许能帮助你。', `MaleText_loc5`='薩滿訓練師?閃金鎮上可沒有。$B$B不過暴風城矮人區的蠻錘矮人們也許能夠幫到你。', `MaleText_loc7`='¿Un instructor de chamanes? En Villadorada no hay.$B$BPero los enanos Martillo Salvaje del Distrito de los Enanos de Ventormenta quizá puedan ayudarte.', `FemaleText_loc1`='상급 주술사 말입니까? 이곳 황금골엔 없습니다.$B$B하지만 스톰윈드의 드워프 지구에 와일드해머 드워프들이라면 당신을 도와줄 수 있을 겁니다.', `FemaleText_loc4`='萨满训练师？闪金镇可没有这种人。$B$B不过暴风城矮人区的蛮锤矮人也许能帮助你。', `FemaleText_loc5`='薩滿訓練師?閃金鎮上可沒有。$B$B不過暴風城矮人區的蠻錘矮人們也許能夠幫到你。', `FemaleText_loc7`='¿Un instructor de chamanes? En Villadorada no hay.$B$BPero los enanos Martillo Salvaje del Distrito de los Enanos de Ventormenta quizá puedan ayudarte.' WHERE `ID`=50367;
