UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 저 녀석 왜 이렇게 빨리 죽지? 나만 그렇게 생각하는 건가?', `MaleText_loc4`='喔。是因为我太强了，还是这家伙太容易死了？', `MaleText_loc5`='哇。是只有我，還是那傢伙真的死很快?', `MaleText_loc7`='Vaya. ¿Soy yo o ese ha muerto rápido de verdad?' WHERE `ID`=50400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하!', `MaleText_loc4`='啊，哈哈，哈哈哈！', `MaleText_loc5`='啊—哈哈哈!', `MaleText_loc7`='¡Ahhhhh ha ha haa!' WHERE `ID`=50401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘날의 마법은 천 년 전의 마법에 비하면 보잘것없을지도 모릅니다. 하지만 우리 명가는 여전히 마법에 대한 방대한 지식을 보유하고 있습니다. 가르침을 받을 준비가 되셨습니까?', `MaleText_loc4`='和千年前的魔法相比，今天的这点伎俩实在算不了什么。上层精灵掌握着许多强大的魔法。你是否已经准备好进行学习了？', `MaleText_loc5`='現代的魔法跟千年前根本無法相比。即使如此，我們精靈貴族仍然知道許多秘法的奧妙。你準備好進行學習了嗎?', `MaleText_loc7`='La magia de hoy no es nada en comparación con la de hace miles de años. Sin embargo, los Altonato poseemos un gran conocimiento de lo arcano. ¿Estás $glisto:lista; para aprender?', `FemaleText_loc1`='오늘날의 마법은 천 년 전의 마법에 비하면 보잘것없을지도 모릅니다. 하지만 우리 명가는 여전히 마법에 대한 방대한 지식을 보유하고 있습니다. 가르침을 받을 준비가 되셨습니까?', `FemaleText_loc4`='和千年前的魔法相比，今天的这点伎俩实在算不了什么。上层精灵掌握着许多强大的魔法。你是否已经准备好进行学习了？', `FemaleText_loc5`='現代的魔法跟千年前根本無法相比。即使如此，我們精靈貴族仍然知道許多秘法的奧妙。你準備好進行學習了嗎?', `FemaleText_loc7`='La magia de hoy no es nada en comparación con la de hace miles de años. Sin embargo, los Altonato poseemos un gran conocimiento de lo arcano. ¿Estás $glisto:lista; para aprender?' WHERE `ID`=50402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 내 공격 봤어, 타레나?', `MaleText_loc4`='看到了吗，塔伦纳？', `MaleText_loc5`='你看到了嗎，塔瑞納爾?', `MaleText_loc7`='¿Ves eso, Tarenar?' WHERE `ID`=50403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받아라!', `MaleText_loc4`='轰隆！', `MaleText_loc5`='爆炸!轟!', `MaleText_loc7`='¡Ka-buum!' WHERE `ID`=50404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 부족을 위하여!', `MaleText_loc4`='为了蛮锤！', `MaleText_loc5`='為了蠻錘氏族!', `MaleText_loc7`='¡POR EL CLAN MARTILLO SALVAJE!' WHERE `ID`=50405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 천천히 하면 안 될까요?', `MaleText_loc4`='我们的速度能慢一点吗？', `MaleText_loc5`='我們速度可不可以放慢一點?', `MaleText_loc7`='¿Podríamos ir un poquito más despacio?' WHERE `ID`=50406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 정말 십자군을 위해 싸우고 있다니, 믿을 수가 없어!', `MaleText_loc4`='真无法相信，我们竟然真的是在为十字军而战！', `MaleText_loc5`='不敢相信，我們竟然真的在為十字軍作戰!', `MaleText_loc7`='¡No puedo creer que de verdad estemos luchando por la Cruzada!' WHERE `ID`=50407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라, 수염도 없는 겁쟁아!', `MaleText_loc4`='接着这个吧，你这个没胡子的孬种！', `MaleText_loc5`='看招，你這沒鬍子的孬種!', `MaleText_loc7`='¡Toma esa, cobarde barbilampiño!' WHERE `ID`=50408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 후면 발이 없어서 서 있을 수도 없을걸!', `MaleText_loc4`='我要让你爬也爬不起来！', `MaleText_loc5`='等我招呼完你，你會連個腳指頭都沒得站!', `MaleText_loc7`='¡Cuánto termine contigo no te quedará ni un dedo del pie sobre el que permanecer erguido!' WHERE `ID`=50409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎에 대고 작별 인사나 하시지, 나쁜 놈아!', `MaleText_loc4`='给我躺下吧，恶棍！', `MaleText_loc5`='混蛋，跟你的膝蓋說再見吧!', `MaleText_loc7`='¡Despídete de tus rótulas, tipo duro!' WHERE `ID`=50410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 맛도 모르는 괴물 같으니!', `MaleText_loc4`='这些不喝啤酒的杂种已经让我受够了！', `MaleText_loc5`='我已經受夠了這個沒有酒的混帳!', `MaleText_loc7`='¡Ya he tenido suficiente de estos endogámicos sin cerveza!' WHERE `ID`=50411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_holy_healingaura.blp:20|t남작 애쉬버리가 |cFFFF0000|Hspell:93468|h[집행유예]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_holy_healingaura.blp:20|t灰葬男爵开始施放|cFFFF0000|Hspell:93468|h[怜悯治疗]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_holy_healingaura.blp:20|t艾胥柏利男爵開始施放|cFFFF0000|Hspell:93468|h[暫緩死刑]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_holy_healingaura.blp:20|t¡El barón Ashbury empieza a lanzar |cFFFF0000|Hspell:93468|h[Ejecución pospuesta]|h|r!' WHERE `ID`=50412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시원하게 한 모금 어때?!', `MaleText_loc4`='来一杯清凉醇美的啤酒如何？！', `MaleText_loc5`='來杯清涼爽口的麥酒如何?!', `MaleText_loc7`='¡¿Qué te parecería una buena y refrescante cerveza?!' WHERE `ID`=50413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 사냥도 지겹군... 그냥 죽어 버려라!', `MaleText_loc4`='我已经厌倦了这样的狩猎……去死吧！', `MaleText_loc5`='我已厭倦了這場狩獵...去死吧!', `MaleText_loc7`='Estoy cansado de esta caza... ¡Hora de morir!' WHERE `ID`=50414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳, 카라노스에는 브롤란 게일비어드가 있죠. 당신을 어디든 데려다 줄 수 있어요.', `MaleText_loc4`='嗯，在卡拉诺斯，布洛兰·风须能送你去你想去的地方。', `MaleText_loc5`='對，在卡拉諾斯的布羅蘭·風鬍，能帶你去任何你要想去的地方。', `MaleText_loc7`='Sí, Broland Barbaviento, aquí mismo en Kharanos, puede hacer que llegues a donde necesites ir.', `FemaleText_loc1`='이곳, 카라노스에는 브롤란 게일비어드가 있죠. 당신을 어디든 데려다 줄 수 있어요.', `FemaleText_loc4`='嗯，在卡拉诺斯，布洛兰·风须能送你去你想去的地方。', `FemaleText_loc5`='對，在卡拉諾斯的布羅蘭·風鬍，能帶你去任何你要想去的地方。', `FemaleText_loc7`='Sí, Broland Barbaviento, aquí mismo en Kharanos, puede hacer que llegues a donde necesites ir.' WHERE `ID`=50415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여; 이 소리가 들리는가? 땅에 귀를 대 보시오. 전쟁의 북소리가 울려 퍼지고 있소. 전쟁을 앞둔 이 땅은 기대에 부풀어 전율하고 있지만, 나는 이미 이런 일이 일어날 줄 알고 있었소. 단단히 채비해야 하오, 젊은이. 이 전쟁은 다른 모든 전쟁을 종국에 이르게 할 전쟁이니까. 전장에서 당신과 함께 싸우게 되어 영광이오. 당신도 준비되어 있으리라고 믿겠소.', `MaleText_loc4`='听到了吗，$r？把耳朵贴到地面上。你能听到战鼓的回音么？我一直都能听到这鼓声，感觉到大地在颤抖。我们必须做好准备，年轻人。一切战争都将在这场战争中结束。与你并肩作战将是我的光荣。相信你已经明白了自己该做什么。', `MaleText_loc5`='你聽見了嗎，$r?把耳朵貼在地上。有沒有聽見戰爭的鼓聲在迴盪?大地為之顫抖，而我老早已聽見了它來臨的聲音。我們務必要做好準備，年輕人。因為，這將是一場能結束所有戰爭的戰爭。在你的麾下作戰是種莫大的榮耀，我相信你勢必也會做好準備。', `MaleText_loc7`='¿Lo oyes, $r? Pega la oreja a la tierra. ¿Puedes oír el eco de los tambores de guerra? La tierra tiembla de expectación, sin embargo yo hace tiempo que les oigo venir. Debemos prepararnos, joven, porque esta será la guerra que terminará con todas las guerra. Será un honor servir contigo en el campo de batalla. Confío en que estarás $gpreparado:preparada;.' WHERE `ID`=50416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 여기 우리 조상이 번성했던 장소에서 경계를 서고 있소. 지금까지 나는 평생 자유를 누려 왔소. 이제 나는 내 아이들과 그 아이들의 아이들도 전쟁의 위험에서 벗어나 자유로운 삶을 살 수 있도록 내 할 일을 해야 하오. 파오리스 폐하와 폐하께서 지금까지 우리 백성을 위해 해 주신 영웅적인 일을 찬양할 시간이오. 어떻게 표현해야 할지는 잘 모르겠지만, 난 당신을 믿소, $r. 이제 떠나시오. 혼돈의 빛으로 하늘이 어두워지기 전에 해야 할 일이 아주 많소.
', `MaleText_loc4`='我的祖先在这个地方繁衍生息。现在，我站在这里，等待敌人的到来。我已经渡过了自由的一生。而我要让我的子子孙孙能够继续平安地生活下去，远离战火的摧残。赞美法奥瑞斯国王和他为我们的人民所立下的一切英雄功业。$r，我不知道你的道路在哪里，但我相信，你不会辜负我们的期望。出发吧，$g姐妹:兄弟;，在天空被硝烟染黑之前，还有许多事要做。', `MaleText_loc5`='我會守在先人興盛繁榮的階臺上。過去我一直過著自由和平安樂的生活。我必須盡一切力量讓我的子孫還有子孫的子孫也能過著免於戰爭之恐懼的生活。讚美法歐瑞斯王為我人民所做的一切英勇事蹟。我們的人民。我無法明言原因為何，$r，但我相信你。去吧，$g兄弟:姊妹;，天空戰雲密佈，我們還有許多事情要努力。', `MaleText_loc7`='Permanezco vigilante en estos escalones donde mis ancestros prosperaron. Hasta ahora, nunca he disfrutado de un período de libertad. Debo hacer lo que sea por asegurar que la vida de mis hijos y de los hijos de mis hijos se vea libre de los peligros de la guerra. Alabados sean el Rey Phaoris y sus heroicos esfuerzos por el bien de mi pueblo. Nuestro pueblo. No sé decir por qué, $r, pero confío en ti. Vete, $ghermano:hermana;, hay mucho que hacer antes de que los cielos se oscurezcan con el conflicto.' WHERE `ID`=50417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머 드워프의 할빈 프로스트해머는 썬더브루 양조장에 있어요. 그가 주술사의 길을 가르쳐줄 거예요.', `MaleText_loc4`='哈鲁宾·霜锤，你可以在雷酒酿制厂找到这位蛮锤矮人。他能够传授你萨满之道。', `MaleText_loc5`='你可以在雷酒釀酒廠找到蠻錘部族的哈爾賓·霜錘。他可以教導你薩滿之道。', `MaleText_loc7`='Encontrarás a Halbin Martilloescharcha, del clan Martillo Salvaje, en la Destilería Cebatruenos. Él podrá instruirte sobre lo que necesite saber un chamán.', `FemaleText_loc1`='와일드해머 드워프의 할빈 프로스트해머는 썬더브루 양조장에 있어요. 그가 주술사의 길을 가르쳐줄 거예요.', `FemaleText_loc4`='哈鲁宾·霜锤，你可以在雷酒酿制厂找到这位蛮锤矮人。他能够传授你萨满之道。', `FemaleText_loc5`='你可以在雷酒釀酒廠找到蠻錘部族的哈爾賓·霜錘。他可以教導你薩滿之道。', `FemaleText_loc7`='Encontrarás a Halbin Martilloescharcha, del clan Martillo Salvaje, en la Destilería Cebatruenos. Él podrá instruirte sobre lo que necesite saber un chamán.' WHERE `ID`=50418;
