UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관주인 리니는 마을 중앙의 커다란 건물로 이사 갔다네. 브릴에서 가장 큰 건물이지... 찾기 어렵지 않을 거라네.', `MaleText_loc4`='旅店老板瑞尼已经把店搬到了镇中心的那个大房子里。那是布瑞尔最大的房子……你不会错过的。', `MaleText_loc5`='旅店老闆芮妮搬到城鎮中心的大建築中。它是布瑞爾最大的建築物...很難錯過它。', `MaleText_loc7`='La tabernera Renee se ha mudado a un edificio más grande en el centro de la ciudad. Es el edificio más grande de Rémol... Es muy difícil no verlo.', `FemaleText_loc1`='여관주인 리니는 마을 중앙의 커다란 건물로 이사 갔다네. 브릴에서 가장 큰 건물이지... 찾기 어렵지 않을 거라네.', `FemaleText_loc4`='旅店老板瑞尼已经把店搬到了镇中心的那个大房子里。那是布瑞尔最大的房子……你不会错过的。', `FemaleText_loc5`='旅店老闆芮妮搬到城鎮中心的大建築中。它是布瑞爾最大的建築物...很難錯過它。', `FemaleText_loc7`='La tabernera Renee se ha mudado a un edificio más grande en el centro de la ciudad. Es el edificio más grande de Rémol... Es muy difícil no verlo.' WHERE `ID`=50442;
