UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름 속의 번개여, 황혼의 망치단이 너를 부른다!', `MaleText_loc4`='苍穹之闪电，听从暮光之锤的召唤！', `MaleText_loc5`='雷轟電光，服從暮光之錘的召喚!', `MaleText_loc7`='¡Relámpagos del cielo, obedeced la llamada del Martillo Crepuscular!', `FemaleText_loc1`='구름 속의 번개여, 황혼의 망치단이 너를 부른다!', `FemaleText_loc4`='苍穹之闪电，听从暮光之锤的召唤！', `FemaleText_loc5`='雷轟電光，服從暮光之錘的召喚!', `FemaleText_loc7`='¡Relámpagos del cielo, obedeced la llamada del Martillo Crepuscular!' WHERE `ID`=50463;
