UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 마법사처럼 보이나? 음, 케인 파이어송이 요즘 실험실에서 불쾌한 냄새가 나는 연구에 몰두하고 있다더군.', `MaleText_loc4`='你觉得我像是懂法术的样子吗？不过，我听说凯恩·火歌就在那间实验室里，他总是喜欢鼓捣些让人不舒服的东西。', `MaleText_loc5`='我看起來像是會施法嗎?好吧，我聽說過凱恩·火歌正在實驗室外面搞一些難聞的東西。', `MaleText_loc7`='¿A ti te parece que tengo pinta de lanzar hechizos? Bueno, lo que sí sé es que Cain Pirosón suele andar ahora por el laboratorio, siempre trabajando en algo desagradable.', `FemaleText_loc1`='내가 마법사처럼 보이나? 음, 케인 파이어송이 요즘 실험실에서 불쾌한 냄새가 나는 연구에 몰두하고 있다더군.', `FemaleText_loc4`='你觉得我像是懂法术的样子吗？不过，我听说凯恩·火歌就在那间实验室里，他总是喜欢鼓捣些让人不舒服的东西。', `FemaleText_loc5`='我看起來像是會施法嗎?好吧，我聽說過凱恩·火歌正在實驗室外面搞一些難聞的東西。', `FemaleText_loc7`='¿A ti te parece que tengo pinta de lanzar hechizos? Bueno, lo que sí sé es que Cain Pirosón suele andar ahora por el laboratorio, siempre trabajando en algo desagradable.' WHERE `ID`=50467;
