UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃이... 날름댄다... 태운다... 언제나 태운다...', `MaleText_loc4`='烈火……它们舔舐……它们叮咬……痛苦的叮咬……', `MaleText_loc5`='火焰...擴散...吞噬...不停吞噬...', `MaleText_loc7`='Las llamas... lamen...muerden... siempre muerden...' WHERE `ID`=50470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 빛이 우리 조상들의 영혼을 축복하길. 그분들은 내 아들이 이 신성한 땅에서 잠들게 해주었다.', `MaleText_loc4`='愿圣光祝福我们先祖的灵魂，他们挑选了我的儿子安息在这片应允的神圣土地上。', `MaleText_loc5`='願聖光祝福我們祖先的靈魂，他們讓我的兒子能長眠於這片神聖的土地。', `MaleText_loc7`='Que la Luz bendiga a nuestros antepasados, que han permitido que mi hijo descanse en este suelo sagrado.' WHERE `ID`=50471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이곳, 길니아스의 애국자와 영웅들이 모인 이곳이, 내 아들이 속한 곳이다.', `MaleText_loc4`='他属于这里，这片被吉尔尼斯的英雄和爱国者所环绕的土地。', `MaleText_loc5`='就在這裡，他被屬於他的吉爾尼斯英雄和愛國者所圍繞。', `MaleText_loc7`='Está aquí, adonde pertenece: rodeado de los héroes y patriotas de Gilneas.' WHERE `ID`=50472;
