UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어둠의 사제 베릴을 찾는 거로군. 베릴은 이제 마을 동쪽에 있는 건물에 살고 있다네.', `MaleText_loc4`='啊，你在寻找黑暗牧师贝里尔。他就住在东边的那幢房子里。', `MaleText_loc5`='啊，你想要找黑暗教士貝里爾。他現在正住在東邊的建築中。', `MaleText_loc7`='Ah, buscas al clérigo oscuro Beryl. Ahora reside en el edificio al este.', `FemaleText_loc1`='아, 어둠의 사제 베릴을 찾는 거로군. 베릴은 이제 마을 동쪽에 있는 건물에 살고 있다네.', `FemaleText_loc4`='啊，你在寻找黑暗牧师贝里尔。他就住在东边的那幢房子里。', `FemaleText_loc5`='啊，你想要找黑暗教士貝里爾。他現在正住在東邊的建築中。', `FemaleText_loc7`='Ah, buscas al clérigo oscuro Beryl. Ahora reside en el edificio al este.' WHERE `ID`=50485;
