UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매리언 콜은 여관 계단 밑에 숨어 있다네.', `MaleText_loc4`='马里恩·考尔就藏在这家旅店的楼梯下面。', `MaleText_loc5`='馬里恩·考爾正在旅館樓梯的下面。', `MaleText_loc7`='Marion Call acecha debajo de las escaleras de la posada.', `FemaleText_loc1`='매리언 콜은 여관 계단 밑에 숨어 있다네.', `FemaleText_loc4`='马里恩·考尔就藏在这家旅店的楼梯下面。', `FemaleText_loc5`='馬里恩·考爾正在旅館樓梯的下面。', `FemaleText_loc7`='Marion Call acecha debajo de las escaleras de la posada.' WHERE `ID`=50493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 먹고 싶은데 너무 배부르다. 그냥 없애야지.', `MaleText_loc4`='我想吃你，但我已经饱了。所以我要杀了你。', `MaleText_loc5`='我要吃你，可是我飽了。啊我殺你好了。', `MaleText_loc7`='Yo querer comerte, pero yo lleno. Por tanto, yo matarte.' WHERE `ID`=50494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루퍼트 보흐를 찾고 있는 거로군. 루퍼트는 요즘 여관 지하에 살고 있다네.', `MaleText_loc4`='你要找的是鲁伯特·鲍什。现在他就住在这家旅店的地下室。', `MaleText_loc5`='你想找的是魯伯特·鮑什。他現在住在旅館的地下室。', `MaleText_loc7`='Es a Rupert Boch a quien buscas. Ahora reside en el sótano de la posada.', `FemaleText_loc1`='루퍼트 보흐를 찾고 있는 거로군. 루퍼트는 요즘 여관 지하에 살고 있다네.', `FemaleText_loc4`='你要找的是鲁伯特·鲍什。现在他就住在这家旅店的地下室。', `FemaleText_loc5`='你想找的是魯伯特·鮑什。他現在住在旅館的地下室。', `FemaleText_loc7`='Es a Rupert Boch a quien buscas. Ahora reside en el sótano de la posada.' WHERE `ID`=50495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 오스틸 드 몽을 찾고 있는 거로군. 여관 근처에 있는 시체마차 주변에서 찾을 수 있을 거라네.', `MaleText_loc4`='是的，你要找的是奥斯蒂尔·德·蒙。他就在旅店附近的一辆绞肉车旁边。', `MaleText_loc5`='是的，那個是奧斯蒂爾·德·蒙。你可以找到他在旅館附近其中一台血屍戰車旁邊放哨。', `MaleText_loc7`='Sí, ese es Austin de Mon. Le encontrarás montando guardia al lado de uno de los carros de despojo, cerca de la posada.', `FemaleText_loc1`='그래, 오스틸 드 몽을 찾고 있는 거로군. 여관 근처에 있는 시체마차 주변에서 찾을 수 있을 거라네.', `FemaleText_loc4`='是的，你要找的是奥斯蒂尔·德·蒙。他就在旅店附近的一辆绞肉车旁边。', `FemaleText_loc5`='是的，那個是奧斯蒂爾·德·蒙。你可以找到他在旅館附近其中一台血屍戰車旁邊放哨。', `FemaleText_loc7`='Sí, ese es Austin de Mon. Le encontrarás montando guardia al lado de uno de los carros de despojos, cerca de la posada.' WHERE `ID`=50496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사의 전당 바로 바깥쪽에서 와이번 꼬리 여관을 찾아보게.', `MaleText_loc4`='你要找飞龙之尾？就在勇者大厅外面。', `MaleText_loc5`='在勇者大廳外面找找雙足翼龍之尾酒館。', `MaleText_loc7`='Busca La Cola del Dracoleón, justo en el exterior del Bastión de los Valientes.', `FemaleText_loc1`='용사의 전당 바로 바깥쪽에서 와이번 꼬리 여관을 찾아보게.', `FemaleText_loc4`='你要找飞龙之尾？就在勇者大厅外面。', `FemaleText_loc5`='在勇者大廳外面找找雙足翼龍之尾酒館。', `FemaleText_loc7`='Busca La Cola del Dracoleón, justo en el exterior del Bastión de los Valientes.' WHERE `ID`=50497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골목길 쪽 문에서 다리를 건너게. 고블린이 고함치는 소리를 들어보면 금방 찾을 걸세.', `MaleText_loc4`='就在通向暗巷区大门的桥对面。仔细听那些地精的喊叫就能找到了。', `MaleText_loc5`='那得穿過前往暗巷區門口的橋。聽到哥布林在大喊就是了。', `MaleText_loc7`='Está al otro lado del puente desde la puerta hasta La Calle Mayor. Sigue el sonido de los gritos de los goblins.', `FemaleText_loc1`='골목길 쪽 문에서 다리를 건너게. 고블린이 고함치는 소리를 들어보면 금방 찾을 걸세.', `FemaleText_loc4`='就在通向暗巷区大门的桥对面。仔细听那些地精的喊叫就能找到了。', `FemaleText_loc5`='那得穿過前往暗巷區門口的橋。聽到哥布林在大喊就是了。', `FemaleText_loc7`='Está al otro lado del puente desde la puerta hasta La Calle Mayor. Sigue el sonido de los gritos de los goblins.' WHERE `ID`=50498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창공의 조련사 스카일스는 영원노래 숲으로 나가는 입구에 있소.', `MaleText_loc4`='飞行管理员斯凯勒斯就站在通向永歌森林的大门前。', `MaleText_loc5`='飛行師史利斯就站在永歌森林的門口。', `MaleText_loc7`='El maestro del cielo Skyles suele estar justo delante de la entrada al Bosque Canción Eterna.', `FemaleText_loc1`='창공의 조련사 스카일스는 영원노래 숲으로 나가는 입구에 있소.', `FemaleText_loc4`='飞行管理员斯凯勒斯就站在通向永歌森林的大门前。', `FemaleText_loc5`='飛行師史利斯就站在永歌森林的門口。', `FemaleText_loc7`='El maestro del cielo Skyles suele estar justo delante de la entrada al Bosque Canción Eterna.' WHERE `ID`=50499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가웠습니다. 경계를 늦추지 마십시오, $p.', `FemaleText_loc4`='很高兴见到你。这里对你是安全的，$p', `FemaleText_loc5`='這是我的榮幸。保重了，$p。', `FemaleText_loc7`='Ha sido un placer. Ten cuidado, $p.' WHERE `ID`=50500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기에 있네. 그롬마쉬 요새 입구의 동쪽이지.', `MaleText_loc4`='就在力量谷，格罗玛什要塞入口的东边。', `MaleText_loc5`='那就在葛羅瑪許堡入口東邊的力量谷。', `MaleText_loc7`='Está en el Valle de la Fuerza, al este de la entrada del Fuerte Grommash.', `FemaleText_loc1`='힘의 골짜기에 있네. 그롬마쉬 요새 입구의 동쪽이지.', `FemaleText_loc4`='就在力量谷，格罗玛什要塞入口的东边。', `FemaleText_loc5`='那就在葛羅瑪許堡入口東邊的力量谷。', `FemaleText_loc7`='Está en el Valle de la Fuerza, al este de la entrada del Fuerte Grommash.' WHERE `ID`=50501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기와 방어구가 있는 곳에서 로산 실버블레이드를 찾을 수 있소. 진정한 전사라면 검에서 멀리 떨어지지 않는 법이오.', `MaleText_loc4`='你可以在能找到武器和盔甲的地方找到罗萨恩·银刃。一位战士绝对不会远离他的武器。', `MaleText_loc5`='你可以在找得到武器和護甲的地方找到洛桑。戰士永遠不會離武裝太遠。', `MaleText_loc7`='Encontrarás a Lothan Platahoja donde haya armas y armaduras. Un guerrero nunca se aleja demasiado de su espada.', `FemaleText_loc1`='무기와 방어구가 있는 곳에서 로산 실버블레이드를 찾을 수 있습니다. 진정한 전사라면 검에서 멀리 떨어지지 않는 법입니다.', `FemaleText_loc4`='你可以在能找到武器和盔甲的地方找到罗萨恩·银刃。一位战士绝对不会远离他的武器。', `FemaleText_loc5`='你可以在找得到武器和護甲的地方找到洛桑。戰士永遠不會離武裝太遠。', `FemaleText_loc7`='Encontrarás a Lothan Platahoja donde haya armas y armaduras. Un guerrero nunca se aleja demasiado de su espada.' WHERE `ID`=50502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피는 붉은색입니까?', `MaleText_loc4`='血是红色的么？', `MaleText_loc5`='血是紅的嗎?', `MaleText_loc7`='¿Acaso no es roja la sangre?', `FemaleText_loc1`='피는 붉은색인가요?', `FemaleText_loc4`='血是红色的么？', `FemaleText_loc5`='血是紅的嗎?', `FemaleText_loc7`='¿Acaso no es roja la sangre?' WHERE `ID`=50503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 울부짖습니까?', `MaleText_loc4`='狼会嚎叫？', `MaleText_loc5`='狼會嗥叫嗎?', `MaleText_loc7`='¿Acaso no aúllan los lobos?', `FemaleText_loc1`='늑대는 울부짖나요?', `FemaleText_loc4`='狼会嚎叫？', `FemaleText_loc5`='狼會嗥叫嗎?', `FemaleText_loc7`='¿Acaso no aúllan los lobos?' WHERE `ID`=50504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재들아, 우릴 방해하는 것도 이번이 마지막이다!', `FemaleText_loc4`='这是你最后一次干扰我们的计划了，凡人！', `FemaleText_loc5`='凡人，這是你們最後一次干擾我們的計畫!', `FemaleText_loc7`='¡Es la última vez que interfieren con nuestros planes, mortales!' WHERE `ID`=50505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나락이 너를 삼키리라!', `FemaleText_loc4`='深渊会吞噬你！', `FemaleText_loc5`='死在深淵之下吧!', `FemaleText_loc7`='¡Al Abismo!' WHERE `ID`=50506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살인자는 사람을 살해한 자입니까?', `MaleText_loc4`='杀手会杀人？', `MaleText_loc5`='殺人狂會殺人嗎?', `MaleText_loc7`='¿Acaso no matan los asesinos?', `FemaleText_loc1`='살인자는 사람을 살해한 자입니까?', `FemaleText_loc4`='杀手会杀人？', `FemaleText_loc5`='殺人狂會殺人嗎?', `FemaleText_loc7`='¿Acaso no matan los asesinos?' WHERE `ID`=50507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심연이 너를 기다린다!', `FemaleText_loc4`='无尽深渊在等待着你！', `FemaleText_loc5`='下深淵受死!', `FemaleText_loc7`='¡El Abismo espera!' WHERE `ID`=50508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='울톡, 놈들을 막아라...', `FemaleText_loc4`='乌尔索克，阻止他们……', `FemaleText_loc5`='烏索克，交給你了...', `FemaleText_loc7`='Ulthok, detenlos…' WHERE `ID`=50509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나락의 군대여, 일어나라... 죽음의 물결이 되어 적을 모조리 쓸어버려라!', `FemaleText_loc4`='深渊的大军，化为死亡的狂潮，吞没我们的敌人！', `FemaleText_loc5`='深淵軍團啊，化成死亡浪潮將你們的敵人淹沒吧!', `FemaleText_loc7`='¡Fuerzas de lo profundo, arrasen al enemigo como una marea mortal!' WHERE `ID`=50510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구더기는 시체를 먹습니까?', `MaleText_loc4`='蛆虫会吃尸体？', `MaleText_loc5`='蛆蟲會大啖死屍嗎?', `MaleText_loc7`='¿Acaso los gusanos no se alimentan de cadáveres?', `FemaleText_loc1`='구더기는 시체를 먹나요?', `FemaleText_loc4`='蛆虫会吃尸体？', `FemaleText_loc5`='蛆蟲會大啖死屍嗎?', `FemaleText_loc7`='¿Acaso los gusanos no se alimentan de cadáveres?' WHERE `ID`=50511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무기를 들어라, 부하들아! 얼어붙은 나락에서 일어나라!', `FemaleText_loc4`='武装起来，我的奴仆！从寒冰深渊中崛起吧！', `FemaleText_loc5`='武裝吧，手下們!從冰冷的深海竄起!', `FemaleText_loc7`='¡A las armas, esbirros! ¡Salgan de las profundidades!' WHERE `ID`=50513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침입자를 처단하라! 놈들을 끝없는 어둠 너머로 보내버려라!', `FemaleText_loc4`='毁灭这些入侵者！将他们丢进无尽的黑暗之中！', `FemaleText_loc5`='消滅這些入侵讓他們被渾沌黑暗吞噬!', `FemaleText_loc7`='¡Destruyan a estos intrusos! ¡Que el oscuro más allá los tome!' WHERE `ID`=50514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘로 솟구치는 만큼 영혼이 자유로워지는 일도 없죠. 하늘 위로 날고 싶다면 마을 중앙에 있는 와이번 조련사 타크와 대화하십시오.', `MaleText_loc4`='在空中翱翔的自由是没有任何东西能与之相比的。如果你想飞上天空，可以和村子中央的双足飞龙管理员塔克聊聊。', `MaleText_loc5`='沒有比穿越空中更能釋放靈魂的事情了。如果你也想嘗到飛行的滋味，你可以和村子中央的雙足飛龍管理員塔克說說。', `MaleText_loc7`='No hay nada mejor para el espíritu que elevarte libre por los cielos. Si quieres volar por el aire, tienes que hablar con Tak, el maestro de jinetes de viento, que está en el centro del pueblo.', `FemaleText_loc1`='하늘로 솟구치는 만큼 영혼이 자유로워지는 일도 없죠. 하늘 위로 날고 싶다면 마을 중앙에 있는 와이번 조련사 타크와 대화하십시오.', `FemaleText_loc4`='在空中翱翔的自由是没有任何东西能与之相比的。如果你想飞上天空，可以和村子中央的双足飞龙管理员塔克聊聊。', `FemaleText_loc5`='沒有比穿越空中更能釋放靈魂的事情了。如果你也想嘗到飛行的滋味，你可以和村子中央的雙足飛龍管理員塔克說說。', `FemaleText_loc7`='No hay nada mejor para el espíritu que elevarte libre por los cielos. Si quieres volar por el aire, tienes que hablar con Tak, el maestro de jinetes de viento, que está en el centro del pueblo.' WHERE `ID`=50515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 금이라네. 어서 일하자고.', `MaleText_loc4`='不要浪费时间了，我们去干活吧。', `MaleText_loc5`='我們在浪費時間。快開始工作吧。', `MaleText_loc7`='Estamos perdiendo el tiempo, vamos a trabajar.', `FemaleText_loc1`='시간은 금이라네. 어서 일하자고.', `FemaleText_loc4`='不要浪费时间了，我们去干活吧。', `FemaleText_loc5`='我們在浪費時間。快開始工作吧。', `FemaleText_loc7`='Estamos perdiendo el tiempo, vamos a trabajar.' WHERE `ID`=50516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비록 우리는 고향에서 멀리 떨어져 있지만, 여기서 우리의 역할이 매우 중요하다네.', `MaleText_loc4`='虽然我们距离主岛很远，但我们在这里的任务是很重要的。', `MaleText_loc5`='雖然我們離大陸很遠，但是我們的任務仍然非常重要。', `MaleText_loc7`='Incluso a pesar de que estamos bastante lejos de la isla principal, nuestra misión aquí es importante.', `FemaleText_loc1`='비록 우리는 고향에서 멀리 떨어져 있지만, 여기서 우리의 역할이 매우 중요하다네.', `FemaleText_loc4`='虽然我们距离主岛很远，但我们在这里的任务是很重要的。', `FemaleText_loc5`='雖然我們離大陸很遠，但是我們的任務仍然非常重要。', `FemaleText_loc7`='Incluso a pesar de que estamos bastante lejos de la isla principal, nuestra misión aquí es importante.' WHERE `ID`=50517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길, 더러운 인간 냄새 때문에 역겨워 죽겠다네.', `MaleText_loc4`='嘿，这些肮脏人类的气味每一秒都在让我觉得更难受。', `MaleText_loc5`='嘎，骯髒的人類傳出的味道，每分每秒都會讓我更加憤怒。', `MaleText_loc7`='Puaj, el hedor a sucio humano me hace sentirme peor a cada segundo que pasa.', `FemaleText_loc1`='제길, 더러운 인간 냄새 때문에 역겨워 죽겠다네.', `FemaleText_loc4`='嘿，这些肮脏人类的气味每一秒都在让我觉得更难受。', `FemaleText_loc5`='嘎，骯髒的人類傳出的味道，每分每秒都會讓我更加憤怒。', `FemaleText_loc7`='Puaj, el hedor a sucio humano me hace sentirme peor a cada segundo que pasa.' WHERE `ID`=50518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬에서는 절대 긴장을 늦추면 안 되네. 악랄한 얼라이언스 놈들이 사방에 도사리고 있으니 말이네.', `MaleText_loc4`='这座半岛可不是个渡假的地方，$r。这里到处都能找到肮脏的联盟。', `MaleText_loc5`='這個半島可不是鬧著玩的，$r。整座島上都可以看到該死的聯盟。', `MaleText_loc7`='La península no es un lugar que se deba tomar a la ligera, $r. Encontrarás a esos miserables de la Alianza por toda la isla.', `FemaleText_loc1`='섬에서는 절대 긴장을 늦추면 안 되네. 악랄한 얼라이언스 놈들이 사방에 도사리고 있으니 말이네.', `FemaleText_loc4`='这座半岛可不是个渡假的地方，$r。这里到处都能找到肮脏的联盟。', `FemaleText_loc5`='這個半島可不是鬧著玩的，$r。整座島上都可以看到該死的聯盟。', `FemaleText_loc7`='La península no es un lugar que se deba tomar a la ligera, $r. Encontrarás a esos miserables de la Alianza por toda la isla.' WHERE `ID`=50519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬을 탈환했으니 임무를 시작해야겠소. 우리를 도울 준비가 되면 내게 얘기하시오.', `MaleText_loc4`='现在，我们已经夺回了这座岛，该是开始工作的时候了。等你准备好之后，就来找我吧。', `MaleText_loc5`='現在我們把島搶回來了，是時候開始工作了。等你準備好幫忙，跟我說一聲。', `MaleText_loc7`='Ahora que hemos recuperado la isla, es el momento de ponerse manos a la obra. Habla conmigo de nuevo cuando estés $glisto:lista; para ayudar.', `FemaleText_loc1`='섬을 탈환했으니 임무를 시작해야겠소. 우리를 도울 준비가 되면 내게 얘기하시오.', `FemaleText_loc4`='现在，我们已经夺回了这座岛，该是开始工作的时候了。等你准备好之后，就来找我吧。', `FemaleText_loc5`='現在我們把島搶回來了，是時候開始工作了。等你準備好幫忙，跟我說一聲。', `FemaleText_loc7`='Ahora que hemos recuperado la isla, es el momento de ponerse manos a la obra. Habla conmigo de nuevo cuando estés $glisto:lista; para ayudar.' WHERE `ID`=50520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양길잡이를 찾으시는군요. 태양길잡이 아이오피는 우리의 다른 직업 상급자들과 함께 있습니다.', `MaleText_loc4`='你在寻找烈日行者？烈日行者艾乌比就和我们的许多训练师居住在一起。', `MaleText_loc5`='你在找日行者。日行者伊歐畢和我們其他的訓練師在一起。', `MaleText_loc7`='Buscas a un Caminasol. El Caminasol Iopi vive junto con muchos de nuestros otros instructores.', `FemaleText_loc1`='태양길잡이를 찾으시는군요. 태양길잡이 아이오피는 우리의 다른 직업 상급자들과 함께 있습니다.', `FemaleText_loc4`='你在寻找烈日行者？烈日行者艾乌比就和我们的许多训练师居住在一起。', `FemaleText_loc5`='你在找日行者。日行者伊歐畢和我們其他的訓練師在一起。', `FemaleText_loc7`='Buscas a un Caminasol. El Caminasol Iopi vive junto con muchos de nuestros otros instructores.' WHERE `ID`=50521;
