UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은 구멍은 불결하고 위험한 곳이네, $n. 장비를 완전히 갖추고 전투 준비를 마치기 전까지는 그곳으로 가지 않는 게 좋을 걸세.', `MaleText_loc4`='这个洞穴是个肮脏的地方，$n。除非你已经装备妥当，做好了充分的战斗准备，否则我可不会进去冒险。', `MaleText_loc5`='大坑是個很糟糕的地方，$n。除非裝備齊全，準備妥當，否則我不會下去那裡。', `MaleText_loc7`='El Agujero es un lugar espantoso, $n. Yo no me aventuraría allí abajo a no ser que estuviera bien armado y listo para la batalla.', `FemaleText_loc1`='깊은 구멍은 불결하고 위험한 곳이네, $n. 장비를 완전히 갖추고 전투 준비를 마치기 전까지는 그곳으로 가지 않는 게 좋을 걸세.', `FemaleText_loc4`='这个洞穴是个肮脏的地方，$n。除非你已经装备妥当，做好了充分的战斗准备，否则我可不会进去冒险。', `FemaleText_loc5`='大坑是個很糟糕的地方，$n。除非裝備齊全，準備妥當，否則我不會下去那裡。', `FemaleText_loc7`='El Agujero es un lugar espantoso, $n. Yo no me aventuraría allí abajo a no ser que estuviera bien armada y lista para la batalla.' WHERE `ID`=50524;
