UPDATE `locales_broadcast_text` SET `MaleText_loc1`='D 구역의 악마들은 우리가 여기 도착했을 때부터 우리를 괴롭혀왔네. 자네가 우리를 좀 도와줄 수 있겠나?', `MaleText_loc4`='自从我们到这里来之后，恶魔监狱中的恶魔一直在给我们惹麻烦。你能帮助我们吗？', `MaleText_loc5`='自從我們來到這裡，D區的惡魔就給我們惹了不少麻煩。你可以幫我們嗎?', `MaleText_loc7`='Los demonios del Bloque D llevan poniéndonos las cosas difíciles desde que llegaron aquí. ¿Puedes ayudarnos?', `FemaleText_loc1`='D 구역의 악마들은 우리가 여기 도착했을 때부터 우리를 괴롭혀왔네. 자네가 우리를 좀 도와줄 수 있겠나?', `FemaleText_loc4`='自从我们到这里来之后，恶魔监狱中的恶魔一直在给我们惹麻烦。你能帮助我们吗？', `FemaleText_loc5`='自從我們來到這裡，D區的惡魔就給我們惹了不少麻煩。你可以幫我們嗎?', `FemaleText_loc7`='Los demonios del Bloque D llevan poniéndonos las cosas difíciles desde que llegaron aquí. ¿Puedes ayudarnos?' WHERE `ID`=50528;
