UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의로운 길을 걷고 싶다면 예언자 알숨세와 대화하십시오.', `MaleText_loc4`='如果你在寻找正义的道路，你就应该去和先知艾尔苏谈谈。', `MaleText_loc5`='如果你想要走正義之道，你該和先知艾爾蘇姆談談。', `MaleText_loc7`='Si buscas elegir el camino recto, entonces debes hablar con la vidente Alsoomse.', `FemaleText_loc1`='정의로운 길을 걷고 싶다면 예언자 알숨세와 대화하십시오.', `FemaleText_loc4`='如果你在寻找正义的道路，你就应该去和先知艾尔苏谈谈。', `FemaleText_loc5`='如果你想要走正義之道，你該和先知艾爾蘇姆談談。', `FemaleText_loc7`='Si buscas elegir el camino recto, entonces debes hablar con la vidente Alsoomse.' WHERE `ID`=50530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬을 탈환하는데 도움을 줘서 고맙네, $n. 이제 저주받은 나락 문제를 해결해야겠네.', `MaleText_loc4`='感谢你帮助我们夺回了这座岛，$n。现在，我们需要你继续在咒怨地牢施展你的力量。', `MaleText_loc5`='感謝你幫我們奪回島嶼，$n。我們現在需要你去詛咒深淵幫忙。', `MaleText_loc7`='Gracias por ayudarnos a recuperar la isla, $n. Ahora necesitamos tu ayuda en las Profundidades Malditas.', `FemaleText_loc1`='섬을 탈환하는데 도움을 줘서 고맙네, $n. 이제 저주받은 나락 문제를 해결해야겠네.', `FemaleText_loc4`='感谢你帮助我们夺回了这座岛，$n。现在，我们需要你继续在咒怨地牢施展你的力量。', `FemaleText_loc5`='感謝你幫我們奪回島嶼，$n。我們現在需要你去詛咒深淵幫忙。', `FemaleText_loc7`='Gracias por ayudarnos a recuperar la isla, $n. Ahora necesitamos tu ayuda en las Profundidades Malditas.' WHERE `ID`=50531;
