UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구여. 용서하십시오. 전... 전 너무 약해져서 도움이 못 되겠습니다.', `MaleText_loc4`='感谢你，我的朋友。请原谅我，我……我现在太虚弱了，一点儿忙都帮不上。', `MaleText_loc5`='朋友，謝謝你們。但是對不起，我...我已經弱到沒辦法提供任何協助了。', `MaleText_loc7`='Gracias, amigos. Perdónenme. Me... Me he vuelto muy débil para ayudar.' WHERE `ID`=50533;
