UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 골짜기 은행은 그롬마쉬 요새 입구의 남쪽에 있네. 정문에서 북서쪽이지.', `MaleText_loc4`='力量谷的银行就在格罗玛什要塞入口处的南边。主大门的西北方。', `MaleText_loc5`='力量谷的銀行就在葛羅瑪許堡入口的南邊，城門的西北方。', `MaleText_loc7`='El banco del Valle de la Fuerza está al sur de la entrada del Fuerte Grommash, al noroeste de la Entrada Principal.', `FemaleText_loc1`='힘의 골짜기 은행은 그롬마쉬 요새 입구의 남쪽에 있네. 정문에서 북서쪽이지.', `FemaleText_loc4`='力量谷的银行就在格罗玛什要塞入口处的南边。主大门的西北方。', `FemaleText_loc5`='力量谷的銀行就在葛羅瑪許堡入口的南邊，城門的西北方。', `FemaleText_loc7`='El banco del Valle de la Fuerza está al sur de la entrada del Fuerte Grommash, al noroeste de la Entrada Principal.' WHERE `ID`=50545;
