UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 와이번 조련사를 찾는 게 그렇게 힘든가? 마을 남쪽의 와이번 옆에 부로크가 있잖은가?', `MaleText_loc4`='你找不到飞行管理员？波洛克就在镇子的南端，那些双足飞龙旁边。', `MaleText_loc5`='你自己真的找不到雙足飛龍管理員嗎?布羅克就在城鎮南邊，雙足飛龍的旁邊。', `MaleText_loc7`='¿Acaso te resulta tan difícil dar con un maestro de jinetes de viento por tu cuenta? Burok está en el extremo sur de la ciudad, cerca de los jinetes de viento.', `FemaleText_loc1`='혼자 와이번 조련사를 찾는 게 그렇게 힘든가? 마을 남쪽의 와이번 옆에 부로크가 있잖은가?', `FemaleText_loc4`='你找不到飞行管理员？波洛克就在镇子的南端，那些双足飞龙旁边。', `FemaleText_loc5`='你自己真的找不到雙足飛龍管理員嗎?布羅克就在城鎮南邊，雙足飛龍的旁邊。', `FemaleText_loc7`='¿Acaso te resulta tan difícil dar con un maestro de jinetes de viento por tu cuenta? Burok está en el extremo sur de la ciudad, cerca de los jinetes de viento.' WHERE `ID`=50548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프는 마을의 북쪽에 있는 잘단이 잘 돌보고 있습니다.', `MaleText_loc4`='萨尔达恩把角鹰兽们照顾得很好。他们就在镇子的北部。', `MaleText_loc5`='札爾丹在城鎮北邊，把角鷹獸照顧得很好。', `MaleText_loc7`='Los hipogrifos viven bien atendidos por Zaldaan, en la parte norte de la ciudad.', `FemaleText_loc1`='히포그리프는 마을의 북쪽에 있는 잘단이 잘 돌보고 있습니다.', `FemaleText_loc4`='萨尔达恩把角鹰兽们照顾得很好。他们就在镇子的北部。', `FemaleText_loc5`='札爾丹在城鎮北邊，把角鷹獸照顧得很好。', `FemaleText_loc7`='Los hipogrifos viven bien atendidos por Zaldaan, en la parte norte de la ciudad.' WHERE `ID`=50549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서... 성공입니다! 이 사원 안에 저장된 힘으로 나홈을 지켜낼 수 있어요!', `MaleText_loc4`='它……它起作用了！我们将用这座神殿中的能量守卫纳奥姆！', `MaleText_loc5`='成...成功了!我們可以用儲藏在這座神殿裡的能量來守護納候姆!', `MaleText_loc7`='¡Ha... ha funcionado! ¡Defenderemos Nahom con el poder almacenado dentro de este templo!' WHERE `ID`=50550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지휘관님, 지원군이 네페르세트 부대에 가로막혀 이동하지 못하고 있습니다. 이제 우리 힘으로만 전쟁에서 이겨야 합니다.', `MaleText_loc4`='长官，援军被尼斐塞特的军队阻截了。我们只能靠自己了。', `MaleText_loc5`='長官，援軍被奈斐賽特部隊阻斷，我們只能靠自己了。', `MaleText_loc7`='Señor. Las tropas de Neferset nos han incomunicado de los refuerzos. Estamos solos.' WHERE `ID`=50551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼바위 언덕 병영 밖에 있는 운투와와 얘기해 보게.', `MaleText_loc4`='同剃刀岭营地外面的安苏瓦谈谈。', `MaleText_loc5`='在剃刀嶺軍營的外面和安蘇瓦談談。', `MaleText_loc7`='Habla con Un''Thuwa, en el exterior del Cuartel de Cerrotajo.', `FemaleText_loc1`='칼바위 언덕 병영 밖에 있는 운투와와 얘기해 보게.', `FemaleText_loc4`='同剃刀岭营地外面的安苏瓦谈谈。', `FemaleText_loc5`='在剃刀嶺軍營的外面和安蘇瓦談談。', `FemaleText_loc7`='Habla con Un''Thuwa, en el exterior del Cuartel de Cerrotajo.' WHERE `ID`=50552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 비밀의회가 패배했군. 필멸자들이여, 너희의 명예로운 전투와 투지가 가상하여 나를 직접 상대할 기회를 주겠다. 내 너희의 공격을 기다리고 있다! 오너라!', `MaleText_loc4`='风之议会已经沉沦。而你们光荣的行为和决心为你们赢得了与我一战的权利，凡人们。我一直在等待着你们的进攻！来吧！', `MaleText_loc5`='風之議會已然消散。凡人啊，你們可敬的作為和決心已贏得了與我面對面決戰的權力。我就在我的平台上恭候大駕!來吧!', `MaleText_loc7`='El Cónclave del Viento se ha disipado. Su honorable conducta y determinación les ha permitido ganarse el derecho a enfrentarse a mí en la batalla, mortales. ¡Esperaré su ataque en mi plataforma! ¡Vengan!' WHERE `ID`=50553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 병사. 이제 네 자리로 돌아가도 좋다.', `MaleText_loc4`='感谢你，军士。你可以回到岗位上去了。', `MaleText_loc5`='謝謝你，中士。你可以回你崗位了。', `MaleText_loc7`='Gracias, sargento. Puedes regresar a tu puesto.' WHERE `ID`=50554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식이 아니군요, $n. 이제 우리 힘만으로 나홈을 지킬 방법을 찾아야 합니다.', `MaleText_loc4`='这样不行，$n。我们必须想办法守住纳奥姆。', `MaleText_loc5`='情況不妙，$n。我們得想個辦法守住納候姆。', `MaleText_loc7`='Esto no es bueno, $n. Debemos encontrar la forma de permanecer en Nahom.' WHERE `ID`=50555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 싸움엔 이제 아무 의미도 없다. 그만 끝내야겠군.', `MaleText_loc4`='这样的对峙没有任何意义。我要结束这一切。', `MaleText_loc5`='這場對決已經不具有任何意義。我要就此結束它。', `MaleText_loc7`='Este enfrentamiento ya no tiene ningún objetivo. Le pondré fin.' WHERE `ID`=50556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다. 리라스트라자 님을 찾아가, 우리가 성공했다고 알려 드려라.', `MaleText_loc4`='干得好。找到莉拉斯塔萨，让她知道，我们胜利了。', `MaleText_loc5`='做得好。去找麗菈史卓莎並讓她知道我們成功了。', `MaleText_loc7`='Bien hecho. Busca a Lirastrasza e informa de que hemos tenido éxito.', `FemaleText_loc1`='잘했다. 리라스트라자 님을 찾아가, 우리가 성공했다고 알려 드려라.', `FemaleText_loc4`='干得好。找到莉拉斯塔萨，让她知道，我们胜利了。', `FemaleText_loc5`='做得好。去找麗菈史卓莎並讓她知道我們成功了。', `FemaleText_loc7`='Bien hecho. Busca a Lirastrasza e informa de que hemos tenido éxito.' WHERE `ID`=50557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전을 받아들여 주마, 필멸자여! 너희가 공기의 정령 군주, 알아키르와 마주하고 있음은 알고 있느냐? 날 쓰러뜨리겠다는 꿈도 꾸지 마라!', `MaleText_loc4`='我接受你们的挑战，凡人！要知道，你们面对的是奥拉基尔，风之领主！别以为能打败我！', `MaleText_loc5`='凡人，你們的挑戰已被接受!要知道，你所面對的乃是奧拉基爾，風元素之王!你毫無擊敗我的希望!', `MaleText_loc7`='¡Acepto su desafío, mortales! ¡Saben que se enfrentan a Al''Akir, Señor elemental del aire! ¡No tienen ninguna oportunidad de vencerme!' WHERE `ID`=50565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 암호가 사원 깊숙한 곳에 있는 기계장치에 힘을 불어넣고 있습니다!', `MaleText_loc4`='这段密文描述的正是神殿深处的能量供给系统！', `MaleText_loc5`='那段密碼是藏在神殿深處裡一道威力強大的機制!', `MaleText_loc7`='¡La clave está activando mecanismos en las profundidades del templo!' WHERE `ID`=50568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파리 같은 놈들...', `MaleText_loc4`='就好象在拍虫子……', `MaleText_loc5`='就像打死蚊蟲一樣...', `MaleText_loc7`='Como aplastar insectos...' WHERE `ID`=50569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 말을 믿어 주세요, $p 님. 지금 엄청나게 장엄한 계획의 첫걸음을 내딛는 순간이라고요.', `MaleText_loc4`='相信我的话，$p。你正处于一个宏大无比的地方。而这里是它的第一层！', `MaleText_loc5`='不要懷疑我講的話，$p。你只是在某個超巨大東西的一樓而已!', `MaleText_loc7`='¡Créeme cuando te digo, $p, que estás en el principio de algo grande!' WHERE `ID`=50571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조그만 것이 날 성가시게 하더니.', `MaleText_loc4`='这个小东西不会再给我找麻烦了。', `MaleText_loc5`='這個小東西再也煩不了我。', `MaleText_loc7`='¡$gEste pequeño:Esta pequeña; no me irritará más!' WHERE `ID`=50573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍이 지나가면, 고요가 찾아오는 법...', `MaleText_loc4`='每一场风暴过后，都是静寂……', `MaleText_loc5`='風暴過後，必有寧靜...', `MaleText_loc7`='Después de cada tormenta llega la calma...' WHERE `ID`=50580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 다 되었다, 필멸자여! 너희 삶은 이제 끝이다!', `MaleText_loc4`='你们已经没有时间了，凡人！你们的生命已经不再属于你们！', `MaleText_loc5`='凡人啊，你們時辰已到!性命無保!', `MaleText_loc7`='¡Se han quedado sin tiempo, mortales! ¡Sus vidas están condenadas!' WHERE `ID`=50583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집요한 것들. 이젠 화가 나는구나!', `MaleText_loc4`='你们无谓的顽固激怒了我！', `MaleText_loc5`='無謂的堅持令我震怒!', `MaleText_loc7`='¡Su persistencia fútil aumenta mi ira!' WHERE `ID`=50584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 더는 자제하지 않겠다!', `MaleText_loc4`='够了！我不会再容忍下去了！', `MaleText_loc5`='夠了!我不要再被束縛住了!', `MaleText_loc7`='¡Basta! ¡No permitiré que se me contenga más tiempo!' WHERE `ID`=50585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람이여! 내 명에 따라라!', `MaleText_loc4`='疾风啊！听从我的吩咐！', `MaleText_loc5`='風啊!聽從我的命令!', `MaleText_loc7`='¡Vientos! ¡Obedescan mis órdenes!' WHERE `ID`=50586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍이여! 너를 소환하노라!', `MaleText_loc4`='暴风啊！到我的身边来！', `MaleText_loc5`='風暴啊!我召喚你們來我身邊!', `MaleText_loc7`='¡Tormentas! ¡Las convoco a mi lado!' WHERE `ID`=50587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개여, 내 적을 무찔러라!', `MaleText_loc4`='闪电啊！摧毁我的敌人！', `MaleText_loc5`='閃電啊!消滅我的敵人!', `MaleText_loc7`='¡Relámpagos! ¡Destruid a mis enemigos!' WHERE `ID`=50588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 침입자를 처치하는 명예는 내 몫이다! 놈들의 허약한 몸뚱이는 내 차디찬 바람 속에서 딱딱하게 얼어붙을 것이다!', `MaleText_loc4`='消灭入侵者的荣誉属于我，兄弟们！他们软弱的躯体将在我的凛冽寒风中永远冻结！', `MaleText_loc5`='兄弟們，殺死這些闖入者的榮耀是我的!他們的屍體會被我的冰冷寒風吹到凍結!', `MaleText_loc7`='¡El honor de destruir a los intrusos será mío, hermanos! ¡Sus débiles cuerpos se congelarán a causa del frío de mis vientos helados!' WHERE `ID`=50589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 얼어붙었군.', `MaleText_loc4`='牢牢地被冻住。', `MaleText_loc5`='凍結。', `MaleText_loc7`='Congelado.' WHERE `ID`=50590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 필멸자 하나가 마지막 숨을 쉬었군.', `MaleText_loc4`='又一个凡人完蛋了！', `MaleText_loc5`='又一位凡人喘完最後一口氣!', `MaleText_loc7`='¡Otro mortal que ha respirado por última vez!' WHERE `ID`=50591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예를 버리고 겁쟁이처럼 도망가는 것이냐? 그럼 죽어라!', `MaleText_loc4`='你们抛下自己的荣誉，要像懦夫一样逃跑？那就死吧！', `MaleText_loc5`='你竟捨棄榮耀，逃如懦夫?那就死吧!', `MaleText_loc7`='¿Pisotean su honor y huyen como cobardes? ¡Entonces mueran!' WHERE `ID`=50592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히포그리프를 타고 싶다면 피델리오와 대화하십시오.', `MaleText_loc4`='如果你想要骑角鹰兽，就去找菲德利奥吧。', `MaleText_loc5`='如果你需要使用角鷹獸，跟芬德利歐談談。', `MaleText_loc7`='Si quieres utilizar un hipogrifo, habla con Fidelio.', `FemaleText_loc1`='히포그리프를 타고 싶다면 피델리오와 대화하십시오.', `FemaleText_loc4`='如果你想要骑角鹰兽，就去找菲德利奥吧。', `FemaleText_loc5`='如果你需要使用角鷹獸，跟芬德利歐談談。', `FemaleText_loc7`='Si quieres utilizar un hipogrifo, habla con Fidelio.' WHERE `ID`=50593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 힘이 풀려난다!', `MaleText_loc4`='强猛的烈风啊，显示力量吧！', `MaleText_loc5`='風的力量，吹吧!', `MaleText_loc7`='¡El poder de nuestros vientos, DESATADO!' WHERE `ID`=50594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 조심해라! 이 필멸자들은 위험하다. 나는 잠시 쉬며 힘을 모아야겠다.', `MaleText_loc4`='兄弟们，小心了！这些凡人非常危险。我必须暂停一下，积聚力量。', `MaleText_loc5`='弟兄們，當心!這些凡人相當危險。我必須稍停片刻，聚集我的力量。', `MaleText_loc7`='¡Hermanos, cuidado! Estos mortales son peligrosos. Debo hacer un pausa y reunir mis fuerzas.' WHERE `ID`=50595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자를 몰아내고 주군의 사랑을 얻는 이는 내가 되겠군. 가장 약한 바람이라도 저놈들을 상대하기엔 충분할 터!', `MaleText_loc4`='消灭入侵者的功绩应该属于我。就算是我麾下最弱小的气流，也能让他们死无葬身之地！', `MaleText_loc5`='那就由我來贏得我主的眷顧，驅逐這些闖入者吧。他們會連我最為平靜的風都承受不起!', `MaleText_loc7`='Seré yo quien se gane el favor de nuestro señor expulsando a los intrusos. ¡Mi viento más leve será incluso demasiado fuerte para que puedan soportarlo!' WHERE `ID`=50596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져라, 이방인아!', `MaleText_loc4`='去死吧，入侵者！', `MaleText_loc5`='外人退散!', `MaleText_loc7`='¡Fuera de aquí, $gextraño:extraña;!' WHERE `ID`=50597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 우리 고향을 더럽힐 수 없으리라!', `MaleText_loc4`='别想再玷污我们的家园！', `MaleText_loc5`='你無法再褻瀆我們的家園!', `MaleText_loc7`='¡No permitiré que tu presencia profane nuestro hogar!' WHERE `ID`=50598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람보다 빠를 줄 알았더냐? 크나큰 착각이로군.', `MaleText_loc4`='你以为能跑得比风还快？你犯了致命的错误。', `MaleText_loc5`='要逃過風的吹襲?致命的錯誤。', `MaleText_loc7`='¿Crees que puedes ir más rápido que el viento? Un error fatal.' WHERE `ID`=50599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 힘이 풀려난다!', `MaleText_loc4`='强猛的烈风啊，显示力量吧！', `MaleText_loc5`='風的力量，吹吧!', `MaleText_loc7`='¡El poder de nuestros vientos, DESATADO!' WHERE `ID`=50600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘이 모자라는구나, 형제들이여. 수치스럽지만 당분간 너희에게 기대야겠다.', `MaleText_loc4`='我的力量在衰减，兄弟们。暂时我必须依赖你们了。真是羞耻啊。', `MaleText_loc5`='我的力量衰減了，弟兄們。羞愧的我得暫且仰仗你們的力量。', `MaleText_loc7`='Mi poder se debilita, hermanos. Me avergüenzo de tener que depender de ustedes durante unos instantes.' WHERE `ID`=50601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 가장 강한 바람이니, 침입자들을 조각내는 것도 바로 나이리라!', `MaleText_loc4`='我是最猛烈的风暴，撕碎入侵者的应该是我！', `MaleText_loc5`='既然我是最強的風，就讓我來撕碎這些闖入者吧!', `MaleText_loc7`='¡Yo soy el viento más fuerte, así que seré yo quien destroce a los invasores!' WHERE `ID`=50602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람에 휩쓸렸군!', `MaleText_loc4`='飞走吧！', `MaleText_loc5`='吹走!', `MaleText_loc7`='¡Sopla!' WHERE `ID`=50603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지 같은 놈...', `MaleText_loc4`='只是一团尘埃……', `MaleText_loc5`='只是塵土...', `MaleText_loc7`='Mero polvo...' WHERE `ID`=50604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관 안에 있는 명가의 일원, 이리엔드가 당신을 비전의 길로 안내할 수 있습니다.', `MaleText_loc4`='上层精灵艾莉恩蒂就在这家旅店里。她能传授你奥术的秘密。', `MaleText_loc5`='在旅館裡的精靈貴族伊莉恩德可以教導你秘法之術。', `MaleText_loc7`='La Altonato Irriende, dentro de la posada, podrá instruirte en el arte de lo arcano.', `FemaleText_loc1`='여관 안에 있는 명가의 일원, 이리엔드가 당신을 비전의 길로 안내할 수 있습니다.', `FemaleText_loc4`='上层精灵艾莉恩蒂就在这家旅店里。她能传授你奥术的秘密。', `FemaleText_loc5`='在旅館裡的精靈貴族伊莉恩德可以教導你秘法之術。', `FemaleText_loc7`='La Altonato Irriende, dentro de la posada, podrá instruirte en el arte de lo arcano.' WHERE `ID`=50605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서 도망가느냐, 필멸자여? 여기엔 도망갈 곳도, 숨을 곳도 없다!', `MaleText_loc4`='你们为什么要逃，凡人？这里没有能让你们逃避死亡的地方！', `MaleText_loc5`='凡人吶，何必要逃?這裡無處可躲、無處可逃!', `MaleText_loc7`='¿Por qué huyen, mortales? ¡Aquí no hay ningún lugar adonde puedan huir ni donde puedan esconderse!' WHERE `ID`=50606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들이 너무나도 완강하다, 형제들이여. 나는 저들을 쓰러뜨릴 수 없다. 잠시만 한숨 돌리며 바람을 키우게 해다오.', `MaleText_loc4`='兄弟们，入侵者相当难对付，我还没办法打败他们。让我暂时休息一下，聚集我的暴风力量。', `MaleText_loc5`='弟兄們，入侵者依然挺立，我無法降服他們。請容我稍歇片刻，凝聚風能。', `MaleText_loc7`='Los intrusos no cejan en su empeño, hermanos, no puedo con ellos. Permitidme un breve respiro para reforzar mis vientos.' WHERE `ID`=50607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지, 제가... 제가 함께 있어 드릴게요.', `FemaleText_loc4`='我……我一直都会在你身边，父亲。', `FemaleText_loc5`='我...我會陪著你，父親。', `FemaleText_loc7`='Yo... me quedaré contigo, padre.' WHERE `ID`=50608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 모두 배에 올라타세요!', `FemaleText_loc4`='所有人，立刻登船！', `FemaleText_loc5`='大家快登上船!', `FemaleText_loc7`='¡Todo el mundo a bordo ahora mismo!' WHERE `ID`=50609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가는 남아서 포세이큰이 거점을 확보하지 못하도록 막아야만 하네. 잘 가게, 겐.', `MaleText_loc4`='一定要有人留下来，阻止被遗忘者在这里站稳脚跟。再见了，吉恩。', `MaleText_loc5`='總得有人留下來殿後，阻止被遺忘者建立據點。再見了，吉恩。', `MaleText_loc7`='Alguien debe quedarse para evitar que los Renegados tomen posiciones. Adiós, Genn.' WHERE `ID`=50610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주민들을 새로운 고향으로 안내해 주게나.', `MaleText_loc4`='带领我们的人民去他们的新家园。', `MaleText_loc5`='帶領我們的人民前往他們的新家園。', `MaleText_loc7`='Guía a nuestro pueblo a su nuevo hogar.' WHERE `ID`=50611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크롤리! 자네는 할 만큼 했네. 또다시 자네가 남도록 할 수는 없어...', `MaleText_loc4`='克罗雷！你付出的已经太多了。我不能再把你丢下……', `MaleText_loc5`='克羅雷!你做的已經夠多了，我不能讓你再留下來...', `MaleText_loc7`='¡Crowley! Has hecho suficiente. No puedo permitir que te quedes atrás de nuevo...' WHERE `ID`=50612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 돌아올 것이네, 친구여. 우리 것을 되찾기 위해 돌아올 것이네. 내 약속하지!', `MaleText_loc4`='我们会回来的，亲爱的朋友。我们会回来夺取属于我们的一切。这是我的誓言！', `MaleText_loc5`='我們一定會回來的，朋友。我們一定會回來，奪回我們的東西。我在此發誓!', `MaleText_loc7`='Regresaremos, querido amigo. Regresaremos para tomar lo que es nuestro. ¡Lo juro!' WHERE `ID`=50613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아빠... 우리는 왜 이렇게 힘들게 살아야만 해요? 왜 햇살이 비추는 멋진 곳에 살면 안 되는 거죠? 열대 섬 같은데 살면 안 돼요?', `MaleText_loc4`='父亲……为什么我们一定要承受这样的苦难？为什么我们不能居住在阳光灿烂，土地肥沃的地方？也许我们应该移居到热带岛屿去？', `MaleText_loc5`='父親...為什麼我們要受這麼多苦?為什麼不能住到陽光普照、花草茂盛的地方?像是熱帶島嶼之類的?', `MaleText_loc7`='Padre... ¿Por qué debemos soportar tantas penurias? ¿Por qué no podemos vivir en algún lugar soleado y exuberante? ¿En una isla tropical, quizá?' WHERE `ID`=50614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강해져라, 아들아. 내가 널 나약하게 키우지는 않았다. 의연히 맞서란 말이야!', `MaleText_loc4`='坚强起来，孩子。我把你养大不是要让你成为一个软弱的人！', `MaleText_loc5`='堅強一點，孩子。不要白費了我平日的教養。要勇敢!', `MaleText_loc7`='Tienes que ser fuerte, muchacho. Yo te he educado para que seas duro. ¡Tienes que mostrarte valiente ante la adversidad!' WHERE `ID`=50615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품 보셨어요? 대박을 터뜨릴지도 몰라요... 폭발하지만 않는다면 말이죠.', `MaleText_loc4`='有没有见过我最新的发明？它一定能让你大吃一惊……如果它没有爆炸的话。', `MaleText_loc5`='有看到我最新的發明嗎?一定會大大成功...只要它不會爆炸的話。', `MaleText_loc7`='¿Has visto mi último invento? Va a ser lo más... Si no explota, claro.' WHERE `ID`=50616;
