UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 날 이리도 오래 기다리게 하다니 믿을 수가 없군!', `MaleText_loc4`='他们竟然让我等了这么久，简直令人难以置信！', `MaleText_loc5`='我不敢相信他們讓我等這麼久!', `MaleText_loc7`='¡Es increíble que me hayan hecho esperar tanto!', `FemaleText_loc1`='저들이 날 이리도 오래 기다리게 하다니 믿을 수가 없군요!', `FemaleText_loc4`='他们竟然让我等了这么久，简直令人难以置信！', `FemaleText_loc5`='我不敢相信他們讓我等這麼久!', `FemaleText_loc7`='¡Es increíble que me hayan hecho esperar tanto!' WHERE `ID`=50644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 도시에 들어가기만 하면 된다고. 그게 뭐 이렇게 어려운 거지?', `MaleText_loc4`='为什么连进个城都这么困难？', `MaleText_loc5`='我只是想要進入城裡。有這麼難嗎?', `MaleText_loc7`='Solo quiero entrar en la ciudad. ¿Por qué es tan difícil?', `FemaleText_loc1`='난 이 도시에 들어가기만 하면 돼요. 그게 뭐 이렇게 어려운 건가요?', `FemaleText_loc4`='为什么连进个城都这么困难？', `FemaleText_loc5`='我只是想要進入城裡。有這麼難嗎?', `FemaleText_loc7`='Solo quiero entrar en la ciudad. ¿Por qué es tan difícil?' WHERE `ID`=50645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그나저나 무슨 일이 벌어지고 있는 거지? 저들은 우리에게 아무것도 말해주지 않는데다가 이제 화가 나기 시작하는걸!', `MaleText_loc4`='到底发生了什么事？他们什么也不肯告诉我，搞得我有些生气了！', `MaleText_loc5`='到底發生了什麼事?他們什麼都沒告訴我們，我開始生氣了!', `MaleText_loc7`='¿Qué está pasando? ¡No nos han contado nada y me estoy empezando a enfadar!', `FemaleText_loc1`='그나저나 무슨 일이 벌어지고 있는 거죠? 저들은 우리에게 아무것도 말해주지 않는데다가 이제 화가 나기 시작하거든요!', `FemaleText_loc4`='到底发生了什么事？他们什么也不肯告诉我，搞得我有些生气了！', `FemaleText_loc5`='到底發生了什麼事?他們什麼都沒告訴我們，我開始生氣了!', `FemaleText_loc7`='¿Qué está pasando? ¡No nos han contado nada y me estoy empezando a enfadar!' WHERE `ID`=50646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 수색하겠습니다.', `MaleText_loc4`='我需要搜查你的随身物品。', `MaleText_loc5`='我需要找你。', `MaleText_loc7`='Tengo que registrarte.', `FemaleText_loc1`='당신을 수색하겠습니다.', `FemaleText_loc4`='我需要搜查你的随身物品。', `FemaleText_loc5`='我需要找你。', `FemaleText_loc7`='Tengo que registrarte.' WHERE `ID`=50647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... 힘들군요. 저 없이 계속 가셔야 합니다. 저는 기운을 좀 회복한 후 돌아가도록 하겠습니다.', `MaleText_loc4`='我已经……精疲力尽了，往后你必须独自前进。我会在力量恢复之后自行离开。', `MaleText_loc5`='我...累了。你必須獨自繼續下去。等我力量恢復了我就會離開。', `MaleText_loc7`='Estoy... cansado. Sigan sin mí. Partiré cuando recupere mis fuerzas.' WHERE `ID`=50648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주 좀 없애줘!', `MaleText_loc4`='除掉诅咒！', `MaleText_loc5`='把詛咒拿掉!', `MaleText_loc7`='¡Quítame la maldición!' WHERE `ID`=50649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심원의 영지에서 돌아와 보니, 황혼의 망치단이 여기 기지를 세우고 정령의 차원문을 장악했더군요.$B$B부탁드립니다, $n 님. 뭔진 몰라도 초갈이 황혼의 요새 안에서 하고 있는 일이 끝나기 전에 저들을 멈춰야 합니다!', `FemaleText_loc4`='从深岩之洲回来之后，我们发现暮光之锤已经在这里建立起基地，控制了元素传送门。$B$B$n，请一定阻止他们，不要让古加尔在暮光堡垒中完成他的阴谋！', `FemaleText_loc5`='等我們從地深之源回來之後，我們發現暮光之錘已經在這邊建立一座基地，並且控制了元素傳送門。$B$B拜託，$n，你一定要阻止他們，千萬不能讓丘加利完成他在暮光堡壘裡面進行的邪惡儀式!', `FemaleText_loc7`='Cuando regresamos de Infralar, descubrimos que el Martillo Crepuscular había establecido una base aquí y se había hecho con el control de los portales elementales.$B$B¡Por favor, $n, debes detenerlos antes de que Cho''gall pueda completar lo que sea que está haciendo dentro de El Bastión del Crepúsculo!' WHERE `ID`=50650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그늘안개 해안으로 돌아가야 합니다!', `MaleText_loc4`='你必须返回暮霭海滩！', `MaleText_loc5`='你必須返回暮霧海岸!', `MaleText_loc7`='¡Debes regresar a Costa Noctuniebla!' WHERE `ID`=50651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `MaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `MaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `MaleText_loc7`='Hola, $c. Este es mi consejo para ti: mientras viajas por el mundo, ten cuidado con la magia porque quemará a los que no han sido instruidos en ella.', `FemaleText_loc1`='반가워요, $c님. 제가 조언 하나만 해드릴게요. 세상을 여행할 때 부디 마법을 조심하세요. 마법에 서투른 자들은 새카맣게 타버릴 수 있답니다.', `FemaleText_loc4`='你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，没有受过训练的人会被它烧成灰。', `FemaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `FemaleText_loc7`='Un placer, $c. Mi consejo es el siguiente: en tus viajes por el mundo, ten cuidado con la magia, porque quema a los inexpertos.' WHERE `ID`=50652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가워요, 원소 마법을 배우러 오신 건가요?', `MaleText_loc4`='你好，你是来找魔法导师的吗？', `MaleText_loc5`='你好。你是來學習如何精通魔法的嗎?', `MaleText_loc7`='Saludos. ¿Has venido a dominar los asuntos mágicos?', `FemaleText_loc1`='반가워요, 원소 마법을 배우러 오신 건가요?', `FemaleText_loc4`='你好，你是来找魔法导师的吗？', `FemaleText_loc5`='你好。你是來學習如何精通魔法的嗎?', `FemaleText_loc7`='Saludos. ¿Has venido a dominar las cuestiones mágicas?' WHERE `ID`=50653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애오낙스의 새끼용들에게 밀리기 전에 애오낙스를 처치하십시오!', `MaleText_loc4`='消灭奥伊纳克斯，不要让他的爪牙吞没你！', `MaleText_loc5`='在艾歐納克斯的幼龍擊潰你之前殺了艾歐納克斯!', `MaleText_loc7`='¡Mata a Aeonaxx antes de que sus crías te superen!', `FemaleText_loc1`='애오낙스의 새끼용들에게 밀리기 전에 애오낙스를 처치하십시오!', `FemaleText_loc4`='消灭奥伊纳克斯，不要让他的爪牙吞没你！', `FemaleText_loc5`='在艾歐納克斯的幼龍擊潰你之前殺了艾歐納克斯!', `FemaleText_loc7`='¡Mata a Aeonaxx antes de que sus crías te superen!' WHERE `ID`=50654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈들. 이 필멸의 세계에서 해는 이미 졌다. 혼돈이 다가온다. 종말을 받아들이고 편히 쉬어라.', `MaleText_loc4`='凡人世界的夕阳已经落幕，平静接受你的末日，暮光的时刻来临了。', `MaleText_loc5`='這個凡人的世界已夕陽西下，笨蛋。迎接你們的死亡吧，因為黃昏正要來臨!', `MaleText_loc7`='El sol se ha puesto en este mundo mortal. Acepten su final, ha llegado el crepúsculo.' WHERE `ID`=50655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카드라크, 비밀 신호 가루가 더 필요합니다.', `MaleText_loc4`='我需要更多的秘密信号粉末，卡德拉克。', `MaleText_loc5`='我需要更多秘密信號粉末，卡德拉克。', `MaleText_loc7`='Necesito más polvos de santo y seña, Kadrak.', `FemaleText_loc1`='카드라크, 비밀 신호 가루가 더 필요해요.', `FemaleText_loc4`='我需要更多的秘密信号粉末，卡德拉克。', `FemaleText_loc5`='我需要更多秘密信號粉末，卡德拉克。', `FemaleText_loc7`='Necesito más polvos de santo y seña, Kadrak.' WHERE `ID`=50656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으스스한 모닥불', `MaleText_loc4`='幽暗的营火', `MaleText_loc5`='恐怖篝火', `MaleText_loc7`='Hoguera macabra', `FemaleText_loc1`='으스스한 모닥불', `FemaleText_loc4`='幽暗的营火', `FemaleText_loc5`='恐怖篝火', `FemaleText_loc7`='Hoguera macabra' WHERE `ID`=50661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜드로의 꼬마 해체자', `MaleText_loc4`='兰德鲁的小拆', `MaleText_loc5`='藍卓的XT小小拆解者', `MaleText_loc7`='Mini XT de Landro', `FemaleText_loc1`='랜드로의 꼬마 해체자', `FemaleText_loc4`='兰德鲁的小拆', `FemaleText_loc5`='藍卓的XT小小拆解者', `FemaleText_loc7`='Mini XT de Landro' WHERE `ID`=50662;
