UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1을;를; 보호하던 빛의 봉화가 꺼졌습니다!', `MaleText_loc4`='%s已经不再受到信标的保护了！', `MaleText_loc5`='%s不再受到光明之塔的保護了!', `MaleText_loc7`='¡A %s ya no le protegen sus señales!' WHERE `ID`=50665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t장군 움브리스가 |cFFFF0000|Hspell:74634|h[지상 봉쇄]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t乌比斯将军开始施放|cFFFF0000|Hspell:74634|h[地动山摇]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_earthquake.blp:20|t昂布里斯將軍開始施放|cFFFF0000|Hspell:74634|h[地面封鎖]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_earthquake.blp:20|t¡El general Umbriss comienza a lanzar |cFFFF0000|Hspell:74634|h[Asedio terrestre]|h|r!' WHERE `ID`=50666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마법 파편을 가져가십시오, $n. 저도 파편의 짝을 통해 드워프들이 하는 얘기를 들을 수 있을 겁니다.', `MaleText_loc4`='拿上这块魔法碎片，$n。这样我就能通过和它匹配的另一块碎片亲耳听到矮人们的声音了。', `MaleText_loc5`='這片附過魔的裂片讓你帶在身上，$n。這樣我自己就能透過另外一片知道矮人在說些什麼。', `MaleText_loc7`='Toma este fragmento encantado, $n. A través de su gemelo, podré oír a los enanos yo mismo.' WHERE `ID`=50667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 버러지 같으니... 오직 우리만 실리시드에게 명령을 내릴 수 있다!', `MaleText_loc4`='该死的虫子……只有我们能指挥这些异种虫！', `MaleText_loc5`='卑鄙的小蟲...除了我們之外沒人能命令異種蟲!', `MaleText_loc7`='Gusano despreciable... ¡Nadie salvo nosotros liderará a los silítidos!' WHERE `ID`=50669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Hitem:63269|h|cFFFFFFFF[조작된 노움 주사위]|r|h를 휙 던집니다.', `MaleText_loc4`='随意地掷出他的|Hitem:63269|h|cFFFFFFFF[侏儒老千的骰子]|r|h。', `MaleText_loc5`='輕鬆地擲出他的|Hitem:63269|h|cFFFFFFFF[灌鉛地精骰子]|r|h。', `MaleText_loc7`='casualmente tira su |Hitem:63269|h|cFFFFFFFF[Dado gnómico cargado]|r|h.', `FemaleText_loc1`='|Hitem:63269|h|cFFFFFFFF[조작된 노움 주사위]|r|h를 휙 던집니다.', `FemaleText_loc4`='随意地掷出他的|Hitem:63269|h|cFFFFFFFF[侏儒老千的骰子]|r|h。', `FemaleText_loc5`='輕鬆地擲出他的|Hitem:63269|h|cFFFFFFFF[灌鉛地精骰子]|r|h。', `FemaleText_loc7`='casualmente tira su |Hitem:63269|h|cFFFFFFFF[Dado gnómico cargado]|r|h.' WHERE `ID`=50670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 이 고통에서 나를 풀어 주게!', `MaleText_loc4`='帮我解除这种折磨吧！', `MaleText_loc5`='別再讓我受罪了!', `MaleText_loc7`='¡Libérame de esta tormenta!' WHERE `ID`=50671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 죗값은 충분히 치르지 않았는가?', `MaleText_loc4`='难道我付出的一切，还不够赎清我的罪行吗？', `MaleText_loc5`='我為我的罪所付出的代價還不夠嗎?', `MaleText_loc7`='¿Acaso no he pagado ya suficiente por mis pecados?' WHERE `ID`=50672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 우리 부족을 위해 한 일이었네!', `MaleText_loc4`='我只是为了我的部族才会这样做！', `MaleText_loc5`='我是為了我的氏族才那樣做的!', `MaleText_loc7`='¡Solo lo hice por mi clan!' WHERE `ID`=50673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 누구라고 감히 날 판단하겠다는 건가?', `MaleText_loc4`='你是谁，竟然能审判我？', `MaleText_loc5`='你是誰?你憑什麼在這邊數落我?', `MaleText_loc7`='¿Quién eres tú para juzgarme?' WHERE `ID`=50674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 경고를... 하이브아쉬...', `MaleText_loc4`='我必须警告……亚什虫巢……', `MaleText_loc5`='我必須去警告...亞什蟲巢...', `MaleText_loc7`='Debo avisar a... Colmen''Ashi...' WHERE `ID`=50675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 카드로스의 모루로 날려 버릴 테니 꽉 잡아라!', `MaleText_loc4`='勇士们，抓紧，我们要飞回卡德罗斯的铁砧了！', `MaleText_loc5`='抓好了，勇士們。我這就送你們飛回卡德羅斯的鐵砧!', `MaleText_loc7`='¡Campeones, agarraos mientras os llevo volando de regreso a Yunque de Khardros!' WHERE `ID`=50676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창살문을 여시겠습니까?', `MaleText_loc4`='要把闸门打开吗？', `MaleText_loc5`='你要打開鐵柵門嗎?', `MaleText_loc7`='¿Quieres que se abra el rastrillo?' WHERE `ID`=50677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열겠습니다.', `MaleText_loc4`='打开。', `MaleText_loc5`='打開它。', `MaleText_loc7`='Ábrelo.', `FemaleText_loc1`='열겠습니다.', `FemaleText_loc4`='打开。', `FemaleText_loc5`='打開它。', `FemaleText_loc7`='Ábrelo.' WHERE `ID`=50678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라, 황혼의 종복들아. (들어! 듣고 복종해!)', `MaleText_loc4`='听我的号令，暮光的爪牙们。（听从！绝对的服从！）', `MaleText_loc5`='聽我說，暮光之僕。(聽!聽好，服從!)', `MaleText_loc7`='Escuchadme, esbirros del Crepúsculo. (¡Escuchad! ¡Escuchad y obedeced!)' WHERE `ID`=50679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석고 나약한 얼라이언스와 호드 멍청이들이 지금 황혼의 고원으로 몰려오고 있다. (멍청이들! 어리석고 나약하고 맛있는...)', `MaleText_loc4`='就在我说话的时候，愚蠢而软弱的联盟与部落正在接近暮光高地。（愚蠢！盲目！软弱！而且美味……）', `MaleText_loc5`='在我們交談的同時，聯盟和部落的弱雞蠢蛋們正前往暮光高地。(笨蛋!又盲又弱又可口...)', `MaleText_loc7`='Mientras hablamos, esos estúpidos debiluchos de la Alianza y la Horda se abren camino hasta las Tierras Altas Crepusculares. (¡INSENSATOS! Ciegos y débiles y sabrosos...)' WHERE `ID`=50680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 너희의 임무를 잊지 마라! 이 세계의 지긋지긋한 영웅들이 이 황폐한 불모지로 눈길을 돌리더라도 의식을 멈추지 마라.', `MaleText_loc4`='不要忘记在这里的任务！当那些爱管闲事的英雄们仍然对这片荒凉废土视而不见的时候，你们必须将仪式进行下去。', `MaleText_loc5`='別忘了你該做些什麼!趁那些愛管閒事的英雄看不見這塊荒地的時候繼續進行儀式。', `MaleText_loc7`='¡No olviden su cometido! Continuen con los rituales mientras los entrometidos héroes del mundo dan la espalda a estos baldíos desolados.' WHERE `ID`=50681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희생자가 생길 때마다 더 많은 주인님의 사자가 이 세계로 들어올 것이다. (곤충 집이 미친 듯이 노래한다, 혼돈의 노래를!)', `MaleText_loc4`='每一个祭品都会让更多主人的使者进入这个世界。（巢穴一片疯狂，一片混乱！）', `MaleText_loc5`='每一分犧牲都能將更多主人的信使帶入這個世界。(蟲巢吟唱著狂亂之歌，吟唱著混沌之歌!)', `MaleText_loc7`='Cada sacrificio trae cada vez más heraldos del maestro a este mundo. (¡Las colmenas zumban por la locura, el caos!)' WHERE `ID`=50682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 곤충 집 안에 있는 주인님의 살과 피로 희생자들을 데려가라. (아직도 굶주렸다...)', `MaleText_loc4`='将这些祭品送到其它巢穴中主人的血肉那里去。（它们已经饥渴难耐……）', `MaleText_loc5`='在其他蟲巢中讓這些犧牲品化為主宰的血肉。(他們餓了...)', `MaleText_loc7`='Traed los sacrificios a la carne y la sangre del maestro, dentro de las otras colmenas. (Tienen hambre...)' WHERE `ID`=50683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 공격이 끝나간다. 놈들의 종말이 눈앞에 있다. (모두 끝이다! 막이 내린다!) 날 실망시키지 마라.', `MaleText_loc4`='万物的毁灭已经临近。覆亡就在眼前。（万物的毁灭！帷幕已落下！）不要让我失望。', `MaleText_loc5`='一切都將邁向終點，壞滅已近在眼前。(結束一切!落幕!)別讓我失望。', `MaleText_loc7`='Se acerca el fin de todo. La destrucción está próxima. (¡El fin de todo! ¡Cae el telón!) No me falléis.' WHERE `ID`=50684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 머리가...', `MaleText_loc4`='天哪，我的头……', `MaleText_loc5`='喔...我的頭啊...', `MaleText_loc7`='Ohh, mi cabeza...', `FemaleText_loc1`='아, 머리가...', `FemaleText_loc4`='天哪，我的头……', `FemaleText_loc5`='喔...我的頭啊...', `FemaleText_loc7`='Ohh, mi cabeza...' WHERE `ID`=50685;
