UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 족쇄를 채우지도 않았는데... 제가 잠든 것도 아니고...', `MaleText_loc4`='我竟然没有戴着镣铐……我应该不是在睡觉吧……', `MaleText_loc5`='我身上甚至沒有什麼鐐銬限制行動...不過我不認為我是在做夢...', `MaleText_loc7`='Ni siquiera estaba encadenado... pero no creo que estuviera dormido...', `FemaleText_loc1`='저한테 족쇄를 채우지도 않았는데... 제가 잠든 것도 아니고...', `FemaleText_loc4`='我竟然没有戴着镣铐……我应该不是在睡觉吧……', `FemaleText_loc5`='我身上甚至沒有什麼鐐銬限制行動...不過我不認為我是在做夢...', `FemaleText_loc7`='Ni siquiera estaba encadenada... pero no creo que estuviera dormida...' WHERE `ID`=50687;
