UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 상처받은 단상으로 날려 버릴 테니 꽉 잡아라!', `MaleText_loc4`='勇士们，抓紧，我们要飞回焰痕平台了！', `MaleText_loc5`='抓好了，勇士們。我這就送你們飛回傷痕殿堂!', `MaleText_loc7`='¡Campeones, agarraos mientras os llevo volando de regreso al Bancal Rajado!' WHERE `ID`=50689;
