UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 친구, 잘 지내지?', `MaleText_loc4`='你好，$g勇士:女士;出了什么事？', `MaleText_loc5`='嗨呀，$g勇士:女士;最近如何?', `MaleText_loc7`='Buenas, $gchaval:señorita;. ¿Qué te cuentas?' WHERE `ID`=50704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 에이스. 잃어버린 섬에서 난파당한 일 기억나세요?', `MaleText_loc4`='你好，王牌战士。还记得我们在失落群岛落难的时候吗？', `MaleText_loc5`='嗨呀，愛司。記得我們在失落群島上發生船難的事嗎?', `MaleText_loc7`='Hola, As. ¿Recuerdas cuando naufragamos en Las Islas Perdidas?', `FemaleText_loc1`='안녕하세요, 에이스. 잃어버린 섬에서 난파당한 일 기억나세요?', `FemaleText_loc4`='你好，王牌战士。还记得我们在失落群岛落难的时候吗？', `FemaleText_loc5`='嗨呀，愛司。記得我們在失落群島上發生船難的事嗎?', `FemaleText_loc7`='Hola, As. ¿Recuerdas cuando naufragamos en Las Islas Perdidas?' WHERE `ID`=50705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥, 이제 나에게 남은 폭탄이 없을 거라 생각하는 건 아니겠지, 응?', `FemaleText_loc4`='你不会真的以为我只布置了一批炸药吧，对不对？', `FemaleText_loc5`='你不會真的以為我只設置了一組的炸藥，對吧?', `FemaleText_loc7`='No habrán pensado que solo iba a colocar una carga de explosivos, ¿verdad?' WHERE `ID`=50706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여! 어서 와, 얼간이!', `MaleText_loc4`='你好，混蛋！', `MaleText_loc5`='哈囉，笨蛋!', `MaleText_loc7`='¡Hola, tú!' WHERE `ID`=50707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 수갑을 채워. 하지만 기억해둬, 갤리윅스. 언젠가 너도 수갑을 찰 날이 올 거야!', `MaleText_loc4`='好吧，上镣铐吧。但给我记住，加里维克斯，你也会有你的那一份！', `MaleText_loc5`='好吧，鎖上鐐銬吧。加里維克斯你聽著，你遲早也會戴上的!', `MaleText_loc7`='De acuerdo, ponle las esposas. Pero entérate bien, Gallywix, ¡recibirás tu merecido!', `FemaleText_loc1`='좋아, 수갑을 채워. 하지만 기억해둬, 갤리윅스. 언젠가 너도 수갑을 찰 날이 올 거야!', `FemaleText_loc4`='好吧，上镣铐吧。但给我记住，加里维克斯，你也会有你的那一份！', `FemaleText_loc5`='好吧，鎖上鐐銬吧。加里維克斯你聽著，你遲早也會戴上的!', `FemaleText_loc7`='De acuerdo, ponle las esposas. Pero entérate bien, Gallywix, ¡recibirás tu merecido!' WHERE `ID`=50708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이곳이오, $n! 우리가 지켜야 할 곳은 바로 이곳이오!', `MaleText_loc4`='就是这样，$n！这里就是我们的阵地！', `MaleText_loc5`='就是這裡，$n!我們在這裡進行死戰!', `MaleText_loc7`='¡Este es el momento, $n! ¡Aquí es donde plantaremos cara!' WHERE `ID`=50710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='결국 일이 이렇게 되어버렸지만, 우리 길니아스인들은 희망을 버리지 않았어요.', `FemaleText_loc4`='我们终于成功了。我们吉尔尼斯人从没有放弃过希望。', `FemaleText_loc5`='在經歷過這一切之後，我們吉爾尼斯人還沒放棄希望。', `FemaleText_loc7`='A pesar de todo lo que hemos sufrido, los gilneanos no hemos renunciado a la esperanza.' WHERE `ID`=50711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어스름 안식처로 어떻게 갔는지 기억나지 않습니다. 아는 게 있으면 말해 주십시오.', `MaleText_loc4`='我不太记得是如何到达暮湾镇的。把你知道的都告诉我。', `MaleText_loc5`='我不太記得我怎麼來到暮色港的。告訴我你所知道的一切。', `MaleText_loc7`='No recuerdo mucho sobre cómo llegué a Refugio del Ocaso. Cuéntame lo que sepas.', `FemaleText_loc1`='어스름 안식처로 어떻게 갔는지 기억나지 않아요. 아는 게 있으면 말해 주세요.', `FemaleText_loc4`='我不太记得是如何到达暮湾镇的。把你知道的都告诉我。', `FemaleText_loc5`='我不太記得我怎麼來到暮色港的。告訴我你所知道的一切。', `FemaleText_loc7`='No recuerdo mucho sobre cómo llegué a Refugio del Ocaso. Cuéntame lo que sepas.' WHERE `ID`=50712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_totemofwrath.blp:20|t 전투 절단기 5000의 |cFFFF0000|Hspell:88522|h[안전 제한 작동 정지]|h|r가 활성화되었습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_totemofwrath.blp:20|t死神5000型|cFFFF0000|Hspell:88522|h[安全限制离线]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_totemofwrath.blp:20|t敵人收割者5000|cFFFF0000|Hspell:88522|h[關閉安全裝置]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_totemofwrath.blp:20|t ¡El Siegaenemigos 5000 tiene las |cFFFF0000|Hspell:88522|h[Restricciones de seguridad desactivadas]|h|r!' WHERE `ID`=50713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네파리안을 불러 주십시오!', `MaleText_loc4`='请刷新奈法利安', `MaleText_loc5`='麻煩生成奈法利安!', `MaleText_loc7`='¡Aparece Nefarian, por favor!', `FemaleText_loc1`='네파리안을 불러 주세요!', `FemaleText_loc4`='请刷新奈法利安', `FemaleText_loc5`='麻煩生成奈法利安!', `FemaleText_loc7`='¡Aparece Nefarian, por favor!' WHERE `ID`=50714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순간이동기는 최근 다양한 물품을 광산 안으로 운반하는 데 사용된 듯합니다.', `MaleText_loc4`='看起来，这个传送设备最近被用来将物资传送到矿井深处。', `MaleText_loc5`='這個傳送裝置看起來最近剛被用來把一些貨物送到礦坑的更深處。', `MaleText_loc7`='Parece que este dispositivo de teletransporte ha sido utilizado recientemente para teletransportar varios objetos a lo más profundo de la mina.', `FemaleText_loc1`='이 순간이동기는 최근 다양한 물품을 광산 안으로 운반하는 데 사용된 듯합니다.', `FemaleText_loc4`='看起来，这个传送设备最近被用来将物资传送到矿井深处。', `FemaleText_loc5`='這個傳送裝置看起來最近剛被用來把一些貨物送到礦坑的更深處。', `FemaleText_loc7`='Parece que este dispositivo de teletransporte ha sido utilizado recientemente para teletransportar varios objetos a lo más profundo de la mina.' WHERE `ID`=50715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''목재류''라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下贴有“树木及木材”标签的按钮。', `MaleText_loc5`='按下標記「木與柴」的按鈕。', `MaleText_loc7`='Pulsa el botón etiquetado como "Madera y tablones".', `FemaleText_loc1`='''목재류''라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下贴有“树木及木材”标签的按钮。', `FemaleText_loc5`='按下標記「木與柴」的按鈕。', `FemaleText_loc7`='Pulsa el botón etiquetado como "Madera y tablones".' WHERE `ID`=50716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''금속류''라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下贴有“金属碎片”标签的按钮。', `MaleText_loc5`='按下標記「鐵與廢料」的按鈕。', `MaleText_loc7`='Pulsa el botón etiquetado como "Metal y chatarra".', `FemaleText_loc1`='''금속류''라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下贴有“金属碎片”标签的按钮。', `FemaleText_loc5`='按下標記「鐵與廢料」的按鈕。', `FemaleText_loc7`='Pulsa el botón etiquetado como "Metal y chatarra".' WHERE `ID`=50717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''함선 부품''이라고 쓰인 단추를 누릅니다.', `MaleText_loc4`='按下贴有“飞船部件”标签的按钮。', `MaleText_loc5`='按下標記「船體零件」的按鈕。', `MaleText_loc7`='Pulsa el botón etiquetado como "Piezas de barco".', `FemaleText_loc1`='''함선 부품''이라고 쓰인 단추를 누릅니다.', `FemaleText_loc4`='按下贴有“飞船部件”标签的按钮。', `FemaleText_loc5`='按下標記「船體零件」的按鈕。', `FemaleText_loc7`='Pulsa el botón etiquetado como "Piezas de barco".' WHERE `ID`=50718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 펄펄 끓는 용암의 힘을 빌려 되살아났습니다!', `MaleText_loc4`='%s被沸腾岩浆的熔火之力复活了！', `MaleText_loc5`='%s被沸騰岩漿的熔火能量復活了!', `MaleText_loc7`='¡%s revive gracias a la energía fundida del magma hirviendo!' WHERE `ID`=50720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님.', `MaleText_loc4`='你好，$C。', `MaleText_loc5`='你好，$c。', `MaleText_loc7`='Saludos, $c.' WHERE `ID`=50721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 머리야... 오늘 며칠이죠?', `MaleText_loc4`='哦，我的头……今天是什么日子？', `MaleText_loc5`='喔好痛，我的頭...今天是幾號?', `MaleText_loc7`='Auch, mi cabeza... ¿Qué día es hoy?' WHERE `ID`=50722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 눈 부신 빛은 어디서 오는 거지? 아아악, 저리 치우세요!', `MaleText_loc4`='这些亮光是从哪里来的？啊，赶快让它消失！', `MaleText_loc5`='這亮光打哪來的?啊啊啊，拿開!', `MaleText_loc7`='¿De dónde procede esa luz tan clara? ¡Ahhh, aléjala de mí!' WHERE `ID`=50723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 사탕을 먹었다고 말했습니다...', `MaleText_loc4`='他说他有糖……', `MaleText_loc5`='他說他有糖果...', `MaleText_loc7`='Dijo que tenía caramelos...' WHERE `ID`=50724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시네스트라가 고동치는 황혼의 알에서 에너지를 빨아들이자, 알을 감싸고 있던 보호막이 사라집니다!', `FemaleText_loc4`='当希奈丝特拉操纵这些脉动的暮光之卵的能量时，卵的保护屏障消失了！', `FemaleText_loc5`='在賽絲特拉控制那些跳動的暮光蛋的力量同時，保護那些蛋的屏障消散了!', `FemaleText_loc7`='¡La barrera que protege los huevos Crepusculares con pulso desaparece cuando Sinestra utiliza su poder!' WHERE `ID`=50725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_whirlwind.blp:10|t 세상에! 제가 |cFFFF0000|Hspell:88481|h[과출력]|h|r을 시전하고 있습니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_whirlwind.blp:10|t天哪，我要施放|cFFFF0000|Hspell:88481|h[超速]|h|r了！', `MaleText_loc5`='|TInterface\\Icons\\ability_whirlwind.blp:10|t喔天啊!我正在施展|cFFFF0000|Hspell:88481|h[急速運轉]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_whirlwind.blp:10|t ¡Ay, madre, estoy lanzando |cFFFF0000|Hspell:88481|h[Ultravelocidad]|h|r!' WHERE `ID`=50726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에! 제가 |TInterface\\Icons\\ability_whirlwind.blp:10|t|cFFFF0000|Hspell:88481|h[증속]|h|r을 시전하고 있습니다! 미쳤군요!', `MaleText_loc4`='天哪，我要施放|TInterface\\Icons\\ability_whirlwind.blp:10|t|cFFFF0000|Hspell:88481|h[超速]|h|r了，这太疯狂了！', `MaleText_loc5`='喔天啊!我正在施展|TInterface\\Icons\\ability_whirlwind.blp:10|t|cFFFF0000|Hspell:88481|h[急速運轉]|h|r!真是瘋了!', `MaleText_loc7`='¡Ay, madre, estoy lanzando |TInterfaceIconsability_whirlwind.blp:10|t|cFFFF0000|Hspell:88481|h[Ultravelocidad]|h|r! ¡Es una locura!' WHERE `ID`=50727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들으셨나요? |TInterface\\Icons\\ability_whirlwind.blp:10|t 세상에! 제가 |cFFFF0000|Hspell:88481|h[과출력]|h|r을 시전하고 있습니다! 미쳤군요!', `MaleText_loc4`='听到了吗？|TInterface\\Icons\\ability_whirlwind.blp:10|t天哪，我要施放|cFFFF0000|Hspell:88481|h[超速]|h|r了，这太疯狂了！', `MaleText_loc5`='你聽到了嗎?|TInterface\\Icons\\ability_whirlwind.blp:10|t喔天啊!我正在施展|cFFFF0000|Hspell:88481|h[Overdrive]|h|r!真是瘋了!', `MaleText_loc7`='¿Has oído? |TInterfaceIconsability_whirlwind.blp:10|t ¡Ay, madre, estoy lanzando |cFFFF0000|Hspell:88481|h[Ultravelocidad]|h|r! ¡Es una locura!' WHERE `ID`=50728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 여기 와주시다니 정말 다행입니다!', `MaleText_loc4`='$n，你在这里！谢天谢地！', `MaleText_loc5`='$n，真是謝天謝地，你來了!', `MaleText_loc7`='¡$n, menos mal que estás aquí!' WHERE `ID`=50729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 다행입니다, 뛰어난 두뇌를 가진 $c님이시군요.', `MaleText_loc4`='谢天谢地，看上去你是个有脑子，也有能力的$c。', `MaleText_loc5`='感謝老天爺，你這個$c看起來有腦袋也有能力。', `MaleText_loc7`='Menos mal, pareces $gun:una; $c bastante capaz y con algo de cerebro.' WHERE `ID`=50730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만세에에!', `MaleText_loc4`='呀！', `MaleText_loc5`='耶耶耶!', `MaleText_loc7`='¡Yupiiiii!' WHERE `ID`=50731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 여긴 우리 땅이 될 것이다! 오우거와 트롤의 땅이 될 거라고!', `MaleText_loc4`='这是我们的地盘！这是食人魔和巨魔的地方！', `MaleText_loc5`='可是這地方是屬於我們的!這是巨魔和食人妖的土地!', `MaleText_loc7`='¡Eh''te lugar es NUEH''TRO! ¡Eh''ta será la tierra de los ogros y los trols!' WHERE `ID`=50732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간과 녹색 피부들이 우리 땅을 빼앗았다. 우리 조상님의 땅을...', `MaleText_loc4`='人类和绿皮占据了这片土地，我们祖先的土地。', `MaleText_loc5`='人類和綠皮的東西搶走了這片土地，搶走了從先祖流傳到現在的土地。', `MaleText_loc7`='Los humanos y los seres de piel verde tomaron eh''ta tierra, la tierra de nueh''tros anceh''tros.' WHERE `ID`=50733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌주먹 일족 강하다. 마른나무껍질 강하다. 우리 힘을 합쳐 적을 쳐부순다! 우오오오오오오!', `MaleText_loc4`='石拳很强大。枯木很强大。我们在一起，打碎一切敌人！吼！！', `MaleText_loc5`='石拳很強。枯木很強。在一起我們能擊倒敵人!嘎啊啊啊啊!', `MaleText_loc7`='Puño de Roca fuerte. Secacorteza fuerte. ¡Juntos aplastar enemigos! ¡Roaaaaarrrr!' WHERE `ID`=50734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 끝난 게 아닙니다, $n 님. 이렇게 끝날 거라 생각하면 오산이에요.', `FemaleText_loc4`='还没有完，$n。还早着呢。', `FemaleText_loc5`='事情還沒有結束，$n。還差得遠呢!', `FemaleText_loc7`='Esto no ha terminado, $n. Ni de lejos.' WHERE `ID`=50737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음의 눈 의식을 치를 준비가 되었습니다, 타알리아.', `MaleText_loc4`='我准备好进行心灵视界仪式了，萨阿莉亚。', `MaleText_loc5`='我準備好進行心靈幻象儀式了，撒亞莉雅。', `MaleText_loc7`='Estoy listo para el ritual de Visión mental, Thaalia.', `FemaleText_loc1`='마음의 눈 의식을 치를 준비가 되었어요, 타알리아.', `FemaleText_loc4`='我准备好进行心灵视界仪式了，萨阿莉亚。', `FemaleText_loc5`='我準備好進行心靈幻象儀式了，撒亞莉雅。', `FemaleText_loc7`='Estoy lista para el ritual de Visión mental, Thaalia.' WHERE `ID`=50738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 지배 의식을 치를 준비가 되었습니다, 타알리아.', `MaleText_loc4`='我准备好进行精神控制仪式了，萨阿莉亚。', `MaleText_loc5`='我準備好進行精神控制儀式了，撒亞莉雅。', `MaleText_loc7`='Estoy listo para el ritual de Control mental, Thaalia.', `FemaleText_loc1`='정신 지배 의식을 치를 준비가 되었어요, 타알리아.', `FemaleText_loc4`='我准备好进行精神控制仪式了，萨阿莉亚。', `FemaleText_loc5`='我準備好進行精神控制儀式了，撒亞莉雅。', `FemaleText_loc7`='Estoy lista para el ritual de Control mental, Thaalia.' WHERE `ID`=50739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬레, 푸른비늘 인장을 잃어버렸습니다. 하나 더 만들어 주실 수 있습니까?', `MaleText_loc4`='哈尔琳，我丢失了蓝鳞印记。你能再给我一个么？', `MaleText_loc5`='哈爾琳，我弄丟了藍鱗符印。你可以再做一個給我嗎?', `MaleText_loc7`='Haleh, he perdido el sigilo de escama azul. ¿Podrías fabricarme otro?', `FemaleText_loc1`='헬레, 푸른비늘 인장을 잃어버렸어요. 하나 더 만들어 주실 수 있나요?', `FemaleText_loc4`='哈尔琳，我丢失了蓝鳞印记。你能再给我一个么？', `FemaleText_loc5`='哈爾琳，我弄丟了藍鱗符印。你可以再做一個給我嗎?', `FemaleText_loc7`='Haleh, he perdido el sigilo de escama azul. ¿Podrías fabricarme otro?' WHERE `ID`=50740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 새로 도착한 명가를 찾는단 말이십니까? 그렇게 하십시오.

달의 신전의 서쪽 건물로 가보시면 그들을 찾을 수 있을 것입니다. 또 울부짖는 참나무 지역에도 명가의 일원이 있을 것입니다.', `MaleText_loc4`='你要找新来的上层精灵？问我就对了。

你可以在月神殿的西翼找到他们。他们之中的一个也有可能在风嚎橡树。', `MaleText_loc5`='你要找新來到的精靈貴族?好吧。

你可以在月神殿的西側找到他們，然後在咆哮橡樹那邊好像也有一位。', `MaleText_loc7`='¿Buscas a los Altonato que acaban de llegar? Que así sea.

Los encontrarás en el ala oeste del Templo de la Luna. Puede que también haya uno de ellos en El Roble Quejumbroso.', `FemaleText_loc1`='이곳에 새로 도착한 명가를 찾는단 말이십니까? 그렇게 하십시오.

달의 신전의 서쪽 건물로 가보시면 그들을 찾을 수 있을 것입니다. 또 울부짖는 참나무 지역에도 명가의 일원이 있을 것입니다.', `FemaleText_loc4`='你要找新来的上层精灵？问我就对了。

你可以在月神殿的西翼找到他们。他们之中的一个也有可能在风嚎橡树。', `FemaleText_loc5`='你要找新來到的精靈貴族?好吧。

你可以在月神殿的西側找到他們，然後在咆哮橡樹那邊好像也有一位。', `FemaleText_loc7`='¿Buscas a los Altonato que acaban de llegar? Que así sea.

Los encontrarás en el ala oeste del Templo de la Luna. Puede que también haya uno de ellos en El Roble Quejumbroso.' WHERE `ID`=50741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 페블비티... 문이 열려 있습니다.', `MaleText_loc4`='嗯……贝波蒂……门已经打开了。', `MaleText_loc5`='嗯...貝波蒂...門是開的。', `MaleText_loc7`='Mmm... Guijarro... la puerta está abierta.', `FemaleText_loc1`='음... 페블비티... 문이 열려 있는데요.', `FemaleText_loc4`='嗯……贝波蒂……门已经打开了。', `FemaleText_loc5`='嗯...貝波蒂...門是開的。', `FemaleText_loc7`='Mmm... Guijarro... la puerta está abierta.' WHERE `ID`=50742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 그랬군요, 문이 열려 있었네요. 그럼 어서 들어가세요. 목숨을 버리러 가시라고요.', `FemaleText_loc4`='啊……原来如此，原来如此。你就这样继续吧，直到你一命呜呼。', `FemaleText_loc5`='啊...是啊，是啊。那就去啊。去找死吧。', `FemaleText_loc7`='Aaah... así es, así es. Entonces sigue. Sigue hacia tu muerte.' WHERE `ID`=50743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 말은 듣고 싶지 않아요, $n. 안 돼요. 당신을 이글거리는 협곡으로 들여보내는 건 절대 안 돼요. 불가능해요. 있어서는 안 되는 일이라고요. 제가 얼마나 더 이야기해야 하죠? 들여보낼 수 없다고요! 공용어 할 줄 몰라요? 오크가 변장한 건가? 여기로 들어갈 수 없다고요! 절대 못 들어가요!$B$B당신을 들여보내면 다른 사람들도 다 들여보내야 한단 말이에요. 그러면 또 당신의 친한 친구들도 들어가고 싶어할 테고, 또 그 친구들의 먼 친척, 그리고 그 친척의 친구들이 다 들어가고 싶어할 거라고요. 지난번에 그랬을 때... 하여튼, 지금 옛날이야기를 할 때가 아니에요.$b$b저는 절대로 저 문을 열어주지 않을 거예요!', `FemaleText_loc4`='我并不在乎听到这些，$n。你别想进入灼热峡谷，别想。这种事绝不会发生。我必须告诉你多少次，我不会让你进去！难道你不懂人话吗？难道你是伪装的兽人吗？不，绝不！$B$B如果我随便让你进去。用不了多久，你的朋友们也会想进去，然后是他们的远亲，他们的朋友，他们远亲的朋友，朋友的远亲。上次发生这种事……我们可不会讨论上次这种事发生时的情形。$b$b我是不会开门的！', `FemaleText_loc5`='我不想聽，$n。不行，不管怎樣我就是不能放你進灼熱峽谷。不可能。絕對不可能。我要跟你講多少次—我不能放你進去!你是聽不懂通用語嗎?還是你是偽裝的獸人?不—行。不行!$B$B要是我放你過去，那我就得放大家都過去。沒多久你的好朋友也會想要進去，然後是他們的遠房親戚，然後他們的朋友，然後朋友的朋友的朋友。上一次...算了，不講上一次的事情了。$b$b我「不會」打開那個門!', `FemaleText_loc7`='No me importa, $n. No, de ninguna manera vas entrar en La Garganta de Fuego. Imposible. Eso no va a ocurrir. ¿Cuántas veces tengo que decírtelo? ¡No puedo dejarte entrar! ¿Es que no hablas común? ¿Eres un orco disfrazado? N-O. ¡NO!$B$BSi te dejo entrar, entonces tendré que dejar entrar a todo el mundo. Pronto, tus amigos más cercanos querrán entrar, después tu parientes lejanos, luego sus amigos y así hasta el infinito. La última vez que ocurrió... bueno, no solemos hablar de la última vez que ocurrió.$b$b¡NO abriré la puerta!' WHERE `ID`=50744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스 시민 중 한 명인 비투스 다크워커가 당신을 도와줄 수 있을 것입니다. 울부짖는 참나무로 가서 그를 찾아보십시오.', `MaleText_loc4`='一个叫维图斯·暗行者的吉尔尼斯人能帮助你。你可以在风嚎橡树找到他。', `MaleText_loc5`='有位叫做維特斯·黑暗行者的吉爾尼斯人可以幫得了你。去咆哮橡樹那裡找他。', `MaleText_loc7`='Uno de los gilneanos, Vitus Camino Oscuro, puede ayudarte. Lo encontrarás en El Roble Quejumbroso.', `FemaleText_loc1`='길니아스 시민 중 한 명인 비투스 다크워커가 당신을 도와줄 수 있을 거예요. 울부짖는 참나무로 가서 그를 찾아보세요.', `FemaleText_loc4`='一个叫维图斯·暗行者的吉尔尼斯人能帮助你。你可以在风嚎橡树找到他。', `FemaleText_loc5`='有位叫做維特斯·黑暗行者的吉爾尼斯人可以幫得了你。去咆哮橡樹那裡找他。', `FemaleText_loc7`='Uno de los gilneanos, Vitus Camino Oscuro, puede ayudarte. Lo encontrarás en El Roble Quejumbroso.' WHERE `ID`=50746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밀짚인형 축제에 온 것을 환영한다, $c|1이여;여;!$B$B할로윈 축제 기간에, 우리는 자신을 정화하는 의미로 밀짚인형을 불태운다. 숲이 한숨과 함께 나뭇잎을 떨어뜨리듯이, 우리도 때가 되면 부정적인 감정을 떨쳐내야만 한다. 두려움, 슬픔, 후회... 불길 속에 장작을 던져넣으며, 마음의 짐을 내려놓고 겨울을 맞이하는 것이다.$B$B자, 화톳불에서 불타는 장작을 집어들고 축제에 동참하라!', `FemaleText_loc4`='欢迎来到稻草人庆典，$c！$B$B按照万圣节的习俗，我们要焚烧一个稻草人，以代表我们对自我内心的净化。如同森林在秋天洒落枯叶，我们也必须抛弃自身枯萎的那一部分——恐惧、悲哀、憾恨。将枯枝投入烈火，代表着你抛下了不应带入冬天的重担。$B$B请从大篝火中拿起燃烧的枯枝，加入我们的庆典吧！', `FemaleText_loc5`='歡迎加入稻草人節慶活動，$c!$B$B為慶祝萬鬼節，我們焚燒稻草人，象徵自我的淨化。就像樹枝會低垂，綠葉會凋零，我們的精神也必定會經歷洗禮淨化。藉由將樹枝投入火中，不論是恐懼、悲傷、還是後悔，所有你不願帶入冬季的重擔都將隨之卸下。$B$B請試試看，在營火旁拿根燃燒的木頭，加入慶典吧!', `FemaleText_loc7`='¡Te doy la bienvenida al Festival del Hombre de Mimbre, $c!$B$BCon motivo de la celebración de Halloween, quemamos un hombre de mimbre para representar la purificación de cada uno de nosotros. Mientras el bosque suspira y suelta sus hojas, nosotros también debemos sufrir una catarsis. Miedos, sufrimientos, pesares: al lanzar una rama al fuego, podrás liberarte de las penas que no podrías soportar en el invierno.$B$B¡Coge un tizón de la fogata y únete a la celebración!' WHERE `ID`=50747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅 그 자체를 타락시키는 악의 기운이 느껴지십니까, $c님? 그건 분명 어둠의 요새에서 나오는 것입니다. 볼 것 없습니다. 어둠의 요새는 앞길을 가로막는 모든 것을 집어삼킬 것입니다.$B$B<옆구리의 끔찍한 상처를 드러내며 기침하는 나이트 엘프>', `MaleText_loc4`='你能感觉到这个地方的污染么，$c？它来自于暗影堡深处。如果不加以阻止，它会将这里的一切吞噬。$B$B我没有多少时间了，$n。只有你能帮助我及时阻止它的蔓延。$B$B<这名受伤的暗夜精灵咳嗽着，移开手，露出肋侧的血污。>', `MaleText_loc5`='你能感受到玷污了這片大地的邪惡魔力嗎，$c?它的源頭來自於暗影堡深處，若是沒有人阻止的話，它勢必會吞噬掉所有的東西。$B$B<夜精靈咳了幾聲，露出他側身一片血淋淋的傷口。>', `MaleText_loc7`='¿Sientes el mal que mancilla esta tierra, $c? Procede de lo más profundo de la Guarida Sombría. Si no nos oponemos, devorará todo lo que se interponga en su camino.$b$b<El elfo de la noche tose y muestra una herida sangrante en su costado.>' WHERE `ID`=50748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스의 아들딸이여! 오랜 벗이여, 새 동맹이여! 자, 가까이 오라!', `MaleText_loc4`='吉尔尼斯的儿女们！新老盟友们！大家请到我这里来！', `MaleText_loc5`='吉爾尼斯的子民!過去與現在的盟友!來，靠近點!', `MaleText_loc7`='¡Hijos e hijas de Gilneas! ¡Amigos y aliados nuevos y antiguos! ¡Acérquense!' WHERE `ID`=50749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들이 알다시피 할로윈 축제는 전환을... 그리고 변화를 기념하는 행사이다.', `MaleText_loc4`='万圣节是一场关于转变……关于变革的庆典。', `MaleText_loc5`='正如大家所知，萬鬼節是個關於轉變的慶典。', `MaleText_loc7`='Como saben, Halloween es una festividad de transición... de cambio.' WHERE `ID`=50750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부족에서 가장 용감하고 명예로운 자만이 붉은 바위 언덕에 잠드는 영예를 누릴 수 있네.', `MaleText_loc4`='只有部族中最勇猛，最具荣誉感的成员才能安息在赤色石。', `MaleText_loc5`='只有族裡最勇敢正直的人能有此殊榮，葬在赤色石安息。', `MaleText_loc7`='Solo los más valientes y más honorables de la tribu tienen el honor de ser enterrados en la Roca Roja.' WHERE `ID`=50751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나, 오늘 이 자리는 애도나 슬픔과는 거리가 멀다.', `MaleText_loc4`='然而，当下不应该再是哀伤悲恸的时刻。', `MaleText_loc5`='然而，現在並非哀悼或悲痛的時刻。', `MaleText_loc7`='Sin embargo, no es tiempo de llantos ni lamentos.' WHERE `ID`=50752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일 아침, 새로운 고난이 우리를 맞이하고, 불확실한 미래가 우리를 짓누른다.', `MaleText_loc4`='每个黎明都会有新的战斗，还有挥之不去的动荡与不安。', `MaleText_loc5`='在每個黎明，新的困境和不安都壓迫著我們。', `MaleText_loc7`='Nuevos retos nos aguardan con cada amanecer y todos sentimos el peso de la incertidumbre.' WHERE `ID`=50753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 안에 있는 불안함을 이 밀짚인형에 모두 담자.', `MaleText_loc4`='就让这个稻草人代表我们心中的不安。', `MaleText_loc5`='讓這個稻草人代表我們內心的不安。', `MaleText_loc7`='Que el Hombre de Mimbre encarne todo nuestro malestar.' WHERE `ID`=50754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 설원호랑이가 고개를 갸웃거리며 기대에 부푼 눈으로 쳐다봅니다. $g아빠:엄마;라면 어떻게 해야 하는지 알고 있겠죠?', `MaleText_loc4`='这只幼崽侧过头，期待地看着你。难道你不知道该做些什么吗，$g爸爸:妈妈;？', `MaleText_loc5`='這隻幼獸歪著腦袋期盼地望著你。你應該知道要做些什麼吧，$g爹地:媽咪;?', `MaleText_loc7`='El cachorro ladea la cabeza y te mira lleno de expectación. ¿No deberías saber lo que hay que hacer, $gpapá:mamá;?' WHERE `ID`=50755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='횃불 준비!', `MaleText_loc4`='火炬准备！', `MaleText_loc5`='舉起火炬!', `MaleText_loc7`='¡Antorchas!' WHERE `ID`=50756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인형에 불을 붙여라! 할로윈 축제가 시작됐도다!', `MaleText_loc4`='让火焰飞舞！万圣节来啦！', `MaleText_loc5`='讓火燒吧!萬鬼節已經到來!', `MaleText_loc7`='¡Que vuelen las llamas! ¡Halloween ya está aquí!' WHERE `ID`=50757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃을 두고 다투는 일도 많고, 꺼지고 다시 켜지는 일도 많지만, 누구나 불꽃에 경의를 표할 수 있네.$b$b대지 고리회에서는 단지 불꽃에 경의를 표할 뿐, 하찮은 세상사에는 발을 들이지 않지.$b$b자, 여기서 우리는 전통에 따라 불꽃에 경의를 표할 것이네. 자네도 함께하겠나, $n?', `MaleText_loc4`='虽然许多火焰都经历过反复争夺与易手，被熄灭又被重新点燃，但所有人都可以去祭拜它们，$c。$b$b在大地之环中，我们只对火焰进行祭拜，不做其它任何轻率愚蠢的事。$b$b我们依照传统举行祭拜仪式。你会加入我们的仪式吗，$n？', `MaleText_loc5`='這裡歡迎任何人前來對火焰表示敬意，$c。雖然有很多盞火焰已並非原先那些，而是熄滅之後重新點燃的。$b$b在陶土議會，我們只是單純對火焰表示敬意，沒有其他任何輕薄舉動。$b$b在這，我們遵照傳統規定來榮耀火焰。你願意加入我們嗎，$n?', `MaleText_loc7`='Todos son bienvenidos para honrar a la llama, $c. Aunque se combaten muchas llamas, se apagan y se vuelven a encender. Aquí, en el Anillo de la Tierra, simplemente honramos a la llama en vez de dedicarnos a asuntos más banales.$b$bAquí honramos a la llama tal y como dicta la tradición. ¿Deseas unirte a nosotros para honrar a la llama, $n?', `FemaleText_loc1`='불꽃을 두고 다투는 일도 많고, 꺼지고 다시 켜지는 일도 많지만, 누구나 불꽃에 경의를 표할 수 있네.$b$b대지 고리회에서는 단지 불꽃에 경의를 표할 뿐, 하찮은 세상사에는 발을 들이지 않지.$b$b자, 여기서 우리는 전통에 따라 불꽃에 경의를 표할 것이네. 자네도 함께하겠나, $n?', `FemaleText_loc4`='虽然许多火焰都经历过反复争夺与易手，被熄灭又被重新点燃，但所有人都可以去祭拜它们，$c。$b$b在大地之环中，我们只对火焰进行祭拜，不做其它任何轻率愚蠢的事。$b$b我们依照传统举行祭拜仪式。你会加入我们的仪式吗，$n？', `FemaleText_loc5`='這裡歡迎任何人前來對火焰表示敬意，$c。雖然有很多盞火焰已並非原先那些，而是熄滅之後重新點燃的。$b$b在陶土議會，我們只是單純對火焰表示敬意，沒有其他任何輕薄舉動。$b$b在這，我們遵照傳統規定來榮耀火焰。你願意加入我們嗎，$n?', `FemaleText_loc7`='Todos son bienvenidos para honrar a la llama, $c. Aunque se combaten muchas llamas, se apagan y se vuelven a encender. Aquí, en el Anillo de la Tierra, simplemente honramos a la llama en vez de dedicarnos a asuntos más banales.$b$bAquí honramos a la llama tal y como dicta la tradición. ¿Deseas unirte a nosotros para honrar a la llama, $n?' WHERE `ID`=50758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염소각기 X-21을 잃어버렸습니다. 새로 하나 얻을 수 있을까요?', `MaleText_loc4`='呃，我把X-21型灭火器弄丢了。能再给我弄一个新的吗？', `MaleText_loc5`='所以...呃...我把我的熄火器X-21弄不見了。能給我個新的嗎?', `MaleText_loc7`='Yo, eh, bueno, he perdido mi Fuegoeliminator X-21. ¿Podrías darme otro?', `FemaleText_loc1`='화염소각기 X-21을 잃어버렸습니다. 새로 하나 얻을 수 있을까요?', `FemaleText_loc4`='呃，我把X-21型灭火器弄丢了。能再给我弄一个新的吗？', `FemaleText_loc5`='所以...呃...我把我的熄火器X-21弄不見了。能給我個新的嗎?', `FemaleText_loc7`='Yo, eh, bueno, he perdido mi Fuegoeliminator X-21. ¿Podrías darme otro?' WHERE `ID`=50759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무역회사에서는 당신같은 분을 "회계상 부채"라고 해요, $n 님.', `FemaleText_loc4`='$n，财阀里有一个形容你这种人的专有名词：“财政累赘。”', `FemaleText_loc5`='企業有為你這種人準備一個頭銜，$n。「財務負擔。」', `FemaleText_loc7`='El cártel tiene un nombre para gente como tú, $n. "Deuda fiscal".' WHERE `ID`=50760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회 화톳불에 도착했습니다!', `MaleText_loc4`='你到达了大地之环大篝火！', `MaleText_loc5`='你來到了陶土議會營火所在位置!', `MaleText_loc7`='¡Has llegado a una fogata del Anillo de la Tierra!' WHERE `ID`=50761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지 고리회 화톳불에 경의를 표해야 합니다!', `MaleText_loc4`='祭拜大地之环大篝火！', `MaleText_loc5`='榮耀陶土議會的營火!', `MaleText_loc7`='¡Honra la fogata del Anillo de la Tierra!', `FemaleText_loc1`='대지 고리회 화톳불에 경의를 표해야 합니다!', `FemaleText_loc4`='祭拜大地之环大篝火！', `FemaleText_loc5`='榮耀陶土議會的營火!', `FemaleText_loc7`='¡Honra la fogata del Anillo de la Tierra!' WHERE `ID`=50762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='10분 후 밀짚인형 축제가 시작됩니다! 스톰윈드 정문 밖에서 축제에 참가하여 할로윈 축제를 즐기세요!', `FemaleText_loc4`='稻草人庆典将在10分钟后开始！请加入我们在暴风城大门外的狂欢，一同庆祝万圣节吧！', `FemaleText_loc5`='稻草人慶典將在十分鐘後開始!請到暴風城門外加入我們的行列，一同歡慶萬鬼節吧!', `FemaleText_loc7`='¡El Festival del Hombre de Mimbre comenzará en diez minutos! ¡Únete a nosotros justo a las afueras de las puertas de la Ciudad de Ventormenta para celebrar Halloween!' WHERE `ID`=50763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 제데나르 악마 중 한 놈에게 발각됐습니다! 놈이 제 옆구리에 큰 상처를 남겼죠. 상처가 깊지만, 목숨을 위협하진 않을 겁니다.$B$B그보다 더 긴급한 문제가 있습니다. 어둠의 의회가 거친심장 거점에 있는 제 친구들에게 총공격을 펼치지 못하게 막아야 합니다. 전 싸울 상태가 못되니 그대가 저 대신 싸워주셔야겠습니다.', `MaleText_loc4`='有个可恨的加德纳尔恶魔发现了我！还在我的身侧划了一条大口子。这道伤口不浅，但我还能活下去。$B$B还有更要紧的事情要办，暗影议会将对我们在野性之心哨站的朋友们发起全面进攻。我现在没法战斗了，所以你必须代替我去阻止他们。', `MaleText_loc5`='其中一個該死的加德納爾惡魔看到我了!在我的側身劃了一道口子。傷口蠻嚴重的，但死不了。$B$B現在有更重要的事要做，像是阻止暗影議會對我們在野性之心營地的朋友發動全面攻擊。我的身體狀況讓我無法戰鬥，你必須代替我。', `MaleText_loc7`='¡Uno de esos malditos demonios de Jaedenar me vio! Me hizo un buen corte en el costado. La herida no tiene muy buena pinta, pero viviré.$B$BTenemos asuntos más urgentes entre manos, como evitar que el Consejo de la Sombra lance un ataque a gran escala contra nuestros amigos del Alto de Corazón Salvaje. Yo no estoy en condiciones de luchar, así que tendrás que ir en mi lugar.' WHERE `ID`=50764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스의 백성들은 그 누구보다 변화의 의미를 잘 알리라.', `MaleText_loc4`='吉尔尼斯人对变革有着再清楚不过的理解。', `MaleText_loc5`='吉爾尼斯的人民已經太了解轉變的沉重。', `MaleText_loc7`='El pueblo gilneano comprende la gravedad del cambio demasiado bien.' WHERE `ID`=50765;
