UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분께서 오시는군! 입을 다물게, 멍청한 자들이여! 어둠의 여왕님이 다가오고 계시네...', `FemaleText_loc4`='她来了！安静，你们这帮傻瓜！黑暗女王驾临……', `FemaleText_loc5`='她來了!安靜點，你們這些笨蛋!黑暗女王就快到場了...', `FemaleText_loc7`='¡Ya viene! ¡Silencio, estúpidos! La Dama Oscura se acerca...' WHERE `ID`=50769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 멋지군요. 감사해요. 그거... 음... 맛있어 보이네요.', `MaleText_loc4`='哦，太好了，谢谢。这看上去……嗯……一定很美味。', `MaleText_loc5`='喔很好，謝了。那看起來...嗯...很好吃。', `MaleText_loc7`='Oh, genial, gracias. Tiene un aspecto... um... delicioso.', `FemaleText_loc1`='오, 멋지군요. 감사해요. 그거... 음... 맛있어 보이네요.', `FemaleText_loc4`='哦，太好了，谢谢。这看上去……嗯……一定很美味。', `FemaleText_loc5`='喔很好，謝了。那看起來...嗯...很好吃。', `FemaleText_loc7`='Oh, genial, gracias. Tiene un aspecto... um... delicioso.' WHERE `ID`=50770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고트 위들스팬 님이 지난번 조수를 해고했다고 들었어요... 조수를 절벽 아래로 밀어서 말이에요! 그의 나쁜 면은 건드리지 않는 게 상책이에요.', `MaleText_loc4`='我听说那个哥特·韦德斯潘解雇上一名助手的时候……直接把那个倒霉鬼推下了悬崖！你最好不要惹他发火。', `MaleText_loc5`='有聽說戈特·哄誘是怎麼把他上個助理炒魷魚的嗎...直接推下山谷!所以最好別激起他的黑暗面。', `MaleText_loc7`='Oí que Gott Zalamerías despidió a su último ayudante... ¡arrojándolo por un acantilado! Será mejor no hacerle enfadar.', `FemaleText_loc1`='고트 위들스팬 님이 지난번 조수를 해고했다고 들었어요... 조수를 절벽 아래로 밀어서 말이에요! 그의 나쁜 면은 건드리지 않는 게 상책이에요.', `FemaleText_loc4`='我听说那个哥特·韦德斯潘解雇了他最后一名助手……他把那个倒霉鬼直接推下了悬崖！你最好不要惹他发火。', `FemaleText_loc5`='有聽說戈特·哄誘是怎麼把他上個助理炒魷魚的嗎...直接推下山谷!所以最好別激起他的黑暗面。', `FemaleText_loc7`='Oí que Gott Zalamerías despidió a su último ayudante... ¡arrojándolo por un acantilado! Será mejor no hacerle enfadar.' WHERE `ID`=50771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴양지 부지배인님은 우리가 쉬는 꼴 보길 싫어하죠. 우리도 그분 꼴 보기 싫어하고요.', `MaleText_loc4`='主管助理不喜欢看到我们休息。我们也不喜欢看到他。', `MaleText_loc5`='渡假村副主管可不喜歡我們忙裡偷閒。我們也不希望他出現在我們視線範圍。', `MaleText_loc7`='Al director adjunto del complejo no le gusta vernos tomarnos descansos. A nosotros tampoco nos gusta verlo a él.', `FemaleText_loc1`='휴양지 부지배인님은 우리가 쉬는 꼴 보길 싫어하죠. 우리도 그분 꼴 보기 싫어하고요.', `FemaleText_loc4`='主管助理不喜欢看到我们休息。我们也不喜欢看到他。', `FemaleText_loc5`='渡假村副主管可不喜歡我們忙裡偷閒。我們也不希望他出現在我們視線範圍。', `FemaleText_loc7`='Al director adjunto del complejo no le gusta vernos tomarnos descansos. A nosotros tampoco nos gusta verlo a él.' WHERE `ID`=50772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 세상에! 그저께 이후로 쉬지도 못했다고요!', `MaleText_loc4`='哦，好啊！从前天到现在，我还完全没休息过呢！', `MaleText_loc5`='喔棒透了!我從前天到現在都沒休息過!', `MaleText_loc7`='¡Ay, madre! ¡No he tenido un descanso desde anteayer!', `FemaleText_loc1`='이런 세상에! 그저께 이후로 쉬지도 못했다고요!', `FemaleText_loc4`='哦，好啊！从前天到现在，我还完全没休息过呢！', `FemaleText_loc5`='喔棒透了!我從前天到現在都沒休息過!', `FemaleText_loc7`='¡Ay, madre! ¡No he tenido un descanso desde anteayer!' WHERE `ID`=50773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가서 가족들을 보고 싶지만, 고트 님이 이 산에서 우릴 벗어나게 놔두지 않을 거예요!', `MaleText_loc4`='我想回家去看看我的亲人，但多德根本不让我们离开这座山！', `MaleText_loc5`='我想要回去和家人聚一聚，但是戈特不讓我們下山!', `MaleText_loc7`='Quiero ir a casa y ver a mi familia, ¡pero Gott no nos deja salir de esta montaña!', `FemaleText_loc1`='집에 가서 가족들을 보고 싶지만, 고트 님이 이 산에서 우릴 벗어나게 놔두지 않을 거예요!', `FemaleText_loc4`='我想回家去看看我的亲人，但多德根本不让我们离开这座山！', `FemaleText_loc5`='我想要回去和家人聚一聚，但是戈特不讓我們下山!', `FemaleText_loc7`='Quiero ir a casa y ver a mi familia, ¡pero Gott no nos deja salir de esta montaña!' WHERE `ID`=50774;
