UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 날아갈 준비가 됐습니다. 언더시티를 날려 버리죠!', `MaleText_loc4`='我已经做好了飞行准备，让我们去轰炸幽暗城！', `MaleText_loc5`='可以起飛了，讓我們去轟炸幽暗城吧!', `MaleText_loc7`='Estoy listo para volar. ¡Bombardeemos Entrañas!', `FemaleText_loc1`='전 날아갈 준비가 됐습니다. 언더시티를 날려 버리죠!', `FemaleText_loc4`='我已经做好了飞行准备，让我们去轰炸幽暗城！', `FemaleText_loc5`='可以起飛了，讓我們去轟炸幽暗城吧!', `FemaleText_loc7`='Estoy lista para volar. ¡Bombardeemos Entrañas!' WHERE `ID`=50794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웩, 이 술 뭐죠? 맛이 젖은 강아지털 같잖아요!', `MaleText_loc4`='呃，这到底是什么东西？尝起来像是湿狗毛！', `MaleText_loc5`='嗚，這堆餿水是怎樣?聞起來像是溼狗毛一樣!', `MaleText_loc7`='¡Agh! ¿Qué es esta bazofia? ¡Sabe a pelaje de perro mojado!', `FemaleText_loc1`='웩, 이 술 뭐죠? 맛이 젖은 강아지털 같잖아요!', `FemaleText_loc4`='呃，这到底是什么东西？尝起来像是湿狗毛！', `FemaleText_loc5`='嗚，這堆餿水是怎樣?聞起來像是溼狗毛一樣!', `FemaleText_loc7`='¡Agh! ¿Qué es esta bazofia? ¡Sabe a pelaje de perro mojado!' WHERE `ID`=50797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제정신으로 이거 마시고 싶은 사람? 우웩!', `MaleText_loc4`='哪个神经正常的家伙会喝这种玩意儿？呸！', `MaleText_loc5`='有哪個心智正常的人會想喝這個呀?噁!', `MaleText_loc7`='¿Quién en su sano juicio querría beber ESTO? ¡Puaaaaj!', `FemaleText_loc1`='제정신으로 이거 마시고 싶은 사람? 우웩!', `FemaleText_loc4`='哪个神经正常的家伙会喝这种玩意儿？呸！', `FemaleText_loc5`='有哪個心智正常的人會想喝這個呀?噁!', `FemaleText_loc7`='¿Quién en su sano juicio querría beber ESTO? ¡Puaaaaj!' WHERE `ID`=50798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 수상쩍은 걸 본 적이 있느냐고요? 이 근처에서 의심스러운 것이라면 바가지 씌우는 거예요.', `MaleText_loc4`='我有没有看到什么可疑的东西？这里唯一可疑的就是那些高得离谱的价格。', `MaleText_loc5`='我有沒有看到什麼可疑的事物?在這唯一可疑的只有高到嚇死人的價格。', `MaleText_loc7`='¿Si he visto algo sospechoso? Lo único sospechoso por aquí son esos precios, que son un escándalo.', `FemaleText_loc1`='뭔가 수상쩍은 걸 본 적이 있느냐고요? 이 근처에서 의심스러운 것이라면 바가지 씌우는 거예요.', `FemaleText_loc4`='我有没有看到什么可疑的东西？这里唯一可疑的就是那些高得离谱的价格。', `FemaleText_loc5`='我有沒有看到什麼可疑的事物?在這唯一可疑的只有高到嚇死人的價格。', `FemaleText_loc7`='¿Si he visto algo sospechoso? Lo único sospechoso por aquí son esos precios, que son un escándalo.' WHERE `ID`=50799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='본 적 없다고요. 그 황혼의 망치단 가지고 그만 좀 괴롭히고 일광욕이나 계속하게 해 주시지요?', `MaleText_loc4`='我什么都没看见。别用什么暮光之锤的事情来烦我。我还要晒日光浴呢。', `MaleText_loc5`='我什麼都沒看到。現在別再拿暮光之錘的事情來煩我，讓我回去曬曬太陽。', `MaleText_loc7`='No he visto nada. Ahora deja de incordiarme con eso del Martillo Crepuscular y permíteme concentrarme en mi bronceado.', `FemaleText_loc1`='본 적 없다고요. 그 황혼의 망치단 가지고 그만 좀 괴롭히고 일광욕이나 계속하게 해 주시지요?', `FemaleText_loc4`='我什么都没看见。别用什么暮光之锤的事情来烦我。我还要晒日光浴呢。', `FemaleText_loc5`='我什麼都沒看到。現在別再拿暮光之錘的事情來煩我，讓我回去曬曬太陽。', `FemaleText_loc7`='No he visto nada. Ahora deja de incordiarme con eso del Martillo Crepuscular y permíteme concentrarme en mi bronceado.' WHERE `ID`=50800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단 로브를 입은 누군가를 본 거 같네요. 키가 매우 컸어요. 분명해요.', `MaleText_loc4`='我似乎是看见了一些穿着暮光之锤长袍的家伙。我能确定的就是，他们的个子很高。', `MaleText_loc5`='我可能有看到身著暮光之錘長袍的人。我可以確定的是他們很高。', `MaleText_loc7`='Puede que haya visto a alguien vestido con una toga del Martillo Crepuscular. Eran muy altos. De eso estoy seguro.', `FemaleText_loc1`='황혼의 망치단 로브를 입은 누군가를 본 거 같네요. 키가 매우 컸어요. 분명해요.', `FemaleText_loc4`='我似乎是看见了一些穿着暮光之锤长袍的家伙。我能确定的就是，他们的个子很高。', `FemaleText_loc5`='我可能有看到身著暮光之錘長袍的人。我可以確定的是他們很高。', `FemaleText_loc7`='Puede que haya visto a alguien vestido con una toga del Martillo Crepuscular. Eran muy altos. De eso estoy segura.' WHERE `ID`=50801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 그 불의 토템을 놓는 걸 봤어요. 어두웠지만, 그들은 붉은색 옷을 입고 있었던 걸로 기억해요.', `MaleText_loc4`='我看见有人栽下了那种火焰图腾。那时天很黑，不过我记得他们穿着红色的衣服。', `MaleText_loc5`='我看到有人設下火焰圖騰。當時很黑，但是我記得那些人身著紅色衣物。', `MaleText_loc7`='Vi a alguien colocar esos tótems de fuego. Estaba oscuro, pero recuerdo que iban vestidos de rojo.', `FemaleText_loc1`='누군가 그 불의 토템을 놓는 걸 봤어요. 어두웠지만, 그들은 붉은색 옷을 입고 있었던 걸로 기억해요.', `FemaleText_loc4`='我看见有人栽下了那种火焰图腾。那时天很黑，不过我记得他们穿着红色的衣服。', `FemaleText_loc5`='我看到有人設下火焰圖騰。當時很黑，但是我記得那些人身著紅色衣物。', `FemaleText_loc7`='Vi a alguien colocar esos tótems de fuego. Estaba oscuro, pero recuerdo que iban vestidos de rojo.' WHERE `ID`=50802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 움직임이요? 휴양지 부지배인이신 위들스팬 님은 누구든 호수의 북쪽 편으로 가는 걸 싫어해요. 이상다고 생각하지 않으세요?', `MaleText_loc4`='可疑活动？主管助理韦德斯潘不想让任何人到湖北边去。你不觉得这很奇怪吗？', `MaleText_loc5`='可疑的舉動?副主管哄誘先生不希望任何人靠近北方那座湖。你不覺得這有點詭異嗎?', `MaleText_loc7`='¿Actividad sospechosa? El ayudante del director Gott no quiere que nadie vaya al lado norte del lago. Es raro, ¿no crees?', `FemaleText_loc1`='수상한 움직임이요? 휴양지 부지배인이신 위들스팬 님은 누구든 호수의 북쪽 편으로 가는 걸 싫어해요. 이상다고 생각하지 않으세요?', `FemaleText_loc4`='可疑活动？主管助理韦德斯潘不想让任何人到湖北边去。你不觉得这很奇怪吗？', `FemaleText_loc5`='可疑的舉動?副主管哄誘先生不希望任何人靠近北方那座湖。你不覺得這有點詭異嗎?', `FemaleText_loc7`='¿Actividad sospechosa? El ayudante del director Gott no quiere que nadie vaya al lado norte del lago. Es raro, ¿no crees?' WHERE `ID`=50803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 어젯밤 연회에서 황혼의 망치단에 대해 누군가 얘기하는 걸 엿들었어요. 그들을 보지 못했지만, 매우 무례했어요.', `MaleText_loc4`='没错，昨晚的聚会上，我就听到有人在谈暮光之锤的事。我没有看见说话的人是谁，不过他们的口气极为粗鲁。', `MaleText_loc5`='沒錯，昨晚我在無意間聽見派對中有人談著暮光之錘的事情。我沒看到對方，不過他們相當沒有禮貌。', `MaleText_loc7`='Sí, oí a alguien hablar sobre el Martillo Crepuscular en la fiesta de ayer por la noche. No les vi, pero parecían de lo más maleducados.', `FemaleText_loc1`='네, 어젯밤 연회에서 황혼의 망치단에 대해 누군가 얘기하는 걸 엿들었어요. 그들을 보지 못했지만, 매우 무례했어요.', `FemaleText_loc4`='没错，昨晚的聚会上，我就听到有人在谈暮光之锤的事。我没有看见说话的人是谁，不过他们的口气极为粗鲁。', `FemaleText_loc5`='沒錯，昨晚我在無意間聽見派對中有人談著暮光之錘的事情。我沒看到對方，不過他們相當沒有禮貌。', `FemaleText_loc7`='Sí, oí a alguien hablar sobre el Martillo Crepuscular en la fiesta de ayer por la noche. No les vi, pero parecían de lo más maleducados.' WHERE `ID`=50804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지목', `MaleText_loc4`='指控', `MaleText_loc5`='揭發', `MaleText_loc7`='Acusar', `FemaleText_loc1`='지목', `FemaleText_loc4`='指控', `FemaleText_loc5`='揭發', `FemaleText_loc7`='Acusar' WHERE `ID`=50805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가워요! 화창한 날이지 않나요?', `MaleText_loc4`='你好！真是令人愉悦的一天啊，对不对？', `MaleText_loc5`='你好!今天真是個好日子，你說對不對?', `MaleText_loc7`='¡Saludos! Un día magnífico, ¿no crees?', `FemaleText_loc1`='반가워요! 화창한 날이지 않나요?', `FemaleText_loc4`='你好！真是令人愉悦的一天啊，对不对？', `FemaleText_loc5`='你好!今天真是個好日子，你說對不對?', `FemaleText_loc7`='¡Saludos! Un día magnífico, ¿no crees?' WHERE `ID`=50806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 감히 날 황혼의 이교도로 지목하는 거죠? 당신한텐 내가 미쳐 보이나요?', `MaleText_loc4`='你怎么敢指控我是暮光教徒！我得罪你了吗？', `MaleText_loc5`='你怎麼會說我是暮光教徒呢!我看起來很瘋狂嗎?', `MaleText_loc7`='¡Cómo te atreves acusarme de ser un cultor Crepuscular! ¿Acaso te parezco que estoy loco?', `FemaleText_loc1`='어떻게 감히 날 황혼의 이교도로 지목하는 거죠? 당신한텐 내가 미쳐 보이나요?', `FemaleText_loc4`='你怎么敢指控我是暮光教徒！我得罪你了吗？', `FemaleText_loc5`='你怎麼會說我是暮光教徒呢!我看起來很瘋狂嗎?', `FemaleText_loc7`='¡Cómo te atreves acusarme de ser un cultor Crepuscular! ¿Acaso te parezco que estoy loca?' WHERE `ID`=50807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<거만하게 당신을 비웃은 고트>$B$B좀 천천히 일 할 수 없나? 쓸데없는 멍청이들만 들끓는군!', `MaleText_loc4`='<多德轻蔑地向你哼了一声。>$B$B你的动作还能再慢一点吗？我身边都是没用的白痴！', `MaleText_loc5`='<戈特輕蔑地譏笑著你。>$B$B你的動作可以再慢點啊!我周圍全都是群沒用的廢物!', `MaleText_loc7`='<Gott te mira con desdén y aire despectivo.>$B$B¿Crees que podrías trabajar aún más despacio? ¡Estoy rodeado de idiotas inútiles!' WHERE `ID`=50808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기요. 우리 전에 만난 적이 있나요?', `MaleText_loc4`='嗨，我们以前见过吗？', `MaleText_loc5`='嘿，我們之前是不是見過?', `MaleText_loc7`='Eh. ¿Nos hemos visto antes?', `FemaleText_loc1`='저기요. 우리 전에 만난 적이 있나요?', `FemaleText_loc4`='嗨，我们以前见过吗？', `FemaleText_loc5`='嘿，我們之前是不是見過?', `FemaleText_loc7`='Eh. ¿Nos hemos visto antes?' WHERE `ID`=50809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='충고 하나 해 준다면, 너무 애쓰지 말라고 해주고 싶네. 그래 봤자 놈들 사기만 북돋아 줄 뿐이니까.', `MaleText_loc4`='如果你想听我的建议，那么我告诉你，不要打得太厉害。你只是在刺激他们。', `MaleText_loc5`='如果你要我給點建議的話，我會說別讓他們難過，反過來鼓勵他們就好。', `MaleText_loc7`='Si quieres un consejo, no te resistas demasiado. No harás más que animarlos.' WHERE `ID`=50810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 등급으로 올라가면 내 맥주를 나눠주겠네!', `MaleText_loc4`='如果你再爬上一级，我就把我的酒给你喝！', `MaleText_loc5`='如果你能爬上另一座峽谷，我會分你一些酒!', `MaleText_loc7`='¡Si subes un poco más, compartiré mi cerveza contigo!' WHERE `ID`=50811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 난 지금 맛좋은 아이언포지 벌꿀 술을 마시고 있지. 한동안은 이 술이 마지막 술이 될 거야.', `MaleText_loc4`='嘿，我在享用铁炉堡蜜酒。这段时间里，我们可能只剩下这点酒了。', `MaleText_loc5`='還不差，我一路上都在享受鐵爐堡的香醇蜜酒。大概只有最後那瓶喝得比較久。', `MaleText_loc7`='No, voy a disfrutar de una buena copa de hidromiel de Forjaz. Quizá sea el último trago que demos en mucho tiempo.' WHERE `ID`=50812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 위로 올라가는 길에 누가 에일 맥주를 깜빡한 거야? 난 아니라고! 하하하하!', `MaleText_loc4`='是谁在上来的时候忘记拿啤酒了？可不是我！哈哈哈哈！', `MaleText_loc5`='是誰在路上忘記帶瓶酒的呀?可不是我喔!哈哈哈!', `MaleText_loc7`='¿Y a quién se le ha olvidado agarrar la cerveza de camino arriba? ¡A mí no! ¡Jajajajajaja!' WHERE `ID`=50813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 남은 에일 맥주 좀 그만 마시고 이 빌어먹을 나무에서 내려가도록 도와달란 말이야!', `MaleText_loc4`='别再喝我们最后的那点酒了，快来帮我弄掉这该死的树枝！', `MaleText_loc5`='別喝了，那是我們最後的酒了，快來幫我弄掉這該死的樹枝!', `MaleText_loc7`='¡Deja de beberte lo que nos queda de cerveza y ayúdame a bajar de esta maldita rama!' WHERE `ID`=50814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 이 난장판으로 와서 우리를 구해줄지도 몰라!', `MaleText_loc4`='也许能有人来帮我们离开这个该死的地方！', `MaleText_loc5`='或許會有人把我們從這一團亂裡頭救出來!', `MaleText_loc7`='¡Quizá alguien pase por aquí y nos saque de este lío!' WHERE `ID`=50815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멧돼지 갈비 까먹지 말라고 했잖아! 우리 버키 형제는 저녁만 잘 먹었는데 왜 너는 속이 안 좋은 거야?', `MaleText_loc4`='我告诉过你，不要丢掉那些猪排骨！为什么你就不能像其他巴克伊家的人一样，有一副能好好吃饭的正经胃口？', `MaleText_loc5`='我告訴過你別忘了烤豬排的!為什麼你的口味就不能正常點，就像我們其他巴基家的人一樣呢?', `MaleText_loc7`='¡Te dije que no te dejaras las costillas de jabalí! ¿Por qué no puedes tener un estómago como hay que tener y comértelo todo como los demás?' WHERE `ID`=50816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 맥주에 손만 댔다가는 얼굴에 한 방 날려주겠어!', `MaleText_loc4`='再靠近一点，我就一拳砸在你的脸上！', `MaleText_loc5`='再靠過來我就會往你這頭大笨熊的臉上招呼幾拳!', `MaleText_loc7`='¡Acércate un poquito más, oso enano, y te daré un puñetazo en la cara!' WHERE `ID`=50817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 해적 선장의 망령과 온갖 보물이 가득한 유령 등대군요! 해적 선장이 우리한테 보물이 어디 묻혀 있는지 가르쳐 줄까요?', `MaleText_loc4`='喔！一座闹鬼的灯塔，一个海盗船长的幽灵，真是精彩啊！你认为他会告诉我们宝藏埋在哪里吗？', `MaleText_loc5`='哇!一座鬧鬼的燈塔和鬼海盜隊長!你認為他會告訴我們寶藏埋在哪嗎?', `MaleText_loc7`='¡Guau! ¡Un faro encantado con fantasma de un capitán pirata incluido! ¿Crees que nos dirá dónde está enterrado el tesoro?' WHERE `ID`=50818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 댐 좀 보세요! 다른 고아 아이들은 제 말을 안 믿을 거예요!', `MaleText_loc4`='圣光啊！看看水坝变成了什么样子！其他孤儿肯定不会相信的！', `MaleText_loc5`='聖光啊!看看這水壩怎麼了!其他的孤兒一定不會相信的!', `MaleText_loc7`='¡Luz Sagrada! ¡Mira lo que le ha ocurrido a la presa! ¡Los demás huérfanos no se lo van a creer!' WHERE `ID`=50819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 큰 곰은 아직 여기 있네요! 사람들이 곰 뱃속에 보물을 잔뜩 집어넣으면 곰이 화내겠죠? 엄청 아플 테니까요.', `MaleText_loc4`='喔，那头大熊还在这里！你觉得大家把财宝都放进他肚子里的时候，他会不会疯掉？那一定很疼……', `MaleText_loc5`='哇!大熊還在這!你覺得大家把寶藏塞在牠的肚子裡牠會生氣嗎?那一定很痛...', `MaleText_loc7`='¡Guau, el oso grande sigue aquí! ¿Crees que se enfada cuando todo el mundo intenta guardar su tesoro en su tripita? Eso tiene que doler...' WHERE `ID`=50820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치유사의 처소에 오신 걸 환영합니다, $c님.', `FemaleText_loc4`='欢迎来到治愈者营地，$c。', `FemaleText_loc5`='歡迎來到治癒者崗哨，$c。', `FemaleText_loc7`='Te doy la bienvenida a La Finca de los Ensalmadores, $c.' WHERE `ID`=50821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 훈련을 위해 젠키키를 다시 불러주실 수 있습니까?', `MaleText_loc4`='赞吉吉可以进行更多的战斗练习吗？', `MaleText_loc5`='贊基奇有空做更多戰鬥練習嗎?', `MaleText_loc7`='¿Zen''Kiki está disponible para un poco más de práctica de combate?', `FemaleText_loc1`='전투 훈련을 위해 젠키키를 다시 불러주실 수 있나요?', `FemaleText_loc4`='赞吉吉可以进行更多的战斗练习吗？', `FemaleText_loc5`='贊基奇有空做更多戰鬥練習嗎?', `FemaleText_loc7`='¿Zen''Kiki está disponible para un poco más de práctica de combate?' WHERE `ID`=50822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴지세요? 마치 아서스가 아직 이 방에 있는 것 같네요! 간 거 맞죠? 여긴 아직도 악의 기운이 가득하네요...', `MaleText_loc4`='有没有感觉到？阿尔萨斯仿佛还在这个房间里！但他已经不在了，对不对？只是这个地方还是让人感到邪恶……', `MaleText_loc5`='你感覺到了嗎?感覺阿薩斯似乎還存在於這個房間內!但他已經不在了，對嗎?這個地方仍舊充滿著邪惡的氣息...', `MaleText_loc7`='¿Lo sientes? ¡Es como si Arthas siguiera en esta sala! Pero ya no está, ¿no? En este lugar se percibe el mal...' WHERE `ID`=50823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 쳐다보는 거야, 웃기게 생긴 친구!', `MaleText_loc4`='你在看什么？你这个海象脑袋的笨蛋？', `MaleText_loc5`='看什麼看!死爆牙笨蛋!', `MaleText_loc7`='¿Qué estás mirando tú, inútil con cara de colmillarr?' WHERE `ID`=50824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이!', `MaleText_loc4`='呀！', `MaleText_loc5`='呃啊!', `MaleText_loc7`='¡Yarr!' WHERE `ID`=50825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가라고, 신참!', `MaleText_loc4`='我的佣人哪？！', `MaleText_loc5`='哇靠!什麼鬼啊!', `MaleText_loc7`='¡Que se me llenen las barbas de percebes!' WHERE `ID`=50826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 얘기를 들으면 좀 슬퍼질 거야. 예전에 나는 한 배의 선장이었다고.$b$b그런데 지금은 한 번만 더 강등당하면 다시 수병으로 추락할 위기에 놓였지. 과연 내가 그런 치욕적인 일을 참아낼 수 있을지 모르겠어.', `MaleText_loc4`='恐怕关于老邓肯的故事只会让人徒增伤心。知道吗？我曾经是一名真真正正的船长。$b$b但现在只要再降一级，我就又要去洗甲板了。我可没办法承受这样的耻辱。', `MaleText_loc5`='唉，小鄧肯的故事是個悲劇。你知道嗎，我曾經擁有自己的船，是個船長。$b$b我只要再被降一級就會變成一個水兵。我覺得我無法承受這種羞辱。', `MaleText_loc7`='Me temo que la historia del viejo Duncan es muy triste. Yo era capitán de mi propio barco, ¿sabes?$b$bSi me vuelven a degradar, volveré a ser un simple marinero. No creo que pudiera soportar la humillación.' WHERE `ID`=50827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무렴, 던컨. 이제 그만 걸레질이나 좀 하지?', `MaleText_loc4`='邓肯，给我听着，快拿起拖把去干活。', `MaleText_loc5`='我不管，鄧肯。拿枝拖把繼續工作。', `MaleText_loc7`='Me da igual, Duncan. Coge una mopa y ponte a trabajar.', `FemaleText_loc1`='아무렴, 던컨. 이제 그만 걸레질이나 좀 하지?', `FemaleText_loc4`='邓肯，给我听着，快拿起拖把去干活。', `FemaleText_loc5`='我不管，鄧肯。拿枝拖把繼續工作。', `FemaleText_loc7`='Me da igual, Duncan. Coge una mopa y ponte a trabajar.' WHERE `ID`=50828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 엄청나게 큰 부두네요! 여기 정박하는 배들은 비행선만큼이나 큰가 보네요! 이 바다가 오그리마에서 보이는 그 바단가요?', `MaleText_loc4`='喔，这些码头可真大！停泊在这里的船一定也像飞艇一样大！这就是我能从奥格瑞玛看到的那片大海吗？', `MaleText_loc5`='哇，這些碼頭超大的!停在這的船一定和飛艇一樣大!這是我在奧格瑪可以看到的那片大海嗎?', `MaleText_loc7`='¡Guau, esos muelles son enormes! ¡Los barcos que atracan aquí deben de ser tan grandes como zepelines! ¿Este océano es el mismo que se ve desde Orgrimmar?' WHERE `ID`=50829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있으면 사악한 나이트 엘프 놈들이 잘 보이죠! 저도 나중에는 이 전사들처럼 대족장님을 위해 싸울 겁니다!', `MaleText_loc4`='我能从这里看到那些肮脏的暗夜精灵！等我长大以后，我要为酋长而战，就像这些战士一样！', `MaleText_loc5`='我可以在這看到那些骯髒的夜精靈!等我長大後要跟這些戰士一樣為大酋長而戰!', `MaleText_loc7`='¡Puedo ver a esos asquerosos elfos de la noche desde aquí! ¡Cuando sea mayor, quiero luchar por el Jefe de Guerra igual que esos guerreros!' WHERE `ID`=50830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"꽃미남" 던컨에게 1 골드를 주고 걸레질을 시키시겠습니까?', `MaleText_loc4`='只要1个金币，帅小伙子邓肯就会为你擦甲板！', `MaleText_loc5`='你願意付『漂亮男孩』鄧肯一枚金幣來幫你打掃甲板嗎?', `MaleText_loc7`='¿Quieres pagar a "El Guapo" Duncan una moneda de oro por fregar las cubiertas para ti?', `FemaleText_loc1`='"꽃미남" 던컨에게 1 골드를 주고 걸레질을 시키시겠습니까?', `FemaleText_loc4`='只要1个金币，帅小伙子邓肯就会为你擦甲板！', `FemaleText_loc5`='你願意付『漂亮男孩』鄧肯一枚金幣來幫你打掃甲板嗎?', `FemaleText_loc7`='¿Quieres pagar a "El Guapo" Duncan una moneda de oro por fregar las cubiertas para ti?' WHERE `ID`=50831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 문제 있어? 도와줄 일이라도?', `MaleText_loc4`='有麻烦吗，水手？需要帮助吗？', `MaleText_loc5`='你那有什麼問題嗎，水手?需要幫忙嗎?', `MaleText_loc7`='¿Tienes algún problema, $gmarinero:marinera;? ¿Necesitas ayuda?' WHERE `ID`=50832;
