UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이런 일이...', `MaleText_loc4`='真不敢相信会是这样。', `MaleText_loc5`='我不敢相信事情會變成這樣。', `MaleText_loc7`='No puedo creer que hayamos llegado a esto.' WHERE `ID`=50834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸레질이 말이나 되냐고.', `MaleText_loc4`='拖把？真的？', `MaleText_loc5`='拖把?開玩笑嗎?', `MaleText_loc7`='¿Una mopa? ¿En serio?' WHERE `ID`=50835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥까지 추락해야 다시 기어오를 수 있는 건가 봐.', `MaleText_loc4`='我想，有时候，在爬上去之前先要跌到最下面去。', `MaleText_loc5`='或許必須先讓你跌到谷底你才有爬起來的空間。', `MaleText_loc7`='A veces hay que tocar fondo para poder salir del pozo de nuevo.' WHERE `ID`=50836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 내 별명을 바꿔야겠어.', `MaleText_loc4`='也许我需要一个新绰号。', `MaleText_loc5`='或許我需要一個新的綽號。', `MaleText_loc7`='Quizá necesite un nuevo apodo.' WHERE `ID`=50837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님, 당신은 제 아이의 영웅입이십니다. 사인 한 장만 부탁드려도 되겠습니까?', `MaleText_loc4`='酋长，在我的年轻卫士心中，您是一位伟大的英雄。您是否介意为他签个名？', `MaleText_loc5`='大酋長，你在這些小朋友眼裡是個英雄。可否請你幫他們簽個名呢?', `MaleText_loc7`='Jefe de Guerra, eres un héroe para mi joven pupilo. ¿No te importaría firmarle un autógrafo?', `FemaleText_loc1`='대족장님, 당신은 제 아이의 영웅이십니다. 사인 한 장만 부탁드려도 될까요?', `FemaleText_loc4`='酋长，在我的年轻卫士心中，您是一位伟大的英雄。您是否介意为他签个名？', `FemaleText_loc5`='大酋長，你在這些小朋友眼裡是個英雄。可否請你幫他們簽個名呢?', `FemaleText_loc7`='Jefe de Guerra, eres un héroe para mi joven pupilo. ¿No te importaría firmarle un autógrafo?' WHERE `ID`=50838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지, $c|1이여;여;. 어린 친구의 이름이 뭔가?$B$B다른 이들도 너처럼 오그리마의 고아들에게 관심을 보였으면 좋겠구나.', `MaleText_loc4`='当然，$c。那位年轻战士叫什么名字？$B$B真希望我们有更多的人能像你那样关心奥格瑞玛的孤儿。', `MaleText_loc5`='當然，$c。這位小戰士叫什麼名字?$B$B希望奧格瑪有更多人跟你一樣關心這些孤兒們。', `MaleText_loc7`='Por supuesto, $c. ¿Cómo se llama el joven guerrero?$B$BDesería que hubiera más gente que se preocupara por los huérfanos de Orgrimmar tanto como tú.' WHERE `ID`=50839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스가 많이 그립지만, 아직 탐사할 고대 유적이 많습니다!', `MaleText_loc4`='虽然我非常想念吉尔尼斯，但还有许多远古遗迹需要我去探索！', `MaleText_loc5`='雖然我很想念吉爾尼斯，但還有很多遠古遺蹟等著我去探索!', `MaleText_loc7`='Aunque echo mucho de menos Gilneas, ¡aquí hay muchas ruinas antiguas listas para explorar!', `FemaleText_loc1`='길니아스가 많이 그립지만, 아직 탐사할 고대 유적이 많습니다!', `FemaleText_loc4`='虽然我非常想念吉尔尼斯，但还有许多远古遗迹需要我去探索！', `FemaleText_loc5`='雖然我很想念吉爾尼斯，但還有很多遠古遺蹟等著我去探索!', `FemaleText_loc7`='Aunque echo mucho de menos Gilneas, ¡aquí hay muchas ruinas antiguas listas para explorar!' WHERE `ID`=50840;
