UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 이봐! 혹시 녹색 냄새 안 나?', `MaleText_loc4`='嗨！你好！怎么样，这里闻起来也是绿色的吧？', `MaleText_loc5`='嗨!就是你!你有沒有聞到一種綠綠的味道?', `MaleText_loc7`='¡Hola! ¡Sí, tú! ¿Esto te huele a sudor?' WHERE `ID`=50842;
