UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 내놓으라고, 이 드워프 대가리 친구야! 아니, 그거 말고, 딴 거!', `MaleText_loc4`='把那个旋转齿轮给我，你这个生了颗矮人脑子的人崽子！不，不是那个，是另一个！', `MaleText_loc5`='給我鏈輪，你這個腦袋裝矮人渣的笨蛋!不是，不是那個，是另一個!', `MaleText_loc7`='¡Pásame ese piñón loco libre de tensión, especie de hijo de humano con cerebro de enano! ¡No, ese no, el otro!' WHERE `ID`=50844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 땜장이 마을의 편집장이었다고!', `MaleText_loc4`='我是侏儒区闲话报的首席编辑！', `MaleText_loc5`='我之前可是「地精區壹週刊」的主編!', `MaleText_loc7`='¡Yo era el editor jefe del Chismoso de Ciudad Manitas!' WHERE `ID`=50845;
