UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보물 사냥꾼의 삶은 위험이 가득하죠. 부디 어리석은 짓 말길 바랍니다.', `MaleText_loc4`='财宝猎人的人生中充满了背叛与欺骗。别再犯傻了。', `MaleText_loc5`='寶藏獵人的一生充滿狡詐。別自欺欺人了。', `MaleText_loc7`='La vida de un cazador de tesoros es traicionera. No te engañes.' WHERE `ID`=50850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개에서 수증기가 마구 생겨납니다! 압도당하기 전에 빨리 으르렁니 제독을 처치해야 합니다!', `MaleText_loc4`='从雾中涌出了许多蒸汽！在被它们吞噬之前赶紧击败撕心狼将军！', `MaleText_loc5`='在大霧之中出現不同種類的水氣!在被擊潰前打倒利普斯納爾上將!', `MaleText_loc7`='¡Múltiples vapores aparecen en la niebla! ¡Mata al almirante Rasgagruñido antes de que te superen!' WHERE `ID`=50851;
