UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 침입할 생각을 하다니! 박살 내주마!', `MaleText_loc4`='你打破入口进去了？！我要把你打破！', `MaleText_loc5`='你破門而入?看我怎樣「打爆」你!', `MaleText_loc7`='¡¿Tú destrozar y entrar?! ¡Yo destrozar a TI!', `FemaleText_loc1`='감히 침입할 생각을 하다니! 박살 내주마!', `FemaleText_loc4`='你打破入口进去了？！我要把你打破！', `FemaleText_loc5`='你破門而入?看我怎樣「打爆」你!', `FemaleText_loc7`='¡¿Tú destrozar y entrar?! ¡Yo destrozar a TI!' WHERE `ID`=50861;
