UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오주마트가 취약한 상태입니다. 지금 공격하십시오!', `MaleText_loc4`='厄祖玛特现在衰弱了，进攻！', `MaleText_loc5`='歐蘇瑪特變脆弱了，快點動手!', `MaleText_loc7`='Ozumat es vulnerable, ¡golpea ahora!', `FemaleText_loc1`='오주마트가 취약한 상태입니다. 지금 공격하십시오!', `FemaleText_loc4`='厄祖玛特现在衰弱了，进攻！', `FemaleText_loc5`='歐蘇瑪特變脆弱了，快點動手!', `FemaleText_loc7`='Ozumat es vulnerable, ¡golpea ahora!' WHERE `ID`=50863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이들아! 내가 그렇게 쉽게 함정에 빠질 것 같으냐!', `MaleText_loc4`='懦夫！我可不会这么容易就掉进你们的陷阱！', `MaleText_loc5`='懦夫!我才不會那麼輕易地落入你的陷阱之中!', `MaleText_loc7`='¡Cobardes! ¡No caeré tan fácilmente en su trampa!' WHERE `ID`=50864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 이 악마들과 싸워야 할 때에 겁쟁이처럼 숨어?', `MaleText_loc4`='你在这里！对抗邪恶的战斗正在进行，而你却像懦夫一样躲在这里？', `MaleText_loc5`='找到你了!在該和這些惡魔作戰的時候，你卻像個懦夫一樣躲起來?', `MaleText_loc7`='¡Eh, tú! ¿Te escondes como un cobarde cuando deberías estar luchando contra estos demonios?' WHERE `ID`=50865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 뛰고 뭐라도 하란 말이다!', `MaleText_loc4`='别跑啦，赶快做些什么！', `MaleText_loc5`='別再跑來跑去的，做點什麼呀!', `MaleText_loc7`='¡Deja de correr y HAZ ALGO!' WHERE `ID`=50866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 겁쟁이들, 너희 모두 말이야! 너희가 기골을 좀 보여준다면, 정말로 보수를 줄 수도 있는데!', `MaleText_loc4`='你们都是没胆气的懦夫！如果你们能显示些勇气出来，也许我真的会付给你们薪水的！', `MaleText_loc5`='無能的懦夫，你們一群人都是!如果你們展現點骨氣的話，我也許會願意多發點工資!', `MaleText_loc7`='¡Sois todos unos cobardes ineptos! ¡Quizá si mostrarais un poco más de coraje os pagaría el sueldo!' WHERE `ID`=50867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못난 것들! 멍청이들! 바보들! 우둔한 것들! 어리석은 것들! 얼간이들! 무식한 것들! 계속할까?', `MaleText_loc4`='白痴！白痴！笨蛋！低能儿！蠢货！傻瓜！呆子！我应该继续吗？', `MaleText_loc5`='白痴!笨蛋!蠢豬!弱智!低能!蠢材!無知!還要我繼續罵下去嗎?', `MaleText_loc7`='¡Idiotas! ¡Imbéciles! ¡Estúpidos! ¡Tontos! ¡Gusanos! ¡Analfabetos! ¿Sigo?' WHERE `ID`=50868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 물을 좀 가져와야겠네요. 상식이 있는 사람이라면 벌써 그랬을 걸요!', `MaleText_loc4`='也许应该有人去拿些水来。有脑子的家伙早就应该去干这件事了！', `MaleText_loc5`='也許有人該去找點水回來。有腦袋的人早就把這事給辦好啦!', `MaleText_loc7`='Quizá alguien debería ir a buscar agua. ¡Una persona con algo de cerebro ya lo habría hecho!' WHERE `ID`=50869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 이 바보 멍청이야! 이곳을 불타 마땅한 곳이다.', `MaleText_loc4`='你们这群傻瓜！这个地方真应该被烧掉。', `MaleText_loc5`='你們這群傻子!這地方被燒掉活該。', `MaleText_loc7`='¡Papanatas! Este lugar merece arder.' WHERE `ID`=50870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에서 악몽의 거미들이 나타납니다! 헬릭스의 악몽에 압도당하기 전에 어서 그를 처치하십시오!', `MaleText_loc4`='噩梦蜘蛛出现在黑暗中！在赫利克斯的噩梦吞噬你之前消灭他！', `MaleText_loc5`='夢魘蜘蛛現身於黑暗之中!在你被夢魘擊潰之前殺掉赫利克斯!', `MaleText_loc7`='¡Las arañas de la pesadilla aparecen en la oscuridad! ¡Mata a Helix antes de que la pesadilla te supere!' WHERE `ID`=50871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까진 제게 좋은 인상을 심어주셨습니다, $n 님. 궁극의 요리를 만드는 데 저를 도와주시면 어떨까요?', `MaleText_loc4`='$n，至今为止，你给我留下了深刻的印象。想不想帮我烹制出终极菜肴？', `MaleText_loc5`='你讓我印象深刻無比，$n。來幫我烹調出究極的菜餚吧，如何?', `MaleText_loc7`='Hasta ahora me has dejado impresionado, $n. ¿Te apetece ayudarme a crear el plato definitivo?' WHERE `ID`=50874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_cyclone.blp:20|t%s|1이;가; |cFFFF9A20|Hspell:86193|h[광풍 강타]|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_cyclone.blp:20|t%s开始施放|cFFFF9A20|Hspell:86193|h [强风冲击]！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_cyclone.blp:20|t%s開始施展|cFFFF9A20|Hspell:86193|h [疾風衝擊]!|r', `MaleText_loc7`='|TInterfaceIconsspell_nature_cyclone.blp:20|t¡%s comienza a lanzar|cFFFF9A20|Hspell:86193|h [Explosión de viento]!|r' WHERE `ID`=50875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFF3366CC잔질 광전사|r를 부활시키기 시작합니다!', `MaleText_loc4`='%s开始复活一个|cFF3366CC赞吉利狂暴者|r！', `MaleText_loc5`='%s開始復活|cFF3366CC贊吉爾狂戰士|r!', `MaleText_loc7`='¡%s empieza a resucitar a un |cFF3366CCrabioso Zanzili|r!', `FemaleText_loc1`='%s|1이;가; |cFF3366CC잔질 광전사|r를 부활시키기 시작합니다!', `FemaleText_loc4`='%s开始复活一个|cFF3366CC赞吉利狂暴者|r！', `FemaleText_loc5`='%s開始復活|cFF3366CC贊吉爾狂戰士|r!', `FemaleText_loc7`='¡%s empieza a resucitar a un |cFF3366CCrabioso Zanzili|r!' WHERE `ID`=50876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFCC0000잔질 좀비|r 무리를 부활시키기 시작합니다!', `MaleText_loc4`='%s开始复活一群|cFFCC0000赞吉利僵尸|r！', `MaleText_loc5`='%s開始復活一群|cFFCC0000贊吉爾殭屍|r!', `MaleText_loc7`='¡%s empieza a resucitar un enjambre de |cFFCC0000zombis Zanzili|r!', `FemaleText_loc1`='%s|1이;가; |cFFCC0000잔질 좀비|r 무리를 부활시키기 시작합니다!', `FemaleText_loc4`='%s开始复活一群|cFFCC0000赞吉利僵尸|r！', `FemaleText_loc5`='%s開始復活一群|cFFCC0000贊吉爾殭屍|r!', `FemaleText_loc7`='¡%s empieza a resucitar un enjambre de |cFFCC0000zombis Zanzili|r!' WHERE `ID`=50877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 대기를 |cFF33FF00유독 가스|r로 가득 채웁니다!', `MaleText_loc4`='%s让这一区域充满了|cFF33FF00毒性瓦斯|r！', `MaleText_loc5`='%s讓這個區域滿是|cFF33FF00毒氣|r!', `MaleText_loc7`='¡%s inunda la zona con |cFF33FF00gas tóxico|r!', `FemaleText_loc1`='%s|1이;가; 대기를 |cFF33FF00유독 가스|r로 가득 채웁니다!', `FemaleText_loc4`='%s让这一区域充满了|cFF33FF00毒性瓦斯|r！', `FemaleText_loc5`='%s讓這個區域滿是|cFF33FF00毒氣|r!', `FemaleText_loc7`='¡%s inunda la zona con |cFF33FF00gas tóxico|r!' WHERE `ID`=50878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우우히이이! 저 여자 뛰는 거 좀 보라고! 쉬면서 저 광경이나 구경하지. 곧 호수 건너편에 닿을 걸세.', `MaleText_loc4`='呦喉！看看她跑得多漂亮！放松，尽情观赏周围的景色吧。我们很快就能驶过湖面了。', `MaleText_loc5`='喔耶!看看這速度!放輕鬆，瀏覽一下風景。我們很快就會越過湖泊。', `MaleText_loc7`='¡Uaaaaaaaa! ¡Mira cómo corre! Relájate y disfruta de las vistas. Estarás al otro lado del lago en menos que canta un gallo.' WHERE `ID`=50879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐겁게 지내시나? 증기 웅덩이에 한 번 몸을 담그면 십 년은 어려 보일 거라고. 증거가 필요하면 날 봐!', `MaleText_loc4`='喜欢这里吗？在蒸汽池里泡一泡，你出来的时候就能年轻10岁。你要是不信，就看看我吧！', `MaleText_loc5`='喜歡這裡嗎?只要在蒸氣池泡一下，馬上讓你看起來年輕十歲。看看我，我就是活生生的證明!', `MaleText_loc7`='¿Te lo estás pasando bien? Te metes una sola vez en Las Charcas Vaporosas y sales 10 años más joven. ¡Mírame a mí si quieres pruebas!' WHERE `ID`=50880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주방장 트램지의 요리를 하나라도 먹어봤나? 난 그가 요리한 나방 수프를 정말 좋아했지. 맛있거든!', `MaleText_loc4`='有没有试过厨师特兰姆塞的菜肴？我非常喜欢他的蛾肉汤。那可真是美味！', `MaleText_loc5`='你有沒有吃過車述大廚煮的菜?我超愛他的飛蛾湯，超好吃的!', `MaleText_loc7`='¿Te lo estás pasando bien? Te metes una sola vez en Las Charcas Vaporosas y sales 10 años más joven. ¡Mírame a mí si quieres pruebas!' WHERE `ID`=50881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐. 저기 저 불빛 보이나? 무슨 일이지?', `MaleText_loc4`='等等，你看到那里的光亮了吗？出了什么事？', `MaleText_loc5`='等下，你有沒有看見那邊的亮光?發生了什麼事?', `MaleText_loc7`='Espera, ¿ves esa luz de ahí? ¿Qué pasa?' WHERE `ID`=50882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저들이 황혼의 망치단 요원들이로군! 어... 휴양지 부지배인이 저들하고 같이 있는 건가?', `MaleText_loc4`='他……他们是暮光之锤的间谍！和他们在一起的……是度假地主管助理吗？', `MaleText_loc5`='他...他們是暮光之錘的特務!那個...跟他們在一起的人是渡假村副主管嗎?', `MaleText_loc7`='¡Son... son agentes del Martillo Crepuscular! ¿El... el director adjunto del complejo está con ellos?' WHERE `ID`=50883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 안 돼! 저들이 우릴 알아봤어! 꽉 잡으라고. 여길 빠져나갈 테니까!', `MaleText_loc4`='哦，不！他们发现我们了！抓紧——我们要马上逃走！', `MaleText_loc5`='喔不!他們發現我們了!坐穩了，我會想辦法讓大家逃出這裡!', `MaleText_loc7`='¡Oh, no! ¡Nos han localizado! Espera... ¡Conseguiré que salgamos de aquí!' WHERE `ID`=50884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간신히 살아남았군. 자네 뛰어가서 라샤에게 본 걸 말해줘야겠네. 처리해야 할 심각한 문제가 생겼어!', `MaleText_loc4`='我们差一点就没命了。你最好赶快跑到拉珊那里去，告诉她你看到的一切。我们有大麻烦了！', `MaleText_loc5`='我們差點就被幹掉了。你最好趕快去把你所看到的一切告訴拉夏。眼前有很嚴重的問題要面對!', `MaleText_loc7`='Apenas hemos conseguido salir con vida. Será mejor que eches a correr y le cuentes a Lasha lo que has visto. ¡Tenemos un problema muy gordo entre manos!' WHERE `ID`=50885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 노스렌드 원정에 참가했던 다른 역전용사들을 찾고 있습니다. 고향에 나타난 새로운 적을 한시라도 빨리 상대해야 하니까요.', `MaleText_loc4`='我正在诺森德寻找其他久经战阵的老兵。我们迫切需要强大的战士去击退出现在家乡的新敌人。', `MaleText_loc5`='我在尋找北裂境戰役之中的精兵。我們迫切地需要人手來面對出現在家園中的新敵人。', `MaleText_loc7`='Busco a otros veteranos de la campaña de Rasganorte. En casa nos necesitan urgentemente para que nos enfrentemos a nuevos enemigos.' WHERE `ID`=50886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5분 후에 톨 바라드 전투 준비를 시작합니다!', `MaleText_loc4`='托尔巴拉德的战斗准备将在5分钟后开始！', `MaleText_loc5`='托巴拉德的準備將在5分鐘後開始!', `MaleText_loc7`='¡La fase de preparación para Tol Barad comenzará en 5 minutos!' WHERE `ID`=50887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분 후에 톨 바라드 전투 준비를 시작합니다!', `MaleText_loc4`='托尔巴拉德的战斗准备将在2分钟后开始！', `MaleText_loc5`='托巴拉德的準備將在2分鐘後開始!', `MaleText_loc7`='¡La fase de preparación para Tol Barad comenzará en 2 minutos!' WHERE `ID`=50888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후에 톨 바라드 전투 준비를 시작합니다!', `MaleText_loc4`='托尔巴拉德的战斗准备将在1分钟后开始！', `MaleText_loc5`='托巴拉德的準備將在1分鐘後開始!', `MaleText_loc7`='¡La fase de preparación para Tol Barad comenzará en 1 minuto!' WHERE `ID`=50889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 다가온다! 싸움 없이 날 데려갈 순 없을 거다. 괴물아!', `FemaleText_loc4`='黑暗正在逼近！除非拼死一搏，否则我绝不会离开，怪物！', `FemaleText_loc5`='黑暗逼近!我可不會就這樣任人宰割，怪物!', `FemaleText_loc7`='¡La oscuridad se acerca! ¡No me iré sin luchar, monstruo!' WHERE `ID`=50890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 난 케빈이라고 하네. 동영상을 보고 싶은가?', `MaleText_loc4`='嗨，我的名字是凯文。你想演电影吗？', `MaleText_loc5`='嗨，我是凱文，你想不想演電影呢?', `MaleText_loc7`='Hola, me llamo Kevin, ¿quieres actuar en una película?', `FemaleText_loc1`='안녕하신가, 난 케빈이라고 하네. 동영상을 보고 싶은가?', `FemaleText_loc4`='嗨，我的名字是凯文。你想演电影吗？', `FemaleText_loc5`='嗨，我是凱文，你想不想演電影呢?', `FemaleText_loc7`='Hola, me llamo Kevin, ¿quieres actuar en una película?' WHERE `ID`=50892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼약탈자와 싸우고 싶지만 놈을 소환할 방법이 없습니다. 절 도와주시겠습니까?', `MaleText_loc4`='我想要与夺灵者战斗，但我没有办法召唤他。你能帮助我吗？', `MaleText_loc5`='我想要和奪魂者戰鬥，但是我沒辦法召喚祂。你能幫幫我嗎?', `MaleText_loc7`='Tengo intención de luchar contra el Cazador de Almas, pero no puedo invocarlo. ¿Puedes ayudarme?', `FemaleText_loc1`='영혼약탈자와 싸우고 싶지만 놈을 소환할 방법이 없네요. 절 도와주시겠어요?', `FemaleText_loc4`='我想要与夺灵者战斗，但我没有办法召唤他。你能帮助我吗？', `FemaleText_loc5`='我想要和奪魂者戰鬥，但是我沒辦法召喚祂。你能幫幫我嗎?', `FemaleText_loc7`='Tengo intención de luchar contra el Cazador de Almas, pero no puedo invocarlo. ¿Puedes ayudarme?' WHERE `ID`=50893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 톨 바라드 전투에서 승리했소! 호드의 공격이 무력화된 지금, 자원과 섬의 안전을 확보하기 위한 당신의 노력이 시급하오!', `MaleText_loc4`='托尔巴拉德的胜利是我们的囊中之物！部落的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！', `MaleText_loc5`='托巴拉德的勝利是我們!在部落攻勢被癱瘓的同時，我們需要你立刻去採集一些資源，好保住這座島!', `MaleText_loc7`='¡La victoria en Tol Barad es nuestra! Tenemos que realizar esfuerzos inmediatos para reunir recursos y asegurar el control de la isla mientras la ofensiva de la Horda está incapacitada.' WHERE `ID`=50894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 톨 바라드 전투에서 승리했다네! 얼라이언스의 공격이 무력화된 지금, 자원과 섬의 안전을 확보하기 위한 자네의 노력이 시급하네!', `MaleText_loc4`='托尔巴拉德的胜利是我们的囊中之物！联盟的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！', `MaleText_loc5`='托巴拉德的勝利是我們!在聯盟攻勢被癱瘓的同時，我們需要你立刻去採集一些資源，好保住這座島!', `MaleText_loc7`='¡La victoria en Tol Barad es nuestra! Tenemos que realizar esfuerzos inmediatos para reunir recursos y asegurar el control de la isla mientras la ofensiva de la Alianza está incapacitada.' WHERE `ID`=50895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 불행한 여행자여. 잠시만 기다려 주십시오... 곧 피투성이로 만들어 드리겠습니다!', `MaleText_loc4`='你好啊，倒霉的冒险者。我只会让你们付出一点点时间……和许多的血！', `MaleText_loc5`='你好，不幸的冒險者。我只要求你稍待片刻...以及留下你的鮮血就好!', `MaleText_loc7`='Saludos, desventurado aventurero. Solo te pido que esperes un instante... ¡y SANGRES!' WHERE `ID`=50896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉴 곳을 찾는다면 제가 도와드릴 수 있습니다.', `MaleText_loc4`='如果你想找一个地方休息，那么我能帮上忙。', `MaleText_loc5`='如果你在找個可以休息的地方，我可以幫上忙。', `MaleText_loc7`='Si buscas un lugar para descansar, yo puedo ayudarte.', `FemaleText_loc1`='쉴 곳을 찾는다면 제가 도와드릴게요.', `FemaleText_loc4`='如果你想找一个地方休息，那么我能帮上忙。', `FemaleText_loc5`='如果你在找個可以休息的地方，我可以幫上忙。', `FemaleText_loc7`='Si buscas un lugar para descansar, yo puedo ayudarte.' WHERE `ID`=50897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언데드와 맞서 나와 한편이 되느니 차라리 내가 죽는 꼴을 보겠다는 말인가? 잘 알았다.', `MaleText_loc4`='在这么多战友中，你单单选择我的躯体对抗亡灵？那好吧。', `MaleText_loc5`='在盟友之中，你選擇以我的屍體來對抗不死生物?那就這樣辦吧。', `MaleText_loc7`='¿Has elegido mi cadáver en vez de a otro aliado para luchar contra los no-muertos? Que así sea.' WHERE `ID`=50898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 몸을... 불태워 주시오... 저들과 같은 운명이... 되지 않게...', `MaleText_loc4`='燃烧吧……我的躯体……不要让我成为它们的一员……', `MaleText_loc5`='燒掉...我的屍體...別讓我成為他們的一員...', `MaleText_loc7`='Quema... mi cadáver... no permitas que me una a ellos...' WHERE `ID`=50899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='복귀 비율을 범위에 넣고 자산과 부채를 고려하여, 수요의 탄력성에서 보급품 지출을 제하고 수익을 내보면... 오, 안녕하세요! 어떻게 지내시나요?', `FemaleText_loc4`='计划收入减去弹性需求的供给支出，考虑到衰减函数中的资产和负债曲线……哦，嗨！你好啊？', `FemaleText_loc5`='收入減去補給支出對上需求彈性，再考慮資產與負債之間的曲線消退比率...喔，嗨!你好嗎?', `FemaleText_loc7`='Los ingresos de la parcela menos los gastos de suministros comparado con la elasticidad de la demanda, considerando los activos y los pasivos derivados del cociente de regresión... Oh, ¡hola! ¿Qué tal estás?' WHERE `ID`=50900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 부엌에 남을 자질이 있으신가요?', `MaleText_loc4`='你够格待在我的厨房里吗？', `MaleText_loc5`='你以為留在我的廚房有那麼容易嗎?', `MaleText_loc7`='¿Tienes lo que hay que tener para quedarte en mi cocina?' WHERE `ID`=50901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 바가지 씌우는 거 보셨나요?', `MaleText_loc4`='见识过这里可怕的物价了吗？', `MaleText_loc5`='你知道這邊的價格貴到讓人無法忍受嗎?', `MaleText_loc7`='¿Has visto estos precios vergonzosos?', `FemaleText_loc1`='이곳에서 바가지 씌우는 거 보셨나요?', `FemaleText_loc4`='见识过这里可怕的物价了吗？', `FemaleText_loc5`='你知道這邊的價格貴到讓人無法忍受嗎?', `FemaleText_loc7`='¿Has visto estos precios vergonzosos?' WHERE `ID`=50902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 음료 한 잔 가져다주시겠어요? 제가 직접 가져오고 싶지만, 일광욕 중이어서요.', `MaleText_loc4`='能给我拿些喝的来吗？我正在晒日光浴，没法去拿饮料。', `MaleText_loc5`='你能幫我拿杯飲料嗎?我是很想自己來，但是我正在做日光浴。', `MaleText_loc7`='¿Me traes algo para beber? Podría ir yo mismo, pero estoy ocupado bronceándome.', `FemaleText_loc1`='제게 음료 한 잔 가져다주시겠어요? 제가 직접 가져오고 싶지만, 일광욕 중이어서요.', `FemaleText_loc4`='能给我拿些喝的来吗？我正在晒日光浴，没法去拿饮料。', `FemaleText_loc5`='你能幫我拿杯飲料嗎?我是很想自己來，但是我正在做日光浴。', `FemaleText_loc7`='¿Me traes algo para beber? Podría ir yo misma, pero estoy ocupada bronceándome.' WHERE `ID`=50903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 다시 일어날 거다! 네 발아래 있는 대지가 부활의 격분으로 삼켜질 것이다!', `MaleText_loc4`='暮光之锤将再次崛起！你们脚下的大地将被我们复苏时的怒火吞噬！', `MaleText_loc5`='暮光之錘會再度崛起!你們腳下的每寸土地都將被我們再次現身時的怒氣所吞沒!', `MaleText_loc7`='¡El Martillo Crepuscular se alzará de nuevo! ¡La misma tierra bajo tus pies se hundirá bajo la furia de su resurgimiento!' WHERE `ID`=50904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안갯속이라 잘 보이지는 않지만, 네 냄새는 맡을 수 있지! 죽어라, 이 더러운 오우거 녀석!', `MaleText_loc4`='我眼前朦朦胧胧的，什么都看不清，但我很清楚这股气味！去死吧，肮脏的食人魔！', `MaleText_loc5`='我的視力在這片霧中沒辦法發揮多大效用，不過不管身處什麼地方我都能認出這股味道!去死吧骯髒的巨魔!', `MaleText_loc7`='Ah, no puedo ver muy bien a través de esta bruma, ¡pero reconocería ese olor en cualquier parte! ¡Muere ogro apestoso!' WHERE `ID`=50905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오오오오...', `MaleText_loc4`='哦…………', `MaleText_loc5`='喔喔喔喔喔喔喔...', `MaleText_loc7`='Ooooooooh...' WHERE `ID`=50906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사나이 두간이 역병지대로, 사악한 스컬지를 묻어버리러 떠났지.', `MaleText_loc4`='老杜甘要去瘟疫之地，把那些天灾恶鬼全都赶回到地里去。', `MaleText_loc5`='老杜甘去了瘟疫之地，把天譴軍送回「地底」的老家。', `MaleText_loc7`='A las tierras de la peste el viejo Duggan fue, para devolver la Plaga a la tierra,' WHERE `ID`=50907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 냄새가 바람에 실려 오고, 죽어가는 황톳빛에 덮인 땅이었지.', `MaleText_loc4`='风把死亡的气息带往所有地方，一切都因之而凋敝。', `MaleText_loc5`='風中瀰漫著死亡的氣味，幾乎所有事物都變成褐色的了。', `MaleText_loc7`='donde el aire hiede a muerte y es marrón el suelo donde se entierra.' WHERE `ID`=50908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 그 땅에 도착했을 때, 드워프의 날카로운 눈에 무엇이 보였을까?', `MaleText_loc4`='当他到了那里的时候，他的矮人眼睛会看到什么？', `MaleText_loc5`='他何時到的，他那對矮人雙眼看見了什麼?', `MaleText_loc7`='Cuando el enano llegó allí, ¿qué creéis que con sus ojos vio?' WHERE `ID`=50909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수북이 쌓인 상자 속 보리로, 수없이 벌꿀 술을 만들었지!', `MaleText_loc4`='那里有上百箱的大麦会被酿成美酒！', `MaleText_loc5`='在那有上百箱大麥可以讓他釀成酒!', `MaleText_loc7`='¡Cientos de cajas de cebada para hacer hidromiel, que alguien se olvidó!' WHERE `ID`=50910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 죽음의 역병에 벌꿀 술은 저주받았고, 하하, 이제 사나이 두간도 마찬가지.', `MaleText_loc4`='但那些美酒受到了死亡的诅咒，现在，老杜甘也被诅咒了。', `MaleText_loc5`='不過酒都感染了死亡瘟疫的詛咒，就連老杜甘也是。', `MaleText_loc7`='Pero el hidromiel estaba maldito con la plaga de la muerte, y a Duggan lo mismo le ocurrió.' WHERE `ID`=50911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리치 왕의 괴물들에게 둘러싸여, 이제 사나이 두간은 어떻게 할까?', `MaleText_loc4`='老杜甘被巫妖王的爪牙包围了，老杜甘能做些什么？', `MaleText_loc5`='被巫妖王手下的爪牙所包圍，你說老杜甘能怎麼辦?', `MaleText_loc7`='Estaba rodeado por las bestias del Rey Exánime, ¿pero creéis que Duggan se abatió?' WHERE `ID`=50912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 안에선 역병이 퍼져도, 내일의 희망은 아직 남았네.', `MaleText_loc4`='虽然我感觉到了体内的诅咒，但是我的希望并没有泯灭。', `MaleText_loc5`='不過即使我能感覺到瘟疫仍蔓延其中，仍有一絲希望。', `MaleText_loc7`='Aunque siento la peste en mi interior, mis esperanzas no se han desvanecido.' WHERE `ID`=50913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무튼 스컬지가 될 운명이라면, 아예 술에 진탕 취해나 보세!', `MaleText_loc4`='如果我真的会成为天灾恶鬼，那我最好还是先喝醉了吧！', `MaleText_loc5`='如果我會加入天譴軍，那我一定是喝醉了!', `MaleText_loc7`='Si voy a formar parte de la Plaga, ¡más me vale que esté bebido!' WHERE `ID`=50914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순간이동기가 자네를 북부 가시덤불에 있는 그롬골로 순간이동시킬 거야.$B$B별 일이 없다면 말이지.$B$B내 말은 가끔 이 고물이 자네를 해체해버리거나 몸 안의 연조직을 악취가 나는 녹색 연기로 만들어버릴지도 모른다는 거지. 그렇지만 대체로 안전해!$B$B항상은 아니지만 말이야.', `MaleText_loc4`='这个传送器将把你传送至北荆棘谷的格罗姆高那里。$B$B通常都会是这样。$B$B我的意思是说，有时候它会把你分解，或者让你全身的软组织都变成散发着臭气的绿色烟雾。不过大多数情况下它还是安全的！$B$B……大多数情况。', `MaleText_loc5`='這個傳送器會將你傳送到北荊棘谷的格羅姆高營地。$B$B一般來說是這樣啦。$B$B我的意思是，有時候可能會把你給分解掉，或是讓你全身上下的軟體組織變成綠色的、聞起來臭臭的，不過大多數時候還是安全的啦!$B$B...大多數時候啦。', `MaleText_loc7`='Este teletransporte te llevará a Grom''gol, en el Norte de la Vega de Tuercespina.$B$BNormalmente.$B$BLo que quiero decir es que, a veces, te desintegrará o reducirá todo tu tejido blando a una especie de gelatina verde de hedor insoportable. Pero, en general, ¡es bastante seguro!$B$B... en general.' WHERE `ID`=50915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 순간이동기는 자네를 던 모로 아래 깊숙이 자리 잡은 놈리건의 오염된 폐허로 순간이동시킬 거야.$B$B걱정 마. 자네를 여기로 돌려보내 줄 사람이 거기 있긴 하니까... 물론 이게 자네 피부를 뒤집어 놓거나 신체 장기를 유기질 폭탄으로 변이시키지 말아야겠지!$B$B뭘 머뭇거려? 어서 올라가!', `MaleText_loc4`='这个传送器将把你传送至丹莫罗地下深处，那个充满辐射的诺莫瑞根废墟。$B$B别担心，那里还有另一个传送器，可以把你送回到这里……嗯，它也有可能让你身体的里里外外彻底翻转过来，或者把你全身的组织变成不稳定的有机爆炸物，就是这样！$B$B怎么啦？你还在等什么？跳进去吧！', `MaleText_loc5`='這個傳送器會將你傳送到丹莫洛地底深處，四處都是輻射的諾姆瑞根廢墟。$B$B別擔心，在那邊還有另一個傳送器可以送你回來...嗯，好吧，當然前提是傳送器沒把你內外翻面，或是把你的器官變成不穩定的炸彈!$B$B了?還在等什麼?快進去呀!', `MaleText_loc7`='Este teletransporte te llevará a las ruinas irradiadas de Gnomeregan, que están en las profundidades debajo de Dun Morogh.$B$BNo te preocupes, allí hay otro que te permitirá regresar aquí... Bueno, si no te vuelve del revés o transfigura tus órganos en explosivos orgánicos, claro está.$B$B¿Y bien? ¿A qué esperas? ¡Entra!' WHERE `ID`=50916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 마녀 아벤디스의 손아귀에서 벗어나 내 꿈을 찾을 때가 왔다! 피! 피, 더 많은 피를 내놔라!', `MaleText_loc4`='终于摆脱阿比迪斯那个疯婆娘了，我现在可以去追求我自己的目标了：鲜血，鲜血，更多的鲜血！', `MaleText_loc5`='終於脫離了阿比迪斯那個女巫的控制，現在我可以去追求自身的喜好了:那就是血、血、更多的血!', `MaleText_loc7`='Por fin libre de la tiranía de esa bruja de Abbendis, y libre para perseguir mis propios intereses: ¡SANGRE, SANGRE Y MÁS SANGRE!', `FemaleText_loc1`='마침내 마녀 아벤디스의 손아귀에서 벗어나 내 꿈을 찾을 때가 왔다! 피! 피, 더 많은 피를 내놔라!', `FemaleText_loc4`='终于摆脱阿比迪斯那个疯婆娘了，我现在可以去追求我自己的目标了：鲜血，鲜血，更多的鲜血！', `FemaleText_loc5`='終於脫離了阿比迪斯那個女巫的控制，現在我可以去追求自身的喜好了:那就是血、血、更多的血!', `FemaleText_loc7`='Por fin libre de la tiranía de esa bruja de Abbendis, y libre para perseguir mis propios intereses: ¡SANGRE, SANGRE Y MÁS SANGRE!' WHERE `ID`=50917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 주간 먹질 못했다. 이 빵은 내 거야! 샌드위치를 위하여!', `MaleText_loc4`='我已经有好几周没吃过东西了，这块面包是我的！为了三明治！', `MaleText_loc5`='我好幾周沒吃東西了...這麵包是我的!為了三明治!', `MaleText_loc7`='Hace semanas que no como; ¡este pan es mío! ¡PARA EL SÁNDWICH!' WHERE `ID`=50918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너... 맛있겠구나!', `MaleText_loc4`='我断定……你很美味！', `MaleText_loc5`='我覺得你...蠻美味的!', `MaleText_loc7`='¡Creo que eres... $gDELICIOSO:DELICIOSA;!' WHERE `ID`=50919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아벤디스 님은 돌아오실 거다. 그리고 난 그분을 기다릴 거고! 그분은 우릴 위해 돌아오실 거야!', `MaleText_loc4`='阿比迪斯会回来的，我会一直等待她的归来！为了我们，她一定会回来的！', `MaleText_loc5`='阿比迪斯會回來的，而我，我會守候著她!她將會為了我們歸來!', `MaleText_loc7`='¡Abbendis volverá, y yo la estaré esperando! ¡VOLVERÁ A POR NOSOTROS!', `FemaleText_loc1`='아벤디스 님은 돌아오실 거다. 그리고 난 그분을 기다릴 거고! 그분은 우릴 위해 돌아오실 거야!', `FemaleText_loc4`='阿比迪斯会回来的，我会一直等待她的归来！为了我们，她一定会回来的！', `FemaleText_loc5`='阿比迪斯會回來的，而我，我會守候著她!她將會為了我們歸來!', `FemaleText_loc7`='¡Abbendis volverá, y yo la estaré esperando! ¡VOLVERÁ A POR NOSOTROS!' WHERE `ID`=50920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲에서 네 악취를 몰아내겠다, 이 괴물아!', `FemaleText_loc4`='我会把你在这片森林中留下的恶臭清除干净，怪物！', `FemaleText_loc5`='怪物，我會把你的惡臭氣味從森林中驅除出去!', `FemaleText_loc7`='¡Eliminaré tu hedionda pestilencia del bosque, monstruo!' WHERE `ID`=50921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 축제에 잘 왔어, 친구. 특별히 준비한 게 있으니, 조금만 기다리라고.', `MaleText_loc4`='朋友，欢迎参加这场盛宴。瞧瞧这次我都给你们准备了什么好戏。', `MaleText_loc5`='歡迎觀賞精采的演出，朋友。別錯過為你們準備的好戲啊。', `MaleText_loc7`='Bienvenidos al gran espectáculo, amigos. Esperen y verán lo que les tengo preparado.' WHERE `ID`=50923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼!!!', `MaleText_loc4`='不……不！！', `MaleText_loc5`='不...不!!!', `MaleText_loc7`='¡¡¡No... NOOOO!!!' WHERE `ID`=50924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 진도를 막을쏘냐!', `MaleText_loc4`='没人能阻止金度！', `MaleText_loc5`='沒人可以阻止金度!', `MaleText_loc7`='¡NADIE detendrá a Jin''do!' WHERE `ID`=50925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풀과 모래, 그리고 진흙 혼합물이 한데 섞인 곳에 희미한 발자국이 찍혀 있습니다.', `MaleText_loc4`='草、沙子和软泥混合在一起，差不多就是这些脚印的样子。', `MaleText_loc5`='青草、沙子及淤泥混合成一種像是腳印的模糊痕跡。', `MaleText_loc7`='Hierba, arena y lodo se mezclan para crear algo que recuerda vagamente a una huella.' WHERE `ID`=50927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생물체가 발을 질질 끈 것 같은 흔적이 질척하게 나 있습니다.', `MaleText_loc4`='这些脚印都有涂抹的痕迹，就好象这只生物是拖着脚行走一样。', `MaleText_loc5`='這些斑駁的足跡就像是有生物拖著腳移動一樣。', `MaleText_loc7`='Las huellas están emborronadas, como si la criatura arrastrara los pies al andar.' WHERE `ID`=50928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진흙과 함께 섞인 것은 근처 시설에서 나온 기름투성이 흔적입니다.', `MaleText_loc4`='这些泥巴中还混合着来自于附近钻探设备的油性软泥。', `MaleText_loc5`='足跡中的淤泥混有來自附近鑽油設備的油污。', `MaleText_loc7`='Mezclados con el barro hay rastros del lodo aceitoso de la torre de perforación cercana.' WHERE `ID`=50929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔적에 핏자국이 보입니다. 당신은 괴생물체가 최근에 잡아먹은 먹잇감의 시체가 있는 곳을 따라 근처의 덤불로 갑니다.', `MaleText_loc4`='这些足迹中带有血污。你跟随着它们，找到了附近的一个灌木丛。这里隐藏着这只怪物吃过的猎物残骸。', `MaleText_loc5`='這道血淋淋的足跡延伸到附近的灌木叢中，在那裡你找到了這隻生物吃剩的上一餐。', `MaleText_loc7`='El rastro es sangriento. Lo sigues hasta un arbusto cercano, donde encuentras los restos del último almuerzo de la criatura.' WHERE `ID`=50930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 흔적은 생긴 지 얼마 되지 않았으며, 물속으로 이어집니다...', `MaleText_loc4`='这些足迹是刚留下的，直接指向了水中……', `MaleText_loc5`='足跡還很新，一路延伸到水裡...', `MaleText_loc7`='Estas huellas son frescas y van directas hacia el agua...' WHERE `ID`=50931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순간이동기 시험 가동이 끝났다고 브락이 그러던가요? 아무튼 노즐팟의 전초기지로 돌아가고 싶으면 제게 말만 하세요! 팔다리가 온전하게 붙은 채로 돌아갔으면 좋겠네요.', `FemaleText_loc4`='布拉克有没有说过，这个传送器是否进行过测试？嗯，如果你准备好了要返回诺兹波特的哨站，就说一句！希望你能完整无缺地到达那里。', `FemaleText_loc5`='巴拉克有沒有跟你說這個傳送器是否經過測試?好吧，如果你準備好要動身回到管壺前哨，只要說一聲就行了!希望你能完好無缺地抵達目的地。', `FemaleText_loc7`='¿Dijo Brak si ya se había probado este teletransportador? Bueno, si quieres volver a la Avanzada de Ollaboquilla, no tienes más que decirlo. Espero que llegues de una pieza.' WHERE `ID`=50933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저거 봤어요? 방금 누가 하늘에서 떨어졌어요!', `FemaleText_loc4`='看到了吗？有人从天上掉下来了！', `FemaleText_loc5`='你看到了嗎?剛有人從天上掉下來!', `FemaleText_loc7`='¿Has visto eso? ¡Alguien ha caído del cielo!' WHERE `ID`=50934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노즐팟의 전초기지로 돌아가고 싶습니다.', `MaleText_loc4`='送我回诺兹波特的哨站。', `MaleText_loc5`='送我回管壺前哨。', `MaleText_loc7`='Envíame de vuelta a Avanzada de Ollaboquilla.', `FemaleText_loc1`='노즐팟의 전초기지로 돌아가고 싶어요.', `FemaleText_loc4`='送我回诺兹波特的哨站。', `FemaleText_loc5`='送我回管壺前哨。', `FemaleText_loc7`='Envíame de vuelta a Avanzada de Ollaboquilla.' WHERE `ID`=50935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 진짜 빠르네요!', `MaleText_loc4`='喔，这可真快啊！', `MaleText_loc5`='哇喔，這一定很快!', `MaleText_loc7`='¡Vaya, sí que va rápido!' WHERE `ID`=50936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 것이 겁도 없이 구루바시의 계획을 방해했겠다? 이젠 너무 늦었다. 너무 늦었다고. 너흰 모두 끝이야!', `MaleText_loc4`='你想干扰古拉巴什的计划，小东西。你太迟了，你们都太迟了！', `MaleText_loc5`='你干擾了古拉巴什的計畫，小傢伙。來不及了。你們全都來不及了!', `MaleText_loc7`='Perturbasss los planesss de los Gurubashi, gusano. Esss demasssiado tarde para ti. ¡Para todosss ustedesss!' WHERE `ID`=50937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하하하! 이교도들아... 베데크의 진정한 힘을 보여 주마!', `FemaleText_loc4`='哈哈哈哈哈！无信者……面对贝瑟克的真正力量！', `FemaleText_loc5`='哈哈哈哈!現在，異教徒們...面對比塞克真正的力量吧!', `FemaleText_loc7`='¡Jaaa, ja, jaaaa! Ahora, paganos... ¡enfréntense al VERDADERO poder de Bethekk!' WHERE `ID`=50938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 한 거야? 힘을... 억제할 수가...', `FemaleText_loc4`='你做了什么？我……不能控制……啊啊啊呃！', `FemaleText_loc5`='你做了什麼?我控制...控制不了...哇啊啊啊啊!', `FemaleText_loc7`='¿Qué has hecho? No puedo... controlar... ¡RRAAAARRRGHHH!' WHERE `ID`=50939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 어서 출발합시다!', `MaleText_loc4`='我准备好了。出发吧！', `MaleText_loc5`='準備好了。出發吧!', `MaleText_loc7`='Estoy listo. ¡Adelante!', `FemaleText_loc1`='준비됐어요. 어서 가요!', `FemaleText_loc4`='我准备好了。出发吧！', `FemaleText_loc5`='準備好了。出發吧!', `FemaleText_loc7`='Estoy lista. ¡Adelante!' WHERE `ID`=50940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 아직 무사하다니 다행이군! 로켓이 먼저 날아가면서 당신이 비명을 지르는 소리가 들리기에 약간 걱정했소.$B$B이제 마지막 짐 하나만 더 수송하면 되오. 준비되면 내게 알려주시오. 그러면 곧장 출발할 것이오.', `MaleText_loc4`='$n，你还活着？这太好了！刚才我看见一支火箭飞上了半天，还听见你在尖叫，不由得有些担心。$B$B我们还有最后一批货要运。准备好以后就来找我，然后我们就出发。', `MaleText_loc5`='$n，真高興能看到你沒事!先前我看到火箭升空，然後聽到你的尖叫聲，讓我有點擔心。$B$B接下來只剩最後一批貨要處理。你準備好的時候跟我說，然後我們就出發。', `MaleText_loc7`='¡$n, me alegro de verte de una pieza! Hace un rato he visto pasar un cohete a toda velocidad y te he oído gritar, así que estaba un poco preocupado.$B$BTenemos que ocuparnos de un último envío. Habla conmigo cuando quieras ponerte en marcha.' WHERE `ID`=50941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 올라타시오! 이 짐마차는 몰샨의 망루 행이오!', `MaleText_loc4`='所有人都准备好了！商队将前往莫尔杉农场！', `MaleText_loc5`='大家出發了!商隊該動身前往莫爾杉壁壘了!', `MaleText_loc7`='¡Todo el mundo a bordo! ¡Esta caravana parte hacia La Empalizada de Mor''shan!' WHERE `ID`=50942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤쪽은 괜찮소? 너무 덜컹거리지 않았으면 좋겠군.', `MaleText_loc4`='那里的路况怎样？希望不要太颠簸。', `MaleText_loc5`='後面的人還好嗎?我希望這趟路不會太過顛簸。', `MaleText_loc7`='¿Qué tal te va ahí atrás? Espero que no te molesten mucho los baches.' WHERE `ID`=50943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자로에서 이 정도로 가까운 거리에서는 적들이 우리를 감히 공격하지 못할 것이오. 조심해야 할 건 멀리 있는 적들이라오.', `MaleText_loc4`='在这么靠近十字路口的地方，敌人不敢攻击我们。但继续前进的话，我们就要提高警惕了。', `MaleText_loc5`='這裡很靠近十字路口，敵人還不敢發動攻擊，但到遠一點的地方我們就必須提高警覺了。', `MaleText_loc7`='Nuestros enemigos no se atreverán a atacarnos tan cerca de El Cruce. Es más adelante donde tendremos que estar ojo avizor.' WHERE `ID`=50944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮다면 공포안개 야영지에 정차해 마지막 여정을 위한 추가 보급품과 새 말을 보충하겠소.', `MaleText_loc4`='希望你不要介意，我们要在鬼雾营地装载另一批补给品，并让拉车的牲口得到休息和食水，为最后一段路程做好准备。', `MaleText_loc5`='我們會在鬼霧營地補給一些物品，順便讓長途跋涉的坐騎休息一下，希望你不會介意。', `MaleText_loc7`='Espero que no te importe, pero haremos una parada en Campamento Calígine para recoger unos cuantos suministros y monturas frescas para la última parte del viaje.' WHERE `ID`=50945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브웸바가 뭘 도와 드릴까요?', `FemaleText_loc4`='布温巴能帮得上你吗？', `FemaleText_loc5`='有什麼需要布恩巴幫忙的嗎?', `FemaleText_loc7`='¿Cómo puede ayudah''te Bwemba?' WHERE `ID`=50949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제... 독 앞에 무릎 꿇어라...', `MaleText_loc4`='对，承受这死亡的剧毒……', `MaleText_loc5`='是的...屈服於劇毒之下...', `MaleText_loc7`='Sssí... sssucumban al veneno…' WHERE `ID`=50950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 여행자들의 몸에서 독을 제거해 주십시오.', `MaleText_loc4`='我需要你的帮助，才能除去这些冒险者身上的毒。', `MaleText_loc5`='我需要你幫我為這些冒險者解毒。', `MaleText_loc7`='Necesito tu ayuda para eliminar el veneno de estos aventureros.', `FemaleText_loc1`='이 여행자들의 몸에서 독을 제거해 주세요.', `FemaleText_loc4`='我需要你的帮助，才能除去这些冒险者身上的毒。', `FemaleText_loc5`='我需要你幫我為這些冒險者解毒。', `FemaleText_loc7`='Necesito tu ayuda para eliminar el veneno de estos aventureros.' WHERE `ID`=50951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 원하시는군요? 하지만 그 힘을 위해 제가 걸어온 저주받은 길을 당신도 걸을 수 있으십니까?', `MaleText_loc4`='你在寻求力量？但你能走过我铺下的诅咒之路吗？', `MaleText_loc5`='你在尋求力量，是嗎?但是你會願意像我一樣踏上那條受詛咒的道路嗎?', `MaleText_loc7`='Buscas poder, ¿verdad? Pero, ¿recorrerás el camino maldito como yo para conseguirlo?', `FemaleText_loc1`='힘을 원하시는군요? 하지만 그 힘을 위해 제가 걸어온 저주받은 길을 당신도 걸을 수 있으십니까?', `FemaleText_loc4`='你在寻求力量？但你能走过我铺下的诅咒之路吗？', `FemaleText_loc5`='你在尋求力量，是嗎?但是你會願意像我一樣踏上那條受詛咒的道路嗎?', `FemaleText_loc7`='Buscas poder, ¿verdad? Pero, ¿recorrerás el camino maldito como yo para conseguirlo?' WHERE `ID`=50952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 걷는 길은 어둡고 저주받은 길이지요, $c님. 저와 함께 이 길을 가고 싶지는 않으실 겁니다.', `MaleText_loc4`='我的道路是黑暗的，受到诅咒的。$c，你不会想要和我同行的。', `MaleText_loc5`='在我面前是一片黑暗，充滿了詛咒，$c。你不會想跟我一起走下去的。', `MaleText_loc7`='Mi camino es oscuro y maldito, $c. No te conviene caminar conmigo.', `FemaleText_loc1`='제가 걷는 길은 어둡고 저주받은 길이지요, $c님. 저와 함께 이 길을 가고 싶지는 않으실 겁니다.', `FemaleText_loc4`='我的道路是黑暗的，受到诅咒的。$c，你不会想要和我同行的。', `FemaleText_loc5`='在我面前是一片黑暗，充滿了詛咒，$c。你不會想跟我一起走下去的。', `FemaleText_loc7`='Mi camino es oscuro y maldito, $c. No te conviene caminar conmigo.' WHERE `ID`=50953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 왔소. 짐을 싣는 동안 잠깐 기다려 주시오... 이봐! 뭐하는 짓이야!?', `MaleText_loc4`='我们来了。别着急，先等我们装货……嘿！出什么事了！？', `MaleText_loc5`='我們到了。我們裝載貨物不會花太多時間的，稍等一下就好...嘿!怎麼回事!?', `MaleText_loc7`='Ya estamos. Espera un segundo mientras cargo... ¡Eh! ¿Qué pasa?' WHERE `ID`=50954;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러! 내가 물건 훔치는 동안 아무나 한 놈 잡으라고!', `FemaleText_loc4`='快点！抓活口。我去对付补给车！', `FemaleText_loc5`='動作快點!我去搶補給車，這兩個你們挑一個帶走!', `FemaleText_loc7`='¡Rápido! ¡Agarra uno de ellos mientras yo me encargo del carro de suministros!' WHERE `ID`=50955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길드 서비스', `MaleText_loc4`='公会服务', `MaleText_loc5`='公會服務', `MaleText_loc7`='Servicios de hermandad', `FemaleText_loc1`='길드 서비스', `FemaleText_loc4`='公会服务', `FemaleText_loc5`='公會服務', `FemaleText_loc7`='Servicios de hermandad' WHERE `ID`=50956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스 길드 사무관과 길드 상인, 휘장 상인은 도시 중심부인 빛의 정원 중앙에 있는 건물에 모여 있습니다.', `MaleText_loc4`='你能在城市正中，圣光广场中心的建筑物里找到沙塔斯的公会管理员——以及公会和战袍商人。', `MaleText_loc5`='你可以在撒塔斯城中心、聖光露臺中央的建築物中找到公會註冊員、公會商人及外袍商人。', `MaleText_loc7`='Encontrarás al maestro de hermandad de Shattrath, al igual que a los vendedores de tabardos y de hermandad, dentro de la estructura central del Bancal de la Luz, en medio de la ciudad.', `FemaleText_loc1`='샤트라스 길드 사무관과 길드 상인, 휘장 상인은 도시 중심부인 빛의 정원 중앙에 있는 건물에 모여 있습니다.', `FemaleText_loc4`='你能在城市正中，圣光广场中心的建筑物里找到沙塔斯的公会管理员——以及公会和战袍商人。', `FemaleText_loc5`='你可以在撒塔斯城中心、聖光露臺中央的建築物中找到公會註冊員、公會商人及外袍商人。', `FemaleText_loc7`='Encontrarás al maestro de hermandad de Shattrath, al igual que a los vendedores de tabardos y de hermandad, dentro de la estructura central del Bancal de la Luz, en medio de la ciudad.' WHERE `ID`=50957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다.', `MaleText_loc4`='感谢你的帮助。', `MaleText_loc5`='多謝你出手相助。', `MaleText_loc7`='Gracias por tu ayuda.', `FemaleText_loc1`='도와주셔서 고마워요.', `FemaleText_loc4`='感谢你的帮助。', `FemaleText_loc5`='多謝你出手相助。', `FemaleText_loc7`='Gracias por tu ayuda.' WHERE `ID`=50958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 상급자들은 빛의 정원 중앙 건물 1층에 흩어져 있습니다.$B$B당신이 알도르든 점술가든 둘 다 아니든, 누군가는 당신을 도와줄 겁니다.', `MaleText_loc4`='职业训练师都在圣光广场中心建筑物一层的各翼区中。$B$B无论是奥尔多，占星者还是其他什么人，总有人能帮助你的。', `MaleText_loc5`='職業訓練師就在聖光露臺中央的建築物裡，分佈在各樓層之中。$B$B不管是奧多爾、占卜者，或是其他陣營，總有人能幫你的。', `MaleText_loc7`='Encontrarás a los instructores de clase en las diferentes alas de la planta baja de la estructura central del Bancal de la Luz.$B$BYa seas Aldor, Arúspice u otra cosa, ellos podrán ayudarte.', `FemaleText_loc1`='직업 상급자들은 빛의 정원 중앙 건물 1층에 흩어져 있습니다.$B$B당신이 알도르든 점술가든 둘 다 아니든, 누군가는 당신을 도와줄 겁니다.', `FemaleText_loc4`='职业训练师都在圣光广场中心建筑物一层的各翼区中。$B$B无论是奥尔多，占星者还是其他什么人，总有人能帮助你的。', `FemaleText_loc5`='職業訓練師就在聖光露臺中央的建築物裡，分佈在各樓層之中。$B$B不管是奧多爾、占卜者，或是其他陣營，總有人能幫你的。', `FemaleText_loc7`='Encontrarás a los instructores de clase en las diferentes alas de la planta baja de la estructura central del Bancal de la Luz.$B$BYa seas Aldor, Arúspice u otra cosa, ellos podrán ayudarte.' WHERE `ID`=50959;
