UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 트롤이라고? 독사보다는 낫군요...', `MaleText_loc4`='另一个巨魔？至少你不是一条毒蛇……', `MaleText_loc5`='又一名食人妖?只要不是蛇就好...', `MaleText_loc7`='¿Otro trol? Al menos no eres una serpiente...', `FemaleText_loc1`='또 다른 트롤인가요? 독사보다는 낫네요...', `FemaleText_loc4`='另一个巨魔？至少你不是一条毒蛇……', `FemaleText_loc5`='又一名食人妖?只要不是蛇就好...', `FemaleText_loc7`='¿Otro trol? Al menos no eres una serpiente...' WHERE `ID`=50961;
