UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 나갈라! 동생이 배고파하는데 점심이나 먹는 게 어때?', `MaleText_loc4`='哦，娜格拉！给你饥饿的兄弟来些午餐如何？', `MaleText_loc5`='唷，納迦拉!給你那快餓扁的弟弟來份午餐如何呀?', `MaleText_loc7`='¡Eh, Nagala! ¿Qué tal si traes algo de comer para tu hermano que se muere de hambre?' WHERE `ID`=50968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='허리둘레가 더 늘어났구나, 우리 귀여운 동생! 이리 내려와서 누나에게 안기렴!', `FemaleText_loc4`='你的腰变粗了几寸，小兄弟！到这里来，给你的姐姐一个拥抱吧！', `FemaleText_loc5`='你的腰圍又多了幾圈，老弟!快來抱抱你姐!', `FemaleText_loc7`='¡Has engordado un poco en la cintura, hermanito! ¡Ven aquí y dale un abrazo a tu hermana!' WHERE `ID`=50969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누굴 잡으라는 거야?', `MaleText_loc4`='我应该对付哪个？', `MaleText_loc5`='我該抓哪個?', `MaleText_loc7`='¿Cuál debería elegir?' WHERE `ID`=50970;
