UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 보세요! 나쁜 놈들이 감시의 언덕을 공격하고 있어요! 경비병 아저씨들, 힘내세요! 놈들을 혼내 주세요!', `MaleText_loc4`='小心，有人正在进攻哨兵岭。卫兵们，一定要打败敌人！', `MaleText_loc5`='看啊，哨兵嶺正遭受攻擊。上吧守衛們，你們一定要打贏!', `MaleText_loc7`='Mira, alguien está atacando la Colina del Centinela. ¡Vamos, guardias, tenéis que ganar!' WHERE `ID`=50977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무가 막 날아다니는 건 처음 봐요. 우리 가까이 가 봐요!', `MaleText_loc4`='我还从没有见过一棵飞行的树呢。让我们再靠近些！', `MaleText_loc5`='我從未見過會飛的樹。咱們靠近點瞧瞧!', `MaleText_loc7`='Nunca había visto un árbol volador. ¡Acerquémonos!' WHERE `ID`=50978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 재밌어 보여요! 저도 운전해 보고 싶지만... 보육원 원장님이 다 클 때까진 탈것을 몰면 안 된다고 하셨어요.', `MaleText_loc4`='这看上去真有趣！我真想自己驾驶一下。但监护员说我年纪还太小，不能有坐骑。', `MaleText_loc5`='看起來真有趣!我也想騎看看，可是孤兒監護員說，要等我長大才能有坐騎。', `MaleText_loc7`='¡Eso parece divertido! Quiero conducir, pero la supervisora de huérfanos dice que no puedo conseguir una montura hasta que sea mayor.' WHERE `ID`=50979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수액괴물이 정말 많군요. 하나가 제 쪽으로 와요!', `MaleText_loc4`='小心那些软泥怪。有一个直冲我过来了！', `MaleText_loc5`='看看這個泥漿怪。喔它正筆直地朝我飛來!', `MaleText_loc7`='Mira toda esa baba. ¡Una viene volando directa hacia mí!' WHERE `ID`=50980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우웩, 얼굴에 달라붙었어요! 떼 주세요!', `MaleText_loc4`='啊，它跑到我的头顶上了！救命！', `MaleText_loc5`='天啊啊啊啊!在我頭上!救命呀!', `MaleText_loc7`='¡Aaaaaaaaagh, está encima de mi cabeza! ¡Socorro!' WHERE `ID`=50981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 %s의 번개 공격이 시작됩니다! 피해야 합니다!', `MaleText_loc4`='%s要用闪电轰击你了！快闪！', `MaleText_loc5`='%s正準備賞你一發閃電!快跑!', `MaleText_loc7`='¡%s está a punto de lanzarte un relámpago! ¡Huye!', `FemaleText_loc1`='곧 %s의 번개 공격이 시작됩니다! 피해야 합니다!', `FemaleText_loc4`='%s要用闪电轰击你了！快闪！', `FemaleText_loc5`='%s正準備賞你一發閃電!快跑!', `FemaleText_loc7`='¡%s está a punto de lanzarte un relámpago! ¡Huye!' WHERE `ID`=50982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽... 속이 좀 울렁거려요...', `MaleText_loc4`='我有点想吐……', `MaleText_loc5`='我的肚子不太舒服...', `MaleText_loc7`='Me duele la tripita...' WHERE `ID`=50983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 우리가 얼마나 높이 날아갔는지 보셨어요?', `MaleText_loc4`='喔！有没有看到我们飞了多高？', `MaleText_loc5`='哇喔!你有沒有看到我們飛多高呀?', `MaleText_loc7`='¡Vaya! ¿Has visto lo alto que hemos subido?' WHERE `ID`=50984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고였어요! 또 타요!', `MaleText_loc4`='这太棒了！我们再来一次吧！', `MaleText_loc5`='棒呆了!再來一次吧!', `MaleText_loc7`='¡Ha sido genial! ¡Hagámoslo otra vez!' WHERE `ID`=50985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 것이 겁도 없이 구루바시의 계획을 방해했겠다? 이젠 너무 늦었다. 너무 늦었다고. 너흰 모두 끝이야!', `MaleText_loc4`='你想干扰古拉巴什的计划，小东西。你太迟了。你们都太迟了！', `MaleText_loc5`='你干擾了古拉巴什的計畫，小傢伙。來不及了。你們全都來不及了!', `MaleText_loc7`='Perturbasss los planesss de los Gurubashi, gusano. Esss demasssiado tarde para ti. ¡Para todosss ustedesss!' WHERE `ID`=50986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 독사들이 이미 온 가시덤불의 바위와 수풀 밑에서 꿈틀대고 있다.', `MaleText_loc4`='荆棘谷每一块岩石和灌木之下都潜伏着我的毒蛇。', `MaleText_loc5`='我的毒蛇，牠們已經游走於荊棘谷的各個角落。', `MaleText_loc7`='Misss serpientesss ya ssse dessslizan bajo cada roca y matorral de Tuercessspina.' WHERE `ID`=50987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 구루바시의 땅, 우리가 되찾는다. 우리를 가로막는 놈들은 모조리 없애 주마!', `MaleText_loc4`='我们会重夺这片土地。古拉巴什之地。阻挡者都要死！', `MaleText_loc5`='我們會拿回這片土地，古拉巴什的土地，並殺了所有阻礙我們的人!', `MaleText_loc7`='Reclamaremosss esta tierra. La tierra Gurubashi. ¡Y mataremosss a quien se interponga en nuesssstro camino!' WHERE `ID`=50988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 구루바시의 땅, 우리가 되찾는다. 우리를 가로막는 놈들은 모조리 없애 주마!', `MaleText_loc4`='我们要夺回我们的古拉巴什。任何敢阻挡我们的人，只有死路一条。', `MaleText_loc5`='我們要取回屬於我們的土地，古拉巴什的土地。我們會殺掉任何礙事的傢伙。', `MaleText_loc7`='Reclamaremos eh''ta tierra. La tierra Gurubashi. Y mataremos a cualquiera que se interponga en nueh''tro camino.' WHERE `ID`=50989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 물어, 오간! 똑같이 당하지 않는다!', `MaleText_loc4`='攻击他们，奥根！我们不会再被愚弄了！', `MaleText_loc5`='宰了他們，奧根!我們不會再次被耍!', `MaleText_loc7`='¡Ve por ellos, Ohgan! ¡NO volverán a tomarnos el pelo!' WHERE `ID`=50990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사라... 최근 어딘가 신비한 구석이 있는 트롤 하나가 장로의 거리 북쪽 끝에 있는 하레네를 찾아왔더군. 그녀가 당신을 도와줄지도 모르겠소.', `MaleText_loc4`='萨满祭司……？一个神秘的巨魔最近来到这里拜访长者步道的哈雷尼。她也许能帮助你。', `MaleText_loc5`='薩滿...?最近有個會使用某種秘術的食人妖來到城內拜會長者步道上的海若妮。她應該有辦法幫你。', `MaleText_loc7`='¿Chamán...? Una especie de mística trol ha llegado a la ciudad recientemente para visitar a Harene en el Camino de los Ancestros. Quizá ella te pueda ayudar.', `FemaleText_loc1`='주술사라... 최근 어딘가 신비한 구석이 있는 트롤 하나가 장로의 거리 북쪽 끝에 있는 하레네를 찾아왔더군요. 그녀가 당신을 도와줄지도 모르겠습니다.', `FemaleText_loc4`='萨满祭司……？一个神秘的巨魔最近来到这里拜访长者步道的哈雷尼。她也许能帮助你。', `FemaleText_loc5`='薩滿...?最近有個會使用某種秘術的食人妖來到城內拜會長者步道上的海若妮。她應該有辦法幫你。', `FemaleText_loc7`='¿Chamán...? Una especie de mística trol ha llegado a la ciudad recientemente para visitar a Harene en el Camino de los Ancestros. Quizá ella te pueda ayudar.' WHERE `ID`=50991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 공원이 있던 자리에 생긴 구멍도 진짜 크다고 생각했는데, 이건 더 큰데다가 회오리바람까지 부네요!', `MaleText_loc4`='我还以为这个公园已经变成了一个大洞。但现在，它更大了，还有了一个大旋风！', `MaleText_loc5`='我覺得暴風城的花園掉進了一個大洞，不過這個洞大的多了，因為裡頭有個旋風!', `MaleText_loc7`='Creí que El Parque se había convertido en un gran agujero, ¡pero este es muchísimo más grande y tiene un remolino!' WHERE `ID`=50992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 나를 제물로 바치려고 하오! 벌써 악마들이 내 시체 위로 침을 뚝뚝 흘리고 있군.$B$B<몸서리치는 발고르>$B$B정말이지 몸무게 줄이는 걸 다시 한 번 생각해봐야겠어.$B$B그건 그렇고, 놈들은 나를 계속 지켜보려고 감시병도 붙여 놓았소. 혼자 이곳을 빠져나갈 순 있지만, 누가 놈들의 주의를 분산시켜야 하오.', `MaleText_loc4`='他们要把我当作祭品！他们的魔鬼就要在我的尸体上舔它们的刀刃了。$B$B<巴尔格打了个哆嗦。>$B$B这让我一点吃东西的胃口都没有。$B$B他们安排了一名卫兵时刻监视着我。我能自己离开这里，但我需要有人吸引卫兵的注意力。', `MaleText_loc5`='他們打算要把我當成祭品!他們那些惡魔真的對著我的屍體舔嘴巴。$B$B<巴爾苟渾身發抖。>$B$B這讓我再三考慮是不是該減肥了。$B$B不管怎樣，他們派了個守衛監視我的一舉一動。我自己能逃出去，但是我需要有人幫我引開注意力。', `MaleText_loc7`='¡Están planeando sacrificarme! Sus demonios ya se relamen pensando en mi cadáver.$B$B<Balgor siente un escalofrío.>$B$BMe hace replantearme mi propia dieta.$B$BDe todas formas, han puesto un guardia que vigila todos mis movimientos. Puedo salir de aquí, pero necesito una buena distracción.' WHERE `ID`=50993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요? 불타는 칼날단 놈들이 동생을 납치했다고요?', `FemaleText_loc4`='什么！？火刃绑架了我的兄弟？', `FemaleText_loc5`='什麼!?燃刃氏族綁走了我的兄弟?', `FemaleText_loc7`='¡¿Qué?! ¿El Filo Ardiente ha secuestrado a mi hermano?' WHERE `ID`=50994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='북쪽의 잿빛 골짜기로 가는 보급 짐마차들은 모두 이곳에서 휴식을 취하고 재정비하지요. 원활하게 보급이 이루어지도록 하는 건 정말 중요한 일입니다.', `FemaleText_loc4`='全部前往北方灰谷的运输队都会在这里停留，休息并补充食水。确保这里一切工作正常是非常重要的。', `FemaleText_loc5`='任何要往北進入梣谷的補給都會在此歇息，同時補充燃料。維持運行順暢無礙對我們十分重要。', `FemaleText_loc7`='Todos los suministros que vuelan hacia el norte, a Vallefresno, se detienen aquí para descansar y repostar. Es vital que mantengamos nuestras operaciones sin problemas.' WHERE `ID`=50995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급 짐마차를 탈 준비가 끝났습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我已經準備好出發了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='보급 짐마차를 탈 준비가 끝났어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我已經準備好出發了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=50996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 한 쌍이 도시를 방문 중일세. 포세이큰의 "상태"라나, 뭐 그런 걸 좀 더 알아보려고 멀고어에서 왔다더군.$B$B연금술 실험실 옆에 있는 약초채집가 근처에 있을 걸세.', `MaleText_loc4`='有两个牛头人来到了这里。我听说他们从莫高雷来，想要了解更多关于被遗忘者的“状况”，或者是与之相关的一些事。$B$B你可以在炼金房的草药师旁边找到他们。', `MaleText_loc5`='有對牛頭人來拜訪這座城市。聽說他們是從莫高雷來這，好像是想了解被遺忘者的「病情」，還是關於那種疫病的效果之類的事情。$B$B你可以在鍊金房的草藥師那邊找到他們。', `MaleText_loc7`='Hay un par de tauren de visita por la ciudad. Me han dicho que han venido desde Mulgore para investigar la "aflicción" de los no-muertos o algo así.$B$BLos encontrarás cerca del herborista en El Apothecarium.', `FemaleText_loc1`='타우렌 한 쌍이 도시를 방문 중일세. 포세이큰의 "상태"라나, 뭐 그런 걸 좀 더 알아보려고 멀고어에서 왔다더군.$B$B연금술 실험실 옆에 있는 약초채집가 근처에 있을 걸세.', `FemaleText_loc4`='有两个牛头人来到了这里。我听说他们从莫高雷来，想要了解更多关于被遗忘者的“状况”，或者是与之相关的一些事。$B$B你可以在炼金房的草药师旁边找到他们。', `FemaleText_loc5`='有對牛頭人來拜訪這座城市。聽說他們是從莫高雷來這，好像是想了解被遺忘者的「病情」，還是關於那種疫病的效果之類的事情。$B$B你可以在鍊金房的草藥師那邊找到他們。', `FemaleText_loc7`='Hay un par de tauren de visita por la ciudad. Me han dicho que han venido desde Mulgore para investigar la "aflicción" de los no-muertos o algo así.$B$BLos encontrarás cerca del herborista en El Apothecarium.' WHERE `ID`=50997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_heroicleap.blp:20|t %s|1이;가; |cFFFF0000|Hspell:96740|h[황폐의 격돌]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_heroicleap.blp:20|t%s开始施放|cFFFF0000|Hspell:96740|h[毁灭猛击]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_heroicleap.blp:20|t%s開始施放|cFFFF0000|Hspell:96740|h[壞滅猛擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_heroicleap.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:96740|h[Embate apabullante]|h|r!' WHERE `ID`=50998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 세상에 있는 모든 다이아몬드 중에 제일 크겠는데요!', `MaleText_loc4`='这一定是全世界最大的钻石！', `MaleText_loc5`='這一定是史上最大的鑽石!', `MaleText_loc7`='¡Este debe ser el diamante más grande que ha existido nunca!' WHERE `ID`=50999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 마그니 폐하의 초상화랑 똑같이 생겼어요! 정말 스스로 이렇게 되신 건가요?', `MaleText_loc4`='这看上去就像是麦格尼国王的雕像！他真的是自己把自己弄成这样的？', `MaleText_loc5`='看起來也像是麥格尼·銅鬚國王的畫!他真的對自己這樣做了?', `MaleText_loc7`='¡Y se parece un montón a los cuadros del rey Magni! ¿De verdad que se hizo esto a sí mismo?' WHERE `ID`=51000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇단다, 꼬마야. 그분께선 백성의 안전을 위해 고대의 티탄 의식을 수행하셨지만, 결과는 이렇게 되고 말았지.', `MaleText_loc4`='是啊，孩子。他曾经想借助一个古老的泰坦仪式保护他的人民，但这也让他自己变成了这种样子。', `MaleText_loc5`='沒錯，小夥子。他想要運用古老的泰坦儀式來保護他的人民，但這個儀式反而保護了他。', `MaleText_loc7`='Sí, camarada. Intentó usar un antiguo ritual de los titanes para mantener a salvo a su pueblo, y esto es lo que le hizo a él.' WHERE `ID`=51001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 별로 좋은 생각은 아니었네요...', `MaleText_loc4`='喔，我可不认为这是个好主意……', `MaleText_loc5`='哇，我可不覺得這會是個好主意...', `MaleText_loc7`='Vaya, no creo que fuera tan buena idea...' WHERE `ID`=51002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하를 잃어서 정말 슬프시겠어요, 아저씨. 하지만, 어떻게 보면 그분은 이제 영원히 아저씨 곁에 있는 거라고요!', `MaleText_loc4`='你们失去了自己的国王，真可怜。但从某种意义上来说，他将永远和你们在一起！', `MaleText_loc5`='很遺憾你失去了你的國王。但是換個角度想，現在他可以永遠陪伴你了!', `MaleText_loc7`='Siento mucho que perdieras a tu rey. Pero en cierta manera, ¡es como si se quedara contigo para siempre!' WHERE `ID`=51003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우리를 발견했다! 짐마차를 지켜라!', `MaleText_loc4`='他们发现我们了！保卫商队！', `MaleText_loc5`='他們發現我們了!保護好商隊!', `MaleText_loc7`='¡Nos han localizado! ¡Defiende la caravana!' WHERE `ID`=51004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 제 잘못입니다, 폐하. 서판을 더 자세히 조사했어야 하는데...', `MaleText_loc4`='这都是我的错，吾王。我应该对那些石板进行更多研究的……', `MaleText_loc5`='是我的錯，大人。我應該多花點時間去研究這些石板才對...', `MaleText_loc7`='Fue culpa mía, mi señor. Debería haber investigado más esas tablillas...' WHERE `ID`=51005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 꼬마야.', `MaleText_loc4`='谢谢你，孩子。', `MaleText_loc5`='謝啦，小夥子。', `MaleText_loc7`='Gracias, camarada.' WHERE `ID`=51006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 날 물었어요!', `MaleText_loc4`='它抓到我了！', `MaleText_loc5`='我被抓到了!', `MaleText_loc7`='¡Me ha pillado!' WHERE `ID`=51007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군, $g형제:자매;여. 훈련을 받고자 왔다면, 내가 가르쳐 주겠다.', `MaleText_loc4`='欢迎，我的$g兄弟:姐妹;。如果你是要来接受训练，我很高兴能满足你的要求。', `MaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', `MaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantado de ayudarte.', `FemaleText_loc1`='반갑군, $g형제:자매;여. 훈련을 받고자 왔다면, 내가 가르쳐 주겠다.', `FemaleText_loc4`='欢迎，我的$g兄弟:姐妹;。如果你是要来接受训练，我很高兴能满足你的要求。', `FemaleText_loc5`='歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。', `FemaleText_loc7`='Te doy la bienvenida, $ghermano:hermana;. Si has venido en busca de instrucción, estaré encantada de ayudarte.' WHERE `ID`=51008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 방식을 배우고 싶은 모양이지만, 난 너를 도울 수가 없다.', `MaleText_loc4`='如果你在寻求古老的技艺，那我无法帮助你。', `MaleText_loc5`='如果你在尋求傳統的訓練方式，我幫不上忙。', `MaleText_loc7`='Si buscas instrucción en las antiguas artes, no puedo ayudarte.', `FemaleText_loc1`='옛 방식을 배우고 싶은 모양이지만, 난 너를 도울 수가 없다.', `FemaleText_loc4`='如果你在寻求古老的技艺，那我无法帮助你。', `FemaleText_loc5`='如果你在尋求傳統的訓練方式，我幫不上忙。', `FemaleText_loc7`='Si buscas instrucción en las antiguas artes, no puedo ayudarte.' WHERE `ID`=51009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 정문 바로 바깥에 다레스라는 늑대인간 드루이드가 있는데, 그가 당신을 도와줄 겁니다.$B$B털이 북슬북슬하고 하얀 가죽옷을 입은 커다란 야수 친구죠. 워낙 눈에 띄니 찾기 쉬울 겁니다.', `MaleText_loc4`='城门外有一个名叫达伦斯的狼人德鲁伊。他也许能帮助你。$B$B他是一头高大的猛兽，身披白色皮毛。你不可能认错他的。', `MaleText_loc5`='在城門外有名叫做達銳斯的狼人德魯伊，他應該能幫上你的忙。$B$B去找一個全身覆滿皮毛的大傢伙，你一眼就能看出是他。', `MaleText_loc7`='Hay un huargen druida llamado Dareth justo en el exterior de las puertas de la ciudad. Quizá pueda ayudarte.$B$BEs un tipo enorme, cubierto de cuero blanco y pelaje. Es imposible pasarlo por alto.', `FemaleText_loc1`='도시 정문 바로 바깥에 다레스라는 늑대인간 드루이드가 있는데, 그가 당신을 도와줄 겁니다.$B$B털이 북슬북슬하고 하얀 가죽옷을 입은 커다란 야수 친구죠. 워낙 눈에 띄니 찾기 쉬울 겁니다.', `FemaleText_loc4`='城门外有一个名叫达伦斯的狼人德鲁伊。他也许能帮助你。$B$B他是一头高大的猛兽，身披白色皮毛。你不可能认错他的。', `FemaleText_loc5`='在城門外有名叫做達銳斯的狼人德魯伊，他應該能幫上你的忙。$B$B去找一個全身覆滿皮毛的大傢伙，你一眼就能看出是他。', `FemaleText_loc7`='Hay un huargen druida llamado Dareth justo en el exterior de las puertas de la ciudad. Quizá pueda ayudarte.$B$BEs un tipo enorme, cubierto de cuero blanco y pelaje. Es imposible pasarlo por alto.' WHERE `ID`=51010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 아저씨는 제가 지금까지 본 나이트 엘프랑 정말 다르게 생기셨어요!', `MaleText_loc4`='喔，你和我以前见过的暗夜精灵都不一样！', `MaleText_loc5`='哇喔，你跟我以往見過的夜精靈不太一樣!', `MaleText_loc7`='Vaya, desde luego no te pareces a ningún elfo de la noche que haya visto antes.' WHERE `ID`=51011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보육원 원장님이 드루이드는 새나 표범, 곰으로 변신할 수 있다고 하셨어요. 하지만 아저씨 모습은 마치 그 동물들을 다 합쳐 놓은 것 같아요!', `MaleText_loc4`='我们的监护员说，德鲁伊能够变成鸟、豹子和熊。但你看上去像是所有这些野兽的组合！', `MaleText_loc5`='孤兒監護員說，德魯伊可以變成鳥呀，豹啊，熊呀，不過你看起來像是這些東西的綜合體!', `MaleText_loc7`='Nuestra supervisora de huérfanos dice que los druidas pueden transformarse en pájaros, gatos y osos, ¡pero tú eres como una combinación de todos ellos!' WHERE `ID`=51012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하, 무슨 생각이신지 알겠어요. 드루이드 변신을 전부 합쳐서 초 강력한 변신을 완성하시려는 거죠?!', `MaleText_loc4`='我知道你在干什么。你要结合全部德鲁伊形态，变出一个超级德鲁伊来！', `MaleText_loc5`='我知道你在幹嘛了。你要把所有德魯伊的變身模樣合而為一，成為一種超級形態!', `MaleText_loc7`='Ya veo lo que pretendes. Vas a coger todas las formas de druida y las vas a convertir en una superforma.' WHERE `ID`=51013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 에메랄드의 꿈이란 곳을 좋아할 것 같진 않네요. 제가 거북이로 변하거나 하면 어떡해요? 물론 동물이라도 좋으니 날개는 달아 보고 싶지만...', `MaleText_loc4`='听起来，翡翠梦境不像是一个适合我去的地方。如果我变成一只海龟该怎么办？我一直都想要一对翅膀，但……', `MaleText_loc5`='對我來說，翡翠夢境聽起來不並像是個地名。萬一我被變成烏龜怎麼辦?雖然我一直都想要雙翅膀...', `MaleText_loc7`='No me parece que el Sueño Esmeralda sea un lugar para mí. ¿Y si me convierte en una tortuga? Aunque siempre he querido tener alas...' WHERE `ID`=51014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와아! 난 새 인간이다!', `MaleText_loc4`='喔！我是个小鸟男孩了！', `MaleText_loc5`='呀呼!我是鳥人!', `MaleText_loc7`='¡Ueeeee! ¡Soy un niño-pájaro!' WHERE `ID`=51015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니란다, 작은 아이야. 그런 게 전혀 아니야. 나는 오랫동안 잠들어 있었지만, 그동안 내 영혼은 에메랄드의 꿈 속에서 헤맸지. 그러면서 내 몸은 우리가 동물로 변신한 형태를 닮아 가기 시작했단다.', `MaleText_loc4`='不，小家伙，不是这样的。我的灵魂在翡翠梦境中渡过了许多岁月；而我的肉体一直在沉眠之中。于是它开始呈现出我们各种动物形体的属性。', `MaleText_loc5`='不，小傢伙，並不是這樣。我的身體沉睡著，而我的靈魂則在翡翠夢境中度過了數年之久，造成的影響也開始展現在我們的動物形態上了。', `MaleText_loc7`='No, pequeño, no es nada de eso. Mi espíritu pasó muchos años en el Sueño Esmeralda mientras mi cuerpo dormía, y empezó a adoptar los atributos de nuestras formas animales.' WHERE `ID`=51016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반가워요! 나사를 조일 일이 있거나 볼트가 느슨해졌나요? 그렇다면 잘 찾아오신 거예요.', `MaleText_loc4`='你好！需要拧紧螺丝或者松开栓钉吗？你可是来对地方了。', `MaleText_loc5`='你好!要來一些栓很緊的螺絲，或是鬆脫的螺栓嗎?你來對地方了。', `MaleText_loc7`='¡Buenos días! ¿Necesitas apretar unos tornillos o soltar algunos pernos? Has venido al lugar indicado.' WHERE `ID`=51017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고프단 말이야아아아아아아아!!', `MaleText_loc4`='饿……啊！！！', `MaleText_loc5`='好好好好好餓呀!', `MaleText_loc7`='¡Haaaaaammmmbrrreeeeeee!' WHERE `ID`=51018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나아아... 미아안하다아아아...', `MaleText_loc4`='我很……难过……', `MaleText_loc5`='真真真真的很對不不不不不起...', `MaleText_loc7`='Yooooooooo sentiiiiiiir...' WHERE `ID`=51019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 우와, 우와! 스퍼터밸브가 이걸 몰게 해 주다니 믿을 수가 없어! 내가 날아보는 건 처음이라고 말은 했던가? 그래도 걱정하지 말라고. 내가 다 알아서 할 테니까 말이야.', `MaleText_loc4`='喔，喔，喔！我真不敢相信，斯布特瓦夫竟然真的允许我驾驶这个小家伙！我有没有说过，这是我的第一次飞行？别担心。一切都在我的控制之中。', `MaleText_loc5`='哇喔哇喔哇喔!我真不敢相信，斯布特瓦夫竟然會把這台寶貝交給我來駕駛!啊對了，這是我的處女航，我提過沒有?不過別擔心啦，一切都在控制之中。', `MaleText_loc7`='¡Guau, guau, guau! No puedo creer que Petardol me haya dejado conducir su preciosidad. ¿He mencionado que esta es la primera vez que vuelo? Pero no te preocupes. Lo tengo todo bajo control.' WHERE `ID`=51020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야... 저 멋진 경치 좀 보라고! 저게 사자던가? 아이고, 운전대 놓칠 뻔했네.', `MaleText_loc4`='天哪，哦，天哪……看看这惊人的景色！那些是狮子吗？哦，我差一点松开了操纵杆。', `MaleText_loc5`='喔老兄...看看這片驚人的景象!那是獅子嗎?喔抱歉，差點放開了方向盤。', `MaleText_loc7`='Oh, la leche... la leche... ¡Mira esas asombrosas vistas! ¿Eso son LEONES? Ups, casi suelto el volante.' WHERE `ID`=51021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전초 기지에 있는 친구들한테 말해주고 싶어서 죽겠군! 이 기어 진짜 끝내준다고!', `MaleText_loc4`='等基地里的那些家伙去查个清楚吧！它已经完全失控了！', `MaleText_loc5`='等到那些傢伙回家發現...情況完全失控!', `MaleText_loc7`='¡Ya verás cuando les cuente esto a los chicos en casa! ¡Esto es taaaan alucinante!' WHERE `ID`=51022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 꿈은 언젠가 스퍼터밸브만큼 똑똑해지는 거라고. 그 친구의 바퀴 두 개 달린 세발자전거 설계도를 봤어야 하는데!', `MaleText_loc4`='我的梦想是有一天成为像斯布特瓦夫那样的超级技师。你真应该看看他设计的只有两只轮子的三轮车！', `MaleText_loc5`='我的夢想就是有天能成為跟斯布特瓦夫一樣傑出的人。你應該去看看他設計的雙輪三輪車!', `MaleText_loc7`='Mi sueño es ser, algún día, tan brillante como Petardol. ¡Deberías ver su diseño para un triciclo de dos ruedas!' WHERE `ID`=51023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응? 잠깐 기다려봐. 엔진이 멈췄네...', `MaleText_loc4`='嗯？等等，发动机停转了……', `MaleText_loc5`='咦?等等，引擎拋錨了...', `MaleText_loc7`='¿Eh? Espera, el motor se ha parado...' WHERE `ID`=51024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우왓! 뭐야?', `MaleText_loc4`='喔！出了什么事？', `MaleText_loc5`='哇喔!這是怎麼回事?', `MaleText_loc7`='¡Eh! ¿Qué pasa?' WHERE `ID`=51025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야, 아니야, 아니야... 이러면 안 돼. 이건 여행 계획에 없던 거라고!', `MaleText_loc4`='不，不，不……这不可能。这不是旅行计划的一部分！', `MaleText_loc5`='不不不...不可能。這可不在旅遊計畫之中呀!', `MaleText_loc7`='No, no, no... no puede estar ocurriendo esto. ¡Esto no formaba parte del plan de viaje!' WHERE `ID`=51026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우웃! 이거 예상치 못한 곳으로 돌아가는 것 같은데! 꽉 잡으라고!', `MaleText_loc4`='啊！看样子，我们发现了一条意想不到的捷径！抓紧！', `MaleText_loc5`='嗚啊!看來我們要繞點路了，雖然這不在計畫之內!抓穩啦!', `MaleText_loc7`='¡Aaaaay! ¡Parece que vamos a tomar un desvío inesperado! ¡Agárrate!' WHERE `ID`=51027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 녹색 단추를 누르면 되나 봐. 아냐, 이 파란색 단추는 어떨까? 잠깐만 기다리라고, 이 전선 좀 다시 이어볼게. 아야!', `MaleText_loc4`='也许，如果我按下绿色按钮。不，蓝色的如何？等等，让我试着改动一些接线。哦！', `MaleText_loc5`='如果我按下綠色按鈕的話...不，按藍色那顆如何?啊等等，先讓我重新接上幾條線看看。哎唷!', `MaleText_loc7`='Quizá si pulso el botón verde. No, ¿y este azul? Espera un momento, déjame probar a reempalmar alguno cables. ¡Auch!' WHERE `ID`=51028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 안 되잖아!', `MaleText_loc4`='没有用！', `MaleText_loc5`='完全沒用!', `MaleText_loc7`='¡No funciona nada!' WHERE `ID`=51029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런. 스퍼터밸브가 날 가만두지 않을 거야! 하아... 미안하지만 여기서부터는 자네 혼자 알아서 가야 할 것 같아. 나는 파편을 주워서 돌아가야 해. 그 먼 길을 걸어서 말이야...', `MaleText_loc4`='哦，不，斯布特瓦夫一定会杀了我的！唉……剩下的路你自己走吧，我还要把火箭残骸收集好，踏上返回营地的漫漫长路……', `MaleText_loc5`='喔不，斯布特瓦夫會殺了我!唉...現在你最好自己去找架運輸工具來用。我得把碎塊收集起來，然後展開一段回到營地的漫長旅程...', `MaleText_loc7`='¡Oh, no, Petardol va a matarme! En fin... Será mejor que a partir de aquí te busques tu propio transporte. Tengo que recoger las piezas y emprender el largo camino de regreso al campamento...' WHERE `ID`=51030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 다 왔군. 십자로로 무사히 돌아왔다고.', `MaleText_loc4`='我们到了，平安返回十字路口。', `MaleText_loc5`='好啦，我們到了，一路平安地回到了十字路口。', `MaleText_loc7`='Bueno, aquí estamos, de regreso en El Cruce, sanos y salvos.' WHERE `ID`=51031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히시스의 제단 주위의 안개가 사라집니다. 베녹시스가 강력한 주문을 준비하고 있습니다!', `MaleText_loc4`='当温诺希斯开始准备一个强大的法术时，赫希斯祭坛周围的迷雾消散了。', `MaleText_loc5`='當溫諾希斯在為強大法術做準備時，環繞在西希斯祭壇周圍的霧氣消散了!', `MaleText_loc7`='¡La bruma que rodea el Altar de Hethiss se disipa mientras Venoxis prepara un poderoso hechizo!' WHERE `ID`=51032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_creature_poison_06.blp:20|t 대사제 베녹시스가 |cFFFF0000|Hspell:96637|h[맹독 촉수]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_creature_poison_06.blp:20|t高阶祭司温诺希斯开始施放|cFFFF0000|Hspell:96637|h[血毒触须]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_creature_poison_06.blp:20|t高階祭司溫諾希斯開始施展|cFFFF0000|Hspell:96637|h[血毒]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_creature_poison_06.blp:20|t ¡El sumo sacerdote Venoxis empieza a lanzar |cFFFF0000|Hspell:96637|h[Ponzoña Sanguinaria]|h|r!' WHERE `ID`=51033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사제 베녹시스가 탈진했습니다!', `MaleText_loc4`='高阶祭司温诺希斯疲惫了！', `MaleText_loc5`='高階祭司溫諾希斯耗盡了所有精力!', `MaleText_loc7`='¡El sumo sacerdote Venoxis está agotado!' WHERE `ID`=51034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈출 수가 없어. 이제 불시착할 거야!', `MaleText_loc4`='我没法让它停下来。我们要坠毁了！', `MaleText_loc5`='停不下來。我們即將迫降!', `MaleText_loc7`='No puedo pararlo. ¡Preparados para un aterrizaje de emergencia!' WHERE `ID`=51035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체를 조사합니다.', `MaleText_loc4`='调查这具尸体。', `MaleText_loc5`='檢查屍體。', `MaleText_loc7`='Examina el cuerpo.', `FemaleText_loc1`='시체를 조사합니다.', `FemaleText_loc4`='调查这具尸体。', `FemaleText_loc5`='檢查屍體。', `FemaleText_loc7`='Examina el cuerpo.' WHERE `ID`=51036;
