UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아, 난 예전에도 불의 정령들과 한 판 했었다고. 그래서 이놈들 문제라면 내가 전문가라고 해도 된다니까.', `MaleText_loc4`='要知道，我研究火元素已经有一段时间了。我想，在这方面我应该是个专家。', `MaleText_loc5`='我熟知火元素的歷史，你知道的。我想在這個話題上我可以算是某種專家。', `MaleText_loc7`='La verdad es que lo mío con los elementales de fuego viene de antiguo, ¿sabes? Me considero una especie de experto en el tema.' WHERE `ID`=51089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아! 이 친구들 진짜 화끈한데!', `MaleText_loc4`='没错！这些家伙真的很热！', `MaleText_loc5`='喔耶!這些傢伙實在是太火辣了!', `MaleText_loc7`='¡Vaaaya! ¡Esos tipos sí que están calientes!' WHERE `ID`=51090;
