UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 혐오스러운 것들 때문에 다람쥐가 수도 없이 죽었습니다! 그러니 자비 따위는 필요 없습니다!', `MaleText_loc4`='这些憎恶造成了几十只松鼠的死亡！它们不应得到任何怜悯！', `MaleText_loc5`='這些憎惡體要為了大批松鼠的死亡負責!不需要手下留情!', `MaleText_loc7`='¡Esas abominaciones son las culpables de la muerte de docenas de ardillas! ¡No merecen piedad!' WHERE `ID`=51136;
