UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 자네가 아제로스라고 부르는 세계의 친구일세. 내가 도와줄 수 있어서 정말 기쁘군.', `MaleText_loc4`='这个被你称为艾泽拉斯的世界是我们的朋友。很高兴能尽我所能为你提供帮助。', `MaleText_loc5`='我們是艾澤拉斯之友。我很樂意盡我可能提供協助。', `MaleText_loc7`='Nosotros ser amigos del mundo que tú llamar Azeroth. Yo estar contento de poder ayudar en lo que yo poder.' WHERE `ID`=51141;
