UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아시겠지만, 여기는 제 전문이 아닙니다. 그래도 도와드릴 수 있어 기쁩니다.', `MaleText_loc4`='这并不是我擅长的领域，不过很高兴能帮忙。', `MaleText_loc5`='我說呀，我其實不怎麼喜歡這樣子的，但能幫上忙也就罷了。', `MaleText_loc7`='Sabes, realmente esto no es lo mío. Pero estoy encantado de ayudar.' WHERE `ID`=51143;
