UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈에게 줄 선물이 있다! 내 총구에서 나올 테니 기다려...', `MaleText_loc4`='我为你准备了一个礼物！来吧，我这就把它从我的枪膛里掏出来……', `MaleText_loc5`='我帶了禮物送你!好，等我從槍裡拿出來...', `MaleText_loc7`='¡Tengo un regalito para ti! Toma, espera que lo saque de mi arma...' WHERE `ID`=51157;
