UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불에는 불로 싸울 때로군요! 그리고 서리로! 그리고 어둠으로!', `MaleText_loc4`='这是烈火对烈火的时刻！还有寒冰！还有暗影！', `MaleText_loc5`='以火制火的時間到了!還有冰霜!另外暗影也是!', `MaleText_loc7`='¡Es el momento de combatir el fuego con el fuego! ¡Y con escarcha! ¡Y con sombras!' WHERE `ID`=51159;
