UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 이놈을 완전히 박살 낸 것 같군요.', `MaleText_loc4`='我想，我已经把这家伙打得不省人事了。', `MaleText_loc5`='我想我應該把他打得抱頭鼠竄了。', `MaleText_loc7`='Creo que he dejado a ese para el arrastre.' WHERE `ID`=51161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란에서 먼 길을 떠나왔는데, 이런 식으로 환영 인사를 해준단 말이군?', `MaleText_loc4`='我从达拉然一路来到这里，这就是我得到的欢迎吗？', `MaleText_loc5`='我爬山涉水來到達拉然，是這樣歡迎我的?', `MaleText_loc7`='Vengo desde Dalaran, ¿y esta es la única bienvenida que recibo?' WHERE `ID`=51162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지도 의회에서 네놈을 추방하라는 명령을 받았다. 나는 그 명령을 끝까지 지킬 테다.', `MaleText_loc4`='议会已经宣布驱逐你，而我则要执行议会的命令。', `MaleText_loc5`='當權議會決定放逐你。我打算完成這項命令。', `MaleText_loc7`='El consejo gobernante ha ordenado tu desaparición. Y yo tengo previsto hacer cumplir esa orden.' WHERE `ID`=51163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직도 이곳 하이잘에서 싸우고 있다니 믿을 수가 없네요. 이 싸움이 끝난 후에 무슨 일이 생길지 봐야 해요.', `FemaleText_loc4`='难以相信，你们还在海加尔奋战。你应该明白随后将要发生什么。', `FemaleText_loc5`='我真不敢相信你們還在海加爾戰鬥。你們應該要知道在這之後發生了什麼事。', `FemaleText_loc7`='No puedo creer que todavía estéis luchando aquí, en Hyjal. Deberíais ver lo que ocurre después de esto.' WHERE `ID`=51164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 몇 시인지 알아? 그래 바로 죽을 때야!', `FemaleText_loc4`='你知道现在是什么时刻？没错，现在是死亡的时刻！', `FemaleText_loc5`='你知道現在幾點了嗎?沒錯，現在正是「死」點!', `FemaleText_loc7`='¿Sabes qué hora es? Sí, así es, ¡la hora de MORIR!' WHERE `ID`=51165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크로미한테 한 방 먹은 거야!', `FemaleText_loc4`='让克罗米来教训你！', `FemaleText_loc5`='你剛變成了克羅米!', `FemaleText_loc7`='¡Cromi acaba de machacarte!' WHERE `ID`=51166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울부짖는 포로의 소리보다 더 내가 즐기는 건 정말 없다네. 특히나 내 포로라면 말이야.', `MaleText_loc4`='没什么能比濒死者的尖叫声更让我喜欢，特别是当他们死在我手中的时候。', `MaleText_loc5`='沒有什麼比受害者的尖叫聲更能讓我開心的了，特別是那些落入我手中的傢伙。', `MaleText_loc7`='La verdad es que no hay nada que disfrute más que el sonido de víctimas gritando. Sobre todo si son MIS víctimas.' WHERE `ID`=51168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 생명체에 있어서 가장 최악인 게 뭔지 아나? 거두어들일 수 있는 조직이 없다는 거야.', `MaleText_loc4`='你知道这些火焰怪物最糟糕的地方是什么？没有任何可供收集的器官。', `MaleText_loc5`='你知道那些火焰生物最慘的地方是什麼嗎?那就是沒有器官可供撿拾。', `MaleText_loc7`='¿Sabes qué es lo peor de las criaturas de fuego? Que no hay órganos que puedas recoger.' WHERE `ID`=51169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불과 돌은 별로 쓸데가 없는데... 난 살로 이루어진 걸 더 좋아한다고!', `MaleText_loc4`='火焰和岩石对我来说没有任何意义，我更喜欢有血有肉的敌人。', `MaleText_loc5`='火焰和岩塊無法傷我分毫。我已經是超越肉身之人。', `MaleText_loc7`='En realidad, el fuego y las rocas no me dicen nada. Soy más un hombre de carne.' WHERE `ID`=51170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 알아? 네놈을 보니 내가 만들던 이동식 모닥불 원형이 생각난다고.', `MaleText_loc4`='你知道吗？你让我想起了我曾经制造过的步行篝火原型机。', `MaleText_loc5`='你知道嗎?你讓我想起以前研究的步行營火初號機。', `MaleText_loc7`='¿Sabes qué? Me recuerdas al prototipo de fogata móvil en el que he estado trabajando.' WHERE `ID`=51171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 이중이진 소형흐름측정 자동렌치를 피할 수 있다면, 피구공도 피할 수 있을 거라고!', `MaleText_loc4`='如果你能躲开双二进制流变振波自动扳手，你就能躲开炮弹！', `MaleText_loc5`='如果你有辦法閃過雙元變換波動自動扳手，那你一定能躲過一顆球!', `MaleText_loc7`='Si puedes esquivar una llave inglesa fluxcilométrica doble binaria ¡puedes esquivar un balón!' WHERE `ID`=51172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 천재라고!', `MaleText_loc4`='我是天才！', `MaleText_loc5`='我真是個天才!', `MaleText_loc7`='¡Soy un genio!' WHERE `ID`=51173;
