UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들도 이 소식을 들을 겁니다!', `MaleText_loc4`='大家都会知道这件事的！', `MaleText_loc5`='先讓大夥兒聽聽看!', `MaleText_loc7`='¡Ya verás cuando los chicos se enteren de esto!' WHERE `ID`=51177;
