UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 일하러 가야겠군. 난 바쁜 고블린이라고!', `MaleText_loc4`='快回来为我工作。我是个忙碌的地精！', `MaleText_loc5`='我要回去工作了。我可是很忙的!', `MaleText_loc7`='Me toca volver al trabajo. ¡Soy un goblin muy ocupado!' WHERE `ID`=51179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠나는 제 모습을 바라보는 게 슬플 수도 있지만, 곧 즐거운 표정으로 바라보게 될 것입니다.', `MaleText_loc4`='虽然我的离开可能会让你难过，不过我相信，你会带着笑容眺望我的背影。', `MaleText_loc5`='雖然看著我離去你可能會感到難過，不過我會讓你開開心心地看著我走。', `MaleText_loc7`='Aunque sé que puede que estés triste por verme partir, estoy seguro de que disfrutarás viendo cómo me voy.' WHERE `ID`=51180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, 아주 잘하셨어요! 또 찔러 버릴 일 있으면 제게 알려주세요.', `FemaleText_loc4`='嗨，和你在一起可真痛快！如果你还有敌人，一定要让我知道。', `FemaleText_loc5`='嘿，表演得真好!如果還有什麼東西需要捅上幾刀的話，記得跟我說。', `FemaleText_loc7`='¡Eh, ha sido un gran espectáculo! Avísame si necesitas acuchillar algo más.' WHERE `ID`=51181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 이곳에서 해낸 일에 은빛십자군이 감사하고 있습니다, $n 님.', `MaleText_loc4`='北伐军感谢你在这里所做的一切，$n。', `MaleText_loc5`='十字軍為你在這所做的表示感謝，$n。', `MaleText_loc7`='La Cruzada agradece el trabajo que estás haciendo, $n.' WHERE `ID`=51182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스의 수하들에게 맞설 기회를 주셔서 감사했습니다.', `MaleText_loc4`='感谢你让我有机会同拉格纳罗斯一战。', `MaleText_loc5`='感謝你給我機會把東西帶去拉格納羅斯那裡。', `MaleText_loc7`='Gracias por la oportunidad de enfrentarme a Ragnaros.' WHERE `ID`=51183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 끔찍한 시련 속에서도 진정한 용기와 기사도를 보여주셨습니다. 또 다른 영웅의 표상인 당신에게 경의를 표합니다!', `MaleText_loc4`='在恐怖的灾难之前，你显示了真正的勇气与骑士精神。作为一个英雄主义的楷模，我向另一个同样的楷模敬礼！', `MaleText_loc5`='你在這可怕的逆境之中，顯現出真正的勇氣與騎士風範。這種英勇氣概可作為其他人的典範:我要向你致敬!', `MaleText_loc7`='Al enfrentarte a la terrible adversidad has demostrado valor y caballerosidad verdaderos. De un brillante adalid del heroísmo a otro: ¡Yo te saludo!' WHERE `ID`=51184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠어요. 그럼 안녕히, 영웅님.', `MaleText_loc4`='打得好。再见，英雄。', `MaleText_loc5`='打得漂亮。再會了，英雄。', `MaleText_loc7`='Has luchado bien. Adiós, héroe.' WHERE `ID`=51185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 만날 때까지 안녕히! 살아 있어야 합니다!', `MaleText_loc4`='下次再见！一定要活着啊！', `MaleText_loc5`='到下次見面前，設法保住你自己的小命吧!', `MaleText_loc7`='¡Hasta la próxima! ¡Intenta seguir con vida!' WHERE `ID`=51186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠소, 영웅이여. 다시 함께 싸울 날을 고대하겠소.', `MaleText_loc4`='你战斗得非常英勇，英雄。期待能再次与你并肩作战。', `MaleText_loc5`='打得不錯，英雄。我很期待和你再次並肩作戰。', `MaleText_loc7`='Has luchado bien, héroe. Espero ansioso la oportunidad de luchar a tu lado de nuevo.' WHERE `ID`=51187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 여왕께서 자네를 지켜보고 계시네.', `MaleText_loc4`='黑暗女王在注视着你。', `MaleText_loc5`='願黑暗女王眷顧你。', `MaleText_loc7`='La Dama Oscura te vigila.' WHERE `ID`=51188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역병지대로 돌아가겠습니다!', `MaleText_loc4`='返回瘟疫之地！', `MaleText_loc5`='滾回瘟疫之地去!', `MaleText_loc7`='¡De regreso a las tierras de la peste!' WHERE `ID`=51189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='굳건히 맞서세요, 투사들이여.', `FemaleText_loc4`='战士们，拿出勇气来。', `FemaleText_loc5`='昂首而立，戰士們。', `FemaleText_loc7`='Sed fuertes, combatientes.' WHERE `ID`=51190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 필요하다면 심원의 영지에 있는 동지들을 항상 기억하게나.', `FemaleText_loc4`='请记住，你在深岩之洲有朋友。如果有需要，就请来找我们。', `FemaleText_loc5`='不要忘記，當你需要我們的時候，盟友就在地深之源。', `FemaleText_loc7`='Debes saber que siempre tendrás aliados en Infralar, si alguna vez nos necesitas.' WHERE `ID`=51191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제 연구실로 돌아가야겠습니다.', `MaleText_loc4`='这样，我就能回到我的研究中去了。', `MaleText_loc5`='只要有那玩意兒，我就能繼續進行研究。', `MaleText_loc7`='Y con esto, debo regresar a mi investigación.' WHERE `ID`=51192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 오그릴라로 돌아가야겠네. 우리가 자네를 잊지 않는 것처럼 자네도 우리를 잊지 않길 바라네.', `MaleText_loc4`='我该回奥格瑞拉去了。希望你不要忘记我们，就像我们永远不会忘记你。', `MaleText_loc5`='該是我回歐格利拉的時候了。希望你不會忘記我們，就像我們永遠不會忘記你一樣。', `MaleText_loc7`='Ya ser hora que yo regresar a Ogri''la. Esperar que tú no olvidar a nosotros, así como nosotros no haber olvidado a ti.' WHERE `ID`=51193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕히 가십시오. 전투를 치르게 해주셔서 고맙습니다!', `MaleText_loc4`='再见，感谢你的英勇奋战！', `MaleText_loc5`='再會，同時為了這幾場仗表達謝意!', `MaleText_loc7`='¡Hasta más ver! ¡Y gracias por las peleas!' WHERE `ID`=51194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리 생각으론 너 너무 나쁜 친구 너무 많이 죽였다. 하지만 돌머리 생각으론 너 그래도 괜찮은 친구야.', `MaleText_loc4`='隆克觉得你杀掉了太多坏家伙，但隆克依然觉得你是个好$g家伙:女孩;。', `MaleText_loc5`='郎克覺得你殺了太多太多壞傢伙。不過郎克還是認為你是好$g先生:小姐;。', `MaleText_loc7`='Ñoño creer que tú matar demasiado al tipo malo. Pero Ñoño creer también que tú ser $gun tipo:una señora; guay.' WHERE `ID`=51195;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기회를 주셔서 감사합니다. 당신의 배려를 볼진 님께 알려드려야겠군요.', `FemaleText_loc4`='感谢你让我有机会痛快杀敌。我会向沃金报告你的功绩。', `FemaleText_loc5`='感謝你給我這個機會。我會代你向沃金傳達問候。', `FemaleText_loc7`='Gracias por eh''ta opoh''tunidad. Iré inmediatamente a informar a Vol''jin y le trasmitiré tus saludos.' WHERE `ID`=51196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하이잘을 수호하는 투쟁을 절대 멈추지 않겠습니다. 우리 모두 힘을 합쳐 하이잘을 재건하기 전에는 말입니다.', `FemaleText_loc4`='在彻底治愈海加尔山以前，我绝不会停止奋战。', `FemaleText_loc5`='在付出那麼多心力治療她之後，我不可能停止奮戰。我會更加盡力保護海加爾。', `FemaleText_loc7`='Nunca dejaré de luchar para proteger Hyjal. Menos aún después de todo lo que hemos hecho para sanarla.' WHERE `ID`=51197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저만큼이나 당신도 즐거운 시간이었기를 바라요.', `MaleText_loc4`='希望你能像我一样得到许多乐趣。', `MaleText_loc5`='希望你玩得和我一樣開心。', `MaleText_loc7`='Espero que te hayas divertido tanto como yo.' WHERE `ID`=51198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀한 시간만 낭비했군.', `MaleText_loc4`='这是在浪费我的时间。', `MaleText_loc5`='那不值得我花時間在上面。', `MaleText_loc7`='No ha merecido la pena perder mi tiempo en esto.' WHERE `ID`=51199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만날 때까지 이만... 언제든지 저를 만나러 오십시오.', `MaleText_loc4`='再见……你知道哪里可以找到我。', `MaleText_loc5`='下次見...你知道可以在哪找到我。', `MaleText_loc7`='Hasta que nos volvamos a ver... ya sabes dónde encontrarme.' WHERE `ID`=51200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에 만나요!', `FemaleText_loc4`='后会有期！', `FemaleText_loc5`='下次再會!', `FemaleText_loc7`='¡Nos vemos!' WHERE `ID`=51201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 가야겠군. 이놈들을 없애다 보니 서로 이어붙이지 못한 새로운 시체들이 좀 있다는 게 생각나서 말이지.', `MaleText_loc4`='我必须走了。这些杀戮让我想起来还有很多尸体没缝好。', `MaleText_loc5`='我真的該走了。這次的事情提醒了我，手上還有一些新鮮屍體要縫合在一起。', `MaleText_loc7`='Debería ponerme en marcha. Toda esta muerte me ha recordado que todavía me quedan unos cadáveres frescos que no he cosido a otros cuerpos.' WHERE `ID`=51202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 끝났군! 실험실로 돌아가야지!', `MaleText_loc4`='成功完成！返回实验室！', `MaleText_loc5`='東西到手了!退回實驗室!', `MaleText_loc7`='¡Pues ya está! ¡De vuelta al laboratorio!' WHERE `ID`=51203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노는 사그라들지 않았네... 하지만 잠잠해지고는 있지. 당분간은 말이야.', `MaleText_loc4`='我的怒火并未平息……只是我的心情暂时平静了一些。', `MaleText_loc5`='我心中的怒火並不沈寂...只是沒那麼猛烈而已。至少現在是這樣子。', `MaleText_loc7`='Mi ira no se ha apagado... pero sí se ha calmado. Por ahora.' WHERE `ID`=51204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나세요!', `MaleText_loc4`='撤退！', `MaleText_loc5`='退後!', `MaleText_loc7`='¡Atrás!' WHERE `ID`=51205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 공격을 중지하십시오!!', `MaleText_loc4`='大家暂停攻击！', `MaleText_loc5`='老兄，快撤銷你的攻擊命令!', `MaleText_loc7`='¡Ignoren sus órdenes de atacar, muchachos!' WHERE `ID`=51206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 멈추십시오, 영웅이여. 놈의 몸뚱이가 불꽃으로 빨갛게 빛나고 있습니다.', `MaleText_loc4`='停手，英雄们。这头龙的鳞正在闪耀鲜红的火光。', `MaleText_loc5`='英雄們，別衝動。這條龍的龍鱗開始起火發紅了。', `MaleText_loc7`='Guarden sus espadas, héroes. Estas escamas de dragón resplandecen de rojo por las llamas.' WHERE `ID`=51207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 공격을 멈추세요!', `MaleText_loc4`='所有人，停止攻击！', `MaleText_loc5`='大家快停手!', `MaleText_loc7`='¡Escuchen todos! ¡Detengan sus ataques!' WHERE `ID`=51208;
