UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 멈추시오!', `MaleText_loc4`='收起武器！', `MaleText_loc5`='停手!', `MaleText_loc7`='¡Detengan sus armas!' WHERE `ID`=51210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 방어막을 펼칠 때는 공격을 멈추게!', `MaleText_loc4`='当护盾升起来的时候停止攻击！', `MaleText_loc5`='護盾升起時別攻擊!', `MaleText_loc7`='¡Detengan sus ataques mientras el escudo esté activo!' WHERE `ID`=51211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 멈추게! 안 그러면 피해를 볼걸세!', `MaleText_loc4`='停止攻击！它的护盾将会粉碎你们。', `MaleText_loc5`='停止攻擊!不然那道護盾會擊垮你的。', `MaleText_loc7`='¡Detengan sus ataques! Su escudo podrá con ustedes.' WHERE `ID`=51212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왔습니다!', `MaleText_loc4`='我，在这里！', `MaleText_loc5`='我在這!', `MaleText_loc7`='¡ESTOY aquí!' WHERE `ID`=51213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코도가 매일 자기 몸무게만큼의 곡식을 먹어치운다는 건 몰랐을 것이오. 물론 그래서 주둥이 반대편으로 나오는 양도 장난이 아니라오.', `MaleText_loc4`='你也许还不知道，科多兽每天可以吃下相当于自身体重的草食。所以，每天从它们的另一头排出的东西也需要打扫很久。', `MaleText_loc5`='我賭你不知道科多獸每天吃下的草就跟牠的體重一樣重。當這些草從另一頭出來的時候可有得清了。', `MaleText_loc7`='Apuesto a que no sabías que un kodo puede comer su peso en hierba cada día. Claro que cuando sale por el otro lado, hay mucho trabajo que hacer con la pala.' WHERE `ID`=51214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 각지의 수제 장난감 팔아요!', `MaleText_loc4`='来自艾泽拉斯各地的手工玩具！', `MaleText_loc5`='這可是來自艾澤拉斯世界各地的手工玩具唷!', `MaleText_loc7`='¡Juguetes hechos a mano de todo Azeroth!' WHERE `ID`=51215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 말하는 지금 이 순간에도 불타는 칼날단 놈들이 울부짖는 소리를 들을 수 있어요. 코도는 몰샨의 망루로 갈 준비가 다 되었으니 당신도 준비되면 말씀해 주세요.', `FemaleText_loc4`='我可以听见火刃氏族的战吼，科多兽已经准备好，随时可以前往莫尔杉农场。当你准备好出发的时候就告诉我。', `FemaleText_loc5`='在我們交談的同時，我可以聽見燃刃氏族的吼叫聲。要前往莫爾杉壁壘的科多獸已經準備好，當你準備好要動身的時候就跟我說吧。', `FemaleText_loc7`='Mientras hablamos, puedo oír el aullido del Filo Ardiente. Los kodos están listos para salir hacia La Empalizada de Mor''shan. Avísame cuando quieras partir.' WHERE `ID`=51216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 중지! 보호막이 없어지거든 공격하게!', `MaleText_loc4`='当护盾升起来的时候不要攻击！', `MaleText_loc5`='別在護盾升起時發動攻擊!', `MaleText_loc7`='¡No ataques mientras el escudo esté activado!' WHERE `ID`=51217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 안 됩니다, 필멸자여.$b$b제가 여기 온 건 급한 용무 때문입니다.', `FemaleText_loc4`='现在不行，凡人。$b$b我到此地有重要的事要做。', `FemaleText_loc5`='現在還不是時候，凡人。$b$b我來此是為了要緊的事情。', `FemaleText_loc7`='Ahora no, mortal.$b$bTengo un asunto urgente entre manos.' WHERE `ID`=51218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디, 이 생물의 어디가 잘못된 건지 볼까요?', `MaleText_loc4`='让我们瞧瞧这家伙怎么了？', `MaleText_loc5`='咱們來看看這隻生物到底是怎麼一回事?', `MaleText_loc7`='Veamos qué le pasa a eh''ta criatura.', `FemaleText_loc1`='어디, 이 생물의 어디가 잘못된 건지 볼까요?', `FemaleText_loc4`='让我们瞧瞧这家伙怎么了？', `FemaleText_loc5`='咱們來看看這隻生物到底是怎麼一回事?', `FemaleText_loc7`='Veamos qué le pasa a eh''ta criatura.' WHERE `ID`=51219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='히시스 님의 귓속말이 네 마음에 독을 불어넣을 거다!', `FemaleText_loc4`='赫希斯之耳语即将毒害你的心灵！', `FemaleText_loc5`='西希斯的呢喃會毒化你的心智!', `FemaleText_loc7`='¡Los susurros de Hethiss te envenenarán la mente!' WHERE `ID`=51220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피를 독으로 바꿔주지!', `MaleText_loc4`='我要把你的血变成剧毒！', `MaleText_loc5`='我會把你的血液全都化為毒液!', `MaleText_loc7`='¡Voy a conveh''tir tu sangre en veneno!' WHERE `ID`=51221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='킬나라가 미친 듯이 웃습니다.', `FemaleText_loc4`='基尔娜拉疯狂地笑了起来。', `FemaleText_loc5`='基爾娜拉瘋狂地笑起來。', `FemaleText_loc7`='Kilnara ríe como una loca.' WHERE `ID`=51222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 표범... 내 표범을 죽였어! 왜 날 괴롭히는 거지?', `FemaleText_loc4`='你——你杀了我的猎豹！为什么我要遭这种罪？', `FemaleText_loc5`='你殺了─殺了我的豹!為什麼要我受這種苦?', `FemaleText_loc7`='Mataste... ¡Mataste a mi gato! ¿Por qué debo sufrir tanto?' WHERE `ID`=51223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가시덤불은 구루바시의 것. 묻어 버리기 전에 이곳을 떠나라.', `FemaleText_loc4`='荆棘谷属于古拉巴什。赶快离开，否则就埋了你。', `FemaleText_loc5`='荊棘谷是屬於古拉巴什的。你們最好在被我們埋起來前離開。', `FemaleText_loc7`='Tuercespina pertenece a los Gurubashi. Será mejor que te vayas antes de que te enterremos aquí.' WHERE `ID`=51224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정 남겠다면 좋다. 제물은 많을수록 좋으니까.', `FemaleText_loc4`='想留下也可以。我们的祭品总是不够用。', `FemaleText_loc5`='想留下也可以。我們一直都很缺祭品。', `FemaleText_loc7`='O quédate si quieres. Siempre nos hacen falta sacrificios.' WHERE `ID`=51225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험을 무릅쓰고 우리가 해냈소! 그런 사격술은 예전에... 그러니까 예전에 본 적이 없다오! 당신과 또 짐마차를 타고 싶지만, 카드라크가 더 중요한 일을 줄 것이오. 무사히 데려다 줘서 고맙소, 친구.', `MaleText_loc4`='刚才真是死里逃生，但我们成功做到了！我从来没有这样射击过……从来没有！我希望我们可以有机会再次一同骑乘，但卡德拉克有更重要的任务交给你。谢谢你把我们安全送达目的地，我的朋友。', `MaleText_loc5`='千鈞一髮!我們成功了!我沒看過有人能完成那種程度的動作...喔好吧，是從來沒有過!真希望我們能再來一次，不過卡德拉克手上有更重要的工作要交給你。朋友，謝謝你平安送我們一程。', `MaleText_loc7`='¡Por las barbas de mi madre, lo hemos conseguido! No he visto a nadie disparar así desde... bueno... nunca! Ojalá pudiéramos viajar juntos de nuevo, pero Kadrak tiene reservado trabajo más importante para ti. Gracias por traernos sanos y salvos, camarada.' WHERE `ID`=51226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 오랜 친구여. 우리 전사들도 고마워하고 있다네.', `MaleText_loc4`='谢谢你，老朋友。我们的勇士感谢你。', `MaleText_loc5`='謝啦，老友。我們的戰士會感謝你的。', `MaleText_loc7`='Gracias, camarada. Nuestros guerreros te están agradecidos.' WHERE `ID`=51227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑소, 친구여. 길이 안전할 때 어서 타시오.', `MaleText_loc4`='很高兴再次见到你，朋友。趁道路仍然畅通，赶紧上来吧。', `MaleText_loc5`='很高興再見到你，朋友。趁著路上還安全的時候，加快腳步趕緊上路吧。', `MaleText_loc7`='Me alegro de verte, camarada. Date prisa y sube mientras el camino esté despejado.' WHERE `ID`=51228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 똑바로 차리시오! 놈들이 우리 뒤에 바싹 따라붙고 있소!', `MaleText_loc4`='保持警惕！他们从后方包抄过来了！', `MaleText_loc5`='提高警覺!他們快要追上來了!', `MaleText_loc7`='¡Ojo avizor! ¡Nos están pisando los talones!' WHERE `ID`=51229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위를 조심하시오! 로켓을 사용해야 하오!', `MaleText_loc4`='小心上空！使用你的火箭！', `MaleText_loc5`='注意我們頭上!使用手中的火箭!', `MaleText_loc7`='¡Vigila por encima de nuestras cabezas! ¡Usa tu cohete!' WHERE `ID`=51230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 사방에서 몰려들고 있소! 거의 다 왔으니 조금만 더 버텨 주시오!', `MaleText_loc4`='他们从四面八方涌来了！再坚持一下，我们快到了！', `MaleText_loc5`='他們從四面八方湧上來!再堅持一下就好，我們要到了!', `MaleText_loc7`='¡Vienen desde todos los lados! ¡Aguanta un poco más, casi hemos llegado!' WHERE `ID`=51231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈렌게스가 말로른의 사슴뿔 때문에 약해졌습니다! 지금 공격하십시오!', `MaleText_loc4`='盖伦格斯遭到了玛洛恩鹿角的削弱！赶快攻击他！', `MaleText_loc5`='瑪洛尼的鹿角弱化了加倫具斯!快發動攻擊!', `MaleText_loc7`='¡La cornamenta de Malorne ha debilitado a Galenges! ¡Ataca ahora!' WHERE `ID`=51232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 쐈소! 저놈은 바로 일어나지는 못할 것이오.', `MaleText_loc4`='打得不错！那家伙短时间内是起不来了。', `MaleText_loc5`='射得好!那傢伙可要很久才爬得起來。', `MaleText_loc7`='¡Buen disparo! Ese no volverá a levantarse en breve.' WHERE `ID`=51233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기분 나쁘게 생각하지 마십시오, $r|1이여;여;.$b$b단지 꾸물거릴 시간이 없기 때문이니까.', `FemaleText_loc4`='不要生气，$r。$b$B我只是没时间分心而已。', `FemaleText_loc5`='恕我失禮，$r。$b$b我現在沒時間分心。', `FemaleText_loc7`='No te ofendas, $r.$b$bSimplemente no tengo tiempo para distracciones.' WHERE `ID`=51234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신경 써드리지 못해 죄송합니다, $c님.$b$b아주 중대한 일을 먼저 보느라 눈코 뜰 새가 없군요.', `FemaleText_loc4`='原谅我的无礼，$c。$b$b我必须全神贯注于紧迫的事情。', `FemaleText_loc5`='恕我失禮了，$c。$b$b如此急迫的重大問題讓我無法分心。', `FemaleText_loc7`='Disculpa mi brusquedad, $c.$b$bAsuntos apremiantes de vital importante requieren mi total atención.' WHERE `ID`=51235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 이게 무슨 일이지?!', `MaleText_loc4`='啊啊！这是什么意思？！', `MaleText_loc5`='啊!這有意義嗎!?', `MaleText_loc7`='¡Ahh! ¡¿Qué significa esto?!' WHERE `ID`=51236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 애쓰는구나... 하지만 쓰러지지 않는 자, 갈렌게스를 이기려면 허약한 수사슴 따위의 도움으론 부족할 것이다!', `MaleText_loc4`='你们的努力值得赞赏……但光凭你们这些小东西是打不倒盖伦格斯的！我是刀枪不入的！', `MaleText_loc5`='多麼高貴的行為...不過只單憑你這弱小雄鹿的幫助是無法擊倒堅不可摧的...加倫具斯!', `MaleText_loc7`='Un esfuerzo muy noble... ¡pero harán falta más de uno de tus débiles venados para acabar con Galenges, el Indomable!' WHERE `ID`=51237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 거기 계셨군요, $n 님.$b$b지금 당장 대화할 것이 있습니다.', `FemaleText_loc4`='啊！是你啊，$n。$b$B我必须马上和你谈谈。', `FemaleText_loc5`='啊!你在這呀，$n。$b$b我必須馬上和你談點事情。', `FemaleText_loc7`='¡Ahh! Ahí estás, $n.$b$bDebo hablar contigo inmediatamente.' WHERE `ID`=51238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 절대로 날 이길 수 없다!', `MaleText_loc4`='在我面前你们毫无机会！', `MaleText_loc5`='你沒機會反抗我的!', `MaleText_loc7`='¡No tienes ninguna oportunidad contra mí!' WHERE `ID`=51239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 이 갈렌게스에게 도전하느냐? 나약한 놈, 앞으로 나와라!', `MaleText_loc4`='你们谁敢上前挑战盖伦格斯？上前来吧，懦夫！', `MaleText_loc5`='誰膽敢挑戰加倫具斯?站出來，弱者!', `MaleText_loc7`='¿Quién se atreve a desafiar a Galenges? ¡Da un paso al frente, alfeñique!' WHERE `ID`=51240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 구루바시, 이 땅을 되찾는다.', `MaleText_loc4`='古拉巴什将夺回我们的土地。', `MaleText_loc5`='古拉巴什會奪回我們的土地。', `MaleText_loc7`='Los Gurubashi recuperaremos nuestra tierra.' WHERE `ID`=51241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 너무 오래 설쳐댔다.', `MaleText_loc4`='我们让你待得太久了。', `MaleText_loc5`='我們忍受你夠久了。', `MaleText_loc7`='Ya te has quedado demasiado tiempo.' WHERE `ID`=51242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 너희 강한 줄 안다. 용감한 줄 안다. 살아남을 줄 안다.', `MaleText_loc4`='你自以为强大。你自以为勇敢。你自以为能活下来。', `MaleText_loc5`='你以為你很強，以為你勇敢，以為你可以活下來。', `MaleText_loc7`='Te crees fuerte. Te crees valiente. Crees que puedes sobrevivir.' WHERE `ID`=51243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우린 알지...', `MaleText_loc4`='但我们知道……', `MaleText_loc5`='但我們知道...', `MaleText_loc7`='Pero nosotros sabemos...' WHERE `ID`=51244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희와 너희 동족들, 죽은 거나 다름없다.', `MaleText_loc4`='你和你的族类，你们都要死了。', `MaleText_loc5`='你和你的同伴，你們全都已經死了。', `MaleText_loc7`='Que tú y tu gente, ya están muertos.' WHERE `ID`=51245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 죽고 나면, 구루바시의 노예가 되는 거야.', `MaleText_loc4`='你们死后都要服侍古拉巴什。', `MaleText_loc5`='而等你們一死，就是古拉巴什的僕人。', `MaleText_loc7`='Y una vez muertos, servirán a los Gurubashi.' WHERE `ID`=51246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 벌레들을 해치워라!', `MaleText_loc4`='杀掉这些虫子！', `MaleText_loc5`='殺死這些蟲子!', `MaleText_loc7`='¡Maten a esos gusanos!' WHERE `ID`=51247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냉기 돌풍에 오신 걸 환영해요! 어디에서도 찾아볼 수 없는 독특한 아이스크림을 맛보세요! 스톰윈드 최고의 수습 마법사들이 주문받은 바로 그 자리에서 얼려 드립니다!', `MaleText_loc4`='欢迎来到冰锥甜筒，朋友！我们的冰激凌味道独一无二，冰寒爽口，是暴风城最优秀的法师学徒特别定制的！', `MaleText_loc5`='歡迎光臨冰錐冰淇淋，朋友!我們獨特的冰淇淋可是由暴風城技藝最精湛的法師學徒所冰製而成!', `MaleText_loc7`='¡Bienvenido al Cono de frío, colega! ¡Nuestro exclusivo helado ha sido enfriado por uno de los aprendices de mago más prometedores de Ventormenta!' WHERE `ID`=51248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_eye_04.blp:20|t%s|1이;가; |cFFFF0000|Hspell:96920|h[오쿠타르의 눈]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_eye_04.blp:20|t%s开始施放|cFFFF0000|Hspell:96920|h[欧库塔尔之眼]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_eye_04.blp:20|t%s開始施放|cFFFF0000|Hspell:96920|h[歐庫薩之眼]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_eye_04.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:96920|h[Ojos de Occu''thar]|h|r!' WHERE `ID`=51249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 발사 3초 전...', `MaleText_loc4`='火箭将在3秒内发射……', `MaleText_loc5`='3...', `MaleText_loc7`='Lanzamiento de cohete en 3...' WHERE `ID`=51250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 발사 2초 전...', `MaleText_loc4`='火箭将在2秒内发射……', `MaleText_loc5`='2...', `MaleText_loc7`='Lanzamiento de cohete en 2...' WHERE `ID`=51251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로켓 발사 1초 전...', `MaleText_loc4`='火箭将在1秒内发射……', `MaleText_loc5`='1...', `MaleText_loc7`='Lanzamiento de cohete en 1...' WHERE `ID`=51252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='发射！', `MaleText_loc5`='發射火箭!', `MaleText_loc7`='¡YA!' WHERE `ID`=51253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 전 여기 잠복 중이란 말입니다.', `MaleText_loc4`='嘘！我躲在这里呢。', `MaleText_loc5`='噓!我正在執行臥底任務。', `MaleText_loc7`='¡Chist! Estoy trabajando como infiltrado.' WHERE `ID`=51254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 쳐다보고 있는 겁니까?', `MaleText_loc4`='你看什么看？', `MaleText_loc5`='你在看什麼?', `MaleText_loc7`='¿Qué miras?' WHERE `ID`=51255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 만난 적이 있던가요?', `MaleText_loc4`='我们认识吗？', `MaleText_loc5`='我們見過面嗎?', `MaleText_loc7`='¿Nos hemos visto antes?' WHERE `ID`=51256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토르톨라 님이 여기 잡혀 계시다고 들었습니다. 그래서 최대한 빨리 왔지요.$b$b하이잘 산은 정말 높군요.', `MaleText_loc4`='我听说托尔托拉被囚禁在此处，所以我以最快的速度赶来了。$b$b海加尔山真高啊！', `MaleText_loc5`='聽說托爾托拉被關在這，所以我盡快趕來了。$b$b海加爾山真的是好高好高。', `MaleText_loc7`='Oí que Tortolla estaba retenido aquí, así que he venido lo más rápido que he podido.$b$bEl Monte Hyjal es muy alto.' WHERE `ID`=51257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네메시스와 맞설 준비가 되었습니까? 토템도 준비되었길 바랍니다.$b$b놈을 소환하고자 할 때 제게 알려 주십시오.', `MaleText_loc4`='你准备好面对涅墨西斯了吗？我希望你能善用你的图腾。$b$b当你需要召唤他的时候跟我说一声。', `MaleText_loc5`='你準備好要面對涅密希斯了嗎?希望你的圖騰也準備好了。$b$b你想要召喚它的時候跟我說一聲。', `MaleText_loc7`='¿Quieres enfrentarte a Némesis? Espero que tengas tu tótem preparado.$b$bAvísame cuando quieras que lo invoque.' WHERE `ID`=51258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나크로노스 님을 만날 준비가 되었습니다, 지라도르미 님.', `MaleText_loc4`='我准备好见阿纳克洛斯了，齐拉多尔米。', `MaleText_loc5`='佐拉多爾米，我準備好要見安納克羅斯了。', `MaleText_loc7`='Estoy listo para encontrarme con Anachronos, Ziradormi.', `FemaleText_loc1`='아나크로노스 님을 만날 준비가 되었어요, 지라도르미 님.', `FemaleText_loc4`='我准备好见阿纳克洛斯了，齐拉多尔米。', `FemaleText_loc5`='佐拉多爾米，我準備好要見安納克羅斯了。', `FemaleText_loc7`='Estoy lista para encontrarme con Anachronos, Ziradormi.' WHERE `ID`=51259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투가, 네메시스와 맞설 준비가 되었습니다.', `MaleText_loc4`='我准备好面对涅墨西斯了，图加。', `MaleText_loc5`='圖加，我準備好要面對涅密希斯了。', `MaleText_loc7`='Estoy preparado para enfrentarme a Némesis, Tooga.', `FemaleText_loc1`='투가, 네메시스와 맞설 준비가 되었습니다.', `FemaleText_loc4`='我准备好面对涅墨西斯了，图加。', `FemaleText_loc5`='圖加，我準備好要面對涅密希斯了。', `FemaleText_loc7`='Estoy preparada para enfrentarme a Némesis, Tooga.' WHERE `ID`=51260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 젊은이들! 차원문을 공격하십시오! 토르톨라를 위하여!', `MaleText_loc4`='就是现在，年轻人！攻击传送门！为了托尔托拉！', `MaleText_loc5`='在此刻，年輕的一輩啊!攻擊傳送門!為了托爾托拉!', `MaleText_loc7`='¡AHORA, JÓVENES! ¡ATAQUEN EL PORTAL! ¡POR TORTOLLA!' WHERE `ID`=51261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나크로노스 님을 만날 준비가 되었습니다, 코리도르미 님.', `MaleText_loc4`='我准备好见阿纳克洛斯了，克里多尔米。', `MaleText_loc5`='可里多爾米，我準備好要見安納克羅斯了。', `MaleText_loc7`='Estoy listo para encontrarme con Anachronos, Coridormi.', `FemaleText_loc1`='아나크로노스 님을 만날 준비가 되었어요, 코리도르미 님.', `FemaleText_loc4`='我准备好见阿纳克洛斯了，克里多尔米。', `FemaleText_loc5`='可里多爾米，我準備好要見安納克羅斯了。', `FemaleText_loc7`='Estoy lista para encontrarme con Anachronos, Coridormi.' WHERE `ID`=51262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽 길로는 가지 마십시오. 정령들이 불안정하게 날뛰고 있습니다.

혹시 당신이 고대 유물에 대해 잘 알고 있다면, 정령들을 안정시킬 방법을 찾을 수 있을지도 모릅니다.', `MaleText_loc4`='你不会想走这条路的，朋友。这里的灵魂狂躁不息。

也许，如果你对上古神器有所了解，就能找到让灵魂安息的方法。', `MaleText_loc5`='你才不會想走那條路，老兄。那些靈魂可不安份呀。

如果你對古文物稍有了解，說不定你能找到方法讓他們安息。', `MaleText_loc7`='No deberías andar por aquí, colega. Los eh''píritus eh''tán inquietos.

Quizá si sabes algo sobre ah''tefactos antiguos puedas encontrar la forma de tranquilizah''los.' WHERE `ID`=51263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르십시오, $n 님.$b$b아나크로노스 님이 기다리고 계십니다!', `FemaleText_loc4`='别再等待了，$n。$b$b阿纳克洛斯正在等你！', `FemaleText_loc5`='別耽擱時間了，$n。$b$b安納克羅斯在等你!', `FemaleText_loc7`='No debes demorarte, $n.$b$b¡Anachronos aguarda!' WHERE `ID`=51264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라가라.', `MaleText_loc4`='攀爬。', `MaleText_loc5`='爬上去。', `MaleText_loc7`='SUBE.' WHERE `ID`=51265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='형제들이여, 너희 육신을 히시스 님께 바쳐라! 부두의 힘이 너희를 지켜줄 것이다!', `FemaleText_loc4`='将你们的肉体献给赫希斯，我的兄弟们！巫毒会保护你们的！', `FemaleText_loc5`='我的兄弟，將你的身軀獻給西希斯吧，巫毒會保護你們的!', `FemaleText_loc7`='¡Entreguen sus cuerpos a Hethiss, mis hermanos, el vudú los protegerá!' WHERE `ID`=51266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물은 새것처럼 깨끗한 상태이지만, 특별한 점은 없어 보입니다.', `MaleText_loc4`='虽然这件神器来自远古时代，但你无法感觉到它散发出任何特殊的气息。', `MaleText_loc5`='雖然看起來這件文物保存得還蠻完整的，但是你感受不到它有任何特殊之處。', `MaleText_loc7`='Aunque el artefacto parece estar en una condición impecable, no percibes nada de particular en él.' WHERE `ID`=51267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물은 손상되지 않은 듯이 보이지만, 먼지와 진흙이 두텁게 덮여 있어 분명하지 않습니다. 마법의 힘은 전혀 담겨 있지 않은 것 같습니다.', `MaleText_loc4`='这件神器看起来是完整的，不过由于被厚厚的泥土掩盖而很难确定。看起来它并不蕴含任何远古魔法能量。', `MaleText_loc5`='這件文物看起來完好無缺，不過上上下下都覆滿了塵土和泥巴，看不出是什麼東西了。看起來並沒有什麼魔法力量蘊藏其中。', `MaleText_loc7`='El artefacto parece estar intacto, aunque está cubierto totalmente por tierra y barro, y es difícil saberlo con seguridad. No da la impresión de que exista algo inherentemente mágico en él.' WHERE `ID`=51268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물은 여러 번의 풍파를 거친 듯 크게 파손되었습니다. 예전의 힘을 아직 담고 있지는 않을 것 같습니다.', `MaleText_loc4`='这件神器经历了多年的风吹雨打，早已失去了往日的光芒。很难相信它是否还蕴含着什么力量。', `MaleText_loc5`='這件文物飽經風吹雨打，被破壞的跡象十分明顯。這不禁讓人懷疑還能有多少能量蘊含其中。', `MaleText_loc7`='El artefacto ha superado muchas tormentas y muestra claros signos de deterioro. Resulta improbable que permanezcan en él los poderes que hubiera podido contener antiguamente.' WHERE `ID`=51269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잎과 가지가 붙어 있는 것으로 보아, 이 물체는 어떤 생물의 둥지 일부였을 것이 분명합니다. 그 밖에는 주목할 점이 없습니다.', `MaleText_loc4`='这个物件粘着了些许树叶和杂枝，显示出它曾被某种生物用来筑巢。除此以外，这东西就没有什么值得注意的地方了。', `MaleText_loc5`='物品上有枝葉攀附，代表這曾是某種生物巢穴的一部份。其他沒什麼值得注意的地方了。', `MaleText_loc7`='Algunas hojas y ramas se aferran a este objeto, lo que indica que probablemente se haya utilizado como parte del nido de alguna criatura. Por lo demás, no hay nada más digno de destacar.' WHERE `ID`=51270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물체에는 이상한 무늬가 여럿 새겨져 있습니다. 어쩌면 이 물체의 기원을 알아내려고 한 트롤이 그 분석 과정을 새겨놓았는지도 모릅니다. 하지만 이 물체가 원형을 유지하고 있는 것으로 보아, 트롤들은 성공하지 못했을 것입니다.', `MaleText_loc4`='这个器物表面有一些奇怪的刻痕，也许是巨魔尝试用来解开它的起源之谜的。看起来他们并未获得成功，因为该物件原封未动。', `MaleText_loc5`='在這件物品上面雕有數種奇怪的飾紋，或許食人妖試圖描繪其起源時所刻下的。這看起來並不是什麼成功的作品，因為這件物品看起來了無生氣。', `MaleText_loc7`='Unas extrañas tallas adornan este objeto, quizá hechas por trols en un intento de descifrar sus orígenes. No parece que tuvieran mucho éxito, ya que el objeto permanece inerte.' WHERE `ID`=51271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물은 신비한 룬으로 장식되어 있습니다. 하지만 지금 룬에는 아무런 힘도 깃들지 않은 듯이 보입니다.', `MaleText_loc4`='神秘的符文装饰着这件神器，不过他们现在看似并无能量。', `MaleText_loc5`='神秘的符文裝飾在這件文物上頭，不過看來早已失去力量。', `MaleText_loc7`='Unas misteriosas runas adornan este artefacto, aunque actualmente parece que no tiene poder alguno.' WHERE `ID`=51272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물건의 조악한 품질로 보아, 한동안 암시장에 넘쳐 흐르던 가짜 유물일 것 같습니다.', `MaleText_loc4`='这个物件质量低劣，很可能是充斥黑市的假冒伪劣产品。', `MaleText_loc5`='以品質來說這件物品算不上是什麼好東西，看起來跟大量湧入黑市中的贗品文物沒兩樣。', `MaleText_loc7`='Este objeto es de baja calidad y, probablemente, sea uno de esos artefactos falsos que abundan en el mercado negro.' WHERE `ID`=51273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물체에서는 마른 핏자국이 몇 군데 보입니다. 트롤들이 이 유물을 차지하려고 다투는 과정에서 생겼을 것입니다. 하지만 물체 자체는 상당히 평범해 보이며, 그렇게 서로 다툴 만한 물건은 아닌 듯합니다.', `MaleText_loc4`='该物件上残留着斑斑血迹，很可能是巨魔们在争夺它时留下的。然而这个物件本身平凡无奇，其实并不值得争抢。', `MaleText_loc5`='這件物品上面有好幾個乾涸的血漬，看來食人妖在取得這件文物時曾經歷一番爭鬥。不過，此物看來一般，很可能不具抗爭奪取的價值。', `MaleText_loc7`='Se pueden ver en este objeto varias manchas de sangre seca, probablemente como resultado de alguna pelea por quitarles el artefacto a los trols. Sin embargo, el objeto es bastante mundano y puede que no mereciera la pena verter sangre por él.' WHERE `ID`=51274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 간식 먹고 싶어?', `FemaleText_loc4`='露比，想要奖励么？', `FemaleText_loc5`='露比想吃點心嗎?', `FemaleText_loc7`='Rubí, ¿quieres un regalito?' WHERE `ID`=51275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 죽은 척 해봐.', `FemaleText_loc4`='露比，装死。', `FemaleText_loc5`='露比，裝死。', `FemaleText_loc7`='Rubí, hazte la muerta.' WHERE `ID`=51276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 으르렁해봐.', `FemaleText_loc4`='露比，说话，', `FemaleText_loc5`='露比，說話。', `FemaleText_loc7`='Rubí, habla.' WHERE `ID`=51277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 뛰어보렴.', `FemaleText_loc4`='露比，跳', `FemaleText_loc5`='露比，跳。', `FemaleText_loc7`='Rubí, salta.' WHERE `ID`=51278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 뒤로 걸어.', `FemaleText_loc4`='露比，后退。', `FemaleText_loc5`='露比，退著走。', `FemaleText_loc7`='Rubí, camina hacia atrás.' WHERE `ID`=51279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='루비, 춤춰.', `FemaleText_loc4`='露比，跳舞。', `FemaleText_loc5`='露比，跳舞。', `FemaleText_loc7`='Rubí, baila.' WHERE `ID`=51280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어, 루비!', `FemaleText_loc4`='露比，好女孩！', `FemaleText_loc5`='乖女孩，露比!', `FemaleText_loc7`='¡Buena chica, Rubí!' WHERE `ID`=51281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 멋진 아기 랩터야!', `FemaleText_loc4`='真是头好恐龙！', `FemaleText_loc5`='真是隻不可思議的迅猛龍!', `FemaleText_loc7`='¡Eres un buen daptod pedqueño!' WHERE `ID`=51282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 똑똑하구나, 그렇지?', `FemaleText_loc4`='你是个聪明的女孩，对不对？', `FemaleText_loc5`='你是個聰明的女孩，對吧?', `FemaleText_loc7`='Eres una chica lista, ¿verdad?' WHERE `ID`=51283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와! 정말 대단했어!', `FemaleText_loc4`='呀！真是惊人啊！', `FemaleText_loc5`='耶!真是太驚人了!', `FemaleText_loc7`='¡Sí! ¡Ha sido alucinante!' WHERE `ID`=51284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 마법사가 아이스크림을 만들 수 있는 줄은 몰랐어요. 게다가 진짜 맛있던데요!', `MaleText_loc4`='哇，我从来不知道法师还可以做冰激凌。这太棒了！', `MaleText_loc5`='哇喔，我不知道原來法師可以做出冰淇淋呀。真好!', `MaleText_loc7`='Vaya, no sabía que los magos podían hacer helado. ¡Estaba bueno!' WHERE `ID`=51285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어른이 되면 저도 여러 가지를 조합해 볼래요!', `MaleText_loc4`='我长大以后，也要把各种怪东西拼起来！', `MaleText_loc5`='等我長大了，我也要用一堆奇怪玩意兒拼湊成一個物品!', `MaleText_loc7`='¡Cuando crezca, yo también quiero unir cosas raras!' WHERE `ID`=51286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 비누에 포크를 붙이는 건 어때요? 그럼 손잡이도 생기고 좋잖아요!', `MaleText_loc4`='不如……在叉子上擦点肥皂？这样就万事俱备啦！', `MaleText_loc5`='這樣如何...在叉子上放塊肥皂呢?有了握把，那就沒問題啦!', `MaleText_loc7`='¿Y si... ponemos jabón en un tenedor? ¡Entonces tendría mango y todo!' WHERE `ID`=51287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 비누를 다 쓰면 새 포크가 생기는 거죠!', `MaleText_loc4`='肥皂消退的时候，你就拥有一把崭新的叉子了！', `MaleText_loc5`='等肥皂沒了，你就有把新的叉子啦!', `MaleText_loc7`='¡Y cuando se ha gastado el jabón, te queda un tenedor nuevo!' WHERE `ID`=51288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물체에서는 어딘지 모르게 이상한 점이 느껴집니다...', `MaleText_loc4`='这件神器有些奇怪……', `MaleText_loc5`='這件物品看起來有點不尋常...', `MaleText_loc7`='Hay algo extraño en este objeto particular...' WHERE `ID`=51289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물체를 관찰합니다.', `MaleText_loc4`='检查该物品。', `MaleText_loc5`='檢視這件物品。', `MaleText_loc7`='Examinar el objeto.' WHERE `ID`=51290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물에는 트롤 의술사의 저주가 걸려 있습니다! 당신이 손을 대자 유물이 음침하게 빛나기 시작합니다.', `MaleText_loc4`='这件神器遭到了巨魔巫医的诅咒！被你碰触了之后，它开始发出邪恶的光辉。', `MaleText_loc5`='這件文物曾為食人妖巫醫所詛咒!你一觸碰，便散發出邪惡的光芒。', `MaleText_loc7`='¡Este artefacto ha sido maldecido por los médicos brujos trols! Cuando lo tocas, empieza a emitir un resplandor maligno.' WHERE `ID`=51291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 편히 가지거라, 필멸의 존재여. 이곳에서 그대와 나누는 시간에는 결실이 있어야 하며, 섣부른 생각으로 마음을 흐려서는 안 된다..$b$b합당한 이유를 알고, 명료한 생각을 할 수 있는 그대의 능력에 많은 것이 달렸다.', `MaleText_loc4`='轻松点，凡人。我们必须在不紧张的情况下有效交流。$b$b当然这主要取决于你是否思路清晰且明辨事理。', `MaleText_loc5`='放輕鬆，凡人。我們的時間在此交會想必會產生些什麼，此種張力會使一切變得明朗。$b$b這絕大部分取決於你清晰思考及分析判斷的能力。', `MaleText_loc7`='Tranquilo, mortal. Nuestro tiempo juntos debe ser productivo y ajeno a toda tensión.$b$bHay muchas cosas que dependen de tu habilidad para pensar con claridad y razonar correctamente.' WHERE `ID`=51292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물체를 관찰합니다.', `MaleText_loc4`='检查这件物品。', `MaleText_loc5`='檢視這件物品。', `MaleText_loc7`='Examinar el objeto.' WHERE `ID`=51293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물체를 관찰합니다.', `MaleText_loc4`='检查这件物品。', `MaleText_loc5`='檢視這件物品。', `MaleText_loc7`='Examinar el objeto.', `FemaleText_loc1`='물체를 관찰합니다.', `FemaleText_loc4`='检查这件物品。', `FemaleText_loc5`='檢視這件物品。', `FemaleText_loc7`='Examinar el objeto.' WHERE `ID`=51294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 파는지 보여주십시오.', `MaleText_loc4`='让我们看看你都在卖些什么。', `MaleText_loc5`='讓我瞧瞧你在賣些什麼。', `MaleText_loc7`='A ver qué tienes para vender.', `FemaleText_loc1`='뭘 파는지 보여주세요.', `FemaleText_loc4`='让我们看看你都在卖些什么。', `FemaleText_loc5`='讓我瞧瞧你在賣些什麼。', `FemaleText_loc7`='A ver qué tienes para vender.' WHERE `ID`=51295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘들아, $n 님이 선물을 사오셨단다! 와서 구경하렴!', `FemaleText_loc4`='孩子们，$n给你们带来了一件礼物！来看看吧！', `FemaleText_loc5`='孩子們，$n帶了禮物來送給你們!快來看看吧!', `FemaleText_loc7`='¡Niños, $n os ha traído un regalo! ¿Por qué no venís a echar un vistazo?' WHERE `ID`=51297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 깜짝 선물이다! 기분 좋아요!', `MaleText_loc4`='喔，真是一个惊喜！我喜欢惊喜！', `MaleText_loc5`='哇喔，驚喜耶!我超愛驚喜的!', `MaleText_loc7`='¡Guau, una sorpresa! ¡Me encantan las sorpresas!', `FemaleText_loc1`='우와, 깜짝 선물이다! 기분 좋아요!', `FemaleText_loc4`='喔，真是一个惊喜！我喜欢惊喜！', `FemaleText_loc5`='哇喔，驚喜耶!我超愛驚喜的!', `FemaleText_loc7`='¡Guau, una sorpresa! ¡Me encantan las sorpresas!' WHERE `ID`=51298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워! 저 때문에 놀라셨나요?$b$b할로윈 축제는 두 가지 빼면 시체죠. 장난과 사탕 말이에요! 어떤 어른들은 그게 다가 아니라고 생각하긴 하더군요. 저한테 설명해 주려고 하긴 했는데, 사실 너무 지루했어요. 불길이 치솟는 걸 볼 때까진 말이에요! 그건 정말 멋지던데요!$b$b하지만 불길도 계속 보면 싫증이 나요. 절대로 싫증 안 나는 게 있는데... 바로 사람들 놀래주는 거랑 사탕 먹는 거랍니다!$b$b하지만 제가 원하는 사탕은 딱 한 종류뿐이에요. 사탕 동전 말이에요! 그게 최고예요. 골드랑 똑같이 생겼지요! 동전이 너무 많다 싶으면 먹어치워도 돼요! 말 그대로 돈 놓고 돈 먹기죠! 정말 멋지죠?!$b$b자... 혹시 동전 가지고 계세요? 다른 거랑 바꾸실래요?', `MaleText_loc4`='嘭！我吓到你了没？$b$b万圣节只有两件事最重要：糖果和捣乱！大人们觉得还有别的更重要的事情，他们想向我灌输他们的想法，但我觉得除了点火以外都太无聊了，那真的很酷！$b$b但话说回来，就算是点火也会无聊的。你知道什么永远不会无聊吗？给别人捣乱和吃糖果！$b$b但我只想要一种糖果，就是糖果硬币！那是最棒的糖果，看起来像真的金币一样！而且如果你嫌硬币太多的话，你可以吃掉它们！感觉就像钱多得可以当饭吃一样！那太疯狂了！$b$b你有想要交易的硬币吗？', `MaleText_loc5`='喝!我嚇到你了嗎?$b$b說穿了，萬鬼節就是兩件事，糖果、跟搗蛋!有些成年人會覺得不只是如此。他們想告訴我，不過我覺得很無聊，一直到有東西燒起來才讓我為之一醒。那實在太酷了!$b$b不過還是一樣，就算是火還是會讓我覺得無聊。我可以告訴你怎樣才不無聊...去作弄人們，討些糖吃!$b$b可是我想要的只有一種糖，那就是糖果幣!這種糖最棒了。看起來就像是真的金幣一樣!而且呀，如果你口袋金幣太多，還可以把它們吃掉!感覺就像是變有錢了，然後吃著你自己的錢一樣!這太瘋狂啦!$b$b所以呢...你有糖果幣要交換的嗎?', `MaleText_loc7`='¡BUUU! ¿Te he asustado?$b$bHalloween trata sobre todo de dos cosas: ¡truco o trato! Intentaron decírmelo, pero me aburría hasta que las cosas empezaron a arder. ¡Fue genial!$b$bPero incluso el fuego puede volverse aburrido... Aunque hay dos cosas de las que no puedes aburrirte nunca: ¡de engañar a la gente y de comer caramelos!$b$BPero yo solo quiero un tipo de caramelos, ¡monedas de caramelo! Son los mejores. ¡Parecen monedas de oro de verdad! Además, si tienes demasiadas monedas, te las puedes comer. Es como si fueras rico y te comieras tu dinero. ¡Es una locura!$b$bBueno... ¿tienes algunas monedas que quieras cambiar?', `FemaleText_loc1`='워! 저 때문에 놀라셨나요?$b$b할로윈 축제는 두 가지 빼면 시체죠. 장난과 사탕 말이에요! 어떤 어른들은 그게 다가 아니라고 생각하긴 하더군요. 저한테 설명해 주려고 하긴 했는데, 사실 너무 지루했어요. 불길이 치솟는 걸 볼 때까진 말이에요! 그건 정말 멋지던데요!$b$b하지만 불길도 계속 보면 싫증이 나요. 절대로 싫증 안 나는 게 있는데... 바로 사람들 놀래주는 거랑 사탕 먹는 거랍니다!$b$b하지만 제가 원하는 사탕은 딱 한 종류뿐이에요. 사탕 동전 말이에요! 그게 최고예요. 골드랑 똑같이 생겼지요! 동전이 너무 많다 싶으면 먹어치워도 돼요! 말 그대로 돈 놓고 돈 먹기죠! 정말 멋지죠?!$b$b자... 혹시 동전 가지고 계세요? 다른 거랑 바꾸실래요?', `FemaleText_loc4`='嘭！我吓到你了没？$b$b万圣节只有两件事最重要：糖果和捣乱！大人们觉得还有别的更重要的事情，他们想向我灌输他们的想法，但我觉得除了点火以外都太无聊了，那真的很酷！$b$b但话说回来，就算是点火也会无聊的。你知道什么永远不会无聊吗？给别人捣乱和吃糖果！$b$b但我只想要一种糖果，就是糖果硬币！那是最棒的糖果，看起来像真的金币一样！而且如果你嫌硬币太多的话，你可以吃掉它们！感觉就像钱多得可以当饭吃一样！那太疯狂了！$b$b你有想要交易的硬币吗？', `FemaleText_loc5`='喝!我嚇到你了嗎?$b$b說穿了，萬鬼節就是兩件事，糖果、跟搗蛋!有些成年人會覺得不只是如此。他們想告訴我，不過我覺得很無聊，一直到有東西燒起來才讓我為之一醒。那實在太酷了!$b$b不過還是一樣，就算是火還是會讓我覺得無聊。我可以告訴你怎樣才不無聊...去作弄人們，討些糖吃!$b$b可是我想要的只有一種糖，那就是糖果幣!這種糖最棒了。看起來就像是真的金幣一樣!而且呀，如果你口袋金幣太多，還可以把它們吃掉!感覺就像是變有錢了，然後吃著你自己的錢一樣!這太瘋狂啦!$b$b所以呢...你有糖果幣要交換的嗎?', `FemaleText_loc7`='¡BUUU! ¿Te he asustado?$b$bHalloween trata sobre todo de dos cosas: ¡truco o trato! Intentaron decírmelo, pero me aburría hasta que las cosas empezaron a arder. ¡Eso fue genial!$b$bPero incluso el fuego puede volverse aburrido... Aunque hay dos cosas de las que no puedes aburrirte nunca: ¡de engañar a la gente y comer caramelos!$b$BPero yo solo quiero un tipo de caramelos, ¡monedas de caramelo! Son los mejores. ¡Parecen monedas de oro de verdad! Además, si tienes demasiadas monedas te las puedes comer. Es como si fueras rico y te comieras tu dinero. ¡Es una locura!$b$bBueno... ¿tienes algunas monedas que quieras cambiar?' WHERE `ID`=51299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누나는 우리를 기다리며 맛있기로 소문난 얼룩말 구이 요리를 해 놓고 있을 것이오. 나보고 고기 좀 줄이고 야채를 더 먹으라고 했지만, 내가 그 정도로 살이 쪘다고는 생각하지 않는데... 안 그렇소?', `MaleText_loc4`='娜格拉一定会切好她拿手的炙烤斑马肉等我们。她说我需要节食并多吃点蔬菜，但我觉得我还没那么胖吧……你说呢？', `MaleText_loc5`='納迦拉當然會準備好她那遠近馳名的烤角斑馬肉排等著我們。她說，我應該要減肥，多吃點蔬菜，可是我不覺得我有胖那麼多呀...你覺得呢?', `MaleText_loc7`='Sin duda, Nagala tendrá una buena ración de sus famosas costillas de zhebra esperándonos. Dice que tengo que cuidarme y comer más verdura, pero no creo haber engordado tanto... ¿no?' WHERE `ID`=51300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 사실 사탕 동전이 좀 있는데, 뭐로 바꿀 수 있니?', `MaleText_loc4`='我有一些想交换的糖果硬币。', `MaleText_loc5`='我有些糖果幣想交換。', `MaleText_loc7`='Tengo algunas monedas de caramelo que me gustaría cambiar.', `FemaleText_loc1`='그래. 사실 사탕 동전이 좀 있는데, 뭐로 바꿀 수 있니?', `FemaleText_loc4`='我有一些想交换的糖果硬币。', `FemaleText_loc5`='我有些糖果幣想交換。', `FemaleText_loc7`='Tengo algunas monedas de caramelo que me gustaría cambiar.' WHERE `ID`=51301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달콤한 걸 보여주세요!', `MaleText_loc4`='要糖！', `MaleText_loc5`='給我糖!', `MaleText_loc7`='¡Enséñame el azúcar!' WHERE `ID`=51302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 놔! 나 좀 도와주시오!', `MaleText_loc4`='救命！放开我！', `MaleText_loc5`='救命啊!放我出去!', `MaleText_loc7`='¡Socorro! ¡Suéltame!' WHERE `ID`=51303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 칼이 제일 멋져!', `MaleText_loc4`='这是最好的！', `MaleText_loc5`='這是最棒的!', `MaleText_loc7`='¡Esta es la mejor!', `FemaleText_loc1`='이 칼이 제일 멋져!', `FemaleText_loc4`='这是最好的！', `FemaleText_loc5`='這是最棒的!', `FemaleText_loc7`='¡Esta es la mejor!' WHERE `ID`=51304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 아나크로노스. 당신이 보여주는 미래의 환영을 보겠습니다.', `MaleText_loc4`='是的，阿纳克洛斯。我准备好见证你所预见的未来了。', `MaleText_loc5`='是的，安納克羅斯。我已經準備好觀看未來的景象。', `MaleText_loc7`='Por favor, Anachronos, estoy listo para tu visión del futuro.', `FemaleText_loc1`='예, 아나크로노스. 당신이 보여주는 미래의 환영을 보여주세요.', `FemaleText_loc4`='是的，阿纳克洛斯。我准备好见证你所预见的未来了。', `FemaleText_loc5`='是的，安納克羅斯。我已經準備好觀看未來的景象。', `FemaleText_loc7`='Por favor, Anachronos, estoy lista para tu visión del futuro.' WHERE `ID`=51305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 루비. 넌 정말 최고야!', `FemaleText_loc4`='哦，露比，你真是最好最好的宠物！', `FemaleText_loc5`='喔喔喔露比，你是最棒的寵物了!', `FemaleText_loc7`='¡Ooh, Rubí, eres la mejor mascota que ha existido nunca!' WHERE `ID`=51306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $c 친구. 난 톨크라고 하네. 대족장님의 이름으로 이곳 수비를 책임지고 있지. 자네가 이곳 십자로를 도울 기회가 생긴 걸 알고 있네. 호드를 위해 계속 전진하게!', `MaleText_loc4`='你好，$c。我的名字是索克。以酋长的名义，我指挥这里的防御。$B$B你已经在十字路口立下了许多功绩。继续为部落而奋战吧！', `MaleText_loc5`='你好，$c。我叫做索克，我奉大酋長之名在此負責防守。$B$B我知道你在十字路口曾出手協助過。繼續下去，為了部落!', `MaleText_loc7`='Saludos, $c. Me llamo Thork y estoy al mando de las defensas de este lugar en nombre del Jefe de Guerra.$B$BVeo que has tenido la oportunidad de echar una mano en El Cruce. ¡Continúa así por la Horda!' WHERE `ID`=51307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이길걸!', `MaleText_loc4`='你抓不住我！', `MaleText_loc5`='你抓不到我!', `MaleText_loc7`='¡No puedes pillarme!', `FemaleText_loc1`='내가 이길걸!', `FemaleText_loc4`='你抓不住我！', `FemaleText_loc5`='你抓不到我!', `FemaleText_loc7`='¡No puedes pillarme!' WHERE `ID`=51308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=51309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 멋있지? 난 빛의 수호자 우서 경이다!', `MaleText_loc4`='看着我，我是乌瑟尔·光明使者！', `MaleText_loc5`='你看，我是烏瑟·光明使者!', `MaleText_loc7`='¡Miradme, soy Uther el Iluminado!', `FemaleText_loc1`='나 멋있지? 난 빛의 수호자 우서 경이다!', `FemaleText_loc4`='看着我，我是乌瑟尔·光明使者！', `FemaleText_loc5`='你看，我是烏瑟·光明使者!', `FemaleText_loc7`='¡Miradme, soy Uther el Iluminado!' WHERE `ID`=51310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 정말 큰 칼이다!', `MaleText_loc4`='这是我见过的最大的剑！', `MaleText_loc5`='這可是有史以來最大一把劍!', `MaleText_loc7`='¡Esta es la espada más grande que ha existido nunca!', `FemaleText_loc1`='우와, 정말 큰 칼이다!', `FemaleText_loc4`='这是我见过的最大的剑！', `FemaleText_loc5`='這可是有史以來最大一把劍!', `FemaleText_loc7`='¡Esta es la espada más grande que ha existido nunca!' WHERE `ID`=51311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사출! 사출! 으아아아아!', `MaleText_loc4`='喷射！喷射！喔啊啊！！', `MaleText_loc5`='彈射!快彈射呀!呃啊啊啊!', `MaleText_loc7`='¡Eyectar! ¡Eyectar! ¡Auuuugggh!' WHERE `ID`=51312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 넘어서는 안 될 선을 넘었다, 진도. 감당하지도 못할 힘으로 장난을 치다니. 너는 내가 누군지 잊었느냐? 너는 내가 가진 힘을 잊었느냐?!', `MaleText_loc4`='你太放肆了，金度，你竟敢把远远凌驾于你的力量当作儿戏。难道你忘了我是谁？难道你忘了我能做什么？', `MaleText_loc5`='你跨越了你的分際，金度。你觸碰了遠超越你的力量。你忘了我是誰嗎?你忘了我的能耐了嗎?', `MaleText_loc7`='Te has pasado de la raya, Jin''do. Juegas con poderes que van más allá de ti. ¿Acaso has olvidado quién soy? ¡¿Has olvidado lo que puedo hacer?!' WHERE `ID`=51313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은산속 광부조합과 보석세공점에 가보셔야겠군요. 대용광로 북쪽에 있습니다.', `MaleText_loc4`='想找深山珠宝矿业协会，去大锻炉北侧吧。', `MaleText_loc5`='你要找深山礦工與珠寶設計協會?就在大鍛爐的北面。', `MaleText_loc7`='Lo que buscas es Minería y joyería de Montehondo, en el lado norte de La Gran Fundición.', `FemaleText_loc1`='깊은산속 광부조합과 보석세공점에 가보셔야겠군요. 대용광로 북쪽에 있습니다.', `FemaleText_loc4`='想找深山珠宝矿业协会，去大锻炉北侧吧。', `FemaleText_loc5`='你要找深山礦工與珠寶設計協會?就在大鍛爐的北面。', `FemaleText_loc7`='Lo que buscas es Minería y joyería de Montehondo, en el lado norte de La Gran Fundición.' WHERE `ID`=51314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 보석세공인과 보석세공용품 상인은 군사 지구 내곽에 있네.', `MaleText_loc4`='你可以在军事区内环找到珠宝加工训练师和供应商。', `MaleText_loc5`='你可以在軍事區的內環找到珠寶設計訓練師和供應商。', `MaleText_loc7`='Encontrarás un instructor de joyería y suministros en el cinturón interior del Barrio de la Guerra.', `FemaleText_loc1`='전문 보석세공인과 보석세공용품 상인은 군사 지구 내곽에 있네.', `FemaleText_loc4`='你可以在军事区内环找到珠宝加工训练师和供应商。', `FemaleText_loc5`='你可以在軍事區的內環找到珠寶設計訓練師和供應商。', `FemaleText_loc7`='Encontrarás un instructor de joyería y suministros en el cinturón interior del Barrio de la Guerra.' WHERE `ID`=51315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구 내곽. 보석 만드는 자들 거기 있다.', `MaleText_loc4`='去军事区内环。你会在那里找到珠宝加工匠人。', `MaleText_loc5`='到軍事區的內環去。從事珠寶設計的那群人都在那裡。', `MaleText_loc7`='Ve al cinturón interior del Barrio de la Guerra. Allí encontrarás a joyeros.', `FemaleText_loc1`='군사 지구 내곽. 보석 만드는 자들 거기 있다.', `FemaleText_loc4`='去军事区内环。你会在那里找到珠宝加工匠人。', `FemaleText_loc5`='到軍事區的內環去。從事珠寶設計的那群人都在那裡。', `FemaleText_loc7`='Ve al cinturón interior del Barrio de la Guerra. Allí encontrarás a joyeros.' WHERE `ID`=51316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다.', `MaleText_loc4`='感谢你的帮助。', `MaleText_loc5`='多謝你出手相助。', `MaleText_loc7`='Gracias por tu ayuda.', `FemaleText_loc1`='도와주셔서 감사해요.', `FemaleText_loc4`='感谢你的帮助。', `FemaleText_loc5`='多謝你出手相助。', `FemaleText_loc7`='Gracias por tu ayuda.' WHERE `ID`=51317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨을 구해 주셨습니다!', `MaleText_loc4`='你救了我的命！', `MaleText_loc5`='你救了我一命!', `MaleText_loc7`='¡Me has salvado la vida!', `FemaleText_loc1`='제 목숨을 구해 주셨어요!', `FemaleText_loc4`='你救了我的命！', `FemaleText_loc5`='你救了我一命!', `FemaleText_loc7`='¡Me has salvado la vida!' WHERE `ID`=51318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이게 무슨 일입니까? 식사하려고 자리에 앉았던 것만 기억납니다...', `MaleText_loc4`='出……出了什么事？我只记得自己要坐下吃东西……', `MaleText_loc5`='怎...這是怎麼一回事?我只記得我正要坐下來吃東西...', `MaleText_loc7`='¿Qué... qué ocurre? Lo último que recuerdo es haberme sentado para comer...', `FemaleText_loc1`='이... 이게 무슨 일이죠? 식사하려고 자리에 앉았던 것만 기억나네요...', `FemaleText_loc4`='出……出了什么事？我只记得自己要坐下吃东西……', `FemaleText_loc5`='怎...這是怎麼一回事?我只記得我正要坐下來吃東西...', `FemaleText_loc7`='¿Qué... qué ocurre? Lo último que recuerdo es haberme sentado para comer...' WHERE `ID`=51319;
