UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사를 하려던 참이었는데, 갑자기 좀비가 나타나기 시작했습니다!', `MaleText_loc4`='我们刚刚要吃东西，僵尸突然就出现了！', `MaleText_loc5`='我們剛剛正想要吃點東西，這群殭屍就突然現身了!', `MaleText_loc7`='¡Estábamos intentando comer algo y, de pronto, empezaron a aparecer zombis!', `FemaleText_loc1`='식사를 하려던 참이었는데, 갑자기 좀비가 나타나기 시작했어요!', `FemaleText_loc4`='我们刚刚要吃东西，僵尸突然就出现了！', `FemaleText_loc5`='我們剛剛正想要吃點東西，這群殭屍就突然現身了!', `FemaleText_loc7`='¡Estábamos intentando comer algo y, de pronto, empezaron a aparecer zombis!' WHERE `ID`=51321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식... 음식이 뭔가 잘못됐습니다!', `MaleText_loc4`='食物，食物有问题！', `MaleText_loc5`='食物、食物有問題!', `MaleText_loc7`='¡La comida! ¡Algo malo le pasa a la comida!', `FemaleText_loc1`='음식... 음식이 뭔가 잘못됐어요!', `FemaleText_loc4`='食物，食物有问题！', `FemaleText_loc5`='食物、食物有問題!', `FemaleText_loc7`='¡La comida! ¡Algo malo le pasa a la comida!' WHERE `ID`=51322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 막 포기하려던 참이었습니다.', `MaleText_loc4`='我几乎要绝望了。', `MaleText_loc5`='我幾乎絕望了。', `MaleText_loc7`='Ya había renunciado a toda esperanza.', `FemaleText_loc1`='지금 막 포기하려던 참이었어요.', `FemaleText_loc4`='我几乎要绝望了。', `FemaleText_loc5`='我幾乎絕望了。', `FemaleText_loc7`='Ya había renunciado a toda esperanza.' WHERE `ID`=51323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 이상합니다... 음식 맛이 정말 끔찍했습니다.', `MaleText_loc4`='哦，我的肚子……那食物真的很糟糕。', `MaleText_loc5`='喔天啊，我的肚子...這食物糟透了。', `MaleText_loc7`='Ay, mi estómago... Esa comida estaba muy mal.', `FemaleText_loc1`='속이 이상해요... 음식 맛이 정말 끔찍했어요.', `FemaleText_loc4`='哦，我的肚子……那食物真的很糟糕。', `FemaleText_loc5`='喔天啊，我的肚子...這食物糟透了。', `FemaleText_loc7`='Ay, mi estómago... Esa comida estaba muy mal.' WHERE `ID`=51324;
