UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이란 수많은 운명의 실이 서로 얽혀 만들어지는 것.', `MaleText_loc4`='无数的时间线编织成了我们的时光之网。', `MaleText_loc5`='我們的時間軸是由無數經緯線交織而成。', `MaleText_loc7`='Innumerables hilos se tejen para crear la trama de nuestra cronología.' WHERE `ID`=51326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 청동용군단, 시간의 파수꾼들은 이 운명의 무한한 조합을 관찰하지.', `MaleText_loc4`='作为时光守护者，我们青铜龙军团一直在观察它们无尽的组合。', `MaleText_loc5`='身為時光守衛，我們青銅龍軍團觀察著這些無限的組合。', `MaleText_loc7`='Como guardianes del tiempo, los del Vuelo Bronce observamos sus infinitas combinaciones.' WHERE `ID`=51327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간에 혼란이 발생했을 때 그것을 바로잡는 게 바로 우리의 임무다.', `MaleText_loc4`='当观察者发现了时间的扰动后，我们将负责修复。', `MaleText_loc5`='當觀察者發現有時間軸瓦解的情況發生，我們就會前去修復。', `MaleText_loc7`='Cuando nuestros observadores detectan una avería, nos encargamos de repararla.' WHERE `ID`=51328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근 한 사건이 강력한 마법에 휩싸여, 나조차도 들여다볼 수가 없구나.', `MaleText_loc4`='一个刚刚发生的事件，掩没于强大的魔法中，即便对我来说也很神秘……', `MaleText_loc5`='最近發生了一個被強大魔法籠罩的事件，至今仍讓我無法感知...', `MaleText_loc7`='Un hecho reciente, oculto por magias poderosas, permanece encubierto incluso para mí...' WHERE `ID`=51329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 사건의 결과만큼은 명백하다.', `MaleText_loc4`='但是，这注定的结果已经很清楚了：', `MaleText_loc5`='但是結局無可避免，而且明顯易見:', `MaleText_loc7`='Pero el catastrófico resultado está claro:' WHERE `ID`=51330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스가 불탈 것이다!', `MaleText_loc4`='艾泽拉斯将会毁灭！', `MaleText_loc5`='艾澤拉斯會陷入一片火海之中!', `MaleText_loc7`='¡Azeroth arderá!' WHERE `ID`=51331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 자세한 내용을 볼 순 없었지만, 한 가지 확실한 건...', `MaleText_loc4`='事件的细节仍然扑朔迷离，但我确定了一件事……', `MaleText_loc5`='在視線仍被瑣碎事物所遮蔽的當下，我們弄清楚了一點...', `MaleText_loc7`='Aunque los detalles se ocultan ante nuestros ojos, hemos podido deducir…' WHERE `ID`=51332;
