UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 운명이 한 흑마법사의 활약에 달려있다는 것이다.', `MaleText_loc4`='艾泽拉斯的命运将维系在一位凡人术士身上。', `MaleText_loc5`='艾澤拉斯的命運在一名凡人術士的手上。', `MaleText_loc7`='El destino de Azeroth depende de lo que haga $gun brujo:una bruja; mortal.', `FemaleText_loc1`='아제로스의 운명이 한 흑마법사의 활약에 달려있다는 것이다.', `FemaleText_loc4`='艾泽拉斯的命运将维系在一位凡人术士身上。', `FemaleText_loc5`='艾澤拉斯的命運在一名凡人術士的手上。', `FemaleText_loc7`='El destino de Azeroth depende de lo que haga $gun brujo:una bruja; mortal.' WHERE `ID`=51337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 바로 그 운명을 짊어진 주인공인가?', `MaleText_loc4`='你就是那个能肩负重担的凡人吗？', `MaleText_loc5`='你會是那個我們能夠依靠的人嗎?', `MaleText_loc7`='¿Eres tú ese mortal del que todo depende?' WHERE `ID`=51338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 설원호랑이가 작은 곤충에 한쪽 앞발을 휘두르지만, 곤충이 날아간 뒤에야 당신의 존재를 알아챕니다.', `MaleText_loc4`='幼崽伸出小爪子想去捕捉一只小虫子，当玩物飞走时它才注意到你在看它。', `MaleText_loc5`='這隻幼獸的爪下壓著一隻小蟲，在掌中玩物飛走之後才注意到你在場。', `MaleText_loc7`='El cachorro abate un pequeño insecto con su garra, y solo se da cuenta de que estás prestando atención cuando su juguete se aleja volando.' WHERE `ID`=51339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 설원호랑이가 몸을 비비며 가르랑거립니다.', `MaleText_loc4`='幼崽用鼻子蹭了蹭你的手，心满意足地发出了咕噜咕噜的叫声。', `MaleText_loc5`='這隻幼獸用鼻頭摩擦你的手，並從喉頭發出低沉的咕嚕聲。', `MaleText_loc7`='El cachorro te acaricia la mano con el hocico y ronronea.' WHERE `ID`=51340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이와 그의 조수는 전사의 정원에서 찾으실 수 있습니다. 무기 및 방어구 상인 근처에 있지요.', `MaleText_loc4`='你可以在战士区找到铁匠和他的助手，就在护甲和武器供应商附近。', `MaleText_loc5`='鐵匠和助手們在戰士區的護甲商及武器商附近。', `MaleText_loc7`='Encontrarás al herrero y a su ayudante en su taller del Bancal de Guerrero, cerca de los vendedores de armaduras y armas.', `FemaleText_loc1`='대장장이와 그의 조수는 전사의 정원에서 찾으실 수 있습니다. 무기 및 방어구 상인 근처에 있지요.', `FemaleText_loc4`='你可以在战士区找到铁匠和他的助手，就在护甲和武器供应商附近。', `FemaleText_loc5`='鐵匠和助手們在戰士區的護甲商及武器商附近。', `FemaleText_loc7`='Encontrarás al herrero y a su ayudante en su taller del Bancal de Guerrero, cerca de los vendedores de armaduras y armas.' WHERE `ID`=51341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 설원호랑이가 사냥 기술을 시험해보려고 공중에 열심히 물기와 앞발질을 합니다.', `MaleText_loc4`='幼崽向空中挥动着它的小爪子，看来他已经迫不及待想试试他的打猎技巧了。', `MaleText_loc5`='你的小小幼獸對著空中張牙舞爪，急著想試試看牠狩獵的技巧。', `MaleText_loc7`='Tu pequeño cachorro da mordiscos y agita la garra en el aire, ansioso por poner a prueba sus habilidades de caza.' WHERE `ID`=51342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 설원호랑이가 당신의 손을 킁킁거리며 냄새를 맡은 뒤 위협적인 존재가 아니라고 생각합니다... 지금은 말이죠.', `MaleText_loc4`='幼崽闻了闻你的手，觉得你暂时不是个威胁。', `MaleText_loc5`='這隻幼獸聞了聞你的手，認為你這次...沒有敵意。', `MaleText_loc7`='El cachorro te olisquea y decide que no eres una amenaza... por ahora.' WHERE `ID`=51343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다행히 길니아스의 기술자 하나가 장인의 정원에서 일하고 있지요. 그녀가 당신을 도와줄 수 있을 겁니다.', `MaleText_loc4`='起码还有一个吉尔尼斯工程师在工匠区工作，她应该能帮上你。', `MaleText_loc5`='不管怎樣，在工匠區有一名吉爾尼斯工程師。她應該能幫上你的忙。', `MaleText_loc7`='Hay por lo menos una ingeniera gilneana que trabaja en el Bancal del Artesano. Ella debería poder ayudarte.', `FemaleText_loc1`='다행히 길니아스의 기술자 하나가 장인의 정원에서 일하고 있지요. 그녀가 당신을 도와줄 수 있을 겁니다.', `FemaleText_loc4`='起码还有一个吉尔尼斯工程师在工匠区工作，她应该能帮上你。', `FemaleText_loc5`='不管怎樣，在工匠區有一名吉爾尼斯工程師。她應該能幫上你的忙。', `FemaleText_loc7`='Hay por lo menos una ingeniera gilneana que trabaja en el Bancal del Artesano. Ella debería poder ayudarte.' WHERE `ID`=51344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 장인의 정원에 있는 실버듀 부부를 찾으시는군요. 최근 마법부여용품점 근처에 상점을 차렸답니다.', `MaleText_loc4`='你是要找工匠区的银露一家人吗？他们最近才在附魔商店附近开起了自己的小店。', `MaleText_loc5`='喔，你可以去找工匠區的銀露一家人。他們最近在附魔師附近開了家店舖。', `MaleText_loc7`='Ah, buscas a los Alboradanívea en el Bancal del Artesano. Acaban de abrir su tienda cerca de la del encantador.', `FemaleText_loc1`='아, 장인의 정원에 있는 실버듀 부부를 찾으시는군요. 최근 마법부여용품점 근처에 상점을 차렸답니다.', `FemaleText_loc4`='你是要找工匠区的银露一家人吗？他们最近才在附魔商店附近开起了自己的小店。', `FemaleText_loc5`='喔，你可以去找工匠區的銀露一家人。他們最近在附魔師附近開了家店舖。', `FemaleText_loc7`='Ah, buscas a los Alboradanívea, en el Bancal del Artesano. Acaban de abrir su tienda cerca de la del encantador.' WHERE `ID`=51345;
