UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노련한 광부 두 명이 역병에 뒤덮인 길니아스에서 도망쳐 여기 정착했지요. 장인의 정원에서 만나실 수 있을 겁니다.', `MaleText_loc4`='有二个熟练的矿工从吉尔尼斯瘟疫中成功逃了出来，来到这里，你可以在工匠区找到他们。', `MaleText_loc5`='有兩名技巧純熟的礦工從瘟疫蔓延的吉爾尼斯成功逃來此地。你可以在工匠區找到他們。', `MaleText_loc7`='Un par de mineros expertos huyeron de Gilneas, asolada por la peste, y consiguieron llegar aquí. Los encontrarás en el Bancal del Artesano.', `FemaleText_loc1`='노련한 광부 두 명이 역병에 뒤덮인 길니아스에서 도망쳐 여기 정착했지요. 장인의 정원에서 만나실 수 있을 겁니다.', `FemaleText_loc4`='有二个熟练的矿工从吉尔尼斯瘟疫中成功逃了出来，来到这里，你可以在工匠区找到他们。', `FemaleText_loc5`='有兩名技巧純熟的礦工從瘟疫蔓延的吉爾尼斯成功逃來此地。你可以在工匠區找到他們。', `FemaleText_loc7`='Un par de mineros expertos huyeron de Gilneas, asolada por la peste, y consiguieron llegar aquí. Los encontrarás en el Bancal del Artesano.' WHERE `ID`=51349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀라가조르가 도망치기 시작합니다!', `MaleText_loc4`='米拉盖佐尔开始逃跑！', `MaleText_loc5`='密拉加卓開始逃跑!', `MaleText_loc7`='¡Millagazor empieza a escapar!' WHERE `ID`=51350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 같은 성가신 녀석들에게 내 시간을 할애할 가치가 없다!', `MaleText_loc4`='你们这些家伙真是在浪费我的时间！', `MaleText_loc5`='你們這些討人厭的害蟲不值得我浪費時間!', `MaleText_loc7`='¡Tus bichos no merecen que pierda mi tiempo con ellos!' WHERE `ID`=51351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 밀라가조르 님을 소환한 거냐?', `MaleText_loc4`='是谁召唤米拉盖佐尔？', `MaleText_loc5`='是誰召喚密拉加卓的?', `MaleText_loc7`='¿Quién invoca a Millagazor?' WHERE `ID`=51352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 승강기와 풍차를 관리하는 페일후프를 찾으시는 게로군요. 썬더 블러프 봉우리 하층으로 가보십시오.', `MaleText_loc4`='你一定是在寻找苍蹄，他把升降梯和风车维护得井井有条。你可以在中部高地下层找到他。', `MaleText_loc5`='你在找的一定是白蹄，他一直在維持升降梯和風車的正常運作。去中部高地找他吧。', `MaleText_loc7`='Buscas a Pezuña Pálida, el que se ocupa del mantenimiento de nuestros ascensores y molinos. Lo encontrarás en la Pequeña Pendiente.', `FemaleText_loc1`='우리 승강기와 풍차를 관리하는 페일후프를 찾으시는 게로군요. 썬더 블러프 봉우리 하층으로 가보십시오.', `FemaleText_loc4`='你一定是在寻找苍蹄，他把升降梯和风车维护得井井有条。你可以在中部高地下层找到他。', `FemaleText_loc5`='你在找的一定是白蹄，他一直在維持升降梯和風車的正常運作。去中部高地找他吧。', `FemaleText_loc7`='Buscas a Pezuña Pálida, el que se ocupa del mantenimiento de nuestros ascensores y molinos. Lo encontrarás en la Pequeña Pendiente.' WHERE `ID`=51353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프 봉우리 하층에서 클라우드체이서 부부를 찾아보십시오. 보석세공에 대한 거라면 뭐든지 그들이 도와줄 겁니다.', `MaleText_loc4`='到中部高地的底层寻找追云者，他们可以就珠宝加工方面的事宜为你提供帮助。', `MaleText_loc5`='到中部高地去找逐雲者他們。那些人應該有辦法幫你解決所有珠寶設計的相關問題。', `MaleText_loc7`='Busca a los Cazanubes en la Pequeña Pendiente. Ellos deberían ser capaces de ayudarte con todo lo relacionado con la joyería.', `FemaleText_loc1`='썬더 블러프 봉우리 하층에서 클라우드체이서 부부를 찾아보십시오. 보석세공에 대한 거라면 뭐든지 그들이 도와줄 겁니다.', `FemaleText_loc4`='到中部高地的底层寻找追云者，他们可以就珠宝加工方面的事宜为你提供帮助。', `FemaleText_loc5`='到中部高地去找逐雲者他們。那些人應該有辦法幫你解決所有珠寶設計的相關問題。', `FemaleText_loc7`='Busca a los Cazanubes en la Pequeña Pendiente. Ellos deberían ser capaces de ayudarte con todo lo relacionado con la joyería.' WHERE `ID`=51354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린이 이런 걸 타는 걸 본 적이 있어요. 무진장 빠르던데요!', `MaleText_loc4`='我见过地精驾驶这些东西。我知道他们可以更快的！', `MaleText_loc5`='我看過哥布林駕駛這些玩意兒。我知道他們的速度可以更快!', `MaleText_loc7`='He visto cómo los goblins montan estas cosas. ¡Sé que pueden ir más rápido!' WHERE `ID`=51355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 단추는 어디에 쓰는 건지 궁금하네요...', `MaleText_loc4`='很好奇这按钮是干吗的……', `MaleText_loc5`='不知道這顆按鈕是幹嘛用的...', `MaleText_loc7`='Me pregunto para qué sirve este botón...' WHERE `ID`=51356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 바로 이거죠!', `MaleText_loc4`='这才像话嘛！', `MaleText_loc5`='現在這樣還差不多!', `MaleText_loc7`='¡ESTO me gusta más!' WHERE `ID`=51357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 로켓을 다루는지 알았어요. 저한테 맡겨 두시라고요!', `MaleText_loc4`='我知道是怎么回事了，我来控制！', `MaleText_loc5`='我弄懂這是怎麼運作的了。我正在控制這玩意兒!', `MaleText_loc7`='He averiguado cómo funciona. ¡Tomo el control!' WHERE `ID`=51358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 머리에 쓴 거 꽉 잡으세요!', `MaleText_loc4`='抓紧你的……头盔！', `MaleText_loc5`='抓緊你的...呃...頭盔!', `MaleText_loc7`='¡Agárrate a tu, eh... casco!' WHERE `ID`=51359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 로켓아, 이리 가면 안 돼!', `MaleText_loc4`='不，火箭！不要往那飞！', `MaleText_loc5`='不，火箭!別往那個方向!', `MaleText_loc7`='¡No, cohete! ¡No vayas por ahí!' WHERE `ID`=51360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엑, 큰일 났다!', `MaleText_loc4`='我就要失去控制了！', `MaleText_loc5`='我無法控制它了!', `MaleText_loc7`='¡Estoy perdiendo el control!' WHERE `ID`=51361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 눌러본 단추가 딱 하나 있는데... 한번 눌러 볼까요?!', `MaleText_loc4`='这有这个按钮我还没按过了，让我们按下去试试吧！', `MaleText_loc5`='這是唯一一個我沒碰過的按鈕了。來試試看吧!', `MaleText_loc7`='Este es el único botón que no he pulsado aún. ¡Probémoslo!' WHERE `ID`=51362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 이상한 일이 벌어지고 있습니다. 브웸바, 도와주실 수 있으십니까?', `MaleText_loc4`='这儿发生了些不寻常的事情，布温巴。你能来帮忙吗？', `MaleText_loc5`='布恩巴，發生了些不太尋常的事情。你能幫個忙嗎?', `MaleText_loc7`='Está ocurriendo algo que no es natural, Bwemba. ¿Puedes ayudar?', `FemaleText_loc1`='무언가 이상한 일이 벌어지고 있어요. 브웸바, 도와주실 수 있으세요?', `FemaleText_loc4`='这儿发生了些不寻常的事情，布温巴。你能来帮忙吗？', `FemaleText_loc5`='布恩巴，發生了些不太尋常的事情。你能幫個忙嗎?', `FemaleText_loc7`='Está ocurriendo algo que no es natural, Bwemba. ¿Puedes ayudar?' WHERE `ID`=51363;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들과 이야기하고 싶으십니까? 어디 한번 해 봅시다...', `FemaleText_loc4`='你想要和灵魂谈话？好吧，让我们看看行不行……', `FemaleText_loc5`='你要來談談那些靈魂的問題嗎?好呀，讓我們來看看能做些什麼...', `FemaleText_loc7`='¿Quieres hablar con los eh''píritus? Bueno, veamos qué podemos hacer...' WHERE `ID`=51364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비상 단추를 찾은 것 같아요. 로켓엔 비상 단추가 달려 있는 거 맞죠?', `MaleText_loc4`='我想我找到了应急按钮。火箭都有这样的按钮，没错吧？', `MaleText_loc5`='我想我找到緊急按鈕了。火箭應該都有這種按鈕吧，對不對?', `MaleText_loc7`='Creo que he encontrado el botón de emergencia. Los cohetes suelen tener botones de esos, ¿no?' WHERE `ID`=51365;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우선 당신이 브웸바의 손이 되어 도와줘야 합니다... 야영지 중앙에 있는 화톳불에 나무토막을 몇 개 던져 넣어 주십시오. 그러면 브웸바가 나머지 일을 맡겠습니다.', `FemaleText_loc4`='你需要成为布温巴的双手……我需要你去扔一些木棍到营地中央的火堆里。剩下的就交给布温巴处理。', `FemaleText_loc5`='你要幫布恩巴處理此事...我要你丟點木材到營地中央的營火裡。剩下的布恩巴會去處理。', `FemaleText_loc7`='Tendrás que ser las manos de Bwemba... Necesito que lances palos a la hoguera que hay en el centro del campamento. Deh''pués, Bwemba se encargará del reh''to.' WHERE `ID`=51366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마우리가 죽자 가마솥을 보호하던 힘이 사라집니다!', `FemaleText_loc4`='玛乌里的死亡移除了附近坩埚受到的保护！', `FemaleText_loc5`='莫里死後，附近大鍋的防護也隨之消失了!', `FemaleText_loc7`='¡La muerte de Mauri ha eliminado las protecciones de un caldero cercano!' WHERE `ID`=51367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트쿨루가 죽자 가마솥을 보호하던 힘이 사라집니다!', `MaleText_loc4`='提库鲁的死亡移除了附近坩埚受到的保护！', `MaleText_loc5`='堤庫魯死後，附近大鍋的防護也隨之消失了!', `MaleText_loc7`='¡La muerte de T''kulu ha eliminado las protecciones de un caldero cercano!' WHERE `ID`=51368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 재미있을 거예요!', `MaleText_loc4`='这一定会很有趣！', `MaleText_loc5`='這一定會很有趣!', `MaleText_loc7`='¡Esto será divertido!' WHERE `ID`=51369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 해냈어요! 우리 로켓을 로켓길로 돌려놨다고요!', `MaleText_loc4`='成功了！我成功让我们回到正轨上来了！', `MaleText_loc5`='成功了!我們回到道路上了!', `MaleText_loc7`='¡Lo he conseguido! ¡He conseguido que recuperemos el rumbo!' WHERE `ID`=51370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폴짝폴짝 뛰어 잿그물 애거미를 떨쳐내십시오!', `MaleText_loc4`='跳起来甩掉燃灰幼蛛！', `MaleText_loc5`='跳起來甩掉小蜘蛛!', `MaleText_loc7`='¡Salta para librarte de las arañas carboncillo!' WHERE `ID`=51371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 진짜 밴시 여왕님이세요? 훨씬 더 키가 크실 줄 알았는데!', `MaleText_loc4`='哇，你就是女妖之王？我还以为你会更高的呢！', `MaleText_loc5`='哇，那你就是女妖之王囉?我還以為你會再高一點呢!', `MaleText_loc7`='Vaya, ¿así que tú eres la Reina alma en pena? ¡Esperaba que fueras más alta!' WHERE `ID`=51372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 그러는데 여왕님이랑 대족장님이랑 싸우셨고, 그래서 여왕님이 호드를 버릴 거래요. 진짜 그러실 건가요?', `MaleText_loc4`='大家都说你和酋长起了争执，将要抛弃部落。那是真的吗？', `MaleText_loc5`='大家都說你和大酋長打了一架，你要拋棄部落。真的嗎?', `MaleText_loc7`='Todo el mundo dice que te has peleado con el Jefe de Guerra y que vas a abandonar la Horda. ¿Es cierto?' WHERE `ID`=51373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 대신해 나서줄 필요는 없소, 사절이여. 아이야, 대족장에게도 이야기했지만, 호드에 대한 내 충성심은 변한 적이 없다.', `FemaleText_loc4`='我无须辩护，大使。年轻人，就跟我告诉酋长的一样，我的忠诚从来没动摇过。', `FemaleText_loc5`='大使，我並不需要辯護什麼。年輕人，就如同我對大酋長說過的一樣，我的忠誠是無可置疑的。', `FemaleText_loc7`='No necesito que me defienda nadie, embajador. Joven, como ya le he dicho al Jefe de Guerra, nunca se debe poner en duda mi lealtad.' WHERE `ID`=51374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드는 의지할 곳 없던 우리를 받아들여 주었지. 그리고 우리 포세이큰은 절대로 빚을 잊지 않는다...', `FemaleText_loc4`='我们永远不会忘记，在我们被遗忘者孤立无援的时候，部落张开双臂欢迎了我们。', `FemaleText_loc5`='在我們孤立無依的時候，部落展開雙手接受我們，被遺忘者絕對不會忘記這份恩情...', `FemaleText_loc7`='La Horda dio la bienvenida a mi gente cuando estábamos solos y los Renegados nunca olvidamos una deuda...' WHERE `ID`=51375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬와 나는 언제나 호드를 위해 최선의 행동을 할 것이다.', `FemaleText_loc4`='加尔鲁什和我会一直做出最有利于我们人民的决定。', `FemaleText_loc5`='我和卡爾洛斯的所作所為一直都是為了我們子民好。', `FemaleText_loc7`='Garrosh y yo siempre haremos lo que sea mejor para nuestro pueblo.' WHERE `ID`=51376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 사람들 얘긴 사실이 아니군요? 와, 정말 다행이다! 여왕님 같은 분이랑 적이 되는 건 생각하기도 싫어요, 여군주 실바나스 님.', `MaleText_loc4`='所以说那不是真的？感谢先祖！我可不希望做你的敌人，希尔瓦娜斯女士。', `MaleText_loc5`='所以這不是真的囉?感謝先祖!我不希望你成為我的敵人，希瓦娜斯女士。', `MaleText_loc7`='¿Así que no es cierto? ¡Gracias a los ancestros! No me gustaría tenerte como enemiga, Lady Sylvanas.' WHERE `ID`=51377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제도 모르는 어린애 같으니! 지금 네 앞에 선 분이 누군지 알고나 있는 게냐?', `MaleText_loc4`='别得意忘形，小孩！你知道你面前是谁吗？', `MaleText_loc5`='別搞不清楚自己是誰，孩子!你知道站在你面前的人是誰嗎?', `MaleText_loc7`='¡Cuida tus modales, niño! ¿Acaso no sabes ante quién te encuentras?' WHERE `ID`=51378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 악력이 약해집니다! 빨리 나무에서 내려오십시오!', `MaleText_loc4`='你已经快抓不住了！快从树上下来！', `MaleText_loc5`='你快要抓不牢了!快爬下樹!', `MaleText_loc7`='¡Estás a punto de soltarte! ¡Bájate del árbol, rápido!', `FemaleText_loc1`='당신의 악력이 약해집니다! 빨리 나무에서 내려오십시오!', `FemaleText_loc4`='你已经快抓不住了！快从树上下来！', `FemaleText_loc5`='你快要抓不牢了!快爬下樹!', `FemaleText_loc7`='¡Estás a punto de soltarte! ¡Bájate del árbol, rápido!' WHERE `ID`=51379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 똬리가 풀리는구나...', `MaleText_loc4`='从尘世的桎梏中解脱……', `MaleText_loc5`='血肉之軀已潰散...', `MaleText_loc7`='La espiral mortal ssse dessspliega...' WHERE `ID`=51380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 제물로 바쳐 그분을 기쁘게 하리라.', `MaleText_loc4`='拿你当祭品……取悦他……', `MaleText_loc5`='你的犧牲可取悅他。', `MaleText_loc7`='Tu sssacrificio lo satisssface.' WHERE `ID`=51381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 똬리가 너희를 휘감으리라!', `MaleText_loc4`='死亡将缠绕你的灵魂！', `MaleText_loc5`='讓死亡的纏繞包圍吧!', `MaleText_loc7`='¡Que la espiral de muerte se desssate!' WHERE `ID`=51382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽는다고... 달라지는 건... 없다...', `MaleText_loc4`='我的死……微不足道……', `MaleText_loc5`='我的死亡...不算什麼...', `MaleText_loc7`='Mi muerte no sssignifica... nada...' WHERE `ID`=51383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하, 여기 좀 보게, 친구!$b$b그립타가 다시 돌아왔다고! 새 상점에 새 상품을 쫙 깔고 장사할 준비를 마쳤지!$b$b더 나아지고, 강해지고, 빨라지고 싶나? 여기 있는 목걸이를 쓰면 그렇게 되지. 검증된 작품이야! 어서 와서 가격까지 착한 기적의 목걸이 하나 사게! 내 반값에 주지!', `MaleText_loc4`='啊哈哈，大家听好了！$b$b格里伏塔又回来啦！新的摊位，崭新的商品，已经做好再次开张的万全准备啦！$b$b你想变得更快、更高、更强吗？我卖的每一个护身符都绝对有效！过来买一个神奇的小玩意吧！性价比超乎想象！', `MaleText_loc5`='啊哈，照過來照過來，老兄!$b$b格利夫塔又回來啦!嶄新的攤位，全新的貨品，隨時任君選購!$b$b想要變得更棒、更強、更快?在這每個護符都保證能提供你想要的效果。快靠過來看看唷!絕對物超所值!', `MaleText_loc7`='¡Ajajaja, aquí me tienes todo pa'' ti, colega!$b$b¡Griftah ha vuelto! Nuevo pueh''to, mercancía totalmente novedosa y dih''pueh''to a ofreceh''te las mejores ofeh''tas!$b$b¿Quieres ser mejor, más fueh''te, más rápido? Te garantizo que eh''tos amuletos hacen juh''to lo que yo digo que hacen. ¡Adelante, compra uno de eh''tos adornos! ¡Bueno, bonito y barato!' WHERE `ID`=51384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤이 끝없이 몰려옵니다, $c님.', `MaleText_loc4`='这些巨魔没完没了，$c。', `MaleText_loc5`='這些食人妖好像殺不完一樣，$c。', `MaleText_loc7`='Esos trols no se acaban, $c.' WHERE `ID`=51385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리핀을 타고 발굴현장으로 갈 수 있습니까?', `MaleText_loc4`='你的狮鹫可以送我到挖掘场吗？', `MaleText_loc5`='可以請你派一隻獅鷲獸送我去挖掘場嗎?', `MaleText_loc7`='¿Alguno de tus grifos puede llevarme a la Excavación?', `FemaleText_loc1`='그리핀을 타고 발굴현장으로 갈 수 있나요?', `FemaleText_loc4`='你的狮鹫可以送我到挖掘场吗？', `FemaleText_loc5`='可以請你派一隻獅鷲獸送我去挖掘場嗎?', `FemaleText_loc7`='¿Alguno de tus grifos puede llevarme a la Excavación?' WHERE `ID`=51386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 감사합니다.', `MaleText_loc4`='感谢你，朋友。', `MaleText_loc5`='感謝你，朋友。', `MaleText_loc7`='Te doy las gracias.', `FemaleText_loc1`='친구여, 감사해요.', `FemaleText_loc4`='感谢你，朋友。', `FemaleText_loc5`='感謝你，朋友。', `FemaleText_loc7`='Te doy las gracias.' WHERE `ID`=51387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 전초기지로 돌아가는 길에 거미를 조금 처치하겠습니다.', `MaleText_loc4`='谢谢你。我一定要在回营地的路上顺手干掉几只蜘蛛。', `MaleText_loc5`='謝謝你。我會在回營地的路上多殺幾隻蜘蛛的。', `MaleText_loc7`='Gracias. Me aseguraré de matar unas cuantas arañas de camino de vuelta al campamento.', `FemaleText_loc1`='감사해요. 전초기지로 돌아가는 길에 거미를 조금 처치할게요.', `FemaleText_loc4`='谢谢你。我一定要在回营地的路上顺手干掉几只蜘蛛。', `FemaleText_loc5`='謝謝你。我會在回營地的路上多殺幾隻蜘蛛的。', `FemaleText_loc7`='Gracias. Me aseguraré de matar unas cuantas arañas de camino de vuelta al campamento.' WHERE `ID`=51388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고치 안은 정말이지 끔찍했습니다.', `MaleText_loc4`='你可不会想知道关在这里是什么感觉。', `MaleText_loc5`='你不會想知道那裡的情況。', `MaleText_loc7`='No quieres saber cómo era esto antes.', `FemaleText_loc1`='고치 안은 정말이지 끔찍했어요.', `FemaleText_loc4`='你可不会想知道关在这里是什么感觉。', `FemaleText_loc5`='你不會想知道那裡的情況。', `FemaleText_loc7`='No quieres saber cómo era esto antes.' WHERE `ID`=51389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사합니다. 끝장이라고 생각했거든요.', `MaleText_loc4`='谢谢你救了我。我还以为自己死定了呢。', `MaleText_loc5`='謝謝你救了我。我以為我完蛋了。', `MaleText_loc7`='Gracias por liberarme. Creía que había llegado mi fin.', `FemaleText_loc1`='구해주셔서 감사해요. 끝장이라고 생각했답니다.', `FemaleText_loc4`='谢谢你救了我。我还以为自己死定了呢。', `FemaleText_loc5`='謝謝你救了我。我以為我完蛋了。', `FemaleText_loc7`='Gracias por liberarme. Creía que había llegado mi fin.' WHERE `ID`=51390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼내주셔서 감사합니다! 정말 끔찍하기 그지없었습니다.', `MaleText_loc4`='谢谢你把我救出来！真是太可怕了。', `MaleText_loc5`='謝謝你把我救出來!那真是太可怕了。', `MaleText_loc7`='¡Gracias por sacarme de ahí! Ha sido horrible.', `FemaleText_loc1`='꺼내주셔서 감사해요! 정말 끔찍하기 그지없었답니다.', `FemaleText_loc4`='谢谢你把我救出来！真是太可怕了。', `FemaleText_loc5`='謝謝你把我救出來!那真是太可怕了。', `FemaleText_loc7`='¡Gracias por sacarme de ahí! Ha sido horrible.' WHERE `ID`=51391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끈... 끈적끈적하군요...', `MaleText_loc4`='好、好、好、好粘啊……', `MaleText_loc5`='黏...黏...黏答答...', `MaleText_loc7`='P-p-p-p-pegajoso...', `FemaleText_loc1`='끈... 끈적끈적해요...', `FemaleText_loc4`='好、好、好、好粘啊……', `FemaleText_loc5`='黏...黏...黏答答...', `FemaleText_loc7`='P-p-p-p-pegajoso...' WHERE `ID`=51392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 이제 화상을 좀 치료해야겠습니다...', `MaleText_loc4`='谢谢你！我要赶紧处理下这种烧灼感的后遗症……', `MaleText_loc5`='謝謝你!現在，來看看這種燃燒的感覺...', `MaleText_loc7`='¡Gracias! Ahora veamos ese escozor...', `FemaleText_loc1`='감사해요! 이제 화상을 좀 치료해야겠어요...', `FemaleText_loc4`='谢谢你！我要赶紧处理下这种烧灼感的后遗症……', `FemaleText_loc5`='謝謝你!現在，來看看這種燃燒的感覺...', `FemaleText_loc7`='¡Gracias! Ahora veamos ese escozor...' WHERE `ID`=51393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이제야 찾았군요! 당신을 찾아 온 정글을 헤맸습니다!', `FemaleText_loc4`='啊，你在这里！我们翻遍整个丛林在找你呢！', `FemaleText_loc5`='啊啊啊，原來在這!我們翻遍整座叢林就為了找你!', `FemaleText_loc7`='¡Aaaah! ¡Ahí eh''tás! ¡Hemos regih''trado toda la jungla para encontrah''te!' WHERE `ID`=51394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 도움을 받았지요. 잔달라의 계획에 따라 구루바시가 전쟁을 준비하고 있습니다.', `FemaleText_loc4`='任何帮助都是宝贵的。赞达拉的计划已经将古拉巴什推向了战争之路。', `FemaleText_loc5`='你們幫了大忙啦。贊達拉計畫要攻打古拉巴什。', `FemaleText_loc7`='La ayuda ha sido buena. El plan de los Zandalar ha colocado a los Gurubashi en el camino de la guerra.' WHERE `ID`=51395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 이렇게 잘 견디고 있는 건 아닙니다. 우리도 힘닿는 데까지 노력했지만 어려움이 많았습니다. 하지만 문제의 근원은 바로 줄구룹입니다.', `FemaleText_loc4`='不是所有地方联系都如此紧密。我们会尽力帮忙，但这一切的源头，是在祖尔格拉布。', `FemaleText_loc5`='並非每個環節都緊密結合在一起。我們會盡量提供協助。但是這一切的根源，存在祖爾格拉布之中。', `FemaleText_loc7`='No todos los lugares lo han sopoh''tado tan bien. Intentamos ayudar todo lo que pudimos. Pero el origen es Zul''Gurub.' WHERE `ID`=51396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마을을 지켜만 준다면, 보상은 충분히 해 줄 거야!', `MaleText_loc4`='如果你能确保我城镇的安全，我一定不会亏待你。', `MaleText_loc5`='如果你能保護我的城鎮安全，我一定會好好報答你的。', `MaleText_loc7`='Si puedes mantener segura la ciudad, haré que tus esfuerzos merezcan la pena.' WHERE `ID`=51397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다 브웸바. 잔달라를 막는 데 얼라이언스가 도움을 준다니 마음이 놓이는구나.', `MaleText_loc4`='干得好，布温巴。联盟竟然愿意帮忙阻止赞达拉，这实在太好了。', `MaleText_loc5`='幹得漂亮，布恩巴。很高興能看到聯盟願意伸出援手，一起阻止贊達拉。', `MaleText_loc7`='Buen trabajo, Bwemba. Me alegro de ver que hay miembros de la Alianza dipueh''tos a ayudar a detener a los Zandalar.' WHERE `ID`=51398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구루바시는 온갖 부두 주술을 사용하여 이 땅을 되찾으려 합니다.', `FemaleText_loc4`='为了夺回领土，古拉巴什不惜使用各种巫毒妖术。', `FemaleText_loc5`='古拉巴什用上了各種巫毒力量想要奪回這片土地。', `FemaleText_loc7`='Los Gurubashi utilizarán todo tipo de vudú pa'' reclamar su tierra.' WHERE `ID`=51399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔질!', `FemaleText_loc4`='赞吉尔！', `FemaleText_loc5`='贊吉爾!', `FemaleText_loc7`='¡Zanzil!' WHERE `ID`=51400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줄 사람을 데려왔군.', `MaleText_loc4`='看来你确实可以找来援助。', `MaleText_loc5`='我想你需要幫忙。', `MaleText_loc7`='Me alegro de que hayas podido conseguir ayuda.' WHERE `ID`=51401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알고 있다. 그래서 내가 모두에게 경고하려고 돌아다닌 거야. 검은창 트롤의 지도자가 직접 말을 하면, 호드와 얼라이언스 모두 귀를 기울이지.', `MaleText_loc4`='我知道。那正是我四处奔波的原因：警告所有人。暗矛部族的领袖亲自发言时，所有人都会认真听，无论是部落还是联盟。', `MaleText_loc5`='是的沒錯，這就是為什麼我四處奔走，警告大家。當暗矛部族的領袖講話時，大家都要專心聽，不管是部落還是聯盟都一樣。', `MaleText_loc7`='Lo sé. Por eso me fui, pa'' avisar a todo el mundo. Cuando el líder de los Lanza Negra habla, todos escuchan, tanto la Horda como la Alianza.' WHERE `ID`=51402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 이제 줄구룹으로 가자. 이 반란을 뿌리째 뽑아버려야겠어.', `MaleText_loc4`='那将是我们下一步应当去的地方，我们必须在源头遏止这次暴动。', `MaleText_loc5`='那麼，接下來要去的地方就是那裡了。我們會在他們的起源地阻止一切。', `MaleText_loc7`='Entonces iremos ahí a continuación. Detendremos eh''te levantamiento en su origen.' WHERE `ID`=51403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 브웸바. 너와 네 친구는 검은창 트롤의 자랑거리다.', `MaleText_loc4`='干得好，布温巴。你和你的朋友让暗矛巨魔感到骄傲。', `MaleText_loc5`='幹得漂亮，布恩巴。暗矛部族以你和你的朋友為榮。', `MaleText_loc7`='Buen trabajo, Bwemba, tú y tu colega hacen que los Lanza Negra se sientan orgullosos.' WHERE `ID`=51404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 여기서 논의할 게 아직 남았습니다. 그 후에 줄구룹으로 가지요. 그곳에서 뵙겠습니다.', `MaleText_loc4`='我还需要留下讨论一些事情，之后我将前往祖尔格拉布，我们在那里见。', `MaleText_loc5`='我在這還有些事情要討論。之後我會動身前往祖爾格拉布。在那碰頭吧。', `MaleText_loc7`='Tengo que hablar de algunas cosas por aquí. Deh''pués, iré a Zul''Gurub. Te veré allí.' WHERE `ID`=51405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식을 통해 무엇이 소환되는지 한번 보십시오...', `FemaleText_loc4`='让我们看看布温巴召唤出了什么……', `FemaleText_loc5`='現在讓咱們來看看布恩巴召喚出什麼東西...', `FemaleText_loc7`='Veamos qué se ha sacado Bwemba de la manga...' WHERE `ID`=51406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문제가 아주 심각하군요. 베녹시스는 만만히 볼 상대가 아닙니다.', `FemaleText_loc4`='这可是严肃的事情，温诺希斯可不是喜欢开玩笑的人。', `FemaleText_loc5`='要正視這件事情的嚴重性。可不能小看溫諾希斯。', `FemaleText_loc7`='Eh''to es serio. No debemos subeh''timar a Venoxis.' WHERE `ID`=51407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 킬나라입니다. 그녀가 관련이 있을 줄 알았어야 했는데...', `FemaleText_loc4`='啊……是基尔娜拉。我就知道她与此有关。', `FemaleText_loc5`='啊...那一定是基爾娜拉。我早該想到她會介入才對。', `FemaleText_loc7`='Ah... es Kilnara. Debería haber sabido que eh''taría metida en eh''to.' WHERE `ID`=51408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿을 수가 없습니다... 혈군주 만도키르인가요? 좋지 않은 소식입니다...', `FemaleText_loc4`='我不敢相信我的眼睛……那是血领主曼多基尔吗？这可糟了……', `FemaleText_loc5`='我不相信我的雙眼...那是血領主曼多基爾嗎?看起來不太妙...', `FemaleText_loc7`='No creo lo que ven mis ojos... ¿Es ese el señor sangriento Mandokir? Eh''to tiene mala pinta...' WHERE `ID`=51409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구루바시 부족이 전력을 다해 쳐들어오는군요. 야영지 사람들을 도와줘야 합니다.', `FemaleText_loc4`='这些古拉巴什巨魔来真的了，我们必须帮助这些人。', `FemaleText_loc5`='這群古拉巴什食人妖可不好搞。我們得幫幫那些人。', `FemaleText_loc7`='Esos Gurubashi son cosa seria. Debemos ayudar a esa gente.' WHERE `ID`=51410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 가장 멀리 떨어진 플레이어를 향해 쇄도합니다!', `MaleText_loc4`='%s扑向最远的玩家！', `MaleText_loc5`='%s向距離最遠的玩家猛衝!', `MaleText_loc7`='¡%s se abalanza sobre el jugador más alejado!' WHERE `ID`=51411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프의 장로들이여, 나는 오늘 나의 아버지, 케른 블러드후프를 기리고자 조상님들 앞에 그대들을 불렀소.', `MaleText_loc4`='雷霆崖的长者们，我把大家召集到这里，是要在先祖的见证下祭拜我的父亲——凯恩·血蹄。', `MaleText_loc5`='雷霆崖的長者啊，在祖靈的注視下，你們回應我的呼喚聚集在此，對我的父親凱恩·血蹄表示敬意。', `MaleText_loc7`='Ancestros de Cima del Trueno, os he convocado bajo la mirada de los ancestros para honrar a mi padre, Cairne Pezuña de Sangre.' WHERE `ID`=51412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 아버지는 현명한 지도자이자 노련한 전사셨습니다. 그리고 당신을 따르는 이들을 위해 어떻게 하는 게 최선인지 언제나 고민하셨죠.', `MaleText_loc4`='父亲，您不但智勇双全，还懂得体恤人民。', `MaleText_loc5`='父親，你曾是英明的領導者，技巧純熟的戰士，所作所為都是為了子民的福祉。', `MaleText_loc7`='Padre, fuiste un hombre que guió a su gente con sabiduría, que luchó con habilidad y que siempre buscó lo mejor para su pueblo.' WHERE `ID`=51413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아서도 그리하셨듯, 아버지의 영혼이 계속 저희를 이끌어 주시길 바랍니다.', `MaleText_loc4`='愿您的灵魂如您身前一样继续指引我们，父亲。', `MaleText_loc5`='願你的靈魂能繼續指引我們，父親，就像你生前那樣引導我們。', `MaleText_loc7`='Que tu espíritu continúe guiándonos, padre, tal y como hiciste en vida.' WHERE `ID`=51414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 드루이드들이 변절한 오크들에게 공격받았을 때, 대부족장님께선 그들의 죽음에 대한 책임을 묻고자 대족장 가로쉬에게 결투를 신청하셨죠.', `MaleText_loc4`='当我和我的德鲁伊们遭到变节兽人的伏击，您向加尔鲁什酋长提出决斗来为死去的族人伸张正义，酋长。', `MaleText_loc5`='當背叛的獸人伏擊我和手下的德魯伊時，你在挑戰大酋長卡爾洛斯，以戰鬥來回應他們的死亡，酋長。', `MaleText_loc7`='Cuando mis druidas y yo caímos en la emboscada de los orcos renegados, desafiaste al Jefe de Guerra Garrosh a una prueba de combate para que respondiera por sus muertes, jefe.' WHERE `ID`=51415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께선 더없이 용감하게 싸우셨습니다, 대부족장님. 하지만 반역자 그림토템이 가로쉬의 무기에 독을 발라, 공정한 승부를 방해했죠.', `MaleText_loc4`='您战斗得十分英勇，酋长，但无奈恐怖图腾的叛徒在加尔鲁什的刀刃上下了毒，让决斗失去了公平。', `MaleText_loc5`='酋長，雖然你英勇地打了一場，不過詭詐的恐怖圖騰在卡爾洛斯的武器上塗毒，讓這場戰鬥失去了公平性。', `MaleText_loc7`='Luchaste con valor, jefe, pero a traición Tótem Siniestro envenenó el arma de Garrosh y te negó la posibilidad de tener un combate justo.' WHERE `ID`=51416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대부족장님의 영혼이 평안하시길 빕니다. 마가타와 그림토템 놈들은 도시에서 쫓겨났고, 훌륭한 아드님께서 대부족장님의 뜻을 이어가고 있습니다.', `MaleText_loc4`='愿您的灵魂安息。玛加萨和她的族人已经被驱逐出了城市，而您优秀的儿子将传承您的传说。', `MaleText_loc5`='願你的靈魂了解何謂平靜。瑪加薩和她那群人被趕出城，你優秀的兒子繼續著你的志業。', `MaleText_loc7`='Que tu espíritu descanse en paz. Magatha y su gente fueron expulsados de la ciudad y tu digno hijo continúa tu legado.' WHERE `ID`=51417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 그대를 안다, 케른 블러드후프여. 또한 그대의 백성이 우리에게 그대의 훌륭한 행동을 얘기해 주었다. 조상들은 그대를 두 팔 벌려 환영할 것이다.', `FemaleText_loc4`='我们熟知您，凯恩·血蹄。您的族人告诉了我们你的英勇事迹，而我们欢迎你进入祖先的归宿。', `FemaleText_loc5`='凱恩·血蹄，我們知道你的事蹟，你的子民告訴了我們。你在先祖之爐會受到款待的。', `FemaleText_loc7`='Nosotros te conocemos, Cairne Pezuña de Sangre; y tu pueblo nos ha hablado muchas veces de tus hazañas. Eres bienvenido en el hogar de los ancestros.' WHERE `ID`=51418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 대부족장님을 기리는군요!', `MaleText_loc4`='正该如此祭拜酋长！', `MaleText_loc5`='所以，就是這樣向酋長表示敬意!', `MaleText_loc7`='¡Así que así es como se honra a un jefe!' WHERE `ID`=51419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜드로의 꼬마 리치', `MaleText_loc4`='兰德鲁的小巫妖', `MaleText_loc5`='藍卓的小巫妖', `MaleText_loc7`='Exanimato de Landro', `FemaleText_loc1`='랜드로의 꼬마 리치', `FemaleText_loc4`='兰德鲁的小巫妖', `FemaleText_loc5`='藍卓的小巫妖', `FemaleText_loc7`='Exanimato de Landro' WHERE `ID`=51420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보의 금', `MaleText_loc4`='愚人的金子', `MaleText_loc5`='愚人的黃金', `MaleText_loc7`='Oro de tontos', `FemaleText_loc1`='바보의 금', `FemaleText_loc4`='愚人的金子', `FemaleText_loc5`='愚人的黃金', `FemaleText_loc7`='Oro de tontos' WHERE `ID`=51421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='솜씨가 나쁘지는 않군요, 용사여! 그대에 대해 그들이 말하던 게 틀린 말은 아니었습니다. 그렇지만 이제 여기서 각자의 길을 가야 합니다. 이 포로는... 제가 개인적으로 볼 일이 좀 있습니다.', `FemaleText_loc4`='不赖嘛，勇士！看来关于你传闻都是真的。不过我们得在这儿分道扬镳了。我得亲自处理这个囚犯……', `FemaleText_loc5`='還不賴，勇士!他們對你的評價沒錯。不過，我們還是得在這裡分開。我必須...親自解決這個囚犯。', `FemaleText_loc7`='¡No ha estado mal, campeón! Lo que dicen sobre ti es cierto. Sin embargo, debemos separarnos aquí. Debo ocuparme de este prisionero... personalmente.' WHERE `ID`=51422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야만 랩터 탈것', `MaleText_loc4`='野蛮迅猛龙坐骑', `MaleText_loc5`='兇蠻迅猛龍坐騎', `MaleText_loc7`='Montura de raptor salvaje', `FemaleText_loc1`='야만 랩터 탈것', `FemaleText_loc4`='野蛮迅猛龙坐骑', `FemaleText_loc5`='兇蠻迅猛龍坐騎', `FemaleText_loc7`='Montura de raptor salvaje' WHERE `ID`=51423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 밤호랑이', `MaleText_loc4`='夜刃豹幼崽', `MaleText_loc5`='夜刃豹寶寶', `MaleText_loc7`='Cachorro sable de la noche', `FemaleText_loc1`='새끼 밤호랑이', `FemaleText_loc4`='夜刃豹幼崽', `FemaleText_loc5`='夜刃豹寶寶', `FemaleText_loc7`='Cachorro sable de la noche' WHERE `ID`=51424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 역마 말뚝대', `MaleText_loc4`='战团马栓', `MaleText_loc5`='戰馬栓', `MaleText_loc7`='Amarradero de destacamento de guerra', `FemaleText_loc1`='전투 역마 말뚝대', `FemaleText_loc4`='战团马栓', `FemaleText_loc5`='戰馬栓', `FemaleText_loc7`='Amarradero de destacamento de guerra' WHERE `ID`=51425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 용매', `MaleText_loc4`='阿曼尼龙鹰', `MaleText_loc5`='阿曼尼龍鷹', `MaleText_loc7`='Dracohalcón Amani', `FemaleText_loc1`='아마니 용매', `FemaleText_loc4`='阿曼尼龙鹰', `FemaleText_loc5`='阿曼尼龍鷹', `FemaleText_loc7`='Dracohalcón Amani' WHERE `ID`=51426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리요! 적을 덫으로 유인하십시오!', `FemaleText_loc4`='快点！把敌人引到我的陷阱上！', `FemaleText_loc5`='快!把敵人誘進我的陷阱之中!', `FemaleText_loc7`='¡Rápido! ¡Atrae al enemigo hasta mi trampa!' WHERE `ID`=51427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령의 전쟁', `MaleText_loc4`='元素之战', `MaleText_loc5`='元素之戰', `MaleText_loc7`='Guerra de los elementos', `FemaleText_loc1`='정령의 전쟁', `FemaleText_loc4`='元素之战', `FemaleText_loc5`='元素之戰', `FemaleText_loc7`='Guerra de los elementos' WHERE `ID`=51428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용들의 황혼', `MaleText_loc4`='巨龙暮光', `MaleText_loc5`='龍之暮光', `MaleText_loc7`='Crepúsculo de los dragones', `FemaleText_loc1`='용들의 황혼', `FemaleText_loc4`='巨龙暮光', `FemaleText_loc5`='龍之暮光', `FemaleText_loc7`='Crepúsculo de los dragones' WHERE `ID`=51429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간만이 답해 주리라.', `MaleText_loc4`='时间会告诉我们。', `MaleText_loc5`='時間將證明一切。', `MaleText_loc7`='El tiempo lo dirá.' WHERE `ID`=51430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 비누에 도끼를 붙이는 건 어때요? 그럼 손잡이도 생기고 좋잖아요!', `MaleText_loc4`='不如……在斧头上擦点肥皂？这样就万事俱备啦！', `MaleText_loc5`='那這樣...把肥皂裝在斧頭上面如何?有了握把，那就沒問題啦!', `MaleText_loc7`='Y qué hay de... ¿poner jabón en un hacha? ¡De ese modo tendría mango y todo!' WHERE `ID`=51431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 비누를 다 쓰면 새 도끼가 생기는 거죠!', `MaleText_loc4`='当肥皂褪去的时候，你就会拥有一把崭新的斧头了！', `MaleText_loc5`='等肥皂沒了，你就有把新斧頭啦!', `MaleText_loc7`='¡Y cuando el jabón se gastara, tendrías un hacha nueva!' WHERE `ID`=51432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘들아, $n 님이 깜짝 선물을 사오셨단다! 이리 와서 선물을 구경하렴!', `FemaleText_loc4`='孩子们，$n给你们带来了惊喜！快过来看看你们的礼物是什么！', `FemaleText_loc5`='孩子們，$n為你們帶來了驚喜!快來看看你的禮物吧!', `FemaleText_loc7`='¡Niños, $n tiene una sorpresa para ustedes! ¡Vengan por su regalo!' WHERE `ID`=51433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 멋있지? 난 대족장 가로쉬다!', `MaleText_loc4`='快看我，我是加尔鲁什酋长！', `MaleText_loc5`='你看，我是大酋長卡爾洛斯!', `MaleText_loc7`='¡Miradme, soy el Jefe de Guerra Garrosh!', `FemaleText_loc1`='나 멋있지? 난 대족장 가로쉬다!', `FemaleText_loc4`='快看我，我是加尔鲁什酋长！', `FemaleText_loc5`='你看，我是大酋長卡爾洛斯!', `FemaleText_loc7`='¡Miradme, soy el Jefe de Guerra Garrosh!' WHERE `ID`=51434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뱀에게서 도망친다고 해도, 표범한테 당할 거야!', `MaleText_loc4`='就算毒蛇不弄死我们，猎豹也会杀死我们的！', `MaleText_loc5`='就算我們沒被蛇咬死，也會被獵豹殺死!', `MaleText_loc7`='¡Si las serpientes no nos matan, la pantera lo hará!' WHERE `ID`=51435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 눈... 놈의 눈이 머리에서 떠나지 않아!', `MaleText_loc4`='那眼睛……在我脑海中挥之不去！', `MaleText_loc5`='那雙眼...我無法克制自己不去想它的眼睛!', `MaleText_loc7`='Los ojos... ¡No puedo dejar de pensar en sus ojos!' WHERE `ID`=51436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬잇 소리가 멈추지 않아. 독사가 계속 쏟아져 나온다고!', `MaleText_loc4`='那嘶嘶声片刻未停，毒蛇不停地涌来！', `MaleText_loc5`='嘶嘶聲一直沒停過。那些蛇一直湧上來!', `MaleText_loc7`='El silbido no cesa nunca. ¡Las serpientes se acercan!' WHERE `ID`=51437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 곳이 없어!', `MaleText_loc4`='没有地方躲啦！', `MaleText_loc5`='沒有安全的地方可躲啦!', `MaleText_loc7`='¡No hay ningún sitio seguro en el que esconderse!' WHERE `ID`=51438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표범이 우릴 쫓고 있으니까, 한곳에 머무르는 건 좋은 생각이 아니야. 어서 떠나야 해!', `MaleText_loc4`='猎豹正在追捕我们，停留在一个地方可不是个好主意。我们必须得离开了！', `MaleText_loc5`='這隻獵豹正在追捕我們，停留在原地可不是個好主意。我們得離開才行!', `MaleText_loc7`='La pantera nos persigue, no es buena idea quedarse quietos en un sitio. ¡Tenemos que marcharnos!' WHERE `ID`=51439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 죽을거야...', `MaleText_loc4`='我们完了……', `MaleText_loc5`='我們完蛋了!', `MaleText_loc7`='Estamos perdidos...' WHERE `ID`=51440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 많은 사냥꾼이 저 괴물의 먹이가 되었다고...', `MaleText_loc4`='那只野兽捕获了那么多猎手……', `MaleText_loc5`='有好多好多獵人反被那隻野獸獵殺...', `MaleText_loc7`='Esa bestia ha matado a tantos cazadores...' WHERE `ID`=51441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정글이 우리 모두의 무덤이 될 거야.', `MaleText_loc4`='这个丛林就将是我们的葬身之处。', `MaleText_loc5`='我們全都會死在這座叢林。', `MaleText_loc7`='Esta jungla será el fin de todos nosotros.' WHERE `ID`=51442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈의 눈이 머리에서 떠나질 않습니다...', `MaleText_loc4`='我脑海里都是那眼睛……', `MaleText_loc5`='我沒辦法把那些眼睛從我腦海中甩開...', `MaleText_loc7`='No puedo sacarme esos ojos de la cabeza...', `FemaleText_loc1`='놈의 눈이 머리에서 떠나질 않아요...', `FemaleText_loc4`='我脑海里都是那眼睛……', `FemaleText_loc5`='我沒辦法把那些眼睛從我腦海中甩開...', `FemaleText_loc7`='No puedo sacarme esos ojos de la cabeza...' WHERE `ID`=51443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모티가 여전히 돌아다닌다면, 차라리 이 독으로 죽음을 맞는 게 나을지도 모릅니다.', `MaleText_loc4`='我还是被毒死算了，因为玛乌提还活着。', `MaleText_loc5`='既然莫堤仍在這邊，讓牠中這個毒藥而死說不定會比較好。', `MaleText_loc7`='Ya que Mauti sigue por ahí, quizá sea mejor morir a causa de este veneno.', `FemaleText_loc1`='모티가 여전히 돌아다닌다면, 차라리 이 독으로 죽음을 맞는 게 나을지도 몰라요.', `FemaleText_loc4`='我还是被毒死算了，因为玛乌提还活着。', `FemaleText_loc5`='既然莫堤仍在這邊，讓牠中這個毒藥而死說不定會比較好。', `FemaleText_loc7`='Ya que Mauti sigue por ahí, quizá sea mejor morir a causa de este veneno.' WHERE `ID`=51444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 표범이 절 끌고 가게 내버려 두지 마십시오... 일이 그렇게 되면 차라리 절 끝내주십시오.', `MaleText_loc4`='别让猎豹把我拖走……那样的话我宁愿去死。', `MaleText_loc5`='別讓那隻獵豹把我拖走...如果情況真的變成那樣，那就送我上路吧。', `MaleText_loc7`='No dejes que esa pantera me arrastre... Si se da el caso, mátame antes.', `FemaleText_loc1`='그 표범이 절 끌고 가게 내버려 두지 마세요... 일이 그렇게 되면 차라리 절 끝내주세요.', `FemaleText_loc4`='别让猎豹把我拖走……那样的话我宁愿去死。', `FemaleText_loc5`='別讓那隻獵豹把我拖走...如果情況真的變成那樣，那就送我上路吧。', `FemaleText_loc7`='No dejes que esa pantera me arrastre... Si se da el caso, mátame antes.' WHERE `ID`=51445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모티를 추적할 수 있는 사람은 그렌트뿐입니다. 일단 그 표범을 처리하고 나면, 걱정할 건 독사뿐이겠군요.', `MaleText_loc4`='如果真有人可以追踪到玛乌提，那就一定是格伦特。一旦解决了那只猎豹，那我们就可以专心对付毒蛇了。', `MaleText_loc5`='如果說有誰能追捕莫堤，那就是袞特啦。只要把那隻獵豹處理掉，剩下要擔心的就只剩那群蛇了。', `MaleText_loc7`='Si alguien puede rastrear a Mauti, ese es Grent. Una vez nos ocupemos de la pantera, entonces lo único que tendremos que hacer es preocuparnos por las serpientes.', `FemaleText_loc1`='모티를 추적할 수 있는 사람은 그렌트뿐이에요. 일단 그 표범을 처리하고 나면, 걱정할 건 독사뿐이겠죠.', `FemaleText_loc4`='如果真有人可以追踪到玛乌提，那就一定是格伦特。一旦解决了那只猎豹，那我们就可以专心对付毒蛇了。', `FemaleText_loc5`='如果說有誰能追捕莫堤，那就是袞特啦。只要把那隻獵豹處理掉，剩下要擔心的就只剩那群蛇了。', `FemaleText_loc7`='Si alguien puede rastrear a Mauti, ese es Grent. Una vez nos ocupemos de la pantera, entonces lo único que tendremos que hacer es preocuparnos por las serpientes.' WHERE `ID`=51446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리 들었습니까? 저쪽에서 모티 소리가 난 것 같습니다...', `MaleText_loc4`='你听见了吗？我好像刚刚听到了那边有玛乌提的声音……', `MaleText_loc5`='聽到沒有?我想莫堤就在附近...', `MaleText_loc7`='¿Has oído eso? Creo que acabo de oír a Mauti por ahí...', `FemaleText_loc1`='저 소리 들으셨나요? 저쪽에서 모티 소리가 난 것 같아요...', `FemaleText_loc4`='你听见了吗？我好像刚刚听到了那边有玛乌提的声音……', `FemaleText_loc5`='聽到沒有?我想莫堤就在附近...', `FemaleText_loc7`='¿Has oído eso? Creo que acabo de oír a Mauti por ahí...' WHERE `ID`=51447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없이 몰려드는 독사와 거대한 표범이라니... 최악의 상황입니다.', `MaleText_loc4`='无穷无尽的毒蛇和一只巨型猎豹……情况不会比这更糟了。', `MaleText_loc5`='數不清的蛇群，巨大的獵豹...沒有比這更糟糕的了。', `MaleText_loc7`='Serpientes que no se acaban nunca y una pantera gigante... Las cosas no pueden ponerse peor...', `FemaleText_loc1`='끝없이 몰려드는 독사와 거대한 표범이라니... 최악의 상황이에요.', `FemaleText_loc4`='无穷无尽的毒蛇和一只巨型猎豹……情况不会比这更糟了。', `FemaleText_loc5`='數不清的蛇群，巨大的獵豹...沒有比這更糟糕的了。', `FemaleText_loc7`='Serpientes que no se acaban nunca y una pantera gigante... Las cosas no pueden ponerse peor...' WHERE `ID`=51448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모티가 우릴 보고 있는 게 느껴집니다. 다시 덤벼들 기회를 노리고 있겠지요.', `MaleText_loc4`='我能感觉到玛乌提注视着我们……它正在等待另一次偷袭我们的机会。', `MaleText_loc5`='我感覺得到，莫堤正在觀察我們...牠正靜候著一個發動突襲的良機。', `MaleText_loc7`='Siento que Mauti nos observa... A la espera del momento oportuno para saltar.', `FemaleText_loc1`='모티가 우릴 보고 있는 게 느껴져요. 다시 덤벼들 기회를 노리고 있겠지요.', `FemaleText_loc4`='我能感觉到玛乌提注视着我们……它正在等待另一次偷袭我们的机会。', `FemaleText_loc5`='我感覺得到，莫堤正在觀察我們...牠正靜候著一個發動突襲的良機。', `FemaleText_loc7`='Siento que Mauti nos observa... A la espera del momento oportuno para saltar.' WHERE `ID`=51449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독사 시체가 이렇게 많다니... 무두질을 계속 연마했다면 좋았을 텐데...', `MaleText_loc4`='好多死掉的毒蛇啊……如果我的剥皮技巧没荒废就好了……', `MaleText_loc5`='好多死蛇啊...如果我的剝皮技能夠高就好了...', `MaleText_loc7`='Tantas serpientes muertas... Si me hubiera mantenido al día con mi desuello...', `FemaleText_loc1`='독사 시체가 이렇게 많다니... 무두질을 계속 연마했다면 좋았겠어요...', `FemaleText_loc4`='好多死掉的毒蛇啊……如果我的剥皮技巧没荒废就好了……', `FemaleText_loc5`='好多死蛇啊...如果我的剝皮技能夠高就好了...', `FemaleText_loc7`='Tantas serpientes muertas... Si me hubiera mantenido al día con mi desuello...' WHERE `ID`=51450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우우와아아아!', `MaleText_loc4`='哇啊啊啊啊啊啊！', `MaleText_loc5`='哇喔!', `MaleText_loc7`='¡Guaaaaauuuu!' WHERE `ID`=51451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 만나서 반갑습니다. 우리가 진격하는 것을 도우러 오신 것입니까?', `FemaleText_loc4`='很高兴见到你，$n。你是来帮我们击退敌人的吧？', `FemaleText_loc5`='$n，很高興看到你。你是來幫我們推進前線的嗎?', `FemaleText_loc7`='$n, me alegro de verte. ¿Has venido para hacer avanzar el frente para nosotras?' WHERE `ID`=51452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정할 것 없다, 아이야. 그런 일이 벌어지지 않도록 대족장의 "감시자"들이 여기 와 있으니까.', `FemaleText_loc4`='你不用担心，孩子。酋长的“眼睛”在这里，他们会确保这点的。', `FemaleText_loc5`='不用擔心，孩子。大酋長手下的「觀察者」就是為了確保這件事情才會出現在這。', `FemaleText_loc7`='No te preocupes, joven. Los "observadores" del Jefe de Guerra han venido para asegurarse de eso.' WHERE `ID`=51453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령 군사들은 정말 가차 없군요. 놈들의 침입을 계속 버티기만 할 수는 없어요. 도움이 더 필요하겠어요.', `FemaleText_loc4`='元素大军无穷无尽。如果得不到援助的话，我们恐怕没办法守住这个突破口。', `FemaleText_loc5`='那些元素前仆後繼。我擔心我們無法守住這個突破口。除非有援軍來幫忙。', `FemaleText_loc7`='Las fuerzas elementales no se agotan. Me temo que no podremos aguantar la posición en esta brecha eternamente. Desde luego, no sin ayuda.' WHERE `ID`=51454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라일라가가 당신의 보잘것없는 울음에 기분이 상했습니다.', `MaleText_loc4`='你低劣的咆哮激怒了莱拉克斯。', `MaleText_loc5`='萊拉卡爾被你弱勢的嚎叫激怒了。', `MaleText_loc7`='Lylagar se siente ofendido por tu aullido inferior.' WHERE `ID`=51455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라일라가가 훌쩍거리며 불쌍하게 울음을 터뜨립니다.', `MaleText_loc4`='莱拉克斯发出了可怜的呜咽声。', `MaleText_loc5`='萊拉卡爾發出了可憐的悲鳴聲。', `MaleText_loc7`='Lylagar emite un gemido lastimero.' WHERE `ID`=51456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아에시나의 에메랄드를 사용하여 파이라크니스의 독을 씻어내십시오!', `MaleText_loc4`='快用艾森娜的翡翠净化你身上的派拉齐尼斯毒素！', `MaleText_loc5`='使用艾森娜翡翠來替你自己清除派拉奇尼斯的毒素!', `MaleText_loc7`='¡Usa la esmeralda de Aessina para eliminar el veneno de Piroaraña!' WHERE `ID`=51457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새끼 설원호랑이에게 좋은 집을 마련해줄 수 있기만 하다면야... 제가 한 마리 드릴 수도 있어요.', `FemaleText_loc4`='如果你发誓好好照顾它的话……我愿意忍痛割爱给你一只。', `FemaleText_loc5`='我是可以分你一隻啦...只要你發誓會給牠一個溫暖的家。', `FemaleText_loc7`='Podría dejarme convencer para que te lleves uno... SI prometes darle al cachorro un buen hogar.' WHERE `ID`=51458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하!? 얼빠진 자가 나타나셨군.', `FemaleText_loc4`='什么？！这是何等愚蠢？', `FemaleText_loc5`='這是在搞什麼鬼?', `FemaleText_loc7`='¿Qué? ¿Qué insensatez es esta?' WHERE `ID`=51459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어이, 거기! 지금 정신이 있는 겁니까?', `FemaleText_loc4`='那个家伙！你失去理智了吗？', `FemaleText_loc5`='喂!你已經失去理智了嗎?', `FemaleText_loc7`='¡Eh, tú! ¿Es que has perdido la razón?' WHERE `ID`=51460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='콜다라는 필멸자가 있을 곳이 아닙니다.', `FemaleText_loc4`='凡人可不该来考达拉。', `FemaleText_loc5`='現在凜懼島不適合凡人待著。', `FemaleText_loc7`='Gelidar ya no es un lugar para mortales.' WHERE `ID`=51461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목숨이 아깝거든, 당장 떠나십시오.', `FemaleText_loc4`='如果你珍惜生命，就马上离开。', `FemaleText_loc5`='如果你珍惜自己的生命就馬上離開。', `FemaleText_loc7`='Si valoras en algo tu vida, debes marcharte ya.' WHERE `ID`=51462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 힘없는 종족에게는 콜다라에 접근하는 것이 금지됐습니다.$b$b당신은 이곳에서 정말 심각한 위험에 빠져 있습니다.', `FemaleText_loc4`='考达拉已经严禁低等种族进入了，$c。$b$b你在这儿会有生命危险。', `FemaleText_loc5`='凜懼島已經禁止低等種族進入了，$c。$b$b你在這裡有生命危險。', `FemaleText_loc7`='Las razas menores tienen prohibida la entrada en Gelidar, $c.$b$bTu vida corre un grave peligro aquí.' WHERE `ID`=51463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 분출하며 용암기생충이 지상으로 쏟아져나옵니다!', `MaleText_loc4`='%s开始喷发了，大群熔岩寄生虫落在了地上！', `MaleText_loc5`='%s開始噴發，地上冒出了熔岩蟲!', `MaleText_loc7`='¡%s entra en erupción y lanza parásitos de lava al suelo!' WHERE `ID`=51464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리 말씀해 주십시오, 필멸의 존재여. 저보다 구분력이 떨어지는 다른 존재에게 발견되기 전에 말입니다.', `FemaleText_loc4`='有话快说，凡人，趁着其他人还没发现你。可不是人人都像我这么有耐心的。', `FemaleText_loc5`='快說吧，凡人，別的龍發現你可不像我這麼好說話了。', `FemaleText_loc7`='Habla rápido, moral, antes de que te descubra alguien más intransigente que yo.' WHERE `ID`=51465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증기 전차가 제대로 작동하게 관리하는 건 퍽 힘든 일이지만, 누군가는 꼭 해야 할 일이죠.', `MaleText_loc4`='要独自开动并驾驶蒸汽坦克可不是件简单的活儿，但总得有人去做。', `MaleText_loc5`='要靠你自己維持蒸汽坦克的運作是蠻難的，但是總得有人去做。', `MaleText_loc7`='Es muy difícil encargarme yo solo de que los tanques de vapor estén en perfectas condiciones de funcionamiento, pero alguien tiene que hacerlo.' WHERE `ID`=51466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린이 주간에는 붕붕이를 무료로 대여한답니다. 아무거나 하나 잡아타고 아름다운 서부 몰락지대를 유람하세요!', `MaleText_loc4`='儿童周期间大家可以免费租用摩托车，赶快挑一架到美丽的西部荒野兜风吧！', `MaleText_loc5`='為了紀念兒童週，來租用摩托車完全免費。自己挑一台，然後悠閒漫遊在美麗的西部荒野!', `MaleText_loc7`='El alquiler de choppers es gratuito en honor a la Semana de los Niños. ¡Súbete en una y viaja por los hermosos Páramos de Poniente!' WHERE `ID`=51467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울바르 고아 호루라기가 하나 더 필요합니다.', `MaleText_loc4`='我需要另一个狼獾人孤儿哨。', `MaleText_loc5`='我需要另一個獾狼怪孤兒哨。', `MaleText_loc7`='Necesito otro silbato de huérfano wolvar.', `FemaleText_loc1`='울바르 고아 호루라기가 하나 더 필요합니다.', `FemaleText_loc4`='我需要另一个狼獾人孤儿哨。', `FemaleText_loc5`='我需要另一個獾狼怪孤兒哨。', `FemaleText_loc7`='Necesito otro silbato de huérfano wolvar.' WHERE `ID`=51468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그니 폐하께서 저렇게 되신 건 모두 제 책임입니다. 제 잘못이에요. 그분을 격려할 게 아니라 신중해야 한다고 조언했어야 하는데! 제대로 이해하지도 못하면서 의식을 서두른 탓에, 얻은 것 없이 폐하를 잃기만 했습니다.', `MaleText_loc4`='麦格尼国王的命运是我的责任，也是我的耻辱。我真该建议他耐心点，而不是怂恿他贸然行动！他还未完全理解就仓促进行仪式，这让他失去了生命，同时我们也一无所获。', `MaleText_loc5`='發生在麥格尼·銅鬚國王身上的悲劇是我一生的恥辱，也是我的責任。我當時應該勸他耐心點才對，不應該鼓勵他那樣做!他魯莽地完成了儀式，卻沒有先了解後果為何，這讓他付出生命作為代價，對我們並無益處。', `MaleText_loc7`='El destino del rey Magni es mi responsabilidad y mi vergüenza. ¡Debí aconsejarle paciencia en vez de animarlo! Al apresurarse a completar el ritual sin comprenderlo del todo, pagó con su vida y a nosotros no nos solucionó nada.' WHERE `ID`=51469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 저 저주받은 서판을 제게 가져왔을 때 부숴 버렸어야 했습니다, $n 님. 하지만 전 그러지 않았죠. 서판을 없앴다면 이 위태로운 시기에 현명하신 폐하께서 우리를 이끌어 주셨을 텐데.', `MaleText_loc4`='当时你把石板带来给我，我就该把它们摔碎的，$n，可我没有。在此危难的时刻，我们仍需要国王的智慧来指引我们。', `MaleText_loc5`='我早該在你把石板帶來那天就要把它們砸壞才對，$n，不過我沒那樣做。我們國王的智慧仍能指引我們渡過這種艱難的時刻。', `MaleText_loc7`='Debí romper esas malditas tablillas el mismo día en el que me las trajo, $n, pero no lo hice. Quizá todavía tendríamos la sabiduría de nuestro rey para guiarnos en estos tiempos peligrosos.' WHERE `ID`=51470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스여, 당신의 힘으로 저를 도와주십시오!', `MaleText_loc4`='拉格纳罗斯，请赐予我力量吧！', `MaleText_loc5`='拉格納羅斯，我呼喚你的力量協助我!', `MaleText_loc7`='¡Ragnaros, invoco tu poder en mi ayuda!', `FemaleText_loc1`='라그나로스여, 당신의 힘으로 저를 도와주세요!', `FemaleText_loc4`='拉格纳罗斯，请赐予我力量吧！', `FemaleText_loc5`='拉格納羅斯，我呼喚你的力量協助我!', `FemaleText_loc7`='¡Ragnaros, invoco tu poder en mi ayuda!' WHERE `ID`=51471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님, 저를 영광스러운 빛으로 채워주십시오!', `MaleText_loc4`='主人，请让你的光辉照耀着我吧！', `MaleText_loc5`='主人啊，為我灌注你榮耀的光輝吧!', `MaleText_loc7`='¡Maestro, lléname con tu glorioso resplandor!', `FemaleText_loc1`='주인님, 저를 영광스러운 빛으로 채워주세요!', `FemaleText_loc4`='主人，请让你的光辉照耀着我吧！', `FemaleText_loc5`='主人啊，為我灌注你榮耀的光輝吧!', `FemaleText_loc7`='¡Maestro, lléname con tu glorioso resplandor!' WHERE `ID`=51472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 군주님! 당신의 영원한 불길을 제게 주십시오!', `MaleText_loc4`='拉格纳罗斯大人，请赐予我不熄的烈焰吧！', `MaleText_loc5`='拉格納羅斯領主，賜給我你不滅的火焰!', `MaleText_loc7`='¡Lord Ragnaros, bendíceme con tu fuego imperecedero!', `FemaleText_loc1`='라그나로스 군주님! 당신의 영원한 불길을 제게 주세요!', `FemaleText_loc4`='拉格纳罗斯大人，请赐予我不熄的烈焰吧！', `FemaleText_loc5`='拉格納羅斯領主，賜給我你不滅的火焰!', `FemaleText_loc7`='¡Lord Ragnaros, bendíceme con tu fuego imperecedero!' WHERE `ID`=51473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='소용없어요! 놈들의 보호막이 너무 강력해요!', `FemaleText_loc4`='这没用！他们的护盾太坚固了！', `FemaleText_loc5`='沒用!他們的護盾太強了!', `FemaleText_loc7`='¡No sirve de nada! ¡Su escudo es demasiado fuerte!' WHERE `ID`=51474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔달라 부족이 미쳐버렸습니다. 우리가 반드시 놈들을 막아야 해요.', `FemaleText_loc4`='赞达拉氏族已经疯了，我们必须阻止他们。', `FemaleText_loc5`='贊達拉食人妖啊，他們全都瘋了。一定得阻止他們。', `FemaleText_loc7`='Los Zandalari se han vuelto locos. Tenemos que asegurarnos de que les paramos los pies.' WHERE `ID`=51475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은창 부족이 잔달라 부족의 계획을 받아들이는 일은 절대로 없을 겁니다.', `FemaleText_loc4`='暗矛氏族不想和赞达拉的计划有任何瓜葛。', `FemaleText_loc5`='暗矛部族不希望跟贊達拉的計畫扯上任何關係。', `FemaleText_loc7`='Los Lanza Negra no quieren tener nada que ver con los planes de los Zandalari.' WHERE `ID`=51476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베녹시스는 독사를 조종합니다. 아주 교활한 자입니다.', `FemaleText_loc4`='温诺希斯控制着毒蛇，是个难缠的家伙。', `FemaleText_loc5`='是溫諾希斯在控制那些蛇。他是個狡猾的傢伙。', `FemaleText_loc7`='Venoxis controla las serpientes. Es una alimaña.' WHERE `ID`=51477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베녹시스는 독극물의 대가입니다. 막강한 적이에요.', `FemaleText_loc4`='温诺希斯擅长使毒，他是一个可怕的敌人。', `FemaleText_loc5`='溫諾希斯精於毒物，是個相當危險的對手。', `FemaleText_loc7`='Venoxis es un maeh''tro en venenos, es un enemigo moh''tal.' WHERE `ID`=51478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='킬나라는 표범을 자기 몸처럼 아낍니다.', `FemaleText_loc4`='基尔娜拉狂热地痴迷于猎豹。', `FemaleText_loc5`='基爾娜拉她為獵豹瘋狂著迷。', `FemaleText_loc7`='Kilnara, eh''tá loca por las panteras.' WHERE `ID`=51479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모티의 눈을 보셨나요? 환하게 빛나더군요! 그걸 보고 표범들이 날뛰는 배후에 킬나라가 있다는 걸 짐작했어야 하는데...', `FemaleText_loc4`='你看到玛乌提的眼睛吗？它们闪烁着光芒！我早该猜到基尔娜拉是猎豹袭击的幕后黑手。', `FemaleText_loc5`='你看見莫堤那雙眼睛沒?那雙眼睛會發光!我早該知道基爾娜拉在背後操縱獵豹攻擊。', `FemaleText_loc7`='¿Vih''te los ojos de Mauti? ¡Brillaban! Tenía que haber sabido que Kilnara eh''taba detrás de los ataques de la pantera.' WHERE `ID`=51480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭합니다, 용사여. 이 사악한 생명체는 제가 데리고 가겠습니다. 이 드루이드는 대답할 게 많답니다.', `FemaleText_loc4`='干得好，勇士。我会把这个肮脏的家伙带回去的。我们有不少问题要问这个德鲁伊。', `FemaleText_loc5`='做得好，勇士。我會把這隻醜惡的生物帶回去。這個德魯伊有很多問題得回答。', `FemaleText_loc7`='Buen trabajo, campeón. Me llevaré a esta miserable criatura conmigo. Este druida tiene que responder por muchas cosas.' WHERE `ID`=51481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불의 군주의 부하들이여, 이 침략자들을 처치해라! 오만한 하이잘의 수호자들을 불태워라!', `FemaleText_loc4`='炎魔之王的仆从，将入侵者烧成焦炭！烧死傲慢的海加尔守护者！', `FemaleText_loc5`='炎魔的僕人，殺光這些入侵者!把這些自大的海加爾守護者燒成灰燼!', `FemaleText_loc7`='¡Esbirros del Señor del Fuego, destruyan a los invasores! ¡Los Guardianes de Hyjal arderán por su arrogancia!' WHERE `ID`=51482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라그나로스 님의 분노를 느껴 보아라!', `FemaleText_loc4`='你们将承受拉格纳罗斯的愤怒！', `FemaleText_loc5`='你將承受拉格納羅斯的怒火!', `FemaleText_loc7`='¡Todos sufrirán la ira de Ragnaros!' WHERE `ID`=51483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사라져라!!!', `FemaleText_loc4`='死吧！', `FemaleText_loc5`='死吧!!!', `FemaleText_loc7`='¡¡¡MUERAN!!!' WHERE `ID`=51484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상관없다. 하이잘의 최후를 멀리서 지켜보리라.', `FemaleText_loc4`='没关系。我会在远处看着海加尔燃烧。', `FemaleText_loc5`='無所謂。我會遠遠看著海加爾燃燒。', `FemaleText_loc7`='No importa. Veré cómo arde Hyjal desde lejos.' WHERE `ID`=51485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔질이 중얼거립니다.', `MaleText_loc4`='赞吉尔自言自语着。', `MaleText_loc5`='贊吉爾對著自己嘟囔著。', `MaleText_loc7`='Zanzil murmura algo para sí mismo.' WHERE `ID`=51486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 그래. 이것도 조금 넣고... 저것도 조금 넣고... 헤헤!', `MaleText_loc4`='对了，加一撮这个……放一把那个……嘿嘿，嘿嘿！', `MaleText_loc5`='加一點這個...放一點那個...嘿嘿!', `MaleText_loc7`='Un pellizquito de esto... un poquito de aquello... ¡je, je!' WHERE `ID`=51487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 잔질, 잔질. 너의 부두 주문은 정말 최고야. 헤헤!', `MaleText_loc4`='哦，赞吉尔，赞吉尔。我和你一样爱巫毒。', `MaleText_loc5`='噢，贊吉爾贊吉爾，我愛死你的巫毒術了。', `MaleText_loc7`='Oh, Zanzil, Zanzil. Cómo me gusta tu vudú.' WHERE `ID`=51488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예든... 좀비든... 잔질한텐 상관없어. 어차피 모두 구루바시를 섬길 테니까...', `MaleText_loc4`='奴隶……僵尸……赞吉尔都无所谓。他们都要服侍古拉巴什，无论是活还是死……', `MaleText_loc5`='奴隸...殭屍...對贊吉爾來說都一樣。反正都會服侍古拉巴什，不論是哪種形式...', `MaleText_loc7`='Esclavos... zombis... A Zanzil le da igual. Todos sirven a los Gurubashi, de una forma u otra...' WHERE `ID`=51489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드여, 공격을 멈춰라! 저쪽은 맨손이다!', `MaleText_loc4`='德鲁伊们，停止攻击！她没有武器！', `MaleText_loc5`='德魯伊們，停火!她手無寸鐵!', `MaleText_loc7`='¡Druidas, deténganse! ¡Está desarmada!' WHERE `ID`=51490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 저 아이를 안다. 레이아라, 그대인가?', `MaleText_loc4`='等一下……我认识那女孩。莱雅娜，是你吗？', `MaleText_loc5`='等一下...我認識這個女孩。雷亞拉...是你嗎?', `MaleText_loc7`='Un momento... Conozco a esta chica. Leyara, ¿eres tú?' WHERE `ID`=51491;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 전쟁에서 보여준 그대의 능력은 칭송받아 마땅합니다. 전장에서 계속 실력을 갈고닦으십시오. 저는 이 범죄자를 데려가겠습니다... 심문을 해야 하니까요.', `FemaleText_loc4`='你的战斗技巧令人称羡，英雄。希望你能继续活跃在战场上。我会把这个罪犯带回去……审讯的……', `FemaleText_loc5`='你的戰鬥技巧十分令人讚賞，英雄。繼續在戰場上做出貢獻吧。我會把這個罪犯帶回去...審問。', `FemaleText_loc7`='Tus habilidades en combate son admirables. Quédate en el campo de batalla y sé útil. Yo me llevaré a este criminal para... interrogarlo.' WHERE `ID`=51492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 저는 감명받았습니다. 이... 드루이드를 진압하는 것을 도와주셔서 감사합니다. 이제는 제가 이 이단자를 데려가겠습니다.', `FemaleText_loc4`='你给我留下了深刻的印象，英雄。谢谢你帮我战胜了这个……德鲁伊。我自己押这个异端回去就行。', `FemaleText_loc5`='我很讚賞你，英雄。謝謝你幫我制服這個...德魯伊。我可以自己把這個異教徒帶回去。', `FemaleText_loc7`='Estoy impresionada. Gracias por ayudarnos a reducir a este... druida. Yo puedo encargarme sola de llevar de vuelta a este hereje .' WHERE `ID`=51493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염의 드루이드... 그녀는 위험합니다. 말퓨리온 님, 그녀를 아십니까?', `MaleText_loc4`='烈焰德鲁伊……她很危险，玛法里奥。你认识她吗？', `MaleText_loc5`='火焰德魯伊...她很危險，瑪法里恩。你...認識她嗎?', `MaleText_loc7`='Una druida de la Llama... es peligrosa, Malfurion. ¿La conoces?' WHERE `ID`=51494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알다마다. 그대의 생각보다 더 위험한 아이지.', `MaleText_loc4`='是的，哈缪尔。她比你想象的更危险。', `MaleText_loc5`='是的，哈繆爾。而且她比你想像中危險。', `MaleText_loc7`='Sí, Hamuul. Y es más peligrosa de lo que crees.' WHERE `ID`=51495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈은 붉은 과부, 베스틸락의 새끼입니다. 베스틸락의 새끼들은 죽임을 당한 형제의 복수를 하려들 것입니다.', `MaleText_loc4`='它是红寡妇，贝丝缇拉克的子嗣。她的其他小崽子们一定会来给它们的兄弟报仇的。', `MaleText_loc5`='這是紅寡婦貝絲堤拉克的孩子。她生出的孩子會替他們死去的兄弟報仇。', `MaleText_loc7`='Es un hijo de Beth''tilac, la Viuda Roja. Su prole buscará venganza por la muerte de sus hermanos.' WHERE `ID`=51498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 랩터가 당신을 올려다봅니다. 확실하지는 않지만 그 눈 속에서 반가운 기색이 스쳐 가는 것 같습니다.', `MaleText_loc4`='小迅猛龙抬头看着你。你无法确定，但你仿佛在她眼中看到认同的眼神。', `MaleText_loc5`='這隻小迅猛龍抬頭看著你。你不是很確定，不過你覺得在牠眼中閃過一絲認同感。', `MaleText_loc7`='El joven raptor te mira. No puedes saberlo con seguridad, pero crees ver una chispa de reconocimiento en sus ojos.' WHERE `ID`=51499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 놈들을 막아야 하네. 놈들이 아제로스의 모든 트롤을 지배하게 되면, 우리 모두 위험해질 게야.', `MaleText_loc4`='我们必须阻止赞达拉，艾泽拉斯所有的巨魔都联合起来听从统一的指挥，这对我们所有人都是巨大的威胁。', `MaleText_loc5`='一定要阻止贊達拉。如果全艾澤拉斯的食人妖都聽從他們的命令，定會對我們所有人造成威脅。', `MaleText_loc7`='Los Zandalari deben ser detenidos. Con todos los trols de Azeroth bajo su dominio, supondrían una gran amenaza pa'' todos nosotros.' WHERE `ID`=51500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족은 자네에게나 우리에게나 크나큰 위협이라네, $r. 놈들을 물리치려면 우리가 힘을 합쳐야만 해.', `MaleText_loc4`='赞达拉对我们双方的臣民都是巨大的威胁，$r。我们必须联合起来消灭他们。', `MaleText_loc5`='贊達拉對我們雙方來說都是個威脅，$r。想打敗他們就必須要結合我們雙方的力量。', `MaleText_loc7`='Los Zandalari son una amenaza pa'' nueh''tro pueblo, $r, tanto el tuyo como el mío. Necesitaremos la fuerza de nueh''tras huestes combinadas pa'' acabar con ellos.' WHERE `ID`=51501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스 군주님이시여! 저를 보호해주십시오!', `MaleText_loc4`='拉格纳罗斯大人！庇护我吧！', `MaleText_loc5`='拉格納羅斯領主，保護我!', `MaleText_loc7`='¡Lord Ragnaros! ¡Protégeme!', `FemaleText_loc1`='라그나로스 군주님이시여! 저를 보호해주세요!', `FemaleText_loc4`='拉格纳罗斯大人！庇护我吧！', `FemaleText_loc5`='拉格納羅斯領主，保護我!', `FemaleText_loc7`='¡Lord Ragnaros! ¡Protégeme!' WHERE `ID`=51502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 열 준비가 됐습니다.', `MaleText_loc4`='我们准备好打开大门了。', `MaleText_loc5`='我們準備要打開大門了。', `MaleText_loc7`='Estamos listos para abrir las puertas.', `FemaleText_loc1`='문을 열 준비가 됐습니다.', `FemaleText_loc4`='我们准备好打开大门了。', `FemaleText_loc5`='我們準備要打開大門了。', `FemaleText_loc7`='Estamos listos para abrir las puertas.' WHERE `ID`=51503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라오게, $c. 문을 열려면 두 명이 있어야 하니까.', `MaleText_loc4`='跟我来，$c。需要我们二个人一起来才能打开大门。', `MaleText_loc5`='跟上，$c。需要我們兩人合力才能打開這扇大門。', `MaleText_loc7`='Sígueme, $c. Tendremos que trabajar juntos pa'' abrir esas pueh''tas.' WHERE `ID`=51504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 여기 계셨군요! 이놈들이 난데없이 나타났습니다! 제가 잠시 숨을 돌리는 동안 부디 도와주십시오!', `FemaleText_loc4`='嘿，$n，你也来了！这些家伙都是突然冒出来的！快来帮帮我，让我喘口气！', `FemaleText_loc5`='喂，$n!這些傢伙突然冒了出來!幫幫我，讓我喘口氣。', `FemaleText_loc7`='¡Hola, $n, has llegado! ¡Esos tipos aparecieron de la nada! Échame una mano mientras recupero el aliento.' WHERE `ID`=51505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘이서 함께 징을 치는 것이 바로 문을 여는 의식이라네.', `MaleText_loc4`='开门仪式需要我们一同敲响这个锣。', `MaleText_loc5`='打開大門的儀式需要我倆同時敲響銅鑼。', `MaleText_loc7`='El ritual pa'' abrir las pueh''tas exige que los dos golpeemos el gong al unísono.' WHERE `ID`=51506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=51507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 준비가 안 됐나 보군. 문을 열고 싶거든 내게 다시 이야기하게.', `MaleText_loc4`='也许我们还没准备好。你们准备打开大门的时候告诉我。', `MaleText_loc5`='或許我們還有人沒準備好。要打開大門的時候跟我說一聲。', `MaleText_loc7`='Quizá no eh''temos lih''tos aún. Habla conmigo cuando quieras abrir las pueh''tas.' WHERE `ID`=51508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 자리에 나온 건 저로선 큰 위험을 감수한 겁니다, 세계파괴자여. 누가 보기라도 하는 날엔...', `MaleText_loc4`='我同意来见你，灭世者，但冒着极大的风险。如果我们被发现了……', `MaleText_loc5`='我同意此次的會面，碎界者，但冒著極大的風險。如果被人發現了...', `MaleText_loc7`='He aceptado este encuentro, Rompemundos, pero con gran riesgo. Si alguien lo descubre...' WHERE `ID`=51509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 체제가 들어선 다음에도... 제 자리는 보장해 주시겠죠, 네?', `MaleText_loc4`='一旦新的秩序建立，你将确保我的地位，是吗？', `MaleText_loc5`='等新的秩序產生之後呢?我的位子就穩了，對吧?', `MaleText_loc7`='¿Y una vez se establezca este nuevo orden? ¿Mi posición seguirá estando asegurada?' WHERE `ID`=51510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라, 아리고스. 너의 보호막이 충분한 시간을 벌어 줄 것이다.', `MaleText_loc4`='冷静，阿瑞苟斯。你的屏障能为你争取足够的时间。', `MaleText_loc5`='冷靜下來，亞雷戈斯。你的障壁爭取的時間絕對足夠。', `MaleText_loc7`='Cálmate, Arygos. Tu barrera te dará todo el tiempo que necesites.' WHERE `ID`=51512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼렉고스가 죽으면, 푸른 위상으로서의 너의 운명이 현실화될 것이다.', `MaleText_loc4`='等到卡雷苟斯死后，你作为蓝龙之王的宿命就将确立。', `MaleText_loc5`='如果卡雷苟斯死了，由你守護藍龍的宿命就會實現。', `MaleText_loc7`='Tras la muerte de Kalecgos, se cumplirá tu destino como Aspecto Azul.' WHERE `ID`=51513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 시간 이후에도... 너는 마법의 영역에 절대 지배력을 행사할 것이다.', `MaleText_loc4`='你将得到对魔法国度至高无上的统治权，即使是在暮光审判日之后。', `MaleText_loc5`='你對魔法領域的統治將是絕對，即使在暮光之時過後也是一樣。', `MaleText_loc7`='Tu gobierno sobre el reino de la magia será absoluto, incluso tras la Hora del Crepúsculo.' WHERE `ID`=51514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 명심해라, 아리고스, 말리고스의 아들아. 네 아비의 실수를 반복하지 마라.', `MaleText_loc4`='但我警告你，阿瑞苟斯，玛里苟斯之子，不要重蹈你父亲的覆辙。', `MaleText_loc5`='但我提醒你，亞雷戈斯，瑪里苟斯之子，別與你父親犯下同樣的錯誤。', `MaleText_loc7`='Te lo advierto, Arygos, hijo de Malygos. No cometas los mismos errores que tu padre.' WHERE `ID`=51515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뜻을 거스르는 날엔, 그의 광기보다 더 끔찍한 벌을 내리리라.', `MaleText_loc4`='如果与我作对，你受到的惩罚将比你父亲的更可怕。', `MaleText_loc5`='背叛我，你的懲罰將比他所承受的瘋狂來得嚴重。', `MaleText_loc7`='Traicióname y tu castigo será peor que la locura que él sufrió.' WHERE `ID`=51516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라, 음흉한 잔달라 놈들아... 네놈들이 아마니 부족을 지배하는 걸 막으러 검은창 부족이 동맹을 이끌고 왔다!', `MaleText_loc4`='听着，赞达拉的阴谋者们……暗矛部落和我们的盟友不允许你们统治阿曼尼！', `MaleText_loc5`='聽我說，在贊達拉背後策劃陰謀的人...暗矛部族和我們的盟友不會接受你們阿曼尼的統治!', `MaleText_loc7`='Escúchenme, conh''piradores Zandalari... ¡Los Lanza Negra y nueh''tros aliados impediremos que gobiernen a los Amani!' WHERE `ID`=51517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령으로부터 티살리를 보호하십시오!', `MaleText_loc4`='保护希萨莉，不要让火元素伤害她！', `MaleText_loc5`='保護黎沙莉不被火元素殺害!', `MaleText_loc7`='¡Protege a Thisalee de los elementales de fuego!', `FemaleText_loc1`='불의 정령으로부터 티살리를 보호하십시오!', `FemaleText_loc4`='保护希萨莉，不要让火元素伤害她！', `FemaleText_loc5`='保護黎沙莉不被火元素殺害!', `FemaleText_loc7`='¡Protege a Thisalee de los elementales de fuego!' WHERE `ID`=51518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 놈들은 우리가 여기 왔음을 아네. 어서 공격을 시작하지!', `MaleText_loc4`='阿曼尼知道我们在这里，进攻的时候到了！', `MaleText_loc5`='阿曼尼知道我們來了。該是發動攻擊的時候了!', `MaleText_loc7`='Los Amani saben que eh''tamos aquí. ¡Es el momento de atacar!' WHERE `ID`=51519;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $c님. 불의 군주가 우리의 형제와 자매였던 이들을 타오르는 격노의 화신으로 만들어놓았습니다. 지금도 화염의 드루이드들은 세계수를 파괴할 끔찍한 계획을 실행하고 있습니다. 우리는 그런 일이 일어나도록 내버려둬서는 안 됩니다.', `FemaleText_loc4`='你好，$c。这些德鲁伊都曾是我们的兄弟姐妹，可现在他们已经被炎魔之王变成了熔岩的化身。现在，烈焰德鲁伊们就在执行他的疯狂计划，试图烧毁世界之树。我们绝对不能让他们得逞。', `FemaleText_loc5`='你好，$c。炎魔把我們從前的兄弟姊妹們都扭曲成熔岩般的怪物。即使是現在，火焰德魯伊們還在執行他摧毀世界之樹的瘋狂計畫。我們不能讓它發生。', `FemaleText_loc7`='Saludos, $c. El Señor del Fuego ha corrompido a nuestros antiguos hermanos y hermanas hasta convertirlos en encarnaciones de furia de magma. Mientras hablamos, los Druidas de la Llama siguen adelante con su plan de destruir el Árbol del Mundo. No permitiremos que eso ocurra.' WHERE `ID`=51520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안렌, 여길 보게! $n 님이 도와주러 오셨네!', `MaleText_loc4`='看，安伦！$n来帮我们了！', `MaleText_loc5`='看啊，安倫，$n來幫我們了!', `MaleText_loc7`='¡Mira, Anren! ¡$n ha venido a ayudarnos!' WHERE `ID`=51521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령으로부터 톨로와 안렌을 보호하십시오!', `MaleText_loc4`='保护索罗和安伦，不要让火元素伤害他们！', `MaleText_loc5`='保護索羅及安倫不被火元素殺害!', `MaleText_loc7`='¡Protege a Tholo y a Anren de los elementales de fuego!', `FemaleText_loc1`='불의 정령으로부터 톨로와 안렌을 보호하십시오!', `FemaleText_loc4`='保护索罗和安伦，不要让火元素伤害他们！', `FemaleText_loc5`='保護索羅及安倫不被火元素殺害!', `FemaleText_loc7`='¡Protege a Tholo y a Anren de los elementales de fuego!' WHERE `ID`=51522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r|1이여;여;, 때맞춰 잘 왔다. 이 끔찍한 괴물들과 싸우는 데 지쳐가는구나.', `MaleText_loc4`='你来得正是时候，$r。我已经受够这些肮脏的怪物了。', `MaleText_loc5`='你來得正是時候，$r。我已經對跟這些可悲的東西作戰感到厭煩了。', `MaleText_loc7`='Llegas en el momento oportuno, $r. Estoy cansado de luchar contra esas malditas cosas.' WHERE `ID`=51523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령으로부터 늙은가지를 보호하십시오!', `MaleText_loc4`='保护老树干，不要让火元素伤害他！', `MaleText_loc5`='保護老枝不被火元素殺害!', `MaleText_loc7`='¡Protege a Tallosaúco de los elementales de fuego!', `FemaleText_loc1`='불의 정령으로부터 늙은가지를 보호하십시오!', `FemaleText_loc4`='保护老树干，不要让火元素伤害他！', `FemaleText_loc5`='保護老枝不被火元素殺害!', `FemaleText_loc7`='¡Protege a Tallosaúco de los elementales de fuego!' WHERE `ID`=51524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 그대의 명령에 따르겠습니다.', `FemaleText_loc4`='愿为您效劳，勇士。', `FemaleText_loc5`='我為你而戰，勇士。', `FemaleText_loc7`='Mi espada es tuya, campeón.' WHERE `ID`=51525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬이 그대를 반기는군요, 용사여. 제가 당신을 지켜 드리겠습니다.', `FemaleText_loc4`='艾露恩欢迎你，勇士。我会掩护你。', `FemaleText_loc5`='伊露恩歡迎你，勇士。我會支援你的。', `FemaleText_loc7`='Elune te saluda, campeón. Yo te cubriré las espaldas.' WHERE `ID`=51526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도움을 청하면 그림자 감시단이 답할 것입니다. 저는 누구라도 상대할 준비가 되어 있습니다.', `FemaleText_loc4`='只要开口求援，暗影守望者就会出现。我已经做好一切准备了。', `FemaleText_loc5`='呼喚援軍，暗影看守者就會來支援。我準備好應付任何狀況了。', `FemaleText_loc7`='Pide ayuda y las Celadoras de las Sombras responderán. Estoy lista para lo que sea.' WHERE `ID`=51527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='임무를 수행하겠습니다. 허비할 시간은 없습니다.', `FemaleText_loc4`='立刻报告。我们没时间了。', `FemaleText_loc5`='前來報到。沒有時間可以浪費了。', `FemaleText_loc7`='Me presento para el servicio. No hay tiempo que perder.' WHERE `ID`=51528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 칼이 전투에 목말라 있습니다. 계속 기다리게 하지 마십시오.', `FemaleText_loc4`='我的剑在渴望战斗。不要让我久等了。', `FemaleText_loc5`='我的武器渴望著戰鬥。別讓我等太久。', `FemaleText_loc7`='Mi espada tiene sed de batallas. No me hagas esperar.' WHERE `ID`=51529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제부터는 제가 알아서 하겠습니다. 성역에서 다시 만나뵙겠습니다, $n 님.', `FemaleText_loc4`='接下来的事我自己可以搞定。我们庇护所再见了，$n。', `FemaleText_loc5`='從這裡我可以自己來了。我們在聖地再見吧，$n。', `FemaleText_loc7`='A partir de aquí ya puedo encargarme yo. Te veré en el Santuario, $n.' WHERE `ID`=51530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 안렌과 내가 힘을 합치면, 이제 더는 큰 문제가 없을 걸세. 가서 다른 이들을 살피게!', `MaleText_loc4`='谢谢你，$n。只要我和安伦在一起，我们就没什么好怕的了。快去看看其他人吧！', `MaleText_loc5`='謝謝你，$n。只要我們一起行動，安倫跟我會沒事的。去照看其他人!', `MaleText_loc7`='Gracias, $n. Siempre y cuando permanezcamos juntos, Anren y yo estaremos bien. ¡Ve por los demás!' WHERE `ID`=51531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터는 내가 저들을 막아낼 수 있다, $r. 말로른의 성역에서 다시 만나자.', `MaleText_loc4`='从这里开始我能自己搞定了，$r。我们在玛洛恩庇护所见吧。', `MaleText_loc5`='從這裡開始我可以自己解決他們了，$r。我們在瑪洛尼聖地再會吧。', `MaleText_loc7`='Puedo mantenerlos a raya desde aquí, $r. Nos reuniremos de nuevo en el Santuario de Malorne.' WHERE `ID`=51532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정의는 실현될 것이다, 이교도 놈아!', `FemaleText_loc4`='正义终将得到伸张，异端！', `FemaleText_loc5`='正義會審判你，異教徒!', `FemaleText_loc7`='¡Se hará justicia, impíos!' WHERE `ID`=51533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이단자에게는 자비도 없을 것이다!', `FemaleText_loc4`='我绝不宽恕亵渎者！', `FemaleText_loc5`='我對受到污染的人不會手下留情!', `FemaleText_loc7`='¡No mostraré ninguna compasión con los corruptos!' WHERE `ID`=51534;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무... 고통스럽지는 않을 거라고 약속하지.', `FemaleText_loc4`='我向你保证，不会痛的……起码不会很痛。', `FemaleText_loc5`='這不會痛...一下子就過去了。', `FemaleText_loc7`='Prometo que esto no dolerá... demasiado.' WHERE `ID`=51535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자비를 바라지는 마라. 내 칼이 허락하지 않을 테니까.', `FemaleText_loc4`='别想求饶了。我的剑是不会宽恕敌人的。', `FemaleText_loc5`='不要祈求憐憫。我的劍不會答應的。', `FemaleText_loc7`='No pidáis compasión. Mi espada no os la concederá.' WHERE `ID`=51536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적에게 조상님들을 만나게 해 주겠다!', `FemaleText_loc4`='我要把所有的敌人都送回老家！', `FemaleText_loc5`='我會把我的敵人送去見他們祖先!', `FemaleText_loc7`='¡Enviaré a mis enemigos a reunirse con sus ancestros!' WHERE `ID`=51537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불길은 많은 것을 태워버리지만, 그림자까지 태울 수는 없지.', `FemaleText_loc4`='火焰可以焚烧许多东西，但它永远碰不到阴影。', `FemaleText_loc5`='火可以燃燒許多東西，但無法觸碰到暗影。', `FemaleText_loc7`='El fuego quema muchas cosas, pero no puede tocar una sombra.' WHERE `ID`=51538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈의 죄를 내 단검의 칼날로 정화해주겠다.', `FemaleText_loc4`='我会用匕首的锋刃洗清你的罪恶。', `FemaleText_loc5`='我會用匕首的刀鋒清洗你的罪孽。', `FemaleText_loc7`='Purificaré tus pecados con el filo de mi daga.' WHERE `ID`=51539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀비가 있는 곳이라면 잔질이 있지요. 잔달라 트롤의 지휘 아래, 구루바시 부족은 모조의 힘을 통해 가시덤불 골짜기를 되찾으려 합니다.', `FemaleText_loc4`='哪里有僵尸，哪里就有赞吉尔。赞达拉巨魔将要集中所有古拉巴什魔精，夺回荆棘谷。', `FemaleText_loc5`='到處都是殭屍，到處都是贊吉爾。贊達拉食人妖讓古拉巴什用上了所有魔精好取回荊棘谷。', `FemaleText_loc7`='Donde haya zombis, allí eh''tará Zanzil. Los trols Zandalar harán que los Gurubashi gah''ten todo su mojo pa'' recuperar Tuercespina.' WHERE `ID`=51540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁에 대한 부담으로 마음이 무겁기만 하구나. 동료들을 죽음으로 몰아넣으니 말이다. 그러나 지금 우리가 라그나로스와 맞서지 않는다면 넬타리온은 어떻게 버텨낼 것이란 말인가?$B$B모든 것을 다 바쳐 전투에 임하지 않는다면 우리 세계가 멸망하는 것을 두 눈으로 보게 될 것이다.', `MaleText_loc4`='这场战争令我心情沉重。我正带领着我的人民走向死亡。但如果我们现在不站出来反抗拉格纳罗斯，将来又怎么能抵挡得住奈萨里奥呢？$B$B我们必须为自己所拥有的一切而战，否则就只能眼睁睁看着世界毁灭。', `MaleText_loc5`='我的心因這場戰爭而充滿了沉重的負擔。我的人民在我的領導下死亡。但是如果我們現在不對拉格納羅斯進行抵抗，我們該怎麼面對奈薩里奧?$B$B我們必須竭盡所能地戰鬥，不然就得見證我們世界的滅亡。', `MaleText_loc7`='Mi corazón sufre por los pesares de esta guerra. Guío a mi pueblo a su muerte. Pero si no podemos enfrentarnos a Ragnaros ahora, ¿cómo podremos vérnoslas con Neltharion?$B$BDebemos luchar con todo lo que tenemos o seremos testigos de la destrucción de nuestro mundo.' WHERE `ID`=51541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 함께 있네, 톨로!', `MaleText_loc4`='有我陪着你呢，索罗！', `MaleText_loc5`='我與你同在，索羅!', `MaleText_loc7`='¡Estoy contigo, Tholo!' WHERE `ID`=51542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤에 있으라고, 톨로!', `MaleText_loc4`='到我后面去，索罗！', `MaleText_loc5`='待在我背後，索羅!', `MaleText_loc7`='¡Cúbreme las espaldas, Tholo!' WHERE `ID`=51543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 함께 움직여야 하네, 톨로!', `MaleText_loc4`='我们绝不分开，索罗！', `MaleText_loc5`='我們不能落單，索羅!', `MaleText_loc7`='¡Debemos permanecer juntos, Tholo!' WHERE `ID`=51544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 정말 좋은 친구야, 톨로!', `MaleText_loc4`='你真是个好兄弟，索罗！', `MaleText_loc5`='你是個好朋友，索羅!', `MaleText_loc7`='¡Eres un buen amigo, Tholo!' WHERE `ID`=51545;
