UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기 있네, 안렌!', `MaleText_loc4`='我在这儿，安伦！', `MaleText_loc5`='我在這裡，安倫!', `MaleText_loc7`='¡Estoy aquí, Anren!' WHERE `ID`=51551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티살리 곁에 머물러야 합니다!', `MaleText_loc4`='你必须留在希萨莉身边！', `MaleText_loc5`='你必須留在黎沙莉身邊!', `MaleText_loc7`='¡Debes permanecer al lado de Thisalee!', `FemaleText_loc1`='티살리 곁에 머물러야 합니다!', `FemaleText_loc4`='你必须留在希萨莉身边！', `FemaleText_loc5`='你必須留在黎沙莉身邊!', `FemaleText_loc7`='¡Debes permanecer al lado de Thisalee!' WHERE `ID`=51552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로와 안렌 곁에 머물러야 합니다!', `MaleText_loc4`='你必须留在索罗和安伦身边！', `MaleText_loc5`='你必須留在索羅及安倫身邊!', `MaleText_loc7`='¡Debes permanecer al lado de Tholo y Anren!', `FemaleText_loc1`='톨로와 안렌 곁에 머물러야 합니다!', `FemaleText_loc4`='你必须留在索罗和安伦身边！', `FemaleText_loc5`='你必須留在索羅及安倫身邊!', `FemaleText_loc7`='¡Debes permanecer al lado de Tholo y Anren!' WHERE `ID`=51553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은가지 곁에 머물러야 합니다!', `MaleText_loc4`='你必须留在老树干身边！', `MaleText_loc5`='你必須留在老枝身邊!', `MaleText_loc7`='¡Debes permanecer al lado de Tallosaúco!', `FemaleText_loc1`='늙은가지 곁에 머물러야 합니다!', `FemaleText_loc4`='你必须留在老树干身边！', `FemaleText_loc5`='你必須留在老枝身邊!', `FemaleText_loc7`='¡Debes permanecer al lado de Tallosaúco!' WHERE `ID`=51554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대사제가 죽고 바깥이 안전해지면 알려 주십시오. 하쿠즈 님께 보고서를 가져가겠습니다.', `MaleText_loc4`='杀死高阶祭司，一切都安全之后再来找我，我就可以带着我的报告回到血卫士身边了。', `MaleText_loc5`='等到高階祭司死了、四周也安全了就告訴我吧，我會接著動身回去向血衛士回報。', `MaleText_loc7`='Cuando el sumo sacerdote eh''té mueh''to y no haya peligro a la vih''ta, avísame y regresaré a la guardia de sangre con mi informe.' WHERE `ID`=51555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤곰은 처치하셨습니까, 친구? 저 이제 돌아가도 괜찮은 겁니까?', `MaleText_loc4`='你除掉那巨魔熊了吗，朋友？我现在能安全地回去了吗？', `MaleText_loc5`='你殺了食人妖熊嗎，老兄?回去的路是不是安全啦?', `MaleText_loc7`='¿Has matado al trol oso, colega? ¿Es seguro que me ponga en marcha yo solo?' WHERE `ID`=51556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 누구 없습니까? 하즐렉 목소리 안 들립니까?', `MaleText_loc4`='嗨，有人能听见哈兹莱克说话吗？', `MaleText_loc5`='哈囉!有人聽到哈茲雷克說話嗎?', `MaleText_loc7`='Hola. ¿No hay nadie que oiga a Hazlek?' WHERE `ID`=51557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 하즐렉이 여기 있단 걸 잊지 말아 주세요.', `MaleText_loc4`='嗨！别忘了哈兹莱克！在这里！', `MaleText_loc5`='嘿!別忘了哈茲雷克還在這。', `MaleText_loc7`='¡Eh! No te olvides de Hazlek.' WHERE `ID`=51558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이딴 자물쇠는 눈 감고도 열 수 있습니다. 그냥 언제 탈출하면 되는지만 좀 알려 주세요.', `MaleText_loc4`='我睡梦中都能打开这个锁，只要告诉我什么时候能安全逃跑就行。', `MaleText_loc5`='就算我睡著了都能打開這個鎖。安全的時候說一聲，我好動身逃出去。', `MaleText_loc7`='Podría abrir eh''ta cerradura incluso dormido. Tú solo avísame cuando sea seguro escapar.' WHERE `ID`=51559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 드디어 자유의 몸이다!', `MaleText_loc4`='终于，我自由了！', `MaleText_loc5`='我終於自由了!', `MaleText_loc7`='¡Por fin, soy libre!' WHERE `ID`=51560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 제 물건이 좀 있는데...', `MaleText_loc4`='这里有些我的东西……', `MaleText_loc5`='我這裡有些東西...', `MaleText_loc7`='Aquí eh''tán algunas de mis cosas...' WHERE `ID`=51561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 열렸군요. 아마니 놈들을 무찌르는 걸 도와주신 여러분께 제가 드리는 선물입니다!', `MaleText_loc4`='好啦。这是给你的礼物，感谢你帮忙打败阿曼尼帝国！', `MaleText_loc5`='你瞧，怎樣。這是給你的禮物，謝謝你打敗了阿曼尼!', `MaleText_loc7`='Toma. Un obsequio pa'' ti, pa'' que te ayude a derrotar a los Amani.' WHERE `ID`=51562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에서 나오니 정말 좋군요. 놈들은 절 제물로 바칠 셈이었습니다...', `MaleText_loc4`='能从笼子里逃出来太好了，他们正要把我当祭品呢……', `MaleText_loc5`='能離開這個籠子感覺真好。他們要把我當成祭品...', `MaleText_loc7`='Me alegro de eh''tar fuera de esa jaula. Iban a sacrificarme...' WHERE `ID`=51563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 걱정하지 않으셔도 됩니다. 여기서 무슨 일이 벌어지는 겁니까?', `MaleText_loc4`='你不用担心了。这里发生了什么？', `MaleText_loc5`='你不用再擔心了。這裡發生了什麼事?', `MaleText_loc7`='Ya no tienes que preocuparte por eso. ¿Qué ocurre aquí?', `FemaleText_loc1`='이젠 걱정하지 않으셔도 됩니다. 여기서 무슨 일이 벌어지는 거죠?', `FemaleText_loc4`='你不用担心了。这里发生了什么？', `FemaleText_loc5`='你不用再擔心了。這裡發生了什麼事?', `FemaleText_loc7`='Ya no tienes que preocuparte por eso. ¿Qué ocurre aquí?' WHERE `ID`=51564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 친구. 본 대로 말씀드리죠...$b$b사방이 조용했습니다. 그런데 어느 순간 마치 나무 사이를 스치는 바람 같은 소리가 나더니, 이 아마니 트롤과 놈들의 애완동물한테 둘러싸여 있지 뭡니까! 그러고는 기억이 없어요. 깨어났을 땐 여기 우리 안에 갇혀 있었습니다.$b$b밤낮으로 포로들이 하나씩 죽어나갔습니다. 한 명 죽을 때마다 저 곰처럼 생긴 트롤 녀석은 더 강해지는 것 같았고 말입니다.$b$b저 우리 안에서 알 수 있었던 건 그 정도뿐입니다.', `MaleText_loc4`='哦朋友，当时的情况是这样的……$b$b夜色寂静，突然传来一阵微风掠过树叶般的飒飒声。没等我们回过神来，阿曼尼巨魔和他们的宠物已经包围了我们！等我醒来的时候，发现自己被囚禁在牢笼中。$b$b日复一日，囚犯们接二连三地惨遭毒手。每杀死一名囚犯，那个熊巨魔的力量就增加一些。$b$b我关在牢笼中，只知道这些。', `MaleText_loc5`='好，老兄，情況是這樣的...$b$b一切是如此的安靜，突然間我們聽到一陣沙沙作響的聲音，就像風吹過樹梢一樣。在尚未來得及反應之前，我們已經被那些阿曼尼還有他們的寵物給包圍了!我隔天醒來的時候，已經身陷牢籠了。$b$b日日夜夜，一個接著一個，斥候們被處決了。每死掉一個，那個熊一般的食人妖看起來就更強壯。$b$b這就是我從籠子裡面知道的事。', `MaleText_loc7`='Vale, colega, eh''to es lo que vi...$b$bTodo eh''taba en silencio y, de pronto, oímos un susurro, como cuando el viento sopla entre los árboles. ¡Antes de darnos cuenta, esos Amani y sus mascotas nos rodearon! Lo siguiente que recuerdo es deh''peh''tarme aquí, en eh''ta jaula.$b$bDía y noche, uno tras otro, los exploradores capturados fueron asesinados. Cada vez que moría uno, ese oso-trol parecía hacerse más fueh''te.$b$bEso es todo lo que he podido descubrir desde mi jaula.' WHERE `ID`=51565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 검은창 트롤을 도와주러 오셨습니까?', `FemaleText_loc4`='你是来帮助暗矛部落的吗，$c？', `FemaleText_loc5`='你是來幫助暗矛部族的嗎，$c?', `FemaleText_loc7`='¿Has venido pa'' ayudar a los Lanza Negra, $c?' WHERE `ID`=51566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다, $c님. 저도 제물 신세가 될 줄 알았습니다...', `MaleText_loc4`='感谢你，$c。我以为我要被献祭了……', `MaleText_loc5`='非常感謝你，$c。我還以為我會變成另一個犧牲者死在這呢...', `MaleText_loc7`='Tienes mi agradecimiento, $c. Pensé que acabaría siendo un sacrificio más.' WHERE `ID`=51567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 잊지 마십시오!', `MaleText_loc4`='不要忘了我！', `MaleText_loc5`='別把我忘在這!', `MaleText_loc7`='¡No te olvides de mí!' WHERE `ID`=51568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 오셔서 절 좀 꺼내 주시는 게 어떻습니까?', `MaleText_loc4`='不如过来救我出去吧？', `MaleText_loc5`='把我從這個籠子放出來如何?', `MaleText_loc7`='¿Qué tal si vienes y me ayudas a salir de aquí?' WHERE `ID`=51569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님께 전해 드릴 정보가 있습니다. 저 좀 구해 주세요!', `MaleText_loc4`='我这有沃金需要的情报，快来放我出来！', `MaleText_loc5`='我取得了沃金所需的資訊。救我離開這裡!', `MaleText_loc7`='Tengo información que debo hacer llegar a Vol''jin. ¡Ayúdame a salir de aquí!' WHERE `ID`=51570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 하려면 끝까지 하셔야죠. 탈출할 수 있는 상황인지 와서 좀 알려 주십시오!', `MaleText_loc4`='做事别做一半。如果安全了就告诉我一声，我好回去汇报！', `MaleText_loc5`='做事別做一半。周圍安全的時候跟我說一下，我好回去報告!', `MaleText_loc7`='No te vayas dejando el trabajo a medias. ¡Ven y dime si ya es seguro que vaya a entregar mi informe!' WHERE `ID`=51571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 자유의 몸이 되니 정말 좋군요!', `MaleText_loc4`='重获自由的感觉真好！', `MaleText_loc5`='再次獲得自由的感覺真好!', `MaleText_loc7`='¡Me alegro de ser libre de nuevo!' WHERE `ID`=51572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 검은창 트롤의 사절입니다. 우리를 위협하는 존재는 얼라이언스 역시 위협하고 있습니다. 검은창 트롤을 도와주시겠습니까, $r|1이여;여;?', `FemaleText_loc4`='我是来自暗矛巨魔的使者。我们面临的威胁也同样是联盟的威胁。你愿意帮助暗矛氏族吗，$r？', `FemaleText_loc5`='我是暗矛食人妖的特使。我們所面臨的威脅，也同樣威脅著聯盟。你願意幫助暗矛部族嗎，$r?', `FemaleText_loc7`='Soy una emisaria de los trols Lanza Negra. La amenaza a la que nos enfrentamos también lo es pa'' la Alianza. ¿Quieres ayudar a los Lanza Negra, $r?' WHERE `ID`=51573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 발견한 게 있는데, 잠깐만 기다리십시오. 그 가방이 어디 있더라...?', `MaleText_loc4`='让我给你看些我找到的东西。咦，背包哪去了？', `MaleText_loc5`='我來讓你看看我發現了什麼。現在讓我們來看看那個背袋在哪?', `MaleText_loc7`='Permíteme que te mueh''tre algo que he descubieh''to. ¿Dónde he dejado esa cah''tera?' WHERE `ID`=51574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 리빙스턴 요새인가요? 이미 늦었군요. 잔달라의 공격이 시작되었습니다.', `FemaleText_loc4`='这就是利文斯顿营地？看来我们已经迟了，赞达拉的进攻已经开始。', `FemaleText_loc5`='這是李文斯頓堡壘?看來我們晚了一步。贊達拉已經開始攻擊了。', `FemaleText_loc7`='¿Eh''to es Fuerte Livingston? Parece que ya es demasiado tarde. El ataque Zandalar ha comenzado.' WHERE `ID`=51575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이럴수가... 밤발라가... 너무 늦었군요. 잔달라의 공격이 시작되었습니다.', `FemaleText_loc4`='哦不……邦巴拉……看来我们太迟了，赞达拉已经发动进攻了。', `FemaleText_loc5`='喔不...班姆巴拉...看來我們晚了一步。贊達拉已經開始攻擊了。', `FemaleText_loc7`='Oh, no... Bambala... Parece que ya es demasiado tarde. El ataque Zandalar ha comenzado.' WHERE `ID`=51576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 당신이 가지십시오. 정찰병이 그렇게 무거운 걸 가지고 돌아다녔다간 죽기 딱 좋죠.', `MaleText_loc4`='你们随便拿吧。作为一名斥候，带着那么多拖油瓶真是自寻死路。', `MaleText_loc5`='請自便。拖著那麼重的東西四處遊蕩，對斥候來說根本是自殺行為。', `MaleText_loc7`='Ustedes verán. Es un suicidio que un explorador ande por ahí con tanta carga.' WHERE `ID`=51577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사냥꾼들이 독사를 막아내고 있습니다. 하지만 뭔가 느낌이 이상해요... 마치 우리가 감시당하는 것 같습니다.', `FemaleText_loc4`='看样子，那些猎手成功阻击了那些毒蛇，但我感觉还有别的事不对劲……就好像有人注视着我们。', `FemaleText_loc5`='看來獵人成功擋住蛇群了。不過有種奇怪的感覺...好像一直有人在看著我們。', `FemaleText_loc7`='Parece ser que los cazadores eh''tán reteniendo a las serpientes. Pero siento que hay algo más fuera de lugar... Como si nos observaran.' WHERE `ID`=51578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다, $c님.$b$b당신을 위해 제가 할 일이 있다면 뭐든 말씀하십시오.', `MaleText_loc4`='感谢你，$c。$b$b如果我能帮你做什么，尽管告诉我。', `MaleText_loc5`='由衷地感謝你，$c。$b$b如果有任何需要我的地方，盡管跟我說。', `MaleText_loc7`='Tienes mi agradecimiento, $c.$b$bSi hay algo que pueda hacer por ti, solo dímelo.' WHERE `ID`=51579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발굴현장이... 좀비에게 점령당했군요...', `FemaleText_loc4`='挖掘场里……处处都是僵尸……', `FemaleText_loc5`='挖掘場到處是殭屍...', `FemaleText_loc7`='La Excavación ha sido invadida por zombis...' WHERE `ID`=51580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은신처에... 좀비가 가득 찼습니다...', `FemaleText_loc4`='避世乐园里……处处都是僵尸……', `FemaleText_loc5`='藏匿處到處是殭屍...', `FemaleText_loc7`='El Escondrijo ha sido invadido por zombis...' WHERE `ID`=51581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 놈들이 득시글거리지만 않으면 여기도 그렇게 나쁘지 않습니다.', `MaleText_loc4`='要是没那么多阿曼尼巨魔的话，这个地方也不算糟糕。', `MaleText_loc5`='如果沒那麼多阿曼尼在這兒，其實這地方也不賴。', `MaleText_loc7`='Eh''te lugar no eh''taría tan mal si no hubiera tantos Amani por aquí.' WHERE `ID`=51582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니와 잔달라 놈들은 다시는 이런 짓을 벌이지 않을 겁니다.', `MaleText_loc4`='阿曼尼和赞达拉部族再也不敢这样了。', `MaleText_loc5`='阿曼尼和贊達拉不敢再做出像這樣的事情了。', `MaleText_loc7`='Los Amani y los Zandalari nunca volverán a intentar algo así.' WHERE `ID`=51583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족을 건드리면 어떻게 되는지 볼진 님이 확실히 보여 주실 겁니다.', `MaleText_loc4`='沃金会让赞达拉部族知道一件事，那就是不要和暗矛部落作对！', `MaleText_loc5`='沃金會讓贊達拉搞清楚，別惹暗矛。', `MaleText_loc7`='Vol''jin enseñará a esos Zandalari a no meterse con los Lanza Negra.' WHERE `ID`=51584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 소름 끼치는 임무입니다. 빨리 모든 게 다 끝나서 집으로 돌아갈 수 있었으면 좋겠어요.', `MaleText_loc4`='这太可怕了，要是能快点结束回家就好了。', `MaleText_loc5`='真是太恐怖了。等事情結束，能再次回家的話我會非常高興。', `MaleText_loc7`='Eh''te es un asunto peliagudo. Me alegraré cuando termine y podamos volver a casa.' WHERE `ID`=51585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 제물과 죽음의 냄새에 뒤덮여 있습니다.$b$b당신도 붙잡히기 전에 어서 떠나는 게 나을 겁니다.
', `FemaleText_loc4`='这个地方散发着死亡和祭品的恶臭。$b$B在你成为下一个囚犯前赶快离开吧。', `FemaleText_loc5`='這地方瀰漫著死亡和犧牲的臭味。$b$b最好趁你沒變成下一個囚犯之前趕緊離開。', `FemaleText_loc7`='Eh''te lugar apeh''ta a mueh''te y sacrificios.$b$bSerá mejor que te vayas antes de que te convieh''tas en el siguiente prisionero.' WHERE `ID`=51586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구세주 여러분! 이리 와서 노르카니와 이야기 좀 합시다.', `FemaleText_loc4`='我的英雄！过来和洛尔卡尼谈谈。', `FemaleText_loc5`='我的救星!過來和諾卡尼說說話。', `FemaleText_loc7`='¡Mis libeh''tadores! Vengan aquí y hablen con Norkani.' WHERE `ID`=51587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노르카니에겐 도움이 필요합니다!
', `FemaleText_loc4`='洛尔卡尼仍然需要你的帮助！', `FemaleText_loc5`='諾卡尼還需要你的幫助!', `FemaleText_loc7`='¡Norkani todavía necesita tu ayuda!' WHERE `ID`=51588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 볼진 님께 돌아가서 보고를 올려야 합니다! 좀 꺼내 주세요!', `FemaleText_loc4`='我必须带着报告回到沃金身边！快帮我出去！', `FemaleText_loc5`='我必須回去向沃金回報!救我離開這裡!', `FemaleText_loc7`='¡Debo regresar junto a Vol''jin con mi informe! Ayúdame a salir de aquí.' WHERE `ID`=51589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 노르카니가 풀려났다!
', `FemaleText_loc4`='洛尔卡尼终于自由啦！', `FemaleText_loc5`='諾卡尼終於自由啦!', `FemaleText_loc7`='¡Por fin Norkani es libre!' WHERE `ID`=51590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 놈들이 노르카니의 물건을 어디에 뒀더라...?', `FemaleText_loc4`='他们把洛尔卡尼的东西放哪里去了？', `FemaleText_loc5`='現在呢，他們把諾卡尼的東西放在哪?', `FemaleText_loc7`='Veamos, ¿dónde han pueh''to las cosas de Norkani?' WHERE `ID`=51591;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐 떨어져 계세요...', `FemaleText_loc4`='站开点……', `FemaleText_loc5`='退開點...', `FemaleText_loc7`='No te acerques...' WHERE `ID`=51592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸 받으세요. 노르카니에겐 쓸데없는 물건입니다.', `FemaleText_loc4`='请拿着这个，洛尔卡尼不再需要这个了。', `FemaleText_loc5`='請收下這個。諾卡尼用不著這東西了。', `FemaleText_loc7`='Por favor, toma eh''to. A Norkani no le hace falta.' WHERE `ID`=51593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 우리를 나오니 정말 좋군요. 노르카니는 복수하고 말 겁니다...', `FemaleText_loc4`='能从笼子里出来真好。洛尔卡尼要复仇……', `FemaleText_loc5`='能離開那個籠子真好。諾卡尼會報仇的...', `FemaleText_loc7`='Me alegro de eh''tar fuera de esa jaula. Norkani tendrá su venganza...' WHERE `ID`=51594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 어디죠? 절 도와주러 오셨나요?', `FemaleText_loc4`='我在哪里？你是来帮忙的吗？', `FemaleText_loc5`='我在哪?你來救我的嗎?', `FemaleText_loc7`='¿Dónde eh''toy? ¿Has venido a ayudar?' WHERE `ID`=51595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 당신에게 뭔가 약을 주입했나 봅니다. 이제 괜찮습니다.', `MaleText_loc4`='他们一定是给你下药了。你现在安全了。', `MaleText_loc5`='他們一定對你用了麻醉藥。現在安全了。', `MaleText_loc7`='Han debido drogarte. Ahora es seguro.', `FemaleText_loc1`='놈들이 당신에게 뭔가 약을 주입했나 보군요. 이제 괜찮습니다.', `FemaleText_loc4`='他们一定是给你下药了。你现在安全了。', `FemaleText_loc5`='他們一定對你用了麻醉藥。現在沒事了。', `FemaleText_loc7`='Han debido drogarte. Ahora es seguro.' WHERE `ID`=51596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 제게 무슨 짓인가 한 것 같아요! 좀 도와주세요!', `FemaleText_loc4`='他们对我做了手脚！我需要帮助！', `FemaleText_loc5`='他們對我幹了什麼好事!快來幫我!', `FemaleText_loc7`='¡Me han hecho algo! ¡Necesito ayuda!' WHERE `ID`=51597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 날 잡은 놈들과 한패가 아닌 것 같군요. 좀 더 똑똑히 볼 수 있게 가까이 와주세요.', `FemaleText_loc4`='我听见你的声音了，不像是抓我的那些人。靠近点，让我看得到你。', `FemaleText_loc5`='我聽得到，我想你不是抓走我的人。靠過來點，讓我看見你。', `FemaleText_loc7`='Te he oído y creo que no formas parte de mis captores. Acércate para que pueda verte.' WHERE `ID`=51598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머리가 어지럽군요... 제발요. 저 좀 도와주세요!', `FemaleText_loc4`='我觉得头晕目眩。求你了，帮帮我！', `FemaleText_loc5`='我的腦袋還昏昏沉沉的。求你，我在求你了!', `FemaleText_loc7`='La cabeza me da vueltas. Por favor, ¡os lo suplico!' WHERE `ID`=51599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억이 돌아오는 것 같아요. 전... 뭔가 임무를 받고 여기 왔습니다... 절 꺼내 주세요. 해야 하는 일이 있어요.', `FemaleText_loc4`='我想起来了。我是来这里……完成一个任务的……救我出去，有些事情必须完成。', `FemaleText_loc5`='我想起來了，我來這是為了...進行一項任務...救我離開，我必須去完成任務。', `FemaleText_loc7`='Empiezo a recordar. Eh''taba aquí para... Una misión... Necesito ayuda. Hay cosas que tengo que hacer.' WHERE `ID`=51600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부두의 힘이여, 사라져라!', `FemaleText_loc4`='巫毒消散！', `FemaleText_loc5`='消失!巫毒消失!', `FemaleText_loc7`='¡Fuera el vudú!' WHERE `ID`=51601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부두의 힘에서 벗어나십시오!', `FemaleText_loc4`='从巫毒中解脱吧！', `FemaleText_loc5`='從巫毒之中解放吧!', `FemaleText_loc7`='¡Libérate del vudú!' WHERE `ID`=51602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 부두의 힘에서 벗어나세요!', `FemaleText_loc4`='现在，你从巫毒中被释放了！', `FemaleText_loc5`='你不再受巫毒控制了!', `FemaleText_loc7`='¡Ahora eres libre del vudú!' WHERE `ID`=51603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령이 이 사람을 우리에게 돌려보내 줄 겁니다.', `FemaleText_loc4`='愿灵魂将你带回我们身边。', `FemaleText_loc5`='靈魂們讓此人回歸我們身邊。', `FemaleText_loc7`='Eh''píritus, hagan que eh''te ser vuelva a nosotros.' WHERE `ID`=51604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와아! 살았다, 살았어, 살았다고! 오, 제가 당신을 마음 깊이 사랑하게 되었다고 말하는 게 너무 저답지 않은 말이 아니었으면 좋겠고요, 아, 가방을 찾아야 할 텐데. 당신은, 아시다시피, 절 구하시려고 엄청나게 애쓰고 고생하셨으니까 뭔가 특별한 걸 받을 자격이 있으시잖아요...', `FemaleText_loc4`='哇哈！我活下来啦，我活下来啦，我活下来啦！喔，我希望这么说不会太直白，但我真的爱死你们啦！我希望可以找到我的包裹，必须要给你们些额外的奖励，这是你们应得的。因为你们经历了那么多艰难困苦才救了我……', `FemaleText_loc5`='耶!我還活著，我還活著，我還活著耶!喔，我要告訴你們，我愛你們所有人，希望這不會太熱情啦，還有，我想找回我的袋子，你們來救我，過程中想必一路辛勞，當然要給你們點東西才對...', `FemaleText_loc7`='¡Ueee! ¡Eh''toy viva, eh''toy viva, eh''toy viva! Oh, eh''pero que no os parezca demasiado atrevido deciros que os quiero a todos y que eh''pero que pueda encontrar mi bolso porque la verdad es que os merecéis un pequeño regalito. Ya sabéis, por vueh''tro esfuerzo y todo eso a lo que habéis tenido que enfrentaros para salvarme...' WHERE `ID`=51605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 형제자매들이여. 적의 손아귀에 있는 저 사악한 탑을 빼앗을 때가 왔다.', `MaleText_loc4`='来吧，兄弟姐妹们。是时候将这座污秽的塔从敌人手中夺过来了。', `MaleText_loc5`='來吧，兄弟姊妹們。是時候從敵人手中奪取這座臭塔了。', `MaleText_loc7`='Vengan, hermanos y hermanas. Es hora de que tomemos esa nauseabunda torre de las manos de nuestros enemigos.' WHERE `ID`=51606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 압박하라! 탑을 향해 진격!', `MaleText_loc4`='前进！向尖塔前进！', `MaleText_loc5`='推進!向塔推進!', `MaleText_loc7`='¡Sigan! ¡Avanzen hacia la torre!' WHERE `ID`=51607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 우두머리가 여기 있다! 처단하라!', `MaleText_loc4`='他们的首领在这儿！快把他干掉！', `MaleText_loc5`='他們的首領在這!殺死他!', `MaleText_loc7`='¡Su líder está aquí! ¡Acaben con él!' WHERE `ID`=51608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때가 되었습니다, $c님.$b$b무엇이 그렇게 철저히 숨겨졌는지 살펴봐야겠습니다...', `FemaleText_loc4`='是时候了，$c。$b$b让我们来看看，到底是什么东西被收藏得这么隐蔽……', `FemaleText_loc5`='是時候了，$c。$b$b我們來看看是什麼東西會藏得這麼小心...', `FemaleText_loc7`='Es la hora, $c.$b$bVeamos qué es lo que ha sido escondido con tanto cuidado...' WHERE `ID`=51609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤발라의 동쪽에 뱀을 섬기는 제단이 있습니다. 제단 앞의 화톳불에 나무를 던져 넣어 주시기 바랍니다. 그러면 브웸바가 나머지 일을 처리하겠습니다.', `FemaleText_loc4`='在邦巴拉东面有一座祭祀毒蛇的神殿，我需要你去扔一些木棍到神殿前面的火堆中。剩下的就交给布温巴处理吧。', `FemaleText_loc5`='在班姆巴拉東邊，有座毒蛇的神殿，我要你丟些手杖到神殿前方的營火裡頭。然後布恩巴會處理剩下的事情。', `FemaleText_loc7`='Había un altar dedicado a las serpientes juh''to al este de Bambala, necesito que arrojes palos a la hoguera que hay delante de ese altar. Deh''pués Bwemba se encargará del reh''to.' WHERE `ID`=51610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 고대 영혼이여, 저에게 죽음도 조롱할 힘을 허락하소서!', `MaleText_loc4`='赞达拉的先祖，赐予我藐视死神的力量吧！', `MaleText_loc5`='贊達拉的先祖，請賜予此人矇騙死亡的力量吧!', `MaleText_loc7`='¡Anceh''tros de Zandalar, otorgad a eh''te ser el poder de buh''lar a la misma mueh''te!' WHERE `ID`=51611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까, 필멸자여?', `MaleText_loc4`='找我有事吗，凡人？', `MaleText_loc5`='找我有事嗎，凡人?', `MaleText_loc7`='¿Qué te trae ante mí, mortal?' WHERE `ID`=51612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='편하게 말씀하십시오, 친구여.', `MaleText_loc4`='有话直说，朋友。', `MaleText_loc5`='直言無妨，朋友。', `MaleText_loc7`='Habla sin tapujos.' WHERE `ID`=51613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 왠지... 낯이 익군요.', `MaleText_loc4`='你看起来……很眼熟。', `MaleText_loc5`='你讓我感覺...很熟悉。', `MaleText_loc7`='Algo en ti me resulta... familiar.' WHERE `ID`=51614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼렉고스여, 영원의 눈에 대한 환영이 절 괴롭힙니다. 어떻게 생각하십니까?', `MaleText_loc4`='永恒之眼里的景象一直困扰着我，卡雷苟斯。你是怎么看的？', `MaleText_loc5`='我在永恆之眼所見到的幻象仍在困擾著我，卡雷苟斯。你怎麼看呢?', `MaleText_loc7`='Kalecgos, no puedo olvidar la visión que tuve en El Ojo de la Eternidad. ¿Qué deduces de ella?', `FemaleText_loc1`='칼렉고스여, 영원의 눈에 대한 환영이 절 괴롭힙니다. 어떻게 생각하세요?', `FemaleText_loc4`='永恒之眼里的景象一直困扰着我，卡雷苟斯。你是怎么看的？', `FemaleText_loc5`='我在永恆之眼所見到的幻象仍在困擾著我，卡雷苟斯。你怎麼看呢?', `FemaleText_loc7`='Kalecgos, no puedo olvidar la visión que tuve en El Ojo de la Eternidad. ¿Qué deduces de ella?' WHERE `ID`=51615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 푸른 용군단 내부에도 큰 위기가 찾아왔습니다.$b$b곧 말리고스를 대신할 새로운 위상을 선택해야 합니다.$b$b부친의 발자취를 이으려 하는 아리고스가 마법의 힘을 지닌 모든 존재에 대한 그릇된 적개심을 새로이 불러일으키고 있습니다. 제가 생각하기에, 이 길은 우리 군단 전체를 멸망으로 이끌고 있습니다.$b$b이런 운명적인 문제를 앞에 두고 우리 군단의 의견 역시 분열되고 있으며, 아리고스는 자신의 계획을 이루기 전에는 절대로 멈추지 않을 것입니다...', `MaleText_loc4`='蓝龙军团正面临重大考验，$c。$b$b很快，我们就会推举出一位新的守护巨龙，来取代玛里苟斯。$b$b阿瑞苟斯一直希望能继承它父亲的遗志，重新展开对所有的施法者的屠杀。我能预感到，这只会让我们的族群走向灭绝。$b$b现在幸存的族人对此仍有分歧，可我担心阿瑞苟斯还是会义无反顾地走上绝路……', `MaleText_loc5`='藍龍軍團已經到了生死存亡的時刻，$c。$b$b很快的，必須選出新的魔法之王來取代瑪里苟斯的位置。$b$b亞雷戈斯想要追隨父親的腳步，以錯誤的仇恨意識對待所有魔法的使用者。我擔心這樣的方向會帶來我們種族的滅亡。$b$b我們軍團對於這個決定命運的問題上意見相當分歧，而我擔心亞雷戈斯會不擇手段地達到他的目的...', `MaleText_loc7`='Hay mucho en juego dentro del Vuelo Azul, $c.$b$bPronto deberán elegir a un nuevo Aspecto de la Magia que ocupe el lugar de Malygos.$b$bArygos aspira a seguir los pasos de su padre y renovar la errónea política de agresión contra todos aquellos que manejan la magia. Siento que ese camino conducirá al fin de nuestra especie.$b$bLos que quedan de nuestro Vuelo están divididos en este asunto y temo que Arygos no se detendrá ante nada para conseguir su objetivo...' WHERE `ID`=51616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렉고사가 누굽니까? 그녀가 없었다면 마력의 탑을 빠져나오지 못했을 겁니다.', `MaleText_loc4`='泰蕾苟萨是哪位？要没有她的话，我不可能逃出魔枢。', `MaleText_loc5`='誰是塔瑞克苟莎?沒有她，我根本不可能離開奧核之心。', `MaleText_loc7`='¿Quién es Tarecgosa? No podría haber salido de El Nexo sin su ayuda.', `FemaleText_loc1`='타렉고사가 누구죠? 그녀가 없었다면 마력의 탑을 빠져나오지 못했을 거예요.', `FemaleText_loc4`='泰蕾苟萨是哪位？要没有她的话，我不可能逃出魔枢。', `FemaleText_loc5`='誰是塔瑞克苟莎?沒有她，我根本不可能離開奧核之心。', `FemaleText_loc7`='¿Quién es Tarecgosa? No podría haber salido de El Nexo sin su ayuda.' WHERE `ID`=51617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<안타까운 듯 먼 곳을 바라보는 칼렉고스>$b$b타렉고사는... 제게 특별한 존재였습니다.$b$b그녀가 어린 용이었을 때, 난 그녀를 보호하고 가르치는 임무를 맡았었지요. 지난 수천 년간, 우리는 특별한 유대 관계를 맺었습니다. 당신들이 형제자매라고 부르는 것과 다르지 않았습니다.$b$b타렉고사는 위대한 운명을 보여주는 특별한 징후를 보이며 태어났지요. 예언이 사실이라면, 그녀가 살아남아야 푸른 용군단과 아제로스가 위기를 극복할 수 있습니다.$b$b우리 용군단 사이에서는 우리 둘의 친밀한 관계가 잘 알려져 있습니다. 당신이 본 환영이 실제 일어난 일을 보여준 것이라면, 아마 그녀는 심각한 위험에 처해 있을 것입니다.', `MaleText_loc4`='<卡雷苟斯担忧地望着远处。>$b$b对我来说，泰蕾苟萨……有着非同一般的意义。$b$b当她还是雏龙时，我负责保护并教导她。千年以来，我们之间有着特殊的纽带，类似于你们所谓的手足之情。$b$b泰蕾苟萨甫一降生，就昭示着不凡命运的开始。如果预言是真的，那么她的生死与蓝龙军团和艾泽拉斯休戚相关。$b$b余下的军团成员都知道我们之间的关系。如果你描绘的景象真的已经发生了，那么她可能已危在旦夕。', `MaleText_loc5`='<卡雷苟斯若有所思地望向地平線的另一端。>$b$b塔瑞克苟莎對我來說...很特別。$b$b當她還是隻幼龍時，我被命令要保護並教育她。千年來，我們之間形成了一種特殊的關係，像你們所說的兄妹一樣。$b$b塔瑞克苟莎生來就是有著偉大的宿命。如果預言沒有出錯，她的存活對藍龍軍團和艾澤拉斯來說都是非常重要的。$b$b我們之間的感情在我們軍團之中是眾所皆知的。如果你所見到的幻景是真正發生過的事情，那麼她很可能面臨極大的危險。', `MaleText_loc7`='<Nostálgico, Kalecgos observa el horizonte.>$b$bTarecgosa es... alguien especial para mí.$b$bCuando no era más que una prole, me encargaron que la protegiera y la educara. A lo largo de los siglos, hemos creado un vínculo especial no muy diferente a lo que ustedes llaman fraternal.$b$bTarecgosa nació bajo un signo especial que le profetizó un gran destino. Si las profecías son ciertas, su supervivencia es de vital importancia para el Vuelo Azul, y para Azeroth.$b$bLa afinidad que sentimos el uno por el otro es bien conocida entre los que quedan de nuestro Vuelo. Si tu visión relata un acontecimiento que ha ocurrido de verdad, entonces ella corre un gran peligro.' WHERE `ID`=51618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 아군이 진입로를 밀어붙이고 있습니다. 그대도 도와야 합니다.', `FemaleText_loc4`='$n，我们的部队正在向斜坡上推进。你应该去那里和他们汇合。', `FemaleText_loc5`='$n，我們的兵力正在進攻坡道。你最好去那裡幫忙。', `FemaleText_loc7`='$n, nuestras fuerzas se abren paso por la rampa. Deberías unirte a ellas allí.' WHERE `ID`=51619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 아군은 이미 탑으로 진격 중입니다. 당신도 어서 도와야 합니다.', `FemaleText_loc4`='$n，我们的部队已经推进到塔下了。你应该去那里和他们汇合，快！', `FemaleText_loc5`='$n，我們的兵力已經在進攻塔了。你應該立刻去幫忙。', `FemaleText_loc7`='$n, nuestras fuerzas ya se están abriendo paso en la torre. Deberías unirte a ellas, rápido.' WHERE `ID`=51620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 어서 공격 준비를 해야 합니다. 이곳에서 대기하다가 아군과 함께 진입로로 진격하십시오.', `FemaleText_loc4`='$n，进攻很快就能准备好。请等在这里，届时和他们一起冲上斜坡。', `FemaleText_loc5`='$n，我們的攻擊很快就會開始。在這裡等一下，並和他們一起向坡道推進。', `FemaleText_loc7`='$n, nuestro ataque debería estar listo en breve. Espera aquí y ábrete paso por la rampa con ellos.' WHERE `ID`=51621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투락, 마린, 병력을 이끌고 진입로로 진격해 탑을 빼앗아라! 서둘러야 한다!', `FemaleText_loc4`='图拉克，麦琳，带领这些部队冲上斜坡，夺下塔楼。要快！', `FemaleText_loc5`='圖拉克，馬林，帶領這些兵力向坡道推進並攻下那座塔!要快!', `FemaleText_loc7`='¡Turak, Marin, guiad a esas fuerzas por la rampa y tomad la torre! ¡Rápido!' WHERE `ID`=51622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='델드렌, 섈리스, 이들은 그대들이 이끌어야 한다. 탑으로 데려가도록.', `FemaleText_loc4`='德尔德伦、萨莉斯，这些人归你们。一定要攻下塔楼。', `FemaleText_loc5`='德爾德倫，夏莉斯，你們負責率領這些人。把塔攻下來。', `FemaleText_loc7`='Delren, Shalis, estos son sus hombres. Tomen la torre.' WHERE `ID`=51623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈드로스 관리인님, 탑을 빼앗을 수 있도록 시라와 다른 이들을 보내드리겠습니다. 엘룬께서 그대와 함께하시기를.', `FemaleText_loc4`='丛林守护者塔尔德罗斯，我派赛拉和其他人协助你攻打塔楼。愿月神与你同在。', `FemaleText_loc5`='看守者塔爾德羅斯，我要派西拉和其他人幫你攻下塔來。願伊露恩與你同在。', `FemaleText_loc7`='Vigilante Taldros, voy a enviar a Sira y a los demás contigo para que te ayuden a tomar la torre. Que Elune esté con ustedes.' WHERE `ID`=51624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 보살피시는 고대 영혼이여, 저들에게 당신의 목소리를 들려주소서!', `MaleText_loc4`='先祖与我同在！让他们听到你的声音！', `MaleText_loc5`='先祖就在我身旁，讓他們聽見祢的聲音吧!', `MaleText_loc7`='¡Los anceh''tros eh''tán de mi lado, deja que oigan tu voz!' WHERE `ID`=51625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 아군이 진입로로 진격하려고 합니다. 어서 합류하십시오.', `FemaleText_loc4`='$n，我们的部队很快就要向斜坡发起攻击。快去和他们汇合吧。', `FemaleText_loc5`='$n，我們的兵力正在進攻坡道。你最好去那裡幫忙。', `FemaleText_loc7`='$n, nuestras fuerzas están a punto de abrirse paso por la rampa. Deberías unirte a ellas.' WHERE `ID`=51626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 트롤들은 엄청난 실수를 저질렀습니다, $c님.', `FemaleText_loc4`='巨魔犯了一个巨大的错误，$c。', `FemaleText_loc5`='這些食人妖犯了很嚴重的錯誤，$c。', `FemaleText_loc7`='Esos trols han cometido un grave error, $c.' WHERE `ID`=51627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 사절을 따라갈 와이번이 필요합니다.', `MaleText_loc4`='我需要借用一头双足飞龙带我去暗矛使者那里。', `MaleText_loc5`='我需要一隻雙足飛龍載我飛去找暗矛特使。', `MaleText_loc7`='Necesito utilizar un dracoleón para volar hasta donde ha ido el emisario Lanza Negra.', `FemaleText_loc1`='검은창 사절을 따라갈 와이번이 필요해요.', `FemaleText_loc4`='我需要借用一头双足飞龙带我去暗矛使者那里。', `FemaleText_loc5`='我需要一隻雙足飛龍載我飛去找暗矛特使。', `FemaleText_loc7`='Necesito utilizar un dracoleón para volar hasta donde ha ido el emisario Lanza Negra.' WHERE `ID`=51628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염 폭주가 다가옵니다! 계속 움직여야 합니다!', `MaleText_loc4`='烈焰火雨来了！都跑起来，别停下！', `MaleText_loc5`='烈焰湧泉來了!不要停下腳步!', `MaleText_loc7`='¡Llega un Chaparrón de llamas! ¡No dejes de moverte!' WHERE `ID`=51629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 고대 영혼이여, 저들에게 어둠의 길을 보여주소서.', `MaleText_loc4`='赞达拉的先祖，标记他们，让他们走向不归之路！', `MaleText_loc5`='贊達拉的先祖，請在漆黑的道路中指引他們吧。', `MaleText_loc7`='Anceh''tros de Zandalar, marcadlos pa'' el camino oscuro.' WHERE `ID`=51630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다시 만나서 반갑습니다, $r님.', `MaleText_loc4`='啊，能再次见到你真好，$r。', `MaleText_loc5`='啊，很高興又見到你，$r。', `MaleText_loc7`='Aaah, me alegro de verte de nuevo, $r.' WHERE `ID`=51631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄 님은 미래를 보았다. 우리는 뭉쳐야 한다. 그러지 않으면 어둠이 우리를 삼킬 것이다.', `MaleText_loc4`='祖尔已经预见了未来。我们必须联合起来，否则我们必定被黑暗吞噬。', `MaleText_loc5`='祖爾看見了未來。我們要攜手並進，否則將會全數墮入黑暗。', `MaleText_loc7`='Zul ha vih''to ese futuro. Debemos ir juntos, o todos caeremos en la oscuridad.' WHERE `ID`=51632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 이것이 유일한 길이다.', `MaleText_loc4`='这是唯一的出路，兄弟们。', `MaleText_loc5`='這是唯一的道路，兄弟們。', `MaleText_loc7`='Eh''ta es la única forma, hermanos.' WHERE `ID`=51633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 피의 강에서 허우적대며 이 땅을 빼앗겼다.', `MaleText_loc4`='敌人用血淋淋的手段把这片土地从我们手中夺走。', `MaleText_loc5`='在一片腥風血雨之中，這座島從我們手中被奪走。', `MaleText_loc7`='Nos arrebataron eh''ta tierra en medio de una marea de sangre.' WHERE `ID`=51634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 위대한 트롤 제국의 푸른 주먹이 이 땅을 치고, 다시 우리 땅으로 만들 것이다.', `MaleText_loc4`='巨魔帝国的绿色铁拳将重重地粉碎这片土地，并再次将它占为己有。', `MaleText_loc5`='食人妖帝國的綠色巨拳會粉碎這塊土地，然後讓土地重回我們手中。', `MaleText_loc7`='El puño verde del imperio trol aplah''tará eh''ta tierra y la conveh''tirá en nueh''tra de nuevo.' WHERE `ID`=51635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족에겐 너희가 지금껏 보지 못한 힘이 있다. 고대 트롤의 지혜가, 마땅히 너희 것인 지혜가 있다.', `MaleText_loc4`='赞达拉拥有你前所未见的力量，以及巨魔最古老的智慧，而那智慧是你应得的。', `MaleText_loc5`='贊達拉擁有你前所未見的力量。最古老的食人妖智慧，本就該屬於你的智慧。', `MaleText_loc7`='Los Zandalari tienen poderes que no han vih''to nunca. Sabiduría de los trols más antiguos, sabiduría que les peh''tenece por derecho.' WHERE `ID`=51636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 갈라진 세상은 아직도 붕괴하고 있다, 친구여.', `MaleText_loc4`='这片支离破碎的大地还将继续粉碎下去，朋友。', `MaleText_loc5`='這個世界的破壞還沒結束呢，老兄。', `MaleText_loc7`='Eh''te mundo deh''trozado no ha terminado de romperse, colegas.' WHERE `ID`=51637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 물결이 몰려온다. 모든 트롤이 위험에 처할 것이다.', `MaleText_loc4`='黑暗的洪潮将再次淹没大地，所有的巨魔都将处于危险之中。', `MaleText_loc5`='這股黑暗浪潮將會席捲全世界，所有食人妖都將陷入危機之中。', `MaleText_loc7`='Las mareas de la oscuridad lo cubrirán todo. Todos los trols eh''tán en peligro.' WHERE `ID`=51638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 멍청이에 불과하다. 아무도 우리를 막을 순 없다.', `MaleText_loc4`='暗矛太愚蠢了，没人可以阻挡我们。', `MaleText_loc5`='暗矛部族太愚蠢了。沒人能阻擋我們。', `MaleText_loc7`='Los Lanza Negra son eh''túpidos. Nadie se interpondrá en nueh''tro camino.' WHERE `ID`=51639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이미 끝났다. 희망은 없어... 화염이 너를 삼킬 것이다!', `FemaleText_loc4`='命运早已注定。你毫无希望……烈焰将吞噬一切！', `FemaleText_loc5`='一切已成定局。你沒希望了...火焰將吞噬一切!', `FemaleText_loc7`='Ya está dispuesto. No tienen esperanza... ¡Las llamas lo consumirán todo!' WHERE `ID`=51640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너... 넌 그때 차원문에서 본... 화염의 드루이드...', `MaleText_loc4`='你……就是那个从传送门来的人——烈焰德鲁伊……', `MaleText_loc5`='你...你是從傳送門來的...火焰德魯伊...', `MaleText_loc7`='Tú... tú eres la del portal... la druida de la Llama.' WHERE `ID`=51641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 내 제자들을 몰살했다. 대가를 치르게 해 주마.', `MaleText_loc4`='你杀死了我的学生。你将为此付出代价。', `MaleText_loc5`='你殺了我許多學生。你將會付出代價。', `MaleText_loc7`='Mataste a docenas de mis estudiantes. Pagarás por lo que has hecho.' WHERE `ID`=51642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 그만!', `FemaleText_loc4`='够了！', `FemaleText_loc5`='我受夠了!', `FemaleText_loc7`='¡Ya basta!' WHERE `ID`=51643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 움직일 수가... 없어! 누가 나를 좀!', `MaleText_loc4`='这是什么？我……不能动了！谁来救救我！', `MaleText_loc5`='怎麼回事?我...我動不了了!誰來幫我!', `MaleText_loc7`='¿Qué es esto? No... puedo moverme. ¡Que alguien me ayude!' WHERE `ID`=51644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타라, 타우렌! 타올라라!', `FemaleText_loc4`='烧吧，牛头人！烧吧！', `FemaleText_loc5`='燒吧，牛頭人!燒吧!', `FemaleText_loc7`='¡Arde, tauren! ¡ARDE!' WHERE `ID`=51645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직도 모자라? 더 고통스럽게 해 줘?', `FemaleText_loc4`='你受够了吗？吃够苦头了吗？', `FemaleText_loc5`='夠不夠啊?感覺到痛了嗎?', `FemaleText_loc7`='¿No has tenido suficiente? ¿No has tenido suficiente dolor?' WHERE `ID`=51646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 한번 봐라! 아제로스 최고의 "드루이드"가 활활 타 재만 남은 모습을 보란 말이다. 이것이 바로 판드랄 스태그헬름 님의 뜻이자 화염의 뜻이다!', `FemaleText_loc4`='好好看着！这曾是艾泽拉斯最强大的“德鲁伊”，如今却空剩一具烧焦的残骸。这是范达尔·鹿盔的意志。这是烈焰的意志！', `FemaleText_loc5`='看清楚吧!艾澤拉斯最強大的德魯伊之一只剩下燒焦的軀殼。這就是范達爾·鹿盔的意志，這就是火焰的意志!', `FemaleText_loc7`='¡Mira ante ti! Uno de los "druidas" más poderosos de Azeroth reducido a un cascarón chamuscado. Tal es la voluntad de Fandral Corzocelada. ¡Tal es la voluntad de la llama!' WHERE `ID`=51647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음대로 해라. 너희의 그 소중한 타우렌 앞에서 눈물을 흘려라... 그런다고 그가 되살아나진 않을 것이다.', `FemaleText_loc4`='去吧，扑倒在你们敬爱的牛头人身上尽情哭泣吧……但我保证你们的眼泪救不了他。', `FemaleText_loc5`='去吧，去對你那寶貝的牛頭人屍體痛哭吧...但我保證你的眼淚是救不了他的。', `FemaleText_loc7`='Entonces, adelante. Llora sobre el cadáver de tu querido tauren... aunque te aseguro que tus lágrimas no lo traerán de vuelta.' WHERE `ID`=51648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훨씬 낫군요. 제게 지금 여러분을 도울 힘은 없지만, 아마니와 잔달라 놈들이 이 방에 숨겨진 보물에 대해 이야기를 나누는 걸 들은 게 기억납니다.', `FemaleText_loc4`='这样好多了。我很虚弱，但我记得听到阿曼尼和赞达拉的人提到有财宝就藏在这个房间里。', `FemaleText_loc5`='這樣好多了。我很虛弱，不過我記得聽見阿曼尼和贊達拉講到藏在房間各處的寶藏。', `FemaleText_loc7`='Eso eh''tá mucho mejor. Quizá sea débil, pero recuerdo haber oído a los Amani y a los Zandalari hablar del tesoro que hay escondido en eh''ta misma eh''tancia.' WHERE `ID`=51649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩌면 저 항아리 안에 있을지도 모르겠군요. 물러서세요!', `FemaleText_loc4`='也许在这边的瓮里。退后！', `FemaleText_loc5`='可能是藏在這邊的甕裡，退後點!', `FemaleText_loc7`='Quizá sea esa urna de ahí. ¡Atrás!' WHERE `ID`=51650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠. 이 안엔 없군요. 다른 항아리를 부숴 보죠.', `FemaleText_loc4`='呼，不是那个，让我们再试试其他的罐子。', `FemaleText_loc5`='嗯。不是這個。我們去看看其他的甕裡有沒有。', `FemaleText_loc7`='Mmm. Eh''te no es. Miremos uno de los otros jarrones.' WHERE `ID`=51651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 들어 있군요. 가서 한번 보시죠.', `FemaleText_loc4`='那里面有东西，快去看看。', `FemaleText_loc5`='那個裡面一定有東西。去看一下。', `FemaleText_loc7`='Hay algo en eh''te. Echa un vih''tazo.' WHERE `ID`=51652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 우리에서 꺼내 주셔서 감사합니다. 이제야 머리가 좀 돌아가는 것 같군요. 볼진 님께 제대로 보고드릴 수 있을 듯해요.
', `FemaleText_loc4`='你把我从笼子里救了出来，非常感谢。我神智总算逐渐清醒了，可以回去向沃金报告我掌握的情报了。', `FemaleText_loc5`='我由衷地感激你，謝謝你從籠子中把我救出來。我的意識終於清醒多了，我能夠告訴沃金我發現了什麼。', `FemaleText_loc7`='Tienes mi agradecimiento por haberme sacado de esa jaula. Eh''toy recuperando las fuerzas y pronto seré capaz de contah''le a Vol''jin todo lo que he descubieh''to.' WHERE `ID`=51653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 신경 쓰지 마세요, $r|1이여;여;. $b$b노르카니는 죽은 거나 마찬가지입니다. 아마니 놈들한테 잡히기 전에 어서 떠나세요, $r|1이여;여;.', `FemaleText_loc4`='不要管我，$r。$b$b洛尔卡尼已经难逃一死。赶快在阿曼尼抓到你之前离开，$r。', `FemaleText_loc5`='別擔心我了，$r。$b$b諾卡尼已經半隻腳踏入棺材裡了。趁阿曼尼還沒把你一起抓起來之前，離開吧$r。', `FemaleText_loc7`='No te preocupes por mí, $r.$b$bNorkani ya es como si eh''tuviera mueh''ta. Ahora vete, $r, antes de que los Amani te cojan.' WHERE `ID`=51654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 좀 꺼내 주세요, $r|1이여;여;. 먼저 절 붙잡은 아마니 사제를 처치하셔야 합니다. 놈은 절 제물로 바칠 준비를 하고 있어요!
', `FemaleText_loc4`='救我出去，$r。首先，你必须杀掉抓住我的阿曼尼祭祀，他正准备献祭我呢！', `FemaleText_loc5`='救我離開這裡，$r。你先去殺掉抓住我的阿曼尼祭司，他正準備要把我當成祭品!', `FemaleText_loc7`='Ayúdame a salir de aquí, $r. Primero, tienes que matar al sacerdote Amani que me capturó. ¡Se eh''tá preparando pa'' sacrificarme!' WHERE `ID`=51655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 검은창 정찰병입니다. 제가 보고서를 가지고 돌아갈 수 있게 저 아마니 사제를 처치해 주십시오!', `MaleText_loc4`='我是一名暗矛斥候。杀了那个阿曼尼祭祀，我就可以带着报告返回了！', `MaleText_loc5`='我是暗矛部族的斥候。除掉那名阿曼尼祭師，這樣我才能帶著報告回去覆命!', `MaleText_loc7`='Soy uno de los exploradores de los Lanza negra. ¡Mata al sacerdote Amani pa'' que pueda regresar con mi informe!' WHERE `ID`=51656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다카라가 쓰러졌다!', `MaleText_loc4`='督军倒下了！', `MaleText_loc5`='督軍死了!', `MaleText_loc7`='¡El Señor de la guerra ha caído!' WHERE `ID`=51657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 잘 들어라, 라스타칸! 또 잔달라 놈들과 함께 모든 트롤을 지배할 계획을 꾸며 보아라! 네놈이 어떤 술수를 부리든, 검은창 부족과 그 동맹이 너희를 막아낼 것이다!', `MaleText_loc4`='听着，拉斯塔哈！无论在什么情况下，暗矛部落和我们的盟友都会挺身而出，挫败你和赞达拉阴谋统治巨魔部族的邪恶计划！', `MaleText_loc5`='聽我說，拉斯塔哈!不論何時，只要你和贊達拉部族企圖統治食人妖，暗矛部族和我們的盟友們就會擋在你面前!', `MaleText_loc7`='¡Escúchame, Rastakhan! ¡Allí donde los Zandalari y tú os reunáis pa'' tramar la dominación de todos los trols os encontraréis a los Lanza Negra y a nueh''tros aliados pa'' impedih''lo!' WHERE `ID`=51658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 갈 준비가 됐습니다, 칼렉고스.', `MaleText_loc4`='我已经准备好陪你一起去了，卡雷苟斯。', `MaleText_loc5`='我準備好和你一起出發了，卡雷苟斯。', `MaleText_loc7`='Estoy preparado para acompañarte, Kalecgos.', `FemaleText_loc1`='함께 갈 준비가 됐어요, 칼렉고스.', `FemaleText_loc4`='我已经准备好陪你一起去了，卡雷苟斯。', `FemaleText_loc5`='我準備好和你一起出發了，卡雷苟斯。', `FemaleText_loc7`='Estoy preparada para acompañarte, Kalecgos.' WHERE `ID`=51659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체... 어찌 된 거지?', `MaleText_loc4`='发……发生了什么事？', `MaleText_loc5`='這...發生什麼事了?', `MaleText_loc7`='¿Qué... qué ha ocurrido?' WHERE `ID`=51660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대드루이드 님은 내게 맡기시오. 말퓨리온 님과 마토클로 님께서 급하게 그대를 찾고 계시오.', `MaleText_loc4`='$n，我会照顾大德鲁伊。玛法里奥和麦托克劳要求你即刻报到。', `MaleText_loc5`='$n，我會照顧大德魯伊。瑪法里恩跟瑪托克勞要求要和你立刻碰面。', `MaleText_loc7`='Yo me ocupo del Archidruida. Malfurion y Matogarra quieren que vayas a verlos inmediatamente.' WHERE `ID`=51661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화염 세례를 받아라!', `FemaleText_loc4`='烈焰吞没你！', `FemaleText_loc5`='蠢貨!沐浴於火焰之中吧!', `FemaleText_loc7`='¡Que la llama te impregne!' WHERE `ID`=51662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렉고사!', `MaleText_loc4`='泰蕾苟萨！', `MaleText_loc5`='塔瑞克苟莎!', `MaleText_loc7`='¡Tarecgosa!' WHERE `ID`=51663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 동지들이여! 탑은 우리 차지다! 이제 저 사악한 기념물이 무너지는 것을 봐야겠다.', `MaleText_loc4`='干得好，朋友们！这座塔是我们的了！现在，我要亲手毁了这座污秽的建筑。', `MaleText_loc5`='做得好，朋友們!塔屬於我們了!現在我要親自把這個汙穢的建築摧毀。', `MaleText_loc7`='¡Bien hecho, amigos! ¡La torre es nuestra! Ahora nos encargaremos de la destrucción de este maligno monumento!' WHERE `ID`=51664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭합니다, $n 님. 우리가 놈들을 몰아낸 것 같군요.', `FemaleText_loc4`='干的好，$n。看来我们把他们打跑了。', `FemaleText_loc5`='幹得好，$n。看來我們把他們打得抱頭鼠竄了。', `FemaleText_loc7`='Bien hecho, $n. Parece que los hemos hecho huir.' WHERE `ID`=51665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무슨 뜻이지?!', `MaleText_loc4`='这是什么意思？！', `MaleText_loc5`='這是什麼意思?!', `MaleText_loc7`='¡¿Qué significa esto?!' WHERE `ID`=51666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심는 중', `MaleText_loc4`='种植', `MaleText_loc5`='種植中', `MaleText_loc7`='Plantando', `FemaleText_loc1`='심는 중', `FemaleText_loc4`='种植', `FemaleText_loc5`='種植中', `FemaleText_loc7`='Plantando' WHERE `ID`=51667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문의 섭정께서 보내신 전언이 있습니다.', `MaleText_loc4`='我带来了银月城摄政王的口谕。', `MaleText_loc5`='銀月城的攝政王派我捎來口信。', `MaleText_loc7`='Traigo noticias del Señor regente de Lunargenta.' WHERE `ID`=51668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르 님께서 이... 추방자들이 우리 땅에 있는 이유에 대해 해명을 요구하셨습니다.', `MaleText_loc4`='为什么这个流亡者会在这里？摄政王洛瑟玛大人需要一个合理的解释。', `MaleText_loc5`='為什麼這個...流放者會出現在我們的土地上，關於這點攝政王洛索瑪·塞隆要求一個合理的解釋。', `MaleText_loc7`='Lord Lor''themar exige una explicación para la presencia de esta... exiliada en nuestras tierras.' WHERE `ID`=51669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희에게 그렇듯 내게도 쿠엘탈라스는 고향과 같다. 고대의 적에게 이 땅이 짓밟히는 꼴은 보지 않겠다. 자, 이제 너희 비겁한 섭정에게 돌아가...', `FemaleText_loc4`='奎尔萨拉斯是你的家园，同样也是我的家园。我不会任由它被我们远古的敌人攻陷。走吧，去告诉你懦弱的摄政王——', `FemaleText_loc5`='奎爾薩拉斯對你來說是家鄉，對我來說也是。我不願意看它陷落在自古以來的敵人手中。現在，去告訴你那怯弱的攝政王...', `FemaleText_loc7`='Quel''Thalas es mi hogar tanto como lo es tuyo y no quiero ver cómo cae ante nuestro antiguo enemigo. Ahora dile a tu cobarde regente...' WHERE `ID`=51670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베리사, 진정하시오!', `MaleText_loc4`='温蕾萨，拜托！', `MaleText_loc5`='拜託!凡蕾莎!', `MaleText_loc7`='¡Vereesa, por favor!' WHERE `ID`=51671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 내 초대를 받고 여기 왔다. 원정순찰대원 대부분은 멀리 나가 있고, 다시 불러들이기가 쉽지 않다. 베리사의 순찰대는 이 땅을 잘 알뿐더러 노련한 투사들이지.', `MaleText_loc4`='是我邀请她来到这里的，信使。我手下大多数远行者都在远方，无法轻易召回。温蕾萨的游侠们熟知这片土地，他们也都是经验丰富的战士。', `MaleText_loc5`='信差，她是我邀請的客人。我手下大多數的遠行者都不在這，而且要叫回來也不容易。凡蕾莎的遊俠熟悉這片土地，同時也是經驗豐富的戰鬥人員。', `MaleText_loc7`='Ella está aquí invitada por mí, mensajero. La mayoría de mis Errantes están fuera y no puedo hacerlos venir fácilmente. Las forestales de Vereesa conocen la tierra y tienen experiencia en combate.' WHERE `ID`=51672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르 님께서는 그 말에 동의하지 않으실 겁니다, 순찰대 사령관님. 당신에겐 저들을 초대할 권한이 없지...', `MaleText_loc4`='洛瑟玛大人不会赞同你的解释的，游侠将军。你无权邀请这个——', `MaleText_loc5`='遊俠將軍，攝政王洛索瑪·塞隆並不贊同你所說的。你沒有權力邀...', `MaleText_loc7`='Lord Lor''themar no está de acuerdo con tu razonamiento, General Forestal. No tienes autoridad para invitar a...' WHERE `ID`=51673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 실버문 방어군의 총사령관이며, 내가 판단하기에 필요하다면 지원군을 구할 것이다!', `MaleText_loc4`='我是银月城守备指挥官，凡是我认为有必要的援助，我不会拒绝！', `MaleText_loc5`='我是銀月城守軍的指揮官，我認為有必要的話，我自己會去尋求援手!', `MaleText_loc7`='¡Soy el comandante de las defensas de Lunargenta y buscaré ayuda donde la considere necesaria!' WHERE `ID`=51674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 볼진이여, 저 무례한 녀석이 끼어들기 직전에 그대가 잔달라 부족의 계획에 대해 이야기하고 있었던 것 같소만.', `MaleText_loc4`='让我们继续吧，沃金酋长。在被打断之前，你刚才正在向我们叙说赞达拉的计划。', `MaleText_loc5`='沃金酋長，在我們的談話被無禮地打斷之前，你正要告訴我們贊達拉在計畫些什麼。', `MaleText_loc7`='Y ahora, jefe Vol''jin, antes de que nos interrumpieran de forma tan poco educada, estabas hablándonos del plan de los Zandalari.' WHERE `ID`=51675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 잔달라 부족이 검은창 부족을 포함해 모든 트롤을 소집했소.', `MaleText_loc4`='是的。赞达拉召集了包括暗矛在内的所有巨魔氏族举行了一次集会。', `MaleText_loc5`='是的沒錯。贊達拉發起了一場會議，對象是包括暗矛在內的所有食人妖部族。', `MaleText_loc7`='Sí. Los Zandalari han convocado una reunión de todos los trols, incluidos los Lanza Negra.' WHERE `ID`=51676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라스타칸은... 모든 트롤 부족을 잔달라 아래 결집할 계획을 꾸미고 있었더군.', `MaleText_loc4`='拉斯塔哈大王，他计划将所有巨魔部族归入赞达拉的麾下。', `MaleText_loc5`='拉斯塔哈王，他正計畫著要將所有食人妖部族統合在贊達拉底下。', `MaleText_loc7`='El rey Rastakhan eh''tá planeando unir a todas las tribus trols bajo el gobierno de los Zandalari.' WHERE `ID`=51677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아마니 부족도 포함해서?', `FemaleText_loc4`='包括阿曼尼巨魔？', `FemaleText_loc5`='阿曼尼也算在內嗎?', `FemaleText_loc7`='¿Incluyendo a los Amani?' WHERE `ID`=51678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 부족, 구루바시 부족, 전부 다 포함되오. 그는 모든 부족에 사절을 보내고 있소.', `MaleText_loc4`='阿曼尼、古拉巴什、他们所有人。他将会派遣大使到各个部族。', `MaleText_loc5`='阿曼尼，古拉巴什，全都是。他正派遣特使前往各個部族。', `MaleText_loc7`='A los Amani, a los Gurubashi, a todos ellos. Eh''tá enviando emisarios a todas las tribus.' WHERE `ID`=51679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 정찰병들은 지금껏 줄아만이 잠잠하다는 보고만 했는데...', `MaleText_loc4`='我的斥候报告说祖阿曼附近没有任何动静。', `MaleText_loc5`='我手下的斥候回報，祖阿曼外圍靜悄悄地沒有任何動靜。', `MaleText_loc7`='Mis exploradores informan que reina la calma en las afueras de Zul''Aman.' WHERE `ID`=51680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 그 파괴된 도시 안에 숨어서 힘을 키우고 있었소.', `MaleText_loc4`='他们躲在城市的废墟中集结部队。', `MaleText_loc5`='他們躲在毀壞的城市重整隊形。', `MaleText_loc7`='Se han atrincherado dentro de la ciudad en ruinas. Se eh''tán reagrupando.' WHERE `ID`=51681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라스타칸은 나를 자기 형제라 부르지만, 호드야말로 우리 검은창 부족의 진정한 형제요. 놈이 달콤한 말로 다른 부족을 자기 제국에 편입시키기 전에 힘을 합쳐 놈을 막아야 하오.', `MaleText_loc4`='拉斯塔哈想跟我称兄道弟，但部落才是我真正的兄弟。我们必须阻止他，以防他继续诱骗其他部族加入他的帝国。', `MaleText_loc5`='雖然拉斯塔哈稱我為兄弟，但部落才是我真正的兄弟。我們得在他用甜言蜜語說服其他人加入他的帝國之前阻止他。', `MaleText_loc7`='Rastakhan me llama su hermano, pero es en la Horda donde eh''tán nueh''tros verdaderos hermanos. Tenemos que deteneh''le antes de que convenza a los demás pa'' que se unan a su imperio.' WHERE `ID`=51682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 이 아마니와 잔달라 동맹에 어떻게 대응하면 되겠소?', `FemaleText_loc4`='那我们该如何对付阿曼尼和赞达拉的联盟？', `FemaleText_loc5`='那麼，我們要怎樣處理阿曼尼和贊達拉聯手這件事情?', `FemaleText_loc7`='Entonces, ¿cómo vamos a enfrentarnos con esta alianza entre los Amani y los Zandalari?' WHERE `ID`=51683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애초에 동맹을 맺지 못하게 해야겠지.', `MaleText_loc4`='我们原本就该阻止这件事发生的。', `MaleText_loc5`='必須在一開始就阻止。', `MaleText_loc7`='Debemos evitar que ocurra desde el principio.' WHERE `ID`=51684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거요. 내 부하들이 도시에 잠입해 새로운 잔달라 장군에 대해 조사하고 있소.', `MaleText_loc4`='那就这样计划，我的手下将潜入那座城市，尽可能探查赞达拉新督军的底细。', `MaleText_loc5`='計畫是這樣的。我的人會潛入城市之中，盡可能收集關於這名新贊達拉督軍的情報。', `MaleText_loc7`='Eh''te es el plan. Mis hombres se infiltrarán en la ciudad y descubrirán todo lo que puedan sobre ese nuevo señor de la guerra de los Zandalari.' WHERE `ID`=51685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할두런, 검은창 정찰병의 보고에 따라 바로 움직일 수 있도록 함께 군대를 준비시켜야겠군요.', `FemaleText_loc4`='哈杜伦，我们需要把部队联合起来，根据暗矛斥候的报告做好准备。', `FemaleText_loc5`='赫杜倫，我們應該聯手，做好準備，依據暗矛斥候送來的報告採取行動。', `FemaleText_loc7`='Halduron, debemos combinar nuestras fuerzas y hacer preparativos para actuar según los informes de los exploradores Lanza Negra.' WHERE `ID`=51686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동의하오. 전령이여, 로르테마르 경에게 우리 계획에 대해 이야기해도 좋소. 하지만 앞으로 나를 방해하면 가만있지 않겠다는 점을 분명히 전하시오.', `MaleText_loc4`='同意。信使，你可以向摄政王洛瑟玛回报我们的计划。但记住，我不希望再受到干扰。', `MaleText_loc5`='我同意。信差，你可以帶個口信回去，把我們的計畫告訴攝政王洛索瑪·塞隆，不過要讓他知道，我不會再容忍任何干預。', `MaleText_loc7`='De acuerdo. Mensajero, llevarás las noticias sobre nuestros planes a Lord Lor''themar, pero deja bien claro que no pienso tolerar más intromisiones.' WHERE `ID`=51687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 위습이... 어디로 간 것 같습니다. 다른 위습을 주실 수 있습니까?', `MaleText_loc4`='我好像……把小精灵给弄丢了。能再给我一个吗？', `MaleText_loc5`='我似乎把幽光...搞丟了。還有其他的嗎?', `MaleText_loc7`='Creo que he... perdido mi fuego fatuo. ¿Hay algún otro disponible?', `FemaleText_loc1`='제 위습이... 어디로 간 것 같아요. 다른 위습을 주실 수 있나요?', `FemaleText_loc4`='我好像……把小精灵给弄丢了。能再给我一个吗？', `FemaleText_loc5`='我似乎把幽光...搞丟了。還有其他的嗎?', `FemaleText_loc7`='Creo que he... perdido mi fuego fatuo. ¿Hay algún otro disponible?' WHERE `ID`=51688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 마법의 위상이 이미 결정됐다.', `MaleText_loc4`='新的魔法守护者已经选定。', `MaleText_loc5`='新的魔法之王已經選定了。', `MaleText_loc7`='Ya ha sido elegido un nuevo Aspecto de la Magia.' WHERE `ID`=51689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 자리는 없다, 칼렉고스.', `MaleText_loc4`='你已经没有容身之处了，卡雷苟斯。', `MaleText_loc5`='這裡沒有你的位置了，卡雷苟斯。', `MaleText_loc7`='No hay sitio para ti, Kalecgos.' WHERE `ID`=51690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는... 제명이다.', `MaleText_loc4`='你……出局了。', `MaleText_loc5`='你...退下吧!', `MaleText_loc7`='Puedes... retirarte.' WHERE `ID`=51691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤엄 좀 쳐보겠나, $r?', `MaleText_loc4`='去游个泳怎么样，$r？', `MaleText_loc5`='游一下泳如何，$r?', `MaleText_loc7`='¿Te apetece nadar un poquito, $r?' WHERE `ID`=51693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같이 용암 속으로 돌아가자...', `MaleText_loc4`='和你一起回岩浆里去……', `MaleText_loc5`='回熔岩裡吧你...', `MaleText_loc7`='Pues vas de cabeza a la lava...' WHERE `ID`=51694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c! 마그마에 몸을 담글 때가 왔다!', `MaleText_loc4`='去泡泡岩浆吧，$c！', `MaleText_loc5`='去熔岩裡洗個澡吧，$c!', `MaleText_loc7`='¡Hora de un baño de magma, $c!' WHERE `ID`=51695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐에 용암을 가득 채워봐라!', `MaleText_loc4`='但愿岩浆灌进你的肺里去！', `MaleText_loc5`='用熔岩灌滿你的肺!', `MaleText_loc7`='¡Que la lava te llene los pulmones!' WHERE `ID`=51696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용암이 너를 집어삼킬 것이다, 차가운 자여!', `MaleText_loc4`='让岩浆吞噬你们吧，冷血动物！', `MaleText_loc5`='熔岩會吞沒你，冰冷的傢伙們!', `MaleText_loc7`='¡Que la lava los consuma, seres fríos!' WHERE `ID`=51697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길의 파도가 너를 집어 삼킬 것이다!', `MaleText_loc4`='让烈焰的热浪吞没你！', `MaleText_loc5`='讓火焰之浪吞沒你!', `MaleText_loc7`='¡Que las olas de llama te consuman!' WHERE `ID`=51698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령이여, 이 쓸모없는 놈을 없애 버려라!', `MaleText_loc4`='火焰之灵，消灭这只爬虫吧！', `MaleText_loc5`='火焰之靈，摧毀這隻害蟲!', `MaleText_loc7`='¡Espíritus de fuego, destruid a esta alimaña!' WHERE `ID`=51699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 불길에 휩쓸릴 것이다...', `MaleText_loc4`='让烈焰把你卷走吧……', `MaleText_loc5`='你會被火焰洗淨...', `MaleText_loc7`='La llama te borrará de la faz de la tierra...' WHERE `ID`=51700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구루바시 놈들이 물밀듯이 몰려들고 있네! 하지만 우리는 여기 고립된 채로 며칠째 외곽 전초기지로부터 아무 소식도 전달받지 못하고 있어.', `MaleText_loc4`='古拉巴什进攻者接连不断地涌来！我们被围困在这里好多天了，完全收不到来自外围哨站的情报。', `MaleText_loc5`='古拉巴什攻擊者不停地湧上來!我們被牽制在這，而且遠方哨站也好幾天沒有消息了。', `MaleText_loc7`='¡Los Gurubashi no dejan de atacar! Nos han acorralado aquí y hace días que no hemos recibido ninguna noticia de las avanzadas más alejadas.' WHERE `ID`=51701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염 덩굴손이 신이 나서 꿈틀거립니다. 당신이 찾아냈습니다!', `MaleText_loc4`='火焰鞭笞者欢快地舞动起来。你找到它了！', `MaleText_loc5`='火焰鞭笞者高興地搖擺著。你找到他了!', `MaleText_loc7`='El azotador de fuego se agita de júbilo. ¡Lo has encontrado!' WHERE `ID`=51702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신 1초 전...', `MaleText_loc4`='快躲起来，倒数1秒……', `MaleText_loc5`='數到1...', `MaleText_loc7`='Me escondo en 1...' WHERE `ID`=51703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신 2초 전...', `MaleText_loc4`='快躲起来，倒数2秒……', `MaleText_loc5`='數到2...', `MaleText_loc7`='Me escondo en 2...' WHERE `ID`=51704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신 3초 전...', `MaleText_loc4`='快躲起来，倒数3秒……', `MaleText_loc5`='數到3...', `MaleText_loc7`='Me escondo en 3...' WHERE `ID`=51705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훔쳐보기 없기!', `MaleText_loc4`='不准偷看！', `MaleText_loc5`='不准偷看!', `MaleText_loc7`='¡No vale mirar!' WHERE `ID`=51706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 제 영혼이 당신과 함께할 겁니다.', `FemaleText_loc4`='我的灵魂与你同在，$n。', `FemaleText_loc5`='我的靈魂會守護著你，$n。', `FemaleText_loc7`='Mi eh''píritu cuidará de ti, $n.' WHERE `ID`=51707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼이 되어 돌아다니는 일은 꽤 힘이 듭니다.', `FemaleText_loc4`='灵魂状态下行走并不轻松。', `FemaleText_loc5`='靈魂之行是件累人的差事。', `FemaleText_loc7`='Caminar en eh''píritu es un trabajo agotador.' WHERE `ID`=51708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애!', `MaleText_loc4`='不！！！！', `MaleText_loc5`='不!!!!', `MaleText_loc7`='¡Nooooo!' WHERE `ID`=51709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레가 물기 일보 직전입니다! 빨리 폭탄을 내려놓으십시오!', `MaleText_loc4`='蠕虫要咬人了！立刻把炸弹放下去！', `MaleText_loc5`='蟲子要咬人了!現在就放炸彈!', `MaleText_loc7`='¡El gusano está a punto de morder! ¡Coloca la bomba ahora!' WHERE `ID`=51710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3...', `MaleText_loc4`='3...', `MaleText_loc5`='3...', `MaleText_loc7`='3...' WHERE `ID`=51711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2...', `MaleText_loc4`='2...', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=51712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1...', `MaleText_loc4`='1...', `MaleText_loc5`='1...', `MaleText_loc7`='1...' WHERE `ID`=51713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스의 월식은 우리 푸른용군단이 가장 신성하게 여기는 현상입니다.', `MaleText_loc4`='艾泽拉斯的月蚀之夜是我们蓝龙军团举行大部分神圣仪式的日子。', `MaleText_loc5`='艾澤拉斯的月蝕是我們藍龍軍團認為最神聖的日子。', `MaleText_loc7`='El eclipse de las lunas de Azeroth es el acontecimiento más sagrado para los miembros del Vuelo Azul.' WHERE `ID`=51714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 어린 덩굴손이 죽은 나무에 어떤 흥미가 있는지는 잘 모르겠어요.', `FemaleText_loc4`='我也不知道这个小鞭笞者为什么要对这棵枯死的树感兴趣。', `FemaleText_loc5`='這隻小鞭笞者對這棵死樹有什麼興趣，這我也不知道。', `FemaleText_loc7`='No sé qué interés puede tener este pequeño azotador en el árbol muerto.' WHERE `ID`=51715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 제 생각에는 덩굴손이 나무를 되살리려는 것 같군요!', `FemaleText_loc4`='怎么，我看它是想复活这棵树！', `FemaleText_loc5`='什麼，我想牠想要把這棵樹給救活!', `FemaleText_loc7`='Vaya, ¡creo que está intentando revivir el árbol!' WHERE `ID`=51716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불쌍한 덩굴손 같으니... 이 나무를 되살려내기에는 너무 늦었다는 걸 모르는군요.', `FemaleText_loc4`='可怜的小家伙……它还不明白，这棵树已经没救了。', `FemaleText_loc5`='可憐的東西...牠不明白這棵樹已經無法救活了。', `FemaleText_loc7`='Pobrecito... No se da cuenta de que el árbol ya no se puede salvar.' WHERE `ID`=51717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만... 뭔가 일어나고 있어요!', `FemaleText_loc4`='等等……有情况!', `FemaleText_loc5`='等等...有狀況!', `FemaleText_loc7`='Espera... ¡algo ocurre!' WHERE `ID`=51718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이런...', `FemaleText_loc4`='噢，天呐……', `FemaleText_loc5`='噢天啊...', `FemaleText_loc7`='Ay, madre...' WHERE `ID`=51719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불가능해...', `FemaleText_loc4`='不可能……', `FemaleText_loc5`='不可能...', `FemaleText_loc7`='Imposible...' WHERE `ID`=51720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만요! 희미하기는 하지만, 아직 숨이 붙어 있는 게 느껴져요. 제가 온 힘을 다해서 살려내 볼게요.', `FemaleText_loc4`='等等！我觉得它还活着，但生命迹象很弱。我会尽全力救治它的.', `FemaleText_loc5`='等等!我感覺到他還有生命能量，但是十分微弱。我會盡我一切所能救活他。', `FemaleText_loc7`='¡Un momento! Todavía percibo vida en él, pero es muy débil. Haré todo lo que pueda para salvarlo.' WHERE `ID`=51721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 제 영혼이 당신을 따를 겁니다.', `FemaleText_loc4`='我的灵魂与你同在，$n。', `FemaleText_loc5`='我的靈魂會守護著你，$n。', `FemaleText_loc7`='Mi eh''píritu cuidará de ti, $n.' WHERE `ID`=51722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 제 영혼이 당신을 따를 겁니다.', `FemaleText_loc4`='我的灵魂与你同在，$n。', `FemaleText_loc5`='我的靈魂會守護著你，$n。', `FemaleText_loc7`='Mi eh''píritu cuidará de ti, $n.' WHERE `ID`=51723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 제때 마무리하려고 내가 여기 나와 있는거야.$b$b무법항은 해일에 입은 피해도 미처 다 복구하지 못했다고!$b$b사납게 날뛰는 트롤 패거리와 좀비 트롤만도 끔찍한데, 독사하고 미친 표범까지 우릴 공격하는 일은 없었으면 좋겠어.', `MaleText_loc4`='我到此来监督工作顺利完成。$B$b藏宝海湾仍在努力从潮汐的冲洗中恢复！$b$b这时候我们可不想遭到一大群暴怒巨魔、僵尸巨魔、毒蛇或发狂猎豹的攻击。', `MaleText_loc5`='我在此處是為了確保一切會及時完成。$b$b經歷了海嘯的藏寶海灣尚未恢復正常!$b$b我們最不需要的，就是受到成群狂暴食人妖、殭屍食人妖、大批的毒蛇或是發瘋獵豹的攻擊。', `MaleText_loc7`='Estoy aquí para asegurarme de que el trabajo se hace a tiempo.$b$b¡Bahía del Botín todavía se está recuperando del maremoto!$b$bLo último que necesitamos ahora es un ataque de una horda de trols que lo arrasan todo, trols zombis, serpientes venenosas y panteras locas.' WHERE `ID`=51724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이번 원정에서 무법항의 이익을 대변하고 있다고.$b$b이번 일이 잘못되면, 무법항에는 심각한 문제가 생길거야.$b$b아직 대격변으로 입은 피해도 다 복구하지 못했으니까.', `MaleText_loc4`='我到这里来的目的是为了确保藏宝海湾在这次探险中的利益。$b$b如果进展不顺利，藏宝海湾也会有麻烦。$b$b我们仍在努力从大灾难中恢复过来。', `MaleText_loc5`='我在這代表藏寶海灣對這次遠征表示關切之意。$b$b如果情況往不好的方面發展，藏寶海灣也會有麻煩的。$b$b大災變帶給我們的傷害尚未完全復原。', `MaleText_loc7`='Estoy aquí en representación de los intereses de Bahía del Botín en esta expedición.$b$bSi las cosas van mal, Bahía del Botín tendrá problemas.$b$bTodavía estamos recuperándonos de los acontecimientos del Cataclismo.' WHERE `ID`=51725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오 저런! 덩굴손이 결국 해내지 못했군요. 그리고 도중에 엄청난 대가를 치른 것 같아요.', `FemaleText_loc4`='噢，亲爱的！它终究还是没能挺过来。看来，它的努力让它付出了最沉重的代价。', `FemaleText_loc5`='噢天啊!看來牠還是沒有辦法做到。而且看起來牠為了嘗試付出了最大的代價。', `FemaleText_loc7`='¡Oh, vaya! Después de todo no ha podido hacerlo. Y parece que ha pagado un alto precio por intentarlo.' WHERE `ID`=51727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오렴, 아가야. 함께 전초기지로 돌아가서 이 헛된 일들은 다 잊어버리자꾸나.', `FemaleText_loc4`='来吧，小家伙。我们回营地了，忘了这个徒劳的任务吧。', `FemaleText_loc5`='來吧，小東西。我們回去營地，放棄這項沒有成果的工作。', `FemaleText_loc7`='Ven, pequeño. Regresemos al campamento y olvidemos esta tarea infructuosa.' WHERE `ID`=51728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광일 것입니다, 칼렉고스.', `MaleText_loc4`='这是我的荣幸，卡雷苟斯。', `MaleText_loc5`='這是我的榮幸，卡雷苟斯。', `MaleText_loc7`='Será un honor para mí, Kalecgos.', `FemaleText_loc1`='영광일 거예요, 칼렉고스.', `FemaleText_loc4`='这是我的荣幸，卡雷苟斯。', `FemaleText_loc5`='這是我的榮幸，卡雷苟斯。', `FemaleText_loc7`='Será un honor para mí, Kalecgos.' WHERE `ID`=51729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 그대가 정말 좋아지고 있어요.', `FemaleText_loc4`='嘿，你好啊！我真是越来越喜欢你了！', `FemaleText_loc5`='嘿，你好!我真是越來越喜歡你了。', `FemaleText_loc7`='¡Hola! La verdad es que cada vez me gustas más.' WHERE `ID`=51730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자연의 모든 것에게는 생명의 의지가 있답니다.', `FemaleText_loc4`='生存，是一切生物的本能。', `FemaleText_loc5`='任何生物都擁有生存下去的意志。', `FemaleText_loc7`='La voluntad de sobrevivir existe en la naturaleza de todas las cosas.' WHERE `ID`=51731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온이 말로른을 소환하는 동안 그의 곁에 머물러야 합니다!', `MaleText_loc4`='陪同玛法里奥召唤玛洛恩！', `MaleText_loc5`='在瑪法里恩召喚瑪洛尼時待在他的身邊!', `MaleText_loc7`='¡Permanece junto a Malfurion mientras invoca a Malorne!' WHERE `ID`=51732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님! 그 사절이 어디로 갔는지 제가 알고 있습니다.', `MaleText_loc4`='$n！我知道另一个使者到哪里去了。', `MaleText_loc5`='$n!我知道其他特使在哪。', `MaleText_loc7`='¡$n! Sé adónde ha ido el otro emisario.' WHERE `ID`=51733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 출발할 준비가 되면 말씀하십시오.', `MaleText_loc4`='准备好出发的时候告诉我，$n。', `MaleText_loc5`='你準備要出發的時候跟我說一聲，$n。', `MaleText_loc7`='Avísame cuando quieras partir, $n.' WHERE `ID`=51734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님! 그 트롤이 어디로 갔는지 제가 알고 있습니다.', `FemaleText_loc4`='$n！我知道你要找的那个巨魔去了哪里。', `FemaleText_loc5`='$n!我知道另一個食人妖在哪。', `FemaleText_loc7`='¡$n! Sé adónde ha ido el otro trol.' WHERE `ID`=51735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 출발할 준비가 되면 말씀하십시오.', `FemaleText_loc4`='准备好出发的时候跟我说话，$n。', `FemaleText_loc5`='你準備要出發的時候跟我說一聲，$n。', `FemaleText_loc7`='Habla conmigo cuando quieras partir, $n.' WHERE `ID`=51736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 랩터 오간아카가 애원하는 눈빛으로 당신을 바라봅니다.', `MaleText_loc4`='小迅猛龙奥根阿卡用恳求的眼神看着你。', `MaleText_loc5`='小迅猛龍奧根阿卡用懇求的眼神看著你。', `MaleText_loc7`='Ohgan''aka, la joven raptor, te mira con ojos suplicantes.' WHERE `ID`=51739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수집 중', `MaleText_loc4`='正在取样', `MaleText_loc5`='採樣中', `MaleText_loc7`='Tomando muestras', `FemaleText_loc1`='수집 중', `FemaleText_loc4`='正在取样', `FemaleText_loc5`='採樣中', `FemaleText_loc7`='Tomando muestras' WHERE `ID`=51740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로의 온도계측장치로 표본을 채취할 준비가 끝났습니다.', `MaleText_loc4`='索罗的温度计已经就绪，可以取样了。', `MaleText_loc5`='索羅的溫度計已經準備好，可以採集樣本了。', `MaleText_loc7`='El termómetro de Tholo está listo para tomar una muestra.', `FemaleText_loc1`='톨로의 온도계측장치로 표본을 채취할 준비가 끝났습니다.', `FemaleText_loc4`='索罗的温度计已经就绪，可以取样了。', `FemaleText_loc5`='索羅的溫度計已經準備好，可以採集樣本了。', `FemaleText_loc7`='El termómetro de Tholo está listo para tomar una muestra.' WHERE `ID`=51741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 찜통보다 더 뜨겁군요! 제 이마에다 계란 프라이를 해먹을 수도 있겠습니다.', `MaleText_loc4`='这下面比火炉还热！啊，我的脑袋上都可以煎蛋了。', `MaleText_loc5`='下面這裡熱死人了!噢，我差不多可以在我額頭上煎蛋了。', `MaleText_loc7`='¡Aquí hace más calor que dentro de un horno! Puf, podría freírme un huevo en la frente.' WHERE `ID`=51742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸의 일부가 떨어져 나가자 %s|1이;가; 앓는 소리를 냅니다!', `MaleText_loc4`='%s因肢体松动而发出了呻吟！', `MaleText_loc5`='隨著身體一部分掉落下來，%s發出悶哼聲響!', `MaleText_loc7`='¡%s gruñe cuando se desprende un gran trozo de su cuerpo!' WHERE `ID`=51743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 함께 걸어가며 불의 길을 통과하겠습니다. 불길을 저지하려면 온 힘을 다해 집중해야 하니 그대는 저를 안전하게 지켜 주셔야만 합니다.', `MaleText_loc4`='我会徒步跟着你，清理一路上的火焰。我需要集中精力，所以你一定要保护我的安全。', `MaleText_loc5`='我會和你一起步行並掃蕩這條火焰之路。我全部的心神會放在對抗火焰，所以你需要維護我的安全。', `MaleText_loc7`='Te acompañaré a pie y limpiaré el camino de llamas. Necesitaré toda mi concentración para mantener el fuego a raya, así que tendrás que asegurarte de mantenerme a salvo.' WHERE `ID`=51744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 그렇게 하겠습니다, 칼렉고스. 타렉고사를 대신해 투표하겠습니다.', `MaleText_loc4`='我愿意，卡雷苟斯。我会代表泰蕾苟萨投下这一票的。', `MaleText_loc5`='我願意，卡雷苟斯。我將代表塔瑞克苟莎投下她的一票。', `MaleText_loc7`='Estoy dipuesto, Kalecgos. Yo votaré en nombre de Tarecgosa.', `FemaleText_loc1`='기꺼이 그렇게 할게요, 칼렉고스. 타렉고사를 대신해 투표할게요.', `FemaleText_loc4`='我愿意，卡雷苟斯。我会代表泰蕾苟萨投下这一票的。', `FemaleText_loc5`='我願意，卡雷苟斯。我將代表塔瑞克苟莎投下她的一票。', `FemaleText_loc7`='Estoy dipuesta, Kalecgos. Yo votaré en nombre de Tarecgosa.' WHERE `ID`=51745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 말고 바싹 따라붙으십시오.', `MaleText_loc4`='靠近点。保持警惕。', `MaleText_loc5`='靠近點。保持警戒。', `MaleText_loc7`='No te alejes. Mantente alerta.' WHERE `ID`=51746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 지나왔습니다. 바짝 따라붙으십시오!', `MaleText_loc4`='我们就快成功了。靠近点！', `MaleText_loc5`='我們快要穿過了。靠近一點!', `MaleText_loc7`='Casi hemos pasado. ¡Mantengámonos juntos!' WHERE `ID`=51747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여! 공격!', `MaleText_loc4`='兄弟们！攻击！', `MaleText_loc5`='兄弟們!出擊!', `MaleText_loc7`='¡Hermanos! ¡Ataquen ahora!' WHERE `ID`=51748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요석 수호병이 강화 보호막 주문을 시전했습니다! 받는 피해가 줄어듭니다!', `MaleText_loc4`='黑曜石守卫者施放了刚硬之盾，所受伤害降低！', `MaleText_loc5`='黑曜防衛者施放了硬化護盾!它受到的傷害降低了!', `MaleText_loc7`='¡El defensor obsidiana ha lanzado Endurecer escudo! ¡Está recibiendo menos daño!' WHERE `ID`=51749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 몸이 조금 나아지기는 했지만, 아직 전투할 수 있는 정도는 아닙니다. 당신이 저를 호위해주시면 좋겠습니다.', `MaleText_loc4`='虽然我已经感觉好多了，可还不能战斗。我需要靠你护送了。', `MaleText_loc5`='雖然我感覺好很多了，但是我還是沒辦法進行戰鬥。我需要你護送我。', `MaleText_loc7`='Aunque ya me siento mejor, no estoy preparado para el combate. Tendrás que escoltarme.' WHERE `ID`=51750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로가 걱정됩니다.', `MaleText_loc4`='我很担心索罗。', `MaleText_loc5`='我很擔心索羅。', `MaleText_loc7`='Estoy preocupado por Tholo.' WHERE `ID`=51751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음이 가장 어렵습니다. 일단 열기 배출구까지만 가면 어디로 가야 할지 더 확실해질 겁니다.', `MaleText_loc4`='开头这段路是最困难的。等我们到热排气口那里，路就好走多了。', `MaleText_loc5`='第一個部分是最難的。等我們抵達熱能噴口，這趟路就會輕鬆許多。', `MaleText_loc7`='La primera parte es la más dura. Una vez que lleguemos a las corrientes térmicas el camino estará más despejado.' WHERE `ID`=51752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 분출구에 왔습니다! 가장자리로 간 다음 힘껏 뛰십시오! 그러면 나머지는 뜨거운 공기가 알아서 할 겁니다.', `MaleText_loc4`='这里就是第一个热排气口了！现在面对岩壁，跳！剩下的事就交给热气流吧。', `MaleText_loc5`='這是第一個噴口!面對岩臺，然後跳吧!熱氣流會解決剩下的問題。', `MaleText_loc7`='¡Aquí viene la primera corriente! ¡Acércate al borde y salta! ¡Las corrientes de aire caliente harán el resto!' WHERE `ID`=51753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장자리로 가서 뛰어오르십시오!', `MaleText_loc4`='只要面对岩壁，然后跳！', `MaleText_loc5`='反正面對岩臺，然後跳就對了!', `MaleText_loc7`='¡Acércate al borde y salta!' WHERE `ID`=51754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로! 지금 가고 있네!', `MaleText_loc4`='我来了，索罗！', `MaleText_loc5`='我來了，索羅!', `MaleText_loc7`='¡Estoy de camino, Tholo!' WHERE `ID`=51755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 정말 거의 다 왔습니다.', `MaleText_loc4`='我们就快到了。', `MaleText_loc5`='我們快要到了。', `MaleText_loc7`='Casi hemos llegado.' WHERE `ID`=51756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 이제 저는 드루이드 동지이자 소중한 친구인 톨로를 찾으러 가야 합니다.', `MaleText_loc4`='谢谢你。我得去找索罗了。他是我的德鲁伊同伴，也是我最珍贵的朋友。', `MaleText_loc5`='謝謝你。我必須去找索羅，我的德魯伊夥伴，也是我所重視的朋友。', `MaleText_loc7`='Gracias. Debo ir por Tholo, mi compañero druida y buen amigo.' WHERE `ID`=51757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 이 동굴로 들어오게 되면 열기 배출구를 꼭 기억하십시오. 급박한 상황을 벗어나게 해 줄 수도 있습니다.', `MaleText_loc4`='如果你下次再来这个洞穴，别忘记利用那些排气口。在紧急关头，它们能救你一命。', `MaleText_loc5`='如果你又來這個洞穴，別忘了這些熱能噴口。它們也許能幫你從一些險境中逃脫。', `MaleText_loc7`='Si alguna vez regresas a esta cueva, no olvides las corrientes térmicas. Podrían sacarte de algún apuro.' WHERE `ID`=51758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로... 자네 톨로 맞나?', `MaleText_loc4`='索罗……是你吗……？', `MaleText_loc5`='索羅...是你嗎...?', `MaleText_loc7`='Tholo... ¿Eres tú...?' WHERE `ID`=51759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안렌, 물 좀 드십시오. 어서 이 동굴에서 나갑시다.', `MaleText_loc4`='喝点水，安伦。我们快离开这个洞穴吧。', `MaleText_loc5`='來，喝些水，安倫。咱們先把你帶離這個洞穴吧。', `MaleText_loc7`='Toma un poco de agua, Anren. Te sacaremos de esta cueva.', `FemaleText_loc1`='안렌, 물 좀 드세요. 어서 이 동굴에서 나가요.', `FemaleText_loc4`='喝点水，安伦。我们快离开这个洞穴吧。', `FemaleText_loc5`='來，喝些水，安倫。咱們先把你帶離這個洞穴吧。', `FemaleText_loc7`='Toma un poco de agua, Anren. Te sacaremos de esta cueva.' WHERE `ID`=51760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑요석 수호병이 과부하되어 이제 폭발물에 취약해졌습니다!', `MaleText_loc4`='由于超负荷运转，黑曜石守卫者现在极易爆炸！', `MaleText_loc5`='黑曜防衛者已經超載了，現在很容易被炸藥引爆!', `MaleText_loc7`='¡El defensor obsidiana se ha sobrecargado y ahora es vulnerable a los explosivos!' WHERE `ID`=51761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보잘것없는 $r 부하를 보내 내 의견을 묻다니... 역시 말퓨리온답군.$b$b그는 언제나 그렇듯 자신이 겁쟁이라는 사실을 드러냈다.', `FemaleText_loc4`='那个玛法里奥……他只会派手下来找我。$b$b他就是个懦夫，一直都是。', `FemaleText_loc5`='那個瑪法里恩...果然又只派了一個$r手下來跟我談。$b$b他又再次證明了他只是個懦夫。', `FemaleText_loc7`='Ese Malfurion... Es tan propio de él mandar a su esbirro $r para hablar conmigo.$b$bHa demostrado ser un cobarde, como siempre.' WHERE `ID`=51762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온 님이 겁쟁이라니? 그걸 어떻게 증명할 텐가?', `MaleText_loc4`='玛法里奥是懦夫？你有什么证据吗？', `MaleText_loc5`='瑪法里恩是個孬種?這話怎麼說呢?', `MaleText_loc7`='¿Malfurion, un cobarde? ¿Cómo puedes justificar algo así?', `FemaleText_loc1`='말퓨리온 님이 겁쟁이라니? 그걸 어떻게 증명할 거지?', `FemaleText_loc4`='玛法里奥是懦夫？你有什么证据吗？', `FemaleText_loc5`='瑪法里恩是個孬種?這話怎麼說呢?', `FemaleText_loc7`='¿Malfurion, un cobarde? ¿Cómo puedes justificar algo así?' WHERE `ID`=51763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신경 쓰지 마라, $r. 화염의 드루이드와 한가족이 되었을 때, 내 과거는 모두 재가 되어 사라졌다. 네가 상관할 바가 아니다.$b$b게다가, 내가 이곳에 온 것은 이 땅의 미래를 논하기 위해서다. 너 따위와는 그런 이야길 나눌 생각이 없어.$b$b이제 대답하라... 말퓨리온은 어디에 있나!?', `FemaleText_loc4`='这不关你的事，$r。从我加入烈焰德鲁伊的那一刻起，我的过去已经在烈火中消逝了。它们对你毫无意义。$b$b而且，我来是要讨论这个王国的未来，但你并不是能与我对话的人。$b$b现在回答我……玛法里奥在哪儿！？', `FemaleText_loc5`='不用操心了，$r。我過去的一切都已經隨著加入火焰德魯伊燃燒殆盡。那些都不關你的事了。$B$B何況，我是來這裡討論這個界域的未來。而且我本來就不是打算跟你談。$b$b現在回答我，瑪法里恩在哪?', `FemaleText_loc7`='No importa, $r. Los detalles de mi pasado ardieron cuando me uní a los Druidas de la Llama. No son asunto tuyo.$b$bAdemás, he venido para hablar del futuro de este reino. Y no tengo intención de hablarlo contigo.$b$bAhora, dime... ¿Dónde está Malfurion?' WHERE `ID`=51764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온 님께서는 오지 않으셨다. 나뿐이다.', `MaleText_loc4`='玛法里奥不会来的。只有我在。', `MaleText_loc5`='瑪法里恩不會來了。只有我。', `MaleText_loc7`='Malfurion no está aquí. Solo yo.', `FemaleText_loc1`='말퓨리온 님께서는 오지 않으셨어. 나뿐이야.', `FemaleText_loc4`='玛法里奥不会来的。只有我在。', `FemaleText_loc5`='瑪法里恩不會來了。只有我。', `FemaleText_loc7`='Malfurion no está aquí. Solo yo.' WHERE `ID`=51765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 휘청이며 그의 갑옷이 산산이 흩어집니다!', `MaleText_loc4`='%s因护甲碎裂而开始蹒跚！', `MaleText_loc5`='%s的護甲粉碎，使他踉蹌了一下!', `MaleText_loc7`='¡%s se tambalea mientras su armadura se cae a pedazos!' WHERE `ID`=51766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아. 어차피 말퓨리온은 불의 땅으로 진군할 테니, 그곳에서 그를 상대해 주지. 그에 대한 심판은 며칠 정도 연기해도 좋다.$b$b<눈에 생기가 도는 레이아라>$b$b하지만 타우렌 대드루이드에게는 그런 운이 따르지 않을 것이다.', `FemaleText_loc4`='很好，就让他去火焰之地吧。我们会在那儿解决他。在接受审判之前，他可以再多活两天。$b$b<莱雅娜的眼睛亮了起来。>$b$b可那个牛头人大德鲁伊，就没那么走运了。', `FemaleText_loc5`='好吧。就讓瑪法里恩進來火源之界好了，我們會在那裡跟他做個了斷。他的審判可以再多等幾天。$b$b<雷亞拉的眼睛開始燃燒。>$b$b至於那個牛頭人大德魯伊，就沒這麼好運了。', `FemaleText_loc7`='Muy bien. Malfurion se adentrará en las Tierras de Fuego y nos encargaremos de él allí. Su juicio puede esperar un par de días más.$b$b<Los ojos de Leyara brillan.>$b$bSin embargo, el archidruida tauren no tendrá tanta suerte.' WHERE `ID`=51767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 대드루이드? 하뮬 님 말이냐?', `MaleText_loc4`='牛头人大德鲁伊？你是指哈缪尔吗？', `MaleText_loc5`='牛頭人大德魯伊?你指的是哈繆爾?', `MaleText_loc7`='¿Archidruida tauren? ¿Te refieres a Hamuul?', `FemaleText_loc1`='타우렌 대드루이드? 하뮬 님 말인가?', `FemaleText_loc4`='牛头人大德鲁伊？你是指哈缪尔吗？', `FemaleText_loc5`='牛頭人大德魯伊?你指的是哈繆爾?', `FemaleText_loc7`='¿Archidruida tauren? ¿Te refieres a Hamuul?' WHERE `ID`=51768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침략자들이 빠르게 접근하고 있습니다, 말퓨리온 님. 의식을 포기하고 전투에 참여해 주십시오!', `FemaleText_loc4`='入侵者正在迅速接近，玛法里奥。赶快中断仪式，加入战斗吧！', `FemaleText_loc5`='入侵者正在快速接近中，瑪法里恩。放棄儀式，趕快加入戰鬥!', `FemaleText_loc7`='Los invasores se acercan a toda velocidad, Malfurion. ¡Renuncia a este ritual y únete a la lucha!' WHERE `ID`=51769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투를 도와 주시면, 놈들을 물리칠 수 있습니다!', `FemaleText_loc4`='有了你的帮助，我们就能击退他们！', `FemaleText_loc5`='有你的幫助，我們能擊退他們!', `FemaleText_loc7`='¡Con tu ayuda, podremos hacerlos retroceder!' WHERE `ID`=51770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다, 마토클로. 라그나로스는 우리에게 보병만 보내고 끝낼 자가 아니다.', `MaleText_loc4`='不，麦托克劳。拉格纳罗斯不会只派几个小兵来对付我们。', `MaleText_loc5`='不，瑪托克勞。拉格納羅斯不會只派步兵來攻擊我們的。', `MaleText_loc7`='No, Matogarra. Ragnaros no se conformará con enviar a simples soldados de infantería para atacarnos.' WHERE `ID`=51771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 더 거대한 것이 오는 게 느껴진다. 살아남으려면, 말로른의 힘이 필요할 것이다.', `MaleText_loc4`='我感到有些大家伙正在靠近。如果我们想活下去，就需要玛洛恩的力量。', `MaleText_loc5`='我感覺到更大的威脅在逼近，如果想要生存下來，我們會需要瑪洛尼的力量。', `MaleText_loc7`='Siento que algo peor se acerca, y necesitaremos toda la fuerza de Malorne si queremos sobrevivir.' WHERE `ID`=51772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내심을 갖게, 마토클로. 의식이 거의 끝났네.', `MaleText_loc4`='耐心点，麦托克劳。仪式很快就要完成了。', `MaleText_loc5`='稍安勿躁，瑪托克勞。儀式快要完成了。', `MaleText_loc7`='Paciencia, Matogarra. El ritual está a punto de completarse.' WHERE `ID`=51773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 빛... 저게 뭐죠?', `FemaleText_loc4`='艾露恩在上……那是什么？', `FemaleText_loc5`='伊露恩之光啊...那是...什麼東西啊?', `FemaleText_loc7`='Por la Luz de Elune... ¿Qué es esa cosa?' WHERE `ID`=51774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 막게! 시간이 좀 더 필요하네!', `MaleText_loc4`='击退他们！我们得争取时间！', `MaleText_loc5`='阻止他們!我們得爭取更多時間!', `MaleText_loc7`='¡Debes contenerlos! ¡Necesitamos más tiempo!' WHERE `ID`=51775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라!', `MaleText_loc4`='烧吧！！！', `MaleText_loc5`='燒啊!!!!', `MaleText_loc7`='¡Ardaaaaaan!' WHERE `ID`=51776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨라! 방어선이 뚫려선 안 된다!', `MaleText_loc4`='守住阵线！绝不能让他们突破！', `MaleText_loc5`='守住陣線!別讓他們突破!', `MaleText_loc7`='¡Manténte firme! ¡No deben pasar!' WHERE `ID`=51777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 불길에 무릎 꿇어라!', `MaleText_loc4`='屈服于烈焰之灵！', `MaleText_loc5`='屈服於火焰吧。', `MaleText_loc7`='¡Sucumban a la llama viva!' WHERE `ID`=51778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서지 말게! 조금만 더 버티게!', `MaleText_loc4`='坚持住！再坚持一会儿！', `MaleText_loc5`='撐住啊!再一下就好了!', `MaleText_loc7`='¡Aguanta! ¡Solo un poco más!' WHERE `ID`=51779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 위기에 처한 푸른용군단의 운명을 결정코자 모였습니다.', `MaleText_loc4`='我们聚集于此，来决定蓝龙军团的命运。', `MaleText_loc5`='我們在此替我們不安的軍團決定命運。', `MaleText_loc7`='Nos reunimos para decidir el destino de nuestro atribulado Vuelo.' WHERE `ID`=51780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 역사는 거대한 도전의 연속이었습니다.', `MaleText_loc4`='我们的历史写满了挫折与挑战……', `MaleText_loc5`='我們的歷史面臨過艱辛的挑戰...', `MaleText_loc7`='Nuestra historia se ha forjado con grandes retos...' WHERE `ID`=51781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리 앞엔 더 큰 위협이 도사리고 있습니다.', `MaleText_loc4`='我们的未来面临着更大的威胁。', `MaleText_loc5`='我們的未來面臨更多的威脅。', `MaleText_loc7`='Nuestro futuro promete amenazas aún mayores.' WHERE `ID`=51782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위기의 시기엔 강력한 지도자가 필요합니다.', `MaleText_loc4`='我们的现状呼唤一位强有力的领袖。', `MaleText_loc5`='這樣的現況需要強力的領袖。', `MaleText_loc7`='Las circunstancias exigen un líder poderoso.' WHERE `ID`=51783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 선친의 발 옆에서 자랐습니다.', `MaleText_loc4`='我是父亲的膝下之子。', `MaleText_loc5`='我是父親一手帶大的。', `MaleText_loc7`='Me criaron a semejanza de mi padre.' WHERE `ID`=51784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선친께서 결단을 내리며 앞장서 역경을 극복하는 모습을 지켜봤습니다.', `MaleText_loc4`='我注视着他，是他引领我们在逆境中前进，从不畏缩挑战。', `MaleText_loc5`='我看著他帶領我們突破困境，碰到困難從不退縮。', `MaleText_loc7`='Lo observé mientras nos guiaba por la adversidad, y nunca vaciló al tomar decisiones difíciles.' WHERE `ID`=51785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹자는 그분을 미치광이라 했지만, 그 암울함 속에서도 의지 하나만은 확고하셨습니다.', `MaleText_loc4`='有人宣称我的父亲疯了。但即使在最黑暗的时刻，他也有着清晰的远见。', `MaleText_loc5`='有人說我父親瘋了，但就算在最低潮時，他也從未失去目標。', `MaleText_loc7`='Algunos lo tacharon de loco. Pero incluso en sus horas más oscuras, su visión era clara.' WHERE `ID`=51786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선친껜 우리 용군단이 최우선이었습니다.', `MaleText_loc4`='他永远将蓝龙军团的需要放在首位。', `MaleText_loc5`='他將藍龍的利益擺在第一位。', `MaleText_loc7`='Las necesidades de este Vuelo eran lo primero para él.' WHERE `ID`=51787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마땅히 우리가 지녀야 할 힘을 강화하여, 대격변에 대비하셨던 겁니다. 선견지명이었죠.', `MaleText_loc4`='他一直努力巩固理应属于我们的力量，以应对这场他所预见的大灾变。', `MaleText_loc5`='他想強化我們應有的力量，為他早預見到的大災變做出準備。', `MaleText_loc7`='Trató de consolidar nuestro poder legítimo y nos preparó para el Cataclismo que él vio venir.' WHERE `ID`=51788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 우리의 것은 우리가 찾아야 합니다.', `MaleText_loc4`='兄弟们，我们必须夺回属于我们的力量。', `MaleText_loc5`='兄弟們，我們必須取得屬於我們的東西。', `MaleText_loc7`='Hermanos, debemos tomar lo que es nuestro.' WHERE `ID`=51789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 지도자가 된다면, 우리 용군단은 과거의 영광을 뛰어넘어 더 원대한 미래를 향해 전진할 것입니다.', `MaleText_loc4`='在我的领导下，蓝龙军团会再次崛起，超越过去的荣光——迎接更伟大的宿命。', `MaleText_loc5`='在我的領導下，藍龍軍團將會崛起，比過去更加輝煌，邁向更加偉大的宿命。', `MaleText_loc7`='Bajo mi liderazgo, este Vuelo se alzará de nuevo, más allá de la gloria del pasado, hacia un destino aún más grande.' WHERE `ID`=51790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 그렇게 만들 것입니다!', `MaleText_loc4`='我保证！', `MaleText_loc5`='我在此做出保證!', `MaleText_loc7`='¡Yo me encargaré!' WHERE `ID`=51791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅을 공격하는데 더 지체할 시간이 없다. 가능한 한 빨리 라그나로스와 판드랄을 공격해야 한다.', `MaleText_loc4`='对火焰之地的突袭刻不容缓。我们必须尽快向拉格纳罗斯和范达尔发动反击。', `MaleText_loc5`='我們對火源之界的攻擊不能延緩。我們將儘快對拉格納羅斯和范達爾進行攻擊。', `MaleText_loc7`='Nuestro asalto a las Tierras de Fuego no puede esperar. Atacaremos a Ragnaros y a Fandral en cuanto podamos.' WHERE `ID`=51792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식은 어떻게 되어 갑니까, 말퓨리온 님?', `MaleText_loc4`='仪式进展如何，玛法里奥？', `MaleText_loc5`='儀式進行得如何，瑪法里恩?', `MaleText_loc7`='¿Cómo va el ritual, Malfurion?', `FemaleText_loc1`='의식은 어떻게 되어 갑니까, 말퓨리온 님?', `FemaleText_loc4`='仪式进展如何，玛法里奥？', `FemaleText_loc5`='儀式進行得如何，瑪法里恩?', `FemaleText_loc7`='¿Cómo va el ritual, Malfurion?' WHERE `ID`=51793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $c님. 당신이 아니었다면 여기서 목숨을 잃었을 겁니다.', `MaleText_loc4`='谢谢你，$c。要不是你的话，我恐怕已经死在这儿了。', `MaleText_loc5`='謝謝你，$c。要不是你，我一定會死掉的。', `MaleText_loc7`='Gracias, $c. Si no hubiera sido por ti, habría muerto.' WHERE `ID`=51794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다. 안전을 기하십시오, $c님.', `MaleText_loc4`='我感谢你。保重，$c。', `MaleText_loc5`='非常感謝你。願你平安，$c。', `MaleText_loc7`='Te lo agradezco. Cuídate, $c.' WHERE `ID`=51795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중 그 누가 알던 것보다도 잔혹한 하늘이군요.', `MaleText_loc4`='这里的天空比我们所知的任何地方都要危险。', `MaleText_loc5`='這裡的天空比我們原本所以為的更為危險。', `MaleText_loc7`='Estos cielos son más duros que los que cualquiera que nosotros hayamos podido conocer.' WHERE `ID`=51796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 조심하셔야 합니다. 처음 예상했던 것보다도 훨씬 위험하군요.', `MaleText_loc4`='在这儿你要小心点。这里远比看上去更危险。', `MaleText_loc5`='要當心。這裡比眼睛所見的還要來得危險許多。', `MaleText_loc7`='Ten cuidado por ahí. Es mucho más peligroso de lo que parece a primera vista.' WHERE `ID`=51797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열기류 속에 갇히지만 않았다면 도망쳤을 겁니다...', `MaleText_loc4`='要不是被卷入了一股热气流，我已经逃出去了……', `MaleText_loc5`='如果不是被其中的熱能困住，我本來可以逃掉的。', `MaleText_loc7`='Podría haber escapado si no me hubiera quedado atrapado en una de esas corrientes térmicas...' WHERE `ID`=51798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리 불꽃매가 하늘에서 저를 강타했습니다. 운이 좋게도 목숨은 건졌군요.', `MaleText_loc4`='那个怪物把我从天上打了下来。我能活下来就已经很走运了。', `MaleText_loc5`='族母把我從空中擊墜了。我還能活著算走運了。', `MaleText_loc7`='La matriarca me ha derribado del cielo. Estoy vivo de milagro.' WHERE `ID`=51799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열기류 때문에 이곳에서 나는 건 자살행위나 다름없어졌습니다. 도우러 와 주셔서 감사합니다.', `MaleText_loc4`='有那些热气流的存在，在这里飞行无异于自杀。谢谢你来帮我们。', `MaleText_loc5`='因為這些熱氣流的關係，在這飛行跟玩命沒啥兩樣。謝謝你來救我們。', `MaleText_loc7`='Esas corrientes térmicas han hecho que volar hasta aquí fuera casi un suicidio. Gracias por venir a por nosotros.' WHERE `ID`=51800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상을 회복하려면 시간이 조금 걸리겠지만, 그래도 목숨을 건져서 다행입니다.', `MaleText_loc4`='我还需要一段时间来养伤。但我还是很高兴能活下来。', `MaleText_loc5`='我會需要點時間才能從傷勢中恢復。但是，我能活下來已經很高興了。', `MaleText_loc7`='Pasará un tiempo antes de que me recupere de estas heridas. Sin embargo, me alegro de estar vivo.' WHERE `ID`=51801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빚을 졌습니다, $c님.', `MaleText_loc4`='我欠你一个人情，$c。', `MaleText_loc5`='我欠你個人情，$c。', `MaleText_loc7`='Estoy en deuda contigo, $c.', `FemaleText_loc1`='빚을 졌군요, $c님.', `FemaleText_loc4`='我欠你一个人情，$c。', `FemaleText_loc5`='我欠你個人情，$c。', `FemaleText_loc7`='Estoy en deuda contigo, $c.' WHERE `ID`=51802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘룬께 영광을! 그리고 당신에게도 영광을.', `MaleText_loc4`='赞美月神！也要赞美你。', `MaleText_loc5`='讚美伊露恩!還有你。', `MaleText_loc7`='¡Alabada sea Elune! Y tú también.', `FemaleText_loc1`='엘룬께 영광을! 그리고 당신에게도 영광을.', `FemaleText_loc4`='赞美月神！也要赞美你。', `FemaleText_loc5`='讚美伊露恩!還有你。', `FemaleText_loc7`='¡Alabada sea Elune! Y tú también.' WHERE `ID`=51803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어선에서 벗어나다니 참 어리석었습니다. 또 다른 기회를 주셔서 감사합니다.', `MaleText_loc4`='我真是个蠢货，竟然被引出了战线。谢谢你给我一个重来的机会。', `MaleText_loc5`='我居然會笨到從戰線上被引走。謝謝你又給了我一次機會。', `MaleText_loc7`='Fue una estupidez por mi parte quedarme atrapado fuera de la línea. Gracias por esta segunda oportunidad.', `FemaleText_loc1`='방어선에서 벗어나다니 참 어리석었어요. 또 다른 기회를 주셔서 감사해요.', `FemaleText_loc4`='我真是个蠢货，竟然被引出了战线。谢谢你给我一个重来的机会。', `FemaleText_loc5`='我居然會笨到從戰線上被引走。謝謝你又給了我一次機會。', `FemaleText_loc7`='Fue una estupidez por mi parte quedarme atrapada fuera de la línea. Gracias por esta segunda oportunidad.' WHERE `ID`=51804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 되돌아오겠습니다. 감사합니다, $c님.', `MaleText_loc4`='我立刻就回去。谢谢你，$c。', `MaleText_loc5`='我會立刻回去。謝謝你，$c。', `MaleText_loc7`='Regresaré inmediatamente. Gracias, $c.', `FemaleText_loc1`='곧 되돌아올게요. 감사합니다, $c님.', `FemaleText_loc4`='我立刻就回去。谢谢你，$c。', `FemaleText_loc5`='我會立刻回去。謝謝你，$c。', `FemaleText_loc7`='Regresaré inmediatamente. Gracias, $c.' WHERE `ID`=51805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 돌아갈 수 있겠군요. 고맙습니다, 친구여.', `MaleText_loc4`='我可以自己回去。谢谢你，朋友。', `MaleText_loc5`='我應該可以自己回去。謝謝你，朋友。', `MaleText_loc7`='Debería ser capaz de regresar solo. Gracias.', `FemaleText_loc1`='이제 돌아갈 수 있겠군요. 고마워요, 친구여.', `FemaleText_loc4`='我可以自己回去。谢谢你，朋友。', `FemaleText_loc5`='我應該可以自己回去。謝謝你，朋友。', `FemaleText_loc7`='Debería ser capaz de regresar sola. Gracias.' WHERE `ID`=51806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 정말 무자비하게 공격하고 있습니다. 도와주셔서 감사합니다.', `MaleText_loc4`='他们的攻击无休无止。谢谢你的帮助。', `MaleText_loc5`='他們的攻擊毫不留情。謝謝你的幫忙。', `MaleText_loc7`='Sus ataques son implacables. Gracias por tu ayuda.', `FemaleText_loc1`='적들이 정말 무자비하게 공격하고 있어요. 도와주셔서 감사해요.', `FemaleText_loc4`='他们的攻击无休无止。谢谢你的帮助。', `FemaleText_loc5`='他們的攻擊毫不留情。謝謝你的幫忙。', `FemaleText_loc7`='Sus ataques son implacables. Gracias por tu ayuda.' WHERE `ID`=51807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께 도움을 받아 큰 빚을 졌습니다. 전투가 끝난 뒤에도 가끔 저를 찾아와 주십시오.', `MaleText_loc4`='我欠你一个天大的人情。等战斗结束后，请来找我。', `MaleText_loc5`='我欠你很大的人情。在戰鬥結束後來找我吧。', `MaleText_loc7`='Te debo un agradecimiento muy especial. Búscame cuando se acabe la lucha.', `FemaleText_loc1`='당신께 도움을 받아 큰 빚을 졌군요. 전투가 끝난 뒤에도 가끔 저를 찾아와 주세요.', `FemaleText_loc4`='我欠你一个天大的人情。等战斗结束后，请来找我。', `FemaleText_loc5`='我欠你很大的人情。在戰鬥結束後來找我吧。', `FemaleText_loc7`='Te debo un agradecimiento muy especial. Búscame cuando se acabe la lucha.' WHERE `ID`=51808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장인 줄로만 알았습니다. 정말 큰 빚을 졌군요. $r님.', `MaleText_loc4`='要不是你，我就死定了。真是多亏了你，$r。', `MaleText_loc5`='我原本死定了。我欠你良多，$r。', `MaleText_loc7`='Estaba convencido de que había llegado mi fin. Te debo una, $r.', `FemaleText_loc1`='끝장인 줄로만 알았어요. 정말 큰 빚을 졌네요. $r님.', `FemaleText_loc4`='要不是你，我就死定了。真是多亏了你，$r。', `FemaleText_loc5`='我原本死定了。我欠你良多，$r。', `FemaleText_loc7`='Estaba convencida de que había llegado mi fin. Te debo una, $r.' WHERE `ID`=51809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알을 훔치자 우두머리 불꽃매가 분노에 가득 차 울부짖습니다.', `MaleText_loc4`='你的偷窃行为令火鹰鸟后愤怒地尖啸起来。', `MaleText_loc5`='火鷹族母因你的竊行而在憤怒中怒吼。', `MaleText_loc7`='La matriarca halcón de fuego chilla de ira al descubrir tu robo.' WHERE `ID`=51810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 짓을 했는지 다 봤다.', `MaleText_loc4`='我看见你了。', `MaleText_loc5`='我看到你了。', `MaleText_loc7`='Te veo.' WHERE `ID`=51811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일일 공격:', `MaleText_loc4`='日常波次：', `MaleText_loc5`='每日波數:', `MaleText_loc7`='Oleada diaria:' WHERE `ID`=51812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌진!', `MaleText_loc4`='骑兵！', `MaleText_loc5`='刺!', `MaleText_loc7`='¡Justad!' WHERE `ID`=51813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창을 들고 찔러!', `MaleText_loc4`='举起长矛，戳他！', `MaleText_loc5`='有槍，能戳!', `MaleText_loc7`='¡Tener lanza, clavar!' WHERE `ID`=51814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부화장으로 가라!', `MaleText_loc4`='你应该回孵化场去！', `MaleText_loc5`='你快去孵化室!', `MaleText_loc7`='¡Ve al criadero!' WHERE `ID`=51815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 다시 날갯짓!', `MaleText_loc4`='我们又遇上了！', `MaleText_loc5`='我們繼續擺動翅膀!', `MaleText_loc7`='¡Otra pasada!' WHERE `ID`=51816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창기병이라고? 모르는 여자야!', `MaleText_loc4`='长矛？我都不认识她！', `MaleText_loc5`='槍兵?我根本不認識她!', `MaleText_loc7`='¿Lancearla? ¡Si apenas la conocía!' WHERE `ID`=51817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 창을 받아라!', `MaleText_loc4`='长矛在我裤子里呢！', `MaleText_loc5`='褲子裡有槍!', `MaleText_loc7`='¡Lanza en los pantalones!' WHERE `ID`=51818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘의 아이들과 여인들이여! 여기서 모두 싸우고 있다!', `MaleText_loc4`='海加尔的小鬼，海加尔的女人！他们在这儿到处戳人！', `MaleText_loc5`='海加爾的老幼婦孺!大家都在扮槍兵!', `MaleText_loc7`='¡Niños de Hyjal, esposas de Hyjal! ¡Nadie escapa de las lanzas!' WHERE `ID`=51819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창백한 황혼 아래에서 악마와 창을 부딪쳐라!', `MaleText_loc4`='和苍白暮光中的魔鬼纠缠去吧！', `MaleText_loc5`='在暮光中跟惡魔一起舞槍吧!', `MaleText_loc7`='¡Lancea con el demonio a la luz del crepúsculo!' WHERE `ID`=51820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매여, 아리고스는 험난했던 우리의 과거를 얘기합니다.', `MaleText_loc4`='兄弟们，姐妹们，阿瑞苟斯谈到了我们坎坷的过去。', `MaleText_loc5`='兄弟，姐妹，亞雷戈斯說的是我們苦難的過去。', `MaleText_loc7`='Hermanos, hermanas, Arygos habla de nuestro atribulado pasado.' WHERE `ID`=51821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다. 고통스러운 과거였죠.', `MaleText_loc4`='没错，过去充满了磨难。', `MaleText_loc5`='沒錯，我們承受了無比的痛苦。', `MaleText_loc7`='Es cierto que hemos sufrido mucho.' WHERE `ID`=51822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 과거의 흉터에는 우리 자신의 책임도 있습니다.', `MaleText_loc4`='但我想说的是，我们也要对自己的伤痕担负起责任。', `MaleText_loc5`='但我主張我們必須為這些傷痕負起一部份的責任。', `MaleText_loc7`='Pero yo diría que somos en parte responsables de las cicatrices que llevamos.' WHERE `ID`=51823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 틀에서 벗어납시다.', `MaleText_loc4`='让我们改变过去的方式。', `MaleText_loc5`='讓我們改變作法。', `MaleText_loc7`='Dejemos atrás las viejas costumbres.' WHERE `ID`=51824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법을 세계에서 완전히 없애 버릴 게 아니라...', `MaleText_loc4`='放弃将魔法从这个世界中根除的想法……', `MaleText_loc5`='不再執意抹去世界上的魔法...', `MaleText_loc7`='No debemos buscar la extinción de la magia en el mundo...' WHERE `ID`=51825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스와 아제로스 주민을 위해 책임감 있게 사용합시다.', `MaleText_loc4`='……为了艾泽拉斯和所有生灵的福祉，负责地使用魔法。', `MaleText_loc5`='...而是負責任地使用它來造福艾澤拉斯和它的居民。', `MaleText_loc7`='...sino utilizarla para el beneficio de Azeroth y todos sus habitantes.' WHERE `ID`=51826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 오늘의 선택은 우리 용군단의 미래에, 그리고 이 세계의 운명에 영향을 미칠 것입니다.', `MaleText_loc4`='我们今日的选择必将改变整个蓝龙军团的宿命，甚至改变这个世界的宿命。', `MaleText_loc5`='我們今天的選擇的確會影響我們藍龍的命運，甚至全世界的命運。', `MaleText_loc7`='Es cierto que nuestra elección de hoy afectará al destino de nuestro Vuelo y, probablemente, al destino del mundo.' WHERE `ID`=51827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄이여, 우리가 현명한 선택을 내리도록 인도하소서.', `MaleText_loc4`='愿泰坦指引我们。愿我们能做出明智的抉择。', `MaleText_loc5`='願泰坦引導我們，願我們做出睿智的選擇。', `MaleText_loc7`='Que los titanes nos guíen. Que nos inspiren para decidir con sabiduría.' WHERE `ID`=51828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이지 마십시오. 안전한 곳으로 보내드리겠습니다.', `MaleText_loc4`='呆着别动。我会把你送到安全的地方。', `MaleText_loc5`='別動。我會把你帶到安全的地方。', `MaleText_loc7`='No te muevas. Te pondré a salvo.' WHERE `ID`=51829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 제가 잡았습니다.', `MaleText_loc4`='别担心。我抓住你了。', `MaleText_loc5`='別擔心，我抓住你了。', `MaleText_loc7`='No te preocupes. Estoy contigo.' WHERE `ID`=51830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무모하게 굴지 마십시오. 아직 그대는 목숨을 잃으면 안 됩니다.', `MaleText_loc4`='别那么着急。你不会那么巧死在我们背上的。', `MaleText_loc5`='放心，我們不會讓你就這樣在我們手上死掉的。', `MaleText_loc7`='No tan rápido. No te estás muriendo, aún no.' WHERE `ID`=51831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발걸음을 주의하십시오. 조심해야 합니다.', `MaleText_loc4`='上面的落脚点很危险。小心点。', `MaleText_loc5`='想爬到上面會有點棘手。小心點。', `MaleText_loc7`='Es un terreno peligroso el de ahí arriba. Ten cuidado.' WHERE `ID`=51832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 섬으로 되돌려보내 드리겠습니다. 이 열기류를 빠져나가기만 하면 됩니다...', `MaleText_loc4`='我会尝试把你送回岛上。只要能穿过这些热气流就行……', `MaleText_loc5`='我會試著把你帶回島上。我們只需要穿過這些熱能...', `MaleText_loc7`='Intentaré llevarte de vuelta a la isla. Solo tenemos que conseguir pasar esas corrientes térmicas...' WHERE `ID`=51833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 잡으십시오, 이곳의 기류는 더없이 위험합니다.', `MaleText_loc4`='抓紧了，这里的气流很危险。', `MaleText_loc5`='抓緊了，空中的氣流十分致命。', `MaleText_loc7`='Agárrate fuerte, las corrientes de aire de por ahí son mortales.' WHERE `ID`=51834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 이렇게 잃기에는 너무나도 소중한 존재입니다.', `MaleText_loc4`='你对我们至关重要，绝对不能这样轻易死掉。', `MaleText_loc5`='你對我們來說太過重要，我們不會如此輕易讓你送命。', `MaleText_loc7`='Eres demasiado importante para nosotros como para que te perdamos tan fácilmente.' WHERE `ID`=51835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올라갑니다.', `MaleText_loc4`='上去了。', `MaleText_loc5`='要往上飛了。', `MaleText_loc7`='Arriba.' WHERE `ID`=51836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펜던트 안의 기억이 끔찍한 고통과 고뇌로 소용돌이치고 있소... 어떤 기억인지 확인해 봅시다.', `MaleText_loc4`='这个坠饰里填满了伤恸的回忆。如此痛苦，如此悲哀……来看看它想告诉我们什么。', `MaleText_loc5`='這個墜盒裡的記憶在痛苦中打轉。如此強烈的苦難...來看看它想告訴我們什麼。', `MaleText_loc7`='Los recuerdos de este guardapelo se retuercen de angustia. Tanto dolor y sufrimiento... Veamos qué nos muestra.' WHERE `ID`=51837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구지? 저자는 판드랄 스태그헬름의 외아들 발스탄인 것 같소. 뭘 하고 있는 거지? 혹시 이건 퀴라지 전쟁?', `MaleText_loc4`='这是谁？好像是瓦斯坦恩，范达尔·鹿盔唯一的儿子。他在做什么？这是其拉之战的回忆吗？', `MaleText_loc5`='這是誰?看起來像是瓦爾斯坦，范達爾·鹿盔的獨子。他在做什麼?這是其拉戰爭的記憶嗎?', `MaleText_loc7`='¿Quién es? Parece Valstann, el único hijo de Fandral Corzocelada. ¿Qué hace? ¿Es un recuerdo de la Guerra qiraji?' WHERE `ID`=51838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞소! 이것은 천 년 전 실리더스 대전쟁의 기억이오. 발스탄은 동족을 구하려다 적에게 붙잡혀... 죽었소.', `MaleText_loc4`='没错！这是千年之前在希利苏斯发生的大战。瓦斯坦恩为族人而战，却不幸被俘……殒命敌手。', `MaleText_loc5`='沒錯!那場希利蘇斯的大戰發生在一千年前。瓦爾斯坦想救他的人民，但是被抓到...被殺害了。', `MaleText_loc7`='¡Lo es! La gran guerra de Silithus se desató hace mil años. Valstann intentó salvar a su gente, pero fue capturado... y asesinado.' WHERE `ID`=51839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 정말 끔찍하오. 레이아라가 왜 이 기억에 매달릴까? 발스탄이 그녀의 삶에 중요했나 보오...', `MaleText_loc4`='哦……这太可怕了。为什么莱雅娜会执着于这段回忆？瓦斯坦恩一定是个对她非常重要的人……', `MaleText_loc5`='噢，這真是糟糕。雷亞拉為什麼要保留這份記憶?瓦爾斯坦對她來說一定很重要...', `MaleText_loc7`='Oh, esto es terrible. ¿Por qué Leyara se aferraría a este recuerdo? Valstann tuvo que ser alguien importante en su vida...' WHERE `ID`=51840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 흘러도, 그 아이를 잃은 아픔은 가시지 않는구나.', `MaleText_loc4`='时光流逝，丧子之痛却不会消褪。', `MaleText_loc5`='時光飛逝，但他的死仍痛徹心扉。', `MaleText_loc7`='El tiempo pasa, pero el dolor por su muerte no desaparece.' WHERE `ID`=51841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발스탄, 내 사랑. 왜 그리 일찍 떠났나요?', `FemaleText_loc4`='瓦斯坦恩，亲爱的丈夫，你离开得太早了。', `FemaleText_loc5`='瓦爾斯坦，親愛的丈夫，你走得太早了。', `FemaleText_loc7`='Valstann, mi querido esposo, nos dejaste tan pronto.' WHERE `ID`=51842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이아라, 이제 내겐 너희 둘뿐이다. 맹세하마. 내가 살아 있는 한, 너와 손녀 아이는 내가 항상 지켜 주겠다.', `MaleText_loc4`='莱雅娜，我只剩下你们俩了。我向你发誓，终我一生，我将始终守护你和我的孙女。', `MaleText_loc5`='雷亞拉，我只剩你們兩個親人了。我以生命起誓，永遠會保護你和我的孫女。', `MaleText_loc7`='Leyara, ustedes son lo único que me queda. Juro por mi vida que mi nieta y tú SIEMPRE contarán con mi protección.' WHERE `ID`=51843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이스타리아, 이 엄마가 너무 약해 널 구하지 못했구나.', `FemaleText_loc4`='我想要救你，伊丝塔瑞亚，但我太弱了。', `FemaleText_loc5`='我想要保住你，伊塔莉雅，但是我太弱了。', `FemaleText_loc7`='Intenté salvarte, Istaria, pero era demasiado débil.' WHERE `ID`=51844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판드랄 님이 계셨다면 호드의 침략 따윈 없었을 거야! 말퓨리온 님은 우릴 위해 뭘 했지? 아무것도 안 했어!', `FemaleText_loc4`='范达尔决不会允许部落攻击我们的家园！玛法里奥派谁来保护我们了？谁也没来！', `FemaleText_loc5`='范達爾才不會眼睜睜看著部落攻擊我們家園!而瑪法里恩有幫上什麼忙嗎?沒有!', `FemaleText_loc7`='¡Fandral nunca hubiera permitido que la Horda atacara nuestro hogar! ¿A quién ha enviado Malfurion para defendernos? ¡A nadie!' WHERE `ID`=51845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같아도 그렇게 화가 났을 거야.', `MaleText_loc4`='你的愤怒并非受到误导。', `MaleText_loc5`='你的確應該感到憤怒。', `MaleText_loc7`='Tu ira no está desencaminada.' WHERE `ID`=51846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구냐?', `FemaleText_loc4`='谁在那儿？', `FemaleText_loc5`='是誰?', `FemaleText_loc7`='¿Quién anda ahí?' WHERE `ID`=51847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 고통을 나누는 자. 너에게 고통을 어루만질 힘을 주는 자.', `MaleText_loc4`='与你有着同样伤痛的人。能助你缓解伤痛的人。', `MaleText_loc5`='和你一樣痛苦的人。想給你力量減輕痛苦的人。', `MaleText_loc7`='Alguien que comparte tu dolor. Alguien que te ofrece el poder para mitigarlo.' WHERE `ID`=51848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판드랄 님! 탈옥하신 건가요?', `FemaleText_loc4`='范达尔！你从监狱中逃出来了？', `FemaleText_loc5`='范達爾!你逃出來了?', `FemaleText_loc7`='¡Fandral! ¿Escapaste de tu prisión?' WHERE `ID`=51849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 도와 줄 새로운 친구들을 만났다. 이렇게 늦게 와서 미안하구나.', `MaleText_loc4`='新的盟友拯救了我。没能早点到你身边，我很抱歉。', `MaleText_loc5`='一些...新盟友救了我。很遺憾不能早點前來找你。', `MaleText_loc7`='Me rescataron unos nuevos aliados. Siento no haber venido antes.' WHERE `ID`=51850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 힘은 뭐죠? 어떻게 되신 거죠?', `FemaleText_loc4`='这是什么力量？你变成了什么？', `FemaleText_loc5`='這是什麼力量?你怎麼變這樣?', `FemaleText_loc7`='¿Qué es ese poder? ¿En qué te has convertido?' WHERE `ID`=51851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘야, 곧 알게 될 것이다. 나와 함께 가자. 힘을 합쳐, 우리를 업신여긴 자들에게 복수하자꾸나...', `MaleText_loc4`='时间会让你明白一切，我的孩子。随我来吧，一起向那些错怪我们的人复仇……', `MaleText_loc5`='你會學到的，女兒。跟我來吧。我們可以聯手報復那些害我們的人...', `MaleText_loc7`='Aprenderás en su momento, hija mía. Ven conmigo. Juntos, nos vengaremos de aquellos que han sido injustos con nosotros...' WHERE `ID`=51852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 아이가 태어났어요. 딸이에요! 예쁜 우리 공주님.', `FemaleText_loc4`='我们的孩子刚出生。是个女孩！多漂亮的女儿。', `FemaleText_loc5`='我把孩子生下來了。是個女孩!一個漂亮的女孩。', `FemaleText_loc7`='Nuestra hija ha nacido. ¡Es una niña! Una niña hermosa.' WHERE `ID`=51853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이스타리아로 이름 지었어요. 눈이 당신을 닮았어요.', `FemaleText_loc4`='我给她取名叫伊丝塔瑞亚。她的眼睛跟你的像极了。', `FemaleText_loc5`='她叫伊塔莉雅。她的眼睛好像你。', `FemaleText_loc7`='La he llamado Istaria. Tiene tus ojos.' WHERE `ID`=51854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들! 넬타리온 님이 가만두지 않으리라!', `MaleText_loc4`='蠢货！奈萨里奥会杀了你们！', `MaleText_loc5`='蠢貨!奈薩里奧會殺光你們!', `MaleText_loc7`='¡Estúpidos! ¡Que Neltharion acabe con todos!' WHERE `ID`=51855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='레이아라가 고개를 끄덕입니다.', `FemaleText_loc4`='莱雅娜点了点头。', `FemaleText_loc5`='雷亞拉點了點頭。', `FemaleText_loc7`='Leyara asiente.' WHERE `ID`=51856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트롤들이 갑자기 나타나 도움을 청했습니다.', `MaleText_loc4`='这些巨魔突然出现，向我们寻求帮助。', `MaleText_loc5`='那些食人妖突然出現，劈頭就要我們幫忙。', `MaleText_loc7`='Acaban de aparecer estos trols en busca de ayuda.' WHERE `ID`=51857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트롤들이 무슨 말을 하는지 도무지 이해할 수가 없습니다.', `MaleText_loc4`='我几乎不明白这些巨魔想说什么。', `MaleText_loc5`='我不太明白那些食人妖到底想說什麼。', `MaleText_loc7`='Apenas puedo entender lo que dicen estos trols.' WHERE `ID`=51858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트롤들이 자기 문제를 스스로 해결하지 않는 이유가 무엇일까요?', `MaleText_loc4`='这些巨魔就不能自己解决自己的问题吗？', `MaleText_loc5`='那些食人妖幹嘛不自己搞定自己的問題?', `MaleText_loc7`='¿Por qué estos trols no solucionan sus problemas ellos mismos?' WHERE `ID`=51859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 트롤은 주위의 참상을 보며 콧노래를 흥얼거립니다.>', `MaleText_loc4`='<那巨魔看着周围成堆的尸体，自顾自地唱着歌。>', `MaleText_loc5`='<這個食人妖一面對著自己哼歌一面仔細看著周圍那場屠殺。>', `MaleText_loc7`='<El trol canta para sí mismo mientras observa la masacre que le rodea.>' WHERE `ID`=51861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다.', `MaleText_loc4`='多谢相助。', `MaleText_loc5`='謝謝你的幫忙。', `MaleText_loc7`='Gracias por ayudarme.', `FemaleText_loc1`='도와주셔서 고마워요.', `FemaleText_loc4`='多谢相助。', `FemaleText_loc5`='謝謝你的幫忙。', `FemaleText_loc7`='Gracias por ayudarme.' WHERE `ID`=51862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨을 구해주셨군요!', `MaleText_loc4`='你救了我一命！', `MaleText_loc5`='你救了我一命!', `MaleText_loc7`='¡Me has salvado la vida!', `FemaleText_loc1`='제 목숨을 구해주셨어요!', `FemaleText_loc4`='你救了我一命！', `FemaleText_loc5`='你救了我一命!', `FemaleText_loc7`='¡Me has salvado la vida!' WHERE `ID`=51863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브웸바, 당신입니까? 구해 주셔서 감사합니다.', `MaleText_loc4`='布温巴，是你吗？多谢相救。', `MaleText_loc5`='布恩巴，是你嗎?謝謝你救了我。', `MaleText_loc7`='¿Bwemba, eres tú? Gracias por salvarme.', `FemaleText_loc1`='브웸바, 당신인가요? 구해 주셔서 고마워요.', `FemaleText_loc4`='布温巴，是你吗？多谢相救。', `FemaleText_loc5`='布恩巴，是你嗎?謝謝你救了我。', `FemaleText_loc7`='¿Bwemba, eres tú? Gracias por salvarme.' WHERE `ID`=51864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방에 온통... 독사가 가득합니다!', `MaleText_loc4`='毒蛇！到处都是毒蛇！', `MaleText_loc5`='到處都是蛇!', `MaleText_loc7`='¡Las serpientes, eh''tán por todas pah''tes!', `FemaleText_loc1`='사방에 온통... 독사가 가득해요!', `FemaleText_loc4`='毒蛇！到处都是毒蛇！', `FemaleText_loc5`='到處都是蛇!', `FemaleText_loc7`='¡Las serpientes, eh''tán por todas pah''tes!' WHERE `ID`=51865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독사들이 우릴 압도했습니다.', `MaleText_loc4`='毒蛇群淹没了我们。', `MaleText_loc5`='我們被蛇群擊潰。', `MaleText_loc7`='Las serpientes nos superaron.', `FemaleText_loc1`='독사들이 우릴 압도했어요.', `FemaleText_loc4`='毒蛇群淹没了我们。', `FemaleText_loc5`='我們被蛇群擊潰。', `FemaleText_loc7`='Las serpientes nos superaron.' WHERE `ID`=51866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 이 정글에서 최후를 맞으리라고 생각했습니다.', `MaleText_loc4`='我还以为我要死在这丛林里了。', `MaleText_loc5`='我還以為我會死在這座叢林咧。', `MaleText_loc7`='Creía que iba a morir en eh''ta jungla.', `FemaleText_loc1`='전 이 정글에서 최후를 맞으리라고 생각했어요.', `FemaleText_loc4`='我还以为我要死在这丛林里了。', `FemaleText_loc5`='我還以為我會死在這座叢林咧。', `FemaleText_loc7`='Creía que iba a morir en eh''ta jungla.' WHERE `ID`=51867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정령이 절 굽어살피시고 계십니다.', `MaleText_loc4`='灵魂在今天眷顾了我。', `MaleText_loc5`='靈魂今天守護著我。', `MaleText_loc7`='Hoy los eh''píritus cuidan de mí.', `FemaleText_loc1`='오늘은 정령이 절 굽어살피시고 계세요.', `FemaleText_loc4`='灵魂在今天眷顾了我。', `FemaleText_loc5`='靈魂今天守護著我。', `FemaleText_loc7`='Hoy los eh''píritus cuidan de mí.' WHERE `ID`=51868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 목숨을 구해 주셔서 감사합니다.', `MaleText_loc4`='多谢救我一命。', `MaleText_loc5`='謝謝你救我一命。', `MaleText_loc7`='Gracias por salvarme la vida.', `FemaleText_loc1`='제 목숨을 구해 주셔서 고마워요.', `FemaleText_loc4`='多谢救我一命。', `FemaleText_loc5`='謝謝你救我一命。', `FemaleText_loc7`='Gracias por salvarme la vida.' WHERE `ID`=51869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 망설일 시간이 없습니다.$b$b제 푸른용군단이 혼란에 빠져 지휘자가 절실한 상황입니다.', `MaleText_loc4`='我们不能再浪费时间了，朋友。$b$b我们整个军团群龙无首，急需新的领袖。', `MaleText_loc5`='不能浪費時間了，朋友。$b$b我的軍團陷入了混亂，急需有人來領導。', `MaleText_loc7`='No hay tiempo que perder, $gamigo:amiga;.$b$bEl caos reina en mi Vuelo. Necesitamos un líder desesperadamente.' WHERE `ID`=51870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 해내서 다행입니다, $n 님.', `FemaleText_loc4`='你做到了，$n，我很高兴。', `FemaleText_loc5`='很高興你能來到這裡，$n。', `FemaleText_loc7`='Me alegro de que lo consiguieras, $n.' WHERE `ID`=51871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녹아내린 용암에 오신 것을 환영합니다, $n 님.', `FemaleText_loc4`='欢迎来到熔火激流，$n。', `FemaleText_loc5`='歡迎來到熔岩之流，$n。', `FemaleText_loc7`='Te doy la bienvenida a La Corriente de Magma, $n.' WHERE `ID`=51872;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 앞에 있는 불꽃꼬리 일족들은 온 힘을 다해 덤벼들고 있습니다. 그곳에 가면 조심하셔야 합니다.', `FemaleText_loc4`='前边的火妖可不是吃素的。小心点。', `FemaleText_loc5`='前方的喚焰者不是好惹的。要小心點。', `FemaleText_loc7`='Los despiertallamas de ahí delante son un asunto serio. Ten cuidado.' WHERE `ID`=51873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞에는 열기 배출구가 많습니다, $n 님. 문제가 생기면 언제든지 배출구를 사용하십시오.', `FemaleText_loc4`='前面有很多热排气口，$n。如果你不小心陷入困境，可以利用它们来脱困。', `FemaleText_loc5`='前面有很多熱能噴口，$n。如果你陷入麻煩，盡量使用它們。', `FemaleText_loc7`='Tendremos un montón de corrientes térmicas ahí delante, $n. No dudes en usarlas si te ves en un aprieto.' WHERE `ID`=51874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동굴 뒤편에 길을 잃은 드루이드가 있는 것 같습니다, $n 님. 그곳을 살펴봐 주십시오.', `FemaleText_loc4`='洞穴的深处恐怕有一个迷失的德鲁伊，$n。你千万要小心。', `FemaleText_loc5`='我擔心洞穴深處可能有個走失的德魯伊，$n。保持警覺。', `FemaleText_loc7`='Temo que pueda haber un druida perdido en lo más profundo de la cueva, $n. Abre bien los ojos.' WHERE `ID`=51875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 갑옷이 활화산에 의해 약해집니다.', `MaleText_loc4`='%s的护甲被活跃的火山削弱了。', `MaleText_loc5`='%s的護甲開始被噴發的火山削弱了。', `MaleText_loc7`='La armadura de %s se ha debilitado debido al volcán activo.' WHERE `ID`=51876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 한 명의 사절도 항상 세계를 구하기 위해 노력한답니다!', `FemaleText_loc4`='另一个使者，他总是想着拯救世界！', `FemaleText_loc5`='另一名特使一直都在試著拯救這個世界!', `FemaleText_loc7`='El otro emisario, ¡siempre eh''tá intentando salvar el mundo!' WHERE `ID`=51877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 한 명의 사절이 이 정글에서 가보지 않은 곳이 있을까요?', `FemaleText_loc4`='另一名使者是不是已经踏遍了整个丛林？', `FemaleText_loc5`='在這片叢林之中，有哪些地方是那名特使還沒去過的?', `FemaleText_loc7`='¿En qué pah''te de la jungla no ha eh''tado el otro emisario?' WHERE `ID`=51878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 우리가 얼마나 끔찍한 일에 휘말린 걸까요?', `FemaleText_loc4`='我们这是陷入了何等困境？', `FemaleText_loc5`='我們到底是碰上怎樣的麻煩呀?', `FemaleText_loc7`='¿En qué lío nos hemos metido?' WHERE `ID`=51879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만도키르는 랩터를 정말로 사랑합니다.', `FemaleText_loc4`='曼多基尔一定很爱他的迅猛龙。', `FemaleText_loc5`='曼多基爾當然很愛他那些迅猛龍。', `FemaleText_loc7`='Eh''tá claro que Mandokir adora a sus raptores.' WHERE `ID`=51880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마치 혈군주가 구루바시 전사들을 이끄는 것 같았습니다.', `FemaleText_loc4`='血领主，看来是他监督着古拉巴什的勇士们。', `FemaleText_loc5`='看起來血領主他正在巡視那些古拉巴什戰士。', `FemaleText_loc7`='Parece ser que el señor sangriento eh''tá supervisando a los guerreros Gurubashi.' WHERE `ID`=51881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 그대가 이루어내신 업적은 모든 푸른용의 기억 속에 영원히 살아 숨 쉴 것입니다.', `FemaleText_loc4`='每一头蓝龙都会铭记你的英勇事迹，$n。', `FemaleText_loc5`='你的作為將會永遠活在每一隻藍龍的記憶之中，$n。', `FemaleText_loc7`='Tus hazañas vivirán eternamente en la memoria de todos los dragones Azules, $n.' WHERE `ID`=51882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할리고사, 의식에 참여할 준비가 됐습니다.', `MaleText_loc4`='我已经准备好要参加典礼了，赫雷苟萨。', `MaleText_loc5`='我已經準備好參與儀式了，哈勒苟莎。', `MaleText_loc7`='Estoy listo para participar en la ceremonia, Hallegosa.', `FemaleText_loc1`='할리고사, 의식에 참여할 준비가 됐어요.', `FemaleText_loc4`='我已经准备好要参加典礼了，赫雷苟萨。', `FemaleText_loc5`='我已經準備好參與儀式了，哈勒苟莎。', `FemaleText_loc7`='Estoy lista para participar en la ceremonia, Hallegosa.' WHERE `ID`=51883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='따라오십시오, $n 님. 그대를 위한 의식이 준비되었습니다.', `FemaleText_loc4`='跟我走，$n。我们已经为你准备了一场典礼。', `FemaleText_loc5`='跟我來，$n。我們為你準備了一場慶祝儀式。', `FemaleText_loc7`='Sígueme, $n. Hemos preparado una ceremonia en tu honor.' WHERE `ID`=51884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다. 당장은 안전하겠지만, 시간이 별로 없다.', `MaleText_loc4`='干得好，我们暂时安全了，但时间并不多。', `MaleText_loc5`='做得好。我們應該暫時安全了，但時間很緊迫。', `MaleText_loc7`='Bien hecho. Deberíamos estar seguros por el momento, pero no tenemos mucho tiempo.' WHERE `ID`=51887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 씨앗이 뿌리를 내리리라. 시간과 정성을 쏟으면, 이 척박한 땅에도 안식처를 마련할 수 있을 것이다.', `MaleText_loc4`='埋下种子，希望扎根。悉心守护，生机萌发。我们将在这个灼热世界里建立一个庇护所。', `MaleText_loc5`='我們用這顆種子扎根。只要有足夠的時間照料它，我們就能在這焦黑的敵境棲息。', `MaleText_loc7`='Con esta semilla, echamos raíces. Con tiempo y cuidados, haremos crecer verdor en este reino hostil y carbonizado.' WHERE `ID`=51888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 우리는 정령들의 공격에 굳게 맞서 싸운다!', `MaleText_loc4`='我们将在此坚守，抵挡元素大军的进攻。', `MaleText_loc5`='我們將在此對元素的猛攻嚴陣以待。', `MaleText_loc7`='Aquí nos mantendremos firmes contra el embate de los elementos.' WHERE `ID`=51889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 라그나로스 군대의 주의를 끄는 동안, 나머지 아군 병력이 놈의 심장부를 칠 것이다.', `MaleText_loc4`='我们要吸引拉格纳罗斯军队的注意，好让其他人直捣火焰王国的腹地。', `MaleText_loc5`='我們在這裡牽制拉格納羅斯的軍隊，讓其他人直闖他領土的心臟地帶。', `MaleText_loc7`='Aquí llamaremos la atención del ejército de Ragnaros para que otros puedan atacar el corazón de su reino.' WHERE `ID`=51890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 전쟁은 시작됐다.', `MaleText_loc4`='战争，已经打响了。', `MaleText_loc5`='現在，戰爭揭開序幕了。', `MaleText_loc7`='Y ahora, comienza la guerra.' WHERE `ID`=51891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님, 이 원반에 서 계십시오. 칼렉고스가 오고 있습니다!', `FemaleText_loc4`='站到这个圆台上，$p。卡雷苟斯过来了！', `FemaleText_loc5`='站在這個圓盤上，$p。卡雷苟斯來了!', `FemaleText_loc7`='Colócate encima de este disco, $p. ¡Kalecgos se acerca!' WHERE `ID`=51892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오래된 무덤은 흐트러짐 없이 평화로운 모습입니다.', `MaleText_loc4`='这是个古老、宁静又安详的墓地。', `MaleText_loc5`='這個墳墓十分老舊、寧靜，許久未受到外界的干擾。', `MaleText_loc7`='La tumba es vieja y emana paz y tranquilidad.' WHERE `ID`=51893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기에 그을린 펜던트를 내놓습니다.', `MaleText_loc4`='拿出烟熏过的坠饰。', `MaleText_loc5`='拿出覆滿煙塵的墜盒。', `MaleText_loc7`='Muestra el guardapelo manchado de humo.', `FemaleText_loc1`='연기에 그을린 펜던트를 내놓습니다.', `FemaleText_loc4`='拿出烟熏过的坠饰。', `FemaleText_loc5`='拿出覆滿煙塵的墜盒。', `FemaleText_loc7`='Muestra el guardapelo manchado de humo.' WHERE `ID`=51894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 분명히 묘비가 맞지만, 이 아래 누가 묻혀 있는지 분명하게 표시되어 있지는 않습니다.', `MaleText_loc4`='虽然这里显然是座坟墓，可没有写明葬在这里的是什么人。', `MaleText_loc5`='雖然這很明顯是墳墓的標記，但卻不清楚是誰埋葬在這裡。', `MaleText_loc7`='A pesar de que claramente esto es una lápida, es difícil saber quién está enterrado aquí.' WHERE `ID`=51895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 요리 기술을 가르쳐 드릴 수 있습니다.

배우고 싶으신가요?', `MaleText_loc4`='我可以传授烹饪的艺术。

你想学吗？', `MaleText_loc5`='我可以教導烹飪的技藝。

你想要學嗎?', `MaleText_loc7`='Puedo enseñarte el arte de la cocina.

¿Quieres aprender?', `FemaleText_loc1`='제가 요리 기술을 가르쳐 드릴 수 있습니다.

배우고 싶으신가요?', `FemaleText_loc4`='我可以传授烹饪的艺术。

你想学吗？', `FemaleText_loc5`='我可以教導烹飪的技藝。

你想要學嗎?', `FemaleText_loc7`='Puedo enseñarte el arte de la cocina.

¿Quieres aprender?' WHERE `ID`=51896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오십시오. 기다리고 있었습니다.', `MaleText_loc4`='欢迎你，我们一直在等你。', `MaleText_loc5`='歡迎你，朋友。我們正在等你。', `MaleText_loc7`='Te damos la bienvenida. Te esperábamos.' WHERE `ID`=51897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 불의 땅에서 눈부신 활약을 펼쳤습니다.', `MaleText_loc4`='祝贺你在火焰之地所取得的胜利。', `MaleText_loc5`='恭喜你在火源之界獲得的成功。', `MaleText_loc7`='Te felicitamos por tu éxito en las Tierras de Fuego.' WHERE `ID`=51898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 그냥 칭찬으론 부족합니다.', `MaleText_loc4`='但只有称赞是不够的。', `MaleText_loc5`='但光是讚美是不夠的。', `MaleText_loc7`='Pero solo el elogio no es suficiente.' WHERE `ID`=51899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 덕분에 우리 용군단의 운명을 바로잡을 수 있었습니다.', `MaleText_loc4`='你改变了蓝龙军团的宿命，我们对你感激不尽。', `MaleText_loc5`='你影響了藍龍軍團的命運，我們欠你很大的人情。', `MaleText_loc7`='Te debemos mucho por el papel que has jugado en el destino de nuestro Vuelo.' WHERE `ID`=51900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지팡이를 주십시오. 그것에 엄청난 힘을 불어넣겠습니다.', `MaleText_loc4`='请把你的法杖交给我，我们能够赋予它更强大的力量。', `MaleText_loc5`='把你的法杖交給我，讓我們注入強大的力量。', `MaleText_loc7`='Muéstrame tu bastón, que dotaremos de gran poder.' WHERE `ID`=51901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 제단은 곧 무너집니다! 다른 곳으로 뛰십시오!', `MaleText_loc4`='这个平台要塌了！跳到别的平台上去！', `MaleText_loc5`='平台要崩塌了!快跳到另外一個平台上!', `MaleText_loc7`='¡La plataforma está a punto de desmoronarse! ¡Salta a otra!', `FemaleText_loc1`='이 제단은 곧 무너집니다! 다른 곳으로 뛰십시오!', `FemaleText_loc4`='这个平台要塌了！跳到别的平台上去！', `FemaleText_loc5`='平台要崩塌了!快跳到另外一個平台上!', `FemaleText_loc7`='¡La plataforma está a punto de desmoronarse! ¡Salta a otra!' WHERE `ID`=51902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이 아래는 정말 뜨거워요. 제 화덕을 가져올 필요도 없었다니까요.', `FemaleText_loc4`='天呐，这里可真热。我连熔炉都可以不用带了。', `FemaleText_loc5`='噢天啊，這裡的確很熱。我甚至不需要自己帶熔爐過來。', `FemaleText_loc7`='Vaya, sí que hace calor aquí abajo. Ni siquiera me ha hecho falta traer mi propia forja.' WHERE `ID`=51903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저쪽에 있는 섬에는 흑요암 생물체들이 득실거려요! 제가 직접 가 보고 싶지만, 저는 다리를 건널 수가 없답니다.', `FemaleText_loc4`='那边那座岛上到处都是黑曜石生物！我本该自己去的，可又过不了那座桥。', `FemaleText_loc5`='那個島上到處都是那些黑曜石生物!我是想自己去那裡，但是我過不了橋。', `FemaleText_loc7`='¡Esa isla de allá está llena de criaturas de obsidium! Iría yo misma, pero no puedo cruzar el puente.' WHERE `ID`=51904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 투사들을 보고 있는 게 아닙니다. 그건 전투교관이 할 일이죠.

제가 신경 쓰는 건 투사들의 상처를 돌보는 두 명의 초보 간호병입니다. 지금까진 제 학생들이 잘 해내고 있는 것 같군요.', `MaleText_loc4`='我不是来监督战士们的，那是训练员的责任。

我关注的是那两个新来的医护人员。到目前为止，我的学生表现还不错。', `MaleText_loc5`='我並不負責照看那些戰士，那是訓練員的工作。

我只關心那兩個負責治療他們的見習牧師。我的學生們目前做得還不錯。', `MaleText_loc7`='No observo a los luchadores, eso es trabajo de los maestros de combate.

Mi responsabilidad son los dos neófitos cuyo trabajo es sanarlos. Por el momento, mis estudiantes lo están haciendo bien.' WHERE `ID`=51905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 불량배들이 즐겨 쓰는 위험한 장난감이 내 손에 들려 있는 거 나도 잘 아네.

자, 뭐가 필요한가?', `MaleText_loc4`='哦，没错。我拿了点蜡烛。

那么，你想要点什么呢？', `MaleText_loc5`='噢，是的。我拿了那個小無賴的蠟燭。

所以呢，你需要什麼嗎?', `MaleText_loc7`='Ah, sí. Cogí la vela de ese granujilla.

Bien, ¿qué necesitas?' WHERE `ID`=51906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 찾았나? 한판 싸워 보자!', `MaleText_loc4`='你找我？我们打架！', `MaleText_loc5`='想找我?那開打吧!', `MaleText_loc7`='¿Me están buscando? ¡Luchemos entonces!' WHERE `ID`=51909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배자!', `MaleText_loc4`='压碎了！', `MaleText_loc5`='碾碎!', `MaleText_loc7`='¡Aplastado!' WHERE `ID`=51910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해빠진 놈!', `MaleText_loc4`='你真弱！', `MaleText_loc5`='你很弱!', `MaleText_loc7`='¡Eres débil!' WHERE `ID`=51911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 간다, 이 꼬맹이 놈아!', `MaleText_loc4`='我来抓你了，小凡人！', `MaleText_loc5`='我來找你了，小傢伙!', `MaleText_loc7`='¡VOY POR TI, MORTAL INSIGNIFICANTE!' WHERE `ID`=51912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡고 말 테다, 이 꼬맹아!', `MaleText_loc4`='我会抓住你，小东西！', `MaleText_loc5`='我會抓到你，小不點!', `MaleText_loc7`='¡Te atraparé, gusano!' WHERE `ID`=51913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이! 도망칠 수 없다!', `MaleText_loc4`='懦夫！你逃不掉！', `MaleText_loc5`='懦夫!你跑不掉的!', `MaleText_loc7`='¡Cobarde! ¡No puedes huir!' WHERE `ID`=51914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 넌 구루바시의 분노를 벗어날 수 없어!', `MaleText_loc4`='不！你躲不开古拉巴什之怒的！', `MaleText_loc5`='不!你無法逃過古拉巴什的怒火!', `MaleText_loc7`='¡No! ¡No escaparás a la ira de los Gurubashi!' WHERE `ID`=51915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리렉의 방랑은... 끝났다...', `MaleText_loc4`='格里雷克……不再游荡了……', `MaleText_loc5`='格里雷克...不再流浪...', `MaleText_loc7`='Gri''lek ya no... vagará...' WHERE `ID`=51916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 잠에서 깨어난 걸 뼈저리게 후회하게 해 주마!', `MaleText_loc4`='今天，你会希望再也不要从梦中醒来！', `MaleText_loc5`='今天，你會後悔你沒有好好躺在床上!', `MaleText_loc7`='¡Hoy, desearán no haberse levantado de la cama!' WHERE `ID`=51917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 것. 이제는 꿈을 꾸지 않겠지...', `MaleText_loc4`='可怜。死后你就不能做梦了……', `MaleText_loc5`='可憐。死掉就沒辦法做夢了...', `MaleText_loc7`='Lástima. Una vez muerto, dejarás de soñar…' WHERE `ID`=51918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그렇게... 눈을 감는 거야...', `MaleText_loc4`='听话……闭上眼睛吧……', `MaleText_loc5`='乖，乖...閉眼睡覺覺...', `MaleText_loc7`='Ya, ya... cierra los ojos…' WHERE `ID`=51919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 악몽에 어떤 공포가 도사리는지 볼까?', `MaleText_loc4`='瞧瞧藏在你噩梦中的恐惧吧！', `MaleText_loc5`='我們來看看你惡夢裡有什麼恐怖的東西!', `MaleText_loc7`='¡Veamos los horrores que habitan en tus pesadillas!' WHERE `ID`=51920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 게 더 끔찍할까?... 영영 꿈속을 헤매는 것, 아니면 악몽 같은 현실을 사는 것?', `MaleText_loc4`='长梦不醒，或是噩梦成真，让我们瞧瞧究竟是哪种更恐怖！', `MaleText_loc5`='看看哪個比較可怕...是睡著的惡夢，還是醒著的惡夢!', `MaleText_loc7`='Veamos qué es más terrorífico... Soñar para siempre, ¡o despertar en una pesadilla viviente!' WHERE `ID`=51921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠들어라... 또 다른 꿈이 너희를 기다린다...', `MaleText_loc4`='睡吧……另一个梦境在等着你……', `MaleText_loc5`='睡吧...另一場夢正等待著你...', `MaleText_loc7`='Duerme... Otro sueño te aguarda…' WHERE `ID`=51922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내 영혼은 꿈꾸지 않으리...', `MaleText_loc4`='我的灵魂再也不会做梦了……', `MaleText_loc5`='我的靈魂不再做夢...', `MaleText_loc7`='Mi espíritu ya no sueña…' WHERE `ID`=51923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내, 당신이 소중히 품어 주신 사랑하는 우리의 누이 타렉고사가... 이 지팡이를 자신의 영원한 보금자리로 선택했습니다.', `MaleText_loc4`='最终，泰蕾苟萨，我们挚爱的姐妹，她选择了你的法杖作为其精魄的永久栖息地。', `MaleText_loc5`='最後，塔瑞克苟莎，我們姊妹的精華由你幫忙帶著，而她選擇了這把法杖做為永久的居所。', `MaleText_loc7`='Finalmente Tarecgosa, nuestra amada hermana con cuya esencia has cargado generosamente, ha elegido habitar en este bastón.' WHERE `ID`=51924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 오늘 새로운 칼 한 자루를 또 수집하겠군...', `MaleText_loc4`='啊……今天我又能多收藏一把利刃了……', `MaleText_loc5`='啊...我今天又能多一把收藏品了...', `MaleText_loc7`='Aaaah... Hoy añadiré una nueva hoja a mi colección...' WHERE `ID`=51925;
