UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부디 목소리를 낮추세요. 우리가 뭘 연구하는지 여군주 프라우드무어에게 들켜서 좋을 거 하나도 없으니까요.

자, 진정한 힘에 대해 좀 얘기해볼까요...?', `FemaleText_loc4`='拜托，小声点。最好别让普罗德摩尔女士知道我们在研究什么东西。

那么，我们现在能来谈谈“真正”的力量了吗……？', `FemaleText_loc5`='拜託，小聲一點。提醒普勞德摩爾女士我們在研究的東西不是明智之舉。

現在，我們是不是該來談談「真實」的力量...?', `FemaleText_loc7`='Por favor, baja la voz. No es muy sabio recordar a Lady Valiente el tipo de cosas que estudiamos aquí.
Y bien, ¿hablamos de poder VERDADERO...?' WHERE `ID`=51957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 전차들이 다 완성되어 가니 조금 지루하군요!

혹시 기계공학자 아니세요? 저랑 설계도를 비교해 보는 건 어때요...?', `MaleText_loc4`='随着所有的攻城坦克接近完工，我开始觉得有点无聊了！

你不是工程师吧？愿意来比下图纸吗……', `MaleText_loc5`='所有的攻城機具都快完成了，害我覺得很無聊!

你不會是工程師吧?要幫忙比對藍圖嗎?', `MaleText_loc7`='Con eso de que las máquinas de asedio están casi terminadas, estoy empezando a aburrirme.

No te dedicarás a la ingeniería, ¿verdad? ¿Te apetece que comparemos planos...?' WHERE `ID`=51958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주방에 온 걸 환영하오!

먹을 걸 구하러 오셨소, 아니면 요리를 하러 오셨소?', `MaleText_loc4`='欢迎来到我的厨房！

你是想来买吃的呢，还是想来自己做点儿？', `MaleText_loc5`='歡迎來到我的廚房!

你是來找食物的，還是來親自下廚的?', `MaleText_loc7`='¡Te doy la bienvenida a mi cocina!

¿Has venido en busca de buena comida o quieres cocinar tú?' WHERE `ID`=51959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 원래는 탐험가 연맹의 일원이었죠.

그런데 어느 날 깨달았답니다. 제가 정말로 찾고 싶어하는 유일한 물건은 바로 보석이라는 걸요.

크고, 빛나고, 다채롭고, 값비싼 보석 말입니다... 아, 얼마나 사랑스러운지!', `MaleText_loc4`='你知道，我曾是探险者协会的成员。

可后来我才发现，我其实只对宝石感兴趣。

硕大、璀璨、艳丽、珍贵的宝石……噢，我是多么爱它呀！', `MaleText_loc5`='我曾經在探險者協會裡，你知道吧。

但是我後來發現我真正感興趣的只有寶石。

大顆的，閃亮的，彩色的，貴重的寶石...噢，我愛死你們了。', `MaleText_loc7`='Yo antes estaba en la Liga de Expedicionarios, sabes.

Pero me di cuenta de que, en realidad, las GEMAS eran lo único que me interesaba buscar.

Gemas grandes, relucientes, coloridas y valiosas... Oh, ¡cómo me gustan!' WHERE `ID`=51960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 그녀가 당신에게 힘을 주는 든든한 벗이 되길.', `MaleText_loc4`='希望她的陪伴能带给你鼓舞与宽慰。', `MaleText_loc5`='願她的存在能為你帶來助力，並陪伴你。', `MaleText_loc7`='Que su presencia sea fuente de consuelo y compañía para ti.' WHERE `ID`=51961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 푸른용군단의 친구여.', `MaleText_loc4`='我们感谢你，蓝龙军团的挚友。', `MaleText_loc5`='我們感謝你，藍龍軍團的朋友。', `MaleText_loc7`='Te damos las gracias, amigo del Vuelo Azul.' WHERE `ID`=51962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 보고 계십니까? 네, 저를 보세요. 저를 보셔야 할 겁니다. 보고 계시나요? 절 보고 계시냐니까요? 좋습니다.', `MaleText_loc4`='你是在看我吗？很好，看着我，就该看着我。你还在看我吗？很好。', `MaleText_loc5`='你在看我嗎?對，看著我。你應該要看著我才對。你有嗎?你有注視著我嗎?很好。', `MaleText_loc7`='¿Me estás mirando? Sí, mírame. Deberías estar mirandome. ¿Lo estás haciendo? ¿Mirarme? Bien.' WHERE `ID`=51963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별보라! 왜 별보라여야만 했나요?', `MaleText_loc4`='烁影！为什么是烁影呢！', `MaleText_loc5`='閃閃!為什麼會是閃閃?', `MaleText_loc7`='¡Centella! ¿Por qué Centella?' WHERE `ID`=51964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저이는 아주 보석에 미쳤다니까요. 하지만 전 저이를 사랑해요. 자기가 가장 좋아하는 보석은 바로 저라나요? 호호!

자, 제가 어떻게 도와드리면 될까요? 아마도 고고학 문제겠죠?', `FemaleText_loc4`='他是个宝石狂人，一点没说错，可我还是爱他。他说过，我是他最爱的那颗宝石，嘻嘻！

那么，我能帮你什么忙呢？是有关考古学的事，对吗？', `FemaleText_loc5`='他瘋狂地熱愛寶石，沒錯，但是我愛他。他說我是他的寶石中他最愛的一顆，嘻!

話說，我能幫你什麼忙?考古學，對吧?', `FemaleText_loc7`='Está loco por las gemas, sí, pero le adoro. ¡Dice que yo soy su gema favorita, jejeje!

Bueno, ¿en qué puedo ayudarte? Arqueología, ¿no?' WHERE `ID`=51966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 깜짝하면, 넌 그냥 먼지가 되는 거야...', `MaleText_loc4`='弹指间，你就灰飞烟灭啦……', `MaleText_loc5`='電光一閃，你就化為塵埃...', `MaleText_loc7`='En un instante, no serás más que polvo…' WHERE `ID`=51967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<지팡이가 신비로운 기운에 휩싸여 진동합니다.>', `MaleText_loc4`='<这根法杖充盈着奥术的能量。>', `MaleText_loc5`='<法杖發出了秘法能量的脈動。>', `MaleText_loc7`='<El bastón palpita con energías Arcanas.>' WHERE `ID`=51968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기만 있다면야 습지대만큼 가죽 구하기 좋은 곳도 없소. 악어가 득시글대니 말이오. 우리 형제는 여기 좀 머무를 생각이오.

내가 도와줄 일이라도 있소?', `MaleText_loc4`='沼泽盛产优质皮革，如果你够胆进去找的话。里面有很多鳄鱼。我和我兄弟就打算在这里呆一段时间。

有什么要我帮忙的吗？', `MaleText_loc5`='沼澤裡面好毛皮可不少，但是你的膽子得要夠大。很多鱷魚。我跟我兄弟應該會多待一會。

我能幫你什麼嗎?', `MaleText_loc7`='Hay buenas pieles en los pantanos, si tienes las agallas para conseguirlas. Montones de crocoliscos. Creo que mi hermano y yo nos quedaremos una temporada.

¿Puedo ayudarte con algo?' WHERE `ID`=51969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱거운 놈!', `MaleText_loc4`='你，毫无价值！', `MaleText_loc5`='你這廢物!', `MaleText_loc7`='¡No eres nadie!' WHERE `ID`=51970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 진도를 막을쏘냐!', `MaleText_loc4`='没人能阻止金度！', `MaleText_loc5`='沒人可以阻止金度!', `MaleText_loc7`='¡NADIE detendrá a Jin''do!' WHERE `ID`=51971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싱거운 놈!', `MaleText_loc4`='你，毫无价值！', `MaleText_loc5`='你這廢物!', `MaleText_loc7`='¡No eres nada!' WHERE `ID`=51972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성가신 버러지들! 자, 이제 내 분노를 느껴 봐라!', `MaleText_loc4`='多管闲事的虫子！面对我的愤怒吧！', `MaleText_loc5`='煩人的蟲子!現在讓你嘗嘗我的怒火!', `MaleText_loc7`='¡Insectos entrometidos! ¡Ahora van a sentir mi ira!' WHERE `ID`=51973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가거라, 벌레들아. 네놈들은 나중에 처리해 주겠다.', `MaleText_loc4`='滚吧，虫子们。下一次我再对付你们。', `MaleText_loc5`='哼，蟲子。我下次再收拾你們。', `MaleText_loc7`='Son libres, insectos. Me ocuparé de ustedes en otra ocasión.' WHERE `ID`=51975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 속임수는 용납할 수 없다, 진도. 감히 대놓고 신을 모욕하다니!', `MaleText_loc4`='你的欺骗是不可饶恕的，金度。你亵渎了你的神明！', `MaleText_loc5`='你的欺騙是不可原諒的，金度。你竟然敢侮辱神!', `MaleText_loc7`='Tu mentira es imperdonable, Jin''do. ¡Escupes en el rostro de un dios!' WHERE `ID`=51976;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대에게 자연의 축복이 있기를.', `FemaleText_loc4`='愿大自然保佑你。', `FemaleText_loc5`='自然祝福你。', `FemaleText_loc7`='La bendición de la naturaleza cae sobre ti.' WHERE `ID`=51977;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불과 맞서 싸우는 데 도움이 필요한가? 좋아. 어서 시작하자.', `FemaleText_loc4`='你需要我的火力支援？很好，我们直接说正事吧。', `FemaleText_loc5`='你需要幫忙解決一些火焰?好吧，我們切入重點。', `FemaleText_loc7`='¿Necesitas ayuda con algunos fuegos? Muy bien, manos a la obra.' WHERE `ID`=51978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 난 당신 곁에서 싸우겠소.', `MaleText_loc4`='今天，我们将并肩战斗。', `MaleText_loc5`='今天，我與你並肩作戰。', `MaleText_loc7`='Hoy lucharé a tu lado.' WHERE `ID`=51979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 당신이 오늘 내 지휘관이군. 아주 좋소.', `MaleText_loc4`='那么，今天你就是我的指挥官了。很好。', `MaleText_loc5`='所以你今天是我的指揮官。好吧。', `MaleText_loc7`='Así que hoy serás mi comandante. Muy bien.' WHERE `ID`=51980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 갑시다.', `MaleText_loc4`='我们一起上。', `MaleText_loc5`='我們動手吧。', `MaleText_loc7`='Vamos allá.' WHERE `ID`=51981;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의사가... 왔습니다요!', `FemaleText_loc4`='医生……来了！', `FemaleText_loc5`='醫生...來了!', `FemaleText_loc7`='¡El médico está... DISPONIBLE!' WHERE `ID`=51982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 저 멍청한 나무를 잔뜩 키워놓지만 않았어도 여기서 사격하기가 훨씬 좋았을 겁니다.', `MaleText_loc4`='如果不是有人又在那儿种了几棵蠢树，我还可以射得再准一点儿的！', `MaleText_loc5`='如果不是有人在這裡又種了樹，我就可以更清楚的瞄準了。', `MaleText_loc7`='Tendría una mejor línea de fuego si a alguien no se le hubiera ido la cabeza y le hubiera dado por plantar todos estos estúpidos árboles.' WHERE `ID`=51983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시죠?!', `MaleText_loc4`='你好啊！', `MaleText_loc5`='哈囉!', `MaleText_loc7`='¡Hola!' WHERE `ID`=51984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고통의 초원에서 즐겁게 뛰놀 수 있기를.', `FemaleText_loc4`='愿你能笑对苦难。', `FemaleText_loc5`='希望你在痛苦的原野中玩得愉快。', `FemaleText_loc7`='Ojalá te retuerzas por praderas de dolor.' WHERE `ID`=51985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 이름으로 네 죽음이 고통스럽지 않게 해 주지.', `FemaleText_loc4`='以月神的名义，我会给你个痛快的。', `FemaleText_loc5`='以伊露恩之名，賜你痛快一死。', `FemaleText_loc7`='Por Elune, yo te daré una muerte rápida.' WHERE `ID`=51986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령이여, 절대로 여기 돌아오지 마라. 이곳은 자연의 땅이다!', `FemaleText_loc4`='永远别回来了，元素。这是自然的领域！', `FemaleText_loc5`='別回來這裡，元素。這裡是自然造物之處!', `FemaleText_loc7`='Nunca regreses a este lugar, elemental. ¡Este es un lugar de naturaleza!' WHERE `ID`=51987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='길니아스를 위하여!', `FemaleText_loc4`='为了吉尔尼斯！', `FemaleText_loc5`='為了吉爾尼斯!', `FemaleText_loc7`='¡Por Gilneas!' WHERE `ID`=51988;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스의 영웅 다섯 명 앞에 이깟 불이 무슨 대수인가?', `FemaleText_loc4`='在联盟的五大英雄面前，你就是个小火苗！', `FemaleText_loc5`='對五個聯盟英雄來說，一場小小的火算什麼呢?', `FemaleText_loc7`='¿Qué es un poco de fuego frente a cinco héroes de la Alianza?' WHERE `ID`=51989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 길니아스인은 외부인을 그리 좋아하지 않아.', `FemaleText_loc4`='我们吉尔尼斯人对外来者可没什么耐心。', `FemaleText_loc5`='我們吉爾尼斯人對外來者沒什麼耐心。', `FemaleText_loc7`='Los gilneanos tenemos poca paciencia con los de fuera.' WHERE `ID`=51990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 아무것도 아니다!', `MaleText_loc4`='你这一无是处的家伙！', `MaleText_loc5`='你什麼都不是!', `MaleText_loc7`='¡No eres nada!' WHERE `ID`=51991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령이여, 여기서 당장 사라져라!', `MaleText_loc4`='这里不欢迎你们，元素！', `MaleText_loc5`='這裡不歡迎你，元素!', `MaleText_loc7`='¡Tu presencia no es bienvenida aquí, elemental!' WHERE `ID`=51992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스에는 너 따위가 머물 곳이 없다!', `MaleText_loc4`='艾泽拉斯可不是你们能来的。', `MaleText_loc5`='艾澤拉斯不需要你們這種東西。', `MaleText_loc7`='En Azeroth no hay sitio para seres como tú.' WHERE `ID`=51993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼 없는 타락자여, 사라져라!', `MaleText_loc4`='滚出去，你们这些没有灵魂的爬虫！', `MaleText_loc5`='滾吧，沒有靈魂的東西!', `MaleText_loc7`='¡Fuera de aquí, miserable desalmado!' WHERE `ID`=51994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 무기를 맛봐라!', `MaleText_loc4`='尝尝我的武器吧！', `MaleText_loc5`='跟我的劍打招呼吧!', `MaleText_loc7`='¡Prueba mi acero!' WHERE `ID`=51995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비는 보이지 않으리라.', `MaleText_loc4`='我不会放过你们的。', `MaleText_loc5`='我不會手下留情的。', `MaleText_loc7`='No tendré piedad contigo.' WHERE `ID`=51996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아아아아!', `MaleText_loc4`='啊……！', `MaleText_loc5`='啊啊啊!!!!', `MaleText_loc7`='¡AAAAAAAAAAAHHHHHHHHH!' WHERE `ID`=51997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰러져 죽어라, 이 줏대 없는 겁쟁이야!', `MaleText_loc4`='去死吧，你们这些懦夫！', `MaleText_loc5`='趴下來吃土吧，沒骨氣的懦夫們!', `MaleText_loc7`='¡Morded el polvo y morid, cobardes desgraciados!' WHERE `ID`=51998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산산이 조각내 주마! 아아아아아!', `MaleText_loc4`='我要把你们撕碎！啊啊啊啊！！！！', `MaleText_loc5`='我會把你撕成碎片!啊啊啊!!!', `MaleText_loc7`='¡Te haré picadillo! ¡AAAAAHHHHHHHH!' WHERE `ID`=51999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈리건을 위하여!', `FemaleText_loc4`='为了诺莫瑞根！', `FemaleText_loc5`='為了諾姆瑞根!', `FemaleText_loc7`='¡Por Gnomeregan!' WHERE `ID`=52000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 봐! 이게 바로 코그스핀의 강력한 힘이야!', `FemaleText_loc4`='看着，这就是克斯宾的实力！', `FemaleText_loc5`='目睹科士賓強大的力量吧!', `FemaleText_loc7`='¡Observad el potente poder de Rotadiente!' WHERE `ID`=52001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의사로서 경고하는데, 불은 너희 건강에 해로울 수도 있어.', `FemaleText_loc4`='作为住院医师，我必须警告你们这些剩下的人，火焰对你们的健康有害。', `FemaleText_loc5`='身為住院醫生，我覺得有必要警告你們其他人，火焰對你們的健康會有不良的影響。', `FemaleText_loc7`='Como médico residente debo advertiros a todos de que el fuego puede ser peligroso para la salud.' WHERE `ID`=52002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 조준하라!', `MaleText_loc4`='瞄准点！', `MaleText_loc5`='瞄準那個玩意兒!', `MaleText_loc7`='¡Apunta a sus partes pudendas!' WHERE `ID`=52003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 네가 지금까지 뭘 잘못했는지 내가 잘 가르쳐 줄게.', `MaleText_loc4`='没错，这只是给你个教训，以后别再干那种蠢事了！', `MaleText_loc5`='噢對，這會教教你不要再做那些事情了。', `MaleText_loc7`='Oh, sí, esto te enseñará a dejar de hacer lo que fuera que hiciste.' WHERE `ID`=52004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 가끔 조그맣고 털이 북실북실한 동물을 대포로 발사하지? 그러면 대체 대포는 어떻게 깨끗이 청소하는데? 드루이드들도 그 문제에 대한 답은 모를 거야!', `MaleText_loc4`='如果你不能时不时从枪管里射出只毛茸茸的小动物来，又怎么能保持枪管清洁呢？德鲁伊对那种事可没什么办法！', `MaleText_loc5`='如果沒有三不五十把一隻毛茸茸的小動物從槍裡射出去，怎麼能保持槍管乾淨勒?德魯伊們還沒辦法回答這個問題!', `MaleText_loc7`='Si no disparas un pequeño animal peludo con tu arma de vez en cuando, ¿cómo vas a mantenerla limpia? ¡Los druidas no tienen respuesta para ESO!' WHERE `ID`=52005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 노래를 불러주마, 암 그러고말고.', `MaleText_loc4`='如果我愿意的话，可以直接靠唱歌把他们唱死。', `MaleText_loc5`='我會唱死他們，沒錯，沒錯。', `MaleText_loc7`='Los mataré a base de canciones, sí, señor, ya lo verás.' WHERE `ID`=52006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트랄랄라...', `MaleText_loc4`='啦啦啦，啦啦啦……', `MaleText_loc5`='答啦啦...啦...', `MaleText_loc7`='Traaa la laaa...' WHERE `ID`=52007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 말리지 마! 내 류트로 저 녀석들을 모두 산산조각 내버릴 테니까!', `MaleText_loc4`='让我来！我要用我的琴狠狠揍他们一顿！', `MaleText_loc5`='讓我來!我會用我的魯特琴把他們砸成碎片!', `MaleText_loc7`='¡Déjame que me encargue de ellos! ¡Les haré picadillo con mi laúd!' WHERE `ID`=52008;
