UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조만간 다시 널 도와 싸우겠다. 잘 있어라!', `FemaleText_loc4`='我也不介意将来再跟你并肩战斗一次。再见！', `FemaleText_loc5`='我不介意改天再跟你打一場。再見!', `FemaleText_loc7`='No me importaría luchar de nuevo a tu lado en otra ocasión. ¡Adiós!' WHERE `ID`=52010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일은 아직 많이 남았소. 판드랄은 배신의 대가를 치를 것이오.', `MaleText_loc4`='我们的工作还远未完成。范达尔必须为他的欺骗付出代价。', `MaleText_loc5`='我們還有很多事情得處理。范達爾會為他的背叛付出代價。', `MaleText_loc7`='Esto aún no ha terminado. Fandral pagará por este engaño.' WHERE `ID`=52011;
