UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어에 있는 큰 건물 중 하나에서 티모시 워싱턴이 일하오. 2층에 있지. 그가 당신을 도와줄 거요.', `MaleText_loc4`='提莫斯·沃森特就在塞拉摩那座大型建筑的二楼工作。他应该能帮你。', `MaleText_loc5`='提摩西·沃森特在塞拉摩比較大間的建築物之一工作。你可以在二樓找到他，他幫得到你。', `MaleText_loc7`='Timothy Valión trabaja desde la segunda planta de uno de los edificios más grandes de Theramore. Él te servirá.', `FemaleText_loc1`='테라모어에 있는 큰 건물 중 하나에서 티모시 워싱턴이 일하지요. 2층에 있어요. 그가 당신을 도와줄 거예요.', `FemaleText_loc4`='提莫斯·沃森特就在塞拉摩那座大型建筑的二楼工作。他应该能帮你。', `FemaleText_loc5`='提摩西·沃森特在塞拉摩比較大間的建築物之一工作。你可以在二樓找到他，他幫得到你。', `FemaleText_loc7`='Timothy Valión trabaja desde la segunda planta de uno de los edificios más grandes de Theramore. Él te servirá.' WHERE `ID`=52078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오십시오. 거의 다 왔습니다.', `MaleText_loc4`='跟着我，凡人！裂隙就在附近。', `MaleText_loc5`='跟著我，凡人，裂隙快到了。', `MaleText_loc7`='Sígueme, mortal. La falla está cerca.', `FemaleText_loc1`='따라오십시오. 거의 다 왔습니다.', `FemaleText_loc4`='跟着我，凡人！裂隙就在附近。', `FemaleText_loc5`='跟著我，凡人，裂隙快到了。', `FemaleText_loc7`='Sígueme, mortal. La falla está cerca.' WHERE `ID`=52079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 길로 가야 합니까?', `MaleText_loc4`='我们该往哪儿走？', `MaleText_loc5`='我們該走哪一邊呢?', `MaleText_loc7`='¿Por dónde deberíamos ir?', `FemaleText_loc1`='어느 길로 가야 하나요?', `FemaleText_loc4`='我们该往哪儿走？', `FemaleText_loc5`='我們該走哪一邊呢?', `FemaleText_loc7`='¿Por dónde deberíamos ir?' WHERE `ID`=52080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수병이 옵니다! 숨으세요, 어서!!', `MaleText_loc4`='有个哨兵接近了！快藏起来！！', `MaleText_loc5`='哨衛接近中。快躲起來，快!', `MaleText_loc7`='¡Se acerca un centinela! ¡¡Escóndete, rápido!!', `FemaleText_loc1`='파수병이 옵니다! 숨으세요, 어서!!', `FemaleText_loc4`='有个哨兵接近了！快藏起来！！', `FemaleText_loc5`='哨衛接近中。快躲起來，快!', `FemaleText_loc7`='¡Se acerca un centinela! ¡¡Escóndete, rápido!!' WHERE `ID`=52081;
