UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이자는 제가 처리할 테니, 다른 곳을 찾아보십시오.', `MaleText_loc4`='我来处理这个家伙。你们去找他的同伙。', `MaleText_loc5`='我來處理這個人，你去找找其他的。', `MaleText_loc7`='Yo me encargo de este. Tú mira si encuentras más.', `FemaleText_loc1`='이자는 제가 처리할 테니, 다른 곳을 찾아보십시오.', `FemaleText_loc4`='我来处理这个家伙。你们去找他的同伙。', `FemaleText_loc5`='我來處理這個人，你去找找其他的。', `FemaleText_loc7`='Yo me encargo de este. Tú mira si encuentras más.' WHERE `ID`=52086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나만큼 응급치료를 잘 아는 이도 없다오, $r. 배우러 여기 왔다면, 내 최선을 다해 가르쳐 드리리다.', `MaleText_loc4`='我是一个从事药学的兽人，$r。如果你是来学习的，我会尽我最大的努力教你。', `MaleText_loc5`='我是一個從事藥學的獸人，$r。如果你是來學習的，我會盡我最大的努力教你。', `MaleText_loc7`='Soy un orco de medicina, $r. Si has venido aquí a aprender, me esforzaré al máximo en enseñarte.' WHERE `ID`=52087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 주십시오, 크렝크.', `MaleText_loc4`='我需要训练，科伦克。', `MaleText_loc5`='克連克，我需要接受訓練。', `MaleText_loc7`='Necesito instrucción, Krenk.', `FemaleText_loc1`='가르침을 주세요, 크렝크.', `FemaleText_loc4`='我需要训练，科伦克。', `FemaleText_loc5`='克連克，我需要接受訓練。', `FemaleText_loc7`='Necesito instrucción, Krenk.' WHERE `ID`=52088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적대적 행위가 감지되었습니다. 보안 체제 11-b를 가동합니다.', `MaleText_loc4`='检测到敌对行为。激活11-b号安全协议。', `MaleText_loc5`='偵測到敵對行為。啟動安全協定11-b。', `MaleText_loc7`='Comportamiento hostil detectado. Activando protocolo de seguridad 11-b.', `FemaleText_loc1`='적대적 행위가 감지되었습니다. 보안 체제 11-b를 가동합니다.', `FemaleText_loc4`='检测到敌对行为。激活11-b号安全协议。', `FemaleText_loc5`='偵測到敵對行為。啟動安全協定11-b。', `FemaleText_loc7`='Comportamiento hostil detectado. Activando protocolo de seguridad 11-b.' WHERE `ID`=52089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 여기서 이럴 시간이 없습니다!', `MaleText_loc4`='啊！我们不能再耽误了！', `MaleText_loc5`='唉!我們禁不起這樣的延誤!', `MaleText_loc7`='¡Augh! ¡No podemos retrasarnos!', `FemaleText_loc1`='아! 여기서 이럴 시간이 없습니다!', `FemaleText_loc4`='啊！我们不能再耽误了！', `FemaleText_loc5`='唉!我們禁不起這樣的延誤!', `FemaleText_loc7`='¡Augh! ¡No podemos retrasarnos!' WHERE `ID`=52090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy preparado.', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy preparada.' WHERE `ID`=52091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙습니다!', `FemaleText_loc4`='感谢你！', `FemaleText_loc5`='謝謝你!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=52093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맛있군요!', `FemaleText_loc4`='这些真美味！', `FemaleText_loc5`='真好吃!', `FemaleText_loc7`='¡Está delicioso!' WHERE `ID`=52094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 배가 고팠던 참이었어요...', `FemaleText_loc4`='我觉得有点饿了……', `FemaleText_loc5`='我真的快餓扁了...', `FemaleText_loc7`='Tenía tanta hambre...' WHERE `ID`=52095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고기 냄새가 정말 좋네요.', `FemaleText_loc4`='那块肉闻起来真香。', `FemaleText_loc5`='肉聞起來真的好香。', `FemaleText_loc7`='Esta carne huele tan bien.' WHERE `ID`=52096;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 좋아하는 갈비네요!', `FemaleText_loc4`='肋排！我的最爱！', `FemaleText_loc5`='肋排!我最愛吃的!', `FemaleText_loc7`='¡Costillas, mis favoritas!' WHERE `ID`=52097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 먹으려면 어디로 가야 하나요?', `FemaleText_loc4`='我去哪里吃第二顿呢？', `FemaleText_loc5`='可以再來一份嗎?', `FemaleText_loc7`='¿Adónde puedo ir para repetir?' WHERE `ID`=52098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체의 소유자여... 운명의 바람을 타고 여기까지 왔구나. 그래... 누구를 찾는지 안다. 오크의 아버지, 대지의 결속자...$b$b그가 가까이 있다. 공포라는 폭풍우에 갇혀 울부짖는구나. 위험을 감수하겠다면... 그에게 데려다 주지.', `MaleText_loc4`='聪明的血肉之躯，懂得在命运之风中翱翔。是的，我知道你要找的人——兽人先知，缚地者……$b$b我感到他就在附近，他内心的恐惧掀起了一场风暴。你可以去找他……但后果自负。', `MaleText_loc5`='聰明的凡人...在命運之風中穿梭。是的，我知道你要找的人...獸人之父...縛地者...他就在附近，困在自己恐懼的風暴中。你可以去找他...後果自負。', `MaleText_loc7`='Ser de carne astuto... volando entre los vientos del destino. Sí, conozco al que buscan... al padre-orco... vinculador terrestre...$b$bPercibo que está cerca... lleno de ira dentro de una tormenta de su propio miedo.' WHERE `ID`=52099;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 찾았습니다! 하지만... 폭풍우라니... 제가 한번 달래서, 고엘과 접촉해 보겠어요.', `FemaleText_loc4`='我们找到他了！但他变成了风暴……我要试着平息它，才能设法接近。', `FemaleText_loc5`='我們找到他了!但這場暴風雨變得...我會試著緩解它─來到達他那。', `FemaleText_loc7`='¡Ahí está! Pero esta tempestad en la que se ha convertido... Intentaré calmarle, llegar a él de alguna forma.' WHERE `ID`=52100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망쳤어. 내가 이 세계를 망쳤어...$b$b정령들은 아무 말이 없고... 대지 고리회는... 날 지도자로 생각하지 않아... 내가 너무 나약해서... 아제로스가... 영영 사라지는구나...', `MaleText_loc4`='我失败了。我辜负了这个世界……$b$b元素……不再和我交谈了。大地之环……也不再相信我的领导。我的无能……将艾泽拉斯……引向了湮灭。', `MaleText_loc5`='失敗了。我讓這個世界失望...元素們...不再與我對話。陶土議會...已經不再相信我的領導能力。我的脆弱...使艾澤拉斯...陷入了絕望...', `MaleText_loc7`='HE FALLADO. He fallado al mundo...$b$bLos elementos... ya no me hablan. El Anillo de la Tierra... ha perdido su fe en mi liderazgo. Mi debilidad... ha condenado a Azeroth... al olvido.' WHERE `ID`=52101;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘, 저예요, 아그라! 절 모르시겠어요?', `FemaleText_loc4`='古伊尔，是我——阿格娜！你不认得我了？', `FemaleText_loc5`='高爾，是我─阿格拉!你不認得我了嗎?', `FemaleText_loc7`='Go''el, soy yo, ¡Aggra! ¿No me reconoces?' WHERE `ID`=52102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도... 남지 않고... 사라지는구나...', `MaleText_loc4`='湮灭……只有……湮灭……', `MaleText_loc5`='絕望...什麼都沒有...只有絕望...', `MaleText_loc7`='Olvido... nada más... que olvido.' WHERE `ID`=52103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 멀어졌어요! 계속 불러야 해요!', `FemaleText_loc4`='他离得太远了！我们不能放弃！', `FemaleText_loc5`='他意志太模糊了!我們必須繼續嘗試!', `FemaleText_loc7`='¡Está demasiado ido! ¡Debemos seguir intentándolo!' WHERE `ID`=52104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장으로서... 내가... 호드를 망쳤다... 가로쉬는... 호드를... 내 백성을... 파멸로 이끌겠지. 케른, 내 형제여... 그대 말을 들어야 했거늘.', `MaleText_loc4`='我辜负了部落……不合格的酋长……$b$b加尔鲁什会毁掉部落……$b$b毁掉我的人民。凯恩，我的兄弟……为何我不听信于你？', `MaleText_loc5`='我身為大酋長...讓部落...失望了...卡爾洛斯...會帶它走向毀滅...我的同胞...走向毀滅。凱恩，我的兄弟...我為什麼當初不聽你的?', `MaleText_loc7`='He... fallado a la Horda... como Jefe de Guerra...$b$bGarrosh... los llevará a la destrucción...$b$bMi gente... a la ruina. Cairne, hermano mío... ¿Por qué no te escuché?' WHERE `ID`=52105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘, 그대는 최선을 다했어요! 의심을 떨쳐요! 의심이 심장을 집어삼키려 해요!', `FemaleText_loc4`='你做了最好的选择，古伊尔！战胜那些怀疑！他们在吞噬你的心！', `FemaleText_loc5`='你做了你認為對的事，高爾!擺脫這些質疑!別讓它們吞噬了你的心!', `FemaleText_loc7`='¡Hiciste lo que creías que era mejor, Go''el! ¡Combate esas dudas! ¡Están devorándote el corazón!' WHERE `ID`=52106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 말을 들어야 했거늘.', `MaleText_loc4`='……为何我不听信于你？', `MaleText_loc5`='...為什麼不聽你的呢?', `MaleText_loc7`='¿Por qué no te escuché?' WHERE `ID`=52107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비해요!', `FemaleText_loc4`='打起精神——另一波又来了！', `FemaleText_loc5`='準備好，$n!', `FemaleText_loc7`='¡Prepárate!' WHERE `ID`=52108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴이 낯이 익어... 아그라! 오, 나의 심장. 날 보시오... 난... 아무것도 아니오. 이기적이지... 지금까지 업적을 쌓은 건... 다 자존심 때문이었소. 난... 그대에게 어울리지 않소...', `MaleText_loc4`='我认识你的脸……阿格娜！哦，我的心——你看不到吗？我……一无是处。自私……我所做的一切……仅仅是为了满足我的傲慢。我……配不上你……', `MaleText_loc5`='我認得妳的臉...阿格拉!噢，我的摯愛─你看不到嗎?我...什麼都不是。我自私...所有我做的...達成的...都只是為了自己的傲慢。我...不配擁有妳...', `MaleText_loc7`='Conozco tu rostro... ¡Aggra! Oh, corazón mío, ¿acaso no lo ves? No soy... nada. Egoísta... todo lo que he hecho... conseguido... lo he hecho por mero ORGULLO. No soy... digno... de ti...' WHERE `ID`=52109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대는 고엘, 듀로탄과 드라카의 아들이자 자랑스러운 호드의 대족장입니다! 그리고 그대는 내 마음을 얻은 오크입니다. 자신을 기억하세요!', `FemaleText_loc4`='你是古伊尔，杜隆坦与德拉卡之子！名正言顺的部落酋长！你还赢得了我的心！记住你是谁！', `FemaleText_loc5`='你是高爾，杜洛坦和崔卡之子!!部落正統的大酋長!你是贏得我心的獸人。記住你是誰!', `FemaleText_loc7`='¡Tú eres Go''el, hijo de Durotan y de Draka! ¡Legítimo Jefe de Guerra de la Horda! ¡Eres el orco que conquistó mi corazón! ¡Recuerda QUIÉN ERES!' WHERE `ID`=52110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라... 그대였군...', `MaleText_loc4`='阿格娜……真的是你……', `MaleText_loc5`='阿格拉...真的是妳...', `MaleText_loc7`='Aggra... ERES tú...' WHERE `ID`=52111;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가만히 있어요, 내 사랑. 마음을 가라앉혀요. 그대는 의무에 짓눌린 노예가 되었습니다. 하지만 자신의 마음에 귀를 기울이는 것이야말로... 백성과... 저에 대한 의무를 다하는 것이랍니다.', `FemaleText_loc4`='平静下来，我的爱人。冷静心绪。你成了使命的奴隶。但只有直面内心，你才能继续履行使命……为了你的人民……也为了我。', `FemaleText_loc5`='別動，我的摯愛。理清你的思緒。你成為了責任的奴隸，但面對你內心真實的聲音才是你完成責任的方式...為你的同胞...也為了我。', `FemaleText_loc7`='Tranquilo, mi amor. Calma tu mente. Te convertiste en esclavo de tu deber. Pero cumplirás ese deber si permaneces fiel a tu corazón... a tu pueblo... y a mí.' WHERE `ID`=52112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 난... 더 견딜 수가... 으아아!', `MaleText_loc4`='阿格娜，我……我坚持不住了……啊！', `MaleText_loc5`='阿格拉，我...我支撐不住，我支撐不住...啊啊!!', `MaleText_loc7`='Aggra... yo... no puedo más... ¡AAH!' WHERE `ID`=52113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s|1이;가; |cFFFF0000|Hspell:98951|h[분할의 일격]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s开始施放|cFFFF0000|Hspell:98951|h[爆裂打击]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s開始施放|cFFFF0000|Hspell:98951|h[碎裂猛擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_ragnaros_splittingblow.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:98951|h[Arremetida atizadora]|h|r!' WHERE `ID`=52114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s|1이;가; |cFFFF6600|Hspell:98164|h[마그마 덫]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s施放了|cFFFF6600|Hspell:98164|h[熔岩陷阱]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s施放了|cFFFF6600|Hspell:98164|h[熔岩陷阱]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_selfdestruct.blp:20|t¡%s lanza |cFFFF6600|Hspell:98164|h[Trampa de magma]|h|r!' WHERE `ID`=52115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하오, 여행자여. 당신에게 줄 게 아무것도 없소.', `MaleText_loc4`='对不起，旅行者。我没什么东西可以给你。', `MaleText_loc5`='抱歉，旅人，我沒辦法提供你什麼。', `MaleText_loc7`='Lo siento, $gviajero:viajera;, no tengo nada que ofrecerte.' WHERE `ID`=52116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 도착했습니다!', `MaleText_loc4`='我们终于到了！', `MaleText_loc5`='我們終於到了!', `MaleText_loc7`='Por fin, aquí estamos.', `FemaleText_loc1`='드디어 도착했습니다!', `FemaleText_loc4`='我们终于到了！', `FemaleText_loc5`='我們終於到了!', `FemaleText_loc7`='Por fin, aquí estamos.' WHERE `ID`=52117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버티십시오, 친구여. 적들은 강합니다.', `MaleText_loc4`='保护好自己，朋友。那些进攻者很难缠。', `MaleText_loc5`='保護自己，朋友。攻擊我們的人很強。', `MaleText_loc7`='Defiéndete. Nuestros atacantes son formidables.', `FemaleText_loc1`='버티십시오, 친구여. 적들은 강합니다.', `FemaleText_loc4`='保护好自己，朋友。那些进攻者很难缠。', `FemaleText_loc5`='保護自己，朋友。攻擊我們的人很強。', `FemaleText_loc7`='Defiéndete. Nuestros atacantes son formidables.' WHERE `ID`=52118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교활한 녀석들 같으니! 나라고 계략이 없는 줄 아느냐...', `MaleText_loc4`='你们好像有两下子，那么就让你们看看我的招数吧……', `MaleText_loc5`='你們好像有兩下子，那麼就讓你們看看我的招數吧!', `MaleText_loc7`='¿Os gustan los jueguecitos? Yo también me sé unos cuantos...' WHERE `ID`=52119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 따위 겁낼 줄 아느냐... 비천한 것들! 어디 한번 덤벼봐라!', `MaleText_loc4`='你们这些下等生物根本无法对我构成任何威胁！使出全力战斗吧！', `MaleText_loc5`='你們這些下等生物，根本無法對我構成任何威脅，使出全力戰鬥吧!', `MaleText_loc7`='¡No suponéis una amenaza seres inferiores! ¡A ver qué valéis!' WHERE `ID`=52120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심! 그의 숨결은 무조건 피하십시오!', `MaleText_loc4`='当心！无论如何都要避开他的吐息！', `MaleText_loc5`='小心!無論如何都要避開他的吐息!', `MaleText_loc7`='¡Cuidado! ¡Evita su aliento como sea!', `FemaleText_loc1`='조심! 그의 숨결은 무조건 피하십시오!', `FemaleText_loc4`='当心！无论如何都要避开他的吐息！', `FemaleText_loc5`='小心!無論如何都要避開他的吐息!', `FemaleText_loc7`='¡Cuidado! ¡Evita su aliento como sea!' WHERE `ID`=52121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어막을 파괴했습니다. 집중공격하세요!', `MaleText_loc4`='我摧毁了他的护盾，释放你的能量吧！', `MaleText_loc5`='我摧毀他的護盾了，現在就動手!', `MaleText_loc7`='¡He destruido su escudo! ¡Desata tu poder ahora!', `FemaleText_loc1`='방어막을 파괴했습니다. 집중공격하세요!', `FemaleText_loc4`='我摧毁了他的护盾，释放你的能量吧！', `FemaleText_loc5`='我摧毀他的護盾了，現在就動手!', `FemaleText_loc7`='¡He destruido su escudo! ¡Desata tu poder ahora!' WHERE `ID`=52122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘을 불어넣노라!', `MaleText_loc4`='注入我的力量吧！', `MaleText_loc5`='沐浴在我的力量之下吧!', `MaleText_loc7`='¡Siente mi poder!', `FemaleText_loc1`='나의 힘을 불어넣노라!', `FemaleText_loc4`='注入我的力量吧！', `FemaleText_loc5`='沐浴在我的力量之下吧!', `FemaleText_loc7`='¡Siente mi poder!' WHERE `ID`=52123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단의 가호가 함께하길!
