UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아, 이 물렁하고 조그만 놈들, 이거 어떻게 할 거냐!', `MaleText_loc4`='啊——讨厌的小害虫，瞧瞧你们都干了些什么！', `MaleText_loc5`='呃─可愛的小害蟲，看看你做了什麼!', `MaleText_loc7`='Augh, alimañas blanditas, ¡miren lo que han hecho!' WHERE `ID`=52235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으 이 녀석들... 화를 돋구는구나!', `MaleText_loc4`='呜啊……你们现在惹我生气了！', `MaleText_loc5`='呃啊啊，你...你惹我生氣了!', `MaleText_loc7`='Uurrghh, ahora... ¡me han hecho enojar!' WHERE `ID`=52236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 이 조그만 것들이...', `MaleText_loc4`='哦你们这些小畜生……', `MaleText_loc5`='噢你們這些小野獸...', `MaleText_loc7`='Oh, pequeñas bestias...' WHERE `ID`=52237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밟아 버린다!', `MaleText_loc4`='践踏。', `MaleText_loc5`='踩扁你。', `MaleText_loc7`='Ahora pisotón.' WHERE `ID`=52238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발로 짓눌러 주마!', `MaleText_loc4`='我要踩烂你们！', `MaleText_loc5`='用腳踩爛你。', `MaleText_loc7`='¡Los aplastaré bajo mis pies!' WHERE `ID`=52239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴 세월 내 잠을 방해한 이가 없었건만... 그래... 이 살덩어리들아. 네놈들을 불태워 주마!', `MaleText_loc4`='我已经沉睡了无数的时光，现在却被这些血肉生灵所扰……你们将燃烧殆尽！', `MaleText_loc5`='數萬年來我平靜地睡著...現在居然這樣...血肉之軀，你們給我燒吧!', `MaleText_loc7`='He dormido durante eones sin ser molestado... Y ahora... Seres de carne, ¡ARDERÁN!' WHERE `ID`=52240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라!!!', `MaleText_loc4`='烧吧！', `MaleText_loc5`='燒啊!!!!', `MaleText_loc7`='¡Ardaaaaaan!' WHERE `ID`=52241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 불길에 무릎 꿇어라.', `MaleText_loc4`='屈服于烈焰之灵。', `MaleText_loc5`='屈服於火焰吧。', `MaleText_loc7`='Sucumban a la llama viva.' WHERE `ID`=52242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 안의 불길은 꺼지지 않는다.', `MaleText_loc4`='我的烈焰永不熄灭。', `MaleText_loc5`='我內心之火永不熄滅。', `MaleText_loc7`='Mi fuego interno nunca morirá.' WHERE `ID`=52243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집어삼켜라...', `MaleText_loc4`='吞噬……', `MaleText_loc5`='吞噬...', `MaleText_loc7`='Consumir...' WHERE `ID`=52244;
