UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서졌어... 으으으으... 부서졌어...', `MaleText_loc4`='碎掉了。呃……碎掉了……', `MaleText_loc5`='碎掉了。嗚啊啊啊...碎掉了...', `MaleText_loc7`='Roto. Mnngghh... roto...' WHERE `ID`=52246;
