UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈만 남기고 모조리 태워버려.', `MaleText_loc4`='烧毁他们孱弱的血肉。', `MaleText_loc5`='把血肉從他們那小小的軀殼裡吸乾。', `MaleText_loc7`='Arrancar la carne de sus pequeños cuerpos.' WHERE `ID`=52248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈를 으스러뜨려라!', `MaleText_loc4`='碎骨成灰！', `MaleText_loc5`='碎他們的骨!', `MaleText_loc7`='¡Destrozar los huesos!' WHERE `ID`=52249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밟고 태우고, 밟고 태우고.', `MaleText_loc4`='踩死他们，烧死他们！', `MaleText_loc5`='踩扁你們，燒死你們。', `MaleText_loc7`='Pisotear y quemar, pisotear y quemar.' WHERE `ID`=52250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이십니까, 필멸의 존재여?', `MaleText_loc4`='你好，凡人。', `MaleText_loc5`='怎樣啊，凡人?', `MaleText_loc7`='¿Sí, mortal?' WHERE `ID`=52251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어 우리 고향에 오신 것입니까?', `MaleText_loc4`='你到我们的家园来干什么呢，幼龙？', `MaleText_loc5`='你為什麼會來到我們的故鄉，飛龍?', `MaleText_loc7`='¿Qué te trae a nuestro hogar, draco?', `FemaleText_loc1`='무슨 일이 있어 우리 고향에 오신 건가요?', `FemaleText_loc4`='你到我们的家园来干什么呢，幼龙？', `FemaleText_loc5`='你為什麼會來到我們的故鄉，飛龍?', `FemaleText_loc7`='¿Qué te trae a nuestro hogar, draco?' WHERE `ID`=52252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른용군단의 새로운 위상으로 칼렉고스가 선택되었습니다. 그대들 중 한 명이 데스윙을 향한 아리고스의 배신을 좌절시키는 데 중요한 역할을 했으며, 따라서 끔찍한 위기를 막아낼 수 있었습니다.$b$b우리는 그들의 영웅적인 행위를 기념하기 위해 이곳에 왔습니다.', `MaleText_loc4`='卡雷苟斯已经被推举为蓝龙军团的新守护巨龙。$b$b你们中的一位勇士曾帮助阻止了阿瑞苟斯倒向死亡之翼，从而避免了一场灾难。$b$b今天，我们欢聚一堂，以颂扬他们的英雄事迹。', `MaleText_loc5`='卡雷苟斯已經被選為藍龍軍團新任的魔法之王。$b$b亞雷戈斯向死亡之翼倒戈的事情會敗露，是因為你們當中有人扮演了關鍵性的角色，也因此讓我們避開了一場災難性的危機。$b$b我們今天來此慶祝他們這些英雄事蹟。', `MaleText_loc7`='Kalecgos ha sido elegido nuevo Aspecto de la Magia para el Vuelo Azul.$b$bUno entre ustedes fue vital para desenmascarar la traición de Arygos, que se alió con Alamuerte; por lo que pudimos evitar una crisis terrible.$b$bEstamos aquí para participar en las celebraciones de tan heroicas hazañas.' WHERE `ID`=52253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험을 감수하겠다면... 그에게 데려다 주지.', `MaleText_loc4`='你可以去找他……但后果自负。', `MaleText_loc5`='你可以去找他...後果自負。', `MaleText_loc7`='Vayan a su encuentro... bajo su propio riesgo.' WHERE `ID`=52258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 잘될까요, 고엘? 드루이드와 주술사가 힘을 합쳐 세계수를 복원하면... 그러면 조각난 세계가 치유될까요?', `FemaleText_loc4`='你认为这会有用吗，古伊尔，德鲁伊与萨满联手治愈世界之树？这能治疗这个崩坏的世界？', `FemaleText_loc5`='真的有用嗎，高爾─德魯伊跟薩滿合作治療世界之樹?真能治好崩壞的世界嗎?', `FemaleText_loc7`='¿Crees que funcionará, Go''el, que los druidas y los chamanes se unan para restaurar el Árbol del Mundo? ¿Que podrían curar este mundo deshecho?' WHERE `ID`=52259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이세라 님.', `FemaleText_loc4`='伊瑟拉女王。', `FemaleText_loc5`='伊瑟拉女士。', `FemaleText_loc7`='Lady Ysera.' WHERE `ID`=52260;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘! 안 돼!', `FemaleText_loc4`='古伊尔！不！', `FemaleText_loc5`='高爾!不!', `FemaleText_loc7`='¡Go''el! ¡NO!' WHERE `ID`=52261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘은 어떡하죠?', `FemaleText_loc4`='但古伊尔怎么办？', `FemaleText_loc5`='那高爾怎麼辦?', `FemaleText_loc7`='¿Y qué hay de Go''el?' WHERE `ID`=52262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요! 놈들이 나의 고엘을 빼앗아 갔지만, 전 절대 그를 포기하지 않겠습니다. 선조시여, 용서하소서... 제 심장을 잃어버린 느낌입니다.', `FemaleText_loc4`='不！那些杂种偷走了我的古伊尔，但我决不会抛弃他。先祖在上……我的心也随他一同被偷走了。', `FemaleText_loc5`='不!那些雜種偷走了我的高爾，但我不會放棄他。原諒我...祖先們，我的心也像是被偷走了一樣。', `FemaleText_loc7`='¡No! Esas alimañas me han robado a mi Go''el, pero yo NO lo abandonaré. Ancestros, perdónenme... Es como si mi corazón se hubiera ido con él.' WHERE `ID`=52263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위상들은 그렇게 믿고 있소. 애초에 세계수를 키웠으니...', `MaleText_loc4`='守护巨龙相信这有用……', `MaleText_loc5`='巨龍守護者相信可以。他們也該知道...', `MaleText_loc7`='Los Aspectos creen que sí. Y ellos deberían saberlo...' WHERE `ID`=52264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...잘 알고 있지 않겠소.', `MaleText_loc4`='……毕竟是他们种下了这棵树。', `MaleText_loc5`='...一開始就是他們種的。', `MaleText_loc7`='...son los que lo hicieron crecer.' WHERE `ID`=52265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온 님, 꿈 바깥세상에 잘 오셨습니다.', `MaleText_loc4`='怒风大师。你能回到清醒的世界真是太好了。', `MaleText_loc5`='怒風大師，很高興看到你回到現實世界。', `MaleText_loc7`='Maestro Tempestira. Me alegra verte en el mundo de la vigilia.' WHERE `ID`=52266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단!', `MaleText_loc4`='暮光之锤！', `MaleText_loc5`='暮光之錘!', `MaleText_loc7`='¡El Martillo Crepuscular!' WHERE `ID`=52267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음 따윈 두렵지 않다.', `MaleText_loc4`='我不惧怕死亡。', `MaleText_loc5`='我不害怕死亡。', `MaleText_loc7`='No temo a la muerte.' WHERE `ID`=52268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 왔다, 듀로탄의 아들이여. 어서 와라, 서리늑대의 아그랄란이여.', `FemaleText_loc4`='欢迎，杜隆坦之子。也欢迎你，霜狼氏族的阿格娜兰。', `FemaleText_loc5`='歡迎你，杜洛坦之子。還有你，霜狼的阿格拉蘭。', `FemaleText_loc7`='Bienvenido, hijo de Durotan. Y tú también, Aggralan de los Lobo Gélido.' WHERE `ID`=52269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친구들이여, 오늘 우리가 여기 모인 건 큰 희생을 치르고 되찾은 이 세계를 치유하기 위함이오.', `FemaleText_loc4`='朋友们，我们今日聚集于此，是为了治愈这个用无数牺牲换回的世界。', `FemaleText_loc5`='朋友們，我們今天齊聚於此來為我們已做出諸多犧牲的世界療傷。', `FemaleText_loc7`='Amigos, nos hemos reunido hoy aquí para sanar este mundo por cuya salvación hemos sacrificado tanto.' WHERE `ID`=52270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 대지 고리회 최고의 주술사, 그 없이는 의식을 진행할 수 없다. 허나 그가 영영 못 돌아올지도 모르니, 대책을 세워야 한다...', `FemaleText_loc4`='他是大地之环最强大的萨满，这场仪式不可能在他缺席的情况下继续。但我们必须做好心理准备，接受他永远消失的可能性。', `FemaleText_loc5`='他是陶土議會最強大的薩滿，少了他，儀式就無法繼續。但是我們必須接受可能永遠失去他的事實...', `FemaleText_loc7`='Era el chamán más poderoso del Anillo de la Tierra y la ceremonia no puede continuar sin él. Pero debemos prepararnos para aceptar que puede que se haya perdido para siempre...' WHERE `ID`=52271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까?', `MaleText_loc4`='你们好，朋友们。', `MaleText_loc5`='朋友們，大家好。', `MaleText_loc7`='Saludos, amigos.' WHERE `ID`=52272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대 안에 엄청난 힘이 느껴진다, 스랄. 그동안 참 많이 성장했구나.', `MaleText_loc4`='我能感到你体内的巨大力量，年轻的萨尔。这些年你成长了不少。', `MaleText_loc5`='我感覺到你體內強大的力量，年輕的索爾。你在上次見面後成長了許多。', `MaleText_loc7`='Percibo un gran poder que crece en tu interior, joven Thrall. Has avanzado mucho desde la última vez que nos vimos.' WHERE `ID`=52273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 후회할 것이다!', `MaleText_loc4`='你会为此后悔的，入侵者！', `MaleText_loc5`='你會後悔的，陌生人!', `MaleText_loc7`='¡Lo lamentarás, extraño!' WHERE `ID`=52274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄... 놈들이 널 어떻게 한 거냐?', `MaleText_loc4`='范达尔……他们对你做了什么？', `MaleText_loc5`='范達爾...他們對你做了什麼啊?', `MaleText_loc7`='Fandral... Pero ¿qué te han hecho?' WHERE `ID`=52275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄이 동료들을 사악한 길로 이끌고 있습니다. 이미 추종 세력이 있을 수도 있습니다. 달숲에 알려야겠습니다.', `MaleText_loc4`='范达尔在腐蚀其他的德鲁伊。他也许已经有了邪恶的追随者——我必须立即警告月光林地。', `MaleText_loc5`='范達爾正在引領德魯伊們走向邪道。可能已經有人追隨他了─我必須警告月光林地。', `MaleText_loc7`='Fandral está corrompiendo y transformando a los druidas en algo siniestro. Puede que ya tenga otros seguidores... Debo avisar al Claro de la Luna.' WHERE `ID`=52276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없소, 누이여. 어서 의식을 시작합시다...', `MaleText_loc4`='时间是宝贵的，姐妹。让我们准备仪式吧……', `MaleText_loc5`='時間寶貴，姊妹。讓我們進行儀式吧...', `MaleText_loc7`='El tiempo es oro, hermana. Ocupémonos de nuestro ritual...' WHERE `ID`=52277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하군, 우리가 방해했나?', `MaleText_loc4`='抱歉，打扰诸位了吗？', `MaleText_loc5`='真是抱歉，打擾到你們了嗎?', `MaleText_loc7`='Lo siento, ¿interrumpimos algo?' WHERE `ID`=52278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라, 듀로탄의 아들! 네놈들 때문에 일정에 차질이 생기긴 했지만, 다가오는 황혼의 시간을 막을 수는 없다!', `MaleText_loc4`='没那么快，杜隆坦之子！你和你的盟友的确阻碍了我们，但暮光审判日是不可避免的！', `MaleText_loc5`='先別急，杜洛坦之子!你和你的同伴的確耽誤了我們，但「暮光之時」是無可避免的!', `MaleText_loc7`='No tan rápido, hijo de Durotan. ¡Tus aliados y tú nos han hecho retroceder, pero la Hora del Crepúsculo NO PUEDE evitarse!' WHERE `ID`=52279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음? 누가 널 죽인다고 했느냐?', `MaleText_loc4`='死？谁提到过死这个字的？', `MaleText_loc5`='死亡?我有提到死亡這兩個字嗎?', `MaleText_loc7`='¿Muerte? ¿Quién ha dicho algo de muerte?' WHERE `ID`=52280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 네가 제아무리 위대한 주술사라 해도, 어차피 필멸의 존재일 뿐. 이건 주인님이 너에게 내리는 저주다. 정령과의 강력한 결속이... 오히려 독이 되리라!
', `MaleText_loc4`='你也许是这个世界上最强大的萨满，萨尔——但你仍然是个凡人。主人的诅咒将降临于你——你与元素的伟大盟约将变成你的……毁灭！', `MaleText_loc5`='你也許是這世上最偉大的薩滿，索爾─但畢竟是血肉之軀。這是我主人贈予你的詛咒─用你與元素之間強大的連結...來毀滅你!', `MaleText_loc7`='Quizá seas el chamán más grande de este mundo, Thrall, pero eres mortal. Esta es la maldición de mi maestro para ti, que convertirá tu gran vínculo con los elementos... ¡en tu perdición!' WHERE `ID`=52281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과연?
', `MaleText_loc4`='我会吗？', `MaleText_loc5`='會嗎?', `MaleText_loc7`='¿Tú crees?' WHERE `ID`=52282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜만입니다, 샨도. 제자 얼굴은 알아보시겠죠?', `MaleText_loc4`='看看我，大导师——想必你还认得你从前的学生吧？', `MaleText_loc5`='哈，尊師─你不會不認得你的前弟子了吧?', `MaleText_loc7`='Vamos, shan''do, ¿acaso no reconoces a tu antiguo aprendiz?' WHERE `ID`=52283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순진한 건 여전하시군요. 저 오크는 이제 당신을 돕지 못합니다.', `MaleText_loc4`='你还是这么天真。你的兽人宠物救不了你，玛法里奥。', `MaleText_loc5`='還是一樣的天真。你的獸人寵物現在救不了你了，瑪法里恩。', `MaleText_loc7`='Tan ingenuo como siempre. Tu orco mascota no puede salvarte, Malfurion.' WHERE `ID`=52284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 들어요, 고엘! 그대는 혼자가 아니에요! 제가 옆에 있어요. 그냥 보내지 않겠어요!', `FemaleText_loc4`='听我说，古伊尔！你并不孤单！我与你同在——我不会放弃你！', `FemaleText_loc5`='聽著，高爾!我在這裡，你不是一個人!我不會讓你就這樣離開!', `FemaleText_loc7`='¡Escúchame, Go''el! ¡NO ESTÁS solo! ¡Estoy aquí contigo, no te dejaré!' WHERE `ID`=52286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 고엘, 힘내요! 내가 풀어 줄게요. 바라던 삶을 살게 해 줄게요, 약속해요!', `FemaleText_loc4`='哦，古伊尔！坚持住！我会救出你，让你拥有这样的生活，我发誓！', `FemaleText_loc5`='噢，高爾，撐住!我一定會救出你，你將會擁有你想要的，我發誓!', `FemaleText_loc7`='¡Go''el, aguanta! ¡Yo te LIBERARÉ! ¡Y TENDRÁS esa vida! ¡Lo juro!' WHERE `ID`=52287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가 욕망을 인정하고 균형을 잡지 않는 한... 이 저주는 계속될 겁니다.', `FemaleText_loc4`='他必须拥抱渴望，并找到平衡……否则诅咒永无终结。', `FemaleText_loc5`='他必須接受它們並找到平衡點...不然這個詛咒永遠都不會消失。', `FemaleText_loc7`='Debe aceptarlos y encontrar el equilibrio... o esta maldición nunca terminará.' WHERE `ID`=52288;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이겨내요, 고엘! 벗어나야 해요!', `FemaleText_loc4`='战胜它，古伊尔！你必须摆脱它！', `FemaleText_loc5`='戰鬥下去，高爾!你必須逃出來!', `FemaleText_loc7`='¡Lucha, Go''el! ¡Debes reaccionar!' WHERE `ID`=52289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 예언자께선 네놈이... 오직 네놈이 우리의 마지막 걸림돌이라는 걸 아신다. 널 제거하라는 명령을 내리셨지.', `MaleText_loc4`='暮光先知已经洞察到你——只有你——是我们最后的阻碍……于是他派我来送你退场。', `MaleText_loc5`='暮光預言者知道你─只有你─是我們最終的障礙...他派我來讓你徹底消失。', `MaleText_loc7`='El profeta Crepuscular sabe que TÚ, y solo tú, eres nuestro obstáculo final... Me ha enviado para eliminarte de la partida.' WHERE `ID`=52290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간도, 정령들은 너를 갉아먹고 있다. 그것들은 이 망할 세상의 마지막 생명의 빛이 꺼지는 그 순간까지, 네 안의 의심과 두려움을 먹고 자랄 것이다.', `MaleText_loc4`='元素无时不在撕裂你的身体——它们将以你的恐惧和怀疑为食，直到这个悲惨世界上的最后一丝生命之光熄灭为止。', `MaleText_loc5`='即使是現在，元素也正在撕裂你─它們將啃食你的不安和恐懼，直到這個世界上最後一盞生命之火消失為止。', `MaleText_loc7`='Incluso ahora, los elementos están destrozándote, y se alimentarán de tus dudas y miedos hasta que la última chispa de vida de este maldito mundo se haya extinguido.' WHERE `ID`=52291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수에 불타는 화염이 다가오고 있습니다. 각오하십시오.', `MaleText_loc4`='我们复仇的烈焰已经逼近了。准备好吧', `MaleText_loc5`='而我們的復仇之火正在接近。準備好吧。', `MaleText_loc7`='Y la LLAMA de nuestra venganza se acerca. Prepárate.' WHERE `ID`=52292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지 고리회와 세나리온 의회가 처음으로 서로 손을 잡고 이 위대한 나무를 복원하리니, 이로써 온 아제로스가 치유될 것이오.', `FemaleText_loc4`='这是史上第一次，大地之环与塞纳里奥议会将联合在一起——为了恢复这棵巨树，治愈整个艾泽拉斯世界。', `FemaleText_loc5`='這是第一次，陶土議會和塞納里奧議會將攜手合作，治療這棵偉大的神木，來拯救整個艾澤拉斯。', `FemaleText_loc7`='Por primera vez, El Anillo de la Tierra y el Círculo Cenarion trabajarán juntos para restaurar este gran Árbol, con lo que sanarán todo el mundo de Azeroth.' WHERE `ID`=52293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가... 누가 도와주시면 안 되겠습니까?', `MaleText_loc4`='有人吗……谁来帮帮我？', `MaleText_loc5`='有...有人能幫我嗎?', `MaleText_loc7`='¿Puede... puede ayudarme alguien?', `FemaleText_loc1`='누가... 누가 도와주시면 안 돼요?', `FemaleText_loc4`='有人吗……谁来帮帮我？', `FemaleText_loc5`='有...有人能幫我嗎?', `FemaleText_loc7`='¿Puede... puede ayudarme alguien?' WHERE `ID`=52298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상태가 별로 좋지 않습니다...', `MaleText_loc4`='我有点不舒服……', `MaleText_loc5`='我感覺不太舒服...', `MaleText_loc7`='No me encuentro muy bien...', `FemaleText_loc1`='상태가 별로 좋지 않아요...', `FemaleText_loc4`='我有点不舒服……', `FemaleText_loc5`='我感覺不太舒服...', `FemaleText_loc7`='No me encuentro muy bien...' WHERE `ID`=52299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 너무 많습니다! 얼마나 버틸 수 있을지 모르겠어요! 고엘, 이제 좀 일어나지 그래요!', `FemaleText_loc4`='他们的数量太多了！我不知道我们还能撑多久！古伊尔，是时候该醒醒了！', `FemaleText_loc5`='他們數量太多了!我不知道我們還能支撐多久!高爾，都什麼時候了，你也該醒了吧!', `FemaleText_loc7`='¡Son demasiados! ¡No sé cuánto tiempo podremos aguantar! ¡Go''el, ahora sería un buen momento para que despertaras!' WHERE `ID`=52300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 참는다.', `MaleText_loc4`='我们要有耐心。', `MaleText_loc5`='我們耐心的等。', `MaleText_loc7`='Somos pacientes.' WHERE `ID`=52301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요? 고엘, 내 말 들려요? 도움이 필요해요! 움직여 봐요!', `FemaleText_loc4`='刚才是他——？古伊尔，你能听见吗？我们需要你的帮助！动手吧！', `FemaleText_loc5`='他是不是...?高爾，你聽得到嗎?我們需要你!幫幫我們!', `FemaleText_loc7`='¿Acaba de...? ¿Go''el, puedes oírme? ¡Necesitamos tu ayuda! ¡Haz algo!' WHERE `ID`=52302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘! 정신 차려요! 안 그러면 우리 모두 끝이에요!', `FemaleText_loc4`='古伊尔！快醒醒，不然我们都要死了！', `FemaleText_loc5`='高爾!快振作!不然我們全都會死!', `FemaleText_loc7`='¡GO''EL! ¡Recupérate o MORIREMOS todos!' WHERE `ID`=52303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 참는다.', `MaleText_loc4`='我们要有耐心。', `MaleText_loc5`='我們耐心的等。', `MaleText_loc7`='Somos pacientes.' WHERE `ID`=52304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘의 본심이 아니에요!', `FemaleText_loc4`='他可不能老这么说！', `FemaleText_loc5`='我沒聽錯他說什麼吧!', `FemaleText_loc7`='¡NO creo que haya dicho eso!' WHERE `ID`=52305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발 좀 일어나요, 고엘! 이렇게 끝낼 순 없다고요! 어떻게 여기까지 왔는데!', `FemaleText_loc4`='该死，古伊尔，快醒过来！一切不能就这样结束！我们绝不能失败！', `FemaleText_loc5`='該死的，高爾─快醒來!結果不該是這樣!我們已經付出太多努力了!', `FemaleText_loc7`='Maldito seas... ¡DESPIERTA! ¡No dejes que esto termine así! ¡No podemos fallar ahora!' WHERE `ID`=52306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 참는다.', `MaleText_loc4`='我们要有耐心。', `MaleText_loc5`='我們耐心的等。', `MaleText_loc7`='Somos pacientes.' WHERE `ID`=52307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 내 앞에서 참으란 말 좀 그만 해, 이 고집불통 같으니...', `FemaleText_loc4`='啊，你别再叫我保持耐心了你这个绿皮……', `FemaleText_loc5`='喂，別叫我耐心地等，你這綠皮...', `FemaleText_loc7`='No me digas que tenga PACIENCIA, especie de...' WHERE `ID`=52308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제. 일어났다.', `MaleText_loc4`='现在！苏醒吧！', `MaleText_loc5`='現在!甦醒吧!', `MaleText_loc7`='AHORA. DESPIERTA.' WHERE `ID`=52309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라... 날 부르는 목소리를 들었소...$b$b여긴 어디요?', `MaleText_loc4`='阿格娜……我听到了你的声音……呼唤着我……$b$b我们在哪？', `MaleText_loc5`='阿格拉...我聽到妳...叫我回來...我們在哪?', `MaleText_loc7`='Aggra... Escuché tu voz... me llamabas...$B$B¿Dónde estamos?' WHERE `ID`=52310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집에 거의 왔어요, 내 사랑. 남은 시간이 얼마 없어요... 그대는 또 변할 거예요, 고엘. 하지만 제가 찾겠습니다. 포기하지 않겠어요!', `FemaleText_loc4`='你就要到家了，我的爱人。我们的时间很短……你又要变形了，古伊尔——但我会找到你！我永远不会放弃你！', `FemaleText_loc5`='就快到家了，我的摯愛。我們相處的時間太短...你將再次轉變，高爾─但我一定會找到你!不會放棄你!', `FemaleText_loc7`='Ya casi estás en casa, mi amor. Nuestro tiempo es tan breve... Volverás a cambiar, Go''el, ¡pero yo te encontraré! ¡Nunca te dejaré!' WHERE `ID`=52311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라? 아그라! 목소리가 안 들려...', `MaleText_loc4`='阿格娜？阿格娜！我听不见——', `MaleText_loc5`='阿格拉?阿格拉!我聽不到-我', `MaleText_loc7`='¿Aggra? ¡Aggra! No puedo oírte... no puedo...' WHERE `ID`=52312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹아내린 알이 부화하려고 합니다!', `MaleText_loc4`='熔火之卵开始孵化了！', `MaleText_loc5`='熔岩蛋開始孵化了!', `MaleText_loc7`='¡Los huevos de magma empiezan a abrirse!' WHERE `ID`=52313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알리스라조르가 빠른 속도로 원을 그리며 날아다닙니다! 그녀의 세찬 날갯짓에 화염의 날개가 없어질 것입니다!', `FemaleText_loc4`='奥利瑟拉佐尔开始高速盘旋！狂风将移除火焰之翼的效果！', `FemaleText_loc5`='艾里絲拉卓開始快速地在空中盤旋!帶起的狂風將移除火焰之翼!', `FemaleText_loc7`='Alysrazor empieza a volar rápido en círculos. ¡Los fuertes vientos eliminarán las Alas de llamas!' WHERE `ID`=52314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t 알리스라조르의 세찬 날갯짓이 지역 중앙에 |cFFFF0000|Hspell:99794|h[불타는 소용돌이]|h|r를 생성합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t一股来自|cFFFF0000|Hspell:99794|h[火焰漩涡]|h|r的强风！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t狂烈的風形成了一股|cFFFF0000|Hspell:99794|h[熾炎漩渦]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_mage_firestarter.blp:20|t ¡Los vientos intensos forman un |cFFFF0000|Hspell:99794|h[Vórtice ígneo]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t 알리스라조르의 세찬 날갯짓이 지역 중앙에 |cFFFF0000|Hspell:99794|h[불타는 소용돌이]|h|r를 생성합니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t一股来自|cFFFF0000|Hspell:99794|h[火焰漩涡]|h|r的强风！', `FemaleText_loc5`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t狂烈的風形成了一股|cFFFF0000|Hspell:99794|h[熾炎漩渦]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_mage_firestarter.blp:20|t ¡Los vientos intensos forman un |cFFFF0000|Hspell:99794|h[Vórtice ígneo]|h|r!' WHERE `ID`=52315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\spell_holiday_tow_spicecloud.blp:20|t 알리스라조르의 불꽃이 |cFFFF0000|Hspell:99432|h[완전 연소]|h|r됩니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_holiday_tow_spicecloud.blp:20|t奥利瑟拉佐尔的火焰|cFFFF0000|Hspell:99432|h[燃尽]|h|r了！', `FemaleText_loc5`='|TInterface\\Icons\\spell_holiday_tow_spicecloud.blp:20|t艾里絲拉卓的火焰|cFFFF0000|Hspell:99432|h[耗盡]|h|r了!', `FemaleText_loc7`='|TInterfaceIconsspell_holiday_tow_spicecloud.blp:20|t¡El fuego de Alysrazor |cFFFF0000|Hspell:99432|h[se apaga]|h|r!' WHERE `ID`=52316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\inv_elemental_primal_fire.blp:20|t 알리스라조르의 불꽃이 |cFFFF0000|Hspell:99922|h[재점화]|h|r됩니다!', `FemaleText_loc4`='|TInterface\\Icons\\inv_elemental_primal_fire.blp:20|t奥利瑟拉佐尔的火焰核心重新|cFFFF0000|Hspell:99922|h[引燃]|h|r了！', `FemaleText_loc5`='|TInterface\\Icons\\inv_elemental_primal_fire.blp:20|t艾里絲拉卓的熾熱核心又|cFFFF0000|Hspell:99922|h[點燃]|h|r了!', `FemaleText_loc7`='|TInterfaceIconsinv_elemental_primal_fire.blp:20|t¡El núcleo ígneo de Alysrazor |cFFFF0000|Hspell:99922|h[vuelve a encenderse]|h|r!' WHERE `ID`=52317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t 알리스라조르가 |cFFFF0000|Hspell:99925|h[극한의 힘]|h|r을 발휘합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t奥利瑟拉佐尔处于|cFFFF0000|Hspell:99925|h[蓄满力量]|h|r状态！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_improvedfirenova.blp:20|t艾里絲拉卓正處於|cFFFF0000|Hspell:99925|h[顛峰力量]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_improvedfirenova.blp:20|t¡Alysrazor ha alcanzado su |cFFFF0000|Hspell:99925|h[Máximo poder]|h|r!' WHERE `ID`=52318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 난 새 주인님을 섬긴다, 필멸자여!', `FemaleText_loc4`='凡人们，我现在侍奉新的主人！', `FemaleText_loc5`='我現在有新的主人了，凡人!', `FemaleText_loc7`='¡Mortales, ahora sirvo a un nuevo amo!' WHERE `ID`=52319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불타 버려라!', `FemaleText_loc4`='燃烧吧！', `FemaleText_loc5`='燒吧!', `FemaleText_loc7`='¡ARDE!' WHERE `ID`=52320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분의 영광을 위해!', `FemaleText_loc4`='为了主人的荣耀！', `FemaleText_loc5`='為了他的榮耀!', `FemaleText_loc7`='¡En su honor!' WHERE `ID`=52321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 하늘은 나의 것이다!', `FemaleText_loc4`='天空，归我统治！', `FemaleText_loc5`='這片天空屬於我。', `FemaleText_loc7`='¡Estos cielos son MÍOS!' WHERE `ID`=52322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘에서 불살라 주겠다!', `FemaleText_loc4`='我会从空中烧死你们！', `FemaleText_loc5`='我會從空中燒死你!', `FemaleText_loc7`='¡Los quemaré desde el cielo!' WHERE `ID`=52323;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불... 불이여...', `FemaleText_loc4`='火焰……火焰……', `FemaleText_loc5`='火...火...', `FemaleText_loc7`='Fuego... fuego...' WHERE `ID`=52324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화염으로 다시 태어났노라!', `FemaleText_loc4`='浴火重生！', `FemaleText_loc5`='由火焰中重生!', `FemaleText_loc7`='¡Renazco en la llama!' WHERE `ID`=52325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빛이... 꺼져선... 안 돼...', `FemaleText_loc4`='烈焰之光……不能熄灭……', `FemaleText_loc5`='火焰...不能熄滅啊...', `FemaleText_loc7`='La luz... no debe apagarse...' WHERE `ID`=52326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주시여, 우리에게 힘을 내리소서!', `MaleText_loc4`='我们将共同恳求火焰之主！', `MaleText_loc5`='我們共同呼喚火焰之王!', `MaleText_loc7`='¡Juntos invocamos al Señor del Fuego!', `FemaleText_loc1`='불의 군주시여, 우리에게 힘을 내리소서!', `FemaleText_loc4`='我们将共同恳求火焰之主！', `FemaleText_loc5`='我們共同呼喚火焰之王!', `FemaleText_loc7`='¡Juntos invocamos al Señor del Fuego!' WHERE `ID`=52327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주시여, 힘을 주소서!', `MaleText_loc4`='我们在此恳求您，炎魔之王！', `MaleText_loc5`='我們呼喚你，炎魔!', `MaleText_loc7`='¡Te invocamos, Señor del Fuego!' WHERE `ID`=52328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 힘을 보아라!', `MaleText_loc4`='见证他的力量！', `MaleText_loc5`='看看他的力量!', `MaleText_loc7`='¡Contemplen su poder!' WHERE `ID`=52329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염의 장엄함을 지켜봐라!', `MaleText_loc4`='目睹烈焰君王！', `MaleText_loc5`='見證壯麗的火焰。', `MaleText_loc7`='¡Presencien la majestuosidad de la llama!' WHERE `ID`=52330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅의 분노를 벗어날 순 없다!', `MaleText_loc4`='没人能逃过火焰之地的愤怒！', `MaleText_loc5`='無人可倖免於火源之界的怒火!', `MaleText_loc7`='¡Nadie escapará a la ira de las Tierras de Fuego!' WHERE `ID`=52331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불의 군주시여, 힘을 주소서!', `FemaleText_loc4`='我们在此恳求您，炎魔之王！', `FemaleText_loc5`='我們呼喚你，炎魔!', `FemaleText_loc7`='¡Te invocamos, Señor del Fuego!' WHERE `ID`=52332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분의 힘을 보아라!', `FemaleText_loc4`='目睹他的力量！', `FemaleText_loc5`='看看他的力量!', `FemaleText_loc7`='¡Contemplen su poder!' WHERE `ID`=52333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿지 않는 자, 불로 멸하리라!', `FemaleText_loc4`='无信者将在火焰中毁灭！', `FemaleText_loc5`='把不信者全都燒死!', `FemaleText_loc7`='¡Que los infieles perezcan en el fuego!' WHERE `ID`=52334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<조용히 당신을 바라보는 그림자 감시자>', `FemaleText_loc4`='<暗影守望者静静地看着你。>', `FemaleText_loc5`='<暗影看守者默默地看著你。>', `FemaleText_loc7`='<La celadora de las Sombras te mira en silencio.>' WHERE `ID`=52335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것과 비슷한 것을 본 적이 있습니까?', `MaleText_loc4`='你见过这样的东西吗？', `MaleText_loc5`='你有見過像這樣的東西嗎?', `MaleText_loc7`='¿Alguna vez has visto algo parecido?', `FemaleText_loc1`='이것과 비슷한 것을 본 적이 있나요?', `FemaleText_loc4`='你见过这样的东西吗？', `FemaleText_loc5`='你有見過像這樣的東西嗎?', `FemaleText_loc7`='¿Alguna vez has visto algo parecido?' WHERE `ID`=52336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발밑에 있는 대지가 신음하며 몸서리치고 있습니다. 하늘에서는 불의 비가 내리고 있습니다. 대기는 모든 생명체를 질식시키고 있지요. 이곳이 바로 진정한 불의 군주의 왕국입니다.', `MaleText_loc4`='大地在我们脚下战栗，呻吟。火雨从空中倾泻而下。生灵在炽热的空气中窒息。这才是炎魔之王的国度。', `MaleText_loc5`='我們腳下的土地在呻吟和發抖。天空下著火雨。空氣擠壓著所有生命。這的確是炎魔的領域。', `MaleText_loc7`='La tierra gruñe y tiembla bajo nuestros pies. Llueve fuego desde el cielo. El aire asfixia toda la vida. Es cierto que este es el reino del Señor del Fuego.' WHERE `ID`=52337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 안심해서는 안 됩니다. 하이잘은 아직 건재하지만, 우리가 불의 군주 앞에서 나약해진다면 모든 것을 잃게 될 것입니다. 고대정령의 힘이 우리와 함께하기를.', `FemaleText_loc4`='我们还不能休息，孩子。海加尔还没有沦陷。但如果我们在炎魔之王的门前踯躅，仍有可能一败涂地。愿远古半神的力量与我们同在。', `FemaleText_loc5`='我們還不能休息，孩子。海加爾還沒被摧毀，但如果我們在炎魔的門口倒下，一切努力還是可能會付諸流水。希望先祖們能與我們同在。', `FemaleText_loc7`='No podemos descansar todavía, joven. Hyjal todavía resiste, pero si flaqueamos en el umbral del Señor del Fuego, todo estará perdido. Que la fuerza de los Ancestros esté con nosotros.' WHERE `ID`=52338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 폭풍까마귀들은 이 고밀도의 대기 속에서 날아오르려고 애만 쓰고 있는데, 저 산등성이에 있는 불꽃매들은 손쉽게 날아오르는 것 같군요.$B$B불꽃매들은 불의 세계에 있는 다른 생물들처럼 사납기는 하지만, 그 모습 자체는 아름답기만 해요.', `FemaleText_loc4`='风暴乌鸦很难在这种高密度的空气中飞行，可那边山脊上的火鹰翱翔起来却好像很轻松。$B$B它们和这片火焰平原上的其他生物一样狂野，但它们的形态却十分美丽。', `FemaleText_loc5`='我們的風暴烏鴉在如此高密度的空氣中很難飛行，但是在那個山頭的火鷹看起來游刃有餘。$b$b牠們跟其他火焰界域的生物一樣狂野，但是牠們的形態有其美麗之處。', `FemaleText_loc7`='A nuestros cuervos de tormenta les cuesta volar en este aire con una densidad tan alta, pero los halcones de fuego de esa cresta planean con facilidad.$B$BSon tan salvajes como las criaturas del plano del Fuego, sin embargo, hay belleza en sus formas.' WHERE `ID`=52339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 흐르면, 이 땅을 되살릴 수 있을 것이다.', `MaleText_loc4`='只要有足够的时间，我们就能恢复这片土地。', `MaleText_loc5`='隨著時間過去，我們也許可以使這片大地回復生機。', `MaleText_loc7`='Con tiempo, quizá podamos restaurar esta tierra.' WHERE `ID`=52340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 지역을 간신히 지키고만 있을 뿐입니다. 우리와 함께할 강력한 병력이 최대한 많이 필요합니다.', `MaleText_loc4`='我们只不过是勉强站稳脚跟而已。所以我们需要每一个健全的士兵全部到岗。', `MaleText_loc5`='我們僅僅能守住戰線。我們這裡需要每一個有戰力的士兵回到他的崗位上。', `MaleText_loc7`='Apenas podemos mantenernos en nuestra posición. Es necesario que todos los soldados que estén en condiciones de luchar se presenten al servicio.' WHERE `ID`=52341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전쟁이 단지 생명을 보호하기 위해서일 뿐일까요? 씨앗이 땅 위로 솟아오르려고 애쓰는 것처럼, 우리 역시 존재하기 위해 싸우는 거죠.', `FemaleText_loc4`='除了挣扎求生，战争还有什么其他意义呢？就像种子要努力破土发芽一样，我们也要为自己的生存而战。', `FemaleText_loc5`='戰爭是什麼，不就是對生命的執著嗎?看著種子努力想要從土中發芽，就像是我們為了自己的生存而戰。', `FemaleText_loc7`='¿Qué es la guerra sino la preservación de la vida? Así como la semilla lucha para emerger de la tierra, nosotros luchamos por nuestra propia existencia.' WHERE `ID`=52342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 당신 얼굴에 뭐가 묻었잖아요!', `FemaleText_loc4`='噢喔，你脸上好像有东西！', `FemaleText_loc5`='呃，你臉上有東西!', `FemaleText_loc7`='¡Oh, oh, tienes algo en la cara!' WHERE `ID`=52343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 이 전쟁에서 이길 수 있을까요? 시간이 지나면 알 수 있겠죠.', `FemaleText_loc4`='我们能否赢得这场战争？只有天知道。', `FemaleText_loc5`='我們會贏得這場戰爭嗎?只有百里香知道。', `FemaleText_loc7`='¿Ganaremos esta guerra? El tiempo lo dirá.' WHERE `ID`=52344;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말이지 여기는 찜통이군요. 누가 온도 좀 올려달라고 했었나 보죠?', `FemaleText_loc4`='这里可真闷热。有人让他们升高温度了吗？', `FemaleText_loc5`='這下面悶死了。有人叫他們開暖氣嗎?', `FemaleText_loc7`='Hace un calor sofocante aquí abajo. ¿Ya les ha dicho alguien que apaguen la calefacción?' WHERE `ID`=52345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알리스라조르가 광폭해졌습니다! 어서 처치하십시오!', `MaleText_loc4`='奥利瑟拉佐尔不能重燃了！快击败她！', `MaleText_loc5`='艾里絲拉卓無法完全重新燃起火焰!快點殺死她!', `MaleText_loc7`='¡Alysrazor no puede inflamarse de nuevo! ¡Mátala rápido!', `FemaleText_loc1`='알리스라조르가 광폭해졌습니다! 어서 처치하십시오!', `FemaleText_loc4`='奥利瑟拉佐尔不能重燃了！快击败她！', `FemaleText_loc5`='艾里絲拉卓無法完全重新燃起火焰!快點殺死她!', `FemaleText_loc7`='¡Alysrazor no puede inflamarse de nuevo! ¡Mátala rápido!' WHERE `ID`=52346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 좋아요! 함께 멋진 일을 해낼 수 있을 거예요.', `FemaleText_loc4`='我喜欢你！青出于蓝啊。', `FemaleText_loc5`='我喜歡你!八角梨的種子。', `FemaleText_loc7`='¡Me gustas! Haríamos buena pareja.' WHERE `ID`=52347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 이들은 저보고 진부하다고 하지만, 저는 오히려 그런 제가 현명하다고 생각한답니다.', `FemaleText_loc4`='有人说我很土，可我觉得自己还挺睿智的。', `FemaleText_loc5`='有人說我是鄉巴佬，但我覺得其實我還挺淵博的。', `FemaleText_loc7`='Hay quien dice que soy una sentimental, pero yo creo que soy bastante sabia.' WHERE `ID`=52348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 또 그대군요! 우리가 필요한 병력을 모을 수 있을 거로 생각하시나요?', `FemaleText_loc4`='噢，又是你呀！你觉得，我们能召集到足够的部队吗？', `FemaleText_loc5`='噢，又是你啊!你覺得我們有辦法集結到我們需要的兵力嗎?', `FemaleText_loc7`='¡Oh, eres tú otra vez! ¿Crees que podremos reunir las fuerzas que necesitamos?' WHERE `ID`=52349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 불모의 황무지는 예전에 본 적이 없습니다.', `MaleText_loc4`='我从来没见过这么荒凉的地方。', `MaleText_loc5`='我從沒來過這麼貧瘠的荒地。', `MaleText_loc7`='Nunca ha visto una tierra estéril y yerma como esta.' WHERE `ID`=52351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 베스틸락의 번식지 한가운데에 서 있습니다. 이 기둥들 너머 북쪽에는 베스틸락의 일족들이 기다리고 있습니다. 놈들은 베스틸락의 새끼들을 기를 쓰고 지키려들 것입니다.', `MaleText_loc4`='我们就站在贝丝缇拉克的产卵区中心。在北边那些柱子那边，就有她的子嗣。它们会拼命保护她的幼崽的。', `MaleText_loc5`='我們站在貝絲堤拉克孵化後代的心臟地帶。穿過北方那些柱子，她的孩子們正在等著。他們會毫不懈怠地保護她的後代。', `MaleText_loc7`='Estamos en el corazón del lugar de cría de Beth''tilac. Más allá de esos pilares que hay al norte, su linaje aguarda. Defenderán a los más jóvenes sin descanso.' WHERE `ID`=52352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시자에 대해 그대가 궁금해하는 점은 전장에서 보시면 알 수 있을 것입니다.', `FemaleText_loc4`='你关于守望者的一切疑问，都将在战场上找到答案。', `FemaleText_loc5`='你對於看守者有任何的問題都可以在戰場上得到答案。', `FemaleText_loc7`='Cualquier pregunta que tengas sobre las Celadoras de las Sombras puede obtener respuesta en el campo de batalla.' WHERE `ID`=52353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시자가 어떤 이들이냐고요? 우리는 치명적인 일격으로 적을 정확히 동강 내버립니다.', `FemaleText_loc4`='守望者是什么人？我们是精密的杀戮机器。', `FemaleText_loc5`='看守者是什麼?我們是最後一擊時那精準的一刀。', `FemaleText_loc7`='¿Qué son las Celadoras? Somos el corte preciso de un golpe mortal.' WHERE `ID`=52354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시자가 어떤 이들이냐고요? 죽음의 순간 바로 직전에 윙윙거리며 돌아가는 칼날 바람이지요.', `FemaleText_loc4`='守望者是什么人？我们是播撒死亡的旋刃。', `FemaleText_loc5`='看守者是什麼?我們是死亡前那一刻刀刃揮舞的低吟。', `FemaleText_loc7`='¿Qué son las Celadoras? Somos el zumbido de una hoja que parte el aire en dos, instantes antes de la muerte.' WHERE `ID`=52355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시자가 어떤 이들이냐고요? 바로 그림자 속의 고요함입니다.', `FemaleText_loc4`='守望者是什么人？我们是无声的暗影。', `FemaleText_loc5`='看守者是什麼?我們是暗影中的沉默。', `FemaleText_loc7`='¿Qué son las Celadoras? Somos el silencio en las sombras.' WHERE `ID`=52356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아군의 전황은 어떻습니까?', `MaleText_loc4`='我们在战场上表现如何？', `MaleText_loc5`='我們的戰況如何?', `MaleText_loc7`='¿Qué tal nos va en la batalla?', `FemaleText_loc1`='아군의 전황은 어떤가요?', `FemaleText_loc4`='我们在战场上表现如何？', `FemaleText_loc5`='我們的戰況如何?', `FemaleText_loc7`='¿Qué tal nos va en la batalla?' WHERE `ID`=52357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 거점을 확보하려고 많은 것을 포기했으니, 이제 끊임없이 싸워 지켜내야만 한다. 아군의 수비가 취약하지만, 계속해서 전진하려는 노력은 앞으로 더욱 강력한 동맹군이 생기게 해줄 것이다.$B$B용사여, 바로 지금이야말로 용기를 가져야 할 때다.', `MaleText_loc4`='我们用无数的牺牲才换来这个据点，但为了保住它，我们还要继续战斗。虽然我们的防御很薄弱，但只要我们不断推进战线，将来一定能招来更强大的盟友。$B$B现在，拿出勇气来吧，勇士。', `MaleText_loc5`='我們犧牲了許多才能獲得這個據點，而我們必須持續戰鬥才能守住它。雖然目前防禦有點薄弱，但是持續推進可以幫我們在未來招募到更強大的盟友。$B$B現在就是展現勇氣的時刻了，勇士。', `MaleText_loc7`='Hemos renunciado a mucho para conseguir esta posición aquí y debemos seguir luchando para mantenerla. Aunque nuestras defensas sean débiles, si seguimos esforzándonos por avanzar, en el futuro podremos reclutar aliados más fuertes.$B$B¡Es la hora de mostrar valor, campeón! ¡Muéstranos por qué estás luchando!' WHERE `ID`=52359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 세운 공 덕분에 우리는 가까스로 이 거점을 지켜냈다.$B$B그대는 우리 동족들에게 소중한 동맹군을 데려다 주었지만, 적군은 계속해서 우리를 가차 없이 공격하고 있다.$B$B우리는 이곳을 지켜내야만 한다. 그렇지 않으면 우리가 그토록 얻고자 했던 것을 잃게 될 것이다.', `MaleText_loc4`='我们终于守住了这个据点，这多亏了你。$B$B你帮我们找到了一个珍贵的盟友。可是，敌人对我们的进攻不会停歇。$B$B我们必须守住这里，否则就会失去我们流血牺牲所换来的一切。', `MaleText_loc5`='我們總算是足以防禦這個據點，多虧你的幫忙。$B$B你成功替我們招募了一個很不錯的盟友，但是敵人仍然不間斷地攻擊我們。$B$B我們必須守住這裡，否則一切的犧牲就前功盡棄了。', `MaleText_loc7`='Nos las hemos arreglado para defender esta posición, sobre todo gracias a ti. Has conseguido reclutar un aliado muy valioso para nuestras filas. Sin embargo, el enemigo sigue asaltándonos sin descanso.$b$bDebemos mantenernos firmes o perderemos lo que tanto nos ha costado ganar.' WHERE `ID`=52360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 노력으로 그림자 감시자와 갈퀴발톱의 드루이드를 우리 쪽으로 데려왔구나.$B$B훌륭하다, $c|1이여;여;.$B$B조금씩 진전을 보이고 있지만, 아직도 해야 할 일이 많이 남아 있다.$B$B적의 공세가 계속되니 우리는 계속해서 방어를 강화해야만 한다. $n, 지금 우리는 세 가지가 필요하다.$B$B늙은가지와 고대 수호자는 하이잘을 수호하지만 그들의 힘은 이곳에서도 아주 유용할 것이다.$B$B우리의 의지가 아무리 굳건하더라도, 무기고에는 보급품이 더 많이 있어야 한다.$B$B마지막으로 엘룬의 맑은 물은 피곤함에 지친 아군을 치유하고 재생시켜줄 것이다.$B$B이 세 가지는 이곳에서의 일이 끝나기 전에 갖춰야만 한다.$B$B가라, $n. 그대의 헌신은 우리가 승리하는 데 꼭 필요한 것이다.', `MaleText_loc4`='在你的帮助下，暗影守望者和猛禽德鲁伊站到了我们这边。$B$B干得好，$c。$B$B我们已经开始扩张了，但还有许多事要做。$B$B在敌人的持续攻击下，我们仍继续建造防御工事。我们需要三样东西，$n。$B$B老树干和远古的保卫者们正守护着海加尔，可这里也急需他们的力量。$B$B虽然我们士气正盛，可我们的军械库仍需要补充额外的军用物资。$B$B最后，艾露恩的神圣之水能够治愈我们的伤兵，并让他们重获新生。$B$B为了完成这里的任务，我们需要这些东西。$B$B去吧，$n。你的努力对我们取得胜利至关重要。', `MaleText_loc5`='透過你的努力，暗影看守者和猛禽德魯伊加入了我們這一方。$B$B做得好，$c。$B$B我們目前稍具優勢，但是還有許多工作得進行。$B$B敵人在攻擊我們的同時，我們必須繼續強化我們的防禦。我們需要三樣東西，$n。老枝與遠祖保衛者們正守護著海加爾，但是他們的力量在這裡將會是無價的助力。$B$B即使我們十分英勇，我們的軍械庫還是需要更多的軍事補給品。$B$B最後，伊露恩的水中寧靜的力量可以使我們疲憊的士兵恢復力量並治療他們。$B$B我們需要這些東西，我們的工作才算完成。$B$B去吧，$n。你的努力是我們贏得勝利的關鍵。', `MaleText_loc7`='Tu empeño ha traído a nuestro bando tanto a las celadoras de las Sombras como a los druidas de la Garfa.$B$BExcelente, $c.$B$BGanamos terreno, pero aún queda mucho por hacer.$B$BEl enemigo no deja de acosarnos y tenemos que seguir reforzando nuestras defensas. Necesitamos tres cosas, $n.$B$BTallosaúco y los protectores ancestrales guardan Hyjal, pero su fuerza sería de gran ayuda aquí.$B$BNuestro valor es inquebrantable, pero nuestra armonía requiere más suministros militares.$B$BFinalmente, la fuerza de las aguas calmantes de Elune sanará y rejuvenecerá a nuestros soldados cansados.$B$BNecesitamos esas cosas para poder terminar nuestro trabajo aquí.$B$BVe, $n. Tus esfuerzos son cruciales para nuestra victoria.' WHERE `ID`=52361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 훌륭한 일을 해냈구나, $c|1이여;여;. 이제 우리가 이곳에 있다는 걸 라그나로스가 더는 모르지 않게 되었다. 결국 우리는 라그나로스에게 눈엣가시 같은 존재지. 그의 분노가 커지는 것과 같이 우리 또한 앞으로 계속 나아가야 한다.$B$B이곳에서 계속 경계심을 늦추지 말아야 하지만, 이제 마지막 전투에 집중해야겠구나. 불의 군주를 직접 만날 때가 왔다.', `MaleText_loc4`='你做得很好，$c。拉格纳罗斯已经不能再无视我们的存在了。我们已经成了他的心腹大患。虽然他已经怒火高涨，我们仍要继续推进。$B$B在这里，我们必须时刻保持警惕，但我们应该考虑一下最终的决战了。挑战炎魔之王本人的时刻到了。', `MaleText_loc5`='你做得很好，$c。我們的存在已經無法瞞過拉格納羅斯。我們對他來說已經可以算是芒刺在背。他的怒意正在逐步增加，所以我們也必須繼續推進。$B$B我們在這裡必須保持警戒，但也該把注意力放到最後一戰上面了。是時候面對炎魔了。', `MaleText_loc7`='Has estado bien, $c. Nuestra presencia en este lugar ya no le pasará desapercibida a Ragnaros. Somos una importante espina en su costado. A medida que aumenta su ira, tenemos que seguir avanzando.$B$BTenemos que permanecer vigilantes, pero es hora de pensar en la batalla final. Es hora de enfrentarnos al Señor del Fuego en persona.' WHERE `ID`=52362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 눈으로 바라보십시오. 무엇이 보입니까? 어떤 것이 느껴지지요?', `FemaleText_loc4`='用你的眼睛去看。你看到了什么？你感觉到了什么？', `FemaleText_loc5`='用你的雙眼瞧瞧。你看到了什麼?你感覺到了什麼?', `FemaleText_loc7`='Mira con tus ojos. ¿Qué ves? ¿Qué sientes?' WHERE `ID`=52363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아비아나의 바람이여, 불길을 막아낼 힘을 주십시오.', `MaleText_loc4`='艾维娜之风，赐予我压制火焰的力量吧！', `MaleText_loc5`='艾維娜之風，賜予我對抗火焰的力量。', `MaleText_loc7`='Vientos de Aviana, concédanme la fuerza para mantener las llamas a raya.' WHERE `ID`=52364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 불의 땅 침공을 준비하는 동안, 불의 군주는 부하들을 보내 우리 부대의 접근을 막아내려 하고 있어요. 우리는 이곳에서 물러설 수가 없어요. 적의 세력과 세계수 사이에 남은 건 우리뿐이니까요.', `FemaleText_loc4`='在我们准备进攻火焰之地的时候，炎魔之王派出了手下爪牙来拦截我们。我们在这里的据点绝对不能陷落，我们已经是保卫世界之树的最后一道防线了。', `FemaleText_loc5`='當我們正準備進軍火源之界時，炎魔派了他的爪牙來反擊。我們在這裡的據點不能失陷。我們是他們與世界之樹之間最後的一道防線了。', `FemaleText_loc7`='Mientras nos preparamos para invadir las Tierras de Fuego, el Señor del Fuego ha enviado a sus esbirros para repeler nuestro ataque. Nuestra posición no debe caer. Nosotros somos lo único que hay entre ellos y el Árbol del Mundo.' WHERE `ID`=52366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요, $n 님. 불의 땅 침공에 지원하러 오셨나요?', `FemaleText_loc4`='欢迎你，$n。你是来参加对火焰之地的进攻的吗？', `FemaleText_loc5`='歡迎，$n。你是來加入對火源之界的入侵行動的嗎?', `FemaleText_loc7`='Te doy la bienvenida, $n. ¿Has venido a unirte a la invasión de las Tierras de Fuego?' WHERE `ID`=52367;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리에겐 불의 땅으로 진군할 힘이 아직 없어요. 우선은 병력과 보급품을 확보해야 해요. 이번 작전에 힘을 빌려주시겠어요?', `FemaleText_loc4`='我们暂时还无力反攻火焰之地。首先，我们得重整部队，建立补给线。你愿意帮助我们吗？', `FemaleText_loc5`='我們還沒有足夠的兵力打進火源之界。首先，我們必須重建我們的兵力和補給。你願意協助我們嗎?', `FemaleText_loc7`='Todavía no tenemos las tropas necesarias para avanzar en las Tierras de Fuego. Primero, debemos recuperar las fuerzas y conseguir suministros. ¿Nos echarás una mano?' WHERE `ID`=52368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금부터 일어날 일은 우리 모두에게 영향을 줄 거예요. 그러니 모두의 도움이 필요해요. 이번 침략을 이겨내려면 우리 모두 함께 싸워야 해요.', `FemaleText_loc4`='眼前所发生的一切与我们所有人都息息相关。每一分力量都是宝贵的。大家必须同心协力对抗入侵。', `FemaleText_loc5`='現在發生的事情會影響到所有人。我們需要每個人的幫助。我們必須一起合作對抗這樣的入侵。', `FemaleText_loc7`='Lo que ocurra ahora nos afectará a todos. Necesitamos la ayuda de todo el mundo. Debemos trabajar juntos para luchar contra esta invasión.' WHERE `ID`=52369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디 제 도움이 필요한 꼬꼬마 동물 친구들 없나요?$B$B<동물을 생각하며 두 눈을 반짝이는 마일룬>$B$B지금 당장 토끼를 꼭 껴안아 주고 싶어요!', `FemaleText_loc4`='有小动物吗需要我救助吗？$B$B<米露恩两眼放光。>$B$B我要立刻去抱抱小兔子！', `FemaleText_loc5`='有什麼小動物需要我的幫助嗎?$B$B<蜜露恩的眼睛開始發光。>$B$B我現在好想要摟隻小兔子!', `FemaleText_loc7`='¿No hay ningún animalillo achuchable que necesite mi ayuda?$b$b<Los ojos de Mylune brillan de solo pensarlo.>¡Necesito abrazar un conejito ahora mismo!' WHERE `ID`=52370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비는 잘 되고 있나요?', `FemaleText_loc4`='准备工作进展如何？', `FemaleText_loc5`='準備得如何了?', `FemaleText_loc7`='¿Qué tal van las preparaciones?' WHERE `ID`=52371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 대드루이드님께서는 쉬고 계십니다.$B$B분명히 그대를 만나면 기뻐하시겠지만, 지금은 그분을 방해하지 않는 편이 좋겠습니다.', `MaleText_loc4`='你好。大德鲁伊正在休息。$B$B我相信，你的造访一定会令他高兴的，但我们最好还是不要去打扰他。', `MaleText_loc5`='什麼事?大德魯伊正在休息。$B$B我相信他會很高興你來拜訪，但現在最好還是不要干擾他。', `MaleText_loc7`='¿Sí? El Archidruida está descansando.$B$BEstoy seguro de que le agrada tu visita, pero es mejor no molestarle ahora.' WHERE `ID`=52372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하뮬 님의 상태는 어떻습니까?', `MaleText_loc4`='哈缪尔怎么样了？', `MaleText_loc5`='哈繆爾怎樣了?', `MaleText_loc7`='¿Qué tal está Hamuul?', `FemaleText_loc1`='하뮬 님의 상태는 어떤가요?', `FemaleText_loc4`='哈缪尔怎么样了？', `FemaleText_loc5`='哈繆爾怎樣了?', `FemaleText_loc7`='¿Qué tal está Hamuul?' WHERE `ID`=52373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라 말씀드리기 어렵군요. 하뮬 님은 심각한 부상을 당했습니다. 물론, 강인한 드루이드시지만, 다시 온전한 상태로 회복하시려면 긴 시간과 인내가 필요합니다.', `MaleText_loc4`='还很难说，他的伤很重。虽然他是位强大的德鲁伊，但我们还需要耐心地等待他彻底恢复。', `MaleText_loc5`='這很難說。他的傷勢十分嚴重。即使他是如此強大的德魯伊，也會需要時間和耐心才能完全康復。', `MaleText_loc7`='Es difícil saberlo. Sus heridas son profundas. Aunque es un druida muy poderoso, necesitaremos tiempo y paciencia para conseguir que se recupere por completo.' WHERE `ID`=52374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님. 이번 침공 작전을 돕고 계십니까? 그대와 같은 숙련된 $c|1이라면;라면; 우리 부대에 큰 도움이 될 겁니다.', `FemaleText_loc4`='你好，$n。你是来协助我们进攻的嘛？像你这样出色的$c一定成为我们的宝贵外援。', `FemaleText_loc5`='哈囉，$n。你要幫忙進攻嗎?有你這麼強的$c加入，對我們來說會是很大的幫助。', `FemaleText_loc7`='Hola, $n. ¿Estás echando una mano contra la invasión? $gUn:Una; $c como tú debe ser de mucha ayuda para nuestras fuerzas.' WHERE `ID`=52376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일을 제대로 끝마칠 줄 아는 사람이 필요하오. 당신을 믿어도 되겠소, $c?', `MaleText_loc4`='我需要一个真正有能力的人。我能指望你吗，$c？', `MaleText_loc5`='我需要有人能把這事情搞定。我能相信你嗎，$c。', `MaleText_loc7`='Necesito a alguien que sea capaz de hacer el trabajo. ¿Puedo contar contigo, $c?' WHERE `ID`=52377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계 좀 더 깊은 곳으로 안내해 드리겠습니다.', `MaleText_loc4`='你好，法师。你愿意领略高深莫测的魔法世界吗？', `MaleText_loc5`='歡迎，法師。我應該提供你關於魔法世界更深的見解嗎?', `MaleText_loc7`='Buenas, $gmago:maga;. ¿Quieres que te enseñe más secretos del mundo de la magia?', `FemaleText_loc1`='안녕하십니까. 당신을 심오한 마법의 세계 좀 더 깊은 곳으로 안내해 드리겠습니다.', `FemaleText_loc4`='你好，法师。你愿意领略高深莫测的魔法世界吗？', `FemaleText_loc5`='歡迎，法師。我應該提供你關於魔法世界更深的見解嗎?', `FemaleText_loc7`='Buenas, $gmago:maga;. ¿Quieres que te enseñe más secretos del mundo de la magia?' WHERE `ID`=52378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `MaleText_loc4`='你好，$c。我有个小建议：当你在世界各地旅行时，要小心应付魔法。未经训练的外行人很容易被魔法灼伤。', `MaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `MaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.', `FemaleText_loc1`='반갑습니다, $c님. 제가 조언 하나만 하지요. 세상을 여행할 때 부디 마법을 조심하시기 바랍니다. 마법에 서투른 자들은 새카맣게 타버릴 수 있으니까요.', `FemaleText_loc4`='你好，$c。我有个小建议：当你在世界各地旅行时，要小心应付魔法。未经训练的外行人很容易被魔法灼伤。', `FemaleText_loc5`='很高興見到你，$c。我給你的建議是:當你在世界旅行的時候，要當心魔法可能會傷害那些未受訓練的人。', `FemaleText_loc7`='Hola, $c. Mi consejo para ti es este: cuando viajes por el mundo, ten cuidado con la magia porque puede acabar con el profano.' WHERE `ID`=52379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 지금은 설교할 시간이 없습니다. 다른 곳에 가서 훈련을 받으십시오.', `MaleText_loc4`='我现在没有时间来说教，$c。到别的地方去寻找你的知识吧。', `MaleText_loc5`='我現在沒空說教，$c。去別的地方尋找你的知識。', `MaleText_loc7`='No tengo tiempo para sermones ahora, $c. Busca tus conocimientos en otra parte.', `FemaleText_loc1`='$c|1이여;여;, 지금은 설교할 시간이 없군요. 다른 곳에 가서 훈련을 받으세요.', `FemaleText_loc4`='我现在没有时间来说教，$c。到别的地方去寻找你的知识吧。', `FemaleText_loc5`='我現在沒空說教，$c。去別的地方尋找你的知識。', `FemaleText_loc7`='No tengo tiempo para sermones ahora, $c. Busca tus conocimientos en otra parte.' WHERE `ID`=52380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛은 우리에게 승리를 위한 힘과 마력을 허락합니다.', `MaleText_loc4`='圣光给了我们通往胜利的力量和魔法。', `MaleText_loc5`='聖光給我們足以獲得勝利的力量和魔法。', `MaleText_loc7`='La Luz nos da la fuerza y la magia para triunfar.', `FemaleText_loc1`='성스러운 빛은 우리에게 승리를 위한 힘과 마력을 허락합니다.', `FemaleText_loc4`='圣光给了我们通往胜利的力量和魔法。', `FemaleText_loc5`='聖光給我們足以獲得勝利的力量和魔法。', `FemaleText_loc7`='La Luz nos da la fuerza y la magia para triunfar.' WHERE `ID`=52381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 그대에게서 힘을 향한 욕망이 느껴집니다.', `MaleText_loc4`='我能感觉到你对力量的渴望，$c。', `MaleText_loc5`='我可以感覺到你對力量的渴望，$c。', `MaleText_loc7`='Puedo sentir tu deseo de poder, $c.', `FemaleText_loc1`='$c|1이여;여;, 그대에게서 힘을 향한 욕망이 느껴집니다.', `FemaleText_loc4`='我能感觉到你对力量的渴望，$c。', `FemaleText_loc5`='我可以感覺到你對力量的渴望，$c。', `FemaleText_loc7`='Puedo sentir tu deseo de poder, $c.' WHERE `ID`=52382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 죄송합니다. 순간 그대를 근성이 있는 다른 이들과 착각했습니다. 가던 길이나 가십시오. 훈련받지 않은 자는 우리의 비밀을 알 수 없습니다.', `MaleText_loc4`='抱歉，$c。我把你错认成个有骨气的人。滚开，我们的秘密不是那些没经过训练的家伙有资格知道的。', `MaleText_loc5`='很抱歉，$c。我以為你是個有骨氣的人。你走吧，我們的秘密不會告訴不相干的人。', `MaleText_loc7`='Lo lamento, $c. Te confundí con alguien con agallas. Vete; nuestros secretos no son para oídos inexpertos.', `FemaleText_loc1`='$c|1이여;여;, 죄송합니다. 순간 그대를 근성이 있는 다른 이들과 착각했습니다. 가던 길이나 가십시오. 훈련받지 않은 자는 우리의 비밀을 알 수 없습니다.', `FemaleText_loc4`='抱歉，$c。我把你错认成个有骨气的人。滚开，我们的秘密不是那些没经过训练的家伙有资格知道的。', `FemaleText_loc5`='很抱歉，$c。我以為你是個有骨氣的人。你走吧;我們的秘密不告訴不牢靠的人。', `FemaleText_loc7`='Lo lamento, $c. Te confundí con alguien con agallas. Vete; nuestros secretos no son para oídos inexpertos.' WHERE `ID`=52383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 도망칠 수 없다. 이제 맞서 싸울 시간이다.', `MaleText_loc4`='我们已经无路可逃了。该停下来战斗了。', `MaleText_loc5`='我們已經逃無可逃。是時候挺身而戰了。', `MaleText_loc7`='No podemos huir más. Es hora de plantar cara.' WHERE `ID`=52384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총이 좋습니까, 아니면 활이 더 마음에 드십니까?', `MaleText_loc4`='你是喜欢枪支还是弓箭？', `MaleText_loc5`='你喜歡槍械還是弓箭?', `MaleText_loc7`='¿Te gustan más los arcos o las armas de fuego?', `FemaleText_loc1`='총이 좋습니까, 아니면 활이 더 마음에 드십니까?', `FemaleText_loc4`='你是喜欢枪支还是弓箭？', `FemaleText_loc5`='你喜歡槍械還是弓箭?', `FemaleText_loc7`='¿Te gustan más los arcos o las armas de fuego?' WHERE `ID`=52385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 전사만 가르치오, $c|1이여;여;. 다른 곳으로 가보시오.', `MaleText_loc4`='我只对战士进行训练，$c。你得去别处找找。', `MaleText_loc5`='我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', `MaleText_loc7`='Yo solo entreno a los guerreros, $c. Tendrás que buscar en otra parte.', `FemaleText_loc1`='저는 전사만 가르칩니다, $c님. 다른 곳으로 가보세요.', `FemaleText_loc4`='我只对战士进行训练，$c。你得去别处找找。', `FemaleText_loc5`='我只訓練戰士而已，$c。你得去別的地方找你的訓練師。', `FemaleText_loc7`='Yo solo entreno a los guerreros, $c. Tendrás que buscar en otra parte.' WHERE `ID`=52386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련받을 준비가 되었소, 전사여?', `MaleText_loc4`='你准备好接受训练了吗，战士？', `MaleText_loc5`='準備接受訓練了嗎，戰士?', `MaleText_loc7`='¿Estás $glisto:lista; para la instrucción, $gguerrero:guerrera;?', `FemaleText_loc1`='훈련받을 준비가 되었소, 전사여?', `FemaleText_loc4`='你准备好接受训练了吗，战士？', `FemaleText_loc5`='準備接受訓練了嗎，戰士?', `FemaleText_loc7`='¿Estás $glisto:lista; para la instrucción, $gguerrero:guerrera;?' WHERE `ID`=52387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 가는 길은 강철 같은 의지와 확고한 믿음을 가진 자만이 통과할 수 있소. $c|1이여;여;, 그대에게는 둘 중 어느 것도 보이지 않소.', `MaleText_loc4`='我们只接受那些拥有钢铁般坚定的意志、怀着永不动摇的决心的同伴。似乎这两样优点你都不具备，$C。', `MaleText_loc5`='我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', `MaleText_loc7`='El nuestro es un camino para aquellos con voluntad férrea y determinación firme. No pareces poseer ninguno de estos rasgos, $c.', `FemaleText_loc1`='우리가 가는 길은 강철 같은 의지와 확고한 믿음을 가진 자만이 통과할 수 있습니다. $c|1이여;여;, 그대에게는 둘 중 어느 것도 보이지 않네요.', `FemaleText_loc4`='我们只接受那些拥有钢铁般坚定的意志、怀着永不动摇的决心的同伴。似乎这两样优点你都不具备，$C。', `FemaleText_loc5`='我們的道路是給那些有鋼鐵意志和堅定決心的人走的。你看起來並不擁有這些特質，$c。', `FemaleText_loc7`='El nuestro es un camino para aquellos con voluntad férrea y determinación firme. No pareces poseer ninguno de estos rasgos, $c.' WHERE `ID`=52388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 더 구하고자 하시오, $n?', `MaleText_loc4`='你是来寻求进一步的指导的吗，$n？', `MaleText_loc5`='你想獲得進一步的教導嗎，$n?', `MaleText_loc7`='¿Buscas más instrucción, $n?', `FemaleText_loc1`='가르침을 더 구하고자 하시나요, $n 님?', `FemaleText_loc4`='你是来寻求进一步的指导的吗，$n？', `FemaleText_loc5`='你想獲得進一步的教導嗎，$n?', `FemaleText_loc7`='¿Buscas más instrucción, $n?' WHERE `ID`=52389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 어떻게 훈련을 도와드릴까요?', `MaleText_loc4`='$n，我如何才能帮助你继续深造呢？', `MaleText_loc5`='$n，想要我怎樣幫你進行訓練?', `MaleText_loc7`='$n, ¿cómo puedo ayudarte a mejorar tu instrucción?', `FemaleText_loc1`='$n 님, 어떻게 훈련을 도와드릴까요?', `FemaleText_loc4`='$n，我如何才能帮助你继续深造呢？', `FemaleText_loc5`='$n，想要我怎樣幫你進行訓練?', `FemaleText_loc7`='$n, ¿cómo puedo ayudarte a mejorar tu instrucción?' WHERE `ID`=52390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가르침을 받고 싶으신 모양이지만, 저는 당신을 도울 수 없습니다.', `MaleText_loc4`='如果你在寻求指导，恕我无法提供帮助。', `MaleText_loc5`='如果你在尋求訓練，我幫不上忙。', `MaleText_loc7`='Si buscas instrucción, no puedo ayudarte.', `FemaleText_loc1`='가르침을 받고 싶으신 모양이지만, 저는 당신을 도울 수 없습니다.', `FemaleText_loc4`='如果你在寻求指导，恕我无法提供帮助。', `FemaleText_loc5`='如果你在尋求訓練，我幫不上忙。', `FemaleText_loc7`='Si buscas instrucción, no puedo ayudarte.' WHERE `ID`=52391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 잘못 찾아오신 것 같군요.', `MaleText_loc4`='看来你来错地方了，$c。', `MaleText_loc5`='看來你做了錯誤的選擇，$c。', `MaleText_loc7`='Parece que te equivocaste, $c.', `FemaleText_loc1`='$c|1이여;여;, 잘못 찾아오신 것 같군요.', `FemaleText_loc4`='看来你来错地方了，$c。', `FemaleText_loc5`='看來你做了錯誤的選擇，$c。', `FemaleText_loc7`='Parece que te equivocaste, $c.' WHERE `ID`=52392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 여기까지 오면서 미행을 당하지는 않으셨겠죠?', `MaleText_loc4`='你好，$n。我希望你不是被跟踪到这里的？', `MaleText_loc5`='你好，$n。我可以相信你沒被人跟蹤嗎?', `MaleText_loc7`='Saludos, $n. Confío en que no te hayan seguido hasta aquí.', `FemaleText_loc1`='안녕하십니까, $n 님. 여기까지 오면서 미행을 당하지는 않으셨겠죠?', `FemaleText_loc4`='你好，$n。我希望你不是被跟踪到这里的？', `FemaleText_loc5`='你好，$n。我可以相信你沒被人跟蹤嗎?', `FemaleText_loc7`='Saludos, $n. Confío en que no te hayan seguido hasta aquí.' WHERE `ID`=52393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할로윈 축제의 백미는 바로 빗자루를 타는 거죠.', `FemaleText_loc4`='还有什么事儿能比骑魔法扫帚更能说明“嘿，万圣节到了”呢。', `FemaleText_loc5`='沒有比騎上掃帚更能表現出「萬鬼節到了」的感覺了。', `FemaleText_loc7`='No hay nada más típico de Halloween que un viaje en escoba.' WHERE `ID`=52394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 저는 식물 전문가랍니다. 이 지역 식물에 관해 궁금한 게 있으신가요?', `FemaleText_loc4`='你好啊！园艺可是我的强项！要打听本地的植物环境吗？', `FemaleText_loc5`='你好啊!植物是我的專長。你想要進一步了解當地的植物嗎?', `FemaleText_loc7`='¡Eh, hola! Las plantas son mi especialidad. ¿Tienes alguna pregunta sobre la flora local?' WHERE `ID`=52400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽃밭의 꽃들만큼 가슴 설레는 것도 없죠!', `FemaleText_loc4`='没有什么比花朵的绽放更能振奋人心的了！', `FemaleText_loc5`='沒有比綻放的花朵更振奮人心的東西了!', `FemaleText_loc7`='¡No existe nada más inspirador que una planta en flor!' WHERE `ID`=52401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거운 화염 앞에 무릎 꿇어라!', `MaleText_loc4`='跪拜在烈焰之前！', `MaleText_loc5`='在烈焰前屈膝吧!', `MaleText_loc7`='¡Arrodíllense ante la llama ardiente!' WHERE `ID`=52408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 고엘이... 바다에 먹히고 말았습니다. 자신의 욕망에 고통스러워 하고 있어요!', `FemaleText_loc4`='我的古伊尔……被大海吞噬了。在他自己的欲望中煎熬！', `FemaleText_loc5`='我的高爾...被海吞噬了。被他自己的欲望所折磨!', `FemaleText_loc7`='Mi Go''el... consumido por el mar. ¡Atormentado por sus propios deseos!' WHERE `ID`=52409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 이렇게 되다니! 고엘이 살아 있는 돌이 되었습니다! 저 깊은 심원의 영지로 그를 쫓아가야 합니다.$b$b대지 고리회가 테라제인의 영지를 구했으니, 그녀는 당연히 고엘을 구출하는 일에 협력할 거예요. 만약 그러지 않으면 제가 바위 어머니를 가만두지 않을 겁니다!', `FemaleText_loc4`='循环又开始了！古伊尔变成了活生生的石头！我们必须到深岩之洲的洞穴里去找他。$b$b在亲眼看到大地之环拯救了她的国度之后，塞拉赞恩应该更愿意帮我们救他了。如果她不肯，那位石母必将付出代价！', `FemaleText_loc5`='輪迴又開始了!高爾變成活石頭了!我們必須在地深之源的洞穴裡追上他。$b$b看在陶土議會剛剛救了她的王國份上，瑟拉贊恩應該會很樂意幫我們拯救他。如果她不肯，我發誓我不會放過那個又胖又醜的傢伙!', `FemaleText_loc7`='¡El ciclo empieza de nuevo! ¡Go''el se ha convertido en piedra viva! Debemos seguirlo por las cavernas de Infralar.$b$bEn vista de que El Anillo de la Tierra acaba de salvar su reino, Therazane debería estar más que dispuesta a ayudarnos a recuperarlo. Si no, ¡la Madre Pétrea tendrá que vérselas conmigo!' WHERE `ID`=52410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 영역에서 꺼져라, 벌레들아.', `MaleText_loc4`='滚出我的王国，虫子。', `MaleText_loc5`='滾出我的國度，蟲子們。', `MaleText_loc7`='Fuera de mi reino, insectos...' WHERE `ID`=52411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 빠짐없이 불태우겠다.', `MaleText_loc4`='我会看着你们燃烧。', `MaleText_loc5`='我將看你們燃燒殆盡。', `MaleText_loc7`='Haré que todos ardan.' WHERE `ID`=52412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염의 먹이가 되어라!', `MaleText_loc4`='烈焰吞噬你们！', `MaleText_loc5`='被火焰吞噬吧!', `MaleText_loc7`='¡Que la llama los consuma!' WHERE `ID`=52413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 세계가 네놈들을 집어삼키리라!', `MaleText_loc4`='火焰王国会吞噬你！', `MaleText_loc5`='火之國度將吞噬你們!', `MaleText_loc7`='¡El reino de fuego los consumirá!' WHERE `ID`=52414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아, 그 끈기 하나는 인정해 주지. 발레록은 헤아릴 수 없이 긴 시간, 이 성채를 지켜 왔다.', `MaleText_loc4`='好吧，好吧。我很佩服你们的顽强。贝尔洛克已经在这座堡垒前守卫了千百个世纪。', `MaleText_loc5`='哎呀哎呀，我真敬佩你們的毅力。巴勒羅克已經在這看門看了幾萬年了。', `MaleText_loc7`='Vaya, vaya. Admiro su tenacidad. Baleroc montó guardia ante esta fortaleza durante miles de vidas humanas.' WHERE `ID`=52415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 군주님의 거소로 들어갈 수 없다!', `MaleText_loc4`='但从未有人能进入炎魔之王的居所！', `MaleText_loc5`='但沒有人可以踏入炎魔的居所!', `MaleText_loc7`='¡Pero nadie entrará en la morada del Señor del Fuego!' WHERE `ID`=52416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 빌어라. 혹시 내가 또 살려줄지 아느냐? 자, "영웅"들이여, 어떻게 하겠는가?', `MaleText_loc4`='现在求饶，我也许会准许你们活下去。好吧，“英雄”们，你们的回答是什么？', `MaleText_loc5`='求饒吧，我或許還可以饒你們一命。怎麼樣，「英雄們」?考慮好了沒?', `MaleText_loc7`='Supliquen clemencia y quizás les permita vivir. ¿Y bien, "héroes"? ¿Qué responden?' WHERE `ID`=52417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타올라라.', `MaleText_loc4`='燃烧吧。', `MaleText_loc5`='燒吧。', `MaleText_loc7`='Arde.' WHERE `ID`=52418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 아제로스 전체가 불타리라!', `MaleText_loc4`='整个艾泽拉斯都将燃烧！', `MaleText_loc5`='整個艾澤拉斯都將燃燒!', `MaleText_loc7`='¡Pronto TODO Azeroth arderá!' WHERE `ID`=52419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 넘치도다!', `MaleText_loc4`='如此强大的力量！', `MaleText_loc5`='如此強大的力量!', `MaleText_loc7`='¡Tanto poder!' WHERE `ID`=52420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길을 막아선 대가다!', `MaleText_loc4`='葬身于火海中！', `MaleText_loc5`='你站在火焰裡!', `MaleText_loc7`='¡Te has quedado en el fuego!' WHERE `ID`=52421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재가 되어 사라져라!', `MaleText_loc4`='只留灰烬！', `MaleText_loc5`='只剩灰燼!', `MaleText_loc7`='¡Solo quedan cenizas!' WHERE `ID`=52422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 필멸자여. 너희의 스랄이 여기에 있다. 몸도 마음도... 이곳의 바위와... 하나가 되었지.', `FemaleText_loc4`='是的，凡人，你们的萨尔就在这里。他的心和灵魂都已经和石头融合了。', `FemaleText_loc5`='是的，凡人，你們的索爾在這裡。他已經與這裡的岩石融合─包括心和靈魂。', `FemaleText_loc7`='Sí, mortales, su Thrall está aquí. Se ha fusionado con la roca de este lugar, en corazón y alma.' WHERE `ID`=52423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='육체의 소유자치고는 영혼이 강하더군. 아주 마음에 들어... 그를 포기하고 싶지 않아.', `FemaleText_loc4`='作为血肉凡人，他的灵魂十分强大。他令我惊奇……我不想放弃他。', `FemaleText_loc5`='身為凡人，他的精神無比堅強。他讓我感到不可思議...我不願失去他。', `FemaleText_loc7`='Su espíritu es fuerte para una criatura de carne mortal. Me fascina... y detesto tener que renunciar a él.' WHERE `ID`=52424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 멀리 심장이 울부짖는 소리가 미로 같은 세계의 틈을 헤치고 여기까지 울려퍼진다. 이건 사랑하는 자의 심장에서 나는 소리야... 이 위대한 테라제인 님은... 아직 사랑을 기억하고 있다...', `FemaleText_loc4`='但我能听到哭泣的心声，遥远地回响在两个世界间的无尽迷宫里。这是为爱人哭泣的心声……伟大的塞拉赞恩并没有忘记爱是什么……', `FemaleText_loc5`='但是，我聽到了遠方的心在呼喊，回音迴盪於諸界的迷宮之中。我聽到的，是呼喊愛人的心...而偉大的瑟拉贊恩並沒有忘記愛，是何物...', `FemaleText_loc7`='Sin embargo, oigo el grito de un corazón lejano, un eco a través de los laberintos entre los mundos. Es el grito de un corazón que ama lo que oigo... y la gran Therazane no ha olvidado lo que es amar...' WHERE `ID`=52425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희의 주술사는 저 아래 현무암 숲에 있다. 허나 명심해라. 그는 영원한 돌의 전당과 하나가 되었다.', `FemaleText_loc4`='你的救世萨满就在下面的玄武岩森林里。但他已经变成了这无尽岩石大厅的一部分。', `FemaleText_loc5`='你們世界的薩滿站在下方的黑石林。但注意─他已經和這些無盡的石廊合為一體了。', `FemaleText_loc7`='El chamán de su mundo se encuentra en las grutas de basalto de abajo. Pero dense prisa, ahora es uno con esas cámaras de piedra sin fin.' WHERE `ID`=52426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광의 불꽃이여!', `MaleText_loc4`='荣耀之焰！', `MaleText_loc5`='榮耀之火!', `MaleText_loc7`='¡Llamarada de gloria!' WHERE `ID`=52427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 누가 부르고 애원을 해도, 자리를 떠나려 하지 않을 것이야.', `FemaleText_loc4`='他也许不想离开，无论是谁在呼唤他。', `FemaleText_loc5`='他也許不願意離開，不管是誰的心在呼喚他。', `FemaleText_loc7`='Quizás no quiera marcharse, aunque su corazón le pida volver al hogar.' WHERE `ID`=52428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가서 그를 찾아라... 내가 허락하마.', `FemaleText_loc4`='带着我的祝福……去找他吧。', `FemaleText_loc5`='去找他吧...帶著我的祝福。', `FemaleText_loc7`='Vayan por él... con mi bendición.' WHERE `ID`=52429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 힘은 여러 모습으로 발현된다...', `MaleText_loc4`='主人的力量有多种形式……', `MaleText_loc5`='主人的力量可不只一種形態...', `MaleText_loc7`='El poder del maestro adquiere muchas formas...' WHERE `ID`=52430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 불의 땅이 포효하는 모습을!', `MaleText_loc4`='看吧，这是火焰之地的愤怒！', `MaleText_loc5`='看好了，火源之界的怒火!', `MaleText_loc7`='¡Contemplen la ira de las Tierras de Fuego!' WHERE `ID`=52431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 연구들... 이제 겨우 시작이거늘...', `MaleText_loc4`='我的研究……才刚刚开始……', `MaleText_loc5`='我的研究...還只是剛開始...', `MaleText_loc7`='Mis estudios... acababan de empezar...' WHERE `ID`=52432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 바위 어머니여.', `FemaleText_loc4`='感谢您，石母。', `FemaleText_loc5`='謝謝你，石母。', `FemaleText_loc7`='Gracias, Madre Pétrea.' WHERE `ID`=52433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르십시오. 고엘은 바로 아래 있을 겁니다.', `FemaleText_loc4`='快一点，朋友。古伊尔应该就在下方。', `FemaleText_loc5`='快點，朋友。高爾應該就在下面。', `FemaleText_loc7`='Rápido, amigo. Go''el debería estar debajo al suroeste.' WHERE `ID`=52434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전사들이여, 준비하십시오. 이제 적의 영토에 들어갑니다.', `FemaleText_loc4`='战士们，做好准备。我们要进入敌人的领地了。', `FemaleText_loc5`='準備好，戰士們。我們進入了敵人的領域了。', `FemaleText_loc7`='Preparaos, guerreros. Entramos en territorio enemigo.' WHERE `ID`=52436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하십시오. 이 숲에는 불의 하수인들이 우글거립니다.', `FemaleText_loc4`='注意。这片林地里充斥着火焰的仆从。', `FemaleText_loc5`='打起精神。這片樹林裡到處都是火焰的爪牙。', `FemaleText_loc7`='Prestad atención. Estos bosques están atestados de lugartenientes de fuego.' WHERE `ID`=52437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경계를 늦추지 마십시오. 여기서 기습을 당하면 목숨을 잃을 수밖에 없습니다.', `FemaleText_loc4`='全军警戒。如果遭遇偷袭，那就是生死立判了。', `FemaleText_loc5`='保持警戒，士兵們。如果受到伏擊，生死之間只是一瞬間的事情。', `FemaleText_loc7`='Atentas las tropas. Un ataque sorpresa significaría la diferencia entre la vida y la muerte.' WHERE `ID`=52438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 침략자들은 우리 땅을 그렇게 쉽게 점령할 수는 없다는 사실을 배워야 합니다. 제가 기꺼이 가르침을 주고 싶군요.', `FemaleText_loc4`='一定得让这些入侵者知道，我们的土地不是那么好侵占的。我很乐意给它们上这一课。', `FemaleText_loc5`='這些入侵者必須了解到我們的土地無法如此輕易被征服。而我非常樂意負責給他們教訓教訓。', `FemaleText_loc7`='Esos invasores deben aprender que no podrán quedarse con nuestras tierras fácilmente. Y yo misma estaré encantada de enseñarles la lección.' WHERE `ID`=52439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 침입자들이군! 해치워라. 먹어 버려!', `MaleText_loc4`='啊哈！闯入者！杀掉他们。吃掉他们！', `MaleText_loc5`='啊哈!不請自來的人!殺了他們，吃了他們!', `MaleText_loc7`='¡Ajá! ¡Los intrusos! Mátalos. ¡DEVÓRALOS!' WHERE `ID`=52440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 아파. 불의 군주님... 너무 아파...', `MaleText_loc4`='哦……真痛苦。炎魔之王……这真痛……', `MaleText_loc5`='噢...這痛楚。火焰之王...我好痛啊...', `MaleText_loc7`='Oooh... El dolor. Señor del Fuego... duele...' WHERE `ID`=52441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 모두 활기차 보이는군! 다들 준비가 됐나?', `MaleText_loc4`='好了，全队注意！大家都准备好了吗？', `MaleText_loc5`='好啦，士兵們。有精神點!都準備好了嗎?', `MaleText_loc7`='Está bien, tropas. ¡Rápido! ¿Estamos todos listos?' WHERE `ID`=52442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비됐습니다, 대장님.', `FemaleText_loc4`='随时待命，队长。', `FemaleText_loc5`='準備好了，隊長。', `FemaleText_loc7`='Listos para partir, capitán.' WHERE `ID`=52443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발구르기로 짓밟을 시간이군.', `MaleText_loc4`='该是战争践踏登场的时候了。', `MaleText_loc5`='開戰時刻到了。', `MaleText_loc7`='Hora de aplastar.' WHERE `ID`=52444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='은신 중이다.', `FemaleText_loc4`='早就迫不及待了。', `FemaleText_loc5`='潛行中。', `FemaleText_loc7`='Al acecho.' WHERE `ID`=52445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 어서 작전을 시작하게.', `FemaleText_loc4`='没问题，伙计。我们赶紧动手吧。', `FemaleText_loc5`='是啊老兄。咱們動手吧。', `FemaleText_loc7`='Sí, colega. Que empiece el eh''pectáculo.' WHERE `ID`=52446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 준비 완료! 변신 시간이다!', `MaleText_loc4`='好了，全队准备完毕！进攻！', `MaleText_loc5`='好了，所有系統就緒!變身時刻到了!', `MaleText_loc7`='¡Está bien, equipo, todos los sistemas están en marcha! ¡Hora de metamorfosearse!' WHERE `ID`=52447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원히 누워 있어라.', `MaleText_loc4`='现在，你去死吧！', `MaleText_loc5`='別爬起來。', `MaleText_loc7`='¡Ahora quédate muerto!' WHERE `ID`=52448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주님이 무척 기뻐하시겠는걸.', `MaleText_loc4`='炎魔之王会非常高兴的。', `MaleText_loc5`='炎魔知道會很高興。', `MaleText_loc7`='El Señor del Fuego estará más que complacido.' WHERE `ID`=52449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s|1이;가; |cFFFF6600|Hspell:100171|h[화염의 세계]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s开始施放|cFFFF6600|Hspell:100171|h[烈焰世界]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s開始施放|cFFFF6600|Hspell:100171|h[焚世烈焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_mage_worldinflames.blp:20|t¡%s comienza a lanzar |cFFFF6600|Hspell:100171|h[Mundo en llamas]|h|r!' WHERE `ID`=52450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가야, 밥 먹자!', `MaleText_loc4`='一文不值！', `MaleText_loc5`='待宰羔羊!', `MaleText_loc7`='¡Comida para perros!' WHERE `ID`=52451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 먹이 물어와!', `MaleText_loc4`='这是你的晚餐！', `MaleText_loc5`='去吃你們的晚餐!', `MaleText_loc7`='¡La cena está lista!' WHERE `ID`=52452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 불태워 주마.', `MaleText_loc4`='燃烧吧！', `MaleText_loc5`='該燃燒了你。', `MaleText_loc7`='¡Ahora ardan!' WHERE `ID`=52453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼로베! 안 돼, 안 돼! 이 짐승만도 못한 놈들아, 세상에 어떻게?', `MaleText_loc4`='裂肢——不。不！你们这些冷酷的野兽，你们怎么敢？！', `MaleText_loc5`='裂軀─不...不!你們這些糟糕的小野獸，你們怎麼可以這樣!', `MaleText_loc7`='Desmembrador... no. ¡NO! Oh, malditas alimañas, ¿cómo han PODIDO?' WHERE `ID`=52454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이 악마 같은 놈들! 왜? 이렇게 고귀한 동물을 도대체 왜!', `MaleText_loc4`='你们这些凶手！为什么你们要杀掉这么一只高贵的动物！', `MaleText_loc5`='你們這些兇手!為什麼?為什麼要殺死這麼高貴的動物?!', `MaleText_loc7`='¡Asesinos! ¡Por qué! ¡Por qué matarían a un animal tan noble!' WHERE `ID`=52455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 나도 냄새가 나, 칼로베. 외부인이 불의 군주님의 땅에 침입했어. 흔적을 쫓아라. 놈들을 찾아서, 벌을 내리는 거야!', `MaleText_loc4`='对，裂肢，我也闻到他们了。外来者侵入了炎魔之王的领地。跟着足迹，把他们揪出来。我会让他们受罚！', `MaleText_loc5`='是的，裂軀，我也聞到他們的味道了。外來者在炎魔的地盤上。追蹤他們，找到他們，讓我可以施以懲罰!', `MaleText_loc7`='Sí, yo también los huelo Desmembrador. Los extraños invaden el suelo sagrado del Señor del Fuego. Busca el rastro. Encuéntralos por mí, ¡para que pueda castigarlos!' WHERE `ID`=52456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불속에서 뒹굴어라, 침입자들아!', `MaleText_loc4`='在烈焰中挣扎吧，闯入者！', `MaleText_loc5`='在火焰中扭曲吧，闖入者!', `MaleText_loc7`='¡Retuérzanse en las llamas, intrusos!' WHERE `ID`=52457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 숨통을 노려!', `MaleText_loc4`='咬他的喉咙！', `MaleText_loc5`='攻擊要害!', `MaleText_loc7`='¡A la yugular!' WHERE `ID`=52458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 치료를 하겠네. 특별히 변신할 필요는 없어.', `FemaleText_loc4`='我来奶吧，兄弟。我可是有特殊形态的哦。', `FemaleText_loc5`='我會負責治療，老兄。我沒有特殊的形態。', `FemaleText_loc7`='Eh''taré curando colega. No tengo una forma eh''pecial.' WHERE `ID`=52459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공기 중에 마법의 기운이 떠도는 게 느껴지나요, $c님?', `FemaleText_loc4`='感觉到空气中的魔法能量了吗，$c？', `FemaleText_loc5`='你感覺到迴盪在空中的魔法嗎，$c?', `FemaleText_loc7`='¿Sientes la magia del ambiente, $c?' WHERE `ID`=52460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 제자리에! 출발할 시간이다.', `MaleText_loc4`='列队！我们准备好出发了。', `MaleText_loc5`='各就各位!我們準備要動手啦。', `MaleText_loc7`='¡A sus posiciones! Estamos listos para la acción.' WHERE `ID`=52461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할로윈 축제 기간에는 강력한 마법이 주변을 떠돈다네.', `FemaleText_loc4`='在这个季节，空气中弥漫着强大的法力，$c。', `FemaleText_loc5`='在這個季節中，強大的魔法充滿了整個空氣，$c。', `FemaleText_loc7`='Esta temporada hay una magia poderosa en el ambiente, $c.' WHERE `ID`=52462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드를 공격할 준비가 됐습니다!', `MaleText_loc4`='我准备好了，我们去轰炸暴风城吧！', `MaleText_loc5`='我準備好攻擊暴風城了!', `MaleText_loc7`='¡Estoy listo para atacar Ventormenta!', `FemaleText_loc1`='스톰윈드를 공격할 준비가 됐어요!', `FemaleText_loc4`='我准备好了，我们去轰炸暴风城吧！', `FemaleText_loc5`='我準備好攻擊暴風城了!', `FemaleText_loc7`='¡Estoy lista para atacar Ventormenta!' WHERE `ID`=52463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드 제군, 모두 수고했다! 이 지역도 안전해졌으니 이제 기지로 돌아가자.', `MaleText_loc4`='干得好，德鲁伊们！这个地方看起来很安全。我们回营地去吧。', `MaleText_loc5`='做得好，德魯伊們。這個地區看起來安全了。我們回去基地吧。', `MaleText_loc7`='¡Buen trabajo, druidas! Esta zona parece segura. Volvamos a la base.' WHERE `ID`=52464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 형태로 변신 준비! 3...', `MaleText_loc4`='准备进入飞行形态，倒数3秒……', `MaleText_loc5`='即將轉變為飛行形態: 3...', `MaleText_loc7`='Adoptad la forma de vuelo en 3...' WHERE `ID`=52465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2...', `MaleText_loc4`='2...', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=52466;
