UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍까마귀, 변신!', `MaleText_loc4`='风暴乌鸦，出发！', `MaleText_loc5`='上啊，風暴烏鴉!', `MaleText_loc7`='Cuervo de tormenta, ¡ve!' WHERE `ID`=52468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 잘했다! 잠시 휴식을 취하고 다시 내게 보고하라.', `MaleText_loc4`='干得不错，各位！休息一下，然后立刻回去复命。', `MaleText_loc5`='做得好啊，大家!休息一下，然後進行回報。', `MaleText_loc7`='¡Buen trabajo, equipo! Recuperad el aliento y volved a informar inmediatamente.' WHERE `ID`=52469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불. 내 사랑이 불이 됐습니다. 설마 했는데... 그를 찾으려면 라그나로스의 영역으로 들어가야 합니다.', `FemaleText_loc4`='火焰。我的爱人变成了火焰。我害怕的事发生了。我们必须进入拉格纳罗斯的火焰领地寻找他。', `FemaleText_loc5`='火焰。我的愛人已經化為火焰，我一直擔心這點。我們必須進入拉格納羅斯的界域才能再次找到他。', `FemaleText_loc7`='Fuego. Mi amor se ha convertido en fuego. Lo temía. Para encontrarle debemos entrar en los dominios ardientes de Ragnaros.' WHERE `ID`=52470;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음 단단히 먹으세요. 그대도 알다시피, 불의 땅엔 우릴 도울 이가 없으니까요.', `FemaleText_loc4`='保持坚强，朋友。你我心中都清楚……在火焰之地，我们将孤立无援。', `FemaleText_loc5`='堅強，朋友。你我都知道─我們在火源之界是不會有任何的援手的。', `FemaleText_loc7`='Sé fuerte. Sabes tan bien como yo que no recibiremos ayuda alguna en las Tierras de Fuego.' WHERE `ID`=52471;
