UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 블러드 엘프 경비탑을 점령했습니다!', `MaleText_loc4`='联盟夺取了血精灵塔！', `MaleText_loc5`='聯盟奪取了血精靈哨塔!', `MaleText_loc7`='¡La Alianza ha tomado la Torre de los Elfos de Sangre!' WHERE `ID`=52502;
