UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 블러드 엘프 경비탑을 방어했습니다!', `MaleText_loc4`='$n守住了血精灵塔！', `MaleText_loc5`='$n守住了血精靈哨塔!', `MaleText_loc7`='¡$n ha defendido la Torre de los Elfos de Sangre!' WHERE `ID`=52504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 블러드 엘프 경비탑을 방어했습니다!', `MaleText_loc4`='$n守住了血精灵塔！', `MaleText_loc5`='$n守住了血精靈哨塔!', `MaleText_loc7`='¡$n ha defendido la Torre de los Elfos de Sangre!' WHERE `ID`=52505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 블러드 엘프 경비탑을 공격했습니다! 방어하지 못하면 1분 안에 얼라이언스에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了血精灵塔！如果不赶快采取行动的话，联盟会在1分钟内控制它！', `MaleText_loc5`='$n攻佔了血精靈哨塔!如果沒有其他人採取行動的話，聯盟將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama la Torre de los Elfos de Sangre! ¡Si nadie acepta el desafío, la Alianza las tomará en 1 minuto!' WHERE `ID`=52506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 블러드 엘프 경비탑을 공격했습니다! 방어하지 못하면 1분 안에 호드에 넘어갈 것입니다!', `MaleText_loc4`='$n突袭了血精灵塔！如果不赶快采取行动的话，部落会在1分钟内控制它！', `MaleText_loc5`='$n攻佔了血精靈哨塔!如果沒有其他人採取行動的話，部落將在1分鐘內控制它!', `MaleText_loc7`='¡$n reclama la Torre de los Elfos de Sangre! ¡Si nadie acepta el desafío, la Horda la tomará en 1 minuto!' WHERE `ID`=52507;
