UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 형태로! 변신!', `MaleText_loc4`='作战形态，出发！', `MaleText_loc5`='戰鬥形態，上!', `MaleText_loc7`='¡Formaciones de batalla, ya!' WHERE `ID`=52509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅에서 사라져라, 침략자여!', `FemaleText_loc4`='滚出这片土地，入侵者！', `FemaleText_loc5`='滾出這片土地，入侵者!', `FemaleText_loc7`='¡Fuera de estas tierras, invasor!' WHERE `ID`=52511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 순간을 위해 발톱을 갈았다.', `FemaleText_loc4`='我磨利了自己的爪子，等的就是这一刻！', `FemaleText_loc5`='我的爪子為了這一刻已經磨得很利了。', `FemaleText_loc7`='He afilado mis garras justo para este momento.' WHERE `ID`=52512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 이빨이 커다랗다고? 정말 고맙구나.', `FemaleText_loc4`='我的獠牙很大吧？这还多亏了你。', `FemaleText_loc5`='我的牙齒很大?噢，謝了。', `FemaleText_loc7`='¿Qué dientes más grandes tengo? Vaya, gracias.' WHERE `ID`=52513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 달빛의 분노를 맛봐라!', `MaleText_loc4`='尝尝我的月光射线吧！', `MaleText_loc5`='嘗嘗我月光束的怒火吧!', `MaleText_loc7`='¡Prueba la furia de mi rayo de luna!' WHERE `ID`=52514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이다! 불! 불!', `MaleText_loc4`='火！火！火！', `MaleText_loc5`='開火!開火!開火!', `MaleText_loc7`='¡Fuego! ¡Fuego! ¡Fuego!' WHERE `ID`=52515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나무들도 네 존재에 저항한다!', `MaleText_loc4`='每一棵树都抗拒你的到来！', `MaleText_loc5`='連樹都厭惡你的到來!', `MaleText_loc7`='¡Los mismos árboles repelen su presencia!' WHERE `ID`=52516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사악한 존재여, 네 불구덩이로 돌아가라!', `FemaleText_loc4`='滚回烈焰中去吧，混蛋。', `FemaleText_loc5`='滾回你來的火焰裡，怪東西。', `FemaleText_loc7`='Regresa al fuego del que hayas salido, maldito.' WHERE `ID`=52517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 여기서 무슨 짓을 하든 상관없다, 파괴자여. 네가 죽은 뒤에 이 땅은 다시 회복할 테니.', `FemaleText_loc4`='你的一切努力都是徒劳的，破坏者。等干掉你之后，我们会再次治愈它。', `FemaleText_loc5`='你做什麼都沒用的，破壞者。大地會在你死去之後自己恢復的。', `FemaleText_loc7`='No impoh''ta lo que hagas aquí, saqueador. La tierra sanará deh''pués de tu mueh''te.' WHERE `ID`=52518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어라! 불에 다시 먹혀 버려라!', `FemaleText_loc4`='去死吧！在烈焰中再死一次吧。', `FemaleText_loc5`='死吧!讓火焰再次吞噬你!', `FemaleText_loc7`='¡Muere! Que el fuego te consuma de nuevo.' WHERE `ID`=52519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 포효로 놈들을 공포에 떨게 하겠다!', `MaleText_loc4`='我要用怒吼吓跑他们！', `MaleText_loc5`='我會用吼聲嚇跑他們!', `MaleText_loc7`='¡Los ahuyentaré con mi rugido!' WHERE `ID`=52520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌진!', `MaleText_loc4`='冲锋！', `MaleText_loc5`='衝啊!', `MaleText_loc7`='¡Cargad!' WHERE `ID`=52521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 발견!', `MaleText_loc4`='瞄准敌人！', `MaleText_loc5`='發現敵人!', `MaleText_loc7`='¡Enemigo a la vista!' WHERE `ID`=52522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 도망가지 않았다면, 이미 늦었다!', `MaleText_loc4`='你再不跑的话，可就来不及了！', `MaleText_loc5`='如果你還沒逃跑，現在已經太遲了!', `MaleText_loc7`='¡Si no habéis huido todavía, ya es demasiado tarde!' WHERE `ID`=52523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드루이드 팀, 공격!', `MaleText_loc4`='德鲁伊小队，进攻！', `MaleText_loc5`='德魯伊小隊，攻擊!', `MaleText_loc7`='¡Equipo druida, atacad!' WHERE `ID`=52524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;, 전투에 참여하러 오셨습니까?', `MaleText_loc4`='你是来参战的吗，$c？', `MaleText_loc5`='你來加入戰鬥的嗎，$c?', `MaleText_loc7`='¿Has venido a unirte a la lucha, $c?', `FemaleText_loc1`='$c|1이여;여;, 전투에 참여하러 오셨나요?', `FemaleText_loc4`='你是来参战的吗，$c？', `FemaleText_loc5`='你來加入戰鬥的嗎，$c?', `FemaleText_loc7`='¿Has venido a unirte a la lucha, $c?' WHERE `ID`=52525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... $n, 다시 만나 반갑네. 이 땅에 엄청난 위협이 찾아와서, 나도 전투에 참여하러 왔네. 얼핏 봐도 자네가 많이 성장했음을 잘 알겠군. 좋아. 자넨 나와 부족 모두의 자랑이네.', `FemaleText_loc4`='啊，$n。真高兴，我们又见面了。这儿危机重重，所以我也加入了战斗。我发现你也成长了不少。很好。我和你的族人都为你感到自豪。', `FemaleText_loc5`='啊，$n。很高興能在這裡又看到你。這片大地受到的威脅很嚴重，我來這裡加入戰鬥。看得出來你自己成長了不少。你讓我，還有你整個部族都感到驕傲。', `FemaleText_loc7`='Ahhh, $n. Me alegra veh''te de nuevo. La amenaza que acecha eh''tas tierras es grave y he venido a unirme a la lucha. Veo que has aprendido mucho por tu cuenta. Bien. Yo y toda la tribu eh''tamos orgullosos.' WHERE `ID`=52526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 놀드랏실의 가지를 건드리자 격렬하게 반응합니다!', `MaleText_loc4`='$n的触摸令诺达希尔的分枝产生了强烈反应！', `MaleText_loc5`='諾達希爾木枝對於$n的碰觸產生了劇烈的反應!', `MaleText_loc7`='¡Cuando la toca $n, la rama de Nordrassil reacciona de forma violenta!', `FemaleText_loc1`='$n|1이;가; 놀드랏실의 가지를 건드리자 격렬하게 반응합니다!', `FemaleText_loc4`='$n的触摸令诺达希尔的分枝产生了强烈反应！', `FemaleText_loc5`='諾達希爾木枝對於$n的碰觸產生了劇烈的反應!', `FemaleText_loc7`='¡Cuando la toca $n, la rama de Nordrassil reacciona de forma violenta!' WHERE `ID`=52527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 여기서 널 만나다니 놀랍군. 난 언제나 네가 내 가장 영리한 제자라고 생각했었다. 너와 함께 싸우게 되어 영광이다, 친구.', `FemaleText_loc4`='我就知道会在这儿见到你，$n。我一直觉得你是我最出色的学生。很荣幸能和你并肩战斗，朋友。', `FemaleText_loc5`='$n，我一點都不訝異會在這裡看到你。我一直認為你是我最聰明的弟子。我很榮幸能跟你並肩作戰，朋友。', `FemaleText_loc7`='$n, no me sorprende verte aquí. Siempre pensé que eras mi estudiante más brillante. Me siento honrada de luchar a tu lado.' WHERE `ID`=52528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 좋아 보이는군요. 긴급 소집 명령을 받자마자 집을 떠나 여기 전투에 참여하러 왔습니다.$B$B지난 번에 만난 이후로 그대도 많이 성장했음을 잘 알겠습니다. 한때 그대를 가르쳤다는 사실이 영광이군요. 그대는 얼라이언스의 진정한 영웅입니다.', `MaleText_loc4`='$n，你看起来不错。获悉征召令后我背井离乡，来这里加入战斗。$B$B分别后你长进许多。能教导你我感到十分荣幸。你是联盟真正的英雄。', `MaleText_loc5`='$n，你看起來還不錯。我聽到召集令了，所以我離開家來這裡加入戰鬥。$B$B看得出你自從上次碰面後又有所成長。我很榮幸曾教導過你。你是聯盟真正的英雄。', `MaleText_loc7`='$n, tienes buen aspecto. Oí el llamamiento a las armas, por eso dejé nuestro hogar y vine a unirme a la lucha.$B$BVeo que has aprendido mucho por tu cuenta desde la última vez que nos vimos. Me siento honrado de haberte instruido. Eres un verdadero héroe de la Alianza.' WHERE `ID`=52529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n. 긴급 소집 명령을 받아 잠시 전투 형태로 변신했소. 내가 가르칠 수 있는 것은 모두 가르쳐 줬으니, 이제 마지막으로 한 가지만 알려주겠소. 용감하게 싸우시오, 젊은이. 호드의 명예를 위해.', `MaleText_loc4`='你好，$n。我听说了动员令，所以暂时进入了战斗形态。我会的都已经教给你了，现在我要给上最后一课。作为一名光荣的部落战士，勇敢地去战斗吧，年轻人。', `MaleText_loc5`='哈囉，$n。我聽到了召集令，所以我暫時轉換成我的戰鬥模式。你已經學會所有我能教的東西了，所以我留給你最後一個課程。以榮耀的部落成員這個身分來勇敢地進行戰鬥吧，年輕人。', `MaleText_loc7`='Hola, $n. He oído el llamamiento a las armas así que, temporalmente, he adoptado mi forma de combate. Ya sabes todo lo que te puedo enseñar, aunque te daré una última lección. Lucha con valor, joven, como honorable miembro de la Horda.' WHERE `ID`=52530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황혼의 저주가 고엘을 다른 정령으로 바꾸었군요! 사라지기 직전, 물의 위상이 되었어요. 서둘러 그를 찾아야 합니다...', `FemaleText_loc4`='暮光诅咒正在将古伊尔转换到另一种元素形态！在消失前，他进入了水元素位面。我们必须赶过去……', `FemaleText_loc5`='暮光詛咒讓高爾在元素之界和現實中轉換!在他消失前，他召喚了水之守護。我們的速度必須快點...', `FemaleText_loc7`='La maldición Crepuscular hace que Go''el sufra diferentes estados elementales. Antes de desaparecer tomó el aspecto del agua. Debemos llegar a él...' WHERE `ID`=52531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통받는 수호정령을 태우는 불이 사그라졌습니다!', `MaleText_loc4`='受折磨的保护者身上一直燃烧着的火焰熄灭了！', `MaleText_loc5`='受折磨的保衛者身上的火焰熄滅了!', `MaleText_loc7`='¡Las llamas que consumen al protector atormentado se extinguen!', `FemaleText_loc1`='고통받는 수호정령을 태우는 불이 사그라졌습니다!', `FemaleText_loc4`='受折磨的保护者身上一直燃烧着的火焰熄灭了！', `FemaleText_loc5`='受折磨的保衛者身上的火焰熄滅了!', `FemaleText_loc7`='¡Las llamas que consumen al protector atormentado se extinguen!' WHERE `ID`=52532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설령 이 세상 끝까지 쫓아가야 한대도... 전 결코 그를 포기하지 않겠어요.', `FemaleText_loc4`='无论要走多远，我也绝不放弃他！', `FemaleText_loc5`='不管要付出多少代價 - 我絕不放棄他。', `FemaleText_loc7`='No importa lo lejos que tenga que ir... Me niego a renunciar a él.' WHERE `ID`=52533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만... 멈춰...', `MaleText_loc4`='够了……停下……', `MaleText_loc5`='夠了...停止...', `MaleText_loc7`='Basta... Basta...' WHERE `ID`=52534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 심연의 구렁으로 여행할 준비가 되었습니다.', `MaleText_loc4`='阿格娜，我准备好前往深渊之喉了。', `MaleText_loc5`='阿格拉，我準備好前往深淵之喉了。', `MaleText_loc7`='Aggra, estoy listo para viajar a la Fauce Abisal.', `FemaleText_loc1`='아그라, 심연의 구렁으로 여행할 준비가 되었습니다.', `FemaleText_loc4`='阿格娜，我准备好前往深渊之喉了。', `FemaleText_loc5`='阿格拉，我準備好前往深淵之喉了。', `FemaleText_loc7`='Aggra, estoy lista para viajar a la Fauce Abisal.' WHERE `ID`=52535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불은 이제 고통스럽지 않지만, 내 힘이 고갈되었다.', `MaleText_loc4`='烈焰不再折磨我了。但我也消耗殆尽了。', `MaleText_loc5`='火焰已不再折磨我。但我已油盡燈枯。', `MaleText_loc7`='El fuego ya no me atormenta. Pero estoy consumido.' WHERE `ID`=52536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 오직 단 한 번만 우리를 그곳으로 순간이동시킬 수 있습니다. 준비 단단히 하세요. 고엘이 바다 밑바닥에서 우리를 기다리고 있습니다...', `FemaleText_loc4`='我的力量只够传送一次。所以你一定要做好充分的准备。古伊尔在海底等着我们……', `FemaleText_loc5`='我只能傳送我們一次。確認你已經準備好了。高爾在海底等著我們。', `FemaleText_loc7`='Solo puedo teletransportarnos una vez. Asegúrate de que quieres partir. Go''el nos espera en el fondo del océano...' WHERE `ID`=52537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이들은 할로윈 축제를 무척 좋아한답니다. 어떤 아이는 사탕을 얻으러 나갔고, 어떤 아이는 뒤에 남았고, 여기 있는 아이들은 작은 사업을 하나 벌이기로 했답니다.$b$b목표는 최대한 많은 사탕을 모으는 거예요. 그리고 아이들은 선물을 좀 주면 다른 이가 그 힘든 일을 대신해주리라 생각하지 뭐예요. 처음에 이 계획을 들었을 땐 깔깔 웃었답니다, $c님. 하지만 수많은 여행자가 아이들의 물건을 받고 사탕을 구해다 주는 걸 보니, 이젠 좀 걱정이 돼요.$b$b사탕이 너무 많이 모였어요. 아이들이 저 많은 사탕을 먹고 어찌 잠들까 걱정이랍니다.', `FemaleText_loc4`='孩子们都喜欢这个节日。有些孩子已经出去要糖果了，有些却只能留在这里。还有些孩子，比如你眼前这些，则想跟你们做个小小的交易。$b$b他们的目的是收集尽可能多的糖果，而他们想到的报酬就是送糖果给那些帮他们奔波的人。当我第一次他们说起这个打算时，都有点忍俊不禁，$c。可当我看到有那么多冒险者都愿意拿糖果来交换他们的小礼品时，我又开始担心了。$b$b他们拿到的糖果太多了。我担心孩子们从此再也睡不着觉了。', `FemaleText_loc5`='孩子們很愛這個節日。有些孩子會去討糖果，有些不想去，而像這些孩子則是打算做點小生意。$b$b他們的目標是盡量收集糖果，而他們認為最好的辦法就是提供努力的人糖果吃。我一開始聽到他們的計畫時笑了出來，$c。但是我現在看到許多冒險者用糖果跟他們交換他們的貨物，我開始擔心了。$b$b太多糖了。我想他們大概再也沒辦法睡著了。', `FemaleText_loc7`='A los niños les encanta esta fiesta. Algunos han salido para jugar a truco o trato, otros se han quedado atrás y otros, como estos, han decidido montar un pequeño negocio.$b$bSu objetivo es reunir todos los caramelos que puedan y han pensado que la mejor forma es ofrecer algo a cambio del duro trabajo de los demás. Cuando me contaron su plan no pude evitar reírme, $c. Pero ahora que veo cuántos aventureros están dándoles sus caramelos a cambio de mercancía, estoy preocupada.$b$bEs mucho azúcar. No creo que los niños puedan volver a dormirse nunca.' WHERE `ID`=52538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대... 놀드랏실의 친구여... 그나마 남은 내 힘을 가져가... 화염과 맞서라...', `MaleText_loc4`='你，诺达希尔之友！带走我残余的力量，击退烈焰的进攻！', `MaleText_loc5`='諾達希爾的朋友啊!拿著我僅存的力量並驅逐火焰吧!', `MaleText_loc7`='¡Tú, amigo de Nordrassil! ¡Toma lo que queda de mis fuerzas y lucha contra las llamas!' WHERE `ID`=52539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 나무의 영혼이 그대를 보호하길...', `MaleText_loc4`='愿巨树之灵庇护着你……', `MaleText_loc5`='願神木的靈魂能保護你...', `MaleText_loc7`='Que el espíritu del Gran Árbol te guarde…' WHERE `ID`=52540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 힘을 모두 드리겠습니다. 위대한 나무의 가지가 화염의 심연에서 타오르는 불길을 막아줄 것입니다.', `MaleText_loc4`='我会将我全部的力量传给你。愿世界之树的浓荫庇佑你不受这地狱烈焰的炙烤。', `MaleText_loc5`='我會盡我所能遞給你力量。希望巨偉之樹的枝葉能為你遮擋這個可憎地獄的烈焰。', `MaleText_loc7`='Te daré todo el poder que pueda. Que las ramas del Gran Árbol te cobijen de las llamas en este abismo infernal.' WHERE `ID`=52541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소중한 놀드랏실이여, 미안하구나. 내가 실패하고 말았다...', `MaleText_loc4`='对不起，亲爱的诺达希尔。我失败了……', `MaleText_loc5`='對不起，親愛的諾達希爾。我失敗了...', `MaleText_loc7`='Lo siento, querido Nordrassil. He fallado...' WHERE `ID`=52542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주인이 죽는 모습을 보더니 쓰러집니다!', `MaleText_loc4`='%s眼见主人死去，随即瘫软在地！', `MaleText_loc5`='%s看到他的主人死去，也隨即崩潰了!', `MaleText_loc7`='¡%s se derrumba al ver morir a su maestro!' WHERE `ID`=52543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할로윈 축제는 우리의 새로운 친구들과 함께 만들어갈 미래를 축하하는 자리다.', `MaleText_loc4`='我们热情欢迎新的朋友，与他们一起展望并肩打造出的未来。', `MaleText_loc5`='讓我們為新朋友，和我們將共同開創的未來而慶祝。', `MaleText_loc7`='Es la hora de brindar por las nuevas amistades y por el futuro que forjaremos juntos.' WHERE `ID`=52544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물이 요동치고 있습니다... 무슨 일이 벌어진 거죠?', `FemaleText_loc4`='这里的水域受到了干扰……发生了什么事？', `FemaleText_loc5`='這裡的水受到了干擾...發生了什麼事?', `FemaleText_loc7`='Aquí el agua está turbia... ¿Qué sucede?' WHERE `ID`=52545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 와라, 여행자여. 운명의 파도에 휩쓸려 저 위 밝은 세상에서 여기까지 왔구나. 너희가 뭘 찾는지 안다. 바로 저 앞에 있지...', `MaleText_loc4`='你好，旅行者。命运之潮指引你们从遥远明亮的世界而来。我知道你们在寻找什么——而他就在你们的面前……', `MaleText_loc5`='你好，旅行者。命運之潮將你從遙遠的表面世界帶來這裡。我知道你在尋找什麼─遠在天邊近在眼前...', `MaleText_loc7`='Saludos, viajeros. La marea del destino los ha traído lejos del luminoso mundo de la superficie. Sé lo que buscan... y está ante ustedes…' WHERE `ID`=52546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 세계에서 온 주술사는 욕망의 소용돌이가 되었다. 보아라. 그의 심장이 주변의 모든 것을 빨아들이는 것을. 조심하지 않으면, 너희도 빨려 들어갈 것이다.', `MaleText_loc4`='你的救世萨满已变成了渴求与欲望的漩涡。看到了吗？他的心正在吞噬一切。如果踏入其中，就连你也会被一同吞没。', `MaleText_loc5`='你們世界的薩滿已成為欲望漩渦的中心。看到他的心如何在吞噬一切鄰近的事物嗎?小心前進，旅行者，以免自己也被吞噬。', `MaleText_loc7`='Su chamán del mundo se ha convertido en un vórtice de ansia y deseo. ¿Ven cómo su corazón devora todo a su alrededor? Ten cuidado, viajero, o tú también serás consumido.' WHERE `ID`=52547;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='딱 맞게 도착했군요! 고엘의 영혼이 너무 불안정해져서, 빨리 손을 쓰지 않으면 스스로 붕괴할지도 모릅니다.', `FemaleText_loc4`='我们来得正好！古伊尔的灵魂变得不稳定了，如果不快点行动，他的灵魂可能会崩溃。', `FemaleText_loc5`='我們來得剛好!高爾的精神變得極不穩定，如果我們不快點他便會自我毀滅。', `FemaleText_loc7`='¡Hemos llegado justo a tiempo! El espíritu de Go''el es inestable, podría colapsarse si no actuamos rápidamente.' WHERE `ID`=52548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 알던 주술사는 이미 심연으로 사라졌다. 이제 그의 존재 이유는 닥치는 대로 집어삼키는 것. 자신도 몰랐던 욕망의 회오리 속에서 고통받으며 말이지.', `MaleText_loc4`='你的救世萨满已经迷失在了暗流的深渊中。他只为吞噬而存在，被他内心汹涌的渴望所折磨，自己却浑然不知。', `MaleText_loc5`='你們世界的薩滿已經跌落於黑暗的深淵。他存在的目的只為了吞噬─被他所渴望的生活所折磨─但渾然不覺。', `MaleText_loc7`='Su chamán del mundo ya se ha perdido en los propósitos oscuros. Ahora solo existe para consumir, torturado por las corrientes de la vida que deseó pero nunca tuvo.' WHERE `ID`=52549;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그를 구하겠습니다. 기필코.', `FemaleText_loc4`='我们一定会救出他，海卓里斯！一定会。', `FemaleText_loc5`='我們會救他的，$n。一定要。', `FemaleText_loc7`='¡Lo salvaremos! ¡Debemos hacerlo!' WHERE `ID`=52550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이미 긴 시간을 지체했다. 어서 이 라그나로스의 하수인들과 전투를 치러야 한다.', `MaleText_loc4`='我们已经耽搁得够久了。现在就对这个拉格纳罗斯的仆人动手吧。', `MaleText_loc5`='我們耽擱夠久了。讓我們立刻跟拉格納羅斯的這個僕人進行戰鬥吧。', `MaleText_loc7`='Ya nos hemos retrasado demasiado. Nos enfrentaremos en batalla a ese sirviente de Ragnaros inmediatamente.' WHERE `ID`=52551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 기다리지 않겠습니다. 저는 싸울 준비가 됐습니다.', `MaleText_loc4`='别再磨蹭了，我已经做好战斗的准备了。', `MaleText_loc5`='不用再等了，我準備好進行戰鬥了。', `MaleText_loc7`='No esperes más, estoy listo para luchar.', `FemaleText_loc1`='더는 기다리지 않겠어요. 저는 싸울 준비가 끝났어요.', `FemaleText_loc4`='别再磨蹭了，我已经做好战斗的准备了。', `FemaleText_loc5`='不用再等了，我準備好進行戰鬥了。', `FemaleText_loc7`='No esperes más, estoy lista para luchar.' WHERE `ID`=52552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용해된 균열이 놀드랏실의 가지에 나타납니다! 무언가 강력한 것이 지팡이에서 생겨나고 있습니다!', `MaleText_loc4`='诺达希尔的分枝上出现了裂痕！法杖中涌出了某种强大的力量！', `MaleText_loc5`='諾達希爾木枝出現了燒熔的裂縫!某種強大的東西正在從法杖內湧出!', `MaleText_loc7`='¡Aparecen grietas incandescentes en la rama de Nordrassil! ¡Algo poderoso está surgiendo del bastón!', `FemaleText_loc1`='용해된 균열이 놀드랏실의 가지에 나타납니다! 무언가 강력한 것이 지팡이에서 생겨나고 있습니다!', `FemaleText_loc4`='诺达希尔的分枝上出现了裂痕！法杖中涌出了某种强大的力量！', `FemaleText_loc5`='諾達希爾木枝出現了燒熔的裂縫!某種強大的東西正在從法杖內湧出!', `FemaleText_loc7`='¡Aparecen grietas incandescentes en la rama de Nordrassil! ¡Algo poderoso está surgiendo del bastón!' WHERE `ID`=52553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기 나는 %s의 몸이 깜박거리며 타오르기 시작합니다!', `MaleText_loc4`='%s灼热的身体开始发光并燃烧！', `MaleText_loc5`='%s悶燒的身體開始晃動和燃燒!', `MaleText_loc7`='¡El cuerpo ardiente de %s empieza a titilar y entra en combustión!', `FemaleText_loc1`='연기 나는 %s의 몸이 깜박거리며 타오르기 시작합니다!', `FemaleText_loc4`='%s灼热的身体开始发光并燃烧！', `FemaleText_loc5`='%s悶燒的身體開始晃動和燃燒!', `FemaleText_loc7`='¡El cuerpo ardiente de %s empieza a titilar y entra en combustión!' WHERE `ID`=52554;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 그 재를 얼굴에 발라 새로운 적에게 고한다. 우리를 괴물이라 매도하고 두려워하는 자들에게 선포한다.', `FemaleText_loc4`='我们将燃烧后的灰烬抹在脸上，告诉那些新的敌人——那些畏惧我们，视我们为怪物的人。', `FemaleText_loc5`='我們將灰燼抹在臉上，向新的敵人傳遞訊息:向那些害怕我們、痛斥我們為怪物的人...', `FemaleText_loc7`='Nos pintamos el rostro con la ceniza para enviar un mensaje a los nuevos enemigos, aquellos que nos temen y nos desprecian como si fuéramos monstruos.' WHERE `ID`=52555;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 고향이 잿더미로 변하는 것을 보았다.', `FemaleText_loc4`='我们亲眼看到自己的家园被夷平。', `FemaleText_loc5`='我們看著自己的家園被夷為平地。', `FemaleText_loc7`='Vimos cómo reducían nuestros hogares a escombros.' WHERE `ID`=52556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 존재 가치를 부정하는 자들은 들어라.', `FemaleText_loc4`='那些认为我们不该存在于世上的人……', `FemaleText_loc5`='和質疑我們存在價值的人宣示...', `FemaleText_loc7`='A los que cuestionen nuestro lugar en este mundo...' WHERE `ID`=52557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니고말고... 우리는 그보다 훨씬 무서운 존재다...', `FemaleText_loc4`='不是！我们是一股更加恐怖的力量……', `FemaleText_loc5`='不...我們的戰力更加可怕...', `FemaleText_loc7`='No... somos una fuerza aún más aterradora...' WHERE `ID`=52558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 심원의 영지로 여행할 준비가 되었습니다.', `MaleText_loc4`='阿格娜，我准备好前往深岩之洲了。', `MaleText_loc5`='阿格拉，我準備好前往地深之源了。', `MaleText_loc7`='Aggra, estoy listo para viajar a Infralar.', `FemaleText_loc1`='아그라, 심원의 영지로 여행할 준비가 되었습니다.', `FemaleText_loc4`='阿格娜，我准备好前往深岩之洲了。', `FemaleText_loc5`='阿格拉，我準備好前往地深之源了。', `FemaleText_loc7`='Aggra, estoy lista para viajar a Infralar.' WHERE `ID`=52559;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈앞에서 가족이 목숨을 잃는 것을 보며 비통함에 울부짖었다.', `FemaleText_loc4`='亲人惨遭屠戮，而我们却只能悲愤地哭嚎。', `FemaleText_loc5`='看著親人在眼前被殺，我們因此而悲嚎。', `FemaleText_loc7`='Gritamos de agonía mientras masacraban a nuestras familias ante nosotros.' WHERE `ID`=52560;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바위 어머니의 손아귀를 되도록 빨리 벗어나는 게 좋을 겁니다. 전 그녀를 믿지 않아요.', `FemaleText_loc4`='我们越早摆脱石母越好。我不相信她。', `FemaleText_loc5`='我們能越早離開石母越好。我不信任她。', `FemaleText_loc7`='Cuando antes nos alejemos de la Madre Pétrea, mejor. No me fío de ella.' WHERE `ID`=52561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 수많은 변화를 견뎌야 했지... 누구도 상상하지 못한 엄청난 변화를.', `MaleText_loc4`='我们承受过太多……那远远超过了我们的想象。', `MaleText_loc5`='因為我們承受了太多...遠超過我們任何人的想像。', `MaleText_loc7`='Porque hemos sufrido mucho... más de lo que cualquiera de nosotros pudo imaginar nunca.' WHERE `ID`=52562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에 선 자들이여, 간청컨대 그대의 짐은 모두 내 뒤에 내려놓으라.', `MaleText_loc4`='请站到我面前来，将你的一切烦恼抛诸身后。', `MaleText_loc5`='如今你站在這裡，請你將身上的負擔都拋諸腦後吧。', `MaleText_loc7`='Allá donde estén, les pido que arrojen sus pesares detrás de mí.' WHERE `ID`=52563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 자리를 빌려 우리는 두려움을 조롱한다... 미지의 공포를 담대하게 바라보고 크게 웃어 보자!', `MaleText_loc4`='我们要做的是嘲笑一切恐怖的存在，大胆瞪视残酷的未知，并放声大笑！', `MaleText_loc5`='這是嘲笑恐懼的機會，無畏地直視嚴峻的未知，然後笑吧!', `MaleText_loc7`='¡Es una oportunidad para burlarnos de lo que nos aterra, de mirar con valor lo desconocido que nos asusta, y reír!' WHERE `ID`=52564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활활 타오르는 횃불로 인형을 불태워 버리자. 내일에 대한 두려움을 이로써 누그러뜨리자.', `MaleText_loc4`='让它随燃烧的火苗灰飞烟灭，使我们能沉着应对未来的一切。', `MaleText_loc5`='以騷亂為火種，燃燒它吧;冶煉我們來面對明天的挑戰。', `MaleText_loc7`='Que arda rápido como la yesca; que nos otorgue templanza para enfrentarnos al mañana.' WHERE `ID`=52565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼거미가 둥지에서 쏟아져나옵니다!', `MaleText_loc4`='幼蛛从巢穴里爬出来了！', `MaleText_loc5`='小蜘蛛從牠們的巢穴中被驚動了!', `MaleText_loc7`='¡Las arañas emergen de su nido!', `FemaleText_loc1`='새끼거미가 둥지에서 쏟아져나옵니다!', `FemaleText_loc4`='幼蛛从巢穴里爬出来了！', `FemaleText_loc5`='小蜘蛛從牠們的巢穴中被驚動了!', `FemaleText_loc7`='¡Las arañas emergen de su nido!' WHERE `ID`=52566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 위에서 잿그물 실거미가 거미줄을 타고 내려옵니다!', `MaleText_loc4`='烬网织网蛛爬下来了！', `MaleText_loc5`='燼網紡織者從上方垂盪下來!', `MaleText_loc7`='¡Hiladoras Telaceniza cuelgan de arriba!', `FemaleText_loc1`='머리 위에서 잿그물 실거미가 거미줄을 타고 내려옵니다!', `FemaleText_loc4`='烬网织网蛛爬下来了！', `FemaleText_loc5`='燼網紡織者從上方垂盪下來!', `FemaleText_loc7`='¡Hiladoras Telaceniza cuelgan de arriba!' WHERE `ID`=52567;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 도착했을 때 이미 소환의 룬이 그려져 있었다. 넌 이제 놈들을 모두 처치해야 해.', `FemaleText_loc4`='我们抵达的时候，召唤符文都已经画好了。你必须把它们全部摧毁。', `FemaleText_loc5`='這些召喚的符文在我們抵達之前已經畫好了。你會需要摧毀全部的符文。', `FemaleText_loc7`='Las runas de Invocación ya estaban dibujadas cuando llegamos. Tienes que destruirlas todas.' WHERE `ID`=52568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 심판의 시간은 바로 지금이다.', `MaleText_loc4`='不，恶魔。你的时间不多了。', `MaleText_loc5`='不，惡魔。你的死期到了。', `MaleText_loc7`='No, monstruo. Ha llegado tu HORA.' WHERE `ID`=52569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여! 그를 속박했다. 끝을 내라!', `MaleText_loc4`='英雄们！他被束缚了！解决他！', `MaleText_loc5`='英雄們!他被困住了!解決他!', `MaleText_loc7`='¡Héroes! Está paralizado. ¡Acaben con él!' WHERE `ID`=52570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝났다!', `MaleText_loc4`='终于结束了！', `MaleText_loc5`='看來結束了。', `MaleText_loc7`='¡Entonces está hecho!' WHERE `ID`=52571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마도...', `MaleText_loc4`='也许……', `MaleText_loc5`='也許吧。', `MaleText_loc7`='Quizás…' WHERE `ID`=52572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 또 한 번 세상을 구했구나.', `MaleText_loc4`='英雄们，这个世界欠你们太多了。', `MaleText_loc5`='英雄們，這個世界欠你良多。', `MaleText_loc7`='Héroes, el mundo está en deuda con ustedes.' WHERE `ID`=52573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스는 사라졌으나, 그를 따랐던 원초적인 세력까지 모두 없어지진 않았다. 누군가 또 나타날 것이다.', `MaleText_loc4`='拉格纳罗斯灰飞烟灭了。但他所代表的原始力量不会终结。将来，必定会有人替代他。', `MaleText_loc5`='拉格納羅斯已經敗亡。但是他所代表的原始力量永遠不會消滅。總有一天，會有人取代他。', `MaleText_loc7`='Ragnaros ha muerto. Pero nunca eliminaremos los poderes primarios que representa. Algún día, otro se alzará en busca de poder.' WHERE `ID`=52574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 세나리우스 님. 이 땅에서 결코 경계를 늦춰서는 안 될 것입니다. 하지만 오늘만큼은 우리의 위대한 승리를 축하했으면 합니다.', `MaleText_loc4`='是的，塞纳留斯。必须在这设立一个永久的岗哨。先庆祝这一天吧，庆祝这来之不易的伟大胜利。', `MaleText_loc5`='是的，塞納留斯，我們必須持續不懈地看顧這個世界。但今天，讓我們好好慶祝我們贏得的勝利吧!', `MaleText_loc7`='Sí, Cenarius. Debemos vigilar este reino día y noche. Pero celebremos la gran victoria que hemos obtenido hoy.' WHERE `ID`=52575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러자꾸나.', `MaleText_loc4`='必须的。', `MaleText_loc5`='沒錯。', `MaleText_loc7`='Desde luego.' WHERE `ID`=52576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기예요! 보세요. 돌이 되어... 굳어 버렸네요... 무정하게... 얼굴엔... 단호함과... 결연함이 어려 있군요. 고엘이 고집 부릴 때 짓는 표정이에요.', `FemaleText_loc4`='看那儿！看看他，被禁锢在石头中，无法动弹。毫无知觉。他脸上的表情……如此坚定，如此顽固。这是他拒绝妥协的表情。', `FemaleText_loc5`='在那裡!看看他─凍在石頭中，無法行動，無法感受。他臉上的表情...顯示出的決心和固執。他一旦做出決定就是這樣。', `FemaleText_loc7`='¡Ahí! Míralo, como un bloque de piedra, inamovible. Sin sentimientos. Esa mirada en su rostro... La determinación, la terquedad. Es la que pone cuando se obstina.' WHERE `ID`=52577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 표정, 본 적이 있습니다. 나그란드에서 대족장 자리를 안 내놓겠다 했을 때도, 훈련을 할 때도 저 표정이었죠.', `FemaleText_loc4`='我见过这个表情。那是在纳格兰，他拒绝放下酋长的责任。在他受训时也出现过。', `FemaleText_loc5`='我曾經看過─當他在納葛蘭拒絕卸下大酋長一職時，和在他接受訓練的時候。', `FemaleText_loc7`='La he visto antes... En Nagrand cuando se negó a renunciar a su autoridad como Jefe de Guerra y, otra vez, durante su instrucción.' WHERE `ID`=52578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 황혼의 망치단은 우릴 기다렸던 거예요! 무기를 들어요!', `FemaleText_loc4`='我就知道！暮光之锤知道我们会来这里！保护你自己！', `FemaleText_loc5`='我早該想到!暮光之錘知道我們會出現在這!準備戰鬥!', `FemaleText_loc7`='¡El Martillo Crepuscular sabía que estaríamos aquí! ¡Defiéndete!' WHERE `ID`=52579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금도 보세요. 사방에서 적이 난리를 피우는데도, 싸움은커녕, 손가락 하나 까닥하지 않네요. 고엘... 가끔은 정말 속이 터지는 거 알아요?', `FemaleText_loc4`='即使是现在，无数的敌人在我们周围蠢蠢欲动，他还是拒绝行动。唉，古伊尔……有时你真是惹人生气。', `FemaleText_loc5`='就連現在，當我們被敵人重重包圍之時，他還是拒絕動一動。噢，高爾，你有時實在是令人生氣。', `FemaleText_loc7`='Incluso ahora, mientras nuestros enemigos se arrojan sobre nosotros, se niega a moverse, ¡a actuar! Go''el… a veces puedes resultar desesperante.' WHERE `ID`=52580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친구여, 진심으로, 진심으로 고맙습니다. 그대의 용기, 그대의 힘... 마치...$b$b고엘을 보는 듯합니다.', `FemaleText_loc4`='朋友……请接受我最深的感谢。你的勇气，你的力量……你……$b$b你让我想起了他。', `FemaleText_loc5`='聽我說，朋友...你擁有我最深的感激。你的勇氣，你的力量...你...$b$b你讓我想到了他。', `FemaleText_loc7`='Debes saber que tienes mi más profundo agradecimiento. Tu valor, tu fuerza, tú...$b$bMe recuerdas a él.' WHERE `ID`=52581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 저는 준비되었습니다. 스랄 님에게 갑시다.', `MaleText_loc4`='阿格娜，我准备好了。我们去见萨尔吧。', `MaleText_loc5`='阿格拉，我準備好了。我們去找索爾吧。', `MaleText_loc7`='Aggra, estoy listo. Vamos a por Thrall.', `FemaleText_loc1`='아그라, 저는 준비되었습니다. 스랄 님에게 갑시다.', `FemaleText_loc4`='阿格娜，我准备好了。我们去见萨尔吧。', `FemaleText_loc5`='阿格拉，我準備好了。我們去找索爾吧。', `FemaleText_loc7`='Aggra, estoy lista. Vamos a por Thrall.' WHERE `ID`=52583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 용암을 들이마시기 시작합니다.', `MaleText_loc4`='%s开始吸取熔岩之池。', `MaleText_loc5`='%s開始喝熔岩池裡的岩漿。', `MaleText_loc7`='%s empieza a beber de los charcos de magma.' WHERE `ID`=52585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 용암 벌레가 땅에서 튀어나옵니다!', `MaleText_loc4`='熔岩火虫从地下涌出来了！', `MaleText_loc5`='熾炎熔岩蟲從地上鑽了出來!', `MaleText_loc7`='¡Gusanos de lava ígneos surgen del suelo!', `FemaleText_loc1`='불타는 용암 벌레가 땅에서 튀어나옵니다!', `FemaleText_loc4`='熔岩火虫从地下涌出来了！', `FemaleText_loc5`='熾炎熔岩蟲從地上鑽了出來!', `FemaleText_loc7`='¡Gusanos de lava ígneos surgen del suelo!' WHERE `ID`=52586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t불의 땅에 서식하는 생명체들이 쓰러지자, 멀리서 사냥꾼의 뿔피리 소리가 들려옵니다.', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t就在火焰之地的怪物轰然倒地之时，远处传来了猎人的号角声。', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t在火源之界的生物逐一倒下時，一個獵手的號角在遠處響起。', `MaleText_loc7`='|TInterfaceIconsinv_misc_horn_03.blp:20|tA medida que caen las criaturas de las Tierras de Fuego se oye, a lo lejos, el cuerno de un cazador.' WHERE `ID`=52588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t사냥꾼의 뿔피리 소리가 더 가까운 곳에서, 더 다급하게 울려 퍼집니다.', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t猎号声再次响起，显得越发迫近。', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_horn_03.blp:20|t獵手的號角又響了起來，這次更加接近，並聽起來更為緊急。', `MaleText_loc7`='|TInterfaceIconsinv_misc_horn_03.blp:20|tEl cuerno de caza suena de nuevo, más cerca y con más urgencia.' WHERE `ID`=52589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성배에서 물방울이 떨어지더니, 그 자리에 작은 달샘이 생겨납니다.', `MaleText_loc4`='圣杯的一小滴液体形成了一小口月亮井。', `MaleText_loc5`='從杯子滴出的液體形成了一個小小的月井。', `MaleText_loc7`='Una pequeña Poza de la Luna emerge de las gotas que caen del cáliz.' WHERE `ID`=52590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹아내린 알에 금이 가며 쪼개지기 시작합니다!', `MaleText_loc4`='熔火之卵开始开裂了！', `MaleText_loc5`='熔岩蛋開始裂開了!', `MaleText_loc7`='¡Los huevos de magma empiezan a resquebrajarse y a astillarse!', `FemaleText_loc1`='녹아내린 알에 금이 가며 쪼개지기 시작합니다!', `FemaleText_loc4`='熔火之卵开始开裂了！', `FemaleText_loc5`='熔岩蛋開始裂開了!', `FemaleText_loc7`='¡Los huevos de magma empiezan a resquebrajarse y a astillarse!' WHERE `ID`=52591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진도가 자신의 무기에 학카르의 어둠을 불어넣습니다!', `MaleText_loc4`='金度给自己的武器注入了哈卡之影！', `MaleText_loc5`='金度使用了哈卡之影來替自己的武器充能!', `MaleText_loc7`='¡Jin''do carga su arma con las Sombras de Hakkar!' WHERE `ID`=52592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타는 나무정령이 수호정령을 돕기 위해 땅에서 일어납니다!', `MaleText_loc4`='烈焰树人从地下涌出，来协助保护者了！', `MaleText_loc5`='燃燒的樹人從地面冒出來協助保衛者!', `MaleText_loc7`='¡Antárboles ardientes emergen del suelo para ayudar al protector!', `FemaleText_loc1`='불타는 나무정령이 수호정령을 돕기 위해 땅에서 일어납니다!', `FemaleText_loc4`='烈焰树人从地下涌出，来协助保护者了！', `FemaleText_loc5`='燃燒的樹人從地面冒出來協助保衛者!', `FemaleText_loc7`='¡Antárboles ardientes emergen del suelo para ayudar al protector!' WHERE `ID`=52593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 %s|1이;가; |cFFFF0000등장|r합니다!', `MaleText_loc4`='%s即将|cFFFF0000现身|r！', `MaleText_loc5`='%s正準備要|cFFFF0000浮現|r!', `MaleText_loc7`='¡%s está a punto de |cFFFF0000Aparecer!|r' WHERE `ID`=52594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽에 있는 아그라의 바람의 토템 주위에서 정령을 처치해야 합니다!', `MaleText_loc4`='杀死空气图腾附近的元素，它们在西边！', `MaleText_loc5`='在西邊殺死阿格拉的風之圖騰附近的元素!', `MaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de aire de Aggra, al oeste!', `FemaleText_loc1`='서쪽에 있는 아그라의 바람의 토템 주위에서 정령을 처치해야 합니다!', `FemaleText_loc4`='杀死空气图腾附近的元素，它们在西边！', `FemaleText_loc5`='在西邊殺死阿格拉的風之圖騰附近的元素!', `FemaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de aire de Aggra, al oeste!' WHERE `ID`=52597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에 있는 아그라의 물의 토템 주위에서 정령을 처치해야 합니다!', `MaleText_loc4`='杀死水图腾附近的元素，它们在北边！', `MaleText_loc5`='在北邊殺死阿格拉的水之圖騰附近的元素!', `MaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de agua de Aggra, al norte!', `FemaleText_loc1`='북쪽에 있는 아그라의 물의 토템 주위에서 정령을 처치해야 합니다!', `FemaleText_loc4`='杀死水图腾附近的元素，它们在北边！', `FemaleText_loc5`='在北邊殺死阿格拉的水之圖騰附近的元素!', `FemaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de agua de Aggra, al norte!' WHERE `ID`=52598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽에 있는 아그라의 대지의 토템 주위에서 정령을 처치해야 합니다!', `MaleText_loc4`='杀死大地图腾附近的元素，它们在东边！', `MaleText_loc5`='在東邊殺死阿格拉的大地圖騰附近的元素!', `MaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de tierra de Aggra, al este!', `FemaleText_loc1`='동쪽에 있는 아그라의 대지의 토템 주위에서 정령을 처치해야 합니다!', `FemaleText_loc4`='杀死大地图腾附近的元素，它们在东边！', `FemaleText_loc5`='在東邊殺死阿格拉的大地圖騰附近的元素!', `FemaleText_loc7`='¡Mata a los elementales que hay cerca del tótem de tierra de Aggra, al este!' WHERE `ID`=52599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 근처에 있는 아그라의 불의 토템 주위에서 정령을 처치해야 합니다!', `MaleText_loc4`='杀死火焰图腾附近的元素，它们在萨尔身边！', `MaleText_loc5`='在索爾身邊殺死阿格拉的火焰圖騰附近的元素!', `MaleText_loc7`='¡Mata a los elementales que hay alrededor del tótem de fuego de Aggra, cerca de Thrall!', `FemaleText_loc1`='스랄 근처에 있는 아그라의 불의 토템 주위에서 정령을 처치해야 합니다!', `FemaleText_loc4`='杀死火焰图腾附近的元素，它们在萨尔身边！', `FemaleText_loc5`='在索爾身邊殺死阿格拉的火焰圖騰附近的元素!', `FemaleText_loc7`='¡Mata a los elementales que hay alrededor del tótem de fuego de Aggra, cerca de Thrall!' WHERE `ID`=52600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부모님은... 어린 나를 두고 배신자에게 살해당하셨다!', `MaleText_loc4`='我的父母……在我懂事之前就被害了……背叛！', `MaleText_loc5`='我的雙親...在我懂事前就被殺害...被背叛!', `MaleText_loc7`='MIS PADRES... ASESINADOS ANTES DE QUE PUDIERA CONOCERLOS... ¡TRAICIONADOS!' WHERE `ID`=52601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴단! 내가 저승에서도 타오를 수만 있다면, 온 지옥을 뒤져 네놈을 찾겠다!', `MaleText_loc4`='古尔丹！我的怒火会烧尽来世之路，将你从藏身的地狱中揪出来！', `MaleText_loc5`='古爾丹!我就算是死都會找到你，不管你躲在地獄的哪個角落!', `MaleText_loc7`='¡GUL''DAN! ¡AUNQUE TENGA QUE ABRIRME PASO A FUEGO EN LA OTRA VIDA, TE ENCONTRARÉ EN EL INFIERNO EN EL QUE TE HAYAS ESCONDIDO!' WHERE `ID`=52602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 복수하겠다! 내 말 들리나???', `MaleText_loc4`='我的复仇终将实现！你听到了吗？？？', `MaleText_loc5`='我會為父母報仇!你聽到了沒有???', `MaleText_loc7`='¡ME VENGARÉ! ¿¿ME OYES??' WHERE `ID`=52603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘의 분노가 폭발하고 있습니다! 그 많은 분노와 그 많은 고통... 이제껏 그 모든 걸 억눌러 왔던 겁니다...', `FemaleText_loc4`='他可真是发怒了！如此愤怒，如此痛苦……这么多年来他一直用自己的力量压抑着……', `FemaleText_loc5`='他絕對氣炸了!如此大的怒火，如此深的痛苦...而他這幾年竟然能壓抑住它們...', `FemaleText_loc7`='¡Está furioso! Tanta ira, tanto dolor... y ha tenido la fuerza para reprimirlos todos estos años…' WHERE `ID`=52604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예로 자라... 인간의 노리개가 되어 살육을 저질렀다...', `MaleText_loc4`='当作奴隶养大，为取悦人类而杀戮……', `MaleText_loc5`='被當成奴隸養大...以殺戮娛樂人類...', `MaleText_loc7`='CRIADO COMO ESCLAVO... PARA MATAR PARA DIVERSIÓN DE LOS HUMANOS..' WHERE `ID`=52605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙무어에겐 죽음도 과분하다. 누군가를 노예로 부리는 놈들은... 죽이는 걸로는 모자라!', `MaleText_loc4`='死亡对布莱克摩尔太仁慈了。奴役他人者的下场应该比死亡更可怕！', `MaleText_loc5`='死亡還不足以贖布拉克摩爾的罪。任何奴役他人的人都應得比死亡更淒慘的下場!', `MaleText_loc7`='LA MUERTE FUE DEMASIADO BUENA PARA LODONEGRO. AQUEL QUE ESCLAVIZA A OTRO... ¡MERECE ALGO PEOR QUE LA MUERTE!' WHERE `ID`=52606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파렴치한 놈들! 모두 죗값을 치르리라!', `MaleText_loc4`='所有人都有罪！所有人都要受罚！', `MaleText_loc5`='全部有罪!全都要付出代價!', `MaleText_loc7`='¡TODOS SON CULPABLES! ¡TODOS DEBEN PAGAR!' WHERE `ID`=52607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 국왕... 우리 백성과 전쟁을 벌이고 싶어 죽겠지? 그래, 인간들아, 전쟁이다!', `MaleText_loc4`='瓦里安国王……你想向我的人民宣战？战争是你自找的，人类！', `MaleText_loc5`='瓦里安國王...你希望與我的同胞戰鬥?那就來戰吧，人類!', `MaleText_loc7`='REY VARIAN... ¿DESEAS DECLARARLE LA GUERRA A MI PUEBLO? ¡TENDRÁS TU GUERRA, HUMANO!' WHERE `ID`=52608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 전체가 호드의 분노로 불타는 모습을 보여 주마! 네놈의 그 옥좌를 둘로 쪼개어 주겠다! 맹세하겠다!', `MaleText_loc4`='部落的怒火将横扫你的城市！你将看着你的王座被劈成两半！我发誓！', `MaleText_loc5`='你將目睹部落的怒火把你的城鎮夷為平地!你將看到你的王座一分為二!我在此起誓!', `MaleText_loc7`='¡VERÁS CÓMO LA FURIA DE LA HORDA DESTRUYE TUS CIUDADES! ¡VERÁS CÓMO TU TRONO SE DESMORONA! ¡¡LO JURO!!' WHERE `ID`=52609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬... 가로쉬...', `MaleText_loc4`='加尔鲁什……加尔鲁什……', `MaleText_loc5`='卡爾洛斯...卡爾洛斯...', `MaleText_loc7`='GARROSH... Garrosh...' WHERE `ID`=52610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘! 고엘, 이제 그만 해요! 화나는 건 알지만, 그럴수록 그대만 힘들어져요. 화를 억눌러요. 안 그럼 승산이 없어요!', `FemaleText_loc4`='古伊尔！古伊尔，你必须停下来！你的愤怒是正确的，但它会吞噬你！压抑它，否则我们都会失败！', `FemaleText_loc5`='高爾!高爾，你必須停手!你的確應該感到憤怒...但怒火只會吞噬你!抵抗它，不然我們都完了!', `FemaleText_loc7`='¡Go''el! ¡Go''el, debes parar! ¡Tu ira es JUSTA... pero acabará consumiéndote! ¡Combátela o TODOS estaremos PERDIDOS!' WHERE `ID`=52611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='케른은 내 형제였단 말이다!!!!!!!!!', `MaleText_loc4`='凯恩是我的兄弟！！！', `MaleText_loc5`='凱恩是我的兄弟啊!!!', `MaleText_loc7`='¡¡¡CAIRNE ERA MI HERMANO!!!' WHERE `ID`=52612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 말이 들리기는 해요???', `FemaleText_loc4`='你能听到吗？', `FemaleText_loc5`='你到底聽得到嗎?', `FemaleText_loc7`='¿Puedes oírme siquiera?' WHERE `ID`=52613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 많은 분들이 여기 이 전통적인 축제를 즐기러 온 모습을 보니 아주 기쁘군요. 올해는 참 힘든 일도 많았지만, 그러다 보니 가을 축제가 더 반갑고 유쾌합니다.', `MaleText_loc4`='你们都聚在这里庆祝这个伟大的节日，真是令人高兴。今年，我们经历了许多艰难困苦，所以像美酒节这样的节日特别振奋人心，特别受欢迎。', `MaleText_loc5`='看到你們大家這麼多人在此慶祝這個光榮的慶典真好。我們今年經歷了許多災難，所以很歡迎有個像啤酒節這麼棒的慶典。', `MaleText_loc7`='Me alegro de veros a todos aquí para celebrar esta festividad tan honorable. Todos hemos sufrido muchas tragedias este año, así que una fiesta como la Fiesta de la Cerveza es una celebración llena de júbilo que acogemos con regocijo.', `FemaleText_loc1`='이렇게 많은 분들이 여기 이 전통적인 축제를 즐기러 온 모습을 보니 아주 기쁘군요. 올해는 참 힘든 일도 많았지만, 그러다 보니 가을 축제가 더 반갑고 유쾌합니다.', `FemaleText_loc4`='你们都聚在这里庆祝这个伟大的节日，真是令人高兴。今年，我们经历了许多艰难困苦，所以像美酒节这样的节日特别振奋人心，特别受欢迎。', `FemaleText_loc5`='看到你們大家這麼多人在此慶祝這個光榮的慶典真好。我們今年經歷了許多災難，所以很歡迎有個像啤酒節這麼棒的慶典。', `FemaleText_loc7`='Me alegro de veros a todos aquí para celebrar esta festividad tan honorable. Todos hemos sufrido muchas tragedias este año, así que una fiesta como la Fiesta de la Cerveza es una celebración llena de júbilo que acogemos con regocijo.' WHERE `ID`=52614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 해 전에 마그니 국왕이 제게 가을 축제를 열자고 했을 때, 전 우리 노움이 정말로 기억에 남을 멋진 가을 축제를 개최할 수 있을 거라고 말했었지요. 하지만 마그니 국왕도 우리 노움은 다른 일에 더 신경을 써야 한다는 사실을 알았기 때문에, 그냥 조촐한 축제를 열어 옛 전통을 이어가라고만 했지요.', `MaleText_loc4`='许多年前，当麦格尼国王陛下把这些节日的准备工作交给我的时候，我向他保证，我们侏儒会将美酒节办成一场令人难忘的盛会。但麦格尼明白我们侏儒还有许多工作要做。所以他希望这个节日能够办得朴素庄重，以纪念往昔。', `MaleText_loc5`='多年前，麥格尼國王來找我談及這個慶典。我跟他保證我們地精可以讓啤酒節成為一個難忘的節日。但是麥格尼知道我們地精還有其他的工作得要進行。他想要這個節日能簡單地緬懷過去就好。', `MaleText_loc7`='Hace años, cuando el rey Magni me habló de estas celebraciones, le aseguré que los gnomos podríamos convertir la Fiesta de la Cerveza en un acontecimiento digno de recordar. Pero Magni sabía que los gnomos teníamos otras tareas en las que debíamos centrar nuestras fuerzas. Quería mantener las cosas sencillas y honrar el pasado.', `FemaleText_loc1`='여러 해 전에 마그니 국왕이 제게 가을 축제를 열자고 했을 때, 전 우리 노움이 정말로 기억에 남을 멋진 가을 축제를 개최할 수 있을 거라고 말했었지요. 하지만 마그니 국왕도 우리 노움은 다른 일에 더 신경을 써야 한다는 사실을 알았기 때문에, 그냥 조촐한 축제를 열어 옛 전통을 이어가라고만 했지요.', `FemaleText_loc4`='许多年前，当麦格尼国王陛下把这些节日的准备工作交给我的时候，我向他保证，我们侏儒会将美酒节办成一场令人难忘的盛会。但麦格尼明白我们侏儒还有许多工作要做。所以他希望这个节日能够办得朴素庄重，以纪念往昔。', `FemaleText_loc5`='多年前，麥格尼國王來找我談及這個慶典。我跟他保證我們地精可以讓啤酒節成為一個難忘的節日。但是麥格尼知道我們地精還有其他的工作得要進行。他想要這個節日能簡單地緬懷過去就好。', `FemaleText_loc7`='Hace años, cuando el rey Magni me habló de estas celebraciones, le aseguré que los gnomos podríamos convertir la Fiesta de la Cerveza en un acontecimiento digno de recordar. Pero Magni sabía que los gnomos teníamos otras tareas en las que debíamos centrar nuestras fuerzas. Quería mantener las cosas sencillas y honrar el pasado.' WHERE `ID`=52615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 내가 조금 실망했다는 걸 알았는지, 마그니 국왕이 축제에 작은 변화를 주라고 하더군요. 그래서 가을 축제 맥주통 따기 행사를 열게 되었습니다. 아... 더 빨리 맥주통을 따서 그 안의 맥주를 모든 참가자가 더 효율적이고 더 빠른 속도로 나눠 마시는 방법은 없을지 며칠 동안이나 밤을 새우며 고민하던 생각이 나네요.', `MaleText_loc4`='我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。我还记得那无数个夜晚里，我独自一人静静思考如何最有效率地打开酒桶，并把里面的酒绝对平均地分给大家喝，请注意绝对平均和最有效率这两个词。', `MaleText_loc5`='麥格尼國王一定感受到我的失望，所以同意了一些改變。他允許讓我有機會負責啤酒節的酒桶。我還記得花了很多個晚上嘗試了解如何有效且快速的開啟桶子並分配容量，讓所有的參與者都能快速有效的分到相同的等分。', `MaleText_loc7`='El rey Magni debió de percibir la decepción ya que permitió un ligero cambio. Me concedió la oportunidad de abrir el barril de la Fiesta de la Cerveza. Recuerdo que pasé noches despierto intentando dar con la forma de abrir el barril de forma rápida y eficiente, y distribuir el contenido a partes iguales entre todos los participantes de forma rápida y eficiente.', `FemaleText_loc1`='그래도 내가 조금 실망했다는 걸 알았는지, 마그니 국왕이 축제에 작은 변화를 주라고 하더군요. 그래서 가을 축제 맥주통 따기 행사를 열게 되었습니다. 아... 더 빨리 맥주통을 따서 그 안의 맥주를 모든 참가자가 더 효율적이고 더 빠른 속도로 나눠 마시는 방법은 없을지 며칠 동안이나 밤을 새우며 고민하던 생각이 나네요.', `FemaleText_loc4`='我对此可以理解，但国王陛下能允许我这个侏儒去开酒桶，已经是个改变了。我还记得那无数个夜晚里，我独自一人静静思考如何最有效率地打开酒桶，并把里面的酒绝对平均地分给大家喝，请注意绝对平均和最有效率这两个词。', `FemaleText_loc5`='麥格尼國王一定感受到我的失望，所以同意了一些改變。他允許讓我有機會負責啤酒節的酒桶。我還記得花了很多個晚上嘗試了解如何有效且快速的開啟桶子並分配容量，讓所有的參與者都能快速有效的分到相同的等分。', `FemaleText_loc7`='El rey Magni debió de percibir la decepción ya que permitió un ligero cambio. Me concedió la oportunidad de abrir el barril de la Fiesta de la Cerveza. Recuerdo que pasé noches despierta intentando dar con la forma de abrir el barril de forma rápida y eficiente, y distribuir el contenido a partes iguales entre todos los participantes de forma rápida y eficiente.' WHERE `ID`=52616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 계획을 세워 놓고, 남녀 가리지 않고 가장 뛰어난 기술자들을 모아 바로 그 작업을 할 기계를 만들기 시작했었지요! 우린 가장 좋은 방법이 무엇일지 알아내려고 작업을 초 단위까지 나눠서 계산했는데...', `MaleText_loc4`='制定出了完美的计划之后，我派出了手下最精锐的人员来研制能够完成任务的机器！我们的计算已经精确到秒……', `MaleText_loc5`='在計畫制定後，我讓我的頂尖手下開始運作機器來進行那個的任務!我們已經精算到秒，該如何以最佳的-', `MaleText_loc7`='¡Así que pedí a mis mejores hombres y mujeres que comenzaran a trabajar en una máquina que desarrollase esa tarea! Hemos calculado al milímetro como dist...', `FemaleText_loc1`='그렇게 계획을 세워 놓고, 남녀 가리지 않고 가장 뛰어난 기술자들을 모아 바로 그 작업을 할 기계를 만들기 시작했었지요! 우린 가장 좋은 방법이 무엇일지 알아내려고 작업을 초 단위까지 나눠서 계산했는데...', `FemaleText_loc4`='制定出了完美的计划之后，我派出了手下最精锐的人员来研制能够完成任务的机器！我们的计算已经精确到秒……', `FemaleText_loc5`='在計畫制定後，我讓我的頂尖手下開始運作機器來進行那個的任務!我們已經精算到秒，該如何以最佳的-', `FemaleText_loc7`='¡Así que pedí a mis mejores hombres y mujeres que comenzaran a trabajar en una máquina que desarrollase esa tarea! Hemos calculado al milímetro como dist...' WHERE `ID`=52617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 여기 계신 분들이 시험용 맥주통 따개 74205와 75633에 대한 이야기를 듣고 싶어하지는 않을 것 같군요... 어쩌면 시험용 1701-D에 대한 이야기는 재미있을지도 모르겠는데요...', `MaleText_loc4`='……好吧……我估计这儿已经没人想听到开罐器74205和75633的名字了……如果我说开罐器1701-D的话，你们可能会兴奋一点……', `MaleText_loc5`='唔...我猜沒有人想要進一步了解開桶器原型74205和75633了...可能我改說成說明原型1701-D，你們會比較有興趣...', `MaleText_loc7`='Bueno... Supongo que nadie de los presentes querrá oír hablar de los prototipos 74205 y 75633 del Abrebarriles... Quizá si os hablara del prototipo 1701-D, entonces suscitaría cierto interés...', `FemaleText_loc1`='뭐... 여기 계신 분들이 시험용 맥주통 따개 74205와 75633에 대한 이야기를 듣고 싶어하지는 않을 것 같군요... 어쩌면 시험용 1701-D에 대한 이야기는 재미있을지도 모르겠는데요...', `FemaleText_loc4`='……好吧……我估计这儿已经没人想听到开罐器74205和75633的名字了……如果我说开罐器1701-D的话，你们可能会兴奋一点……', `FemaleText_loc5`='唔...我猜沒有人想要進一步了解開桶器原型74205和75633了...可能我改說成說明原型1701-D，你們會比較有興趣...', `FemaleText_loc7`='Bueno... Supongo que nadie de los presentes querrá oír hablar de los prototipos 74205 y 75633 del Abrebarriles... Quizá si os hablara del prototipo 1701-D, entonces suscitaría cierto interés...' WHERE `ID`=52618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 좋아요... 열부터 초읽기를 시작해 봅시다, 여러분, 준비되셨나요? 열!', `MaleText_loc4`='好吧，好吧……现在我们就开始十秒倒计时，大家准备好了吗？10！', `MaleText_loc5`='對，沒錯...那麼讓我們從十開始倒數計時，準備好了嗎?十!', `MaleText_loc7`='Vale, vale... Comencemos la cuenta atrás desde diez, ¿preparados? ¡10!', `FemaleText_loc1`='좋아, 좋아요... 열부터 초읽기를 시작해 봅시다, 여러분, 준비되셨나요? 열!', `FemaleText_loc4`='好吧，好吧……现在我们就开始十秒倒计时，大家准备好了吗？10！', `FemaleText_loc5`='對，沒錯...那麼讓我們從十開始倒數計時，準備好了嗎?十!', `FemaleText_loc7`='Vale, vale... Comencemos la cuenta atrás desde diez, ¿preparados? ¡10!' WHERE `ID`=52619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 알겠습니다. 그냥 영이 됐다고 합시다...', `MaleText_loc4`='哦……好吧，让我们直接数零吧……', `MaleText_loc5`='喔...好吧，那我直接等零好了...', `MaleText_loc7`='Oh... vale, esperaré hasta el cero...', `FemaleText_loc1`='아... 알겠습니다. 그냥 영이 됐다고 합시다...', `FemaleText_loc4`='哦……好吧，让我们直接数零吧……', `FemaleText_loc5`='喔...好吧，那我直接等零好了...', `FemaleText_loc7`='Oh... vale, esperaré hasta el cero...' WHERE `ID`=52620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 살아있다...', `MaleText_loc4`='我……还活着……', `MaleText_loc5`='我還...活著...', `MaleText_loc7`='Estoy... vivo...' WHERE `ID`=52621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘, 그대를 잃는 줄 알았어요...', `FemaleText_loc4`='古伊尔，我以为我要失去你了……', `FemaleText_loc5`='高爾，我以為我失去你了...', `FemaleText_loc7`='Go''el, creía que te había perdido...' WHERE `ID`=52622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 내 심장이여... 그대는 날 포기하지 않았소. 내 생명, 그리고 내 모든 것이 그대의 것이오.', `MaleText_loc4`='阿格娜，我的心……你从未放弃我。我的生命，我的一切，都亏欠于你。', `MaleText_loc5`='阿格拉，我的摯愛...你從沒放棄過我。我的生命...我的所有都屬於妳。', `MaleText_loc7`='Aggra, corazón mío... Nunca te rendiste conmigo. Te debo la vida... todo lo que soy.' WHERE `ID`=52623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 보이오. 끊임없는 의심과 분노에 억눌려 살아온 나의 모습이. 나 스랄은 평생 두려움을 안고 사는 삶...', `MaleText_loc4`='我看清了现在的自己——怀疑和愤怒摧垮了我。终我一生，我自己选择了成为恐惧的奴隶……', `MaleText_loc5`='我看到了我自己的變化，被猜忌和怒火所控制。我這一生，我選擇了成為恐懼的奴隸...', `MaleText_loc7`='Porque ahora veo en lo que me he convertido al dejarme llevar por la duda y la ira. Toda mi vida, he elegido ser un esclavo del miedo...' WHERE `ID`=52624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 노예의 삶을 살아왔소.', `MaleText_loc4`='……一个“萨尔”。', `MaleText_loc5`='...和它的傀儡。', `MaleText_loc7`='...un THRALL.' WHERE `ID`=52625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판드랄은 나의 이런 약점을 이용하려고 했소...', `MaleText_loc4`='范达尔想利用我的弱点来对付我……', `MaleText_loc5`='范達爾想利用那個弱點來對付我...', `MaleText_loc7`='Fandral intentó utilizar esa debilidad contra mí...' WHERE `ID`=52626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그와 그를 조종하는 황혼의 주인들이 하나 간과한 게 있었소. 정령은 분노와 전쟁을 위해 존재하는 게 아니라... 세상 안의... 그리고 우리 안의 조화를 유지하기 위해 존재한다는 사실을.', `MaleText_loc4`='但他和他的暮光主子永远不明白的是：愤怒与争斗并非元素存在的意义……他们为协调而生：与世界的协调，与我们的协调。', `MaleText_loc5`='但他和他的暮光大師從來不瞭解，元素的存在不是為了戰爭和怒火...它們的存在是為了替世界...和我們帶來和諧。', `MaleText_loc7`='Pero lo que él y sus amos Crepusculares nunca han entendido es que los elementos no existen para la ira y la guerra... existen para traer armonía al mundo... y a nosotros.' WHERE `ID`=52627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그 진실을 보았고, 그러자 내 사슬이 끊겼소.', `MaleText_loc4`='我见证了真理，我的枷锁已经碎了。', `MaleText_loc5`='我看到了真理─而我的枷鎖也打開了。', `MaleText_loc7`='He visto la VERDAD y he roto mis cadenas.' WHERE `ID`=52628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 난 예전의 나로 돌아왔소... 아니 그 이상이 되었소.', `MaleText_loc4`='我又变成了曾经的我……而且更加强大。', `MaleText_loc5`='現在的我已經比以前擁有的還要更多。', `MaleText_loc7`='Ahora, soy todo lo que fui una vez... y más.' WHERE `ID`=52629;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말은 확실히 많아졌네요...', `FemaleText_loc4`='哦……你显然更加健谈了……', `FemaleText_loc5`='話是比以前多了沒錯...', `FemaleText_loc7`='Bueno, parece que estás más comunicativo...' WHERE `ID`=52630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러 세계수로 돌아가야 합니다! 용의 위상들이 기다리고 있어요...', `FemaleText_loc4`='但我们必须尽快回到世界之树！守护巨龙在等待……', `FemaleText_loc5`='但我們必須快點回到世界樹那!守護巨龍在等我們...', `FemaleText_loc7`='Pero debemos apresurarnos a volver al Árbol del Mundo. Los dragones Aspectos esperan...' WHERE `ID`=52631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 친구여. 자네의 도움과 우정을 어떻게 갚아야 할지...', `MaleText_loc4`='谢谢你，我的朋友。我难以回报你的忠诚和友谊。', `MaleText_loc5`='謝謝你，我的朋友。我永遠都無法報答你的貢獻和友誼。', `MaleText_loc7`='Gracias. Nunca podré devolverte el favor de tu amistad.' WHERE `ID`=52632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계수에서 우리 다시 만나세. 자네가 꼭... 봐 줬으면 하는 일이 있네.', `MaleText_loc4`='回世界之树再见吧。有件事情……我想邀你一同见证。', `MaleText_loc5`='在世界樹與我們見面。我...有些東西想讓你親眼目睹。', `MaleText_loc7`='Reúnete con nosotros en el Árbol del Mundo. Hay algo que... quiero que presencies.' WHERE `ID`=52633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입찰하실 물건을 마음껏 살펴보십시오. 혹시 경매에 부치고 싶은 물건이 있다면, 제가 도와드리겠습니다.', `MaleText_loc4`='请随意浏览这里的拍品。如果你有东西要拍卖的话，我也可以帮你办理。', `MaleText_loc5`='歡迎瀏覽拍賣中的物品，或者如果你想要放東西上去拍賣，我也能幫忙。', `MaleText_loc7`='Puedes rebuscar entre los objetos que hay para subasta, o si prefieres poner algo a la venta, yo puedo ayudarte.' WHERE `ID`=52634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장에 올라온 물건을 살펴보고 싶습니다.', `MaleText_loc4`='我要查看拍卖的物品。', `MaleText_loc5`='我想要瀏覽拍賣中的物品。', `MaleText_loc7`='Me gustaría echar un vistazo a los objetos que hay para subasta.', `FemaleText_loc1`='경매장에 올라온 물건을 살펴보고 싶습니다.', `FemaleText_loc4`='我要查看拍卖的物品。', `FemaleText_loc5`='我想要瀏覽拍賣中的物品。', `FemaleText_loc7`='Me gustaría echar un vistazo a los objetos que hay para subasta.' WHERE `ID`=52635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 수상해 보이는 자가 어떤 상자를 가져와서 그 안에 든 물건을 경매에 부치려고 한 적이 있습니까?', `MaleText_loc4`='最近有可疑人员来要求拍卖一箱货物吗？', `MaleText_loc5`='最近有可疑的人試著要放上一箱貨物嗎?', `MaleText_loc7`='¿Alguien de aspecto sospechoso ha intentado subastar un cajón lleno de mercancía hace poco?', `FemaleText_loc1`='최근에 수상해 보이는 자가 어떤 상자를 가져와서 그 안에 든 물건을 경매에 부치려고 한 적이 있나요?', `FemaleText_loc4`='最近有可疑人员来要求拍卖一箱货物吗？', `FemaleText_loc5`='最近有可疑的人試著要放上一箱貨物嗎?', `FemaleText_loc7`='¿Alguien de aspecto sospechoso ha intentado subastar un cajón lleno de mercancía hace poco?' WHERE `ID`=52636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 그저 우리의 밴시 여왕이시자 어둠의 여왕이신 실바나스 님의 보잘것없는 전령일 뿐이라네.', `FemaleText_loc4`='我只是伟大的女妖之王，黑暗女王希尔瓦娜斯座下一名卑微的信使。', `FemaleText_loc5`='我不過是黑暗女王希瓦娜斯·風行者，我們女妖之王手下一個謙卑的信使罷了。', `FemaleText_loc7`='No soy más que una humilde heraldo de la Dama Oscura Sylvanas, nuestra Reina alma en pena.' WHERE `ID`=52637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 보십시오, 경매인에게는 비밀 엄수가 생명이란 말입니다. 사실 이런 이야기를 하면 안 되는데...', `MaleText_loc4`='你瞧，干我这份工作的人，谨慎是第一要诀。我本来是不该提这事儿的。', `MaleText_loc5`='聽著，我們這一行，保密非常重要。我完全不應該討論這件事。', `MaleText_loc7`='Mira, en mi negocio la discreción es muy importante. Ni siquiera debería estar hablando de esto.' WHERE `ID`=52638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 당신이 말한 모습을 한 사람이 상자를 하나 들고 와서는, 그 안에 있는 비전 마력을 띤 물건을 경매에 올려달라고 하더군요.', `MaleText_loc4`='你所说的这个人不久前才来过，想让我帮他拍卖一箱奥术物品。', `MaleText_loc5`='你描述的那個人剛剛來這裡，並嘗試放上一箱秘法的物品。', `MaleText_loc7`='La persona que has descrito estuvo aquí hace poco e intentó convencerme de que admitiera a subasta un cajón lleno de objetos arcanos.' WHERE `ID`=52639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당연히 장물은 취급하지 않는다고 말했습니다. 여긴 스톰윈드 경매장입니다. 은밀한 거래가 판을 치는 뒷골목 중고 시장 따위가 아니라고요!', `MaleText_loc4`='自然的，我告诉他我们从不接受贼赃。这里是暴风城拍卖行。可不是后街上那种鬼鬼祟祟的黑市。', `MaleText_loc5`='我很自然地告訴他說我們不接收贓物。這裡可是暴風城的拍賣場，而不是什麼黑街暗巷裡烏煙瘴氣的跳蚤市場!', `MaleText_loc7`='Como es natural, le dije que no comerciamos con objetos robados. ¡Esta es la Casa de subastas de Ventormenta, no una apestosa tienda de segunda mano en un callejón!' WHERE `ID`=52640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말이십니까, 옴누론 님? 우리도 이번 전투에 참여하는 건가요?', `FemaleText_loc4`='我没听错吧，欧穆隆？我们要参战了？', `FemaleText_loc5`='我沒聽錯吧，歐姆奴隆?我們要加入戰鬥?', `FemaleText_loc7`='¿He oído bien, Omnuron? ¿Vamos a unirnos a la lucha?' WHERE `ID`=52641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 저를 설득하실 필요 없습니다, $n 님. 갈퀴발톱의 드루이드는 그대를 도울 것입니다.', `MaleText_loc4`='你已经说服我了，$n。猛禽德鲁伊愿意帮助你。', `MaleText_loc5`='不用再繼續說服我了，$n。猛禽德魯伊願意為你提供幫助。', `MaleText_loc7`='No necesito que me convenzas más, $n. Los Druidas de la Garfa te ayudarán.' WHERE `ID`=52642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 티살리. 병력을 소집해라. 즉시 녹아내린 전초지로 떠나야 한다.', `MaleText_loc4`='是的，希萨莉。把我们的人召集起来。我们立刻开赴熔火前线。', `MaleText_loc5`='是的，黎沙莉。集結我們的部隊。我們立刻前往熔岩前線。', `MaleText_loc7`='Sí, Thisalee. Reúne a nuestras fuerzas. Partimos hacia el Frente de Magma inmediatamente.' WHERE `ID`=52643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기다리고 있었습니다.', `FemaleText_loc4`='我想我会喜欢的。', `FemaleText_loc5`='這一定很有趣。', `FemaleText_loc7`='Voy a disfrutar esto mucho.' WHERE `ID`=52644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s|1이;가; |c0087CEFA|Hspell:98374|h[표범]|h|r으로 변신합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s变形成|c0087CEFA|Hspell:98374|h[猎豹]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s變形為一隻|c0087CEFA|Hspell:98374|h[獵豹]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_druid_tigersroar.blp:20|t¡%s se transforma en un |c0087CEFA|Hspell:98374|h[Felino]|h|r!' WHERE `ID`=52645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s|1이;가; |c0087CEFA|Hspell:98379|h[전갈]|h|r로 변신합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s变形成|c0087CEFA|Hspell:98379|h[蝎子]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s變形為一隻|c0087CEFA|Hspell:98379|h[蠍子]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_mount_hordescorpiong.blp:20|t¡%s se transforma en un |c0087CEFA|Hspell:98379|h[Escorpión]|h|r!' WHERE `ID`=52646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 원래 임무는 이 땅을 수호하는 것입니다만, 판드랄이 정말로 불의 땅으로 도망쳤다면, 가서 그에게 심판을 내려야 합니다.', `FemaleText_loc4`='我们的天职要求我们守好这片土地。可如果范达尔真的逃进了火焰之地，那我们必须将他绳之以法。', `FemaleText_loc5`='我們原本的任務是防禦這片土地，但如果范達爾真的逃到火源之界了，那我們就必須把他繩之以法。', `FemaleText_loc7`='Nuestro deber original nos obliga a defender esta tierra, pero si Fandral ha huido a las Tierras de Fuego, entonces debemos llevarlo ante la justicia.' WHERE `ID`=52647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자매들이여, 모습을 드러내세요. 눈에 띄지 말아야 할 시기는 지났습니다. 불의 세계에서 적과 맞서야 합니다.', `FemaleText_loc4`='姐妹们，显身吧。隐藏的时刻已经过去了。我们要去火焰之地对付敌人。', `FemaleText_loc5`='姊妹們，現身吧。現在已經無需隱藏了。我們就在火焰界域面對我們的敵人。', `FemaleText_loc7`='Hermanas, muéstrense. El tiempo para sutilezas ha pasado. Nos enfrentaremos a nuestros enemigos en el plano del Fuego.' WHERE `ID`=52648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장에서 만납시다, $G형제:자매;여.', `FemaleText_loc4`='我们战场上见，$G兄弟:姐妹;。', `FemaleText_loc5`='在戰場上見，$G兄弟:姊妹;。', `FemaleText_loc7`='Te veré en el campo de batalla, $ghermano:hermana;.' WHERE `ID`=52649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 필멸자들아... 주인님의 요새는 금지된 곳이다...', `MaleText_loc4`='污秽的凡人……不能进入主人的城堡……', `MaleText_loc5`='骯髒的凡人...不准進入主人的要塞...', `MaleText_loc7`='Escoria mortal... la fortaleza del maestro está prohibida...' WHERE `ID`=52650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고엘은 어째서 가만히 서 있기만 할까요? 우리가 그의 코앞에서 적과 싸우고 있는데?', `FemaleText_loc4`='他怎么能就站在那儿，眼睁睁地看着我们击退他脚下的进攻者？', `FemaleText_loc5`='他怎麼可以就站在那裡，眼睜睜地看著我們在他腳下跟敵人作戰?', `FemaleText_loc7`='¿Cómo puede quedarse ahí PARADO mientras nosotros luchamos contra los atacantes delante de sus narices?' WHERE `ID`=52651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='단단히 준비하세요. 불의 땅은 위험한 곳입니다... 당신처럼 굳센 $r에게도 말이지요.$b$b준비되면 알려 주세요.', `FemaleText_loc4`='做好准备。火焰之地非常危险……即使是像你这样强大的$r也不能掉以轻心。$b$b你准备好之后，就告诉我一声。', `FemaleText_loc5`='做好準備。火源之界是個危險的地方...即使對你這麼強大的$r來說也一樣。$b$b等你準備好了跟我說一聲。', `FemaleText_loc7`='Prepárate. Las Tierras de Fuego son un lugar peligroso... Incluso para $gun:una; $r tan fuerte como tú.$b$bAvísame cuando quieras partir.' WHERE `ID`=52652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 불의 땅으로 가서 이 모든 것을 끝냅시다.', `MaleText_loc4`='我准备好了。让我们前往火焰之地，了结这一切吧。', `MaleText_loc5`='我準備好了。咱們前往火源之界為這一切做個了斷吧。', `MaleText_loc7`='Estoy preparado. Vamos a las Tierras de Fuego y acabemos con esto.', `FemaleText_loc1`='준비됐습니다. 불의 땅으로 가서 이 모든 것을 끝냅시다.', `FemaleText_loc4`='我准备好了。让我们前往火焰之地，了结这一切吧。', `FemaleText_loc5`='我準備好了。咱們前往火源之界為這一切做個了斷吧。', `FemaleText_loc7`='Estoy preparada. Vamos a las Tierras de Fuego y acabemos con esto.' WHERE `ID`=52653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 생각보다 더 끔찍하군요. 지금 이 순간에도 이 땅의 분노가 절 짓누르는 게 느껴집니다.', `FemaleText_loc4`='火焰的国度比我想象的还要可怕。我能感到这个世界想要压垮我的狂怒。', `FemaleText_loc5`='這個界域比我想像中的還糟。我甚至現在都能感到此地憤怒的壓迫感。', `FemaleText_loc7`='Este reino es más terrible de lo que había imaginado. Incluso ahora, puedo sentir la ira de este lugar cerniéndose sobre mí.' WHERE `ID`=52654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적들이 금방 이리로 몰려들 겁니다. 출발하죠.', `FemaleText_loc4`='用不了多久他们就会发现我们的。开始吧。', `FemaleText_loc5`='他們很快就會找上我們。動作快。', `FemaleText_loc7`='No tendremos mucho tiempo antes de que caigan sobre nosotros. Empecemos.' WHERE `ID`=52655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요! 화염에 휩싸인 그가 보입니다! 그의 깊은 곳에서 뿜어 나오는 분노가 느껴집니다... 오, 이 분노만으로도 우리 모두 잿더미가 되겠어요!', `FemaleText_loc4`='那边！我看到他了，包裹在烈焰中！我能感受到他心中喷薄而出的狂怒。如此狂野……他的愤怒会将我们也烧成灰烬！', `FemaleText_loc5`='在那!被火焰包圍!我能感覺到他的核心散發的怒火。如此的怒火...可輕易把我們燒成灰燼!', `FemaleText_loc7`='¡Allí, lo veo! Coronado de fuego. Siento las oleadas de furia que irradia desde su núcleo. Tanta ira... ¡Solo su ira podría reducirnos a cenizas!' WHERE `ID`=52656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄호해 주세요. 주위에 수호 토템을 설치하겠습니다.', `FemaleText_loc4`='保护我，我会将防护图腾放置在周围。', `FemaleText_loc5`='掩護我，我會在周圍放下防護圖騰。', `FemaleText_loc7`='Protégeme y colocaré tótems guardianes a nuestro alrededor.' WHERE `ID`=52657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구신가? 우리 불의 땅에 손님들이 찾아오셨군.', `MaleText_loc4`='瞧瞧谁来了，这火焰的王国有访客了？', `MaleText_loc5`='看看這裡...我們火源之界的王國居然來了訪客?', `MaleText_loc7`='¿Qué tenemos aquí? Visitantes en nuestro reino de las Tierras de Fuego.' WHERE `ID`=52658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알리스라를 기억할지 모르겠군. 하이잘 산에서 나를 풀어 줬지. 그녀도 다시 태어났다... 화염의 존재로!', `MaleText_loc4`='凡人们，你们也许还记得奥利瑟拉，在海加尔山释放过我的绿龙。她也在烈焰中……得到了重生！', `MaleText_loc5`='你們凡人還記得艾里絲拉吧?是她在海加爾山救我出來的。她，同樣的，也已在火焰中重生了!', `MaleText_loc7`='Ustedes, mortales, quizás recuerden a Alysra, la que me liberó en el Monte Hyjal. Ella también ha renacido... ¡Renacido de las llamas!' WHERE `ID`=52659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 너희를 잿더미로 만드는 모습을 지켜보고 싶지만, 급히 갈 곳이 있어서 말이야. 잘 있으라고!', `MaleText_loc4`='我真希望能亲眼看着她将你们这群可怜的家伙烧成灰烬，但我还有别的事情要忙。永别了！', `MaleText_loc5`='我也想目睹你們這些可悲的蟲子化為灰燼，但別處還需要我。再會了!', `MaleText_loc7`='Ojalá pudiera quedarme a ver cómo reduce su patética banda a cenizas, pero me necesitan en otro sitio. ¡Adiós!' WHERE `ID`=52660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자꾸 질문을 피하지 마십시오, 퀸시! 상자를 훔친 그자가 여기 온 적이 있다는 사실을 다 알고 있습니다.', `MaleText_loc4`='别再躲躲闪闪的了，昆西！我知道那个贼和那个箱子就在这儿。', `MaleText_loc5`='別再逃避問題了，昆西!我知道那個賊帶了箱子來過這裡。', `MaleText_loc7`='¡Deja de evitar la pregunta, Quincy! Sé que el ladrón estuvo aquí con un cajón.' WHERE `ID`=52661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 상자 안에 든 물건은 아주 위험합니다. 무식하고 돈만 많은 수집가의 손이 아니라 튼튼한 금고 안에 보관되어야 할 물건이란 말입니다!', `MaleText_loc4`='那个箱子里的东西非常危险。它们都来自一个守卫森严的库房，可不是从某个愚昧的暴发户收藏家那里偷来的！', `MaleText_loc5`='那個箱子裡面的東西非常危險，應該放在安全的保險櫃裡，而不是在某些有錢但是無知的收藏家手裡!', `MaleText_loc7`='¡El contenido de ese cajón es muy peligroso y debería estar guardado en una cámara de seguridad, no en manos de un coleccionista forrado de pasta pero ignorante!' WHERE `ID`=52662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리 좀 낮춰주게, 응? 장사 좀 하자고...', `MaleText_loc4`='拜托，别吵了。我还要做生意呢……', `MaleText_loc5`='安靜點好嗎?我這裡還得做生意勒...', `MaleText_loc7`='Baja la voz, ¿quieres? Estoy intentando llevar un negocio...' WHERE `ID`=52663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 상자 어쩌고저쩌고하는 일을 없던 일로 해준다면, 내가 울둠에서 막 도착한 물건들을 싸게 내주지.', `MaleText_loc4`='如果你肯忘记这箱东西，我可以用最优惠的价格，卖给你几件奥丹姆的新货。', `MaleText_loc5`='如果你願意忘記這個箱子的事情，我可以給你一些奧丹姆剛到貨的新玩意兒打點折。', `MaleText_loc7`='Si estás dispuesto a olvidar todo esto del cajón, puedo ofrecerte un buen precio sobre las últimas novedades recién llegadas de Uldum.' WHERE `ID`=52664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네, 알았어. 내가 그자에게 상자 안에 든 물건에 관심을 보일법한 개인 수집가의 이름을 알려준 것 같기도 하군.', `MaleText_loc4`='好啦，好啦。我好像是跟他说过，有个私人收藏家可能对那个箱子里的东西有兴趣的来着。', `MaleText_loc5`='好啦好啦。我是有介紹給他一個對那個箱子裡的東西有興趣的私人收藏家。', `MaleText_loc7`='Está bien, está bien. Quizá le diera el nombre de un coleccionista privado interesado en el contenido de ese cajón.' WHERE `ID`=52665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병이 찾아오면 저기 있는 울둠 유물이나 훌륭한 그림을 어떻게 얻었는지 잘 설명할 자신이 있으신가 보군요?', `MaleText_loc4`='等警卫来找你谈话的时候，但愿你能解释清楚那些奥丹姆遗物，或者那副漂亮的画作的来历。', `MaleText_loc5`='等守衛來找你時，我想你應該可以解釋你是怎麼拿到那些奧丹姆神器或那幅漂亮的畫。', `MaleText_loc7`='Cuando los guardias vengan a verte, estoy seguro de que no tendrás ningún problema para explicarles cómo te hiciste con esos artefactos de Uldum o con ese encantador cuadro.' WHERE `ID`=52666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $c|1이여;여;. 우리는 오래전 오늘 같은 날이 올 것을 알았고, 이미 준비를 마쳤다.', `MaleText_loc4`='是的，$c。我们早就预见到了这一天，而且已经做好了准备。', `MaleText_loc5`='是的，$c。我們很久以前已經預見到這一刻的來臨，而且我們已經做好準備。', `MaleText_loc7`='Sí, $c. Hace mucho que previmos este día y estamos preparados.' WHERE `ID`=52667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 승리하게 내버려둬서는 안 된다. 데스윙이 이 전쟁에서 승리한다면, 모든 생명체가 소멸할 것이다.', `MaleText_loc4`='我们不能让死亡之翼得逞。如果让他赢得了这场战争，那整个世界都将生灵涂炭。', `MaleText_loc5`='不能讓死亡之翼獲勝。如果他在這場戰爭中勝利，將會生靈塗炭。', `MaleText_loc7`='No podemos permitir que gane Alamuerte. Si él se alzara triunfal, sería el final de toda vida.' WHERE `ID`=52668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오라, 수호자들이여! 이번 전투에서는 고대정령의 힘이 우리에게 가세했다! 이제 우리는 절대로 쓰러지지 않으리라!', `MaleText_loc4`='保护者们，集合起来吧！我们要运用古树的力量赢得这场战争！我们决不能失败！', `MaleText_loc5`='來吧，保衛者們。將先祖的力量借給這場戰爭!我們絕對不會失敗的!', `MaleText_loc7`='¡Vamos, protectores! ¡Traemos la fuerza de los ancestros a esta batalla! ¡Y no caeremos!' WHERE `ID`=52669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 실토하시는군요. 거기 새로 오신 분, 어떻습니까? 당신도 역시 그 상자를 찾는 중이니 이곳으로 온 걸 텐데요.', `MaleText_loc4`='这只是个开始。那么你呢，新来的？要不是为了追查那个箱子，你也不会到这儿来了吧？', `MaleText_loc5`='這才像話。新來的，你呢?如果不是為了那個箱子，你也不會來這裡吧?', `MaleText_loc7`='Es un comienzo. ¿Y qué hay de ti, eh? No estarías aquí si no buscaras también ese cajón.' WHERE `ID`=52670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라...', `MaleText_loc4`='阿格娜……$n……', `MaleText_loc5`='阿格拉...$n...', `MaleText_loc7`='Aggra... eres tú...' WHERE `ID`=52673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='딱 맞춰 왔군요, 리켓. $n 님이 녹아내린 전초지에서 그대 도움이 필요하다고 합니다.', `FemaleText_loc4`='你来的正好，莉吉特。$n说，熔火前线需要你的专业知识帮忙。', `FemaleText_loc5`='來得好，瑞基特。$n說在熔岩前線那裡需要你的專長。', `FemaleText_loc7`='Llegas a tiempo, Ricket. $n dice que necesitan tu pericia en el Frente de Magma.' WHERE `ID`=52674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아우! 시험생산 제품도 제대로 작동하지 않는 모양이네요.', `FemaleText_loc4`='哎呀！好吧，我估计那个设备也没法运转了。', `FemaleText_loc5`='噢!看來那個原型也壞了。', `FemaleText_loc7`='¡Vaya! Bueno, supongo que ese prototipo tampoco funcionó.' WHERE `ID`=52675;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 불과 맞서 싸우려면... 초 가연성 무기 폭약이 딱 맞죠!', `FemaleText_loc4`='哇，太棒啦！是时候让那些火元素尝尝……高度易燃的爆炸类武器的厉害啦！', `FemaleText_loc5`='喔讚啦!是時候用...高度易燃爆炸的東西來應付火焰了!', `FemaleText_loc7`='¡Estupendo! Es el momento de combatir el fuego con... ¡armas y explosivos altamente inflamables!' WHERE `ID`=52676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오실 줄 알았습니다. 정말 끈질기시군요. 짜증이 날 정도로요.', `FemaleText_loc4`='我知道你会来。你真顽强，顽强得令人讨厌。', `FemaleText_loc5`='我就知道你會來。你的堅持我看到了，相當煩人。', `FemaleText_loc7`='Imaginé que vendrías. Has demostrado ser muy persistente. Me molesta.' WHERE `ID`=52677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 사라져 주셔야겠습니다.', `FemaleText_loc4`='是时候除掉你了。', `FemaleText_loc5`='是時候消滅你了。', `FemaleText_loc7`='Es hora de librarme de ti.' WHERE `ID`=52678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판드랄 님은 진정한 지도자셨지만, 당신은 몽상가일 뿐이야.', `FemaleText_loc4`='范达尔是个真正的领袖。而你不过是个绝望之梦。', `FemaleText_loc5`='范達爾是個真正的領袖。你不過是個絕望的夢境。', `FemaleText_loc7`='Fandral era un líder de verdad. Tú no eres más que un sueño desesperado.' WHERE `ID`=52679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누군가를 이끌어 나갈 힘이 없지.', `FemaleText_loc4`='你没有力量领导任何人。', `FemaleText_loc5`='你沒有領導任何人的力量。', `FemaleText_loc7`='No posees la fuerza para liderar a nadie.' WHERE `ID`=52680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조만간 모두가 그 약점을 알아챌 겁니다, "샨도."', `FemaleText_loc4`='他们很快就会看穿你的弱点，“大导师”。', `FemaleText_loc5`='他們很快便會見識到你的無力，「尊師」。', `FemaleText_loc7`='Pronto, todos verán a través de tus debilidades, "shan''do".' WHERE `ID`=52681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나에겐 상상도 못할 힘이 있습니다, 말퓨리온.', `FemaleText_loc4`='我拥有你从未知晓的力量，玛法里奥。', `FemaleText_loc5`='我擁有你無法掌握的力量，瑪法里恩。', `FemaleText_loc7`='No te imaginas el poder que tengo, Malfurion.' WHERE `ID`=52682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하뮬을 처치했듯이 당신의 동료도 없애겠습니다. 나를 막을 방법은 없습니다.', `FemaleText_loc4`='我会杀掉你的同伴，就如同我杀死哈缪尔。而你对此无能为力。', `FemaleText_loc5`='我會像殺了哈繆爾一樣殺了你的同伴，而你會一籌莫展。', `FemaleText_loc7`='Mataré a tu compañero igual que maté a Hamuul. Y no hay nada que puedas hacer al respecto.' WHERE `ID`=52683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테나론, 옛 친구여. 여기 $c님을 위해 달샘 물을 약병에 채워다 주겠어요?', `FemaleText_loc4`='特纳隆老伙计，你能去帮这位$c收集一瓶月井之水来吗？', `FemaleText_loc5`='特納隆，老朋友。你能為這位$c帶瓶月井之水回來嗎?', `FemaleText_loc7`='Tenaron, viejo amigo. ¿Te importaría recoger un vial de agua de la Poza de la Luna para $geste:esta; $c?' WHERE `ID`=52684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿을 수 없어! 생명을 완전히 불태웠는데!', `FemaleText_loc4`='我不相信！我本已将你的生命烧干了！', `FemaleText_loc5`='這不可能!我燒乾了你的生命能量!', `FemaleText_loc7`='¡No puede ser! ¡Quemé la vida de tu cuerpo!' WHERE `ID`=52685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가세요, $n. 최전선으로 다시 돌아가면 달샘이 가득 차 있을 거예요.', `FemaleText_loc4`='去吧，$n。当你回到前线的时候，月井应该已经满溢了。', `FemaleText_loc5`='去吧，$n。等你回到前線時，月井應該已經被注滿了。', `FemaleText_loc7`='Ve, $n. La Poza de la Luna estará llena para cuando regreses al frente.' WHERE `ID`=52686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 그러겠습니다, 마토클로.', `MaleText_loc4`='这是我的荣幸，麦托克劳。', `MaleText_loc5`='這是我的榮幸，瑪托克勞。', `MaleText_loc7`='Será un placer, Matogarra.' WHERE `ID`=52687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 널 상대하러 왔다, 레이아라.', `MaleText_loc4`='我为你而来，莱雅娜。', `MaleText_loc5`='而我為你而來，雷亞拉。', `MaleText_loc7`='Y he venido por ti, Leyara.' WHERE `ID`=52688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 운명의 사슬을 끊어 주마. 저 세상에선... 부디 평안하길.', `MaleText_loc4`='我会让你获得解脱。愿你能在死后得到安宁。', `MaleText_loc5`='我從這樣的命運中釋放你。願妳能在死亡中獲得解脫。', `MaleText_loc7`='Te libero de este destino. Ojalá encuentres la paz en la muerte.' WHERE `ID`=52689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다. 제가 좀 늦었습니다. 뭐, 저 없이도 잘하고 계셨네요.', `MaleText_loc4`='抱歉我没能早点赶到，虽然一切似乎都在你的掌握之中。', `MaleText_loc5`='很抱歉我無法更早到達，不過你似乎處理得還不錯。', `MaleText_loc7`='Siento no haber llegado antes, aunque parece ser que te las has arreglado muy bien.' WHERE `ID`=52690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지에서 다시 만나세.', `MaleText_loc4`='我们回营地汇合。', `MaleText_loc5`='我們之後在營地見。', `MaleText_loc7`='Nos reuniremos en el campamento.' WHERE `ID`=52691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이아라, 판드랄은 이제 구제할 수 없다. 그는 네가 아는 것보다 더 깊이 타락했다.', `MaleText_loc4`='莱雅娜，你必须明白范达尔已经无法救赎了。他受到的腐蚀比你想象的还深。', `MaleText_loc5`='雷亞拉，妳必須了解到范達爾已經無可救藥。他腐化的深度已遠超過妳的想像。', `MaleText_loc7`='Leyara, debes comprender que Fandral no tiene redención. La corrupción es más profunda en él que en ti.' WHERE `ID`=52692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하뮬은 죽지 않았다, 레이아라. 그는 살아있다.', `MaleText_loc4`='你没有杀死哈缪尔。他还活着。', `MaleText_loc5`='你沒有殺死哈繆爾，雷亞拉。他還活著。', `MaleText_loc7`='No mataste a Hamuul, Leyara. Está vivo.' WHERE `ID`=52693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑네, 하뮬. 이곳을 떠나세.', `MaleText_loc4`='欢迎回来，哈缪尔。我们离开这个地方吧。', `MaleText_loc5`='歡迎你回來，哈繆爾。我們離開這裡吧。', `MaleText_loc7`='Me alegra verte de vuelta, Hamuul. Abandonemos este lugar.' WHERE `ID`=52694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와!', `MaleText_loc4`='哇啊！', `MaleText_loc5`='呀呼!!', `MaleText_loc7`='¡Yujuuuu!' WHERE `ID`=52695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $p! 저를 많이 도와주셨다고 아빠한테 말씀드릴게요!', `MaleText_loc4`='谢谢你，$p！我要告诉爸爸，说你带我出来见了世面！', `MaleText_loc5`='謝謝，$p!我會告訴我老爸你幫我開了眼界!', `MaleText_loc7`='¡Gracias, $p! ¡Le diré a mi padre que me ayudaste a ver el mundo!' WHERE `ID`=52696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단해요!', `MaleText_loc4`='真是太棒了！', `MaleText_loc5`='這太棒了!', `MaleText_loc7`='¡Esto es genial!' WHERE `ID`=52697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고예요, $p!', `MaleText_loc4`='你真了不起，$p！', `MaleText_loc5`='你最讚了，$p!', `MaleText_loc7`='¡Eres lo más, $p!' WHERE `ID`=52698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불청객이 찾아오셨군.', `FemaleText_loc4`='这里不欢迎你们。', `FemaleText_loc5`='你來到不歡迎你的地方了。', `FemaleText_loc7`='Aquí no recibirás bienvenida alguna.' WHERE `ID`=52699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 오직 불과 유황과 죽음뿐.', `FemaleText_loc4`='这里只有火焰，硫磺，还有死亡。', `FemaleText_loc5`='這裡只有火焰、硫磺和死亡。', `FemaleText_loc7`='Aquí solo hay fuego, azufre y muerte.' WHERE `ID`=52700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 명분은 어리석고 헛되다. 사랑하는 이를 지켜 줄 힘조차 없지.', `FemaleText_loc4`='你的举动愚蠢而徒劳。你没有力量去守护你最珍视的人。', `FemaleText_loc5`='你的目標愚蠢而白費心機。你沒有力量保護你在乎的人。', `FemaleText_loc7`='Tu causa es estúpida y fútil. No posees la fuerza para aferrarte a los que te son queridos.' WHERE `ID`=52701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약한 것. 불쌍해. 네 목숨을 가져가 주지. 하지만 그전에 네가 사랑하는 모든 걸 불태우겠다.', `FemaleText_loc4`='你虚弱而可悲。你所爱的人会被烈焰烧尽，你的生命将弃你而去。', `FemaleText_loc5`='你很脆弱、可悲。等到你鍾愛的一切被燒光之後，你的生命也會被奪走。', `FemaleText_loc7`='Eres débil. Patético. Te arrebataremos la vida, pero solo después de que arda todo lo que amas.' WHERE `ID`=52702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너를 기다리는 건 아무것도 없다. 아무것도.', `FemaleText_loc4`='等待你的只有虚无。无尽空虚。', `FemaleText_loc5`='在盡頭等待你的是空虛。空洞。', `FemaleText_loc7`='Lo único que te aguarda es la nada. El vacío.' WHERE `ID`=52703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 모두 널 버렸어. 죽게 내버려뒀지.', `FemaleText_loc4`='他们已经抛弃了你。留你独自受死。', `FemaleText_loc5`='他們都遺棄你了，任你自生自滅。', `FemaleText_loc7`='Todos te han abandonado. Para que mueras.' WHERE `ID`=52704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도움이 가장 절실한 순간, 버림받을 거야. 그리고 넌 불타겠지.', `FemaleText_loc4`='他们会在你最需要之时抛弃你。他们会看着你被烧死。', `FemaleText_loc5`='他們會在你最需要幫助時遺棄你，讓你燒成灰燼。', `FemaleText_loc7`='Te abandonarán cuando más los necesites. Te dejarán para que ardas.' WHERE `ID`=52705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너에겐 아무도 없어, 아무도.', `FemaleText_loc4`='你一无所有，一无所有。', `FemaleText_loc5`='沒人會幫你。沒有人!', `FemaleText_loc7`='No tienes nada. A nadie.' WHERE `ID`=52706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 힘을 몰라. 절박한 마음에 동맹에 손을 뻗어 보지만, 그들은 널 구할 수 없어.', `FemaleText_loc4`='你对力量一无所知。你在绝望中寻求同伴，但他们救不了你。', `FemaleText_loc5`='你不瞭解什麼是力量。你渴望盟友的幫助，但他們幫不了你。', `FemaleText_loc7`='No sabes nada del poder. En tu desesperación te aferras a tus aliados, pero no pueden salvarte.' WHERE `ID`=52707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유일한 희망은, 모두 함께 불타는 것. 너에게 승리란 없어.', `FemaleText_loc4`='你只能奢望与他们一起被烧死。你们没有胜利的可能。', `FemaleText_loc5`='你只能期望燒死在一起。勝利並不存在。', `FemaleText_loc7`='Tu único consuelo es que todos arderán juntos. No hay victoria para ti.' WHERE `ID`=52708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_mace_2h_sulfuras_d_01.blp:20|t%s|1이;가; |cFFFF6600|Hspell:100604|h[설퍼라스 강화]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_mace_2h_sulfuras_d_01.blp:20|t%s开始施放|cFFFF6600|Hspell:100604|h[强化萨弗拉斯]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_mace_2h_sulfuras_d_01.blp:20|t%s開始施放|cFFFF6600|Hspell:100604|h[強化薩弗拉斯]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_mace_2h_sulfuras_d_01.blp:20|t¡%s comienza a lanzar |cFFFF6600|Hspell:100604|h[Potenciar a Sulfuras]|h|r!' WHERE `ID`=52709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대마법사 실렘 님은 깡패와는 거래하지 않으신다. 너 따위에게 돈을 줄 것 같으냐!', `MaleText_loc4`='大法师克希雷姆可不会跟你这种人讨价还价，恶棍！不给就是不给！', `MaleText_loc5`='大法師克希雷姆不會跟你這種惡棍討價還價。我們不會付錢的!', `MaleText_loc7`='El archimago Xylem no hace tratos con los de tu calaña, granuja. ¡No habrá ningún pago!' WHERE `ID`=52710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야, 침입자잖아? 어디, 이 상자 안에 든 유물에 어떤 힘이 있는지 볼까?', `MaleText_loc4`='这是什么，一个闯入者？让我们来看看这个箱子里的遗物有什么作用，如何？', `MaleText_loc5`='那裡來的不速之客?讓我們來看看箱子裡面的神器有什麼功用，如何?', `MaleText_loc7`='¿Qué es esto, $gun intruso:una intrusa;? Veamos lo que pueden hacer los artefactos que hay en esta caja, ¿de acuerdo?' WHERE `ID`=52711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주변의 아군을 즉시 죽입니다!', `MaleText_loc4`='%s秒杀了附近所有的盟友！', `MaleText_loc5`='%s瞬間殺光周圍的盟友!', `MaleText_loc7`='¡%s mata a todos los aliados cercanos de forma instantánea!', `FemaleText_loc1`='%s|1이;가; 주변의 아군을 즉시 죽입니다!', `FemaleText_loc4`='%s秒杀了附近所有的盟友！', `FemaleText_loc5`='%s瞬間殺光周圍的盟友!', `FemaleText_loc7`='¡%s mata a todos los aliados cercanos de forma instantánea!' WHERE `ID`=52712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 연기 나는 무더기로 스러집니다...', `MaleText_loc4`='%s倒地后化为一堆灼热的碎片……', `MaleText_loc5`='%s潰成一堆燃燼...', `MaleText_loc7`='%s se derrumba y se convierte en un montón de brasas...' WHERE `ID`=52713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 되살아나더니 주인을 보호하려고 전투에 뛰어듭니다!', `MaleText_loc4`='%s再次充满力量并投入战斗，以保护他的主人！', `MaleText_loc5`='為了保護主人，%s活化重生、衝進戰局之中!', `MaleText_loc7`='¡%s se reanima y se lanza a la batalla para proteger a su maestro!' WHERE `ID`=52714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여부가 있겠나. 내 지식을 공유해주겠다.', `FemaleText_loc4`='当然，我会和你分享我的智慧。', `FemaleText_loc5`='當然，我會把我的知識與你分享。', `FemaleText_loc7`='Por supuesto que compartiré mis conocimientos contigo.' WHERE `ID`=52715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말퓨리온 님이 너의 할아버지를 가두지만 않았어도. 호드가 쳐들어온 마당에 지하굴에 갇혀 계시단다.', `FemaleText_loc4`='玛法里奥将你的祖父关进了监狱。部落攻击灰谷时，他只能在兽穴里等死。', `FemaleText_loc5`='瑪法里恩沒有把你祖父關起來就好了。部落襲擊梣谷的時候他被關在一個山洞裡。', `FemaleText_loc7`='Ojalá Malfurion no hubiera encerrado a tu abuelo en prisión. Se pudre en un túmulo mientras la Horda asalta Vallefresno.' WHERE `ID`=52716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 될 리가 없는데!', `MaleText_loc4`='这不可能！', `MaleText_loc5`='不應該這樣才對啊!', `MaleText_loc7`='¡Esto no tenía que pasar!' WHERE `ID`=52717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑군요, 반즈 씨. 상자는 가져오셨습니까?', `MaleText_loc4`='很高兴再次见到你，巴恩斯先生。那个箱子在你手里吗？', `MaleText_loc5`='真高興再見到你，巴奈斯先生。你拿到箱子了嗎?', `MaleText_loc7`='Me alegra volver a verte, Sr. Barnes. ¿Tienes el cajón?' WHERE `ID`=52718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. $n|1이;가; 방금 가지고 돌아왔지요. 그런데 제값을 치러주기는 하실 겁니까?', `MaleText_loc4`='没错。$n刚把它送了回来，但我怎么能肯定你一定会信守诺言呢？', `MaleText_loc5`='是的在我這。$n才剛帶來給我，不過我怎麼知道你會不會遵守約定?', `MaleText_loc7`='Lo tengo. $n acaba de traerlo, ¿pero cómo sé que cumplirás con tu parte del trato?' WHERE `ID`=52719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부적이 하나 있는데, 상자를 넘겨주면 그 부적의 힘을 해방해 드리겠습니다. 마음 바꾸길 정말 잘하신 겁니다, 반즈 씨.', `MaleText_loc4`='我已经把护符带来了。只要一拿到箱子，我就释放它的力量。你肯改变主意是个很明智的决定，巴恩斯。', `MaleText_loc5`='符咒在我身上，只要把箱子交給我，我就會解開符咒的力量。巴奈斯，改變主意是件明智之舉。', `MaleText_loc7`='Tengo el talismán conmigo y desbloquearé su poder en cuanto el cajón esté en mis manos. Hiciste bien en cambiar de opinión, Barnes.' WHERE `ID`=52720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 부적만 있으면 해를 입을 걱정 없이 몰래 카라잔에 들어갈 수 있습니다. 당신이 그 탑 안에서 무엇을 밝혀낼지 해리슨 존스라고 해도 모를 겁니다.', `MaleText_loc4`='有了它，你就可以躲过探测，毫发无伤地进入卡拉赞。连哈里森·琼斯都猜不到你是如何发掘出这座塔的历史的。', `MaleText_loc5`='只要有了這個，你就能夠進入卡拉贊，不用害怕受到傷害或是被偵測到行蹤。就算是哈里遜·瓊斯也不會知道你是如何知道那座塔的歷史。', `MaleText_loc7`='Con él, podrás entrar en Karazhan sin miedo a sufrir ningún daño o a que te detecten. Ni siquiera Harrison Jones sabrá cómo descubriste la historia de la torre.' WHERE `ID`=52721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 부디 상자를 받으십시오. 카라잔 도서관 안에 무엇이 있을지 벌써 가슴이 두근거리는군요!', `MaleText_loc4`='这是箱子，请拿好。我已经开始想象，自己能在塔里的图书馆发现些什么了！', `MaleText_loc5`='來吧，請收下箱子。我已經在想像在那座塔的圖書館中，我會發現些什麼東西了!', `MaleText_loc7`='Por favor, coge el cajón. ¡Ya me estoy imaginando lo que encontraré en la biblioteca de la torre!' WHERE `ID`=52722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 이날을 기다렸지. 내가 변신하는 걸 봐라!', `MaleText_loc4`='为了这一天，我已经等待了好几年了。看看我的新造型！', `MaleText_loc5`='我等這天已經等了數年之久，讓你瞧瞧我的變形!', `MaleText_loc7`='He estado esperando esto durante años. ¡Contempla mi transformación!' WHERE `ID`=52723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이얏호!', `FemaleText_loc4`='呀！', `FemaleText_loc5`='喔耶!', `FemaleText_loc7`='¡Ueee!' WHERE `ID`=52724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단해요!', `FemaleText_loc4`='这太神奇了！', `FemaleText_loc5`='真是太棒了!', `FemaleText_loc7`='¡Esto es maravilloso!' WHERE `ID`=52725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기에 올라오니까 전부 다 보여요!', `FemaleText_loc4`='站在这儿，什么都能看见！', `FemaleText_loc5`='在這裡望去，所有景色盡收眼底!', `FemaleText_loc7`='¡Lo puedo ver todo desde aquí arriba!' WHERE `ID`=52726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕히 계세요, $p! 고마워요!', `FemaleText_loc4`='再见，$p！谢谢你！', `FemaleText_loc5`='再見，$p!謝謝你!', `FemaleText_loc7`='¡Adiós, $p! ¡Gracias!' WHERE `ID`=52727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 눈에 띄게 행동하진 않으셨겠죠, $n 님? 이 상자 안에 든 물건은 대대로 우리 가족에게 아주 중요한 물건이었습니다.', `MaleText_loc4`='希望这不会给你添太多麻烦，$n。但这个箱子里的东西是祖传的，对我的家族至关重要。', `MaleText_loc5`='我希望你不會太過慍怒，$n，不過箱子裡面裝的東西，在數世紀以來對我的家族一直都相當重要。', `MaleText_loc7`='Espero que no te hayas molestado demasiado, $n, pero el contenido de este cajón ha sido muy importante para mi familia durante generaciones.' WHERE `ID`=52730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랫동안 이 순간을 기다려왔다, $n. 당신 덕분에 그 노력이 오늘 결실을 보는군. 자... 내가 변신하는 모습을 똑똑히 지켜봐라!', `MaleText_loc4`='为了这一天，我已经等待了好几年了，$n。是你帮我实现了它。现在，看看我的新造型吧！', `MaleText_loc5`='我為這一刻準備了好多年了，$n，是你讓我的夢想有機會成真。目睹我的變形吧!', `MaleText_loc7`='He estado preparándome para este momento durante años, $n, y tú lo has hecho todo posible. ¡Observa mi transformación!' WHERE `ID`=52731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경매인 피치에게 물어보세요!', `FemaleText_loc4`='审讯拍卖师费奇！', `FemaleText_loc5`='質問拍賣師費奇!', `FemaleText_loc7`='¡Interroga al subastador Fitch!' WHERE `ID`=52732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<비전 수호병이 현자의 도서관을 가리킵니다.>', `MaleText_loc4`='<奥术守护者指了指先知的图书馆。>', `MaleText_loc5`='<秘法守護者指向先知書庫。>', `MaleText_loc7`='<El guardián Arcano hace un gesto hacia la Biblioteca del Profeta.>' WHERE `ID`=52733;
