UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주님을 위해...', `MaleText_loc4`='为您效劳……炎魔之王。', `MaleText_loc5`='將我獻給你...炎魔大人。', `MaleText_loc7`='Yo te sirvo... Señor del Fuego.', `FemaleText_loc1`='불의 군주님을 위해...', `FemaleText_loc4`='为您效劳……炎魔之王。', `FemaleText_loc5`='將我獻給你...炎魔大人。', `FemaleText_loc7`='Yo te sirvo... Señor del Fuego.' WHERE `ID`=52738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재에서... 재로...', `MaleText_loc4`='尘……归尘……', `MaleText_loc5`='灰燼...化為灰燼...', `MaleText_loc7`='Cenizas... a las cenizas...', `FemaleText_loc1`='재에서... 재로...', `FemaleText_loc4`='尘……归尘……', `FemaleText_loc5`='灰燼...化為灰燼...', `FemaleText_loc7`='Cenizas... a las cenizas...' WHERE `ID`=52739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 영겁의 시간 동안 불타오를 것이다!', `MaleText_loc4`='永远在烈焰中煎熬吧！', `MaleText_loc5`='願你永受燒灼之苦!', `MaleText_loc7`='¡Ojalá ardas para toda la eternidad!', `FemaleText_loc1`='네놈은 영겁의 시간 동안 불타오르리라!', `FemaleText_loc4`='永远在烈焰中煎熬吧！', `FemaleText_loc5`='願你永受燒灼之苦!', `FemaleText_loc7`='¡Ojalá ardas para toda la eternidad!' WHERE `ID`=52740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것으로 우리가 멈추지는 않을 것이다...', `MaleText_loc4`='这阻止不了我们……', `MaleText_loc5`='這無法阻止我們...', `MaleText_loc7`='Esto no nos detendrá...', `FemaleText_loc1`='이것으로 우리가 멈추지는 않으리라...', `FemaleText_loc4`='这阻止不了我们……', `FemaleText_loc5`='這無法阻止我們...', `FemaleText_loc7`='Esto no nos detendrá...' WHERE `ID`=52741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 내 맨발톱으로 네놈을 없애주마!', `MaleText_loc4`='入侵者！我赤手空拳都能干掉你！', `MaleText_loc5`='入侵者死!看我用雙爪撕裂你們!', `MaleText_loc7`='¡$gIntruso:Intrusa;! ¡Te mataré con mis propias garras!', `FemaleText_loc1`='침입자다! 내 맨발톱으로 네놈을 없애주지!', `FemaleText_loc4`='入侵者！我赤手空拳都能干掉你！', `FemaleText_loc5`='入侵者死!看我用雙爪撕裂你們!', `FemaleText_loc7`='¡$gIntruso:Intrusa;! ¡Te mataré con mis propias garras!' WHERE `ID`=52742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 왕국에서 감히 우리를 시험하겠다는 건가?', `MaleText_loc4`='你竟敢在火焰的国度中挑战我们？', `MaleText_loc5`='你竟敢在火焰的界域測試我們的能力?', `MaleText_loc7`='¿Te atreves a desafiarnos en el reino del Fuego?', `FemaleText_loc1`='불의 왕국에서 감히 우리를 시험하겠다고?', `FemaleText_loc4`='你竟敢在火焰的国度中挑战我们？', `FemaleText_loc5`='你竟敢在火焰的界域測試我們的能力?', `FemaleText_loc7`='¿Te atreves a desafiarnos en el reino del Fuego?' WHERE `ID`=52743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길의 적은 이곳에서 환영받지 못한다!', `MaleText_loc4`='这里不欢迎火焰的敌人！', `MaleText_loc5`='此處不歡迎烈焰之敵!', `MaleText_loc7`='¡Los enemigos de la Llama no son bienvenidos aquí!', `FemaleText_loc1`='불길의 적은 이곳에서 환영받지 못해!', `FemaleText_loc4`='这里不欢迎火焰的敌人！', `FemaleText_loc5`='此處不歡迎烈焰之敵!', `FemaleText_loc7`='¡Los enemigos de la Llama no son bienvenidos aquí!' WHERE `ID`=52744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다! 네놈의 뼈에 붙은 살을 태워버리겠다!', `MaleText_loc4`='入侵者！我要把你的血肉都烧化掉！', `MaleText_loc5`='入侵者!看我把你連骨帶肉整個熔掉!', `MaleText_loc7`='¡$gIntruso:Intrusa;! ¡Derretiré la carne que cubre tus huesos!', `FemaleText_loc1`='침입자다! 네놈의 뼈에 붙은 살을 태워버려 주지!', `FemaleText_loc4`='入侵者！我要把你的血肉都烧化掉！', `FemaleText_loc5`='入侵者!看我把你連骨帶肉整個熔掉!', `FemaleText_loc7`='¡$gIntruso:Intrusa;! ¡Derretiré la carne que cubre tus huesos!' WHERE `ID`=52745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자는 불타 없어질 것이다.', `MaleText_loc4`='入侵者将被烈焰烧成灰。', `MaleText_loc5`='膽敢入侵之人將會化為灰燼。', `MaleText_loc7`='Los intrusos serán incinerados.', `FemaleText_loc1`='침입자는 불타 없어지리라.', `FemaleText_loc4`='入侵者将被烈焰烧成灰。', `FemaleText_loc5`='膽敢入侵之人將會化為灰燼。', `FemaleText_loc7`='Los intrusos serán incinerados.' WHERE `ID`=52746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 불의 화신에게 도전하겠다는 건가?', `MaleText_loc4`='你胆敢挑战烈焰的化身？', `MaleText_loc5`='你膽敢挑戰烈焰的化身?', `MaleText_loc7`='¿Te atreves a desafiar a las encarnaciones de la Llama?', `FemaleText_loc1`='감히 불의 화신에게 도전하겠다는 것이냐?', `FemaleText_loc4`='你胆敢挑战烈焰的化身？', `FemaleText_loc5`='你膽敢挑戰烈焰的化身?', `FemaleText_loc7`='¿Te atreves a desafiar a las encarnaciones de la Llama?' WHERE `ID`=52747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불장난하다 타 없어져 버려라, 침입자 놈아.', `MaleText_loc4`='你这是玩火自焚，入侵者。', `MaleText_loc5`='入侵者，玩火者必會自焚。', `MaleText_loc7`='Si juegas con fuego, te quemarás, $gintruso:intrusa;.', `FemaleText_loc1`='불장난하다 타버려라, 침입자 놈아.', `FemaleText_loc4`='你这是玩火自焚，入侵者。', `FemaleText_loc5`='入侵者，玩火者必會自焚。', `FemaleText_loc7`='Si juegas con fuego, te quemarás, $gintruso:intrusa;.' WHERE `ID`=52748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이단자여, 네가 사는 곳은 불타 없어질 것이다!', `MaleText_loc4`='你的世界将熊熊燃烧，异教徒！', `MaleText_loc5`='你的世界會燃燒起來，沒有信仰的傢伙!', `MaleText_loc7`='¡Tu mundo arderá, infiel!', `FemaleText_loc1`='이단자여, 네가 사는 곳은 불타 없어지리라!', `FemaleText_loc4`='你的世界将熊熊燃烧，异教徒！', `FemaleText_loc5`='你的世界會燃燒起來，沒有信仰的傢伙!', `FemaleText_loc7`='¡Tu mundo arderá, infiel!' WHERE `ID`=52749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 기다려요! 이 부적의 사용 방법은 이야기해 주지 않았잖아요!', `MaleText_loc4`='喂，等等！你还没告诉我该怎么使用这个咒符！', `MaleText_loc5`='不，等等!你還沒告訴我這個符咒該如何使用!', `MaleText_loc7`='¡No, espera! ¡Aún no me has explicado cómo se usa este talismán!' WHERE `ID`=52750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 일이지? 뜨겁잖아!', `MaleText_loc4`='我这是怎么了？好烫！', `MaleText_loc5`='發生了什麼事?燒起來了!', `MaleText_loc7`='¿Qué me está pasando? ¡Quema!' WHERE `ID`=52751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 방법은 없어요.', `FemaleText_loc4`='我别无他求。', `FemaleText_loc5`='我絕不接受別種方式。', `FemaleText_loc7`='No lo querría de otra manera.' WHERE `ID`=52752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤통수를 치는 것 같지만, 헤이스팅스 씨가 제게 도저히 거절할 수 없는 제안을 해서 말이죠. 정말 죄송합니다, $n 님.', `MaleText_loc4`='我知道这像是背信弃义，但我实在是难以拒绝哈斯廷先生的出价。真抱歉，$n。', `MaleText_loc5`='我知道這有點像是背叛，但是哈斯丁先生開出的條件讓我無法拒絕。真的很抱歉，$n。', `MaleText_loc7`='Sé que esto parece una traición, pero el Sr. Castilla me ha hecho una oferta que no puedo rechazar. Mis disculpas, $n.' WHERE `ID`=52753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아그라가 익사하려고 합니다! 그녀를 구하십시오!', `FemaleText_loc4`='阿格娜快要溺死了！救救她！', `FemaleText_loc5`='阿格拉快溺斃了!把她救出來!', `FemaleText_loc7`='¡Aggra está a punto de ahogarse! ¡Sálvala!' WHERE `ID`=52754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매인 드레즈밋에게 물어보십시오!', `MaleText_loc4`='询问拍卖师德雷泽米特！', `MaleText_loc5`='質問拍賣師德瑞伊密特!', `MaleText_loc7`='¡Interroga al subastador Drezmit!' WHERE `ID`=52755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입찰할 물건을 마음껏 골라 보라고. 가진 물건을 경매에 내놓게 도와줄 수도 있어.', `MaleText_loc4`='您可以随意浏览拍卖中的物品并出价。我还能帮你将想要出售的物品摆上拍卖架。', `MaleText_loc5`='歡迎瀏覽拍賣中的物品，或者如果你想要放東西上去拍賣，我也能幫忙。', `MaleText_loc7`='Puedes rebuscar entre los objetos que hay para subasta. También puedo ayudarte a sacar un objeto a subasta.' WHERE `ID`=52756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근 수상해 보이는 누군가가 안에 물건이 든 상자를 팔려고 한 적이 있습니까?', `MaleText_loc4`='你最近是否见过某个可疑的家伙想要出售一箱奇怪的货物？', `MaleText_loc5`='最近有沒有什麼可疑人士想要拍賣一箱什麼東西?', `MaleText_loc7`='¿Has visto a alguien de aspecto sospechoso que estuviera intentando vender un cajón de objetos hace poco?', `FemaleText_loc1`='최근 수상해 보이는 누군가가 안에 물건이 든 상자를 팔려고 한 적이 있나요?', `FemaleText_loc4`='你最近是否见过某个可疑的家伙想要出售一箱奇怪的货物？', `FemaleText_loc5`='最近有沒有什麼可疑人士想要拍賣一箱什麼東西?', `FemaleText_loc7`='¿Has visto a alguien de aspecto sospechoso que estuviera intentando vender un cajón de objetos hace poco?' WHERE `ID`=52757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매 물품을 보여주십시오.', `MaleText_loc4`='让我查看一下拍卖的物品。', `MaleText_loc5`='我來查查看拍賣物品。', `MaleText_loc7`='Déjame ver los objetos que hay para subasta.', `FemaleText_loc1`='경매 물품을 보여주세요.', `FemaleText_loc4`='让我查看一下拍卖的物品。', `FemaleText_loc5`='我來查查看拍賣物品。', `FemaleText_loc7`='Déjame ver los objetos que hay para subasta.' WHERE `ID`=52758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그런 부류와는 거래하지 않는다고! 경매장에는 정직하게 얻은 물건만 들인단 말이야.', `MaleText_loc4`='我们不会和那种家伙做生意！拍卖行里只会出售正规来路的商品。', `MaleText_loc5`='我們才不跟那種人打交道呢!拍賣場只接受來源沒問題的商品。', `MaleText_loc7`='¡Aquí no hacemos negocios con gentuza como esa! En esta casa de subasta solo aceptamos mercancía adquirida de forma honrada.' WHERE `ID`=52759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 신경 써서 찾아보면 이 동네에 나 같은 정직한 상인이 알아서는 안 될 곳이 몇 군데 있다고.', `MaleText_loc4`='好吧，听着。像我这样的人原本是不该知道这种事的，所以你得替我保守秘密。这座城里确实有那么几个……场所。', `MaleText_loc5`='嘿聽著，如果你能保密，有很多地方不是像我這種人該知道的。', `MaleText_loc7`='Mira, si sabes ser $gdiscreto:discreta;, te diré que hay unos cuantos sitios en esta ciudad que personas como yo no deberían conocer.' WHERE `ID`=52760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줄 수는 있는데, 아무에게도 이 일을 말하지 않겠다고 약속해. 비슷한 이야기만 해도 내 명성에 금이 간단 말이야!', `MaleText_loc4`='我愿意帮你的忙，但你得保证不向任何人提起这件事。哪怕只是随便聊聊这种事情也会对我的声誉造成负面影响！', `MaleText_loc5`='我很願意幫你，不過你要答應，你不會對任何人說出去。光是談論這方面的事情就已經有損我的名聲!', `MaleText_loc7`='Estoy dispuesto a ayudarte, pero debes prometerme que no le dirás nada a nadie. ¡Hasta hablar contigo sobre estas cosas podría dañar mi reputación!' WHERE `ID`=52761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘은 억눌리지 않을 것이다!', `MaleText_loc4`='我的力量不再受到束缚了！', `MaleText_loc5`='沒人能控制我的力量!', `MaleText_loc7`='¡MI PODER NO SERÁ CONTENIDO!' WHERE `ID`=52762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅으로!', `MaleText_loc4`='夷为平地！', `MaleText_loc5`='徹底地!', `MaleText_loc7`='¡AL SUELO!' WHERE `ID`=52763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에서 불타올라라!', `MaleText_loc4`='在我面前燃烧吧！', `MaleText_loc5`='在我面前燃燒吧!', `MaleText_loc7`='¡ARDAN ANTE MÍ!' WHERE `ID`=52764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타 없어져라!', `MaleText_loc4`='燃烧殆尽！', `MaleText_loc5`='燒吧!', `MaleText_loc7`='¡ARDAN!' WHERE `ID`=52765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 움직이지 않으면 내가 직접 잿가루로 만들어버리겠다!', `MaleText_loc4`='动作快，不然我会亲自把你烧成灰！', `MaleText_loc5`='快點，不然我會親自把你化為灰燼!', `MaleText_loc7`='¡Más rápido o yo mismo los convertiré en ceniza!' WHERE `ID`=52766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t 불타는 종말의 전령이 |cFFFF0000|Hspell:100761|h[재앙]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t烈焰之末使者开始施放|cFFFF0000|Hspell:100761|h[灾变流星]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t燃末信使開始施放|cFFFF0000|Hspell:100761|h[災變]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_rainoffire.blp:20|t¡Heraldo del extremo ardiente empieza a lanzar |cFFFF0000|Hspell:100761|h[Cataclismo]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t Herald of the Burning End가|cFFFF0000|Hspell:100761|h[대격변]|h|r을 시전합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t烈焰之末使者开始施放|cFFFF0000|Hspell:100761|h[灾变流星]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t燃末信使開始施放|cFFFF0000|Hspell:100761|h[災變]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shadow_rainoffire.blp:20|t¡Heraldo del extremo ardiente empieza a lanzar |cFFFF0000|Hspell:100761|h[Cataclismo]|h|r!' WHERE `ID`=52767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무능해 빠진 멍청이 같으니라고, 더 빨리 소환하란 말이다!', `MaleText_loc4`='无能的蠢货，加快召唤！', `MaleText_loc5`='無能的蠢蛋，召喚快點啊!', `MaleText_loc7`='¡Idiotas incompetentes, invocad más rápido!' WHERE `ID`=52768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 이 필멸의 존재들을 태워버릴 것이다!', `MaleText_loc4`='烈焰会吞噬那些凡人！', `MaleText_loc5`='烈焰吞噬這群凡人吧!', `MaleText_loc7`='¡Qué las llamas consuman a estos mortales!' WHERE `ID`=52769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿더미만이 남게 될 것이다!', `MaleText_loc4`='除了灰烬，什么都不会剩下！', `MaleText_loc5`='只留下一堆堆灰燼!', `MaleText_loc7`='¡No quedará nada más que un montón de ceniza!' WHERE `ID`=52770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 시전해!', `MaleText_loc4`='快点施法！', `MaleText_loc5`='施法快一點!', `MaleText_loc7`='¡Lanzen más rápido!' WHERE `ID`=52771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 필멸의 존재들이 널 죽이지 않는다면, 내가 대신 죽여줄 테다!', `MaleText_loc4`='如果那些凡人没杀掉你们，我会亲自动手！', `MaleText_loc5`='如果這些凡人沒殺了你，我也會動手!', `MaleText_loc7`='¡Si no los matan estos mortales, lo haré yo!' WHERE `ID`=52772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...그리고 내 사랑, 그대는 가서 세계를 구해야죠.', `FemaleText_loc4`='……而你，我的爱人，还要拯救一个世界。', `FemaleText_loc5`='而你呢，我的摯愛，這個世界等著你來救。', `FemaleText_loc7`='...y tú, mi amor, tienes un mundo que salvar.' WHERE `ID`=52773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토템이 멈췄습니다! 다시 활성화시키세요!', `FemaleText_loc4`='一个图腾失效了！你必须重新激活它！', `FemaleText_loc5`='一根圖騰失效了!你必須重新啟動它!', `FemaleText_loc7`='¡Un tótem está fallando! ¡Debes reactivarlo!' WHERE `ID`=52774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서, 토템을 작동시키세요!', `FemaleText_loc4`='快点，重新激活那个图腾！', `FemaleText_loc5`='快，重新啟動圖騰!', `FemaleText_loc7`='¡Rápido, reactiva el tótem!' WHERE `ID`=52775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토템을 살려야 합니다! 서둘러요!', `FemaleText_loc4`='恢复那个图腾！赶快！', `FemaleText_loc5`='別讓圖騰失效!快點!', `FemaleText_loc7`='¡Mantén los tótems activos!' WHERE `ID`=52776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르는 척 해봤자 소용없다, 드란! 그 도둑은 분명히 훔친 물건을 어디로 가져가야 하는지 알고 있었단 말이야.', `MaleText_loc4`='你不用抵赖了，德兰！那个小偷当然知道应该到什么地方来处理他的赃物。', `MaleText_loc5`='再繼續否認下去毫無意義可言，德蘭!那個竊賊很清楚該把贓物拿去哪兒。', `MaleText_loc7`='¡Es inútil negarlo, Dran! Ese ladrón sabía exactamente a dónde llevar sus objetos robados.' WHERE `ID`=52777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프 친구, 도무지 무슨 말을 하는 건지 알 수 없군. 그리고 내 일에 사사건건 참견하는 건 그다지 달갑지 않아!', `MaleText_loc4`='我不知道你在胡说些什么，精灵。另外，我非常不喜欢你对我的生意指手画脚！', `MaleText_loc5`='精靈，我不知道你在說什麼，但我可不喜歡你打探我生意的消息!', `MaleText_loc7`='¡No sé de qué estás hablando, $gelfo:elfa; y no me gusta que andes husmeando en mi negocio!' WHERE `ID`=52778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울둠에서 나온 유물을 정말이지 실수로 얻은 것 같기는 한데 말이지. 성물회가 이 물건에 관심이 있는 건가?', `MaleText_loc4`='我貌似确实不小心和某些奥丹姆发掘出的神器有过那么一些关联。难道神圣遗物学会对那些东西有兴趣？', `MaleText_loc5`='是有一些奧丹姆的文物誤入我手中。難道聖匣守護者會對這些東西感興趣?', `MaleText_loc7`='Parece que algunos objetos de Uldum han llegado a mi posesión por equivocación. ¿Quizá le interesen al Relicario?' WHERE `ID`=52779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았네, 알았어. 관심이 있는 구매자와 만나게 해줄 수는 있을 거야. 그런데 목소리는 좀 낮추라고! 손님들이 겁에 질린단 말이야.', `MaleText_loc4`='好吧，好吧。我也许帮那家伙联系过一个有意向的买家。但你能不能小声点！你会把我的顾客吓跑的。', `MaleText_loc5`='好吧好吧。我可能是有幫他聯絡有興趣的買家。但是小聲點!你會嚇到其他客人的。', `MaleText_loc7`='Está bien, está bien. Puede que le ayudara a ponerse en contacto con un comprador interesado. ¡Pero baja la voz! Vas a espantar a mis clientes.' WHERE `ID`=52780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도난당한 유물을 보면 그런트가 뭐라고 할지 한번 볼까?', `MaleText_loc4`='让我们看看那些兽人步兵对失窃的古物都知道些什么？', `MaleText_loc5`='關於這些被盜的文物，不知道蠻兵會說些什麼喔?', `MaleText_loc7`='¿Quieres saber lo que opinan los brutos de tus antigüedades robadas?' WHERE `ID`=52781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 말이 통하는군...', `MaleText_loc4`='现在我们算是有点头绪了……', `MaleText_loc5`='現在我們總算有些進展了...', `MaleText_loc7`='Por fin estamos progresando...' WHERE `ID`=52782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고, 그대는 왜 이 물건에 관심을 보이는 건가? 이야기 좀 해 보시오...', `MaleText_loc4`='还有你，你干嘛要对这些事情有兴趣？让我们单独聊聊……', `MaleText_loc5`='那你呢?讓我們來聊聊你為何對此感興趣...', `MaleText_loc7`='¿Qué hay de ti, qué sacas tú de esto? Hablemos...' WHERE `ID`=52783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주님을 실망하시게 해서는 안 된다!', `MaleText_loc4`='我们绝不能让炎魔之王失望！', `MaleText_loc5`='我們不能讓炎魔失望!', `MaleText_loc7`='¡No debemos fallarle al Señor del Fuego!' WHERE `ID`=52784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생환술사들이여, 이 마그마에 생명을 불어넣어라!', `MaleText_loc4`='塑能者，为这些熔岩注入生命！', `MaleText_loc5`='復生者，賦予岩漿生命吧!', `MaleText_loc7`='¡Animadores, haced cobrar vida a este magma!' WHERE `ID`=52785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날이 네놈의 살점을 불태워버릴 것이다!', `MaleText_loc4`='我的焰刃会烧焦你的血肉！', `MaleText_loc5`='我的刀刃將會燒黑你的血肉!', `MaleText_loc7`='¡Mi hoja abrasará tu carne!' WHERE `ID`=52786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 시전해라! 내가 놈들을 없애버리겠다.', `MaleText_loc4`='继续施法！我会处理掉那些家伙。', `MaleText_loc5`='繼續施法!我會對付這些人。', `MaleText_loc7`='¡Continuad! ¡Yo me desharé de ellos!' WHERE `ID`=52787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t 알리스라조르가 |cFFFF0000|Hspell:100744|h[화염폭풍]|h|r을 충전하기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t奥利瑟拉佐尔开始为|cFFFF0000|Hspell:100744|h[火焰风暴]|h|r充能！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t艾里絲拉卓開始累積能量準備施放|cFFFF0000|Hspell:100744|h[火焰風暴]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_stormearthfire.blp:20|t¡Alysrazor empieza a cargar una |cFFFF0000|Hspell:100744|h[Tormenta de Fuego]|h|r!' WHERE `ID`=52788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스랄을 여기서 구해내려면 모든 원소의 도움이 필요합니다. 라그나로스의 부관들은 사이클로나스나 하이드리우스는 물론, 테라제인만큼도 협조적이지 않을 테니까요.', `FemaleText_loc4`='我们需要所有元素的帮助才能救回萨尔。拉格纳罗斯的爪牙可没有赛克隆纳斯、海卓里斯或者塞拉赞恩那么好说话。', `FemaleText_loc5`='我們需要所有元素的幫忙才能從這地方救出索爾。拉格納羅斯的副官不會輕易讓步的，就連塞寇那斯、海德留斯、甚至是瑟拉贊恩都還知道什麼是妥協。', `FemaleText_loc7`='Necesitaremos la ayuda de TODOS los elementos para rescatar a Thrall de este lugar. Los tenientes de Ragnaros no tendrán tantas ganas de cooperar como Cyclonas, Hydrius o incluso Therazane.' WHERE `ID`=52789;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 끝났단 게... 믿어지지 않는군요...$b$b고엘은 자유예요. 당신의 공이 큽니다, $n 님.', `FemaleText_loc4`='都结束了……我不敢相信……$b$b古伊尔自由了，我对你感激不尽，$n。', `FemaleText_loc5`='我真不敢相信...這真的...結束了$b$b高爾自由了，光用謝謝不足以表達你幫了多大的忙，$n。', `FemaleText_loc7`='No me puedo creer que haya... terminado...$B$BGo''el es libre, en gran parte gracias a ti, $n.' WHERE `ID`=52790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄, 아그라... 스랄 님을 따라가셔야 하지 않나요?', `MaleText_loc4`='啊，阿格娜……你不是应该跟着萨尔吗？', `MaleText_loc5`='嗯...阿格拉...你不是應該跟在索爾身邊嗎?', `MaleText_loc7`='Umm, Aggra... ¿No deberías estar buscando a Thrall?', `FemaleText_loc1`='엄, 아그라... 스랄 님을 따라가셔야 하지 않나요?', `FemaleText_loc4`='啊，阿格娜……你不是应该跟着萨尔吗？', `FemaleText_loc5`='嗯...阿格拉...你不是應該跟在索爾身邊嗎?', `FemaleText_loc7`='Umm, Aggra... ¿No deberías estar buscando a Thrall?' WHERE `ID`=52791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래야죠. 하이잘 산에서 뵙겠습니다, 친구여.', `FemaleText_loc4`='没错。我们海加尔山再见，朋友。', `FemaleText_loc5`='你說的沒錯。在海加爾山碰面吧，朋友。', `FemaleText_loc7`='Tienes razón. Te veré en el Monte Hyjal.' WHERE `ID`=52792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토템을 회수하는 걸 잊지 마십시오!', `MaleText_loc4`='别忘了你的图腾！', `MaleText_loc5`='別忘了你的圖騰!', `MaleText_loc7`='¡No olvides tus tótems!', `FemaleText_loc1`='토템을 회수하는 걸 잊지 마세요!', `FemaleText_loc4`='别忘了你的图腾！', `FemaleText_loc5`='別忘了你的圖騰!', `FemaleText_loc7`='¡No olvides tus tótems!' WHERE `ID`=52793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군, 전선을 사수하라! 적을 살려두지 마라! 절대로 지나가게 해서는 안 된다!', `MaleText_loc4`='守住阵线，士兵们！不要给敌人任何的机会！别让他们通过！', `MaleText_loc5`='士兵，守住戰線!別對他們仁慈!一個都不准放過!', `MaleText_loc7`='¡Manténganse firmes, soldados! ¡No les den cuartel! ¡No los dejen pasar!' WHERE `ID`=52794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식이라고? 휴식은 무덤에 묻혔을 때나 즐길 수 있을 것이다. 오늘, 우리는 싸워야만 한다!', `MaleText_loc4`='休息？除非躺在我们自己的坟墓里。今天，我们必须战斗到底！', `MaleText_loc5`='休息?等我們躺在墓地裡頭就可以好好休息啦。今天我們必須戰鬥!', `MaleText_loc7`='¿Descansar? Podremos descansar cuando yazcamos enterrados en nuestras tumbas. Hoy, ¡tenemos que luchar!' WHERE `ID`=52795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군! 이동하라!', `MaleText_loc4`='动起来，士兵们！', `MaleText_loc5`='跑起來!士兵!', `MaleText_loc7`='¡Usen sus piernas, soldados!' WHERE `ID`=52796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전우들의 죽음을 헛되게 할 수는 없다! 절대 방어를 허술히 해서는 안 된다!', `MaleText_loc4`='我们不能让同伴的牺牲白费！不要松懈！', `MaleText_loc5`='不要讓同袍的性命白白浪費掉!別讓守衛失望!', `MaleText_loc7`='¡No podemos permitir que nuestros camaradas hayan muerto en vano! ¡No bajen la guardia!' WHERE `ID`=52797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보충 병력이 올 때까지 조금이라도 더 버텨내야만 한다.', `MaleText_loc4`='我们必须坚持住，援军马上就要到了。', `MaleText_loc5`='我們得再撐一下，只要撐到援軍趕到就行了。', `MaleText_loc7`='Tenemos que resistir un poco más, solo hasta que lleguen los refuerzos.' WHERE `ID`=52798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들은 우리가 나약하다고 생각한다. 제군! 우리가 나약하단 말인가? 그렇지 않다면 적들에게 우리의 강력함을 보여줘라!', `MaleText_loc4`='我们的敌人以为我们很弱。我们弱吗，士兵们？向他们证明，他们大错特错了！', `MaleText_loc5`='敵人認為我們是弱者。各位士兵，我們是弱者嗎?不是的話，就證明給對手看看!', `MaleText_loc7`='Nuestros enemigos piensan que somos débiles. ¿Lo somos, soldados? Si no es así, ¡demostrádselo!' WHERE `ID`=52799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수비병 모두 잘해냈다! 전세가 바뀌고 있구나!', `MaleText_loc4`='干得好，卫士们！我们寸土不让！', `MaleText_loc5`='做得不錯，各位防衛者!我們有優勢!', `MaleText_loc7`='¡Bien hecho, defensores! ¡Estamos ganando terreno!' WHERE `ID`=52800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투야말로 진정한 용기를 시험하는 것이다. 마음을 가다듬고 적의 피로 제군의 칼을 흥건히 물들여라!', `MaleText_loc4`='这场战斗的确是对勇气的极大考验。坚定你的信念，举起你的刀剑，让利刃痛饮敌人的鲜血吧！', `MaleText_loc5`='這場戰鬥是個真正的考驗。狠下心來，讓你手中的刀刃沾滿敵人的鮮血吧!', `MaleText_loc7`='Esta lucha es la auténtica prueba de coraje. ¡Ármense de valor y empapen sus espadas con la sangre de nuestros enemigos!' WHERE `ID`=52801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 대격변을 겪으며, 나는 우리의 삶이 얼마나 빠르게 흘러가는지 보았소. 이제부터 삶의 단 한 순간도 헛되이 보내지 않겠소.', `MaleText_loc4`='我见证了这场大灾变，亲眼目睹了生命的短暂。此时此刻，我不想再浪费哪怕一秒钟的时间。', `MaleText_loc5`='在這次的大災變中，我看到了我們的生命是多麼地短暫。而我，將不會再浪費一分一秒的時間。', `MaleText_loc7`='Al enfrentarnos al Cataclismo, he comprobado lo fugaces que pueden ser nuestras vidas. Y, por una vez, no tengo intención de malgastar un segundo de la mía.' WHERE `ID`=52802;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 말이에요, 고엘? 무슨 생각이길래?', `FemaleText_loc4`='你想说什么，古伊尔？你的真心是什么？', `FemaleText_loc5`='你在說什麼，高爾?你心裡在想什麼?', `FemaleText_loc7`='¿Qué dices, Go''el? ¿Qué hay en tu corazón?' WHERE `ID`=52803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라... 내 비록 드레노어 태생은 아니지만, 언제나 선조의 전통을 존중하려 노력했소...', `MaleText_loc4`='阿格娜……虽然我不是在我们的故乡——德拉诺出生，但我总是尽可能去尊重先祖的传统……', `MaleText_loc5`='阿格拉...雖然我不是在德拉諾出生的，但我一直以來都在試著為我們祖先的傳統帶來榮耀...', `MaleText_loc7`='Aggra... Aunque no nací en Draenor, siempre he intentado honrar las tradiciones de nuestros ancestros...' WHERE `ID`=52804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가라드의 아들, 듀로탄의 아들, 나 고엘은... 그대 앞에 섰소. 그대가 허락한다면, 평생 그대의 동반자가 되고 싶소.', `MaleText_loc4`='我就在你身边——我是古伊尔，杜隆坦之子，加拉达之子……如果你愿意，我愿成为你的终身伴侣。', `MaleText_loc5`='在你眼前的這個人─高爾，杜洛坦之子，卡拉達之孫...如果妳願意，我將永遠是妳的伴侶。', `MaleText_loc7`='Yo soy Go''el, hijo de Durotan, hijo de Garad... y si me aceptas, seré tu compañero de por vida.' WHERE `ID`=52805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 내 곁에 있었듯... 나 역시 생명이 다하는 그 순간까지... 그대의 곁을 지키겠소.', `MaleText_loc4`='终我一生，我将伴你左右……亦如你将终生伴我身侧。', `MaleText_loc5`='我只要活著一天，就會在你身邊陪伴著你...如同你為我所做的一樣。', `MaleText_loc7`='Mientras viva, permaneceré a tu lado... como tú has permanecido al mío.' WHERE `ID`=52806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사라크의 딸, 리알의 딸, 나 아그랄란은 그대 앞에 섰습니다. 자랑스러운 마음으로 이 세계, 그리고 다른 세계에서도 그대 고엘의 동반자가 되겠습니다.', `FemaleText_loc4`='我就在你身边。我是阿格娜兰，瑞亚尔之女，莎拉克之女……我以成为你的伴侣为荣，古伊尔……无论身在任何世界。', `FemaleText_loc5`='在你眼前的這個人─阿格拉蘭，萊由之女，莎拉克的孫女...我很光榮能成為你的伴侶，高爾...不管是在哪個世界中。', `FemaleText_loc7`='Yo soy Aggralan, hija de Ryal, hija de Sarrak... y estaré orgullosa de ser tu compañera, Go''el... en este mundo o en cualquier otro.' WHERE `ID`=52807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렉고사의 정수가 당신과 하나가 되었습니다.', `MaleText_loc4`='泰蕾苟萨的精魄与你同在。', `MaleText_loc5`='塔瑞克苟莎的精華與你同在。', `MaleText_loc7`='La esencia de Tarecgosa está contigo.', `FemaleText_loc1`='타렉고사의 정수가 당신과 하나가 되었습니다.', `FemaleText_loc4`='泰蕾苟萨的精魄与你同在。', `FemaleText_loc5`='塔瑞克苟莎的精華與你同在。', `FemaleText_loc7`='La esencia de Tarecgosa está contigo.' WHERE `ID`=52808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이걸 배반이라고 생각해서는 안 되오. 에드가가 그의 물건을 대가로 일생에 한 번 볼까 말까 한 물건을 줬단 말이오.', `MaleText_loc4`='你可千万别觉得这是背叛，$n。古德温先生可是给了我一笔这辈子只能碰见一次的丰厚报酬来交换他的货物。', `MaleText_loc5`='你一定不覺得這是種背叛，$n，但是古德溫先生付我錢是要我要畢生時光去換取他的遺物。', `MaleText_loc7`='No debes verlo como una traición, $n, pero el Sr. Ganabien me ha ofrecido el hallazgo de mi vida a cambio de sus pertenencias.' WHERE `ID`=52809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 방금 $n|1이;가; 가지고 왔다오. 흑마법서는 어떻게 됐소?', `MaleText_loc4`='是的。$n刚刚带着它回来。魔典怎么样了？', `MaleText_loc5`='是的沒錯。$n帶著東西回來。是怎樣的魔典?', `MaleText_loc7`='Así es. $n acaba de traerlo. ¿Qué hay del grimorio?' WHERE `ID`=52810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굿윈 씨, 이 물건은 이제 그대가 가지시오. 우리 거래를 벨록 님께서 아주 만족해하실 것이오.', `MaleText_loc4`='这东西是你的了，亲爱的古德温先生。贝洛克大师想必会对我们的交易十分满意。', `MaleText_loc5`='親愛的古德溫太太，東西是你的了。貝洛克大師會對我們的交易感到相當滿意。', `MaleText_loc7`='Es tuyo, mi querido Sr. Ganabien. El maestro Belloc estará encantado con nuestro intercambio.' WHERE `ID`=52811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 벨록과 성물회가 이것들을 다 가지게 될 거야...', `MaleText_loc4`='也许贝洛克和神圣遗物学会想要把两件东西都拿到手……', `MaleText_loc5`='畢竟這兩樣東西都該在貝洛克和聖匣守護者手上...', `MaleText_loc7`='Tal vez Belloc y El Relicario deban quedarse con ambos después de todo...' WHERE `ID`=52812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 단도직입적이군! 좋아, 내 물건이 어떤 건지 확실히 말해주지. 물건은 있나?', `MaleText_loc4`='开门见山！很好，我迫不及待的想要拿回原本就属于我的东西。你带着它吗？', `MaleText_loc5`='直接切入重點!很好，我也急著想要把屬於我的東西拿回來。東西在你那嗎?', `MaleText_loc7`='¡Al grano, sin rodeos! Bien, estoy deseando reclamar lo que me pertenece por derecho. ¿Lo tienes?' WHERE `ID`=52813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말이라네. 나는 메디브의 흑마법서를 가지고 있지. 성물회가 이 거래를 현명하게 진행해서 정말 다행이군.', `MaleText_loc4`='没错，我的确带着麦迪文的魔典。幸好神圣遗物学会明智地认为交换对大家都有好处。', `MaleText_loc5`='是在我這，麥迪文的魔典在我手上。我很走運，聖匣守護者看出藏在這筆交易中的智慧。', `MaleText_loc7`='Efectivamente, tengo el grimorio de Medivh. Ha sido una suerte que El Relicario haya comprendido lo sabio de este intercambio.' WHERE `ID`=52814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자가 내 것이 되는 순간 너는 곧바로 그것을 가지게 될 것이다. 네 동료는 그것이 큰 도움이 된다는 걸 알게 될 것이다.', `MaleText_loc4`='一旦我拿到箱子，你就能拿到你想要的东西。你的同事一定会茅塞顿开的，我确信。', `MaleText_loc5`='等箱子一落入我的手中，東西就是你的了。我深信你那些同事將會發現，這其中蘊含了多少的資訊和啟發性。', `MaleText_loc7`='Lo tendrás tan pronto como el cajón esté en mi poder. Seguro que tus colegas lo encontrarán de lo más instructivo.' WHERE `ID`=52815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 해 동안 이 주문과 내 변신이 완성되기를 갈망해 왔다. 내 모습을 보라!', `MaleText_loc4`='多年来，我一直渴望着完成这个法术，完成我的变形。现在，见证这一切吧！', `MaleText_loc5`='數年來，我一直想將這個法術以及變形加以完成。看吧!', `MaleText_loc7`='Durante años he deseado completar este hechizo y mi transformación. ¡Contempla!' WHERE `ID`=52816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 수년 동안 오늘을 꿈꿔왔다. 그리고 너도 온 힘을 다해줬구나. 내 일생의 정점을 보아라!', `MaleText_loc4`='我梦寐以求的这一天终于到了，$n，是你把这一切变成了现实。见证我毕生的最高成就吧！', `MaleText_loc5`='數年來我一直都在夢想著這一天的到來，$n，你讓我的夢想有機會成真。見證我一生志業的巔峰極致吧!', `MaleText_loc7`='He soñado con esto durante años, $n, y tú lo has hecho posible. ¡Observa la culminación del trabajo de toda una vida!' WHERE `ID`=52817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_vehicle_oiljets.blp:16|t당신은 |cFFFF0000|Hspell:81831|h[오염: 고통]|h|r을 시전하려고 합니다! 동료에게서 얼굴을 돌리십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_vehicle_oiljets.blp:16|t你将要施放|cFFFF0000|Hspell:81831|h[腐蚀：疫病]|h|r！赶紧背对盟友！', `MaleText_loc5`='|TInterface\\Icons\\ability_vehicle_oiljets.blp:16|t你即將施放|cFFFF0000|Hspell:81831|h[腐化:疾病]|h|r!轉身背對盟友!', `MaleText_loc7`='|TInterfaceIconsability_vehicle_oiljets.blp:16|t¡Estás a punto de lanzar |cFFFF0000|Hspell:81831|h[Corrupción: dolencia]|h|r! ¡Ponte de espaldas a tus aliados!' WHERE `ID`=52818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|t당신은 |cFFFF0000|Hspell:100460|h[타오르는 열기]|h|r를 내뿜으려고 합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|t你即将被|cFFFF0000|Hspell:100460|h[炽炎之热]|h|r包围！', `MaleText_loc5`='|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|t你即將爆發出|cFFFF0000|Hspell:100460|h[熾熱高溫]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_elemental_mote_fire01.blp:16|t¡Estás a punto de estallar en |cFFFF0000|Hspell:100460|h[Calor llameante]|h|r!' WHERE `ID`=52819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s|1이;가; 적이 뭉쳐 있는 곳에 |cFFFF6600|Hspell:100777|h[마그마 온천]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s开始朝敌人群施放|cFFFF6600|Hspell:100777|h[熔岩喷泉]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s開始對群聚的敵人施放|cFFFF6600|Hspell:100777|h[岩漿噴泉]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warlock_inferno.blp:20|t¡%s empieza a lanzar |cFFFF6600|Hspell:100777|h[Géiser de magma]|h|r a la maraña de enemigos!' WHERE `ID`=52820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 오너라! 놀드랏실의 힘은 내가 갖겠다!', `MaleText_loc4`='来吧，飞蛾们。诺达希尔的力量是我的！', `MaleText_loc5`='來吧，小火種!諾達希爾的力量會屬於我!', `MaleText_loc7`='¡Vamos! ¡El poder de Nordrassil SERÁ mío!', `FemaleText_loc1`='자, 오너라! 놀드랏실의 힘은 내가 갖겠다!', `FemaleText_loc4`='来吧，飞蛾们。诺达希尔的力量是我的！', `FemaleText_loc5`='來吧，小火種!諾達希爾的力量會屬於我!', `FemaleText_loc7`='¡Vamos! ¡El poder de Nordrassil SERÁ mío!' WHERE `ID`=52821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 타렉고사의 정수가 나타나자 강력한 힘이 솟아오르는 것을 느낍니다.', `MaleText_loc4`='泰蕾苟萨的精魄逐渐显现出其原本的模样，你能感受到一股能量的涌动。', `MaleText_loc5`='在塔瑞克苟莎的精華顯現時，你感到能量在奔騰。', `MaleText_loc7`='Sientes una oleada de poder cuando la esencia de Tarecgosa se manifiesta.', `FemaleText_loc1`='당신은 타렉고사의 정수가 나타나자 강력한 힘이 솟아오르는 것을 느낍니다.', `FemaleText_loc4`='泰蕾苟萨的精魄逐渐显现出其原本的模样，你能感受到一股能量的涌动。', `FemaleText_loc5`='在塔瑞克苟莎的精華顯現時，你感到能量在奔騰。', `FemaleText_loc7`='Sientes una oleada de poder cuando la esencia de Tarecgosa se manifiesta.' WHERE `ID`=52822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디에서도 찾을 수 없는 훌륭한 포도주와 이국적인 상품이 가득한 곳! 아가씨의 은밀한 상점에 오신 걸 환영합니다!', `MaleText_loc4`='欢迎来到林荫女士，这里有最好的美酒和异域商品，只此一家！', `MaleText_loc5`='歡迎來到敝店秘密仕女，在這你能找到其他地方沒有的精緻美酒和異國商品!', `MaleText_loc7`='¡Te doy la bienvenida a La Dama Misteriosa, hogar de vinos exquisitos y mercancías exóticas que no se encuentran en ninguna otra parte!' WHERE `ID`=52823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 파는지 보여주십시오.', `MaleText_loc4`='请让我看看菜单上都有些什么。', `MaleText_loc5`='讓我看看有些什麼東西。', `MaleText_loc7`='A ver qué hay en el menú.', `FemaleText_loc1`='뭘 파는지 보여주세요.', `FemaleText_loc4`='请让我看看菜单上都有些什么。', `FemaleText_loc5`='讓我看看有些什麼東西。', `FemaleText_loc7`='A ver qué hay en el menú.' WHERE `ID`=52824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아니야! 나는 용군단을 "배신"하지 않았어. 배신당한 건 바로 우리야. 세상이 무너지고 있는데도 이세라는 꿈속을 헤매고 있었다고.', `MaleText_loc4`='不，不！我没有“背叛”巨龙军团。被背叛的是我们。这个世界即将毁灭，伊瑟拉却迷失在梦境中。', `MaleText_loc5`='不，不!我沒有「背叛」龍群。我們都被背叛了。伊瑟拉在整個世界要毀滅時都還在夢境中遊蕩。', `MaleText_loc7`='No, ¡no! Yo no "traicioné" a los Vuelos. Fuimos traicionados. Ysera estaba perdida en su sueño mientras el mundo se venía abajo.' WHERE `ID`=52825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 주인님의 뜻을 이행하는 자! 관문의 수호자다!', `MaleText_loc4`='我即是主人的意志！我为他守护这道大门！', `MaleText_loc5`='我是主人意志的執行者!此門由我守護!', `MaleText_loc7`='¡Represento la voluntad de mi maestro! ¡Yo soy quien bloquea la puerta!' WHERE `ID`=52826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것들. 제 발로 무덤에 걸어 들어오다니!', `MaleText_loc4`='愚蠢的凡人。你们这是自寻死路。', `MaleText_loc5`='愚蠢的凡人。根本就是自取滅亡。', `MaleText_loc7`='Estúpidos mortales. Van directo a su muerte.' WHERE `ID`=52827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 군주님의 명을 받들어 네놈 역시 멸하리라!', `MaleText_loc4`='秉承炎魔之王的命令，你也会被毁灭！', `MaleText_loc5`='以炎魔之名，你，亦將殞命!', `MaleText_loc7`='¡Por orden del Señor del Fuego, también perecerán!' WHERE `ID`=52828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 뜻에 따라 모두 불태우리라.', `MaleText_loc4`='主人会见证你们的湮灭。', `MaleText_loc5`='主人會看到你們全都被吞噬。', `MaleText_loc7`='El maestro los consumirá a todos.' WHERE `ID`=52829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염의 바다가 너희를 삼킬 것이다!', `MaleText_loc4`='淹没在烈焰之海！', `MaleText_loc5`='被火海吞沒吧!', `MaleText_loc7`='¡Que el mar de llamas los devore!' WHERE `ID`=52830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이글거리는 나의 분노로 불살라 주마.', `MaleText_loc4`='我的熔岩之怒会烧尽你们。', `MaleText_loc5`='在我的熔岩怒火下燒吧。', `MaleText_loc7`='Ardan bajo mi furia de magma.' WHERE `ID`=52831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 주인님의 영역에 들어갈 수 없다!', `MaleText_loc4`='无人能进入主人的领地。', `MaleText_loc5`='沒人可以踏入主人的領地!', `MaleText_loc7`='¡Nadie entrará en los dominios del maestro!' WHERE `ID`=52832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왔습니다, 말퓨리온.', `MaleText_loc4`='我为你而来，玛法里奥。', `MaleText_loc5`='我來找你了，瑪法里恩。', `MaleText_loc7`='He venido por ti, Malfurion.' WHERE `ID`=52833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나도 나약한 존재여.', `MaleText_loc4`='你太弱了，老家伙。', `MaleText_loc5`='你們都太軟弱，太無力。', `MaleText_loc7`='Son todos débiles. Frágiles.' WHERE `ID`=52834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진리의 길은 단 하나, 화염의 길뿐이다!', `MaleText_loc4`='真理之道只有一个。那就是烈焰之道！', `MaleText_loc5`='只有一條正道，那就是火之道!', `MaleText_loc7`='Solo hay un camino verdadero. ¡El camino de la llama!' WHERE `ID`=52835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 길은 파멸의 길이다.', `MaleText_loc4`='你们的道路通向毁灭。', `MaleText_loc5`='你走的是毀滅之道。', `MaleText_loc7`='El suyo es el camino de la perdición.' WHERE `ID`=52836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들의 기지를 파괴해라. 나무를 태워 버려.', `MaleText_loc4`='毁掉他们的营地。烧光他们的树。', `MaleText_loc5`='摧毀他們的營房，把他們的樹燒了。', `MaleText_loc7`='Destruyan su campamento. Reduzcan su árbol a cenizas.' WHERE `ID`=52837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 남김없이 모조리 불태워라.', `MaleText_loc4`='烧尽一切。不留活口。', `MaleText_loc5`='燒光一切，不留任何活口。', `MaleText_loc7`='Quemen todo. No dejen sobrevivientes.' WHERE `ID`=52838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모조리 해치워라. 말퓨리온을 데려와라.', `MaleText_loc4`='把他们杀光。带玛法里奥来见我。', `MaleText_loc5`='殺光他們，把瑪法里恩帶過來。', `MaleText_loc7`='Maten a todos. Tráiganme a Malfurion.' WHERE `ID`=52839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온만 빼고 모두 없애라. 그는 내가 처리한다.', `MaleText_loc4`='杀掉所有人，除了玛法里奥。他是我的。', `MaleText_loc5`='別放過任何人，只留瑪法里恩給我。', `MaleText_loc7`='Que no quede nadie vivo, salvo Malfurion. Es mío.' WHERE `ID`=52840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 영역에서 꺼져라, 벌레들아.', `MaleText_loc4`='滚出我的王国，虫子。', `MaleText_loc5`='滾出我的國度，蟲子們。', `MaleText_loc7`='Fuera de mi reino, insectos...' WHERE `ID`=52841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 놈도 빠짐없이 불태우겠다.', `MaleText_loc4`='我会看着你们燃烧。', `MaleText_loc5`='我將看你們燃燒殆盡。', `MaleText_loc7`='Haré que todos ardan.' WHERE `ID`=52842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염의 먹이가 되어라!', `MaleText_loc4`='烈焰吞噬你们！', `MaleText_loc5`='被火焰吞噬吧!', `MaleText_loc7`='¡Que la llama los consuma!' WHERE `ID`=52843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 세계가 네놈들을 집어삼키리라!', `MaleText_loc4`='火焰王国会吞噬你！', `MaleText_loc5`='火之國度將吞噬你們!', `MaleText_loc7`='¡El reino de fuego los consumirá!' WHERE `ID`=52844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 죽음의 표적이다. 가라, 멀리 멀리!', `MaleText_loc4`='这是死亡的标记。逃吧，快逃，小东西！', `MaleText_loc5`='你們已經死定了。跑吧!逃吧!小不點!', `MaleText_loc7`='Estás marcado para morir. Largo. Huye, gusano.' WHERE `ID`=52845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 나의... 사냥감.', `MaleText_loc4`='你们是……猎物。', `MaleText_loc5`='你們已是...狩獵目標。', `MaleText_loc7`='Los van a... cazar.' WHERE `ID`=52846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭꼭 숨어라, 샤녹스가 간다.', `MaleText_loc4`='该逃跑了。沙恩诺克斯来了。', `MaleText_loc5`='該落跑囉。夏諾克斯登場。', `MaleText_loc7`='Hora de correr. Aquí viene Shannox.' WHERE `ID`=52847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거운 불길이 너희를 집어삼키리라!', `MaleText_loc4`='火焰的王国会吞噬你！', `MaleText_loc5`='火之國度將吞噬你們!', `MaleText_loc7`='¡El reino de fuego los consumirá!' WHERE `ID`=52848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t%s|1이;가; |cFFFF0000|Hspell:100675|h[공포의 불길]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t%s施放了|cFFFF0000|Hspell:100675|h[恐惧烈焰]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t%s開始施放|cFFFF0000|Hspell:100675|h[懼焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_mage_firestarter.blp:20|t¡%s lanza |cFFFF0000|Hspell:100675|h[Llama terrible]|h|r!' WHERE `ID`=52849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그마가 소용돌이치며 보주 안을 빙빙 돕니다. 하지만 반투명한 표면은 단단하고 건드릴 수 있을 정도로 차갑습니다.', `MaleText_loc4`='熔岩的涡流在这颗宝珠内缓慢地旋转着，但半透明的宝珠表面摸上去却是坚硬冰凉的。', `MaleText_loc5`='熔岩在寶珠內懶懶地旋轉著，但透明的表層十分結實，而且觸感冰涼。', `MaleText_loc7`='El magma gira y se arremolina lentamente dentro del orbe, pero la superficie transparente es sólida y fría al tacto.' WHERE `ID`=52850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<보주를 주운 뒤 세차게 흔듭니다.>', `MaleText_loc4`='<捡起宝珠后用力摇动。>', `MaleText_loc5`='<拿起寶珠並用力搖晃。>', `MaleText_loc7`='<Recoge el orbe y agítalo con fuerza.>', `FemaleText_loc1`='<보주를 주운 뒤 세차게 흔듭니다.>', `FemaleText_loc4`='<捡起宝珠然后用力摇动。>', `FemaleText_loc5`='<拿起寶珠並用力搖晃。>', `FemaleText_loc7`='<Recoge el orbe y agítalo con fuerza.>' WHERE `ID`=52851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙께서 타렉고사의 정수를 상대할 방법을 가르쳐 주셨다. 네놈들의 어리석은 여정도 여기서 끝이다!', `MaleText_loc4`='死亡之翼命我对付泰蕾苟萨的容器。你愚蠢的旅程到此结束了。', `MaleText_loc5`='死亡之翼已經幫我準備好應付塔瑞克苟莎的承載者。你的生命在此終結!', `MaleText_loc7`='Alamuerte me ha preparado para enfrentarme al recipiente de Tarecgosa. ¡Tu inútil viaje termina aquí!' WHERE `ID`=52852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하기는! 감히 불의 왕국에 들어가겠다는 건가?', `MaleText_loc4`='蠢货！你胆敢进入火焰的王国？', `MaleText_loc5`='蠢貨!你竟敢進入火的界域?', `MaleText_loc7`='¡$gInsensato:Insensata;! ¿Te atreves a adentrarte en el reino de fuego?' WHERE `ID`=52853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알도르 마루에서 남쪽으로 가면 주문각인사인 기록자 리디오를 찾을 수 있을 겁니다.', `MaleText_loc4`='你可以在奥尔多高地的南部找到铭文训练师，记录员利迪欧。', `MaleText_loc5`='你可以在奧多爾高地的南邊找到銘文學訓練師，記錄者里迪歐。', `MaleText_loc7`='Encontrarás al instructor de inscripción, el grabador Lidio, en la parte sur del Alto Aldor.', `FemaleText_loc1`='알도르 마루에서 남쪽으로 가면 주문각인사인 기록자 리디오를 찾을 수 있을 거예요.', `FemaleText_loc4`='你可以在奥尔多高地的南部找到铭文训练师，记录员利迪欧。', `FemaleText_loc5`='你可以在奧多爾高地的南邊找到銘文學訓練師，記錄者里迪歐。', `FemaleText_loc7`='Encontrarás al instructor de inscripción, el grabador Lidio, en la parte sur del Alto Aldor.' WHERE `ID`=52854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술가 언덕에는 전문 기술 훈련에 전념하는 도서관이 있습니다.$b$b당신이 찾고자 하는 지식은 현자의 도서관에 가면 알 수 있을 것입니다.', `MaleText_loc4`='占星者之台上有一个专门研究各种专业技能的图书馆。$b$b你可以去占星者之台的先知图书馆寻求你想要学习的知识。', `MaleText_loc5`='占卜者階梯有個圖書館專門提供專業訓練。$b$b你可以在先知書庫找到你追求的知識。', `MaleText_loc7`='En la Grada del Arúspice hay una biblioteca especializada en profesiones.$B$BEncontrarás el conocimiento que buscas en La Biblioteca del Profeta.', `FemaleText_loc1`='점술가 언덕에는 전문 기술 훈련에 전념하는 도서관이 있어요.$b$b당신이 찾고자 하는 지식은 현자의 도서관에 가면 알 수 있을 거예요.', `FemaleText_loc4`='占星者之台上有一个专门研究各种专业技能的图书馆。$b$b你可以去占星者之台的先知图书馆寻求你想要学习的知识。', `FemaleText_loc5`='占卜者階梯有個圖書館專門提供專業訓練。$b$b你可以在先知書庫找到你追求的知識。', `FemaleText_loc7`='En la Grada del Arúspice hay una biblioteca especializada en profesiones.$B$BEncontrarás el conocimiento que buscas en La Biblioteca del Profeta.' WHERE `ID`=52855;
