UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영약과 강화 효과를 준비하십시오!', `MaleText_loc4`='快吃药剂，快上buff！', `MaleText_loc5`='快喝精鍊藥劑!快補上增益效果!', `MaleText_loc7`='¡Usen sus frascos y lanzen los hechizos beneficiosos!', `FemaleText_loc1`='영약과 강화 효과를 준비하세요!', `FemaleText_loc4`='快吃药剂，快上buff！', `FemaleText_loc5`='快喝精鍊藥劑!快補上增益效果!', `FemaleText_loc7`='¡Usen sus frascos y lanzen los hechizos beneficiosos!' WHERE `ID`=52870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예. 우두머리가 2단계에서 세 번째 주문을 시전할 때 발차기할 것. 항상 1단계에서 첫 번째 주문을 시전할 때 발차기할 것. 하지만 1단계에서 두 번째 주문을 시전할 때는 절대 발차기하지 말 것. 대신 벼락이 치면 예외. 벼락이 치면... 무조건 발차기. 이게 뭐가 그렇게 어렵다는 겁니까?', `MaleText_loc4`='听好了，地上有什么躲什么，boss召什么打什么，换阶段的时候记得停手。踢掉boss在二阶段的第三次施法。一阶段的第一次施法一定要踢掉，但是第二次施法一定不能踢。除非是你看到他在用闪电。如果你看到他用闪电就无论如何都踢掉。这很难吗？', `MaleText_loc5`='好吧，在第二階段的第三形態踹一下王。第一階段的第一形態一定要踹他，但是第一階段的第二形態不行。除非，你看到閃電。如果你看到閃電，那就踹下去就對了。這樣有很難嗎?', `MaleText_loc7`='Vale, id a por el jefe en el tercer lanzamiento de la segunda fase. Atacad siempre en el primer lanzamiento de la primera fase, pero nunca en el segundo de la primera. A menos que veáis rayos. Si veis rayos... atacad de todas formas. ¿Qué tiene eso de difícil?', `FemaleText_loc1`='예. 우두머리가 2단계에서 세 번째 주문을 시전할 때 발차기할 것. 항상 1단계에서 첫 번째 주문을 시전할 때 발차기할 것. 하지만 1단계에서 두 번째 주문을 시전할 때는 절대 발차기하지 말 것. 대신 벼락이 치면 예외. 벼락이 치면... 무조건 발차기. 이게 뭐가 그렇게 어렵다는 거죠?', `FemaleText_loc4`='听好了，地上有什么躲什么，boss召什么打什么，换阶段的时候记得停手。踢掉boss在二阶段的第三次施法。一阶段的第一次施法一定要踢掉，但是第二次施法一定不能踢。除非是你看到他在用闪电。如果你看到他用闪电就无论如何都踢掉。这很难吗？', `FemaleText_loc5`='好吧，在第二階段的第三形態踹一下王。第一階段的第一形態一定要踹他，但是第一階段的第二形態不行。除非，你看到閃電。如果你看到閃電，那就踹下去就對了。這樣有很難嗎?', `FemaleText_loc7`='Vale, id a por el jefe en el tercer lanzamiento de la segunda fase. Atacad siempre en el primer lanzamiento de la primera fase, pero nunca en el segundo de la primera. A menos que veáis rayos. Si veis rayos... atacad de todas formas. ¿Qué tiene eso de difícil?' WHERE `ID`=52871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수리로봇 가진 분 없으십니까?', `MaleText_loc4`='有谁带修理机器人了吗？', `MaleText_loc5`='誰有修理機器人?', `MaleText_loc7`='¿Alguien tiene un robot de reparación?', `FemaleText_loc1`='수리로봇 가진 분 없나요?', `FemaleText_loc4`='有谁带修理机器人了吗？', `FemaleText_loc5`='誰有修理機器人?', `FemaleText_loc7`='¿Alguien tiene un robot de reparación?' WHERE `ID`=52872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 여러분. 제가 여기 처음 와서 그러는데... 미리 알아야 할 것이라도 있습니까?', `MaleText_loc4`='嘿，我以前没打过……打这个要注意点啥？', `MaleText_loc5`='哈囉各位，我是第一次來到這裡...有什麼事是我該知道的嗎?', `MaleText_loc7`='Eh, es la primera vez que estoy aquí... ¿hay algo que debería saber?', `FemaleText_loc1`='저기, 여러분. 제가 여기 처음 와서 그러는데... 미리 알아야 할 것이라도 있나요?', `FemaleText_loc4`='嘿，我以前没打过……打这个要注意点啥？', `FemaleText_loc5`='哈囉各位，我是第一次來到這裡...有什麼事是我該知道的嗎?', `FemaleText_loc7`='Eh, es la primera vez que estoy aquí... ¿hay algo que debería saber?' WHERE `ID`=52873;
