UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이런 일이 계속 일어나는 겁니까?', `MaleText_loc4`='为什么这些破事儿来个没完了？', `MaleText_loc5`='為什麼一直發生那樣的事?', `MaleText_loc7`='¿Por qué sigue pasando eso?', `FemaleText_loc1`='왜 이런 일이 계속 일어나는 건가요?', `FemaleText_loc4`='为什么这些破事儿来个没完了？', `FemaleText_loc5`='為什麼一直發生那樣的事?', `FemaleText_loc7`='¿Por qué sigue pasando eso?' WHERE `ID`=52880;
