UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='레이아라가 무정한 웃음을 터뜨립니다.', `FemaleText_loc4`='莱雅娜发出了一阵残忍的笑声。', `FemaleText_loc5`='雷亞拉發出了一聲殘忍的笑聲。', `FemaleText_loc7`='Leyara suelta una carcajada cruel.' WHERE `ID`=52891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 알고 있는 한 가지 분명한 사실은, 좋은 친구는 언제나 믿을 수 있다는 것이지. 그대에게도 이런 사람이 있다면, 항상 아껴줘야 하네.', `MaleText_loc4`='有件事我可以肯定，那就是你总是可以依赖你的好朋友。如果在你的生命中有这么一个人，请好好珍惜他。', `MaleText_loc5`='有一件事是我確切知道的，那就是你可以仰賴真正的好朋友。如果你的生命中有這樣的人，要好好珍惜他。', `MaleText_loc7`='Si hay algo que sé, es que siempre puedes contar con un buen amigo. Si tienes una persona así en tu vida, trátala bien.' WHERE `ID`=52892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안렌은 내 가장 친한 친구라네. 그 친구 없이는 뭘 해야 할지 모르겠군.', `MaleText_loc4`='安伦是我最好的朋友。要是没有他在，我真不知道该怎么办了。', `MaleText_loc5`='安倫是我最要好的朋友。我不知道如果沒有他我該怎麼辦。', `MaleText_loc7`='Anren es mi mejor amigo. No sé qué haría sin él.' WHERE `ID`=52893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로와 저는 불의 땅 침공 작전에 참여하기로 했습니다. 함께 살고, 함께 싸워, 함께 죽는 존재가 바로 형제 아니겠습니까!', `MaleText_loc4`='索罗和我一起加入了火焰之地战役。我们并肩作战，同生共死。这才是战火中的兄弟！', `MaleText_loc5`='索羅和我要加入進軍火源之界的行動。一起活著，一起戰鬥，一起死去。這就是兄弟!', `MaleText_loc7`='Tholo y yo vamos a unirnos a la invasión de las Tierras de Fuego. Vivimos juntos, luchamos juntos y moriremos juntos. ¡Para eso están los hermanos!' WHERE `ID`=52894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톨로와 저는 오랫동안 함께 해 왔습니다. 그가 저를 지켜주고 있다는 걸 항상 잘 알고 있습니다.', `MaleText_loc4`='我和索罗一起度过了无数难关。我知道他一定会为了我而格外留心。', `MaleText_loc5`='索羅跟我一起經歷了許多事情。我知道他一直在照顧我。', `MaleText_loc7`='Tholo y yo hemos pasado por muchas cosas juntos. Sé que siempre está cuidando de mí.' WHERE `ID`=52895;
