UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군대를 유지하는데 보급품이 얼마나 많이 필요한지 아십니까, $n 님? 무기, 음식, 피난처, 붕대... 이런 것도 그저 시작에 불과합니다.$B$B보급품이 저절로 생겨나는 것도 아니니, 가서 마토클로 님께 도와드리고 싶다고 말씀해 보십시오. 아마 그대의 힘이 필요하실 겁니다.', `MaleText_loc4`='$n，你可知道要支持一只军队需要多少补给？我们需要武器、食物、掩体、绷带……这还仅仅是个开始。$B$B补给不会自己就增加。如果你想要帮忙，就去和麦托克劳谈谈吧。她会让你派上用场的。', `MaleText_loc5`='你知道需要多少物資才能支撐整支軍隊，$n?我們需要武器、食物、營地、繃帶...而那些只是最基本的。$B$B補給物資不會自己生出來。如果你想要幫上忙，問問瑪托克勞。她會有辦法讓你做出貢獻的。', `MaleText_loc7`='¿Sabes cuántos suministros hacen falta para mantener un ejército, $n? Necesitamos armas, comida, cobijo, vendas... y eso es solo el principio.$B$BLos suministros no se van a almacenar solos. Si quieres ayudar, habla con Matogarra. Te dirá lo que puedes hacer.' WHERE `ID`=52912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타렉고사의 따뜻한 품이 당신을 감쌉니다.', `MaleText_loc4`='泰蕾苟萨的温暖气息环绕着你。', `MaleText_loc5`='塔瑞克苟莎存在的暖意包圍著你。', `MaleText_loc7`='El cálido abrazo de la presencia de Tarecgosa te envuelve.', `FemaleText_loc1`='타렉고사의 따뜻한 품이 당신을 감쌉니다.', `FemaleText_loc4`='泰蕾苟萨的温暖气息环绕着你。', `FemaleText_loc5`='塔瑞克苟莎存在的暖意包圍著你。', `FemaleText_loc7`='El cálido abrazo de la presencia de Tarecgosa te envuelve.' WHERE `ID`=52913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장으로 돌아가기 전에 힘을 비축하고 있다. 너도 나처럼 하는 게 좋을 거야.', `FemaleText_loc4`='重回战场前我需要恢复我的力量。最好你也这么做。', `FemaleText_loc5`='我正在為了回到戰鬥中而回復我的氣力。你聰明的話最好也這麼做。', `FemaleText_loc7`='Estoy recuperando fuerzas antes de volver a la batalla. Deberías hacer lo mismo.' WHERE `ID`=52914;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있는 거미들은 크기가... 저만해요! 들끓는 거미들을 어떻게 없애야 하는지 아세요?$B$B예, 그렇죠. 다이너마이트를 쓰면 돼요. 아주 아주 많이 말이죠.', `FemaleText_loc4`='那些蜘蛛的个头就和……我一样大！你知道该怎么对付成群的蜘蛛吗？$B$B嗯哼，没错。炸弹。成堆的炸弹。', `FemaleText_loc5`='那些蜘蛛跟...我一樣大!你知道怎麼解決蛛群肆虐的問題嗎?$B$B是的，沒錯。炸藥。很多很多的炸藥。', `FemaleText_loc7`='Aquí las arañas son tan grandes como... ¡yo! ¿Sabes cómo exterminar una plaga de arañas?$B$BExacto. Dinamita. Un montón de dinamita.' WHERE `ID`=52915;
