UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말퓨리온에게 돌아가 말로른의 성역을 보호해야 합니다.', `MaleText_loc4`='回到玛法里奥身边，保护玛洛恩庇护所。', `MaleText_loc5`='回倒瑪法里恩身邊保護瑪洛尼聖地。', `MaleText_loc7`='Vuelve junto a Malfurion para proteger el Santuario de Malorne.', `FemaleText_loc1`='말퓨리온에게 돌아가 말로른의 성역을 보호해야 합니다.', `FemaleText_loc4`='回到玛法里奥身边，保护玛洛恩庇护所。', `FemaleText_loc5`='回倒瑪法里恩身邊保護瑪洛尼聖地。', `FemaleText_loc7`='Vuelve junto a Malfurion para proteger el Santuario de Malorne.' WHERE `ID`=52973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 점점 짜증을 내더니 |cff7115ff|Hspell:101304|h[과열]|h|r됩니다.', `MaleText_loc4`='%s失去了耐心，并且变得|cff7115ff|Hspell:101304|h[极热]|h|r了。', `MaleText_loc5`='%s感到不耐煩，開始進入|cff7115ff|Hspell:101304|h[極炙]|h|r的狀態。', `MaleText_loc7`='%s se impacienta y se |cff7115ff|Hspell:101304|h[Sobrecalienta]|h|r.' WHERE `ID`=52974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님! 게임 하는 곳에서는 탈 것 금지입니다!', `MaleText_loc4`='$C！游戏场地内禁止使用坐骑！', `MaleText_loc5`='$C!遊戲場地上不准騎坐騎!', `MaleText_loc7`='¡$C! ¡Nada de monturas en el recinto de la feria!', `FemaleText_loc1`='$C님! 게임 하는 곳에서는 탈 것 금지예요!', `FemaleText_loc4`='$C！游戏场地内禁止使用坐骑！', `FemaleText_loc5`='$C!遊戲場地上不准騎坐騎!', `FemaleText_loc7`='¡$C! ¡Nada de monturas en el recinto de la feria!' WHERE `ID`=52975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 다크문 축제를 떠나시는 겁니까?$b$b돈을 조금만 주시면 제가 대도시로 순간이동 시켜 드리겠습니다.$b$b정말 떠나시겠습니까?', `MaleText_loc4`='这么快就要走了吗？$b$b只要交纳少许费用，我就能把你传回某个主城。$b$b确定要离开吗？', `MaleText_loc5`='這麼快就要離開馬戲團了?$b$b只要一點點費用，我可以把你傳送到一個主城去。$b$b你確定要離開嗎?', `MaleText_loc7`='¿Ya dejas la feria?$b$bPor una pequeña cantidad, te puedo teletransportar a una capital.$b$b¿De verdad que te quieres ir?', `FemaleText_loc1`='벌써 다크문 축제를 떠나시는 건가요?$b$b돈을 조금만 주시면 제가 대도시로 순간이동 시켜 드릴게요.$b$b정말 떠나시겠어요?', `FemaleText_loc4`='这么快就要走了吗？$b$b只要交纳少许费用，我就能把你传回某个主城。$b$b确定要离开吗？', `FemaleText_loc5`='這麼快就要離開馬戲團了?$b$b只要一點點費用，我可以把你傳送到一個主城去。$b$b你確定要離開嗎?', `FemaleText_loc7`='¿Ya dejas la feria?$b$bPor una pequeña cantidad, te puedo teletransportar a una capital.$b$b¿De verdad que te quieres ir?' WHERE `ID`=52976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드로 데려다 주십시오.', `MaleText_loc4`='送我去暴风城。', `MaleText_loc5`='把我傳送到暴風城。', `MaleText_loc7`='Llévame a Ventormenta.', `FemaleText_loc1`='스톰윈드로 데려다 주세요.', `FemaleText_loc4`='送我去暴风城。', `FemaleText_loc5`='把我傳送到暴風城。', `FemaleText_loc7`='Llévame a Ventormenta.' WHERE `ID`=52977;
