UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님! 다크문 축제에 오신 것을 환영합니다!', `MaleText_loc4`='欢迎来到暗月马戏团，$c！', `MaleText_loc5`='歡迎來到暗月馬戲團，$c!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra, $c!', `FemaleText_loc1`='$c님! 다크문 축제에 오신 것을 환영해요!', `FemaleText_loc4`='欢迎来到暗月马戏团，$c！', `FemaleText_loc5`='歡迎來到暗月馬戲團，$c!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra, $c!' WHERE `ID`=52979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알리스라가 숨을 깊게 들이쉽니다. 몸을 숨기십시오!', `MaleText_loc4`='奥利瑟拉深深地吸了一口气。快躲到掩体后面！', `MaleText_loc5`='艾里絲拉深深地吸了一口氣。快找掩護!', `MaleText_loc7`='Alysra respira profundamente. ¡Ponte a cubierto!' WHERE `ID`=52980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재 새 보스를 중점적으로 테스트하고 있습니다! 테스트를 진행하기 위해 제가 그곳으로 통하는 문을 열 수 있고, 다리를 건설할 수 있으며, 사자들을 처치할 수도 있습니다.', `MaleText_loc4`='我们正着力于测试新副本！我可以为您提供传送门，建立联接，杀死怪物以帮助您进行测试。', `MaleText_loc5`='我們正在測試伺服器上集中測試新的首領戰!我可以開門、造橋，還有殺獅子，來協助這個測試。', `MaleText_loc7`='¡Estamos probando nuevos encuentros! Puedo abrir puertas, construir puentes y matar leones para facilitar las pruebas.' WHERE `ID`=52982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다, 제베디아. 순간이동시켜 주십시오!', `MaleText_loc4`='尊特拉华达，我准备好了。传送我吧！', `MaleText_loc5`='好的，捷蒂雅。傳送我吧!', `MaleText_loc7`='Lo haré, Jebediah. ¡Teletranspórtame!', `FemaleText_loc1`='준비됐어요, 제베디아. 순간이동시켜 주세요!', `FemaleText_loc4`='尊特拉华达，我准备好了。传送我吧！', `FemaleText_loc5`='好的，捷蒂雅。傳送我吧!', `FemaleText_loc7`='Lo haré, Jebediah. ¡Teletranspórtame!' WHERE `ID`=52983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙과 싸울 수 있도록 하늘불꽃호로 데려가 주십시오.', `MaleText_loc4`='我要挑战死亡之翼，送我去天火号。', `MaleText_loc5`='請帶我到天火號與死亡之翼作戰。', `MaleText_loc7`='Llévame a El Abrasacielos para luchar contra Alamuerte.', `FemaleText_loc1`='데스윙과 싸울 수 있도록 하늘불꽃호로 데려가 주세요.', `FemaleText_loc4`='我要挑战死亡之翼，送我去天火号。', `FemaleText_loc5`='請帶我到天火號與死亡之翼作戰。', `FemaleText_loc7`='Llévame a El Abrasacielos para luchar contra Alamuerte.' WHERE `ID`=52984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='필멸의 존재여, 조심해야 합니다. 가장 노련한 영웅만이 저와 함께 마력의 탑 안으로 들어갈 수 있습니다.', `FemaleText_loc4`='当心点，凡人。$b$b只有最老练的英雄才能和我一起进入魔枢。', `FemaleText_loc5`='小心了，凡人。$b$b只有經驗最豐富的英雄可以陪我進入奧核之心。', `FemaleText_loc7`='Cuidado, mortal.$B$BSolo los héroes con más experiencia deberían acompañarme a El Nexo.' WHERE `ID`=52987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설적인 마력의 탑 인스턴스를 시험해보고 싶습니다.', `MaleText_loc4`='我想要测试传奇武器魔枢副本。', `MaleText_loc5`='我想要測試傳奇奧核之心。', `MaleText_loc7`='Quiero probar la estancia legendaria de El Nexo.', `FemaleText_loc1`='전설적인 마력의 탑 인스턴스를 시험해보고 싶어요.', `FemaleText_loc4`='我想要测试传奇武器魔枢副本。', `FemaleText_loc5`='我想要嘗試傳奇奧核之心。', `FemaleText_loc7`='Quiero probar la estancia legendaria de El Nexo.' WHERE `ID`=52988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1은;는; 당신이 길들이려고 하자 재빨리 도망칩니다!', `MaleText_loc4`='你想制伏%s，却被它迅速躲过了！', `MaleText_loc5`='%s很快地避開了你馴服的嘗試!', `MaleText_loc7`='¡%s evita rápidamente tus intentos de domar!' WHERE `ID`=52991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 위습이 적군의 차원문에 다가설 때 보호해야 합니다!', `MaleText_loc4`='保护好海加尔小精灵，让它关闭入侵者的传送门！', `MaleText_loc5`='保護海加爾幽光，等它關閉攻擊者的傳送門!', `MaleText_loc7`='¡Defiende al fuego fatuo de Hyjal mientras cierra el portal del atacante!' WHERE `ID`=52995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 위습이 도움을 요청합니다! 하이잘 위습이 적군의 차원문에 접근할 때 보호해 주십시오!', `MaleText_loc4`='海加尔小精灵需要帮助！保护好海加尔小精灵，让它关闭入侵者的传送门！', `MaleText_loc5`='海加爾幽光在求救!保護海加爾幽光，等它關閉攻擊者的傳送門!', `MaleText_loc7`='¡El fuego fatuo de Hyjal llama pidiendo ayuda! ¡Defiende al fuego fatuo de Hyjal mientras cierra el portal del atacante!' WHERE `ID`=52996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 위습이 약해졌습니다! 하이잘 위습이 적군의 차원문에 접근할 때 보호해 주십시오!', `MaleText_loc4`='海加尔小精灵受伤了！保护好海加尔小精灵，让它关闭入侵者的传送门！', `MaleText_loc5`='海加爾幽光逐漸變得虛弱!保護海加爾幽光，等它關閉攻擊者的傳送門!', `MaleText_loc7`='¡El fuego fatuo de Hyjal se debilita! ¡Defiende al fuego fatuo de Hyjal mientras cierra el portal del atacante!' WHERE `ID`=52997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이잘 위습이 죽었습니다!', `MaleText_loc4`='海加尔小精灵被杀害了！', `MaleText_loc5`='海加爾幽光被殺害了!', `MaleText_loc7`='¡El fuego fatuo de Hyjal ha sido asesinado!' WHERE `ID`=52998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이곳에 건설하는 게 무엇입니까?', `MaleText_loc4`='我们要在这里造什么？', `MaleText_loc5`='我們在這裡建造什麼?', `MaleText_loc7`='¿Qué estamos construyendo aquí?', `FemaleText_loc1`='우리가 이곳에 건설하는 게 뭔가요?', `FemaleText_loc4`='我们要在这里造什么？', `FemaleText_loc5`='我們在這裡建造什麼?', `FemaleText_loc7`='¿Qué estamos construyendo aquí?' WHERE `ID`=52999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 우리는 이곳 불의 땅에 영구적인 전초 기지를 건설 중이다. 라그나로스를 처치했더라도 또 다른 누군가가 그의 뒤를 따를 수도 있지 않겠나. 불타는 평원이나 하이잘 산에서 우리 세계를 위협했던 일들이 또다시 일어나게 할 수는 없다.$B$B그 목적을 달성코자 우리는 이곳에 "파수 나무"를 길러 낼 것이다. 뿌리는 아제로스에 있지만, 보호 효과를 가진 가지들은 끔찍한 이곳에 자라나겠지. 그리고 그 가지 아래에는 한 무리의 드루이드를 상주시켜 이 황량한 땅을 영원히 살피도록 할 것이다.', `MaleText_loc4`='我们将在火焰之地建立一座永久性的哨所，$n。即使拉格纳罗斯被打败了，但在将来的某一天，其他人仍有可能出来接替他的地位。我们不能让燃烧平原和海加尔的悲剧重演，再次威胁我们的世界。$B$B为此，我们将在这里种下“哨卫之树”。它扎根在艾泽拉斯，却能将树冠延伸到这个可怕的国度，形成保护。在它的庇荫下，我们就可以派一队德鲁伊永久驻扎下来，日夜监视这个荒芜的世界。', `MaleText_loc5`='我們在火源之界這裡建造一個永久性的前哨站，$n。即使拉格納羅斯被擊敗了，仍會有人取代他的位置。我們無法允許像發生在燃燒平原和海加爾山這樣的事情再次威脅我們的世界。$B$B為了這個目標，我們會種植「哨兵樹」。一棵在艾澤拉斯扎根的樹，但它保護性的頂蓋會在這個可怕的界域中成長。在它的保護下，我們會永久性的派駐一些德魯伊，永遠維持警戒地看顧這個荒蕪的世界。', `MaleText_loc7`='Estamos construyendo una avanzada permanente aquí, en las Tierras de Fuego, $n. Aunque derrotásemos a Ragnaros, otro podría ocupar su lugar. No podemos permitir que lo que ocurrió en Las Estepas Ardientes y en el Monte Hyjal vuelva a amenazar nuestro mundo.$B$BCon ese fin, plantaremos un "Árbol Centinela". Un árbol con raíces en Azeroth, pero con un dosel protector que crecerá en este terrible reino. Bajo su cobijo, apostaremos de manera permanente un grupo de druidas para mantener una vigilia eterna sobre este mundo desolado.' WHERE `ID`=53000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날카로운 울부짖음이 복도에 울려 퍼집니다!', `MaleText_loc4`='门厅中回荡着刺耳的嗥叫！', `MaleText_loc5`='尖銳的嚎叫聲在走廊上迴盪!', `MaleText_loc7`='¡Un aullido desgarrador resuena en los pasillos!', `FemaleText_loc1`='날카로운 울부짖음이 복도에 울려 퍼집니다!', `FemaleText_loc4`='门厅中回荡着刺耳的嗥叫！', `FemaleText_loc5`='尖銳的嚎叫聲在走廊上迴盪!', `FemaleText_loc7`='¡Un aullido desgarrador resuena en los pasillos!' WHERE `ID`=53003;
