UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자불이라는 트롤을 찾고 계시는군요. 그가 당신을 도울 수 있습니다.', `MaleText_loc4`='你得去找巨魔贾布。他可以帮助你。', `MaleText_loc5`='去找叫賈布爾的食人妖。他可以幫你。', `MaleText_loc7`='Buscas al trol, Jabul. Puede ayudarte.', `FemaleText_loc1`='자불이라는 트롤을 찾고 계시는군요. 그가 당신을 도울 수 있습니다.', `FemaleText_loc4`='你得去找巨魔贾布。他可以帮助你。', `FemaleText_loc5`='去找叫賈布爾的食人妖。他可以幫你。', `FemaleText_loc7`='Buscas al trol, Jabul. Puede ayudarte.' WHERE `ID`=53015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐마차가 도착했군. 행운을 빌겠소!', `MaleText_loc4`='大篷车到了。一路顺风！', `MaleText_loc5`='商隊到了。祝你好運!', `MaleText_loc7`='La caravana ha llegado. ¡Buena suerte!' WHERE `ID`=53016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 사냥개를 처치하고 타렉고사를 찾으십시오!', `MaleText_loc4`='击败魔法追猎者，找到泰蕾苟萨！', `MaleText_loc5`='擊敗魔法獵人並找到塔瑞克苟莎!', `MaleText_loc7`='¡Derrota a los cazadores mágicos y encuentra a Tarecgosa!', `FemaleText_loc1`='마법 사냥개를 처치하고 타렉고사를 찾으십시오!', `FemaleText_loc4`='击败魔法追猎者，找到泰蕾苟萨！', `FemaleText_loc5`='擊敗魔法獵人並找到塔瑞克苟莎!', `FemaleText_loc7`='¡Derrota a los cazadores mágicos y encuentra a Tarecgosa!' WHERE `ID`=53017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 에테리얼 기술은 이전에는 상상도 할 수 없었던, 사물의 비전 정수를 바꿀 수 있는 능력이 있습니다. 또한 작은 공간에 아이템을 보관할 수도 있습니다... 물론 비용이 약간 들지요. 자세한 이야기를 들으려면 제 동료들을 만나보십시오.$B$B아니면 시험해볼 물건 좀 가지고 계십니까?', `MaleText_loc4`='我们虚灵的技术能够改变一件物品的魔法本质，这在过去是不可想象的。我们还能将物品放入其他位面保存起来……只是需要少许费用。具体情况，你可以找我的同伴询问。$B$B你有东西要让我检查吗？', `MaleText_loc5`='我們的以太魔科技有著以前的人無法想像的能力，可以修改物品秘法本質。我們能把物品存進一處獨立次元...只要少許的費用。詳情請洽詢我的同事。$B$B或者，你有東西要讓我看看嗎?', `MaleText_loc7`='Nuestra tecnomancia etérea tiene la facultad de modificar la esencia Arcana de un objeto en formas que nunca podrías imaginar. También podemos alojar objetos en otra dimensión... por un módico precio. Consulta los detalles con mis socios.$b$bA no ser que tengas algo que quieras que examine.', `FemaleText_loc1`='우리의 에테리얼 기술은 이전에는 상상도 할 수 없었던, 사물의 비전 정수를 바꿀 수 있는 능력이 있어요. 또한 작은 공간에 아이템을 보관할 수도 있답니다... 물론 비용이 약간 들긴 해요. 자세한 이야기를 들으려면 제 동료들을 만나보세요.$B$B아니면 시험해볼 물건 좀 가지고 계신가요?', `FemaleText_loc4`='我们虚灵的技术能够改变一件物品的魔法本质，这在过去是不可想象的。我们还能将物品放入其他位面保存起来……只是需要少许费用。具体情况，你可以找我的同伴询问。$B$B你有东西要让我检查吗？', `FemaleText_loc5`='我們的以太魔科技有著以前的人無法想像的能力，可以修改物品秘法本質。我們能把物品存進一處獨立次元...只要少許的費用。詳情請洽詢我的同事。$B$B或者，你有東西要讓我看看嗎?', `FemaleText_loc7`='Nuestra tecnomancia etérea tiene la facultad de modificar la esencia Arcana de un objeto en formas que nunca podrías imaginar. También podemos alojar objetos en otra dimensión... por un módico precio. Consulta los detalles con mis socios.$b$bA no ser que tengas algo que quieras que examine.' WHERE `ID`=53018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 계신 물건의 모양이 마음에 안 드십니까?$B$B가장 강력한 최신기술로 만들어진 우리 형상변환기를 주목해 주십시오. 능숙한 차원술사라면 이것으로 물건을 기존과 다른 형태로 바꿀 수 있습니다.$B$B이 변변찮은 물건을 무엇으로 바꿔 드릴까요, 잘생긴 손님?', `MaleText_loc4`='对物品的外观不满意吗？$B$B来看看我们的幻化器吧，这是我们最有潜力的科技产品。有了它，一名熟练的织幻者就可以把一件物品的外观变成另外一件物品的样子。$B$B需要在下为您幻化什么物品吗，亲爱的客人？', `MaleText_loc5`='對於物品的外型不滿意嗎?$B$B來看看塑形轉化器，我們最強大的魔科技引擎之一。有了這個，熟練的星移編織師就可以把一個物品的樣子變成另一個物品的樣子。$B$B我能為你塑形什麼東西嗎?', `MaleText_loc7`='¿No te gusta la apariencia de un objeto?$B$BHe aquí el transfigurador, uno de nuestros inventos tecnománticos más poderosos. Con él, un tejedor de distorsión con talento puede cambiar la apariencia de un objeto por la de otro.$B$B¿Hay algo que este humilde ser pueda transfigurarte, $gestimado:estimada; cliente?', `FemaleText_loc1`='가지고 계신 물건의 모양이 마음에 안 드세요?$B$B가장 강력한 최신기술로 만들어진 우리 형상변환기를 주목해 주세요. 능숙한 차원술사라면 이것으로 물건을 기존과 다른 형태로 바꿀 수 있답니다.$B$B이 변변찮은 물건을 무엇으로 바꿔 드릴까요, 잘생긴 손님?', `FemaleText_loc4`='对物品的外观不满意吗？$B$B来看看我们的幻化器吧，这是我们最有潜力的科技产品。有了它，一名熟练的织幻者就可以把一件物品的外观变成另外一件物品的样子。$B$B需要在下为您幻化什么物品吗，亲爱的客人？', `FemaleText_loc5`='對於物品的外型不滿意嗎?$B$B來看看塑形轉化器，我們最強大的魔科技引擎之一。有了這個，熟練的星移編織師就可以把一個物品的樣子變成另一個物品的樣子。$B$B我能為你塑形什麼東西嗎?', `FemaleText_loc7`='¿No te gusta la apariencia de un objeto?$B$BHe aquí el transfigurador, uno de nuestros inventos tecnománticos más poderosos. Con él, un tejedor de distorsión con talento puede cambiar la apariencia de un objeto por la de otro.$B$B¿Hay algo que este humilde ser pueda transfigurarte, $gestimado:estimada; cliente?' WHERE `ID`=53019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이템의 형상을 변환하겠습니다.', `MaleText_loc4`='幻化一件物品。', `MaleText_loc5`='塑形一項物品。', `MaleText_loc7`='Transfigurar un objeto.', `FemaleText_loc1`='아이템의 형상을 변환할게요.', `FemaleText_loc4`='幻化一件物品。', `FemaleText_loc5`='塑形一項物品。', `FemaleText_loc7`='Transfigurar un objeto.' WHERE `ID`=53020;
