UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<DNT: Storage explanation.>', `MaleText_loc4`='<DNT: Storage explanation.>', `MaleText_loc5`='精靈貴族已然歸來，並且帶回了失傳百千年之久的魔法技藝。$B$B你有東西要我查驗嗎?', `MaleText_loc7`='<DNT: Storage explanation.>', `FemaleText_loc1`='<DNT: Storage explanation.>', `FemaleText_loc4`='<DNT: Storage explanation.>', `FemaleText_loc5`='精靈貴族已然歸來，並且帶回了失傳百千年之久的魔法技藝。$B$B你有東西要我查驗嗎?', `FemaleText_loc7`='<DNT: Storage explanation.>' WHERE `ID`=53023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이템을 저장하겠습니다.', `MaleText_loc4`='储存一件物品。', `MaleText_loc5`='存放一項物品。', `MaleText_loc7`='Almacenar un objeto.', `FemaleText_loc1`='아이템을 저장할게요.', `FemaleText_loc4`='储存一件物品。', `FemaleText_loc5`='存放一項物品。', `FemaleText_loc7`='Almacenar un objeto.' WHERE `ID`=53024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 자!$B$B당신이라면 느릿느릿하게 움직이는 거북이 등에 고리를 던져 놓을 수 있을 겁니다.$b$b어떠십니까?', `MaleText_loc4`='嘿，嘿！$B$B我敢说，你一定有本事把投环扔到一只慢腾腾的乌龟背上。$b$b你觉得呢？', `MaleText_loc5`='嘿，嘿!$B$B我想你一定可以把圈圈丟到慢吞吞的烏龜身上。$b$b怎麼樣?', `MaleText_loc7`='¡Eh, oye!$B$BEstoy seguro de que puedes alcanzar a una tortuga en movimiento con un anillo.$b$b¿Qué me dices?', `FemaleText_loc1`='자, 자!$B$B당신이라면 느릿느릿하게 움직이는 거북이 등에 고리를 던져 놓을 수 있을 거예요.$b$b어떠세요?', `FemaleText_loc4`='嘿，嘿！$B$B我敢说，你一定有本事把投环扔到一只慢腾腾的乌龟背上。$b$b你觉得呢？', `FemaleText_loc5`='嘿，嘿!$B$B我想你一定可以把圈圈丟到慢吞吞的烏龜身上。$b$b怎麼樣?', `FemaleText_loc7`='¡Eh, oye!$B$BEstoy segura de que puedes alcanzar a una tortuga en movimiento con un anillo.$b$b¿Qué me dices?' WHERE `ID`=53027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='我准备好了！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='準備開始玩! |cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Estoy listo para jugar! |cFF0008E8(Ficha de juego de la Luna Negra)|r', `FemaleText_loc1`='준비됐어요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='我准备好了！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='準備開始玩! |cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Estoy lista para jugar! |cFF0008E8(Ficha de juego de la Luna Negra)|r' WHERE `ID`=53028;
