UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 훨씬 나아진 느낌입니다.', `MaleText_loc4`='我已经好多了。', `MaleText_loc5`='我已經覺得好多了。', `MaleText_loc7`='Ya me siento mejor.', `FemaleText_loc1`='벌써 훨씬 나아진 느낌이 들어요.', `FemaleText_loc4`='我已经好多了。', `FemaleText_loc5`='我已經覺得好多了。', `FemaleText_loc7`='Ya me siento mejor.' WHERE `ID`=53034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 그렇게 많이 아프지 않군요.', `MaleText_loc4`='已经没那么疼了。', `MaleText_loc5`='已經不會那麼痛了。', `MaleText_loc7`='Ya no duele tanto.', `FemaleText_loc1`='이젠 그렇게 많이 아프지 않아요.', `FemaleText_loc4`='已经没那么疼了。', `FemaleText_loc5`='已經不會那麼痛了。', `FemaleText_loc7`='Ya no duele tanto.' WHERE `ID`=53035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 고맙습니다!', `MaleText_loc4`='真不知道该怎么感谢你！', `MaleText_loc5`='我非常感謝你!', `MaleText_loc7`='¡Nunca podré agradecértelo lo suficiente!', `FemaleText_loc1`='너무 고마워요!', `FemaleText_loc4`='真不知道该怎么感谢你！', `FemaleText_loc5`='我非常感謝你!', `FemaleText_loc7`='¡Nunca podré agradecértelo lo suficiente!' WHERE `ID`=53036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 다크문 게임 동전 한 개를 주시면 고리 10개를 드릴 겁니다.$B$B그 고리를 저기 있는 다크문 거북이 두벤코의 등 위에 있는 막대... 보이시죠? 거기에 던져넣으면 됩니다.$b$b한 번 시도해서 고리를 다 던져넣지 못하면, 다시 시도해 보십시오! 점수는 다음 게임에도 계속 누적되니까 말입니다.', `MaleText_loc4`='你给我一枚游戏代币，我会给你10个投环。$B$B你得想办法把它们扔到那边的暗月乌龟杜本科的背上……看到它驮着的那根柱子了吗？$b$b不过要是你没能扔中足够的环，那就再试一次！你的分数是可以累积到下一轮游戏的。', `MaleText_loc5`='你先給我一個遊戲代幣，然後我給你十個圈圈。$b$b把圈圈丟到那邊的肚邊龜身上... 有看到牠背上的桿子嗎?。$b$b就算你丟中的圈圈不夠多、沒法一次獲勝，只要再試一次就好了!你的點數可以沿用到下場遊戲。', `MaleText_loc7`='Me das una ficha de juego y yo te doy diez anillos.$B$BLanza los anillos a la tortuga de la Luna Negra Dubenko que está ahí... ¿Ves la barra que lleva en el caparazón?$b$bSi no metes los anillos suficientes para ganar en un turno, ¡vuelve a intentarlo! Los puntos se acumulan para la siguiente partida.', `FemaleText_loc1`='제게 다크문 게임 동전 한 개를 주시면 고리 10개를 드릴 거예요.$B$B그 고리를 저기 있는 다크문 거북이 두벤코의 등 위에 있는 막대... 보이시죠? 거기에 던져넣으면 된답니다.$b$b한 번 시도해서 고리를 다 던져넣지 못하면, 다시 시도해 보세요! 점수는 다음 게임에도 계속 누적된답니다.', `FemaleText_loc4`='你给我一枚游戏代币，我会给你10个投环。$B$B你得想办法把它们扔到那边的暗月乌龟杜本科的背上……看到它驮着的那根柱子了吗？$b$b不过要是你没能扔中足够的环，那就再试一次！你的分数是可以累积到下一轮游戏的。', `FemaleText_loc5`='你先給我一個遊戲代幣，然後我給你十個圈圈。$b$b把圈圈丟到那邊的肚邊龜身上... 有看到牠背上的桿子嗎?。$b$b就算你丟中的圈圈不夠多、沒法一次獲勝，只要再試一次就好了!你的點數可以沿用到下場遊戲。', `FemaleText_loc7`='Me das una ficha de juego y yo te doy diez anillos.$B$BLanza los anillos a la tortuga de la Luna Negra Dubenko que está ahí... ¿Ves la barra que lleva en el caparazón?$b$bSi no metes los anillos suficientes para ganar en un turno, ¡vuelve a intentarlo! Los puntos se acumulan para la siguiente partida.' WHERE `ID`=53037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사해 주십시오! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='发射吧！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='發射我! |cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Lánzame! |cFF0008E8(Ficha de juego de la Luna Negra)|r', `FemaleText_loc1`='발사해 주세요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='发射吧！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='發射我! |cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Lánzame! |cFF0008E8(Ficha de juego de la Luna Negra)|r' WHERE `ID`=53038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warstomp.blp:20|t%s|1이;가; |cFFFF0000|Hspell:101626|h[파쇄]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warstomp.blp:20|t%s开始释放|cFFFF0000|Hspell:101626|h[粉碎]|h|r了！', `MaleText_loc5`='|TInterface\\Icons\\ability_warstomp.blp:20|t%s開始施放|cFFFF0000|Hspell:101626|h[粉碎]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warstomp.blp:20|t¡%s lanza |cFFFF0000|Hspell:101626|h[Pulverizar]|h|r!' WHERE `ID`=53039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 자초한 일입니다.', `FemaleText_loc4`='这是你自找的。', `FemaleText_loc5`='你們自找的。', `FemaleText_loc7`='Se lo han buscado.' WHERE `ID`=53040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가! 어서 오게!$B$B도전할 수 있겠나?', `MaleText_loc4`='你好啊！欢迎你！$B$B你是来进行挑战的吗？', `MaleText_loc5`='哈囉，歡迎啊!$B$B要來挑戰一下嗎?', `MaleText_loc7`='¡Hola! ¡Te doy la bienvenida!$B$B¿Te apetece un reto?' WHERE `ID`=53041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 쏴봅시다! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='我们要开打了！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='打靶射擊! |cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Estoy listo para disparar! |cFF0008E8(Ficha de juego de la Luna Negra)|r', `FemaleText_loc1`='한 번 쏴볼게요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='我们要开打了！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='打靶射擊! |cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Estoy lista para disparar! |cFF0008E8(Ficha de juego de la Luna Negra)|r' WHERE `ID`=53042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 위상들에게 가야 하네. 준비됐나?', `MaleText_loc4`='我们要去见守护巨龙了，你准备好了吗？', `MaleText_loc5`='我們得去和守護巨龍會合。你準備好了嗎?', `MaleText_loc7`='Tenemos que llegar hasta los Aspectos. ¿Vamos?' WHERE `ID`=53043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 스랄 님.', `MaleText_loc4`='是的，萨尔。', `MaleText_loc5`='是的，索爾。', `MaleText_loc7`='Sí, Thrall.', `FemaleText_loc1`='네, 스랄 님.', `FemaleText_loc4`='是的，萨尔。', `FemaleText_loc5`='是的，索爾。', `FemaleText_loc7`='Sí, Thrall.' WHERE `ID`=53044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 용의 영혼을 손에 넣었네. 위상들이 고룡쉼터에서 기다리고 있어. 어서... 날 따라오게!', `MaleText_loc4`='英雄们，我们得到了巨龙之魂。守护巨龙在神殿里等着我们。快——跟我来！', `MaleText_loc5`='英雄們，我們取得巨龍之魂了。守護巨龍正在龍眠神殿等我們。快!跟我來!', `MaleText_loc7`='Tenemos el Alma de dragón. Los Aspectos nos esperan en el Reposo del Dragón. ¡Rápido, síganme!' WHERE `ID`=53046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 살아서 빠져나갈 것 같으냐?', `MaleText_loc4`='你们别想活着走出这条峡谷。', `MaleText_loc5`='你們不會活著離開這個峽谷。', `MaleText_loc7`='¡No saldrás vivo de este cañón!' WHERE `ID`=53047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르게, 계속 가야 하네.', `MaleText_loc4`='快，我们必须继续前进。', `MaleText_loc5`='快點，我們必須前進。', `MaleText_loc7`='¡Deprisa! Tenemos que seguir adelante.' WHERE `ID`=53048;
