UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무슨 조화지?', `MaleText_loc4`='这是什么魔法？', `MaleText_loc5`='這是什麼魔法?', `MaleText_loc7`='¿Qué clase de magia es esta?' WHERE `ID`=53050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속사!', `MaleText_loc4`='快射击！', `MaleText_loc5`='快速射擊!', `MaleText_loc7`='¡Disparo presuroso!', `FemaleText_loc1`='속사!', `FemaleText_loc4`='快射击！', `FemaleText_loc5`='快速射擊!', `FemaleText_loc7`='¡Disparo presuroso!' WHERE `ID`=53051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제 지역을 만들고 보수하는 일은 힘듭니다...', `MaleText_loc4`='建立及维护场地可不容易……', `MaleText_loc5`='要架設馬戲團的場地並進行維護，是件很艱難的工作...', `MaleText_loc7`='Establecerse y mantener el recinto es un trabajo duro.', `FemaleText_loc1`='축제 지역을 만들고 보수하는 일은 힘들어요...', `FemaleText_loc4`='建立及维护场地可不容易……', `FemaleText_loc5`='要架設馬戲團的場地並進行維護，是件很艱難的工作...', `FemaleText_loc7`='Establecerse y mantener el recinto es un trabajo duro.' WHERE `ID`=53052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔을 움직이면 아픕니다.', `MaleText_loc4`='我动一动胳膊都觉得疼。', `MaleText_loc5`='我每次動到手臂都會覺得痛。', `MaleText_loc7`='Me duele si muevo el brazo.', `FemaleText_loc1`='팔을 움직이면 아파요.', `FemaleText_loc4`='我动一动胳膊都觉得疼。', `FemaleText_loc5`='我每次動到手臂都會覺得痛。', `FemaleText_loc7`='Me duele si muevo el brazo.' WHERE `ID`=53053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 깊은 상처는 나아지지 않을 것 같습니다.', `MaleText_loc4`='这条伤口看来似乎好不了了。', `MaleText_loc5`='這個傷口看起來一直沒有痊癒的跡象。', `MaleText_loc7`='Este corte no parece que se esté curando.', `FemaleText_loc1`='이 깊은 상처는 나아지지 않을 것 같아요.', `FemaleText_loc4`='这条伤口看来似乎好不了了。', `FemaleText_loc5`='這個傷口看起來一直沒有痊癒的跡象。', `FemaleText_loc7`='Este corte no parece que se esté curando.' WHERE `ID`=53054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 절대로 대포를 혼자 설치하려고 하지 말아야겠습니다...', `MaleText_loc4`='我再也不一个人去调整大炮了……', `MaleText_loc5`='那是我最後一次嘗試自己獨自把大砲架起來...', `MaleText_loc7`='Es la última vez que intento preparar el cañón yo solo...', `FemaleText_loc1`='이제 절대로 대포를 혼자 설치하려고 하지 말아야겠어요...', `FemaleText_loc4`='我再也不一个人去调整大炮了……', `FemaleText_loc5`='那是我最後一次嘗試自己獨自把大砲架起來...', `FemaleText_loc7`='Es la última vez que intento preparar el cañón yo sola...' WHERE `ID`=53055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 망치도 있고, 놀도 있어요.$b$b다크문 게임 동전이 있다면 망치로 놀을 두들겨 팰 수 있답니다.', `MaleText_loc4`='我们这儿有锤子，还有豺狼人。$b$b只要一个代币，你就可以用锤子砸这些豺狼人了。', `MaleText_loc5`='我們有錘子、有豺狼人。$b$b只要你有代幣，就可以用錘子痛扁豺狼人。', `MaleText_loc7`='Tenemos martillos y tenemos gnolls.$b$bSi tienes una ficha, puedes usar el martillo y aporrear algunos gnolls.', `FemaleText_loc1`='여기 망치도 있고, 놀도 있답니다.$b$b다크문 게임 동전만 있다면 망치로 놀을 두들겨 팰 수 있어요.', `FemaleText_loc4`='我们这儿有锤子，还有豺狼人。$b$b只要一个代币，你就可以用锤子砸这些豺狼人了。', `FemaleText_loc5`='我們有錘子、有豺狼人。$b$b只要你有代幣，就可以用錘子痛扁豺狼人。', `FemaleText_loc7`='Tenemos martillos y tenemos gnolls.$b$bSi tienes una ficha, puedes usar el martillo y aporrear algunos gnolls.' WHERE `ID`=53056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한바탕 할 준비됐습니다! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='我要开始砸了！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='準備開扁! |cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Listo para aporrear! |cFF0008E8(Ficha de juego de la Luna Negra)|r', `FemaleText_loc1`='한바탕 할 준비됐어요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='我要开始砸了！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='準備開扁! |cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Lista para aporrear! |cFF0008E8(Ficha de juego de la Luna Negra)|r' WHERE `ID`=53057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와! 내가 뼈를 찾았어! 이것 좀 봐!', `MaleText_loc4`='我找到一根骨头，看！', `MaleText_loc5`='我找到一根骨頭了，看!', `MaleText_loc7`='¡He encontrado un hueso, mira!' WHERE `ID`=53058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전의 통통 전차를 찾고 있나?$b$b더 많은 즐거움을 선사하려고 새로운 통통 전차를 준비했다네.$b$b원격 조종 장치를 사용하려면 원래 게임 동전 두 개를 내야 하지만, 자네는 군인 할인으로 한 개만 내도 되네.$b$b다크문 축제에 있는 우리 모두 자네의 헌신에 감사해하고 있으니까 말이네.', `MaleText_loc4`='在找旧的蒸汽坦克吗？$b$b好吧，我们现在有些新的货色了。$b$b通常情况下，使用坦克遥控器要花费两个代币。但由于你曾经在部队服过役，所以能享受一个代币的优惠。$b$b我们暗月马戏团的成员非常感谢你所做的贡献。', `MaleText_loc5`='在找舊版的蒸汽坦克嗎?$b$b我們有新版的讓你玩呢。$b$b通常，你會需要花費兩個代幣才能使用坦克的遙控裝置。但是因為你在軍事上的貢獻，我們給了你只要花一個代幣的折扣。$b$b我們暗月馬戲團感謝你的服務。', `MaleText_loc7`='¿Estás buscando los antiguos tonques de vapor?$b$bBueno, tenemos algunos nuevos para que te entretengas.$b$bNormalmente, te costaría dos fichas usar el control remoto del tonque pero por los servicios militares que has prestado, tendrás un descuento de una ficha.$b$bEn la Feria de la Luna Negra te estamos agradecidos por tus servicios.', `FemaleText_loc1`='예전의 통통 전차를 찾고 계신가요?$b$b더 많은 즐거움을 선사하려고 새로운 통통 전차를 준비했답니다.$b$b원격 조종 장치를 사용하려면 원래 게임 동전 두 개를 내야 하지만, 당신은 군인 할인으로 한 개만 내셔도 돼요.$b$b다크문 축제에 있는 우리 모두 당신의 헌신에 감사해하고 있답니다.', `FemaleText_loc4`='在找旧的蒸汽坦克吗？$b$b好吧，我们现在有些新的货色了。$b$b通常情况下，使用坦克遥控器要花费两个代币。但由于你曾经在部队服过役，所以能享受一个代币的优惠。$b$b我们暗月马戏团的成员非常感谢你所做的贡献。', `FemaleText_loc5`='在找舊版的蒸汽坦克嗎?$b$b我們有新版的讓你玩呢。$b$b通常，你會需要花費兩個代幣才能使用坦克的遙控裝置。但是因為你在軍事上的貢獻，我們給了你只要花一個代幣的折扣。$b$b我們暗月馬戲團感謝你的服務。', `FemaleText_loc7`='¿Estás buscando los antiguos tonques de vapor?$b$bBueno, tenemos algunos nuevos para que te entretengas.$b$bNormalmente, te costaría dos fichas usar el control remoto del tonque pero por los servicios militares que has prestado, tendrás un descuento de una ficha.$b$bEn la Feria de la Luna Negra te estamos agradecidos por tus servicios.' WHERE `ID`=53059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='我准备好了！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='準備開始玩! |cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Estoy listo para jugar! |cFF0008E8(Ficha de juego de la Luna Negra)|r', `FemaleText_loc1`='준비됐어요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='我准备好了！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='準備開始玩! |cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Estoy lista para jugar! |cFF0008E8(Ficha de juego de la Luna Negra)|r' WHERE `ID`=53060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 뼈일 것 같지 않아? 아니면 거인이나!', `MaleText_loc4`='你猜，它会不会来自一条巨龙？或者是一个巨人？', `MaleText_loc5`='你覺得這是龍的嗎?還是巨人的?', `MaleText_loc7`='¿Crees que es de un dragón? ¿O de un gigante?' WHERE `ID`=53061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 지옥불 성채를 무너뜨릴 계획입니다. 우선은 이 성루에서부터 시작합시다.', `MaleText_loc4`='我们将要攻陷地狱火堡垒，就从这些城墙开始。', `MaleText_loc5`='我們將攻陷地獄火堡壘，就從這座壁壘開始。', `MaleText_loc7`='Vamos a echar abajo la Ciudadela del Fuego Infernal, empezando por estas murallas.' WHERE `ID`=53062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보같이... 이건 용의 뼈가 아니야. 이건 엘레크나 그거 비슷한 생물의 뼈잖아.', `FemaleText_loc4`='蠢货，那不是龙骨。可能是雷象或者什么别的动物的骨头。', `FemaleText_loc5`='拜託，那才不是龍骨。八成是伊萊克獸還是什麼的。', `FemaleText_loc7`='Tonto, eso no es un hueso de dragón. Seguro que es de un elekk o algo así.' WHERE `ID`=53063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 지옥불 성채를 공격하라고 지시하셨네. 우린 외부로 노출된 이곳 성루에서부터 공격을 시작할 계획이야.', `MaleText_loc4`='酋长已经下令攻击地狱火堡垒，我们就从外面这些城墙开始。', `MaleText_loc5`='大酋長命令我們進攻地獄火堡壘，所以我們先從這些孤立的壁壘開始打起。', `MaleText_loc7`='El Jefe de Guerra ha ordenado la invasión de la Ciudadela del Fuego Infernal y hemos comenzado por estas murallas desprotegidas.' WHERE `ID`=53064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 네가 어떻게 알아?', `MaleText_loc4`='你怎么知道的？', `MaleText_loc5`='你怎麼會知道?', `MaleText_loc7`='¿Cómo lo sabes?' WHERE `ID`=53065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아슬아슬했군! 데스윙이 우릴 하늘에서 떨어뜨려 버렸네! 어쨌든 목적지에 거의 다 왔군. 고룡쉼터 사원을 향한 마지막 여정을 떠날 준비가 됐나?', `MaleText_loc4`='好险！死亡之翼的爪牙把我们从天上打了下来！但龙眠神殿已经近在咫尺了。大家准备好前进了吗？', `MaleText_loc5`='哇，差一點!死亡之翼把我們從空中吹了下來!不過我們也快到了。你準備好進行前往龍眠神殿的最後一段旅程了嗎?', `MaleText_loc7`='¡Ufff, ha estado cerca! Alamuerte nos acaba de hacer volar por los aires. Ya casi hemos llegado, ¿todo listo para los últimos momentos de nuestro viaje al Templo del Reposo del Dragón?' WHERE `ID`=53066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 출발하지요!', `MaleText_loc4`='是的，萨尔。我们开始吧！', `MaleText_loc5`='是的，索爾，我們動手吧!', `MaleText_loc7`='Sí, Thrall, ¡adelante!', `FemaleText_loc1`='준비됐습니다. 출발하지요!', `FemaleText_loc4`='是的，萨尔。我们开始吧！', `FemaleText_loc5`='是的，索爾，我們動手吧!', `FemaleText_loc7`='Sí, Thrall, ¡adelante!' WHERE `ID`=53067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피의 용광로는 내 동족의 어두운 과거를 보여주는 증거요.', `MaleText_loc4`='鲜血熔炉见证了我的族人们黑暗的过去。', `MaleText_loc5`='血熔爐是我的人民黑暗面的見證。', `MaleText_loc7`='El Horno de Sangre es un testamento del oscuro pasado de mi pueblo.' WHERE `ID`=53068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크를 처치하는 일이 즐겁고 말이 별로 없는 분이라면, 잘 오셨어요!$B$B그렇지 않다면 동쪽으로 조금만 가 보세요. 매년 이맘때 아주 예쁜 차원문이 열린다고 하더라고요.', `MaleText_loc4`='如果你喜欢屠杀兽人，又不爱唠叨，那么欢迎你！$B$B如果不是的话，那么东边就有一座可爱的传送门。我听说，只有在每年的这个时候，它才会特别可爱。', `MaleText_loc5`='如果你喜歡殺獸人，而且不囉嗦，歡迎加入!$B$B如果不是，東邊有個漂亮的傳送門，聽說這個時節風景特別漂亮。', `MaleText_loc7`='Si te encanta matar orcos y no hablas mucho, ¡estaré encantado de tenerte!$B$BSi no, hay un portal estupendo al este de aquí que me han contado que es una maravilla en esta época del año.' WHERE `ID`=53069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친구들이 무사하길...', `FemaleText_loc4`='但愿我的朋友们都没事……', `FemaleText_loc5`='希望我的朋友沒事...', `FemaleText_loc7`='Espero que mis amigos estén bien...' WHERE `ID`=53070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만약 이미 탈출했으면 어떡하죠? 저쪽 어딘가에서 절 찾고 있으면요?', `FemaleText_loc4`='或许他们已经逃出去了？万一他们在外面找我怎么办？', `FemaleText_loc5`='也許他們逃走了?說不定他們在外面找我?', `FemaleText_loc7`='Tal vez ya hayan escapado. ¿Y si están ahí fuera buscándome?' WHERE `ID`=53071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가들이 노예 일꾼을 부리고 있다고요? 놈들은 이 그릇된 행위의 죗값을 치르게 될 겁니다!', `FemaleText_loc4`='纳迦在使用奴隶劳工？他们必须为这种罪行付出代价！', `FemaleText_loc5`='納迦在使用奴隸?他們一定得為如此暴行付出代價!', `FemaleText_loc7`='¿Los nagas están empleando esclavos? ¡Pagarán por sus atropellos!' WHERE `ID`=53072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조치를 취할 수 있을 때 나가를 저지하고 장가르 습지대를 구해야 합니다!', `FemaleText_loc4`='我们必须尽快阻止纳迦，拯救赞加沼泽，否则就太迟了！', `FemaleText_loc5`='我們必須盡力阻止納迦並拯救贊格沼澤!', `FemaleText_loc7`='¡Debemos detener a los naga y salvar Marisma de Zangar mientras podamos!' WHERE `ID`=53073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나가들이 물을 사적인 용도로 쓰기 위해 모조리 뽑아내고 있습니다. 그 여파로 수많은 생명체들이 멸종하고 있죠.$b$b우리가 손을 쓰지 않는다면 이 죽어가는 땅에 생명이라곤 영영 찾아볼 수 없을 것입니다.', `FemaleText_loc4`='纳迦为了自己的目的，把所有的水都抽走了，这里的生物种群正在走向灭绝。$B$B如果我们不尽快采取行动，这个垂暮的世界上剩余的生物就会永远消失。', `FemaleText_loc5`='納迦為一己之私抽走了所有的水，害整個生態系統都瀕臨滅絕的危機。$B$B要是我們不做點什麼的話，這個垂死世界所殘存的寶貴生命都將會徹底消失。', `FemaleText_loc7`='Los nagas están extrayendo toda el agua para su propio uso; especies enteras están muriendo a consecuencia de ello.$B$BSi no hacemos algo pronto, la poca vida que queda en este mundo moribundo desaparecerá para siempre.' WHERE `ID`=53074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 원정대에 합류한 이유는 하나뿐입니다, $r님. 복수를 위해서죠.', `MaleText_loc4`='我加入这个远征队的目的只有一个，$r，那就是复仇。', `MaleText_loc5`='我加入遠征隊只為了一個理由，$r。那就是復仇。', `MaleText_loc7`='Me uní a esta expedición por una única razón, $r: ¡venganza!' WHERE `ID`=53075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 대부분은 아직 나가로부터 자유롭습니다. 하지만... 큰 고통에 시달리고 있죠. 시간이 얼마나 남았을지 모르겠습니다.', `MaleText_loc4`='这里的绝大部分地方还没有遭到纳迦的侵扰。可是……这片土地经历了深重的苦难。我不知道我们还有多少时间。', `MaleText_loc5`='這個地方已經大多脫離納迦的掌控了。但仍然...滿目瘡痍。我不知道我們還有多少時間。', `MaleText_loc7`='Este lugar se ha salvado en su mayoría de la invasión naga. Pero... sufre mucho. No sé cuánto tiempo nos queda.' WHERE `ID`=53076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 버섯은 보통 버섯과는 달라요. 이걸 먹는 자에게 엄청난 지혜와 청명함을 선사한다고 하죠.$B$B스포어가르로 몇 개 가져갈 겁니다.', `MaleText_loc4`='这些蘑菇和地表上的任何东西都不一样。据说，谁吃了它们，就能获得无比的智慧和清晰的头脑。$B$B我要带一点回孢子村去。', `MaleText_loc5`='這些蘑菇跟地面上的不太一樣。聽說它們能替吃的人帶來無比的智慧與明晰的思考。$B$B我要帶一些回去斯博格爾。', `MaleText_loc7`='Estos champiñones no se parecen en nada a los de la superficie. Dicen que proporcionan gran sabiduría y claridad a quien los come.$B$BMe llevaré unos cuantos a Esporaggar.' WHERE `ID`=53077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지하수렁에서 연구하고 배우는 건 인생에 한 번 올까 말까 한 기회입니다.$B$B방금 전까지 강제 노역소의 상자에 갇혀 있을 때는 죽은 것과 다름없었던 것 같네요...', `MaleText_loc4`='去幽暗沼泽进行研究和学习的机会一生只有一次，非常难得。$B$B尤其是想到我不久前还坐在奴隶围栏的笼子里，那时我和死人也没什么差别……', `MaleText_loc5`='能在深幽泥沼學習是一生一次的難得機會。$B$B想到我不久前還在奴隸監獄的箱子裡面，幾乎快死透了...', `MaleText_loc7`='Poder estudiar y aprender en La Sotiénaga es una oportunidad que se da una vez en la vida.$B$BY pensar que hace poco estaba al borde de la muerte sentado en una jaula en El Recinto de los Esclavos...' WHERE `ID`=53078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리얼 기술자 3인방이 스톰윈드에 가게를 열었습니다. 대성당 광장 남쪽의 대운하를 따라가면 찾을 수 있지요.$b$b세 바람의 마법상점이라는 가게입니다. 기묘한 기계들과 보라색 불빛을 찾아보면... 바로 찾을 수 있을 겁니다.$b$b그 3인방이 당신이 찾던 서비스를 제공해줄 것입니다.', `MaleText_loc4`='有三个虚灵技师在暴风城里开了一家店，就在教堂广场南边的运河沿岸。

店名叫“三缕风”。你只要找奇怪的机械和紫色的灯就对了……绝对不会找错的。

他们那里有你想要的服务。', `MaleText_loc5`='三位以太魔科技師在暴風城教堂廣場南邊的運河旁開了家店。

那家店的名字叫「三陣風」。看到奇怪的機械跟紫色的燈就沒錯了...你不會找不到的。

他們會提供你想要的服務。', `MaleText_loc7`='Un trío de tecnománticos etéreos ha abierto una tienda en Ventormenta, a lo largo del canal sur de la Plaza de la Catedral.

"Los Tres Vientos", se llama. Busca maquinaria extraña y luces moradas... no tiene pérdida.

Tienen exactamente el tipo de cosas que estás buscando.', `FemaleText_loc1`='에테리얼 기술자 3인방이 스톰윈드에 가게를 열었어요. 대성당 광장 남쪽의 대운하를 따라가면 찾을 수 있답니다.$b$b세 바람의 마법상점이라는 가게에요. 기묘한 기계들과 보라색 불빛을 찾아보면... 바로 찾을 수 있을 거예요.$b$b그 3인방이 당신이 찾던 서비스를 제공해줄 거예요.', `FemaleText_loc4`='有三个虚灵技师在暴风城里开了一家店，就在教堂广场南边的运河沿岸。

店名叫“三缕风”。你只要找奇怪的机械和紫色的灯就对了……绝对不会找错的。

他们那里有你想要的服务。', `FemaleText_loc5`='三位以太魔科技師在暴風城教堂廣場南邊的運河旁開了家店。

那家店的名字叫「三陣風」。看到奇怪的機械跟紫色的燈就沒錯了...你不會找不到的。

他們會提供你想要的服務。', `FemaleText_loc7`='Un trío de tecnománticos etéreos ha abierto una tienda en Ventormenta, a lo largo del canal sur de la Plaza de la Catedral.

"Los Tres Vientos", se llama. Busca maquinaria extraña y luces moradas... no tiene pérdida.

Tienen exactamente el tipo de cosas que estás buscando.' WHERE `ID`=53079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허 보관소', `MaleText_loc4`='虚空仓库', `MaleText_loc5`='虛空倉庫', `MaleText_loc7`='Depósito del vacío', `FemaleText_loc1`='공허 보관소', `FemaleText_loc4`='虚空仓库', `FemaleText_loc5`='虛空倉庫', `FemaleText_loc7`='Depósito del vacío' WHERE `ID`=53080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연합왕자 하라매드는 우리가 샤파르의 방을 빨리 찾아내지 못하면 내가 다음 실험 대상이 될 거라고 말하곤 했었다.$B$B농담이 아니었지.', `MaleText_loc4`='节点亲王哈拉迈德一直在威胁我说，如果我们不能尽快穿过沙法尔的警戒线，他就要拿我当下一个实验品。$B$B他可不是开玩笑的。', `MaleText_loc5`='奈薩斯王子哈拉瑪德一直告訴我，如果我們不趕快破除薩法爾的結界，我就會成為下一個實驗對象。$B$B他不是嚇唬我的。', `MaleText_loc7`='El príncipe-nexo Haramad me decía siempre que si no encontrábamos pronto la forma de superar el resguardo de Shaffar, yo sería el siguiente sujeto de prueba.$B$BNo se estaba marcando un farol.' WHERE `ID`=53081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"전문가"가 뭐냐고 했나? 그건 내가 모든 것에 대해 연구한다는 뜻이다! 난 네가 생각해낼 수 있는 어떤 주제에 대해서도, 지금까지 네가 만나본 사람이나 앞으로 만나볼 사람, 그 누구보다 더 자세히 알고 있다.$B$B샤파르의 방을 통과하는 건 아무 것도 아니야. 몰팔리우스가 내 말을 들었더라면 어디 한 군데 긁히지도 않았을 것이다. 그 녀석은 언제나 자기 방식대로만 일을 하는 게 문제야.', `MaleText_loc4`='你问什么是“杂学家”？那当然是指，我什么都研究！在你所能想象到的任何领域，我都是最博学的人，比你认识或者不认识的任何人知道的都多。$B$B穿过沙法尔的警戒线不算什么。要是莫法鲁斯肯听我的，他连一根寒毛都不会掉。他这个人，老是我行我素。', `MaleText_loc5`='什麼是『學家』?當然是表示我研究所有的事物!我對於任何你能想到的話題，比起任何你認識或未來會認識的人都還要來得博學。$B$B穿過薩法爾的結界根本就是小事一樁。當初莫法利厄司如果肯聽我的，他就會毫髮無傷。那傢伙啊，老是一意孤行。', `MaleText_loc7`='¿Qué es un "todólogo", dices? Vamos, ¡significa que lo estudio todo! Sé más de cualquier tema que cualquiera que conozcas o que puedas conocer.$B$BSuperar el resguardo de Shaffar no fue nada. Morphalius no habría sufrido ni un rasguño si me hubiese escuchado. Siempre hace las cosas a su manera.' WHERE `ID`=53082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 봐! 괜찮을 거라고 하더니! 지금 내가 괜찮아 보이나?', `MaleText_loc4`='你看看我！你跟我说不会有事的！你看我像没事的样子吗？', `MaleText_loc5`='看看我!你說我會沒事的!我看起來像沒事嗎?', `MaleText_loc7`='¡Mírame! Dijiste que estaría bien. ¿Te parece que estoy bien?' WHERE `ID`=53083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 문까지 데려다 줄 수는 있겠지, 몰팔리우스. 하지만 그걸 통과해야 하는 건 바로 너다.', `MaleText_loc4`='我只能给你指出那扇门，莫法鲁斯。最后还得要你自己走进去。', `MaleText_loc5`='我只能指引你門的方向，莫法利厄司。你得親自穿過去才行。', `MaleText_loc7`='Solo puedo mostrarte la puerta, Morphalius. Tú eres el que tiene que atravesarla.' WHERE `ID`=53084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 고대 신의 하수인들이 나타납니다!', `MaleText_loc4`='上古之神的爪牙突然现身了！', `MaleText_loc5`='古神的爪牙在附近成形!', `MaleText_loc7`='¡La aparición de los dioses antiguos se materializa cerca!', `FemaleText_loc1`='근처에 고대 신의 하수인들이 나타납니다!', `FemaleText_loc4`='上古之神的爪牙突然现身了！', `FemaleText_loc5`='古神的爪牙在附近成形!', `FemaleText_loc7`='¡La aparición de los dioses antiguos se materializa cerca!' WHERE `ID`=53085;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽은 자는 이 세계에 속할 수 없습니다.$B$B그런데 왜 우리는 그들을 안식에 들게 한 뒤에도 계속 찾아 헤매는 것일까요?', `FemaleText_loc4`='亡者不属于这个国度。$B$B那我们为什么还要在让他们安息之后，再不断地寻找他们呢？', `FemaleText_loc5`='亡者不屬於這個世界。$B$B那我們為何又在讓他們安息後又一直打擾他們?', `FemaleText_loc7`='Los muertos no pertenecen a este reino.$B$B¿Por qué los perseguimos constantemente después de matarlos?' WHERE `ID`=53086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한때 아키나이 납골당은 우리들에게 신성한 곳이었어요. 우리가 사랑하던 이들의 영혼이 잠들어 있었으니까요. 이곳에서 멀리 떨어진 곳에 있는 이들도 성지를 순례하러 많이 오곤 했었답니다.$B$B그러한 일들은 이제 옛날 이야기가 되어버렸어요. 어떤 존재가 납골당의 유골을 극진히 보살피던 아키나이를 붙잡고 있어요. 영혼들이 납골당을 산산조각내기 전에 어서 도와주셔야만 해요.', `FemaleText_loc4`='这些地穴对我的族人来说，曾经非常神圣。因为里面有我们的亲人的灵魂。许多人不远万里赶来这里朝圣。$B$B但那已经是很久之前的事了。某种力量控制了奥金尼，这个曾经与亡者们戚戚相关的地方。我请求你，在灵魂们捣毁地穴之前，做点什么吧。', `FemaleText_loc5`='從前，這座墓穴是我們的聖地，裡頭收納了我們摯愛親人的遺骨與魂魄。還有許多人長途跋涉到此來朝聖。$B$B但那樣的時代已經消失了。奧奇奈人員原本都是懷著深深敬意在服侍亡者，如今卻受到了不明外力的影響。請你一定要幫幫我們，別讓失控的亡魂把這座墓窖給毀了。', `FemaleText_loc7`='En otro tiempo estas criptas eran sagradas para mi pueblo. Albergaban los espíritus de nuestros seres queridos. Mucha gente recorría grandes distancias hasta aquí en peregrinación.$B$BEse tiempo pasó hace mucho. Algo retiene a los Auchenai que solían preocuparse tanto de sus muertos. Tienes que ayudarnos antes de que los espíritus devasten la cripta.' WHERE `ID`=53087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼의 세계를 들여다보아서는 안 돼...', `FemaleText_loc4`='我们不应该窥视灵魂的国度……', `FemaleText_loc5`='我們不該窺探靈魂的國度...', `FemaleText_loc7`='No deberíamos fisgar en el mundo de los espíritus...' WHERE `ID`=53088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 자기들이 어떤 문을 열고 있는지 모르지...', `FemaleText_loc4`='他们根本不知道自己打开了一扇怎样的门……', `FemaleText_loc5`='他們不知道他們開了什麼門...', `FemaleText_loc7`='Desconocen las puertas que están abriendo...' WHERE `ID`=53089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선원의 숨이 막혀 옵니다!', `MaleText_loc4`='船员就快窒息了！', `MaleText_loc5`='船員們快窒息了!', `MaleText_loc7`='¡El tripulante se está asfixiando!', `FemaleText_loc1`='선원의 숨이 막혀 옵니다!', `FemaleText_loc4`='船员就快窒息了！', `FemaleText_loc5`='這船員快窒息了!', `FemaleText_loc7`='¡El tripulante se está asfixiando!' WHERE `ID`=53091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦기 전에 응급치료 기술을 사용하여 선원을 회복시키십시오!', `MaleText_loc4`='快使用医疗技能救助这名船员，否则就太迟了！', `MaleText_loc5`='使用你的醫療技能來及時救活船員!', `MaleText_loc7`='¡Utiliza tus facultades médicas para reanimar al tripulante antes de que sea demasiado tarde!', `FemaleText_loc1`='너무 늦기 전에 응급치료 기술을 사용하여 선원을 회복시키십시오!', `FemaleText_loc4`='快使用医疗技能救助这名船员，否则就太迟了！', `FemaleText_loc5`='使用你的醫療技能來及時救活船員!', `FemaleText_loc7`='¡Utiliza tus facultades médicas para reanimar al tripulante antes de que sea demasiado tarde!' WHERE `ID`=53092;
