UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할라이, 거긴 아무것도 없잖니. 잠시만이라도 조용히 있어 주렴.', `FemaleText_loc4`='那里什么都没有，哈雷。好了，我只要几分钟就行了，安静一会吧。', `FemaleText_loc5`='那裡什麼都沒有，哈勒。麻煩你，我只需要片刻的寧靜。', `FemaleText_loc7`='Ahí no hay nada, Ha''lei. Solo necesito unos pocos minutos más de silencio.' WHERE `ID`=53095;
