UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장치에 달린 여러 기계를 어떻게 작동시켜야 할지 전혀 모르겠습니다. 하지만 어딘가 익숙한 느낌이 머릿속을 가득 채워 떨쳐버릴 수가 없습니다.$B$B우선은 그냥 내버려 두는 게 좋을 것 같습니다.', `MaleText_loc4`='你根本就不懂怎么操作这个设备上的各种机械，可你心中却总有一种挥之不去的熟悉感。$B$B最好还是先别去管它。', `MaleText_loc5`='你完全不清楚怎樣操作這個裝置上的各種機關，但是你卻很難擺脫對它的一種熟悉感。$B$B也許你最好還是不要去碰它比較好。', `MaleText_loc7`='No tienes ni la menor idea de cómo funcionan los diversos mecanismos de este aparato, sin embargo tienes un sentimiento de familiaridad del que no te puedes desprender.$B$BSeguramente lo mejor será dejarlo estar.' WHERE `ID`=53103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통통 전차가 당신을 조준합니다!', `MaleText_loc4`='一辆坦克瞄准了你！', `MaleText_loc5`='一台坦克正瞄準著你!', `MaleText_loc7`='¡Un tonque te está apuntando!' WHERE `ID`=53104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자여! 더는 너희를 따라갈 수 없구나. 내 축복을 받고 시간의 모래시계를 사용해서 무르도즈노를 쓰러뜨려라!', `MaleText_loc4`='凡人们！我不能再跟你们前进了——接受我的祝福，使用时光沙漏击败姆诺兹多吧！', `MaleText_loc5`='凡人!我不能繼續跟著你們了 - 接受我的祝福，使用時光沙漏來擊敗姆多茲諾!', `MaleText_loc7`='¡Mortales! No puedo seguirlos; ¡acepten mi bendición y utilicen el reloj de arena de tiempo para derrotar a Murozond!' WHERE `ID`=53105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 있는 영혼들은 오랫동안 괴롭힘을 받아왔습니다. 우리는 단지 안식을 원할 뿐입니다.', `FemaleText_loc4`='这里的灵魂已经被折磨了很久。我们只想安息。', `FemaleText_loc5`='這些靈魂已經受到長久的折磨。我們只想永眠。', `FemaleText_loc7`='Los espíritus de este lugar llevan mucho tiempo torturados. Solo queremos descansar.' WHERE `ID`=53106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 판다렌은 자신의 운명을 찾아야만 하네. 그게 전사가 됐든 농부가 됐든 우리 각자에게 맞는 자리가 있고, 그 모든 자리가 나름대로 중요하다네.', `MaleText_loc4`='所有熊猫人都要探寻并确认自己的命运。无论是战士还是农夫，总有一个适合我们的角色，每个角色都具有独一无二的重要性。', `MaleText_loc5`='每個熊貓人都必須搜尋並了解他們的天命。不論是戰士或農夫，我們都有適合自己的立場。每種立場都具有獨特的重要性。', `MaleText_loc7`='Todos los pandaren han de buscar y descubrir su propio destino. Da igual ser guerrero o granjero, todos tenemos un lugar que nos gusta y cada lugar es de una importancia única.' WHERE `ID`=53107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투슈이의 가르침은 균형 잡힌 관점을 찾는 것입니다. 문제가 있다면 명상과 고찰을 통해 가장 효과적인 해결책을 찾을 수 있습니다. 수련과 수양을 통해 우리의 몸을 갈고닦아, 우리의 뜻을 실현하는 완벽한 도구로 만들 수 있습니다.$B$B투슈이의 가르침을 따른다는 것은, 단련된 정신과 완전무결한 외형으로 존경받는 것입니다.', `FemaleText_loc4`='土水派的修行之道是获得真知的途径之一。通过沉思和冥想，我们发现我们的修行之道是解决问题最有效的方法。通过练习和修正，我们让自己的意志完美支配自己的身体。$B$B要学习土水派的修行之道，必须具有坚强的意志和完美的体魄。', `FemaleText_loc5`='土水之道是修習精深洞察力的道理。藉著冥想和深思，我們找出最高效解決一切問題的方法。透過反覆練習，我們將身體磨礪成承載意志的絕佳工具。$B$B要遵循土水之道，你必須了解沉靜心靈和無瑕身姿的重要。', `FemaleText_loc7`='El camino de los tushui consiste en obtener perspectiva. A través de la meditación y la consideración, descubrimos la mejor solución a los problemas. A través de la práctica y la disciplina, ponemos a punto nuestros cuerpos para que sean un reflejo de nuestra voluntad.$B$BVivir como un tushui es vivir respetado por la mente templada y la forma impecable.' WHERE `ID`=53108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행하지 않는 것이야말로 진정한 죄야.', `MaleText_loc4`='无为乃罪。', `MaleText_loc5`='沒有行動才是真正的錯。', `MaleText_loc7`='El único y verdadero crimen es la pasividad.' WHERE `ID`=53109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 어두운 달빛이 비칩니다!', `MaleText_loc4`='附近出现了一泓黑暗月光！', `MaleText_loc5`='一道黑暗的月光出現在附近!', `MaleText_loc7`='¡Un charco de luz de Luna oscura aparece cerca!', `FemaleText_loc1`='근처에 어두운 달빛이 비칩니다!', `FemaleText_loc4`='附近出现了一泓黑暗月光！', `FemaleText_loc5`='一道黑暗的月光出現在附近!', `FemaleText_loc7`='¡Un charco de luz de Luna oscura aparece cerca!' WHERE `ID`=53110;
