UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈둥아, 여길 보렴. $c|1이;가; 우릴 구하러 왔구나!', `MaleText_loc4`='雪雾，快看，有个$c来救我们了！', `MaleText_loc5`='看啊雪噴，有個$c來救我們了!', `MaleText_loc7`='¡Mira, Ventonieve! ¡Ha venido $gun:una; $c a rescatarnos!' WHERE `ID`=53114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, $c님! 여기 아가씨 좀 도와주실래요?', `FemaleText_loc4`='嘿，$c！帮帮我，好吗？', `FemaleText_loc5`='嘿，$c!給我這女孩幫個忙，行嗎?', `FemaleText_loc7`='¡Oye, $c! Échame una mano, ¿quieres?' WHERE `ID`=53115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 늦었습니다, $n 님. 저 원숭이들이 현장감독과 그 일행들을 모두 살해한 것 같습니다.', `FemaleText_loc4`='我们太迟了，$n。看来这些猴子已经杀害了工头和他的工人。', `FemaleText_loc5`='我們晚了一步，$n。看來那些猴子把工頭和他的屬下都給宰了。', `FemaleText_loc7`='Hemos llegado tarde, $n. Parece que los monos masacraron al supervisor y a su equipo.' WHERE `ID`=53116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮추십시오, $r님. 저는 이제 세데크 전당에서 환영받는 존재가 아닙니다.', `MaleText_loc4`='小声点，$r。塞泰克已经不欢迎我了。', `MaleText_loc5`='輕聲點，$r。我在塞司克這裡已經不受歡迎了。', `MaleText_loc7`='Baja la voz, $r. Ya no soy bienvenido en Sethekk.' WHERE `ID`=53117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정할 것 없네, $c 친구. 이 보호막만 있으면 아라코아는 나를 볼 수 없으니까.$B$B이곳에 볼 일이 좀 있어서 왔다네.', `MaleText_loc4`='不用担心，$c，有了这道屏障，鸦人就看不见我了。$B$B我来这里是有公务在身的。', `MaleText_loc5`='不用擔心，$c。只要這個屏障存在，阿拉卡就看不到我。$B$B我來這裡是有目的的。', `MaleText_loc7`='No te preocupes, $c, con esta barrera los arakkoa no pueden verme.$B$BHe venido por negocios.' WHERE `ID`=53118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈이! 안경도 아무 소용이 없잖아!', `MaleText_loc4`='我的眼睛！这眼镜没用啊！', `MaleText_loc5`='我的眼睛!這護目鏡屁用也沒有!', `MaleText_loc7`='¡Mis ojos! ¡Las gafas no me hacen nada!' WHERE `ID`=53119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장군 칼리스레쉬는 쓰러질 것입니다!', `FemaleText_loc4`='督军卡利瑟里斯必败！', `FemaleText_loc5`='督軍卡利斯瑞會倒下!', `FemaleText_loc7`='¡El señor de la guerra Kalithresh caerá!' WHERE `ID`=53121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 기괴한 어둠과 영원한 밤이 깔려 있다. 조심해라, 영웅들이여. 빛에서 멀어지지 마라.', `MaleText_loc4`='这里的黑暗诡异难测，仿佛无尽的永夜。小心，英雄们，不要远离月光的庇护。', `MaleText_loc5`='這裡的黑暗並不尋常，像是持續永恆的午夜。小心點，英雄們，別離光線太遠。', `MaleText_loc7`='Hay una oscuridad sobrenatural en este lugar, una noche eterna. Tengan cuidado, héroes, y no se alejen de la luz.' WHERE `ID`=53122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 공격해야 하오. 내가 놈들을 조각내겠소!', `MaleText_loc4`='我们必须立刻攻击。我要把他们撕成碎片！', `MaleText_loc5`='我們現在就該攻擊。我會把他們撕碎!', `MaleText_loc7`='Deberíamos atacar ahora. ¡Los haré pedazos!' WHERE `ID`=53123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 자살행위입니다, 클로 님! 너무 위험해요.', `FemaleText_loc4`='那是自杀，克劳恩！这太危险了。', `FemaleText_loc5`='這根本是自殺，裂爪!這太危險了。', `FemaleText_loc7`='¡Es un suicidio, Zarpa! Es demasiado peligroso.' WHERE `ID`=53124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐길 수 있는 게임이 더 없습니다.', `MaleText_loc4`='你不能再参加游戏了。', `MaleText_loc5`='已經沒有遊戲能讓你玩了。', `MaleText_loc7`='Se te acabaron las partidas.', `FemaleText_loc1`='즐길 수 있는 게임이 더 없어요.', `FemaleText_loc4`='你不能再参加游戏了。', `FemaleText_loc5`='已經沒有遊戲能讓你玩了。', `FemaleText_loc7`='Se te acabaron las partidas.' WHERE `ID`=53125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 뭘 원하시는 겁니까?', `MaleText_loc4`='你想知道什么？', `MaleText_loc5`='你現在想幹嘛?', `MaleText_loc7`='¿Qué es lo que quieres, ahora?', `FemaleText_loc1`='이제 뭘 원하시는 거죠?', `FemaleText_loc4`='你想知道什么？', `FemaleText_loc5`='你現在想幹嘛?', `FemaleText_loc7`='¿Qué es lo que quieres, ahora?' WHERE `ID`=53126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 뒤로 물러나서 다른 사람도 게임을 즐기게 해 주십시오.', `MaleText_loc4`='让开点，让其他人也来玩玩吧。', `MaleText_loc5`='請退開，讓其他人有機會玩。', `MaleText_loc7`='Échate a un lado y deja que otros jueguen.', `FemaleText_loc1`='이제 뒤로 물러나서 다른 사람도 게임을 즐기게 해 주세요.', `FemaleText_loc4`='让开点，让其他人也来玩玩吧。', `FemaleText_loc5`='請退開，讓其他人有機會玩。', `FemaleText_loc7`='Échate a un lado y deja que otros jueguen.' WHERE `ID`=53127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시들어 가는 연꽃은 겨울을 예고하는 첫 징조일세. 수천 년 동안 셴진 수에는 찾아오지 않았던 겨울이지.', `MaleText_loc4`='凋谢的莲花是冬季降临的征兆。数千年来，神真子的背上从未经历过寒冬。', `MaleText_loc5`='這枯萎的蓮花就是寒冬的前兆，預示數千年來不曾降臨神真子的冬天即將到來。', `MaleText_loc7`='Los lotos marchitos son la primera señal del invierno; un invierno que no ha llegado a Shen-zin Su desde hace milenios.' WHERE `ID`=53128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "투슈이의 가르침... 인내와 명상을 통한 깨우침... 지조 있는 삶."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“土水之道……即通过耐心和冥想获得启迪……是一种自律的生活态度。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「土水之道...耐性與冥想的啟發...紀律的人生。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "El camino de los tushui... Iluminación a través de la paciencia y la meditación... Una vida de principios".' WHERE `ID`=53129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 모습이 흐릿해지더니 사라집니다.', `MaleText_loc4`='李飞大师消失了。', `MaleText_loc5`='李飛大師的身形消失了。', `MaleText_loc7`='El maestro Li Fei desaparece lentamente.' WHERE `ID`=53130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람소환사 클로가 으르렁댑니다.', `MaleText_loc4`='唤风者克劳恩大声咆哮着。', `MaleText_loc5`='喚風者裂爪低吼了幾聲。', `MaleText_loc7`='Clamavientos Zarpa gruñe.' WHERE `ID`=53131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦기 전에 여기 나가가 퍼뜨린 질병을 막아야 합니다!', `MaleText_loc4`='我们必须控制住纳迦散播到这里的疾病，否则就太迟了！', `MaleText_loc5`='我們必須在事態無可挽救之前控制住納迦放出的疾病!', `MaleText_loc7`='¡Tenemos que contener la enfermedad que han extendido los nagas en este lugar antes de que sea demasiado tarde!' WHERE `ID`=53132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 갑자기 나타났습니다!', `MaleText_loc4`='它们从四面八方涌过来了！', `MaleText_loc5`='他們就這樣憑空跑出來!', `MaleText_loc7`='¡Han salido de la nada!', `FemaleText_loc1`='놈들이 갑자기 나타났어요!', `FemaleText_loc4`='它们从四面八方涌过来了！', `FemaleText_loc5`='他們就這樣憑空跑出來!', `FemaleText_loc7`='¡Han salido de la nada!' WHERE `ID`=53133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 저들과는 달라 보이는데... 대체 누구십니까?', `MaleText_loc4`='你不像是他们的人……你是谁？', `MaleText_loc5`='你看起來不像和他們是一伙的...你是誰?', `MaleText_loc7`='No pareces $guno:una; de ellos... ¿Quién eres?', `FemaleText_loc1`='당신은 저들과는 달라 보이는데... 대체 누구신가요?', `FemaleText_loc4`='你不像是他们的人……你是谁？', `FemaleText_loc5`='你看起來不像和他們是一伙的...你是誰?', `FemaleText_loc7`='No pareces $guno:una; de ellos... ¿Quién eres?' WHERE `ID`=53134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나에 님 댁으로 가십시오. 그곳은 안전합니다.', `MaleText_loc4`='到韩妮的房子去。那里很安全。', `MaleText_loc5`='到漢妮的房子去。那裡很安全。', `MaleText_loc7`='Ve hasta la casa de Hanae. Es un lugar seguro.', `FemaleText_loc1`='하나에 님 댁으로 가세요. 그곳은 안전해요.', `FemaleText_loc4`='到韩妮的房子去。那里很安全。', `FemaleText_loc5`='到漢妮的房子去。那裡很安全。', `FemaleText_loc7`='Ve hasta la casa de Hanae. Es un lugar seguro.' WHERE `ID`=53135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 그냥 앉아 있을 순 없소!', `MaleText_loc4`='我们不能这样干坐着！', `MaleText_loc5`='我們不能什麼事都不做!', `MaleText_loc7`='¡No podemos quedarnos aquí sentados!' WHERE `ID`=53136;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수가 너무 많습니다. 칼리스레쉬의 전 병력이 여기 있는 것 같아요.', `FemaleText_loc4`='他们人太多了。卡利瑟里斯带来了整整一支大军。', `FemaleText_loc5`='他們的數量太多了。卡利斯瑞根本就是有一整支軍隊在這裡。', `FemaleText_loc7`='Son demasiados. Kalithresh tiene todo un ejército aquí abajo.' WHERE `ID`=53137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청금석 용제단에 남은 건 이것뿐이다. 거대한 전투가 이 버림받은 곳 밖으로 나가는 시간의 길을 닫아버렸지. 땅 곳곳에 떨어진 파편을 합치고 갇힌 영혼을 쓰러뜨려야만 나갈 수 있다.', `MaleText_loc4`='这里就是碧蓝巨龙圣地的遗迹。一场大战摧毁了这片废墟通往外界的时间流。你必须修复散落在各个角落里的碎片，击败被禁锢的灵魂，才能继续前进。', `MaleText_loc5`='這裡是蒼藍龍殿僅存的一切了。一場慘烈的戰役把離開這裡的時間之道給擊碎了。你必須收集散落在地上的碎片並重建它，然後擊敗困在其中的靈魂，才能繼續。', `MaleText_loc7`='Esto es lo que queda del Santuario de Dragones Azul. Una gran batalla devastó los portales del tiempo que salían de este lugar maldito. Tienes que reconstruir los fragmentos repartidos por el suelo y derrotar al espíritu atrapado para seguir adelante.' WHERE `ID`=53138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바이트의 주문이 영영 지속되진 않을 거요.', `MaleText_loc4`='拜特的法术不可能永远持续下去。', `MaleText_loc5`='拜特的法術不會一直持續下去的。', `MaleText_loc7`='El hechizo de Mordedura no va a durar para siempre.' WHERE `ID`=53139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我能幫你什麼嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=53140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아서 이동하고 싶습니다.', `MaleText_loc4`='我要飞行。', `MaleText_loc5`='我想要透過飛行進行移動。', `MaleText_loc7`='Me gustaría viajar por el aire.', `FemaleText_loc1`='날아서 이동하고 싶어요.', `FemaleText_loc4`='我要飞行。', `FemaleText_loc5`='我想要透過飛行進行移動。', `FemaleText_loc7`='Me gustaría viajar por el aire.' WHERE `ID`=53141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요하십니까?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能幫你什麼嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=53142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 이제 가 보겠습니다.', `MaleText_loc4`='谢谢你，我马上就去。', `MaleText_loc5`='謝謝你，我走了。', `MaleText_loc7`='Gracias, me voy.', `FemaleText_loc1`='고마워요. 이제 가 볼게요.', `FemaleText_loc4`='谢谢你，我马上就去。', `FemaleText_loc5`='謝謝你，我走了。', `FemaleText_loc7`='Gracias, me voy.' WHERE `ID`=53143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요하십니까?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我能幫你什麼嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=53144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 누구신지는 모르겠지만, 정말 감사합니다.', `MaleText_loc4`='我不知道你是谁，但我对你感激不尽。', `MaleText_loc5`='我不知道你是誰，但我感謝你。', `MaleText_loc7`='No sé quién eres, pero cuentas con mi gratitud.', `FemaleText_loc1`='당신이 누구신지는 모르겠지만, 정말 고마워요.', `FemaleText_loc4`='我不知道你是谁，但我对你感激不尽。', `FemaleText_loc5`='我不知道你是誰，但我感謝你。', `FemaleText_loc7`='No sé quién eres, pero cuentas con mi gratitud.' WHERE `ID`=53145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇을 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我能幫你什麼嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=53146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기엔 아무것도 남지 않았다. 오직 죽음과 슬픔뿐이지.', `FemaleText_loc4`='这里空无一物，留给你们的只有死亡和悲伤。', `FemaleText_loc5`='在這裡，等待著你的只有死亡和哀傷。', `FemaleText_loc7`='Aquí no les espera nada mas que muerte y sufrimiento.' WHERE `ID`=53147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 너를 덮는다. 엘룬의 빛이 유일한 구원일지니.', `FemaleText_loc4`='黑暗围绕着你，艾露恩之光是你的唯一救赎。', `FemaleText_loc5`='黑暗包圍著你，只有伊露恩之光才能拯救你。', `FemaleText_loc7`='La oscuridad los rodea, la luz de Elune es su única salvación.' WHERE `ID`=53148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잊혀진 이곳에서 달빛이 지친 네 영혼에 휴식을 안기리라.', `FemaleText_loc4`='在这遗忘之地，月光能让你们疲惫的灵魂得到安息。', `FemaleText_loc5`='月光能夠在這裡為你疲倦的靈魂帶來寧靜。', `FemaleText_loc7`='La luz de la luna puede traer descanso a sus almas en este lugar olvidado.' WHERE `ID`=53149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤에 몸을 맡겨라. 엘룬이 필멸자의 감옥에서 널 구원하리라.', `FemaleText_loc4`='投入暗夜的怀抱，艾露恩会指引你们逃离凡尘。', `FemaleText_loc5`='投入夜晚的懷抱，伊露恩就會引領你脫離凡軀的桎梏。', `FemaleText_loc7`='Entréguense a la noche, Elune los guiará para que abandonen esta prisión mortal.' WHERE `ID`=53150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 길을 택했군. 어머니 달이시여, 절 인도하십시오. 길 잃은 영혼들에게 안식을 허락하십시오.', `FemaleText_loc4`='你们选择了一条黑暗的道路。月亮母亲啊，指引我的双手，让我为这些可悲的灵魂带去安宁。', `FemaleText_loc5`='你選擇了一條黑暗之路。月亮之母啊，引領我的手，使我能替這些不正常的靈魂帶來安息。', `FemaleText_loc7`='Han elegido un camino de oscuridad. Madre Luna, guía mi mano y permíteme liberar a estas almas desdichadas.' WHERE `ID`=53151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달의 여신이여, 빛이 약해집니다! 당신의 인도가 필요합니다!', `FemaleText_loc4`='月之女神，您的光辉黯淡了！失去指引，我已迷失！', `FemaleText_loc5`='月之女神啊，你的光芒變暗了!沒有你的指引，我會迷失的!', `FemaleText_loc7`='¡Diosa luna, tu luz se atenúa! ¡Estoy perdida sin tu amparo!' WHERE `ID`=53152;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 다가옵니다... 눈이 흐려집니다...', `FemaleText_loc4`='黑暗正在逼近……阴影遮蔽了我的眼睛……', `FemaleText_loc5`='黑暗正在靠近...我的眼前晦暗不明...', `FemaleText_loc7`='La oscuridad se cierne... mi vista se nubla…' WHERE `ID`=53153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머니 달이시여, 빛이 안 보입니다! 당신의 딸이... 홀로 어둠에 갇혔습니다!', `FemaleText_loc4`='月亮母亲，我看不见您的光辉了！您的女儿正在黑暗中徘徊！', `FemaleText_loc5`='月亮之母，我無法再看到你的光芒!你的女兒獨自在黑暗中!', `FemaleText_loc7`='¡Madre Luna, ya no puedo ver tu luz! ¡Tu hija está sola en la oscuridad!' WHERE `ID`=53154;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='평화로운 엘룬의 빛이 이 어두운 시간 속에서 너희 영혼을 보듬으리라.', `FemaleText_loc4`='愿艾露恩安详的光辉在黑暗中抚慰你们的灵魂。', `FemaleText_loc5`='讓伊露恩平和的光芒在黑暗的時刻安撫你的靈魂。', `FemaleText_loc7`='Dejen que la luz de Elune sosiegue sus almas en estos tiempos oscuros.' WHERE `ID`=53155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠 속에서 엘룬의 인도를 받아라.', `FemaleText_loc4`='艾露恩指引你们穿过黑夜。', `FemaleText_loc5`='伊露恩在黑夜指引你。', `FemaleText_loc7`='Que Elune los guíe a través de la noche.' WHERE `ID`=53156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤의 눈이여, 어둠을 꿰뚫어라!', `FemaleText_loc4`='暗夜之眼啊，刺破这黑暗吧！', `FemaleText_loc5`='夜之眼啊，破除黑暗!', `FemaleText_loc7`='¡Ojos de la noche, penetren en esta oscuridad!' WHERE `ID`=53157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 창이여, 밤을 쫓아내라!', `FemaleText_loc4`='艾露恩之矛，驱散这黑夜吧！', `FemaleText_loc5`='伊露恩之矛啊，擊退黑夜吧!', `FemaleText_loc7`='¡Lanza de Elune, haz retroceder a la noche!' WHERE `ID`=53158;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제... 달빛이... 보입니다. 너무나도... 아름답군요...', `FemaleText_loc4`='我看见月亮的光辉了……如此清晰。真是……太美了……', `FemaleText_loc5`='我能...看到月亮之光...如此清晰。好美啊...', `FemaleText_loc7`='Ahora veo... la luz de la luna... tan claramente. Es... hermosa...' WHERE `ID`=53159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t하늘에서 |cFFFF0000|Hspell:102241|h[엘룬의 눈물]|h|r이 떨어집니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[艾露恩之泪]|h|r开始从天空落下！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[伊露恩之淚]|h|r開始從空中落下!', `MaleText_loc7`='|TInterfaceIconsability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[Lágrimas de Elune]|h|r empiezan a caer del cielo.', `FemaleText_loc1`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t하늘에서 |cFFFF0000|Hspell:102241|h[엘룬의 눈물]|h|r이 떨어집니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[艾露恩之泪]|h|r开始从天空落下！', `FemaleText_loc5`='|TInterface\\Icons\\ability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[伊露恩之淚]|h|r開始從空中落下!', `FemaleText_loc7`='|TInterfaceIconsability_druid_starfall.blp:20|t |cFFFF0000|Hspell:102241|h[Lágrimas de Elune]|h|r empiezan a caer del cielo.' WHERE `ID`=53160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲은 그림리어 부족 거야. 우리 땅에 발을 들이면 모조리 없애 버리겠어.', `MaleText_loc4`='这片森林属于恐目部族。闯进来的人都要死。', `MaleText_loc5`='這片森林是嚴睨部族的。我們會把膽敢擅闖我們地盤的傢伙都宰掉。', `MaleText_loc7`='Este boske pertenece a la tribu Vista Vil. Mataremos a todo el ke pise nuestro territorio.' WHERE `ID`=53161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 이쪽입니다!', `MaleText_loc4`='嘿，在这儿呢！', `MaleText_loc5`='嘿，在這裡!', `MaleText_loc7`='¡Eh, aquí!' WHERE `ID`=53162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 발 뻗고 잘 생각은 하지도 마. 우린 돌아올 거야. 그때는 너희 모두 영원히 박살내 주마!', `MaleText_loc4`='哼，我们会趁你们睡着的时候反攻。下一次，你们就死定了！', `MaleText_loc5`='別睡得太安穩，因為我們會回來的。下一次，我們會讓你永世不得超生!', `MaleText_loc7`='No duermas mucho porke volveremos. Y, la próxima vez, ¡akabaremos kontigo de una vez por todas!' WHERE `ID`=53163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼리스레쉬 장군에게 가려면 기계박사 스팀리거와 풍수사 세스피아를 쓰러뜨리고 주 저장실 접근 장치까지 가야 합니다.$B$B장치에 도착하여 단추 몇 개만 누르면 주 저장실로 가는 문이 열릴 겁니다!', `MaleText_loc4`='如果你想要挑战督军卡利瑟里斯，就必须先击败机械师斯蒂里格和水术师瑟丝比娅，这样才能接触到主厅控制面板。$B$B然后，你只要按下面板上的几个按钮，就能打开通向主厅的大门了！', `MaleText_loc5`='如果你想要到達督軍卡利斯瑞那裡，你必須先擊敗機電師蒸汽操控者和水占師希斯比亞，來使用主房間通道面板。$B$B你只要在那些東西上面狂按幾個按鈕，前往主房間的門就會打開了!', `MaleText_loc7`='Si quieres llegar hasta el señor de la guerra Kalithresh, tendrás que derrotar primero al mekigeniero Vaporino y a la hidromántica Thespia para poder llegar hasta el panel de acceso de la cámara principal.$B$B¡Aporreas unos cuantos botones de esos y la cámara principal se abrirá de par en par!' WHERE `ID`=53164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도... 도... 도와주십시오! 병사들... 아니, 우린 공격받고 있습니다!', `MaleText_loc4`='救……救命！我的人……我们遭到了攻击！', `MaleText_loc5`='救、救救命!我的人...我們被攻擊了!', `MaleText_loc7`='¡S-s-socorro! Mis hombres y yo... ¡Nos atacan!' WHERE `ID`=53165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐죠? 절 구해주러 오셨습니까? $r님, 여깁니다! 도와주십시오!', `MaleText_loc4`='什么？有人来救我们了？这边，$r，救救我们！', `MaleText_loc5`='咦?救援來了嗎?$r，快來這兒!幫幫我們!', `MaleText_loc7`='¿Qué? ¿Veo rescatadores? ¡Aquí, $r! ¡Ayúdanos!' WHERE `ID`=53166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t티란데가 |cFFFF0000|Hspell:102472|h[달의 인도]|h|r를 얻습니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t泰兰德获得了|cFFFF0000|Hspell:102472|h[月神指引]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t 泰蘭妲獲得了|cFFFF0000|Hspell:102472|h[月神引導]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_druid_lunarguidance.blp:20|t ¡Tyrande consigue |cFFFF0000|Hspell:102472|h[Guía de la Luna]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t티란데가 |cFFFF0000|Hspell:102472|h[달의 인도]|h|r를 얻습니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t泰兰德获得了|cFFFF0000|Hspell:102472|h[月神指引]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\ability_druid_lunarguidance.blp:20|t 泰蘭妲獲得了|cFFFF0000|Hspell:102472|h[月神引導]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_druid_lunarguidance.blp:20|t ¡Tyrande consigue |cFFFF0000|Hspell:102472|h[Guía de la Luna]|h|r!' WHERE `ID`=53167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우악! 민둥머리 놈들 더 온다. 족장, 지금 도망가야 해요!', `MaleText_loc4`='啊呃！鸟蛋人越来越多了。酋长，我们最好赶紧逃跑！', `MaleText_loc5`='啊喔!更多蛋蛋人跑來了。老大，我們最好快逃!', `MaleText_loc7`='¡Uh, uh! Vienen más hombres huevo. Jefe, ¡mejor korrer!' WHERE `ID`=53168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악! 따가워!', `MaleText_loc4`='啊！痛死了！', `MaleText_loc5`='啊!!好疼啊!', `MaleText_loc7`='¡Aj! ¡Eskuece!' WHERE `ID`=53169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 썬더 블러프, 연체금 2,063,000골드.', `MaleText_loc4`='……雷霆崖，欠两千零六十三。', `MaleText_loc5`='...雷霆崖，拖欠兩千又六十三。', `MaleText_loc7`='...Cima del Trueno, dos mil sesenta y tres en atrasos.' WHERE `ID`=53170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언더시티, 연체금 5,022,000골드.', `MaleText_loc4`='幽暗城，欠五千零二十二。', `MaleText_loc5`='幽暗城，拖欠五千又二十二。', `MaleText_loc7`='Entrañas, cinco mil veintidós en atrasos.' WHERE `ID`=53171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문, 연체금 9,000,000골드 이상...', `MaleText_loc4`='银月城，超过九千……', `MaleText_loc5`='銀月，超過九千...', `MaleText_loc7`='Lunargenta, más de nueve mil...' WHERE `ID`=53172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 그 촌놈들에게 심장을 팔아서라도 돈을 갚던가, 아니면 내 앞에 엎드려 죽으라고 전해!', `MaleText_loc4`='够了！这些王国最好识相点，否则就等死吧！', `MaleText_loc5`='夠了!這些王國要負起他們的重擔，或在我的重擊下粉碎!', `MaleText_loc7`='¡Basta! ¡Los reinos se harán responsables de esto o caerán ante el mío!' WHERE `ID`=53173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달이 두 번 바뀔 때까지 빚을 갚아야 한다. 당장 이 사실을 알려!', `MaleText_loc4`='他们还有两晚时间付清欠款。去告诉他们！', `MaleText_loc5`='他們有兩次月圓的時間來償還債務。讓他們知道!', `MaleText_loc7`='Tienen dos lunas para pagar sus deudas. ¡Házselo saber!' WHERE `ID`=53174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀결사단은 그 무모함의 대가를 치르리라!', `MaleText_loc4`='秘教徒们必将为他们的鲁莽付出代价！', `MaleText_loc5`='那些卡巴的傢伙會為他們的魯莽付出代價!', `MaleText_loc7`='¡La Cábala pagará por su temeridad!' WHERE `ID`=53175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은심장! 보르필! 이제 네놈들 차례다!', `MaleText_loc4`='布莱卡特！沃匹尔！你们死期将至！', `MaleText_loc5`='黑心!瓦皮歐!你們的死期到了!', `MaleText_loc7`='¡Negrozón! ¡Vorpil! ¡Su tiempo se ha terminado!' WHERE `ID`=53176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 어둠의 의회를 저지하고, 그들의 잔학무도함에 종지부를 찍을 것이다!', `MaleText_loc4`='我们必须阻止暗影议会的暴行！', `MaleText_loc5`='我們會阻止暗影議會，終結它們的暴行!', `MaleText_loc7`='¡Detendremos al Consejo de la Sombra y acabaremos con sus atrocidades!' WHERE `ID`=53177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀결사단은 아무 죄없는 이들을 너무나도 오랫동안 괴롭혀왔다! 이제 놈들을 응징할 때다!', `MaleText_loc4`='秘教徒们对无辜者的威胁已经持续得太久了！他们的报应已经到了！', `MaleText_loc5`='卡巴已經威脅到無辜善良的人們太久了!反擊的時刻到了!', `MaleText_loc7`='¡La Cábala lleva ya demasiado tiempo amenazando a inocentes! ¡Ha llegado la hora de la venganza!' WHERE `ID`=53178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복의 휘장을 잃어버렸습니다.', `MaleText_loc4`='我把征服之岛战袍弄丢了。', `MaleText_loc5`='我的征服外袍掉了。', `MaleText_loc7`='He perdido mi tabardo de Conquista.', `FemaleText_loc1`='정복의 휘장을 잃어버렸어요.', `FemaleText_loc4`='我把征服之岛战袍弄丢了。', `FemaleText_loc5`='我的征服外袍掉了。', `FemaleText_loc7`='He perdido mi tabardo de Conquista.' WHERE `ID`=53179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 순수성이 우리를 정화하고, 불의 열정이 우리를 움직인다네.', `MaleText_loc4`='上古火灵的纯洁净化了我们，他的激情更激励着我们。', `MaleText_loc5`='火之靈的純淨讓我們得到淨化，他的熱情讓我們得到鼓舞。', `MaleText_loc7`='La pureza del espíritu del fuego nos depura. La pasión de su ser nos guía.' WHERE `ID`=53180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화로가 준비되었습니다. 이제 사부님을 상대할 준비가 되었습니다.', `MaleText_loc4`='火盆已经点燃了。我做好挑战你的准备了。', `MaleText_loc5`='火盆備好了，我也做好和你交手的準備。', `MaleText_loc7`='Los blandones están preparados. Estoy listo para enfrentarme a ti.', `FemaleText_loc1`='화로가 준비되었습니다. 이제 사부님을 상대할 준비가 되었습니다.', `FemaleText_loc4`='火盆已经点燃了。我做好挑战你的准备了。', `FemaleText_loc5`='火盆備好了，我也做好和你交手的準備。', `FemaleText_loc7`='Los blandones están preparados. Estoy lista para enfrentarme a ti.' WHERE `ID`=53181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸울 준비가 되면 내게 말하게, 젊은 $c|1이여;여;.', `MaleText_loc4`='做好战斗的准备后，就告诉我吧，年轻的$c。', `MaleText_loc5`='準備好戰鬥時就和我說，年輕的$c。', `MaleText_loc7`='Habla conmigo cuando estés $gpreparado:preparada; para el combate.' WHERE `ID`=53182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 모래시계의 힘은 무의미하다!', `MaleText_loc4`='沙漏的力量对我毫无用处！', `MaleText_loc5`='沙漏的力量對我無效!', `MaleText_loc7`='¡El poder del reloj de arena no me afecta!' WHERE `ID`=53183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림. 승리의 소식으로 나를 기쁘게 해라.', `MaleText_loc4`='纳兹戈林，用胜利的捷报振奋下我的精神吧。', `MaleText_loc5`='納茲格寧姆，用勝利的好消息來讓我鬆一口氣吧。', `MaleText_loc7`='Nazgrim, levántame el ánimo con noticias de victoria.' WHERE `ID`=53184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉시 분부를 따르겠습니다.', `MaleText_loc4`='立刻。', `MaleText_loc5`='立刻。', `MaleText_loc7`='Inmediatamente.' WHERE `ID`=53185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈둥아! 살아났구나! 아, 정말 고맙네, $c!', `MaleText_loc4`='雪雾，你得救了！真是太感谢你了，$c！', `MaleText_loc5`='雪噴!你平安了!喔謝謝你，$c!', `MaleText_loc7`='¡Ventonieve! ¡Estás a salvo! ¡Oh, gracias, $c!' WHERE `ID`=53186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리끼리 야영지로 돌아갈 수 있네. 그리핀을 타고 비행할 일이 있으면 언제든 내게 이야기하게.', `MaleText_loc4`='我们自己能回到营地去。回头如果你想借狮鹫的话就来找我吧。', `MaleText_loc5`='我們可以自己回去營地了，如果你想要借用獅鷲獸就來找我。', `MaleText_loc7`='Podemos volver al campamento por nuestra cuenta. Ven a verme más tarde si te apetece tomar prestado un grifo.' WHERE `ID`=53187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고난의 거리에 있는 우리들은 최근까지 어둠의 미궁에 훨씬 광범위한 첩보망을 구축했었다네.$B$B이제 비밀요원들은 모두 죽고 나와 토군만 남았군.', `FemaleText_loc4`='我们贫民窟的人原本在暗影迷宫里有一张相当广大的间谍网络。$B$B可现在，除了我和托古恩，其他人都死了。', `FemaleText_loc5`='我們陰鬱城的人一直到最近在暗影迷宮都有著相當龐大的間諜網。$B$B現在，除了我跟吐剛之外，其他人都死了。', `FemaleText_loc7`='La gente del Bajo Arrabal teníamos una red de espías bastante grande establecida en el Laberinto de las Sombras hasta hace poco.$B$BAhora están todos muertos menos To''gun y yo.' WHERE `ID`=53188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n 님! 이제 혼자 돌아갈 수 있어요. 보급품이 필요하면 언제든 절 찾아오세요.', `FemaleText_loc4`='谢谢你，$n！我自己能回去。如果你需要补给，就回来找我吧。', `FemaleText_loc5`='謝了，$n!我應該能自己回去了。若你在上路前需要任何補給，就來找我吧。', `FemaleText_loc7`='¡Gracias, $n! Ya puedo volver sola. Ven a verme más tarde si te hacen falta provisiones para el camino.' WHERE `ID`=53189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산드라가 당신에게 윙크를 합니다.', `FemaleText_loc4`='桑德拉向你眨了眨眼。', `FemaleText_loc5`='珊卓拉對你眨眨眼睛。', `FemaleText_loc7`='Sandra te guiña el ojo.' WHERE `ID`=53190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스의 지도자들은 뭐 하나 하는데도 너무 느리게 반응합니다. 그래서 고난의 거리의 위대하신 분들께서는 어둠의 미궁 문제를 우리에게 맡기신 겁니다.', `MaleText_loc4`='沙塔斯的领导层行动太缓慢了，所以贫民窟的大人物把暗影迷宫的事揽到了自己手里。', `MaleText_loc5`='撒塔斯的領導階層反應太慢了，所以陰鬱城的勇敢人民打算自己動手解決暗影迷宮的問題。', `MaleText_loc7`='Los líderes de Shattrath son demasiado lentos para actuar, así que el gran pueblo del Bajo Arrabal ha tomado el control de la situación en el Laberinto de las Sombras.' WHERE `ID`=53191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이곳이다, 영웅들이여. 그녀는 이곳에서 저항하다 쓰러졌지. 시간 속에 갇힌 여군주 실바나스 윈드러너의 환영은 루비 용제단의 썩어가는 가지 사이를 영원히 맴돌 것이다.', `MaleText_loc4`='英雄们，这是她曾经的战斗之地，也是她的陨落之地。希尔瓦娜斯·风行者迷失在时空中的投影将永远在巨龙圣地的残骸上徘徊。', `MaleText_loc5`='英雄們，這裡就是她挺身奮戰，也是她倒下的地方。希瓦娜斯·風行者在時間中消褪的回音將穿越龍殿中滿地腐朽的肢體，迴盪到永恆。', `MaleText_loc7`='Aquí resistió, héroes, y también sucumbió. El eco de Sylvanas Brisaveloz perdido en el tiempo resonará entre las ramas podridas del Santuario de Dragones por toda la eternidad.' WHERE `ID`=53192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나의 지팡이 조각을 모두 찾으십시오!', `MaleText_loc4`='找到所有的吉安娜法杖碎片！', `MaleText_loc5`='找出珍娜法杖的所有的碎片!', `MaleText_loc7`='¡Encuentra todos los fragmentos del bastón de Jaina!' WHERE `ID`=53193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙의 통치가 가져오는 결과가 네 눈앞에 펼쳐져 있다. 한때 루비 용제단이었던 곳은 검게 탄 나무와 그을린 대지만 남긴 채 폐허가 되었지.
$b먼 옛날 알렉스트라자의 눈물 한 방울이 눈을 녹이고, 네 눈 앞에 선 거대한 진홍 떡갈나무에 생명을 주었다고 한다. 그 나무의 가지는 의기양양하게 하늘로 뻗고, 붉은용군단의 온기와 생명을 내뿜었다고 하지.
$b하지만 이제 나무는 뒤틀리고 가지는 썩어들어가, 생명과 활력의 힘은 이 나무에 거할 수 없다... 대신 그 자리를 죽음과 파괴가 차지했지. 불길과 부패가 이 땅에서 모든 생명을 몰살하는 동안, 저 위대한 나무는 목격했다... 이 신성한 땅에 쓰러진 영웅들의 환영을 말이다.', `MaleText_loc4`='你面前就是死亡之翼的残酷统治所造成的后果。曾经的红玉巨龙圣地已经成了一片废墟，只有焦黑的残垣和龟裂的土地证明它的存在。
$b据说，很久之前，阿莱克斯塔萨的一滴鲜血，融化了冰雪，并催生出你面前这棵巨大的红玉橡树。这棵巨树的枝叶直刺苍穹，散发着红龙军团特有的温暖及生命力。
$b可现在，它却被扭曲了，腐败的枝叶无法再掌管生命与活力的力量——反而成了死亡与毁灭的代言人。当烈焰与堕落灭绝这片圣地的生机之时，这棵巨树定格了一个缩影——依稀就是那些倒在这片圣地上的英雄们的残影。', `MaleText_loc5`='在你面前是死亡之翼統治的殘跡。晶紅龍殿原本屹立之處，現在已成廢墟，只有焦黑的斷壁殘垣和土壤作為它曾經存在的見證。
$b據說，在很久以前，雅立史卓莎的一滴血把冰雪都融化了，還賦予了你眼前這棵赤紅橡樹生命，使它的枝葉伸展到空中，散發出紅龍軍團的溫暖生命能量。
$b但是現在，它扭曲、腐化的枝葉已不再蘊含生命的力量，反而散發著死亡與毀滅。當火焰與腐化的力量掐滅這片土地的生命能量時，這棵巨樹卻捕捉到了一道影像...在聖地上倒下的戰士們的回音殘響。', `MaleText_loc7`='Ante ti se hallan las secuelas del reinado de Alamuerte. Lo que era el Santuario de Dragones Rubí ahora está vacío; los restos carbonizados y la tierra quemada son el único vestigio de su existencia.
$b Se dice que una sola gota de la sangre de Alexstrasza derritió la nieve y dio vida al gran roble carmesí, cuyas ramas se elevaban triunfantes hacia el cielo y desprendían la calidez y vida del Vuelo Rojo.
$bAhora está retorcido, las ramas podridas ya no poseen el poder de la vida y la vitalidad, están llenas de muerte y destrucción. Cuando la llama y la corrupción acabaron con la fuerza vital de estas tierras, el gran árbol capturó una imagen, un eco de los guerreros que cayeron en sus tierras sagradas.' WHERE `ID`=53194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 어서 상처를 치료하고 다시 전투를 시작해야겠습니다!', `MaleText_loc4`='谢谢你。是时候抚平伤痛，回去再战了！', `MaleText_loc5`='謝謝你。我得處理一下我的傷口，然後回去戰鬥!', `MaleText_loc7`='Gracias. ¡Hora de lamerme las heridas y volver a la batalla!', `FemaleText_loc1`='고마워요. 어서 상처를 치료하고 다시 전투를 시작해야겠어요!', `FemaleText_loc4`='谢谢你。是时候抚平伤痛，回去再战了！', `FemaleText_loc5`='謝謝你。我得處理一下我的傷口，然後回去戰鬥!', `FemaleText_loc7`='Gracias. ¡Hora de lamerme las heridas y volver a la batalla!' WHERE `ID`=53195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구출해주셔서 감사합니다. 앞선 전투는 꽤 힘에 겨웠습니다.', `MaleText_loc4`='感谢你救了我。待在那上面可真难受。', `MaleText_loc5`='感謝你救了我。剛剛還真有點危險。', `MaleText_loc7`='Gracias por salvarme. La hemos pasado mal.', `FemaleText_loc1`='구출해주셔서 고마워요. 앞선 전투는 꽤 힘에 겨웠어요.', `FemaleText_loc4`='感谢你救了我。待在那上面可真难受。', `FemaleText_loc5`='感謝你救了我。剛剛還真有點危險。', `FemaleText_loc7`='Gracias por salvarme. La hemos pasado mal.' WHERE `ID`=53196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 지금... 살아 있는 겁니까? 하! 가로쉬아르 거점의 호드들에게 인사를 전하고 싶군요. 우리가 아주 혼쭐을 내줬습니다.', `MaleText_loc4`='我还活着？哈！加尔鲁什尔前哨站的部落真是白费力气了。给他们点颜色瞧瞧。', `MaleText_loc5`='我還活著?哈!卡爾洛夏海岬那邊的部落可就沒那麼好運了。我們把他們打得落花流水。', `MaleText_loc7`='¿Estoy vivo? ¡Ja! No se puede decir lo mismo de la Horda en Puesto Garrosh''ar. Les hemos dado una buena tunda.', `FemaleText_loc1`='저 지금... 살아 있는 건가요? 하! 가로쉬아르 거점의 호드들에게 인사나 전하고 싶네요. 우리가 아주 혼쭐을 내줬거든요.', `FemaleText_loc4`='我还活着？哈！加尔鲁什尔前哨站的部落真是白费力气了。给他们点颜色瞧瞧。', `FemaleText_loc5`='我還活著?哈!卡爾洛夏海岬那邊的部落可就沒那麼好運了。我們把他們打得落花流水。', `FemaleText_loc7`='¿Estoy viva? ¡Ja! No se puede decir lo mismo de la Horda en Puesto Garrosh''ar. Les hemos dado una buena tunda.' WHERE `ID`=53197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에는 아무 문제도 없습니다, 대족장님.', `MaleText_loc4`='我很高兴地向你报告，战况良好，酋长。', `MaleText_loc5`='我很高興向您報告戰況極佳，大酋長。', `MaleText_loc7`='Me alegra anunciar que la batalla naval va bien, Jefe de Guerra.' WHERE `ID`=53198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즈즈를 수도원 훈련 과정에 집어넣다니! 믿을 수 없어!$b$b나, 즈즈를!', `MaleText_loc4`='他们真的让我来禅院修炼了！齐齐真不敢相信！$b$b齐齐办到了！', `MaleText_loc5`='熙熙不敢相信他們真的讓我進寺廟訓練!$b$b我!熙熙!', `MaleText_loc7`='Zhi-Zhi no se puede creer que le hayan dejado entrar en el programa de entrenamiento del monasterio.$b$b¡A mí! ¡A Zhi-Zhi!' WHERE `ID`=53199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서! 즈즈가 여기서 연습하고 있잖아! 여기서 5미터 이내로 접근하면 모두 때려눕혀 버리겠어! 어쩌면... 처치할지도 몰라.$b$b하이... 얍!', `MaleText_loc4`='闪开！齐齐正在练功！靠近我五码之内的人都有可能被踢飞……甚至可能被踢死。$b$b呀哈——！', `MaleText_loc5`='退後!熙熙在這練習!任何接近我五尺之內的都有可能被打昏...甚至被打死!$b$b呀哈!', `MaleText_loc7`='¡Atrás! ¡Zhi-Zhi está entrenando! Cualquiera que se acerque a menos de cinco metros puede acabar sin sentido... o muerto.$b$b¡Hai-yah!' WHERE `ID`=53200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즈즈는 항상 친구를 잘 때렸지만, 여기서 공부하는 동안 버릇을 많이 고쳤어.', `MaleText_loc4`='以前齐齐最擅长误伤队友，但自从开始训练之后，齐齐已经进步很多了。', `MaleText_loc5`='熙熙打他的朋友總是很厲害，但熙熙在這裡學習後變得更厲害。', `MaleText_loc7`='A Zhi-Zhi siempre se le ha dado bien pegar a sus amigos, pero se le da mucho mejor desde que estudia aquí.' WHERE `ID`=53201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 싸우시겠습니까?', `MaleText_loc4`='想过两招吗？', `MaleText_loc5`='想來一場嗎?', `MaleText_loc7`='¿Quieres luchar?', `FemaleText_loc1`='저와 싸우실래요?', `FemaleText_loc4`='想过两招吗？', `FemaleText_loc5`='想來一場嗎?', `FemaleText_loc7`='¿Quieres luchar?' WHERE `ID`=53202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 즈즈한테 덤비는 꼬마가 나올 때도 됐지!', `MaleText_loc4`='总算有人来挑战齐齐了！', `MaleText_loc5`='終於有人來挑戰熙熙了!', `MaleText_loc7`='¡Ya era hora de que alguien desafiara a Zhi-Zhi!', `FemaleText_loc1`='그래, 즈즈한테 덤비는 꼬마가 나올 때도 됐지!', `FemaleText_loc4`='总算有人来挑战齐齐了！', `FemaleText_loc5`='終於有人來挑戰熙熙了!', `FemaleText_loc7`='¡Ya era hora de que alguien desafiara a Zhi-Zhi!' WHERE `ID`=53203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어, 그만, 그만해! 즈즈 때리지 마!', `MaleText_loc4`='够了，够了！别打齐齐了！', `MaleText_loc5`='好了，夠了、夠了!別再打熙熙了!', `MaleText_loc7`='¡Basta, basta! ¡Deja de pegar a Zhi-Zhi!', `FemaleText_loc1`='알았어, 그만, 그만해! 즈즈 때리지 마!', `FemaleText_loc4`='够了，够了！别打齐齐了！', `FemaleText_loc5`='好了，夠了、夠了!別再打熙熙了!', `FemaleText_loc7`='¡Basta, basta! ¡Deja de pegar a Zhi-Zhi!' WHERE `ID`=53204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적지에 한 걸음 더 가까워졌네, 친구들이여. 잠시 숨을 돌리게나. 계속 나아갈 준비가 되면 알려주게.', `MaleText_loc4`='我的朋友们，我们离目标又近了一步。休息一下吧，等你们准备好继续前进时，请和我说一声。', `MaleText_loc5`='我們已經更接近目的地了，朋友們。休息一下，等你們準備好了跟我說。', `MaleText_loc7`='Estamos un poco más cerca, amigos míos. Descansemos un poco y cuando estéis listos para continuar, hacédmelo saber.' WHERE `ID`=53205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타나리스와 톨 바라드 해안에서의 주요 전투에서 승리했다는 보고가 들어왔습니다...', `MaleText_loc4`='我方军队在塔纳利斯和托尔巴拉德海岸频频告捷……', `MaleText_loc5`='我們的軍隊回報了在海岸上與塔納利斯和托巴拉德爭戰的重大勝利...', `MaleText_loc7`='Nuestros ejércitos informan de victorias decisivas en Tanaris y Tol Barad.' WHERE `ID`=53206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진! 거의 다 왔네! 준비되면 말해 주게. 계속 승리를 향해 나아갈 수 있도록!', `MaleText_loc4`='前进！我们马上就要成功了！只要一声令下，我们就将继续高歌猛进！', `MaleText_loc5`='向前!我們快到了!只要說一聲，我們就前往勝利的終點!', `MaleText_loc7`='¡Adelante! Ya casi estamos. ¡Pídelo y continuaremos hasta la victoria!' WHERE `ID`=53207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위를 수도원에 받아들인 것은 판다렌 장로들의 현명한 선택이었습니다.$b$b하지만 호젠에게도 같은 특권을 준 것은 그리 현명하지 못한 처사였지요.', `MaleText_loc4`='熊猫人长老允许锦鱼人进入禅院是个贤明的决定。$b$b但他们给予猢狲同样的待遇，此为不智。', `MaleText_loc5`='讓錦魚人加入寺院是熊貓人長者們的明智裁決。$b$b但讓猴人擁有同樣的特權卻是不智的。', `MaleText_loc7`='Los ancestros pandaren fueron sabios al permitir que los jinyu entraran en el monasterio.$b$bCometieron un error al otorgarles el mismo privilegio a los hozen.' WHERE `ID`=53208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기가 좋습니다. 물이 조금 더 있으면 좋겠지만... 마음에 듭니다.', `MaleText_loc4`='我喜欢这个地方。要是这里的水再多一点就好了……', `MaleText_loc5`='我喜歡這個地方。雖然還需要更多的水...但我喜歡。', `MaleText_loc7`='Me gusta este lugar. Le falta agua, pero me gusta.' WHERE `ID`=53209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 여기 수도사들에게서 많은 것을 배웠습니다, $r님. 당신도 그럴 수 있을 겁니다.', `MaleText_loc4`='我从这里的武僧身上学到了很多东西，$r。希望你也一样。', `MaleText_loc5`='我從這些武僧身上學到很多，$r。希望你也能一樣。', `MaleText_loc7`='He aprendido mucho de estos monjes, $r. Harías bien en seguir mi ejemplo.' WHERE `ID`=53210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 겨루고 싶습니다, 후슌 님!', `MaleText_loc4`='我想和你交手，胡苏安！', `MaleText_loc5`='我向你提出決鬥的挑戰，賀司涵!', `MaleText_loc7`='¡Te reto a un combate, Husshun!', `FemaleText_loc1`='당신과 겨루고 싶어요, 후슌 님!', `FemaleText_loc4`='我想和你交手，胡苏安！', `FemaleText_loc5`='我向你提出決鬥的挑戰，賀司涵!', `FemaleText_loc7`='¡Te reto a un combate, Husshun!' WHERE `ID`=53211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다!', `MaleText_loc4`='很好！', `MaleText_loc5`='很好!', `MaleText_loc7`='¡Muy bien!' WHERE `ID`=53212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 패할 줄 알았습니다. 강물이 그렇게 말하더군요.', `MaleText_loc4`='我早就预见了这场失败。河水早已把一切都告诉了我。', `MaleText_loc5`='我早就知道會輸。河流是這樣跟我說的。', `MaleText_loc7`='Sabía que perdería. Los ríos me lo habían dicho.' WHERE `ID`=53213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무르도즈노와 맞서고 싶다면 이 땅에 안식을 가져와야 한다.', `MaleText_loc4`='如果要挑战姆诺兹多，你们必须使这些圣地重获安宁。', `MaleText_loc5`='如果你想要面對姆多茲諾，你必須給這片土地帶來安寧。', `MaleText_loc7`='Debes traer paz a estas tierras si pretendes enfrentarte a Murozond.' WHERE `ID`=53214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 음식이 마음에 들지 않는다고는 말할 수 없겠습니다. 맥주도 마찬가지고요.', `MaleText_loc4`='我得说，这儿的饭菜还真是不错。啤酒也是，真心给力。', `MaleText_loc5`='我可不介意這裡的食物。或者是啤酒。', `MaleText_loc7`='La verdad es que la comida de este sitio no está nada mal. Y la cerveza tampoco.' WHERE `ID`=53215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 밥은 먹어 보셨습니까? 꼭 한 번 경험해 봐야 하는 맛입니다.', `MaleText_loc4`='你尝过这个米饭了吗？你真应该尝尝。', `MaleText_loc5`='你有吃過那些米飯嗎?你真的該嚐嚐那些米飯。', `MaleText_loc7`='¿Has probado el arroz? Tienes que catarlo.' WHERE `ID`=53216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사도 훈련의 한 가지 형태랍니다. 알고 계시죠?', `MaleText_loc4`='吃东西也是一种修炼，你明白的。', `MaleText_loc5`='吃東西也是一種訓練，你懂的。', `MaleText_loc7`='¿Sabes? Comer también es una forma de entrenamiento.' WHERE `ID`=53217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젓가락을 내려놓고 주먹을 쥐십시오! 도전합니다!', `MaleText_loc4`='别吃了，露两手吧！我要挑战你！', `MaleText_loc5`='放下你的筷子，舉起你的拳頭!我向你挑戰!', `MaleText_loc7`='¡Deja el tenedor y alza los puños! ¡Te desafío!', `FemaleText_loc1`='젓가락을 내려놓고 주먹을 쥐세요! 도전하겠어요!', `FemaleText_loc4`='别吃了，露两手吧！我要挑战你！', `FemaleText_loc5`='放下你的筷子，舉起你的拳頭!我向你挑戰!', `FemaleText_loc7`='¡Deja el tenedor y alza los puños! ¡Te desafío!' WHERE `ID`=53218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 원한다면... 좋습니다. $R 주물럭을 만들어 먹을 시간이군요!', `MaleText_loc4`='好吧，让我来尝尝单片$R三明治的味道！', `MaleText_loc5`='很好。是時候做一道外餡$R三明治了!', `MaleText_loc7`='Muy bien. ¡Es la hora del bocadillo de $r!' WHERE `ID`=53219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는... 당신이 이겼습니다. 저도 체력 훈련을 다시 시작해야겠어요.', `MaleText_loc4`='好吧……算你赢了。我得继续修炼体重了。', `MaleText_loc5`='你贏了...但只是這一次而已。我得趕快回去做我的體型訓練了。', `MaleText_loc7`='Has ganado... esta vez. Será mejor que retome el entrenamiento de peso.' WHERE `ID`=53220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살살 하십시오. 지난 번 전투에서 패했을... 아니, 이겼을 때 생긴 상처가 아직 낫지 않았습니다.', `MaleText_loc4`='轻点——我还没从上一次失败……呃……胜利中恢复过来。', `MaleText_loc5`='溫和點，我上一場敗仗...我是說...勝仗留下來的瘀傷還是有點痛。', `MaleText_loc7`='No te pases mucho, todavía estoy magullado de la última pelea que perdí... digo... que gané.', `FemaleText_loc1`='살살 해주세요. 지난 번 전투에서 패했을... 아니, 이겼을 때 생긴 상처가 아직 낫지 않았거든요.', `FemaleText_loc4`='轻点——我还没从上一次失败……呃……胜利中恢复过来。', `FemaleText_loc5`='溫和點，我上一場敗仗...我是說...勝仗留下來的瘀傷還是有點痛。', `FemaleText_loc7`='No te pases mucho, todavía estoy magullada de la última pelea que perdí... digo... que gané.' WHERE `ID`=53221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 겨루게 되어 영광입니다, $g형제:자매;여.', `MaleText_loc4`='能和你过招是我的荣幸，$g先生:女士;。', `MaleText_loc5`='和你對決是我的榮幸，$g先生:女士;。', `MaleText_loc7`='Sería un honor enfrentarme a ti, $gseñor:señora;.', `FemaleText_loc1`='당신과 겨루게 되어 영광이에요, $g형제:자매;여.', `FemaleText_loc4`='能和你过招是我的荣幸，$g先生:女士;。', `FemaleText_loc5`='和你對決是我的榮幸，$g先生:女士;。', `FemaleText_loc7`='Sería un honor enfrentarme a ti, $gseñor:señora;.' WHERE `ID`=53222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 생각을 하시는지 압니다. 그 작은 $r 눈에 다 드러납니다.$b$b<미소 짓는 견습생>$b$b자, 계속하시겠습니까?', `MaleText_loc4`='我知道你在想什么。你的心思全写在你那双$r眼睛里呢。$b$b<这名徒弟露出了微笑。>$b$b好吧，我们可以开始了吗？', `MaleText_loc5`='我知道你在想什麼。我可以從你的小$r眼睛裡看出來。$b$b<寺院弟子微笑。>$b$b好了，我們要不要開始?', `MaleText_loc7`='Sé lo que estás pensando. Lo veo en tus ojitos de $r.$b$b<El pupilo sonríe.>$b$b¿Y bien? ¿Vamos a ello?', `FemaleText_loc1`='무슨 생각 하시는지 알아요. 그 작은 $r 눈에 다 드러나네요.$b$b<미소 짓는 견습생>$b$b자, 할까요, 말까요?', `FemaleText_loc4`='我知道你在想什么。你的心思全写在你那双$r眼睛里呢。$b$b<这名徒弟露出了微笑。>$b$b好吧，我们可以开始了吗？', `FemaleText_loc5`='我知道你在想什麼。我可以從你的小$r眼睛裡看出來。$b$b<寺院弟子微笑。>$b$b好了，我們要不要開始?', `FemaleText_loc7`='Sé lo que estás pensando. Lo veo en tus ojitos de $r.$b$b<La pupila sonríe.>$b$b¿Y bien? ¿Vamos a ello?' WHERE `ID`=53223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 바로 시작하십시오.', `MaleText_loc4`='随时可以开始。', `MaleText_loc5`='我準備好了，由你決定。', `MaleText_loc7`='Cuando quieras.', `FemaleText_loc1`='당신만 준비 되면 바로 시작하세요.', `FemaleText_loc4`='随时可以开始。', `FemaleText_loc5`='我準備好了，由你決定。', `FemaleText_loc7`='Cuando quieras.' WHERE `ID`=53224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금껏 하루 종일 대련을 했습니다. 식사는 언제 합니까?', `MaleText_loc4`='整天都在过招。啥时候吃饭啊？', `MaleText_loc5`='我決鬥了一整天。哪時候吃飯?', `MaleText_loc7`='Llevo todo el día luchando. ¿Cuándo comemos?', `FemaleText_loc1`='난 오늘 온종일 대련을 했어요. 밥은 언제 먹죠?', `FemaleText_loc4`='整天都在过招。啥时候吃饭啊？', `FemaleText_loc5`='我決鬥了一整天。哪時候吃飯?', `FemaleText_loc7`='Llevo todo el día luchando. ¿Cuándo comemos?' WHERE `ID`=53225;
