UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디, 제 "느리고 약한 정권 지르기" 기술을 어떻게 피하는지 봅시다!', `MaleText_loc4`='让我瞧瞧你打算怎么对付我的“超慢超弱拳”！', `MaleText_loc5`='看看你能否擋住我的「慢弱拳」絕技!', `MaleText_loc7`='¡Veamos cómo aguantas mi técnica de "puñetazos lentos y endebles"!', `FemaleText_loc1`='어디, 제 "느리고 약한 정권 지르기" 기술을 어떻게 피하는지 보자고요!', `FemaleText_loc4`='让我瞧瞧你打算怎么对付我的“超慢超弱拳”！', `FemaleText_loc5`='看看你能否擋住我的「慢弱拳」絕技!', `FemaleText_loc7`='¡Veamos cómo aguantas mi técnica de "puñetazos lentos y endebles"!' WHERE `ID`=53234;
