UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 결투였습니다. 다음에는 제가 승리하겠습니다.', `MaleText_loc4`='好功夫。下次我再找你单练。', `MaleText_loc5`='打得好。下次我會贏過你的。', `MaleText_loc7`='Buen combate. La próxima vez te venceré.', `FemaleText_loc1`='멋진 결투였어요. 다음에는 제가 승리할게요.', `FemaleText_loc4`='好功夫。下次我再找你单练。', `FemaleText_loc5`='打得好。下次我會贏過你的。', `FemaleText_loc7`='Buen combate. La próxima vez te venceré.' WHERE `ID`=53240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위주먹 스승님 말씀이 옳았습니다. 솜씨가 정말 훌륭하시군요.', `MaleText_loc4`='石拳大师说的没错。你可真强。', `MaleText_loc5`='石拳大師對你的評價沒錯。你很厲害。', `MaleText_loc7`='El maestro Puño Firme tenía razón. Eres un prodigio.', `FemaleText_loc1`='바위주먹 스승님 말씀이 옳았어요. 솜씨가 정말 훌륭하시네요.', `FemaleText_loc4`='石拳大师说的没错。你可真强。', `FemaleText_loc5`='石拳大師對你的評價沒錯。你很厲害。', `FemaleText_loc7`='El maestro Puño Firme tenía razón. Eres un prodigio.' WHERE `ID`=53241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께 두들겨 맞을 기회를 주셔서 감사합니다.', `MaleText_loc4`='感谢你的指点。', `MaleText_loc5`='感謝你給我被你痛毆的機會。', `MaleText_loc7`='Gracias por darme la oportunidad de recibir una paliza a tus manos.', `FemaleText_loc1`='당신께 두들겨 맞을 기회를 주셔서 고마워요.', `FemaleText_loc4`='感谢你的指点。', `FemaleText_loc5`='感謝你給我被你痛毆的機會。', `FemaleText_loc7`='Gracias por darme la oportunidad de recibir una paliza a tus manos.' WHERE `ID`=53242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 대련에서 지나칠 만큼 최선을 다하시는군요. 안 그렇습니까?', `MaleText_loc4`='你也太认真了一点吧？', `MaleText_loc5`='你是認真的，是吧?', `MaleText_loc7`='Te lo tomas muy en serio, ¿no?', `FemaleText_loc1`='아이고, 대련에서 지나칠 만큼 최선을 다하시네요. 안 그래요?', `FemaleText_loc4`='你也太认真了一点吧？', `FemaleText_loc5`='你是認真的，是吧?', `FemaleText_loc7`='Te lo tomas muy en serio, ¿no?' WHERE `ID`=53243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 대련이었습니다.', `MaleText_loc4`='好功夫。', `MaleText_loc5`='打得好。', `MaleText_loc7`='Buen combate.', `FemaleText_loc1`='멋진 대련이었어요.', `FemaleText_loc4`='好功夫。', `FemaleText_loc5`='打得好。', `FemaleText_loc7`='Buen combate.' WHERE `ID`=53244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고명한 아이사 클라우드싱어 님께 도움을 청하려고 왔는데, 도저히 이분의 수련을 방해할 수가 없소. 너무나 침착하고, 우아하고... 아름답소.', `MaleText_loc4`='我是来向远近闻名的艾莎·云歌求助的，但我不能打扰她的修行。她是如此娴静、如此沉稳……如此美丽。', `MaleText_loc5`='我來是為了向名聞遐邇的艾莎·雲詠求助，但我不敢前去打斷她的修練。她是如此的悠然自若，如此的從容熟稔...如此的美麗。', `MaleText_loc7`='He venido a pedir ayuda a la célebre Aysa Canción Etérea, pero no puedo interrumpir sus ejercicios. Es tan equilibrada, tan sabia... tan bella.' WHERE `ID`=53245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단 한 순간도 제가 우세한 적이 없었습니다. 또 뵙겠습니다!', `MaleText_loc4`='我果然一点机会都没有。我先告辞了！', `MaleText_loc5`='我不覺得我有一丁點機會。那麼，再會啦!', `MaleText_loc7`='Creo que nunca tuve la más mínima posibilidad. ¡Suerte!', `FemaleText_loc1`='단 한 순간도 제가 우세한 적이 없었어요. 또 뵐게요!', `FemaleText_loc4`='我果然一点机会都没有。我先告辞了！', `FemaleText_loc5`='我不覺得我有一丁點機會。那麼，再會啦!', `FemaleText_loc7`='Creo que nunca tuve la más mínima posibilidad. ¡Suerte!' WHERE `ID`=53246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치열한 전투 끝에, 무법항으로 향하는 보급로를 다시 확보했습니다.', `MaleText_loc4`='经过激烈的战斗，我们已经恢复了与藏宝海湾之间的运输线。', `MaleText_loc5`='經過激烈的戰役後，我們已重新建立與藏寶海灣之間的補給航線。', `MaleText_loc7`='Después de una intensa lucha, hemos conseguido restablecer nuestra ruta de suministro hasta Bahía del Botín.' WHERE `ID`=53247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서요! 서둘러야 합니다.', `FemaleText_loc4`='来吧，$n！动作要快。', `FemaleText_loc5`='來吧，$n。讓我們像風一樣快。', `FemaleText_loc7`='¡Vamos! Démonos prisa.' WHERE `ID`=53248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 전쟁을 하러 여기 왔네.$B$B저들이 초래한 전쟁이지.', `MaleText_loc4`='我们是来打仗的。$B$B这是他们强加给我们的。', `MaleText_loc5`='我們為戰爭而來。$B$B他們滿足了我們。', `MaleText_loc7`='Vinimos aquí para luchar.$B$BY ellos nos han proporcionado guerra.' WHERE `ID`=53249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격에 앞서 정찰을 위해 이곳에 왔습니다만, 저들은 우리가 올 거라는 사실을 이미 알고 있었습니다.', `MaleText_loc4`='我们是来侦察敌人的入侵行动的，可他们已经知道我们来了。', `MaleText_loc5`='我們來這裡偵查入侵的跡象，但是他們已經知道我們會來這裡。', `MaleText_loc7`='Vinimos a explorar para una invasión, pero ellos ya sabían que veníamos.' WHERE `ID`=53250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안으로 들어오시오. 어서! 내가 놈들을 막겠소!', `MaleText_loc4`='进去，快！我来挡住他们！', `MaleText_loc5`='進去，快!我會擋著他們!', `MaleText_loc7`='¡Adentro, rápido! ¡Los retendré!' WHERE `ID`=53254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼... 주술사, 용의 영혼을 내놓으시지. 당장.', `MaleText_loc4`='萨满，你会把巨龙之魂交给我。', `MaleText_loc5`='現在呢，薩滿，把巨龍之魂交給我吧。', `MaleText_loc7`='Y ahora, chamán, me vas a entregar el Alma de dragón.' WHERE `ID`=53255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주제를 알아야 할 때다, 판다렌!', `MaleText_loc4`='该学乖了，熊猫人！', `MaleText_loc5`='臣服的時刻到了，熊貓人!', `MaleText_loc7`='¡Es hora de que aprendan cuál es su sitio, pandaren!' WHERE `ID`=53257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴 중', `MaleText_loc4`='破坏', `MaleText_loc5`='破壞中', `MaleText_loc7`='Saboteando' WHERE `ID`=53258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 여기다! 이 녀석이 다른 놈들을 보호하고 있어!', `MaleText_loc4`='这个，在这边！他正努力保护其他人！', `MaleText_loc5`='這邊這個!他在試著保護其他人!', `MaleText_loc7`='¡Ese! ¡Ese de ahí! ¡Intenta proteger a los demás!' WHERE `ID`=53259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 집으로 들어가! 걸을 수 있는 놈은 모두 데려가라!', `MaleText_loc4`='到房子里去！带上所有还能走路的人！', `MaleText_loc5`='進到那房子裡去!把還能走動的都帶著!', `MaleText_loc7`='¡Entra en la casa! ¡Llévate a todo aquel que aún pueda andar!' WHERE `ID`=53260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛날 옛적, 사람들의 기운이 약해지고 땅이 차가워졌다.', `MaleText_loc4`='在远古时期，人民浑浑噩噩，大地一片冷寂。', `MaleText_loc5`='某個古老的時代，人們的魂靈變得黯淡，大地變得寒冷。', `MaleText_loc7`='En tiempos ancestrales, los espíritus del pueblo se debilitaron y la tierra se enfrió.', `FemaleText_loc1`='옛날 옛적, 사람들의 기운이 약해지고 땅이 차가워졌다.', `FemaleText_loc4`='在远古时期，人民浑浑噩噩，大地一片冷寂。', `FemaleText_loc5`='某個古老的時代，人們的魂靈變得黯淡，大地變得寒冷。', `FemaleText_loc7`='En tiempos ancestrales, los espíritus del pueblo se debilitaron y la tierra se enfrió.' WHERE `ID`=53261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 불의 정령 후오가 셴진 수에 나타났다.', `MaleText_loc4`='此时，上古火灵燧焰降临到了神真子的背上。', `MaleText_loc5`='接著火焰之靈·霍來了，來到神真子這片土地上。', `MaleText_loc7`='Y entonces Huo, el espíritu del fuego, llegó a la tierra de Shen-zin Su.', `FemaleText_loc1`='그때 불의 정령 후오가 셴진 수에 나타났다.', `FemaleText_loc4`='此时，上古火灵燧焰降临到了神真子的背上。', `FemaleText_loc5`='接著火焰之靈·霍來了，來到神真子這片土地上。', `FemaleText_loc7`='Y entonces Huo, el espíritu del fuego, llegó a la tierra de Shen-zin Su.' WHERE `ID`=53262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후오가 이 땅을 따스하게 하고 사람들의 열정에 불을 지폈다.', `MaleText_loc4`='燧焰温暖了大地，点燃了人们的激情。', `MaleText_loc5`='火焰之靈·霍溫暖了大地，點燃了人們的熱情。', `MaleText_loc7`='Huo calentó la tierra y avivó el entusiasmo del pueblo.', `FemaleText_loc1`='후오가 이 땅을 따스하게 하고 사람들의 열정에 불을 지폈다.', `FemaleText_loc4`='燧焰温暖了大地，点燃了人们的激情。', `FemaleText_loc5`='火焰之靈·霍溫暖了大地，點燃了人們的熱情。', `FemaleText_loc7`='Huo calentó la tierra y avivó el entusiasmo del pueblo.' WHERE `ID`=53263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후로 사람들은 후오와 자신들 사이에 깊은 연이 있다는 것을 알고, 후오를 돌보았다.', `MaleText_loc4`='从那时起，人们就开始供奉燧焰。因为他们明白，自己和燧焰是紧密相连的。', `MaleText_loc5`='從今而後，人們照料著火焰之靈·霍，並了解到他們和祂唇齒相依。', `MaleText_loc7`='Y, desde entonces, el pueblo ha cuidado de Huo, ya que conocía el fuerte vínculo entre ellos.', `FemaleText_loc1`='그 후로 사람들은 후오와 자신들 사이에 깊은 연이 있다는 것을 알고, 후오를 돌보았다.', `FemaleText_loc4`='从那时起，人们就开始供奉燧焰。因为他们明白，自己和燧焰是紧密相连的。', `FemaleText_loc5`='從今而後，人們照料著火焰之靈·霍，並了解到他們和祂唇齒相依。', `FemaleText_loc7`='Y, desde entonces, el pueblo ha cuidado de Huo, ya que conocía el fuerte vínculo entre ellos.' WHERE `ID`=53264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샹 사부님께 잘 배웠군. 고맙소, 친구!', `MaleText_loc4`='尚师父教了个好徒弟。谢谢你，朋友！', `MaleText_loc5`='尚羲大師將你訓練得很好。謝謝你，朋友!', `MaleText_loc7`='El maestro Shang te ha entrenado bien. ¡Gracias, $gamigo:amiga;!' WHERE `ID`=53265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 피를 쏟아라... 내게는 그게 기쁨이다, 장군.', `MaleText_loc4`='联盟血溅四野。真是大快人心啊，将军。', `MaleText_loc5`='看到聯盟的傢伙流血讓我很愉快，將軍。', `MaleText_loc7`='Sangre de la Alianza... Eso me complace, General.' WHERE `ID`=53266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해상 작전은 어떻게 됐나? 내 소중한 화물은 어디 있지?', `MaleText_loc4`='海焰行动怎么样？我珍贵的货物如何了？', `MaleText_loc5`='「海焰行動(PH)」是什麼?我珍貴的船貨情況如何?', `MaleText_loc7`='¿Qué ha sido de [la Operación Fuego Marino (PH)]? ¿Cómo va mi preciada mercancía?' WHERE `ID`=53267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 본론으로 들어갈까?', `FemaleText_loc4`='该干正事了，对吧？', `FemaleText_loc5`='該辦正事了，對吧?', `FemaleText_loc7`='A trabajar, ¿de acuerdo?' WHERE `ID`=53268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 소식이 있습니다, 대족장님.', `MaleText_loc4`='有消息，酋长。', `MaleText_loc5`='有消息，大酋長。', `MaleText_loc7`='Tenemos noticias, Jefe de Guerra.' WHERE `ID`=53270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 말해라, 고블린...', `MaleText_loc4`='说吧，地精……', `MaleText_loc5`='說吧，哥布林...', `MaleText_loc7`='Habla, goblin...' WHERE `ID`=53271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇겐 못 해, 대주교여. 절대 넘기지 않을 걸세.', `MaleText_loc4`='我不会给你的，大主教。你休想得到它。', `MaleText_loc5`='我不會答應，大主教。你永遠得不到巨龍之魂。', `MaleText_loc7`='No, Arzobispo. Nunca te pertenecerá.' WHERE `ID`=53275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네, 네... 바로 말씀드립죠.', `MaleText_loc4`='是——是，长官……马上，长官。', `MaleText_loc5`='是，是的長官...立刻，長官。', `MaleText_loc7`='S... sí, señor... ahora mismo, señor.' WHERE `ID`=53276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음엔 아무 일 없었어요.', `MaleText_loc4`='一切都开始得很顺利。', `MaleText_loc5`='一開始非常順利。', `MaleText_loc7`='Todo empezó muy bien.' WHERE `ID`=53277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상에 선은 없다. 악도 없어. 빛도 없지. 오직 힘뿐이다!', `MaleText_loc4`='没有善，没有恶，也没有圣光。只有——力量！', `MaleText_loc5`='沒有善良，沒有邪惡，沒有聖光，只有力量!', `MaleText_loc7`='No hay bien. No hay mal. No hay Luz. ¡Solo...PODER!' WHERE `ID`=53278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 빛의 최고 성직자가 아닌가, 베네딕투스. 어떻게 백성들을 배신할 수 있나.', `MaleText_loc4`='你曾被视为圣光的化身，本尼迪塔斯。你怎么能背叛你的人民。', `MaleText_loc5`='你曾是聖光的精神領袖，本尼迪塔斯。你怎麼可以背叛你自己的人民?', `MaleText_loc7`='Eras el emisario de la Luz, Benedictus. ¿Cómo fuiste capaz de traicionar a tu propia gente?' WHERE `ID`=53279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만! 너희랑 놀아 주는 것도 재미있다만, 난 더 중요한 일이 있어 이만 가봐야겠다.', `FemaleText_loc4`='够了！我虽然好客，但现在必须要去处理更重要的事情了。', `FemaleText_loc5`='夠了。我雖然想當稱職的女主人，但是我還有其他事情要忙。', `FemaleText_loc7`='Ya basta. Por mucho que me guste hacer de anfitriona, debo atender asuntos más urgentes.' WHERE `ID`=53280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기수여! 이리 오너라!', `FemaleText_loc4`='骑士们，过来！', `FemaleText_loc5`='騎兵們，護駕!', `FemaleText_loc7`='¡Jinetes, a mí!' WHERE `ID`=53281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적 전선을 손쉽게 통과했거든요. 전혀 무리 없는 작전이 될 것만 같았습죠.', `MaleText_loc4`='我们通过了敌人的阵线——似乎会顺风顺水地一路航行下去。', `MaleText_loc5`='我們成功的穿越了敵人的陣線，看起來似乎可以一路順暢地行駛下去。', `MaleText_loc7`='Atravesamos las líneas enemigas; parecía que iba a ser un camino de rosas.' WHERE `ID`=53282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 나오다니 어쩔 수 없군, 주술사. 만약 내가 본 걸 너도 봤더라면... 그랬다면 이해했을 텐데.', `MaleText_loc4`='我想别无他途了。如果你们能看到我所看到的东西，你们就会明白的。', `MaleText_loc5`='我想只能這樣做了。如果你曾看到我所見的，你就會了解。', `MaleText_loc7`='Supongo que tiene que ser así. Si hubieras visto lo que yo vi, lo entenderías.' WHERE `ID`=53283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 갑자기... 난데없이... 어디에서부턴가 전투기 떼가 나타났지 뭡니까, 대족장님...', `MaleText_loc4`='然后突然之间……意外发生了！不知从哪里冒出来一大堆不速之客，长官……', `MaleText_loc5`='然後事情就發生了...就在一瞬間!一大群戰士從四面八方冒出來，長官...', `MaleText_loc7`='Entonces ocurrió... ¡todo fue de repente! Un montón de luchadores salió de la nada, señor...' WHERE `ID`=53284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천 개의 달빛이여, 이 영광을 저에게 허락해 주십시오.', `MaleText_loc4`='我衷心祈求千月之光能够赐予我这份荣光。', `MaleText_loc5`='我祈求千月之光能賜予我這份榮耀。', `MaleText_loc7`='Rezo para que la luz de mil lunas me conceda este honor.', `FemaleText_loc1`='천 개의 달빛이여, 이 영광을 저에게 허락해 주십시오.', `FemaleText_loc4`='我衷心祈求千月之光能够赐予我这份荣光。', `FemaleText_loc5`='我祈求千月之光能賜予我這份榮耀。', `FemaleText_loc7`='Rezo para que la luz de mil lunas me conceda este honor.' WHERE `ID`=53285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛 중의 빛이시여! 제 목숨은 당신의 것입니다!', `MaleText_loc4`='是的，光中之光！我的生命属于您！', `MaleText_loc5`='是的，聖光之光啊!我的生命屬於你!', `MaleText_loc7`='¡Sí, luz de luces! ¡Mi vida te pertenece!', `FemaleText_loc1`='빛 중의 빛이시여! 제 목숨은 당신의 것입니다!', `FemaleText_loc4`='是的，光中之光！我的生命属于您！', `FemaleText_loc5`='是的，聖光之光啊!我的生命屬於你!', `FemaleText_loc7`='¡Sí, luz de luces! ¡Mi vida te pertenece!' WHERE `ID`=53286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 꽃이시여, 부름을 받들겠습니다. 실망시키지 않겠습니다.', `MaleText_loc4`='生命之花在召唤我。我不会让您失望的，女王陛下。', `MaleText_loc5`='生命之花呼喚著我。我不會讓你失望，女王。', `MaleText_loc7`='La Flor de la Vida me reclama. No te fallaré, mi reina.', `FemaleText_loc1`='생명의 꽃이시여, 부름을 받들겠습니다. 실망시키지 않겠습니다.', `FemaleText_loc4`='生命之花在召唤我。我不会让您失望的，女王陛下。', `FemaleText_loc5`='生命之花呼喚著我。我不會讓你失望，女王。', `FemaleText_loc7`='La Flor de la Vida me reclama. No te fallaré, mi reina.' WHERE `ID`=53287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐... 이봐요! 뭐 하는 겁니까?', `MaleText_loc4`='嘿……嘿！你在做什么？', `MaleText_loc5`='喂...你!你在做什麼?', `MaleText_loc7`='Oye... ¡OYE! ¿Qué haces?' WHERE `ID`=53288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 물건을 훔치고 있군요! 그렇죠?', `MaleText_loc4`='你在偷我的发明，对不对？', `MaleText_loc5`='你在偷我的東西，對吧?', `MaleText_loc7`='Me estás robando la mercancía, ¿verdad?' WHERE `ID`=53289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알렉스트라자 님의 비룡들이 이 버려진 발굴현장 저편에서 우릴 태워줄 걸세. 무기를 점검하게. 아무래도 적이 우리를 기습할 것 같네.

이동할 준비가 되면 알려 주게.', `MaleText_loc4`='阿莱克斯塔萨麾下的巨龙会在这片废墟的另一边接应我们。准备好你们的武器，这个地方太适合打埋伏了。

你们做好行动的准备之后，就告诉我。', `MaleText_loc5`='雅立史卓莎的飛龍會在這個被遺棄的挖掘場另一頭等我們。把武器準備好，這地方我一聞就知道有埋伏。

等你準備好，跟我說一聲。', `MaleText_loc7`='Los dracos de Alexstrasza nos recogerán al otro lado de esta excavación abandonada. Pon a punto tus armas, este lugar apesta a emboscada.

Cuando quieras que nos movamos, avísame.' WHERE `ID`=53290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하아, 뭐 하자는 건지.', `FemaleText_loc4`='一点也不精彩。', `FemaleText_loc5`='唉，真沒意思。', `FemaleText_loc7`='No me impresionan.' WHERE `ID`=53294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 일어서게 만들지 마십시오!', `MaleText_loc4`='别逼我站起来！', `MaleText_loc5`='別逼我站起來!', `MaleText_loc7`='¡No me hagas levantarme!' WHERE `ID`=53295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 할 겁니다. 맹세해요! 이제 일어나기 직전입니다!', `MaleText_loc4`='我发誓，我会干的！我这就要站起来了！', `MaleText_loc5`='我真的會喔，我發誓!我要站起來了喔!', `MaleText_loc7`='¡Te juro que lo haré! ¡Estoy a punto de levantarme!' WHERE `ID`=53296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑니다!', `MaleText_loc4`='看我的！', `MaleText_loc5`='我來了!', `MaleText_loc7`='¡Allá voy!' WHERE `ID`=53297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 역시 속일 수가 없군요. 꽤 영리한 도둑이시네요.', `MaleText_loc4`='哦，我在唬谁呢？你真是个狡猾的小偷。', `MaleText_loc5`='喔，我騙誰啊?你是個狡猾的傢伙，小賊。', `MaleText_loc7`='Bah, ¿a quién quiero engañar? Eres un ladrón astuto.' WHERE `ID`=53298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사랑하는 신하들이여, 내 청을 들어 다오. 이 무례한 것들을 물리쳐라!', `FemaleText_loc4`='亲爱的仆从们，我在此命令你们：除掉那些暴徒。', `FemaleText_loc5`='我鍾愛的支持者，我請求你們，消滅這些暴徒。', `FemaleText_loc7`='Se los ruego, mis amados súbditos. Acaben con estos canallas.' WHERE `ID`=53299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 이딴 일에 신경 쓸 여유가 없다. 영원의 수호자여, 너희의 여왕을 지키겠느냐?', `FemaleText_loc4`='我没时间处理这等琐事。永恒守卫，你们是否愿意为女王而战？', `FemaleText_loc5`='我沒空處理這種小事。永恆守護者，為你們的女王出手好嗎?', `FemaleText_loc7`='No tengo tiempo para tales entretenimientos. Guardianes de la eternidad, ¿defenderán a su Reina?' WHERE `ID`=53300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인들이 아직도 너희의 여왕을 거스르는구나. 누가 이들을 막겠느냐?', `FemaleText_loc4`='这些外来者想要违抗你们女王的意志。谁来阻止他们？', `FemaleText_loc5`='這些陌生人一直想跟你們的女王作對。誰能阻止他們呢?', `FemaleText_loc7`='Aun así, estos extraños se oponen a los deseos de su Reina. ¿Quién los detendrá?' WHERE `ID`=53301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런 행동은 용납되지 않는다.', `FemaleText_loc4`='你们的行为不可饶恕。', `FemaleText_loc5`='你們的行為不可原諒!', `FemaleText_loc7`='Su conducta fue imperdonable.' WHERE `ID`=53302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유감스럽지만, 넌 죽어 마땅해.', `FemaleText_loc4`='真不幸，但罪有应得。', `FemaleText_loc5`='真不幸，你就是該死。', `FemaleText_loc7`='Desafortunado pero merecido.' WHERE `ID`=53303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='완벽한 세계를 창조하려면, 먼저 불완전한 것들을 쓸어 버려야 하지.', `FemaleText_loc4`='要创造一个完美的世界，必须清除一切不完美的东西。', `FemaleText_loc5`='要創造完美的世界，必須清除不完美的人。', `FemaleText_loc7`='Para crear un mundo de perfección, hay que eliminar lo imperfecto.' WHERE `ID`=53304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='간도 크지. 여왕의 몸에 손을 대다니. 저열한 군주라면 격분했을 터.', `FemaleText_loc4`='真大胆，竟敢攻击女王。幸好我宽宏大量。', `FemaleText_loc5`='真大膽，居然對女王動手。幸好我度量大。', `FemaleText_loc7`='Qué atrevimiento, atacar a una Reina. Un monarca inferior estaría furioso.' WHERE `ID`=53305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원의 왕실을 위해 춤춰라.', `FemaleText_loc4`='为永恒王庭跳支舞吧。', `FemaleText_loc5`='為永恆宮廷跳舞吧。', `FemaleText_loc7`='Bailen para la corte eterna.' WHERE `ID`=53306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미처 알아채기 전에, 놈들이 사방을 둘러쌌어요!', `MaleText_loc4`='还没等我们反应过来，他们就已经无处不在了！', `MaleText_loc5`='等我們發現的時候已經被他們包圍了!', `MaleText_loc7`='¡Nos rodearon por todas partes antes de que pudiéramos reaccionar!' WHERE `ID`=53307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 끝까지 화물을 붙들고 있었어요... 뭐, 시작하자마자 끝이 났긴 하지만...', `MaleText_loc4`='我们坚守货物，直至最后……呃，其实也没坚守多久……', `MaleText_loc5`='我們堅守著船貨直到最後，只不過，嗯，這最後來得很快...', `MaleText_loc7`='Nos quedamos con la mercancía hasta el final, que fue, bueno, justo después del principio...' WHERE `ID`=53308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 동안 둥둥 떠다니다가, 마침내 우리 함대가 절 발견했지요...', `MaleText_loc4`='我在水面上漂了好几天，直到被一艘我们的船发现……', `MaleText_loc5`='我漂流了好幾天，直到一艘我們的船注意到我...', `MaleText_loc7`='Estuve flotando durante días, hasta que uno de nuestros barcos me divisó...' WHERE `ID`=53309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 게임을 하려면 무엇이 필요합니까?', `MaleText_loc4`='我要怎么才能玩这个游戏？', `MaleText_loc5`='我需要什麼才能玩這個遊戲?', `MaleText_loc7`='¿Qué necesito para jugar?', `FemaleText_loc1`='이 게임을 하려면 무엇이 필요하나요?', `FemaleText_loc4`='我要怎么才能玩这个游戏？', `FemaleText_loc5`='我需要什麼才能玩這個遊戲?', `FemaleText_loc7`='¿Qué necesito para jugar?' WHERE `ID`=53311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임을 하려면 다크문 게임 동전이 필요하다네.$b$b다크문 축제 지역에 있는 아무 동전 상인에게서나 동전을 구입하게.$b$b내가 지도에 표시해주지.', `MaleText_loc4`='要想玩游戏，你必须拥有暗月游戏代币。$b$b马戏团里到处都有出售代币的商人。$b$b我可以帮你在地图上标记出来。', `MaleText_loc5`='你要有暗月遊戲代幣才能玩。$b$b馬戲團的每個代幣商人都有賣。$b$b我會幫你標記在你的地圖上。', `MaleText_loc7`='Para jugar una partida, necesitas fichas de juego de la Luna Negra.$b$bPuedes comprarlas en los vendedores de fichas de juego de la feria.$b$bLos marcaré en tu mapa.', `FemaleText_loc1`='게임을 하려면 다크문 게임 동전이 필요하답니다.$b$b다크문 축제 지역에 있는 아무 동전 상인에게서나 동전을 구입하세요.$b$b제가 지도에 표시해드릴게요.', `FemaleText_loc4`='要想玩游戏，你必须拥有暗月游戏代币。$b$b马戏团里到处都有出售代币的商人。$b$b我可以帮你在地图上标记出来。', `FemaleText_loc5`='你要有暗月遊戲代幣才能玩。$b$b馬戲團的每個代幣商人都有賣。$b$b我會幫你標記在你的地圖上。', `FemaleText_loc7`='Para jugar una partida, necesitas fichas de juego de la Luna Negra.$b$bPuedes comprarlas en los vendedores de fichas de juego de la feria.$b$bLos marcaré en tu mapa.' WHERE `ID`=53312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 공짜는 없습니다. 다른 곳으로 가보십시오.', `MaleText_loc4`='这里可没有免费的午餐，走吧。', `MaleText_loc5`='這裡可沒有免費的東西，走吧你。', `MaleText_loc7`='Aquí no hay nada gratis, circula.', `FemaleText_loc1`='이곳에 공짜는 없어요. 다른 곳으로 가보세요.', `FemaleText_loc4`='这里可没有免费的午餐，走吧。', `FemaleText_loc5`='這裡可沒有免費的東西，走吧你。', `FemaleText_loc7`='Aquí no hay nada gratis, circula.' WHERE `ID`=53313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임을 하려면 동전을 주십시오.', `MaleText_loc4`='你得先付钱，才能玩。', `MaleText_loc5`='你要玩得先付錢。', `MaleText_loc7`='Tienes que pagar para jugar.', `FemaleText_loc1`='게임을 하려면 동전을 주세요.', `FemaleText_loc4`='你得先付钱，才能玩。', `FemaleText_loc5`='你要玩得先付錢。', `FemaleText_loc7`='Tienes que pagar para jugar.' WHERE `ID`=53314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다. 무료로 게임을 즐기실 수는 없습니다.', `MaleText_loc4`='抱歉伙计，我可不能让你白玩。', `MaleText_loc5`='抱歉老兄，不能讓你免費玩。', `MaleText_loc7`='Lo siento, no puedo dejarte jugar gratis.', `FemaleText_loc1`='죄송해요. 무료로 게임을 즐기실 수는 없어요.', `FemaleText_loc4`='抱歉伙计，我可不能让你白玩。', `FemaleText_loc5`='抱歉老兄，不能讓你免費玩。', `FemaleText_loc7`='Lo siento, no puedo dejarte jugar gratis.' WHERE `ID`=53315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 얼라이언스 겁쟁이들의 포에 격추당했다고?! 미련한 놈들!', `MaleText_loc4`='被一队联盟懦夫给击落了？！真是可鄙！', `MaleText_loc5`='被一群聯盟懦夫擊落?!太可悲了!', `MaleText_loc7`='¡¿Abatidos por un grupo de cobardes de la alianza?! ¡PATÉTICO!' WHERE `ID`=53316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고리 던지기는 어떻게 하는 겁니까?', `MaleText_loc4`='这个套圈圈怎么玩？', `MaleText_loc5`='丟圈圈遊戲要怎麼玩?', `MaleText_loc7`='¿Cómo puedo jugar al lanzamiento de anillo?', `FemaleText_loc1`='고리 던지기는 어떻게 하는 건가요?', `FemaleText_loc4`='这个套圈圈怎么玩？', `FemaleText_loc5`='丟圈圈遊戲要怎麼玩?', `FemaleText_loc7`='¿Cómo puedo jugar al lanzamiento de anillo?' WHERE `ID`=53317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='我明白了。', `MaleText_loc5`='我了解。', `MaleText_loc7`='Comprendo.', `FemaleText_loc1`='알겠어요.', `FemaleText_loc4`='我明白了。', `FemaleText_loc5`='我了解。', `FemaleText_loc7`='Comprendo.' WHERE `ID`=53318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 내게 다크문 축제 게임 동전을 주게. 그다음 내가 망치를 줄 걸세. 그러면 놀들이 게임 진행 구역에 있는 나무통에서 튀어나올 것이네. 그때 놀들을 망치로 때려서 점수를 얻으면 된다네.$b$B그렇지만 까다로운 점이 하나 있네. 바로 놀이 세 종류라는 걸세. 그냥 놀과 들창코 놀, 그리고 아기가 있네.$b$b그냥 놀을 처치하면 1점을 얻네. 또 들창코 놀은 3점이지. 하지만 아기를 때리면?... 아기를 때리게 되면 넘어져서 잠깐 기절할 걸세. 그러니 아기는 절대 때리지 말게나!$b$b주어진 시간 안에 놀들을 다 처치하지 못하면 다시 동전을 써서 새 게임을 할 수 있네! 누적된 점수는 새 게임을 해서 얻은 점수와도 합산되고 말일세.', `MaleText_loc4`='首先，你要给我一个游戏代币。然后我就给你一个大锤。然后你就会看见有豺狼人从游戏场地上的桶里冒出来。$B$B你就要用锤子去打这些豺狼人，来获取积分。$b$B但比较复杂的是，这里一共有三种目标：普通豺狼人，霍格豺狼人和娃娃。$b$b普通豺狼人计一分，霍格豺狼人计三分。而娃娃呢？击打他们会导致你被击倒并昏迷……所以千万别打那些娃娃！$b$b如果你没能在规定时间内砸到足够的豺狼人，可以再花一个代币再试一次！你累积的分数也可以带入下一轮。', `MaleText_loc5`='首先，你先給我一個遊戲代幣。然後，我會給你一把錘子。你會看到豺狼人從遊戲區的桶子裡冒出來。$B$B用錘子打中豺狼人，你就會獲得分數。$b$b要特別注意的是，桶子會出現三種目標:普通豺狼人、大豺狼人，還有寶寶。$b$b普通豺狼人能獲得一分，大豺狼人算三分。至於寶寶?打中寶寶會害你摔跤暈倒...所以千萬不要動手打寶寶!$b$b如果你時間內無法打到夠多的豺狼人，只要多花個代幣就好了!因為你累積的點數是可以沿用到下一場遊戲的。', `MaleText_loc7`='Primero, me das una ficha de juego. Después te doy una marra. Verás cómo van apareciendo gnolls en los tubos de la zona de juego.$B$BGolpea a los gnolls con tu marra para puntuar.$b$bY aquí está el truco... Hay tres tipos de gnoll: normales, Hogger y bebés.$b$bLos gnolls normales te darán un punto y los Hogger, tres. Pero ¿los bebés? Si golpeas a un bebé te caerás y te aturdirán... ¡así que no golpees a los bebés!$b$BSi no golpeas a todos los gnolls a su debido tiempo, gasta otra ficha para volver a intentarlo. Los puntos que ganes se acumulan en la siguiente ronda.', `FemaleText_loc1`='일단 제게 다크문 축제 게임 동전을 주세요. 그다음 제가 망치를 줄 거예요. 그러면 놀들이 게임 진행 구역에 있는 나무통에서 튀어나온답니다. 그때 놀들을 망치로 때려서 점수를 얻으면 돼요.$b$B그렇지만 까다로운 점이 하나 있어요. 바로 놀이 세 종류라는 거죠. 그냥 놀과 들창코 놀, 그리고 아기가 있답니다.$b$b그냥 놀을 처치하면 1점을 얻어요. 또 들창코 놀은 3점이죠. 하지만 아기를 때리면?... 아기를 때리게 되면 넘어져서 잠깐 기절할 거예요. 그러니 아기는 절대 때리지 마세요!$b$b주어진 시간 안에 놀들을 다 처치하지 못하면 다시 동전을 써서 새 게임을 할 수 있어요! 누적된 점수는 새 게임을 해서 얻은 점수와도 합산된답니다.', `FemaleText_loc4`='首先，你要给我一个游戏代币。然后我就给你一个大锤。然后你就会看见有豺狼人从游戏场地上的桶里冒出来。$B$B你就要用锤子去打这些豺狼人，来获取积分。$b$B但比较复杂的是，这里一共有三种豺狼人：普通豺狼人，霍格豺狼人和小豺狼人。$b$b普通豺狼人计一分，霍格豺狼人计三分。而小豺狼人呢？击打他们会导致你被击倒并昏迷……所以千万别打小豺狼人！$b$b如果你没能在规定时间内砸到足够的豺狼人，可以再花一个代币再试一次！你累积的分数也可以带入下一轮。', `FemaleText_loc5`='首先，你先給我一個遊戲代幣。然後，我會給你一把錘子。你會看到豺狼人從遊戲區的桶子裡冒出來。$B$B用錘子打中豺狼人，你就會獲得分數。$b$b要特別注意的是，桶子會出現三種目標:普通豺狼人、大豺狼人，還有寶寶。$b$b普通豺狼人能獲得一分，大豺狼人算三分。至於寶寶?打中寶寶會害你摔跤暈倒...所以千萬不要動手打寶寶!$b$b如果你時間內無法打到夠多的豺狼人，只要多花個代幣就好了!因為你累積的點數是可以沿用到下一場遊戲的。', `FemaleText_loc7`='Primero, me das una ficha de juego. Después te doy una marra. Verás cómo van apareciendo gnolls en los tubos de la zona de juego.$B$BGolpea a los gnolls con tu marra para puntuar.$b$bY aquí está el truco... Hay tres tipos de gnoll: normales, Hogger y bebés.$b$bLos gnolls normales te darán un punto y los Hogger, tres. Pero ¿los bebés? Si golpeas a un bebé te caerás y te aturdirán... ¡así que no golpees a los bebés!$b$BSi no golpeas a todos los gnolls a su debido tiempo, gasta otra ficha para volver a intentarlo. Los puntos que ganes se acumulan en la siguiente ronda.' WHERE `ID`=53319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀 때려잡기 게임은 어떻게 하는 겁니까?', `MaleText_loc4`='打豺狼人要怎么玩？', `MaleText_loc5`='要怎樣玩痛扁豺狼人?', `MaleText_loc7`='¿Cómo puedo jugar a Golpea al gnoll?', `FemaleText_loc1`='놀 때려잡기 게임은 어떻게 하는 건가요?', `FemaleText_loc4`='打豺狼人要怎么玩？', `FemaleText_loc5`='要怎樣玩痛扁豺狼人?', `FemaleText_loc7`='¿Cómo puedo jugar a Golpea al gnoll?' WHERE `ID`=53320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통통 전차 게임은 어떻게 하는 겁니까?', `MaleText_loc4`='蒸汽坦克大挑战该怎么玩？', `MaleText_loc5`='坦克遊戲怎麼玩呢?', `MaleText_loc7`='¿Cómo puedo jugar a la batalla de tonques?', `FemaleText_loc1`='통통 전차 게임은 어떻게 하는 건가요?', `FemaleText_loc4`='蒸汽坦克大挑战该怎么玩？', `FemaleText_loc5`='坦克遊戲怎麼玩呢?', `FemaleText_loc7`='¿Cómo puedo jugar a la batalla de tonques?' WHERE `ID`=53321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 제국은 이미 수 세기 전에 무너졌습니다. 이 폐허는 까마득한 옛날부터 이곳에 버려진 채로 있었습니다.$B$B놈들이 어째서 지금 돌아온 걸까요?', `MaleText_loc4`='魔古帝国早就被推翻了。从那以后，这些遗迹就一直荒弃于此，已经记不清有多少个年头了。$b$b为什么他们偏偏现在回来了？', `MaleText_loc5`='魔古帝國已被推翻有數世紀之久。這些遺跡被廢棄在這裡的歷史和我們所有人的記憶一樣長。$B$B為什麼他們會在這時候出現?', `MaleText_loc7`='El imperio mogu cayó hace siglos. Estas ruinas llevan abandonadas desde que tenemos memoria.$b$b¿Por qué iban a volver ahora?' WHERE `ID`=53322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 내게 다크문 축제 게임 동전을 하나 주게나. 그러면 자네는 통통 전차를 조종할 수 있다네!$b$b주어진 시간 동안 전장에 있는 목표물을 모두 파괴해야 하네. 목표물을 파괴할 때마다 얻는 점수는 1점일세.$b$b하지만 조심하게. 전장에는 또 다른 악랄한 통통 전차와 비행선이 있네. 이것들에게 공격 받으면 통통 전차가 피해를 입게 되지.$b$b획득한 점수는 다음 게임을 할 때도 누적되네. 그러니 통통 전차가 폭발하더라도 걱정하지 말게나.', `MaleText_loc4`='首先，你要先给我一个游戏代币。然后，你就可以操纵一辆蒸汽坦克。$b$b你需要驾驶坦克，在有限的时间内炸飞战场上的目标。每摧毁一个目标，你可以得一分。$b$b不过你要注意，战场上还有一些邪恶坦克和飞艇。被它们打中会损毁你的坦克。$b$b你的分数可以累积到下一轮，所以死了也不用担心。', `MaleText_loc5`='首先，你先給我一個遊戲代幣，然後你就能控制一台蒸汽坦克。$b$b你得在限定的時間內擊中戰場上的目標，每摧毀一個目標就能贏得一點積分。$b$b但要小心:戰場上同時也有著敵方的坦克跟飛艇，被它們擊中會使你的坦克受損。$b$b你的分數在結束後會帶到下一場遊戲中，所以就算被打爆了也不用擔心。', `MaleText_loc7`='Primero, me das una ficha de juego. Después estarás en los controles de un tonque de vapor.$b$bTienes un límite de tiempo para disparar a todos los objetivos del campo de batalla. Con cada objetivo que destruyas ganarás un punto.$b$bPero cuidado, en el campo de batalla te encontrarás algunos zepelines y tonques enemigos. Tu tonque sufrirá daños si te alcanzan con sus disparos.$b$bTu puntuación se guardará de un tonque a otro, así que no te preocupes si explotas.', `FemaleText_loc1`='일단 제게 다크문 축제 게임 동전을 하나 주세요. 그러면 당신은 통통 전차를 조종할 수 있답니다!$b$b주어진 시간 동안 전장에 있는 목표물을 모두 파괴해야 해요. 목표물을 파괴할 때마다 얻는 점수는 1점이고요.$b$b하지만 조심하세요. 전장에는 또 다른 악랄한 통통 전차와 비행선이 있답니다. 이것들에게 공격 받으면 통통 전차가 피해를 입게 돼요.$b$b획득한 점수는 다음 게임을 할 때도 누적된답니다. 그러니 통통 전차가 폭발하더라도 걱정하지 마세요.', `FemaleText_loc4`='首先，你要先给我一个游戏代币。然后，你就可以操纵一辆蒸汽坦克。$b$b你需要驾驶坦克，在有限的时间内炸飞战场上的目标。每摧毁一个目标，你可以得一分。$b$b不过你要注意，战场上还有一些邪恶坦克和飞艇。被它们打中会损毁你的坦克。$b$b你的分数可以累积到下一轮，所以死了也不用担心。', `FemaleText_loc5`='首先，你先給我一個遊戲代幣，然後你就能控制一台蒸汽坦克。$b$b你得在限定的時間內擊中戰場上的目標，每摧毀一個目標就能贏得一點積分。$b$b但要小心:戰場上同時也有著敵方的坦克跟飛艇，被它們擊中會使你的坦克受損。$b$b你的分數在結束後會帶到下一場遊戲中，所以就算被打爆了也不用擔心。', `FemaleText_loc7`='Primero, me das una ficha de juego. Después estarás en los controles de un tonque de vapor.$b$bTienes un límite de tiempo para disparar a todos los objetivos del campo de batalla. Con cada objetivo que destruyas ganarás un punto.$b$bPero cuidado, en el campo de batalla te encontrarás algunos zepelines y tonques enemigos. Tu tonque sufrirá daños si te alcanzan con sus disparos.$b$bTu puntuación se guardará de un tonque a otro, así que no te preocupes si explotas.' WHERE `ID`=53323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 그린치를 없애버렸어!', `MaleText_loc4`='他们杀了格林奇！', `MaleText_loc5`='他們把格林奇殺死了!', `MaleText_loc7`='¡Han matado al Grinch!' WHERE `ID`=53324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐!', `MaleText_loc4`='快跑！', `MaleText_loc5`='逃啊!', `MaleText_loc7`='¡Corre!' WHERE `ID`=53325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 배는... 어디에... 있나!?', `MaleText_loc4`='我……的……船呢？！', `MaleText_loc5`='我...的...船...在...哪!?', `MaleText_loc7`='¿¡Dónde... está... mi... barco!?' WHERE `ID`=53326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제... 제가 마지막으로 봤을 땐, 안개 낀 해안으로 들어가고 있었어요... 얼라이언스가 쫓아오고... 그 뒤로 어떻게 되었는지는 아무도 모릅니다, 대족장님...', `MaleText_loc4`='驶进了一片浓雾里，然后就再也没见过了，后面有联盟在追……不——不知道后来怎么样了，长官……', `MaleText_loc5`='我，我最後一次見到...他們駛進濃霧...追捕聯盟...不，不知道他們遭遇什麼事，長官...', `MaleText_loc7`='Na... navegando hasta un banco de niebla, lo último que vi, la Alianza nos perseguía... no... no sabría decir qué fue de ellos, señor...' WHERE `ID`=53327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 다크문 게임 동전 한 개를 내게 주면, 내가 라이플 총을 줄걸세.$B$B그 다음 자네는 반짝거리는 과녁을 쏘면 된다네.$b$b과녁이 반짝거릴 때 바로 쏠 수 있을 정도로 빨리 쏘면 추가 점수를 얻을 수 있네.$b$b주어진 시간 안에 점수를 다 얻지 못했거나, 아니면 게임 도중에 여기를 벗어나더라도 걱정하지 말게. 기존 게임에서 얻은 점수는 다음 게임에도 누적된다네.', `MaleText_loc4`='首先，你得给我一个游戏代币，而我会给你一把步枪。$B$B然后，你就用枪射击那些亮起来的靶子。$b$b如果你出手够快，能在目标亮起后直接击中它，那你就能额外得到一分。$b$b如果你没在规定时间内打到足够的分数，或者离开了游戏场地，也不用担心。你的分数可以带到下一轮游戏里。', `MaleText_loc5`='首先，你得給我一個遊戲代幣，我就給你一把氣彈步槍。$B$B然後，用它射擊亮起來的目標。$b$b如果你動作夠快，在目標亮起來之後立刻射中它，就能獲得額外的分數。$b$b如果你在時間結束前沒辦法達到指定的分數，或你離開了場地，也不用擔心。你的分數會保留到下一場遊戲計算。', `MaleText_loc7`='Primero, te doy una escopeta de balines a cambio de una ficha de juego de la Luna Negra.$B$BDespués, disparas al objetivo que se ilumine.$b$bSi eres lo suficientemente ágil y alcanzas un objetivo justo después de que se ilumine conseguirás un punto extra.$b$bSi no alcanzas el límite de puntos cuando acaba el tiempo, o te mueves del puesto, no te preocupes. Tu puntuación se guardará para la próxima partida.', `FemaleText_loc1`='정말 "멈춰 있는 과녁은 어떻게 쏴요?"라고 물어보시는 거예요?$b$b첫 번째이자 가장 중요한 점은 제게 동전을 주셔야 한다는 거죠. 두 번째로는, 제가 라이플 총을 드릴 거예요. 세 번째, 그 총으로 불이 켜지는 과녁을 쏘세요.$b$b아주 재빠르게 쏘거나, 과녁에 불이 들어온 뒤 바로 쏘면 추가 점수를 얻을 수 있답니다.$b$b주어진 시간 안에 점수를 다 얻지 못했거나, 아니면 게임 도중에 여기를 벗어나더라도 걱정하지 마세요. 기존 게임에서 얻은 점수는 다음 게임에도 누적되니까요.', `FemaleText_loc4`='首先，你得给我一个游戏代币，而我会给你一把步枪。$B$B然后，你就用枪射击那些亮起来的靶子。$b$b如果你出手够快，能在目标亮起后直接击中它，那你就能额外得到一分。$b$b如果你没在规定时间内打到足够的分数，或者离开了游戏场地，也不用担心。你的分数可以带到下一轮游戏里。', `FemaleText_loc5`='首先，你得給我一個遊戲代幣，我就給你一把氣彈步槍。$B$B然後，用它射擊亮起來的目標。$b$b如果你動作夠快，在目標亮起來之後立刻射中它，就能獲得額外的分數。$b$b如果你在時間結束前沒辦法達到指定的分數，或你離開了場地，也不用擔心。你的分數會保留到下一場遊戲計算。', `FemaleText_loc7`='Primero, te doy una escopeta de balines a cambio de una ficha de juego de la Luna Negra.$B$BDespués, disparas al objetivo que se ilumine.$b$bSi eres lo suficientemente ágil y alcanzas un objetivo justo después de que se ilumine conseguirás un punto extra.$b$bSi no alcanzas el límite de puntos cuando acaba el tiempo, o te mueves del puesto, no te preocupes. Tu puntuación se guardará para la próxima partida.' WHERE `ID`=53328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격을 하려면 어떻게 해야 합니까?', `MaleText_loc4`='这个射击游戏怎么玩？', `MaleText_loc5`='打靶場的遊戲要怎麼玩?', `MaleText_loc7`='¿Cómo funciona la galería de tiro?', `FemaleText_loc1`='사격을 하려면 어떻게 해야 하나요?', `FemaleText_loc4`='这个射击游戏怎么玩？', `FemaleText_loc5`='打靶場的遊戲要怎麼玩?', `FemaleText_loc7`='¿Cómo funciona la galería de tiro?' WHERE `ID`=53329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='송구스러운 말씀입니다만, 대족장님, 이미 엎질러진 물입니다. 앞으로 작전을 어떻게 전개할 것인가에 집중해야 합니다...', `MaleText_loc4`='恕我直言，酋长，过去的已经过去了。我们现在必须集中全力做好下一步打算……', `MaleText_loc5`='請容我說一句，大酋長，發生的事就發生了。我們現在必須把重點放在如何進行...', `MaleText_loc7`='Con el debido respeto, Jefe de Guerra; lo hecho, hecho está. Debemos centrar nuestros esfuerzos en cómo proceder...' WHERE `ID`=53330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇에 집중해야 할지는 내가 알려주마, 장군.', `MaleText_loc4`='让我来告诉你下一步打算是什么，将军。', `MaleText_loc5`='我會告訴你我們要如何進行，將軍。', `MaleText_loc7`='Te diré cómo vamos a proceder, General.' WHERE `ID`=53331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 네 최고의 병사들을 모아! 그리고 내 배를 찾아내!', `MaleText_loc4`='你去召集所有精兵强将，给我把船找回来！', `MaleText_loc5`='你去把你最好的手下集合起來，然後把我的船找回來!', `MaleText_loc7`='¡Vas a reunir a tus mejores hombres para buscar mi barco!' WHERE `ID`=53332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났습니다. 하지만 여기서 꾸물거려서는 안 됩니다. 폐허 동쪽 끝에서 뵙겠습니다.', `MaleText_loc4`='完成了，此地不宜久留。回去之后到营地东边来找我。', `MaleText_loc5`='完成了，但我們不該逗留。回去和我在營地東端碰面。', `MaleText_loc7`='Hemos terminado, pero no deberíamos quedarnos aquí. Reúnete conmigo en el lado oriental del campamento.' WHERE `ID`=53333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 바짝 차리십시오. 악마가 근처에 있습니다.', `MaleText_loc4`='机灵点。这附近有恶魔。', `MaleText_loc5`='保持警戒。附近有惡魔呢。', `MaleText_loc7`='¡Mantén la cabeza fría! Hay demonios cerca.' WHERE `ID`=53334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 잘하셨습니다! 캘타스 선스트라이더의 진정한 최후였으면 좋겠군요.', `MaleText_loc4`='干得好，英雄们！但愿凯尔萨斯·逐日者能永远从这个世界上消失。', `MaleText_loc5`='做得好，英雄們!讓我們希望這次是最後一次凱爾薩斯·逐日者出現在這個世界上。', `MaleText_loc7`='¡Bien hecho, héroes! Esperemos que esto sea lo último que verá el mundo de Kael''thas Caminante del Sol.' WHERE `ID`=53335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들이여, 지금입니다. 공격하세요!', `MaleText_loc4`='就是现在，朋友。进攻！', `MaleText_loc5`='就是現在，朋友們。進攻!', `MaleText_loc7`='Ahora, amigos. ¡Al ataque!' WHERE `ID`=53336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 한번 정복해 보시지!', `MaleText_loc4`='尝尝我的厉害！', `MaleText_loc5`='來征服我們啊!', `MaleText_loc7`='¡Somete ESTO!', `FemaleText_loc1`='우리도 한번 정복해 봐!', `FemaleText_loc4`='尝尝我的厉害！', `FemaleText_loc5`='來征服我們啊!', `FemaleText_loc7`='¡Somete ESTO!' WHERE `ID`=53337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕 폐하를 위해 사역할 놈이 또 나타났구나!', `MaleText_loc4`='雷电之王又多了些免费的苦力！', `MaleText_loc5`='募召雷王的勞動志願者!', `MaleText_loc7`='¡Más voluntarios para la mano de obra del Rey del Trueno!' WHERE `ID`=53338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 네가 두렵지 않다!', `MaleText_loc4`='我们可不怕你！', `MaleText_loc5`='我們不怕你!', `MaleText_loc7`='¡No os tenemos miedo!', `FemaleText_loc1`='우린 네가 무섭지 않아!', `FemaleText_loc4`='我们可不怕你！', `FemaleText_loc5`='我們不怕你!', `FemaleText_loc7`='¡No os tenemos miedo!' WHERE `ID`=53339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 멍청이들이 내 스톰스타우트 한정판 특별주를 박살냈다... 아껴 마시던 거란 말이다!!', `MaleText_loc4`='呆子，你打碎了一坛风暴烈酒陈酿……我藏了好多年的！！！', `MaleText_loc5`='你手下那群暴徒砸了我的特藏風暴烈酒...那是我特別留著喝的啊!', `MaleText_loc7`='Tus esbirros han roto mi barril de Cerveza de Trueno Gran Reserva... ¡La estaba guardando para una ocasión especial!', `FemaleText_loc1`='너희 멍청이들이 내 스톰스타우트 한정판 특별주를 박살냈어... 아껴 마시던 거란 말야!!', `FemaleText_loc4`='呆子，你打碎了一坛风暴烈酒陈酿……我藏了好多年的！！！', `FemaleText_loc5`='你手下那群暴徒砸了我的特藏風暴烈酒...那是我特別留著喝的啊!', `FemaleText_loc7`='Tus esbirros han roto mi barril de Cerveza de Trueno Gran Reserva... ¡La estaba guardando para una ocasión especial!' WHERE `ID`=53340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다, 이 못생긴 녀석아!', `MaleText_loc4`='来这边，丑八怪！', `MaleText_loc5`='在這邊啊，醜八怪!', `MaleText_loc7`='¡Aquí, feo!', `FemaleText_loc1`='여기라고, 이 못생긴 녀석아!', `FemaleText_loc4`='来这边，丑八怪！', `FemaleText_loc5`='在這邊啊，醜八怪!', `FemaleText_loc7`='¡Aquí, feo!' WHERE `ID`=53341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤에 앉은 세 명부터 소개하지.', `MaleText_loc4`='从我身后这三位开始吧。', `MaleText_loc5`='讓我們從站我後面那三個傢伙開始。', `MaleText_loc7`='Empecemos con los tres que se sientan detrás de mí.' WHERE `ID`=53342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽은 미앙 교관이네. 가장 기본적인 전투 기술을 자네에게 가르쳐줄 걸세.', `MaleText_loc4`='坐在你面前这位是孟教头。她会教你用于实战的功夫。', `MaleText_loc5`='在你面前的是講師崔眠。她負責教導你最實用的戰鬥技藝。', `MaleText_loc7`='Ante ti se encuentra la maestra Myang. Ella será la responsable de enseñarte las técnicas de lucha más prácticas.' WHERE `ID`=53343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 수도원에 들어오기 전에, 미앙은 한 번의 전투에서 날뛰는 호젠 백 마리를 무찌른 적이 있다고들 하네.', `MaleText_loc4`='传言她在进入禅院之前是位以一敌百的高手——她一口气收拾了一百只狂暴的猢狲。', `MaleText_loc5`='據說在她加入我們寺院之前，講師崔眠在肉搏戰裡擊敗了一百名狂亂的猴人。', `MaleText_loc7`='Se rumorea que, antes de unirse a nuestro monasterio, Myang derrotó a un centenar de hozen saqueadores en un solo combate.' WHERE `ID`=53344;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='과찬의 말씀이십니다, 대장로님. 호젠들은 약하고, 어리고, 실력이 미천했습니다. 판다렌이라면 누구나 물리칠 수 있었을 것입니다.', `FemaleText_loc4`='您太抬举我了，长老。那些弱小的猢狲既年幼又没有战斗经验。任何一名熊猫人都能轻松获胜的。', `FemaleText_loc5`='你誇得我太過了，高階長者。那些猴人弱小、年輕又技術不足。任何熊貓人都能辦到。', `FemaleText_loc7`='Me halagas, gran ancestro. Esos hozen eran débiles, jóvenes e inexpertos. Cualquier otro pandaren habría hecho lo mismo.' WHERE `ID`=53345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과찬이라니? 넌 그때 여덟 살이 아니었더냐.', `MaleText_loc4`='抬举你？那时你才八岁。', `MaleText_loc5`='誇得太過?你那時才八歲呢。', `MaleText_loc7`='¿Halagarte? Solo tenías ocho años.' WHERE `ID`=53346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 여덟 살 반이었습니다, 대장로님.', `FemaleText_loc4`='……八岁半了，长老。', `FemaleText_loc5`='...是八歲半。長者。', `FemaleText_loc7`='...y medio, señor.' WHERE `ID`=53347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음으로, 여기 바위주먹 사부가 자네의 대련 연습을 책임질 것이네.', `MaleText_loc4`='这位是石拳大师。他会主持你的过招训练。', `MaleText_loc5`='接著，我們有石拳大師。他會負責傳授你拳法的訓練。', `MaleText_loc7`='Después, tenemos al maestro Puño Firme. Él se encargará de tus ejercicios de entrenamiento.' WHERE `ID`=53348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위주먹 사부는 일대일 대결에서는 상대할 수 있는 이가 거의 없네. 한때는 999명의 도전자를 차례로 무찌른 적도 있어.', `MaleText_loc4`='石拳大师在一对一的比试里几乎未尝一败。他的最高连胜纪录是九百九十九场。', `MaleText_loc5`='石拳大師在單挑比武中近乎不敗。他曾經連續擊敗九百九十九名挑戰者。', `MaleText_loc7`='El maestro Puño Firme es prácticamente inigualable en el combate individual. Una vez derrotó a novecientos noventa y nueve oponentes seguidos.' WHERE `ID`=53349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1000번째 도전자는 반칙을 했죠.', `MaleText_loc4`='第一千个挑战者使诈了。', `MaleText_loc5`='第一千名挑戰者作了弊。', `MaleText_loc7`='El número mil hizo trampas.' WHERE `ID`=53350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고? 반칙이라니!?', `MaleText_loc4`='什么？使诈？', `MaleText_loc5`='什麼?作弊!?', `MaleText_loc7`='¿Cómo que trampas?' WHERE `ID`=53351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 절대로 반칙을 하지 않네!', `MaleText_loc4`='我可不会使诈！', `MaleText_loc5`='我從不作弊!', `MaleText_loc7`='¡Yo nunca hago trampas!' WHERE `ID`=53352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 산 교관이네. 전투의 기초를 온전하게 체득해서, 이제는 완벽에 가까운 동작을 완성했지.', `MaleText_loc4`='最后一位是夏教头。他十分注重基本功的磨砺，他使出的每一招都臻乎完美。', `MaleText_loc5`='最後，講師老詹。他精通所有戰鬥基礎，這讓他具備了至臻完美的身法。', `MaleText_loc7`='Y, por último, el instructor Xann. Su dominio de las bases del combate le ha otorgado un estilo de lucha casi perfecto.' WHERE `ID`=53353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산, 자네 제자들이 지르기 연습을 하루에 몇 번이나 하지?', `MaleText_loc4`='夏，你的徒弟每天会练多少次直拳？', `MaleText_loc5`='老詹，你的學生每天做多少次打擊練習?', `MaleText_loc7`='Xann, ¿cuántos golpes practican tus estudiantes a diario?' WHERE `ID`=53354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일만 번입니다. 매일요.', `MaleText_loc4`='一万次，每天。', `MaleText_loc5`='每天每天，一萬次滿懷感激的正拳。', `MaleText_loc7`='Diez mil golpes al día.' WHERE `ID`=53355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 자네는 몇 번이나 하나?', `MaleText_loc4`='*你*每天会练多少次呢？', `MaleText_loc5`='而你，每天能練幾拳?', `MaleText_loc7`='¿Y cuántos practicas tú?' WHERE `ID`=53356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일만 한 번입니다.', `MaleText_loc4`='一万零一次。', `MaleText_loc5`='一萬零一拳。', `MaleText_loc7`='Diez mil y uno.' WHERE `ID`=53357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장로는 기초 훈련을 하지 않아도 돼서 정말 다행이야. 난 운동을 하지 않을 때 더 행복하더군.', `MaleText_loc4`='幸好当上长老之后我就不用练基本功了。老实说，自从不练功之后我的心情好了很多。', `MaleText_loc5`='幸運的是，高階長者不用再做基本訓練。我發現我不練習時會比較開心。', `MaleText_loc7`='Afortunadamente, los grandes ancestros ya no tenemos que realizar un entrenamiento básico. Creo que soy más feliz cuando no me ejercito.' WHERE `ID`=53358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오게. 함께 걸으며 한잔하세, $n.', `MaleText_loc4`='走吧，陪我喝上两杯，$n。', `MaleText_loc5`='陪我邊走邊喝點酒，$n。', `MaleText_loc7`='Camina y bebe conmigo.' WHERE `ID`=53359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이쪽에는 영혼현자 가오취앤 님이 계시군. 우리 수도원의 최고 연장자시네.', `MaleText_loc4`='啊！这里坐的是灵魂贤者高全，他是这间禅院最年长的成员。', `MaleText_loc5`='啊!在這桌子上，你會看見靈魂先知高泉，我們寺廟最古老的成員。', `MaleText_loc7`='¡Ah! En esta mesa se encuentra el sabio espiritual Gaoquan, el miembro más antiguo de nuestro monasterio.' WHERE `ID`=53360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 대장로들이 오고 가는 모습을 보신 분이지. 그리고 이런 연회를 아주 심각하게 좋아하신다네.', `MaleText_loc4`='他见证了许多长老的兴衰沉浮。他对这些庆典也非常重视。', `MaleText_loc5`='他見過許多高階長者來來去去，他也將這些慶典看得很重。', `MaleText_loc7`='Ha visto ir y venir a muchos grandes ancestros. También suele conceder gran importancia a estas celebraciones.' WHERE `ID`=53361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원에 호젠과 진위도 함께 있다는 사실을 눈치챘겠지? 수도원은 모든 이를 환영한다네, 배우려는 의지만 있다면.', `MaleText_loc4`='你或许已经注意到，我们之中既有猢狲，也有锦鱼人。无论是谁，只要他渴望求知，禅院都会欢迎的。', `MaleText_loc5`='你或許已經發現有猴人和錦魚人和我們一起。只要有求知的心，這間寺廟歡迎所有人。', `MaleText_loc7`='Quizás te hayas percatado de la presencia de hozen y jinyu entre nosotros. Todos somos bienvenidos, siempre y cuando tengamos el deseo de aprender.' WHERE `ID`=53362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 우 관리인이네.', `MaleText_loc4`='最后，这位是园丁老吴。', `MaleText_loc5`='終於，這位是園丁老吳。', `MaleText_loc7`='Finalmente, este es el guardés Wu.' WHERE `ID`=53363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우!', `MaleText_loc4`='老吴！', `MaleText_loc5`='老吳!', `MaleText_loc7`='¡WU!' WHERE `ID`=53364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 네, 대 <딸꾹> 장로님?', `MaleText_loc4`='在……在，长<嗝>老？', `MaleText_loc5`='是...是的，高階<嗝>長者?', `MaleText_loc7`='¿S... sí, gran <hip> ancestro?' WHERE `ID`=53365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우, 여기는 $n|1이;;네. 다른 수련생들과 함께 수련할 걸세.', `MaleText_loc4`='吴，这是$n。$G他:她;将和其他弟子一起接受训练。', `MaleText_loc5`='老吳，這是$n。$G他:她;會加入其他弟子的行列。', `MaleText_loc7`='Wu, $geste:esta; es $n. Pronto se unirá a los otros alumnos.' WHERE `ID`=53366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... <딸꾹>... 안녕하세요... $n 니이이이임...', `MaleText_loc4`='哦……<嗝>……你好……$n呼呼……', `MaleText_loc5`='喔...<嗝>...幸會啊...$n啊噗啦...', `MaleText_loc7`='Oh...<hip>... Hola... $nsszzhhhh..' WHERE `ID`=53367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우가 자네에게 일을 몇 가지 시킬 걸세. 어려운 일은 아니네. 수도원을 유지하기 위한 단순한 작업들이야.', `MaleText_loc4`='老吴会要你帮忙干些杂务。没什么复杂的，就是些禅院的日常维护工作。', `MaleText_loc5`='老吳會要求你做點勞務。沒什麼複雜的，只是一些維護寺院的日常工作。', `MaleText_loc7`='Wu te encargará unas cuantas tareas. Nada complicado, solo algunas faenas relacionadas con el mantenimiento del monasterio.' WHERE `ID`=53368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 이곳, 우리의 집을 보살펴야 할 책임이 있네. 대장로라도 때때로 힘을 보태야 하지.', `MaleText_loc4`='我们都有义务和责任来维护好我们共同的家。就算是长老，偶尔也要搭把手。', `MaleText_loc5`='我們都有責任維護我們的家。就連高階長者也得時不時幫點忙。', `MaleText_loc7`='Todos somos responsables del mantenimiento de nuestro hogar. Hasta los grandes ancestros ayudan alguna que otra vez.' WHERE `ID`=53369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다들 만나 본 셈이군. 이런, 여기 좀 보게. 내 술잔이 다시 가득 채워졌군! 대장로 노릇도 할 만하다니까.', `MaleText_loc4`='你现在明白了吧。瞧见没？我的杯子又满了！当长老还真不错。', `MaleText_loc5`='你現在瞭解情況了。你看看?我的杯子又滿了!當個高階長者真好。', `MaleText_loc7`='Ahora ya sabes todo lo que necesitas. Pero ¿has visto eso? ¡Me han vuelto a llenar la copa! Me encanta ser un gran ancestro.' WHERE `ID`=53370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, $n. 자네를 이렇게 맞이하게 되어 무척 기쁘군. 오늘 이 연회는 자네가 이곳에 도착한 것과 더불어, 우리 수도원에 새로운 수련생들을 맞이하게 되었음을 축하하는 자리네.$b$b부디 우리가 마련한 음식과 음료를 마음껏 즐기길 바라네. 그리고 자네만 괜찮다면, 우리 교관들을 소개해 주고 싶군.', `MaleText_loc4`='欢迎，$n。你能来做客是我们的荣幸。今天，我们不仅要为你接风，也为了即将加入禅院的一批新弟子而庆祝。$b$b请随意享用我们准备的食物和酒水。等你准备好后，我要为你引见几位禅院的教头。', `MaleText_loc5`='歡迎，$n。我們很榮幸有你來擔任我們的貴客。今天，我們不只歡慶你的到來，更慶祝一班新弟子在敝寺的嶄新起步。$b$b請享用我們準備的酒菜。待你準備好時，我很樂意向你介紹我們寺院的幾位導師。', `MaleText_loc7`='Te damos la bienvenida, $n. Es un honor tenerte como huésped. Hoy, no solo celebramos tu llegada, sino el comienzo de una nueva clase de alumnos de nuestro monasterio.$b$bDisfruta de la comida y la bebida que hemos preparado. Cuando estés $gpreparado:preparada;, me gustaría presentarte a algunos de los instructores del monasterio.' WHERE `ID`=53371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, $n. 목을 축이고 배를 채우거든 다시 내게 돌아오게.', `MaleText_loc4`='非常好，$n。等你吃饱喝足之后再来找我吧。', `MaleText_loc5`='非常好，$n。待你的飢渴得到滿足後回來找我。', `MaleText_loc7`='Muy bien, $n. Vuelve cuando hayas saciado el hambre y la sed.' WHERE `ID`=53372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실한가? 교관들은 자네처럼 솜씨 좋은 $r $c|1이;;라면 언제든 만나고 싶어할 거야.', `MaleText_loc4`='你确定吗？教头们会很乐意见到像你这样经验丰富的$r $c。', `MaleText_loc5`='你確定嗎?講師們會很樂意和像你這樣經驗老到的$r$c碰面。', `MaleText_loc7`='¿Estás $gseguro:segura;? A los instructores les encantaría conocer a $gun:una; $r $c con experiencia como tú.' WHERE `ID`=53373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원한다면 그렇게 하지. 이 자리를 빛내 주는 $n|1을;를; 위해 건배!', `MaleText_loc4`='如你所愿。干杯！敬我们的贵客，$n！', `MaleText_loc5`='如你所請。為了我們的貴客$n，舉杯!', `MaleText_loc7`='Como desees. ¡Un brindis por $gnuestro:nuestra; honorable $ginvitado:invitada;, $n!' WHERE `ID`=53374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교관들을 만날 준비가 됐습니다, 대장로님.', `MaleText_loc4`='我已经做好参见教头们的准备了，长老。', `MaleText_loc5`='我準備好面見講師們了，高階長者。', `MaleText_loc7`='Estoy listo para presentarme ante los instructores, gran ancestro.', `FemaleText_loc1`='교관들을 만날 준비가 됐어요, 대장로님.', `FemaleText_loc4`='我已经做好参见教头们的准备了，长老。', `FemaleText_loc5`='我準備好面見講師們了，高階長者。', `FemaleText_loc7`='Estoy lista para presentarme ante los instructores, gran ancestro.' WHERE `ID`=53375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려 주십시오. 아직 준비가 안 됐습니다.', `MaleText_loc4`='再等一会，我还没喝好呢。', `MaleText_loc5`='再等一會兒。我還沒準備好。', `MaleText_loc7`='Dame un segundo, aún no estoy listo.', `FemaleText_loc1`='잠깐만 기다려 주세요. 아직 준비가 안 됐어요.', `FemaleText_loc4`='再等一会，我还没喝好呢。', `FemaleText_loc5`='再等一會兒。我還沒準備好。', `FemaleText_loc7`='Dame un segundo, aún no estoy lista.' WHERE `ID`=53376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소개해 주실 필요 없습니다. 그냥 넘어가시지요.', `MaleText_loc4`='我无需任何介绍，老人家。我们还是直奔主题吧。', `MaleText_loc5`='我不需要什麼指引，老頭子。直接跳到精采的部份就好。', `MaleText_loc7`='No necesito presentaciones, anciano. Vamos directamente a lo que importa.', `FemaleText_loc1`='소개해 주실 필요 없어요. 그냥 넘어가시죠.', `FemaleText_loc4`='我无需任何介绍，老人家。我们还是直奔主题吧。', `FemaleText_loc5`='我不需要什麼指引，老頭子。直接跳到精采的部份就好。', `FemaleText_loc7`='No necesito presentaciones, anciano. Vamos directamente a lo que importa.' WHERE `ID`=53377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 소개해 주십시오.', `MaleText_loc4`='很好。让我们继续介绍吧。', `MaleText_loc5`='好啦。讓我們開始介紹吧。', `MaleText_loc7`='Bien. Procedamos con las presentaciones.', `FemaleText_loc1`='좋습니다. 소개해 주세요.', `FemaleText_loc4`='很好。让我们继续介绍吧。', `FemaleText_loc5`='好啦。讓我們開始介紹吧。', `FemaleText_loc7`='Bien. Procedamos con las presentaciones.' WHERE `ID`=53378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니다. 어서 대전하는 부분으로 넘어가시지요.', `MaleText_loc4`='我确定。让我们开始战斗吧。', `MaleText_loc5`='我說真的，現在就去戰鬥吧。', `MaleText_loc7`='No me cabe duda. Pasemos a la acción.', `FemaleText_loc1`='정말이에요. 어서 대전하는 부분으로 넘어가시죠.', `FemaleText_loc4`='我确定。让我们开始战斗吧。', `FemaleText_loc5`='我說真的，現在就去戰鬥吧。', `FemaleText_loc7`='No me cabe duda. Pasemos a la acción.' WHERE `ID`=53379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하기 싫으면 죽어라, 이 멍청한 녀석아!', `MaleText_loc4`='投降免死，你这蠢货！', `MaleText_loc5`='不投降就得死，蠢材!', `MaleText_loc7`='¡Ríndete o muere!' WHERE `ID`=53380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번에 한 명씩만 공격하지 말란 말이다, 이 바보들아! 지금 놈을 포위해!', `MaleText_loc4`='别一个一个上，你们这些蠢货！给我一起上！', `MaleText_loc5`='別一個一個上，你們這群呆瓜!包圍他!', `MaleText_loc7`='¡No le ataquéis uno a uno, idiotas! ¡Rodeadlo ahora!' WHERE `ID`=53381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 미소를 짓습니다.', `MaleText_loc4`='%s微笑了起来。', `MaleText_loc5`='%s微笑。', `MaleText_loc7`='%s sonríe.' WHERE `ID`=53385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 농부 같아 보이지 않는군요...', `MaleText_loc4`='你显然不是农夫……', `MaleText_loc5`='你顯然不是個農夫...', `MaleText_loc7`='Está claro que no eres un granjero...' WHERE `ID`=53386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 에일 맥주 한 잔 더!', `MaleText_loc4`='给$n再来一杯啤酒！', `MaleText_loc5`='為了$n再乾一杯!', `MaleText_loc7`='¡Otra jarra de cerveza para $n!' WHERE `ID`=53387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대연회에 잘 오셨습니다. 클라우드폴 대장로님이 뒤쪽에서 당신을 기다리십니다.', `MaleText_loc4`='欢迎参加我们的盛宴。云瀑长老在后面张桌子那儿等着你。', `MaleText_loc5`='歡迎來到筵席場地，高階長者雲落在後桌等你。', `MaleText_loc7`='Te doy la bienvenida al gran banquete. El gran ancestro Otoño Nublo te espera en la mesa del fondo.' WHERE `ID`=53388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 풀려났군요! 마실 것이 필요해요...', `MaleText_loc4`='终于自由了！我得去喝一杯……', `MaleText_loc5`='終於自由了!我得喝一杯...', `MaleText_loc7`='¡Por fin libre! Necesito un trago...', `FemaleText_loc1`='마침내 풀려났군요! 마실 것이 필요해요...', `FemaleText_loc4`='终于自由了！我得去喝一杯……', `FemaleText_loc5`='終於自由了!我得喝一杯...', `FemaleText_loc7`='¡Por fin libre! Necesito un trago...' WHERE `ID`=53390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만 기다리렴, $n.', `FemaleText_loc4`='请稍等，$n。', `FemaleText_loc5`='耽誤一點時間，$n。', `FemaleText_loc7`='Un momento, $n.' WHERE `ID`=53391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 탄산수가 담긴 약병에 으깬 약초 한 줌을 넣고, 혼합물을 열심히 흔들어 섞습니다.', `FemaleText_loc4`='%s将果酒和一把碾碎的草药放入瓶子里，然后用力摇晃。', `FemaleText_loc5`='%s將蘋果汁和一把捏碎的草藥混在一個燒瓶裡，然後用力地搖晃。', `FemaleText_loc7`='%s mezcla la sidra y un puñado de hierbas machacadas en un frasco y lo agita vigorosamente.' WHERE `ID`=53392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 정도면 충분할 거다!', `FemaleText_loc4`='这样应该就行了！', `FemaleText_loc5`='這樣應該行了!', `FemaleText_loc7`='¡Ya está!' WHERE `ID`=53393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 복병이 나무에서 내려옵니다. 조심하세요!', `MaleText_loc4`='魔古伏击者从树上跳下来了。小心！', `MaleText_loc5`='魔古伏擊者從樹上下來了。小心!', `MaleText_loc7`='Unos emboscadores mogu bajan de los árboles. ¡Cuidado!', `FemaleText_loc1`='모구 복병이 나무에서 내려옵니다. 조심하세요!', `FemaleText_loc4`='魔古伏击者从树上跳下来了。小心！', `FemaleText_loc5`='魔古伏擊者從樹上下來了。小心!', `FemaleText_loc7`='Unos emboscadores mogu bajan de los árboles. ¡Cuidado!' WHERE `ID`=53394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구야! 과수원에서 온 녀석이 또 있군...', `MaleText_loc4`='看看我们找到了什么！又一个从果园里跑出来的农夫……', `MaleText_loc5`='看看這是什麼!又是個從果園來的流浪者...', `MaleText_loc7`='¡Mira! Otro rezagado del huerto...' WHERE `ID`=53395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 훈련할 생각이 있다면, 연회장에서 내게 다시 말을 하게.', `MaleText_loc4`='如果你想和我们一起训练，就等晚上开席时来跟我说一声吧。', `MaleText_loc5`='如果你有興趣和我們一起受訓，傍晚之後到筵席桌那裡和我談話。', `MaleText_loc7`='Si te interesa entrenarte con nosotros, habla conmigo esta noche en la mesa del banquete.' WHERE `ID`=53396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금쯤이면 반이 도착했을 겁니다... 야영지 외곽에서 반을 찾아보세요.', `MaleText_loc4`='班应该已经到了……到营地外围去找他吧。', `MaleText_loc5`='班應該已經到了...到營地邊去找他。', `MaleText_loc7`='Ban ya debería haber llegado... Ve a buscarlo al límite del campamento.', `FemaleText_loc1`='지금쯤이면 반이 도착했을 겁니다... 야영지 외곽에서 반을 찾아보세요.', `FemaleText_loc4`='班应该已经到了……到营地外围去找他吧。', `FemaleText_loc5`='班應該已經到了...到營地邊去找他。', `FemaleText_loc7`='Ban ya debería haber llegado... Ve a buscarlo al límite del campamento.' WHERE `ID`=53397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 다크문 축제에 오신 것을 환영합니다.$b$b이 차원문을 이용하면 다크문 축제로 갈 수 있습니다.$b$b하지만 이동하기 전에 궁금한 점이 있으시다면 제가 알려 드리겠습니다.', `MaleText_loc4`='你好，欢迎来到暗月马戏团入口处。$b$b这座传送门能送你去暗月马戏团。$b$b如果你在出发前有什么疑问的话，我也可以帮你解答。', `MaleText_loc5`='您好，$c，歡迎來到暗月馬戲團的籌備區。$b$b這裡的門會把你帶到暗月馬戲團的位置。$b$b但若您在前往之前有任何問題，我可以幫忙回答。', `MaleText_loc7`='Hola y $gbienvenido:bienvenida; a la zona de escala de la Feria de la Luna Negra.$b$bEste portal te llevará a la Feria de la Luna Negra.$b$bPero si tienes alguna pregunta antes de irte, yo puedo respondértela.', `FemaleText_loc1`='안녕하세요! 다크문 축제에 오신 것을 환영해요.$b$b이 차원문을 이용하면 다크문 축제로 갈 수 있답니다.$b$b하지만 이동하기 전에 궁금한 점이 있으시다면 제가 알려 드릴게요.', `FemaleText_loc4`='你好，欢迎来到暗月马戏团入口处。$b$b这座传送门能送你去暗月马戏团。$b$b如果你在出发前有什么疑问的话，我也可以帮你解答。', `FemaleText_loc5`='您好，$c，歡迎來到暗月馬戲團的籌備區。$b$b這裡的門會把你帶到暗月馬戲團的位置。$b$b但若您在前往之前有任何問題，我可以幫忙回答。', `FemaleText_loc7`='Hola y $gbienvenido:bienvenida; a la zona de escala de la Feria de la Luna Negra.$b$bEste portal te llevará a la Feria de la Luna Negra.$b$bPero si tienes alguna pregunta antes de irte, yo puedo respondértela.' WHERE `ID`=53398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제는 온갖 놀라운 구경거리가 가득합니다. 점쟁이와 공연, 낚시 대회와 수많은 게임이 있지요.$b$b우리는 계속해서 다양한 종류의 구경거리를 더 만들어내고 있습니다!$b$b더 알고 싶으신 구경거리가 있으십니까?', `MaleText_loc4`='暗月马戏团里有各种有趣的游乐设施，有占卜师，音乐会，钓鱼大赛以及各种游戏。$b$b而且我们还在不断扩张马戏团，添加各种新的游乐设施！$b$b你要不要了解一下某种游乐设施的具体情况呢？', `MaleText_loc5`='暗月馬戲團裡頭有很多令人驚嘆的東西。我們有個占卜師，一場演唱會、一場釣魚比賽跟許多小遊戲。$b$b我們一直在持續用新花樣來擴張馬戲團的規模!$b$b有任何特別的東西是你想知道的嗎?', `MaleText_loc7`='La Feria de la Luna Negra está llena de todo tipo de atracciones divertidas. Tenemos un clarividente, un concierto, un concurso de pesca y un montón de juegos.$b$bAmpliamos constantemente la feria con múltiples y variadas atracciones.$b$b¿Te gustaría informarte acerca de alguna atracción?', `FemaleText_loc1`='다크문 축제는 온갖 놀라운 구경거리가 가득해요. 점쟁이와 공연, 낚시 대회와 수많은 게임이 있답니다.$b$b우리는 계속해서 다양한 종류의 구경거리를 더 만들어내고 있어요!$b$b더 알고 싶으신 구경거리가 있으신가요?', `FemaleText_loc4`='暗月马戏团里有各种有趣的游乐设施，有占卜师，音乐会，钓鱼大赛以及各种游戏。$b$b而且我们还在不断扩张马戏团，添加各种新的游乐设施！$b$b你要不要了解一下某种游乐设施的具体情况呢？', `FemaleText_loc5`='暗月馬戲團裡頭有很多令人驚嘆的東西。我們有個占卜師，一場演唱會、一場釣魚比賽跟許多小遊戲。$b$b我們一直在持續用新花樣來擴張馬戲團的規模!$b$b有任何特別的東西是你想知道的嗎?', `FemaleText_loc7`='La Feria de la Luna Negra está llena de todo tipo de atracciones divertidas. Tenemos un clarividente, un concierto, un concurso de pesca y un montón de juegos.$b$bAmpliamos constantemente la feria con múltiples y variadas atracciones.$b$b¿Te gustaría informarte acerca de alguna atracción?' WHERE `ID`=53399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통통 전차가 무엇입니까?', `MaleText_loc4`='那些就是坦克吗？', `MaleText_loc5`='這裡有坦克嗎?', `MaleText_loc7`='¿Hay tonques?', `FemaleText_loc1`='통통 전차가 무엇입니까?', `FemaleText_loc4`='那些就是坦克吗？', `FemaleText_loc5`='這裡有坦克嗎?', `FemaleText_loc7`='¿Hay tonques?' WHERE `ID`=53400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 전차, 또는 통통 전차라는 멋들어진 이름을 가진 이 전차는, 다크문 축제에서 오래전부터 인기 만점이었습니다.$b$b통통 전차 전투를 위한 전용 경기장이 두 개 있습니다.$b$b한 경기장에서는 적 통통 전차를 피해서 목표물을 시간 안에 파괴해야 합니다. 게임 동전 하나만 있으면 즐기실 수 있습니다!$b$b또 다른 경기장에서는 당신의 통통 전차나 꼬마비행선을 써서 친구와 전투를 벌일 수 있습니다.', `MaleText_loc4`='我们给这些迷你坦克起了一个很拉风的名字，叫蒸汽坦克。它们可是我记忆当中，最受欢迎的马戏团游戏了。$b$b我们有两座坦克大战专用的战场。$b$b一座为限时挑战战场，你需要在里面快速摧毁目标，并躲避敌对坦克的攻击。只要一个代币，你就可以参加游戏了！$b$b另一座战场则是对战专用的场地，你可以驾驶自己的坦克或迷你飞艇来和朋友对战。', `MaleText_loc5`='小型坦克，就我記憶所及，一直都是馬戲團裡面很搶手的遊戲。$b$b我們有兩個競技場來讓坦克進行戰鬥。$b$b一個競技場要你在有限時間內摧毀目標，並避免被敵方坦克擊破。你只需要一個代幣就可以玩了$b$b在另一個競技場裡面，你可以使用自己的坦克或迷你飛艇跟朋友對戰。', `MaleText_loc7`='Los tanques en miniatura o tonques, que es el ingenioso nombre que les hemos puesto, han sido los favoritos de la feria desde que tengo memoria.$b$bTenemos dos arenas dedicadas a las batallas de tonques.$b$bLa primera es una arena contrarreloj que consiste en destruir los objetivos y evitar a los tonques enemigos. ¡Solo necesitas una ficha de juego!$b$bLa segunda es un lugar en el que puedes usar tus propios tonques o minizepelines para luchar con tus amigos.', `FemaleText_loc1`='꼬마 전차, 또는 통통 전차라는 멋들어진 이름을 가진 이 전차는, 다크문 축제에서 오래전부터 인기 만점이었답니다.$b$b통통 전차 전투를 위한 전용 경기장이 두 개 있어요.$b$b한 경기장에서는 적 통통 전차를 피해서 목표물을 시간 안에 파괴해야 해요. 게임 동전 하나만 있으면 즐기실 수 있죠!$b$b또 다른 경기장에서는 당신의 통통 전차나 꼬마비행선을 써서 친구와 전투를 벌일 수 있어요.', `FemaleText_loc4`='我们给这些迷你坦克起了一个很拉风的名字，叫蒸汽坦克。它们可是我记忆当中，最受欢迎的马戏团游戏了。$b$b我们有两座坦克大战专用的战场。$b$b一座为限时挑战战场，你需要在里面快速摧毁目标，并躲避敌对坦克的攻击。只要一个代币，你就可以参加游戏了！$b$b另一座战场则是对战专用的场地，你可以驾驶自己的坦克或迷你飞艇来和朋友对战。', `FemaleText_loc5`='小型坦克，就我記憶所及，一直都是馬戲團裡面很搶手的遊戲。$b$b我們有兩個競技場來讓坦克進行戰鬥。$b$b一個競技場要你在有限時間內摧毀目標，並避免被敵方坦克擊破。你只需要一個代幣就可以玩了$b$b在另一個競技場裡面，你可以使用自己的坦克或迷你飛艇跟朋友對戰。', `FemaleText_loc7`='Los tanques de miniatura o tonques, que es el ingenioso nombre que les hemos puesto, han sido los favoritos de la feria desde que tengo memoria.$b$bTenemos dos arenas dedicadas a las batallas de tonques.$b$bLa primera es una arena contrarreloj cuyo objetivo es destruir los objetivos y evitar a los tonques enemigos. ¡Solo necesitas una ficha de juego!$b$bLa segunda es un lugar en el que puedes usar tus propios tonques o minizepelines para luchar con tus amigos.' WHERE `ID`=53401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최신형 블라스텐하이머 5000 초특급 대포는 탑승자 한 명을 발사하는 장치입니다.$b$b거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로서, 항공역학적인데다가 화끈한 성능까지 갖춰 온 세상에 명성이 자자하지요!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 맥시마 블라스텐하이머를 찾아보십시오.', `MaleText_loc4`='雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置。$b$b它能以接近飞龙的速度将搭乘者发射出去。它的发明者是雷管家族，这个家族在航空及爆破领域享有盛名。这架超级大炮已经成为了家族的荣耀！$B$B如果你想像鸟儿一样在空中翱翔，就去找玛克希玛·雷管吧。', `MaleText_loc5`='衝擊者5000型超級大砲是一種最先進的單人拋射裝置。$B$B能以近乎龍的飛行速度射出彈頭，這門大砲是布萊頓海默家族的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想要像隻鳥一樣在空中翱翔，就去找瑪克希瑪·布萊頓海默。', `MaleText_loc7`='El Ultracañón Pimpampum 5000 es un artefacto único para el lanzamiento de personas.$b$bProyecta su carga a una velocidad cercana a la del vuelo de un dragón. Este cañón es el orgullo de la familia Pimpampum, conocida en todo el mundo por sus derroches en el campo de la aeronáutica.$B$BSi quieres que te lancen por los cielos y volar como un pájaro, busca a Maxima Pimpampum.', `FemaleText_loc1`='최신형 블라스텐하이머 5000 초특급 대포는 탑승자 한 명을 발사하는 장치예요. 거의 용이 날아가는 속도로 탑승자를 발사하는 이 대포는 블라스텐하이머가의 자랑이자 기쁨으로서, 항공역학적인데다가 화끈한 성능까지 갖춰 온 세상에 명성이 자자하다고요!$B$B새처럼 자유롭게 하늘로 날아오르고 싶다면 맥시마 블라스텐하이머를 찾아보세요.', `FemaleText_loc4`='雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置。$b$b它能以接近飞龙的速度将搭乘者发射出去。它的发明者是雷管家族，这个家族在航空及爆破领域享有盛名。这架超级大炮已经成为了家族的荣耀！$B$B如果你想像鸟儿一样在空中翱翔，就去找玛克希玛·雷管吧。', `FemaleText_loc5`='衝擊者5000型超級大砲是一種最先進的單人拋射裝置。$B$B能以近乎龍的飛行速度射出彈頭，這門大砲是布萊頓海默家族的驕傲與喜悅，他們的航空與彈藥技術是出了名的!$B$B如果你想要像隻鳥一樣在空中翱翔，就去找瑪克希瑪·布萊頓海默。', `FemaleText_loc7`='El Ultracañón Pimpampum 5000 es un artefacto único para el lanzamiento de personas.$b$bProyecta su carga a una velocidad cercana a la del vuelo de un dragón. Este cañón es el orgullo de la familia Pimpampum, conocida en todo el mundo por sus derroches en el campo de la aeronáutica.$B$BSi quieres que te lancen por los cielos y volar como un pájaro, busca a Maxima Pimpampum.' WHERE `ID`=53402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀 때려잡기는 뭡니까?', `MaleText_loc4`='打豺狼人？', `MaleText_loc5`='痛扁豺狼人?', `MaleText_loc7`='¿Golpear al gnoll?', `FemaleText_loc1`='놀 때려잡기는 뭔가요?', `FemaleText_loc4`='打豺狼人？', `FemaleText_loc5`='痛扁豺狼人?', `FemaleText_loc7`='¿Golpear al gnoll?' WHERE `ID`=53403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀 때려잡기는... 말 그대로 놀을 두들겨 패는 흥미진진한 게임입니다.$b$b새로 생긴 게임인데, 우리 사이에서도 유명합니다... 아, 세이지는 그렇게 좋아하지는 않습니다.', `MaleText_loc4`='打豺狼人是一种打……豺狼人的有趣游戏。$b$b这是一个新的游乐设施，而且颇受我们大家的欢迎……好吧，其实塞格不太喜欢这玩意儿。', `MaleText_loc5`='痛扁豺狼人是一個充滿樂趣的遊戲，讓你痛扁...豺狼人。$b$b這是個新玩意，我們很多人都很愛玩。好吧，其實賽吉並不是很喜歡這個遊戲。', `MaleText_loc7`='Golpear al gnoll es un divertido juego que consiste en golpear... gnolls.$b$bEs una atracción nueva y bastante popular entre nosotros... Bueno, a Sayge no le hace tanta gracia.', `FemaleText_loc1`='놀 때려잡기는... 말 그대로 놀을 두들겨 패는 흥미진진한 게임이죠.$b$b새로 생긴 게임인데, 우리 사이에서도 유명해요... 아, 세이지는 그렇게 좋아하지는 않지만요.', `FemaleText_loc4`='打豺狼人是一种打……豺狼人的有趣游戏。$b$b这是一个新的游乐设施，而且颇受我们大家的欢迎……好吧，其实塞格不太喜欢这玩意儿。', `FemaleText_loc5`='痛扁豺狼人是一個充滿樂趣的遊戲，讓你痛扁...豺狼人。$b$b這是個新玩意，我們很多人都很愛玩。好吧，其實賽吉並不是很喜歡這個遊戲。', `FemaleText_loc7`='Golpear al gnoll es un divertido juego que consiste en golpear... gnolls.$b$bEs una atracción nueva y bastante popular entre nosotros... Bueno, a Sayge no le hace tanta gracia.' WHERE `ID`=53404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기다! 어서 가라!', `MaleText_loc4`='那边！快！快！！！', `MaleText_loc5`='那邊的，動作快!', `MaleText_loc7`='¡Allí! ¡Vamos! ¡VAMOS!' WHERE `ID`=53405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문이 닫힌다! 서둘러라!', `MaleText_loc4`='传送门要关闭了！快！', `MaleText_loc5`='傳送門要關了!快!', `MaleText_loc7`='¡El portal se cierra! ¡Rápido!' WHERE `ID`=53406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장교: 적진을 돌파한 것 같습니다, 장군님.', `MaleText_loc4`='军官：看来我们已经突破了敌人的防线，将军。', `MaleText_loc5`='軍官:看來我們成功穿越敵方防線了，將軍。', `MaleText_loc7`='Oficial: Parece que hemos conseguido atravesar las líneas enemigas, General.' WHERE `ID`=53407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장교: 사라진 수송선의 흔적은 아직 보이지 않습니다.', `MaleText_loc4`='军官：仍没发现失踪运输机的踪迹。', `MaleText_loc5`='軍官:還是沒有那位失蹤乘客的蹤影。', `MaleText_loc7`='Oficial: Aún no hay señales del transporte perdido.' WHERE `ID`=53408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림: 바다 밑바닥을 샅샅이 수색하는 한이 있더라도, 수송선을 찾기 전에는 돌아갈 수 없다!', `MaleText_loc4`='纳兹戈林：我们一定要找到它，否则绝不返航——哪怕是要把大海翻个底朝天！', `MaleText_loc5`='納茲格寧姆:在確認它的命運之前我們絕不回頭。就算我們得為此尋遍整個海底!', `MaleText_loc7`='Nazgrim: No regresaremos hasta que descubramos qué ha sido de él, ¡aunque tengamos que registrar el fondo del mar!' WHERE `ID`=53409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림: ... 그리고 내가 바다를 얼마나 싫어하는지 다들 알고 있겠지...', `MaleText_loc4`='纳兹戈林：……你知道我对那个计划的看法……', `MaleText_loc5`='納茲格寧姆:...你知道我對那個主意有什麼看法...', `MaleText_loc7`='Nazgrim: ... Y ya sabéis lo que opino sobre eso...' WHERE `ID`=53410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린: 육지다!', `MaleText_loc4`='地精：陆地！', `MaleText_loc5`='哥布林:看到陸地了!', `MaleText_loc7`='Goblin: ¡Tierra a la vista!' WHERE `ID`=53411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림: 육지라고? 여기에? 말도 안 돼!', `MaleText_loc4`='纳兹戈林：陆地？在这里？那不可能！', `MaleText_loc5`='納茲格寧姆:陸地?這裡?不可能!', `MaleText_loc7`='Nazgrim: ¿Tierra? ¿Aquí? ¡Imposible!' WHERE `ID`=53412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 이렇게 반가울 수가. 관리인 일은 굉장히 배고픈 작업이거든.', `MaleText_loc4`='$n，你绝对想象不出我有多高兴见到你。监控这活儿消耗可是很大的。', `MaleText_loc5`='$n，你想不出我有多高興看見你。監督是件讓人肚子餓的工作。', `MaleText_loc7`='$n, no tienes idea de lo que me alegro de verte. Supervisar me da mucha hambre.' WHERE `ID`=53413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제에 오시는 모든 분들이 게임을 즐기면 좋겠습니다.$b$b고리 던지기는 움직이는 거북이 등 위에 고리를 올려놓기만 하면 되는 간단한 게임이지요.$b$b제가 가장 좋아하는 게임 중 하나이기도 합니다.', `MaleText_loc4`='我们希望各个年龄层的游客都能享受到游戏乐趣。$b$b套圈圈是一个简单的游戏，你只要设法把投环扔到一只不断移动的海龟背上就可以了。$b$b这也是我最喜欢的游戏之一。', `MaleText_loc5`='我們想要確保來看馬戲團的觀眾，不管是任何年齡層，都會喜愛這些遊戲。$b$b丟圈圈是一個簡單的遊戲，你只要試著把圈圈丟到烏龜的背上就可以了。$b$b這是我最愛的遊戲之一。', `MaleText_loc7`='Nos gusta asegurarnos de que los visitantes de la feria de todas las edades puedan disfrutar de los juegos.$b$bEl lanzamiento de anillos es un juego sencillo donde tienes que intentar lanzar un anillo al lomo de una tortuga en movimiento.$b$bEs uno de mis juegos favoritos.', `FemaleText_loc1`='다크문 축제에 오시는 모든 분들이 게임을 즐기면 좋겠어요.$b$b고리 던지기는 움직이는 거북이 등 위에 고리를 올려놓기만 하면 되는 간단한 게임이랍니다.$b$b제가 가장 좋아하는 게임 중 하나이기도 하고요.', `FemaleText_loc4`='我们希望各个年龄层的游客都能享受到游戏乐趣。$b$b套圈圈是一个简单的游戏，你只要设法把投环扔到一只不断移动的海龟背上就可以了。$b$b这也是我最喜欢的游戏之一。', `FemaleText_loc5`='我們想要確保來看馬戲團的觀眾，不管是任何年齡層，都會喜愛這些遊戲。$b$b丟圈圈是一個簡單的遊戲，你只要試著把圈圈丟到烏龜的背上就可以了。$b$b這是我最愛的遊戲之一。', `FemaleText_loc7`='Nos gusta asegurarnos de que los visitantes de la feria de todas las edades puedan disfrutar de los juegos.$b$bEl lanzamiento de anillos es un juego sencillo donde tienes que intentar lanzar un anillo al lomo de una tortuga en movimiento.$b$bEs uno de mis juegos favoritos.' WHERE `ID`=53414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고리 던지기는 어떤 게임입니까?', `MaleText_loc4`='套圈圈？', `MaleText_loc5`='丟圈圈?', `MaleText_loc7`='¿Lanzamiento de anillos?', `FemaleText_loc1`='고리 던지기는 어떤 게임인가요?', `FemaleText_loc4`='套圈圈？', `FemaleText_loc5`='丟圈圈?', `FemaleText_loc7`='¿Lanzamiento de anillos?' WHERE `ID`=53415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린링이 사격 연습장을 운영하고 있습니다.$b$b그곳에는 과녁이 달랑 세 개만 있고, 빨리 사격할수록 높은 점수를 얻을 수 있습니다.$b$b개인적으로 가장 좋아하는 게임 중 하나입니다.', `MaleText_loc4`='瑞林开设了一家射击场。$b$b那里只有三个射击目标，你动作越快，成绩就越好。$b$b就个人意见来说，这是我最喜欢的游戏之一。', `MaleText_loc5`='瑞林負責經營打靶場。$b$b那裡只有三個打靶的目標，命中的速度越快、分數越高。$b$b這是我最喜歡的遊戲。', `MaleText_loc7`='Rinling lleva la galería de tiro.$b$bSolo hay tres objetivos y cuanto más rápido dispares, mejor.$b$bPersonalmente, es uno de mis juegos favoritos.', `FemaleText_loc1`='린링이 사격 연습장을 운영하고 있어요.$b$b그곳에는 과녁이 달랑 세 개만 있고, 빨리 사격할수록 높은 점수를 얻을 수 있답니다.$b$b개인적으로도 가장 좋아하는 게임 중 하나예요.', `FemaleText_loc4`='瑞林开设了一家射击场。$b$b那里只有三个射击目标，你动作越快，成绩就越好。$b$b就个人意见来说，这是我最喜欢的游戏之一。', `FemaleText_loc5`='瑞林負責經營打靶場。$b$b那裡只有三個打靶的目標，命中的速度越快、分數越高。$b$b這是我最喜歡的遊戲。', `FemaleText_loc7`='Rinling lleva la galería de tiro.$b$bSolo hay tres objetivos y cuanto más rápido dispares, mejor.$b$bPersonalmente, es uno de mis juegos favoritos.' WHERE `ID`=53416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격 연습장은 무엇입니까?', `MaleText_loc4`='射击场？', `MaleText_loc5`='打靶場?', `MaleText_loc7`='¿Galería de tiro?', `FemaleText_loc1`='사격 연습장은 무엇인가요?', `FemaleText_loc4`='射击场？', `FemaleText_loc5`='打靶場?', `FemaleText_loc7`='¿Galería de tiro?' WHERE `ID`=53417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세이지에게 들러서 점괘를 들어보는 것을 강력히 추천합니다.$b$b네, 네... 세이지는 놀 맞습니다. 하지만 당신의 미래를 예견할 수 있는 아주 특별한 놀입니다!', `MaleText_loc4`='我强烈推荐你到塞格那里去算个命。$b$b我知道，我知道……他是个豺狼人。但他是个非常特别的豺狼人，他能解读你的命运！', `MaleText_loc5`='我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個豺狼人。不過他是一個非常特別的豺狼人，擁有占卜你未來的能力!', `MaleText_loc7`='Te recomiendo encarecidamente que visites a Sayge para que te lea tu fortuna.$b$bLo sé, lo sé... es un gnoll. ¡Pero es un gnoll muy especial con el poder de la adivinación!', `FemaleText_loc1`='세이지에게 들러서 점괘를 들어보는 것을 강력히 추천해요.$b$b네, 네... 세이지는 놀 맞아요. 하지만 당신의 미래를 예견할 수 있는 아주 특별한 놀이죠!', `FemaleText_loc4`='我强烈推荐你到塞格那里去算个命。$b$b我知道，我知道……他是个豺狼人。但他是个非常特别的豺狼人，他能解读你的命运！', `FemaleText_loc5`='我極度推薦你去拜訪賽吉得到你的未來預言。我知道，我知道...他是個豺狼人。不過他是一個非常特別的豺狼人，擁有占卜你未來的能力!', `FemaleText_loc7`='Te recomiendo encarecidamente que visites a Sayge para que te lea tu fortuna.$b$bLo sé, lo sé... es un gnoll. ¡Pero es un gnoll muy especial con el poder de la adivinación!' WHERE `ID`=53418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='점술사도 있나봅니다?', `MaleText_loc4`='占卜师？', `MaleText_loc5`='占卜師?', `MaleText_loc7`='¿Clarividente?', `FemaleText_loc1`='점술사도 있나보군요?', `FemaleText_loc4`='占卜师？', `FemaleText_loc5`='占卜師?', `FemaleText_loc7`='¿Clarividente?' WHERE `ID`=53419;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 아들이 널 보냈니? 요리는 모두들 맛볼 만큼 충분하단다. 자, 마음껏 가져가렴.', `FemaleText_loc4`='是我儿子让你来的吗？我炖了很多菜，足够分的。请自己拿吧。', `FemaleText_loc5`='我的孩子派你來的嗎?燉菜還有很多。請自便、請自便。', `FemaleText_loc7`='¿Te ha enviado mi hijo? Hay estofado de sobra para todos. Sírvete lo que quieras.' WHERE `ID`=53420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까? 다크문 축제에 오신 것을 환영합니다.$b$b다크문 축제에는 즐길 거리가 너무 많아 처음 오시는 분은 뭘 해야 할지 몰라 망설이는 경우가 많습니다. 바로 그 점이 제가 이곳에 있는 이유입니다.$b$b궁금한 게 있으십니까?', `MaleText_loc4`='您好，$c，欢迎来到暗月马戏团。$b$b在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。所以我才会在这里帮忙。$b$b您有什么问题吗？', `MaleText_loc5`='哈囉，$c，歡迎來到暗月馬戲團。$b$b這裡有很多東西可以玩，對於第一次來的參觀者可能會覺得不知從何下手。我就是因為這個原因來幫忙的。$b$b你有任何疑問嗎?', `MaleText_loc7`='Hola, $c, y $gbienvenido:bienvenida; a la Feria de la Luna Negra.$b$bHay tanto que hacer aquí que puede resultar un tanto abrumador para aquellos que nos visitan por primera vez. Por eso estoy aquí para ayudarte.$b$b¿Tienes alguna pregunta?', `FemaleText_loc1`='안녕하세요? 다크문 축제에 오신 것을 환영해요.$b$b다크문 축제에는 즐길 거리가 너무 많아 처음 오시는 분은 뭘 해야 할지 몰라 망설이는 경우가 많답니다. 바로 그 점이 제가 이곳에 있는 이유죠.$b$b궁금한 게 있으세요?', `FemaleText_loc4`='您好，$c，欢迎来到暗月马戏团。$b$b在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。所以我才会在这里帮忙。$b$b您有什么问题吗？', `FemaleText_loc5`='哈囉，$c，歡迎來到暗月馬戲團。$b$b這裡有很多東西可以玩，對於第一次來的參觀者可能會覺得不知從何下手。我就是因為這個原因來幫忙的。$b$b你有任何疑問嗎?', `FemaleText_loc7`='Hola, $c, y $gbienvenido:bienvenida; a la Feria de la Luna Negra.$b$bHay tanto que hacer aquí que puede resultar un tanto abrumador para aquellos que nos visitan por primera vez. Por eso estoy aquí para ayudarte.$b$b¿Tienes alguna pregunta?' WHERE `ID`=53421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 갑자기 나타났습니다! 어쩔 수 없었습니다...', `MaleText_loc4`='他们不知道从哪儿冒了出来！我们什么也做不了……', `MaleText_loc5`='他們就像憑空出現!我們什麼辦法也沒有...', `MaleText_loc7`='¡Salieron de la nada! No pudimos reaccionar...' WHERE `ID`=53422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허약하고 쓸모없는 생명체 같으니!', `MaleText_loc4`='太脆弱了。不堪一击！', `MaleText_loc5`='真脆弱的生物。沒用!', `MaleText_loc7`='Qué criaturas tan frágiles y ruines.' WHERE `ID`=53423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 상황에서 신병이 실력을 발휘할 거라고는 생각하지 않습니다만, 그래도 최선을 다하십시오.', `FemaleText_loc4`='我并不指望一个新兵在这种情况下还能沉着应对，只要尽力而为就行了。', `FemaleText_loc5`='這種情況下，我不期待一個新兵有什麼表現。盡力嘗試吧。', `FemaleText_loc7`='No espero que un recluta tenga éxito en esta situación, pero hazlo lo mejor que puedas.' WHERE `ID`=53424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사람을 구할 수 있습니다. 하지만 서둘러야 합니다.', `FemaleText_loc4`='我们可以救这个人，但必须得抓紧时间。', `FemaleText_loc5`='我們能救他，但動作一定要快。', `FemaleText_loc7`='Podemos salvar a este, pero debemos darnos prisa.' WHERE `ID`=53425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선원이 질식하려 하면, 숨을 불어넣어서 일시적으로 상태를 안정시키십시오.', `FemaleText_loc4`='如果船员发生了窒息，我们可以输送氧气以稳定他们渐弱的生命体征。', `FemaleText_loc5`='如果船員被嗆得咳嗽，我們可以輸送空氣來暫時穩定他們的生命跡象。', `FemaleText_loc7`='Si el tripulante se asfixia, podemos insuflarle aire temporalmente para estabilizar sus constantes vitales.' WHERE `ID`=53426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='환자의 가슴을 압박해서 서서히 상태를 호전시키십시오.', `FemaleText_loc4`='按压病人的胸膛以增强他们的生命体征。', `FemaleText_loc5`='壓住傷患的胸部來穩定他們的生命跡象。', `FemaleText_loc7`='Comprime el tórax del paciente para mejorar sus constantes de forma regular.' WHERE `ID`=53427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전기 충격으로 환자의 상태를 크게 호전시킬 수 있습니다. 하지만 자주 사용할 수는 없지요.', `FemaleText_loc4`='电击能够大大加强病人的生命体征。但这个办法不能多用。', `FemaleText_loc5`='電擊能用來大幅增強病患的生命跡象。但是，我們不能用得太頻繁。', `FemaleText_loc7`='Podemos utilizar Choque eléctrico para aumentar las constantes vitales del paciente considerablemente, pero solo ocasionalmente.' WHERE `ID`=53428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 선원을 살려 내셨군요! 솔직히 말하면, 방금 전까지도 실패할 거라고 생각했습니다.', `FemaleText_loc4`='你真的救活了一个人！我必须承认，我原本对你还是有所怀疑的。', `FemaleText_loc5`='你救活了一個!老實說之前我不太相信你的能力。', `FemaleText_loc7`='¡Has salvado a uno! Admito que tenía mis dudas.' WHERE `ID`=53429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼... 선원이 목숨을 잃었군요. 절망하지 마십시오, $n 님. 이미 너무 늦은 상태였습니다.', `FemaleText_loc4`='噢，不。我们失去了一位病人。不过别难过，$n。他们已经坚持得够久了。', `FemaleText_loc5`='喔不，一名傷患過世了。不要絕望，$n。他們原本就已經難以救治了。', `FemaleText_loc7`='Oh, no... Hemos perdido a un paciente. No desesperes, $n. Ya no se podía hacer nada por él.' WHERE `ID`=53430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선원들을 모두 구출할 수는 없습니다, $n 님. 아직 치료할 수 있는 다른 선원들을 찾아봅시다.', `FemaleText_loc4`='我们不可能救下所有人，$n。我们还是去关注一下那些还有救的病人吧。', `FemaleText_loc5`='我們沒辦法救每一個人，$n。我們得去找可以救得回來的人。', `FemaleText_loc7`='No podemos salvarlos a todos, $n. Ayudemos a alguien que todavía pueda responder al tratamiento.' WHERE `ID`=53431;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님! 들리세요? 정신을 딴 데 팔고 있는 건 아닌가 해서 확인해 봤습니다.', `FemaleText_loc4`='$n！你听到我的话了吗？噢，我只是确定一下你有没有专心听讲而已。', `FemaleText_loc5`='$n!你能聽到我嗎?只是看看你有沒有專心。', `FemaleText_loc7`='¡$n! ¿ME OYES? Solo quería probar si me estabas prestando atención.' WHERE `ID`=53432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 치유 능력 자체에는 그다지 소질이 없지만, 의무병의 일은 성격에 맞는 것 같습니다. 물약이나 붕대, 기타 응급처치술은 쓸모가 많답니다!', `FemaleText_loc4`='我在治疗法术上一向没有天分，可却在医术上找到了目标。药水、绷带和其他的诊疗手段也能治病救人！', `FemaleText_loc5`='我從來都沒有治療的天賦能力，但我在急救這方面找到我的歸宿。藥水、繃帶還有檢傷分類也能派上用場!', `FemaleText_loc7`='Nunca disfruté de talento alguno en los poderes de la sanación, pero acabé encontrando mi vocación en la disciplina médica. Las pociones, las vendas y demás ramas de la medicina pueden obrar milagros.' WHERE `ID`=53433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 요원들도 무사했으면 좋겠습니다. 그렇지 않다면, 제가 할 일이 많아지니까요.', `FemaleText_loc4`='但愿其他密探也能挺过来。否则的话，我的负担就更重了。', `FemaleText_loc5`='我真的希望其他密探也都平安。否則我就有更多工作得做了。', `FemaleText_loc7`='Espero que los demás agentes estén bien. Si no, tendremos más trabajo pendiente.' WHERE `ID`=53434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 생존자들을 도와주는 것도 좋지만, 원래 임무를 잊어서는 안 됩니다.', `FemaleText_loc4`='能帮助幸存者当然是好事，可我们也不能忘记自己原本的任务。', `FemaleText_loc5`='在這裡幫助生還者是件好事，但我們也絕不能忘記最初的任務。', `FemaleText_loc7`='Está bien ayudar a estos supervivientes, pero no debemos olvidar nuestra misión principal.' WHERE `ID`=53435;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 아직 이곳을 발견하지 못했기를 빕시다. 아마 놈들도 이 땅을 독차지하려 할 테니까요.', `FemaleText_loc4`='但愿部落还没有发现这个地方。否则他们一定会设法占领这里的。', `FemaleText_loc5`='希望部落還沒發現這個地方。他們會想將這裡佔為己有。', `FemaleText_loc7`='Esperemos que la Horda aún no haya encontrado este lugar. Querrán hacerse con el control.' WHERE `ID`=53436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='착륙 과정에서 비행선을 잃은 건 참 아쉬운 일입니다. 구출 임무가 조금... 어려워지겠습니다.', `FemaleText_loc4`='虽然我们活了下来，可遗憾的是，我们的飞机都坠毁了。这会让我们的任务变得更加……有挑战性。', `FemaleText_loc5`='飛機墜毀對我們來說相當麻煩。這會讓我們的撤退任務變得稍微...有挑戰性。', `FemaleText_loc7`='Es una pena que perdiéramos los aviones al llegar. Nuestra misión de extracción va a ser algo más... desafiante.' WHERE `ID`=53437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 멈추지 말게. 훈련을 멈추지 말게. 그 누구도 완벽하지는 않네.', `MaleText_loc4`='战斗不息，修行不止。你永远也无法达到完美境界。', `MaleText_loc5`='戰鬥不倦，修行不懈，你永遠都不夠完美。', `MaleText_loc7`='Nunca dejes de luchar. Nunca dejes de entrenarte. La perfección es inalcanzable.' WHERE `ID`=53438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네보다 앞서 지나간 이들을 잊지 말게. 자네가 어디서 왔는지 잊지 말게.', `MaleText_loc4`='做人要向前看，也不能忘本。', `MaleText_loc5`='毋忘前人，毋忘思源。', `MaleText_loc7`='Nunca olvides a los que recorrieron esta senda antes que tú. Nunca olvides de dónde procedes.' WHERE `ID`=53439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신을 남들보다 앞에 두지 말게. 이 땅에는 많은 이들이 함께 살고 있음을 잊지 않아야 하네.', `MaleText_loc4`='永远不要自以为高人一等。记住，这片土地是大家共同的家园。', `MaleText_loc5`='切忌自我中心，毋忘這片土地屬於眾人。', `MaleText_loc7`='Nunca te pongas por encima de otras personas. Nunca olvides que esta tierra nos pertenece a todos.' WHERE `ID`=53440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 사랑하는 이를 잊지 말게. 자네가 무엇을 위해 싸우고 있는지 잊지 말아야 하네.', `MaleText_loc4`='不要忘记你所爱的人，不要忘记你为之战斗的理由。', `MaleText_loc5`='毋忘你所愛的事物，毋忘你戰鬥的初衷。', `MaleText_loc7`='Nunca olvides a tus seres queridos. Nunca olvides por qué luchas.' WHERE `ID`=53441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르가스 블레이드피스트가 쓰러졌다! 호드를 위하여!', `MaleText_loc4`='卡加斯·刃拳倒下了！为了部落！', `MaleText_loc5`='卡加斯·刃拳已經倒下了!為了部落!', `MaleText_loc7`='¡Kargath Garrafilada ha caído! ¡Por la Horda!' WHERE `ID`=53442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카자레즈는 나처럼 운이 좋지 못했네, $n. 그는 이제 영혼들과 함께 쉬고 있을 거야.', `MaleText_loc4`='卡萨雷兹没有我这么走运，$n。他已经和幽灵为伴了。', `MaleText_loc5`='卡沙瑞斯沒我那麼好運，$n。他現在已經與靈魂一起安息了。', `MaleText_loc7`='Caza''rez no tuvo tanta suerte como yo, $n. Ahora descansa con los espíritus.' WHERE `ID`=53443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 머리가 빙빙 도는군. 자, 난파된 비행선으로 안내하게.', `MaleText_loc4`='嗷……我脑袋还晕忽忽的，朋友。我看看飞艇残骸。', `MaleText_loc5`='噁...我的頭還在暈，朋友。來，帶我去看看殘骸。', `MaleText_loc7`='Ah... La cabeza todavía me da vueltas. Vamos, muéstrame los restos.' WHERE `ID`=53444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽었다고? 안 돼...', `MaleText_loc4`='我的人……都死了？不……', `MaleText_loc5`='我的人呢?全死了?不...', `MaleText_loc7`='Mis hombres... ¿Han muerto todos? No...' WHERE `ID`=53445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝지만 구니는 견뎌내지 못했습니다, $n 님.', `MaleText_loc4`='我担心冈尼没能撑下来，$n。', `MaleText_loc5`='很遺憾甘尼沒有活下來，$n。', `MaleText_loc7`='Me temo que Pistolete no lo consiguió, $n.' WHERE `ID`=53446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카르가스 블레이드피스트가 쓰러졌다! 얼라이언스여, 영원하라!', `MaleText_loc4`='卡加斯·刃拳被杀了！联盟万岁！', `MaleText_loc5`='卡加斯·刃拳已經被殺了!聯盟萬歲!', `MaleText_loc7`='¡Kargath Garrafilada ha sido derrotado! ¡Larga vida a la Alianza!' WHERE `ID`=53447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 거기 $c님! 느릿느릿하게 움직이는 거북이 등에 고리를 던져 놓을 수 있으시겠습니까?', `MaleText_loc4`='嘿，嘿$c！你有信心把投环扔到一只慢吞吞的海龟背上吗？', `MaleText_loc5`='嘿，嘿，$c!你有本事把圈圈丟到慢吞吞的烏龜身上?', `MaleText_loc7`='¡Eh, oye, $c! ¿Crees que puedes acertarle a una tortuga en movimiento con un anillo?', `FemaleText_loc1`='자, 거기 $c님! 느릿느릿하게 움직이는 거북이 등에 고리를 던져 놓을 수 있으시겠어요?', `FemaleText_loc4`='嘿，嘿$c！你有信心把投环扔到一只慢吞吞的海龟背上吗？', `FemaleText_loc5`='嘿，嘿，$c!你有本事把圈圈丟到慢吞吞的烏龜身上?', `FemaleText_loc7`='¡Eh, oye, $c! ¿Crees que puedes acertarle a una tortuga en movimiento con un anillo?' WHERE `ID`=53448;
