UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단순한 분들을 위한 단순한 게임입니다. 한번 해보시겠습니까?', `MaleText_loc4`='很简单的游戏，傻瓜都能玩。你有信心玩好吗？', `MaleText_loc5`='單純的遊戲，最適合單純的人玩。你覺得自己能玩得好嗎?', `MaleText_loc7`='Un juego sencillo para gente sencilla. ¿Crees que puedes con él?', `FemaleText_loc1`='단순한 분들을 위한 단순한 게임이랍니다. 한번 해보시겠어요?', `FemaleText_loc4`='很简单的游戏，傻瓜都能玩。你有信心玩好吗？', `FemaleText_loc5`='單純的遊戲，最適合單純的人玩。你覺得自己能玩得好嗎?', `FemaleText_loc7`='Un juego sencillo para gente sencilla. ¿Crees que puedes con él?' WHERE `ID`=53450;
