UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 차리십시오! 당신은 살아남았습니다! 나즈그림 장군님께서 근처의 마을에 보고하라고 명령하셨습니다.', `MaleText_loc4`='振作起来！你还活着！纳兹戈林命令我们去附近村子报到。', `MaleText_loc5`='快點振作起來!你還活著!納茲格寧姆命令我們到附近的村子去報到。', `MaleText_loc7`='¡Recupera la compostura! ¡Estás viva! Nazgrim nos ha ordenado que vayamos a la aldea más cercana.', `FemaleText_loc1`='정신 차리세요! 당신은 살아남았어요! 나즈그림 장군님께서 근처의 마을에 보고하라고 명령하셨어요.', `FemaleText_loc4`='振作起来！你还活着！纳兹戈林命令我们去附近村子报到。', `FemaleText_loc5`='快點振作起來!你還活著!納茲格寧姆命令我們到附近的村子去報到。', `FemaleText_loc7`='¡Recupera la compostura! ¡Estás viva! Nazgrim nos ha ordenado que vayamos a la aldea más cercana.' WHERE `ID`=53474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요. 마을까지는 혼자 갈게요. 무사하시길 바랄게요...', `FemaleText_loc4`='谢谢你。我能自己去村子里。注意安全……', `FemaleText_loc5`='謝謝你。我會啟程前往村子。保重...', `FemaleText_loc7`='Gracias, iré a la aldea. Ten cuidado.' WHERE `ID`=53475;
