UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 여기서 꺼내줘, $n! 이 여자가 날 죽이려고 해!', `MaleText_loc4`='救我下来，$n！这女人要杀了我！', `MaleText_loc5`='把我救出這裡，$n!這女的想要殺了我!', `MaleText_loc7`='¡Sácame de aquí, $n! ¡Esta belleza quiere matarme!' WHERE `ID`=53484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소란 떨지 말고 칼을 사용하십시오! 나즈그림 장군님께서 근처 마을로 즉시 보고하라고 하셨습니다.', `MaleText_loc4`='别浪费时间了，打起精神来！纳兹戈林要你立刻去村里报到。', `MaleText_loc5`='不要胡搞瞎搞，快使用你的小刀!納茲格寧姆要你馬上去村子裡報到。', `MaleText_loc7`='¡Deja de quejarte y usa tu cuchillo! Nazgrim quiere que te presentes en la aldea de inmediato.', `FemaleText_loc1`='소란 떨지 말고 칼을 사용하세요! 나즈그림 장군님께서 근처 마을로 즉시 보고하라고 하셨어요.', `FemaleText_loc4`='别浪费时间了，打起精神来！纳兹戈林要你立刻去村里报到。', `FemaleText_loc5`='不要胡搞瞎搞，快使用你的小刀!納茲格寧姆要你馬上去村子裡報到。', `FemaleText_loc7`='¡Deja de quejarte y usa tu cuchillo! Nazgrim quiere que te presentes en la aldea de inmediato.' WHERE `ID`=53485;
