UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 번에는 운이 따르시길 바라요, $n 님. 한 번에 여러 적을 공격하는 기술을 사용해 보세요!', `FemaleText_loc4`='祝你下次好运，$n。你可以试着用一些能够同时打击多名敌人的技巧！', `FemaleText_loc5`='下次會更好，$n。試著用技能一口氣擊中數名敵人!', `FemaleText_loc7`='Te irá mejor la próxima vez, $n. Prueba a utilizar facultades que golpean a varios enemigos a la vez.' WHERE `ID`=53488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하의 왕실 깃발입니다. 왕가의 혈통이 이 선실에서 잠을 잔 것이 틀림 없습니다.', `MaleText_loc4`='国王的皇家纹章。这间舱室里肯定住过某位具有皇室血统的大人物。', `MaleText_loc5`='國王的皇家旗幟。肯定有個皇家血統的人在這房間裡睡過。', `MaleText_loc7`='El estandarte del rey. Es evidente que alguien de sangre real durmió en esta habitación.', `FemaleText_loc1`='국왕 폐하의 왕실 깃발입니다. 왕가의 혈통이 이 선실에서 잠을 잔 것이 틀림 없습니다.', `FemaleText_loc4`='国王的皇家纹章。这间舱室里肯定住过某位具有皇室血统的大人物。', `FemaleText_loc5`='國王的皇家旗幟。肯定有個皇家血統的人在這房間裡睡過。', `FemaleText_loc7`='El estandarte del rey. Es evidente que alguien de sangre real durmió en esta habitación.' WHERE `ID`=53489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 병사는 다른 이들과는 다릅니다. 개인 경호원처럼 보입니다.', `MaleText_loc4`='这个士兵和其他人不一样。他看起来像是个私人保镖。', `MaleText_loc5`='這位戰士和其他人不同，他像是個人保鏢。', `MaleText_loc7`='Este soldado es distinto a los demás. Parece un guardaespaldas personal.', `FemaleText_loc1`='이 병사는 다른 이들과는 다릅니다. 개인 경호원처럼 보입니다.', `FemaleText_loc4`='这个士兵和其他人不一样。他看起来像是个私人保镖。', `FemaleText_loc5`='這位戰士和其他人不同。他像是個人保鏢。', `FemaleText_loc7`='Este soldado es distinto a los demás. Parece un guardaespaldas personal.' WHERE `ID`=53490;
