UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 살아 있어서는 안 되네, $r.$b$b내 형제들과 함께 죽었어야 했어.', `MaleText_loc4`='我就不该苟活下来，$r。$b$b我应该和其他兄弟们死在一起。', `MaleText_loc5`='我不該活下來，$r。$b$b我應該和其他弟兄們一起死去。', `MaleText_loc7`='No debería seguir con vida, $r.$b$bDebería haber muerto con el resto de mis hermanos.' WHERE `ID`=53493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재집결해야 합니다, 하사관님! 근처 마을로 가십시오.', `MaleText_loc4`='我们需要重整队伍，中士！去附近的村里报到。', `MaleText_loc5`='士官，我們得重整隊伍!到附近的村子去。', `MaleText_loc7`='¡Debemos reagruparnos, sargento! Ve a la aldea más cercana.', `FemaleText_loc1`='재집결해야 해요, 하사관님! 근처 마을로 가세요.', `FemaleText_loc4`='我们需要重整队伍，中士！去附近的村里报到。', `FemaleText_loc5`='士官，我們得重整隊伍!到附近的村子去。', `FemaleText_loc7`='¡Debemos reagruparnos, sargento! Ve a la aldea más cercana.' WHERE `ID`=53494;
