UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $c. 슬퍼할 시간이 없네. 쓰러진 형제들의 복수를 하고, 이 땅을 호드의 이름으로 점령해야 하네!', `MaleText_loc4`='没错，$c，我们没有时间悲伤了。让我们为死去的同胞复仇，为部落夺下这片土地！', `MaleText_loc5`='是的，$c，沒時間哀悼了。讓我們替死去的同袍報仇，為了部落佔領這片土地!', `MaleText_loc7`='Tienes razón, $c. No es momento de llorar. ¡Vamos a vengar a nuestros hermanos caídos y conquistar estas tierras en nombre de la Horda!' WHERE `ID`=53499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자를 살펴보다가 부분적으로 물에 젖은 쪽지들을 발견했습니다. 왕자님의 글씨입니다. 노드에게 가져가는 게 좋겠습니다.', `MaleText_loc4`='你发现了一叠被浸湿的纸张，上面有王子殿下的笔迹。你最好把它们拿去给诺德看看。', `MaleText_loc5`='你發現一疊濕了大半的頁面，字跡出於王子之手。你最好帶回去給諾德看。', `MaleText_loc7`='Encuentras un fajo de páginas empapadas, escritas de puño y letra del príncipe. Será mejor que se las lleves a Nodd.', `FemaleText_loc1`='상자를 살펴보다가 부분적으로 물에 젖은 쪽지들을 발견했습니다. 왕자님의 글씨입니다. 노드에게 가져가는 게 좋겠습니다.', `FemaleText_loc4`='你发现了一叠被浸湿的纸张，上面有王子殿下的笔迹。你最好把它们拿去给诺德看看。', `FemaleText_loc5`='你發現一疊濕了大半的頁面，字跡出於王子之手。你最好帶回去給諾德看。', `FemaleText_loc7`='Encuentras un fajo de páginas empapadas, escritas de puño y letra del príncipe. Será mejor que se las lleves a Nodd.' WHERE `ID`=53500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제 준비는 정말 힘듭니다.', `MaleText_loc4`='这种调整工作可不简单。', `MaleText_loc5`='把場地設置妥當還真的不簡單。', `MaleText_loc7`='Este tinglado parece bastante trabajoso.', `FemaleText_loc1`='축제 준비는 정말 힘들어요.', `FemaleText_loc4`='这种调整工作可不简单。', `FemaleText_loc5`='把場地設置妥當還真的不簡單。', `FemaleText_loc7`='Este tinglado parece bastante trabajoso.' WHERE `ID`=53501;
