UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오! 나즈그림 장군님께서 역습을 준비하고 계십니다. 저 마을에서 재집결해야 합니다.', `MaleText_loc4`='赶快行动！纳兹戈林在谋划反击。我们正在村里重新集结。', `MaleText_loc5`='快站起來!納茲格寧姆正在組織一次反攻。我們正在村子裡重整部隊。', `MaleText_loc7`='¡Levanta! Nazgrim está preparando un contraataque. Nos reagruparemos en la aldea.', `FemaleText_loc1`='일어나세요! 나즈그림 장군님께서 역습을 준비하고 계세요. 저 마을에서 재집결해야 해요.', `FemaleText_loc4`='赶快行动！纳兹戈林在谋划反击。我们正在村里重新集结。', `FemaleText_loc5`='快站起來!納茲格寧姆正在組織一次反攻。我們正在村子裡重整部隊。', `FemaleText_loc7`='¡Levanta! Nazgrim está preparando un contraataque. Nos reagruparemos en la aldea.' WHERE `ID`=53504;
