UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 살 것 같군요. 밧줄이 너무 단단히 묶여 있었습니다.', `MaleText_loc4`='啊，这下好多了。那些玩意儿缠得太紧了。', `MaleText_loc5`='啊，好多了。那可綁得真緊。', `MaleText_loc7`='Ah, mucho mejor. Las cuerdas me estaban cortando la circulación.', `FemaleText_loc1`='아, 살 것 같군요. 밧줄이 너무 단단히 묶여 있었어요.', `FemaleText_loc4`='啊，这下好多了。那些玩意儿缠得太紧了。', `FemaleText_loc5`='啊，好多了。那可綁得真緊。', `FemaleText_loc7`='Ah, mucho mejor. Las cuerdas me estaban cortando la circulación.' WHERE `ID`=53558;
