UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 괜찮습니다. 다른 이들을 도와주십시오!', `MaleText_loc4`='我会没事的，请去帮助别人吧！', `MaleText_loc5`='我會沒事的。請去幫忙其他人!', `MaleText_loc7`='Yo estoy bien, ¡ayuda a los demás!', `FemaleText_loc1`='전 괜찮아요. 다른 이들을 도와주세요!', `FemaleText_loc4`='我会没事的，请去帮助别人吧！', `FemaleText_loc5`='我會沒事的。請去幫忙其他人!', `FemaleText_loc7`='Yo estoy bien, ¡ayuda a los demás!' WHERE `ID`=53560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 놈들이 우리에게 무슨 짓을 하려고 했는지, 생각하기도 싫습니다.', `MaleText_loc4`='谢谢你，我都不敢想象他们想对我们做什么。', `MaleText_loc5`='謝謝你，我甚至沒膽子去想他們打算對我們做什麼事。', `MaleText_loc7`='Gracias. No quiero ni saber lo que tenían pensado hacer con nosotros.', `FemaleText_loc1`='고마워요. 놈들이 우리에게 무슨 짓을 하려고 했는지, 정말 생각하기도 싫어요.', `FemaleText_loc4`='谢谢你，我都不敢想象他们想对我们做什么。', `FemaleText_loc5`='謝謝你，我甚至沒膽子去想他們打算對我們做什麼事。', `FemaleText_loc7`='Gracias. No quiero ni saber lo que tenían pensado hacer con nosotros.' WHERE `ID`=53561;
