UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에게 항복하는 일은 없다!', `MaleText_loc4`='我们绝不向魔古族低头！', `MaleText_loc5`='我們永遠不向魔古屈服!', `MaleText_loc7`='¡Jamás obedeceremos a los mogu!', `FemaleText_loc1`='모구에게 항복하는 일은 없다!', `FemaleText_loc4`='我们绝不向魔古族低头！', `FemaleText_loc5`='我們永遠不向魔古屈服!', `FemaleText_loc7`='¡Jamás obedeceremos a los mogu!' WHERE `ID`=53566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공정하고 정직한 전투를 통해서만이 자신의 진정한 힘을 시험해볼 수 있네. 다른 시험은 모두 그릇될 뿐.', `MaleText_loc4`='只有公平公正的战斗才能真正衡量出一个人的实力。任何其他的考验都是有瑕疵的。', `MaleText_loc5`='公平的戰鬥是對力量的真正考驗。任何其他形式的測驗都是不公正的。', `MaleText_loc7`='El combate justo y honesto es la única prueba para demostrar la fuerza de cada uno. Cualquier otra prueba no sirve.' WHERE `ID`=53569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이는 못 속이겠네. 옛날처럼 움직일 수가 없어. 내 옛 친구에게도 해 줄 수 있는 게 없다네.', `MaleText_loc4`='真是岁月催人老啊。我的行动已经不如从前敏捷了，所以我也很少去看我的老朋友了……', `MaleText_loc5`='看來我終究老了。我沒辦法像以前一樣行動，也因此沒什麼能留給我的老朋友...', `MaleText_loc7`='Parece que la edad me ha pasado factura. Ya no me muevo como antes, así que no me queda mucho que ofrecer al que una vez fue mi amigo...' WHERE `ID`=53570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 강하다면 내가 존중해 주겠네.$b$b자네가 약하다면 내가 격려해 주겠네.$b$b자네가 적이라면 내가 주먹으로 맞서 주겠네. 필요하다면, 여러 번이라도.', `MaleText_loc4`='如果你很强壮，那我会向你表示敬意。$b$b如果你很软弱，那我也会鼓励你。$b$b如果你是我的敌人，那我就会用拳头来揍你。如果有必要的话，我会一次又一次地接着揍你。', `MaleText_loc5`='如果你很強大，我會對你表示尊敬。$b$b如果你很弱小，我會給你鼓勵。$b$b如果你是我的敵人，我會請你吃我的拳頭。必要的話，請你多吃幾顆。', `MaleText_loc7`='Si eres fuerte, te ofrezco mi respeto.$b$bSi eres débil, te ofrezco mi apoyo.$b$bSi eres mi enemigo, te ofrezco mi puño. Todas las veces que haga falta.' WHERE `ID`=53571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 통해 정신을 환기하고, 교전을 통해 깨달음을 얻고, 지르기를 통해 평온을 이뤄야 하네.$b$b이것이 티엔의 방식이야.', `MaleText_loc4`='以战生慧，以斗促觉，以动得静。$b$b这就是天之道。', `MaleText_loc5`='從戰鬥中觀悟自然，在過招中啟發自我，以武止戈。$b$b這就是天僧寺之道。', `MaleText_loc7`='Alcanza la lucidez a través del combate. La iluminación a través del compromiso. La paz a través del puño.$b$bAsí es el estilo Tian.' WHERE `ID`=53572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽함의 열쇠는 바로 규율이네. 자신의 나태함과 싸워 이기게! 게으름을 극복해야 하네!', `MaleText_loc4`='纪律是臻于完美的关键。你必须打败你的惰性！管好你那把懒骨头！', `MaleText_loc5`='紀律是臻至完美的關鍵。擊潰你的惰性!駕馭自身的懶散!', `MaleText_loc7`='La disciplina es la clave de la perfección. ¡Vence tu pereza! ¡Domina la holgazanería!' WHERE `ID`=53573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버님은 클라우드폴 님 이전의 대장로셨네. 내가 아는 모든 것은 아버님께 배웠지.', `MaleText_loc4`='我父亲是云瀑长老的前任。我所知道的一切都是他教的。', `MaleText_loc5`='我父親是雲落前一任的高階長者，他教導我所知的一切。', `MaleText_loc7`='Mi padre fue el gran ancestro antes que Otoño Nublo. Me enseñó todo lo que sé.' WHERE `ID`=53574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반복해서 연습하면 무엇이든 완벽하게 습득할 수 있네.', `MaleText_loc4`='只要反复练习，没有什么是掌握不了的。', `MaleText_loc5`='反覆練習是精通一切事物的法門。', `MaleText_loc7`='No hay nada que no se pueda dominar mediante la repetición.' WHERE `ID`=53575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 연습할 준비가 되었습니다, 교관님.', `MaleText_loc4`='我做好再练一次的准备了，教头。', `MaleText_loc5`='我準備好再次練習了，導師。', `MaleText_loc7`='Estoy listo para seguir entrenando, instructor.', `FemaleText_loc1`='다시 연습할 준비가 되었어요, 교관님.', `FemaleText_loc4`='我做好再练一次的准备了，教头。', `FemaleText_loc5`='我準備好再次練習了，導師。', `FemaleText_loc7`='Estoy lista para seguir entrenando, instructor.' WHERE `ID`=53576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 와주셔서 다행입니다. 저 혼자였다면 이 문제를 해결할 수 없었을 겁니다.', `MaleText_loc4`='很高兴你能前来——我一个人没法解决这个问题。', `MaleText_loc5`='有你來這裡很好。我沒辦法獨自解決這件事。', `MaleText_loc7`='Me alegro de que hayas venido. No habría podido resolver esto solo.' WHERE `ID`=53577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$N|1을;를; 위해 만세 세 번! 만세 세 번과 맥주 세 잔!', `MaleText_loc4`='为$n欢呼三声吧！再来三杯啤酒！', `MaleText_loc5`='為$n歡呼三聲!然後乾三杯啤酒!', `MaleText_loc7`='¡Tres hurras por $n! ¡Tres hurras y tres birras!' WHERE `ID`=53578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투기장 안에서 폭죽을 발사하세요. 여러 적과 한번에 맞설 준비를 하시고요! 난투에서는 무슨 일이 일어날지 아무도 모르니까요.', `FemaleText_loc4`='进入乱斗比武场并燃放焰火。然后，做好同时面对几名对手的准备吧！在乱斗比武场中，一切皆有可能。', `FemaleText_loc5`='進入格鬥競技場，然後點放煙火。準備好同時面對數名敵人!格鬥場上什麼意外都可能發生。', `FemaleText_loc7`='Entra en Fosa Embrollo y dispara los fuegos artificiales. ¡Prepárate para enfrentarte a varios enemigos a la vez! En el Embrollo puede pasar cualquier cosa.' WHERE `ID`=53579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 아래에서 수련생들과 함께 사각 진형에 맞춰 서게. 그리고 교관의 지시를 따르게.', `MaleText_loc4`='加入下面那些弟子的队伍吧。然后像他们一样，跟着带头的做。', `MaleText_loc5`='到下面去加入弟子們的方陣，然後和他們一起跟隨領隊的指導。', `MaleText_loc7`='Únete a los estudiantes que están formados en bloque más abajo. Luego sigue al líder, como lo harán ellos.' WHERE `ID`=53581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"왼쪽"이나 "오른쪽"이라고 구령을 외치겠네. 주의를 집중하게, $c.', `MaleText_loc4`='我会喊出“左”和“右”的口令。你要注意听，$c。', `MaleText_loc5`='我會發號「左」或者是「右」。注意好了，$c。', `MaleText_loc7`='Voy a gritarte las instrucciones "izquierda" y "derecha". Presta atención, $c.' WHERE `ID`=53582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말로른 말로른 말로른...', `MaleText_loc4`='玛洛恩！玛洛恩！玛洛恩！', `MaleText_loc5`='瑪洛尼瑪洛尼瑪洛尼。', `MaleText_loc7`='MALORNE MALORNE MALORNE' WHERE `ID`=53584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제 진짜 끝내준다!', `MaleText_loc4`='这个马戏团太棒了！', `MaleText_loc5`='這個馬戲團真棒!', `MaleText_loc7`='¡Esta feria es genial!', `FemaleText_loc1`='다크문 축제는 정말 재미있어!', `FemaleText_loc4`='这个马戏团太棒了！', `FemaleText_loc5`='這個馬戲團真棒!', `FemaleText_loc7`='¡Esta feria es genial!' WHERE `ID`=53591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원래는 여기에서 놀아야 하는 건데, 다른데 돌아다녀도 그렇게 안 위험할 거야.', `MaleText_loc4`='我们本来是只能在这里玩的。可我想我们稍微走远一些也不会有什么大问题。', `MaleText_loc5`='我們原本應該在這裡玩，不過我敢說我們可以四處晃晃，也不會惹上什麼麻煩才對。', `MaleText_loc7`='Se supone que tenemos que jugar aquí, pero apuesto a que podemos andar por ahí sin meternos en problemas.', `FemaleText_loc1`='원래는 여기에서 놀아야 하는 건데, 다른데 돌아다녀도 그렇게 안 위험할 거야.', `FemaleText_loc4`='我们本来是只能在这里玩的。可我想我们稍微走远一些也不会有什么大问题。', `FemaleText_loc5`='我們原本應該在這裡玩，不過我敢說我們可以四處晃晃，也不會惹上什麼麻煩才對。', `FemaleText_loc7`='Se supone que tenemos que jugar aquí, pero apuesto a que podemos andar por ahí sin meternos en problemas.' WHERE `ID`=53592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모래터는 자주 청소하는지 모르겠네.', `MaleText_loc4`='我在想，这个沙箱到底多久清理一次啊。', `MaleText_loc5`='不知道這個沙箱多久會清理一次呢。', `MaleText_loc7`='Me pregunto cada cuánto tiempo se limpia el cajón de arena.', `FemaleText_loc1`='이 모래터는 자주 청소하는 건지 몰라.', `FemaleText_loc4`='我在想，这个沙箱到底多久清理一次啊。', `FemaleText_loc5`='不知道這個沙箱多久會清理一次呢。', `FemaleText_loc7`='Me pregunto cada cuánto tiempo se limpia el cajón de arena.' WHERE `ID`=53593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모래터에서 노는 건 정말 지루해.', `MaleText_loc4`='这个沙箱真无聊。', `MaleText_loc5`='這個沙箱相當無聊。', `MaleText_loc7`='Este cajón de arena es bastante aburrido.', `FemaleText_loc1`='모래터에서 노는 건 정말 지루해.', `FemaleText_loc4`='这个沙箱真无聊。', `FemaleText_loc5`='這個沙箱相當無聊。', `FemaleText_loc7`='Este cajón de arena es bastante aburrido.' WHERE `ID`=53594;
