UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정권 지르기, 발차기, 식사, 술주정... 이런 걸 모두 마치고 나면, 누군가 그 흔적들을 치워야 하겠지.$b$b관리인이 등장하는 건, 바로 그 순간이네.', `MaleText_loc4`='经过一阵拳打脚踢，大吃大喝之后……必须得有人来打扫。$b$b现在就该园丁上了。', `MaleText_loc5`='經過一陣狂毆亂踹，還有大吃大喝之後...總得有人來打掃。$b$b那就是園丁的工作了。', `MaleText_loc7`='Después de todos los puñetazos, patadas, comida y bebida... alguien tiene que limpiar.$b$bAhí es donde entra el papel del guardés.' WHERE `ID`=53609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들을 매일매일 대포로 쏴 보내면 어떨까?', `MaleText_loc4`='为什么那个大炮里不能一直飞出人来？', `MaleText_loc5`='為什麼大家不會每次都從大砲裡面飛出去?', `MaleText_loc7`='Deberíamos disparar a gente con cañones todo el tiempo.', `FemaleText_loc1`='사람들을 매일매일 대포로 쏴 보내면 어떨까?', `FemaleText_loc4`='为什么那个大炮里不能一直飞出人来？', `FemaleText_loc5`='為什麼大家不會每次都從大砲裡面飛出去?', `FemaleText_loc7`='Deberíamos disparar a gente con cañones todo el tiempo.' WHERE `ID`=53610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉술과 운무술은 혼자 연습해도 되네. 난 그저 여기 서서 구경하는 것만으로도 충분히 즐겁거든.', `MaleText_loc4`='你还是留着你的棍术和织雾绝招吧，我站在这里看看就行了。', `MaleText_loc5`='你可以繼續玩你的花拳繡腿，我樂得站在這裡欣賞。', `MaleText_loc7`='Podéis quedaros con las peleas de palos y el tejido de niebla. Yo estoy muy bien aquí sentado, mirando.' WHERE `ID`=53611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 대포알들은 다 뭐죠? 가져가도 되는 건가요?', `MaleText_loc4`='那些炮弹有什么用？他们会让你带一个吗？', `MaleText_loc5`='砲彈是幹嘛用的?他們允許你攜帶這個嗎?', `MaleText_loc7`='¿Para qué son las balas de cañón? ¿Te dejan llevar una?', `FemaleText_loc1`='저 대포알들은 다 뭐죠? 가져가도 되는 건가요?', `FemaleText_loc4`='那些炮弹有什么用？他们会让你带一个吗？', `FemaleText_loc5`='砲彈是幹嘛用的?他們允許你攜帶這個嗎?', `FemaleText_loc7`='¿Para qué son las balas de cañón? ¿Te dejan llevar una?' WHERE `ID`=53612;
