UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 더 위로 번쩍 들어서 쏴야 하는데.', `MaleText_loc4`='他们应该把炮口笔直朝上。', `MaleText_loc5`='他們應該要把大砲往正上方瞄準。', `MaleText_loc7`='Deberían apuntar el cañón todo recto.', `FemaleText_loc1`='대포를 더 위로 번쩍 들어서 쏴야 하는데.', `FemaleText_loc4`='他们应该把炮口笔直朝上。', `FemaleText_loc5`='他們應該要把大砲往正上方瞄準。', `FemaleText_loc7`='Deberían apuntar el cañón todo recto.' WHERE `ID`=53614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원 교육 과정 내내 게으름만 피우다 보면 어떻게 되는지 아는가? 다름 아닌 관리인이 되는 걸세.$b$b사실, 그렇게 나쁘지는 않네. 빈손으로 왔다가 빗자루 하나 얻어 가는 거니까...$b$b<한숨 쉬는 우>', `MaleText_loc4`='你知道总在禅院的日课上偷懒会有什么后果吗？你会沦为园丁！就像我这样。$b$b不过这也不算太糟。我总算有了一把自己的扫帚。$b$b<老吴叹了口气。>', `MaleText_loc5`='如果你在所有的寺院課程中偷懶會發生什麼事，你知道嗎?你會變成園丁。就是這回事。$b$b但這也不是那麼壞，我有我的掃帚陪伴。$b$b<老吳嘆口氣。>', `MaleText_loc7`='¿Sabes qué ocurre si vagueas en todas las clases del monasterio? Que te conviertes en guardés, eso es lo que pasa.$b$bAunque no está tan mal. Tengo mi propia escoba.$b$b<Wu suspira.>' WHERE `ID`=53615;
