UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 불도 무섭지만, 공중으로 날아가는 불은 더 무서워.', `MaleText_loc4`='喷火是很吓人，可是被大炮打到天上更吓人。', `MaleText_loc5`='火焰是很可怕，但是從空中呼嘯而過的火焰更可怕。', `MaleText_loc7`='El fuego da miedo, pero el fuego volando por los aires da más miedo todavía.', `FemaleText_loc1`='그냥 불도 무섭지만, 공중으로 날아가는 불은 더 무서워.', `FemaleText_loc4`='喷火是很吓人，可是被大炮打到天上更吓人。', `FemaleText_loc5`='火焰是很可怕，但是從空中呼嘯而過的火焰更可怕。', `FemaleText_loc7`='El fuego da miedo, pero el fuego volando por los aires da más miedo todavía.' WHERE `ID`=53630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내준다!', `MaleText_loc4`='他们很棒！', `MaleText_loc5`='他們棒透了!', `MaleText_loc7`='¡Son increíbles!', `FemaleText_loc1`='진짜 끝내주네!', `FemaleText_loc4`='他们很棒！', `FemaleText_loc5`='他們棒透了!', `FemaleText_loc7`='¡Son increíbles!' WHERE `ID`=53631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 어른이 되면 불꽃 곡예사가 될 거야!', `MaleText_loc4`='我长大以后，也要当一个喷火的杂耍艺人！', `MaleText_loc5`='等我長大我也要當火焰雜耍師!', `MaleText_loc7`='¡Cuando sea mayor, quiero ser malabarista de fuego!', `FemaleText_loc1`='나중에 어른이 되면 불꽃 곡예사가 될 거야!', `FemaleText_loc4`='我长大以后，也要当一个喷火的杂耍艺人！', `FemaleText_loc5`='等我長大我也要當火焰雜耍師!', `FemaleText_loc7`='¡Cuando sea mayor, quiero ser malabarista de fuego!' WHERE `ID`=53632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 불꽃 곡예를 해보면 잘할 수 있을 것 같아.', `MaleText_loc4`='我想，我只要努力尝试，也可以喷出火来。', `MaleText_loc5`='我覺得我也可以學會火焰雜耍。', `MaleText_loc7`='Creo que podría hacer malabares con fuego si lo intentase.', `FemaleText_loc1`='나도 불꽃 곡예를 해보면 잘할 수 있을 것 같아.', `FemaleText_loc4`='我想，我只要努力尝试，也可以喷出火来。', `FemaleText_loc5`='我覺得我也可以學會火焰雜耍。', `FemaleText_loc7`='Creo que podría hacer malabares con fuego si lo intentase.' WHERE `ID`=53633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최근까지도 이 근방의 모구는 숲 속에서 여행자들을 습격하는 것으로만 만족했단다. 하지만 이번 공습은 다르구나. 조직적이고... 목적 의식이 뚜렷해.', `FemaleText_loc4`='不久之前，魔古族还只是在树林里伏击一下过往的行人而已。但这次袭击不同，这次行动是有组织……有目的的。', `FemaleText_loc5`='在這之前，這區域裡的魔古只要偷襲幾個經過林中的旅人就夠他們樂的了。這次的行動卻不一樣，有組織...也有目的。', `FemaleText_loc7`='Hasta hace poco, los mogu de esta región se limitaban a tender emboscadas a los viajeros en el bosque. Este asalto era diferente... Estaban organizados y tenían un propósito.' WHERE `ID`=53635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 문으로 들어온 이 중에서 충격을 받지 않거나, 다치지 않은 건 너뿐이구나.$B$B네가 우릴 도와줄 수 있다는 뜻이면 좋겠는데.', `FemaleText_loc4`='你是第一个穿过那座大门后没有被吓坏、或是受伤，或是又伤又怕的。$B$B但愿你能帮上我们的忙。', `FemaleText_loc5`='進門的人那麼多，你是唯一一個沒有受驚或負傷的。$B$B我希望這代表著你能幫得上忙。', `FemaleText_loc7`='Eres $gel primero:la primera; en atravesar esa puerta sin estar en shock, $gherido:herida; o las dos cosas.$b$bEspero que eso signifique que nos puedes ayudar.' WHERE `ID`=53636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가십시오! 안전한 곳으로 어서 가십시오!', `MaleText_loc4`='快跑！到安全的地方去！', `MaleText_loc5`='快!到安全的地方去!', `MaleText_loc7`='¡Vete! ¡Ponte a salvo!', `FemaleText_loc1`='가세요! 안전한 곳으로 어서 가세요!', `FemaleText_loc4`='快跑！到安全的地方去！', `FemaleText_loc5`='快!到安全的地方去!', `FemaleText_loc7`='¡Vete! ¡Ponte a salvo!' WHERE `ID`=53637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 버리십시오. 그럴 가치가 없습니다!', `MaleText_loc4`='别管它了，这不值得！', `MaleText_loc5`='別管它了，那不值得!', `MaleText_loc7`='¡Déjalo! ¡No merece la pena!', `FemaleText_loc1`='그건 버리세요. 그럴 가치가 없어요!', `FemaleText_loc4`='别管它了，这不值得！', `FemaleText_loc5`='別管它了，那不值得!', `FemaleText_loc7`='¡Déjalo! ¡No merece la pena!' WHERE `ID`=53638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 수도원이죠!$b$b이곳 티엔 수도원에서는 여러 수도사님들께서 저처럼 젊은 판다렌에게 전투하는 법을 가르쳐 주신답니다. 위대한 투사들은 모두 이곳에서 배움을 시작했어요. 칼날의 유 밍, 무적의 리앙... 심지어는 위대한 황제 샤오하오 님도 바로 이 사원에서 한때 수련을 받으셨다고 해요.$b$b뭐, 그런 전설이 있어요.', `FemaleText_loc4`='当然是一座禅院！$b$b天禅院的武僧专门教授像我一样的年轻熊猫人如何战斗。所有的战斗大师都是在这里诞生的：剑仙宇明、铁布衫梁……甚至连伟大的帝王少昊都是在这座寺院学习的。$b$b或者至少传闻是这么说的。', `FemaleText_loc5`='當然是座僧寺囉!$b$b天僧寺這裡的武僧專精於教導像我這樣的年輕熊貓人戰鬥之道。這裡是所有偉大戰士的發源地:『刀鋒之王』余明、『鐵骨』梁...就連紹昊大帝也在這寺院接受過訓練。$b$b至少傳說是這樣描述的。', `FemaleText_loc7`='¡Un monasterio, evidentemente!$b$bLos monjes del Monasterio Tian se especializan en enseñar a luchar a los pandaren jóvenes como yo. Todos los luchadores legendarios se adiestraron aquí: Yu Ming la Espada, Liang la Invencible... hasta el gran emperador Shaohao estudió en este templo.$b$bAl menos, eso es lo que cuentan las leyendas.' WHERE `ID`=53644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕 위의 보금자리에 잘 오셨어요, $r님.', `FemaleText_loc4`='欢迎来到我们在群山中的家园，$r。', `FemaleText_loc5`='歡迎來到我們山丘上的家，$r。', `FemaleText_loc7`='Te doy la bienvenida a nuestro hogar en las colinas, $r.' WHERE `ID`=53645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 그리고 어서 오세요!', `FemaleText_loc4`='你好啊！欢迎你！', `FemaleText_loc5`='幸會!歡迎!', `FemaleText_loc7`='¡Hola! ¡$gBienvenido:Bienvenida;!' WHERE `ID`=53646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 어떤 곳입니까?', `MaleText_loc4`='这里是什么地方？', `MaleText_loc5`='這是什麼地方?', `MaleText_loc7`='¿Qué es este lugar?', `FemaleText_loc1`='이곳은 어떤 곳인가요?', `FemaleText_loc4`='这里是什么地方？', `FemaleText_loc5`='這是什麼地方?', `FemaleText_loc7`='¿Qué es este lugar?' WHERE `ID`=53647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체...?! 뭐하는 겁니까? 저는 장난감을 만들어야 한단 말입니다!', `MaleText_loc4`='什——？！你干嘛——？！我还要做玩具呢！', `MaleText_loc5`='什麼...?!你怎麼...?!我還得繼續做玩具呢!', `MaleText_loc7`='¡¿Pero qué...?! ¡¿Por qué has...?! ¡Tengo juguetes que hacer!', `FemaleText_loc1`='이게 대체...?! 뭐하는 건가요? 저는 장난감을 만들어야 해요!', `FemaleText_loc4`='什——？！你干嘛——？！我还要做玩具呢！', `FemaleText_loc5`='什麼...?!你怎麼...?!我還得繼續做玩具呢!', `FemaleText_loc7`='¡¿Pero qué...?! ¡¿Por qué has...?! ¡Tengo juguetes que hacer!' WHERE `ID`=53652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 겨울맞이 축제가 열릴 때는 아니지 않습니까. 전 할 일이 있단 말입니다!', `MaleText_loc4`='冬幕节还没到呢。我还有工作呢！', `MaleText_loc5`='還沒到冬幕節。我還得幹活呢!', `MaleText_loc7`='Todavía no es el Festival de Invierno, ¿sabes? ¡Tengo trabajo que hacer!', `FemaleText_loc1`='아직 겨울맞이 축제가 열릴 때는 아니잖아요. 전 할 일이 있다고요!', `FemaleText_loc4`='冬幕节还没到呢。我还有工作呢！', `FemaleText_loc5`='還沒到冬幕節。我還得幹活呢!', `FemaleText_loc7`='Todavía no es el Festival de Invierno, ¿sabes? ¡Tengo trabajo que hacer!' WHERE `ID`=53653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞물림톱니가 2만 개 필요하고, 또 다른 게... 어어! 저를 그렇게 소환해버리면 안 됩니다!', `MaleText_loc4`='我们还需要两万个齿轮，以及……嘿！你不能这么召唤我！', `MaleText_loc5`='我們還需要兩萬個齒輪，還有....喂!你不能這樣隨便召喚我!', `MaleText_loc7`='Necesitaremos cien ruedas de piñones más, y otro... ¡oye! No puedes invocarme así como así.', `FemaleText_loc1`='맞물림톱니가 2만 개 필요하고, 또 다른 게... 어어! 저를 그렇게 소환해버리면 안 돼요!', `FemaleText_loc4`='我们还需要两万个齿轮，以及……嘿！你不能这么召唤我！', `FemaleText_loc5`='我們還需要兩萬個齒輪，還有....喂!你不能這樣隨便召喚我!', `FemaleText_loc7`='Necesitaremos cien ruedas de piñones más, y otro... ¡oye! No puedes invocarme así como así.' WHERE `ID`=53654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 도우미 432-A가 뭔지 들어보셨습니까? 제가 듣기로는... 어어? 이것 보십시오! 우리 도우미는 할 일이 있단 거 아시지 않습니까!', `MaleText_loc4`='那么，你听说过432-A型小助手吗？我听说……什——？嘿！我们小助手也是有正经工作的，你知道嘛！', `MaleText_loc5`='你有聽過助手432-A吧?我聽說...嗄?!喂!我們助手有工作得做的耶!', `MaleText_loc7`='¿Has oído hablar del ayudante 432-A? Por lo visto... ¿Pero qué...? ¡Oye! Los ayudantes tenemos trabajo que hacer, ¿sabías?', `FemaleText_loc1`='그러니까, 도우미 432-A가 뭔지 들어보셨어요? 제가 듣기로는... 어어? 이것 보세요! 우리 도우미는 할 일이 있단 거 아시잖아요!', `FemaleText_loc4`='那么，你听说过432-A型小助手吗？我听说……什——？嘿！我们小助手也是有正经工作的，你知道嘛！', `FemaleText_loc5`='你有聽過助手432-A吧?我聽說...嗄?!喂!我們助手有工作得做的耶!', `FemaleText_loc7`='¿Has oído hablar del ayudante 432-A? Por lo visto... ¿Pero qué...? ¡Oye! Los ayudantes tenemos trabajo que hacer, ¿sabías?' WHERE `ID`=53655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 겨울맞이 축제 같아 보이죠? 색색들이 불빛과 장식들이? 아니라고요? 흠, 이걸 누가 다 만들어야 하는지 알잖습니까, 네?!', `MaleText_loc4`='你觉得这像是冬幕节吗？彩灯，装饰？不像？很好，那你也知道这些东西是谁做的，不是吗？！', `MaleText_loc5`='你覺得這看起來像是冬幕節嗎?彩虹燈泡，花俏的裝飾?不像嗎?你知道這些東西全部都得由誰來做嗎?', `MaleText_loc7`='¿A ti te parece que es el festín del Festival de Invierno? ¿No? ¿Luces de colores, adornos? ¿No? Bien, sabes quién se encarga de hacer todas esas cosas, ¿verdad?', `FemaleText_loc1`='이거 겨울맞이 축제 같아 보이나요? 색색들이 불빛과 장식들이? 아니라고요? 흠, 이걸 누가 다 만들어야 하는지 알잖아요, 네?!', `FemaleText_loc4`='你觉得这像是冬幕节吗？彩灯，装饰？不像？很好，那你也知道这些东西是谁做的，不是吗？！', `FemaleText_loc5`='你覺得這看起來像是冬幕節嗎?彩虹燈泡，花俏的裝飾?不像嗎?你知道這些東西全部都得由誰來做嗎?', `FemaleText_loc7`='¿A ti te parece que es el festín del Festival de Invierno? ¿No? ¿Luces de colores, adornos? ¿No? Bien, sabes quién se encarga de hacer todas esas cosas, ¿verdad?' WHERE `ID`=53656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 보십시오, $c님. 요점은 이렇습니다. 잘 아시겠지만, 장난감과 전등, 축제용 약초 묶음 같은 것들은 땅을 파면 그냥 나오는 게 아닙니다. 그러니 제발 도우미 소환하는 것 좀 그만 하십시오.', `MaleText_loc4`='你瞧，$c。事情是这样的。玩具啊，彩灯啊，还有各种节日草药是不会自己做出来的，你知道吧？所以，别再召唤小助手了，拜托你！', `MaleText_loc5`='聽著，$c。我想講的是，玩具跟燈光跟節日草藥不會自己變出來，知道吧。所以不要再亂召喚助手了，拜託。', `MaleText_loc7`='Mira, $c. El tema es que los juguetes, las luces, y los fardos de las hierbas del Festival no se hacen solos, ¿sabías? Así que basta ya de tanto invocar al ayudante, ¿quieres?', `FemaleText_loc1`='이것 보세요, $c님. 요점은 이래요. 잘 아시겠지만, 장난감과 전등, 축제용 약초 묶음 같은 것들은 땅을 파면 그냥 나오는 게 아니라고요. 그러니 제발 도우미 소환하는 것 좀 그만 하세요.', `FemaleText_loc4`='你瞧，$c。事情是这样的。玩具啊，彩灯啊，还有各种节日草药是不会自己做出来的，你知道吧？所以，别再召唤小助手了，拜托你！', `FemaleText_loc5`='聽著，$c。我想講的是，玩具跟燈光跟節日草藥不會自己變出來，知道吧。所以不要再亂召喚助手了，拜託。', `FemaleText_loc7`='Mira, $c. El tema es que los juguetes, las luces, y los fardos de las hierbas del Festival no se hacen solos, ¿sabías? Así que basta ya de tanto invocar al ayudante, ¿quieres?' WHERE `ID`=53657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어? 또 이러기입니까?! 이것 보십시오, $c님. 당신이 괴물을 때려잡든, 경매장에서 입 벌리고 멍청하게 서 있든... 하여튼 당신이 뭘 하든 일 년 내내 지켜보는 것도 좋지만, 저도 할 일이 있단 말입니다.', `MaleText_loc4`='怎么——？又来？！你看，$c。你一整年都打怪或者在拍卖行里吸冷气，或者干别的无聊事，我已经看够了。我还有工作要做呢。', `MaleText_loc5`='什麼-?又來了?!拜託，$c。我是很喜歡看你扁怪物，陪你在拍賣場閒晃，或做其他你通常會做的那些事情，但是我有工作得做。', `MaleText_loc7`='¡¿Pero qué...?! ¡Otra vez! Mira, $c. Por mucho que me guste la idea de verte machacar monstruos o quedarte como un pasmarote en la casa de subastas o lo que sea que haces a lo largo del año, tengo trabajo que hacer.', `FemaleText_loc1`='어어? 또 이러기인가요?! 이것 보세요, $c님. 당신이 괴물을 때려잡든, 경매장에서 입 벌리고 멍청하게 서 있든... 하여튼 당신이 뭘 하든 일 년 내내 지켜보는 것도 좋지만, 저도 할 일이 있단 말이에요.', `FemaleText_loc4`='怎么——？又来？！你看，$c。你一整年都打怪或者在拍卖行里吸冷气，或者干别的无聊事，我已经看够了。我还有工作要做呢。', `FemaleText_loc5`='什麼-?又來了?!拜託，$c。我是很喜歡看你扁怪物，陪你在拍賣場閒晃，或做其他你通常會做的那些事情，但是我有工作得做。', `FemaleText_loc7`='¡¿Pero qué...?! ¡Otra vez! Mira, $c. Por mucho que me guste la idea de verte machacar monstruos o quedarte como un pasmarote en la casa de subastas o lo que sea que haces a lo largo del año, tengo trabajo que hacer.' WHERE `ID`=53658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 작업장은 어디 있습니까? 저는 이번 해 후반에 소환해 주십시오.', `MaleText_loc4`='哇！车间哪儿去了？！等今年的晚些时候再召唤我，好吗？', `MaleText_loc5`='嗚哇!工作室在哪?!晚點再召喚我可以嗎?', `MaleText_loc7`='¡Hey! ¡¿Dónde está el taller?! Invócame un poco más tarde en el año, ¿vale?', `FemaleText_loc1`='이야! 작업장은 어디 있나요? 저는 이번 해 후반에 소환해 주세요.', `FemaleText_loc4`='哇！车间哪儿去了？！等今年的晚些时候再召唤我，好吗？', `FemaleText_loc5`='嗚哇!工作室在哪?!晚點再召喚我可以嗎?', `FemaleText_loc7`='¡Hey! ¡¿Dónde está el taller?! Invócame un poco más tarde en el año, ¿vale?' WHERE `ID`=53659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오셔서 게임 동전을 사가십시오!', `MaleText_loc4`='快来买游戏代币啊！', `MaleText_loc5`='快來這裡換取你的遊戲代幣!', `MaleText_loc7`='¡Vengan por sus fichas de juego!', `FemaleText_loc1`='이리 오셔서 게임 동전 사가세요!', `FemaleText_loc4`='快来买游戏代币啊！', `FemaleText_loc5`='快來這裡換取你的遊戲代幣!', `FemaleText_loc7`='¡Vengan por sus fichas de juego!' WHERE `ID`=53660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임 동전입니다! 게임 동전! 게임 동전을 사십시오!', `MaleText_loc4`='代币！代币！代币！', `MaleText_loc5`='代幣!代幣!代幣!', `MaleText_loc7`='¡Fichas! ¡Fichas! ¡Fichas!', `FemaleText_loc1`='게임 동전이에요! 게임 동전! 게임 동전을 사세요!', `FemaleText_loc4`='代币！代币！代币！', `FemaleText_loc5`='代幣!代幣!代幣!', `FemaleText_loc7`='¡Fichas! ¡Fichas! ¡Fichas!' WHERE `ID`=53661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임 동전입니다! 게임 동전 사십시오!', `MaleText_loc4`='代币！快来买代币！', `MaleText_loc5`='代幣!來換你的代幣!', `MaleText_loc7`='¡Fichas! ¡Consigue tus fichas!', `FemaleText_loc1`='게임 동전입니다! 게임 동전 사가세요!', `FemaleText_loc4`='代币！快来买代币！', `FemaleText_loc5`='代幣!來換你的代幣!', `FemaleText_loc7`='¡Fichas! ¡Consigue tus fichas!' WHERE `ID`=53662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임을 하려면 동전을 내야 합니다. 이리 오셔서 게임 동전을 사가십시오!', `MaleText_loc4`='各位，你们得先付钱才能玩游戏！快来买游戏代币啊！', `MaleText_loc5`='你得花錢才能玩唷!快來換你的代幣!', `MaleText_loc7`='¡Tienen que pagar para jugar, amigos! ¡Vengan por sus fichas de juego!', `FemaleText_loc1`='게임을 하려면 동전을 내야 합니다. 이리 오셔서 게임 동전을 사가세요!', `FemaleText_loc4`='各位，你们得先付钱才能玩游戏！快来买游戏代币啊！', `FemaleText_loc5`='你得花錢才能玩唷!快來換你的代幣!', `FemaleText_loc7`='¡Tienen que pagar para jugar, amigos! ¡Vengan por sus fichas de juego!' WHERE `ID`=53663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임 동전 팝니다! 게임 동전 사가십시오!', `MaleText_loc4`='卖游戏代币了！快来买游戏代币！', `MaleText_loc5`='賣遊戲代幣!來這裡買你的遊戲代幣!', `MaleText_loc7`='¡Fichas a la venta! ¡Consigue tus fichas!', `FemaleText_loc1`='게임 동전 팔아요! 게임 동전 사가세요!', `FemaleText_loc4`='卖游戏代币了！快来买游戏代币！', `FemaleText_loc5`='賣遊戲代幣!來這裡買你的遊戲代幣!', `FemaleText_loc7`='¡Fichas a la venta! ¡Consigue tus fichas!' WHERE `ID`=53664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임을 하려면 게임 동전이 필요합니다. 게임 동전 사가십시오!', `MaleText_loc4`='有了游戏代币才能玩游戏。快来买游戏代币了！', `MaleText_loc5`='你必須使用遊戲代幣才能玩。快來買遊戲代幣喔!', `MaleText_loc7`='Necesitarás fichas de juego para jugar. ¡Ven por tus fichas de juego!', `FemaleText_loc1`='게임을 하려면 게임 동전이 필요해요. 게임 동전 사가세요!', `FemaleText_loc4`='有了游戏代币才能玩游戏。快来买游戏代币了！', `FemaleText_loc5`='你必須使用遊戲代幣才能玩。快來買遊戲代幣喔!', `FemaleText_loc7`='Necesitarás fichas de juego para jugar. ¡Ven por tus fichas de juego!' WHERE `ID`=53665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 어서 서두르십시오! 이리 오셔서 게임 동전 사가십시오!', `MaleText_loc4`='快快快！快来买游戏代币了！', `MaleText_loc5`='快來，快來唷!來這裡購買你的遊戲代幣!', `MaleText_loc7`='¡Deprisa, vamos! ¡Sube y consigue tus fichas de juego!', `FemaleText_loc1`='자자, 어서 서두르세요! 이리 오셔서 게임 동전 사가세요!', `FemaleText_loc4`='快快快！快来买游戏代币了！', `FemaleText_loc5`='快來，快來唷!來這裡購買你的遊戲代幣!', `FemaleText_loc7`='¡Deprisa, vamos! ¡Sube y consigue tus fichas de juego!' WHERE `ID`=53666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 거짓말하는 거 아닙니다. 이리 오셔서 게임 동전 사가십시오!', `MaleText_loc4`='嘿，嘿，我可不是开玩笑的，快来买游戏代币！', `MaleText_loc5`='嘿，嘿，我不是在開玩笑，來買個遊戲代幣吧!', `MaleText_loc7`='¡Eh, oye! ¡No estoy de broma, ven y compra una ficha de juego!', `FemaleText_loc1`='자자, 거짓말하는 거 아니에요. 이리 오셔서 게임 동전 사가세요!', `FemaleText_loc4`='嘿，嘿，我可不是开玩笑的，快来买游戏代币！', `FemaleText_loc5`='嘿，嘿，我不是在開玩笑，來買個遊戲代幣吧!', `FemaleText_loc7`='¡Eh, oye! ¡No estoy de broma, ven y compra una ficha de juego!' WHERE `ID`=53667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 안전하단다. 어서 내려오렴.', `MaleText_loc4`='现在安全了。你可以下来了。', `MaleText_loc5`='現在安全了。你可以下來了。', `MaleText_loc7`='Ya no hay peligro. Puedes bajar.', `FemaleText_loc1`='이제 안전하단다. 어서 내려오렴.', `FemaleText_loc4`='现在安全了。你可以下来了。', `FemaleText_loc5`='現在安全了。你可以下來了。', `FemaleText_loc7`='Ya no hay peligro. Puedes bajar.' WHERE `ID`=53675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이이익! 괴물들을 쫓아주세요!', `MaleText_loc4`='哎呀！救命啊，怪物要吃我啦！', `MaleText_loc5`='嚶!有怪獸!救救我!', `MaleText_loc7`='¡Eyy! ¡Sálvame de los monstruos!' WHERE `ID`=53677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 30분 후에 그 막을 올립니다!', `MaleText_loc4`='牛头人酋长音乐会将在30分钟后开演！', `MaleText_loc5`='牛頭大佬演唱會將在三十分鐘後開始!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 30 minutos!' WHERE `ID`=53679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 15분 후에 그 막을 올립니다!', `MaleText_loc4`='牛头人酋长音乐会将在15分钟后开演！', `MaleText_loc5`='牛頭大佬演唱會將在十五分鐘後開始!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 15 minutos!' WHERE `ID`=53680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌 족장들의 공연이 5분 후에 그 막을 올립니다!', `MaleText_loc4`='牛头人酋长音乐会将在5分钟后开演！', `MaleText_loc5`='牛頭大佬演唱會將在五分鐘後開始!', `MaleText_loc7`='¡El concierto de los Tauren Chieftains comenzará en 5 minutos!' WHERE `ID`=53681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제에 오신 여러분, 한판 놀아볼 준비가 되셨습니까?! 타우렌 족장들의 공연을 시작하겠습니다!', `MaleText_loc4`='马戏团的游客们，你们准备好了吗？牛头人酋长音乐会现在正式开演！', `MaleText_loc5`='馬戲團的觀眾們，準備好要搖滾了嗎?!牛頭大佬演唱會現在開始!', `MaleText_loc7`='Visitantes de la feria, ¿están listos para el rock? ¡Comienza el concierto de los Tauren Chieftains!' WHERE `ID`=53682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥의 마녀는 정말정말 무시무시해요.', `MaleText_loc4`='那个青玉巫婆超级恐怖的。', `MaleText_loc5`='玉巫婆超可怕的。', `MaleText_loc7`='La Bruja de Jade da un montón de miedo.' WHERE `ID`=53683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으익! 옥의 마녀예요! 숨어야겠어요!', `FemaleText_loc4`='呃！青玉巫婆！我得躲起来！', `FemaleText_loc5`='嚶!是玉巫婆!我得躲起來!', `FemaleText_loc7`='¡Aah! ¡Es la Bruja de Jade! ¡Tengo que esconderme!' WHERE `ID`=53684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 게임이 좀 쉽대.', `MaleText_loc4`='我听说这个游戏很简单。', `MaleText_loc5`='我聽說這個遊戲非常簡單。', `MaleText_loc7`='He oído que este juego es bastante fácil.', `FemaleText_loc1`='이 게임이 좀 쉽대.', `FemaleText_loc4`='我听说这个游戏很简单。', `FemaleText_loc5`='我聽說這個遊戲非常簡單。', `FemaleText_loc7`='He oído que este juego es bastante fácil.' WHERE `ID`=53685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고리가 거북이를 안 다치게 했으면 좋겠어.', `MaleText_loc4`='但愿这些环不会伤害那只海龟。', `MaleText_loc5`='我希望圈圈不會傷害到烏龜。', `MaleText_loc7`='Espero que los anillos no hieran a la tortuga.', `FemaleText_loc1`='고리가 거북이를 안 다치게 했으면 좋겠어.', `FemaleText_loc4`='但愿这些环不会伤害那只海龟。', `FemaleText_loc5`='我希望圈圈不會傷害到烏龜。', `FemaleText_loc7`='Espero que los anillos no hieran a la tortuga.' WHERE `ID`=53686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완용 거북이 가지고 싶다.', `MaleText_loc4`='我也想要一只宠物龟。', `MaleText_loc5`='我希望我也有隻烏龜寵物。', `MaleText_loc7`='Ojalá tuviera una tortuga como mascota.', `FemaleText_loc1`='애완용 거북이 가지고 싶어.', `FemaleText_loc4`='我也想要一只宠物龟。', `FemaleText_loc5`='我希望我也有隻烏龜寵物。', `FemaleText_loc7`='Ojalá tuviera una tortuga como mascota.' WHERE `ID`=53687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구한테 애완용 거북이가 있었는데, 다른 애한테 선물로 줘버렸어.', `MaleText_loc4`='我朋友就有一只，可他把它送掉了。', `MaleText_loc5`='我朋友本來有隻烏龜寵物，但是他把牠送人當禮物了。', `MaleText_loc7`='Mi amigo tenía una tortuga como mascota, pero la regaló.', `FemaleText_loc1`='내 친구한테 애완용 거북이가 있었는데, 다른 애한테 선물로 줘버렸어.', `FemaleText_loc4`='我朋友就有一只，可他把它送掉了。', `FemaleText_loc5`='我朋友本來有隻烏龜寵物，但是他把牠送人當禮物了。', `FemaleText_loc7`='Mi amigo tenía una tortuga como mascota, pero la regaló.' WHERE `ID`=53688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고리 던지기가 뭐 저래.', `MaleText_loc4`='套圈圈太好玩了。', `MaleText_loc5`='丟圈圈真該死的好玩。', `MaleText_loc7`='El lanzamiento de anillos es un escándalo.', `FemaleText_loc1`='고리 던지기가 뭐 저래.', `FemaleText_loc4`='套圈圈太好玩了。', `FemaleText_loc5`='丟圈圈真該死的好玩。', `FemaleText_loc7`='El lanzamiento de anillos es un escándalo.' WHERE `ID`=53689;
