UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 사람들을 정말 터무니없는 점괘가 나왔다고 하더라.', `MaleText_loc4`='我听说，有些人算出来的命运很吓人。', `MaleText_loc5`='我聽說有人得到不幸的占卜結果。', `MaleText_loc7`='He oído que algunas personas tienen un destino atroz.', `FemaleText_loc1`='어떤 사람들을 정말 터무니없는 점괘가 나왔다고 하더라.', `FemaleText_loc4`='我听说，有些人算出来的命运很吓人。', `FemaleText_loc5`='我聽說有人得到不幸的占卜結果。', `FemaleText_loc7`='He oído que algunas personas tienen un destino atroz.' WHERE `ID`=53738;
