UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침 딱 맞춰 나타나셨군요. 지금은 얼라이언스 병사라면 누구나 전투에 뛰어들어야 할 상황입니다.', `MaleText_loc4`='你出现的正是时候，朋友。我们需要每一个联盟士兵的力量。', `MaleText_loc5`='你出現的時間很剛好，朋友。我們需要每一名聯盟戰士的支援。', `MaleText_loc7`='Has escogido un buen momento para venir, $gamigo:amiga;. Necesitamos la ayuda de todos los soldados de la Alianza.' WHERE `ID`=53743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 한 건지는 모르겠지만, 어쨌든 저 호젠을 몰아내는 데 성공했습니다.$B$B정말 감사합니다.', `MaleText_loc4`='我不知道我们是怎么做到的，可我们确实抵挡住了那些猢狲。$B$B谢谢你，伙计。', `MaleText_loc5`='我不知道我們怎麼做到的，但我們成功擊退了那些猴人。$B$B多謝你了，兄弟。', `MaleText_loc7`='No sé cómo lo hemos conseguido, pero hemos echado a los hozen.$b$bGracias a ti, colega.' WHERE `ID`=53744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 단단히 먹으십시오!', `MaleText_loc4`='振作点！', `MaleText_loc5`='做好心理準備!', `MaleText_loc7`='¡Prepárate!' WHERE `ID`=53745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 나아지고 있습니다, $n 님. 이제 적의 공격이 중단되었으니, 함선을 수리하고 집으로 돌아갈 준비를 할 수 있습니다.', `MaleText_loc4`='事情正在向有利于我们的方向转变，$n。既然攻击已经结束了，我们终于可以想办法修复飞船，并寻找回家的路了。', `MaleText_loc5`='事態變得越來越好了，$n。攻擊停止之後，我們終於有辦法開始修理船隻，找尋回家之路。', `MaleText_loc7`='La cosa mejora, $n. Ahora que los ataques han cesado, por fin podemos centrarnos en reparar nuestros barcos y volver a casa.' WHERE `ID`=53746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<전투 중 공격을 받아 의식을 잃은 것처럼 보입니다.>$B$B<가죽 가방을 단단히 붙잡고 있습니다.>', `MaleText_loc4`='<他似乎在战斗伊始就被打晕了。>$B$B<他手中紧紧抓着一只皮包。>', `MaleText_loc5`='<他看起來因戰鬥而不省人事。>$B$B<他手中緊緊握著一個皮袋子。>', `MaleText_loc7`='<Parece que ha permanecido inconsciente durante todo el combate.>$B$B<Se agazapa alrededor la bolsa de cuero.>' WHERE `ID`=53748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리가 마치 망치로 얻어맞은 듯이 울리지만, 그것만 빼면 괜찮소. 다른 선원들을 보면, 이것도 다행이라고 해야겠군.', `MaleText_loc4`='我的脑袋就像被榔头砸过一样，不过除此之外，我毫发无伤。我敢说，这一点已经比大部分船员都好多了。', `MaleText_loc5`='我的腦袋好像被鎚子砸了一下，但除此之外我都好。其他的船員就不見得這麼幸運了。', `MaleText_loc7`='Me siento como si me hubieran dado con un martillo en el cráneo, pero por lo demás estoy bien. Es más de lo que se puede decir de la mayor parte de la tripulación.' WHERE `ID`=53749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가방을 샅샅이 뒤집니다.', `MaleText_loc4`='翻看他的包裹。', `MaleText_loc5`='搜索他的袋子。', `MaleText_loc7`='Rebusca en su bolsa.', `FemaleText_loc1`='가방을 샅샅이 뒤집니다.', `FemaleText_loc4`='翻看他的包裹。', `FemaleText_loc5`='搜索他的袋子。', `FemaleText_loc7`='Rebusca en su bolsa.' WHERE `ID`=53750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 저놈은 처리했으니, 이제 네놈과 네 멍청한 친구들을 처치하면 되겠군. 음, 날 이렇게 오래 기다리게 하다니!', `FemaleText_loc4`='……解决了那东西，你和这群乌合之众就是我的下一个目标。唔，我还以为你们根本到不了这儿！', `FemaleText_loc5`='...搞定了那傢伙，現在輪到你和你這群笨拙的朋友了。嗯，我還以為你們到不了這裡呢!', `FemaleText_loc7`='... una vez liquidado eso, tú y ese rebaño de torpes amigos tuyos son los siguientes en mi lista. ¡Mmm, creí que nunca llegarías!' WHERE `ID`=53751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신비롭고 불가사의한 일들은 다크문 축제에서뿐만 아니라, 우리 주변에서도 항상 일어납니다. 우리가 평범한 일상에서 찾을 수 있는 불가사의한 물건들의 목록을 이 책에 정리해 놓았습니다. 그렇게 만들어진 이 다크문 모험가 도감은 세상의 불가사의한 것들을 분별해내도록 도와줄 겁니다.$b$b도감을 이용하면 평소에 있었는지조차도 몰랐던 물건들을 찾아낼 수 있을 겁니다. 과거에는 아무런 가치도 없었지만, 지금은 다른 이들이 찾아 헤매는 보물 말입니다.$b$b다크문 모험가 도감을 꼭 가지고 다니십시오. 그리고 신비한 물건들을 눈 크게 뜨고 찾아보시기 바랍니다.$b$b도감을 잃어버리면 우리를 찾아오십시오. 그러면 무료로 또 드리겠습니다.', `MaleText_loc4`='神秘与奇迹不仅仅存在于马戏团，我们身边每天都有奇迹发生。我们列出了一张表格，上面写着你在日常生活中可能遇到的奇迹。暗月冒险者指南能帮你找出这个世界上的奇迹。$b$b只要拥有了这本指南，你就能够发现未知的物品。你熟视无睹的东西可能就是别人孜孜以求的宝物。$b$b带上这本指南吧，用你眼睛去发现未解的谜团。$b$b如果你不小心丢失了指南，可以再来找我们，我们会免费送你一本新的。', `MaleText_loc5`='我們周遭每天都有驚奇神秘的事物，不僅僅是在暗月馬戲團這裡。我們整理了一份列表，是你可能平日就會碰上的驚奇事物。這本「暗月野地指南」能幫你尋找世界各地的驚奇事物。$b$b只要指南在手，你可能會碰上你前所未見的東西。有些過去你瞧不上眼的東西，說不定現在已經成為別人夢寐以求的寶物。$b$b帶著這本指南，睜大你的眼睛注意各種不尋常的東西。$b$b萬一你把指南搞丟了，來找我們，我們會免費再送你一本。', `MaleText_loc7`='Los misterios y las maravillas nos rodean cada día, no solo en la feria. Tenemos una lista de algunas de las maravillas que te puedes encontrar en tu día a día. La guía del aventurero de la Luna Negra te ayudará a visitar las maravillas del mundo.$b$BCon la guía en tu posesión, te encontrarás con cosas que nunca imaginarías. Cosas que no se supieron valorar en el pasado y que ahora son tesoros.$b$bTen tu guía a mano y mantén los ojos abiertos y atentos a los misterios.$b$bSi llegas a perder tu guía, ven a buscarnos y te conseguiremos otra gratis.', `FemaleText_loc1`='신비롭고 불가사의한 일들은 다크문 축제에서뿐만 아니라, 우리 주변에서도 항상 일어난답니다. 우리가 평범한 일상에서 찾을 수 있는 불가사의한 물건들의 목록을 이 책에 정리해 놓았어요. 그렇게 만들어진 이 다크문 모험가 도감은 세상의 불가사의한 것들을 분별해내도록 도와줄 거예요.$b$b도감을 이용하면 평소에 있었는지조차도 몰랐던 물건들을 찾아낼 수 있을 거예요. 과거에는 아무런 가치도 없었지만, 지금은 다른 이들이 찾아 헤매는 보물 말이죠.$b$b다크문 모험가 도감을 꼭 가지고 다니세요. 그리고 신비한 물건들을 눈 크게 뜨고 찾아보세요.$b$b도감을 잃어버리면 우리를 찾아오세요. 그러면 무료로 또 드린답니다.', `FemaleText_loc4`='神秘与奇迹不仅仅存在于马戏团，我们身边每天都有奇迹发生。我们列出了一张表格，上面写着你在日常生活中可能遇到的奇迹。暗月冒险者指南能帮你找出这个世界上的奇迹。$b$b只要拥有了这本指南，你就能够发现未知的物品。你熟视无睹的东西可能就是别人孜孜以求的宝物。$b$b带上这本指南吧，用你眼睛去发现未解的谜团。$b$b如果你不小心丢失了指南，可以再来找我们，我们会免费送你一本新的。', `FemaleText_loc5`='我們周遭每天都有驚奇神秘的事物，不僅僅是在暗月馬戲團這裡。我們整理了一份列表，是你可能平日就會碰上的驚奇事物。這本「暗月野地指南」能幫你尋找世界各地的驚奇事物。$b$b只要指南在手，你可能會碰上你前所未見的東西。有些過去你瞧不上眼的東西，說不定現在已經成為別人夢寐以求的寶物。$b$b帶著這本指南，睜大你的眼睛注意各種不尋常的東西。$b$b萬一你把指南搞丟了，來找我們，我們會免費再送你一本。', `FemaleText_loc7`='Los misterios y las maravillas nos rodean cada día, no solo en la feria. Tenemos una lista de algunas de las maravillas que te puedes encontrar en tu día a día. La guía del aventurero de la Luna Negra te ayudará a visitar las maravillas del mundo.$b$BCon la guía en tu posesión, te encontrarás con cosas que nunca imaginarías. Cosas que no se supieron valorar en el pasado y que ahora son tesoros.$b$bTen tu guía a mano y mantén los ojos abiertos y atentos a los misterios.$b$bSi llegas a perder tu guía, ven a buscarnos y te conseguiremos otra gratis.' WHERE `ID`=53754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 모험가 도감이 무엇입니까?', `MaleText_loc4`='暗月冒险者指南？', `MaleText_loc5`='暗月野地指南?', `MaleText_loc7`='¿Guía del aventurero de la Luna Negra?', `FemaleText_loc1`='다크문 모험가 도감이 뭔가요?', `FemaleText_loc4`='暗月冒险者指南？', `FemaleText_loc5`='暗月野地指南?', `FemaleText_loc7`='¿Guía del aventurero de la Luna Negra?' WHERE `ID`=53755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 모험가 도감 좀 다시 얻을 수 있습니까?', `MaleText_loc4`='能再给我一本暗月冒险者指南吗？', `MaleText_loc5`='我可以再要一本暗月野地指南嗎?', `MaleText_loc7`='¿Me puedes dar una guía del aventurero de la Luna Negra?', `FemaleText_loc1`='다크문 모험가 도감 좀 다시 얻을 수 있나요?', `FemaleText_loc4`='能再给我一本暗月冒险者指南吗？', `FemaleText_loc5`='我可以再要一本暗月野地指南嗎?', `FemaleText_loc7`='¿Me puedes dar una guía del aventurero de la Luna Negra?' WHERE `ID`=53756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 맞서는 모든 이에게 죽음을!', `MaleText_loc4`='敢于反抗我们的人都得死！', `MaleText_loc5`='阻擋我們的人都死吧!', `MaleText_loc7`='¡Muerte a todos nuestros oponentes!', `FemaleText_loc1`='우리에게 맞서는 모든 이에게 죽음을!', `FemaleText_loc4`='敢于反抗我们的人都得死！', `FemaleText_loc5`='阻擋我們的人都死吧!', `FemaleText_loc7`='¡Muerte a todos nuestros oponentes!' WHERE `ID`=53757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 있습니까?', `MaleText_loc4`='你有什么东西好卖的？', `MaleText_loc5`='你有什麼好買賣的?', `MaleText_loc7`='¿Qué vendes?', `FemaleText_loc1`='어떤 물건을 팔고 있나요?', `FemaleText_loc4`='你有什么东西好卖的？', `FemaleText_loc5`='你有什麼好買賣的?', `FemaleText_loc7`='¿Qué vendes?' WHERE `ID`=53758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 벌써 며칠째 이곳에 조난된 상태였어요. 사실 포기하기 직전이라고 해야겠지만, 그래도 사기를 북돋으려고 힘껏 애쓰고 있답니다.', `FemaleText_loc4`='我们已经在这里困守了好几天了。大家都已经濒临崩溃的边缘了，不过依然在努力保持斗志。', `FemaleText_loc5`='我們被困在這裡好幾天了。我們就快達到崩潰的臨界點，但還是嘗試著保持鬥志高昂。', `FemaleText_loc7`='Llevamos días perdidos aquí. Estamos al límite de nuestras fuerzas, pero intentamos mantener los ánimos.' WHERE `ID`=53760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원숭이들이 공격해 왔어요.$b$b맞서 싸워서 가까스로 막아냈지만, 놈들은 다시 돌아올 거예요. 더 많이...', `FemaleText_loc4`='那些……猴子……攻击我们……$b$b我击退了他们，可……他们很快就会回来……带着更多的人手……', `FemaleText_loc5`='那些...猴子...前來攻擊...$b$b我打退了他們，他們肯定...會帶更多人...回來...', `FemaleText_loc7`='Los... los monos... nos atacaron...$b$bConseguí espantarlos, pero... volverán... más...' WHERE `ID`=53764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다, 켈넌 요원. 이제 힘을 아껴라. 우리가 놈들을 쫓아내겠다.', `MaleText_loc4`='你做的很好，密探吉尔妮。现在你可以休息一下了……让我们来对付他们。', `MaleText_loc5`='你做得很好了，密探吉爾妮。好了，省省體力...我們會料理他們。', `MaleText_loc7`='Has hecho bien, agente Kearnen. Ahora conserva energías; nos defenderemos.', `FemaleText_loc1`='잘했다, 켈넌 요원. 이제 힘을 아껴라. 우리가 놈들을 쫓아내겠다.', `FemaleText_loc4`='你做的很好，密探吉尔妮。现在你可以休息一下了……让我们来对付他们。', `FemaleText_loc5`='你做得很好了，密探吉爾妮。好了，省省體力...我們會料理他們。', `FemaleText_loc7`='Has hecho bien, agente Kearnen. Ahora conserva energías; nos defenderemos.' WHERE `ID`=53765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 보려고 고개를 들지도 못하는 렐>$b$b<렐의 상태를 보면, 고개를 들 힘도 남아 있지 않은 것 같습니다.>', `MaleText_loc4`='<利尔没有抬头看你。>$b$b<从他的状态来看，你甚至怀疑他连抬头的力气都没有了。>', `MaleText_loc5`='<瑞爾沒有抬起頭來和你說話。>$b$b<按照他的狀態來看，你甚至不確定他有力氣移動他的腦袋。>', `MaleText_loc7`='<Rell no alza la vista para dirigirse a ti.>$b$b<A juzgar por su estado, no estás $gseguro:segura; de que pueda tener la energía suficiente para mover la cabeza.>' WHERE `ID`=53769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮으시면 계속 말씀해 주십시오.', `MaleText_loc4`='请继续你的报告。', `MaleText_loc5`='請你繼續報告。', `MaleText_loc7`='Sigue con tu informe, por favor.', `FemaleText_loc1`='괜찮으시면 계속 말씀해 주세요.', `FemaleText_loc4`='请继续你的报告。', `FemaleText_loc5`='請你繼續報告。', `FemaleText_loc7`='Sigue con tu informe, por favor.' WHERE `ID`=53770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 만들거나 부술 게 있나요? 떼어 버리거나 납땜할 거는요? 쪼개거나 수리할 거? 그렇다면 최고의 기계공학자를 제대로 찾아오신 거예요.', `MaleText_loc4`='你是想要建造东西还是拆除东西？拆卸东西还是组装东西？破坏东西还是修补东西？如果是的话，那你就来对地方了。', `MaleText_loc5`='你需要打造或打爛什麼玩意?拆除或焊接什麼玩意?撬開或修補什麼玩意?你找對技師了。', `MaleText_loc7`='¿Quieres construir o romper algo? ¿Desmontarlo o soldarlo? ¿Desgarrarlo o coserlo? Has venido a ver al ingeniero adecuado.' WHERE `ID`=53772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 장로들은 세상 사람들과 이야기를 나누고, 조상님에게 간 이들을 반기려고 연초에 잠깐 들른다네.', `MaleText_loc4`='在新年的伊始，我们的先祖们会暂时降临，为生者指点迷津，并欢迎后来者加入他们的行列。', `MaleText_loc5`='在一年初始的時候，我們長者會短暫地來訪並提供生者建議，並歡迎那些加入先祖的人們。', `MaleText_loc7`='Al comenzar el año, los ancestros venimos de visita brevemente para ofrecer consejo a los vivos y dar la bienvenida a los que se han unido a nosotros.' WHERE `ID`=53773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우, 젠장, 젠장, 젠장...', `MaleText_loc4`='射击，射击，射击……', `MaleText_loc5`='啊慘了啊慘了啊慘了。', `MaleText_loc7`='Mecachis, no, no, no...' WHERE `ID`=53775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설리, 이야기를 계속하십시오.', `MaleText_loc4`='接着说，苏利。', `MaleText_loc5`='繼續說你的故事，蘇利。', `MaleText_loc7`='Sigue con tu historia, Sully.', `FemaleText_loc1`='설리, 이야기를 계속하세요.', `FemaleText_loc4`='接着说，苏利。', `FemaleText_loc5`='繼續說你的故事，蘇利。', `FemaleText_loc7`='Sigue con tu historia, Sully.' WHERE `ID`=53777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 조각상의 겉모습은 마치 살아있는 것 같습니다. 얼굴에는 공포의 표정이 서린 채 굳어 있습니다.$b$b하지만 신과 닮지는 않았습니다.', `MaleText_loc4`='这座青玉雕像栩栩如生，面部表情十分惊恐。$b$B不过，看上去并不像阿信。', `MaleText_loc5`='這些玉像的姿態極度栩栩如生，轉瞬間的恐懼表情凝結在臉上。$b$b但裡面沒有小新。', `MaleText_loc7`='Las facciones de esta estatua de jade son increíblemente realistas. La expresión del rostro es una mueca de terror.$b$bSin embargo, no se parece a Shin.', `FemaleText_loc1`='비취 조각상의 겉모습은 마치 살아있는 것 같습니다. 얼굴에는 공포의 표정이 서린 채 굳어 있습니다.$b$b하지만 신과 닮지는 않았습니다.', `FemaleText_loc4`='这座青玉雕像栩栩如生，面部表情十分惊恐。$b$B不过，看上去并不像阿信。', `FemaleText_loc5`='這些玉像的姿態極度栩栩如生，轉瞬間的恐懼表情凝結在臉上。$b$b但裡面沒有小新。', `FemaleText_loc7`='Las facciones de esta estatua de jade son increíblemente realistas. La expresión del rostro es una mueca de terror.$b$bSin embargo, no se parece a Shin.' WHERE `ID`=53783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상 조사', `MaleText_loc4`='检查雕像', `MaleText_loc5`='檢視玉像。', `MaleText_loc7`='Examina la estatua.', `FemaleText_loc1`='조각상 조사', `FemaleText_loc4`='检查雕像', `FemaleText_loc5`='檢視玉像。', `FemaleText_loc7`='Examina la estatua.' WHERE `ID`=53784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만! 내 친구들을 멍청한 조각상으로 바꾸지 마!', `FemaleText_loc4`='住手！你休想把我的朋友们变成可笑的雕像！', `FemaleText_loc5`='等等!不准你把我的朋友變成什麼蠢雕像!', `FemaleText_loc7`='¡Alto! ¡No convertirás a mis amigos en estúpidas estatuas!' WHERE `ID`=53786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_shaman_cleansespirit.blp:16|t스랄이 당신에게 |cFF00FFFF|Hspell:103550|h[영혼 정화]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_shaman_cleansespirit.blp:16|t萨尔对你施放了|cFF00FFFF|Hspell:103550|h[净化灵魂]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_shaman_cleansespirit.blp:16|t索爾施放了|cFF00FFFF|Hspell:103550|h[淨化靈魂]|h|r在你身上!', `MaleText_loc7`='|TInterfaceIconsability_shaman_cleansespirit.blp:16|t¡Thrall lanza |cFF00FFFF|Hspell:103550|h[Limpiar espíritu]|h|r sobre ti!' WHERE `ID`=53787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"SI: 7" 요원분들이 절 받아들여 주신 게 얼마나 기쁜지 몰라요.$b$b사실 저희는 편안한 호수를 떠나는 일이 많지 않거든요. 이번이 제가 지금까지 집을 떠났던 것 중에서 가장 멀리까지 가본 거예요.', `MaleText_loc4`='我很高兴这些“军情七处”的人愿意带上我。$b$b我们很少离开舒适的湖泊。这是我有生以来第一次离家这么远。', `MaleText_loc5`='我很高興這些「軍情七處」的傢伙決定帶我一起走。$b$b我們很少很少離開我們安逸的湖水住居。這是我離家最遠的一次。', `MaleText_loc7`='Me alegro de que esta gente del "IV:7" decidieran llevarme con ellos.$b$bNormalmente no solemos abandonar las comodidades de nuestro lago. Esto es lo más lejos que he estado nunca de mi casa.' WHERE `ID`=53788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루, 그 다음에 무슨 일이 있었니?', `MaleText_loc4`='接着出了什么事，小卢？', `MaleText_loc5`='後來發生了什麼事，小小盧?', `MaleText_loc7`='¿Qué pasó después, pequeño Lu?', `FemaleText_loc1`='루, 그 다음에 무슨 일이 있었니?', `FemaleText_loc4`='接着出了什么事，小卢？', `FemaleText_loc5`='後來發生了什麼事，小小盧?', `FemaleText_loc7`='¿Qué pasó después, pequeño Lu?' WHERE `ID`=53789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니? 내... 내 눈에 $r|1이;가; 보이는 건가? 구해줘서 정말 고맙습니다.', `MaleText_loc4`='什么？我看到的该不是……该不是个$r吧？谢谢你救了我。', `MaleText_loc5`='什麼?那是...我是看到一個$r了嗎?謝謝你來救我。', `MaleText_loc7`='¿Qué? ¿Es $gun:una; $r eso que veo? Gracias por rescatarme.' WHERE `ID`=53790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 생물의 몸통처럼 보이는 물체로, 다행히 그 특징이 아직 남아 있어 그림으로 남길 수 있습니다.', `MaleText_loc4`='幸运地是，你还是能辨别出一些细节，看上去似乎是某个生物的躯干。', `MaleText_loc5`='幸運的是，你還是認出了足夠的細節，幫你描繪出貌似某種生物軀體的形狀。', `MaleText_loc7`='Afortunadamente, aún puedes distinguir los detalles suficientes para esbozar lo que parece el torso de una criatura.' WHERE `ID`=53791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<일부만 남은 조각상을 그림으로 그립니다.>', `MaleText_loc4`='<绘出雕像碎片的草图。>', `MaleText_loc5`='<描繪出雕像的一部份。>', `MaleText_loc7`='<Crea un boceto del trozo de estatua.>', `FemaleText_loc1`='<일부만 남은 조각상을 그림으로 그립니다.>', `FemaleText_loc4`='<绘出雕像碎片的草图。>', `FemaleText_loc5`='<描繪出雕像的一部份。>', `FemaleText_loc7`='<Crea un boceto del trozo de estatua.>' WHERE `ID`=53792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상의 이 부분을 봐도, 팔이 달려 있었다는 사실밖에는 알 수 있는 점이 별로 없습니다.', `MaleText_loc4`='你从这个雕像残片上看不出什么来，除了它的主人是有手臂的这一点。', `MaleText_loc5`='這部份的雕像沒能給你什麼資訊，除了這東西有手之外...', `MaleText_loc7`='Esta sección de la estatua no te dice mucho; solo que el sujeto tenía brazos...' WHERE `ID`=53793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제가 열렸습니다!$b$b돈을 조금만 주시면 축제가 열리는 곳으로 순간이동 시켜 드리겠습니다.$b$b다크문 축제로 가시겠습니까?', `MaleText_loc4`='暗月马戏团开张啦！$b$b只要交纳少许费用，我就能把你传送到马戏团的入口。$b$b你想去吗？', `MaleText_loc5`='暗月馬戲團開了!$b$b只要一點費用，我就可以把你傳送到籌備區去。$b$b你想要去嗎?', `MaleText_loc7`='¡La Feria de la Luna Negra ya está abierta!$b$bPor un módico precio te puedo teletransportar a la zona de escala de la feria.$b$b¿Quieres ir?', `FemaleText_loc1`='다크문 축제가 열렸어요!$b$b돈을 조금만 주시면 축제가 열리는 곳으로 순간이동 시켜 드릴게요.$b$b다크문 축제로 가시겠어요?', `FemaleText_loc4`='暗月马戏团开张啦！$b$b只要交纳少许费用，我就能把你传送到马戏团的入口。$b$b你想去吗？', `FemaleText_loc5`='暗月馬戲團開了!$b$b只要一點費用，我就可以把你傳送到籌備區去。$b$b你想要去嗎?', `FemaleText_loc7`='¡La Feria de la Luna Negra ya está abierta!$b$bPor un módico precio te puedo teletransportar a la zona de escala de la feria.$b$b¿Quieres ir?' WHERE `ID`=53794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상의 어깨 부분은 나머지 부분과 달리 상당히 위협적으로 보입니다. 이 존재는 매우 강력한 생물이었음이 틀림 없습니다!$b$b성격이 좋은 존재였으면 좋겠습니다. 혹시 그렇지 않았다면, 이미 멸종했을 겁니다!$b$b아니, 그러길 바랄 뿐입니다...', `MaleText_loc4`='相比它的其他部分，雕像的肩部看上去十分威武。它的主人一定是个强大的生物！$b$b它或许是一个温和的家伙。如果不是的话，那它可能十分具有侵略性！$b$b我们只能祈祷……', `MaleText_loc5`='這雕像的肩膀看起來符合它其他的特徵，相當壯健。這顯然是種相當強大的生物!$b$b也許這是種個性溫和的生物。如果不是，或許它已經絕種了!$b$b每個人都有想像的權利...', `MaleText_loc7`='El hombro de la estatua parece muy imponente en comparación con el resto de sus rasgos. ¡Está claro que el sujeto era una criatura poderosa!$b$bA lo mejor tenía buen carácter. Y si no, ¡a lo mejor se ha extinguido!$b$bDe ilusión también se vive...' WHERE `ID`=53795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이방인을 좋아하지 않는다. 하지만 빚을 졌으니 이 정도는 해야겠지. 이번 일로 장로님들이 나를 벌하지 않으면 좋겠군.', `MaleText_loc4`='我的族人们不喜欢陌生人，可是，我欠你太多了。但愿长老们不会因此怪罪我。', `MaleText_loc5`='我的同胞不喜歡陌生人，但這是我欠你的。希望長者們不會因為這事懲罰我。', `MaleText_loc7`='A mi gente no le gustan los forasteros, pero esto te lo debo. Que los ancestros no me castiguen por este gesto.' WHERE `ID`=53796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사여! 용의 영혼은 네 것이 아니다. 포기해라. 그러면 목숨만은 건져서 돌아갈 수 있을 거다.', `MaleText_loc4`='萨满！巨龙之魂不属于你。现在放手，你还有机会活着离开这里。', `MaleText_loc5`='薩滿!巨龍之魂不屬於你。放棄吧，你也許還能全身而退。', `MaleText_loc7`='¡Chamán! El Alma de dragón no te pertenece. Devuélvela y tal vez salgas con vida.' WHERE `ID`=53797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 처치해라. 하지만 주술사는 산 채로 데려와야 한다!', `MaleText_loc4`='杀光他们，除了那个萨满。带他来见我！', `MaleText_loc5`='把薩滿帶來我這，其他全殺掉!', `MaleText_loc7`='¡Destrúyanlos a todos, pero tráiganme al chamán!' WHERE `ID`=53798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이냐, 얘들아?', `FemaleText_loc4`='你好啊，孩子。', `FemaleText_loc5`='如何，小朋友?', `FemaleText_loc7`='¿Sí, hijos míos?' WHERE `ID`=53799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 좀 도와주실래요? 친구가 다쳤거든요.', `MaleText_loc4`='你能帮帮我们吗？我们的朋友受伤了。', `MaleText_loc5`='你能幫我們嗎?我們的朋友受傷了。', `MaleText_loc7`='¿Nos prestas tu ayuda? Nuestro compañero está herido.', `FemaleText_loc1`='우릴 좀 도와주실래요? 친구가 다쳤거든요.', `FemaleText_loc4`='你能帮帮我们吗？我们的朋友受伤了。', `FemaleText_loc5`='你能幫我們嗎?我們的朋友受傷了。', `FemaleText_loc7`='¿Nos prestas tu ayuda? Nuestro compañero está herido.' WHERE `ID`=53800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 조각상의 겉모습은 마치 살아있는 것만 같습니다. 공포의 표정이 서린 채 굳어 있습니다.', `MaleText_loc4`='这座青玉雕像栩栩如生，面部表情十分惊恐。', `MaleText_loc5`='這些玉像的姿態極度栩栩如生，恐懼的表情凝結在臉上。', `MaleText_loc7`='Las facciones de esta estatua de jade son increíblemente realistas. La expresión del rostro es una mueca de terror.', `FemaleText_loc1`='비취 조각상의 겉모습은 마치 살아있는 것만 같습니다. 공포의 표정이 서린 채 굳어 있습니다.', `FemaleText_loc4`='这座青玉雕像栩栩如生，面部表情十分惊恐。', `FemaleText_loc5`='這些玉像的姿態極度栩栩如生，恐懼的表情凝結在臉上。', `FemaleText_loc7`='Las facciones de esta estatua de jade son increíblemente realistas. La expresión del rostro es una mueca de terror.' WHERE `ID`=53801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상은 안 윈드퍼가 당신에게 설명한 신의 모습과 닮지 않았습니다.', `MaleText_loc4`='这座雕像与安·风裘向你描述的阿信的容貌并不相似。', `MaleText_loc5`='這雕像的樣子不符合安·風毛所描述的小新。', `MaleText_loc7`='Esta estatua no se corresponde con la descripción de Shin que te ha dado An Pelaje Recio.', `FemaleText_loc1`='이 조각상은 안 윈드퍼가 당신에게 설명한 신의 모습과 닮지 않았습니다.', `FemaleText_loc4`='这座雕像与安·风裘向你描述的阿信的容貌并不相似。', `FemaleText_loc5`='這雕像的樣子不符合安·風毛所描述的小新。', `FemaleText_loc7`='Esta estatua no se corresponde con la descripción de Shin que te ha dado An Pelaje Recio.' WHERE `ID`=53802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 독 안에 든 쥐다, 주술사여.', `MaleText_loc4`='你无路可逃了，萨满。', `MaleText_loc5`='薩滿，你哪都別想去。', `MaleText_loc7`='No irás a ninguna parte, chamán.' WHERE `ID`=53803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님! 다크문 축제에 오신 것을 환영합니다!', `MaleText_loc4`='欢迎光临暗月马戏团，$c！', `MaleText_loc5`='歡迎來到暗月馬戲團，$c!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra, $c!', `FemaleText_loc1`='$c님! 다크문 축제에 오신 것을 환영해요!', `FemaleText_loc4`='欢迎光临暗月马戏团，$c！', `FemaleText_loc5`='歡迎來到暗月馬戲團，$c!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra, $c!' WHERE `ID`=53804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제에 오신 것을 환영합니다!', `MaleText_loc4`='欢迎光临暗月马戏团！', `MaleText_loc5`='歡迎來到暗月馬戲團!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra!', `FemaleText_loc1`='다크문 축제에 오신 것을 환영해요!', `FemaleText_loc4`='欢迎光临暗月马戏团！', `FemaleText_loc5`='歡迎來到暗月馬戲團!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la Feria de la Luna Negra!' WHERE `ID`=53805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영합니다!', `MaleText_loc4`='欢迎！', `MaleText_loc5`='歡迎!', `MaleText_loc7`='¡$gBienvenido:Bienvenida;!', `FemaleText_loc1`='환영해요!', `FemaleText_loc4`='欢迎！', `FemaleText_loc5`='歡迎!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida;!' WHERE `ID`=53806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다랗고 무시무시한 가면을 얼굴에 쓴 것 같습니다...', `MaleText_loc4`='但愿它脸上那个又大又恐怖的面具只是面具而已……', `MaleText_loc5`='也許它臉上的只是個又大又恐怖的面具...', `MaleText_loc7`='A lo mejor no es más que una máscara grande y espeluznante...' WHERE `ID`=53807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다!', `MaleText_loc4`='欢迎！', `MaleText_loc5`='你好!', `MaleText_loc7`='¡Saludos!', `FemaleText_loc1`='반가워요!', `FemaleText_loc4`='欢迎！', `FemaleText_loc5`='你好!', `FemaleText_loc7`='¡Saludos!' WHERE `ID`=53808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험을 준비하십시오!', `MaleText_loc4`='做好冒险的准备吧！', `MaleText_loc5`='準備進行冒險嘍!', `MaleText_loc7`='¡Prepárate para la aventura!', `FemaleText_loc1`='모험을 준비하세요!', `FemaleText_loc4`='做好冒险的准备吧！', `FemaleText_loc5`='準備進行冒險嘍!', `FemaleText_loc7`='¡Prepárate para la aventura!' WHERE `ID`=53809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라. 사부 그린포우는 이 땅 방방곡곡에 옥권의 수도사로 이름을 떨쳤다.$b$b뛰어난 솜씨와 확고한 의지, 놀라운 기를 바탕으로 적을 비취 조각상으로 변화시키는 비취의 일격을 완성했다.$b$b그의 영웅적인 활약과 희생 덕분에 비취 숲은 최악의 위기를 극복할 수 있었고, 이 세계에는 그와 같은 위대한 존재는 두 번 다시 나타나지 않으리라.$b$b이 조각상은 영원히 이곳에 서서, 평화에 필요한 대가를 모두에게 알리고 그의 희생을 영원히 기리는 상징이 되리라.', `MaleText_loc4`='看，绿爪大师，他就是这片土地上远近闻名的玉拳武僧。$b$b通过高超的武艺、坚定的意志和强大的气，他创出了一种名叫“碎玉打击”的绝招，能将敌人直接变成玉雕。$b$b是他的英勇与献身精神，在危急时刻拯救了翡翠林，在这个世界上再也找不到像他这样的人了。$b$b愿这座永不倒下的雕像能不断提醒人们和平是多么来之不易，愿他的牺牲将被人们永远铭记。', `MaleText_loc5`='看吶，綠爪大師，在這片土地上聲名遠播的玉拳武僧。$b$b他將技巧、專注和氣功融會貫通成一項名為化玉擊的驚天絕招。這種攻擊能將敵人轉化為玉。$b$b他的英勇與犧牲拯救了翠玉林的危機，而像他這樣的高手也從此在世上絕跡。$b$b願這座雕像能幫助我們永遠記得和平的代價，願他的犧牲永不被忘記。', `MaleText_loc7`='Observa al maestro Zarpa Verde, conocido en todo el continente como el Monje del Puño de Jade.$b$bA través de la habilidad, la determinación y el chi, consiguió dominar el estilo actualmente conocido como el terrorífico Golpe de Jade; un ataque que transforma a los enemigos en estatuas de jade.$b$bFueron su heroísmo y su sacrificio los que salvaron al Bosque de Jade en momentos de gran necesidad, y este mundo no conocerá a nadie que llegue a su nivel.$b$bEsta estatua se alzará hasta el fin de los días para recordarnos cuál es el precio de la paz y para que no olvidemos jamás su sacrificio.' WHERE `ID`=53810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 고통 받을 때면 정령이 가장 먼저 그 흉조를 느낀다네. 정령들이 사원을 떠나 원초적인 본능에 굴복하면, 현명한 판다렌은 경계를 하지.', `MaleText_loc4`='当大地遭受苦难时，元素之灵们首先察觉到了凶兆。当元素之灵离开五晨寺，各按本能行事时，睿智的熊猫人发现了端倪。', `MaleText_loc5`='這塊土地正在受苦，而元素之靈們是最先感受到這股浪潮的。當元素之靈們順從本性離開寺廟，睿智的熊貓人會聆聽其中的訊息。', `MaleText_loc7`='Cuando la tierra llora, los espíritus son los primeros en sentir su dolor. Cuando abandonan el templo y se refugian en sus instintos más primitivos, el pandaren sabio presta atención.' WHERE `ID`=53811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령을 돌보고 다시 우리에게 데려오면 땅을 치유하고, 나아가 눈앞에 닥친 더 큰 위험을 이해할 수 있지.', `MaleText_loc4`='只有关注并迎回元素之灵，我们才能治愈这片土地，并真正了解目前最大的危机。', `MaleText_loc5`='照料了元素之靈並將他們帶回身邊之後，我們就能治療這片土地，並進一步了解即將到來的重大威脅。', `MaleText_loc7`='Si nos interesamos por los espíritus y los traemos de vuelta con nosotros, podemos curar la tierra y llegar a entender las grandes amenazas que están por llegar.' WHERE `ID`=53812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제에 오신 분들은 모두 주목하십시오! 곧 다크문 사투를 시작합니다! 잠시 후 사투장 가운데에 상품이 든 상자가 나타날 겁니다!', `MaleText_loc4`='各位游客请注意了！暗月死斗大赛就要开始了！奖品宝箱即将出现在竞技场中央！', `MaleText_loc5`='暗月馬戲團的遊客，仔細注意囉!暗月死鬥即將開始!再過一會兒，獎品寶箱就會出現在死鬥場的正中央!', `MaleText_loc7`='¡Atención, visitantes de la feria! ¡El combate a muerte de la Feria de la Luna Negra va a empezar! ¡En unos momentos pondré el cofre del premio en el centro de la arena!' WHERE `ID`=53813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 사투를 시작하겠습니다!', `MaleText_loc4`='暗月死斗大赛开始！', `MaleText_loc5`='讓死鬥開始吧!', `MaleText_loc7`='¡Que comience el combate a muerte de la Feria de la Luna Negra!' WHERE `ID`=53814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근자에 네 정령이 모두 사원을 떠나 셴진 수 각지로 뿔뿔이 흩어졌다네. 땅이 괴로워하고 있다네.', `MaleText_loc4`='最近，四位元素之灵都离开了五晨寺，藏身于神真子的各个角落。大地因此承受了苦难。', `MaleText_loc5`='最近，四名元素之靈離開寺廟並流落到神真子的各處。這片土地正在受苦。', `MaleText_loc7`='Muy recientemente, nuestros cuatro espíritus abandonaron el templo y se repartieron por las distintas zonas de Shen-zin Su. La tierra sufre.' WHERE `ID`=53815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 수련이 곧 쓸모가 닿을 걸세, 젊은 $c|1이여;여;. 이제 가서 배움을 계속하게.', `MaleText_loc4`='你的训练很快就会发挥作用的，年轻的$c。现在继续你的学习吧。', `MaleText_loc5`='你的訓練很快就會派上用場，年輕的$c。去吧，繼續你們的課程。', `MaleText_loc7`='Pronto pondrás en práctica tu entrenamiento, joven $c. Ahora ve y continúa con tus lecciones.' WHERE `ID`=53816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 대지의 위상 자리를 이어받을 생각을 하다니, 어리석구나, 주술사여!', `MaleText_loc4`='你以为自己能取代大地守护者的地位吗，萨满？愚不可及！', `MaleText_loc5`='如果你真認為你能成為大地守護者，就太天真了，薩滿!', `MaleText_loc7`='¡Estás loco si crees que vas a ocupar el lugar del Aspecto de la Tierra, chamán!' WHERE `ID`=53818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 일이 벌어지든, 우리는 이곳에서의 임무에 집중해야 해요.', `FemaleText_loc4`='无论发生了什么事——我们都必须专注于我们来的目标。', `FemaleText_loc5`='不管發生什麼事，我們都必須專注於眼前的目標。', `FemaleText_loc7`='Pase lo que pase, debemos centrarnos en nuestros objetivos.' WHERE `ID`=53819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 보고를 듣고 싶습니다, 켈넌 요원님.', `MaleText_loc4`='让我听听你其余的报告，密探吉尔妮。', `MaleText_loc5`='讓我聽聽剩下的部份，吉爾妮探員。', `MaleText_loc7`='Quiero escuchar el resto de tu informe, agente Kearnen.', `FemaleText_loc1`='나머지 보고를 듣고 싶어요, 켈넌 요원님.', `FemaleText_loc4`='让我听听你其他的报告，密探吉尔妮。', `FemaleText_loc5`='讓我聽聽剩下的部份，吉爾妮探員。', `FemaleText_loc7`='Quiero escuchar el resto de tu informe, agente Kearnen.' WHERE `ID`=53820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 우릴 막을 순 없다!', `MaleText_loc4`='没人能阻挡我们前进。', `MaleText_loc5`='凡擋我者死。', `MaleText_loc7`='¡No dejes que se crucen por nuestro camino!' WHERE `ID`=53821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 돌아왔군!', `MaleText_loc4`='暮光之锤的人冲过来了。', `MaleText_loc5`='暮光之錘回來了。', `MaleText_loc7`='El Martillo Crepuscular regresa.' WHERE `ID`=53822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='올테면 와 봐라!', `MaleText_loc4`='让他们来！', `MaleText_loc5`='有種來吧!', `MaleText_loc7`='¡Que vengan!' WHERE `ID`=53823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 보시는 건 다크문 사투장입니다. 다른 참가자들을 모두 때려눕히고 상품을 차지할 힘과 의지가 있습니까?$B$B격투는 매일 밤 자정에 시작되며, 그 후 3시간마다 한 번씩 열립니다.', `MaleText_loc4`='你眼前的就是暗月死斗场。你是否拥有强大的实力和坚定的意志，能够打败所有的参赛者并赢得大奖？

大赛将从午夜开始，每三小时举行一次。', `MaleText_loc5`='你這裡看到的是暗月死鬥場。你有力量和意志力來擊敗所有挑戰者，取得格鬥戰士的獎賞嗎?

每個回合從午夜開始，每三個小時一次。', `MaleText_loc7`='Aquí está la arena del combate a muerte de la Feria de la Luna Negra. ¿Tienes el poder y la voluntad para ganar a los participantes y conseguir el premio de los combatientes?

Los ataques comenzarán a media noche y después, cada tres horas.' WHERE `ID`=53824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딜 빠져나가시려고? 작은 도마뱀 녀석!', `FemaleText_loc4`='你觉得你能逃到哪儿去，小蜥蜴？', `FemaleText_loc5`='你以為你能去哪，小蜥蜴?', `FemaleText_loc7`='¿Adónde crees que vas, alimaña?' WHERE `ID`=53825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발각됐군! 싸울 준비를 하게. 이 협곡을 벗어나야 해!', `MaleText_loc4`='他们是怎么发现我们的？拿起武器——我们必须冲出这条峡谷！', `MaleText_loc5`='他們怎麼找到我們的?舉起武器!我們必須離開這個狹谷!', `MaleText_loc7`='¿Cómo nos encontraron? Preparen las armas, ¡tenemos que salir de este cañón!' WHERE `ID`=53826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 네 정령을 찾아서 사원으로 다시 데려와야 하네. 그럼으로써 땅을 치유하고, 땅이 고통스러워하는 진짜 이유를 이해할 수 있다네.', `MaleText_loc4`='我们必须找到元素之灵，并将他们带回寺中。只有这样，我们才能治愈大地，并发现真正的危机。', `MaleText_loc5`='我們必須尋找元素之靈，並讓他們在寺廟重聚。然後我們將能治癒這片土地，並了解讓他受苦的真正原因。', `MaleText_loc7`='Tenemos que buscar a los espíritus elementales y devolverlos al templo. De esta forma curaremos la tierra y llegaremos a descubrir lo que verdaderamente le aqueja.' WHERE `ID`=53827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 가까이 있는 정령은 불의 정령 후오일세. 내가 가장 아끼는 제자들을 찾아가서 후오에 대해 아는 게 있는지 알아 보게.', `MaleText_loc4`='最近的一位元素之灵是上古火灵燧焰。我要你去见见我的几个得意弟子，并向他们询问燧焰的消息。', `MaleText_loc5`='距離此地最近的元素之靈是霍。你要去找我最有天份的幾名弟子，了解他們對霍有什麼了解。', `MaleText_loc7`='El espíritu más cercano es Huo, el espíritu de la llama. Te reunirás con algunos de mis estudiantes más sobresalientes para adquirir sus conocimientos sobre Huo.' WHERE `ID`=53828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가게, $c|1이여;여;. 할 일이 많네.', `MaleText_loc4`='去吧，$c。你还有很多事情要做。', `MaleText_loc5`='去吧，$c。你有很多工作得做。', `MaleText_loc7`='Vete, $c. Tienes mucho que hacer.' WHERE `ID`=53829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설리, 이 나무가 어쩌다 이렇게 된 걸까?', `MaleText_loc4`='你猜这棵树是怎么回事，苏利？', `MaleText_loc5`='你覺得發生了什麼事，蘇利?', `MaleText_loc7`='¿Qué se supone que le pasó a este árbol, Sully?' WHERE `ID`=53831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 충돌했습니다, 대장. 잘린 것도 아니고, 쓰러진 것도 아닙니다.', `MaleText_loc4`='什么东西撞上它了，长官。不是砍倒的，也不是自己倒下的。', `MaleText_loc5`='有東西打中了它，長官。樹上沒有斧痕，也不是自然倒下。', `MaleText_loc7`='Algo lo golpeó, señor. Ni lo talaron ni se cayó solo.' WHERE `ID`=53832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 저건 뭐죠? 새 같은 건가요?', `MaleText_loc4`='那是什么，在那儿？是某种鸟吗？', `MaleText_loc5`='那邊那個是什麼玩意?是鳥嗎?', `MaleText_loc7`='¿Qué es eso de ahí? ¿Es un pájaro?' WHERE `ID`=53833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 비행기야. 잠깐... 비행기?!', `MaleText_loc4`='不是，那是一架飞机。等等……飞机！？', `MaleText_loc5`='不，那是飛機啦。等等...飛機!?', `MaleText_loc7`='No, es un avión. Espera, ¿UN AVIÓN?' WHERE `ID`=53834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버와 님의 비행기야! 모두 살아 있나 봐!', `MaleText_loc4`='那是安玻和尼姆的飞机！他们可能还活着！', `MaleText_loc5`='那是琥珀和妮姆的飛機!他們可能還活著!', `MaleText_loc7`='¡Es el avión de Amber y Nimm! ¡Podrían estar vivos!' WHERE `ID`=53835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버하고 님은 누구죠? 따라가야 하나요?', `MaleText_loc4`='谁是安玻和尼姆？我们要跟上他吗？', `MaleText_loc5`='琥珀和尼姆是誰?我們該跟上去嗎?', `MaleText_loc7`='¿Quiénes son Amber y Nimm? ¿Lo seguimos?' WHERE `ID`=53836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 숨을 쉽니다! 여기요! 말을 걸어 보세요!', `MaleText_loc4`='她还有呼吸，长官！快过来！跟她说说话！', `MaleText_loc5`='長官，她還有氣!快過來這裡!跟她說話!', `MaleText_loc7`='¡Aún respira, señor! ¡Ven! ¡Habla con ella!' WHERE `ID`=53837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주목! 호젠의 매복이다! 전투 준비!', `MaleText_loc4`='大家听好了！小心猢狲的伏击！', `MaleText_loc5`='大家注意!準備迎擊猴人的埋伏!', `MaleText_loc7`='¡Atención! ¡Prepárense para una emboscada hozen!' WHERE `ID`=53838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 루, 앰버를 지켜라! 설리, 비행기가 폭발하지 않게 해!', `MaleText_loc4`='小卢，保护好安玻！苏利，别让飞机在我们身边炸了！', `MaleText_loc5`='小小盧，看好琥珀!蘇利，別讓這架飛機爆炸了!', `MaleText_loc7`='Pequeño Lu, protege a Amber. Sully, ¡procura que ese avión no nos explote en la cara!' WHERE `ID`=53839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 내가 막겠다!', `MaleText_loc4`='我来尽力挡住他们！', `MaleText_loc5`='我會盡可能擋住他們!', `MaleText_loc7`='¡Los mantendré a raya todo lo que pueda!' WHERE `ID`=53840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "불의 정령 후오는 탐식이 심하기로 유명하지. 녀석은 부싯깃을 먹고 싶어하네. 바람의 손길에 깨어나고 싶어하네."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“上古火灵燧焰以贪吃著称。他想要吃柴火，还需要轻风的抚慰来振作精神。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「火焰之靈·霍是出了名的愛吃。他喜歡以火絨為食，他需要清風的鼓舞。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "Huo, el espíritu del fuego, es famoso por su hambre. Ansía yesca para comer. Necesita la caricia del viento para despertarse".' WHERE `ID`=53841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "그것을 찾아서 우쏭 마을 너머의 후오가 있는 동굴로 가져가면, 동굴 안에서 시험에 들게 될 걸세."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“如果你能找到这些东西，并把它们带去他在武松村外的洞穴，你就会在那里接受挑战。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「如果你找到這些東西，並且帶到洞穴將東西交給他，你將在裡頭面臨一項挑戰。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "Si encuentras estas cosas y se las llevas a su cueva, al otro lado del Aldea Wu-Song, tendrás que enfrentarte a un reto".' WHERE `ID`=53842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "시험을 통과하고 나면 후오 앞에 설 수 있을 걸세. 후오의 불꽃에 다시 불을 지피게. 자네의 영혼이 순수하다면 후오가 자네를 따라 나설 걸세."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“只有赢得挑战，你才能觐见燧焰。如果你的灵魂是纯洁的，那么在重新点燃他的火焰后，他就会跟你走。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「克服那項挑戰就能得到霍的恩澤。點燃祂的火焰，若你的心靈純潔，祂就會跟隨你。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "Supera ese reto y se te concederá el honor de contar con la presencia de Huo. Reaviva su llama y, si eres pura de espíritu, te seguirá".' WHERE `ID`=53843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "가게, 제자들이여. 곧 다시 만나게 될 걸세."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“去吧，孩子。我们很快就会重逢的。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「去吧，孩子。我們很快就會再次見面。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "Adelante, jóvenes. Nos volveremos a ver muy pronto".' WHERE `ID`=53844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 리 페이의 목소리가 울려 퍼집니다. "다시 보니 반갑구먼, 아이사. 자네가 공경심을 지니고 왔으니, 자네가 구하는 답을 주겠네."', `MaleText_loc4`='李飞大师的声音在耳畔回响，“很高兴再次见到你，艾莎。既然你怀着敬意而来，我也会给出你所追寻的答案。”', `MaleText_loc5`='李飛大師的聲音迴盪著:「很高興再見到你，艾莎。妳帶著敬意前來，我理當提供妳所追尋的答案。」', `MaleText_loc7`='Se oye la voz del maestro Li Fei: "Me alegro de volver a verte, Aysa. Has venido con respeto, por lo que te daré las respuestas que buscas".' WHERE `ID`=53845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲이 누구 거지?', `MaleText_loc4`='这片森林是谁的？', `MaleText_loc5`='這片林子是誰的?', `MaleText_loc7`='¿Kién manda en este boske?' WHERE `ID`=53847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 가장 큰 적이 누구지?', `MaleText_loc4`='谁才是我们最大的敌人？', `MaleText_loc5`='誰是我們最大的敵人?', `MaleText_loc7`='¿Kién es nuestro mayor enemigo?' WHERE `ID`=53848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐, 멍청이들 같으니. 저 물가에 있는 놈들이야!', `MaleText_loc4`='不对，蠢货！是海滩上的那些家伙！', `MaleText_loc5`='不，蠢材!是海灘邊的那些!', `MaleText_loc7`='¡No, imbéciles! ¡Los tipos de la playa!' WHERE `ID`=53849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 꼬리 없는 민둥살 겁쟁이들이 우리 숲의 나무를 자르고, 우리 형제들을 해치는 걸 보고만 있을 거야?', `MaleText_loc4`='难道我们要看着这些不长尾巴的软蛋砍伐我们的树林，杀害我们的同胞手足吗？', `MaleText_loc5`='我們要放任那些軟皮膚、沒尾巴的懦夫砍伐我們的森林，殘殺我們部族的兄弟嗎?', `MaleText_loc7`='¿Vamos a dejar ke esos kobardes pieles suaves sin kola talen nuestro boske y maten a nuestros hermanos?' WHERE `ID`=53850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 다시 말해줄게... 바로 우리가! 이 숲에서 가장 강한 존재야! 숲의 제왕이라고! 적을 두려움에 떨게 할 죽음의 신!', `MaleText_loc4`='我要提醒你们……我们才是这片森林里最强的存在。我们是森林之王！我们是敌人的死神！', `MaleText_loc5`='那我提醒你...「我們」才是林子裡最強的。我們是樹上的王!我們是敵人的死神!', `MaleText_loc7`='Os lo rekordaré... NOSOTROS somos los más fuertes en este boske. ¡Somos los reyes de los árboles! ¡Somos la muerte de nuestros enemigos!' WHERE `ID`=53851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 그림리어 부족을 깔볼 수 있는 자는 없어. 우리 부족이 피와 승리를 맛볼 시간이야!', `MaleText_loc4`='谁也别想挑战恐目部族。现在，该是我们品尝鲜血与胜利的时刻了！', `MaleText_loc5`='沒有人能欺負嚴睨部族。是時候讓我們嚐嚐鮮血與勝利的滋味了!', `MaleText_loc7`='Nadie amenaza a la tribu Vista Vil. ¡Es hora de ke nuestro klan pruebe la sangre y la viktoria!' WHERE `ID`=53852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴하라! 파괴! 파괴하라!', `MaleText_loc4`='复仇！复仇！复仇！', `MaleText_loc5`='掠奪!掠奪!掠奪!', `MaleText_loc7`='¡Sakear! ¡Sakear! ¡Sakear!' WHERE `ID`=53853;
