UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s|1이;가; |cFFFF0000|Hspell:103678|h[선의 물결]|h|r을 소환합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s召唤出了|cFFFF0000|Hspell:103678|h[善德之潮]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s召喚了一股|cFFFF0000|Hspell:103678|h[美德浪潮]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_vehicle_sonicshockwave.blp:20|t%s invoca una |cFFFF0000|Hspell:103678|h[Ola de virtud]|h|r.' WHERE `ID`=53877;
