UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 왕겁쟁이라고 놀리다니, 안은 정말 못됐어요. 전 그런 말을 듣고 도망칠 판다렌이 아니라고요.', `MaleText_loc4`='安这个刻薄鬼，故意说我没胆子。而我是从不逃避挑衅的。', `MaleText_loc5`='安用加倍賭注的猴人挑戰來激我時顯得很惡毒。但我不打算逃避一次挑戰。', `MaleText_loc7`='An fue una bellaca cuando me retó a llamar a la puerta de la bruja. Pero no podía resistirme a un desafío.' WHERE `ID`=53880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮니?', `MaleText_loc4`='你还好吗？', `MaleText_loc5`='你還好嗎?', `MaleText_loc7`='¿Estás bien?', `FemaleText_loc1`='괜찮니?', `FemaleText_loc4`='你还好吗？', `FemaleText_loc5`='你還好嗎?', `FemaleText_loc7`='¿Estás bien?' WHERE `ID`=53881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설리, 꼬마 루, 작전 변경이다. 앰버를 야영지로 데려가야 한다.', `MaleText_loc4`='苏利，小卢，计划有变。我们要把安玻送回营地去。', `MaleText_loc5`='蘇利，小小盧，計畫改變。我們得將琥珀送回主營地。', `MaleText_loc7`='Sully, pequeño Lu, los planes han cambiado. Hay que llevar a Amber al campamento principal.' WHERE `ID`=53882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괜찮아요. 저도 함께 갈게요.', `FemaleText_loc4`='没那个必要。我会跟着你们的。', `FemaleText_loc5`='不必了，我會跟你們一起去。', `FemaleText_loc7`='No será necesario. Voy con ustedes.' WHERE `ID`=53883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 되는 소리! 죽을 뻔했잖아! 봐봐!', `MaleText_loc4`='你在开玩笑吧！你都快死了！看看你的样子！', `MaleText_loc5`='你在開玩笑吧!你都快死了!看看你自己!', `MaleText_loc7`='¿Pero estás loca? ¡Estás medio muerta! ¡Mírate!' WHERE `ID`=53884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아냐, 설리. 상처는 나을 거야. 지금은 하얀 싹을 찾아내야 해.', `FemaleText_loc4`='不，苏利。我的伤没事。现在，我们必须去找白卒。', `FemaleText_loc5`='不，蘇利，我的傷會痊癒的。眼前我們得先找到白棋。', `FemaleText_loc7`='No, Sully. Mis heridas sanarán. El objetivo ahora es encontrar al Peón Blanco.' WHERE `ID`=53885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하얀 싹이 뭔가요? 전 우리가 호젠을 공격하는 줄 알았는데요.', `MaleText_loc4`='白……白卒是什么？我还以为我们是来打猢狲的。', `MaleText_loc5`='什麼是白棋?我以為我們是在攻擊猴人。', `MaleText_loc7`='¿Qué es el Peón Blanco? Creí que atacábamos a los hozen.' WHERE `ID`=53886;
