UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 죽거나 저들이 죽는 걸세, $r. 오늘은 피를 보지 않고서는 끝나지 않을 게야.', `MaleText_loc4`='不是他们死，就是我们亡，$r。今天的战斗注定不死不休。', `MaleText_loc5`='不是他們死，就是我們亡，$r。今天的流血衝突已經無可避免。', `MaleText_loc7`='Son ellos o nosotros, $r. El día de hoy no acabará sin que se derrame sangre.' WHERE `ID`=53894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 호드의 일원을 만나니 기분이 좋군요.$b$b아니, 좋을 뻔했다고 할까요? 보시다시피, 지금 제 상태가 좀...', `MaleText_loc4`='啊，总算让我看见一个和善人了，伙计。$b$b你瞧，如果我能看见……那就好了……', `MaleText_loc5`='啊啊，終於看到個熟面孔。真好，老兄。$b$b應該說那樣一定很好，如果我...你知道的，如果我看得到的話...', `MaleText_loc7`='Aah, eh''taba deseando ver una cara conocida, colega.$b$bEn fin, si pudiera, ya sabes, ver...' WHERE `ID`=53895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s|1이;가; |cFFFF0000|Hspell:103780|h[황혼의 물결]|h|r을 소환합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s召唤出了|cFFFF0000|Hspell:103780|h[暮光之潮]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s召喚了一股|cFFFF0000|Hspell:103780|h[暮光浪潮]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightfire.blp:20|t¡%s invoca una |cFFFF0000|Hspell:103780|h[Ola del Crepúsculo]|h|r!' WHERE `ID`=53896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사령관님의 상태가 안 좋아. 잠깐 쉬어야겠어.', `FemaleText_loc4`='利尔的情况不妙。我们再停下休息一会儿。', `FemaleText_loc5`='瑞爾的狀態越來越糟了，我們得再次停下來休息。', `FemaleText_loc7`='El estado de Rell empeora. Debemos parar y descansar.' WHERE `ID`=53897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미시카만 여기 있었더라도, 바로 치료했을 텐데.', `MaleText_loc4`='要是米希卡在就好了。她很快就能治好他的。', `MaleText_loc5`='如果密西卡在這裡就好了，她一眨眼就可以治好他。', `MaleText_loc7`='Ojalá Mishka estuviera aquí. Lo curaría en un santiamén.' WHERE `ID`=53898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요원님들! 판다렌 오두막이에요. 판다렌은 우리 동맹인데...', `MaleText_loc4`='嘿，伙计们！这是熊猫人的小屋。熊猫人都是很友好的……', `MaleText_loc5`='探員們!這是個熊貓人小屋。熊貓人是朋友，他們也許會幫忙。', `MaleText_loc7`='¡Compañeros agentes! Miren, es una cabaña pandaren. Son nuestros aliados... A lo mejor pueden ayudarnos.' WHERE `ID`=53899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 생각이야, 루. 가서 누가 사는지 알아봐. 설리와 함께 가.', `FemaleText_loc4`='好主意，小卢。去看看是谁住在那里。把苏利也带上。', `FemaleText_loc5`='好主意，小小盧。去看看誰住在這裡。跟蘇利一起去吧。', `FemaleText_loc7`='Buena idea, pequeño Lu. Ve a ver quién vive ahí. Llévate a Sully.' WHERE `ID`=53900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양말이도!', `MaleText_loc4`='还有袜子！', `MaleText_loc5`='還有襪子!', `MaleText_loc7`='¡Y a Calcetines!' WHERE `ID`=53901;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래... 저 너구리도. 사령관님은 내가 보살필게.', `FemaleText_loc4`='没错……还有浣熊。我会照顾好指挥官的。', `FemaleText_loc5`='好啦...還有那隻浣熊。我會照顧我們的指揮官。', `FemaleText_loc7`='Sí, y al mapache. Yo cuidaré al Comandante.' WHERE `ID`=53902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<계속해서 고서를 읽어내려갑니다...>', `MaleText_loc4`='<继续读……>', `MaleText_loc5`='<繼續閱讀...>', `MaleText_loc7`='<Sigue leyendo...>', `FemaleText_loc1`='<계속해서 고서를 읽어내려갑니다...>', `FemaleText_loc4`='<继续读……>', `FemaleText_loc5`='<繼續閱讀...>', `FemaleText_loc7`='<Sigue leyendo...>' WHERE `ID`=53903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t%s|1이;가; |cFF006EFD|Hspell:103754|h[황혼 강림]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t%s开始施放|cFF006EFD|Hspell:103754|h[暮光乍现]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t%s開始施放|cFF006EFD|Hspell:103754|h[暮光頓悟]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_twilight.blp:20|t¡%s comienza a lanzar |cFF006EFD|Hspell:103754|h[Epifanía Crepuscular]|h|r!' WHERE `ID`=53904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신은 겁쟁이라는 말까지는 참아냈는데, 우리가 왕겁쟁이라고 부르니까 견디지 못하고 우리가 얘기한 대로 했어요.', `FemaleText_loc4`='阿信想要反悔，可我们都故意打赌说他肯定不敢去，他就没法反悔了。', `FemaleText_loc5`='小新本來想退出猴人挑戰，但我們加倍了賭注，他就沒辦法退出。', `FemaleText_loc7`='Shin intentó escaquearse de la apuesta hozen, pero entonces hicimos una doble apuesta hozen y de esa ya no se pudo escaquear.' WHERE `ID`=53905;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 아이들이, 제가 아니라 다른 아이들이 신에게 옥의 마녀 집 앞문을 두드려 보라고 했어요. 신은 그러지 않겠다고 했지만, 그러니까 다른 아이가, 제가 아니라 다른 아이가 겁쟁이라고 놀렸어요.$b$b그때도 신은 참았는데 다른 아이가, 제가 아니라고 맹세해요, 또 다른 아이가 왕겁쟁이라고 놀렸어요. 신도 왕겁쟁이라는 말은 견딜 수 없었어요.$b$b신이 가서 문을 두드렸는데, 그 뒤의 일은 보지 못했어요. 비취 괴물이 나타나서 우린 도망갔거든요.$b$b전 정말 그렇게까지 놀릴 생각은 아니었어요...', `FemaleText_loc4`='于是其他孩子，不是我，挑唆阿信去敲青玉巫婆的前门。他不肯去，结果有个人，不是我，故意说他肯定是没胆子。$b$b阿信想反悔，结果有个人，我发誓不是我，是别人在一旁煽风点火。阿信受了挑唆。$b$b他去敲了门，但我们没有看到发生了什么事。青玉怪物冲出来攻击我们，我们就跑了。$b$b我真不该去挑唆阿信的。', `FemaleText_loc5`='所以其他那些孩子，我不在內，打賭要激小新去敲玉巫婆的前門。他本來不想去，但後來有個人，不是我喔，用猴人挑戰激他去。$b$b小新想要退出，但後來一個真的不是我的某人又用加倍賭注的猴人大挑戰激他去。這下就算是小新也沒法退出了。$b$b他過去敲了門，但我們沒看見發生了什麼。玉怪獸跑出來追我們，我們全都跑了。$b$b我真不該那樣激小新的...', `FemaleText_loc7`='Así que los demás niños, yo no, apostaron a que Shin no se atrevería a llamar a la puerta de la Bruja de Jade. No quería, pero alguien, yo no, le hizo una apuesta hozen.$b$bShin se escaqueó de ella, pero alguien, juro que yo no, le hizo una doble apuesta hozen. Ni Shin puede escaquearse de una doble apuesta hozen.$b$bFue y llamó a la puerta, pero no vimos qué paso. Vinieron monstruos de jade y salimos corriendo.$b$bNo debería haber hecho la apuesta...' WHERE `ID`=53906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 이런, 젊은 친구.$B$B내 남편의 제단에 인사를 드리러 찾아왔나? 있잖아, 남편은 영웅이었어. 비취 세공과 전투의 달인이었지. 영원히 기억될 사람이라고 다들 그랬었지.$B$B내 조각상들이 마음에 들어? 난 하나하나 무척 세심하게 만든다고. 내 남편의 저승길에 동행하며 남편을 지켜주는 친구들이니까.', `FemaleText_loc4`='很好很好，一个年轻的访客。$B$b你是来祭扫我丈夫的神龛的吗？你知道，他可是个大英雄。一个玉雕大师，战斗高手。据说，他的名字会被人们永远铭记。$B$b你喜欢我的雕像吗？这些都是我用特殊方法制作的，只有最精良的作品，才能留下来陪伴和保护我的丈夫。', `FemaleText_loc5`='唉呀呀，年輕的訪客。$b$b你是來我丈夫的祠堂前表示敬意的嗎?你知道的，因為他是個英雄。玉石工藝和格鬥的大師。他們說他的名聲會永遠流傳。$b$b你喜歡我的雕像嗎?我特別用心打造了它們，留下最好的作品來陪伴並保護我的丈夫。', `FemaleText_loc7`='Buenas, joven visitante.$b$b¿Has venido a presentar tus respetos en el templo de mi marido? Era un héroe, ¿sabes? Un maestro de la artesanía del jade y de la lucha. Dijeron que lo recordarían para siempre.$b$b¿Te gustan mis estatuas? Las tallo con gran primor; solo las mejores son dignas de aportar compañía y protección a mi esposo.' WHERE `ID`=53907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신은 어디에 있습니까?', `MaleText_loc4`='阿信呢？', `MaleText_loc5`='小新呢?', `MaleText_loc7`='¿Dónde está Shin?', `FemaleText_loc1`='신은 어디에 있지요?', `FemaleText_loc4`='阿信呢？', `FemaleText_loc5`='小新呢?', `FemaleText_loc7`='¿Dónde está Shin?' WHERE `ID`=53908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요즘 들어 이 길을 따라 여행하는 이들이 많아져서 보기 좋구나. 내 남편이라면 널 좋아했을 거다. 우린 항상 아이를 갖고 싶어했으니까.', `FemaleText_loc4`='这年头还能有人关心赶路的单身旅客可真不容易。我丈夫一定会很喜欢你的。我们一直都想要几个孩子。', `FemaleText_loc5`='有這麼體貼的人在路上一起旅行真好。我丈夫會喜歡你的，我們一直想要孩子。', `FemaleText_loc7`='Me alegro de ver a una persona entregada por los caminos. A mi marido le habrías caído bien. Siempre quisimos tener hijos.' WHERE `ID`=53909;
