UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 데스윙의 부하들과 맞서 싸우는 것이 당신의 가장 큰 임무요. 하지만 더불어 우리 임무도 도와준다면 더 좋겠지.', `MaleText_loc4`='与死亡之翼的爪牙战斗是你当前的首要任务，$n。可如果你能再帮我们军团一个小忙的话，那就更好了。', `MaleText_loc5`='與死亡之翼的爪牙作戰是你最重要的事，$n。但如果你能幫我們軍團做這件小事，也是不無小補。', `MaleText_loc7`='La batalla contra los esbirros de Alamuerte es tu prioridad absoluta, $n. Pero si puedes ayudar a nuestro Vuelo con esta pequeña tarea, mucho mejor.' WHERE `ID`=53929;
