UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 약삭빠른 원숭이들이 갑자기 나타나 절 공격했어요.', `MaleText_loc4`='那些鬼鬼祟祟的猴子莫名其妙地伏击了我。', `MaleText_loc5`='那些鬼鬼祟祟的猴子憑空跑出來偷襲我。', `MaleText_loc7`='Esos monos traicioneros me tendieron una emboscada de repente.' WHERE `ID`=53943;
