UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신이 아니에요. 그래도 정말 살아있는 듯한 조각상이네요.', `FemaleText_loc4`='这个不是阿信。不过它看上去真是活灵活现。', `FemaleText_loc5`='那不是小新，不過它看起來超像真的。', `FemaleText_loc7`='Ese no es Shin. Pero es muy realista.' WHERE `ID`=53946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으이... 얼굴이 참 웃기네요.', `FemaleText_loc4`='呃。那个小鬼长得真滑稽。', `FemaleText_loc5`='噁，這小子的臉好怪。', `FemaleText_loc7`='¡Puaj! Ese cachorro pone una cara muy rara.' WHERE `ID`=53947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테일러 제독의 친구입니까? 그렇다면, 나중에 결투를 통해 당신의 힘을 시험해보고 싶습니다.', `MaleText_loc4`='你们是海军上将泰勒的朋友吗？如果是的话，我就要在稍后的战斗中试试你们的实力了。', `MaleText_loc5`='你是泰勒上將的朋友嗎?這樣的話，晚點我得試試你的身手。', `MaleText_loc7`='¿Tus amigos están con el almirante Taylor? Si es así, entonces debo poner a prueba tu fuerza en el combate más tarde.' WHERE `ID`=53948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 정령이 제 기도에 응해 줬군요. 감사합니다.', `MaleText_loc4`='水灵们回应了我的祈祷。谢谢你。', `MaleText_loc5`='水靈回應了我的祈禱。謝謝你。', `MaleText_loc7`='Los espíritus del agua han respondido a mis plegarias. Gracias.' WHERE `ID`=53949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 포기하려던 참이었습니다. 친구여, 감사합니다.', `MaleText_loc4`='我之前都已经绝望了，朋友。谢谢你。', `MaleText_loc5`='我本來已經放棄了希望，朋友。謝謝你。', `MaleText_loc7`='Había perdido la esperanza, $gamigo:amiga;. Gracias.' WHERE `ID`=53950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛것이 보이는 건가? 제가 정말 풀려난 건가요?', `MaleText_loc4`='我不是眼花了吧？我真的自由了？', `MaleText_loc5`='我不是看到幻覺了吧?我真的自由了?', `MaleText_loc7`='¿Me engañan mis ojos? ¿De verdad soy libre?' WHERE `ID`=53951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 살아남는군요. 모두 당신 덕분입니다.', `MaleText_loc4`='多亏了你，我又多活了一天。', `MaleText_loc5`='我活下來了，多謝你。', `MaleText_loc7`='Gracias a ti viviré un día más.' WHERE `ID`=53952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구출대 중의 한 분이신가요? 우린 이제 살 수 있나요?', `MaleText_loc4`='你是搜救队的成员吗？我们得救了吗？', `MaleText_loc5`='你是救援隊的一份子嗎?我們得救了嗎?', `MaleText_loc7`='¿Perteneces al equipo de rescate? ¿Estamos salvados?' WHERE `ID`=53953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 우릴 구하러 올 줄 알았습니다. 감사합니다, $c님!', `MaleText_loc4`='我就知道会有人来救我们的。谢谢你，$c！', `MaleText_loc5`='我就知道會有人來救我們。謝謝你，$c!', `MaleText_loc7`='Sabía que vendría alguien a rescatarnos. Gracias, $c.' WHERE `ID`=53954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $c님. 야영지까지는 제가 알아서 갈 수 있습니다.', `MaleText_loc4`='谢谢你，$c。我可以自己返回营地的。', `MaleText_loc5`='謝謝你，$c。我可以自己回到營地。', `MaleText_loc7`='Gracias, $c. Puedo volver al campamento por mi cuenta.' WHERE `ID`=53955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 제독님을 마치 동물처럼 가둬놨습니다. 제독님도 구출하십시오.', `MaleText_loc4`='他们把上将像畜生一样关了起来。请你把他也救出来吧。', `MaleText_loc5`='他們把上將像動物一樣地關起來。請一起解救他。', `MaleText_loc7`='Han encerrado al almirante como si fuera un animal. Sálvalo a él también.' WHERE `ID`=53956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 포로들을 고문하고 있습니다. 끔찍한 운명으로부터 절 구해주셔서 정말 감사합니다, $c님.', `MaleText_loc4`='猢狲都热衷于折磨俘虏。谢谢你，$c，是你帮我避免了那种悲惨的命运。', `MaleText_loc5`='猴人以虐待囚犯為樂。謝謝你，$c，你讓我免於恐怖的命運。', `MaleText_loc7`='Los hozen disfrutan torturando a sus prisioneros. Gracias, $c, por salvarme de un destino terrible.' WHERE `ID`=53957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 이곳에 남은 건 꺼지지 않는 불꽃뿐이구나. 커다란 분노가 느껴진다... 폭발 직전의 이글거리는 분노가. 부디 조심해라.', `MaleText_loc4`='这片圣地只剩下了不灭的烈焰。我能在这里感受到愤怒……炽热的怒火，难以抑制。小心点。', `MaleText_loc5`='這個神聖的地方只剩不滅的火焰。我感覺到極端的憤怒...一股沸騰，勉強才克制住的怒火。要小心。', `MaleText_loc7`='Las llamas imperecederas son lo único que queda de este lugar sagrado. Percibo mucha ira aquí... la rabia brota, sin límites. ¡Permanece en guardia!' WHERE `ID`=53958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 너... 영웅 같은 네 모습을 보니, 내 남편의 제단을 지키는... 조각상이 되면 어울리겠구나.', `FemaleText_loc4`='而你，有着英勇的品质。我丈夫的神龛……正需要像你这样出色的守卫。', `FemaleText_loc5`='而你，你有著英雄般的身段。我丈夫的祠堂需要...你的雕像來守衛。', `FemaleText_loc7`='Y tú, con tus facciones heroicas... El santuario de mi marido necesita guardianes de tu... estatura.' WHERE `ID`=53959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오!$b$b이렇게 피가 멈추질 않으니, 오래 버틸 수 없을 겁니다...', `MaleText_loc4`='快点，伙计！$b$b我就像个筛子一样在往外飙血，就在这！我的时间可不多了……', `MaleText_loc5`='快點，老兄!$b$b我的血都快流乾了!沒剩多少時間...', `MaleText_loc7`='¡Venga, colega!$b$b¡Tengo más agujeros que un colador! No me queda mucho tiempo...' WHERE `ID`=53960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진준 님, 저를 따라 오십시오. 가서 당신이... 잃어버린 것들을 찾아 봅시다.', `MaleText_loc4`='跟我来吧，金祖恩，我们要去找你丢失的……财物。', `MaleText_loc5`='跟我來，金浚，讓我們找到你失去的...東西。', `MaleText_loc7`='Ven conmigo, Zin''Jun. Vamos a buscar tus pertenencias... perdidas.', `FemaleText_loc1`='진준 님, 저를 따라 오세요. 가서 당신이... 잃어버린 것들을 찾아 봐요.', `FemaleText_loc4`='跟我来吧，金祖恩，我们要去找你丢失的……财物。', `FemaleText_loc5`='跟我來，金浚，讓我們找到你失去的...東西。', `FemaleText_loc7`='Ven conmigo, Zin''Jun. Vamos a buscar tus pertenencias... perdidas.' WHERE `ID`=53961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 가겠습니다...', `MaleText_loc4`='我马上就来，伙计……', `MaleText_loc5`='我與你同在，老兄...', `MaleText_loc7`='Enseguida voy, colega...' WHERE `ID`=53962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 해치웠어! 오그노카 록타르. 이제 끝내버리세!', `MaleText_loc4`='胜利在望了！Og’nor ka Lok’tar——让我们给他个了断！', `MaleText_loc5`='你就快打倒他了!(獸人語)迎接勝利 - 做個了斷吧!', `MaleText_loc7`='¡Casi lo tienen! Og’nor ka Lok’tar. ¡Acabemos con esto!' WHERE `ID`=53963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 안 돼... 놈들이 내 총에 대체 무슨 짓을 한 겁니까?!', `MaleText_loc4`='噢，不……他们对我的步枪干了什么，伙计！？', `MaleText_loc5`='啊，別這樣...他們對我的槍做了什麼，老兄!?', `MaleText_loc7`='Oh, no... ¿Qué le han hecho a mi rifle, colega?' WHERE `ID`=53964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾았군요! 제 눈썹 중 하나입니다. 출발이 나쁘지 않습니다!', `MaleText_loc4`='快看！这就是我被抢走眼镜片。虽然已经坏了，不过这是一个好的开始。', `MaleText_loc5`='喔看哪!我壞的那只眼睛，但是個好的開始!', `MaleText_loc7`='¡Vaya sueh''te! Ese es mi ojo malo, ¡pero es un buen comienzo!' WHERE `ID`=53965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요, 제 눈썹입니다! 이제 조상님들과 함께 안식에 들 수 있겠습니다...', `MaleText_loc4`='在那边，伙计。我的猎鹰之眼！我总算能安心地去见我的祖先们了……', `MaleText_loc5`='罩啊，老兄。我打獵的眼睛!我可以安心去見老祖宗了...', `MaleText_loc7`='Ahí eh''tá, colega. ¡Mi ojo de caza! Ya puedo deh''cansar en paz con mis anceh''tros...' WHERE `ID`=53966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭡니까? 놈들이 우리 벌름이를 죽였다고요?! 안 돼애애!', `MaleText_loc4`='什么，伙计？他们杀了老呼呼？！不！！', `MaleText_loc5`='你說啥，老兄?他們殺了我的老鼻煙?!不!', `MaleText_loc7`='¿Qué pasa, colega? ¿Han matado a Snuff? ¡Nooo!' WHERE `ID`=53967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 먼 길을 왔는데 너 따위가 날 막을쏘냐!', `MaleText_loc4`='我千里迢迢地赶来，绝不会让你拦下！', `MaleText_loc5`='我才不會讓你們這種程度的雜兵擋在這裡。', `MaleText_loc7`='¡No he llegado hasta aquí para que me detenga escoria como ustedes!' WHERE `ID`=53968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만. 이제 됐습니다. 저도 벌름이와 함께 떠나고 싶습니다...', `MaleText_loc4`='这就好，伙计。现在我可以去找呼呼了……', `MaleText_loc5`='這就行了，老兄。現在我可以和鼻煙一起去了...', `MaleText_loc7`='Ya eh''tá, colega. Ahora me voy con Snuff...' WHERE `ID`=53969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $p 님. 벌름이와 제가 당신의 앞길을 지켜보겠습니다.', `MaleText_loc4`='我们很感激你，$p。我们会保佑你的。', `MaleText_loc5`='我們感謝你，$p。我們會關照你的。', `MaleText_loc7`='Tienes nueh''tro agradecimiento, $p. Cuidaremos de ti.' WHERE `ID`=53970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아깝군.', `FemaleText_loc4`='真是浪费。', `FemaleText_loc5`='真浪費。', `FemaleText_loc7`='Qué desperdicio.' WHERE `ID`=53971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 찾으십니까?', `MaleText_loc4`='你在找什么？', `MaleText_loc5`='你在尋找什麼?', `MaleText_loc7`='¿Qué es lo que buscas?', `FemaleText_loc1`='뭘 찾으시나요?', `FemaleText_loc4`='你在找什么？', `FemaleText_loc5`='你在尋找什麼?', `FemaleText_loc7`='¿Qué es lo que buscas?' WHERE `ID`=53972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한판 붙읍시다!', `MaleText_loc4`='打我呀！', `MaleText_loc5`='跟我戰鬥!', `MaleText_loc7`='¡Lucha contra mí!', `FemaleText_loc1`='한판 붙읍시다!', `FemaleText_loc4`='打我呀！', `FemaleText_loc5`='跟我戰鬥!', `FemaleText_loc7`='¡Lucha contra mí!' WHERE `ID`=53973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다...', `MaleText_loc4`='非常好……', `MaleText_loc5`='非常好...', `MaleText_loc7`='Muy bien...', `FemaleText_loc1`='좋아요...', `FemaleText_loc4`='非常好……', `FemaleText_loc5`='非常好...', `FemaleText_loc7`='Muy bien...' WHERE `ID`=53977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합시다!', `MaleText_loc4`='让我们庆祝一下吧！', `MaleText_loc5`='我們來慶祝吧!', `MaleText_loc7`='¡Vamos a festejarlo!', `FemaleText_loc1`='축하하죠!', `FemaleText_loc4`='让我们庆祝一下吧！', `FemaleText_loc5`='我們來慶祝吧!', `FemaleText_loc7`='¡Vamos a festejarlo!' WHERE `ID`=53978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하의 시간은 지났습니다.', `MaleText_loc4`='庆祝时间已经过了。', `MaleText_loc5`='慶祝的時間結束了。', `MaleText_loc7`='El tiempo de fiestas ha terminado.', `FemaleText_loc1`='축하의 시간은 지났어요.', `FemaleText_loc4`='庆祝时间已经过了。', `FemaleText_loc5`='慶祝的時間結束了。', `FemaleText_loc7`='El tiempo de fiestas ha terminado.' WHERE `ID`=53979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Basta!', `FemaleText_loc1`='이제 그만!', `FemaleText_loc4`='够了！', `FemaleText_loc5`='夠了!', `FemaleText_loc7`='¡Basta!' WHERE `ID`=53980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<렐의 창백한 이마에 식은땀이 맺혀 있습니다. 상태가 그다지 좋아 보이지 않습니다.>', `MaleText_loc4`='<利尔的额头十分苍白，冷汗直流。他看起来非常不妙。>', `MaleText_loc5`='<瑞爾的前額蒼白，冒著一粒粒的汗珠。他看起來不太好。>', `MaleText_loc7`='<Rell tiene la frente pálida y empapada en sudor. Tiene muy mala cara.>' WHERE `ID`=53984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<렐은 얕은 숨을 힘겹게 쉬며, 계속해서 공허한 눈길로 바닥을 바라보고 있습니다.>', `MaleText_loc4`='<利尔一直茫然地盯着地板，呼吸困难。>', `MaleText_loc5`='<瑞爾繼續無神地瞪視著墊子。他的呼吸淺而粗重。>', `MaleText_loc7`='<Rell continúa fijando su vista inexpresiva en la alfombra. Su respiración es superficial y muestra claros signos de fatiga.>' WHERE `ID`=53985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 했네, 이제 이 친구를 살펴보지...', `MaleText_loc4`='干得好，让我们去看看我们的朋友……', `MaleText_loc5`='做得好。去看看我們的朋友吧..', `MaleText_loc7`='Bien hecho. Encarguémonos de nuestro amigo…' WHERE `ID`=53986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 비룡들이 곧 도착할 걸세. 먼저 갈 테니 준비되면 따라오게.', `MaleText_loc4`='其他的幼龙马上就到。我会飞在最前面，你们准备好了就跟上。', `MaleText_loc5`='其他飛龍應該很快就到了。我先飛走了，你們儘快趕上吧。', `MaleText_loc7`='El resto de los dracos deberían llegar en breve. Me adelantaré volando; alcáncenme cuando puedan.' WHERE `ID`=53987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='렐, 제발... 좀 쉬세요. 다음 일은 설리가 얘기할 거예요.', `FemaleText_loc4`='利尔，拜托……省点力气。苏利会把之后的事告诉$n。', `FemaleText_loc5`='瑞爾...拜託，省省力氣。蘇利可以告訴$n接著發生了什麼事。', `FemaleText_loc7`='Por favor, Rell, ahorra energías. Sully le contará lo que pasó después.' WHERE `ID`=53989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 몇 시간 동안 숲을 따라... 북쪽으로 이동하다가...', `MaleText_loc4`='我们一直往北，在森林里走了几个小时。', `MaleText_loc5`='我們向北穿越林子，走了好幾個小時。', `MaleText_loc7`='Llevábamos varias horas viajando por el bosque, hacia el norte.' WHERE `ID`=53990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하게 쓰러진 나무를 발견했네.', `MaleText_loc4`='我们在一棵倒得很蹊跷的树前停下。', `MaleText_loc5`='直到發現一棵倒下的怪樹。', `MaleText_loc7`='Nos detuvimos al encontrar un extraño árbol caído.' WHERE `ID`=53994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 될 일이 아니었네. 지금쯤 하얀 싹을 찾아내고, 나는 아이언포지에 돌아가 있었어야 해.', `MaleText_loc4`='计划出了些岔子，我们原本是要出来找白卒的。我这会儿早该回到铁炉堡了。', `MaleText_loc5`='一切都不對了。我們應該要找到白棋才對，我現在應該已經回到鐵爐堡了才對。', `MaleText_loc7`='No tenía que haber pasado así. Se suponía que íbamos a encontrar el peón blanco. A estas alturas debería estar de vuelta en Forjaz.' WHERE `ID`=53995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 일이 엉망진창이 되고 있네, $n. 이번 작전은 단순한 정찰 임무였는데!', `MaleText_loc4`='一切都搞砸了，$n。这原本只是一项简单的侦查任务。', `MaleText_loc5`='事情全都搞砸了，$n。這應該只是個簡單的偵查任務。', `MaleText_loc7`='Todo se ha ido al carajo, $n. Esto se suponía que iba a ser una simple misión de reconocimiento.' WHERE `ID`=53996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... <훌쩍>... 그 후의 일을 이야기할 자신이 없네! 꼬마 루야, 다음 이야기를 들려주렴.', `MaleText_loc4`='我……<吸鼻子>……我说不下去了！小卢，你来把之后发生的事告诉$n。', `MaleText_loc5`='我...<抽噎>...我恐怕沒辦法承受下一段!小小盧，告訴$n後來發生的事。', `MaleText_loc7`='Yo... <sollozo> Creo que no soy capaz de contar lo que pasó después. Cuéntaselo tú, pequeño Lu.' WHERE `ID`=53997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 요원들. 잘 들어라.', `MaleText_loc4`='好了，特工们。听好了。', `MaleText_loc5`='好了，密探們。聽好了。', `MaleText_loc7`='Muy bien, agentes. Atiendan.' WHERE `ID`=53998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으음... 저를 요원이라고 생각하시나 봐요.', `MaleText_loc4`='嗯……他管我叫特工！', `MaleText_loc5`='嗯...他認為我是個探員。', `MaleText_loc7`='Ooh... Me ha llamado agente...' WHERE `ID`=53999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 늦었으니, 밤을 지낼 야영지를 구축한다. 설리, 도끼 있나?', `MaleText_loc4`='天色已经晚了。我们该扎营了。苏利，你有斧子吗？', `MaleText_loc5`='天色晚了，我們該準備紮營過夜。蘇利，你有斧頭嗎?', `MaleText_loc7`='Se hace tarde. Hay que levantar el campamento. Sully, ¿tienes un hacha?' WHERE `ID`=54000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아뇨. 뭐, 하나 만들게요. 어디 보자... 나무 자르는 거요, 아니면 사람 자르는 거요?', `MaleText_loc4`='没有，不过我可以现做。我想想……你是要一把伐木斧呢，还是一把砍人斧？', `MaleText_loc5`='沒有，但我隨手就能造出一把。讓我想想...你是要砍木頭，還是要砍腦袋的斧頭呢?', `MaleText_loc7`='No, pero te hago una en un santiamén. A ver... ¿quieres un hacha de cortar árboles o de matar gente?' WHERE `ID`=54001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무 자르는 거. 루, 이 도끼로 땔감을 모아와.', `MaleText_loc4`='伐木斧。小卢，用这把斧头去砍点木柴。', `MaleText_loc5`='砍木頭的。小小盧，用它去收集生火的木材。', `MaleText_loc7`='De cortar árboles. Pequeño Lu, utiliza el hacha para recoger leña.' WHERE `ID`=54002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='是的長官!', `MaleText_loc7`='¡Sí, señor!' WHERE `ID`=54003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설리, 서쪽의 제단을 조사해라. 하얀 싹의 흔적이 있는지 찾아봐.', `MaleText_loc4`='苏利，去查看一下西面那些神龛，找找白卒的踪迹。', `MaleText_loc5`='蘇利。調查西邊的那些祠堂，搜索有關白棋的線索。', `MaleText_loc7`='Sully, investiga esos santuarios del oeste. Busca rastros del Peón Blanco.' WHERE `ID`=54004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버, 적당한 지점에서 설리를 엄호해라. 후방에서 다시 집합한다.', `MaleText_loc4`='安玻，去找个好位置，用火力掩护苏利。我们稍后回来汇合。', `MaleText_loc5`='琥珀，找個制高點，給蘇利火力支援。最後回到這裡集合。', `MaleText_loc7`='Amber, busca una buena posición y cubre a Sully. Nos volveremos a reunir aquí mismo.' WHERE `ID`=54005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 그럽죠!', `MaleText_loc4`='遵命，长官！', `MaleText_loc5`='收到，長官!', `MaleText_loc7`='¡Sí, señor!' WHERE `ID`=54006;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 대장님.', `FemaleText_loc4`='是，长官。', `FemaleText_loc5`='是的長官。', `FemaleText_loc7`='Sí, señor.' WHERE `ID`=54007;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설리, 이쪽이야! 적당한 곳을 봐 뒀어.', `FemaleText_loc4`='这边，苏利！我找到一个很好的地方。', `FemaleText_loc5`='這邊，蘇利!我找到最佳的制高點了。', `FemaleText_loc7`='¡Por aquí, Sully! Veo el escondite perfecto.' WHERE `ID`=54008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 그늘 속에 숨어 있을게. 문제가 생기면, 적에게 빛을 비춰. 그러면 내가 처리할게.', `FemaleText_loc4`='我就躲在这片阴影里。如果你遇到麻烦，就用灯光指出目标，我来对付他们。', `FemaleText_loc5`='我會躲在這邊的陰影裡。如果你遇到麻煩，對目標閃個光，我就會解決他們。', `FemaleText_loc7`='Yo me esconderé aquí, en las sombras. Si te metes en algún lío, ilumina al objetivo y yo me encargaré de él.' WHERE `ID`=54009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명중이야, 앰버!', `MaleText_loc4`='打得好，安玻！', `MaleText_loc5`='射得漂亮，琥珀!', `MaleText_loc7`='¡Buen disparo, Amber!' WHERE `ID`=54010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저격병이 날 지켜준다는 건 몰랐지?', `MaleText_loc4`='没想到我身边还有一个狙击手吧，嗯？', `MaleText_loc5`='沒想到我有個狙擊手罩著吧?', `MaleText_loc7`='¡Sorpresa! ¡Tengo una francotiradora en el equipo!' WHERE `ID`=54011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버는 빗맞히는 법이 없어. 대단해.', `MaleText_loc4`='我发誓，那个女人从来没有失手过。', `MaleText_loc5`='我發誓，那女人百發百中。', `MaleText_loc7`='En serio, esa mujer no falla nunca.' WHERE `ID`=54012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억할 것: 앰버를 적으로 돌리지 마라.', `MaleText_loc4`='我得提醒自己：绝对不要惹恼安玻。', `MaleText_loc5`='給自己的提醒:千萬別惹琥珀生氣。', `MaleText_loc7`='Nota mental: no hacer enfadar a Amber.' WHERE `ID`=54013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탕! 좋았어!', `MaleText_loc4`='砰！打得好！', `MaleText_loc5`='砰!射得好!', `MaleText_loc7`='¡Bum! ¡Muy buena!' WHERE `ID`=54014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 설리 님을 기습하겠다고? 응?', `MaleText_loc4`='想要偷袭老苏利，嗯？', `MaleText_loc5`='想偷襲老蘇利，是吧?', `MaleText_loc7`='Intentabas sorprender al viejo Sully, ¿eh?' WHERE `ID`=54015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버는 항상 미간을 맞추더라고.', `MaleText_loc4`='她每次都能一枪爆头。', `MaleText_loc5`='她總是正中眉心，彈無虛發。', `MaleText_loc7`='Entre ceja y ceja. No falla.' WHERE `ID`=54016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우엑... 피가 튀었네.', `MaleText_loc4`='呃……好恶心。', `MaleText_loc5`='噁...濺到我了。', `MaleText_loc7`='Puaj... Me salpicó.' WHERE `ID`=54017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 지금 상태가 좋지 않습니다, $n 님. 이 상처는... 그... 그래도 조금 더 견뎌 보겠습니다. 부디, 여기서 절 구해 주십시오.', `MaleText_loc4`='我的情况很糟糕，$n。我的伤……我会努力多坚持一会儿的。带我离开这儿，拜托了。', `MaleText_loc5`='我快不行了，$n。我的傷勢...我...我會試著撐久一點。請帶我離開這裡。', `MaleText_loc7`='No estoy en buena forma, $n. Mis heridas... I-intentaré aguantar un poco más. Sácame de aquí, te lo ruego.' WHERE `ID`=54018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 북쪽으로 가다가, 커다란 공터에서 멈춰 섰네.', `MaleText_loc4`='我们继续北上，一直走到这片空地附近。', `MaleText_loc5`='我們不斷向北，直到發現一片大空地。', `MaleText_loc7`='Seguíamos rumbo al norte cuando nos detuvimos en un gran claro.' WHERE `ID`=54019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤을 보낼 야영지를 세웠어. 렐은 각자에게 할 일을 나눠줬고.', `MaleText_loc4`='我们开始准备扎营过夜。利尔分派了任务。', `MaleText_loc5`='我們在此準備紮營過夜，瑞爾負責分配工作。', `MaleText_loc7`='Acampamos para pasar la noche. Rell repartió responsabilidades.' WHERE `ID`=54020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주머니 속에 낡은 조준경이 있었네. 그거면 충분했어.$b|TInterface\\Icons\\inv_misc_scopeb.blp:32|t$b', `MaleText_loc4`='我在口袋里找到个旧的步枪瞄准镜。这东西管用。$b|TInterface\\Icons\\inv_misc_scopeb.blp:32|t$b', `MaleText_loc5`='我剛好有個老來福槍瞄準鏡，就這麼辦吧。$b|TInterface\\Icons\\inv_misc_scopeb.blp:32|t$b', `MaleText_loc7`='Encontré una vieja mira de rifle en el bolsillo. Tendría que servir.$b|TInterfaceIconsinv_misc_scopeb.blp:32|t$b' WHERE `ID`=54021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 검을 들었네.', `MaleText_loc4`='刀剑出鞘，准备应战。', `MaleText_loc5`='我的劍已準備應戰。', `MaleText_loc7`='Preparé mis espadas para la batalla.' WHERE `ID`=54022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 위험한 걸 발견하면, 빛을 비췄어. 그러면 앰버의 저격총이 해결해 줬지.', `MaleText_loc4`='如果我发现有危险，就用光标识出来，剩下的事就由安玻的狙击步枪去料理了。', `MaleText_loc5`='要是看見危險的東西，我只要用光照一下，琥珀的狙擊槍就會幹掉他們。', `MaleText_loc7`='Si veía algo peligroso, lo iluminaría y el rifle de francotirador de Amber se encargaría del resto.' WHERE `ID`=54023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<슈가 기대에 찬 눈빛으로 당신을 바라봅니다.>', `MaleText_loc4`='<涓流期待地看着你。>', `MaleText_loc5`='<舒滿懷期待地看著你。>', `MaleText_loc7`='<Shu te observa expectante.>' WHERE `ID`=54024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='슈, 우고우를 좀 깨워 줄래?', `MaleText_loc4`='涓流，你能帮我叫醒无垢吗？', `MaleText_loc5`='水靈，你能幫我叫醒烏果嗎?', `MaleText_loc7`='Shu, ¿puedes despertar a Wuguo?', `FemaleText_loc1`='슈, 우고우를 좀 깨워 줄래?', `FemaleText_loc4`='涓流，你能帮我叫醒无垢吗？', `FemaleText_loc5`='水靈，你能幫我叫醒烏果嗎?', `FemaleText_loc7`='Shu, ¿puedes despertar a Wuguo?' WHERE `ID`=54025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남서쪽 제단에는 왕자님의 흔적이 없었네.', `MaleText_loc4`='在西南边的神龛附近没发现安度因的踪迹。', `MaleText_loc5`='我在西南邊的祠堂沒有發現安杜因的線索。', `MaleText_loc7`='No encontré ni rastro de Anduin en el santuario suroeste.' WHERE `ID`=54026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 얌전한 너구리를 하나 만났어. 날 따라오더군.', `MaleText_loc4`='可我倒是遇见了一只友善的浣熊，它一直跟着我。', `MaleText_loc5`='不過，我發現一隻友善的浣熊。牠決定跟著我。', `MaleText_loc7`='Lo que sí encontré fue un mapache de lo más simpático que empezó a seguirme.' WHERE `ID`=54027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기즈모라고 이름 붙였지.', `MaleText_loc4`='我给他起名叫吉兹莫。', `MaleText_loc5`='我決定叫牠吉事摩。', `MaleText_loc7`='Decidí llamarlo Gizmo.' WHERE `ID`=54028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 기즈모!', `MaleText_loc4`='不！吉兹莫！', `MaleText_loc5`='不!吉事摩!', `MaleText_loc7`='¡NO! ¡GIZMO!' WHERE `ID`=54029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 바탕 싸우고 나면 먹을 것이나 마실 것이나 훨씬 달게 느껴지지요.', `MaleText_loc4`='大战过后，吃起东西来格外香甜。', `MaleText_loc5`='好好打一場後，食物與酒嚐起來更加美味。', `MaleText_loc7`='La comida y la bebida saben mucho mejor después de una buena pelea.', `FemaleText_loc1`='한 바탕 싸우고 나면 먹을 것이나 마실 것이나 훨씬 달게 느껴지지요.', `FemaleText_loc4`='大战过后，吃起东西来格外香甜。', `FemaleText_loc5`='好好打一場後，食物與酒嚐起來更加美味。', `FemaleText_loc7`='La comida y la bebida saben mucho mejor después de una buena pelea.' WHERE `ID`=54030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 꼬마 친구! 앞으로 기즈모라고 불러 줄게.', `MaleText_loc4`='嘿，小家伙！我要给你起名叫吉兹莫。', `MaleText_loc5`='嘿，小傢伙!我要叫你吉事摩。', `MaleText_loc7`='¡Hola, pequeñín! Te voy a llamar Gizmo.' WHERE `ID`=54031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버, 왜!? 내가 빛도 비추지 않았는데!', `MaleText_loc4`='安玻，怎么回事！？我根本没亮过这该死的灯！', `MaleText_loc5`='為什麼，琥珀!?我根本沒有閃那該死的光!', `MaleText_loc7`='¡AMBER! ¿POR QUÉ? ¡NI SIQUIERA HABÍA ENCENDIDO LA MALDITA LUZ!' WHERE `ID`=54032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그 후에 또 다른 너구리를 만났어.', `MaleText_loc4`='很快，又有一只浣熊跟我交上了朋友。', `MaleText_loc5`='過了不久，又有一隻浣熊成為我的朋友。', `MaleText_loc7`='Poco después me hice amigo de otro mapache.' WHERE `ID`=54033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양말이라고 부르고, 옛 친구는 잊었지.', `MaleText_loc4`='我给它起名叫袜子，然后又继续前进了。', `MaleText_loc5`='我把牠命名為襪子，然後就上路了。', `MaleText_loc7`='Lo llamé Calcetines y seguí adelante.' WHERE `ID`=54034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와, 양말아. 총에 맞기 전에 여길 빠져나가자.', `MaleText_loc4`='来吧，袜子。趁你还没被打死，我们离开这儿。', `MaleText_loc5`='快點，襪子。在你被射中之前趕快離開這裡。', `MaleText_loc7`='Ven, Calcetines. Vámonos antes de que te dispare alguien.' WHERE `ID`=54035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저길 보세요! 황혼의 이교도들이 고대 신과 놈들의 타락을 고룡쉼터 사원에 불러왔습니다. 꽉 잡으세요!', `MaleText_loc4`='看那边！暮光教徒好像将上古之神以及他们的腐蚀也带到了龙眠神殿。坚持住！', `MaleText_loc5`='看看那裡!看起來就像是暮光教徒把上古諸神跟祂們的腐敗帶來龍眠神殿了。抓緊了!', `MaleText_loc7`='¡Mira eso! Parece que los cultores Crepusculares han traído a los dioses antiguos y su corrupción al Reposo del Dragón. ¡Agárrate!' WHERE `ID`=54036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그르릉... *딸꾹*... 으르릉...', `MaleText_loc4`='呃……*嗝*……呃……', `MaleText_loc5`='嘎呃...*嗝*...呃...', `MaleText_loc7`='Grrrrr...*hip*... rrr...' WHERE `ID`=54037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 제단에는 아무것도 없었어. 안두인 왕자님도, 호젠도.', `MaleText_loc4`='我在北边的神龛一无所获——没有白卒，没有猢狲……什么都没有。', `MaleText_loc5`='我在北邊的祠堂什麼都沒發現。沒有安杜因，沒有猴人...什麼都沒有。', `MaleText_loc7`='No encontré nada en el santuario del norte. Ni al peón blanco, ni hozen, ni nada.' WHERE `ID`=54038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제단 세 곳을 정찰하고, 야영지로 돌아갔네.', `MaleText_loc4`='侦查过三处神龛后，我就返回了营地。', `MaleText_loc5`='偵查完三座祠堂，我就往營地的方向走回去了。', `MaleText_loc7`='Tras explorar los tres santuarios, me dirigí de vuelta al campamento.' WHERE `ID`=54039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양말이도 날 졸졸 따라왔어.', `MaleText_loc4`='袜子忠心耿耿地跟了过来。', `MaleText_loc5`='襪子也忠心地跟上了。', `MaleText_loc7`='Calcetines me siguió fielmente.' WHERE `ID`=54040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽃가루 강타!', `MaleText_loc4`='花粉重击！', `MaleText_loc5`='花粉拳!', `MaleText_loc7`='¡Puñetazo de polen!' WHERE `ID`=54041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 난초!', `MaleText_loc4`='我的果园！', `MaleText_loc5`='我的蘭花!', `MaleText_loc7`='¡Mis orquídeas!' WHERE `ID`=54042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우이이이이이!', `MaleText_loc4`='啊啊啊啊！！', `MaleText_loc5`='威咿咿!', `MaleText_loc7`='¡Ueee!' WHERE `ID`=54043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 렐...', `MaleText_loc4`='不……利尔……', `MaleText_loc5`='不...瑞爾...', `MaleText_loc7`='No... Rell...' WHERE `ID`=54044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으... 으으으... 으으으으...

<저는 괜찮을 겁니다... 조금 있으면 나을 테니까요...>', `MaleText_loc4`='唔……唔……嗯……

<我不会……有事的……它会慢慢……消失的……>', `MaleText_loc5`='嗯...嗯嗯...嗯噢...嗯啊...

<我...沒事...過一會兒...就好了...>', `MaleText_loc7`='Nnn... nn nnnn... n-nl nnnr nnn... nn n nnnt...

<Estaré... bien... desaparecerá... pronto...>' WHERE `ID`=54045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니. 망자를 괴롭히는 네 만행은 여기서 끝난다.', `MaleText_loc4`='不。你亵渎死者的恶行到此为止了。', `MaleText_loc5`='不，你奴役亡者的邪行到此為止。', `MaleText_loc7`='No. Tu perversión de los muertos acaba aquí.' WHERE `ID`=54046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 불쌍한 영혼들이... 자, 이곳을 통해 안식처로 갈 수 있습니다.', `MaleText_loc4`='这些可怜的灵魂……这边走，它会带领你们返回故乡的。', `MaleText_loc5`='這麼多可憐的魂靈...來吧，這會引領你們回家。', `MaleText_loc7`='Estas pobres almas... Tomen, esto los guiará hasta su hogar.' WHERE `ID`=54047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 잡고 말겠다, 영혼현자!', `MaleText_loc4`='我会抓住你的，灵魂贤者！', `MaleText_loc5`='我一定會找到你的，靈魂先知!', `MaleText_loc7`='¡Acabaré contigo, sabio espiritual!' WHERE `ID`=54049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억! 너무... 너무... 많아!', `MaleText_loc4`='嗷！太……多了……太多了！', `MaleText_loc5`='啊呃!太...多了...太多了!', `MaleText_loc7`='¡Auch! Demasiado... ¡Es demasiado!' WHERE `ID`=54050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 쓰러질 수는 없다. 아직 할 일이 이렇게 많은데...', `MaleText_loc4`='我可不能倒在这里，还有很多事情等着我去做呢……', `MaleText_loc5`='我不能在這裡倒下，有這麼多工作等著我去做...', `MaleText_loc7`='No puedo caer aquí. No cuando me queda tanto por hacer...' WHERE `ID`=54051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노스렌드 지하 깊숙한 곳은 네루비안의 영토다, $r.$B$B나는 이 위대한 진리를 다시 세우는 데 나 자신을 바쳤다.', `MaleText_loc4`='诺森德的地底深渊是属于蛛魔的，$r。$B$B我毕生都在为重建这一秩序而奋斗。', `MaleText_loc5`='北裂境的地底屬於奈幽蟲族，$r。$B$B我全心全意要讓這個事實回歸。', `MaleText_loc7`='Las profundidades de Rasganorte pertenecen a los nerubianos, $r.$B$BMe he dedicado a restaurar esa gran verdad.' WHERE `ID`=54052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하. 이번 달 내로 제7함대 전체를 현장에 배치할 수 있습니...', `FemaleText_loc4`='长官，我们在本月内就能集齐整支第七舰队——', `FemaleText_loc5`='長官，一個月內我們就可以讓第七艦隊完全就緒－', `FemaleText_loc7`='Señor, podemos contar con la séptima flota al completo en un mes --' WHERE `ID`=54055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하! 마침내 테일러의 마지막 교신을 복구했습니다.', `MaleText_loc4`='陛下！我们终于复原了泰勒最后发出的信息。', `MaleText_loc5`='陛下!我們終於拼湊出泰勒的上一道訊息了。', `MaleText_loc7`='¡Su Majestad! Hemos recuperado la última transmisión de Taylor.' WHERE `ID`=54056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트윈드, 네가 확보한 교신은 아직 복구하지 못했나? 뭐든 준비된 것만이라도 들려다오!', `MaleText_loc4`='夜风，你拼合出最后的信息了吗？尽全力去做！', `MaleText_loc5`='夜風，你弄清楚上次傳來的訊息了嗎?不管你知道甚麼都告訴我!', `MaleText_loc7`='Nochebrisa, ¿has podido juntar todos los trozos de la última transmisión? ¡Quiero escuchar lo que tengas!' WHERE `ID`=54057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 시간이 없다! 소규모 작전 부대를 지금 즉시 파견하라. 정예병이어야 한다. 생존자들을 구출하고, 소중한 화물을 반드시 회수해야 한다!', `MaleText_loc4`='没时间了！我们要立即派出一支小队。一支精英战队。去救回幸存者，还有那些珍贵的货物！', `MaleText_loc5`='沒時間了!我們會派一個小隊過去。一支精銳部隊。救回倖存者，還有他們珍貴的船貨!', `MaleText_loc7`='¡No hay tiempo! Enviaremos de inmediato un pequeño equipo. Una fuerza de élite. ¡Rescaten a los sobrevivientes, Y su preciado cargamento!' WHERE `ID`=54058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 들었나? 안전한 곳에 도착한 모양이군!', `MaleText_loc4`='你听到没？他们正安全地待在某个地方！', `MaleText_loc5`='你聽見了嗎?他們在某處，平安無事!', `MaleText_loc7`='¿Lo has oído? ¡Están a salvo en algún lugar!' WHERE `ID`=54059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 계획된 접선 지점의 서쪽... 호드 비행선들이... [총성]... 사상자가 발생했다!', `MaleText_loc4`='……原定集结地以西……部落空中部队……[炮火声]……伤亡！', `MaleText_loc5`='...預計會合地點的西方...部落空軍部隊...<槍聲>...有人傷亡!', `MaleText_loc7`='... al oeste del punto de encuentro planeado... Flota aérea de la Horda... [disparos]... ¡Bajas!' WHERE `ID`=54060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 승리는 우리 것입니다!', `MaleText_loc4`='胜利今天是属于我们的！', `MaleText_loc5`='今天勝利是我們的!', `MaleText_loc7`='¡Hemos vencido!' WHERE `ID`=54061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 안개가 자욱한 해안을 은신처로... 후퇴하라... 미지의 땅이다...', `MaleText_loc4`='……浓雾提供掩护……撤退……未知陆地……', `MaleText_loc5`='...濃霧作為掩護...撤退...未知的土地...', `MaleText_loc7`='... Banco de niebla espesa para estar cubiertos... retirada... tierra ignota...' WHERE `ID`=54062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 적대적인 생물이다. 하지만 하얀 싹을 확인했다. 반복한다. 하얀 싹은 안전하다.', `MaleText_loc4`='……敌对生物。但已找到白卒。重复：白卒是安全的。', `MaleText_loc5`='...充滿敵意的生物。但白棋沒有問題。重複:白棋很安全。', `MaleText_loc7`='... Criaturas hostiles. Pero el peón blanco está bien. Repito: el peón blanco está a salvo.' WHERE `ID`=54063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... [칼싸움 소리]... 위급 상황! 구조를 요청한다. 구조를...', `MaleText_loc4`='……[刀剑碰撞声]……紧要危机！请求救援，请求——', `MaleText_loc5`='...<刀劍撞擊聲>...陷入危機!請求支援，重複－', `MaleText_loc7`='... [Sonido de espadas]... ¡Peligro inmediato! Solicitando rescate, solicitando...' WHERE `ID`=54064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 맞섰다... 부족이... 극도로 적대적인 생물이다... 우리는... 위급한 상황이다... 구조를 요청한다. 반복한다...', `MaleText_loc4`='……遭遇——部族——极端敌对生物……我们——身陷巨大危险……请求救援，我再重复一次——', `MaleText_loc5`='...遇到...部族...極有敵意的生物...我們－陷入危機...請求支援，重複－', `MaleText_loc7`='... Encontrado... tribu... criaturas extremadamente hostiles... Estamos... en peligro inmediato... Solicitando rescate, repito...' WHERE `ID`=54065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하얀 싹을 회수하고 나면, 해군이 총력을 동원하여 호드와 맞설 수 있다. 우리 방식대로.', `MaleText_loc4`='等救出白卒后，我们的海军就能发挥出全部威力，去迎战部落。这次该轮到我们做主了。', `MaleText_loc5`='一旦找回白棋，我們的海軍就能全力攻擊部落。以「我們的」方式。', `MaleText_loc7`='Una vez se recupere el peón blanco, todo el poder de nuestra marina podrá enfrentarse a la Horda. Tal y como QUERAMOS.' WHERE `ID`=54066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아와 보니, 렐이 호젠에게 공격받고 있었어! 또!', `MaleText_loc4`='我回来时，却发现利尔又遭到了猢狲的攻击！', `MaleText_loc5`='我回去之後，發現瑞爾再次遭受猴人的攻擊!', `MaleText_loc7`='Volví y me encontré a los hozen atacando a Rell. ¡Otra vez!' WHERE `ID`=54067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앰버! 여기 지원이 필요해!', `MaleText_loc4`='安玻！把枪瞄准这边！', `MaleText_loc5`='琥珀!快點瞄準這裡!', `MaleText_loc7`='¡AMBER! ¡APUNTA HACIA AQUÍ!' WHERE `ID`=54068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$N 님, 당신이 도착한 후에 상황이 빠르게 바뀌고 있어요. 호젠의 위협이 그 어느 때보다 강해졌어요.$b$b하지만 우리 진위도... 더 강해졌죠.', `MaleText_loc4`='自从你来了之后，形势迅速好转了，$n。猢狲的威胁空前强大。$b$b可我们锦鱼人……也更加强大了。', `MaleText_loc5`='你來了之後事情有很多改變，$n。猴人的威脅前所未有的大。$b$b但我們錦魚人...我們也變得更加強大。', `MaleText_loc7`='Las cosas han cambiado muy rápido desde que llegaste aquí, $n. Los hozen son una amenaza mayor que nunca.$b$bPero los jinyu... también nos hemos vuelto más fuertes.' WHERE `ID`=54069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리끼리만 호젠과 맞서면 아마 상대도 안 될 거예요. 우리 부족이 살아남으려면, 얼라이언스의 도움이 필요해요.', `MaleText_loc4`='我们不可能独自对抗猢狲。如果我们的部族想要生存下去，就需要联盟的帮助。', `MaleText_loc5`='光靠我們自己面對猴人是有死無生，我們需要聯盟的幫助來讓部族生存。', `MaleText_loc7`='No podemos enfrentarnos solos a los hozen. Si nuestra tribu quiere sobrevivir, necesita la ayuda de la Alianza.' WHERE `ID`=54070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렐은 살아남았어요. 하지만 상태가 좋지 못했죠.', `MaleText_loc4`='利尔在袭击中活了下来，可是他的情况不太好。', `MaleText_loc5`='瑞爾撐過了這場攻擊，但他的狀況不太好。', `MaleText_loc7`='Rell sobrevivió al ataque, pero no estaba en buen estado.' WHERE `ID`=54071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 참 특이한 곳이에요.$B$B지맥을 바로잡으려고 제가 지금 사용하는 마법은 원래는 절 갈가리 찢을 만큼 강력한 마법이거든요. 그런데 이렇게 몸이 가뿐하다니!', `FemaleText_loc4`='这个地方很特别。$B$B我正在引导魔法，以修复魔网。虽然这么做会将我撕成碎片，可我还是觉得很不可思议！', `FemaleText_loc5`='這是個非常奇特的地方。$B$B我用來修復地脈的魔法本來應該扯碎我的身體，但我卻覺得棒極了!', `FemaleText_loc7`='Este lugar es muy extraño.$B$BLa magia que estoy canalizando para reparar las líneas Ley debería estar destrozándome el cuerpo, ¡pero la sensación es increíble!' WHERE `ID`=54072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞길에 바나나 껍질을 던지지 마라.', `MaleText_loc4`='不要在路上乱扔香蕉皮。', `MaleText_loc5`='別在自己走路的地方擺香蕉皮。', `MaleText_loc7`='No tires una piel de plátano donde vayas a caminar.', `FemaleText_loc1`='앞길에 바나나 껍질을 던지지 마라.', `FemaleText_loc4`='不要在路上乱扔香蕉皮。', `FemaleText_loc5`='別在自己走路的地方擺香蕉皮。', `FemaleText_loc7`='No tires una piel de plátano donde vayas a caminar.' WHERE `ID`=54073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바나나 먹으려면 까야 한다.', `MaleText_loc4`='先剥皮，再吃香蕉。', `MaleText_loc5`='吃香蕉前，先剝香蕉皮。', `MaleText_loc7`='Primero pelar banana. Después, komer.', `FemaleText_loc1`='바나나 먹으려면 까야 한다.', `FemaleText_loc4`='先剥皮，再吃香蕉。', `FemaleText_loc5`='吃香蕉前，先剝香蕉皮。', `FemaleText_loc7`='Primero pelar banana. Después, komer.' WHERE `ID`=54074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 바나나 뺏으면 호젠 화낸다.', `MaleText_loc4`='从猢狲那里偷香蕉，你就等着遇到一只暴怒的猢狲吧。', `MaleText_loc5`='偷猴人香蕉之前，先想好怎麼對付生氣的猴人。', `MaleText_loc7`='Si le robas un plátano a un hozen, tendrás un hozen enfadado.', `FemaleText_loc1`='호젠 바나나 뺏으면 호젠 화낸다.', `FemaleText_loc4`='从猢狲那里偷香蕉，你就等着遇到一只暴怒的猢狲吧。', `FemaleText_loc5`='偷猴人香蕉之前，先想好怎麼對付生氣的猴人。', `FemaleText_loc7`='Si le robas un plátano a un hozen, tendrás un hozen enfadado.' WHERE `ID`=54075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭죽은 던지는 것, 바나나는 먹는 것.', `MaleText_loc4`='爆竹是用来丢的，香蕉是用来吃的。', `MaleText_loc5`='鞭炮是用來丟的，香蕉是用來吃的。', `MaleText_loc7`='Petardos para lanzar, banana para komer.', `FemaleText_loc1`='폭죽은 던지는 것, 바나나는 먹는 것.', `FemaleText_loc4`='爆竹是用来丢的，香蕉是用来吃的。', `FemaleText_loc5`='鞭炮是用來丟的，香蕉是用來吃的。', `FemaleText_loc7`='Petardos para lanzar, banana para komer.' WHERE `ID`=54076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='털이 젖으면 잘 때 기분 나쁘다.', `MaleText_loc4`='不擦干毛发就睡觉会不舒服。', `MaleText_loc5`='濕濕的毛好難睡。', `MaleText_loc7`='No es divertido dormir sobre pelo mojado.', `FemaleText_loc1`='털이 젖으면 잘 때 기분 나쁘다.', `FemaleText_loc4`='不擦干毛发就睡觉会不舒服。', `FemaleText_loc5`='濕濕的毛好難睡。', `FemaleText_loc7`='No es divertido dormir sobre pelo mojado.' WHERE `ID`=54077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종일 응가 냄새 풍기기 싫으면 응가 밭에 구르지 마라.', `MaleText_loc4`='别在自己的粪便里打滚，除非你想臭上一整天。', `MaleText_loc5`='別在自己的便便上打滾除非你整天都想聞便便味。', `MaleText_loc7`='Si makaku hace croketa en kaka, huele a kaka todo día.', `FemaleText_loc1`='종일 응가 냄새 풍기기 싫으면 응가 밭에 구르지 마라.', `FemaleText_loc4`='别在自己的粪便里打滚，除非你想臭上一整天。', `FemaleText_loc5`='別在自己的便便上打滾除非你整天都想聞便便味。', `FemaleText_loc7`='Si makaku hace croketa en kaka, huele a kaka todo día.' WHERE `ID`=54078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 꼬리가 있을 때는 자기 꼬리 당기지 마라.', `MaleText_loc4`='可以扯别人的尾巴时，绝对不扯自己的。', `MaleText_loc5`='有其他尾巴可以拉的時候別拉自己尾巴。', `MaleText_loc7`='Makaku no debe tirar de kola propia si puede tirar de otras.', `FemaleText_loc1`='다른 꼬리가 있을 때는 자기 꼬리 당기지 마라.', `FemaleText_loc4`='可以扯别人的尾巴时，绝对不扯自己的。', `FemaleText_loc5`='有其他尾巴可以拉的時候別拉自己尾巴。', `FemaleText_loc7`='Makaku no debe tirar de kola propia si puede tirar de otras.' WHERE `ID`=54079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가, 먹기 나쁘지만 던지기 좋다.', `MaleText_loc4`='粪便不能吃，但可以用来丢。', `MaleText_loc5`='便便不好吃，但很好丟。', `MaleText_loc7`='Kaka no se kome, kaka se lanza.', `FemaleText_loc1`='응가, 먹기 나쁘지만 던지기 좋다.', `FemaleText_loc4`='粪便不能吃，但可以用来丢。', `FemaleText_loc5`='便便不好吃，但很好丟。', `FemaleText_loc7`='Kaka no se kome, kaka se lanza.' WHERE `ID`=54080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 친구여. 당신이 도와주지 않았더라면 저는 아직도 저 저주받은 곳에 갇혀 있었을 것입니다.$B$B하지만, 사실 저는 이곳에 있어서는 안 됩니다. 영혼결속자들을 막아야만 합니다.', `MaleText_loc4`='谢谢你，朋友。要不是你的介入，我现在已经被束缚在那个卑鄙的建筑里了。$B$B但是，我根本就不该留在这个世上。我们必须阻止那些缚灵者。', `MaleText_loc5`='謝謝你，朋友。若不是你的干預，我已經被束縛在那邪惡的造像裡面了。$B$B但我依然不該存在於這裡，我們必須阻止這些縛靈者。', `MaleText_loc7`='Gracias, $gamigo:amiga;. Si no fuera por tu intervención, aún seguiría ligado a ese ensamblaje maldito.$b$bNo debería estar aquí. Debemos poner fin a los vinculadores de espíritus.' WHERE `ID`=54081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어찌 보면 네가 부럽기도 하다, 작은 $r.$B$B너는 강대한 아졸네룹 왕국이 다시 일어서는 그 첫 단계를 직접 보는 행운을 얻었으니 말이다.', `MaleText_loc4`='从某个角度来说，我很嫉妒你，小$r。$B$B你真是太幸运了，居然能够见证伟大的艾卓-尼鲁布帝国重生的第一步。', `MaleText_loc5`='某方面來說我很嫉妒你，小$r。你很幸運，能親眼目睹偉大的阿茲歐-奈幽王國重生的第一步。', `MaleText_loc7`='Te envidio en parte, $r.$B$BTienes la gran fortuna de contemplar los primeros pasos del renacimiento del gran imperio de Azjol-Nerub.' WHERE `ID`=54082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 앞의 표지판은 우릴... 반기지 않았어요.', `MaleText_loc4`='前门的情形看起来有点儿……吓人。', `MaleText_loc5`='前面的狀況似乎...不太妙。', `MaleText_loc7`='La señal de fuera era poco... cordial.' WHERE `ID`=54083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔디밭에는 작은 비취 조각상이 널려 있었어요. 마치... 살아있는 것 같았죠.', `MaleText_loc4`='草地上摆满了小小的青玉雕像。每一个都……栩栩如生。', `MaleText_loc5`='草坪上到處都是小型的玉像，它們看起來...栩栩如生。', `MaleText_loc7`='El jardín estaba lleno de pequeñas estatuas de jade. Eran muy... realistas.' WHERE `ID`=54084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상 하나가 특히 눈에 띄었어요. 그런 생물은 본 적이 없었거든요.', `MaleText_loc4`='其中有一座雕像特别突出。我从没见过那种生物。', `MaleText_loc5`='有一座雕像特別突出，我從沒見過像這樣的生物。', `MaleText_loc7`='Una en concreto me llamó la atención. Nunca había visto una criatura semejante.' WHERE `ID`=54085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허! 어떤 표지판도 나와 양말이를 막을 순 없어!', `MaleText_loc4`='哼！什么情形都吓不住我和我的好伙伴袜子！', `MaleText_loc5`='切!破牌子!別想阻止我和我的好夥伴襪子!', `MaleText_loc7`='¡Bah! Una señal no nos detendrá ni a mí ni a mi colega Calcetines.' WHERE `ID`=54086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상이 왜 이렇게 많은 거지...?', `MaleText_loc4`='这个家伙肯定收藏了不少雕像……', `MaleText_loc5`='這傢伙的雕像還真不少耶...', `MaleText_loc7`='Alguien tiene un montón de estatuas...' WHERE `ID`=54087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니아니, 잠깐만 기다려 봐. 오크? 호... 호드도 여기 온 건가?!', `MaleText_loc4`='等一下。那不是兽人吗？部……部落也来了！？', `MaleText_loc5`='咦等等。那是個獸人嗎?難道...難道部落也在這裡!?', `MaleText_loc7`='Espera un momento. ¿Eso es un orco? ¿La HORDA también está aquí?' WHERE `ID`=54088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것 봐라... 진위하고... 저건 대체 뭐지? 수염 요마인가?', `FemaleText_loc4`='看看这个……一个锦鱼人和……这是什么东西？一个胡子精吗？', `FemaleText_loc5`='看哪看哪...一個錦魚人和...那是什麼?某種長鬍子的妖精?', `FemaleText_loc7`='Vamos a ver... un jinyu y... ¿qué es esto? ¿Una especie de duende barbudo?' WHERE `ID`=54089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프입니다, 부인. 음식 좀 얻을 수 있을까요?', `MaleText_loc4`='我是个矮人，女士。能向您借点儿吃的吗？', `MaleText_loc5`='我是個矮人，女士。能給我們點食物嗎?', `MaleText_loc7`='Soy un enano, señora. ¿Nos das algo de comida?' WHERE `ID`=54090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 수염 요마는 우리 가족이 되면 좋겠는걸!', `FemaleText_loc4`='这个胡子精一定能成为一个很不错的家族藏品！', `FemaleText_loc5`='鬍子妖精會是我家族的優秀新成員!', `FemaleText_loc7`='¡El duende barbudo será una adquisición excelente para mi familia!' WHERE `ID`=54091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 대체 무슨 말입니까...', `MaleText_loc4`='你到底在说些什么呢……', `MaleText_loc5`='妳到底在說些什麼啊...', `MaleText_loc7`='¿De qué demonios estás hablando?' WHERE `ID`=54092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설리... 이것들은 조각상이 아니에요! 저 여자가 당신을 비취로 만들려고 해요!', `MaleText_loc4`='苏利……她是想把你变成玉雕，她草地上的雕像都是受害者！', `MaleText_loc5`='蘇利...草坪上的不是雕像!她想要把你變成玉石!', `MaleText_loc7`='Sully... ¡lo del jardín no son estatuas! ¡Quiere convertirte en jade!' WHERE `ID`=54093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그제서야 무슨 일이 일어나고 있는 건지 깨달았지만... 이미 늦은 후였어요.', `MaleText_loc4`='然后我终于弄清楚是怎么回事儿了……可那已经太迟了。', `MaleText_loc5`='我終於瞭解現在是什麼狀況...但我晚了一步。', `MaleText_loc7`='Por fin comprendí lo que sucedía... pero ya era demasiado tarde.' WHERE `ID`=54094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아하하하하! 하하! 하하하!', `FemaleText_loc4`='啊哈哈哈哈！！', `FemaleText_loc5`='啊哈哈哈哈哈!', `FemaleText_loc7`='¡JAAAAAA JA JA JAAAAA!' WHERE `ID`=54095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양말아! 안 돼애애애애!', `MaleText_loc4`='袜子！不！！！！！', `MaleText_loc5`='襪子!不...!', `MaleText_loc7`='¡CALCETINES! ¡NOOOO!' WHERE `ID`=54096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 시간이 다가온다. 모든 것의 끝. 넌 막지 못한다. 넌 못 해. 못 해!', `MaleText_loc4`='暮光审判降临了——万物的末日到了——你阻止不了。你微不足道。微不足道！', `MaleText_loc5`='暮光之時已降臨，一切的終點。你無能為力。你是廢物。廢物!', `MaleText_loc7`='La Hora del Crepúsculo, el final de todas las cosas, no podrás impedirlo. No eres nada. ¡NADA!' WHERE `ID`=54097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 구리구리 역겨운 우낏들을 없애라!', `MaleText_loc4`='打倒这些该死的蠢蛋！', `MaleText_loc5`='打怪怪人的下面，拿走他們的蛋蛋!', `MaleText_loc7`='¡Molesten a makakus en kuku!' WHERE `ID`=54098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 놈들을 모두 응가 더미에 푹 파묻어 버려라!', `MaleText_loc4`='小的们，干掉他们！', `MaleText_loc5`='打爆他們的要害，小子們!', `MaleText_loc7`='¡Moléstenles los mikos, chikos!' WHERE `ID`=54099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가를 우끼끼할 때까지 엉덩이를 두들겨라!', `MaleText_loc4`='打呀，把他们赶回老家去！', `MaleText_loc5`='打到他們拉肚子!', `MaleText_loc7`='¡Háganles unga hasta que se kraku en los wakus!' WHERE `ID`=54100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼기짝을 뻥 걷어차고 거꾸로 들어서 절벽 너머로 던져!', `MaleText_loc4`='打到他们，揍死他们！', `MaleText_loc5`='抓住他們的臉然後打到他們頭髮都掉下來!', `MaleText_loc7`='¡Aplatanadles los kukos y patadlos hasta que se les caiga la puka!' WHERE `ID`=54101;
