UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형, 차원문을 닫을 수 있겠어?', `MaleText_loc4`='你能关闭这座传送门吗，哥哥？', `MaleText_loc5`='你能把傳送門關閉嗎，兄弟?', `MaleText_loc7`='¿Puedes cerrar el portal, hermano?' WHERE `ID`=54103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 알았어. 놈은 우리가 쓰러뜨리지.', `MaleText_loc4`='很好，我们可以帮你摧毁它。', `MaleText_loc5`='好吧，我們幫你擊潰牠吧。', `MaleText_loc7`='Muy bien, lo romperemos por ti.' WHERE `ID`=54104;
