UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 악마가 차원문을 유지하고 있다... 만노로스 말이지.', `MaleText_loc4`='有一个强大的恶魔在用自己的意志保护着它——是玛诺洛斯。', `MaleText_loc5`='它是由一個強大惡魔的意志所開啟...瑪諾洛斯。', `MaleText_loc7`='Lo mantiene la voluntad de un poderoso demonio... Mannoroth.' WHERE `ID`=54106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 혼자선 놈을 어찌할 수 없어...', `MaleText_loc4`='我无法独自摧毁他的意志……', `MaleText_loc5`='我無法獨自擊潰他的意志...', `MaleText_loc7`='No puedo quebrar su voluntad solo...' WHERE `ID`=54107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='만노로스는 우리가 뭘 하려는지 알아. 시간이 없어. 숲엔 놈의 부하들이 가득해.', `FemaleText_loc4`='他知道了我们的计划。时间不多了，他的恶魔遍布了整片森林。', `FemaleText_loc5`='他知道我們的企圖。我們沒時間了，森林裡到處都是他的惡魔。', `FemaleText_loc7`='Sabe lo que pretendemos. No tenemos mucho tiempo, sus demonios infestan el bosque.' WHERE `ID`=54108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 많군...', `MaleText_loc4`='他们的数量太多了……', `MaleText_loc5`='來得還真多啊...', `MaleText_loc7`='Hay MUCHÍSIMOS…' WHERE `ID`=54109;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머니 달이시여, 어둠 속에서 저흴 이끄소서.', `FemaleText_loc4`='月亮母亲，请您指引我们走出这黑暗。', `FemaleText_loc5`='月亮之母啊，引領我們度過黑暗。', `FemaleText_loc7`='Madre luna, guíanos en esta oscuridad.' WHERE `ID`=54110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약하고 무능한 것들 같으니. 불타는 군단이라는 이름이 아깝군.', `MaleText_loc4`='一群软弱的可怜虫。根本配不上“军团”这个称号。', `MaleText_loc5`='弱小可憐的生物。稱為軍團太抬舉他們了。', `MaleText_loc7`='Criaturas débiles y lamentables. No son dignos de llamarse legión.' WHERE `ID`=54111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이건 상대할 맛 나겠는데...', `MaleText_loc4`='噢，这一定很有趣……', `MaleText_loc5`='噢，這一定很好玩...', `MaleText_loc7`='Oh, esto va a ser divertido...' WHERE `ID`=54112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 좋은 생각이 있어.', `MaleText_loc4`='等等，我有个主意。', `MaleText_loc5`='等等，我有個主意。', `MaleText_loc7`='Espera, tengo una idea.' WHERE `ID`=54113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일리단, 그 물병은 뭐지? 지금 뭐 하는 거야?', `FemaleText_loc4`='伊利丹，那个瓶子里装的是什么？你在干什么？', `FemaleText_loc5`='伊利丹，那個瓶子裡是什麼?你在做什麼?', `FemaleText_loc7`='Illidan, ¿qué hay en ese vial? ¿Qué estás haciendo?' WHERE `ID`=54114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상을 살펴보고 나니까, 오두막에서 여자 판다렌이 나타나더라고요.', `MaleText_loc4`='调查过那些雕像后，我们看见一个女熊猫人从屋子里走了出来。', `MaleText_loc5`='檢查完雕像之後，我們看到一個女熊貓人從小屋裡跑出來。', `MaleText_loc7`='Tras inspeccionar las estatuas, vimos a una pandaren salir de la casa.' WHERE `ID`=54115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동족들은 못 하는 일.', `MaleText_loc4`='做我们族人做不了的事。', `MaleText_loc5`='我們的人做不到的。', `MaleText_loc7`='Lo que nuestro pueblo no consiguió.' WHERE `ID`=54116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 이거야. 영원의 샘에 담긴... 생생한 마력이 느껴지는군! 이제 이 한심한 싸움을 끝내버리겠다!', `MaleText_loc4`='是的……是的。我能感觉到永恒之井的原始力量！是时候结束这场闹剧了！', `MaleText_loc5`='沒錯...沒錯。我可以感受到永恆之井的力量。是時候結束這場鬧劇了!', `MaleText_loc7`='Sí... ¡Sí! ¡Siento el poder salvaje del Pozo de la Eternidad! ¡Es hora de acabar con esta farsa!' WHERE `ID`=54117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로덴, 하찮은 놈들이 날 방해하지 못하게 해라!', `MaleText_loc4`='瓦罗森，别让这群乌合之众来打搅我！', `MaleText_loc5`='瓦羅森，確保我不受到這群烏合之眾的干擾!', `MaleText_loc7`='¡Varo''then, ocúpate de que esta chusma no me interrumpa!' WHERE `ID`=54118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근위대, 전투 준비! 여왕님을 위해, 아즈샤라 님을 위해!', `MaleText_loc4`='上层卫士们，动手！为了女王！为了艾萨拉！', `MaleText_loc5`='高等衛兵，攻擊!為了你們的女王!為了艾薩拉!', `MaleText_loc7`='¡Guardias nobles, a las armas! ¡Por la Reina! ¡Por Azshara!' WHERE `ID`=54119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격할 수가 없어! 이 사악한 마법은 뭐지?', `FemaleText_loc4`='我打不中他们了！这是什么恶魔邪法？', `FemaleText_loc5`='我無法攻擊!這是什麼惡魔魔法?', `FemaleText_loc7`='¡No puedo golpearlos! ¿Qué tipo de magia demoníaca es esta?' WHERE `ID`=54120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 보이는 건 허상이고, 실체는 다른 곳에 있어. 진짜를 찾아내려면 주변을 공격해!', `MaleText_loc4`='他们并不在我们眼见的位置上！用大范围的攻击，只有这样才能让他们显形！', `MaleText_loc5`='他們的位置不是真的!攻擊整片區域，這是唯一找到真身的方法!', `MaleText_loc7`='¡No están donde parecen estar! ¡Golpea en toda la zona, es la única forma de descubrir al auténtico!' WHERE `ID`=54121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 왔구나.
$b이곳에선 내일이면 세계의 분리가 일어난다. 영원의 샘이 무너지고 대륙이 여러 개로 분리된 사건 말이지.
$b여기서 용의 영혼을 손에 넣어야 한다. 이 시간의 안개 속으로 영영 사라지기 전에...
$b일단 아즈샤라를 따르는 명가 놈들이 만든 보호의 수호물을 찾아서 없애라. 궁전 안에서 찾을 수 있을 터. 난 그 이후를 탐색해 보마.
$b행운을 비노라!', `MaleText_loc4`='啊，你们到了。
这里是大分裂的前夕，永恒之井即将毁灭，撕裂整个大陆。
$b在这里，我们要趁巨龙之魂失落于时间的迷雾之前将其夺回。
$b但首先，你们必须先破坏艾萨拉的上层精灵侍从们的防护结界。他们就在宫殿里。我则会先行一步。
$b祝你们好运，英雄们！', `MaleText_loc5`='你來了。
$b此刻乃永恆之井即將崩壞，而讓世界大陸四分五裂的那場大爆炸前夕。
$b在巨龍之魂消逝在時間的迷霧前，我們會在這裡拿走它。
$b但首先你必須先破壞艾薩拉的貴族手下所施放的保護結界，而結界則在宮殿內。那我先去前面探探路了。
$b祝好運，英雄們!', `MaleText_loc7`='Veo que han llegado.
$bEstamos en la víspera del Cataclismo, cuando el derrumbe del Pozo de la Eternidad fracturó los continentes del mundo.
$bAquí, recuperaremos el Alma de dragón antes de que se pierda en la noche de los tiempos.
$bPero primero, deben eliminar a los resguardos de los lacayos Altonato de Azshara. Me adelantará para explorar.
$b¡Buena suerte, héroes!' WHERE `ID`=54122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 차원문으로 보내 주십시오.', `MaleText_loc4`='送我去1号传送门。', `MaleText_loc5`='送我到傳送門1。', `MaleText_loc7`='Envíame al portal 1.', `FemaleText_loc1`='첫 번째 차원문으로 보내 주십시오.', `FemaleText_loc4`='送我去1号传送门。', `FemaleText_loc5`='送我到傳送門1。', `FemaleText_loc7`='Envíame al portal 1.' WHERE `ID`=54123;
