UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리에게 보내 주십시오.', `MaleText_loc4`='送我去见首领。', `MaleText_loc5`='送我到首領那裡。', `MaleText_loc7`='Envíame al jefe.', `FemaleText_loc1`='우두머리에게 보내 주세요.', `FemaleText_loc4`='送我去见首领。', `FemaleText_loc5`='送我到首領那裡。', `FemaleText_loc7`='Envíame al jefe.' WHERE `ID`=54126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 루! 도망쳐! 너도 당하기 전에!', `MaleText_loc4`='跑啊，小卢！快跑！！别让她抓住你！', `MaleText_loc5`='跑啊，小小盧，快跑!!別讓她也射到你!', `MaleText_loc7`='¡Corre, pequeño Lu! ¡Huye! ¡Antes de que te atrape a ti también!' WHERE `ID`=54127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끼익!', `MaleText_loc4`='吱吱！', `MaleText_loc5`='嘎吱!', `MaleText_loc7`='¡Iiiiic!' WHERE `ID`=54128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너구리 한 마리는 걱정할 일도 아니에요. 가장 중요한 건 이곳에 왜 비취가 된 오크가 있냐는 거예요. 제가 나머지 일을 말씀드릴게요.', `FemaleText_loc4`='失去一只浣熊微不足道。我们最担心的是那个石化的兽人……以及它背后的意义。剩下的事就让我来说吧。', `FemaleText_loc5`='失去浣熊是小事。我們最該擔心的是那個被玉化的獸人..還有他為何出現在這裡。我可以告訴你接下來的故事。', `FemaleText_loc7`='El mapache es el último de nuestros problemas. Nuestra mayor preocupación es el orco petrificado y lo que su presencia significa. Te contaré el resto de la historia.' WHERE `ID`=54129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='렐이... 많이 다쳤어요.$b$b<주먹으로 땅을 내리치는 켈넌 요원>$b$b죽어가고 있다고요, $n 님! 그런데도 우리가 할 수 있는 게 아무것도 없어요!', `FemaleText_loc4`='利尔……伤得很重。$b$b<密探吉尔妮用力地捶了地面一拳。>$b$b他快死了，$n！可我们对此却无能为力！', `FemaleText_loc5`='瑞爾...他傷得很重。$b$b<密探吉爾妮憤恨地揮拳搥打地面。>$b$b他快死了，$n!我們什麼都做不了!', `FemaleText_loc7`='Rell está malherido.$b$b<La agente Kearnen golpea el puño contra el suelo.>$b$b¡Se muere, $n! ¡Se muere y no podemos hacer nada!' WHERE `ID`=54130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아뇨, 하얀 싹을 찾지 못했어요.$b$b아뇨. 하얀 싹이 뭔지 알려드릴 수도 없어요.', `FemaleText_loc4`='不，我们没有找到白卒。$b$b不行，我不能把白卒的身份告诉你。', `FemaleText_loc5`='不，我們沒有找到白棋。$b$b不，我不能告訴你白棋是什麼東西。', `FemaleText_loc7`='No, no encontramos al peón blanco.$b$bNo, no te puedo decir qué es el peón blanco.' WHERE `ID`=54131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산속에 야영지를 세웠어요. 루가 렐을 보살폈지요.', `FemaleText_loc4`='我们在山里扎营。小卢照看利尔。', `FemaleText_loc5`='我們在山裡建立了營地。小小盧負責照顧瑞爾。', `FemaleText_loc7`='Acampamos en las montañas. Pequeño Lu cuidó de Rell.' WHERE `ID`=54132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산꼭대기까지 올라가서, 저격용 총을 붙잡았어요.', `FemaleText_loc4`='我走到了山顶，手里端着狙击枪。', `FemaleText_loc5`='我走到山頂上，手裡拿著我的狙擊槍。', `FemaleText_loc7`='Subí hasta la cima de la montaña y tomé mi rifle de francotirador.' WHERE `ID`=54133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<콜록>... 호젠에게 복수해 다오, 앰버.', `MaleText_loc4`='去杀……几个猢狲，安玻。', `MaleText_loc5`='去...咳咳...去多殺些猴人，琥珀。', `MaleText_loc7`='M... mata unos cuantos hozen, Amber.' WHERE `ID`=54134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 사령관님.', `FemaleText_loc4`='如你所愿，指挥官。', `FemaleText_loc5`='如你所願，指揮官。', `FemaleText_loc7`='Como desees, Comandante.' WHERE `ID`=54135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을 입구에 설리가 기다리고 있더군요.', `FemaleText_loc4`='我发现苏利就等在村子外面。', `FemaleText_loc5`='我發現蘇利在村子入口的外邊等著。', `FemaleText_loc7`='Descubrí a Sully esperando en la entrada de la aldea.' WHERE `ID`=54136;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈을 부릅뜨니까 입술을 읽을 수 있었어요. 이렇게 말하더군요.', `FemaleText_loc4`='我聚精会神，好不容易看清他的口型，他说：', `FemaleText_loc5`='我張大了眼睛，卻只能勉強讀出他的嘴型，他說:', `FemaleText_loc7`='Forzando la vista, conseguí a duras penas leerle los labios. Dijo:' WHERE `ID`=54137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 전진할 수 있게 경비병을 모두 쏴!', `MaleText_loc4`='放倒所有守卫，我才能前进！', `MaleText_loc5`='放倒所有守衛，我要上了!', `MaleText_loc7`='¡Derriba a todos los guardias para que pueda avanzar!' WHERE `ID`=54138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어! 한 번 더 부탁할게!', `MaleText_loc4`='干得好！继续！', `MaleText_loc5`='做得好!再來一次!', `MaleText_loc7`='¡Buen trabajo! ¡Una vez más!' WHERE `ID`=54139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설리가 폭탄 통도 몇 개 설치했어요.', `FemaleText_loc4`='苏利埋下了一些火药桶，让我来开枪引爆。', `FemaleText_loc5`='蘇利放了一些炸藥桶讓我射擊。', `FemaleText_loc7`='Sully colocó varios barriles explosivos para que dispare.' WHERE `ID`=54140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이들에게 줄 선물을 가져왔지! 나도 같이 날려버리진 마!', `MaleText_loc4`='我给猴子们准备了些礼物！可别打我啊，安玻！', `MaleText_loc5`='我給這些猴子帶了些禮物。可別把我也炸飛了，琥珀!', `MaleText_loc7`='¡Traje regalitos para los monos! ¡No me vueles en pedazos, Amber!' WHERE `ID`=54141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 아무것도 없어! 계속 가자!', `MaleText_loc4`='这里没什么好看的了！继续前进！', `MaleText_loc5`='這裡沒什麼好看的!繼續走!', `MaleText_loc7`='¡Aquí no ha pasado nada! ¡Sigamos adelante!' WHERE `ID`=54142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시... 호드 상자가 보여! 갈게, 엄호해 줘!', `MaleText_loc4`='啊哈……我看见一个部落的箱子！掩护我，那附近没有掩体！', `MaleText_loc5`='中獎了...我看到一個部落木箱!掩護我，我要衝出去了!', `MaleText_loc7`='Bingo... ¡Veo un cajón de la Horda! Cúbreme, voy para allá.' WHERE `ID`=54143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 생각대로... 호드도 여기, 판다리아에 왔어요. 그리고 호젠과 손을 잡았지요.', `FemaleText_loc4`='不出我所料……部落也来到了潘达利亚，还和一群猴子结了盟。', `FemaleText_loc5`='跟我想的一樣...部落就在這裡，在潘達利亞上。而他們跟猴人結盟了。', `FemaleText_loc7`='Es lo que sospechaba... La Horda está aquí, en Pandaria. Y se han aliado con los hozen.' WHERE `ID`=54144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 진주지느러미 마을에 알려야 했어요... 하지만 먼저 오크 머리에 총알을 박아줬죠.', `FemaleText_loc4`='我们得把这个消息带回珠鳍村……但首先，让我们收拾几个肮脏的兽人。', `FemaleText_loc5`='我們必須把這個消息帶回珠鰭村...但在那之前得先幹掉幾個獸人。', `FemaleText_loc7`='Informemos al Poblado Aleta de Nácar... pero antes practicaremos puntería con algunos orcos.' WHERE `ID`=54145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나갈 수 있겠어! 간다, 앰버!', `MaleText_loc4`='我看到一个缺口！我来了，安玻！', `MaleText_loc5`='我看到一個缺口!琥珀，我來了!', `MaleText_loc7`='¡Veo una salida! ¡Allá voy, Amber!' WHERE `ID`=54146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 이봐!', `MaleText_loc4`='哎哟！嘿！', `MaleText_loc5`='噢!喂!', `MaleText_loc7`='¡Ay! ¡Oye!' WHERE `ID`=54147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 앰버를 때린 몫이다!', `MaleText_loc4`='让你们再动安玻的坏脑筋！', `MaleText_loc5`='這是為了琥珀!', `MaleText_loc7`='¡Eso por herir a Amber!' WHERE `ID`=54148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 렐을 때린 몫이고!', `MaleText_loc4`='让你们欺负利尔！', `MaleText_loc5`='這是為了瑞爾!', `MaleText_loc7`='¡Eso por herir a Rell!' WHERE `ID`=54149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 기즈모와 양말이 몫이다, 이 나쁜 놈들아!!', `MaleText_loc4`='这个是为吉兹莫和袜子报仇，你们这些混蛋！', `MaleText_loc5`='這是為了吉事摩和襪子，你們這些混蛋!', `MaleText_loc7`='Y esta va por Gizmo y Calcetines, ¡bastardos!' WHERE `ID`=54150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아눕아락이 쓰러졌다, 형제들이여! 나락에서 몸을 일으켜, 타고난 우리의 권리를 되찾자!', `MaleText_loc4`='阿努巴拉克倒下了，兄弟们！从地底深处站起来，夺回我们天赋的权利吧！', `MaleText_loc5`='阿努巴拉克倒下了，兄弟們!從深淵中起身奪回我們生來應得的一切!', `MaleText_loc7`='¡Hermanos míos, Anub''Arak ha caído! Alzaos de las profundidades y reclamad nuestro derecho de linaje.' WHERE `ID`=54151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배의 아픔은 시간이 지나면 사라질 겁니다.', `MaleText_loc4`='失败的痛楚将随时间而渐渐平复。', `MaleText_loc5`='被擊敗的痛楚會隨著時間消退。', `MaleText_loc7`='El hedor de tu derrota se perderá con el tiempo.', `FemaleText_loc1`='패배의 아픔은 시간이 지나면 사라질 거예요.', `FemaleText_loc4`='失败的痛楚将随时间而渐渐平复。', `FemaleText_loc5`='被擊敗的痛楚會隨著時間消退。', `FemaleText_loc7`='El hedor de tu derrota se perderá con el tiempo.' WHERE `ID`=54152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t 티란데가 |cFFFF0000|Hspell:103917|h[엘룬의 축복]|h|r을 얻습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t泰兰德获得了|cFFFF0000|Hspell:103917|h[艾露恩的祝福]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t 泰蘭妲獲得了|cFFFF0000|Hspell:103917|h[伊露恩的祝福]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_moonglow.blp:20|t Tyrande obtiene la |cFFFF0000|Hspell:103917|h[Bendición de Elune]|h|r.', `FemaleText_loc1`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t 티란데가 |cFFFF0000|Hspell:103917|h[엘룬의 축복]|h|r을 얻습니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t泰兰德获得了|cFFFF0000|Hspell:103917|h[艾露恩的祝福]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_nature_moonglow.blp:20|t 泰蘭妲獲得了|cFFFF0000|Hspell:103917|h[伊露恩的祝福]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_nature_moonglow.blp:20|t Tyrande obtiene la |cFFFF0000|Hspell:103917|h[Bendición de Elune]|h|r.' WHERE `ID`=54153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선조들이시여, 제 말을 들어 주십시오! 저승의 여러분을 부르노니, 이 영혼을 제 의지에 구속하여 주십시오!', `MaleText_loc4`='先祖之灵，请听从我的召唤！从遥远的彼岸归来，让这灵魂服从我的意志！', `MaleText_loc5`='祖先啊，請聆聽我的懇求!我呼喚位於彼方的你們，讓這個魂靈順從我的意志!', `MaleText_loc7`='¡Ancestros, atiendan mi llamada! ¡Los invoco desde el más allá para vincular este espíritu a mi voluntad!' WHERE `ID`=54154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t 일리단이 |cFFFF0000|Hspell:103952|h[영원의 물]|h|r로 몸을 적십니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t伊利丹将|cFFFF0000|Hspell:103952|h[永恒之水]|h|r浇在自己身上！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t 伊利丹在自己身上澆了|cFFFF0000|Hspell:103952|h[永恆之水]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_mage_conjurewater11.blp:20|t Illidan se rocía a sí mismo con |cFFFF0000|Hspell:103952|h[Aguas de la eternidad]|h|r.', `FemaleText_loc1`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t 일리단이 |cFFFF0000|Hspell:103952|h[영원의 물]|h|r로 몸을 적십니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t伊利丹将|cFFFF0000|Hspell:103952|h[永恒之水]|h|r浇在自己身上！', `FemaleText_loc5`='|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t 伊利丹在自己身上澆了|cFFFF0000|Hspell:103952|h[永恆之水]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_mage_conjurewater11.blp:20|t Illidan se rocía a sí mismo con |cFFFF0000|Hspell:103952|h[Aguas de la eternidad]|h|r.' WHERE `ID`=54155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참견은 그만둬라, $r! 영혼발톱들아! 이 벌레 같은 녀석을 없애!', `MaleText_loc4`='你的骚扰到此为止了，$r！灵爪刺客们！干掉这只臭虫！', `MaleText_loc5`='我受夠你的干擾了，$r!靈爪們!料理掉這個害蟲!', `MaleText_loc7`='¡Ya has intervenido bastante, $r! Atormentadores de espíritus, ¡acaben con $geste entrometido:esta entrometida;!' WHERE `ID`=54156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 더! 더 필요해! 빨리!', `MaleText_loc4`='我还要更多的灵魂！更多！马上！', `MaleText_loc5`='更多魂靈!更多!給我動作快!', `MaleText_loc7`='¡Más espíritus! ¡MÁS! ¡Rápido!' WHERE `ID`=54157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 절대로! 술은 안 마실 겁니다!', `MaleText_loc4`='我再也不喝酒了！', `MaleText_loc5`='我再也不喝酒了!', `MaleText_loc7`='¡No pienso volver a beber!', `FemaleText_loc1`='이제 절대로! 술은 안 마실 거예요!', `FemaleText_loc4`='我再也不喝酒了！', `FemaleText_loc5`='我再也不喝酒了!', `FemaleText_loc7`='¡No pienso volver a beber!' WHERE `ID`=54158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 영혼들이시여, 이제 지팡이에서 풀어 드리겠습니다! 이 괴물에게 복수를 하십시오!', `MaleText_loc4`='古老的灵魂们啊，从我的法杖中出来吧！向这个畜生复仇吧！', `MaleText_loc5`='古老的魂靈，我將你從我的杖中釋放出來!對這隻野獸進行你的復仇吧!', `MaleText_loc7`='Espíritus de la antigüedad, ¡los libero de mi bastón! ¡Ejecuten su venganza contra esta bestia!' WHERE `ID`=54159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우우! 네가 응가를 꿀꺽할 때까지 때찌때찌해 주겠어, 우낏!', `MaleText_loc4`='嗷！我要揍扁你，揍得你满地找牙，蠢货！', `MaleText_loc5`='喔!我會把你打到你便便都掉出來，怪怪人!', `MaleText_loc7`='¡Ooooh! ¡Te voy a patar hasta que te kukes los mikos, makaku!' WHERE `ID`=54160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이 우낏! 네 갈비뼈를 엉치에 꽂아주마!', `MaleText_loc4`='该死的蠢蛋！我要把你砸扁！', `MaleText_loc5`='壞蛋怪怪人!我會把你的蛋蛋打扁扁的!', `MaleText_loc7`='¡Dingue makaku! ¡Te voy a meter los rukos en el buche!' WHERE `ID`=54161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 코를 꼬집고 얼굴을 부비부비 문질러주마, 우낏!', `MaleText_loc4`='我要揍扁你的鼻子，然后把你抢得精光，蠢蛋！', `MaleText_loc5`='我會打爆你，然後再打扁你，怪怪人!', `MaleText_loc7`='¡Te voy a patar en los mikos y darte una barruka, makaku!' WHERE `ID`=54162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 적들은 얼어붙은 황무지에서 우릴 완전히 몰아냈다고 생각한다.$B$B그 무지한 생각이 어떤 결과를 가져오는지 놈들에게 보여주겠다.', `MaleText_loc4`='我们的敌人以为能靠冰封的荒原来击败我们。$B$B我们要让他们看看愚昧的后果。', `MaleText_loc5`='我們的敵人以為我們在冰凍荒原死光了。$B$B我們讓他們瞧瞧他們無知的後果。', `MaleText_loc7`='Nuestros enemigos creen que fuimos derrotados en los baldíos helados.$B$BLes mostraremos las consecuencias de su ignorancia.' WHERE `ID`=54163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 일해라! 새끼거미가 더 빨리 태어나도록!', `MaleText_loc4`='快点干！我们必须把这个茧孵化出来！', `MaleText_loc5`='動作快點!我們必須把繭孵化!', `MaleText_loc7`='¡Trabajad más deprisa! ¡Debemos abrir el capullo!' WHERE `ID`=54164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아졸네룹 왕국을 우리 손으로 재건할 때이다! 내 부름을 들어라, 형제들이여. 타고난 우리의 권리를 되찾기 위해 일어나라!', `MaleText_loc4`='艾卓-尼鲁布帝国复兴的希望就靠我们了！听从我的召唤吧，兄弟们，站起来夺回属于我们的东西！', `MaleText_loc5`='阿茲歐-奈幽王國的重生即將到來!聽我的呼喚，兄弟們，起身取回屬於我們的東西!', `MaleText_loc7`='¡El renacimiento del imperio de Azjol-Nerub se acerca! ¡Escuchad mi llamada, hermanos, y alzaos para reclamar lo que nos pertenece por derecho!' WHERE `ID`=54165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러 이 지역을 정비하라! 아직 할 일이 많다.', `MaleText_loc4`='快行动，保护好这个区域！我们还有很多事要做呢。', `MaleText_loc5`='快點奪下這個地方!還有很多工作得完成。', `MaleText_loc7`='Date prisa y asegura la zona. Queda mucho trabajo por delante.' WHERE `ID`=54166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 있었지?', `MaleText_loc4`='这里出什么事了？', `MaleText_loc5`='這裡發生了什麼事?', `MaleText_loc7`='¿Qué ha pasado aquí?', `FemaleText_loc1`='여기서 무슨 일이 있었니?', `FemaleText_loc4`='这里出什么事了？', `FemaleText_loc5`='這裡發生了什麼事?', `FemaleText_loc7`='¿Qué ha pasado aquí?' WHERE `ID`=54167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려주셔서 정말 고마워요!', `MaleText_loc4`='谢谢你救了我！', `MaleText_loc5`='感謝你救了我!', `MaleText_loc7`='¡Gracias por salvarme!', `FemaleText_loc1`='구해주셔서 정말 고마워요!', `FemaleText_loc4`='谢谢你救了我！', `FemaleText_loc5`='感謝你救了我!', `FemaleText_loc7`='¡Gracias por salvarme!' WHERE `ID`=54168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 여기 왔었다고 엄마 아빠한테 말하지 마세요.', `MaleText_loc4`='千万别告诉我爸妈我来过这里。', `MaleText_loc5`='拜託別跟我爸媽說我來過這裡。', `MaleText_loc7`='No les digas a mis padres que estaba aquí.', `FemaleText_loc1`='엄마 아빠한테는 제가 여기 왔었다고 말하지 마세요.', `FemaleText_loc4`='千万别告诉我爸妈我来过这里。', `FemaleText_loc5`='拜託別跟我爸媽說我來過這裡。', `FemaleText_loc7`='No les digas a mis padres que estaba aquí.' WHERE `ID`=54169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호 장치가 제대로 작동할 때까지 쉬지 마라. 누구도 우릴 방해하게 둘 순 없다!', `MaleText_loc4`='在那些守卫运转起来之前不准休息。我们决不能受打扰。', `MaleText_loc5`='在那些結界運作之前不准休息。我們不能受到干擾。', `MaleText_loc7`='No descanséis hasta que los resguardos funcionen. Que nada nos moleste.' WHERE `ID`=54170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 괴물 머리를 한 대 차 줬는데, 제 발만 아팠어요.', `MaleText_loc4`='我想要踢碎一只玉石怪物的脑袋，结果却把爪子弄伤了。', `MaleText_loc5`='我用力踢翠玉獸的腦袋，結果反而害我的腳掌受傷了。', `MaleText_loc7`='Intenté darle un sopapo a un monstruo de jade en la cabeza, pero me hice daño en la zarpa.', `FemaleText_loc1`='비취 괴물 머리를 한 대 차 줬는데, 제 발만 아팠다니까요.', `FemaleText_loc4`='我想要踢碎一只玉石怪物的脑袋，结果却把爪子弄伤了。', `FemaleText_loc5`='我用力踢翠玉獸的腦袋，結果反而害我的腳掌受傷了。', `FemaleText_loc7`='Intenté darle un sopapo a un monstruo de jade en la cabeza, pero me hice daño en la zarpa.' WHERE `ID`=54171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 괴물을 또 만나면, 와다다 때려서 가루를 만들 거예요.', `MaleText_loc4`='下次再让我看见这些青玉怪物，我要狠狠揍扁它们。', `MaleText_loc5`='下次再看到翠玉獸，我一定會狠很揍牠的「要害」。', `MaleText_loc7`='La próxima vez que vea un monstruo de jade le voy a dar un puñetazo ya sabes dónde.', `FemaleText_loc1`='비취 괴물을 또 만나면, 이렇게 이렇게 때려서 박살낼 거예요.', `FemaleText_loc4`='下次再让我看见这些青玉怪物，我要狠狠揍扁它们。', `FemaleText_loc5`='下次再看到翠玉獸，我一定會狠很揍牠的「要害」。', `FemaleText_loc7`='La próxima vez que vea un monstruo de jade le voy a dar un puñetazo ya sabes dónde.' WHERE `ID`=54172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옥의 마녀가 제 친구들을 모두 잡아간 건 아니겠죠? 정말 무서운 할머니 같아요.', `FemaleText_loc4`='但愿青玉巫婆没把我的朋友们都抓走。她超级恐怖的。', `FemaleText_loc5`='我希望玉巫婆沒抓到我所有的朋友。她太可怕了。', `FemaleText_loc7`='Espero que la Bruja de Jade no atrapara a todos mis amigos. Da un montón de miedo.' WHERE `ID`=54173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 당신에게 꼭 붙어 있을 거예요. 제 경호원이 되어 주세요!', `FemaleText_loc4`='我会紧紧跟着你的。你就是我的保镖了！', `FemaleText_loc5`='我跟緊你了。你可以當我的保鏢!', `FemaleText_loc7`='Me quedo contigo. ¡Puedes ser mi guardaespaldas!' WHERE `ID`=54174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 용감하시네요. 그렇게 용감해질 수 있는 방법을 제게도 가르쳐 주실래요?', `FemaleText_loc4`='你真勇敢。你能教我怎么变勇敢吗？', `FemaleText_loc5`='你非常勇敢。能教我怎麼和你一樣勇敢嗎?', `FemaleText_loc7`='Eres supervaliente. ¿Me enseñas a ser supervaliente?' WHERE `ID`=54175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기 위쪽에서 황혼의 군대가 나타납니다.', `MaleText_loc4`='暮光大军出现在峡谷上方的悬崖边。', `MaleText_loc5`='暮光的軍隊開始出現在峽谷邊緣。', `MaleText_loc7`='Las fuerzas Crepusculares comienzan a aparecer en los bordes de los cañones.' WHERE `ID`=54176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포위되었군. 난 복병을 막을 테니 자네들은 승천자를 상대하게.', `MaleText_loc4`='我们被包围了——你们去对付那个升腾者，我会处理伏兵。', `MaleText_loc5`='我們被包圍了。去解決那個卓越者，我來纏住這些伏兵。', `MaleText_loc7`='Estamos rodeados. ¡Maten al ascendiente, yo me encargo de los emboscados!' WHERE `ID`=54177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜?', `MaleText_loc4`='你好啊。', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Sí?' WHERE `ID`=54178;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 작은 섬이 아니에요, $n. 노스렌드에 견줄 만한 대륙이라고요!$b$b아직까지 왜 발견되지 않았는지는 여전히 수수께끼에요.', `FemaleText_loc4`='这可不是什么小岛，$n。这是一片足以媲美诺森德的大陆！$b$b至于它为什么一直没有被发现，现在我们还不得而知。', `FemaleText_loc5`='這可不是個小島，$n。這是一片可以和北裂境匹敵的大地!$b$b為什麼至今無人發現這裡，則仍是一個謎題。', `FemaleText_loc7`='Esto no es una simple isla, $n. Es un continente, probablemente más grande que Rasganorte.$b$bEs un misterio que lleve tanto tiempo sin descubrir.' WHERE `ID`=54179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호젠 길잡이와 함께 간 것이 썩 좋은 생각은 아니었던 것 같아요.', `FemaleText_loc4`='带上个猢狲向导恐怕不是什么好主意。', `FemaleText_loc5`='帶一隻猴人當嚮導或許不是個好主意。', `FemaleText_loc7`='Es posible que llevar un guía hozen no haya sido la mejor idea del mundo.' WHERE `ID`=54180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속하십시오, 리코.', `MaleText_loc4`='继续，里克。', `MaleText_loc5`='繼續說吧，瑞可。', `MaleText_loc7`='Vamos, Riko.', `FemaleText_loc1`='계속하세요, 리코.', `FemaleText_loc4`='继续，里克。', `FemaleText_loc5`='繼續說吧，瑞可。', `FemaleText_loc7`='Vamos, Riko.' WHERE `ID`=54181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 다음에는 무슨 일이 있었습니까, 키린?', `MaleText_loc4`='后来怎么样了，琪麟？', `MaleText_loc5`='後來發生了什麼事，卡玲?', `MaleText_loc7`='¿Qué pasó después, Kiryn?', `FemaleText_loc1`='그 다음에는 무슨 일이 있었나요, 키린?', `FemaleText_loc4`='后来怎么样了，琪麟？', `FemaleText_loc5`='後來發生了什麼事，卡玲?', `FemaleText_loc7`='¿Qué pasó después, Kiryn?' WHERE `ID`=54182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 이야기를 들려주십시오, 쇼키아.', `MaleText_loc4`='让我听听你其余的报告，夏琪亚。', `MaleText_loc5`='說說接下來的部份吧，修基雅。', `MaleText_loc7`='Sigue con el resto de tu informe, Shokia.', `FemaleText_loc1`='나머지 이야기를 들려주세요, 쇼키아.', `FemaleText_loc4`='让我听听你其余的报告，夏琪亚。', `FemaleText_loc5`='說說接下來的部份吧，修基雅。', `FemaleText_loc7`='Sigue con el resto de tu informe, Shokia.' WHERE `ID`=54183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로덴을 상대해라. 만노로스는 내가 맡지.', `MaleText_loc4`='你去对付瓦罗森。玛诺洛斯是我的。', `MaleText_loc5`='解決瓦羅森。瑪諾洛斯讓我來。', `MaleText_loc7`='Encárguense de Varo''then. Mannoroth es mío.' WHERE `ID`=54184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 뭐라는 생물이냐?$b$b<잠시 말을 멈추더니, 눈이 휘둥그레지는 판다렌>$b$b맙소사... 저 아름다운 초록색 피부 좀 봐!', `FemaleText_loc4`='你是什么东西啊？$b$b<熊猫人停顿了一下，睁大了眼睛。>$b$b天呐……看看那碧绿的皮肤！', `FemaleText_loc5`='你是哪一種生物?$b$b<熊貓人停了下來，眼睛睜大。>$b$b天啊...看看這美妙的綠皮膚!', `FemaleText_loc7`='¿Qué tipo de criatura eres?$b$b<La pandaren hace una pausa y abre los ojos.>$b$bVaya... ¡mira qué piel verde tan preciosa!' WHERE `ID`=54186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 오크입니다, 부인. 몇 가지 질문을 해도 되겠습니까?', `MaleText_loc4`='我是个兽人，女士。我能问您几个问题吗？', `MaleText_loc5`='我是個獸人，女士。你介意我問妳幾個問題嗎?', `MaleText_loc7`='Soy un orco, señora. ¿Te importa si te hago unas preguntas?', `FemaleText_loc1`='저는 오크입니다, 부인. 몇 가지 질문을 해도 되겠습니까?', `FemaleText_loc4`='我是个兽人，女士。我能问您几个问题吗？', `FemaleText_loc5`='我是個獸人，女士。你介意我問妳幾個問題嗎?', `FemaleText_loc7`='Soy un orco, señora. ¿Te importa si te hago unas preguntas?' WHERE `ID`=54187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무너무 수리술술 맛있게 잘 넘어갔습니다.', `MaleText_loc4`='那酒真是太顺口了。', `MaleText_loc5`='口感實在太－順暢了。', `MaleText_loc7`='Me ha sabido de fábula.', `FemaleText_loc1`='너무너무 수리술술 맛있게 잘 넘어갔습니다.', `FemaleText_loc4`='那酒真是太顺口了。', `FemaleText_loc5`='口感實在太－順暢了。', `FemaleText_loc7`='Me ha sabido de fábula.' WHERE `ID`=54189;
