UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블라우스 조각을 잃어버렸습니다. 다른 블라우스 조각을 얻을 수 있는지요?', `MaleText_loc4`='我把布弄丢了。能再裁一块给我吗？', `MaleText_loc5`='我的布不見了。你可以再幫我撕一塊布嗎?', `MaleText_loc7`='He perdido mi ropa. ¿Me puedes conseguirme otra?', `FemaleText_loc1`='블라우스 조각을 잃어버렸어요. 다른 블라우스 조각을 얻을 수 있나요?', `FemaleText_loc4`='我把布弄丢了。能再裁一块给我吗？', `FemaleText_loc5`='我的布不見了。你可以再幫我撕一塊布嗎?', `FemaleText_loc7`='He perdido mi ropa. ¿Me puedes conseguirme otra?' WHERE `ID`=54192;
