UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼결속을 하찮게 생각하지 마십시오. 모구가 영혼껍질을 만들어내기 시작했으니, 놈들이 전쟁을 준비하고 있음이 분명합니다.', `MaleText_loc4`='可别小看了这些缚灵仪式。一旦魔古族开始大量制造灵俑，就说明他们已经在策划战争了。', `MaleText_loc5`='別小看練習縛靈術這件事。如果魔古在生產魔傀，可以肯定他們是在準備戰爭。', `MaleText_loc7`='No te tomes la práctica de vinculación de espíritus a la ligera. Si los mogu están realizando pruebas, ten por seguro que se están preparando para la guerra.' WHERE `ID`=54194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순록이 화를 내기 전에 여우 숲으로 돌아가야 합니다!', `MaleText_loc4`='快趁你的雄鹿发怒之前赶回狐狸森林去！', `MaleText_loc5`='在你的鹿生氣之前回到狐林!', `MaleText_loc7`='¡Vuelve a la Arboleda del Zorro antes de que tu venado se enfade!', `FemaleText_loc1`='순록이 화를 내기 전에 여우 숲으로 돌아가야 합니다!', `FemaleText_loc4`='快趁你的雄鹿发怒之前赶回狐狸森林去！', `FemaleText_loc5`='在你的鹿生氣之前回到狐林!', `FemaleText_loc7`='¡Vuelve a la Arboleda del Zorro antes de que tu venado se enfade!' WHERE `ID`=54195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 아침 바람 마을은 이쪽이야.', `MaleText_loc4`='嘿，$p！晨息村往这儿走。', `MaleText_loc5`='嘿，$p!晨風村往這裡走。', `MaleText_loc7`='¡Eh! La Aldea Brisa Temprana está por aquí.' WHERE `ID`=54196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 정령 셋을 무사히 데려오는 게 무엇보다도 중요하다네. 나는 직접 그 일을 하기엔 너무 늙었고, 아이사와 지는 물론 강하지만 너무 외골수로 자기 이상을 추구하는 경향이 있어.$B$B자네는 영웅의 자질을 모두 갖추었고, 그 둘에겐 없는 중용의 덕도 갖추었네. 자네가 이 일을 해줘야 해.', `MaleText_loc4`='我们必须得把剩下三个灵魂安全带回来。我年事已高，力不从心，而考虑到他们的力量，艾莎和季又太过固执。$B$B你具备英雄应有的一切品质，以及他们所欠缺的平衡。必须由你完成这项任务。', `MaleText_loc5`='平安帶回剩下的三位魂靈是十分重要的任務。我老得沒辦法親自去做，而艾莎和紀雖然擁有力量，卻都同樣沈溺於自己的理想中。$B$B你擁有身為英雄的一切特質，和他們兩人所不具備的平衡。你必須去完成這項任務。', `MaleText_loc7`='Es crucial que traigamos a los tres espíritus restantes sanos y salvos. Yo soy demasiado viejo, y Aysa y Ji, a pesar de sus virtudes, son demasiado obcecados con sus ideales.$b$bTú posees todas las cualidades de un héroe junto con un equilibrio que a ellos les falta. Debes llevar a cabo esta tarea.' WHERE `ID`=54197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웃는 바람의 마루에 가려면 사원 꼭대기에 올라가야 하네.', `MaleText_loc4`='我要去笑风山，请送我到寺院的顶层。', `MaleText_loc5`='我得到寺廟頂端才能出發前往大氣高原。', `MaleText_loc7`='Necesito llegar a lo alto del templo para viajar a la Meseta del Aire.', `FemaleText_loc1`='웃는 바람의 마루에 가려면 사원 꼭대기에 올라가야 하네.', `FemaleText_loc4`='我要去笑风山，请送我到寺院的顶层。', `FemaleText_loc5`='我得到寺廟頂端才能出發前往大氣高原。', `FemaleText_loc7`='Necesito llegar a lo alto del templo para viajar a la Meseta del Aire.' WHERE `ID`=54198;
