UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암호술사의 해독 반지를 충전해 주실 수 있을까요?', `MaleText_loc4`='你能帮我的地火操纵者的解码环充能吗？', `MaleText_loc5`='你可以替密譯師的解碼戒指充能嗎?', `MaleText_loc7`='¿Puedes recargar mi anillo descodificador de criptomántico?', `FemaleText_loc1`='암호술사의 해독 반지를 충전해 주실 수 있을까요?', `FemaleText_loc4`='你能帮我的地火操纵者的解码环充能吗？', `FemaleText_loc5`='你可以替密譯師的解碼戒指充能嗎?', `FemaleText_loc7`='¿Puedes recargar mi anillo descodificador de criptomántico?' WHERE `ID`=54203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 축제다운 행사에요.', `FemaleText_loc4`='多么欢乐的活动啊。', `FemaleText_loc5`='真是熱鬧啊。', `FemaleText_loc7`='¡Qué evento tan festivo!' WHERE `ID`=54204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 저는 정신나간 양조장이라고 불리는 섀도푸어 양조사의 제자예요.$b$B안전에는 신경을 쓰지 않고 맛을 추구한 그 자의 무모한 시도 때문에, 수많은 존재들이 다치고 병에 걸렸고, 이제 이 지역의 야생 생물들까지도 그 미친 음료의 영향을 받고 있어요. 그는 악당이에요. 이제 당신이 저를 도와주시면 막을 수 있어요.', `FemaleText_loc4`='你好！我是酒仙影斟的徒弟，他就是那个被称为疯酒师的熊猫人。$b$B他无视安全、不计后果追求酒香的行为，已导致了不计其数的伤害和疾病。现在，就连当地的野生动物都察觉到他的疯狂酿酒行为了。他是个罪人，我需要你的帮助来阻止他。', `FemaleText_loc5`='歡迎!我是人稱瘋狂釀酒師的熊貓人「釀酒大師影傾」的學徒。$b$b他魯莽追求釀酒風味的行為創造出無數的傷病，就連這區域裡的野生動植物也受到他瘋狂之酒的影響。他是個壞蛋，我需要你的幫助來阻止他。', `FemaleText_loc7`='¡Hola! Soy la aprendiza del maestro cervecero Trago Oscuro, un pandaren al que ahora llaman el cervecero loco.$b$BSu deseo de sabor por encima de la seguridad ha provocado innumerables accidentes y enfermedades, y ahora hasta la fauna de la zona paga por sus destilados. Es un villano; necesito tu ayuda para detenerlo.' WHERE `ID`=54205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 소금 평원과는 완전히 다른 곳이군요.', `FemaleText_loc4`='这一点都不像闪光平原。', `FemaleText_loc5`='這裡跟閃光平原差真多。', `FemaleText_loc7`='No hay nada como El Desierto de Sal.' WHERE `ID`=54206;
