UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 불량 식품이 아주 많군요. 그런데 과연 맛은 어떤지 모르겠습니다.', `MaleText_loc4`='这里有着大量的垃圾食品，但到底好不好吃呢？', `MaleText_loc5`='這裡真多垃圾食物，不過還是一樣好吃就是了。', `MaleText_loc7`='Un montón de comida basura, ¡pero está deliciosa!', `FemaleText_loc1`='여긴 불량 식품이 아주 많네요. 그런데 과연 맛은 어떤지 모르겠어요.', `FemaleText_loc4`='这里有着大量的垃圾食品，但到底好不好吃呢？', `FemaleText_loc5`='這裡真多垃圾食物，不過還是一樣好吃就是了。', `FemaleText_loc7`='Un montón de comida basura, ¡pero está deliciosa!' WHERE `ID`=54217;
