UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 모두 별문제 없어 보이는군요.', `MaleText_loc4`='这里的一切都很井井有条。', `MaleText_loc5`='一切看起來都風平浪靜，沒什麼問題。', `MaleText_loc7`='Parece que todo está en orden por aquí.', `FemaleText_loc1`='여긴 모두 별문제 없어 보이네요.', `FemaleText_loc4`='这里的一切都很井井有条。', `FemaleText_loc5`='一切看起來都風平浪靜，沒什麼問題。', `FemaleText_loc7`='Parece que todo está en orden por aquí.' WHERE `ID`=54219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 허술해 보이지만, 이 정도면 충분하지. 넌 길을 모르는 것 같군. 싸움은 좀 할 줄 아는 것 같고...
$b저 앞엔 수백 마리의 악마가 있다. 혼자 가는 건 미친 짓이야.', `MaleText_loc4`='嗯，虽然鲁莽，但能力也足够了。你看起来还有点战斗力，只是需要一点指导。
$b前面足有好几百个恶魔，一个人冲上去无异于自杀：', `MaleText_loc5`='稀鬆平常，但還過得去。你看起來是可戰之力，只是需要方向。
$b前面有數百隻惡魔，單獨前往只是自殺的行為。', `MaleText_loc7`='Arriesgado, pero adecuado. Pareces ser bastante $gdiestro:diestra; en el combate y necesitar dirección.
$bHay cientos de demonios ahí delante, sería un suicidio ir solo:' WHERE `ID`=54220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 괜찮아 보이는군요.', `MaleText_loc4`='目前看来还不错。', `MaleText_loc5`='目前看起來還不錯。', `MaleText_loc7`='No está mal.', `FemaleText_loc1`='아직은 괜찮아 보이네요.', `FemaleText_loc4`='目前看来还不错。', `FemaleText_loc5`='目前看起來還不錯。', `FemaleText_loc7`='No está mal.' WHERE `ID`=54221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있군요... 아주 재미있습니다.', `MaleText_loc4`='有趣……非常有趣。', `MaleText_loc5`='很有趣...非常有趣。', `MaleText_loc7`='Interesante... Muy interesante.', `FemaleText_loc1`='재미있어요... 아주 재미있네요.', `FemaleText_loc4`='有趣……非常有趣。', `FemaleText_loc5`='很有趣...非常有趣。', `FemaleText_loc7`='Interesante... Muy interesante.' WHERE `ID`=54222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오너라, 스톰레이지. 내 보여주마. 불타는 군단의 군주를 배신하면 어떤 일이 벌어지는지 말이다!', `MaleText_loc4`='来吧，怒风，我要让你看看，敢于背叛军团之主的人会有什么下场。', `MaleText_loc5`='來吧，怒風，我會讓你看看背叛軍團領主的下場。', `MaleText_loc7`='Ven, Tempestira. Te mostraré lo que les ocurre a los que traicionan al señor de la Legión.' WHERE `ID`=54223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 우릴 잘 숨겨줄 것이다.
$b난 어둠장막으로 몸을 숨길 수 있지. 그리고 너한테도 이 마법을 걸어줄 수 있다.
$b어둠장막이 있다고 아예 안 보이게 되는 건 아니지만, 적과 적당한 거리만 유지한다면 들키지 않는다.', `MaleText_loc4`='阴影能很好地掩盖我们的行迹。
$b这个暗影斗篷遮掩了我的身形，也可以将它的魔法灌注到你身上。
$b它不能让我们隐身，可只要我们和敌人保持距离，就不会被发现。', `MaleText_loc5`='陰影可以隱藏我們。
$b我被這件暗影披風所掩蔽，我也可以將它的魔法延展到你們身上。
$b雖然無法讓我們徹底隱形，但只要我們跟敵人保持距離，就能維持匿蹤隱藏的狀態。', `MaleText_loc7`='Las sombras nos esconderán.
$bEstoy oculto por este manto de las Sombras y puedo imbuirte su magia.
$bNo nos hará invisibles, pero mientras guardemos las distancias con nuestros enemigos permaneceremos ocultos.' WHERE `ID`=54224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 위해!', `MaleText_loc4`='为你而战，艾萨拉。', `MaleText_loc5`='為你而戰，艾薩拉。', `MaleText_loc7`='Por ti, Azshara.' WHERE `ID`=54225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원 바깥에 서 있는 자들은 누구도 널 볼 수 없지만, 네가 누굴 공격하거나 피해를 입으면 마법이 사라진다.
$b내가 신호를 주기 전까진 몸을 잘 숨기고 있는 게 좋을 것이다. 정면으로 상대하기엔 악마가 너무 강하고 수도 많으니까.', `MaleText_loc4`='你身周的这个环能够让外面的人看不到你，可只要你进行攻击或者受到伤害，幻象就会消失。
$b我建议你隐藏起来，直到我发出指令为止。这些恶魔太强大了，我们无法与他们正面对抗。', `MaleText_loc5`='任何在圈圈之外的人都看不到你，但這個幻術會在你攻擊或受傷時消退。
$b我建議你，除非我要你現身，否則維持隱蔽的狀態。這些惡魔十分強大，要正面衝突太過危險。', `MaleText_loc7`='Todo lo que esté fuera de ese círculo no podrá verte, pero la ilusión desaparecerá si atacas o recibes daño.
$bTe aconsejo que permanezcas $goculto:oculta; a no ser que te diga lo contrario. Esos demonios son demasiado poderosos como para plantarles cara mediante la fuerza bruta.' WHERE `ID`=54226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 악마들은 제가 맡지요. 엘룬이여, 제 화살을 이끄소서!', `FemaleText_loc4`='我来对付这些恶魔。艾露恩，请您指引我的箭矢！', `FemaleText_loc5`='我會解決這些惡魔。伊露恩，指引我的箭!', `FemaleText_loc7`='Me ocuparé de los demonios. ¡Elune, guía mis flechas!' WHERE `ID`=54227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 온갖 귀여운 동물들 좀 보십시오!', `MaleText_loc4`='快看这些动物，真可爱！', `MaleText_loc5`='看看那些可愛的動物啊!', `MaleText_loc7`='¡Mira todos esos animales adorables!', `FemaleText_loc1`='여기 온갖 귀여운 동물들 좀 보세요!', `FemaleText_loc4`='快看这些动物，真可爱！', `FemaleText_loc5`='看看那些可愛的動物啊!', `FemaleText_loc7`='¡Mira todos esos animales adorables!' WHERE `ID`=54228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엘룬의 빛이여, 지켜주소서!', `FemaleText_loc4`='艾露恩之光，救救我！', `FemaleText_loc5`='伊露恩之光，救我!', `FemaleText_loc7`='¡Luz de Elune, sálvame!' WHERE `ID`=54229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 너무 귀엽군요!', `MaleText_loc4`='噢……真可爱！', `MaleText_loc5`='噢...好可愛唷!', `MaleText_loc7`='Oh... ¡Qué monada!', `FemaleText_loc1`='아... 너무 귀여워요!', `FemaleText_loc4`='噢……真可爱！', `FemaleText_loc5`='噢...好可愛唷!', `FemaleText_loc7`='Oh... ¡Qué monada!' WHERE `ID`=54230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 저 혼자 상대하지요!', `FemaleText_loc4`='我可以暂时击退他们！', `FemaleText_loc5`='我會先擋著他們!', `FemaleText_loc7`='¡Los retendré por el momento!' WHERE `ID`=54231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<걱정스러운 듯 얼굴을 찌푸리며 당신과 시체 사이를 가로막는 코라스트라자>$B$B미안해요, $n. 이건 우리 붉은용군단이 직접 처리해야 할 내부적인 문제입니다.$B$B부디 바깥의 다른 이들을 도와주세요.', `FemaleText_loc4`='<科拉丝塔萨在你和附近的尸体间来回踱步，她的眉头因为担心而皱了起来。>$B$B我很抱歉，$n。这是红龙军团的私事。$B$B请你先出去帮帮其他人。', `FemaleText_loc5`='<寇菈史卓莎一臉愁容地走到你和旁邊的屍體中間。>$B$B很抱歉，$n。這是紅龍軍團要解決的一件私事。$B$B請到外頭看看其他人需不需要你的協助。', `FemaleText_loc7`='<Corastrasza se coloca entre el cadáver y tú. La preocupación se refleja en su rostro contrito.>$B$BLo siento, $n. Esto es una cuestión personal que debe resolver el Vuelo Rojo.$B$BIntenta ayudar a los que están fuera.' WHERE `ID`=54232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데가 위험에 처했습니다! 엘룬의 축복에 힘입어 악마를 처치하십시오!', `MaleText_loc4`='泰兰德顶不住了！快使用艾露恩的祝福击退恶魔！', `MaleText_loc5`='泰蘭妲正在被圍攻!快使用伊露恩的祝福逼退惡魔!', `MaleText_loc7`='¡Tyrande no aguantará! ¡Usa la Bendición de Elune para hacer que los demonios retrocedan!', `FemaleText_loc1`='티란데가 위험에 처했습니다! 엘룬의 축복에 힘입어 악마를 처치하십시오!', `FemaleText_loc4`='泰兰德顶不住了！快使用艾露恩的祝福击退恶魔！', `FemaleText_loc5`='泰蘭妲正在被圍攻!快使用伊露恩的祝福逼退惡魔!', `FemaleText_loc7`='¡Tyrande no aguantará! ¡Usa la Bendición de Elune para hacer que los demonios retrocedan!' WHERE `ID`=54233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가게에 여유 공간이 조금만 더 있었다면, 너희 모두 달라란으로 데려갔을 텐데.', `MaleText_loc4`='如果我的商店能大一点就好了，我就能把你们全带回达拉然去了。', `MaleText_loc5`='如果我的店裡面還有更多的空間，我一定會把你們全部帶到達拉然去。', `MaleText_loc7`='Si tuviese más sitio en mi almacén, os llevaría a todos conmigo a Dalaran.', `FemaleText_loc1`='내 가게에 여유 공간이 조금만 더 있었다면, 너희 모두 달라란으로 데려갔을 거야.', `FemaleText_loc4`='如果我的商店能大一点就好了，我就能把你们全带回达拉然去了。', `FemaleText_loc5`='如果我的店裡面還有更多的空間，我一定會把你們全部帶到達拉然去。', `FemaleText_loc7`='Si tuviese más sitio en mi almacén, os llevaría a todos conmigo a Dalaran.' WHERE `ID`=54234;
