UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데가 힘을 되찾고 일어섭니다!', `MaleText_loc4`='泰兰德又振作起来了！', `MaleText_loc5`='泰蘭妲又自己站了起來!', `MaleText_loc7`='¡Tyrande ya puede seguir aguantando!', `FemaleText_loc1`='티란데가 힘을 되찾고 일어섭니다!', `FemaleText_loc4`='泰兰德又振作起来了！', `FemaleText_loc5`='泰蘭妲又自己站了起來!', `FemaleText_loc7`='¡Tyrande ya puede seguir aguantando!' WHERE `ID`=54236;
