UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='검은용 알의 행방이 미궁에 빠져 있습니다.$B$B뭐라도 알아냈나요, $n?', `FemaleText_loc4`='我们很不走运，没能追踪到丢失的黑龙蛋。$B$B你那儿有什么发现吗，$n？', `FemaleText_loc5`='我們還是沒有找到失蹤的黑龍蛋。$B$B你有任何斬獲嗎，$n?', `FemaleText_loc7`='Nuestra investigación sobre el paradero del huevo de dragón Negro desaparecido no nos ha llevado a ninguna parte.$B$B¿Has descubierto algo, $n?' WHERE `ID`=54238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠...', `MaleText_loc4`='唔……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm...', `FemaleText_loc1`='흠...', `FemaleText_loc4`='唔……', `FemaleText_loc5`='嗯...', `FemaleText_loc7`='Mmm...' WHERE `ID`=54239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 있었습니까? 뭘 도둑맞은 거지요?', `MaleText_loc4`='这儿出什么事了？什么东西被偷了？', `MaleText_loc5`='這裡發生了什麼事?什麼東西被偷了?', `MaleText_loc7`='¿Qué pasó aquí? ¿Qué se llevaron?', `FemaleText_loc1`='여기서 무슨 일이 있었나요? 뭘 도둑맞은 거지요?', `FemaleText_loc4`='这儿出什么事了？什么东西被偷了？', `FemaleText_loc5`='這裡發生了什麼事?什麼東西被偷了?', `FemaleText_loc7`='¿Qué pasó aquí? ¿Qué se llevaron?' WHERE `ID`=54240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동물은 통을 얼마나 많이 들 수 있는 거지?', `MaleText_loc4`='这些动物到底能背几个桶啊？', `MaleText_loc5`='不知道這些動物能載多少桶呢?', `MaleText_loc7`='Me pregunto cuántos barriles pueden llevar estos animales.', `FemaleText_loc1`='이 동물은 통을 얼마나 많이 들 수 있는 건가요?', `FemaleText_loc4`='这些动物到底能背几个桶啊？', `FemaleText_loc5`='不知道這些動物能載多少桶呢?', `FemaleText_loc7`='Me pregunto cuántos barriles pueden llevar estos animales.' WHERE `ID`=54241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사람들은 얼마나 빨리 움직일 수 있는 거지?', `MaleText_loc4`='这些家伙能跑多快？', `MaleText_loc5`='不知道這些傢伙能跑多快呢?', `MaleText_loc7`='Me pregunto a qué velocidad se pueden mover.', `FemaleText_loc1`='이 사람들은 얼마나 빨리 움직일 수 있는 건가요?', `FemaleText_loc4`='这些家伙能跑多快？', `FemaleText_loc5`='不知道這些傢伙能跑多快呢?', `FemaleText_loc7`='Me pregunto a qué velocidad se pueden mover.' WHERE `ID`=54242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 좋은 동물들이군...', `MaleText_loc4`='这些动物非常出色……', `MaleText_loc5`='這些動物看起來相當強壯...', `MaleText_loc7`='Esos son unos animales tremendísimos...', `FemaleText_loc1`='정말 좋은 동물들이구나...', `FemaleText_loc4`='这些动物非常出色……', `FemaleText_loc5`='這些動物看起來相當強壯...', `FemaleText_loc7`='Esos son unos animales tremendísimos...' WHERE `ID`=54243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 지금은 세상을 떠난 레아스트라자라는 용을 아시나요? 조금 괴상한 구석이 있는 용이었죠. 종종 필멸자인 고블린의 형태를 취하고는 황야의 땅에 숨어 지내곤 했어요.$B$B레아스트라자는 그곳에서 검은용 알을 하나 훔쳐서 정화할 계획을 세웠어요. 검은용군단, 그리고 타락한 대지의 수호자인 데스윙과의 연결을 완전히 끊는 거죠.', `FemaleText_loc4`='你和已故的巨龙瑞亚丝塔萨熟悉吗？那家伙有点不正常。她经常以普通地精的形象在荒芜之地出没。$B$B瑞亚丝塔萨提出了窃取一颗黑龙蛋，并将之净化的计策，以切断它与黑龙军团，以及堕落的大地守护者，死亡之翼间的联系。', `FemaleText_loc5`='你認識已故的莉雅史卓莎那頭龍嗎?她有點古怪，經常變身成哥布林的樣子在荒蕪之地出沒$B$B莉雅史卓莎想出了一個點子，偷走一顆黑龍蛋，將它淨化，切斷它與黑龍軍團和墮落的大地守護者死亡之翼之間的聯繫。', `FemaleText_loc7`='¿Has oído hablar de la difunta Rheastrasza? No estaba muy bien. Solía pasearse por las Tierras Inhóspitas en su forma mortal de goblin.$B$BA Rheastrasza se le ocurrió un plan para robar y purificar un huevo de dragón Negro, cortando su relación con el Vuelo Negro y el Guardián de la Tierra corrupto, Alamuerte.' WHERE `ID`=54244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 악마들을 상대하죠?', `MaleText_loc4`='我们该怎么对付这些恶魔？', `MaleText_loc5`='我們要怎樣解決那些惡魔?', `MaleText_loc7`='¿Qué vamos a hacer con los demonios?', `FemaleText_loc1`='어떻게 악마들을 상대하죠?', `FemaleText_loc4`='我们该怎么对付这些恶魔？', `FemaleText_loc5`='我們要怎樣解決那些惡魔?', `FemaleText_loc7`='¿Qué vamos a hacer con los demonios?' WHERE `ID`=54245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 어둠장막으로 저를 숨겨 주세요.', `MaleText_loc4`='我准备好躲入你的暗影斗篷了。', `MaleText_loc5`='我已經準備好藏身於你的暗影披風。', `MaleText_loc7`='Estoy listo para que me ocultes con tu manto de las Sombras.', `FemaleText_loc1`='준비됐습니다. 어둠장막으로 저를 숨겨 주세요.', `FemaleText_loc4`='我准备好躲入你的暗影斗篷了。', `FemaleText_loc5`='我已經準備好藏身於你的暗影披風。', `FemaleText_loc7`='Estoy lista para que me ocultes con tu manto de las Sombras.' WHERE `ID`=54246;
