UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하하하하! 맛이 어떠냐, 스톰레이지?', `MaleText_loc4`='啊哈哈哈哈。受不了了吧，怒风？', `MaleText_loc5`='哇哈哈哈哈。滋味如何啊，怒風?', `MaleText_loc7`='Ja, ja, ja, ja, ja, ja. ¿Has tenido suficiente, Tempestira?' WHERE `ID`=54249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁도 없이 내게 등을 돌리다니...', `MaleText_loc4`='你怎么敢背叛我？', `MaleText_loc5`='你竟然敢背叛我?', `MaleText_loc7`='¿Cómo te atreves a darme la espalda?' WHERE `ID`=54250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단이 바닥에 쓰러졌습니다! 만노로스가 새로운 대상을 찾습니다!', `MaleText_loc4`='伊利丹被打倒了！玛诺洛斯正在寻找新目标！', `MaleText_loc5`='伊利丹被撞倒了!瑪諾洛斯正在找新的目標!', `MaleText_loc7`='¡Illidan ha caído al suelo! ¡Mannoroth busca un nuevo objetivo!', `FemaleText_loc1`='일리단이 바닥에 쓰러졌습니다! 만노로스가 새로운 대상을 찾습니다!', `FemaleText_loc4`='伊利丹被打倒了！玛诺洛斯正在寻找新目标！', `FemaleText_loc5`='伊利丹被撞倒了!瑪諾洛斯正在找新的目標!', `FemaleText_loc7`='¡Illidan ha caído al suelo! ¡Mannoroth busca un nuevo objetivo!' WHERE `ID`=54251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단이 힘을 되찾았습니다!', `MaleText_loc4`='伊利丹又恢复了！', `MaleText_loc5`='伊利丹站起來了!', `MaleText_loc7`='¡Illidan se ha recuperado!', `FemaleText_loc1`='일리단이 힘을 되찾았습니다!', `FemaleText_loc4`='伊利丹又恢复了！', `FemaleText_loc5`='伊利丹站起來了!', `FemaleText_loc7`='¡Illidan se ha recuperado!' WHERE `ID`=54252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛 중의 빛이여... 실망을 안겨드려 죄송합니다... 나의 아즈샤라...', `MaleText_loc4`='光中之光……我让你失望了。我很抱歉……我的艾萨拉……', `MaleText_loc5`='聖光之光...我令你失望了。對不起，艾薩拉...', `MaleText_loc7`='Luz de luces... te he fallado. Lo siento... Azshara mía...' WHERE `ID`=54253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검이 만노로스의 지옥불 갑옷을 꿰뚫었다! 지금 공격해!', `MaleText_loc4`='剑刃刺穿了他的地狱火盔甲！快击败他！', `MaleText_loc5`='劍劃開了他的地獄護甲!打倒他!', `MaleText_loc7`='¡La espada ha perforado su armadura infernal! ¡Acaben con él!' WHERE `ID`=54254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로덴의 마법검이 땅에 떨어집니다!', `MaleText_loc4`='瓦罗森的魔法长剑掉在了地上！', `MaleText_loc5`='瓦羅森的魔法劍掉到了地上!', `MaleText_loc7`='¡La espada mágica de Varo''then cae al suelo!', `FemaleText_loc1`='바로덴의 마법검이 땅에 떨어집니다!', `FemaleText_loc4`='瓦罗森的魔法长剑掉在了地上！', `FemaleText_loc5`='瓦羅森的魔法劍掉到了地上!', `FemaleText_loc7`='¡La espada mágica de Varo''then cae al suelo!' WHERE `ID`=54255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살게라스 님, 실망시키지 않겠습니다! 당신의 불타는 주먹으로 이 세상을 부숴, 모든 것이 불꽃과 암흑 속에서 다시 태어나게 하소서!', `MaleText_loc4`='萨格拉斯大人，我是不会让你失望的！用你的熔岩之拳横扫这个世界吧，让它在烈焰与黑暗中重生！', `MaleText_loc5`='薩格拉斯領主，我不會令你失望!揮舞你燃燒的雙拳撼動這個世界，使它在烈焰和黑暗中重生!', `MaleText_loc7`='¡Lord Sargeras, no te fallaré! Golpea este mundo con tu puño de lava para que renazca en llamas y oscuridad.' WHERE `ID`=54256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 아직도 샘과 연결돼 있잖아! 만노로스를 집중 공격해라! 놈이 집중하지 못하게 해!', `MaleText_loc4`='他仍然与永恒之井连接在一起！集中攻击玛诺洛斯！不能让他专心施法！', `MaleText_loc5`='他還是跟井連結在一起!集中攻擊瑪諾洛斯!我們必須干擾他的注意力!', `MaleText_loc7`='¡Sigue vinculado con el pozo de algún modo! ¡Centren sus ataques en Mannoroth! ¡Debemos desviar su atención!' WHERE `ID`=54257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일리단, 화살이 다 떨어졌어! 달의 여신이여, 내일 밤에도 당신의 빛을 볼 수 있도록 저희를 암흑에서 보호해 주십시오!', `FemaleText_loc4`='伊利丹，我的箭用光了！月亮女神，请庇护我们不受黑暗的侵袭，保佑我们见到明晚的月光！', `FemaleText_loc5`='伊利丹，我沒箭了!月之女神啊，在黑暗中保護我們，讓我們能在今後再次見證你的光芒!', `FemaleText_loc7`='Illidan, ¡no me quedan flechas! Diosa luna, protégenos de la oscuridad, ¡ilumínanos con tu luz una noche más!' WHERE `ID`=54258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그래! 그분의 타오르는 눈길이 느껴진다. 그분이 곧 강림하신다... 곧! 그분이 오시면 이 세계는 무너지고, 네놈들은 먼지로 돌아가리라!', `MaleText_loc4`='是的……是的！我能感觉到他的灼热目光，他已经很近……很近了！然后，你们的世界将被毁灭，你们的生命归于虚无！', `MaleText_loc5`='沒錯...沒錯!我可以感到他燃燒的雙眼看著我...如此靠近!你們的世界會被毀滅，你們的生命都終結!', `MaleText_loc7`='¡Sí... sí! Siento sus ojos abrasadores sobre mí, está cerca... tan cerca! Y después, el mundo se derrumbará, ¡sus vidas no valen nada!' WHERE `ID`=54259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 커다란 악마의 차원문이 열립니다!', `MaleText_loc4`='一座巨大的恶魔传送门在附近开启了！', `MaleText_loc5`='一個巨大的惡魔傳送門在旁邊開啟了!', `MaleText_loc7`='¡Un portal demoníaco enorme se abre cerca!', `FemaleText_loc1`='근처에 커다란 악마의 차원문이 열립니다!', `FemaleText_loc4`='一座巨大的恶魔传送门在附近开启了！', `FemaleText_loc5`='一個巨大的惡魔傳送門在旁邊開啟了!', `FemaleText_loc7`='¡Un portal demoníaco enorme se abre cerca!' WHERE `ID`=54260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만노로스, 이 세상에서 살게라스의 힘을 가진 게 너 혼자인 줄 아느냐! 잘 봐라!', `MaleText_loc4`='掌握萨格拉斯力量的可不止你一个，玛诺洛斯！看招！', `MaleText_loc5`='你不是唯一能施展薩格拉斯力量的人，瑪諾洛斯!看好了!', `MaleText_loc7`='¡No eres el único que posee el poder de Sargeras, Mannoroth! ¡Contempla!' WHERE `ID`=54261;
