UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데가 쓰러집니다! 엘룬의 빛이 꺼집니다!', `MaleText_loc4`='泰兰德精疲力尽了！艾露恩之光熄灭了！', `MaleText_loc5`='泰蘭妲倒下了!伊露恩之光熄滅了!', `MaleText_loc7`='¡Tyrande se derrumba! ¡La Luz de Elune se extingue!', `FemaleText_loc1`='티란데가 쓰러집니다! 엘룬의 빛이 꺼집니다!', `FemaleText_loc4`='泰兰德精疲力尽了！艾露恩之光熄灭了！', `FemaleText_loc5`='泰蘭妲倒下了!伊露恩之光熄滅了!', `FemaleText_loc7`='¡Tyrande se derrumba! ¡La Luz de Elune se extingue!' WHERE `ID`=54263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 우리 종족의 구세주가 될 것이다! 반드시, 내 운명을 실현하고야 말겠다!', `MaleText_loc4`='我将成为全族的救世主！我将履行我的使命！', `MaleText_loc5`='我會成為我們人民的救星!我會達成我的宿命!', `MaleText_loc7`='¡Seré el salvador de nuestro pueblo! ¡¡¡Cumpliré con mi destino!!!' WHERE `ID`=54264;
