UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[악마어] 레보스 일 옥 모르다나스 알킴 마즈 나즈테로스. 알킴 지안테 마즈레 미슌 테 나가스!', `MaleText_loc4`='[恶魔语]Revos ill ok mordanas archim maz naztheros! Archim xi ante maz-re mishun te nagas！', `MaleText_loc5`='[惡魔語]Revos ill ok mordanas archim maz naztheros.  Archim xi ante maz-re mishun te nagas!', `MaleText_loc7`='[Demoníaco] ¡Revos ill ok mordanas archim maz naztheros! ¡Archim xi ante maz-re mishun te nagas!' WHERE `ID`=54266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 움직여야 하네. 준비됐나?', `MaleText_loc4`='我们必须继续前进，你们准备好了吗？', `MaleText_loc5`='我們得繼續前進。準備好了嗎?', `MaleText_loc7`='Tenemos que seguir adelante, ¿estás $gpreparado:preparada;?' WHERE `ID`=54267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데에게 달의 여신의 반짝이는 빛이 깃들었습니다!', `MaleText_loc4`='泰兰德沐浴在月神的光辉之中！', `MaleText_loc5`='泰蘭妲全身灌注著月之女神的耀眼光芒!', `MaleText_loc7`='¡Tyrande está imbuida de la luz resplandeciente de la diosa luna!', `FemaleText_loc1`='티란데에게 달의 여신의 반짝이는 빛이 깃들었습니다!', `FemaleText_loc4`='泰兰德沐浴在月神的光辉之中！', `FemaleText_loc5`='泰蘭妲全身灌注著月之女神的耀眼光芒!', `FemaleText_loc7`='¡Tyrande está imbuida de la luz resplandeciente de la diosa luna!' WHERE `ID`=54268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이끌어 주십시오.', `MaleText_loc4`='带路吧。', `MaleText_loc5`='帶路吧。', `MaleText_loc7`='Guíanos.', `FemaleText_loc1`='이끌어 주세요.', `FemaleText_loc4`='带路吧。', `FemaleText_loc5`='帶路吧。', `FemaleText_loc7`='Guíanos.' WHERE `ID`=54269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말퓨리온, 그가 해냈어! 차원문이 무너지고 있어!', `FemaleText_loc4`='玛法里奥，他成功了！传送门崩溃了！', `FemaleText_loc5`='瑪法里恩，他做到了!傳送門在崩塌了!', `FemaleText_loc7`='¡Malfurion... lo ha logrado! ¡El portal se desmorona!' WHERE `ID`=54270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼! 승리가 눈앞에 있는데 어떻게 이런 일이! 내가 빈손으로 그분께 돌아갈 것 같으냐! 난... 이 초라한 세계를 떠날 수 없어! 안 돼... 안 돼애애애애!', `MaleText_loc4`='不……不！我不能让到手的胜利白白溜走！我不能带着一场失败回去见他！我不能……这样……离开这个可悲的世界！不，不——！！！！！', `MaleText_loc5`='不...不!勝利應該是屬於我的!我不會失敗地回到他面前!我不會...在這個可悲的世界...被撕裂!絕不-!!!!!', `MaleText_loc7`='¡No... no! ¡No me arrebatarán esta victoria! ¡No regresaré a él con una derrota! ¡No... me arrancarán... de este patético mundo! ¡No! ¡¡¡NooooOOOOOOOO!!!' WHERE `ID`=54271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 영혼을 손에 넣었군. 서둘러라! 이 세계가 무너지기 전에 시간의 차원문을 통과해라!', `MaleText_loc4`='巨龙之魂安全了。快，在这个世界分裂之前进入时光传送门。', `MaleText_loc5`='巨龍之魂已經安全了。快，在世界崩壞前進入時光傳送門!', `MaleText_loc7`='El Alma de dragón vuelve a estar a salvo. ¡Rápido, hacia el portal del tiempo, antes de que este mundo se derrumbe!' WHERE `ID`=54272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 영혼과 차원문의 연결이 끊어졌습니다! 용의 영혼이 영원의 샘에 끌려들어 갑니다!', `MaleText_loc4`='巨龙之魂与传送门之间的联系被切断了！它正在坠入永恒之井！', `MaleText_loc5`='巨龍之魂與傳送門之間的連結已經斷了!巨龍之魂開始往下方的井墜落!', `MaleText_loc7`='¡El vínculo del Alma de dragón con el portal se ha roto! ¡El Alma se precipita hacia el Pozo!', `FemaleText_loc1`='용의 영혼과 차원문의 연결이 끊어졌습니다! 용의 영혼이 영원의 샘에 끌려들어 갑니다!', `FemaleText_loc4`='巨龙之魂与传送门之间的联系被切断了！它正在坠入永恒之井！', `FemaleText_loc5`='巨龍之魂與傳送門之間的連結已經斷了!巨龍之魂開始往下方的井墜落!', `FemaleText_loc7`='¡El vínculo del Alma de dragón con el portal se ha roto! ¡El Alma se precipita hacia el Pozo!' WHERE `ID`=54273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 여기 어둠 속이다.', `MaleText_loc4`='我在暗影之中。', `MaleText_loc5`='在這裡，陰影之中。', `MaleText_loc7`='Aquí, en las sombras.' WHERE `ID`=54274;
