UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우, 또 뵙네요, 멋쟁이 씨! 근육이 정말 끝내주는군요!', `MaleText_loc4`='喔，又路过了，美人儿！你的身材真火辣！', `MaleText_loc5`='噢，再走過一次，小可愛!你背部的肌肉線條真美!', `MaleText_loc7`='¡Oooh, vuelve a pasar, fiera! ¡Tus músculos traseros están muy bien tonificados!', `FemaleText_loc1`='오우, 또 뵙네요, 멋쟁이 씨! 근육이 정말 끝내주는데요!', `FemaleText_loc4`='喔，又路过了，美人儿！你的身材真火辣！', `FemaleText_loc5`='噢，再走過一次，小可愛!你背部的肌肉線條真美!', `FemaleText_loc7`='¡Oooh, vuelve a pasar, fiera! ¡Tus músculos traseros están muy bien tonificados!' WHERE `ID`=54278;
