UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우후, 자기! 이봐요, 당신 말입니다, $c님! 지적인 토론을 하면서도 매력적인 태도를 잃지 않는 여자한테 관심 없으신지요?', `MaleText_loc4`='甜心！嗨，$c！你对伶牙俐齿魅力四射的女人感兴趣吗？', `MaleText_loc5`='寶貝!嘿，$c!你對於在做這種事時還能保持對話理性，外表動人的女人感興趣嗎?', `MaleText_loc7`='¡Cielo! ¡Hey, $c! ¿Te interesa una mujer que pueda mantener una conversación inteligente y ser atractiva al mismo tiempo?', `FemaleText_loc1`='어머, 자기! 이봐요, 당신 말이에요, $c님! 지적인 토론을 하면서도 매력적인 태도를 잃지 않는 여자한테 관심 없으신가요?', `FemaleText_loc4`='甜心！嗨，$c！你对伶牙俐齿魅力四射的女人感兴趣吗？', `FemaleText_loc5`='寶貝!嘿，$c!你對於在做這種事時還能保持對話理性，外表動人的女人感興趣嗎?', `FemaleText_loc7`='¡Cielo! ¡Hey, $c! ¿Te interesa una mujer que pueda mantener una conversación inteligente y ser atractiva al mismo tiempo?' WHERE `ID`=54280;
