UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살고 싶다면 따라와라. 내가 이 세상을 구하는 걸 보여 주지!', `MaleText_loc4`='如果你想活着看到我拯救这个世界的话，就跟我走！', `MaleText_loc5`='如果你想要活著看我拯救世界，最好跟我來!', `MaleText_loc7`='¡Ven conmigo si quieres vivir lo suficiente como para verme salvar este mundo!' WHERE `ID`=54284;
