UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마가 너무 많군. 처리할 시간이 없어.', `MaleText_loc4`='恶魔太多，时间不够了。', `MaleText_loc5`='太多惡魔了，時間不夠啊。', `MaleText_loc7`='Tantos demonios y tan poco tiempo.' WHERE `ID`=54288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 먹을 것 좀 사주시면 화요일에 꼭 갚겠습니다요.', `MaleText_loc4`='我很乐意在周二来支付今天汉堡的钱。', `MaleText_loc5`='今天的漢堡我會很樂意在星期二那天付錢給你。', `MaleText_loc7`='Te prometo que el martes te pago lo que me des hoy para una hamburguesa.', `FemaleText_loc1`='지금 먹을 것 좀 사주시면 화요일에 꼭 갚아 드릴게요.', `FemaleText_loc4`='我很乐意在周二来支付今天汉堡的钱。', `FemaleText_loc5`='今天的漢堡我會很樂意在星期二那天付錢給你。', `FemaleText_loc7`='Te prometo que el martes te pago lo que me des hoy para una hamburguesa.' WHERE `ID`=54289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두 바보 같은 얼라이언스 군대 때문입죠. 내 농장 바로 뒤에 경비탑을 지어 버리다니...', `MaleText_loc4`='这都是他们的错，愚蠢的联盟军队。居然在我的农场背后修建他们的哨塔。', `MaleText_loc5`='這都是他們的錯，愚蠢的聯盟軍隊。非得把他們的哨塔蓋在我的農場後面。', `MaleText_loc7`='Todo es culpa del maldito ejército de la Alianza... Tenían que construir sus torres justo detrás de mi granja.', `FemaleText_loc1`='이건 모두 바보 같은 얼라이언스 군대 때문이랍니다. 내 농장 바로 뒤에 경비탑을 지어 버리다니...', `FemaleText_loc4`='这都是他们的错，愚蠢的联盟军队。居然在我的农场背后修建他们的哨塔。', `FemaleText_loc5`='這都是他們的錯，愚蠢的聯盟軍隊。非得把他們的哨塔蓋在我的農場後面。', `FemaleText_loc7`='Todo es culpa del maldito ejército de la Alianza... Tenían que construir sus torres justo detrás de mi granja.' WHERE `ID`=54290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 모두 바보 같은 오크족 때문입죠. 내 농장을 모두 불태워 버리다니...', `MaleText_loc4`='这都是他们的错，愚蠢的兽人。居然放火烧我的农场。', `MaleText_loc5`='這都是他們的錯，愚蠢的獸人。居然放火燒我的農場。', `MaleText_loc7`='Todo es culpa de los estúpidos orcos. Tenían que quemar mi granja hasta los cimientos.', `FemaleText_loc1`='이건 모두 바보 같은 오크족 때문이랍니다. 내 농장을 모두 불태워 버리다니...', `FemaleText_loc4`='这都是他们的错，愚蠢的兽人。居然放火烧我的农场。', `FemaleText_loc5`='這都是他們的錯，愚蠢的獸人。居然放火燒我的農場。', `FemaleText_loc7`='Todo es culpa de los estúpidos orcos. Tenían que quemar mi granja hasta los cimientos.' WHERE `ID`=54291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르지 않아도 놈들은 죗값을 치를 거다...', `MaleText_loc4`='很快，他们就会得到应有的报应。', `MaleText_loc5`='等時候到了，他們會得到應有的懲罰。', `MaleText_loc7`='Recibirán su merecido, a su debido tiempo.' WHERE `ID`=54292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위치를 간파당했네. 피곤하겠지. 하지만 위상들이 우릴 기다리고 있네.', `MaleText_loc4`='我们被发现了。我知道你们很累，但我们不能让巨龙们等太久！', `MaleText_loc5`='我們被發現了。我知道你累了，但我們不能再讓守護巨龍等下去!', `MaleText_loc7`='Nos han descubierto. Sé que están cansados, ¡pero no podemos hacer esperar a los Aspectos!' WHERE `ID`=54294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 축제에는 이 늙은 그립타도 아주 즐거울 거야...', `MaleText_loc4`='逛逛这个马戏团能让老格里伏塔放松一下……', `MaleText_loc5`='馬戲團開放時，老格利夫塔就輕鬆了...', `MaleText_loc7`='El viejo Griftah lo pasará bien en la feria...' WHERE `ID`=54295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호 악마 하나가 수백 명의 엘프를 학살하는 것도 봤다. 조심해라.', `MaleText_loc4`='我亲眼看到一个守护恶魔屠杀了上百个精灵。放轻脚步。', `MaleText_loc5`='我見過一隻守護者惡魔屠殺上百個精靈。小心點。', `MaleText_loc7`='He visto a un solo demonio guardián masacrar a cientos de elfos. Camina con cuidado.' WHERE `ID`=54296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 지나가야겠군. 놈들을 막을 테니, 준비해.', `MaleText_loc4`='我会拦住他们，准备通过。', `MaleText_loc5`='我會遮蔽他們視線，好通過這裡。準備好。', `MaleText_loc7`='Los retendré para que podamos pasar. Preparaos.' WHERE `ID`=54297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽으로 가고 있었어. 인간들을 찾아서 말이야.', `MaleText_loc4`='我们往东走，去找那些卑鄙的人类。', `MaleText_loc5`='我們本來往東走，去找那些人類傢伙。', `MaleText_loc7`='Nosotros viajaban hacia el este, buskando a esos makakus humanos.' WHERE `ID`=54298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법이 약해지는군. 나도 건너가겠다!', `MaleText_loc4`='魔力在衰退，我快撑不住了！', `MaleText_loc5`='我的魔法在消散。我要穿過去了!', `MaleText_loc7`='Mi magia se debilita. ¡Voy a atravesarlo!' WHERE `ID`=54299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 문제도 없어서, 두 무리로 나눴어.', `MaleText_loc4`='事情一直很顺利，所以我们决定分头行动。', `MaleText_loc5`='一切順利，所以我們決定暫時分開行動。', `MaleText_loc7`='Todo iba bien, así ke nosotros deciden separarnos un rato.' WHERE `ID`=54300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼키아하고 키린은 여자들끼리 볼일이 있댔어.', `MaleText_loc4`='夏琪亚和琪麟处理姑娘们的私事去了。', `MaleText_loc5`='修基雅和卡玲有些女生的事要處理。', `MaleText_loc7`='Shokia y Kiryn se fueron a hacer kosas de chikas.' WHERE `ID`=54301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 공격해라...', `MaleText_loc4`='准备攻击……', `MaleText_loc5`='準備攻擊...', `MaleText_loc7`='Espero el ataque...' WHERE `ID`=54302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한잔 걸쳐야겠군요...', `MaleText_loc4`='该去喝一杯了……', `MaleText_loc5`='我要去喝杯東西...', `MaleText_loc7`='Hora de beber algo...', `FemaleText_loc1`='한잔 마셔야겠어요...', `FemaleText_loc4`='该去喝一杯了……', `FemaleText_loc5`='我要去喝杯東西...', `FemaleText_loc7`='Hora de beber algo...' WHERE `ID`=54303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격해라. 난 기다리는 걸 싫어한다.', `MaleText_loc4`='进攻。我可不喜欢磨蹭。', `MaleText_loc5`='攻擊吧。我不喜歡一直等。', `MaleText_loc7`='Ataquen. No me gusta que me hagan esperar.' WHERE `ID`=54304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한잔 마셔봅시다!', `MaleText_loc4`='畅饮的时刻到了！', `MaleText_loc5`='喝酒啦!', `MaleText_loc7`='¡Hora de beber!', `FemaleText_loc1`='한잔 마셔봐요!', `FemaleText_loc4`='畅饮的时刻到了！', `FemaleText_loc5`='喝酒啦!', `FemaleText_loc7`='¡Hora de beber!' WHERE `ID`=54305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쭉 들이켜십시오!', `MaleText_loc4`='干杯！', `MaleText_loc5`='乾啦!', `MaleText_loc7`='¡Bebed!', `FemaleText_loc1`='쭉 들이켜세요!', `FemaleText_loc4`='干杯！', `FemaleText_loc5`='乾啦!', `FemaleText_loc7`='¡Bebed!' WHERE `ID`=54306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술 마시는 건 힘들군요... 이제 낚시를 해야겠습니다! 아니야... 낚시가 힘들지. 그냥 술이나 마셔야겠습니다!', `MaleText_loc4`='喝酒是个累人的活儿……快来钓鱼吧！等等，我说反了……钓鱼是个无聊的活儿，快来喝几杯吧！', `MaleText_loc5`='喝酒很耗體力...該去釣魚了!等等，不太對...釣魚很無聊，該去喝酒了!', `MaleText_loc7`='Beber es una tarea agotadora... ¡Es hora de pescar! Espera, mejor no... Pescar es aburrido, ¡hora de beber!', `FemaleText_loc1`='술 마시는 건 힘드네요... 이제 낚시를 해야겠어요! 아니야... 낚시가 힘들지. 그냥 술이나 마셔야겠어요!', `FemaleText_loc4`='喝酒是个累人的活儿……快来钓鱼吧！等等，我说反了……钓鱼是个无聊的活儿，快来喝几杯吧！', `FemaleText_loc5`='喝酒很耗體力...該去釣魚了!等等，不太對...釣魚很無聊，該去喝酒了!', `FemaleText_loc7`='Beber es una tarea agotadora... ¡Es hora de pescar! Espera, mejor no... Pescar es aburrido, ¡hora de beber!' WHERE `ID`=54307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 놈은 양보해 주지. 내가 후회하게 하지 마라.', `MaleText_loc4`='我可以让你打头阵。别让我失望。', `MaleText_loc5`='第一下留給你。別讓我失望。', `MaleText_loc7`='Les dejaré asestar el primer golpe. No hagan que me arrepienta.' WHERE `ID`=54308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 인내심을 바라지 마라.', `MaleText_loc4`='我可没什么耐性。', `MaleText_loc5`='我的優點中沒有耐心這一項。', `MaleText_loc7`='La paciencia no es una de mis virtudes.' WHERE `ID`=54309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나랑 고로크만 남았어. 고로크에게 앞장서라고 했지... 덩치가 크니까.', `MaleText_loc4`='只剩下我和格罗克。我让他打头阵了……因为他又高又壮嘛。', `MaleText_loc5`='剩下我和哥羅克。我讓他領頭...因為他比較大隻嘛。', `MaleText_loc7`='Me kedó solo con Gorrok. Yo le dejó ser jefe... por eso de ser el más grande.' WHERE `ID`=54310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상을 조사하고 보니, 오두막에서 판다렌 노파가 나오더라고.', `MaleText_loc4`='调查过那些雕像后，我们看见一个女熊猫人从屋里走出来。', `MaleText_loc5`='檢查過雕像之後，我們看到這個老熊貓人女士從房子裡走出來。', `MaleText_loc7`='Tras inspeccionar las estatuas, nosotros han visto a la vieja pandaren salir de la kasa.' WHERE `ID`=54311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 조심해라.', `MaleText_loc4`='要留心联盟的人。', `MaleText_loc5`='小心聯盟的蹤跡。', `MaleText_loc7`='Ojo con la Alianza.' WHERE `ID`=54312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 와, 키린. 여자들끼리 가 보자.', `FemaleText_loc4`='来吧，琪麟。去解决点女士的私事。', `FemaleText_loc5`='走嘛，卡玲。去做做女生該做的事。', `FemaleText_loc7`='Vamos, Kiryn. Hagamos cosas de chicas.' WHERE `ID`=54313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 오두막을 조사해 보자. 얼라이언스 생존자들을 봤을지도 모르니.', `MaleText_loc4`='调查一下这个小屋。里面的人或许见过联盟的幸存者。', `MaleText_loc5`='讓我們調查一下這座小屋吧。也許他們見過聯盟的倖存者。', `MaleText_loc7`='Vamos a investigar esa cabaña. A lo mejor han visto supervivientes de la Alianza.' WHERE `ID`=54314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 오두막! 좋은 생각이야. 너 먼저 가.', `MaleText_loc4`='没错，小屋！好主意。你先走。', `MaleText_loc5`='是啊，小屋!好主意。你先上。', `MaleText_loc7`='¡Sí, la kabaña! Buena idea. Tú primero.' WHERE `ID`=54315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"출입 금지 - 면회 사절". 하!', `MaleText_loc4`='“停下——谢绝参观。”哈！', `MaleText_loc5`='禁止進入 - 謝絕訪客。哈!', `MaleText_loc7`='"No pasar - No se admiten visitas." ¡Ja!' WHERE `ID`=54316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고로크, 둘 중에 누가 좋아? 쇼키아야, 키린이야?', `MaleText_loc4`='嘿，格罗克，你喜欢哪个姑娘？夏琪亚还是琪麟？', `MaleText_loc5`='嘿，哥羅克，你喜歡哪個女生?修基雅還卡玲?', `MaleText_loc7`='Oye, Gorrok, ¿ké chika te gusta? ¿Shokia o Kiryn?' WHERE `ID`=54317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상... 마치 진짜 생물 같군. 뭔가 이상해, 리코.', `MaleText_loc4`='这些雕像……太逼真了。事情有点不对劲，里克。', `MaleText_loc5`='這些雕像...簡直就像真的一樣。這裡有點不對勁，瑞可。', `MaleText_loc7`='Estas estatuas... Es como si tuvieran vida propia. Aquí hay gato encerrado, Riko.' WHERE `ID`=54318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 누가 좋은지 알아? 키린이야. 눈이 예쁘거든.', `MaleText_loc4`='是我的话就选琪麟。她有一双漂亮的眼睛。', `MaleText_loc5`='你想知道我喜歡誰?我喜歡卡玲。她的眼睛很美。', `MaleText_loc7`='¿Sabes kuál me gusta? Kiryn. Tiene ojos bonitos.' WHERE `ID`=54319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지, 질문이라고? 하! 아하하하하!', `FemaleText_loc4`='问题？哈！啊哈哈哈哈！', `FemaleText_loc5`='疑惑嗎?哈!啊哈哈哈哈哈!', `FemaleText_loc7`='¿Preguntas? ¡Ja! ¡JAAAAAA JA JA JAAAAA!' WHERE `ID`=54320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너, "오크"는 소중한 우리 가족이 되렴!', `FemaleText_loc4`='你，“兽人”，一定能成为很不错的家族藏品！', `FemaleText_loc5`='你，「獸人」，會是我家族的優秀新成員!', `FemaleText_loc7`='Tú, "orco", ¡serás una adquisición excelente para mi familia!' WHERE `ID`=54321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 고로크. 키린이 내 마음을 받아줄까?', `MaleText_loc4`='那么，格罗克，你觉得我能追到琪麟吗？', `MaleText_loc5`='說真的，哥羅克，你覺得我和卡玲有沒有機會?', `MaleText_loc7`='Entonces, Gorrok, ¿krees que yo tiene posibilidades con Kiryn?' WHERE `ID`=54322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 일이지...?', `MaleText_loc4`='这是什么见鬼的……？', `MaleText_loc5`='見鬼的是怎麼...?', `MaleText_loc7`='¿Pero ké cosa...?' WHERE `ID`=54323;
