UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안내원이 곧 여기로 왔으면 좋겠습니다.', `MaleText_loc4`='但愿这个向导能早点到。', `MaleText_loc5`='我們希望導遊趕快到達這裡。', `MaleText_loc7`='Esperamos que el guía llegue pronto.', `FemaleText_loc1`='안내원이 곧 여기로 왔으면 좋겠어요.', `FemaleText_loc4`='但愿这个向导能早点到。', `FemaleText_loc5`='我們希望導遊趕快到達這裡。', `FemaleText_loc7`='Esperamos que el guía llegue pronto.' WHERE `ID`=54327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 관광을 아주 오래전부터 기다려 왔습니다.', `MaleText_loc4`='为了这次观光，我已经等了很久了。', `MaleText_loc5`='我等這次的導覽已經等了好久。', `MaleText_loc7`='He esperado mucho tiempo para estar en este recorrido.', `FemaleText_loc1`='이번 관광을 아주 오래전부터 기다려 왔답니다.', `FemaleText_loc4`='为了这次观光，我已经等了很久了。', `FemaleText_loc5`='我等這次的導覽已經等了好久。', `FemaleText_loc7`='He esperado mucho tiempo para estar en este recorrido.' WHERE `ID`=54328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안내원이 여기 오기는 하는 건지 슬슬 의심되는군요.', `MaleText_loc4`='我开始怀疑，这个向导永远都不会来了。', `MaleText_loc5`='我開始懷疑這個導遊是不是不來了呢。', `MaleText_loc7`='Empiezo a pensar que este guía no va a llegar nunca.', `FemaleText_loc1`='안내원이 여기 오기는 하는 건지 슬슬 의심되네요.', `FemaleText_loc4`='我开始怀疑，这个向导永远都不会来了。', `FemaleText_loc5`='我開始懷疑這個導遊是不是不來了呢。', `FemaleText_loc7`='Empiezo a pensar que este guía no va a llegar nunca.' WHERE `ID`=54329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관광을 안내하러 여기 오신 겁니까?', `MaleText_loc4`='你是来带我参观的吗？', `MaleText_loc5`='你是來導遊的?', `MaleText_loc7`='¿Has venido para guiarnos?', `FemaleText_loc1`='관광을 안내하러 여기 오신 건가요?', `FemaleText_loc4`='你是来带我参观的吗？', `FemaleText_loc5`='你是來導遊的?', `FemaleText_loc7`='¿Has venido para guiarnos?' WHERE `ID`=54330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 제 관광 안내원입니까?', `MaleText_loc4`='你是我的向导吗？', `MaleText_loc5`='你是我的導遊?', `MaleText_loc7`='¿Eres mi guía?', `FemaleText_loc1`='당신이 제 관광 안내원인가요?', `FemaleText_loc4`='你是我的向导吗？', `FemaleText_loc5`='你是我的導遊?', `FemaleText_loc7`='¿Eres mi guía?' WHERE `ID`=54331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관광을 안내하러 오신 것이 아니라면, 다른 데 가 보십시오.', `MaleText_loc4`='如果你不是我们的向导，就快走开。', `MaleText_loc5`='如果你不是來這裡當導遊的，那就走開。', `MaleText_loc7`='Si no estás aquí para ser nuestro guía, vete.', `FemaleText_loc1`='관광을 안내하러 오신 것이 아니라면, 다른 데 가 보세요.', `FemaleText_loc4`='如果你不是我们的向导，就快走开。', `FemaleText_loc5`='如果你不是來這裡當導遊的，那就走開。', `FemaleText_loc7`='Si no estás aquí para ser nuestro guía, vete.' WHERE `ID`=54332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관광을 안내하러 오셨습니까? 아니면 우리를 구경이라도 하러 오신 겁니까? 저리 가십시오.', `MaleText_loc4`='你是来带我们参观的还是来参观我们的啊？滚开。', `MaleText_loc5`='你是來導遊還是來盯著我們看的?滾吧。', `MaleText_loc7`='¿Has venido para guiarnos o para quedarte mirándonos todo el día? ¡Largo!', `FemaleText_loc1`='관광을 안내하러 오셨나요? 아니면 우리를 구경이라도 하러 오신 건가요? 저리 가세요.', `FemaleText_loc4`='你是来带我们参观的还是来参观我们的啊？滚开。', `FemaleText_loc5`='你是來導遊還是來盯著我們看的?滾吧。', `FemaleText_loc7`='¿Has venido para guiarnos o para quedarte mirándonos todo el día? ¡Largo!' WHERE `ID`=54333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 뭔가 꾸미고 있습니다. 지금까지는 우리 수송선을 직접 공격한 적이 없었거든요.', `FemaleText_loc4`='部落一定是在谋划着什么。他们以前从没直接攻击过我们的运输工具。', `FemaleText_loc5`='部落在計畫些什麼。他們以前從沒直接攻擊我們的運輸船。', `FemaleText_loc7`='La Horda trama algo. Nunca antes habían atacado nuestros transportes.' WHERE `ID`=54334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 계획이 성공했나요?', `MaleText_loc4`='成功了吗？', `MaleText_loc5`='成功了嗎?', `MaleText_loc7`='¿Funcionó?', `FemaleText_loc1`='그 계획이 성공했나요?', `FemaleText_loc4`='成功了吗？', `FemaleText_loc5`='成功了嗎?', `FemaleText_loc7`='¿Funcionó?' WHERE `ID`=54335;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿어지실지 모르겠지만, 네, 성공했답니다. 도대체 어떻게 한 건진 모르겠지만 어쨌든 레아스트라자는 검은용 알 하나를 손에 넣었어요. 그리고 타락한 검은용군단과 그 알의 연결은 완전히 끊겼다고 했죠.$B$B하지만 데스윙이 그 일에 대해 알아냈어요.$B$B데스윙은 레아스트라자를 황야의 땅에 있는 동굴 속에 몰아넣고, 그녀가 돌보던 알과 함께 파괴했죠. 적어도 데스윙은 그렇게 생각했어요. 사실 레아스트라자는 죽음의 위상을 속이려고 자기 알을 희생했답니다.$B$B이 세상에 단 하나 있는, 정화된 검은용 알은 그렇게 살아남았어요. 그리고 비밀스럽게 다른 곳에 숨겨져 있었죠!', `FemaleText_loc4`='不管你信不信，她的计划真的成功了。她弄到了一颗蛋——我现在都不知道她到底用了什么办法——而且她声称已经切断了这颗蛋和那个堕落的军团之间的联系。$B$B死亡之翼发现了这件事。$B$B他将瑞亚丝塔萨困在荒芜之地的一个洞穴里，杀害了她，并且毁掉了她的一切努力。至少他是这么认为的。其实，瑞亚丝塔萨是牺牲了她自己的蛋，骗过了死亡的化身。$B$B那颗净化过的黑龙蛋已经被秘密地送走并藏了起来！', `FemaleText_loc5`='不管你相不相信，她的計畫成功了。她取得了一顆蛋，雖然我還不確定她是怎麼做到的，但是她宣稱這顆蛋沒有受到腐化。$B$B然後死亡之翼發現了這件事。$B$B他在一個洞穴把莉雅史卓莎逼到死角，把她跟她所有努力成果都毀了。至少他這樣以為。莉雅史卓莎犧牲了她自己的蛋，瞞過了死亡化身。$B$B一顆淨化過的黑龍蛋偷偷地被藏起來了!', `FemaleText_loc7`='Lo creas o no, su plan funcionó. Consiguió un huevo, aún no sé cómo lo hizo, y dijo haber roto su relación con el Vuelo corrupto.$B$BDespués, Alamuerte lo descubrió.$B$BAcorraló a Rheastrasza en una cueva en las Tierras Inhóspitas, destruyéndola a ella y todo su trabajo. O eso pensó. Rheastrasza había sacrificado sus propios huevos para engañar al Aspecto de la Muerte.$B$BEl único y purificado huevo de dragón Negro estaba oculto, a salvo y en secreto.' WHERE `ID`=54336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 맞아요! 당시에 제가 마침 황야의 땅에 있다가 그녀를 도왔습니다.', `MaleText_loc4`='当然！我在荒芜之地的时候也帮过她的忙。', `MaleText_loc5`='當然了!我在荒蕪之地幫過她呢!', `MaleText_loc7`='¡Claro! La ayudé cuando estaba en las Tierras Inhóspitas.', `FemaleText_loc1`='아, 맞아요! 당시에 제가 마침 황야의 땅에 있다가 그녀를 도왔습니다.', `FemaleText_loc4`='当然！我在荒芜之地的时候也帮过她的忙。', `FemaleText_loc5`='當然了!我在荒蕪之地幫過她呢!', `FemaleText_loc7`='¡Claro! La ayudé cuando estaba en las Tierras Inhóspitas.' WHERE `ID`=54337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<깜짝 놀란 듯 당신을 바라보는 코라스트라자>$B$B당신이요?! 당신이 레아스트라자를 도왔다고요? 그러고도 이렇게 살아남다니!$B$B내가 당신을 과소평가했군요, $r|1이여;여;. 군주 아프라사스트라즈가 당신을 내게 보낸 것도 당연해요.$B$B그럼 그다음에 일어난 일도 기억하겠군요. 레아스트라자는 데스윙에게 죽음을 맞았어요. 하지만 그녀의 희생 덕분에 이 세상에 단 하나 있는, 정화된 검은용 알은 살아남았죠. 그리고 비밀스럽게 다른 곳에 숨겨져 있었어요.', `FemaleText_loc4`='<科拉丝塔萨又打量了你一下。>$B$B你！？你帮助过瑞亚丝塔萨？居然还能活到现在？$B$B我真是低估你了，$r。难怪阿弗拉沙斯塔兹指挥官会把你派来给我。$B$B那你肯定还记得后来发生的事：死亡之翼杀害了瑞亚丝塔萨，但由于她的牺牲，那颗净化过的黑龙蛋被秘密地送走并藏了起来。', `FemaleText_loc5`='<寇菈史卓莎多看了你一眼。>$B$B你!?是你幫了莉雅史卓莎?還活下來了?$B$B我低估你了，$r。難怪艾弗薩斯塔茲領主會派你來找我。$B$B你一定記得接下來發生的事情吧:莉雅史卓莎被死亡之翼殺死，但因為她的犧牲，一顆淨化的黑龍蛋被秘密地藏起來了。', `FemaleText_loc7`='<Corastrasza no da crédito.>$B$B¿¡Tú!? ¿Tú ayudaste a Rheastrasza? ¿Y vives para contarlo?$B$BTe he subestimado, $r. Por eso Lord Afrasastrasz te envió a mí.$B$BSeguro que recuerdas qué pasó después: Rheastrasza murió a manos de Alamuerte, pero gracias a su sacrificio un único y purificado huevo de dragón Negro se ocultó lejos en secreto.' WHERE `ID`=54338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 알에 무슨 일이 생겼나요?', `MaleText_loc4`='那颗蛋怎么了？', `MaleText_loc5`='蛋怎麼了?', `MaleText_loc7`='¿Qué pasó con el huevo?', `FemaleText_loc1`='그 알에 무슨 일이 생겼나요?', `FemaleText_loc4`='那颗蛋怎么了？', `FemaleText_loc5`='蛋怎麼了?', `FemaleText_loc7`='¿Qué pasó con el huevo?' WHERE `ID`=54339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네. 그래서 당신이 여기 오게 된 겁니다, $n. 알은 이곳 주홍빛 보루에 숨겨져 있었어요. 그런데 며칠 전, 알이 사라졌죠.$B$B누군지 몰라도 날카로운 우리 경비들의 눈을 피할 정도의 실력자예요. 도둑 중 하나는 사살되었는데, 지금 생각해 보면 우리 눈을 돌리는 미끼였던 것도 같아요. 결국 알이 사라졌잖아요.$B$B그 도둑의 시체에서 이 쪽지를 찾았습니다. 유일한 단서인데, 난해한 암호로 작성되어 있어요. 반드시 해독해야 합니다.', `FemaleText_loc4`='那就是你被派来的原因，$n。那颗蛋原本一直被藏在这里的朱红庇护所内。可几天前，它却突然消失了。$B$B不管这是谁干的，但他们确实骗过了我们最精锐的守卫。其中一个小偷在行动中被我们打死，可我现在认为，那个家伙只是个转移我们视线的幌子而已——那颗蛋就这么不见了。$B$B在他的尸体上，我们发现了这张纸条。上面有我们目前唯一的线索，可它是用一种复杂的密码写成的，我们必须先破解它。', `FemaleText_loc5`='這就是為什麼你在這裡，$n。龍蛋被藏在朱紅壁壘這裡。幾天前，它不見了。$B$B不管是誰幹的，他避開了我們警覺性最高的守衛。在偷走龍蛋的過程中，有一個賊被殺了，但是現在我相信他只是個幌子。龍蛋就這麼不見了。$B$B他的屍體上我們找到這張紙條。這是我們唯一的線索，但是它是用很深奧的密碼寫的，我們必須破譯這張紙條。', `FemaleText_loc7`='Por eso estás aquí, $n. El huevo se guardó aquí, en el Reducto Bermellón. Hace unos días, desapareció.$B$BQuien lo haya hecho consiguió eludir a los guardas más hábiles. Uno de los ladrones murió durante el secuestro, aunque ahora creo que igual se trataba de una distracción. El huevo simplemente desapareció.$B$BEn su cuerpo encontramos esta nota. Es nuestra única pista, pero está escrita en un código difícil y hay que descifrarlo.' WHERE `ID`=54340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일이 잘 풀렸어! 난 우리가 끈끈한 친구가 됐다고 생각했지.', `MaleText_loc4`='一切都非常顺利！我觉得我们真是最佳搭档。', `MaleText_loc5`='一切都進行得很順利!我覺得我們真的變親密了。', `MaleText_loc7`='¡Todo iba de maravilla! Yo sintió komo nosotros estuvieran realmente unidos.' WHERE `ID`=54341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이... 승객을 가득 태운 우리 배를 공격했소!', `MaleText_loc4`='他们……他们刚刚攻击了一艘满载乘客的船只！', `MaleText_loc5`='他們...他們就這樣攻擊載滿乘客的船!', `MaleText_loc7`='Acaban... ¡Acaban de atacar a un barco lleno de pasajeros!' WHERE `ID`=54342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 이 전쟁을 더욱 확대할 결심을 한 모양이오. 그리고 그 대족장은 내 고향 땅에 눈독을 들이고 있소!', `MaleText_loc4`='部落似乎决意要扩大这场战争的规模，酋长竟然要把战火烧到我的家乡！', `MaleText_loc5`='部落似乎決心要擴大戰事，而他們大酋長的眼光盯上了我的家鄉!', `MaleText_loc7`='¡La Horda parece empeñada en aumentar aún más las proporciones de esta guerra, y ese jefe de guerra ha puesto sus ojos en mi tierra!' WHERE `ID`=54343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 명령에 따르는 함선 500척 중에서, 하필 이 왕국의 열쇠를 품은 단 한 척이 사라졌다. 어떻게 이런 일이 있을 수가 있나?', `MaleText_loc4`='有五百艘船只任我调遣，可载有王国命脉的那艘却不见了。这怎么可能？', `MaleText_loc5`='我手上有五百艘船，偏偏載有王國鑰匙的那艘失蹤了。怎麼會這樣?', `MaleText_loc7`='Tengo quinientos barcos a mi disposición, pero el único que tiene la clave para el reino no está. ¿Cómo puede ser?' WHERE `ID`=54344;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벌써 며칠 째 잔해를 수색했습니다, 폐하. 하지만 테일러 제독이나 그의 함선을 찾을 수는 없었습니다.', `FemaleText_loc4`='我们已经清理残骸好几天了，陛下。没有找到与海军上将泰勒或他舰船有关的任何线索。', `FemaleText_loc5`='我們已經連續清理殘骸好幾天了，陛下。還是沒有泰勒上將或他的船艦的蹤影。', `FemaleText_loc7`='Hemos inspeccionado a fondo los restos, Su Majestad. No hay rastro del almirante Taylor ni de su navío.' WHERE `ID`=54345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제없습니다! 암호문을 제게 주시죠.', `MaleText_loc4`='我很乐意效劳！把密信交给我吧。', `MaleText_loc5`='我是來接應的!給我密譯的訊息吧。', `MaleText_loc7`='¡Soy quien buscas! Dame el mensaje cifrado.', `FemaleText_loc1`='문제없어요! 암호문을 제게 주시죠.', `FemaleText_loc4`='我很乐意效劳！把密信交给我吧。', `FemaleText_loc5`='我是來接應的!給我密譯的訊息吧。', `FemaleText_loc7`='¡Soy quien buscas! Dame el mensaje cifrado.' WHERE `ID`=54346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아프라사스트라즈 님이 보내서 왔습니다. 당신이 암호문을 가지고 있다던데요?', `MaleText_loc4`='是阿弗拉沙斯塔兹指挥官派我来的。他说你这里有一份密信需要破译？', `MaleText_loc5`='艾弗薩斯塔茲領主派我來的。他說你有訊息要解譯?', `MaleText_loc7`='Lord Afrasastrasz me envía. Dice que tienes un mensaje para descifrar.', `FemaleText_loc1`='아프라사스트라즈 님이 보내서 왔습니다. 당신이 암호문을 가지고 있다던데요?', `FemaleText_loc4`='是阿弗拉沙斯塔兹指挥官派我来的。他说你这里有一份密信需要破译？', `FemaleText_loc5`='艾弗薩斯塔茲領主派我來的。他說你有訊息要解譯?', `FemaleText_loc7`='Lord Afrasastrasz me envía. Dice que tienes un mensaje para descifrar.' WHERE `ID`=54347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 아픈 거지?!', `MaleText_loc4`='怎么那么疼啊？！', `MaleText_loc5`='為什麼這麼痛?!', `MaleText_loc7`='¡¿Por qué duele?!', `FemaleText_loc1`='왜 아픈 거죠?!', `FemaleText_loc4`='怎么那么疼啊？！', `FemaleText_loc5`='為什麼這麼痛?!', `FemaleText_loc7`='¡¿Por qué duele?!' WHERE `ID`=54348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것이 우리가 찾은 암호문입니다, $n. 무슨 내용인지 알겠나요?', `FemaleText_loc4`='$n，这就是我们找到的密信残片。你能看懂吗？', `FemaleText_loc5`='這個是我們找到的殘存訊息，$n。你能看得出是寫什麼嗎?', `FemaleText_loc7`='Esto es lo que queda del mensaje que encontramos, $n. ¿Lo entiendes?' WHERE `ID`=54349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 뭐냐?! 넌 누구지?! 여기가 어디야?!', `MaleText_loc4`='你是什么东西？！你是谁？！我在哪儿？！', `MaleText_loc5`='你是啥?!你是誰?!我在哪?!', `MaleText_loc7`='¿Qué eres? ¿Quién eres? ¿Dónde estoy?', `FemaleText_loc1`='넌 뭐냐?! 넌 누구지?! 여기가 어디야?!', `FemaleText_loc4`='你是什么东西？！你是谁？！我在哪儿？！', `FemaleText_loc5`='你是啥?!你是誰?!我在哪?!', `FemaleText_loc7`='¿Qué eres? ¿Quién eres? ¿Dónde estoy?' WHERE `ID`=54350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 옷은 어디로 간 거지?!', `MaleText_loc4`='我的衣服怎么了？！', `MaleText_loc5`='我的衣服怎麼了?', `MaleText_loc7`='¿Qué le ha pasado a mi ropa?', `FemaleText_loc1`='내 옷은 어디로 간 거죠?!', `FemaleText_loc4`='我的衣服怎么了？！', `FemaleText_loc5`='我的衣服怎麼了?', `FemaleText_loc7`='¿Qué le ha pasado a mi ropa?' WHERE `ID`=54351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 원했던 건 이 도시에서 친구들을 몇몇 만나는 것 뿐이오. 이런 상황을 원했던 적은 없소! 호드가 우리에게 왜 이런 짓을 하는 거요?', `MaleText_loc4`='我只不过想要进城造访几位朋友。从没想到会遇见这种事！部落为何要这么对我们？', `MaleText_loc5`='我只是想到城裡去找一些朋友。我從沒想過會發生這種事!為什麼部落要這樣對我們?', `MaleText_loc7`='Todo lo que pretendía era visitar a varios amigos que tengo en la ciudad. ¡Yo no he pedido esto! ¿Por qué nos hace esto la Horda?' WHERE `ID`=54352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공명의 수정을 소환합니다!', `MaleText_loc4`='%s召唤了一颗共鸣水晶！', `MaleText_loc5`='%s召喚了一顆共鳴水晶!', `MaleText_loc7`='¡%s invoca un cristal resonador!' WHERE `ID`=54353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼어붙어라!', `MaleText_loc4`='冻结！', `MaleText_loc5`='不准動!', `MaleText_loc7`='¡Alto!' WHERE `ID`=54354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐!', `FemaleText_loc4`='等等！', `FemaleText_loc5`='等等!', `FemaleText_loc7`='¡Espera!' WHERE `ID`=54355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람이 잦아들기를 기다린 다음에 저쪽 복도로 뛰어 몸을 숨겨야 합니다.', `FemaleText_loc4`='我们得等狂风平息下来，然后突破大厅的屏障。', `FemaleText_loc5`='我們得等風平息下來，然後衝到通道另一端的掩蔽處。', `FemaleText_loc7`='Tenemos que esperar a que los vientos amainen e intentar llegar a la estancia del fondo.' WHERE `ID`=54356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공간이 또 생길 때를 기다리세요. 그럼 저쪽에서 뵙지요.', `FemaleText_loc4`='等待另一个机会。我会在远处等你。', `FemaleText_loc5`='等待另一個空檔。我會和你和另一端碰頭。', `FemaleText_loc7`='Espera la siguiente oportunidad. Me reuniré contigo al otro lado.' WHERE `ID`=54357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기호에서 무슨 일이 있었습니까?', `MaleText_loc4`='勇者号上发生了什么事？', `MaleText_loc5`='勇氣號上發生了甚麼事?', `MaleText_loc7`='¿Qué sucedió en El Valentía?', `FemaleText_loc1`='용기호에서 무슨 일이 있었나요?', `FemaleText_loc4`='勇者号上发生了什么事？', `FemaleText_loc5`='勇氣號上發生了甚麼事?', `FemaleText_loc7`='¿Qué sucedió en El Valentía?' WHERE `ID`=54358;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 리코. 이제 다들 알았을 거야. 나머지는 키린이 얘기하면 돼.', `FemaleText_loc4`='好了，里克，$n听够了。后面的事让琪麟说吧。', `FemaleText_loc5`='好吧瑞可，我想$n聽夠了，接下來換卡玲說。', `FemaleText_loc7`='Muy bien, Riko, creo que ya escuchamos suficiente. Kiryn puede contar la parte siguiente.' WHERE `ID`=54359;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 전투함들이 우릴 막아 세우더니, 적 전사들이 용기호의 갑판으로 쏟아져 들어왔어요. 필요한 것은 모두 가져가고, 돕지 않는 이는 모두 살해하더군요. 우린 역부족이었어요...', `FemaleText_loc4`='部落的战舰拦住了我们，他们的士兵冲上勇者号的甲板。他们夺走了想要的一切，杀死了那些拒绝合作的硬骨头。我们简直寡不敌众……', `FemaleText_loc5`='部落戰艦攔住我們，他們的戰士湧上勇氣號的甲板。他們任意取走東西，並殺死那些不合作的人。我們寡不敵眾...', `FemaleText_loc7`='Las naves de guerra de la Horda nos detuvieron y sus guerreros se abalanzaron sobre la cubierta. Cogieron lo que les vino en gana y mataron a los que no cooperaron. Estábamos en inferioridad numérica.' WHERE `ID`=54360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들은 스톰윈드로 가져오던 우리 상품들을 지키던 제 부인을 붙잡아서는 바다에 던져 버렸습니다! 놈들을 이대로 내버려 둘 수는 없습니다!', `MaleText_loc4`='我妻子想要保护我们运往暴风城的货物，结果却被那群兽人抓去丢进了海里！你决不能让他们轻易逃脱！', `MaleText_loc5`='當我妻子試圖保護我們給暴風城帶去的貨物時，那些獸人把她抓起來丟進水中!你絕不能放過他們!', `MaleText_loc7`='¡Esos orcos cogieron a mi mujer y la lanzaron al agua cuando intentaba proteger las mercancías que traíamos a Ventormenta! ¡No puedes permitir que se salgan con la suya!' WHERE `ID`=54361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다펑! 어떻게 된 거니? 왜 여기 숨어 있는 거지?', `FemaleText_loc4`='大风！出什么事了？你怎么躲在这里？', `FemaleText_loc5`='大風!怎麼了?你為什麼躲在這裡?', `FemaleText_loc7`='¡Dafeng! ¿Qué ocurre? ¿Por qué te escondes aquí?' WHERE `ID`=54362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까스로 적의 무기를 하나 빼았아 맞서 싸웠지만... 적이 너무 많았소. 여기 보이시오? 난 그 도끼를 아직도 갖고 있소.', `MaleText_loc4`='我设法从攻击者手里抢来了一把武器，想要回击，可他们人太多了。看见没？我还留着那把斧子……', `MaleText_loc5`='我設法搶過攻擊者的武器並反擊，但他們人數太多了。看見沒?我手上還拿著斧頭...', `MaleText_loc7`='Conseguí robarle el arma a uno de los atacantes e intenté repeler el asalto, pero eran demasiados. Mira, aún tengo el hacha...' WHERE `ID`=54363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 배에 탑승한 후, 나는 눈을 감고 숨었소. 그 일에 대해 말하고 싶지 않소...', `MaleText_loc4`='他们上船后，我就闭眼躲了起来。求你别再让我说这个了……', `MaleText_loc5`='他們登上船之後，我閉上眼睛躲了起來。請不要逼我談論這件事...', `MaleText_loc7`='Después de que abordasen el barco, cerré los ojos y me escondí. Te ruego que no me hagas hablar de ello...' WHERE `ID`=54364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밤이 될 때까지 남쪽으로 갔어요. 쇼키아가 말했죠.', `FemaleText_loc4`='我们一直向南走到天黑。夏琪亚就说：', `FemaleText_loc5`='我們往南走，直到夜幕低垂。修基雅說:', `FemaleText_loc7`='Viajamos hacia el sur hasta la noche. Shokia dijo:' WHERE `ID`=54365;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주머니에 연막탄이 들어 있었어요. 그걸 이용하기로 했죠.$b|TInterface\\Icons\\ability_rogue_smoke.blp:32|t$b', `FemaleText_loc4`='我在口袋里找到一些烟雾弹，肯定能派上用场。$b|TInterface\\Icons\\ability_rogue_smoke.blp:32|t$b', `FemaleText_loc5`='我在包包裡找到一些煙霧彈，只能靠它們了。$b|TInterface\\Icons\\ability_rogue_smoke.blp:32|t$b', `FemaleText_loc7`='Encontré bombas de humo en mi bolsillo. Tendrían que servir.$b|TInterfaceIconsability_rogue_smoke.blp:32|t$b' WHERE `ID`=54366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적과 마주치면, 연막탄으로 맞추기로 했어요. 그러면 쇼키아가 저격총으로 처리하는 거였죠.', `FemaleText_loc4`='如果我遇到敌人的话，就可以用烟雾弹砸他们。夏琪亚的狙击枪会对付他们的。', `FemaleText_loc5`='如果遇到敵人，我會用煙霧彈丟向他們。修基雅的狙擊槍會負責剩下的事。', `FemaleText_loc7`='Si tropezara con algún enemigo, le lanzaría una bomba de humo. El rifle de Shokia se encargaría del resto.' WHERE `ID`=54367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞쪽에 모닥불 흔적이 보였어요. 조각상의 동쪽이었죠.', `MaleText_loc4`='我在前头看到了营火的痕迹，就在雕像的东边。', `MaleText_loc5`='我在前方發現了營火，就在雕像的東邊。', `MaleText_loc7`='Vi señales de una fogata más adelante, en el lado oriental de la estatua.' WHERE `ID`=54368;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미사용', `FemaleText_loc4`='UNUSED', `FemaleText_loc5`='未使用', `FemaleText_loc7`='UNUSED' WHERE `ID`=54369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='북쪽 제단에서 그를 찾았어요. 삐쩍 마른 인간 병사였지요.', `FemaleText_loc4`='我是在北部神龛找到他的：一个骨瘦如柴的人类士兵。', `FemaleText_loc5`='我在北邊的祠堂找到了他。一個骨瘦如柴的人類士兵。', `FemaleText_loc7`='En el santuario norte encontré un soldado humano de aspecto huesudo.' WHERE `ID`=54370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사냥감을 끌고 야영지로 돌아왔죠. 쇼키아도 기뻐했어요.', `FemaleText_loc4`='我带着俘虏返回了营地。夏琪亚一定会很满意的。', `FemaleText_loc5`='我把我的獵物帶回營地。修基雅會很高興的。', `FemaleText_loc7`='Volví al campamento con la presa. Shokia estaría encantada.' WHERE `ID`=54371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 화물을 받지 못하면 정말 큰일납니다!', `MaleText_loc4`='我不能再错过一次货运了！', `MaleText_loc5`='我無法承受另一船貨物的損失!', `MaleText_loc7`='¡No me puedo permitir perder otro envío!', `FemaleText_loc1`='또 화물을 받지 못하면 정말 큰일날 거예요!', `FemaleText_loc4`='我不能再错过一次货运了！', `FemaleText_loc5`='我無法承受另一船貨物的損失!', `FemaleText_loc7`='¡No me puedo permitir perder otro envío!' WHERE `ID`=54372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어로 물품을 보낼 수도 없고, 또 거기서 받을 수도 없다면... 난 망했소!', `MaleText_loc4`='要是我不能运送货物往来卡利姆多，我就完蛋了！', `MaleText_loc5`='如果我不能讓貨物進出卡林多，我就毀了!', `MaleText_loc7`='¡Si no puedo llevar mercancías a y desde Kalimdor, será mi ruina!', `FemaleText_loc1`='칼림도어로 물품을 보낼 수도 없고, 또 거기서 받을 수도 없다면... 난 망했어요!', `FemaleText_loc4`='要是我不能运送货物往来卡利姆多，我就完蛋了！', `FemaleText_loc5`='如果我不能讓貨物進出卡林多，我就毀了!', `FemaleText_loc7`='¡Si no puedo llevar mercancías a y desde Kalimdor, será mi ruina!' WHERE `ID`=54373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕은 우리의 이런 고통에 대해 신경이라도 씁니까?', `MaleText_loc4`='乌瑞恩国王会管我们的死活吗？', `MaleText_loc5`='烏瑞恩王在乎我們的處境嗎?', `MaleText_loc7`='¿Y acaso le importa nada de esto al Rey Wrynn?', `FemaleText_loc1`='린 국왕은 우리의 이런 고통에 대해 신경이라도 쓰나요?', `FemaleText_loc4`='乌瑞恩国王会管我们的死活吗？', `FemaleText_loc5`='烏瑞恩王在乎我們的處境嗎?', `FemaleText_loc7`='¿Y acaso le importa nada de esto al Rey Wrynn?' WHERE `ID`=54374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창고가 텅 비었는데 장사를 어떻게 하라는 말이오?', `MaleText_loc4`='仓库空空，我要怎么做生意？', `MaleText_loc5`='倉庫空空的要我怎麼做生意?', `MaleText_loc7`='¿Cómo se supone que debo llevar mi negocio con un almacén vacío?', `FemaleText_loc1`='창고가 텅 비었는데 장사를 어떻게 하라는 말인가요?', `FemaleText_loc4`='仓库空空，我要怎么做生意？', `FemaleText_loc5`='倉庫空空的要我怎麼做生意?', `FemaleText_loc7`='¿Cómo se supone que debo llevar mi negocio con un almacén vacío?' WHERE `ID`=54375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 키린.', `FemaleText_loc4`='好吧，琪麟。', `FemaleText_loc5`='嗯，卡玲。', `FemaleText_loc7`='Muy bien, Kiryn.' WHERE `ID`=54376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리코.', `FemaleText_loc4`='里克。', `FemaleText_loc5`='瑞可。', `FemaleText_loc7`='Riko.' WHERE `ID`=54377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 곧 야영지를 세울 거야. 우선 이 어둠을 틈타 주변 정찰을 해야겠어.', `FemaleText_loc4`='我们马上就扎营。但首先，我们要趁天黑侦察一下周围的环境。', `FemaleText_loc5`='我們很快就要紮營。首先，我們要利用黑暗的優勢進行一些偵查。', `FemaleText_loc7`='Pronto acamparemos, pero antes aprovecharemos la oscuridad para hacer algo de reconocimiento.' WHERE `ID`=54378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 생각이야. 난 전방 지역을 확인할게.', `FemaleText_loc4`='好主意。我去侦察前面那片区域。', `FemaleText_loc5`='好主意。我會偵查前頭的區域。', `FemaleText_loc7`='Buena idea. Exploraré esa zona de ahí.' WHERE `ID`=54379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼... 난 키린을 보호해 줄게.', `MaleText_loc4`='那……那我就来保护琪麟。', `MaleText_loc5`='那...那我會保護卡玲不遇到危險。', `MaleText_loc7`='Y... y yo protegerá a Kiryn del peligro.' WHERE `ID`=54380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아냐, 리코. 여기서 기다려. 이번엔 아무도 죽는 일이 없게 하고.', `FemaleText_loc4`='不，里克。你留下。这次可别再出人命了。', `FemaleText_loc5`='不，瑞可。你留在這裡。這次別讓任何人死掉了。', `FemaleText_loc7`='No, Riko. Tú te quedas aquí. Procura que esta vez no maten a nadie.' WHERE `ID`=54381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우우, 젠장...', `MaleText_loc4`='噢，知道了……', `MaleText_loc5`='啊，便便的...', `MaleText_loc7`='Ooh, mierda…' WHERE `ID`=54382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽이야, 키린.', `FemaleText_loc4`='这边，琪麟。', `FemaleText_loc5`='卡玲，往這兒。', `FemaleText_loc7`='Por aquí, Kiryn.' WHERE `ID`=54383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 엄호해 줄게. 너무 어두우니까, 공격할 대상을 표시해줘.', `FemaleText_loc4`='我就在这里掩护你。天很黑，你得帮我标出目标。', `FemaleText_loc5`='我會在這上面掩護你。天色很黑，所以你得幫我標記目標。', `FemaleText_loc7`='Te cubriré desde aquí. Está oscuro, así que tendrás que marcar a los objetivos.' WHERE `ID`=54384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정찰이 끝나면 여기서 만나.', `FemaleText_loc4`='侦察完毕在这里汇合。', `FemaleText_loc5`='完成後到這裡會合。', `FemaleText_loc7`='Nos encontraremos aquí cuando acabes.' WHERE `ID`=54385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='움직이지 마라, 인간. 넌 포위됐다.', `FemaleText_loc4`='别动，人类。你逃不了了。', `FemaleText_loc5`='別動，人類。你已經無路可逃了。', `FemaleText_loc7`='No te muevas, humano. Estás acorralado.' WHERE `ID`=54386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정확히 어떻게 날 포위했다는 거지, 언데드?', `MaleText_loc4`='我倒想看看，你怎么阻止我逃跑？', `MaleText_loc5`='你們是怎麼包圍我的，不死生物?', `MaleText_loc7`='¿Qué quieres decir con que estoy acorralado, no-muerta?' WHERE `ID`=54387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다.', `MaleText_loc4`='我明白了。', `MaleText_loc5`='原來如此。', `MaleText_loc7`='Ya veo.' WHERE `ID`=54388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 죽이지 않는 걸 다행이라고 생각하렴... 너 맛있어 보이는구나.', `FemaleText_loc4`='我没痛下杀手就算你走运了……你看着很好吃。', `FemaleText_loc5`='沒馬上宰了你算你好運...你看起來挺好吃的。', `FemaleText_loc7`='Tienes suerte de que no te mate aquí mismo. Pareces delicioso.' WHERE `ID`=54389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호라... 뭔가 수상한 일에 발을 들이셨군요, $r 님? 아, 경계하실 필요는 없습니다. 어떤 거래든, 비밀은 확실히 지켜드리니까요.$B$B당신이 가져온 이 반지는 정말 대단한 작품입니다. 물론 당장에라도 충전을 시작할 수 있습니다... 적당한 가격에요. 충전이 완료되는 데에는 당신네 기준에서 하루의 반 정도가 걸립니다. 다른 말로 하면, 12시간이지요.$B$B10,000골드 어떻습니까? 양심적인 가격입니다.', `MaleText_loc4`='我明白了……这东西见不得光，对吧，$r？噢，不用担心——我们保证对一切交易保密。$B$B你这只解码环是一个杰作。我们可以开始充能了……收费绝对低廉。按照你们那个世界的计算方法，充能大概需要半天时间。换言之，也就是十二个小时。$B$B一万个金币怎么样？这个价钱很公道了。', `MaleText_loc5`='了解...跟一些不可告人的事情有關吧，$r?噢，不用擔心...所有交易都保證隱私。$B$B你有的這個戒指品質相當高。我們可以馬上開始充能...只要花點小錢。替它充能需要你們世界半個週期的自轉。換句話說，十二個小時。$B$B只要10,000金就好了。便宜吧?', `MaleText_loc7`='Vaya... tramas negocios oscuros, ¿eh, $r? Oh, no tienes por qué preocuparte, la confidencialidad de todas las transacciones está garantizada.$B$BEse anillo tuyo es una pieza extraordinaria. Podemos comenzar el proceso de cargado... por un módico precio. La carga del anillo llevará aproximadamente la mitad del ciclo de rotación de tu mundo hasta completarse. En otras palabras: doce horas.$B$B¿Qué te parecen 10000 monedas de oro? Es lo justo.' WHERE `ID`=54390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<10,000골드를 지불합니다.>', `MaleText_loc4`='<支付10,000金。>', `MaleText_loc5`='<支付10000金。>', `MaleText_loc7`='<Paga 10000 monedas de oro.>', `FemaleText_loc1`='<10,000골드를 지불합니다.>', `FemaleText_loc4`='<支付10,000金。>', `FemaleText_loc5`='<支付10000金。>', `FemaleText_loc7`='<Paga 10000 monedas de oro.>' WHERE `ID`=54391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<전승지기가 상냥한 눈빛으로 주의 깊게 당신을 바라봅니다.>', `MaleText_loc4`='<游学者用温和的目光凝视着你。>', `MaleText_loc5`='<博學行者阿洲溫和的眼睛關注地看著你。>', `MaleText_loc7`='<Los amables ojos del eremita se posan sobre ti con atención.>' WHERE `ID`=54392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<전승지기 초가 호기심 많고 기대에 가득 찬 눈빛으로 당신을 바라봅니다.>', `MaleText_loc4`='<游学者周卓好奇又期待地看着你。>', `MaleText_loc5`='<博學行者阿洲期待地看著你。>', `MaleText_loc7`='<El eremita Cho te observa con expectación.>' WHERE `ID`=54393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 무엇이 자네를 우리 땅으로 이끌었는지 무척 궁금하군.$b$b때가 되면 판다리아의 안개가 걷히고 답이 드러날 것이네...', `MaleText_loc4`='我很好奇你为何会踏上我们的土地，陌生人。$b$b潘达利亚的迷雾迟早会给出答案的……', `MaleText_loc5`='是什麼讓你來到我們的土地上呢，陌生人。$b$b潘達利亞的霧會有找到這答案的一天...', `MaleText_loc7`='Me pregunto qué te trae a nuestras tierras.$b$bLa niebla de Pandaria nos revelará la respuesta a su debido tiempo...' WHERE `ID`=54394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='10,000골드?! 말이 됩니까?! 잠자고 있을 때 확 없애 버릴까 보다!', `MaleText_loc4`='一万金！？你这是抢劫！我非趁你睡觉的时候杀了你不可！', `MaleText_loc5`='一萬!?開什麼玩笑!我一定會趁你睡覺時幹掉你!', `MaleText_loc7`='¡¿Diez mil?! ¡Increíble! ¡Te mataré mientras duermes!', `FemaleText_loc1`='10,000골드?! 말이 됩니까?! 잠자고 있을 때 확 없애 버릴까 보다!', `FemaleText_loc4`='一万金！？你这是抢劫！我非趁你睡觉的时候杀了你不可！', `FemaleText_loc5`='一萬!?開什麼玩笑!我一定會趁你睡覺時幹掉你!', `FemaleText_loc7`='¡¿Diez mil?! ¡Increíble! ¡Te mataré mientras duermes!' WHERE `ID`=54395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표는 열심히 쫓을수록 점점 멀어지지.', `MaleText_loc4`='你越想找一样东西，就越是找不到。', `MaleText_loc5`='你越飢渴地追尋一項事物，你就越追不到它。', `MaleText_loc7`='Cuanta más ansia tienes por buscar una cosa, más te rehúye.' WHERE `ID`=54396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아를 파괴할 수는 없네.$b$b판다리아 위의 자신을 파괴할 뿐이지.', `MaleText_loc4`='谁也不能毁灭潘达利亚。$b$b野心家只会在潘达利亚碰得头破血流。', `MaleText_loc5`='人無法毀壞潘達利亞。$b$b人只會在潘達利亞上毀壞自己。', `MaleText_loc7`='Uno no puede tomar Pandaria.$b$bUno solo puede perderse en Pandaria.' WHERE `ID`=54397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러시던가요.$B$B제가 이제는 잠을 자지 않는다는 게 다행이군요.', `MaleText_loc4`='随便你。$B$B幸好我早就不睡觉了。', `MaleText_loc5`='那好吧。$B$B幸好我不再需要睡眠了。', `MaleText_loc7`='Bueno.$B$BEs una suerte que ya no necesite dormir.', `FemaleText_loc1`='그러시던가요.$B$B제가 이제는 잠을 자지 않는다는 게 다행이군요.', `FemaleText_loc4`='随便你。$B$B幸好我早就不睡觉了。', `FemaleText_loc5`='那好吧。$B$B幸好我不再需要睡眠了。', `FemaleText_loc7`='Bueno.$B$BEs una suerte que ya no necesite dormir.' WHERE `ID`=54398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까... 아니, 당신은 무엇입니까?', `MaleText_loc4`='你是谁……你是什么东西？', `MaleText_loc5`='你是誰...你是啥?', `MaleText_loc7`='Quién eres... ¿QUÉ eres?', `FemaleText_loc1`='당신은 누구세요... 아니, 당신은 무엇인가요?', `FemaleText_loc4`='你是谁……你是什么东西？', `FemaleText_loc5`='你是誰...你是啥?', `FemaleText_loc7`='Quién eres... ¿QUÉ eres?' WHERE `ID`=54399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심오한 진실은 심오한 질문을 통해서만 깨달을 수 있네.', `MaleText_loc4`='只有刨根问底，才能明察秋毫。', `MaleText_loc5`='深層的真相只能透過深入的質疑來尋得。', `MaleText_loc7`='Las grandes verdades solo se aprenden a través de las grandes preguntas.' WHERE `ID`=54400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, $r 님! 충전하는 데 시간이 오래 걸린다는 걸 기억해 주십시오.', `MaleText_loc4`='很好，$r！记住，你的解码环需要好几个小时才能彻底充能完毕。', `MaleText_loc5`='很好，$r!記得，你戒指的能量在數個小時之後才能完全充能完畢。', `MaleText_loc7`='¡Muy bien, $r! Recuerda, tu anillo no se cargará del todo hasta dentro de muchas horas.', `FemaleText_loc1`='좋습니다, $r 님! 충전하는 데 시간이 오래 걸린다는 걸 기억해 주십시오.', `FemaleText_loc4`='很好，$r！记住，你的解码环需要好几个小时才能彻底充能完毕。', `FemaleText_loc5`='很好，$r!記得，你戒指的能量在數個小時之後才能完全充能完畢。', `FemaleText_loc7`='¡Muy bien, $r! Recuerda, tu anillo no se cargará del todo hasta dentro de muchas horas.' WHERE `ID`=54401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그저 답을 가르쳐주기만 한다면, 아무것도 가르칠 수 없네.$b$b판다리아는 가르침과 배움의 땅이야.', `MaleText_loc4`='仅仅给出答案并不是为师之道。$b$b潘达利亚是授业解惑的圣地。', `MaleText_loc5`='直接提供答案無法傳承任何東西。$b$b潘達利亞是傳承和學習的土地。', `MaleText_loc7`='Limitarse a ofrecer una respuesta no es enseñar.$b$bPandaria es una tierra de enseñanza y aprendizaje.' WHERE `ID`=54402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 문제에 대한 답을 진심으로 갈망하면, 자네가 깨달을 준비가 되었을 때 그 답이 자연스럽게 자네를 찾아올 것이네.', `MaleText_loc4`='如果你真想了解这些知识，那么当你做好准备时，答案自然会从天而降。', `MaleText_loc5`='如果你真的渴望知道這些事情，答案會在你準備好時來到你的身邊。', `MaleText_loc7`='Si de verdad deseas conocer estas cosas, la respuesta vendrá cuando estés $glisto:lista; para recibirla.' WHERE `ID`=54403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='질문을 던지는 것은, 답을 알아내기 위한 마음의 준비일 뿐이네.', `MaleText_loc4`='学会发问是学习的第一步。', `MaleText_loc5`='問問題只是讓你的心準備好接受答案。', `MaleText_loc7`='Formular una pregunta es el comienzo de la preparación mental para recibir la respuesta.' WHERE `ID`=54404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와 자네 질문의 답 사이에는 아직 많은 장애물이 있네.', `MaleText_loc4`='要想解惑，你还有很多东西要学。', `MaleText_loc5`='在你和你所追尋的答案之間，還有層層阻礙。', `MaleText_loc7`='Aún se interponen demasiadas cosas entre la respuesta a tu pregunta y tú.' WHERE `ID`=54405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침묵에 귀를 기울이게, $c. 침묵이 뭐라고 말하는지 들리나?', `MaleText_loc4`='仔细聆听那寂静，$c。它说了什么？', `MaleText_loc5`='仔細聆聽這片寂靜，$c。它告訴你什麼?', `MaleText_loc7`='Escucha atentamente el silencio, $c. ¿Qué te dice?' WHERE `ID`=54406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 생각하는 법을 배워야 하네, 이방인. 성급한 질문은 자네 마음이 게으르다는 증거일 뿐이야.', `MaleText_loc4`='你必须学会思考，陌生人。这些鲁莽的问题只能显示你的懒惰。', `MaleText_loc5`='你必須學會沉思，陌生人。你急躁的問題會背叛你懶散的心智。', `MaleText_loc7`='Debes aprender a reflexionar, $gforastero:forastera;. Tus preguntas impetuosas son señal de una mente perezosa.' WHERE `ID`=54407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 답을 말하면, 마땅히 자네의 것이 되어야 할 깨우침을 방해하는 일이 될 뿐이네.', `MaleText_loc4`='如果我必须现在回答你，那你将会失去原本应得的启示。', `MaleText_loc5`='如果我現在就給你答案，我就剝奪了屬於你的體悟。', `MaleText_loc7`='Si te contestara ahora, te estaría negando la iluminación que te correspondería.' WHERE `ID`=54408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야만적인 원시 종족이 우릴 죽이려 합니다! 부디 말씀해 주십시오... 놈들을 어떻게 무찔러야 합니까?', `MaleText_loc4`='这些野蛮的猩猩想要杀了我们！告诉我……我们怎么才能打败他们？', `MaleText_loc5`='這些蠻族想要殺掉我們!告訴我...我們怎麼征服他們?', `MaleText_loc7`='¡Esos primates salvajes quieren matarnos! Dime, ¿cómo podemos vencerlos?', `FemaleText_loc1`='야만적인 원시 종족이 우릴 죽이려 해요! 부디 말씀해 주세요... 놈들을 어떻게 무찔러야 하나요?', `FemaleText_loc4`='这些野蛮的猩猩想要杀了我们！告诉我……我们怎么才能打败他们？', `FemaleText_loc5`='這些蠻族想要殺掉我們!告訴我...我們怎麼征服他們?', `FemaleText_loc7`='¡Esos primates salvajes quieren matarnos! Dime, ¿cómo podemos vencerlos?' WHERE `ID`=54409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 어디서 왔습니까? 갑작스럽게 나타난 것만 같습니다!', `MaleText_loc4`='这片大陆是从哪儿来的？简直就像凭空冒出来的一样！', `MaleText_loc5`='這塊土地打哪來的?它簡直像是憑空出現一般!', `MaleText_loc7`='¿De dónde ha salido esta tierra? ¡Es como si hubiera aparecido de la nada!', `FemaleText_loc1`='이 땅은 어디서 왔지요? 갑자기 나타난 것만 같아요!', `FemaleText_loc4`='这片大陆是从哪儿来的？简直就像凭空冒出来的一样！', `FemaleText_loc5`='這塊土地打哪來的?它簡直像是憑空出現一般!', `FemaleText_loc7`='¿De dónde ha salido esta tierra? ¡Es como si hubiera aparecido de la nada!' WHERE `ID`=54410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대... 굴복하지... 않아!', `MaleText_loc4`='绝不……屈服！', `MaleText_loc5`='永不...屈服!', `MaleText_loc7`='¡Jamás... nos rendiremos!' WHERE `ID`=54411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가! 우릴 고통받게 내버려 둬!', `MaleText_loc4`='滚开！让我们继续痛苦下去吧！', `MaleText_loc5`='走開!讓我們在這受苦!', `MaleText_loc7`='¡Vete! ¡Déjanos a solas con nuestro sufrimiento!' WHERE `ID`=54412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이...', `MaleText_loc4`='黑暗……', `MaleText_loc5`='黑暗...', `MaleText_loc7`='Oscuridad...' WHERE `ID`=54413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 평화가 없어... 안식도...', `MaleText_loc4`='不得安宁……无法安息……', `MaleText_loc5`='不得安寧...不得休息...', `MaleText_loc7`='Aquí no hay paz... No hay descanso...' WHERE `ID`=54414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 풀어다오!', `MaleText_loc4`='求求你……放了我！', `MaleText_loc5`='拜託...自由!', `MaleText_loc7`='Por favor... ¡libéranos!' WHERE `ID`=54415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코 차례! 무슨 일이 있었는지 알아! 나한테 물어봐! 나! 나!', `MaleText_loc4`='该里克了！我知道后面的故事！选我！我在这儿！', `MaleText_loc5`='換瑞可了!我知道接著發生什麼!選我!看這裡，$n!', `MaleText_loc7`='¡Es la hora de Riko! ¡Sabe lo ke pasó después! ¡Elige a mí! ¡Aquí!' WHERE `ID`=54416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어와 교역을 할 수 없는 게 나뿐이 아니라고 하더군요.', `MaleText_loc4`='听说我不是唯一一个无法运送货物进出卡利姆多的人。', `MaleText_loc5`='我不是唯一無法讓貨物進出卡林多的人。', `MaleText_loc7`='Según parece, hay más personas que tampoco pueden traer ni llevar mercancías a Kalimdor.', `FemaleText_loc1`='칼림도어와 교역을 할 수 없는 게 나뿐이 아니라고 하더군요.', `FemaleText_loc4`='听说我不是唯一一个无法运送货物进出卡利姆多的人。', `FemaleText_loc5`='我不是唯一無法讓貨物進出卡林多的人。', `FemaleText_loc7`='Según parece, hay más personas que tampoco pueden traer ni llevar mercancías a Kalimdor.' WHERE `ID`=54417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 상품을 보낼 수 없다면, 우리 식구들은 어떻게 먹여 살리겠소?', `MaleText_loc4`='要是我无法运送货物，我该怎么养家糊口？', `MaleText_loc5`='如果我無法運送我的貨品，那我要怎麼餵飽家人?', `MaleText_loc7`='¿Cómo voy a alimentar a mi familia si no puedo transportar mis mercancías?', `FemaleText_loc1`='내 상품을 보낼 수 없다면, 우리 식구들은 어떻게 먹여 살리겠어요?', `FemaleText_loc4`='要是我无法运送货物，我该怎么养家糊口？', `FemaleText_loc5`='如果我無法運送我的貨品，那我要怎麼餵飽家人?', `FemaleText_loc7`='¿Cómo voy a alimentar a mi familia si no puedo transportar mis mercancías?' WHERE `ID`=54418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕이 우리 화물을 지켜주지 못한다면, 거기 왕좌에 앉아 있을 자격이 없소!', `MaleText_loc4`='要是国王无法保证我们的货运安全，他就不配坐在那个王座上！', `MaleText_loc5`='如果國王無法保護我們貨物的安全，那他就沒資格坐在王座上!', `MaleText_loc7`='¡Si el rey ni siquiera puede hacer que pueda realizar envíos de forma segura, no se merece ese trono!', `FemaleText_loc1`='국왕이 우리 화물을 지켜주지 못한다면, 거기 왕좌에 앉아 있을 자격이 없어요!', `FemaleText_loc4`='要是国王无法保证我们的货运安全，他就不配坐在那个王座上！', `FemaleText_loc5`='如果國王無法保護我們貨物的安全，那他就沒資格坐在王座上!', `FemaleText_loc7`='¡Si el rey ni siquiera puede hacer que pueda realizar envíos de forma segura, no se merece ese trono!' WHERE `ID`=54419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 이번에는 우리를 목 졸라 죽이려 하고 있소. 너무 늦기 전에 국왕이 움직이기를 빛에 기원할 뿐이오...', `MaleText_loc4`='部落这次是想要置我们于死地了。我祈求圣光，希望国王能及时采取行动……', `MaleText_loc5`='部落這次是真的要致我們於死地了。我向聖光祈禱，希望國王能在事情無法挽救之前行動...', `MaleText_loc7`='La Horda pretende estrangularnos hasta la muerte. Espero por la Luz que el rey actúe antes de que sea demasiado tarde...', `FemaleText_loc1`='호드가 이번에는 우리를 목 졸라 죽이려 하고 있어요. 너무 늦기 전에 국왕이 움직이기를 빛에 기원할 뿐이에요...', `FemaleText_loc4`='部落这次是想要置我们于死地了。我祈求圣光，希望国王能及时采取行动……', `FemaleText_loc5`='部落這次是真的要致我們於死地了。我向聖光祈禱，希望國王能在事情無法挽救之前行動...', `FemaleText_loc7`='La Horda pretende estrangularnos hasta la muerte. Espero por la Luz que el rey actúe antes de que sea demasiado tarde...' WHERE `ID`=54420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 테라모어에 한 짓을 우리에게도 하기까지, 시간이 얼마나 있겠습니까? 국왕도 이 사실을 알아야 합니다...', `MaleText_loc4`='过不了多久，部落就会像对待塞拉摩那样对待我们了。国王必须明白……', `MaleText_loc5`='過不了多久，部落就會把他們對塞拉摩做的事拿來重演在我們身上。國王一定得了解...', `MaleText_loc7`='¿Cuánto tiempo pasará hasta que la Horda nos haga lo que le hizo a Theramore? El rey tiene que entenderlo...', `FemaleText_loc1`='호드가 테라모어에 한 짓을 우리에게도 하기까지, 시간이 얼마나 있겠어요? 국왕도 이 사실을 알아야 해요...', `FemaleText_loc4`='过不了多久，部落就会像对待塞拉摩那样对待我们了。国王必须明白……', `FemaleText_loc5`='過不了多久，部落就會把他們對塞拉摩做的事拿來重演在我們身上。國王一定得了解...', `FemaleText_loc7`='¿Cuánto tiempo pasará hasta que la Horda nos haga lo que le hizo a Theramore? El rey tiene que entenderlo...' WHERE `ID`=54421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕도 당신 말이라면 들을 겁니다. 당신은 얼라이언스의 영웅이잖습니까!', `MaleText_loc4`='乌瑞恩国王会听你的话，你是联盟的英雄！', `MaleText_loc5`='烏瑞恩王會聽你說話，你是聯盟的英雄!', `MaleText_loc7`='El Rey Wrynn te escuchará, ¡eres $gun:una; $ghéroe:heroína; para la Alianza!', `FemaleText_loc1`='린 국왕도 당신 말이라면 들을 거예요. 당신은 얼라이언스의 영웅이잖아요!', `FemaleText_loc4`='乌瑞恩国王会听你的话，你是联盟的英雄！', `FemaleText_loc5`='烏瑞恩王會聽你說話，你是聯盟的英雄!', `FemaleText_loc7`='El Rey Wrynn te escuchará, ¡eres $gun:una; $ghéroe:heroína; para la Alianza!' WHERE `ID`=54422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 큰 도움이 될지는 모르겠지만, 여기 제 탄원서를 가져가십시오.', `MaleText_loc4`='也许于事无补，但这是我的请愿书。', `MaleText_loc5`='不覺得這會有多大幫助，不過這是我的請願書。', `MaleText_loc7`='No creo que esto ayude en nada, pero aquí tienes mi petición.', `FemaleText_loc1`='이게 큰 도움이 될지는 모르겠지만, 여기 제 탄원서를 가져가세요.', `FemaleText_loc4`='也许于事无补，但这是我的请愿书。', `FemaleText_loc5`='不覺得這會有多大幫助，不過這是我的請願書。', `FemaleText_loc7`='No creo que esto ayude en nada, pero aquí tienes mi petición.' WHERE `ID`=54423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 우리 밥줄을 쥐고 있소. 국왕이 당장 함대를 보내 놈들을 혼쭐내지 않으면, 우린 끝장입니다.', `MaleText_loc4`='部落要对我们赶尽杀绝，要是国王不尽快派舰队来教训教训他们，我们就死定了。', `MaleText_loc5`='部落用經濟箝制了我們，如果國王不派艦隊去給他們一點教訓，我們就完了。', `MaleText_loc7`='La Horda está estrangulando nuestra cartera, y si el rey no envía a su flota a darles una lección, estamos condenados.', `FemaleText_loc1`='호드가 우리 밥줄을 쥐고 있어요. 국왕이 당장 함대를 보내 놈들을 혼쭐내지 않으면, 우린 끝장이에요.', `FemaleText_loc4`='部落要对我们赶尽杀绝，要是国王不尽快派舰队来教训教训他们，我们就死定了。', `FemaleText_loc5`='部落用經濟箝制了我們，如果國王不派艦隊去給他們一點教訓，我們就完了。', `FemaleText_loc7`='La Horda está estrangulando nuestra cartera, y si el rey no envía a su flota a darles una lección, estamos condenados.' WHERE `ID`=54424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 암호문이 당장은 우리가 가진 유일한 단서입니다.', `FemaleText_loc4`='那封密信是我们手中唯一的线索了。', `FemaleText_loc5`='那段密碼訊息是我們唯一有的線索。', `FemaleText_loc7`='El mensaje cifrado es la única pista que tenemos.' WHERE `ID`=54425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 남쪽으로 내려갔어. 근데 쇼키아가 갑자기 뭐라고 하더라고.', `MaleText_loc4`='我们一直往南走，直到夏琪亚开始感觉不对劲了。', `MaleText_loc5`='我們一路往南，後來修基雅開始鬼吼鬼叫。', `MaleText_loc7`='Nosotros prosiguieron hacia el sur, hasta ke Shokia empezó a kejarse por algo.' WHERE `ID`=54428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼키아는 포로를 감시하고, 키린은 가버렸어.', `MaleText_loc4`='琪麟继续前进，而夏琪亚留下看守俘虏。', `MaleText_loc5`='卡玲出去時，修基雅留下來看守囚犯。', `MaleText_loc7`='Shokia vigiló al prisionero mientras Kiryn se adelantaba.' WHERE `ID`=54429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코가 화가 났었나 봐. 조금.', `MaleText_loc4`='里克或许有点太激动了。', `MaleText_loc5`='或許瑞可是稍微發了點脾氣。', `MaleText_loc7`='Es posible ke Riko perdiera los estribos un pokito.' WHERE `ID`=54430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼키아에게 소리쳐도 소용 없었어. 난 키린을 따라가기로 했지.', `MaleText_loc4`='对着夏琪亚大喊大叫也没用。里克决定跟着琪麟走。', `MaleText_loc5`='對修基雅大吼一點用也沒有。瑞可決定要跟著卡玲。', `MaleText_loc7`='Gritarle a Shokia no tenía efecto. Así ke yo decidió seguir a Kiryn.' WHERE `ID`=54431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 주먹을 꽉 쥐고 싸울 준비를 했어.$b|TInterface\\Icons\\inv_gauntlets_05.blp:32|t  |TInterface\\Icons\\inv_inscription_pigment_emerald.blp:32|t$b', `MaleText_loc4`='我捏了捏拳头，准备开始战斗。$b|TInterface\\Icons\\inv_gauntlets_05.blp:32|t  |TInterface\\Icons\\inv_inscription_pigment_emerald.blp:32|t$b', `MaleText_loc5`='我折了折指頭關節，準備戰鬥。$b|Tinterface/Icons/inv_gauntlets_05.blp:32|t  |Tinterface/Icons/inv_inscription_pigment_emerald.blp:32|t$b', `MaleText_loc7`='Yo hizo krujir los nudillos y me preparó para el kombate.$b|TInterfaceIconsinv_gauntlets_05.blp:32|t |TInterfaceIconsinv_inscription_pigment_emerald.blp:32|t$b' WHERE `ID`=54432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저길 봐! 얼라이언스 폭격기야!', `FemaleText_loc4`='看，正前方——联盟的轰炸机！', `FemaleText_loc5`='看上面，是聯盟轟炸機!', `FemaleText_loc7`='Mira, ahí delante. ¡Un bombardero de la Alianza!' WHERE `ID`=54433;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 봤어, 쇼키아. 내가 살펴보고 올게.', `FemaleText_loc4`='我看见了，夏琪亚。我去看看。', `FemaleText_loc5`='我看到了，修基雅。我會調查看看的。', `FemaleText_loc7`='Lo veo, Shokia. Iré a echar un vistazo.' WHERE `ID`=54434;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='따라갈 생각은 하지도 마, 리코. 또 일을 망쳐 놓으면 안 돼.', `FemaleText_loc4`='你不要跟过去，里克。别再把事情搞砸了。', `FemaleText_loc5`='你最好別跟著她，瑞可。我不想再看見你把事情搞砸。', `FemaleText_loc7`='No te atrevas a seguirla, Riko. No quiero que lo estropees todo de nuevo.' WHERE `ID`=54435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐, 이 구리구리 오크! 리코 이제 멍청한 명령 안 들어!', `MaleText_loc4`='行了，你这个白痴兽人！里克受够你愚蠢的命令了！', `MaleText_loc5`='不，你這個大老粗獸人!瑞可已經聽夠你的笨命令了!', `MaleText_loc7`='¡No, makaku orco! ¡Riko ya se ha kansado de obedecer tus órdenes!' WHERE `ID`=54436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 바나나! 머리에 응가만 가득한, 바위머리통 같으니!', `MaleText_loc4`='你什么也不是，就是个一脑袋浆糊的蠢货！', `MaleText_loc5`='你什麼都不是，你...你只有一個大老粗的渾球腦袋而已!', `MaleText_loc7`='¡No eres más ke una makaku mika kon kabeza de gruka!' WHERE `ID`=54437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 도와줘! 도와줘, 쇼키아! 리코!', `FemaleText_loc4`='什——救命！救命啊，夏琪亚！里克！', `FemaleText_loc5`='救命!救命啊修基雅!瑞可!', `FemaleText_loc7`='¿Qué? ¡Socorro! ¡Ayuda, Shokia! ¡Riko!' WHERE `ID`=54438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 간다, 키린!', `MaleText_loc4`='我来救你了，琪麟！', `MaleText_loc5`='我來救妳，卡玲!', `MaleText_loc7`='¡Yo te salvará, Kiryn!' WHERE `ID`=54439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리코, 네... 네가 날 구해줬어.', `FemaleText_loc4`='里克，你……你救了我的命。', `FemaleText_loc5`='瑞可，你...你救了我的命。', `FemaleText_loc7`='Riko... Me salvaste la vida.' WHERE `ID`=54440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 리코한테 뽀뽀해 줄래?', `MaleText_loc4`='那么……嗯……能给里克一个吻吗？', `MaleText_loc5`='所以...呃...可以給瑞可親一下嗎?', `MaleText_loc7`='Entonces... eh... ¿Riko se lleva un beso?' WHERE `ID`=54441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지. 우선 복면을 벗고...', `FemaleText_loc4`='当然。等我把面具摘了……', `FemaleText_loc5`='當然了。讓我把面具拿下來...', `FemaleText_loc7`='Claro. Espera a que me quite la máscara...' WHERE `ID`=54442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야! 너 얼굴이 어떻게 된 거야!? 너... 너... 죽었어?', `MaleText_loc4`='见鬼，你的脸怎么了？你……你是死怪物？', `MaleText_loc5`='妳的臉是怎麼搞的啊?妳...妳已經死翹翹了?', `MaleText_loc7`='¿PERO KÉ COSA LE PASA A TU CARA? ¿TÚ ESTÁ... ESTÁ MU-UH-UH-ERTA?' WHERE `ID`=54443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군단에 죽음을!', `MaleText_loc4`='去死吧，燃烧军团！', `MaleText_loc5`='殺光燃燒軍團!', `MaleText_loc7`='¡Muerte a la Legión!' WHERE `ID`=54444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠장막이 사라진다!', `MaleText_loc4`='Shadowcloak Vanish! PH', `MaleText_loc5`='暗影披風消失!PH', `MaleText_loc7`='Shadowcloak Vanish! PH' WHERE `ID`=54445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오게.', `MaleText_loc4`='跟我走。', `MaleText_loc5`='跟我來。', `MaleText_loc7`='Síganme.' WHERE `ID`=54446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진위가 이 함정을 설치했다면, 놈들이 곧 돌아올 거야.$b$b<지평선 쪽을 바라보며 깜짝 놀라는 키린>$b$b어둠의 여군주시여, 굽어 살피소서... 놈들이 오고 있어. 도망가, 리코!', `FemaleText_loc4`='如果这个陷阱是锦鱼人设下的，他们很快就会回来的。$b$b<琪麟震惊地看着远处的地平线。>$b$b黑暗女王在上……他们来了。快跑啊，里克！', `FemaleText_loc5`='如果設這陷阱的是錦魚人，他們一定很快就會回來。$b$b<卡玲震驚地看著地平線的方向。>$b$b願黑暗女王眷顧我們...他們已經到了。自己逃命吧，瑞可!', `FemaleText_loc7`='Si los jinyu tendieron esta trampa, no tardarán en volver.$b$b<Kiryn alza la vista, incrédula.>$b$bQue la Dama Oscura nos proteja... están aquí. ¡Sálvate, Riko!' WHERE `ID`=54447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 리코 목숨을 바쳐서라도 널 구해 주겠어!', `MaleText_loc4`='绝不！里克要誓死保护你！', `MaleText_loc5`='不!瑞可拼死都會保護你!', `MaleText_loc7`='¡Jamás! ¡Riko te protege hasta la muerte!', `FemaleText_loc1`='안 돼! 리코 목숨을 바쳐서라도 널 구해 주겠어!', `FemaleText_loc4`='绝不！里克要誓死保护你！', `FemaleText_loc5`='不!瑞可拼死都會保護你!', `FemaleText_loc7`='¡Jamás! ¡Riko te protege hasta la muerte!' WHERE `ID`=54448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 무슨 소리가 들렸어. 키린이 붙잡힌 거야! 진위 그물에!', `MaleText_loc4`='突然，我听到一阵声响。琪麟被困住了！是锦鱼人的网！', `MaleText_loc5`='突然間，我聽到一陣聲響。卡玲被困住了!困在錦魚人的網裡!', `MaleText_loc7`='De repente, yo oyó un ruido. ¡Kiryn estaba atrapada en redes jinyu!' WHERE `ID`=54449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라, 응가들아!', `MaleText_loc4`='冲我来，混蛋！', `MaleText_loc5`='來找我啊，臭蛋!', `MaleText_loc7`='¡AKÍ, MAKAKUS!' WHERE `ID`=54450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐나?', `MaleText_loc4`='准备好了吗？', `MaleText_loc5`='你準備好了嗎?', `MaleText_loc7`='¿Vamos allá?' WHERE `ID`=54451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 망할 진위에게 본때를 보여줘야지!', `MaleText_loc4`='好吧！去杀几个恶心的锦鱼人吧！', `MaleText_loc5`='好!是該殺點錦魚人了!', `MaleText_loc7`='¡Venga! ¡Es hora de matar grukos jinyu!' WHERE `ID`=54452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 진위가... 함께 싸운다고?', `MaleText_loc4`='联盟和锦鱼人……一起打我们？', `MaleText_loc5`='聯盟和錦魚人...竟然並肩作戰?', `MaleText_loc7`='Alianza y jinyu... ¿luchando juntos?' WHERE `ID`=54453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행기에서 떨어져, 호젠 놈들아!', `MaleText_loc4`='滚出我们的飞机，该死的猢狲！', `MaleText_loc5`='別碰我們的飛機，該死的猴人!', `MaleText_loc7`='¡Aléjate del avión, escoria hozen!' WHERE `ID`=54454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아!', `MaleText_loc4`='啊啊啊！！！', `MaleText_loc5`='啊啊啊啊!', `MaleText_loc7`='¡Aaaaaah!' WHERE `ID`=54455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 마치고, 키린에게 다가가서... 칭찬해 달라고 했어.', `MaleText_loc4`='战斗结束之后，我就去找琪麟要我的……奖赏了。', `MaleText_loc5`='當我結束戰鬥時，我去找卡玲要我的...報酬。', `MaleText_loc7`='Kuando yo terminó de luchar, yo me acerkó a Kiryn para pedirle mi... rekompensa.' WHERE `ID`=54456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='중요한 점은 진위와 얼라이언스가 힘을 합쳤다는 거예요. 이리 오세요. 나머지 이야기를 들려드릴게요.', `FemaleText_loc4`='重点在于，联盟和锦鱼人结成了联军。过来跟我谈谈，$n。我来把最后一部分报告说给你听。', `FemaleText_loc5`='最重要的問題是錦魚人和聯盟成了朋友。過來和我說話，$n。我會告訴你最後一部份的報告。', `FemaleText_loc7`='Lo que importa es que la Alianza y los jinyu han unido sus fuerzas. Ven a hablar conmigo. Puedo contarte la última parte de nuestro informe.' WHERE `ID`=54457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가도 되겠나?', `MaleText_loc4`='我们要继续前进了，准备好了吗？', `MaleText_loc5`='你準備好繼續了嗎?', `MaleText_loc7`='¿Quieres continuar?' WHERE `ID`=54458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='出发！', `MaleText_loc5`='出發!', `MaleText_loc7`='Moveos.', `FemaleText_loc1`='갑시다!', `FemaleText_loc4`='出发！', `FemaleText_loc5`='出發!', `FemaleText_loc7`='Moveos.' WHERE `ID`=54459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하, $n|1이;가; 도와준 덕분에 용기호에 무슨 일이 있었는지 조사가 끝났습니다.', `FemaleText_loc4`='殿下，在$n的帮助下，我已经完成了对勇者号上所发生事情的调查。', `FemaleText_loc5`='陛下，在$n的協助下，我已完成對勇氣號上所發生事件的調查。', `FemaleText_loc7`='Su Alteza, gracias a la ayuda de $n he podido concluir la investigación sobre los incidentes a bordo de El Valentía.' WHERE `ID`=54460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 용기호를 공격해서 텔드랏실에 가지 못하게 막은 것은 사실입니다. 하지만 그건 시작에 불과했습니다...', `FemaleText_loc4`='部落确实攻击了舰船，使其无法顺利抵达泰达希尔。但那仅仅是开始……', `FemaleText_loc5`='為了阻止船隻抵達泰達希爾，部落確實攻擊了船隻。但那只是事情的開端...', `FemaleText_loc7`='La Horda atacó el barco, impidiendo que llegase a Teldrassil. Pero eso no es más que el comienzo...' WHERE `ID`=54461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오크 함대가 칼림도어의 해안에 대한 봉쇄 작전을 시작했습니다. 여객선뿐 아니라 화물을 실은 상선들도 칼림도어에 접근하지 못하고 있어요!', `FemaleText_loc4`='兽人的船队开始了对卡利姆多海岸线的封锁。所有旅行者都无法抵达那片大陆，我们商人的货运也被迫中止了！', `FemaleText_loc5`='獸人船艦已在卡林多海岸架起了封鎖線。沒有乘客可以踏上大陸一步，且我們的商人也無法運送貨物!', `FemaleText_loc7`='Los barcos orcos han comenzado un bloqueo de la costa de Kalimdor. Ningún pasajero puede llegar al continente, y no hay mercader capaz de transportar sus mercancías.' WHERE `ID`=54462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 시라, 시라. 그녀는 제가 만나본 중에 가장 아름다운 여인이고, 이 판다리아를 거니는 중 가장 착한 영혼의 소유자예요.$b$b결혼하고 싶지만, 그녀는 골든드래프트, 저는 원더브루 집안의 판다렌이죠.', `MaleText_loc4`='噢，塞拉，塞拉！她是我见过的最美丽的人儿，她有着全潘达利亚最善良的灵魂。$b$b我们想要结婚，可她姓金酿，而我姓游酒。', `MaleText_loc5`='喔錫拉，錫拉。她是我見過最美的人，也擁有全潘達利亞最好的心腸。$b$b我們想要結婚，但她是金流家的女兒，而我是蕩酒家的兒子。', `MaleText_loc7`='Oh, Syra, Syra. Es la criatura más hermosa que he visto jamás, y el alma más bondadosa que haya pisado Pandaria.$b$bQueremos casarnos, pero ella es una Brisa Dorada y yo soy un Pócima Errante.' WHERE `ID`=54463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 가로쉬가 칼림도어를 완전히 고립시키려 하는 모양이지?', `MaleText_loc4`='看来加尔鲁什是希望将卡利姆多彻底隔绝？', `MaleText_loc5`='所以卡爾洛斯想完全孤立卡林多?', `MaleText_loc7`='Así que Garrosh pretende aislar Kalimdor por completo...' WHERE `ID`=54464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드와 얼라이언스는 이런 사태를 내버려 둘 수 없다. 하지만 우리가 할 수 있는 일은 제한되어 있지. 함대가 대부분 재정비 중이니...', `MaleText_loc4`='暴风城和联盟决不会让他们得逞，可我们能采取的行动也非常有限。舰队的大部分舰船正在整修中。', `MaleText_loc5`='暴風城與聯盟決不讓他們得逞，但我們的選擇有限。大部分的艦隊都在整修。', `MaleText_loc7`='Ventormenta y la Alianza no pueden permitir que eso suceda, pero nuestras opciones son escasas. La mayor parte de la flota está siendo reparada.' WHERE `ID`=54465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독, 테라모어의 남은 함선들을 보내 나이트 엘프를 돕게 하고, 이번 작전에 참여하는 선장들에게는 모두 전쟁 허가서를 발부하라.', `MaleText_loc4`='将军，派塞拉摩的残余舰队前去协助暗夜精灵，并向任何愿意分担我们使命的船长颁发私掠许可证。', `MaleText_loc5`='上將，派塞拉摩艦隊剩下的人去支援夜精靈，並派發許可信函給任何願意協助我們的艦長。', `MaleText_loc7`='Almirante, envíe los efectivos restantes de la flota de Theramore a ayudar a los elfos de la noche, y envíe cartas lacradas a cualquier capitán que quiera apoyar nuestra causa.' WHERE `ID`=54466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 즉시 준비하겠습니다, 폐하. 이 봉쇄 작전을 저지하는 데 도움을 줄 수 있는 선장들이 몇 명 있습니다...', `FemaleText_loc4`='我会立即着手安排，国王陛下。我认识几位船长，也许能说服他们帮忙应对这次封锁……', `FemaleText_loc5`='我的王，我會立刻做出安排。我認識幾個或許能被說動來幫我們處理這個封鎖線的艦長...', `FemaleText_loc7`='Comenzaré los preparativos de inmediato, su majestad. Conozco a varios capitanes a los que podríamos convencer para que nos ayuden con dicho bloqueo...' WHERE `ID`=54467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정을 파괴해야 다른 곳으로 갈 수 있다.', `MaleText_loc4`='摧毁水晶，我们就能继续前进了。', `MaleText_loc5`='把水晶摧毀，我們再繼續。', `MaleText_loc7`='Destruyan el cristal para que podamos continuar.' WHERE `ID`=54468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 진위 마을 위쪽에 진지를 구축했어요.', `FemaleText_loc4`='我们在山上扎营，可以俯瞰锦鱼人村子。', `FemaleText_loc5`='我們在錦魚人村莊的後山上設立了一個小營地。', `FemaleText_loc7`='Establecimos un pequeño campamento en las colinas, sobre la aldea jinyu.' WHERE `ID`=54469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포로를 감시할 여유가 없어서, 그 아이가... 도망칠 수 없게 해뒀죠.', `FemaleText_loc4`='在没人看管囚犯的情况下，我必须确保他……没有逃跑的能力。', `FemaleText_loc5`='因為沒有人負責看守囚犯，所以我必須確保他...沒辦法逃跑。', `FemaleText_loc7`='Ya que no había nadie que vigilara a nuestro prisionero, tuve que asegurarme de que no pudiera escapar.' WHERE `ID`=54470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨...?', `MaleText_loc4`='什么——？', `MaleText_loc5`='什麼...?', `MaleText_loc7`='¿Qué?' WHERE `ID`=54471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저격용 총으로 진위 마을을 조준했어요.', `FemaleText_loc4`='我拿过狙击枪，瞄准了锦鱼人的村子。', `FemaleText_loc5`='我伸手拿起我的狙擊槍，朝著錦魚人村莊的方向瞄準。', `FemaleText_loc7`='Tome mi rifle de francotirador y apunté hacia la aldea jinyu.' WHERE `ID`=54472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린은 진위 마을에 도착한 후였어요. 마을 경계 지점의 수풀 뒤에 숨어 있었죠.', `FemaleText_loc4`='琪麟到锦鱼人村子去了。我看见她在村外的灌木丛里潜伏着。', `FemaleText_loc5`='卡玲成功到達錦魚人村莊，我看見她埋伏在村莊邊緣的某個樹叢裡。', `FemaleText_loc7`='Kiryn había llegado hasta la aldea jinyu. La vi esconderse entre unos matorrales, fuera de la aldea.' WHERE `ID`=54473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈을 가늘게 뜨고 키린 입술을 읽었어요. 이러더군요.', `FemaleText_loc4`='我使劲看才看清了她的口型，她说的是：', `FemaleText_loc5`='我睜大眼睛也只能勉強讀出唇型，她說:', `FemaleText_loc7`='Forzando la vista, conseguí a duras penas leerle los labios. Dijo:' WHERE `ID`=54474;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 전진할 수 있게 경비병을 모두 처치해!', `FemaleText_loc4`='杀光那些守卫，好让我继续前进！', `FemaleText_loc5`='放倒所有守衛，我要衝出去了!', `FemaleText_loc7`='¡Dispara a todos los guardias para que pueda avanzar!' WHERE `ID`=54475;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어! 한 번 더!', `FemaleText_loc4`='干得太棒了！再来一次！', `FemaleText_loc5`='做得好!再一次!', `FemaleText_loc7`='¡Buen trabajo! ¡Una vez más!' WHERE `ID`=54476;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 호젠 독이 진위에게도 효과가 있나 보자고! 나도 같이 날려버리진 마!', `FemaleText_loc4`='来看看我的猢狲毒药对锦鱼人有没有用吧！别误伤了我，夏琪亚！', `FemaleText_loc5`='來看看我的猴人毒藥對錦魚人有沒有用吧!可別把我炸飛了，修基雅!', `FemaleText_loc7`='¡A ver si mi veneno hozen funciona con los jinyu! ¡Intenta no matarme, Shokia!' WHERE `ID`=54477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을 가운데는 텅 비어 있었어요. 확실하게 하려고 키린이 폭탄을 설치했고, 제가 총으로 폭발시켰죠.', `FemaleText_loc4`='我们肃清了锦鱼人的村子。为防万一，琪麟埋下了一些炸药，由我射击引爆。', `FemaleText_loc5`='錦魚人村莊的中心已經淨空。為了保險起見，卡玲安置了一些火藥桶讓我射擊。', `FemaleText_loc7`='El centro de la aldea jinyu estaba despejado. Solo para asegurarnos, Kiryn colocó unos barriles explosivos para que los hiciera estallar.' WHERE `ID`=54478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 정도면 진위와 얼라이언스도 우릴 무서워할 거야! 빠져나가자!', `FemaleText_loc4`='就给跟我们作对的联盟和锦鱼人留个难忘的教训吧！我们走！', `FemaleText_loc5`='這下錦魚人跟聯盟就不敢招惹我們啦!我們離開吧!', `FemaleText_loc7`='¡Así aprenderán a no meterse con nosotros! ¡Larguémonos de aquí!' WHERE `ID`=54479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쇼키아, 발각됐어! 엄호해 줘!', `FemaleText_loc4`='夏琪亚，他们发现我了！掩护我！', `FemaleText_loc5`='修基雅，他們發現我了!掩護我!', `FemaleText_loc7`='Shokia, ¡me han descubierto! ¡Cúbreme!' WHERE `ID`=54480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 주변이 정리됐으니, 다시 탈출을 시도했어요.', `FemaleText_loc4`='海滩已被肃清。琪麟开始逃跑。', `FemaleText_loc5`='危險已經解除。卡玲已開始逃跑。', `FemaleText_loc7`='Estaba todo despejado. Kiryn comenzó su huida.' WHERE `ID`=54481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 진위 그물에 또 걸렸어요! 빠져나오기 직전이었는데...', `FemaleText_loc4`='该死，又是锦鱼人的网！我们差一点就成功了……', `FemaleText_loc5`='該死，又一個錦魚網!我們已很接近了...', `FemaleText_loc7`='¡Maldita sea, otra red jinyu! Con lo cerca que estaba...' WHERE `ID`=54482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을 동쪽이 갑자기 소란스러워지더군요.', `FemaleText_loc4`='我感到村子东部起了骚乱。', `FemaleText_loc5`='我感覺在東邊島上的村莊有一陣騷亂...', `FemaleText_loc7`='Sentí una perturbación en el islote del este de la aldea.' WHERE `ID`=54483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 돌아왔다, 응가들아!', `MaleText_loc4`='我回来啦，恶棍！', `MaleText_loc5`='我回來了，你們這些廢渣!', `MaleText_loc7`='¡YO HA VUELTO, MIKOS!' WHERE `ID`=54484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 갈게, 키린! 얼굴이 시체 같아도 상관없어!', `MaleText_loc4`='我来啦，琪麟！我也不在乎你那张死怪物脸！', `MaleText_loc5`='我來了，卡玲!我不介意妳奇怪的死人臉!', `MaleText_loc7`='¡Yo va, Kiryn! ¡No me importa tu kara muerta rara!' WHERE `ID`=54485;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리코...', `FemaleText_loc4`='里克……', `FemaleText_loc5`='瑞可...', `FemaleText_loc7`='Riko...' WHERE `ID`=54486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와, 키린! 어서 떠나야 돼!', `MaleText_loc4`='来吧，琪麟！我们离开这儿！', `MaleText_loc5`='快點，卡玲!快點離開這裡!', `MaleText_loc7`='¡Vamos, Kiryn! ¡Hay ke largarnos!' WHERE `ID`=54487;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으악!', `FemaleText_loc4`='哎哟！', `FemaleText_loc5`='啊!', `FemaleText_loc7`='¡AY! ¡Oye, cuidado!' WHERE `ID`=54488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=54489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 매복이군. 기습을 조심하게!', `MaleText_loc4`='又有埋伏。小心后面！', `MaleText_loc5`='又有埋伏，小心!', `MaleText_loc7`='Otra emboscada. ¡Vigilen la retaguardia!' WHERE `ID`=54490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 쉬면서 숨 좀 돌리게. 곧 출발할 테니.', `MaleText_loc4`='抓紧时间喘口气，然后我们就继续前进。', `MaleText_loc5`='我們先在這裡喘口氣，然後再繼續。', `MaleText_loc7`='Recuperen el aliento antes de que nos pongamos en marcha.' WHERE `ID`=54491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모습을 드러내라!', `MaleText_loc4`='现身吧！', `MaleText_loc5`='現身吧!', `MaleText_loc7`='¡Manifiéstate!' WHERE `ID`=54492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 오늘 우리는 판다렌 역사상 가장 무섭고 가장 끔찍한 양조사와 맞서야 합니다.$b$b그의 음료가 불러오는 위험에 대해 들어보지 못한 이는 거의 없습니다. 하지만 그는 여전히 우리와 동물들을 꼬드겨 자신의 음료를 맛보게 하고 있습니다.$b$b그를 반드시 막아야 합니다! 함께하시겠습니까?', `MaleText_loc4`='我的朋友，今天我们将要面对熊猫人有史以来最伟大也最恶毒的酒仙。$b$b现在，他酿的酒有多么危险已经是尽人皆知了，可他还是诱骗了一些人和动物喝下他酿的酒。$b$b我们必须阻止他！你愿意跟我们一起去吗？', `MaleText_loc5`='我的朋友，今天我們將面對潘達利亞有史以來最偉大也最邪惡的一名釀酒大師。$b$b他所釀之酒的危險無人不曉，但他依舊能欺騙人們乃至動物去一嚐他的飲品。$b$b必須阻止他才行!你和我們一道嗎?', `MaleText_loc7`='$gAmigo:Amiga;, hoy nos enfrentamos a uno de los maestros cerveceros más geniales y más malvados que jamás han conocido los pandaren.$b$bCasi todo el mundo ha oído hablar de los peligros de sus productos, pero a pesar de todo sigue ingeniándoselas para que las personas y los animales sigan probando sus destilados.$b$b¡Hay que detenerlo! ¿Estás con nosotros?' WHERE `ID`=54493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께하겠습니다!', `MaleText_loc4`='我跟你走！', `MaleText_loc5`='我與你同在!', `MaleText_loc7`='¡Estoy con ustedes!', `FemaleText_loc1`='함께하겠어요!', `FemaleText_loc4`='我跟你走！', `FemaleText_loc5`='我與你同在!', `FemaleText_loc7`='¡Estoy con ustedes!' WHERE `ID`=54494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 하찮은 필멸자일 뿐. 필멸자답게 황천에나 떨어져라.', `MaleText_loc4`='你不过是个凡人。现在，像个凡人那样卑微地死去吧。', `MaleText_loc5`='你只是個凡人。就像凡人一樣死去吧。', `MaleText_loc7`='Eres un simple mortal y es hora de que mueras como tal.' WHERE `ID`=54495;
