UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 얼라이언스 포로는 발견했죠... 하지만 그 대가가 무엇이었나요?', `FemaleText_loc4`='没错，我们抓到了一个联盟战俘……可我们付出了什么样的代价呢？', `FemaleText_loc5`='的確，我們找到了聯盟的俘虜...但是我們付出的代價呢?', `FemaleText_loc7`='Sí, nos hicimos con un prisionero de guerra de la Alianza, ¿pero a qué precio?' WHERE `ID`=54504;
