UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코 생각할 게 많아.', `MaleText_loc4`='里克有很多事情要思考呢。', `MaleText_loc5`='瑞可有很多事要想。', `MaleText_loc7`='Riko tiene mucho en lo que pensar.' WHERE `ID`=54506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 뭘 그리 쳐다보는 거야?', `MaleText_loc4`='你到底在看什么啊？', `MaleText_loc5`='你是在看啥呀你?', `MaleText_loc7`='¿Qué mikos estás mirando?' WHERE `ID`=54507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 포로는 조금 이상해요. 무기도 없고, 옷도... 일반적인 양식이 아니에요.$b$b어쩌면 무슨 군주 나부랑이라도 되는 것 같네요. 값어치가 있는 인물을 사로잡은 거면 좋겠는데요!', `FemaleText_loc4`='我们的俘虏很奇怪。他没有带武器，而且他的服装很……怪异。$b$b他可能是某个贵族。如果走运的话，我们或许抓住了个大人物！', `FemaleText_loc5`='我們的囚犯很怪。他沒帶武器，他的打扮...很不傳統。$b$b也許他是某種王侯。幸運的話，我們或許逮到了有價值的人物!', `FemaleText_loc7`='Nuestro prisionero es extraño. No lleva armas y su atuendo es... poco tradicional.$b$bA lo mejor es el señor de alguna tierra. Con un poco de suerte, ¡igual hemos capturado a alguien importante!' WHERE `ID`=54508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리코는... 뭐, 제가 만나본 중에 가장 성숙한 호젠이에요. 그래 봐야 대단히 성숙했다는 뜻은 아니지만요.$b$b쇼키아가 얘기한 만큼 나쁜 녀석은 아니에요... 사실, 꽤 귀엽다는 생각도 드네요... 호젠 식으로 말이에요.', `FemaleText_loc4`='里克是……呃，他是我目前见过的最成熟的猢狲，这就不用多说了。$b$b他真的没有夏琪亚想的那么糟。事实上，我觉得他挺可爱的……以猢狲的方式。', `FemaleText_loc5`='瑞可...這麼說吧，他是我目前遇過最成熟的猴人。不過這算不上什麼成就。$b$b他確實不像修基雅形容得那麼糟糕。實際上我覺得他還蠻貼心的...以猴人的角度來說。', `FemaleText_loc7`='Riko es... bueno, es el hozen más maduro que he visto hasta ahora, aunque eso no es decir mucho.$b$bNo es tan malo como lo pinta Shokia. Creo que es hasta simpático... al estilo hozen.' WHERE `ID`=54509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁전에서 악마가 끝없이 몰려나오는군.', `MaleText_loc4`='他们源源不断地从宫殿中涌出来。', `MaleText_loc5`='他們從宮殿裡不停竄出。', `MaleText_loc7`='Llegan sin cesar desde el palacio.' WHERE `ID`=54510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자. 잘 따라와라.', `MaleText_loc4`='我们要走了，跟紧点。', `MaleText_loc5`='我們要走了。跟緊點。', `MaleText_loc7`='Nos vamos. No os alejéis.' WHERE `ID`=54511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유황 냄새가 아주 코를 찌르는군. 이 차원문도 악마 놈들과 똑같이 역겨워.', `MaleText_loc4`='一股硫磺的臭气……这些传送门散发出和恶魔一样的邪恶气息。', `MaleText_loc5`='充滿硫磺的臭味...這些傳送門跟惡魔本身一樣臭。', `MaleText_loc7`='Qué hedor a sulfuro y azufre... Estos portales son tan repugnantes como los mismos demonios.' WHERE `ID`=54512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 악마를 공격해라. 네가 안 하면, 내가 한다.', `MaleText_loc4`='快攻击那个恶魔，不然我就要出手了。', `MaleText_loc5`='趕快攻擊那些惡魔，不然我就親自動手。', `MaleText_loc7`='Atacad a los demonios pronto o lo haré yo.' WHERE `ID`=54513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠을 벗어던지고 놈을 덮쳐!', `MaleText_loc4`='从阴影中突袭，干掉他。', `MaleText_loc5`='從陰影中砍死這傢伙吧。', `MaleText_loc7`='Acaben con este desde las sombras.' WHERE `ID`=54514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 전 지엔이에요! 우리 전에 만났었나요? 음, 얼굴이 꼭 그... 여기저기서 흔히 볼 수 있는 얼굴 같아요...', `MaleText_loc4`='嗨，我是浅浅！我们以前见过吗？你的脸和那些人很像。就是那些脸上……', `MaleText_loc5`='幸會，我是小堅!我們碰過面嗎?你有張那種臉，就是那種似曾相識的臉...', `MaleText_loc7`='¡Hola, soy Jian! ¿Nos conocemos? Tienes una cara de esas... De esas que tienen las cosas con cara...' WHERE `ID`=54515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<나 레크가 당신을 보고 웃자, 당신은 젊어진 듯한 기분이 듭니다. 몇 년 만에 처음 드는 기분입니다.>', `MaleText_loc4`='<纳乐对你微笑，你觉得自己焕发了久违的年轻活力。>', `MaleText_loc5`='<納類克對你微笑，你覺得自己變得像不曾經歷時光流逝般年輕。>', `MaleText_loc7`='<Na Lek te sonríe, y te sientes joven como no te habías sentido en años.>' WHERE `ID`=54516;
