UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 누구요? 뭘 원하시오? 날 보지 마시오!', `MaleText_loc4`='谁在说话？你想要什么？别盯着我看？', `MaleText_loc5`='那是誰?你要什麼?別看我!', `MaleText_loc7`='¿Quién es? ¿Qué quieres? ¡No me mires!' WHERE `ID`=54519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수를 정화할 수 있게 도와주시겠습니까?', `MaleText_loc4`='你能帮我净化这座湖吗？', `MaleText_loc5`='你能幫我淨化這片湖嗎?', `MaleText_loc7`='¿Me ayudas a limpiar el lago?', `FemaleText_loc1`='호수를 정화할 수 있게 도와주시겠어요?', `FemaleText_loc4`='你能帮我净化这座湖吗？', `FemaleText_loc5`='你能幫我淨化這片湖嗎?', `FemaleText_loc7`='¿Me ayudas a limpiar el lago?' WHERE `ID`=54520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 혼자 있고 싶다는 걸 모르겠소? 이렇게 귀찮게 하는 이유가 뭐요?', `MaleText_loc4`='你没看出来我想要自己待会吗？究竟为什么要来打扰我？', `MaleText_loc5`='你看不出來我想自己靜一靜嗎?這陣騷動是甚麼意思?', `MaleText_loc7`='¿Es que no ves que quiero estar a solas? ¿A qué viene tanta interrupción?' WHERE `ID`=54521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대제독님께서 이 병을 당신께 전하라시면서, 호드에 맞서는 우리 군에 힘을 보태주실 것을 부탁드리라고 하셨습니다.', `MaleText_loc4`='将军让我把这些瓶子带给你，还让你考虑是否愿意与我们一同对抗部落。', `MaleText_loc5`='上將要我給你這些瓶子，並要求你加入我們對抗部落。', `MaleText_loc7`='La gran almirante me ha pedido que te entregue estas botellas y que te pida que consideres la opción de unir nuestras fuerzas para hacer frente a la Horda.', `FemaleText_loc1`='대제독님께서 이 병을 당신께 전하라시면서, 호드에 맞서는 우리 군에 힘을 보태주실 것을 부탁드리라고 하셨습니다.', `FemaleText_loc4`='将军让我把这些瓶子带给你，还让你考虑是否愿意与我们一同对抗部落。', `FemaleText_loc5`='上將要我給你這些瓶子，並要求你加入我們對抗部落。', `FemaleText_loc7`='El gran almirante me ha pedido que te entregue estas botellas y que te pida que consideres la opción de unir nuestras fuerzas para hacer frente a la Horda.' WHERE `ID`=54522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대제독님이 내... 고통에 대해 알고 계시는군... 그렇게 관심을 가지고 계신지 몰랐는데!', `MaleText_loc4`='看来将军知道我所遭受的……折磨，是吧？我不知道她竟然在乎！', `MaleText_loc5`='所以上將知道我的...痛苦，是嗎?我不知道她會關心!', `MaleText_loc7`='Así que la gran almirante está al tanto de mi... dolencia, ¿no? ¡No sabía que estuviese interesada en ella!' WHERE `ID`=54523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨는 것도 이제 그만입니다. 지금은 무쇠 드워프에 맞서 싸울 때입니다.', `MaleText_loc4`='我已经躲够了。和铁矮人开战的时候到了。', `MaleText_loc5`='不要再躲了。是時候反擊那些鐵矮人了。', `MaleText_loc7`='¡Basta de esconderse! Es hora de luchar contra los enanos de hierro.' WHERE `ID`=54524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 몸을 거칠게 긁어댑니다.', `MaleText_loc4`='%s狂躁地抓挠着自己。', `MaleText_loc5`='%s暴躁地在自己身上抓著。', `MaleText_loc7`='%s se rasca con furia.' WHERE `ID`=54525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이건... 이건 내게 꼭 필요한 치료제요. 그 분이 어떻게 내 상태를 알고 계시지?', `MaleText_loc4`='等等……这些……正是我需要的药品。她是怎么知道的？', `MaleText_loc5`='等等，這些...這些就是我需要的藥。她怎麼知道?', `MaleText_loc7`='Espera... esta es la medicina que necesito. ¿Cómo lo ha sabido?' WHERE `ID`=54526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대제독님께 이 약이 효과가 있다면, 내 함선과 선원들이 모두 그분의 명을 따를 것이라고 전해주시오.', `MaleText_loc4`='告诉你们的将军，如果这药有效，我的船只和船员就任她调遣。', `MaleText_loc5`='告訴你的上將，如果這能奏效，我的船與我的船員都會聽她指揮。', `MaleText_loc7`='Dile a tu almirante que si esto funciona, mi barco y mi tripulación estarán a sus órdenes.' WHERE `ID`=54527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지옥과도 같은 이 가려움증이 사라지고, 반질반질한 내 고급 망토를 입게 될 날만을 기다리고 있소! 당신도 원하는 바를 이뤘으니, 이제 가시오!', `MaleText_loc4`='我已经迫不及待想要摆脱这该死的搔痒，重新穿上我那光鲜亮丽的大衣！你的目的已经达到了。走吧！', `MaleText_loc5`='我等不及想讓這可恨的搔癢消失，並拿回我柔軟光亮的外套!你拿到你要的東西了。滾開!', `MaleText_loc7`='¡No veo la hora de que acaben estos picores y vuelva a disfrutar de mi lustroso abrigo! Ya tienes lo que querías. Ahora, vete.' WHERE `ID`=54528;
