UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 빨리 오시다니, 정말 고마워요, $n 님.', `FemaleText_loc4`='谢谢你这么快赶到，$n。', `FemaleText_loc5`='謝謝你這麼快就趕來，$n。', `FemaleText_loc7`='Gracias por venir tan rápido, $n.' WHERE `ID`=54531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르단이 술 마시는 걸 방해하다니 용감한 $r|1이로군;로군;. 무슨 일인가?', `MaleText_loc4`='这位勇敢的$r竟然来妨碍老阿尔丹喝酒。我能为你做些什么？', `MaleText_loc5`='這位擋在老亞爾丹與他的酒之間的壯士$r。有什麼我可以效勞的?', `MaleText_loc7`='Hay que ser $gun:una; $r valiente para interponerse entre el viejo Ardan y su bebida. ¿En qué puedo ayudarte?', `FemaleText_loc1`='아르단이 술 마시는 걸 방해하다니 용감한 $r|1이로군;로군;. 무슨 일인가?', `FemaleText_loc4`='这位勇敢的$r竟然来妨碍老阿尔丹喝酒。我能为你做些什么？', `FemaleText_loc5`='這位擋在老亞爾丹與他的酒之間的壯士$r。有什麼我可以效勞的?', `FemaleText_loc7`='Hay que ser $gun:una; $r valiente para interponerse entre el viejo Ardan y su bebida. ¿En qué puedo ayudarte?' WHERE `ID`=54532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네?', `MaleText_loc4`='你好啊。', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Sí?' WHERE `ID`=54533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙하산을 하나 더 얻을 수 있습니까?', `MaleText_loc4`='我能再领一顶降落伞吗？', `MaleText_loc5`='我可以再拿一個降落傘嗎?', `MaleText_loc7`='¿Puedo conseguir otro paracaídas?', `FemaleText_loc1`='낙하산을 하나 더 얻을 수 있나요?', `FemaleText_loc4`='我能再领一顶降落伞吗？', `FemaleText_loc5`='我可以再拿一個降落傘嗎?', `FemaleText_loc7`='¿Puedo conseguir otro paracaídas?' WHERE `ID`=54534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제스테레스 대제독님이 호드의 칼림도어 봉쇄를 깨뜨릴 공격 함대를 모집하고 있습니다. 함께하시겠습니까?', `MaleText_loc4`='杰塔瑞斯将军派我来让你加入我们的舰队，粉碎部落对卡利姆多的封锁。', `MaleText_loc5`='傑塔瑞斯上將派我來請你加入艦隊，破壞部落在卡林多的封鎖線。', `MaleText_loc7`='La gran almirante Jes-Tereth me ha enviado a pedirte que te unas a la flota para romper el bloqueo de la Horda de Kalimdor.', `FemaleText_loc1`='제스테레스 대제독님이 호드의 칼림도어 봉쇄를 깨뜨릴 공격 함대를 모집하고 있어요. 함께하실래요?', `FemaleText_loc4`='杰塔瑞斯将军派我来让你加入我们的舰队，粉碎部落对卡利姆多的封锁。', `FemaleText_loc5`='傑塔瑞斯上將派我來請你加入艦隊，破壞部落在卡林多的封鎖線。', `FemaleText_loc7`='La gran almirante Jes-Tereth me ha enviado a pedirte que te unas a la flota para romper el bloqueo de la Horda de Kalimdor.' WHERE `ID`=54535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전을 받아들이지! 주먹엔 주먹으로, 술에는 술로!', `MaleText_loc4`='接受挑战！以拳还拳，以酒还酒。', `MaleText_loc5`='接受挑戰!拳對拳，酒對酒。', `MaleText_loc7`='¡Desafío aceptado! Golpe por golpe, trago por trago.' WHERE `ID`=54536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 호드 함선을 상대로 포격 연습을 한 것도 벌써 오래 전 일이군...', `MaleText_loc4`='这个嘛，我已经很久没找到理由，拿部落的舰船练枪法了……', `MaleText_loc5`='唉呀，我已經很久沒機會拿部落的飛船來練槍法了....', `MaleText_loc7`='No tengo motivos para probar mis cañones contra un navío de la Horda desde hace mucho tiempo...' WHERE `ID`=54537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투는 짜릿하고 전리품은 푸짐할 것 같은 느낌이 드는걸!', `MaleText_loc4`='听起来会是场激烈的战斗，战利品一定很丰厚！', `MaleText_loc5`='聽起來這場戰鬥將會非常猛烈，而且可以好好掠奪一番!', `MaleText_loc7`='¡Parece que la batalla será feroz y el botín bueno!' WHERE `ID`=54538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 선원들이 이 도시에서 술이 있는 곳이라면 어디서든 술판을 벌이고 있네. 선원들이 술을 버리고 총을 들게 해 준다면, 내 얼마든지 도와주지!', `MaleText_loc4`='我跟你说，我的船员们已经快把这城里的酒都给喝干了。要是你能劝他们放下酒杯，重新拿起枪，那我就入你的伙！', `MaleText_loc5`='告訴你吧，這個城市中任何找得到啤酒的地方，都有我的船員在那裡喝酒。如果你能說服他們放下啤酒並拿起他們的槍，算我一份!', `MaleText_loc7`='¿Sabes lo que te digo? Mi tripulación está bebiéndose toda la cerveza que hay en esta ciudad. ¡Si logras convencerlos para que dejen sus cervezas y cojan sus armas, cuenta conmigo!' WHERE `ID`=54539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 잔은 당신이 사는 거요?', `MaleText_loc4`='下轮酒你买单？', `MaleText_loc5`='下一輪算你的嗎?', `MaleText_loc7`='¿Vas a invitar a la próxima ronda?', `FemaleText_loc1`='다음 잔은 당신이 사는 건가요?', `FemaleText_loc4`='下轮酒你买单？', `FemaleText_loc5`='下一輪算你的嗎?', `FemaleText_loc7`='¿Vas a invitar a la próxima ronda?' WHERE `ID`=54540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 아시오?', `MaleText_loc4`='我认识你吗？', `MaleText_loc5`='我認識你嗎?', `MaleText_loc7`='¿Te conozco?', `FemaleText_loc1`='저를 아시나요?', `FemaleText_loc4`='我认识你吗？', `FemaleText_loc5`='我認識你嗎?', `FemaleText_loc7`='¿Te conozco?' WHERE `ID`=54541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이오?', `MaleText_loc4`='这是要干嘛？', `MaleText_loc5`='這是為了什麼?', `MaleText_loc7`='¿De qué va esto?', `FemaleText_loc1`='무슨 일이죠?', `FemaleText_loc4`='这是要干嘛？', `FemaleText_loc5`='這是為了什麼?', `FemaleText_loc7`='¿De qué va esto?' WHERE `ID`=54542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 종업원 같진 않은데...', `MaleText_loc4`='你不像是个女招待……', `MaleText_loc5`='你看起來不像招待員', `MaleText_loc7`='No pareces la tabernera...', `FemaleText_loc1`='여기 종업원 같진 않은데...', `FemaleText_loc4`='你不像是个女招待……', `FemaleText_loc5`='你看起來不像招待員', `FemaleText_loc7`='No pareces la tabernera...' WHERE `ID`=54543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... *딸꾹* 맛이 강하군... 쉬어야겠어...', `MaleText_loc4`='太……*嗝*太好喝了。得……休息一下。', `MaleText_loc5`='味道太...*嗝*濃了。得...休息一會兒。', `MaleText_loc7`='Demasiado... *hip* sabor. Debo... descansar.' WHERE `ID`=54544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술잔은 내려놓고 총을 드십시오. 선장이 출항하려 합니다.', `MaleText_loc4`='放下酒杯，把枪拿起来。你的船长要起航了。', `MaleText_loc5`='放下啤酒並拿起你的武器。你的船長要出海了。', `MaleText_loc7`='Deja esa cerveza y coge tu arma. Tu capitán va a zarpar.', `FemaleText_loc1`='술잔은 내려놓고 총을 드세요. 선장이 출항하려 해요.', `FemaleText_loc4`='放下酒杯，把枪拿起来。你的船长要起航了。', `FemaleText_loc5`='放下啤酒並拿起你的武器。你的船長要出海了。', `FemaleText_loc7`='Deja esa cerveza y coge tu arma. Tu capitán va a zarpar.' WHERE `ID`=54545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 정수는... 내것이다.', `MaleText_loc4`='你的精华……归我了。', `MaleText_loc5`='你的精華...歸我。', `MaleText_loc7`='¡Tu esencia... es mía!' WHERE `ID`=54546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지. 호드 배를 산산조각 내 줄 준비가 되었다오!', `MaleText_loc4`='是，我已经准备好要把兽人的舰船砸得稀巴烂了！', `MaleText_loc5`='是的，我準備要去砸爛一些部落的船隻了!', `MaleText_loc7`='¡Sí, estoy listo para reducir a astillas unos cuantos barcos de la Horda!', `FemaleText_loc1`='좋지. 호드 배를 산산조각 내 줄 준비가 됐거든요!', `FemaleText_loc4`='是，我已经准备好要把兽人的舰船砸得稀巴烂了！', `FemaleText_loc5`='是的，我準備要去砸爛一些部落的船隻了!', `FemaleText_loc7`='¡Sí, estoy lista para reducir a astillas unos cuantos barcos de la Horda!' WHERE `ID`=54547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지. 물론 갈 거지만, 내가 준비가 되면 그때 가겠소.', `MaleText_loc4`='好吧，我会去，可得等我准备好才行……', `MaleText_loc5`='是的，我會去的，不過要等我準備好再去...', `MaleText_loc7`='Sí, iré, pero cuando esté preparado...', `FemaleText_loc1`='좋죠. 물론 갈 거지만, 내가 준비가 되면 그때 가겠어요.', `FemaleText_loc4`='好吧，我会去，可得等我准备好才行……', `FemaleText_loc5`='是的，我會去的，不過要等我準備好再去...', `FemaleText_loc7`='Sí, iré, pero cuando esté preparada...' WHERE `ID`=54548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 물론 총을 가져와야지. 한 번만 더 내가 술 마실 때 방해하면, 그걸로 쏴 줄 거요!', `MaleText_loc4`='噢，我会去拿枪，要是你再敢打扰我喝酒，我就先把你的屁股射出个洞来！', `MaleText_loc5`='喔，我會拿起我的槍，而且我要拿來對付你，如果你再來打擾我喝酒的話!', `MaleText_loc7`='¡Oh, cogeré mi arma, y te dispararé con ella si vuelves a interrumpirme mientras estoy bebiendo!', `FemaleText_loc1`='아, 물론 총을 가져와야지. 한 번만 더 내가 술 마실 때 방해하면, 그걸로 쏴 줄 거예요!', `FemaleText_loc4`='噢，我会去拿枪，要是你再敢打扰我喝酒，我就先把你的屁股射出个洞来！', `FemaleText_loc5`='喔，我會拿起我的槍，而且我要拿來對付你，如果你再來打擾我喝酒的話!', `FemaleText_loc7`='¡Oh, cogeré mi arma, y te dispararé con ella si vuelves a interrumpirme mientras estoy bebiendo!' WHERE `ID`=54549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에게 본때를 보여 주겠소!', `MaleText_loc4`='我们要让部落付出代价，一定会的！', `MaleText_loc5`='我們會讓部落付出代價，我們一定會!', `MaleText_loc7`='¡La Horda nos las pagará!', `FemaleText_loc1`='호드에게 본때를 보여 주겠어요!', `FemaleText_loc4`='我们要让部落付出代价，一定会的！', `FemaleText_loc5`='我們會讓部落付出代價，我們一定會!', `FemaleText_loc7`='¡La Horda nos las pagará!' WHERE `ID`=54550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 허수아비 오크랑 싸울 일은 없어!', `MaleText_loc4`='我可不想再去打什么垃圾兽人了！', `MaleText_loc5`='別再要我射稻草獸人了!', `MaleText_loc7`='¡Se acabó el disparar a orcos de paja!', `FemaleText_loc1`='이제 허수아비 오크랑 싸울 일은 없어요!', `FemaleText_loc4`='我可不想再去打什么垃圾兽人了！', `FemaleText_loc5`='別再要我射稻草獸人了!', `FemaleText_loc7`='¡Se acabó el disparar a orcos de paja!' WHERE `ID`=54551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후아... 다음엔 그렇게 빨리 하지 말라고!', `MaleText_loc4`='哇……下次别那么快！', `MaleText_loc5`='嗚哇...下次別這麼快!', `MaleText_loc7`='Uau... ¡No vayas tan deprisa la próxima vez!', `FemaleText_loc1`='후아... 다음엔 그렇게 빨리 하지 말라고!', `FemaleText_loc4`='哇……下次别那么快！', `FemaleText_loc5`='嗚哇...下次別這麼快!', `FemaleText_loc7`='Uau... ¡No vayas tan deprisa la próxima vez!' WHERE `ID`=54552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속도를 늦춰, 이 커다란 멍청아!', `MaleText_loc4`='慢点儿，你这大蠢货！', `MaleText_loc5`='你這大蠢蛋，慢一點!', `MaleText_loc7`='¡Más lento, tontaina!', `FemaleText_loc1`='속도를 늦춰, 이 커다란 멍청아!', `FemaleText_loc4`='慢点儿，你这大蠢货！', `FemaleText_loc5`='你這大蠢蛋，慢一點!', `FemaleText_loc7`='¡Más lento, tontaina!' WHERE `ID`=54553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 짓을 하려거든 미리 경고를 해!', `MaleText_loc4`='在动手之前先告诉我一声！', `MaleText_loc5`='你要幹這種事之前先警告我一聲!', `MaleText_loc7`='¡Avísame antes de hacer eso!', `FemaleText_loc1`='그런 짓을 하려거든 미리 경고를 해!', `FemaleText_loc4`='在动手之前先告诉我一声！', `FemaleText_loc5`='你要幹這種事之前先警告我一聲!', `FemaleText_loc7`='¡Avísame antes de hacer eso!' WHERE `ID`=54554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아!', `MaleText_loc4`='啊啊啊！！', `MaleText_loc5`='吼!!!', `MaleText_loc7`='¡¡Rrraaaghhh!!' WHERE `ID`=54555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사업차 여기 온 거라면, 생각하고 있는 비용을 제시하시오.', `MaleText_loc4`='如果你是来这办正事的，就别绕弯子了。', `MaleText_loc5`='如果你是來這裡談交易的，就說吧。', `MaleText_loc7`='Si has venido a dirigir el negocio, di lo que tengas que decir.' WHERE `ID`=54556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무척 화가 나 있군. 맛있는... 고통의 맥주로 좀 진정시켜야겠어!', `MaleText_loc4`='这么生气啊。那我们一定得用一杯…苦酒来让你消停下来！', `MaleText_loc5`='多麼強烈的怒火。我們該用啤酒來熄滅你的怒焰...名為痛苦的啤酒!', `MaleText_loc7`='Cuánta ira. Deberíamos calmarte un poco con un buen licor... ¡del dolor!' WHERE `ID`=54557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫인상이 좋지 않았군. 어디, 에일맥주 한 잔과 함께... 아픔을 맛보는 게 어때?!', `MaleText_loc4`='显然我们有了一个很坏的开局。再来一杯……更苦的酒怎么样？！', `MaleText_loc5`='顯然我們有個不太好的開始。不如來點...加倍痛苦的麥酒?!', `MaleText_loc7`='Hemos empezado con mal pie. ¿Qué tal si lo zanjamos con una cerveza... de más dolor?' WHERE `ID`=54558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 더 맛있는 걸 마셔보지. 이건 내 특제 흑맥주야... 고통 맛을 더했지!', `MaleText_loc4`='好了，该动真格的了。这是我特别酿制的……痛苦烈酒！', `MaleText_loc5`='好啦，該好東西上場了。這是我的特製烈酒...災難烈酒!', `MaleText_loc7`='Muy bien, ahora viene lo mejor. Esta es mi cerveza especial... ¡del sufrimiento!' WHERE `ID`=54559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제스테레스 대제독님이 호드의 칼림도어 봉쇄를 깨뜨릴 공격 함대를 모집하고 있습니다. 함께하시겠습니까?', `MaleText_loc4`='杰塔瑞斯将军要派舰队前去打破部落对卡利姆多的封锁。你愿意加入她吗？', `MaleText_loc5`='傑塔瑞斯上將正派出一支軍隊到卡林多去，擊潰部落的封鎖線。你要加入她嗎?', `MaleText_loc7`='La gran almirante va a lanzar su flota en un ataque contra la Horda para acabar con el bloqueo de Kalimdor. ¿Te unirás a ella?', `FemaleText_loc1`='제스테레스 대제독님이 호드의 칼림도어 봉쇄를 깨뜨릴 공격 함대를 모집하고 있어요. 함께하실래요?', `FemaleText_loc4`='杰塔瑞斯将军要派舰队前去打破部落对卡利姆多的封锁。你愿意加入她吗？', `FemaleText_loc5`='傑塔瑞斯上將正派出一支軍隊到卡林多去，擊潰部落的封鎖線。你要加入她嗎?', `FemaleText_loc7`='La gran almirante va a lanzar su flota en un ataque contra la Horda para acabar con el bloqueo de Kalimdor. ¿Te unirás a ella?' WHERE `ID`=54560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무모한 행위에 대한 벌을 호드에게 내릴 수 있다면 기꺼이 받아들이겠소...', `MaleText_loc4`='我很愿意趁此机会惩罚部落犯下的暴行……', `MaleText_loc5`='我樂於懲罰部落這樣的暴行...', `MaleText_loc7`='Me encantaría tener la oportunidad de castigar a la Horda por toda esta atrocidad...' WHERE `ID`=54561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 일등항해사와의 결투에서 승리한다면, 당신 함대에 참여하겠소.', `MaleText_loc4`='要是你能打败我最优秀的大副，我就加入你的舰队。', `MaleText_loc5`='如果你能在戰鬥中擊敗我的首席軍官，我就加入你的部隊。', `MaleText_loc7`='Me uniré a tu flota si derrotas a mi primer oficial en una batalla.' WHERE `ID`=54562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윌리엄스, 도전자가 있다. 이 $c에게 우리가 오크를 어떻게 대접하는지 보여줘라!', `MaleText_loc4`='威廉姆斯，我们有挑战者了。让这位$c瞧瞧，我们会怎么对付那些兽人！', `MaleText_loc5`='威廉斯，我們有個挑戰者。讓這個$c瞧瞧我們能對獸人做什麼!', `MaleText_loc7`='Williams, tenemos $gun:una; aspirante. ¡Muéstrale a $geste:esta; $c lo que les vamos a hacer a los orcos!' WHERE `ID`=54563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 항복합니다! 솜씨가 뛰어나시군요.', `MaleText_loc4`='够了！我对你的卓越战技感到心悦诚服。', `MaleText_loc5`='夠了!我折服於你優秀的技能。', `MaleText_loc7`='¡Basta! Me inclino ante tus superiores habilidades.' WHERE `ID`=54564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장님, 우리도 함대에 참여해야 합니다. 대제독님은 뛰어난 동료들과 함께하시는군요.', `MaleText_loc4`='我们应该加入这支舰队，船长。将军的同伴们值得信任。', `MaleText_loc5`='我們應該加入這支艦隊，艦長。成為海軍上將的盟友很有價值。', `MaleText_loc7`='Deberíamos unirnos a esta flota, capitán. La valía de los aliados de la almirante está fuera de toda duda.' WHERE `ID`=54565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 보잘것없는 계곡에 잘 왔구나, 얘야. 내 삶의 목표는 네가 지금까지 맛본 모든 것을 초라하게 만들 만큼 달콤한 음료를 만들어내는 것이란다.$b$b오랜 연구 끝에, 마침내 뭔가 획기적인 것이 탄생하려 하는 중이다. 누구도 상상조차 하지 못했던 그런 맛이지.', `MaleText_loc4`='欢迎来到我这个简陋的山谷，孩子。我毕生的目标就是酿造出一种绝世佳酿，它要能胜过你的味蕾所品尝过的一切味道。$b$b我的研究已经快要得出成果了，从没有一个熊猫人能达到我这样的高度。', `MaleText_loc5`='歡迎來到敝山谷，孩子。我的人生目標就是釀造出美味得讓你這輩子所喝過一切都相形遜色的酒。$b$b我的研究就快要得出成果，至今沒有任何熊貓人能完成到這種程度。', `MaleText_loc7`='Te doy la bienvenida, joven, a mi humilde valle. Mi objetivo en la vida es diseñar una bebida tan deliciosa que supere a todas las demás experiencias que hayan probado tus papilas.$b$bMi investigación está al borde de descubrir algo fenomenal, algo que ningún pandaren puede ni soñar con alcanzar.' WHERE `ID`=54566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신은 이 아늑한 동굴 안에서 공중에 우아한 선을 그리는 생물의 모습을 흥미롭게 바라봅니다. 지난 몇 시간 동안의 폭력과 소란에서 벗어나 잠시 찾아온 휴식이 정말 반갑습니다.$b$b이 생물은 당신의 기척을 눈치챘다는 사실을 전혀 겉으로 드러내지 않지만, 점차 그가 당신의 숨결 하나하나까지 모두 알고 있다는 생각이 당신 안에서 자라납니다.$b$b나즈그림과 다른 동료들을 생각하면서, 당신은 이 낯선 존재와 어떻게 대화를 시작해야 할지 고민합니다.>', `MaleText_loc4`='<你着迷地看着这个熊猫人在洞内宁静的空气中画出一条条优雅的弧线。经历了几个小时的动荡和厮杀后，片刻的休憩无疑是最好的享受。$b$b他似乎并没有察觉你的到来，但你越来越相信，他早就捕捉到了你的每一次呼吸。$b$b想到纳兹戈林和其他人，你开始琢磨怎么才能和这个陌生人搭上话。>', `MaleText_loc5`='<你著迷地看著這生物在這舒適洞穴的空中優雅地畫出線條。能遠離前幾個小時的暴力和騷亂對你來說是最好也不過的事。$b$b這生物看不見你，但你忍不住開始覺得，他其實能感受到你的每一次呼吸。$b$b想起納茲格寧姆和其他人，你開始思考該怎麼和這位陌生人進行談話。>', `MaleText_loc7`='<Observas con fascinación a la criatura mientras dibuja con gracia líneas en el aire dentro de su acogedora cueva. Agradeces enormemente el descanso de la violencia y agitación de las últimas horas.$b$bEl ser no parece percatarse de tu presencia, pero algo dentro de ti te dice que siente cada respiración.$b$bVuelves a pensar en Nazgrim y los demás y te preguntas cómo entablar conversación con el extraño.>' WHERE `ID`=54567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시음가의 결투에 도전합니다.', `MaleText_loc4`='向一名品酒师发起挑战。', `MaleText_loc5`='提出品酒對決的挑戰。', `MaleText_loc7`='Te reto a un duelo de catadores.', `FemaleText_loc1`='시음가의 결투에 도전합니다.', `FemaleText_loc4`='向一名品酒师发起挑战。', `FemaleText_loc5`='提出品酒對決的挑戰。', `FemaleText_loc7`='Te reto a un duelo de catadores.' WHERE `ID`=54568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 궁전에서 악마들이 나오지 않는군. 어서 가자.', `MaleText_loc4`='宫殿里不再涌出恶魔。我们可以前进了。', `MaleText_loc5`='惡魔已經不再從宮殿中出現。我們可以繼續向前了。', `MaleText_loc7`='Ya no salen demonios del palacio. Podemos proseguir.' WHERE `ID`=54572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 쉬웠어.', `MaleText_loc4`='太简单了……', `MaleText_loc5`='太簡單了。', `MaleText_loc7`='Demasiado fácil.' WHERE `ID`=54573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마 한 놈이 또 최후를 맞으러 왔군.', `MaleText_loc4`='又是一个来送死的恶魔。', `MaleText_loc5`='又一隻惡魔，送到刀口上。', `MaleText_loc7`='Otro demonio que está deseando que lo liquiden.' WHERE `ID`=54574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 죽을 목숨인 줄도 모르고 멍청히 서 있는 꼴이라니.', `MaleText_loc4`='他们完全没意识到自己死期将至。', `MaleText_loc5`='他們站在那裡，不知道死之將至。', `MaleText_loc7`='No son conscientes de que les acecha la muerte.' WHERE `ID`=54575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불 속에서 가져온 향초가 이 동물들을 벌써 치유하고 있는 것 같아요. 감사합니다!', `FemaleText_loc4`='火里的草药好像已经把这只动物治好了。谢谢你！', `FemaleText_loc5`='草藥似乎已經開始對這動物產生療效了。謝謝你!', `FemaleText_loc7`='Las hierbas del fuego parecen estar sanando al animal. ¡Gracias!' WHERE `ID`=54576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 알아두셔야 할 게 있어요. 지난 번까지 총 16명의 신병들이...', `FemaleText_loc4`='$n，你应该知道那最后十六名新兵……', `FemaleText_loc5`='$n，你應該知道過去十六個新兵...', `FemaleText_loc7`='$n, deberías saber que los últimos dieciséis reclutas...' WHERE `ID`=54577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 모두 잘 들어라. 지금 미확인 적지에 진입하고 있다. 본부의 지원은 기대할 수 없다.', `MaleText_loc4`='好，大家听好了。我们正在进入未知的敌方领土，远离联盟控制地区。', `MaleText_loc5`='好了，大家聽好了。我們正在進入未知的敵方領域。遠離聯盟的指揮鍊。', `MaleText_loc7`='Muy bien. Escúchenme. Estamos entrando en territorio hostil desconocido, lejos de la cadena de mando de la Alianza.' WHERE `ID`=54578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장, 거기엔 알려진 육지가 없습니다. 어디로 간 걸까요?', `MaleText_loc4`='但是长官，这片区域的地图没有记录这座岛屿啊。他们在哪儿呢？', `MaleText_loc5`='可是長官，資料顯示那一帶根本沒有陸地。他們到底在哪?', `MaleText_loc7`='Pero, señor, si no hay constancia de tierra alguna en esa región. ¿Dónde están?' WHERE `ID`=54579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트라드! 렌스타트! 안 돼애애애애애!', `MaleText_loc4`='特拉德！伦斯坦德！不--！', `MaleText_loc5`='崔德!任斯特德!不...!', `MaleText_loc7`='¡Trad! ¡Renstadt! ¡Nooooooooooooooooooo!' WHERE `ID`=54580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담하시는 거죠, 사령관님? 전 신병에게 우유나 먹여주려고 여기 온 게 아니라고요.', `MaleText_loc4`='你在跟我开玩笑吗，指挥官？我可不是来照看什么菜鸟新手的。', `MaleText_loc5`='你在開玩笑吧，指揮官?我不是來這裡當這些沒受訓菜鳥的保母的。', `MaleText_loc7`='¿Es una broma, comandante? Yo no estoy aquí para hacer de niñera para $gun:una; $gnovato:novata; sin entrenamiento.' WHERE `ID`=54581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안개 속에서 대체 뭘 어떻게 찾으라는 거야?', `MaleText_loc4`='我们怎样才能在这片浓雾里找到些什么呢？', `MaleText_loc5`='無論如何，我們到底想在這團霧裡找到什麼?', `MaleText_loc7`='Sea como sea, ¿cómo se supone que vamos a encontrar nada con toda esta niebla?' WHERE `ID`=54582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사령관님, 전방에 얼라이언스 조난 신호입니다.', `FemaleText_loc4`='指挥官，前方收到联盟发出的呼救信号。', `FemaleText_loc5`='指揮官，前方有聯盟的求救信號。', `FemaleText_loc7`='Comandante, recibimos una señal de socorro de la Alianza.' WHERE `ID`=54583;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우릴 공격합니다!', `FemaleText_loc4`='他们开火了，长官！', `FemaleText_loc5`='他們對我們開火了，長官!', `FemaleText_loc7`='¡Nos disparan, señor!' WHERE `ID`=54584;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위로!', `FemaleText_loc4`='拉升高度！', `FemaleText_loc5`='往上拉!', `FemaleText_loc7`='¡Acércate!' WHERE `ID`=54585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지가 위험에 처했군.', `MaleText_loc4`='这里的船员遇到麻烦了。', `MaleText_loc5`='看來這裡的船員遇到麻煩了。', `MaleText_loc7`='Parece que la tripulación tiene problemas.' WHERE `ID`=54586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 저들을 도와주고, 나머진 나중에 걱정하세. 움직여!', `MaleText_loc4`='我们先救出他们，然后再担心其它人。出发！', `MaleText_loc5`='我們最好幫他們一把，等等再擔心其他人。我們走吧!', `MaleText_loc7`='Les ayudaremos y nos preocuparemos después de los demás. ¡Vamos!' WHERE `ID`=54587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 이 항구 건설에 참여하셨지. 정말 아름답지 않나?', `MaleText_loc4`='知道吗，是我爸爸帮忙建造了这个港口。这里美不美？', `MaleText_loc5`='你知道的，我把拔幫忙建了這個港口。她是不是很漂亮?', `MaleText_loc7`='Mi padre ayudó a construir este puerto, no sé si lo sabías. ¿A que es una preciosidad?' WHERE `ID`=54588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='믿어 주세요, 대장님. 반드시 그 아이를 구해낼게요.', `FemaleText_loc4`='交给我们了，长官。一定带那孩子回来。', `FemaleText_loc5`='交給我們吧，長官。我們一定會帶回那個男孩。', `FemaleText_loc7`='No te fallaremos, señor. No volveremos sin el chico.' WHERE `ID`=54589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그랬다고 해도 놀라지 않겠어. 정말 위대한 드워프였으니까!', `MaleText_loc4`='嗯，我对这件事情一点都不感到惊讶。他是个伟大的矮人！', `MaleText_loc5`='嗯，如果他做了我也不會意外。他是個偉大的矮人!', `MaleText_loc7`='Bueno, sería una sorpresa si fue así. ¡Era un gran enano!' WHERE `ID`=54590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='있잖아, 설리. 우리 돌아가면 에일맥주 한 잔 놓고 그분에 대해 이야기해 보자고.', `FemaleText_loc4`='听着苏利，我们回去之后得好好喝一杯，到时候把与他有关的一切都说给我听。', `FemaleText_loc5`='這麼著吧蘇利，當我們回來後，喝杯啤酒，然後告訴我關於他的事。', `FemaleText_loc7`='Sully, dime todo lo que sepas de él con una jarra de cerveza cuando regresemos.' WHERE `ID`=54591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아!', `MaleText_loc4`='成交！', `MaleText_loc5`='一言為定!', `MaleText_loc7`='¡Hecho!' WHERE `ID`=54592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 호드 함선? 여기에?', `MaleText_loc4`='什么？一艘部落的船？在这儿？', `MaleText_loc5`='什麼?部落飛艇?在這裡?', `MaleText_loc7`='¿Cómo? ¿Una nave de la Horda? ¿AQUÍ?' WHERE `ID`=54593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 끝난 일은 말할 것 없네... 지난 일은 탓할 것 없네.', `MaleText_loc4`='做完的事就不用反复讨论……过去的事，也不必再去追究。', `MaleText_loc5`='成事不說...既往不咎。', `MaleText_loc7`='No es necesario hablar del pasado. No es necesario culpar a nadie.' WHERE `ID`=54594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피는 내것이다!', `MaleText_loc4`='你的鲜血归我了，精灵！', `MaleText_loc5`='我要你的血，精靈!', `MaleText_loc7`='¡Tu sangre es mía, elfo!' WHERE `ID`=54595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 일어나게, 이방인! 자네가 코를 고는 소리 때문에 내가 명상을 할 수가 없지 않나.', `MaleText_loc4`='醒醒，陌生人！你的打呼声害得我都没法学习了.', `MaleText_loc5`='醒來，陌生人!你的打呼聲擾亂了我的修行。', `MaleText_loc7`='¡Despierta, $gextraño:extraña;! Tus ronquidos perturban mis estudios.' WHERE `ID`=54596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임기응변이 필요하다. 거점 확보가 가장 우선이니, 원주민들과도 접촉을 시도하라.', `MaleText_loc4`='我们得随机应变。与当地人交朋友——无论如何也要抢占摊头。', `MaleText_loc5`='我們可能得臨機應變。和本地居民建立友誼 - 想盡辦法建立灘頭堡。', `MaleText_loc7`='Habrá que improvisar. Entablar amistad con los nativos. Lo que haga falta para asegurar la playa.' WHERE `ID`=54597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁금하군. 사부님이 내 연구를 방해하라며 자네를 보낸 건가?$b$b... 아니면 그저 내 인내심을 시험해 보려고 보낸 건가?', `MaleText_loc4`='我很好奇。你不会是我师父故意派来让我分心的吧？$b$b亦或是……派你来考验我耐心的？', `MaleText_loc5`='我很疑惑。我的師父是派你來妨礙我修習的嗎?$b$b...或者你是被派來考驗我耐性的。', `MaleText_loc7`='Me pregunto si mi maestro te enviaría para que me distrajeras de mis estudios.$b$bA lo mejor te envió para poner a prueba mi paciencia.' WHERE `ID`=54598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수를 정화할 준비가 되었습니다.', `MaleText_loc4`='我做好净化湖泊的准备了。', `MaleText_loc5`='準備好淨化湖水。', `MaleText_loc7`='Estoy listo para purificar el lago.', `FemaleText_loc1`='호수를 정화할 준비가 됐어요.', `FemaleText_loc4`='我做好净化湖泊的准备了。', `FemaleText_loc5`='準備好淨化湖水。', `FemaleText_loc7`='Estoy lista para purificar el lago.' WHERE `ID`=54599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 양조사가 이 물에 무슨 짓을 한 거죠?', `MaleText_loc4`='那个酒仙对我的湖水做了什么？', `MaleText_loc5`='釀酒大師對我的水做了什麼?', `MaleText_loc7`='¿Qué le ha hecho ese maestro de la cerveza a mi agua?' WHERE `ID`=54600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛이 이상하군요...', `MaleText_loc4`='这味道很古怪……', `MaleText_loc5`='這味道真奇怪...', `MaleText_loc7`='Esto sabe raro...' WHERE `ID`=54601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 의식을 시작하십시오.', `MaleText_loc4`='我准备好了。开始你的仪式吧。', `MaleText_loc5`='我準備好了。進行你的儀式吧。', `MaleText_loc7`='Estoy listo. Sigue adelante con el ritual.', `FemaleText_loc1`='준비됐어요. 의식을 시작하세요.', `FemaleText_loc4`='我准备好了。开始你的仪式吧。', `FemaleText_loc5`='我準備好了。進行你的儀式吧。', `FemaleText_loc7`='Estoy lista. Sigue adelante con el ritual.' WHERE `ID`=54602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 옆에 의식을 치를 수 있는 제단이 있습니다. 갑시다!', `MaleText_loc4`='这附近有个祭坛，我可以在那里举行仪式。我们走吧！', `MaleText_loc5`='附近有個可供我進行儀式的祭壇。快走吧!', `MaleText_loc7`='Cerca hay un altar en el que puedo realizar el ritual. ¡Vamos!' WHERE `ID`=54603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다... 제가 탄차오를 여는 동안 적들을 물리쳐 주십시오, $p 님!', `MaleText_loc4`='好了……别让他们靠近我，$p！我来开启接天桥。', `MaleText_loc5`='我們到了...在我開啟天橋時別讓他們接近我，$p!', `MaleText_loc7`='Aquí está... Mantenlos a raya mientras abro el Tan-Chao, $p.' WHERE `ID`=54604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 차원문에서 지옥사냥개가 쏟아져 나옵니다!', `MaleText_loc4`='恶魔传送门里涌出了大量地狱猎犬！', `MaleText_loc5`='惡魔犬從惡魔傳送門中一湧而出!', `MaleText_loc7`='¡Salen canes manáfagos del portal demoníaco!', `FemaleText_loc1`='악마의 차원문에서 지옥사냥개가 쏟아져 나옵니다!', `FemaleText_loc4`='恶魔传送门里涌出了大量地狱猎犬！', `FemaleText_loc5`='惡魔犬從惡魔傳送門中一湧而出!', `FemaleText_loc7`='¡Salen canes manáfagos del portal demoníaco!' WHERE `ID`=54605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 차원문에서 지옥수호병이 쏟아져 나옵니다!', `MaleText_loc4`='恶魔传送门里涌出了大量恶魔卫士！', `MaleText_loc5`='惡魔守衛從惡魔傳送門中一湧而出!', `MaleText_loc7`='¡Salen guardias viles del portal demoníaco!', `FemaleText_loc1`='악마의 차원문에서 지옥수호병이 쏟아져 나옵니다!', `FemaleText_loc4`='恶魔传送门里涌出了大量恶魔卫士！', `FemaleText_loc5`='惡魔守衛從惡魔傳送門中一湧而出!', `FemaleText_loc7`='¡Salen guardias viles del portal demoníaco!' WHERE `ID`=54606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 차원문에서 파멸의 수호병이 쏟아져 나옵니다!', `MaleText_loc4`='恶魔传送门里涌出了大量末日守卫！', `MaleText_loc5`='末日守衛從惡魔傳送門中一湧而出!', `MaleText_loc7`='¡Salen guardias apocalípticos del portal demoníaco!', `FemaleText_loc1`='악마의 차원문에서 파멸의 수호병이 쏟아져 나옵니다!', `FemaleText_loc4`='恶魔传送门里涌出了大量末日守卫！', `FemaleText_loc5`='末日守衛從惡魔傳送門中一湧而出!', `FemaleText_loc7`='¡Salen guardias apocalípticos del portal demoníaco!' WHERE `ID`=54607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘에서 지옥불정령이 쏟아집니다!', `MaleText_loc4`='天空中落下了大量地狱火！', `MaleText_loc5`='煉獄火從天而降了!', `MaleText_loc7`='¡Caen infernales del cielo!', `FemaleText_loc1`='하늘에서 지옥불정령이 쏟아집니다!', `FemaleText_loc4`='天空中落下了大量地狱火！', `FemaleText_loc5`='煉獄火從天而降了!', `FemaleText_loc7`='¡Caen infernales del cielo!' WHERE `ID`=54608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 너무 많아!', `FemaleText_loc4`='他们数量太多了！', `FemaleText_loc5`='他們的數量太多了!', `FemaleText_loc7`='¡Son demasiados!' WHERE `ID`=54609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 내 배에서 꼬르륵 소리가 엄청나. 벌써 몇 시간째 날기만 하고 있잖아!', `MaleText_loc4`='嘿，我的肚子在发牢骚了。我们已经飞了几个小时了！', `MaleText_loc5`='嘿，我的胃在咕嚕咕嚕叫了。我們已經飛了好幾個小時!', `MaleText_loc7`='Eh, mi estómago no deja de rugir. ¡Llevamos horas volando!' WHERE `ID`=54610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 주위를 잘 살펴라. 이 부근에 생존자들이 상륙한 육지가 있을 것이다.', `MaleText_loc4`='好了，都看仔细。这附近应该会有大陆块，幸存者可能就在上面。', `MaleText_loc5`='好了，仔細看。生還者降落的那片廣闊陸地，應該就在附近。', `MaleText_loc7`='Hay que darse prisa. Por aquí cerca debería haber una masa de tierra a la que habrán llegado los supervivientes.' WHERE `ID`=54611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비행 장비가 먹통이에요! 조종할 수가 없어요!', `FemaleText_loc4`='系统受损，指挥官！我控制不了这飞机！', `FemaleText_loc5`='我們的系統都錯亂了，指揮官!我無法控制這架飛機!', `FemaleText_loc7`='¡Nuestros sistemas están bloqueados, Comandante! ¡No puedo controlar el avión!' WHERE `ID`=54612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수 없군! 얼라이언스 깃발이다!', `MaleText_loc4`='难以置信！是联盟的颜色！', `MaleText_loc5`='不敢相信!那是聯盟的代表色!', `MaleText_loc7`='¡Increíble! ¡Los colores de la Alianza!' WHERE `ID`=54613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기네!', `MaleText_loc4`='这边，$n！', `MaleText_loc5`='在這裡，$n!', `MaleText_loc7`='¡Aquí, $n!' WHERE `ID`=54614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테일러 제독이 이 근처에 있을 것이네.', `MaleText_loc4`='泰勒一定就在附近。', `MaleText_loc5`='泰勒一定就在附近。', `MaleText_loc7`='Taylor deber de estar cerca.' WHERE `ID`=54615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윽! 맞았어요!', `FemaleText_loc4`='啊！遭到攻击！', `FemaleText_loc5`='呃!我們被擊中了!', `FemaleText_loc7`='¡Ah! ¡Nos han dado!' WHERE `ID`=54616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 우선 이 땅과 하나가 되는 법을 배워야 하네.$b$b그래야만 이 땅의 비밀이 자네에게 드러날 거야.', `MaleText_loc4`='你必须学会融入这片土地，陌生人。$b$b只有这样，你才能探知它的秘密。', `MaleText_loc5`='你必須學著和這片土地合而為一，陌生人。$b$b唯有如此，你才能聽見土地的秘密。', `MaleText_loc7`='Debes aprender a ser $guno:una; con la tierra, $gforastero:forastera;.$b$bSolo entonces te revelará sus secretos.' WHERE `ID`=54617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명상할 준비가 되었습니다.', `MaleText_loc4`='我准备好了，可以开始冥想课程了。', `MaleText_loc5`='我準備好接受冥想訓練了。', `MaleText_loc7`='Estoy preparado para mi sesión de meditación.', `FemaleText_loc1`='명상할 준비가 됐어요.', `FemaleText_loc4`='我准备好了，可以开始冥想课程了。', `FemaleText_loc5`='我準備好接受冥想訓練了。', `FemaleText_loc7`='Estoy preparada para mi sesión de meditación.' WHERE `ID`=54618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님! 제가 숙취해소의 불을 만들 거예요. 술에서 깨시려면 제 쪽으로 오세요.', `FemaleText_loc4`='$p！我点了一堆清心焰。如果你想吸口新鲜空气，可以来找我。', `FemaleText_loc5`='$p!我在生一把清醒之火。如果你需要呼吸新鮮空氣就來找我。', `FemaleText_loc7`='¡$p! Estoy preparando un fuego serenador. Acércate si quieres tomarte un respiro.' WHERE `ID`=54619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이사는 수련을 지나치게 오래 하는 것 같아... 하지만 그러는 보람이 있다는 건 부인할 수가 없네. 자세가 정말 아름다워.', `MaleText_loc4`='艾莎花在修炼上的时间似乎太长了……但成效着实不错。她的风度十分迷人。', `MaleText_loc5`='艾莎花在修行上的時間似乎過多了...但你無法否認她的成果。她的姿態美極了。', `MaleText_loc7`='El tiempo que Aysa emplea entrenando es excesivo... Pero no puedes negar los resultados. Tiene una figura preciosa.' WHERE `ID`=54620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 숨을 깊이 들이쉬게...', `MaleText_loc4`='深呼吸，陌生人……', `MaleText_loc5`='深呼吸，陌生人...', `MaleText_loc7`='Respira hondo, $gextraño:extraña;...' WHERE `ID`=54621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 비우게.', `MaleText_loc4`='约束你的思想。', `MaleText_loc5`='淨空你的心神。', `MaleText_loc7`='Despeja tu mente.' WHERE `ID`=54622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섀도푸어를 쓰러뜨렸으니, 이제 양조사라는 이름은 제 것이에요. 그러니 이제부터는 그가 이 계곡에 저질러 놓은 온갖 폐해를 치유해야 하겠어요.', `FemaleText_loc4`='打败影斟之后，他的酒仙之位就传给了我。现在，我必须去挽救他对这座山谷造成的伤害了。', `FemaleText_loc5`='打敗影傾之後，他的釀酒大師稱號就變成我的了。現在我得繼續消除他對這山谷造成的傷害。', `FemaleText_loc7`='Ahora que Trago Oscuro ha sido derrotado, el título de maestra cervecera me corresponde a mí. Tendré que reparar todo el daño que ha causado en este valle.' WHERE `ID`=54623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 가게가 이렇게 붐비던 때가 기억나는군요...', `MaleText_loc4`='我还记得，在我的商店里看到那么多人流时的情景……', `MaleText_loc5`='我記得以前我的店裡生意也曾經這麼好...', `MaleText_loc7`='Recuerdo cuando mi tienda tenía toda esta afluencia...' WHERE `ID`=54624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 샤트라스 밖으로 나오는 것도 좋지요.', `MaleText_loc4`='能时不时从沙塔斯出来逛逛还真不错。', `MaleText_loc5`='偶爾出撒塔斯城走走也不錯。', `MaleText_loc7`='Está bien salir de Shattrath de vez en cuando.' WHERE `ID`=54625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사과 수레가 전혀 보이지 않는군요...', `MaleText_loc4`='连一辆卖苹果的小货车都看不到……', `MaleText_loc5`='半個蘋果攤都沒有...', `MaleText_loc7`='Ni un solo carrito de manzanas a la vista...' WHERE `ID`=54626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불량 식품이 아주 많군요... 그런데 사과는 하나도 없군요.', `MaleText_loc4`='这么多垃圾食物……连一个苹果都没有。', `MaleText_loc5`='一堆垃圾食物...連一顆蘋果都沒有。', `MaleText_loc7`='Toda esta comida basura... y ni una mísera manzana.' WHERE `ID`=54627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신은 지금도 스미스 할머니가 우리 마구간에 사과를 놓고 갔다고 확신하는 거고요?', `MaleText_loc4`='而你敢确定，那个史密斯奶奶一直把她的苹果放在我们的货摊上？', `MaleText_loc5`='你確定葛蘭尼·史密斯這段時間一直把她的蘋果放在我們的攤位這裡?', `MaleText_loc7`='¿Seguro que esa tal Reineta ha dejado sus manzanas en nuestro puesto todo este tiempo?' WHERE `ID`=54628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 과일 상인이 절대로 우리와 싸우려고 하지 않았다라? 정말 믿기 어렵군요...', `MaleText_loc4`='所以说，水果商其实无意跟我们作对？真是难以置信……', `MaleText_loc5`='所以說那個水果商從來都沒有要跟我們作對?真難以置信...', `MaleText_loc7`='¿Entonces el vendedor de fruta no pretendía declararnos la guerra? Me cuesta creerlo...' WHERE `ID`=54629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 말한 대로 과일 상인이 그 할머니라는 게 사실이라면... 쳇! 그럴 리가 없는데!', `MaleText_loc4`='如果你说水果商是个老奶奶的事真的话……呸！这不可能！', `MaleText_loc5`='如果你說的是真的，那個水果商是個老太太...嘖，我才不信!', `MaleText_loc7`='Si lo que dices de que la vendedora de fruta es una anciana es verdad... ¡Bah! ¡No puede ser!' WHERE `ID`=54630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 제가 소리 지르고, 고함쳐서 사람을 모은 게... 다 헛된 일이라는 거군요... 모두 저를 바보라고 생각할 겁니다...', `MaleText_loc4`='所以我那些卖力的吆喝……都是白费力气……大家肯定觉得我是个白痴……', `MaleText_loc5`='所以我喊了半天，大吼大叫...都沒有意義...大家一定都覺得我很蠢...', `MaleText_loc7`='Pero entonces, mis gritos... mis llamadas a la reunión... Todo para nada... Todo el mundo debe de tomarme por estúpido...' WHERE `ID`=54631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 한숨을 내쉽니다.', `FemaleText_loc4`='$n叹了口气。', `FemaleText_loc5`='$n嘆了口氣。', `FemaleText_loc7`='$n suspira.' WHERE `ID`=54632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 고개를 절레절레 흔들더니 한숨을 내쉽니다.', `FemaleText_loc4`='$n摇摇头，叹了口气。', `FemaleText_loc5`='$n搖了搖頭並嘆了口氣。', `FemaleText_loc7`='$n mueve la cabeza y suspira.' WHERE `ID`=54633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1이;가; 얼굴에 손을 얹더니 긴 한숨을 내쉽니다.', `FemaleText_loc4`='$n用手捂住脸，长叹了一口气。', `FemaleText_loc5`='$n用手遮臉，並長長地嘆了口氣。', `FemaleText_loc7`='$n se lleva la mano a la cara y suspira profundamente.' WHERE `ID`=54634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 지금 배 만들려고 하고 있는 거 안 보이나? 자네랑 나이트 엘프들 때문에 도저히 이 일을 끝낼 수가 없다고!', `MaleText_loc4`='你看不出来我正在努力建造船只吗？一会是你，一会是那些暗夜精灵，我们永远也干不完了！', `MaleText_loc5`='你沒看到我正試著造船嗎?待在你跟那些夜精靈中間，我們永遠都沒辦法把工作完成!', `MaleText_loc7`='¿No ves que estoy intentando construir barcos? ¡Entre tú y esos elfos de la noche, nunca terminaremos este proyecto!' WHERE `ID`=54635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 함선 건조가 왜 늦어지는지 알고 싶어 하십니다.', `MaleText_loc4`='酋长想知道，为什么他的船只迟到了。', `MaleText_loc5`='大酋長想知道為什麼他的船會延遲。', `MaleText_loc7`='El Jefe de Guerra quiere saber por qué se han retrasado sus barcos.', `FemaleText_loc1`='대족장님께서 함선 건조가 왜 늦어지는지 알고 싶어 하세요.', `FemaleText_loc4`='酋长想知道，为什么他的船只迟到了。', `FemaleText_loc5`='大酋長想知道為什麼他的船會延遲。', `FemaleText_loc7`='El Jefe de Guerra quiere saber por qué se han retrasado sus barcos.' WHERE `ID`=54636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장? 덩치 크고, 커다랗고 삐죽삐죽한 어깨받이에, 성격 나쁘고, 도끼에 이상하게 집착하는 그 자 말인가? 그 대족장 말야?', `MaleText_loc4`='酋长？是不是那个总是穿着长刺的巨型肩甲，脾气暴躁，对斧子有种病态偏执的大个子？是那个酋长吗？', `MaleText_loc5`='大酋長?就是身材魁梧，穿著巨大有刺的墊肩，脾氣暴躁，而且對斧頭有病態依賴...的那個大酋長嗎?', `MaleText_loc7`='¿El Jefe de Guerra? ¿Un tipo grande, con hombreras gigantes con pinchos, mal genio y un cariño enfermizo hacia las hachas? ¿ESE Jefe de Guerra?' WHERE `ID`=54637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 실은 말이지, 배가 있긴 있었다고!', `MaleText_loc4`='这个嘛，呃，事实是，原本是有船的。原本有的！', `MaleText_loc5`='嗯，呃，事實是，曾經有過船。「曾經」有過!', `MaleText_loc7`='Bueno, eh, la verdad es que había barcos. ¡Los HABÍA!' WHERE `ID`=54638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근데 어떻게인지 나이프 엘프 놈들이 우리가 함대를 준비하고 있는 걸 알고는 공격해 왔지 뭐야! 새로 만든 배가 대부분 부두에 정박한 채로 불타 버렸어!', `MaleText_loc4`='那些暗夜精灵不知怎的发现了我们要派出舰队，于是就发起了攻击！大部分停泊在港口里的新造船只都被烧毁了！', `MaleText_loc5`='夜精靈不知怎麼發現我們即將下水的艦隊，他們對艦隊進行攻擊!大部分停在港口的的新船隻都被燒了!', `MaleText_loc7`='De alguna forma, los elfos de la noche descubrieron que íbamos a botar la flota, ¡y atacaron! ¡La mayoría de los barcos nuevos se quemaron anclados en el puerto!' WHERE `ID`=54639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 배를 구하기엔 너무 늦었지만, 자네라면 공격자 잔당을 처치해 줄 순 있겠군...', `MaleText_loc4`='我知道要想挽救这些船只已经来不及了，但也——也许你能解决掉剩下的那些攻击者……', `MaleText_loc5`='我知道現在要救他們已經太晚了，但或許你可以解決其他的進攻者。', `MaleText_loc7`='Sé que es demasiado tarde para salvarlos, pero q-quizás podrías acabar con el resto de los atacantes...' WHERE `ID`=54640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장한테 내 잘못이 아니라고 말해 줘! 내 부하들은 망치든 뭐든 손에 잡히는 대로 들고 싸웠던 말이야! 맹세해!', `MaleText_loc4`='去告诉酋长，这不是我的错！我的兄弟们抓起木槌或是手边可用的一切武器奋起回击，我发誓！', `MaleText_loc5`='告訴大酋長這不是我的錯!我的手下已經用手中的木槌甚至一切能拿起來的東西去反擊了，我發誓!', `MaleText_loc7`='¡Dile al Jefe de Guerra que no es culpa mía! Mis muchachos se defendieron con marras o lo que tuvieran a mano, ¡lo juro!' WHERE `ID`=54641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이제 보고만 있지는 않을 것이다. 울두아르의 신성한 전당을 정화하리라!', `MaleText_loc4`='我们的人不能再袖手旁观了。我们必须把整个奥杜尔的所有大厅扫荡一遍！', `MaleText_loc5`='我的人民不會再坐視不管。奧杜亞將被淨化!', `MaleText_loc7`='Mi pueblo no permanecerá impasible ni un minuto más. ¡Limpiaremos las salas de Ulduar!' WHERE `ID`=54642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 사악한 하늘 괴물들과 싸워 놈들 목숨을 빼앗은 위대한 리크리크의 아들이야. 아빠는 죽었고, 이젠 내가 장군이지. 이건 내 비행물건이고. 위대한 장군 리크리크 2세 앞에 고개를 조아리라고!', `MaleText_loc4`='我是伟大的里克里克之子，他曾与邪恶的天怪战斗，抢了他们的财物。他死了，现在我是将军了，这是我的地盘。在强大的将军里克里克二世面前颤抖吧。', `MaleText_loc5`='我是偉大里克·里克的兒子。他和邪惡的飛天蟲蟲打仗拿走他們的蛋蛋。如今他死了，我成了將軍。這是我的飛天蟲蟲。敬畏偉大的里克·里克將軍二代。', `MaleText_loc7`='Yo es hijo de Rik-Rik el Grande, ke luchó contra babiekas malignas del cielo y kogió sus rukos. Murió. Ahora yo es general. Esta es mi kosa del aire. Teme al poderoso general Rik-Rik Jr.' WHERE `ID`=54643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 받으면 탄차오를 열 수 없습니다!', `MaleText_loc4`='我没法在遭受攻击的状态下开启接天桥！', `MaleText_loc5`='我被攻擊時無法開啟天橋!', `MaleText_loc7`='¡No puedo abrir el Tan-Chao mientras me atacan!' WHERE `ID`=54644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변 환경이 어떻든, 균형을 유지해야 하네...', `MaleText_loc4`='你必须无视周围的环境，努力保持平衡……', `MaleText_loc5`='你必須努力保持平衡，無論環境狀態如何...', `MaleText_loc7`='Debes intentar mantener el equilibrio, sin importar el entorno...' WHERE `ID`=54645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 들었나? 안전한 곳에 도착한 모양이군!', `MaleText_loc4`='你听见了吗？他们正安全地待在某个地方！', `MaleText_loc5`='你聽見了嗎?他們在某處，平安無事!', `MaleText_loc7`='¿Lo has oído? ¡Están a salvo en algún lugar!' WHERE `ID`=54646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신. 어서 항구로 가서 나이트윈드 사령관을 만나보세요. 지금 즉시.', `FemaleText_loc4`='你，立刻去港口与指挥官夜风会面。', `FemaleText_loc5`='你，到港口去見指揮官夜風，立刻去。', `FemaleText_loc7`='Tú, ve a ver al Comandante Nochebrisa en el puerto, inmediatamente.' WHERE `ID`=54647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 끄시오.', `MaleText_loc4`='管好你自己的事吧。', `MaleText_loc5`='管你自己的事就好。', `MaleText_loc7`='Métete en tus asuntos.', `FemaleText_loc1`='신경 끄세요.', `FemaleText_loc4`='管好你自己的事吧。', `FemaleText_loc5`='管你自己的事就好。', `FemaleText_loc7`='Métete en tus asuntos.' WHERE `ID`=54648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 실패했군, 이방인.', `MaleText_loc4`='你又失败了，陌生人。', `MaleText_loc5`='你再次失敗了，陌生人。', `MaleText_loc7`='Has vuelto a fracasar, $gforastero:forastera;.' WHERE `ID`=54649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 원하시오?', `MaleText_loc4`='你想要什么？', `MaleText_loc5`='你要什麼?', `MaleText_loc7`='¿Qué es lo que quieres?', `FemaleText_loc1`='뭘 원하세요?', `FemaleText_loc4`='你想要什么？', `FemaleText_loc5`='你要什麼?', `FemaleText_loc7`='¿Qué es lo que quieres?' WHERE `ID`=54650;
