UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병에게 신고해야겠소?', `MaleText_loc4`='你想惹我发火吗？', `MaleText_loc5`='你要我去找那些蠻兵嗎?', `MaleText_loc7`='¿Quieres que llame a los brutos?', `FemaleText_loc1`='경비병에게 신고할까요?', `FemaleText_loc4`='你想惹我发火吗？', `FemaleText_loc5`='你要我去找那些蠻兵嗎?', `FemaleText_loc7`='¿Quieres que llame a los brutos?' WHERE `ID`=54652;
