UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리통에 도끼를 꽂아주기 전에 떠나는 편이 좋을거요.', `MaleText_loc4`='要是你不想让自己的脑壳被斧子劈开，就躲远点！', `MaleText_loc5`='如果你不想有把斧頭劈在你頭上，最好滾遠一點!', `MaleText_loc7`='¡Será mejor que te vayas si no quieres que te incruste un hacha en el cráneo!', `FemaleText_loc1`='머리통에 도끼를 꽂아주기 전에 떠나는 편이 좋을거예요.', `FemaleText_loc4`='要是你不想让自己的脑壳被斧子劈开，就躲远点！', `FemaleText_loc5`='如果你不想有把斧頭劈在你頭上，最好滾遠一點!', `FemaleText_loc7`='¡Será mejor que te vayas si no quieres que te incruste un hacha en el cráneo!' WHERE `ID`=54654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r식으로 상대방을 유혹하는 새로운 의식 같은 거요? 날 내버려 두시오!', `MaleText_loc4`='这是新兴的$r配对仪式还是什么？别来烦我！', `MaleText_loc5`='這是某種新的$r交配儀式還是什麼?讓我靜一靜!', `MaleText_loc7`='¿Esto es una especie de nuevo ritual de apareamiento $r o algo así? ¡Déjame en paz!', `FemaleText_loc1`='$r식으로 상대방을 유혹하는 새로운 의식 같은 건가요? 날 내버려 두세요!', `FemaleText_loc4`='这是新兴的$r配对仪式还是什么？别来烦我！', `FemaleText_loc5`='這是某種新的$r交配儀式還是什麼?讓我靜一靜!', `FemaleText_loc7`='¿Esto es una especie de nuevo ritual de apareamiento $r o algo así? ¡Déjame en paz!' WHERE `ID`=54655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 데서 볼 일은 없습니까?', `MaleText_loc4`='你没其它事情可做了吗？', `MaleText_loc5`='你沒有別的事做嗎?', `MaleText_loc7`='¿No tienes nada que hacer en otra parte?', `FemaleText_loc1`='다른 데서 볼 일은 없나요?', `FemaleText_loc4`='你没其它事情可做了吗？', `FemaleText_loc5`='你沒有別的事做嗎?', `FemaleText_loc7`='¿No tienes nada que hacer en otra parte?' WHERE `ID`=54656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 화내기 전에 여기서 떠나시오!', `MaleText_loc4`='在我发火之前，离我远点儿！', `MaleText_loc5`='在我生氣之前離我遠一點!', `MaleText_loc7`='¡Lárgate de aquí antes de que me enfade!', `FemaleText_loc1`='내가 화내기 전에 여기서 떠나세요!', `FemaleText_loc4`='在我发火之前，离我远点儿！', `FemaleText_loc5`='在我生氣之前離我遠一點!', `FemaleText_loc7`='¡Lárgate de aquí antes de que me enfade!' WHERE `ID`=54657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 수레에 짐이나 실으시오, 일꾼 양반.', `MaleText_loc4`='去马车底下玩吧，倒霉蛋！', `MaleText_loc5`='到貨車下去玩，苦工!', `MaleText_loc7`='¡Vete a jugar entre las ruedas de un carro, peón!', `FemaleText_loc1`='가서 수레에 짐이나 실어요, 일꾼 양반.', `FemaleText_loc4`='去马车底下玩吧，倒霉蛋！', `FemaleText_loc5`='到貨車下去玩，苦工!', `FemaleText_loc7`='¡Vete a jugar entre las ruedas de un carro, peón!' WHERE `ID`=54658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 $C들은 예의를 차릴 줄 모른다니까.', `MaleText_loc4`='我告诉你，现在的$C都不懂礼貌为何物。', `MaleText_loc5`='這陣子的$C很不尊重人，真的是。', `MaleText_loc7`='Los $Cs ya no tienen respeto por nada. Qué vergüenza.', `FemaleText_loc1`='요즘 $C들은 예의를 차릴 줄 모른다니까요.', `FemaleText_loc4`='我告诉你，现在的$C都不懂礼貌为何物。', `FemaleText_loc5`='這陣子的$C很不尊重人，真的是。', `FemaleText_loc7`='Los $Cs ya no tienen respeto por nada. Qué vergüenza.' WHERE `ID`=54659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 그만 쳐다보고 가서 뭔가 도움이 될 일을 하시오!', `MaleText_loc4`='别再盯着我看了，去做些有用的事！', `MaleText_loc5`='別再盯著我看，去找點有用的事做!', `MaleText_loc7`='¡Deja de mirarme y haz algo útil!', `FemaleText_loc1`='날 그만 쳐다보고 가서 뭔가 도움이 될 일을 하세요!', `FemaleText_loc4`='别再盯着我看了，去做些有用的事！', `FemaleText_loc5`='別再盯著我看，去找點有用的事做!', `FemaleText_loc7`='¡Deja de mirarme y haz algo útil!' WHERE `ID`=54660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 나를 어떻게 찾았소?', `MaleText_loc4`='你——你是怎么找到我的？', `MaleText_loc5`='你，你怎麼找到我的?', `MaleText_loc7`='¿Có... cómo me has encontrado?', `FemaleText_loc1`='나... 나를 어떻게 찾았어요?', `FemaleText_loc4`='你——你是怎么找到我的？', `FemaleText_loc5`='你，你怎麼找到我的?', `FemaleText_loc7`='¿Có... cómo me has encontrado?' WHERE `ID`=54661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오, $p 님! 공격받고 있습니다!', `MaleText_loc4`='救命，$p！我被袭击了！', `MaleText_loc5`='幫幫忙，$p!我被攻擊了!', `MaleText_loc7`='¡Socorro, $p! ¡Me atacan!' WHERE `ID`=54662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들을 쫓아 주십시오! 탄차오를 열려면 정신을 집중해야 합니다!', `MaleText_loc4`='别让他们靠近我！我需要集中精神打开接天桥！', `MaleText_loc5`='把他們趕開!我需要全部心力才能打開天橋!', `MaleText_loc7`='¡Quítamelos de encima! Necesito total concentración para abrir el Tan-Chao!' WHERE `ID`=54663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 손님이시군요. 이곳에는 손님이 많지 않죠.$B$B배가 고프신가요? 맛있는 걸 많이 만들어놨답니다.$B$B아니, 아니, 물고기 말고요. 이건 제가 맛있는 걸 하나도 못 잡았을 때 먹으려고 마련해놓은 거예요.', `FemaleText_loc4`='噢，一个客人。我这里的客人可不多。$B$B饿了吗？我做了很多好吃的东西，亲爱的。$B$B不不，不是鱼。只有在我抓不到什么好东西的时候，才会拿鱼出来充数。', `FemaleText_loc5`='噢，有訪客啊。我通常沒什麼訪客。$B$B餓嗎?我煮了很多好吃的東西唷。$B$B不，不，別吃魚。那些是等到我抓不到更好吃的東西才會去吃的。', `FemaleText_loc7`='¡Vaya, una visita! No suelo tener muchas visitas.$B$B¿Tienes hambre? He preparado montones de cosas deliciosas.$B$BNo, no, nada de pescado. Eso es cuando no consigo nada más sabroso, cariño.' WHERE `ID`=54664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 어쩌면 내가 자네에 대해 잘못 생각했었는지도 모르겠군, 이방인.', `MaleText_loc4`='唔，或许我是看错了你，陌生人。', `MaleText_loc5`='唔，也許我看錯你了，陌生人。', `MaleText_loc7`='Mmmm... A lo mejor me equivoqué contigo, $gforastero:forastera;.' WHERE `ID`=54665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='춤추는 빛 속에서 텅 빈 그릇이 보입니다. 우리는 그 그릇을 채우고, 그릇은 우리의 몸이 됩니다. 우리는 안식을 찾습니다.', `MaleText_loc4`='归魂入缶，喜乐安康。', `MaleText_loc5`='在躍動的光亮中，我們見到一只空空的碗。把碗裝滿後，碗變成了我們的身體，於是我們休憩。', `MaleText_loc7`='En la luz danzante vemos una taza vacía. Llenamos la taza, que se convierte en nuestro cuerpo. Descansamos.' WHERE `ID`=54666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진 빚을... 다 갚은 것 같은데...', `MaleText_loc4`='我想……我大部分的债已经还清了……', `MaleText_loc5`='我大部分的債都還了...吧...', `MaleText_loc7`='La mayoría de mis deudas estaban saldadas... eso creo...', `FemaleText_loc1`='진 빚을... 다 갚은 거라고 생각했는데...', `FemaleText_loc4`='我想……我大部分的债已经还清了……', `FemaleText_loc5`='我大部分的債都還了...吧...', `FemaleText_loc7`='La mayoría de mis deudas estaban saldadas... eso creo...' WHERE `ID`=54667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제 여는 것을 도우려 여기 남지 않아도 아무도 상관 안 할 겁니다.', `MaleText_loc4`='我想，就算我不留在这里帮忙经营马戏团，别人也不会介意的吧。', `MaleText_loc5`='我想應該不會有人介意我沒有留下來幫忙馬戲團的生意。', `MaleText_loc7`='No creo que a nadie le importe si no me quedo a ayudar con la feria.', `FemaleText_loc1`='축제 여는 것을 도우려 여기 남지 않아도 아무도 상관 안 할 거예요.', `FemaleText_loc4`='我想，就算我不留在这里帮忙经营马戏团，别人也不会介意的吧。', `FemaleText_loc5`='我想應該不會有人介意我沒有留下來幫忙馬戲團的生意。', `FemaleText_loc7`='No creo que a nadie le importe si no me quedo a ayudar con la feria.' WHERE `ID`=54668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 빚은 거의 다 갚았습니다. 마지막 남은 조금은 안 갚아도 별 탈 없었을 텐데...', `MaleText_loc4`='我的债已经基本还请了。谁也不会在乎剩下的那点金币的……', `MaleText_loc5`='我的債已經還得差不多了。不會有人記得差幾個金幣的。', `MaleText_loc7`='Mis deudas están casi saldadas. Nadie va a echar de menos esas últimas monedas de oro...', `FemaleText_loc1`='제 빚은 거의 다 갚았어요. 마지막 남은 조금은 안 갚아도 별 탈 없었을 텐데...', `FemaleText_loc4`='我的债已经基本还请了。谁也不会在乎剩下的那点金币的……', `FemaleText_loc5`='我的債已經還得差不多了。不會有人記得差幾個金幣的。', `FemaleText_loc7`='Mis deudas están casi saldadas. Nadie va a echar de menos esas últimas monedas de oro...' WHERE `ID`=54669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피해라!', `MaleText_loc4`='躲避攻击!', `MaleText_loc5`='閃躲，閃躲!', `MaleText_loc7`='¡Evasión, evasión!' WHERE `ID`=54670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이 땅의 어둠이 두렵지 않습니다. 어둠은 그 너머의 영광스러운 세상이 드리우는 그림자에 불과하다는 것을 알고 있으니까요.', `MaleText_loc4`='无惧黑暗，彼岸在望。', `MaleText_loc5`='我們不害怕這世界的黑暗，我們知道那不過是彼端那偉大世界所撒落的陰影。', `MaleText_loc7`='No tememos la oscuridad de este mundo. Sabemos que no es más que una sombra, proyectada por el glorioso mundo del más allá.' WHERE `ID`=54671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 이건 뭐지?', `MaleText_loc4`='这到底是什么东西？', `MaleText_loc5`='這是什麼鬼東西??', `MaleText_loc7`='¿Qué demonios es esto?' WHERE `ID`=54672;
