UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 탄차오의 빛을 두려워하지 않습니다. 집으로 돌아가는 길임을 알고 있으니까요. 탄차오는 지상과 하늘을 잇는 다리입니다.', `MaleText_loc4`='接天宝桥，归我故乡。', `MaleText_loc5`='我們不怕天橋的光輝。我們知道那是一條回家的路。連接人世與天際的橋樑。', `MaleText_loc7`='No tememos el brillo del Tan-Chao. Sabemos que es el camino a casa. Es el puente entre la tierra y el cielo.' WHERE `ID`=54680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 길을 잃었습니다. 우린 자신이 누군지, 어디에 속했는지도 알지 못합니다. 어둠 속에서 방황할 뿐...', `MaleText_loc4`='冥途迷茫，不知所往。', `MaleText_loc5`='我們是失落者。我們不知道自己是誰，該歸屬哪裡。我們在黑暗中遊蕩。', `MaleText_loc7`='Somos los perdidos. No sabemos quiénes somos, ni adónde debemos ir. Vagamos en la oscuridad.' WHERE `ID`=54681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깜빡이는 불꽃이 보입니다. 멀리 있는 듯이 보이지만, 실은 가까이에 있음을 우린 알고 있지요.', `MaleText_loc4`='毫光灼灼，在彼一方。', `MaleText_loc5`='我們看到一絲火光。似乎很遙遠，但我們知道它很近。', `MaleText_loc7`='Vemos la luz de una llama. Parece muy lejana, pero sabemos que está cerca.' WHERE `ID`=54682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 가까이 있다. 어둠 속에 몸을 숨겼군. 느껴진다.', `MaleText_loc4`='他就在附近，躲藏在阴影里……我能感觉得到。', `MaleText_loc5`='他就在附近，躲在陰影中...我感覺得到。', `MaleText_loc7`='Está cerca, acechando en las sombras... lo siento.' WHERE `ID`=54683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 경계하라. 차원문이 닫혀선 안 된다.', `MaleText_loc4`='保持警惕。传送门绝不能被封印。', `MaleText_loc5`='保持警覺。不能讓傳送門關閉。', `MaleText_loc7`='¡Cuidado! Los portales no deben sellarse.' WHERE `ID`=54684;
