UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났습니다!', `MaleText_loc4`='完成了！', `MaleText_loc5`='完成了!', `MaleText_loc7`='¡Ya está!' WHERE `ID`=54686;
