UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 괜찮습니다.', `MaleText_loc4`='不了，谢谢。', `MaleText_loc5`='不，謝了。', `MaleText_loc7`='No, gracias.', `FemaleText_loc1`='아니요, 괜찮아요.', `FemaleText_loc4`='不了，谢谢。', `FemaleText_loc5`='不，謝了。', `FemaleText_loc7`='No, gracias.' WHERE `ID`=54688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠사냥꾼 우르코진에게 무슨 볼일이 있습니까?', `MaleText_loc4`='你找暗影猎手乌克金有什么事吗？', `MaleText_loc5`='你找影子獵人爾卡巾有什麼事?', `MaleText_loc7`='¿Qué te traes entre manos con el Cazador de las Sombras Urko''jin?' WHERE `ID`=54689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령들이 우르코진을 위해 이 항해의 토템에 축복을 내렸소. 적과의 전투에 언제나 함께하는 토템이지.', `FemaleText_loc4`='灵魂已经为乌克金祝福了这个远航图腾。它们将随他一同去对抗我们的敌人。', `FemaleText_loc5`='靈魂已賜福爾卡巾的航海圖騰。它們會跟他一同去與我們的敵人作戰。', `FemaleText_loc7`='Los espíritus han bendecido este tótem de navegación para Urko''jin. Van con él a luchar contra nuestros enemigos.' WHERE `ID`=54690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼현자야!!', `MaleText_loc4`='灵魂贤者！！', `MaleText_loc5`='靈魂賢者!!', `MaleText_loc7`='¡Sabio espiritual!' WHERE `ID`=54691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내... 이 고문이 끝나는 것을 보게 되었군요.', `MaleText_loc4`='终于……这无尽的折磨终于结束了。', `MaleText_loc5`='終於...這種苦難有了終點。', `MaleText_loc7`='Al final... esta tortura llegará a su fin.' WHERE `ID`=54692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 토템만 있으면 정령들이 봉쇄 작전에 투입된 당신에게 축복을 내릴 것입니다.', `MaleText_loc4`='有了这个图腾，灵魂将庇佑你参与封锁行动。', `MaleText_loc5`='有了這個圖騰，你過去封鎖線時魂靈們會保佑你。', `MaleText_loc7`='Con este tótem, los eh''píritus bendecirán tu pah''ticipación en el bloqueo.', `FemaleText_loc1`='이 토템만 있으면 정령들이 봉쇄 작전에 투입된 당신에게 축복을 내릴 거예요.', `FemaleText_loc4`='有了这个图腾，灵魂将庇佑你参与封锁行动。', `FemaleText_loc5`='有了這個圖騰，你過去封鎖線時魂靈們會保佑你。', `FemaleText_loc7`='Con este tótem, los eh''píritus bendecirán tu pah''ticipación en el bloqueo.' WHERE `ID`=54693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 내게 호의를 보였군! 내 선원들은 모두 봉쇄 작전에 참여하겠소.', `MaleText_loc4`='灵魂已经赐予我眷顾的启示！我的兄弟们将参加这次封锁行动。', `MaleText_loc5`='魂靈給了我一個吉兆!我的手下會加入這個封鎖線。', `MaleText_loc7`='¡Los eh''píritus me han dado una señal de su favor! Mis hombres se unirán a este bloqueo.' WHERE `ID`=54694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선원 모두를 대표하여 감사하오, $n. 이 토템은 전쟁을 부르는 막강한 전조라오.', `MaleText_loc4`='我的兄弟们对你感激不已，$n。这个图腾是战争的强力征兆。', `MaleText_loc5`='$n，我的手下很感謝你。這圖騰對戰爭來說應該是一個強有力的的好兆頭。', `MaleText_loc7`='Mis hombres te están muy agradecidos, $n. Este tótem es un gran presagio pa'' la guerra.' WHERE `ID`=54695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장에게 검은창 부족의 용맹함과 무시무시한 솜씨를 보여주겠소!', `MaleText_loc4`='我们要向酋长展示暗矛的勇猛和卓越战技！', `MaleText_loc5`='我們要讓大酋長看看黑暗之矛的勇氣與技藝!', `MaleText_loc7`='¡Le demoh''traremos al Jefe de Guerra el valor y la deh''treza de los Lanza Negra!' WHERE `ID`=54696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 곧 저들의 뒤를 따르겠습니다. 하지만 우선은 감사하다는 말씀을...', `MaleText_loc4`='我很快就会赶上他们的，但首先请允许我表达我的谢——', `MaleText_loc5`='我很快就跟上他們，但首先請讓我表達我的謝－', `MaleText_loc7`='Los seguiré enseguida, pero antes quiero expresar mi agradecimiento.' WHERE `ID`=54697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 말했었지? 너를 잡겠다고 말이야, 페이즈. 넌 오늘 수천의 영혼을 우리에게서 빼앗아 갔지만, 너와 바꾸는 조건이라면, 기꺼이 보내주겠다.', `MaleText_loc4`='我说了我会抓住你的，裴智。你今天放跑了几千条灵魂，不过能用它们引你入彀，我就很满足了。', `MaleText_loc5`='我說過我會找到你的，培志。你今天讓我們損失了數千條的魂靈，但若能看到你被束縛，我樂於用他們來交換。', `MaleText_loc7`='Te dije que te atraparía, Pei-Zhi. Hoy nos has costado miles de espíritus, pero renunciaría a ellos de buena gana por verte prisionero.' WHERE `ID`=54698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너, 애송이 $c 녀석아...', `MaleText_loc4`='至于你，小$c。', `MaleText_loc5`='至於你，小$c。', `MaleText_loc7`='Y en cuanto a TI, $gpequeño:pequeña; $c.' WHERE `ID`=54699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 바닥에 흩어진 시체들을 훑어봅니다.', `MaleText_loc4`='%s检查着散落在地上的尸体。', `MaleText_loc5`='%s搜索散落在地上的屍體。', `MaleText_loc7`='%s supervisa los cadáveres esparcidos por el suelo.' WHERE `ID`=54700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼발톱을 더 보내봐야 네 손에 죽기만 하겠지. 이번에는 진지하게 경고하겠다...', `MaleText_loc4`='继续派炮灰来送死是徒劳的。相反，我要给你一个教训……', `MaleText_loc5`='讓更多靈爪去找你送死並沒有意義。相反地，我會給你一個警告...', `MaleText_loc7`='No tiene sentido enviar a más garras para que mueran a tus pies. Solo te dejaré una advertencia...' WHERE `ID`=54701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤도 돌아보지 말고 도망쳐라. 이제 내가 영혼결속을 통해 만들어 낼 존재는 너라도 상대할 수 없을 테니.', `MaleText_loc4`='头也不回地逃跑吧！就算是你，也抵挡不住我的下一次缚灵术！', `MaleText_loc5`='立刻往回逃，永遠不要回頭。就算是你，也永遠不可能面對我下一次縛靈儀式的產物。', `MaleText_loc7`='Sal corriendo y no mires atrás. Ni siquiera tú podrás enfrentarte al producto de mi próxima vinculación de espíritus.' WHERE `ID`=54702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 능글맞게 웃으며 페이즈를 쳐다봅니다.', `MaleText_loc4`='%s看着裴智傻笑。', `MaleText_loc5`='%s看著培志傻笑。', `MaleText_loc7`='%s mira a Pei-Zhi con una sonrisa de satisfacción.' WHERE `ID`=54703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 압니까?', `MaleText_loc4`='我认识你吗？', `MaleText_loc5`='我認識你嗎?', `MaleText_loc7`='¿Te conozco?' WHERE `ID`=54704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에 몸을 숨겼다. 이제 적은 우릴 볼 수 없어.', `MaleText_loc4`='我们现在躲藏在阴影中，不让敌人发现。', `MaleText_loc5`='現在我們躲在陰影中，不讓敵人看到。', `MaleText_loc7`='Ahora nos escondemos de nuestros enemigos en las sombras.' WHERE `ID`=54705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 미끈한 꼬마 우낏이냐? 음?', `MaleText_loc4`='就是你这个光溜溜的小笨蛋？嗯？', `MaleText_loc5`='你是個腦子滑滑的小怪怪人?嗯?', `MaleText_loc7`='¿Makaku kiere manduka? ¿Mm?' WHERE `ID`=54706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 미끈고기와 함께 헤엄친다!', `MaleText_loc4`='把这个蠢货拖出去去喂鱼！', `MaleText_loc5`='怪怪人要和滑魚一起游泳咧!', `MaleText_loc7`='¡Makaku va a nadar con mandukos!' WHERE `ID`=54707;
