UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 유랑단은 제 가족입니다. 절대로 제 가족을 떠날 수는 없습니다.', `MaleText_loc4`='马戏团就是我的家。我永远离不开它。', `MaleText_loc5`='馬戲團是我的家。我絕不會離開我的家庭。', `MaleText_loc7`='La feria es mi familia. Nunca dejaría a mi familia.', `FemaleText_loc1`='다크문 유랑단은 제 가족이에요. 절대로 제 가족을 떠날 수는 없어요.', `FemaleText_loc4`='马戏团就是我的家。我永远离不开它。', `FemaleText_loc5`='馬戲團是我的家。我絕不會離開我的家庭。', `FemaleText_loc7`='La feria es mi familia. Nunca dejaría a mi familia.' WHERE `ID`=54714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움이 필요한 이들이 아주 많군요...', `MaleText_loc4`='需要帮助的人太多了……', `MaleText_loc5`='好多人需要幫助...', `MaleText_loc7`='Muchos necesitan ayuda...', `FemaleText_loc1`='도움이 필요한 이들이 아주 많아요...', `FemaleText_loc4`='需要帮助的人太多了……', `FemaleText_loc5`='好多人需要幫助...', `FemaleText_loc7`='Muchos necesitan ayuda...' WHERE `ID`=54715;
