UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 우낏도 미끈고기 같은 맛일지도 모르겠다...', `MaleText_loc4`='蠢蛋吃上去大概和光板儿差不多……', `MaleText_loc5`='也許怪怪人吃起來就像滑魚...', `MaleText_loc7`='Igual makaku sabe a manduka...' WHERE `ID`=54717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크와의 전쟁은 숨 돌릴 틈도 없는 것 같습니다.', `MaleText_loc4`='对兽人的战争似乎已经迫在眉睫了。', `MaleText_loc5`='與獸人之間的戰爭像是毫無喘息之地。', `MaleText_loc7`='En la guerra contra los orcos parece que no hay descanso.', `FemaleText_loc1`='오크와의 전쟁은 숨 돌릴 틈도 없는 것 같아요.', `FemaleText_loc4`='对兽人的战争似乎已经迫在眉睫了。', `FemaleText_loc5`='與獸人之間的戰爭像是毫無喘息之地。', `FemaleText_loc7`='En la guerra contra los orcos parece que no hay descanso.' WHERE `ID`=54718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 손으로 많은 이를 죽였습니다. 단지 그 참상에서 도망치고 싶었을 뿐이었지요.', `MaleText_loc4`='尽管我手下的亡魂无数，可我只是想逃离那些噩梦而已。', `MaleText_loc5`='有好多人在我手上死去。我只想逃離那樣的惡夢。', `MaleText_loc7`='Han muerto tantos a mis manos. Solo quería escapar de aquel horror.', `FemaleText_loc1`='이 손으로 많은 이를 죽였어요. 단지 그 참상에서 도망치고 싶었을 뿐이었답니다.', `FemaleText_loc4`='尽管我手下的亡魂无数，可我只是想逃离那些噩梦而已。', `FemaleText_loc5`='有好多人在我手上死去。我只想逃離那樣的惡夢。', `FemaleText_loc7`='Han muerto tantos a mis manos. Solo quería escapar de aquel horror.' WHERE `ID`=54719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 유랑단에서는 전쟁의 참혹함을 다시는 직면하지 않게 될 것이라는 약속을 받았습니다.', `MaleText_loc4`='他们向我保证，进了马戏团里就永远不会面临恐怖的战争。', `MaleText_loc5`='他們答應我，在馬戲團這裡，我不會再見到戰爭恐怖的一面。', `MaleText_loc7`='Me prometieron que en la feria no me enfrentaría nunca a los horrores de la guerra.', `FemaleText_loc1`='다크문 유랑단에서는 전쟁의 참혹함을 다시는 직면하지 않게 될 것이라는 약속을 받았어요.', `FemaleText_loc4`='他们向我保证，进了马戏团里就永远不会面临恐怖的战争。', `FemaleText_loc5`='他們答應我，在馬戲團這裡，我不會再見到戰爭恐怖的一面。', `FemaleText_loc7`='Me prometieron que en la feria no me enfrentaría nunca a los horrores de la guerra.' WHERE `ID`=54720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가격만 맞다면야 기꺼이 응하지요.$B$B나즈그림 장군은 명예로운 오크니, 착수금으로 100골드만 받겠습니다. 물론 위험수당은 톡톡히 치르셔야지요.', `MaleText_loc4`='只要价格合理，我和船员们就乐意效劳。$B$B鉴于纳兹戈林将军是位可敬的兽人，我就先要100个金币好了，但要记得给我和兄弟们发放丰厚的危险津贴啊。', `MaleText_loc5`='只要有個好價錢，我跟我的船員都會為您服務。$B$B由於納茲格寧姆將軍是個可敬的獸人，我剛開始只會要求100金，用來慷慨補貼我跟我的手下所要冒的極大危險。', `MaleText_loc7`='Mi tripulación y yo mismo trabajaremos si se trata de un precio justo.$B$BYa que el general Nazgrim es un orco honorable, solo pediré 100 monedas de oro, con un generoso plus de peligrosidad para mí y mis hombres.' WHERE `ID`=54721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 그렇게 하지요.', `MaleText_loc4`='很好。你会拿到钱的。', `MaleText_loc5`='非常好。你會拿到你的金子。', `MaleText_loc7`='Muy bien. Tendrás tu oro.', `FemaleText_loc1`='좋아요. 그렇게 하죠.', `FemaleText_loc4`='很好。你会拿到钱的。', `FemaleText_loc5`='非常好。你會拿到你的金子。', `FemaleText_loc7`='Muy bien. Tendrás tu oro.' WHERE `ID`=54722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 거래가 성사된 겁니다. 전장에서 뵙지요, $n 님.', `MaleText_loc4`='那就这么说定了。战斗中见吧，$n。', `MaleText_loc5`='那麼我們說定了。我們戰場上見，', `MaleText_loc7`='En ese caso tenemos un trato. Te veré en la batalla, $n.' WHERE `ID`=54723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어렸을 때 다크문 유랑단에 들어왔습니다...', `MaleText_loc4`='我在孩提时代就加入了马戏团……', `MaleText_loc5`='我從小就加入了馬戲團...', `MaleText_loc7`='Me uní a la feria cuando era un niño...', `FemaleText_loc1`='어렸을 때 다크문 유랑단에 들어왔어요...', `FemaleText_loc4`='我在孩提时代就加入了马戏团……', `FemaleText_loc5`='我從小就加入了馬戲團...', `FemaleText_loc7`='Me uní a la feria cuando era una niña...' WHERE `ID`=54724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일생의 대부분 동안 다크문 유랑단은 저의 고향이었습니다.', `MaleText_loc4`='我一生中的大部分都是在马戏团里度过的，它就是我的家。', `MaleText_loc5`='我這一生幾乎都以馬戲團為家。', `MaleText_loc7`='Durante gran parte de mi vida, la feria ha sido mi hogar.', `FemaleText_loc1`='일생의 대부분 동안 다크문 유랑단은 저의 고향이었어요.', `FemaleText_loc4`='我一生中的大部分都是在马戏团里度过的，它就是我的家。', `FemaleText_loc5`='我這一生幾乎都以馬戲團為家。', `FemaleText_loc7`='Durante gran parte de mi vida, la feria ha sido mi hogar.' WHERE `ID`=54725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지가 저를 죽이려고 한 뒤에 스트롬에 있는 고향에서 도망쳐왔습니다.', `MaleText_loc4`='为了躲避父亲的毒手，我逃出了位于暴风城里的家。', `MaleText_loc5`='我父親想要殺我，所以我才從激流堡的家逃走。', `MaleText_loc7`='Me fui de mi casa en Strom después de que mi padre intentase matarme.', `FemaleText_loc1`='아버지가 저를 죽이려고 한 뒤에 스트롬에 있는 고향에서 도망쳐왔어요.', `FemaleText_loc4`='为了躲避父亲的毒手，我逃出了位于暴风城里的家。', `FemaleText_loc5`='我父親想要殺我，所以我才從激流堡的家逃走。', `FemaleText_loc7`='Me fui de mi casa en Strom después de que mi padre intentase matarme.' WHERE `ID`=54726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 유랑단 이전의 제 삶은 팍팍했습니다. 그 시절은 기억조차도 하기 싫고, 가족도 보고 싶지 않습니다.', `MaleText_loc4`='加入马戏团之前，我的生活苦不堪言。我一点都不想再回忆起那段时光，和那个家。', `MaleText_loc5`='我加入馬戲團之前的日子非常不好過。我不會懷念那些日子的，也不會想我的家人。', `MaleText_loc7`='La vida antes de la feria era dura. Nunca la eché de menos, ni a mi familia.', `FemaleText_loc1`='다크문 유랑단 이전의 제 삶은 팍팍했죠. 그 시절은 기억조차도 하기 싫고, 가족도 보고 싶지 않아요.', `FemaleText_loc4`='加入马戏团之前，我的生活苦不堪言。我一点都不想再回忆起那段时光，和那个家。', `FemaleText_loc5`='我加入馬戲團之前的日子非常不好過。我不會懷念那些日子的，也不會想我的家人。', `FemaleText_loc7`='La vida antes de la feria era dura. Nunca la eché de menos, ni a mi familia.' WHERE `ID`=54727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에서 벗어나려고 다크문 유랑단에 들어왔습니다.', `MaleText_loc4`='为了逃离那个家，我加入了马戏团。', `MaleText_loc5`='我加入馬戲團是為了逃家...', `MaleText_loc7`='Me uní a la feria para escapar de mi familia.', `FemaleText_loc1`='집에서 벗어나려고 다크문 유랑단에 들어왔어요.', `FemaleText_loc4`='为了逃离那个家，我加入了马戏团。', `FemaleText_loc5`='我加入馬戲團是為了逃家...', `FemaleText_loc7`='Me uní a la feria para escapar de mi familia.' WHERE `ID`=54728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실라스에게 이렇게 말했던 게 기억나는군요. "다시는 제 가족을 보고 싶지 않습니다."', `MaleText_loc4`='我还记得我跟希拉斯说过：“我永远也不想再见到我的家人了。”', `MaleText_loc5`='我還記得我跟希拉斯說，我再也不要見到我的家人了。', `MaleText_loc7`='Recuerdo haberle dicho a Silas: "No quiero volver a ver a mi familia nunca".', `FemaleText_loc1`='실라스에게 이렇게 말했던 게 기억나네요. "다시는 제 가족을 보고 싶지 않아요."', `FemaleText_loc4`='我还记得我跟希拉斯说过：“我永远也不想再见到我的家人了。”', `FemaleText_loc5`='我還記得我跟希拉斯說，我再也不要見到我的家人了。', `FemaleText_loc7`='Recuerdo haberle dicho a Silas: "No quiero volver a ver a mi familia nunca".' WHERE `ID`=54729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 미끈고기랑 우낏을 같이 요리해서 카 카한테 먹여야겠다!', `MaleText_loc4`='……把光板儿蠢蛋煮了……给卡卡大王吃！', `MaleText_loc5`='...要來煮掉腦子滑滑的怪怪人送給咔咔國王吃!', `MaleText_loc7`='... ¡va a kocinar manduka de makaku y dar a rey Ka Ka!' WHERE `ID`=54730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영장에 쓸 장작을 가져오기로 했는데 말입니다...', `MaleText_loc4`='我原本是出来帮营地收集些柴火的……', `MaleText_loc5`='我原本是要替營地收集木柴的...', `MaleText_loc7`='Se suponía que tenía que ir a por leña para el campamento...', `FemaleText_loc1`='야영장에 쓸 장작을 가져오기로 했는데요...', `FemaleText_loc4`='我原本是出来帮营地收集些柴火的……', `FemaleText_loc5`='我原本是要替營地收集木柴的...', `FemaleText_loc7`='Se suponía que tenía que ir a por leña para el campamento...' WHERE `ID`=54731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장작을 모으는 건 정말 힘들었습니다...', `MaleText_loc4`='收集柴火对我来说太辛苦了……', `MaleText_loc5`='這裡好難收集到木柴唷...', `MaleText_loc7`='Ha sido duro recoger la leña...', `FemaleText_loc1`='장작을 모으는 건 정말 힘들었어요...', `FemaleText_loc4`='收集柴火对我来说太辛苦了……', `FemaleText_loc5`='這裡好難收集到木柴唷...', `FemaleText_loc7`='Ha sido duro recoger la leña...' WHERE `ID`=54732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처의 풀숲에서 무언가를 본 것 같았습니다... 그리고는 의식을 잃은 게 아닌가 싶군요.', `MaleText_loc4`='我好像看到附近的灌木丛里有什么东西……然后我就晕过去了。', `MaleText_loc5`='我好像看到附近的草叢裡面有東西...然後我大概就昏倒了。', `MaleText_loc7`='Me pareció ver algo en los arbustos cercanos... y supongo que después me desmayé.', `FemaleText_loc1`='근처의 풀숲에서 무언가를 본 것 같았어요... 그리고는 의식을 잃은 게 아닌가 모르겠어요.', `FemaleText_loc4`='我好像看到附近的灌木丛里有什么东西……然后我就晕过去了。', `FemaleText_loc5`='我好像看到附近的草叢裡面有東西...然後我大概就昏倒了。', `FemaleText_loc7`='Me pareció ver algo en los arbustos cercanos... y supongo que después me desmayé.' WHERE `ID`=54733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨어나고 나니 야영지로 가는 길을 찾을 수가 없었습니다...', `MaleText_loc4`='当我醒来时，已经找不到回营地的路了……', `MaleText_loc5`='等我醒來後，我就找不到回去營地的路了...', `MaleText_loc7`='Cuando me desperté, no pude encontrar el camino de vuelta al campamento...', `FemaleText_loc1`='깨어나고 나니 야영지로 가는 길을 찾을 수가 없었어요...', `FemaleText_loc4`='当我醒来时，已经找不到回营地的路了……', `FemaleText_loc5`='等我醒來後，我就找不到回去營地的路了...', `FemaleText_loc7`='Cuando me desperté, no pude encontrar el camino de vuelta al campamento...' WHERE `ID`=54734;
