UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음조차도 야영지를 지켜야 하는 제 임무를 막을 수는 없습니다...', `MaleText_loc4`='就算是死亡，也不能阻止我履行守护营地的职责……', `MaleText_loc5`='即使死亡都無法阻止我執行看守營地的責任...', `MaleText_loc7`='Ni la muerte me impedirá cumplir mi deber de vigilar el campamento...', `FemaleText_loc1`='죽음조차도 야영지를 지켜야 하는 제 임무를 막을 수는 없어요...', `FemaleText_loc4`='就算是死亡，也不能阻止我履行守护营地的职责……', `FemaleText_loc5`='即使死亡都無法阻止我執行看守營地的責任...', `FemaleText_loc7`='Ni la muerte me impedirá cumplir mi deber de vigilar el campamento...' WHERE `ID`=54737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 숲은 위험합니다. 힘든 대가를 치르고 배운 교훈이지요.', `MaleText_loc4`='这片树林很危险。这是我历经千难万险之后得到的教训。', `MaleText_loc5`='這片樹林相當危險。我是親身嚐過苦頭的。', `MaleText_loc7`='Esos bosques son peligrosos. Una lección que aprendí por las malas.', `FemaleText_loc1`='이 숲은 위험해요. 힘든 대가를 치르고 배운 교훈이랍니다.', `FemaleText_loc4`='这片树林很危险。这是我历经千难万险之后得到的教训。', `FemaleText_loc5`='這片樹林相當危險。我是親身嚐過苦頭的。', `FemaleText_loc7`='Esos bosques son peligrosos. Una lección que aprendí por las malas.' WHERE `ID`=54738;
