UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 오랫동안 야영장을 지켰는지는 잘 모르겠습니다...', `MaleText_loc4`='我也不知道自己已经守护这营地有多久了……', `MaleText_loc5`='我不知道我在營地這裡守護了多久...', `MaleText_loc7`='No sé cuánto tiempo he estado vigilando el campamento...', `FemaleText_loc1`='얼마나 오랫동안 야영장을 지켰는지는 잘 모르겠어요...', `FemaleText_loc4`='我也不知道自己已经守护这营地有多久了……', `FemaleText_loc5`='我不知道我在營地這裡守護了多久...', `FemaleText_loc7`='No sé cuánto tiempo he estado vigilando el campamento...' WHERE `ID`=54740;
