UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실라스가 예전에 저를 잡아갔던 자들로부터 보호해 주었습니다...', `MaleText_loc4`='希拉斯把我从那群绑匪手里救了出来……', `MaleText_loc5`='希拉斯保護我不被之前抓我的人傷害...', `MaleText_loc7`='Silas me mantuvo a salvo de mis antiguos captores...', `FemaleText_loc1`='실라스가 예전에 저를 잡아갔던 자들로부터 보호해 주었죠...', `FemaleText_loc4`='希拉斯把我从那群绑匪手里救了出来……', `FemaleText_loc5`='希拉斯保護我不被之前抓我的人傷害...', `FemaleText_loc7`='Silas me mantuvo a salvo de mis antiguos captores...' WHERE `ID`=54742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 잡아갔던 이들이 끔찍하게 죽는 것을 보았습니다.$b$b그리고 저는 웃음 지었지요.', `MaleText_loc4`='我眼看着那些绑匪死得惨不忍睹。$b$b忍不住哈哈大笑。', `MaleText_loc5`='我看到抓我的人死得很慘。$b$b然後我笑了。', `MaleText_loc7`='Vi como mis captores tenían una muerte horrible.$b$bY me reí.', `FemaleText_loc1`='저를 잡아갔던 이들이 끔찍하게 죽는 것을 보았어요.$b$b그리고 저는 웃음 지었죠.', `FemaleText_loc4`='我眼看着那些绑匪死得惨不忍睹。$b$b忍不住哈哈大笑。', `FemaleText_loc5`='我看到抓我的人死得很慘。$b$b然後我笑了。', `FemaleText_loc7`='Vi como mis captores tenían una muerte horrible.$b$bY me reí.' WHERE `ID`=54743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 유랑단 덕분에 사형을 면했습니다. 제 목숨을 구해준 거지요.', `MaleText_loc4`='马戏团让我逃过一死。它救了我的命。', `MaleText_loc5`='馬戲團把我從處決中救了出來。它拯救了我的生命。', `MaleText_loc7`='La feria me libró de una ejecución. Me salvó la vida.', `FemaleText_loc1`='다크문 유랑단 덕분에 사형을 면했답니다. 제 목숨을 구해준 거죠.', `FemaleText_loc4`='马戏团让我逃过一死。它救了我的命。', `FemaleText_loc5`='馬戲團把我從處決中救了出來。它拯救了我的生命。', `FemaleText_loc7`='La feria me libró de una ejecución. Me salvó la vida.' WHERE `ID`=54744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 유랑단에서 일하는 동안에는 실라스가 제 빚을 대부분 갚아줄 수 있었습니다.', `MaleText_loc4`='只要我为马戏团工作，希拉斯就会帮我偿还大部分债务。', `MaleText_loc5`='只要我在馬戲團工作，希拉斯就會還清我大部分的債務。', `MaleText_loc7`='Silas fue capaz de saldar la mayoría de mis deudas mientras yo trabajaba en la feria.', `FemaleText_loc1`='제가 유랑단에서 일하는 동안에는 실라스가 제 빚을 대부분 갚아줄 수 있었어요.', `FemaleText_loc4`='只要我为马戏团工作，希拉斯就会帮我偿还大部分债务。', `FemaleText_loc5`='只要我在馬戲團工作，希拉斯就會還清我大部分的債務。', `FemaleText_loc7`='Silas fue capaz de saldar la mayoría de mis deudas mientras yo trabajaba en la feria.' WHERE `ID`=54745;
