UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 악마 놈들이 없어질 거다. 그러면 바로 궁전으로 갈 수 있어.', `MaleText_loc4`='恶魔应该都离开了。我们很快就能进入宫殿。', `MaleText_loc5`='這些惡魔應該都離開了，我們很快就能進入宮殿。', `MaleText_loc7`='Todos los demonios se estarán yendo. Llegaremos al palacio enseguida.' WHERE `ID`=54750;
