UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노루토끼를 조심하게! 놈들은 예상치 못한 때 깨무니까 말이야.', `MaleText_loc4`='小心那些鹿角小飞兔！它们总会趁你毫无防备的时候冲出来咬你一口。', `MaleText_loc5`='小心鹿角兔!牠們最會趁你不注意的時候咬你一口。', `MaleText_loc7`='¡Cuidado con los wolpertingers! Te meten un bocado cuando menos te lo esperas.' WHERE `ID`=54752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님께 박수! 걔들이 직접 차 봉지가 돼서 호수를 정화했어요!', `MaleText_loc4`='$p万岁！他们让我把他们变成茶袋，来净化我的湖泊！', `MaleText_loc5`='為$p歡呼!他們為了拯救我的湖，允許我將他們變成一堆茶包!', `MaleText_loc7`='¡Viva $p! ¡Me han dejado convertirlos en una bolsa de té para limpiar el lago!' WHERE `ID`=54753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 감자는 어디 있죠?', `MaleText_loc4`='我的土豆呢？', `MaleText_loc5`='我的甜薯咧?', `MaleText_loc7`='¿Dónde está mi patata?' WHERE `ID`=54754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 세상의 진짜 주인을 모신다! 그들의 지배가 시작되면, 우리가 그 영광을 함께 누릴 것이다!', `MaleText_loc4`='我们侍奉世界真正的主人！当他们的秩序降临，我们将分享他们的荣光！', `MaleText_loc5`='我們服侍這個世界真正的主人!當他們開始統治，我們會分享他們的榮耀!', `MaleText_loc7`='¡Servimos a los verdaderos amos del mundo! Cuando ellos manden, ¡compartiremos su gloria!' WHERE `ID`=54755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 붉은 판다에게는 뭔가 흥미로운 구석이 있네요. 양조사 섀도푸어의 음료를 어떻게 조정해야 치명적인 독성이 없는 맛있는 음료가 될지 대충 알 것도 같아요.', `FemaleText_loc4`='那些小熊猫有点意思。我想我或许可以改进一下酒仙影斟的配方，让酿出的酒不再致命。', `FemaleText_loc5`='紅熊貓有些有趣的特性。我想我好像想到一個方法，能讓釀酒大師影傾的酒不再具有奪魂的美味。', `FemaleText_loc7`='Esos pandas rojos tenían algo interesante. Creo que tengo una idea sobre cómo modificar las bebidas del maestro cervecero Trago Oscuro para que sean sabrosas pero no letales.' WHERE `ID`=54756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난초와 깨끗한 물을 잘 조정해 보면, 궁극의 맥주 제조법이 탄생할지도 몰라요. 아무래도 양조사 섀도푸어의 증류기를 직접 확인해야 실제로 만들 수 있을 것 같아요. 그러려면, 우선 섀도푸어의 방식으로 그에게 승리해야 해요.', `FemaleText_loc4`='我或许可以用兰花和净水开发出一种终极佳酿的配方。但我们必须去酒仙影斟的蒸馏室才能把他酿造出来。为此，我们必须在他的强项上打败他。', `FemaleText_loc5`='藉由蘭花和清水，我可能創造出了終極之酒的配方。我恐怕需要釀酒大師影傾的蒸餾器才有辦法實現。那樣的話，我們得按照他的規則打敗他。', `FemaleText_loc7`='Con las orquídeas y el agua más limpia puedo haber inventado una receta para elaborar la cerveza suprema. Puede que necesite un alambique del maestro cervecero Trago Oscuro para que funcione. Para ello, tenemos que ganarle a su propio juego.' WHERE `ID`=54757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 모아 온 난초를 사용해서 정신나간 양조장이의 골짜기에 있는 호수를 정화할 수 있어요. 하지만 도움이 필요해요.$b$b제 친구 지엔은 물의 정령인데, 제가 맥주를 만드는 데 많은 도움을 줬어요. 이 친구는 물의 밀도를 꼭 필요한 만큼 맞출 수 있어서 큰 도움이 돼요. 이 약초를 어떻게 배분해야 할지 잘 알고 있을 거예요.', `FemaleText_loc4`='我们可以用你收集的兰花来净化疯酒师山谷的湖水。但我们需要帮助。$b$b我的朋友浅浅是个水灵，曾帮我酿造过一些酒。在净化水体时，他是很有帮助的。他应该知道怎么分配这些草药才最合适。', `FemaleText_loc5`='我們可以用你收集到的蘭花淨化瘋狂釀酒師之谷裡的湖水。但我們會需要幫助。$b$b我的朋友吉安是個水靈，曾經幫我自製一些酒，而且非常擅長取得正確密度的水。他會知道怎樣分配這些藥草最好。', `FemaleText_loc7`='Podemos usar las orquídeas que has reunido para purificar el lago en el Valle del Cervecero Loco. Sin embargo, necesitaremos ayuda.$b$bMi amigo Jian es un duende de agua que me ha echado una mano con algunas de mis cervezas y resulta muy útil para obtener la densidad adecuada del agua. Él sabría cuál es la mejor forma de distribuir estas hierbas.' WHERE `ID`=54758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지가 당신을 보냈나요? 전 지를 좋아해요! 아주 행복한 얼굴을 하고 있죠. 하지만 정신나간 양조장이는 크고 뚱뚱한 데다가 얼굴이 건조하고 흉악해요!$b$b물 속의 제 친구들을 낫게 해주실 수 있나요? 얼굴이 건조한 그 흉악범이, 끔찍한 것들을 물 속에 넣어버렸어요.', `MaleText_loc4`='是季派你来吗？我喜欢季！她有一张快活的脸。而疯酒师呢，他是一个刻薄鬼，那张干巴巴的丑脸又大又肥！$b$b你能帮我去安抚我那些水灵朋友吗？那个皱脸的刻薄鬼在水里放了恶心的东西。', `MaleText_loc5`='是紀派你來的嗎?我喜歡紀!她是個開心的傢伙。至於瘋狂釀酒師，他是個又高又胖臉又臭的壞傢伙!$b$b你能幫忙讓我的水朋友舒服一點嗎?那個臉臭臭的壞傢伙放了一堆壞東西進去。', `MaleText_loc7`='¿Te ha enviado Ji? ¡Me gusta Ji! Siempre está contenta. Sin embargo, el cervecero loco es un miserable gordo con la cara seca.$b$b¿Puedes ayudar a mis amigos acuíferos para que se sientan mejor? El miserable de cara seca puso un puñado de porquerías ahí.' WHERE `ID`=54759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 쩍쩍이 없앴어?! 착한 우낏인가?', `MaleText_loc4`='蠢蛋干掉了鳄鱼？好蠢蛋？', `MaleText_loc5`='怪怪人打扁鱷魚?好怪怪人?', `MaleText_loc7`='¿Makaku jeringa al cocodrilo? ¿Makaku bueno?' WHERE `ID`=54760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 호젠 구해주나?', `MaleText_loc4`='蠢蛋救了猢狲？', `MaleText_loc5`='怪怪人救猴人?', `MaleText_loc7`='¿Makaku salva a hozen?' WHERE `ID`=54761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끈고기 하루 더 먹을 수 있다!', `MaleText_loc4`='猢狲没死，又能钓鱼了！', `MaleText_loc5`='猴人明天又可以繼續抓魚了!', `MaleText_loc7`='¡Hozen seguirán pescando!' WHERE `ID`=54762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 쩍쩍이 없애고 호젠 구한 거야?', `MaleText_loc4`='是蠢蛋干掉了鳄鱼，救了猢狲？', `MaleText_loc5`='怪怪人打扁鱷魚救猴人?', `MaleText_loc7`='¿Makaku jeringa a los cocodrilos y salva a los hozen?' WHERE `ID`=54763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 쩍쩍이 없앴다고 호젠이 투키 투키한테 얘기해 줄게!', `MaleText_loc4`='猢狲要告诉图奇图奇，是蠢蛋干掉了鳄鱼！', `MaleText_loc5`='猴人跟兔積·兔積說怪怪人打扁了鱷魚!', `MaleText_loc7`='¡Hozen kuenta a Tuki Tuki que makaku jeringar cocodrilos!' WHERE `ID`=54764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 대체 누구십니까?', `MaleText_loc4`='你到底是谁？', `MaleText_loc5`='你到底是誰?', `MaleText_loc7`='¿Quién eres exactamente?', `FemaleText_loc1`='당신은 대체 누구시죠?', `FemaleText_loc4`='你到底是谁？', `FemaleText_loc5`='你到底是誰?', `FemaleText_loc7`='¿Quién eres exactamente?' WHERE `ID`=54765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘도 숨는구나, 벌레들아. 그런다고 얼마나 목숨을 부지할 것 같으냐?', `MaleText_loc4`='你们很会捉迷藏，虫子。但你们能藏多久呢？', `MaleText_loc5`='你們躲得不錯，蟲子們。你們以為末日能拖多久呢?', `MaleText_loc7`='Se esconden bien, gusanos. Pero no escaparán de su destino.' WHERE `ID`=54766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='색. 대비와 농도, 명암과 색조를 만들어내는 요인입니다. 색채를 조금 바꾸기만 해도, 보는 이가 웃음을 터뜨리거나 눈물을 흘리게 만들 수 있습니다.', `MaleText_loc4`='色彩。它赋予了我们反差、深度、浓淡和色调的变化。稍微调整一下色彩，就能让欢笑中的人们潸然泪下。', `MaleText_loc5`='顏色。賦予我們對比、深淺、質感和基調。簡單的色彩變化就能感動人發笑或哭泣。', `MaleText_loc7`='El color. Nos da contraste, profundidad, valor y tono. El simple cambio de tono puede despertar risas o lágrimas en alguien.' WHERE `ID`=54767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선 하나하나, 붓놀림 하나하나가 모여서 그림을 이룬다네. 그리고 그 그림은 종이를 떠나 하나의 생각이 되어, 보는 이의 눈길을 사로잡지.', `MaleText_loc4`='每一笔一划，都表达了一个意象。它让人们的思想跃然纸上，吸引了观看者的注意力。', `MaleText_loc5`='每一筆，每一劃，都有能力勾勒出一幅圖象。它讓思想躍於紙上，捉住觀者的目光。', `MaleText_loc7`='Cada línea, cada trazo, permite definir una imagen. Separa el pensamiento del papel y capta la atención del que lo ve.' WHERE `ID`=54768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희도 데스윙을 따르는 놈들이냐? 특별히 고통스런 죽음을 맛보게 해주지.', `FemaleText_loc4`='又是一群死亡之翼的信徒？我保证你们会死得特别痛苦。', `FemaleText_loc5`='又是死亡之翼的信徒?我會讓你們死得特別痛苦。', `FemaleText_loc7`='¿Más conversos de Alamuerte? Me encargaré de que su muerte sea especialmente dolorosa.' WHERE `ID`=54769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어버려!', `FemaleText_loc4`='玉石俱焚！', `FemaleText_loc5`='痛哭流涕吧!', `FemaleText_loc7`='¡Sin cuartel!' WHERE `ID`=54770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 영웅담도 여기까지다.', `FemaleText_loc4`='而你的故事也结束了。', `FemaleText_loc5`='你們的故事結束了。', `FemaleText_loc7`='Y así acaba su historia.' WHERE `ID`=54772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보아라, 이방인이여, 죽음이 너흴 감싼다!', `FemaleText_loc4`='看着吧，邪教徒，死亡降临了！', `FemaleText_loc5`='異教徒，看著死亡包圍你們吧!', `FemaleText_loc7`='¡Miren, infieles! ¡La muerte los rodea!' WHERE `ID`=54773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게... 끝나서는... 안 돼.', `FemaleText_loc4`='这不是……我想要的……结局。', `FemaleText_loc5`='不應該...是這樣的結果。', `FemaleText_loc7`='Esto... no debería acabar... así.' WHERE `ID`=54774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 것도 마법이라고. 내 실력을 똑똑히 봐라.', `MaleText_loc4`='你的魔法伎俩真可怜。瞧瞧我的手段吧。', `MaleText_loc5`='你的魔法很可悲。我來讓你看看我的。', `MaleText_loc7`='Tu magia es patética. Deja que te muestre la mía.' WHERE `ID`=54775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨바꼭질 한번 해볼까, 응? 꼭꼭 숨어라, 벌레들아. 그러면 조금은 더 살지도 모르지...', `MaleText_loc4`='让我们玩个游戏吧，嗯？躲好点，虫子，那样你们或许能多活几分钟……', `MaleText_loc5`='我們來玩個遊戲吧，嗯?躲好，蟲子們，這樣也許能活久一點...', `MaleText_loc7`='Esto va a ser como un juego, ¿eh? Escóndanse bien, gusanos, y vivirán un poco más…' WHERE `ID`=54776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 날 방해해?!', `MaleText_loc4`='你们竟敢违抗我？！', `MaleText_loc5`='你竟敢反抗我?', `MaleText_loc7`='¿¡Se atreven a rechazarme!?' WHERE `ID`=54777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자 주제에 내 앞에 서고도 살기를 바라느냐!', `MaleText_loc4`='没有凡人能从我手中逃脱！', `MaleText_loc5`='沒有凡人能在我眼前活下來!', `MaleText_loc7`='¡Ningún mortal que se enfrente a mí saldrá con vida!' WHERE `ID`=54778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있는 동안 많은 자식과 손자를 보았었지. 하지만 내 증손자들은 이제 나를 찾지 않는구나. 위대한 윈드퍼 가문의 혈통을 명예롭게 기억하는 이는 거의 없다.', `MaleText_loc4`='我这一生中有过许多子女，以及许多孙辈。可没有一个曾孙辈的孩子来看望过我。他们几乎都忘了伟大的风裘家族。', `MaleText_loc5`='在世時我有很多子孫，還有很多曾子孫，但我的曾曾子孫都不再來拜訪了。很少人記得要對偉大風毛家族的血脈傳承表示敬意。', `MaleText_loc7`='En vida tuve muchos cachorros, y mis cachorros tuvieron muchos cachorros. Pero ya no me visitan. No quedan muchos que recuerden el gran linaje Pelaje Recio con honor.' WHERE `ID`=54779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정 전도체가 과부하됩니다!', `MaleText_loc4`='一块传导水晶开始过载了！', `MaleText_loc5`='有顆導引晶體超載了!', `MaleText_loc7`='¡Un cristal conductor se sobrecarga!', `FemaleText_loc1`='수정 전도체가 과부하됩니다!', `FemaleText_loc4`='一块传导水晶开始过载了！', `FemaleText_loc5`='有顆導引晶體超載了!', `FemaleText_loc7`='¡Un cristal conductor se sobrecarga!' WHERE `ID`=54780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 사사롭고 보잘것없는 목적을 위해 내게 도전하겠다는 말인가? 좋다. 네가 이 대결에서 승리하면, 나도 둘을 축복해 주는 걸 고려해 보겠다.', `MaleText_loc4`='你想为那个下贱的过街老鼠而战？很好。只要你能打败我，我就会给出我的祝福。', `MaleText_loc5`='你願意擔任這種下等人的勇士?非常好，在戰鬥中擊敗我，我就會考慮賦予你們我的祝福。', `MaleText_loc7`='¿Pretendes abanderar la causa de semejante rata de alcantarilla? Muy bien, derrótame en combate y me plantearé darte mi bendición.' WHERE `ID`=54781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 네가 이겼다... 용사여. 그 건방진 녀석에게 내가 축복을 하겠노라 얘기해 다오.', `MaleText_loc4`='行了！你赢了……勇士。去告诉那个暴发户吧，就说我祝福他。', `MaleText_loc5`='夠了!你贏了...勇士。告訴那個傲慢的傢伙我願意給他祝福。', `MaleText_loc7`='¡Basta! Tú ganas... Dile a ese presuntuoso que cuenta con mi bendición.' WHERE `ID`=54782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시조에게 도전합니다.', `MaleText_loc4`='挑战族长。', `MaleText_loc5`='挑戰潘達族王。', `MaleText_loc7`='Desafía al pandriarca.', `FemaleText_loc1`='시조에게 도전합니다.', `FemaleText_loc4`='挑战族长。', `FemaleText_loc5`='挑戰潘達族王。', `FemaleText_loc7`='Desafía al pandriarca.' WHERE `ID`=54783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가치 없는 것.', `MaleText_loc4`='不值一哂。', `MaleText_loc5`='根本不配。', `MaleText_loc7`='Inaceptable.' WHERE `ID`=54784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 전투였다! 몇십 년 만에 처음으로군. 가서 그 소년에게 내가 축복한다고 전해다오.', `MaleText_loc4`='真痛快！我已经好多年没打得这么痛快过了。为那个孩子带去我的祝福吧。', `MaleText_loc5`='真是一場精采的戰鬥!我好幾十年沒享受過這種感覺了。把我的祝福交給那個孩子吧。', `MaleText_loc7`='¡Ha sido una batalla digna! No había luchado así en muchas décadas. Ve y dale mi bendición al muchacho.' WHERE `ID`=54785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실망스럽군.', `MaleText_loc4`='真扫兴。', `MaleText_loc5`='令人失望。', `MaleText_loc7`='Decepcionante.' WHERE `ID`=54786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강인함! 그것이 바로 브램블스태프 가문의 혈통이다. 내 후손들은 어떤 도전이라도 기꺼이 받아들이는 우월한 육체의 소유자가 되어 지금도 이름을 떨치고 있다.', `MaleText_loc4`='力量！这才是棘杖家族的生命之源。我的家族能延续至今，就是强大的肉身力量不惧任何挑战的最好明证。', `MaleText_loc5`='力量!那就是藤杖家族的生命泉源。直至今日我的血脈仍擁有強大的肉體力量能勇於面對任何挑戰，那就是最好的證明。', `MaleText_loc7`='¡Fuerza! Es la esencia vital de la familia Vara Enzarzada. Que mi linaje sobreviva es una prueba de nuestra grandeza física y de nuestra disposición a enfrentarnos a cualquier reto.' WHERE `ID`=54787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원더브루 가문의 아이가 골든드래프트의 딸과 혼인하려 한다고?! 말도 안 되는 소리.', `MaleText_loc4`='游酒家的人想跟金酿家联姻？！荒唐。', `MaleText_loc5`='蕩酒家的傢伙想要娶金流家的孩子?!荒謬。', `MaleText_loc7`='¿Que un Pócima Errante quiere casarse con una Brisa Dorada? ¡Tonterías!' WHERE `ID`=54788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복한다! 소년이 용사를 잘 골랐군. 가서 내 축복을 전해주고, 녀석이 혹시라도 잘못하는 일이 없게 잘 돌봐다오.', `MaleText_loc4`='我认输！那个小鬼选对了人。请把我的祝福带给他，千万别让他浪费了我的好意。', `MaleText_loc5`='我投降!這孩子懂得選擇他的勇士。我給他我的祝福，可別讓他浪費了。', `MaleText_loc7`='¡Me rindo! El muchacho sabe elegir a sus campeones. Dale mi bendición y asegúrate de que no la desperdicia.' WHERE `ID`=54789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 네가 보인다...', `MaleText_loc4`='我看见你了。', `MaleText_loc5`='我看得到你...', `MaleText_loc7`='Los veo…' WHERE `ID`=54790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사는 무슨...', `MaleText_loc4`='一个支持者。', `MaleText_loc5`='真是勇士。', `MaleText_loc7`='$gMenudo campeón:Menuda campeona;.' WHERE `ID`=54791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 내 혈통이 내 주위에서 흐릿한 기억 속의 존재가 되어가는 것을 목격했다. 한때 모든 양조사들 중 으뜸이던 우리가 이제 스톰스타우트 뒤로 물러나 있다니. 허!', `MaleText_loc4`='我亲眼见证了家族的衰落。我们曾是最伟大的酒仙，现在却只能排在风暴烈酒家族后头，呸！', `MaleText_loc5`='我看著我的血脈就這樣日漸凋零。我們曾是最偉大的釀酒師一族，如今卻是風暴烈酒的後台配角。呿!', `MaleText_loc7`='No puedo más que observar mientras mi linaje se reduce a un recuerdo difuso a mi alrededor. Una vez fuimos los mayores maestros cerveceros del mundo, y ahora somos los segundones de los Cerveza de Trueno. ¡Bah!' WHERE `ID`=54792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람의 이야기를 들어보니, 내 고손녀 지가 꿈에 그리던 양조사가 되는 데 네가 큰 도움을 줬다더구나.$b$b내가 무척 자랑스럽게 생각하는 아이를 그렇게 도와주다니, 정말 고맙게 생각한다. 우리 가문의 이름이 다시 한 번 빛날 계기를 마련해 준 것이나 마찬가지다.', `MaleText_loc4`='风儿告诉我说，你帮助我的曾曾曾孙女季实现了成为酒仙的梦想。$b$b我为她感到骄傲，也非常感谢你的帮助。是你帮我的家族走回了正道。', `MaleText_loc5`='我聽到風傳來的消息說你幫助我的曾曾孫女紀完成她當上釀酒大師的夢想。$b$b我很為她驕傲，也很感謝你的援助。你幫助我家族的名聲走回了正軌。', `MaleText_loc7`='El viento me ha contado que has ayudado a mi bis-bisnieta Ji a conseguir su sueño de convertirse en una maestra cervecera.$b$bEstoy muy orgulloso de ella y te agradezco profundamente que la hayas ayudado. Gracias a ti el nombre de mi familia vuelve a tener futuro.' WHERE `ID`=54793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 내 어린 후손을 옥의 마녀의 사악한 손아귀에서 구해줬다는 소문이 들리더군. 그 영웅적인 행동에 무척 감사하고 있다.', `MaleText_loc4`='我听说，你从青玉巫婆手里救出了我的一个晚辈。对于你的义举，我深表感谢。', `MaleText_loc5`='我聽說就是你將我最年幼的後代從玉巫婆那裡解救出來。謝謝你的英勇。', `MaleText_loc7`='He oído que salvaste a uno de mis descendientes más jóvenes de las garras de la Bruja de Jade. Te agradezco tu heroísmo.' WHERE `ID`=54794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠나십니까?', `MaleText_loc4`='你要走了吗？', `MaleText_loc5`='你要走了?', `MaleText_loc7`='¿Te vas?', `FemaleText_loc1`='떠나시나요?', `FemaleText_loc4`='你要走了吗？', `FemaleText_loc5`='你要走了?', `FemaleText_loc7`='¿Te vas?' WHERE `ID`=54795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족장님과 대화하고 싶습니다.', `MaleText_loc4`='我想和你们的酋长对话。', `MaleText_loc5`='我想和你們酋長談話。', `MaleText_loc7`='Me gustaría hablar con su jefe.', `FemaleText_loc1`='족장님과 대화하고 싶어요.', `FemaleText_loc4`='我想和你们的酋长对话。', `FemaleText_loc5`='我想和你們酋長談話。', `FemaleText_loc7`='Me gustaría hablar con su jefe.' WHERE `ID`=54796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 물이 결코 마르는 일이 없기를.', `MaleText_loc4`='愿你的清水永不干涸。', `MaleText_loc5`='願你的水永不枯竭。', `MaleText_loc7`='Que tu cauce nunca se seque.' WHERE `ID`=54797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망의 징, 이 위풍당당한 모습을 보게! 사실 몇 세기 전에 징을 종으로 교체했네. 예전에 있던 징은 너무 작아서, 우리 백성들의 가슴 속에 희망을 불어넣어 주지 못했거든.', `MaleText_loc4`='看，希望之锣！好吧，没错，这其实是一口钟，几百年前，我们就把原来那面锣给换掉了。那面小锣发出的声音不够洪亮，没办法给我们提供足够的希望之声。', `MaleText_loc5`='看哪，希望之鑼!不過我們幾世紀前就把鑼換成鐘了。老的那口鑼有點小，不是很能將足夠的希望灌輸給我們的百姓。', `MaleText_loc7`='¡Contempla el Gong de la Esperanza! Aunque, en realidad, sustituimos el gong por una campana hace muchos siglos. El antiguo gong era bastante pequeño y no infundía el sentimiento esperanza adecuado a nuestro pueblo.' WHERE `ID`=54798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종과 징의 이야기에 관심이 있나? 요즘에는 이렇게 흥미로운 지적 여행을 떠나려고 하는 젊은이들이 별로 없더군.', `MaleText_loc4`='你对钟和锣的知识有兴趣吗？这年头，像你这样乐意来一场神奇的知识之旅的年轻人可不多了。', `MaleText_loc5`='你對鐘和鑼的傳說有興趣?這陣子，很少有年輕人想進行這樣一趟美妙的知識之旅了。', `MaleText_loc7`='¿Te interesa la historia de la campana y el gong? No hay muchos jóvenes dispuestos a embarcarse en un viaje intelectual tan fascinante hoy en día.' WHERE `ID`=54799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자여, 실례지만 혹시 저 아래 숲에서 대나무를 가져오지 않았나? 하루 종일 군침을 흘리며 바라봐도 배고픔을 누그러뜨릴 수가 없네. 여기서 내가 먹을 수 있는 거라고는 보잘것없는 내 마법으로 만들어내는 것뿐이거든.', `MaleText_loc4`='旅行者，我想冒昧地问一句，你有没有从下面的林子里带点竹子上来？我在这里巴望了一整天了，却只能空流口水。我在这里，只能吃自己用有限的魔法召唤出来的食物。', `MaleText_loc5`='對不起，旅人。你身上是否剛好有前面林裡的竹子?我一整天都盯著那邊流口水、飢腸轆轆。但我在這能吃的只有我微弱魔法所能造出的東西。', `MaleText_loc7`='Discúlpame, $gviajero:viajera;, pero ¿no habrás traído por casualidad algo de bambú del bosque? Me paso el día mirándolo, babeando, hambriento y sin remedio. Todo lo que tengo para comer aquí arriba es lo que puedo invocar con mis limitadas dotes de magia.' WHERE `ID`=54800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<결의에 찬 눈길로 앞을 바라보는 패니 양. 자신의 일에 매우 헌신적입니다.>', `MaleText_loc4`='<范妮小姐坚定地凝视着前方。她下定决心要完成任务。>', `MaleText_loc5`='<范妮小姐毅然瞪著前方。她十分專注於她的工作。>', `MaleText_loc7`='<La señorita Fanny mira hacia delante con determinación. Está entregada a su trabajo.>' WHERE `ID`=54801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기대에 찬 눈으로 당신을 바라보는 패니 양>', `MaleText_loc4`='<范妮小姐充满期待地看着你。>', `MaleText_loc5`='<范妮小姐期待地看著你。>', `MaleText_loc7`='<La señorita Fanny te mira expectante.>' WHERE `ID`=54802;
