UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 친구는 너보다 세다고 해줘.', `FemaleText_loc4`='但愿你的朋友们能表现得好些。', `FemaleText_loc5`='希望你朋友有比較猛。', `FemaleText_loc7`='Espero que tus amigos sepan hacerlo mejor.' WHERE `ID`=54823;
