UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무엇도 날 막을 수 없어! 너도 마찬가지다, 악마야.', `MaleText_loc4`='什么也阻止不了我。连你也不行，恶魔。', `MaleText_loc5`='沒有東西能阻止我。就算你也不行，惡魔。', `MaleText_loc7`='Nada me detendrá. Ni siquiera tú, demonio.' WHERE `ID`=54829;
