UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 차원문을 닫았지? 교활한 벌레들 같으니...', `MaleText_loc4`='是谁关闭了传送门？狡猾的小爬虫。', `MaleText_loc5`='是誰關閉傳送門的?蠻聰明的嘛，小蟲子。', `MaleText_loc7`='¿Quién cerró los portales? ¡Gusanos astutos!' WHERE `ID`=54833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁전으로 가고 싶은 놈은, 악의 힘을 처음으로 얻은 이 페로스안에게 덤벼라!', `MaleText_loc4`='想进入宫殿？先打败佩罗萨恩，魔能的第一个赐福者吧。', `MaleText_loc5`='在擊敗第一個魔化的佩洛薩恩前，沒有人能抵達宮殿!', `MaleText_loc7`='Nadie llegará al palacio sin derrotar a Peroth''arn, ¡el primero de los seres viles!' WHERE `ID`=54834;
