UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘해줬다. 하지만 이젠 나 혼자 가야 해. 행운을 빈다.', `MaleText_loc4`='你干得很好，可现在我必须独自行动了。狩猎愉快。', `MaleText_loc5`='你們做得很好，但是我現在得自己繼續了。狩獵愉快。', `MaleText_loc7`='Lo han hecho bien, pero ahora debo continuar solo. ¡Buena caza!' WHERE `ID`=54839;
