UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 그 어느 때보다 좋습니다! 감사합니다!', `MaleText_loc4`='我的感觉从没这么好过！谢谢你！', `MaleText_loc5`='我從沒感覺這麼好過!謝謝你!', `MaleText_loc7`='¡Nunca me había sentido mejor! ¡Gracias!' WHERE `ID`=54842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 태어난 것 같은 기분이에요! 정말 고마워요, 이방인님.', `MaleText_loc4`='我又重获新生了！谢谢你，陌生人。', `MaleText_loc5`='我感覺像新的一樣!謝謝你，陌生人。', `MaleText_loc7`='¡Me siento como nuevo! Gracias, $gforastero:forastera;.' WHERE `ID`=54843;
