UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠과 우낏... 친구?', `MaleText_loc4`='猢狲跟蠢蛋……做朋友？', `MaleText_loc5`='猴人和怪怪人...是朋友?', `MaleText_loc7`='Hozen y makaku... ¿amigos?' WHERE `ID`=54885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 너 호젠 구해줬다.$b$b우낏이 호젠 사랑하나?', `MaleText_loc4`='蠢蛋在救猢狲？$b$b蠢蛋喜欢猢狲？', `MaleText_loc5`='你在救猴人，怪怪人?$b$b怪怪人愛猴人?', `MaleText_loc7`='¿Makaku ha salvado hozen?$b$b¿Makaku quiere hozen?' WHERE `ID`=54886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 이제 우낏 좋아한다.$b$b우낏도 그렇게 나쁘지 않은 것 같아...', `MaleText_loc4`='猢狲开始喜欢蠢蛋了。$b$b蠢蛋大概没那么坏……', `MaleText_loc5`='猴人開始喜歡怪怪人。$b$b怪怪人或許不是很壞...', `MaleText_loc7`='Makaku kae bien a hozen.$b$bA lo mejor makaku no tan mal.' WHERE `ID`=54887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개가 당신의 존재를 감지합니다!', `MaleText_loc4`='迷雾发现了你！', `MaleText_loc5`='霧感覺到了你的存在!', `MaleText_loc7`='¡La niebla percibe tu presencia!', `FemaleText_loc1`='안개가 당신의 존재를 감지합니다!', `FemaleText_loc4`='迷雾发现了你！', `FemaleText_loc5`='霧感覺到了你的存在!', `FemaleText_loc7`='¡La niebla percibe tu presencia!' WHERE `ID`=54888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개가 당신 주위에 모여듭니다.', `MaleText_loc4`='你周围开始起雾了。', `MaleText_loc5`='霧在你的身邊聚集。', `MaleText_loc7`='La niebla se espesa a tu alrededor.', `FemaleText_loc1`='안개가 당신 주위에 모여듭니다.', `FemaleText_loc4`='你周围开始起雾了。', `FemaleText_loc5`='霧在你的身邊聚集。', `FemaleText_loc7`='La niebla se espesa a tu alrededor.' WHERE `ID`=54889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 주위에서 안개가 더욱 짙어집니다.', `MaleText_loc4`='你周围的雾气愈发浓密了。', `MaleText_loc5`='在你身邊，霧變得濃厚。', `MaleText_loc7`='A tu alrededor, la niebla se vuelve más densa.', `FemaleText_loc1`='당신 주위에서 안개가 더욱 짙어집니다.', `FemaleText_loc4`='你周围的雾气愈发浓密了。', `FemaleText_loc5`='在你身邊，霧變得濃厚。', `FemaleText_loc7`='A tu alrededor, la niebla se vuelve más densa.' WHERE `ID`=54890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개가 당신을 붙잡습니다!', `MaleText_loc4`='迷雾彻底吞没了你！', `MaleText_loc5`='霧將你團團包圍!', `MaleText_loc7`='¡La niebla te envuelve!', `FemaleText_loc1`='안개가 당신을 붙잡습니다!', `FemaleText_loc4`='迷雾彻底吞没了你！', `FemaleText_loc5`='霧將你團團包圍!', `FemaleText_loc7`='¡La niebla te envuelve!' WHERE `ID`=54891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 속에서 한 생물이 나타납니다!', `MaleText_loc4`='迷雾之外浮现出了一个生物！', `MaleText_loc5`='從霧中竄出了一個生物!', `MaleText_loc7`='¡Una criatura surge de la niebla!', `FemaleText_loc1`='안개 속에서 한 생물이 나타납니다!', `FemaleText_loc4`='迷雾之外浮现出了一个生物！', `FemaleText_loc5`='從霧中竄出了一個生物!', `FemaleText_loc7`='¡Una criatura surge de la niebla!' WHERE `ID`=54892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개가 사라집니다...', `MaleText_loc4`='迷雾散去了……', `MaleText_loc5`='霧消退了...', `MaleText_loc7`='La niebla se disipa...', `FemaleText_loc1`='안개가 사라집니다...', `FemaleText_loc4`='迷雾散去了……', `FemaleText_loc5`='霧消退了...', `FemaleText_loc7`='La niebla se disipa...' WHERE `ID`=54893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 수평으로 균형을 잡습니다.', `MaleText_loc4`='%s保持平衡。', `MaleText_loc5`='%s回復平衡。', `MaleText_loc7`='%s se estabiliza.' WHERE `ID`=54894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 붙잡히기 전에, 난 호젠 스무 마리를 해치웠다!', `MaleText_loc4`='我被俘之前，足足干掉了二十个猢狲！', `MaleText_loc5`='在被抓到前我幹掉了二十個猴人!', `MaleText_loc7`='¡Acabé con veinte hozen antes de que me capturaran!' WHERE `ID`=54897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 우리에 갇힌 게 다행인 줄 알아라.', `MaleText_loc4`='我被关在笼子里是你的运气。', `MaleText_loc5`='有我在這籠子裡是你的好運。', `MaleText_loc7`='Tienes suerte de que esté encerrado.' WHERE `ID`=54898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일족과 새로운 동맹이 이 마을을 온통 불태워 버릴 것이다.', `MaleText_loc4`='我的人民和他们的新盟友会把这个村子夷为平地的。', `MaleText_loc5`='我的人和他們的新盟友會把這座村子燒成平地。', `MaleText_loc7`='Mi pueblo y sus nuevos aliados reducirán esta aldea a cenizas.' WHERE `ID`=54899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠! 너희 시간은 끝났다. 우리에게 새로운 동맹군이 생겼으니까!', `MaleText_loc4`='猢狲！你们的好日子到头了。我们有新盟友了！', `MaleText_loc5`='猴人!你們活不長了。我們有了新的盟友!', `MaleText_loc7`='¡Hozen! Se os agota el tiempo. ¡Tenemos nuevos aliados!' WHERE `ID`=54900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 웃기게 생긴 녀석이다.', `MaleText_loc4`='你的样子真可笑。', `MaleText_loc5`='你是個怪長相的傢伙。', `MaleText_loc7`='Eres un miko un poko raro.' WHERE `ID`=54901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발하겠습니다! 시간이 없습니다.', `MaleText_loc4`='我们行动吧，朋友！不能再浪费时间了。', `MaleText_loc5`='出發吧，朋友。我們沒有時間了。', `MaleText_loc7`='¡En marcha! No hay tiempo que perder.' WHERE `ID`=54902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코라스트라자가 속상해 하는 것도 당연합니다. 그 알은 데스윙의 타락에서 무사하다고 생각되는 유일한 검은용 알이었으니까요.', `MaleText_loc4`='科拉丝塔萨的焦虑也是可以理解的。毕竟她照料着唯一一枚没有被死亡之翼的堕落所腐蚀的黑龙蛋……', `MaleText_loc5`='寇菈史卓莎顯然不高興。在她的保護下，我們相信有顆黑龍蛋沒有受到死亡之翼的污染...', `MaleText_loc7`='Es comprensible que Corastrasza esté decepcionada. Estaba al cuidado de un huevo de dragón Negro que creíamos libre de la maldición de la corrupción de Alamuerte...' WHERE `ID`=54903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 그렇게 소중한 알을 하룻밤 사이에 도둑맞다니요!', `MaleText_loc4`='……可一群小偷却趁夜从我们手里偷走了它！', `MaleText_loc5`='...而它居然在晚上被賊偷走了!', `MaleText_loc7`='... ¡y unos ladrones nos lo robaron durante la noche!' WHERE `ID`=54904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 덕분에 그나마 단서를 얻었군요. 라벤홀트 장원의 도적들 말입니다.', `MaleText_loc4`='你帮我们找到了唯一的线索。拉文霍德的盗贼就是幕后黑手。', `MaleText_loc5`='你替我們找到了唯一的線索。是拉文霍德的盜賊搞的鬼。', `MaleText_loc7`='Has encontrado nuestra única pista. Los pillos de Ravendholt son los culpables.' WHERE `ID`=54905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라벤홀트라니... 이건 말도 안 됩니다! 그런 오합지졸들이 검은용 알에 대해 어떻게 알았을까요?', `MaleText_loc4`='拉文霍德？这可真奇怪！那不过是一群小毛贼。他们怎么可能知道龙蛋的事？', `MaleText_loc5`='拉文霍德?這根本說不通!只是群烏合之眾的盜賊而已。他們怎麼會知道這顆龍蛋?', `MaleText_loc7`='¿Ravenholdt? ¡No tiene sentido! Una insignificante banda de ladronzuelos. ¿Cómo sabrán de la existencia del huevo?' WHERE `ID`=54906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일을 끝까지 파헤쳐야 합니다. 그러려면 당신 같은 분이 필요합니다.', `MaleText_loc4`='我们会查清这件事的。我们正需要你这样有能力的人。', `MaleText_loc5`='我們會追查到底。我們正需要像你這樣的人才。', `MaleText_loc7`='Llegaremos al fondo del asunto. Alguien con tu capacidad es justo lo que necesitamos.' WHERE `ID`=54907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 말이 있잖습니까. 도적은 도적으로 잡는 거라고요.', `MaleText_loc4`='俗话怎么说的？“以其人之道”的后面？', `MaleText_loc5`='那句話是怎麼說的?「以賊抓賊」對吧?嗯?', `MaleText_loc7`='¿Cómo era la expresión? Era "quien roba a un ladrón...", ¿no?' WHERE `ID`=54908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 황량한 광경을 보십시오... 2차와 3차 대전쟁에 의한 파괴의 흔적이 아직도 곳곳에 남아 있습니다.', `MaleText_loc4`='看看这片狼藉的土地。这片丘陵一直没能从第二次和第三次战争中恢复过来。', `MaleText_loc5`='看看這片荒涼。這片丘陵一直沒有從第二和第三次戰爭的戰役中復原。', `MaleText_loc7`='Contempla la devastación. Estas laderas nunca se han recuperado de las campañas de la Segunda y la Tercera Guerra.' WHERE `ID`=54909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기저기 잔해와 쓰레기가 널려 있습니다. 라벤홀트 장원의 도둑과 암살자 놈들도 그 일부라고 할 수 있죠.', `MaleText_loc4`='到处都是废墟和遗骸……我原以为拉文霍德的盗贼和刺客不过是其中的一部分。', `MaleText_loc5`='放眼望去盡是廢墟跟瓦礫...對我來說，拉文霍德的盜賊跟殺手也是殘破瓦礫的一部分。', `MaleText_loc7`='Ruinas y escombros ensucian el paisaje... y considero a los ladrones y asesinos de Ravenholdt una parte de esa basura.' WHERE `ID`=54910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라도 없고... 대의도 없는데... 그들은 뭘 위해 움직이는 걸까요?', `MaleText_loc4`='没有动机……没有理由……你觉得他们到底怎么了？', `MaleText_loc5`='沒有歸屬，沒有目標...你難道不好奇是什麼在驅使他們的?', `MaleText_loc7`='Sin un cargo... Sin una causa... ¿Qué les guiará? ¿No te lo preguntas?' WHERE `ID`=54911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 무슨 일이 있었길래 붉은용군단을 건드린 걸까요? 이해가 안 됩니다. 더 조사해 봐야 합니다!', `MaleText_loc4`='他们到底是着了什么魔，竟敢和红龙军团作对？真是疯了。我们必须了解真相！', `MaleText_loc5`='是什麼在驅使他們跟紅龍軍團作對?太瘋狂了。我們得更深入了解!', `MaleText_loc7`='¿Y qué les llevó a atacar al Vuelo Rojo? La locura. ¡Debemos averiguar más al respecto!' WHERE `ID`=54912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 라벤홀트 장원입니다.', `MaleText_loc4`='我们接近拉文霍德庄园了。', `MaleText_loc5`='我們快到拉文霍德莊園了。', `MaleText_loc7`='Casi hemos llegado a la Mansión Ravenholdt.' WHERE `ID`=54913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알이 거기 있다면, 전면 공격은 알을 위험에 빠뜨릴 수도 있습니다. 몰래 잠입해서, 놈들의 계획을 알아내십시오. 어떻게든 알을 되찾아야 합니다.', `MaleText_loc4`='如果他们拿到了那枚蛋，那么发动全面进攻就太危险了。你需要潜入那里，查清他们的阴谋……并不惜一切夺回那枚蛋。', `MaleText_loc5`='如果龍蛋在他們手上，全面出擊太過危險。你必須潛入那裡，查出他們想做什麼...並不計任何代價取回龍蛋。', `MaleText_loc7`='Si tienen el huevo es demasiado arriesgado intentar un asalto general. Vas a tener que colarte allí sin que lo noten, enterarte de qué traman... y recuperar el huevo a toda costa.' WHERE `ID`=54914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 이제 이 동굴 안에서 계획을 짜야 합니다.', `MaleText_loc4`='安静点！我们要在这个洞穴里制定一个计划……', `MaleText_loc5`='安靜!我們就在這洞裡做好計畫...', `MaleText_loc7`='¡Ahora, silencio! Elaboraremos un plan en esta cueva...' WHERE `ID`=54915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어라, 벌레들아! 사냥이 시작된다...', `MaleText_loc4`='躲起来吧，虫子！狩猎开始了……', `MaleText_loc5`='躲好啊，蟲子們!開始狩獵囉...', `MaleText_loc7`='¡Escóndanse, gusanos! La caza comenzó…' WHERE `ID`=54916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요그토드 얘기 들었어? 내게 갚을 돈이 있었는데.', `MaleText_loc4`='约格塔德的口信？他还欠我钱呢。', `MaleText_loc5`='從尤革妥那聽說的?他欠我一顆蛋蛋。', `MaleText_loc7`='¿Makaku sabe de Yoggtard? Me debe rukos.' WHERE `ID`=54917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 정말 끝내주는 곳이군요! 음식이 얼마나 많이 쌓여 있는지 보셨습니까?', `MaleText_loc4`='这地方太棒了！看到他们这里有多少食物了吗？', `MaleText_loc5`='這地方真是太棒了!你有沒有看到他們這裡有多少的食物?', `MaleText_loc7`='¡Este lugar es genial! ¿Has visto cuánta comida tienen aquí?' WHERE `ID`=54918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 다른 친구들은 신나는 모험을 떠난 것 같지만, 저는 신경 쓰지 않습니다. 저는 여기 이렇게 앉아 있는 게 딱 맞습니다.', `MaleText_loc4`='当然，其他人可能已经踏上了激动人心的探险之旅，但我并不在乎。我在这里过得非常开心。', `MaleText_loc5`='當然，其他人可能會停止這刺激的冒險，但我不在意。我在這裡實在是再快樂不過了。', `MaleText_loc7`='Bueno, puede que los demás se hayan marchado a vivir emocionantes aventuras, pero no me importa. Yo soy perfectamente feliz aquí.' WHERE `ID`=54919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원에서부터 쉬지 않고 계속 걸어왔더니 발이 쑤셔 죽겠군요. 배도 등가죽에 붙을 지경이고 말입니다. 다시 움직일 수 있겠다 싶을 때까지 여기 머물며 배나 채워야겠습니다.', `MaleText_loc4`='从修道院长途跋涉而来可苦了我的脚——还有我的胃。我想在重新考虑启程先在这儿大吃一顿，以恢复体力。', `MaleText_loc5`='從修道院走過來這段漫長的路，讓我的兩腿都要廢了，也讓我餓翻了。若不讓我花點時間補充能量，我是不會考慮再度站起來的。', `MaleText_loc7`='La larga caminata desde el monasterio ha acabado con mis pies y me ha despertado un gran apetito. Creo que voy a estar aquí mucho tiempo reponiendo fuerzas antes de volver a ponerme de pie.' WHERE `ID`=54920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 모르실까 봐 말씀드리는 건데, 이곳은 가족이 함께 운영하는 사육장입니다. 썬더풋 가문은 싸우지 않고, 모험도 즐기지 않습니다... 그런 짓을 할 정도로 술을 많이 마시지도 않지요.$b$b하지만 우리는 먹는 것은 아주 좋아합니다.', `MaleText_loc4`='不知道你发现了没有，这是个家庭农场。我们雷脚家的人不斗争、不探险……甚至不怎么喝酒。$b$b但我们很享受美食带来的快乐。', `MaleText_loc5`='提醒你一下，這是一個家庭農場。我們雷足不與人爭鬥，不深究細節...我們甚至也不大喝酒。$b$b不過，我們非常重視「吃」。', `MaleText_loc7`='Esto es una granja familiar, por si no te has dado cuenta. Los Pie Atronador no peleamos ni exploramos... ni siquiera bebemos tanto.$b$bEso sí, nos gusta mucho nuestra comida.' WHERE `ID`=54921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돼지 사육장을 하는 건 당신이 생각하는 것 이상으로 품이 많이 듭니다... 결과적으로만 본다면 "돼지를 먹일 음식을 더 찾는" 일이기는 하지만요.', `MaleText_loc4`='经营养猪场比你想象的要复杂……尽管多数时候可以将其概括为“寻找更多的猪食”。', `MaleText_loc5`='經營一個養豬場的工作比你想像的要多得多...雖然大部分的工作都可以歸類為「找更多食物來餵豬」。', `MaleText_loc7`='Mantener una granja de cerdos tiene mucho más trabajo del que piensas... aunque la mayor parte puede reducirse a "buscar más comida para los cerdos".' WHERE `ID`=54922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 독수리가!$b$b아아아! 늑대다!', `MaleText_loc4`='啊啊！老鹰！$b$b啊啊啊啊！狼来了！', `MaleText_loc5`='啊!老鷹!$b$b哇啊啊!狼!', `MaleText_loc7`='¡Aaah! ¡Halcones!$b$b¡AAAAH! ¡LOBOS!' WHERE `ID`=54923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이상은 저도 어떻게 할 수가 없어요! 제가 정말 저 늑대들과 싸워야 하는 건가요?', `MaleText_loc4`='我再也受不了了！我真的要去对付那些狼吗？', `MaleText_loc5`='我沒辦法再承受這些了!我真的得去跟那些狼戰鬥嗎?', `MaleText_loc7`='¡No puedo seguir aguantando mucho más! ¿En serio tengo que enfrentarme a esos lobos?' WHERE `ID`=54924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 양들이! 누가 어떻게 좀 해 주세요!', `MaleText_loc4`='我的羊！来人啊，帮帮忙啊！', `MaleText_loc5`='我的羊!誰來幫幫忙啊!', `MaleText_loc7`='¡Mis ovejas! ¡Que alguien haga algo!' WHERE `ID`=54925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌! 어서요! 뭘 꾸물거리는 거예요?', `FemaleText_loc4`='走吧，陈叔！我们还等什么呢？', `FemaleText_loc5`='來吧，老陳叔叔!我們到底在等什麼?', `FemaleText_loc7`='¡Vamos, tío Chen! ¿Qué estamos esperando?' WHERE `ID`=54926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라, 리 리. 판다리아를 탐험할 시간은 차고 넘친단다. 느긋하게 여행을 즐기렴.', `MaleText_loc4`='别着急，丽丽。我们有大把的时间来探索潘达利亚。花点时间来享受这个旅程吧。', `MaleText_loc5`='放輕鬆，莉莉。我們還有很多時間可以探索潘達利亞。放慢步調享受這趟旅程吧。', `MaleText_loc7`='Tranquila, Li Li. Tenemos todo el tiempo del mundo para explorar Pandaria. Relájate y disfruta del viaje.' WHERE `ID`=54927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딜 가야 여행을 즐기든 말든 할 거 아니에요!', `FemaleText_loc4`='我是想“享受”旅程，可那也得先“出发”才行！', `FemaleText_loc5`='如果我們真的有要「去」哪，我應該會更「享受」這趟旅程!', `FemaleText_loc7`='¡Disfrutaría más del viaje si de verdad estuviéramos yendo a alguna parte!' WHERE `ID`=54928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가도 돼요? 맥주 다 드셨어요?', `FemaleText_loc4`='能走了吗？啤酒喝完了吗？', `FemaleText_loc5`='我們可以走了嗎?你啤酒喝夠了沒?', `FemaleText_loc7`='¿Podemos irnos ya? ¿Terminaste la cerveza?' WHERE `ID`=54929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직.', `MaleText_loc4`='快喝完了。', `MaleText_loc5`='快了。', `MaleText_loc7`='Casi.' WHERE `ID`=54930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제는요?', `FemaleText_loc4`='那现在呢？', `FemaleText_loc5`='現在呢?', `FemaleText_loc7`='¿Y ahora?' WHERE `ID`=54931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 어서 가요! 저 거대한 계곡이 우리를 기다리는데, 삼촌은 술잔 바닥만 쳐다보고 있을 거예요?', `FemaleText_loc4`='出发吧！整个大峡谷等着我们去探索呢，可是你却只盯着杯底那点儿啤酒。', `FemaleText_loc5`='我們走了啦!你兩眼只顧盯著酒杯，都看不到前面有一整座山谷等著我們來探險。', `FemaleText_loc7`='¡Vamos, en marcha! Nos espera todo un valle, pero estás demasiado concentrado en el fondo de esa jarra como para darte cuenta.' WHERE `ID`=54932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 알았다, 리 리. 그런데 이 술잔 바닥이 참 재미있게 생겨서 말이지.', `MaleText_loc4`='是啊，丽丽，但是这杯底的啤酒确实非常吸引我。', `MaleText_loc5`='好吧，莉莉。不過我真的覺得能看到杯子的底部非常有趣。', `MaleText_loc7`='Sí, Li Li, pero el fondo de esta jarra me resulta muy interesante.' WHERE `ID`=54933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌 그냥 놔두고 갈래요. 정말이라고요. 냄새나는 늙은 삼촌 손 잡고 다니기 싫어요.', `FemaleText_loc4`='那我自己去。别以为我只是随口说说。我可不需要某个臭哄哄的大叔牵着我。', `FemaleText_loc5`='我要自己過去了。別以為我嚇唬你。我不需要什麼臭臭的老叔叔牽我的手。', `FemaleText_loc7`='Me iré sin ti. No estoy alardeando. No necesito que un tío viejo y apestoso me lleve de la mano.' WHERE `ID`=54934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그리 마음이 급한 게냐? 내가 술을 다 마시기 전에 다시 안개가 낄까 봐 그러는 거니?', `MaleText_loc4`='你怎么这么没耐心？难道你担心我还没喝完啤酒，迷雾又把岛笼罩起来了？', `MaleText_loc5`='妳怎麼這樣沒耐心?妳擔心我喝完啤酒前便會起霧嗎?', `MaleText_loc7`='¿Por qué eres tan impaciente? ¿Te preocupa que vuelva la niebla antes de que me termine mi bebida?' WHERE `ID`=54935;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헉, 듣고 보니 그렇네요!', `FemaleText_loc4`='我还真担心！', `FemaleText_loc5`='你說得沒錯!', `FemaleText_loc7`='¡Bueno, ahora sí!' WHERE `ID`=54936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 평생 처음으로 조상님의 고향에 발을 들이려는 참인데, 아니 삼촌은 고작 돼지 농장에서 쉬어 가고 싶다는 거예요?', `FemaleText_loc4`='我们好不容易才回到故土，有生以来第一次踏上这片土地，你难道只想在养猪场里休息吗？', `FemaleText_loc5`='有生以來第一次，我們終於踏上我們祖先的土地。而你打算停下來在一個豬圈裡休息?', `FemaleText_loc7`='Estamos aquí, por fin pisamos nuestro hogar ancestral, por primera vez en la vida... ¿y te quieres parar a descansar junto a una granja de cerdos?' WHERE `ID`=54937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두를 거 없다, 리 리. 판다리아를 너무 빨리 구경하면 구경거리가 금방 없어질 테니까.', `MaleText_loc4`='耐心点儿吧，丽丽。如果我们那么快就把潘达利亚逛个遍，那我们很快就没得玩了。', `MaleText_loc5`='耐心點，莉莉。如果我們探索得太快，潘達利亞很快就沒有地方可以讓我們冒險了。', `MaleText_loc7`='Ten paciencia, Li Li. Si exploramos Pandaria demasiado rápido, nos quedaremos sin Pandaria que explorar.' WHERE `ID`=54938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐야... 말도 안 돼요! 삼촌이 게으르고 늙어서 그런 소리를 하는 거잖아요!', `FemaleText_loc4`='这……你说的都是废话！你这么说都是因为你又老又懒！', `FemaleText_loc5`='這...這一點都說不通!你這麼說只是因為你又老又懶!', `FemaleText_loc7`='¡Es que... no tiene ningún sentido! ¡Solo lo dices porque eres un viejo perezoso!' WHERE `ID`=54939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[TEMP] 여기 머물러도 될까요. 아이고 감사합니다.', `MaleText_loc4`='[TEMP]我能留在这儿吗？好的。谢谢！', `MaleText_loc5`='[TEMP] CAN I STAY HERE OK THANKS', `MaleText_loc7`='[TEMP] PUEDO QUEDARME AQUÍ VALE GRACIAS' WHERE `ID`=54940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그저 자네가 여행을 시작하게 도와줬을 뿐이네. 커다란 보상이 기다리고 있겠지만, 이를 무사히 마치느냐 그렇지 못하느냐는 모두 자네에게 달려 있네.', `MaleText_loc4`='我只能帮助你开始这段旅程。丰厚的奖励在等待着你，可是否要完成它就完全取决于你自己了。', `MaleText_loc5`='我不過是幫助你開始最初的旅程。巨大的寶藏正在前方等待，但是否能得到它全操之在你。', `MaleText_loc7`='No he hecho más que ayudarte a comenzar tu camino. Te esperan grandes recompensas, pero si llegas hasta el final depende de ti.' WHERE `ID`=54941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 주위에 강한 기운이 맴돌고 있네. 자네가 이 땅에 빛을 가져올지 어둠을 가져올지, 나는 아직 알 수 없지만, 자네가 강인한 마음을 가진 이라는 사실은 알 수 있겠군.', `MaleText_loc4`='你的气势很惊人，陌生人。我还无法确定你究竟会给这片大陆带来光明还是黑暗，可我知道你有一颗坚定的心。', `MaleText_loc5`='你的存在非常有份量，陌生人。我還不確定你到底會為這片土地帶來光明或者黑暗，但我知道你擁有強大的內心。', `MaleText_loc7`='Tienes una presencia muy fuerte, $gforastero:forastera;. Aún no sé si traerás luz u oscuridad a esta tierra, pero sí sé que tu corazón es fuerte.' WHERE `ID`=54942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이방인을 좋아하지 않지만, 자네 안에 커다란 힘이 담겨 있음을 알 수 있네. 그래... 정말 흥미로운 수련생이 될 수도 있겠어...', `MaleText_loc4`='我不喜欢陌生人，可我在你身上看到了巨大的潜力。是的……你或许会成为一个非常有趣的徒弟。', `MaleText_loc5`='我不喜歡陌生人，但我在你身上看見強大的潛力。是的...你或許會是非常有趣的學生。', `MaleText_loc7`='No me gustan los forasteros, pero veo mucho potencial en ti. Sí... Vas a ser $gun discípulo:una discípula; de lo más interesante.' WHERE `ID`=54943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈결 맥주가 한 잔 더 필요합니다, 사부님.', `MaleText_loc4`='我还需要一瓶洄梦仙酒，大师。', `MaleText_loc5`='我需要另一份夢幻之釀，大師。', `MaleText_loc7`='Necesito otro brebaje de ensueño, maestro.', `FemaleText_loc1`='꿈결 맥주가 한 잔 더 필요해요, 사부님.', `FemaleText_loc4`='我还需要一瓶洄梦仙酒，大师。', `FemaleText_loc5`='我需要另一份夢幻之釀，大師。', `FemaleText_loc7`='Necesito otro brebaje de ensueño, maestro.' WHERE `ID`=54944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내 양이!', `MaleText_loc4`='不！我的羊！', `MaleText_loc5`='不!我的羊!', `MaleText_loc7`='¡No! ¡Mi oveja!' WHERE `ID`=54945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이, 이놈들아! 내 양 돌려줘!', `MaleText_loc4`='嘿！把我的羊还给我！', `MaleText_loc5`='喂...喂!還給我!', `MaleText_loc7`='¡Eh, eh! ¡Devuélvemela!' WHERE `ID`=54946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런...', `MaleText_loc4`='哦，不……', `MaleText_loc5`='喔不...', `MaleText_loc7`='Oh, no...' WHERE `ID`=54947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해, 어린 양들아!', `MaleText_loc4`='对不起，小羊！', `MaleText_loc5`='對不起，小羊!', `MaleText_loc7`='¡Lo siento, ovejita!' WHERE `ID`=54948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 저, 저리 가! 내 양들을 돌려줘!', `MaleText_loc4`='滚……滚开！把我的羊还给我！', `MaleText_loc5`='走、走、走開!還我的羊來!', `MaleText_loc7`='¡La... lárgate! ¡Devuélveme mi oveja!' WHERE `ID`=54949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이, 이리 돌아와! 그 양은 내 거라고!', `MaleText_loc4`='回来！那是我的羊！', `MaleText_loc5`='回、回、回來!那是我的羊!', `MaleText_loc7`='¡Vu... vuelve aquí! ¡Esa oveja es mía!' WHERE `ID`=54950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어... 이건 아니야... 이건 아니야... 응?', `MaleText_loc4`='哦，天啊，糟糕……', `MaleText_loc5`='喔不，這真糟糕...', `MaleText_loc7`='Ay madre, qué horror...' WHERE `ID`=54951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프란시스! 이야기 좀 하지!', `MaleText_loc4`='弗二郎！我们得谈谈！', `MaleText_loc5`='法蘭西斯!我們得談談!', `MaleText_loc7`='¡Francis! ¡Tenemos que hablar!' WHERE `ID`=54952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 일을 다 끝내면 저와 다시 만납시다. 저는 저쪽 길에 있는 작은 농가에 삽니다.', `MaleText_loc4`='完成了就来找我，$n。我就住在路那头的小农舍里。', `MaleText_loc5`='完成後過來找我，$n。我住在路底的一間小農舍裡。', `MaleText_loc7`='Ven a verme cuando hayas terminado, $n. Vivo en una pequeña granja siguiendo la carretera.' WHERE `ID`=54953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 사부님께서 오시네요...', `MaleText_loc4`='啊哦……师父来了……', `MaleText_loc5`='呃喔...大師來了...', `MaleText_loc7`='Oh-oh... aquí llega el maestro...' WHERE `ID`=54954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s|1이;가; |c0087CEFA|Hspell:105845|h[핵폭발]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s正在施放|c0087CEFA|Hspell:105845|h[核能冲击]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s開始施放|c0087CEFA|Hspell:105845|h[核子爆破]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_gizmo_supersappercharge.blp:20|t¡%s lanza |c0087CEFA|Hspell:105845|h[Explosión nuclear]|h|r!' WHERE `ID`=54955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웨이, 이들은 당신 친구요?', `MaleText_loc4`='魏，这些是你的朋友吗？', `MaleText_loc5`='魏，這些是你的朋友嗎?', `MaleText_loc7`='Wei, ¿estos son amigos tuyos?' WHERE `ID`=54956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주홍빛 보루는 이곳 황혼의 고원에서 우리 붉은용군단의 작전 기지입니다.$B$B우리는 이 고지대에서 그림 바톨 공격을 지휘하고, 저 아래쪽의 계곡에서 더러운 놈들을 몰아내는 작전도 진행하죠.', `MaleText_loc4`='朱红庇护所是我们在暮光高地上的行动基地。$B$B我们可以从这个制高点监督对格瑞姆巴托的进攻，以及对下方河谷的清扫行动。', `MaleText_loc5`='朱紅壁壘是我們在暮光高地的指揮中心。$B$B在這個制高點，我們可以監督對格瑞姆巴托的攻擊，以及下面河谷的掃蕩進度。', `MaleText_loc7`='El Reducto Bermellón es nuestra base de operaciones en las Tierras Altas Crepusculares.$B$BDesde esta posición privilegiada podemos supervisar el ataque contra Grim Batol y la limpieza del valle fluvial de más abajo.' WHERE `ID`=54957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r|1이여;여;! 코라스트라자를 찾으신다면 안쪽으로 들어가 보십시오.$B$B<불편한 듯 자세를 바꾸는 모스트라즈>$B$B그녀의 기분이 지금 썩 좋지는 않단 걸 알아두시고요.', `MaleText_loc4`='你好，$r！如果你是在找科拉丝塔萨，那她就在里面。$B$B<莫奥斯塔兹不安地挪动了一下身体。>$B$B她的心情可不太好。', `MaleText_loc5`='你好啊，$r!如果你在找寇菈史卓莎，她就在裡面。$B$B<莫爾斯塔茲不自在地變換著身體的重心。>$B$B她現在的心情不怎麼好。', `MaleText_loc7`='¡Saludos, $r! Si buscas a Corastrasza, está dentro.$B$B<Mostrasz cambia de postura incómodo.>$B$BNo está de muy buen humor.' WHERE `ID`=54958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 암호를 결국 해독해 냈군요. 이 일을 끝까지 파헤쳐 봅시다.$B$B날아갈 준비는 되셨습니까?', `MaleText_loc4`='$n！你破译了密信，干得好。让我们弄清事情的真相吧。$B$B你做好飞行的准备了吗？', `MaleText_loc5`='$n!解碼訊息做得不錯。我們繼續追查下去吧。$B$B準備好要飛了嗎?', `MaleText_loc7`='¡$n! Hiciste un buen trabajo al descodificar el mensaje. Veamos qué se esconde detrás de este asunto.$B$B¿$gListo:Lista; para volar?' WHERE `ID`=54959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다! 라벤홀트 장원으로 갑시다.', `MaleText_loc4`='我准备好了！我们去拉文霍德吧。', `MaleText_loc5`='我好了!我們去拉文霍德吧!', `MaleText_loc7`='¡Estoy listo! Vamos a Ravenholdt.', `FemaleText_loc1`='준비됐어요! 라벤홀트 장원으로 가지요.', `FemaleText_loc4`='我准备好了！我们去拉文霍德吧。', `FemaleText_loc5`='我好了!我們去拉文霍德吧!', `FemaleText_loc7`='¡Estoy lista! Vamos a Ravenholdt.' WHERE `ID`=54960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 그 일을 해내다니 미, 믿을 수가 없어요! 하늘 높이에서 목숨을 잃을 수도 있었는데 말이에요! 독수리와 전투하는 법과 그 날개를 이용해서 안전하게 착지하는 방법까지... 정말 놀라웠어요!$b$b당신이 이런 일을 할 수 있다면... 그렇다면 저도 작은 늑대와 초원매들 쯤은 상대할 수 있어요! 새로운 제가 돼서 첫출발을 해야겠어요.$b$b이게 다 $n 님 덕분이에요.', `MaleText_loc4`='我……我真不敢相信，你居然做到了！你可能会死在那里啊！你与那只鹰打成一团，还利用它的双翼成功着陆……太不可思议了！$b$b既然你能做到这一切，那么……那么我也可以对付那些微不足道的狼和平原鹰！对我弗二郎来说，这是个崭新的开始。$b$b这一切都要感谢你，$n。', `MaleText_loc5`='我、我不敢相信你那樣做了!你可能會死在那裡的!像你那樣和老鷹角力，然後用牠的翅膀安全降落...那真是太厲害了!$b$b如果你能做到這種事，那...那我一定能料理那些可惡的狼和平原隼!這是全新法蘭西斯的誕生。$b$b這都多虧了你，$n。', `MaleText_loc7`='¡No... no me puedo creer que hayas hecho eso! ¡Podías haber muerto ahí arriba! La manera en que has luchado contra esa águila, y cómo has utilizado sus alas para aterrizar... ¡ha sido impresionante!$b$bSi tú puedes hacer algo así, entonces... ¡entonces yo puedo encargarme de unos míseros lobos y halcones de la llanura! Este es el nacimiento del nuevo Francis.$b$bY todo te lo debo a ti, $n.' WHERE `ID`=54961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님... 스승님께서 제가 그분께 아들과도 같은 존재라고 말씀하셨나요?', `MaleText_loc4`='他……他刚才是说我就像他的儿子一样吗？', `MaleText_loc5`='他...他剛剛是不是說了我就像他的兒子?', `MaleText_loc7`='¿Acaba... acaba de decir que yo era como un hijo para él?' WHERE `ID`=54962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 당신은 제가 알고 있는 그 무엇과도 다르게 생겼군요!', `MaleText_loc4`='哇，我从没见过你这样的东西！', `MaleText_loc5`='哇，你和我以前看過的東西都不一樣!', `MaleText_loc7`='¡No te pareces a nada que haya visto antes!' WHERE `ID`=54963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 정말 무서워 보이는데요! 형은 당신이 우리 편이라고 하던데, 정말 다행이에요.', `MaleText_loc4`='你看起来真吓人！幸好我哥哥说你很友好。', `MaleText_loc5`='你看起來真可怕!幸好我兄弟說你很友善。', `MaleText_loc7`='¡Das mucho miedo! Menos mal que mi hermano me ha dicho que eres buena persona.' WHERE `ID`=54964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 형을 구해주셨나요? 멍청하게 호젠에게 붙잡히다니... 당신을 만난 게 정말 다행입니다.', `MaleText_loc4`='你真把我兄弟救出来了？那个白痴居然成了猢狲的俘虏，幸好他遇见了你。', `MaleText_loc5`='你真的救了我的兄弟?那個呆瓜被猴人抓走了。遇見你是他的運氣。', `MaleText_loc7`='¿De verdad has salvado a mi hermano? Ese idiota se dejó capturar por los hozen. Tiene suerte de haberte encontrado.' WHERE `ID`=54965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 옷을 껴입고 어떻게 수영을 합니까?', `MaleText_loc4`='你穿的这么多，要怎么游泳啊？', `MaleText_loc5`='你穿那麼多衣服是怎麼游泳的?', `MaleText_loc7`='¿Cómo puedes nadar con tanta ropa?' WHERE `ID`=54966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(후오가 다시 활활 타오르면서 말이 아닌 방식으로 감사를 표현하는, 멋진 완료 이벤트)', `MaleText_loc4`='(Awesome completion event here where Huo gets re-ignited and flares up, then expresses appretiation in some non text-based form)', `MaleText_loc5`='(這裡要放進超棒的完成事件，霍重新開始燃燒，然後使用某種非文字的方式來表達感謝 。)', `MaleText_loc7`='(Awesome completion event here where Huo gets re-ignited and flares up, then expresses appretiation in some non text-based form)' WHERE `ID`=54967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(사원의 화로가 다시 타오르면서 성과를 인정받는, 멋진 완료 이벤트)', `MaleText_loc4`='(Fancy completion event where temple braziers are re-ignited and the accomplishments are recognized)', `MaleText_loc5`='(寺廟火盆重新點燃並取得成就時的精采完成事件。)', `MaleText_loc7`='(Fancy completion event where temple braziers are re-ignited and the accomplishments are recognized)' WHERE `ID`=54968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 슈마의 |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r를 소환합니다!', `MaleText_loc4`='%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[绿色]|h|r，以及|cFF0080FF|Hspell:104900|h[蓝色]|h|r舒玛之血！', `MaleText_loc5`='%s召喚了|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[綠色]|h|r，以及|cFF0080FF|Hspell:104900|h[藍色]|h|r鬚瑪之血!', `MaleText_loc7`='¡%s invoca la Sangre de Shu''ma |cFF9932CD|Hspell:104896|h[morada]|h|r, |cFF088A08|Hspell:104898|h[verde]|h|r y |cFF0080FF|Hspell:104900|h[azul]|h|r!' WHERE `ID`=54969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 됐군. 설리와 나는 정찰 임무를 떠나겠네.', `MaleText_loc4`='是时候了，$n。苏利和我要去侦察岛屿的内陆地区了。', `MaleText_loc5`='時候到了。我和蘇利要出發，調查島嶼的內部。', `MaleText_loc7`='Es la hora. Sully y yo vamos a explorar el interior de la isla.' WHERE `ID`=54971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님의 흔적이 있다면 찾아낼 것이네.', `MaleText_loc4`='只要他留下了线索，我们就能找到。', `MaleText_loc5`='如果有安杜因的蹤跡，我們會找到的。', `MaleText_loc7`='Si hay algún rastro de Anduin, lo encontraremos.' WHERE `ID`=54972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 안전하게 보호하겠소. 최대한 빨리 돌아오지.', `MaleText_loc4`='我发誓会保护他的安全。我们会尽快赶回来。', `MaleText_loc5`='我發誓會保護他的安全。我們會盡快回來。', `MaleText_loc7`='Juro que lo protegeré. Volveremos en cuanto podamos.' WHERE `ID`=54973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 여기서 테일러 제독을 보살펴 주게.', `MaleText_loc4`='$n，你留下，帮助泰勒恢复。', `MaleText_loc5`='$n，留在這裡幫助泰勒恢復。', `MaleText_loc7`='$n, quédate aquí y ayuda a Taylor a recuperarse.' WHERE `ID`=54975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위와 친구가 되게. 이 임무를 위해서는 그들의 도움이 필요하네. 이건 명령이야.', `MaleText_loc4`='去和锦鱼人交个朋友吧。在完成任务之前，我们或许需要他们的帮助，这是命令。', `MaleText_loc5`='和錦魚人交個朋友。在任務完成前，我們或許會需要他們的幫忙。這是命令。', `MaleText_loc7`='Traba amistad con los jinyu; es posible que nos hagan falta en esta misión. Es una orden.' WHERE `ID`=54976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려! 우리가 아직... 친구는 아니지만, 너희끼리만 위험한 곳에 들어가게 할 수는 없겠지.', `MaleText_loc4`='等等！虽然我们还不算朋友，可你也不能独自一人进入不熟悉的区域。', `MaleText_loc5`='等等!雖然我們不是朋友，但我也不能讓你獨自進入陌生的區域。', `MaleText_loc7`='¡Espera! Aunque no seamos amigos, no deberían aventurarse solos por territorio desconocido.' WHERE `ID`=54977;
