UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동생을 안전하게 데려와 다오. 어리지만 영리한 아이다. 길을 잘 알려줄 것이다.', `MaleText_loc4`='请把他安全地带回来。他还年轻，但很聪明。他能为你们带路。', `MaleText_loc5`='請安全帶他回來。他還年輕，但很聰明。他能替你帶路。', `MaleText_loc7`='Devuélvanmelo sano y salvo. Es joven, pero muy listo. Les ayudará a encontrar lo que buscan.' WHERE `ID`=54981;
