UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 나보고... 가라고?', `MaleText_loc4`='你想让……我来？', `MaleText_loc5`='嗯，你要...我?', `MaleText_loc7`='¿Quieres que yo...?' WHERE `ID`=54985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렐이 작은 목소리로 귓속말을 합니다.', `MaleText_loc4`='利尔压低了声音，窃窃私语着。', `MaleText_loc5`='瑞爾把聲音壓低。', `MaleText_loc7`='Rell baja la voz.' WHERE `ID`=54986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 시체는 반쯤 물어뜯기고 심하게 불에 탔습니다.>$B$B<붉은용군단이 아제로스에 거하는 모든 생명의 수호자이긴 하나, 자신들에게 도전하는 이를 용납하지는 않는 게 분명합니다.>', `MaleText_loc4`='<这具尸体被烧得面目全非，而且被咬成了两截。>$B$B<红龙军团或许是艾泽拉斯所有生命的守护者，但他们显然也不是好惹的。>', `MaleText_loc5`='<這具屍體被火燒得很慘，而且幾乎被咬成兩半。>$B$B<紅龍軍團雖然是全艾澤拉斯的守護者，但顯然還是不要激怒他們的好。>', `MaleText_loc7`='<El cuerpo está abrasado y prácticamente partido en dos.>$B$B<Tal vez el Vuelo Rojo sea el guardián de toda vida en Azeroth, pero está claro que es preferible no enfadarlo.>' WHERE `ID`=54987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 밀림으로 사라진 후, 구출된 병사들이 포우돈 마을에 돌아오기 시작했네. 그래서 여기까지 자네를 찾아오기가 어렵지 않았지.', `MaleText_loc4`='就在你进入丛林之后，得救的士兵就开始陆续返回坡东村。跟着你找到这里并不困难。', `MaleText_loc5`='在你消失在叢林中不久後，獲救的士兵陸續回到坡東與我們會合。跟著你的蹤跡來到這裡不算困難。', `MaleText_loc7`='Poco después de que te fueras, los soldados rescatados empezaron a volver a Zarpa''don. No ha sido difícil seguirte la pista.' WHERE `ID`=54988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 테일러 제독을 구출했다고? 진위의 말이 사실인가 보군...', `MaleText_loc4`='就是你救了海军上将泰勒？看来那些锦鱼人说的是真话……', `MaleText_loc5`='就是你拯救了泰勒上將?所以錦魚人說的是實話...', `MaleText_loc7`='¿Tú rescataste al almirante Taylor? Así que los jinyu decían la verdad...' WHERE `ID`=54989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(소 수레가 우고우를 굴리려고 하지만 밧줄이 끊어지고 우고우는 더 크게 코를 골며 깨어나지 않는 완료 이벤트)', `MaleText_loc4`='(Completion event where Ox cart tries to roll Wugou over, ropes snap, Wugou snores loudly and doesn''t wake)', `MaleText_loc5`='（完成事件:牛車試著翻滾烏果，繩子斷裂，烏果繼續打鼾沒有醒來。）', `MaleText_loc7`='(Completion event where Ox cart tries to roll Wugou over, ropes snap, Wugou snores loudly and doesn''t wake)' WHERE `ID`=54990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1은;는; 큰 소리로 코를 골며 계속 잠을 잡니다.', `MaleText_loc4`='%s大声喷着鼻息，睡得更香了。', `MaleText_loc5`='%s大聲地打呼，繼續睡著。', `MaleText_loc7`='%s lanza un fuerte resoplido y sigue durmiendo.' WHERE `ID`=54991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(슈가 우고우에게 커다란 물 덩어리를 던지고, 우고우가 깨어나서 슈를 쫓아다니는 이벤트)', `MaleText_loc4`='(Event where Shu splashes Wugou with a giant ball of water, Wugou wakes, then starts chasing Shu around town)', `MaleText_loc5`='（事件:舒把一顆大水球砸到烏果頭上，烏果醒過來，開始滿鎮追著舒跑。）', `MaleText_loc7`='(Event where Shu splashes Wugou with a giant ball of water, Wugou wakes, then starts chasing Shu around town)' WHERE `ID`=54992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 숲에 평생 있었던 것만 같아요. 빨리 가요! 저 계곡을 탐험해 보자고요!', `FemaleText_loc4`='再这么磨蹭，我们哪儿都不用去了！走啦！我们得到谷中去探险！', `FemaleText_loc5`='感覺就像在那座森林裡待了兩萬年。快走啦!我們還得探索山谷!', `FemaleText_loc7`='Siento que llevamos una eternidad en ese bosque. ¡Vamos! ¡Tenemos que explorar el valle!' WHERE `ID`=54993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르지 말거라. 삼촌은 칼림도어도 이렇게 여행했단다. 한 번에 한 군데씩 머물며 말이지.', `MaleText_loc4`='别那么急，丽丽。我就是这么游历卡利姆多的：一次一站。', `MaleText_loc5`='不要催嘛，莉莉。我以前就是這樣探索卡林多的:一站一站來。', `MaleText_loc7`='No tengas prisa, Li Li. Así atravesé Kalimdor, tomándome mi tiempo para descansar.' WHERE `ID`=54994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까 오래 걸렸죠. 그렇게 엉덩이가 무거워서 무슨 탐험을 하겠어요.', `FemaleText_loc4`='难怪你花了这么长时间。你一直坐着的话，什么收获也不会有。', `FemaleText_loc5`='怪不得花了你那麼久時間。屁股黏在地板上可探索不了任何東西。', `FemaleText_loc7`='Así no me extraña que tardaras tanto. Resulta difícil explorar sin levantarse del asiento.' WHERE `ID`=54995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌이 여길 왜 그렇게 좋아하는지 알 것 같네요.', `FemaleText_loc4`='陈叔，我知道你为什么喜欢这儿了。', `FemaleText_loc5`='老陳，我覺得我知道你為什麼這麼喜歡這裡了。', `FemaleText_loc7`='Chen, creo que sé por qué te gusta tanto estar aquí.' WHERE `ID`=54996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜지, 리 리?', `MaleText_loc4`='为什么呢，丽丽？', `MaleText_loc5`='為什麼，莉莉?', `MaleText_loc7`='¿Y por qué es, Li Li?' WHERE `ID`=54997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 두 판다렌 때문에 삼촌이 날씬해 보여서죠?', `FemaleText_loc4`='因为那两个家伙让你感觉自己很苗条。', `FemaleText_loc5`='因為那兩個傢伙讓你覺得自己很瘦。', `FemaleText_loc7`='Porque esos dos de ahí hacen que te sientas delgado.' WHERE `ID`=54998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 왜 날씬해 보이고 싶겠니? 덩치가 곧 힘인데.', `MaleText_loc4`='我为什么想要苗条呢？体格等于力量。', `MaleText_loc5`='我幹嘛要覺得很瘦?體型就是力量。', `MaleText_loc7`='¿Y por qué querría yo sentirme delgado? Los kilos me dan fuerza.' WHERE `ID`=54999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있는 샤오를 보려무나. 두둑한 아랫배의 중요성을 잘 알고 있잖니.', `MaleText_loc4`='听到那边晓怎么说了么。他就意识到了大肚子的价值。', `MaleText_loc5`='看看這位曉先生，他就知道大肚子的價值。', `MaleText_loc7`='Mira a Xiao. Él conoce el valor de una gran barriga.' WHERE `ID`=55000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(샹이 셴진 수의 상태와, 셴진 수와 대화하는 방법에 대해서 이야기하고, 지팡이를 꽂은 다음 죽는 이벤트)', `MaleText_loc4`='(Event where Shang speaks of Shen-zin Su and how you''re going to talk to him, then plants his staff and passes on)', `MaleText_loc5`='（事件:尚羲大師向你講述神真子和與他談話的方法，然後插下他的手杖撒手塵寰。）', `MaleText_loc7`='(Event where Shang speaks of Shen-zin Su and how you''re going to talk to him, then plants his staff and passes on)' WHERE `ID`=55001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 오신 것이 요 며칠 사이에 유일한 좋은 일입니다. 도와주셔서 정말 감사합니다.', `FemaleText_loc4`='遇见你是我们这几天来唯一走运的事。很高兴能得到你的帮助。', `FemaleText_loc5`='你是我們幾天來唯一的好運。我們很高興接受你的幫助。', `FemaleText_loc7`='Eres lo único positivo que nos ha pasado en varios días. Nos alegra contar contigo.' WHERE `ID`=55002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 가시죠.', `MaleText_loc4`='很好。让我们继续。', `MaleText_loc5`='很好。我們出發吧。', `MaleText_loc7`='Muy bien. Vamos allá.' WHERE `ID`=55003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아버지? 그분과 이야기하는 게 무슨 소용이 있나?', `MaleText_loc4`='我父亲？干嘛要提起他？', `MaleText_loc5`='我父親?和他說話有什麼好處?', `MaleText_loc7`='¿Mi padre? ¿De qué sirve hablar con él?' WHERE `ID`=55004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 우리 물품을 약탈하고 우리 전사를 죽이는 동안 아버지가 뭘 했지? 아무것도 안 했네!', `MaleText_loc4`='当猢狲掠夺我们的物资，杀害我们的战士时，他做了什么？什么都没有！', `MaleText_loc5`='當猴人掠奪我們的物資、殺死我們戰士的時候，他做了什麼?什麼也沒有!', `MaleText_loc7`='Mientras los hozen saquean nuestros suministros y matan a nuestros guerreros, ¿qué hace él? ¡Nada!' WHERE `ID`=55005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분은 아무것도 하지 않은 채 족장의 의자에 앉아 있네. 평화라는 꿈으로 자신이 겁쟁이라는 진실을 가린 채!', `MaleText_loc4`='他慵懒地坐在酋长宝座上，奢望用和平的美梦掩饰他的懦弱！', `MaleText_loc5`='他呆呆坐在他的族長椅子上，企圖用和平的幻夢遮掩他的懦弱!', `MaleText_loc7`='¡Se queda sentado en su trono de jefe y se contenta con enmascarar su cobardía con sueños de paz!' WHERE `ID`=55006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 평화를 이해하지 못해! 우리가 마지막 한 명까지 사라질 때까지 마을 주민 모두를 학살할 거야!', `MaleText_loc4`='猢狲根本不懂和平！他们会将我们村里的人都杀光的！', `MaleText_loc5`='猴人不了解什麼叫和平!他們會血洗這個村莊，直到我們全都死淨!', `MaleText_loc7`='Los hozen no entienden de paz. ¡Masacrarán a nuestro pueblo hasta que no quedemos ninguno!' WHERE `ID`=55007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미... 미안하군. 이렇게 폭발할 생각은 없었네, $n. 아버지와 나는 생각이 많이 다르네.', `MaleText_loc4`='我……我很抱歉刚才发了火，$n。我和我父亲在很多事情上都意见相左。', `MaleText_loc5`='我...我為我的失控感到抱歉，$n。我和父親有很多地方意見不一致。', `MaleText_loc7`='S... Siento mi arrebato, $n. Mi padre y yo no estamos de acuerdo en muchas cosas.' WHERE `ID`=55008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 목숨을 구해준 자네에게 정말 큰 빚을 졌네. 물론 장로님과 만나게 해주겠네.', `MaleText_loc4`='你救了我的命，我欠你一份天大的人情。我一定会帮你见到长老的。', `MaleText_loc5`='你救了我的命，我欠你很大的情。我當然會幫助你面見長者。', `MaleText_loc7`='Estoy en gran deuda contigo por haberme salvado la vida. Claro que te ayudaré a conseguir una audiencia con el ancestro.' WHERE `ID`=55009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복실이 밥 줄 시간이야.', `MaleText_loc4`='该给那些毛毛们喂食了。', `MaleText_loc5`='毛毛怪吃飯時間。', `MaleText_loc7`='Hora de manduka para pelakos.' WHERE `ID`=55010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나 찾았다!', `MaleText_loc4`='找到一个！', `MaleText_loc5`='找到一個!', `MaleText_loc7`='¡Encuentra uno!' WHERE `ID`=55011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝반짝!', `MaleText_loc4`='太棒了！', `MaleText_loc5`='閃亮亮!', `MaleText_loc7`='¡Brilla!' WHERE `ID`=55012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='히이! 히히!', `MaleText_loc4`='嘿嘿！', `MaleText_loc5`='嘻嘻!', `MaleText_loc7`='¡Je je!' WHERE `ID`=55013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡았다!', `MaleText_loc4`='接到了！', `MaleText_loc5`='接住!', `MaleText_loc7`='¡Pilla!' WHERE `ID`=55014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휘이이!', `MaleText_loc4`='哇！', `MaleText_loc5`='嘻咿!', `MaleText_loc7`='¡Ueee!' WHERE `ID`=55015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패스! 받아!', `MaleText_loc4`='接着！', `MaleText_loc5`='空中接力!', `MaleText_loc7`='¡Alehop!' WHERE `ID`=55016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='받았지!', `MaleText_loc4`='接住了！', `MaleText_loc5`='接到了!', `MaleText_loc7`='¡Lo tengo!' WHERE `ID`=55017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이얏!', `MaleText_loc4`='耶！', `MaleText_loc5`='耶!!', `MaleText_loc7`='¡Bien!' WHERE `ID`=55018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냠냠!', `MaleText_loc4`='嚼呀嚼！', `MaleText_loc5`='嚼嚼嚼嚼!', `MaleText_loc7`='¡Ñam ñam!' WHERE `ID`=55020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오! 패니 양이 오는군요!', `MaleText_loc4`='快看！范妮小姐正好来了！', `MaleText_loc5`='看哪!范妮小姐來了!', `MaleText_loc7`='¡Mira! ¡Aquí viene la señorita Fanny!' WHERE `ID`=55021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤쪽 정원에서 건방진 꼬맹이 소리가 들린 거 같은데. 가서 한번 찾아보자고.', `FemaleText_loc4`='我好像听到花园里有小孩子在捣乱。我们去找找看吧。', `FemaleText_loc5`='我想我聽見某個小討打的跑到我後邊的園子裡了。讓我們去找找他吧。', `FemaleText_loc7`='Me parece haber oído a algún joven insolente en el jardín. Vamos a buscarlo.' WHERE `ID`=55022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105863|h[과다출혈]|h|r을 일으킵니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s开始|cFFFF0000|Hspell:105863|h[出血]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s開始施放 |cFFFF0000|Hspell:105863|h[出血]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_moltenblood.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:105863|h[Hemorragia]|h|r!' WHERE `ID`=55023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 호젠을 상대로 승리하지는 못할 거라고 생각한다.', `MaleText_loc4`='我怀疑我们永远也战胜不了猢狲了。', `MaleText_loc5`='我很懷疑我們有能打敗猴人的一天。', `MaleText_loc7`='No creo que jamás venzamos a los hozen.' WHERE `ID`=55024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보라. 물이 생명을 길러내는 모습을.$B$B우리는 이 축복에 감사하며, 우리 동족들과 함께함을 기뻐하고 있다.', `MaleText_loc4`='看看四周，清澈的流水就是生命之源。$B$B我们对这上天的恩赐深表感激，也为我们的人民欢欣鼓舞。', `MaleText_loc5`='環顧你四周。看看水如何帶來生命。$B$B我們對我們受到的祝福感恩，我們的人民歡欣鼓舞。', `MaleText_loc7`='Mira a tu alrededor. Contempla la vida que otorga el agua.$b$bAgradecemos nuestras bendiciones y apreciamos nuestro pueblo.' WHERE `ID`=55025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에서 방문객을 환영한 것도 벌써 오래 전 일이다.', `MaleText_loc4`='我们村已经很久没有欢迎过外来的访客了。', `MaleText_loc5`='我們村子已經很久沒有迎接旅客的到來了。', `MaleText_loc7`='Hace muchos años que no recibíamos visitantes en nuestra aldea.' WHERE `ID`=55026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 젊었을 때, 호젠과의 이 전쟁을 끝내는 것을 꿈꿨지. 이 나이가 되고 보니, 내가 죽기 전에 과연 그런 날을 볼 수 있을지 걱정이 되는군.', `MaleText_loc4`='在我年轻时，曾梦想能结束这场与猢狲的战争。可现在，我感觉自己恐怕无法活着看到那一天了。', `MaleText_loc5`='曾經，當我還年輕的時候，我夢想結束這場和猴人之間的戰爭。現在，我害怕在我有生之年看不到這樣的情景。', `MaleText_loc7`='Una vez, cuando era joven, soñé con poner fin a la guerra contra los hozen. Ahora temo que no viviré para ver ese día.' WHERE `ID`=55027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신보다 계급이 높은 진위에게 말을 거는 것은 무례한 행동입니다.', `MaleText_loc4`='和比自己地位高的锦鱼人搭讪是粗鲁的行为。', `MaleText_loc5`='和比你高階的錦魚人說話是無禮的。', `MaleText_loc7`='Es de mala educación hablar con jinyu de un rango superior al tuyo.' WHERE `ID`=55028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 존경을 받는 이만 장로님과 대화할 수 있습니다.', `MaleText_loc4`='只有最为尊贵的客人，才能与长老说话。', `MaleText_loc5`='只有最受尊重者能和長者說話。', `MaleText_loc7`='Solo aquellos de más alta estima pueden hablar con el ancestro.' WHERE `ID`=55029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님은 다른 문제 때문에 매우 바쁘십니다. 다음에 다시 찾아오십시오.', `MaleText_loc4`='长老正在处理要务。请改天再来吧。', `MaleText_loc5`='長者正為了重要的事務非常忙碌。請下次再來。', `MaleText_loc7`='El ancestro está muy ocupado con asuntos importantes. Vuelve en otro momento.' WHERE `ID`=55030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식에 사용할 물품을 가져왔습니다.', `MaleText_loc4`='我带来了仪式所需的物品。', `MaleText_loc5`='我帶來儀式需要的東西了。', `MaleText_loc7`='He traído los objetos para la ceremonia.', `FemaleText_loc1`='의식에 사용할 물품을 가져왔어요.', `FemaleText_loc4`='我带来了仪式所需的物品。', `FemaleText_loc5`='我帶來儀式需要的東西了。', `FemaleText_loc7`='He traído los objetos para la ceremonia.' WHERE `ID`=55031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 네 앞에 거대한 어둠이 도사리고 있구나.', `MaleText_loc4`='兄弟，我看到你的前路潜伏着巨大的黑暗。', `MaleText_loc5`='兄弟，我看到你的前方潛伏著黑暗。', `MaleText_loc7`='Hermano, veo una oscuridad que se cierne sobre ustedes.' WHERE `ID`=55032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사방 어디를 둘러봐도, 강이 말라 있다.', `MaleText_loc4`='我目光所及，河流纷纷干涸。', `MaleText_loc5`='我目光所及之處，河流都已乾涸。', `MaleText_loc7`='Allá donde miro, los ríos están secos.' WHERE `ID`=55033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 아직 하나의 강이, 이 고난의 시간에서 널 구해줄 하나의 길이 남아 있다.', `MaleText_loc4`='但仍然有一条出路，一条河流，能带你们走出这艰难的时代。', `MaleText_loc5`='但仍有一條出路，一條河流，可以帶你走出這艱困的情勢。', `MaleText_loc7`='Pero aún hay una senda, un río, que puede salvarlos de estos tiempos difíciles.' WHERE `ID`=55034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강인한 이방인들이 바다를 건너 온다. 그들의 힘을 구하고, 우리의 힘에 더하라.', `MaleText_loc4`='强大的陌生人渡海而来。让他们加入我们，从而寻求他们的力量。', `MaleText_loc5`='強大的陌生人渡海而來。尋求他們的力量。讓他們加入我們。', `MaleText_loc7`='Llegan poderosos seres del otro lado del mar. Busquen su fuerza. Recíbanlos.' WHERE `ID`=55035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러지 못하면, 앞날에 짙은 어둠이 드리울 것이다...', `MaleText_loc4`='否则，未来的日子将被强大的阴影所笼罩……', `MaleText_loc5`='否則，巨大的黑暗會在以後的日子裡逐漸成形...', `MaleText_loc7`='Si no, una gran oscuridad se cierne sobre el futuro...' WHERE `ID`=55036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지 않은 미래에 끔찍한 어둠이 도사리고 있는 것이 보이는군.', `MaleText_loc4`='我看见，未来充斥着巨大的黑暗。', `MaleText_loc5`='我看見強大的黑暗在未來的日子裡逐漸成形。', `MaleText_loc7`='Veo una gran oscuridad que se cierne sobre el futuro.' WHERE `ID`=55037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 진위는 패배의 두려움에 떨지 않는다. 그리고 단지 승리를 위해 싸우지도 않는다.', `MaleText_loc4`='我们锦鱼人并不畏惧战斗。但我们也不仅是为胜利而战。', `MaleText_loc5`='我們錦魚人不會因害怕失敗而蜷縮，但也不光為了勝利而作戰。', `MaleText_loc7`='Los jinyu no conocemos el miedo ni la derrota, pero tampoco luchamos solo por probar la victoria.' WHERE `ID`=55038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 우리가 지키고자 하는 가치를 믿기 때문에 싸운다.', `MaleText_loc4`='我们是为自己的信念而战。', `MaleText_loc5`='我們戰鬥，是因為我們相信自己戰鬥的理由。', `MaleText_loc7`='Luchamos porque creemos en lo que hacemos.' WHERE `ID`=55039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 결정해야 한다, 젊은 루. 무엇을 위해 싸우려 하느냐?', `MaleText_loc4`='你必须明白，小卢。什么才值得我们为之而战？', `MaleText_loc5`='你必須決定，年輕的盧。值得為之戰鬥的是什麼?', `MaleText_loc7`='Debes tomar una decisión, joven Lu. ¿Por qué merece la pena luchar?' WHERE `ID`=55040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 위해 죽으려 하느냐?', `MaleText_loc4`='什么才值得我们为之牺牲？', `MaleText_loc5`='值得為之獻身的是什麼?', `MaleText_loc7`='¿Por qué merece la pena morir?' WHERE `ID`=55041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아이들이 우리보다는 더 나은 삶을 살 수 있게 하려고 싸웁니다!', `MaleText_loc4`='我们是为了让孩子们过上比我们更好的生活而战！', `MaleText_loc5`='我們戰鬥是為了後代子孫能過上更好的生活!', `MaleText_loc7`='¡Luchamos para que nuestros hijos lleven una vida mejor que la nuestra!' WHERE `ID`=55042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조상들의 희생이 헛된 것이 아니었기에 싸웁니다!', `MaleText_loc4`='我们是为了不让先祖们白白牺牲而战！', `MaleText_loc5`='我們戰鬥是為了讓我們祖先的犧牲不會白費!', `MaleText_loc7`='¡Luchamos para que los sacrificios de nuestros antepasados no hayan sido en vano!' WHERE `ID`=55043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 가지 이유가 있겠지. 하지만 네가 무엇을 위해 싸울 것인지 결정해야 한다.', `MaleText_loc4`='说一千道一万，你还是要做出决定，究竟什么才值得我们为之而战。', `MaleText_loc5`='理由有千千萬萬種，但你必須決定哪一種值得你為之戰鬥。', `MaleText_loc7`='Hay miles de razones, pero tú debes decidir por qué quieres luchar.' WHERE `ID`=55044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 물의 영혼이여.', `MaleText_loc4`='来自远古的水灵。', `MaleText_loc5`='古老的水之靈。', `MaleText_loc7`='Antiguos espíritus del agua.' WHERE `ID`=55045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침묵 속 메아리를 들어 주십시오.', `MaleText_loc4`='请在深渊中聆听我的呼唤。', `MaleText_loc5`='透過靜寂深淵聆聽我的回音。', `MaleText_loc7`='Escuchen mi eco en el silencioso abismo.' WHERE `ID`=55046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심연의 물 속에서 깨어나십시오.', `MaleText_loc4`='从彼岸无边大水中苏醒。', `MaleText_loc5`='在偉大的彼岸水域中甦醒。', `MaleText_loc7`='Álcense desde las aguas del más allá.' WHERE `ID`=55047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어려움에 빠진 후손을 도와주십시오!', `MaleText_loc4`='在这危难的时刻帮助你的孩子们！', `MaleText_loc5`='在這非常時刻幫助你的子孫!', `MaleText_loc7`='¡Ayuden a sus hijos en esta época de necesidad!' WHERE `ID`=55048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 어둠이라고? 우리가 이 이방인들... 이 얼라이언스를... 믿어야 한다는 뜻인가?', `MaleText_loc4`='巨大的黑暗？他是否在告诫我们必须相信这些陌生人…这些…来自…联盟的人？', `MaleText_loc5`='強大的黑暗?難道他是說我們終究還是要相信這群陌生人...這些...聯盟?', `MaleText_loc7`='Una oscuridad... ¿Podría estar diciendo que debemos confiar en esos forasteros? ¿En... la Alianza?' WHERE `ID`=55049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 나도 지나친 의혹과 두려움에 휩싸여 있었던 모양이군.', `MaleText_loc4`='或许我是被自己的疑虑和恐惧蒙蔽了眼睛。', `MaleText_loc5`='也許我一直太沈溺於自己的懷疑和恐懼裡。', `MaleText_loc7`='Quizás haya estado demasiado cegado por mis propias dudas y miedos.' WHERE `ID`=55050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우리 부족을 위해 더 나은 지도자가 되어야 한다.', `MaleText_loc4`='我一定能成为更出色的部落领袖。', `MaleText_loc5`='我必須為了部族成為更好的領導人。', `MaleText_loc7`='Debo convertirme en un líder mejor para nuestra tribu.' WHERE `ID`=55051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조언해 줘서 고맙다. 이제 이 문제에 대해 깊이 명상해 보겠다.', `MaleText_loc4`='感谢您的告诫。我会认真思考这个问题的。', `MaleText_loc5`='謝謝你的忠告，我會深思的。', `MaleText_loc7`='Gracias por tu consejo. Meditaré sobre ello a fondo.' WHERE `ID`=55052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 물의 영혼이여!', `MaleText_loc4`='远古水灵！', `MaleText_loc5`='古老的水靈!', `MaleText_loc7`='¡Espíritus del agua antiguos!' WHERE `ID`=55053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어서 지상으로만 다니십시오. 문제가 생기면 여기로 순간이동시켜 드리죠.', `MaleText_loc4`='身子伏低，注意隐蔽。如果你遇到麻烦，我会立刻把你传送回来的！', `MaleText_loc5`='站穩，隱藏身形。如果你有麻煩，我會把你傳回這裡!', `MaleText_loc7`='Quédate escondido en tierra. ¡Te teletransportaré aquí si te metes en problemas!' WHERE `ID`=55054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끈고기가 이겼어.', `MaleText_loc4`='光板儿赢了。', `MaleText_loc5`='滑魚贏了。', `MaleText_loc7`='Mandukos ganan.' WHERE `ID`=55055;
