UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b<패니 양이 순무를 얼마나 세게 쳐내면 좋겠습니까?>', `MaleText_loc4`='|TInterface\\Icons\\INV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b<你想让范妮小姐怎么处理芜菁？>', `MaleText_loc5`='|TInterface\\Icons\\INV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b<你想要范妮小姐對菜頭做什麼?>', `MaleText_loc7`='|TInterfaceIconsINV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b<¿Qué te gustaría que la señorita Fanny le hiciera a la naba?>' WHERE `ID`=55057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\INV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<패니 양이 수박을 얼마나 세게 쳐내면 좋겠습니까?>', `MaleText_loc4`='|TInterface\\Icons\\INV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<你想让范妮小姐怎么处理西瓜？>', `MaleText_loc5`='|TInterface\\Icons\\INV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<你想要范妮小姐對西瓜做什麼?>', `MaleText_loc7`='|TInterfaceIconsINV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<¿Qué te gustaría que la señorita Fanny le hiciera a la sandía?>' WHERE `ID`=55058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_guild_cauldron_b.blp:64:64:100:0|t$b$b<패니 양이 불두부를 얼마나 세게 쳐내면 좋겠습니까?>', `MaleText_loc4`='|TInterface\\Icons\\inv_guild_cauldron_b.blp:64:64:100:0|t$b$b<你想让范妮小姐怎么处理特辣豆腐？>', `MaleText_loc5`='|TInterface\\Icons\\inv_guild_cauldron_b.blp:64:64:100:0|t$b$b<你想要范妮小姐對特辣豆腐做什麼?>', `MaleText_loc7`='|TInterfaceIconsinv_guild_cauldron_b.blp:64:64:100:0|t$b$b<¿Qué te gustaría que la señorita Fanny le hiciera al tofu hiperpicante?>' WHERE `ID`=55059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 패니 양. 너무 세게 쳤나 본데.', `MaleText_loc4`='哇哦，范妮小姐。也许太难了。', `MaleText_loc5`='哇喔，范妮小姐。也許那是太難了。', `MaleText_loc7`='Hala, señorita Fanny. Igual tú ha pasado un poco.' WHERE `ID`=55060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패니 양, 더 세게 칠 수 있잖아! 다음번에는 힘을 더 실어 봐!', `MaleText_loc4`='范妮小姐，你可以的！再试一次吧，多用点力气！', `MaleText_loc5`='范妮小姐，妳的力量不只這樣!下次試著多用一點力氣!', `MaleText_loc7`='¡Señorita Fanny, tú más fuerte que eso! ¡Un poco más de machuka la próxima vez!' WHERE `ID`=55061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패니 양. 진정하라고. 수박을 너무 세게 쳤잖아... 다 부서졌네!', `MaleText_loc4`='放轻松，范妮小姐。你敲的太重了……西瓜都被你敲烂了！', `MaleText_loc5`='放輕鬆，范妮小姐。妳打西瓜打得太大力了...它們全爆開了!', `MaleText_loc7`='Trankila, señorita Fanny. Tú golpea sandías muy fuerte... ¡hacen bum!' WHERE `ID`=55062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하하하! 언덕 반만큼도 못 갔잖아!', `MaleText_loc4`='啊哈哈哈哈！都还没下到半山腰呢！', `MaleText_loc5`='啊哈哈哈哈!它甚至沒下到山丘的一半!', `MaleText_loc7`='¡Jaaaa ja ja ja ja! ¡Apenas pasó esta colina!' WHERE `ID`=55063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 잘 쳤어! 패니 양!', `MaleText_loc4`='哇啊。打得好啊，范妮小姐！', `MaleText_loc5`='哇喔。射得好，范妮小姐!', `MaleText_loc7`='¡Hala! ¡Buen lanzamiento, señorita Fanny!' WHERE `ID`=55064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 때렸는데, 패니 양! 제구력이 아주 좋아!', `MaleText_loc4`='打得好，范妮小姐！你控制得很好！', `MaleText_loc5`='好一記重擊呀，范妮小姐!妳控制得很好!', `MaleText_loc7`='¡Buen tiro, señorita Fanny! ¡Tú kontrola muy bien!' WHERE `ID`=55065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 패니 양! 아주 세게 때렸어!', `MaleText_loc4`='不错，范妮小姐！你打得很重！', `MaleText_loc5`='很好，范妮小姐!妳的攻擊夠威猛!', `MaleText_loc7`='¡Genial, señorita Fanny! ¡Tú ha golpeado fuerte!' WHERE `ID`=55066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 뭐하는 거야? 그러다 죽는다고!', `MaleText_loc4`='嘿，$g先生:小姐;，你在干嘛？你这是去送死！', `MaleText_loc5`='嘿，$g先生:女士;，你在做什麼?你會害死自己的!', `MaleText_loc7`='¡Eh, $gseñor:señora;, ¿tú ké está haciendo? ¡Tú va a matarse!' WHERE `ID`=55067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<패니 양이 당신의 눈을 똑바로 바라보며 조용히 고개를 반대쪽으로 돌립니다. 패니 양이... 패니 양이 당신을 날려버리고 싶은 걸까요?>$b$b<당신이 패니 양의 의도를 올바로 알아차렸다면, 얼마나 세게 당신을 쳐낼 수 있는지 알아볼까요?', `MaleText_loc4`='<范妮小姐看着你的眼睛，微妙地侧了侧头。她……她是想把你打出去吗？>$b$b<假如你没猜错，那范妮小姐又会用多大的力气呢？>', `MaleText_loc5`='<范妮小姐看著你的眼睛，微妙地轉過頭。難道...難道她想要把你發射出去?>$b$b<假設你的解讀是正確的，范妮小姐該用多大的力道來拍你呢?>', `MaleText_loc7`='<La señorita Fanny te mira a la cara y gira la cabeza sutilmente. ¿Acaso... acaso quiere lanzarte a ti?>$b$b<Suponiendo que has interpretado correctamente sus intenciones, ¿con qué fuerza te golpearía la señorita Fanny?>' WHERE `ID`=55068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다!', `MaleText_loc4`='在这边！', `MaleText_loc5`='我在這裡!', `MaleText_loc7`='¡Eh! ¡Aquí!' WHERE `ID`=55069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가도 돼요? 맥주 다 드셨어요?', `FemaleText_loc4`='能走了吧？啤酒喝完了吗？', `FemaleText_loc5`='我們可以走了嗎?你啤酒喝夠了沒?', `FemaleText_loc7`='¿Podemos irnos ya? ¿Terminaste la cerveza?' WHERE `ID`=55070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직.', `MaleText_loc4`='差不多。', `MaleText_loc5`='快了。', `MaleText_loc7`='Casi.' WHERE `ID`=55071;
