UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌! 어서요! 뭘 꾸물거리는 거예요?', `FemaleText_loc4`='走吧，陈叔！我们还等什么呢？', `FemaleText_loc5`='來吧，老陳叔叔!我們到底在等什麼啊?', `FemaleText_loc7`='¡Vamos, tío Chen! ¿Qué estamos esperando?' WHERE `ID`=55073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라, 리 리. 판다리아를 탐험할 시간은 차고 넘친단다. 느긋하게 여행을 즐기렴.', `MaleText_loc4`='别着急，丽丽。我们有大把的时间来探索潘达利亚。花点时间来享受这个旅程吧。', `MaleText_loc5`='放輕鬆，莉莉。我們還有很多時間可以探索潘達利亞。放慢步調享受這趟旅程吧。', `MaleText_loc7`='Tranquila, Li Li. Tenemos todo el tiempo del mundo para explorar Pandaria. Relájate y disfruta del viaje.' WHERE `ID`=55074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어딜 가야 여행을 즐기든 말든 할 거 아니에요!', `FemaleText_loc4`='我是想“享受”旅程，可那也得先“出发”才行！', `FemaleText_loc5`='如果我們真的有要「去」哪，我應該會更「享受」這趟旅程!', `FemaleText_loc7`='¡Disfrutaría más del viaje si de verdad estuviéramos yendo a alguna parte!' WHERE `ID`=55075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구분들과 함께 여기 머무신다면 환영입니다. 마음껏 머물다 가십시오.', `MaleText_loc4`='欢迎你和你的朋友们来做客，想呆多久都可以。', `MaleText_loc5`='只要你願意，歡迎你和你所有朋友留在這裡。', `MaleText_loc7`='Tú y tus amigos son bienvenidos a quedarse aquí todo el tiempo que quieran.' WHERE `ID`=55076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역의 농장이 모두 당신 소유입니까?', `MaleText_loc4`='这些农田都是你的吗？', `MaleText_loc5`='所有農地都屬於你的嗎?', `MaleText_loc7`='¿Todos estos campos son tuyos?', `FemaleText_loc1`='이 지역의 농장이 모두 당신 소유인가요?', `FemaleText_loc4`='这些农田都是你的吗？', `FemaleText_loc5`='所有農地都屬於你的嗎?', `FemaleText_loc7`='¿Todos estos campos son tuyos?' WHERE `ID`=55077;
