UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께 적당한 제물이로군.', `MaleText_loc4`='你将成为献给我主的尊贵祭品。', `MaleText_loc5`='是給我主人的上好祭品。', `MaleText_loc7`='Un sacrificio digno de nuestro maestro.' WHERE `ID`=55085;
