UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산 자는 이곳에 오지 못한다!', `MaleText_loc4`='这里不欢迎生者！', `MaleText_loc5`='生者在這裡不受歡迎!', `MaleText_loc7`='¡Los vivos no son bienvenidos!' WHERE `ID`=55090;
