UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무! 넌 이제 끝장이야!', `MaleText_loc4`='你的死期到了，芜菁！', `MaleText_loc5`='死吧，菜頭!', `MaleText_loc7`='¡Ha llegado tu hora, naba!' WHERE `ID`=55092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무를 공격해!', `MaleText_loc4`='攻击芜菁！', `MaleText_loc5`='攻擊菜頭!', `MaleText_loc7`='¡Atacad a las nabas!' WHERE `ID`=55093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무는 다 없애버려!', `MaleText_loc4`='消灭所有的芜菁！', `MaleText_loc5`='殺死所有菜頭!', `MaleText_loc7`='¡Acaben con todas las nabas!' WHERE `ID`=55094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 순무 없앤다! 그리고 그걸 키우는 판다렌도 없애버린다!', `MaleText_loc4`='首先我们要消灭芜菁！接着消灭种植这些芜菁的熊猫人！', `MaleText_loc5`='首先我們殺死菜頭!然後我們殺死種菜頭的熊貓人!', `MaleText_loc7`='¡Primero acabamos con las nabas! ¡Luego matamos a los pandaren que las cultivan!' WHERE `ID`=55095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무라면 모조리 없애버린다!', `MaleText_loc4`='我们要把所有的芜菁都消灭掉，一个都不剩！', `MaleText_loc5`='我們要殺死每一棵菜頭!', `MaleText_loc7`='¡Tenemos que matar a cada una de las nabas!' WHERE `ID`=55096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무! 넌 왜 그렇게 나쁜 거야?', `MaleText_loc4`='芜菁！你怎么这么坏？', `MaleText_loc5`='菜頭!你為什麼這麼壞?', `MaleText_loc7`='¡Nabas! ¿Por qué sois tan malas?' WHERE `ID`=55097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무는 벌을 받아야 해!', `MaleText_loc4`='芜菁必须受到惩罚！', `MaleText_loc5`='菜頭必須死!', `MaleText_loc7`='¡Las nabas deben ser castigadas!' WHERE `ID`=55098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 이 끔찍한 순무를 키운 대가를 치러라!', `MaleText_loc4`='熊猫人将为种植这些恶心的芜菁而付出代价！', `MaleText_loc5`='熊貓人會為種噁心的菜頭付出代價!', `MaleText_loc7`='¡Los pandaren nos las pagarán por haber cultivado asquerosas nabas!' WHERE `ID`=55099;
