UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이여, 안식을 누리세요.', `MaleText_loc4`='安息吧，灵魂。', `MaleText_loc5`='安息吧，靈魂。', `MaleText_loc7`='Ve en paz, espíritu.' WHERE `ID`=55103;
