UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 배가 이기고 있어!', `MaleText_loc4`='我的船就要赢了！', `MaleText_loc5`='我的船要贏了!', `MaleText_loc7`='¡Mi bote va ganando!' WHERE `ID`=55105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이... 돌아온다...', `MaleText_loc4`='光明……回来了……', `MaleText_loc5`='曙光...又出現了...', `MaleText_loc7`='La luz... vuelve...' WHERE `ID`=55106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 함선이 갇힌 것 같아.', `MaleText_loc4`='我想我的船被卡住了。', `MaleText_loc5`='我想我的船卡住了。', `MaleText_loc7`='Creo que mi bote está atascado.' WHERE `ID`=55107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수박 배는 띄우기가 정말 쉬워.', `MaleText_loc4`='西瓜船很容易浮起来。', `MaleText_loc5`='西瓜船很容易浮起來。', `MaleText_loc7`='Los botes de sandía flotan con mucha facilidad.' WHERE `ID`=55108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 잘 사용하시오. 비할 데 없이 소중한 것이니...', `MaleText_loc4`='好好利用这水。它们是无价之宝。', `MaleText_loc5`='好好利用這些水。他們是無價之寶...', `MaleText_loc7`='Haz buen uso de las aguas. Su valor es incalculable...' WHERE `ID`=55109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 이방인...', `MaleText_loc4`='谢谢你，陌生人……', `MaleText_loc5`='謝謝你，陌生人...', `MaleText_loc7`='Gracias, $gforastero:forastera;...' WHERE `ID`=55110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 배가 얼마나 천천히 가는지 봐봐.', `MaleText_loc4`='看看你的船走得多慢啊。', `MaleText_loc5`='看看你的船跑得多慢。', `MaleText_loc7`='Mira lo lento que va tu bote.' WHERE `ID`=55111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 사라졌다... 타락이 걷혔다.', `MaleText_loc4`='阴影消失了……腐蚀得到了净化。', `MaleText_loc5`='黑影離開了...腐化被消除了。', `MaleText_loc7`='Las sombras se disipan... la corrupción desaparece.' WHERE `ID`=55112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 있다가 수박을 더 훔쳐와야겠는데.', `MaleText_loc4`='很快就可以再偷些西瓜了。', `MaleText_loc5`='很快就可以偷更多西瓜了。', `MaleText_loc7`='Va siendo hora de robar más sandías.' WHERE `ID`=55113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 물을 보호한다. 탐욕으로부터, 어둠으로부터.', `MaleText_loc4`='我们守护着这水，让它远离贪婪与黑暗。', `MaleText_loc5`='我們保護這些水。保護它遠離貪婪，遠離黑暗。', `MaleText_loc7`='Protegeremos el agua. De la codicia y de la oscuridad.' WHERE `ID`=55114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 배가 더 필요하겠는걸.', `MaleText_loc4`='我们很快就会用到更多的船只了。', `MaleText_loc5`='很快我們就需要更多的船。', `MaleText_loc7`='Pronto vamos a necesitar más botes.' WHERE `ID`=55115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잎을 떼어내면 배가 더 빨리 움직일 거야.', `MaleText_loc4`='把叶子摘掉，船会行驶得更快。', `MaleText_loc5`='如果拿掉葉子，船會跑得更快。', `MaleText_loc7`='Los botes van más rápidos si les quitas las hojas.' WHERE `ID`=55116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이겨라! 이겨라!', `MaleText_loc4`='快快快！', `MaleText_loc5`='衝衝衝!', `MaleText_loc7`='¡Vamos, vamos, vamos!' WHERE `ID`=55117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 신성한 물을 휘젓다니! 익사시켜주마!', `MaleText_loc4`='你们竟敢扰乱这水流？淹死你们！', `MaleText_loc5`='你膽敢打擾這片水域?你會淹死在這裡!', `MaleText_loc7`='¿Osan perturbar estas aguas? ¡Se ahogarán!' WHERE `ID`=55118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훠이!', `FemaleText_loc4`='嘘！', `FemaleText_loc5`='呿!', `FemaleText_loc7`='¡Fuera!' WHERE `ID`=55121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저리 가! 쥐새끼들아!', `FemaleText_loc4`='滚开，土拨鼠！', `FemaleText_loc5`='滾開，土撥鼠!', `FemaleText_loc7`='¡Largo de aquí, marmotas!' WHERE `ID`=55122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 농작물에서 떨어져!', `FemaleText_loc4`='离我们的庄稼远点！', `FemaleText_loc5`='別碰我的作物!', `FemaleText_loc7`='¡Fuera de mis cultivos!' WHERE `ID`=55123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉭, 쉭!', `FemaleText_loc4`='嘘，嘘！', `FemaleText_loc5`='呿、呿!', `FemaleText_loc7`='¡Fuera, fuera!' WHERE `ID`=55124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 흰색 초원매를 처치하십시오!', `MaleText_loc4`='打败巨型白色平原鹰！', `MaleText_loc5`='擊敗大白平原隼!', `MaleText_loc7`='¡Derrota al gran halcón de la llanura blanco!' WHERE `ID`=55125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만나는군, $n! 샹을 찾나? 멜론을 손질하느라 뒤뜰에 있는 것 같던데.', `MaleText_loc4`='$n，我们又见面了！你是来找尚的吗？我想他在后面，正在擦他的瓜。', `MaleText_loc5`='$n，我們又見面了!你在找尚嗎?我想他人在後面幫他的甜瓜擦亮拋光。', `MaleText_loc7`='¡$n, volvemos a vernos las caras! ¿Buscas a Shang? Creo que ha ido atrás para darle brillo a su sandía.' WHERE `ID`=55126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내! 어둠의 손아귀에서 풀려났다! 빛이여! 축복받은, 아름다운 빛이여!', `MaleText_loc4`='终于逃出黑暗的魔爪了！光！神圣而又美丽的光啊！', `MaleText_loc5`='終於!從黑暗的掌握中解脫。光!聖潔的、美麗的光!', `MaleText_loc7`='¡Al fin! Libres de las garras de esa oscuridad. ¡La luz! ¡Qué bendita y maravillosa luz!' WHERE `ID`=55127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일천 년 전에 제가 이곳으로 물을 가져왔습니다. 진주지느러미 부족이 고대에 행한 일에 대한 보답이었지요.', `MaleText_loc4`='千次轮回之前，我将水带到了这里。那是一份送给珠鳍锦鱼人的礼物，源自一个古老的约定。', `MaleText_loc5`='千世之前，我把水帶到這裡。那是為了履行古老的契約而送給珠鰭村的禮物。', `MaleText_loc7`='Hace milenios, traje el agua hasta aquí. Fue un regalo para los Aleta de Nácar por sus antiguas hazañas.' WHERE `ID`=55128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 물을 지켰습니다. 너무 위험하고 너무 강력하기에, 그릇된 손에 들어가서는 안 되니까요.', `MaleText_loc4`='我们一直守护着这水。它是如此强大，一旦落入邪恶的手，后果将不堪设想。', `MaleText_loc5`='我們是水的守衛。它太危險、太強大，不能落入錯誤的人手中。', `MaleText_loc7`='Protegimos las aguas. Son demasiado peligrosas, demasiado poderosas, como para dejar que caigan en malas manos.' WHERE `ID`=55129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때 어둠이 나타났습니다. 땅에서부터 스며나왔지요. 천천히, 어둠은 우릴 오염시키고, 우릴 질식시켰습니다!', `MaleText_loc4`='然后，黑暗降临了。它从地下渗出，逐渐侵蚀了我们……吞噬了我们！', `MaleText_loc5`='而後黑暗降臨，滲入地面，慢慢地感染了我們...讓我們窒息!', `MaleText_loc7`='Entonces vino la oscuridad. Se filtraba desde el suelo. Poco a poco, nos infectó... ¡nos asfixió!' WHERE `ID`=55130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 필멸의 육신이 모두 썩어 문드러진 후, 어둠은 우리 영혼에서 희망을 빨아들였습니다. 끝이 없었어요!', `MaleText_loc4`='即使我们的肉身腐朽成灰，它依然能从我们的灵魂中汲取希望之力。这折磨无穷无尽！', `MaleText_loc5`='就算我們的肉身早已朽壞，它仍然從我們的靈魂中吸走希望。永無休止!', `MaleText_loc7`='Incluso después de que nuestra carne mortal se descompusiera, absorbió la esperanza de nuestras almas. ¡Era interminable!' WHERE `ID`=55131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각만 해도 몸서리쳐지는군요. 고대의 악. 판다리아의 적. 그 이름을 이야기하지 않겠습니다.', `MaleText_loc4`='这念头令我不寒而栗。一群远古的邪魔。一群潘达利亚的宿敌。我无法说出他们的名字。', `MaleText_loc5`='我甚至不敢想起這種古老的邪惡，潘達利亞的敵人。我不會說出他們的名字。', `MaleText_loc7`='Me estremezco de solo pensarlo. Un mal antiguo. Un enemigo de Pandaria. No mencionaré su nombre.' WHERE `ID`=55132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에겐 무슨 일이 있었죠?', `MaleText_loc4`='你怎么了，大师？', `MaleText_loc5`='你怎麼了，大師?', `MaleText_loc7`='¿Qué te pasó, maestro?' WHERE `ID`=55133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 타락시킨 어둠은 뭐였죠?', `MaleText_loc4`='那腐蚀你的黑暗到底是什么？', `MaleText_loc5`='那片腐蝕你的黑暗是什麼?', `MaleText_loc7`='¿Qué era esa oscuridad?' WHERE `ID`=55134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 영혼이 그 시에 대해서 알지도 몰라요. 정화할게요!', `MaleText_loc4`='也许这个灵魂知道那首诗歌。净化吧，灵魂！', `MaleText_loc5`='也許這個靈魂會知道這首詩。淨化吧，靈魂!', `MaleText_loc7`='A lo mejor este sabe algo sobre el poema. ¡Recibe la purificación!' WHERE `ID`=55135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 아무래도 우리는 또다시 만날 운명이었던 것 같군. 다른 곳도 많은데 돼지 사육장에서 이렇게 만나다니 말일세.$b$b나는 이 네 바람의 계곡에서 즐겁게 지내고 있다네. 마치 거의... 고향 같은 느낌이 드는군. 푸른 잔디밭과 넓은 하늘... 게다가 이 길로 쭉 가면 거대한 양조장이 있다는 말도 들었다네. 이제 궁둥이를 붙이고 정착해야 할 때가 됐나 싶네.$b$b<약간 오랜 시간 동안 멀리 쳐다보다 어깨를 으쓱이는 첸>$b$b뭐, 아닐 수도 있겠군.', `MaleText_loc4`='看来我们的命运再次交叉了，$n，而且还是在这个大养猪场里。$b$b我喜欢这个山谷。它感觉就像……家一样。绿色的田野，广阔的天空……我甚至还听说路的那头有个大的酿酒厂。我也许是时候安定下来，不再漂泊了。$b$b<陈向远方凝视了几秒钟，然后耸耸肩。>$b$b或者不会。', `MaleText_loc5`='$n，看來我們的人生道路再次交集。走過千山萬水，竟是在一個養豬農舍相遇。$b$b我很喜歡這個山谷，這裡幾乎就像是...家一樣。翠綠的田野，廣闊的天空...我甚至聽說沿著路走下去，有一座大酒坊在那裡。也許我定下來的時候到了，永遠的安定下來。$b$b<老陳凝望著遙遠的彼方，停頓了好幾秒鐘，然後聳聳肩。>$b$b也或者還不是時候。', `MaleText_loc7`='Parece que nuestros caminos vuelven a encontrarse, $n. En una granja de cerdos, nada menos.$b$bMe gusta mucho este valle. Me siento casi como... en casa. Los verdes campos, el cielo azul... He oído que hay una gran cervecería siguiendo esta carretera. Quizá haya llegado el momento de asentarme definitivamente.$b$b<Chen mira al infinito durante unos segundos y luego se encoge de hombros.>$b$bO quizá no.' WHERE `ID`=55136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한바탕 제대로 놀아볼 시간이군! 모두 대비해라. 용 사냥할 시간이다.', `MaleText_loc4`='是时候大干一场了。所有人进入船舱：我们要去杀的是一条龙。', `MaleText_loc5`='派對可以開始了。全體各就各位，有隻龍等著我們去殺呢。', `MaleText_loc7`='El reloj dice que es la hora del rock and roll. Todos a la bodega: tenemos un dragón que matar.' WHERE `ID`=55137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=55138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크... 큰 신세를 졌소.', `MaleText_loc4`='我……我欠你一份情。', `MaleText_loc5`='我...我欠你一次。', `MaleText_loc7`='Estoy en deuda contigo.', `FemaleText_loc1`='크... 큰 신세를 졌소.', `FemaleText_loc4`='我……我欠你一份情。', `FemaleText_loc5`='我...我欠你一次。', `FemaleText_loc7`='Estoy en deuda contigo.' WHERE `ID`=55139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지를 막지 않으면 셴진 수가 죽을지도 몰라요! 같이 가요! 당장!!!', `FemaleText_loc4`='如果我们任由季这么干的话，他可能会害死神真子的！$p，跟我来，快！', `FemaleText_loc5`='如果我們放任他這樣做，紀有可能會把神真子給害死!跟我來，$p，快!', `FemaleText_loc7`='¡Ji podría matar a Shen-zin Su si no se lo impedimos! ¡Ven conmigo, rápido!' WHERE `ID`=55140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악... 내게서 떨어져, 이 미친... 거미 녀석아!', `MaleText_loc4`='哇……别过来，疯子……蜘蛛！', `MaleText_loc5`='哇喔...離我遠一點，好可怕的...蜘蛛!', `MaleText_loc7`='¡Ah! Aléjate de mí... araña... ¡cosa!', `FemaleText_loc1`='으악... 내게서 떨어져, 이 미친... 거미 녀석아!', `FemaleText_loc4`='哇……别过来，疯子……蜘蛛！', `FemaleText_loc5`='哇喔...離我遠一點，好可怕的...蜘蛛!', `FemaleText_loc7`='¡Ah! Aléjate de mí... araña... ¡cosa!' WHERE `ID`=55141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 이쪽으로 온다!', `MaleText_loc4`='啊！它朝我冲过来了！', `MaleText_loc5`='啊!!它來追我了!', `MaleText_loc7`='¡Ah! ¡Viene a por mí!', `FemaleText_loc1`='으악! 이쪽으로 오네!', `FemaleText_loc4`='啊！它朝我冲过来了！', `FemaleText_loc5`='啊!!它來追我了!', `FemaleText_loc7`='¡Ah! ¡Viene a por mí!' WHERE `ID`=55142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 하필 거미야?!', `MaleText_loc4`='为什么总是蜘蛛呢？！', `MaleText_loc5`='為什麼偏偏要是蜘蛛?!', `MaleText_loc7`='¿Por qué tenían que ser arañas?', `FemaleText_loc1`='왜 하필 거미람?!', `FemaleText_loc4`='为什么总是蜘蛛呢？！', `FemaleText_loc5`='為什麼偏偏要是蜘蛛?!', `FemaleText_loc7`='¿Por qué tenían que ser arañas?' WHERE `ID`=55143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악, 누가 이것들 좀 쫓아줘!', `MaleText_loc4`='啊，把这些东西弄走！', `MaleText_loc5`='啊啊，把這些東西從我身上弄走!', `MaleText_loc7`='Aaah, ¡quítame estas cosas de encima!', `FemaleText_loc1`='아아악, 누가 이것들 좀 쫓아줘요!', `FemaleText_loc4`='啊，把这些东西弄走！', `FemaleText_loc5`='啊啊，把這些東西從我身上弄走!', `FemaleText_loc7`='Aaah, ¡quítame estas cosas de encima!' WHERE `ID`=55144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 날 먹어치우지 마!', `MaleText_loc4`='不要！我不想被咬死！', `MaleText_loc5`='不要!我不要被啃掉!', `MaleText_loc7`='¡No! ¡No quiero que me mordisqueen!', `FemaleText_loc1`='안 돼! 날 먹어치우면 안 돼!', `FemaleText_loc4`='不要！我不想被咬死！', `FemaleText_loc5`='不要!我不要被啃掉!', `FemaleText_loc7`='¡No! ¡No quiero que me mordisqueen!' WHERE `ID`=55145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으르릉... 한 발짝만 더 다가오면, 네 다리를 물어뜯어 버릴 테다!', `MaleText_loc4`='呃……靠近点儿，小崽子。我要把你的腿咬下来！', `MaleText_loc5`='嘎吼吼...再靠近點啊，爬蟲。我會把你的腿都咬下來!', `MaleText_loc7`='Grr... Acércate más, alimaña. ¡Te voy a arrancar las patas a mordiscos!', `FemaleText_loc1`='으르릉... 한 발짝만 더 다가오면, 다리를 물어뜯어 버릴 거야!', `FemaleText_loc4`='呃……靠近点儿，小崽子。我要把你的腿咬下来！', `FemaleText_loc5`='嘎吼吼...再靠近點啊，爬蟲。我會把你的腿都咬下來!', `FemaleText_loc7`='Grr... Acércate más, alimaña. ¡Te voy a arrancar las patas a mordiscos!' WHERE `ID`=55146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 쫓으려고 숨을 훅훅 내뿜습니다.', `MaleText_loc4`='%s张牙舞爪的，试图吓唬$n。', `MaleText_loc5`='%s噴著氣恫嚇著，試圖對$n發動攻擊。', `MaleText_loc7`='%s bufa, intentando apuntar hacia $n.', `FemaleText_loc1`='%s|1이;가; $n|1을;를; 쫓으려고 숨을 훅훅 내뿜습니다.', `FemaleText_loc4`='%s张牙舞爪的，试图吓唬$n。', `FemaleText_loc5`='%s噴著氣恫嚇著，試圖對$n發動攻擊。', `FemaleText_loc7`='%s bufa, intentando apuntar hacia $n.' WHERE `ID`=55147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 애써 $n|1을;를; 외면하려 합니다.', `MaleText_loc4`='%s极力转过脸去，不看$n。', `MaleText_loc5`='%s掙扎著把臉從$n的方向轉開。', `MaleText_loc7`='%s se esfuerza por apartar la cara de $n.', `FemaleText_loc1`='%s|1이;가; 애써 $n|1을;를; 외면하려 합니다.', `FemaleText_loc4`='%s极力转过脸去，不看$n。', `FemaleText_loc5`='%s掙扎著把臉從$n的方向轉開。', `FemaleText_loc7`='%s se esfuerza por apartar la cara de $n.' WHERE `ID`=55148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳은 지금껏 본 적이 없습니다. $n 님, 혹시 전에 이런 곳에 와보신 적이 있나요?', `MaleText_loc4`='我没见过这样的地方。你呢，$n？', `MaleText_loc5`='我從沒見過像這樣的地方。你有嗎，$n?', `MaleText_loc7`='Nunca había visto un sitio así. ¿Y tú, $n?' WHERE `ID`=55149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 고대의 지식에 정통하더군요. 지금 리나가 제게 이 지역의 약초를 사용하여 상처를 치료하는 법을 가르쳐 주고 있었어요.', `MaleText_loc4`='熊猫人掌握着许多古老的知识。林娜教会了我怎么使用当地的草药治病。', `MaleText_loc5`='熊貓人懂得許多古老的知識，琳娜已經教導我當地植物的醫療用法。', `MaleText_loc7`='Los pandaren rebosan de conocimientos antiguos. Lina me ha estado enseñando las propiedades medicinales de las hierbas del lugar.' WHERE `ID`=55150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 어디서 왔다고 생각하십니까? 왜 이토록 오랫동안 숨어 있었을까요?', `MaleText_loc4`='你觉得这些熊猫人是从哪儿冒出来了？他们怎么会与世隔绝了那么久呢？', `MaleText_loc5`='你覺得熊貓人是打哪來的?為什麼他們躲藏了這麼久?', `MaleText_loc7`='¿De dónde crees que vienen los pandaren? ¿Por qué llevan ocultos tanto tiempo?' WHERE `ID`=55151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는, 런도 제게 그의 가족이 사는 마을을 보여줄 것입니다.', `MaleText_loc4`='总有一天，任会带我去看他家所在的村子的。', `MaleText_loc5`='有一天，阿仁會讓我看看他家族的村子。', `MaleText_loc7`='Algún día Ren me enseñará la aldea de su familia.' WHERE `ID`=55152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지는 어떠신가요? 너무 걱정하지 않으셨으면 좋겠는데. 아버지는 걱정이 너무 많으세요.', `MaleText_loc4`='我父亲怎么样了？但愿他不要太担心了。他已经为我操碎了心。', `MaleText_loc5`='我父親狀況如何?希望他不會太擔心。他過於擔心我了。', `MaleText_loc7`='¿Qué tal está mi padre? Espero que no esté muy preocupado. Se preocupa demasiado por mí.' WHERE `ID`=55153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지 생각과는 달리, 저도 제 몸은 지킬 수 있습니다.', `MaleText_loc4`='我父亲可不这么想，但我会照顾好自己的。', `MaleText_loc5`='我父親不這樣覺得，但我確實能照顧好自己。', `MaleText_loc7`='Mi padre cree que no, pero sé cuidar de mí mismo.' WHERE `ID`=55154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 집에 가고 싶지 않아요. 보고 배워야 할 게 많이 남았거든요.', `MaleText_loc4`='我还不太想回家。还有那么多东西等着我去见识、学习呢。', `MaleText_loc5`='我還不想要回家，還有很多事值得看跟學習。', `MaleText_loc7`='Todavía no quiero irme a casa. Aún queda mucho por ver y aprender.' WHERE `ID`=55155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 집에 돌아가실 시간입니다, 안두인 왕자님.', `MaleText_loc4`='该回家了，安度因王子。', `MaleText_loc5`='回家的時候到了，安杜因王子。', `MaleText_loc7`='Es hora de volver a casa, príncipe Anduin.', `FemaleText_loc1`='이제 집에 돌아가실 시간이에요, 안두인 왕자님.', `FemaleText_loc4`='该回家了，安度因王子。', `FemaleText_loc5`='回家的時候到了，安杜因王子。', `FemaleText_loc7`='Es hora de volver a casa, príncipe Anduin.' WHERE `ID`=55156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<런이 의식이 혼미한 채 거칠게 뒤척입니다. 그의 이마는 고열로 매우 뜨겁습니다.>$B$B무... 물을...', `MaleText_loc4`='<任辗转反侧，额头发烫。>$B$B水……水……', `MaleText_loc5`='<阿仁神智不清地搖晃著，他的額頭因發燒而滾燙。>$B$B水...水...', `MaleText_loc7`='<Ren se zarandea entre delirios. Le arde la frente a causa de la fiebre.>$B$BA... agua...' WHERE `ID`=55157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안두인의 친구라면 우리 친구이기도 해요, $c님. 안두인이 없었다면 우리 아버진 무사하지 못하셨을 거예요.', `FemaleText_loc4`='安度因的朋友就是我们的朋友，$c。要不是他，我父亲也不可能站在这里。', `FemaleText_loc5`='安杜因的朋友就是我們的朋友，$c。少了他，我父親不會在這裡。', `FemaleText_loc7`='Los amigos de Anduin son nuestros amigos, $c. Mi padre no estaría con nosotros de no ser por él.' WHERE `ID`=55158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해요. 아직 돌아갈 순 없어요.', `MaleText_loc4`='我很抱歉，可我暂时还不能回去。', `MaleText_loc5`='我很抱歉，但是我還不能回去。', `MaleText_loc7`='Lo siento, pero todavía no puedo regresar.' WHERE `ID`=55159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 골짜기를 찾아보겠어요. 신성한 웅덩이가 지닌 치유의 힘에 대해 알아봐야 해요.', `MaleText_loc4`='我决心去寻找那座溪谷。我一定要找到圣池，并研究一下它们的治疗力量。', `MaleText_loc5`='我決定去搜尋這座山谷。我必須找到神聖之池，了解它的治療力量。', `MaleText_loc7`='He decidido ir a buscar el valle. Quiero encontrar las Pozas Sagradas y estudiar sus poderes curativos.' WHERE `ID`=55160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인 왕자님, 집에 가실 시간입니다.', `MaleText_loc4`='安度因王子，我们是来带你回家的。', `MaleText_loc5`='安杜因王子，我們是來送你回去的。', `MaleText_loc7`='Príncipe Anduin, hemos venido para llevarte a casa.' WHERE `ID`=55161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가시지요.', `MaleText_loc4`='悄悄跟着我，快。', `MaleText_loc5`='乖乖跟我們回去吧。', `MaleText_loc7`='Ven sin sin hacer ruido.' WHERE `ID`=55162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해요. 그럴 순 없어요. 이해해 주실 거라고 믿어요.', `MaleText_loc4`='我很抱歉，可我不能。我相信你明白我的苦衷。', `MaleText_loc5`='我很抱歉，但我不會跟你們走。你一定能了解我的苦衷。', `MaleText_loc7`='Lo siento, pero no puedo. Sé que comprenderán mis razones.' WHERE `ID`=55163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 어... 음... 그렇죠, 안두인 왕자님. 마음대로 가십시오.', `MaleText_loc4`='啊？噢……嗯……安度因王子，您说的完全正确。您可以去了。', `MaleText_loc5`='呃?喔...嗯...你說的很有道理，安杜因王子。想離開就請便吧。', `MaleText_loc7`='¿Eh? Oh... Tienes toda la razón, príncipe Anduin. Eres libre de marcharte si lo deseas.' WHERE `ID`=55164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 가시죠.', `MaleText_loc4`='来吧，我们走。', `MaleText_loc5`='來吧，我們走。', `MaleText_loc7`='Bueno, vámonos.' WHERE `ID`=55165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설리! 그냥 보내 드리면 어떡해?', `FemaleText_loc4`='苏利！你怎么就这样让他跑了？', `FemaleText_loc5`='蘇利!你怎麼就這樣讓他走了?', `FemaleText_loc7`='¡Sully! ¿Cómo pudiste dejarlo ir?' WHERE `ID`=55166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어? 어떻게 된 거야?', `MaleText_loc4`='嗯？出什么事了？', `MaleText_loc5`='呃?發生了什麼事?', `MaleText_loc7`='¿Cómo? ¿Qué paso?' WHERE `ID`=55167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 드워프, 넌 정신 지배에 당한 거야. 가 버렸잖아!', `FemaleText_loc4`='愚蠢的矮子，他用了精神控制！现在他跑了！', `FemaleText_loc5`='你這個傻矮人，你被他心控了!現在他跑掉啦!', `FemaleText_loc7`='¡Enano estúpido! Te engañó con control mental. ¡Y ahora se fue!' WHERE `ID`=55168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테일러 제독님께 잘 설명드려야 할 거야!', `FemaleText_loc4`='你还是想想怎么跟泰勒上将解释吧！', `FemaleText_loc5`='我希望你已做好向泰勒上將解釋的準備!', `FemaleText_loc7`='¡Prepárate para explicárselo al almirante Taylor!' WHERE `ID`=55169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐어어? 어떻게 그러실 수가 있어!', `MaleText_loc4`='什么？？难以置信，他怎么能这样！', `MaleText_loc5`='啥啊啊?我不敢相信他會對我做出這種事!', `MaleText_loc7`='¿Cómo? ¡No puedo creer que me haya hecho eso!' WHERE `ID`=55170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주를 깨뜨리려면 자신의 영혼을 찾아야 합니다!', `MaleText_loc4`='找到你的灵魂，打破诅咒！', `MaleText_loc5`='找到你的靈魂來破除詛咒!', `MaleText_loc7`='¡Encuentren su alma para romper la maldición!', `FemaleText_loc1`='저주를 깨뜨리려면 자신의 영혼을 찾아야 합니다!', `FemaleText_loc4`='找到你的灵魂，打破诅咒！', `FemaleText_loc5`='找到你的靈魂來破除詛咒!', `FemaleText_loc7`='¡Encuentren su alma para romper la maldición!' WHERE `ID`=55171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 생물들과 이성적인 대화를 할 수 있을 거라고 누가 생각이라도 했겠어요?', `FemaleText_loc4`='谁会想到这些怪物还能跟你讲道理呢？', `FemaleText_loc5`='誰想得到可以跟這種生物講道理?', `FemaleText_loc7`='¡Quién me iba a decir que se puede razonar con esas criaturas!' WHERE `ID`=55172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 당신에게 이 지역 정찰 임무를 맡기셨습니다, 쇼키아 님. 지금 즉시 출발하셔야 합니다.', `MaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，夏琪亚。你立刻就动身吧。', `MaleText_loc5`='納茲格寧姆派你去做區域偵查，修基雅。你得儘快出發。', `MaleText_loc7`='Nazgrim te ha asignado la exploración de la zona, Shokia. Partirás en breve.', `FemaleText_loc1`='나즈그림 장군님께서 당신에게 이 지역 정찰 임무를 맡기셨어요, 쇼키아 님. 지금 즉시 출발하셔야 해요.', `FemaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，夏琪亚。你立刻就动身吧。', `FemaleText_loc5`='納茲格寧姆派你去做區域偵查，修基雅。你得儘快出發。', `FemaleText_loc7`='Nazgrim te ha asignado la exploración de la zona, Shokia. Partirás en breve.' WHERE `ID`=55173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 준비할게요.$b$b이 야만스러운 종족과 잠시 떨어져 있는 것도 좋을 거예요.', `FemaleText_loc4`='我会做好准备的。$b$b能暂时摆脱这些野蛮人就再好不过了。', `FemaleText_loc5`='我會做好準備。$b$b能夠遠離這些蠻族一會兒也是不錯。', `FemaleText_loc7`='Me prepararé.$b$bEstará bien alejarme un rato de estos salvajes.' WHERE `ID`=55174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='익숙해질 시간이 조금 필요하겠네.$b$b난 당장이라도 이 생물의 털을 몽땅 뽑아버리고 싶은 충동을 애써 억누르고 있으니까 말이야.', `MaleText_loc4`='这还需要适应。$b$b我得努力忍住把这些家伙的脑袋揪下来的冲动。', `MaleText_loc5`='這得花些時間才能習慣。$b$b我很努力遏制把這種生物的腦袋扭下來的衝動。', `MaleText_loc7`='Tendré que acostumbrarme.$b$bSiento la necesidad de arrancarles la cabeza a esas criaturas.' WHERE `ID`=55175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 당신에게 이 지역 정찰을 도와줄 것을 명령하셨습니다. 즉시 출발하셔야 합니다.', `MaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，格罗克。你立刻就动身吧。', `MaleText_loc5`='納茲格寧姆派你去做區域偵查，哥羅克。你得儘快出發。', `MaleText_loc7`='Nazgrim ha ordenado que contribuyas a la exploración de la zona, Gorrok. Partirás en breve.', `FemaleText_loc1`='나즈그림 장군님께서 당신에게 이 지역 정찰을 도와줄 것을 명령하셨어요. 즉시 출발하셔야 해요.', `FemaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，格罗克。你立刻就动身吧。', `FemaleText_loc5`='納茲格寧姆派你去做區域偵查，哥羅克。你得儘快出發。', `FemaleText_loc7`='Nazgrim ha ordenado que contribuyas a la exploración de la zona, Gorrok. Partirás en breve.' WHERE `ID`=55176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아쉽군. 조금 더 쉬면 좋을 텐데.$b$b상관없네. 나즈그림 장군님께 내가 정찰대에 합류할 거라고 전해주게.', `MaleText_loc4`='真丢人。我得休息一会儿了。$b$b没关系，你去告诉纳兹戈林，我会跟上队伍的。', `MaleText_loc5`='真糟。我本來希望能稍微休息一下。$b$b沒關係，告訴納茲格寧姆我會隨隊出發。', `MaleText_loc7`='Qué pena. Un descanso no me vendría nada mal.$b$bNo importa. Dile a Nazgrim que acompañaré al grupo.' WHERE `ID`=55177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='있잖아요, 이 꼬마 친구들도 일단 친해지고 나니 그렇게 나쁘진 않네요.', `FemaleText_loc4`='你看，当你了解之后，就会发现这些小家伙也不是那么坏的……', `FemaleText_loc5`='你知道嗎，混熟了之後，這些小傢伙其實並不壞...', `FemaleText_loc7`='¿Sabes? Estos pequeñajos no están mal, cuando se les conoce...' WHERE `ID`=55178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님이 당신을 정찰대에 배치하셨습니다, 키린 님. 곧 출발하셔야 합니다.', `MaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，琪麟。你立刻就动身吧。', `MaleText_loc5`='納茲格寧姆派你去做區域偵查，卡玲。你得儘快出發。', `MaleText_loc7`='Nazgrim te ha asignado al grupo de exploración, Kiryn. Partirás en breve.', `FemaleText_loc1`='나즈그림 장군님이 당신을 정찰대에 배치하셨어요, 키린 님. 곧 출발하셔야 해요.', `FemaleText_loc4`='纳兹戈林已经指定由你去侦察这片区域，琪麟。你立刻就动身吧。', `FemaleText_loc5`='納茲格寧姆派你去做區域偵查，卡玲。你得儘快出發。', `FemaleText_loc7`='Nazgrim te ha asignado al grupo de exploración, Kiryn. Partirás en breve.' WHERE `ID`=55179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 물론 그러셨겠죠. 당연히 그러셨어야죠.$b$b고마워요, $r님. 즉시 출발 준비를 마칠게요.', `FemaleText_loc4`='当然了。他要不选我那才是笨呢。$b$b谢谢你，$r。我立刻就准备出发。', `FemaleText_loc5`='嘿他當然會了，除非他是個傻瓜$b$b謝謝你，$r。我會立刻準備動身。', `FemaleText_loc7`='Pues claro que me ha asignado. Sería de tontos no asignarme.$b$bGracias, $r. Daré comienzo a los preparativos inmediatamente.' WHERE `ID`=55180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다, 이방인.', `MaleText_loc4`='衷心感谢，陌生人。', `MaleText_loc5`='大恩大德，陌生人。', `MaleText_loc7`='Muchas gracias, $gforastero:forastera;.', `FemaleText_loc1`='정말 고마워요, 친구!', `FemaleText_loc4`='噢，谢啦，朋友！', `FemaleText_loc5`='喔，謝啦，朋友!', `FemaleText_loc7`='¡Muchas gracias, colega!' WHERE `ID`=55181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 두렵지 않았습니다... 아마도요...', `MaleText_loc4`='我可不想留下疤痕……', `MaleText_loc5`='我可沒有害怕...', `MaleText_loc7`='No tenía miedo...', `FemaleText_loc1`='아우, 훨씬 낫네요. 제 머리 어때요?', `FemaleText_loc4`='噢，这下好多了……我的发型没乱吧？', `FemaleText_loc5`='喔好多了...我的頭髮如何?', `FemaleText_loc7`='Ay, eso está mejor... ¿Cómo tengo el pelo?' WHERE `ID`=55182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 아이들에게 이 일에 대해 얘기해줘야겠습니다! 물론, 아빠가 꼼짝없이 갇혔었다는 부분은 조금 바꿔야겠지만...', `MaleText_loc4`='我要把这个故事告诉我的孩子们！当然了，我会把他们的爸爸受窘的部分修改一下的……', `MaleText_loc5`='我得去跟我的小崽子們說說這個故事!當然，我會改編一下爪爪卡住的那部分...', `MaleText_loc7`='¡Tengo que contárselo a mis cachorros! Claro que tendré que cambiar esa parte en la que papá se quedó atascado...', `FemaleText_loc1`='결심했어요. 이번에는 산재 보상을 신청할 거예요.', `FemaleText_loc4`='就这样：这事完了之后，我要申请危险津贴。', `FemaleText_loc5`='我受夠了。我之後一定要申請危險津貼。', `FemaleText_loc7`='Ya está: después de esta pido bono por peligrosidad.' WHERE `ID`=55183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님이 절 녹옥거미에게서 구해주실 거라고는 생각도 못했습니다. 감사합니다!', `MaleText_loc4`='真没想到，居然是个$c把我从蜘蛛嘴里救了下来。谢谢你！', `MaleText_loc5`='從沒想到我需要一個$c來救我逃過啃咬者。謝謝你!', `MaleText_loc7`='Nunca pensé que me haría falta $gun:una; $c para salvarme de los mordisqueadores. ¡Gracias!', `FemaleText_loc1`='제가 좋아하는 $c|1은;는;요, 용감하고 절 구해주는 분이에요!', `FemaleText_loc4`='我最喜欢你这种$c了：勇敢，乐于助人！', `FemaleText_loc5`='我最喜歡的一種$c。勇敢來救援的那種!', `FemaleText_loc7`='Mi $c $gfavorito:favorita;: ¡$gel:la; que me rescata!' WHERE `ID`=55184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 쓰레기의 악취가 풍겨오는군.', `MaleText_loc4`='空气里有联盟恶棍的臭味儿。', `MaleText_loc5`='有聯盟雜碎的臭味飄在空氣裡。', `MaleText_loc7`='El aire apesta a escoria de la Alianza.' WHERE `ID`=55185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 전 그냥 쉬고 있었어요... 가끔씩... 바위 밑에서 쉬거든요.', `MaleText_loc4`='噢，我只是在休息……我有时候就是在……石头底下休息的……', `MaleText_loc5`='喔，我只是在休息...有時候我...在石頭下休息...', `MaleText_loc7`='Solo estaba descansando... A veces descanso... debajo de las piedras...', `FemaleText_loc1`='이제 막 제 힘으로 빠져나오려던 참이었... 던 것 같아요.', `FemaleText_loc4`='我差一点就能钻出来了……反正我是这么觉得的。', `FemaleText_loc5`='我差一點就要扭出來了...我覺得啦。', `FemaleText_loc7`='Estaba A PUNTO de salir... creo.' WHERE `ID`=55186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하오 님께 가보겠습니다. 감사합니다!', `MaleText_loc4`='我会去找豪的。谢谢你！', `MaleText_loc5`='我會去找老郝報到的。謝啦!', `MaleText_loc7`='Iré a ver a Hao. ¡Gracias!', `FemaleText_loc1`='현장감독님이 길길이 뛰고 있겠네요. 제가 아니라 당신이 그분을 상대하게 돼서 다행이에요.', `FemaleText_loc4`='工头现在肯定气得七窍生烟了，幸好不用我去跟她打交道。', `FemaleText_loc5`='工頭現在一定是七竅生煙。幸好是你在跟她接洽而不是我。', `FemaleText_loc7`='La supervisora debe de estar furiosa. Menos mal que tú vas a lidiar con ella y no yo.' WHERE `ID`=55187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 친구가 되다니, 영리한 우낏이다.$b$b이제 호젠이 때려줘야 할 우낏이 하나 줄었다.', `MaleText_loc4`='蠢蛋选择和猢狲做朋友真是明智。$b$b现在，猢狲要砸扁的蠢蛋又少了一个。', `MaleText_loc5`='怪怪人很聰明，知道要當猴人的朋友。$b$b現在，猴人要打爛的怪怪人少一個了。', `MaleText_loc7`='Makaku hacer bien en ser amigo de hozen.$b$bAhora, un makaku menos que los hozen deber golpear.' WHERE `ID`=55188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 카 카 족장님, 우리가 이 땅을 탐험하려고 하는데, 괜찮은 안내인이 하나 필요합니다. 도와주시겠습니까?', `MaleText_loc4`='伟大的酋长卡哈卡哈，我们将探索您的领地，并且需要一名好的向导。您能帮我吗？', `MaleText_loc5`='卡卡大酋長，我們要探索你們的土地，並需要一名好嚮導。你願意幫助我們嗎?', `MaleText_loc7`='Gran jefe Kah Kah, vamos a explorar tus tierras y nos vendría muy bien contar con un guía. ¿Nos ayudas?', `FemaleText_loc1`='위대한 카 카 족장님, 우리가 이 땅을 탐험하려고 하는데, 괜찮은 안내인이 하나 필요해요. 도와주시겠어요?', `FemaleText_loc4`='伟大的酋长卡哈卡哈，我们将探索您的领地，并且需要一名好的向导。您能帮我吗？', `FemaleText_loc5`='卡卡大酋長，我們要探索你們的土地，並需要一名好嚮導。你願意幫助我們嗎?', `FemaleText_loc7`='Gran jefe Kah Kah, vamos a explorar tus tierras y nos vendría muy bien contar con un guía. ¿Nos ayudas?' WHERE `ID`=55189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 동굴이 붕괴하고 녹옥거미가 나타나고... 내일은 또 홍수와 진위가 몰려오겠지요? 채석장은 늘 그렇습니다.', `MaleText_loc4`='今天是塌方和利齿蛛，明天就有可能是洪水和锦鱼人入侵。在矿场嘛，混一天是一天了。', `MaleText_loc5`='今天是坍方跟啃咬者，明天就有洪水跟錦魚人。又是礦場裡尋常的一天。', `MaleText_loc7`='Hoy tocan derrumbamientos y mordisqueadores; mañana serán inundaciones y jinyu. Un día cualquiera en la cantera.', `FemaleText_loc1`='절대로 여기 다시 발을 들이는 일은 없을 거예요!', `FemaleText_loc4`='我再也不来这个鬼地方了！', `FemaleText_loc5`='我再也不來這個地方了!', `FemaleText_loc7`='¡No pienso volver a pisar este lugar!' WHERE `ID`=55190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 야근 수당을 받아야겠어!', `MaleText_loc4`='我最好加班加点干完它。', `MaleText_loc5`='我最好有加班費可以領。', `MaleText_loc7`='Más les vale que me paguen las horas extra.', `FemaleText_loc1`='이번에는 정말 야근 수당을 받아야겠어!', `FemaleText_loc4`='我最好加班加点干完它。', `FemaleText_loc5`='我最好有加班費可以領。', `FemaleText_loc7`='Más les vale que me paguen las horas extra.' WHERE `ID`=55191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠.$b$b<당신은 족장 카 카가 생각하는 동안 참을성 있게 기다립니다. 그리고 잠시 더 기다린 후에야 카 카가 입을 엽니다.>$b$b카 카한테 조카 많다. 모두 이름 이름을 얻은 녀석들이지.$b$b그루끼끼에는 이름 이름이 없는 녀석 없어야 하는데...$b$b리코는 정신 없는 녀석이다. 호젠 중에서도 심해. 우낏이랑 같이 오래 걸으면 정신 차릴지도 모르지.', `MaleText_loc4`='唔。$b$b<你耐心地等待酋长卡哈卡哈思考完，又等了一会儿，才听到他开口。>$b$b卡哈卡哈有许多子侄。他们都没给卡哈卡哈丢脸。$b$b古鲁金家族里只有一个家伙败坏了卡哈卡哈的名声……$b$b即便是对于猢狲来说，里克也显得太不安分了。也许到外面多走走能把他拉回正道上来。', `MaleText_loc5`='哼嗯。$b$b<你耐心地等卡卡酋長思考，然後再等他開口說話。>$b$b卡卡有很多姪子。他們都已經贏得自己的名名。$b$b回家去找一個還沒贏得名名的人...$b$b即使對猴人來說，瑞可也有點太活潑了。也許長途旅行對他有好處。', `MaleText_loc7`='Mmm.$b$b<Esperas pacientemente a que el jefe Kah Kah termine de pensar, y luego esperas un poco más a que empiece a hablar.>$b$bKah Kah tiene muchos sobrinos. Todos se ganan su nombre nombre.$b$bEn Makaku hay uno ke no gana todavía el nombre nombre...$b$bRiko es demasiado vago, inkluso para un hozen. Puede ke larga kaminata lo ayude.' WHERE `ID`=55192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮습니다! 아슬아슬했군요.', `MaleText_loc4`='我救下你了！好险啊。', `MaleText_loc5`='你沒事了!就差一點。', `MaleText_loc7`='¡Te tengo! Por los pelos.' WHERE `ID`=55193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해야 합니다. 경계가 삼엄하다고요!', `MaleText_loc4`='你得小心点——他们非常警惕！', `MaleText_loc5`='你要小心點...他們正全神戒備!', `MaleText_loc7`='Debes tener cuidado. ¡Están en alerta máxima!' WHERE `ID`=55194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하아, 이것 참... 제가 있는 걸 다행으로 아십시오.', `MaleText_loc4`='好吧……这真是太糟了。幸好有我在。', `MaleText_loc5`='嗯...情況有點糟。還好我在這裡。', `MaleText_loc7`='Vaya... se torció la situación. Suerte que estoy aquí.' WHERE `ID`=55195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 주머니를 털려고 한 건 아니겠지요?', `MaleText_loc4`='你不是想掏他们的口袋吧？', `MaleText_loc5`='你剛不會是想順手牽羊吧?', `MaleText_loc7`='¿No estarías intentando robarles, verdad?' WHERE `ID`=55196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하아... 다시 시도해 봅시다.', `MaleText_loc4`='救下你了！让我们再试一次……', `MaleText_loc5`='沒事了!咱們再試一次...', `MaleText_loc7`='¡Te tengo! Vamos a intentarlo de nuevo...' WHERE `ID`=55197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수레꾼을 데리고 와 줘서 고맙네, 친구.', `MaleText_loc4`='谢谢你帮我找回了车夫，朋友。', `MaleText_loc5`='謝謝你把我的車夫帶回來，朋友。', `MaleText_loc7`='Gracias por devolverme al conductor, $gamigo:amiga;.' WHERE `ID`=55198;
