UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이다! 잡아라!', `MaleText_loc4`='在这儿——抓住$g他:她;！', `MaleText_loc5`='在這裡 - 抓住$g他:她;!', `MaleText_loc7`='¡Por aquí! ¡Por $gél:ella;!' WHERE `ID`=55200;
