UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 보인다, 이 바보 녀석아!', `MaleText_loc4`='我看见你了，蠢货！', `MaleText_loc5`='看到你了，笨蛋!', `MaleText_loc7`='¡Te veo!' WHERE `ID`=55202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 도망칠 수 없다!', `MaleText_loc4`='你休想……逃跑！', `MaleText_loc5`='你...逃不了的!', `MaleText_loc7`='¡No puedes escapar!' WHERE `ID`=55203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러, $p! 폭풍 설사, 아니, 발사를 시작해야 해!', `MaleText_loc4`='快点，$p！我们要赶快开始装粪……我是说装弹！', `MaleText_loc5`='快點，$p!我們得開始聞...我是說開始轟炸!', `MaleText_loc7`='¡Deprisa, $p! Tenemos que empezar el olfateo... Digo, ¡el bombardeo!' WHERE `ID`=55204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련을 충실히 하셨군요.', `MaleText_loc4`='你的师父教出了个好徒弟。', `MaleText_loc5`='你被訓練得很好。', `MaleText_loc7`='Te han entrenado bien.' WHERE `ID`=55205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우셨습니다. 샹 사부님께서 기뻐하실 겁니다.', `MaleText_loc4`='打得漂亮。尚师父会很高兴的。', `MaleText_loc5`='打得好。尚羲大師會很高興的。', `MaleText_loc7`='Buen combate. El maestro Shang se alegrará mucho.' WHERE `ID`=55206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍습니다! 보기보다 훨씬 강하시군요.', `MaleText_loc4`='太棒了！你比看上去还要强壮得多。', `MaleText_loc5`='太棒了!你比外表看起來要強得多。', `MaleText_loc7`='¡Increíble! Eres más fuerte de lo que aparentas.' WHERE `ID`=55207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아직 수련이 부족한 것 같습니다. 가르침, 감사합니다.', `MaleText_loc4`='看来我还需要更多的练习。感谢你的教诲。', `MaleText_loc5`='看來我還得接受更多的訓練。多謝指教。', `MaleText_loc7`='Parece que tengo que entrenar más. Gracias por la lección.' WHERE `ID`=55208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 실력에 경의를 표합니다. 정정당당히 저를 이기셨습니다.', `MaleText_loc4`='我打不过你。你赢得光明正大。', `MaleText_loc5`='你的技巧令人欽佩。你堂堂正正打敗了我。', `MaleText_loc7`='Me inclino ante tus habilidades. Me has superado en buena lid.' WHERE `ID`=55209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 진 것은 영광입니다.', `MaleText_loc4`='被你击败是一种荣誉。', `MaleText_loc5`='敗在你手下是我的榮幸。', `MaleText_loc7`='Ha sido un honor que me hayas derrotado.' WHERE `ID`=55210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐으으으으읍!!!', `MaleText_loc4`='啊呀呀呀！！！', `MaleText_loc5`='哼嗯嗯嗯嗯!!!', `MaleText_loc7`='¡¡¡AHHGGG!!!' WHERE `ID`=55211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 됐네요. 괜찮을 거라고 했죠!', `MaleText_loc4`='哈，出来了。我就说了我能行！', `MaleText_loc5`='啊，可以了。我就說沒問題!', `MaleText_loc7`='¡Ya está! ¿Ves? ¡Lo tenía todo bajo control!' WHERE `ID`=55212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 일은 당신이 해결할 수 있겠죠? 전 다른 문제를 처리하겠습니다.', `MaleText_loc4`='我相信你能处理这里的事。我出去解决外面的问题。', `MaleText_loc5`='我相信你有辦法搞定這裡。我會在外面把一切都處理好。', `MaleText_loc7`='Seguro que te las arreglas sin problemas. Yo iré afuera a evaluar la situación.' WHERE `ID`=55213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='응급처치 필요한 분 계십니까?', `FemaleText_loc4`='有人需要医疗救助吗？', `FemaleText_loc5`='有誰需要醫療救援的嗎?', `FemaleText_loc7`='¿Alguien necesita asistencia médica?' WHERE `ID`=55214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진위는 아직 우리를 환영하는 것 같지 않지만, 우리의 선한 의도는 잘 전달됐을 거라고 생각합니다.', `FemaleText_loc4`='锦鱼人看上去可能不太友好，但我相信我们已经表达出了善意。', `FemaleText_loc5`='錦魚人也許不歡迎我們，但我相信我們證明了自己的善意。', `FemaleText_loc7`='Los jinyu no parecen muy afables, pero creo que estamos demostrando nuestras buenas intenciones.' WHERE `ID`=55215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의무병의 일은 끝나는 법이 없습니다.', `FemaleText_loc4`='医生总得忙个不停。', `FemaleText_loc5`='醫護人員的工作永不止息。', `FemaleText_loc7`='El trabajo de un médico no se acaba nunca.' WHERE `ID`=55216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 오래 머물수록, 이 신비한 땅의 매력에 더 빠져드는 것 같습니다.', `FemaleText_loc4`='我在这里呆得越久，就越喜欢这片神奇的大陆。', `FemaleText_loc5`='我在這裡待得時間越長，就越被這片奇怪土地所吸引。', `FemaleText_loc7`='Cuanto más tiempo paso aquí, más me gusta esta tierra extraña.' WHERE `ID`=55217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 집으로 돌아갈 수 있을 것 같습니까?', `FemaleText_loc4`='你说，我们会不会永远也回不了家了？', `FemaleText_loc5`='你覺得我們有找到回家之路的一天嗎?', `FemaleText_loc7`='¿Crees que alguna vez encontraremos el camino de regreso a casa?' WHERE `ID`=55218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러 해 동안 저는 임무에 실패한 적이 없습니다, $n 님. 이번에도 마찬가지일 겁니다.', `FemaleText_loc4`='我已经很多年没有搞砸过任务了。这次，我也不想搞砸。', `FemaleText_loc5`='許多年來，我從不曾讓一項任務失敗，$n。我現在也不打算失敗。', `FemaleText_loc7`='Hace muchos años que no fracaso en una misión, $n. No pienso empezar ahora.' WHERE `ID`=55219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님의 부상이 심각합니다, $n 님.', `FemaleText_loc4`='上将伤得很重，$n。', `FemaleText_loc5`='上將受了致命的傷害，$n。', `FemaleText_loc7`='El almirante está gravemente herido, $n.' WHERE `ID`=55220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 제때 도착하신 게 제독님께 얼마나 다행인지 모릅니다.', `FemaleText_loc4`='上将真是非常、非常走运，你竟然能及时赶到。', `FemaleText_loc5`='上將非常非常幸運能在那時候遇到你。', `FemaleText_loc7`='El almirante tiene mucha, mucha suerte de que hayas venido.' WHERE `ID`=55221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님의 상처를 보면, 아마 끔찍한 고문을 당하신 것 같습니다.', `FemaleText_loc4`='从伤口上看，上将遭受过严酷的折磨。', `FemaleText_loc5`='根據他的傷勢，上將正承受著殘酷的痛楚。', `FemaleText_loc7`='A juzgar por sus heridas, torturaron al almirante con crueldad.' WHERE `ID`=55222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님은 크게 다치셨지만, 가망이 없는 것은 아닙니다. 제가 고쳐드릴 수 있습니다. 시간이 조금 필요할 뿐입니다.', `FemaleText_loc4`='上将伤得很重，但并不是完全没救。我可以治好他，但我需要时间。', `FemaleText_loc5`='上將受的傷很重，但並沒有完全絕望。我可以治好他，但需要時間。', `FemaleText_loc7`='El almirante está herido, pero tiene remedio. Puedo sanarlo, pero llevará tiempo.' WHERE `ID`=55223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독님을 공격한 자들은... 야만족이라고 부를 수밖에 없습니다.', `FemaleText_loc4`='我只能将攻击上将的那些家伙称为……野蛮人。', `FemaleText_loc5`='我只能說攻擊上將的傢伙非常的...野蠻。', `FemaleText_loc7`='Solo se me ocurre una palabra para describir a los agresores del almirante: salvajes.' WHERE `ID`=55224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉬... $n 님, 이 부상을 치료하려면 집중해야 하니, 방해하지 말아 주십시오.', `FemaleText_loc4`='嘘，$n。我必须专心处理这些伤口。', `FemaleText_loc5`='噓，$n。我需要完全專心才能照料這些傷口。', `FemaleText_loc7`='$n, shhh. Necesito concentración total para curar estas heridas.' WHERE `ID`=55225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, $n 님. 당신이 없었다면, 제독님께서는 저 더러운 구덩이에서 돌아가셨을 겁니다.', `FemaleText_loc4`='谢谢你，$n。要不是你，上将肯定要葬身在那个肮脏的地方了。', `FemaleText_loc5`='謝謝你，$n。若沒有你，上將會死在那骯髒的坑裡。', `FemaleText_loc7`='Gracias, $c. Sin ti, el almirante habría perecido en aquel agujero infecto.' WHERE `ID`=55226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 이제는 꽤 유능한 의무병이 되셨군요. 응급치료 훈련을 계속하시는 게 좋겠습니다.', `FemaleText_loc4`='$n，你已经是一个非常熟练的医护兵了。你应该继续接受急救训练。', `FemaleText_loc5`='$n，你的急救技巧變得越來越熟練了。你應該繼續你的急救訓練。', `FemaleText_loc7`='Te estás convirtiendo en todo un as de las artes médicas, $n. Deberías continuar con tu entrenamiento en primeros auxilios.' WHERE `ID`=55227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안타깝지만 사령관님의 부상은 제가 손쓸 수 있는 수준이 아닙니다.', `FemaleText_loc4`='我对指挥官的伤势恐怕已经无能为力了。', `FemaleText_loc5`='我恐怕指揮官的傷勢不是我能照顧的了。', `FemaleText_loc7`='Me temo que las heridas del comandante superan mis habilidades.' WHERE `ID`=55228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 사령관님을 구하려면 기적이 필요합니다.', `FemaleText_loc4`='现在，只有奇迹才能拯救指挥官了。', `FemaleText_loc5`='現在需要奇蹟才能拯救指揮官。', `FemaleText_loc7`='Ahora solo un milagro podría salvar al comandante.' WHERE `ID`=55229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사령관님을 위해 제가 할 수 있는 건 모두 했습니다. 하지만 이제 시간이 얼마 남지 않은 것 같습니다.', `FemaleText_loc4`='我已经尽力抢救了。但指挥官恐怕已经坚持不了多久了。', `FemaleText_loc5`='我已經為指揮官盡了一切努力。我恐怕他的時間剩下不多了。', `FemaleText_loc7`='He hecho todo lo posible por el comandante. Me temo que ya no le queda mucho tiempo.' WHERE `ID`=55230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 몸이 괜찮습니다, $n 님. 신경 써 주셔서 감사합니다. 하지만 지금은 더 중요한 일이 있습니다.', `MaleText_loc4`='我感觉很好，$n。多谢你的关心，可眼下我们还有更重要的事情。', `MaleText_loc5`='我感覺還不錯，$n。謝謝你詢問，但我們手邊有更重要的事。', `MaleText_loc7`='Me encuentro bien, $n. Gracias por preguntar, pero hay cosas más importantes sobre las que tratar.' WHERE `ID`=55231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무법천지 상륙지에 전갈을 보냈습니다. 그쪽에서 곧 병사들을 보낼 겁니다.', `MaleText_loc4`='我已经往迷航港送了消息。他们应该很快就会派出更多士兵的。', `MaleText_loc5`='我已經送信到無常海岸，他們應該很快就會派更多士兵過來。', `MaleText_loc7`='He enviado un mensaje al Desembarco Improvisado. Deberían enviar más soldados dentro de poco.' WHERE `ID`=55232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작전을 위한 거점을 만드는 데 집중해야 합니다. 우선 이곳을 확보하고 나면, 집으로 돌아갈 방법을 찾아내는 데 인원을 할당할 수 있을 겁니다.', `MaleText_loc4`='我们必须先集中力量建立一个基地。等我们在这里站稳脚跟后，就能抽出人手来寻找回家的方法了。', `MaleText_loc5`='我們必須專注在建立行動基地的工作上。一旦取得穩固的根據地，我們就能分出資源來找尋回家的路。', `MaleText_loc7`='Debemos centrarnos en crear una base de operaciones. Cuando hayamos asegurado nuestra posición podremos emplear recursos en encontrar la forma de volver a casa.' WHERE `ID`=55233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 천연자원이 풍부합니다, $n 님. 돌아갈 때를 대비해서 상세한 보고서를 준비하고 있습니다.', `MaleText_loc4`='这片土地的资源很丰富，$n。我正在准备一份报告，回去以后应该能用上。', `MaleText_loc5`='這片土地擁有豐富的資源，$n。我正在準備一份詳細報告等回家後呈上。', `MaleText_loc7`='Esta tierra es rica en recursos, $n. Estoy preparando un informe detallado para cuando volvamos.' WHERE `ID`=55234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 원주민도 비교적 호의적입니다. 아, 저 원숭이들은 제외하고요.', `MaleText_loc4`='这里的原住民都很友善。呃，那些猴子除外。', `MaleText_loc5`='這裡的原生住民相當友善。好吧，除了那些猴子。', `MaleText_loc7`='Los nativos son muy amistosos. Bueno, a excepción de los monos.' WHERE `ID`=55235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위는 고대로부터 이어진 종족으로 보입니다. 시간이 지나면 저들의 비밀에 대해 알게 될 겁니다.', `MaleText_loc4`='锦鱼人似乎是个古老的种族。我们迟早会了解他们的秘密的。', `MaleText_loc5`='錦魚人似乎是個古老的種族，有一天我們會了解他們的秘密。', `MaleText_loc7`='Los jinyu parecen ser una raza antigua. Con el tiempo descubriremos sus secretos.' WHERE `ID`=55236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 저들의 족장과 이야기해보려 했는데, 저를 만나려 하지 않았습니다. 제가 "높은 지위"의 인물이 아니라는 것 같습니다. 아무래도 제독을 만나 본 적이 없는 모양입니다.', `MaleText_loc4`='我试图与他们的酋长对话，可他根本不想见我。看来，我的“地位”还不够高。显然，他从来没见识过“海军上将”这种人。', `MaleText_loc5`='我試著和他們的酋長講話，但他不想見我。看來我還不夠「高階」，顯然他從沒見過所謂的將軍。', `MaleText_loc7`='He intentado hablar con su jefe, pero no quiere verme. Parece ser que mi grado no es "lo suficientemente alto". Por lo visto, nunca ha recibido a un almirante.' WHERE `ID`=55237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 유리지느러미 장로와 친분을 맺는 데 실패했습니다. $C님, 이제는 당신에게 기대를 걸겠습니다.', `MaleText_loc4`='我是没法和珠鳍长老交上朋友了，$C。我就全指望你能成功了。', `MaleText_loc5`='我沒辦法和珠鰭村的長者建立友誼。$C，我得靠你完成我失敗的任務了。', `MaleText_loc7`='No he sido capaz de trabar amistad con el ancestro Aleta de Nácar. $C, cuento contigo para que triunfes donde yo he fracasado.' WHERE `ID`=55238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<타일러 제독은 매우 위독합니다. 지금은 말을 걸지 않는 편이 좋겠습니다.>', `MaleText_loc4`='<泰勒病得很重。现在最好别去打扰他。>', `MaleText_loc5`='<泰勒病得極重，最好先不要和他說話。>', `MaleText_loc7`='<Taylor está muy enfermo. Es mejor no hablar con él en este momento.>' WHERE `ID`=55239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따는 중', `MaleText_loc4`='采摘', `MaleText_loc5`='撿起來', `MaleText_loc7`='Recogiendo', `FemaleText_loc1`='따는 중', `FemaleText_loc4`='采摘', `FemaleText_loc5`='撿起來', `FemaleText_loc7`='Recogiendo' WHERE `ID`=55240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배움의 첫 단계는 자네가 배워야 할 것이 많음을 인정하는 것이네.', `MaleText_loc4`='学习的第一步就是承认自己的无知。', `MaleText_loc5`='學習的第一步，就是承認你還有很多有待學習。', `MaleText_loc7`='El primer paso del aprendizaje es admitir que te queda mucho por aprender.' WHERE `ID`=55241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 지혜는 자네가 익혀야 할 것이 많다는 점을 이해하는 것에서 출발한다네.', `MaleText_loc4`='智慧源自于对自身愚昧的认识。', `MaleText_loc5`='真正的智慧來自於理解你尚未熟知的事物。', `MaleText_loc7`='La verdadera sabiduría radica en comprender que te queda mucho por dominar.' WHERE `ID`=55242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 어서 어서! 당장이라도 놈들이 여기 들이닥칠 거야!', `MaleText_loc4`='快，快，快！他们随时可能出现！', `MaleText_loc5`='快點、快點、快點!他們隨時都會到!', `MaleText_loc7`='¡Vamos, vamos, vamos! ¡Llegarán en cualquier momento!' WHERE `ID`=55243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우왓! 달라란 치즈의 톡 쏘는 향기가 느껴져!', `MaleText_loc4`='哇！闻上去很像达拉然奶酪！', `MaleText_loc5`='喔耶!聞起來像是達拉然乳酪!', `MaleText_loc7`='¡Uf! ¡Huele a queso añejo de Dalaran!' WHERE `ID`=55244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼라이언스 쓰레기들이 내 전리품을 훔쳐가게 놔두진 않겠다.', `MaleText_loc4`='我绝不能让这个联盟恶棍把我的战利品偷回去。', `MaleText_loc5`='我可不會讓這些聯盟雜碎偷走我的戰利品。', `MaleText_loc7`='No pienso dejar que la escoria de la Alianza se lleve mi tesoro.' WHERE `ID`=55245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내가 화약을 압축... 연료로 대체하기만 하면 준비가 완료될 거야! 말하자면 그렇다고.', `MaleText_loc4`='所以，如果我用压缩……燃料来替代火药，那我们就发达了。只是打个比方。', `MaleText_loc5`='所以如果我把火藥直接替換成壓縮過的...燃料，我們應該就能搞定了!差不多啦。', `MaleText_loc7`='Si cambio la pólvora por... combustible comprimido, ¡funcionará! Posiblemente.' WHERE `ID`=55246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그로그주가 더 있습니까?', `MaleText_loc4`='还有烈酒吗？', `MaleText_loc5`='還有烈酒可喝嗎?', `MaleText_loc7`='¿Tienes más grog?', `FemaleText_loc1`='그로그주가 더 있나요?', `FemaleText_loc4`='还有烈酒吗？', `FemaleText_loc5`='還有烈酒好喝嗎?', `FemaleText_loc7`='¿Tienes más grog?' WHERE `ID`=55247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 성공한다고 가정하면, 내 발명품에도 이름이 필요할 텐데... 음... 그루끼끼 응가탄 어때?', `MaleText_loc4`='这是一件杰作，我给我的发明起个名字……古鲁金手雷怎么样？', `MaleText_loc5`='假設這能有效。我得為我的發明取個名字。「便便爆彈」...聽起來如何?', `MaleText_loc7`='Suponiendo que esto funcionase, necesitaré un nombre para mi invento. ¿Qué tal... granada jeringue?' WHERE `ID`=55248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 조심해! 이런 메탄 실험실은 폭발할 가능성이 극도로 높아!', `MaleText_loc4`='小心，$p！这些沼气室可能极不稳定.', `MaleText_loc5`='小心，$p!像這樣的甲烷萃取室會具有極高的易爆性。', `MaleText_loc7`='¡Cuidado, $p! Los laboratorios de metano como estos pueden resultar extremadamente explosivos.' WHERE `ID`=55249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, 리벳. 준비되었습니다!', `MaleText_loc4`='好的，利维特。我准备好了！', `MaleText_loc5`='好啦，理弗特。我準備好啦!', `MaleText_loc7`='Bueno, Perno. Estoy listo.', `FemaleText_loc1`='좋아요, 리벳. 준비됐어요!', `FemaleText_loc4`='好的，利维特。我准备好了！', `FemaleText_loc5`='好啦，理弗特。我準備好啦!', `FemaleText_loc7`='Bueno, Perno. Estoy lista.' WHERE `ID`=55250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 지나갈 자격을 얻었네. 후오는 안쪽에 있다네.', `MaleText_loc4`='你可以继续前进了。燧焰就在前面。', `MaleText_loc5`='你贏得了前行的權利。霍就在那裡。', `MaleText_loc7`='Te has ganado el derecho a avanzar. Prosigue y hallarás a Huo.' WHERE `ID`=55251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당근이 나타났다!', `MaleText_loc4`='出现了一个胡萝卜！', `MaleText_loc5`='胡蘿蔔出現了!', `MaleText_loc7`='¡Ha aparecido una zanahoria!' WHERE `ID`=55252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아, 당근!', `MaleText_loc4`='哦，一个胡萝卜！', `MaleText_loc5`='喔，有胡蘿蔔!', `MaleText_loc7`='¡Ooh, una zanahoria!' WHERE `ID`=55253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련한 보람이 있군, 젊은 $c|1이여;여;. 후오를 찾아서 사원으로 무사히 데리고 왔네.', `MaleText_loc4`='你的训练很有成效，年轻的$c。你成功找到了燧焰并将他带回了五晨寺。', `MaleText_loc5`='你的訓練有了成果，年輕的$c。你找到霍，並將他平安帶來了寺廟。', `MaleText_loc7`='Tu entrenamiento ha dado sus frutos, joven $c. Has encontrado a Huo y lo has traído de vuelta al templo sano y salvo.' WHERE `ID`=55254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 당근!', `MaleText_loc4`='嗯……胡萝卜！', `MaleText_loc5`='嗯...胡蘿蔔!', `MaleText_loc7`='Mmm... ¡zanahoria!' WHERE `ID`=55255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보게. 후오가 사원에는 따스함을, 사람들에게는 열정을 되돌려 주고 있네.', `MaleText_loc4`='看呐，燧焰不仅将温暖带回了寺中，更让他的人民恢复了激情。', `MaleText_loc5`='看哪，霍又將溫暖帶回這座寺廟，讓熱情重回人民心中。', `MaleText_loc7`='Contemplad cómo Huo devuelve el calor al templo y el entusiasmo a su pueblo.' WHERE `ID`=55256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 오늘 해낸 일이 정말 자랑스럽네.', `MaleText_loc4`='我为你今天的成就而骄傲。', `MaleText_loc5`='我為你今天的成就感到驕傲。', `MaleText_loc7`='Estoy orgulloso de lo que has conseguido hoy.' WHERE `ID`=55257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 커!', `MaleText_loc4`='真大啊！', `MaleText_loc5`='它好胖!', `MaleText_loc7`='¡Está muy gorda!' WHERE `ID`=55258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 정령은 물의 정령 슈라네. 준비가 되면 동쪽에 있는 노래하는 웅덩이로 아이사를 찾아가게.', `MaleText_loc4`='接下来，你要去找上古水灵涓流。你准备好之后，就去东边的咏之池找艾莎吧。', `MaleText_loc5`='下一名等待你去尋找的元素之靈是水之靈·舒。準備好時，去東邊的頌唱之池找艾莎。', `MaleText_loc7`='El próximo espíritu que te espera es Shu, el espíritu del agua. Cuando estés $glisto:lista;, reúnete con Aysa en las Pozas Cantarinas, situadas al este.' WHERE `ID`=55259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 맛있어!', `MaleText_loc4`='看起来很多汁！', `MaleText_loc5`='看起來很多汁!', `MaleText_loc7`='¡Parece muy jugosa!' WHERE `ID`=55260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문제 없어 보이는데.', `MaleText_loc4`='看起来不错。', `MaleText_loc5`='看起來是真的。', `MaleText_loc7`='Qué buena pinta...' WHERE `ID`=55261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 당근이 정말 좋아. 당근이 너무 좋아.', `MaleText_loc4`='我喜欢。我喜欢这个胡萝卜。', `MaleText_loc5`='我愛它。我愛這胡蘿蔔。', `MaleText_loc7`='Me encanta. Me encanta esta zanahoria.' WHERE `ID`=55262;
