UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이런 짓을 한 거야?!', `MaleText_loc4`='谁会做这种事啊？！', `MaleText_loc5`='誰會做這麼過分的事?', `MaleText_loc7`='¡¿Quién podría hacer algo así?!' WHERE `ID`=55268;
