UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신하는 걸 잊지 마세요!', `MaleText_loc4`='别忘了使用潜行！', `MaleText_loc5`='不要忘記使用潛行!', `MaleText_loc7`='¡No olvides utilizar tu sigilo!' WHERE `ID`=55276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 왜 이러십니까? 거기서 날아다니면 들킨다고요!', `MaleText_loc4`='你疯了吗？如果你到处乱飞，会被他们发现的！', `MaleText_loc5`='你瘋了嗎?如果你飛來飛去，他們會看到你的!', `MaleText_loc7`='¿Estás chiflado? ¡Te van a ver si entras ahí volando!' WHERE `ID`=55277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 날아다니면 안 됩니다. 들키고 만다고요!', `MaleText_loc4`='你不能在这里飞行。我们一定会被发现的！', `MaleText_loc5`='你不能在這裡飛。我們一定會被看到!', `MaleText_loc7`='No puedes volar por aquí. ¡Seguro que nos atraparán!' WHERE `ID`=55278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 먼지만도 못하다. 내 등에서 쓸어내면 그만인 것들.', `MaleText_loc4`='你们比尘埃更渺小，赶走你们就像掸走灰尘一般容易。', `MaleText_loc5`='你們連灰塵都不如，只配從我的背上被刷掉。', `MaleText_loc7`='Son más despreciables que el polvo que me sacudo de la espalda.' WHERE `ID`=55279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 된 거냐? 얼라이언스는 그로그주도 못 마시나? 하하하!', `MaleText_loc4`='出什么事了？联盟藏的烈酒泄漏了吗？哈哈哈！', `MaleText_loc5`='怎麼啦?聯盟傢伙被自己的酒嗆倒了?哈哈哈!', `MaleText_loc7`='¿Qué pasa? ¿A la Alianza se le sube el grog a la cabeza? ¡Ja ja!' WHERE `ID`=55280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다... 잘하고 계세요... 계속 가보십시오...', `MaleText_loc4`='就是这样……你做的很好……坚持住……', `MaleText_loc5`='就是這樣...你做得很好...保持下去...', `MaleText_loc7`='Eso es... Puedes hacerlo... Sigue así...' WHERE `ID`=55281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 정문은 경비가 너무 삼엄합니다. 아, 장원 뒤편으로 가보십시오. 다른 길이 있을지도 모릅니다.', `MaleText_loc4`='小心！前门的守卫太森严了。唔……绕到庄园后头去看看，我们或许能找到其他道路。', `MaleText_loc5`='小心!前門的警戒太嚴密了。嗯...繞到莊園的後面，也許我們可以找到別的路進去。', `MaleText_loc7`='¡Cuidado! La puerta delantera está demasiado vigilada. Mmm, ronda por detrás de la mansión. Tal vez así encontremos otra forma de entrar.' WHERE `ID`=55282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 가시는 겁니까? 장원은 반대쪽에 있습니다!', `MaleText_loc4`='你要去哪儿？庄园在另一边！', `MaleText_loc5`='你要去哪?莊園在另一個方向!', `MaleText_loc7`='¿Adónde vas? ¡La mansión está en la otra dirección!' WHERE `ID`=55283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 이쪽엔 아무것도 없는 것 같군요. 빙 돌아 장원 뒤편으로 가보십시오.', `MaleText_loc4`='唔……这儿似乎什么都没有。试试绕到庄园背后去。', `MaleText_loc5`='嗯嗯...這裡看起來什麼都沒有。試著繞到莊園後面去看看。', `MaleText_loc7`='Mmm... no parece que haya nada por aquí. Intenta rondar por detrás de la mansión.' WHERE `ID`=55284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이쪽엔 경비가 없군요. 혹시 지붕으로 올라가실 수 있겠습니까?', `MaleText_loc4`='啊哈！这里没有守卫！看看你能不能找到一条上屋顶的路？', `MaleText_loc5`='啊哈!後面這裡沒有守衛。也許你可以想辦法爬上屋頂?', `MaleText_loc7`='¡Ajá! Aquí no hay guardias. Es posible que encuentres la manera de subir al tejado.' WHERE `ID`=55285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 거기 창문 열린 거 없습니까? 둘러보세요!', `MaleText_loc4`='干得漂亮！那上面有没有打开的窗户？仔细找找！', `MaleText_loc5`='做得好!上面有窗戶沒關好嗎?到處看看!', `MaleText_loc7`='¡Buen trabajo! ¿Hay alguna ventana abierta? ¡Mira por ahí!' WHERE `ID`=55286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요! 자, 놈들이 알을 어디에 숨겨 뒀을까요? 어딘가 어두운 구석이겠죠. 조심하십시오!', `MaleText_loc4`='你成功了！你进去了！现在……他们会把蛋藏在哪儿呢？我猜是个漆黑的地方。仔细点！', `MaleText_loc5`='你成功了!你在裡面了!現在呢...他們會把蛋藏在哪裡?我猜一定在暗處。小心點!', `MaleText_loc7`='¡Lo lograste! ¡Estás adentro! Veamos... ¿Dónde podrían estar guardando el huevo? Diría que en algún lugar oscuro. ¡Ten cuidado!' WHERE `ID`=55287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네가 두렵지 않다! 잠깐... 넌... 넌 누구지?', `MaleText_loc4`='我可不怕你！等等……你……你是谁？', `MaleText_loc5`='我才不怕你!等等...你...你是誰?', `MaleText_loc7`='¡No te tengo miedo! Espera, ¿quién eres tú?' WHERE `ID`=55288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 데스윙의 졸개들이 당신을 죽일 수도...', `MaleText_loc4`='但……但死亡之翼的爪牙可能会杀了你……', `MaleText_loc5`='但是...死亡之翼的爪牙會殺死你的...', `MaleText_loc7`='Pero... puede que los subordinados de Alamuerte te asesinen…' WHERE `ID`=55289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀한 $r|1이여;여;, 몇 가지 합의를 통해 제가 석방될 수 있는 방법을 틀림없이 도출할 수 있을 겁니다.', `MaleText_loc4`='高贵的$r，我相信我们是可以就释放我的问题达成某些共识的。', `MaleText_loc5`='高貴的$r，我確定我們可以達成讓我重獲自由的協議。', `MaleText_loc7`='Noble $r, estoy seguro de que podremos llegar a un acuerdo para mi liberación.' WHERE `ID`=55290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 옛날 티탄의 시대부터 감춰져 있던 이 미지의 이상향에 우리가 함께 서 있는데, 왜 전쟁을 시작하려 하십니까?', `MaleText_loc4`='我们正站在一片与泰坦一样古老的隐秘乐土上，而你却满脑子都是打打杀杀的事？', `MaleText_loc5`='我們正站在一塊和泰坦同樣古老的失落天堂上，難道你只想打仗?', `MaleText_loc7`='Nos encontramos en un paraíso inexplorado tan antiguo como los mismísimos titanes, ¿y quieres declarar una guerra?' WHERE `ID`=55291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 종족들을 우리 전쟁에 휘말리게 하고요? 이 땅을 전쟁의 공포에 물들게 하고 싶습니까?$b$b그게 정말로 당신들이 원하는 겁니까?', `MaleText_loc4`='将这些种族卷入我们的战争？用战火玷污这片土地？$b$b你真的想这么做吗？', `MaleText_loc5`='讓這些種族捲入我們的戰爭?用戰爭的恐懼污染這片淨土?$b$b這真是你想要的嗎?', `MaleText_loc7`='¿Involucrar a estas razas en nuestra guerra? ¿Mancillar esta tierra con el horror de la batalla?$b$b¿Es eso lo que quieres de verdad?' WHERE `ID`=55292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 저들을 훈련시켜 군대로 만드는 데 성공하셨군요...$b$b놀라운 업적입니다. 하지만 전쟁이 정말 옳은 일일까요?', `MaleText_loc4`='所以，你训练出了一支军队……$b$b一个了不起的成就，可战争真的是正确的应对方式吗？', `MaleText_loc5`='沒錯，你訓練出了一支軍隊...$b$b確實是令人刮目相看的成就，但戰爭真的是正確的發展方向嗎?', `MaleText_loc7`='Así que has conseguido formar un ejército...$b$bUna hazaña en toda regla, ¿pero es la guerra el camino correcto?' WHERE `ID`=55293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 종족들 간의 적대심을 교묘하게 이용하는 것은 현명한 일이 아닙니다, $r님.$b$b그 결과에 대한 책임도 당신들이 짊어져야 할 겁니다.', `MaleText_loc4`='利用这些种族之间的仇恨是不明智的，$r。$b$b你必须为后果负责。', `MaleText_loc5`='利用這些種族之間的敵意是不明智的，$r。$b$b有一天你會必須為其後果負責。', `MaleText_loc7`='Aprovecharse de la hostilidad entre estas razas es insensato, $r.$b$bVas a tener que aceptar la responsabilidad de las consecuencias.' WHERE `ID`=55294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물과 대지의 정령을 데리고 왔군. 이 노사부는 자랑스러울 따름일세.', `MaleText_loc4`='你把水灵和土灵带回来了。我为你感到骄傲。', `MaleText_loc5`='你帶著水與土之靈一起回來了。你讓我這個老師傅感到驕傲。', `MaleText_loc7`='Has regresado con los espíritus del agua y la tierra. Este viejo maestro está orgulloso.' WHERE `ID`=55295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우고우와 슈는 언제든 환영일세. 우리가 잘 돌보겠네.', `MaleText_loc4`='五晨寺欢迎无垢和涓流的归来。我们会好好照顾他们的。', `MaleText_loc5`='我們竭誠歡迎烏果跟舒。他們會受到妥善照顧。', `MaleText_loc7`='Wugou y Shu son bienvenidos. Los cuidaremos muy bien.' WHERE `ID`=55296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 남은 정령은 다펑뿐일세. 서쪽, 새벽의 교각 건너 어딘가에 숨어 있다네.', `MaleText_loc4`='现在只剩下上古风灵大风了，他就躲在西边的晨之桥那头的某个地方。', `MaleText_loc5`='最後一位元素之靈名叫大風，他就躲在西邊晨曦橋另一端的某處。', `MaleText_loc7`='El único espíritu que queda es Dafeng. Se esconde en algún lugar de El Puente del Amanecer, al oeste.' WHERE `ID`=55297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 사원 꼭대기로 보내 주겠네. 지가 기다리고 있으니 함께 가게.', `MaleText_loc4`='我会把你送到寺院顶层。季在那里等着你，他会为你带路的。', `MaleText_loc5`='我能帶你到寺廟頂端，紀在那裡等著為你引路。', `MaleText_loc7`='Puedo llevarte hasta lo alto del templo. Allí te espera Ji, quien guiará tu camino.' WHERE `ID`=55298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='욱... 아무래도 응가가 삐져나온 것 같아.', `MaleText_loc4`='呃……我好像把事情搞砸了。', `MaleText_loc5`='呃...我好像快要便便...', `MaleText_loc7`='Ugh... kreo ke me he grokado los mikos.' WHERE `ID`=55299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼! 응가할 때도 고개는 꼿꼿이!', `MaleText_loc4`='该死！真见鬼！', `MaleText_loc5`='喔!用力憋便便!', `MaleText_loc7`='¡Uh, uh! ¡Kraku perraku!' WHERE `ID`=55300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우욱... 상한 미끈고기 꿀꺽했더니...', `MaleText_loc4`='噢……这些混蛋光板儿……', `MaleText_loc5`='喔呃...壞滑魚害了我。', `MaleText_loc7`='Ooh... Mandukos malos me jeringa...' WHERE `ID`=55301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 제일 잘하는 건 우끼끼 응가 철푸덕!', `MaleText_loc4`='猢狲最擅长干这个了！', `MaleText_loc5`='猴人最會壞壞!', `MaleText_loc7`='¡Hozen dinga mejor que makaku!' WHERE `ID`=55302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 움직일 때마다 머드머그의 약병에서 물이 천천히 새어나옵니다! 조심해서 걸으십시오!', `MaleText_loc4`='在你行进过程中，泥盏的瓶子会不断地渗水。请谨慎选择路线！', `MaleText_loc5`='在你移動時，泥杯的水瓶會慢慢地濺出水來。小心規劃你的路線!', `MaleText_loc7`='El vial de Caolín derramará agua lentamente mientras te estés moviendo. ¡Planifica bien tu ruta!', `FemaleText_loc1`='당신이 움직일 때마다 머드머그의 약병에서 물이 천천히 새어나옵니다! 조심해서 걸으십시오!', `FemaleText_loc4`='在你行进过程中，泥盏的瓶子会不断地渗水。请谨慎选择路线！', `FemaleText_loc5`='在你移動時，泥杯的水瓶會慢慢地濺出水來。小心規劃你的路線!', `FemaleText_loc7`='El vial de Caolín derramará agua lentamente mientras te estés moviendo. ¡Planifica bien tu ruta!' WHERE `ID`=55303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 용의 영혼을 손에 넣어야 한다. 이 시간의 안개 속으로 영영 사라지기 전에...', `MaleText_loc4`='在这里，我们要趁巨龙之魂失落于时间的迷雾之前将它夺回。', `MaleText_loc5`='在巨龍之魂失落在時間的迷霧前，我們會在這裡拿走它。', `MaleText_loc7`='Aquí recuperaremos el Alma de dragón antes de que se pierda en la noche de los tiempos.' WHERE `ID`=55304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 아즈샤라를 따르는 명가 놈들이 만든 보호의 수호물을 찾아서 없애라. 궁전 안에서 찾을 수 있을 터. 난 그 이후를 탐색해 보마.', `MaleText_loc4`='但首先，你们必须先破坏艾萨拉的上层精灵布下的防护结界。他们就在宫殿里。我会先行一步。', `MaleText_loc5`='但首先你必須先破壞艾薩拉的貴族手下所施放的保護結界。它們就在宮殿的裡面。我先去前面探探路。', `MaleText_loc7`='Pero antes, deben eliminar a los resguardos de los lacayos Altonato de Azshara. Los encontrarán en el palacio. Me adelantaré para explorar.' WHERE `ID`=55305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 비노라!', `MaleText_loc4`='祝你们好运，英雄们！', `MaleText_loc5`='祝好運，英雄們!', `MaleText_loc7`='¡Buena suerte, héroes!' WHERE `ID`=55306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 이놈들! 너희가 잠들어 있던 샤를 깨운 놈들이로구나!', `MaleText_loc4`='是你们！这么多年了，是你们又让煞再次苏醒！', `MaleText_loc5`='你!在煞沉眠了這麼多年之後，你竟然讓它甦醒了!', `MaleText_loc7`='¡Ustedes han permitido que los sha despierten, después de todos estos años!' WHERE `ID`=55307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 진정으로 우리 땅에 불러온 재앙을 막고자 한다면 먼저 스스로의 능력을 증명해 보이거라.', `MaleText_loc4`='你们这些人给我们的家园带来如此灾难，如果你们真想补救，就在这儿，证明自己。', `MaleText_loc5`='如果你真的想挽救你們族人在我們的土地上造成的災難，你必須在我們的學院這裡證明自己的能耐。', `MaleText_loc7`='Si desean reparar el daño que su gente ha causado en nuestra tierra, antes tendrán que demostrar su valía en esta escuela.' WHERE `ID`=55308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저, 우리 신입생들을 상대해 봐라...', `MaleText_loc4`='首先，你们要面对我的徒弟们…', `MaleText_loc5`='首先，你要迎戰我們的學徒...', `MaleText_loc7`='Primero, se enfrentarán a nuestros iniciados...' WHERE `ID`=55309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 명이 쓰러지면 다른 수련생이 그 자리를 대신할 것이다.', `MaleText_loc4`='就算一个倒下，另一个会奋起替代他。', `MaleText_loc5`='如果有人倒下，另一個人會接替他的位置。', `MaleText_loc7`='Cuando uno cae, otro acude a ocupar su puesto.' WHERE `ID`=55310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤에게서 백성들을 지키려면 아직 갈 길이 먼 것 같구나. 네 동료들이 싸울 수 있게 물러서거라!', `MaleText_loc4`='如果你们想战胜煞，保护你们的族人，就要多加学习。做好准备，战斗到底！', `MaleText_loc5`='學徒，若想保護同胞不受煞的威脅，你還有很多要學的。退下，讓你的同學過去!', `MaleText_loc7`='Te queda mucho por aprender si pretendes defender a tu pueblo de los sha, iniciado. ¡Da paso a tus compañeros!' WHERE `ID`=55311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 들어온 신참들보다는 강하구나. 그럼 우리의 상급생 둘을 상대해 봐라.', `MaleText_loc4`='你们只是击败了我最年轻的学徒而已。接下来是我的两位得意门生。', `MaleText_loc5`='你打贏了我資歷最淺的徒弟。現在你要面對我最資深的兩個徒弟。', `MaleText_loc7`='Han superado a mi pupilo más inexperto. Ahora se las verán con dos de los más veteranos...' WHERE `ID`=55312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비설! 연향! 앞으로 나오거라!', `MaleText_loc4`='飞雪！香莲！速速上前！', `MaleText_loc5`='飛雪!香蓮!上前!', `MaleText_loc7`='¡Nieve Volátil! ¡Loto Fragante! ¡Adelante!' WHERE `ID`=55313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 특출난 수련생 둘을 쓰러뜨리다니. 진정 우리에게 도움이 될 수 있겠구나...', `MaleText_loc4`='你们击败了我最强的学生。也许你们还不算一无是处…', `MaleText_loc5`='你打贏了我最自豪的徒弟。也許你還是能派上用場的...', `MaleText_loc7`='Han derrotado a mis mejores discípulos. Es posible que sí puedan ayudarnos…' WHERE `ID`=55314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 사부님이 말씀하셨지, ''진정 상대를 알고 싶다면 싸워봐야 한다.''고...', `MaleText_loc4`='也许这就是我师父曾说过的“不打不相识吧。”', `MaleText_loc5`='我師父曾經說過一句話，「真正的武士，以拳才能交心」。', `MaleText_loc7`='Como decía mi maestro: "No conoces de verdad a alguien hasta que has luchado contra él".' WHERE `ID`=55315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 야영지가 불타며 피어오르는 연기에서조차 공허와 수치의 냄새가 나는군.', `MaleText_loc4`='就连他们那燃烧的营地上空的浓烟，都带着无能和羞耻的味道。', `MaleText_loc5`='就連他們營地著火冒出的煙都滲漏出無力和羞愧的氣息。', `MaleText_loc7`='Hasta el humo de los restos de su campamento en llamas siembra futilidad y vergüenza.' WHERE `ID`=55316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $p. 그루끼끼 언덕에서 다시 만나서, 다음 계획에 대해 이야기하지.', `MaleText_loc4`='干得好，$p。回古鲁金来见我，我们商量一下下一步的行动。', `MaleText_loc5`='做得好$p。和我在葛魯碰面，我們來討論下一步該怎麼行動。', `MaleText_loc7`='Bien hecho, $p. Reúnete conmigo en Makaku para establecer nuestro siguiente plan de acción.' WHERE `ID`=55317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $n. 나만큼 목이 마른 건가?', `MaleText_loc4`='你好，$n。你也像我一样口渴吗？', `MaleText_loc5`='你好，$n。你和我一樣口渴嗎?', `MaleText_loc7`='Hola, $n. ¿Tienes tanta sed como yo?' WHERE `ID`=55318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 준비됐습니다. 어서 가시죠.', `MaleText_loc4`='我准备好了。出发吧。', `MaleText_loc5`='我準備好了，上路吧。', `MaleText_loc7`='Estoy listo. En marcha.', `FemaleText_loc1`='저는 준비됐어요. 어서 가요.', `FemaleText_loc4`='我准备好了。出发吧。', `FemaleText_loc5`='我準備好了。上路吧。', `FemaleText_loc7`='Estoy lista. En marcha.' WHERE `ID`=55319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 종말의 시작이다. 태양을 뒤덮어버리는 그림자이자, 네 파멸을 알리는 종소리이다.', `MaleText_loc4`='我即是末日的开端……蔽日的阴影……毁灭的丧钟……', `MaleText_loc5`='我是終結的開始...遮掩陽光的印跡...通知末日將臨的鈴聲...', `MaleText_loc7`='Soy el principio del fin, la sombra que eclipsa el Sol, la campana que tañe por tu muerte.' WHERE `ID`=55320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄청난 무언가가 느껴진다. 조화롭지 못한 그의 혼돈이 내 정신을 어지럽히는구나!', `FemaleText_loc4`='一股破坏平衡的力量正在接近。它的混乱灼烧着我的心智！', `FemaleText_loc5`='我感到平衡被一股強大的波動干擾。如此混沌在燃燒我的心靈!', `FemaleText_loc7`='Percibo que se avecina una gran alteración del equilibrio. ¡Su caos inunda mi mente!' WHERE `ID`=55321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가련한 녀석들, 이 실험은 위대한 결말을 위한 희생이었다. 알 연구의 결과물을 직접 확인해라.', `MaleText_loc4`='这些龙崽子，这些实验，只为一个崇高的目标。你很快就会看到我最伟大的研究成果。', `MaleText_loc5`='這些幼龍、實驗品，只不過是實現更偉大目標的手段罷了。你會看到研究的龍蛋有什麼成果。', `MaleText_loc7`='Simples crías, experimentos, un medio para un fin mayor. Verás el resultado de las investigaciones de mi nidada.' WHERE `ID`=55322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 순간만을 위해 태어났다. 네 저승사자의 모습을 봐라, 필멸자여. 그리고 절망하라.', `MaleText_loc4`='我存在的意义就是为了这个时刻。见证你们的死亡和绝望吧，凡人！', `MaleText_loc5`='我就是為了此刻而生。在絕望中迎接你們的死亡吧，凡人們!', `MaleText_loc7`='Me crearon para este preciso momento. Contemplen su muerte, mortales, y desesperen.' WHERE `ID`=55323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지의 힘이여, 내 부름을 들어라! 아제로스의 마지막 수호자들을 어두운 시간으로부터 보호해다오!', `MaleText_loc4`='大地之力，听我召唤！请在这个黑暗的时刻庇护艾泽拉斯最后的守护者！', `MaleText_loc5`='大地之力啊，請聆聽我的呼喚!在這個黑暗之刻保護艾澤拉斯的最終防衛者吧!', `MaleText_loc7`='Fuerza de la tierra, ¡atiende mi llamada! ¡Protege a los últimos defensores de Azeroth en esta hora oscura!' WHERE `ID`=55324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘을 내라, 영웅들이여. 삶은 가장 어두운 흙 속에서 피어나는 법!', `FemaleText_loc4`='振作起来，英雄们，生命总能在最黑暗的土地上绽放！', `FemaleText_loc5`='振作起來，英雄們。最黑暗的土壤也能綻放生命!', `FemaleText_loc7`='Ánimo, héroes. ¡La vida siempre florece en la tierra más sombría!' WHERE `ID`=55325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꿈 속에서는 그 어떤 역경도 이겨낼 수 있다!', `FemaleText_loc4`='在梦中，我们能够克服任何障碍！', `FemaleText_loc5`='在夢境中，我們可以克服一切阻礙!', `FemaleText_loc7`='En sueños, ¡podemos superar cualquier obstáculo!' WHERE `ID`=55326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 바람이여, 저들의 뒤를 받쳐라. 역경을 헤치는 용사들을 회복시켜라!', `MaleText_loc4`='奥术之风将支援他们，让他们在这个黑暗的时刻重焕活力！', `MaleText_loc5`='秘法之風照拂他們，在此黑暗之刻給他們力量!', `MaleText_loc7`='¡Que los vientos de lo arcano estén con ellos y los conforten en esta hora de oscuridad!' WHERE `ID`=55327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 순환은 모든 것의 끝을 불러오리니.', `MaleText_loc4`='时光的轮回将带来万物的终结。', `MaleText_loc5`='時間的輪迴終究會終結一切事物。', `MaleText_loc7`='El ciclo temporal hace que todas las cosas lleguen a su fin.' WHERE `ID`=55328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 황혼의 시간이다!', `MaleText_loc4`='暮光审判降临了！', `MaleText_loc5`='現在就是暮光之時!', `MaleText_loc7`='¡Es la Hora del Crepúsculo!' WHERE `ID`=55329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 하지만.. 난... 난... 울트락시...', `MaleText_loc4`='可……可……我是……奥卓……', `MaleText_loc5`='但...但我是...奧特拉...', `MaleText_loc7`='Pero... pero... soy... Ul...' WHERE `ID`=55330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울트락시온 앞에 무릎 꿇어라!', `MaleText_loc4`='在我面前倒下吧！', `MaleText_loc5`='在奧特拉賽恩面前倒下吧!', `MaleText_loc7`='¡Caigan ante Ultraxion!' WHERE `ID`=55331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 희망은 없다!', `MaleText_loc4`='你们毫无希望！', `MaleText_loc5`='你們沒有希望!', `MaleText_loc7`='¡No tienen esperanza!' WHERE `ID`=55332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하하!', `MaleText_loc4`='哈哈哈！', `MaleText_loc5`='哈哈哈哈!', `MaleText_loc7`='¡Ja! ¡Ja! ¡Ja! ¡Ja! ¡Ja!' WHERE `ID`=55333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 빛 한 줄기가 흐려진다. 네 가소로운 필멸의 목숨과 함께!', `MaleText_loc4`='最后一缕光也消失了，你们这些可悲的凡人也将随之消逝！', `MaleText_loc5`='最後一絲光明消散了。你們可悲的凡人生命也隨之而去!', `MaleText_loc7`='¡El último rayo de luz se apaga y, con él, su lamentable y mortal existencia!' WHERE `ID`=55334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 님, 당신의 은총이... 제게는 너무 과합니다. 저는... 으아아아아아아악!', `MaleText_loc4`='死亡之翼阁下，我承受不了……您的馈赠……我……啊啊啊啊！！', `MaleText_loc5`='吾主死亡之翼，您的禮物...太重了。我沒辦法...', `MaleText_loc7`='Lord Alamuerte, su don... es demasiado. Estoy…' WHERE `ID`=55335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통과 화염 속에서 내 끝없는 증오가 타오른다.', `MaleText_loc4`='我的仇恨在烈焰与痛苦中燃烧！', `MaleText_loc5`='我的恨意在痛苦和火焰中燃燒!', `MaleText_loc7`='¡Con el dolor y el fuego mi odio arde!' WHERE `ID`=55336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화염과 암흑 속으로, 너희 모두 다 끌고 가주마.', `MaleText_loc4`='我要拖着你们一起陷入烈焰与黑暗！', `MaleText_loc5`='我會把你們一起拖進火焰和黑暗之中。', `MaleText_loc7`='¡LOS ARRASTRARÉ CONMIGO A LAS LLAMAS Y LA OSCURIDAD!' WHERE `ID`=55337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t 알렉스트라자가 |cFFFF0000|Hspell:105896|h[생명의 선물]|h|r을 소환합니다!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t阿莱克丝塔萨召唤出了|cFFFF0000|Hspell:105896|h[生命赐福]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t 雅立史卓莎召喚出|cFFFF0000|Hspell:105896|h[生命賜福]|h|r!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_01.blp:20|t ¡Alexstrasza invoca la |cFFFF0000|Hspell:105896|h[Ofrenda de vida]|h|r!' WHERE `ID`=55338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_green.blp:20|t 이세라가 |cFF00CC00|Hspell:105900|h[꿈의 정수]|h|r를 소환합니다!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_green.blp:20|t伊瑟拉召唤出了|cFF00CC00|Hspell:105900|h[梦境精华]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_green.blp:20|t 伊瑟拉召喚出|cFF00CC00|Hspell:105900|h[夢之精華]|h|r!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_green.blp:20|t ¡Ysera invoca la |cFF00CC00|Hspell:105900|h[Esencia de los sueños]|h|r!' WHERE `ID`=55339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t 칼렉고스가 |cFF0000FF|Hspell:105903|h[마법의 원천]|h|r을 소환합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t卡雷苟斯召唤出了|cFF0000FF|Hspell:105903|h[魔力之源]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t 卡雷苟斯召喚了|cFF0000FF|Hspell:105903|h[魔力之源]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_blue.blp:20|t ¡Kalecgos invoca la |cFF0000FF|Hspell:105903|h[Fuente de magia]|h|r!' WHERE `ID`=55340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t 노즈도르무가 |cFFFFFF00|Hspell:105984|h[시간의 고리]|h|r로 당신을 강화합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t诺兹多姆为你加持了|cFFFFFF00|Hspell:105984|h[时光之环]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t 諾茲多姆賦予你|cFFFFFF00|Hspell:105984|h[時之環]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_bronze.blp:20|t ¡Nozdormu te imbuye con un |cFFFFFF00|Hspell:105984|h[Bucle temporal]|h|r!' WHERE `ID`=55341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t 스랄이 대지의 힘으로 방어 담당자를 강화합니다! 당신은 |cFF9900CC|Hspell:106218|h[아제로스의 마지막 수호자]|h|r입니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t萨尔为坦克们加持了大地之力！你成为了|cFF9900CC|Hspell:106218|h[艾泽拉斯最后的守护者]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t 索爾賦予坦克大地之力!你成為了|cFF9900CC|Hspell:106218|h[艾澤拉斯最終防衛者]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_black.blp:20|t ¡Thrall imbuye a los tanques con la Fuerza de la tierra! ¡Representas al |cFF9900CC|Hspell:106218|h[Último defensor de Azeroth]|h|r!' WHERE `ID`=55342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 울트락시온이 |cFF9900CC|Hspell:106373|h[더욱 불안정한 상태]|h|r가 됩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t奥卓克希昂发生|cFF9900CC|Hspell:106373|h[新生变异]|h|r了！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 奧特拉賽恩變得|cFF9900CC|Hspell:106373|h[更不穩定]|h|r了!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightimmolation.blp:20|t ¡Ultraxion se vuelve |cFF9900CC|Hspell:106373|h[más inestable]|h|r!' WHERE `ID`=55343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightcano.blp:20|t 울트락시온의 불안정성이 최고 수준에 달해 |cFF9900CC|Hspell:106388|h[황혼 분출]|h|r을 일으킵니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightcano.blp:20|t奥卓克希昂的不稳定导致了大规模的|cFF9900CC|Hspell:106388|h[暮光崩裂]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightcano.blp:20|t 奧特拉賽恩不穩定的狀態造成了巨大的|cFF9900CC|Hspell:106388|h[暮光爆發]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightcano.blp:20|t ¡La inestabilidad de Ultraxion provoca una enorme |cFF9900CC|Hspell:106388|h[Erupción Crepuscular]|h|r!' WHERE `ID`=55344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 울트락시온이 |cFF9900CC|Hspell:106395|h[최고조의 불안정성]|h|r 상태가 됩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t奥卓克希昂发生|cFF9900CC|Hspell:106395|h[致命变异]|h|r了！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 奧特拉賽恩達到了|cFF9900CC|Hspell:106395|h[極限不穩定]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_twilightimmolation.blp:20|t ¡Ultraxion alcanza la |cFF9900CC|Hspell:106395|h[Inestabilidad máxima]|h|r!' WHERE `ID`=55345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 의무는 동포들을 보호하는 것입니다. 제가 최전방에 서야 한다면, 기꺼이 그러겠습니다.', `MaleText_loc4`='我的职责就是保护我的人民。如果必须要我上前线，那么我将义无反顾。', `MaleText_loc5`='我的責任是保衛我的族人。如果必須身赴前線才能做到，我在所不辭。', `MaleText_loc7`='Mi deber es proteger a mi pueblo. Si para eso debo estar en el frente, partiré de buena gana.' WHERE `ID`=55346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 강력한 진위입니다! 어떤 공격이라도 두려움 없이 막아낼 수 있습니다!', `MaleText_loc4`='我很强壮！我能承受凶猛的攻击而面不改色！', `MaleText_loc5`='我是個強大的錦魚人!我能無懼地承受無數次的重擊!', `MaleText_loc7`='¡Soy un jinyu fuerte! ¡Puedo soportar muchos ataques sin temor!' WHERE `ID`=55347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 온몸으로 적의 공격을 막아내는 동안, 동료들이 적을 쓰러뜨릴 겁니다.', `MaleText_loc4`='当敌人把注意力都放在我身上时，我的战友们就可以从后面包抄他们了！', `MaleText_loc5`='當敵人的注意力集中在我身上，我的盟友就能從後面突襲!', `MaleText_loc7`='Mientras los enemigos me atacan a mí, ¡mis aliados pueden escabullirse por detrás!' WHERE `ID`=55348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 검은 빠르고 제 발은 튼튼합니다. 제 동료들을 공격하기 전에, 적들은 우선 저를 상대해야 할 겁니다.', `MaleText_loc4`='我步履沉着、运剑如风。敌人必须先打倒我，才能去阻挠我的战友们。', `MaleText_loc5`='我的劍如閃電，腳如磐根。敵人想攻擊我的盟友得先問過我。', `MaleText_loc7`='Mi espada es veloz y mis pies firmes. Los enemigos tienen que vérselas conmigo antes de enfrentarse a mis aliados.' WHERE `ID`=55349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 시절부터 저게는 치유술이 더 매력적이었습니다.', `MaleText_loc4`='从小时候起，我就对医术很着迷。', `MaleText_loc5`='我從年輕的時候就對醫術很感興趣。', `MaleText_loc7`='Desde una edad temprana, me encaminé hacia las artes de la sanación.' WHERE `ID`=55350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투로 인해 부상을 입은 이를 보살펴주는 사람이 너무 적습니다. 제게 기술만 있다면, 반드시 앞장서겠습니다.', `MaleText_loc4`='照顾伤员的人手太少了。如果能掌握相关的技术，我很乐意加入他们。', `MaleText_loc5`='很少人會關心戰爭中的傷者。如果我懂得醫術，絕對會加入他們的行列。', `MaleText_loc7`='Hay pocos que puedan atender a los heridos en combate. Si contara con la habilidad necesaria, les ayudaría.' WHERE `ID`=55351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 아프고 다친 이들에게 붕대와 식량을 가져다줍니다. 더 많이 도와줄 수 있다면 좋을 텐데...', `MaleText_loc4`='我给伤病员带来了绷带和食物。我要是能再多帮点忙就好了……', `MaleText_loc5`='我將繃帶和食物帶給病患和傷者。真希望我還能多做點什麼...', `MaleText_loc7`='Traigo vendas y comida para los enfermos y los heridos. Ojalá pudiera hacer algo más...' WHERE `ID`=55352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 땅에서는 치유사들이 전사들과 함께 전장에 나선다는 것이 사실입니까? 저도 더 좋은 장비를 갖추기만 한다면, 그렇게 할 수 있을지도 모릅니다.', `MaleText_loc4`='在你们那儿，治疗者真的要跟着战士上战场吗？如果我有趁手的家伙，我或许也做得到。', `MaleText_loc5`='在你的土地上，治療者和戰士真的會並肩同上戰場嗎?如果我的器具再好一點，或許我也會做一樣的事。', `MaleText_loc7`='¿Es verdad que en tu tierra los sanadores acompañan a los guerreros en combate? Si tuviera mejores herramientas a lo mejor podría hacer lo mismo.' WHERE `ID`=55353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 친구들! 석쇠에서 갓 구워낸 미끈고기를 맛보라고!', `MaleText_loc4`='好了，小伙子们！快来拿吧，刚烤好的滑水鱼！', `MaleText_loc5`='好了小子們!到烤架這邊來拿點現烤的鮮魚!', `MaleText_loc7`='¡Vengan, chicos! ¡Vengan por un poco de "manduka" recién sacada de la parrilla!' WHERE `ID`=55354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 물의 성질을 변화시켜 적에게 쏟아붓는 것을 좋아합니다.', `MaleText_loc4`='我更喜欢塑造流水之形，并使用它们来对付我的敌人。', `MaleText_loc5`='我偏好操控水的特性，並將其釋放出來對抗我的敵人。', `MaleText_loc7`='Prefiero alterar las propiedades del agua y utilizarla contra mis enemigos.' WHERE `ID`=55355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 마법에 소질이 조금 있습니다. 하지만 한번쯤 정식으로 훈련을 받고 싶습니다.', `MaleText_loc4`='我有一些魔法天分，可我希望能接受更加系统的训练。', `MaleText_loc5`='我懂一些魔法的技巧，但我希望自己能受過正式訓練。', `MaleText_loc7`='Tengo cierta pericia en las artes mágicas, pero me gustaría haber recibido más instrucción.' WHERE `ID`=55356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 기본적인 전사 훈련을 받았습니다. 하지만 제가 주문 시전에 더 소질이 있다는 것을 아는 이는 별로 없습니다.', `MaleText_loc4`='我已经接受过基础战士训练了，可大家都不知道，其实我的施法技巧更加出色。', `MaleText_loc5`='我接受過基本的戰士訓練，但沒有人知道我更懂得施法的技巧。', `MaleText_loc7`='He recibido el entrenamiento básico de un guerrero, pero nadie sabe que se me da mejor lanzar hechizos.' WHERE `ID`=55357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 창은 전혀 다룰 줄 모릅니다. 그보다 더 먼 거리에서 전투하는 편이 좋습니다.', `MaleText_loc4`='我对长矛一窍不通。我更喜欢远程战斗。', `MaleText_loc5`='我不擅於使用長矛。我比較希望從遠距離作戰。', `MaleText_loc7`='Las lanzas se me dan fatal. Prefiero el combate a distancia.' WHERE `ID`=55358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 매우 민첩합니다. 제가 적의 뒤쪽으로 다가가더라도, 적은 제 기척을 눈치채지 못할 겁니다.', `MaleText_loc4`='我的行动迅捷如风。只要把我置于敌人身后，他们甚至不会感觉到我的接近。', `MaleText_loc5`='我的動作敏捷迅速。讓我待在敵人後面，他們完全感覺不到我的行動。', `MaleText_loc7`='Soy rápido y veloz. Ponme detrás de un enemigo y jamás sabrán lo que les ha pasado.' WHERE `ID`=55359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='체격이 작다는 것에도 장점이 있습니다. 제가 몰래 숨어들지 못하는 곳이 없으니까요.', `MaleText_loc4`='小个子也有小个子的优势。我能潜入任何地方而不被发现。', `MaleText_loc5`='體型小隻一點也有優勢，我幾乎能潛行到任何地方。', `MaleText_loc7`='Ser pequeño tiene sus ventajas. Me puedo colar por casi cualquier sitio.' WHERE `ID`=55360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 모두 일반 전사 훈련을 받습니다만, 아무래도 저는 잠입 임무가 더 잘 어울리는 것 같습니다.', `MaleText_loc4`='这里的所有人都会接受标准的战士训练，可我觉得我更合适隐秘任务。', `MaleText_loc5`='這裡每個人都接受過標準的戰士訓練，但覺得自己更適合秘密的任務。', `MaleText_loc7`='Aquí todos reciben el entrenamiento de guerrero estándar, pero yo creo que sirvo más para misiones en las que se requiere el sigilo.' WHERE `ID`=55361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 적과 정면으로 맞서본 적이 없습니다. 전 제 지혜와... 몇 가지 은밀한 속임수를 사용하는 것을 선호합니다.', `MaleText_loc4`='我从不正面对敌。我更喜欢运用头脑……以及各种鬼祟伎俩来战胜敌人。', `MaleText_loc5`='我從不和敵人硬碰硬。我寧願運用我的機智...和各種隱密的伎倆。', `MaleText_loc7`='Nunca me enfrento directamente a un enemigo. Prefiero utilizar mi ingenio... y un par de trucos sigilosos.' WHERE `ID`=55362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 내가 아는 얼굴이군, 인간. 너는... 바리안 린의 아들이구나!', `MaleText_loc4`='等等，我认识你，人类。你是瓦里安·乌瑞恩的儿子！', `MaleText_loc5`='等等，我記得你的臉，人類。你是瓦里安·烏瑞恩的兒子!', `MaleText_loc7`='Espera, humano. Tu cara me suena. ¡Eres el hijo de Varian Wrynn!' WHERE `ID`=55363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, $p. 그렇게 빨리 만들 수는 없으니까... 한 발 한 발 신중하게 쏴야 한다고!', `MaleText_loc4`='好了，$p。我的速度只能那么快了……你要好好利用每一颗炸弹！', `MaleText_loc5`='好了，$p。我盡我最快的速度做出這些...你得好好運用每一顆手榴彈!', `MaleText_loc7`='Muy bien, $p. No puedo ir más rápido... ¡tienes que hacer que cada disparo cuente!' WHERE `ID`=55364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 실컷 요구해 봐라, 꼬마 왕자야. 네 머리를 몸통으로부터 석방시켜 줄 테니.', `MaleText_loc4`='哈！你要再多嘴，我的小王子，我就把你的小脑袋砍下来！', `MaleText_loc5`='哈!再發號施令一次，小王爺，我就會把你的頭從肩膀上摘下來!', `MaleText_loc7`='¡Ja! ¡Haz otra solicitud, principito, y te arrancaré la cabeza de cuajo!' WHERE `ID`=55365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군님, 절 아버지의 관할 구역으로 석방해 주실 것을 요구합니다!', `MaleText_loc4`='先生，我要求你立即释放我，并将我送到我父亲那里！', `MaleText_loc5`='先生，我要求立即得到釋放，接受我父親的監護!', `MaleText_loc7`='General, solicito que se me libere y se me entregue a mi padre.' WHERE `ID`=55366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐다! 이곳에 머물 만큼 머문 것 같구나.', `MaleText_loc4`='好了！我们在这儿待得够久了。', `MaleText_loc5`='好吧!我想我們在這裡待得夠久了。', `MaleText_loc7`='Bueno, creo que ya nos hemos quedado lo suficiente aquí.' WHERE `ID`=55367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더풋 일가는 좋은 이들이지만, 이곳의 술을 다 합쳐도 술통 하나도 안 나오는구나.', `MaleText_loc4`='雷脚一家真好，但他家的啤酒少得连一个酒桶都装不满。', `MaleText_loc5`='雷足家的都是好人，可惜他們的藏酒竟然連一個木桶都裝不滿。', `MaleText_loc7`='Estos Pie Atronador son buena gente, pero no tienen suficiente cerveza para llenar un barril.' WHERE `ID`=55368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 마실 것을 좀 찾아 보자꾸나, 리 리.', `MaleText_loc4`='我们去找些啤酒行吗，丽丽？', `MaleText_loc5`='我們去找點喝的吧，怎麼樣啊，莉莉?', `MaleText_loc7`='Vamos a buscar cerveza, ¿te parece, Li Li?' WHERE `ID`=55369;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맥주로 삼촌 엉덩이를 뗄 수만 있다면야... 좋아요. 가요.', `FemaleText_loc4`='如果啤酒能让你挪动屁股，那……我们就去找吧。', `FemaleText_loc5`='既然非要有酒喝你才肯動起來，那...好吧。我們一起去找啤酒吧。', `FemaleText_loc7`='Si lo que necesitas es calmar la sed para ponerte en marcha... Claro, vamos a buscarte una cerveza.' WHERE `ID`=55370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 계시게!', `MaleText_loc4`='再见了，尚！', `MaleText_loc5`='再會啦，尚!', `MaleText_loc7`='¡Hasta pronto, Shang!' WHERE `ID`=55371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그네 집에서 재미있는 시간 보내십시오! 고마웠습니다!', `MaleText_loc4`='在泥盏那儿玩得开心点！再次感谢！', `MaleText_loc5`='到泥杯那裡玩得開心點!再次多謝啦，$n!', `MaleText_loc7`='¡Que se diviertan con Caolín! ¡Y gracias de nuevo!' WHERE `ID`=55372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌, 봐요. 앞에 누가 있어요. 좀... 이상해 보이는데요.', `FemaleText_loc4`='叔叔，看。前面有个人。他看起来……很奇怪。', `FemaleText_loc5`='叔叔，看。前頭有個人。他看起來...怪怪的。', `FemaleText_loc7`='Tío, mira. Hay alguien allí delante. Tiene un aspecto... extraño.' WHERE `ID`=55373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서는 우리가 이방인이란다, 리 리. 우리가 더 이상해 보일 수도 있어.', `MaleText_loc4`='在这里我们可是外人，丽丽，对他来说，我们看起来可能更奇怪。', `MaleText_loc5`='我們在這裡才是外人，莉莉。也許我們在他眼中更怪。', `MaleText_loc7`='Aquí nosotros somos los forasteros, Li Li. A él le pareceremos aún más extraños.' WHERE `ID`=55374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥. 그건 이 이방인 때문이에요!', `FemaleText_loc4`='嘁……还不是因为我们跟外乡人走在一起！', `FemaleText_loc5`='哼...那只是因為我們跟這個外來者走在一起!', `FemaleText_loc7`='Bah... ¡solo porque viajamos con otros forasteros!' WHERE `ID`=55375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안하지만, 당신은 눈에 띄어요.', `FemaleText_loc4`='抱歉，$n，但你的确与众不同。', `FemaleText_loc5`='抱歉，$n，但你是有點顯眼。', `FemaleText_loc7`='Perdona, pero llamas un poco la atención.' WHERE `ID`=55376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 얼라이언스 꼬마? 여기에?', `MaleText_loc4`='这是什么？一个联盟男孩儿？在这种地方？', `MaleText_loc5`='這是什麼?一個聯盟的小男孩?在這地方?', `MaleText_loc7`='¿Qué? ¿Un chico de la Alianza? ¿Aquí?' WHERE `ID`=55377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 소리예요? 우린 판다렌인걸요! 우리가 거북이 등 출신이라고 이상할 건 없죠.', `FemaleText_loc4`='什么？我们都是熊猫人！难道迷踪岛的熊猫人看上去会很怪？', `FemaleText_loc5`='什麼?我們可都是熊貓人。我們從烏龜那裡來不代表我們長得很奇怪。', `FemaleText_loc7`='¿Qué? ¡Aquí todos somos pandaren! Que vengamos de la tortuga no significa que tengamos un aspecto extraño.' WHERE `ID`=55378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안하지만, 당신은 눈에 띄어요.', `FemaleText_loc4`='好吧，是$n看起来有一点奇怪。抱歉，$n。', `FemaleText_loc5`='好吧，$n長得是有點奇怪。抱歉，$n。', `FemaleText_loc7`='Bueno, $n tiene una pinta un poco extraña. Lo siento, $n.' WHERE `ID`=55379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 낯선 이!', `MaleText_loc4`='你好啊，陌生人！', `MaleText_loc5`='哈囉～～～～～～陌生人!', `MaleText_loc7`='¡Hooolaaa, desconocido!' WHERE `ID`=55380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그라는 양조장이를 찾고 있다네. 혹시 아는가?', `MaleText_loc4`='我们正在找一个名叫泥盏的酿酒师。你认识他吗？', `MaleText_loc5`='我們在找個叫泥杯的釀酒師。你認識他嗎?', `MaleText_loc7`='Buscamos a un cervecero llamado Caolín. ¿Sabes algo de él?' WHERE `ID`=55381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 머드머그입니다만, 누구십니까?', `MaleText_loc4`='我就是泥盏。你们是？', `MaleText_loc5`='我就是泥杯。是誰要找我?', `MaleText_loc7`='Soy Caolín. ¿Quién lo pregunta?' WHERE `ID`=55382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 첸이라 하네. 이 아이는 조카 리 리지.', `MaleText_loc4`='我是陈，这是我的侄女丽丽。', `MaleText_loc5`='我是老陳，這是我的姪女莉莉。', `MaleText_loc7`='Me llamo Chen, y esta es mi sobrina, Li Li.' WHERE `ID`=55383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인 린... 우리가 지금껏 겪어 왔던 온갖 고통에 대한 적당한 보상이 되겠어! $p, 이리 오게. 할 말이 있네.', `MaleText_loc4`='安度因·乌瑞恩……我们吃的苦终于得到回报了。 $p，过来，和我谈谈。', `MaleText_loc5`='安杜因·烏瑞恩...對我們在這受到的試煉來說，是個合適的獎品!$p，過來和我談話。', `MaleText_loc7`='Anduin Wrynn... ¡una recompensa digna del sufrimiento que hemos padecido! $p, ven a hablar conmigo.' WHERE `ID`=55384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 다들 토깽 놈들과 잘 싸우십니까?', `MaleText_loc4`='嗯，你们能对付兔妖吗？', `MaleText_loc5`='嗯。你們都很會打架吧?', `MaleText_loc7`='Mmm. ¿Son buenos para luchar contra mures?' WHERE `ID`=55385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇고말고요! 전 유랑도에서 토깽을 백만 마리쯤 혼쭐을 내준 사람이라고요!', `FemaleText_loc4`='那可是我们的拿手好戏！在迷踪岛上，我打扁过上百万只兔妖！', `FemaleText_loc5`='當然行咧!在漂流島上我恐怕已經打過上百萬隻兔妖啦!', `FemaleText_loc7`='¡Claro que sí! ¡Habré acabado como a un millón de mures en La Isla Errante!' WHERE `ID`=55386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토깽 때문에 골치가 아프다고? 우리가 도와 주겠네.', `MaleText_loc4`='你遇到兔妖了？我们很乐意帮助你，泥盏。', `MaleText_loc5`='你在煩惱兔妖的問題嗎?我們很樂意來幫你，泥杯。', `MaleText_loc7`='¿Tienes problemas con los mures? Nos gustaría ayudarte, Caolín.' WHERE `ID`=55387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 좋습니다! 여기만 돌면 제 집입니다.', `MaleText_loc4`='那好吧！我就住在附近。', `MaleText_loc5`='那好吧!我家就在轉角那邊。', `MaleText_loc7`='¡Muy bien! Mi casa está a la vuelta de la esquina.' WHERE `ID`=55388;
