UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거봐요. 이상한 사람 맞지.', `FemaleText_loc4`='我就说他很奇怪吧。', `FemaleText_loc5`='跟你說過他很怪吧。', `FemaleText_loc7`='Ya te dije que era extraño.' WHERE `ID`=55392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용을 따라잡고 있소! 아마도 구름 속에서 놈을 따라잡을 수 있을 거요!', `MaleText_loc4`='我们就快追上那条龙了！我想我们可以把它从云层里揪出来！', `MaleText_loc5`='我們快追到他了!我可以透過雲端看到他!', `MaleText_loc7`='¡Estamos alcanzando al dragón! ¡Creo que veo su silueta a través de las nubes!' WHERE `ID`=55393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 가까이 데려가 주십시오!', `MaleText_loc4`='让我们再靠近点！', `MaleText_loc5`='我們再靠近點!', `MaleText_loc7`='¡Acerquémonos!', `FemaleText_loc1`='더 가까이 데려가 주세요!', `FemaleText_loc4`='让我们再靠近点！', `FemaleText_loc5`='我們再靠近點!', `FemaleText_loc7`='¡Acerquémonos!' WHERE `ID`=55394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위상들을 둘러싸고 있던 보호막이 흩어집니다! 위상들이 약해졌습니다!', `MaleText_loc4`='守护巨龙周围的护盾碎裂了！守护巨龙要受到伤害了！', `MaleText_loc5`='包圍守護巨龍們的護罩破碎了!守護巨龍有危險了!', `MaleText_loc7`='¡Los escudos que cubren a los Aspectos se quiebran! ¡Los Aspectos son vulnerables!' WHERE `ID`=55395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 무슨 일로 우리 마을에 오셨습니까?', `MaleText_loc4`='外来人，你来我们村干什么？', `MaleText_loc5`='外地人，是什麼讓你來到我們的村子?', `MaleText_loc7`='¡$gForastero:Forastera;! ¿Qué te trae a nuestra aldea?' WHERE `ID`=55396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 주민들이 온통 이방인 얘기만 하던데, 그게 바로 당신이었군요.', `MaleText_loc4`='你肯定就是大家都在议论的那个外来人。', `MaleText_loc5`='你一定是那個所有人都在談論的外地人。', `MaleText_loc7`='Tú debes de ser $gel forastero del:la forastera de la; que todo el mundo habla.' WHERE `ID`=55397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠도 당신들과 마찬가지로 우리에게 접근했었습니다.$B$B우린 그저 가엾다는 생각이 들어서, 이 땅에서 살아남는 법을 알려줬었지요.$B$B시간이 지날수록 놈들은 더 강해지고 대담해졌고, 오히려 이 땅을 점령하기 시작했습니다.', `MaleText_loc4`='猢狲曾经也来向我们求助过，就像你现在这样。$B$B我们同情他们，并教会他们如何在这片土地上生存。$B$B可随着时间推移，他们越来越强大，也越来越傲慢，开始想要独占这片土地。', `MaleText_loc5`='猴人曾經就像你這樣來到我們這裡。$B$B我們曾覺得他們很可憐，而教導他們如何在這塊土地上生存。$B$B隨著時間過去，他們變得強壯且大膽，並開始將這塊土地據為己有。', `MaleText_loc7`='Una vez los hozen nos pidieron ayuda, igual que nos la pides tú ahora.$b$bNos dieron lástima y les enseñamos a sobrevivir en esta tierra.$b$bCon el tiempo se volvieron fuertes y orgullosos y comenzaron a conquistar la tierra.' WHERE `ID`=55398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이방인을 쉽게 믿지 말라는 가르침을 받았습니다, $c님.', `MaleText_loc4`='经历了这次教训之后，我们就不再相信陌生人了，$c。', `MaleText_loc5`='我們學會了不要相信陌生人，$c。', `MaleText_loc7`='Nos han enseñado a no confiar en los desconocidos, $c.' WHERE `ID`=55399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이라고 하셨습니까? 요즘 마을에서 당신의 이름이 자주 들리더군요.', `MaleText_loc4`='$n是吗？我在村里听说过你的名字。', `MaleText_loc5`='$n，是嗎?我在村中久聞你的大名。', `MaleText_loc7`='¿$n, verdad? He oído hablar de ti por la aldea.' WHERE `ID`=55400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 바로 그 $c|1이로;로;군요. 제 동생의 유품을 가져다 주셔서 감사합니다. 그 유품은 이제 제게 가장 소중한 물건이 되었습니다.', `MaleText_loc4`='你就是那个$c，对吧？谢谢你把我哥哥的传家宝带了回来，那是我最宝贵的财富。', `MaleText_loc5`='你就是那個$c，不是嗎?謝謝你取回我兄弟的傳家寶。它已成為我最珍貴的寶物。', `MaleText_loc7`='Eres $gel:la; $c, ¿verdad? Gracias por recuperar la reliquia de mi hermano. Se ha convertido en mi posesión más preciada.' WHERE `ID`=55401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 제가 당신에 대해 잘못 생각한 모양입니다, $r님. 이미 우리 마을에 큰 도움을 주셨습니다.', `MaleText_loc4`='或许我误解了你，$r。你已经帮了我们村很多忙了。', `MaleText_loc5`='或許我對你的想法是錯的，$r。你已經幫了我們村子這麼多。', `MaleText_loc7`='Quizás me equivoqué contigo, $r. Ya has hecho mucho para ayudar a nuestra aldea.' WHERE `ID`=55402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 종족에게는 정말 흥미로운 점이 많습니다, $r님. 당신과 다른 종족에 대해 알고 싶다는 마음이 생겼습니다.', `MaleText_loc4`='你们的人很有趣，$r。我希望能更深入地了解你和你的同胞们。', `MaleText_loc5`='你們非常有趣，$r。我希望能知道更多關於你還有你的同胞的事。', `MaleText_loc7`='Tu gente es muy interesante, $r. Quiero saber más sobre ti y sobre tu pueblo.' WHERE `ID`=55403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 언젠가 저도 당신의 고향에 가볼 일이 있겠지요, $n 님.', `MaleText_loc4`='或许有一天，我也会去拜访你的村子的，$n。', `MaleText_loc5`='也許有一天我也能拜訪你的村莊，$n。', `MaleText_loc7`='Espero visitar tu aldea algún día, $n.' WHERE `ID`=55404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 우리 마을을 위해 좋은 일을 많이 해주셨습니다, $n 님. 어쩌면 우리도 친구가 될 수 있을지 모릅니다.', `MaleText_loc4`='你为我们的村子做了许多好事，$n。或许我们是可以成为朋友的。', `MaleText_loc5`='你為我們的村子做了許多好事，$n。也許我們終究是能做朋友。', `MaleText_loc7`='Has hecho mucho bien en nuestra aldea, $n. Puede que acabemos siendo amigos después de todo.' WHERE `ID`=55405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 위상들을 둘러싼 보호막이 울트락시온의 공격에 파괴됩니다!', `MaleText_loc4`='奥卓克希昂的攻击摧毁了守护巨龙们四周的护盾！', `MaleText_loc5`='環繞守護巨龍的護盾被奧特拉賽恩的攻擊摧毀了!', `MaleText_loc7`='¡El ataque de Ultraxion ha destruido el escudo que rodeaba a los Aspectos!' WHERE `ID`=55406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 이 호수에서 수천 년째 살아왔습니다. 이곳의 물은 판다리아의 고대 웅덩이에서부터 흘러 내려옵니다.', `MaleText_loc4`='我们在这座湖泊上居住了几千年了。这里的湖水源自于潘达利亚的古老水池。', `MaleText_loc5`='我們在這湖上居住了數千年之久。這裡的水是從潘達利亞的古老池裡流淌下來的。', `MaleText_loc7`='Hemos vivido en este lago desde hace miles de años. Estas aguas fluyen desde los estanques más antiguos de Pandaria.' WHERE `ID`=55407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 해주신 일에 대해 부족 전체가 감사하고 있습니다, $n 님.', `MaleText_loc4`='我们整个部落都十分感激你善行，$n。', `MaleText_loc5`='部族感謝你的功績，$n。', `MaleText_loc7`='La tribu agradece tu ayuda, $n.' WHERE `ID`=55408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인의 말을 모두 믿는 것은 어리석은 일입니다. 하지만 친구일 수 있는 이들까지 거부하는 것 또한 어리석은 일입니다.', `MaleText_loc4`='无条件相信陌生人的话是愚蠢的，但拒绝潜在的朋友也是愚蠢的。', `MaleText_loc5`='完全相信一個陌生人所說的每一句話是愚蠢的行為，但是拒絕可能成為朋友的人也是愚蠢的行為。', `MaleText_loc7`='Es de necios confiar en todo lo que dice un desconocido, pero también es de necios rechazar a los posibles amigos.' WHERE `ID`=55409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물 같은 힘이 당신을 황혼 세계로 잡아끕니다!', `MaleText_loc4`='一股诡异的力量将你拉入了暮光领域！', `MaleText_loc5`='一股非人的力量將你扯進暮光國度!', `MaleText_loc7`='¡Una fuerza monstruosa te atrae hasta el Reino Crepuscular!' WHERE `ID`=55410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요, $p 님! 제가 풀려났습니다!', `MaleText_loc4`='你成功了，$p！我自由了！', `MaleText_loc5`='你成功了，$p!我自由了!', `MaleText_loc7`='¡Lo has conseguido, $p! ¡Soy libre!' WHERE `ID`=55411;
