UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리. 어려움에 처한 낯선 이는 훗날의 친구란다. 그게 바로 방랑자의 도리지!', `MaleText_loc4`='丽丽。今天的陌生人就是明天的朋友。这就是云游者之道！', `MaleText_loc5`='莉莉。一個需要幫助的陌生人，將成為未來的朋友。這就是浪人之道!', `MaleText_loc7`='Li Li, un desconocido en apuros es un futuro amigo. ¡Es la filosofía del viajero!' WHERE `ID`=55414;
