UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐, 스톰스타우트 양조장이라고요?', `FemaleText_loc4`='等等……你是说风暴烈酒酿造厂？', `FemaleText_loc5`='等等，你剛剛說風暴烈酒酒坊?', `FemaleText_loc7`='¿Acaso dijiste Cervecería del Trueno?' WHERE `ID`=55475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트 일가 사람을 아는가? 판다리아에서?', `MaleText_loc4`='你认识风暴烈酒家的人吗？在潘达利亚？', `MaleText_loc5`='你認識其他風暴烈酒家的人?在潘達利亞這裡?', `MaleText_loc7`='¿Conoces a más Cerveza de Trueno? ¿Aquí, en Pandaria?' WHERE `ID`=55476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 물론이죠! 이 계곡에서 가장 큰 양조장을 가진 양조 가문이니까요!', `MaleText_loc4`='嘁，当然了！他们可是整个四风谷最大的酿酒家族！', `MaleText_loc5`='喔，當然囉!他們是整個山谷最大的釀酒家族!', `MaleText_loc7`='¡Caray, claro! ¡Son la familia cervecera más importante de todo el valle!' WHERE `ID`=55477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조장이라고... 우리 가문... 우리 조상의 고향이야!', `MaleText_loc4`='酿酒厂……我的家人……我祖先的家园！', `MaleText_loc5`='酒坊...我的家人...我的老家!', `MaleText_loc7`='Una cervecería... mi familia... ¡mi hogar ancestral!' WHERE `ID`=55478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 당신 스톰스타우트 가문이신가요?', `MaleText_loc4`='等等——你是风暴烈酒家族的？', `MaleText_loc5`='等等，你是風暴烈酒家的?', `MaleText_loc7`='Espera un momento... ¿tú eres un Cerveza de Trueno?' WHERE `ID`=55479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇네... "스톰스타우트 양조장"이란 곳이 어디인가? 내 눈으로 봐야만 하겠네!', `MaleText_loc4`='对，对。告诉我——这个“风暴烈酒酿造厂”在哪里？我得亲自去看看！', `MaleText_loc5`='是的，我是。告訴我，「風暴烈酒酒坊」在哪裡?我必須親眼看看!', `MaleText_loc7`='Así es. Cuéntame, ¿dónde está esa "Cervecería del Trueno"? ¡Tengo que verla con mis propios ojos!' WHERE `ID`=55480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 길로 쭉 따라가면 됩니다. 그런데...', `MaleText_loc4`='沿着这条路往下走就是了，但是……', `MaleText_loc5`='你只要順著這條路走下去就好，不過...', `MaleText_loc7`='Solo tienes que seguir este camino, pero...' WHERE `ID`=55481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 가 봐야겠네. 리 리... 넌 여기 있거라. 갔다 오마.', `MaleText_loc4`='我走了。丽丽……你留在这儿。我会回来找你的。', `MaleText_loc5`='我要去了。莉莉...妳在這裡等著。我會回來找你。', `MaleText_loc7`='Me voy. Li Li... tú quédate aquí. Volveré por ti.' WHERE `ID`=55482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 없는 동안 말썽 피우지 말고. 알겠지?', `MaleText_loc4`='答应我，我不在时，你可不要惹麻烦啊。', `MaleText_loc5`='答應我，我不在時妳會好好保護自己?', `MaleText_loc7`='Prométeme que no te meterás en líos en mi ausencia.' WHERE `ID`=55483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 네, 물론이죠. 네.', `FemaleText_loc4`='我……好的，当然了。去吧。', `FemaleText_loc5`='我...行啊，當然。隨便啦。', `FemaleText_loc7`='Eh... sí, claro. Lo que tú digas.' WHERE `ID`=55484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 이상한 아저씨한테 날 맡기다니.', `FemaleText_loc4`='他居然把我丢给这个怪泥盏了。', `FemaleText_loc5`='他居然把我留下來跟個奇怪的泥巴傢伙在一起。', `FemaleText_loc7`='No puedo creer que me haya dejado con este tipo raro y fangoso.' WHERE `ID`=55485;
