UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새벽의 꽃으로 뛰어가! 거기서 만나자!', `FemaleText_loc4`='快去晨芳园。我们会在那里等你的！', `FemaleText_loc5`='趕快到晨綻去。我們在那裡和你會合!', `FemaleText_loc7`='Ve a Floralba. ¡Te veremos allí!' WHERE `ID`=55499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 그렇게 높이 올라갔던 거야?', `FemaleText_loc4`='你是怎么爬到那么高的地方的？', `FemaleText_loc5`='你怎麼跑那麼高的?', `FemaleText_loc7`='¿Cómo has subido hasta ahí?' WHERE `ID`=55500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나 정말 멋진 용사님과 함께 왔지? 안 그래?', `FemaleText_loc4`='我给我们找了个很酷的保镖，是不是？', `FemaleText_loc5`='我給我們找了個很酷的保鏢，對吧?', `FemaleText_loc7`='¿A que he encontrado un guardaespaldas genial?' WHERE `ID`=55501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 다가가라. 적의 범위 안으로 파고들라고. 주도권을 주지 마!', `MaleText_loc4`='靠近点。深入他的空间。别让他掌握主动！', `MaleText_loc5`='靠近一點。在他的位置攻擊。不要讓他先發制人!', `MaleText_loc7`='Acércate. Invade su espacio. ¡No le concedas la iniciativa!' WHERE `ID`=55502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다양한 공격을 구사해라. 일정한 공격 유형이 있는 것처럼 보여선 안 돼. 적의 직감이 틀렸다는 걸 보여주라고.', `MaleText_loc4`='你要尽量使自己的进攻多样化，别让对手摸清你的套路，证明他的直觉是错的。', `MaleText_loc5`='改變進攻方式。讓你的對手找不到模式。證明他的本能出了錯。', `MaleText_loc7`='Varía tus golpes. No permitas que tu adversario descubra una pauta. Demuéstrale que sus instintos le engañan.' WHERE `ID`=55503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날만 사용하려고 하지 마라. 손잡이 끝 부분도 써 보라고. 적의 코를 부러뜨리는 거야!', `MaleText_loc4`='别只知道用武器的锋刃部分。用用武器的柄，砸扁他的鼻子！', `MaleText_loc5`='不要只用刀鋒。使用你武器的柄。打斷他的鼻樑!', `MaleText_loc7`='No utilices solo la hoja. Usa también la empuñadura. ¡Rómpele la nariz!' WHERE `ID`=55504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매서운 눈빛 좀 보고 싶군. 노려보라고. 더 매섭게! 지금 그게 노려보는 건가?', `MaleText_loc4`='让我看看你发皱眉的样子吧。皱眉。用力皱眉！你管这叫皱眉？', `MaleText_loc5`='讓我看你們生氣的樣子。生氣。再生氣點。你這樣叫生氣的臉?', `MaleText_loc7`='¡Deja que vea tu rabia! ¡Más rabia! ¿A eso le llamas tú fruncir el ceño?' WHERE `ID`=55505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들의 목표는 적이 아무 소리도 못 내게 순식간에 죽이는 것이다. 하지만 상황이 안 좋으면 좀 시끄러워져도 할 수 없지.', `MaleText_loc4`='你的目标是消无声息地干掉对方。不到万不得已，别搞出太大的动静。', `MaleText_loc5`='你的目標是安靜的擊殺。真的不行的話，有慘叫聲也行。', `MaleText_loc7`='Tu objetivo es conseguir una muerte silenciosa. Pero en un aprieto, las muertes escandalosas y furibundas también nos valen.' WHERE `ID`=55506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정강이, 얼굴, 사타구니. 가리지 말고 걷어차라.', `MaleText_loc4`='小腿，面部，胯部，随便踢。', `MaleText_loc5`='腳踝。臉部。褲檔。不用選，全部都踢。', `MaleText_loc7`='En la espinilla, en la cara, en la entrepierna. Lanza patadas de forma indiscriminada.' WHERE `ID`=55507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐 하는 건가? 춤추나? 우린 지금 전투를 연습하고 있다, 제군들! 하아... 두 명 더 들여보내.', `MaleText_loc4`='你在干什么呢，跳舞？我们在研究谋杀，伙计！呸——再带两个进来。', `MaleText_loc5`='你們在幹嘛，跳舞嗎?我們在學習謀殺耶!算了 - 再派兩個進去。', `MaleText_loc7`='¿Qué estáis haciendo, bailar? ¡Aquí estamos aprendiendo a matar, gente! BAH. ¡Que vengan dos más!' WHERE `ID`=55508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직임이 가볍고, 제멋대로고, 마구 늘어지는군... 그런 식으로는 순식간에 적에게 죽고 말걸. 썩 나와!', `MaleText_loc4`='你的行动轻率、随意、松散……你在瞬间就会被干掉。滚出去！', `MaleText_loc5`='你的動作很輕盈，自由，流暢...瞬間就會被殺。給我滾出來!', `MaleText_loc7`='Tus movimientos son débiles, sin determinación, sin fuerza... Te matarían al instante. ¡Sal del ring!' WHERE `ID`=55509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 건 마음에 드는군. 다들 잘 봤나? 다음은 누군가?', `MaleText_loc4`='我喜欢在这里看到的一切。大家都看见了吗？下一个是谁？', `MaleText_loc5`='我很喜歡目前看到的狀況。大家都有看到嗎?誰要下一個?', `MaleText_loc7`='Me gusta lo que veo por aquí. ¿Lo habéis visto todos? ¿Quién es el siguiente?' WHERE `ID`=55510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 그건 피인가? 아니면 이가 깨진 건가? 훌륭하군! 두 명 더 들여보내!', `MaleText_loc4`='很好。你牙上的是血吗？太好了！再送两个进来！', `MaleText_loc5`='很好。那是血嗎?在你牙齒上?很好!再來兩個!', `MaleText_loc7`='Muy bien. ¿Eso que tienes en el diente es sangre? ¡Estupendo! ¡Que vengan dos más!' WHERE `ID`=55511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 짝짓기하는 놀 두 마리 같군. 산만하고 엉성해. 아주 갈팡질팡하는군. 나와. 나오라고! 다음 사람?!', `MaleText_loc4`='呃，你战斗起来就像热锅上的豺狼人。心不在焉，鲁莽草率，乱七八糟。滚出去。出去！下一个！', `MaleText_loc5`='呃，你們打起來像兩個發情的狗頭人。漫不經心。懶散。亂七八糟。滾出去。滾!下一個呢?', `MaleText_loc7`='Uf, peleas como un par de gnolls en celo. Tienes la cabeza en las nubes, te falta técnica y eres torpe. Fuera. ¡LARGO! ¿Siguiente?' WHERE `ID`=55512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어, 우와! 그게 "어흥!"하니까 $g아저씨:아줌마;가 "으라차차!" 하시네요!', `FemaleText_loc4`='噢，哇！那真是太棒了！你真了不起！', `FemaleText_loc5`='哇塞!他們就像這樣「吼嗚嗚!」然後你就像這樣「呀喝!」', `FemaleText_loc7`='¡Guau! Ha sido como "¡Grrr!" y luego tú has hecho "¡Pum!".' WHERE `ID`=55513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게 그렇게 용감해지셨어요?', `FemaleText_loc4`='你为什么能那么勇敢呢？', `FemaleText_loc5`='你為什麼能這麼勇敢?', `FemaleText_loc7`='¿Cómo has llegado a ser tan valiente?' WHERE `ID`=55514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마녀가 제 친구들 잡아먹기 전에 $g아저씨:아줌마;가 쾅 때려주면 좋겠어요.', `FemaleText_loc4`='我真心希望，它在被你打跑之前，没吃过我的任何一个朋友。', `FemaleText_loc5`='希望在你打扁牠之前，牠還沒吃掉我的朋友。', `FemaleText_loc7`='Espero que no se comiera a ninguno de mis amigos antes de que le dieras una paliza.' WHERE `ID`=55515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목을 축이고 잠시 쉬어라, 여행자여.', `MaleText_loc4`='喝一杯休息一下吧，旅行者。', `MaleText_loc5`='喝杯酒休息吧，旅人。', `MaleText_loc7`='Bebe algo y descansa, $gviajero:viajera;.' WHERE `ID`=55516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 지내고 있나, $n?', `MaleText_loc4`='一切都还顺利吗，$n？', `MaleText_loc5`='一切都還舒適嗎，$n?', `MaleText_loc7`='¿Está todo a tu gusto, $n?' WHERE `ID`=55517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 엄호할게요, $p 님.', `FemaleText_loc4`='我会支持你的，$p。', `FemaleText_loc5`='我掩護你，$p。', `FemaleText_loc7`='Te cubro las espaldas, $p.' WHERE `ID`=55519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오게. 자네가 수련을 마치기 전에 마지막으로 함께 가야 할 곳이 있네.', `MaleText_loc4`='来吧，孩子。在你完成训练之前，我们还要同行最后一段旅程。', `MaleText_loc5`='來吧，孩子。在你的訓練結束之前，我們還有最後一段旅程要走。', `MaleText_loc7`='Vamos, joven. Tenemos que emprender un último viaje juntos para completar tu entrenamiento.' WHERE `ID`=55520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로의 길을 지나면 지팡이의 숲이 나온다네. 자격이 있는 자만 들어갈 수 있는 신성한 곳이지.', `MaleText_loc4`='长者之路的尽头就是禅杖林，只有最杰出的熊猫人才能进入这片圣地。', `MaleText_loc5`='長者之路的彼端就是杖木林，那是只有具備資格者才能進入的神聖之地。', `MaleText_loc7`='Más allá de El Camino de los Ancestros está El Bosque de Bastones, un lugar sagrado al que solo acceden los dignos.' WHERE `ID`=55521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자격을 증명하는 방법은 여러 가지가 있네만, 가장 단순한 방법으로 하겠네. 자네가 민족을 위해 싸울 의지가 있는지, 민족의 안전을 지킬 수 있는지 알아야겠네.', `MaleText_loc4`='要证明自己，方法有很多，而我的要求是最简单的。我必须知道，你是否愿意为族人而战；你是否有能力来保护他们。', `MaleText_loc5`='我只需要你用最簡單的方式來證明自己。我必須知道你會為我們的人民而戰。我必須知道你能保護他們。', `MaleText_loc7`='Aunque hay muchas formas de que demuestres tu valía, yo te exijo la más sencilla. He de saber que lucharás por nuestro pueblo y que lo mantendrás a salvo.' WHERE `ID`=55522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로의 수호자를 쓰러뜨리면 지나갈 수 있네.', `MaleText_loc4`='击败长者的卫士，我们才能通过。', `MaleText_loc5`='擊敗長者守護者，我們就能通過。', `MaleText_loc7`='Derrota al Guardián de los Ancestros, y podremos pasar.' WHERE `ID`=55523;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 처치하려던 참이었어요, $p 님!', `FemaleText_loc4`='嘿！别跟我抢人头啊，$p！', `FemaleText_loc5`='嘿!別搶我的獵物，$p!', `FemaleText_loc7`='¡Oye! ¡Deja de robarme las víctimas, $p!' WHERE `ID`=55524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님, 제 사냥감이었다고요!', `FemaleText_loc4`='那个是我杀的，$p！', `FemaleText_loc5`='那是我要殺的，$p!', `FemaleText_loc7`='¡Ese era mío, $p!' WHERE `ID`=55525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 조준하고 있던 놈이었는데!', `FemaleText_loc4`='那是我先看见的！', `FemaleText_loc5`='我先看到那傢伙的!', `FemaleText_loc7`='¡A ese lo estaba apuntando yo!' WHERE `ID`=55526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적은 안 그래도 많은데 왜 제가 노린 걸 건드리시나요...', `FemaleText_loc4`='外面的对手足够我们杀的了……', `FemaleText_loc5`='這裡有足夠我們兩人的目標好嗎...', `FemaleText_loc7`='Hay objetivos de sobra para todos...' WHERE `ID`=55527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 3천 년 동안 민족의 지혜를 계승했다네. 늙은이에게서 젊은이에게로, 또 사부에게서 제자에게로.', `MaleText_loc4`='三千年来，这些智慧在我们中间代代相传，长幼相继，师徒相承。', `MaleText_loc5`='三千年來，我們的知識代代相傳。長者傳給幼兒，師傅傳給弟子。', `MaleText_loc7`='Durante 3,000 años, hemos transmitido el saber de nuestro pueblo. De ancestro a joven. De maestro a estudiante.' WHERE `ID`=55528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은이는 모두 떠나야 할 날이 온다네. 그날 자기 지팡이를 조상의 지팡이 사이에 꽂지. 오늘이 내 지팡이가 이 숲에 꽂히는 날일세.', `MaleText_loc4`='每位长者都会有离世的一天。在那之前，他必须将自己的禅杖和祖先们的种在一起。今天，我的禅杖也将种入此林。', `MaleText_loc5`='每位長者都有一天會卸下重擔，他們會將手杖立在祖先的手杖旁。今天就是我的手杖加入這片樹林的日子。', `MaleText_loc7`='Para todo viejo maestro llega el día en que debe partir y dejar su bastón junto a los de sus ancestros. Hoy es el día que mi bastón se une al bosque.' WHERE `ID`=55529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 민족은 대대손손 이 거대한 거북 셴진 수 위에 살아 왔다네. 하지만 수백 년 동안 아무도 그와 이야기를 한 적이 없지.', `MaleText_loc4`='$p，我们的人民终生居住在这只巨大的神龟——神真子的背上。但数百年来，没有人与它交谈过。', `MaleText_loc5`='$p，我們的人民畢生都生活在神真子這位偉大神龜的背上，但是已經有幾百年沒人跟他說過話。', `MaleText_loc7`='Nuestro pueblo ha vivido durante generaciones sobre Shen-zin Su, la gran tortuga, pero en cientos de años nadie ha hablado con él.' WHERE `ID`=55530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 셴진 수가 아프고, 우리 모두가 위험하다네. 정령들의 도움을 받으면 오랜 침묵을 깰 수가 있네. 자네가 거북과 이야기를 하게.', `MaleText_loc4`='现在，神真子病了，我们都处在危险之中。有了元素之灵的帮助，你将打破这种沉默，聆听它的诉说。', `MaleText_loc5`='神真子病了，我們全都因此身處險境。透過元素的幫助，你便能打破這段沉默。去和神真子交談吧。', `MaleText_loc7`='Ahora Shen-zin Su está enfermo y todos corremos peligro. Con la ayuda de los elementos, podrás romper el silencio y hablar con él.' WHERE `ID`=55531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이사와 지가 네 정령을 이곳으로 데리고 왔다네. 함께 가서 위대한 셴진 수와 이야기를 하고, 우리 민족을 구할 길이 있다면 그대로 따르게.', `MaleText_loc4`='艾莎和季已经把元素之灵接来了。你要跟他们一起去觐见伟大的神真子，并尽你所能拯救我们的人民。', `MaleText_loc5`='艾莎跟紀把元素之靈們帶來這裡了。跟他們一起去吧，去找偉大的神真子交談，並且盡一切的努力拯救我們的同胞。', `MaleText_loc7`='Aysa y Ji han traído a los espíritus. Debes ir con ellos, hablar con el grandioso Shen-zin Su y hacer lo que sea necesario para salvar a nuestro pueblo.' WHERE `ID`=55532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 먼 길을 왔네, 젊은 제자여. 자네에게서는 영웅의 싹이 보이네. 이 땅의 운명을 자네에게 맡기겠네.', `MaleText_loc4`='你功不可没，年轻的徒儿。看得出来，你有一颗英雄的心。这片土地的未来就托付给你了。', `MaleText_loc5`='你通過了重重考驗，我年輕的徒弟。我在你身上看見英雄的潛力。這座島的命運就交給你了。', `MaleText_loc7`='Has llegado lejos, joven. Veo grandeza en tu interior. Dejo en tus manos el destino de esta tierra.' WHERE `ID`=55533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?! 말도 안 돼!', `MaleText_loc4`='什么？！那不可能！', `MaleText_loc5`='什麼?!不可能!', `MaleText_loc7`='¿Cómo? ¡Imposible!' WHERE `ID`=55534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s|1이;가; |cFFFF0000|Hspell:106523|h[대격변]|h|r을 시전합니다! 막아야 합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s开始施放|cFFFF0000|Hspell:106523|h[大灾变]|h|r！快阻止他！', `MaleText_loc5`='|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s開始施放|cFFFF0000|Hspell:106523|h[災變]|h|r!阻止他!', `MaleText_loc7`='|TInterfaceIconsability_deathwing_cataclysm.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:106523|h[Cataclismo]|h|r! ¡Hay que detenerlo!' WHERE `ID`=55535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 영혼아, 그 몸 속에 숨을 수는 없다!', `MaleText_loc4`='渺小的灵魂，你带着那个躯壳是逃不出我的掌心的！', `MaleText_loc5`='小小的魂靈，你躲在那身體裡是逃不過我的!', `MaleText_loc7`='Pequeño espíritu, no puedes esconderte de mí en ese cuerpo.' WHERE `ID`=55536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시는 방해하지 못할 것이다!', `MaleText_loc4`='你休想再来捣乱！', `MaleText_loc5`='不准你再來礙事!', `MaleText_loc7`='¡No volverás a inmiscuirte!' WHERE `ID`=55537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리가 뻣뻣해요.', `MaleText_loc4`='我的腿都僵了。', `MaleText_loc5`='我的腿感覺好硬。', `MaleText_loc7`='Tengo las patas rígidas.' WHERE `ID`=55538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야호! 우리가 해냈어!', `MaleText_loc4`='哇！我们成功了！', `MaleText_loc5`='喔耶!我們成功了!', `MaleText_loc7`='¡Yujuu! ¡Lo conseguimos!' WHERE `ID`=55539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요, $p 님!', `FemaleText_loc4`='干得好，$p！', `FemaleText_loc5`='做得好，$p!', `FemaleText_loc7`='¡Bien hecho, $p!' WHERE `ID`=55540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나비야, 이리 온.', `FemaleText_loc4`='过来，小猫咪。', `FemaleText_loc5`='來啊小貓咪!', `FemaleText_loc7`='Ven, gatito, gatito.' WHERE `ID`=55541;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너도 이제 우리 가족이 되렴... 비취가 되어 영원히!', `FemaleText_loc4`='你应该被变成玉雕，永远加入我们的大家庭。', `FemaleText_loc5`='你應該加入我的家族，像翠玉永遠保存。', `FemaleText_loc7`='Deberías unirte a nuestra familia, conservada eternamente en jade.' WHERE `ID`=55542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이얏호! 신! 너 살아 있었구나!', `FemaleText_loc4`='耶！阿信！你还活着！', `FemaleText_loc5`='耶!小新!你還活著!', `FemaleText_loc7`='¡Sí! ¡Shin! ¡Estás vivo!' WHERE `ID`=55543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각했던 대로야...', `MaleText_loc4`='我就知道……', `MaleText_loc5`='跟我想的一樣...', `MaleText_loc7`='Tal y como esperaba...' WHERE `ID`=55544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 이제 전투 준비가 끝났습니다.', `MaleText_loc4`='是的！我做好战斗的准备了。', `MaleText_loc5`='太好了!我現在準備好戰鬥了!', `MaleText_loc7`='¡Sí! Y ahora estoy listo para el combate.' WHERE `ID`=55545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 고마워요, $p 님! 새벽의 꽃에서 뵐게요. 전에 탐험할 때 발견한 멋진 물건 중에서 하나를 선물로 드리고 싶어요!', `FemaleText_loc4`='太感谢你了， $p！你等下到晨芳园来找我，我会送你一件我们为探险准备的东西的。', `FemaleText_loc5`='真是謝謝你，$p!如果你晚點在晨綻遇到我，我會給你一個我們冒險中拿到的東西。', `FemaleText_loc7`='¡Muchísimas gracias, $p! Si vienes a verme en Floralba más tarde, te daré un recuerdo que conservamos de nuestras aventuras.' WHERE `ID`=55546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 술 마시러 갑시다.', `MaleText_loc4`='走，我们去喝一杯。', `MaleText_loc5`='當然，來喝一杯吧。', `MaleText_loc7`='Claro, vamos a echar un trago.', `FemaleText_loc1`='물론이죠. 술 마시러 가요.', `FemaleText_loc4`='走，我们去喝一杯。', `FemaleText_loc5`='當然，來喝一杯吧。', `FemaleText_loc7`='Claro, vamos a echar un trago.' WHERE `ID`=55547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 좀 봐!', `MaleText_loc4`='$p！来看看这个！', `MaleText_loc5`='$p!看看這個東西!', `MaleText_loc7`='¡Vaya, mira eso!' WHERE `ID`=55548;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비되는 대로 출발하지요.', `FemaleText_loc4`='等你准备好了我们就出发，$n。', `FemaleText_loc5`='我們已準備好和你一起行動，$n。', `FemaleText_loc7`='Estamos listos para partir.' WHERE `ID`=55549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리우 랑의 후손들이 나를 잊지 않았다니 고통스러운 중에도 마음이 따뜻해지는구나.', `MaleText_loc4`='我正遭受痛苦的折磨，但刘浪的子孙们没有忘记我，值得欣慰。', `MaleText_loc5`='我很痛苦，但我感到欣慰。劉浪的子孫還記得我。', `MaleText_loc7`='A pesar del dolor, me llena de felicidad saber que los hijos de Liu Lang no me han olvidado.' WHERE `ID`=55550;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타시죠.', `FemaleText_loc4`='跳进去。', `FemaleText_loc5`='上來吧。', `FemaleText_loc7`='Sube.' WHERE `ID`=55551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 숲을 산책하고 싶으면, 나는 아이사랑 여기 있을게. 알겠지...? 단 둘이서 말이야.', `MaleText_loc4`='如果你想在林子里逛逛，艾莎和我可以在这里等着。我是说…就我们俩。', `MaleText_loc5`='你想去林子那邊逛逛的話，艾莎和我可以待在這裡。你知道的...「獨處」一下。', `MaleText_loc7`='O, si quieres dar un paseo por el bosque, Aysa y yo podemos esperarte aquí. Ya sabes... los dos solos.' WHERE `ID`=55552;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지는 무시하세요. 우린 할 일이 있습니다.', `FemaleText_loc4`='别听他的。我们还有事要做呢。', `FemaleText_loc5`='別聽他的。我們還有工作要做。', `FemaleText_loc7`='No le hagas caso. Tenemos mucho que hacer.' WHERE `ID`=55553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부님은 어디 계셔?', `MaleText_loc4`='$p，尚师父呢？', `MaleText_loc5`='$p，尚羲大師在哪裡?', `MaleText_loc7`='¿Y el maestro Shang?' WHERE `ID`=55554;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 지, 사부님은 지팡이의 숲에 가셨잖아요. 그게 무슨 뜻이겠어요.', `FemaleText_loc4`='……季，他们去了禅杖林。你应该明白尚师父去哪了……', `FemaleText_loc5`='...紀，他們來過杖木林。你知道尚羲大師現在在哪裡。', `FemaleText_loc7`='... Ji, estaban en El Bosque de Bastones, así que ya sabes dónde está el maestro Shang.' WHERE `ID`=55555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그렇게 희망을 짓밟지 마요. 사부님이 보고 싶을 거란 말이에요.', `MaleText_loc4`='唉，就不能让我心存侥幸吗？我会想念那老头儿的。', `MaleText_loc5`='唉，就不能讓熊貓人抱點希望嗎?我會懷念這老傢伙的。', `MaleText_loc7`='Bah, deja que sueñe un poco, ¿vale? Voy a echar de menos al viejo.' WHERE `ID`=55556;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앗! 저 폭포 좀 봐요!', `FemaleText_loc4`='嘿！看那道瀑布！', `FemaleText_loc5`='嘿!看看那個瀑布!', `FemaleText_loc7`='¡Eh! ¡Mira esa catarata!' WHERE `ID`=55557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤에 동굴이 있을까요?', `FemaleText_loc4`='我在想它后面会不会有个洞。', `FemaleText_loc5`='我懷疑那後面可能有個洞穴。', `FemaleText_loc7`='Quizá haya una cueva detrás...' WHERE `ID`=55558;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭포가 있으면 뒤에 동굴이 없는지 꼭 봐야 돼요.', `FemaleText_loc4`='见到瀑布你就应该去看看它后面有没有洞穴。', `FemaleText_loc5`='你每次看到瀑布都應該檢查裡頭有沒有洞穴。', `FemaleText_loc7`='Siempre se debe mirar detrás de las cataratas por si hay cuevas.' WHERE `ID`=55559;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지, 셴진 수와 이야기할 때는 공손해야 해요.', `FemaleText_loc4`='季，与神真子交谈的时候，应该保持恭敬。', `FemaleText_loc5`='紀，跟神真子交談時不得失禮。', `FemaleText_loc7`='Ji, sé respetuoso cuando hablemos con Shen-zin Su.' WHERE `ID`=55560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 언제는 안 공손했나요? 나 상처 받았어요, 아이사.', `MaleText_loc4`='我哪里不恭敬了？我太伤心了，艾莎。', `MaleText_loc5`='我什麼時候失禮了?我這樣很受傷欸，艾莎。', `MaleText_loc7`='¿Cuándo no lo soy? Tus palabras me hieren, Aysa.' WHERE `ID`=55561;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자꾸 창피하게 굴면, 각오해요.', `FemaleText_loc4`='你的无礼才让我伤心。', `FemaleText_loc5`='你敢讓我們丟臉，就真的要受傷了。', `FemaleText_loc7`='No nos avergüences, o te heriré de verdad.' WHERE `ID`=55562;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셴진 수, 저희는 리우 랑의 후손입니다. 당신의 고통을 알고, 돕고자 왔습니다.', `FemaleText_loc4`='神真子，我们是刘浪的后人。我们感到您很痛苦，我们想帮您。', `FemaleText_loc5`='神真子，我們是劉浪的後代。我們感受到您的痛苦，我們想要幫忙。', `FemaleText_loc7`='Shen-zin Su, somos los descendientes de Liu Lang. Hemos sentido tu dolor y queremos ayudarte.' WHERE `ID`=55563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇 때문에 괴로우십니까? 저희가 어떻게 해야 할까요?', `FemaleText_loc4`='您怎么了，神真子？我们该怎么做？', `FemaleText_loc5`='什麼東西讓您痛苦，神真子?我們能怎麼做?', `FemaleText_loc7`='¿Qué te aflige? ¿Qué podemos hacer por ti?' WHERE `ID`=55564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 멋진 비단 좀 보세요!', `FemaleText_loc4`='看看这些上好的丝绸！', `FemaleText_loc5`='看吶，有那麼多的蠶絲!', `FemaleText_loc7`='¡Mira esta seda preciosa!' WHERE `ID`=55565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 정말로 누에 꽁무니에서 나오는 걸까요?', `FemaleText_loc4`='这东西真是从蚕的屁股里出来的吗？', `FemaleText_loc5`='你覺得他們真的是從蠶的屁屁拿到這玩意兒的嗎?', `FemaleText_loc7`='¿De verdad crees que sacaron todo esto del trasero de los gusanos de seda?' WHERE `ID`=55566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='웩... 구더기 같아.', `FemaleText_loc4`='呃……它们看起来像蛆虫。', `FemaleText_loc5`='噁...他們看起來像蛆一樣。', `FemaleText_loc7`='Puaj... parecen orugas.' WHERE `ID`=55567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옆구리에 가시가 박혔는데, 뺄 수가 없다.', `MaleText_loc4`='我的身体上扎进了一根刺。我没法拔掉它。', `MaleText_loc5`='我的背上有根刺。我沒辦法拔掉它。', `MaleText_loc7`='Tengo una espina en el costado. No me la puedo quitar.' WHERE `ID`=55568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 고통스러워서 참을 수가 없다. 똑바로 헤엄칠 수가 없어.', `MaleText_loc4`='疼痛难当，我已经快游不动了。', `MaleText_loc5`='這痛苦非常難以忍受，讓我沒辦法繼續往前游。', `MaleText_loc7`='El dolor es insoportable, y ya no puedo nadar bien.' WHERE `ID`=55569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후손들이여, 부디 이 가시를 빼 주겠나? 나 혼자서는 뺄 수가 없다.', `MaleText_loc4`='孩子们，你们能帮我拔掉这根刺吗？我对此无能为力。', `MaleText_loc5`='拜託了，孩子們。幫我移除這根刺。我沒辦法自己做到。', `MaleText_loc7`='Por favor, hijos, ¿pueden quitarme esta espina? Yo solo no puedo.' WHERE `ID`=55570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지요, 셴진 수! 하지만 당신의 넓은 등딱지 어디에 가시가 있는지 저는 모릅니다.', `FemaleText_loc4`='当然，神真子！可您的壳太大了，我不知道这根刺在哪儿。', `FemaleText_loc5`='當然了，神真子!但您的殼太大了，我不知道這根刺到底在哪。', `FemaleText_loc7`='Claro, Shen-zin Su, pero tu caparazón es enorme y no sabemos dónde podría estar.' WHERE `ID`=55571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 발이 닿지 않는 숲 속에 있다. 산맥을 따라 계속 가다 보면 찾을 수 있을 것이다.', `MaleText_loc4`='它就在你从未踏足过的森林中。沿着山脉走，你就能找到它。', `MaleText_loc5`='就在你們從不踏足的那片森林。不斷沿著山脈走，你們就會看到。', `MaleText_loc7`='Está en el bosque por el que sus pies no caminan. Sigan las montañas y la encontrarán.' WHERE `ID`=55572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희가 찾아서 제거하겠습니다. 약속합니다!', `FemaleText_loc4`='我们会找到它然后拔掉它的，我们向您保证！', `FemaleText_loc5`='我們會找到它，然後拔掉它的!我們向您保證!', `FemaleText_loc7`='La encontraremos y te la quitaremos. Tienes nuestra palabra.' WHERE `ID`=55573;
