UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 뭐길래 이런 덩치가 그렇게 아파하는 거지?', `MaleText_loc4`='小小一根刺怎么会让那么大的东西受苦呢？', `MaleText_loc5`='這種小玩意怎麼能讓那麼大的東西感到痛苦?', `MaleText_loc7`='¿Cómo es posible que algo tan inmenso sufra por tal nimiedad?' WHERE `ID`=55575;
