UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈이 이상한 건가?! 저거, 배야?!', `MaleText_loc4`='我该不会是眼花了吧？！那是一艘船？！', `MaleText_loc5`='你也看到了嗎?!那是艘船嗎?!', `MaleText_loc7`='¿Pero tú ves lo que yo veo? ¡¿Eso es un barco?!' WHERE `ID`=55577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞네요. 비행선입니다. 생각보다는 큰 가시군요.', `FemaleText_loc4`='这是一艘船。一整艘飞船。这“刺”可比我想象的大多了。', `FemaleText_loc5`='是一艘船沒錯...一整艘飛船!好大的一根刺啊。', `FemaleText_loc7`='Lo es. Una nave entera. Esta "espina" es más grande de lo que esperaba.' WHERE `ID`=55578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가 저 녀석들, 판다렌이 아냐. 털이 없어.', `MaleText_loc4`='而且那些不是熊猫人。他们身上不长毛。', `MaleText_loc5`='下面那些也不是熊貓人，他們身上可沒長毛。', `MaleText_loc7`='Y esos de ahí abajo no son pandaren. No tienen pelaje.' WHERE `ID`=55579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난파한 모양이야. 나쁜 짓 하러 온 거 같진 않은데.', `MaleText_loc4`='他们应该不是来找麻烦的，他们的飞船坠毁了。', `MaleText_loc5`='他們好像墜毀了。我想他們不是來找麻煩的。', `MaleText_loc7`='Parece que se han estrellado. Dudo que vengan buscando jaleo.' WHERE `ID`=55580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 우리 섬에 부딪혀 난파했습니다. 아무래도 가시를 빼기가 쉽지 않겠습니다.', `FemaleText_loc4`='飞船失事，一定有人在这座岛上遇难了。看来要拔掉这根刺绝非易事。', `FemaleText_loc5`='有人墜毀在這座島上。要拔除這根刺恐怕沒那麼容易。', `FemaleText_loc7`='Alguien se ha estrellado contra la isla. Sacar esta espina va a ser más complicado de lo que pensábamos.' WHERE `ID`=55581;
