UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까, 첸 님?', `MaleText_loc4`='发生什么事啦，陈？', `MaleText_loc5`='發生什麼事了，老陳?', `MaleText_loc7`='¿Qué ha ocurrido, Chen?', `FemaleText_loc1`='무슨 일인가요, 첸 님?', `FemaleText_loc4`='发生什么事啦，陈？', `FemaleText_loc5`='發生什麼事了，老陳?', `FemaleText_loc7`='¿Qué ha ocurrido, Chen?' WHERE `ID`=55596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 투사입니다. 장로님께서는 왜 절 싸우지 못하게 하시는 걸까요?', `MaleText_loc4`='我是个战士。为什么长老不让我战斗？', `MaleText_loc5`='我是個戰士。為什麼長者不讓我戰鬥?', `MaleText_loc7`='Soy un luchador. ¿Por qué no me deja luchar el ancestro?' WHERE `ID`=55597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일 우리는 호젠을 겨우 막아낼 만큼만 병력을 파견합니다. 적을 밀어낼 만큼 많은 수가 나서는 법은 없습니다.', `MaleText_loc4`='每天，我们派出的战士只能勉强阻挡住那些猢狲。我们的人手根本不足以发起反击。', `MaleText_loc5`='每天，我們只派出僅堪擋住猴人攻勢的戰士，數量從未多到足以將他們真正擊退。', `MaleText_loc7`='Cada día enviamos solo a los guerreros que hacen falta para mantener a raya a los hozen. Nunca los suficientes como para hacerlos retroceder.' WHERE `ID`=55598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루 장로님께서 우리가 호젠과 제대로 싸우지 못하게 막으시는 이유가 뭘까요?', `MaleText_loc4`='为什么长老卢山不让我们反击猢狲呢？', `MaleText_loc5`='為什麼長者廬不讓我們好好擊退猴人?', `MaleText_loc7`='¿Por qué no nos deja el ancestro Lu luchar contra los hozen como es debido?' WHERE `ID`=55599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 좀 바쁘다는 걸 모르시겠습니까?', `MaleText_loc4`='你没看到我正忙着吗？', `MaleText_loc5`='你看不見我正有點忙嗎?', `MaleText_loc7`='¿No ves que estoy algo ocupado?' WHERE `ID`=55600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 호젠은 나무들 사이로 마치 유령처럼 움직입니다!', `MaleText_loc4`='这些该死的猢狲在树林里就像幽灵一样神出鬼没！', `MaleText_loc5`='該死的猴人在樹上移動起來像鬼魅一樣!', `MaleText_loc7`='¡Malditos hozen! Se mueven entre las ramas como fantasmas.' WHERE `ID`=55601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달빛물 은거지를 되찾는 것도 시간 문제입니다.', `MaleText_loc4`='我们夺回月水庄只是时间问题。', `MaleText_loc5`='收復月水居只是時間的問題。', `MaleText_loc7`='Es cuestión de tiempo que retomemos el Retiro Agualuna.' WHERE `ID`=55602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠에 당당히 맞서 싸워야 합니다. 두려움에 사로잡혀 이렇게 피하기만 해서는 안 됩니다.', `MaleText_loc4`='我们应该跟猢狲干到底，而不是恐惧退缩。', `MaleText_loc5`='我們該正面迎戰猴人，而不是因恐懼猶疑不前。', `MaleText_loc7`='Deberíamos contraatacar a los hozen, no quedarnos paralizados de miedo.' WHERE `ID`=55603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님의 말씀이 옳습니다. 호젠과의 문제에서 외교적인 해결책을 찾아야 합니다.', `MaleText_loc4`='长老是对的，我们应该用外交手段解决和猢狲的争端。', `MaleText_loc5`='長者是對的，我們應該用外交手段解決和猴人之間的問題。', `MaleText_loc7`='El ancestro tiene razón; deberíamos encontrar una solución diplomática al conflicto con los hozen.' WHERE `ID`=55604;
