UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 풀어주시는 편이 좋을 겁니다. 저희 아버지는 저처럼 너그럽지 않으시거든요.', `MaleText_loc4`='我建议你们放了我。我父亲可没我这么宽容。', `MaleText_loc5`='我建議你們放我走，我的父親不像我這麼好說話。', `MaleText_loc7`='Te recomiendo que me liberes. Mi padre no es tan comprensivo como yo.' WHERE `ID`=55675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 대신 나즈그림 장군에게 이야기 좀 해주실 수 없겠습니까? 저하고는 협상할 생각이 없는 것 같더라고요.', `MaleText_loc4`='要不你帮我跟纳兹戈林谈谈？他似乎不太愿意跟我交涉。', `MaleText_loc5`='也許你可以替我和納茲格寧姆談談?他似乎沒意思和我談判。', `MaleText_loc7`='¿Podrías hablar con Nazgrim de mi parte? No parece dispuesto a negociar conmigo.' WHERE `ID`=55676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 보십시오. 지금은 평화와 탐험에 대해 이야기해야 할 때입니다.', `MaleText_loc4`='看看这片土地。现在，该是探讨和平，探索秘境的时候了。', `MaleText_loc5`='看看這片土地。現在應該是議和與探索的時刻。', `MaleText_loc7`='Observa esta tierra. Es el momento de hablar de paz y exploración.' WHERE `ID`=55677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 동료들에게 연락을 한 번만 하게 해 준다면, 바로 제 석방을 위한 협상을 시작할 수 있을 것입니다.', `MaleText_loc4`='我敢肯定，只要你让我联系上我的同伴，我们就能对释放我的问题展开谈判了。', `MaleText_loc5`='如果你讓我和同伴們聯繫，我們一定可以展開讓我自由的談判。', `MaleText_loc7`='Estoy seguro de que si te pones en contacto con mis compañeros podremos comenzar a negociar mi liberación.' WHERE `ID`=55678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피바람을 불러 일으키자!', `MaleText_loc4`='鲜血与雷鸣！', `MaleText_loc5`='鮮血與雷霆!', `MaleText_loc7`='¡Sangre y truenos!' WHERE `ID`=55679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도끼에 표식을 하나 더 새겨야겠군.', `MaleText_loc4`='看来我的斧子上又要多一个缺口了。', `MaleText_loc5`='我的斧頭又多了道缺口。', `MaleText_loc7`='Otro tanto para mi hacha.' WHERE `ID`=55680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 된 적수를 보내 봐라!', `MaleText_loc4`='给我一场真正的挑战吧！', `MaleText_loc5`='給我來點真正的挑戰!', `MaleText_loc7`='¡Mandadme un desafío de verdad!' WHERE `ID`=55681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=55682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네. 지금은 손님을 받고 있지 않네.', `MaleText_loc4`='抱歉，我们现在不接待访客。', `MaleText_loc5`='抱歉，現在不開放遊客參觀。', `MaleText_loc7`='Lo siento, en este momento no aceptamos visitas.' WHERE `ID`=55683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 손님이 아닙니다. 첸 스톰스타...', `MaleText_loc4`='我可不是访客，我是陈·风暴……', `MaleText_loc5`='我不是遊客，我是老陳·風暴烈－', `MaleText_loc7`='No soy un visitante, soy Chen Cer…' WHERE `ID`=55684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나가주게.', `MaleText_loc4`='你快走吧。', `MaleText_loc5`='請離開。', `MaleText_loc7`='Deberías irte.' WHERE `ID`=55685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 우리는 가족입니다. 저도 스톰스타우트 일가예요. 유랑도에서 온!', `MaleText_loc4`='可我们是一家人啊！我也姓风暴烈酒！从迷踪岛来……', `MaleText_loc5`='但我們是一家人。我也是風暴烈酒的族人!來自漂流島...', `MaleText_loc7`='Pero somos familia. Soy un Cerveza de Trueno, de La Isla Errante...' WHERE `ID`=55686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀가 먹었나? 지금은 아무도 양조장에 들어갈 수 없어.', `MaleText_loc4`='你聋了吗？我们现在不会让任何人进酒厂的。', `MaleText_loc5`='你聾了嗎?現在不管是誰都不准進來。', `MaleText_loc7`='¿Estás sordo? Ahora mismo nadie puede entrar en la cervecería.' WHERE `ID`=55687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 그런 식으로 말씀하셔야 합니까?', `MaleText_loc4`='你怎么用这种态度和你的家人说话。', `MaleText_loc5`='不需要這樣跟我說話。', `MaleText_loc7`='No hace falta que me hables en ese tono.' WHERE `ID`=55688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 잠깐! 뒤에 저게 뭡니까!?', `MaleText_loc4`='等等——你身后是什么？！', `MaleText_loc5`='等等，你後面發生什麼事了!?', `MaleText_loc7`='Espera... ¿qué está pasando detrás de ti?' WHERE `ID`=55689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엉?! 아... 아무것도 아닐세! 당장 나가주게!', `MaleText_loc4`='嗯？！没……没东西啊！马上滚！', `MaleText_loc5`='嗯?那個...那個沒什麼!快點滾!', `MaleText_loc7`='¿Qué? Eso... ¡eso no es nada! ¡Y ahora LARGO!' WHERE `ID`=55690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 얘기 좀 합시다! 앉아서 얘기 좀 하자고요. 맥주라도 한잔 하면서...', `MaleText_loc4`='来，跟我谈谈吧！我们坐下来好好聊聊。一起喝一杯……', `MaleText_loc5`='來嘛，跟我說說話!我們坐下來聊聊嘛，我們可以一起喝杯啤酒啊...', `MaleText_loc7`='¡Ven! ¡Habla conmigo! Podemos sentarnos a charlar, tomarnos una cerveza...' WHERE `ID`=55691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 앉겠네. 말도 안 할 거고. 자네의 그 지긋지긋한 맥주도 싫어!', `MaleText_loc4`='我可不想陪你坐着说闲话。更不想喝你那些糟糕的啤酒！', `MaleText_loc5`='別賴在這裡，別跟我說話，也不要你糟透的啤酒!', `MaleText_loc7`='No nos sentaremos, no beberemos, ¡y no quiero tu horrible cerveza!' WHERE `ID`=55692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[이 대사는 잘렸습니다]', `MaleText_loc4`='[This line has been cut]', `MaleText_loc5`='[這條線已被切斷]', `MaleText_loc7`='[This line has been cut]' WHERE `ID`=55693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등 뒤에 저게 뭐지?!', `MaleText_loc4`='嘿，你身后是什么？！', `MaleText_loc5`='嘿，你後面是什麼?', `MaleText_loc7`='Oye, ¿qué es eso que hay detrás de ti?' WHERE `ID`=55694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 더 말해야 알아듣겠나... 어서 나가주게!', `MaleText_loc4`='你要我说多少遍啊……滚出去！', `MaleText_loc5`='我到底要告訴你多少次...給我滾!', `MaleText_loc7`='¿Cuántas veces te tengo que decir... QUE TE MARCHES?' WHERE `ID`=55695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 왜 그러십니까? 제가 잘못한 거라도 있습니까?', `MaleText_loc4`='我真是不明白啊，老头。我到底哪里惹到你了？', `MaleText_loc5`='我不明白，老頭。我做了什麼事惹到你了?', `MaleText_loc7`='No lo entiendo, anciano. ¿Qué he hecho para enfurecerte?' WHERE `ID`=55696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 잘못한 게 아니네. 바로 자네가 문제야. "첸 스톰스타우트."', `MaleText_loc4`='不论你做了什么，你的身份就惹到我了。这里不欢迎你，“陈·风暴烈酒”。', `MaleText_loc5`='不是因為你做了什麼，而是因為你。這裡不歡迎你，「老陳·風暴烈酒」。', `MaleText_loc7`='No se trata de lo que has hecho, sino de quién eres. No eres bienvenido aquí, "Chen Cerveza de Trueno".' WHERE `ID`=55697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조장을 발견하고 안으로 들어갔지.', `MaleText_loc4`='我找到了酿酒厂，然后走进去。', `MaleText_loc5`='我找到酒坊並設法進去裡頭。', `MaleText_loc7`='Encontré la cervecería y entré directamente.' WHERE `ID`=55698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고는 혹시 스톰스타우트 일가 사람이 있는지 둘러보기로 했단다.', `MaleText_loc4`='我决定在附近找找其他风暴烈酒家族的人。', `MaleText_loc5`='我決定四處找找，看有沒有風暴烈酒家族的其他成員。', `MaleText_loc7`='Decidí buscar a alguien más de la familia Cerveza de Trueno.' WHERE `ID`=55699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 충격 받았지만 포기하지 않았지. 그 묘한 양조장이에게 질문을 더 하려고 뒤를 따라갔어.', `MaleText_loc4`='我有些动摇，但并没有放弃。我跟上那个古怪的老酿酒师，想要追问他。', `MaleText_loc5`='我動搖了，但我沒有放棄。我追著那個奇怪的老釀酒師問他更多問題。', `MaleText_loc7`='Estaba preocupado, pero no me rendí. Seguí al viejo cervecero para hacerle algunas preguntas.' WHERE `ID`=55700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 정령에다, 이제는 호젠까지? 뭔가 심각하게 잘못돼 있었지.', `MaleText_loc4`='先是啤酒元素，然后又是猢狲？这其中肯定有蹊跷。', `MaleText_loc5`='先是啤酒元素，然後現在又是猴人來襲?有些事不大對頭。', `MaleText_loc7`='¿Elementales de cerveza y ahora un ataque hozen? Estaba pasando algo malo.' WHERE `ID`=55701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그에게 한 번 더 기회를 주기로 했어. 가족을 그렇게 포기할 순 없으니.', `MaleText_loc4`='我决定再给他一次机会。我是不会放弃我的家人的。', `MaleText_loc5`='我決定再給他一個機會，我不會就這樣放棄家人。', `MaleText_loc7`='Decidí darle otra oportunidad. No era cuestión de darle la espalda a la familia.' WHERE `ID`=55702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 들을 필요가 없었단다. 내 핏줄에게... 냉대 받다니! 그대로 뒤돌아서 와 버렸지.', `MaleText_loc4`='听到这些我放弃了。我被自己的亲人……拒之千里！我转身离开了。', `MaleText_loc5`='聽到這些話語，我自己的血親...將我拒於門外!我隨即轉身離開。', `MaleText_loc7`='Eso es todo lo que necesitaba escuchar. ¡Despreciado por sangre de mi sangre! Me fui.' WHERE `ID`=55703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[이 대사는 삭제되었습니다]', `MaleText_loc4`='[This line has been cut]', `MaleText_loc5`='[這條線已被切斷]', `MaleText_loc7`='[This line has been cut]' WHERE `ID`=55704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 내 몸을 지킬 수밖에 없었단다.', `MaleText_loc4`='我别无选择，只有自卫。', `MaleText_loc5`='我別無選擇，只能保護我自己。', `MaleText_loc7`='No tuve más remedio que defenderme.' WHERE `ID`=55705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*딸꾹* 그 우낏 맥주 좀 더 줘! *딸꾹*', `MaleText_loc4`='*嗝*给我再来点儿该死的啤酒！*嗝*', `MaleText_loc5`='*嗝* 再給我更多那天殺的啤酒! *嗝*', `MaleText_loc7`='*hip* ¡Tú dame más de esa cerveza machuka! *hip*' WHERE `ID`=55706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어렸을 때부터 저는 양조사가 되고 싶었습니다. 여러 가지 성분을 섞어 완벽한 맛과 향을 만들어 내는 일이 좋았습니다.$b$b하지만 훈련을 받는 동안 사람들은 제 음료가 지나치게 강하다고 거듭 말했습니다.$b$b그래서 저는 금속을 녹이고 섞는 제련술에서 제 길을 찾았습니다. 당시에는 논리적인 결정이라고 생각했었습니다.', `MaleText_loc4`='在我小的时候，我曾梦想成为一名酒仙。通过各种奇妙的化学反应酿造出完美的陈年佳酿。$b$b但在我学习的过程中，他们总说我酿的酒太烈了。$b$b所以我就转行搞冶炼了。当时看来，这种转行很合理。', `MaleText_loc5`='我年輕的時候想成為釀酒大師。混合各種不同的化學物質，調配出完美的飲品和風味。$b$b在接受訓練的期間，他們老是說我的酒勁太飽滿了。$b$b所以我改入了冶煉這一行。在當時，這像是個合理的轉變。', `MaleText_loc7`='Cuando era joven quería ser maestro cervecero y mezclar sustancias químicas hasta encontrar la bebida y el sabor perfectos.$b$bPero durante mi aprendizaje no dejaban de decirme que las bebidas me salían demasiado sólidas.$b$bAsí que me pasé a la fundición. En aquella época me pareció una transición lógica.' WHERE `ID`=55707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 국수 가게에 잘 오셨습니다. 먹을 수 있는 국수라면 뭐든 만들어 드립니다. 여기에 없는 건, 먹을 음식이 아닌 겁니다!', `MaleText_loc4`='欢迎来到我的面馆，各式面条应有尽有。要是我们这儿没有的，您不吃也罢。', `MaleText_loc5`='歡迎來到我的麵館。我們這裡有每一種該被品嚐的麵條。如果我們沒有，你就不該品嚐它。', `MaleText_loc7`='Te doy la bienvenida a mi caseta de fideos. Tenemos todos los tipos de fideos comestibles. Si no lo tenemos, es que no deberías comértelo.' WHERE `ID`=55708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 위대한 추라고 하네. 무쇠배 수도사라고도 불리지. 워낙 많이 먹어서 말이야. 아마 내 이름을 들어본 적이 있을 걸세.', `MaleText_loc4`='我是强大的破军铁腹志大师，这个外号源自我那臭名昭著的腹壁神功。你大概已经听说我了吧。', `MaleText_loc5`='我是強大的『鐵肚皮』祖，我的名字來自於我威名遠播的「肚皮彈幕」。也許你聽過我的名頭。', `MaleText_loc7`='Soy el poderoso Tzu, el monje de la Panza Férrea, famoso por mi infame barriga sin fondo. Quizás hayas oído hablar de mí.' WHERE `ID`=55709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 무시무시한 송곳니 괴수와 전투를 벌였던 적이 있네. 온 세계에 어둠을 드리울까 봐, 차마 그 이름을 입에 올릴 수 없는 그런 괴수였어.', `MaleText_loc4`='我曾经与长着恐怖利齿的野兽战斗过，我们最好不要提起它的名字，因为其中蕴含的恐惧足以使日月失色。', `MaleText_loc5`='我曾經和擁有恐怖尖牙利齒的野獸戰鬥。這野獸的名字不該被說出來，以免天地變色。', `MaleText_loc7`='Una vez luché contra una bestia de colmillos y garras temibles que no nombraré por miedo a nublar el cielo.' WHERE `ID`=55710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친도 자신의 칭호를 거저 얻은 것이 아니네. 언젠가 마을 전체의 국수 요리사들이 한데 모여 치열한 시합을 벌였던 적이 있었지.$b$b바로 이곳에서 끓는 물 한 통을 놓고 모두들 최고의 국수를 요리하기 위해 무시무시하다고 할 만큼 열정적으로 경쟁했어.$b$b영광스러운 현장이었다고 할 수밖에!$b$b그 시합의 승자가 바로 친이었네. 시식 그릇을 뒤흔들 만큼 놀라운 맛의 국수를 만들어냈던 거야.', `MaleText_loc4`='秦可不是浪得虚名。曾经有过一场竞争非常激烈的面条大赛，汇集了全村的行家里手。$b$b他们在一桶桶煮沸的面汤前大展身手，只为在一天之内制作出最上乘的面条来。$b$b别提有多精彩啦！$b$b最终他技压群雄，做出来的面条好吃到连我这个美食家都为之震惊。', `MaleText_loc5`='欽不是浪得虛名的師傅。村裡四面八方的麵師傅曾經齊聚一堂，進行一場激烈的冠軍賽。$b$b他們就在這裡勇猛地戰鬥，爭奪裝滿滾水的木桶，在一天的時限之內做出最上等的麵條。$b$b那過程真是扣人心弦吶，我跟你說!$b$b最終只有麵粉怒成功出線，製造出驚天動地、震憾碗公的麵條。', `MaleText_loc7`='Chin se ha ganado el título a pulso. Se celebró una gran competición que reunió a los cocineros de tallarines de todos los rincones de nuestra aldea.$b$bEs aquí donde compitieron ferozmente entre barriles de agua hirviente para elaborar los mejores tallarines en varios kilómetros a la redonda.$b$b¡Fue glorioso!$b$bAl final, Harina Sazonada se alzó como vencedor gracias a unos tallarines tan deliciosos que se te hacía la boca agua con solo olerlos.' WHERE `ID`=55711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 한 분의 이방인이시군요? 다들 어디서 오시는 거지요?$b$b며칠 전에도 어떤 분이 이곳을 지나가시면서, 거북섬에서 왔다고 하시더라고요. 이름이 아마... 스톰스타우트라고 하셨을 걸요?', `FemaleText_loc4`='又一个陌生人？你们都是从哪儿来的啊？$b$B几天前有一个自称来自于乌龟岛的人，他说他的名字叫风暴烈酒。', `FemaleText_loc5`='又一個陌生人?你們都打哪鑽出來的啊?$b$b幾天前有個人經過這裡，自稱是從烏龜上來的。他說他的名字是風暴烈酒。', `FemaleText_loc7`='¿$gOtro forastero:Otra forastera;? ¿Pero de dónde salís?$b$bHace poco pasó alguien que decía venir de la tortuga. Dijo llamarse Cerveza de Trueno.' WHERE `ID`=55712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 제 양조장에서 싸움을 하러 오신 건 아니겠지요? 저기 이방인 두 명은 지난 주에 이곳에 와서, 꽤 큰 난투극을 벌였었어요.', `FemaleText_loc4`='你不会是到我的酿酒厂来捣乱的吧？那边那两个陌生人上周到这里时还大打出手了呢。', `FemaleText_loc5`='你不是要來我的釀酒廠鬧事的吧?上禮拜那兩個陌生人搞出了一場好大的騷動。', `FemaleText_loc7`='No habrás venido a buscar pelea en mi cervecería, ¿no? Esos dos forasteros de ahí montaron una buena cuando llegaron, la semana pasada.' WHERE `ID`=55713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전승지기 초 님께서 당신에 대해 칭찬을 많이 하시더군요. 호젠처럼 날뛰지만 않는다면 언제든 환영이에요.', `FemaleText_loc4`='游学者周卓对你称赞有加。只要你帮我们赶走猢狲，你永远都会受到欢迎。', `FemaleText_loc5`='博學行者阿洲對你的評價很高。只要你別像猴人一樣搗蛋，我們隨時歡迎你。', `FemaleText_loc7`='El eremita Cho nos habló muy bien de ti. Te daremos la bienvenida siempre que no te comportes como un hozen.' WHERE `ID`=55714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='겁쟁이들! 허약해 빠진... 애송이들...', `FemaleText_loc4`='懦夫！你们这群懦弱的……走狗……', `FemaleText_loc5`='懦夫!你們這群弱小的...傢伙...', `FemaleText_loc7`='¡Cobardes! Vaya bola de inútiles... perros…' WHERE `ID`=55715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저한테 하실 중요한 말씀이 있다고요, 사부님?', `MaleText_loc4`='你有话要对我说吗，师父？', `MaleText_loc5`='你有重要的事想告訴我嗎，大師?', `MaleText_loc7`='¿Tenías algo importante que decirme, maestro?', `FemaleText_loc1`='저한테 하실 중요한 말씀이 있다고요, 사부님?', `FemaleText_loc4`='你有话要对我说吗，师父？', `FemaleText_loc5`='你有重要的事想告訴我嗎，大師?', `FemaleText_loc7`='¿Tenías algo importante que decirme, maestro?' WHERE `ID`=55716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토야 대령했습니다! 필요한 게 있으시다고요? 제가 구해드리죠! 새벽의 꽃에서 다른 사람을 찾을 필요가 없어요!', `MaleText_loc4`='我叫托亚！无论你需要什么我都能帮你搞到！不用找别人了，我可是全晨芳园独一无二的！', `MaleText_loc5`='我是托亞!你需要什麼?我能弄到!甭去找晨綻裡的其他人了!', `MaleText_loc7`='¡Soy Toya! ¡Si lo necesitas, yo puedo conseguírtelo! ¡No hagas negocios con nadie más en Floralba!' WHERE `ID`=55717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기 초 님을 만날 준비가 됐습니다.', `MaleText_loc4`='我已经准备好去见游学者周卓了。', `MaleText_loc5`='我準備好面見博學行者阿洲了。', `MaleText_loc7`='Estoy preparado para ver al eremita Cho.', `FemaleText_loc1`='전승지기 초 님을 만날 준비가 됐어요.', `FemaleText_loc4`='我已经准备好去见游学者周卓了。', `FemaleText_loc5`='我準備好面見博學行者阿洲了。', `FemaleText_loc7`='Estoy preparada para ver al eremita Cho.' WHERE `ID`=55718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 걷힌다...', `MaleText_loc4`='黑暗退去了……', `MaleText_loc5`='黑暗散去...', `MaleText_loc7`='La oscuridad se disipa...' WHERE `ID`=55719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 들여다봤지만 내 모습이 비치지 않더군...', `MaleText_loc4`='我注视水面，却看不见我的倒影……', `MaleText_loc5`='我凝望水中，而我的倒影空蕩蕩...', `MaleText_loc7`='Escudriño las aguas, y mi reflejo... está vacío.' WHERE `ID`=55720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이여... 날 받아다오...', `MaleText_loc4`='重归于……水流。', `MaleText_loc5`='水呀...帶我走吧...', `MaleText_loc7`='Agua... Llévame contigo...' WHERE `ID`=55721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이시여, 도와주신 데 대해 다시 한번 감사의 말씀을 드릴게요. 전 벌써 시라의 손가락에서 예쁘게 빛날 반지에 대한 생각이 머리를 꽉 채워 버렸어요.', `MaleText_loc4`='再次感谢你的帮助，陌生人。我已经开始琢磨该给塞拉打造一枚什么样的戒指了。', `MaleText_loc5`='再次感謝你的幫助，陌生人。我已經開始計畫錫拉的手該配什麼樣的戒指了。', `MaleText_loc7`='Gracias de nuevo por tu ayuda, $gforastero:forastera;. Ya he empezado a pensar en el anillo que forjaré para Syra.' WHERE `ID`=55722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 말해주더군... 적들이 다가온다고.', `MaleText_loc4`='水流告诉我……敌人在逼近。', `MaleText_loc5`='水輕聲地告訴我...敵人接近了。', `MaleText_loc7`='Las aguas me susurran... que se acerca el enemigo.' WHERE `ID`=55723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 용사님! 그 나쁜 마녀에게 누가 진짜 강한지 제대로 보여주셨어요.', `FemaleText_loc4`='哇，陌生人！你让那个恶毒的老巫婆明白了谁才是老大。', `FemaleText_loc5`='哇喔，陌生人!你真的給了那個壞蛋老巫婆一點顏色瞧瞧。', `FemaleText_loc7`='¡Toma, $gforastero:forastera;! Le has enseñado quién manda a esa vieja bruja.' WHERE `ID`=55724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 표범들을 때려눕히는 모습이 정말 멋졌어요! 녀석들이 "으르르릉!"하니까 $G아저씨:아줌마;는 "아뵤!"하면서 툭탁툭탁 해버렸잖아요.', `FemaleText_loc4`='你痛打那些懒猫的招式实在是太酷了！它们气势汹汹地来，结果被你三下两下就收拾掉了。', `FemaleText_loc5`='你打倒那些貓咪的樣子真是太屌了!他們就像這樣「吼啊啊啊!」然後你就像這樣「啊躂!」然後你就拿走他們的東西了。', `FemaleText_loc7`='¡Ha sido genial la paliza que les has dado a los gatos! Se han puesto "¡Grrrr!" y luego tú "¡Bum!" y luego les has quitado cosas.' WHERE `ID`=55725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어른들은 항상 옥의 마녀가 남편을 잃고 슬픔에 빠져 숲속에 사는 할머니라고만 했어요. 하지만 $G아저씨:아줌마;가 진짜 모습을 드러내 주셨죠!$b$b그런데... 제가 어른들한테는 따로 얘기 안 했어요. 아무래도 제가 혼날 것만 같았거든요.', `FemaleText_loc4`='大人们总是告诉我们说，那个住在林子里的青玉巫婆只是个因为而死了丈夫伤心过度的老太婆。可你证明他们错了！$b$b只是……我不能讲给那些大人们听，我可不想给自己找麻烦。', `FemaleText_loc5`='大人們老是跟我們說玉巫婆只是丈夫死掉住在樹林裡的普通老太太。你可讓他們搞清楚了!$b$b只不過...我沒有跟大人們說，因為我不想惹麻煩。', `FemaleText_loc7`='Los mayores siempre nos han dicho que la Bruja de Jade solo era una vieja del bosque que estaba triste porque murió su marido. ¡Pero tú has demostrado que no!$b$bSolo que... no se lo he contado a ninguno porque no quería meterme en líos.' WHERE `ID`=55726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 너 응가에 우끼해버린다!', `MaleText_loc4`='我要把你打得稀巴烂！', `MaleText_loc5`='我要用便便揍你!', `MaleText_loc7`='¡Les hace kraku en los mikos!' WHERE `ID`=55727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_food_23.blp:20|t 우끼우끼가 |cFFFF0000|Hspell:106651|h[미친 바나나]|h|r를 시전합니다! 더 많은 통이 쏟아집니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_food_23.blp:20|t乌克乌克|cFFFF0000|Hspell:106651|h[发疯]|h|r啦！更多的桶飞过来了！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_food_23.blp:20|t歐克·歐克要|cFFFF0000|Hspell:106651|h[暴走]|h|r了!更多桶子要來了!', `MaleText_loc7`='|TInterfaceIconsinv_misc_food_23.blp:20|t¡A Ook-Ook le ha dado una |cFFFF0000|Hspell:106651|h[Ida de coco]|h|r! ¡Vienen más barriles!' WHERE `ID`=55728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로 원더브루를 보셨습니까?', `MaleText_loc4`='你看见罗·游酒了吗？', `MaleText_loc5`='你有看到學徒小樓·蕩酒嗎?', `MaleText_loc7`='¿Has visto al aprendiz Lo Pócima Errante?', `FemaleText_loc1`='로 원더브루를 보셨나요?', `FemaleText_loc4`='你看见罗·游酒了吗？', `FemaleText_loc5`='你有看到學徒小樓·蕩酒嗎?', `FemaleText_loc7`='¿Has visto al aprendiz Lo Pócima Errante?' WHERE `ID`=55729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깨달음을 찾으시나요?', `FemaleText_loc4`='你想要寻求突破吗？', `FemaleText_loc5`='你尋求頓悟嗎?', `FemaleText_loc7`='¿Buscas la iluminación?' WHERE `ID`=55730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우끼! 우우우우우우끼!!', `MaleText_loc4`='乌克！乌………克！', `MaleText_loc5`='歐嗚!歐歐歐歐歐嗚!!', `MaleText_loc7`='¡Oook! ¡Ooooooook!!' WHERE `ID`=55731;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 정신과 육체를 가두고 있는 한계에서 벗어나고 싶으세요?', `FemaleText_loc4`='你想拓展你的思维，强健你的身心，突破现在的极限吗？', `FemaleText_loc5`='你想要讓你的心智和身體突破當前所受到的界限嗎?', `FemaleText_loc7`='¿Deseas expandir tu mente y tu cuerpo más allá de los límites que te confinan?' WHERE `ID`=55732;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티엔 수도원에서 기력을 한 곳에 집중하는 방법을 제대로 배웠어요. 그랬더니 이제는 새끼손가락 하나만 사용해서 술병 뚜껑을 딸 수 있더라고요.', `FemaleText_loc4`='天禅院教会了我如何凝聚自己的力量，现在我只用一根小拇指就能点开一个酒桶。', `FemaleText_loc5`='天僧寺教導我如何聚焦我的能量，讓我僅憑一根粉紅的指頭就能戳穿酒桶。', `FemaleText_loc7`='El Monasterio Tian me enseñó a concentrar mi energía con tanta fuerza que puedo partir un barril con el dedo meñique.' WHERE `ID`=55733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로가 제 제자 시라와 도망친 이후로는 본 적이 없어요. 둘은 동쪽 도원으로 갔을 거예요.$b$b양 집안의 부모들이 이 사실을 알면 좋지 않을 거예요. 원더브루와 골든드래프트 가문은 오랫동안 서로 티격태격하고 있거든요.', `FemaleText_loc4`='自从罗拐跑了我的弟子塞拉之后，我就再也没有见到过他了。他们往东边的百木园去了。$b$b这要是让他们的父母知道了可就糟了，游酒家族和金酿家族向来水火不容啊。', `FemaleText_loc5`='自從小樓和我的學生錫拉一起離開後，我就再也沒看過他。他們往東邊落英園的方向去了。$b$b如果這件事被他們的父母知道，他們可不會有好下場。金流和蕩酒兩家有些根深蒂固的仇怨。', `FemaleText_loc7`='No he visto a Lo desde que se escapó con mi estudiante, Syra. Se dirigían al este, hacia El Arboretum.$b$bComo se enteren sus padres, la cosa se puede poner fea. Los Pócima Errante y los Brisa Dorada tienen una larga historia de rivalidad.' WHERE `ID`=55734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도원에 잘 왔네. 이 나무들 사이에서 영감을 얻기를 바라겠네.', `MaleText_loc4`='欢迎来到百木园。愿你能在这林宇间找到灵感。', `MaleText_loc5`='歡迎來到落英園，願你在林蔭間找到靈感。', `MaleText_loc7`='$gBienvenido: Bienvenida; al Arboretum. Que encuentres la inspiración entre los árboles.' WHERE `ID`=55735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순환하며 영원히 계속되는 생명의 관점에서 보면, 우리의 삶이란 눈 깜빡일 새에 스쳐가는 한 순간에 불과하다네.', `MaleText_loc4`='生命之短暂犹如白驹过隙，眨眼即逝。', `MaleText_loc5`='我們的生命稍縱即逝。', `MaleText_loc7`='Nuestras vidas no son más que una gota de rocío para la realidad.' WHERE `ID`=55736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 문화는 고대로부터 오래도록 전해 내려왔네.$b$b우리 기술 덕분에, 그런 고대 문화가 후세에 이르기까지 보존될 수 있는 거지.', `MaleText_loc4`='我们的文化源远流长。$b$b多亏了我们的能工巧匠，使我们的文化记忆得以保存，并传承给下一代。', `MaleText_loc5`='我們擁有古老而悠久的文化。$b$b多虧了我們的技藝，其中一些文化將得以傳承給後人。', `MaleText_loc7`='La nuestra es una cultura antigua y longeva.$b$bGracias a nuestra artesanía, parte de la memoria cultural se puede conservar para las generaciones futuras.' WHERE `ID`=55737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로 원더브루를 보셨습니까?', `MaleText_loc4`='你看见罗·游酒了吗？', `MaleText_loc5`='你有看到學徒小樓·蕩酒嗎?', `MaleText_loc7`='¿Has visto al aprendiz Lo Pócima Errante?', `FemaleText_loc1`='로 원더브루를 보셨나요?', `FemaleText_loc4`='你看见罗·游酒了吗？', `FemaleText_loc5`='你有看到學徒小樓·蕩酒嗎?', `FemaleText_loc7`='¿Has visto al aprendiz Lo Pócima Errante?' WHERE `ID`=55738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가문의 이름을 외면하고 서로에게 눈이 멀어버린 두 명의 연인들을 찾고 있는 모양이군. 둘은 이곳에 왔었네. 함께 걸어야 할 길을 찾으러 왔더군.$b$b안타깝지만, 이곳의 나무에서도, 예술에서도 그 답을 찾지 못했어.', `MaleText_loc4`='你要找的是一对抛弃了家族名誉的爱侣。他们曾来过这里，想要找到厮守一生的方法。$b$b可惜他们并没有在林木或艺术中找到答案。', `MaleText_loc5`='你在找尋一對無視家族間紛擾的愛侶。他們是來過這裡，來這裡尋找力量，幫助他們堅持所走的道路。$b$b可惜，他們並沒有在山水或文藝間找到答案。', `MaleText_loc7`='Estás buscando a dos amores ciegos ante las ambiciones de sus familias. Estaban aquí, en busca de un camino hacia la libertad.$b$bDesafortunadamente no encontraron las respuestas entre los árboles o el arte.' WHERE `ID`=55739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시조님들의 축복입니다.', `MaleText_loc4`='族长的祝福。', `MaleText_loc5`='潘達族王的祝福。', `MaleText_loc7`='Recibe la bendición de los pandriarcas.', `FemaleText_loc1`='시조님들의 축복이에요.', `FemaleText_loc4`='族长的祝福。', `FemaleText_loc5`='潘達族王的祝福。', `FemaleText_loc7`='Recibe la bendición de los pandriarcas.' WHERE `ID`=55741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옥룡이시여, 저에게 힘을!', `FemaleText_loc4`='青龙，赐予我力量吧！', `FemaleText_loc5`='玉蛟，請賜予我力量!', `FemaleText_loc7`='¡Dragón de Jade, dame fuerzas!' WHERE `ID`=55742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로 말씀이세요? 아, 오늘은 못 봤어요. 안 그래도 이상하다고 생각하고 있었어요. 보통은 아침에 절 데려다 주거든요.$b$b정말 착한 사람이에요. 하지만 신지그러프 님께 수련을 받는 걸 우습게 생각하는 건 참 안타까워요. 그분은 정말 재능 있는 제련사거든요.$b$b로를 보시거든, 아침에 함께 걷지 못해서 정말 아쉬웠다고 전해주세요.', `MaleText_loc4`='罗？噢。我今天没看见他。我觉得这事儿很古怪。他每天早晨，都会陪我去工作的。$b$b他有一颗善良的心。他竟然没有好好珍惜自己与拙焰师匠的师徒缘分，这真是太遗憾了。他在金属冶炼上很有天赋。$b$b如果你见到他，请告诉他我今早没有等到他。', `MaleText_loc5`='小樓?喔，我今天還沒看見他。我還想這挺奇怪。他通常都在早上和我一起走路去上工。$b$b他有著一副好心腸。真可惜他不太看重在森格格魯夫那裡當學徒的機會。他是個很有天賦的精鍊工。$b$b如果你看見他，跟他說我想念今天早上我們一起散步。', `MaleText_loc7`='¿Lo? Hoy no lo he visto. Me ha extrañado bastante. Normalmente me acompaña al trabajo por la mañana.$b$bTiene un gran corazón. Es una lástima que infravalore su aprendizaje con Forja Adusta. Tiene mucho talento como fundidor.$b$bSi lo ves, dile que he echado de menos el paseo esta mañana.' WHERE `ID`=55743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩔 수 없지.', `MaleText_loc4`='那就这样吧。', `MaleText_loc5`='就這樣吧。', `MaleText_loc7`='Que así sea.' WHERE `ID`=55744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 네가 무슨 짓을 저지르는지 모른다. 아만툴... 내가... 본... 것은...', `MaleText_loc4`='你根本不明白你究竟干了什么。阿曼苏尔……我……看到……的……', `MaleText_loc5`='你們不知道自己做了什麼。阿曼蘇爾...我所...見到的...', `MaleText_loc7`='No tienen ni idea de lo que han hecho. Aman''Thul... Lo que... he... visto…' WHERE `ID`=55745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무쇠배 추 님! 숲 속 마녀가 제 친구를 비취로 만들어 버렸어요. 도와주실 수 있나요?', `FemaleText_loc4`='你好，破军铁腹先生！林子里的巫婆把我朋友变成了玉雕。你能帮帮我吗？', `FemaleText_loc5`='嘿，鐵肚皮大師!樹林裡的巫婆把我的朋友變成玉了。你能幫忙嗎?', `FemaleText_loc7`='¡Señor Panza Férrea! La bruja del bosque ha convertido a mis amigos en jade. ¿Me ayudas?' WHERE `ID`=55746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 시간이다.', `MaleText_loc4`='你的死期到了。', `MaleText_loc5`='你死期到了。', `MaleText_loc7`='Les ha llegado la hora.' WHERE `ID`=55747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모래의 흐름이 멈췄다.', `MaleText_loc4`='沙子已经漏完了。', `MaleText_loc5`='沙子已用盡。', `MaleText_loc7`='Se ha terminado la arena.' WHERE `ID`=55748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 끝났다.', `MaleText_loc4`='时光的尽头。', `MaleText_loc5`='時間到。', `MaleText_loc7`='El tiempo se agota.' WHERE `ID`=55749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 행동에 다른 결과를 바란다니 어리석군.', `MaleText_loc4`='只有疯子才相信重复的行为能带来不同的结果。', `MaleText_loc5`='重複同樣動作而期待不同的結果，簡直是愚不可及。', `MaleText_loc7`='Locura es hacer lo mismo una y otra vez esperando obtener diferentes resultados.' WHERE `ID`=55750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 더 기회가 와도 결과는 마찬가지야. 날 막진 못해.', `MaleText_loc4`='再来一次也不会有任何改变。你必将失败。', `MaleText_loc5`='再給一次機會也沒有差別。你還是會失敗。', `MaleText_loc7`='Da igual que tengan otra oportunidad. Fracasarán.' WHERE `ID`=55751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이게 네 작전이냐, 네 계획이냐?', `MaleText_loc4`='再次失败……？这就是你的诡计，你的阴谋？', `MaleText_loc5`='又來了...?這就是你的計畫，你的陰謀?', `MaleText_loc7`='¿Otra vez...? ¿Es esta su confabulación?' WHERE `ID`=55752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모래시계의 힘이 떨어졌다. 장난은 끝이다, 필멸자여. 포기해라. 아니면 죽어라.', `MaleText_loc4`='沙漏的力量耗尽了，游戏结束了，凡人。屈服，或者消亡。', `MaleText_loc5`='沙漏的力量已經耗盡。沒得玩了，凡人們。放棄，或死亡。', `MaleText_loc7`='El poder del reloj de arena se ha agotado. Se acabó el juego, mortales. Ríndanse o morirán.' WHERE `ID`=55753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그린포우 부인은 마녀가 아니란다. 그냥 정말 살아 있는 듯한 비취 조각상을 만들 뿐이야.', `MaleText_loc4`='寡妇绿爪可不是巫婆。只是她做的青玉雕像非常逼真罢了。', `MaleText_loc5`='寡婦綠爪「不是」個巫婆，她只是能造非常栩栩如生的玉像。', `MaleText_loc7`='La viuda Zarpa Verde no es una bruja. Sencillamente talla estatuas de jade muy realistas.' WHERE `ID`=55754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 봉화에 불을 붙여야 하네. 지원군이 없으면 놈들이 문을 부술 거야!', `MaleText_loc4`='我们得点燃信号火焰。要是没有援军，它们会摧毁大门！', `MaleText_loc5`='我們得去點燃烽火信號。援軍再不來，他們就要攻破這座關口了!', `MaleText_loc7`='Tenemos que encender la señal de fuego. Sin refuerzos, ¡destruirán la puerta!' WHERE `ID`=55755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 사마귀들이 이 지역을 점령했어. 갈 방법이 없네!', `MaleText_loc4`='可这儿全是螳螂妖。没有一条安全的道路！', `MaleText_loc5`='可是這裡到處都是螳螂人，我們根本殺不過去!', `MaleText_loc7`='Pero los mántides nos invaden. ¡Los caminos están obstruidos!' WHERE `ID`=55756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정마세요! 제가 해볼게요!', `MaleText_loc4`='别担心！我能行！', `MaleText_loc5`='別擔心!我辦得到的!', `MaleText_loc7`='¡No se preocupen! ¡Yo me encargo!' WHERE `ID`=55757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐하는 건가?! 거기까지 갈 수 있을리가!', `MaleText_loc4`='你在做什么？！你不会成功的！', `MaleText_loc5`='你在做什麼?!你不可能辦到的!', `MaleText_loc7`='Pero, ¿qué haces? ¡Nunca lograrás llegar hasta ella!' WHERE `ID`=55758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러다 죽을지도 몰라!', `MaleText_loc4`='你这是在送死！', `MaleText_loc5`='你會被殺掉的!', `MaleText_loc7`='¡Conseguirás que te maten!' WHERE `ID`=55759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내 말을 안 들었지?', `MaleText_loc4`='他怎么不听劝呢！', `MaleText_loc5`='為什麼他不聽我的話?', `MaleText_loc7`='¿Por qué no hace caso?' WHERE `ID`=55760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련병들에게 저 붉은 셔츠를 주면 안 되겠어. 움직이는 표적이 될 뿐이야.', `MaleText_loc4`='别再给新兵发那种红衬衫了。那只会把他们变成活靶子。', `MaleText_loc5`='我們最好別再給新士兵穿上紅衣了，那只會讓他們變成活靶子。', `MaleText_loc7`='Vamos a dejar de dar camisetas rojas a los nuevos. Parecen blancos andantes.' WHERE `ID`=55761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s|1이;가; |cFFFF0000|Hspell:106886|h[소작]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s开始施放|cFFFF0000|Hspell:106886|h[灸灼]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s開始施放|cFFFF0000|Hspell:106886|h[燒灼]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_vehicle_sonicshockwave.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:106886|h[Cauterizar]|h|r!' WHERE `ID`=55762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 무언가를 찾는 유일한 방법이 그것을 더 이상 찾지 않는 것이기도 합니다.', `MaleText_loc4`='有时候，你不去找它，想找的东西反而会自己出现。', `MaleText_loc5`='有時候，要找到某樣事物的唯一方法，就是停止尋找。', `MaleText_loc7`='A veces, la única manera de encontrar algo es dejar de buscarlo.' WHERE `ID`=55763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물과 대화해주십시오, 애쉬요.', `MaleText_loc4`='去和水谈谈吧，阿西约。', `MaleText_loc5`='儘管去對水說話吧，艾須歐。', `MaleText_loc7`='Adelante, Ashyo, habla con el agua.', `FemaleText_loc1`='물과 대화해주세요, 애쉬요.', `FemaleText_loc4`='去和水谈谈吧，阿西约。', `FemaleText_loc5`='儘管去對水說話吧，艾須歐。', `FemaleText_loc7`='Adelante, Ashyo, habla con el agua.' WHERE `ID`=55764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되면 위에 있는 연못에서 만납시다!', `MaleText_loc4`='你准备好后，就到水池里找我！', `MaleText_loc5`='你準備好之後就到池子來跟我見面吧!', `MaleText_loc7`='¡Reúnete conmigo en las pozas cuando puedas!' WHERE `ID`=55765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군, 영웅들이여!', `MaleText_loc4`='你成功了！', `MaleText_loc5`='你成功了!', `MaleText_loc7`='¡Lo han hecho!' WHERE `ID`=55766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 파괴자를 물리쳤습니다!', `MaleText_loc4`='我们击败了灭世者！', `MaleText_loc5`='我們擊敗了毀滅者!', `MaleText_loc7`='¡Hemos derrotado al Destructor!', `FemaleText_loc1`='저희가 파괴자를 물리쳤습니다!', `FemaleText_loc4`='我们击败了灭世者！', `FemaleText_loc5`='我們擊敗了毀滅者!', `FemaleText_loc7`='¡Hemos derrotado al Destructor!' WHERE `ID`=55767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝났다. 마침내 파괴자가 최후를 맞았어. 드디어, 우리 세상을 치유할 수 있네.', `MaleText_loc4`='结束了；灭世者终于走向了灭亡。现在，我们将开始治疗这个世界。', `MaleText_loc5`='結束了。毀滅者終於就戮。現在，該開始替我們世界療傷了。', `MaleText_loc7`='Se acabó; al fin el Destructor se enfrentó a su destino. Ahora, podemos empezar a sanar nuestro mundo.' WHERE `ID`=55768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불가능한 일을 해냈구나. 전 아제로스가 실패를 염려하던 일을 너희가 해냈다.', `MaleText_loc4`='你完成了不可能完成的任务，全艾泽拉斯都担心你会失败，可你却成功了。', `MaleText_loc5`='你達成了不可能的任務，在全艾澤拉斯都怕你會失敗的時候竟然成功了。', `MaleText_loc7`='Han logrado lo imposible; han triunfado donde todo Azeroth temía que podrían fracasar.', `FemaleText_loc1`='불가능한 일을 해냈구나. 전 아제로스가 실패를 염려하던 일을 너희가 해냈다.', `FemaleText_loc4`='你完成了不可能完成的任务，全艾泽拉斯都担心你会失败，可你却成功了。', `FemaleText_loc5`='你達成了不可能的任務，在全艾澤拉斯都怕你會失敗的時候竟然成功了。', `FemaleText_loc7`='Han logrado lo imposible; han triunfado donde todo Azeroth temía que podrían fracasar.' WHERE `ID`=55769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...하지만, 서두르는 게 좋을지도.', `MaleText_loc4`='我要是你们，就会赶快一点……', `MaleText_loc5`='...不過你們最好動作快點。', `MaleText_loc7`='... aunque, quizás deban darse prisa.' WHERE `ID`=55770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 들었나? 이게 무슨 소리지!', `MaleText_loc4`='你听到了吗？那是什么声音！', `MaleText_loc5`='你有聽到嗎?那是什麼聲音?', `MaleText_loc7`='¿Has oído eso? ¿Qué es ese ruido?' WHERE `ID`=55771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 됩니다! 놈이 살아남았을 리가 없어요!', `MaleText_loc4`='难以置信！他不可能还活着！', `MaleText_loc5`='真難以置信!他怎麼可能還活著!', `MaleText_loc7`='¡Inconcebible! ¡No puede seguir con vida!', `FemaleText_loc1`='말도 안 됩니다! 놈이 살아남았을 리가 없어요!', `FemaleText_loc4`='难以置信！他不可能还活着！', `FemaleText_loc5`='真難以置信!他怎麼可能還活著!', `FemaleText_loc7`='¡Inconcebible! ¡No puede seguir con vida!' WHERE `ID`=55772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 너무 강해! 데스윙이 최후의 대격변을 일으키면 아제로스의 모든 생명은 끝이다. 서둘러, 놈을 막아야 해!', `MaleText_loc4`='不！如此强大的力量！死亡之翼将召来毁灭所有生命的大灾变。赶快，我们必须阻止他！', `MaleText_loc5`='不!好強的力量!死亡之翼召喚的最終浩劫會毀滅艾澤拉斯的一切生命。快，我們快阻止他!', `MaleText_loc7`='¡No! ¡Todo ese poder! El lanzamiento del cataclismo final de Alamuerte destruirá todo tipo de vida en Azeroth. Rápido, ¡debemos detenerlo!', `FemaleText_loc1`='안 돼! 너무 강해! 데스윙이 최후의 대격변을 일으키면 아제로스의 모든 생명은 끝이다. 서둘러, 놈을 막아야 해!', `FemaleText_loc4`='不！如此强大的力量！死亡之翼将召来毁灭所有生命的大灾变。赶快，我们必须阻止他！', `FemaleText_loc5`='不!好強的力量!死亡之翼召喚的最終浩劫會毀滅艾澤拉斯的一切生命。快，我們快阻止他!', `FemaleText_loc7`='¡No! ¡Todo ese poder! El lanzamiento del cataclismo final de Alamuerte destruirá todo tipo de vida en Azeroth. Rápido, ¡debemos detenerlo!' WHERE `ID`=55773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, 영웅들이여. 머지않아 데스윙이 초래한 대격변이 세상을 휩쓸어 종말을 불러올 것이다. 나와 함께 공격하자. 당장!', `MaleText_loc4`='赶快，英雄们。死亡之翼引导的大灾变即将毁灭这个世界。和我一起进攻，快！', `MaleText_loc5`='快，英雄們。死亡之翼的大災變馬上就會完成並使世界毀滅。加入我一起攻擊，快!', `MaleText_loc7`='¡Apresúrense, héroes! En unos instantes el cataclismo de Alamuerte terminará lo que empezó y acabará con el mundo. Únanse a mi ataque, ¡ahora!' WHERE `ID`=55774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴자가 세상을 조각낼 일격을 위해 엄청난 힘을 모으고 있습니다. 당장 공격하십시오! 마지막 대격변을 막아야 합니다!', `MaleText_loc4`='灭世者想要集中它全部的力量来撕裂这个世界！快进攻！我们必须阻止这最后的大灾变！', `MaleText_loc5`='毀滅者正在蓄積所有的力量，要將世界一分為二。現在就攻擊他!我們必須阻止最終的災變!', `MaleText_loc7`='El Destructor está reuniendo todo su poder para un golpe que partirá el mundo en dos. ¡Atáquenlo ya! ¡Debemos detener el Cataclismo final!' WHERE `ID`=55776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락은 내가 정화하마. 내 불에 너희가 피해를 입진 않을 거다.', `MaleText_loc4`='我会尽力净化一切腐化堕落；我的烈焰是不会伤害你的。', `MaleText_loc5`='我會盡我所能淨化腐化的力量，我的火焰不會傷害到你。', `MaleText_loc7`='Purificaré toda la corrupción que pueda. Mi fuego no les dañará.', `FemaleText_loc1`='타락은 내가 정화하마. 내 불에 너희가 피해를 입진 않을 거다.', `FemaleText_loc4`='我会尽力净化一切腐化堕落；我的烈焰是不会伤害你的。', `FemaleText_loc5`='我會盡我所能淨化腐化的力量，我的火焰不會傷害到你。', `FemaleText_loc7`='Purificaré toda la corrupción que pueda. Mi fuego no les dañará.' WHERE `ID`=55778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노에서 탈출할 곳은 없다.', `MaleText_loc4`='谁都逃不过我的怒火。', `MaleText_loc5`='沒有地方能逃過我的怒火。', `MaleText_loc7`='Es imposible resguardarse de mi furia.' WHERE `ID`=55779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 따윈 아무 소용없다. 믿음은 더더욱 그렇지.', `MaleText_loc4`='你的护甲毫无作用，你的信仰一文不值。', `MaleText_loc5`='你們的護甲毫無意義，你們的信念更是垃圾。', `MaleText_loc7`='Su armadura no es nada. Su fe, menos aún.' WHERE `ID`=55780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다가 네놈들의 불에 탄 몸뚱이를 삼킬 것이다.', `MaleText_loc4`='大海将吞噬你们熊熊燃烧的尸体。', `MaleText_loc5`='大海會吞噬你們燃燒的軀體。', `MaleText_loc7`='El mar engullirá sus restos ardientes.' WHERE `ID`=55781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 세상을 갈기갈기 찢어주마.', `MaleText_loc4`='我要将这世界撕成碎片。', `MaleText_loc5`='我會將這個世界撕裂。', `MaleText_loc7`='Devastaré este mundo.' WHERE `ID`=55782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 진정한 대격변을 보여주지.', `MaleText_loc4`='我会让你们看看真正的大灾变。', `MaleText_loc5`='我會讓你們見識真正的浩劫。', `MaleText_loc7`='Les mostraré un verdadero cataclismo.' WHERE `ID`=55783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 종말을 직접 지켜봐라.', `MaleText_loc4`='亲眼见证你们世界的末日。', `MaleText_loc5`='眼睜睜看著你們世界毀滅吧。', `MaleText_loc7`='Observen mientras su mundo se acaba.' WHERE `ID`=55784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 데스윙. 피할 수 없고, 꺾을 수 없는 파괴자, 만물의 종결자. 내가 바로 대격변이다!', `MaleText_loc4`='吾名死亡之翼，天命之灭世者，万物的终结者，无可阻挡，无可违逆；吾即大灾变！', `MaleText_loc5`='我是死亡之翼，毀滅者，一切的終結者，無法逃避，也無法動搖，我，就是浩劫!', `MaleText_loc7`='¡SOY ALAMUERTE, EL DESTRUCTOR, EL FIN DE TODAS LAS COSAS, INEVITABLE, INDÓMITO; SOY EL CATACLISMO!' WHERE `ID`=55785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 파괴자의 공격을 최대한 늦춰보겠다.', `MaleText_loc4`='我会尽力放慢灭世者的攻击。', `MaleText_loc5`='我會盡量拖延毀滅者的攻擊。', `MaleText_loc7`='Ralentizaré los ataques del Destructor cuando pueda.' WHERE `ID`=55786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억양이 독특하시군요. 네 바람의 계곡 출신이십니까?', `MaleText_loc4`='你的口音很奇怪。你是从四风谷来的吗？', `MaleText_loc5`='你的口音真奇怪。你打四風峽來的嗎?', `MaleText_loc7`='Tienes un acento extraño. ¿Vienes del Valle de los Cuatro Vientos?', `FemaleText_loc1`='억양이 독특하시군요. 네 바람의 계곡 출신이신가요?', `FemaleText_loc4`='你的口音很奇怪。你是从四风谷来的吗？', `FemaleText_loc5`='你的口音真奇怪。你打四風峽來的嗎?', `FemaleText_loc7`='Tienes un acento extraño. ¿Vienes del Valle de los Cuatro Vientos?' WHERE `ID`=55787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험가신가요? 이 근방에서는 추 님이 들려주시는 이야기 말고는 모험에 대한 이야기를 별로 듣지 못합니다.', `MaleText_loc4`='你是冒险者吗？我们这儿见到冒险者，只有在老志说的那些故事里才能听到。', `MaleText_loc5`='你是冒險家嗎?我們這裡不常聽說冒險家的事，除了老祖告訴我們的那些故事。', `MaleText_loc7`='¿Eres $gun aventurero:una aventurera;? Por aquí no se escuchan muchas aventuras, aparte de las historias que nos cuenta Tzu.', `FemaleText_loc1`='모험가신가요? 이 근방에서는 추 님이 들려주시는 이야기 말고는 모험에 대한 이야기를 별로 듣지 못해요.', `FemaleText_loc4`='你是冒险者吗？我们这儿见到冒险者，只有在老志说的那些故事里才能听到。', `FemaleText_loc5`='你是冒險家嗎?我們這裡不常聽說冒險家的事，除了老祖告訴我們的那些故事。', `FemaleText_loc7`='¿Eres $gun aventurero:una aventurera;? Por aquí no se escuchan muchas aventuras, aparte de las historias que nos cuenta Tzu.' WHERE `ID`=55788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마을에 처음 오셨나요? 친 님의 국수를 꼭 드셔 보세요. 이 지역의 전설적인 명물이니까요.', `MaleText_loc4`='新来的吧？你应该去尝尝秦的面条，那可是本地一绝。', `MaleText_loc5`='新來的?你應該嚐嚐欽的麵條。那可是本地名聞遐邇的美食。', `MaleText_loc7`='¿Acabas de llegar? Deberías probar los fideos de Parrilla Rugiente. Son una leyenda local.', `FemaleText_loc1`='이 마을에 처음 오셨나요? 친 님의 국수를 꼭 드셔 보세요. 이 지역의 전설적인 명물이니까요.', `FemaleText_loc4`='新来的吧？你应该去尝尝秦的面条，那可是本地一绝。', `FemaleText_loc5`='新來的?你應該嚐嚐欽的麵條。他們可是本地的傳說美食。', `FemaleText_loc7`='¿Acabas de llegar? Deberías probar los fideos de Parrilla Rugiente. Son una leyenda local.' WHERE `ID`=55789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠과 진위가 서로에 대한 공격을 강화하기 시작했다는 소문을 들었습니다. 이러다가는 그 불쌍한 생물들이 서로를 멸망시키고 말 겁니다. 두 종족은 정말 끔찍한 관계로 얽혀 있습니다.', `MaleText_loc4`='我听说，猢狲和锦鱼人的冲突正逐渐白热化。如果不能谨慎行事的话，这些可怜的小东西会同归于尽的。他们已经陷入了一个恶性循环。', `MaleText_loc5`='我聽說猴人和錦魚人之間的衝突有越演越烈之勢。那些可憐的小生物一不小心就會毀了彼此，他們陷入了一種惡性循環裡。', `MaleText_loc7`='He oído que los hozen y los jinyu han estado aumentando sus escaramuzas. Esas pobres criaturas acabarán destruyéndose mutuamente si no tienen cuidado. Están atrapados en un ciclo devastador.', `FemaleText_loc1`='호젠과 진위가 서로에 대한 공격을 강화하기 시작했다는 소문을 들었어요. 이러다가는 그 불쌍한 생물들이 서로를 멸망시키고 말 거예요. 두 종족은 정말 끔찍한 관계로 얽혀 있어요.', `FemaleText_loc4`='我听说，猢狲和锦鱼人的冲突正逐渐白热化。如果不能谨慎行事的话，这些可怜的小东西会同归于尽的。他们已经陷入了一个恶性循环。', `FemaleText_loc5`='我聽說猴人和錦魚人之間的衝突有越演越烈之勢。那些可憐的小生物一不小心就會毀了彼此。他們陷入了一種惡性循環裡。', `FemaleText_loc7`='He oído que los hozen y los jinyu han estado aumentando sus escaramuzas. Esas pobres criaturas acabarán destruyéndose mutuamente si no tienen cuidado. Están atrapados en un ciclo devastador.' WHERE `ID`=55790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 당신은 대체 무슨 존재입니까? 저도 한창때 참 많은 것을 봤지만, 당신 같은 존재는 정말 처음입니다. 거북이가 돌아왔습니까? 저는 그게 전설 속의 이야기인 줄로만 알았었습니다.', `MaleText_loc4`='你是什么东西？我这辈子见过不少稀奇事儿，可像你这样的人还是第一次见。那只乌龟回来了吗？我一直以为那只是个传说。', `MaleText_loc5`='你是什麼?我這輩子看過很多東西，但你，我顯然是第一次見到。烏龜回來了嗎?我總是以為那是個神話。', `MaleText_loc7`='¿Y tú qué eres? He visto muchas cosas en mi vida, pero nada como tú. ¿Ha vuelto la tortuga? Siempre creí que era un mito.', `FemaleText_loc1`='그런데 당신은 대체 무슨 존재인가요? 저도 한창때 참 많은 것을 봤지만, 당신 같은 존재는 정말 처음이네요. 거북이가 돌아왔나요? 전 그게 전설 속의 이야기인 줄로만 알았었어요.', `FemaleText_loc4`='你是什么东西？我这辈子见过不少稀奇事儿，可像你这样的人还是第一次见。那只乌龟回来了吗？我一直以为那只是个传说。', `FemaleText_loc5`='你是什麼?我這輩子看過很多東西，但你，我顯然是第一次見到。烏龜回來了嗎?我總是以為那是個神話。', `FemaleText_loc7`='¿Y tú qué eres? He visto muchas cosas en mi vida, pero nada como tú. ¿Ha vuelto la tortuga? Siempre creí que era un mito.' WHERE `ID`=55791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 제대로 낮잠을 잘 준비를 하려면, 일단 여섯 번째와 일곱 번째 쪽잠을 꼭 자야 합니다.', `MaleText_loc4`='如果我每天想好好的睡上一觉，必须先打六七个小盹儿做做准备。', `MaleText_loc5`='我得做好第六和第七次小睡才行，那樣我才能準備好進行我的呼呼大睡。', `MaleText_loc7`='Tengo que echar la sexta y la séptima siesta de hoy para estar descansado y poder dormir por la noche.', `FemaleText_loc1`='오늘 제대로 낮잠을 잘 준비를 하려면, 일단 여섯 번째와 일곱 번째 쪽잠을 꼭 자야 해요.', `FemaleText_loc4`='如果我每天想好好的睡上一觉，必须先打六七个小盹儿做做准备。', `FemaleText_loc5`='我得做好第六和第七次小睡才行，那樣我才能準備好進行我的呼呼大睡。', `FemaleText_loc7`='Tengo que echar la sexta y la séptima siesta de hoy para estar descansada y poder dormir por la noche.' WHERE `ID`=55792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 조각상이 거의 완성되었습니다. 무슨 뜻인지 아십니까? 몇 달 동안 계속해서 축제를 하고, 잔치를 벌이고, 잠을 자고, 맥주를 마신다는 겁니다! 정말 기대가 됩니다!', `MaleText_loc4`='青龙雕像就要完工了。你知道那意味着什么吗？持续数月之久的狂欢、庆典、酣睡和豪饮！我等不及了！', `MaleText_loc5`='玉蛟像接近完成了。你知道那代表什麼嗎?接連幾個月的歡呼、慶祝、睡覺、喝酒!我等不及了!', `MaleText_loc7`='El dragón de jade casi está listo. ¿Sabes lo que significa eso? ¡Meses celebrando, durmiendo y destilando! ¡No veo el momento!', `FemaleText_loc1`='옥룡 조각상이 거의 완성되었어요. 무슨 뜻인지 아세요? 몇 달 동안 계속해서 축제를 하고, 잔치를 벌이고, 잠을 자고, 맥주를 마신다는 거지요! 정말 기대가 되네요!', `FemaleText_loc4`='青龙雕像就要完工了。你知道那意味着什么吗？持续数月之久的狂欢、庆典、酣睡和豪饮！我等不及了！', `FemaleText_loc5`='玉蛟像接近完成了。你知道那代表什麼嗎?接連幾個月的歡呼、慶祝、睡覺、喝酒!我等不及了!', `FemaleText_loc7`='El dragón de jade casi está listo. ¿Sabes lo que significa eso? ¡Meses celebrando, durmiendo y destilando! ¡No veo el momento!' WHERE `ID`=55793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 바구니의 내용물을 꺼내며 콧노래를 흥얼거립니다.', `MaleText_loc4`='%s一边哼着小曲，一边拿出他篮子里的东西。', `MaleText_loc5`='%s一邊把他身上的簍子卸下來，嘴裡一邊哼著小調。', `MaleText_loc7`='%s tararea una melodía mientras vacía su cesta.', `FemaleText_loc1`='%s|1이;가; 바구니의 내용물을 꺼내며 콧노래를 흥얼거립니다.', `FemaleText_loc4`='%s一边哼着小曲，一边拿出她篮子里的东西。', `FemaleText_loc5`='%s一邊把他身上的簍子卸下來，嘴裡一邊哼著小調。', `FemaleText_loc7`='%s tararea una melodía mientras vacía su cesta.' WHERE `ID`=55794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송합니다, 장 웨. 활짝 핀 꽃은 이것밖에 없습니다. 연못에 있는 꽃 대부분은 아직 피지 않았습니다.', `MaleText_loc4`='对不起，月，我所能找到的鲜花都在这里了。水池里的花大多数还没开。', `MaleText_loc5`='抱歉，月，但我能找到的盛開花朵就這些了。這池子裡的花大部份都還沒開。', `MaleText_loc7`='Lo siento, Yue, pero eso es todo lo que he podido conseguir. La mayoría de las flores de esta poza no han florecido aún.', `FemaleText_loc1`='죄송해요, 장 웨. 활짝 핀 꽃은 이것밖에 없어요. 연못에 있는 꽃 대부분은 아직 피지 않았답니다.', `FemaleText_loc4`='对不起，月，我所能找到的鲜花都在这里了。水池里的花大多数还没开。', `FemaleText_loc5`='抱歉，月，但我能找到的盛開花朵就這些了。這池子裡的花大部份都還沒開。', `FemaleText_loc7`='Lo siento, Yue, pero eso es todo lo que he podido conseguir. La mayoría de las flores de esta poza no han florecido aún.' WHERE `ID`=55795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='你说了算。', `MaleText_loc5`='你說了算。', `MaleText_loc7`='Tú mandas.', `FemaleText_loc1`='알겠어요.', `FemaleText_loc4`='你说了算。', `FemaleText_loc5`='你說了算。', `FemaleText_loc7`='Tú mandas.' WHERE `ID`=55796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘들아, 이리 모여서 "$p|1과;와; 명주숲의 무시무시한 어둠" 이야기를 들어 보려무나...', `MaleText_loc4`='召集孩子们来听“$p与恐怖的丝滑暗影”的故事……', `MaleText_loc5`='把小崽子們都找來聽「$p和恐怖的絲林暗影」的故事...', `MaleText_loc7`='Únete a los cachorros y escucha el cuento de "$p y las sombras de seda temibles"...' WHERE `ID`=55797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 저기, 명주숲 깊은 곳으로부터 평화의 사절이 되어 당당하게 나타난 분이시지.', `MaleText_loc4`='从前有一群人，他们带着和平的使命，穿行在丝木林的深处。', `MaleText_loc5`='於是，他們穿越了絲林的深處，進行一項和平任務。', `MaleText_loc7`='Así caminaban, a través de las profundidades del Sedal, en una misión de paz.' WHERE `ID`=55798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 갑자기, 검은 악마의 거미들이 악마의 세계로부터 나타났단다. 눈과 다리에 악의를 가득 품고서...', `MaleText_loc4`='可是，黑暗的邪恶蜘蛛从它们的巢穴中爬了出来，个个长着邪恶的眼睛和狞恶的长腿。', `MaleText_loc5`='但就在此時，邪惡的蜘蛛從牠們的邪惡巢穴中竄出，眼睛與細肢中充滿邪惡。', `MaleText_loc7`='Pero entonces, las oscuras y malvadas arañas emergieron de sus malvados rincones con los ojos y las patas llenas de maldad.' WHERE `ID`=55799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 다리를 뻗어 찌르고 이빨로 물고 잘근잘근 씹어 댔지만, 그 무엇도 우리의 영웅, $p|1을;를; 막을 수는 없었어!', `MaleText_loc4`='它们蛰啊、咬啊，啃啊，可就是没法打败我们的大英雄，$p！', `MaleText_loc5`='牠們戳啊咬啊嚼啊，但牠們完全沒有辦法擊敗我們的英雄，$p!', `MaleText_loc7`='¡Pincharon y mordieron y picaron, pero no pudieron hacer nada para derrotar a $gnuestro héroe:nuestra heroína;, $p!' WHERE `ID`=55800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수백 마리가 쓰러졌단다!', `MaleText_loc4`='杀千刀的！', `MaleText_loc5`='百人斬!', `MaleText_loc7`='¡CIENTOS DE DECAPITACIONES!' WHERE `ID`=55801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막대한 힘을 품은 무기를 들고, 웅장한 휘장을 차고, 우리의 영웅은 야수를 향해 분노를 내뿜었지. 아, 찬란한 모습이었단다!', `MaleText_loc4`='凭借强大的武器和崇高的精神，我们的英雄将正义之火全部倾泻在那些野兽身上。那场面，壮观极了！', `MaleText_loc5`='我們的英雄憑藉著強大的武器和華麗的招式，一股腦地將怒火傾瀉到這些野獸身上。太壯麗了!', `MaleText_loc7`='Gracias a sus poderosas armas y su magnífico atavío, $gnuestro héroe:nuestra heroína; desató su cólera sobre las bestias. ¡Fue glorioso!' WHERE `ID`=55802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야호오오!', `MaleText_loc4`='噢噢噢！！！', `MaleText_loc5`='喔喔喔!', `MaleText_loc7`='¡Ooooooh!', `FemaleText_loc1`='우와아아아!', `FemaleText_loc4`='哇哇哇！', `FemaleText_loc5`='啊啊啊!', `FemaleText_loc7`='¡Aaaaaaah!' WHERE `ID`=55804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 무슨 일이 있었어요?', `MaleText_loc4`='后来怎么样了？', `MaleText_loc5`='後來發生了什麼事?', `MaleText_loc7`='¿Y qué pasó después?', `FemaleText_loc1`='그리고 무슨 일이 있었죠?', `FemaleText_loc4`='后来怎么样了？', `FemaleText_loc5`='後來發生了什麼事?', `FemaleText_loc7`='¿Y qué pasó después?' WHERE `ID`=55805;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맥주 따르기는 여러 세대를 거치며 전해져 내려온 하나의 예술이에요. 다른 사람들한테 이게 사실인지 물어볼 필요는 없어요. 그냥 제 말을 믿으세요.', `FemaleText_loc4`='开酒桶可是一门代代相传的手艺。用不着去问别人这是不是真的，只要记住我的话就行了。', `FemaleText_loc5`='控閥是一項傳承了數個世代的技藝。不用問其他人這是不是真的。記住我的話就成了。', `FemaleText_loc7`='Tirar la cerveza es un arte que se transmite de generación en generación. No hace falta que le preguntes a nadie si es cierto o no. Simplemente créetelo.' WHERE `ID`=55808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"뭔가 심오한 것."$b$B자, 이제 누가 당신에게 "리 머그파인더를 처음 만났을 때, 그가 뭐라고 하던가요?"라고 물으면, 항상 뭔가 심오한 것이었다고 답해야 할 겁니다.', `MaleText_loc4`='“一些很有深度的话。”$b$B好了。以后如果有人问你第一次见到李·寻杯时他都说了什么，你就可以回答说了“一些很有深度的话。”', `MaleText_loc5`='很深奧的事。$b$b成啦。現在無論什麼人問你，杯尋者小李和你初次會面時說了什麼?那就是「很深奧的事」。', `MaleText_loc7`='"Algo profundo".$b$bEso. Ahora, cuando alguien te pregunte qué te dijo Lee Jarra Inagotable la primera vez que lo conociste, siempre les dirás que fue algo profundo.' WHERE `ID`=55809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 술통을 만듭니다. 깨달음을 얻지 못한 이들에게는 참 단순한 일처럼 들리겠지만, 술통에 사용하는 재료에 따라 그 안에 담긴 음료의 맛이 얼마나 달라지는지 알고 나면 당신도 아마 깜짝 놀랄 겁니다.', `MaleText_loc4`='我是一个酒桶匠。对外行来说，这门手艺似乎很简单。但酒桶的用料对于酒水口味的影响之大，绝对会出乎你的意料。', `MaleText_loc5`='我製作桶子。聽起來平凡無奇，但你會驚訝於桶子的材料對裡面酒的味道有多大的影響。', `MaleText_loc7`='Fabrico barriles. Puede sonar simple para los incultos, pero te sorprendería cuánto afecta el tipo de material que utilizas para construirlos al sabor de la bebida que encierran.' WHERE `ID`=55810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님!$B$B우리가 재배하고 수확하는 연꽃은 판다리아를 통틀어 최상품이랍니다. 이곳에서 수확한 연꽃은 신 사이페라의 마을로 보내 선별 작업을 거친 뒤 전 지역으로 운송되고요.$B$B연꽃은 요리 재료 및 약재용, 그리고 장식용과 같이 아주 다양한 용도로 사용할 수 있어요. 짐작하시겠지만 수요도 꽤 된답니다.', `FemaleText_loc4`='你好，$c！$B$B我们这里养殖着全潘达利亚最好的莲花。我们的莲花从这里送到下面的新希菲拉村，然后在那里分类和装船，最后运送到各地。$B$B莲花的用途广泛，在烹饪、医疗和装饰领域都能发挥作用——所以你也能想到，它的需求量是很大的。', `FemaleText_loc5`='你好啊，$c!$B$B我們栽種與採收的蓮花在潘達利亞是數一數二的。蓮花採收下來以後，便送到新席非拉的村子去，在那裡分類並船運到世界各地。$B$B蓮花可以運用在烹飪、醫藥以及裝飾上，有數不盡的用途。想當然耳，需求量自然也很高。', `FemaleText_loc7`='¡Hola, $c!$B$BCultivamos y cosechamos las mejores flores de loto de toda Pandaria. Desde aquí las enviamos a la aldea de Nueva Cifera, donde las clasifican y distribuyen por todas partes.$B$BEl loto tiene incontables aplicaciones culinarias, medicinales y decorativas. Como te puedes imaginar, hay mucha demanda.' WHERE `ID`=55811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 너희가 여기 일어난 일의 원흉인가...?', `MaleText_loc4`='你们！这一切都是你们造成的吗……？', `MaleText_loc5`='你!你們就是這一切的罪魁禍首嗎...?', `MaleText_loc7`='¡Ustedes! ¿Son los responsables de lo que ha pasado aquí...?' WHERE `ID`=55812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 이곳에 어떤 사악한 기운을 풀어놓았는지는 아느냐? 조상님의 명예를 걸고 널 벌하겠다!', `MaleText_loc4`='都是因为你们，黑暗和恐惧玷污了这片圣地！为了先祖的荣耀，我要亲手惩罚你们！', `MaleText_loc5`='你們給這個地方帶來了什麼樣的恐怖啊?以我先祖之名，我會懲罰你們!', `MaleText_loc7`='¿Qué oscuras monstruosidades han traído a este lugar? Por el honor de mis ancestros, ¡lo pagarán muy caro!' WHERE `ID`=55813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴... 어디인가? 내가 무슨 짓을? 아버님, 저를 용서하십시오...', `MaleText_loc4`='这是……什么地方？我……干了什么？原谅我，父亲……', `MaleText_loc5`='這是...什麼地方?我...做了什麼事?原諒我，父親...', `MaleText_loc7`='¿Dónde... estoy? ¿Qué... he hecho? Perdóname, padre.' WHERE `ID`=55814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 죗값을 치렀구나!', `MaleText_loc4`='这就是你付出的代价！', `MaleText_loc5`='這就是你的代價!', `MaleText_loc7`='¡Este es el precio que pagarán!' WHERE `ID`=55815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 심판을 받아라!', `MaleText_loc4`='公正的惩罚！', `MaleText_loc5`='很公平的懲罰!', `MaleText_loc7`='¡Un simple castigo!' WHERE `ID`=55816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오만함의 대가를 치뤄라!', `MaleText_loc4`='尝尝傲慢的苦果吧！', `MaleText_loc5`='因你的自大受苦吧!', `MaleText_loc7`='¡Sufran por su arrogancia!' WHERE `ID`=55817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 곳은 없다!', `MaleText_loc4`='你们无处可逃了！', `MaleText_loc5`='你們無路可逃了!', `MaleText_loc7`='¡No escaparán!' WHERE `ID`=55818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노에는 끝이 없다!', `MaleText_loc4`='我的怒火无边！', `MaleText_loc5`='我的憤怒沒有極限!', `MaleText_loc7`='¡Mi cólera no tiene límites!' WHERE `ID`=55819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 받고 싶단 말인가? 자네가!?', `MaleText_loc4`='你想接受试炼？就凭你！？', `MaleText_loc5`='你想接受訓練?你?!', `MaleText_loc7`='¿Que quieres entrenarte? ¿¡TÚ!?' WHERE `ID`=55820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대나무 깨기 시험을 치를 준비가 됐습니다.', `MaleText_loc4`='我已经准备好接受竹之试炼了。', `MaleText_loc5`='我已經準備好接受竹之試煉了。', `MaleText_loc7`='Estoy listo para la prueba del bambú.', `FemaleText_loc1`='대나무 깨기 시험을 치를 준비가 됐어요.', `FemaleText_loc4`='我已经准备好接受竹之试炼了。', `FemaleText_loc5`='我已經準備好接受竹之試煉了。', `FemaleText_loc7`='Estoy lista para la prueba del bambú.' WHERE `ID`=55821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹을 쓸 준비가 됐습니다. 송판 깨기 시험을 치러보겠습니다.', `MaleText_loc4`='我的拳头已蓄势待发，想继续接受木之试炼。', `MaleText_loc5`='我的拳頭熱好了。進行木之試煉吧。', `MaleText_loc7`='Mis puños están listos. Que empiece la prueba de la madera.', `FemaleText_loc1`='주먹을 쓸 준비가 됐어요. 송판 깨기 시험을 치러볼게요.', `FemaleText_loc4`='我的拳头已蓄势待发，想继续接受木之试炼。', `FemaleText_loc5`='我的拳頭已經熱了。進行木之試煉吧。', `FemaleText_loc7`='Mis puños están listos. Que empiece la prueba de la madera.' WHERE `ID`=55822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 요청하셨던 시험을 다 마쳤습니다. 이제 돌 깨기 시험을 치를 준비가 됐습니다.', `MaleText_loc4`='我已经完成了你所有的要求。我已经准备好接受石之试炼了。', `MaleText_loc5`='我已經完成你之前的所有要求。現在我準備好接受石之試煉了。', `MaleText_loc7`='He hecho todo lo que me has pedido. Estoy listo para la prueba de la piedra.', `FemaleText_loc1`='제게 요청하셨던 시험을 다 마쳤어요. 이제 돌 깨기 시험을 치를 준비가 됐어요.', `FemaleText_loc4`='我已经完成了你所有的要求。我已经准备好接受石之试炼了。', `FemaleText_loc5`='我已經完成你之前的所有要求。現在我準備好接受石之試煉了。', `FemaleText_loc7`='He hecho todo lo que me has pedido. Estoy lista para la prueba de la piedra.' WHERE `ID`=55823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s|1이;가; |cFFFF0000|Hspell:105651|h[엘레멘티움 화살]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s开始施放|cFFFF0000|Hspell:105651|h[源质箭]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s開始施放|cFFFF0000|Hspell:105651|h[源質箭]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_meteorstorm.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:105651|h[Descarga de elementium]|h|r!' WHERE `ID`=55826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기요!$B$B<눈을 가늘게 뜨고 당신을 노려보는 어린 소녀>$B$B저기 원로 현자님과 이야기하시는 걸 들었어요. 꽤나 진지한 분이시죠?$B$B다행인 줄 아세요. 사실 저는 이 주변에서 일어나는 일을 엿듣는 게 취미거든요.', `FemaleText_loc4`='嗨，你好啊！$B$B<小女孩瞥了你一眼。>$B$B我无意中听到了你和大贤者的谈话。他这个人太严肃了，不是吗？$B$B哈哈，这回你可走运了，因为我碰巧知道这周围发生的所有事情。', `FemaleText_loc5`='嘿你!$B$B<小女孩斜眼看著你。>$B$B我聽到你和大司祭的談話。他很嚴肅，對嗎?$b$b好吧你很幸運，因為這附近發生的所有事情幾乎都逃不過我的耳朵。', `FemaleText_loc7`='¡Oye!$b$b<La pequeña te mira con los ojos entornados.>$b$bHe oído la conversación que has tenido con el ancestro sabio. Es bastante serio, ¿a que sí?$b$bTienes suerte porque yo oigo casi todo lo que pasa por aquí.' WHERE `ID`=55827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 이방인들이여. 이제 너희의 진짜 힘을 보여다오.', `MaleText_loc4`='很好，陌生人。让我看看你们有多大能耐。', `MaleText_loc5`='那好，外地人。就讓我們見識一下你的真本事。', `MaleText_loc7`='Muy bien, forasteros. Comprobemos su verdadera fuerza.' WHERE `ID`=55828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 사용하는 기술은 무력의 물리적 표출에 지나지 않지. 내가 정신력의 진가를 보여주마!', `MaleText_loc4`='会舞刀弄枪只能证明你们身子骨不错，略懂武学。让我告诉你们什么才是融汇真气之力。', `MaleText_loc5`='熟練兵器不過是一個人武學技巧的外在展現。我要讓你看看什麼是精神的力量!', `MaleText_loc7`='La habilidad con las armas no es más que una manifestación física de las artes marciales. ¡Les mostraré lo que es el poder espiritual!' WHERE `ID`=55829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 풋내기였던 시절에는 정권 지르기 한 번도 버거웠다. 하지만 수년간 뼈를 깎는 수련을 거듭한 지금은 달라!', `MaleText_loc4`='少不更事的时候，我连打出一记好拳都难，但经过多年修炼，我已今非昔比！', `MaleText_loc5`='在我小的時候連拳頭都揮不好，可是長年訓練以後，我厲害了許多!', `MaleText_loc7`='Cuando era un cachorro apenas podía dar puñetazos. Tras años de entrenamiento, puedo hacer muchísimo más.' WHERE `ID`=55830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요! 쉿! 이쪽으로 와보실래요?', `FemaleText_loc4`='嗨，陌生人！嘿！快过来！', `FemaleText_loc5`='嘿，陌生人!唷!過來這裡!', `FemaleText_loc7`='¡Oye, $gforastero:forastera;! ¡Pssst! ¡Ven aquí!' WHERE `ID`=55831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 패배다. 조금 있다가 함께 샤를 상대하러 가자꾸나.', `MaleText_loc4`='我被打败了。让我休息一下，我们将一起面对煞的挑战。', `MaleText_loc5`='我敗了。給我一點時間，我們就一起前往面對煞。', `MaleText_loc7`='Me han vencido. Dejen que me recupere y juntos nos enfrentaremos a los sha.' WHERE `ID`=55832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 혼란스럽게 날뛰고 있습니다. 무언가 물을 자극합니다.', `MaleText_loc4`='这里的水开始变得狂野而混乱，一定有什么东西在扰动它们。', `MaleText_loc5`='水變得狂亂混濁。有什麼煽動了他們。', `MaleText_loc7`='El agua está salvaje y caótica. Algo la agita.' WHERE `ID`=55833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 혼란을 이해하려면, 물과 대화해야 합니다.', `MaleText_loc4`='我必须与流水谈一谈，才能了解它们的骚动源自何处。', `MaleText_loc5`='我得和水談話來理解它們為何騷動。', `MaleText_loc7`='Debo hablar con el agua para comprender su inquietud.' WHERE `ID`=55834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 덕분에 저도 일을 계속할 수 있습니다.', `MaleText_loc4`='多亏了你，我现在可以继续工作了。', `MaleText_loc5`='多虧了你，我的工作得以繼續。', `MaleText_loc7`='Gracias a ti puedo continuar con mi trabajo.' WHERE `ID`=55835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님, 지팡이를 찾았습니다.', `MaleText_loc4`='长老，我找到你的法杖了。', `MaleText_loc5`='長者，我找到你的法杖了。', `MaleText_loc7`='Ancestro, he encontrado tu bastón.', `FemaleText_loc1`='장로님, 지팡이를 찾았어요.', `FemaleText_loc4`='长老，我找到你的法杖了。', `FemaleText_loc5`='長者，我找到你的法杖了。', `FemaleText_loc7`='Ancestro, he encontrado tu bastón.' WHERE `ID`=55836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지팡이에는 제 조상들로부터 내려오는 힘이 담겨 있습니다. 찾아주셔서 감사합니다.', `MaleText_loc4`='这根法杖承载了我世代相传的先祖之力。感谢你把它归还给我。', `MaleText_loc5`='這法杖擁有祖先傳承下來的法力。謝謝你送回來給我。', `MaleText_loc7`='Este bastón contiene poderes transmitidos por mis ancestros. Gracias por devolvérmelo.' WHERE `ID`=55837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앉아!', `MaleText_loc4`='坐下！', `MaleText_loc5`='坐下!', `MaleText_loc7`='¡SIÉNTATE!' WHERE `ID`=55838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사에 잘 왔네, 이방인.$B$B우린 찾아오는 손님을 모두 환영하고, 구하는 자에게는 자유로이 지식을 전해주지.', `MaleText_loc4`='欢迎来到青龙寺，旅行者。$B$B我们欢迎所有的来访者，并将知识自由传授给所有求知的人。', `MaleText_loc5`='歡迎來到玉蛟寺，旅人。$B$B我們的大門為所有人而開，我們的知識歡迎所有追尋者來取。', `MaleText_loc7`='$gBienvenido:Bienvenida; al Templo del Dragón de Jade, $gviajero:viajera;.$b$bDamos la bienvenida a todo el mundo y ofrecemos nuestra sabiduría a todo aquel que la busca.' WHERE `ID`=55839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 어서 움직입시다!', `MaleText_loc4`='好吧，我们继续！', `MaleText_loc5`='好啦，我們動身吧!', `MaleText_loc7`='¡Muy bien, sigamos avanzando!' WHERE `ID`=55840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 에메랄드의 꿈으로 너희를 인도하마. 전투가 너무 치열해지면, 안전한 그곳으로 이동해라.', `MaleText_loc4`='我会让你们离翡翠梦境更近一些。当战斗太过激烈的时候可以进入梦境寻求庇护。', `MaleText_loc5`='我會帶你到靠近翡翠夢境的地方。如果戰鬥太過激烈，可以在那裡喘口氣。', `MaleText_loc7`='Los acercaré al Sueño Esmeralda. Busquen cobijo en él cuando el combate sea demasiado intenso.' WHERE `ID`=55843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 자네만이 이 일을 시작할 수 있네!', `MaleText_loc4`='英雄们，进攻。只有你们能为我们创造机会！', `MaleText_loc5`='只有你們能替我們突破!', `MaleText_loc7`='¡Son los únicos que nos pueden ofrecer un comienzo!' WHERE `ID`=55844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 용사들이 데스윙의 헛점을 노출시킬 유일한 희망입니다. 힘을 합치면, 이길 수 있습니다.', `MaleText_loc4`='要让死亡之翼暴露弱点，这些英雄是唯一的希望。团结，我们终将胜利。', `MaleText_loc5`='只有這些英雄才能幫我們製造出死亡之翼的破綻。我們可以合力取勝。', `MaleText_loc7`='Estos campeones son nuestra única esperanza para mostrar la debilidad de Alamuerte. Juntos podremos vencer.' WHERE `ID`=55845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기말게. 자네들이라면 데스윙을 막을 수 있어.!', `MaleText_loc4`='别放弃。击败死亡之翼的希望寄托在你们身上了。', `MaleText_loc5`='不要放棄!我們就靠你們擊退死亡之翼了。', `MaleText_loc7`='¡No se rindan! Contamos con ustedes para hacer retroceder a Alamuerte.' WHERE `ID`=55846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사악한 옥의 마녀에게서 날 구해줘서 정말 고맙네, $p.$b$b아직도 다리가 뻣뻣하군. 병사들에게 명령은 내릴 수 있을 것 같네. 물론 이 생물들을 병사라고 부를 수 있다면 말이지만. 그래도 내가 직접 전투에 참여하기는 힘들 것 같군.', `MaleText_loc4`='谢谢你，$p，你把我从那个邪恶的巫婆手里救了出来。$b$b虽然我的腿到现在还有点僵硬。但我可以帮你指挥士兵——如果这些家伙也能算士兵的话。但我恐怕没法在战场上起多大作用了。', `MaleText_loc5`='謝謝你從那邪惡的玉巫婆手中拯救我，$p。$b$b我的腿到現在都還很僵硬。我可以號令士兵，如果這些生物稱得上士兵的話。但我想我在戰鬥中派不上什麼用場。', `MaleText_loc7`='$p, muchas gracias por salvarme de la malvada Bruja de Jade.$b$bIncluso ahora, sigo teniendo las patas rígidas. Puedo dirigir a los soldados, si es que se les puede llamar así a estas criaturas. Pero creo que no seré de gran ayuda en ningún combate.' WHERE `ID`=55847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFFFF0000|Hspell:107018|h[알렉스트라자]|h|r를 공격합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFFFF0000|Hspell:107018|h[阿莱克丝塔萨]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻擊了|cFFFF0000|Hspell:107018|h[雅立史卓莎]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_deathwing_assualtaspects.blp:20|t¡%s ataca a |cFFFF0000|Hspell:107018|h[Alexstrasza]|h|r!' WHERE `ID`=55848;
