UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFF04FC32|Hspell:107018|h[이세라]|h|r를 공격합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFF04FC32|Hspell:107018|h[伊瑟拉]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻擊了|cFF04FC32|Hspell:107018|h[伊瑟拉]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_deathwing_assualtaspects.blp:20|t¡%s ataca a |cFF04FC32|Hspell:107018|h[Ysera]|h|r!' WHERE `ID`=55850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFF5858FA|Hspell:107018|h[칼렉고스]|h|r를 공격합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻击|cFF5858FA|Hspell:107018|h[卡雷苟斯]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s攻擊了|cFF5858FA|Hspell:107018|h[卡雷苟斯]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_deathwing_assualtaspects.blp:20|t¡%s ataca a |cFF5858FA|Hspell:107018|h[Kalecgos]|h|r!' WHERE `ID`=55851;
