UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s|1이;가; |cFFFF0000|Hspell:107018|h[위상 공격]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s开始施放|cFFFF0000|Hspell:107018|h[攻击守护巨龙]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s開始施展|cFFFF0000|Hspell:107018|h[突襲形態]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_deathwing_assualtaspects.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:107018|h[Atacar a Aspectos]|h|r!' WHERE `ID`=55853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조준!', `MaleText_loc4`='瞄准！', `MaleText_loc5`='瞄準!', `MaleText_loc7`='¡Apunta!' WHERE `ID`=55854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='发射！', `MaleText_loc5`='投擲!', `MaleText_loc7`='¡LANZAD!' WHERE `ID`=55855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 응가 덩어리들이 우낏 또 못 맞췄다! 바보들!', `MaleText_loc4`='你们这些白痴没打中蠢蛋！再来！', `MaleText_loc5`='你這笨蛋又沒丟到怪怪人!重來!', `MaleText_loc7`='¡Dingues penkos no han dado al makaku! ¡OTRA VEZ!' WHERE `ID`=55856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅 위의 벌레들처럼 끝장내 주마!', `MaleText_loc4`='你看起来就像个旱鸭子！', `MaleText_loc5`='你丟的像在地上爬的一樣!', `MaleText_loc7`='¡Tú lanza komo un dos patas!' WHERE `ID`=55857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 멍청해도 아픔이 느껴지냐?', `MaleText_loc4`='变得像你这么笨会不会很伤？', `MaleText_loc5`='像你這麼笨會覺得痛嗎?', `MaleText_loc7`='¿Duele ser tan $gestúpido:estúpida; como tú?' WHERE `ID`=55858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 속도라면 내가 늙어 죽는 게 더 빠르겠구나.', `MaleText_loc4`='按照这个速度，我很快就要自然死亡了。', `MaleText_loc5`='這樣下去我可能會先自然老死。', `MaleText_loc7`='A este paso me moriré antes por causas naturales.' WHERE `ID`=55859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 아무것도 못 했다. 내가 이 세상을 조각내주마.', `MaleText_loc4`='你们什么都没做到。我要撕碎你们的世界。', `MaleText_loc5`='你們都徒勞無功。我會撕裂你們的世界。', `MaleText_loc7`='No has hecho nada. Despedacaré tu mundo.' WHERE `ID`=55860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아기 채찍꼬리랩터를 잃어버렸습니다.', `MaleText_loc4`='我的鞭尾幼龙不见了。', `MaleText_loc5`='我把我的小鞭尾迅猛龍搞丟了。', `MaleText_loc7`='He perdido mi prole de colazote.', `FemaleText_loc1`='아기 채찍꼬리랩터를 잃어버렸어요.', `FemaleText_loc4`='我的鞭尾幼龙不见了。', `FemaleText_loc5`='我把我的小鞭尾迅猛龍搞丟了。', `FemaleText_loc7`='He perdido mi prole de colazote.' WHERE `ID`=55875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 표범을 잃어버렸습니다.', `MaleText_loc4`='我的猎豹幼崽不见了。', `MaleText_loc5`='我把我的獵豹寶寶搞丟了。', `MaleText_loc7`='He perdido mi cachorro de pantera.', `FemaleText_loc1`='새끼 표범을 잃어버렸어요.', `FemaleText_loc4`='我的猎豹幼崽不见了。', `FemaleText_loc5`='我把我的獵豹寶寶搞丟了。', `FemaleText_loc7`='He perdido mi cachorro de pantera.' WHERE `ID`=55879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풍선을 잃어버렸습니다.', `MaleText_loc4`='我的气球不见了。', `MaleText_loc5`='我把我的氣球搞丟了。', `MaleText_loc7`='He perdido mi globo.', `FemaleText_loc1`='풍선을 잃어버렸어요.', `FemaleText_loc4`='我的气球不见了。', `FemaleText_loc5`='我把我的氣球搞丟了。', `FemaleText_loc7`='He perdido mi globo.' WHERE `ID`=55880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지?', `MaleText_loc4`='你想要什么？', `MaleText_loc5`='你想要什麼?', `MaleText_loc7`='¿Qué quieres?' WHERE `ID`=55881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코도가 길에서 기다리고 있네. 몸성히 다녀오기를 바라겠네.', `FemaleText_loc4`='科多兽已经等在路上了。一路顺风，$G兄弟:姐妹;。', `FemaleText_loc5`='科多獸已經在路上等了。一路平安，$G兄弟:姊妹;。', `FemaleText_loc7`='Los kodos aguardan en el camino. Buen viaje, $Ghermano:hermana;.' WHERE `ID`=55882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 녀석들을 훈련시킬 수 있을 거라고는 생각도 못 했었어요.', `FemaleText_loc4`='真想不到这些野猴子也能训练有素。', `FemaleText_loc5`='我從沒想過這些大頭呆可以被訓練。', `FemaleText_loc7`='Nunca pensé que fuera posible adiestrar a esos brutos.' WHERE `ID`=55887;
