UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅들이여! 노즈도르무 님의 명을 받고 왔습니다! 어서 타세요. 용의 영혼으로 가야 합니다!', `FemaleText_loc4`='英雄们！是诺兹多姆派我们来的！快上来，我们要把你们带到巨龙之魂那儿！', `FemaleText_loc5`='英雄們!諾茲多姆派我們來這!快跳到我們背上，我們必須帶你們去巨龍之魂!', `FemaleText_loc7`='¡Héroes! ¡Nos envía Nozdormu! De prisa, suban a nuestros lomos, ¡los llevaremos hasta el Alma de dragón!' WHERE `ID`=55914;
