UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 잘 왔다. 곧 있을 기쁜 일에 동참하러 왔겠지? 아니라고? 애석하군.', `FemaleText_loc4`='啊，欢迎。你们也是来参加庆祝仪式的？不是？真可惜。', `FemaleText_loc5`='啊，歡迎啊。是來加入我們的慶典嗎?不是嗎?真可惜啊。', `FemaleText_loc7`='Bienvenidos. ¿Vienen a unirse a nuestra celebración? ¿No? Qué lástima.' WHERE `ID`=55919;
