UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨습니다.', `MaleText_loc4`='麦龙下达了疏散命令。', `MaleText_loc5`='輪眉宣布了撤離命令。', `MaleText_loc7`='Loon Mai ha dado orden de evacuar.', `FemaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨어요.', `FemaleText_loc4`='麦龙下达了疏散命令。', `FemaleText_loc5`='輪眉宣布了撤離命令。', `FemaleText_loc7`='Loon Mai ha dado orden de evacuar.' WHERE `ID`=55923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저는 잘 모르겠군요. 제가 나이도 들고 또 항상...', `MaleText_loc4`='哦，我不清楚。我老了，而且常常……', `MaleText_loc5`='喔我不知道。我老了，而且我總是...', `MaleText_loc7`='Oh, no lo sé. Soy viejo y siempre he...' WHERE `ID`=55924;
