UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이날이 올까 봐 두려움에 떨고 있었습니다. 어서 짐을 챙겨야겠군요.', `MaleText_loc4`='我就怕这一天会到来。我去收拾东西。', `MaleText_loc5`='我擔心這一天總會到來。我要來整理行囊了。', `MaleText_loc7`='Temía que llegara este día. Recogeré mis cosas.' WHERE `ID`=55926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 또 누가 왔잖아? 사령관 룬 마이가 보낸 겁니까? 그 돌머리에게 대체 몇 번을 말해야 하는 건지 참... 우리는 대피하지 않습니다!', `MaleText_loc4`='怎么，又来一个？指挥官麦龙派你来的？$b$b我跟那个蠢蛋说了多少次了—我们绝不撤离！', `MaleText_loc5`='什麼，又一個?是輪眉指揮官派你來的嗎?$b$b我得跟那個笨蛋講多少次?我們不會撤離!', `MaleText_loc7`='¿Qué, otro? ¿Te envía el comandante Mai?$b$bCuántas veces tengo que decirle a ese estúpido... ¡que no nos vamos!' WHERE `ID`=55927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 룬 마이 사령관님께서 저를 이곳으로 보내셨습니다. 사령관님께서 내리신 대피 명령을 전달하러 왔습니다.', `MaleText_loc4`='是的，指挥官麦龙派我来的，我带来了他的紧急疏散令。', `MaleText_loc5`='是的，指揮官輪眉派我來的，我帶著他的撤離命令。', `MaleText_loc7`='Sí, me ha enviado el comandante Mai y traigo sus órdenes de evacuación.', `FemaleText_loc1`='네, 룬 마이 사령관님께서 저를 이곳으로 보내셨어요. 사령관님께서 내리신 대피 명령을 전달하러 왔답니다.', `FemaleText_loc4`='是的，指挥官麦龙派我来的，我带来了他的紧急疏散令。', `FemaleText_loc5`='是的，指揮官輪眉派我來的，我帶著他的撤離命令。', `FemaleText_loc7`='Sí, me ha enviado el comandante Mai y traigo sus órdenes de evacuación.' WHERE `ID`=55928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칫... 외부인들이란. 돌밭의 방식을 아는 게 하나도 없잖아요.', `FemaleText_loc4`='嘁……外来者。你对石犁之道一无所知。', `FemaleText_loc5`='呿...外來的傢伙。你們根本不懂石犁之道。', `FemaleText_loc7`='Bah... forasteros. No saben nadas de las costumbres de Villarroca.' WHERE `ID`=55929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 자랑스럽고 강하다고요. 또 농부의 피를 이어받았고... 곤경에서 도망치지 않아요.', `FemaleText_loc4`='我们很自豪。我们很强大。我们是阡陌客的后裔……我们决不会逃避困难。', `FemaleText_loc5`='我們自豪，我們強大，我們是耕者們的直系血脈...我們不逃避眼前的麻煩。', `FemaleText_loc7`='Somos orgullosos. Somos fuertes. Somos descendientes de la sangre del mismísimo Labrador... y no huimos de los problemas.' WHERE `ID`=55930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞는 말입니다. 자, $r님, 이제 우리 것을 스스로 지켜내도록 해주십시오.', `MaleText_loc4`='没错。所以，$r，你还是快走吧，让我们来保卫自己的财产。', `MaleText_loc5`='沒錯。現在，$r，請離開這裡，讓我們保衛我們的家園。', `MaleText_loc7`='Eso es. Ahora márchate, $r, y déjanos defender nuestra propiedad, por favor.' WHERE `ID`=55931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나라!!$b$b가만... 당신은 그놈들과 한패가 아니군요. 우리는 외부인과의 접촉에 익숙하지 않습니다. 그리고 저 사마귀 놈들까지 벽을 부수고 들어오다 보니 제가...$b$b어쨌든, 우리가 뭘 도와드리면 되겠습니까?', `MaleText_loc4`='退后！$b$b等等……你不是它们的一员。我们不习惯有外人，在螳螂妖破墙而入的当下，我……$b$b无论如何，我们能为你做些什么？', `MaleText_loc5`='退後!$b$b等等...你不是跟他們一伙的。我們不常見到外來人，加上那些螳螂人不斷往長城這一端滲透，我...$b$b無論如何，我們可以幫你什麼?', `MaleText_loc7`='¡Atrás!$b$bEspera... tú no eres uno de ellos. No estamos acostumbrados a recibir forasteros, y con los mántides a punto de atravesar la muralla, yo...$b$bEn fin, ¿qué podemos hacer por ti?' WHERE `ID`=55932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨습니다.', `MaleText_loc4`='麦龙下达了疏散命令。', `MaleText_loc5`='輪眉宣布了撤離命令。', `MaleText_loc7`='Loon Mai ha dado orden de evacuar.', `FemaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨어요.', `FemaleText_loc4`='麦龙下达了疏散命令。', `FemaleText_loc5`='輪眉宣布了撤離命令。', `FemaleText_loc7`='Loon Mai ha dado orden de evacuar.' WHERE `ID`=55933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 전쟁이 끝날 때까지 기다렸으면 좋겠지만, 사령관님께서 우리가 떠나기를 원하신다면 그렇게 하겠습니다.', `MaleText_loc4`='我明白了。我本来觉得我们可以挺过这场入侵的，但如果上面想让我们离开的话，那我们就离开。', `MaleText_loc5`='我知道了。我自己是希望能撐到這場入侵結束，但如果上層希望我們撤退，我們只能撤退。', `MaleText_loc7`='Entiendo. Esperaba que pudiéramos resistir a esta invasión, pero si las autoridades quieren que nos vayamos, nos iremos.' WHERE `ID`=55934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 짐을 챙기시오. 후이종도... 어서 짐을 챙기거라. 안전해질 때까지 밭에서 떠나야겠다.', `MaleText_loc4`='瑛、辉钟……去收拾东西。等农场安全了，我们再回来。', `MaleText_loc5`='瑩、慧中...整理你們的行李，我們要離開農場避難。', `MaleText_loc7`='Ying, Huizhong... recogan sus cosas. Nos marchamos de la granja hasta que sea seguro volver.' WHERE `ID`=55935;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 여보...', `FemaleText_loc4`='噢，亲爱的……', `FemaleText_loc5`='喔，親愛的...', `FemaleText_loc7`='Oh, cielo...' WHERE `ID`=55936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 이 착한 분이 나쁜 사마귀들 처치해주신다는 거야?', `FemaleText_loc4`='爸爸，这个好人要杀死所有的的坏螳螂妖士兵吗？', `FemaleText_loc5`='爸爸，這個好人會去殺光那些螳螂人戰士嗎?', `FemaleText_loc7`='Papi, ¿esta buena persona va a matar a todos los soldados mántides malos?' WHERE `ID`=55937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 모르겠구나, 애야...', `MaleText_loc4`='我不知道，亲爱的。', `MaleText_loc5`='我不知道，親愛的。', `MaleText_loc7`='No lo sé, cariño.' WHERE `ID`=55938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래주실 겁니까?', `MaleText_loc4`='你会怎么做呢？', `MaleText_loc5`='你會去嗎?', `MaleText_loc7`='¿Los matarás?' WHERE `ID`=55939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드릴까요, $c님?', `MaleText_loc4`='我能帮你什么吗，$c？', `MaleText_loc5`='我能幫上什麼忙嗎，$c?', `MaleText_loc7`='¿En qué puedo ayudarte, $c?' WHERE `ID`=55940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨습니다.', `MaleText_loc4`='麦龙下达了疏散命令。', `MaleText_loc5`='輪眉宣布了撤離命令。', `MaleText_loc7`='Loon Mai ha dado orden de evacuar.', `FemaleText_loc1`='룬 마이 사령관님께서 대피 명령을 내리셨어요.', `FemaleText_loc4`='麦龙下达了疏散命令。', `FemaleText_loc5`='輪眉宣布了撤離命令。', `FemaleText_loc7`='Loon Mai ha dado orden de evacuar.' WHERE `ID`=55941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 내쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=55942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 저는 농부입니다. 농사 빼고는 제가 아는 게 뭐가 있겠습니까.', `MaleText_loc4`='我是个农民，$c。我只知道这一点。', `MaleText_loc5`='我是個農夫，$c。這就是我所懂的一切。', `MaleText_loc7`='Soy un granjero, $c. Es todo lo que sé.' WHERE `ID`=55943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 가진 거라고는 땅이 전부입니다. 그런데도 사령관님께서는 우리 보고 이 땅을 사마귀 놈들에게 양보하라는 겁니까?', `MaleText_loc4`='除了土地，我们一无所有。那位指挥官却想让我们把它拱手让给螳螂妖？', `MaleText_loc5`='我們唯一擁有的就是我們的土地。而指揮官希望我們將它拱手讓給這些螳螂人?', `MaleText_loc7`='La tierra es lo único que tenemos... ¿y nuestro comandante quiere que se la entreguemos a los mántides?' WHERE `ID`=55944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 안 그럴 겁니다. 할아버지께서 용의 척추 가까운 곳에 처음 씨앗을 심었을 때 어떤 문제가 생길지 이미 알고 계셨거든요.', `MaleText_loc4`='我不会那么做的。在蟠龙脊的阴凉中播下第一粒种子开始，我的祖父就知道将来会变成什么样子。', `MaleText_loc5`='我不會這樣做。我祖父在蟠龍脊的影子裡種下第一顆種子的時候，心中就清楚他要面對什麼樣的東西。', `MaleText_loc7`='No lo haré. Mi abuelo sabía a lo que se exponía cuando plantó la primera semilla en la sombra del Espinazo del Dragón.' WHERE `ID`=55945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 아내가 있고, 강인한 딸과 아들도 둘씩이나 있습니다. 말씀은 감사합니다만 우리 밭은 우리가 지킬 수 있습니다.', `MaleText_loc4`='我有妻子，两个健壮的女儿，还有两个强壮的儿子。谢谢你，但我们能保卫这个农场。', `MaleText_loc5`='我有妻子，兩個強壯的女兒，還有兩個強壯的兒子。謝謝你，但我們可以自己保護這個農場。', `MaleText_loc7`='Tengo a mi esposa, dos fuertes hijas y dos fuertes hijos. Gracias, pero podemos proteger esta granja nosotros solos.' WHERE `ID`=55946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 대피 명령서가 아니었으면 좋겠군요.', `FemaleText_loc4`='但愿我看到的那些纸不是疏散令。', `FemaleText_loc5`='我看到的那個最好不是撤離命令。', `FemaleText_loc7`='Será mejor que eso que veo no sean papeles de evacuación.' WHERE `ID`=55947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌밭에 오신 것을 환영해요. 뭘 도와드릴까요?', `FemaleText_loc4`='欢迎来到石犁村。能为你做点什么吗？', `FemaleText_loc5`='歡迎來到石犁村。我們能幫上什麼忙嗎?', `FemaleText_loc7`='Te damos la bienvenida a Villarroca. ¿Qué podemos hacer por ti?' WHERE `ID`=55948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난장판이라 죄송해요. 지금 바빠서 아주 정신이 없거든요.$b$b제가 어떻게 도와드리면 될까요?', `FemaleText_loc4`='对不起，这里一团乱。什么都是乱糟糟的。$b$b我能帮你什么吗？', `FemaleText_loc5`='我為這一片混亂感到抱歉。眼前的情況有點麻煩。$b$b我能幫你什麼嗎?', `FemaleText_loc7`='Disculpa este desorden. Todo se ha vuelto un poco loco últimamente.$b$b¿En qué puedo servirte?' WHERE `ID`=55949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대피 명령서 갖고 있습니까?', `MaleText_loc4`='你收到疏散令了吗？', `MaleText_loc5`='你拿到撤離命令了?', `MaleText_loc7`='¿Tienes esos papeles de evacuación?' WHERE `ID`=55950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 여기 있습니다. 어서 가시죠.', `MaleText_loc4`='是的，就在这儿呢。走吧。', `MaleText_loc5`='是的，就在這裡。我們走吧。', `MaleText_loc7`='Sí, aquí están. Vámonos.', `FemaleText_loc1`='네, 여기 있어요. 어서 가세요.', `FemaleText_loc4`='是的，就在这儿呢。走吧。', `FemaleText_loc5`='是的，就在這裡。我們走吧。', `FemaleText_loc7`='Sí, aquí están. Vámonos.' WHERE `ID`=55951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 생각해봤습니다... 여기에 있기에는 너무 위험하군요. 목숨을 걸 정도로 땅이 소중하지는 않으니까요. 어디 그 대피 명령서 좀 보여주십시오.', `MaleText_loc4`='我又想了下……待在这儿太危险。生命可比土地重要多了。让我看看那些疏散令。', `MaleText_loc5`='我重新思考過了...待在這裡太過危險。為了一片土地放棄生命永遠都不值得。讓我看看那些撤離命令。', `MaleText_loc7`='Lo he pensado mejor... es demasiado peligroso quedarse aquí. No merece la pena perder la vida por un pedazo de tierra. Déjame ver esas órdenes de evacuación.' WHERE `ID`=55952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치료가 필요한 분이 있습니까?', `FemaleText_loc4`='有人需要医疗救助吗？', `FemaleText_loc5`='有誰需要醫療救援的嗎?', `FemaleText_loc7`='¿Alguien necesita asistencia médica?' WHERE `ID`=55953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요 신병! 제게 뭐라고 말했나요? 미안해요! 폭발 때문에 아직도 귀가 먹먹해요!', `FemaleText_loc4`='嗨，新丁！你刚才跟我说话了吗？不好意思，我的耳朵还没从爆炸里恢复过来，到现在还在嗡嗡作响呢！', `FemaleText_loc5`='嘿!新人!你說了什麼嗎!?抱歉!我的耳朵還因為爆炸而嗡嗡響的!', `FemaleText_loc7`='¡HOLA, RECLUTA! ¿ME HAS DICHO ALGO? PERDONA, TODAVÍA ME ZUMBAN LOS OÍDOS POR LA EXPLOSIÓN.' WHERE `ID`=55954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 소리로 야영지로 돌아가는 길을 설명합니다.', `MaleText_loc4`='大声解释如何返回营地。', `MaleText_loc5`='大聲解釋如何回到營地。', `MaleText_loc7`='Explícale a voz en grito cómo volver al campamento.', `FemaleText_loc1`='큰 소리로 야영지로 돌아가는 길을 설명합니다.', `FemaleText_loc4`='大声解释如何返回营地。', `FemaleText_loc5`='大聲解釋如何回到營地。', `FemaleText_loc7`='Explícale a voz en grito cómo volver al campamento.' WHERE `ID`=55955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요원을 깨웁니다.', `MaleText_loc4`='叫醒他。', `MaleText_loc5`='叫醒他。', `MaleText_loc7`='Despiértalo.', `FemaleText_loc1`='요원을 깨웁니다.', `FemaleText_loc4`='叫醒他。', `FemaleText_loc5`='叫醒他。', `FemaleText_loc7`='Despiértalo.' WHERE `ID`=55956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<노움의 얼굴은 시커멓게 불에 그을렸지만, 아직 살아 있기는 합니다.>', `MaleText_loc4`='<这个侏儒的脸上烟熏火燎的，但还活着。>', `MaleText_loc5`='<地精的臉上沾滿了煙灰和燒傷的痕跡，但他還活著。>', `MaleText_loc7`='<El rostro del gnomo muestra quemaduras y restos de humo, pero está vivo.>' WHERE `ID`=55957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 임무는 뭔가? 필요한 도구라면 내가 다 갖고 있네.', `MaleText_loc4`='你的任务是什么？我这里有你需要的工具。', `MaleText_loc5`='你的任務是啥?我有你需要的工具。', `MaleText_loc7`='¿Cuál es tu misión? Tengo las herramientas que necesitas.' WHERE `ID`=55958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 드워프는 의식이 없습니다. 하지만 다친 것 같지는 않습니다.>', `MaleText_loc4`='<这个矮人失去了意识，但并没有受伤。>', `MaleText_loc5`='<矮人失去意識了，但基本沒有受傷。>', `MaleText_loc7`='<El enano está inconsciente, aunque ha resultado ileso.>' WHERE `ID`=55959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야영지를 점령하려면, 내 시체를 넘어야 할 겁니다!', `MaleText_loc4`='除非我死了，否则他们休想占领这个营地！', `MaleText_loc5`='他們得踩過我才能佔領這座營地!', `MaleText_loc7`='¡Solo tomarán este campamento por encima de mi cadáver!' WHERE `ID`=55960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 크게 뜨고 항상 임무에 집중하게.', `MaleText_loc4`='在执行任务时，一定要睁大眼睛，多动脑子，新兵。', `MaleText_loc5`='張大你的眼睛，專注在任務上，新人。', `MaleText_loc7`='Mantén los ojos abiertos y piensa en la misión, recluta.' WHERE `ID`=55961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 꽤 무시무시한 폭발이었어요! 뭐 그래도 몸에서 없어진 부분은 없어진 것 같네요. 고마워요, 신병.', `MaleText_loc4`='哇哦，撞得可真够惨的！我身上的零件好像都还在。谢了，新丁。', `MaleText_loc5`='喔耶!這次墜毀真夠勁!我身上的部位似乎都還在。謝啦，菜鳥。', `MaleText_loc7`='¡Guau! ¡Menudo aterrizaje! Creo que tengo todas mis partes. Gracias, recluta.' WHERE `ID`=55962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우! 그래도 우리가 앰버와 님보다는 상태가 나은 것 같네. 그들의 비행기가 육지 안쪽으로 더 날아가다가 폭발하는 걸 봤거든. 고맙네, $c.', `MaleText_loc4`='噢！我看我们的情形要比安玻和尼姆强点。我看见他们的飞机起火了，就在更靠近内陆一点的地方。谢谢你了，$c。', `MaleText_loc5`='喔!我估計琥珀和妮姆的遭遇比我們更糟。看見他們的飛機冒著火掉到更內陸的地方。謝謝，$c。', `MaleText_loc7`='¡Ay! Creo que nos ha ido mejor que a Amber y a Nimm. Vi su avión estrellarse hacia el interior. Gracias, $c.' WHERE `ID`=55963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금 더 당신과 함께 있겠습니다, $n 님. 아직 제 도움이 필요한 선원들이 많습니다.', `FemaleText_loc4`='我会再照顾你一小会，$n。我看到还有许多受伤的机组成员需要我的帮助呢。', `FemaleText_loc5`='我會多陪你一點時間，$n。我看到很多受傷的船員，他們可能需要我的援助。', `FemaleText_loc7`='Me quedaré contiguo un rato más, $n. He visto a muchos tripulantes heridos que podrían necesitar mi ayuda.' WHERE `ID`=55964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 물과 대화하기에 딱 좋은 곳인 것 같군요!', `MaleText_loc4`='这里很适合使用水占术！', `MaleText_loc5`='這裡像是和水會談的好地點!', `MaleText_loc7`='¡Ese parece un buen lugar para consultar al agua!' WHERE `ID`=55965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가자, 자매여. 이제 끝낼 때이다. 고대 신의 어두운 흔적을 씻어내, 용의 영혼을 정화하자!', `FemaleText_loc4`='来吧，妹妹，该做个了结了。我们将净化上古之神对巨龙之魂造成的黑暗污染！', `FemaleText_loc5`='來吧姊妹，終結這一切。我們將淨化上古之神對巨龍之魂的黑暗影響力!', `FemaleText_loc7`='Ven hermana, es hora de terminar con esto. ¡Purgemos el Alma de dragón de la influencia oscura de los dioses antiguos!' WHERE `ID`=55966;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 강력해!', `FemaleText_loc4`='太强大了！', `FemaleText_loc5`='它太強大了!', `FemaleText_loc7`='¡Es demasiado poderoso!' WHERE `ID`=55967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 나의 창조물에 손을 대다니! 용의 영혼은 내것이다. 내 거... 내 거야!', `MaleText_loc4`='你怎么敢染指我的造物？！它是我的，我的，我的！', `MaleText_loc5`='你竟敢觸碰我的作品?那是我的。我的...我的。', `MaleText_loc7`='¡¿Cómo te atreves a tocar mi creación?! Es mía. Mía... mía y solo mía. ' WHERE `ID`=55968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넬타리온! 무슨 짓을 한 거요? 그대는 우리 모두를 고대 신의 광기에 노출시켰소!', `FemaleText_loc4`='奈萨里奥！你都做了些什么？你将上古之神的疯狂厄运带给了我们！', `FemaleText_loc5`='奈薩里奧!你做了什麼好事啊?你會害我們因上古之神的瘋狂而滅亡!', `FemaleText_loc7`='¡Neltharion! ¿Qué has hecho? ¡Nos has condenado a todos a la locura de los dioses antiguos!' WHERE `ID`=55969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 영혼은 내것이다!', `MaleText_loc4`='它·是·我·的！', `MaleText_loc5`='那是我的。', `MaleText_loc7`='¡¡ES MÍA!!' WHERE `ID`=55970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니, 그는 이제 없어. 저건 넬타리온이 아니야.', `FemaleText_loc4`='他背叛我们了，姐姐。他不再是奈萨里奥了。', `FemaleText_loc5`='我們失去他了，姊妹。他不再是奈薩里奧。', `FemaleText_loc7`='Lo hemos perdido, hermana. Ya no es Neltharion.' WHERE `ID`=55971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용의 영혼이 그를 갈가리 찢고 있어!', `FemaleText_loc4`='巨龙之魂的力量正在撕裂他！', `FemaleText_loc5`='巨龍之魂的力量正在撕裂他!', `FemaleText_loc7`='¡El poder del Alma lo está destruyendo!' WHERE `ID`=55972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 물러서라...', `MaleText_loc4`='不……滚开……', `MaleText_loc5`='不....走開...', `MaleText_loc7`='Noooooo… fuera...' WHERE `ID`=55973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시... 손에 넣을 것이야!', `MaleText_loc4`='我是不会失败的。', `MaleText_loc5`='不要想阻擋我!', `MaleText_loc7`='¡NO SE ME NEGARÁ!' WHERE `ID`=55974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라!', `MaleText_loc4`='滚开！', `MaleText_loc5`='走開!', `MaleText_loc7`='¡FUERA!' WHERE `ID`=55975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고요?! 따라오라고요?! 알았어요!', `FemaleText_loc4`='什么？跟着你？好吧！', `FemaleText_loc5`='什麼?跟著你?好啊!', `FemaleText_loc7`='¿QUÉ? ¿QUE TE SIGA? ¡VAMOS!' WHERE `ID`=55976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 때가 왔구나. 내 최후의 순간 말이다. 이 시간의 고리는 끊겼다. 이제 미래의 나는 아무 위협도 가하지 않을 것이다.', `MaleText_loc4`='最终的时刻到来了。我将在这一刻消亡。轮回结束了。未来的我再也不能作恶了。', `MaleText_loc5`='終於走到這一步了。我殞命的時刻。迴圈已經終結。未來的我不會再惹麻煩了。', `MaleText_loc7`='Al fin ha ocurrido. Ha llegado mi hora. El ciclo se ha interrumpido. Mi yo del futuro no volverá a causar más daño.' WHERE `ID`=55977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 시간이 지나면... 지금의 내가 광기에 휩싸이겠지. 그리고 너희 영웅들이... 날 제압하리라. 순환은 계속되고, 또 계속될 터.', `MaleText_loc4`='在未来，我仍将……堕入疯狂。而你们，英雄们，注定将消灭我。循环仍将继续，如此往复。', `MaleText_loc5`='不過，隨時間過去，我還是會...發瘋。你們將...會殺死我。輪迴會不斷地重複下去。', `MaleText_loc7`='Sin embargo, con el tiempo, sucumbiré a la... locura. Y ustedes, héroes, me vencerán. El ciclo se repetirá. Así debe ser.' WHERE `ID`=55978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 것은 아제로스가 멸망하지 않았다는 것이다. 우리가 살아남아 다시 투쟁할 수 있다는 것이다.', `MaleText_loc4`='重要的是艾泽拉斯并没有毁灭；我们仍将为生存而战。', `MaleText_loc5`='重要的是艾澤拉斯沒有淪陷，我們能活下來繼續奮戰。', `MaleText_loc7`='Lo importante es que Azeroth no cayó; sobrevivimos para luchar un día más.' WHERE `ID`=55979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 것은... 지금 이 순간이다.', `MaleText_loc4`='最重要的是……此时此刻。', `MaleText_loc5`='這一刻...是最關鍵的時刻。', `MaleText_loc7`='Lo único que importa... es este momento.' WHERE `ID`=55980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"시간의 끝", 난 한때 이곳을 그렇게 불렀다. 그때는 알지 못했다. 보지 못했지. 그런데 뭐? 여기서 날 막겠다고? 내가 이리 힘들게 일궈놓은 운명을?', `MaleText_loc4`='“时光之末”，我曾经这么称呼这个地方，我看不到从此以后的时间。什么？你想要……阻止我？改变我花费了无尽时间编织的命运？', `MaleText_loc5`='我曾稱呼這裡為「終焉之刻」。當時我還無法看見，也還不知道你們想做什麼?在這裡阻止我?改變我努力編織的命運?', `MaleText_loc7`='Una vez llamé a este lugar, el "Fin de los Días". Entonces, no lo conocía. ¿Qué esperan? ¿Detenerme aquí? ¿Cambiar el destino que tanto me costó tejer?  ' WHERE `ID`=55981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장님처럼, 꿈틀대는 벌레처럼, 끝없는 광기와 절망을 향해 기어가는 너흰 알지 못한다. 난 진정한 시간의 끝을 목격했다. 이거? 이건 축복이다. 네놈들은 이해할 수 없겠지만.', `MaleText_loc4`='你在地上无知地爬行，像一只瞎眼的爬虫，向着无尽的疯狂与绝望蠕动。我见证了真正的时光之末。这儿？这儿只是你无法理解的祝福。', `MaleText_loc5`='你們就像無知扭動的蟲子，爬向無盡的瘋狂和絕望。我見識過真正的「終焉之刻」。那是什麼呢?是你們根本無法理解的祝福。', `MaleText_loc7`='Se arrastran como gusanos ciegos y retorcidos hacia una locura y desesperación infinitas. Yo he visto el verdadero Fin de los Días y esto es una bendición que escapa a su entendimiento.' WHERE `ID`=55982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어둠 속으로 사라집니다!', `MaleText_loc4`='%s消失在阴影中了！', `MaleText_loc5`='%s消失在陰影中!', `MaleText_loc7`='¡%s desaparece entre las sombras!' WHERE `ID`=55983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='페로스안의 눈이 당신을 찾고 있습니다.', `MaleText_loc4`='佩罗萨恩之眼正在搜寻你。', `MaleText_loc5`='佩洛薩恩之眼正在找你。', `MaleText_loc7`='Los ojos de Peroth''arn te buscan.' WHERE `ID`=55984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목적지를 선택합니다.', `MaleText_loc4`='选择你的目的地。', `MaleText_loc5`='選擇你的目的地。', `MaleText_loc7`='Elige el destino.', `FemaleText_loc1`='목적지를 선택합니다.', `FemaleText_loc4`='选择你的目的地。', `FemaleText_loc5`='選擇你的目的地。', `FemaleText_loc7`='Elige el destino.' WHERE `ID`=55985;
