UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청동 용제단', `MaleText_loc4`='青铜巨龙圣地', `MaleText_loc5`='青銅龍殿', `MaleText_loc7`='Santuario de Dragones Bronce', `FemaleText_loc1`='청동 용제단', `FemaleText_loc4`='青铜巨龙圣地', `FemaleText_loc5`='青銅龍殿', `FemaleText_loc7`='Santuario de Dragones Bronce' WHERE `ID`=55991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신도 들으셨나요? 은둔 고수께서 이곳 북쪽에 계시다고요!?', `FemaleText_loc4`='你听到了吗！？隐秘大师，是在北边吗！？', `FemaleText_loc5`='你聽到了嗎!?隱居的宗師就在北邊!?', `FemaleText_loc7`='¡¿Has oído eso?! ¡¿El maestro oculto, al norte de aquí?!' WHERE `ID`=55992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경비대 사령관님, 저는 지금 떠날게요. 드디어 제 수련을 계속 진행할 수 있겠어요.', `FemaleText_loc4`='执勤官，我得走了。我终于可以继续训练了！', `FemaleText_loc5`='指揮官，我要離開了。我終於可以繼續我的訓練了!', `FemaleText_loc7`='Comandante de vigilancia, me marcho ya. ¡Por fin voy a continuar con mi entrenamiento!' WHERE `ID`=55993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 그곳에서 만날지도 모르겠네요!', `FemaleText_loc4`='也许我会在那儿见到你，$n！', `FemaleText_loc5`='或許我們會在那裡見面，$n!', `FemaleText_loc7`='¡Quizá nos veamos allí arriba, $n!' WHERE `ID`=55994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 잘하셨습니다. 전 이제 부상자들을 돌보기 위해 야영지로 돌아가겠습니다. 이곳의 일을 마무리하시거든 사령관님과 다시 이야기해 보십시오.', `FemaleText_loc4`='$n，你干的不错，我要回营地去照顾其他伤员了。你要是没事了就到指挥官那里去报个道。', `FemaleText_loc5`='$n，你做得很好。我要回營地照料傷患。把這裡的事情處理完就去找指揮官報到吧。', `FemaleText_loc7`='Lo has hecho bien, $n. Vuelvo al campamento a encargarme de los heridos. Habla con el comandante cuando hayas terminado.' WHERE `ID`=55995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $r님! 제가 말씀드린 걸 꼭 찾아 오세요. 아시겠죠? 정말 먹을 만한지 확인해 봐야 하니까요.', `FemaleText_loc4`='哦，还有，$r！去把货物带回来，好吗？我得确保它们没事。', `FemaleText_loc5`='喔，對了$r!帶著那些物資一起回來，好嗎?我得確認他們能派上用場。', `FemaleText_loc7`='Ah, por cierto, $r. Vuelve con la mercancía. Tengo que asegurarme de que está en buen estado.' WHERE `ID`=55998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈둥이와 내가 기다리고 있겠네! 서두르게!', `MaleText_loc4`='我和雪雾会等着的！请快去快回！', `MaleText_loc5`='雪噴和我會等著的!拜託快點!', `MaleText_loc7`='¡Te estaré esperando con Ventonieve! ¡Date prisa!' WHERE `ID`=55999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선은 지금 이 문제를 해결해야 하네. 아군을 도와 이곳을 방어하게!', `MaleText_loc4`='我们遇到麻烦了。快帮忙保护我们的战友！', `MaleText_loc5`='我們眼前有個狀況要處理。幫忙保護我們的盟友!', `MaleText_loc7`='Tenemos un problema. ¡Ayúdanos a defender a nuestros aliados!' WHERE `ID`=56000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 영혼 안에 있는 어두운 힘이 정화 의식에 격렬하게 반응합니다!', `MaleText_loc4`='巨龙之魂内的黑暗力量对净化产生了强烈的反应！', `MaleText_loc5`='巨龍之魂裡面的一股黑暗力量劇烈地抗拒著淨化!', `MaleText_loc7`='¡Una fuerza oscura del Alma de dragón reacciona de forma violenta a la limpieza!', `FemaleText_loc1`='용의 영혼 안에 있는 어두운 힘이 정화 의식에 격렬하게 반응합니다!', `FemaleText_loc4`='巨龙之魂内的黑暗力量对净化产生了强烈的反应！', `FemaleText_loc5`='巨龍之魂裡面的一股黑暗力量劇烈地抗拒著淨化!', `FemaleText_loc7`='¡Una fuerza oscura del Alma de dragón reacciona de forma violenta a la limpieza!' WHERE `ID`=56001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험은 간단하다네. 대나무를 치기만 하면 되지. 부서질 때까지 말이야.', `MaleText_loc4`='这个测试很简单。你要做的就是击打竹子，直到它破裂。', `MaleText_loc5`='啊...這測驗十分簡單。你只需要擊打竹子，直到它們斷裂為止。', `MaleText_loc7`='Esta prueba es sencilla. Lo único que tienes que hacer es golpear el bambú hasta que se rompa.' WHERE `ID`=56003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"너무 굵은걸요!"라고 말하고 싶겠지.', `MaleText_loc4`='你或许会说：“可竹子太厚了！”。', `MaleText_loc5`='你或許會說:「但它實在太硬了!」', `MaleText_loc7`='"¡Pero es demasiado grueso!", dirás. ' WHERE `ID`=56004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 시험의 일부라네. 성공하고 싶은가? 그렇다면 한쪽 주먹에 기를 모두 모은 다음...', `MaleText_loc4`='这只是测试的一部分。是的，要想成功，你必须将全身力量集中在一只拳头上……', `MaleText_loc5`='這就是測驗的一部分。沒錯，想要成功，你必須把所有精力凝聚在整個拳頭上...', `MaleText_loc7`='Forma parte de la prueba. Sí, para superarla, debes centrar toda tu energía en un puño... ' WHERE `ID`=56005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 강타!', `MaleText_loc4`='……然后，出拳！', `MaleText_loc5`='...然後，出拳!', `MaleText_loc7`='¡... y GOLPEAR!' WHERE `ID`=56006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원에 불이 가득 차면 대나무 뭉치를 강타하십시오!', `MaleText_loc4`='在力量积聚到顶点时，一拳击打到竹堆上！', `MaleText_loc5`='計量表全滿時擊打竹子!', `MaleText_loc7`='¡Golpea el montón de bambú cuando el medidor esté lleno!' WHERE `ID`=56007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험은 간단하다네. 나무를 치기만 하면 되지. 부서질 때까지 말이야.', `MaleText_loc4`='这个测试很简单。你要做的就是击打木板，直到它破裂。', `MaleText_loc5`='這測驗十分簡單。你只需要擊打木頭，直到它們斷裂為止。', `MaleText_loc7`='Esta prueba es sencilla. Lo único que tienes que hacer es golpear la madera hasta que se rompa.' WHERE `ID`=56008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"너무 어려워요!"라고 말하고 싶겠지.', `MaleText_loc4`='你或许会说：“可木板太硬了！”。', `MaleText_loc5`='你或許會說:「但它實在太硬了!」', `MaleText_loc7`='"¡Pero es muy difícil!", dirás.' WHERE `ID`=56009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 어렵지 않네. 자넨 준비가 됐어.', `MaleText_loc4`='但它其实并没那么硬。你已经做好了准备，$n。', `MaleText_loc5`='但是它並不難。而你也有足夠能力。', `MaleText_loc7`='No es difícil. Te has entrenado para esto.' WHERE `ID`=56010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험은 간단하다네. 돌을 치기만 하면 되지. 부서질 때까지 말이야.', `MaleText_loc4`='这个测试很简单。你要做的就是击打石块，直到将其击碎。', `MaleText_loc5`='這測驗十分簡單。你只需要擊打石頭，直到它們斷裂為止。', `MaleText_loc7`='Esta prueba es sencilla. Lo único que tienes que hacer es golpear esa piedra hasta que se rompa.' WHERE `ID`=56011;
