UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려워하지 마십시오, 작은 존재들이여. 어둠이 찾아오건, 빛이 찾아오건, 물은 언제나 흐를 것입니다.', `MaleText_loc4`='别害怕，小家伙们。无论光明还是黑暗，流水不腐。', `MaleText_loc5`='別害怕，小朋友。無論在黑暗或光明中，水都照常地流動。', `MaleText_loc7`='No temáis, pequeños. Ya sea con oscuridad o luz, las aguas siempre fluirán.' WHERE `ID`=56041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물은 생명입니다. 물이 고통을 느끼면, 우리도 그러할 것입니다.', `MaleText_loc4`='水即是生命。一旦水遭遇痛苦，我们也将在劫难逃。', `MaleText_loc5`='水就是生命。當水感受到痛苦，我們也會。', `MaleText_loc7`='El agua es vida. Cuando el agua padece tormento, nosotros también.' WHERE `ID`=56042;
