UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저는 당신 친구가 본 게 무엇인지 알고 있어요. 이제 애쉬요는 좀 쉬어야 해요. 저와 잠깐 이야기 좀 나누시죠.', `FemaleText_loc4`='我知道你朋友看到了什么，$n——他现在需要休息。来和我谈谈。', `FemaleText_loc5`='$n，我知道你的朋友看到了什麼，他現在需要休息一下。過來跟我聊聊。', `FemaleText_loc7`='Sé lo que ha visto tu amigo, $n. De momento tendrá que descansar. Ven a hablar conmigo.' WHERE `ID`=56044;
