UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 가능한가요? 진위가 정말 물의 힘을 그렇게 가뿐하게 끌어낼 수 있단 말이죠?', `FemaleText_loc4`='可能吗？锦鱼人难道真能轻易接触到水的力量？', `FemaleText_loc5`='這可能嗎?錦魚人真能那麼輕易地利用水的力量嗎?', `FemaleText_loc7`='¿Es esto posible? ¿Realmente los jinyu pueden utilizar el poder del agua con tanta facilidad?' WHERE `ID`=56048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 물에서 그렇게 손쉽게 환영을 얻어내는 이는 여태껏 보지 못했어요.$B$B진위가 우리 마을에 와서 물속에 얼굴을 처박았던 기억도 없긴 하지만요...', `FemaleText_loc4`='我从未见过有人如此轻易就从水中看到幻象。$B$B不过，我都不记得上次锦鱼人是何时来访，然后把脸扎进水里的了……', `FemaleText_loc5`='我從沒見過任何人能如此輕易地從水中看到影像。$B$B話說回來，我記不得上次錦魚人來這裡拜訪並把臉埋到水裡是什麼時候的事了...', `FemaleText_loc7`='Nunca he visto a nadie recibir una visión de estas aguas con tanta facilidad.$B$BAunque no recuerdo la última vez que un jinyu vino a visitarnos y metió la cara en el agua...' WHERE `ID`=56049;
