UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 진홍빛 운룡이 당신을 시험하는 듯 조심스럽게 깨뭅니다.', `MaleText_loc4`='顽皮的赤红小翔龙试探着咬了咬你。', `MaleText_loc5`='好動的紅蛟試驗性地啃了啃你。', `MaleText_loc7`='Dragón carmesí juguetón prueba a darte un mordisco.' WHERE `ID`=56060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 진홍빛 운룡이 지루해 합니다.', `MaleText_loc4`='顽皮的赤红小翔龙觉得很无聊。', `MaleText_loc5`='好動的紅蛟感到很無聊。', `MaleText_loc7`='Dragón carmesí juguetón está aburrido.' WHERE `ID`=56061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 호기심에 찬 눈길로 주위를 둘러봅니다.', `MaleText_loc4`='顽皮的翡翠小翔龙好奇地环顾四周。', `MaleText_loc5`='好動的綠蛟好奇地東張西望。', `MaleText_loc7`='Dragón esmeralda juguetón mira a su alrededor con curiosidad.' WHERE `ID`=56062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 당신의 냄새를 맡습니다.', `MaleText_loc4`='顽皮的翡翠小翔龙嗅了嗅你。', `MaleText_loc5`='好動的綠蛟聞了聞你。', `MaleText_loc7`='Dragón esmeralda juguetón te olisquea.' WHERE `ID`=56063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 당신의 머리카락을 먹으려고 하다가 다시 뱉어 냅니다. 우웩!', `MaleText_loc4`='顽皮的翡翠小翔龙想要吃你的头发，可马上又吐了出来。呃！', `MaleText_loc5`='好動的綠蛟想要吃你的頭髮，然後又吐出來。噁!', `MaleText_loc7`='Dragón esmeralda juguetón intenta comerse tu pelo y luego lo escupe. ¡Puaj!' WHERE `ID`=56064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 공중을 빙글 돕니다.', `MaleText_loc4`='顽皮的翡翠小翔龙在空中打滚。', `MaleText_loc5`='好動的綠蛟在空中翻筋斗。', `MaleText_loc7`='Dragón esmeralda juguetón da vueltas en el aire.' WHERE `ID`=56067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 졸려 합니다.', `MaleText_loc4`='顽皮的翡翠小翔龙开始昏昏欲睡。', `MaleText_loc5`='好動的綠蛟想睡了。', `MaleText_loc7`='Dragón esmeralda juguetón tiene sueño.' WHERE `ID`=56068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 에메랄드 운룡이 당신과 놀이를 하고 싶어 합니다!', `MaleText_loc4`='顽皮的翡翠小翔龙想要玩游戏！', `MaleText_loc5`='好動的綠蛟想要玩遊戲!', `MaleText_loc7`='¡Dragón esmeralda juguetón quiere jugar a algo!' WHERE `ID`=56069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡이 자신의 그림자와 함께 놉니다.', `MaleText_loc4`='顽皮的青色小翔龙在和自己的影子嬉戏。', `MaleText_loc5`='好動的蒼蛟在和自己的影子玩。', `MaleText_loc7`='Dragón azur juguetón juega con su propia sombra.' WHERE `ID`=56070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡이 배가 고픕니다!', `MaleText_loc4`='顽皮的青色小翔龙饿了！', `MaleText_loc5`='好動的蒼蛟肚子餓了!', `MaleText_loc7`='¡Dragón azur juguetón tiene hambre!' WHERE `ID`=56071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡이 과자를 먹고 싶어 합니다.', `MaleText_loc4`='顽皮的青色小翔龙想要吃点心。', `MaleText_loc5`='好動的蒼蛟想要吃點心!', `MaleText_loc7`='Dragón azur juguetón quiere picar algo.' WHERE `ID`=56072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡은 당신에게 사탕이 없는지 궁금해 합니다.', `MaleText_loc4`='顽皮的青色小翔龙问你有没有东西吃。', `MaleText_loc5`='好動的蒼蛟在想你是不是點心。', `MaleText_loc7`='Dragón azur juguetón se pregunta si tienes algo de comer.' WHERE `ID`=56073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡이 자기 몸을 핥습니다.', `MaleText_loc4`='顽皮的青色小翔龙在舔舐自己。', `MaleText_loc5`='好動的蒼蛟舔了舔自己。', `MaleText_loc7`='Dragón azur juguetón se lame.' WHERE `ID`=56074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활발한 하늘빛 운룡은 사랑이 필요합니다!', `MaleText_loc4`='顽皮的青色小翔龙在撒娇！', `MaleText_loc5`='好動的蒼蛟需要有人疼愛!', `MaleText_loc7`='¡Dragón azur juguetón quiere mimos!' WHERE `ID`=56075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에 참여할 애완동물을 선택하십시오!', `MaleText_loc4`='选择一只宠物，为你战斗！', `MaleText_loc5`='選一隻寵物在戰場上為你戰鬥!', `MaleText_loc7`='¡Elige una mascota para que luche por ti en la batalla!', `FemaleText_loc1`='전투에 참여할 애완동물을 선택하십시오!', `FemaleText_loc4`='选择一只宠物，为你战斗！', `FemaleText_loc5`='選一隻寵物在戰場上為你戰鬥!', `FemaleText_loc7`='¡Elige una mascota para que luche por ti en la batalla!' WHERE `ID`=56076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 또다시 큰일을 맡기게 됐군. 우리가 영혼에 아제로스 위상의 힘을 불어넣는 동안, 자네들은 데스윙의 병력으로부터 우릴 보호해야 하네.', `MaleText_loc4`='英雄们，这个重担又落到你们的肩上了。我们会将守护巨龙的力量灌注到巨龙之魂中，在此期间，你们必须保护我们。', `MaleText_loc5`='英雄們，我們必須再次把這個重擔放在你們的雙肩上。在我們將艾澤拉斯守護巨龍的力量灌注到巨龍之魂時，你們必須保護我們，別讓我們受到死亡之翼爪牙的攻擊。', `MaleText_loc7`='Héroes, esta responsabilidad recae en ustedes una vez más. Deben protegernos de los ejércitos de Alamuerte mientras imbuimos el Alma con los poderes de los Aspectos.' WHERE `ID`=56077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 시작하십시오. 저희가 지켜드리겠습니다.', `MaleText_loc4`='你们可以开始仪式了，我们会保护你们的。', `MaleText_loc5`='你可以開始儀式了，我們會保護你。', `MaleText_loc7`='Que comience el ritual, nosotros te defenderemos.', `FemaleText_loc1`='의식을 시작하십시오. 저희가 지켜드리겠습니다.', `FemaleText_loc4`='你们可以开始仪式了，我们会保护你们的。', `FemaleText_loc5`='你可以開始儀式了，我們會保護你。', `FemaleText_loc7`='Que comience el ritual, nosotros te defenderemos.' WHERE `ID`=56078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 엔진이 고장났다! 완전 무방비 상태가 되었군!', `MaleText_loc4`='我们的引擎受损了！我们成了活靶子！', `MaleText_loc5`='我們的引擎受損了!我們這樣很容易遭受攻擊!', `MaleText_loc7`='¡Nuestros motores están dañados! ¡Somos presa fácil aquí!' WHERE `ID`=56079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑군, 알렉스트라자. 난 떠나 있는 동안 좀 바쁘게 지냈다.', `MaleText_loc4`='重逢真令我高兴，阿莱克斯塔萨。分开之后，我可是一直很忙。', `MaleText_loc5`='很高興又見到你，雅立史卓莎。我離開這段時間忙得很。', `MaleText_loc7`='Me alegra volver a verte, Alexstrasza. He estado ocupado en mi ausencia.' WHERE `ID`=56080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들은... 이제 내 자식이 아니다. 전부 쓰러뜨려라.', `FemaleText_loc4`='它们……已经不再是我的子嗣了。消灭它们。', `FemaleText_loc5`='牠們不再是我的幼龍。摧毀牠們。', `FemaleText_loc7`='Ya no... son mi nidada. Elimínenlos.' WHERE `ID`=56081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도서관에는 수천 년의 세월에 대한 역사와 이야기가 담겨 있네. 판다리아 전역에서 가장 위대한 지혜가 여기 보관되어 있지.$B$B그렇기 때문에 우리가 이 엄청난 보물을 지켜야 하는 것이네.', `MaleText_loc4`='这个藏书室保存着几千年的历史文化，以及全潘达利亚的最了不起的知识。$B$B这也是我们一定要保护好这里的原因。', `MaleText_loc5`='圖書館收藏了數千年的歷史與傳說。全潘達利亞的偉大知識都在這裡。$B$B正因此，我們必須守護這偉大寶藏安全無虞。', `MaleText_loc7`='Esta biblioteca contiene miles de años de historia y tradiciones. Aquí se conserva el mayor conocimiento de toda Pandaria.$b$bPor eso debemos proteger este gran tesoro.' WHERE `ID`=56082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두루마리를! 두루마리를 지켜야 하네!', `MaleText_loc4`='卷轴！我必须抢救出那些卷轴！', `MaleText_loc5`='卷軸!我必須守護卷軸!', `MaleText_loc7`='¡Los pergaminos! ¡Debo salvar los pergaminos!' WHERE `ID`=56083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없네. 용의 영혼이 가진 힘이 너무 강력해, 안전하게 다룰 수 없네. 이 안의 혼돈의 힘이 모두에게 파멸을 가져올지도 모른다네.', `MaleText_loc4`='这没有用，巨龙之魂的力量太强大了。我不能安全地使用它，这个神器里的混乱力量也许会毁掉我们所有的人。', `MaleText_loc5`='沒有用，巨龍之魂的力量太強了。我無法安全地使用它，它所含有的混沌力量會使我們滅亡。', `MaleText_loc7`='No sirve de nada, el Alma es demasiado poderosa. No puedo empuñarla de forma segura; las fuerzas arrasadoras que encierra pueden ser fatales.' WHERE `ID`=56084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사 중', `MaleText_loc4`='调查中', `MaleText_loc5`='調查', `MaleText_loc7`='Investigando', `FemaleText_loc1`='조사 중', `FemaleText_loc4`='调查中', `FemaleText_loc5`='調查', `FemaleText_loc7`='Investigando' WHERE `ID`=56085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤헤헤헤!', `MaleText_loc4`='嘿嘿嘿嘿嘿！', `MaleText_loc5`='嘻嘻嘻嘻!', `MaleText_loc7`='¡Jee jee jee jee jee!' WHERE `ID`=56086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 더 필요해!', `MaleText_loc4`='更多能量！', `MaleText_loc5`='更多力量!', `MaleText_loc7`='¡Más fuerza!' WHERE `ID`=56087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 맛있구나!', `MaleText_loc4`='真美味！', `MaleText_loc5`='如此美味!', `MaleText_loc7`='¡Qué delicia!' WHERE `ID`=56088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 약병 조심하십시오. 좀 새거든요.', `MaleText_loc4`='当心那个小瓶子，它有点儿漏。', `MaleText_loc5`='那個瓶子要小心拿。它會漏。', `MaleText_loc7`='Cuidado con ese vial. Tiene algunas fugas.' WHERE `ID`=56089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옥룡사에 잘 왔네. 내가 무엇을 도와주면 되겠나?', `FemaleText_loc4`='欢迎来到青龙寺。有什么需要帮助的吗？', `FemaleText_loc5`='歡迎來到玉蛟寺。我能怎麼幫助你嗎?', `FemaleText_loc7`='Te doy la bienvenida al Templo del Dragón de Jade. ¿En qué puedo ayudarte?' WHERE `ID`=56090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사에 들어가고 싶습니다.', `MaleText_loc4`='我想进入青龙寺。', `MaleText_loc5`='我想要進入玉蛟寺。', `MaleText_loc7`='Me gustaría entrar en el Templo del Dragón de Jade.', `FemaleText_loc1`='옥룡사에 들어가고 싶어요.', `FemaleText_loc4`='我想进入青龙寺。', `FemaleText_loc5`='我想要進入玉蛟寺。', `FemaleText_loc7`='Me gustaría entrar en el Templo del Dragón de Jade.' WHERE `ID`=56091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 님께 전할 말씀이 있습니다.', `MaleText_loc4`='我有消息要带给青龙。', `MaleText_loc5`='我有個訊息要傳給玉蛟。', `MaleText_loc7`='Tengo un mensaje para el dragón de jade.', `FemaleText_loc1`='옥룡 님께 전할 말씀이 있어요.', `FemaleText_loc4`='我有消息要带给青龙。', `FemaleText_loc5`='我有個訊息要傳給玉蛟。', `FemaleText_loc7`='Tengo un mensaje para el dragón de jade.' WHERE `ID`=56092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사에서 필요한 건 모두 찾았나?', `MaleText_loc4`='你在青龙寺里找到需要的东西了吗？', `MaleText_loc5`='你在寺裡找到需要的一切了嗎?', `MaleText_loc7`='¿Tienes todo lo que necesitas en el templo?' WHERE `ID`=56093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사 정원으로 돌아가고 싶습니다.', `MaleText_loc4`='我想要返回青龙寺庭院。', `MaleText_loc5`='我想要回到玉廟庭去。', `MaleText_loc7`='Me gustaría volver a las tierras del templo.', `FemaleText_loc1`='옥룡사 정원으로 돌아가고 싶어요.', `FemaleText_loc4`='我想要返回青龙寺庭院。', `FemaleText_loc5`='我想要回到玉廟庭去。', `FemaleText_loc7`='Me gustaría volver a las tierras del templo.' WHERE `ID`=56094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 옥룡사에서 정말 큰 도움을 주셨어요!$B$B원로 현자께서도 당신이 여기 와주셔서 정말 기뻤다고 말씀하시더라고요.', `FemaleText_loc4`='你真是帮了我们寺院大忙了！$B$B我听大贤者说他很高兴你的到来。', `FemaleText_loc5`='你在寺廟這裡真是幫了大忙!$B$B我聽大司祭說，他很高興你及時來到這裡。', `FemaleText_loc7`='¡Nos has servido de gran ayuda en el templo!$b$bHe oído que el ancestro sabio dice que se alegra de que vinieras.' WHERE `ID`=56095;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옥룡사에 잘 왔네, 이방인. 우리는 지혜를 구하는 이 모두에게 문을 활짝 열고 있네.', `FemaleText_loc4`='欢迎来到青龙寺，陌生人。我们的大门永远向渴求知识的人敞开。', `FemaleText_loc5`='歡迎來到玉蛟寺，陌生人。我們的門永遠為追尋知識者敞開。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Templo del Dragón de Jade, $gforastero:forastera;. Nuestras puertas están abiertas a todo aquel que busca conocimiento.' WHERE `ID`=56096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정원 입구로 순간이동', `MaleText_loc4`='传送到花园入口。', `MaleText_loc5`='傳送到花園入口。', `MaleText_loc7`='Teletransporte a la entrada del jardín.', `FemaleText_loc1`='정원 입구로 순간이동', `FemaleText_loc4`='传送到花园入口。', `FemaleText_loc5`='傳送到花園入口。', `FemaleText_loc7`='Teletransporte a la entrada del jardín.' WHERE `ID`=56097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아저씨 곡식은 왜 맛이 하나같이 맹탕이죠?', `FemaleText_loc4`='你的谷物怎么这么寡淡无味？', `FemaleText_loc5`='為什麼你的穀物都沒啥味道?', `FemaleText_loc7`='¿Por qué es tan insípido todo tu grano?' WHERE `ID`=56098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자매여, 저들이 우릴 실망시켰어...', `FemaleText_loc4`='他们辜负了我们，姐妹。', `FemaleText_loc5`='妹妹，他們失敗了...', `FemaleText_loc7`='Nos han fallado, hermana.' WHERE `ID`=56099;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='깨어난 지 얼마 되지 않았거늘, 다시 잠들게 되었구나...', `FemaleText_loc4`='我从迷梦中苏醒，只是为了再次沉睡。', `FemaleText_loc5`='醒來竟是又再度沈眠。', `FemaleText_loc7`='He despertado solo para volver a dormir.' WHERE `ID`=56100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하, 우리가 모은 곡물은 양조장에서 대량으로 사용되는 것이란다. 하지만 네 입맛에 맞는 곡물이 뭔진 알 것 같구나.', `MaleText_loc4`='我们的谷物是供应给酿酒厂的，量都很大。也许有一种谷物符合你的需要。', `MaleText_loc5`='我們所採收的穀物需要很大的量才足以提供給酒坊使用。我大概知道有種穀物符合你的需求。', `MaleText_loc7`='Debemos reunir grandes cantidades de grano para su elaboración. Sin embargo, creo que tengo el grano adecuado para ti.' WHERE `ID`=56101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 같은 존재에게는, 퍽 짧은 시간이었다...', `MaleText_loc4`='对我们来说，这点时光不过是弹指一挥间……', `MaleText_loc5`='我們結束得...太快了...', `MaleText_loc7`='Fue muy poco tiempo, para nosotros...' WHERE `ID`=56102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 정말 그러했습니다.', `MaleText_loc4`='……的确如此。', `MaleText_loc5`='...的確。', `MaleText_loc7`='... claro que lo fue.' WHERE `ID`=56103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 방법이 있을지도...', `MaleText_loc4`='或许还有办法……', `MaleText_loc5`='或許還有個辦法...', `MaleText_loc7`='Tal vez exista una forma...' WHERE `ID`=56104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리, 가자꾸나. 이 삼촌이 너에게 보여줄 것이 있다.', `MaleText_loc4`='丽丽……我们走。你叔叔要证明一些事情。', `MaleText_loc5`='莉莉...我們走吧。妳叔叔得證明一些事情。', `MaleText_loc7`='Li Li... vámonos. Tu tío tiene algo que demostrar.' WHERE `ID`=56105;
