UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 우선, 달짝지근한 맥아가 좀 필요할 거야.', `MaleText_loc4`='首先我们需要的是，一些甜麦芽。', `MaleText_loc5`='首先呢，我們需要弄一些甜麥芽。', `MaleText_loc7`='Lo primero es lo primero. Vamos a necesitar malta dulce.' WHERE `ID`=56114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... $c|1이;가; 어쩐 일로 여기까지 다 올라오고 그러나...', `MaleText_loc4`='嗯……我们这里平时可不常见到$c……', `MaleText_loc5`='嗯...不常有$c跑來這裡...', `MaleText_loc7`='Hm... no se encuentra a muchos de tu clase por aquí...', `FemaleText_loc1`='하... $c|1이;가; 어쩐 일로 여기까지 다 올라오고 그런다지...', `FemaleText_loc4`='嗯……我们这里平时可不常见到$c……', `FemaleText_loc5`='嗯...這邊很少看到$c。', `FemaleText_loc7`='Hm... no se encuentra a muchos de tu clase por aquí...' WHERE `ID`=56118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안녕하세요! 예전에 어디서 본 적이...', `MaleText_loc4`='噢，你好！以前没见过你……', `MaleText_loc5`='喔哈囉!好像從沒在這附近見過你...', `MaleText_loc7`='¡Ah, hola! No te había visto nunca por aquí...' WHERE `ID`=56119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 몸부림쳐 밧줄을 끊고 자유로워집니다!', `MaleText_loc4`='%s用力咬断了缰绳，逃了出来！', `MaleText_loc5`='%s猛力扯斷牠的拴繩，獲得了自由!', `MaleText_loc7`='¡%s rompe la soga con gran esfuerzo y es libre!' WHERE `ID`=56120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곡물창고로 가면 맥아를 구할 수 있을 겁니다.', `MaleText_loc4`='我想你可以从粮仓里找到你要的甜麦芽。', `MaleText_loc5`='我猜你能在榖倉裡找到你要的麥芽。', `MaleText_loc7`='Supongo que podrás encontrar tus maltas en el granero.' WHERE `ID`=56121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머드머그!', `FemaleText_loc4`='泥盏！', `FemaleText_loc5`='泥杯!', `FemaleText_loc7`='¡Caolín!' WHERE `ID`=56122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그!', `MaleText_loc4`='泥盏！', `MaleText_loc5`='泥杯!', `MaleText_loc7`='¡Caolín!' WHERE `ID`=56123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 말하던 맛좋은 맥주 양조를 도와주러 왔습니다.', `MaleText_loc4`='我是来帮忙酿造你们说的那种神奇啤酒的。', `MaleText_loc5`='我是來幫你製作你說的奇妙啤酒的。', `MaleText_loc7`='Estoy aquí para ayudar con esa cerveza tan selecta de la que hablabas.' WHERE `ID`=56124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 와서 다행이네. 스타우트 맥주를 만들 건데, 물을 몇 통 갖다 주겠나?', `MaleText_loc4`='很高兴你能加入。我们要酿一种烈酒。你能弄几桶水来吗？', `MaleText_loc5`='很高興你來了。我們正要開始釀酒。你能帶幾桶水來嗎?', `MaleText_loc7`='Me alegro de contar contigo. Vamos a hacer cerveza negra. ¿Puedes traerme unos barriles de agua?' WHERE `ID`=56125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='包在我身上。', `MaleText_loc5`='搞定。', `MaleText_loc7`='Marchando.' WHERE `ID`=56126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리, 맥아를 구해 오렴. 나는 이 동네 술을... 연구하고 있으마. 이곳에서 모이세.', `MaleText_loc4`='丽丽，你去找麦芽。我……去调查当地的啤酒。然后在这儿会合。', `MaleText_loc5`='莉莉，你去拿麥芽。我會去...研究當地的啤酒。我們回來這裡碰頭。', `MaleText_loc7`='Li Li, tú trae la malta. Yo voy a... investigar la cerveza local. Nos reuniremos aquí.' WHERE `ID`=56127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연구라고요? 좋죠...', `FemaleText_loc4`='“调查”？好吧。', `FemaleText_loc5`='「研究?」最好是。', `FemaleText_loc7`='¿"Investigar"? Ya.' WHERE `ID`=56128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속여서 미안하구나. 하지만 꼭 필요한 일이었다.', `MaleText_loc4`='$n，很抱歉欺骗了你，但这实属无奈之举。', `MaleText_loc5`='很抱歉騙了你，但是我必須這麼做。', `MaleText_loc7`='Te pido disculpas por el engaño, pero era necesario.' WHERE `ID`=56129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 수천 년 동안, 너희들과 만나지 못했구나.', `MaleText_loc4`='数千年来，我们从未遇见过你这样的人。', `MaleText_loc5`='幾千年來，我們從沒見過你們這一類人。', `MaleText_loc7`='No hemos visto a nadie de los tuyos en miles de años.' WHERE `ID`=56130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 우선 네 마음에 품은 뜻을 확인해야 했다.', `MaleText_loc4`='所以我得先探明你的心意，这非常重要。', `MaleText_loc5`='我不得不先評量你和你的心胸氣度。', `MaleText_loc7`='Era crucial medir la fuerza de tu corazón antes que nada.' WHERE `ID`=56131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금까지, 나는 네 행동에 악의 기운이 도사리지 않았음을 직접 보았다.', `FemaleText_loc4`='现在，我已经看到了，你的行为非常正派。', `FemaleText_loc5`='目前，我在你的行為間沒有發現邪惡。', `FemaleText_loc7`='Pero he comprobado que tus actos no ocultan maldad alguna.' WHERE `ID`=56132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아, 이제 나는 너무 약해져서 운명의 실타래를 볼 수가 없구나.', `FemaleText_loc4`='唉，我变得越来越虚弱，已经看不清命运的织线了。', `FemaleText_loc5`='可惜的是，我變得太虛弱，已無法看穿交織的命運。', `FemaleText_loc7`='Por desgracia, ya soy demasiado débil para ver las hebras del destino.' WHERE `ID`=56133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 어떤 운명의 가닥에 올라 있는지 궁금하구나. 매듭을 풀어내는 가닥일까, 아니면 매듭을 묶어두는 가닥일까?', `FemaleText_loc4`='我很好奇，你到底是哪一根线？到底是毁天灭地的那一根，还是力挽狂澜的那一根？', `FemaleText_loc5`='我忍不住想，哪一條線是屬於你的命運呢?闡明脈絡的那一條，或是串連一切的那一條?', `FemaleText_loc7`='¿Qué hebra eres tú? ¿La que deshilacha el tejido, o la que lo mantiene unido?' WHERE `ID`=56134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 이제 늙었다. 이 세계에서의 내 시간도 거의 끝났구나.', `FemaleText_loc4`='我老了，小家伙。我的时日无多了。', `FemaleText_loc5`='孩子，我老了，我就快要離開這個世界了。', `FemaleText_loc7`='Me hago viejo. Mi tiempo en este mundo casi ha llegado a su fin.' WHERE `ID`=56135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 멀리 거대한 조각상이 보이느냐?', `FemaleText_loc4`='看到远处那宏伟的雕像了吗？', `FemaleText_loc5`='有看見遠方那尊雄偉雕像嗎?', `FemaleText_loc7`='¿Ves aquella gran estatua?' WHERE `ID`=56136;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조각공들이 수백 년째 애쓴 끝에, 거의 완성이 되었다.', `FemaleText_loc4`='那些建造者辛勤劳作多年，就快完工了。', `FemaleText_loc5`='多年來，工人們一直在建造它，已經快完成了。', `FemaleText_loc7`='Muchos años de trabajo han sido necesarios, pero casi está terminada.' WHERE `ID`=56137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 덕분에 손에 넣은 비취만 있으면, 모두 끝날 것이다.', `FemaleText_loc4`='再来些玉石——就是你取回的那种——就大功告成了。', `FemaleText_loc5`='只需要再一小塊，就是你幫忙取來的那一種玉，雕像就完成了。', `FemaleText_loc7`='Un poco más de jade, el jade que tú has ayudado a encontrar, y estará terminada.' WHERE `ID`=56138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 마지막 숨결로, 생명의 정수를 조각상에 불어 넣으면, 새로운 수호자가 탄생한다.', `FemaleText_loc4`='我会将我所有的生命精华灌输到雕像中去。新的守护者由此诞生。', `FemaleText_loc5`='我會用最後一口氣把我的生命精華轉移到雕像裡，使新的守護者誕生。', `FemaleText_loc7`='Con mi último aliento transferiré mi esencia vital a la estatua, y nacerá un nuevo guardián.' WHERE `ID`=56139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가, 너도 네게 소중한 것을 지켜야 할 때가 올 것이다.', `FemaleText_loc4`='有朝一日，你也会响应召唤，捍卫你所挚爱的一切。', `FemaleText_loc5`='有一天，可能會有人召喚你為所有摯愛的一切而戰。', `FemaleText_loc7`='Es posible que algún día tú también tengas que defender todo lo que amas.' WHERE `ID`=56140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='슬퍼하지 마라, 모두 순환일 뿐이니. 나는 그 시작도 끝도 아니다.', `FemaleText_loc4`='不要难过。这就是轮回——我非起点，亦非终点。', `FemaleText_loc5`='不要哀傷。這就是萬物的循環，我既不是這循環的開始，也不是結束。', `FemaleText_loc7`='No estés triste. El ciclo continúa: ni empieza ni acaba conmigo.' WHERE `ID`=56141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먼지가 되어 사라진 이들을 경배하라.', `FemaleText_loc4`='缅怀那些已归于尘土的逝者。', `FemaleText_loc5`='要敬畏已經回歸塵土的那些人。', `FemaleText_loc7`='Venera a aquellos que han vuelto al polvo.' WHERE `ID`=56142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅에서 네게 주어진 삶을 기뻐하라.', `FemaleText_loc4`='珍惜让你来到这尘世的生命。', `FemaleText_loc5`='並歡慶你為這塊土地播下的生命。', `FemaleText_loc7`='Celebra la vida que te ha sido concedida en este mundo.' WHERE `ID`=56143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 받는 모든 것을 두 배로 돌려주거라.', `FemaleText_loc4`='滴水之恩，当涌泉相报。', `FemaleText_loc5`='你得到了任何東西，用雙倍去回饋。', `FemaleText_loc7`='Por cada cosa que cojas, da el doble.' WHERE `ID`=56144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 해야만 우리 지혜가 오랜 세월 전해질 수 있다.', `FemaleText_loc4`='只有这样，我们的智慧才能得以代代相传，绵延后世。', `FemaleText_loc5`='只有這樣我們的智慧才能超越時間，永續傳承。', `FemaleText_loc7`='Solo así podremos conservar nuestra sabiduría a lo largo del tiempo.' WHERE `ID`=56145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것이 우리가 영원히 살아 남는 방법이다.', `FemaleText_loc4`='这便是我们的生存之道，亘古不变。', `FemaleText_loc5`='這就是我輩的生活方式，千秋萬載。', `FemaleText_loc7`='Así es como vivimos en la eternidad.' WHERE `ID`=56146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피곤하구나. 이제 쉬어야겠다.', `FemaleText_loc4`='我累了。需要休息了。', `FemaleText_loc5`='我疲倦了，得休息一下。', `FemaleText_loc7`='Me estoy fatigando. Debo descansar.' WHERE `ID`=56147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='현명한 선택을 해라, 어린 존재야.', `FemaleText_loc4`='作出明智的选择吧，年轻人。', `FemaleText_loc5`='要明智地選擇前方的道路，年輕人。', `FemaleText_loc7`='Elige bien, joven.' WHERE `ID`=56148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 곡물은 맛이 너무 퀴퀴하고 써서 화까지 납니다.', `MaleText_loc4`='这些谷物的味道不够新鲜，又苦又涩。', `MaleText_loc5`='這榖物嚐起來太老、太澀，而且讓人感到憤怒。', `MaleText_loc7`='Este grano sabe a viejo, amargo y enfadado.', `FemaleText_loc1`='이 곡물은 맛이 너무 퀴퀴하고 써서 화까지 나네요.', `FemaleText_loc4`='这些谷物的味道不够新鲜，又苦又涩。', `FemaleText_loc5`='這榖物嚐起來太老、太澀，而且讓人感到憤怒。', `FemaleText_loc7`='Este grano sabe a viejo, amargo y enfadado.' WHERE `ID`=56149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 곡물은 맛이 너무 가볍고 톡톡 튑니다.', `MaleText_loc4`='这谷物吃起来太清淡，太有弹性了。', `MaleText_loc5`='這榖物嚐起來太淡，又讓人感到渾身輕盈。', `MaleText_loc7`='Este grano tiene un sabor demasiado ligero y vivo.', `FemaleText_loc1`='이 곡물은 맛이 너무 가볍고 톡톡 튀네요.', `FemaleText_loc4`='这谷物吃起来太清淡，太有弹性了。', `FemaleText_loc5`='這榖物嚐起來太淡，又讓人感到渾身輕盈。', `FemaleText_loc7`='Este grano tiene un sabor demasiado ligero y vivo.' WHERE `ID`=56150;
