UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 농사철에는 밭을 놀리고 있습니다. 현명한 농부는 땅이 쉬어야 할 때가 언제인지 아는 법이지요.', `MaleText_loc4`='我打算让我的田休耕一季。一个聪明的农夫知道什么时候该让土地休息。', `MaleText_loc5`='這一季我會讓我的田地保持在休耕狀態。聰明的農夫知道土地何時需要休息。', `MaleText_loc7`='Voy a dejar mis campos en barbecho esta temporada. Un granjero sabio sabe cuándo debe dejar descansar la tierra.' WHERE `ID`=56219;
