UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보라고, $n!$b$b네가 없는 사이에 우리가 이 원숭이 놈들을 진짜 군대로 변화시켰어!', `MaleText_loc4`='$n，瞧瞧他们！$b$b你不在的这段时间里，我们已经把这群猴子打造成一支训练有素的军队啦！', `MaleText_loc5`='看看你的四周，$n!$b$b你不在的時候，我們把這些猴子變成了超級大軍!', `MaleText_loc7`='¡Mira a tu alrededor, $n!$b$bMientras estabas fuera, ¡hemos convertido a esos monos en un auténtico ejército!' WHERE `ID`=56222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 비단을 더 생산적인 방법으로 만들어내는 방법을 찾아내는 일을 맡았습니다. 그런데 제 자만심 때문에 괴물을 만들어내고 말았군요! 이건 제가 무덤에 가서도 부끄러워해야 할 일입니다.', `MaleText_loc4`='我的任务就是设法提高蚕丝产量。但我过于自信，竟造出了怪物！这将是我的毕生的耻辱。', `MaleText_loc5`='我身負提升絲產量的任務，但是因為我的傲慢，我創造出了一群怪物!這是我一輩子的恥辱。', `MaleText_loc7`='Se me encargó encontrar maneras más productivas de crear seda. ¡En mi arrogancia, he creado monstruos! Es una losa con la que tendré que cargar hasta el fin de mis días.' WHERE `ID`=56223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌 아가씨! 당근 꼭대기에서 춤 좀 춰 봐!', `MaleText_loc4`='熊猫小姐！在胡萝卜上面跳只舞吧！', `MaleText_loc5`='熊貓小姐!在胡蘿蔔上跳支舞吧!', `MaleText_loc7`='¡Mujer panda! ¡Baila encima de la zanahoria!' WHERE `ID`=56224;
