UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 저기 커다란 당근 위에 서 있는 동안 이 작은 당근도 들고 있어.', `MaleText_loc4`='在这儿，你站在大胡萝卜上，再拿着小胡萝卜！', `MaleText_loc5`='這兒，妳握住小胡蘿蔔，然後站在大胡蘿蔔上!', `MaleText_loc7`='¡Toma, coge esta pequeña zanahoria mientras te pones encima de la zanahoria grande!' WHERE `ID`=56232;
