UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주를 만들려는 친구를 돕고 싶은데, 지금 홉 열매가 필요합니다. 남는 것 좀 있으십니까?', `MaleText_loc4`='我在帮一个朋友酿造啤酒，需要用啤酒花。能给我一点吗？', `MaleText_loc5`='我正在幫一個朋友釀些啤酒，我們需要啤酒花。你有多出來的啤酒花嗎?', `MaleText_loc7`='Estoy ayudando a un amigo a preparar cerveza y necesitamos lúpulos. ¿Me podrías dar algunos?', `FemaleText_loc1`='맥주를 만들려는 친구를 돕고 싶은데, 지금 홉 열매가 필요합니다. 남는 것 좀 있으시나요?', `FemaleText_loc4`='我在帮一个朋友酿造啤酒，需要用啤酒花。能给我一点吗？', `FemaleText_loc5`='我正在幫一個朋友釀些啤酒，我們需要啤酒花。你有多出來的啤酒花嗎?', `FemaleText_loc7`='Estoy ayudando a un amigo a preparar cerveza y necesitamos lúpulos. ¿Me podrías dar algunos?' WHERE `ID`=56242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홉 열매 좀 살 수 있습니까?', `MaleText_loc4`='你能卖给我一些啤酒花吗？', `MaleText_loc5`='我可以跟你買些啤酒花嗎?', `MaleText_loc7`='¿Podrías venderme unos lúpulos?', `FemaleText_loc1`='홉 열매 좀 살 수 있나요?', `FemaleText_loc4`='你能卖给我一些啤酒花吗？', `FemaleText_loc5`='我可以跟你買些啤酒花嗎?', `FemaleText_loc7`='¿Podrías venderme unos lúpulos?' WHERE `ID`=56243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남는 홉 열매 좀 있습니까?', `MaleText_loc4`='你有多余的啤酒花给我吗？', `MaleText_loc5`='你有多出來的啤酒花嗎?', `MaleText_loc7`='¿Podrías darme algunos lúpulos?', `FemaleText_loc1`='남는 홉 열매 좀 있나요?', `FemaleText_loc4`='你有多余的啤酒花给我吗？', `FemaleText_loc5`='你有多出來的啤酒花嗎?', `FemaleText_loc7`='¿Podrías darme algunos lúpulos?' WHERE `ID`=56244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 농작물에 물 주는 일을 많이 도와주신 것 같군요. 좋아요... 언덕골에 있는 당신 친구인 첸에게 홉 열매를 보낼게요.', `FemaleText_loc4`='我想你确实是帮我给植物浇过水了。很好……我会派人将啤酒花送到半山，交给你那位叫陈的朋友。', `FemaleText_loc5`='看來你的確幫我的植物澆了水。非常好...我會把啤酒花送去半丘給你的朋友老陳。', `FemaleText_loc7`='Bueno, tú me ayudaste a regar las plantas. En fin... haré que envíen los lúpulos a tu amigo Chen a El Alcor.' WHERE `ID`=56245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r님, 세상에 공짜는 없답니다. 홉 열매를 갖고 싶다면 일을 해야 해요.', `FemaleText_loc4`='天下没有免费的午餐，$r。想要啤酒花，你就得出点力。', `FemaleText_loc5`='$r，沒有不勞而獲這種事。你想要啤酒花，就得工作。', `FemaleText_loc7`='Nada es gratis, $r. Si quieres lúpulos, deberás trabajar para conseguirlos.' WHERE `ID`=56246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 저 잡초 문제를 도와주셨으니 제가 홉 열매를 조금이라도 드려야지요. 언덕골에 있는 첸 님에게 홉 열매를 보내겠습니다.', `MaleText_loc4`='当然了！你帮我除掉那些杂草，我肯定会分你一些啤酒花。我会把啤酒花送给半山的风暴烈酒大师的。', `MaleText_loc5`='當然!你幫我處理完這些雜草，分你一點啤酒花只是小事一件。我會把啤酒花送到半丘去給風暴烈酒大師。', `MaleText_loc7`='¡Por supuesto! Después de ayudarme con esas hierbas, compartir unos lúpulos contigo es lo menos que puedo hacer. Se los haré llegar al maestro Cerveza de Trueno, en El Alcor.' WHERE `ID`=56247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고는 싶지만, 제가 잡초 때문에 조금 골치가 아픕니다. 그... 저 좀 조금 도와주시겠지요? 그죠?', `MaleText_loc4`='我也很想帮你，$c，但我遇到一点关于杂草的小麻烦。嗯……你大概是不肯帮我解决问题的，是吧？', `MaleText_loc5`='$c，我可以幫你，不過這裡的雜草讓我有點頭痛。這麼說吧...你會幫我解決這個問題嗎?', `MaleText_loc7`='Lo haría si pudiera, $c, pero tengo un pequeño problema con unas malas hierbas. Dime... tú no estarías por la labor de echarme una mano, ¿verdad?' WHERE `ID`=56248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 토깽 놈들을 처치했으니 홉 열매를 드리죠. 뭉뭉을 시켜 언덕골로 홉 열매를 보내겠습니다.', `MaleText_loc4`='当然愿意了。你去杀几个兔妖，就挣到一些啤酒花。我会叫蒙蒙把啤酒花送去半山的。', `MaleText_loc5`='當然。殺幾隻兔妖，換取不少的啤酒花。我會叫芒芒把啤酒花送去半丘。', `MaleText_loc7`='Desde luego. Si matas a unos cuantos mures, te ganarás unas fanegas de lúpulos. Haré que Mung-Mung te las envíe a El Alcor.' WHERE `ID`=56249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 뭉뭉에게 물어봐야 할 겁니다. 우리 식량 창고를 관리하고 있으니까요.', `MaleText_loc4`='你得跟蒙蒙商量商量。是他在管理我们的存粮。', `MaleText_loc5`='這件事你得去問芒芒。他負責管理我們的食品店。', `MaleText_loc7`='Eso tendrás que preguntárselo a Mung-Mung. Él se encarga de nuestras reservas de alimentos.' WHERE `ID`=56250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='홉 열매가 필요하다고 하셨나요? 좋아요. 제가 언덕골로 홉 열매를 보낼게요.', `FemaleText_loc4`='你说你需要啤酒花？好吧。我会送一些到半山。', `FemaleText_loc5`='你說你需要啤酒花?非常好，我會送一些去半丘。', `FemaleText_loc7`='¿Has dicho que necesitabas lúpulos? Muy bien. Te enviaré unos cuantos a El Alcor.' WHERE `ID`=56251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 정말 구세주시군요. 어서 언덕골로 홉 열매를 보내겠습니다.', `MaleText_loc4`='你真是个救星，$c。我立刻就将啤酒花送到半山。', `MaleText_loc5`='你真是救命恩人，$c。我會立刻把你的啤酒花送去半丘。', `MaleText_loc7`='Me salvas la vida, $c. Haré que te entreguen los lúpulos en El Alcor de inmediato.' WHERE `ID`=56252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코가 호숫가 꽉 잡고 있어!$b$b호젠 병사들이 먹을 미끈고기가 잔뜩해!', `MaleText_loc4`='里克把这贱人抓起来了！$b$b猢狲大军有了好多光板儿！', `MaleText_loc5`='瑞可牢牢逮住了這個傢伙!$b$b猴人大軍有很多滑魚可吃!', `MaleText_loc7`='¡Riko encerró a este makaku bajo llave!$b$b¡Muchos mandukos para ejército hozen!' WHERE `ID`=56253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홉 열매가 필요하다고 했어? 그거야 별거 아니지. 나 대신 토깽 놈들을 처치해줬으니 뭉뭉이 언덕골로 홉을 보내준다.', `MaleText_loc4`='你说你需要啤酒花？没问题。你帮我杀兔妖，蒙蒙就帮你把啤酒花送到半山。', `MaleText_loc5`='你說你想要啤酒花?沒問題。你幫我殺了兔妖，芒芒會幫你把啤酒花送去半丘。', `MaleText_loc7`='¿Quieres lúpulos? Ningún problema. Tú mata a unos cuantos mures. Mung-Mung te enviará unos lúpulos a El Alcor.' WHERE `ID`=56254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토깽 놈들! 으으으! 정말 수도 없이 많군!', `MaleText_loc4`='兔妖！嗨！数不尽的兔妖！', `MaleText_loc5`='兔妖!吼!他們的數量根本不會減少!', `MaleText_loc7`='¡Mures! ¡Uff! ¡No se acaban nunca!' WHERE `ID`=56255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미나야! 돌아왔구나!', `MaleText_loc4`='米娜！你回来了！', `MaleText_loc5`='米娜!妳回家了!', `MaleText_loc7`='¡Mina! ¡Estás en casa!' WHERE `ID`=56256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠... 저는 이제 당근이라면 쳐다보기도 싫어요.', `FemaleText_loc4`='爸爸……我再也不想看到胡萝卜了。', `FemaleText_loc5`='爸...我再也不想看到任何胡蘿蔔了。', `FemaleText_loc7`='Papá... no quiero volver a ver una zanahoria en mi vida.' WHERE `ID`=56257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 소용돌이로 데려가주십시오.', `MaleText_loc4`='送我去大漩涡。', `MaleText_loc5`='請你帶我去大漩渦。', `MaleText_loc7`='Llévame a La Vorágine.', `FemaleText_loc1`='혼돈의 소용돌이로 데려가주세요.', `FemaleText_loc4`='送我去大漩涡。', `FemaleText_loc5`='請你帶我去大漩渦。', `FemaleText_loc7`='Llévame a La Vorágine.' WHERE `ID`=56258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랙혼과 싸울 수 있도록 하늘불꽃호 갑판으로 데려가 주십시오.', `MaleText_loc4`='我要挑战黑角，送我去天火号甲板。', `MaleText_loc5`='帶我登上天火號甲板，與黑角作戰。', `MaleText_loc7`='Llévame a la cubierta de El Abrasacielos para luchar contra Cuerno Negro.', `FemaleText_loc1`='블랙혼과 싸울 수 있도록 하늘불꽃호 갑판으로 데려가 주세요.', `FemaleText_loc4`='我要挑战黑角，送我去天火号甲板。', `FemaleText_loc5`='帶我登上天火號甲板，與黑角作戰。', `FemaleText_loc7`='Llévame a la cubierta de El Abrasacielos para luchar contra Cuerno Negro.' WHERE `ID`=56259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍술사 하가라와 싸울 수 있도록 고룡쉼터 사원 정상으로 데려가 주십시오.', `MaleText_loc4`='我要挑战哈格拉，送我去龙眠神殿顶层。', `MaleText_loc5`='帶我到龍眠神殿之頂，與哈甲拉作戰。', `MaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Hagara.', `FemaleText_loc1`='폭풍술사 하가라와 싸울 수 있도록 고룡쉼터 사원 정상으로 데려가 주세요.', `FemaleText_loc4`='我要挑战哈格拉，送我去龙眠神殿顶层。', `FemaleText_loc5`='帶我到龍眠神殿之頂，與哈甲拉作戰。', `FemaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Hagara.' WHERE `ID`=56260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요르사지, 존오즈와 싸울 수 있도록 고룡쉼터 사원 1층으로 데려가 주십시오.', `MaleText_loc4`='我要挑战约萨希和佐诺兹，送我去龙眠神殿底层。', `MaleText_loc5`='請你帶我去龍眠神殿底下，準備和尤沙吉與松奧茲作戰。', `MaleText_loc7`='Llévame a la base del Templo del Reposo del Dragón para luchar contra Yor''sahj y Zon''ozz.', `FemaleText_loc1`='요르사지, 존오즈와 싸울 수 있도록 고룡쉼터 사원 1층으로 데려가 주세요.', `FemaleText_loc4`='我要挑战约萨希和佐诺兹，送我去龙眠神殿底层。', `FemaleText_loc5`='請你帶我去龍眠神殿底下，準備和尤沙吉與松奧茲作戰。', `FemaleText_loc7`='Llévame a la base del Templo del Reposo del Dragón para luchar contra Yor''sahj y Zon''ozz.' WHERE `ID`=56261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당근을... 너무... 많이...', `FemaleText_loc4`='这么……多……胡萝卜……', `FemaleText_loc5`='好...多...胡蘿蔔...', `FemaleText_loc7`='Son... demasiadas... zanahorias...' WHERE `ID`=56262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요, 미나. 여기서 나갑시다.', `MaleText_loc4`='快来，米娜。我们离开这儿。', `MaleText_loc5`='來吧，米娜。我們把妳弄出這裡。', `MaleText_loc7`='Venga, Mina. Vamos a sacarte de aquí.', `FemaleText_loc1`='어서요, 미나, 여기서 나가요.', `FemaleText_loc4`='快来，米娜。我们离开这儿。', `FemaleText_loc5`='來吧，米娜。我們把妳弄出這裡。', `FemaleText_loc7`='Venga, Mina. Vamos a sacarte de aquí.' WHERE `ID`=56263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비룡이 빠르게 날아와 황혼의 폭파병을 갑판에 떨어뜨립니다!', `MaleText_loc4`='一条幼龙俯冲下来，往甲板上投放了一个暮光工兵！', `MaleText_loc5`='一頭龍急速飛來，載送一名暮光工兵降落到甲板上!', `MaleText_loc7`='¡Un draco desciende para dejar a un zapador Crepuscular en la cubierta!' WHERE `ID`=56264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 사원에서 빠져나왔네. 놈들을 무찔러야 하네... 우리 목숨을 바쳐서라도.', `MaleText_loc4`='煞魔从寺庙里跑出来了，我们得把他们赶回去……或者同归于尽。', `MaleText_loc5`='煞衝出了寺廟。我們必須擊退他們...或至死方休。', `MaleText_loc7`='Los sha se han escapado del templo. Debemos capturarlos... o morir en el intento.' WHERE `ID`=56265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군, $r.', `MaleText_loc4`='欢迎，$r。', `MaleText_loc5`='歡迎，$r。', `MaleText_loc7`='Saludos, $r.' WHERE `ID`=56266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집으로 가요.', `FemaleText_loc4`='我们回家。', `FemaleText_loc5`='我們回家吧。', `FemaleText_loc7`='Vámonos a casa.' WHERE `ID`=56267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 탈 것에 탄 채로 농작물에 물을 줄 수 있는데, 왜 제가 그걸 해야 하나요?', `FemaleText_loc4`='当然，你可以在骑乘状态下去为植物浇水。我为什么要在乎这个？', `FemaleText_loc5`='當然，你可以騎在坐騎上澆水。我何必管那麼多?', `FemaleText_loc7`='Claro que puedes regar las plantas a lomos de una montura. ¿A mí qué más me da?' WHERE `ID`=56268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡쉼터 용군단이여, 공격하라!', `MaleText_loc4`='龙眠联军，进攻！', `MaleText_loc5`='龍眠協調者，進攻!', `MaleText_loc7`='¡El Reposo del Dragón, al ataque!' WHERE `ID`=56269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타이리고사 님이 아직 살아있다! 계속 몰아붙여라! 사원으로!', `MaleText_loc4`='塔丽苟萨还活着！我们必须前进，朝神殿进军！', `MaleText_loc5`='泰利苟莎還活著!我們必須抵達神殿!', `MaleText_loc7`='¡Tyrygosa aún vive! Debemos presionar, ¡al templo!' WHERE `ID`=56270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽... 왼쪽! 왼쪽으로 가라고오오오!', `MaleText_loc4`='左转……左转！左——转！', `MaleText_loc5`='左...左!左～～～～～～!', `MaleText_loc7`='Izquierda... ¡Izquierda! ¡¡¡Izquierda!!!' WHERE `ID`=56271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 오른쪽! 오른쪽으로!', `MaleText_loc4`='不！右转！右转！', `MaleText_loc5`='不對!右!往右!', `MaleText_loc7`='¡No! ¡Derecha! ¡A la derecha!' WHERE `ID`=56272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아아! 우린 다 끝장이야!', `MaleText_loc4`='啊啊啊！我们都要完蛋啦！', `MaleText_loc5`='啊啊啊啊啊!我們完蛋了!', `MaleText_loc7`='¡Aaaaaaahhh! ¡Estamos todos condenados!' WHERE `ID`=56273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타라!', `MaleText_loc4`='着火啦！', `MaleText_loc5`='燒燒燒!', `MaleText_loc7`='¡Ardaaann!' WHERE `ID`=56274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿵!', `MaleText_loc4`='践踏。', `MaleText_loc5`='我踩!', `MaleText_loc7`='Ahora pisotón.' WHERE `ID`=56275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전군, 진격!', `MaleText_loc4`='向着前线进发！', `MaleText_loc5`='向前線進軍!', `MaleText_loc7`='¡Avancen al frente!' WHERE `ID`=56276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 포위를 뚫어야 한다. 전군, 전선을 사수해라.', `MaleText_loc4`='必须打退围攻的敌人。龙眠联军，守住阵线!', `MaleText_loc5`='必須擋下攻擊。龍眠協調者，守住防線!', `MaleText_loc7`='El sitio deber haber recaído. Reposo del Dragón, ¡defiende la línea!' WHERE `ID`=56277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 제자는 완벽을 추구하는 과정에서 실패는 몇 번이라도 감수해야 한다는 사실을 가끔 잊어버리곤 한다네.', `MaleText_loc4`='我的学徒们常常忘记，一个人要达到登峰造极的境界必须先经历多次失败。', `MaleText_loc5`='我手下的學徒常會忘記，追求完美的過程中一定會失敗很多次。', `MaleText_loc7`='Mi oficial suele olvidar que uno debe esperar cometer muchos errores hasta alcanzar la perfección.' WHERE `ID`=56278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 경험이 아주 풍부해 보이는 것 같군.', `MaleText_loc4`='我觉得你这个人饱经沧桑。', `MaleText_loc5`='我覺得你似乎是有很多經驗的傢伙。', `MaleText_loc7`='Parece que has vivido muchas experiencias.' WHERE `ID`=56279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷이 아주 멋지군. 누가 만들었는지 물어봐도 되겠나?', `MaleText_loc4`='你穿的外套挺有趣。我能问一下这是出自谁的手吗？', `MaleText_loc5`='你身上的裝扮真有趣。我能否問一下是出自誰的手?', `MaleText_loc7`='Qué vestimenta más interesante llevas. ¿Quién es el artesano que la ha cosido, si se puede preguntar?' WHERE `ID`=56280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕망이 높은 비단장인 차이가 최고의 비단 한 올을 만들어 냈는데, 그걸 떨어뜨리자 땅 속으로 미끄러져 들어갔던 게 기억나는군. 여태껏 그런 비단을 본 적이 없다네.', `MaleText_loc4`='我记得曾经有位德高望重的蔡丝匠做出了一种极品丝线，它掉在地上时都能把泥土切开。可那之后我们就再也没见过那种丝了。', `MaleText_loc5`='我記得有一次，可敬的絲綢大師老蔡創造出一段奇細無比的絲線，細到它一落地就切進土裡。我們從此再也沒看過這條線。', `MaleText_loc7`='Recuerdo una ocasión en que el venerable maestro de la seda Tsai creó una hebra de seda tan fina que atravesó la tierra cuando la dejó caer. Jamás volvimos a verla.' WHERE `ID`=56281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 실험을 엉망으로 망쳤던 기억이 나는군. 실험장이 이 시대의 세계에서는 본 적이 없던 거대한 유충들로 들끓었다네.', `MaleText_loc4`='我记得我的第一次实验失败了。这些地里当时爬满了前所未见的超级大虫子。', `MaleText_loc5`='我記得我第一次的實驗出了很大的差錯，這地方爬滿了前所未見的超級幼蟲。', `MaleText_loc7`='Recuerdo que mi primer experimento salió fatal. Estos campos estaban llenos de larvas más grandes de lo que se había visto en esta época del mundo.' WHERE `ID`=56282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번은 길쌈장이 젱이 비단 실을 만들어냈는데, 너무나 얇고 부드러워 갈라진 틈으로 미끄러져 들어갔다네. 그런 실이 다시 나오지는 않았지만, 요즘은 기대하고 있지.', `MaleText_loc4`='纺丝人锦织曾经织出很薄很滑的丝绸，可以瞬间从细缝中滑过。虽然尚未将其复制出来，但我们希望能在近期成功。', `MaleText_loc5`='紡織大王小政曾經紡出一段又細又滑的絲線，細滑到一溜溜進時間的細縫裡去了。它至今還沒出現，但我們預期是在這幾天。', `MaleText_loc7`='El maestro del telar Jeng elaboró en una ocasión una tela de seda tan fina y suave que se deslizó por una grieta en el tiempo. No ha vuelto a aparecer, pero esperamos que lo haga un día de estos.' WHERE `ID`=56283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 이방인이여. 나는 비단장인인 차이일세. 고대의 황실 비단 농장에 온 것을 환영하네.$b$b이 비단 농장은 판다리아 왕조 초기에 설립됐으며, 세대를 거칠수록 더 좋은 품질의 비단을 만들어내고 있다네.', `MaleText_loc4`='欢迎你，陌生人。我是蔡丝匠。欢迎来到古老的皇家丝场。$b$b这个农场可以回溯到最早的几个熊猫人王朝，在丝绸质量方面是青出于蓝胜于蓝，一代更比一代强。', `MaleText_loc5`='歡迎，陌生人。我是絲綢大師老蔡。歡迎來到我們歷史悠久的皇家蠶絲農場。$b$b這農場可追溯到潘達利亞最古老的朝代，每個世代都創造出品質更勝前代的蠶絲。', `MaleText_loc7`='Saludos, $gforastero:forastera;. Soy el maestro de la seda Tsai. Bienvenido a la ancestral Granja de Seda Imperial.$b$bEsta granja se remonta a la época de alguna de las dinastías más antiguas de Pandaria, y cada generación supera a la anterior en la calidad de la seda.' WHERE `ID`=56284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷차림이 여행할 때 딱 좋아 보이는군요. 아주 보기 좋습니다. 나중에 제 제품 목록에 그런 디자인으로 넣어 보는 것도 괜찮겠군요. 상표 이름은...$b$b팔에감어로 해야겠습니다.', `MaleText_loc4`='你这身衣服，好像很适合旅行时穿。看起来很有趣。我或许会将它用到以后的服装系列里。我打算叫它：$b$b$p特别款。', `MaleText_loc5`='從你設計的衣服可看出你豐富的閱歷。很有趣的設計，我可能會拿來用在我其中一條服裝生產線裡。我會稱之為:$b$b$p風。', `MaleText_loc7`='Tu ropa parece muy viajada. Tiene un aspecto muy interesante. Podría utilizarla en alguna de mis futuras líneas de moda. La llamaré:$b$b$písima.' WHERE `ID`=56285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신발? 아니, 허리띠? 그건 더더욱 아니고... 셔츠? 멋지긴 한데 잘 안 어울리는군요. 진짜 멋진 망토를 하나 해 드려야겠습니다. 그리고 영웅에게 딱 어울리는 조끼도 말이지요.', `MaleText_loc4`='靴子，不好。腰带，非常不好。衬衣，挺好看，但不适合你。我们应该给你弄个斗篷。也许再配件样式符合英雄身份的外套。', `MaleText_loc5`='這靴子，不行。腰帶，喔太糟了。這衣服，棒透了，但不是指在你身上。我們應該給你弄一條真正的斗篷，或許再來件適合英雄剪裁的背心。', `MaleText_loc7`='Las botas, no. El cinturón, menos aún. La camisa, estupenda, pero a ti te sienta fatal. Deberíamos conseguirte una capa de verdad. Y quizá un chaleco con un corte de héroe adecuado.' WHERE `ID`=56286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 보니 고 사부님이 떠오르는군요. 허리 둘레는 빼고 말이죠.$b$B고 사부님은 처음에 넝마를 걸치고 시골 소년 같은 모습으로 제게 오셨지만, 걸음걸이는 예사롭지 않았습니다.$B$b우리는 함께 옷을 만들었고, 동부에서 2년 동안은 명성이 아주 자자했습니다.', `MaleText_loc4`='你让我想起了年轻的郭大师，他腰围要再细一点。$b$B我第一次见他时他还是个农场小工，尽管衣衫褴褛，但走起路来英姿飒爽，和他英俊的外表还挺相配。$B$b我们一起做了一个服装系列，在东部地区流行了至少两年。', `MaleText_loc5`='你讓我想起一名年輕的苟大師，只是肚子小了點。$B$B他來找我的時候只是個穿著破布的農村小孩，但他的步伐非常有型，引人注目。$b$b我們一起創造出在東部至少風靡了兩年的服裝生產線。', `MaleText_loc7`='Me recuerdas al maestro Goh de joven, excepto por el volumen.$b$BCuando acudió a mí no era más que un chico granjero andrajoso, pero su andar elegante atraía las miradas.$B$bJuntos creamos una línea de ropa que arrasó en el este durante al menos dos años.' WHERE `ID`=56287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가쇼.', `MaleText_loc4`='走开。', `MaleText_loc5`='走開!', `MaleText_loc7`='Márchate.', `FemaleText_loc1`='저리 가요.', `FemaleText_loc4`='走开。', `FemaleText_loc5`='走開!', `FemaleText_loc7`='Márchate.' WHERE `ID`=56288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 있고 싶소.', `MaleText_loc4`='让我一个人呆着。', `MaleText_loc5`='讓我靜一靜。', `MaleText_loc7`='Déjame en paz.', `FemaleText_loc1`='혼자 있고 싶어요.', `FemaleText_loc4`='让我一个人呆着。', `FemaleText_loc5`='讓我靜一靜。', `FemaleText_loc7`='Déjame en paz.' WHERE `ID`=56289;
