UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 바짝 붙지 좀 마시오. 이 마을 사람들은 어찌나 바짝 붙어 다니는지, 거리라는 게 없다오.', `MaleText_loc4`='别挤我，人们总喜欢在村子里挤成一堆。没地方啦。', `MaleText_loc5`='不要再擠我了，這個村莊裡的人一天到晚都在那邊推來擠去的。已經沒位置了。', `MaleText_loc7`='Deja de agobiarme, todo el mundo en esta aldea me agobia sin parar. No hay espacio.', `FemaleText_loc1`='그렇게 바짝 붙지 좀 마요. 이 마을 사람들은 어찌나 바짝 붙어 다니는지, 거리라는 게 없다니까.', `FemaleText_loc4`='别挤我，人们总喜欢在村子里挤成一堆。没地方啦。', `FemaleText_loc5`='不要再擠我了，這個村莊裡的人一天到晚都在那邊推來擠去的。已經沒位置了。', `FemaleText_loc7`='Deja de agobiarme, todo el mundo en esta aldea me agobia sin parar. No hay espacio.' WHERE `ID`=56294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 비가 오고 있소. 날씨도 춥고... 그나마 요즘은 태풍은 없군.', `MaleText_loc4`='天还在下雨。又冷。还好最近没台风。', `MaleText_loc5`='雨還在下噢，而且冷的要命。至少我們最近沒有碰上颱風。', `MaleText_loc7`='Sigue lloviendo. Y hace un frío que pela. Al menos no hemos sufrido ningún tifón últimamente.', `FemaleText_loc1`='아직도 비가 오고 있어요. 날씨도 춥고... 그나마 요즘은 태풍은 없네요.', `FemaleText_loc4`='天还在下雨。又冷。还好最近没台风。', `FemaleText_loc5`='雨還在下噢，而且冷的要命。至少我們最近沒有碰上颱風。', `FemaleText_loc7`='Sigue lloviendo. Y hace un frío que pela. Al menos no hemos sufrido ningún tifón últimamente.' WHERE `ID`=56295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 귀찮아!', `MaleText_loc4`='噢，麻烦让一下。', `MaleText_loc5`='喔，老兄。', `MaleText_loc7`='Ay, madre.', `FemaleText_loc1`='아, 귀찮아!', `FemaleText_loc4`='噢，麻烦让一下。', `FemaleText_loc5`='喔，老兄。', `FemaleText_loc7`='Ay, madre.' WHERE `ID`=56296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손안의 바나나 한 개가 수풀 속의 바나나 두 개보다 낫다.', `MaleText_loc4`='一根香蕉在手，胜过两根香蕉在林。', `MaleText_loc5`='兩根蕉在樹不如一根蕉在手。', `MaleText_loc7`='Más vale pájaro en mano que ciento volando.', `FemaleText_loc1`='손안의 바나나 한 개가 수풀 속의 바나나 두 개보다 낫다.', `FemaleText_loc4`='一根香蕉在手，胜过两根香蕉在林。', `FemaleText_loc5`='兩根蕉在樹不如一根蕉在手。', `FemaleText_loc7`='Más vale pájaro en mano que ciento volando.' WHERE `ID`=56297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 모험가로군. 좋구먼... 참 좋을 때 오셨어.', `MaleText_loc4`='噢，太好了。一位冒险家。正是我需要的。', `MaleText_loc5`='喔，太棒了。一個冒險者，這正是我所需要的。', `MaleText_loc7`='Oh, estupendo. $gUn aventurero:una aventurera;. Justo lo que necesitaba.', `FemaleText_loc1`='아, 모험가네. 좋아... 참 좋을 때 오셨어.', `FemaleText_loc4`='噢，太好了。一位冒险家。正是我需要的。', `FemaleText_loc5`='喔，太棒了。一個冒險者，這正是我所需要的。', `FemaleText_loc7`='Oh, estupendo. $gUn aventurero:una aventurera;. Justo lo que necesitaba.' WHERE `ID`=56298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘도 별 볼 일 없는 하루군. 별 볼 일 없는 삶에 딱 어울리지.', `MaleText_loc4`='这日子马马虎虎吧。跟混日子的人正相配。', `MaleText_loc5`='這是個不怎麼樣的一天。正好，人生也是個不怎麼樣的人生。', `MaleText_loc7`='Un día sin pena ni gloria. En sintonía con una vida sin pena ni gloria.', `FemaleText_loc1`='오늘도 별 볼 일 없는 하루네. 별 볼 일 없는 삶에 딱 어울리지.', `FemaleText_loc4`='这日子马马虎虎吧。跟混日子的人正相配。', `FemaleText_loc5`='這是個不怎麼樣的一天。正好，人生也是個不怎麼樣的人生。', `FemaleText_loc7`='Un día sin pena ni gloria. En sintonía con una vida sin pena ni gloria.' WHERE `ID`=56299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비 조금 온다고 사람이 다치진 않지... 앞으로는 또 몰라도...', `MaleText_loc4`='这点小雨又不会伤人……起码目前没有。', `MaleText_loc5`='一場小雨不會傷害任何人...吧。', `MaleText_loc7`='Un poco de lluvia nunca ha hecho daño a nadie... aún.', `FemaleText_loc1`='비 조금 온다고 사람이 다치진 않죠... 앞으로는 또 몰라도...', `FemaleText_loc4`='这点小雨又不会伤人……起码目前没有。', `FemaleText_loc5`='一場小雨不會傷害任何人...吧。', `FemaleText_loc7`='Un poco de lluvia nunca ha hecho daño a nadie... aún.' WHERE `ID`=56300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 무슨 요일이오? 요즘은 다들 통 말이 없어서...', `MaleText_loc4`='今天几号了？都没人来告诉我。', `MaleText_loc5`='今天是什麼日子啊?都沒人告訴我。', `MaleText_loc7`='¿Qué día es? Nadie me cuenta nada.', `FemaleText_loc1`='오늘이 무슨 요일이죠? 요즘은 다들 통 말이 없어서...', `FemaleText_loc4`='今天几号了？都没人来告诉我。', `FemaleText_loc5`='今天是什麼日子啊?都沒人告訴我。', `FemaleText_loc7`='¿Qué día es? Nadie me cuenta nada.' WHERE `ID`=56301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮게 하지 마쇼.', `MaleText_loc4`='别烦我。', `MaleText_loc5`='別煩我。', `MaleText_loc7`='No me molestes.', `FemaleText_loc1`='귀찮게 하지 마요.', `FemaleText_loc4`='别烦我。', `FemaleText_loc5`='別煩我。', `FemaleText_loc7`='No me molestes.' WHERE `ID`=56302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이럴 수가 있지? 사는 게 신물이 난다오.', `MaleText_loc4`='这种事怎么会发生到我身上呢？我受够了这种生活。', `MaleText_loc5`='這怎麼會發生在我身上?這種生活真讓我厭倦。', `MaleText_loc7`='¿Cómo ha podido pasarme esto a mí? No aguanto esta vida.', `FemaleText_loc1`='어떻게 이럴 수가 있죠? 사는 게 신물이 나요.', `FemaleText_loc4`='这种事怎么会发生到我身上呢？我受够了这种生活。', `FemaleText_loc5`='這怎麼會發生在我身上?這種生活真讓我厭倦。', `FemaleText_loc7`='¿Cómo ha podido pasarme esto a mí? No aguanto esta vida.' WHERE `ID`=56303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘불꽃호에 온 걸 환영하오. 세계의 끝까지 추적할 준비는 됐소?', `MaleText_loc4`='欢迎登上天火号。我们要追到世界的尽头，你们准备好了吗？', `MaleText_loc5`='歡迎搭乘天火號。準備好追到天涯海角了嗎?', `MaleText_loc7`='Bienvenidos a bordo de El Rompecielos. ¿Listos para llegar hasta el fin del mundo?' WHERE `ID`=56304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 얼라이언스입니다. 언제나 준비되어 있죠.', `MaleText_loc4`='我们联盟时刻准备着。', `MaleText_loc5`='我們是聯盟，隨時都可以動手。', `MaleText_loc7`='Somos la Alianza. Siempre estamos preparados.', `FemaleText_loc1`='우리는 얼라이언스입니다. 언제나 준비되어 있죠.', `FemaleText_loc4`='我们联盟时刻准备着。', `FemaleText_loc5`='我們是聯盟，隨時都可以動手。', `FemaleText_loc7`='Somos la Alianza. Siempre estamos preparados.' WHERE `ID`=56305;
