UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 나쁜 벌레 같으니라고! 나쁜 놈! 나쁜 놈! 나쁜 놈!', `MaleText_loc4`='坏虫子！那是个非常非常非常坏的虫子！', `MaleText_loc5`='壞蟲!那是條壞壞壞壞蟲!', `MaleText_loc7`='¡GUSANO MALO! ¡ERES UN GUSANO MUY, MUY MALO!' WHERE `ID`=56309;
