UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 호드입니다. 언제나 준비되어 있죠.', `MaleText_loc4`='我们部落时刻准备着。', `MaleText_loc5`='我們是部落，隨時都可以動手。', `MaleText_loc7`='Somos la Horda. Siempre estamos preparados.', `FemaleText_loc1`='우리는 호드입니다. 언제나 준비되어 있죠.', `FemaleText_loc4`='我们部落时刻准备着。', `FemaleText_loc5`='我們是部落，隨時都可以動手。', `FemaleText_loc7`='Somos la Horda. Siempre estamos preparados.' WHERE `ID`=56311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 망치단이 후퇴한다! 사원을 되찾았다. 각자 위치를 지켜라!', `MaleText_loc4`='暮光之锤撤退了！我们夺回了神殿；进入神殿，稳固防守。', `MaleText_loc5`='暮光之錘正在撤退!我們守住神殿了，強化防禦工事!', `MaleText_loc7`='¡El Martillo Crepuscular se está retirando! El templo es nuestro, fortalezcan su posición en el interior.' WHERE `ID`=56312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 만나서 반갑습니다!$B$B배고프십니까?', `MaleText_loc4`='啊，很高兴见到你，我的朋友！$B$B饿了吗？', `MaleText_loc5`='啊，看見你真好，朋友!$B$B肚子餓了嗎?', `MaleText_loc7`='¡Ah, me alegro de verte, $p!$B$B¿Tienes hambre?' WHERE `ID`=56313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그런데 병 문제는 좀 죄송하게 됐습니다. 사실 두꺼비 알을 거기 한데 모아놓는 게 더 좋거든요. 좋은 맥주처럼 숙성이 돼서 말입니다.', `MaleText_loc4`='嘿，另外，关于那个瓶子，我很抱歉。其实我们应该把那些陈年老泥留在瓶子里——它们的年头都快赶上老酒了。', `MaleText_loc5`='嘿，對了，瓶子的事情不好意思。把那些老黏怪關在裡面其實比較好。那就像酒一樣越陳越香。', `MaleText_loc7`='Oye, perdona por lo de aquella botella, por cierto. Es mejor guardar todo el cieno viejo ahí; envejece como una buena cerveza.' WHERE `ID`=56314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디자이너가 천을 짠 방식을 보면 많은 것을 알 수 있습니다. 당신이 입은 옷을 보니 디자이너가 자존심보다는 기능에 치중했군요.$b$b옷감에 직접 마나를 주입해 단단히 여며져 있습니다. 인상적이긴 하지만, 예술적인 손길을 거치면 좀 더 나아질 겁니다.', `MaleText_loc4`='你总能从设计师设计的服装上看出他们的性格。你的服装看上去实用大于美观。$b$b灌注了法力的织物缝合紧密。很出色，不过要是能有一个风雅的设计师来改进一下就更好了。', `MaleText_loc5`='透過編織布料的方法，你可以了解很多和它的設計師有關之事。你的設計看起來重視機能性更甚於讓穿著者感到體面。$b$b這布料緊密地將法力封存在其中。令人印象深刻，但還可以再多點藝術設計。', `MaleText_loc7`='Se puede aprender mucho sobre un diseñador observando cómo teje sus telas. El tuyo parece que antepone la funcionalidad al orgullo.$b$bUn buen sellado con maná inyectado directamente en la tela. Impresionante, aunque no le vendría mal una mano artística.' WHERE `ID`=56315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부님, 횃불을 잃어 버렸습니다.', `MaleText_loc4`='师父，我的火炬不见了。', `MaleText_loc5`='大師，我的火把掉了。', `MaleText_loc7`='Maestro, he perdido mi antorcha...', `FemaleText_loc1`='사부님, 횃불을 잃어 버렸습니다.', `FemaleText_loc4`='师父，我的火炬不见了。', `FemaleText_loc5`='大師，我的火把掉了。', `FemaleText_loc7`='Maestro, he perdido mi antorcha...' WHERE `ID`=56316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 무능한 공격대가 싫어.', `FemaleText_loc4`='我恨无能的掠夺者。', `FemaleText_loc5`='我恨無能的敵人。', `FemaleText_loc7`='Odio a los asaltantes incompetentes.' WHERE `ID`=56317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래도 난 네가 싫어.', `FemaleText_loc4`='我还是很恨你。', `FemaleText_loc5`='我還是恨你。', `FemaleText_loc7`='Los sigo odiando.' WHERE `ID`=56318;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나를 싫어한다고? 좋아.', `FemaleText_loc4`='你恨我吗？很好。', `FemaleText_loc5`='你恨我嗎?很好。', `FemaleText_loc7`='¿Me odian? Bien.' WHERE `ID`=56319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 자비가 싫어.', `FemaleText_loc4`='我恨心慈手软。', `FemaleText_loc5`='我恨手下留情。', `FemaleText_loc7`='Odio la compasión.' WHERE `ID`=56320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 건 싫지 않았어.', `FemaleText_loc4`='我倒不太恨杀戮。', `FemaleText_loc5`='這個我倒是不恨。', `FemaleText_loc7`='Eso no lo odiaba.' WHERE `ID`=56321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 모험가들이 싫어.', `FemaleText_loc4`='我恨冒险者。', `FemaleText_loc5`='我恨透冒險者。', `FemaleText_loc7`='Odio a los aventureros.' WHERE `ID`=56322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싫어... 너희 전부 다...', `FemaleText_loc4`='我恨……你们所有人……', `FemaleText_loc5`='我恨...你們每一個人...', `FemaleText_loc7`='Los odio... a todos ustedes…' WHERE `ID`=56323;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 다 싫어!', `FemaleText_loc4`='我恨你们所有人！', `FemaleText_loc5`='我恨你們所有人!', `FemaleText_loc7`='¡Los odio a todos!' WHERE `ID`=56324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가만히 서 있기 싫어!', `FemaleText_loc4`='我恨站着不动。', `FemaleText_loc5`='我恨站著不動。', `FemaleText_loc7`='Odio quedarme quieta.' WHERE `ID`=56325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 증오를 느껴라!', `FemaleText_loc4`='感受我的仇恨！', `FemaleText_loc5`='感受我的恨!', `FemaleText_loc7`='¡Sientan mi odio!' WHERE `ID`=56326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 증오가 불탄다!', `FemaleText_loc4`='我的仇恨在燃烧！', `FemaleText_loc5`='我的恨在燃燒!', `FemaleText_loc7`='¡Mi odio arde!' WHERE `ID`=56327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 증오가 너흴 삼키리라!', `FemaleText_loc4`='我的仇恨会吞噬你！', `FemaleText_loc5`='我的恨會吞噬你們!', `FemaleText_loc7`='¡Mi odio los consumirá!' WHERE `ID`=56328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 방어구가 싫어.', `FemaleText_loc4`='我恨护甲。', `FemaleText_loc5`='我恨盔甲。', `FemaleText_loc7`='Odio las armaduras.' WHERE `ID`=56329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 수호자가 싫어.', `FemaleText_loc4`='我恨肉盾。', `FemaleText_loc5`='我恨烈士。', `FemaleText_loc7`='Odio a los mártires.' WHERE `ID`=56330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 이곳이 싫어. 날 가둬둔 자들은 오래전에 죽었지만, 분풀이나 해야겠다. 너희 같은 망할 보물 사냥꾼들에게 말이야.', `FemaleText_loc4`='我恨死这个地方了。也许关押我的人早就死了，但别以为我会放过你们这些卑鄙的财宝猎人。', `FemaleText_loc5`='我恨透這個地方了。抓住我的人早就死了，但我不介意把氣出在你們這些該死的寶藏獵人身上。', `FemaleText_loc7`='Cómo ODIO este lugar. Puede que mis captores lleven tiempo muertos, pero lo pagaré con ustedes, miserables cazatesoros.' WHERE `ID`=56331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노래하는 웅덩이에 자라는 갈대는 이 땅에서 가장 단단하지만, 내 강한 이마 앞에서는 공기나 마찬가지요.', `MaleText_loc4`='咏之池的芦苇是这里最硬的东西，但要是碰到我坚实的额头，也不过是浮云。', `MaleText_loc5`='頌唱之池的蘆葦是這片土地上最硬的，但對我的鐵頭來說就跟空氣一樣。', `MaleText_loc7`='Los juncos de las Pozas Cantarinas son los más duros de todas estas tierras, pero son como aire ante mi frente.' WHERE `ID`=56333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이들이 이런 내 말을 시험하려 들었지만, 나는 항상 증명해 보였다오.', `MaleText_loc4`='试者连连，屡试不爽。', `MaleText_loc5`='很多東西被用來檢驗我的宣言。但最終都證明了我的能力。', `MaleText_loc7`='Muchos han desafiado mis palabras, y siguen demostrando ser ciertas.' WHERE `ID`=56334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에 아무도 없습니까?', `MaleText_loc4`='外面有人吗？', `MaleText_loc5`='有人在嗎?', `MaleText_loc7`='¿Hay alguien ahí fuera?' WHERE `ID`=56335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오!', `MaleText_loc4`='救命啊！', `MaleText_loc5`='幫幫忙!', `MaleText_loc7`='¡Socorro!' WHERE `ID`=56336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 좀 도와주시겠습니까?', `MaleText_loc4`='有人能帮忙吗？', `MaleText_loc5`='誰來幫幫忙?', `MaleText_loc7`='¿Alguien puede ayudarme?' WHERE `ID`=56337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 너무 어두워!', `MaleText_loc4`='这里好黑啊！', `MaleText_loc5`='這裡好黑!', `MaleText_loc7`='¡Está muy oscuro aquí dentro!' WHERE `ID`=56338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 여기서 저 좀 꺼내주십시오!', `MaleText_loc4`='来人啊，救我出去！', `MaleText_loc5`='誰來放我出去!', `MaleText_loc7`='¡Que alguien me saque de aquí!' WHERE `ID`=56339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주십시오오오!', `MaleText_loc4`='救救救命！', `MaleText_loc5`='幫幫忙!!!', `MaleText_loc7`='¡Socorrooo!' WHERE `ID`=56340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 통에서 좀 꺼내주십시오!', `MaleText_loc4`='把我从桶里弄出去！', `MaleText_loc5`='把我弄出這個桶子!', `MaleText_loc7`='¡Sacadme de este barril!' WHERE `ID`=56341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 말 아무도 안 들립니까?', `MaleText_loc4`='有人听见我说话吗？', `MaleText_loc5`='有人能聽到我嗎?', `MaleText_loc7`='¿Alguien me oye?' WHERE `ID`=56342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 장인들이 만드는 나무판자는 최고급이라오. 아무리 심한 폭풍에도 끄떡하지 않지. 하지만 내 폭풍 같은 머리통 앞에서는 물이나 마찬가지요.', `MaleText_loc4`='我们的工人制造出了最好的木板。它们能经受最恐怖的风暴考验。但在我碎颅风暴的侵袭下，它们就像流水一样软弱。', `MaleText_loc5`='我們的工匠製造了最好的木板。它們有能力撐過最兇猛的風暴，但在我強勁的鐵頭風暴面前就像爛泥一灘。', `MaleText_loc7`='Nuestros artesanos fabrican las mejores tablas de madera. Resisten hasta la más brutal de las tormentas. Pero son como agua ante la tempestad de mi cráneo.' WHERE `ID`=56343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌의 손으로 만든 것은 내 힘을 당할 수가 없다오.', `MaleText_loc4`='熊猫人双手创造出的一切都抵挡不了我的额头。', `MaleText_loc5`='熊貓人造出的任何東西都無法抵擋我。', `MaleText_loc7`='Nada que hayan fabricado unas manos pandaren podrá contra mí.' WHERE `ID`=56344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모스랄루스를 처치했다! $p 님 만세!', `MaleText_loc4`='魔丝勒斯被打败了！$p万岁！', `MaleText_loc5`='摩沙拉被擊敗了!為$p歡呼!', `MaleText_loc7`='¡Has derrotado a Alevón! ¡Hurra por $p!' WHERE `ID`=56345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수를 처치했다! 만세!', `MaleText_loc4`='那个怪物被打败了！万岁！', `MaleText_loc5`='那野獸被擊敗了!喔耶!', `MaleText_loc7`='¡La bestia ha sido derrotada! ¡Hurra!' WHERE `ID`=56346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢！', `MaleText_loc5`='謝啦!', `MaleText_loc7`='¡Gracias!' WHERE `ID`=56347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 좀 마셔야겠습니다.', `MaleText_loc4`='我想喝杯啤酒。', `MaleText_loc5`='我需要來杯啤酒。', `MaleText_loc7`='Necesito una cerveza.' WHERE `ID`=56348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안에 얼마나 갇혀 있었는지 모르실 겁니다.', `MaleText_loc4`='你都不知道我在里面呆了多久。', `MaleText_loc5`='你不知道我在這裡待了多久。', `MaleText_loc7`='No te haces una idea del tiempo que he estado ahí dentro.' WHERE `ID`=56349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 빛 때문에... 눈이 아프군요.', `MaleText_loc4`='啊！这光……它闪到我们的眼睛了……', `MaleText_loc5`='呃啊!光...刺痛我的眼睛...', `MaleText_loc7`='¡Ay! La luz... nos hace daño a los ojos...' WHERE `ID`=56350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈이 다시 돌아오기 전에 여기를 벗어나는 게 좋을 겁니다!', `MaleText_loc4`='在他回来之前，我们最好离开这儿！', `MaleText_loc5`='最好在他回來之前離開這裡!', `MaleText_loc7`='¡Será mejor salir de aquí antes de que vuelva!' WHERE `ID`=56351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어!', `MaleText_loc4`='终于！', `MaleText_loc5`='終於!', `MaleText_loc7`='¡Por fin!' WHERE `ID`=56352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 정말 친절... 아 이런, 놈이 또 옵니다!', `MaleText_loc4`='谢谢你，好心的……噢，不，他又来了！', `MaleText_loc5`='謝謝你，好心的...喔天啊，他又來了!', `MaleText_loc7`='Gracias, amable... ¡OH NO, AQUÍ VIENE OTRA VEZ!' WHERE `ID`=56353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통에 영원히 갇히는 것보다 더 고통스러운 운명이 있을까 싶군요.', `MaleText_loc4`='我想被永远困在啤酒桶里还不算最糟糕的下场。', `MaleText_loc5`='我想永遠困在啤酒桶裡還不是最可怕的命運。', `MaleText_loc7`='Supongo que habrá peores destinos que estar encerrado para siempre dentro de un barril de cerveza.' WHERE `ID`=56354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 셴진 수에서 가장 단단한 돌이지만, 내 무지막지한 머리통 앞에서는 아무것도 아니라오.', `MaleText_loc4`='这是神真子背上最硬的石头，但在我坚硬的头颅面前，它们不值一提。', `MaleText_loc5`='這些是神真子身上最堅硬的石頭，但面對我的鐵頭都不堪一擊。', `MaleText_loc7`='Estas son las piedras más consistentes de todo Shen-zin Su, mas nada pueden ante mi poderosa cabeza.' WHERE `ID`=56355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 내 힘을 의심하는 자는 멍청한 자요.', `MaleText_loc4`='任何胆敢质疑我力量的人，都是蠢货。', `MaleText_loc5`='質疑我力量的人都是蠢材。', `MaleText_loc7`='Los que aún duden de mi fuerza son unos necios.' WHERE `ID`=56356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랐지!', `MaleText_loc4`='惊喜！', `MaleText_loc5`='嚇你一跳!', `MaleText_loc7`='¡Sorpresa!' WHERE `ID`=56357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 제가 저 비단 보호막을 파괴해보겠습니다.', `MaleText_loc4`='谢谢你！我会设法弄破一部分丝盾的。', `MaleText_loc5`='謝謝你!我會試著把那種絲之盾弄破一些。', `MaleText_loc7`='¡Gracias! Intentaré cortar un poco de ese escudo de seda.' WHERE `ID`=56358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 끈적끈적하군요! 당신이 공격할 수 있도록 저 나방을 끌어내려 보겠습니다.', `MaleText_loc4`='好粘啊！我会帮你把那只飞蛾弄下来。', `MaleText_loc5`='好黏啊!我會試著為你把那隻蛾弄下來。', `MaleText_loc7`='¡Qué pegajoso! Intentaré derrotar a esa polilla por ti.' WHERE `ID`=56359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 감사합니다!', `MaleText_loc4`='谢谢你，陌生人！', `MaleText_loc5`='謝謝你，陌生人!', `MaleText_loc7`='¡Gracias, $gforastero:forastera;!' WHERE `ID`=56360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='답은 하나요. 부숴 버려야지! 모두가 대번에 내 무지막지한 머리통의 힘을 알게 될 거요.', `MaleText_loc4`='现在我只要做一件事，那就是砸碎它！这下，所有人都会彻底看清我额头的强大力量。', `MaleText_loc5`='現在該做的只有一件事:我必須打爛它!從今以後，所有人都會了解我的鐵頭有多麼強力!', `MaleText_loc7`='Solo podemos hacer una cosa. ¡Tengo que aplastarlo! Por fin todos conocerán el poder de mi frente.' WHERE `ID`=56361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 내 머리... 너무 아파! 난... 이 기둥에는 엄청난 힘이 깃들어 있는 게 분명하오... 내 이마보다 더 강한 힘이...', `MaleText_loc4`='噢……我的头……好痛啊！我……这根柱子肯定蕴藏着巨大的力量……也许比我的额头还要厉害……', `MaleText_loc5`='喔...我的腦袋瓜...好痛!我...這柱子一定蘊含了無與倫比的力量，甚至有可能超越我的額頭...', `MaleText_loc7`='Oh... mi cabeza... ¡Me duele tanto! El pilar debe contener un poder enorme; un poder más enorme que el de mi frente...' WHERE `ID`=56362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 정말 놀라운걸! 대단한 장인의 솜씨요.', `MaleText_loc4`='这真是太精美了！我从未见过如此精良的工艺。', `MaleText_loc5`='這太棒了!我從沒看過這麼好的工藝。', `MaleText_loc7`='¡Qué maravilla! Nunca había visto un trabajo de artesanía tan refinado.' WHERE `ID`=56363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나... 나는 잠시 누워 있어야겠소... 이 두통이 사라질 때까지.', `MaleText_loc4`='我……我得躺一会儿了……直到头疼好一点为止。', `MaleText_loc5`='我...我得躺下來休息一下...讓這個頭痛消失一會兒。', `MaleText_loc7`='Me... voy a tumbar un momento... hasta que se me pase este dolor de cabeza.' WHERE `ID`=56364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고라스의 아귀 속으로 흡수됩니다.', `MaleText_loc4`='%s被吸入了苟拉斯之口', `MaleText_loc5`='%s被吸入了苟拉斯之顎', `MaleText_loc7`='¡Las Fauces de Go''rath absorben a %s!', `FemaleText_loc1`='%s|1이;가; 고라스의 아귀 속으로 흡수됩니다.', `FemaleText_loc4`='%s被吸入了苟拉斯之口', `FemaleText_loc5`='%s被吸入了苟拉斯之顎', `FemaleText_loc7`='¡Las Fauces de Go''rath absorben a %s!' WHERE `ID`=56365;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 우리 방어선을 뚫었습니다... 대지마저도 데스윙의 이름 아래 우리에게 등을 돌리는군요.', `FemaleText_loc4`='他们突破了我们的防御……连大地都以死亡之翼的名义背叛了我们。', `FemaleText_loc5`='他們突破我們的防禦了...大地以死亡之翼之名與我們為敵。', `FemaleText_loc7`='Han roto nuestras defensas... La tierra se vuelve contra nosotros en nombre de Alamuerte.' WHERE `ID`=56366;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알리자발이 $n|1을;를; 바닥에 꽂아버립니다.', `FemaleText_loc4`='阿丽萨巴尔将$n困在了地上。', `FemaleText_loc5`='阿利札巴把$n釘在地上!', `FemaleText_loc7`='Alizabal ensartó a $n en el suelo.' WHERE `ID`=56367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반대편에서 보세.', `MaleText_loc4`='我们在另一边见，$n。', `MaleText_loc5`='在另一頭見啦，$n。', `MaleText_loc7`='Nos vemos al otro lado.' WHERE `ID`=56368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그, 리 리. 나를 따르게!', `MaleText_loc4`='泥盏、丽丽……跟我走！', `MaleText_loc5`='泥杯、莉莉...跟著我!', `MaleText_loc7`='¡Caolín, Li Li... síganme!' WHERE `ID`=56369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리, 머드머그! 기다리게!', `MaleText_loc4`='丽丽，泥盏，等等！', `MaleText_loc5`='莉莉、泥杯，等等我!', `MaleText_loc7`='¡Li Li, Caolín, esperen!' WHERE `ID`=56370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리, 기다려라!', `MaleText_loc4`='丽丽，等等！', `MaleText_loc5`='莉莉，等等!', `MaleText_loc7`='¡Li Li, espera!' WHERE `ID`=56371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그를 따라가야겠군...', `MaleText_loc4`='我最好跟上泥盏……', `MaleText_loc5`='我最好趕上泥杯。', `MaleText_loc7`='Será mejor que siga a Caolín...' WHERE `ID`=56372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 먼저 가서 도와줄 게 없는지 봐야겠어요.', `FemaleText_loc4`='我先走了，看有什么要帮忙的。', `FemaleText_loc5`='我要去看看有沒有我可以幫忙的地方。', `FemaleText_loc7`='Voy a adelantarme para ver si puedo ayudar en algo.' WHERE `ID`=56373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삼촌! 머드머그! 우리 경주해요!', `FemaleText_loc4`='陈叔，泥盏！看我们谁先到那儿！', `FemaleText_loc5`='老陳叔叔、泥杯!來比誰先到!', `FemaleText_loc7`='¡Tío Chen, Caolín! ¡Juguemos una carrera hasta allí!' WHERE `ID`=56374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 나쁜 아저씨들! 날 놓고 가다니!', `FemaleText_loc4`='嘿，老怪物们！你们等等我！', `FemaleText_loc5`='嘿，你們這些老壞蛋!竟然把我留在這裡!', `FemaleText_loc7`='¡Ey, vejetes! ¡Me dejaron atrás!' WHERE `ID`=56375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으휴, 나쁜 삼촌! 날 놓고 갔어!', `FemaleText_loc4`='嘿，你个呆老头！等等我！', `FemaleText_loc5`='嘿，笨蛋老叔叔!你竟然把我留在這裡!', `FemaleText_loc7`='¡Ey, tío tonto! ¡Me dejaste atrás!' WHERE `ID`=56376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기서 봐요, 삼촌!', `FemaleText_loc4`='回头见咯，陈叔！', `FemaleText_loc5`='到那邊見囉，老陳叔叔!', `FemaleText_loc7`='¡Nos vemos allí, tío Chen!' WHERE `ID`=56377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 너머에 양조장으로 가는 다른 입구가 있습니다.', `MaleText_loc4`='酒厂还有一个入口，就在那边。', `MaleText_loc5`='釀酒廠有第二個入口，就在那邊。', `MaleText_loc7`='La cervecería tiene una segunda entrada, por allí.' WHERE `ID`=56378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기에서 다시 만납시다.', `MaleText_loc4`='我会到那儿跟你们会合。', `MaleText_loc5`='我想我們就在那邊碰面吧。', `MaleText_loc7`='Supongo que los veré allí.' WHERE `ID`=56379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘이 어디로 간 겁니까? 저를 떼 놓고 간 건가요? 아무도 신경 안 쓰는 겁니까?', `MaleText_loc4`='那两个家伙呢？他们不会丢下我了吧？就没人关心泥盏吗？', `MaleText_loc5`='其他兩個人跑哪去了?他們把我丟下來了嗎?就沒有人在意泥杯嗎?', `MaleText_loc7`='¿Adónde fueron esos dos? ¿Me abandonaron? ¿Nadie se preocupa por Caolín?' WHERE `ID`=56380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 저는 이만. 리 리, 너도 갈 거니?', `MaleText_loc4`='我想我还是走吧。你来吗，丽丽？', `MaleText_loc5`='看來我該走了。妳來嗎，莉莉?', `MaleText_loc7`='Bueno, entonces me voy. ¿Vienes, Li Li?' WHERE `ID`=56381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 저는 이만. 첸 님도 가실 겁니까?', `MaleText_loc4`='我想我还是走吧。你来吗，陈？', `MaleText_loc5`='看來我該走了。你來嗎，老陳?', `MaleText_loc7`='Bueno, entonces me voy. ¿Vienes, Chen?' WHERE `ID`=56382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자... 여기서 은둔 고수가 사는 곳 아는 사람?', `FemaleText_loc4`='那……你们知道那位隐居的大师在哪儿吗？', `FemaleText_loc5`='所以，沒人知道隱居的宗師在哪裡嗎?', `FemaleText_loc7`='Esto... ¿alguien sabe dónde vive el maestro oculto?' WHERE `ID`=56383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 모르니까 은둔 고수라고 불리는 게 아닐까 싶은데, 린.', `MaleText_loc4`='我很确信那就是他叫隐秘大师的原因，林。', `MaleText_loc5`='林，我很確定那就是他被稱為隱居宗師的原因。', `MaleText_loc7`='No, y estoy seguro de que por eso lo llaman el maestro oculto, Lin.' WHERE `ID`=56384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 맞네.', `FemaleText_loc4`='哦，真遗憾。', `FemaleText_loc5`='喔。抱歉。', `FemaleText_loc7`='Ah. Lo siento.' WHERE `ID`=56385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 그럼 어디부터 찾아볼까?', `FemaleText_loc4`='那么，我们从哪儿开始找？', `FemaleText_loc5`='那，我們該從哪開始找?', `FemaleText_loc7`='Bueno, ¿dónde buscamos primero?' WHERE `ID`=56386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개울에게 길을 물어볼 수도 있어...', `MaleText_loc4`='我可以试着向溪流寻求指引…', `MaleText_loc5`='我可以試著向溪流尋求指引...', `MaleText_loc7`='¿Y si pido consejo a las corrientes?' WHERE `ID`=56387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개울에 물어본다고? 애쉬요, 너는 장로는커녕 아직 어른도 아니잖아. 시간 낭비일 거야.', `MaleText_loc4`='向河流发问？阿西约你又不是长老。你还没有成年。这是在浪费你的时间。', `MaleText_loc5`='向水流請示?艾須歐，你不是長者，甚至不算個成年的錦魚人。這樣只是在浪費時間。', `MaleText_loc7`='¿A las corrientes? No eres un ancestro, Ashyo. Ni siquiera eres todavía un jinyu adulto. Perderías el tiempo.' WHERE `ID`=56388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨 생각인데, 갈라지자. 네 바람을 따라가보자.', `MaleText_loc4`='肯肯觉得我们应该分开走。跟着风儿。', `MaleText_loc5`='肯·肯覺得我們該分散。跟著四風走。', `MaleText_loc7`='Ken-Ken piensa mejor dividirse. Seguir los kuatro vientos.' WHERE `ID`=56389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 생각이야, 컨컨. 내가 남쪽으로 가지. 밀림 속으로 말이야.', `MaleText_loc4`='这个想法要好的多，肯肯。我可以向南出发，深入丛林。', `MaleText_loc5`='這主意不錯，肯肯。我自願往南，到叢林裡去。', `MaleText_loc7`='Esa idea es mucho mejor, Ken-Ken. Yo me ofrezco para viajar al sur y adentrarme en la jungla.' WHERE `ID`=56390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 북풍을 따라갈게.', `MaleText_loc4`='我追随北风的指引。', `MaleText_loc5`='我會追隨北風的方向。', `MaleText_loc7`='Yo seguiré el viento del norte.' WHERE `ID`=56391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨은 동풍을 따라간다. 가장 가까우니.', `MaleText_loc4`='肯肯去追东风。路程最短。', `MaleText_loc5`='肯·肯會跟著東風，走起來最近。', `MaleText_loc7`='Ken-Ken persigue el viento del este. Kaminata más korta.' WHERE `ID`=56392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼... 내가 서쪽으로 가야겠네.', `FemaleText_loc4`='我……我想我就去西面吧。', `FemaleText_loc5`='那...那我往西走。', `FemaleText_loc7`='Eh... entonces yo iré al oeste, supongo.' WHERE `ID`=56393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 난 여기서 나이도 가장 많고 몸무게도 제일 많이 나가니까, 너희가 돌아올 때까지 기다려 주지.', `MaleText_loc4`='很好。作为我们之中最胖最年长的人，我会在这里等待大家安全归来。', `MaleText_loc5`='很好，作為我們之中最老也最胖的，我留在這裡等待你們回來。', `MaleText_loc7`='Muy bien. Como soy el más viejo y el más gordo, esperaré aquí a que vayan regresando.' WHERE `ID`=56394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빈다, 친구들아. 은둔 고수를 찾아내면 훈련을 계속할 수 있을 거야.', `MaleText_loc4`='祝你们好运，朋友们。一旦找到隐秘大师，我们就可以继续训练了。', `MaleText_loc5`='祝好運，朋友們。一旦找到隱居的宗師，我們就能繼續訓練。', `MaleText_loc7`='Buena suerte, amigos. Una vez que encontremos al maestro oculto, podremos seguir con nuestro entrenamiento.' WHERE `ID`=56395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테스트 서버에 있는 불의 땅에 특별한 이벤트가 마련되어 있습니다.', `MaleText_loc4`='由于特殊原因，测试服上火焰之地已经关闭。', `MaleText_loc5`='測試伺服器的火源之界已保留給某一特殊事件。', `MaleText_loc7`='Las Tierras de Fuego del reino de pruebas han sido reservadas para un evento especial.' WHERE `ID`=56396;
