UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이곳 불에 땅에 있는 우두머리들 근처로 당신을 순간이동켜드릴 수 있습니다.', `MaleText_loc4`='我可以把你传送到火焰之地的任何一个首领附近。', `MaleText_loc5`='我可以把你傳送到火源之界的任何一位首領附近。', `MaleText_loc7`='Puedo teletransportarte cerca de cualquier jefe de los encuentros de las Tierras de Fuego.' WHERE `ID`=56404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 땅을 파괴하는 경쟁이 시작되었습니다!', `MaleText_loc4`='征服火焰之地的比赛开始了！', `MaleText_loc5`='擊敗火源之界的競賽開始了!', `MaleText_loc7`='¡La carrera para acabar con las Tierras de Fuego ha comenzado!' WHERE `ID`=56405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구! 필요하다면 내 수레를 써도 좋소. 수레를 타면 다이로 농장으로 갈 수 있소.', `MaleText_loc4`='你好啊，朋友！欢迎你乘坐我的牛车。它可以送你去大箩农场。', `MaleText_loc5`='幸會啊朋友!想要的話，歡迎你使用我的車。它會把你送到戴洛農莊。', `MaleText_loc7`='¡Hola, $gamigo:amiga;! Puedes usar mi carreta si quieres. Te llevará hasta la Granja de Dai-Lo.' WHERE `ID`=56406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네! 이 맥주를 담그는 데 자네 도움이 필요하네.', `MaleText_loc4`='很好，$n。我需要你帮忙酿制这种啤酒。', `MaleText_loc5`='好了，$n。我需要你的幫忙來釀造這啤酒。', `MaleText_loc7`='Muy bien. Voy a necesitar tu ayuda para elaborar esta cerveza.' WHERE `ID`=56407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 재료 이름을 외치면, 솥에다 던져 넣게나.', `MaleText_loc4`='在我喊出配料名字的时候，你就把它们扔进锅中……', `MaleText_loc5`='當我喊出原料的名字，你就把它們丟到鍋子裡去...', `MaleText_loc7`='Cuando grite los nombres de los ingredientes, tú los arrojas a la olla...' WHERE `ID`=56408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농담일세!', `MaleText_loc4`='我开玩笑的！', `MaleText_loc5`='開玩笑的啦!', `MaleText_loc7`='¡Es una broma!' WHERE `ID`=56409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 모든 대륙을 통틀어 최고의 양조사지! 여기서부터는 내가 맡겠네.', `MaleText_loc4`='我可是三个大陆最棒的酿酒师！这部分我自己能搞定。', `MaleText_loc5`='我是三塊大陸中最厲害的釀酒師!我可以自己搞定這個部分的。', `MaleText_loc7`='Soy el mejor cervecero en tres continentes. Creo que puedo ocuparme de esta parte.' WHERE `ID`=56410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연히 그러셔야죠!', `MaleText_loc4`='啊哈哈！你一定能做到的！', `MaleText_loc5`='你當然可以搞定!', `MaleText_loc7`='¡Pues claro que puedes!' WHERE `ID`=56411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 기다려야 할 텐데... 시간이 오래 걸릴 걸세.', `MaleText_loc4`='如果你不介意，$n……可能需要等上很长时间哦。', `MaleText_loc5`='你介意等一等嗎...這可能要很久的時間。', `MaleText_loc7`='Si no te importa esperar... puede que esto tarde un buen rato.' WHERE `ID`=56412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 오래 걸렸네!', `FemaleText_loc4`='真是花了很长时间！', `FemaleText_loc5`='真的是有夠久!', `FemaleText_loc7`='¡Sí que tardó un buen rato!' WHERE `ID`=56413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모스랄루스가 옵니다!', `MaleText_loc4`='魔丝勒斯来了！', `MaleText_loc5`='摩沙拉逼近!', `MaleText_loc7`='¡Alevón se acerca!', `FemaleText_loc1`='모스랄루스가 옵니다!', `FemaleText_loc4`='魔丝勒斯来了！', `FemaleText_loc5`='摩沙拉逼近!', `FemaleText_loc7`='¡Alevón se acerca!' WHERE `ID`=56414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구! 필요하다면 내 수레를 써도 좋소. 수레를 타면 다섯 새벽 사원으로 갈 수 있소.', `MaleText_loc4`='你好啊，朋友！欢迎你乘坐我的牛车。它可以送你去五晨寺。', `MaleText_loc5`='幸會啊朋友!想要的話，歡迎你使用我的車。它會把你送到五晨寺。', `MaleText_loc7`='¡Hola, $gamigo:amiga;! Puedes usar mi carreta si quieres. Te llevará hasta el Templo de los Cinco Albores.' WHERE `ID`=56415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내주는 포스터를 획득했습니다! 태연하게 손을 드세요!', `MaleText_loc4`='你刚刚赢得了一张酷炫海报！把手举起来，装成满不在乎的样子吧！', `MaleText_loc5`='你贏得了一張酷斃了的海報!快把你的手舉到空中，表現出一副不在乎的樣子!', `MaleText_loc7`='¡Acabas de ganar un póster que parte la pana! ¡Levanta la mano y flipa en colores!' WHERE `ID`=56416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 $c|1이여;여;, 지금은 수련을 하고 있어야 할 때 아닌가?$B$B몸과 마음을 수양하면 못 이룰 일이 없다네.', `MaleText_loc4`='你不是应该在训练吗，年轻的$c？$B$B只要好好修炼你的心志和躯体，就没有什么是你做不到的。', `MaleText_loc5`='你不是應該在接受訓練嗎，年輕的$c?$B$B整頓好你的心智和身體，世界上就沒有你辦不到的事。', `MaleText_loc7`='¿No deberías estar entrenando, joven $c?$b$bDisciplina tu cuerpo y tu mente, y conseguirás todo cuanto te propongas.' WHERE `ID`=56417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 램한테 걸래. 지난주 대련할 때 추를 꺾는 거 봤어?', `MaleText_loc4`='我押蓝获胜。你没看见他在上周的训练中，是怎么打倒楚的吗？', `MaleText_loc5`='我賭連姆贏。你沒看他在上週的訓練裡打倒了小楚嗎?', `MaleText_loc7`='He apostado por Lam. ¿Viste como derrotó a Chu en el entrenamiento de la semana pasada?' WHERE `ID`=56420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 네 착각이지. 조우는 떡갈나무처럼 튼튼하다고.', `MaleText_loc4`='你这就错了，朋友。周就如橡树一般坚韧不拔。', `MaleText_loc5`='那你就錯了，朋友。老周結實得像棵老橡樹。', `MaleText_loc7`='Ahí es donde te equivocas. Zhou está como un roble.' WHERE `ID`=56421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조우는 체력이 세 사람분이야. 웬만한 적은 상대가 안 된다고.', `MaleText_loc4`='周的耐力比得上三个普通人，所以他能打败大部分的对手。', `MaleText_loc5`='老周的耐力是普通人的三倍，所以他能比大部分的對手都持久。', `MaleText_loc7`='Zhou posee el aguante de tres hombres, por lo que resiste más que casi todos sus oponentes.' WHERE `ID`=56422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 봤자 램의 힘에 대면 아무것도 아니지.', `MaleText_loc4`='周的耐力在蓝的力量面前不值一提。', `MaleText_loc5`='他的耐力在連姆的力量面前完全沒用。', `MaleText_loc7`='Su resistencia no es nada comparada con la fuerza de Lam.' WHERE `ID`=56423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석은 다리가 황소 다리야! 대련할 때 걷어차인 적 있어?', `MaleText_loc4`='他的腿像牛一样有力！你在训练时被他踢到过吗？', `MaleText_loc5`='他的腿壯得跟條牛一樣!你有在訓練裡被他踢過嗎?', `MaleText_loc7`='¡Tiene las patas de un buey! ¿Alguna vez te ha dado una patada al entrenar?' WHERE `ID`=56424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조우한테 4 코퍼.', `MaleText_loc4`='我押周，四个铜板。', `MaleText_loc5`='四枚銅幣賭老周贏。', `MaleText_loc7`='Cuatro monedas de cobre para Zhou.' WHERE `ID`=56427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트 골드 한 통 더 걸지. 네가 질 게 분명해.', `MaleText_loc4`='我赌一桶风暴金酿。你输定了。', `MaleText_loc5`='為自己乾一桶金牌風暴烈酒吧。輸的人會是你。', `MaleText_loc7`='Subo la apuesta con un barril de cerveza de trueno añeja. Lo vas a perder.' WHERE `ID`=56428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비단 농사는 정말 위험한 일입니다.', `MaleText_loc4`='养蚕取丝真是一个危险的活儿。', `MaleText_loc5`='蠶絲生產是很危險的事業。', `MaleText_loc7`='La elaboración de la seda es un negocio peligroso.' WHERE `ID`=56429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠잡을 데 없는 자세야.', `MaleText_loc4`='你的招式真是无懈可击。', `MaleText_loc5`='你的招式無懈可擊。', `MaleText_loc7`='Tu estilo es impecable.', `FemaleText_loc1`='흠잡을 데 없는 자세로군요.', `FemaleText_loc4`='你的招式真是无懈可击。', `FemaleText_loc5`='你的招式無懈可擊。', `FemaleText_loc7`='Tu estilo es impecable.' WHERE `ID`=56430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신입치고는 대단한 실력인걸.', `MaleText_loc4`='对一个新手来说，拥有如此技巧实属难得。', `MaleText_loc5`='以新人來說真是技藝精湛。', `MaleText_loc7`='Qué habilidad para $gun nuevo:una nueva; aprendiz.', `FemaleText_loc1`='신입치고는 대단한 실력인걸요.', `FemaleText_loc4`='对一个新手来说，拥有如此技巧实属难得。', `FemaleText_loc5`='以新人來說真是技藝精湛。', `FemaleText_loc7`='Qué habilidad para $gun nuevo:una nueva; aprendiz.' WHERE `ID`=56431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 꼭 내게도 비결을 가르쳐 줘.', `MaleText_loc4`='以后你一定得把你的秘诀教给我。', `MaleText_loc5`='有一天你得教我你的秘訣。', `MaleText_loc7`='Algún día tendrás que enseñarme tus secretos.', `FemaleText_loc1`='언젠가 꼭 내게도 비결을 가르쳐 줘요.', `FemaleText_loc4`='以后你一定得把你的秘诀教给我。', `FemaleText_loc5`='有一天你得教我你的秘訣。', `FemaleText_loc7`='Algún día tendrás que enseñarme tus secretos.' WHERE `ID`=56432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련 기구 따위, 당신 상대가 안 되던걸.', `MaleText_loc4`='那个沙袋毫无还手之力。', `MaleText_loc5`='那傢伙一點機會都沒有。', `MaleText_loc7`='Ese objetivo no tenía ninguna posibilidad.', `FemaleText_loc1`='수련 기구 따위, 당신 상대가 안 되던걸요.', `FemaleText_loc4`='那个沙袋毫无还手之力。', `FemaleText_loc5`='那傢伙一點機會都沒有。', `FemaleText_loc7`='Ese objetivo no tenía ninguna posibilidad.' WHERE `ID`=56433;
