UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 인물이 되겠군요, 수련생.', `MaleText_loc4`='你注定要成就一番大事业，新人。', `MaleText_loc5`='你註定要完成偉大的事，受訓弟子。', `MaleText_loc7`='Llegarás muy alto, $galumno:alumna;.', `FemaleText_loc1`='큰 인물이 되겠군요, 수련생.', `FemaleText_loc4`='你注定要成就一番大事业，新人。', `FemaleText_loc5`='你註定要完成偉大的事，受訓弟子。', `FemaleText_loc7`='Llegarás muy alto, $galumno:alumna;.' WHERE `ID`=56435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신만큼 열심히 수련해야겠소.', `MaleText_loc4`='我得像你那么刻苦才行。', `MaleText_loc5`='我得和你一樣努力才行。', `MaleText_loc7`='Tengo que esforzarme tanto como tú.', `FemaleText_loc1`='당신만큼 열심히 수련해야겠어요.', `FemaleText_loc4`='我得像你那么刻苦才行。', `FemaleText_loc5`='我得和你一樣努力才行。', `FemaleText_loc7`='Tengo que esforzarme tanto como tú.' WHERE `ID`=56436;
