UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 훌륭한 대련 상대군요.', `MaleText_loc4`='你是一位可敬的对手。', `MaleText_loc5`='你是個可敬的對手。', `MaleText_loc7`='Es un honor ser tu oponente.', `FemaleText_loc1`='당신은 훌륭한 대련 상대군요.', `FemaleText_loc4`='你是一位可敬的对手。', `FemaleText_loc5`='你是個可敬的對手。', `FemaleText_loc7`='Es un honor ser tu oponente.' WHERE `ID`=56438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.', `MaleText_loc4`='多谢你的指点，我必须更加努力地修炼才行。', `MaleText_loc5`='謝謝你提醒了我應該更加勤奮地鍛鍊自己。', `MaleText_loc7`='Gracias por recordarme que tengo que entrenar con más diligencia.', `FemaleText_loc1`='고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.', `FemaleText_loc4`='多谢你的指点，我必须更加努力地修炼才行。', `FemaleText_loc5`='謝謝你提醒了我應該更加勤奮地鍛鍊自己。', `FemaleText_loc7`='Gracias por recordarme que tengo que entrenar con más diligencia.' WHERE `ID`=56439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예롭게 싸우는군요, 친구.', `MaleText_loc4`='你赢得光明正大，朋友。', `MaleText_loc5`='你贏得正大光明，朋友。', `MaleText_loc7`='Has luchado con honor.', `FemaleText_loc1`='명예롭게 싸우는군요, 친구.', `FemaleText_loc4`='你赢得光明正大，朋友。', `FemaleText_loc5`='你贏得正大光明，朋友。', `FemaleText_loc7`='Has luchado con honor.' WHERE `ID`=56440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.', `MaleText_loc4`='我打不过你。我认输了。', `MaleText_loc5`='我不是你的對手，我認輸。', `MaleText_loc7`='Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.', `FemaleText_loc1`='당신 실력에 미치려면 아직 멀었네요. 패배를 인정할게요.', `FemaleText_loc4`='我打不过你。我认输了。', `FemaleText_loc5`='我不是你的對手，我認輸。', `FemaleText_loc7`='Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.' WHERE `ID`=56441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력이 대단하오. 졌소.', `MaleText_loc4`='你太厉害了。我认输。', `MaleText_loc5`='你的技巧太好了，我投降。', `MaleText_loc7`='Tus habilidades me superan. Me rindo.', `FemaleText_loc1`='실력이 대단하군요. 졌어요.', `FemaleText_loc4`='你太厉害了。我认输。', `FemaleText_loc5`='你的技巧太好了，我投降。', `FemaleText_loc7`='Tus habilidades me superan. Me rindo.' WHERE `ID`=56442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.', `MaleText_loc4`='你很会战斗。我以后一定得好好向你学习。', `MaleText_loc5`='你打得太好了，未來我一定要多跟你學習。', `MaleText_loc7`='Has combatido bien. Debo aprender más de ti en el futuro.', `FemaleText_loc1`='잘 싸우시더군요. 나중에 또 한 수 가르쳐 주세요.', `FemaleText_loc4`='你很会战斗。我以后一定得好好向你学习。', `FemaleText_loc5`='你打得太好了，未來我一定要多跟你學習。', `FemaleText_loc7`='Has combatido bien. Debo aprender más de ti en el futuro.' WHERE `ID`=56443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 싸움이었소. 고맙소.', `MaleText_loc4`='真是场痛快的战斗。谢谢你。', `MaleText_loc5`='這是場精采的比試。多謝指教。', `MaleText_loc7`='Buena pelea. Gracias.', `FemaleText_loc1`='좋은 싸움이었어요. 고마워요.', `FemaleText_loc4`='真是场痛快的战斗。谢谢你。', `FemaleText_loc5`='這是場精采的比試。多謝指教。', `FemaleText_loc7`='Buena pelea. Gracias.' WHERE `ID`=56444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.', `MaleText_loc4`='我从没见过像你这么厉害的学徒。我得告诉其他人去。', `MaleText_loc5`='我從沒見過擁有你這種技巧的受訓弟子。我得跟其他人講。', `MaleText_loc7`='Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', `FemaleText_loc1`='당신만큼 출중한 수련생은 처음 봐요. 다른 이들에게도 이야기해야겠어요.', `FemaleText_loc4`='我从没见过像你这么厉害的学徒。我得告诉其他人去。', `FemaleText_loc5`='我從沒見過擁有你這種技巧的受訓弟子。我得跟其他人講。', `FemaleText_loc7`='Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.' WHERE `ID`=56445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='< 임시 : 검은 왕자 래시온이 이미 빠져나온 알을 발견합니다! >', `MaleText_loc4`='< PLACEHOLDER：你发现黑龙蛋已经孵化成了黑龙王子拉希奥！>', `MaleText_loc5`='< PLACEHOLDER : You discover that the egg has hatched into Black Prince Wrathion! >', `MaleText_loc7`='< PLACEHOLDER : You discover that the egg has hatched into Black Prince Wrathion! >' WHERE `ID`=56446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 알다시피, 검은용은 종종 인간으로 변장하곤 하지. 필멸자들의 일에 개입하려고 말이다.', `MaleText_loc4`='如你所知，我们黑龙经常会假扮成形色各异的人，去插手凡人的事务。', `MaleText_loc5`='如你所知，黑龍經常化為人形，藉此插手凡人的事務。', `MaleText_loc7`='Como sabes, los dragones Negros suelen adoptar forma humana para manipular los asuntos de los mortales.' WHERE `ID`=56447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광기에 찬 내 아버지의 군대가 점점 약해지자, 남아 있던 몇 안 되는 검은용은 종적을 감췄다.', `MaleText_loc4`='当我发疯的父亲众叛亲离时，那些残存的黑龙四散奔逃，并藏了起来。', `MaleText_loc5`='當我那瘋狂的父親敗亡的時候，剩下的那些黑龍全都躲了起來。', `MaleText_loc7`='Mientras la casa de mi demente padre se derrumba, los pocos dragones negros que quedan se han escondido.' WHERE `ID`=56448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 난 아직 그들을 느낄 수 있어. 비겁한 내 형제 자매들이 이대로 어둠 속에 숨어 있으면 끔찍한 일이 생기고 말 것이다.', `MaleText_loc4`='但是，我还是能感觉到他们。如果任由他们藏在阴影里，我那些懦弱的兄弟姐妹们指不定会掀起怎样的波澜。', `MaleText_loc5`='但是我還能感覺到他們。如果讓我那些膽小的兄弟姊妹們繼續躲在暗處，他們會造成更多的苦難。', `MaleText_loc7`='Pero aún los percibo. Mis cobardes hermanos y hermanas causarán un sufrimiento inefable si los dejamos en las sombras.' WHERE `ID`=56449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가, 그들은 내게 위협이 되지.', `MaleText_loc4`='他们也是对我的威胁。', `MaleText_loc5`='不僅如此，他們對我來說是個威脅。', `MaleText_loc7`='Además, representan una amenaza para mí.' WHERE `ID`=56450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 네가 필요한 것이다. 그들을 다 없애는 걸 도와주면 후하게 보상해 주마.', `MaleText_loc4`='这就是你的任务了。帮我们去杀掉他们，然后我会好好回报你。', `MaleText_loc5`='這就是要你出場的原因。幫我殺光他們，我就會好好的獎賞你。', `MaleText_loc7`='Ahí es donde intervienes tú. Ayúdanos a matarlos y te recompensaré generosamente.' WHERE `ID`=56451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 혼자서는 물리치지 못했을 거요. 실례지만, 이제 수레를 찾으러 가야겠소.', `MaleText_loc4`='我实在没法独自击退那么多敌人。现在，如果你不介意的话，我得去找我的车了。', `MaleText_loc5`='我自個兒一定沒辦法擊退他們的。好吧，我該去找我的推車了，先告退。', `MaleText_loc7`='Yo solo no me habría podido librar de ellos. Ahora, si me disculpas, tengo que ir a buscar mi carreta.' WHERE `ID`=56452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수레야!', `MaleText_loc4`='我的车！', `MaleText_loc5`='我的推車!', `MaleText_loc7`='¡Mi carreta!' WHERE `ID`=56453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 수레야. 아직도 뒤집혀 있구나.', `MaleText_loc4`='你好啊，老伙计。还底朝天躺在这儿呢？', `MaleText_loc5`='你好啊，推車。看你還是老樣子在這屁股朝天嘛。', `MaleText_loc7`='Ay, mi carreta. Está hecha un desastre.' WHERE `ID`=56454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자 따위가 내 임무를 막을 순 없다.', `MaleText_loc4`='没有凡人能阻碍我的使命。', `MaleText_loc5`='沒有凡人能干擾我工作。', `MaleText_loc7`='Ningún mortal me desviará de mi propósito.' WHERE `ID`=56455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계란으로 바위를 치려 드는군. 내가 널 묻어주마.', `MaleText_loc4`='你妄想阻止雪崩。我只会埋葬你。', `MaleText_loc5`='你想要阻止山崩。我會埋葬你。', `MaleText_loc7`='Pretenden detener una avalancha. Los sepultaré.' WHERE `ID`=56456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 나와 싸우겠다고? 대지가 갈라져 널 삼키고 뭉개버릴 거다.', `MaleText_loc4`='你们以为对手只有我？碎裂的大地会摧垮你。', `MaleText_loc5`='你想要獨自挑戰我?大地會裂開來吞噬和碾碎你。', `MaleText_loc7`='¿Pensabas luchar a solas? La tierra se fractura para tragarte y aplastarte.' WHERE `ID`=56457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가. 말도 안 돼. 탑을... 꼭 무너뜨려야... 하는데...', `MaleText_loc4`='不可能。这不可能。这座塔……必须毁掉……', `MaleText_loc5`='不可能。怎麼會這樣。要...打下...塔...', `MaleText_loc7`='Imposible. No puede ser. La torre... debe... caer...' WHERE `ID`=56458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 막을 순 없다.', `MaleText_loc4`='我不可阻挡。', `MaleText_loc5`='我勢不可擋。', `MaleText_loc7`='Soy imparable.' WHERE `ID`=56459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연한 결과다.', `MaleText_loc4`='这是必然的结局。', `MaleText_loc5`='這無可避免。', `MaleText_loc7`='Era inevitable.' WHERE `ID`=56460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼지가 되어라.', `MaleText_loc4`='大地归于尘土。', `MaleText_loc5`='回歸塵土。', `MaleText_loc7`='Reducido a polvo.' WHERE `ID`=56461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌이 부른다...', `MaleText_loc4`='石头在呼唤……', `MaleText_loc5`='岩石在呼喚...', `MaleText_loc7`='La piedra llama...' WHERE `ID`=56462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅이 요동친다...', `MaleText_loc4`='大地在震颤……', `MaleText_loc5`='地面在動搖...', `MaleText_loc7`='La tierra se estremece...' WHERE `ID`=56463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하! 정말 형편없이 압도당했군!', `MaleText_loc4`='啊哈哈！你们输定了！', `MaleText_loc5`='哈哈!你們寡不敵眾!', `MaleText_loc7`='¡Ja, ja, ja! ¡Os superamos con creces!' WHERE `ID`=56464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위가 떨린다...', `MaleText_loc4`='岩石在战抖……', `MaleText_loc5`='石頭在顫抖...', `MaleText_loc7`='Las rocas tiemblan...' WHERE `ID`=56465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥이 전율한다...', `MaleText_loc4`='地面在动荡……', `MaleText_loc5`='陸地在震動...', `MaleText_loc7`='La superficie se agita...' WHERE `ID`=56466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...대지의 검은 피가 널 삼키리라.', `MaleText_loc4`='……大地的黑血会吞噬你。', `MaleText_loc5`='...而大地的黑色血將吞噬你。', `MaleText_loc7`='...y la sangre negra de la tierra los consume.' WHERE `ID`=56467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...그 누구도 고대 신에게서 벗어날 순 없으리라.', `MaleText_loc4`='……没人能从上古之神的手中逃脱。', `MaleText_loc5`='...絕對無法逃離上古之神。', `MaleText_loc7`='...y es imposible escapar de los dioses antiguos.' WHERE `ID`=56468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...진정한 신의 분노가 뒤따르리라.', `MaleText_loc4`='……真神之怒接踵而来。', `MaleText_loc5`='...真神的憤怒隨之而來。', `MaleText_loc7`='... y la ira de los verdaderos dioses se aproxima.' WHERE `ID`=56469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...주인님의 증오가 너희를 덮치리라.', `MaleText_loc4`='……主人的仇恨将吞没你。', `MaleText_loc5`='...你將淹沒在主人的憤恨裡。', `MaleText_loc7`='...y se ahogan en el odio del Maestro.' WHERE `ID`=56470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뛰어 봤자 벼룩인 것을.', `MaleText_loc4`='逃向死亡。', `MaleText_loc5`='逃吧，死吧。', `MaleText_loc7`='Huyan y mueran.' WHERE `ID`=56471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐 봤자 죽은 목숨이다.', `MaleText_loc4`='奔向灭亡。', `MaleText_loc5`='逃亡，滅亡。', `MaleText_loc7`='Corran y perezcan.' WHERE `ID`=56472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해! 녀석의 친구가 오고 있어!', `MaleText_loc4`='小心！它的同伴过来了！', `MaleText_loc5`='小心!牠的朋友們來了!', `MaleText_loc7`='¡Mira! ¡Vienen sus amigüitos!' WHERE `ID`=56473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치자!', `MaleText_loc4`='快跑！', `MaleText_loc5`='快跑!', `MaleText_loc7`='¡Huyan!' WHERE `ID`=56474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이들. 약해 빠진 것들. 내려와서 싸워라. 내가 직접 끌어 내리기 전에.', `MaleText_loc4`='懦夫。弱者。下来与我一战，否则我就“送”你们下来。', `MaleText_loc5`='懦夫。廢物。下來戰鬥，不然我要抓你們下來了。', `MaleText_loc7`='Cobardes. Débiles. Vengan y luchen o acabaré con ustedes.' WHERE `ID`=56475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사원에 영원히 숨을 순 없다, 주술사여.', `MaleText_loc4`='你不可能永远躲在这座神殿里，萨满。', `MaleText_loc5`='你無法永遠躲在這座神殿中，薩滿。', `MaleText_loc7`='No te puedes esconder para siempre en este templo, chamán.' WHERE `ID`=56476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 탑을 돌 무더기로 만들어서, 온 벌판에 흩뿌리겠다.', `MaleText_loc4`='我会夷平这座塔，将它的碎片抛洒在荒原上。', `MaleText_loc5`='我會把這座塔拆成碎片，灑在荒野中。', `MaleText_loc7`='Reduciré esta torre a cenizas y las esparciré por los baldíos.' WHERE `ID`=56477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고룡쉼터는 무너질 것이다. 모두 먼지가 될 것이다.', `MaleText_loc4`='神殿必将倒塌。万物归于尘土。', `MaleText_loc5`='龍眠神殿會毀滅。一切化成灰。', `MaleText_loc7`='El Reposo del Dragón caerá. Solo quedarán cenizas.' WHERE `ID`=56478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 목표물은 여기, 길니아스의 폐허에 있다. 이미 유능한 요원 몇 명을 놈에게 잃었지. 넌 다를지 두고 보자.', `MaleText_loc4`='你的第一个目标，就在吉尔尼斯废墟。我之前派去的人都失败了，看看你能不能走运点。', `MaleText_loc5`='你的第一個目標在這，吉爾尼斯的廢墟裡。我已經損失了一些精銳，看看你的表現會不會好一點。', `MaleText_loc7`='Tu primer objetivo está aquí, en las Ruinas de Gilneas. Ya he perdido a algunos de mis mejores hombres: veamos si te va mejor a ti.' WHERE `ID`=56479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 길니아스 전체를 집어삼키면, 다음엔 어디로 숨어들지 아무도 모를 일이다. 지금 쳐야 한다.', `MaleText_loc4`='如果他成功洗劫了吉尔尼斯，没人能知道他以后的行踪。现在就是进攻的时机。', `MaleText_loc5`='等他把吉爾尼斯搜刮一空，很難猜到他接下來會躲去哪。我們該出手了。', `MaleText_loc7`='Si consigue saquear toda Gilneas, no sabremos dónde se esconderá a continuación. Es el momento de atacar.' WHERE `ID`=56480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 찾는 그 용은... 크리드라고 불린다.', `MaleText_loc4`='你要找的那条龙名为“信条”。', `MaleText_loc5`='你要找的龍，名字是「希拉姆」。', `MaleText_loc7`='El dragón que buscas responde al nombre de "Credo".' WHERE `ID`=56481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈은 병에 걸린 인간들을 속여, 자기가 그들의 땅을 되찾아줄 수 있다고 믿게 만들었지. 그리고 용의 정수로 인간들의 피를 오염시켰다.', `MaleText_loc4`='他蛊惑了一群染病的人类，让他们自以为可以夺回失去的土地。他用他的龙族精华污染了那些人的血。', `MaleText_loc5`='他哄騙了一群染病的人類，使他們相信可以奪回領土。他用自己的龍之精華毒化了他們的血。', `MaleText_loc7`='Ha hecho pensar a un grupo de humanos enfermizos que pueden recuperar su tierra. Les ha envenenado la sangre con su propia esencia dracónica.' WHERE `ID`=56482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술통을 빠짐없이 되찾지 못하면 수련생들이 실망할 거요. 하지만 아주 엉망진창이 되었는걸...', `MaleText_loc4`='如果我不能把这些桶运回去，学徒们会很失望的。真是糟透了……', `MaleText_loc5`='如果我不替他們把這些酒桶全都帶回去，受訓弟子們會很失望的。真是一團糟...', `MaleText_loc7`='Los aprendices estarán bastante decepcionados si no recupero todos los barriles. Qué desastre...' WHERE `ID`=56483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 강해졌군, 제자여. 좋은 일일세. 곧 그 힘이 필요할 테니.', `MaleText_loc4`='你的确变强了，孩子。这很好。这力量很快就会有用武之地。', `MaleText_loc5`='你確實變強了，孩子。這樣很好，你很快就會需要這股力量。', `MaleText_loc7`='Te has vuelto realmente fuerte. Me alegro mucho, porque pronto necesitarás esa fuerza.' WHERE `ID`=56484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 왔네. 내가 채비를 하는 동안 몇 가지 일 좀 도와주게.', `MaleText_loc4`='我们到了。如果你愿意，可以在我做准备时帮我几个小忙。', `MaleText_loc5`='我們到了。在我做準備時有幾項小工作要麻煩你。', `MaleText_loc7`='Ya hemos llegado. ¿Te importaría ayudarme con unas tareas mientras me preparo?' WHERE `ID`=56485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[동영상 예정] 아이사가 배를 향해 달려가지만, 그 순간 지가 폭발을 피해 달려 나오는 모습을 본다.', `MaleText_loc4`='[Pending Cinematic] Aysa rushes towards the ship, only to find Ji running out to escape the coming explosion.', `MaleText_loc5`='[動畫待確認]艾莎衝向船，卻只看到紀正往船外跑，逃離即將到來的爆炸。', `MaleText_loc7`='[Pending Cinematic] Aysa rushes towards the ship, only to find Ji running out to escape the coming explosion.' WHERE `ID`=56486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[동영상 예정] 지가 아이사를 보호하려고 뒤에서 붙잡는다. 아이사는 셴진 수가 돌이킬 수 없이 다칠까 봐 몸부림을 치며 비명을 지른다. 지가 상의도 하지 않고 그렇게 무모한 짓을 한 데 화가 나 있다.', `MaleText_loc4`='[Pending Cinematic] Ji holds Aysa back, not wanting her to get hurt.  She struggles and yells, fearful that Shen-zin Su will be irreparably healed, and angry that Ji would do something so rash without consulting her.', `MaleText_loc5`='[動畫待確認]紀擁著艾莎往後跑，以免她受爆炸傷害。她掙扎著喊叫，惟恐神真子受到無法治癒的傷害，並憤怒於紀沒有詢問她便做出如此倉促的決定。', `MaleText_loc7`='[Pending Cinematic] Ji holds Aysa back, not wanting her to get hurt.  She struggles and yells, fearful that Shen-zin Su will be irreparably healed, and angry that Ji would do something so rash without consulting her.' WHERE `ID`=56487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[동영상 예정] 배가 멋있게 폭발한다. 지와 아이사는 폭발에 휘말려 땅에 내팽개쳐지지만, 크게 다치지 않는다.', `MaleText_loc4`='[Pending Cinematic] The ship explodes GLORIOUSLY.  Ji and Aysa are sent flying to the ground farther away, but are largely unhurt.', `MaleText_loc5`='[動畫待確認]船劇烈地炸開了。紀和艾莎被爆風吹飛到遠處的地面，但並沒有受傷。', `MaleText_loc7`='[Pending Cinematic] The ship explodes GLORIOUSLY.  Ji and Aysa are sent flying to the ground farther away, but are largely unhurt.' WHERE `ID`=56488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[동영상 예정] 둘 다 일어서서 배가 있었던 곳에 난 구멍을 돌아본다. 셴진 수의 상처에서 피가 강처럼 흘러나온다.', `MaleText_loc4`='[Pending Cinematic] Both rise to look back at the hole where the ship had been.  A river of blood pours from the wound in Shen-zin Su.', `MaleText_loc5`='[動畫待確認]兩人站起身來看著原本插著船骸的空洞。一條血河從神真子的身上噴發出來。', `MaleText_loc7`='[Pending Cinematic] Both rise to look back at the hole where the ship had been.  A river of blood pours from the wound in Shen-zin Su.' WHERE `ID`=56489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 다른 암살자 12명이 바로 그러다가 목숨을 잃었답니다.', `MaleText_loc4`='小心啊！我们之前的那12个刺客就是这么挂掉的。', `MaleText_loc5`='小心!我們那12個刺客就是這樣被殺的。', `MaleText_loc7`='¡Cuidado! Así murieron los otros 12 asesinos.' WHERE `ID`=56490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보셨죠? 저기 있는 놈들은 완전 짐승이라니까요!', `MaleText_loc4`='你看到了吧？那些家伙都是些凶残的野兽！', `MaleText_loc5`='看到沒?他們在那裡頭可狂野得很!', `MaleText_loc7`='¿Lo ves? Allí hay animales salvajes.' WHERE `ID`=56491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 자조가 구해드렸습니다! 다시 해봅시다...', `MaleText_loc4`='扎佐来救你了！再试一次……', `MaleText_loc5`='薩索來了!繼續努力...', `MaleText_loc7`='¡Zazzo al rescate! Sigue intentándolo...' WHERE `ID`=56492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 괜찮아요, $n 님. 제가 구해냈습니다... 이번엔요.', `MaleText_loc4`='没事了，$n。这次……我总算救下了你。', `MaleText_loc5`='沒關係，$n。因為這回...我有你。', `MaleText_loc7`='Está bien, $n. Te tengo... esta vez.' WHERE `ID`=56493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 좀 보고 다니세요! 도시 구석구석에 적이 있다고요...', `MaleText_loc4`='注意你脚下的路！城里到处都是他们的人……', `MaleText_loc5`='提高警覺!他們在那城裡到處都是...', `MaleText_loc7`='¡Mira por dónde vas! ¡Están por cada esquina de la ciudad...' WHERE `ID`=56494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 무슨 잠입입니까?', `MaleText_loc4`='你管那叫潜行？', `MaleText_loc5`='這是哪門子的潛行?', `MaleText_loc7`='¿A eso le llamas escabullirse?' WHERE `ID`=56495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스 시에 그냥 날아서 들어갈 순 없습니다!', `MaleText_loc4`='谁都别想就这么飞进吉尔尼斯城！', `MaleText_loc5`='沒有人可以就這麼「飛」進吉爾尼斯城!', `MaleText_loc7`='¡No se entra volando así como así en Gilneas!' WHERE `ID`=56496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워워워... 지붕에 저격수가 쫙 깔렸다고요. 걸어서 가셔야 합니다!', `MaleText_loc4`='哇哇哇——他们在所有的房顶上都安插了狙击手。你得靠双脚走进去！', `MaleText_loc5`='哇，屋頂上到處都是狙擊手!你得自己徒步進去了!', `MaleText_loc7`='¡Hala! Tienen francotiradores en todos los tejados. Vas a tener que ir a pie.' WHERE `ID`=56497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기엔 날아들어가면 안 됩니다. 걸리고 만다고요. 그 방법은 우리가 이미 시도해봤을 거란 생각은 안 드세요?', `MaleText_loc4`='你不能就这么飞进去——肯定会被发现的。你以为我们没有试过吗？', `MaleText_loc5`='你不能就那樣飛進去，一定會被發現的!你以為我們沒試過嗎?', `MaleText_loc7`='No puedes volar allí, te verán, te lo aseguro. ¿Crees que no lo hemos intentado ya?' WHERE `ID`=56498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이다! 암살자가 있다!', `MaleText_loc4`='在这里——一个刺客！', `MaleText_loc5`='在這裡 - 有刺客!', `MaleText_loc7`='¡Por aquí! ¡Un asesino!', `FemaleText_loc1`='모습을 보여라!', `FemaleText_loc4`='滚出来！', `FemaleText_loc5`='現身吧!', `FemaleText_loc7`='¡Muéstrate!' WHERE `ID`=56499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!', `MaleText_loc4`='入侵者！', `MaleText_loc5`='入侵者!', `MaleText_loc7`='¡Intruso!', `FemaleText_loc1`='크리드 경을 보호하라!', `FemaleText_loc4`='保护信条大人！', `FemaleText_loc5`='保護悉拉姆領主!', `FemaleText_loc7`='¡Protejan a Lord Creed!' WHERE `ID`=56500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 잡아라!', `MaleText_loc4`='抓住$g他:她;！', `MaleText_loc5`='逮住$g他:她;!', `MaleText_loc7`='¡$gCogedlo:Cogedla;!', `FemaleText_loc1`='놈을 쓰러뜨려라!', `FemaleText_loc4`='把$g他:她;揪出来！', `FemaleText_loc5`='逮住$g他:她;!', `FemaleText_loc7`='¡$gCogedlo:Cogedla;!' WHERE `ID`=56501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구신가?', `MaleText_loc4`='看看是谁来了？', `MaleText_loc5`='看看是誰來啦?', `MaleText_loc7`='¿Qué tenemos aquí?', `FemaleText_loc1`='네가 보인다...', `FemaleText_loc4`='我看见你了……', `FemaleText_loc5`='我看到你了...', `FemaleText_loc7`='Te veo...' WHERE `ID`=56502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈을 없애라!', `MaleText_loc4`='干掉$g他:她;！', `MaleText_loc5`='消滅$g他:她;!', `MaleText_loc7`='¡$gDestrúyanlo:Destrúyanla;!' WHERE `ID`=56503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도둑 냄새가 나는데!', `MaleText_loc4`='我闻到你的气味了，小偷！', `MaleText_loc5`='我聞到你了，小偷!', `MaleText_loc7`='¡Puedo olerte, ladrón!' WHERE `ID`=56504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 암살자야!', `MaleText_loc4`='去死吧，刺客！', `MaleText_loc5`='去死吧，刺客!', `MaleText_loc7`='¡Muere, asesino!' WHERE `ID`=56505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모스랄루스가 날아오릅니다. 나방전사들을 고치에서 꺼내 모스랄루스를 끌어내리게 하십시오.', `MaleText_loc4`='魔丝勒斯飞起来了，将灭蛾战士从丝茧中解救出来，让他们把她打下来。', `MaleText_loc5`='摩沙拉起飛了，把殺蛾鬥士從繭裡放出來，這樣他們才能把摩沙拉抓下來。', `MaleText_loc7`='Alevón se está elevando; libera a los luchadores de polillas de los capullos para que la eliminen.', `FemaleText_loc1`='모스랄루스가 날아오릅니다. 나방전사들을 고치에서 꺼내 모스랄루스를 끌어내리게 하십시오.', `FemaleText_loc4`='魔丝勒斯飞起来了，将灭蛾战士从丝茧中解救出来，让他们把她打下来。', `FemaleText_loc5`='摩沙拉起飛了，把殺蛾鬥士從繭裡放出來，這樣他們才能把摩沙拉抓下來。', `FemaleText_loc7`='Alevón se está elevando; libera a los luchadores de polillas de los capullos para que la eliminen.' WHERE `ID`=56506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모스랄루스가 떨어졌습니다. 공격하십시오!', `MaleText_loc4`='魔丝勒斯下来了。攻击！', `MaleText_loc5`='摩沙拉下降了，攻擊!', `MaleText_loc7`='Alevón ha caído. ¡Ataca!', `FemaleText_loc1`='모스랄루스가 떨어졌습니다. 공격하십시오!', `FemaleText_loc4`='魔丝勒斯下来了。攻击！', `FemaleText_loc5`='摩沙拉下降了，攻擊!', `FemaleText_loc7`='Alevón ha caído. ¡Ataca!' WHERE `ID`=56507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 땅을 되찾을 것이다.', `MaleText_loc4`='我们将重塑这个世界。', `MaleText_loc5`='我們會奪回這個世界。', `MaleText_loc7`='Conquistaremos el mundo una vez más.' WHERE `ID`=56508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 실패한다!', `MaleText_loc4`='你必将失败！', `MaleText_loc5`='你將會失敗!', `MaleText_loc7`='Fracasarán.' WHERE `ID`=56509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 가장 큰 약점은, 나약한 마음이다.', `MaleText_loc4`='脆弱的心灵是你们最大的弱点。', `MaleText_loc5`='你們脆弱的心靈是最大的致命傷。', `MaleText_loc7`='Sus frágiles mentes son su mayor debilidad.' WHERE `ID`=56510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 세계는 어둠 속에서 끝날 것이다!', `MaleText_loc4`='你们的世界将陷入黑暗！', `MaleText_loc5`='你們的世界會在黑暗中滅亡!', `MaleText_loc7`='¡Su mundo se sumirá en la oscuridad!' WHERE `ID`=56511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니... 안 돼...', `MaleText_loc4`='不……这不可能……', `MaleText_loc5`='不，不可能...', `MaleText_loc7`='No... No puede ser...' WHERE `ID`=56512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 돌아올 것이다...', `MaleText_loc4`='我会回来的……', `MaleText_loc5`='我會回來的...', `MaleText_loc7`='Volveré...' WHERE `ID`=56513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 우리를 파괴할 수 없어...', `MaleText_loc4`='你无法消灭我们……', `MaleText_loc5`='你們無法消滅我們...', `MaleText_loc7`='No pueden destruirnos…' WHERE `ID`=56514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 막을 수 있다고 생각하지 마라...', `MaleText_loc4`='你休想阻止我们……', `MaleText_loc5`='你們不可能阻止我們...', `MaleText_loc7`='Jamás podrán detenernos…' WHERE `ID`=56515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 눈부셔!', `MaleText_loc4`='好刺眼的光芒！', `MaleText_loc5`='光明使我睜不開眼!', `MaleText_loc7`='¡La luz me ciega!' WHERE `ID`=56516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 소리를... 견딜 수 없어!', `MaleText_loc4`='我受不了……这声音了！', `MaleText_loc5`='我無法忍受...這種聲音!', `MaleText_loc7`='¡No soporto... ese sonido!' WHERE `ID`=56517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 무슨 짓을 한 거냐?', `MaleText_loc4`='你对我做了什么？', `MaleText_loc5`='你對我做了什麼?', `MaleText_loc7`='¿Qué me han hecho?' WHERE `ID`=56518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 빠져나간다!', `MaleText_loc4`='我的力量在流失！', `MaleText_loc5`='我的力量被抽走了!', `MaleText_loc7`='¡Mis poderes se desvanecen!' WHERE `ID`=56519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 암살자라! 누가 보냈지? 불어라. 안 그러면 네 시체에서 대답을 얻어내겠다!', `MaleText_loc4`='嗯，一个刺客？谁派你来的？快老实交代，不然我就把答案从你脑袋里挖出来！', `MaleText_loc5`='刺客?誰派你來的?說!別逼我動手從你腦袋把答案挖出來!', `MaleText_loc7`='¿Asesino, eh? ¿Quién te envía? ¡Habla o te sacaré las respuestas de tu propia calavera!' WHERE `ID`=56520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 도와주신 일도, 또 제가 망신당하지 않게 도와주신 일도 절대 잊지 않겠습니다. 감사합니다!', `MaleText_loc4`='我永远不会忘记您给予我们的帮助。是您让我们免遭屈辱，英雄。谢谢你！', `MaleText_loc5`='我永遠不會忘記你給我們的幫助，或你讓我們免於的羞辱，英雄。謝謝你!', `MaleText_loc7`='Nunca olvidaré la ayuda que nos prestaste ni la vergüenza que me evitaste, $ghéroe:heroína;. ¡Gracias!' WHERE `ID`=56521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 계속하십시오. 저희가 지켜드리겠습니다.', `MaleText_loc4`='你们可以继续仪式了，我们会保护你们的。', `MaleText_loc5`='你可以開始儀式了，我們會保護你。', `MaleText_loc7`='Continúa con el ritual, nosotros te defenderemos.', `FemaleText_loc1`='의식을 계속하십시오. 저희가 지켜드리겠습니다.', `FemaleText_loc4`='你们可以继续仪式了，我们会保护你们的。', `FemaleText_loc5`='你可以開始儀式了，我們會保護你。', `FemaleText_loc7`='Continúa con el ritual, nosotros te defenderemos.' WHERE `ID`=56522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 또다시 큰일을 맡기게 됐군. 우리가 영혼에 아제로스 위상의 힘을 불어넣는 동안, 자네들은 데스윙의 병력으로부터 우릴 보호해야 하네.', `MaleText_loc4`='英雄们，这个重担又落到你们的肩上了。我们会将守护巨龙的力量灌注到巨龙之魂中，在此期间，你们必须保护我们。', `MaleText_loc5`='英雄們，我們必須再次把這個重擔放在你們的雙肩上。你們必須在我們將艾澤拉斯守護巨龍的力量灌注到巨龍之魂時保護我們，不受死亡之翼爪牙的攻擊。', `MaleText_loc7`='Héroes, esta responsabilidad recae en ustedes una vez más. Deben protegernos de los ejércitos de Alamuerte mientras imbuimos el Alma con los poderes de los Aspectos.' WHERE `ID`=56523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 가장 오래되고 명성이 자자한 비단 농장 관광을 즐겨보십시오.', `MaleText_loc4`='祝你在潘达利亚最古老、最负盛名的丝绸农场过得开心。', `MaleText_loc5`='好好遊覽全潘達利亞最古老、最有名望的蠶絲農場吧。', `MaleText_loc7`='Disfruta de tu visita a la granja de seda más antigua y respetada de Pandaria.' WHERE `ID`=56524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누에가 고치를 만들면, 우리는 이 기계로 비단을 뽑아냅니다.', `MaleText_loc4`='在蚕作茧时，我们就用这件设备来抽取蚕丝。', `MaleText_loc5`='待蠶寶寶結繭後，我們用這個裝置取出蠶絲。', `MaleText_loc7`='Cuando el gusano de seda crea su capullo, utilizamos este aparato para extraer la seda.' WHERE `ID`=56525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누에 먹이로 가장 적절한 나뭇잎을 찾는 데에만 수 세대의 시간이 걸렸습니다.', `MaleText_loc4`='我们祖祖辈辈都致力于改良桑叶，希望能培育出最适合蚕虫的食物。', `MaleText_loc5`='我們花費好幾代的時間找出最完美的樹葉給蠶寶寶們吃。', `MaleText_loc7`='Se han necesitado generaciones para perfeccionar las hojas adecuadas para hacer comida de gusanos de seda.' WHERE `ID`=56526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 새로 태어난 누에 유충들이 고치를 만들 때까지 먹이를 주고 있습니다.', `MaleText_loc4`='我们在这里饲养新生的幼蚕，直到它们能够吐丝作茧。', `MaleText_loc5`='我們在這裡餵食蠶寶寶的幼蟲，直到他們準備好結繭。', `MaleText_loc7`='Aquí alimentamos a las nuevas larvas de gusanos de seda hasta que están preparadas para elaborar sus capullos.' WHERE `ID`=56527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울트락시온과 싸울 수 있도록 고룡쉼터 사원 정상으로 데려가 주십시오.', `MaleText_loc4`='我要挑战奥卓克希昂，送我去龙眠神殿顶层。', `MaleText_loc5`='帶我到龍眠神殿之頂，與奧特拉賽恩作戰。', `MaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Ultraxion.', `FemaleText_loc1`='울트락시온과 싸울 수 있도록 고룡쉼터 사원 정상으로 데려가 주세요.', `FemaleText_loc4`='我要挑战奥卓克希昂，送我去龙眠神殿顶层。', `FemaleText_loc5`='帶我到龍眠神殿之頂，與奧特拉賽恩作戰。', `FemaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Ultraxion.' WHERE `ID`=56528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요! 크리드의 암흑 마법이 제 시야를 방해하고 있습니다... 여기서부턴 혼자 알아서 하셔야 해요. 행운을 빌어요!', `MaleText_loc4`='你成功了！信条的黑暗魔法干扰了我的视线——从现在起，你就得靠自己了。祝你好运！', `MaleText_loc5`='你辦到了!悉拉姆的邪惡魔法讓我無法看清，接下來就只能靠你自己了。祝你好運!', `MaleText_loc7`='¡Lo conseguiste! La magia oscura de Creed está interfiriendo en mi visión, a partir de aquí depende solo de ti. ¡Buena suerte!' WHERE `ID`=56529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈다! 우리의 힘이 용의 영혼 안에서 꿈틀댄다! 이제 우리 운명은 너희 손에 달렸다, 대지의 수호자여!', `FemaleText_loc4`='完成了！我们的力量灌注到了巨龙之魂里！我们的命运就交给你了，大地守护者！', `FemaleText_loc5`='完成了!我們的力量都灌注到巨龍之魂裡了!我們的命運就交給你了，大地守護者!', `FemaleText_loc7`='¡Se acabó! ¡Ahora nuestro poder reside en el Alma de dragón! ¡Nuestro destino yace contigo, Guardián de la Tierra!' WHERE `ID`=56530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타레사... 케른... 아그라... 절대 실망시키지 않겠소. 절대 이 세상을 포기하지 않겠소!', `MaleText_loc4`='塔蕾莎……凯恩……阿格娜……我不会辜负你们。我不会辜负这个世界！', `MaleText_loc5`='塔蕾莎...凱恩...阿格拉...我不會讓你們失望。不會讓這個世界失望!', `MaleText_loc7`='Taretha... Cairne… Agara… No les fallaré. ¡No defraudaré al mundo!' WHERE `ID`=56531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 뭘 위해 매일 뼈 빠지게 일을 하는 거지?$B$B다 부질없어...', `MaleText_loc4`='我们夜以继日地辛苦劳作，究竟是为了什么？$B$B这一切都毫无意义……', `MaleText_loc5`='我們日夜不停地工作，都為了什麼?$B$B一點意義也沒有...', `MaleText_loc7`='Trabajamos muy duro día sí y día también, ¿y para qué?$B$BNo tiene ningún sentido...' WHERE `ID`=56532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음...? 뭐지?$B$B아, 또 깨어났구나.$B$B<깊은 한숨을 내쉬는 수니>$B$B저 비가 내리기 시작한 뒤로는 그냥 만사가 귀찮네요...', `MaleText_loc4`='哈？什么？$B$B噢，我又醒了。$B$B<孙妮发出一声长叹。>$B$B自从下起这场雨，我就什么都懒得做……', `MaleText_loc5`='呃?什麼?$B$B喔，我又醒了。$B$B<桑尼長長嘆了口氣。>$B$B自從這場雨開始，我就什麼事也不想做...', `MaleText_loc7`='¿Eh? ¿Qué?$B$BOh, vuelvo a estar despierta.$B$B<Sunni exhala un profundo suspiro.>$B$BDesde que empezó esta lluvia, es que no me apetece hacer nada...', `FemaleText_loc1`='음...? 뭐지?$B$B아, 또 깨어났구나.$B$B<깊은 한숨을 내쉬는 수니>$B$B저 비가 내리기 시작한 뒤로는 그냥 만사가 귀찮네요...', `FemaleText_loc4`='哈？什么？$B$B噢，我又醒了。$B$B<孙妮发出一声长叹。>$B$B自从下起这场雨，我就什么都懒得做……', `FemaleText_loc5`='呃?什麼?$B$B喔，我又醒了。$B$B<桑尼長長嘆了口氣。>$B$B自從這場雨開始，我就什麼事也不想做...', `FemaleText_loc7`='¿Eh? ¿Qué?$B$BOh, vuelvo a estar despierta.$B$B<Sunni exhala un profundo suspiro.>$B$BDesde que empezó esta lluvia, es que no me apetece hacer nada...' WHERE `ID`=56533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 변장도 이젠 지겹군. 그만 끝내자!', `MaleText_loc4`='我受够这些伪装了。让我们做个了断吧！', `MaleText_loc5`='我不想再偽裝了。現在就來做個了結吧!', `MaleText_loc7`='Me aburre este disfraz. ¡Acabemos con esto ahora!' WHERE `ID`=56534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 어떻게 된 건지 모르겠습니다. 마치 모두 정신이 나간 것 같아요!$B$B부디 도와주시겠습니까?', `MaleText_loc4`='我不知道这里究竟发生了什么事——似乎所有人都疯了！$B$B拜托了，你能帮帮忙吗？', `MaleText_loc5`='我不知道這裡發生了什麼事。好像所有人都瘋了一樣!$B$B拜託，你能幫忙嗎?', `MaleText_loc7`='No sé qué es lo que está pasando por aquí... ¡es como si todo el mundo se hubiera vuelto loco!$B$BPor favor, ¿podrías ayudarnos?', `FemaleText_loc1`='대체 어떻게 된 건지 모르겠습니다. 마치 모두 정신이 나간 것 같아요!$B$B부디 도와주시겠습니까?', `FemaleText_loc4`='我不知道这里究竟发生了什么事——似乎所有人都疯了！$B$B拜托了，你能帮帮忙吗？', `FemaleText_loc5`='我不知道這裡發生了什麼事。好像所有人都瘋了一樣!$B$B拜託，你能幫忙嗎?', `FemaleText_loc7`='No sé qué es lo que está pasando por aquí... ¡es como si todo el mundo se hubiera vuelto loco!$B$BPor favor, ¿podrías ayudarnos?' WHERE `ID`=56535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구의... 사주로... 이런 짓을...?', `MaleText_loc4`='这是……谁的……命令？', `MaleText_loc5`='是誰...下令的?', `MaleText_loc7`='¿Quién... ordenó... esto?' WHERE `ID`=56536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해내셨군요! 당신은 저의 영웅이에요, $n 님! 래시온 왕자님이 기뻐하실 겁니다.', `MaleText_loc4`='你成功了！你真是我的大英雄，$n！拉希奥王子一定会很高兴的。', `MaleText_loc5`='你辦到了!你真是我的英雄，$n!怒西昂王子一定會很高興。', `MaleText_loc7`='¡Lo conseguiste! ¡Eres increíble, $n! El príncipe Wrathion estará encantado.' WHERE `ID`=56537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그 용의 눈을 들여다봤어... 그리고 절망했지...', `MaleText_loc4`='在巨龙的眼中，我只看到了绝望……', `MaleText_loc5`='我看著巨龍的眼睛，感到了絕望...', `MaleText_loc7`='Miré a los ojos del dragón, y perdí la esperanza…' WHERE `ID`=56538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 함께하길.', `MaleText_loc4`='圣光，与你同在。', `MaleText_loc5`='聖光與你同在。', `MaleText_loc7`='Que la Luz esté con ustedes.' WHERE `ID`=56539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿음이 널 인도하길.', `MaleText_loc4`='让你的信仰，指引你。', `MaleText_loc5`='讓你的信仰指引你。', `MaleText_loc7`='Que la fe te guíe.' WHERE `ID`=56540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 진정한 힘을 봐라!', `MaleText_loc4`='见证我的力量！', `MaleText_loc5`='見證我的力量!', `MaleText_loc7`='¡Contempla mi PODER!' WHERE `ID`=56541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너를 삼키리라!', `MaleText_loc4`='圣光会吞噬你！', `MaleText_loc5`='聖光會吞噬你!', `MaleText_loc7`='¡La Luz los consumirá!' WHERE `ID`=56542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑 속에 잠겨라!', `MaleText_loc4`='被暗影淹没！', `MaleText_loc5`='被暗影吞沒吧!', `MaleText_loc7`='¡Ahóguense en la sombra!' WHERE `ID`=56543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너! 우린 네 시체 위에서 춤을 추리라! 이제, 죽어라!', `MaleText_loc4`='而你，你的灰烬将成为我们的盛宴！现在，受死吧！', `MaleText_loc5`='而你，我們會享用你的骨灰，現在，死吧!', `MaleText_loc7`='¡Y USTEDES! ¡Nos devoraremos sus cenizas! ¡Mueran!' WHERE `ID`=56544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t 울트락시온이 |cFF9900CC|Hspell:106371|h[황혼의 시간]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t奥卓克希昂开始施放|cFF9900CC|Hspell:106371|h[暮光审判]|h|r!', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_twilight.blp:20|t 奧特拉賽恩開始施放 |cFF9900CC|Hspell:106371|h[暮光之時]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_twilight.blp:20|t ¡Ultraxion comienza a lanzar |cFF9900CC|Hspell:106371|h[Hora del Crepúsculo]|h|r!' WHERE `ID`=56545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 초특급 대포로 재빨리 순간이동할 방법을 찾고 있지는 않았겠죠?$B$B왜냐하면 그건 바로 제가 하는 일이니까요!$B$B물론 돈을 좀 주시긴 해야죠...', `MaleText_loc4`='你好啊！我说，你该不会是在找返回大炮的传送门吧？$B$B我就可以帮你！$B$B当然了，只是要一小笔费用……', `MaleText_loc5`='嗨，你好!我說，你想不想快速傳送回大砲那裡呢?$B$B因為啊，我正巧可以幫你這個忙!$B$B當然啦，要酌收少許費用...', `MaleText_loc7`='¡Hola! Dime, ¿no estarás buscando un teletransporte rapidito para el gran cañón?$B$B¡Lo digo porque yo puedo ayudarte!$B$BPor un módico precio, claro...' WHERE `ID`=56546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내줬어요!$B$B물고기들이 겁을 좀 먹었겠지만요.$B$B초특급 대포로 다시 순간이동시켜드릴까요?$B$B물론 돈은 좀 든답니다...', `MaleText_loc4`='哇，准头不错嘛！$B$B就是把我的鱼吓跑了。$B$B你想快速传回大炮那里去吗？$B$B当然了，你得付一小笔费用……', `MaleText_loc5`='嘿，這一砲打得漂亮!$B$B把魚都嚇壞了。$B$B需要快速傳送回大砲那邊嗎?$B$B當然，得酌收一些費用...', `MaleText_loc7`='Hala, ¡buen tiro!$B$BCreo que has asustado al pez.$B$B¿Necesitas un teletransporte rapidito para volver al cañón?$B$BPor un módico precio, claro...' WHERE `ID`=56547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초특급 대포로 순간이동시켜주십시오.', `MaleText_loc4`='把我传送回大炮那里。', `MaleText_loc5`='把我傳送到大砲那裡。', `MaleText_loc7`='Teletranspórtame al cañón.', `FemaleText_loc1`='초특급 대포로 순간이동시켜주세요.', `FemaleText_loc4`='把我传送回大炮那里。', `FemaleText_loc5`='把我傳送到大砲那裡。', `FemaleText_loc7`='Teletranspórtame al cañón.' WHERE `ID`=56548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누군가가 침을 흘리며 바라보고 있다는 것을 느낍니다.', `MaleText_loc4`='你感到有饥饿的眼神在注视着你。', `MaleText_loc5`='你感覺到飢餓的視線盯著你。', `MaleText_loc7`='Sientes la presencia de unos ojos hambrientos que te observan.' WHERE `ID`=56549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥새는 정말 아름답지 않아요? 위풍당당하고 무시무시하지요.$B$B천둥새는 이 땅의 어떤 판다렌보다 가치 있는 존재예요.$B$B저는 여기서 기다릴 거예요. 천둥새들이 준비가 끝나는 대로 절 데려갈 테니까요.', `MaleText_loc4`='这些雷鸟不美吗？简直堪称壮丽。令人生畏。$B$B它们在这片土地上比我们任何人都要珍贵。$B$B我要在这里等着。等他们准备好，就会带我走了。', `MaleText_loc5`='雷鳥真美不是嗎?莊嚴，懾人。$B$B牠們比我們更配得上這片土地。$B$B我將在這裡等待。當牠們準備好時，牠們會把我帶走。', `MaleText_loc7`='¿No te parecen preciosos los pájaros de trueno? Majestuosos. Aterradores.$B$BMerecen esta tierra más que cualquiera de nosotros.$B$BLos esperaré aquí. Que me lleven cuando quieran.' WHERE `ID`=56550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 낭비예요.$B$B저는 한 발짝도 안 움직일 테니까요.', `MaleText_loc4`='别白费力气了。$B$B我哪儿都不去。', `MaleText_loc5`='你是在浪費你的時間。$B$B我哪裡也不去。', `MaleText_loc7`='Estás perdiendo el tiempo.$B$BNo pienso moverme de aquí.' WHERE `ID`=56551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이모우, 제발 돌아갑시다. 이모님께서 많이 걱정하십니다.', `MaleText_loc4`='拜托了，易默，你的阿姨很担心你。', `MaleText_loc5`='拜託，易謀。你嬸嬸擔心你都擔心出病來了。', `MaleText_loc7`='Por favor, Yi-Mo, tu tía está preocupadísima por ti.', `FemaleText_loc1`='이모우, 제발 돌아가요. 이모님께서 많이 걱정하세요.', `FemaleText_loc4`='拜托了，易默，你的阿姨很担心你。', `FemaleText_loc5`='拜託，易謀。你嬸嬸擔心你都擔心出病來了。', `FemaleText_loc7`='Por favor, Yi-Mo, tu tía está preocupadísima por ti.' WHERE `ID`=56552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 시간 없습니다. 어서 일어나지 않으면 제가 일어나게 해 주겠습니다.', `MaleText_loc4`='我没时间跟你废话。自己挪动屁股，别等我动手帮你。', `MaleText_loc5`='我沒空扯這些。挪動你的屁股，或者我幫你挪。', `MaleText_loc7`='No tengo tiempo para esto. O te mueves o te muevo.', `FemaleText_loc1`='이럴 시간 없어요. 어서 일어나지 않으면 제가 일어나게 해 주겠어요.', `FemaleText_loc4`='我没时间跟你废话。自己挪动屁股，别等我动手帮你。', `FemaleText_loc5`='我沒空扯這些。挪動你的屁股，或者我幫你挪。', `FemaleText_loc7`='No tengo tiempo para esto. O te mueves o te muevo.' WHERE `ID`=56553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하다, 친구여. 군대가 몰려가도 성공하기 어려운 일을, 숙련된 암살자 한 명이 해낼 수 있다는 걸 잘 보여줬군.', `MaleText_loc4`='干得好，朋友。你证明了自己是一名优秀的刺客。你的致命一击能成就一支大军所不能成就的伟业。', `MaleText_loc5`='做得好，朋友。你證明了一個熟練的刺客能做到一整支軍隊都做不到的致命一擊。', `MaleText_loc7`='Un trabajo excelente. Has demostrado que, donde fracasaría un ejército, un experto asesino puede asestar un golpe decisivo.' WHERE `ID`=56554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 우리와 일하고 싶나? 물건을 좀 구해줬으면 하는데...', `MaleText_loc4`='如果你想要继续为我们工作，我们还需要一些补给……', `MaleText_loc5`='你想繼續合作的話，我們還缺一些其他的物資...', `MaleText_loc7`='Si quieres continuar con nuestro trabajo, necesitaremos algunos suministros...' WHERE `ID`=56555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 운이 좋았던 겁니다. 적이 미숙했죠.', `MaleText_loc4`='哼！瞎猫碰到死耗子而已。', `MaleText_loc5`='哼!運氣好，加上對手毫無防備罷了。', `MaleText_loc7`='¡Bah! Un golpe de suerte contra un oponente desprevenido.' WHERE `ID`=56556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 잘될 겁니다.', `MaleText_loc4`='你的人生还长得很。', `MaleText_loc5`='你有一段大好人生等待著你。', `MaleText_loc7`='Tienes toda la vida por delante.', `FemaleText_loc1`='다 잘될 거예요.', `FemaleText_loc4`='你的人生还长得很。', `FemaleText_loc5`='你有一段大好人生等待著你。', `FemaleText_loc7`='Tienes toda la vida por delante.' WHERE `ID`=56557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이모님께서 저를 많이 걱정한다고요? 설마...', `MaleText_loc4`='她真的担心我吗？我很怀疑……', `MaleText_loc5`='她真的在擔心我嗎?我很懷疑...', `MaleText_loc7`='¿En serio está preocupada por mí? Lo dudo...' WHERE `ID`=56558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삶이 대체 뭔데요? 실망 뒤에 또 실망, 실망의 연속이에요.', `MaleText_loc4`='那什么是人生呢？失望之后还是失望，没完没了。', `MaleText_loc5`='說穿了，什麼是人生?不過是一連串的失望。', `MaleText_loc7`='¿Qué es la vida al fin y al cabo? Una serie de decepciones, una detrás de otra.' WHERE `ID`=56559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 슈마의 |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFFFF0404|Hspell:104897|h[붉은색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r를 소환합니다!', `MaleText_loc4`='%s召唤|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFFFF0404|Hspell:104897|h[红色]|h|r，|cFFFFA901|Hspell:104901|h[黄色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r舒玛之血！', `MaleText_loc5`='%s召喚了|cFF9932CD|Hspell:104896|h[紫色]|h|r、|cFFFF0404|Hspell:104897|h[紅色]|h|r、|cFFFFA901|Hspell:104901|h[黃色]|h|r，以及|cFF424242|Hspell:104894|h[黑色]|h|r的鬚瑪之血!', `MaleText_loc7`='¡%s invoca la Sangre de Shu''ma |cFF9932CD|Hspell:104896|h[morada]|h|r, |cFFFF0404|Hspell:104897|h[roja]|h|r, |cFFFFA901|Hspell:104901|h[amarilla]|h|r y |cFF424242|Hspell:104894|h[negra]|h|r!' WHERE `ID`=56560;
