UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 슈마의 |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFF088A08|Hspell:104898|h[초록색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r를 소환합니다!', `MaleText_loc4`='%s召唤|cFF0080FF|Hspell:104900|h[蓝色]|h|r，|cFF9932CD|Hspell:104896|h[紫色]|h|r，|cFF088A08|Hspell:104898|h[绿色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！', `MaleText_loc5`='%s召喚了|cFF0080FF|Hspell:104900|h[藍色]|h|r、|cFF9932CD|Hspell:104896|h[紫色]|h|r、|cFF088A08|Hspell:104898|h[綠色]|h|r，以及|cFFFFA901|Hspell:104901|h[黃色]|h|r鬚瑪之血!', `MaleText_loc7`='¡%s invoca la Sangre de Shu''ma |cFF0080FF|Hspell:104900|h[azul]|h|r, |cFF9932CD|Hspell:104896|h[morada]|h|r, |cFF088A08|Hspell:104898|h[verde]|h|r y |cFFFFA901|Hspell:104901|h[amarilla]|h|r!' WHERE `ID`=56564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 슈마의 |cFF0080FF|Hspell:104900|h[푸른색 피]|h|r, |cFF424242|Hspell:104894|h[검은색 피]|h|r, |cFF9932CD|Hspell:104896|h[보라색 피]|h|r, |cFFFFA901|Hspell:104901|h[노란색 피]|h|r를 소환합니다!', `MaleText_loc4`='%s召唤|cFF0080FF|Hspell:104900|h[蓝色]|h|r，|cFF424242|Hspell:104894|h[黑色]|h|r，|cFF9932CD|Hspell:104896|h[紫色]|h|r，以及|cFFFFA901|Hspell:104901|h[黄色]|h|r舒玛之血！', `MaleText_loc5`='%s召喚了|cFF0080FF|Hspell:104900|h[藍色]|h|r、|cFF424242|Hspell:104894|h[黑色]|h|r、|cFF9932CD|Hspell:104896|h[紫色]|h|r，以及|cFFFFA901|Hspell:104901|h[黃色]|h|r鬚瑪之血!', `MaleText_loc7`='¡%s invoca la Sangre de Shu''ma |cFF0080FF|Hspell:104900|h[azul]|h|r, |cFF424242|Hspell:104894|h[negra]|h|r, |cFF9932CD|Hspell:104896|h[morada]|h|r y |cFFFFA901|Hspell:104901|h[amarilla]|h|r !' WHERE `ID`=56565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 바로 여기, 카라잔 아래 동굴에 있다. 하하하하... 어떻게든 목숨을 부지하려고, 카라잔 아래 숨겨진 비전 마법을 연구하고 있지.', `MaleText_loc4`='我们找到了她，藏在卡拉赞地下的洞穴里。担惊受怕之余，她正在学习埋藏于地下的奥术秘密。', `MaleText_loc5`='我們剛找到她，躲在卡拉贊下面的山洞裡。她正在研究埋在地基下面的秘法典籍，想要保住自己的小命。', `MaleText_loc7`='La hemos localizado aquí, en las cavernas situadas bajo Karazhan. Temerosa por su vida, investiga los secretos arcanos enterrados bajo los cimientos.' WHERE `ID`=56566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 용을 숭배하는 미친 이교도들에게 주변을 지키게 했다. 정신 나간 놈들이지만 제대로 무장했지. 위험한 놈들이다.', `MaleText_loc4`='她由一群疯狂的巨龙教徒守卫着。那些教徒也许脑子不太正常，但却武装到了牙齿，极度危险。', `MaleText_loc5`='她被一群瘋狂的黑龍教徒所保護著。那群人也許腦子怪怪的，但是裝備精良而危險。', `MaleText_loc7`='Se ha rodeado de un pequeño ejército de cultores de dragones trastornados. Puede que no estén bien de la cabeza, pero están bien armados. Y son peligrosos.' WHERE `ID`=56567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 모은 보석으로 일전에 내가 준 무기를 강화할 수 있다. 하지만 다른 재료가 하나 필요해. 다음 목표물에게서 얻을 수 있지.', `MaleText_loc4`='你收集来的这些宝石能够强化我给你的武器，但我还需要一些别的材料。它们就在你的下一个对手身上。', `MaleText_loc5`='你收集的寶石可以強化我給你的武器，但是我需要另一種材料。你的下一個目標身上就有。', `MaleText_loc7`='Las gemas que has recogido aumentarán el poder de las armas que te he dado, pero nos falta otro ingrediente. Lo obtendremos de tu siguiente objetivo.' WHERE `ID`=56568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름은 날리스라고 한다. 최근까지만 해도 검은용군단의 대표로서 고룡쉼터 사원에 머물렀지. 지금은? 도망자 신세다.', `MaleText_loc4`='她的名字叫“纳莉丝”。不久之前她还作为黑龙军团的代表站在龙眠神殿里。现在？她逃走了。', `MaleText_loc5`='她的名字是「納麗絲」。不久前她還在龍眠神殿擔任黑龍軍團的代表。現在呢?她正在逃命。', `MaleText_loc7`='Se llama "Nalice". Y, hasta hace poco, se encontraba en el Templo del Reposo del Dragón como representante del Vuelo Negro. Ahora es una prófuga.' WHERE `ID`=56569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 돌아오길 바란다. 하지만 혹시 모르니 말해 두는데, 네가 일하는 걸 보는 건 즐거웠다. 너희 종족을 다시 보게 될 정도였지. 행운을 빈다.', `MaleText_loc4`='我希望能见到你活着完成这个任务。要是你挂了，至少我挺享受你为我们工作的过程。你是你们种族中的佼佼者。祝你好运。', `MaleText_loc5`='希望你能從這個任務活著回來。如果不能，我想說你的能力相當不錯，替你的種族增光不少。祝你好運。', `MaleText_loc7`='Espero que vuelvas con vida de esta misión. Pero si no es así, quiero que sepas que me ha gustado verte en acción. Eres un orgullo para los tuyos. Buena suerte.' WHERE `ID`=56570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지를 측량할 준비가 끝났습니다.', `MaleText_loc4`='准备调查这个地方。', `MaleText_loc5`='準備開始探索調查這地方。', `MaleText_loc7`='Inspeccionemos la tierra.', `FemaleText_loc1`='대지를 측량할 준비가 끝났어요.', `FemaleText_loc4`='准备调查这个地方。', `FemaleText_loc5`='準備開始探索調查這地方。', `FemaleText_loc7`='Inspeccionemos la tierra.' WHERE `ID`=56571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭력을 쓰고 싶진 않아요.', `FemaleText_loc4`='我讨厌使用暴力。', `FemaleText_loc5`='我討厭動用暴力。', `FemaleText_loc7`='Odio recurrir a la violencia.' WHERE `ID`=56572;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 누군진 몰라도 전 목숨 걸고 이 제단을 지킬 것입니다. 싸우기 싫다면 당장 떠나십시오.', `FemaleText_loc4`='我不知道你是谁，但我会用生命来保卫这座圣殿。在我动手之前离开吧。', `FemaleText_loc5`='我不認識你們，但是我會以生命守護這裡。快離開吧，我實在不想訴諸武力。', `FemaleText_loc7`='No sé quiénes son, pero defenderé este santuario con mi vida. Ahora márchense, antes de que desate mi furia.' WHERE `ID`=56573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아, 이제 알겠어요. 안녕, 행운을 빌어요.', `FemaleText_loc4`='我现在明白了。永别了，还有，祝你好运。', `FemaleText_loc5`='我終於懂了。再見，祝好運。', `FemaleText_loc7`='Ahora lo entiendo. Adiós y buena suerte.' WHERE `ID`=56574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선택의 여지가 없었어요.', `FemaleText_loc4`='是你逼我的。', `FemaleText_loc5`='是你們逼我的。', `FemaleText_loc7`='Me obligaste.' WHERE `ID`=56575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이러고 싶진 않았는데.', `FemaleText_loc4`='我不想这样的。', `FemaleText_loc5`='我不想這麼做。', `FemaleText_loc7`='No quería hacerlo.' WHERE `ID`=56576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항복했다면 좋았을 걸.', `FemaleText_loc4`='我以为你会投降的。', `FemaleText_loc5`='你能投降就好了。', `FemaleText_loc7`='Ojalá se hubieran rendido.' WHERE `ID`=56577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸로 머리나 식히시죠.', `FemaleText_loc4`='也许这个能冷静一下你的头脑……', `FemaleText_loc5`='也許這能讓你們冷靜點...', `FemaleText_loc7`='Quizás esto les aclare las ideas…' WHERE `ID`=56578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼음으로 가슴 속 불을 꺼드리죠.', `FemaleText_loc4`='这些冰块应该能熄灭你胸中的怒火……', `FemaleText_loc5`='一些冰應該能澆熄你們心中的火...', `FemaleText_loc7`='Algo de hielo sofocará el fuego de sus corazones…' WHERE `ID`=56579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어째서 포기하지 않죠?!', `FemaleText_loc4`='你为什么不放弃？！', `FemaleText_loc5`='為什麼就是不放棄?!', `FemaleText_loc7`='¡¿Por qué no se rinden?!' WHERE `ID`=56580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 행동에 나서야 하오! 타이리고사 님과 그분의 경비병들이 쓰러져서, 사원은 지금 무방비 상태요. 용의 영혼이 데스윙의 수하들에게 넘어가면 모든 게 끝장이니, 어떻게든 막아야 하오. 고룡쉼터 사원 용군단이 당신의 진격을 돕겠소. 적의 포위를 뚫어야 하오!', `MaleText_loc4`='我们必须尽快行动！塔丽苟萨和她的守卫们已经倒下了，神殿的防御完全崩溃。决不能让死亡之翼的部队接近巨龙之魂，否则一切都完了。龙眠联军会在战斗中协助你的；我们必须打破敌人的围攻！', `MaleText_loc5`='我們得加快動作!泰利苟莎和她的護衛已敗，神殿無人防守。絕對不能讓死亡之翼的手下染指巨龍之魂，否則一切就完了!龍眠協調者會協助你作戰，我們一定要打破敵人的攻勢!', `MaleText_loc7`='¡Tenemos que actuar con rapidez! Tyrygosa y su guardia han caído y han dejado el templo indefenso. Las fuerzas de Alamuerte no deben alcanzar el Alma de dragón jamás o todo estará perdido. El Acuerdo del Reposo del Dragón te ayudará durante el asalto: ¡debemos interrumpir el asedio!' WHERE `ID`=56581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외람되지만 용의 위상들께서 저와 제 동료 모험가들에게 도움을 주지 않으셨으면 합니다. 위상들께서는 위상들의 일을 신경 쓰시고, 저희 일은 저희가 신경 써야죠.', `MaleText_loc4`='我谦卑地请求守护巨龙们不要为我和我的同伴提供援助。他们应该操心他们自己的事，我们的事就让我们自己来解决吧。', `MaleText_loc5`='我謙卑地要求守護巨龍不要對我和我的同伴提供協助。他們只需要煩惱他們的問題，我們會處理好我們自己的狀況。', `MaleText_loc7`='Solicito humildemente que los dragones Aspectos no nos otorguen ayuda ni a mis compañeros de aventuras ni a mí. Deberían preocuparse por sus propios problemas y nosotros por los nuestros.', `FemaleText_loc1`='외람되지만 용의 위상들께서 저와 제 동료 모험가들에게 도움을 주지 않으셨으면 합니다. 위상들께서는 위상들의 일을 걱정하고, 저희 일은 저희가 걱정해야죠.', `FemaleText_loc4`='我谦卑地请求守护巨龙们不要为我和我的同伴提供援助。他们应该操心他们自己的事，我们的事就让我们自己来解决吧。', `FemaleText_loc5`='我謙卑地要求守護巨龍不要對我和我的同伴提供協助。他們只需要煩惱他們的問題，我們會處理好我們自己的狀況。', `FemaleText_loc7`='Solicito humildemente que los dragones Aspectos no nos otorguen ayuda ni a mis compañeros de aventuras ni a mí. Deberían preocuparse por sus propios problemas y nosotros por los nuestros.' WHERE `ID`=56582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈!', `MaleText_loc4`='蠢货！', `MaleText_loc5`='蠢蛋!', `MaleText_loc7`='¡Imbécil!', `FemaleText_loc1`='머리가 별로 좋지 않은가 보군, 암살자 녀석아.', `FemaleText_loc4`='你可真不聪明，刺客。', `FemaleText_loc5`='刺客，別自以為聰明!', `FemaleText_loc7`='No eres tan inteligente, $gasesino:asesina;.' WHERE `ID`=56583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 없애라!', `MaleText_loc4`='干掉$g他:她;。', `MaleText_loc5`='幹掉$g他:她;。', `MaleText_loc7`='¡Acaben con $gél:ella;.', `FemaleText_loc1`='더러운 좀도둑 녀석. 없애 버리겠어!', `FemaleText_loc4`='鬼鬼祟祟的老鼠。你死定了！', `FemaleText_loc5`='見不得人的東西，你會被消滅掉!', `FemaleText_loc7`='Serpiente repugnante. ¡Morirás!' WHERE `ID`=56584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 미쳤거나, 무모하거나, 아니면 전설이라 불릴 자격이 있는 영웅일 거요. 어느 쪽이오?', `MaleText_loc4`='你到底是个疯子、傻瓜，还是个值得颂扬的英雄呢？你到底是哪个？', `MaleText_loc5`='你要嘛是個瘋子、蠢蛋， 不然真正的傳奇英雄。你究竟是哪種呢?', `MaleText_loc7`='Puedes ser un demente, un imprudente o un héroe digno de ser una leyenda. ¿Qué eres tú?' WHERE `ID`=56585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 전설이 될 겁니다.', `MaleText_loc4`='我们会名留青史的。', `MaleText_loc5`='我們將變成傳奇。', `MaleText_loc7`='Seremos una leyenda.', `FemaleText_loc1`='저희는 전설이 될 겁니다.', `FemaleText_loc4`='我们会名留青史的。', `FemaleText_loc5`='我們將變成傳奇。', `FemaleText_loc7`='Seremos una leyenda.' WHERE `ID`=56586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기대하겠소, $C|1이여;여;.', `MaleText_loc4`='我们等着瞧吧，$C。', `MaleText_loc5`='等著瞧，$C。', `MaleText_loc7`='Veremos, $C.' WHERE `ID`=56587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 뭐라고 하든 저는 한 발자국도 안 움직일 거예요.', `MaleText_loc4`='有话就说吧。我一步都不会动的。', `MaleText_loc5`='隨便你怎麼說，我一寸都不會動的。', `MaleText_loc7`='Digas lo que digas, no pienso moverme ni un centímetro.' WHERE `ID`=56588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 네. 쉽지 않죠?', `MaleText_loc4`='我知道，对吗？', `MaleText_loc5`='我知道，是吧?', `MaleText_loc7`='Lo sé, ¿verdad?' WHERE `ID`=56589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 들어가려면 실력 발휘를 아주 제대로 하셔야 할 겁니다.', `MaleText_loc4`='你必须施展出浑身解数才有可能潜入那里。', `MaleText_loc5`='你得使出渾身解數，才有辦法混進去。', `MaleText_loc7`='Vas a tener que sacar a relucir todos los trucos que sabes para llegar allí.' WHERE `ID`=56590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 장비가 좀 부족하신 건...?', `MaleText_loc4`='这大概是你的装备吧？', `MaleText_loc5`='說不定是你的裝備?', `MaleText_loc7`='¿Será tu equipo?' WHERE `ID`=56591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='래시온 님이 당신을 믿고 계십니다. 당신은 할 수 있어요!', `MaleText_loc4`='拉希奥对你有信心。我就知道你一定能成功的！', `MaleText_loc5`='怒西昂相信你。我就知道你辦得到!', `MaleText_loc7`='Wrathion cree en ti. ¡Sé que puedes hacerlo!' WHERE `ID`=56592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은신한 상태로 날아다닐 수는 없다고요... 경험에서 우러나온 말입니다.', `MaleText_loc4`='你是不可能神不知鬼不觉地飞进去的……我试过了。', `MaleText_loc5`='你不能同時要飛、又同時要保持隱匿...我已經試過了。', `MaleText_loc7`='No puedes volar y estar en sigilo a la vez... lo he intentado.' WHERE `ID`=56593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공이군요! 타락한 용 하나가 또 없어졌어요! 곧 데스윙만 남겠군요...', `MaleText_loc4`='成功！我们又消灭了一条堕落的巨龙！很快，死亡之翼就得孤军奋战了……', `MaleText_loc5`='成功!又幹掉了一頭墮落的惡龍!很快就會只剩下死亡之翼而已...', `MaleText_loc7`='¡Bien! ¡Otro dragón corrupto ha caído! Pronto solo quedará Alamuerte...' WHERE `ID`=56594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어가셨군요! 날리스가 설치해 둔 모종의 방어 장치가 제 마법을 없애고 있습니다. 여기서부턴 당신을 도울 수가 없어요. 날리스를 처치하세요!', `MaleText_loc4`='你进去了！纳莉丝的守卫阻碍了我的魔法，所以从现在开始，我就没法继续指点你了。去干掉她！', `MaleText_loc5`='你進去了!納麗絲有阻斷我魔法的結界，所以我在外頭沒辦法協助你。去殺掉她!', `MaleText_loc7`='¡Estás dentro! Nalice tiene resguardos que bloquean mi magia, así que no podré ayudarte a salir de ahí. ¡Ve por ella!' WHERE `ID`=56595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s|1이;가; |cFF9900CC|Hspell:106401|h[황혼의 맹공격]|h|r을 시전하려고 합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s准备施放|cFF9900CC|Hspell:106401|h[暮光杀戮]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s準備使出|cFF9900CC|Hspell:106401|h[暮光突襲]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_fire_twilightflamebreath.blp:20|t¡%s se prepara para soltar un |cFF9900CC|Hspell:106401|h[Embate Crepuscular]|h|r!' WHERE `ID`=56596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가세요. 행운을 빕니다.', `MaleText_loc4`='再见，以及，祝好运。', `MaleText_loc5`='再見，祝好運。', `MaleText_loc7`='Adiós y buena suerte.', `FemaleText_loc1`='잘 가세요. 행운을 빕니다.', `FemaleText_loc4`='再见，以及，祝好运。', `FemaleText_loc5`='再見，祝好運。', `FemaleText_loc7`='Adiós y buena suerte.' WHERE `ID`=56597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리에게 도전하다니, 멍청한 악마 같으니. 불타는 군단은 놈의 부패한 시체를 보며 이 일리단 스톰레이지의 강력함을 느낄 것이야.
$b어둠장막 마법이 약해져서 더는 우리 몸을 숨길 수가 없구나. 숨어다니는 것도 재미있었지만, 사실 난 적에게 죽음을 안길 때 좀 더 거침없이 접근하는 걸 선호하지.
$b잘 싸워줬다. 하지만 지금부터는 나 혼자 가야 한다.', `MaleText_loc4`='真是个愚蠢的家伙，竟然想挑战我们。他那腐臭的尸体就留给燃烧军团做个纪念，好让他们牢记伊利丹·怒风的强大力量。
$b暗影斗篷的力量正在减弱，已经无法再遮掩我们的行踪了。这玩意儿用起来也挺有趣的，但我更喜欢直接把死亡带给我的敌人。
$b你很能打，可我接下来要去的地方只能由我独自前往了。', `MaleText_loc5`='愚蠢的東西，竟然膽敢挑戰我們。就讓他腐臭的屍體留下給軍團當證據，見識我伊利丹·怒風的力量。
$b暗影披風的魔力快消失了，無法繼續掩蔽我們的行蹤。雖然這還蠻有趣的，但其實我更喜歡正面進攻，讓我的敵手品嚐到死亡的滋味。
$b雖然你們的身手不錯，但接下來我不能帶你們一起走了，我得獨自行動。', `MaleText_loc7`='Qué criatura tan necia, intentando enfrentarse a nosotros. Su cadáver rancio servirá de recordatorio a la Legión del poder de Illidan Tempestira.
$bLa magia del manto de las Sombras se desvanece y deja de ocultarnos. Fue divertido mientras duró, pero prefiero un plan más directo para dar muerte a mi enemigo.
$bLuchaste bien, pero adonde me dirijo ahora tengo que ir solo.' WHERE `ID`=56598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 뭐 재미있는 장면이라도 놓쳤나요? 오, 어머나!', `FemaleText_loc4`='我错过什么好戏了吗？噢，哇！', `FemaleText_loc5`='我錯過了什麼嗎?喔，哇!', `FemaleText_loc7`='¿Me he perdido algo? ¡Oh, vaya!' WHERE `ID`=56599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요! 여기요! 아니요, 조금 아래를 보세요! 원하신다면 제가 원래 시간으로 돌려보내 드릴 수 있어요.', `FemaleText_loc4`='嘿！我在上面！不对，我在下面呢！如果你愿意的话，我可以把你送回现实世界。', `FemaleText_loc5`='嘿!在這邊!不對，在下面!若是你想的話，我可以帶你回當前的時間。', `FemaleText_loc7`='¡Oye! ¡Aquí! ¡No, aquí abajo! Te puedo llevar de vuelta al presente, si quieres.' WHERE `ID`=56600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이여;여;, 네가 지금 보고 있는 것은 너희 세계의 먼 미래이다. 데스윙, 황혼의 망치단, 그리고 놈들이 섬기는 고대 신이 승리한 세계이지. 과거의 환영들만이 거하는 척박한 황무지가 끝없이 펼쳐져 있다.', `MaleText_loc4`='$n，你眼前所见，就是遥远的未来。在这个时空，死亡之翼，暮光之锤和上古之神们赢得了胜利。因此，这里也成了一片荒芜，亘古不变的荒原，只有一些昔日的残影还在这里徘徊。', `MaleText_loc5`='此刻你所見的，$n，正是你遙遠的未來--死亡之翼、暮光之錘，還有他們服侍的上古邪神獲得勝利的未來。只剩凋零死寂的荒原，只剩下過去的哀嘆回聲。', `MaleText_loc7`='Lo que ves ahora, $n, es tu futuro distante. Un futuro en el que Alamuerte, el Martillo Crepuscular y los dioses antiguos a los que sirven han ganado. Un páramo baldío e inmutable habitado solo por los ecos del pasado.' WHERE `ID`=56601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $n|1이여;여;?', `MaleText_loc4`='你好啊，$n？', `MaleText_loc5`='$n，你找我?', `MaleText_loc7`='¿Sí, $n?' WHERE `ID`=56602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 거슬러 여행할 준비가 됐습니다. 영원의 샘으로 보내 주세요.', `MaleText_loc4`='我已经做好返回过去的准备了——我要去永恒之井。', `MaleText_loc5`='我已準備好返回過去，前往永恆之井。', `MaleText_loc7`='Estoy listo para viajar al pasado, al Pozo de la Eternidad.', `FemaleText_loc1`='시간을 거슬러 여행할 준비가 됐습니다. 영원의 샘으로 보내 주세요.', `FemaleText_loc4`='我已经做好返回过去的准备了——我要去永恒之井。', `FemaleText_loc5`='我已準備好返回過去，前往永恆之井。', `FemaleText_loc7`='Estoy lista para viajar al pasado, al Pozo de la Eternidad.' WHERE `ID`=56603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $n|1이여;여;.', `FemaleText_loc4`='欢迎你，$n。', `FemaleText_loc5`='你好，$n。', `FemaleText_loc7`='Saludos, $n.' WHERE `ID`=56604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄 님을 도울 준비가 됐습니다. 원래 시간대로 돌려보내 주세요.', `MaleText_loc4`='我准备好返回现实，去帮助萨尔了。', `MaleText_loc5`='我已準備好返回我當前的時間，協助索爾。', `MaleText_loc7`='Estoy listo para ayudar a Thrall, de vuelta en el presente.', `FemaleText_loc1`='스랄 님을 도울 준비가 됐습니다. 원래 시간대로 돌려보내 주세요.', `FemaleText_loc4`='我准备好返回现实，去帮助萨尔了。', `FemaleText_loc5`='我已準備好返回我當前的時間，協助索爾。', `FemaleText_loc7`='Estoy lista para ayudar a Thrall de vuelta en el presente.' WHERE `ID`=56605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 끝에서 노즈도르무 님을 만날 준비가 됐습니다.', `MaleText_loc4`='我准备好去时光之末见诺兹多姆了。', `MaleText_loc5`='我已準備好前往終焉之刻，與諾茲多姆見面。', `MaleText_loc7`='Estoy listo para ver a Nozdormu en el Fin de los Días.', `FemaleText_loc1`='시간의 끝에서 노즈도르무 님을 만날 준비가 됐습니다.', `FemaleText_loc4`='我准备好去时光之末见诺兹多姆了。', `FemaleText_loc5`='我已準備好前往終焉之刻，與諾茲多姆見面。', `FemaleText_loc7`='Estoy lista para ver a Nozdormu en el Fin de los Días.' WHERE `ID`=56606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간의 끝에서 노즈도르무 님을 만날 준비가 됐습니다.', `MaleText_loc4`='我准备好去时光之末见诺兹多姆了。', `MaleText_loc5`='我已準備好前往終焉之刻，與諾茲多姆見面。', `MaleText_loc7`='Estoy listo para ver a Nozdormu en el Fin de los Días.', `FemaleText_loc1`='시간의 끝에서 노즈도르무 님을 만날 준비가 됐습니다.', `FemaleText_loc4`='我准备好去时光之末见诺兹多姆了。', `FemaleText_loc5`='我已準備好前往終焉之刻，與諾茲多姆見面。', `FemaleText_loc7`='Estoy lista para ver a Nozdormu en el Fin de los Días.' WHERE `ID`=56607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 어떻게 도와드릴까요, 이방인이여?', `FemaleText_loc4`='我能帮你什么忙吗，陌生人？', `FemaleText_loc5`='陌生人，我能幫你什麼嗎?', `FemaleText_loc7`='¿Cómo podría ayudarte?' WHERE `ID`=56608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 옆에 붙어 있게, $n. 우리는 힘을 합쳐야 할 것이야.', `MaleText_loc4`='跟紧我，$n。我们可能需要互相帮助。', `MaleText_loc5`='待在我身邊，$n。我們或許會需要彼此的協助。', `MaleText_loc7`='Quédate a mi lado, $n. Puede que nos necesitemos el uno al otro.' WHERE `ID`=56609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났네. 용의 영혼은 무사히 용군단의 손안에 들어갔네.', `MaleText_loc4`='成功了。巨龙之魂已经被安全送到巨龙军团手中了。', `MaleText_loc5`='完成了。巨龍之魂已安全地落入龍群的手中。', `MaleText_loc7`='Ya está. El Alma de dragón está a salvo en la guarida de los Vuelos de los dragones.' WHERE `ID`=56610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잃어버린 동료를 찾고 있습니다.', `MaleText_loc4`='我在寻找走失的小伙伴。', `MaleText_loc5`='我要尋找失蹤的夥伴。', `MaleText_loc7`='Estoy buscando una mascota perdida.', `FemaleText_loc1`='잃어버린 동료를 찾고 있어요.', `FemaleText_loc4`='我在寻找走失的小伙伴。', `FemaleText_loc5`='我要尋找失蹤的夥伴。', `FemaleText_loc7`='Estoy buscando una mascota perdida.' WHERE `ID`=56613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='허! 시간의 위상이 너희들 편인데도, 어리석게 제발로 덫에 뛰어들다니?', `FemaleText_loc4`='嗤。仗着时光守护者站在你们那边，你们就敢闯进这陷阱吗？', `FemaleText_loc5`='嘖。就連有永恆之王幫忙，你們還是笨笨的踩入陷阱?', `FemaleText_loc7`='Aun con la ayuda del Aspecto del Tiempo, ¿caen como moscas en una trampa?' WHERE `ID`=56614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기뻐하기엔 일러, 애송이들아. 우리가 너희 필멸자들을 말살해주마.', `FemaleText_loc4`='别得意，小崽子。我们会把你们从这个世界上清除掉。', `FemaleText_loc5`='先別急，小傢伙們。我們會把你們從世界裡抹除。', `FemaleText_loc7`='No nos laman las heridas aún, cachorros. Eliminaremos a su raza de este mundo.' WHERE `ID`=56615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흥! 살아서 나갈 생각은 꿈도 꾸지마!', `FemaleText_loc4`='哼！你们休想活着离开这里！', `FemaleText_loc5`='哼!你們不會活著離開這裡!', `FemaleText_loc7`='¡No saldrán vivos de aquí!' WHERE `ID`=56616;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무도 최후의 대격변까지 살아남지 못할 것이다! 처치해!', `FemaleText_loc4`='你们没人能活着看到真正的大灾变！杀掉他们！', `FemaleText_loc5`='你們沒有人能活著見到最後的災變!解決他們!', `FemaleText_loc7`='¡Ninguno vivirá para presenciar el cataclismo final! ¡Acaben con ellos!' WHERE `ID`=56617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 갑옷! 놈의 갑옷이 벗겨지는군! 갑옷을 뜯어내면 놈을 쓰러뜨릴 기회가 생길 거요!', `MaleText_loc4`='看那些装甲！他正在解体！摧毁那些装甲，我们就能给他最后一击！', `MaleText_loc5`='他的護甲!他正在崩壞!破壞他的護甲，我們就有機會打贏他了!', `MaleText_loc7`='¡Las placas! ¡Se está deshaciendo! ¡Destrocen las placas y tendremos una oportunidad de derribarlo!' WHERE `ID`=56618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 걱정하지 마시오. 파괴자를 막으시오! 엔슈-팔라-나, 도리니.', `MaleText_loc4`='别担心我。去阻止灭世者吧！Enshu-falah-nah, dorini。', `MaleText_loc5`='別擔心我!阻止毀滅者!再會了，朋友。', `MaleText_loc7`='No se preocupen por mí. ¡Detengan al Destructor! Enshu-falah-nah, dorini.' WHERE `ID`=56619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말퓨리온...', `FemaleText_loc4`='玛法里奥……', `FemaleText_loc5`='瑪法里恩...', `FemaleText_loc7`='Malfurion...' WHERE `ID`=56620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샘 가장자리에요...', `FemaleText_loc4`='他在井水旁……', `FemaleText_loc5`='就在那個邊緣...', `FemaleText_loc7`='Por los pelos…' WHERE `ID`=56621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구신진 모르겠지만, 정말 감사합니다. 여러분의 도움이 없었다면 이 세계는... 아, 생각하고 싶지도 않군요. 달의 여신께서 그대의 앞길을 비춰주시길.', `FemaleText_loc4`='我不知道你是谁……但我要感谢你。没有你的帮助，我们的世界……我不敢想象。愿月神指引你的道路。', `FemaleText_loc5`='我不知道你是誰...但是謝謝你。沒有你們的幫忙，我們的世界就...我不敢再設想下去了。願月之女神照亮你。', `FemaleText_loc7`='No sé quién eres, pero... gracias. Sin tu ayuda, nuestro mundo sería... no quiero pensarlo. Que la diosa luna ilumine tu camino.' WHERE `ID`=56622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 멍청한 놈들, 아직 거기 붙어 있는지도 몰랐다.', `MaleText_loc4`='你们这些蠢货竟然还在我背上。', `MaleText_loc5`='沒想到你們這些笨蛋居然還在這裡。', `MaleText_loc7`='No me había percatado de que aún estaban aquí, insensatos.' WHERE `ID`=56623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버둥거리는 꼴이 가소롭군. 내 너희를 황천으로 인도해주마.', `MaleText_loc4`='你们的努力是徒劳的，我只会带着你们飞向死亡。', `MaleText_loc5`='你們的努力毫無意義。我會背著你們迎接死亡。', `MaleText_loc7`='Sus esfuerzos son inútiles. Los llevaré a la tumba.' WHERE `ID`=56624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있는 힘껏 매달려 보시지, 영웅 나리. 너와 네 세상은 끝이다.', `MaleText_loc4`='别抵抗了，“英雄们”。你们和这个世界都在劫难逃。', `MaleText_loc5`='繼續抓緊吧，「英雄們」。你們的世界要完蛋了。', `MaleText_loc7`='Aférrense mientras puedan, "héroes". Están todos condenados.' WHERE `ID`=56625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끈기 하나는 인정해 줘야겠군. 하지만 무의미하다. 너희들을 파멸의 도가니에 처넣어주마!', `MaleText_loc4`='你们的顽强令我赞叹，但毫无价值。你们踏上了末日审判之路。', `MaleText_loc5`='你們的固執令人讚嘆，但是毫無意義。你們正在前往末日的旅途中。', `MaleText_loc7`='Su tesón es admirable, pero inútil. Se precipitan hacia las fauces del apocalipsis.' WHERE `ID`=56626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 운룡은 옥룡사 정원 밖으로 나갈 수 없습니다! 떨어지기 전에 돌아가야 합니다!', `MaleText_loc4`='作战翔龙是不能飞出青龙寺庭院的！在你被扔下来之前赶紧回去！', `MaleText_loc5`='戰蛟不會進入玉廟庭!在你被吃乾抹淨前退回去!', `MaleText_loc7`='¡El dragón de guerra no viajará fuera de las Tierras del Templo de Jade! ¡Vuelve antes de que te desmonte!', `FemaleText_loc1`='전투 운룡은 옥룡사 정원 밖으로 나갈 수 없습니다! 떨어지기 전에 돌아가야 합니다!', `FemaleText_loc4`='作战翔龙是不能飞出青龙寺庭院的！在你被扔下来之前赶紧回去！', `FemaleText_loc5`='戰蛟不會進入玉廟庭!在你被吃乾抹淨前退回去!', `FemaleText_loc7`='¡El dragón de guerra no viajará fuera de las Tierras del Templo de Jade! ¡Vuelve antes de que te desmonte!' WHERE `ID`=56627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 혼돈의 소용돌이로 갑니다! 당장 막아야 합니다! 놈이 심원의 영지로 도망치면 돌이킬 수 없습니다.', `MaleText_loc4`='他朝着大漩涡去了！我们必须马上阻止他；如果他逃回了深岩之洲，我们就再也没有机会了。', `MaleText_loc5`='他正要前往大漩渦!我們必須阻止他，如果他逃到地深之源，我們也許就沒機會了!', `MaleText_loc7`='¡Se dirige a La Vorágine! Debemos detenerlo ya; quizás no tengamos otra oportunidad si llega hasta Infralar.' WHERE `ID`=56628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘불꽃호에 온 걸 환영하오. 세계의 끝까지 추적할 준비는 됐소?', `MaleText_loc4`='欢迎登上天火号。我们要追到世界的尽头，你们准备好了吗？', `MaleText_loc5`='歡迎搭乘天火號。準備好追到天涯海角了嗎?', `MaleText_loc7`='Bienvenidos a bordo de El Rompecielos. ¿Listos para llegar hasta el fin del mundo?' WHERE `ID`=56629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물이!', `MaleText_loc4`='啊，神器！', `MaleText_loc5`='神器!', `MaleText_loc7`='¡El artefacto!' WHERE `ID`=56630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형... 딱 맞춰서 왔군...', `MaleText_loc4`='哥哥……你来得真及时……', `MaleText_loc5`='兄弟...來得正好...', `MaleText_loc7`='Hermano... justo a tiempo…' WHERE `ID`=56631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아. 수많은 마법에 영향을 받아 샘이 뒤틀리고 말았어. 우리가... 아니, 형이 차원문을 닫겠다고 한 짓이 과했던 거야! 불타는 군단을 저 더러운 지옥으로 돌려보낸 그 주문이 이제 샘에도 영향을 미치고 있어! 샘 자체와, 그 주변까지 몽땅 삼켜버리고 있다고! 재미있군... 안 그래?!', `MaleText_loc4`='没错。滥用魔法导致了它的扭曲。我们——特别是你——处理传送门时做得太过火了！将燃烧军团送回扭曲虚空的力量现在影响到了永恒之井！它正在自我吞噬，并吸收周围的一切东西！真壮观，是吧？', `MaleText_loc5`='是的。它被太多法術扭曲了。我們 - 特別是你施放太多法術干擾傳送門了!用來把燃燒軍團逐回他們世界的法術也影響了永恆之井!它正在吞噬自己和身邊的環境!很有意思，不是嗎?', `MaleText_loc7`='Sí. Lo han corrompido demasiados hechizos. ¡La confusión que hemos causado en el portal, especialmente tú, ha sido excesiva! ¡El mismo hechizo que devolvió a la Legión Ardiente a su reino infecto ahora actúa en el pozo! Se está devorando a sí mismo y a cuanto lo rodea. Fascinante, ¿no?' WHERE `ID`=56632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형이 나가는 길을 알면 가르쳐 주지그래! 마법으로 티란데와 함께 탈출하려고 해 봤는데, 샘이 너무 요동쳐서 먹히질 않아!', `MaleText_loc4`='如果你知道怎么离开，我们恐怕得赶快了！我本想带着泰兰德离开，但井水的魔力太混乱了！', `MaleText_loc5`='如果你有離開的方法，趕快用吧!我本來想傳送自己跟泰蘭妲離開，但井的狀況太不穩定了', `MaleText_loc7`='Si conoces una salida, deberíamos usarla. He intentado salir de aquí con Tyrande, ¡pero el pozo está demasiado inestable!' WHERE `ID`=56633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 여왕님을 거역하다니!', `MaleText_loc4`='没人能背叛女王！', `MaleText_loc5`='冒犯女王的下場。', `MaleText_loc7`='Nadie se opondrá a la Reina.' WHERE `ID`=56634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어 마땅하다.', `MaleText_loc4`='死有余辜！', `MaleText_loc5`='罪有應得。', `MaleText_loc7`='Una muerte merecida.' WHERE `ID`=56635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아즈샤라의 이름으로!', `MaleText_loc4`='以艾萨拉之名！', `MaleText_loc5`='以艾薩拉之名!', `MaleText_loc7`='¡En nombre de Azshara!' WHERE `ID`=56636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하시오, 티란데. 일리단은 어디 있소?', `MaleText_loc4`='哈，泰兰德。伊利丹在哪？', `MaleText_loc5`='噓，泰蘭妲。伊利丹在哪?', `MaleText_loc7`='Calma, Tyrande. ¿Dónde está Illidan?' WHERE `ID`=56637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단! 샘은 지금 극도로 불안정해!', `MaleText_loc4`='伊利丹！永恒之井失去控制了！', `MaleText_loc5`='伊利丹!永恆之井失控了!', `MaleText_loc7`='¡Illidan! ¡El pozo está fuera de control!' WHERE `ID`=56638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같이 빨려들어가면 재미없을 게다! 왜 도망가지 않았지? 뭐 하느라 샘에 손을 담그고 있었던 거냐?', `MaleText_loc4`='我们可不能被卷进去！你为什么不逃跑？……你把手伸进井水里想干什么？', `MaleText_loc5`='被吸進去就不好玩了!你為什麼還不跑?...還有，你的手放在井裡做什麼?', `MaleText_loc7`='¡No si nos quedamos atrapados en él! ¿Por qué no corriste?... ¿Qué hacías con la mano en el pozo?' WHERE `ID`=56639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로!', `MaleText_loc4`='走这边！', `MaleText_loc5`='走這裡!', `MaleText_loc7`='¡Por aquí!' WHERE `ID`=56640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥을 기며 죽어가라!', `MaleText_loc4`='屈服于我，死吧！', `MaleText_loc5`='在我面前倒下吧!', `MaleText_loc7`='¡Caigan y MUERAN ante mí!' WHERE `ID`=56641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸부림쳐라! 비명을 질러!', `MaleText_loc4`='抽搐吧！惨叫吧！', `MaleText_loc5`='蠕動吧，慘叫吧!', `MaleText_loc7`='¡Retuérzanse y griten!' WHERE `ID`=56642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 놈!', `MaleText_loc4`='没用的东西！', `MaleText_loc5`='沒用!', `MaleText_loc7`='¡Inútil!' WHERE `ID`=56643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[악마어] 아마나르 마이브 일 아즈갈라다 질라 아셰 아셰 질라 엔킬!', `MaleText_loc4`='[恶魔语] Amanare maev il azgalada zila ashj ashj zila enkil！', `MaleText_loc5`='[惡魔語] Amanare maev il azgalada zila ashj ashj zila enkil!!', `MaleText_loc7`='[Demoníaco] ¡Amanare maev il azgalada zila ashj ashj zila enkil!' WHERE `ID`=56644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 시대에서 모은 물건이 좀 있어요. 마음에 드시면 좋겠군요!', `FemaleText_loc4`='我们从这个时间段收集了一些东西。但愿它能帮上忙！', `FemaleText_loc5`='我們在這段時間軸裡收集到了一些物品。希望能幫上你!', `FemaleText_loc7`='He conseguido algunos objetos de este tiempo. ¡Espero que sirva de ayuda!' WHERE `ID`=56645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 불쌍한 자식들을 내 명령만을 따르는 넋나간 졸개들로 만들었거든. 생각보다 참... 눈뜨고 보기 힘들더군.', `MaleText_loc4`='将你的幼龙变成扭曲无脑的畸形，并屈从于我的命令。这可是……非常痛苦的过程。', `MaleText_loc5`='忙著把你可悲的幼龍轉為無腦的怪物，只聽從我的命令。過程...相當...痛苦。', `MaleText_loc7`='Convirtiendo a tus patéticas crías en descerebradas abominaciones sometidas a mi voluntad. Fue un proceso... muy... doloroso.' WHERE `ID`=56646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네파리안, 오닉시아, 시네스트라... 그들은 아무것도 아니었다. 이제 내 궁극의 창조물을 상대해라.', `MaleText_loc4`='奈法利安，奥妮克希亚，希奈丝特拉……他们毫无价值。现在，你们就要面对我最终的造物。', `MaleText_loc5`='奈法利安、奧妮克希亞、賽絲特拉...都不算什麼。面對我最終極的傑作吧。', `MaleText_loc7`='Nefarian, Onyxia, Sinestra… no eran nada. Ahora se enfrentarán a mi máxima creación.' WHERE `ID`=56647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼의 시간이 임박했다. 태양이 지리라. 하찮은 네 필멸의 육신 위로.', `MaleText_loc4`='暮光审判已经临近；你们这些可悲的凡人即将谢幕。', `MaleText_loc5`='暮光之時已降臨，你們可悲的凡人即將毀滅。', `MaleText_loc7`='La Hora del Crepúsculo se acerca dando paso al ocaso de su lastimera y mortal existencia.' WHERE `ID`=56648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이 술통을 수레에 실어 볼까?', `MaleText_loc4`='我们把这些酒装上马车，怎么样？', `MaleText_loc5`='我們來把這些桶子抬到推車上吧，好嗎?', `MaleText_loc7`='Vamos a cargar esos barriles en la carreta, ¿sí?' WHERE `ID`=56649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트 양조장으로 간다!', `MaleText_loc4`='前往风暴烈酒酿造厂！', `MaleText_loc5`='朝風暴烈酒酒坊前進!', `MaleText_loc7`='¡Hacia la Cervecería del Trueno!' WHERE `ID`=56650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕골아, 안녕!', `FemaleText_loc4`='再见，半山村！', `FemaleText_loc5`='再會了，半丘!', `FemaleText_loc7`='¡Hasta la vista, El Alcor!' WHERE `ID`=56651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그, 같이 가겠나?', `MaleText_loc4`='泥盏，你来吗？', `MaleText_loc5`='泥杯，你來不來?', `MaleText_loc7`='Caolín, ¿vienes?' WHERE `ID`=56652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 글쎄요. 첸 님 집안일인 것 같아서 제가 함께해도 될지...', `MaleText_loc4`='噢，我不太确定。这看来是你们的家务事……', `MaleText_loc5`='喔，我不知道耶。你的生意好像是家族事業...', `MaleText_loc7`='Ah, no sé. Parece más un asunto de familia, y, bueno...' WHERE `ID`=56653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집안일 맞다네, 머드머그. 그래서 같이 가자는 걸세.', `MaleText_loc4`='这确实是家务事，泥盏。但是我希望你加入。', `MaleText_loc5`='泥杯，沒錯，這的確是家族事業，而且我希望你加入我們。', `MaleText_loc7`='Sí, es un asunto de familia, Caolín. Y quiero que vengas con nosotros.' WHERE `ID`=56654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜요?', `MaleText_loc4`='不开玩笑？', `MaleText_loc5`='不是開玩笑吧?', `MaleText_loc7`='¿En serio?' WHERE `ID`=56655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하지! 맥주도 함께 담근 사이 아닌가. 그 순간 우린 형제가 됐네.', `MaleText_loc4`='当然不开玩笑！我们一起酿过酒，我们是好兄弟。', `MaleText_loc5`='當然不是!我們一起釀過酒，這讓我們跟親兄弟一樣親。', `MaleText_loc7`='¡Por supuesto! Hemos preparado cerveza juntos. Eso casi nos convierte en hermanos.' WHERE `ID`=56656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 맥주 형제라니!', `MaleText_loc4`='对啊！啤酒兄弟！', `MaleText_loc5`='咿耶!啤酒兄弟!', `MaleText_loc7`='¡Sí! ¡Hermanos de cerveza!' WHERE `ID`=56657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우웩! 두 사람 때문에 토하겠어요.', `FemaleText_loc4`='呃！你们俩就得了吧。', `FemaleText_loc5`='呃!你們這些傢伙快讓我吐了。', `FemaleText_loc7`='¡Puaj! Me van a hacer vomitar.' WHERE `ID`=56658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 수레 끄는 것 좀 도와 주게.', `MaleText_loc4`='来，和我一起拉货车。', `MaleText_loc5`='來嘛，幫我拉這台推車。', `MaleText_loc7`='Vamos, ayúdame a tirar de esta carreta.' WHERE `ID`=56659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 제일 빠른 거예요? 뚱보들! 빨리 좀 움직여요!', `FemaleText_loc4`='这就是你们最快的速度？加油，胖子们！都跑起来！', `FemaleText_loc5`='你們最快只能這樣嗎?來吧，胖子們!把腳動起來!', `FemaleText_loc7`='¿Esto es lo más rápido que pueden ir? ¡Vamos, gorditos! ¡Muevan esas patas!' WHERE `ID`=56660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어. 이제 밥값 좀 해 볼까나...', `MaleText_loc4`='很好，收紧小腹，气聚丹田……', `MaleText_loc5`='好吧，我會使盡我肚子的力氣...', `MaleText_loc7`='Muy bien, a ver si hago de contrapeso con la barriga…' WHERE `ID`=56661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착해서 보세!', `MaleText_loc4`='待会儿见，$n！', `MaleText_loc5`='$n，我們在那裡見!', `MaleText_loc7`='¡Nos vemos allí, $n!' WHERE `ID`=56662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜로... 바보짓 좀 하지 마요.', `FemaleText_loc4`='说正经的，泥盏。一起去吧。', `FemaleText_loc5`='說真的，泥杯。別笨了。', `FemaleText_loc7`='Ahora en serio, Caolín. No seas tonto.' WHERE `ID`=56663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 그런 것만은 아니오. 내 생각에... 그래... 그 방법이라면.', `MaleText_loc4`='不，还不一定。我相信……是的……这样也许能行。', `MaleText_loc5`='也不一定。我相信...是的，也許能成功。', `MaleText_loc7`='No necesariamente. Creo que... sí... puede que funcione.' WHERE `ID`=56664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 내가 영원의 눈으로 가는 길을 열겠소. 실패해선 안 됩니다, 영웅들이여. 아제로스의 미래가 그대들에게 달렸습니다.', `MaleText_loc4`='我会打开通向永恒之眼的通路。英雄们，你们绝不能失败，艾泽拉斯的未来寄托在你们身上。', `MaleText_loc5`='那我就開啟進入永恆之眼的路吧。英雄們，你們不能失敗。艾澤拉斯的未來就交給你們了。', `MaleText_loc7`='Después, abriré una vía hasta El Ojo de la Eternidad. No deben fracasar, héroes. El futuro de Azeroth depende de sus actos.' WHERE `ID`=56665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없습니다. 용의 영혼이 가진 힘이 너무 강력해 안전하게 다룰 수 없습니다. 이 안의 혼돈의 힘이 모두에게 파멸을 가져올지도 모릅니다.', `MaleText_loc4`='这没有用，巨龙之魂的力量太强大了。我不能安全地使用它，这个神器里的混乱力量也许会毁掉我们所有的人。', `MaleText_loc5`='沒有用，巨龍之魂的力量太強了。我無法安全地使用它，它所含有的混沌力量會使我們滅亡。', `MaleText_loc7`='No sirve de nada, el Alma es demasiado poderosa. No puedo empuñarla de forma segura; la ira que encierra podría ser nuestra perdición.' WHERE `ID`=56666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 마침내 데스윙의 힘을 고스란히 놈에게 돌려줄 수 있겠습니다.', `MaleText_loc4`='是的，我明白了。我们将使用死亡之翼的力量去对付他自己。', `MaleText_loc5`='沒錯，我懂了。我們終於可以用死亡之翼自己的力量來對付他。', `MaleText_loc7`='Comprendo. Finalmente podríamos utilizar el poder de Alamuerte contra él mismo.' WHERE `ID`=56667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 또한 우리의 패배로군.', `FemaleText_loc4`='那么，我们就真的失败了。', `FemaleText_loc5`='那我們就真的失敗了。', `FemaleText_loc7`='Entonces, estamos perdidos.' WHERE `ID`=56668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위험이 느껴지는군. 이건 함정이오... 이 중대한 순간을 위해 미리 준비된 함정.', `FemaleText_loc4`='我感到了危险。这是个陷阱……在这个险恶的时刻，我们被算计了。', `FemaleText_loc5`='我感到危險。在如此關鍵的時刻，有一個為我們精心安排的陷阱。', `FemaleText_loc7`='Siento el peligro. Es una trampa... cuidadosamente tendida para nosotros en este momento crucial.' WHERE `ID`=56669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택권이 없습니다. 우리편을 믿는 수 밖에.', `MaleText_loc4`='我们没有选择，必须相信这些盟友。', `MaleText_loc5`='我們沒有選擇。我們只能相信盟友了。', `MaleText_loc7`='No tenemos alternativa. Debemos tener fe en nuestros aliados.' WHERE `ID`=56670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 도전자가 나타났군! 그래, "용사"라고? 얼마나 튼튼한 녀석인지 한번 보자!', `MaleText_loc4`='终于来了！一个挑战者！让我们来试试你的气魄吧，“勇士”。', `MaleText_loc5`='終於!有點挑戰性了!讓我們試試你的身手吧，「勇士」。', `MaleText_loc7`='¡Por fin, un desafío! Veamos de qué material estás hecho, "campeón".' WHERE `ID`=56671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛 앞에 기원을 드리러 온 것이오? 아니면 신성한 능력을 훈련하러 왔소?$b$b대주교 베네딕투스 님과 이야기를 나누러 온 것이라면 미안하지만 그분은 지금 임무를 수행하러 떠났소.', `MaleText_loc4`='你是来向圣光祈祷的吗？还是来接受圣光技艺的训练呢？$b$b如果你是来找大主教本尼迪塔斯的话，那我必须很抱歉地告诉你，他出门去执行任务了。', `MaleText_loc5`='你是來向聖光祈禱致敬的?還是要來接受使用聖光之力的訓練?$B$B但如果你是來找大主教本尼迪塔斯的，那麼很抱歉，他已經動身離開去執行某個重要任務了。', `MaleText_loc7`='¿Has venido para suplicarle a la Luz? ¿O tal vez has venido para instruirte en el arte de lo sagrado?$b$BSi estás aquí para hablar con el arzobispo Benedictus, siento informarte de que ha salido en una misión.' WHERE `ID`=56672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇소. 베네딕투스는 고룡쉼터 사원에 있는 위상들을 도우려고 갔소. 그는 데스윙의 위협에 빠진 아제로스를 정화하고자 그들을 돕고 싶어 했다오.$b$b베네딕투스의 앞길에 성스러운 빛의 가호가 함께하기를.', `MaleText_loc4`='是的。他受命前往龙眠神殿帮助守护巨龙。他希望能帮助他们扫除死亡之翼对艾泽拉斯的威胁。$b$b愿圣光指引他的道路。', `MaleText_loc5`='是的。他獲邀前去龍眠神殿，協助守護巨龍淨化艾澤拉斯，洗去死亡之翼的威脅。$b$b願聖光指引他的道路。', `MaleText_loc7`='Sí. Se le ha convocado para ayudar a los aspectos con sus esfuerzos en el Reposo del Dragón. Desea ayudarlos a limpiar Azeroth de la amenaza de Alamuerte.$b$b¡Que la Luz guíe su camino!' WHERE `ID`=56673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 황혼의 예언자 베네딕투스라!$b$b하하하!$b$b아주 끝내주는군. 하하.', `MaleText_loc4`='哈哈哈！本尼迪塔斯，暮光先知！$b$b哇哈哈哈！$b$b噢，那真是太好了。万岁！', `MaleText_loc5`='哈哈哈!本尼迪塔斯是暮光預言者!$B$B哇哈哈哈!$B$B哦，真是太好笑了，哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja! ¡Benedictus, el profeta Crepuscular!$b$b¡Ja, ja, ja, ja!$b$bOh, esa es buena. ¡Ayyyy!' WHERE `ID`=56674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문이오, 어린 친구. 힘이 있는 사람들 주변에는 소문이 돌기 마련이지. 사실 나도 최근에 세상을 떠난 볼바르 경에 대한 아주 고약한 소문을 들었다오.$b$b당신의 거짓말을 다른 곳에도 퍼뜨렸으면 좋겠소. 그리고 빛 앞에 용서를 고할 준비가 되면 다시 돌아오시오.', `MaleText_loc4`='都是流言，孩子。流言总是能想方设法地和大人物搭上关系。事实上，我最近还听到一些关于已故的伯瓦尔大人的坏话呢。$b$b到别处去散播你的谎言吧。等你准备好在圣光面前忏悔自己的错误时再回来吧。', `MaleText_loc5`='謠言啊，孩子。名人總免不了會受穿鑿附會、空穴來風的謠言所苦。事實上，最近我才聽到一則對已故的伯瓦爾大人相當不敬的謠言。$b$b要撒謊請到別地方去吧，等你願意向聖光懺悔認錯的時候再回來。', `MaleText_loc7`='Rumores. Los rumores son una forma de relacionarse con la gente de poder. De hecho, hace poco oí uno particularmente desagradable sobre el difunto señor Bolvar.$b$bTe voy a pedir que vayas a contar tus mentiras a otro lugar. Vuelve cuando quieras confesar tus faltas ante la Luz.' WHERE `ID`=56675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무 말입니까?', `MaleText_loc4`='任务？', `MaleText_loc5`='重要任務?', `MaleText_loc7`='¿Una misión?', `FemaleText_loc1`='임무라니요?', `FemaleText_loc4`='任务？', `FemaleText_loc5`='重要任務?', `FemaleText_loc7`='¿Una misión?' WHERE `ID`=56676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 고룡쉼터 사원에서 베네딕투스를 봤습니다. 그는 황혼의 예언자였습니다.', `MaleText_loc4`='事实上，我在龙眠神殿见到了本尼迪塔斯。他就是暮光先知。', `MaleText_loc5`='事實上，我在龍眠神殿看到了本尼迪塔斯。他正是暮光預言者。', `MaleText_loc7`='La verdad es que vi a Benedictus en el Reposo del Dragón. Era el profeta Crepuscular.', `FemaleText_loc1`='사실 고룡쉼터 사원에서 베네딕투스를 봤어요. 그는 황혼의 예언자였답니다.', `FemaleText_loc4`='事实上，我在龙眠神殿见到了本尼迪塔斯。他就是暮光先知。', `FemaleText_loc5`='事實上，我在龍眠神殿看到了本尼迪塔斯。他正是暮光預言者。', `FemaleText_loc7`='La verdad es que vi a Benedictus en el Reposo del Dragón. Era el profeta Crepuscular.' WHERE `ID`=56677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니다. 베네딕투스는 스랄 님을 없애버리고 아제로스를 데스윙에게 바치려고 했습니다. 제 두 눈으로 똑똑히 봤습니다.', `MaleText_loc4`='我可没开玩笑。本尼迪塔斯想要杀了萨尔，把艾泽拉斯拱手交给死亡之翼。这是我亲眼看到的。', `MaleText_loc5`='我是說真的。本尼迪塔斯企圖殺害索爾，把艾澤拉斯奉送給死亡之翼。我親眼看到的。', `MaleText_loc7`='En serio. Benedictus intentó matar a Thrall y entregar Azeroth a Alamuerte. Lo vi con mis propios ojos.', `FemaleText_loc1`='정말이에요. 베네딕투스는 스랄 님을 없애버리고 아제로스를 데스윙에게 바치려고 했어요. 제 두 눈으로 똑똑히 봤답니다.', `FemaleText_loc4`='我可没开玩笑。本尼迪塔斯想要杀了萨尔，把艾泽拉斯拱手交给死亡之翼。这是我亲眼看到的。', `FemaleText_loc5`='我是說真的。本尼迪塔斯企圖殺害索爾，把艾澤拉斯奉送給死亡之翼。我親眼看到的。', `FemaleText_loc7`='En serio. Benedictus intentó matar a Thrall y entregar Azeroth a Alamuerte. Lo vi con mis propios ojos.' WHERE `ID`=56678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 용들이 사원을 구하기 위해 애쓰고 있습니다.$B$B필요하다면 기꺼이 힘을 빌려줄 것입니다.', `MaleText_loc4`='我们的翔龙正在努力拯救寺庙。$B$B如果你需要的话，它们很乐意向你伸出援手。', `MaleText_loc5`='我們的蛟龍孜孜不倦地保衛著寺廟。$b$b若你需要，牠們會樂於助你一臂之力。', `MaleText_loc7`='Nuestros dragones se están esforzando mucho para salvar el templo.$b$bSi te hace falta su fuerza, te la prestarán de buena gana.' WHERE `ID`=56679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 적은 처음 봅니다.', `MaleText_loc4`='我从来没有见到过像这样的敌人。', `MaleText_loc5`='我從沒看過這種敵人。', `MaleText_loc7`='Nunca había visto un enemigo así.' WHERE `ID`=56680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 우리 땅이네. 우리 집이야.$B$B샤의 손에 부서지게 내버려 두지는 않겠네.', `MaleText_loc4`='这是我们的土地，我们的家园。$B$B我绝不会眼睁睁看着它落入煞魔手中。', `MaleText_loc5`='這是我們的土地。我們的家。$B$B我不會坐視它在煞的手中淪陷。', `MaleText_loc7`='Esta es nuestra tierra. Nuestro hogar.$b$bNo permitiré que caiga en manos de los sha.' WHERE `ID`=56681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 깨달은 존재가 되기 위해 무던히도 애를 썼지만, 과거의 실수를 반복하고 말았네.$B$B샤가 다시 한 번 이 땅을 위협하고 있어.', `MaleText_loc4`='尽管我们一直努力想要塑造更加进步的文明，可我们总是重复过去的错误。$B$B煞魔又一次威胁到了这片土地。', `MaleText_loc5`='儘管我們努力想成為文明的生物，我們還是重複了過去的錯誤。$B$B煞再次威脅到這片土地。', `MaleText_loc7`='A pesar de nuestros esfuerzos para convertirnos en seres iluminados, hemos caído en los errores del pasado.$b$bEl sha amenaza esta tierra de nuevo.' WHERE `ID`=56682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과거의 실수만을 곱씹으며 살 수는 없네, $r.$B$B우리가 갈 길은 앞으로 나아가는 길뿐이야.', `MaleText_loc4`='我们不能纠结于过去的错误了，$r。$B$B现在唯一的办法就是前进。', `MaleText_loc5`='我們不能沈溺於過去的錯誤，$r。$B$B往前行才有唯一的道路。', `MaleText_loc7`='No podemos aferrarnos a los errores del pasado, $r.$b$bSolo podemos seguir adelante.' WHERE `ID`=56683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용기를 내게, $r. 함께라면 우린 샤를 물리칠 수 있네.', `FemaleText_loc4`='拿出你的勇气来，$r。团结一致，我们就能对抗煞魔。', `FemaleText_loc5`='鼓起你的勇氣，$r。同心協力，我們可以抵抗煞。', `FemaleText_loc7`='Ármate de valor, $r. Juntos resistiremos a los sha.' WHERE `ID`=56684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤의 공격이 시작되었을 때, 내 제자들은 한 명도 빠짐 없이 전장으로 달려갔지.$B$B내가 많은 것을 가르치기도 했지만, 제자들은 늘 내 기대를 뛰어넘는다네.', `FemaleText_loc4`='当煞魔开始攻击的时候，我所有的弟子都毫不犹豫地出去战斗了。$B$B我教了他们很多东西，但他们的表现总能超出我的期望。', `FemaleText_loc5`='煞再次攻擊時，我的學生全都毫無猶豫地加入戰鬥。$b$b我教了他們很多，但他們依舊不斷超越我的期待。', `FemaleText_loc7`='Cuando los sha atacaron, todos y cada uno de mis discípulos se lanzó a la batalla sin dudarlo.$b$bLes he enseñado mucho, pero siguen superando mis expectativas.' WHERE `ID`=56685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜 시간이 흐르는 동안, 샤에 대한 지식도 대부분 사라졌지.$B$B이제는 전투를 계속하면서 샤의 성질을 파악해야 하네.$B$B그래야만 이후에도 이런 일이 다시 발생하는 것을 막을 수 있어.', `FemaleText_loc4`='我们对煞魔的大部分认知都失传了。$B$B随着战斗的持续，我必须要研究他们的天性。$B$B只有这样，我们才能避免同样的悲剧在将来再次发生。', `FemaleText_loc5`='我們關於煞的知識有很多在時間中散佚了。$B$B在戰鬥繼續之際，我必須研究他們的特質。$B$B只有這樣我們才能防止這種事在未來再次發生。', `FemaleText_loc7`='Gran parte de lo que sabíamos de los sha se ha perdido con el tiempo.$b$bMientras la batalla continúa, debo estudiar su naturaleza.$b$bSolo entonces impediremos que esto vuelva a suceder.' WHERE `ID`=56686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 수업에 참관하러 왔나?', `FemaleText_loc4`='你是来观摩我教学的吗？', `FemaleText_loc5`='你是來旁聽我講的課嗎?', `FemaleText_loc7`='¿Has venido a presenciar mi clase?' WHERE `ID`=56688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 오세요, 여행자님. 마음 편히 머물면서 푹 쉬고 가세요.', `FemaleText_loc4`='欢迎你，旅行者。请在此稍事休息。', `FemaleText_loc5`='歡迎，旅人。請待下來休息一陣。', `FemaleText_loc7`='$gBienvenido, viajero:Bienvenida, viajera;. Quédate un rato y descansa.' WHERE `ID`=56690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤가 저 밖에만 있으니, 저는 괜찮을 거예요.', `FemaleText_loc4`='只要煞魔还待在外面，我就不会有事。', `FemaleText_loc5`='只要煞繼續被擋在外面，我就會沒事的。', `FemaleText_loc7`='Mientras los sha sigan fuera, estaré bien.' WHERE `ID`=56691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 막아내려면 우리 전사들에게 영양가 있는 음식을 대접해야 합니다!$B$B어서 제가 뭘 대접하면 좋을지 말씀하세요.', `MaleText_loc4`='我们的战斗需要有营养的食物才能挡住敌人！$B$B快，告诉我我能给你弄点什么。', `MaleText_loc5`='我們的戰士需要有營養的食物來抵禦敵人!$B$B快說說我能給你來點什麼。', `MaleText_loc7`='¡Nuestros luchadores necesitan comida nutritiva para mantener a raya al enemigo!$b$bDate prisa y dime qué quieres.' WHERE `ID`=56692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴 표정을 보니 따끈한 식사가 하고 싶으시겠군요.$B$B뭘 드릴까요?', `MaleText_loc4`='你看上去需要一顿热饭热菜。$B$B要我给你弄点什么？', `MaleText_loc5`='你看起來需要一頓熱騰騰的大餐。$b$b我能給你來什麼?', `MaleText_loc7`='Tienes pinta de necesitar una comida caliente.$b$b¿Qué quieres?' WHERE `ID`=56693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티탄을 찬양하라. 그들이 돌아왔다!', `FemaleText_loc4`='赞美泰坦，他们回来了！', `FemaleText_loc5`='讚美泰坦，他們回來了!', `FemaleText_loc7`='¡Alabados sean los Titanes, han regresado!' WHERE `ID`=56694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 정도는 예상했다.', `MaleText_loc4`='倒也不是完全没料到。', `MaleText_loc5`='也算是意料中的事。', `MaleText_loc7`='Era de esperar.' WHERE `ID`=56695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 지금 당장 의식을 시작하지요!', `MaleText_loc4`='太好了！我们马上就开始仪式！', `MaleText_loc5`='很好!我們立刻就進行儀式!', `MaleText_loc7`='¡Excelente! ¡Iniciaremos el ritual de inmediato!' WHERE `ID`=56696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠! 문 닫은 것 같은데?', `FemaleText_loc4`='唔！他们好像关门了。', `FemaleText_loc5`='哈!看來他們已經關門了。', `FemaleText_loc7`='¡Vaya! Parece que ya cerraron.' WHERE `ID`=56697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이상하구나. 전에는 이런 문이 없었는데.', `MaleText_loc4`='是啊，奇怪。上次这扇门可没关。', `MaleText_loc5`='是的，怪了。之前這裡沒有這扇門的。', `MaleText_loc7`='Sí, qué raro. Esta puerta no estaba aquí antes.' WHERE `ID`=56698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='의식을 치루려면 우리가 가진 힘의 작은 부분 하나까지도 끌어내야 한다. 우린 많이 약해질테지.', `FemaleText_loc4`='仪式需要我们身上的一块碎片，并将带走我们大部分力量。我们将被大大地削弱。', `FemaleText_loc5`='儀式會消耗我們大部分的力量，因為它會抽取我們的每一分精力。我們將會不堪一擊。', `FemaleText_loc7`='El ritual nos desgastará mucho porque requiere una pieza de nuestro propio ser. Estaremos muy debilitados.' WHERE `ID`=56699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안에 뭔가 숨기고 있는 것 같죠?', `MaleText_loc4`='你们都觉得他们在隐藏着什么？', `MaleText_loc5`='你認為他們在裡面藏了些東西嗎?', `MaleText_loc7`='¿Creen que ocultan algo ahí dentro?' WHERE `ID`=56700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아내야지.', `MaleText_loc4`='我们会知道的。', `MaleText_loc5`='我們會查清楚的。', `MaleText_loc7`='Comprobémoslo.' WHERE `ID`=56701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조장에서 저런 소리가 나면 안 되는 것 같은데...', `MaleText_loc4`='我可不认为酒厂会发出那种声响……', `MaleText_loc5`='我不認為酒坊發出這種聲音是正常的...', `MaleText_loc7`='Creo que eso no es un ruido normal de cervecería...' WHERE `ID`=56702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 또다시 큰일을 맡기게 됐군.', `MaleText_loc4`='英雄们，这个重担又落到你们的肩上了。', `MaleText_loc5`='英雄們，這個重擔又得落在你們身上了。', `MaleText_loc7`='Héroes, esta responsabilidad recae en ustedes una vez más.' WHERE `ID`=56703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어... 아저씨들...', `FemaleText_loc4`='嗯……伙计们……', `FemaleText_loc5`='嗯...大家...', `FemaleText_loc7`='Esto... chicos...' WHERE `ID`=56704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있어라, 리 리. 내가 문 두드릴 때 방해하는 사람 싫어하는 거 알잖니.', `MaleText_loc4`='安静点，丽丽。你知道我可不喜欢在敲门的时候被人打扰。', `MaleText_loc5`='冷靜點，莉莉。你知道我最討厭敲門的時候被人打斷。', `MaleText_loc7`='Tranquila, Li Li. Sabes que odio que me interrumpan cuando estoy tocando una puerta.' WHERE `ID`=56705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첸 님! 거대한 호젠입니다!', `MaleText_loc4`='陈！那是只该死的大猢狲！', `MaleText_loc5`='老陳!是一隻巨大的猴人!', `MaleText_loc7`='¡Chen! ¡Es un pedazo de hozen!' WHERE `ID`=56706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 우끼 잔치 망쳐?', `MaleText_loc4`='谁敢打搅乌克的派对？！', `MaleText_loc5`='是誰闖入猴人的派對!?喔嗚嗚!', `MaleText_loc7`='¿Kién agua fiesta de Ook?' WHERE `ID`=56707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이다!', `MaleText_loc4`='来吧，猢狲！', `MaleText_loc5`='猴人來襲!', `MaleText_loc7`='¡Ataque hozen!' WHERE `ID`=56708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여, 집중의 눈동자를 손에 넣었습니까?', `MaleText_loc4`='英雄们，你们有没有拿到聚焦之虹？', `MaleText_loc5`='英雄，你們成功取得聚源虹膜了嗎?', `MaleText_loc7`='Héroes, ¿han conseguido el Iris de enfoque?' WHERE `ID`=56709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리게. 내가 술통에서 꺼내 주겠네.', `MaleText_loc4`='坚持住，我会把你们从桶里弄出来。', `MaleText_loc5`='撐著點，我會打破這些桶子把你弄出來。', `MaleText_loc7`='Esperen, los sacaré de esos barriles.' WHERE `ID`=56710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 칼렉고스 님.', `MaleText_loc4`='我们成功了，卡雷苟斯。', `MaleText_loc5`='我們成功了，卡雷苟斯。', `MaleText_loc7`='Lo hemos conseguido, Kalecgos.', `FemaleText_loc1`='네, 칼렉고스 님.', `FemaleText_loc4`='我们成功了，卡雷苟斯。', `FemaleText_loc5`='我們成功了，卡雷苟斯。', `FemaleText_loc7`='Lo hemos conseguido, Kalecgos.' WHERE `ID`=56711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호병들이여, 자리를 지켜라! 놈들을 통과시켜서는 안 된다!', `FemaleText_loc4`='坚守阵地，卫士们！别让他们通过！', `FemaleText_loc5`='堅守崗位，衛士們!別讓他們通過!', `FemaleText_loc7`='¡No cedan terreno, defensores! ¡Que no pasen!' WHERE `ID`=56712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음 단단히 먹어라! 적이 더 몰려온다!', `FemaleText_loc4`='坚持住！又有煞魔逼近了！', `FemaleText_loc5`='整備好自己!更多敵人接近了!', `FemaleText_loc7`='¡Preparaos! ¡Vienen más!' WHERE `ID`=56713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사들이여, 놈들을 황무지로 돌려보내라!', `FemaleText_loc4`='把他们送回荒废虚无的世界去，勇士们！', `FemaleText_loc5`='送他們回老家去，勇士們!', `FemaleText_loc7`='¡Enviadlos de vuelta a los abismos de su mundo, campeones!' WHERE `ID`=56714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 지금 항복하면, 온 사원이 무너질 것이다!', `FemaleText_loc4`='如果我们现在放弃，整个青龙寺就将陷落！', `FemaleText_loc5`='如果我們在此刻投降，整個帝國都會淪陷!', `FemaleText_loc7`='¡Si nos rendimos ahora, todo el templo caerá!' WHERE `ID`=56715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밀어붙여라, 수호병들이여!', `FemaleText_loc4`='向前推进，卫士们！', `FemaleText_loc5`='向前推進，衛士們!', `FemaleText_loc7`='¡Avanzad, defensores!' WHERE `ID`=56716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두들 견뎌내라. 한 걸음만 전진하면 된다.', `FemaleText_loc4`='大家坚持住。我们只需要再前进一步。', `FemaleText_loc5`='堅持住，大家。我們只需要往前推進一步。', `FemaleText_loc7`='Aguanten. Solo necesitamos dar un paso adelante.' WHERE `ID`=56717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포기하지 마라, 친구들!', `FemaleText_loc4`='不要放弃希望，同胞们！', `FemaleText_loc5`='別放棄希望，朋友們!', `FemaleText_loc7`='¡No perdáis la esperanza, amigos!' WHERE `ID`=56718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내일이면 모두들 우리의 활약을 노래할 것이다. 하지만 먼저 승리해야 한다.', `FemaleText_loc4`='明天，人们将为我们唱响赞歌，但前提是我们必须在今天取得胜利。', `FemaleText_loc5`='明天，他們將會歌詠我們，但前提是我們必須在此刻獲得勝利。', `FemaleText_loc7`='Mañana cantarán nuestras hazañas, pero solo si hoy salimos victoriosos.' WHERE `ID`=56719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s|1이;가; |cFF04FC32이세라|r의 돌마루에 거꾸러집니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s落向了|cFF04FC32伊瑟拉|r的平台！', `MaleText_loc5`='|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s往前掉落，快前往|cFF04FC32伊瑟拉的|r平台!', `MaleText_loc7`='|TInterfaceIconsinv_stave_2h_deathwingraiddw_d_01.blp:20|t¡%s cae en la plataforma de |cFF04FC32Ysera|h|r!' WHERE `ID`=56720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러분, 문을 여십시오! 제가 왔습니다. 맥주도 가져왔지요.', `MaleText_loc4`='风暴烈酒家人们，赶快开门吧！我带着啤酒回来啦。', `MaleText_loc5`='風暴烈酒族人們，開門啊!我回來了。而且我帶了啤酒!', `MaleText_loc7`='¡Cerveza de Trueno, abran! ¡Soy Chen! ¡Traigo cerveza!' WHERE `ID`=56721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 위상을 꿰뚫으려고 합니다. 막아야 합니다!', `MaleText_loc4`='%s开始穿刺守护巨龙！快阻止它！', `MaleText_loc5`='%s開始要刺穿守護巨龍!快阻止!', `MaleText_loc7`='¡%s comienza a empalar al Aspecto! ¡Detenlo!' WHERE `ID`=56722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 영혼에 아제로스 위상의 힘을 불어넣는 동안, 자네들은 데스윙의 병력으로부터 우릴 보호해야 하네.', `MaleText_loc4`='我们会将守护巨龙的力量灌注到巨龙之魂中，在此期间，你们必须保护我们。', `MaleText_loc5`='當我們用守護巨龍的力量強化巨龍之魂時，你們必須保護我們不受死亡之翼爪牙的攻擊。', `MaleText_loc7`='Deben protegernos de los ejércitos de Alamuerte mientras imbuimos el Alma con los poderes de Aspectos.' WHERE `ID`=56723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호할 준비가 되면 내게 말을 걸게.', `MaleText_loc4`='当你们准备好的时候就告诉我。', `MaleText_loc5`='等你們準備好，跟我說一聲。', `MaleText_loc7`='Hablen conmigo cuando estén listos.' WHERE `ID`=56724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='편히 쉬어라, 아이야.', `FemaleText_loc4`='安息吧，孩子。', `FemaleText_loc5`='安息吧，孩子。', `FemaleText_loc7`='Ve en paz, criatura.' WHERE `ID`=56725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 희생을 영원히 기억할 것이다.', `FemaleText_loc4`='你做出的牺牲是不会被遗忘的。', `FemaleText_loc5`='你的犧牲不會被輕易遺忘。', `FemaleText_loc7`='Tu sacrificio no será olvidado.' WHERE `ID`=56726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데스윙은 이 죗값을 치를 것이다.', `FemaleText_loc4`='死亡之翼会为此付出代价的。', `FemaleText_loc5`='死亡之翼得為此付出代價。', `FemaleText_loc7`='Alamuerte pagará por esto.' WHERE `ID`=56727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군! 날리스의 방어를 뚫고, 그녀의 마법을 역으로 이용해 공격하다니! 참으로 영리해.', `MaleText_loc4`='难以置信！极少有刺客能像你这样骗过纳莉丝的护卫，还使用她的魔法来对付她。', `MaleText_loc5`='太棒了!沒幾個刺客能解除納麗絲的保護措施，用她自己的魔法來對付她。', `MaleText_loc7`='¡Increíble! Pocos asesinos serían tan listos como para infiltrarse entre los celadores de Nalice y usar su magia contra ella.' WHERE `ID`=56728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도. 그러니 보석을 더 모으는 편이 좋겠어...', `MaleText_loc4`='也许吧。因为这个缘故，我们还需要更多的补给……', `MaleText_loc5`='或許吧。也因為這樣，我們需要收集更多物資...', `MaleText_loc7`='Quizás. Por eso, necesitamos reunir más suministros...' WHERE `ID`=56729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날리스는 패배를 자초했습니다. 나머진 그렇게 약하지 않을 겁니다.', `MaleText_loc4`='她的失败是自找的。剩下的可没那么好对付。', `MaleText_loc5`='她這是自取滅亡。其他目標不會這麼好搞定。', `MaleText_loc7`='Se ha dejado derrotar. Los demás no serán tan débiles.' WHERE `ID`=56730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초특급 대포로 순간이동하면 아래 비용이 소비됩니다:', `MaleText_loc4`='传送到大炮需要交纳：', `MaleText_loc5`='傳送到大砲旁邊需要花費:', `MaleText_loc7`='El teletransporte al cañón te costará:', `FemaleText_loc1`='초특급 대포로 순간이동하면 아래 비용이 소비됩니다:', `FemaleText_loc4`='传送到大炮需要交纳：', `FemaleText_loc5`='傳送到大砲旁邊需要花費:', `FemaleText_loc7`='El teletransporte al cañón te costará:' WHERE `ID`=56731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동하지 않아도 됩니다.', `MaleText_loc4`='我不需要传送。', `MaleText_loc5`='我不需要傳送。', `MaleText_loc7`='No necesito un teletransporte.', `FemaleText_loc1`='순간이동하지 않아도 돼요.', `FemaleText_loc4`='我不需要传送。', `FemaleText_loc5`='我不需要傳送。', `FemaleText_loc7`='No necesito un teletransporte.' WHERE `ID`=56732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원의 눈 속 집중의 눈동자를 사용하면, 용의 영혼에 담긴 마법의 힘을 하나로 집중할 수 있을 거요.', `MaleText_loc4`='永恒之眼里的聚焦之虹也许能让我们汇聚储藏在巨龙之魂里的魔法矩阵。', `MaleText_loc5`='永恆之眼的聚源虹膜也許能讓我們結合巨龍之魂裡面的魔法矩陣。', `MaleText_loc7`='Puede que el Iris de enfoque de El Ojo de la Eternidad nos permita unir la matriz mágica que contiene el Alma de dragón.' WHERE `ID`=56733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 성공하면 우리 일은 거의 끝난 셈이다. 행운을 빈다!', `MaleText_loc4`='若是你成功了，我们的工作就接近尾声了。祝好运，英雄！', `MaleText_loc5`='只要能成功，我們的工作就差不多了。祝你好運，英雄!', `MaleText_loc7`='Triunfa y casi habremos acabado nuestro trabajo. ¡Buena suerte!' WHERE `ID`=56734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정할 것 없다, 파라드. 다음 임무는... 거의 자살 임무에 가깝지.', `MaleText_loc4`='没必要担心，法拉德。下一个任务……和自杀也差不多了。', `MaleText_loc5`='不需要擔心，法拉德。下一個任務...幾乎可以說是自殺任務。', `MaleText_loc7`='No te preocupes, Fahrad. La próxima misión es... un tanto... suicida.' WHERE `ID`=56735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이자의 말을 믿지 마십시오. 그렇게까지 완벽할 순 없습니다.', `MaleText_loc4`='别相信他，王子殿下，他不值得信任。', `MaleText_loc5`='別相信這傢伙，殿下。沒有人能做到!', `MaleText_loc7`='No se fíe, alteza. Nadie es tan bueno.' WHERE `ID`=56736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위상들이여! 전력으로 영웅들을 도와주십시오.', `MaleText_loc4`='守护巨龙！请尽力帮助这些英雄。', `MaleText_loc5`='守護巨龍們!盡量協助這些英雄吧。', `MaleText_loc7`='¡Aspectos! Ayuden a los héroes tanto como puedan.' WHERE `ID`=56737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰러진 전우의 복수를! 계속 밀어붙이게!', `MaleText_loc4`='为逝者复仇！继续战斗！', `MaleText_loc5`='替死者復仇!繼續戰鬥!', `MaleText_loc7`='¡Vengad a los caídos! ¡Que siga la batalla!' WHERE `ID`=56738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 수습생이 또 내 딸과 함께 도망갔소.', `MaleText_loc4`='我的女儿又跟你的学徒跑了。', `MaleText_loc5`='你的學徒又把我的女兒拐跑了。', `MaleText_loc7`='Tu aprendiz se ha vuelto a escapar con mi hija.' WHERE `ID`=56739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러야 합니다... 고룡쉼터 사원이 무너져 버린다면... 모두... 끝장입니다...', `FemaleText_loc4`='你必须赶快……龙眠神殿……快倒塌了……没有希望了……', `FemaleText_loc5`='請你儘快...龍眠神殿快要陷落了...一切..都要完了...', `FemaleText_loc7`='Dense prisa. El Reposo del Dragón se derrumba mientras hablamos... Es... el fin...' WHERE `ID`=56740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙소, 자매들이여, 이젠 괜찮소.', `FemaleText_loc4`='谢谢，姐妹们，我重焕活力了。', `FemaleText_loc5`='謝謝，姊妹們。我好多了。', `FemaleText_loc7`='Gracias, hermanas, estoy renovada.' WHERE `ID`=56741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고대 신이 모습을 드러냈군요. 구렁에서 밀려오는 어둠의 물결이 사원을 덮쳐오고 있습니다. 위상들에게 시간을 벌어줘야 합니다.', `FemaleText_loc4`='上古之神现身了——黑暗之潮从他们撕开的裂口中涌出，直奔神殿而去。我们要为守护巨龙争取时间。', `FemaleText_loc5`='上古之神已經現身 - 祂們口中吐出了一股黑暗之潮，向神殿來襲。我們必須替守護巨龍爭取更多時間。', `FemaleText_loc7`='Los dioses antiguos se han mostrado; una ola de oscuridad se extiende desde sus enormes fauces hacia el templo. Debemos ganar tiempo para los Aspectos.' WHERE `ID`=56742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼굴 없는 장군, 존오즈와 요르사지는 지평선에 보이는 흉측한 괴물 구렁 속에서 적 군단을 지휘하고 있습니다.', `FemaleText_loc4`='在地平线的那边，两名无面者将军，佐诺兹和约萨希，指挥着一支邪恶的军团。', `FemaleText_loc5`='無面者的將領，松奧茲和尤沙吉，他們負責指揮在地平線另一端的怪物軍團。', `FemaleText_loc7`='Los generales ignotos, Zon’ozz y Yor’sahj, lideran las legiones enemigas desde las monstruosidades que se ven en el horizonte.' WHERE `ID`=56743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 살아남아 이 일을 마무리지으려면 반드시 놈들을 처치해야 합니다. 제 자매들 등에 타세요. 최대한 가까이 보내줄 겁니다!', `FemaleText_loc4`='要想活着终结这一切，我们就必须击败他们。借助我姐妹们的双翼，让她们带你们飞到尽可能近的地方！', `FemaleText_loc5`='如果你想活到最後，就必須擊殺他們。在我姊妹的翅膀上飛翔吧，她們會盡量飛到靠近他們的位置!', `FemaleText_loc7`='Hay que derribarlos si queremos sobrevivir para terminar con esto. Surquen los cielos sobre mis hermanas, ¡los transportarán tan cerca como puedan!' WHERE `ID`=56744;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 장군 하나가 남았습니다. 서두르셔야 합니다!', `FemaleText_loc4`='只剩下一名将军了。你们必须赶快！', `FemaleText_loc5`='還有一個將軍還活著。動作要快!', `FemaleText_loc7`='Solo queda un general. ¡Apresúrense!' WHERE `ID`=56745;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠의 물결이 잦아듭니다. 그대는 진정 전설 속의 영웅이 맞나 봅니다.', `FemaleText_loc4`='黑暗之潮退去了。你们果真是传说中的英雄。', `FemaleText_loc5`='黑暗之潮變弱了。看來你真的是傳說中的英雄。', `FemaleText_loc7`='El flujo de oscuridad amaina. Parece que realmente son los héroes de leyenda.' WHERE `ID`=56746;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위상들이 그대들을 기다리고 있습니다. 가십시오!', `FemaleText_loc4`='守护巨龙早就等着你们了。快去吧！', `FemaleText_loc5`='守護巨龍已經集結，正在等候你。快去吧!', `FemaleText_loc7`='Los Aspectos ya se han reunido y esperan su llegada. ¡Váyanse!' WHERE `ID`=56747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이모우를 쥬의 감시초소까지 굴리십시오!', `MaleText_loc4`='让易默滚回朱家堡！', `MaleText_loc5`='把易謀推往祝家守望站去!', `MaleText_loc7`='¡Haz rodar a Yi-Mo hasta la Atalaya de Zhu!', `FemaleText_loc1`='이모우를 쥬의 감시초소까지 굴리십시오!', `FemaleText_loc4`='让易默滚回朱家堡！', `FemaleText_loc5`='把易謀推往祝家守望站去!', `FemaleText_loc7`='¡Haz rodar a Yi-Mo hasta la Atalaya de Zhu!' WHERE `ID`=56748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연인들은 누구나 그러지요. 그 녀석은 착한 아이입니다.', `MaleText_loc4`='热恋中的情侣总是要谈情说爱的嘛。他是个好小伙儿。', `MaleText_loc5`='戀愛的人總是不由自主。他是個好孩子。', `MaleText_loc7`='Son cosas de enamorados. Es un buen chico.' WHERE `ID`=56749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 두십시오! 그 녀석은 원더브루 집안의 아이고, 내 딸은 골든드래프트 집안의 아이입니다. 내 딸을 당장 돌려보내지 않으면, 당분간 아무 일도 못할 줄 아십시오.', `MaleText_loc4`='我不要听！他是游酒家族的人，而她来自金酿家族。把我的女儿交出来，不然我就让你整整一个月都找不到活儿。', `MaleText_loc5`='我不要聽!他是蕩酒家的兒子，而她是金流家的女兒。把我的女兒送回來，否則我就讓你們一整個月都接不到活兒。', `MaleText_loc7`='¡Ni hablar! Es un Aguardiente y ella es una Cerveza Colérica. Devuélveme a mi hija o me aseguraré de que nadie te dé trabajo en un mes.' WHERE `ID`=56750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 이제 마나의 흐름을 재배열하고 용의 영혼을 제 비전 마력으로 채우겠습니다.', `MaleText_loc4`='干得好！我会重调魔法的涡流，并将我所有的奥术力量灌注到巨龙之魂中。', `MaleText_loc5`='做得好!我會重新排列法力的流向，用我全部的秘法能量填滿巨龍之魂。', `MaleText_loc7`='¡Bien hecho! Reajustaré el flujo de maná y llenaré el Alma de dragón con mi poder arcano.' WHERE `ID`=56751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 마력을 불어넣어 드리겠습니다. 적을 무찌르세요!', `MaleText_loc4`='我会赋予你们奥术的力量，摧毁敌人。', `MaleText_loc5`='我會用秘法替你充能，來轟炸你的敵人。', `MaleText_loc7`='Te imbuiré de energía arcana para que aniquiles a tus enemigos.' WHERE `ID`=56752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 데스윙의 몸이 분해되는 건가?', `MaleText_loc4`='他是不是……在解体？', `MaleText_loc5`='他...正在崩壞嗎?', `MaleText_loc7`='¿Se está... despedazando?' WHERE `ID`=56753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브와이크 액스 샤오크멕 조스 브라 즈으 쉬프 쿠오 게할라스 액스. 울그마, 아그 쿠암.', `MaleText_loc4`='Vwyq agth sshoq''meg N''Zoth vra zz shfk qwor ga''halahs agthu。Uulg''ma, ag qam。', `MaleText_loc5`='Vwyq agth sshoq''meg N''Zoth vra zz shfk qwor ga''halahs agthu. Uulg''ma, ag qam.', `MaleText_loc7`='Vwyq agth sshoq''meg N''Zoth vra zz shfk qwor ga''halahs agthu. Uulg''ma, ag qam.' WHERE `ID`=56754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 이 세계의 썩어빠진 시체들 위에 느조스의 뒤틀린 살점 깃발이 꿈틀거리며 펄럭이는구나. 천 년의 세월이 지나, 우리가 돌아왔다.', `MaleText_loc4`='恩佐斯这扭曲的血肉大旗终将再次飘扬在这个世界的尸体上空，猎猎作响。一千年后，我们终于回来了。', `MaleText_loc5`='恩若司扭曲的肉體旗幟又將再次在這個世界到處遍佈的屍體上飄揚。在億萬年之後，我們又再次回歸。', `MaleText_loc7`='De nuevo, los retorcidos tentáculos de N''Zoth gritan y rugen sobre el pútrido cadáver de este mundo. Milenios después, hemos regresado.' WHERE `ID`=56755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조브 슐와. 토크 프쉬 느조스!', `MaleText_loc4`='Zzof Shuul''wah。Thoq fssh N''Zoth！', `MaleText_loc5`='Zzof Shuul''wah. Thoq fssh N''Zoth!', `MaleText_loc7`='Zzof Shuul''wah. ¡Thoq fssh N''Zoth!' WHERE `ID`=56756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙 님에게 승리를! 느조스의 영광을 위하여!', `MaleText_loc4`='死亡之翼必胜。为了恩佐斯的荣耀！', `MaleText_loc5`='為死亡之翼而戰。恩若司萬歲!', `MaleText_loc7`='Victoria para Alamuerte. ¡Por la gloria de N''Zoth!' WHERE `ID`=56757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위 사람들은 모두 나를 좋아하는 척할 뿐이다.', `MaleText_loc4`='我周围的所有人都是假装喜欢我。', `MaleText_loc5`='我身邊的每個人都只是假裝喜歡我。', `MaleText_loc7`='Los que me rodean fingen que les agrado.', `FemaleText_loc1`='주위 사람들은 모두 나를 좋아하는 척할 뿐이야.', `FemaleText_loc4`='我周围的所有人都是假装喜欢我。', `FemaleText_loc5`='我身邊的每個人都只是假裝喜歡我。', `FemaleText_loc7`='Los que me rodean fingen que les agrado.' WHERE `ID`=56758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 방어구가 몸에 너무 꽉 끼나?', `MaleText_loc4`='这身铠甲对我来说是不是有点紧了？', `MaleText_loc5`='這盔甲在我身上會顯得很緊嗎?', `MaleText_loc7`='¿Crees que me aprieta mucho esta armadura?', `FemaleText_loc1`='이 방어구... 내 몸에 너무 꽉 끼나?', `FemaleText_loc4`='这身铠甲对我来说是不是有点紧了？', `FemaleText_loc5`='這盔甲在我身上會顯得很緊嗎?', `FemaleText_loc7`='¿Crees que me aprieta mucho esta armadura?' WHERE `ID`=56759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 알아... 내가 걱정하는 일이 일어나고 말 거야.', `MaleText_loc4`='果然，我最担心的事情终究还是发生了。', `MaleText_loc5`='我最害怕的東西當然會成真囉。', `MaleText_loc7`='Mis mayores temores se van a hacer realidad.', `FemaleText_loc1`='난 알아... 내가 걱정하는 일이 일어나고 말 거야.', `FemaleText_loc4`='果然，我最担心的事情终究还是发生了。', `FemaleText_loc5`='我最害怕的東西當然會成真囉。', `FemaleText_loc7`='Mis mayores temores se van a hacer realidad.' WHERE `ID`=56760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 사람들이 나에 대해 뭐라고 할까?', `MaleText_loc4`='人们会怎么说我？', `MaleText_loc5`='人們都怎麼說我?', `MaleText_loc7`='¿Qué dice la gente sobre mí?', `FemaleText_loc1`='사람들이 나에 대해 뭐라고 할까?', `FemaleText_loc4`='人们会怎么说我？', `FemaleText_loc5`='人們都怎麼說我?', `FemaleText_loc7`='¿Qué dice la gente sobre mí?' WHERE `ID`=56761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 속에서 계속 이상한 목소리가 들리는군. 걱정해야 할 일인가?', `MaleText_loc4`='总有邪恶的低语在我的脑海中盘旋。我是不是该为此担心？', `MaleText_loc5`='我老是在腦裡聽到聲音。我該感到擔心嗎?', `MaleText_loc7`='No dejo de oír voces en mi cabeza. ¿Debería preocuparme?', `FemaleText_loc1`='머리 속에서 계속 이상한 목소리가 들리네. 걱정해야 할 일일까?', `FemaleText_loc4`='总有邪恶的低语在我的脑海中盘旋。我是不是该为此担心？', `FemaleText_loc5`='我老是在腦裡聽到聲音。我該感到擔心嗎?', `FemaleText_loc7`='No dejo de oír voces en mi cabeza. ¿Debería preocuparme?' WHERE `ID`=56762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무것도 변하지 않을 거야.', `MaleText_loc4`='什么都没有改变。', `MaleText_loc5`='什麼都不會變的。', `MaleText_loc7`='Nunca cambiará nada.', `FemaleText_loc1`='아무것도 변하지 않을 거야.', `FemaleText_loc4`='什么都没有改变。', `FemaleText_loc5`='什麼都不會變的。', `FemaleText_loc7`='Nunca cambiará nada.' WHERE `ID`=56763;
