UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것을 위해... 너무 오랜 시간을 기다렸다...', `MaleText_loc4`='为了这一天……等待了那么久……', `MaleText_loc5`='等了...這麼的久...', `MaleText_loc7`='Haber esperado tanto... para esto.' WHERE `ID`=56765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 열심히 노력해야 하는 거지? 결국 아무 의미도 없을 텐데...', `MaleText_loc4`='为什么我要这么努力？到头来一点意义都没有……', `MaleText_loc5`='我何必這麼努力嘗試?到最後一切都沒有意義...', `MaleText_loc7`='¿Por qué pongo tanto esfuerzo? Al final todo es para nada...', `FemaleText_loc1`='왜 이렇게 열심히 노력해야 하는 거야? 결국에는 아무 의미도 없을 텐데...', `FemaleText_loc4`='为什么我要这么努力？到头来一点意义都没有……', `FemaleText_loc5`='我何必這麼努力嘗試?到最後一切都沒有意義...', `FemaleText_loc7`='¿Por qué pongo tanto esfuerzo? Al final todo es para nada...' WHERE `ID`=56766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 왜 늘 이렇게 외로운 거지? 역시... 혼자이기 때문일까?', `MaleText_loc4`='我为什么总感觉如此孤独？是因为……我孑然一身吗？', `MaleText_loc5`='為什麼我老是感到孤單?難道是因為...我很孤單?', `MaleText_loc7`='¿Por qué siempre me siento tan solo? ¿Será porque... estoy solo?', `FemaleText_loc1`='난 왜 늘 이렇게 외로운 거지? 역시... 혼자이기 때문일까?', `FemaleText_loc4`='我为什么总感觉如此孤独？是因为……我孑然一身吗？', `FemaleText_loc5`='為什麼我老是感到孤單?難道是因為...我很孤單?', `FemaleText_loc7`='¿Por qué siempre me siento tan sola? ¿Será porque... estoy sola?' WHERE `ID`=56767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가문은 벌써 몇 대 전부터 비취 숲에서 가장 뛰어난 양조사였네.$b$b저 추악한 방랑자 원더브루 가문과는 달라. 걔들이 만드는 건 촌구석 싸구려 술이라고.', `MaleText_loc4`='数代以来，我的家族一直是翡翠林最伟大的酒仙家族之一。$b$b我们跟那个卑鄙的旅行家族游酒可不一样。他们只会酿造村野劣酒。', `MaleText_loc5`='我們家族好幾代以來都是翠玉林最厲害的釀酒大師。$b$b不像蕩酒家那些四處旅行的骯髒傢伙，他們做的都是些下等人的酒。', `MaleText_loc7`='Mi familia ha dado los mejores maestros cerveceros de todo el Bosque de Jade durante generaciones.$b$bNo como esos repugnantes Pócima Errante. Bebidas de campesinos, eso es lo que hacen.' WHERE `ID`=56768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 왔다. 내가 가진 모든 힘을 쏟아 모든 가능성의 끈을 바로 여기, 바로 지금, 용의 영혼에 엮겠다. 앞으로 일어날 일은 절대로 되돌릴 수 없으리라.', `MaleText_loc4`='是时候了。我将使用全部的力量来控制巨龙之魂周围所有的时光线。我们过去的一切努力绝不能白费。', `MaleText_loc5`='時候到了。我會盡我全力在此束縛巨龍之魂的每一條時光之絲。這裡發生的一切絕對不會白費。', `MaleText_loc7`='Es la hora. Usaré todo mi poder para vincular cada hilo aquí y ahora en torno al Alma de dragón. Lo que ocurra nunca podrá deshacerse.' WHERE `ID`=56769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 몰아쳐라, 영웅들이여.', `MaleText_loc4`='发动进攻，英雄们。', `MaleText_loc5`='加強攻擊，英雄們。', `MaleText_loc7`='Ataquen con furia, héroes.' WHERE `ID`=56770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞에 있는 것은 위상의 보관함이다. 원하는 대로 가져가라. 너희에겐 그만한 자격이 있다.', `MaleText_loc4`='在你面前的就是我们守护巨龙的宝箱：挑选你的奖励吧，这是你应得的。', `MaleText_loc5`='你的前面就是守護巨龍的貯藏箱。拿走你想拿的東西吧，你獲得了這個權利。', `MaleText_loc7`='Ante ustedes se encuentra el Alijo de los Aspectos. Tomen todo lo que quieran, pues se han ganado el derecho.', `FemaleText_loc1`='앞에 있는 것은 위상의 보관함이다. 원하는 대로 가져가라. 너희에겐 그만한 자격이 있다.', `FemaleText_loc4`='在你面前的就是我们守护巨龙的宝箱：挑选你的奖励吧，这是你应得的。', `FemaleText_loc5`='你的前面就是守護巨龍的貯藏箱。拿走你想拿的東西吧，你獲得了這個權利。', `FemaleText_loc7`='Ante ustedes se encuentra el Alijo de los Aspectos. Tomen todo lo que quieran, pues se han ganado el derecho.' WHERE `ID`=56771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락은 내가 정화하마. 내 불에 너희가 피해를 입진 않을 거다.', `MaleText_loc4`='我会尽力净化一切堕落之物；我的烈焰不会伤害你们。', `MaleText_loc5`='我會盡我所能淨化腐化的力量，我的火焰不會傷害到你。', `MaleText_loc7`='Purificaré toda la corrupción que pueda. Mi fuego no les dañará.', `FemaleText_loc1`='타락은 내가 정화하마. 내 불에 너희가 피해를 입진 않을 거다.', `FemaleText_loc4`='我会尽力净化一切堕落之物；我的烈焰不会伤害你们。', `FemaleText_loc5`='我會盡我所能淨化腐化的力量，我的火焰不會傷害到你。', `FemaleText_loc7`='Purificaré toda la corrupción que pueda. Mi fuego no les dañará.' WHERE `ID`=56772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 잘했다. 내 심장의 불이 더할바 없는 순수함으로 빛나는구나. 불꽃 하나 빠짐없이 전부 쏟아내주지. 용의 영혼으로!', `MaleText_loc4`='干得好。我心中的火焰将迸发出无比纯净的光芒；每一束火花都将被引导至巨龙之魂中。', `MaleText_loc5`='做得很好。我心中的火焰正以無可比擬的純淨能量熾熱地燃燒著，我會把每一分都傳輸到巨龍之魂裡。', `MaleText_loc7`='Excelente trabajo. El fuego de mi corazón brilla con una pureza incomparable; canalizaré cada chispa al Alma de dragón.', `FemaleText_loc1`='정말 잘했다. 내 심장의 불이 더할바 없는 순수함으로 빛나는구나. 불꽃 하나 빠짐없이 전부 쏟아내주지. 용의 영혼으로!', `FemaleText_loc4`='干得好。我心中的火焰将迸发出无比纯净的光芒；每一束火花都将被引导至巨龙之魂中。', `FemaleText_loc5`='做得很好。我心中的火焰正以無可比擬的純淨能量熾熱地燃燒著，我會把每一分都傳輸到巨龍之魂裡。', `FemaleText_loc7`='Excelente trabajo. El fuego de mi corazón brilla con una pureza incomparable; canalizaré cada chispa al Alma de dragón.' WHERE `ID`=56773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 이성을 잃었군!', `MaleText_loc4`='他已经彻底疯了！', `MaleText_loc5`='他完全瘋了!', `MaleText_loc7`='¡Está completamente loco!', `FemaleText_loc1`='완전히 이성을 잃었군!', `FemaleText_loc4`='他已经彻底疯了！', `FemaleText_loc5`='他完全瘋了!', `FemaleText_loc7`='¡Está completamente loco!' WHERE `ID`=56774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 한걸음 다가섰구나. 이제 에메랄드의 꿈이 가진 미지의, 초자연적인 힘을 용의 영혼에 불어넣겠노라.', `MaleText_loc4`='我们又近了一步。我会将神秘莫测的翡翠梦境之力注入到巨龙之魂中。', `MaleText_loc5`='我們越來越接近了。我現在，將翡翠夢境超乎想像、未知的力量交給巨龍之魂。', `MaleText_loc7`='Ya queda menos. Ahora otorgaré al Alma de dragón el insondable y trascendente poder del Sueño Esmeralda.' WHERE `ID`=56775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 에메랄드의 꿈으로 너희를 인도하마. 전투가 너무 치열해지면, 안전한 그곳으로 이동해라.', `MaleText_loc4`='我会让你们离翡翠梦境更近一些。当战斗太过激烈的时候可以进入梦境寻求庇护。', `MaleText_loc5`='我會帶你到靠近翡翠夢境的地方。如果戰鬥太過激烈，可以在那裡喘口氣。', `MaleText_loc7`='Los acercaré al Sueño Esmeralda. Busquen cobijo en él cuando el combate sea demasiado intenso.' WHERE `ID`=56776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 분노는 정말 처음 보는군...', `MaleText_loc4`='如此……愤怒……我从未见过……', `MaleText_loc5`='我從未見過如此怒火...', `MaleText_loc7`='Nunca he visto... tanta... ira...' WHERE `ID`=56777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스켁 아그스 누크 느조스 와큐즈.', `MaleText_loc4`='Sk''tek agth nuq N''Zoth yyqzz。', `MaleText_loc5`='Sk''tek agth nuq N''Zoth yyqzz.', `MaleText_loc7`='Sk''tek agth nuq N''Zoth yyqzz.' WHERE `ID`=56778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 해골은 고통에 몸부림치는 느조스의 왕좌를 장식할 것이다.', `MaleText_loc4`='你们的头颅将装饰恩佐斯的扭曲王座。', `MaleText_loc5`='你們的頭顱相當適合拿來裝飾恩若司蠕動的王座。', `MaleText_loc7`='Sus calaveras adornarán el tortuoso trono de N''Zoth.' WHERE `ID`=56779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스케야그프 아가스 허크스 느조스 고나스.', `MaleText_loc4`='Sk''yahf agth huqth N''Zoth qornaus。', `MaleText_loc5`='Sk''yahf agth huqth N''Zoth qornaus.', `MaleText_loc7`='Sk''yahf agth huqth N''Zoth qornaus.' WHERE `ID`=56780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙이 마지막 대격변을 불러오려 한다. 에메랄드의 꿈마저 떨리는구나. 주문을 막으려면 모두 함께 놈을 공격해야 한다.', `MaleText_loc4`='死亡之翼正在引导最后的大灾变，连翡翠梦境都在颤抖。要想阻止他，我们必须联手进攻。', `MaleText_loc5`='死亡之翼正在召喚最終的災變，連翡翠夢境都為之震動。如果想要阻止他，我們必須一起進攻。', `MaleText_loc7`='Alamuerte está preparando el último cataclismo; hasta el Sueño Esmeralda tiembla. Si debemos detener el hechizo, lo haremos atacando juntos.' WHERE `ID`=56781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 영혼은 느조스의 끝없는 굶주림을 채워줄 것이다.', `MaleText_loc4`='你们的灵魂将成为恩佐斯口中的美餐！', `MaleText_loc5`='你們的靈魂將滿足恩若司無盡的飢渴。', `MaleText_loc7`='Sus almas saciarán la inagotable sed de N''Zoth.' WHERE `ID`=56782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스케울 아그스 보르즈 느조스 나그와프시.', `MaleText_loc4`='Sk''shuul agth vorzz N''Zoth naggwa''fssh。', `MaleText_loc5`='Sk''shuul agth vorzz N''Zoth naggwa''fssh.', `MaleText_loc7`='Sk''shuul agth vorzz N''Zoth naggwa''fssh.' WHERE `ID`=56783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 죽음은 느조스의 끝없는 영광을 찬미할 것이다.', `MaleText_loc4`='你们的死亡将歌颂恩佐斯无尽的荣耀。', `MaleText_loc5`='你們的死亡是在為恩若司無盡的榮耀而高唱。', `MaleText_loc7`='Sus muertes cantarán la gloria infinita de N''Zoth.' WHERE `ID`=56784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴카와스 언고브 느조스.', `MaleText_loc4`='Gul''kafh an''qov N''Zoth。', `MaleText_loc5`='Gul''kafh an''qov N''Zoth.', `MaleText_loc7`='Gul''kafh an''qov N''Zoth.' WHERE `ID`=56785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느조스의 심장 안을 응시하라.', `MaleText_loc4`='凝视恩佐斯的内心吧。', `MaleText_loc5`='注視恩若司的心。', `MaleText_loc7`='Contemplen el corazón de N''Zoth.' WHERE `ID`=56786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느조스 가 지크타그 일리스.', `MaleText_loc4`='N''Zoth ga zyqtahg iilth。', `MaleText_loc5`='N''Zoth ga zyqtahg iilth.', `MaleText_loc7`='N''Zoth ga zyqtahg iilth.' WHERE `ID`=56787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느조스의 의지가 너를 타락시킬 것이다.', `MaleText_loc4`='恩佐斯的意志将腐蚀你。', `MaleText_loc5`='恩若司的意志會腐化你們。', `MaleText_loc7`='La voluntad de N''Zoth los corrompe.' WHERE `ID`=56788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스카맥 야위픽 하크.', `MaleText_loc4`='Sk''magg yawifk hoq。', `MaleText_loc5`='Sk''magg yawifk hoq.', `MaleText_loc7`='Sk''magg yawifk hoq.' WHERE `ID`=56789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 고통은 나를 강하게 만든다.', `MaleText_loc4`='你们的苦难强化了我。', `MaleText_loc5`='你們的苦難使我變強。', `MaleText_loc7`='Su sufrimiento me fortalece.' WHERE `ID`=56790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가면을 구해줘서 고맙네, $n. 감사의 표시로, 자네의 평온을 바라는 마음과 함께 축복을 받아 주게.', `FemaleText_loc4`='谢谢你的面具，$n。请放心接受此祝福，以聊表我们的谢意。', `FemaleText_loc5`='面具的事多謝你了，$n。祝你平安，請收下這項祝福作為我們對你的感謝。', `FemaleText_loc7`='Gracias por las máscaras, $n. Ve en paz y llévate esta bendición como muestra de nuestro agradecimiento.' WHERE `ID`=56791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불쌍한 로. 시조들께 잘 보이려고 무던히 애썼는데... 우린 그저 집안의 반대를 피해 도망치는 것밖에는 다른 방법을 생각할 수 없었어요.', `FemaleText_loc4`='我可怜的罗。他是那么努力地去争取族长们的认可，这也是我们能够想到的唯一一个能避开家族恩怨的体面的解决办法。', `FemaleText_loc5`='我可憐的小樓。他是這麼努力地想贏得潘達族王的尊敬。這是我們唯一能想出來，跨越家族紛爭的正當解決方案。', `FemaleText_loc7`='Pobre Lo. Se esforzó mucho por ganarse el respeto de los pandriarcas. Era la única solución honorable que se nos ocurrió para solventar el odio de nuestras familias.' WHERE `ID`=56792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후우, 멋진 전투였습니다... 정말 영웅답더군요. 앞에 있는 리 리에게 가보십시오.', `MaleText_loc4`='打得好……真像个英雄。你该到前面去找丽丽了。', `MaleText_loc5`='打得好...很有英雄氣概。你們應該去前面找莉莉碰面。', `MaleText_loc7`='Buen combate... muy heroico. Deberían ir a ver a Li Li. Está más adelante.' WHERE `ID`=56793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후우, 이 정도면 싸울 만큼 싸운 것 같군요. 이제 여길 빠져나가 첸 님과 리 리를 만납시다.', `MaleText_loc4`='我觉得，这里的战斗应该都结束了。我们该出去和陈还有丽丽会合了。', `MaleText_loc5`='我猜該打的都已經打完了。我們走吧，去和老陳與莉莉會合。', `MaleText_loc7`='Creo que ya no es necesario seguir luchando. Salgamos de aquí y reunámonos con Chen y Li Li.' WHERE `ID`=56794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스큐야트 굴프그 하크.', `MaleText_loc4`='Sk''uuyat guulphg hoq。', `MaleText_loc5`='Sk''uuyat guulphg hoq.', `MaleText_loc7`='Sk''uuyat guulphg hoq.' WHERE `ID`=56795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸 삼촌이 기다리고 있어요. 가서 삼촌을 찾아보세요... 전 여기서 이 녀석을 놀리고 있을게요.', `FemaleText_loc4`='陈叔在前面等着呢。你去找他吧……我要戏弄一下这只不省人事的猴子。', `FemaleText_loc5`='老陳叔叔正在前面等。你們去找他...我留在這裡戲弄這隻昏迷的猴子。', `FemaleText_loc7`='El tío Chen está esperando más adelante. Ve a buscarlo... Yo me quedaré aquí burlándome de este mono inconsciente.' WHERE `ID`=56796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 끝난 것 같아요! 양조장 후문에 있는 멍청한 아저씨 둘을 만나러 가죠.', `FemaleText_loc4`='我想我们都搞定了！让我们去酿酒厂的后门和那两个呆子会合吧。', `FemaleText_loc5`='我想我們都搞定了!去釀酒廠的後門跟那兩個傢伙碰頭吧!', `FemaleText_loc7`='¡Creo que hemos terminado! Reunámonos con esos dos patanes en la entrada trasera de la cervecería.' WHERE `ID`=56797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 고뇌는 내게 힘이 되지.', `MaleText_loc4`='你们的痛苦支撑着我。', `MaleText_loc5`='我以你們的痛苦維生。', `MaleText_loc7`='Su agonía me sustenta.' WHERE `ID`=56798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스카센 이퀴니즈 호크.', `MaleText_loc4`='Sk''shgn eqnizz hoq。', `MaleText_loc5`='Sk''shgn eqnizz hoq.', `MaleText_loc7`='Sk''shgn eqnizz hoq.' WHERE `ID`=56799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 두려움이 나를 움직이지.', `MaleText_loc4`='你们的恐惧驱使着我。', `MaleText_loc5`='你們的恐懼是我的動力。', `MaleText_loc7`='Su miedo me guía.' WHERE `ID`=56800;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너 정말 약하구나? 너 그렇게 뻗어 있으니까 정말 우습다. 엉뚱한 맘 먹지 마. 여기 내 친구가 맥주통 또 던진다.', `FemaleText_loc4`='现在狠不起来了，对吧？这就对了。你躺在地上的样子看上去傻透了。别逼我让$p再往你身上扔酒桶。', `FemaleText_loc5`='現在可強硬不起來了吧?沒錯，你躺在地上的樣子蠢斃了。別逼我叫我朋友拿更多桶子砸你喔。', `FemaleText_loc7`='Ahora no eres tan duro, ¿eh? Eso. Pareces un bobo ahí tirado en el suelo. No nos obligues a lanzarte más barriles.' WHERE `ID`=56801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카그티쉬 마 우니쉬. 아욱크 쉬그출 브와후운! 하이은 이긱쉬 푸쿠와티 객 우 카악스 슈울!', `MaleText_loc4`='Ak''agthshi ma uhnish，ak''uq shg''cul vwahuhn！H''iwn iggksh Phquathi gag OOU KAAXTH SHUUL！', `MaleText_loc5`='Ak''agthshi ma uhnish, ak''uq shg''cul vwahuhn! H''iwn iggksh Phquathi gag OOU KAAXTH SHUUL!', `MaleText_loc7`='¡Ak''agthshi ma uhnish, ak''uq shg''cul vwahuhn! ¡H''iwn iggksh Phquathi gag OOU KAAXTH SHUUL!' WHERE `ID`=56802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 군사는 셀 수 없을 정도로 많고, 그 힘은 상상조차 할 수 없을 만큼 강력하다! 파괴자에 맞서는 자들은 모두 천 번의 죽음을 맞으리라!', `MaleText_loc4`='我们的数量无穷无尽，我们的力量超乎想象！所有敢于和灭世者作对的人，都将被千刀万剐！', `MaleText_loc5`='我們的數量是無盡的，我們的力量無法計量!任何想要跟毀滅者做對的人都會死上千百次!', `MaleText_loc7`='¡Nuestras filas son innumerables; nuestro poder no tiene límites! ¡Los que se opongan al Destructor sufrirán mil muertes!' WHERE `ID`=56803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴스 퀴요툭 샨마 예글루 셰아스야! 하인 릴스!', `MaleText_loc4`='Iilth qi''uothk shn''ma yeh''glu Shath''Yar！H''IWN IILTH！', `MaleText_loc5`='Iilth qi''uothk shn''ma yeh''glu Shath''Yar! H''IWN IILTH!', `MaleText_loc7`='¡Iilth qi''uothk shn''ma yeh''glu Shath''Yar! ¡H''IWN IILTH!' WHERE `ID`=56804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들은 모두 고대 신의 피에 빠져 죽을 것이다! 너희들 모두!', `MaleText_loc4`='古神之血将淹没你们！淹没你们所有人！', `MaleText_loc5`='你們會溺斃在上古之神的血中!全部的人!', `MaleText_loc7`='¡Se ahogarán en la sangre de los dioses antiguos! ¡TODOS!' WHERE `ID`=56805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이즈. 슈울와! 슥우스글 유게즈 요흐글리 일스!', `MaleText_loc4`='Ez，Shuul''wah！Sk''woth''gl yu''gaz yoh''ghyl iilth！', `MaleText_loc5`='Ez, Shuul''wah! Sk''woth''gl yu''gaz yoh''ghyl iilth!', `MaleText_loc7`='¡Ez, Shuul''wah! ¡Sk''woth''gl yu''gaz yoh''ghyl iilth!' WHERE `ID`=56806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷이 맥주에 절어서 좀 짜야겠군. 먼저 가서 머드머그를 찾게나.', `MaleText_loc4`='我要把衣服里的酒水拧掉一些。你们继续前进，去找泥盏。', `MaleText_loc5`='我要去把衣服裡的啤酒擰出來。你儘管去吧，去找泥杯。', `MaleText_loc7`='Voy a escurrirme la cerveza de la ropa. Adelántate y busca a Caolín.' WHERE `ID`=56807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 데스윙 님이시여! 당신의 충실한 하인이 실망을 안겨드렸습니다!', `MaleText_loc4`='哦，死亡之翼！您忠实的仆人辜负了您！', `MaleText_loc5`='噢，死亡之翼!你忠誠的僕人失敗了!', `MaleText_loc7`='¡Oh, Alamuerte! ¡Tu fiel siervo te ha fallado!' WHERE `ID`=56808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스크야프 파이팔라프 피마그!', `MaleText_loc4`='Sk''yahf qi''plahf PH''MAGG！', `MaleText_loc5`='Sk''yahf qi''plahf PH''MAGG!', `MaleText_loc7`='¡Sk''yahf qi''plahf PH''MAGG!' WHERE `ID`=56809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 네 영혼이 끝없는 고통을 깨닫게 될 것이다!', `MaleText_loc4`='你的灵魂将遭受无尽的折磨！', `MaleText_loc5`='你們的靈魂會感受到無窮的折磨!', `MaleText_loc7`='¡Tu alma sufrirá un TORMENTO ETERNO!' WHERE `ID`=56810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이은 자익스 슈울와, 프쿠타이!', `MaleText_loc4`='H''iwn zaix Shuul''wah，PHQUATHI！', `MaleText_loc5`='H''iwn zaix Shuul''wah, PHQUATHI!', `MaleText_loc7`='¡H''iwn zaix Shuul''wah, PHQUATHI!' WHERE `ID`=56811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴자 데스윙 님을 찬양하라!', `MaleText_loc4`='赞美伟大的灭世者，死亡之翼！', `MaleText_loc5`='全部的人都讚美死亡之翼 - 毀滅者!', `MaleText_loc7`='¡Elogien a Alamuerte, EL DESTRUCTOR!' WHERE `ID`=56812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 이 정도면 된 것 같네. 양조장 후문에서 나머지 둘을 만나세.', `MaleText_loc4`='我想我们今天造成的破坏已经够多了。我们去酒厂后门跟他们两人会合吧。', `MaleText_loc5`='我想我們今天已經造成夠多災難了。我們去釀造廠的後門跟另外兩個人碰頭吧。', `MaleText_loc7`='Creo que ya hemos provocado suficiente daño por hoy. Vamos a reunirnos con los otros dos en la entrada trasera de la cervecería.' WHERE `ID`=56813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스쿨 안지그 크브삭프 케쉬가, 악 티작 아그수!', `MaleText_loc4`='Shkul an''zig qvsakf KSSH''GA，ag''THYZAK agthu！', `MaleText_loc5`='Shkul an''zig qvsakf KSSH''GA, ag''THYZAK agthu!', `MaleText_loc7`='¡Shkul an''zig qvsakf KSSH''GA, ag''THYZAK agthu!' WHERE `ID`=56814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 음울한 깊은 곳으로부터, 우리는 이 세상을 되찾을 것이다!', `MaleText_loc4`='我们冲出最黑暗的深渊，将要夺回这个世界！', `MaleText_loc5`='從最寒冷的深淵中，我們歸來奪回這個世界!', `MaleText_loc7`='Desde las profundidades más sombrías, ¡RECLAMAMOS este mundo!' WHERE `ID`=56815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카이스 아그시그 야아그파 일쿠아아스 온그!', `MaleText_loc4`='KYTH ag''xig yyg''far IIQAATH ONGG！', `MaleText_loc5`='KYTH ag''xig yyg''far IIQAATH ONGG!', `MaleText_loc7`='¡KYTH ag''xig yyg''far IIQAATH ONGG!' WHERE `ID`=56816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어떻게 이 저주받은 대지에서 쏟아져나오는지 봐라!', `MaleText_loc4`='见证我们从破碎的大地下涌出的那一刻吧！', `MaleText_loc5`='看看我們是怎樣從詛咒的大地中出現!', `MaleText_loc7`='¡CONTEMPLEN cómo salimos de la TIERRA MALDITA!' WHERE `ID`=56817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우울 이위훅 하이윈!', `MaleText_loc4`='UULL lwhuk H''IWN！', `MaleText_loc5`='UULL lwhuk H''IWN!', `MaleText_loc7`='¡UULL lwhuk H''IWN!' WHERE `ID`=56818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 모든 것을 집어삼킬 것이다!', `MaleText_loc4`='让黑暗吞噬一切！', `MaleText_loc5`='黑暗會吞噬一切!', `MaleText_loc7`='¡La OSCURIDAD lo devora TODO!' WHERE `ID`=56819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우트크그후 엑우훅 일스!', `MaleText_loc4`='Awtgsshu LWHUK iilth！', `MaleText_loc5`='Awtgsshu LWHUK iilth!', `MaleText_loc7`='¡Awtgsshu LWHUK iilth!' WHERE `ID`=56820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락이 너를 집어삼키리라!', `MaleText_loc4`='让腐蚀吞噬你！', `MaleText_loc5`='腐化會吞噬你們!', `MaleText_loc7`='¡La corrupción los CONSUME!' WHERE `ID`=56821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분들이... 동의하셨다고요?! 멋지군요! 정말 감사합니다! 그분들의 축복이 있다면, 우린 이 땅에서 가장 행복한 판다렌이 될 거예요.', `MaleText_loc4`='他们……他们同意了？！天呐！真是太感谢你了！只要有了他们的祝福，我们就是这世界上最最幸福的熊猫人！', `MaleText_loc5`='他們...他們同意了?!太棒了!真是感激不盡!有了他們的祝福，我們會成為這片土地上最快樂的熊貓人!', `MaleText_loc7`='Han... ¡¿Han accedido?! ¡Es fantástico! ¡Muchísimas gracias! Con su bendición seremos los pandaren más felices del mundo.' WHERE `ID`=56822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 영웅이시여, 정말 감사드려요! 저희에게 정말 멋진 선물을 주셨어요!', `FemaleText_loc4`='谢谢你，英雄！你给了我们一份极其贵重的礼物！', `FemaleText_loc5`='喔謝謝你，英雄!你給了我們最大的禮物!', `FemaleText_loc7`='Muchas gracias, $ghéroe:heroína;. Nos has dado una gran bendición.' WHERE `ID`=56823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하세요! 이미 돌아가신 분들이지만, 시조님들은 여전히 무시무시하세요.', `MaleText_loc4`='小心点！他们或许是死了，可这些族长还是很危险的。', `MaleText_loc5`='小心!他們或許死了，但潘達族王還是很危險。', `MaleText_loc7`='¡Cuidado! Puede que estén muertos, pero los pandriarcas siguen siendo peligrosos.' WHERE `ID`=56824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤에 대해 알아낸 게 하나 있단다. 놈들은 우리의 약점을 어떻게 이용할지 알고 있어.', `FemaleText_loc4`='我从煞魔身上了解到的一点就是，他们知道如何利用我们自身的弱点。', `FemaleText_loc5`='我從煞身上學到一件事。他們知道怎麼吞食我們的弱點。', `FemaleText_loc7`='Si hay algo que he aprendido de los sha, es que saben aprovecharse de nuestras debilidades.' WHERE `ID`=56825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤도 한 가지 문제에 대해서는 옳다네.$B$B우리의 가장 큰 적은 대개 우리 자신이야.$B$B나도 나 자신이 이렇게 강력한 적이 아니었으면 좋았을 거라고 생각한다네.', `FemaleText_loc4`='煞魔在有一点上是对的。$B$B我们最大的敌人通常就是我们自身。$B$B我只希望我自己不会是个难缠的对手。', `FemaleText_loc5`='煞說對了一件事。$B$B我們最大的敵人經常是我們自己。$B$B我只希望我不是個非常難纏的敵人。', `FemaleText_loc7`='Los sha tienen razón en una cosa.$b$bA menudo somos nuestros peores enemigos.$b$bOjalá yo no fuera un oponente tan formidable.' WHERE `ID`=56826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이건 현실이다. 저 교활한 붉은용군단 녀석들이 날 죽이려 들었다. 놈들이 어떤 족속인지 이제 너도 알겠지.', `MaleText_loc4`='你的眼睛没有欺骗你。奸诈的红龙军团试图杀掉我。我希望你能看清他们的真面目。', `MaleText_loc5`='你雙眼所見的就是真相。卑鄙的紅龍軍團想要殺死我。希望你現在能認清他們的真面目。', `MaleText_loc7`='Tus ojos no te engañan. Los traidores del Vuelo Rojo querían aniquilarme. Espero que ahora los veas como son de verdad.' WHERE `ID`=56829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 이상한 기척이 느껴지는데...', `MaleText_loc4`='我闻到了什么味道……', `MaleText_loc5`='我聞到一種味道...', `MaleText_loc7`='Huelo algo...' WHERE `ID`=56830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 용사여?', `FemaleText_loc4`='你有什么事吗，英雄？', `FemaleText_loc5`='什麼事情啊，英雄?', `FemaleText_loc7`='¿Sí, $ghéroe:heroína;?' WHERE `ID`=56831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 청동용군단의 일원이니 다음에 무슨 일이 일어날지 아실 겁니다! 그냥 넘기고 바로 행동으로 들어가게 해주시면 안 될까요?', `MaleText_loc4`='你是青铜龙军团的一员，你知道接下来会发生什么！你就不能让我们直接开始实际行动吗？', `MaleText_loc5`='你是屬於青銅龍軍團的，你知道接下來會發生什麼!你能直接把我們跳到真正熱血刺激的時間點上嗎?', `MaleText_loc7`='Eres del Vuelo Bronce, ¡ya sabes qué va a pasar! ¿Puedes llevarnos directamente a la acción?', `FemaleText_loc1`='당신은 청동용군단의 일원이니 다음에 무슨 일이 일어날지 아실 겁니다! 그냥 넘기고 바로 행동으로 들어가게 해주시면 안 될까요?', `FemaleText_loc4`='你是青铜龙军团的一员，你知道接下来会发生什么！你就不能让我们直接开始实际行动吗？', `FemaleText_loc5`='你是屬於青銅龍軍團的，你知道接下來會發生什麼!你能直接把我們跳到真正熱血刺激的時間點上嗎?', `FemaleText_loc7`='Eres del Vuelo Bronce, ¡ya sabes qué va a pasar! ¿Puedes llevarnos directamente a la acción?' WHERE `ID`=56832;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 짓을 하고도 자비를 바라진 않겠지.', `FemaleText_loc4`='犯下了此等罪行，你休想得到宽恕。', `FemaleText_loc5`='做這樣的事情，就別想乞求憐憫了。', `FemaleText_loc7`='No pidas piedad después de tal atrevimiento.' WHERE `ID`=56833;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보 노릇을 하고 싶나 본데, 그럼 생긴 것도 바보 같아야지?', `FemaleText_loc4`='如果你们想扮小丑，就要扮得像一点儿。', `FemaleText_loc5`='要扮演小丑的話，扮相要跟得上哦。', `FemaleText_loc7`='Si intentan hacerse los locos, quizás también lo sean.' WHERE `ID`=56834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 임무에서 살아남는다면... 충분히 보람을 느끼게 해주지.', `MaleText_loc4`='如果你可以活着完成任务……我会付给你等值的报酬。', `MaleText_loc5`='如果你能活著回來，我保證你值回票價。', `MaleText_loc7`='Si sobrevives... te aseguro que habrá valido la pena.' WHERE `ID`=56835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 필멸자여. 네가 찾는 물건은 이제 껍질 속에 있지 않다. 바로 여기에... 두 발로 서 있지.', `MaleText_loc4`='没错，凡人！你寻找的东西如今不再沉睡在蛋壳里。我就活生生地站在这里。', `MaleText_loc5`='沒錯，凡人。你們追尋的目標不再沉睡於蛋殼之中。我就在這裡，如假包換。', `MaleText_loc7`='Así es, mortal. El tesoro que buscas ya no duerme en un cascarón. Aquí me tienes: de carne y hueso.' WHERE `ID`=56836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 붉은용군단의 전리품 따위가 아니다. 결코 돌아가지 않을 것이다.', `MaleText_loc4`='我不是什么红龙伟大事迹的活证，我可不会回去。', `MaleText_loc5`='我可不是讓紅龍掛在牆上的戰利品，我絕對不會回去。', `MaleText_loc7`='No soy ningún trofeo para la vitrina de algún dragón Rojo y nunca volveré.' WHERE `ID`=56837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 놀랄 것 없다! 우리 용족은 알 속에 있을 때에도 의식을 가지고 있지. 알 속에서 난 그 모든 음모를 들었다. 내가 포로 신세라는 것도.', `MaleText_loc4`='别这么惊讶！我们龙族即使在蛋壳里也是有意识的。在成长过程中，我听到的全是诡计和阴谋。我生来就是个囚徒。', `MaleText_loc5`='不用那麼吃驚!我們龍族在蛋殼裡就有了意識。長大時，我都聽得到那些陰謀計畫。我本來一出生就是俘虜。', `MaleText_loc7`='¡No te sorprendas! Los dragones somos conscientes, incluso dentro del huevo. Mientras crecía, podía oír las conspiraciones y los planes. Nací para ser un prisionero.' WHERE `ID`=56838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 난 유일무이한 존재다! 아버지의 타락에서 자유로운 단 하나의 검은용이지. 그리고 앞으로도, 자유로울 것이다.', `MaleText_loc4`='可我是族群的最后一员了！凡人。作为仅存的一条没有受到父亲堕落污染的黑龙，我要保持我的自由。', `MaleText_loc5`='但我是獨一無二的!一隻不受我父親腐化影響的黑龍。我打算就這樣繼續保有我的自由。', `MaleText_loc7`='¡Pero soy único! Un dragón negro libre de la deshonra de la corrupción de mi padre. Y así permaneceré: libre.' WHERE `ID`=56839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신기하구나. 어떻게 그 많은 경비병의 눈을 피했지? 유령처럼 조용히 숨어들다니. 그 능력은... 마음에 드는군. 얘기 좀 하지.', `MaleText_loc4`='但是，你躲开了我所有的守卫，像个幽灵一样的潜入了这里。这让我觉得……你还有点用处。我们聊聊吧。', `MaleText_loc5`='你居然能夠躲過我所有的警衛。像鬼魂一樣神出鬼沒。這顯出了你的...價值。我們好好談談吧。', `MaleText_loc7`='Conseguiste eludir a todos mis guardias. Te infiltraste como un fantasma. Podrías serme... útil. Vamos a hablar.' WHERE `ID`=56840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 찾던 포로를 알아보지 못하겠나?', `MaleText_loc4`='你不认得你以前的囚徒了吗？', `MaleText_loc5`='你不認識之前的俘虜了嗎?', `MaleText_loc7`='¿No reconoces a tu antiguo prisionero?' WHERE `ID`=56841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다. 이자가 붉은용군단에 내 뜻을 전했으면 한다.', `MaleText_loc4`='不。我想让他给红龙军团传句话回去。', `MaleText_loc5`='不。我要他給紅龍軍團帶個口信。', `MaleText_loc7`='No. Quiero que entregue un mensaje al Vuelo Rojo.' WHERE `ID`=56842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 전해라. 난 아버지의 광기에서 자유로우며, 너희 손아귀에서도 자유로울 거라고. 날 홀로 내버려 둬라. 이것이 내 처음이자 마지막 경고다.', `MaleText_loc4`='告诉他们，我是自由的。我没有受到父亲疯狂的影响，也不会成为红龙的囚徒。别来打扰我：这是我第一次也是唯一的警告。', `MaleText_loc5`='告訴他們我並沒有受制於我父親的瘋狂，我也不會受制於他們。不要想掌控我，這是我最初也是唯一的警告。', `MaleText_loc7`='Diles que me libré de la locura de mi padre y que me libraré de ellos también. Quiero que me dejen en paz: este será mi primer y único aviso.' WHERE `ID`=56843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그놈들이 오히려 날 두려워할 것이야! 데리고 나가!', `MaleText_loc4`='死亡之翼的爪牙应该会害怕我。让他滚出这里。', `MaleText_loc5`='死亡之翼的爪牙只會恐懼我。帶他下去。', `MaleText_loc7`='Los esbirros de Alamuerte deberían temerme. Sácalo de aquí.' WHERE `ID`=56844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 파라드?', `MaleText_loc4`='嗯，法拉德？', `MaleText_loc5`='還有，法拉德?', `MaleText_loc7`='Y, ¿Fahrad?' WHERE `ID`=56845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리를 부러뜨려라.', `MaleText_loc4`='打断他的腿。', `MaleText_loc5`='弄斷他的腿。', `MaleText_loc7`='Rómpele las piernas.' WHERE `ID`=56846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자 이제, 새로운 친구여. 할 얘기가 많은데...', `MaleText_loc4`='好吧，我的新朋友。我们还有不少事要聊。', `MaleText_loc5`='好啦，我的新朋友。我們有正事要談。', `MaleText_loc7`='Y ahora, camarada. Tenemos mucho de qué hablar.' WHERE `ID`=56847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저하, 장원 바로 바깥에 있는 동굴에서 이 야수가 주변을 염탐하고 있었습니다.', `MaleText_loc4`='殿下，我们在庄园附近的洞穴里抓住了这头鬼鬼祟祟的野兽。', `MaleText_loc5`='殿下，我們在莊園外面的山洞抓到這鬼鬼祟祟的傢伙。', `MaleText_loc7`='Su alteza, hemos cazado a esta bestia husmeando en las cuevas fuera del recinto.' WHERE `ID`=56848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님, 처형해 버릴까요?', `MaleText_loc4`='我们要处决他吗，王子殿下？', `MaleText_loc5`='要處決他嗎，王子殿下?', `MaleText_loc7`='¿Lo ejecutamos, mi príncipe?' WHERE `ID`=56849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 저하?', `MaleText_loc4`='殿下？', `MaleText_loc5`='殿下?', `MaleText_loc7`='¿Sí, señor?' WHERE `ID`=56850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥새야, 포기하지 마! 날 데리러 와!', `MaleText_loc4`='别放弃，雷鸟！回来找我！', `MaleText_loc5`='別放棄，雷鳥們!回來我身邊!', `MaleText_loc7`='¡No se rindan, pájaros de trueno! ¡Vuelvan por mí!' WHERE `ID`=56853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 느껴진다... 이 땅에 드리웠던 검은 그림자가 사라진 것 같구나! 죽었어! 내 아버지가 세상을 떠났다!', `MaleText_loc4`='我能感觉到……笼罩大地的阴影消失了。死了！我的父亲死了！', `MaleText_loc5`='我感覺到...似乎有一股黑暗的陰影從地面散去。死了!我父親死了!', `MaleText_loc7`='Puedo sentirlo... Como si una oscura sombra se hubiera disipado de la tierra. ¡Mi padre está muerto!' WHERE `ID`=56854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 너는 보상을 받았다. 그러나 없애야 할 용이 하나 더 남았다.', `MaleText_loc4`='勇士，请收下这件奖励。但我们还要对付最后一条龙。', `MaleText_loc5`='勇士，你已經得到獎勵。但是我們還需要殺死最後的一頭龍。', `MaleText_loc7`='Valiente, tienes tu recompensa. Pero tenemos que matar a un último dragón.' WHERE `ID`=56855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파라드! 바로 네 얘길 하고 있었는데. 그 누구보다도 꼭꼭 숨어 있었던... 마지막 검은용 말이다.', `MaleText_loc4`='法拉德！我说的就是你。你就是最后那条黑龙。比其他任何一条龙藏得都要深。', `MaleText_loc5`='法拉德!我才剛說到你呢。最後一頭黑龍。藏得比其他任何一頭龍都要深。', `MaleText_loc7`='¡Fahrad! Justo hablaba de ti. El último dragón negro. El que mejor escondido estaba de todos ellos.' WHERE `ID`=56856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미로운 무기를 사용하는군... 꽤 센 것 같은데.', `MaleText_loc4`='你的武器很特别……很强大。', `MaleText_loc5`='你用的武器很有趣...好強的力量。', `MaleText_loc7`='Llevas curiosas armas... tanto poder.' WHERE `ID`=56857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 넌 내가 아직 알 속에 있을 때 구해줬지. 너에게 목숨을 빚졌다.', `MaleText_loc4`='是的。你在我还是一只龙蛋的时候救下了我，我欠你一条命。', `MaleText_loc5`='是的。是你把還在蛋裡面的我救了出來，我欠你一命。', `MaleText_loc7`='Sí. Me rescataste cuando aún estaba en el cascarón y te debo la vida.' WHERE `ID`=56858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 너도 검은용이다. 그리고 다른 형제 자매와 마찬가지로 타락을 품고 있지.', `MaleText_loc4`='但你是一条黑龙。我所有兄弟姐妹所受到的腐蚀也影响着你。', `MaleText_loc5`='但你是頭黑龍。你跟我其他的兄弟姊妹們一樣受到了腐化。', `MaleText_loc7`='Pero eres un dragón Negro. Y compartes la corrupción de todos mis hermanos y hermanas.' WHERE `ID`=56859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부인하는 건가? 어두운 환상들을? 네 머릿속의 목소리를?', `MaleText_loc4`='你敢否认吗？那些黑暗的幻象？那些你脑中的黑暗之声？', `MaleText_loc5`='你否認嗎?黑暗的影像?還有你腦中的聲音?', `MaleText_loc7`='¿Lo niegas? ¿Las visiones oscuras? ¿Las voces en tu cabeza?' WHERE `ID`=56860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 지금은 무슨 얘길 하느냐, 파라드? 네 어둠의 주인들이 뭐라고 속삭이느냐?', `MaleText_loc4`='他们在和你说什么，法拉德？你的黑暗主人在低语着什么？', `MaleText_loc5`='現在你聽到了什麼，法拉德?你的黑暗主人說了什麼?', `MaleText_loc7`='¿Y qué te dicen ahora, Fahrad? ¿Qué te susurran tus maestros oscuros?' WHERE `ID`=56861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 날 통제할 순 없어! 붉은용군단은 상상도 못 할 거다. 자기들이 알에 한 실험이 어떤 존재를 이 세상에 풀어놓았는지!', `MaleText_loc4`='我绝不会被控制！红龙军团在拿我的蛋做实验时根本不知道他们自己释放出了什么。', `MaleText_loc5`='我永遠不要被控制!紅龍軍團在對我的蛋做實驗時，他們想像不到我未來的能耐。', `MaleText_loc7`='¡Nunca me controlarán! El Vuelo Rojo no tiene ni idea de lo que liberó cuando experimentó conmigo.' WHERE `ID`=56862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 지금 공격해라! 새로 얻은 힘으로 놈을 끝장내라.', `MaleText_loc4`='英雄——攻击！使用你新获得的力量去消灭他。', `MaleText_loc5`='英雄，快攻擊!使用你新的力量，終結他。', `MaleText_loc7`='Valiente, ¡ataca ahora! Utiliza tu nuevo poder para acabar con él.' WHERE `ID`=56863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났다, 친구여. 내가 아는 한, 이제 내가 유일한 검은용이다.', `MaleText_loc4`='都结束了，朋友。据我所知，我是这个世界上仅存的黑龙了。', `MaleText_loc5`='完成了，朋友。據我所知，我是唯一僅存的黑龍。', `MaleText_loc7`='Se acabó. Hasta donde yo sé, soy el último dragón negro.' WHERE `ID`=56864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자의 새로운 시대가 밝았다. 너 같은 영웅들이 이끄는 새로운 시대가.', `MaleText_loc4`='凡人的新时代开始了，你这样的英雄是这个时代的先锋。', `MaleText_loc5`='凡人的時代來臨了，而像你這樣的英雄正是先鋒。', `MaleText_loc7`='Amanece una nueva era para los mortales, y los héroes como tú forman parte de la vanguardia.' WHERE `ID`=56865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이제... 모습을 감춰야겠다.', `MaleText_loc4`='我必须离开了——暂时消失。', `MaleText_loc5`='我得走了。消失不見。', `MaleText_loc7`='Ahora debo irme; desaparecer.' WHERE `ID`=56866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다시 만날지도 모르지. 그때, 우리가 같은 편이었으면 좋겠군...', `MaleText_loc4`='也许我们有朝一日会再次相遇。但愿届时我们还能站在同一阵线……', `MaleText_loc5`='也許我們會再碰面。希望到時候我們不是敵人。', `MaleText_loc7`='Quizás nos volvamos a encontrar. Espero que estemos del mismo lado...' WHERE `ID`=56867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼애애애애애!', `MaleText_loc4`='不——！', `MaleText_loc5`='不!', `MaleText_loc7`='¡Nooooo!' WHERE `ID`=56868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 준비된 것 같군.', `MaleText_loc4`='你看来已经准备好了。', `MaleText_loc5`='看起來你已經準備好了。', `MaleText_loc7`='Parece que estás $gpreparado:preparada;.' WHERE `ID`=56869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님, 이 원반에 서 계십시오. 칼렉고스가 오고 있습니다!', `FemaleText_loc4`='站到这个圆台上，$p。卡雷苟斯过来了！', `FemaleText_loc5`='站在這個圓盤上，$p。卡雷苟斯來了!', `FemaleText_loc7`='Colócate encima de este disco, $p. ¡Kalecgos se acerca!' WHERE `ID`=56870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자님, 어서 이곳을 떠야 합니다. 붉은용이 일을 끝내러 돌아올지 모릅니다.', `MaleText_loc4`='我的王子，我们应该离开这儿，他们也许会回来继续攻击你。', `MaleText_loc5`='王子殿下，我們最好離開這裡，免得他們回頭找上我們。', `MaleText_loc7`='Mi príncipe, deberíamos salir de aquí, por si vuelven a terminar el trabajo.' WHERE `ID`=56871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저하, 저는 저하에게 제 정체를 숨기려고 한 적이 없습니다!', `MaleText_loc4`='殿下。我从来没有向您隐瞒过我的身份。', `MaleText_loc5`='殿下。我從來沒有對你隱瞞過任何事情。', `MaleText_loc7`='Su alteza. Nunca he intentado ocultarle lo que soy.' WHERE `ID`=56872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건... 그렇지 않습니다!', `MaleText_loc4`='这——不是真的！', `MaleText_loc5`='這...這不是真的!', `MaleText_loc7`='¡Eso no es cierto!' WHERE `ID`=56873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아닙니다! 전 그 목소리를 통제합니다. 그들은 절 돕습니다!', `MaleText_loc4`='不，不！我能控制那些声音。他们只是来帮我的。', `MaleText_loc5`='不，不!我控制得住那些聲音。他們會幫助我。', `MaleText_loc7`='¡No, no! Yo controlo las voces. Están ahí para ayudarme.' WHERE `ID`=56874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽이라고... 저하를 지금 죽이라고 합니다... 아아, 어째서 그러셨습니까? 어째서 그들을 화나게 하셨습니까?', `MaleText_loc4`='杀……他们要我现在就杀掉你……哦，你为什么要故意激怒他们？', `MaleText_loc5`='殺...他們要我現在就殺死你...噢，你為什麼一定要激怒他們?', `MaleText_loc7`='Matar... Quieren que te mate ahora... Oh, ¿por qué has tenido que enfurecerlas?' WHERE `ID`=56875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은... 통제하기가 너무 어려워!', `MaleText_loc4`='事实证明你真是太难控制了！', `MaleText_loc5`='你實在太難以控制了!', `MaleText_loc7`='¡Has demostrado ser muy difícil de controlar!' WHERE `ID`=56876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\inv_weapon_shortblade_45.blp:20|t%s|1이;가; |cFF9900CC|Hspell:109887|h[비전력이 깃든 무기]|h|r를 시전합니다! 날리스의 공격을 피하십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_weapon_shortblade_45.blp:20|t%s开始施放|cFF9900CC|Hspell:109887|h[奥能灌注武器]|h|r！躲开她的攻击！', `FemaleText_loc5`='|TInterface\\Icons\\inv_weapon_shortblade_45.blp:20|t%s開始施展|cFF9900CC|Hspell:109887|h[秘法灌注武器]|h|r!避開她的攻擊!', `FemaleText_loc7`='|TInterfaceIconsinv_weapon_shortblade_45.blp:20|t¡%s comienza a lanzar |cFF9900CC|Hspell:109887|h[Arma Arcana imbuida]|h|r! ¡Evita su ataque!' WHERE `ID`=56878;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\ability_warrior_riposte:20|t%s|1이;가; |cFF9900CC|Hspell:109893|h[비전력이 깃든 방어구]|h|r를 시전합니다! 날리스의 약점을 노출시키십시오!', `FemaleText_loc4`='|TInterface\\Icons\\ability_warrior_riposte:20|t%s开始施放|cFF9900CC|Hspell:109893|h[奥能灌注护甲]|h|r！快打破她的护甲！', `FemaleText_loc5`='|TInterface\\Icons\\ability_warrior_riposte:20|t%s開始施展|cFF9900CC|Hspell:109893|h[秘法灌注護甲]|h|r!快破掉她的護甲!', `FemaleText_loc7`='|TInterfaceIconsability_warrior_riposte:20|t¡%s comienza a lanzar |cFF9900CC|Hspell:109893|h[Armadura Arcana imbuida]|h|r! ¡Quítale la armadura!' WHERE `ID`=56879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s|1이;가; |cFFFF0000|Hspell:109807|h[비전 파괴]|h|r를 시전합니다! 기둥을 작동시켜 그녀를 막으십시오!', `FemaleText_loc4`='|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s开始施放|cFFFF0000|Hspell:109807|h[奥术毁灭]|h|r！快激活柱子来阻止她！', `FemaleText_loc5`='|TInterface\\Icons\\spell_arcane_arcaneresilience.blp:20|t%s開始施展|cFFFF0000|Hspell:109807|h[秘法毀滅]|h|r!啟動柱子來阻止她!', `FemaleText_loc7`='|TInterfaceIconsspell_arcane_arcaneresilience.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:109807|h[Destrucción Arcana]|h|r! ¡Activa los pilares para detenerla!' WHERE `ID`=56880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되셨습니까? 저는 준비 다 됐습니다. 이 요마 놈들을 진흙으로 만들어버릴 겁니다.$b$b단지... 제 덩치가 그렇게 큰 것도 아니고, 또 겁도 쉽게 먹고 그래서 말입니다. 그런데 당신은 $c 아닙니까. 그러니까 저... 저 좀 지켜주실 거죠, 네?', `MaleText_loc4`='你准备好了吗？我准备好了。我很想把那个畜生打得落花流水！$b$b只是……我并非好斗的人，我很容易受惊。你是这里唯一的$c。你会……你会保护我的，对吗？', `MaleText_loc5`='你準備好了嗎?我準備好了。我一定要在那東西身上打幾個洞。$b$b我...好吧，我算不上什麼打手。而且我真的很膽小。你是個$c。你...你會保護我的，對吧?', `MaleText_loc7`='¿Todo preparado? Yo estoy listo. Pienso convertir a ese bicho en un charco.$b$bSolo que... bueno, no soy ningún matón y me asusto fácilmente. Tienes más experiencia con estas cosas. Tú me... tú me protegerás, ¿verdad?' WHERE `ID`=56881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 이제 저 요마 놈들을 뭉개버립시다!', `MaleText_loc4`='很好！让我们痛扁这个水鬼吧！', `MaleText_loc5`='好了!來痛扁那個水壞蛋!', `MaleText_loc7`='¡De acuerdo! ¡Vamos a aplastar a esa alimaña de agua!' WHERE `ID`=56882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이놈은 생각했던 것보다도 좀 더 크네요.$b$b술을 마셔서 그런 것 같지 않아요? 술을 많이 마시면 뚱뚱해진다고 알고 있거든요, 첸 삼촌같이 말이죠. 그런데 키가 커질 거라는 생각은 안 해봤네요.$b$b어느 쪽이 됐든, 저 혼자 이놈들을 상대할 순 없어요.', `FemaleText_loc4`='这家伙的块头比我想象得要大一点。$b$b你觉得这是因为啤酒喝多了？我很清楚喝太多啤酒会让你长胖，就像陈叔那样，但是我不认为喝酒能让你长高。$b$b总之，我觉得我一个人恐怕搞不定他。', `FemaleText_loc5`='這傢伙比我想像的大了些。$b$b你覺得是因為喝了啤酒的關係嗎?我知道喝太多啤酒會讓你變胖，就像老陳叔叔一樣，但我沒想到還能讓你變高。$b$b無論如何，我不覺得我能單挑這個傢伙。', `FemaleText_loc7`='Este tipo es más grande de lo que imaginaba.$b$b¿Crees que es por la cerveza que bebe? Sé que tomar mucha cerveza engorda, como al tío Chen, pero no sabía que te hacía más alto.$b$bSea como sea, no creo que pueda yo sola con este tipo.' WHERE `ID`=56883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 이번 기회에 우리가 맥주통 던지는 바보들이 될 수도 있겠어요!', `FemaleText_loc4`='很好！也许这一次，我们可以成为扔木桶的一方了！', `FemaleText_loc5`='很好!也許這一次，可以輪到「我們」丟桶子!', `FemaleText_loc7`='¡Bien! ¡Puede que esta vez seamos nosotros los abusones que lanzan barriles!' WHERE `ID`=56884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 양조장 안에서 무슨 일이 일어나는 건가? 아무도 여기를 지키지 않았나? 양조사들은 어디 있는 거지?$b$b내 가족은 어디에 있지?...$b$b모두 어디론가 가버린 게 틀림없군. 만약 그들이 이곳에 있었다면 이 난장판을 청소하고 있을 것 아니겠나! 지금 당장은 그 일이 나와 자네 손에 달린 것 같군. 준비됐나?', `MaleText_loc4`='这座酒厂里到底出什么事了？这里没人打理了吗？酿酒师们都去哪了？$b$b我的家人呢……？$b$b他们一定去了别的什么地方。如果他们在这儿，一定会好好收拾这里的！看起来现在只能由我俩来做了，$n。你准备好了吗？', `MaleText_loc5`='這釀酒廠裡是發生什麼事!?這地方都沒人管了嗎?釀酒師都跑哪去了?$b$b我的家人呢...?$b$b他們一定跑去某個地方了。如果他們在這裡，他們就會處理掉這一團混亂!但目前，看來這工作得由你和我來做了，$n。你準備好了嗎?', `MaleText_loc7`='¡¿Qué está sucediendo en esta cervecería?! ¿Nadie se ha ocupado de este lugar? ¿Dónde están los cerveceros?$b$b¿Dónde está mi familia...?$b$bDeben de haberse marchado a algún sitio. ¡Si estuvieran aquí, estarían limpiando este desastre! De momento, parece que nos toca a ti y a mí, $n. ¿Estás $glisto:lista;?' WHERE `ID`=56885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트!', `MaleText_loc4`='风暴烈酒！', `MaleText_loc5`='風暴烈酒!', `MaleText_loc7`='¡Cerveza de Trueno!' WHERE `ID`=56886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 멈추지 마십시오.$B$B아직 게임 시간이 남아 있습니다!', `MaleText_loc4`='不要停。$B$B你还有时间！', `MaleText_loc5`='不要停啊。$B$B你還有時間可以繼續玩!', `MaleText_loc7`='No pares ahora.$B$B¡Aún tienes tiempo de juego!', `FemaleText_loc1`='지금 멈추지 마세요.$B$B아직 게임 시간이 남아 있어요!', `FemaleText_loc4`='不要停。$B$B你还有时间！', `FemaleText_loc5`='不要停啊。$B$B你還有時間可以繼續玩!', `FemaleText_loc7`='No pares ahora.$B$B¡Aún tienes tiempo de juego!' WHERE `ID`=56887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오, 머드머그. 어서 갑시다.', `MaleText_loc4`='冷静点，泥盏。出发。', `MaleText_loc5`='冷靜點，泥杯。我們走吧。', `MaleText_loc7`='Cálmate, Caolín. Vámonos.', `FemaleText_loc1`='진정하세요, 머드머그. 어서 가요.', `FemaleText_loc4`='冷静点，泥盏。出发。', `FemaleText_loc5`='冷靜點，泥杯。我們走吧。', `FemaleText_loc7`='Cálmate, Caolín. Vámonos.' WHERE `ID`=56888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 도와드리겠습니다.', `MaleText_loc4`='我会帮忙的。', `MaleText_loc5`='我會幫忙。', `MaleText_loc7`='Yo te ayudaré.', `FemaleText_loc1`='제가 도와드리겠습니다.', `FemaleText_loc4`='我会帮忙的。', `FemaleText_loc5`='我會幫忙。', `FemaleText_loc7`='Yo te ayudaré.' WHERE `ID`=56889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작합시다, 첸 님.', `MaleText_loc4`='我们开始吧，陈。', `MaleText_loc5`='讓我們上吧，老陳。', `MaleText_loc7`='Vamos allá, Chen.', `FemaleText_loc1`='시작하시죠, 첸 님.', `FemaleText_loc4`='我们开始吧，陈。', `FemaleText_loc5`='讓我們上吧，老陳。', `FemaleText_loc7`='Vamos allá, Chen.' WHERE `ID`=56890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게임 하는 곳에서 벗어나주십시오.', `MaleText_loc4`='请离开游戏场地。', `MaleText_loc5`='請不要擅入遊戲場地!', `MaleText_loc7`='Permanece fuera de la zona de juego.', `FemaleText_loc1`='게임 하는 곳에서 벗어나주세요.', `FemaleText_loc4`='请离开游戏场地。', `FemaleText_loc5`='請不要擅入遊戲場地!', `FemaleText_loc7`='Permanece fuera de la zona de juego.' WHERE `ID`=56891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 저지해라! 궁수를 보호해라!', `MaleText_loc4`='阻击他们！保护弓箭手！', `MaleText_loc5`='擋住他們!保護弓箭手!', `MaleText_loc7`='¡Aguántenlos! ¡Protejan a los arqueros!' WHERE `ID`=56892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 희생해, 용의 영혼을 원래 있던 시간으로 돌려놓았다.', `MaleText_loc4`='由于我失去了力量，巨龙之魂已经回到了原本的时空。', `MaleText_loc5`='失去我的力量後，巨龍之魂會逐漸回歸到原有的狀態。', `MaleText_loc7`='Con la pérdida de mi poder, el Alma de dragón ha vuelto a su lugar original en el tiempo.' WHERE `ID`=56893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄 나가신다!', `MaleText_loc4`='要爆炸啦！', `MaleText_loc5`='給我...爆吧!', `MaleText_loc7`='¡Allá va el BUM!' WHERE `ID`=56894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='암살자군! 그 조그만 새끼용의 사주를 받았나? 오너라, 도적이여. 한바탕 놀아 보자.', `FemaleText_loc4`='一个刺客！是那条小龙崽子派你来追杀我的吗？来吧，潜行者。让我们一决高下。', `FemaleText_loc5`='一個刺客!那隻小幼龍派你來殺我?來吧，盜賊，咱們來玩玩。', `FemaleText_loc7`='¡$gUn asesino:Una asesina;! ¿Te ha enviado ese minúsculo vástago? Ven, $gpícaro:pícara;. Bailemos.' WHERE `ID`=56895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내게도 비장의 무기가 몇 개 있지, 도적이여.', `FemaleText_loc4`='我自己也有一些小秘密，潜行者。', `FemaleText_loc5`='我也有些自己的秘密，盜賊。', `FemaleText_loc7`='Tengo mis secretos, pícaro.' WHERE `ID`=56896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이... 더 필요해!', `FemaleText_loc4`='我……我需要更多的时间！', `FemaleText_loc5`='我...我需要更多時間!', `FemaleText_loc7`='¡Ne... necesito más tiempo!' WHERE `ID`=56897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 끝날 리가 없어. 적어도 나는! 나는 살아남은 자다.', `FemaleText_loc4`='这不是我要的结局。我还没到谢幕的时候呢。我才是最后的幸存者。', `FemaleText_loc5`='不是這樣結束的。我不該是這樣的。我是個存活者。', `FemaleText_loc7`='Así no es cómo acaba. No para mí. Soy una sobreviviente.' WHERE `ID`=56898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조각난 세상에 매달리는 꼴이라니... 너도 이렇게 될 날이... 곧 올 것이다...', `FemaleText_loc4`='你不过是个抱残守缺的可怜虫……你的末日……很快就会降临……', `FemaleText_loc5`='你們緊抓著一個破碎的世界...你們的時間到了...很快就到了...', `FemaleText_loc7`='Te aferras a un mundo destrozado... Pronto... llegará tu hora.' WHERE `ID`=56899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 행운의 여신이 내 편이라고!', `MaleText_loc4`='我今晚真是鸿运当头！', `MaleText_loc5`='幸運女神今晚是在我這邊的!', `MaleText_loc7`='¡La suerte está de mi lado esta noche!', `FemaleText_loc1`='오늘은 행운의 여신이 내 편이라고!', `FemaleText_loc4`='我今晚真是鸿运当头！', `FemaleText_loc5`='幸運女神今晚是在我這邊的!', `FemaleText_loc7`='¡La suerte está de mi lado esta noche!' WHERE `ID`=56900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨 평생 판다렌 많이 못 봤다. 그래도 한 가지는 안다. 판다렌은 슬픈 민족 아니다.$B$B그런데 여기를 좀 봐라! 다들 슬픔에 빠져 부루퉁해 있다.$B$B노래랑 춤은 어디로 간 거냐? 산더미 같은 음식은?$B$B술은 또 어딜 갔고?!', `MaleText_loc4`='肯肯这辈子见过几个熊猫人。他会告诉你——他们一点也不悲伤。$B$B现在，看看这地方！到处都是满脸哀苦、无精打采的熊猫人。$B$B欢歌热舞去哪儿了？堆积如山的美食又去哪儿了？$B$B干杯狂饮的场面又去哪儿了啊，伙计？！', `MaleText_loc5`='肯·肯曾經遇過幾個熊貓人。讓肯·肯告訴你:他們不是悲傷的種族。$b$b現在看看這個地方!大家都是一副傷心欲絕、失魂落魄的模樣。$B$B過去的載歌載舞呢?成山的食物呢?$B$B還有那香醇美酒呢，老兄?!', `MaleText_loc7`='Ken-Ken konoció a los pandaren hace tiempo. Yo dice una kosa: ellos no eran tristes.$B$B¡Pero ahora mira este lugar! Todos tristones.$B$B¿Ké fue de las kanciones y los bailes? ¿Y de los montones de manduka?$B$B¡¿Y las cervezas?!' WHERE `ID`=56901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에잇, 모 아니면 도다!', `MaleText_loc4`='双倍加注！', `MaleText_loc5`='賠二倍或賠光光!', `MaleText_loc7`='¡Doble o nada!', `FemaleText_loc1`='에잇, 모 아니면 도다!', `FemaleText_loc4`='双倍加注！', `FemaleText_loc5`='賠二倍或賠光光!', `FemaleText_loc7`='¡Doble o nada!' WHERE `ID`=56902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주사위 신이여, 자비를...', `MaleText_loc4`='两点……', `MaleText_loc5`='蛇的眼睛...', `MaleText_loc7`='Ojos de serpiente...', `FemaleText_loc1`='주사위 신이여, 자비를...', `FemaleText_loc4`='两点……', `FemaleText_loc5`='蛇的眼睛...', `FemaleText_loc7`='Ojos de serpiente...' WHERE `ID`=56903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메이 도와야 한다.$B$B컨컨 왕슬픈 판다렌 위로할 방법 찾을 거다.', `MaleText_loc4`='你应该帮帮明。$B$B肯肯在想办法鼓舞这些超级悲伤的家伙。', `MaleText_loc5`='你應該去幫小美。$B$B肯·肯試著想辦法鼓勵這些悲哀至極的傢伙。', `MaleText_loc7`='Tú tiene ke ayudar a Mei.$B$BKen-Ken intenta pensar una manera de animar a estos tristones.' WHERE `ID`=56904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌 슬프니까 컨컨도 우울하다.', `MaleText_loc4`='看着这些熊猫人如此悲伤，肯肯也快变成悲伤的猢狲了。', `MaleText_loc5`='這麼多傷心的熊貓讓肯·肯變成傷心的猴人。', `MaleText_loc7`='Todos estos pandas tristes hacen a Ken-Ken un hozen triste.' WHERE `ID`=56905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 느려터진 멍멍이야!', `MaleText_loc4`='懒狗！', `MaleText_loc5`='懶惰的笨蛋!', `MaleText_loc7`='¡Vagos inútiles!' WHERE `ID`=56906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 좀 움직여!', `MaleText_loc4`='抓紧点！', `MaleText_loc5`='快點動作!', `MaleText_loc7`='¡Adelante!', `FemaleText_loc1`='빨리 좀 움직여!', `FemaleText_loc4`='抓紧点！', `FemaleText_loc5`='快點動作!', `FemaleText_loc7`='¡Adelante!' WHERE `ID`=56907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고양이도 너보단 경비를 잘 선다, 이놈아!', `MaleText_loc4`='论起当守卫，连猫都比你们称职！', `MaleText_loc5`='我見過貓都能比你們當更好的警衛!', `MaleText_loc7`='¡He visto gatos hacer de guardia mejor que tú!' WHERE `ID`=56908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐 양탄자로 만들어 버리는 게 낫겠군!', `MaleText_loc4`='你的皮很合适做地毯！', `MaleText_loc5`='你的皮拿來做毯子還不錯!', `MaleText_loc7`='¡No matarías ni el tiempo!' WHERE `ID`=56909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치겠군. 한 발자국 걸을 때마다 킁킁거리니...', `MaleText_loc4`='你已经把城里的每个角落都嗅遍了！', `MaleText_loc5`='你已經聞過這座城市的每一吋土地。', `MaleText_loc7`='Rastreen cada rincón de esta ciudad.', `FemaleText_loc1`='미치겠군. 한 발자국 걸을 때마다 킁킁거리니...', `FemaleText_loc4`='你已经把城里的每个角落都嗅遍了！', `FemaleText_loc5`='你已經聞過這座城市的每一吋土地。', `FemaleText_loc7`='Rastreen cada rincón de esta ciudad.' WHERE `ID`=56910;
