UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨어 있는 놈을 찾아내!', `MaleText_loc4`='追踪他们的气味！', `MaleText_loc5`='找出他們!', `MaleText_loc7`='¡Encontradlos!', `FemaleText_loc1`='숨어 있는 놈을 찾아내!', `FemaleText_loc4`='追踪他们的气味！', `FemaleText_loc5`='找出他們!', `FemaleText_loc7`='¡Encontradlos!' WHERE `ID`=56913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전력 보관 장치가 과부하되기 시작합니다. 물러서십시오!', `MaleText_loc4`='奥能存储单元开始过载了。退后！', `MaleText_loc5`='秘法倉庫單位開始超載了。退後!', `MaleText_loc7`='La unidad de almacenamiento Arcana empieza a sobrecargarse. ¡Atrás!' WHERE `ID`=56914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종이 재충전되었습니다! 종을 울려 주위의 적을 약화시키십시오!', `MaleText_loc4`='钟的力量恢复了！快敲响它，以削弱附近的敌人！', `MaleText_loc5`='鐘的能量重新充滿了!敲打它來削弱附近的敵人!', `MaleText_loc7`='¡La campana está recargada! ¡Golpéala para despertar a los enemigos cercanos!', `FemaleText_loc1`='종이 재충전되었습니다! 종을 울려 주위의 적을 약화시키십시오!', `FemaleText_loc4`='钟的力量恢复了！快敲响它，以削弱附近的敌人！', `FemaleText_loc5`='鐘的能量重新充滿了!敲打它來削弱附近的敵人!', `FemaleText_loc7`='¡La campana está recargada! ¡Golpéala para despertar a los enemigos cercanos!' WHERE `ID`=56915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 많이 죽지 마세요', `MaleText_loc4`='别死个没完', `MaleText_loc5`='不要這麼容易死', `MaleText_loc7`='NO TE MUERAS TANTO', `FemaleText_loc1`='너무 많이 죽지 마세요', `FemaleText_loc4`='别死个没完', `FemaleText_loc5`='不要這麼容易死', `FemaleText_loc7`='NO TE MUERAS TANTO' WHERE `ID`=56916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만나서 반갑소, 여행자여. 이 강가에서 우리 편인 호드의 얼굴을 보리라곤 생각도 못했다오.', `MaleText_loc4`='你好，旅行者。没想到在这片海滩上还能看到一个友善的部落人士。', `MaleText_loc5`='歡迎，旅人。我沒想到會在這個地方見到友善的部落臉孔。', `MaleText_loc7`='Saludos, viajante. No esperaba ver una cara amiga de la Horda en estas costas.' WHERE `ID`=56917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 멀리 떨어진 북쪽에서 빛의 부름이 느껴진다오. 하지만 이곳...$b$b이곳에는 몇 세대 동안 빛이라는 게 없었다오.', `MaleText_loc4`='我感受到了圣光的召唤，就在遥远的北方。但这个地方……$b$b数代以来都未曾听说过圣光的存在。', `MaleText_loc5`='我在遙遠的北地感覺到聖光的呼喚。但是這裡...$b$b這裡不見到聖光已經有很多、很多個世代了。', `MaleText_loc7`='Siento la llamada de la Luz a lo lejos, al norte de aquí. Pero este lugar...$b$bNo ha conocido la luz durante muchas, muchas generaciones.' WHERE `ID`=56918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $p 님이시군요! 이 "태양길잡이"라는 사람들은 은둔 고수는 아닐지도 모르겠지만, 전투 방식은 지금까지 봐왔던 것과는 전혀 달라요.$b$b한번 배워봐야겠어요.', `MaleText_loc4`='啊，$p！这些“烈日行者”可能并非隐秘大师，可我却从未见过他们这样的战斗方式。$b$b我要向他们学习。', `MaleText_loc5`='啊，$p!這些「日行者」或許不是隱居的宗師，但他們的戰鬥技巧是我從來也不曾見過的。$b$b我想要向他們學習。', `MaleText_loc7`='¡Ah, $p! Puede que estos "caminasol" no sean el maestro oculto, pero su estilo de lucha no se parece a nada que haya visto antes.$b$bQuiero aprender de ellos.' WHERE `ID`=56919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라.', `MaleText_loc4`='走开。', `MaleText_loc5`='滾吧。', `MaleText_loc7`='Desaparece.' WHERE `ID`=56920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 불에 날아드는 나방과도 같이, 레자가 본 빛의 환영을 따라서 이곳으로 왔네.', `MaleText_loc4`='我们追随着莱莎对光明的预见来到此地，如同飞蛾扑火。', `MaleText_loc5`='我們像飛蛾撲火一樣地跟著麗紗的幻象走，來到這個地方。', `MaleText_loc7`='Seguimos las visiones de la luz de Leza hasta este lugar como las polillas a una lumbre.' WHERE `ID`=56921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에는 얼라이언스가, 동쪽과 서쪽에는 모구가, 북쪽에는 절벽이 있네. 우리는 사방으로 에워싸여 있는 걸세.', `MaleText_loc4`='我们的南面是联盟，东面和西面有魔古族，北面是悬崖。这还真是四面楚歌啊。', `MaleText_loc5`='南方有聯盟，東西方有魔古，北方又是懸崖。我們可真是腹背受敵啊。', `MaleText_loc7`='La Alianza al sur, mogu al este y el oeste, y acantilados al norte. Estamos acorralados por todos los flancos.' WHERE `ID`=56922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지긋지긋하고 끈적한 더위보다는 차라리 노스렌드의 살을 에는 추위가 낫겠네. 나무들이 우리를 질식시키려는 건 아닌가 싶을 정도야.', `MaleText_loc4`='相比于这里可怕的湿热，我比较喜欢诺森德刺骨的寒风。这里好像连树木都想要闷死我们。', `MaleText_loc5`='北裂境的刺骨霜寒和這片土地駭人的悶熱相比，似乎還比較可親。這些樹簡直就像是要讓我們窒息似的。', `MaleText_loc7`='Casi prefiero el frío helador de Rasganorte a este calor sofocante. Es como si los propios árboles trataran de asfixiarnos.' WHERE `ID`=56923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데즈코 님은 훌륭한 족장님이십니다. 그분을 따라서 온 이 땅에서 어떻게 살아남을지 걱정이 되기 시작했지만 말입니다.', `MaleText_loc4`='德兹科是一位伟大的酋长，是他把我们带到了这里，但我开始有点怀疑我们能否在这片土地上存活下来。', `MaleText_loc5`='戴斯可是個偉大的酋長，但我開始懷疑他能帶領我們在這片土地上存活到什麼程度。', `MaleText_loc7`='Dezco es un gran jefe, aunque empiezo a dudar si podremos sobrevivir en esta tierra a la que nos ha traído.', `FemaleText_loc1`='데즈코 님은 훌륭한 족장님이세요. 그분을 따라서 온 이 땅에서 어떻게 살아남을지 걱정이 되기 시작했지만 말이죠.', `FemaleText_loc4`='德兹科是一位伟大的酋长，是他把我们带到了这里，但我开始有点怀疑我们能否在这片土地上存活下来。', `FemaleText_loc5`='戴斯可是個偉大的酋長，但我開始懷疑他能帶領我們在這片土地上存活到什麼程度。', `FemaleText_loc7`='Dezco es un gran jefe, aunque empiezo a dudar si podremos sobrevivir en esta tierra a la que nos ha traído.' WHERE `ID`=56924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 이상한 곳입니다. 너무나 아름답고도 위험하지요.', `MaleText_loc4`='这是一片神秘的土地，如此美丽，却又如此致命。', `MaleText_loc5`='這是片奇怪的土地。如此美麗，卻又如此致命。', `MaleText_loc7`='Es una tierra extraña. Es preciosa, pero a la vez es mortal.', `FemaleText_loc1`='참 이상한 곳이에요. 너무나 아름답고도 위험하지요.', `FemaleText_loc4`='这是一片神秘的土地，如此美丽，却又如此致命。', `FemaleText_loc5`='這是片奇怪的土地。如此美麗，卻又如此致命。', `FemaleText_loc7`='Es una tierra extraña. Es preciosa, pero a la vez es mortal.' WHERE `ID`=56925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤불 사이에서 눈동자가 보인 것 같습니다...', `MaleText_loc4`='我觉得矮树丛中有东西在盯着我们……', `MaleText_loc5`='我好像在樹叢裡看到眼睛...', `MaleText_loc7`='Creo haber visto unos ojos en el arbusto...', `FemaleText_loc1`='덤불 사이에서 눈동자가 보인 것 같아요...', `FemaleText_loc4`='我觉得矮树丛中有东西在盯着我们……', `FemaleText_loc5`='我好像在樹叢裡看到眼睛...', `FemaleText_loc7`='Creo haber visto unos ojos en el arbusto...' WHERE `ID`=56926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그날이 오면, 이 세계의 빛과 경이로움을 찾아라. 그리고 싸워라.', `FemaleText_loc4`='到那时，寻求这世上所有的光明与奇迹，并奋战到底。', `FemaleText_loc5`='當那天來臨，想想這世界一切光明和美好的事物，然後去戰吧。', `FemaleText_loc7`='Cuando llegue ese día, busca toda la luz y la felicidad de este mundo y lucha.' WHERE `ID`=56927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 함께 살고, 함께 죽는다. 판다리아의 모두는... 하나다.', `FemaleText_loc4`='我们将同生共死，潘达利亚的所有生灵与我们同在。', `FemaleText_loc5`='我們會一起活著，或一起死去。潘達利亞是一體同心。', `FemaleText_loc7`='Vivimos juntos. Morimos juntos. Toda Pandaria está conectada.' WHERE `ID`=56928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밀림에 잘 왔어요, $r님! 네싱워리 원정대에서 이곳의 야생 동물에 대한 정보를 수집하라고 저를 이곳에 파견했어요.$b$b좀 도와줄래요?', `FemaleText_loc4`='欢迎来到丛林，$r！奈辛瓦里派我来收集附近野生动物的情报。$b$b你愿意帮我一把吗？', `FemaleText_loc5`='叢林歡迎你，$r!奈辛瓦里派我來收集這裡野生動物的情報。$b$b你能幫點忙嗎?', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la jungla, $r! Nesingwary me ha enviado para reunir información sobre la vida salvaje de por aquí.$b$b¿Te gustaría echarme una mano?' WHERE `ID`=56929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 아무 짓도... 하지 않았는데... 모구가... 공격을 했고... 눈앞이 깜깜해졌습니다...', `MaleText_loc4`='无……无缘无故地，魔古族突然发起了攻击……一切都变黑了……', `MaleText_loc5`='呃...被觸怒了。魔古發動攻擊...一切陷入黑暗...', `MaleText_loc7`='Sin... provocación previa. Los mogu nos atacaron... todo se vuelve oscuro...' WHERE `ID`=56930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=56931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드에 여기에 있단 말인가?!', `FemaleText_loc4`='这里有部落？！', `FemaleText_loc5`='部落在這裡?!', `FemaleText_loc7`='¡¿La Horda está aquí?!' WHERE `ID`=56932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 놈들이 이 땅을 더럽히지는 못할 것이다!', `FemaleText_loc4`='决不容许部落玷污这片土地！', `FemaleText_loc5`='絕不讓部落玷污這片土地!', `FemaleText_loc7`='¡La Horda no profanará esta tierra!' WHERE `ID`=56933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요. 서쪽에 있는 네싱워리 님과 그 아드님을 만나면 우리가 짐승을 몇 마리나 처치했는지 알려줘요. 그런 이야기 듣는 걸 좋아하거든요.', `FemaleText_loc4`='谢谢帮忙，朋友。如果你在西边见到奈辛瓦里和他儿子，就告诉他们我们杀了多少动物。他们就喜欢听这个。', `FemaleText_loc5`='謝謝你的幫忙，朋友。如果你在西邊見到奈辛瓦里和他的孩子，跟他們講講我們宰了多少傢伙。他們喜歡這種故事。', `FemaleText_loc7`='Gracias por tu ayuda, $gamigo:amiga;. Si ves a Nesingwary y a su chico en el oeste, háblales sobre todo lo que hemos matado. Les gusta escuchar esas cosas.' WHERE `ID`=56934;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드 시민 여러분, 기뻐해주세요! 이제 데스윙은 끝장났습니다! 대격변은 끝났어요. 용맹한 영웅들이 압도적인 강력함으로 파괴자를 박살내버렸고, 이것은 용의 위상들에게 그들의 힘을 소모해 강력한 마지막 공격을 가하는 기회가 되었답니다. 데스윙의 턱은 희망과 미래의 표시로 여기 스톰윈드에 놓아둘 거예요!', `FemaleText_loc4`='暴风城的居民们，欢呼吧！死亡之翼已经被消灭了！灾难结束了！一群勇敢的英雄们冒死突袭灭世者，为守护巨龙们争取到了对死亡之翼发起致命一击的机会，虽然这也让他们牺牲了所有的力量。现在，死亡之翼的最后一段残骸就被保存在暴风城，成为了未来希望之光的象征！', `FemaleText_loc5`='暴風城的市民們，歡呼吧!死亡之翼已經死去!大災變已經結束了!一群勇敢的英雄以致命的精準和令人讚嘆的力量攻擊了毀滅者，使守護巨龍們有機會犧牲他們的力量進行最後的一擊。死亡之翼最後的遺體現在就在暴風城裡，當成對未來希望的明燈!', `FemaleText_loc7`='¡Ciudadanos de Ventormenta! ¡Alegraos! ¡Alamuerte ha dejado de existir! ¡El cataclismo ha acabado! Un grupo de valientes héroes fustigó al Destructor con una precisión mortal y un poder sobrecogedor, de modo que los dragones Aspectos tuvieron la oportunidad de sacrificar sus poderes en un golpe final. Lo que queda de Alamuerte ahora se halla aquí, en Ventormenta, ¡e iluminará nuestro futuro con un rayo de esperanza!' WHERE `ID`=56935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마 시민 여러분, 기뻐하십시오! 이제 데스윙은 끝장났습니다! 대격변은 끝났습니다. 용맹한 영웅들이 압도적인 강력함으로 파괴자를 박살내버렸고, 이것은 용의 위상들에게 그들의 힘을 소모해 강력한 마지막 공격을 가하는 기회가 되었습니다. 데스윙의 턱은 희망과 미래의 표시로 여기 오그리마에 놓아둘 것입니다!', `MaleText_loc4`='奥格瑞玛的居民们，欢呼吧！死亡之翼已经被消灭了！灾难结束了！一群勇敢的英雄们冒死突袭灭世者，为守护巨龙们争取到了对死亡之翼发起致命一击的机会，虽然这也让他们牺牲了所有的力量。现在，死亡之翼的最后一段残骸就被保存在奥格瑞玛，成为了未来希望之光的象征！', `MaleText_loc5`='奧格瑪的市民們，歡呼吧!死亡之翼已經死去!大災變已經結束了!一群勇敢的英雄以致命的精準和令人讚嘆的力量攻擊了毀滅者，使守護巨龍們有機會犧牲他們的力量進行最後的一擊。死亡之翼最後的遺體現在就在奧格瑪裡，當成對未來希望的明燈!', `MaleText_loc7`='¡Ciudadanos de Orgrimmar! ¡Alegraos! ¡Alamuerte ha dejado de existir! ¡El cataclismo ha acabado! Un grupo de valientes héroes fustigó al Destructor con una precisión mortal y un poder sobrecogedor, de modo que los dragones Aspectos tuvieron la oportunidad de sacrificar sus poderes en un golpe final. Lo que queda de Alamuerte ahora se halla aquí, en Orgrimmar, ¡e iluminará nuestro futuro con un rayo de esperanza!' WHERE `ID`=56936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도자니 왕조는 잔인하기로 유명해요. 조심하세요.', `MaleText_loc4`='都阳王朝是以凶残著称的。多加小心。', `MaleText_loc5`='朵迦皇朝最為人們熟記的就是他們的殘酷。小心。', `MaleText_loc7`='La dinastía Dojani es recordada por su crueldad. Ten cuidado.' WHERE `ID`=56937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내 정령들이 눈을 뜨고... 기뻐하는군... 대격변은... 이제 끝났네.', `MaleText_loc4`='我感到元素正在苏醒，欢呼……这场灾难……结束了。', `MaleText_loc5`='我可以感到元素在甦醒...歡呼...大災變結束了。', `MaleText_loc7`='Siento que los elementos despiertan; se regocijan... el Cataclismo... ha terminado.' WHERE `ID`=56941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원하신다면 혼돈의 소용돌이에서 데스윙이 파멸한 게 어떤 여파를 미쳤는지 보여드릴 수 있어요.', `FemaleText_loc4`='如果你希望如此，我可以向你展示死亡之翼在大漩涡所造成破坏的后果。', `FemaleText_loc5`='如果你想要看的話，我可以讓你看看死亡之翼在大漩渦的毀滅所造成的影響。', `FemaleText_loc7`='Te puedo mostrar las consecuencias de la destrucción de Alamuerte en La Vorágine, si quieres.' WHERE `ID`=56942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보여주십시오, 크로미.', `MaleText_loc4`='请让我看吧，克罗米。', `MaleText_loc5`='我想要看看，克羅米。', `MaleText_loc7`='Por favor, muéstramelo, Cromi.', `FemaleText_loc1`='보여주세요, 크로미.', `FemaleText_loc4`='请让我看吧，克罗米。', `FemaleText_loc5`='我想要看看，克羅米。', `FemaleText_loc7`='Por favor, muéstramelo, Cromi.' WHERE `ID`=56943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 마을에 죽치고 있긴 싫어요. 싸우고 싶다고요!', `MaleText_loc4`='我不能继续待在城里了！我得打上一场！', `MaleText_loc5`='我無法再待在鎮上了。我必須去戰鬥!', `MaleText_loc7`='No puedo quedarme aquí. ¡Tengo que buscar pelea!' WHERE `ID`=56944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 내 눈으로 지켜보고 싶어요.', `MaleText_loc4`='我会用自己的双眼注视这片土地。', `MaleText_loc5`='我會以我的雙眼照看這些土地。', `MaleText_loc7`='Miraría estas tierras con mis propios ojos.' WHERE `ID`=56945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸울 때 제 몸놀림을 보면 배울 게 많을 거예요.', `MaleText_loc4`='观察我的动作会令你受益匪浅。', `MaleText_loc5`='你可以藉由觀察我的行動學到很多。', `MaleText_loc7`='Aprenderías mucho si me vieras en acción.' WHERE `ID`=56946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수습생! 이리 와 봐요! 당신, 제 수습생... 맞죠?', `MaleText_loc4`='来吧，我的学徒！你是我的学徒，对吧……？', `MaleText_loc5`='過來，我的徒弟!你確實是我的徒弟，對吧...?', `MaleText_loc7`='¡Ven, aprendiz! ERES mi aprendiz, ¿verdad?' WHERE `ID`=56947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하신다면 혼돈의 소용돌이에서 데스윙이 파멸한 게 어떤 여파를 미쳤는지 보여드릴 수 있습니다.', `MaleText_loc4`='如果你希望如此，我可以向你展示死亡之翼在大漩涡所造成破坏的后果。', `MaleText_loc5`='你願意的話，我可以展現給你看，死亡之翼在大漩渦所造成的毀滅。', `MaleText_loc7`='Te puedo mostrar las consecuencias de la destrucción de Alamuerte en La Vorágine, si quieres.' WHERE `ID`=56948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보여주십시오, 용이여.', `MaleText_loc4`='让我看看，巨龙。', `MaleText_loc5`='綠龍，展現給我看吧。', `MaleText_loc7`='Muéstramelo, dragón.', `FemaleText_loc1`='보여주세요, 용이여.', `FemaleText_loc4`='让我看看，巨龙。', `FemaleText_loc5`='綠龍，展現給我看吧。', `FemaleText_loc7`='Muéstramelo, dragón.' WHERE `ID`=56949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 야영장에서 만나요.', `MaleText_loc4`='我会在营地与你会面。', `MaleText_loc5`='我會回營地去找你。', `MaleText_loc7`='Nos vemos en el campamento.' WHERE `ID`=56950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없구나... 정말 끝난 것인가? 다시 꿈을 꾸는 것만 같군...', `MaleText_loc4`='这不可能，真的结束了吗？我肯定又做梦了。', `MaleText_loc5`='這不可能...真的結束了嗎?我一定又在做夢了。', `MaleText_loc7`='No puede ser, ¿se ha acabado? Debo estar soñando otra vez.', `FemaleText_loc1`='믿을 수가 없구나... 정말 끝난 것인가? 다시 꿈을 꾸는 것만 같군...', `FemaleText_loc4`='这不可能，真的结束了吗？我肯定又做梦了。', `FemaleText_loc5`='這不可能...真的結束了嗎?我一定又在做夢了。', `FemaleText_loc7`='No puede ser, ¿se ha acabado? Debo estar soñando otra vez.' WHERE `ID`=56951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 힘을 합쳐 불가능한 일을 해냈습니다.', `MaleText_loc4`='我们合力完成了一件不可能的任务。', `MaleText_loc5`='我們一起達成了不可能的挑戰。', `MaleText_loc7`='Juntos hemos logrado lo imposible.' WHERE `ID`=56952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그대는 새로운 시대를 이끌어야 한다... 필멸자의 시대를 말이다.', `MaleText_loc4`='现在，你们必须开创一个新的时代……一个属于凡人的时代。', `MaleText_loc5`='現在你必須引領下一個年代...凡人的年代。', `MaleText_loc7`='Ahora debes marcar el comienzo de una nueva era: la era de los mortales.', `FemaleText_loc1`='이제 그대는 새로운 시대를 이끌어야 한다... 필멸자의 시대를 말이다.', `FemaleText_loc4`='现在，你们必须开创一个新的时代……一个属于凡人的时代。', `FemaleText_loc5`='現在你必須引領下一個年代...凡人的年代。', `FemaleText_loc7`='Ahora debes marcar el comienzo de una nueva era: la era de los mortales.' WHERE `ID`=56953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 함께해주십시오!', `MaleText_loc4`='加入我吧！', `MaleText_loc5`='加入我!', `MaleText_loc7`='¡Únete a mí!', `FemaleText_loc1`='저와 함께해주세요!', `FemaleText_loc4`='加入我吧！', `FemaleText_loc5`='加入我!', `FemaleText_loc7`='¡Únete a mí!' WHERE `ID`=56954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 전설에는 도자니 왕조와 젊음의 웅덩이에 대한 이야기가 나와요. 그 전설이 사실인지 보자고요.', `MaleText_loc4`='古老的传说讲述了都阳王朝和他们的青春之池。让我们看看传说究竟是不是真的。', `MaleText_loc5`='傳說朵迦皇朝有個青春之池。我們來看看傳說是否屬實。', `MaleText_loc7`='Las antiguas leyendas hablan de la dinastía Dojani y sus Pozas de la Juventud. Veamos si la leyenda es cierta.' WHERE `ID`=56955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 레크를 감옥에서 풀어주려고 합니다.', `MaleText_loc4`='试图将纳乐从囚牢中解救出来。', `MaleText_loc5`='嘗試將納類克從監獄釋放出來。', `MaleText_loc7`='Intenta liberar a Na Lek de su prisión.', `FemaleText_loc1`='나 레크를 감옥에서 풀어주려고 합니다.', `FemaleText_loc4`='试图将纳乐从囚牢中解救出来。', `FemaleText_loc5`='嘗試將納類克從監獄釋放出來。', `FemaleText_loc7`='Intenta liberar a Na Lek de su prisión.' WHERE `ID`=56956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어둠의 벽은 악마의 진군을 막아 우리가 길을 건널 시간을 벌어줄 것이다.
$b너와 다른 엘프들이 건너가고 나면 나도 따라가지.', `MaleText_loc4`='这道暗影之墙能挡住恶魔，直到我们安全通过。
$b等你们和其他精灵通过之后，我也会跟上的。', `MaleText_loc5`='這道暗影之牆能阻絕惡魔，讓我們有時間穿過去。
$b等你和其他夜精靈都過去了，我就會跟上。', `MaleText_loc7`='Esta pared de sombras mantendrá a los demonios a raya lo suficiente para que crucemos.
$bCuando tú y el resto de elfos hayan cruzado los seguiré.' WHERE `ID`=56957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라, 노예! 이 물은 천둥왕의 소유다. 이곳은 네놈이 올 곳이 아니다.', `MaleText_loc4`='站住，乞丐！这片水域属于雷电之王。你在这里是不受欢迎的。', `MaleText_loc5`='別動，賤民!這些水屬於雷王。這裡不歡迎你。', `MaleText_loc7`='¡Alto, suplicante! Estas aguas pertenecen al Rey del Trueno. No eres bienvenido.' WHERE `ID`=56958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자들이여! 침입자를 처치하라.', `MaleText_loc4`='守卫！消灭这些闯入者。', `MaleText_loc5`='守護者!殺死這些入侵者。', `MaleText_loc7`='¡Guardianes! Maten a estos intrusos.' WHERE `ID`=56959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬이이! 저들은 제가 여기 숨어 있다는 것을 모릅니다.', `MaleText_loc4`='嘘！它们不知道我藏在这里。', `MaleText_loc5`='噓!!他們不知道我躲在這裡。', `MaleText_loc7`='¡Shhhh! No saben que me he escondido aquí.' WHERE `ID`=56960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 판다렌 한 명에 불과하지만, 여기 남아서 용들을 보살펴야겠습니다.', `MaleText_loc4`='我只是一个熊猫人，可我必须留在这里，帮助翔龙。', `MaleText_loc5`='我只是一個熊貓人，但我必須留在這裡幫助這些蛟。', `MaleText_loc7`='Solo soy un pandaren, pero debo quedarme y ayudar a los dragones.' WHERE `ID`=56961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 조용히 해야 합니다. 뱀비늘 일족에게 들키면, 놈들은 조금도 주저하지 않고 우릴 저녁밥으로 먹어치울 테니까요.', `MaleText_loc4`='我们务必要保持安静。否则那些滑鳞蜥蜴人会毫不犹豫地把我们当晚餐吃了。', `MaleText_loc5`='我們得非常安靜，這些滑鱗會毫不遲疑地拿我們當晚餐。', `MaleText_loc7`='No debemos hacer el más mínimo ruido. Los Reptaescama no dudarán ni un instante en comernos para cenar.' WHERE `ID`=56962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 16일 동안 씻지 않았습니다. 그래야 주위 환경에 잘 스며들 수 있으니까요.', `MaleText_loc4`='我已经十六天没洗过澡了。这样就不太容易被发现。', `MaleText_loc5`='我有六天沒洗澡了，這樣更容易和環境合而為一。', `MaleText_loc7`='No me he bañado en quince días. Así es más fácil camuflarse.' WHERE `ID`=56963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 운룡에 대해 정말 많은 정보를 수집했습니다!', `MaleText_loc4`='我已经在野外收集到那么多有关翔龙的数据了！', `MaleText_loc5`='我在野地裡收集了這麼多蛟龍的資料!', `MaleText_loc7`='¡He reunido un montón de información sobre los dragones salvajes!' WHERE `ID`=56964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 야생 운룡의 천연 번식지랍니다. 발을 디딜 때도 항상 조심해야 해요.', `MaleText_loc4`='这里是它们天然的繁殖地，我们可得小心点儿。', `MaleText_loc5`='這是他們的自然繁衍地，我們必須步步小心。', `MaleText_loc7`='Este es su territorio de cría natural. Debemos andar con cuidado.' WHERE `ID`=56965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬마 정령이 우리를 돕고 있어요! 정령 근처에서 싸우세요!', `MaleText_loc4`='那个小精灵在帮我们！在他附近战斗，英雄！', `MaleText_loc5`='小精靈在幫助我們!到他附近戰鬥，英雄!', `MaleText_loc7`='¡El pequeño espíritu nos ayuda! ¡Lucha cerca de él, héroe!' WHERE `ID`=56966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 레크가 $p에게 감사의 마음을 전한 뒤 젊음의 웅덩이로 돌아갑니다.', `MaleText_loc4`='纳乐向$p致谢，然后回到了池水之中。', `MaleText_loc5`='納類克感謝地擁抱了$p並回到池水。', `MaleText_loc7`='Na Lek imbuye a $p de gratitud y vuelve a las aguas de la poza.' WHERE `ID`=56967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사는 방문해 봤습니까? 우리 수련생들 중에는 그곳에 가서 위론 님의 인도를 받으며 훈련을 계속하는 이들이 많습니다.', `MaleText_loc4`='你去过青龙寺吗？我们的许多弟子都会被派去那里潜心进修，由玉珑亲自督导。', `MaleText_loc5`='你拜訪過東邊的玉蛟寺嗎?我們有許多學生被送進寺廟裡，在玉龍的關照下接受進一步的訓練。', `MaleText_loc7`='¿Has tenido oportunidad de visitar el Templo del Dragón de Jade? Enviamos a muchos de nuestros estudiantes a proseguir su entrenamiento entre sus muros, bajo la atenta mirada de la propia Yu''lon.' WHERE `ID`=56968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 운룡을 번식시키려고 무척 애를 썼지만, 안타깝게도 모두 실패했습니다. 그래서 조심스럽게 야생 운룡의 알을 조금씩 가져다가 우리 손으로 키운답니다.', `MaleText_loc4`='不幸的是，我们培育翔龙的努力失败了。我们现在只能仔细挑选一些野生翔龙蛋回去自己饲养了。', `MaleText_loc5`='不幸的是，我們養殖蛟龍的努力不太成功。我們小心地從野生蛟龍那裡帶回少許的蛋來培育屬於我們的蛟龍。', `MaleText_loc7`='Por desgracia, nuestros intentos de reproducir a los dragones han fracasado. Nos llevaremos unos cuantos huevos de dragones salvajes para criarlos nosotros mismos.' WHERE `ID`=56969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울트락시온과 그 졸개들을 물리치도록 고룡쉼터 사원 정상으로 데려가 주십시오.', `MaleText_loc4`='我要挑战奥卓克希昂和他的爪牙，送我去龙眠神殿顶层。', `MaleText_loc5`='帶我到龍眠神殿之頂，與奧特拉賽恩和他的爪牙作戰。', `MaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Ultraxion y sus esbirros.', `FemaleText_loc1`='울트락시온과 그 졸개들을 물리치도록 고룡쉼터 사원 정상으로 데려가 주십시오.', `FemaleText_loc4`='我要挑战奥卓克希昂和他的爪牙，送我去龙眠神殿顶层。', `FemaleText_loc5`='帶我到龍眠神殿之頂，與奧特拉賽恩和他的爪牙作戰。', `FemaleText_loc7`='Llévame a la cima del Templo del Reposo del Dragón para luchar contra Ultraxion y sus esbirros.' WHERE `ID`=56970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 봐요. 저 꼬마가 당신을 위해 정화된 물을 남겼네요.', `MaleText_loc4`='看哪。那个小家伙给你留下了一些纯净之水。', `MaleText_loc5`='看看那個。小傢伙留了些淨化過的水給你。', `MaleText_loc7`='Fíjate. El pequeñajo te ha dejado un poco de agua purificada.' WHERE `ID`=56971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제여, 우리는 수비에 치중해야만 하네. 얼라이언스가 동쪽에서 몰려오고 있네.', `MaleText_loc4`='兄弟，我们必须留心保护自己。联盟正从东面步步逼近。', `MaleText_loc5`='兄弟，我們得小心防禦。聯盟正從東邊朝我們蠶食而來。', `MaleText_loc7`='Hermano, debemos supervisar nuestras defensas. La Alianza nos acecha desde el este.' WHERE `ID`=56972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 호드의 신하일세. 호드로서의 의무와 맹약을 잊지 말게. 우리는 대족장님의 명령에 따라 이 나이트 엘프들을 처단해야만 하네.', `MaleText_loc4`='你是部落的一份子。请牢记你的责任和誓言。酋长有令，我们必须杀死这些暗夜精灵。', `MaleText_loc5`='你是部落的一份子。要記得你的義務和誓約。依大酋長之命，我們必須殺死這些夜精靈。', `MaleText_loc7`='Eres un súbdito de la Horda. No olvides tus obligaciones y juramentos. Por orden del Jefe de Guerra, debemos acabar con estos elfos de la noche.' WHERE `ID`=56973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자의 고통 뒤에 숨을 수 있는 것도 여기까지네. 조만간 태양길잡이답게 우뚝 서서 우리를 이끌고 호드의 적과 맞서 싸워야 하네.', `MaleText_loc4`='你不能再以莱莎的痛苦为借口了。迟早，你要作为一名烈日行者挺身而出，带领我们对抗部落的敌人。', `MaleText_loc5`='你不能永遠拿麗紗的痛苦當藉口。總有一天，你必須肩負起你所稱的日行者的責任，領導我們對抗部落的敵人。', `MaleText_loc7`='No puedes ocultarte detrás del sufrimiento de Leza durante mucho tiempo. Tarde o temprano, deberás levantarte como el caminasol que dices ser y liderarnos contra los enemigos de la Horda.' WHERE `ID`=56974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 레자가 아이를 낳을 때까지 옆에 있어야만 하네. 죽음보다는 생명이 우선일세.', `MaleText_loc4`='我必须待在莱莎身边，直到她生下孩子。死亡，总要排在生命之后。', `MaleText_loc5`='我必須守在麗紗的身邊，直到她生下寶寶。新生命比死亡重要多了。', `MaleText_loc7`='Debo permanecer junto a Leza hasta que haya dado a luz. La muerte puede esperar a la vida.' WHERE `ID`=56975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베인 블러드후프 님께서 내게 내리신 명령은 이 땅에 정착하여 우리 태양길잡이들이 느낀 빛에 대해 조사하라는 것이네. 얼라이언스 문제는 논외란 말일세.', `MaleText_loc4`='贝恩的命令是保护我们在这片土地上的新据点，并调查我们的烈日行者所感受到的圣光。联盟方面不足为虑。', `MaleText_loc5`='我奉貝恩之命在這片土地上取得新據點，並調查我們日行者感覺到的聖光。聯盟只是小問題。', `MaleText_loc7`='Las órdenes que recibí de Baine eran asegurar nuevos asentamientos en esta tierra e investigar la luz que sintieron nuestros caminasol. La Alianza nos preocupa poco.' WHERE `ID`=56976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 주체하지 못하면... 그로 인해 눈이 멀게 된다네, 형제여.', `MaleText_loc4`='如果放任仇恨滋生，它会遮蔽你的双眼，兄弟。', `MaleText_loc5`='如果你任由憎恨滋長，憎恨將蒙蔽你的眼睛，兄弟。', `MaleText_loc7`='El odio te cegará, hermano, si lo permites.' WHERE `ID`=56977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구의 움직임을 보면 아무래도 그중에 지도자가 있는 듯하네. 조심하게.', `MaleText_loc4`='魔古族的首领有着特殊的领导能力。你要谨慎从事。', `MaleText_loc5`='魔古似乎擁有組織和紀律。多小心。', `MaleText_loc7`='Los mogu tienen cierto dominio sobre ellos que le imponen su liderazgo. Ten cuidado.' WHERE `ID`=56978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에 머물러도 괜찮기만 하다네. 경치도 좋고, 맥주도 많고... 싸울 놈들도 많으니까 말일세.', `MaleText_loc4`='我会很乐意在这里住下的。风景秀丽，啤酒充足……还有很多架可打。', `MaleText_loc5`='我不介意在這樣的地方定下來。風景好，啤酒多...又隨時有架可以打。', `MaleText_loc7`='No me importaría instalarme en un sitio como este. Buenas vistas, mucha cerveza... y un montón de cosas con las que pelearte.' WHERE `ID`=56979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신은 주먹에서 까드득 소리를 내며 고개를 좌우로 흔듭니다.>', `MaleText_loc4`='<摩拳擦掌并点头。>', `MaleText_loc5`='<折折你的指關節並點點頭。>', `MaleText_loc7`='<Chasqueas los nudillos y asientes con la cabeza.>', `FemaleText_loc1`='<당신은 주먹에서 까드득 소리를 내며 고개를 좌우로 흔듭니다.>', `FemaleText_loc4`='<摩拳擦掌并点头。>', `FemaleText_loc5`='<折折你的指關節並點點頭。>', `FemaleText_loc7`='<Chasqueas los nudillos y asientes con la cabeza.>' WHERE `ID`=56980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 한바탕 할 준비 됐나?', `MaleText_loc4`='你准备好打架了吗，$n？', `MaleText_loc5`='準備好來場大亂鬥了嗎，$n?', `MaleText_loc7`='¿Estás $glisto:lista; para pelear, $n?' WHERE `ID`=56981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 다시 공격해오기 전에 뭉쳐야 해!', `MaleText_loc4`='我们必须在煞再次攻击前，重整旗鼓！', `MaleText_loc5`='我們必須在煞再次進攻之前重整隊伍!', `MaleText_loc7`='¡Debemos reagruparnos antes de que ataquen de nuevo los Sha!', `FemaleText_loc1`='샤가 다시 공격해오기 전에 뭉쳐야 해!', `FemaleText_loc4`='我们必须在煞再次攻击前，重整旗鼓！', `FemaleText_loc5`='我們必須在煞再次進攻之前重整隊伍!', `FemaleText_loc7`='¡Debemos reagruparnos antes de que ataquen de nuevo los Sha!' WHERE `ID`=56982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='플레임하트 님이 우릴 배신했어! 사원은 이제 끝이야!', `MaleText_loc4`='焰心女祭司背叛了我们！寺院要沦陷了！', `MaleText_loc5`='女司祭焰心背叛了我們!寺院失陷了!', `MaleText_loc7`='¡La sacerdotisa Corazón Llameante nos ha traicionado! ¡El templo está perdido!', `FemaleText_loc1`='플레임하트 님이 우릴 배신했어! 사원은 이제 끝이야!', `FemaleText_loc4`='焰心女祭司背叛了我们！寺院要沦陷了！', `FemaleText_loc5`='女司祭焰心背叛了我們!寺院失陷了!', `FemaleText_loc7`='¡La sacerdotisa Corazón Llameante nos ha traicionado! ¡El templo está perdido!' WHERE `ID`=56983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 너무 많아. 기회가 있을 때 도망쳐!', `MaleText_loc4`='煞魔太多了，能逃就赶快逃吧！', `MaleText_loc5`='煞的數量太多，我們得趁還有機會時趕快逃走!', `MaleText_loc7`='¡Son demasiados Sha, debemos huir mientras podamos!', `FemaleText_loc1`='샤가 너무 많아. 기회가 있을 때 도망쳐!', `FemaleText_loc4`='煞魔太多了，能逃就赶快逃吧！', `FemaleText_loc5`='煞的數量太多，我們得趁還有機會時趕快逃走!', `FemaleText_loc7`='¡Son demasiados Sha, debemos huir mientras podamos!' WHERE `ID`=56984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어라... 저한테 곧바로 오네요.', `FemaleText_loc4`='嗯……他朝我冲过来了。', `FemaleText_loc5`='嗯...他是衝著我來的。', `FemaleText_loc7`='Uuh... viene directo hacia mí.' WHERE `ID`=56985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메이, 이 주변에서 소금을 구할 수 있는 곳이 어디인지 아십니까?', `MaleText_loc4`='明，你知道在这附近哪里有盐吗？', `MaleText_loc5`='小美，你知道我可以在哪找到鹽嗎?', `MaleText_loc7`='Mei, ¿tienes idea de dónde puedo encontrar sal por aquí?', `FemaleText_loc1`='메이, 이 주변에서 소금을 구할 수 있는 곳이 어디인지 아세요?', `FemaleText_loc4`='明，你知道在这附近哪里有盐吗？', `FemaleText_loc5`='小美，你知道我可以在哪找到鹽嗎?', `FemaleText_loc7`='Mei, ¿tienes idea de dónde puedo encontrar sal por aquí?' WHERE `ID`=56986;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망쳐야 돼요?', `FemaleText_loc4`='我该跑了么？', `FemaleText_loc5`='我該用跑嗎?', `FemaleText_loc7`='¿Debería correr?' WHERE `ID`=56987;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망칠래요.', `FemaleText_loc4`='我要跑了。', `FemaleText_loc5`='我得用跑的。', `FemaleText_loc7`='Voy a correr.' WHERE `ID`=56988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이모우를 데려와 주셔서 감사합니다.$B$B우리가 쥬 지구에서 수행해야 할 임무를 더는 무시할 수가 없어요.', `MaleText_loc4`='谢谢你把易默带回来。$B$B我现在明白了，我们再也不能忽视自己在这里的职责。', `MaleText_loc5`='謝謝你把易謀帶回來。$B$B我們不能再忽視對這塊土地該負的責任了。', `MaleText_loc7`='Gracias por traer a Yi-Mo de vuelta.$B$BAhora tengo claro que ya no podemos obviar nuestros deberes en la provincia.', `FemaleText_loc1`='이모우를 데려와 주셔서 감사합니다.$B$B우리가 쥬 지구에서 수행해야 할 임무를 더는 무시할 수가 없어요.', `FemaleText_loc4`='谢谢你把易默带回来。$B$B我现在明白了，我们再也不能忽视自己在这里的职责。', `FemaleText_loc5`='謝謝你把易謀帶回來。$B$B我們不能再忽視對這塊土地該負的責任了。', `FemaleText_loc7`='Gracias por traer a Yi-Mo de vuelta.$B$BAhora tengo claro que ya no podemos obviar nuestros deberes en la provincia.' WHERE `ID`=56989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평소라면 소금이 남아돌겠지만, 비가 오는 바람에 보급품이 대부분 엉망이 되었답니다.$B$B하지만 저기 메마른 연못에 있는 생물들은 땅속의 염분과 빗물의 혼합물인 게 확실합니다. 아마 놈들을 처치하면 소금이 나올 거예요.', `MaleText_loc4`='通常我们手上会有很多，但眼下几乎所有补给品都被雨水冲毁了。$B$B不过，我相信那些干涸池塘里的生物是雨水和泥土盐分的混合物。你也许能从它们身上找到需要的东西。', `MaleText_loc5`='通常我們手上有很多補給品，但是大部分都在雨中毀掉了。$B$B然而，我肯定乾涸池子裡的那些生物是雨水和鹽的結合體。或許你能從他們身上拿到你需要的物資。', `MaleText_loc7`='Normalmente tenemos mucha a mano, pero la mayoría de nuestras provisiones se han estropeado con la lluvia.$B$BSin embargo, una cosa es segura: las criaturas de los estanques secos son una mezcla de agua de lluvia y sal de la tierra. Es posible que consigas lo que necesitas de esas criaturas.', `FemaleText_loc1`='평소라면 소금이 남아돌겠지만, 비가 오는 바람에 보급품이 대부분 엉망이 되었답니다.$B$B하지만 저기 메마른 연못에 있는 생물들은 땅속의 염분과 빗물의 혼합물인 게 확실합니다. 아마 놈들을 처치하면 소금이 나올 거예요.', `FemaleText_loc4`='通常我们手上会有很多，但眼下几乎所有补给品都被雨水冲毁了。$B$B不过，我相信那些干涸池塘里的生物是雨水和泥土盐分的混合物。你也许能从它们身上找到需要的东西。', `FemaleText_loc5`='通常我們手上有很多補給品，但是大部分都在雨中毀掉了。$B$B然而，我肯定乾涸池子裡的那些生物是雨水和鹽的結合體。或許你能從他們身上拿到你需要的物資。', `FemaleText_loc7`='Normalmente tenemos mucha a mano, pero la mayoría de nuestras provisiones se han estropeado con la lluvia.$B$BSin embargo, una cosa es segura: las criaturas de los estanques secos son una mezcla de agua de lluvia y sal de la tierra. Es posible que consigas lo que necesitas de esas criaturas.' WHERE `ID`=56990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 어떻게 이런 일이...?!', `MaleText_loc4`='不！！！这怎么可能？', `MaleText_loc5`='不!怎麼可能?!', `MaleText_loc7`='¡Nooo! ¡¿Cómo es posible?!' WHERE `ID`=56991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=56992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아, 정말 멋지군요. 네, 이 알이면 충분할 겁니다. 이쪽은 안 됩니다. 너무 작아요! 네, 아마 이 알로 결정될 겁니다...', `MaleText_loc4`='啊，这个蛋很不错。嗯，这个应该可以。这个不行，太小了。这个应该能通过检查……', `MaleText_loc5`='啊啊，這個不錯。嗯，這個蛋可以。這個就不行。太小了。這顆也許可以過關...', `MaleText_loc7`='Vaya, este está muy bien. Sí, este huevo servirá. Este no. ¡Es demasiado pequeño! Quizás este podría pasar...' WHERE `ID`=56993;
