UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고요? 생각을 바꿨다고요? 신중하게 선택하라고 그렇게 말씀드렸잖습니까!$B$B아, 뭐, 이번 한 번은 괜찮습니다. 말씀하십시오. 진짜로 원하는 알이 뭡니까?', `MaleText_loc4`='什么？你最终还是改变主意了？我告诉过你叫你仔细挑选！$B$B算了算了，这次我就原谅你了。告诉我，你到底想要哪个蛋？', `MaleText_loc5`='什麼?你終究是改變心意了。我跟你講過要小心選了!$B$B啊好吧，這次我原諒你。告訴我，你最想要哪一種蛋?', `MaleText_loc7`='¿Qué? ¿Al final has cambiado de opinión? ¡Te dije que escogieras con cuidado!$b$bAh, bueno, por esta vez te perdono. Dime, ¿qué huevo quieres de verdad?' WHERE `ID`=57027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t하늘불꽃호가 심각한 손상을 입어 |cFFFF0000|Hspell:110095|h[갑판 화재]|h|r가 일어납니다!', `MaleText_loc4`='|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t天火号受到结构性损害，突然引发了一次|cFFFF0000|Hspell:110095|h[甲板起火]|h|r！', `MaleText_loc5`='|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|t對天火號船體的傷害忽然引發了一陣|cFFFF0000|Hspell:110095|h[甲板烈焰]|h|r!', `MaleText_loc7`='|Tinterface\icons\spell_fire_ragnaros_lavabolt.blp:0|t¡El daño estructural de El Abrasacielos activa un repentino |cFFFF0000|Hspell:110095|h[Fuego de cubierta]|h|r!' WHERE `ID`=57030;
