UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 거품위로 뛰어다녀서 에디의 |cFFFF0000|Hspell:110189|h[축축한 보호막]|h|r을 약화시키십시오!', `MaleText_loc4`='碾过小泡泡以削弱涡流的|cFFFF0000|Hspell:110189|h[水体护盾]|h|r！', `MaleText_loc5`='輾過那些小泡泡來削弱艾迪的|cFFFF0000|Hspell:110189|h[水盾]|h|r!', `MaleText_loc7`='¡Aplasta las burbujas para debilitar el |cFFFF0000|Hspell:110189|h[Escudo acuático]|h|r de Eddy!' WHERE `ID`=57043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에디의 약해진 |cFFFF0000|Hspell:110198|h[축축한 보호막]|h|r을 클릭해 터뜨리십시오!', `MaleText_loc4`='点击涡流被削弱的|cFFFF0000|Hspell:110198|h[水体护盾]|h|r来戳破它！', `MaleText_loc5`='點擊艾迪虛弱的|cFFFF0000|Hspell:110198|h[水盾]|h|r使它動起來!', `MaleText_loc7`='¡Haz clic en el |cFFFF0000|Hspell:110198|h[Escudo acuático]|h|r debilitado de Eddy para estallarlo!' WHERE `ID`=57044;
