UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지를 과소평가하지 마라. 몸뚱이가 엉망이 된 후에도... 그의 광기와 분노는 여전히 남아 널 없애려고 안간힘을 쓸 터이니.', `MaleText_loc4`='别低估我的父亲。即使你摧毁了他的身体，他那颗充满疯狂与愤怒的心仍然能毁掉你。', `MaleText_loc5`='不要低估我的父親。即使你能摧毀他的身體，他瘋狂和憤怒的根源仍會試圖毀滅你。', `MaleText_loc7`='No subestimes a mi padre. Aunque destrozaras su cuerpo, el núcleo de su locura y su ira lucharían por destruirte.' WHERE `ID`=57102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전한 파괴만이 그를 무너뜨릴 유일한 길이다.', `MaleText_loc4`='除非将他轰至灰飞烟灭，否则都不能算是击败了他。', `MaleText_loc5`='在他徹底被消滅之前，他都不算是真正被擊敗。', `MaleText_loc7`='No será derrotado hasta que lo aniquile por completo.' WHERE `ID`=57103;
