UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빈다, 도적이여. 결과가 어떻든, 넌 진정한 용사다.', `MaleText_loc4`='祝你好运，潜行者。无论结局如何，你都是一个真正的勇士。', `MaleText_loc5`='祝你好運，盜賊。不論結果如何，你都是真正的勇士。', `MaleText_loc7`='Te deseo lo mejor, granuja. Sea cual sea el resultado, te mereces un reconocimiento.' WHERE `ID`=57105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격대 일로 가신 거잖아요. 어쨌든 경의를 표합니다. 저는 카라잔이 어딘지도 몰라요. 거긴 어떻게 가셨습니까?', `MaleText_loc4`='你发动了突然袭击。不过我还是要向你致敬，我甚至都不知道卡拉赞在哪儿。你是怎么到那的？', `MaleText_loc5`='你在隊伍裡。但我還是對你表示敬意，我連卡拉贊在哪都不知道。你怎麼過去的?', `MaleText_loc7`='Estuviste en una banda. Pero bueno, me descubro, yo ni siquiera sé dónde está Karazhan. ¿Cómo llegaste hasta allí?', `FemaleText_loc1`='공격대 일로 가신 거잖아요. 어쨌든 경의를 표합니다. 저는 카라잔이 어딘지도 몰라요. 거긴 어떻게 가셨습니까?', `FemaleText_loc4`='你发动了突然袭击。不过我还是要向你致敬，我甚至都不知道卡拉赞在哪儿。你是怎么到那的？', `FemaleText_loc5`='你在隊伍裡。但我還是對你表示敬意，我連卡拉贊在哪都不知道。你怎麼過去的?', `FemaleText_loc7`='Estuviste en una banda. Pero bueno, me descubro, yo ni siquiera sé dónde está Karazhan. ¿Cómo llegaste hasta allí?' WHERE `ID`=57106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘불꽃호가 |cFF9900CC|Hspell:107439|h[황혼 탄막]|h|r의 피해를 입지 않도록 가로막으십시오!', `MaleText_loc4`='快挡住|cFF9900CC|Hspell:107439|h[暮光弹幕]|h|r，以防天火号受到损伤！', `MaleText_loc5`='攔截|cFF9900CC|Hspell:107439|h[暮光彈幕]|h|r以防止天火號受到傷害!', `MaleText_loc7`='¡Intercepta |cFF9900CC|Hspell:107439|h[Tromba Crepuscular]|h|r para evitar que El Abrasacielos reciba daño!', `FemaleText_loc1`='하늘불꽃호가 |cFF9900CC|Hspell:107439|h[황혼 탄막]|h|r의 피해를 입지 않도록 가로막으십시오!', `FemaleText_loc4`='快挡住|cFF9900CC|Hspell:107439|h[暮光弹幕]|h|r，以防天火号受到损伤！', `FemaleText_loc5`='攔截|cFF9900CC|Hspell:107439|h[暮光彈幕]|h|r以防止天火號受到傷害!', `FemaleText_loc7`='¡Intercepta |cFF9900CC|Hspell:107439|h[Tromba Crepuscular]|h|r para evitar que El Abrasacielos reciba daño!' WHERE `ID`=57107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 데서 일자리를 구하는 게 어떻습니까?', `MaleText_loc4`='你为什么不去其它地方找活儿干呢？', `MaleText_loc5`='你為什麼不去別處找個工作?', `MaleText_loc7`='¿Por qué no buscas trabajo en otro sitio?', `FemaleText_loc1`='다른 데서 일자리를 구하는 게 어때요?', `FemaleText_loc4`='你为什么不去其它地方找活儿干呢？', `FemaleText_loc5`='你為什麼不去別處找個工作?', `FemaleText_loc7`='¿Por qué no buscas trabajo en otro sitio?' WHERE `ID`=57108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|c0087CEFA|Hspell:105845|h[핵폭발]|h|r이 갑옷을 들어낼 정도로 가까운 곳에서 터지지 않았습니다!', `MaleText_loc4`='|c0087CEFA|Hspell:105845|h[核能冲击]|h|r的爆发距离太远，不足以掀起装甲板！', `MaleText_loc5`='|c0087CEFA|Hspell:105845|h[核子爆破]|h|r的距離不夠近，不足以炸開護甲!', `MaleText_loc7`='|c0087CEFA|Hspell:105845|h¡La [Explosión nuclear]|h|r no estaba lo bastante cerca como para levantar la placa!' WHERE `ID`=57109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일은 내게 어울리지 않아! 난 배우이자 연기자지, 평범한 청소부가 아니란 말이오! 빛에 맹세하는데, 난 카라잔에서 가극에 출연한 적도 있다오!', `MaleText_loc4`='这可不是我应得的待遇！我是一位演员，一位表演者——才不是什么普通的清洁工！看在圣光的份上——我可是在卡拉赞的歌剧院里表演过的！', `MaleText_loc5`='我不該受到這種待遇!我是個演員，表演家，不是路邊隨便一個戲子!聖光在上，我可是曾在卡拉贊的歌劇院表演過!', `MaleText_loc7`='¡Me merezco algo mejor! Soy un actor, un intérprete, no un simple barrendero de guano. ¡Por el amor de la Luz! ¡He actuado en la ópera de Karazhan!' WHERE `ID`=57110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 타락한 피 잔류물을 핵폭발을 일으킬 만큼 충분히 흡수하지 못했습니다.', `MaleText_loc4`='%s未能吸收到足够的堕落熔岩残渣来触发核能冲击。', `MaleText_loc5`='%s沒有吸收到足夠的腐化之血殘渣來引發核子爆破。', `MaleText_loc7`='%s no absorbió suficientes residuos de sangre corrupta para activar una Explosión nuclear.' WHERE `ID`=57111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연습! 연습! 또 연습!', `MaleText_loc4`='练习，练习，再练习！', `MaleText_loc5`='練習、練習、練習!', `MaleText_loc7`='Tanto practicar, tanto practicar...' WHERE `ID`=57112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 이 꼴 좀 보쇼. 망할 동물 뒷시중이나 들고 있으니.', `MaleText_loc4`='瞧瞧我现在的模样。跟在这只蠢野兽的屁股后面打扫个没完。', `MaleText_loc5`='看看我。跟在這蠢蛋野獸後面打掃。', `MaleText_loc7`='Y ahora mírame. Barriendo lo que ensucia esta bestia estúpida.' WHERE `ID`=57113;
