UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅의 의지를 사용해 황혼의 시간과 사그라지는 빛을 피하십시오!', `MaleText_loc4`='快使用英勇意志技能来躲避暮光审判和黯淡之光！', `MaleText_loc5`='使用英勇意志技能來迴避暮光之時和消逝之光!', `MaleText_loc7`='¡Utiliza la facultad Voluntad heroica para evitar Hora del Crepúsculo y Luz mortecina!', `FemaleText_loc1`='영웅의 의지를 사용해 황혼의 시간과 사그라지는 빛을 피하십시오!', `FemaleText_loc4`='快使用英勇意志技能来躲避暮光审判和黯淡之光！', `FemaleText_loc5`='使用英勇意志技能來迴避暮光之時和消逝之光!', `FemaleText_loc7`='¡Utiliza la facultad Voluntad heroica para evitar Hora del Crepúsculo y Luz mortecina!' WHERE `ID`=57115;
