UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 여기서 뭘 하고 있는 거지? 할 일도 많은데!', `MaleText_loc4`='我在这儿干什么？我还有工作要做！', `MaleText_loc5`='我在這外頭做什麼?我還有工作要做!', `MaleText_loc7`='¿Qué estoy haciendo aquí fuera? ¡Tengo trabajo que hacer!', `FemaleText_loc1`='내가 여기서 뭘 하고 있는 거지? 할 일도 많은데!', `FemaleText_loc4`='我在这儿干什么？我还有工作要做！', `FemaleText_loc5`='我在這外頭做什麼?我還有工作要做!', `FemaleText_loc7`='¿Qué estoy haciendo aquí fuera? ¡Tengo trabajo que hacer!' WHERE `ID`=57120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아가들과 싸우러 온 거냐? 보물도 훔쳐갈 거지?', `MaleText_loc4`='你是来打我的孩子的？还是来偷我的财宝的？', `MaleText_loc5`='你跑來攻擊我的子孫?你跑來偷我的寶貝?', `MaleText_loc7`='¿Vienes a enfrentarte a los míos? ¿Vienes a robar mis tesoros?' WHERE `ID`=57121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깜짝 놀랄 거다!', `MaleText_loc4`='地栗的惊喜来了！', `MaleText_loc5`='給秋法一點驚喜的時候到了!', `MaleText_loc7`='¡Es el momento de la sorpresa de Chufa!' WHERE `ID`=57122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 이제 큰일 난 거야!', `MaleText_loc4`='你要倒霉了！', `MaleText_loc5`='現在你逃不了了!', `MaleText_loc7`='¡Te la estás ganando!' WHERE `ID`=57123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일 있었나?', `MaleText_loc4`='我错过什么了吗？', `MaleText_loc5`='我錯過了什麼嗎?', `MaleText_loc7`='¿Me perdí de algo?' WHERE `ID`=57124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐어어???', `MaleText_loc4`='什么！？', `MaleText_loc5`='什麼...?', `MaleText_loc7`='¿Qué...?' WHERE `ID`=57125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 딱 시간 맞춰 온 것 같군.', `MaleText_loc4`='看起来我来的正是时候！', `MaleText_loc5`='看來我及時趕到了!', `MaleText_loc7`='¡Parece que llegué justo a tiempo!' WHERE `ID`=57126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정구와 연결됐다면, 수정구를 향해 달려가십시오!', `MaleText_loc4`='如果你与宝珠之间有联结，就快跑到那边去吧！', `MaleText_loc5`='如果你被一顆寶珠連結了，跑向它!', `MaleText_loc7`='¡Corre hacia el orbe si estás conectado con él!' WHERE `ID`=57127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님! 검은 바닥에서 나오셔야 합니다!', `MaleText_loc4`='$n！快躲开地面上有黑色污泥的地方！', `MaleText_loc5`='$n!趕快離開地上的黑色軟泥!', `MaleText_loc7`='¡$n! ¡Apártate del moco negro que hay en el suelo!' WHERE `ID`=57128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 공명의 수정에 의해 목숨을 잃으셨습니다. 수정에 더 가까이 서면, 받는 피해가 줄어듭니다.', `MaleText_loc4`='$n，你被共鸣水晶杀死了。靠近共鸣水晶可降低伤害。', `MaleText_loc5`='$n，你被一顆共鳴水晶殺死了。站離共鳴水晶近一點可以減低傷害。', `MaleText_loc7`='$n, te mató un cristal resonador. Colocarse más cerca del cristal resonador reduce el daño.' WHERE `ID`=57129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 해봅시다!', `MaleText_loc4`='我们动手吧！', `MaleText_loc5`='我們開始吧!', `MaleText_loc7`='¡Vamos allá!', `FemaleText_loc1`='한번 해봐요!', `FemaleText_loc4`='我们动手吧！', `FemaleText_loc5`='我們開始吧!', `FemaleText_loc7`='¡Vamos allá!' WHERE `ID`=57130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 하가라의 얼음 파도에 의해 목숨을 잃으셨습니다. $B더 일찍 달리기 시작해, 얼음을 피하세요!', `MaleText_loc4`='$n，你被哈格拉的寒冰之潮杀死了。$B请提前移动以躲开寒冰之潮！', `MaleText_loc5`='$n，你被哈甲拉的冰霜浪潮殺死了。$B早點開始跑，才能躲過攻擊!', `MaleText_loc7`='$n, te mató una Ola de hielo de Hagara. $B¡Empieza a correr cuanto antes para evitar el hielo!', `FemaleText_loc1`='$n 님, 하가라의 얼음 파도에 의해 목숨을 잃으셨습니다. $B더 일찍 달리기 시작해, 얼음을 피하세요!', `FemaleText_loc4`='$n，你被哈格拉的寒冰之潮杀死了。$B请提前移动以躲开寒冰之潮！', `FemaleText_loc5`='$n，你被哈甲拉的冰霜浪潮殺死了。$B早點開始跑，才能躲過攻擊!', `FemaleText_loc7`='$n, te mató una Ola de hielo de Hagara. $B¡Empieza a correr cuanto antes para evitar el hielo!' WHERE `ID`=57131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 내 갑옷... 약해진다...', `MaleText_loc4`='啊噢……我的战甲……正在被削弱……', `MaleText_loc5`='哦喔...我的戰甲...變薄了...', `MaleText_loc7`='Oh oh... Mi armadura de batalla... se debilita...' WHERE `ID`=57132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 자네가 정리하게. 머드머그의 집터에서 보세!', `MaleText_loc4`='好好打扫这里吧，$p。到泥盏那儿见！', `MaleText_loc5`='$p，我讓你在這裡先整理乾淨。到泥杯那兒見啦!', `MaleText_loc7`='Los dejo limpiar este sitio. ¡Nos vemos con Caolín!' WHERE `ID`=57133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 하나의 영혼이 파괴자의 손에 쓰러지는구나...', `MaleText_loc4`='灭世者又夺走了一条灵魂……', `MaleText_loc5`='又有一個靈魂被毀滅者帶走了...', `MaleText_loc7`='El Destructor ha reclamado otra alma...' WHERE `ID`=57134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 졸업을 축하하네. 이제 티엔의 벽 안에서 알아야 할 것을 모두 배웠군.', `MaleText_loc4`='$n，今天我们要庆祝你顺利毕业了。你已经学习并掌握了天禅院的所有智慧与奥妙。', `MaleText_loc5`='$n，恭喜你今天結業了。你已經學到天僧寺內所有的知識。', `MaleText_loc7`='$n, hoy celebramos tu graduación. Has aprendido todo lo que podemos enseñarte tras los muros de Tian.' WHERE `ID`=57135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑네, $n! 훈련은 잘 되고 있나?$b$b우리 교관들이 자네를 매우 그리워한다네... 자네와 대련을 하지 않아도 된다는 사실은 기뻐하고 있는 것 같지만...', `MaleText_loc4`='欢迎回来，$n！你的训练怎么样啦？$b$b我们的弟子都非常想念你……尽管我不得不说，他们对不用再和你过招这一点还是很高兴的。', `MaleText_loc5`='歡迎回來，$n!你的訓練進行得如何?$B$B我們的受訓弟子都很想念你...不過我得說，他們也都為不用和你練習對打而鬆一口氣。', `MaleText_loc7`='¡Hola de nuevo, $n! ¿Qué tal va tu entrenamiento?$b$bNuestros discípulos te han echado muchísimo de menos, pero debo decir que les gusta no tener que luchar más contigo.' WHERE `ID`=57136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망은 없다. 미래도 없지. 모든 생명은 끝이다.', `MaleText_loc4`='没有希望，没有未来。这是所有生命的末日。', `MaleText_loc5`='沒有希望，沒有未來。一切生命都將毀滅。', `MaleText_loc7`='No hay esperanza ni futuro. La vida está condenada.' WHERE `ID`=57137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈처럼, 온 아제로스가 불타리라.', `MaleText_loc4`='和你一样，整个艾泽拉斯都将燃烧。', `MaleText_loc5`='整個艾澤拉斯會跟你一樣燃燒。', `MaleText_loc7`='Como tú, todo Azeroth debe arder.' WHERE `ID`=57138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 세상도 곧 너처럼 만들어주마.', `MaleText_loc4`='这个世界即将步你后尘。', `MaleText_loc5`='你的世界馬上就會有一樣的下場。', `MaleText_loc7`='Sepan que su mundo será el siguiente.' WHERE `ID`=57139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용과 하나가 되게, $n. 용의 경험을 자네 것이라고 생각하고, 훈련을 통해 서로의 결속을 강화하게.', `FemaleText_loc4`='要与翔龙合为一体，$n。与它感同身受，加强你们之间的联系。', `FemaleText_loc5`='要和你的蛟龍一體同心，$n。感受蛟龍的體驗就如同你自身的體驗一般，並且加深你們之間的羈絆。', `FemaleText_loc7`='Tú y tu dragón deben ser uno, $n. Percibe los sentimientos de tu dragón como si fueran los tuyos y refuerza tu vínculo.' WHERE `ID`=57141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠도 무술 배울 수 있다.$b$b여기 있는 판다렌들 다 합쳐도 컨컨보다 무술 못한다. 특히 저기 있는 멍청한 진위, 영리한 애쉬요보다는 훨씬 더 잘한다.', `MaleText_loc4`='你要知道，猢狲也会学习武术。$b$b肯肯比其他所有人加起来都厉害，尤其是那个笨蛋锦鱼人聪明的阿西约。', `MaleText_loc5`='其實，猴人也能學武術。$b$b肯·肯比其他人加起來都厲害，尤其比聰明的艾須歐那個笨蛋錦魚人厲害。', `MaleText_loc7`='Los hozen también pueden aprender artes marciales, ¿tú sabe?$b$bKen-Ken mejor ke todos esos tipos juntos. Especialmente mejor ke esos Ashyo el Astuto y Jinyu el Tonto.' WHERE `ID`=57142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 비취 숲에 있는 티엔 수도원에서 막 수련을 마쳤답니다. 그곳에서 수련을 해보셨어요?$b$b우리는 이제 수련생이 아니에요. 첫 번째 모험을 하는 거죠. 바로 은둔 고수를 찾는 거랍니다.', `FemaleText_loc4`='我们刚从翡翠林中的天禅院毕业。你以前去过那儿吗？$b$b我们不再是弟子了。我们正在执行第一个任务——找到隐秘大师。', `FemaleText_loc5`='我們剛從翠玉林裡的天僧寺結業。你曾去過那裡嗎?$b$b今後我們不再是學生了。我們正在進行結業後的第一項任務:找到隱居的宗師。', `FemaleText_loc7`='Acabamos de graduarnos en el Monasterio Tian, en el Bosque de Jade. ¿Has estado allí alguna vez?$b$bYa no somos estudiantes, estamos en nuestra primera misión: buscar al maestro oculto.' WHERE `ID`=57143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님! 저 기억 나세요? 티엔 수도원에서?$b$b시간이 조금 걸리기는 했지만, 그래도 결국 수련을 마쳤어요! 샤오도 그렇고... 음, 여기 있는 친구들도 다 마쳤답니다.$b$b우리는 이제 수련생이 아니에요. 첫 번째 모험을 하고 있죠. 바로 은둔 고수를 찾는 거예요.', `FemaleText_loc4`='$n！是我！还记得我吗？天禅院的！$b$b虽然花了我不少时间，但我终于毕业了！晓也毕业了，还有……嗯，这里的所有人。$b$b我们不再是弟子了。我们正在执行第一个任务——找到隐秘大师。', `FemaleText_loc5`='$n!是我啊!記得嗎?天僧寺裡的?$b$b雖然花了點時間，但我終於結業了!曉也是，還有...好吧，就是你在這看到的所有人。$b$b今後我們不再是學生了。我們正在進行結業後的第一項任務:找到隱居的宗師。', `FemaleText_loc7`='¡$n! ¡Soy yo! ¿Te acuerdas de mí? ¿Del Monasterio Tian?$b$b¡Me ha llevado un tiempo, pero por fin me he graduado! Xiao también y... bueno, todos los demás que ves aquí.$b$bYa no somos estudiantes, estamos en nuestra primera misión: buscar al maestro oculto.' WHERE `ID`=57144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거지들, 그리고 강탈자들아. 네놈과 판다렌 놈들 모두 잿더미로 만들어주겠다.', `MaleText_loc4`='乞丐和逆贼，我们要把你和这群熊猫人盟友烧成灰烬。', `MaleText_loc5`='乞丐和篡位者們，我們會把你和你的熊貓人盟友燒成灰。', `MaleText_loc7`='Pedigüeños y usurpadores, tanto ustedes como sus aliados pandaren serán reducidos a cenizas.' WHERE `ID`=57145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 마을에 계신 장로님들께서 가르쳐주셨는데, 지식은 모든 강을 따라 흐르고, 모든 연못으로 모여든다고 하셨습니다. 이곳의 물에서는 어떤 지식을 얻을 수 있을지 궁금해서 못참겠군요.$b$b장로님들께서 가르쳐주신 게 또 하나 있는데 호젠은 절대로 믿지 말라고 하셨습니다.$b$b<컨컨을 의심스러운 눈초리로 쏘아보는 애쉬요>', `MaleText_loc4`='村里的长者曾教导我，每条河流里都流淌着智慧，每个池塘中汇聚着知识。我等不及想要知道这里的水能告诉我什么了。$b$b村里的长者还教导我，绝不要相信猢狲。$b$b<阿西约警惕地瞥了一眼肯肯。>', `MaleText_loc5`='我村子裡的長者教導我，智慧流淌在每一條河裡，儲存在每一片池水中。我等不及要學習這地方的水蘊含著什麼樣的知識。$b$b我村子裡的長者也教我永遠不要信任猴人。$b$b<艾須歐擔心地看了看肯·肯。>', `MaleText_loc7`='Los ancianos de mi aldea me enseñaron que la sabiduría fluye a lo largo de cada río, y se recoge en cada estanque. Estoy deseando conocer lo que las aguas de este lugar pueden ofrecer.$b$bLos ancianos de mi aldea me enseñaron también que nunca se debe confiar en un hozen.$b$b<Ashyo lanza una mirada de desconfianza a Ken-Ken.>' WHERE `ID`=57146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 우리가 수련한 능력을 쓸 기회가 온 거군요? 네 바람의 계곡에서 어떤 모험을 하게 될지 누가 알겠어요?', `MaleText_loc4`='终于有机会用上我们一直训练的技巧了。谁会知道我们会在四风谷中经历什么样的冒险呢？', `MaleText_loc5`='終於有機會讓我們使用訓練得來的技巧了。誰知道我們會在四風峽碰到什麼樣的冒險經歷?', `MaleText_loc7`='Por fin tengo la oportunidad de utilizar las habilidades para las que hemos estado entrenando. ¿Quién sabe qué aventuras nos encontraremos aquí, en el Valle de los Cuatro Vientos?' WHERE `ID`=57147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡을 잃어버렸습니다! 정신의 고리를 다시 한 번 연결해 주실 수 있으십니까?', `MaleText_loc4`='我的翔龙走失了！你能帮我重新建立灵魂链接吗？', `MaleText_loc5`='我失去了我的蛟龍!你能幫我重新建立靈魂連結嗎?', `MaleText_loc7`='¡He perdido a mi dragón! ¿Podrías realizar el enlace de espíritu otra vez?', `FemaleText_loc1`='운룡을 잃어버렸습니다! 정신의 고리를 다시 한 번 연결해 주실 수 있으세요?', `FemaleText_loc4`='我的翔龙走失了！你能帮我重新建立灵魂链接吗？', `FemaleText_loc5`='我失去了我的蛟龍!你能幫我重新建立靈魂連結嗎?', `FemaleText_loc7`='¡He perdido a mi dragón! ¿Podrías realizar el enlace de espíritu otra vez?' WHERE `ID`=57148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐다, 이제 이걸 누구한테 시험해 봐야 하는데...', `MaleText_loc4`='好了，现在我们得找人来试试这个……', `MaleText_loc5`='好吧，現在我們需要來個人測試一下這玩意兒...', `MaleText_loc7`='Ahora nosotros necesitan a alguien en kien probar esto...' WHERE `ID`=57149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 너! 이리 와 봐. 컨컨 너한테 딱 좋은 것 갖고 있다.', `MaleText_loc4`='你！快过来，闲人。肯肯给你准备了好东西！', `MaleText_loc5`='你!過來這裡，阿呆。肯·肯拿了這東西要給你!', `MaleText_loc7`='¡Tú! Viene akí, tristón. ¡Ken-Ken tiene justo lo ke tú necesita!' WHERE `ID`=57150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구? 나 말이오?', `MaleText_loc4`='谁，我吗？', `MaleText_loc5`='誰，我嗎?', `MaleText_loc7`='¿Quién, yo?' WHERE `ID`=57151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러지, 뭐. 무슨 일이든 여기서 더 나빠지기야 하겠소...', `MaleText_loc4`='没问题，反正事情也不会变得更糟……', `MaleText_loc5`='當然，反正事情不會再更糟了...', `MaleText_loc7`='Claro. Total, la cosa no puede ir a peor...' WHERE `ID`=57152;
