UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 성공이다! 컨컨 성공할 줄 알았다! 이제 기분이 한결 낫지?', `MaleText_loc4`='哈哈哈！起作用了！肯肯知道一定有用！你现在感觉好些了吗？', `MaleText_loc5`='哈哈哈!有效耶!肯·肯知道這個會有效!你現在覺得好多了吧?', `MaleText_loc7`='¡Ja, ja, ja! ¡Funciona! ¡Ken-Ken sabe ke funciona! ¿Tú te siente mejor ahora?' WHERE `ID`=57158;
