UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 움직여라, 멍청한 놈들아. 우리는 이 유물이 급히 필요하다. 게으름 피우는 놈들은 혼쭐을 내주겠다.', `MaleText_loc4`='快一点，你们这些笨蛋。我们急需这些神器，否则你们就等着挨鞭子吧。', `MaleText_loc5`='快一點，你們這些笨瓜。我們得儘快把這裡所有的神器搬完，不然你們就要討皮痛了。', `MaleText_loc7`='Más rápido, idiotas. Necesitamos todos estos artefactos pronto u os moleremos a palos.' WHERE `ID`=57161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 가면을 쓰면 슬플 수가 없지! 자, 누구한테 시험하면 되냐?', `MaleText_loc4`='不管是谁，只要戴上这样的面具，都再也悲伤不起来了！现在，我们该找谁来试验一下？', `MaleText_loc5`='沒有人戴著這個面具還會覺得悲傷!現在，我們還可以拿誰來測試看看?', `MaleText_loc7`='¡Nadie puede estar triste si lleva una máskara komo esta! Bueno, ¿kon kién nosotros pueden probarla?' WHERE `ID`=57162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침 잘 왔다! 이리 와 봐라, 친구. 지난번에는 미안했다. 이거 한번 써 봐라.', `MaleText_loc4`='好极了！过来，伙计。上次真是不好意思！把这个戴上吧。', `MaleText_loc5`='太完美了!到這裡來，老兄。上次真的很抱歉!把這個戴上。', `MaleText_loc7`='¡Perfekto! Ven aká, kolega. ¡Tú perdona lo de la última vez! Tú pon esto.' WHERE `ID`=57163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으... 그때 그건 뭐였소? 상한 차를 마신 것처럼 속이 안 좋았소.', `MaleText_loc4`='呃……那玩意是什么？就像是喝了馊茶水。', `MaleText_loc5`='噁...那是什麼玩意兒?喝起來像壞掉的茶。', `MaleText_loc7`='Aah... ¿qué era eso? Me ha sentado peor que un té caducado.', `FemaleText_loc1`='으... 그때 그건 뭐였죠? 상한 차를 마신 것처럼 속이 안 좋았어요.', `FemaleText_loc4`='呃……那玩意是什么？就像是喝了馊茶水。', `FemaleText_loc5`='噁...那是什麼玩意兒?喝起來像壞掉的茶。', `FemaleText_loc7`='Aah... ¿qué era eso? Me ha sentado peor que un té caducado.' WHERE `ID`=57164;
