UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 영웅님! 고맙소! 남들에게도 당신의 이야기를 들려줘야겠소! 강력한 $p 님의 이야기 말이오! 두려움을 모르는 컨컨의 이야기도!', `MaleText_loc4`='真是太感谢了，勇敢的英雄们！我要歌颂你们的事迹！强大的$p！还有无畏者肯肯！', `MaleText_loc5`='真是太感謝你們了，英雄!我會傳頌你們的故事!關於偉大的$p!還有無懼的肯·肯!', `MaleText_loc7`='¡Muchas gracias, valientes héroes! ¡Narraré historias sobre ustedes! ¡Sobre $p $gel:la; Valiente! ¡Y Ken-Ken el Intrépido!', `FemaleText_loc1`='용감한 영웅님! 고맙소! 남들에게도 당신의 이야기를 들려줘야겠소! 강력한 $p 님의 이야기 말이오! 두려움을 모르는 컨컨의 이야기도!', `FemaleText_loc4`='真是太感谢了，勇敢的英雄们！我要歌颂你们的事迹！强大的$p！还有无畏者肯肯！', `FemaleText_loc5`='真是太感謝你們了，英雄!我會傳頌你們的故事!關於偉大的$p!還有無懼的肯·肯!', `FemaleText_loc7`='¡Muchas gracias, valientes héroes! ¡Narraré historias sobre ustedes! ¡Sobre $p $gel:la; Valiente! ¡Y Ken-Ken el Intrépido!' WHERE `ID`=57168;
