UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘에 얼라이언스의 눈이 있을지 모르니 잘 살피게. 천둥 틈새에서 다시 만나세. 헬스크림 님께서 자네를 지켜보실 걸세.', `MaleText_loc4`='留意联盟在空中的眼线。我会在雷霆裂口等你回来。地狱咆哮之眼会注视着你。', `MaleText_loc5`='注意天空中的聯盟耳目，我會在雷霆斷崖和你再見。地獄吼的雙眼在盯著你。', `MaleText_loc7`='Observa los cielos en busca de ojos de la Alianza. Nos veremos de nuevo en Grieta del Trueno. Los ojos de Grito Infernal te vigilan.' WHERE `ID`=57183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 밀림은 부자연스러운 절망감으로 가득하오.', `MaleText_loc4`='丛林中充满了异常的绝望感。', `MaleText_loc5`='整個叢林瀰漫著一股不尋常的絕望氣息。', `MaleText_loc7`='Esta jungla está llena de una sensación sobrenatural de desesperación.' WHERE `ID`=57184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 내게 허한 능력을 이 땅의 슬픔이 억누르고 있소.$b$b아내가 고통받고 있는데도 할 수 있는 일이 없다오.', `MaleText_loc4`='土地中的悲伤正在侵蚀圣光赐予我的天赋。$b$b我的妻子，她正备受煎熬，可我完全无法帮助她。', `MaleText_loc5`='世界上最令人悲傷的事，就是壓抑聖光賜予我的天賦。$b$b我的太太正在受苦，而我的天賦卻一點忙也幫不上她。', `MaleText_loc7`='La tristeza de la tierra está socavando los dones que me concedió la Luz.$b$bMi esposa está sufriendo y ninguna de mis virtudes puede ayudarla.' WHERE `ID`=57185;
