UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다시 일어날 것이며, 네놈 족속들은 우리의 종이 될 것이다!', `MaleText_loc4`='我们会再次崛起，你们这些家伙都将成为奴隶！', `MaleText_loc5`='我們會再次強盛，而像你這樣的人可以做我們的僕人!', `MaleText_loc7`='¡Volveremos a levantarnos, y los de tu clase serán obligados a servir!' WHERE `ID`=57190;
