UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브램블스태프의 분노를 보여주지요!', `MaleText_loc4`='面对棘杖的愤怒吧！', `MaleText_loc5`='面對藤杖的怒火吧!', `MaleText_loc7`='¡Enfréntate a la cólera de los Vara Enzarzada!' WHERE `ID`=57198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 놈을 너무 세게 때려서 그놈의 조상까지도 아파했을 거예요.', `MaleText_loc4`='我想我打得太重了，连他的祖宗都感觉到了。', `MaleText_loc5`='我想我打他打得太用力，連他的祖宗都感覺到了。', `MaleText_loc7`='Creo que le he golpeado tan fuerte que lo han podido sentir hasta sus antepasados.' WHERE `ID`=57199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네싱워리 탐험대 나머지 대원들은 네 바람의 계곡 서쪽에 있어요. 혹시 서쪽에 갈 일이 있으면 우릴 찾아 오세요. 사냥 잘해요!', `FemaleText_loc4`='奈辛瓦里狩猎队营地的其他人正在四风谷的西边。倘若你正向西行，你就该加入我们。狩猎愉快！', `FemaleText_loc5`='奈辛瓦里狩旅團的其他人就在四風峽的西邊。如果你要到西邊去，可以來找我。狩獵愉快!', `FemaleText_loc7`='El resto del Safari de Nesingwary se encuentra en el flanco occidental del Valle de los Cuatro Vientos. Si vas hacia el oeste, únete a nosotros. ¡Buena caza!' WHERE `ID`=57200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 어떻게 왔습니까?', `MaleText_loc4`='你怎么到这儿的？', `MaleText_loc5`='你怎麼來到這裡的?', `MaleText_loc7`='¿Cómo has llegado hasta aquí?', `FemaleText_loc1`='이곳엔 어떻게 왔나요?', `FemaleText_loc4`='你怎么到这儿的？', `FemaleText_loc5`='你怎麼來到這裡的?', `FemaleText_loc7`='¿Cómo has llegado hasta aquí?' WHERE `ID`=57201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 네싱워리 탐험대 대원이에요. 우리는 열기구를 타고 안개 속을 날다가 우연히 이 땅을 발견했지요.$b$b네싱워리 님과 아드님은 저 북쪽에서 발굽동물 따위를 잡고 싶어 하더군요.$b$b저는 진짜 야수들이 있는 밀림으로 와서 선수를 치기로 했어요.$b$b근데 로켓을 타고 오다가 호랑이들이 득시글거리는 곳에 떨어졌지요.', `FemaleText_loc4`='我是奈辛瓦里狩猎队的成员。我们乘坐热气球穿过迷雾的时候偶然发现了这片大陆。$b$b奈辛瓦里和他的儿子想要去北边狩猎一些有蹄类动物。$b$b我决定抢先一步，去丛林里探寻真正的野兽。$b$b坐上火箭降落之后，我就发现自己身陷老虎堆了。', `FemaleText_loc5`='我是奈辛瓦里狩旅團的一員。我們乘坐熱氣球穿過一片迷霧，然後來到這片土地。$b$b奈辛瓦里和他的孩子在北邊打一些無聊的有蹄動物。$b$b我決定搶先他們一步，進到叢林裡找真正的野獸。$b$b過了不久，我就能奪得先機。', `FemaleText_loc7`='Soy parte del Safari de Nesingwary. Íbamos en nuestro globo de aire caliente atravesando unas brumas cuando nos encontramos con estas tierras.$b$bNesingwary y su muchacho querían cazar algunos ungulados y todo eso, al norte.$b$bYo decidí tomarles la delantera y venir a la jungla, donde están las bestias de verdad.$b$bDespués de un viaje en cohete, estoy hasta el cuello de tigres.' WHERE `ID`=57202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c? 이런 곳에? 게다가 호드라니.$b$b당신이 도와줄 마음만 있다면 우리에게 많은 도움이 되겠군.$b$b우리는 예언과 꿈을 따라 이곳에 왔는데, 악몽이 우릴 기다리고 있었다네.', `MaleText_loc4`='一个$c？在这儿？而且还是个部落的人。$b$b如果你愿意帮忙，你的能力会派上很大用场。$b$b我们追随幻象和梦境而来，可到头来发现等着我们的却是个梦靥。', `MaleText_loc5`='一個$c?在這種地方?想必還有部落。$b$b如果願意，你可以幫我們很大的忙。$b$b我們跟隨幻象和夢境的指示來到這裡，卻發現等著我們的只是一個夢魘。', `MaleText_loc7`='¿$gUn:Una; $c? ¿Aquí? Y de la Horda, nada menos.$b$bNos vendrías muy bien si quisieras ayudarnos.$b$bSeguimos visiones y sueños para llegar hasta aquí, pero lo único que hemos encontrado ha sido una pesadilla.' WHERE `ID`=57205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐냐 이건... 고약한 샤 놈들 여기저기서 튀어나오고 있다! 이놈들부터 처리해야 된다!', `MaleText_loc4`='怎么……到处都是该死的煞！我们得先解决他们！', `MaleText_loc5`='可惡...到處都有煞跑出來!我們必須先料理他們!', `MaleText_loc7`='Pero ké... ¡askerosos sha salen de todas partes! ¡Nosotros tiene ke okuparnos de ellos primero!' WHERE `ID`=57206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐다. 이제 시간이 없다. 이모우를 도와줘야 된다! 이모우한테 가면 씌우자!', `MaleText_loc4`='好了，没时间了。易默需要帮助！我们得给他找个面具！', `MaleText_loc5`='好了，沒時間了。易謀現在就需要協助!我們掩護他!', `MaleText_loc7`='No hay tiempo. ¡Yi-Mo necesita ayuda ya! ¡Nosotros ponen a él una máskara!' WHERE `ID`=57207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지와 저는 독특한 사냥 여행을 하고 있습니다. 기묘하고도 새로운 이 땅 모든 곳에는 위험이 잔뜩 도사리고 있고, 구덩이가 있는 곳마다 괴물들이 튀어나오는 데다가, 오래된 토양만큼이나 나이가 많은 야수들이 겁 없이 나돌아다니고 있습니다.$b$b이제 사냥철이 왔군요!', `MaleText_loc4`='父亲和我正在进行一次真正的远征。这是一片陌生又新奇的土地，每个转角处都危机四伏，每个洞穴里都潜伏着怪物，与这片土地同样古老的野兽毫无畏惧地恣意生活着。$b$b狩猎的季节到了！', `MaleText_loc5`='我老爸跟我在進行一場名符其實的狩獵。這是一塊奇特的新土地，每個轉彎處都存在著危險，每個洞裡都有怪物探出頭來，還有不知道何謂恐懼的古老野獸。$b$b打獵季節到了!', `MaleText_loc7`='Mi padre y yo estamos en un auténtico safari. Esta es una tierra nueva y extraña, llena de peligros a cada paso, con monstruos que salen de cada agujero y fieras más viejas que la propia tierra que viven sin miedo.$b$b¡Es temporada de caza!' WHERE `ID`=57208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보시오, 거기 $p! 예전에 제대로 된 사냥을 함께해본 이후로는 아주 오랜만이군. 안 그렇소? 조준 실력이 무뎌지지는 않았는지 한번 봐야겠군.', `MaleText_loc4`='嘿，你好啊，$p！我们似乎已经很久没一起像样地狩猎了，是吧？让我们瞧瞧时间有没有磨光你的战力。', `MaleText_loc5`='你好啊，$p!距離我們上次一起好好狩獵可有好一段時間了，對吧。我們來看看時間有沒有讓你失去準頭。', `MaleText_loc7`='¡Alto ahí, $p! Hace mucho que no coincidimos en una cacería como es debido, ¿verdad? Veamos si el tiempo ha debilitado tu puntería.' WHERE `ID`=57209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:106794|h[산탄 파편]|h|r에 의해 목숨을 잃었습니다! |cFF04FC32|Hspell:106466|h[꿈]|h|r을 이용해 피해를 막으십시오.', `MaleText_loc4`='|cFFFF0000|Hspell:106794|h[碎屑]|h|r杀死了你！使用|cFF04FC32|Hspell:106466|h[梦境]|h|r来避免受到伤害。', `MaleText_loc5`='你被|cFFFF0000|Hspell:106794|h[破片]|h|r殺死了!使用 |cFF04FC32|Hspell:106466|h[夢境]|h|r來防止傷害。', `MaleText_loc7`='|cFFFF0000|Hspell:106794|h¡[Metralla]|h|r te ha matado! Usa |cFF04FC32|Hspell:106466|h[Sueño]|h|r para evitar el daño.' WHERE `ID`=57210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:105723|h[엘레멘티움 화살]|h|r에 의해 목숨을 잃었습니다. 화살이 떨어지는 지점을 피하면, 받는 피해가 줄어듭니다.', `MaleText_loc4`='|cFFFF0000|Hspell:105723|h[源质箭]|h|r杀死了你。远离源质箭落地的区域以降低伤害。', `MaleText_loc5`='你被|cFFFF0000|Hspell:105723|h[源質箭]|h|r殺死了。從衝擊點跑開以減少它的傷害。', `MaleText_loc7`='¡La |cFFFF0000|Hspell:105723|h[Descarga de elementium]|h|r te ha matado! Sal del punto de impacto para reducir el daño de la descarga.' WHERE `ID`=57211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 끝났다! 하던 일을 멈추고 절망에 굴복하라!', `MaleText_loc4`='一切都完了！放弃抵抗，向你的绝望屈服吧！', `MaleText_loc5`='全都完了!躺下來淹沒於絕望中吧!', `MaleText_loc7`='¡ESTÁ TODO PERDIDO! ¡ENTRÉGENSE A SU DESESPERACIÓN!' WHERE `ID`=57212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 용이 곧 도착할 겁니다. 행운을 빕니다!', `FemaleText_loc4`='你的翔龙马上就到了，祝你好运！', `FemaleText_loc5`='你的蛟龍很快就會到來。祝好運!', `FemaleText_loc7`='Tu dragón vendrá en un instante. ¡Buena suerte!' WHERE `ID`=57213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈드블레이드 교관님, 제 운룡을 다시 불러 주실 수 있으십니까?', `MaleText_loc4`='风刃教头，你能再帮我召唤一次翔龙吗？', `MaleText_loc5`='講師風刃，你能再幫我呼喚一次蛟龍嗎。', `MaleText_loc7`='Maestra Hoja Liviana, ¿podría llamar a mi dragón otra vez?', `FemaleText_loc1`='윈드블레이드 교관님, 제 운룡을 다시 불러 주실 수 있으신가요?', `FemaleText_loc4`='风刃教头，你能再帮我召唤一次翔龙吗？', `FemaleText_loc5`='講師風刃，你能再幫我呼喚一次蛟龍嗎。', `FemaleText_loc7`='Instructora Hoja Liviana, ¿podrías volver a llamar a mi dragón?' WHERE `ID`=57214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡이 도착하고 있습니다. 준비가 되면 올라타세요.', `FemaleText_loc4`='你的翔龙已经到了，准备好后就骑上去吧。', `FemaleText_loc5`='你的蛟龍到了。準備好就上座吧。', `FemaleText_loc7`='Tu dragón llegará ahora. Monta en él cuando estés $gpreparado:preparada;.' WHERE `ID`=57215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용 조련사가 되는 여정은 꽤나 힘든 길입니다. 도전할 준비가 되셨습니까?', `FemaleText_loc4`='想要成为一个翔龙大师，道路是异常艰辛的。你准备好接受挑战了吗？', `FemaleText_loc5`='成為蛟龍訓練師的旅程並不簡單。你準備好接受挑戰了嗎?', `FemaleText_loc7`='El camino para convertirse en un maestro de dragones es difícil. ¿Aceptas el reto?' WHERE `ID`=57216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡단에서 지위를 높이는 데는 엄청난 헌신이 필요합니다. 당신께 행운을 빌어드리겠습니다.', `FemaleText_loc4`='想要晋升为翔龙骑士，就需要付出极大的牺牲。我祝你好运。', `FemaleText_loc5`='你必須奉獻心力，才能在雲蛟衛中脫穎而出。祝你好運。', `FemaleText_loc7`='La dedicación plena es necesaria para ascender en la jerarquía de la Orden del Dragón Nimbo. Que tengas suerte.' WHERE `ID`=57217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄이 목숨을 잃었습니다! 스랄이 피해를 입지 않게 하려면 타락한 수액괴물을 처치하십시오.', `MaleText_loc4`='萨尔被杀死了！攻击腐蚀软泥怪以使他避免受到伤害。', `MaleText_loc5`='索爾被殺死了!攻擊腐化的泥漿怪來防止他受傷。', `MaleText_loc7`='¡Thrall ha muerto! Ataca a las babosas corruptas para evitar que reciba daño.', `FemaleText_loc1`='스랄이 목숨을 잃었습니다! 스랄이 피해를 입지 않게 하려면 타락한 수액괴물을 처치하십시오.', `FemaleText_loc4`='萨尔被杀死了！攻击腐蚀软泥怪以使他避免受到伤害。', `FemaleText_loc5`='索爾被殺死了!攻擊腐化的泥漿怪來防止他受傷。', `FemaleText_loc7`='¡Thrall ha muerto! Ataca a las babosas corruptas para evitar que reciba daño.' WHERE `ID`=57218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속바지 한 벌만 입고 사냥칼 달랑 한 자루로 설인과 홀로 맞서 싸워 이긴다면 당신도 "행운아" 칭호를 얻을 겁니다.', `MaleText_loc4`='要是你全身上下只围着一根腰带，手里拿着一把猎刀，单枪匹马地跟雪人单挑，那你也能为自己赢得“幸运”的称号。', `MaleText_loc5`='只帶著長獵刀，穿著兜檔布，獨自一人去對付雪人，你也會幫自己贏得一個「幸運」的稱號。', `MaleText_loc7`='Enfréntate a solas con un yeti sin nada más que un cuchillo y llevando un taparrabos, y tú también te ganarás el título de "afortunado".' WHERE `ID`=57219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이모우는 당장은 괜찮을 거다. 일단 저 고약한 놈들부터 처리해야 된다!', `MaleText_loc4`='易默现在没事了，我们得先解决这些麻烦！', `MaleText_loc5`='易謀會沒事的，我們必須先處理這團混亂!', `MaleText_loc7`='Yi-Mo estará bien de momento... ¡Nosotros tienen ke akabar primero kon estos bichos askerosos!' WHERE `ID`=57220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신이 드는 모양입니다!', `MaleText_loc4`='$G他:她;醒过来了！', `MaleText_loc5`='$G他:她;來了!', `MaleText_loc7`='¡Se está despertando!' WHERE `ID`=57221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 운룡단의 수련생들은 하늘 경주라고 하는 시합에서 서로 비행 솜씨를 겨룬답니다.', `FemaleText_loc4`='我们骑士团的学员们会在名为“飞行竞技赛”的比赛中一较高下。', `FemaleText_loc5`='雲蛟衛的學生在名為天際競賽的比賽中測試他們的速度。', `FemaleText_loc7`='Los estudiantes de nuestra Orden ponen a prueba su velocidad en una competición aérea conocida como la carrera de los cielos.' WHERE `ID`=57222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘 경주의 규칙을 알려드릴게요. 절 따라오세요!', `FemaleText_loc4`='我会将比赛的规则传授给你。跟我来！', `FemaleText_loc5`='我會教你比賽的規則。跟上來!', `FemaleText_loc7`='Te enseñaré las reglas de la carrera. ¡Sígueme!' WHERE `ID`=57223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이 고대의 의식이 진짜 되는지 한번 해봐야겠군요..', `MaleText_loc4`='好吧，让我们看看这古老的仪式能不能起作用。', `MaleText_loc5`='好吧，我們看看這個老儀式管不管用。', `MaleText_loc7`='Vale, vamos a ver si este ritual funciona.' WHERE `ID`=57224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두고 보십시오, 아버지. 제가 아주 큰 사냥감을 잡아올 겁니다.', `MaleText_loc4`='你等着瞧吧，爸爸。我会逮个大的回来。', `MaleText_loc5`='你會明白的，老爸。我會幫我自己獵隻大的。', `MaleText_loc7`='Ya verás, papá. Voy a cazar uno de los grandes.' WHERE `ID`=57225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1단계는 춤을 춥니다.', `MaleText_loc4`='第一步：跳舞。', `MaleText_loc5`='第一步:跳舞。', `MaleText_loc7`='Paso uno: bailar.' WHERE `ID`=57226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2단계는 이렇게 말하는 겁니다. "고통의 물이여, 내 부름에 응하라. 그리고 토자리의 파멸을 불러 일으켜라!"', `MaleText_loc4`='第二步：说出下面这句话——“痛苦之水，听我召唤，现身吧，托加尔之怨！”', `MaleText_loc5`='第二步:唸出這個句子。「聽從我的呼喚，痛苦之泉，並且現身，托加的禍害!」', `MaleText_loc7`='Paso dos: decir las palabras. "¡Oíd mi llamada, aguas del dolor, y traed la Perdición de Torjari!"' WHERE `ID`=57227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 부르십니다.', `MaleText_loc4`='主人在召唤。', `MaleText_loc5`='主人在呼喚。', `MaleText_loc7`='El amo nos llama.' WHERE `ID`=57228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이젠 주문까지 외우는 건가?', `MaleText_loc4`='噢，你现在是要回霍克噗克去吗？', `MaleText_loc5`='喔，你現在打算求助於魔法了是吧?', `MaleText_loc7`='Oh, ¿así que recurres a brujerías?' WHERE `ID`=57229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아! 안 돼애애애!', `MaleText_loc4`='儿子！不——！', `MaleText_loc5`='二世!不不不!', `MaleText_loc7`='¡Junior! ¡Nooooo!' WHERE `ID`=57230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요! 아들을 구해야 합니다!', `MaleText_loc4`='来吧！我们得救救我的孩子！', `MaleText_loc5`='快!我們得救出我的孩子!', `MaleText_loc7`='¡Vamos! ¡Tenemos que salvar a mi chico!' WHERE `ID`=57231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p! 괜찮냐? 일어나라!', `MaleText_loc4`='$p！你还好吗？快醒醒！', `MaleText_loc5`='$p!你沒事吧?醒一醒!', `MaleText_loc7`='¡$p! ¿Tú está bien? ¡Despierta!' WHERE `ID`=57232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련을 계속할수록 속도가 빨라질 겁니다. 열심히 따라오세요.', `FemaleText_loc4`='我会在练习过程中加快速度，试着跟上我。', `FemaleText_loc5`='我在練習中會持續加速。試著跟上。', `FemaleText_loc7`='Iré aumentando la velocidad a medida que avance el ejercicio. Intenta seguirme.' WHERE `ID`=57233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저와 너무 멀리 떨어지면, 제가 경고해드릴게요. 그 후에도 계속 멀어지면, 훈련을 중단하겠습니다.', `FemaleText_loc4`='如果你离开太远，我会向你发出警告。要是你还不回头，我就会立即判你不及格。', `FemaleText_loc5`='如果你跑得太遠，我會警告你。如果你繼續亂跑，我會立刻宣告你失去資格。', `FemaleText_loc7`='Si te alejas demasiado, te avisaré. Si sigues desviándote, no dudaré en suspenderte.' WHERE `ID`=57234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 밧줄로 당신을 안내할 거예요. 너무 멀리 떨어지면 밧줄이 끊어지고, 그러면 훈련을 다시 시작해야 해요.', `FemaleText_loc4`='我会用这根绳索来引导你。如果你离我太远，绳索就会断掉，而我也只能重新开始训练了。', `FemaleText_loc5`='我會用這繩子來引導你。如果你跑太遠了，它就會斷裂。我們也必須重新開始練習。', `FemaleText_loc7`='Te guiaré con esta cuerda. Si te alejas demasiado, se romperá y tendremos que empezar desde el principio.' WHERE `ID`=57235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위쪽에 늘어진 밧줄과 삼각 깃발들이 보이세요? 경주로를 표시하고 있어요. 혹시라도 경로에서 벗어나면, 저 삼각 깃발을 따라가세요.', `FemaleText_loc4`='你看见我们头顶上方的那一串三角旗了么？我们用这些旗帜标出了赛道。要是你迷了路，可以根据这些旗帜找到方向。', `FemaleText_loc5`='你有看到我們頭上那條旗子嗎?那些旗子標示出比賽的路線。如果你迷路了，可以利用這些旗子來辨別方向。', `FemaleText_loc7`='¿Ves las grímpolas que ondean sobre nosotros? Son las banderas que marcan el recorrido de la carrera. Si te pierdes, úsalas como guía.' WHERE `ID`=57236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 시험을 거치면서, 당신과 운룡의 유대는 더 강해집니다.', `FemaleText_loc4`='在你通过这些考验后，你和你的翔龙之间的羁绊将会变得越来越稳固。', `FemaleText_loc5`='藉由這些試煉，你和你蛟龍之間的連結也會加強。', `FemaleText_loc7`='Superar estas pruebas reforzará el vínculo entre tu dragón y tú.' WHERE `ID`=57237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 따라오십시오, $n 님.', `FemaleText_loc4`='跟紧我，$n。', `FemaleText_loc5`='跟在我身邊，$n。', `FemaleText_loc7`='Quédate conmigo, $n.' WHERE `ID`=57238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 나중에 혼자 비행할 때, 적이 저처럼 친절한 대접을 해줄 거라고는 생각하지 마세요.', `FemaleText_loc4`='当你以后独当一面时，你的敌人可不会像我这般客气。', `FemaleText_loc5`='等你獨立的時候，你的敵人不會像我一樣仁慈。', `FemaleText_loc7`='Cuando estés $gsolo:sola;, los enemigos no serán tan considerados como yo.' WHERE `ID`=57239;
