UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거의 도착했습니다. 목적지까지 일직선으로 달리기만 하면 됩니다!', `FemaleText_loc4`='我们就快完成了，坚持到底！', `FemaleText_loc5`='我們就快到了。最後衝刺!', `FemaleText_loc7`='Casi hemos terminado. ¡Solo queda la recta final!' WHERE `ID`=57245;
