UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 뒤쳐졌습니다!', `FemaleText_loc4`='你落后太多了！', `FemaleText_loc5`='你落後太遠了!', `FemaleText_loc7`='¡Te has quedado atrás!' WHERE `ID`=57247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 따라오셔야 합니다, $n 님. 너무 떨어지시면 훈련에 실패할 거예요.', `FemaleText_loc4`='你得跟上我，$n。要是离得太远，这场练习你就失败了。', `FemaleText_loc5`='你必須跟著我，$n。若跑得太前面。練習就會失敗。', `FemaleText_loc7`='Tienes que seguir mi ritmo, $n. Si te alejas demasiado, fallarás el ejercicio.' WHERE `ID`=57248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 시도하려면 말씀하세요.', `FemaleText_loc4`='等你准备好再试一遍的时候，来找我谈谈。', `FemaleText_loc5`='準備好再次嘗試時就來跟我說。', `FemaleText_loc7`='Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=57249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='통과 지점 10곳을 모두 통과해야 경주를 끝마칠 수 있습니다.', `FemaleText_loc4`='你必须飞过所有10个检查点，才能结束比赛。', `FemaleText_loc5`='你需要飛過10個檢查點來完成賽程。', `FemaleText_loc7`='Debes atravesar los 10 puntos de control para completar la carrera.' WHERE `ID`=57250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실제 경주에서는, 각각의 체크무늬 깃발을 통과해야 통과 지점을 통과했다고 인정받을 수 있습니다.', `FemaleText_loc4`='在真正的比赛中，你必须飞过每个方格旗的检查点，才能得分。', `FemaleText_loc5`='在真正的比賽中，你會需要飛過每面檢查旗子來獲得通過檢查點的認證。', `FemaleText_loc7`='En la carrera de verdad, tendrás que volar a través de cada bandera a cuadros para que se considere que has pasado el punto de control.' WHERE `ID`=57251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 멀리 떨어졌습니다! 교관에게 가까이 가세요!', `FemaleText_loc4`='你离得太远啦！快跟紧你的教头！', `FemaleText_loc5`='你跑太遠了!跟緊你的指導者!', `FemaleText_loc7`='¡Te has alejado! ¡Acércate a tu instructor!' WHERE `ID`=57252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 뭐라고요?... 누구십니까? 제가 여기 어떻게 온 거죠?', `MaleText_loc4`='噢……什么……谁？我是怎么到这儿来的？', `MaleText_loc5`='喔...啥...誰?我怎麼會到這裡來?', `MaleText_loc7`='Oh... ¿qué... quién? ¿Cómo he llegado hasta aquí?' WHERE `ID`=57253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송해요, 제가 이렇게 말썽만 피워서...', `MaleText_loc4`='对不起，我把一切都搞砸了。', `MaleText_loc5`='抱歉我把事情搞得一團亂。', `MaleText_loc7`='Siento haber causado este lío.' WHERE `ID`=57254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 사랑합니다.', `MaleText_loc4`='我爱你，爸爸。', `MaleText_loc5`='老爸我愛你。', `MaleText_loc7`='Te quiero, papá.' WHERE `ID`=57255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아, 아들아! 이제 정신 좀 차리거라.', `MaleText_loc4`='儿子！儿子！打起精神来！', `MaleText_loc5`='二世!二世!振作起來。', `MaleText_loc7`='¡Junior! ¡Junior! Despierta.' WHERE `ID`=57256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아, 아들아! 이제 정신 좀 차리거라.', `MaleText_loc4`='儿子！儿子！打起精神来！', `MaleText_loc5`='二世!二世!振作起來。', `MaleText_loc7`='¡Junior! ¡Junior! Despierta.' WHERE `ID`=57257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이러지 말거라, 아들아. 너는 이것보다 더 강하지 않니.', `MaleText_loc4`='加油，小子，你比这家伙强大得多。', `MaleText_loc5`='振作點孩子，你比這東西更強壯。', `MaleText_loc7`='Vamos, chico, eres más fuerte que esto.' WHERE `ID`=57258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님이 오고 있단다. 여기서 나가도록 도와주실 거야.', `MaleText_loc4`='$p来了。他们能帮忙带你离开这里。', `MaleText_loc5`='$p來了。他們可以協助我們讓你離開這裡。', `MaleText_loc7`='$p viene para acá. Puede ayudarnos a sacarte de aquí.' WHERE `ID`=57259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 오십니다.', `MaleText_loc4`='主人来了。', `MaleText_loc5`='主人來了。', `MaleText_loc7`='Viene el amo.' WHERE `ID`=57260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<헤멧 네싱워리 2세를 흔들어봅니다.>', `MaleText_loc4`='<试着摇晃赫米特。>', `MaleText_loc5`='<試著搖晃赫米特。>', `MaleText_loc7`='<Intenta agitar a Hemet.>', `FemaleText_loc1`='<헤멧 네싱워리 2세를 흔들어봅니다.>', `FemaleText_loc4`='<试着摇晃赫米特。>', `FemaleText_loc5`='<試著搖晃赫米特。>', `FemaleText_loc7`='<Intenta agitar a Hemet.>' WHERE `ID`=57262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 구석을 조심하십시오. 뭔가 다가오는 소리를 들었습니다.', `MaleText_loc4`='$p，注意四周。我想我听到了什么声音。有东西靠近了。', `MaleText_loc5`='$p，注意角落。我想我聽到了什麼。', `MaleText_loc7`='$p, atención a las esquinas. Creo que he oído algo.' WHERE `ID`=57263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하필이면 사냥꾼인 나를 사냥감으로 골랐구나! $p 님, 제가 더 잘 맞출 수 있게 저놈을 약간 멀리 유인하십시오.', `MaleText_loc4`='你选错猎手了！$p，把那家伙引远点儿，我才能射得更准。', `MaleText_loc5`='$p，你選了錯誤的獵人進行狩獵!把那東西拉遠一點，這樣我比較好瞄準。', `MaleText_loc7`='¡Has elegido cazar al cazador equivocado! $p, aleja un poco a esa cosa para que tenga una mejor línea de tiro.' WHERE `ID`=57264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 우리가 해냈다! 놈들 엉덩이를 시원하게 걷어차 줬다!', `MaleText_loc4`='我们成功了，$p！干得漂亮！', `MaleText_loc5`='$p，我們成功了!這可是一次漂亮的反擊!', `MaleText_loc7`='¡Nosotros lo han konseguido, $p! ¡Nosotros han pateado traseros a base de bien!' WHERE `ID`=57265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님... 두 번씩이나 목숨을 걸고 저를 구해주셨는데... 저는 당신을 무시하기만 했군요.', `MaleText_loc4`='$p……你竟然冒生命危险来救我——还救了两次，可我却对你不屑一顾。', `MaleText_loc5`='$p...想到你冒著生命危險救我，而且是第二次了，而我卻一直那麼瞧不起你。', `MaleText_loc7`='$p... pensar que has arriesgado tu vida por mí, dos veces ya, y yo no he hecho más que tratarte con desdén.' WHERE `ID`=57266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 부끄럽기 그지없군요. 부디 저를 용서하세요. 제가 제정신이 아니었습니다.', `MaleText_loc4`='我的羞愧之情简直难以言表。原谅我吧——我当时神智失常了。', `MaleText_loc5`='我感到無以名狀的羞愧。請原諒我，之前那並不是我的本心。', `MaleText_loc7`='Estoy más avergonzado de lo que puedo expresar. Por favor, perdóname; estaba fuera de mis cabales.' WHERE `ID`=57267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무 씨앗 한 움큼이든 화살 세례든, 필요한 것이 있으면 쥬의 감시초소에 맡겨 주세요.', `MaleText_loc4`='如果你今后需要任何帮助，不管是缺少芜菁种子还是箭矢，朱家堡永远是你的坚实后盾。', `MaleText_loc5`='不管你需要什麼，無論是一把大頭菜種子到一束羽箭，請記得祝家守望站永遠都會提供給你。', `MaleText_loc7`='Si alguna vez necesitas ayuda, desde un puñado de semillas de nabas hasta unas cuantas flechas, ten por seguro que en la Atalaya de Zhu lo encontrarás.' WHERE `ID`=57268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단은 마을 재건에 힘써야겠습니다. 해야 할 일이 많군요. 원하신다면 이곳에 머무르셔도 되지만, 이제 도움은 받지 않겠습니다.', `MaleText_loc4`='现在，我必须把注意力转移到重建村庄上去。还有很多事情要做。如果你愿意的话，可以在这里休息，但我们不能接受你更多的帮助了。', `MaleText_loc5`='現在，我必須把注意力集中在重建村莊上。有許多事等著要去完成。如果你想，你可以在這裡休息一下，但我們不再接受更多的幫助。', `MaleText_loc7`='Ahora debo centrar mis esfuerzos en reconstruir la aldea. Hay mucho que hacer. Puedes descansar aquí, si quieres, pero no aceptaremos más ayuda.' WHERE `ID`=57269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 컨컨, 아무래도 슬픔이 이렇게 끝나지 않을 거 같다...', `MaleText_loc4`='但肯肯总觉得悲伤的还不止那几个……', `MaleText_loc5`='有些跡象告訴肯·肯，這並不是悲傷的終結...', `MaleText_loc7`='Algo dice a Ken-Ken ke esa no es el último tristón...' WHERE `ID`=57270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 어딥니까? 당근과... 더러운 냄새 같은 게 나는군요.', `MaleText_loc4`='我们到哪儿了？闻起来好像……胡萝卜和粪味儿。', `MaleText_loc5`='我們在哪裡啊?聞起來像...像胡蘿蔔和臭狗屎。', `MaleText_loc7`='¿Dónde estamos? Huele a... a zanahorias y excremento.' WHERE `ID`=57271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 친구 누굽니까? 방금 말하던 친구요. 지금 뭐하자는 거죠?', `MaleText_loc4`='那是谁啊？跟你说话的那个家伙。谁来告诉我怎么了？', `MaleText_loc5`='那傢伙是誰?剛才跟你說話的那傢伙?誰能告訴我發生什麼事了嗎?', `MaleText_loc7`='¿Quién es ese tipo? Ese con el que estabas hablando. ¿Puede alguien decirme qué está pasando aquí?' WHERE `ID`=57272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 데려가는 겁니까?', `MaleText_loc4`='你要把我带哪儿去，$p？', `MaleText_loc5`='$p，你要帶我去哪?', `MaleText_loc7`='¿Adónde me llevas?' WHERE `ID`=57273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거... 호젠 소리 아닙니까? 언덕골은 아직인가요?', `MaleText_loc4`='那是猢狲的声音吗？我们还没到半山村吧？', `MaleText_loc5`='我聽到的是猴人的聲音嗎?已經到半丘了嗎?', `MaleText_loc7`='¿Eso que oí era un hozen? ¿Estamos ya en El Alcor?' WHERE `ID`=57274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리? 너니? 여보세요? 이 늙은 머드머그에게 신경 좀 써주실 분?', `MaleText_loc4`='丽丽？是你吗？有人吗？谁来关心一下老泥盏啊？', `MaleText_loc5`='莉莉?是妳嗎?哈囉?有人可以回答老泥杯一下嗎?', `MaleText_loc7`='¿Li Li? ¿Eres tú? ¿Hola? ¿Alguien va a hacerle caso al bueno de Caolín?' WHERE `ID`=57275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아! 이제 괜찮다!', `MaleText_loc4`='儿子！你没事了！', `MaleText_loc5`='二世!你沒事!', `MaleText_loc7`='¡Junior! ¡Estás bien!' WHERE `ID`=57276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다. 네가 옳았단다. 정말 거대한 사냥감을 잡았구나. 자랑스럽다, 아들아!', `MaleText_loc4`='不，你是对的。你完美地诠释了“王牌狩猎”。我以你为荣，儿子！', `MaleText_loc5`='不，你是對的。你的確在「大型狩獵遊戲」裡抓到「大傢伙」。你讓我為你感到驕傲，兒子!', `MaleText_loc7`='No, tenías razón. Tú pusiste "MAYOR" en "caza mayor". ¡Estoy orgulloso de ti, hijo!' WHERE `ID`=57277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 사랑한단다, 아들아. 자, 이제 맥주나 마시러 가자꾸나!', `MaleText_loc4`='我也爱你，儿子。现在，让我们找地方喝一杯吧！', `MaleText_loc5`='我也愛你，兒子。現在我們去喝一杯吧!', `MaleText_loc7`='Yo también te quiero, hijo. Ahora vamos a tomar una pinta.' WHERE `ID`=57278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님이 오십니다...', `MaleText_loc4`='他来了……', `MaleText_loc5`='他醒了...', `MaleText_loc7`='Ya viene...' WHERE `ID`=57279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 할 일이 있는 겁니까? 이 머드머그 걱정일랑 마시고... 도착하면 살짝 알려주십시오.', `MaleText_loc4`='你还有其他事情要做吗？不用为老泥盏担心……只要到了捅我一下就行。', `MaleText_loc5`='你還有其它差事要辦嗎?不用擔心老泥杯...到了以後戳我一下就好。', `MaleText_loc7`='¿Tienes que hacer alguna otra tarea? No te preocupes por el bueno de Caolín... tú dame un codazo cuando lleguemos.' WHERE `ID`=57280;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='봉우리들 사이에 열기구 10개가 흩어져 있는데, 이게 통과 지점이랍니다. 방금 한 개를 지나왔어요.', `FemaleText_loc4`='在尖塔之间有10个热气球。这些是检查点。我们刚才就经过了一个。', `FemaleText_loc5`='在尖柱之間散佈著10個熱氣球。這些就是檢查點。我們剛才正好經過了一個。', `FemaleText_loc7`='Hay 10 globos esparcidos entre las torres. Son los puntos de control. Estamos pasando por uno ahora mismo.' WHERE `ID`=57281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $p 님! 제 아들을 구해 주신 일은 절대 잊지 않겠습니다. 정말 멋진 사냥이었습니다!', `MaleText_loc4`='欢迎你，$p！我永远也不会忘记，是你帮我救回了儿子。那才是像样的狩猎！', `MaleText_loc5`='歡迎，$p!我永遠都不會忘記你協助我救了我家的男孩。這才叫好一場狩獵!', `MaleText_loc7`='¡Te doy la bienvenida, $p! Nunca olvidaré cómo me ayudaste a salvar a mi chico. ¡Eso sí que fue una buena cacería!' WHERE `ID`=57282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 스스로 함정의 미끼 역할을 했다는 게 믿어지지 않는군요. 아버지와 당신이 그곳에 있었던 게 제게는 행운이었습니다.', `MaleText_loc4`='我真不敢相信，自己竟成了陷阱的诱饵。幸亏你和我爸爸赶来了。', `MaleText_loc5`='我不敢相信我讓自己變成陷阱的誘餌。算我運氣好，有你跟我老爸在那裡。', `MaleText_loc7`='No me puedo creer que haya sido el señuelo de una trampa. Por suerte, mi padre y tú estabais ahí.' WHERE `ID`=57283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 땅에 왔는데, 따분하게 늙은 늑대나 잡고 싶단 말입니까?', `MaleText_loc4`='一片全新的土地，可你还想继续狩猎无聊的老狼？', `MaleText_loc5`='這是一片新的土地，而你要去獵狼這種無趣的老獵物嗎?', `MaleText_loc7`='¿Una tierra nueva, y quieres cazar los lobos aburridos de siempre?' WHERE `ID`=57284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아, 양보다는 질이란다.', `MaleText_loc4`='重质不重量，孩子。', `MaleText_loc5`='品質比數量重要，孩子。', `MaleText_loc7`='Calidad mejor que cantidad, mi chico.' WHERE `ID`=57285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 게 바로... 진짜 사냥감이라오.', `MaleText_loc4`='看好了……这才叫作战利品。', `MaleText_loc5`='那才算得上是個獎品。', `MaleText_loc7`='Así que... eso es un trofeo.' WHERE `ID`=57286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 사냥감이 작아진 겁니까? 아니면 원래 작은 사냥감을 잡아오신 건가요?', `MaleText_loc4`='你的战利品缩水了吗，爸爸？还是说你的狩猎规模变小了？', `MaleText_loc5`='你的獎品縮水了嗎，老爸?還是你獵點小獵物就滿足了?', `MaleText_loc7`='¿Tus trofeos se reducen, papá? ¿O es que estás cazando presas más pequeñas?' WHERE `ID`=57287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용이 도착하고 있습니다. 저기 하늘에 떠 있는 열기구에 깃발이 매달린 게 보이시죠?', `FemaleText_loc4`='你的翔龙已经到了。你可以在空中找到悬挂在红色热气球上的旗帜。', `FemaleText_loc5`='你的蛟龍來了。你可以在天上的紅色熱氣球找到懸掛的旗幟。', `FemaleText_loc7`='Tu dragón está llegando. Encontrarás las banderas colgando de los globos rojos en el cielo.' WHERE `ID`=57288;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참가자들은 모두 출발선으로! 하늘 경주가 곧 시작됩니다!', `FemaleText_loc4`='参赛选手各就各位！飞行竞技赛即将开始啦！', `FemaleText_loc5`='選手就位!天際競賽即將開始!', `FemaleText_loc7`='¡Jinetes en sus marcas! ¡La carrera del cielo va a dar comienzo!' WHERE `ID`=57289;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='규칙은 간단합니다. 통과 지점 10곳을 모두 지나간 후 결승선을 통과하면 됩니다.', `FemaleText_loc4`='比赛规则很简单。经过全部10个检查点，并穿越终点线。', `FemaleText_loc5`='規則很簡單。通過10個檢查點並跨越終點線。', `FemaleText_loc7`='Las reglas son sencillas. Atraviesa los 10 puntos de control y cruza la meta.' WHERE `ID`=57290;
