UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주를 완료하려면 통과 지점 10곳을 모두 통과해야 합니다!', `MaleText_loc4`='你需要经过全部10个检查点才能完成比赛！', `MaleText_loc5`='你需要飛過10個檢查點來完成賽程!', `MaleText_loc7`='¡Tienes que atravesar los 10 puntos de control antes de completar el recorrido!', `FemaleText_loc1`='경주를 완료하려면 통과 지점 10곳을 모두 통과해야 합니다!', `FemaleText_loc4`='你需要经过全部10个检查点才能完成比赛！', `FemaleText_loc5`='你需要飛過10個檢查點來完成賽程!', `FemaleText_loc7`='¡Tienes que atravesar los 10 puntos de control antes de completar el recorrido!' WHERE `ID`=57302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투를 시작하시겠습니까?', `MaleText_loc4`='你想要开始这场首领战吗？', `MaleText_loc5`='你想要開始這場戰鬥嗎?', `MaleText_loc7`='¿Quieres empezar el encuentro?', `FemaleText_loc1`='전투를 시작하시겠습니까?', `FemaleText_loc4`='你想要开始这场首领战吗？', `FemaleText_loc5`='你想要開始這場戰鬥嗎?', `FemaleText_loc7`='¿Quieres empezar el encuentro?' WHERE `ID`=57303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 어떻게 오셨습니까?', `MaleText_loc4`='你是怎么到这儿来的？', `MaleText_loc5`='你怎麼到這裡來的?', `MaleText_loc7`='¿Cómo has llegado hasta aquí?', `FemaleText_loc1`='이곳에는 어떻게 오셨나요?', `FemaleText_loc4`='你是怎么到这儿来的？', `FemaleText_loc5`='你怎麼到這裡來的?', `FemaleText_loc7`='¿Cómo has llegado hasta aquí?' WHERE `ID`=57304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 부름을 받았다오.$b$b처음에는 대족장이신 바인 블러드후프 님의 명령을 받아 미지의 바다 깊숙이 항해했다오.$b$b아내 레자가 환영 속에서 본 항로를 따라갔지.$b$B그런데 안개의 장벽이 보이기 시작했을 때, 웬 목소리가 바람에 실려 들려 왔다오. 우리는 그 목소리의 부름에 따라 북쪽으로 이동했소.$b$b마침내 해안에 닿아 배를 정박했소. 그리고 지금 우리 앞에 있는 절벽에 도착할 때까지 작은 배를 타고 강을 거슬러 올랐소.', `MaleText_loc4`='我们是被召唤来的。$b$b最初，我们是受大酋长贝恩·血蹄之命远航进入未知的水域。$b$b是我的妻子莱莎的预见指引了我们的航线。$b$B可是当我们看到重重迷雾的时候，我们都感受到风中传来低语般的召唤。北方。那声音召唤我们前往北方。$b$b我们登上海岸，拆卸掉船只，乘坐独木舟逆着河流而上，直到撞上我们面前这片悬崖。', `MaleText_loc5`='我們是被呼喚來的。$b$b一開始，我們聽命於酋長貝恩·血蹄，航向未知的水域。$b$b後來我的妻子麗紗看到了預示，指引我們往這裡來。$b$B當霧牆進入視線時，我們全都感覺到風中傳來呼喚的聲音。北邊，那聲音呼喚我們前往北邊。$b$B於是我們上了岸，拆下船上的裝備，坐上小舟沿著河流溯溪而上，直到撞上我們前面那面峭壁才停下來。', `MaleText_loc7`='Fuimos llamados.$b$bNos adentramos navegando en aguas desconocidas, al principio siguiendo órdenes del gran jefe Baine Pezuña de Sangre.$b$bFue por mi esposa Leza, cuyas visiones nos indicaron una ruta por la que navegar.$b$BSin embargo, cuando vimos el muro vaharado, todos sentimos la llamada como una voz en el viento. La voz nos dice que viajemos hacia el norte.$b$bDesembarcamos, desmontamos nuestro barco y navegamos río arriba en canoa hasta llegar al acantilado que ves ante nosotros.' WHERE `ID`=57305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천막 안에서 무슨 일이 일어나고 있는 겁니까?', `MaleText_loc4`='帐篷里出什么事了？', `MaleText_loc5`='帳棚裡發生了什麼事?', `MaleText_loc7`='¿Qué está pasando dentro de la tienda?', `FemaleText_loc1`='천막 안에서 무슨 일이 일어나고 있는 건가요?', `FemaleText_loc4`='帐篷里出什么事了？', `FemaleText_loc5`='帳棚裡發生了什麼事?', `FemaleText_loc7`='¿Qué está pasando dentro de la tienda?' WHERE `ID`=57306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자가 본 환영이 우리를 이곳으로 이끌었기 때문이오. 또 우리 모두 꿈에서 황금빛 꽃으로 뒤덮인 계곡을 보았다오. 계곡에는 평화와 희망이 감돌고 있었소.$b$b바인 블러드후프 족장님께서도 같은 꿈을 꾸셨소.$b$b그렇지만 우리에게 길을 알려준 것은 레자가 본 환영이었소. 그래서 좋든 싫든 이곳에 오게 된 거라오.', `MaleText_loc4`='是莱莎的预见指引我们来到这里的。我们每个人都梦到一个峡谷，盛开着金色的鲜花，洋溢着和平的希望。$b$b就连是我们的大酋长贝恩·血蹄也得到了这样的预见。$b$b可是，只有莱莎的幻象给我们指明了道路。现在，无论好坏，我们都已经到了这里。', `MaleText_loc5`='麗紗預見的景象帶領我們來到這裡。我們每個人都夢到一個溪谷，開滿金色的花，充滿和平與希望。$b$b連我們的酋長貝恩·血蹄也夢見了這個景象。$b$b但是，只有麗紗預見的景象指引出一條道路。現在，無論是好是壞，總之我們來到了這裡。', `MaleText_loc7`='Fueron las visiones de Leza las que nos guiaron hasta aquí. Todos nosotros soñamos con un valle, dorado con flores, lleno de esperanza de paz.$b$bIncluso nuestro gran jefe Baine Pezuña de Sangre ha tenido estas visiones.$b$bSin embargo, únicamente las visiones de Leza nos indicaron una ruta a seguir. Y aquí nos encontramos, pues, para bien o para mal.' WHERE `ID`=57307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 빠른 기수들이 상품을 차지해요! 모두 운룡에 올라 타세요!', `FemaleText_loc4`='只有最迅捷的骑手才会赢得最终的奖励！骑上你们的云端翔龙！', `FemaleText_loc5`='勝利的獎杯屬於最快速的騎手!登上你的雲蛟吧!', `FemaleText_loc7`='¡Los premios de la victoria son para los jinetes más veloces! ¡A los dragones nimbo!' WHERE `ID`=57308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북이를 다 잡으면 토자리 구덩이에서 다시 만납시다.', `MaleText_loc4`='等你找到足够的龟壳后，去托加尼洼地与我会面，$p。', `MaleText_loc5`='一旦你拿到動物屍體就到托加利坑來見我。', `MaleText_loc7`='Reúnete conmigo en la Fosa Torjari cuando tengas los cadáveres, $p.' WHERE `ID`=57309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님! 네싱워리가 토자리 구덩이에서 기다리고 있습니다.', `MaleText_loc4`='$p！奈辛瓦里和奈辛瓦里二世正在托加尼洼地等着你呢。', `MaleText_loc5`='$p!兩個奈辛瓦里正在托加利坑裡等你。', `MaleText_loc7`='¡$p! Nesingwary y Nesingwary están esperándote en la Fosa Torjari.' WHERE `ID`=57310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 운룡이 게걸스럽게 먹이를 먹습니다.', `MaleText_loc4`='你的翔龙狼吞虎咽着。', `MaleText_loc5`='你的蛟龍飢渴地狼吞虎嚥著。', `MaleText_loc7`='Tu dragón devora la comida con hambre.', `FemaleText_loc1`='당신의 운룡이 게걸스럽게 먹이를 먹습니다.', `FemaleText_loc4`='你的翔龙狼吞虎咽着。', `FemaleText_loc5`='你的蛟龍飢渴地狼吞虎嚥著。', `FemaleText_loc7`='Tu dragón devora la comida con hambre.' WHERE `ID`=57311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 운룡이 먹이를 꿀꺽 삼킵니다. 얌냠!', `MaleText_loc4`='你的翔龙一口吞下了食物。好美味！', `MaleText_loc5`='你的蛟龍將食物一口吞下。好吃!', `MaleText_loc7`='Tu dragón se zampa la comida. ¡Ñam!', `FemaleText_loc1`='당신의 운룡이 먹이를 꿀꺽 삼킵니다. 얌냠!', `FemaleText_loc4`='你的翔龙一口吞下了食物。好美味！', `FemaleText_loc5`='你的蛟龍將食物一口吞下。好吃!', `FemaleText_loc7`='Tu dragón se zampa la comida. ¡Ñam!' WHERE `ID`=57312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 운룡이 먹이를 먹어 치우고는, 더 없는지 주위를 둘러봅니다.', `MaleText_loc4`='你的翔龙吃完后又四处张望，寻找起食物来。', `MaleText_loc5`='你的蛟龍把食物吃掉，東張西望地想要更多。', `MaleText_loc7`='Tu dragón se come la comida y busca más.', `FemaleText_loc1`='당신의 운룡이 먹이를 먹어 치우고는, 더 없는지 주위를 둘러봅니다.', `FemaleText_loc4`='你的翔龙吃完后又四处张望，寻找起食物来。', `FemaleText_loc5`='你的蛟龍把食物吃掉，東張西望地想要更多。', `FemaleText_loc7`='Tu dragón se come la comida y busca más.' WHERE `ID`=57313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 또 한 놈이 나타났네? $p 님, 저놈을 처치하게 동굴 뒤편으로 유인하십시오.', `MaleText_loc4`='噢，又来一个？$p，把他引到洞穴最里边，让我一枪击毙他。', `MaleText_loc5`='喔，另一個是吧?$p，把他引誘到山洞後面好讓我狙擊他。', `MaleText_loc7`='Oh, otro, ¿eh? $p, llévalo hacia el fondo de la cueva para que pueda dispararle.' WHERE `ID`=57314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용이 입맛을 다십니다. 정말 맛있었던 모양입니다!', `MaleText_loc4`='你的翔龙舔着嘴唇，真是太好吃了！', `MaleText_loc5`='你的蛟龍舔了舔嘴唇。真好吃!', `MaleText_loc7`='Tu dragón se relame. ¡Estaba riquísimo!', `FemaleText_loc1`='당신의 용이 입맛을 다십니다. 정말 맛있었던 모양입니다!', `FemaleText_loc4`='你的翔龙舔着嘴唇，真是太好吃了！', `FemaleText_loc5`='你的蛟龍舔了舔嘴唇。真好吃!', `FemaleText_loc7`='Tu dragón se relame. ¡Estaba riquísimo!' WHERE `ID`=57315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용이 애원하는 눈길로 당신을 바라봅니다. 더 없나요?', `MaleText_loc4`='你的翔龙恳求地看着你，还有食物吗？', `MaleText_loc5`='你的蛟龍哀求地看著你。還有嗎?', `MaleText_loc7`='Tu dragón te pone ojos de cordero degollado. ¿Queda más?', `FemaleText_loc1`='당신의 용이 애원하는 눈길로 당신을 바라봅니다. 더 없나요?', `FemaleText_loc4`='你的翔龙恳求地看着你，还有食物吗？', `FemaleText_loc5`='你的蛟龍哀求地看著你。還有嗎?', `FemaleText_loc7`='Tu dragón te pone ojos de cordero degollado. ¿Queda más?' WHERE `ID`=57316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용 아랫배가 더 둥글둥글 토실토실해진 것 같습니다.', `MaleText_loc4`='你的翔龙的肚子看上去又圆了一点。', `MaleText_loc5`='你蛟龍的肚子似乎變得圓圓的。', `MaleText_loc7`='La barriga de tu dragón está algo más redonda.', `FemaleText_loc1`='당신의 용 아랫배가 더 둥글둥글 토실토실해진 것 같습니다.', `FemaleText_loc4`='你的翔龙的肚子看上去又圆了一点。', `FemaleText_loc5`='你蛟龍的肚子似乎變得圓圓的。', `FemaleText_loc7`='La barriga de tu dragón está algo más redonda.' WHERE `ID`=57317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용이 애정 어린 몸짓으로 당신에게 몸을 부비고 난 후, 음식을 먹기 시작합니다.', `MaleText_loc4`='你的翔龙在开吃之前亲昵地拱了你一下。', `MaleText_loc5`='你的蛟龍在吃東西前親暱地頂了頂你。', `MaleText_loc7`='Tu dragón te da un empujón cariñoso y se pone a comer.', `FemaleText_loc1`='당신의 용이 애정 어린 몸짓으로 당신에게 몸을 부비고 난 후, 음식을 먹기 시작합니다.', `FemaleText_loc4`='你的翔龙在开吃之前亲昵地拱了你一下。', `FemaleText_loc5`='你的蛟龍在吃東西前親暱地頂了頂你。', `FemaleText_loc7`='Tu dragón te da un empujón cariñoso y se pone a comer.' WHERE `ID`=57318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용은 음식이 맛있다고 생각했습니다.', `MaleText_loc4`='你的翔龙觉得食物非常美味。', `MaleText_loc5`='你的蛟龍覺得那食物真是很好吃。', `MaleText_loc7`='A tu dragón le ha parecido que la comida estaba deliciosa.', `FemaleText_loc1`='당신의 용은 음식이 맛있다고 생각했습니다.', `FemaleText_loc4`='你的翔龙觉得食物非常美味。', `FemaleText_loc5`='你的蛟龍覺得那食物真是很好吃。', `FemaleText_loc7`='A tu dragón le ha parecido que la comida estaba deliciosa.' WHERE `ID`=57319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네는 전망이 무척 밝아 보이네, $n. 하지만 재능을 규율로 다스려야 빛을 낼 수 있네.', `FemaleText_loc4`='你表现出了极大的潜力，$n，但你必须依靠戒律来磨砺你的天赋。', `FemaleText_loc5`='你看起來似乎很有前途，$n。但你必須用紀律培養你的天賦。', `FemaleText_loc7`='Prometes mucho, $n, pero debes nutrir tu talento con disciplina.' WHERE `ID`=57320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님! 구해주셔서 감사합니다. 정말 큰 빚을 졌군요.', `MaleText_loc4`='多谢你救了我，$p！我欠你个大人情。', `MaleText_loc5`='謝謝你救了我，$p!我欠你一個大恩情。', `MaleText_loc7`='¡Gracias por salvarme, $p! Te debo una.' WHERE `ID`=57321;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린 용은 섬세한 존재일세. 나쁜 습관이 형성되는 것도 그 시점이지. 훈련을 잘 시키면 큰 차이가 난다네.', `FemaleText_loc4`='幼年翔龙是非常脆弱的。许多坏习惯就是在这时期养成的。但良好的训练能改变这一切。', `FemaleText_loc5`='年輕的蛟龍是需要好好呵護的，在這個階段容易養成壞習慣。好的訓練能改變這種情況。', `FemaleText_loc7`='Los dragones jóvenes son muy delicados. Es a esta edad cuando desarrollan los malos hábitos. Un buen entrenamiento marca la diferencia.' WHERE `ID`=57322;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린 운룡은 다 자란 운룡보다 훨씬 활기차다네.', `FemaleText_loc4`='幼年翔龙要比成年翔龙顽皮得多。', `FemaleText_loc5`='年輕的蛟龍比成年的更愛玩。', `FemaleText_loc7`='Los dragones jóvenes son mucho más juguetones que los adultos.' WHERE `ID`=57323;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡 기수의 길은 길고 고되네. 하지만 자신의 운룡과 함께 달리는 길이지.$B$B함께 그 길의 끝에 다다를 때면, 자신의 최후까지 함께할 좋은 친구를 얻을 수 있네.', `FemaleText_loc4`='翔龙骑士的道路漫长而艰险，但你将和你的翔龙伙伴一路同行。$B$B如果你们能互相扶持走到终点，你就将收获一个终生不渝的忠实朋友。', `FemaleText_loc5`='雲蛟騎士的道路是漫長而艱辛的。但你會和你的雲蛟夥伴一起度過。$B$B如果你們一起抵達終點，你將得到一個終身跟隨你的忠誠朋友。', `FemaleText_loc7`='La senda del jinete de dragones nimbo es larga y ardua, pero tu dragón nimbo te acompañará.$b$bSi llegáis al final del camino juntos, tendrás un amigo leal que te apoyará hasta el final de tus días.' WHERE `ID`=57324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 레자. 힘을 줘야 해요. 준비됐죠?', `FemaleText_loc4`='好了，莱莎，我需要你用力推。你准备好了么吗？', `FemaleText_loc5`='好了，麗紗，我需要你用力推寶寶出來。你準備好了嗎?', `FemaleText_loc7`='Bueno, Leza, necesito que empujes. ¿Estás lista?' WHERE `ID`=57327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 고개를 끄덕입니다.', `FemaleText_loc4`='%s点了点头。', `FemaleText_loc5`='%s點點頭。', `FemaleText_loc7`='%s asiente.' WHERE `ID`=57328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘주세요!', `FemaleText_loc4`='推！', `FemaleText_loc5`='推!', `FemaleText_loc7`='¡Empuja!' WHERE `ID`=57329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아악! 흐아아악!', `FemaleText_loc4`='啊啊啊！嗯嗯嗯！', `FemaleText_loc5`='啊啊啊!喝啊!', `FemaleText_loc7`='¡AAAH! ¡MMMFF!' WHERE `ID`=57330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아아아아아악!', `FemaleText_loc4`='哇啊啊啊！', `FemaleText_loc5`='嘎啊啊啊啊!', `FemaleText_loc7`='¡AAAAAAH!' WHERE `ID`=57331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요. 정말 잘하셨어요. 이제 좀 쉬세요. 뜨거운 물 좀 더 가져다 드릴게요.', `FemaleText_loc4`='很好，干得不错。你现在可以休息一下。我再去给你端点热水来。', `FemaleText_loc5`='很好，非常好。你現在可以休息了。我會多給你一些熱水。', `FemaleText_loc7`='Bien, muy bien. Ya puedes descansar. Te traeré un poco más de agua caliente.' WHERE `ID`=57332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈드블레이드 교관님, 제 운룡을 다시 불러주시겠습니까?', `MaleText_loc4`='风刃教头，你能再帮我召唤一次翔龙吗？', `MaleText_loc5`='講師風刃，你能再次呼喚我的蛟龍嗎?', `MaleText_loc7`='Instructora Hoja Liviana, ¿podrías volver a llamar a mi dragón?', `FemaleText_loc1`='윈드블레이드 교관님, 제 운룡을 다시 불러주시겠어요?', `FemaleText_loc4`='风刃教头，你能再帮我召唤一次翔龙吗？', `FemaleText_loc5`='講師風刃，你能再次呼喚我的蛟龍嗎?', `FemaleText_loc7`='Instructora Hoja Liviana, ¿podrías volver a llamar a mi dragón?' WHERE `ID`=57333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 천둥 틈새에서 만나세. 태양의 빛이 자네를 보호하기를.', `MaleText_loc4`='雷霆裂口见，$p。愿阳光保佑你。', `MaleText_loc5`='到雷霆斷崖再見面了，$p。願日光保護你。', `MaleText_loc7`='Nos veremos en Grieta del Trueno, $p. Que la luz del sol te proteja.' WHERE `ID`=57335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 천둥 틈새에서 만나세. 나는 형제의 시신을 동료들이 있는 곳으로 옮겨야 하네.', `MaleText_loc4`='$p，回雷霆裂口来见我吧。我必须把我兄弟的遗体带回去。', `MaleText_loc5`='$p，到雷霆斷崖去和我碰頭。我必須把我兄弟的屍體帶回族人身邊。', `MaleText_loc7`='$p, reúnete conmigo en Grieta del Trueno. Debo traer el cuerpo de mi hermano de vuelta con nuestra gente.' WHERE `ID`=57336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윈드블레이드 교관님, 제 운룡은 어떻게 지내고 있습니까?', `MaleText_loc4`='风刃教头，我的翔龙还好吗？', `MaleText_loc5`='講師風刃，我的蛟龍狀況如何?', `MaleText_loc7`='Instructora Hoja Liviana, ¿qué tal le va a mi dragón?', `FemaleText_loc1`='윈드블레이드 교관님, 제 운룡은 어떻게 지내고 있나요?', `FemaleText_loc4`='风刃教头，我的翔龙还好吗？', `FemaleText_loc5`='講師風刃，我的蛟龍狀況如何?', `FemaleText_loc7`='Instructora Hoja Liviana, ¿qué tal le va a mi dragón?' WHERE `ID`=57337;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금까지 오랜 시간 인내하며 사랑을 주셨더군요, $n 님. 이제 당신의 운룡을 만나보십시오.', `FemaleText_loc4`='你已经投入了大量的时间、耐心还有爱心，$n。现在来看看你的翔龙吧。', `FemaleText_loc5`='你花費了許多的時間、耐性和愛心，$n。來看看你的蛟龍吧。', `FemaleText_loc7`='Has dedicado mucho tiempo, paciencia y amor, $n. Mira en lo que se ha convertido tu dragón.' WHERE `ID`=57338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 말이 맞소. 나는 레자 곁에 있어야 하오. 고맙소.', `MaleText_loc4`='你是对的，$p。我必须为了莱莎留在那里。谢谢你。', `MaleText_loc5`='$p，你是對的，我應該要過去幫麗紗，謝謝你。', `MaleText_loc7`='Tienes razón: debería estar con Leza. Gracias.' WHERE `ID`=57339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데즈코... 아파요... 아아아악!!', `FemaleText_loc4`='德兹科……好疼……好……啊啊啊！', `FemaleText_loc5`='戴斯可...好痛...好...啊啊啊啊!', `FemaleText_loc7`='Dezco... duele... due... ¡AAAH!' WHERE `ID`=57340;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭔가 잘못됐습니다. 아기가 잘못 들어서 있어요.', `FemaleText_loc4`='不太对劲。婴儿的胎位不正。', `FemaleText_loc5`='事情不太對勁，這寶貝的方向錯了。', `FemaleText_loc7`='Algo va mal. El bebé viene en mala postura.' WHERE `ID`=57341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데즈코, 어디 있어요?', `FemaleText_loc4`='德兹科，你在哪？！', `FemaleText_loc5`='戴斯可，你在哪裡?', `FemaleText_loc7`='Dezco, ¡¿dónde estás?!' WHERE `ID`=57342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 여기 있소, 레자.', `MaleText_loc4`='我在这儿，莱莎。', `MaleText_loc5`='我來了，麗紗。', `MaleText_loc7`='Estoy aquí, Leza.' WHERE `ID`=57343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 사랑... 무슨 일이 있더라도... 우리... 우리 아이를 지켜주셔야만 해요...', `FemaleText_loc4`='亲爱的……不管发生什么事……你都必须保护我们的……我们的孩子……', `FemaleText_loc5`='親愛的...不管發生什麼事...你一定要保護我們...我們這個孩子...', `FemaleText_loc7`='Mi amor... pase lo que pase... tienes que proteger a nuestro... nuestro bebé...' WHERE `ID`=57344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자!', `MaleText_loc4`='莱莎！', `MaleText_loc5`='麗紗!', `MaleText_loc7`='¡Leza!' WHERE `ID`=57345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자!!', `MaleText_loc4`='莱莎！！', `MaleText_loc5`='麗紗!!', `MaleText_loc7`='¡¡LEZA!!' WHERE `ID`=57346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아아아아아악!', `FemaleText_loc4`='哇啊啊啊！', `FemaleText_loc5`='啊啊啊!', `FemaleText_loc7`='¡GAAAH!' WHERE `ID`=57347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘, 운룡단을 향한 당신의 여정이 끝납니다. 오늘, 새로운 기수가 우리와 함께합니다.', `FemaleText_loc4`='今天，你终于通过了云端翔龙骑士团的考验。今天，一位新骑士加入了我们的行列。', `FemaleText_loc5`='今天，你加入雲蛟衛的旅途到達終點了。今天，一名新騎兵加入我們的行列。', `FemaleText_loc7`='Hoy, tu viaje para unirte a la Orden del Dragón Nimbo termina. Hoy, $gun nuevo:una nueva; jinete se une a nuestras filas.' WHERE `ID`=57348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘, 당신은 자신의 운룡과 영원한 유대를 맺습니다.', `FemaleText_loc4`='今天，你与你的云端翔龙建立了永恒的联结。', `FemaleText_loc5`='今天，你和你的雲蛟結下永恆的羈絆。', `FemaleText_loc7`='Hoy, se forja un vínculo eterno entre tu dragón nimbo y tú.' WHERE `ID`=57349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥과 폭풍을 뚫고, 우리는 함께 비행합니다.', `MaleText_loc4`='穿越雷鸣，穿越风暴，我们守望相助。', `MaleText_loc5`='我們一起飛越風暴與雷霆。', `MaleText_loc7`='Juntos superamos truenos y tormentas.' WHERE `ID`=57350;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바다와 하늘을 넘어, 우리는 함께 비행합니다.', `FemaleText_loc4`='飞天越海，我们比肩翱翔。', `FemaleText_loc5`='我們一起飛越高山和海洋。', `FemaleText_loc7`='Juntos surcamos mares y cielos.' WHERE `ID`=57351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람과 해일을 뚫고, 우리는 함께 비행합니다.', `FemaleText_loc4`='穿越飓风，穿越潮汐，我们一起翱翔。', `FemaleText_loc5`='我們一起飛越狂風和驚濤。', `FemaleText_loc7`='Contra viento y marea, volamos juntos.' WHERE `ID`=57352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 당신은 혼자 비행하는 일이 없을 겁니다.', `FemaleText_loc4`='你再也不会孤独飞翔。', `FemaleText_loc5`='從今以後你再也不是獨自飛行。', `FemaleText_loc7`='Nunca más volarás $gsolo:sola;.' WHERE `ID`=57353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기수들이 내 뒤에, 그리고 운룡이 내 곁에 함께합니다.', `MaleText_loc4`='因我有同袍在后，我有翔龙在侧。', `MaleText_loc5`='同袍與我並肩，蛟龍與我同行。', `MaleText_loc7`='Con el apoyo de los jinetes y junto a mi dragón.', `FemaleText_loc1`='기수들이 내 뒤에, 그리고 운룡이 내 곁에 함께합니다.', `FemaleText_loc4`='因我有同袍在后，我有翔龙在侧。', `FemaleText_loc5`='同袍與我並肩，蛟龍與我同行。', `FemaleText_loc7`='Con el apoyo de los jinetes y junto a mi dragón.' WHERE `ID`=57354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='명예와 용기를 바탕으로 우리는 함께 비행합니다. 이제, 용 기수가 되어 일어서십시오!', `FemaleText_loc4`='带着荣耀与勇气飞翔吧。现在……化身为翔龙骑士！', `FemaleText_loc5`='帶著勇氣和榮譽一齊飛翔。現在...以雲蛟騎士的身分起飛!', `FemaleText_loc7`='Volad juntos con honor y coraje. Ahora... ¡álzate como jinete de dragones!' WHERE `ID`=57355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 아내 곁을 지켜주십시오. 제가 침입자들로부터 천막을 보호하겠습니다.', `MaleText_loc4`='去，到你妻子身边去。我来保护帐篷，抵御入侵者。', `MaleText_loc5`='去吧，去陪在你妻子身邊。我會在帳棚這裡抵擋入侵者。', `MaleText_loc7`='Corre, ve junto a tu esposa. Yo protegeré la tienda de los invasores.', `FemaleText_loc1`='가서 아내 곁을 지켜주세요. 제가 침입자들로부터 천막을 보호할게요.', `FemaleText_loc4`='去，到你妻子身边去。我来保护帐篷，抵御入侵者。', `FemaleText_loc5`='去吧，去陪在你妻子身邊。我會在帳棚這裡抵擋入侵者。', `FemaleText_loc7`='Corre, ve junto a tu esposa. Yo protegeré la tienda de los invasores.' WHERE `ID`=57356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아이가 곧 태어날 거요... 오늘로서 모든 게 변하는군...', `MaleText_loc4`='我的孩子就要降生了……今天一切都变了……', `MaleText_loc5`='我的孩子就快生了...今天一切都變了...', `MaleText_loc7`='Mi hijo ya casi está aquí... hoy cambia todo...' WHERE `ID`=57357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 털이 오늘 좀 멋지지 않나요?', `MaleText_loc4`='我的毛今天看起来是不是很闪亮啊？', `MaleText_loc5`='今天我的毛皮看起來不錯吧?', `MaleText_loc7`='¿A que hoy está precioso mi pelaje?' WHERE `ID`=57358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가라 덕분에 제가 멋져 보입니다. 제 덕분에 그녀가 멋져 보이고요.', `MaleText_loc4`='我跟阿加拉是交相辉映，相得益彰。', `MaleText_loc5`='顎卡拉讓我顯得很好看，就像我讓她顯得很好看一樣。', `MaleText_loc7`='Agara favorece mi imagen, igual que yo favorezco la suya.' WHERE `ID`=57359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 하늘에서 가장 멋져 보이는 기수라고 하더군요. 아니요, 그렇게 생각하시면 안 됩니다. 저는 땅에서도, 바다에서도... 그냥 어디에서든 가장 멋져 보이는 기수랍니다.', `MaleText_loc4`='别人告诉我，我是天空之中最英俊的骑士。如果我是你，我就不会相信这种鬼话。我也是大地之上最英俊的骑士，深海之下最英俊的骑士……呃，反正不管到哪儿我都是最英俊的！', `MaleText_loc5`='聽說我是天空中最好看的騎士。這拿來說你就有點不太好相信了。我也是陸地上最好看的騎士。還有海底...好吧，反正差不多在每個地方都是!', `MaleText_loc7`='Me han dicho que soy el jinete más atractivo de los cielos. Si fuera tú, no me lo creería. También soy el jinete más atractivo del suelo, del mar... ¡en fin, de todas partes!' WHERE `ID`=57360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 용을 감상하러 오셨군요. 네, 저도 아가라가 멋지다는 걸 잘 압니다.', `MaleText_loc4`='你是来欣赏我的翔龙的吧。噢，它给阿加拉也留下了深刻的印象。', `MaleText_loc5`='看來你是來這裡觀摩我的蛟龍。喔，還有顎卡拉也相當令人讚嘆。', `MaleText_loc7`='Veo que has venido a admirar mi dragón. Ah, y Agara también es impresionante.' WHERE `ID`=57361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요? 혹시 시간 있으세요?', `MaleText_loc4`='嘿，你在干什么？', `MaleText_loc5`='嘿，你狀況如何?', `MaleText_loc7`='¿Qué tal te va?' WHERE `ID`=57362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이따가 저와 친구들 몇이 함께 춤추는 용 여관으로 가서 맥주나 마시려고 합니다.', `MaleText_loc4`='这里的事结束之后，我一定要和兄弟们去龙舞楼喝几杯！', `MaleText_loc5`='這邊完事之後我和其他小子要衝進舞龍客棧裡多喝幾杯。', `MaleText_loc7`='Cuando terminemos, voy a ir con unos amigos al Dragón Danzante a tomar unas birras.' WHERE `ID`=57363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 바람맞이 섬에서는 혹시 마노 알이 있는지 눈을 크게 뜨고 찾아보십시오. 그 알을 가져오면 용 조련사들이 난리가 날 겁니다.', `MaleText_loc4`='嘿菜鸟，在临风岛上注意寻找玛瑙翔龙蛋。要是你能将它带给翔龙大师，他们一定会喜出望外！', `MaleText_loc5`='嘿，新人，當你在嘯風島上時，注意一下有沒有瑪瑙蛟蛋。如果你帶一個給他們，蛟龍訓練師們會樂瘋的。', `MaleText_loc7`='Oye, $gnovato:novata;, mientras estés en la Isla de Barlovento, ten los ojos abiertos por si ves huevos de ónice. A los maestros de dragones les dará algo si les llevas uno.' WHERE `ID`=57364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 제 팬클럽에서 오셨습니까? 죄송합니다. 지금은 사인을 해드릴 수가 없네요.', `MaleText_loc4`='哦，你是我的粉丝吗？真不好意思，我现在不能给你签名。', `MaleText_loc5`='喔你是我粉絲團的成員?不好意思，我目前不給簽名。', `MaleText_loc7`='¿Eres de mi club de fans? Lo siento, ahora mismo no firmo autógrafos.' WHERE `ID`=57365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다. 지금은 말을 할 수가 없습니다. 여기 훈련을 마치면 점심시간이거든요!', `MaleText_loc4`='抱歉，我现在不能和你闲聊。等我们完成这里的训练之后，就该吃午饭了！', `MaleText_loc5`='抱歉，我現在不能說話。等我們完成這裡的訓練，就是午餐時間!', `MaleText_loc7`='Lo siento, ahora mismo no puedo hablar. Después de que terminemos el entrenamiento aquí será la hora de comer.' WHERE `ID`=57366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 최고의 기수는 아니지만, 제 발명품은 최고랍니다!', `MaleText_loc4`='我也许不是最棒的骑士，但却拥有一流的发明！', `MaleText_loc5`='我或許不是最好的騎士，但我有最好的發明!', `MaleText_loc7`='Puede que no sea el mejor jinete, ¡pero soy el mejor inventor!' WHERE `ID`=57367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배의 슬픔에 잠겨 있을 때... 저는 밥을 먹습니다.', `MaleText_loc4`='当我因失去而感到难过时，我就化悲痛为食量……', `MaleText_loc5`='當我因失敗而感到悲傷時，我就吃東西...', `MaleText_loc7`='Cuando me pongo triste por perder, me pongo a comer...' WHERE `ID`=57368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로운 발명품이 생각났어요. 응가 수집기라는 건데요, 다시는 제 손으로 응가를 치울 필요가 없겠어요!', `MaleText_loc4`='我想到了一个新发明，叫做集粪桶。有了它，我就再也不用自己去收集粪便了！', `MaleText_loc5`='我有個新發明的點子。叫做便便撿拾器。這樣我永遠都不用撿便便啦!', `MaleText_loc7`='Tengo una idea para un nuevo invento. Se llama "recogecacas". ¡Nunca tendré que volver a recoger caca!' WHERE `ID`=57369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람맞이 섬에서 가끔씩 마노 알이 발견되기도 한다는 걸 아셨나요? 그 알을 찾아서 용 조련사에게 가져다 주면, 운룡단의 존경 받는 일원으로 부각될 겁니다.', `MaleText_loc4`='你知道吗，在临风岛上有时能找到稀有的玛瑙翔龙蛋。要是你将它带给翔龙大师，就能赢得骑士团的尊重。', `MaleText_loc5`='你知道嘯風島上偶爾會有稀有的瑪瑙蛟蛋嗎?如果你帶一顆去給蛟龍訓練師，你會在雲蛟衛裡贏得很大的尊敬。', `MaleText_loc7`='¿Sabes que a veces se encuentran huevos de ónice en la Isla de Barlovento? Si le llevas uno a un maestro de dragones, te ganarás el respeto de la Orden.' WHERE `ID`=57370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건강을 유지하려면 잘 먹어야 합니다! 우리 엄마가 늘 그렇게 말씀해 주셨어요...', `MaleText_loc4`='吃饱了才有力气！反正我妈妈总跟我这么说……', `MaleText_loc5`='你必須吃好一點來維持你的體力!至少，我媽媽總是這樣告訴我...', `MaleText_loc7`='¡Tienes que comer bien para estar fuerte! Eso es lo que siempre me decía mi madre...' WHERE `ID`=57371;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 말할 수 없어요. 매우 바쁘거든요.', `FemaleText_loc4`='我现在没空聊天，我很忙。', `FemaleText_loc5`='我現在不能說話。我很忙。', `FemaleText_loc7`='No puedo hablar ahora mismo. Estoy muy ocupado.' WHERE `ID`=57372;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나중에 다시 오시겠어요? 지금은 운룡을 훈련시키느라고 많이 바빠요. 다른 기수들에게 이기려면, 열심히 노력해야 하거든요.', `FemaleText_loc4`='你能稍后再来吗？我正在忙着训练我的云端翔龙。要是我想击败对手，就必须得加把劲。', `FemaleText_loc5`='請晚點再來好嗎?我正忙著訓練我的雲蛟。我得更努力才能擊敗其他人。', `FemaleText_loc7`='¿Te importa venir más tarde? Ahora mismo estoy ocupada entrenando a mi dragón nimbo. Tengo que esforzarme si quiero ganar a los demás.' WHERE `ID`=57373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시합에 대해서는 걱정하지 않아요. 제가 이길 것을 알고 있으니까요.', `FemaleText_loc4`='我并不担心我的比赛，因为我知道我赢定了。', `FemaleText_loc5`='我不擔心我的競賽，因為我知道我會贏。', `FemaleText_loc7`='No me preocupan mis competidores: sé que voy a ganar.' WHERE `ID`=57374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 두려운 건 쿠아로뿐이에요. 항상 뭔가 속임수를 감추고 있거든요.', `FemaleText_loc4`='我唯一担心的就是奎陆，他总在自己的设备上搞些花样。', `FemaleText_loc5`='我唯一擔心的就是魁羅，他總是有些鬼點子。', `FemaleText_loc7`='El único que me preocupa es Qua-Ro. Siempre se guarda algún as en la manga.' WHERE `ID`=57375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저와 겨뤄보고 싶다고요? 하! 대결 내내 제 운룡 꼬리만 보게 될 걸요?', `FemaleText_loc4`='你想跟我一较高下？哈！你只能看着我的翔龙尾巴，望尘莫及。', `FemaleText_loc5`='你想要和我競賽?哈!你整場都只能從後面看著我蛟龍的尾巴。', `FemaleText_loc7`='¿Quieres corres contra mí? ¡Ja! Lo único que vas a ver va a ser la cola de mi dragón.' WHERE `ID`=57376;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 서서 당신과 얘기만 하면, 다른 기수들을 이길 수가 없어요.', `FemaleText_loc4`='要是我一直站着陪你聊天，就无法击败对手了。', `FemaleText_loc5`='站在這邊和你講話可不能幫我擊敗其他人。', `FemaleText_loc7`='No voy a ganar a nadie si me quedo parada hablando contigo.' WHERE `ID`=57377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그래요. 저도 마노 알을 안리 장로님께 많이 갖다 드렸어요. 하나 드릴 때마다 운룡단에서의 제 지위가 높아지더군요.', `FemaleText_loc4`='哦耶，我给安离长老带去了许多玛瑙翔龙蛋。我每给她一枚，就使自己在骑士团中的地位得到了提升。', `FemaleText_loc5`='喔是的，我帶了很多瑪瑙蛟蛋給安麗長老。我每帶給她一顆，我在雲蛟衛中的地位就提升一些。', `FemaleText_loc7`='Ah, sí, le he llevado muchos huevos de ónice a la ancestro Anli. Cada vez que le doy uno, asciendo en la jerarquía de la Orden.' WHERE `ID`=57378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열심히 노력하지 않으면, 뒤처질 거예요.', `FemaleText_loc4`='要是我不努力，就会被别人甩在身后。', `FemaleText_loc5`='如果我不努力，我會落後的。', `FemaleText_loc7`='Si no trabajo duro, me quedaré atrás.' WHERE `ID`=57379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연구에 매진하는 기수가 성공할 수 있습니다.', `MaleText_loc4`='一个勤奋的骑士就是一个成功的骑士。', `MaleText_loc5`='勤奮的騎兵會是成功的騎兵。', `MaleText_loc7`='Jinete aplicado, éxito asegurado.' WHERE `ID`=57380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 시간에 연습이나 더 하셔야 하지 않겠습니까?', `MaleText_loc4`='你不该多练练吗？', `MaleText_loc5`='你不是該在練習嗎?', `MaleText_loc7`='¿No deberías estar entrenando?' WHERE `ID`=57381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 좋은 훈련은 직접 해보는 것입니다.', `MaleText_loc4`='最好的经验就是自己的经验。', `MaleText_loc5`='自力獲得的經驗是最好的。', `MaleText_loc7`='La mejor experiencia es la de uno mismo.' WHERE `ID`=57382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 저만의 기술을 몇 가지 말씀드릴 수도 있을 겁니다. 하지만 그건 스스로 직접 연습하고 몸으로 익힌 기술에 비할 바가 아닙니다.', `MaleText_loc4`='我可以把我的骑术窍门告诉你，但这还是比不上你自己的刻苦练习和亲身体会。', `MaleText_loc5`='我可以把我駕馭戰蛟的小技巧跟你說，但他們全都比不上你自己的練習和經驗。', `MaleText_loc7`='Te puedo contar mis trucos para volar, pero no son nada en comparación con la práctica y la experiencia.' WHERE `ID`=57383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 그렇게 빠르냐고요? 그 비결을 알려드리고 나면, 제가 불리해질 겁니다.', `MaleText_loc4`='我为什么能这么快？如果我告诉你，不就对自己不利了吗？', `MaleText_loc5`='我為什麼這麼快?如果我告訴你，我只會讓自己失去優勢。', `MaleText_loc7`='¿Que por qué soy tan rápido? Si te lo dijera, me estaría poniendo en desventaja.' WHERE `ID`=57384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 교관들에게 배우십시오. 저도 아직 학생일 뿐이니, 가르쳐드릴 게 없습니다.', `MaleText_loc4`='去向教头们请教吧。我没什么可教你的，我也只是个徒弟而已。', `MaleText_loc5`='向大師們學習。我沒有東西可以教你，因為我不過是個學生。', `MaleText_loc7`='Aprende de los maestros. Yo no tengo nada que enseñarte, pues un estudiante soy nada más.' WHERE `ID`=57385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 수련생들은 기술과 재능을 모두 지니고 있습니다. 모두와 함께 비행하게 되어 영광입니다.', `MaleText_loc4`='其他的新手都有着各自的技巧和天赋，能和他们一起翱翔我感到很荣幸。', `MaleText_loc5`='其他受訓弟子都擁有各自的技巧和天份，我很榮幸能和他們並騎。', `MaleText_loc7`='Los otros alumnos tienen sus habilidades y talentos. Me honra montar a su lado.' WHERE `ID`=57386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 비행하게 되어 영광입니다.', `MaleText_loc4`='能和你同场竞技是我的荣幸。', `MaleText_loc5`='和你並騎是我的榮幸。', `MaleText_loc7`='Es un honor volar contigo.' WHERE `ID`=57387;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 잘 지내시죠?', `FemaleText_loc4`='嗨！你好吗？', `FemaleText_loc5`='嗨!你好嗎?', `FemaleText_loc7`='¡Hola! ¿Qué tal?' WHERE `ID`=57388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도움이 필요하시면 제게 말씀만 하세요!', `FemaleText_loc4`='需要帮助的话，尽管找我！', `FemaleText_loc5`='如果你需要幫助，儘管問我!', `FemaleText_loc7`='Si necesitas ayuda, ¡ven a verme!' WHERE `ID`=57389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='통과 지점이 어디인지 기억해 두세요. 깃발의 위치만 정확히 알아두면, 최단거리로 비행할 수 있어요.', `FemaleText_loc4`='你要尽量记住那些检查点的位置。一旦搞清楚该去哪儿收集那些旗帜，你便可以制定出最短的飞行路线。', `FemaleText_loc5`='試著記住檢查點的位置。如果你知道在哪撿起旗子，你就能規劃最短的路徑。', `FemaleText_loc7`='Intenta recordar dónde están los puntos de control. Cuando sepas dónde están las banderas, podrás calcular la ruta más corta.' WHERE `ID`=57390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='구름 고리를 통과하는 것이 비행 속도를 높이는 최선의 방법이에요. 그렇게 폭발적인 속도를 얻기 위해서 잠시 경로를 벗어나는 것도 좋아요.', `FemaleText_loc4`='穿越那些云之环是提升速度的最好办法。有时候为了提升速度而偏离一下航线还是很值得的！', `FemaleText_loc5`='穿越環狀雲是加速的最好方法。有時候偏離一點航線換取加速也是值得的!', `FemaleText_loc7`='Atravesar anillos de nubes es la mejor forma de ganar velocidad. A veces merece la pena salirse un poco de la ruta para ir más rápido.' WHERE `ID`=57391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주위를 둘러보며 다른 경로가 없는지 확인하세요. 너무 뻔한 길은 가장 빠른 길이 아닐 수도 있어요.', `FemaleText_loc4`='四处找找看有没有新路线，有时候最快捷的路线并不是那么显而易见的！', `FemaleText_loc5`='眼觀四面尋找最短路徑。有時候最快的路並不是最明顯的!', `FemaleText_loc7`='Busca nuevas rutas. A veces el camino más rápido no es el más evidente.' WHERE `ID`=57392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람맞이 섬에서 마노 알을 찾을 수 있다는 말을 다른 수련생들에게 들었어요. 저도 찾고 또 찾아봤지만, 아직 하나도 발견하지 못했다는 건 자랑이 아니겠죠?!', `FemaleText_loc4`='我听其他受训者说，在临风岛上能找到玛瑙翔龙蛋。我找啊找啊，可却一个都没找到！', `FemaleText_loc5`='聽其他的受訓弟子說，你可以在嘯風島上找到稀有的瑪瑙蛟蛋。但我找了又找，還是沒找到任何一顆!', `FemaleText_loc7`='He oído decir a los demás alumnos que se pueden encontrar huevos de ónice en la Isla de Barlovento. He buscado y rebuscado, ¡pero todavía no he encontrado ni uno!' WHERE `ID`=57393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실력도 중요해요. 하지만 운이 모든 것을 좌우하는 때도 있어요.', `FemaleText_loc4`='技巧很重要，但归根结底有时候还得看运气。', `FemaleText_loc5`='技巧很重要，但有時候運氣決定最終結果。', `FemaleText_loc7`='La habilidad es importante, pero a veces la suerte es lo que importa.' WHERE `ID`=57394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 당신이 꼴찌로 들어와도 저는 당신을 응원할 거예요.', `FemaleText_loc4`='别担心，就算你最后一个冲过比赛终点，我也会为你呐喊助威的！', `FemaleText_loc5`='別擔心，就算你晚到了我也會幫你留一份!', `FemaleText_loc7`='No te preocupes, ¡te animaré aunque acabes en último lugar!' WHERE `ID`=57395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 최고의 기수는 아니지만, 제 발명품은 최고랍니다!', `MaleText_loc4`='我也许不是最棒的骑士，但却拥有一流的发明！', `MaleText_loc5`='我或許不是最好的騎士，但我有最好的發明!', `MaleText_loc7`='Puede que no sea el mejor jinete, ¡pero soy el mejor inventor!' WHERE `ID`=57396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 수련생들도 모두 훌륭한 기수들입니다. 저도 언젠가 저들처럼 뛰어난 기수가 될 겁니다. 그때까지 열심히 훈련해야겠습니다!', `MaleText_loc4`='其他弟子都是非常优秀的骑士。但愿有一天，我也能像他们那么出色。在那之前，我只要不懈地练习就行了！', `MaleText_loc5`='其他受訓弟子都是很好的騎士。我希望有一天能和他們一樣好。目前，我只需要持續練習!', `MaleText_loc7`='Los demás alumnos son muy buenos jinetes. Espero estar a su altura algún día. Mientras tanto, no puedo dejar de entrenar.' WHERE `ID`=57397;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어린 용을 돌보는 것은 매우 섬세한 작업이에요.', `FemaleText_loc4`='照顾幼年翔龙可是一门精细活儿。', `FemaleText_loc5`='照料年輕蛟龍是很微妙的事。', `FemaleText_loc7`='Cuidar de un dragón joven es un asunto delicado.' WHERE `ID`=57398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='둥지를 청소하는 일을 도와줄 생각이 없다면, 그냥 제가 일을 계속하게 내버려 두세요.', `FemaleText_loc4`='除非你愿意帮我清理龙穴，否则你最好让我回去工作。', `FemaleText_loc5`='除非你想要幫我清理這些巢，否則你最好讓我回去工作。', `FemaleText_loc7`='Será mejor que me dejes trabajar, a no ser que quieras ayudarme a limpiar los nidos.' WHERE `ID`=57399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 하루의 절반 정도는 도서관에서 보내고, 나머지는 새끼 운룡들을 돌보며 보내요.', `FemaleText_loc4`='我一半的时间花在这座图书馆上，另一半的时间则花在照顾这些雏龙身上了。', `FemaleText_loc5`='我花了大半輩子在圖書館裡，另一半時間則是照料小戰蛟。', `FemaleText_loc7`='Me paso la mitad del tiempo en la biblioteca y la otra mitad cuidando de las proles.' WHERE `ID`=57400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용 기수의 역사에 대해 알고 계세요? 꽤 재미있는 이야기랍니다.', `FemaleText_loc4`='你了解翔龙骑士的历史吗？那是个非常有趣的故事。', `FemaleText_loc5`='你知道蛟龍騎士的歷史嗎?這是門很有趣的學問。', `FemaleText_loc7`='¿Conoces la historia de los jinetes de dragones? Es bastante interesante.' WHERE `ID`=57401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가 저는 고대의 지식을 살려낼 생각이에요. 막대한 지식이 오랜 세월에 묻혀 사라져 버렸거든요.', `FemaleText_loc4`='我希望有一天能增进我们的古老知识，其中绝大多数都在历史的长河中遗失了。', `FemaleText_loc5`='有一天我希望能增進我們的古代知識。這些知識有很多隨著時間的流逝而散佚了。', `FemaleText_loc7`='Algún día me gustaría contribuir a nuestro conocimiento ancestral. Gran parte se ha perdido con el paso de los siglos.' WHERE `ID`=57402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가 세상의 다른 부분까지 살펴보시게 되면, 돌아와서 제게 이야기를 들려 주세요. 저는 용 기수의 모든 것을 알려드릴 테니까요.', `FemaleText_loc4`='等你将来见识过更多世面之后，记得回来跟我谈谈。我会把有关翔龙骑士的一切都告诉你。', `FemaleText_loc5`='有朝一日，當你見過更廣闊的世面，你該回來和我說話。我能告訴你關於蛟龍騎士的一切。', `FemaleText_loc7`='Algún día, cuando hayas visto más mundo, deberías volver y hablar conmigo. Te puedo contar todo sobre los jinetes de dragones.' WHERE `ID`=57403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡단의 일원이 되고 싶으면 안리 장로님과 대화해 보세요.', `FemaleText_loc4`='如果你想加入到我们的行列，就去跟安离长老谈一谈。', `FemaleText_loc5`='如果你有興趣加入我們的行列，去和安麗長老說話。', `FemaleText_loc7`='Habla con la ancestro Anli si te interesa unirte a nosotros.' WHERE `ID`=57404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 용 기수가 되고자 하는 이들을 모두 환영합니다. 하지만 시작하기 전에 어느 정도 경험이 있어야 합니다. 나중에 저를 다시 찾아오십시오.', `MaleText_loc4`='我们欢迎一切有志加入我们行列的人，但在开始之前，你需要积攒更多的经验。请稍后再来和我谈谈。', `MaleText_loc5`='我們歡迎所有想要加入的人，但你還需要更多經驗才能開始。請晚點再來找我。', `MaleText_loc7`='Damos la bienvenida a todos aquellos que quieren unirse a nuestras filas, pero te hace falta un poco más de experiencia para empezar. Habla conmigo más adelante.' WHERE `ID`=57405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신입 수련생이라고요?$B$B네, 그렇겠지요.$B$B머리에 피도 안 마른 자들이 두 눈을 반짝이며 여길 찾아와서는, 동방의 위대한 운룡을 그렇게 쉽게 데려갈 수 있을 거라고 생각하다니...$B$B신중히 생각해 보는 게 좋을 겁니다.$B$B이 길은 그렇게 쉬운 길이 아니니까요.$B$B운룡단은 훈련을 끝까지 견뎌낼 수 있는 잠재력을 지닌 수련생들만 받아들이고 있습니다.', `MaleText_loc4`='一个新弟子？$B$B嗯，当然了。$B$B看你们那眼睛发亮、尾巴乱摇的兴奋样儿，还以为能轻松带一条来自东方的云端翔龙回去呢。$B$B好吧，你们应该仔细考虑清楚。$B$B这条路可没那么好走。$B$B骑士团只接收那些有潜力将训练进行到底的弟子。', `MaleText_loc5`='新弟子?$B$B是的，當然了。$B$B你們一個個眼巴巴、尾巴翹翹地過來找我，想著領一條偉大的東方雲蛟回老家。$B$B那麼，你對這趟旅程最好考慮清楚。$B$B這可不是條簡單的路。$B$B雲蛟衛只接受那些有潛力可以完成全套訓練的的學生。', `MaleText_loc7`='Conque $gun nuevo:una nueva; estudiante, ¿eh?$B$BPor supuesto.$B$BTodos acudís a mí con chiribitas en los ojos y reverencias, pensando que os llevaréis a casa un gran dragón nuboso del este.$B$BBueno, quizás sea conveniente que te tomes dicho camino con calma.$B$BNo es una senda sencilla en absoluto.$B$BLa Orden solo acepta a estudiantes con el potencial de llegar al final del entrenamiento.' WHERE `ID`=57406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행자여, 도원에 잘 왔네.$B$B이곳은 운룡단의 거점이야. 운룡들과 함께 비취 숲을 수호하는 게 우리의 임무지.$B$B자네도 운룡단의 일원이 될 수 있네. 하지만, 우리와의 여정을 시작하기 전에 우선 경험을 더 쌓아야겠군.$B$B가서 이 땅을 더 탐험해 보게. 그리고 더 강해졌을 때, 나를 다시 찾아오게.', `FemaleText_loc4`='欢迎来到百木园，旅行者。$B$B这里是云端翔龙骑士团的家园。我们与我们的云端翔龙都将誓死守护翡翠林。$B$B你也可以加入我们的行列。但在开启这段旅程之前，你还需要更丰富的经验。$B$B在这片土地上游历一番，当你更加强大时，再回来找我吧。', `FemaleText_loc5`='歡迎來到落英園，旅人。$B$B這是雲蛟衛的大本營。和我們的雲蛟一起，我們立誓保衛翠玉林。$B$B你也可以加入我們的行列。然而，你得累積更多經驗才能開始這趟旅程。$B$B到這片土地上遊歷，等你變得更加強壯時再回來找我。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Arboretum, $gviajero:viajera;.$b$bEsta es la sede de la Orden del Dragón Nimbo. Hemos jurado defender el Bosque de Jade junto a nuestros dragones nimbo.$b$bTú también puedes unirte a nosotros, pero te hace falta experiencia para comenzar el viaje.$b$bVe, recorre esta tierra, y vuelve a verme cuando seas más fuerte.' WHERE `ID`=57407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투 운룡의 등을 타고 나는 것만큼 기분 좋은 일은 없죠.', `FemaleText_loc4`='再没有比骑在作战翔龙的背上翱翔更加精彩的体验了。', `FemaleText_loc5`='騎在戰蛟背上的體驗和什麼都不一樣。', `FemaleText_loc7`='Montar a lomos de un dragón de guerra es una experiencia única.' WHERE `ID`=57408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거칠고, 자기 실력도 모른 채... 당신은 그렇게 혼자 날고 있어요.$B$B이를 바꾸고 싶으면, 서쪽에 계신 안리 장로님과 대화해 보세요.', `FemaleText_loc4`='你很稚嫩，未经考验，榜上无名。只能独自飞翔。$B$B如果你想改变这一切，就去西边找安离长老谈一谈吧。', `FemaleText_loc5`='你初出茅廬，缺乏試煉，沒有地位。你獨自飛行。$B$B如果你想要改變這種情況，到西邊去找安麗長老。', `FemaleText_loc7`='Necesitas que te entrenen, te pongan a prueba y te otorguen un rango. Vuelas por libre.$b$bSi quieres cambiar tu situación, habla con la ancestro Anli, en el oeste.' WHERE `ID`=57409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 모습을 감상하러 또 한 분 찾아오셨군요! 제 명성이 정말 널리 퍼진 모양입니다.$B$B걱정 마세요. 언젠가 당신도 저와 함께 날 수 있는 날이 올 테니까요.', `MaleText_loc4`='啊，又一个崇拜着！我还真是声名远播啊。$B$B别难过，我们将来或许会有并驾齐驱的机会。', `MaleText_loc5`='啊，又一個崇拜者!想必我的名聲已經無遠弗屆。$B$B別擔心，有一天你和我或許會並肩而騎。', `MaleText_loc7`='¡Ah, $gotro admirador:otra admiradora;! Mi reputación me precede, de eso estoy seguro.$b$bNo te preocupes, quizás algún día volemos juntos.' WHERE `ID`=57410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마십시오. 비행은 보이는 것처럼 어렵지 않습니다.$B$B하지만 배 둘레가 몇 곱절 더 늘어날 만큼의 경험을 먼저 쌓아야 합니다.', `MaleText_loc4`='别担心，孩子。骑龙没有看上去那么困难。$B$B不过你尝试这个动作之前，还需要多加练习。', `MaleText_loc5`='別擔心，孩子。騎戰蛟不像看起來那麼難。$B$B不過，在嘗試前皮帶上最好多打幾個洞。', `MaleText_loc7`='No te preocupes, $ghijo:hija;. Ser jinete no es tan complicado como parece.$b$bAunque, antes de probar, deberías hacerte unos cuantos agujeros más en el cinturón.' WHERE `ID`=57411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요. 너무 바빠서 이방인과 한가하게 대화할 시간이 없네요.', `FemaleText_loc4`='抱歉，我不想把时间浪费在陌生人身上。', `FemaleText_loc5`='我很抱歉，我忙得沒法和陌生人說話。', `FemaleText_loc7`='Lo siento, pero estoy demasiado ocupada como para hablar con forasteros.' WHERE `ID`=57412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 어쩌면 언젠가 용 기수가 되기를 꿈꿀 수 있을 겁니다.', `MaleText_loc4`='也许有一天，你也会渴望成为一名翔龙骑士。', `MaleText_loc5`='或許有一天，你也會渴望成為一名蛟龍騎士。', `MaleText_loc7`='Algún día quizás también tú puedas aspirar a convertirte en un jinete de dragones.' WHERE `ID`=57413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요!$B$B우리처럼 용 기수가 되려면 경험을 더 쌓으셔야 할 것 같네요. 곧 다시 뵙길 바랄게요!', `FemaleText_loc4`='嗨，你好啊！$B$B在你加入我们之前，还有几季的课程等着你去学呢。', `FemaleText_loc5`='你好啊!$B$B你還需要幾季的鍛鍊才能加入我們。希望能早點見到你!', `FemaleText_loc7`='¡Hola!$b$bParece que te faltan unas cuantas estaciones para poder unirte a nosotros. ¡Espero verte pronto!' WHERE `ID`=57414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 경주가 뭐냐고요? 용 기수의 솜씨를 겨루는 최고, 최대의 시험장입니다!', `MaleText_loc4`='什么是飞行竞技赛？那当然是最能展现翔龙骑士技巧的一场大赛啦！', `MaleText_loc5`='什麼是天際競賽?怎麼說呢，就是對蛟龍騎士技巧的最偉大考驗!', `MaleText_loc7`='¿Qué es la carrera de los cielos? ¡Solo es la mayor prueba de habilidad para un jinete de dragones!' WHERE `ID`=57415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주에 참여하고 싶으십니까? 머리에 피도 안 말랐으면서?$B$B하! 하하하하하!$B$B개미가 거인에게 도전하는 격이군요!', `MaleText_loc4`='你也想来试试？一个像你这样乳臭未干的小子？$B$B哈哈！哈哈哈哈哈！$B$B你这是螳臂当车、不自量力啊！', `MaleText_loc5`='你想要參賽?像你這樣初出茅廬的菜鳥?$B$B哈!哈哈哈哈哈哈!$B$B螞蟻想與大象抗衡!', `MaleText_loc7`='¿Que quieres competir? ¿Un cachorro inexperto como tú?$b$b¡Ja! ¡Ja ja ja ja ja ja!$b$b¡Eres una hormiga que quiere competir contra gigantes!' WHERE `ID`=57416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 도와주십시오!', `MaleText_loc4`='帮帮我，$p！', `MaleText_loc5`='幫一下$p!', `MaleText_loc7`='¡Socorro, $p!', `FemaleText_loc1`='$p 님, 도와주세요!', `FemaleText_loc4`='帮帮我，$p！', `FemaleText_loc5`='幫一下$p!', `FemaleText_loc7`='¡Socorro, $p!' WHERE `ID`=57417;
