UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 가까이에 모구가 있습니다! 조심하십시오!', `MaleText_loc4`='$p！这附近有魔古族！小心！', `MaleText_loc5`='$p!附近有魔古!小心!', `MaleText_loc7`='¡$p! ¡Hay mogu cerca! ¡Cuidado!', `FemaleText_loc1`='$p 님, 가까이에 모구가 있어요! 조심하세요!', `FemaleText_loc4`='$p！这附近有魔古族！小心！', `FemaleText_loc5`='$p!附近有魔古!小心!', `FemaleText_loc7`='¡$p! ¡Hay mogu cerca! ¡Cuidado!' WHERE `ID`=57419;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='1등이라고? 오호라!$B$B젊은 수련생 치고는 정말 대단하군.', `FemaleText_loc4`='第一名？哇！$B$B对像你这么年轻的弟子来说，这已经很不错了。', `FemaleText_loc5`='第一名?哇!$B$B以年輕受訓弟子來講真是相當好。', `FemaleText_loc7`='¿Primer puesto? ¡Vaya!$b$bEstá bastante bien para $gun:una; joven $galumno:alumna;.' WHERE `ID`=57420;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 2등만 해도 대단한 거네. 다음에는 꼭 1등을 차지하게.', `FemaleText_loc4`='嘿，第二名也不赖。你下次就能超过他们啦。', `FemaleText_loc5`='嘿，第二名還算不賴。下次你會贏過他們的。', `FemaleText_loc7`='Oye, quedar segundo no está nada mal. La próxima podrás con ellos.' WHERE `ID`=57421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='3등 안에 든 것만 해도 충분히 놀라운 성과라네. 그래도 앞쪽이 뒤쪽보다 낫지 않겠나?', `FemaleText_loc4`='能进入前三名已经很不错了。名列前茅总比排名倒数要体面嘛，对吧？', `FemaleText_loc5`='前三名可說相當了不起。前段班總比後段班好，對嗎?', `FemaleText_loc7`='Acabar entre los tres primeros sigue siendo un buen resultado. Mejor estar en la primera mitad que en la segunda mitad, ¿no?' WHERE `ID`=57422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='4등이라... 놀라운 성과는 아니군. 그래도 괜찮네. 언제든 다시 경주에 참여할 수 있으니까.', `FemaleText_loc4`='第四名。嗯，不算很出色。不过没关系。你可以再试一次。', `FemaleText_loc5`='第四名。好吧，不是很突出。沒關係，你總是能再試一次。', `FemaleText_loc7`='Cuarto puesto. Bueno, no es extraordinario, pero está bien. Siempre puedes volverlo a intentar.' WHERE `ID`=57423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='5등? 그래도 꼴등은 아니었으니 다행이군.', `FemaleText_loc4`='第五名？好歹你不是最后一名。', `FemaleText_loc5`='第五名?至少你不是最後。', `FemaleText_loc7`='¿Quinto puesto? Bueno, al menos no has sido $gel último:la última;.' WHERE `ID`=57424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꼴등으로 들어왔군.$B$B이제 더 떨어질 곳이 없으니, 올라갈 일만 남았겠지?', `FemaleText_loc4`='好吧，你是最后一名。$B$B硬着头皮也得上啊，不是吗？', `FemaleText_loc5`='好吧!你是最後一名。$B$B不過往好處想，以後也就只有進步的空間囉?', `FemaleText_loc7`='Bueno, ¿y qué si has terminado $gel último:la última;?$b$b¡Ya solo puedes ir a mejor!' WHERE `ID`=57425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 너무 감사합니다!', `MaleText_loc4`='真是太感谢你了，$p！', `MaleText_loc5`='太感謝你了，$p!', `MaleText_loc7`='¡Muchas gracias, $p!', `FemaleText_loc1`='$p 님, 너무 감사해요!', `FemaleText_loc4`='真是太感谢你了，$p！', `FemaleText_loc5`='太感謝你了，$p!', `FemaleText_loc7`='¡Muchas gracias, $p!' WHERE `ID`=57426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 놈들이 우리를 노예로 삼을 거라고 했습니다.', `MaleText_loc4`='谢谢你！他们说，我们要变成奴隶了。', `MaleText_loc5`='謝謝你!他們說要把我們當作奴隸。', `MaleText_loc7`='¡Gracias! Decían que seríamos esclavos.', `FemaleText_loc1`='감사해요! 놈들이 우리를 노예로 삼을 거라고 했답니다.', `FemaleText_loc4`='谢谢你！他们说，我们要变成奴隶了。', `FemaleText_loc5`='謝謝你!他們說要把我們當作奴隸。', `FemaleText_loc7`='¡Gracias! Decían que seríamos esclavos.' WHERE `ID`=57427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 이 은혜를 절대 잊지 않겠습니다.', `MaleText_loc4`='我永远都不会忘记的，英雄。', `MaleText_loc5`='我永遠不會忘記這件事，英雄。', `MaleText_loc7`='Nunca olvidaré esto, $ghéroe:heroína;.', `FemaleText_loc1`='영웅이여, 이 은혜를 절대 잊지 않을게요.', `FemaleText_loc4`='我永远都不会忘记的，英雄。', `FemaleText_loc5`='我永遠不會忘記這件事，英雄。', `FemaleText_loc7`='Nunca olvidaré esto, $ghéroe:heroína;.' WHERE `ID`=57428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 노예와 무기를 찾고 있다고 했습니다.', `MaleText_loc4`='他们说，他们在找奴隶和武器。', `MaleText_loc5`='他們說他們在尋找奴隸跟武器。', `MaleText_loc7`='Decían que buscaban esclavos y armas.', `FemaleText_loc1`='놈들이 노예와 무기를 찾고 있다고 했어요.', `FemaleText_loc4`='他们说，他们在找奴隶和武器。', `FemaleText_loc5`='他們說他們在尋找奴隸跟武器。', `FemaleText_loc7`='Decían que buscaban esclavos y armas.' WHERE `ID`=57429;
