UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 하루 더 잠이나 잘까 봐...', `MaleText_loc4`='看来我再睡上一天好了……', `MaleText_loc5`='我猜我又要睡上一天了...', `MaleText_loc7`='Creo que voy a dormir otro día más...', `FemaleText_loc1`='그냥 하루 더 잠이나 잘까 봐...', `FemaleText_loc4`='看来我再睡上一天好了……', `FemaleText_loc5`='我猜我又要睡上一天了...', `FemaleText_loc7`='Creo que voy a dormir otro día más...' WHERE `ID`=57432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가시오! 우리 일은 우리가 알아서 할 거요. "모험가"의 도움 따위는 필요 없소!', `MaleText_loc4`='走开！朱家堡能自己解决问题。我们不需要什么所谓的“冒险者”插手！', `MaleText_loc5`='離開!祝家守望站的事情輪不到外人來管。我們不需要所謂「冒險者」的幫助!', `MaleText_loc7`='¡Lárgate! La Atalaya de Zhu puede defenderse sola. ¡No necesitamos la ayuda de los que os hacéis llamar "aventureros"!' WHERE `ID`=57433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님, 제 기초 수련을 다시 해보고 싶습니다.', `MaleText_loc4`='大师，我想要重温一下基础训练。', `MaleText_loc5`='大師，我想複習我的基礎訓練。', `MaleText_loc7`='Maestro, deseo repetir mi entrenamiento básico.', `FemaleText_loc1`='스승님, 제 기초 수련을 다시 해보고 싶어요.', `FemaleText_loc4`='大师，我想要重温一下基础训练。', `FemaleText_loc5`='大師，我想複習我的基礎訓練。', `FemaleText_loc7`='Maestro, deseo repetir mi entrenamiento básico.' WHERE `ID`=57434;
