UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토지파괴자 브로자이가 버려진 수호자를 되살립니다.', `MaleText_loc4`='碎地者勃罗耶正在复活废墟守卫。', `MaleText_loc5`='創始者布歐齋正讓廢墟守護者復活。', `MaleText_loc7`='Quebrantasuelos Brojai está reviviendo a un guardián en ruinas.' WHERE `ID`=57436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 권능 앞에 무릎 꿇기를 거부하느냐? 그렇다면 벌레같이 죽어라.', `MaleText_loc4`='你不愿意臣服于我们的力量？那就像个渣滓一样死掉吧。', `MaleText_loc5`='你不願臣服於我們的力量?那就像隻兔妖一樣的死去吧。', `MaleText_loc7`='¿Se niegan a arrodillarse ante nuestro poder? Entonces mueran como las ratas que son.' WHERE `ID`=57437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 모구 놈들은... 생각보다 강한 데다 영리하기까지 하군. 자네는 여기 오지 말았어야 하네. 이건 함정일세.', `MaleText_loc4`='这些……魔古族……比我预想的还要难对付，也更聪明。你不该来的，这是个陷阱。', `MaleText_loc5`='這些...魔古...比我所想的要更兇悍，也更聰明。你不該來的，這是個陷阱。', `MaleText_loc7`='Estos... mogu... son más duros de lo que yo pensaba. Y más inteligentes. No deberías haber venido, esto es una trampa.' WHERE `ID`=57438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<코르 블러드터스크를 속박에서 풀어주려고 해 봅니다.>', `MaleText_loc4`='<尝试解除科尔·血牙的束缚。>', `MaleText_loc5`='<試著把柯爾·血牙身上的繩子解開。>', `MaleText_loc7`='<Intenta liberar a Kor Sangradiente de sus ataduras.>', `FemaleText_loc1`='<코르 블러드터스크를 속박에서 풀어주려고 해 봅니다.>', `FemaleText_loc4`='<尝试解除科尔·血牙的束缚。>', `FemaleText_loc5`='<試著把柯爾·血牙身上的繩子解開。>', `FemaleText_loc7`='<Intenta liberar a Kor Sangradiente de sus ataduras.>' WHERE `ID`=57439;
