UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $p, 이리 와 봐라! 컨컨, 슬픈 판다렌들 고치는 법 알 것 같다!', `MaleText_loc4`='嘿，$p，到这儿来！肯肯觉得自己已经知道该如何帮助那些悲伤的熊猫了！', `MaleText_loc5`='嘿，$p，到這裡來!肯·肯認為他知道如何讓悲傷的熊貓振作起來!', `MaleText_loc7`='¡Eh, $p, tú viene akí! ¡Ken-Ken kree ke sabe kómo animar a los pandas tristes!' WHERE `ID`=57441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신사 숙녀 여러분, 다들 제 승리에 찬사를 보낼 준비를 하십시오!', `MaleText_loc4`='女士们、先生们，准备仰望我的胜利吧！', `MaleText_loc5`='準備好迎接我的勝利，女士先生們!', `MaleText_loc7`='¡Preparaos para disfrutar de mi victoria, damas y caballeros!' WHERE `ID`=57442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주가 끝난 후에는 춤추는 용 여관으로 가서 제 승리를 축하하지요. 첫 잔은 당신이 사는 겁니다!', `MaleText_loc4`='比赛结束后到龙舞楼喝一杯？就当是庆祝我夺冠嘛。第一轮你请！', `MaleText_loc5`='比賽結束後到舞龍客棧來慶祝我的勝利。第一輪的酒給你請!', `MaleText_loc7`='¿Quedamos en el Dragón Danzante después de la carrera? ¡Tú invitas a la primera ronda!' WHERE `ID`=57443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 아름다운 얼굴에 먹칠을 할 수는 없지요.', `MaleText_loc4`='我是不会让这张漂亮的脸蛋儿沾上一点泥巴的。', `MaleText_loc5`='我這美麗的臉上可不能沾到任何一點灰塵。', `MaleText_loc7`='Esta hermosa cara no se va a manchar de tierra.' WHERE `ID`=57444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 구름 자석입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个吸云石！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的吸雲磁鐵!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es un imán de nubes!' WHERE `ID`=57445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 원격 조종 기수 추락기입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个遥控骑手弹射器！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的遙控騎士彈出器!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es un desmontador de jinetes por control remoto!' WHERE `ID`=57446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아차차! 제 최신 발명품 맛을 보시죠! 무슨 발명품인지 힌트를 드릴까요? 호박 흡수기입니다!', `MaleText_loc4`='嘿嘿！你们这些家伙等着看我的最新发明啊！我会给你们一个提示，它是一个南瓜雨！', `MaleText_loc5`='啊呃!讓你們這些傢伙見識一下我最新的發明!讓我給點提示。這是南瓜沐浴球!', `MaleText_loc7`='¡Ey! ¡Esperad a ver mi último invento! Os daré una pista: ¡es un regador de calabazas!' WHERE `ID`=57447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아차차! 제 최신 발명품 맛을 보시죠! 무슨 발명품인지 힌트를 드릴까요? 호박 로켓입니다!', `MaleText_loc4`='嘿嘿！你们这些家伙等着看我的最新发明啊！我会给你们一个提示，它是一个南瓜火箭！', `MaleText_loc5`='啊呃!讓你們這些傢伙見識一下我最新的發明!讓我給點提示。這是南瓜火箭!', `MaleText_loc7`='¡Ey! ¡Esperad a ver mi último invento! Os daré una pista: ¡es un cohete calabacín!' WHERE `ID`=57448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 급속 깃발 추출기입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个快速摘旗器！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的快速旗幟攫取器!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es un extractor de banderas!' WHERE `ID`=57449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 통과 지점 탐지기입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个检查点查找器！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的紀錄位置偵測器!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es un buscador de puntos de control!' WHERE `ID`=57450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 바람 반사기입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个风动器！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的偏風器!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es un reflector de viento!' WHERE `ID`=57451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 발명품으로 모두를 따돌리겠어요! 자, 당근 달린 지팡이입니다!', `MaleText_loc4`='我要用我的新发明打败你们。它是一个棍子上的胡萝卜！', `MaleText_loc5`='讓我用我最新的發明來擊敗你們全部!看我的棒子上的胡蘿蔔!', `MaleText_loc7`='Os voy a ganar a todos con mi último invento. ¡Es una zanahoria pinchada en un palo!' WHERE `ID`=57452;
