UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스승님, 고급 훈련을 다시 해보고 싶습니다.', `MaleText_loc4`='大师，我想要重温一下进阶训练。', `MaleText_loc5`='大師，我想複習我的高級訓練。', `MaleText_loc7`='Maestro, deseo repetir mi entrenamiento avanzado.', `FemaleText_loc1`='스승님, 고급 훈련을 다시 해보고 싶어요.', `FemaleText_loc4`='大师，我想要重温一下进阶训练。', `FemaleText_loc5`='大師，我想複習我的高級訓練。', `FemaleText_loc7`='Maestro, deseo repetir mi entrenamiento avanzado.' WHERE `ID`=57458;
