UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 영원한 안식을 주마!', `MaleText_loc4`='我要超度你！', `MaleText_loc5`='我賦予你永恆的寧靜!', `MaleText_loc7`='¡Te concedo la paz eterna!' WHERE `ID`=57462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 존재를 없애주겠다!', `MaleText_loc4`='我要结果了你！', `MaleText_loc5`='我從現世解放你!', `MaleText_loc7`='¡Te libero de esta existencia!' WHERE `ID`=57463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 거기! 거기 자네들! 내 신성한 도서관이 샤의 손아귀에 넘어갔네!', `MaleText_loc4`='说你呢！在椽子那儿的！煞魔侵占了我神圣的藏书阁！', `MaleText_loc5`='喂!樑那邊的!煞佔據了我神聖的藏卷閣!', `MaleText_loc7`='¡Escúchenme, los de arriba! ¡Los sha han poseído mi biblioteca sagrada!' WHERE `ID`=57464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 이 신성한 두루마리의 글자들에서 쏟아져 나오고 있어... 변질시키고, 더럽히고 있네!', `MaleText_loc4`='看看它们是怎么对待这些神圣书卷的……腐化它们！亵渎它们！', `MaleText_loc5`='看看他們對這些神聖卷軸上的文字做了什麼...要腐化了!要弄髒了!', `MaleText_loc7`='Miren cómo salen de cada letra de los pergaminos sagrados... ¡Los corrompen! ¡Los profanan!' WHERE `ID`=57465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두루마리 타락도 여기까지다!', `MaleText_loc4`='你休想再玷污这些书卷！', `MaleText_loc5`='你無法再污染這些卷軸了!', `MaleText_loc7`='¡No volverás a profanar esos pergaminos!' WHERE `ID`=57466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락의 원천을 파괴해야 하네! 서두르게, 우리 소중한 역사가 지워지기 전에 막아야 해!', `MaleText_loc4`='你必须消灭腐化的源头！快，否则宝贵的历史就要被永久抹除了！', `MaleText_loc5`='你們一定要消滅腐化的源頭!快，別讓我們珍貴的歷史記錄消失!', `MaleText_loc7`='¡Deben destruir el origen de la corrupción! ¡Rápido, antes de que nuestra valiosa historia se pierda para siempre!' WHERE `ID`=57467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 보통 깡패나 도적에 지나지 않아요. 제가 보기엔 비전 마법을 쓸 만큼 참을성이 있는 종족 같진 않았어요.', `MaleText_loc4`='魔古族大多是些暴徒和强盗。在我印象中，他们向来没有学习奥术魔法的耐心。', `MaleText_loc5`='魔古通常都是惡棍與強盜，據我所知他們從沒有耐心去用秘法魔法。', `MaleText_loc7`='Los mogu suelen ser matones y bandidos. No me pega que tengan suficiente paciencia para las magias arcanas.' WHERE `ID`=57468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르자 폐허는 예전에 뭔가 중요한 일이 있었던 곳일 거예요. 역사 시간에 그 이야기가 나올 때 제가 좀 졸았던 모양이네요.', `MaleText_loc4`='我猜，科夏废墟就是某个重大事件的发生地。我可能是在那节历史课上打盹了。', `MaleText_loc5`='我猜想，廓亞廢墟在歷史上曾經發生一些重要的事。大概吧。我上歷史課的時候可能睡著了。', `MaleText_loc7`='Las ruinas de Korja deben de haber sido testigo de algo importante, supongo. Me quedaría dormido durante esa clase de historia.' WHERE `ID`=57469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들었어요? 데즈코가 쌍둥이 중 한 명의 이름을 $p|1이라고;라고; 지었대요.', `MaleText_loc4`='你听说了吗？德兹科给双胞胎之一起名为“$p”了。', `MaleText_loc5`='你聽說了嗎?戴斯可把雙胞胎的其中一個命名為「$p」。', `MaleText_loc7`='¿Has oído? Dezco ha llamado a uno de sus gemelos "$p".' WHERE `ID`=57470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데굴데굴 동호회의 첫 번째 규칙은 데굴데굴 동호회에 대해 이야기하지 않는 것.$B$B두 번째 규칙은 처음 나온 사람은 무조건 구르는 것.', `MaleText_loc4`='翻滚俱乐部的第一条规则：不要议论翻滚俱乐部。$B$B翻滚俱乐部的第二条规则：如果是你的第一次，你就翻滚吧。', `MaleText_loc5`='翻滾俱樂部的第一條守則:你不能談論翻滾俱樂部。
翻滾俱樂部的第二條守則:如果你是第一次來，就要翻滾。', `MaleText_loc7`='La primera regla del club del giro es: nadie habla del club del giro.$b$bLa segunda regla del club del giro es: si es tu primera vez, tienes que girar.' WHERE `ID`=57471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 굴러 보지요.', `MaleText_loc4`='让我们翻滚起来。', `MaleText_loc5`='我們翻滾吧。', `MaleText_loc7`='A girar.', `FemaleText_loc1`='그럼 굴러 보죠.', `FemaleText_loc4`='让我们翻滚起来。', `FemaleText_loc5`='我們翻滾吧。', `FemaleText_loc7`='A girar.' WHERE `ID`=57475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 이방인이여.', `MaleText_loc4`='谢谢你，陌生人。', `MaleText_loc5`='謝謝你，陌生人。', `MaleText_loc7`='Gracias, $gdesconocido:desconocida;.', `FemaleText_loc1`='감사해요, 이방인이여.', `FemaleText_loc4`='谢谢你，陌生人。', `FemaleText_loc5`='謝謝你，陌生人。', `FemaleText_loc7`='Gracias, $gdesconocido:desconocida;.' WHERE `ID`=57476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 계속 감시할 겁니다.', `MaleText_loc4`='我将继续守护。', `MaleText_loc5`='我繼續守夜。', `MaleText_loc7`='Mi vigilancia continua.' WHERE `ID`=57477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 죽기 전까지 싸웁니다. 그리고 가끔 죽어서도 싸웁니다.', `MaleText_loc4`='我们效忠至死，有时在死后也依然效忠。', `MaleText_loc5`='我們到死都是僕人，有時死了之後還是要當僕人。', `MaleText_loc7`='Servimos hasta la muerte, y a veces incluso después.' WHERE `ID`=57478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장으로 돌아가 다시 싸우겠습니다.', `MaleText_loc4`='我要让敌人再尝尝我的拳头。', `MaleText_loc5`='我會帶著雙拳重回戰場。', `MaleText_loc7`='Llevaré mis puños de vuelta a la batalla.' WHERE `ID`=57479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가벼운 상처일 뿐입니다.', `MaleText_loc4`='只是皮肉伤。', `MaleText_loc5`='只是皮肉傷。', `MaleText_loc7`='Solo es un rasguño.' WHERE `ID`=57480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 퀴라지 전쟁의 최전선에서 싸웠고, 아졸네룹의 심연으로도 돌격했었소. 곤충 떼를 방치하면 어디까지 위험해질 수 있는지, 겪어서 알고 있다오.', `MaleText_loc4`='我曾在其拉之战中奋战在最前线，也曾在艾卓——尼鲁布深渊中冲锋陷阵。我完全了解，一支放任自流的昆虫军团会对我们的世界造成多大的威胁。', `MaleText_loc5`='我曾在其拉戰爭的第一線戰鬥，並且攻入阿茲歐-奈幽的深淵。我很清楚知道，蟲人軍團一旦不受抑制，可以給世界帶來多大的威脅。', `MaleText_loc7`='Luché en los frentes de la guerra de Qiraji y cargué en las profundidades de Azjol-Nerub. Conozco de primera mano la amenaza que una legión de insectos puede suponer para el mundo cuando no se les tiene controlados.' WHERE `ID`=57481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 서쪽으로 가고 있었는데, 사마귀 놈들이 공격했다는 소식을 듣고 이리로 방향을 틀었소.', `MaleText_loc4`='在得知螳螂妖袭击的消息时，我们正在向西进发，随后我们就改变方向来到了这里。', `MaleText_loc5`='我們獲知螳螂人攻擊的消息時正在往西走，於是改道前來這裡。', `MaleText_loc7`='Nos dirigíamos hacia el oeste cuando nos informaron sobre el ataque mántide y nos encaminamos hacia aquí.' WHERE `ID`=57482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자가 보고 싶소.', `MaleText_loc4`='我想念莱莎。', `MaleText_loc5`='我想念麗紗。', `MaleText_loc7`='Añoro a Leza.' WHERE `ID`=57483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다렌들은 민간인 신분인데도 노련한 전사들이군.', `MaleText_loc4`='即便是平民，这些熊猫人也是技巧高超的战士。', `MaleText_loc5`='這些熊貓人連平民都是技巧高超的戰士。', `MaleText_loc7`='Estos pandaren son guerreros habilidosos, pese a ser civiles.' WHERE `ID`=57484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀와 사우록, 모구, 열병, 그리고 밀림의 셀 수 없는 야수들 사이에서도, 나는 내 아이들에게서 눈을 떼지 않을 거요.', `MaleText_loc4`='在这个螳螂妖、蜥蜴人、魔古族、热疫和无数的丛林野兽横行的地方，我绝不会让我的孩子离开我的视线。', `MaleText_loc5`='這個叢林中有螳螂人、薩烏怪、魔古、熱疫，還有數不盡的野獸，我拒絕讓我的孩子離開視線範圍。', `MaleText_loc7`='Entre mántides, soren, mogu, fiebres y las incontables bestias de esta jungla, me niego a perder de vista a mis hijos.' WHERE `ID`=57485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀요?! 놈들은 판다렌이 아이들에게 이야기해주는 으스스한 전설 속에나 나오는 줄 알았어요.', `MaleText_loc4`='螳螂妖？！我一直以为他们只是熊猫人讲给自己孩子听的恐怖传说。', `MaleText_loc5`='螳螂人?!我以為這只是熊貓人用來嚇小孩的怪誕傳奇而已。', `MaleText_loc7`='¡¿Los mántides?! Siempre pensé que eran una espeluznante leyenda que los pandaren les contaban a sus hijos.' WHERE `ID`=57486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 전설적이죠. 판다리아에서 그들에게 맞설 자는 없어요.', `MaleText_loc4`='影踪派充满了传奇色彩。他们的实力在潘达利亚是无可匹敌的。', `MaleText_loc5`='影潘是一個傳說，他們的武功在潘達利亞所向無敵。', `MaleText_loc7`='El Shadopan es legendario. Su fuerza no tiene rival en Pandaria.' WHERE `ID`=57487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 만난 이후로, 저는 전설 속 존재들과 싸웠고, 수도 없는 신비를 보았어요.', `MaleText_loc4`='遇见你以来，我们经历了传奇般的战斗，见证了数不清的奇迹。', `MaleText_loc5`='自從遇見你，我便和許多傳奇人物作戰，還見識到了無數奇景。', `MaleText_loc7`='Desde la última vez que te vi, he luchado contra leyendas y he visto innumerables maravillas.' WHERE `ID`=57488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 영웅이여.', `MaleText_loc4`='谢谢你，英雄。', `MaleText_loc5`='謝謝你，英雄。', `MaleText_loc7`='Gracias, $ghéroe:heroína;.', `FemaleText_loc1`='감사해요, 영웅이여.', `FemaleText_loc4`='谢谢你，英雄。', `FemaleText_loc5`='謝謝你，英雄。', `FemaleText_loc7`='Gracias, $ghéroe:heroína;.' WHERE `ID`=57489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 돌밭으로 가야만 합니다! 사마귀들이 곧 공격해 올 겁니다.', `MaleText_loc4`='我必须赶到石犁村去！螳螂妖很快就会发动进攻了。', `MaleText_loc5`='我必須到石犁村去!螳螂人很快就會攻過來了。', `MaleText_loc7`='¡Debo llegar a Villarroca! Los mántides van a atacar pronto.', `FemaleText_loc1`='저는 돌밭으로 가야만 해요! 사마귀들이 곧 공격해 올 거예요.', `FemaleText_loc4`='我必须赶到石犁村去！螳螂妖很快就会发动进攻了。', `FemaleText_loc5`='我必須到石犁村去!螳螂人很快就會攻過來了。', `FemaleText_loc7`='¡Debo llegar a Villarroca! Los mántides van a atacar pronto.' WHERE `ID`=57490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 사마귀들과 싸우다가 후퇴하려고 할 때, 모구가 기습해 왔습니다.', `MaleText_loc4`='魔古族在我们躲避螳螂妖的途中伏击了我们。', `MaleText_loc5`='當我們試著從螳螂人的攻擊中撤退時，卻遭到魔古的埋伏。', `MaleText_loc7`='Los mogu nos asaltaron cuando intentábamos huir de los mántides.', `FemaleText_loc1`='우리가 사마귀들과 싸우다가 후퇴하려고 할 때, 모구가 기습해 왔어요.', `FemaleText_loc4`='魔古族在我们躲避螳螂妖的途中伏击了我们。', `FemaleText_loc5`='當我們試著從螳螂人的攻擊中撤退時，卻遭到魔古的埋伏。', `FemaleText_loc7`='Los mogu nos asaltaron cuando intentábamos huir de los mántides.' WHERE `ID`=57491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 이방인이여.', `MaleText_loc4`='谢谢你，陌生人。', `MaleText_loc5`='向你致上我的謝意，陌生人。', `MaleText_loc7`='Te lo agradezco, $gforastero:forastera;.', `FemaleText_loc1`='고마워요, 이방인이여.', `FemaleText_loc4`='谢谢你，陌生人。', `FemaleText_loc5`='我向你致上我的謝意，陌生人。', `FemaleText_loc7`='Te lo agradezco, $gforastero:forastera;.' WHERE `ID`=57492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 특사가 주학사로 가고 있을 때 모구들이 기습했습니다.', `MaleText_loc4`='当我们遭到魔古族的伏击时，我们的使者正在去朱鹤寺的路上。', `MaleText_loc5`='當魔古伏擊我們的時候，我們的使者正朝紅鶴寺前進。', `MaleText_loc7`='Nuestro enviado se dirigía al Templo de la Grulla cuando los mogu nos asaltaron.' WHERE `ID`=57493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 당신이 이 "사마귀"라는 놈들을 상대해 주게. 그러면 우리는 계속 모구를 공격할 수 있네. 운이 좋으면 우리도 곧 합류할 수 있을 걸세.', `MaleText_loc4`='$p，帮我们拖住这些“螳螂妖”，我们要继续攻击魔古族的人。运气好的话，我们很快就能来支援你了。', `MaleText_loc5`='先面對這些「螳螂人」$p，然後再繼續攻擊魔古。運氣好的話，我們很快就會加入你。', `MaleText_loc7`='Enfréntate a estos "mántides", $p, y nosotros continuaremos nuestro asalto a los mogu. Con un poco de suerte, nos uniremos a ti en breve.' WHERE `ID`=57494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약탈자를 아무리 처치해도 공격이 끊이지가 않습니다. 대체 어떻게 그럴 수 있는지 모르겠습니다.', `MaleText_loc4`='我很奇怪，这些袭击者为什么能不计伤亡地拼命攻击我们。', `MaleText_loc5`='我實在搞不懂，不管我們殺掉多少劫掠者，他們還是會源源不絕地湧出來攻擊我們。', `MaleText_loc7`='No lo entiendo... no paramos de matar a estos asaltantes, pero aparecen otros que siguen atacándonos.' WHERE `ID`=57495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약탈자들은 주민의 시체에서 옷을 벗기고, 집에서 귀금속을 털고, 대장간에서는 주괴를 훔치고 있습니다. 어떻게 그런 짓을 할 수 있습니까?', `MaleText_loc4`='他们扒走了遇难者身上的衣物，偷走了我们家里的装饰品，还掠走了我们熔炼出来的铁锭。这是什么样的行径？', `MaleText_loc5`='這些劫掠者從我們人民的屍體上偷走衣物，從我們的家偷走物品，還從我們的熔爐偷走鑄鐵塊。這是什麼樣的道理啊?', `MaleText_loc7`='Estos asaltantes han robado la ropa de nuestros muertos, los abalorios de nuestras casas y los lingotes de nuestra fragua. ¿Qué forma de comportarse es esa?' WHERE `ID`=57496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보통은 주학사에서 원군을 보내 약탈자들을 막아 줍니다. 그런데 최근에는 주학사 쪽이 조용하군요.', `MaleText_loc4`='朱鹤寺通常都会来帮我们抵御这些强盗。但近来他们却一点动静也没有。', `MaleText_loc5`='紅鶴寺通常會來幫我們防守並擋住那些劫掠者，但最近他們那裡沒什麼音訊。', `MaleText_loc7`='El Templo de la Grulla suele acudir en nuestra defensa y mantiene a los asaltantes a raya, pero últimamente no se han manifestado.' WHERE `ID`=57497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $p 님. 물이 당신이 온다는 것을 예견했습니다. 불행히도 약탈자들이 이토록 강하게 공격해올 것은 예견하지 못했지만 말입니다.$b$b저는 물예언자인 지친 슈션이라고 합니다. 가을노래 마을에 오신 것을 환영합니다.', `MaleText_loc4`='欢迎你，$p。水流预言了你的到来。不幸的是，它们并没有预言这些强盗会下手这么重。$b$b我是水语者疲惫的苏什。欢迎来到瀑歌村。', `MaleText_loc5`='你好，$p。水已預知你會來到這裡。可惜它們沒預料到我們會受到如此猛烈的攻擊。$b$b我是水語者疲勞的舒申，歡迎來到秋歌。', `MaleText_loc7`='Saludos, $p. Las aguas nos avisaron de tu llegada. Por desgracia, no nos avisaron de que los asaltantes nos atacarían con tanta vehemencia.$b$bSoy el orador del agua Shushen el Exhausto. Te doy la bienvenida a Canción de Otoño.' WHERE `ID`=57498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<힘겹게 이마의 땀을 훔치는 농부 윤>$B$B절망이야! 이 바위는 절대로 옮길 수가 없겠어!', `MaleText_loc4`='<农夫老愚疲惫地揉着眉头。>$B$B一点希望都没有！我永远也搬不光这些石头了！', `MaleText_loc5`='<農夫尹疲倦地擦了擦額頭。>$B$B沒希望了!我永遠也沒辦法移動這些石頭!', `MaleText_loc7`='<El granjero Yoon se limpia la frente con cansancio.>$B$B¡No hay nada que hacer! ¡Nunca conseguiré mover estas rocas!' WHERE `ID`=57499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르, 왜 그런 거냐? 목숨을 던지면서까지 복수할 가치는 없는 것을.', `MaleText_loc4`='科尔，你为什么要这样做？为了复仇而把命给搭进去，不值得呀。', `MaleText_loc5`='柯爾·血牙，你為什麼要這麼作?為了復仇而死並不值得。', `MaleText_loc7`='Kor, ¿por qué lo has hecho? No merece la pena morir por la venganza.' WHERE `ID`=57500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 돈체이서 은거처에서 만납시다. 나는 형제의 주검을 거둬야 하고, 그 뒤에는 이 사마귀 놈들의 공격에 맞서야만 하오.', `MaleText_loc4`='$p，到逐晨者营地来找我吧。我必须照顾好我兄弟的遗体，然后我们再来解决除螳螂妖的威胁。', `MaleText_loc5`='$p，到曦逐者居所去和我碰頭。我必須照料兄弟的遺族，接著還得處理螳螂人的威脅。', `MaleText_loc7`='$p, reúnete conmigo en el Retiro del Cazador del Alba. Debo encargarme de los restos de mi hermano, y luego nos ocuparemos de esta amenaza mántide.' WHERE `ID`=57501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이름이 뭐였죠? $n 님이었나? 대신 좀 해주십시오... 감사합니다, $n 님. 저는 좀 쉬어야겠습니다.', `MaleText_loc4`='帮把手……呃……你叫什么来着？$n？谢谢你，$n。我得歇会儿。', `MaleText_loc5`='交給你了...呃...你叫什麼名字?$n?謝謝了，$n。我需要休息。', `MaleText_loc7`='Sustitúyeme, eh... ¿cómo te llamabas? ¿$n? Gracias, $n. Necesito un descanso.' WHERE `ID`=57502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 필요하시면 저희 집으로 오십시오.', `MaleText_loc4`='如果你有什么不清楚的，可以来我家找我。', `MaleText_loc5`='如果你需要我，可以到我的屋子裡來找我。', `MaleText_loc7`='Podrás encontrarme en mi casa si me necesitas.' WHERE `ID`=57503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 살고 싸우고 죽는다오. 그럴 이유를 찾는 게 어려울 뿐.', `MaleText_loc4`='我们为战而生、至死方休。而要诠释生存，战斗和死亡的意义，却并非易事。', `MaleText_loc5`='我們活下來，戰鬥，然後死去。詭異的地方在於我們必須找個理由來做這些事。', `MaleText_loc7`='Vivimos, luchamos, morimos. Lo difícil es encontrar una razón para hacer cada una de esas cosas.' WHERE `ID`=57504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 고결한 종족이오. 그러니 나는 기꺼이 그들과 함께 싸울 것이오.', `MaleText_loc4`='熊猫人是一个高贵的种族，我愿意与之并肩作战。', `MaleText_loc5`='熊貓人是高貴的種族，我很榮幸能與其中一員並肩作戰。', `MaleText_loc7`='Los pandaren son una raza noble y estoy dispuesto a luchar a su lado.' WHERE `ID`=57505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쌍둥이의 이름은 지었습니까?', `MaleText_loc4`='你给这对双胞胎起名字了吗？', `MaleText_loc5`='你幫雙胞胎取名字了嗎?', `MaleText_loc7`='¿Les has puesto nombres a los mellizos?', `FemaleText_loc1`='쌍둥이의 이름은 지었나요?', `FemaleText_loc4`='你给这对双胞胎起名字了吗？', `FemaleText_loc5`='你幫雙胞胎取名字了嗎?', `FemaleText_loc7`='¿Les has puesto nombres a los mellizos?' WHERE `ID`=57506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이오! 내가 안고 있는 아이는 옛 친구의 이름을 따라 "코르"라 이름 지었소.$b$b또 업고 있는 이 장군은 목숨을 구해준 영웅의 이름을 따라 "$p"|1이라고;라고; 이름 지었다오.', `MaleText_loc4`='当然啦！我胸前的这个小的叫“科尔”，这是为了纪念我的老友。$b$b而我背上这个小勇士叫“$p”，这是为了纪念他的救命恩人。', `MaleText_loc5`='沒錯!我懷裡抱著的這個名叫「柯爾」，以紀念我的好友柯爾·血牙。$b$b而我背著的那位小勇士則叫「$p」，以酬謝他的救命恩人。', `MaleText_loc7`='¡En efecto! El joven en mi pecho se llama "Kor", por mi viejo amigo.$b$bY este joven campeón a mi espalda se llama "$p", por su $gsalvador:salvadora;.' WHERE `ID`=57507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 그런데 제 이름은 여자 이름입니다만.', `MaleText_loc4`='谢谢，但我的名字是女孩用的。', `MaleText_loc5`='謝謝，但我有個女孩兒的名字。', `MaleText_loc7`='Gracias, pero tengo un nombre de chica.', `FemaleText_loc1`='고마워요. 그런데 제 이름은 여자 이름인데요.', `FemaleText_loc4`='谢谢，但我的名字是女孩用的。', `FemaleText_loc5`='謝謝，但我有個女孩兒的名字。', `FemaleText_loc7`='Gracias, pero tengo un nombre de chica.' WHERE `ID`=57508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 그래도... 이 녀석이 나중에 엄청난 위업을 이룰 테니, 그 이름은 강인한 수컷 타우렌의 이름으로 역사에 남을 것이오.', `MaleText_loc4`='没事，他一定能以英勇的事迹留名青史，让人们记住这是一个勇士的名字。', `MaleText_loc5`='那麼或許他將會有一番偉大的作為，讓歷史記得這是個勇者的名字。', `MaleText_loc7`='Bueno, a lo mejor sus hazañas serán tan grandes que la historia lo recordará como el nombre de un toro.' WHERE `ID`=57509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사일은 보기보다 훨씬 어렵습니다.', `MaleText_loc4`='农活是看着简单做着难。', `MaleText_loc5`='耕田比看起來要困難得多了。', `MaleText_loc7`='Llevar una granja es mucho más difícil de lo que parece.' WHERE `ID`=57510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 윤! 이리 와 보게!', `MaleText_loc4`='嘿，老愚！出来一下！', `MaleText_loc5`='嘿，尹!到這裡來!', `MaleText_loc7`='¡Oye, Yoon! ¡Ven aquí!' WHERE `ID`=57511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까, 자네가 농장을 완전히 이어받은 거군, 그렇지?', `MaleText_loc4`='这么说，你永久性地接管了农场，嗯？', `MaleText_loc5`='嗯，你已經完全接管整個農莊了嗎?', `MaleText_loc7`='Entonces te vas a encargar del rancho de forma permanente, ¿no?' WHERE `ID`=57512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시 친구, 한마디만 하겠네. 자네가 예전에 여기서 일하던 늙은 윤의 자식일지는 모르겠지만, 그래도 자넨 여전히 도시 출신 아닌가.', `MaleText_loc4`='我们开门见山吧。你也许是老老愚的后代，可你终究是个城里人。', `MaleText_loc5`='先搞清楚一件事。你也許是老尹的孩子，但你仍然是一個城市佬。', `MaleText_loc7`='Vamos a dejar una cosa clara. Es posible que seas el cachorro del viejo Yoon, pero sigues siendo un zarpa urbanita.' WHERE `ID`=57513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사짓는 법 같은 건 알기라도 하나? 내가 자네를 도와줄 테니 이러는 건 어떻겠나? 여기 이 땅뙈기를 내게 팔아넘기고 도시로 돌아가게.', `MaleText_loc4`='你甚至连如何经营一家农场都不懂吧？这样吧，我来帮你省去这个麻烦。你把这块地卖给我，然后从哪儿来的回哪儿去。', `MaleText_loc5`='你到底知不知道該如何經營一個農場?你知道嗎，我能幫你省點麻煩。把這片土地賣給我，然後你從哪裡來就回哪裡去吧。', `MaleText_loc7`='¿Acaso sabes cómo atender una granja? Mira, te ahorraré el problema. Véndeme esta parcela y vuelve por donde has venido.' WHERE `ID`=57514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음대로 해보시게나, 도시 친구. 하지만 틀림없이 일주일도 못 갈 걸세. 이 난장판 좀 보라고!', `MaleText_loc4`='随你的便吧，城里人。但我赌你撑不过一个星期。我是说，瞧瞧这烂摊子！', `MaleText_loc5`='隨你便吧，城市佬，不過我敢打賭你一定撐不過一個星期。我的意思是，看看這個爛地方!', `MaleText_loc7`='Como tú quieras, urbanita, pero te apuesto a que no aguantas ni una semana. ¡Mira esta ruina!' WHERE `ID`=57515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 자네 땅을 내게 팔면 내가 잘 해결해 주겠네.', `MaleText_loc4`='别瞎折腾了。把地卖给我，我来帮你省去这个麻烦。', `MaleText_loc5`='哼，把土地賣給我，我幫你省點麻煩。', `MaleText_loc7`='Bah, véndeme tus tierras y te ahorraré el problema.' WHERE `ID`=57516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일주일도 못 갈 게 뻔해.', `MaleText_loc4`='我打赌你连一个星期都撑不到。', `MaleText_loc5`='我敢打賭你撐不過一個星期。', `MaleText_loc7`='Te apuesto a que no aguantas ni una semana.' WHERE `ID`=57517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐들, 저 친구 농사인가 뭔가 좀 하게 놓아두게나. 하하하!', `MaleText_loc4`='走吧大伙儿，让他继续干他的“农活”吧，哈哈哈！', `MaleText_loc5`='來吧，孩子們，我們就讓他繼續去「經營」他的農場吧。呵呵呵!', `MaleText_loc7`='Venga, chicos. Dejémoslo con sus "labranzas". ¡Jo, jo, jo!' WHERE `ID`=57518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아이고, 하오한 씨! 이렇게 귀한 손님이 오실 줄은 몰랐습니다.', `MaleText_loc4`='哦，我的天呐！泥爪先生！真想不到会有您这样的贵客临门。', `MaleText_loc5`='喔，喔老天啊!泥爪先生!我沒預期會有這麼重要的人來訪。', `MaleText_loc7`='¡Madre mía! ¡Sr. Zarpa Fangosa! No esperaba una visita tan importante.' WHERE `ID`=57519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가? 농사꾼 연합에 들어온다고? 하하! 그렇다면 우리 투표 위원회에 있는 다섯 명의 위원에게 자네의 농사 실력을 증명해야만 하네. 그냥은 절대로 자네에게 표를 주진 않을 걸세!', `MaleText_loc4`='你？想加入阡陌客？哈！你得让那五名有表决权的委员会成员认同你的耕作能力。他们永远都不会对你投赞成票！', `MaleText_loc5`='你?加入耕者?哈!你得向我們議會的所有五名成員證明你的農耕技巧。他們是絕對不會贊同你的!', `MaleText_loc7`='¿Tú? ¿En los Labradores? ¡Ja! Tendrías que demostrar tus dotes granjeras a los cinco miembros del consejo. ¡Y nunca te votaremos!' WHERE `ID`=57520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유명한 하오한 머드클로 씨 맞으시죠? 농사꾼 연합의 대표직을 맡고 계시지 않습니까? 농사꾼 연합 소속이신 분들은 모두 판다리아에서 가장 훌륭한 농부들이시고요!', `MaleText_loc4`='你是郝瀚·泥爪，对吧？阡陌客的首领？你们是全潘达利亚大师级的农夫！', `MaleText_loc5`='你就是好漢·泥爪，對吧?耕者工會的領導人?你們是全潘達利亞最優秀的農夫!', `MaleText_loc7`='Eres Haohan Zarpa Fangosa, ¿no? ¿El líder del gremio de los Labradores? ¡Son los mejores granjeros de toda Pandaria!' WHERE `ID`=57521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 대표님! 제 할아버님께서 이 밭을 남겨주셨습니다. 여기로 이사온지는 얼마 안 됐습니다. 만나서 반갑습니다!', `MaleText_loc4`='是的，先生！这个农场是我祖父留给我的，我刚搬来不久。很高兴认识你，邻居！', `MaleText_loc5`='是的長官!我的祖父把這片農地留給我。我前幾天才搬來。很高興認識你，好鄰居!', `MaleText_loc7`='¡Sí, señor! Mi abuelo me dejó esta granja. Me trasladé aquí el otro día. ¡Es un placer conocerte, vecino!' WHERE `ID`=57522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이곳 농장 일을 배우고 나면, 저는 여기 계신 다른 분들처럼 농사꾼 연합의 일원이 되고 싶습니다!', `MaleText_loc4`='另外，等我掌握窍门之后，我也想跟你们一样，做个阡陌客！', `MaleText_loc5`='此外，在我抓到訣竅後，我想要成為和你們一樣的耕者!', `MaleText_loc7`='Cuando le haya tomado el control a todo esto, ¡quiero formar parte de los Labradores, como ustedes!' WHERE `ID`=57523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 하지만 이곳은 제 가족 농장입니다. 그냥 그렇게 팔아버릴 수는 없습니다.', `MaleText_loc4`='但……但这是我们家传的农场，我不能卖。', `MaleText_loc5`='但、但這是我的家族農場。我不能賣掉它。', `MaleText_loc7`='Pe... pero es la granja de mi familia. No puedo venderla sin más.' WHERE `ID`=57524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할아버지께서는 절대라는 건 절대 없다고 하셨습니다. 저는 온 힘을 다해볼 겁니다.', `MaleText_loc4`='我爷爷经常告诫我，不要把话说得太满。我会尽力而为。', `MaleText_loc5`='絕不說絕不，我爺爺總是這麼說。我要盡全力去試試看。', `MaleText_loc7`='Nunca digas nunca jamás, como decía mi abuelo. Voy a esforzarme al máximo.' WHERE `ID`=57525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 밖에 누가 온 것 같은데?', `MaleText_loc4`='嘿，外面有人吗？', `MaleText_loc5`='嘿，我聽到有人在外面?', `MaleText_loc7`='Oye, he oído a alguien fuera.' WHERE `ID`=57526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닷새 간다에 걸지.', `MaleText_loc4`='我给他五天时间。', `MaleText_loc5`='我給他五天時間。', `MaleText_loc7`='Le doy cinco días.' WHERE `ID`=57527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닷새는 무슨... 이틀!', `MaleText_loc4`='两天，最多！', `MaleText_loc5`='最多兩天!', `MaleText_loc7`='¡Dos días como mucho!' WHERE `ID`=57528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤, 제가 도와드리겠습니다.', `MaleText_loc4`='我会帮你的，农夫老愚。', `MaleText_loc5`='農夫尹，我會幫你。', `MaleText_loc7`='Te ayudaré, granjero Yoon.', `FemaleText_loc1`='윤, 제가 도와드릴게요.', `FemaleText_loc4`='我会帮你的，农夫老愚。', `FemaleText_loc5`='農夫尹，我會幫你。', `FemaleText_loc7`='Te ayudaré, granjero Yoon.' WHERE `ID`=57529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮습니다. 그럼 전 이만 가보겠습니다.', `MaleText_loc4`='不用了，谢谢。我自己能行。', `MaleText_loc5`='不了，謝謝，我會走我自己的路。', `MaleText_loc7`='No, gracias. Me voy.', `FemaleText_loc1`='괜찮아요. 그럼 전 이만 가볼게요.', `FemaleText_loc4`='不用了，谢谢。我自己能行。', `FemaleText_loc5`='不了，謝謝，我會走我自己的路。', `FemaleText_loc7`='No, gracias. Me voy.' WHERE `ID`=57530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네! 힘을 모아서 농사꾼 연합에 가입할 때까지 함께 일할 겁니다!', `MaleText_loc4`='好！我们一起努力，一定能加入阡陌客！', `MaleText_loc5`='沒錯!我們一起努力，直到我們可以加入耕者工會的那一天!', `MaleText_loc7`='¡Sí! ¡Juntos trabajaremos hasta entrar en el gremio de labradores!' WHERE `ID`=57531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우, 이런. 이런 식으로 해서는 농사꾼 연합에 절대 가입할 수 없을 겁니다. 뭐, 마음이 바뀌면 언제든 제게 알려주십시오.', `MaleText_loc4`='噢，见鬼。照这个速度，我永远也进不了阡陌客。好吧，如果你改主意了，通知我一声。', `MaleText_loc5`='咳呸。照這個情況下去，我一輩子也別想加入耕者工會。嗯，如果你改變心意，記得告訴我。', `MaleText_loc7`='Oh, vaya. A este ritmo nunca entraré en el gremio de labradores. Bueno, avísame si cambias de opinión.' WHERE `ID`=57532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 구슬프게 흐느낍니다.', `MaleText_loc4`='%s发出了一声凄惨的哀号。', `MaleText_loc5`='%s發出了淒慘的哀號聲。', `MaleText_loc7`='%s emite un gemido lastimoso.' WHERE `ID`=57533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 이걸 스튜에 넣어야 할 것 같습니다. 어쨌든 고기가 부족한 상황이니까요.', `MaleText_loc4`='我想我会把它放进炖汤里，正好我们缺肉。', `MaleText_loc5`='我還是直接把這個加到燉菜裡吧，反正我們很缺肉。', `MaleText_loc7`='Supongo que lo añadiré al estofado. De todos modos, andamos un poco escasos de carne.' WHERE `ID`=57535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊음의 웅덩이는 오래전 우리 조부께서 들려주신 옛이야기였다네. 이제 이 늙은이가 그걸 찾을 걸세!', `MaleText_loc4`='青春之池是我祖祖辈辈流传下来的一个古老传说。现在，我这个老朽决心要找到它们！', `MaleText_loc5`='青春之池是很久很久以前，我祖父輩告訴我的古老傳說。現在我這個老頭子竟企圖要找到青春之池!', `MaleText_loc7`='Las Pozas de la Juventud eran una fábula antigua que me contaban mis abuelos hace mucho tiempo... ¡y ahora este anciano trata de encontrarlas!' WHERE `ID`=57537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 나는 오로지 지식을 추구하기 위해 살았다네.$b$b지금은, 눈 뜨고 있는 동안 우리 종족이 잃어버린 불멸성을 되찾을 방법을 백방으로 찾고 있지.', `MaleText_loc4`='曾经，我只为追求知识而生。$b$b现在，我穷尽每一分每一秒，只为让我的族人重新获得永生。', `MaleText_loc5`='我通常只為了追尋知識而活。$b$b現在我用所有的時間來尋找讓我們的人民再度永生不死的方式。', `MaleText_loc7`='Solía vivir en busca del conocimiento.$b$bAhora dedico todo mi tiempo a buscar una manera para que nuestra gente recupere nuestra inmortalidad perdida.' WHERE `ID`=57538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 딸 리알리아는 내가 사원 청소나 하면서 남은 생을 보내기를 바라는 모양이네.$b$b흥! 그 차원문을 통해 이 기묘하고 아름다운 땅으로 발을 내딛던 순간, 그 순간만큼 살아 있다는 느낌을 받은 적이 없는데 말일세.', `MaleText_loc4`='我女儿丽娅拉本想让我终日打扫寺庙，以过此余生。$b$b呸！当我决定跨过传送门来到这片神奇而又美丽的土地时，我感受到前所未有的活力。', `MaleText_loc5`='若是以前，我女兒賴奧莉亞會要我把今天剩下的時間都拿來清理寺廟。$b$b嗟!當我選擇穿越傳送門來到這塊陌生而美麗的大地時，我從沒覺得如此生龍活虎過。', `MaleText_loc7`='Si por mi hija Lyalia fuera, me pasaría el resto de mis días limpiando un templo.$b$b¡Bah! Nunca me he sentido tan vivo como cuando decidí traspasar el portal a este extraña y hermosa tierra.' WHERE `ID`=57539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $r! 딱 좋을 때에 왔군.$b$b이 땅에서 얼라이언스의 일원을 만날 줄이야.', `MaleText_loc4`='你好，$r！你来的正是时候。$b$b我们没想到在这里还能遇见联盟的人。', `MaleText_loc5`='你好啊，$r!今天真是個好日子。$b$b我們沒預料到還能在這塊土地上找到聯盟的人。', `MaleText_loc7`='¡Saludos, $r! Justo a tiempo.$b$bNo esperábamos encontrar a nadie de la Alianza en esta tierra.' WHERE `ID`=57540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀감옥 가장자리에서 족쇄를 찾아 보게. 세 개가 있을 걸세.', `MaleText_loc4`='在地牢边上找一些镣铐，应该有三个。', `MaleText_loc5`='在地牢周圍尋找鐐銬，應該要有三副才對。', `MaleText_loc7`='Busca los grilletes en los extremos del calabozo. Debería haber tres.' WHERE `ID`=57541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼 연합 일로 언덕골 시장에 갑니다. 그곳에서 저를 찾아주십시오. 아니면 뭉뭉이 어떤 일이라도 도와줄 겁니다.

- 하오한 머드클로', `MaleText_loc4`='我去市集了。若是关于阡陌客的事情，请来半山市集找我。若是其他事情，可以找蒙蒙帮你解决。

——郝瀚·泥爪', `MaleText_loc5`='我到市集去了。若是為了耕者工會的公事，請到半丘市集找我。其他時候，芒芒可以滿足所有的需要

-好漢·泥爪', `MaleText_loc7`='He ido al mercado. Para cuestiones oficiales del gremio de labradores, búscame en el Mercado del Alcor. Para cualquier otra cuestión, Mung-Mung te atenderá en lo que necesites.

- Haohan Zarpa Fangosa' WHERE `ID`=57542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지께서 안 보시는 동안 잠깐 나갔다 올게요. 언덕골 시장에서 저를 찾아주세요!

- 티나 머드클로', `FemaleText_loc4`='我趁我爸没注意的时候溜出来了，去半山市集找我！

——迪娜·泥爪', `FemaleText_loc5`='趁我爸沒注意的時候偷溜出去。到半丘市集找我!

-蒂娜·泥爪', `FemaleText_loc7`='Me he escapado mientras mi padre no miraba. Puedes encontrarme en el Mercado del Alcor.

- Tina Zarpa Fangosa' WHERE `ID`=57543;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕골 시장에 물고기 가져다 놓으러 가요. 거기서 만나요!

- 피시', `FemaleText_loc4`='把鱼带到市集，半山见！

——玉儿', `FemaleText_loc5`='把魚帶到市集來。到半丘見囉!

-魚', `FemaleText_loc7`='He llevado el pescado al mercado. ¡Nos vemos en El Alcor!

- Pez' WHERE `ID`=57544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 쪽지를 찾았다면, 제가 죽었거나 아니면 언덕골 시장에 있거나 둘 중 하나일 거예요.$B$B자리를 잠깐 비우고 따끈한 에일 한 잔 마시러 갔을 수도 있고요. 그래도 혹시 모르니 죽지 않았나 확인은 해주세요.$B$B만일 제가 목숨을 잃은 거라면, 애틋한 이 마음과 유품을 쥬의 감시초소에 있는 가족들에게 전해주세요.

- 쇼', `FemaleText_loc4`='如果你发现这张字条，那我不是死了，就是在半山市集。$B$B但愿我能暂时放下工作，到镇上喝一杯热乎乎的麦芽酒。或许你该去确认一下，以防万一。$B$B如果我真的没能完成任务，请把我的爱意和私人物品转交给我远在朱家堡的家人。

——阿烁', `FemaleText_loc5`='如果你找到這張紙條，那麼我人不是死了就是在半丘市集。$B$B希望我只是暫離崗位去鎮上喝杯熱麥芽啤酒。也許你應該去確認一下，以防萬一。$B$B如果我真的執行任務失敗了，請將我的隨身物品與我的愛送去祝家守望站，交給我的家人。

-阿秀', `FemaleText_loc7`='Si encuentras esta nota, significa que estoy muerta o en el Mercado del Alcor.$B$BEspero que sea porque he abandonado temporalmente mi puesto y he ido a disfrutar de una jarra caliente de cerveza a la ciudad. Quizás deberías ir a comprobarlo, por si acaso.$B$BSi resulta que he fracasado en mi misión, te ruego que le transmitas mi cariño y mis efectos personales a mi familia en la Atalaya de Zhu.

- Sho' WHERE `ID`=57545;
