UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전차가 폭발하기 전에 떨어지십시오!', `MaleText_loc4`='快离开损毁的坦克，它要爆炸了！', `MaleText_loc5`='在被破壞的坦克爆炸前逃出來!', `MaleText_loc7`='¡Aléjate del tanque saboteado antes de que explote!' WHERE `ID`=57568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국에 넣어 먹을 거라면 방금 수확한 채소 만큼 좋은 게 없습니다.', `MaleText_loc4`='没什么能比这新鲜蔬菜更适合你的汤了。', `MaleText_loc5`='沒有什麼比剛採收的新鮮蔬菜更適合加進你的湯裡了。', `MaleText_loc7`='Nada como una cosecha fresca de verduras para tu sopa.' WHERE `ID`=57572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리사님! 궁금한 게 있습니다... 우리는 친구입니까?', `MaleText_loc4`='嘿，大厨！我想问你下……我们是朋友吧？', `MaleText_loc5`='嘿，老大!我必須要問你一下...我們算是朋友嗎?', `MaleText_loc7`='¡Oye, chef! Tengo que preguntarte algo... ¿somos amigos?', `FemaleText_loc1`='요리사님! 궁금한 게 있어요... 우리는 친구인가요?', `FemaleText_loc4`='嘿，大厨！我想问你下……我们是朋友吧？', `FemaleText_loc5`='嘿，老大!我必須要問你一下...我們算是朋友嗎?', `FemaleText_loc7`='¡Oye, chef! Tengo que preguntarte algo... ¿somos $gamigos:amigas;?' WHERE `ID`=57573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론입니다, $n 님! 우리는 좋은 친구죠.$B$B호젠 산에서 저를 구해주셨던 일 기억 못 하십니까? 그러고는 술을 잔뜩 퍼마시고 바지를 잃어버린 것도 기억 안 나는 거지요?', `FemaleText_loc4`='当然了，$n！我们是名副其实的好友。$B$B难道你忘了你从山地猢狲手里把我救出来那事了吗？后来我们还为此痛饮一番，醉得连裤子都找不着了。', `FemaleText_loc5`='當然啦，$n!我們是很好的朋友。$B$B你不記得你從山上猴人的手中救了我一命嗎?還有之後我們喝的大醉，連褲子都弄丟了?', `FemaleText_loc7`='¡Por supuesto, $n! Somos muy $gbuenos amigos:buenas amigas;.$B$B¿No te acuerdas de aquella vez que me salvaste de aquel hozen de la montaña? ¿Y que luego nos emborrachamos y perdimos los pantalones?' WHERE `ID`=57575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 올 때가 됐다 싶었죠. 날 풀어줄 겁니까, 아니면... 다른 계획이라도?', `MaleText_loc4`='啊，是时候了。$B$B你是要放了我，还是有……其它的主意？', `MaleText_loc5`='啊，該是時候了。你會放了我，還是...你另有打算?', `MaleText_loc7`='Ah, ya era hora. ¿Van a liberarme, o tienen... otra cosa en mente?' WHERE `ID`=57576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF0008E8도적:|r <족쇄의 자물쇠를 땁니다.>', `MaleText_loc4`='|cFF0008E8Rogue:|r <捡起锁铐。>', `MaleText_loc5`='|cFF0008E8盜賊:|r <解開鐐銬的鎖。>', `MaleText_loc7`='|cFF0008E8Rogue:|r <Coge los candados de los grilletes.>', `FemaleText_loc1`='|cFF0008E8도적:|r <족쇄의 자물쇠를 땁니다.>', `FemaleText_loc4`='|cFF0008E8Rogue:|r <捡起锁铐。>', `FemaleText_loc5`='|cFF0008E8盜賊:|r <解開鐐銬的鎖。>', `FemaleText_loc7`='|cFF0008E8Rogue:|r <Coge los candados de los grilletes.>' WHERE `ID`=57577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<족쇄를 풉니다.>', `MaleText_loc4`='<打开锁铐。>', `MaleText_loc5`='<解開鐐銬的鎖。>', `MaleText_loc7`='<Abre los grilletes.>', `FemaleText_loc1`='<족쇄를 풉니다.>', `FemaleText_loc4`='<打开锁铐。>', `FemaleText_loc5`='<解開鐐銬的鎖。>', `FemaleText_loc7`='<Abre los grilletes.>' WHERE `ID`=57578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족쇄 열쇠가 없습니다.', `MaleText_loc4`='我没有用来打开锁铐的钥匙。', `MaleText_loc5`='我沒有鐐銬的鑰匙。', `MaleText_loc7`='No tengo la llave de los grilletes.', `FemaleText_loc1`='족쇄 열쇠가 없어요.', `FemaleText_loc4`='我没有用来打开锁铐的钥匙。', `FemaleText_loc5`='我沒有鐐銬的鑰匙。', `FemaleText_loc7`='No tengo la llave de los grilletes.' WHERE `ID`=57579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<족쇄를 풀지 않고 둡니다.>', `MaleText_loc4`='<让他继续被锁着。>', `MaleText_loc5`='<任由他被鐐銬禁錮。>', `MaleText_loc7`='<Déjalo esposado.>', `FemaleText_loc1`='<족쇄를 풀지 않고 둡니다.>', `FemaleText_loc4`='<让他继续被锁着。>', `FemaleText_loc5`='<任由他被鐐銬禁錮。>', `FemaleText_loc7`='<Déjalo esposado.>' WHERE `ID`=57580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위층에 있는 경비대장 헤드릭 이븐케인에게 열쇠가 있을 겁니다. 서두르십시오. 아시다시피 시간이 없습니다!', `MaleText_loc4`='楼上的卫兵队长赫德里克·伊文凯恩应该有钥匙。请你抓紧时间，我们可不能整晚都待在这里！', `MaleText_loc5`='樓上的衛兵隊長海瑞克·伊文凱恩應該有鑰匙。但請動作快點，你也知道，我們時間不多!', `MaleText_loc7`='El capitán de la guardia, Hedric Cañalisa, está arriba y tiene una llave. Dense prisa, ¿quieren? ¡No tenemos toda la noche!' WHERE `ID`=57581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물은 꽤 괜찮아 보이는군요.', `MaleText_loc4`='这里的水看起来很不错。', `MaleText_loc5`='這裡的水看起來非常棒。', `MaleText_loc7`='El agua se ve muy bien por aquí.' WHERE `ID`=57582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물은 뭔가 좀 이상한데...', `MaleText_loc4`='这里的水倒是有点意思……', `MaleText_loc5`='這裡的水有點古怪...', `MaleText_loc7`='Hay algo extraño en esta agua de aquí...' WHERE `ID`=57583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 이 웅덩이는 참 작고 예쁘군요!', `MaleText_loc4`='好家伙！看看这个可爱的小池子！', `MaleText_loc5`='好讚啊!看看這個漂亮的小池子!', `MaleText_loc7`='¡Mira nada más! ¡Qué preciosa pocita!' WHERE `ID`=57584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 볼까요...', `MaleText_loc4`='让我们瞧瞧……', `MaleText_loc5`='我們來看看...', `MaleText_loc7`='Veamos por aquí...' WHERE `ID`=57585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물은 약간 뭐랄까... 너무... 뭐였더라? 아, 깨끗하군요.', `MaleText_loc4`='这水似乎有点太……怎么说的来着？哦，太干净了。', `MaleText_loc5`='這水看起來有點太...該怎麼說?喔，太乾淨了。', `MaleText_loc7`='Esta agua parece demasiado... ¿cuál es la palabra? Ah, sí... limpia.' WHERE `ID`=57586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 제가 찾던 물입니다! 이 물에는 거미나 게가 안 살죠.', `MaleText_loc4`='我想说的就是这个！水里既没蜘蛛也没螃蟹。', `MaleText_loc5`='我就是這個意思!水裡一隻蜘蛛或螃蟹都沒有。', `MaleText_loc7`='¡Ahora sí que sí! No hay arañas ni cangrejos en esta agua.' WHERE `ID`=57587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 마지막일 겁니다.', `MaleText_loc4`='这应该是最后一个了。', `MaleText_loc5`='這樣應該就結束了。', `MaleText_loc7`='Yo creo que ya no hay más.' WHERE `ID`=57588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야!', `MaleText_loc4`='哎哟！', `MaleText_loc5`='好痛!', `MaleText_loc7`='¡Ay!' WHERE `ID`=57589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 젠장!', `MaleText_loc4`='该死！', `MaleText_loc5`='該死!', `MaleText_loc7`='¡Ay, dios!' WHERE `ID`=57590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런!', `MaleText_loc4`='见鬼！', `MaleText_loc5`='唉唷!', `MaleText_loc7`='¡Maldición!' WHERE `ID`=57591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가미에 물이 약간 고여 있나 봅니다. 좀 퍼내야겠군요...', `MaleText_loc4`='看起来他的鳃里有点儿水，我得弄一些出来……', `MaleText_loc5`='牠的鰓裡好像有一些這種水積在裡頭，我要弄點出來...', `MaleText_loc7`='Parece que tiene un poco de esa agua atascada en las branquias. Voy a sacársela...' WHERE `ID`=57592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미 주둥이에 있는 물을 조금만 뽑을 겁니다. 조금인데 뭐 괜찮겠죠. 안 그렇습니까?', `MaleText_loc4`='我得从这蜘蛛的嘴里把水弄出来。一点小毒素应该没什么大碍的，对吧？', `MaleText_loc5`='我要從牠的小蜘蛛嘴裡弄點這種水出來。一點點毒液死不了人，對吧?', `MaleText_loc7`='Voy a sacarle un poco de agua de su boquita de araña. Un poco de veneno no hace daño a nadie, ¿verdad? Claro que no.' WHERE `ID`=57593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이 친구는 물을 아주 많이 마셨군요. 이것도 좀 가져가야겠습니다.', `MaleText_loc4`='天呐，这家伙吞了好多水。我得弄点出来。', `MaleText_loc5`='老天，這傢伙喝了真多水啊。我應該收集一些才是。', `MaleText_loc7`='Ahí va, este tragó un montón de agua. Tengo que sacarle un poco.' WHERE `ID`=57594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첸 님도 악어물로 맥주는 안 만들어봤을 겁니다.', `MaleText_loc4`='陈酿的酒里肯定掺着鳄鱼肚子里的水。', `MaleText_loc5`='我敢打賭，老陳一定沒釀過鱷腹水啤酒。', `MaleText_loc7`='Seguro que Chen nunca hizo cerveza con agua como esta.' WHERE `ID`=57595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버에서 좋아하지 않을 겁니다. 명심하시지요. 우리는 가볍게 볼 조직이 아닙니다.', `MaleText_loc4`='夺日者不会高兴的。记住我的话，谁都不应该轻视夺日者。', `MaleText_loc5`='奪日者會很不滿的。記住我的話:不要小看我們的組織。', `MaleText_loc7`='A los Atracasol no les va a gustar nada. Escúchenme bien: no somos una organización que convenga tomar a la ligera.' WHERE `ID`=57596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 이제 이 우울한 섬에서 나가 볼까요?', `MaleText_loc4`='谢谢你！我们现在能离开这该死的小岛了吗？', `MaleText_loc5`='太感謝了!我們快想辦法離開這可悲的小島吧?', `MaleText_loc7`='¡Muchas gracias! ¿Nos vamos de este miserable islote?' WHERE `ID`=57597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲으로 가봅시다. 거뭇한 물이 휘도는 웅덩이를 찾아보자고요... 그게 좋은 거니까요.', `MaleText_loc4`='我们去金扇泽那找颜色发暗、有漩涡的池水吧……那水一定不错。', `MaleText_loc5`='我們往林地前進吧。尋找黑暗，充滿漩渦的水池...那可是好東西。', `MaleText_loc7`='Vamos hacia ese claro. Buscamos pozas de agua oscura y arremolinada... son las buenas.' WHERE `ID`=57598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그 씨, 갈 준비 됐습니다.', `MaleText_loc4`='我准备好出发了，泥盏。', `MaleText_loc5`='泥杯，我準備好要走了。', `MaleText_loc7`='Estoy listo para partir, Caolín.', `FemaleText_loc1`='머드머그 씨, 갈 준비 됐어요.', `FemaleText_loc4`='我准备好出发了，泥盏。', `FemaleText_loc5`='泥杯，我準備好要走了。', `FemaleText_loc7`='Estoy lista para partir, Caolín.' WHERE `ID`=57599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물을 찾을 준비가 되셨습니까?', `MaleText_loc4`='你准备好去找水了吗？', `MaleText_loc5`='你準備好加入獵水行動了嗎?', `MaleText_loc7`='¿Ya podemos ir por agua?' WHERE `ID`=57600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFE9A2E크릭티크 보호자|r 추가 병력이 나타납니다!', `MaleText_loc4`='|cFFFE9A2E科里克提克捍卫者|r援军出现了！', `MaleText_loc5`='|cFFFE9A2E柯克席克護衛兵|r的援軍出現了!', `MaleText_loc7`='¡Los refuerzos de |cFFFE9A2Eprotectorados Krik''thik|r aparecen!' WHERE `ID`=57601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위쪽에 |cFFFE9A2E크릭티크 휘몰이|r 추가 병력이 나타납니다!', `MaleText_loc4`='|cFFFE9A2E科里克提克吞噬者|r援军在上方出现了！', `MaleText_loc5`='|cFFFE9A2E柯克席克捲風者|r的援軍在上空出現!', `MaleText_loc7`='¡Los refuerzos de |cFFFE9A2Esepultadores Krik''thik|r aparecen arriba!' WHERE `ID`=57602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFE9A2E크리티크 무리 인도자|r 추가 병력이 전투에 합류합니다!', `MaleText_loc4`='|cFFFE9A2E科里克提克虫群使者|r援军加入了战斗！', `MaleText_loc5`='一隻|cFFFE9A2E柯克席克喚蟲者|r的援軍加入了戰局!', `MaleText_loc7`='¡Los refuerzos de |cFFFE9A2Eliberadores de enjambres Krik''thik|r se unen a la batalla!' WHERE `ID`=57603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이리 비네, 이방인이여. 이곳에 넘치는 샤의 사악함을 정화해주게! 우리 이야기들을 쉬게 해줘!', `MaleText_loc4`='拜托了，好心的陌生人。净化这里的恶灵！这些书籍需要安宁！', `MaleText_loc5`='好心的陌生人，我求求你們，淨化這個地方的邪惡!讓我們的故事繼續保存下去!', `MaleText_loc7`='Se los ruego, honorables forasteros. ¡Eliminen su maligna presencia de este lugar! ¡Devuelvan la paz a nuestra historia!' WHERE `ID`=57604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오. 내 생각이 맞다면, 짜오 선시커의 전설이 우리 눈 앞에서 펼쳐지는 것 같군.', `MaleText_loc4`='噢，天哪。如果我没搞错的话，这似乎是在演绎赵·追日者的故事。', `MaleText_loc5`='喔天啊，如果沒弄錯的話，在我們面前重演的應該是兆·尋日者的故事。', `MaleText_loc7`='Vaya, vaya. Si no me equivoco, parece que la historia de Zao Cazador de Soles ha cobrado vida ante nosotros.' WHERE `ID`=57605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 영웅들이여. 난... 어...', `MaleText_loc4`='谢谢，英雄们。我……呃……<被诡异的事情打断>', `MaleText_loc5`='英雄，謝謝你們。我...', `MaleText_loc7`='Gracias, héroes; se…' WHERE `ID`=57606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면, 먼 옛날 하늘에는 밝게 타오르는 해가 다섯 개나 있었다고 하네. 바람이 불 때면 그 강렬한 화염이 불난리를 피웠다고 하지.', `MaleText_loc4`='相传在很久以前，天上明晃晃地挂着五个太阳。一旦刮起风来，灼人的热浪总会让大地燃起燎原野火。', `MaleText_loc5`='據傳說所言，很久以前有五個烈陽高掛天空。每次起風，太陽的高溫便會引發大火。', `MaleText_loc7`='Según la leyenda, hace mucho tiempo había cinco soles que ardían con fuerza en el cielo. Cuando soplaba el viento, el calor provocaba graves incendios.' WHERE `ID`=57607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작물은 시들고, 마을은 불탔으며, 사람들은 불을 피해 쉴 새 없이 떠돌아 다녀야만 했네.', `MaleText_loc4`='庄稼枯萎，村庄燃烧，家家户户背井离乡，不断地躲避着烈焰的侵扰……<爆炸打断了他的话>', `MaleText_loc5`='作物凋零，村落起火，人們四處遊蕩尋找避難所逃避烈焰...', `MaleText_loc7`='Los cultivos se secaban, las aldeas ardían y las familias huían tratando de refugiarse de las llamas...' WHERE `ID`=57608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 충분할 것 같군요.', `MaleText_loc4`='我看我们找得差不多了。', `MaleText_loc5`='我想收集這些就夠了。', `MaleText_loc7`='Creo que tenemos suficiente.' WHERE `ID`=57609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이 도서관을 태우고 있네! 부탁일세, 영웅들이여! 사원이 잿더미가 되기 전에 이곳의 악을 몰아내주게!', `MaleText_loc4`='大火席卷了藏书阁！拜托了，英雄们！在寺庙化为灰烬之前，净化这邪恶之力吧！', `MaleText_loc5`='火勢延燒到藏書了!英雄們，拜託你們!在寺廟付之一炬前淨化這股邪惡!', `MaleText_loc7`='¡El fuego está quemando la biblioteca! ¡Se los ruego, héroes! ¡Purguen este mal antes de que reduzca el templo a cenizas!' WHERE `ID`=57610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짜오는 우리들의 진정한 영웅일세. 그의 이야기가 샤에 의해 이렇게 변질되다니 슬프군. 그래도 그의 전설을 욕보이지 않아 다행이네.', `MaleText_loc4`='赵是真正的民族英雄，看着他的传说被煞魔亵渎真是令人难过。看到正义得到伸张，我很宽慰。', `MaleText_loc5`='兆是真正的勇士，看到他被煞腐化令人相當難過。能維持他的形象真讓人感到欣慰。', `MaleText_loc7`='Zao fue un verdadero campeón de nuestro pueblo. Qué triste que los sha hayan mancillado su historia. Me alegro de que hayan hecho justicia en su memoria.' WHERE `ID`=57611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고맙네, 영웅들이여. 자네들은 이 사원에 평화를 가져다 주었네.', `MaleText_loc4`='衷心感谢，英雄们。是你们让这座神圣的庙宇重获安宁。', `MaleText_loc5`='各位英雄，謝謝你們。你們讓這座神聖的寺廟恢復平靜。', `MaleText_loc7`='Se los agradezco, héroes. Han traído la paz a este templo sagrado.' WHERE `ID`=57612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 실례하겠네! 복원 의식을 시작하기 전에 명상을 해야하니.', `MaleText_loc4`='现在，你们走吧！我得在复原仪式开始前冥想一下。', `MaleText_loc5`='現在，你們退下吧!在進行恢復儀式之前，我需要冥想一下。', `MaleText_loc7`='Ahora, ¡fuera! Debo meditar antes de dar comienzo al ritual de restauración.' WHERE `ID`=57613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아직 끝나지 않았네. 내가 보기엔 아직 야운골의 시험이 남았네. 내가 실마리를 주지...', `MaleText_loc4`='啊，还没完呢。看来，我们正面临野牛人的挑战。让我解释一下……', `MaleText_loc5`='啊，還沒結束。目前看來，我們面臨的是揚古的試煉，我來說明一下...', `MaleText_loc7`='Ah, aún no hemos terminado. Parece ser que nos enfrentamos a la prueba del yaungol. Dejen que los ilustre…' WHERE `ID`=57614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거운 열기에 내 감각이 무뎌진 게 틀림없어... 환영들이여! 사라져라!', `MaleText_loc4`='这滚烫的热气已经让我精神恍惚了…海市蜃楼！你们都是幻觉！', `MaleText_loc5`='一定是這熱度蒙蔽我的知覺...幻覺!全都是幻覺!', `MaleText_loc7`='El calor insoportable debió aturdir mis sentidos... ¡Son espejismos! ¡Espejismos!' WHERE `ID`=57623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면, 짜오는 하늘 높이 화살을 쏘아올리며 격렬하게 싸웠고, 결국 해는 하나만 남게 되었다지.', `MaleText_loc4`='如传说所言，赵勇猛抗争……朝天空射出箭矢，直到只剩下一个太阳。', `MaleText_loc5`='根據故事，兆瘋狂攻擊...一箭箭射向天空，最後只剩一個太陽。', `MaleText_loc7`='La historia cuenta que Zao luchó sin descanso... Disparó una flecha tras otra al cielo, hasta que solo quedó un solo sol.' WHERE `ID`=57624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 꼬집었는데! 잡아요!', `MaleText_loc4`='有东西蛰了我！抓住它，$p！', `MaleText_loc5`='有東西夾了我一下!$p，快抓住它!', `MaleText_loc7`='¡Algo me pellizcó! ¡Agárralo!' WHERE `ID`=57625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미다! 뭉개버려요!', `MaleText_loc4`='水蜘蛛！踩死它，$p！', `MaleText_loc5`='水蜘蛛!$p，打扁他!', `MaleText_loc7`='¡Una araña de agua! ¡Aplástala!' WHERE `ID`=57626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 늙은 악어가 손을 물 뻔했습니다!', `MaleText_loc4`='该死的鳄鱼，差点咬掉我的手！', `MaleText_loc5`='可惡的鱷魚差點咬掉我的手!', `MaleText_loc7`='¡Ese crocolisco casi me arranca la mano!' WHERE `ID`=57627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s의 |cFFFF0000약점|r이 노출되었습니다! 약점에 공격을 집중해 뚫리지 않는 껍질을 파괴하십시오!', `MaleText_loc4`='%s的|cFFFF0000弱点|r暴露了！发起攻击，打破他的密封甲壳！', `MaleText_loc5`='%s的|cFFFF0000弱點|r顯露出來了!攻擊他，打碎他的不破甲殼!', `MaleText_loc7`='¡El |cFFFF0000Punto Débil|r de %s está expuesto! ¡Ataquen para romper su caparazón indestructible!' WHERE `ID`=57628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하... 함정이었어...', `FemaleText_loc4`='这……这是一个陷阱……', `FemaleText_loc5`='這...這是個陷阱...', `FemaleText_loc7`='Es... es una trampa...' WHERE `ID`=57629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<리알리아를 풀어주려고 해 봅니다.>', `MaleText_loc4`='<给丽娅拉松绑。>', `MaleText_loc5`='<試著幫賴奧莉亞鬆綁。>', `MaleText_loc7`='<Intenta desatar a Lyalia.>', `FemaleText_loc1`='<리알리아를 풀어주려고 해 봅니다.>', `FemaleText_loc4`='<给丽娅拉松绑。>', `FemaleText_loc5`='<試著幫賴奧莉亞鬆綁。>', `FemaleText_loc7`='<Intenta desatar a Lyalia.>' WHERE `ID`=57630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리알리아! 정말 미안하구나, 얘야.', `MaleText_loc4`='丽娅拉！非常抱歉，我的孩子。', `MaleText_loc5`='賴奧莉亞!我的孩子，我很抱歉。', `MaleText_loc7`='¡Lyalia! Lo siento mucho, hija mía.' WHERE `ID`=57631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 파수꾼 주둔지에서 만나세. 나는 그곳으로 딸아이의 시신을 옮겨야겠네. 우리에겐 아직 젊음의 물이 있으니까.', `MaleText_loc4`='$p，到哨兵营地来找我，我必须把我女儿的尸体带到那里去。我们还有青春之水。', `MaleText_loc5`='$p，到哨兵營地去跟我碰頭。我必須把我女兒的屍體帶去那裡。我們還有回春水。', `MaleText_loc7`='$p, reúnete conmigo en el Campamento Base de las Centinelas. Debo llevar allí el cuerpo de mi hija. Todavía tenemos el Agua de la Juventud.' WHERE `ID`=57632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 이제 우리는 약간 친해졌으니 제가 하나 알려 드릴게요. 이곳에 있는 주민들은 당신 농장을 멋지게 가꿔줄 수 있답니다. 하지만 그러려면 먼저 그들과 친구가 돼야 해요. 날마다 이웃들이 부탁하는 일을 도와주거나 제게 주셨던 것 같은 선물로 친구가 돼보세요.', `FemaleText_loc4`='既然我们已经是熟人了，$n，那我就给你点提示吧。这附近的村民能帮你装扮农场，但你得先跟他们成为朋友才行。你可以帮他们完成日常任务，或送他们些小礼品——就像你刚才给我的那个，这样就能和他们建立友谊。', `FemaleText_loc5`='如今我們是熟識了，$n，讓我給你個小提示。這裡的人們能幫忙你將農場打理得很好，但你必須先和他們成為朋友。你能藉由幫助他們完成每日的工作，或是送給他們一個像你剛剛送我的禮物來和他們結交。', `FemaleText_loc7`='Ahora que nos conocemos un poco mejor, $n, deja que te dé un consejo. La gente de los alrededores puede ayudarte a mejorar tu granja, pero antes tienen que hacerse amigos. Para ello, ayúdalos con sus tareas diarias o dales regalos como el que me acabas de dar.' WHERE `ID`=57633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후퇴하라!', `MaleText_loc4`='撤退！', `MaleText_loc5`='撤退!', `MaleText_loc7`='¡Retirada!' WHERE `ID`=57634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리알리아! 안 돼애애애애애!', `MaleText_loc4`='丽娅拉！不……！', `MaleText_loc5`='賴奧莉亞!不!!!!', `MaleText_loc7`='¡LYALIA! ¡NOOOOOOOO!' WHERE `ID`=57635;
