UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 안녕하십니까?', `MaleText_loc4`='呃，你好？', `MaleText_loc5`='嗯，哈囉?', `MaleText_loc7`='Eh... ¿hola?', `FemaleText_loc1`='저, 안녕하세요?', `FemaleText_loc4`='呃，你好？', `FemaleText_loc5`='嗯，哈囉?', `FemaleText_loc7`='Eh... ¿hola?' WHERE `ID`=57637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저는 이쪽 길 아래에 사는 농부 윤과 같이 일하고 있습니다. 잘 지내십니까?', `MaleText_loc4`='嗨！我今后会跟农夫老愚一起干活。你好吗？', `MaleText_loc5`='嗨!我在路的那頭跟農夫尹一起工作。你好嗎?', `MaleText_loc7`='¡Hola! Trabajo con el granjero Yoon, que vive al final de este camino. ¿Cómo estás?', `FemaleText_loc1`='안녕하세요! 저는 이쪽 길 아래에 사는 농부 윤과 같이 일하고 있답니다. 잘 지내세요?', `FemaleText_loc4`='嗨！我今后会跟农夫老愚一起干活。你好吗？', `FemaleText_loc5`='嗨!我在路的那頭跟農夫尹一起工作。你好嗎?', `FemaleText_loc7`='¡Hola! Trabajo con el granjero Yoon, que vive al final de este camino. ¿Cómo estás?' WHERE `ID`=57638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안녕하십니까? 이 마을에 새로 왔습니다.', `MaleText_loc4`='嘿，你好吗？我是新来的。', `MaleText_loc5`='嘿，你好嗎?我最近才來到這一帶。', `MaleText_loc7`='¡Hola! ¿Cómo va eso? Soy nuevo por aquí.', `FemaleText_loc1`='아, 안녕하세요? 이 마을에 새로 왔답니다.', `FemaleText_loc4`='嘿，你好吗？我是新来的。', `FemaleText_loc5`='嘿，你好嗎?我最近才來到這一帶。', `FemaleText_loc7`='¡Hola! ¿Cómo va eso? Soy nueva por aquí.' WHERE `ID`=57639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안녕하십니까. 저는 다른 곳에서 왔습니다.', `MaleText_loc4`='你好，我是从外地来的。', `MaleText_loc5`='你好啊。我是從小鎮外頭來的。', `MaleText_loc7`='Ah, hola. Soy de fuera.', `FemaleText_loc1`='아, 안녕하세요. 저는 다른 곳에서 왔어요.', `FemaleText_loc4`='你好，我是从外地来的。', `FemaleText_loc5`='你好啊。我是從小鎮外頭來的。', `FemaleText_loc7`='Ah, hola. Soy de fuera.' WHERE `ID`=57640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 이 근처에 사시는지요?', `MaleText_loc4`='你好，先生。你住在这附近吗？', `MaleText_loc5`='先生您好。您住在這附近嗎?', `MaleText_loc7`='Hola, señor. ¿Vive por aquí?', `FemaleText_loc1`='안녕하십니까. 이 근처에 사세요?', `FemaleText_loc4`='你好，先生。你住在这附近吗？', `FemaleText_loc5`='先生您好。你住在這附近嗎?', `FemaleText_loc7`='Hola, señor. ¿Vive por aquí?' WHERE `ID`=57641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 만나서 반갑습니다.', `MaleText_loc4`='你好，很高兴认识你。', `MaleText_loc5`='哈囉。很高興認識你。', `MaleText_loc7`='Hola. Encantado de conocerte.', `FemaleText_loc1`='안녕하세요. 만나서 반가워요.', `FemaleText_loc4`='你好，很高兴认识你。', `FemaleText_loc5`='哈囉。很高興認識你。', `FemaleText_loc7`='Hola. Encantada de conocerte.' WHERE `ID`=57642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 하오한 씨. 예전에 저를 보셨는지는 모르겠지만, 저는 농부 윤의 농장에서 함께 일하고 있습니다.', `MaleText_loc4`='你好，泥爪先生。不知你是否见过我，我在农夫老愚的农场帮忙。', `MaleText_loc5`='哈囉，泥爪先生。我不知道您之前有沒有看過我，我在農夫尹的農場幫忙。', `MaleText_loc7`='Hola, Sr. Zarpa Fangosa. No sé si me has visto anteriormente, pero estoy ayudando al granjero Yoon en su granja.', `FemaleText_loc1`='안녕하세요, 하오한 씨. 예전에 저를 보셨는지는 모르겠지만, 저는 농부 윤의 농장에서 함께 일하고 있어요.', `FemaleText_loc4`='你好，泥爪先生。不知你是否见过我，我在农夫老愚的农场帮忙。', `FemaleText_loc5`='哈囉，泥爪先生。我不知道您之前有沒有看過我，我在農夫尹的農場幫忙。', `FemaleText_loc7`='Hola, Sr. Zarpa Fangosa. No sé si me has visto anteriormente, pero estoy ayudando al granjero Yoon en su granja.' WHERE `ID`=57643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저쪽에서 보니 당신이 보이더군요. 저는 이 마을에 새로 왔습니다.', `MaleText_loc4`='我在那一眼就认出了你，我是新来的。', `MaleText_loc5`='我從那裡一眼就注意到你了。我剛來到鎮上。', `MaleText_loc7`='No he podido evitar verte desde allí. Soy nuevo en la ciudad.', `FemaleText_loc1`='저쪽에서 보니 당신이 보이더라고요. 저는 이 마을에 새로 왔답니다.', `FemaleText_loc4`='我在那一眼就认出了你，我是新来的。', `FemaleText_loc5`='我從那裡一眼就注意到你了。我剛來到鎮上。', `FemaleText_loc7`='No he podido evitar verte desde allí. Soy nueva en la ciudad.' WHERE `ID`=57644;
