UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 브램블스태프를 만나야 합니다.', `MaleText_loc4`='我得去见康·棘杖。', `MaleText_loc5`='我需要和康恩·藤杖見個面。', `MaleText_loc7`='Tengo que reunirme con Kang Vara Enzarzada.', `FemaleText_loc1`='캉 브램블스태프를 만나야 해요.', `FemaleText_loc4`='我得去见康·棘杖。', `FemaleText_loc5`='我需要和康恩·藤杖見個面。', `FemaleText_loc7`='Tengo que reunirme con Kang Vara Enzarzada.' WHERE `ID`=57650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네. 이름을 들어본 적이 있습니다. 썬더풋 방목지 너머에 있는 팡의 처소를 방문 중이시더군요.$b$b갈 준비되셨습니까?', `MaleText_loc4`='啊，是的，我听说过他。他去了庞家农场，就在雷脚农场那边。$b$b你准备好出发了吗？', `MaleText_loc5`='啊，是的，我聽說過他。他正到雷足牧地裡的潘家莊拜訪。$b$b你準備要動身了嗎?', `MaleText_loc7`='Ah, sí. He oído hablar de él. Está visitando la Finca de Pang en las Granjas Pie Atronador.$b$b¿Estás $glisto:lista; para partir?' WHERE `ID`=57651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네. 이름을 들어본 적이 있습니다. 머드머그네 집을 방문 중이시더군요.$b$b준비가 되면 제가 그곳으로 데려가드리겠습니다.', `MaleText_loc4`='啊，是的，我听说过他。他好像去了泥盏营地，对吗？$b$b等你准备好，我们就可以上路了。', `MaleText_loc5`='啊，是的，我聽說過他。他不是正到泥杯宅邸去拜訪嗎?$b$b等你準備好之後，我可以帶你一起去。', `MaleText_loc7`='Ah, sí. He oído hablar de él. Está visitando el Hogar de Caolín, ¿verdad?$b$bPuedo llevarte cuando lo consideres oportuno.' WHERE `ID`=57652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네. 이름을 들어본 적이 있습니다. 머드머그와 함께 언덕골을 방문 중이시더군요.$b$b준비가 되면 제가 그곳으로 데려가드리겠습니다.', `MaleText_loc4`='啊，是的，我听说过他。他好像和泥盏一起去了半山，对吗？$b$b等你准备好，我们就可以上路了。', `MaleText_loc5`='啊，是的，我聽說過他。他不是正和泥杯一起到半丘去嗎?$b$b等你準備好之後，我可以帶你一起去。', `MaleText_loc7`='Ah, sí. He oído hablar de él. Está visitando El Alcor con Caolín, ¿verdad?$b$bPuedo llevarte hasta allí cuando lo consideres oportuno.' WHERE `ID`=57653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 네. 이름을 들어본 적이 있습니다. 스톰스타우트 양조장에 계시더군요.$b$b준비가 되면 제가 그곳으로 데려가드리겠습니다.', `MaleText_loc4`='啊，是的，我听说过他。他好像去了酒坊，对吗？$b$b等你准备好，我们就可以上路了。', `MaleText_loc5`='啊，是的，我聽說過他。他人不是正在酒坊嗎?$b$b等你準備好之後，我可以帶你一起去。', `MaleText_loc7`='Ah, sí. He oído hablar de él. Está en la cervecería, ¿verdad?$b$bPuedo llevarte hasta allí cuando lo consideres oportuno.' WHERE `ID`=57654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다.', `MaleText_loc4`='出发。', `MaleText_loc5`='我們走吧。', `MaleText_loc7`='Vamos.', `FemaleText_loc1`='가시죠.', `FemaleText_loc4`='出发。', `FemaleText_loc5`='我們走吧。', `FemaleText_loc7`='Vamos.' WHERE `ID`=57655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨이라... 쥬의 감시초소에 머물고 있단 소문들 들었습니다.$b$b제가 그곳으로 데려다 드릴까요?', `MaleText_loc4`='肯肯……我听说他好像在朱家堡。$b$b要我带你过去吗？', `MaleText_loc5`='肯·肯...我聽到傳聞說他待在祝家守望站。$b$b你要我帶你到那裡去嗎?', `MaleText_loc7`='Ken-Ken... Creo haber oído el rumor de que estaba en la Atalaya de Zhu.$b$b¿Quieres que te lleve hasta allí?' WHERE `ID`=57656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨이라... 주학사 근처 어딘가에 머물고 있다는 소문을 들었습니다.$b$b제가 그곳으로 데려다 드릴까요?', `MaleText_loc4`='肯肯……我听说他好像在朱鹤寺附近的某个地方。$b$b要我带你过去吗？', `MaleText_loc5`='肯·肯...我聽到謠傳說他待在紅鶴寺的附近。$b$b你要我帶你到那裡去嗎?', `MaleText_loc7`='Ken-Ken... Creo haber oído el rumor de que estaba en algún lugar cerca del Templo de la Grulla Roja.$b$b¿Quieres que te lleve hasta allí?' WHERE `ID`=57657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공성 "실패"는 물론 속임수였습니다. 설마... 몰랐습니까?', `MaleText_loc4`='这次“失败”的围攻当然只是幌子。你没看出来吗？', `MaleText_loc5`='那「失敗」的攻城行動當然只是虛晃一招。你看不出來嗎?', `MaleText_loc7`='El asedio "fallido" era una maniobra, evidentemente. ¿No se han dado cuenta?' WHERE `ID`=57658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물 좋아하십니까?', `MaleText_loc4`='你喜欢礼物吗？', `MaleText_loc5`='你喜歡禮物嗎?', `MaleText_loc7`='¿Te gustan los regalos?', `FemaleText_loc1`='선물 좋아하시나요?', `FemaleText_loc4`='你喜欢礼物吗？', `FemaleText_loc5`='你喜歡禮物嗎?', `FemaleText_loc7`='¿Te gustan los regalos?' WHERE `ID`=57659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어으으으음... 제가 선물을 좋아하냐고요? 아, 그야 물론이지요! 누가 선물을 안 좋아하겠습니까?', `MaleText_loc4`='呜呜噜噜……我喜不喜欢礼物？那当然了！有谁会不喜欢礼物呢？', `MaleText_loc5`='呣嗯嗯...偶喜番禮物嗎?當籃，當籃啦!隨不喜番禮物咧?', `MaleText_loc7`='Mmm... ¿que shi me gushtan losh regalosh? ¡Puesh claro! ¿Y a quién no le gushtan?' WHERE `ID`=57660;
