UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 착각하신 것 같습니다. 제가 갖고 싶은 게 아무것도 없군요.', `MaleText_loc4`='我想你弄错了，朋友。你没有我想要的东西。', `MaleText_loc5`='我想你搞錯了，朋友。你身上沒有我想要的東西。', `MaleText_loc7`='Creo que te equivocas, $gamigo:amiga;. No tienes nada que yo pueda querer.' WHERE `ID`=57666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 브램블스태프는 크라사랑 밀림에 있습니다. 천둥 틈새에 있는 타우렌들에게 친한 척하고 있지요. 굳이 말씀드리자면, 정말 어리석은 짓이죠.$b$b캉과 함께하시겠습니까?', `MaleText_loc4`='那个棘杖家的小子成天在野外游荡，和雷霆裂口的那些“牛头人”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？', `MaleText_loc5`='那個藤杖男孩在荒野那邊，與雷霆斷崖的「牛頭人」親近。如果你問我的話，我會說他是在自找麻煩。$b$b你想加入他嗎?', `MaleText_loc7`='Ese chico Vara Enzarzada está en los bosques, fraternizando con esos "tauren" en Grieta del Trueno. Está buscando problemas, si quieres mi opinión.$b$b¿Quieres unirte a él?' WHERE `ID`=57667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 브램블스태프는 크라사랑 밀림에 있습니다. 돈체이서 은거처에 있는 타우렌들에게 친한 척하고 있지요. 굳이 말씀드리자면, 정말 어리석은 짓이죠.$b$b캉과 함께하시겠습니까?', `MaleText_loc4`='那个棘杖家的小子成天在野外游荡，和逐晨者营地的那些“牛头人”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？', `MaleText_loc5`='那個藤杖男孩在荒野那邊，與曦逐者居所的「牛頭人」親近。如果你問我的話，我會說他是在自找麻煩。$b$b你想加入他嗎?', `MaleText_loc7`='Ese chico Vara Enzarzada está en los bosques, fraternizando con esos "tauren" en el Retiro del Cazador del Alba. Está buscando problemas, si quieres mi opinión.$b$b¿Quieres unirte a él?' WHERE `ID`=57668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 브램블스태프는 크라사랑 밀림에 있습니다. 나이트 엘프들이 "원정지"라고 부르는 곳에 가서 그들에게 친한 척하고 있지요. 굳이 말씀드리자면, 정말 어리석은 짓이죠.$b$b캉과 함께하시겠습니까?', `MaleText_loc4`='那个棘杖家的小子成天在野外游荡，和他们称之为“先遣营地”的那些“暗夜精灵”打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？', `MaleText_loc5`='那個藤杖男孩在荒野的南方，與人們稱之為「侵略哨站」裡的那些「夜精靈」親近。如果你問我的話，我會說他是在自找麻煩。$b$b你想加入他嗎?', `MaleText_loc7`='Ese chico Vara Enzarzada está en los bosques, fraternizando con esos "elfos de la noche" en el lugar que ellos denominan "la Incursión". Está buscando problemas, si quieres mi opinión.$b$b¿Quieres unirte a él?' WHERE `ID`=57669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 브램블스태프는 크라사랑 밀림에 있습니다. 나이트 엘프 야영지에 가서 그들에게 친한 척하고 있지요. 굳이 말씀드리자면, 정말 어리석은 짓이죠.$b$b캉과 함께하시겠습니까?', `MaleText_loc4`='那个棘杖家的小子成天在野外游荡，和营地里的暗夜精灵打成了一片。依我看，他这是在找麻烦。$b$b你也想加入他？', `MaleText_loc5`='那個藤杖男孩在荒野的南方，跟他們營地的夜精靈親近。如果你問我的話，我會說他是在自找麻煩。$b$b你想加入他嗎?', `MaleText_loc7`='Ese chico Vara Enzarzada está en los bosques, fraternizando con esos elfos de la noche en su campamento base. Está buscando problemas, si quieres mi opinión.$b$b¿Quieres unirte a él?' WHERE `ID`=57670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈속에 맥주를 들이켜니 속이 좋을 리가 없지요. 진위한테 먹을 것 좀 주십시오, 네?', `MaleText_loc4`='胃里空空，光喝可不解饱。给锦鱼人来点吃的吧，好吗？', `MaleText_loc5`='空肚子喝酒對胃不好。給一名錦魚人一點東西吃吧，嗯?', `MaleText_loc7`='No es agradable beber con el estómago vacío. Dale a un jinyu algo de comer, ¿eh?' WHERE `ID`=57671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물 말입니까? 그렇다면 말씀드리지요.$B$B맛좋은 술에 뭐가 필요한지 아십니까? 바로 맛좋은 안주입니다.', `MaleText_loc4`='礼物？我有个主意。$B$B你知道什么和可口的饮料最搭吗？是美味的小吃。', `MaleText_loc5`='禮物?偶有個主意。$B$B你機到有啥麼好東西口以拿來配好酒嗎?一份好粗的點心。', `MaleText_loc7`='¿Regalosh? Aquí tienesh una idea.$B$B¿Sabesh qué pega con una bebida sabrosha? Un aperitivo sabrosho.' WHERE `ID`=57672;
