UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당근 볶음이라고 들어보셨습니까? 제가 가장 좋아하는 음식입니다. 지금 당장 좀 먹었으면 좋겠군요... *딸꾹*', `MaleText_loc4`='你听说过煎炸胡萝卜吗？这是我的最爱。真想现在就吃到嘴……嗝！', `MaleText_loc5`='你聽過炒胡蘿蔔嗎?那是我最愛吃的東西。我真希望現在就能吃到...嗝呃!', `MaleText_loc7`='¿Hash oído hablar de lash zanahoriash shalteadash? Esh mi comida favorita. Me gushtaría comer un poco ahora mishmo... ¡hip!' WHERE `ID`=57684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 아름다운 사과를 먹어본 적이 있습니다. 정말 맛있었지요.$B$B<정신을 놓은 것처럼 멍하니 먼 곳을 쳐다보는 조구>', `MaleText_loc4`='我曾经吃过一只可爱的苹果，太美味了。$B$B<贾古呆呆地眺目远方，似乎走神了。>', `MaleText_loc5`='我曾經吃過一次可愛的蘋果。那真是好吃到不行。$B$B<酒骨兩眼無神地望著遠方，一臉腦袋空空的樣子。>', `MaleText_loc7`='Una vez me comí una manzana preciosha. Eshtaba deliciosha.$B$B<Jogu se queda mirando al infinito, como si hubiera perdido el hilo de lo que estaba pensando.>' WHERE `ID`=57685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오오, 예쁘군요! 정말 좋습니다!', `MaleText_loc4`='哦，太美了！我喜欢！', `MaleText_loc5`='喔喔喔，真漂亮!我喜歡!', `MaleText_loc7`='¡Oooh, qué precioshidad! ¡Me encanta!' WHERE `ID`=57686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 아름다운 사과군요! 오늘 아주 운이 좋은 날인 게 틀림없습니다!', `MaleText_loc4`='哦，一只可爱的苹果！今天真走运！', `MaleText_loc5`='喔，一個可愛的蘋果!今天真素偶的幸運日!', `MaleText_loc7`='¡Oh, una manzana preciosha! ¡Debe de ser mi día de shuerte!' WHERE `ID`=57687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*딸꾹* 자알 생긴 고양이군요. 어제 꿈에 나온 고양이랑 똑같은데...', `MaleText_loc4`='真是只可爱的小猫咪，跟我梦里见过的一样……嗝！', `MaleText_loc5`='這真素隻好貓咪，就像偶上次夢見的一樣...嗝!', `MaleText_loc7`='Esh un gatito preciosho, jushto como en mi último shueño de borrachera... ¡hip!' WHERE `ID`=57688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깃털이군요. 너무나 아름답습니다. 감사합니다... *딸꾹*', `MaleText_loc4`='这根羽毛，太漂亮了。谢谢你……嗝！', `MaleText_loc5`='這素一根羽毛。尊美麗。謝謝你...嗝!', `MaleText_loc7`='Esh una pluma. Qué bonita. Graciash... ¡hip!' WHERE `ID`=57689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이 꽃을 보니 고향 생각이 나는군요.', `MaleText_loc4`='哦……这些花让我想家了。', `MaleText_loc5`='喔...這些花讓偶想起家。', `MaleText_loc7`='Oh... eshtash floresh me recuerdan a mi hogar.' WHERE `ID`=57690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 당근 볶음이군요! 제가 가장 좋아하는 음식입니다!', `MaleText_loc4`='哦，煎炸胡萝卜！我的最爱！', `MaleText_loc5`='喔，炒胡蘿蔔!我的最愛!', `MaleText_loc7`='¡Oh, zanahoriash shalteadash! ¡Mi plato favorito!' WHERE `ID`=57691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음. 이거 직접 만드신 겁니까? 제가 원하던 바로 그 맛입니다. 감사합니다!', `MaleText_loc4`='呃……你亲手做的？这正是我想要的，谢谢你！', `MaleText_loc5`='呣嗯，這素你自己做的嗎?這正素偶要的，謝謝你!', `MaleText_loc7`='Mmm, ¿lo hash hecho tú? Esh jushto lo que quería, ¡graciash!' WHERE `ID`=57692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿그늘이 파수대 사령관 리알리아에게 가르랑거립니다.', `MaleText_loc4`='灰烬用鼻子蹭了蹭哨兵指挥官丽娅拉。', `MaleText_loc5`='艾許緊挨著哨兵指揮官賴奧莉亞。', `MaleText_loc7`='Ash acaricia con el hocico a la Comandante Centinela Lyalia.' WHERE `ID`=57693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이... 갑자기 달려들었어요. 기습이었죠.', `FemaleText_loc4`='他们……不知道从哪儿冒出来的。我中了埋伏。', `FemaleText_loc5`='他們...從四面八方冒出來。這是埋伏。', `FemaleText_loc7`='Sa... salieron de la nada. Emboscada.' WHERE `ID`=57694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 지금까지 돌밭에 아주 많은 도움을 주셨습니다. 나중에 도움이 필요하면 제가 다시 요청 드리겠습니다. 그전까지는... 우리 비행 조련사와 이야기해보십시오. 원하는 곳이라면 아무 데나 데려가 줄 겁니다... 공짜로 말이지요.', `MaleText_loc4`='你是石犁村的贵人，$n。我们以后可能还会请求你的帮助。在那之前，你该和我们的飞行管理员谈一谈，他会带你去任何你想去的地方……免费的哟。', `MaleText_loc5`='$n，你已經成為石犁村的珍貴資產了。將來我們也許會再召集你。到時候，你應該去找我們的飛行管理員交談。他會帶你去你需要去的地方...完全免費。', `MaleText_loc7`='Has sido muy importante para Villarroca, $n. Puede que volvamos a necesitarte más adelante. Hasta entonces, deberías hablar con nuestro maestro de vuelo. Él te llevará adonde tengas que ir... y gratis.' WHERE `ID`=57695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잿그늘이 저를 원정지로 다시 데려다 줄 거예요. $p, 그 독 묻은 칼을 가져오세요.', `FemaleText_loc4`='灰烬会把我带回先遣营地。拜托了，$p，带上那些毒刃。', `FemaleText_loc5`='艾許可以帶我回去侵略哨站。拜託你，$p，帶著那些淬毒的劍刃。', `FemaleText_loc7`='Ash puede llevarme de vuelta a la Incursión. Por favor, $p, trae esas espadas envenenadas.' WHERE `ID`=57696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 뭘 드릴까요? 가게 일 때문에 정신이 없네요.', `FemaleText_loc4`='那么，你到底想干嘛，陌生人？我还要经营市集呢。', `FemaleText_loc5`='嗯，有什麼事嗎，陌生人?我還得去經營市集呢。', `FemaleText_loc7`='Bueno, ¿qué va a ser, $gforastero:forastera;? Tengo un mercado que atender.' WHERE `ID`=57697;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제대로 찾아오셨군요! 언덕골 시장에는 없는 게 없답니다.', `FemaleText_loc4`='你来对地方啦，陌生人！半山市集有你需要的所有东西。', `FemaleText_loc5`='陌生人，你來對地方了!你所需要的一切都在半丘市集裡。', `FemaleText_loc7`='¡Has venido al lugar idóneo, $gforastero:forastera;! El Mercado del Alcor tiene todo lo que necesitas.' WHERE `ID`=57698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음식과 맥주를 찾으시나요? 바로 여기 언덕골 시장에 있답니다.', `FemaleText_loc4`='陌生人，你在找食物和酒？半山市集里就有。', `FemaleText_loc5`='陌生人，要找食物跟啤酒嗎?半丘市集這裡就有。', `FemaleText_loc7`='¿Buscas comida y cerveza, $gforastero:forastera;? Pues aquí en el Mercado del Alcor tenemos de eso.' WHERE `ID`=57699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 그렇게 가만히 서 있지만 마시고요! 뭐 재미있는 이야깃거리라도 없어요?', `FemaleText_loc4`='别光傻站在那儿啊，陌生人！不想过来跟我聊聊吗？', `FemaleText_loc5`='陌生人，別光只是站在那兒!你有什麼八卦可以告訴我嗎?', `FemaleText_loc7`='Pero bueno, ¡no te quedes ahí, $gforastero:forastera;! ¿Te sabes algún cotilleo?' WHERE `ID`=57700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐 사고팔려고 오신 건가요? 마음껏 둘러보세요.', `FemaleText_loc4`='陌生人，你是来买，还是要卖？请随便看看吧。', `FemaleText_loc5`='陌生人，你是要買還是要賣?隨意逛逛吧。', `FemaleText_loc7`='¿Has venido a comprar o a vender, $gforastero:forastera;? No te cortes en echar un vistazo por ahí.' WHERE `ID`=57701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 필요하신 거라도 있습니까? 제가 조금... 바빠서 말입니다.$B$B<발버둥치는 사우록의 목을 더 꽉 조이는 코로>', `MaleText_loc4`='你需要什么吗？我这会有点儿……忙。$B$B<科洛捏紧了正在挣扎的蜥蜴人的脖子。>', `MaleText_loc5`='你需要什麼嗎?我有一點...忙。$B$B<可羅把手搭在不停扭動掙扎的薩烏洛克脖子上，並用力收緊。>', `MaleText_loc7`='¿Necesitas algo? Estoy un poco... ocupado.$B$B<Koro aprieta más fuerte el cuello del saurok, que se retuerce.>' WHERE `ID`=57702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선물에 대해 알려주시겠습니까?', `MaleText_loc4`='关于礼物，你有什么好建议？', `MaleText_loc5`='關於禮物，你有什麼可以告訴我的?', `MaleText_loc7`='¿Qué puedes decirme sobre regalos?', `FemaleText_loc1`='선물에 대해 알려주시겠어요?', `FemaleText_loc4`='关于礼物，你有什么好建议？', `FemaleText_loc5`='關於禮物，你有什麼可以告訴我的?', `FemaleText_loc7`='¿Qué puedes decirme sobre regalos?' WHERE `ID`=57703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='간단하지 않을까요? 좋아하는 이가 있다면, 갖고 싶어 하는 걸 선물로 주면 되잖아요.', `FemaleText_loc4`='这有什么好说的？你喜欢谁，就送一些他们喜欢的东西呗。', `FemaleText_loc5`='沒什麼呀?你喜歡某人，就送他們會喜歡的東西。', `FemaleText_loc7`='¿Qué hay que saber? Cuando te gusta alguien, le regalas algo que le guste.' WHERE `ID`=57704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 선물 받는 걸 싫어하겠어요?$B$B저는 꽃을 좋아한답니다.', `FemaleText_loc4`='有谁不喜欢收到礼物呢？$B$B我——我喜欢花。', `FemaleText_loc5`='誰不喜歡禮物?$B$B我－我喜歡花。', `FemaleText_loc7`='¿A quién no le gusta que le hagan un regalo?$B$BA mí me encantan las flores.' WHERE `ID`=57705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아름다운 여자에게는 아름다운 꽃을 선물해야 하는 거예요. 저처럼 말이죠.', `FemaleText_loc4`='你应该把漂亮的花送给漂亮的女士，比如我。', `FemaleText_loc5`='你應該要把美麗的花送給美麗的淑女。比如說我。', `FemaleText_loc7`='Las flores bonitas hay que dárselas a las mujeres bonitas. Como yo.' WHERE `ID`=57706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 주변에 예쁜 꽃들이 많이 자라지만, 제가 가장 좋아하는 꽃은 습지대 백합이랍니다. 불행히도 그 우아한 꽃은 찾기가 쉽지 않아요.', `FemaleText_loc4`='这附近长着很多漂亮的花，而我最喜欢的是泽地百合。可惜，那种美丽的花很难找到。', `FemaleText_loc5`='這附近長了很多美麗的花，但我最愛的是溼地百合。可惜這種美麗的花非常難找。', `FemaleText_loc7`='Por aquí crecen muchas flores, pero mi favorita es el lirio de marisma. Por desgracia, esas preciosidades son difíciles de encontrar.' WHERE `ID`=57707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 정말 먹고 싶어 하는 게 뭔지 아세요? 푸짐한 소용돌이치는 안갯국 한 그릇이랍니다. 지금 이맘때에 맛이 아주 좋을 거예요.', `FemaleText_loc4`='你知道我最想要的是什么吗？一大碗迷雾汤。那一定很好喝。', `FemaleText_loc5`='我最想要什麼?一碗很棒的繚繞薄霧湯。如果現在可以來一碗一定很讚。', `FemaleText_loc7`='¿Sabes qué me encantaría probar? Un buen cuenco de sopa de niebla espiral. Me sentaría estupendamente ahora mismo.' WHERE `ID`=57708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이웃끼리는 서로 도우라는 말이 있습니다.$B$B물론 가끔 서로 일을 도와줄 수도 있겠지만, 선물을 하는 게 친구를 더 빨리 만들 수 있지 않겠습니까? 그렇지요?', `FemaleText_loc4`='你知道他们怎么说吗——帮助你的邻居，你的邻居也会帮助你。$B$B当然，你可以偶尔帮他们做一些杂事，但礼物能更快地让你们成为朋友，你不觉得吗？', `FemaleText_loc5`='你知道人們總是說:敦親睦鄰，守望相助。$B$B當然，你可以偶爾幫他們做點事，不過用送禮物的方法來交朋友更快一點，你不覺得嗎?', `FemaleText_loc7`='Ya sabes lo que se dice... ayuda a tus vecinos y ellos te ayudarán a ti.$B$BEstá claro que puedes ayudarles con sus tareas de vez en cuando, pero los regalos hacen amigos antes, ¿no te parece?' WHERE `ID`=57709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디서 선물을 찾을 수 있냐고요? 밭은 좀 살펴보신 거예요?$B$B이곳에 있는 농장에서 어떤 걸 찾을 수 있는지 절대 모르실 거예요.$B$B당신 밭에서도 뭔가 파낼 수도 있고 말이죠!', `FemaleText_loc4`='从哪儿能找到礼物？你有没有在田地里找过？$B$B你永远也不知道你会在这些农田里找到什么。$B$B说不定你甚至能在自家地里刨出些东西来！', `FemaleText_loc5`='你要去哪裡找禮物?你有試過在田地附近找一找嗎? $B$B你永遠不知道在農場周圍可以遇上什麼東西。$B$B說不定你在自己的土地裡也可以挖到東西!', `FemaleText_loc7`='¿Que dónde puedes encontrar regalos? ¿Has buscado por los campos?$B$BNunca se sabe con lo que te puedes encontrar por estas granjas.$B$B¡Quizá incluso puedas encontrar algo enterrado en tus propias tierras!' WHERE `ID`=57710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밭에서 하루 종일 일하고 나면 배가 엄청 고프답니다.$B$B이건 비밀인데, 여기 있는 주민들 대부분은 저보다도 입맛이 까다롭답니다.$B$B전부 좋아하는 음식이 따로 있거든요. 요리 기술 좀 있다면 다들 당신이 만든 요리를 먹고 싶어서 환장할 거예요.', `FemaleText_loc4`='在田里劳作一整天会让人胃口大开。$B$B别说是我告诉你的，这里的家伙胃口大到能把一个女人都吞下去。$B$B大多数人都会有一道最喜欢的菜。如果你会烹饪的话，他们会很乐意尝尝你的手艺。', `FemaleText_loc5`='在田裡工作一整天會讓人胃口大開。$B$B偷偷告訴你，這裡有許多人都可以一個人吃光一整個市場攤位的食物! $B$B大多數的人都有自己最愛吃的東西。如果你懂烹飪，他們可是會搶著來吃你做的菜。', `FemaleText_loc7`='Trabajar todo el día en el campo despierta un gran apetito.$B$BYo no te he dicho nada, pero la mayoría de esta gente se comería una vaca entera.$B$BCasi todos tienen un plato favorito. Si se te da bien la cocina, estarán deseando probar tus platos.' WHERE `ID`=57711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔어. 다른 사람이 올지도 모르니까 잠깐만 기다리자.', `MaleText_loc4`='欢迎你。我们还想再等一会儿，看看还有没有其它人要来。', `MaleText_loc5`='歡迎。我們會再停留幾秒鐘，看看會不會有別人來。', `MaleText_loc7`='$GBienvenido:Bienvenida;. Esperemos un momento a ver si alguien más se apunta.' WHERE `ID`=57712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<폭풍이 휘몰아치는 와중에 외치는 블랜치>$B$B오셨군요! 증류기와 맥주통은 준비됐어요... 이제 대자연이 마법을 부리기를 기다리기만 하면 되죠.$B$B어때요? 불꽃놀이 할 준비가 되었나요?', `FemaleText_loc4`='<布兰琪的吼声震彻风暴。>$B$B你成功了！锅炉和酒桶都到位了……现在我们就等着大自然显现神迹吧。$B$B你觉得呢？准备好来点烟火吗？', `FemaleText_loc5`='<白蘭琪在風暴中大吼。>$B$B你成功了!汽鍋和酒桶準備好了...我們需要的只剩下等待大自然施展他的魔法。$B$B你怎麼說?準備好放點煙火了嗎?', `FemaleText_loc7`='<Clara grita sobre la conmoción de la tormenta.>$B$B¡Lo has conseguido! El hervidor y los barriles están en su sitio... ahora solo hace falta que la madre naturaleza haga su magia.$B$B¿Qué me dices? ¿Estás $glisto:lista; para unos fuegos artificiales?' WHERE `ID`=57713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력을 보여 주십시오, 블랜치!', `MaleText_loc4`='让我看看你的本事吧，布兰琪！', `MaleText_loc5`='讓我看看你有什麼招數，白蘭琪!', `MaleText_loc7`='¡A ver qué sabes hacer, Clara!', `FemaleText_loc1`='실력을 보여 주세요, 블랜치!', `FemaleText_loc4`='让我看看你的本事吧，布兰琪！', `FemaleText_loc5`='讓我看看你有什麼招數，白蘭琪!', `FemaleText_loc7`='¡A ver qué sabes hacer, Clara!' WHERE `ID`=57714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이곳을 쑥대밭으로 만들 것이다, 흐흐.', `MaleText_loc4`='我们要把这地方炸成个大坑，呵呵。', `MaleText_loc5`='我們要把這地方給變成下水坑，嘿。', `MaleText_loc7`='Este sitio se va a convertir en un desagüe, je, je.' WHERE `ID`=57715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 함선의 화약통을 조작했습니다.', `MaleText_loc4`='我们在每艘船上都放好了炸药桶。', `MaleText_loc5`='我們在所有船上裝設了火藥桶。', `MaleText_loc7`='Hemos preparado barriles de pólvora en todos los barcos.', `FemaleText_loc1`='모든 함선의 화약통을 조작했어요.', `FemaleText_loc4`='我们在每艘船上都放好了炸药桶。', `FemaleText_loc5`='我們在每艘船上都裝設了火藥桶。', `FemaleText_loc7`='Hemos preparado barriles de pólvora en todos los barcos.' WHERE `ID`=57716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 이 마을 어디에 누가 사는지 다 알려 드릴 수 있답니다. 누굴 찾으세요?', `FemaleText_loc4`='我可以告诉你镇上每一个人的住处，你想找谁？', `FemaleText_loc5`='我可以告訴你鎮上每個人的住所。你要找誰?', `FemaleText_loc7`='Sabría decirte dónde vive cada uno de los habitantes de esta ciudad. ¿A quién estás buscando?' WHERE `ID`=57717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘라는 어디 삽니까?', `MaleText_loc4`='艾拉住哪儿？', `MaleText_loc5`='艾拉住在哪裡?', `MaleText_loc7`='¿Dónde vive Ella?', `FemaleText_loc1`='엘라는 어디 사나요?', `FemaleText_loc4`='艾拉住哪儿？', `FemaleText_loc5`='艾拉住在哪裡?', `FemaleText_loc7`='¿Dónde vive Ella?' WHERE `ID`=57718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 힐포우는 어디 삽니까?', `MaleText_loc4`='老农山掌住哪儿？', `MaleText_loc5`='老丘爪住在哪裡?', `MaleText_loc7`='¿Dónde vive el viejo Zarpa Collado?', `FemaleText_loc1`='늙은 힐포우는 어디 사나요?', `FemaleText_loc4`='老农山掌住哪儿？', `FemaleText_loc5`='老丘爪住在哪裡?', `FemaleText_loc7`='¿Dónde vive el viejo Zarpa Collado?' WHERE `ID`=57719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼는 어디 삽니까?', `MaleText_loc4`='阿烁住哪儿？', `MaleText_loc5`='阿秀住在哪裡?', `MaleText_loc7`='¿Dónde vive Sho?', `FemaleText_loc1`='쇼는 어디 사나요?', `FemaleText_loc4`='阿烁住哪儿？', `FemaleText_loc5`='阿秀住在哪裡?', `FemaleText_loc7`='¿Dónde vive Sho?' WHERE `ID`=57720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치는 어디 삽니까?', `MaleText_loc4`='吱吱住哪儿？', `MaleText_loc5`='奇奇住在哪裡?', `MaleText_loc7`='¿Dónde vive Chee Chee?', `FemaleText_loc1`='치 치는 어디 사나요?', `FemaleText_loc4`='吱吱住哪儿？', `FemaleText_loc5`='奇奇住在哪裡?', `FemaleText_loc7`='¿Dónde vive Chee Chee?' WHERE `ID`=57721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하오한 머드클로 씨는 어디 삽니까?', `MaleText_loc4`='郝瀚·泥爪住哪儿？', `MaleText_loc5`='好漢·泥爪住在哪裡?', `MaleText_loc7`='¿Dónde vive Haohan Zarpa Fangosa?', `FemaleText_loc1`='하오한 머드클로 씨는 어디 사나요?', `FemaleText_loc4`='郝瀚·泥爪住哪儿？', `FemaleText_loc5`='好漢·泥爪住在哪裡?', `FemaleText_loc7`='¿Dónde vive Haohan Zarpa Fangosa?' WHERE `ID`=57722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티나 머드클로는 어디 삽니까?', `MaleText_loc4`='迪娜·泥爪住哪儿？', `MaleText_loc5`='蒂娜·泥爪住在哪裡?', `MaleText_loc7`='¿Dónde vive Tina Zarpa Fangosa?', `FemaleText_loc1`='티나 머드클로는 어디 사나요?', `FemaleText_loc4`='迪娜·泥爪住哪儿？', `FemaleText_loc5`='蒂娜·泥爪住在哪裡?', `FemaleText_loc7`='¿Dónde vive Tina Zarpa Fangosa?' WHERE `ID`=57723;
