UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 이제 맥주를 수도원으로 가져가죠...', `FemaleText_loc4`='你做到了！让我们把这酒送到禅院去……', `FemaleText_loc5`='你成功了!讓我們把這酒帶去靜修居...', `FemaleText_loc7`='¡Lo han conseguido! Llevemos esta cerveza al Monasterio...' WHERE `ID`=57811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제... 제가 왜 그랬는지 모르겠습니다.', `MaleText_loc4`='我……我也不知道自己是怎么了。', `MaleText_loc5`='我...我不知道我是怎麼想的。', `MaleText_loc7`='No... No sé qué me ha pasado.', `FemaleText_loc1`='제... 제가 왜 그랬는지 모르겠어요.', `FemaleText_loc4`='我……我也不知道自己是怎么了。', `FemaleText_loc5`='我...我不知道我是怎麼想的。', `FemaleText_loc7`='No... No sé qué me ha pasado.' WHERE `ID`=57812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 우리는 희망을 포기해서는 안 됩니다.', `MaleText_loc4`='当然。我们决不能失去希望。', `MaleText_loc5`='當然了。我們不能放棄希望。', `MaleText_loc7`='Por supuesto. No debemos perder la esperanza.', `FemaleText_loc1`='물론입니다. 우리는 희망을 포기해서는 안 돼요.', `FemaleText_loc4`='当然。我们决不能失去希望。', `FemaleText_loc5`='當然了。我們不能放棄希望。', `FemaleText_loc7`='Por supuesto. No debemos perder la esperanza.' WHERE `ID`=57813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까 놈들도 죽기는 하는군요... 이제 정신을 차려야겠습니다.', `MaleText_loc4`='那就让他们死吧……我只能保持专注。', `MaleText_loc5`='所以他們會死嘛...我得保持專注。', `MaleText_loc7`='Así que PUEDEN morir... Debo mantener la concentración...', `FemaleText_loc1`='그러니까 놈들도 죽기는 하네요... 이제 정신을 차려야겠어요.', `FemaleText_loc4`='那就让他们死吧……我只能保持专注。', `FemaleText_loc5`='所以他們會死嘛...我得保持專注。', `FemaleText_loc7`='Así que PUEDEN morir... Debo mantener la concentración...' WHERE `ID`=57814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 잠시 길을 잃었던 것 같습니다', `MaleText_loc4`='谢谢你，我忘记了“道”之真意。', `MaleText_loc5`='謝謝你，我忘記了道的教誨。', `MaleText_loc7`='Gracias, me había desviado del Camino.', `FemaleText_loc1`='고마워요. 잠시 길을 잃었던 것 같아요.', `FemaleText_loc4`='谢谢你，我忘记了“道”之真意。', `FemaleText_loc5`='謝謝你，我忘記了道的教誨。', `FemaleText_loc7`='Gracias, me había desviado del Camino.' WHERE `ID`=57815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 됩니다. 이렇게 끝낼 수는 없습니다. 계속 싸워야만 합니다!', `MaleText_loc4`='不，我不能让一切就这么结束。我必须继续战斗！', `MaleText_loc5`='不，我不能讓一切這樣結束。我得繼續戰鬥!', `MaleText_loc7`='No, no puede terminar así. ¡Tengo que seguir luchando!', `FemaleText_loc1`='안 돼요. 이렇게 끝낼 수는 없어요. 계속 싸워야만 해요!', `FemaleText_loc4`='不，我不能让一切就这么结束。我必须继续战斗！', `FemaleText_loc5`='不，我不能讓一切這樣結束。我得繼續戰鬥!', `FemaleText_loc7`='No, no puede terminar así. ¡Tengo que seguir luchando!' WHERE `ID`=57816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이 옆에서 계속 싸우고 있는데, 제가 어떻게 포기하겠습니까?', `MaleText_loc4`='英雄们还在与我并肩作战，我怎能放弃？', `MaleText_loc5`='英雄在我身邊奮戰，我怎麼能放棄?', `MaleText_loc7`='¿Cómo puedo rendirme cuando hay héroes que siguen luchando a mi lado?', `FemaleText_loc1`='영웅들이 옆에서 계속 싸우고 있는데, 제가 어떻게 포기하겠어요?', `FemaleText_loc4`='英雄们还在与我并肩作战，我怎能放弃？', `FemaleText_loc5`='英雄在我身邊奮戰，我怎麼能放棄?', `FemaleText_loc7`='¿Cómo puedo rendirme cuando hay héroes que siguen luchando a mi lado?' WHERE `ID`=57817;
