UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지의 희생을 헛되이 하진 않겠어요. 사마귀들을 바짝 밀어붙여야 해요.', `FemaleText_loc4`='我父亲是不会白白牺牲的，我们得向螳螂妖发动进攻。', `FemaleText_loc5`='我父親絕不會白白犧牲。我們必須奮力攻擊以抵抗螳螂人。', `FemaleText_loc7`='El sacrificio de mi padre no habrá sido en vano. Debemos reforzar el ataque contra los mántides.' WHERE `ID`=57821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지는 적대 세력과 마주치지 않을 거라고 생각하셨어요. 하지만 생각해 보면, 아버지는 불멸성에 집착하느라 제대로 생각을 하지 않았을 거예요.', `FemaleText_loc4`='我父亲曾以为我们不会遇到抵抗。但是之后，他总是把时间花在研究永生上，而不是全面考虑问题。', `FemaleText_loc5`='我父親認為我們不會遭遇抵抗。不過話又說回來，他通常把時間花在對長生不老的迷戀上，也沒有在思考其他事情。', `FemaleText_loc7`='Mi padre pensaba que no encontraríamos resistencia, pero está tan obsesionado con la inmortalidad que a veces no piensa bien las cosas.' WHERE `ID`=57822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토지파괴자 브로자이가, 모구는 우리와 협상할 의지가 없음을 분명히 했어요.', `FemaleText_loc4`='碎地者勃罗耶证实了魔古族没有与我们谈判的打算。', `FemaleText_loc5`='創始者布歐齋說得很清楚，魔古完全無意與我們進行協商。', `FemaleText_loc7`='El quebrantasuelos Brojai ha dejado claro que los mogu no tienen intención de negociar con nosotros.' WHERE `ID`=57823;
