UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 마을 한가운데에 밭을 만들 생각을 했을까요? 참!', `FemaleText_loc4`='谁会想到在镇子中间开一个农场？哈！', `FemaleText_loc5`='誰會想要在鎮中央蓋一座農場啊?哈!', `FemaleText_loc7`='¿A quién se le ocurriría poner una granja en medio de una ciudad? ¡Ja!' WHERE `ID`=57865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 기르는 농작물만 해도 판다리아 사람을 다 먹이고 남을 것 같아요.', `FemaleText_loc4`='我敢打赌，他们在这儿种了足够所有潘达利亚人吃的食物。', `FemaleText_loc5`='我敢打賭，他們生產的食物可以餵飽潘達利亞所有的人。', `FemaleText_loc7`='Seguro que aquí cultivan suficiente comida como para alimentar a toda Pandaria.' WHERE `ID`=57866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 채소라 아쉽네요. 왜 큼지막한 고깃덩이는 없지?', `FemaleText_loc4`='只可惜全都是些蔬菜。为什么就没有肉呢？', `FemaleText_loc5`='全都只有蔬菜，真是糟透了。為什麼沒有大塊的肉呢?', `FemaleText_loc7`='Qué pena solo sean verduras. ¿Por qué no carne gigante?' WHERE `ID`=57867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 끝내준다! 양조장에서 맥주 재료를 저장해 두는 곳인가 봐요.', `FemaleText_loc4`='噢，真酷！这儿一定就是他们储藏酿造啤酒用的谷物的地方。', `FemaleText_loc5`='喔，太棒了!他們一定是用這地方儲藏釀啤酒的穀物。', `FemaleText_loc7`='¡Guau, qué bueno! Debe ser aquí donde guardan el grano para toda la cerveza que preparan en esa cervecería.' WHERE `ID`=57868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리 어른이 되고 싶어요. 그래야 맥주가 무슨 맛인지 알 거 아녜요.', `FemaleText_loc4`='我不想等到长大了才知道啤酒到底是什么味道。', `FemaleText_loc5`='我等不及要長大來嘗嘗啤酒的滋味是什麼。', `FemaleText_loc7`='Estoy deseando ser mayor para saber a qué sabe la cerveza.' WHERE `ID`=57869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웃으며 신경질적으로 째려봅니다.', `FemaleText_loc4`='%s微笑了起来，并神情紧张地瞟了一眼。', `FemaleText_loc5`='%s微笑並神經質地瞥了一眼。', `FemaleText_loc7`='%s sonríe y mira alrededor nerviosa.' WHERE `ID`=57870;
