UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 삼촌보다 훨씬 멋져요.', `FemaleText_loc4`='你比陈叔酷多了。', `FemaleText_loc5`='你比老陳叔叔要酷多了。', `FemaleText_loc7`='Eres mucho más cool que el tío Chen.' WHERE `ID`=57876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸 삼촌이랑 비취 숲을 몇 주 동안 떠돌았는데, 본 거라곤 나무뿐이에요. 참, 멋진 운룡 딱 한 마리랑요.', `FemaleText_loc4`='我和陈叔在翡翠林里转了几个星期，除了看到一条很酷的翔龙之外，就全是树了。', `FemaleText_loc5`='我和老陳叔叔在翠玉林裡繞了好幾個星期，看來看去都只有樹，還有一隻非常酷的蛟龍。', `FemaleText_loc7`='El tío Chen y yo nos pasamos semanas deambulando por El Bosque de Jade y lo único que vimos fueron árboles, y una especie de dragón increíble.' WHERE `ID`=57877;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='근데 우린 고작 하루 사이에 벌써 이 계곡을 다 봤네요.', `FemaleText_loc4`='而我和你在一起才一天，就看遍了整座山谷。', `FemaleText_loc5`='我只陪你待了一天，我們就已經把整個峽谷看過一遍了。', `FemaleText_loc7`='Solo llevo un día contigo y ya hemos visto todo este valle.' WHERE `ID`=57878;
