UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빽빽한 밀림이 ''쿵!''하고 하늘에서 떨어진 것 같아요.', `FemaleText_loc4`='这就好像，突然间，不知道从哪儿就……砰。超级茂密的丛林。', `FemaleText_loc5`='一片好密的叢林。就這樣突然...砰冒出來了。', `FemaleText_loc7`='Es como si surgiese de la nada, de repente... BUM... una jungla súper espesa.' WHERE `ID`=57880;
