UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거 정말 멋지고, 무섭고, 다 좋은데요, 이제 머드머그 아저씨네로 가야 되지 않아요?', `FemaleText_loc4`='好吧，这一切真的很酷，也很惊险，不过我们现在应该回泥盏那儿了吧？', `FemaleText_loc5`='這真的很酷，也很嚇人，但我們現在不是應該回到泥杯宅邸去嗎?', `FemaleText_loc7`='Todo esto está genial, da mucho miedo y todo… pero ¿no deberíamos volver ya a casa de Caolín?' WHERE `ID`=57884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까... 음... ? 저 아직 여기 있거든요.', `FemaleText_loc4`='那么……嗯……$p？我还在这儿呢。', `FemaleText_loc5`='所以...嗯...$p?你知道我還在這裡吧。', `FemaleText_loc7`='Eh... ¿Sabes que todavía estoy aquí?' WHERE `ID`=57885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속 따라다니고 있잖아요. 아까부터.', `FemaleText_loc4`='到处跟着你，到现在已经好一会儿了。', `FemaleText_loc5`='跟著你到處走。現在也有好一段時間了。', `FemaleText_loc7`='Te estoy siguiendo a todos lados. Llevo haciéndolo un buen rato.' WHERE `ID`=57886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악, 그렇게 막 잡아당기지 마요. 약초 캐 본 적 없어요?', `FemaleText_loc4`='哎呀，$p，别那么粗鲁嘛。你以前没摘过草药吗？', `FemaleText_loc5`='哎呀，$p，不要這麼粗暴的去扯它。你以前從沒摘過藥草嗎?', `FemaleText_loc7`='Oye, no la manosees. ¿Acaso nunca has recogido hierbas?' WHERE `ID`=57887;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='강가에 있는 저 진위랑 꼭 이야기하세요.', `FemaleText_loc4`='别忘了和那个锦鱼人聊一聊，就是河边的那个。', `FemaleText_loc5`='別忘了跟那位錦魚人聊聊，他就在河邊。', `FemaleText_loc7`='No olvides hablar con ese jinyu, junto al río.' WHERE `ID`=57888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니깐 제가 하려는 말은... 고맙다고요.', `FemaleText_loc4`='我想要说的是……谢谢。', `FemaleText_loc5`='我想我要說的是...謝謝。', `FemaleText_loc7`='Supongo que quiero decir... gracias.' WHERE `ID`=57889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아버지는 우리가 젊음의 웅덩이를 찾아 이곳에 온 거라고 하셨겠죠.$b$b사실은 여군주 티란데 위스퍼윈드 님께서 환영을 보셨어요. 우리가 이 여정에서 찾을지도 모르는... 아니 찾을 위대한 빛에 대한 환영이었지요. 우리가 그 빛을 찾아서 지켜야 한다고 하셨어요.$b$b아버지는 그게 바로 젊음의 웅덩이라고 생각하세요.$b$b제 생각에 아버지는 오랜 집착에 눈이 멀어 진실을 보지 못하고 계세요.', `FemaleText_loc4`='我父亲会告诉你我们来这里是为了寻找青春之池。$b$b而实际上，我们的泰兰德·语风女士在幻象中看到了一道神圣的光芒，我们也许会……不……我们一定会找到它。我们必须找到并且守护那束光。$b$b我父亲坚信那束光就是青春之池。$b$b但我觉得他被这十年来的狂热研究蒙蔽了双眼。', `FemaleText_loc5`='我父親會告訴你，我們是為了青春之池才來到這兒。$b$b事實是，我們的泰蘭妲·語風看到預言，我們會...即將會...在這趟旅途中找到偉大的聖光。我們必須找到那道聖光，並且保護它。$b$b我父親堅持預言中的聖光就是青春之池。$b$b我想他已被二十年來對青春之池的迷戀給蒙蔽了。', `FemaleText_loc7`='Mi padre te diría que estamos aquí por las Pozas de la Juventud.$b$bLa realidad es que nuestra señora Tyrande Susurravientos ha tenido visiones de una gran luz que encontraríamos... encontraremos... en este viaje. Una luz que debemos encontrar y defender.$b$bMi padre insiste en que se trata de las Pozas de la Juventud.$b$bCreo que está cegado por una década de obsesión.' WHERE `ID`=57890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 무슨 일로 오셨습니까?', `MaleText_loc4`='你在这儿干嘛？', `MaleText_loc5`='你在這裡做什麼?', `MaleText_loc7`='¿Qué estás haciendo aquí?', `FemaleText_loc1`='여기엔 무슨 일로 오셨나요?', `FemaleText_loc4`='你在这儿干嘛？', `FemaleText_loc5`='你在這裡做什麼?', `FemaleText_loc7`='¿Qué estás haciendo aquí?' WHERE `ID`=57891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늦었군. 자네만 비행기에 타면 출발할 걸세. 국왕 폐하의 기대가 아주 크네.', `MaleText_loc4`='你是最后一个。快上那架飞机，马上出发。国王很信任你啊。', `MaleText_loc5`='你是最後一個了。跳上那艘水上飛機我們就出發。國王很信任你。', `MaleText_loc7`='No esperamos a nadie más. Sube al hidroavión y despegaremos. El Rey confía mucho en ti.' WHERE `ID`=57892;
