UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특별한 문제 없이 차원문 10개를 여는 목표를 거의 달성해가는 중이었습니다. 저 빌어먹을 모구 놈이 함정을 설치하는 바람에 다 망쳤지요.$b$b그 함정 때문에 제 능력 대부분이 산산조각이 났지만, 다른 차원문을 몇 개 더 간신히 열 수는 있을 겁니다.', `MaleText_loc4`='我差点儿就达到了开启10次法师传送门无事故的目标。结果却被那些该死魔古族的陷阱给破坏了。$b$b那陷阱令我丧失了大部分能力，可我应该能再开几个本地传送门。', `MaleText_loc5`='我差一點就能毫無意外地完成十名法師的傳送門了。那些該死的魔古卻用他們的陷阱毀了這一切。$b$b那陷阱讓我無法使用我的能力，但我應該還是可以運用一些本地的傳送門。', `MaleText_loc7`='Casi llego a mi objetivo de diez portales de mago sin incidentes. Esos mogu tres veces malditos lo echaron a perder con su trampa.$b$bLa trampa ha mermado muchas de mis facultades, pero seré capaz de montar más portales locales.' WHERE `ID`=57897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 첫 번째 임무에서 살아남지 못했죠.', `MaleText_loc4`='……没能挺过第一次野外任务。', `MaleText_loc5`='...沒有挺過他們的第一個實地任務。', `MaleText_loc7`='... no sobrevivieron a su primera misión.' WHERE `ID`=57898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 친구를 한번 믿어 보자고. 못된 녀석들 같으니...', `MaleText_loc4`='噢，给那$g小伙子:姑娘;一次机会吧？真是一群老顽固。', `MaleText_loc5`='喔，給這$G少年:小姑娘;一個機會，好不?這群頑固的傢伙。', `MaleText_loc7`='Vamos, da una oportunidad $gal:a la; $gmuchacho:muchacha;. Panda de insensibles...' WHERE `ID`=57899;
