UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모구들은 내가 전에 상대했던 놈들하고는 싸우는 방식이 아주 달라요. 이놈들은 자신감이 있어요.', `MaleText_loc4`='这些魔古族的战斗风格跟我过去面对过的对手很不一样。他们自信满满。', `MaleText_loc5`='這些魔古的戰鬥方式與我過去遇到的非常不同。他們很有自信。', `MaleText_loc7`='Estos mogu luchan de manera muy distinta a los que me he enfrentado en otras ocasiones. Tienen confianza.' WHERE `ID`=57902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마가 지금 날 볼 수 있다면 얼마나 좋을까...', `MaleText_loc4`='如果棘杖妈妈看到我现在的样子……', `MaleText_loc5`='如果藤杖媽媽可以看到我現在的模樣...', `MaleText_loc7`='Si mamá Vara Enzarzada pudiese verme ahora...' WHERE `ID`=57903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊음의 웅덩이의 실체에 대해서 진작에 알았어야 했네. 길을 떠나기 전에 환영을 보았는데도, 영원한 젊음을 꿈꾸느라 눈이 멀었던 걸세.', `MaleText_loc4`='我应该知道青春之池的。在这趟旅途开始之前，我就预见到了，可我却被追求青春永驻的梦想蒙住了双眼。', `MaleText_loc5`='我早該知道關於青春之池的事了。在啟程之前我就有預感，但我被青春永駐的夢想給蒙蔽了。', `MaleText_loc7`='Debería haber sabido lo de las Pozas de la Juventud. Tuve visiones antes del viaje, pero estaba cegado por el sueño de la eterna juventud.' WHERE `ID`=57904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스무 해 동안 연구하고 희망하고 꿈꿔 온 것이 이렇게 무너져 내리는군. 이제 남은 것은 우리의 임무와 내 딸 리알리아뿐일세.', `MaleText_loc4`='长达二十年的研究，那些希望和梦想，全都戛然而止了。现在仅剩下这使命，还有我的女儿丽娅拉。', `MaleText_loc5`='二十年的研究，希望與夢想，都毀於一旦了。現在只剩下這個任務，以及我女兒賴奧莉亞。', `MaleText_loc7`='Veinte años de investigación, con esperanzas y sueños, todo ello echado a perder. Ahora lo único que queda es la misión... y mi hija Lyalia.' WHERE `ID`=57905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사마귀들을 보고 있으면 자꾸만 안퀴라즈의 문이 열려 아내를 삼켜버린 그 날이 생각나네.$b$b이 괴물들은 이 땅에서 진정 위협적인 존재라네.', `MaleText_loc4`='这些螳螂妖不禁让我想起安其拉大门开启的那一天，我的妻子惨遭吞噬。$b$b这些怪物是这片土地上真正的祸患。', `MaleText_loc5`='這些螳螂人，他們讓我想起安其拉之門開啟並吞噬我的妻子的那一天。$b$b這些生物是這片土地上真正的威脅。', `MaleText_loc7`='Estos mántides me recuerdan al día en que las puertas de Ahn''Qiraj se abrieron y se tragaron a mi esposa.$b$bEstas criaturas son la verdadera amenaza en esta tierra.' WHERE `ID`=57906;
