UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다, 도마뱀. 한 번 더 기회를 주마. 정찰대는 어디 있느냐?', `MaleText_loc4`='好了，蜥蜴嘴，我再给你一次机会——你们的巡逻队在哪儿？！', `MaleText_loc5`='好吧，蜥蜴嘴，再給你一次機會:你的巡邏隊在哪裡?!', `MaleText_loc7`='Vamos, cara de lagarto, tienes otra oportunidad: ¡¿dónde están tus patrullas?!' WHERE `ID`=57914;
