UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에, 그러니까, 이 무서운 밀림에 데려와 주신 거랑...', `FemaleText_loc4`='真是谢谢你把我带到恐怖的丛林和各种麻烦中来……', `FemaleText_loc5`='嗯，我很感謝你帶我一起進入這片恐怖的叢林...', `FemaleText_loc7`='Bueno, te agradezco mucho que me hayas traído a esta jungla tenebrosa y todo...' WHERE `ID`=57924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악마를 물리치는 거라든지, 재밌는 구경 시켜 주신 건 정말 고마운데요...', `FemaleText_loc4`='……让我在一旁看你驱散那古老的邪恶之力，以及其他有趣的事……', `FemaleText_loc5`='...還有讓我看著你消滅了那個古老的邪惡生物，還有我們一起做的那些事...', `FemaleText_loc7`='... que me hayas dejado mirar mientras te deshacías de un mal ancestral y todas las otras cosas que hemos hecho...' WHERE `ID`=57925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 이 정도면 오늘은 다닐 만큼 다닌 것 같지 않아요?', `FemaleText_loc4`='……可难道你不觉得，我们今天已经探索得够久了吗？', `FemaleText_loc5`='...但你不覺得我們今天的探索已經夠多了嗎?', `FemaleText_loc7`='... ¿pero no crees que ya hemos explorado bastante por hoy?' WHERE `ID`=57926;
