UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 총을 많이 가진 녀석이었어요.', `FemaleText_loc4`='天哪，那家伙绝对有两把刷子。', `FemaleText_loc5`='那傢伙真的有很多槍。', `FemaleText_loc7`='Ese tipo tenía un montón de armas.' WHERE `ID`=57930;
