UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무의 우선순위가 변경되었네.$B$B이 야영지를 방어해야 하네. 지금 당장!', `MaleText_loc4`='我们的任务优先级变更了。$B$B我们得去守护这座营地，快！', `MaleText_loc5`='我們任務的優先順序改變了。$B$B我們必須立刻守衛這座營地。', `MaleText_loc7`='La prioridad de nuestra misión ha cambiado.$b$bTenemos que defender este campamento. ¡Ya!' WHERE `ID`=57933;
