UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 쌍둥이 동생인 님은 만나보셨나요? 늘 그렇듯이 길을 잃은 모양이에요.', `MaleText_loc4`='你看见我的双胞胎妹妹尼姆了吗？她可能走失了，她总这样。', `MaleText_loc5`='你有見到我的孿生妹妹妮姆嗎?她可能和往常一樣走失了。', `MaleText_loc7`='¿Has visto a mi hermana gemela, Nimm? Seguro que se ha perdido, como de costumbre.' WHERE `ID`=57944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 얼라이언스를 처치하지 않고 싶다면요?', `MaleText_loc4`='要是我不想杀联盟怎么办？', `MaleText_loc5`='如果我不想殺聯盟的人呢?', `MaleText_loc7`='¿Y si no quiero matar a los de la Alianza?', `FemaleText_loc1`='제가 얼라이언스를 처치하지 않고 싶다면요?', `FemaleText_loc4`='要是我不想杀联盟怎么办？', `FemaleText_loc5`='如果我不想殺聯盟的人呢?', `FemaleText_loc7`='¿Y si no quiero matar a los de la Alianza?' WHERE `ID`=57945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하고 싶은 일을 물은 게 아니네. 호드에게 맹세한 서약을 이행하라고 한 걸세.$b$b$p, 깜박한 모양인데, 우리는 지금 전쟁을 치르고 있다네.$b$b전시에는 개인적인 관심사보다는 임무 수행이 우선이지.', `MaleText_loc4`='我没问你想要什么。我是要你履行对部落立下的誓言。$b$b看来我有必要提醒你，现在是在打仗，$p。$b$b在这种情况下，与责任相比，个人利益必须退居次要地位。', `MaleText_loc5`='我沒有問你想要什麼。我要求你履行你對部落立下的誓約。$b$b$p，不知道你記不記得，我們正在打仗。$b$b在這種時候，個人利益必須擺在責任後面。', `MaleText_loc7`='No te he preguntado lo que quieres. Te he pedido que cumplas las promesas que realizaste a la Horda.$b$bEstamos en guerra, $p, por si lo has olvidado.$b$bEn estas circunstancias, los intereses personales deben pasar a un segundo plano.' WHERE `ID`=57946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출산을 앞두고 있는 아내 레자가 열병에 걸렸소.$b$b이 지긋지긋한 밀림이 우리 힘을 약화시키고 있소. 아무래도 물 때문인 것 같소.', `MaleText_loc4`='我的妻子莱莎即将分娩，现在还发着高烧。$b$b这该死的丛林简直要榨干我们所有人的力量了。也许是水里有古怪。', `MaleText_loc5`='我的妻子，麗紗，她身患熱疫仍在努力工作。$b$b這個該死的叢林侵蝕了我們所有的力量。這裡的水可能有點問題。', `MaleText_loc7`='Mi esposa, Leza, está de parto y sufre unas fiebres.$b$bEsta maldita jungla está acabando con toda nuestra fuerza. Podría ser algo en el agua.' WHERE `ID`=57947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 임산부를 데려오신 겁니까?', `MaleText_loc4`='你为什么要带上个孕妇？', `MaleText_loc5`='你為什麼要帶個懷孕的女人在身邊?', `MaleText_loc7`='¿Por qué has traído a una mujer embarazada?', `FemaleText_loc1`='왜 임산부를 데려오신 건가요?', `FemaleText_loc4`='你为什么要带上个孕妇？', `FemaleText_loc5`='你為什麼要帶個懷孕的女人在身邊?', `FemaleText_loc7`='¿Por qué has traído a una mujer embarazada?' WHERE `ID`=57948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데즈코, 모구 놈들이 우리가 나약하다고 생각할 때 공격을 감행해야 하네. 이 $c|1을;를; 보내서 놈들을 혼내 주세.', `MaleText_loc4`='德兹科，我们必须趁这些魔古族轻视我们的机会出击。让我们派这位$c去对付他们吧。', `MaleText_loc5`='戴斯可，我們必須在魔古輕敵的時候給他們迎頭痛擊。讓我們派$c對他們發動攻勢吧。', `MaleText_loc7`='Dezco, debemos atacar a los mogu ahora que piensan que estamos débiles. Dejemos que $p se encargue de ellos.' WHERE `ID`=57949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 친구는 꽤나 멋지게 싸웠다. 탈출에 성공할 뻔했지만, 이제 우리와 마찬가지로 포로 신세다.', `MaleText_loc4`='你的朋友真能打，差点就逃脱了。不过现在还是和我们一样沦为阶下囚。', `MaleText_loc5`='你的朋友英勇地奮戰。他幾乎成功逃脫，但現在他像我們一樣成了囚犯。', `MaleText_loc7`='Tu amigo se ha resistido con uñas y dientes. Casi se escapa, pero ahora está prisionero, como todos nosotros.' WHERE `ID`=57950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 일족은 이방인을 경계한다. 하지만 지금으로서는 너를 믿을 수밖에 없겠군.', `MaleText_loc4`='我的族人们不喜欢陌生人，可是，我欠你太多了。但愿长老们不会因此怪罪我。', `MaleText_loc5`='我的同胞對陌生人很警戒。然而，相信你似乎是我唯一的選擇。', `MaleText_loc7`='Mi gente desconfía de los desconocidos, pero creo que no me queda más remedio que confiar en ti.' WHERE `ID`=57951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 네 친구라고 오해하지 마라. 오랜 시간 동안, 우리 일족은 신뢰가 너무 쉽게 깨어질 수 있다는 사실을 배웠다.', `MaleText_loc4`='可别把我当成你们的朋友了。经过漫长的岁月，我们的族人都已经明白信任是多么脆弱。', `MaleText_loc5`='但別以為我們就是朋友了。長久以來，我們已經學會信任易碎的道理。', `MaleText_loc7`='No me consideres tu amigo. Con el tiempo, mi pueblo se ha dado cuenta de que la confianza se traiciona muy fácilmente.' WHERE `ID`=57952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 바보들만이 이방인을 믿는다. 하지만 호젠보다는 이방인을 믿고 싶군.', `MaleText_loc4`='只有蠢货才会相信陌生人。但我宁可相信陌生人，也不相信猢狲。', `MaleText_loc5`='只有蠢材會信任陌生人，但我寧願相信一個陌生人也不願相信一個猴人。', `MaleText_loc7`='Es de necios confiar en los desconocidos, pero prefiero confiar en un desconocido que en un hozen.' WHERE `ID`=57953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 한때 위대한 진위 제국의 소유였다. 하지만 우리 왕국이 황폐화되면서, 지칠 줄 모르는 호젠에게 많은 땅을 빼앗기고 말았다.', `MaleText_loc4`='这片土地曾经属于伟大的锦鱼人帝国。在帝国衰落之后，我们的土地就逐渐落入野蛮的猢狲部族手中。', `MaleText_loc5`='這塊土地曾經屬於偉大的錦魚人帝國。隨著我們的國土於絕望中陷落，我們有越來越多的土地淪入無情的猴人之手。', `MaleText_loc7`='Esta tierra perteneció una vez al gran imperio jinyu. Con el deterioro de nuestro reino, hemos perdido cada vez más territorio en favor de las despiadadas tribus hozen.' WHERE `ID`=57954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족은 마지막 남은 마을을 지키기 위해 싸우고 있다. 지금 패하면, 한때 위대했던 황제와 철학자들의 혈통이 끊어질 것이다.', `MaleText_loc4`='现在，我的族人要为保卫我们的最后一个村子而战。如果我们现在失败了，那么曾经显赫一时的帝王与贤者的血脉就将消失。', `MaleText_loc5`='我的人民為了守衛我們最後的村莊而戰。如果我們在此刻輸了，這代表一條曾經屬於偉大帝王和哲學家們的血脈就此終結。', `MaleText_loc7`='Mi pueblo lucha para defender nuestro último poblado. Si perdemos ahora, será el final de un linaje de otrora grandes emperadores y filósofos.' WHERE `ID`=57955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 이곳에서 도망쳐야 하는 신세지만, 다시 이곳으로 돌아올 때는 진위 전사들을 이끌고 오겠다.', `MaleText_loc4`='我会逃出去的。当我回来时，将带来一整支锦鱼人大军。', `MaleText_loc5`='我會逃離這裡。當我回來時，我會帶著一整支錦魚人戰士組成的軍隊。', `MaleText_loc7`='Huiré de aquí, y cuando vuelva, lo haré con un ejército de guerreros jinyu.' WHERE `ID`=57956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영에서는 이런 일이 있을 거라는 이야기는 없었다네.', `MaleText_loc4`='我们看到的幻象里没有包含这件事。', `MaleText_loc5`='我們所看到的幻象並沒有預示到這件事。', `MaleText_loc7`='Las visiones que tuvimos no mencionaron este evento.' WHERE `ID`=57957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테일러는 마치 날뛰는 야수처럼 호젠과 맞서 싸웠네. 자네 동료들에게 멋진 본보기가 되었지!$B$B하지만 결국 붙잡히고 말았네.', `MaleText_loc4`='泰勒就像头野兽一样激烈地抵抗那些猢狲。他真是你族人中的英雄！$B$B但最后，他还是被击败了。', `MaleText_loc5`='泰勒像隻野獸似的和猴人戰鬥。他為你們族人帶來極大的榮耀!$B$B但最終，他被敵人淹沒了。', `MaleText_loc7`='Taylor se defendió de los hozen como un león. ¡Tu gente debería estar muy orgullosa!$b$bPero al final pudieron con él.' WHERE `ID`=57958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<제독의 몸은 온통 상처와 멍, 피와 땀으로 덮여 있습니다. 열도 심하게 나는 것 같습니다.>', `MaleText_loc4`='<上将的身体上伤痕累累、血汗模糊。他好像正在发烧。>', `MaleText_loc5`='<上將全身上下都是傷口、抓痕、瘀傷、鮮血和汗珠。他似乎正發著高燒。>', `MaleText_loc7`='<El cuerpo del almirante está lleno de heridas, raspones, moratones, sangre y sudor. Parece que tiene fiebre.>' WHERE `ID`=57959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르와 데즈코에게 보낼 보고서를 갖고 있습니까?', `MaleText_loc4`='你有什么事要报告给科尔和德兹科吗？', `MaleText_loc5`='你有報告要交給柯爾和戴斯可嗎?', `MaleText_loc7`='¿Tienes un informe para Kor y Dezco?', `FemaleText_loc1`='코르와 데즈코에게 보낼 보고서를 갖고 있나요?', `FemaleText_loc4`='你有什么事要报告给科尔和德兹科吗？', `FemaleText_loc5`='你有報告要交給柯爾和戴斯可嗎?', `FemaleText_loc7`='¿Tienes un informe para Kor y Dezco?' WHERE `ID`=57960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅을 잘 살펴봐. 여긴 지뢰밭이나 마찬가지야!', `MaleText_loc4`='注意脚下，这里可是雷区！', `MaleText_loc5`='小心你的腳步，那可是塊地雷區!', `MaleText_loc7`='¡Mira dónde pisas! ¡Esto es un campo de minas!' WHERE `ID`=57961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 무슨 일인가, 이방인?', `MaleText_loc4`='嗯，陌生人？', `MaleText_loc5`='是的，陌生人?', `MaleText_loc7`='¿Sí, $gforastero:forastera;?' WHERE `ID`=57962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인, 너와는 할 말이 없다. 뭘 원하나?', `MaleText_loc4`='我跟你没什么好说的，陌生人。你想要什么？', `MaleText_loc5`='我和你一點關係都沒有，陌生人。你想要什麼?', `MaleText_loc7`='No tengo nada que decirte, $gforastero:forastera;. ¿Qué quieres?' WHERE `ID`=57963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 아는 걸 말씀드리자면, 보시다시피 상황이 예상과는 다르답니다.$b$b이곳 주민들은 도움이 필요하니 저는 여기 머물며 도움을 줄 생각이에요.$b$b그대도 여기 머물며 우리를 도와주신다면 전세가 눈에 띄게 달라질 거예요.', `FemaleText_loc4`='情况是这样的。如你所见，事情有些出乎我们的预料。$b$b这些人需要帮助，而我打算留下来帮助他们。$b$b如果你也愿意留下来，在你的帮助下，问题会变得更加容易解决。', `FemaleText_loc5`='我的情況是這樣的。如你所見，事情並不如我們的預期。$b$b這些人需要我們的幫助，而我打算留下來幫助他們。$b$b如果你也願意留下來，有你的幫助，我們的機會更大。', `FemaleText_loc7`='Esto es lo que tengo. Como ves, las cosas no son como esperábamos.$b$bEsta gente necesita ayuda, y pienso quedarme para ayudarles.$b$bSi tú también decides quedarte, tendríamos muchas más posibilidades.' WHERE `ID`=57964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 밀림 때문에 우울해졌어요.', `FemaleText_loc4`='这丛林让我心生沮丧。', `FemaleText_loc5`='這片叢林讓我很沮喪。', `FemaleText_loc7`='Esta jungla me deprime.' WHERE `ID`=57965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 안 돼요. 레자는 제가 계속 신경 써줘야만 한답니다. 출산 예정일보다 3주나 빨리 아기를 낳고 있으니 뭔가 아주 안 좋은 것 같아요.', `FemaleText_loc4`='现在别来打搅我。我得全心全意照料莱莎。她早产三个星期，出了不小的问题。', `FemaleText_loc5`='現在不行。麗紗需要我照顧。她早了三周，而且有什麼事非常的不對勁。', `FemaleText_loc7`='Ahora no. Leza necesita toda mi atención. Lleva tres semanas de adelanto y algo va mal.' WHERE `ID`=57966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏들은 구덩이로 꺼져!', `MaleText_loc4`='你们蠢蛋只配活在垃圾堆里！', `MaleText_loc5`='怪怪人到坑裡去!', `MaleText_loc7`='¡Makakus en tumba!' WHERE `ID`=57969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어어... 족장님 기분 나쁘겠다...', `MaleText_loc4`='噢喔……酋长知道了要生气的……', `MaleText_loc5`='呃喔...酋長不會高興的...', `MaleText_loc7`='Uh, uh... Jefe no se va a poner kontento...' WHERE `ID`=57970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 매끈피부들, 훔쳐갈 생각은 하지도 마!', `MaleText_loc4`='别偷我们的大光板儿！', `MaleText_loc5`='不准偷走大滑魚!', `MaleText_loc7`='¡Ustedes no mangan manduka!' WHERE `ID`=57971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구크구트가 너희 죽으래!', `MaleText_loc4`='咕克嘎克要你们死！', `MaleText_loc5`='尬腸說你必須死!', `MaleText_loc7`='¡Gukgut dice ke tú muere!' WHERE `ID`=57972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 뭐하는 거요? 야운골이 쿤라이 봉우리를 습격하고 있다는 거, 모르오?', `MaleText_loc4`='你在这里做什么？！你难道不知道，野牛人正在入侵昆莱山？', `MaleText_loc5`='你在這幹嘛?!你不知道揚古在入侵崑萊峰嗎?', `MaleText_loc7`='¡¿Qué estás haciendo aquí?! ¿No sabes que los yaungol están invadiendo la Cima Kun-Lai?', `FemaleText_loc1`='여기서 뭐하는 거예요? 야운골이 쿤라이 봉우리를 습격하고 있다는 거, 몰라요?', `FemaleText_loc4`='你在这里做什么？！你难道不知道，野牛人正在入侵昆莱山？', `FemaleText_loc5`='你在這幹嘛?!你不知道揚古在入侵崑萊峰嗎?', `FemaleText_loc7`='¡¿Qué estás haciendo aquí?! ¿No sabes que los yaungol están invadiendo la Cima Kun-Lai?' WHERE `ID`=57973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이들 여기다 응가 떨굴 생각은 하지도 마!', `MaleText_loc4`='坏蛋来干坏事了！', `MaleText_loc5`='廢渣在做壞壞的事情!', `MaleText_loc7`='¡Mikos hacen kosas dingues!' WHERE `ID`=57974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가를 날려버려!', `MaleText_loc4`='把他们弄死！', `MaleText_loc5`='敲爆他們這些渾蛋!', `MaleText_loc7`='¡Hacedles kraku en el kuku!' WHERE `ID`=57975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구리구리 응가쟁이야!', `MaleText_loc4`='坏蛋太坏了！', `MaleText_loc5`='壞廢渣!', `MaleText_loc7`='¡Dingue miko!' WHERE `ID`=57976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징그러운 매끈피부들이 도망친다!', `MaleText_loc4`='讨厌的光板儿逃走啦！', `MaleText_loc5`='壞滑魚逃跑了!', `MaleText_loc7`='¡Kochos mandukos eskapan!' WHERE `ID`=57977;
