UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸르륵!', `MaleText_loc4`='可恶！', `MaleText_loc5`='肝!', `MaleText_loc7`='¡Kuaho!' WHERE `ID`=57983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면, 야운골은 쿤라이 평원을 가로질러 가다, 갑자기 두 이상한 괴물의 습격을 받게 됐다네!', `MaleText_loc4`='相传，那野牛人正在穿越昆莱平原，突然遭到两个奇怪生物的伏击！', `MaleText_loc5`='根據故事，在揚古穿越崑萊平原時，忽然有兩隻奇怪的生物襲擊他!', `MaleText_loc7`='Según cuenta la historia, el yaungol viajaba por las llanuras de Kun-Lai cuando dos extrañas criaturas le tendieron una emboscada.' WHERE `ID`=57986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상님들을 위해!', `MaleText_loc4`='为了祖先的荣耀!', `MaleText_loc5`='為了先祖!', `MaleText_loc7`='¡POR LOS ANCESTROS!' WHERE `ID`=57987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골은 맹렬히 괴물들을 공격했지. 하지만 그가 공격을 거듭할수록 괴물은 더 무시무시하게 커졌다네!', `MaleText_loc4`='野牛人坚决勇猛地予以回击。可是，他的反击越猛烈，那些野兽就变得越是可怕！', `MaleText_loc5`='揚古帶著無比決心，勇猛攻擊那些野獸。但是他越攻擊，野獸就變得越恐怖!', `MaleText_loc7`='El yaungol atacó a las bestias con gran ferocidad y determinación, pero cuanto más atacaba, ¡más aterradoras se volvían las bestias!' WHERE `ID`=57988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그가 공격을 멈추자, 괴물은 거의 무에 가까울 정도로 작아졌지.', `MaleText_loc4`='然而，当他不理它们时，那些野兽却几乎化为虚无。', `MaleText_loc5`='不過，他置之不理時，野獸就縮小到幾乎消失了。', `MaleText_loc7`='Por el contrario, cuando paró, las bestias se encogieron hasta casi desaparecer.' WHERE `ID`=57989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이처럼 불화는 분쟁을 먹고 살지. 자신의 가슴 속이 평화롭다면, 불화는 다른 대상을 찾아 배회한다네.', `MaleText_loc4`='你明白了吧，没有对抗，就没有纷争。当你内心一片平静时，纷争便会离你而去。', `MaleText_loc5`='看得出來，鬥爭只會招來衝突。你內心平靜的時候，鬥爭心就會離開跑去其他地方。', `MaleText_loc7`='Sepan pues… la calamidad se nutre del conflicto. Si llenan su corazón de paz, la calamidad tendrá que irse a otra parte.' WHERE `ID`=57990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=58002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 당했다! 방심하지 마십시오!', `MaleText_loc4`='我动不了了！你们小心！', `MaleText_loc5`='我被箝制住了!你們自己小心點!', `MaleText_loc7`='¡No puedo moverme! ¡Tengan cuidado!' WHERE `ID`=58003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p! 저 폐허를 보게나. 어떤 제국이 저런 것을 건설했는지 궁금하군.', `MaleText_loc4`='看看这片遗迹，$p。真不知道是什么样的帝国建造出来的。', `MaleText_loc5`='看看這些廢墟，$p!我很想知道是什麼樣的帝國打造出這些東西。', `MaleText_loc7`='¡Mira estas ruinas, $p! Me pregunto qué clase de imperio las construiría.' WHERE `ID`=58004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 기묘하고 흥미로운 생물이군. 키도 크고 건장한 데다가 금속에 가까운 피부를 지녔네. 이 생물을 연구해 봐야겠네.', `MaleText_loc4`='这是多么奇特有趣的生物啊。又高又壮，还有着钢铁般的皮肤。我必须得好好研究一下。', `MaleText_loc5`='真是奇怪而迷人的生物。高大，魁武，有著金屬般的肌膚。我非得研究這些生物不可。', `MaleText_loc7`='Qué criaturas tan extrañas y fascinantes. Altas, corpulentas, con una piel casi metálica. Debo investigar a estas criaturas.' WHERE `ID`=58005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊음의 물. 이 물은 생명력을 옮겨 줄 뿐일세. 내 해석이 이제야 모두 맞아 들어가는군.$b$b아마도 모구는 이 물을 이용해 포로나 반란자, 노예를 희생시켜 자기 생을 연장했을 걸세.$b$b내가 연구했던 고대 두루마리가 모두 모구가 쓴 것이기에, 그 사실을 빠뜨렸던 듯하네.', `MaleText_loc4`='水。只是转移生命。我开始明白我那译文的含义了。$b$b我猜魔古族曾用献祭囚犯、叛徒和奴隶的方式，继续与水共生。$b$b我还猜测，我研究的那些古老卷轴，最初都是由魔古族书写的，而他们没有提及这个事实。', `MaleText_loc5`='那些水。它們只轉移生命。現在我的翻譯開始說得通了。$b$b我推測魔古曾用這些水，藉由犧牲囚犯、叛亂份子與奴隸的性命，來延長他們自己的壽命。$b$b這也是我的猜測，我所研究的古代卷軸都是出自魔古之手，而他們則略過此事不提。', `MaleText_loc7`='Las aguas. Solo transfieren vida. Mis traducciones ya empiezan a tener sentido.$b$bSupongo que los mogu alargaban sus vidas con el agua sacrificando prisioneros, rebeldes y esclavos.$b$bTambién imagino que todos los antiguos pergaminos que he investigado fueron escritos en origen por los mogu, y se olvidaron de mencionar ese dato.' WHERE `ID`=58006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 착하지? 오, 그래그래...', `MaleText_loc4`='好——好——好狗狗……', `MaleText_loc5`='乖喔乖...乖狗狗...', `MaleText_loc7`='P-perritos buenos...' WHERE `ID`=58007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 이건 아니야. 이건 아니야...', `MaleText_loc4`='这可不太好。', `MaleText_loc5`='情況不妙...', `MaleText_loc7`='Esto no me gusta...' WHERE `ID`=58008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 얼굴은 안 돼.', `MaleText_loc4`='别打脸！', `MaleText_loc5`='別打臉!', `MaleText_loc7`='¡En la cara no!' WHERE `ID`=58009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 던졌어? 누구야?!', `MaleText_loc4`='谁扔的桶？老实交代！到底是谁？！', `MaleText_loc5`='誰丟的桶子?到底是誰?', `MaleText_loc7`='¿A quién se le ocurre tirar un cubo? ¡En serio! ¡¿Quién ha sido?!' WHERE `ID`=58010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아악!', `MaleText_loc4`='啊啊！', `MaleText_loc5`='嘎啊啊啊!', `MaleText_loc7`='¡Aaaah!' WHERE `ID`=58011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 저 사람, 안개 너머에서 우리를 구하러 온 영웅일지도 몰라.', `MaleText_loc4`='也许$g他:她;是来自迷雾之外的英雄，特地来救我们的？', `MaleText_loc5`='或許$g他:她;是來自迷霧另一端的英雄，專程到這裡拯救我們?', `MaleText_loc7`='Quizás sea $gel héroe:la heroína; de más allá de la niebla que ha venido a salvarnos...', `FemaleText_loc1`='어쩌면 저 사람, 안개 너머에서 우리를 구하러 온 영웅일지도 몰라요.', `FemaleText_loc4`='也许$g他:她;是来自迷雾之外的英雄，特地来救我们的？', `FemaleText_loc5`='或許$g他:她;是來自迷霧另一端的英雄，專程到這裡拯救我們?', `FemaleText_loc7`='Quizás sea $gel héroe:la heroína; de más allá de la niebla que ha venido a salvarnos...' WHERE `ID`=58012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 침입자의 존재가 느껴진다. 호젠인가? 모습을 보여라!', `MaleText_loc4`='等等，我感觉到有入侵者。是猢狲吗？快滚出来！', `MaleText_loc5`='等等，我感覺有入侵者。是猴人嗎?快現身!', `MaleText_loc7`='Espera, percibo la presencia de intrusos. ¿Serán hozen? ¡Den la cara!' WHERE `ID`=58013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 아무 짓도 하지 않았다. 줄꼬리 부족의 족장, 구크구트의 짓이다.', `MaleText_loc4`='我什么都没做。这都是吊尾酋长干的，咕克嘎克。', `MaleText_loc5`='我什麼都沒做。都是一個叫做尬腸的彈尾酋長幹的。', `MaleText_loc7`='No hemos sido nosotros. Esto es obra del jefe Colafusta, Gukgut.' WHERE `ID`=58014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 외부인을 마을에 들이는 일이 별로 없다.', `MaleText_loc4`='我们可没有欢迎外乡人来我们村的习俗。', `MaleText_loc5`='我們沒有歡迎外地人來我們村裡的習慣。', `MaleText_loc7`='No acostumbramos recibir a desconocidos en nuestra aldea.' WHERE `ID`=58015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테일러가 회복될 때까지만 이곳에 머물러라. 그 후에는 떠나야 한다.', `MaleText_loc4`='你们可以留下，直到泰勒痊愈。但那以后，你们必须离开。', `MaleText_loc5`='你們可以留下，等泰勒康復。等他好了，你們就得離開。', `MaleText_loc7`='Pueden quedarse solo hasta que Taylor se recupere. Después tendrán que marcharse.' WHERE `ID`=58016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택의 여지가 없다. 전사여, 무기를 내려놓으시오. 우리도 내려놓겠소.', `MaleText_loc4`='我们别无选择。放下你的武器，战士，我们同样也放下武器。', `MaleText_loc5`='我們別無選擇了。把武器放下吧，戰士，我們也會放下手裡的武器。', `MaleText_loc7`='No tenemos elección. Baja tu arma, guerrero, y nosotros bajaremos las nuestras.' WHERE `ID`=58017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n? 이게 무슨 일인가?', `MaleText_loc4`='$n？这里出什么事了？', `MaleText_loc5`='$n?這裡是怎麼回事?', `MaleText_loc7`='¿$n? ¿Qué está ocurriendo aquí?' WHERE `ID`=58018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저자를 믿어도 될까요?', `FemaleText_loc4`='长官，你觉得我们能相信他？', `FemaleText_loc5`='我們能相信他嗎，指揮官?', `FemaleText_loc7`='¿Podemos confiar en él, Comandante?' WHERE `ID`=58019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독님께 무슨 짓을 한 거냐?', `MaleText_loc4`='你对我们的海军上将做了什么？', `MaleText_loc5`='你對我們的上將做了什麼?', `MaleText_loc7`='¿Qué le han hecho al Almirante?' WHERE `ID`=58020;
