UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간여행자: 고대의 전쟁', `MaleText_loc4`='时间行者：远古之战', `MaleText_loc5`='時光行者:先祖之戰', `MaleText_loc7`='Caminantes del Tiempo: Guerra de los Ancestros', `FemaleText_loc1`='시간여행자: 고대의 전쟁', `FemaleText_loc4`='时间行者：远古之战', `FemaleText_loc5`='時光行者:先祖之戰', `FemaleText_loc7`='Caminantes del Tiempo: Guerra de los Ancestros' WHERE `ID`=58024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치열하게 싸우며 적을 돌파해야 한다. 내가 달리는 동안 호젠을 막아다오. 성공하면, 우리 마을에서 다시 만나자.', `MaleText_loc4`='我们要打一场硬仗了。在我逃跑的时候，你得缠住那些猢狲。假如一切顺利，我们在村子里碰头。', `MaleText_loc5`='我們將面對一場惡戰。你必須在我通過時和猴人交戰。一切順利的話，我會和你在我的村子裡碰頭。', `MaleText_loc7`='Vamos a pasar a través de una batalla encarnizada. Ocúpate de los hozen mientras yo me abro paso. Si todo va bien, te veré en mi poblado.' WHERE `ID`=58025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 저도 저 차원문으로 뛰어들려고 해봤어요.', `MaleText_loc4`='是的，我也试着跳过那玩意儿。', `MaleText_loc5`='是的。我也試著跳過那玩意兒。', `MaleText_loc7`='Sí, yo también intenté cruzar eso de un salto.' WHERE `ID`=58026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 함정이 작동되면, 걸려든 이는 생명력을 다 흡수당할 때까지 빠져나오지 못해요. 모구는 사악한 놈들이에요.', `MaleText_loc4`='陷阱一旦被触发，任何人都进不去也出不来，直到被困在里面的人被彻底吸干生命。魔古族可真邪恶。', `MaleText_loc5`='一旦陷阱啟動，沒有人能進來，也沒人能出去，直到它完全吸乾所有人的生命。魔古很邪惡。', `MaleText_loc7`='Cuando la trampa se activa, nadie puede entrar ni salir hasta que las personas atrapadas quedan vacías de vida. Los mogu son malignos.' WHERE `ID`=58027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해요. 거기 갇히면 함정이 당신의 생명력을 흡수해서 동력원으로 사용해요.', `MaleText_loc4`='多加小心。要是你被困住了，它就会汲取你的生命，来为自己赋能。', `MaleText_loc5`='小心。卡在裡面的話，它會吸乾你的生命作為自己的力量。', `MaleText_loc7`='Cuidado. Si te atrapa, te absorberá la vida para alimentarse.' WHERE `ID`=58028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 모구 함정은 무서운 옛이야기에서도 위험했지만, 지금도 똑같이 위험해요.', `MaleText_loc4`='时至今日，这些古老的魔古陷阱仍然危险得很，其威力与恐怖的传说时代相比也毫不逊色。', `MaleText_loc5`='古老的魔古陷阱在今日仍然危險，就和他們在那些嚇人的傳說裡一樣。', `MaleText_loc7`='Las viejas trampas mogu son tan peligrosas ahora como en la época de las historias de miedo.' WHERE `ID`=58029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹으로 때려보고, 발로 차보고, 후려갈겨도 봤지만, 아무리 해도 이 비밀감옥을 깰 수가 없었어요.', `MaleText_loc4`='我试着打它、踢它、拍它、凿它。可任何方法都无济于事。', `MaleText_loc5`='我揍它、踢它、甩它巴掌還劈哩啪啦地扁它。似乎沒有任何東西能破壞這個地牢。', `MaleText_loc7`='Le he dado puñetazos, patadas, golpes, porrazos. Parece que nada puede romper este calabozo.' WHERE `ID`=58030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대담한 카라쉬가 돌아왔다!', `MaleText_loc4`='勇敢的卡拉什回来了！', `MaleText_loc5`='英勇的卡爾勒什回來了!', `MaleText_loc7`='¡Karasshi el Audaz ha regresado!' WHERE `ID`=58031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 봐! 이방인이야.', `MaleText_loc4`='看，一个陌生人。', `MaleText_loc5`='看，一個陌生人。', `MaleText_loc7`='Mirad, $gun extraño:una extraña;.' WHERE `ID`=58032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용없습니다! 호젠이 우릴 압박해 옵니다!', `MaleText_loc4`='这没用！我们被猢狲打得节节败退！', `MaleText_loc5`='沒用的!猴人把我們都逼退了!', `MaleText_loc7`='¡Es inútil! ¡Los hozen nos obligan a retroceder!' WHERE `ID`=58033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 내십시오, 전사들! 호젠을 막으십시오!', `MaleText_loc4`='坚强点，战士们！挡住这些猢狲！', `MaleText_loc5`='振作起來，戰士們!擋住這些猴人!', `MaleText_loc7`='¡Sean fuertes, guerreros! ¡Mantengan a los hozen a raya!' WHERE `ID`=58034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리들 사이로 섞여 들어온 저 이방인은 누구지?', `MaleText_loc4`='这个与我们同行的陌生人是谁？', `MaleText_loc5`='跟我們走在一起的陌生人是誰?', `MaleText_loc7`='¿Quién es $gel extraño:la extraña; que anda entre nosotros?' WHERE `ID`=58035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건... 이방인인가?', `MaleText_loc4`='这就是那个陌生人吗？', `MaleText_loc5`='他就是那個陌生人嗎?', `MaleText_loc7`='¿$gEse:Esa; es $gel extraño:la extraña;?' WHERE `ID`=58036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 용기를 내시오! 진격!', `MaleText_loc4`='勇敢点，兄弟们！前进！', `MaleText_loc5`='拿出勇氣，弟兄們!推進!', `MaleText_loc7`='¡Ánimo, hermanos! ¡Avanzad!' WHERE `ID`=58037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진주지느러미를 위하여!', `MaleText_loc4`='为了珠鳍部族！', `MaleText_loc5`='為了珠鰭!', `MaleText_loc7`='¡Por los Aleta de Nácar!' WHERE `ID`=58038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부축해 주십시오. 무... 무릎에 화살을 맞았습니다...', `MaleText_loc4`='拉我一把，$p。我……我膝盖中箭了……', `MaleText_loc5`='幫我一把，$p。我...我的膝蓋中了一箭...', `MaleText_loc7`='Ayúdenme... Me... me hirieron en la rodilla con una flecha...' WHERE `ID`=58039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 저는 괜찮습니다. 계속 가지요.', `MaleText_loc4`='谢谢你。我没事，我们继续前进。', `MaleText_loc5`='謝謝你。我會沒事的，我們最好繼續前進。', `MaleText_loc7`='Gracias. Me recuperaré, pero será mejor seguir avanzando.' WHERE `ID`=58040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록들이 또 옵니다!', `MaleText_loc4`='有更多蜥蜴人来了！', `MaleText_loc5`='更多薩烏洛克來了!', `MaleText_loc7`='¡Se acercan más saurok!' WHERE `ID`=58041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 내 무릎! 미안합니다. 이래서는 싸울 수가 없군요.', `MaleText_loc4`='啊！我的膝盖！对不起，$p，我这样不能战斗。', `MaleText_loc5`='嘎啊!我的膝蓋!對不起，$p，我沒辦法繼續戰鬥了。', `MaleText_loc7`='¡Aah! ¡Mi rodilla! Lo siento, no puedo luchar así.' WHERE `ID`=58042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야영지가 바로 앞입니다. 이제부터는 우리끼리 갈 수 있습니다.', `MaleText_loc4`='营地就在前方，我们应该能安然抵达。', `MaleText_loc5`='營地就在前方，我們從這裡應該走得到。', `MaleText_loc7`='El campamento está un poco más adelante. Podremos llegar desde aquí.' WHERE `ID`=58043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 여기 있구나. 정말 사랑스럽지 않니? 죽은 남편과 난 항상 아이가 갖고 싶었어.', `FemaleText_loc4`='啊，这孩子在这儿。他看起来很特别吧？我和我的亡夫一直都想要个孩子。', `FemaleText_loc5`='啊，找到這孩子了。他長得很特別對吧?我過世的丈夫和我總是想要小孩。', `FemaleText_loc7`='Ah, aquí está. ¿A que tiene algo especial? Mi difunto marido y yo siempre quisimos tener hijos.' WHERE `ID`=58044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안이 그랬어요! 신한테 겁쟁이라고 놀리면서, 옥의 마녀네 문을 두드리라고 했어요.', `MaleText_loc4`='都是安的错！是她怂恿阿信去敲青玉巫婆的大门的。', `MaleText_loc5`='是安!是她賭小新不敢去敲玉巫婆的門。', `MaleText_loc7`='¡Fue An! Se apostó que Shin no se atrevería a llamar a la puerta de la Bruja de Jade.', `FemaleText_loc1`='안이 그랬어요! 신한테 겁쟁이라고 놀리면서, 옥의 마녀네 문을 두드리라고 했지 뭐예요.', `FemaleText_loc4`='都是安的错！是她怂恿阿信去敲青玉巫婆的大门的。', `FemaleText_loc5`='是安!是她賭小新不敢去敲玉巫婆的門。', `FemaleText_loc7`='¡Fue An! Se apostó que Shin no se atrevería a llamar a la puerta de la Bruja de Jade.' WHERE `ID`=58045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마가 보고 싶어요.', `MaleText_loc4`='我要妈妈。', `MaleText_loc5`='我想要媽咪。', `MaleText_loc7`='Quiero a mi mamá.', `FemaleText_loc1`='엄마를 보고 싶어요.', `FemaleText_loc4`='我要妈妈。', `FemaleText_loc5`='我想要媽咪。', `FemaleText_loc7`='Quiero a mi mamá.' WHERE `ID`=58046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 고마워요! 고마워요! 고마워요!', `MaleText_loc4`='哦，谢谢！谢谢！谢谢！', `MaleText_loc5`='喔謝謝你!謝謝你!謝謝你!', `MaleText_loc7`='¡Oh, gracias! ¡Gracias! ¡Gracias!', `FemaleText_loc1`='아, 고마워요! 고마워요! 고마워요!', `FemaleText_loc4`='哦，谢谢！谢谢！谢谢！', `FemaleText_loc5`='喔謝謝你!謝謝你!謝謝你!', `FemaleText_loc7`='¡Oh, gracias! ¡Gracias! ¡Gracias!' WHERE `ID`=58047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 선의를 증명할 기회를 주십시오. 해를 끼칠 생각은 없습니다.', `MaleText_loc4`='请给我们一个机会来证明我们的友谊。我们不会伤害你们的。', `MaleText_loc5`='請給我們一個機會證明我們的友誼。我們對你們沒有惡意。', `MaleText_loc7`='Danos una oportunidad para demostrar nuestra amistad. No les deseamos ningún mal.', `FemaleText_loc1`='우리 선의를 증명할 기회를 주세요. 해를 끼칠 생각은 없어요.', `FemaleText_loc4`='请给我们一个机会来证明我们的友谊。我们不会伤害你们的。', `FemaleText_loc5`='請給我們一個機會證明我們的友誼。我們對你們沒有惡意。', `FemaleText_loc7`='Danos una oportunidad para demostrar nuestra amistad. No les deseamos ningún mal.' WHERE `ID`=58048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 하고 계십니까?', `MaleText_loc4`='你在干什么？', `MaleText_loc5`='你在做什麼?', `MaleText_loc7`='¿Qué estás haciendo?', `FemaleText_loc1`='무엇을 하고 계신가요?', `FemaleText_loc4`='你在干什么？', `FemaleText_loc5`='你在做什麼?', `FemaleText_loc7`='¿Qué estás haciendo?' WHERE `ID`=58049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 제 친구들은 평화로운 동맹을 원합니다.', `MaleText_loc4`='我和我的朋友带着和平的意愿而来。', `MaleText_loc5`='我的朋友們和我是為了和平而來。', `MaleText_loc7`='Mis amigos y yo venimos en son de paz.', `FemaleText_loc1`='저와 제 친구들은 평화로운 동맹을 원해요.', `FemaleText_loc4`='我和我的朋友带着和平的意愿而来。', `FemaleText_loc5`='我的朋友們和我是為了和平而來。', `FemaleText_loc7`='Mis amigos y yo venimos en son de paz.' WHERE `ID`=58050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 얼라이언스입니다. 적이 아니라 동맹이 되기를 청합니다.', `MaleText_loc4`='我来自联盟。我们希望成为你们的朋友，而不是敌人。', `MaleText_loc5`='我來自聯盟。我們希望成為盟友，而不是敵人。', `MaleText_loc7`='Vengo de la Alianza. Queremos ser sus aliados, no sus enemigos.', `FemaleText_loc1`='저희는 얼라이언스랍니다. 적이 아니라 동맹이 되고 싶어요.', `FemaleText_loc4`='我来自联盟。我们希望成为你们的朋友，而不是敌人。', `FemaleText_loc5`='我來自聯盟。我們希望成為盟友，而不是敵人。', `FemaleText_loc7`='Vengo de la Alianza. Queremos ser sus aliados, no sus enemigos.' WHERE `ID`=58051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명확한 목표를 찾으려면, 자네의 내면에 집중해야 하네.', `MaleText_loc4`='想要清晰了解自己的心意，就要反省你的内心。', `MaleText_loc5`='深深自省，你就能找到透徹的體悟和決心。', `MaleText_loc7`='Para encontrar la claridad y la determinación, sumérgete en la reflexión interna.' WHERE `ID`=58052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔잔한 물처럼 마음을 차분하게 가라앉히게. 그리고 심호흡을 하게. 평온을 찾을 수 있네.', `MaleText_loc4`='让你的思绪澄净如水。深呼吸，然后保持平静。', `MaleText_loc5`='讓你的神識平靜如水。深深呼吸。心若冰清。', `MaleText_loc7`='Mantén la mente tranquila como el agua en calma. Respira profundo. Y permanece en paz.' WHERE `ID`=58053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 내 자신이 우리 일족의 역사가와 같은 존재라고 생각하네. 그리고 현재를 이해하려면 먼저 과거의 사건들을 살펴봐야 한다고 믿는다네.', `MaleText_loc4`='我喜欢将自己定位为本民族的历史学家。我相信，为了更好地理解现状，我们必须研究过去的历史。', `MaleText_loc5`='我喜歡把自己想成歷史學家。我相信我們應該審視過去的歷史，才能了解現在。', `MaleText_loc7`='Me gusta pensar que soy un historiador de mi pueblo. Creo que para entender el presente deberíamos estudiar los acontecimientos del pasado.' WHERE `ID`=58054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해를 끼칠 생각이 없다고? 파하! 수천 년 전, 진주지느러미 부족은 판다리아의 왕좌에 앉아 있었네. 하지만 이제, 남아 있는 건 이 마을뿐이지. 모두 다른 종족... 호젠을 믿었기 때문이네.', `MaleText_loc4`='不会伤害？呸！几千年前，珠鳍部族统治着潘达利亚全境。可现在，我们就只剩下这个村子里的族人了，而这一切都是因为我们相信了一个外来部族……那些猢狲。', `MaleText_loc5`='沒有惡意?呸!數千年前，珠鰭一族統治著整個潘達利亞。現在這個村莊是我們人民唯一的領土，就因為我們相信了一族外來人，猴人。', `MaleText_loc7`='¿Ningún mal? ¡Bah! Hace miles de años, la tribu Aleta de Nácar ocupaba el trono de Pandaria. Ahora, este pueblo es todo lo que queda, y todo porque confiamos en una tribu de forasteros: los hozen.' WHERE `ID`=58055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $c|1이로군;로군;! 이쪽으로 와 주게. 잠깐 시간이 있으면, 내 부탁을 하나만 들어 주게나.', `MaleText_loc4`='哦！$c！到这来。如果你有空的话，我需要你帮我个忙。', `MaleText_loc5`='喔!$c!在這裡。若你有空，我需要一點援助。', `MaleText_loc7`='¡Ah! Aquí, $c. Me vendría bien un poco de ayuda, si tienes un segundo.' WHERE `ID`=58056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 당신이 그 외부 종족이군요. 슬프게도 저는 지금 전쟁 무기를 만들고 있습니다. 불과 얼마 전까지만 해도 기도와 의식용 도구를 만들었습니다. 이 전쟁이 모든 이들의 신경을 곤두서게 하고 있습니다.', `MaleText_loc4`='啊，你肯定是个外乡人。很遗憾，我正在制作武器。不久之前，我还是个专门制作祭典礼器的手艺人呢。这场战争把大家都逼入了绝境。', `MaleText_loc5`='啊，你一定就是那個外來者。唉，我正在為戰爭製作武器。就在不久之前，我的工作還只是為了祈禱及慶典而製作祭器而已。這場戰爭讓每個人都針鋒相對，神經緊繃了起來。', `MaleText_loc7`='Ah, tú debes ser $gel forastero:la forastera;. Por desgracia estoy fabricando armas para la guerra. Antes, hace no mucho tiempo, creaba instrumentos para los rezos y las celebraciones. Es esta guerra la que nos hace vivir al borde del peligro.' WHERE `ID`=58057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호병이 강해져야 우리가 생존할 수 있는 가능성도 높아집니다. 당신 같은 사람도 쉽게 알 수 있는 문제겠지요.', `MaleText_loc4`='我们的守卫越强壮，我们生存下来的几率也就越大。但这显而易见，特别是对于像你这样的人。', `MaleText_loc5`='防衛越強，我們生存的機率就越高。但就連你，也應該清楚目前的狀況。', `MaleText_loc7`='Cuanto más fuertes sean nuestros defensores, mayor será nuestra probabilidad de sobrevivir. Pero eso debería ser obvio, incluso para alguien como tú.' WHERE `ID`=58058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 강하게 훈련해야 합니다.', `MaleText_loc4`='我们得更加刻苦训练。', `MaleText_loc5`='我們必須更努力地接受訓練。', `MaleText_loc7`='Debemos entrenarnos más.' WHERE `ID`=58059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 전사들에게 제가 아는 것을 모두 가르치고 있습니다. 하지만 아쉽게도, 그걸로는 부족한 것 같습니다.', `MaleText_loc4`='我已经把我所会的都教给我们的战士们了。不幸的是，这似乎还不够。', `MaleText_loc5`='我正試著將自己所知的一切全教給我們的戰士。不幸的是，那似乎還不夠。', `MaleText_loc7`='Les enseño a nuestros guerreros todo lo que sé. Por desgracia, no parece ser suficiente.' WHERE `ID`=58060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 지저분한 유격전에 의존합니다. 매복이나 함정 같은 것들이죠. 슬픈 일이지만, 아무래도 항상 우리보다 영리한 움직임을 보입니다.', `MaleText_loc4`='猢狲总是使用卑鄙的游击战术，例如伏击和陷阱。很不幸是的，我们每次都会中他们的招。', `MaleText_loc5`='猴人慣用骯髒的游擊戰術:埋伏和陷阱。雖然聽起來很悲哀，但他們似乎總是能靠智取打敗我們。', `MaleText_loc7`='Los hozen recurren a tácticas de guerrilla deshonrosas: emboscadas y trampas. Es triste, pero nos superan en ingenio a cada paso que dan.' WHERE `ID`=58061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 물을 지배합니다. 그래서 이 마을을 지금까지 지킬 수 있었던 것이지요. 하지만 땅에서는, 특히 굵은 나무로 덮인 땅에서는 호젠이 훨씬 우월합니다.', `MaleText_loc4`='我们是水上的霸主，这也是我们为什么能坚守村子如此之久的原因。但是在陆地上，特别是丛林茂密的地方，猢狲拥有压倒性的优势。', `MaleText_loc5`='我們擅於馭水，這就是我們有辦法保護這村子這麼長時間的原因。但在陸地上，特別是透過重重大樹的掩護，猴人佔有強大的優勢。', `MaleText_loc7`='Somos expertos del agua; por eso hemos podido defender esta aldea tanto tiempo. En tierra, sin embargo, los hozen son muy superiores, especialmente bajo los árboles.' WHERE `ID`=58062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각만 하는 것보다는 행동하는 편이 당신의 뜻을 분명히 드러낼 수 있습니다. 저희 전사들은 보복을 원합니다. 하지만 훈련을 해야 그 목표를 이룰 수 있을 것입니다. 이제 가 보십시오. 우리는 바쁩니다.', `MaleText_loc4`='君子讷于言而敏于行，陌生人。我的战士们渴望复仇，但这需要更加刻苦的修炼。走开点，我们很忙。', `MaleText_loc5`='坐而言不如起而行，陌生人。我的戰士們想要報復，但唯有練習才能辦到。走開點，我們很忙。', `MaleText_loc7`='Los actos dicen más que las palabras, $gforastero:forastera;. Mis guerreros desean vengarse, pero solo lo conseguirán mediante el entrenamiento. Ahora vete. Estamos ocupados.' WHERE `ID`=58063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 호수가 얼마나 잔잔하고 차분한지 봤나? 그게 우리가 원하는 모습이다. 한결같고, 움직이지 않는 모습. 우리는 변화를 바라지 않는다.', `MaleText_loc4`='你看见我们湖泊了吗？多么宁静安详。我们就喜欢这样。稳定、宁静。我们不喜欢改变。', `MaleText_loc5`='你看過我們的湖水了嗎，是不是非常平靜清澈?那就是我們喜歡它的原因。恆常，悠久。我們不喜歡改變。', `MaleText_loc7`='¿Has visto nuestro lago, tan tranquilo y en calma? Así es como nos gusta. Constante. Inmóvil. No soportamos el cambio.' WHERE `ID`=58064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 강이 우리 모두를 통해 흐른다. 어떤 이들은 자신을 물의 길에 던지고자 한다. 다른 이들은 물가로 헤엄쳐 가려 하고.$B$B너는 어떤가, 이방인이여? 네 강이 너를 어디로 데려가는가?', `MaleText_loc4`='奔流不息的河水冲刷着我们每一个人。有些人选择随波逐流、苟活于世；有些人选择激流勇进、开创未来。$B$B你是哪一种，陌生人？你心中的河水将流向何方？', `MaleText_loc5`='偉大之河在我們所有人的體內流淌。有些人寧願隨波逐流。而有些人會朝特定的岸邊游去。$B$B你是哪一類呢，陌生人?你的河流將你帶到何方?', `MaleText_loc7`='El gran río fluye a través de todos nosotros. Hay quien prefiere entregarse al recorrido del agua. Otros nadan hacia la costa.$b$b¿Tú qué prefieres, $gforastero:forastera;? ¿Adónde conduce tu río?' WHERE `ID`=58065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 잔잔한 호수에 돌이 떨어지는 것을 본 적이 있나? 모든 행동은 물결을 일으키지. 우정을 맺는 것도 마찬가지다. 네 제안에 대해 생각해 보겠다.', `MaleText_loc4`='陌生人，你见过石子落入平静的湖水中的样子吗？我们的一举一动都会激起阵阵涟漪，哪怕是接受一份信誓旦旦的友情。我需要三思而后行。', `MaleText_loc5`='陌生人，你曾看過石頭墜入平靜的湖中嗎?每個行動都會激起漣漪，就連接受友誼的誓言也一樣。我得考慮一下你的請求。', `MaleText_loc7`='$gForastero:Forastera;, ¿alguna vez has visto una piedra caer en un lago en calma? Toda acción provoca una reacción; incluso aceptar una petición de amistad. Consideraré tu solicitud.' WHERE `ID`=58066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠수모를 잊지 말게, $n...', `MaleText_loc4`='别忘了你的头盔，$n。新丁……', `MaleText_loc5`='別忘了你頭盔，$n。菜鳥...', `MaleText_loc7`='No te olvides del yelmo, $n. Estos novatos...' WHERE `ID`=58067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 잠수모를 잃어버렸습니다.', `MaleText_loc4`='指挥官，我把潜水头盔弄丢了。', `MaleText_loc5`='指揮官，我弄丟了我的頭盔。', `MaleText_loc7`='Comandante, he perdido mi escafandra.', `FemaleText_loc1`='사령관님, 잠수모를 잃어버렸어요.', `FemaleText_loc4`='指挥官，我把潜水头盔弄丢了。', `FemaleText_loc5`='指揮官，我弄丟了我的頭盔。', `FemaleText_loc7`='Comandante, he perdido mi escafandra.' WHERE `ID`=58068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크히히! 네놈은 저기 네 친구처럼 진흙탕에서 죽을 거다...', `MaleText_loc4`='嘻嘻嘻！你会跟你那边的朋友一样，死在泥浆里的……', `MaleText_loc5`='嘿嘿!你會像你那邊的朋友一樣死在泥巴裡...', `MaleText_loc7`='¡Tsss! Morirás en el barro como tu amigo...' WHERE `ID`=58069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉개 버리겠다!', `MaleText_loc4`='我要粉碎你！', `MaleText_loc5`='我會摧毀你!', `MaleText_loc7`='¡Los machacaré!' WHERE `ID`=58070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌들은 자신들이 어려운 때에도 친절하게 음식을 나눠주고, 불가의 따듯한 자리를 내주었답니다.$B$B우리는 그들로부터 많은 것을 배웠어요.', `FemaleText_loc4`='即便是在困难时期，熊猫人也总是慷慨地与他人分享食物和栖身之所。$B$B我们其他人都该向他们学习。', `FemaleText_loc5`='即使是在他們自己也很匱乏的時候，熊貓人還是很大方地分享出食物與火堆旁的空間。$B$B他們有多地方可供我們學習。', `FemaleText_loc7`='Incluso en tiempos de necesidad, los pandaren han ofrecido amablemente compartir su comida y un sitio junto al fuego.$B$BTodos nosotros podíamos aprender mucho de ellos.' WHERE `ID`=58071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌들은 자신들이 어려운 때에도 친절하게 음식을 나눠주고, 불가의 따듯한 자리를 내주었답니다.$B$B우리는 그들로부터 많은 것을 배웠어요.', `FemaleText_loc4`='即便是在困难时期，熊猫人也总是慷慨地与他人分享食物和栖身之所。$B$B我们其他人都该向他们学习。', `FemaleText_loc5`='即使是在他們自己也很匱乏的時候，熊貓人還是很大方地分享出食物與火堆旁的空間。$B$B他們有多地方可供我們學習。', `FemaleText_loc7`='Incluso en tiempos de necesidad, los pandaren han ofrecido amablemente compartir su comida y un sitio junto al fuego.$B$BTodos nosotros podíamos aprender mucho de ellos.' WHERE `ID`=58072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! $p! 내 딸이! 화, 환영에... 내 딸이 위험하네!', `MaleText_loc4`='啊！$p！我的女儿！我……看到了幻象，她……她遇到麻烦了！', `MaleText_loc5`='啊!$p!我的女兒!我...是一個幻像，她...她有麻煩了!', `MaleText_loc7`='¡Ah! ¡$p! ¡Mi hija! Yo... una visión, está... ¡está en peligro!' WHERE `ID`=58073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 옛날에 모구는 이런 덫을 온 세상에 설치해서, 사람들이 여기저기로 차원문을 타고 이동하는 걸 막으려고 했어요. 비밀감옥은 안에 갇힌 사람들에게서 빨아내는 힘으로 작동하고, 사람들이 다 죽고 나야 작동을 멈추지요.$b$b그래서 엄마가 항상 얘기했어요. "모르는 사람의 차원문에는 손을 넣지 마라."', `MaleText_loc4`='早在多年以前，魔古族就会在世界各地布满这种小陷阱，以阻止人们四处传送。陷阱会从被困者的身上汲取能量，直到他们死亡。$b$b就像棘杖妈妈常说的那样：“别随便把手伸进陌生人的传送门。”', `MaleText_loc5`='在很久很久以前，魔古在世界各地設置了許多像這樣的小陷阱，用來阻擋人們利用傳送門移動。這陷阱的能量來自於被卡在裡面的人，一直到他們死去後，陷阱才會失效。$b$b就像藤杖媽媽常說的:「別把手放進陌生人的傳送門。」', `MaleText_loc7`='Allá por los viejos tiempos, los mogu ponían trampas como estas por todo el mundo para evitar que la gente utilizara los portales para ir de un lado a otro. Se activan al contactar con alguien y no se desactivan hasta que la víctima ha muerto.$b$bComo mamá Vara Enzarzada solía decir: "No metas la mano en el portal de un desconocido".' WHERE `ID`=58074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭡니까?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='這是什麼東西?', `MaleText_loc7`='¿Qué es esto?', `FemaleText_loc1`='이게 뭔가요?', `FemaleText_loc4`='这是什么？', `FemaleText_loc5`='這是什麼東西?', `FemaleText_loc7`='¿Qué es esto?' WHERE `ID`=58075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요! 거기 누구 없나요? 이보세요오오오!', `FemaleText_loc4`='嘿！有人吗？喂！', `FemaleText_loc5`='嘿!有人在這裡嗎?有人嗎－!', `FemaleText_loc7`='¿Hola? ¿Hay alguien ahí? ¡Hooooolaaaaaa!' WHERE `ID`=58076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 문제가 많이 생길 줄은 몰랐습니다.$B$B사원을 떠나지 말았어야 하나 봅니다...', `MaleText_loc4`='我从没想到我们会在这里遇到这么大麻烦。$B$B也许就不该离开寺庙……', `MaleText_loc5`='我沒想到會在這裡遇上這麼多麻煩。$B$B也許我們根本不該離開寺廟...', `MaleText_loc7`='Nunca imaginé que tendríamos tantos problemas por aquí.$B$BQuizá no deberíamos haber salido del templo...' WHERE `ID`=58077;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 좀 도와주세요!', `FemaleText_loc4`='谁来救救我！', `FemaleText_loc5`='誰來幫幫忙!', `FemaleText_loc7`='¡Que alguien me ayude!' WHERE `ID`=58078;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야 이 원숭아, 날 그렇게 쳐다보지 말란 말이야. 난 먹을 게 아니라고. 알았어?', `FemaleText_loc4`='嗨，猴子，别这么瞧我。我可不是用来吃的，明白？', `FemaleText_loc5`='嘿，猴子。別那樣看我。我不是食物，懂嗎?', `FemaleText_loc7`='Oye, mono, no me mires así. A mí no se me come, ¿entiendes?' WHERE `ID`=58079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 콩알만한 까만 눈으로 날 그렇게 쳐다보지 말라고!', `FemaleText_loc4`='别用你那贼溜溜的小眼睛盯着我看！', `FemaleText_loc5`='別用你的小眼珠子那樣看我!', `FemaleText_loc7`='¡Deja de mirarme con esos ojos de pájaro!' WHERE `ID`=58080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까이 오지 마, 이 원숭아! 난 숙련된 SI:7 요원이야.', `FemaleText_loc4`='别过来，死猴子！我可是个训练有素的军情七处特工。', `FemaleText_loc5`='別靠近了，猴子!我可是受過嚴格軍情七處訓練的密探。', `FemaleText_loc7`='¡No te acerques más, mono! ¡Soy una agente del IV:7 letal!' WHERE `ID`=58081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 다들 어디 갔어요? 여기 우리에 노움 하나 있어요! 도와줘요!', `FemaleText_loc4`='呃……大家都去哪儿了？这边笼子里有个侏儒！救命啊！', `FemaleText_loc5`='喔...大家都跑哪去了?有個地精在籠子裡啊!幫幫忙啊!', `FemaleText_loc7`='Ay... ¿dónde está todo el mundo? ¡Aquí hay gnoma encerrada! ¡Socorro!' WHERE `ID`=58082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신세를 졌소.', `MaleText_loc4`='我欠你个人情。', `MaleText_loc5`='我會回報你的。', `MaleText_loc7`='Estoy en deuda contigo.' WHERE `ID`=58086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유력이 대단하군요!', `MaleText_loc4`='真是强大的治疗啊！', `MaleText_loc5`='這治療真有效!', `MaleText_loc7`='¡Qué curación más poderosa!' WHERE `ID`=58087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 싸웁시다, $c. 당신이 있으면 힘이 될 거요.', `MaleText_loc4`='加入我们吧，$c。你在战斗中能助我们一臂之力。', `MaleText_loc5`='$c，加入我們。我們在戰鬥中用得上你。', `MaleText_loc7`='Únete a nosotros, $c. Nos serías de mucha ayuda en la batalla.' WHERE `ID`=58088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 당신은 제 생명의 은인이십니다.', `MaleText_loc4`='谢谢你。是你救了我。', `MaleText_loc5`='謝謝你。你救了我的命。', `MaleText_loc7`='Gracias. Me has salvado la vida.' WHERE `ID`=58089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈안 마을을 구하기 위해 다시 싸움을 시작해야겠소.', `MaleText_loc4`='我必须重新加入拯救滨岸村的战斗。', `MaleText_loc5`='我必須重回戰場拯救濱南村。', `MaleText_loc7`='Debo volver a la batalla para salvar la Aldea Binan.' WHERE `ID`=58090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 놈들을 탕랑 평원으로 쫓아 보내야 합니다.', `MaleText_loc4`='我们必须把野牛人赶回螳螂高原。', `MaleText_loc5`='我們必須把揚古趕回螳螂荒原去。', `MaleText_loc7`='Debemos repeler a los yaungol de vuelta a las Estepas de Tong Long.' WHERE `ID`=58091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낯선 이여, 그대는 매우 영예로운 분이시군요. 저희와 함께해 주십시오.', `MaleText_loc4`='你身负殊荣，陌生人。请加入我们吧。', `MaleText_loc5`='陌生人，你擁有崇高的榮譽感。請加入我們。', `MaleText_loc7`='Eres honorable, $gextranjero:extranjera;. Únete a nosotros, por favor.' WHERE `ID`=58092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤오하오 황제께서 당신을 보내신 게 분명합니다.', `MaleText_loc4`='你一定是少昊派来的救星。', `MaleText_loc5`='一定是紹昊派你來的。', `MaleText_loc7`='Te ha debido enviar Shaohao.' WHERE `ID`=58093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이젠 어쩔 거냐, 태양길잡이?', `MaleText_loc4`='现在怎么说，烈日行者？', `MaleText_loc5`='日行者，現在要怎麼辦?', `MaleText_loc7`='¿Y ahora qué, Caminasol?' WHERE `ID`=58095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찬성이다.', `MaleText_loc4`='同意。', `MaleText_loc5`='同意。', `MaleText_loc7`='De acuerdo.' WHERE `ID`=58096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 피차 많은 것을 잃은 것 같다, 늙은 엘프. 시신을 수습하지.', `MaleText_loc4`='我想我们今天全都损失惨重，年老的精灵。收殓亡者吧。', `MaleText_loc5`='老精靈，我們今天都失去了很多東西。去幫你的死者處理後事吧。', `MaleText_loc7`='Creo que ambos hemos perdido bastante hoy, viejo elfo. Ocúpense de sus muertos.' WHERE `ID`=58097;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 앰버라는 이름의 SI:7 요원을 보셨나요?$B$B그녀가 탄 폭격기가 크게 손상된 채로 북동쪽에 있는 숲 속으로 사라졌다고 하더라고요.', `FemaleText_loc4`='你见过那个名叫安玻的军情七处特工吗？$B$B她的轰炸机遭到重创，消失在了东北边的那片树林里，之后就杳无音信了。', `FemaleText_loc5`='你有看到一個名叫琥珀的軍情七處探員嗎?$B$B我最後聽說她的轟炸機遭受嚴重的損傷，並消失在東北方的樹林中。', `FemaleText_loc7`='¿Has visto a una agente del IV:7 llamada Amber?$b$bLa última vez que la vi, su bombardero había sufrido grandes daños y desapareció entre los árboles, al noreste.' WHERE `ID`=58098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수업을 시작하지!', `MaleText_loc4`='现在开始上课！', `MaleText_loc5`='現在開始上課!', `MaleText_loc7`='¡Estamos dando clase!' WHERE `ID`=58099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석.', `MaleText_loc4`='蠢货。', `MaleText_loc5`='蠢蛋。', `MaleText_loc7`='Suspendido.' WHERE `ID`=58100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 몸이 많이 좋아졌습니다.$B$B미시카와 대담한 카라쉬가 제게 지금까지의 이야기를 들려주었습니다. 당신이 도착하고, 하얀 싹을 찾고, 호젠에게서 절 구출한 얘기까지요.$B$B이상적인 상황은 아니고, 아직 할 일도 많습니다. 우선은 안두인 왕자님을 찾아내는 것이 최우선 과제겠습니다.', `MaleText_loc4`='是的，我感觉好多了。$B$B米希卡和勇敢的卡拉什向我汇报了最近的情况：你的到来，你搜寻白卒的过程，以及将我从猢狲手中营救回来的事迹。$B$B目前的情形不容乐观，我们还有很多工作要做。我们当前的首要任务是找到安度因王子。', `MaleText_loc5`='是的，我感覺好多了。$B$B密西卡和英勇的卡爾勒什把大致情況都跟我說了:你的到來、搜索白棋的行動，以及將我從猴人手中救出的過程。$B$B目前的情況並不理想，我們有很多事情得做，找到安杜因是第一要務。', `MaleText_loc7`='Sí, me encuentro mucho mejor.$b$bMishka y Karasshi el Audaz me han puesto al tanto de todo: tu llegada, la búsqueda del peón blanco, mi rescate de los hozen...$b$bLa situación no es ideal y tenemos mucho trabajo que hacer. Nuestra prioridad es encontrar a Anduin.' WHERE `ID`=58101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수업... 끝.', `MaleText_loc4`='课程…结束了。', `MaleText_loc5`='課堂...結束了。', `MaleText_loc7`='La lección... ha terminado.' WHERE `ID`=58102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_book_01.blp:20|t%s|1이;가; $n에게 |cFFFF0000|Hspell:113395|h[혹독한 가르침]|h|r을 내립니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_book_01.blp:20|t%s给$n来了个|cFFFF0000|Hspell:113395|h[严酷教训]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_book_01.blp:20|t%s 給$n指派了|cFFFF0000|Hspell:113395|h[嚴酷課程]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_book_01.blp:20|t¡%s asigna a $n una |cFFFF0000|Hspell:113395|h[Dura lección]|h|r!' WHERE `ID`=58103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장비를 아주 제때에 가져왔군, $n. 장로님이 물예언의 의식을 시작할 준비를 마치셨네.', `MaleText_loc4`='你总算及时把东西带回来了，$n。长老已经准备好进行水语仪式了。', `MaleText_loc5`='你把祭器帶回的時間剛好，$n!長者準備好進行水語儀式了。', `MaleText_loc7`='Nos has devuelto los instrumentos justo a tiempo, $n. El ancestro está listo para llevar a cabo la ceremonia de la oración del agua.' WHERE `ID`=58104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급사는 필사적으로 싸우다가 심한 상처를 입어 죽은 듯합니다.$B$B하지만 보급품 가방은 무사합니다.', `MaleText_loc4`='这里看来发生过激烈打斗，信使一定是因伤而死的。$B$B他的补给背包似乎原封未动。', `MaleText_loc5`='看來經過一場激烈的戰鬥後，信差因為傷勢過重而死亡了。$B$B他的補給背袋倒是完好如初。', `MaleText_loc7`='El mensajero debe de haber muerto por las heridas de lo que parece haber sido una lucha brutal.$B$BSu saco de provisiones parece estar intacto.' WHERE `ID`=58105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급사는 필사적으로 싸우다가 심한 상처를 입어 죽은 듯합니다.', `MaleText_loc4`='这里看来发生过激烈打斗，信使一定是因伤而死的。', `MaleText_loc5`='看來經過一場激烈的戰鬥後，信差因為傷勢過重而死亡了。', `MaleText_loc7`='El mensajero debe de haber muerto por las heridas de lo que parece haber sido una lucha brutal.' WHERE `ID`=58106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품을 가져갑니다.', `MaleText_loc4`='拿走补给品。', `MaleText_loc5`='把補給品拿走。', `MaleText_loc7`='Recoge las provisiones.', `FemaleText_loc1`='보급품을 가져갑니다.', `FemaleText_loc4`='拿走补给品。', `FemaleText_loc5`='把補給品拿走。', `FemaleText_loc7`='Recoge las provisiones.' WHERE `ID`=58107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 이방인이여. 신비의 판다리아를 방문하고자 하십니까?', `MaleText_loc4`='你好啊，陌生人。你想要造访神秘的潘达利亚吗？', `MaleText_loc5`='歡迎，陌生人。你想要參觀神秘的潘達利亞嗎?', `MaleText_loc7`='Saludos. ¿Te gustaría visitar la mística Pandaria?' WHERE `ID`=58108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아로 보내주십시오!', `MaleText_loc4`='送我去潘达利亚！', `MaleText_loc5`='送我去潘達利亞!', `MaleText_loc7`='¡Envíame a Pandaria!', `FemaleText_loc1`='판다리아로 보내주세요!', `FemaleText_loc4`='送我去潘达利亚！', `FemaleText_loc5`='送我去潘達利亞!', `FemaleText_loc7`='¡Envíame a Pandaria!' WHERE `ID`=58109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 원더브루네 아들? 골든드래프트 집안인 내가, 그런 녀석이 어디에 있는지 어떻게 알겠나? 그 집안은 아름다운 이 마을의 명성에 흠집을 내는 존재라고.$b$b게다가, 그 추악한 아들놈이 감히 내 딸아이에게 눈독을 들이는 것 같더군. 절대로 받아들일 수 없어!$b$b그 녀석이나 내 딸을 만나게 되면, 이 말을 꼭 전해주게.', `MaleText_loc4`='那个游酒家的家伙？为什么一个金酿家的人要知道游酒家的人在哪儿呢？他们家族只会让我们美丽的小镇蒙羞。$b$b更可恶的是，那个卑鄙肮脏的家伙好像盯上我的女儿了。我绝不允许这种事发生！$b$b如果你看到他或是我女儿，帮我多说说他们两个。', `MaleText_loc5`='蕩酒?為什麼金流家的人要知道蕩酒家的傢伙在哪裡?那個家族一向是這個美麗城鎮名聲上的污點。$b$b更糟的是，那個雜碎可能還覬覦著我的女兒。我絕不能忍受這種事!$b$b如果你看到那小子或者我的女兒，讓他們知道我的意思。', `MaleText_loc7`='¿Ese Pócima Errante? ¿Por qué iba a saber un Brisa Dorada dónde anda un Pócima Errante? Su familia siempre ha sido como una cicatriz en la reputación de nuestra maravillosa ciudad.$b$bY, lo que es peor, probablemente ese cretino le haya echado el ojo a mi hija. ¡No lo toleraré!$b$bSi ves a mi hija o a él, díselo de mi parte.' WHERE `ID`=58119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로? 당연하죠. 그 친구를 찾아 돌아다닌 게 지금까지 한두 번이 아니었어요. 로하고 시라 골든드래프트요.$b$b저기 술 취한 호젠 여관이나 도원을 찾아보시는 게 빠를 거예요.', `MaleText_loc4`='罗？当然。我已经去找过他好多次了。呃，其实是找他和塞拉·金酿两个人。$b$b他们最常去的地方，就是旅店和百木园。', `MaleText_loc5`='小樓?當然。我被派去找他好多次了。應該說，找他和錫拉·金流。$b$b通常他們不是在旅店就是落英園。', `MaleText_loc7`='¿Lo? Claro. Me han enviado a buscarlo muchas veces. Bueno, a él y a Syra Brisa Dorada.$b$bLos mejores sitios para buscarlos son la posada o El Arboretum.' WHERE `ID`=58120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈 준비는 됐습니까? 이곳 일은 거의 끝난 것 같습니다...', `MaleText_loc4`='你准备好出发了吗？我想我们在这里的事情刚好要做完了……', `MaleText_loc5`='你準備好動身了嗎?我想我們這裡的工作都完成了...', `MaleText_loc7`='¿Estás $glisto:lista; para partir? Creo que ya hemos acabado por aquí...' WHERE `ID`=58123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 덕분에 시조님들께서 내 사윗감에게 축복을 내려 주셨네. 이건 원더브루 집안과 골든드래프트 집안 사이의 다툼도 끝나게 되었다는 뜻일세.$b$b이건 자네만 알고 있게. 사실, 이렇게 도와준 것을 정말 고맙게 생각하네. 이렇게 오랜 세월 서로 미워한다는 것은 정말 피곤한 일이거든.$b$b서로 지나치게 자기 입장만을 고집했던 탓에, 우리 두 집안의 차이점을 극복할 수 있게 도와줄 무언가, 아니 누군가가 필요했던 모양이네.', `MaleText_loc4`='多亏了你，族长祝福了我未来的女婿。我想这意味着游酒家族和金酿家族的世仇终于可以终结了。$b$b不要告诉别人，其实我还是很感激你的。长年死抱着仇恨不放是很累人的。$b$b我们过去太固执己见了，需要某些新的事物，或新的人，来帮我们理清分歧、搁置争议。', `MaleText_loc5`='多虧了你，潘達族王們祝福了我未來的女婿。我猜這代表金流和蕩酒家得一笑泯恩仇了。$b$b別告訴任何人，但我有點感謝你這樣做。這麼多年的憎恨真的很累人。$b$b我們都太執著於自己的想法，需要新的人事物來幫忙摒除之間的爭議。', `MaleText_loc7`='Los pandriarcas bendijeron a mi futuro yerno gracias a ti. Supongo que eso significa que tendremos que aparcar las disputas entre los Pócima Errante y los Brisa Dorada.$b$bNo se lo cuentes a nadie, pero te estoy algo agradecido. Tantos años de odio cansan mucho.$b$bEstábamos obcecados por nuestras tradiciones, y ha hecho falta algo o alguien de fuera para ayudarnos a superar nuestras diferencias.' WHERE `ID`=58124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $p 님! 도와주신 덕분에 행복한 생활이 시작되었어요. 저는 로와 함께 지낼 수 있고, 저희 아버지도 마음을 놓으신 것 같아요.$b$b아직 솔직히 말씀하지는 않으셨지만, 제 생각에 아버지도 로를 좋아하시는 것 같아요.', `FemaleText_loc4`='谢谢你，$p！我很高兴你帮助了我们。罗现在跟我在一起了，甚至我的父亲看起来也缓和了许多。$b$b他是不会向我承认这点的，但我认为我的父亲是喜欢罗的。', `FemaleText_loc5`='謝謝你，$p!我真高興你來幫助我們。我終於和小樓在一起了，就連我父親都好像放鬆了許多。$b$b他不願在我面前承認，但我想我父親喜歡小樓。', `FemaleText_loc7`='¡Gracias, $p! Me alegra tanto que nos hayas ayudado... Mi Lo ya está conmigo e incluso mi padre parece estar tranquilo.$b$bNunca lo admitiría delante de mí, pero creo que a mi padre le gusta Lo.' WHERE `ID`=58125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사 원더브루요. 만나서 반갑소.$b$b난 맥주를 만드는 데 사용할 최고의 재료를 찾아 비취 숲 전역을 떠돈다오.$b$b새벽의 꽃에 엉덩이를 깔고 앉아버린, 저 잘나 빠진 골든드래프트 집안과는 다르단 말이오.$b$b그 집안은 대량 생산을 위해 커다란 양조장을 만들었소. 뭐, 사실, 그것도 나쁘지는 않소. 개성 없는 싸구려 저질 술이 당신 입맛에 맞는다면 말이오.', `MaleText_loc4`='酒仙游酒愿意为你效劳。$b$b我游历翡翠林，只是为了寻找最好的酿酒材料。$b$b我可不像晨芳园里那个傲慢自大的金酿家族。$b$b他们只会用他们大型的酿酒厂进行批量生产。其实他们的酒也还行啦，如果你爱喝泔水的话。', `MaleText_loc5`='釀酒大師蕩酒，聽候差遣。$b$b我在翠玉林裡跋涉，只為我的酒挑選最好的原料。$b$b我才不像晨綻的那個高貴又偉大的金流家呢。$b$b他們用大酒廠來量產。是沒什麼不好，你知道的，假如你喜歡喝餿水的話。', `MaleText_loc7`='Maestro cervecero Pócima Errante a tu servicio.$b$bViajo por El Bosque de Jade en busca de los ingredientes más exquisitos para mis bebidas.$b$bA diferencia de los ricos y poderosos Brisa Dorada de Floralba.$b$bEllos dedican su enorme cervecería a la producción en masa. Lo cual está bien... si te gusta beber agua de alcantarilla.' WHERE `ID`=58126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원더브루 집안과 골든드래프트 집안이 사돈을 맺는다니? 기분 나쁜 일이지만... 사실 저 완고한 페이지가 이 소식을 듣고 얼마나 기분이 나빴을지 생각하니, 이것도 나름 유쾌한 일이군.$b$b적어도 당신이 우리 아들은 행복하게 해 준 것 같소. 고맙소, $p.', `MaleText_loc4`='游酒家和金酿家联姻？我当然很生气，不过一想到老佩吉听到这个消息时会多么愤怒，我又有点儿高兴了。$b$b至少你让我儿子高兴了起来。谢谢你，$p。', `MaleText_loc5`='蕩酒家和金流家結親?這對我是一種羞辱，但想到老佩吉聽到時會有多惱怒，這又變成一種娛樂。$b$b至少你似乎幫我的孩子找到快樂。謝謝你，$p。', `MaleText_loc7`='¿Un Pócima Errante casándose con una Brisa Dorada? A mí me ofendería, pero resultaría divertido ver cómo se lo toma el viejo Peiji cuando se entere de la noticia.$b$bAl menos parece que has hecho feliz a mi hijo. Gracias, $p.' WHERE `ID`=58127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시라를 찾아야겠어!', `MaleText_loc4`='我得找到塞拉！', `MaleText_loc5`='我得找到錫拉!', `MaleText_loc7`='¡Tengo que encontrar a Syra!' WHERE `ID`=58128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다. 이제 시작하자.', `MaleText_loc4`='谢谢你。让我们开始吧。', `MaleText_loc5`='謝謝你。讓我們開始吧。', `MaleText_loc7`='Gracias. Podemos comenzar.' WHERE `ID`=58129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로! 이제 출발할 시간이다! 대체 어디 간 거니?', `MaleText_loc4`='罗！我们要出发了。你去哪儿了？', `MaleText_loc5`='小樓!我們走了。你之前去哪裡了?', `MaleText_loc7`='¡Lo! Nos vamos. ¿Dónde te has metido?' WHERE `ID`=58130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼께서 입을 여셨다. 생각할 것이 많구나.', `MaleText_loc4`='流水之魂告诫我，我还需要仔细思量。', `MaleText_loc5`='魂靈開口了。我有很多事得思索。', `MaleText_loc7`='Los espíritus han hablado. Tengo mucho que reflexionar.' WHERE `ID`=58131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하얀 싹을 찾으려면, 우리에게 전해 내려오는 고대의 마법을 불러내야 하네. 그러려면, 우선 꿈결 맥주를 만들어야 하고.', `MaleText_loc4`='想要找到白卒的话，我们得依靠我们族人的远古魔法。为此，我们首先得做出一瓶洄梦仙酒。', `MaleText_loc5`='要找到你的白棋，必須運用我們人民的一種古老魔法。為此，我們需要先創造出一份夢幻之釀。', `MaleText_loc7`='Para encontrar tu peón blanco debemos invocar la magia ancestral de mi pueblo. Para ello, tenemos que elaborar primero un brebaje de ensueño.' WHERE `ID`=58132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s|1이;가; |cFFFF0000|Hspell:113364|h[책 불태우기]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s开始施放|cFFFF0000|Hspell:113364|h[焚烧书籍]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s開始施放|cFFFF0000|Hspell:113364|h[焚書烈焰]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warlock_inferno.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:113364|h[Quemador de libros]|h|r!' WHERE `ID`=58133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재료가 강해지면 강해질수록, 맥주의 마법 역시 강해지지.', `MaleText_loc4`='酿酒的材料越强大，酿出的酒中蕴含的魔法也就越强大。', `MaleText_loc5`='成分越強，夢幻之釀的法力就越強。', `MaleText_loc7`='Cuanto más fuertes sean los ingredientes, más potente será la magia de la bebida.' WHERE `ID`=58134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈결 맥주가 자네를 깊은 명상에 빠지게 할 걸세. 그러면 자네 마음의 눈이 가장 큰 문제에 대한 해답을 찾을 거야.', `MaleText_loc4`='洄梦仙酒会让你进入深度的冥想，你的心灵之眼会帮你解答最大的疑问。', `MaleText_loc5`='夢幻之釀會讓你進入深層的冥想狀態，你的心智之眼會為你最大的問題找出答案。', `MaleText_loc7`='El brebaje de ensueño te sumergirá en un profundo estado de meditación. Tu imaginación encontrará las respuestas a tus mayores preguntas.' WHERE `ID`=58135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에는 우리가 아직 밝혀내지 못한 힘이 숨어 있네. 조화와 지혜를 통해 이런 마음의 힘을 해방할 수도 있지.$B$B꿈결 맥주는 일시적으로 만물을 내다볼 수 있는 상태로 자네를 이끄는 도구일 뿐이네.', `MaleText_loc4`='我们的心灵具有一种尚未发现、难以言喻的力量。凭借着智慧和平衡，我们就有可能施放出这种心灵之力。$B$B洄梦仙酒只是一个工具，能够帮你暂时进入这种全视状态。', `MaleText_loc5`='心智蘊含著我們仍未參透的未知力量。透過平衡與睿智，或許有可能解鎖其中的力量。$B$B夢幻之釀只是幫助我們短暫地創造出這種全知狀態的工具。', `MaleText_loc7`='La mente posee unos poderes que aún no hemos descubierto. A través del equilibrio y la sabiduría, se pueden desbloquear estos poderes mentales.$b$bEl brebaje de ensueño solo es un instrumento que favorece temporalmente un estado de visión profundo.' WHERE `ID`=58136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러죠.', `MaleText_loc4`='当然。', `MaleText_loc5`='當然。', `MaleText_loc7`='Desde luego.' WHERE `ID`=58137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈결 맥주의 제조법은 오랜 세월 동안 전해 내려왔네.', `MaleText_loc4`='洄梦仙酒是多年以来流传至今的古老配方。', `MaleText_loc5`='夢幻之釀是一種傳承了千年的古老配方。', `MaleText_loc7`='El brebaje de ensueño es una antigua receta que se ha transmitido a lo largo de generaciones...' WHERE `ID`=58138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들이여, 공격!', `MaleText_loc4`='弓箭手，放箭！', `MaleText_loc5`='弓箭手，放箭!', `MaleText_loc7`='¡Arqueros, ataquen!' WHERE `ID`=58139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시만 기다리게.', `MaleText_loc4`='请稍后。', `MaleText_loc5`='請稍等片刻。', `MaleText_loc7`='Espera un momento.' WHERE `ID`=58141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭풍이 몰려오고 있어요! 준비하세요.', `FemaleText_loc4`='风暴来袭！做好准备。', `FemaleText_loc5`='風暴開始了!準備好。', `FemaleText_loc7`='¡Ya empieza la tormenta! Prepárense.' WHERE `ID`=58142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맥주통에 불이 붙으면 꺼 주세요.', `FemaleText_loc4`='酒桶要是着起火来，我需要你帮忙灭火。', `FemaleText_loc5`='如果酒桶著火，我需要你幫忙滅火。', `FemaleText_loc7`='Si los barriles empiezan a arder, tienen que ayudarme a apagarlos.' WHERE `ID`=58143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벼락을 조심하세요!', `FemaleText_loc4`='小心闪电攻击！', `FemaleText_loc5`='小心雷擊!', `FemaleText_loc7`='¡Cuidado con los rayos!' WHERE `ID`=58144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...사우록? 여기서 뭘 하는 거지? 놈들을 쫓아 주세요!', `FemaleText_loc4`='……蜥蜴人？他们在这儿干什么？把他们赶走！', `FemaleText_loc5`='...薩烏洛克?他們在這做什麼?別讓他們靠近!', `FemaleText_loc7`='... ¿Saurok? ¿Qué hacen aquí? ¡Que no se acerquen!' WHERE `ID`=58145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭풍이 생각보다 더 심하네요! 조심하세요!', `FemaleText_loc4`='呦，风暴比我想的还要猛烈！小心！', `FemaleText_loc5`='唷，風暴比我想像的更猛烈!小心!', `FemaleText_loc7`='¡Uau, la tormenta es más intensa de lo que creía! ¡Tengan cuidado!' WHERE `ID`=58146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐 거기! 보고만 있지 말고 이 소환사들 좀 처리해줘!', `FemaleText_loc4`='说你呢！别光站着不动，解决掉这些召唤者！', `FemaleText_loc5`='你們幾個!有點用處，去料理那些召喚者!', `FemaleText_loc7`='¡Ustedes! ¡Hagan algo útil y encárguense de los invocadores!' WHERE `ID`=58148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐니 뭐니 해도 맥주통이 제일 중요해요. 타지 않게 해 주세요!', `FemaleText_loc4`='关键在于那些酒桶——别让它们起火！', `FemaleText_loc5`='酒桶至關重大，別讓它們燒起來!', `FemaleText_loc7`='Lo importante son los barriles: ¡procuren que no se quemen!' WHERE `ID`=58150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맥주통에 붙은 불을 꺼 주세요!', `FemaleText_loc4`='快把酒桶的火扑灭！', `FemaleText_loc5`='撲滅酒桶的火!', `FemaleText_loc7`='¡Apaguen esos barriles!' WHERE `ID`=58151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭풍이 점점 거세지고 있어요! 맥주통을 지켜 주세요...', `FemaleText_loc4`='这场风暴已经肆虐得失去控制了！保护酒桶……', `FemaleText_loc5`='這風暴已經失去控制了!保護酒桶的安全...', `FemaleText_loc7`='¡Esta tormenta está fuera de control! Mantén a salvo los barriles...' WHERE `ID`=58152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모험가님 덕분에 해독제는 충분해요.', `MaleText_loc4`='多亏$p，现在解毒剂应该够用了。', `MaleText_loc5`='多虧$p這位冒險者，現在抗毒藥劑應該夠了。', `MaleText_loc7`='Debería haber antiveneno de sobra, gracias a su osadía.' WHERE `ID`=58154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망을 떠올리지 마세요, 코로. 제 고향에는 이런 말이 있죠. "해 뜨기 직전이 가장 어둡다."', `MaleText_loc4`='不要心怀绝望，科洛。在我家乡那边有句名言：黎明前夕总是最黑暗的。', `MaleText_loc5`='別那麼悲觀，可羅。我聽過一句諺語:黎明前總是最黑暗的。', `MaleText_loc7`='Ten paciencia, Koro. En mi tierra tenemos un dicho: "La hora más oscura es la que precede al alba".' WHERE `ID`=58155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인, 이리 와 주시겠습니까? 당분간은 사우록이 잠잠할 듯하니, 다음 행보를 결정해야 합니다.', `MaleText_loc4`='安度因，一起行动吗？蜥蜴人的威胁已经暂时解除，我们该讨论下一步行动了。', `MaleText_loc5`='安杜因，你要加入我們嗎?趁薩烏洛克的威脅暫時解除的當下，我們該討論下一步行動了。', `MaleText_loc7`='Anduin, ¿puedes acercarte? Ahora que la amenaza saurok está controlada, es hora de preparar el siguiente paso.' WHERE `ID`=58156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중과 휴식을 통해 균형을 유지하십시오.', `MaleText_loc4`='集中精神、放松心情，保持你的身心平衡。', `MaleText_loc5`='用專注和放鬆來維持你的平衡。', `MaleText_loc7`='Concéntrate y relájate para mantener el equilibrio.' WHERE `ID`=58157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 분 모두 감사합니다. 우리에게 늘 희망의 상징이셨던 주학 님께서 안 계시니, 저마저도 희망을 잃을까 두렵습니다.', `MaleText_loc4`='谢谢，谢谢你们两位。对我的族人来说，朱鹤始终象征着希望，没有了他，就连我的思绪也开始变得晦暗。', `MaleText_loc5`='謝謝，謝謝你們兩個。紅鶴一直是我們人民希望的象徵，但是，當祂不在的時候，我擔心就連我的思想也會變得黑暗。', `MaleText_loc7`='Os lo agradezco. La Grulla Roja siempre ha sido un símbolo de esperanza para nosotros, pero en su ausencia hasta mis pensamientos se oscurecieron.' WHERE `ID`=58158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞는 말씀입니다. 나이에 비해 정말 현명하시군요. 이 일이 마무리되면, 당신이 살던 곳에 대해 더 알고 싶습니다.', `MaleText_loc4`='很好。在你的言辞间我看到了超乎年龄的睿智。等这一切结束之后，我很愿意进一步了解你的来历。', `MaleText_loc5`='你說得沒錯。你說的話擁有超越年齡的智慧。如果我們能平安度過這個難關，我很想知道關於你故鄉的事。', `MaleText_loc7`='Cierto. Hablas con sabiduría, a pesar de tu juventud. Si salimos de esta, quiero que me cuentes más cosas sobre tu hogar.' WHERE `ID`=58159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 웃습니다.', `MaleText_loc4`='%s轻声笑了起来。', `MaleText_loc5`='%s輕笑著。', `MaleText_loc7`='%s ríe entre dientes.' WHERE `ID`=58160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나방전사 해먹기 정말 힘들군!', `MaleText_loc4`='真是巧夺天工！', `MaleText_loc5`='極限縫紉!', `MaleText_loc7`='¡Costura extrema!' WHERE `ID`=58161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 안 돼!', `MaleText_loc4`='现在不是时候！', `MaleText_loc5`='現在不行!', `MaleText_loc7`='¡Ahora no!' WHERE `ID`=58163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 덩치 좀 보십시오! 틀림없이 이번 주에 본 나방 중 가장 큰 놈일 겁니다.', `MaleText_loc4`='看那家伙多大啊！它一定是我这星期见过最大的飞蛾。', `MaleText_loc5`='看看那玩意兒的尺寸!這是我整個星期以來看到最大的蛾了。', `MaleText_loc7`='¡Mira el tamaño de esa cosa! Sin duda es la polilla más grande que he visto en toda la semana.' WHERE `ID`=58165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전세를 역전시키기 위해 당신 같은 $c|1이;가; 꼭 필요하던 참이었습니다.', `MaleText_loc4`='我们正需要像你这样富有才干的$c，帮忙扭转战局。', `MaleText_loc5`='像你這樣的$c正是我們扭轉戰局需要的。', `MaleText_loc7`='$gUn:Una; $c de tu categoría es exactamente lo que necesitamos para obtener ventaja en la batalla.' WHERE `ID`=58167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s|1이;가; |cFFFF0000|Hspell:113653|h[거대 용의 숨결]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s开始施放|cFFFF0000|Hspell:113653|h[巨龙之息]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s開始施放|cFFFF0000|Hspell:113653|h[強效龍之吐息]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_head_dragon_01.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:113653|h[Aliento de dragón superior]|h|r!' WHERE `ID`=58168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책 불태우기에 닿자, 책들이 화염이 되어 타오르기 시작합니다.', `MaleText_loc4`='被“焚烧书籍”击中，书燃起了火焰。', `MaleText_loc5`='被焚書烈焰擊中後，書本猛烈燃燒了起來。', `MaleText_loc7`='Los libros estallan en llamas debido a Quemador de libros.' WHERE `ID`=58169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 매끈피부! 열심히 뛰어 봤자, 넌 내 아침밥이야!', `MaleText_loc4`='跑吧跑吧，光板儿！要是被我抓住，我就把你吞进肚子里去！', `MaleText_loc5`='跑啊，滑魚!我把你拿來當早餐吃!', `MaleText_loc7`='¡Korre, manduko! ¡Yo desayuna mandukos como tú!' WHERE `ID`=58170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 스톰윈드의 왕자, 안두인 린이다. 여기서 죽을 수는 없어. 이렇게는 안 돼!', `MaleText_loc4`='我安度因·乌瑞恩是暴风城的王子。我绝不能死在这里。绝不！', `MaleText_loc5`='我是安杜因·烏瑞恩，暴風城的王子。我不會在這裡，像這樣死去!', `MaleText_loc7`='Soy Anduin Wrynn, Príncipe de Ventormenta. No moriré aquí. ¡No así!' WHERE `ID`=58171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 아버지께 되돌려보내려고 오신 거라면 먼저 우리 주변을 둘러봐 달라고 부탁하고 싶군요. 이렇게 도움이 필요한 이들을 내버려둔 채 떠나고 난 뒤에도 우리가 얼라이언스라고 할 수 있겠습니까?', `MaleText_loc4`='如果你是来带我回去见我父亲的，那我必须要让你先环顾周围——我们真能在这些人急需帮助的时候扬长而去，还声称自己是代表联盟而来吗？', `MaleText_loc5`='如果你要把我帶回我父親的身邊，我必須要求你先看看我們四周－我們真能在這些人最需要的時候離開他們嗎，並聲稱自己代表著聯盟嗎?', `MaleText_loc7`='Si has venido a devolverme junto a mi padre, debo pedirte que mires primero a mi alrededor; ¿acaso podemos abandonar a esta gente en tiempos de necesidad y seguir diciendo que representamos a la Alianza?' WHERE `ID`=58172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c님, 우리 얼라이언스는 의견이 서로 분분하겠지만, 여기서는 호드나 얼라이언스 모두가 손님입니다.$B$B당신도 이미 겪어봤겠지만, 판다렌들은 제게도 극진한 환대와 존경을 보여줬습니다. 그리고 그들은 지금 도움이 필요합니다.$B$B호드는 명예 없인 아무것도 아닙니다. 당신이 명예가 뭔지 안다면, 지금의 우리 논쟁을 다음으로 미뤄둬야 할 겁니다.', `MaleText_loc4`='在我们的族人之间存在分歧，$c，可我们都是这里的宾客。$B$B熊猫人热情尊敬地厚待我们，我敢肯定你也受到了同样的待遇，现在，他们需要我们的帮助。$B$B部落也并非没有荣誉感。如果你也知道荣誉为何物，那你应该明白，我们的恩怨可以改日再行了结。', `MaleText_loc5`='$c，我們人民有他們之間的差異，但我們在這裡都是客人。$B$B熊貓人尊敬並且熱情地款待我，我相信他們對你也是一樣，而現在他們需要我們幫忙。$B$B部落是注重榮譽的。如果你明白榮譽是什麼，你就知道該在此時放下我們之間的歧見。', `MaleText_loc7`='Nuestra gente tiene sus diferencias, $c, pero todos somos invitados en este lugar.$B$BLos pandaren me han mostrado una gran hospitalidad y respeto, que seguramente tú también habrás recibido, y ahora necesitan nuestra ayuda.$B$BLa Horda no es tal sin el honor. Si conoces el honor, sabrás dejar nuestras disputas para otro momento.' WHERE `ID`=58173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 쏴라! 모두 처치해!', `MaleText_loc4`='继续放箭！一个也别想跑！', `MaleText_loc5`='繼續放箭! 不留活口', `MaleText_loc7`='¡Sigan disparando! ¡Que no escape ni uno!' WHERE `ID`=58174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 처치했군. 봐주지 마라!', `MaleText_loc4`='又干掉一个。再接再厉！', `MaleText_loc5`='又幹掉一個，保持下去!', `MaleText_loc7`='Ha caído otro. ¡No paren!' WHERE `ID`=58175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까.$b$b저는 샤이 클리프와처라고 합니다.$b$b다른 이들이 저보고 절벽을 감시하라고 하더군요.$b$b어떨 때는 어린이들이 겁 없는 마음에 여기 올라오고, 다 큰 어른들도 호기심에 종종 올라옵니다.$b$b제가 그들에게 하는 말은 이렇습니다. 절벽은 슬픈 곳이고, 밀림은 더욱더 슬픈 곳이라고 말입니다.$b$b밧줄을 타고 내려갈 수 있지만, 그곳이 아주 슬픈 곳이라는 건 알아두십시오.', `MaleText_loc4`='你好。$b$b我是沙埃。$b$b他们让我守望悬崖。$b$b有时会有初生牛犊不怕虎的幼仔跑到这里来。有时也会有大人出于好奇心前来。$b$b我要把已经告诉他们的话重复给你听。悬崖很危险，那片丛林则更加危险。$b$b你可以用绳索下去，但我要提醒你，这是个非常危险的地方。', `MaleText_loc5`='哈囉。$b$b我的名字叫做夏。$b$b他們叫我去看守峭壁。$b$b有時候小孩子為了打賭跑來這裡。有時候大人因為好奇而來。$b$b我會把告訴他們的話也告訴你。峭壁充滿了悲傷，而叢林裡的悲傷更是有過之而無不及。$b$b你可以利用繩索下去那地方，但你要明瞭它是個令人非常傷心的場所。', `MaleText_loc7`='Hola.$b$bMi nombre es Shai.$b$bMe dicen que observe el acantilado.$b$bA veces, los cachorros se acercan por atrevimiento. Otras veces, los adultos vienen porque son curiosos.$b$bTe diré lo que les digo a ellos. Los acantilados son tristes, y la jungla lo es más aún.$b$bPuedes descender con la cuerda, pero debes saber que es un lugar muy triste.' WHERE `ID`=58177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을 거둔 실험체를 모두 처치해 탈출하십시오!', `MaleText_loc4`='击败所有作废的试验样本来逃脱！', `MaleText_loc5`='打倒所有過期的實驗體才有辦法逃跑!', `MaleText_loc7`='¡Derrota a los sujetos de prueba caducados para escapar!', `FemaleText_loc1`='숨을 거둔 실험체를 모두 처치해 탈출하십시오!', `FemaleText_loc4`='击败所有作废的试验样本来逃脱！', `FemaleText_loc5`='打倒所有過期的實驗體才有辦法逃跑!', `FemaleText_loc7`='¡Derrota a los sujetos de prueba caducados para escapar!' WHERE `ID`=58178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주학 님과 함께 보낸 시간은 길지 않았지만, 저는 그분의 지도로 정말 많은 것을 배웠습니다.$B$B이 "샤"라는 적이 가진 기운은 우리가 예전에 접했던 것과는 전혀 다릅니다. 정서적인 혼란에서 비롯된 물질적 발현이지요. 수 세기 동안 이 대륙에서 자라나 왔습니다.$B$B이제 이 슬픈 감정의 기운은 생명이 있고 감정을 느끼는 대상을 찾아 숙주로 삼으려고 하고 있습니다.$B$B판다렌을 치유해 샤를 제압하지 않으면, 놈들은 이 대륙뿐만 아니라 온 세상을 엄습할 겁니다!', `MaleText_loc4`='我与朱鹤相处的时间很短，但我却在他的指导下收获良多。$B$B这个敌人——这股名为“煞”的能量，不同于我们以往面对过的任何敌手。它是情绪波动的物质表现，在大地里滋长了几个世纪。$B$B这股情绪能量现在已经喷薄而出，寻找富有情感的活人宿主寄居其中。$B$B如果我们不帮助熊猫人镇压住煞，煞很可能要袭遍整片大陆，甚至是整个世界！', `MaleText_loc5`='我和紅鶴相處的時間很短暫，但我在他的保護下學到一件很重要的事。$B$B這個敵人...這種稱之為「煞」的能量，跟我們以前所面對的完全不同。這是一種心靈騷亂所引發的物理現象，在這塊大地裡已封存了幾個世紀。$B$B這種心靈能量現在爆發出來，四處尋找可寄居的宿主。$B$B煞的威脅已瀰漫了整個大陸，如果我們不幫助熊貓人把煞壓制下去，有可能會影響全世界!', `MaleText_loc7`='He pasado poco tiempo con la Grulla Roja, pero he aprendido mucho bajo su tutela.$B$BEste enemigo, esta energía "sha", no se parece a nada a lo que nos hayamos enfrentado anteriormente. Es la manifestación física del tormento emocional encerrado en la tierra durante siglos.$B$BEsta energía emocional ha estallado en busca de vida, tanteando a huéspedes donde residir.$B$B¡El sha amenaza con arrasar todo el continente, posiblemente el mundo entero, si no ayudamos a los pandaren a acabar con él!' WHERE `ID`=58180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이여 검을 준비하라!', `MaleText_loc4`='准备好就接刀！', `MaleText_loc5`='準備好戰鬥!', `MaleText_loc7`='¡Espadas preparadas!' WHERE `ID`=58181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 완료!', `MaleText_loc4`='开始了！', `MaleText_loc5`='開始啦!', `MaleText_loc7`='¡Ahora veréis!' WHERE `ID`=58182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골든드래프트 님, 부디 따님 시라와 결혼할 수 있게 허락해 주십시오.', `MaleText_loc4`='金酿先生，我在此恳请您将您的女儿塞拉嫁给我。', `MaleText_loc5`='金流先生，我謙卑地請求您允許我和您的女兒錫拉成親。', `MaleText_loc7`='Señor Brisa Dorada, te pido con la mayor humildad la mano de tu hija Syra.' WHERE `ID`=58183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 사랑하는 것은 그 이름이 아닙니다. 시라입니다. 그녀는 제가 만나본 중에서 가장 친절하고, 상냥하고, 예쁜 판다렌입니다.', `MaleText_loc4`='我感兴趣的不是她的名字，而是她的人。她是我见过的最善良、最温柔、最美丽的人。', `MaleText_loc5`='我不是覬覦她的名字。我感興趣的是她本人。她是我所見過最仁慈、最和善、最美麗的人。', `MaleText_loc7`='No es su apellido lo que me interesa, sino ella. Es la pandaren más amable, buena y bella que he conocido nunca.' WHERE `ID`=58184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 이제, 허락해 주신다면, 따님의 손을 잡고 싶습니다.', `MaleText_loc4`='是的。那么现在，在您的允许下，我想牵起您女儿的手。', `MaleText_loc5`='是的。現在，在您的允許下，我想要和您的女兒攜手共度一生。', `MaleText_loc7`='Sí. Y ahora, con tu permiso, me gustaría pedirte la mano de tu hija.' WHERE `ID`=58185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기의 물은 이제 네가 지켜야 한다...', `MaleText_loc4`='谷里的溪水现在就由你来守护了……', `MaleText_loc5`='保護谷地中的水成了你的責任...', `MaleText_loc7`='Ahora te toca a ti proteger las aguas del valle...' WHERE `ID`=58186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 지하 깊은 곳에서 나타났다. 그것은 여전히, 굶주리고 있다...', `MaleText_loc4`='黑暗来自于地下深处，它仍旧渴望着……', `MaleText_loc5`='這黑暗來自土地的深處。它依舊感到飢餓...', `MaleText_loc7`='La oscuridad emergió de las raíces de la tierra y aún está hambrienta...' WHERE `ID`=58187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들아! 무슨 짓이냐! 그 아이는 골든드래프트 집안의 딸이다.', `MaleText_loc4`='儿子！你在干什么！她是金酿家族的人。', `MaleText_loc5`='兒子!你在做什麼!她可是金流家的人。', `MaleText_loc7`='¡Hijo! ¡Qué estás haciendo! Es una Brisa Dorada.' WHERE `ID`=58188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있네요. 말씀드렸잖아요. 전 누구든, 무엇이든 찾을 수 있어요.', `MaleText_loc4`='他们在这儿呢。看见了吧，我早就说了，不管是谁，不管是什么东西，我都能找得到。', `MaleText_loc5`='他們在這裡。看吧，就跟你說我能找到任何人或東西。', `MaleText_loc7`='Aquí están. ¿Lo ves? Te dije que podía encontrar lo que fuese o a quien fuese.' WHERE `ID`=58189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 정말 멋졌어요! 이제 뭘 하실 건가요, $p 님? 호젠과 진위를 화해시키기라도 하실 건가요?', `MaleText_loc4`='哇！真是太神奇了。接下来是什么，$p？你觉得你能让猢狲和锦鱼人和睦共处吗？', `MaleText_loc5`='哇!那真是太棒了。接著還有什麼，$p?你是不是要讓猴人和錦魚人變成朋友?', `MaleText_loc7`='¡Guau! Impresionante. ¿Qué será lo siguiente, $p? ¿Crees que puedes hacer que los hozen y los jinyu se lleven bien?' WHERE `ID`=58190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기의 노래는 벽에 걸려 있습니다. 가져가십시오. 하늘이 절 부르는 소리가 들리는군요. 감사합니다...', `MaleText_loc4`='《溪山吟》就挂在墙上。拿去吧。我听到了上天的召唤，谢谢你……', `MaleText_loc5`='谷之歌就掛在牆上。將它拿去吧。我聽到天國的呼喚，謝謝你...', `MaleText_loc7`='La Canción del Valle cuelga de la pared. Llévatela. Oigo la llamada de los Celestiales. Gracias...' WHERE `ID`=58191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 영원꽃 골짜기라는 곳이 점점 더 궁금해지네요. 아무래도 제가 직접 가봐야겠어요.', `MaleText_loc4`='这个锦绣谷真是越来越有趣了，我一定要亲眼去看看。', `MaleText_loc5`='這座恆春谷越來越耐人尋味了。看來我非得親自看看不可。', `MaleText_loc7`='Ese Valle de la Flor Eterna me intriga cada vez más. Tendré que verlo con mis propios ojos.' WHERE `ID`=58192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런, 손님들이 오신 것 같군! 친구들이냐, 보스?', `MaleText_loc4`='宝贝儿，好像有客人来了！是你的朋友吗，沃斯？', `MaleText_loc5`='親愛的，有人來參觀了!是你的朋友嗎，佛斯?', `MaleText_loc7`='¡Vaya! Parece que tenemos visita. ¿Son amigos tuyos, Voss?' WHERE `ID`=58193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들의 죽음은 내 소환사들을 더 강하게 할 뿐이다! 잘 봐라!', `MaleText_loc4`='他们的死亡只会令我的召唤者变得更强！看吧！', `MaleText_loc5`='他們的死亡只會讓我的召喚者更為強大!看好了!', `MaleText_loc7`='¡Sus muertes no harán más que aumentar el poder de mis invocadores! ¡Observen!' WHERE `ID`=58194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러냐, 보스? 이제 좀 지쳐?', `MaleText_loc4`='怎么了，沃斯，你累了吗？', `MaleText_loc5`='怎麼啦，佛斯，你累了嗎?', `MaleText_loc7`='¿Qué pasa, Voss? ¿Te estás cansando?' WHERE `ID`=58195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아름답지 않나? 이 살점과 뼈, 그리고 영혼의 향연!', `MaleText_loc4`='这难道不美么？交织着血肉、骨骼和灵魂。', `MaleText_loc5`='是否很美呢?血肉、骨頭跟靈魂交織在一起。', `MaleText_loc7`='El entrelazado de la carne, los huesos y el alma... ¿No es hermoso?' WHERE `ID`=58196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 아름다워, 보스. 최근에 거울을 본 적 있나?', `MaleText_loc4`='你也很美啊，沃斯。最近照镜子了吗？', `MaleText_loc5`='你也很美呀，佛斯。你最近照過鏡子了嗎?', `MaleText_loc7`='Tú también eres hermosa, Voss. ¿Te has mirado en el espejo últimamente?' WHERE `ID`=58197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘야, 너에게 내려진 이 축복을 순순히 받아들이거라.', `MaleText_loc4`='宝贝儿，你应该将这份礼物视作对你的恩赐。', `MaleText_loc5`='親愛的，好好接受這份贈與你的禮物吧。', `MaleText_loc7`='Querida, deberías aceptar el don que te han concedido.' WHERE `ID`=58198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 보스. 운명이 널 기다린다.', `MaleText_loc4`='来吧，沃斯，你的命运在召唤你。', `MaleText_loc5`='來吧，佛斯，你的命運正等著你。', `MaleText_loc7`='Ven, Voss. Tu destino te aguarda.' WHERE `ID`=58199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동족의 영혼을 동족에게 먹이는 거냐? 역겨운 놈.', `FemaleText_loc4`='你将他们的灵魂喂给他们的同族？恶心。', `FemaleText_loc5`='你把他們的靈魂餵給他們的弟兄? 你真是噁心。', `FemaleText_loc7`='¿Los alimentas con las almas de sus hermanos? Estás enfermo.' WHERE `ID`=58200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영영 너 같은 족속들을 사냥할 테다, 영원히!', `FemaleText_loc4`='我永远也不会放过你的同类，死灵法师。永远。', `FemaleText_loc5`='我絕不會停止追殺你們這些死靈法師。絕不。', `FemaleText_loc7`='Nunca dejaré de dar caza a los de tu calaña, nigromante. Nunca.' WHERE `ID`=58201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목에 칼이 들어와도 그렇게 떠들어댈 수 있을지 한 번 보자!', `FemaleText_loc4`='我倒是要看看你死了以后还能怎么为非作歹！', `FemaleText_loc5`='等我割斷你的喉嚨，看看你死後是否還那麼愜意!', `FemaleText_loc7`='¡Ya veremos si disfrutas tanto de la muerte cuando te haya degollado!' WHERE `ID`=58202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분들께서 허락해 주셨다고?!', `MaleText_loc4`='他们同意了？', `MaleText_loc5`='他們同意了?!', `MaleText_loc7`='¡¿Han accedido?!' WHERE `ID`=58203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 페이지. 나도 자네처럼 이 일이 썩 마음에 들지는 않지만, 시조님들의 축복은 정말 명예로운 일이라고.', `MaleText_loc4`='算了吧，佩吉。我跟你一样不情愿，可族长的祝福是一种荣誉。', `MaleText_loc5`='好了佩吉。我和你一樣不喜歡這個主意，但我們必須尊重潘達族王的祝福。', `MaleText_loc7`='Vamos, Peiji. A mí no me agrada la idea más que a ti, pero las bendiciones de los pandriarcas son honorables.' WHERE `ID`=58204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 그렇게 생각하네. 일단 이 아이들을 새벽의 꽃으로 데려가지.', `MaleText_loc4`='我也一样。现在让我们把这些孩子带回晨芳园吧。', `MaleText_loc5`='同感。現在讓我們把這些孩子帶回晨綻吧。', `MaleText_loc7`='Bueno, llevemos a los chicos de vuelta a Floralba.' WHERE `ID`=58205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야?! 터무니없는 소리군.', `MaleText_loc4`='什么？！这太荒谬了。', `MaleText_loc5`='什麼?!這簡直荒謬。', `MaleText_loc7`='¿Cómo? Esto es ridículo.' WHERE `ID`=58206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 딸 시라가 원더브루 따위와 어울리는 것은 허락할 수 없다.', `MaleText_loc4`='我的塞拉一定不会受到游酒家族的待见。', `MaleText_loc5`='我的錫拉絕不能跟蕩酒家的人在一起。', `MaleText_loc7`='A mi Syra NO la verán con un Pócima Errante.' WHERE `ID`=58207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 그... 나는...', `MaleText_loc4`='那么……呃……我……', `MaleText_loc5`='就是...呃...我...', `MaleText_loc7`='En fin... hmm... Yo...' WHERE `ID`=58208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 이왕 이렇게 된 이상 어쩔 수 없지. 하지만 그렇다고 이 일이 마음에 든다는 건 아니네. 자네도 마찬가지고.', `MaleText_loc4`='好吧。已经发生的事就不用再追究了。可你别指望我会喜欢这桩婚事，或者是你，凯。', `MaleText_loc5`='好吧。木已成舟。但別以為我會喜歡上這種結果。或是喜歡你，凱。', `MaleText_loc7`='De acuerdo. Lo hecho, hecho está. Pero no pienses que algún día me acabará gustando esta situación ni tú, Kai.' WHERE `ID`=58209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요, 아버지. 로는 저를 위해 시조님들과도 결투를 했어요. $p 님이 용사가 되어 도와주시긴 했지만, 결국 그분들도 허락해 주셨고요.', `FemaleText_loc4`='不，父亲，我会的。罗甚至愿意为了我去挑战族长，连$p都支持我们，他们不会不同意的。', `FemaleText_loc5`='不，父親，我會的。小樓願意為了我和潘達族王戰鬥。最後雖然得請$p擔任我們的勇士，但他們同意了。', `FemaleText_loc7`='No, padre. Lo estaba dispuesto a luchar contra los pandriarcas por mí. Al final fue $p quien se enfrentó a ellos, pero nos dieron su consentimiento.' WHERE `ID`=58210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 말, 후회하게 될 거다.', `FemaleText_loc4`='你会为多嘴付出代价。', `FemaleText_loc5`='你會為多嘴付出代價。', `FemaleText_loc7`='Pagarás por tu insolencia.' WHERE `ID`=58211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 저주로 또 다른 영혼이 악몽에 시달리게 할 순 없어.', `FemaleText_loc4`='我决不会让你用这个梦魇去荼毒另一个灵魂。', `FemaleText_loc5`='我絕不讓你再用這個夢魘詛咒下一個靈魂。', `FemaleText_loc7`='No dejaré que condenes otra alma a esta pesadilla.' WHERE `ID`=58212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망쳐라... 강령술사여... 내가 숨만 가다듬으면 넌 죽은 목숨이다.', `FemaleText_loc4`='跑吧……死灵法师……等我喘过气来，你就死定了。', `FemaleText_loc5`='跑吧...死靈法師...等我喘過氣來就是你的死期到了。', `FemaleText_loc7`='Huye, nigromante... Tu vida acabará en el momento en el que recupere el aliento.' WHERE `ID`=58213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 교활한 분이셨나?! 전혀 몰랐네!', `MaleText_loc4`='这个小骗子！真没想到他敢这么做！', `MaleText_loc5`='無恥的小混蛋!沒想到他還有這種本領!', `MaleText_loc7`='¡Bribón descarado! ¡No pensaba que fuera capaz de algo así!' WHERE `ID`=58214;
