UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 오래 살아남다니, 솔직히 놀랐다. 임시', `MaleText_loc4`='真没想到，他竟然坚持了那么久。', `MaleText_loc5`='我很驚訝他支撐了那麼久。', `MaleText_loc7`='Me sorprende que haya vivido tanto. PH' WHERE `ID`=58223;
