UPDATE `locales_broadcast_text` SET `MaleText_loc1`='표적을 방패로 써야 합니다!', `MaleText_loc4`='跟上，用护盾做掩护！', `MaleText_loc5`='跟上來，拿這個盾當做掩護!', `MaleText_loc7`='¡Continúa y usa el escudo para cubrirte!' WHERE `ID`=58228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘, 우리는 얼라이언스와 굳게 손을 맞잡았다! 오늘, 우리는 형제 자매가 되어 전진한다! 새로운 미래를 향해!', `MaleText_loc4`='今天，我们和联盟缔结友情！今天，我们如同兄弟姐妹般共同前行，驶向新的未来！', `MaleText_loc5`='今天，我們和聯盟建立起堅定的友誼!今天，我們以同胞的身分前進。前往我們嶄新的未來!', `MaleText_loc7`='¡Hoy hemos consolidado nuestra amistad con la Alianza! Hoy, seguimos nuestro destino como hermanos. ¡Por el nuevo futuro!' WHERE `ID`=58231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 어디로 가고 싶으십니까?', `MaleText_loc4`='你今天想去哪里游览？', `MaleText_loc5`='你今天想到哪裡?', `MaleText_loc7`='¿Adónde te gustaría viajar hoy?' WHERE `ID`=58232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽의 꽃으로 데려다 주십시오.', `MaleText_loc4`='我想去晨芳园走一走。', `MaleText_loc5`='我想要前往晨綻。', `MaleText_loc7`='Me gustaría viajar a Floralba.', `FemaleText_loc1`='새벽의 꽃으로 데려다 주세요.', `FemaleText_loc4`='我想去晨芳园走一走。', `FemaleText_loc5`='我想要前往晨綻。', `FemaleText_loc7`='Me gustaría viajar a Floralba.' WHERE `ID`=58233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러요! 거의 다 왔어요!', `MaleText_loc4`='万岁！我们成功了！', `MaleText_loc5`='萬歲!我們成功了!', `MaleText_loc7`='¡Hurra! ¡Lo hemos conseguido!' WHERE `ID`=58234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리알리아가 새 차원문을 만들고 싶어한단 말입니까? 정말 정신 나간 여자군요. 지난번에 생겼던 일을 벌써 잊어버렸답니까?$b$b뭐, 밸드린의 연구가 이런 형태의 함정 주변에서도 차원문을 열 방법을 알려주기는 했습니다만... 우리가 이곳으로 오려고 저도 지름길을 몇 번 거쳐왔을 겁니다.$b$b제게 시간을 조금만 더 주시면 야영지를 위한 차원문을 더 열 수 있겠군요.', `MaleText_loc4`='丽娅拉想让我开启新的传送门？那女人简直疯了。难道她已经忘记上次发生的事了？$b$b好吧，瓦尔德林的研究提供了几种绕开陷阱的可行方案。而我也许是走了点儿捷径才把我们带到这里来的。$b$b多给我些时间，我也许能召唤出另一个撤退传送门。', `MaleText_loc5`='賴奧莉亞要我做出一個新的傳送門?那女人瘋了。她忘記上次發生什麼事了嗎? $b$b嗯，費爾迪林的研究有提到繞過陷阱的可能方法。而我也許已找出解決方案了。$b$b給我足夠的時間，我或許能幫臨時營地召喚出另一個傳送門。', `MaleText_loc7`='¿Que Lyalia quiere que yo cree un nuevo portal? Esa mujer está loca. ¿Ya se le ha olvidado lo que pasó la última vez?$b$bEn fin, la investigación de Vaeldrin sugería algunas maneras de evitar trampas como esa, y puede que yo haya tomado un par de atajos para traernos hasta aquí.$b$bDame tiempo y podré invocar otro portal para el campamento.' WHERE `ID`=58235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가... 어쨌든 반대쪽으로 나왔군요. 정말 다행입니다.$b$b가보지 않았던 곳에 차원문을 만들어내는 건 절대 쉬운 일이 아닙니다.$b$b하긴 이게 쉬운 일이라면 모두 다 차원문을 열고 다니겠지요.', `MaleText_loc4`='噢天哪……我们到另一侧来了。这真让我欣慰。$b$b开启一道通往陌生地方的传送门可不是件容易的事啊。$b$b可要是容易的话，岂不是人人都能做到了。', `MaleText_loc5`='我的天啊...不知道怎麼搞的，我們居然成功穿越到另一邊了。我總算能鬆口氣。$b$b要創造一個傳送門把你傳送到以前從沒去過的地方，這可不是件容易的事。$b$b不過話又說回來了，如果這很簡單，那每個人都可以做了。', `MaleText_loc7`='Madre mía... no sé cómo, pero hemos conseguido llegar al otro lado. ¡Qué alivio!$b$bNo es fácil crear un portal hacia un lugar en el que nunca has estado.$b$bEn fin, si fuera fácil todo el mundo lo haría.' WHERE `ID`=58236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도난당한 물건 더미가 있는 곳에 폭죽통을 설치해야 합니다.', `MaleText_loc4`='你必须把焰火放在一堆被偷走的货物附近。', `MaleText_loc5`='你必須把煙火放在那堆偷來的貨物旁邊。', `MaleText_loc7`='Debes colocar los fuegos artificiales cerca de una pila de objetos robados.' WHERE `ID`=58237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='통을 채우는 동안 잠시만 쉬고 계세요.', `FemaleText_loc4`='你稍事休息，让我把桶准备好。', `FemaleText_loc5`='休息一下，等我準備桶子。', `FemaleText_loc7`='Descansen un segundo mientras preparo el barril.' WHERE `ID`=58238;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 준비됐나요? 가죠!', `FemaleText_loc4`='所有人都准备好了吗？出发咯！', `FemaleText_loc5`='大家都準備好了嗎?出發吧!', `FemaleText_loc7`='¿Todos listos? ¡Adelante!' WHERE `ID`=58239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 사우록이 또 몰려오네요. 사우록은 비가 왔다 하면 항상 높은 곳을 향하죠.', `FemaleText_loc4`='呵，小子，出现了更多蜥蜴人。雨水落下时，他们总是喜欢到高处去！', `FemaleText_loc5`='喔老天，更多薩烏洛克。他們總是在雨天試著佔據高地。', `FemaleText_loc7`='Vaya, más saurok. ¡Siempre buscan el terreno elevado cuando llegan las lluvias!' WHERE `ID`=58240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야만족들이 우리를 좋아하게 만들었다고?$b$b너 정말 $r 중에서는 보기 힘든 천재인가 봐!$b$b상상도 못할 일이라고...', `MaleText_loc4`='你居然能让那些野蛮人接受我们？$b$b你还真鬼才，$r！$b$b谁能想到……', `MaleText_loc5`='你成功讓這些蠻族喜歡上我們了?$b$b你一定是某種怪咖$r天才!$b$b誰曉得...', `MaleText_loc7`='¿Has ido y has conseguido que le agrademos a esos salvajes?$b$b¡Debes ser una especie de genio $r!$b$bQuién lo hubiera dicho...' WHERE `ID`=58241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길에서 도망쳐!', `MaleText_loc4`='离火远点儿！', `MaleText_loc5`='你離火遠一點!', `MaleText_loc7`='¡Tú aleja del fuego!' WHERE `ID`=58242;
