UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 $r 왔다!', `MaleText_loc4`='该死的$r！', `MaleText_loc5`='天殺的$r!', `MaleText_loc7`='¡Machuka $r!' WHERE `ID`=58248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 수프에 너 집어넣는다, 이 바보!', `MaleText_loc4`='我要把你丢进汤锅里，你这该死的蠢蛋！', `MaleText_loc5`='我要把你煮成湯來吃，你這個怪胎廢渣!', `MaleText_loc7`='¡Yo te cocina en mi sopa, trakupa!' WHERE `ID`=58249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 벼랑을 타고 올라와요! 이거 귀찮게 됐네요.', `FemaleText_loc4`='他们在攀爬峭壁！这下情况复杂了。', `FemaleText_loc5`='他們在爬懸崖山壁!這可就難辦了。', `FemaleText_loc7`='¡Están escalando los acantilados! Esto va a ponerse feo.' WHERE `ID`=58250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인상적이군, $r.$b$b자네 덕분에 이 생물들이 소중한 아군이 되었네.', `MaleText_loc4`='令人钦佩，$r。$b$b多亏了你，这些生物或许会成为宝贵的盟友。', `MaleText_loc5`='了不起啊，$r。$b$b多虧了你，這些生物或許會成為寶貴的盟友。', `MaleText_loc7`='Impresionante, $r.$b$bGracias a ti, estas criaturas se pueden convertir en valiosos aliados.' WHERE `ID`=58251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='발 조심하세요! 돌이 비를 맞아서 미끄러워요.', `FemaleText_loc4`='小心脚下！由于下雨的关系，石头还是很湿滑。', `FemaleText_loc5`='小心腳步!下雨後石頭還是很滑。', `FemaleText_loc7`='¡Mira dónde pisas! Las piedras todavía están resbalosas por la lluvia.' WHERE `ID`=58252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤를 보세요! 아, 제 뒤태 말고요. 뒤쪽 말이에요!', `FemaleText_loc4`='注意屁股后面！不——不是说我的屁股。是我们身后！', `FemaleText_loc5`='注意後面!不是我的屁股後面啦。我們的後面!', `FemaleText_loc7`='¡Atención a la retaguardia! No, MI retaguardia no. ¡Detrás de nosotros!' WHERE `ID`=58253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 숨을 가쁘게 몰아쉬며 멈춰 섭니다.', `FemaleText_loc4`='%s在路旁停了下来，喘着粗气。', `FemaleText_loc5`='%s停在路邊，深深地喘氣。', `FemaleText_loc7`='%s se detiene junto al camino, jadeando con fuerza.' WHERE `ID`=58254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌은 가장 위풍당당한 사냥꾼이라네.', `MaleText_loc4`='牛头人是最伟大的猎手。', `MaleText_loc5`='牛頭人是最威武的獵人。', `MaleText_loc7`='Los tauren son los cazadores más majestuosos.' WHERE `ID`=58255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌이 사냥하는 것 본 적 있나? 사냥 당하는 마지막 순간까지 사냥감이 절대 알아챌 수가 없다네.', `MaleText_loc4`='你见过牛头人猎人吗？等你见到时已经来不及脱身了。', `MaleText_loc5`='你有見過牛頭人狩獵的情景嗎?等你見到時已經太晚了。', `MaleText_loc7`='¿Has visto alguna vez a un tauren cazando? Nunca lo ves hasta que es demasiado tarde.' WHERE `ID`=58256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가면은 절대 빼앗을 수 없을 거다, $P!', `MaleText_loc4`='你休想从我手里拿到面具，$P！', `MaleText_loc5`='$P，你一輩子都別想把面具從我臉上摘掉!', `MaleText_loc7`='¡NUNCA CONSEGUIRÁS ARREBATARME LA MÁSCARA, $P!' WHERE `ID`=58257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노에 무릎 꿇어라!', `MaleText_loc4`='向你的愤怒屈服吧！', `MaleText_loc5`='向你的憤怒屈服吧!', `MaleText_loc7`='¡Dejaos llevar por la ira!' WHERE `ID`=58258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 쿤라이 봉우리는 물론, 판다리아 전역이 분노에 휩싸일 것이다. 그 다음은 온 세상이다!', `MaleText_loc4`='很快，昆莱山和整个潘达利亚都将被怒火吞噬。然后，就是全世界！', `MaleText_loc5`='很快的，崑萊峰與潘達利亞就會被憤怒吞噬殆盡。接下來，就是全世界!', `MaleText_loc7`='Pronto la Cima Kun-Lai y toda Pandaria estarán consumidas por la ira. ¡Y luego el mundo entero!' WHERE `ID`=58260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위는 이미 우리 수중에 있고, 다음은 빈안 마을이다!', `MaleText_loc4`='锦鱼人是我们的，下一个就是滨岸村！', `MaleText_loc5`='我們已經拿下錦魚人，濱南村就是下一個!', `MaleText_loc7`='¡Los jinyu son nuestros y en breve también lo será la Aldea Binan!' WHERE `ID`=58261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 안에서 끓어오르는 분노가 느껴진다.', `MaleText_loc4`='我能感受到愤怒正充斥你的内心。', `MaleText_loc5`='我可以感受到憤怒在你心中成型。', `MaleText_loc7`='Siento cómo la ira se acumula en tu interior.' WHERE `ID`=58262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸 모 스 따위, 비틀거리는 영감태기다. 아무것도 할 줄 아는 게 없지!', `MaleText_loc4`='付莫是就是个老蠢货。他简直一事无成！', `MaleText_loc5`='伏魔氏是個腳步蹣跚的老笨蛋。他是個一無是處大師!', `MaleText_loc7`='Fu Mo Shi es un viejo chalado. ¡No es maestro de nada!' WHERE `ID`=58263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노에 불을 질러라!', `MaleText_loc4`='被我的怒火吞噬吧！', `MaleText_loc5`='餵養我的憤怒吧!', `MaleText_loc7`='¡Alimenta mi ira!' WHERE `ID`=58264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 유명한 오로른 파스트라이더 님과 함께 사냥해본 적이 있다네. 그분께서는 속옷 한 장 달랑 입고 토템만으로도 사냥하실 수 있었다네.', `MaleText_loc4`='我曾经与声名远播的欧洛恩·远行者一同狩猎。他是一位牛头人，打猎时只带着图腾，穿着粗布衣衫。', `MaleText_loc5`='我曾經與有名的歐洛恩·遠行者一同狩獵。他就是一個身上只需要圖騰跟汗衫就能進行狩獵的牛頭人。', `MaleText_loc7`='Una vez cacé junto al célebre Ohlorn Errante. Era un tauren que podía cazar únicamente con un tótem y unos calzones.' WHERE `ID`=58265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네싱워리 님은 대단한 사냥꾼이셨습니다만, 제대로 된 사냥 작전을 가르쳐줄 수 있는 드루이드가 있었으면 합니다.', `MaleText_loc4`='奈辛瓦里是位杰出的猎手，可我多么希望这儿能有一位德鲁伊，向我们传授些实用的捕猎动物的技法。', `MaleText_loc5`='奈辛瓦里是個技術高超的獵人，但我希望能有個德魯伊在這兒教我們一些正確的動物狩獵策略。', `MaleText_loc7`='Nesingwary es un cazador impresionante, pero me gustaría que hubiera un druida aquí para enseñarnos algunas estrategias de caza de animales.' WHERE `ID`=58266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요. 이제 뭘 해야 할지 알 것 같아요.', `MaleText_loc4`='好吧，我想我知道接下来该做什么了。', `MaleText_loc5`='好吧，我想我知道我們接下來該採取什麼行動了。', `MaleText_loc7`='Muy bien, creo que ya sé cuál será nuestro siguiente paso.' WHERE `ID`=58269;
