UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼끼 응가쟁이!', `MaleText_loc4`='该死的坏蛋！', `MaleText_loc5`='你這廢渣!', `MaleText_loc7`='¡Dingue miko!' WHERE `ID`=58275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발도 못 맞추는 녀석들은 평생 처음 본다고!', `MaleText_loc4`='这真是我见过的有史以来最最糟糕的行军队列！', `MaleText_loc5`='那是我見過最糟的行進!', `MaleText_loc7`='¡Esa es la peor marcha que he visto en mi vida!' WHERE `ID`=58276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아니, 아니라고... 왼발 다음에 오른발이라니까!', `MaleText_loc4`='不，不，不……先是左脚，后是右脚！', `MaleText_loc5`='不對不對...先左腳再右腳!', `MaleText_loc7`='No, no, no... ¡Primero izquierda y luego derecha!' WHERE `ID`=58277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정말! 하루 종일 이것만 하고 있잖아!', `MaleText_loc4`='噢得了吧！我们已经忙活了一整天了！', `MaleText_loc5`='喔拜託!我們搞這個已經搞一整天了!', `MaleText_loc7`='¡Venga, hombre! ¡Llevamos con esto todo el día!' WHERE `ID`=58278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 거기! 뒤쪽에 있는 너! 내가 지켜보고 있어!', `MaleText_loc4`='嘿！嘿，就是你，后面个家伙！我盯着你呢！', `MaleText_loc5`='嘿!嘿後面的那個!我在盯著你!', `MaleText_loc7`='Eh, tú. ¡Sí, tú, $gel:la; de atrás! ¡Que te estoy viendo!' WHERE `ID`=58279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억! 호드다!', `MaleText_loc4`='啊！是部落！', `MaleText_loc5`='噁!是部落!', `MaleText_loc7`='¡Aah! ¡Es la Horda!' WHERE `ID`=58280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드다! 도망쳐!', `MaleText_loc4`='是部落！快跑！', `MaleText_loc5`='是部落!快逃!', `MaleText_loc7`='¡La Horda! ¡Corred!' WHERE `ID`=58281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 쳐들어온다!', `MaleText_loc4`='部落入侵了！', `MaleText_loc5`='部落入侵了!', `MaleText_loc7`='¡La Horda nos invade!' WHERE `ID`=58282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이들을 숨겨라! 아내를 숨겨라!', `MaleText_loc4`='藏好你们的孩子！看好你们的老婆！', `MaleText_loc5`='把孩子藏起來!把老婆藏起來!', `MaleText_loc7`='¡Escondan a sus hijos! ¡Escondan a sus mujeres!' WHERE `ID`=58283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 다들 도망쳐!', `MaleText_loc4`='呀！大家快跑！', `MaleText_loc5`='咿!大家快跑!', `MaleText_loc7`='¡Aaah! ¡Huyamos!' WHERE `ID`=58284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 날 구한 건가? 당신, 호드잖아!', `MaleText_loc4`='是你救了我？可你是部落！', `MaleText_loc5`='你救了我?但是，你是部落的人!', `MaleText_loc7`='¿Me has salvado tú? Pero... ¡eres de la Horda!' WHERE `ID`=58285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 샤로도 모자라서 호드까지!', `MaleText_loc4`='先是惹恼了煞魔，现在又是部落！', `MaleText_loc5`='先是怒煞，現在又來了部落!', `MaleText_loc7`='¡Primero el Sha de la ira y ahora la Horda!' WHERE `ID`=58286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집으로 돌아가라, 호드!', `MaleText_loc4`='从哪儿来的就回哪儿去吧，部落！', `MaleText_loc5`='部落的傢伙，回到你原本的地方去!', `MaleText_loc7`='¡Vuelve por donde has venido, Horda!' WHERE `ID`=58287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 살았습니다. 고맙습니다!', `MaleText_loc4`='谢谢你救了我一命！', `MaleText_loc5`='謝謝你救了我的命!', `MaleText_loc7`='¡Gracias por salvarme la vida!' WHERE `ID`=58288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물에게 말을 걸었을 때, 물은 네 모습을 보여주었다, $n. 아무래도 너는 지나가는 여행자 이상의 존재인 모양이군. 어떤 이유가 있어 우리에게 보내진 모양이다.', `MaleText_loc4`='当我跟水交谈时，它们向我展示了一个关于你的景象，$n。或许你不仅仅只是一个过客，或许你被派到我们这儿来是有原因的。', `MaleText_loc5`='我和水交談的時候，他們給了我一個關於你的幻象，$n。也許你不只是個過客，也許你來到這裡是有原因的。', `MaleText_loc7`='Cuando las aguas me hablaron, me mostraron una visión de ti, $n. Quizás seas algo más que $gun extraño:una extraña; visitante. Puede que te llegaras hasta aquí por algo.' WHERE `ID`=58289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 가지만은 분명하다. 너와 네 동료들이 우리 미래에 영향을 주었다.', `MaleText_loc4`='有件事很清楚，你和你的同胞将会影响到我们的未来。', `MaleText_loc5`='有件事是肯定的。我們的未來將受到你和你族類的影響。', `MaleText_loc7`='Una cosa está clara. Nuestro futuro se verá afectado por ti y por tu pueblo.' WHERE `ID`=58290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물예언의 의식 때문인지 무척 피곤하군. 부디, 내가 잠시 쉬며 생각할 수 있는 시간을 다오.', `MaleText_loc4`='水语仪式让我感到十分疲惫。请给我点时间，让我好好地休息，好好地思考。', `MaleText_loc5`='水語儀式讓我感到很疲倦。請給我一點休息和思考的時間。', `MaleText_loc7`='La ceremonia de la oración del agua me ha fatigado. Te ruego que me concedas tiempo para descansar y reflexionar.' WHERE `ID`=58291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 너희 병사들과 함께 열심히 훈련하고 있다.', `MaleText_loc4`='我们正在努力工作，和你的士兵一起受训。', `MaleText_loc5`='我們很努力地和你的士兵們一起訓練。', `MaleText_loc7`='Estamos trabajando muy duro entrenando con sus soldados.' WHERE `ID`=58292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 덕분에 호젠은 이제 우릴 위협하는 존재가 아니다. 이제 우리 마을도 재건과 성장을 시작할 수 있다.', `MaleText_loc4`='多亏有你，猢狲以后再也不会成为我们的威胁了。我们的村子现在可以重新投入建设和发展了。', `MaleText_loc5`='多虧了你，猴人不再是威脅了。我們的村子可以開始致力於重建和繁榮。', `MaleText_loc7`='Gracias a ti, los hozen ya no suponen una amenaza. Nuestra aldea ya puede empezar a reconstruirse y crecer.' WHERE `ID`=58293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내일은 알 수 없는 가능성을 품고 있다. 모두 너와 얼라이언스 덕분이다.', `MaleText_loc4`='明天充满了无限的可能性，而这一切都多亏了你和联盟的大力相助。', `MaleText_loc5`='我們的明天有著無盡的可能性，這多虧了你和聯盟。', `MaleText_loc7`='El mañana nos ofrece posibilidades inefables, y todo gracias a ti y a la Alianza.' WHERE `ID`=58294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 기이한 너희 고향에 대해서도 내게 더 들려주면 좋겠구나.', `MaleText_loc4`='或许某天，你可以跟我多讲一些有关你们那片神奇的故土的情况。', `MaleText_loc5`='有一天，或許你能跟我多說點你所來自的那片奇怪土地。', `MaleText_loc7`='Algún día quizás puedas contarme más cosas sobre la extraña tierra de la que procedes.' WHERE `ID`=58295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼께서 말씀하셨다. 우린 무기를 들고 호젠을 공격해야 해!', `MaleText_loc4`='诸灵喻示，我们必须拿起武器，抗击猢狲！', `MaleText_loc5`='魂靈說話了。我們應該拿起武器，攻擊猴人!', `MaleText_loc7`='El espíritu ha hablado. ¡Deberíamos tomar las armas y atacar a los hozen!' WHERE `ID`=58296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 판다리아의 고대 진위 황제 중 한 분을 뵌 것이다, $n.', `MaleText_loc4`='你现在注视的是一位古代锦鱼人皇帝，$n，他曾经统治过潘达利亚。', `MaleText_loc5`='你見到的是一位潘達利亞的古代錦魚人皇帝，$n。', `MaleText_loc7`='Acabas de ver a uno de los antiguos emperadores jinyu de Pandaria, $n.' WHERE `ID`=58297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 목소리가 마치 천둥처럼 나를 꿰뚫었다. 너도 들었나?', `MaleText_loc4`='流水之魂的声音如雷鸣般在我耳边回荡。你听到了吗？', `MaleText_loc5`='魂靈的聲音像雷電般穿透了我。你有聽到嗎?', `MaleText_loc7`='La voz del espíritu resuena a través de mí como un trueno. ¿La oyes?' WHERE `ID`=58298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 말씀은... 아마도 우리가 힘을 합쳐야 한다는 의미일 것이다, $n.', `MaleText_loc4`='我相信这个景象是叫我们紧密团结在一起，$n。', `MaleText_loc5`='我相信，這幻象的意思是要我們團結起來，攜手合作，$n。', `MaleText_loc7`='Creo que la visión quiere decir que nos unamos, $n.' WHERE `ID`=58299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님도 많은 점을 고려하실 것이다. 하지만 나는 명백하다고 생각한다. 너는 호젠과의 전쟁에서 우리를 승리로 이끌 것이다.', `MaleText_loc4`='长老还有很多顾虑，但我觉得已经很清楚。你是来领导我们击败猢狲并取得最终胜利的。', `MaleText_loc5`='長者有很多事需要沉思。但我想事情已經很清楚了。你註定要領導我們戰勝猴人。', `MaleText_loc7`='El ancestro debe tener mucho que considerar, pero para mí está claro. Tu destino es guiarnos a la victoria contra los hozen.' WHERE `ID`=58300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리는 친구다, $n. 돌아오고 싶으면 언제라도 우리 마을을 찾아와도 좋다.', `MaleText_loc4`='我们现在是朋友了，$n。我们村随时欢迎你回来。', `MaleText_loc5`='我們是朋友了，$n。只要你想回來，我們村莊隨時歡迎你。', `MaleText_loc7`='Ahora somos amigos, $n. Nuestro poblado siempre te dará la bienvenida cuando quieras regresar.' WHERE `ID`=58301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 여러 해 동안 네 이름이 우리 마을 안에서 울려 퍼질 것이다.', `MaleText_loc4`='你的名字将在我们村子里世代传诵、流芳百世。', `MaleText_loc5`='你的名字會在我們的村莊傳頌多年。', `MaleText_loc7`='Tu nombre pasará de generación en generación en nuestro poblado.' WHERE `ID`=58302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 네 고향을 나도 볼 수 있었으면 좋겠군. 아무래도 우리 이곳과는 많이 다르겠지?', `MaleText_loc4`='或许某天，你可以带我去看看你的故乡。那里一定有着别样的风景。', `MaleText_loc5`='有一天，或許你會帶我見識你的家鄉。那一定和我們這裡十分不同。', `MaleText_loc7`='Quizás algún día me enseñes tu hogar. Debe ser un lugar muy diferente al nuestro.' WHERE `ID`=58303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두 네게 큰 빚을 졌다, $r.', `MaleText_loc4`='我们欠你一个很大的人情，$r。', `MaleText_loc5`='我們欠你很大的人情，$r。', `MaleText_loc7`='Estamos en gran deuda contigo, $r.' WHERE `ID`=58304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위가 생각보다 능력 있는 병력임이 드러나고 있습니다.', `MaleText_loc4`='锦鱼人的确是出色的战士。', `MaleText_loc5`='錦魚人是相當不錯的戰士。', `MaleText_loc7`='Los jinyu están demostrando ser soldados competentes.' WHERE `ID`=58305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 훈련만 한다면, 진위가 우리 육상 전투력을 크게 강화시킬 수 있을 것입니다.', `MaleText_loc4`='经过正规的训练，锦鱼人将成为我们地面部队不可或缺的一支强大战力。', `MaleText_loc5`='接受過正確的訓練，錦魚人會成為我們陸地上的強大生力軍。', `MaleText_loc7`='Con el entrenamiento adecuado, los jinyu serían una gran contribución para nuestras tropas terrestres.' WHERE `ID`=58306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 그 추악한 얼굴을 드러낼 때면, 우리도 모든 준비를 마친 후일 것입니다.', `MaleText_loc4`='当部落那群野兽最终露出他们狰狞的面孔时，我们会准备好的。', `MaleText_loc5`='等部落終於露出他們的醜臉時，我們會好好給他們個痛快。', `MaleText_loc7`='Cuando la Horda muestre al fin su sucia cara, estaremos preparados.' WHERE `ID`=58307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 여기서 많은 도움을 주셨습니다, $n 님. 우리가 스톰윈드에 돌아가게 되면, 당신의 직속상관에게 당신의 공로를 꼭 전하겠습니다.', `MaleText_loc4`='你做得很好，$n。等我们回暴风城后，我会在你的长官面前为你多美言几句的。', `MaleText_loc5`='你在這表現得很好，$n。回到暴風城後我會跟你的長官們說點好話的。', `MaleText_loc7`='Lo has hecho muy bien, $n. Enviaré una recomendación a tus superiores cuando regresemos a Ventormenta.' WHERE `ID`=58308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드릴까요?', `MaleText_loc4`='我该怎么帮你呢？', `MaleText_loc5`='有什麼我能幫忙的嗎?', `MaleText_loc7`='¿En qué puedo ayudarte?' WHERE `ID`=58309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 당신의 물은 어디로 흘러가고 있습니까, 여행자여?', `MaleText_loc4`='今天的水流是否顺遂呢，旅行者？', `MaleText_loc5`='你今天狀況如何，旅人?', `MaleText_loc7`='¿Cómo fluyen tus aguas hoy, $gviajero:viajera;?' WHERE `ID`=58310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 형제들을 너무 많이 잃었습니다. 이제 그 숫자를 세고 싶지도 않습니다.', `MaleText_loc4`='我们在战斗中失去了许多兄弟，我已经不想再数下去了。', `MaleText_loc5`='我們在戰鬥中失去了這麼多弟兄，我不想繼續數下去了。', `MaleText_loc7`='Hemos perdido a tantos hermanos en la batalla que ya no quiero llevar la cuenta.' WHERE `ID`=58311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 약삭빠르고 교활합니다. 그보다 더 안 좋은 것은, 수치심이나 후회를 느끼지 않는다는 점입니다.$B$B순전히 본능적으로, 아니면 탐욕 때문에 재미삼아 살상을 합니다.', `MaleText_loc4`='猢狲非常狡猾、奸诈。更糟的是，他们完全不懂羞耻和反省。$B$B他们完全凭着本能去烧杀掠夺，只为满足他们的欲望和贪婪。', `MaleText_loc5`='猴人狡猾又詭詐。更糟的是，他們不會羞愧也不會懊悔。$B$B他們的殺戮出於本能，純粹為了快樂或貪婪。', `MaleText_loc7`='Los hozen son escurridizos y astutos. Y, aún peor, no sienten vergüenza o remordimiento.$b$bSe guían por el instinto, el placer y la avaricia para asesinar.' WHERE `ID`=58312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없습니다! 황제님의 영혼을 뵙다니!', `MaleText_loc4`='难以置信！我竟然看见了一位皇帝的灵魂！', `MaleText_loc5`='真不敢相信!我見到了一位皇帝的魂靈!', `MaleText_loc7`='¡No doy crédito! ¡He visto el espíritu de un emperador!' WHERE `ID`=58313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 우리에게 미래의 길을 보여주셨습니다. 그리고, 왠지 모르지만 그 길은 당신과 관련이 있다고 합니다.', `MaleText_loc4`='流水之魂向我们展现了未来的道路。但不知为何，这多少跟你还有点关系。', `MaleText_loc5`='魂靈將未來的道路展現在我們眼前。不知為何，這條道路和你有些不可分的關係。', `MaleText_loc7`='El espíritu nos mostró el camino a nuestro futuro. Y, de alguna forma, tienes algo que ver.' WHERE `ID`=58314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어, 달이 여러 번 지나간 끝에, 우리의 미래에 대한 희망이 생겼습니다.', `MaleText_loc4`='终于，这么多天以来，我第一次感到我们的未来还有希望。', `MaleText_loc5`='終於，歷經無數個日子之後，我第一次對我們的未來感到希望。', `MaleText_loc7`='Al fin, por primera vez en muchas lunas, tengo esperanzas en el futuro.' WHERE `ID`=58315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가 제 아이들에게 당신의 이야기를 들려주겠습니다, $n 님.', `MaleText_loc4`='有朝一日，我会把你的故事讲给我的孩子听，$n。', `MaleText_loc5`='有一天，我會和我的子孫講述你的故事，$n。', `MaleText_loc7`='Algún día le hablaré de ti a mis hijos, $n.' WHERE `ID`=58316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 얼라이언스... 친구들 중 몇몇과 이야기를 나눴습니다. 정말 재미있는 분들이시더군요.', `MaleText_loc4`='我已经和你的一些……联盟……朋友聊过了。你们的人相当有趣。', `MaleText_loc5`='我和你的...聯盟...朋友們說了點話。你們是群相當有趣的傢伙。', `MaleText_loc7`='He hablado con algunos de tus... amigos de la... Alianza. Tu pueblo resulta bastante interesante.' WHERE `ID`=58317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이 온통 새로 시작한 훈련에 대해서만 이야기합니다.', `MaleText_loc4`='我们的士兵一直在谈论着他们的训练。', `MaleText_loc5`='我們的士兵滔滔不絕地討論著他們受的新訓練。', `MaleText_loc7`='Nuestros soldados solo hablan de su nuevo entrenamiento.' WHERE `ID`=58318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 소문이 무성한 $c, $n 님이십니까? 당신에 대한 이야기를 정말 많이 들었습니다만, 이렇게 직접 만나 뵙게 될 줄은 몰랐습니다.', `MaleText_loc4`='你是$c吗， $n？我听过很多有关你的传闻，可从没想过能见到你本人。', `MaleText_loc5`='你就是傳說中的那位$c嗎，$n?我聽了好多關於你的故事，但從沒想到可以當面遇到你。', `MaleText_loc7`='¿Eres $gel:la; $c, $n? He oído muchas historias sobre ti, pero nunca me imaginé que te conocería en persona.' WHERE `ID`=58319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리 마을의 축복 같은 존재이십니다.', `MaleText_loc4`='你的到来犹如一阵春风，沐浴了我们的部族。', `MaleText_loc5`='你的到來是我們部族的祝福。', `MaleText_loc7`='Tu llegada fue una bendición para nuestra tribu.' WHERE `ID`=58320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 당신을 의심했었습니다, $n 님. 하지만 당신은 지금까지 우리 부족에게 자신의 역할을 충분히 증명해 보이셨습니다.', `MaleText_loc4`='我必须承认，我一开始怀疑过你，$n，但你已经向我们的部落证明了你自己。', `MaleText_loc5`='我必須承認自己曾經懷疑過你，$n。但你向我們部族證明了你自己。', `MaleText_loc7`='Debo admitir que tuve mis dudas sobre ti al principio, $n, pero has demostrado lo suficiente a nuestra tribu.' WHERE `ID`=58321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원에 대해 대책을 취하려면 안두인의 도움이 필요합니다. 안두인이 준비되면 시작하지요.', `MaleText_loc4`='我们需要安度因帮忙，才能对寺庙采取行动。等他准备好，我们就开始。', `MaleText_loc5`='我們需要安杜因的幫忙來移動到寺廟去。等他準備好我們就開始。', `MaleText_loc7`='Necesitaremos la ayuda de Anduin para pasar al templo. Cuando esté listo, comenzaremos.' WHERE `ID`=58322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들창엄니!', `MaleText_loc4`='血骨傀儡！', `MaleText_loc5`='血骨傀儡!', `MaleText_loc7`='¡Traquesangre!', `FemaleText_loc1`='들창엄니!', `FemaleText_loc4`='血骨傀儡！', `FemaleText_loc5`='血骨傀儡!', `FemaleText_loc7`='¡Traquesangre!' WHERE `ID`=58323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 그에 동조하는 세력을 무찌르고 이 땅을 차지하는 것은, 호드의 끈기 있는 도전을 잘 보여주는 상징이 될 걸세.', `MaleText_loc4`='等我们击溃联盟和他们的盟友，并占领这片土地之后，它就将成为部落百折不挠的精神最强有力的证明。', `MaleText_loc5`='一旦我們擊敗聯盟和他們的盟友，這片土地將成為部落屹立不搖的最好證明。', `MaleText_loc7`='Una vez derrotemos a la Alianza y a sus aliados, reclamar esta tierra representará un testimonio digno de la tenacidad de la Horda.' WHERE `ID`=58324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 아니었다면 죽느니만 못한 꼴을 당했을 겁니다!', `MaleText_loc4`='要不是因为你，我早就死了，甚至更糟！', `MaleText_loc5`='如果不是你，我可能會死，或者更糟!', `MaleText_loc7`='¡De no ser por ti estaría muerto o algo peor!' WHERE `ID`=58325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 또 구하러 왔다!', `MaleText_loc4`='联盟又来救援了！', `MaleText_loc5`='聯盟又來拯救我們了!', `MaleText_loc7`='¡La Alianza viene de nuevo al rescate!' WHERE `ID`=58326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 외지인이여!', `MaleText_loc4`='谢谢你，外乡人！', `MaleText_loc5`='謝謝你，外來者!', `MaleText_loc7`='¡Gracias, $gforastero:forastera;!' WHERE `ID`=58327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 진위가 당신네 얼라이언스에게 큰 신세를 졌습니다!', `MaleText_loc4`='锦鱼人对你和联盟不胜感激！', `MaleText_loc5`='錦魚人欠你跟聯盟一份情!', `MaleText_loc7`='¡Los jinyu están en deuda contigo y con la Alianza!' WHERE `ID`=58328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살았다! 얼라이언스 만세!', `MaleText_loc4`='我自由了！联盟万岁！', `MaleText_loc5`='我自由了!聯盟萬歲!', `MaleText_loc7`='¡Soy libre! ¡Viva la Alianza!' WHERE `ID`=58329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위도 얼라이언스가 될 수 있었으면 좋겠군요. 감사합니다!', `MaleText_loc4`='真希望锦鱼人能加入联盟。谢谢你！', `MaleText_loc5`='我希望錦魚人可以加入聯盟。謝謝你!', `MaleText_loc7`='Ojalá los jinyu se pudieran unir a la Alianza. ¡Gracias!' WHERE `ID`=58330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 빚을 졌습니다. 부디 다른 이들도 구해 주십시오.', `MaleText_loc4`='我欠你份人情。请救救我其他的族人。', `MaleText_loc5`='我欠你的太多了。請救出我們其他的人。', `MaleText_loc7`='Estoy en deuda contigo. Por favor, salva al resto de mi pueblo.' WHERE `ID`=58331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 훈련 보고서를 제출하라고 하셨습니다.', `MaleText_loc4`='纳兹戈林将军要看你的训练报告。', `MaleText_loc5`='納茲格寧姆將軍需要你的訓練報告。', `MaleText_loc7`='El general Nazgrim necesita tu informe de entrenamiento.', `FemaleText_loc1`='나즈그림 장군님께서 훈련 보고서를 제출하라고 하셨어요.', `FemaleText_loc4`='纳兹戈林将军要看你的训练报告。', `FemaleText_loc5`='納茲格寧姆將軍需要你的訓練報告。', `FemaleText_loc7`='El general Nazgrim necesita tu informe de entrenamiento.' WHERE `ID`=58332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의사가 왔도다!', `MaleText_loc4`='医生来了！', `MaleText_loc5`='醫生來了!', `MaleText_loc7`='¡Llegó el doctor!' WHERE `ID`=58333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 현재 훈련 진행 상황을 알고 싶으시답니다.', `MaleText_loc4`='纳兹戈林将军想要了解你的最新进展。', `MaleText_loc5`='納茲格寧姆將軍想要了解你的最新進度。', `MaleText_loc7`='El general Nazgrim quiere que le informes de tu progreso.', `FemaleText_loc1`='나즈그림 장군님께서 현재 훈련 진행 상황을 알고 싶으시대요.', `FemaleText_loc4`='纳兹戈林将军想要了解你的最新进展。', `FemaleText_loc5`='納茲格寧姆將軍想要了解你的最新進度。', `FemaleText_loc7`='El general Nazgrim quiere que le informes de tu progreso.' WHERE `ID`=58334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 훈련 상황을 알고 싶으시답니다.', `MaleText_loc4`='纳兹戈林将军想要了解你的最新进展。', `MaleText_loc5`='納茲格寧姆將軍需要了解你的最新進度。', `MaleText_loc7`='El general Nazgrim necesita que le informes de tu progreso.', `FemaleText_loc1`='나즈그림 장군님께서 훈련 상황을 알고 싶으시대요.', `FemaleText_loc4`='纳兹戈林将军想要了解你的最新进展。', `FemaleText_loc5`='納茲格寧姆將軍想要了解你的最新進度。', `FemaleText_loc7`='El general Nazgrim necesita que le informes de tu progreso.' WHERE `ID`=58335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단한걸요, $p. 여기서부턴 우리가 데려갈게요.', `MaleText_loc4`='真是太好了，$p。接下来就交给我们吧。', `MaleText_loc5`='那很好，$p。接下來就交給我們吧。', `MaleText_loc7`='Eso es genial, $p. Ya nos encargamos nosotros.' WHERE `ID`=58336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워, 그 녀석 정말 더러운걸요. 세척기에 같이 안 들어가도 되겠어요?', `MaleText_loc4`='哇哦。它可真够脏的。你确定不想把它洗干净？', `MaleText_loc5`='哇喔，那隻真髒。你確定你不想一塊兒去洗洗乾淨嗎?', `MaleText_loc7`='Vaya. Qué suciedad. ¿Seguro que no quieres pasar por el lavadero tú también?' WHERE `ID`=58337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 냄새가 고약하네요.', `MaleText_loc4`='呃……那家伙都发臭了。', `MaleText_loc5`='呼...那隻準備好了。', `MaleText_loc7`='Uf... ese estaba maduro.' WHERE `ID`=58338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 녀석을 한참 찾아다녔어요. 정말 골칫덩이라니까요.', `MaleText_loc4`='噢，我一直在到处找它， 真是个麻烦的家伙。', `MaleText_loc5`='喔，我一直在找那傢伙。他可是個小麻煩。', `MaleText_loc7`='Ah, he estado buscando a ese por todas partes. Menudo elemento.' WHERE `ID`=58339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 이 녀석한테는 향수를 팍팍 뿌려 줘야겠네요.', `MaleText_loc4`='嗯。我想得把它弄得更香一些。', `MaleText_loc5`='嗯。我想那隻需要加點額外的芳香劑。', `MaleText_loc7`='Mmm. Creo que ese va a necesitar más colonia.' WHERE `ID`=58340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 그 녀석 그루멀들이 아주 좋아하게 생겼네요.', `MaleText_loc4`='噢，土地精会喜欢它的。', `MaleText_loc5`='喔，咕嚕摩會愛死那隻的。', `MaleText_loc7`='Ah, ese les va a encantar a los grúmel.' WHERE `ID`=58341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 이 불쌍한 녀석에게 무슨 짓을 한 거지?', `MaleText_loc4`='野牛人对那个可怜的家伙干了什么？', `MaleText_loc5`='揚古對那個可憐的東西做了什麼?', `MaleText_loc7`='¿Qué han hecho los yaungol con este pobre?' WHERE `ID`=58342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 더 씻길 일은 없기를.', `MaleText_loc4`='但愿它不会再遇到这种事了。', `MaleText_loc5`='我希望那小傢伙不需要經歷這種事兩次。', `MaleText_loc7`='Espero que ese no tenga que pasar dos veces.' WHERE `ID`=58343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들이 아무리 괴롭혀도 여길 떠나진 않을 테다!', `MaleText_loc4`='你休想让我离开自己的土地！', `MaleText_loc5`='你不能把我趕離我的土地!', `MaleText_loc7`='¡No me van a expulsar de mis tierras!' WHERE `ID`=58344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 내 야크잖아! 당장 이리 데리고 와!', `MaleText_loc4`='嘿！那些是我的牦牛！马上把它们带回来！', `MaleText_loc5`='嘿!那是我的犛牛!馬上把牠們帶回這裡!', `MaleText_loc7`='¡Eh! ¡Esos yaks son míos! ¡Devuélvanmelos inmediatamente!' WHERE `ID`=58345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 더러운 야운골 놈들한테 겁먹을 거라 생각한다면, 각오 단단히 해야 할 거다!', `MaleText_loc4`='要是你以为我会被几个脏兮兮的野牛人吓倒，那你可就大错特错了！', `MaleText_loc5`='如果你以為我會被一群骯髒的揚古嚇倒，你可就想錯了!', `MaleText_loc7`='¡No piensen que me voy a dejar intimidar por un grupito de sucios yaungol!' WHERE `ID`=58346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주게! 야운골 놈들이 내 야크를 훔치려고 하네!', `MaleText_loc4`='快来帮帮我！这些野牛人想偷我的牦牛！', `MaleText_loc5`='救命!這些揚古想偷走我的犛牛!', `MaleText_loc7`='¡Ayuda! ¡Estos yaungol intentan robarme mis yaks!' WHERE `ID`=58347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 허리를 다친 게 다행인 줄 알아라! 아니면 당장 쫓아가서 네놈들을 걷어차 쫓아버릴 테니까.', `MaleText_loc4`='看我走了你们就偷着乐吧，否则我会到那把你们赶出我的土地。', `MaleText_loc5`='你最好慶幸我扭傷了我的背，不然我會把你從我的土地踢出去。', `MaleText_loc7`='Den gracias de que tengo la espalda destrozada, si no los echaría de mis tierras a patadas.' WHERE `ID`=58348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 야운골 놈들!', `MaleText_loc4`='卑鄙的野牛人祸害！', `MaleText_loc5`='到處都是這些骯髒的揚古!', `MaleText_loc7`='¡Sucia plaga yaungol!' WHERE `ID`=58349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀들이 와서 네놈들 야운골을 다시 장벽 너머로 끌고 갔으면 좋겠군.', `MaleText_loc4`='真希望螳螂妖能来把你们这些野牛人拖回长城那边去。', `MaleText_loc5`='我希望螳螂人來把你們這些揚古拖到長城外去。', `MaleText_loc7`='Yaungol, espero que vengan los mántides y te arrastren de vuelta al otro lado de la muralla.' WHERE `ID`=58350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저세상에 있는 아내가 우리 농장에 깡패들이 들끓는 걸 못 보기에 망정이지!', `MaleText_loc4`='幸好我的妻子——愿灵魂指引着她，不用亲眼看见我们的家业被这些无赖和流氓恣意侵扰。', `MaleText_loc5`='我的妻子，願魂靈們引導她，我只慶幸她不在這裡，眼睜睜看那些暴徒跟強盜蹂躪我們的基業!', `MaleText_loc7`='¡Me alegro de que mi esposa, que los espíritus la guíen, no pueda ver cómo estos rufianes y matones invaden nuestro negocio!' WHERE `ID`=58351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 정말 희대의 비극일세. 그저 아들과 함께 평화롭게 야크 세척장을 운영하는 게 꿈인 목장주가 야운골의 습격에 벌벌 떨어야 하다니...', `MaleText_loc4`='这世道真是可笑，我跟你说。一个堂堂的牧场主和他儿子连开个洗牛站都提心吊胆害怕野牛人的侵袭。', `MaleText_loc5`='我告訴你，這絕對是我們時代的一場鬧劇，一個熊貓人跟他兒子竟然因為擔心揚古突襲，而無法平和地將犛牛牽去洗澡...', `MaleText_loc7`='Es una auténtica barbaridad en estos tiempos que corren. Que un ranchero y su hijo no puedan mantener un lavadero de yaks sin miedo a que lo saqueen los yaungol...' WHERE `ID`=58352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이러면 그루멀들에게 야크를 공급하기가 힘들어질 걸세.', `MaleText_loc4`='要是再这么下去，真不知道我们该怎么继续向土地精供应牦牛。', `MaleText_loc5`='如果這情況持續下去，我甚至不知道該如何繼續供應犛牛給咕嚕摩。', `MaleText_loc7`='Si esto sigue así no sé cómo vamos a poder mantener nuestro suministro de yaks a los grúmel.' WHERE `ID`=58353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운의 여덟동전은 만나 봤나? 우리의 가장 큰 고객이기도 하고, 그루멀 중에 가장 능수능란한 협상가기도 하지.', `MaleText_loc4`='你见过好运的八铜钱吗？他是我们最大的客户，也是土地精贸易谈判代表中最精明的一位。', `MaleText_loc5`='你見過好運八錢嗎?他是我們最大的顧客，也是最精明的咕嚕摩商人。', `MaleText_loc7`='¿Conoces a Fortuno el Calderillas? Es nuestro cliente más importante y el más astuto de los negociadores grúmel.' WHERE `ID`=58354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 무려 열두 세대 동안 그루멀과 거래를 하면서, 말쑥하고 깨끗하고 냄새 나는 야크를 수백 마리 공급했다네.$b$b홍수와 기근은 물론, 모구의 침략도 이겨냈지. 그런데 이 야운골 놈들한테 쫓겨나면 내가 호젠 삼촌이다!', `MaleText_loc4`='我们的产业已经沿袭了十二代，给土地精供应了无数新鲜、卫生又“芬芳”的牦牛。$b$b我们经历过洪灾、饥荒和魔古族的入侵。要是我让这些野牛人赶跑我们，那我就是猢狲叔叔！', `MaleText_loc5`='我們的生意已經營了十二代，提供數以百計健康、乾淨而且臭兮兮的犛牛給咕嚕摩。$b$b我們曾遇過水災、饑荒和魔古。如果我讓這些揚古踩到我們頭上，那我就是猴人的叔叔。', `MaleText_loc7`='Nuestro negocio lleva en marcha doce generaciones y ha suministrado cientos de yaks recién lavados y perfumados a los grúmel.$b$bHemos superado inundaciones, hambrunas y a los mogu. Ni siquiera un hozen se dejaría ningunear por estos yaungol.' WHERE `ID`=58355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 야크를 훔치러 온 게냐?!$b$b그렇다면 각오해라. 나한테 따귀를 한 대 맞고 나면 그런 표정 못 지을 테니.', `MaleText_loc4`='你想偷我的牦牛？！$b$b如果真是这样，就等着我抽你的耳刮子吧。', `MaleText_loc5`='你來這裡偷我的犛牛?!$b$b如果真是這樣，準備好吃我一巴掌。', `MaleText_loc7`='¡¿Has venido a robarme mis yaks?!$b$bSi es así, prepárate para que te borre la cara a golpes.' WHERE `ID`=58356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈에게서 떨어져라!', `MaleText_loc4`='躲开他！', `MaleText_loc5`='離他遠一點!', `MaleText_loc7`='¡Aléjate de él!' WHERE `ID`=58357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석의 범위에서 벗어나!', `MaleText_loc4`='快离他远点！', `MaleText_loc5`='別進去他的攻擊範圍!', `MaleText_loc7`='¡Mantente fuera de su alcance!' WHERE `ID`=58358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 내 아들과 목장을 구했네. 정말 영영 갚을 수 없는 빚을 졌네, 이방인. 혹시 깨끗한 야크가 필요하면 언제든 찾아오게.', `MaleText_loc4`='你救了我的儿子，还有我的牧场。我这辈子都会感激你的，陌生人。假如哪天你想要一头干净的牦牛，你知道该去哪找我。', `MaleText_loc5`='你救了我的兒子跟我的牧場。我永遠欠你一份情，陌生人。如果哪天你需要洗乾淨你的犛牛，盡管來找我。', `MaleText_loc7`='Has salvado a mi hijo y defendido mi rancho. Siempre estaré en deuda contigo, $gforastero:forastera;. Si alguna vez necesitas un yak limpio, ya sabes adónde ir.' WHERE `ID`=58359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤로 물러나서 공격을 피해!', `MaleText_loc4`='躲开他的攻击！', `MaleText_loc5`='躲開他的攻擊!', `MaleText_loc7`='¡Aléjate de su ataque!' WHERE `ID`=58360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 그래! 피를 더 내놔!', `MaleText_loc4`='对！对！更多的血！', `MaleText_loc5`='沒錯!沒錯!更多的血!', `MaleText_loc7`='¡Sí! ¡Sí! ¡Más sangre!', `FemaleText_loc1`='그래! 그래! 피를 더 내놔!', `FemaleText_loc4`='对！对！更多的血！', `FemaleText_loc5`='沒錯!沒錯!更多的血!', `FemaleText_loc7`='¡Sí! ¡Sí! ¡Más sangre!' WHERE `ID`=58361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피, 피, 피, 피, 피!!', `MaleText_loc4`='血，血，血，血，血！！', `MaleText_loc5`='血...血...血...血...血!!', `MaleText_loc7`='¡Sangre sangre sangre SANGRE SANGRE!', `FemaleText_loc1`='피, 피, 피, 피, 피!!', `FemaleText_loc4`='血，血，血，血，血！！', `FemaleText_loc5`='血...血...血...血...血!!', `FemaleText_loc7`='¡Sangre sangre sangre SANGRE SANGRE!' WHERE `ID`=58362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뚝뚝 떨어지고 콸콸 흘러!', `MaleText_loc4`='滴血吧，飙血吧，凝血吧！', `MaleText_loc5`='滴落...四濺...凝固的血!', `MaleText_loc7`='¡Gotea, se derrama, se coagula!', `FemaleText_loc1`='뚝뚝 떨어지고 콸콸 흘러!', `FemaleText_loc4`='滴血吧，飙血吧，凝血吧！', `FemaleText_loc5`='滴落...四濺...凝固的血!', `FemaleText_loc7`='¡Gotea, se derrama, se coagula!' WHERE `ID`=58363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 줘!', `MaleText_loc4`='更多鲜血！', `MaleText_loc5`='更多的血!', `MaleText_loc7`='¡Más sangre!', `FemaleText_loc1`='피를 줘!', `FemaleText_loc4`='更多鲜血！', `FemaleText_loc5`='更多的血!', `FemaleText_loc7`='¡Más sangre!' WHERE `ID`=58364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 피 냄새... 너무 달콤해!', `MaleText_loc4`='香浓的鲜血……太美味了！', `MaleText_loc5`='血的味道...如此美味!', `MaleText_loc7`='El aroma de la sangre... es delicioso.', `FemaleText_loc1`='이 피 냄새... 너무 달콤해!', `FemaleText_loc4`='香浓的鲜血……太美味了！', `FemaleText_loc5`='血的味道...如此美味!', `FemaleText_loc7`='El aroma de la sangre... es delicioso.' WHERE `ID`=58365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 심홍빛 향연!', `MaleText_loc4`='鲜血四溅！', `MaleText_loc5`='血花四濺!', `MaleText_loc7`='¡Chorros carmesíes!', `FemaleText_loc1`='이 심홍빛 향연!', `FemaleText_loc4`='鲜血四溅！', `FemaleText_loc5`='血花四濺!', `FemaleText_loc7`='¡Chorros carmesíes!' WHERE `ID`=58366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 뿜어내라, 계속 뿜어내!', `MaleText_loc4`='血流不止，血流不止！', `MaleText_loc5`='不斷地跳動，不斷地跳動!', `MaleText_loc7`='¡Siempre bombea, siempre bombea!', `FemaleText_loc1`='계속 뿜어내라, 계속 뿜어내!', `FemaleText_loc4`='血流不止，血流不止！', `FemaleText_loc5`='不斷地跳動，不斷地跳動!', `FemaleText_loc7`='¡Siempre bombea, siempre bombea!' WHERE `ID`=58367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 따뜻해. 너무 붉어!', `MaleText_loc4`='如此温热，如此鲜红！', `MaleText_loc5`='好溫暖，好紅啊!', `MaleText_loc7`='¡Qué cálida! ¡Qué roja!', `FemaleText_loc1`='너무 따뜻해. 너무 붉어!', `FemaleText_loc4`='如此温热，如此鲜红！', `FemaleText_loc5`='好溫暖，好紅啊!', `FemaleText_loc7`='¡Qué cálida! ¡Qué roja!' WHERE `ID`=58368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 많은 야크를 혼자서 어떻게 끌어모을지 막막해요. 야운골은 위험한 족속이거든요.', `MaleText_loc4`='我实在不知道自己该怎么把这么多牦牛赶到一起。那些野牛人危险得很。', `MaleText_loc5`='老實說，我不知道靠我自己該怎麼圍捕那麼多犛牛。那些揚古很危險。', `MaleText_loc7`='Sinceramente, no sé cómo me las voy a apañar yo solo para reunir a los yaks. Estos yaungol son peligrosos.' WHERE `ID`=58369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 쳐들어온 게 더 나쁜 일의 전조가 아니었으면 좋겠어요. 야운골만으로 충분히 골치 아프니까요.', `MaleText_loc4`='希望野牛人的到来不是更大厄运来临前的先兆。这些野牛人已经够麻烦了。', `MaleText_loc5`='我希望揚古的出現不是發生什麼更大災難的前兆。這些揚古已經夠糟糕了。', `MaleText_loc7`='Espero que la llegada de los yaungol no fuera una señal de que las cosas van a empeorar. Ya están bastante mal.' WHERE `ID`=58370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지 말씀으로는 더한 일도 있었다고 해요. 하지만 그건 아마 고조 할아버지 때 얘기일 거예요.$b$b제가 겪은 일 중에 제일 나쁜 일은, 야크한테서 냄새가 덜 난다며 그루멀이 화를 낸 일이었단 말이에요.', `MaleText_loc4`='爸爸说我们还遇到过更糟的。但他所谓的“我们”，指的是他爷爷的爷爷了。$b$b我所遇到的最糟糕的事，就是一个土地精因为他的牦牛还不够臭而大发雷霆。', `MaleText_loc5`='老爹說我們曾碰過更糟的狀況，但當他說「我們」的時候，他的意思是他曾曾曾祖父那一代。$b$b我這輩子遇過最糟的情況也不過是一個咕嚕摩大發脾氣，因為他的犛牛聞起來不夠臭。', `MaleText_loc7`='Papá dice que hemos superado cosas peores. Pero cuando dice "hemos" se refiere a su tatatatarabuelo.$b$bA lo peor que nos hemos tenido que enfrentar ha sido a un grúmel enfadado porque su yak no apestaba lo suficiente.' WHERE `ID`=58371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산 요마들은 아주 못됐어요. 장난이라고 치는 게 진짜로 위험하다고요.', `MaleText_loc4`='高山树精是种卑劣的生物。它们的恶作剧真能伤到人。', `MaleText_loc5`='山妖精是惡劣的生物。他們的惡作劇會真的讓人受傷。', `MaleText_loc7`='Los duendes de las montañas son criaturas despiadadas. Sus bromas pueden hacer daño a la gente.' WHERE `ID`=58372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지는 저더러 할아버지를 본받으라고 자꾸 말씀하세요. 하지만 할아버지는 제가 태어나기도 전에 야크 떼에게 밟혀서 돌아가셨어요.', `MaleText_loc4`='爸爸总说要我变得跟爷爷一样，但爷爷早在我出生之前就死于一次牦牛踩踏事故了。', `MaleText_loc5`='老爹一直告訴我，我必須多像我爺爺一點。但他在我出生前就被犛牛踩扁了。', `MaleText_loc7`='Papá no deja de repetirme que debo parecerme más a mi abuelo. Pero murió antes de que yo naciera, en una estampida de yaks.' WHERE `ID`=58373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주세요! 잃어버린 야크를 찾다가 요마들한테 잡혔어요.', `MaleText_loc4`='拜托了！你能帮帮我吗？这些树精在我寻找走失的牦牛时绑架了我。', `MaleText_loc5`='拜託!你能不能幫幫我!這些妖精在我尋找走失犛牛的時候把我抓住了。', `MaleText_loc7`='¡Por favor! ¡Ayúdame! Los duendes me atraparon mientras buscaba a unos yaks que se habían perdido.' WHERE `ID`=58374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 우리 사업이 망하다가 살아났어요.$b$b이제 야운골의 공격이 주춤하니 우리끼리 감당할 수 있을 거예요.', `MaleText_loc4`='你不知道你帮了我们多大的忙，是你挽救了我们的家族生意。$b$b既然野牛人减缓了攻势，我自己应该能应付了。', `MaleText_loc5`='你肯定不知道你的協助對我們的家族事業有多大的意義。$b$b只要揚古減緩攻擊，我接下來應該就能自己處理了。', `MaleText_loc7`='No te haces una idea de lo que ha significado tu ayuda para salvar el negocio familiar.$b$bCreo que ya puedo encargarme yo, siempre y cuando los yaungol disminuyan sus ataques.' WHERE `ID`=58375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림 장군님께서 보급 상황을 확인하고 싶어하십니다.', `MaleText_loc4`='纳兹戈林将军想要了解补给品的现状。', `MaleText_loc5`='納茲格寧姆將軍想要知道補給物資的狀況。', `MaleText_loc7`='El general Nazgrim quiere saber en qué estado se encuentran los suministros.', `FemaleText_loc1`='나즈그림 장군님께서 보급 상황을 확인하고 싶어하세요.', `FemaleText_loc4`='纳兹戈林将军想要了解补给品的现状。', `FemaleText_loc5`='納茲格寧姆將軍想要知道補給物資的狀況。', `FemaleText_loc7`='El general Nazgrim quiere saber en qué estado se encuentran los suministros.' WHERE `ID`=58376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 고마워요! 야크 세척장에서 만나요.', `MaleText_loc4`='多谢你救了我，陌生人！我们在洗牛站再见吧。', `MaleText_loc5`='陌生人，謝謝你救了我!我們到清洗場見了。', `MaleText_loc7`='¡Gracias por rescatarme, $gforastero:forastera;! Te veré en el lavadero de yaks.' WHERE `ID`=58377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 많은 요마를 한 번에 쓸어 버리다니, 정말 대단하네요.', `MaleText_loc4`='你刚才可是干掉了不少树精啊。', `MaleText_loc5`='你解決的妖精數量可真是驚人。', `MaleText_loc7`='Acabas de segar a un número impresionante de duendes.' WHERE `ID`=58378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 신념은 완벽하다. 우리와 함께 한다면 살려주마.', `MaleText_loc4`='原则是绝对的，照做，你便会得到接纳。', `MaleText_loc5`='規矩是絕對的。遵從規矩，你就會被接受。', `MaleText_loc7`='El principio es absoluto, síguelo y serás aceptado.' WHERE `ID`=58379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 붉은십자군뿐! 우리와 함께하지 않는 자들은 패망하리라!', `MaleText_loc4`='只有十字军才是真理！顺我者昌，逆我者亡！', `MaleText_loc5`='十字軍就是一切!不順從我們的，就要毀滅!', `MaleText_loc7`='¡Solo importa la Cruzada! ¡Todo el que no esté con nosotros, caerá!' WHERE `ID`=58380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 복스러운 야크 냄새가 여기까지 나네요. 잘 왔어요, $p. 대가로 어마어마한 복을 드릴게요.', `MaleText_loc4`='喔，我在这儿就能闻到你的牦牛身上的好运气了。过来，$pc，我会给你许多财富作为回报的。', `MaleText_loc5`='喔，我在這裡就能聞到你犛牛的好運。來吧，$pc，我會給你更多好運做回報。', `MaleText_loc7`='Ooh, puedo oler la suerte de tus yaks desde aquí. Acércate, $pc, y te daré buena fortuna a cambio.' WHERE `ID`=58381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크를 잃어버렸습니다.', `MaleText_loc4`='我的牦牛走失了。', `MaleText_loc5`='我的犛牛不見了。', `MaleText_loc7`='He perdido a mis yaks.', `FemaleText_loc1`='야크를 잃어버렸어요.', `FemaleText_loc4`='我的牦牛走失了。', `FemaleText_loc5`='我的犛牛不見了。', `FemaleText_loc7`='He perdido a mis yaks.' WHERE `ID`=58382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마요. 녀석들은 이미 여기로 돌아 왔으니까요.', `MaleText_loc4`='别担心。这些小家伙似乎已经找到回来的路了。', `MaleText_loc5`='別擔心，這些小東西似乎可以自己找到路回家。', `MaleText_loc7`='No te preocupes. Parece que estos pequeños han encontrado el camino de vuelta ellos solos.' WHERE `ID`=58383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마요. 녀석들은 이미 여기로 돌아 왔으니까요. 자, 그럼 다시 가세요.', `MaleText_loc4`='别担心。小家伙们似乎已经找到回来的路了。去吧。', `MaleText_loc5`='別擔心，這些小東西似乎可以自己找到路回家。你看吧。', `MaleText_loc7`='No te preocupes. Parece que los pequeños han encontrado el camino de vuelta ellos solos. Aquí tienes.' WHERE `ID`=58385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 구하는 답이 나를 피하는군...$b$b$c, 숲을 보려면 나무에서 한 걸음 물러나야 하는 때도 있는 법이네.', `MaleText_loc4`='我一直找不到答案……$b$b$c，有时候你必须后退几步，才能看到整片森林。', `MaleText_loc5`='我所追尋的答案蒙蔽了我的眼睛...$b$b有時候，$c，你必須在樹前退後一步，才能看見整片森林。', `MaleText_loc7`='La respuesta que busco se me escapa...$b$bA veces, $c, uno debe alejarse del árbol para ver el bosque.' WHERE `ID`=58386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 시력을 잃었지만, 다행히 오감 모두를 만족시키는 땅에 살고 있네.', `MaleText_loc4`='我的视力可能不行了，但幸运的是，我生活在一个到处都充满了感知的土地上。', `MaleText_loc5`='雖然我看不見了，但我很幸運能居住在一塊各種感官都能派上用場的土地上。', `MaleText_loc7`='Puede que haya perdido la vista, pero tengo suerte de vivir en una tierra que deleita todos los sentidos.' WHERE `ID`=58389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 상관할 일이 아니다, $p! 너는 보내 주마.', `MaleText_loc4`='这不关你的事，$p！我会允许你离开。', `MaleText_loc5`='$p，這跟你沒有關係!我允許你離開。', `MaleText_loc7`='¡Esto no es de tu incumbencia, $p! Te dejaré marchar.' WHERE `ID`=58390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 폭발시켜라. 나를 죽임으로써 나의 존재를 인정해라.', `MaleText_loc4`='释放你的怒火吧。杀了我，证明我存在的意义。', `MaleText_loc5`='釋放你的怒氣。殺了我，並藉此證明我的存在。', `MaleText_loc7`='Libera tu odio. Acaba conmigo y legitima así mi existencia.' WHERE `ID`=58391;
