UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 밖에 누구니, 샤오? 밖은 안전하니?', `FemaleText_loc4`='邵傲，谁在外面？安全吗？', `FemaleText_loc5`='誰在那裡，邵?外面安全嗎?', `FemaleText_loc7`='¿Quién hay ahí, Shao? ¿Es seguro?' WHERE `ID`=58398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 준비가 됐어.', `MaleText_loc4`='我做好出发的准备了。', `MaleText_loc5`='我準備好離開了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='떠날 준비가 됐어.', `FemaleText_loc4`='我做好出发的准备了。', `FemaleText_loc5`='我準備好離開了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=58399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크가 뻗대기 시작했습니다. 라오 부자의 야크 세척장으로 돌아가십시오.', `MaleText_loc4`='你的牦牛开始反抗了。返回父子洗牛站。', `MaleText_loc5`='你的犛牛開始反抗了。回去勞記犛牛清洗場吧', `MaleText_loc7`='Tu yak empieza a tambalearse. Vuelve al lavadero de Yaks Lao e Hijo.', `FemaleText_loc1`='야크가 뻗대기 시작했습니다. 라오 부자의 야크 세척장으로 돌아가십시오.', `FemaleText_loc4`='你的牦牛开始反抗了。返回父子洗牛站。', `FemaleText_loc5`='你的犛牛開始反抗了。回去勞記犛牛清洗場吧', `FemaleText_loc7`='Tu yak empieza a tambalearse. Vuelve al lavadero de Yaks Lao e Hijo.' WHERE `ID`=58400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 말씀하십시오, 친구. 마감이 얼마 남지 않았습니다.', `MaleText_loc4`='动作快点，伙计。我们一定要赶上最后期限。', `MaleText_loc5`='快點，兄弟。我們在趕期限。', `MaleText_loc7`='Date prisa, colega. Tenemos que cumplir una fecha de entrega.' WHERE `ID`=58401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는 잠시 뒤로 한 걸음 물러나서, 더 큰 목표에 대해 생각해 보는 것도 좋네.', `MaleText_loc4`='有时后退一步，将目光放在长远目标上，还是大有裨益的。', `MaleText_loc5`='有時候退一步，更能清楚看見我們的大目標。', `MaleText_loc7`='A veces conviene dar un paso atrás y reflexionar sobre los objetivos más importantes.' WHERE `ID`=58402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금까지 정말 오랫동안 꾸준히 작업한 끝에, 마침내 조각상이 거의 완성됐어요.', `FemaleText_loc4`='我们在这里的工作一成不变且沉闷冗长，但雕像已经快接近完工了。', `FemaleText_loc5`='我們在這裡的工作穩定又沈悶，但雕像幾乎快要完成了。', `FemaleText_loc7`='Nuestro trabajo ha sido constante y tedioso, pero la estatua ya casi está acabada.' WHERE `ID`=58403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐 동안 조각상을 한번 바라보세요. 백 년 동안의 노력이 만들어 낸 경이로운 작품이에요.', `FemaleText_loc4`='花点时间仔细瞧瞧这座宏伟的雕像吧，它可是耗费了近百年的人力所创造出来的奇迹。', `FemaleText_loc5`='花點時間看看這座雕像，這是累積了一百年的勞動力才完成的奇觀。', `FemaleText_loc7`='Tómate un segundo y mira la estatua. Esta maravilla es la culminación de cientos de años de trabajo.' WHERE `ID`=58404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것이 필요하십니까?', `MaleText_loc4`='要搭便车吗？', `MaleText_loc5`='想直接升到雕像頂上嗎?', `MaleText_loc7`='¿Necesitas subir?' WHERE `ID`=58405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 아버지와 아버지의 아버지도 이 조각상을 세우는 데 일생을 바쳤습니다. 이걸 마무리하는 것이 제가 된다니, 정말 자랑스러운 일입니다.', `MaleText_loc4`='我父亲和我爷爷将毕生的精力都花费在这座宏伟的雕像上。作为收官之人，我感到非常自豪。', `MaleText_loc5`='我父親和我父親的父親花了一輩子在這雕像上賣力。我很榮幸能成為完成它的那一代人。', `MaleText_loc7`='Mi padre y el padre de mi padre invirtieron sus vidas trabajando duro en esta estatua. Estoy orgulloso de ser el que la termine.' WHERE `ID`=58406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘든 일이지만 꼭 필요한 일이기도 합니다. 이 조각상은 우리 믿음의 상징이니까요.', `MaleText_loc4`='工作虽然艰辛，但还是很有必要的。这座雕像代表了我们的信仰。', `MaleText_loc5`='工作很辛苦，但也是必要的。這雕像代表了我們所信仰的一切。', `MaleText_loc7`='Este trabajo es duro, pero necesario. La estatua representa todo en lo que creemos.' WHERE `ID`=58407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취가 몇 수레만 더 도착하면, 용이 완성될 것입니다.', `MaleText_loc4`='再有一些玉石，这条龙就完成了。', `MaleText_loc5`='只需要最後幾車玉石，玉蛟雕像就完成了。', `MaleText_loc7`='Unos cuantos envíos de jade más y terminaremos el dragón.' WHERE `ID`=58408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상만 완성되면 편히 쉴 수 있을 겁니다.', `MaleText_loc4`='雕像完成后再休息一下应该会很不错。', `MaleText_loc5`='完成雕像後，休息起來會特別舒適。', `MaleText_loc7`='Cuando la estatua esté acabada nos vendrá bien un buen descanso.' WHERE `ID`=58409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리 일이 끝나는 날이 머지 않았습니다.', `MaleText_loc4`='离我们完成任务的日子已经不远了。', `MaleText_loc5`='再過不久，我們的工作便完成了。', `MaleText_loc7`='No tardaremos mucho en terminar el trabajo.' WHERE `ID`=58410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각상이 완성되는 날, 우리 가족은 호화로운 축하연을 열 겁니다.', `MaleText_loc4`='我的家族正在策划一场盛大的宴会，来庆祝雕像的落成。', `MaleText_loc5`='我的家族打算舉辦盛大宴會來慶祝雕像完成。', `MaleText_loc7`='Mi familia planea celebrar un gran banquete cuando terminemos la estatua.' WHERE `ID`=58411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근무 시간이 아직 안 끝났습니까? 새벽의 꽃에 있는 술 취한 호젠이 저를 부르고 있습니다.', `MaleText_loc4`='今天的工作结束了吗？晨芳园里的醉猴楼正在向我招手呢。', `MaleText_loc5`='工作時段結束了沒有?晨綻裡的醉猴樓正呼喚我的名字。', `MaleText_loc7`='¿Ya se ha terminado la jornada laboral? El Hozen Beodo de Floralba me espera.' WHERE `ID`=58412;
