UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깜박한 거냐, 아가야? 나는 암흑스승이다! 언데드를 지배하지!', `MaleText_loc4`='你忘了吗，小女孩？我是黑暗院长！我统御着亡者！', `MaleText_loc5`='你難道忘了嗎，女孩?我是黑暗院長!我指揮不死生物!', `MaleText_loc7`='¿Ya lo olvidaste, niña? ¡Soy el maestro oscuro! ¡Los no-muertos me obedecen!' WHERE `ID`=58421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 네 귀여운 검 끝을 손님들을 향해 돌리고 그들의 뼈를 발라 와라!', `MaleText_loc4`='现在用你可爱的符文剑对准客人们，取来他们的骨头！', `MaleText_loc5`='現在用你的符文刃招呼來賓吧，把他們的骨頭交給我!', `MaleText_loc7`='Ahora usa tus preciosas hojarrunas contra los invitados, ¡y tráeme sus huesos!' WHERE `ID`=58422;
