UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐, 이방인이야. 저분이 우리를 야운골에게서 구해줄까?', `MaleText_loc4`='看呐，是个陌生人。不知道$g他:她;是不是来帮我们摆脱野牛人的。', `MaleText_loc5`='看。是個陌生人。不知道$g他:她;是不是來這從揚古手中拯救我們。', `MaleText_loc7`='Mira. $GUn extranjero:Una extranjera;. Me pregunto si ha venido a salvarnos de los yaungol.', `FemaleText_loc1`='봐요, 이방인이에요. 저분이 우리를 야운골에게서 구해줄까요?', `FemaleText_loc4`='看呐，是个陌生人。不知道$g他:她;是不是来帮我们摆脱野牛人的。', `FemaleText_loc5`='看。是個陌生人。不知道$g他:她;是不是來這從揚古手中拯救我們。', `FemaleText_loc7`='Mira. $GUn extranjero:Una extranjera;. Me pregunto si ha venido a salvarnos de los yaungol.' WHERE `ID`=58427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿, 외지인이야.', `MaleText_loc4`='嘘，有个外乡人。', `MaleText_loc5`='噓，有外人。', `MaleText_loc7`='Sssh, $gun forastero:una forastera;.', `FemaleText_loc1`='쉿, 외지인이에요.', `FemaleText_loc4`='嘘，有个外乡人。', `FemaleText_loc5`='噓，有外人。', `FemaleText_loc7`='Sssh, $gun forastero:una forastera;.' WHERE `ID`=58428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 강해 보이는걸. 야운골을 몰아낼 정도로 강할지도 몰라!', `MaleText_loc4`='$g他:她;看上去相当强大。也许强大到能赶走野牛人！', `MaleText_loc5`='$G他:她;看起來非常強大。或許強到足以把揚古趕回去!', `MaleText_loc7`='Parece muy $gpoderoso:poderosa;. ¡Quizás lo suficiente como para rechazar a los yaungol!', `FemaleText_loc1`='꽤 강해 보이는걸요. 야운골을 몰아낼 정도로 강할지도 몰라요!', `FemaleText_loc4`='$g他:她;看上去相当强大。也许强大到能赶走野牛人！', `FemaleText_loc5`='$G他:她;看起來非常強大。或許強到足以把揚古趕回去!', `FemaleText_loc7`='Parece muy $gpoderoso:poderosa;. ¡Quizás lo suficiente como para rechazar a los yaungol!' WHERE `ID`=58429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡으로 후퇴해야 할지도 모르겠어. 이곳의 집을 버리고 싶진 않은데.', `MaleText_loc4`='我们也许得撤退到四风谷。可我不想放弃这里的家园。', `MaleText_loc5`='我們可能得撤退到四風峽。我真不想放棄我在這裡的家。', `MaleText_loc7`='Es posible que debamos retirarnos al Valle de los Cuatro Vientos. No quiero abandonar mi hogar aquí.', `FemaleText_loc1`='네 바람의 계곡으로 후퇴해야 할지도 모르겠어요. 이곳의 집을 버리고 싶진 않은데.', `FemaleText_loc4`='我们也许得撤退到四风谷。可我不想放弃这里的家园。', `FemaleText_loc5`='我們可能得撤退到四風峽。我真不想放棄我在這裡的家。', `FemaleText_loc7`='Es posible que debamos retirarnos al Valle de los Cuatro Vientos. No quiero abandonar mi hogar aquí.' WHERE `ID`=58430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이야. 정말 특이하게 생겼는걸. 빤히 쳐다 보진 말고!', `MaleText_loc4`='是个外乡人。$g他:她;看上去古怪得很。别盯着看！', `MaleText_loc5`='是個外國人。$G他:她;的外表非常奇特。不要盯著看!', `MaleText_loc7`='$GUn extranjero:Una extranjera;. Parece muy $gexótico:exótica;. ¡No te quedes mirando!', `FemaleText_loc1`='이방인이에요. 정말 특이하게 생겼는걸요. 빤히 쳐다 보진 말고요!', `FemaleText_loc4`='是个外乡人。$g他:她;看上去古怪得很。别盯着看！', `FemaleText_loc5`='是個外國人。$G他:她;的外表非常奇特。不要盯著看!', `FemaleText_loc7`='$GUn extranjero:Una extranjera;. Parece muy $gexótico:exótica;. ¡No te quedes mirando!' WHERE `ID`=58431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 구하러 오셨습니까, $c님?', `MaleText_loc4`='你是来救我们的吗，$c？', `MaleText_loc5`='這位$c，你是來救我們的嗎?', `MaleText_loc7`='¿Has venido a salvarnos, $c?', `FemaleText_loc1`='우릴 구하러 오셨나요, $c님?', `FemaleText_loc4`='你是来救我们的吗，$c？', `FemaleText_loc5`='這位$c，你是來救我們的嗎?', `FemaleText_loc7`='¿Has venido a salvarnos, $c?' WHERE `ID`=58432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r $c치고도 정말 이상한 차림새인걸.', `MaleText_loc4`='真是奇装异服，在我看来，即便是对于一个$r$c来说也有点过了。', `MaleText_loc5`='如果你問我，我認為即使用$r$c的標準來看，他的打扮仍然很怪。', `MaleText_loc7`='Vaya forma de vestir... incluso para $gun:una; $r $c.', `FemaleText_loc1`='$r $c치고도 정말 이상한 차림새인걸요.', `FemaleText_loc4`='真是奇装异服，在我看来，即便是对于一个$r$c来说也有点过了。', `FemaleText_loc5`='如果你問我，我認為即使用$r$c的標準來看，他的打扮仍然很怪。', `FemaleText_loc7`='Vaya forma de vestir... incluso para $gun:una; $r $c.' WHERE `ID`=58433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 뭐라든 상관없어. 저 $c|1이;가; 우릴 도우러 왔다면, 양팔 벌려 환영해야 마땅하지!', `MaleText_loc4`='我不在乎你说什么。如果那个$c是来帮我们的，我想我们会展开双臂热情欢迎$g他:她;！', `MaleText_loc5`='我不在乎你怎麼說。如果那個$c是來這裡幫我們的，照我說我們就該展開雙臂歡迎$g他:她;!', `MaleText_loc7`='Tú dirás lo que quieras. ¡Si $gese:esa; $c ha venido a ayudarnos, yo digo que le demos la bienvenida y $glo:la; recibamos con los brazos abiertos!', `FemaleText_loc1`='당신이 뭐라든 상관없어요. 저 $c|1이;가; 우릴 도우러 왔다면, 양팔 벌려 환영해야 마땅하죠!', `FemaleText_loc4`='我不在乎你说什么。如果那个$c是来帮我们的，我想我们会展开双臂热情欢迎$g他:她;！', `FemaleText_loc5`='我不在乎你怎麼說。如果那個$c是來這裡幫我們的，照我說我們就該展開雙臂歡迎$g他:她;!', `FemaleText_loc7`='Tú dirás lo que quieras. ¡Si $gese:esa; $c ha venido a ayudarnos, yo digo que le demos la bienvenida y $glo:la; recibamos con los brazos abiertos!' WHERE `ID`=58434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취! 비취가 문제입니다! 우린 비취가 필요하다고요! 그게 전부입니다!', `MaleText_loc4`='玉石，一切都是为了玉石！我们需要玉石，这是底线！', `MaleText_loc5`='玉，全都是玉的問題!我們需要玉，就是這樣!', `MaleText_loc7`='¡Jade! ¡Solo importa el jade! ¡Lo necesitamos y punto!' WHERE `ID`=58435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 부족 사태는 황금빛 가을의 대공황 이후 가장 끔찍한 사건입니다. 공사가 벌써 몇 달이나 늦어졌어요. 옥룡 님이 젊어지실 것도 아닌데!', `MaleText_loc4`='目前的玉石短缺是自金秋危机最严重的麻烦。工程进度已经落后好几个月了。青龙正在日益衰老！', `MaleText_loc5`='玉礦短缺是繼黃金秋危機之後最糟糕的問題。產量已經落後好幾個月了，蛟龍的年紀也會越來越大!', `MaleText_loc7`='La escasez de jade es el peor acontecimiento desde la crisis del otoño dorado. La producción lleva meses de retraso. ¡El dragón se va a morir del aburrimiento!' WHERE `ID`=58436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상품을 보여 주십시오.', `MaleText_loc4`='让我看看你的货物。', `MaleText_loc5`='讓我看看你的東西。', `MaleText_loc7`='Enséñame tu mercancía.', `FemaleText_loc1`='상품을 보여 주세요.', `FemaleText_loc4`='让我看看你的货物。', `FemaleText_loc5`='讓我看看你的東西。', `FemaleText_loc7`='Enséñame tu mercancía.' WHERE `ID`=58437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 물건 사면 복이 오고, 그냥 가면 복이 달아나요.', `MaleText_loc4`='聪明的幸运儿会来选购我的货物。只有倒霉蛋才会匆匆走开。', `MaleText_loc5`='買一個幸運星是明智的選擇。那些不買就直接走開的人會有惡運。', `MaleText_loc7`='Un grisgrís haría bien en comprar mis mercancías. Mala suerte si no lo haces.' WHERE `ID`=58438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 멋진 금속 조각을 갖고 있네. 난 강철 조각을 좋아하거든.', `MaleText_loc4`='噢，你手里拿的可是块上佳的金属啊。我对精良的钢材总是相当钟爱。', `MaleText_loc5`='喔你擁有一塊品質優良的金屬片呢。我非常喜歡一塊優質的鋼鐵片。', `MaleText_loc7`='Oh, menuda joya de metal que tienes ahí. Me encanta el buen acero.' WHERE `ID`=58439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈안 마을에 잘 왔네, $c. 부디... 우리를 도와주게.', `MaleText_loc4`='欢迎来到滨岸村，$c。我求你……帮帮我们吧。', `MaleText_loc5`='$c，歡迎來到濱南村。我求求你...拜託幫幫我們。', `MaleText_loc7`='$GBienvenido:Bienvenida; a la Aldea Binan, $c. Te lo imploro... ayúdanos, por favor.' WHERE `ID`=58440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 비취가 있습니다.', `MaleText_loc4`='我把你的玉石送来了。', `MaleText_loc5`='我這裡有你要的玉。', `MaleText_loc7`='Aquí está tu jade.', `FemaleText_loc1`='여기 비취가 있어요.', `FemaleText_loc4`='我把你的玉石送来了。', `FemaleText_loc5`='我這裡有你要的玉。', `FemaleText_loc7`='Aquí está tu jade.' WHERE `ID`=58441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취가 필요하다고 말씀하셨습니까?', `MaleText_loc4`='好像有人说过想要玉石？', `MaleText_loc5`='有人提到他需要玉嗎?', `MaleText_loc7`='¿Alguien ha dicho que necesitaba jade?', `FemaleText_loc1`='비취가 필요하다고 말씀하셨나요?', `FemaleText_loc4`='好像有人说过想要玉石？', `FemaleText_loc5`='有人提到他需要玉嗎?', `FemaleText_loc7`='¿Alguien ha dicho que necesitaba jade?' WHERE `ID`=58442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신께 드릴 비취를 가져왔습니다.', `MaleText_loc4`='我有一块玉石要交给你。', `MaleText_loc5`='我有一批玉要交給你。', `MaleText_loc7`='Tengo un cargamento de jade para ti.', `FemaleText_loc1`='당신께 드릴 비취를 가져왔어요.', `FemaleText_loc4`='我有一块玉石要交给你。', `FemaleText_loc5`='我有一批玉要交給你。', `FemaleText_loc7`='Tengo un cargamento de jade para ti.' WHERE `ID`=58443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 당신을 위해 비취를 가져왔습니다.', `MaleText_loc4`='我给你送了一批新玉石来。', `MaleText_loc5`='我這邊有一批新來的玉礦。', `MaleText_loc7`='Tengo un nuevo envío de jade para ti.', `FemaleText_loc1`='여기, 당신을 위해 비취를 가져왔어요.', `FemaleText_loc4`='我给你送了一批新玉石来。', `FemaleText_loc5`='我這邊有一批新來的玉礦。', `FemaleText_loc7`='Tengo un nuevo envío de jade para ti.' WHERE `ID`=58444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑스럽고 아름다워! 아참, 시간이 있으면 옥룡사도 방문해 보게. 그러면 이 거대한 조각상이 우리 삶의 방식에 왜 중요한지 알게 될 테니까.', `MaleText_loc4`='太好了，太棒了！如果你有时间，应该去看看青龙寺。这样，你才能进一步了解我们伟大的雕像，以及它对我们的重要性。', `MaleText_loc5`='太棒了，美極啦!若有時間，你應該去拜訪玉蛟寺。或許你會更深入理解我們的偉大玉像，和它對我們生活之道的重要性。', `MaleText_loc7`='¡Espléndido, maravilloso! Si tienes tiempo, deberías visitar también el Templo del Este. Así aprenderás más sobre la gran estatua y lo importante que es para nuestra forma de vida.' WHERE `ID`=58445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑스럽고 아름다워! 아, 벌써 옥룡사에 다녀왔나? 그러면 이 거대한 조각상이 우리 삶의 방식에 왜 중요한지 알고 있겠군.', `MaleText_loc4`='太好了，太棒了！我看你已经去过青龙寺了。那你应该明白，这座雕像为何对我们如此重要。', `MaleText_loc5`='太棒了，美極啦!看來你已經拜訪過玉蛟寺了。所以你能理解為什麼這尊雕像對我們的生活之道來說如此重要。', `MaleText_loc7`='¡Espléndido, maravilloso! Veo que ya has visitado el Templo del Este. Por tanto, comprenderás lo por qué esta estatua es tan importante para nuestra forma de vida.' WHERE `ID`=58446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그루멀과 술을 마실 땐 쉬면 안 돼요. 그러면 아마 그루멀이 먼저 뻗어 버릴 거예요.', `FemaleText_loc4`='跟土地精拼酒的诀窍就是不能停。幸运的话，他们总会在你之前醉倒。', `FemaleText_loc5`='跟咕嚕摩拼酒的竅門就是不要停。如果運氣好，他們會先你一步昏倒。', `FemaleText_loc7`='El truco para beber con los grúmel es no parar. Con suerte se desmayarán antes que tú.' WHERE `ID`=58447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! 지금 절 구원해 주신 것이나 마찬가지입니다, $n 님. 이야호! 아름답게 빛나는 걸 좀 보십시오.', `MaleText_loc4`='难以置信！你刚刚救了我的小命，$n。嚯嚯，你看看这光泽。', `MaleText_loc5`='真不敢相信!你保住了我的腦袋，$n。喔喔，看看這個光澤。', `MaleText_loc7`='¡Increíble! Me acabas de salvar el cuello, $n. Guau, observa este fulgor.' WHERE `ID`=58448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭해요! 한번 보세요. 옥룡 님을 위한 이 놀라운 기념비를 제작하는 데 백 년이 걸렸어요. 물론 당신도 이 걸작을 완성하는 데 크게 기여하셨고요.', `FemaleText_loc4`='太好了！瞧瞧它，花了整整一百年的时间才建起如此宏伟的青龙雕像。现在，你也为这个杰作贡献了一份力量。', `FemaleText_loc5`='太棒了!看看它。人們花費了百年光陰為玉蛟打造出的壯麗紀念碑，而如今，你也對這傑作貢獻了一份心力。', `FemaleText_loc7`='¡Maravilloso! Contémplalo. Cien años para construir este increíble monumento dedicado al Dragón de Jade. Y ahora tú también puedes decir que has contribuido en esta obra maestra.' WHERE `ID`=58449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 결실을 맺을 날이 얼마 남지 않았어요.', `FemaleText_loc4`='快了，快了，很快就要完成了。', `FemaleText_loc5`='很快，很快就要完成了，一切辛苦都會得到回報。', `FemaleText_loc7`='Pronto veremos que todo esto ha merecido la pena.' WHERE `ID`=58450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취가 도착할 시간이 됐다 했습니다. 광산에 문제가 생겼다는 이야기를 듣기는 했습니다만, 그렇다고 우리 일이 늦춰져서는 안 됩니다.', `MaleText_loc4`='下一批货应该已经送到了才对。我听说矿山那里出了麻烦，可我们的工作是不能拖延的。', `MaleText_loc5`='接近我們收到另一批貨物的時間了。我聽說礦坑那裡遇到了一些麻煩，但我們的工作不能停滯。', `MaleText_loc7`='Ya era hora de que nos enviaran otra entrega. He oído que estaban teniendo problemas en las minas, pero nuestro trabajo no puede interrumpirse.' WHERE `ID`=58451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붓으로 그린 선 하나에도 천 가지 의미가 담겨 있네.', `MaleText_loc4`='每一笔、每一画，都包含着千层含义。', `MaleText_loc5`='每一筆劃都蘊含著上千種意涵。', `MaleText_loc7`='Cada trazo significa miles de cosas.' WHERE `ID`=58452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한창 때 강한 힘이 담긴 글을 많이 남겼었지만, 가장 강한 게 무엇인지는 알지 못한다네.', `MaleText_loc4`='在我一生中，曾写下过无数强大的真言。可对于最强大的真言，我始终未窥门径。', `MaleText_loc5`='我一整輩子曾寫下許多箴言，但我始終寫不出影響最深遠的箴言。', `MaleText_loc7`='He escrito muchas palabras convincentes en mis días, pero, aun así, la más convincente escapa a mi entendimiento.' WHERE `ID`=58453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 혼자서 일하는 편을 좋아하네.', `MaleText_loc4`='我更喜欢独自工作。', `MaleText_loc5`='我偏好獨自工作。', `MaleText_loc7`='Prefiero trabajar en solitario.' WHERE `ID`=58454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 무엇을 도와드릴까요?', `MaleText_loc4`='你想来点什么？', `MaleText_loc5`='我能給你來些什麼?', `MaleText_loc7`='¿Qué puedo hacer por ti?' WHERE `ID`=58455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주하기 딱 좋은 날씨 아닙니까? 어떻게 생각하세요?', `MaleText_loc4`='对一个种族来说，这是伟大的一天，你觉得呢？', `MaleText_loc5`='真是比賽的好天氣，你不覺得嗎?', `MaleText_loc7`='Hace un día perfecto para una carrera, ¿no crees?' WHERE `ID`=58456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끈하고, 신선하고, 맛있는 음식이 왔습니다! 여기서 간식을 사 가세요!', `MaleText_loc4`='新鲜美味，热气腾腾的饭菜！快来这里享用你的赛间快餐吧！', `MaleText_loc5`='熱騰騰、新鮮又美味的食物!把你的競賽點心拿過來!', `MaleText_loc7`='¡Caliente, fresco y delicioso! ¡Consigue tus aperitivos de carreras aquí!' WHERE `ID`=58457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굉장한 활약이었네, $n!', `MaleText_loc4`='你可真是惹人注目啊，$n！', `MaleText_loc5`='你的表現真是雄壯威武啊，$n!', `MaleText_loc7`='¡Eso ha sido impresionante, $n!' WHERE `ID`=58458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그걸세!', `MaleText_loc4`='我的$g小伙子:小姑娘;来了！', `MaleText_loc5`='這是我的$g兒子:女兒;!', `MaleText_loc7`='¡Así se hace!' WHERE `ID`=58459;
