UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 대장을 어떻게 무찔렀는지 한 번 더 이야기해 보게, $n.', `MaleText_loc4`='再给我们讲讲吧，你是怎么杀死野牛人战争领袖的，$n。', `MaleText_loc5`='$n，再跟我們說說你殺死揚古戰爭領袖的經歷。', `MaleText_loc7`='Cuéntanos otra vez cómo acabaste con el líder de guerra yaungol, $n.' WHERE `ID`=58461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 곳에 정착할 생각은 없나, $n? 자네 같이 강한 $c가 쿤라이 봉우리를 지켜 준다면 참 든든할 텐데 말이지.', `MaleText_loc4`='你想过要安定下来吗，$n？昆莱山正需要像你一样强大的$c守护者。', `MaleText_loc5`='$n，你有沒有考慮過定居下來?崑萊峰能用上你這樣厲害的$c做為保護者。', `MaleText_loc7`='¿Te has planteado la idea de asentarte, $n? A la Cima Kun-Lai le vendría de perlas tener a $gun poderoso:una poderosa; $c como $gprotector:protectora;.' WHERE `ID`=58462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 용기와 이타심은 처음 보네.', `MaleText_loc4`='我从没见过这般的壮举与无私。', `MaleText_loc5`='我從沒見過這樣英勇而無私的行為。', `MaleText_loc7`='Jamás he visto semejante heroicidad y altruismo.' WHERE `ID`=58463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔네! 새로운 소식이라도 있나, $n?', `MaleText_loc4`='欢迎回来！有什么消息吗，$n？', `MaleText_loc5`='歡迎回來!$n，最近過得怎樣?', `MaleText_loc7`='¡$GBienvenido:Bienvenida; otra vez! ¿Qué noticias traes, $n?' WHERE `ID`=58464;
