UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 혹시 이번 선거철에 지원 유세를 해줄 생각 없나?', `MaleText_loc4`='$n，不知你愿不愿意在下次选举时投我一票？', `MaleText_loc5`='$n，我在想，你願意在選舉的時候支持我嗎?', `MaleText_loc7`='¿Apoyarías mi candidatura en las siguientes elecciones, $n?' WHERE `ID`=58466;
