UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 문제가 있는 건 아니겠지, $c? 자네가 야운골 대장을 처치해 줄 걸로 우리 모두 믿고 있다네.', `MaleText_loc4`='一切都还好吗，$c？我们全靠你去消灭野牛人战争领袖了。', `MaleText_loc5`='$c，一切都還好吧?我們全都指望你來殺死揚古戰爭領袖。', `MaleText_loc7`='¿Todo bien, $c? Contamos contigo para acabar con el líder de guerra yaungol.' WHERE `ID`=58468;
