UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘엔 $n 님 같은 $c|1이;가; 참 드물어.', `MaleText_loc4`='你再也找不到像$n这样的$c了。', `MaleText_loc5`='像$n這樣的$c打著燈籠也找不著了。', `MaleText_loc7`='$n es $gun:una; $c de $glos:las; que ya no se ven.', `FemaleText_loc1`='요즘엔 $n 님 같은 $c|1이;가; 참 드물어요.', `FemaleText_loc4`='你再也找不到像$n这样的$c了。', `FemaleText_loc5`='像$n這樣的$c打著燈籠也找不著了。', `FemaleText_loc7`='$n es $gun:una; $c de $glos:las; que ya no se ven.' WHERE `ID`=58481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님은 안개 너머 먼 땅에서 오셨다고 하더라고. 이 먼 곳까지 오셔서 우릴 구해 주시다니, 그곳에서도 분명 영웅이셨을 거야.', `MaleText_loc4`='我听说$n是从迷雾那一边的遥远疆域来的。$g他:她;肯定是他们的英雄，不远千里前来搭救我们。', `MaleText_loc5`='我聽說$n是從迷霧另一頭的遙遠地方來的。$G他:她;一定是他們國家的$g英雄:女英雄;，大老遠過來拯救我們的。', `MaleText_loc7`='He oído que $n viene de una tierra lejana más allá de la niebla. Si ha venido hasta aquí para salvarnos, tiene que ser $gun héroe:una heroína;.', `FemaleText_loc1`='$n 님은 안개 너머 먼 땅에서 오셨다고 하더라고요. 이 먼 곳까지 오셔서 우릴 구해 주시다니, 그곳에서도 분명 영웅이셨을 거예요.', `FemaleText_loc4`='我听说$n是从迷雾那一边的遥远疆域来的。$g他:她;肯定是他们的英雄，不远千里前来搭救我们。', `FemaleText_loc5`='我聽說$n是從迷霧另一頭的遙遠地方來的。$G他:她;一定是他們國家的$g英雄:女英雄;，大老遠過來拯救我們的。', `FemaleText_loc7`='He oído que $n viene de una tierra lejana más allá de la niebla. Si ha venido hasta aquí para salvarnos, tiene que ser $gun héroe:una heroína;.' WHERE `ID`=58482;
