UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전사들이 당신 덕분에 살았다고 이야기하더군요. 감사합니다, $n 님.', `FemaleText_loc4`='战士们报告说是你救了他们。谢谢你，$n。', `FemaleText_loc5`='戰士們說你救了他們的命。謝謝你，$n', `FemaleText_loc7`='Los guerreros dicen que les has salvado la vida. Gracias, $n.' WHERE `ID`=58495;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이라면 늘 환영입니다, $n 님. 어떻게 지내셨나요?', `FemaleText_loc4`='见到你总是很高兴，$n。近来好吗？', `FemaleText_loc5`='$n，我總是很高興能見到你。你最近如何?', `FemaleText_loc7`='Siempre es bueno volver a verte, $n. ¿Cómo estás?' WHERE `ID`=58496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몸은 좀 어떠세요, $c님? 호랑이 연고가 더 필요한가요?', `FemaleText_loc4`='你感觉怎么样，$c？要再来点跌打酒吗？', `FemaleText_loc5`='$c，你感覺如何?需要更多跌打酒嗎?', `FemaleText_loc7`='¿Cómo te encuentras, $c? ¿Necesitas más Dit Da Jow?' WHERE `ID`=58497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 우리 모두에게 베푸신 아량과 친절은 놀라울 따름이에요.', `FemaleText_loc4`='你竟然对我们大家如此无私和仁慈，这令我感到很惊讶。', `FemaleText_loc5`='我非常驚訝，你對我們是如此無私而仁慈。', `FemaleText_loc7`='Me sorprende lo bien y desinteresadamente que te has portado con todos nosotros.' WHERE `ID`=58498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동료들은 좀 어떤가요, $n 님?', `FemaleText_loc4`='你的朋友们怎么样了，$n？', `FemaleText_loc5`='$n，你的朋友們過的如何啊?', `FemaleText_loc7`='¿Qué tal están tus amigos, $n?' WHERE `ID`=58499;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 오셨군요. $n 님은 언제든 환영이에요.', `FemaleText_loc4`='$g他:她;在那儿。这里随时欢迎你，$n。', `FemaleText_loc5`='$g他:她;來了。$n，我們隨時都歡迎你。', `FemaleText_loc7`='Aquí está. Siempre eres $gbienvenido:bienvenida;, $n.' WHERE `ID`=58500;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 마을에 오래 계실 건가요, $n 님? 최근의 무용담을 들려 주세요.', `FemaleText_loc4`='要在这里待上一阵子吗，$n？你一定给我讲讲你最近的壮举哦。', `FemaleText_loc5`='$n，你會在這待久一點嗎?你一定得跟我說說你最新的豐功偉業!', `FemaleText_loc7`='¿Te vas a quedar un tiempo, $n? Quiero saberlo todo sobre tus últimas hazañas.' WHERE `ID`=58501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모험으로 힘드실 테니, 푹 쉬셔야 해요.', `FemaleText_loc4`='你经历了那么多次冒险，现在该好好休息一下了，年轻的$g先生:女士;。', `FemaleText_loc5`='在經過這些冒險之後，你需要好好休息一下，$g小夥子:小姑娘;。', `FemaleText_loc7`='Después de todas esas aventuras, lo que necesitas es un buen descanso.' WHERE `ID`=58502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침 당신 생각을 하던 참이었어요, $n 님.', `FemaleText_loc4`='我刚才还在念叨你呢，$n。', `FemaleText_loc5`='$n，我正好想到你。', `FemaleText_loc7`='Precisamente estaba pensando en ti, $n.' WHERE `ID`=58503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨끗한 야크를 기르면 복이 와요. 게다가 내 특제 맥주를 먹이면 더 큰 복이 오죠. 그게 바로 코베야크를 기르는 비결이에요!', `MaleText_loc4`='能找到一头干净的牦牛可真是幸事。喂它喝我特制的佳酿则是更大的幸事。稞神牦牛就是这么制成的！', `MaleText_loc5`='擁有一隻乾淨的犛牛是很幸運的。要是能餵牠吃我的特釀啤酒，就更加幸運了。這就是養出柯布犛牛的方法!', `MaleText_loc7`='Tener un yak limpio es un grisgrís. Y todavía mayor grisgrís es alimentarlo con mi cerveza especial. ¡Así es como se consiguen los Kobeyaks!' WHERE `ID`=58504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀의 의지가 무너지는 것이 느껴진다... 그 영혼이 환하게 타오르는구나!', `MaleText_loc4`='我感到她的意志在破碎……她的灵魂在灼热地燃烧着。', `MaleText_loc5`='我感到她的意志正在崩潰...她的靈魂熾烈地燃燒。', `MaleText_loc7`='Siento cómo se quiebra su voluntad... cómo arde su alma.' WHERE `ID`=58505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 빼먹은 거지...', `MaleText_loc4`='我错过了什么……', `MaleText_loc5`='我錯過了什麼...', `MaleText_loc7`='Me falta algo...', `FemaleText_loc1`='뭘 빼먹은 거지...', `FemaleText_loc4`='我错过了什么……', `FemaleText_loc5`='我錯過了什麼...', `FemaleText_loc7`='Me falta algo...' WHERE `ID`=58506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 이상한데...', `MaleText_loc4`='有些不太对劲……', `MaleText_loc5`='有什麼不對勁...', `MaleText_loc7`='Algo no está bien...', `FemaleText_loc1`='뭔가 이상한데...', `FemaleText_loc4`='有些不太对劲……', `FemaleText_loc5`='有什麼不對勁...', `FemaleText_loc7`='Algo no está bien...' WHERE `ID`=58507;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인? 게다가 보아 하니 노련한 $c|1이로군요;로군요;! 좋아요! 이 난리를 수습하는 데 도움이 되겠군요.', `FemaleText_loc4`='外乡人？从你的打扮来看，还是个老练的$c。很好！也许你能帮我们脱离困境。', `FemaleText_loc5`='外國人?從你的外表看來，你是個經驗豐富的$c。太好了!也許你能把我們從這團混亂裡拯救出來。', `FemaleText_loc7`='¿$GUn extranjero:Una extranjera;? Y por tu aspecto, diría que eres $gun:una; $c $gveterano:veterana;. ¡Genial! Quizás puedas sacarnos de este lío.' WHERE `ID`=58508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 계획이 성공하려면, 당신이 전장에서 되도록 많은 화살을 모아 와야 해요, $c.', `FemaleText_loc4`='我的计划取决于你能否从战场上给我们带来尽可能多的箭矢，$c。', `FemaleText_loc5`='我計畫的成敗取決於你能從戰場上帶回多少箭頭給我們，$c。', `FemaleText_loc7`='Mi plan depende de que nos traigas todas las flechas que puedas del campo de batalla, $c.' WHERE `ID`=58509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 정도면 충분한 것 같네요. 빨리요, $n. 지평선에 야운골 원군이 운집하는 모습이 보이는 것 같군요.', `FemaleText_loc4`='看来你弄到的这些已经绰绰有余了。快，$n，我想我已经在地平线上看到了铺天盖地的野牛人援军。', `FemaleText_loc5`='看來你的能力綽綽有餘。快點，$n，我似乎看見揚古集結在地平線那端。', `FemaleText_loc7`='Parece que ya tienes suficientes. Rápido, $n, me ha parecido ver refuerzos yaungol agrupándose en el horizonte.' WHERE `ID`=58510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<멍하니 바닥을 바라보고 있는 농부>$B$B놈들이... 데려갔어요.$B$B데려가 버렸어요...', `MaleText_loc4`='<这个农夫漠然地盯着地板。>$B$B他们……抓住了他们。$B$B把他们抓走了……', `MaleText_loc5`='<農夫用遙遠空洞的眼神望著地面。>$B$B他們...把他們帶走了。$B$B帶走了...', `MaleText_loc7`='<El granjero dirige sus ojos al suelo con una mirada distante.>$B$BSe los han... llevado.$B$BSe los han llevado...' WHERE `ID`=58511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 찾아 주실 건가요? 정말 그래 주시겠어요?', `MaleText_loc4`='你要去找他们吗？你真的可以吗？', `MaleText_loc5`='你要找到他們嗎?你真的能嗎?', `MaleText_loc7`='¿Los encontrarás? ¿Crees que serás capaz?' WHERE `ID`=58512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 릴리안, 이제 변신할 시간이다.', `MaleText_loc4`='现在，莉莉安，你变身的时刻到了。', `MaleText_loc5`='現在，莉莉安，該準備你的轉化了。', `MaleText_loc7`='Ahora ha llegado la hora de tu transformación, Lilian.' WHERE `ID`=58513;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쿤라이 길의 영웅, $n 님께 경례!', `FemaleText_loc4`='向昆莱小径的英雄——$n致敬！', `FemaleText_loc5`='為崑萊小徑的英雄「$n」而歡呼!', `FemaleText_loc7`='¡Aclamad a $n, $gel héroe:la heroína; del Paso Kun-Lai!' WHERE `ID`=58514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 보니 반갑군요, $n. 야운골 놈들을 또 한 번 혼쭐을 내 주고 싶나요?', `FemaleText_loc4`='很高兴再次见到你，$n。想再好好教训这群野牛人渣滓一顿吗？', `FemaleText_loc5`='$n，真高興又見到你。有興趣再把這些揚古害蟲掃蕩一次嗎?', `FemaleText_loc7`='Me alegro de volver a verte, $n. ¿Tienes ganas de atacar a la peste yaungol otra vez?' WHERE `ID`=58515;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 걱정하지 않아도 돼요. 이제 남은 놈들을 처리하고 있어요. 오래 걸리지도 않을 거예요.', `FemaleText_loc4`='不用管我们。我们正在清理最后的余孽。应该用不了多久了。', `FemaleText_loc5`='別在意我們。我們只是在對他們作最後的掃蕩。應該不會花太長時間。', `FemaleText_loc7`='No te preocupes por nosotros. Estamos limpiando los últimos ahora mismo. No nos llevará mucho tiempo.' WHERE `ID`=58516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 언제 한 잔 사지요, $g 멋쟁이 : 아가씨;.', `FemaleText_loc4`='能请你喝一杯吗，$g帅哥:美女;？', `FemaleText_loc5`='$g帥哥:美女;，我還欠你一杯酒不是嗎?', `FemaleText_loc7`='¿No te debo un trago, $gguapo:señorita;?' WHERE `ID`=58517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 야운골 놈들이 왜 탕랑 평원에서 이곳으로 몰려오는지 알아냈나요?', `FemaleText_loc4`='你弄清究竟是什么把这些野牛人赶出螳螂高原的了吗？', `FemaleText_loc5`='你搞清楚是什麼驅使這一大票揚古從螳螂荒地跑出來了嗎?', `FemaleText_loc7`='¿Ya has descubierto por qué hay tanto yaungol fuera de los Baldíos de Tong Long?' WHERE `ID`=58518;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n|1을;를; 쏘지 않게 조심해라!', `FemaleText_loc4`='射击时小心点。别打到$n！', `FemaleText_loc5`='小心射擊。不要打到$n!', `FemaleText_loc7`='Cuidado con los disparos. ¡No vaya a ser que des a $n!' WHERE `ID`=58519;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 큰 영예군요, $n. 언제 한번 앉아서 제게 무용담을 들려 주시는 게 어때요?', `FemaleText_loc4`='这真是莫大的荣誉，$n。也许我们稍后能找个机会一起坐坐，听你给我讲讲你最近的义举？', `FemaleText_loc5`='這真是我的榮幸，$n。或許我們很快就能坐在一起，聽你說說你最新的功績?', `FemaleText_loc7`='Es todo un honor, $n. Ojalá tengas algo de tiempo para contarme tus últimas hazañas.' WHERE `ID`=58520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들에게 지옥을 보여 줘요, $n!', `FemaleText_loc4`='送它们下地狱，$n！', `FemaleText_loc5`='$n，讓他們下地獄去!', `FemaleText_loc7`='¡Hazlos sufrir, $n!' WHERE `ID`=58521;
