UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 좋은 시체를 안 쓰고 버릴 순 없지.', `MaleText_loc4`='为什么要白白浪费一具完美的尸体？', `MaleText_loc5`='為什麼要讓好好的一具屍體浪費呢?', `MaleText_loc7`='¿Por qué desperdiciar un cadáver en buenas condiciones?' WHERE `ID`=58523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 어떤가, 보스? 갈가리 찢기는 네 육체를 보는 기분이?', `MaleText_loc4`='感觉如何，沃斯？看着他们将你的凡躯切成碎片？', `MaleText_loc5`='感覺如何呢，佛斯?看著他們把你的肉體砍成碎塊?', `MaleText_loc7`='¿Qué se siente, Voss, al ver cómo destrozan tu cuerpo mortal?' WHERE `ID`=58524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여! 잠깐 시간을 내 주겠나?', `MaleText_loc4`='陌生人！可以占用你一些时间吗？', `MaleText_loc5`='陌生人!能不能耽誤你一點點時間呢?', `MaleText_loc7`='¡$gForastero:Forastera;! ¿Tienes un momento?' WHERE `ID`=58525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 재미있군. 그녀의 영혼은 아직 포기하지 않으려나 봐.', `MaleText_loc4`='真是有趣。她的灵魂不肯放开这个世界。', `MaleText_loc5`='真有趣，她的靈魂竟然捨不得這個世界。', `MaleText_loc7`='Es fascinante. Su espíritu no renuncia a este mundo.' WHERE `ID`=58526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽어, 강령술사!', `FemaleText_loc4`='死吧，死灵法师！', `FemaleText_loc5`='受死吧，死靈法師!', `FemaleText_loc7`='¡MUERE, NIGROMANTE!' WHERE `ID`=58527;
