UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈 보호막을! 이 망할 녀석!', `MaleText_loc4`='骨头！你这蠢货！', `MaleText_loc5`='我的骨頭!你這混蛋!', `MaleText_loc7`='¡Los huesos! ¡Maldita!' WHERE `ID`=58530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집은 마을을 들어서서 바로 오른쪽에 있다네. 가면은 위층에 있을 걸세.', `MaleText_loc4`='我的房子就在你进村之后的右手边。面具应该在楼上。', `MaleText_loc5`='我的房子就在你進入村莊後的右手邊。面具應該就在樓上。', `MaleText_loc7`='Mi casa está justo a la derecha según entras en el pueblo. La máscara está en el piso de arriba.' WHERE `ID`=58531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c가 돌아왔구먼. 그게 내 가면인가?', `MaleText_loc4`='$c回来了。那是我的面具吗？', `MaleText_loc5`='$c回來了。那是我在找的面具嗎?', `MaleText_loc7`='$gEl:La; $c ha vuelto. ¿Eso que veo es mi máscara?' WHERE `ID`=58532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$C님, 부탁드릴 게 있어요.', `FemaleText_loc4`='$C，我得请你帮个忙。', `FemaleText_loc5`='$C，我要拜託你幫個忙。', `FemaleText_loc7`='$C, me gustaría pedirte algo.' WHERE `ID`=58533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다, $n 님!', `MaleText_loc4`='这里，$n！', `MaleText_loc5`='這裡，$n!', `MaleText_loc7`='¡Por aquí, $n!' WHERE `ID`=58534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위에게서 샤를 몰아내는 일은 어떻게 되어가는가, $c?', `MaleText_loc4`='你成功消除锦鱼人身上的邪煞之力了吗，$c？', `MaleText_loc5`='$c，你將煞的污染從錦魚人身體驅趕出來的成果如何?', `MaleText_loc7`='¿Cómo van tus esfuerzos para eliminar la contaminación del sha de los jinyu, $c?' WHERE `ID`=58535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n. 덕분에 살았어요!', `MaleText_loc4`='谢谢你，$n。你刚刚救了我一命！', `MaleText_loc5`='謝謝你，$n。你救了我這身老皮!', `MaleText_loc7`='Gracias, $n. ¡Me has salvado el pellejo!' WHERE `ID`=58536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말하면 내가 음영파가 됐다는 게 아직도 놀라워. 물론 음영파는 대단한 단체지. 하지만 폭력 같은 건 나의 무결점 용모와는 어울리지 않는단 말야.$B$B그래도 왜 음영파에 들어갔는지는 똑똑히 기억 나... 안지는 가끔씩 정말 설득력이 있거든.', `MaleText_loc4`='老实说，我至今仍为自己加入影踪派而感到不可思议。并不是说他们有何逊色之处，只是暴力与我的完美人格向来都是风马牛不相及。$B$B不过要是说到加入他们的原因，真是想忘记都难……简而言之，安济有着超群的说服力。', `MaleText_loc5`='說實話，我還是為了自己居然加入影潘而驚訝。不是說他們不夠棒，而是考慮到我狂猛的攻擊是那麼完美無瑕。$B$B不過，我倒從來沒忘記自己為什麼加入他們...這樣說吧，安吉的說服力可是很強的。', `MaleText_loc7`='Sinceramente, aún me sorprende que me uniera al Shadopan. No niego que son magníficos y todo eso, pero la idea de someter mi complexión impecable a la violencia...$b$bEso sí, nunca olvido por qué me uní. Dejémoslo que en que Anji puede ser muy convincente.' WHERE `ID`=58537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배신당했어요! 우린 여기 매주 찾아왔어요. 그냥 상인인 줄 알았는데...

알고 보니 이... 물고기 인간들이 물갈퀴가 달린 한 손으로 우리를 맞이하면서, 다른 한 손으로는 등 뒤로 칼을 쥐고 있었지 뭐예요. 우리가 돌아서기만 하면 칼을 꽂아 넣을 심산으로요!', `FemaleText_loc4`='被骗了！我们每个星期都到这儿来。他们看上去就像是普通的生意人。

可现在……这些鱼人却一边用长蹼的手跟我们打招呼，一边握紧了藏在背后的刀子，想趁我们转身时捅我们一刀！', `FemaleText_loc5`='我們被騙了!我們每個星期都到這裡來，因為他們看起來只是普通的商人。

這些...這些魚人一手迎接我們，另一手卻握著刀藏在身後，只等我們轉身好在我們背後插上一刀!', `FemaleText_loc7`='¡Traición! Venimos aquí cada semana. Parecían simples comerciantes.

Ahora estos... hombres pez nos saludan con una mano palmeada mientras esconden un cuchillo en la otra, esperando a que nos descuidemos para apuñalarnos por la espalda.' WHERE `ID`=58538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 하게, $n. 분노의 괴수를 마주했을 때 차분하게 자기 식으로 싸울 수 있어야 하니까.', `MaleText_loc4`='别着急，$n。你最好先做好准备，以你自己的方式从容面对狂怒的海怪。', `MaleText_loc5`='慢慢來，$n。最好做好萬全準備了再去對付狂怒巨神海蛇。', `MaleText_loc7`='Tómate tu tiempo, $n. Será mejor que te enfrentes al leviatán de furia $gpreparado:preparada; y según tus términos.' WHERE `ID`=58539;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 모조리 없애 버리겠어. 여기 있어 봐야 소용없어!', `FemaleText_loc4`='我会消灭他们的。没必要继续待下去了！', `FemaleText_loc5`='我要徹底毀滅他們。待在這裡一點用也沒有!', `FemaleText_loc7`='Los DESTRUIRÍA a todos. ¡No tiene sentido quedarse aquí!' WHERE `ID`=58540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p, 혹시 정찰병에게서 모구 지도자에 대한 정보를 얻으면 어떡해야 되는지는 아시죠?', `FemaleText_loc4`='$p，如果斥候向你报告有关魔古首领的任何消息，你知道该怎么做。', `FemaleText_loc5`='$p，如果斥候給你任何與魔古首領有關的資訊，你知道該怎麼做。', `FemaleText_loc7`='$p, si los exploradores te dan cualquier tipo de información sobre el líder mogu, ya sabes lo que tienes que hacer.' WHERE `ID`=58541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났나, $n? 여기서도 폭발이 보이더구먼.', `MaleText_loc4`='完成了吗，$n？我们大老远的都能看见爆炸了。', `MaleText_loc5`='$n，事情成功了嗎?我們就連在這裡都能看到爆炸。', `MaleText_loc7`='¿Ya está, $n? Hemos visto la explosión desde aquí.' WHERE `ID`=58542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 가면은 뭐에 쓰는 거죠?', `MaleText_loc4`='那面具是干什么用的？', `MaleText_loc5`='這面具是做什麼用的?', `MaleText_loc7`='¿Para qué es esa máscara?' WHERE `ID`=58543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='워!', `MaleText_loc4`='哇哦！', `MaleText_loc5`='哇喔!', `MaleText_loc7`='¡Guau!' WHERE `ID`=58544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했네, $n.', `MaleText_loc4`='干得漂亮，$n。', `MaleText_loc5`='做的真熟練，$n。', `MaleText_loc7`='Muy bien hecho $n.' WHERE `ID`=58545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군요! 진짜로 해냈어요! 저한테 한 수 가르쳐 주세요, 네?', `MaleText_loc4`='你做到了！你真的做到了！也许你能给我演示几招，$n？', `MaleText_loc5`='你辦到了!你真的辦到了!$n，你可以表演幾招給我看嗎?', `MaleText_loc7`='¡Lo has logrado! ¡Lo has conseguido! ¿Me enseñarás alguno de tus trucos, $n?' WHERE `ID`=58546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 투덜대듯 경의를 표합니다.', `FemaleText_loc4`='%s咕哝着表达着她的赞美。', `FemaleText_loc5`='%s咕噥著她的崇拜之情。', `FemaleText_loc7`='%s gruñe de admiración.' WHERE `ID`=58547;
