UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 여기 일이 마무리되면 저를 제자로 삼아 줄래요?', `MaleText_loc4`='$n，等我们做完这里的事情后，我能来跟你一起训练吗？', `MaleText_loc5`='$n，等這裡的事結束後，我能不能跟你一起接受訓練?', `MaleText_loc7`='¿Puedo entrenar contigo cuando hayamos terminado, $n?' WHERE `ID`=58549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 $c|1이;가; 되고 싶어요, 검객님.', `MaleText_loc4`='我想我愿意成为一名$c，宝剑女侠。', `MaleText_loc5`='我想要成為一個$c，女劍聖。', `MaleText_loc7`='Creo que quiero ser como $n, maestra de espadas.' WHERE `ID`=58550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향이 어디에요, $n? 돌아갈 때 저도 같이 가도 돼요?', `MaleText_loc4`='你是从哪里来的，$n？等你回去时，能带上我吗？', `MaleText_loc5`='$n，你從哪裡來的?等你要回去的時候，我可以一起去嗎?', `MaleText_loc7`='¿De dónde vienes, $n? Cuando te marches, ¿puedo ir contigo?' WHERE `ID`=58551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮은 일인데 해 줘서 고마워요. 이따 마을에서 봐요.', `MaleText_loc4`='再次感谢你帮我处理杂事。我们稍后在村里见？', `MaleText_loc5`='再次感謝你幫忙做我的庄稼活。我們回村莊見囉?', `MaleText_loc7`='Gracias por ayudarme con mis tareas. ¿Te volveré a ver por el pueblo?' WHERE `ID`=58552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, $n. 이 동작 어때요?', `MaleText_loc4`='嘿，$n，你觉得这招怎么样？', `MaleText_loc5`='嘿，$n，你覺得這一招怎麼樣?', `MaleText_loc7`='¡Eh, $n! ¿Qué te parece este movimiento?' WHERE `ID`=58553;
