UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이라면;라면; 이 타락한 진위들을 $c 필살기 한 방으로 모조리 쓸어 버릴 수 있겠죠.', `MaleText_loc4`='$n只要使出$g他的:她的;招牌$c绝招，恐怕就能横扫所有这些被感染的锦鱼人了。', `MaleText_loc5`='$n只消用上$g他:她;招牌的$c絕招，就可以清光這些被污染的錦魚人。', `MaleText_loc7`='¡Seguro que $n puede acabar con esos jinyu contaminados con uno de sus movimientos especiales!' WHERE `ID`=58555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 돌 캐는 일을 시키면 잘 하겠구나!', `MaleText_loc4`='哈，你会变成一把很不错的敲石锤！', `MaleText_loc5`='啊，我想你可以當一把很好的敲石錘!', `MaleText_loc7`='¡Ah, creo que se te va a dar bien partir rocas!' WHERE `ID`=58556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무례한 꼬마들 같으니! 내게 복종하거나, 아니면 그냥 죽어라!', `MaleText_loc4`='无礼的小崽子们！投降免死！', `MaleText_loc5`='無禮的小崽子!不投降就得死!', `MaleText_loc7`='¡Cachorros insolentes! ¡Someteos o morid!' WHERE `ID`=58557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하는 법을 알려주지!', `MaleText_loc4`='我要让你学会听话！', `MaleText_loc5`='我會教導你服從的道理!', `MaleText_loc7`='¡Les voy a enseñar a obedecer!' WHERE `ID`=58558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 내게 그따위 말을 할 수가 있느냐! 네 처지를 알아라!', `MaleText_loc4`='你怎么敢这么跟我说话！想想你的身份！', `MaleText_loc5`='你竟敢這樣和我說話!搞清楚你的立場!', `MaleText_loc7`='¿Cómo se atrevén a hablarme así? ¡Les voy a enseñar dónde está su sitio!' WHERE `ID`=58559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촌구석 멍청이들이 막대기를 든다고 뭘 하겠느냐! 나를 공격하겠다고? 한꺼번에 덤벼봐라!', `MaleText_loc4`='你们不过是一群拿着棍子的乡下农夫！滚回去！', `MaleText_loc5`='你不過是帶著棍子的下等農夫!給我認份點!', `MaleText_loc7`='¡Solo son un puñado de granjeros patéticos con palos! ¡Vuelvan a la fila!' WHERE `ID`=58560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 수는 무한하다. 우리는 없는 곳이 없다. 먹물아가미 호수에서 다시 만나자, $p.', `MaleText_loc4`='我们浩浩荡荡。我们所向披靡。我们墨鳃潭见，$p。', `MaleText_loc5`='我們為數眾多。我們無所不在。我們回墨鰓湖見了，$p。', `MaleText_loc7`='Somos legión. Estamos en todas partes. Te veré de nuevo en Jinyu Mere, $p.' WHERE `ID`=58561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 진위! 네놈은 진위를 되찾을 수 없다, $P!', `MaleText_loc4`='我们的锦鱼人！你别想夺回他们，$P！', `MaleText_loc5`='我們的錦魚人!絕不讓你把他們拿回去，$P!', `MaleText_loc7`='¡LOS JINYU SON NUESTROS! ¡NO PODRÁS RECUPERARLOS, $P!' WHERE `ID`=58562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노에 무릎 꿇어라.', `MaleText_loc4`='向你的愤怒屈服吧。', `MaleText_loc5`='向你的憤怒屈服吧。', `MaleText_loc7`='Ríndete ante tu ira.' WHERE `ID`=58563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스스로 타락을 택하다니 우리로서는 영광이로군.', `MaleText_loc4`='真是荣幸，你竟然选择被感染。', `MaleText_loc5`='我們很榮幸你選擇成為被污染的目標。', `MaleText_loc7`='Nos honra que te dejes contaminar.' WHERE `ID`=58564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 우리 편이 된다니 든든하겠는걸, $p.', `MaleText_loc4`='你会令我们如虎添翼的，$p。', `MaleText_loc5`='加上你就更完美了，$p。', `MaleText_loc7`='Serás una aportación excelente, $p.' WHERE `ID`=58565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노의 괴수께서 네 몸을 조종해 이 땅을 지배할 것이다.', `MaleText_loc4`='狂怒的海怪会很乐意将你的身体当做傀儡，对抗这片土地。', `MaleText_loc5`='狂怒巨神海蛇會很樂於拿你的身體當傀儡來對付這些土地。', `MaleText_loc7`='El leviatán de furia disfrutará controlando tu cuerpo como una marioneta contra estas tierras.' WHERE `ID`=58566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 물고기 대가리들이야 어찌 되든 무슨 상관이냐?', `MaleText_loc4`='不管我们对这些鱼脑袋做了什么，这关你什么事？', `MaleText_loc5`='你何必要在意我們對這些魚頭做些什麼?', `MaleText_loc7`='¿Qué más te da lo que hagamos con estos cabezas de pescado?' WHERE `ID`=58567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 너희 종족을 모조리 지배할 것이다!', `MaleText_loc4`='不！我会控制你，以及你所有的族人！', `MaleText_loc5`='不!我要佔據你和你們全族的人!', `MaleText_loc7`='¡NO! ¡TE POSEERÉ A TI Y A TODA TU ESPECIE!' WHERE `ID`=58568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 역시 남들에게 분노를 표출하며 살지 않느냐? 어떻게 네가 감히 우릴 꺾을 수가 있겠느냐?', `MaleText_loc4`='你才对别人施加过几次怒火？你竟然奢望能打败我们？', `MaleText_loc5`='你知道你浪費了多少時間在對別人發脾氣上?你怎麼可能還指望能夠打敗我們?', `MaleText_loc7`='¿Cuánto tiempo empleas proyectando tu odio hacia los demás? ¿Cómo crees que puedes derrotarnos?' WHERE `ID`=58569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈은 폭탄이 될 거다.', `MaleText_loc4`='这个可以当炸弹。', `MaleText_loc5`='這個人會變炸彈!', `MaleText_loc7`='¡Pon una bomba en tu vida!' WHERE `ID`=58570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나서 반갑네, $p.$B$B이곳은 고대로부터 내려온 장소라네. 여기에는 답이 있지. 질문을 아는 이만 찾을 수 있는 답이...', `MaleText_loc4`='很高兴再次见到你，$p。$B$B这个地方十分古老。那些满怀问题的人，将在这里找到答案。', `MaleText_loc5`='很高興和你再會，$p。$B$B這地方非常古老。對那些知道該問什麼的人來說，這裡也有著答案。', `MaleText_loc7`='Me alegro de volver a verte, $p.$b$bEste lugar es muy antiguo. Aquí, los que buscan preguntas encuentran respuestas.' WHERE `ID`=58571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것 보세요, 이방인님. 고명하신 전승지기님께 말씀드린 것과 같은 이야기를 다시 한번 해줄게요...$B$B<한 마디 한 마디 말할 때마다 눈을 점점 더 크게 뜨며 당신에게 위협적으로 접근하는 만>$B$B비취가, 하나도, 없다고요!', `FemaleText_loc4`='听着，陌生人，我刚才已经跟那位尊贵的游学者说了，我现在再跟你重复一遍……$B$B<孟一边说一边走了过来，她的眼睛突然瞪得很大。>$B$B我！没！有！玉！石！', `FemaleText_loc5`='聽著，陌生人。我會把我跟尊貴的博學行者講過的話原封不動地告訴你...$b$b<蔓恩湊過身子，瞪大眼睛，一字一字地說。>$B$B玉、沒、了!', `FemaleText_loc7`='Mira, $gforastero:forastera;, te digo lo mismo que le dije al honorable eremita...$b$b<Mann se va acercando a cada palabra que pronuncia y abre los ojos cada vez más.>$B$B¡No. Tengo. Jade!' WHERE `ID`=58572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미로운 일이군... 하지만 무슨 의미일까?!$B$B자네가 저 요마에게서 모아온 비취를 사용하면 다음 그림을 완성할 수 있겠지만, 전체 벽화를 완성하려면 비취가 더 필요하네.$B$B현장감독을 도와서 채석장을 복구해 주게.', `MaleText_loc4`='这很有趣……但能有什么意义呢？！$B$B你收集来的玉石只够我们完成下一块嵌板的，但我们还需要更多的玉石来完成整个作品。$B$B请帮助工头让她的采石场恢复运作。', `MaleText_loc5`='這真是太棒了...但這會是什麼意思?!$B$B你從這些妖精身上收集來的玉足夠我們弄好下一塊畫壁，但我們還需要更多才能完成整個壁畫。$B$B請幫助工頭恢復玉礦的運作。', `MaleText_loc7`='Esto es fascinante, ¿pero qué podría significar?$b$bEl jade que has recolectado de esos duendes nos ayudará a rellenar el próximo panel, pero necesitaremos más para terminar el fresco entero.$b$bAyuda a la supervisora a retomar la producción en la cantera.' WHERE `ID`=58573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주의 깊게 살펴보게, $p. 이 판은 분명히 전쟁을 보여주고 있네.$B$B이제 무슨 일이 일어날까? 이 판은 무슨 이야기를 하려는 걸까?', `MaleText_loc4`='看呐，$p。很显然这嵌板描述的是战争。$B$B下一块呢？它又会试图描述些什么呢？', `MaleText_loc5`='看看，$p。這塊畫壁把戰爭描繪得栩栩如生。$B$B接下來會是什麼?它是在描述什麼東西?', `MaleText_loc7`='Echa un vistazo, $p. Este panel describe claramente la guerra.$b$b¿Qué vendrá después? ¿Qué querrá decir?' WHERE `ID`=58574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='평상시 같으면 초 님의 부탁을 충분히 들어드리고도 남았을 거예요. 이 땅에는 비취 광맥이 마치...$B$B<잠시 생각에 잠겨 머리를 긁적이는 만>$B$B왜 그 몸속 여기저기로 흘러가는 뭐 그런 거 있잖아요? 그런 것처럼 퍼져 있어요.$B$B이봐요, 전 글쟁이가 아니예요.$B$B제가 하고 싶은 말은, 지금 문제가 생겼다는 거라고요.', `FemaleText_loc4`='通常我们都能轻松完成周卓的要求。这里的玉石矿脉贯穿大地，就好像……$B$B<孟挠了挠头，似乎在思考。>$B$B呃，就好像某些东西体内的血管。$B$B你瞧，我又不是诗人。$B$B重点在于：我们遇到麻烦了。', `FemaleText_loc5`='通常我們能輕易符合阿洲的要求。玉石礦脈貫串這片土地就像...$b$b<蔓恩抓了抓她的腦袋，想了一會兒。>$B$B好吧，反正就像貫串其他東西的東西一樣。$B$B夠了，我又不是詩人。$B$B重點是:我們有麻煩了。', `FemaleText_loc7`='Normalmente podríamos atender la petición de Cho. El jade corre por las venas de esta tierra como...$b$b<Mann se rasca la cabeza pensativa durante unos segundos.>$b$bBueno, como algo que corre por las venas de otra cosa. $b$bMira, no soy poetisa.$b$bLo que cuenta es que tenemos problemas.' WHERE `ID`=58575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 덕분에 채석장은 무사할 거예요.$B$B직원들은 휴가라도 보내줘야겠...$B$B푸하! 물론 농담이지요. 아, 얼굴색 하나 변하지 않고 얘기할 수 있었는데!$B$B할 일이 아주 많아요! 이제부터 시작이라고요!', `FemaleText_loc4`='多亏了你，采石场总算没事了。$B$B看来我得让小伙子们放个假……$B$B哈哈！我哄谁呢？瞧我自己也一本正经的样子。$B$B我们还有活儿要做呢！', `FemaleText_loc5`='多虧了你，玉礦應該會沒事的。$B$B我可能會讓小子們放點小假...$b$b哈!我騙誰啊?可惜，我差點就憋住笑了。$B$B我們有工作要做!', `FemaleText_loc7`='La cantera saldrá adelante gracias a ti.$b$bHasta les he dado vacaciones a algunos de los chicos...$b$b¡Ja, ja! ¿Pero quién se lo cree? Lo he dicho casi sin reírme.$b$bVamos, ¡al turrón!' WHERE `ID`=58576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 걱정은 하지 마십시오.$B$B흐으으아아아악!!$B$B전 괜찮을 겁니다. 정말로요.', `MaleText_loc4`='你完全不用担心我。$B$B啊啊啊啊！！$B$B我很快就能搞定，真的。', `MaleText_loc5`='甭擔心我了。$B$B哼呃呃呃呃!!$B$B我會沒事的，真的沒事的。', `MaleText_loc7`='No os preocupéis por mí.$B$B¡¡HNNGGHHH!!$B$BEstoy bien, de verdad.' WHERE `ID`=58577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도가 끔찍한 일이라고 생각하십니까? 아, 여기 30년 전에 와보셨어야 합니다.$B$B일꾼들 중 하나가 점심 식사거리를 밖에 내놨었지요. 기억이 맞다면 아마 생선 종류였을 겁니다.$B$B안마당에 그걸 내놨었지요. 커다란 생선탕을 냄비째 내놨다고요. 분명히 그거였던 것 같네요. 그러자, 세상에, 수백 미터 밖에서부터 호젠이란 호젠은 모조리 여기로 달려왔습니다.$B$B그 난리법석을 겪고 나니, 커다란 녹옥거미 정도는 아무것도 아닙니다...', `MaleText_loc4`='你觉得那就算糟的了？我得说，你要是见过30年前那场灾难就不会这么想了。$B$B以前有个小伙子将他的午餐放在了外面——是某种鱼汤，如果我没记错的话。$B$B他把那锅炖汤放在中庭那里了——一大锅热气腾腾的鱼肉炖汤，没错，我现在记起来了——然后，我的老天，方圆百里之内所有猢狲都涌过来了。$B$B经历过那事之后，我已经不把几只发育过度的利齿蛛放在眼里了……', `MaleText_loc5`='你以為這樣就叫可怕?你該看看，喔，大概是三十年前吧。$B$B有個小子落下了他的午餐。沒記錯的話是某種魚湯吧。$B$B他把它落在中庭。喔是一大鍋魚湯，我現在肯定了。接著，我敢發誓，百哩之內的每個猴人都狂奔而來。$B$B收拾過那種殘局後，我寧願應付過度成長的啃咬者...', `MaleText_loc7`='Si crees que eso ha sido malo, deberías haber estado aquí hace, digamos... treinta años.$b$bUno de los chicos dejó fuera su comida; una especie de guiso de pescado, si la memoria no me traiciona.$b$bA lo que iba, deja fuera una cacerola enorme con guiso de pescado, ahora lo recuerdo claramente, y, por el honor del cachorro, vinieron todos los hozen que había en cien kilómetros a la redonda.$b$bDespués de limpiar ese desastre, cualquier día me haré con unos cuantos roedores gigantes...' WHERE `ID`=58578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 공격해 온다!', `MaleText_loc4`='野牛人发起进攻了！', `MaleText_loc5`='揚古攻來了!', `MaleText_loc7`='¡Los yaungol nos atacan!', `FemaleText_loc1`='야운골이 공격해 와요!', `FemaleText_loc4`='野牛人发起进攻了！', `FemaleText_loc5`='揚古攻來了!', `FemaleText_loc7`='¡Los yaungol nos atacan!' WHERE `ID`=58579;
