UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 좀 도와주시오!', `MaleText_loc4`='快来人救救我们！', `MaleText_loc5`='來人啊，救救我們!', `MaleText_loc7`='¡Que alguien nos salve!', `FemaleText_loc1`='누가 좀 도와줘요!', `FemaleText_loc4`='快来人救救我们！', `FemaleText_loc5`='來人啊，救救我們!', `FemaleText_loc7`='¡Que alguien nos salve!' WHERE `ID`=58581;
