UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 야운골에게 무슨 잘못을 했다고?!', `MaleText_loc4`='我们对野牛人做过什么？！', `MaleText_loc5`='我們是做了什麼讓揚古這樣對我們?!', `MaleText_loc7`='¡¿Qué les habremos hecho a los yaungol?!', `FemaleText_loc1`='우리가 야운골에게 무슨 잘못을 했다고?!', `FemaleText_loc4`='我们对野牛人做过什么？！', `FemaleText_loc5`='我們是做了什麼讓揚古這樣對我們?!', `FemaleText_loc7`='¡¿Qué les habremos hecho a los yaungol?!' WHERE `ID`=58584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 이방인 때문에 야운골이 공격하는 거야!', `MaleText_loc4`='一定是因为那个陌生人，野牛人才发起攻击的！', `MaleText_loc5`='揚古一定是因為那陌生人才來攻擊我們的!', `MaleText_loc7`='¡Seguro que los yaungol nos atacan por culpa $gdel extranjero:de la extranjera;!', `FemaleText_loc1`='저 이방인 때문에 야운골이 공격하는 거예요!', `FemaleText_loc4`='一定是因为那个陌生人，野牛人才发起攻击的！', `FemaleText_loc5`='揚古一定是因為那陌生人才來攻擊我們的!', `FemaleText_loc7`='¡Seguro que los yaungol nos atacan por culpa $gdel extranjero:de la extranjera;!' WHERE `ID`=58585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 녹옥거미가 채석장을 온통 무너뜨리고 있습니다!', `MaleText_loc4`='这些该死的利齿蛛快把这儿全毁了！', `MaleText_loc5`='該死的啃咬者快把這地方給拆啦!', `MaleText_loc7`='¡Los malditos roedores van a tirar todo abajo!', `FemaleText_loc1`='망할 녹옥거미가 채석장을 온통 무너뜨리고 있어요!', `FemaleText_loc4`='这些该死的利齿蛛快把这儿全毁了！', `FemaleText_loc5`='該死的啃咬者快把這地方給拆啦!', `FemaleText_loc7`='¡Los malditos roedores van a tirar todo abajo!' WHERE `ID`=58586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 저는 자연의 제자, 웡입니다!$B$B최근의 나무 요마 문제를 조사하러 파견 나왔습니다.$B$B전 어릴 때부터 항상 나무 요마라는 존재를 매력적이라고 생각했습니다. 그거 아세요? 보통 요마들은 그다지 폭력적이지 않아요.$B$B짓궂긴 하지만, 진짜 피해를 주는 일은 거의 없지요.', `MaleText_loc4`='你好啊！我是老翁：自然的弟子！$B$B我是奉命来调查最近爆发的林精问题的。$B$B我还是个孩子的时候，就对林精很着迷。你知道，一般来说，他们并不残暴。$B$B他们或许是有点淘气，但很少会对人造成真正的伤害。', `MaleText_loc5`='幸會啊!我是老黃，自然的學習者!$B$B我被派來調查最近開始的森林妖精問題。$B$B我一直很為木之妖精著迷，從小時候就開始了。其實，他們通常不粗暴。$B$B他們或許愛玩，但很少真的造成傷害。', `MaleText_loc7`='¡Buenas! Soy Weng, ¡estudioso de la naturaleza!$b$bMe han enviado a investigar los problemas recientes con los duendes del bosque.$b$bSiempre me han fascinado, incluso cuando era pequeño. Normalmente no son violentos, ¿sabes?$b$bTraviesos, quizás, pero casi nunca pretenden hacer daño.' WHERE `ID`=58587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘!', `MaleText_loc4`='救命！', `MaleText_loc5`='快來幫忙!', `MaleText_loc7`='¡Socorro!' WHERE `ID`=58588;
