UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 피?... 하하... 하지만 난 죽지 않아!', `MaleText_loc4`='我流血了……哈哈……可我死不了！', `MaleText_loc5`='我流血了...哈哈..但我死不了!', `MaleText_loc7`='Sangro... ¡Ja, ja! ¡Pero no moriré!' WHERE `ID`=58592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연약한 매끈피부들은 쓸모없어!', `MaleText_loc4`='瘦瘦的光板儿一点用也没有！', `MaleText_loc5`='弱小的滑魚爛死了!', `MaleText_loc7`='¡Mandukos débiles son inútiles!' WHERE `ID`=58596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 찌그러져 있어, 이 멍청한 매끈피부들!', `MaleText_loc4`='退下，笨光板儿！', `MaleText_loc5`='躺好吧，笨蛋滑魚!', `MaleText_loc7`='¡Kietos ahí, estúpidos mandukos!' WHERE `ID`=58597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 매끈피부 없이 너희가 얼마나 센지 한번 보자!', `MaleText_loc4`='让我们看看，没有了那些滑溜溜的朋友，你还有多大本事吧！', `MaleText_loc5`='看看少了你腦子滑滑的朋友你還有多強!', `MaleText_loc7`='¡Veamos los fuerte que eres sin tus amigos mandukos!' WHERE `ID`=58598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 네 영혼을 내가 차지하겠다! 다른 녀석들처럼!', `MaleText_loc4`='我会得到你那不驯的灵魂的，就像其他灵魂一样！', `MaleText_loc5`='我會得到你的，倨傲不遜的魂靈，像我得到其他傢伙一樣!', `MaleText_loc7`='Tu espíritu indómito será mío, ¡como todos los demás!' WHERE `ID`=58599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 내 것이다!', `MaleText_loc4`='你是我的！', `MaleText_loc5`='你是我的!', `MaleText_loc7`='¡Tu espíritu es MÍO!' WHERE `ID`=58600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는... 천둥을... 막을 수 없다...', `MaleText_loc4`='你……休想击败……雷……', `MaleText_loc5`='你...沒法贏過...雷王...', `MaleText_loc7`='No... derrotarás... al trueno...' WHERE `ID`=58601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그다지 많이 가져오실 것도 없어요!$B$B판다리아의 땅에서 찾아오셔야 하는 보물은 딱 5가지랍니다. 루비 파편, 아름다운 사과, 비취 고양이, 푸른 깃털, 그리고 습지대 백합이에요.$B$B가방에 이 물건들을 계속 가지고 돌아다니다 보면. 누가 어떤 물건을 받고 싶어하는지 알게 될 거예요. 이웃들을 찾아다니면서 당신이 가져온 물건을 주고 싶은 이웃에게 줘보세요. 물론 별로 좋아하지 않을 수도 있답니다! 이 다섯 개의 보물 중 각자 좋아하는 게 다를 수도 있으니까요. 그러니 주민들과 이야기해서 뭘 좋아하는지 알아보세요.$B$B이 동네 마을 주민들은 음식도 정말 좋아해요! 제 말은, 누가 맛있는 걸 안 좋아하겠어요? 요리법을 아신다면 아주 금상첨화겠죠!$B$B이게 제가 선물에 대해 아는 전부랍니다. 행운을 빌게요!', `FemaleText_loc4`='这还远远不够！$B$B在潘达利亚的黑色泥土里埋藏着五件稀世珍宝：红宝石碎片、可爱的苹果、玉猫、蓝色羽毛以及泽地百合。$B$B只要你能将其中一件收入囊中，就能在附近找到愿意接受它们的人。$B$B找到其中一件并交给你喜欢的人，就有机会赢得他们的好感！每个人都会有他们最喜欢的东西，所以要跟他们多聊聊才能知其喜好。$B$B还有，这儿的人都很爱美食！说实话，谁不爱呢？如果你会做菜，那就再好不过了！$B$B关于礼物我就知道这些了。祝你好运！', `FemaleText_loc5`='事情很簡單!$B$B你可以在潘達利亞境內的深色土壤中找到五樣稀有的寶物:紅寶石裂片，可愛的蘋果，玉貓，藍羽，與溼地百合。$B$B只要你的背包中有其中一項物品，你就能知道這附近有誰願意接受它們。$B$B找到其中一樣，並把東西送給你喜歡的某個人，或許你有機會讓他們也有一點點喜歡你!這五樣寶物中，每個人都有自己最喜歡的物品，所以要多跟人們交談來瞭解他們喜歡哪樣。$B$B另外，這一帶的人們都很愛食物!我的意思是，誰不愛呢?如果你懂烹飪，那或許對你十分有利! $B$B這大概就是所有我知道關於禮物的事了。祝你好運!', `FemaleText_loc7`='¡No tiene mucha historia!$B$BHay cinco tesoros singulares que puedes encontrar en la tierra oscura de Pandaria: fragmentos de rubí, manzanas preciosas, gatos de jade, plumas azules y lirios de marisma.$b$bMientras tengas uno de esos objetos en la bolsa, podrás ver quién está dispuesto a aceptarlo.$b$bEncuentra uno de estos tesoros y regálaselo a alguien que te guste; ¡es muy posible que empieces a gustarle tú también! Todo el mundo tiene un objeto favorito entre estos cinco, así que habla con la gente para saber cuáles prefieren.$B$BAdemás, a la gente de por aquí le encanta la comida. Bueno, ¿y a quién no? Si sabes cocinar, ¡podría salirte muy rentable!$B$BEso es todo lo que sé sobre regalos. ¡Buena suerte!' WHERE `ID`=58602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 선물을 좋아하십니까?', `MaleText_loc4`='你喜欢什么样的礼物？', `MaleText_loc5`='你喜歡什麼樣的禮物?', `MaleText_loc7`='¿Qué tipo de regalos te gustan?', `FemaleText_loc1`='어떤 선물을 좋아하세요?', `FemaleText_loc4`='你喜欢什么样的礼物？', `FemaleText_loc5`='你喜歡什麼樣的禮物?', `FemaleText_loc7`='¿Qué tipo de regalos te gustan?' WHERE `ID`=58603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 본 때를 보여주세요.', `MaleText_loc4`='去干掉他们，孩子。', `MaleText_loc5`='給他們好看，小鬼。', `MaleText_loc7`='Ve por ellos, $gchico:chica;.' WHERE `ID`=58604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 친구! 괜찮아요?

이제 괜찮아요. 빛을 따라가지 마세요!', `MaleText_loc4`='嘿，孩子！你还好吗？

我抓住你了。别走进那光里！', `MaleText_loc5`='嘿，小鬼!你還好嗎?

我罩著你。別進入光裡!', `MaleText_loc7`='¡Joven! ¿Estás bien?

Te tengo. ¡No vayas a la luz!' WHERE `ID`=58605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 개들에게 줄 신선한 고기들!', `MaleText_loc4`='啊！狗崽子们又有鲜肉吃了。', `MaleText_loc5`='啊，獵犬又有鮮肉吃了。', `MaleText_loc7`='Ah, carne fresca para los perros.' WHERE `ID`=58608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지원군이 있거든. 이걸 봐.', `FemaleText_loc4`='我自然有办法。瞧瞧这个。', `FemaleText_loc5`='我有援手。看著吧。', `FemaleText_loc7`='Traigo refuerzos. Mira esto.' WHERE `ID`=58609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽입니다!', `MaleText_loc4`='$n，到这儿来！', `MaleText_loc5`='喂，$n，我在這。', `MaleText_loc7`='¡Tú, ven aquí!' WHERE `ID`=58610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 거점을 세워야 한다... 저 호드 강아지들을 없애고!', `MaleText_loc4`='我们得在这儿站稳脚跟……远离这些部落恶狗。', `MaleText_loc5`='我們得在這裡取得據點...遠離那些部落的走狗。', `MaleText_loc7`='Debemos apostarnos aquí... lejos de esos perros de la Horda.' WHERE `ID`=58611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이 호드 놈들은 이제 지겹군. 달리 조용한 곳이 또 있지 않을까...', `MaleText_loc4`='我烦透这些部落的懦夫了。这村子里一定还有其它地方能让我歇脚。', `MaleText_loc5`='我厭倦這些部落懦夫了，村莊裡一定還有別的地方可以休息吧。', `MaleText_loc7`='Me estoy cansando de esos cobardes de la Horda. Tiene que haber otro lugar de reposo en la aldea.' WHERE `ID`=58612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 잔인한 호드의 노예가 되게 할 수는 없다. 용납 못해!', `MaleText_loc4`='这些人不能被你们那残忍的部落所奴役。我决不允许！', `MaleText_loc5`='這些人絕不會受到殘忍的部落奴役。我絕不允許!', `MaleText_loc7`='Tu cruel Horda no esclavizará a esta gente. ¡No lo permitiré!' WHERE `ID`=58613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크, 네 손에 죄 없는 자가 몇이나 죽었나? 호드는 명예를 모른다...', `MaleText_loc4`='有多少无辜者曾经死在你的手上，兽人？恬不知耻的部落……', `MaleText_loc5`='有多少無辜者死在你手中，獸人?你們部落一點榮譽心都沒有...', `MaleText_loc7`='¿Cuántos inocentes han muerto a tus manos, orco? Tu Horda no conoce el honor...' WHERE `ID`=58614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 쥐새끼가 세 마리 남았군. 너희를 모두 없애버리는 건 일도 아니다.', `MaleText_loc4`='还剩三个部落鼠辈。这次我会一块儿把你们收拾了。', `MaleText_loc5`='只剩下三隻部落鼠輩。把這些垃圾一口氣解決掉應該不是什麼大問題。', `MaleText_loc7`='Solo quedan tres ratas de la Horda. No será muy difícil acabar con tu calaña de una vez por todas.' WHERE `ID`=58615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크, 쿤라이 봉우리가 네 무덤이 될 거다. 내 손으로 묻어 주지.', `MaleText_loc4`='昆莱山就是你的葬身之地，兽人。我会亲手埋葬你。', `MaleText_loc5`='崑萊峰就是你的葬身之地，獸人。我要殺了你。', `MaleText_loc7`='Solo quedan tres ratas de la Horda. No será muy difícil acabar con tu calaña de una vez por todas.' WHERE `ID`=58616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림, 네가 기운을 차릴 때까지 기다려 주마. 얼라이언스가 명예를 모른다고 하지 마라.', `MaleText_loc4`='我会等你的伤养好了再结果你，纳兹戈林。免得你说我们联盟的人没有荣誉感。', `MaleText_loc5`='我會等你痊癒之後再宰了你，納茲格寧姆。免得有人說聯盟不夠光明磊落。', `MaleText_loc7`='Esperaré a que te cures para matarte, Nazgrim. Que no se diga que la Alianza lucha sin honor.' WHERE `ID`=58617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온순하고 평화를 사랑하는 이 땅의 주민들을 봐라. 이들은 얼라이언스가 될 운명이다.', `MaleText_loc4`='看看生活在这片土地上的平和善良的人们。他们生来就属于联盟。', `MaleText_loc5`='看看這片土地上和平、善良的人們，他們生來就該屬於聯盟。', `MaleText_loc7`='Mira a la apacible y bondadosa gente de esta tierra. Nacieron para pertenecer a la Alianza.' WHERE `ID`=58618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기, 이쪽이네!', `MaleText_loc4`='$n，过来！', `MaleText_loc5`='$n，過來!', `MaleText_loc7`='¡Tú! ¡Sí, tú!' WHERE `ID`=58619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 일어나는 대로, 너를 뭉개 주마!', `MaleText_loc4`='等我……站起来，我就揍扁你！', `MaleText_loc5`='等我能...起身時，我一定要打扁你!', `MaleText_loc7`='En cuanto pueda levantarme, ¡te aplastaré!' WHERE `ID`=58620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린, 내 도끼를 찾아 와라! 이 멍청한 인간의 머리를 쪼개 주겠다!', `MaleText_loc4`='地精，我的斧子呢！我要把这人类傻瓜的脑袋砍下来！', `MaleText_loc5`='哥布林，去找我的斧頭!我要把這人類笨蛋的腦袋砍下來!', `MaleText_loc7`='¡Goblin, encuentra mi hacha! ¡Le voy a cortar la cabeza a este necio humano!' WHERE `ID`=58621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도, 얼라이언스도 곧 아제로스의 역사책에나 나오는 존재가 될 것이다.', `MaleText_loc4`='很快，你和你的联盟就会被写进艾泽拉斯的历史书里。', `MaleText_loc5`='很快的，你和你的聯盟就只會出現在艾澤拉斯的歷史書籍裡了。', `MaleText_loc7`='Pronto tú y tu Alianza solo existirán en los libros de historia de Azeroth.' WHERE `ID`=58622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간, 내 도끼가 네 피를 삼킬 것이다.', `MaleText_loc4`='我的斧子会享用你的鲜血，人类。', `MaleText_loc5`='我的斧頭很快就能暢飲你的鮮血，人類。', `MaleText_loc7`='Mi hacha pronto devorará tu sangre, humano.' WHERE `ID`=58623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 여기에 요새를 세우지 못할 거다. 이곳은 호드의 땅이 될 운명이다.', `MaleText_loc4`='你们无法在这里立足。这里注定要成为部落的领地。', `MaleText_loc5`='你們聯盟永遠無法在這裡建立據點，這裡注定要成為部落的領地。', `MaleText_loc7`='Los tuyos jamás construirán una avanzada aquí. Estas tierras pertenecerán a la Horda.' WHERE `ID`=58624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쉬르에서는 나를 따돌렸지만, 여기서는 그렇게 안 될 거다.', `MaleText_loc4`='你……在瓦斯琪尔逃过一劫，这次你没这么走运了。', `MaleText_loc5`='你...在瓦許伊爾時讓你逃了。你這次可不會那麼幸運。', `MaleText_loc7`='Lograste escapar en Vashj''ir. No tendrás tanta suerte aquí.' WHERE `ID`=58625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 현명한 종족이다. 조만간 호드 편에 설 것이다.', `MaleText_loc4`='这些熊猫人都很明智，他们迟早会加入我们部落的。', `MaleText_loc5`='這些熊貓人是群相當明智的傢伙。他們遲早會和部落站在同一陣線。', `MaleText_loc7`='Los pandaren son un pueblo sabio. Tarde o temprano se aliarán con la Horda.' WHERE `ID`=58626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감하게 죽을 배짱은 있나, 인간? 이리 와서 나와 놀아보자.', `MaleText_loc4`='希望你有勇气来面对死亡，人类。我可是想好好打一架。', `MaleText_loc5`='我希望你有勇氣面對死亡，人類。我現在很想好好打一場。', `MaleText_loc7`='Espero que tengas el valor de morir con valentía, humano. Espero un buen desafío.' WHERE `ID`=58627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실수는 언젠가는 교훈이 된다네. 실수를 어떻게 대하느냐에 따라 자네라는 사람이 달라지지.', `MaleText_loc4`='犯错只说明我们还有待学习，$n。而你处理那些错误的方法，才是最终证明你品行的东西。', `MaleText_loc5`='錯誤不過是我們還未學到的一課，$n。如何處理這些錯誤，才決定你是什麼樣的人。', `MaleText_loc7`='Los errores son simples lecciones que nos quedan por aprender, $n. El cómo nos enfrentamos a ellos es lo que nos define al final.' WHERE `ID`=58628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가셔서 다른 일을 보십시오. 저는 장비를 챙겨서 태양노래 농장으로 가겠습니다.', `MaleText_loc4`='你先去吧。我带上工具，与你在日歌农场会合。', `MaleText_loc5`='你儘管繼續吧。我負責收集我的工具，然後跟你在日歌農莊碰頭。', `MaleText_loc7`='Adelante. Recogeré mis herramientas y nos encontraremos en el Rancho Cantosol.' WHERE `ID`=58629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔존하는 의심을 무찌르려면 냉철한 이성과 차분한 감정이 필요하네, $c. 그렇게 잔존하는 의심을 물리치고 나면 복구를 시작할 수 있지.', `MaleText_loc4`='击败徘徊之疑需要冷静的头脑和坚定的信念，$c。只要控制住这些怪物，重建工作就可以开始了。', `MaleText_loc5`='擊敗徘徊之惑需要冷靜的頭腦和穩定的情緒，$c。控制住他們之後，重建工作就能開始。', `MaleText_loc7`='Para derrotar las dudas persistentes hay que tener una mente sensata y unas emociones equilibradas, $c. Con ellas bajo control, puede comenzar el proceso de reconstrucción.' WHERE `ID`=58630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 것! 뭉개 버릴 테다!', `MaleText_loc4`='蠢货！我要粉碎你！', `MaleText_loc5`='蠢蛋!我要碾碎你!', `MaleText_loc7`='¡Idiota! ¡Te aplastaré!' WHERE `ID`=58631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 인내를 가지십시오. 금방 될 겁니다.', `MaleText_loc4`='耐心点。很快就要完成了。', `MaleText_loc5`='有點耐心。很快就可以完成了。', `MaleText_loc7`='Paciencia. Ya queda poco.' WHERE `ID`=58632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 혼자 있는 시간이 길어질수록 일이 더 빨리 끝날 겁니다.', `MaleText_loc4`='我越早能不被打扰，就能越快把活儿干完。', `MaleText_loc5`='你越早讓我獨處，工作就能越快完成。', `MaleText_loc7`='Cuanto antes me dejen en paz, antes terminaré el trabajo.' WHERE `ID`=58633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡초 박멸은 정말 힘들지요.', `MaleText_loc4`='割草可是艰苦的工作啊。', `MaleText_loc5`='除草是一件吃重的工作。', `MaleText_loc7`='Aporrear hierbajos es un trabajo duro.' WHERE `ID`=58634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 하면 끝날 겁니다.', `MaleText_loc4`='再来一点点，就能完成了。', `MaleText_loc5`='再一下下就可以完成了。', `MaleText_loc7`='Solo un poco más y se habrá acabado.' WHERE `ID`=58635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 밭은 금세 새로 일군 땅처럼 보일 겁니다!', `MaleText_loc4`='这片田地马上就能焕然一新了！', `MaleText_loc5`='田地馬上就能變得跟新的一樣好!', `MaleText_loc7`='¡Este campo estará como nuevo en menos que canta un gallo!' WHERE `ID`=58636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕골 시장에 갑니다. 제 채소 건드리지 마십시오!

- 농부 펑', `MaleText_loc4`='我去半山市集了。别碰我的蔬菜！

——农夫老方', `MaleText_loc5`='到半丘市集去。別碰我的蔬菜!

－農夫老豐', `MaleText_loc7`='He ido al Mercado del Alcor. ¡No toques mis verduras!

- Granjero Fung' WHERE `ID`=58637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 동영상이 시작됩니다...', `MaleText_loc4`='此处将播放影片……', `MaleText_loc5`='這裡將會播放過場動畫...', `MaleText_loc7`='Aquí tendrá lugar la escena de vídeo...' WHERE `ID`=58638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내... 끝났습니다.', `MaleText_loc4`='总算结束了……', `MaleText_loc5`='終於結束了...', `MaleText_loc7`='Al fin se ha terminado...' WHERE `ID`=58639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄차오에서 기다리고 있겠습니다. 거기서 만나뵙겠습니다.', `MaleText_loc4`='我会在接天桥那里等你。到那里去和我谈一谈吧。', `MaleText_loc5`='我會在天橋上等著。到那裡和我說話。', `MaleText_loc7`='Estaré esperando en el Tan-Chao. Ven y habla conmigo cuando llegues.' WHERE `ID`=58640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 마침내 잠들 수 있게 되었습니다. 모두 당신 덕분이지요. 곧 저도 다음 세상으로 건너가야 합니다.$B$B당신에게 마지막으로 한 가지만 말씀드리고 싶습니다. 판다리아는 오랜 역사를 지닌 땅입니다. 미래가 불확실하다면, 과거에서 그 해답을 찾을 수 있을 것입니다.$B$B이것만 기억하신다면, 여기서 원하는 것을 모두 얻으실 수 있을 겁니다.', `MaleText_loc4`='多亏了你，怨灵们终于可以安息了。很快，我魂归地府。$B$B在走之前，我要给你个忠告：潘达利亚是一块历史悠久的土地。如果你对未来感到迷茫，你只需要从过去寻找答案。$B$B记住这点，你就能在这里如鱼得水。', `MaleText_loc5`='多虧了你，魂靈們終於能安息了。很快，我也會和他們一樣回到另一側去。$B$B讓我給你留下一點忠告:潘達利亞是一片歷史悠久的土地。如果你對未來感到不確定，你只需要到過去尋求答案。$B$B記住這點，你將能在這裡繁榮昌盛。', `MaleText_loc7`='Gracias a ti, los espíritus ya pueden descansar. Muy pronto, yo también regresaré al otro lado.$b$bTe dejo con este consejo: Pandaria es una tierra de historia. Si alguna vez sientes incertidumbre sobre el futuro, solo tienes que buscar respuestas en el pasado.$b$bRecuerda esto y prosperarás.' WHERE `ID`=58641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 음... 어서... 가야 해!', `MaleText_loc4`='哇！呃……我得……走了！', `MaleText_loc5`='呼啊!喔...我..得走了!', `MaleText_loc7`='¡Vaya! Eh... tengo que... ¡irme!', `FemaleText_loc1`='우와! 음... 어서... 가야 해!', `FemaleText_loc4`='哇！呃……我得……走了！', `FemaleText_loc5`='呼啊!喔...我..得走了!', `FemaleText_loc7`='¡Vaya! Eh... tengo que... ¡irme!' WHERE `ID`=58642;
