UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 속에서 뭔가 우르릉거리는군요. 실례하겠습니다!', `MaleText_loc4`='噢！我感觉到有东西在隆隆作响。失陪了！', `MaleText_loc5`='喔!我感覺到有某種東西在隆隆作響。借過!', `MaleText_loc7`='¡Oh! Noto que algo ruge. ¡Con permiso!', `FemaleText_loc1`='윽! 속에서 뭔가 우르릉거려요. 잠깐 실례할게요!', `FemaleText_loc4`='噢！我感觉到有东西在隆隆作响。失陪了！', `FemaleText_loc5`='喔!我感覺到有某種東西在隆隆作響。借過!', `FemaleText_loc7`='¡Oh! Noto que algo ruge. ¡Con permiso!' WHERE `ID`=58645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와. 진짜 독하군요. 좀 뛰어야 할 것 같... 저는 좀 뛰어야겠습니다!', `MaleText_loc4`='哇哦，那可真了不起。我已经跑……呃……我得跑了！', `MaleText_loc5`='哇喔，那可是很強大的東西。我得跑了...呃...得落跑了!', `MaleText_loc7`='Vaya, es muy potente. Me voy de... esto... ¡tengo que irme!', `FemaleText_loc1`='우와. 진짜 독하네요. 좀 뛰어야 할 것 같... 저는 좀 뛰어야겠어요!', `FemaleText_loc4`='哇哦，那可真了不起。我已经跑……呃……我得跑了！', `FemaleText_loc5`='哇喔，那可是很強大的東西。我得跑了...呃...得落跑了!', `FemaleText_loc7`='Vaya, es muy potente. Me voy de... esto... ¡tengo que irme!' WHERE `ID`=58646;
