UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구! 필요하다면 내 수레를 써도 좋소. 수레를 타면 다섯 새벽 사원으로 갈 수 있소.', `MaleText_loc4`='你好啊，朋友！欢迎你乘坐我的牛车。它可以送你去五晨寺。', `MaleText_loc5`='幸會啊朋友!想要的話，歡迎你使用我的車。它會把你送到五晨寺。', `MaleText_loc7`='¡Hola, $gamigo:amiga;! Puedes usar mi carreta si quieres. Te llevará hasta el Templo de los Cinco Albores.' WHERE `ID`=58657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 발자국은 증거로 삼기엔 너무 진흙투성이입니다.', `MaleText_loc4`='这脚印已经变得泥泞难辨。', `MaleText_loc5`='這腳印太模糊了，沒有用。', `MaleText_loc7`='Esta huella está demasiado embarrada para ser de utilidad.' WHERE `ID`=58658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 흔적 옆에는 갉아먹은 당근이 몇 개 보입니다.', `MaleText_loc4`='在这踪迹旁边，你看到一些嚼碎的胡萝卜。', `MaleText_loc5`='痕跡的旁邊，你看見一些被咬過的胡蘿蔔。', `MaleText_loc7`='Junto a este rastro ves restos mordidos de zanahoria.' WHERE `ID`=58659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 발자국은 아주 민첩해 보입니다.', `MaleText_loc4`='那泥泞的踪迹显然是敏捷的爪子留下的。', `MaleText_loc5`='泥上有著清楚的靈巧爪痕。', `MaleText_loc7`='El rastro embarrado muestra claramente una zarpa hábil.' WHERE `ID`=58660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발자국에는 건초 섞인 차가운 진흙과 야크 털이 찍혀 있습니다.', `MaleText_loc4`='被踩进脚印里的，是混有干草和牦牛鬃的泥团。', `MaleText_loc5`='乾草、犛牛毛及淤泥混合成一種像是腳印的模糊痕跡。', `MaleText_loc7`='En la huella hay un trozo de barro mezclado con heno y pelo de yak.' WHERE `ID`=58661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔적 뒤에는 물건을 잡을 수 있는 꼬리가 끌린 자국이 길게 나 있습니다', `MaleText_loc4`='在这印痕后面，有卷尾留下的长长痕迹。', `MaleText_loc5`='痕跡後面有一條長尾巴的痕跡。', `MaleText_loc7`='Detrás de la huella se aprecia la marca alargada de una cola prensil.' WHERE `ID`=58662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직인 흔적 옆에는 예리하고 끝이 뾰족한 창머리와 화려한 깃털이 있습니다.', `MaleText_loc4`='在混战痕迹的边上，散落着一个锋利尖削的矛头，还有几根彩色羽毛。', `MaleText_loc5`='扭打痕跡旁，躺著一支銳利的矛尖和一些鮮豔的羽毛。', `MaleText_loc7`='Junto a las señales de una pelea hay una punta de lanza afilada y algunas plumas de colores.' WHERE `ID`=58663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔적이 북쪽에 있는 산으로 이어집니다.', `MaleText_loc4`='这些最后的足印，一直延伸到北边的山里。', `MaleText_loc5`='足跡通往北邊的山中...', `MaleText_loc7`='Unas huellas conducen a la montaña del norte.' WHERE `ID`=58664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀란 호젠이 가까운 풀숲에서 뛰어오릅니다!', `MaleText_loc4`='一只受惊的猢狲从附近的灌木丛中跳了出来！', `MaleText_loc5`='一個被嚇壞的猴人從附近的一個樹叢中跳了出來!', `MaleText_loc7`='¡Un hozen asustado sale de un arbusto cercano!' WHERE `ID`=58665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모두 이해가 되는군! 우리 농장에 일어났던 온갖 요상한 일들 말일세. 이건 다 호젠 놈들 짓이야! $n, 자네가 나보다 꽤 빨리 알아차린 건 인정해야겠군.', `MaleText_loc4`='现在全都说得通了！发生在我们农场上的各种怪事。幕后黑手一定是猢狲！我必须承认，你分析得很快，$n。', `MaleText_loc5`='這樣就說得通了!農場發生那麼多怪事情。一定都是猴人幹的!我得承認，你解開謎底的速度還挺快的，$n。', `MaleText_loc7`='¡Todo tiene sentido! Todas las cosas raras que han pasado en nuestras granjas. ¡Seguro que los hozen están detrás de todo esto! Debo admitir que lo has averiguado bastante rápido, $n.' WHERE `ID`=58666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 이방인님!', `FemaleText_loc4`='你好，陌生人！', `FemaleText_loc5`='你好啊，陌生人!', `FemaleText_loc7`='¡Qué hay, $gforastero:forastera;!' WHERE `ID`=58667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부 윤의 수레에 대해 이야기해주십시오.', `MaleText_loc4`='给我讲讲与农夫老愚的马车有关的事。', `MaleText_loc5`='告訴我關於農夫尹的貨車的故事吧。', `MaleText_loc7`='Cuéntame la historia sobre el carro del granjero Yoon.', `FemaleText_loc1`='농부 윤의 수레에 대해 이야기해주세요.', `FemaleText_loc4`='给我讲讲与农夫老愚的马车有关的事。', `FemaleText_loc5`='告訴我關於農夫尹的貨車的故事吧。', `FemaleText_loc7`='Cuéntame la historia sobre el carro del granjero Yoon.' WHERE `ID`=58668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠가 아마 이 이야기를 100번은 해줬을 거예요!$B$B대가뭄 때로 되돌아가서 생각해 보면 정말 힘들었대요. 농부들은 농작물이 너무 메말라서 물을 주는 대신 침을 뱉었답니다. 마을 전체가 물이 없어서 메말라가고 있었어요!$B$B그래서 윤의 할아버지께서는 한밤중 수레에 짐을 꾸릴 수밖에 없었답니다.$B$B그리고 무샨 야수를 몰아 쿤라이 봉우리 밑자락에 있는 호수까지 가셨어요. 그리고는 수레에 물통 백 개를 싣고 곧바로 마을로 돌아오셨어요.$B$B윤의 할아버지께서는 수레를 끌고 오는 동안 한 번도 멈추지 않으셨대요! 왜 그러셨냐고요? 마을 주민들이 전부 죽어가고 있었으니까요! 할아버지가 덜컹거리는 수레를 농장까지 끌고 오자 무샨 야수는 그 자리에서 죽어버렸어요!!$B$B하지만 마을 전체와 농작물에 쓸 물은 충분히 가져오셨죠.$B$B윤의 할아버지께서는 언덕골을 구하신 거예요!', `FemaleText_loc4`='我老爸无数次跟我说起过那个故事！$B$B大旱那段期间日子非常难过。农夫们都在用唾沫浇灌庄稼了，因为太干了。整个村子又饿又渴！$B$B所以农夫老愚的祖父在夜里收拾好自己的货车。$B$B然后骑着穆山兽直奔昆莱山脚下的湖泊。他在货车上装满了几百桶清水，然后立即返乡。$B$B他马不停蹄、日夜兼程！他如何能停下脚步？整个村子的人都快渴死了！当他赶着涨裂的货车回到田里时，穆山兽当场就累死了！$B$B但我们村子有了足够的水，并且还完成了春耕。$B$B泽被半山众生，老愚的祖父就是这样的人！', `FemaleText_loc5`='我老爸跟我講這故事一定有上百次了!$B$B在之前大乾旱時期，日子真的很難熬。天氣乾燥到農夫得吐口水在農作物上幫它們澆水。整個城鎮都要因為乾旱而餓死了!$B$B於是農夫尹的爺爺就在半夜把東西打包裝上他的貨車。$B$B然後他駕著他的牡山獸一路去到崑萊峰山腳下。他把那貨車裝滿了上百桶的清水，然後載回來。$B$B他一路上完全沒有停下!他怎麼能停下?我們整個城鎮都快完蛋了!他將那快爛掉的貨車駛回他的農場後他的牡山獸就當場倒地死翹翹!$B$B但是我們整個城鎮得到了足夠的水，還撐到春天收割。$B$B農夫尹的爺爺就這麼拯救了半丘!', `FemaleText_loc7`='¡Mi papi me contó la historia lo menos cien veces!$B$BDurante la gran sequía, las cosas iban muy mal. Era un tiempo tan seco que los granjeros escupían sobre sus cultivos para regarlos. ¡El pueblo entero se moría de sed!$B$BAl abuelo del granjero Yoon se le ocurrió cargar su carreta en mitad de la noche.$B$BLuego llevó a su bestia mushan hasta el lago al pie de la Cima Kun-Lai. Cargó la carreta con cien barriles de agua fresca y luego volvió.$B$B¡No se detuvo ante nada! ¿Cómo iba a hacerlo? ¡Nuestro pueblo entero se moría! Llevó esa carreta destartalada hasta su granja, ¡y su mushan se murió allí mismo!$B$BPero teníamos agua suficiente para todo el pueblo, y también para la cosecha de primavera.$B$B¡El abuelo de Yoon salvó El Alcor!' WHERE `ID`=58669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 연장을 챙겨서 윤의 농장에서 만나요. 거기서 반드시 만나게 될 거예요!', `FemaleText_loc4`='我去拿些工具来，待会在农夫老愚的田里跟你碰头。我打赌一定能赢你！', `FemaleText_loc5`='我會收集好我的工具，跟你在農夫尹那裡碰頭。我敢打賭我一定可以贏你!', `FemaleText_loc7`='Recogeré mis herramientas y me reuniré contigo en la granja de Yoon. ¡Seguro que llego antes que tú!' WHERE `ID`=58670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도시 친구들은 이렇게 참을성이 없나 봐요?', `FemaleText_loc4`='你们这些城里人都这么没耐心？', `FemaleText_loc5`='你們城市佬都這麼沒耐性嗎?', `FemaleText_loc7`='¿Todos los zarpas urbanitas sois tan impacientes?' WHERE `ID`=58671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 이 수레가 혼자 고쳐지지는 않으니까요.', `FemaleText_loc4`='这货车可不会自己把自己修好的。', `FemaleText_loc5`='這個壞掉的馬車不會自己修好的。', `FemaleText_loc7`='Bueno, este carro no se va a arreglar solo.' WHERE `ID`=58672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이렇게 하죠. 계속 투덜대면 제가 망치질을 안 할 거예요.', `FemaleText_loc4`='要不这样吧。你接着嚎，我不干了。', `FemaleText_loc5`='聽著，我跟你講白了。你繼續鬼吼鬼叫我就停下錘子。', `FemaleText_loc7`='Mira, este es el trato. Tú dejas de decir tonterías y yo sigo martilleando.' WHERE `ID`=58673;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 원예도 잘하고, 물건도 잘 고친답니다. 아빠는 거의 모든 걸 고칠 수 있도록 가르쳐주셨어요.', `FemaleText_loc4`='我既会园艺，又能打铁。我老爸把我教成了一个万能修理匠。', `FemaleText_loc5`='我會園藝也會工藝。我把拔教我如何修理所有的東西。', `FemaleText_loc7`='Tengo mano para las plantas y mano para el acero. Mi papi me enseñó a arreglar prácticamente cualquier cosa.' WHERE `ID`=58674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인은 주학의 가르침을 단 며칠 공부했을 뿐인데도 벌써 이해를 하는 것 같습니다.$B$B아니, 원래 알고 있었던 걸까요?', `MaleText_loc4`='在经过短短几天的研学之后，安度因已经理解朱鹤之道了。$B$B也许他天生就懂？', `MaleText_loc5`='看來經過幾天的苦讀後，安杜因已經了解何謂鶴之道了。$B$B或許他一直都明白?', `MaleText_loc7`='Parece que tras solo unos días de estudio, Anduin ya comprende el Camino de la Grulla.$B$BQuizás lo haya comprendido siempre...' WHERE `ID`=58675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<너무 바싹 말라 갈비뼈가 드러난 강아지가 불쌍한 눈으로 당신을 쳐다봅니다.>', `MaleText_loc4`='<那条狗瘦得皮包骨头。它可怜巴巴地望着你。>', `MaleText_loc5`='<狗狗的身體邊緣浮現肋骨的線條。牠用可憐的眼神看著你。>', `MaleText_loc7`='<Al perro se le notan todas las costillas. Te mira con ojos lastimosos.>' WHERE `ID`=58676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<강아지의 털은 흙으로 뒤엉켜 있고, 얕은 숨을 내쉽니다.>', `MaleText_loc4`='<那条狗全身上下沾满泥污。气若游丝。>', `MaleText_loc5`='<狗狗的毛上沾滿了土。牠的氣息十分微弱。>', `MaleText_loc7`='<El perro tiene todo el pelaje sucio. Respira de manera cansina.>' WHERE `ID`=58677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<강아지가 고개를 들어 당신을 보더니 힘없이 꼬리를 흔듭니다.>', `MaleText_loc4`='<那条狗抬起头来看着你，无力地摇着尾巴。>', `MaleText_loc5`='<狗狗抬起頭看著你，虛弱地搖著尾巴。>', `MaleText_loc7`='<El perro levanta la cabeza para mirarte y sacude débilmente la cola.>' WHERE `ID`=58678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 그루멀의 친구, 복 받아요. 도와줘서 고마워요!', `MaleText_loc4`='祝土地精的朋友好运。非常感谢你的帮助！', `MaleText_loc5`='希望咕嚕摩的朋友有很多好運。非常感謝你的幫助!', `MaleText_loc7`='Buena suerte a los amigos de los grúmel. ¡Gracias por la ayuda!' WHERE `ID`=58679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컹!', `MaleText_loc4`='汪！', `MaleText_loc5`='汪!', `MaleText_loc7`='¡Guau!' WHERE `ID`=58680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 행복한 듯 꼬리를 흔듭니다. 강아지가 당신 농장으로 갑니다!', `MaleText_loc4`='狗狗欢快地摇着尾巴。朝你的农场奔去了！', `MaleText_loc5`='狗狗開心地搖尾巴朝著你的農場走去。', `MaleText_loc7`='El perro mueve la cola con alegría. ¡Se dirige a tu granja!' WHERE `ID`=58681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이여, 네 힘으로 날 채워라!', `MaleText_loc4`='翔龙，赐予我力量吧！', `MaleText_loc5`='蛟龍，賦予我你的力量!', `MaleText_loc7`='¡Dragón, otórgame tu poder!' WHERE `ID`=58682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기력이 충만한 놈들이군!', `MaleText_loc4`='他们的力量太强了！', `MaleText_loc5`='他們的能量好強!', `MaleText_loc7`='¡Su energía es fuerte!' WHERE `ID`=58683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 날 실망시키지 마!', `MaleText_loc4`='不，不！别让我失望！', `MaleText_loc5`='不，不!不要讓我失望!', `MaleText_loc7`='¡No, no! ¡No me falles!' WHERE `ID`=58684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 당신을 보고 웃습니다.', `MaleText_loc4`='你的狗狗在对你微笑。', `MaleText_loc5`='你的狗狗向你微笑。', `MaleText_loc7`='Tu perro te sonríe.' WHERE `ID`=58685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 꼬리를 행복하게 흔듭니다.', `MaleText_loc4`='狗狗欢快地摇着尾巴。', `MaleText_loc5`='狗狗開心地搖著尾巴。', `MaleText_loc7`='El perro menea la cola con alegría.' WHERE `ID`=58686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 당신이 무슨 생각을 하는지 궁금하다는 듯이 고개를 갸우뚱거립니다.', `MaleText_loc4`='狗狗歪着脑袋，似乎在猜测你在想什么。', `MaleText_loc5`='狗狗歪過腦袋，好像在思考你心中想些什麼。', `MaleText_loc7`='El perro inclina la cabeza, como preguntándose qué estás pensando.' WHERE `ID`=58687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 당신 손 밑으로 머리를 밀어 넣습니다.', `MaleText_loc4`='你的狗狗把头钻到了你的手底下。', `MaleText_loc5`='你的狗狗自己用頭磨蹭你的手。', `MaleText_loc7`='Tu perro te pone la cabeza bajo la mano.' WHERE `ID`=58688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지도 당신을 사랑합니다!', `MaleText_loc4`='你的狗狗也爱你！', `MaleText_loc5`='你的狗狗也愛你!', `MaleText_loc7`='¡Tu perro también te quiere!' WHERE `ID`=58689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강아지가 혀로 당신 얼굴을 핥습니다.', `MaleText_loc4`='你的狗狗用它那湿乎乎的舌头舔了舔你的脸。', `MaleText_loc5`='你的狗狗在你臉上濕答答地大舔特舔!', `MaleText_loc7`='Tu perro te da un buen lametón en la cara.' WHERE `ID`=58690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위카위카 이제 막 농장 일 시작하려고 했다. 이렇게 어려울 줄 몰랐다.', `MaleText_loc4`='维卡维卡只想试着经营农场。没想到竟然这么难。', `MaleText_loc5`='威卡威卡只是想試著建立農場。沒想到有這麼難。', `MaleText_loc7`='Wika-Wika solo intenta montar una granja. No sabía ke sería tan difícil.' WHERE `ID`=58691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐새끼들 밟아주러 온 거야?', `MaleText_loc4`='你是来帮我教训土拨鼠的吗？', `MaleText_loc5`='你是來踩土鼠鼠的嗎?', `MaleText_loc7`='¿Tú está akí para pisotear muk-muks?' WHERE `ID`=58692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐! 저기 쥐새끼들 있다!', `MaleText_loc4`='瞧！那边就有一只土拨鼠！', `MaleText_loc5`='看!那裡有一隻土鼠鼠!', `MaleText_loc7`='¡Mira! ¡Hay un muk-muk ahí!' WHERE `ID`=58693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 쥐새끼들 더 있다! 조심해!', `MaleText_loc4`='更多的土拨鼠！小心啊！', `MaleText_loc5`='更多土鼠鼠!小心!', `MaleText_loc7`='¡Más muk-muks! ¡Kuidado!' WHERE `ID`=58694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 무는 벌레다! 가까이 오게 하지 마! 쟤네 문다!', `MaleText_loc4`='呃——噢，蜇人的虫子！别让它们靠近你！会咬人的！', `MaleText_loc5`='啊喔，刺刺的蟲!別讓他們靠近你!他們咬人很痛!', `MaleText_loc7`='¡Oh-oh, bichos ke pikan! ¡Tú no deja ke ellos se te acerken! ¡Muerden!' WHERE `ID`=58695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐새끼들이 도망간 것 같다. 이젠 하오한 대장한테 가서 알려야 해.', `MaleText_loc4`='看来那些土拨鼠逃跑了，至少现在是这样。你该去和泥爪老大谈一谈。', `MaleText_loc5`='看來土鼠鼠都跑走了。暫時的。你應該去和泥爪大大說話。', `MaleText_loc7`='Parece que muk-muks se ha marchado. De momento. Tú debe ir a hablar con el jefe Zarpa Fangosa.' WHERE `ID`=58696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쥐새끼들이라고요?', `MaleText_loc4`='土拨鼠？', `MaleText_loc5`='土鼠鼠?', `MaleText_loc7`='¿Muk-muks?', `FemaleText_loc1`='쥐새끼들이라고요?', `FemaleText_loc4`='土拨鼠？', `FemaleText_loc5`='土鼠鼠?', `FemaleText_loc7`='¿Muk-muks?' WHERE `ID`=58697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마모트를 클릭해 밟아버리십시오!', `MaleText_loc4`='点击土拨鼠，踩上去！', `MaleText_loc5`='點擊土撥鼠來進行踩踏!', `MaleText_loc7`='¡Haz clic sobre las marmotas para pisotearlas!', `FemaleText_loc1`='마모트를 클릭해 밟아버리십시오!', `FemaleText_loc4`='点击土拨鼠，踩上去！', `FemaleText_loc5`='點擊土撥鼠來進行踩踏!', `FemaleText_loc7`='¡Haz clic sobre las marmotas para pisotearlas!' WHERE `ID`=58698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레 떼를 피하십시오!', `MaleText_loc4`='躲开虫群！', `MaleText_loc5`='避開蟲群!', `MaleText_loc7`='¡Evita los enjambres de insectos!', `FemaleText_loc1`='벌레 떼를 피하십시오!', `FemaleText_loc4`='躲开虫群！', `FemaleText_loc5`='避開蟲群!', `FemaleText_loc7`='¡Evita los enjambres de insectos!' WHERE `ID`=58699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 쇠뇌만 있으면 전투에서 우리가 상당한 우위를 점할 수 있어! 이제 나머지 하나만 수리해서 작동시킬 수 있으면, 두려울 게 없을 거야.', `MaleText_loc4`='这些弩炮对我们来说真是如虎添翼！如果我们现在把另一架弄好并运转起来，那我们可就牛了。', `MaleText_loc5`='這些弩砲正是我們所需要的優勢!如果我們能讓另一台運作起來，我們可就真的所向披靡了。', `MaleText_loc7`='¡Estas balistas son justo la ventaja que necesitábamos! Y si pudiéramos poner la otra en marcha, seríamos invencibles.' WHERE `ID`=58700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라! 무는 벌레 놈들아!', `MaleText_loc4`='受死吧，可恶的虫子！', `MaleText_loc5`='吃我這招，刺刺蟲!', `MaleText_loc7`='¡Traga esto, bichos ke pikan!' WHERE `ID`=58701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 곡식에서 떨어져!', `MaleText_loc4`='离我的庄稼远点！', `MaleText_loc5`='不要靠近我的作物!', `MaleText_loc7`='¡Fuera de mis cultivos!' WHERE `ID`=58702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살충제를 한입 가득 먹여주마!', `MaleText_loc4`='给你来一大口杀虫剂尝尝！', `MaleText_loc5`='給你吃滿嘴的殺蟲劑!', `MaleText_loc7`='¡Va a llevar un buen bokado de pesticida!' WHERE `ID`=58703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 꺼져! 이 우낏 벌레 놈들아!', `MaleText_loc4`='退后，你们这群该死的虫子！', `MaleText_loc5`='退後，你們這些混蛋害蟲!', `MaleText_loc7`='¡Fuera, bichos machuka!' WHERE `ID`=58704;
