UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 생각에 잠겨 혀를 차며 하늘을 바라봅니다. 공기 냄새를 맡고는 눈살을 찌푸립니다.', `MaleText_loc4`='%s若有所思地扫视着天空，咂咂舌头。她闻着空气，皱起了眉头。', `MaleText_loc5`='%s沉思著檢視天空，彈著舌頭。她嗅著空氣，皺起眉頭。', `MaleText_loc7`='%s estudia el cielo pensativa, chasqueando la lengua. Olfatea el aire y frunce el ceño.' WHERE `ID`=58715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마모트들을 밟아 없애십시오! 곤충 떼는 피하십시오!', `MaleText_loc4`='狠踩土拨鼠！避开虫群！', `MaleText_loc5`='踩扁土撥鼠!防範害蟲群!', `MaleText_loc7`='¡Pisotea a las marmotas! ¡Evita los enjambres de insectos!', `FemaleText_loc1`='마모트들을 밟아 없애십시오! 곤충 떼는 피하십시오!', `FemaleText_loc4`='狠踩土拨鼠！避开虫群！', `FemaleText_loc5`='踩扁土撥鼠!防範害蟲群!', `FemaleText_loc7`='¡Pisotea a las marmotas! ¡Evita los enjambres de insectos!' WHERE `ID`=58716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행길이 즐거우시길 바라요, $r님!$B$B지금은 날씨가 무척 좋아 보이지만, 소나기가 오면 비취 숲의 하늘도 순식간에 어두워진답니다. 공기가 변하고 있는 게 느껴지시나요? 제가 전설적인 폭발 맥주를 만들려고 하는데, 혹시 도와주실 수 있으시겠어요?', `FemaleText_loc4`='旅途愉快，$r！$B$B这天气现在看起来不错，但翡翠林的上空会伴随着风暴迅速阴沉下来。你能感觉到空气在变化吗？也许你想帮我酿造一些我传说中的闪电陈酿？', `FemaleText_loc5`='旅行快樂，$r!$B$B天氣或許看起來不錯，但翠玉林的天空會有突如其來的風暴。你能感覺到大氣的轉變嗎?也許你有興趣幫忙釀造一些我傳說中的轟隆酒?', `FemaleText_loc7`='¡Felices viajes, $r!$B$BPuede que el tiempo sea bueno ahora, pero los cielos del Bosque de Jade se pueden ensombrecer rápidamente con borrascas. ¿Sientes cómo cambia el viento? ¿Me ayudarías a elaborar un poco de mi legendario brebaje relámpago?' WHERE `ID`=58717;
