UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 고집 센 늙은 농사꾼인 건 안다네, 하지만 자네가 나를 위해 큰일을 해준 건 인정해야겠군.', `MaleText_loc4`='我是个顽固的老农夫，可我承认，你帮我了一个大忙。', `MaleText_loc5`='我知道我是個固執的老農民，但我也得承認你為我做出不少貢獻。', `MaleText_loc7`='Sé que soy un viejo y testarudo zarpa granjero, pero admito que has hecho mucho por mí.' WHERE `ID`=58744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 호젠 놈들 때문에 내 농장에 골치 아픈 문제가 많았는데, 자네 덕분에 다 해결됐네.', `MaleText_loc4`='那群猢狲给我的农场添了大麻烦，幸亏你帮我解决了问题。', `MaleText_loc5`='我的農場被那些猴人搞得雞飛狗跳，多虧你它才能得救。', `MaleText_loc7`='Mi granja corría peligro por culpa de los hozen, pero gracias a ti se ha salvado.' WHERE `ID`=58745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 내게 표를 얻는 것 이상의 일을 해낸 걸세.', `MaleText_loc4`='我一定会投你一票。', `MaleText_loc5`='你可不只贏得我的贊同而已。', `MaleText_loc7`='Te has ganado mi voto con creces.' WHERE `ID`=58746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 마지막 남은 이 자리는 자네와 농부 윤의 자리일세. 어서 예를 올리지 그러나.', `MaleText_loc4`='$n，这最后一块地是给你和农夫老愚的。你何不欣然接受？', `MaleText_loc5`='$n，這最後的空位是給你和農夫尹的。你何不盡一下主人之誼呢?', `MaleText_loc7`='$n, este sitio de aquí es para el granjero Yoon y para ti. ¿Por qué no haces los honores?' WHERE `ID`=58747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤, 그리고 $n. 우리와 한가족이 돼서 영광일세.', `MaleText_loc4`='老愚，$n，很荣幸能邀请你们加入。', `MaleText_loc5`='尹，$n，很榮幸有你們加入我們。', `MaleText_loc7`='Es un honor aceptaros entre nosotros, Yoon y $n.' WHERE `ID`=58748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 정말입니다! $n 님 덕분에 이 원숭이 놈들이 우두머리를 잃었습니다. 이제 저놈들은 하오한 씨의 밭에 문제를 일으키진 않을 겁니다.', `MaleText_loc4`='是真的！多亏了$n，昆森部族的头领已死。那群猴子应该再也不会骚扰泥爪先生了。', `MaleText_loc5`='沒錯，是真的!多虧了$n，崑真的領袖死了。那些猴崽子們應該再也不會打攪泥爪先生了。', `MaleText_loc7`='¡Es cierto! Gracias a $n, el líder Kunzen ha muerto. Esos monos ya no molestarán al señor Zarpa Fangosa.' WHERE `ID`=58749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 드디어! 정말 제가 바라던 일이었습니다! 네, 하오한 씨! 당연히 농사꾼 연합에 들어가야죠!', `MaleText_loc4`='噢，终于盼到了！这是我最大的梦想！是的，泥爪先生！我当然愿意加入！', `MaleText_loc5`='喔，終於啊!我的夢想實現了!是的，泥爪先生!我當然要加入你們!', `MaleText_loc7`='¡Oh, por fin! ¡Este es mi gran sueño! ¡Sí, Sr. Zarpa Fangosa! ¡Por supuesto que me uniré a ustedes!' WHERE `ID`=58750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 일해라!', `MaleText_loc4`='快点干！', `MaleText_loc5`='動作快點!', `MaleText_loc7`='¡Trabaja más rápido!' WHERE `ID`=58751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어서 오십시오. 양념 사러 오셨습니까? 낯설고, 희귀하거나, 진귀한 양념을 찾으시나 보군요?$b$b그렇다면 잘 찾아오신 겁니다...', `MaleText_loc4`='啊，欢迎你。你是来买香料的吗？奇特的、稀有的、异国的香料？$b$b那你可来对地方了……邻居。', `MaleText_loc5`='啊，歡迎。你來這裡買香料嗎?奇特的、稀有的異國香料?$b$b你來對地方了...好鄰居。', `MaleText_loc7`='Ah, hola. ¿Estás aquí para comprar especias? ¿Especias poco comunes, raras y exóticas?$b$bHas venido al lugar adecuado... $gvecino:vecina;.' WHERE `ID`=58752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 도와드릴까요, $c님?', `MaleText_loc4`='我能帮你什么忙吗，$c？', `MaleText_loc5`='$c，我能幫你嗎?', `MaleText_loc7`='¿Puedo ayudarte, $c?' WHERE `ID`=58753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어오세요, 들어오세요! 오늘 뭐 필요한 거라도 있으십니까?', `MaleText_loc4`='快进来，快进来！我今天能为你做些什么吗？', `MaleText_loc5`='進來，快進來!今天有什麼我可以為你效勞的?', `MaleText_loc7`='¡Pasa, pasa! ¿Hay algo que pueda hacer por ti hoy?' WHERE `ID`=58754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 당신이 지나 머드클로에게 진 빚 때문에 그러는데, 제가 대신 왔습니다.', `MaleText_loc4`='你好！我是代表吉娜·泥爪前来跟你谈谈你所欠下的债务。', `MaleText_loc5`='哈囉!我代表吉娜·泥爪前來，為了你的欠款。', `MaleText_loc7`='¡Hola! He venido en nombre de Gina Zarpa Fangosa por lo de tu deuda.', `FemaleText_loc1`='안녕하세요! 당신이 지나 머드클로에게 진 빚 때문에 그러는데, 제가 대신 왔어요.', `FemaleText_loc4`='你好！我是代表吉娜·泥爪前来跟你谈谈你所欠下的债务。', `FemaleText_loc5`='哈囉!我代表吉娜·泥爪前來，為了你的欠款。', `FemaleText_loc7`='¡Hola! He venido en nombre de Gina Zarpa Fangosa por lo de tu deuda.' WHERE `ID`=58755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으름 피우지 마라!', `MaleText_loc4`='别偷懒！', `MaleText_loc5`='不准偷懶!', `MaleText_loc7`='¡Deja de holgazanear!' WHERE `ID`=58756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드리고 말고요. 지금 바로 돈을 드리겠습니다. 그리고 지나에게 제 안부 좀... 전해주십시오.', `MaleText_loc4`='没问题。我欠她的钱就在这儿。顺便替我……问候她。', `MaleText_loc5`='當然，我這裡有她的款項。請順便替我向她...致意。', `MaleText_loc7`='Por supuesto. Tengo su pago justo aquí. Y salúdala de mi parte.' WHERE `ID`=58757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나라고요? 아 그 상점 일을 하는 여자 말입니까? 하하!$b$b그 조그만 아줌마에게 직접 돈을 받으러 오라고 말해주십시오. 그러면 저랑 둘이서 확실히... 뭔가 담판 지을 수 있으니까요.', `MaleText_loc4`='吉娜？市集里的那个小女孩？哈哈！$b$b替我转告那个小美女，让她亲自来收钱。我相信在她跟我之间能达成某种……协议。', `MaleText_loc5`='吉娜?那個市集裡的女孩?哈!$b$b告訴那個漂亮的小東西，叫她自己來拿錢。我相信我跟她可以達成某種...協議。', `MaleText_loc7`='¿Gina? ¿Esa chica del mercado? ¡Ja!$b$bDile a esa muchachita que venga ella misma a cobrar el dinero. Seguro que ella y yo podemos llegar a algún tipo de... acuerdo.' WHERE `ID`=58758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 더 세게 때릴 테다!', `MaleText_loc4`='下次我会打得更重！', `MaleText_loc5`='下次我會打得更用力!', `MaleText_loc7`='¡La próxima vez te golpearé más fuerte!' WHERE `ID`=58759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빚이라고요? 저는 그 여자에게 빚진 게 없습니다.$b$b지나가 제게 양념을 준 건... 맞습니다. 제게 윙크한 것도 봤고 말입니다. 당신도 저 같이 잘생기면 이런 일쯤이야 비일비재한 겁니다.$b$b아직도 여기 있는 겁니까? 이제 저리 가십시오.', `MaleText_loc4`='我的债务？我可不欠她什么。$b$b我相当确认，那些香料，是她……送给我的。我看见她对我抛媚眼了。如果你跟我一样英俊潇洒，就也能经常碰到这种好事。$b$b你怎么还在这儿？快走吧，小$r。', `MaleText_loc5`='我的欠款?我沒欠那小姑娘任何東西。$b$b我很確定...她把那些香料「送」給我了。我看到她對我眨了眨眼。這種事只會發生在像我這麼英俊的人身上。$b$b你還在這兒啊?走開吧，小$r。', `MaleText_loc7`='¿Mi deuda? Yo no le debo nada a esa chica.$b$bEstoy seguro de que me... regaló esas especias. Vi cómo me guiñaba el ojo. Estas cosas pasan cuando eres tan guapo como yo.$b$b¿Todavía estás aquí? Lárgate, $gpequeño:pequeña; $r.' WHERE `ID`=58760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 판다렌은 약해 빠졌다.', `MaleText_loc4`='你们熊猫人可真弱。', `MaleText_loc5`='你們熊貓人真弱。', `MaleText_loc7`='Los pandaren sois débiles.' WHERE `ID`=58761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리한테 땅을 빼앗긴 걸로도 모자라서, 이제 식량을 빼앗기는군.', `MaleText_loc4`='我们夺取了你们的土地，现在还要抢走你们的食物。', `MaleText_loc5`='我們奪走了你們的土地，現在我們要奪走你們的食物。', `MaleText_loc7`='Os arrebatamos la tierra y ahora la comida.' WHERE `ID`=58762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포악하게 위협합니다.> 주둥이에 한 방 먹고 싶습니까?', `MaleText_loc4`='<用暴力威胁他。>你想让我一拳打进你嘴里吗？', `MaleText_loc5`='<用暴力威脅他。>你嘴巴想挨揍嗎?', `MaleText_loc7`='<Amenázalo con violencia.> ¿Quieres que te pegue un puñetazo en la boca?', `FemaleText_loc1`='<포악하게 위협합니다.> 주둥이에 한 방 먹고 싶어요?', `FemaleText_loc4`='<用暴力威胁他。>你想让我一拳打进你嘴里吗？', `FemaleText_loc5`='<用暴力威脅他。>你嘴巴想挨揍嗎?', `FemaleText_loc7`='<Amenázalo con violencia.> ¿Quieres que te pegue un puñetazo en la boca?' WHERE `ID`=58763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이, 이보십시오! 폭력을 쓸 필요까진 없잖습니까! 알겠습니다. 돈을 드리지요... 하지만 제가 기분이 좋을 거라고는 생각하지 마십시오.', `MaleText_loc4`='嘿，嘿！别动手啊！好吧，我付……但别指望我会高高兴兴地掏钱。', `MaleText_loc5`='嘿，嘿!不需要動手動腳的!好啦，我會付錢...但別期待我會情願地給錢。', `MaleText_loc7`='¡Oye, oye! ¡No hace falta llegar a las manos! De acuerdo, te pagaré... pero no esperes que lo haga alegremente.' WHERE `ID`=58764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 재미있군!', `MaleText_loc4`='这可真有趣！', `MaleText_loc5`='真是太好玩了!', `MaleText_loc7`='¡Qué divertido!' WHERE `ID`=58765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<빚을 갚아준다고 말합니다.> 걱정하지 마십시오. 오늘은 제가 빚을 갚아드리겠습니다.', `MaleText_loc4`='<提出替他还债。>别担心。我今天替你还上。', `MaleText_loc5`='<提議替他繳清欠款。>別擔心。我今天會把你那份付清。', `MaleText_loc7`='<Ofrécete a pagar su deuda.> No te preocupes. Yo pagaré tu deuda hoy.', `FemaleText_loc1`='<빚을 갚아준다고 말합니다.> 걱정하지 마세요. 오늘은 제가 빚을 갚아드릴게요.', `FemaleText_loc4`='<提出替他还债。>别担心。我今天替你还上。', `FemaleText_loc5`='<提議替他繳清欠款。>別擔心。我今天會把你那份付清。', `FemaleText_loc7`='<Ofrécete a pagar su deuda.> No te preocupes. Yo pagaré tu deuda hoy.' WHERE `ID`=58766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식은 없다! 일해라!', `MaleText_loc4`='不许休息，赶紧干活！', `MaleText_loc5`='不准休息，快工作!', `MaleText_loc7`='¡Nada de descansos, solo trabajar!' WHERE `ID`=58767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러셔야지요. 이제 가십시오! 훠이! 손님들이 무서워하지 않습니까!', `MaleText_loc4`='这还差不多。现在就去吧。嘘！你要吓跑真正的顾客了！', `MaleText_loc5`='這才像話。現在滾吧。去!你把客人都嚇走了!', `MaleText_loc7`='Eso está mejor. Ahora lárgate. ¡Fuera! ¡Estás ahuyentando a los clientes de verdad!' WHERE `ID`=58768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 꼭 너희처럼 무르구나.', `MaleText_loc4`='这片土地就跟你们一样软弱。', `MaleText_loc5`='這塊土地就跟你們一樣軟趴趴。', `MaleText_loc7`='Esta tierra es débil como ustedes.' WHERE `ID`=58769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='팔아치울 게 아주 많습니다. 야크 털 목걸이가 아주 잘 팔리지요. 행운이 넘치거든요.', `MaleText_loc4`='是的，好货品应有尽有。看看这用牦牛毛做的护符。非常热销。非常好运。', `MaleText_loc5`='是的，有很多東西要賣。犛牛毛護身符。很受歡迎。非常靈驗。', `MaleText_loc7`='Muchas cosas para vender, sí. Amuletos de pelo de yak. Muy populares. Dan mucha suerte.' WHERE `ID`=58770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 보물을 가져옵니다. 아주 먼 곳에 있는 보물 말입니다. 산 너머에 있는 보물도... 또 장벽 너머에 있는 보물까지도 말입니다.', `MaleText_loc4`='我携宝物而来。来自远方的宝物。来自山那边的宝物……甚至有来自长城另一侧的宝物。', `MaleText_loc5`='我帶了寶物。從很遠的地方來的寶物。從山的另一頭帶來的寶物...甚至是，從牆的另一端來的寶物。', `MaleText_loc7`='Traigo tesoros. Tesoros desde muy lejos. Tesoros desde más allá de las montañas... tesoros desde más allá del muro, incluso.' WHERE `ID`=58771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 운이 아주 좋은 날이군요. 안 그렇습니까?', `MaleText_loc4`='今天可真是百年不遇的好日子啊，不是吗？', `MaleText_loc5`='今天真是個幸運的好日子，不是嗎?', `MaleText_loc7`='Este día promete mucho, ¿verdad?' WHERE `ID`=58772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 언덕골 시장에 있는 여자 말씀이시군요! 여기 있습니다!! 위풍당당한 $c님이 이렇게 대신 와주셨는데, 똑똑한 그루멀이라면 당연히 빚을 갚아야지요.', `MaleText_loc4`='噢是的！市集上的女孩！拿去吧！当一个气宇轩昂的$c参与进来时，聪明的人就会还债。', `MaleText_loc5`='喔對!市集女孩!你來了!當有個雄壯威武的$c在場時，聰明的人會懂得還清他的欠款。', `MaleText_loc7`='¡Ah, sí! ¡La chica del mercado! ¡Aquí tienes! Un hombre sabio paga sus deudas cuando $gun:una; imponente $c está de por medio.' WHERE `ID`=58773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 이는 빚을 즉각 갚습니다. 더 현명한 이는 사기를 당할 때 알아채고 말이지요.$b$b지나는 시장에 앉아서 하루 종일 돈만 셉니다. 그런데 저는 쓸쓸히 길을 걸어 다니다가 운이 좋아야 간신히 하루를 먹고 삽니다. 왜 제가 빚을 갚아야 하는 겁니까?', `MaleText_loc4`='聪明人会立刻还债。更聪明的人则会判断出自己是不是被敲诈了。$b$b吉娜一天到晚都坐在集市里数钱。而我却走在荒无人烟的路上，靠运气勉强糊口。我为什么应该付钱？', `MaleText_loc5`='一個聰明的人會立即還清欠款。一個聰明的人也知道自己什麼時候在被敲詐。$b$b吉娜整天坐在市集裡數錢。而我只是孤獨地做我自己的事，很幸運才能勉強餬口。為什麼我要付錢?', `MaleText_loc7`='Un hombre sabio paga sus deudas inmediatamente. Un hombre más sabio sabe cuándo le están estafando.$b$bGina se sienta en el mercado y cuenta dinero durante todo el día. Yo recorro carreteras solitarias y tengo suerte si consigo lo suficiente para ir tirando. ¿Por qué tendría que pagar?' WHERE `ID`=58774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나의 아버지는 돈이 아주, 아주 많습니다. 그러니 돈이 필요하면 언제든지 아버지에게 달라고 할 수 있지요.$b$b그런데도 지나는 왜 이렇게 가난하고 늙은 잠비지를 괴롭히는 겁니까?', `MaleText_loc4`='吉娜的父亲很富有，超级富有。要是她缺钱，可以直接去跟他说啊。$b$b为什么非要跟可怜的老迦姆比兹过不去？', `MaleText_loc5`='吉娜的父親非常、非常有錢。如果她想要錢，她可以去跟她爸爸說。$b$b為什麼她一定要來煩可憐的老傑必基?', `MaleText_loc7`='El padre de Gina es muy, muy rico. Si quiere dinero, siempre puede hablar con él.$b$b¿Por qué tiene que molestar al pobre de Jambeezi?' WHERE `ID`=58775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포악하게 위협합니다.>
빚은 빚입니다. 돈 좀 있나 봐야겠군요.', `MaleText_loc4`='<用暴力威胁他。>
欠债还钱。用钱说话。', `MaleText_loc5`='<用暴力威脅他。>
欠錢就是欠錢。把錢拿出來。', `MaleText_loc7`='<Amenázalo con violencia.>
Una deuda es una deuda. A ver ese dinero.', `FemaleText_loc1`='<포악하게 위협합니다.>
빚은 빚이에요. 돈이 있나 봐야겠어요.', `FemaleText_loc4`='<用暴力威胁他。>
欠债还钱。用钱说话。', `FemaleText_loc5`='<用暴力威脅他。>
欠錢就是欠錢。把錢拿出來。', `FemaleText_loc7`='<Amenázalo con violencia.>
Una deuda es una deuda. A ver ese dinero.' WHERE `ID`=58776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 이보십시오! 마을 한가운데서 주먹을 치켜들면 불운이 찾아옵니다.$b$b제가 그냥... 당신을 좀 시험해본 겁니다. 여기 빚진 돈 받으십시오.', `MaleText_loc4`='够了，够了！在镇中心打架真是晦气。我只是……只是在试探你。这是我欠的钱。', `MaleText_loc5`='現在就給，現在就給!在鎮中央舉起拳頭可會招來壞運。$b$b我只是...我只是在測試你。這是我欠的錢。', `MaleText_loc7`='¡Calma, calma! Da mala suerte sacar los puños en mitad de la ciudad.$b$bSolo estaba... Solo te estaba poniendo a prueba. Aquí tienes el dinero que debo.' WHERE `ID`=58777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<빚을 갚아준다고 말합니다.>
걱정하지 마십시오, 잠비지. 오늘은 제가 빚을 대신 갚아 드리겠습니다.', `MaleText_loc4`='<提出替他还债。>
别担心，迦姆比兹。我今天替你还上。', `MaleText_loc5`='<提議替他繳清欠款。>
別擔心，傑必基。我今天會把你那份付清。', `MaleText_loc7`='<Ofrécete a pagar su deuda.>
No te preocupes, Jambeezi. Yo pagaré la deuda por ti hoy.', `FemaleText_loc1`='<빚을 갚아준다고 말합니다.>
걱정하지 마세요, 잠비지. 오늘은 제가 빚을 대신 갚아 드릴게요.', `FemaleText_loc4`='<提出替他还债。>
别担心，迦姆比兹。我今天替你还上。', `FemaleText_loc5`='<提議替他繳清欠款。>
別擔心，傑必基。我今天會把你那份付清。', `FemaleText_loc7`='<Ofrécete a pagar su deuda.>
No te preocupes, Jambeezi. Yo pagaré la deuda por ti hoy.' WHERE `ID`=58778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인격이 높으신 만큼 친절도 하시군요. 이방인을 도우면 복을 받는다더군요.', `MaleText_loc4`='你不光聪明，还很和善。帮助陌生人会为你带来好运的。', `MaleText_loc5`='你的仁慈就像你的智慧一樣多。能幫助一個陌生人是很幸運的事。', `MaleText_loc7`='Eres tan amable como inteligente. Da mucha suerte ayudar a un desconocido.' WHERE `ID`=58779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='들어오셔서 좀 앉으세요. 그리고 좀 쉬시고요... 분명히 하루 종일 돌아다니셨을 테니까요.$b$b자, 이제 뭘 찾으시나요?', `FemaleText_loc4`='进来坐坐，别老站着……我肯定你在外面跑了一整天了。$b$b那么，我有什么可以效劳的？', `FemaleText_loc5`='進來坐坐吧。移動你的雙腳...我相信你已經到處跑了一整天。$b$b現在，我能為你做什麼呢?', `FemaleText_loc7`='Entra y toma asiento. Descansa los pies... Seguro que has estado corriendo por ahí todo el día.$b$bBueno, ¿qué puedo hacer por ti?' WHERE `ID`=58780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 꽤 푹하네요, 그렇죠?', `FemaleText_loc4`='今天外面挺暖和的，对吧？', `FemaleText_loc5`='今天外頭很溫暖，不是嗎?', `FemaleText_loc7`='Hace bastante calor hoy, ¿no crees?' WHERE `ID`=58781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕골에 오신 걸 환영해요.', `FemaleText_loc4`='欢迎来到半山，邻居。', `FemaleText_loc5`='歡迎來到半丘，好鄰居。', `FemaleText_loc7`='Bienvenido a El Alcor, $gvecino:vecina;.' WHERE `ID`=58782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 드려야죠! 들러주셔서 고마워요. 여기 빚진 돈을 드릴게요.', `FemaleText_loc4`='那是当然！谢谢你能来。这些是我付的钱。', `FemaleText_loc5`='當然囉!謝謝你過來。這是我的欠款。', `FemaleText_loc7`='¡Por supuesto que sí!$b$bGracias por venir. Aquí tienes el pago.' WHERE `ID`=58783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 오늘 빚을 갚을 수 있으면 좋겠는데... 요즘 가게 일이 너무 안 돼서 말이에요.$b$b몇 푼 안 되는 돈은 가족과 함께 먹을 저녁을 사야 해서요. 제발... 이 정도는 봐주실 수 있잖아요.', `FemaleText_loc4`='我也想今天就能还上钱……但这段时间生意难做呀，我实在是没有钱。$b$b我身上仅有的几块金币还是准备给我家人买晚餐的。求求你……发发慈悲帮助我吧。', `FemaleText_loc5`='我真希望我今天能付錢...但最近生意很差。我實在沒錢。$b$b我手邊剩下的幾個金幣要拿去買晚餐給我的家人。拜託...你一定能做點什麼的。', `FemaleText_loc7`='Ojalá pudiera pagarte hoy... pero el negocio me ha ido muy mal últimamente. Simplemente no tengo el dinero.$b$bLas pocas monedas de oro que tengo son para comprar la cena para mi familia. Por favor... debe de haber algo que puedas hacer.' WHERE `ID`=58784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 빚을 졌다는 건 알고 있어요. 원하신다면 갚을 수도 있는데, 하지만...$b$b저는 지금 이 돈이 정말 필요해요. 우리 여관이 지금 다 무너지기 직전이란 말이에요. 여관 수리에 돈을 쓰지 않으면, 제 직장도 없어지고... 집도 없어진답니다.', `FemaleText_loc4`='我明白，我欠你钱。如果能还我肯定还了，但是……$b$b我急需这笔钱。我们的小店已经年久失修。如果我没钱付维修费的话，我不仅会失业……而且家庭也要垮了。', `FemaleText_loc5`='我了解，我欠了錢。如果有需要，我會還給你，但是...$b$b我「需要」這筆錢。我們的旅舍快要倒塌了。如果我沒錢去整修它，我就要失業了...也無家可歸了。', `FemaleText_loc7`='Lo entiendo, te debo dinero. Puedo pagarte si es necesario, pero...$b$bNecesito este dinero. Nuestra posada se cae a pedazos. Si no tengo dinero para pagar las reparaciones, me quedaré sin trabajo... y sin casa.' WHERE `ID`=58785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포악하게 위협합니다.> 그건 제가 알 바 아닙니다. 돈을 내거나 아니면 대가를 치르십시오.', `MaleText_loc4`='<用暴力威胁她。>那不关我事。给钱，不然就承担后果。', `MaleText_loc5`='<用暴力威脅她。>這不是我的問題。還錢，不然就等著面對後果。', `MaleText_loc7`='<Amenázala con violencia.> Eso no es mi problema. Paga o atente a las consecuencias.', `FemaleText_loc1`='<포악하게 위협합니다.> 그건 제가 알 바 아니에요. 돈을 내거나 아니면 대가를 치르세요.', `FemaleText_loc4`='<用暴力威胁她。>那不关我事。给钱，不然就承担后果。', `FemaleText_loc5`='<用暴力威脅他。>這不是我的問題。還錢，不然就等著面對後果。', `FemaleText_loc7`='<Amenázala con violencia.> Eso no es mi problema. Paga o atente a las consecuencias.' WHERE `ID`=58786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠어요. 여기 돈을 드릴게요. 시간을 너무 많이 빼앗아서 죄송했어요.', `FemaleText_loc4`='我明白了，这是我的欠款。很抱歉占用你这么长时间，$g先生:女士;。', `FemaleText_loc5`='我了解了。這裡是欠款。我很抱歉占用你那麼多時間，$g先生:夫人;。', `FemaleText_loc7`='Lo entiendo. Aquí tienes el pago. Siento haberte hecho perder tanto tiempo, $gseñor:señora;.' WHERE `ID`=58787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<빚을 갚아준다고 말합니다.> 오늘은 제가 빚을 갚아드리겠습니다. 그 정도는 해 드릴 수 있습니다.', `MaleText_loc4`='<提出替她还债。>我今天替你还上。我也只能做这么多了。', `MaleText_loc5`='<提議替她繳清欠款。>我今天會幫你付欠款。至少我能做到這點。', `MaleText_loc7`='<Ofrécete a pagar su deuda.> Yo te pagaré la deuda hoy. Es lo menos que puedo hacer.', `FemaleText_loc1`='<빚을 갚아준다고 말합니다.> 오늘은 제가 빚을 갚아드릴게요. 그 정도는 해 드릴 수 있어요.', `FemaleText_loc4`='<提出替她还债。>我今天替你还上。我也只能做这么多了。', `FemaleText_loc5`='<提議替她繳清欠款。>我今天會幫你付欠款。至少我能做到這點。', `FemaleText_loc7`='<Ofrécete a pagar su deuda.> Yo te pagaré la deuda hoy. Es lo menos que puedo hacer.' WHERE `ID`=58788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 정말 좋은 분이시군요. 이 선행은 잊지 않겠습니다.', `FemaleText_loc4`='你是位心地善良的$g先生:女士;，$n。我们不会忘记你的这份恩情。', `FemaleText_loc5`='你真是個好$g人:女人;，$n。我絕不會忘記你這樣的善行。', `FemaleText_loc7`='Eres $gun:una; $ghombre:mujer; excepcional, $n. Este acto de bondad no caerá en el olvido.' WHERE `ID`=58789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 많은 이들이 오고 갑니다. 그걸 보니 인생에 대해 생각하게 되더라 이겁니다.$b$b뭐랄까, 저도... 어디를 좀 왔다갔다 해보고 싶군요.', `MaleText_loc4`='看着如今这些来来往往的人。真会引发你对人生的思考。$b$b比如，也许……我也应该到别的地方来来往往一把。', `MaleText_loc5`='這麼多人來了又走。這真的會讓你開始思考人生。$b$b就像，或許...我也應該去某個地方遠行。', `MaleText_loc7`='Todos estos amigos que vienen y van estos días. Te hace reflexionar sobre la vida.$b$bComo que, quizá... yo también debería estar yendo y viniendo de algún sitio.' WHERE `ID`=58790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바깥에는 뭐가 있다고 생각하십니가? 제 말은 이 판다리아 외부에 말입니다.', `MaleText_loc4`='你觉得外面是什么样的？我是说，潘达利亚外面的世界？', `MaleText_loc5`='你認為外頭有什麼?我是說，潘達利亞外頭?', `MaleText_loc7`='¿Qué piensas que habrá ahí fuera? Fuera de Pandaria, quiero decir.' WHERE `ID`=58791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 이유 없이 걸어보신 적이 있습니까? 언덕 반대편에 뭐가 있는지 보고 싶어서 말입니다.$b$b어머니께서는 제가 잠시도 가만있지 않는데다가 머리까지도 약간 이상한 것 같다고 하셨습니다. 하지만 제가 볼 때는 어머니가 한참 잘못 생각하고 계신 것 같았습니다.', `MaleText_loc4`='你总是四处游走，漫无目的吗？只是为了看看在山的那一边有些什么？$b$b妈妈总说我有一双停不下来的脚，除此之外还有个颠三倒四的大脑袋。可我觉得，也许犯糊涂的是她才对。', `MaleText_loc5`='你曾經沒有任何原因，只是一直走嗎?只是想看看山丘外的世界?$b$b我媽說我有一雙停不下來的腳跟胡思亂想的腦袋。但我想，也許她是唯一思想落後的人。', `MaleText_loc7`='¿Alguna vez has salido a caminar sin ninguna razón en concreto? ¿Solo para ver lo que hay al otro lado de la colina?$b$bMamá dice que tengo pies inquietos y que, por si fuera poco, tengo el cerebro del revés. Pero yo creo que es ella la que lo tiene todo del revés.' WHERE `ID`=58792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나! 생각납니다! 며칠 전에 제가 물건을 조금 구입했지요.$b$b여기 돈을 드리겠습니다. 제 안부 좀 전해주십시오.', `MaleText_loc4`='我记得吉娜！几天前，我从她那里买了一些物资。给你钱。请转告我对她的问候。', `MaleText_loc5`='我記得吉娜!就在幾天前，我從她那裡帶了一些補給品。錢在這裡。替我跟她打聲招呼。', `MaleText_loc7`='¡Me acuerdo de Gina! Le compré algunas provisiones hace unos días. Aquí tienes el dinero. Salúdala de mi parte.' WHERE `ID`=58793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런...$b$b이런 말씀을 드려서는 안 되겠지만, 이 마을을 떠나려고 돈을 모으는 중입니다. 한곳에 머물러 있는 것도 이젠 못참겠더군요.$b$b당신은 모험가니까... 이해하실 겁니다. 저 좀 도와주시겠습니까?', `MaleText_loc4`='额——噢……$b$b我也许不该告诉你，可我正在存钱，准备离开这镇子。我再也受不了只待在一个地方了。$b$b你是个冒险家……你明白的。能帮帮我吗？', `MaleText_loc5`='呃喔...$b$b或許我不該告訴你，但我正在存錢準備離開這個鎮。我就是沒辦法再待在同一個地方。$b$b你是個冒險者...你了解的。你能幫我離開嗎?', `MaleText_loc7`='Oh-oh...$b$bProbablemente no debería decírtelo, pero estoy ahorrando dinero para irme de esta ciudad. Ya no soporto quedarme en un sitio.$b$bA ti te gusta la aventura... así que me entenderás. ¿Podrías echarme una mano?' WHERE `ID`=58794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 검과 방패를 들어 올립니다.', `MaleText_loc4`='%s拿出了佩剑和盾牌。', `MaleText_loc5`='%s抽出劍和盾。', `MaleText_loc7`='%s desenfunda su espada y alza su escudo.' WHERE `ID`=58795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이런. 어머니께서 이걸 아시면 골치가 아주 아플 겁니다.$b$b저 대신 빚 좀 갚아주시겠습니까?', `MaleText_loc4`='噢……噢不。要是让妈妈知道，我就有大麻烦了。$b$b你能帮我还债吗？', `MaleText_loc5`='喔...喔不。如果被老媽發現這件事，我就有大麻煩了。$b$b你能幫我付我的欠款嗎?', `MaleText_loc7`='Oh... Oh, no. Me voy a meter en un buen lío cuando mamá se entere de esto.$b$b¿Podrías pagar la deuda por mí?' WHERE `ID`=58796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 방패를 내려놓고 단검을 뽑아 듭니다.', `MaleText_loc4`='%s丢下盾牌，拔出一把匕首。', `MaleText_loc5`='%s丟下盾，抽出匕首。', `MaleText_loc7`='%s tira su escudo y saca una daga.' WHERE `ID`=58797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포악하게 위협합니다.> 인생 수업 좀 받아야겠군요. 어서 돈을 주십시오.', `MaleText_loc4`='<用暴力威胁他。>看来得有人给你上一课了，孩子。给钱。', `MaleText_loc5`='<以暴力脅迫他。>你需要受點教訓，小子。快付錢。', `MaleText_loc7`='<Amenázalo con violencia.> Tienes que aprender una lección, chico. Paga.', `FemaleText_loc1`='<포악하게 위협합니다.> 인생 수업 좀 받아야겠네요. 어서 돈을 주세요.', `FemaleText_loc4`='<用暴力威胁他。>看来得有人给你上一课了，孩子。给钱。', `FemaleText_loc5`='<以暴力脅迫他。>你需要受點教訓，小子。快付錢。', `FemaleText_loc7`='<Amenázalo con violencia.> Tienes que aprender una lección, chico. Paga.' WHERE `ID`=58798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아! 정말... 정말 진심이시군요! 좋아요, 알겠습니다... 이제 제가 가진 전부입니다.', `MaleText_loc4`='哇！你……你是认真的！好吧，算了……我身上就这么多。', `MaleText_loc5`='哇喔!你...你是認真的!好吧，好吧...這是我所有的家當了。', `MaleText_loc7`='¡Uff! ¡Estás... estás hablando en serio! Vale, de acuerdo... aquí tienes todo lo que tengo.' WHERE `ID`=58799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<빚을 갚아준다고 말합니다.> 이번에는 제가 빚을 갚아 드리겠습니다. 다음번에는 조금 더 책임감 있게 빚을 갚아주십시오.', `MaleText_loc4`='<提出替他还债。>我今天先替你还上。下次，学会有所担当。', `MaleText_loc5`='<提議替他繳清欠款>我這次會幫你付欠款。下次有點責任感。', `MaleText_loc7`='<Ofrécete a pagar su deuda.> Yo pagaré tu deuda hoy. La próxima vez, trata de ser más responsable.', `FemaleText_loc1`='<빚을 갚아준다고 말합니다.> 이번에는 제가 빚을 갚아 드릴게요. 다음번에는 조금 더 책임감 있게 빚을 갚아주세요.', `FemaleText_loc4`='<提出替他还债。>我今天先替你还上。下次，学会有所担当。', `FemaleText_loc5`='<提議替他繳清欠款>我這次會幫你付欠款。下次有點責任感。', `FemaleText_loc7`='<Ofrécete a pagar su deuda.> Yo pagaré tu deuda hoy. La próxima vez, trata de ser más responsable.' WHERE `ID`=58800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 정말이십니까? 이 은혜는 절대 잊지 않겠습니다!', `MaleText_loc4`='真——真的？我不会忘记的，$g先生:女士;！', `MaleText_loc5`='真，真的嗎?我不會忘記這件事的，$g先生:女士;!', `MaleText_loc7`='¿En... en serio? ¡No lo olvidaré, $gseñor:señora;!' WHERE `ID`=58801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다!', `MaleText_loc4`='我们自由了！', `MaleText_loc5`='我們自由了!', `MaleText_loc7`='¡Somos libres!', `FemaleText_loc1`='자유다!', `FemaleText_loc4`='我们自由了！', `FemaleText_loc5`='我們自由了!', `FemaleText_loc7`='¡Somos libres!' WHERE `ID`=58802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 먼저 가 있게. 내가 우레를 데리고 태양노래 농장으로 바로 가겠네.', `MaleText_loc4`='你先走。等我把雷霆准备好，就马上去日歌农场跟你会合。', `MaleText_loc5`='你先走吧。只等我把轟雷準備好，我會馬上到日歌農莊和你會合。', `MaleText_loc7`='Adelántate tú. Yo tengo que preparar a Trueno, pero nos reuniremos en el Rancho Cantosol en un periquete.' WHERE `ID`=58803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐이면 된다네.', `MaleText_loc4`='只需要再等一小会儿。', `MaleText_loc5`='只需要再一下子就會好。', `MaleText_loc7`='Solo un momentito más.' WHERE `ID`=58804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 더 센지 한번 해보자고. 내 우레인지 아니면 저 바위인지! 나는 우레에 걸겠네.', `MaleText_loc4`='让我们看看谁更强大——是我的雷霆还是那块石头！我把钱押给雷霆。', `MaleText_loc5`='讓我們看看誰比較強壯，是我的轟雷還是那個岩石!我賭轟雷。', `MaleText_loc7`='A ver quién es más fuerte... ¡mi Trueno o esa roca! Yo apuesto por Trueno.' WHERE `ID`=58805;
