UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하신가요, 우리 식구 $n 님! 뭐 사고팔려고 오신 건가요? 마음껏 둘러보세요.', `FemaleText_loc4`='你好，邻居！你是来购物的，还是来卖货的？请随便瞧瞧吧。', `FemaleText_loc5`='你好啊，鄰居!你來這是要買還是要賣?隨便看看啊。', `FemaleText_loc7`='¡Qué hay, $gvecino:vecina;! ¿Has venido a comprar o a vender? No te cortes en echar un vistazo por ahí.' WHERE `ID`=58844;
