UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구신지 모르겠네요. 마을에 새로 오신 분이 틀림없군요.', `FemaleText_loc4`='我认不出你这张脸，你一定是新来的。', `FemaleText_loc5`='我認不出你的面孔。你一定是鎮上新來的。', `FemaleText_loc7`='No me suena tu cara. Debes de ser $gnuevo:nueva; en la ciudad.' WHERE `ID`=58846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을에 있는 이웃들을 대부분 제가 다 알아요. 이웃들에게 마을에 누가 새로 왔다고 알려야겠군요.', `FemaleText_loc4`='这地方的人我都认识，我会告诉他们镇上来了个新面孔。', `FemaleText_loc5`='我幾乎認識這地區每個人。我會讓大家知道鎮上來了個新面孔。', `FemaleText_loc7`='Conozco prácticamente a todo el mundo por estos lares. Les diré que hay una cara nueva en la ciudad.' WHERE `ID`=58847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 여기 주민이 아니시군요. 도시에서 오셨나요? 저기, 제 치마 어때요?', `FemaleText_loc4`='哦，你肯定不是这附近的人。你是从城里来的吗？你觉得我的裙子怎么样？', `FemaleText_loc5`='喔，你不是這裡的人。你是個城市佬嗎?告訴我，你覺得我的禮服如何?', `FemaleText_loc7`='Oh, no eres de por aquí. ¿Eres un zarpa urbanita? Dime, ¿qué te parece mi vestido?' WHERE `ID`=58848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 우리 예전에 만난 적 있죠? 그렇죠?', `FemaleText_loc4`='你好。我们以前见过，对吗？', `FemaleText_loc5`='你好。我們以前見過面，對吧?', `FemaleText_loc7`='Hola. Nos hemos visto antes, ¿verdad?' WHERE `ID`=58849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 그전에는 몰랐는데, 옷이 아주 멋진 걸요?', `FemaleText_loc4`='哦，你这套衣服真漂亮。我之前居然没注意到。', `FemaleText_loc5`='喔，你的服裝真棒。我以前都沒注意到。', `FemaleText_loc7`='Oh, qué conjunto tan bonito. No me había dado cuenta antes.' WHERE `ID`=58850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 주민들이 당신 이야기를 하고 있어요. 걱정하지 마세요, 제가 가끔 좋은 말을 해줄 테니까요.', `FemaleText_loc4`='这里的人们都在谈论你。别担心，我会时不时地帮你说些好话的。', `FemaleText_loc5`='這附近的人都在談論你。別擔心，我不時會幫你說說好話。', `FemaleText_loc7`='La gente de por aquí ha estado hablando sobre ti. No te preocupes, he dicho buenas cosas de ti de vez en cuando.' WHERE `ID`=58851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저한테 이 색깔 옷이 어울리는 것 같나요?', `FemaleText_loc4`='你觉得这颜色衬我吗？', `FemaleText_loc5`='你喜歡我穿這顏色嗎?', `FemaleText_loc7`='¿Te gusta cómo me queda este color?' WHERE `ID`=58852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 다시 만나서 반가워요.', `FemaleText_loc4`='嗨，哥们！真高兴又见到你。', `FemaleText_loc5`='嗨，兄弟!再次見到你真好。', `FemaleText_loc7`='¡Hola, colega! Me alegro de volver a verte.' WHERE `ID`=58853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 그 신발이 눈이랑 아주 잘 어울리네요.', `FemaleText_loc4`='这些鞋子配上你的眼睛真是太漂亮了。', `FemaleText_loc5`='那雙鞋子和你的眼睛很搭。', `FemaleText_loc7`='Esos zapatos combinan estupendamente con tus ojos.' WHERE `ID`=58854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 여기 주민들이 당신 이야기를 하고 있어요. 걱정하지 마세요, 제가 가끔 좋은 말을 해줄 테니까요.', `FemaleText_loc4`='这里的人们都在谈论你，哥们。别担心，我会时不时地帮你说些好话的。', `FemaleText_loc5`='這附近的人都在談論你，兄弟。別擔心，我不時會幫你說說好話。', `FemaleText_loc7`='La gente de por aquí ha estado hablando sobre ti, colega. No te preocupes, he dicho buenas cosas de ti de vez en cuando.' WHERE `ID`=58855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 말해봐요, 제 귀걸이 어때요?', `FemaleText_loc4`='嗨，哥们！你觉得……我的耳环怎么样？', `FemaleText_loc5`='嗨，兄弟!請你告訴我...你喜歡我的耳環嗎?', `FemaleText_loc7`='¡Hola, colega! Dime... ¿te gustan mis pendientes?' WHERE `ID`=58856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 내 친구 $n 님. 농장 일은 다 잘돼 가죠?', `FemaleText_loc4`='你好，朋友。你的农场还顺利吗？', `FemaleText_loc5`='哈囉，朋友。你的農場進展得都還順利嗎?', `FemaleText_loc7`='Hola, $gamigo:amiga;. ¿Te las estás arreglando bien en tu granja?' WHERE `ID`=58857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 우리는 친구예요. 그래서 그런데, 당신 옷은 정말... 끔찍하다고밖에 말할 수 없어요.', `FemaleText_loc4`='既然大家是朋友了，我不得不说你的衣服实在是……太丑了。', `FemaleText_loc5`='如今我們是朋友，我必須告訴你，你的服裝真的是...醜死了。', `FemaleText_loc7`='Ahora que somos $gamigos:amigas;, debo decirte que tu conjunto es... espantoso.' WHERE `ID`=58858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 여기 주민들이 당신 이야기를 하고 있어요! 당신을 정말 좋게 생각하는 것 같아요.', `FemaleText_loc4`='这里的人们都在谈论你，朋友！他们看起来都很喜欢你哦。', `FemaleText_loc5`='這附近的人都在談論你，朋友!他們似乎對你有許多遐想。', `FemaleText_loc7`='¡La gente de por aquí ha estado hablando sobre ti, $gamigo:amiga;! Parece que les has caído bastante bien.' WHERE `ID`=58859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제발, 당신이 친구라서 이렇게 부탁드리는 건데... 제 옷이 진짜 어떤지 좀 말해주세요. ...너무 안 예쁜가요?', `FemaleText_loc4`='拜托，作为朋友……实话告诉我，我的衣服怎么样？真有那么……糟吗？', `FemaleText_loc5`='拜託，當作幫朋友個忙...對我說實話。我的服裝...很爛嗎?', `FemaleText_loc7`='Te lo pido como amiga... dime la verdad sobre mi conjunto. ¿Te parece... horrible?' WHERE `ID`=58860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 우리는 친구가 됐으니까, 고백할 게 있어요. 제가... 제가 농부 펑을 조금 많이 좋아하는 것 같아요.', `FemaleText_loc4`='既然大家是朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。', `FemaleText_loc5`='如今我們是朋友，我必須要自白。我...我想我相當喜歡農夫老豐。', `FemaleText_loc7`='Ahora que somos $gamigos:amigas;, tengo que confesarte una cosa. Creo... creo que me gusta bastante el granjero Fung.' WHERE `ID`=58861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 농부 펑은 정말... 멋지다고 생각 안 하세요?', `FemaleText_loc4`='你不觉得农夫老方很……迷人吗？', `FemaleText_loc5`='你不覺得農夫老豐很...吸引人嗎?', `FemaleText_loc7`='¿No te parece que el granjero Fung es... de ensueño?' WHERE `ID`=58862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님! 하시는 일 다 잘되고, 농장에 있는 윤도 일이 잘 풀렸으면 좋겠어요.', `FemaleText_loc4`='$n，我的好朋友！我希望你和老愚在农场一切顺利。', `FemaleText_loc5`='$n，我的好朋友!我希望你和尹先生在農場一切順利。', `FemaleText_loc7`='¡$n, mi $gbuen amigo:buena amiga;! Espero que todo os vaya bien a ti y al Sr. Yoon en la granja.' WHERE `ID`=58863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 우린 좋은 친구가 된 거예요. 그래서 그러는 건데, 당신 복장이 참... 형편없다고 말할 수밖에 없네요.', `FemaleText_loc4`='既然大家是好朋友了，我不得不说你的衣服实在是……太糟了。', `FemaleText_loc5`='如今我們是好朋友，我必須告訴你，你的服裝真的是...糟透了。', `FemaleText_loc7`='Ahora que somos $gbuenos amigos:buenas amigas;, debo decirte que tu conjunto es... horrible.' WHERE `ID`=58864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님! 이 동네 이웃들이 당신 이야기를 하고 있었어요. 소문이 꽤 자자하더라고요.', `FemaleText_loc4`='这里的人们都在谈论你，$n！你打破了这里的平静。', `FemaleText_loc5`='這附近的人都在談論你，$n!你可是在這裡引起大騷動了。', `FemaleText_loc7`='¡La gente de por aquí ha estado hablando sobre ti, $n! Estás levantando mucha expectación.' WHERE `ID`=58865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 친구니까 제가 이렇게 부탁 드리는 건데... 제 옷이 어떤지 말해주세요. 좀... 끔찍한가요?', `FemaleText_loc4`='拜托，作为好朋友……实话告诉我，我的衣服怎么样？真有那么……难看吗？', `FemaleText_loc5`='拜託，當作幫好朋友個忙...對我說實話。我的服裝...很醜嗎?', `FemaleText_loc7`='Te lo pido como amiga... dime la verdad sobre mi conjunto. ¿Te parece... horrible?' WHERE `ID`=58866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 우리는 좋은 친구가 됐으니까, 고백할 게 있어요. 제가... 제가 농부 펑을 좋아하는 것 같아요. 하긴 펑은 눈이 아주 멋지게 생겼잖아요. 그렇죠?', `FemaleText_loc4`='既然大家是好朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？', `FemaleText_loc5`='如今我們是最好的朋友，我必須要自白。我...我想我相當喜歡農夫老豐。可是農夫尹的雙眼很迷人，你不覺得嗎?', `FemaleText_loc7`='Ahora que somos $gbuenos amigos:buenas amigas;, tengo que confesarte una cosa. Creo... creo que me gusta bastante el granjero Fung. Por otra parte, el granjero Yoon tiene ojos bonitos, ¿no te parece?' WHERE `ID`=58867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 하시는 일 다 잘되고, 농장에 있는 윤도 일이 잘 풀렸으면 좋겠어요.', `FemaleText_loc4`='你好，邻居！我希望你和老愚在农场一切顺利。', `FemaleText_loc5`='你好啊，鄰居!我希望你和尹先生在農場一切順利。', `FemaleText_loc7`='¡Qué hay, $gvecino:vecina;! Espero que todo os vaya bien a ti y al Sr. Yoon en la granja.' WHERE `ID`=58868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 우린 가장 친한 친구가 돼서 그런데... 당신 옷... 정말 갖고 싶어 죽겠어요!', `FemaleText_loc4`='既然我们是死党了，我不得不说你的衣服实在是……难看死了！', `FemaleText_loc5`='如今我們是最好的朋友，我必須告訴你，你的服裝真的是...棒極了!', `FemaleText_loc7`='Ahora que somos mejores $gamigos:amigas;, tengo que decirte que tu conjunto es... ¡para morirse!' WHERE `ID`=58869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님, 이 동네 이웃들이 당신 이야기를 하고 있었어요! 모두에게 제 이웃이라고 말하고 다녔답니다.', `FemaleText_loc4`='这里的人们都在谈论你，$n！我跟所有人都说你是我的邻居。', `FemaleText_loc5`='這附近的人都在談論你，$n!我一直跟每個人說你是我的鄰居。', `FemaleText_loc7`='¡La gente de por aquí ha estado hablando sobre ti, $n! Les he dicho a todos que eres mi $gvecino:vecina;.' WHERE `ID`=58870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가장 친한 친구니까 제가 이렇게 부탁 드리는 건데... 제 옷이 어떤지 말해주세요. 어떤가요?$B$B아? 예쁘다고 하신 거죠? 정말 고마워요! 그래서 당신이 제 평생 친구인 거예요!', `FemaleText_loc4`='拜托，作为挚友……实话告诉我，我的衣服怎么样？好吗？$B$B哦？你觉得很好？哎呀，谢谢你！这就是为什么你是我一辈子的朋友！', `FemaleText_loc5`='拜託，當作幫最好朋友一個忙...實話告訴我，我的服裝怎麼樣。看起來如何?$B$B喔?你覺得很棒?真是謝謝你!這就是為什麼你是我一生的朋友!', `FemaleText_loc7`='A modo de favor para tu mejor amiga... dime la verdad sobre mi conjunto. ¿Cómo es?$B$B¿Eh? ¿Precioso, dices? ¡Vaya, gracias! ¡Por eso serás mi $gamigo:amiga; de por vida!' WHERE `ID`=58871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이젠 우리는 가장 친한 친구가 됐으니까, 고백할 게 있어요. 제가... 제가 농부 펑을 좋아하는 것 같아요. 하긴 펑은 눈이 아주 멋지게 생겼잖아요. 그렇죠?$B$B아, 어떻게 해야 할지 모르겠어요!', `FemaleText_loc4`='既然我们是挚友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？$B$B哦，我左右为难啊！', `FemaleText_loc5`='如今我們是最好的朋友，我必須要自白。我...我想我相當喜歡農夫老豐。可是農夫尹的雙眼很迷人，你不覺得嗎?$B$B喔，我沒辦法做決定!', `FemaleText_loc7`='Ahora que somos mejores $gamigos:amigas;, tengo que confesarte una cosa. Creo... creo que me gusta bastante el granjero Fung. Por otra parte, el granjero Yoon tiene ojos bonitos, ¿no te parece?$B$B¡Uff, es que no me decido!' WHERE `ID`=58872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다!', `MaleText_loc4`='谢谢你！', `MaleText_loc5`='謝謝你!', `MaleText_loc7`='¡Gracias!', `FemaleText_loc1`='감사해요!', `FemaleText_loc4`='谢谢你！', `FemaleText_loc5`='謝謝你!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=58873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 여길 뜨자.', `MaleText_loc4`='赶快，我们离开这儿。', `MaleText_loc5`='快，我們快離開這兒。', `MaleText_loc7`='Rápido, salgamos de aquí.', `FemaleText_loc1`='빨리 여길 뜨자.', `FemaleText_loc4`='赶快，我们离开这儿。', `FemaleText_loc5`='快，我們快離開這兒。', `FemaleText_loc7`='Rápido, salgamos de aquí.' WHERE `ID`=58874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골에게 죽음을!', `MaleText_loc4`='野牛人去死吧！', `MaleText_loc5`='揚古都去死!', `MaleText_loc7`='¡Muerte a los yaungol!', `FemaleText_loc1`='야운골에게 죽음을!', `FemaleText_loc4`='野牛人去死吧！', `FemaleText_loc5`='揚古都去死!', `FemaleText_loc7`='¡Muerte a los yaungol!' WHERE `ID`=58875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 영웅이시다!', `MaleText_loc4`='我们的大英雄！', `MaleText_loc5`='我們的英雄!', `MaleText_loc7`='¡Gracias, valiente!', `FemaleText_loc1`='우리 영웅이시다!', `FemaleText_loc4`='我们的大英雄！', `FemaleText_loc5`='我們的英雄!', `FemaleText_loc7`='¡Gracias, valiente!' WHERE `ID`=58876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살았다!', `MaleText_loc4`='我们得救了！', `MaleText_loc5`='我們得救了!', `MaleText_loc7`='¡Estamos salvados!', `FemaleText_loc1`='살았다!', `FemaleText_loc4`='我们得救了！', `FemaleText_loc5`='我們得救了!', `FemaleText_loc7`='¡Estamos salvados!' WHERE `ID`=58877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈안 마을로 가자.', `MaleText_loc4`='我们去滨岸村吧。', `MaleText_loc5`='我們到濱南村去吧。', `MaleText_loc7`='Vamos a la Aldea Binan.', `FemaleText_loc1`='빈안 마을로 가자.', `FemaleText_loc4`='我们去滨岸村吧。', `FemaleText_loc5`='我們到濱南村去吧。', `FemaleText_loc7`='Vamos a la Aldea Binan.' WHERE `ID`=58878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼴 좋다.', `MaleText_loc4`='解脱了。', `MaleText_loc5`='死好。', `MaleText_loc7`='Buen viaje.', `FemaleText_loc1`='꼴 좋다.', `FemaleText_loc4`='解脱了。', `FemaleText_loc5`='死好。', `FemaleText_loc7`='Buen viaje.' WHERE `ID`=58879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아. 이게 누구십니까. 마을에 새 친구가 왔군요.', `MaleText_loc4`='嘿，看啊，是镇上新来的$G小伙子:小姑娘;。', `MaleText_loc5`='嘿，大家看，是村裡的新來的$G兄弟:姊妹;。', `MaleText_loc7`='Anda, mira, es $Gel:la; $Gnuevo:nueva; $Gchico:chica; de la ciudad.' WHERE `ID`=58880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크에 대해 아는 거라도 좀 있으십니까? 뭐 제가 좀 많이 알고 있긴 합니다만.', `MaleText_loc4`='你对牦牛有研究吗，菜鸟？我可熟悉得很。', `MaleText_loc5`='你懂得犛牛嗎，菜鳥?我懂得可多了。', `MaleText_loc7`='¿Sabes algo sobre yaks, $gnovato:novata;? Pues yo sé mucho sobre ellos.' WHERE `ID`=58881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 네 바람의 계곡에서 가장 큰 채소를 가졌는지 아십니까? 바로 당신 눈앞에 있는 접니다!', `MaleText_loc4`='你知道谷里谁家的蔬菜长得最大吗？远在天边，近在眼前！', `MaleText_loc5`='你知道擁有這峽谷中最大蔬菜的人是誰嗎?你正看著他本人!', `MaleText_loc7`='¿Sabes quién tiene las verduras más grandes del Valle? ¡Lo tienes delante de ti!' WHERE `ID`=58882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 무슨 일이십니까, $n 님?', `MaleText_loc4`='嘿，哥们，发生什么事了？', `MaleText_loc5`='嘿，兄弟，最近好嗎?', `MaleText_loc7`='Eh, colega, ¿qué está pasando?' WHERE `ID`=58883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 제 야크 칭찬이라면 언제든지 와서 해주셔도 됩니다.', `MaleText_loc4`='嘿，哥们，随时欢迎你来欣赏我的牦牛。', `MaleText_loc5`='嘿，兄弟，歡迎你隨時來這欣賞我的犛牛。', `MaleText_loc7`='Oye, colega, no te dé corte admirar mis yaks cuando quieras.' WHERE `ID`=58884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 동료로서 비밀을 한 가지 알려드리겠습니다. 큰 채소를 수확하고 싶으십니까? 그렇다면 비료를 써야 합니다.$B$B네 바람의 계곡에서 누가 가장 훌륭한 비료를 갖고 있는지 아십니까? 바로 접니다!', `MaleText_loc4`='嘿，$r，看在哥们的情分上，我要跟你说个秘密。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！', `MaleText_loc5`='嘿，$r，跟你說個兄弟間的小秘密。你想要巨大蔬菜嗎?你得用肥料。$B$B而你知道誰有這峽谷中最棒的肥料嗎?就是我!', `MaleText_loc7`='Oye, $r, de colega a colega, te voy a contar un secreto. ¿Quieres verduras grandes? Tienes que utilizar un fertilizante.$B$B¿Y sabes quién tiene el mejor fertilizante del Valle? ¡Yo!' WHERE `ID`=58885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내 친구 $n 님, 무슨 일이 일어난 겁니까?', `MaleText_loc4`='嘿，朋友，怎么了？', `MaleText_loc5`='嘿，朋友，你好嗎?', `MaleText_loc7`='Oye, $gamigo:amiga;, ¿qué está pasando?' WHERE `ID`=58886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 $n 님, 제 야크 칭찬이라면 언제든지 와서 해주셔도 됩니다.', `MaleText_loc4`='嘿，朋友，随时欢迎你来欣赏我的牦牛。', `MaleText_loc5`='嘿，朋友，歡迎你隨時來這欣賞我的犛牛。', `MaleText_loc7`='Oye, $gamigo:amiga;, no te dé corte admirar mis yaks cuando quieras.' WHERE `ID`=58887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구니까 제가 한 가지 알려드리겠습니다. 큰 채소를 수확하고 싶으십니까? 그렇다면 비료를 써야 합니다.$B$B네 바람의 계곡에서 누가 가장 훌륭한 비료를 갖고 있는지 아십니까? 바로 접니다!', `MaleText_loc4`='嘿，朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！', `MaleText_loc5`='嘿，朋友，告訴你個情報。你想要巨大蔬菜嗎?你得用肥料。$B$B而你知道誰有這峽谷中最棒的肥料嗎?就是我!', `MaleText_loc7`='Oye, $gamigo:amiga;, te daré un consejo. ¿Quieres verduras grandes? Tienes que utilizar un fertilizante.$B$B¿Y sabes quién tiene el mejor fertilizante del Valle? ¡Yo!' WHERE `ID`=58888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n 님! 농장 일은 어떻습니까?', `MaleText_loc4`='我的好朋友！农场的情况怎么样？', `MaleText_loc5`='我的好朋友!農場的一切都還好嗎?', `MaleText_loc7`='¡Mi $gbuen amigo:buena amiga;! ¿Cómo van las cosas en la granja?' WHERE `ID`=58889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n 님, 오늘은 좀 어떠십니까?$B$B제 이야기 잘 들어보십시오. 이런 말 아무에게나 안 하는 건데, 야크가 필요하시면 이 펑에게 말씀해주십시오.', `MaleText_loc4`='我的好朋友，你今天过得好吗？$B$B听着，一般人我不告诉他——可如果你需要牦牛，就跟老方说一声。', `MaleText_loc5`='我的好朋友，你今天好嗎?$B$B聽著，我不會對任何人都這麼說，但假如有天你需要一匹犛牛，你來找我老豐。', `MaleText_loc7`='Mi $gbuen amigo:buena amiga;, ¿cómo estás hoy?$B$BMira, no le digo esto a todo el mundo, pero si alguna vez necesitas un yak, díselo a Fung.' WHERE `ID`=58890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 친구니까 제가 조언을 하나 해 드리겠습니다. 큰 채소를 수확하고 싶으십니까?$B$B그렇다면 잘 돌봐줘야 합니다. 물도 주고, 비료도 주고, 애정도 담아줘야 합니다.', `MaleText_loc4`='我的好朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？$B$B你得细心照料它们。浇水、施肥，还要献出你的爱。', `MaleText_loc5`='我的好朋友，告訴你個情報。你想要種出巨大蔬菜嗎?$B$B你得照顧它們。給它們一些水，一些肥料，還有一些愛。', `MaleText_loc7`='Mi $gbuen amigo:buena amiga;, te daré un consejo. ¿Quieres verduras grandes?$B$BTienes que cuidarlas bien. Regarlas de cuando en cuando, echarles un poco de fertilizante y darles un poquito de amor.' WHERE `ID`=58891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 우리 식구 $n 님! 농장 일은 잘돼가십니까?', `MaleText_loc4`='嘿，邻居！农场一切都好？', `MaleText_loc5`='嘿，鄰居!農場裡的事還順利吧?', `MaleText_loc7`='¡Hola, $gvecino:vecina;! ¿Va todo bien en la granja?' WHERE `ID`=58892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 우리 식구 $n 님. 오늘은 좀 어떠십니까?$B$B털북숭이는 잘 지내고 있습니까?', `MaleText_loc4`='你好啊邻居，今天过得怎么样？$B$B毛毛好吗？', `MaleText_loc5`='嘿，鄰居!你今天好嗎?$B$B沙奇過得怎樣啊?', `MaleText_loc7`='Hola, $gvecino:vecina;, ¿cómo estás hoy?$B$B¿Cómo está Peludo?' WHERE `ID`=58893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 우리 식구 $n 님! 저 채소가 아주 좋아 보이는군요.', `MaleText_loc4`='嘿，邻居！那些蔬菜看起来真不错。', `MaleText_loc5`='嘿，鄰居!那些蔬菜看起來很棒。', `MaleText_loc7`='¡Hola, $gvecino:vecina;! Esas verduras tienen muy buena pinta.' WHERE `ID`=58894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저기요! 당신 예전에 본 적이 있던가요?', `FemaleText_loc4`='嘿，你好！我以前见过你？', `FemaleText_loc5`='嘿，你好!我們是不是以前見過面?', `FemaleText_loc7`='¡Hola! ¿Yo a ti te he visto antes?' WHERE `ID`=58895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저기요! 이곳에선 전에 본 적이 없는 얼굴 같네요.', `FemaleText_loc4`='嘿，你好！以前没在这附近见过你啊。', `FemaleText_loc5`='你好!在附近沒見過像你這樣的面孔。', `FemaleText_loc7`='¡Hola! Nunca había visto tu cara por aquí.' WHERE `ID`=58896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 뭐 좋은 이야기라도 해주실 것 없나요? 전 이야기 하는 거 엄청 좋아해요!', `FemaleText_loc4`='嘿，城里人！你有没有什么有趣的故事跟我分享啊？我超爱讲故事！', `FemaleText_loc5`='你好，城市佬!你有聽到什麼好故事可以分享嗎?我愛說故事!', `FemaleText_loc7`='¡Hola, zarpa urbanita! ¿Has oído buenas historias que puedas compartir? ¡Me encanta contar historias!' WHERE `ID`=58897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기, 늙은 엉겅퀴 노인이라는 이야기 들어보셨어요? 제가 들어본 이야기 중 가장 좋은 이야기랍니다.', `FemaleText_loc4`='嘿，你有没有听过关于老农阿蓟的故事？那是我所听过的最好的故事了。', `FemaleText_loc5`='嘿，你有聽過「寂老頭」的故事嗎?那可是我聽過的一個好故事。', `FemaleText_loc7`='Oye, ¿has escuchado la historia de Cardo el Viejo? Es una buena historia que me contaron.' WHERE `ID`=58898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기... 왜 이름이 $n인 건가요? 좀 이상한 이름 아니에요?', `FemaleText_loc4`='嘿，你的名字为什么叫$n？这名字不怪吗？', `FemaleText_loc5`='嘿，為什麼你要叫$n?那名字不是很奇怪的嗎?', `FemaleText_loc7`='Oye, ¿por qué te llamas $n? ¿No te parece un nombre extraño?' WHERE `ID`=58899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 주변에 있는 이웃들은 정말 좋답니다... 좋은 점을 찾아낼 수 있을 때까지 붙어 지낸다면 말이죠.', `FemaleText_loc4`='这里的人们心地善良……在这儿待久了你就会发现。', `FemaleText_loc5`='這附近的人們都非常友善...只要你待得夠久就會發現。', `FemaleText_loc7`='La gente de por aquí es muy buena... si te quedas el tiempo suficiente para comprobarlo.' WHERE `ID`=58900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠가 물고기는 헤엄치고 새는 난다고 하셨어요. 만약 제가 날 수 있고 헤엄칠 수 있으면 저는 대체 뭐예요?', `FemaleText_loc4`='我老爸常说鱼儿会游、鸟儿会飞。假如我既会游又会飞，那我成啥了？', `FemaleText_loc5`='我老爸總是告訴我魚會游泳、鳥會飛。假設我現在會游泳也會飛了，那我到底是什麼?', `FemaleText_loc7`='Mi papá siempre me dijo que los peces nadaban y los pájaros volaban. Entonces, si yo sé nadar y volar, ¿qué soy yo?' WHERE `ID`=58901;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야, $n 님! 다시 만나서 반가워요!', `FemaleText_loc4`='嘿，哥们！很高兴再次见到你。', `FemaleText_loc5`='嘿，兄弟!再次見到你真好。', `FemaleText_loc7`='¡Hola, colega! Cuantísimo me alegro de volver a verte.' WHERE `ID`=58902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 아서스의 어릴 적 이야기 정말 좋았어요. 또 들려주실 이야기 없나요?', `FemaleText_loc4`='嘿，哥们！我很喜欢那个关于小男孩阿尔萨斯的故事。你还有其他故事分享吗？', `FemaleText_loc5`='你好，兄弟!我喜歡那個男孩阿薩斯的故事。你有其它可以分享的嗎?', `FemaleText_loc7`='¡Qué pasa, colega! Me encantó esa historia sobre el chico ese, Arthas. ¿Te sabes más?' WHERE `ID`=58903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 스랄이라는 오크 이야기 정말 좋았어요. 또 들려주실 이야기 없나요?', `FemaleText_loc4`='嘿，哥们！我很喜欢那个关于兽人萨尔的故事。你还有其他故事分享吗？', `FemaleText_loc5`='你好，兄弟!我喜歡那個獸人索爾的故事。你有其它可以分享的嗎?', `FemaleText_loc7`='¡Qué pasa, colega! Me encantó esa historia sobre el orco ese, Thrall. ¿Te sabes más?' WHERE `ID`=58904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늙은 엉겅퀴 노인은 저기 언덕 위에 아주 작은 밭을 갖고 있었어요.$B$B그는 어느 날 계속해서 땅을 파 내려가기 시작했어요. 땅을 또 파고, 파고, 파 내려가다 보니 더는 팔 땅이 없었지만, 그 언덕 아래에 있는 동굴을 발견한 거예요!$B$B그다음 엉겅퀴 노인이 동굴에서 뭘 찾아냈을 것 같아요?', `FemaleText_loc4`='老农阿蓟在那山上有一小块地皮。$B$B有一天他在那挖呀挖呀，也不知道自己挖了多深，突然发现在山底下居然有一个洞穴！$B$B你猜他在洞穴里发现了什么？', `FemaleText_loc5`='寂老頭就在那邊的山丘上擁有一小塊土地。$B$B有一天他挖土挖了又挖，挖了又挖，挖得深啊深到他發現在山丘下面有一個大洞窟!$B$B你猜猜他在那洞窟裡發現了什麼?', `FemaleText_loc7`='Cardo el Viejo tenía un terreno allí en aquella colina.$B$BUn día se puso a cavar y cavar; ¡cavó tanto que hasta encontró toda una cueva debajo de esas montañas!$B$B¿Y qué crees que encontró en esa cueva?' WHERE `ID`=58905;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 피시도 이상한 이름이라니 그게 무슨 뜻이죠? 전혀 이상하지 않다고요! 호수에 있는 물고기를 본따서 만든 이름인데!$B$B그러면 "$n"은 안 이상해요? 지금 제가 묻잖아요!', `FemaleText_loc4`='你是说“玉儿”也是个怪名字？它一点儿也不怪，哥们！我的名字取自于湖里的那些鱼！$B$B现在说说你的名字“$n”是啥意思，啊？你倒是说啊！', `FemaleText_loc5`='你說小魚也是個怪名字是什麼意思?根本一點都不奇怪，老兄!我是以湖中的那些魚命名的!$B$B而「$n」是個什麼東西，嗯?你說啊?', `FemaleText_loc7`='¿Qué quieres decir con que Pez también es un nombre raro? ¡No es nada raro, colega! ¡Me llamaron así por los peces del lago!$B$B¿Y acaso sabes qué es $gun:una; "$n", eh? ¡Qué me respondes a eso!' WHERE `ID`=58906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠는 항상 적 대신 친구를 만들라고 하셨어요. 그래서 $n 님이랑 저랑 친한 거예요!', `FemaleText_loc4`='老爸常告诫我要多交朋友少结仇，那就是为什么你会是我哥们！', `FemaleText_loc5`='我老爸總是告訴我多一個敵人不如多一個朋友。那就是為什麼你是我兄弟!', `FemaleText_loc7`='Mi papá siempre me dijo que hiciera amigos en vez de enemigos. ¡Por eso eres mi coleguita!' WHERE `ID`=58907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 내 친구 $n 님! 다시 만나서 아주 반가워요.', `FemaleText_loc4`='嘿，朋友！很高兴再次见到你。', `FemaleText_loc5`='嘿，兄弟!再次見到你真好。', `FemaleText_loc7`='¡Hola, $gamigo:amiga;! Me alegro mucho de volver a verte.' WHERE `ID`=58908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 내 친구 $n 님! 세계수와 그리고... 뭐라고 하는 거더라... 아, 세계의 분리 이야기 다시 한 번 해주세요!', `FemaleText_loc4`='嘿，朋友！再给我讲讲世界之树的故事和那个……啥来着……世界的分裂！', `FemaleText_loc5`='你好，朋友!再跟我說一次那個關於世界樹還有...你叫它什麼啊...大裂變的故事!', `FemaleText_loc7`='¡Qué hay, $gamigo:amiga;! ¡Cuéntame otra vez esa historia del árbol del mundo y el... cómo era... el cataclismo!' WHERE `ID`=58909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 찾은 건...', `MaleText_loc4`='你找到了……', `MaleText_loc5`='你找到...', `MaleText_loc7`='Has encontrado...', `FemaleText_loc1`='당신이 찾은 건...', `FemaleText_loc4`='你找到了……', `FemaleText_loc5`='你找到...', `FemaleText_loc7`='Has encontrado...' WHERE `ID`=58910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늙은 엉겅퀴 노인이 발견한 건 보물로 가득 찬 동굴이었답니다!!!$B$B거기엔 금도 있고, 옥도 있고, 동상도 있고, 그리고 책으로 가득 찬 방도 있었답니다!$B$B노인은 그 동굴을 돌아다니다 보니 하루가 꼴딱 가버려서 배가 무진장 고파지기 시작했답니다.$B$B그래서 다시 처음으로 땅을 파냈던 길로 해서 원래 있던 곳으로 돌아가려고 하는데, 다시 돌아갈 길을 못 찾겠지 뭐예요!', `FemaleText_loc4`='老农阿蓟发现了一个堆满金银财宝的洞穴！！！$B$B那里有黄金、钻石、翡翠、雕像，还有一整屋的古籍！$B$B他在洞穴里徘徊许久。很快，一整天就过去了，他感到非常饥饿。$B$B于是他就沿着来时的路往回走，却找不到回去的路了！', `FemaleText_loc5`='寂老頭發現了一個裝滿寶藏的洞窟!!!!$B$B那裡有黃金有鑽石有玉有雕像還有整個房間的書!$B$B不知不覺他就在那洞窟晃了一整天，然後他感到非常餓了。$B$B所以他就沿著進來的路回去。但不知怎麼回事他卻找不到路回去!', `FemaleText_loc7`='¡¡¡¡Cardo el viejo encontró una cueva llena de tesoros!!!!$B$B¡Había oro y diamantes y jade y estatuas... y una sala llena de libros!$B$BEn fin, estuvo vagando por esa cueva y al cabo del día le entró muchísima hambre.$B$BEntonces intentó volver al sitio por donde entró... ¡y lo que pasa es que no encontraba la salida!' WHERE `ID`=58911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당황한 암탉입니다! 닭장으로 되돌려보내십시오!', `MaleText_loc4`='一只丢失的母鸡！把她带回鸡笼。', `MaleText_loc5`='一隻迷路的雞!把她帶回雞舍。', `MaleText_loc7`='¡Una gallina perdida! Devuélvela al gallinero.', `FemaleText_loc1`='당황한 암탉입니다! 닭장으로 되돌려보내십시오!', `FemaleText_loc4`='一只丢失的母鸡！把她带回鸡笼。', `FemaleText_loc5`='一隻迷路的雞!把她帶回雞舍。', `FemaleText_loc7`='¡Una gallina perdida! Devuélvela al gallinero.' WHERE `ID`=58912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구애하는 수탉입니다! 물에 담가 진정시키십시오.', `MaleText_loc4`='一只发情的公鸡！把他浸在水里，冷却下他的热情。', `MaleText_loc5`='一隻熱情的公雞!把牠泡在水裡讓牠的激情冷靜一下。', `MaleText_loc7`='¡Un gallo amoroso! Sumérgelo en el agua para enfriar sus pasiones.', `FemaleText_loc1`='구애하는 수탉입니다! 물에 담가 진정시키십시오.', `FemaleText_loc4`='一只发情的公鸡！把他浸在水里，冷却下他的热情。', `FemaleText_loc5`='一隻熱情的公雞!把牠泡在水裡讓牠的激情冷靜一下。', `FemaleText_loc7`='¡Un gallo amoroso! Sumérgelo en el agua para enfriar sus pasiones.' WHERE `ID`=58913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 초원닭입니다! 이곳에서 쫓아내십시오!', `MaleText_loc4`='一只野生农场小鸡！把它踢走！', `MaleText_loc5`='一隻野生山雞!把他踢出去!', `MaleText_loc7`='¡Un pollo de la pradera salvaje! ¡Échalo de aquí!', `FemaleText_loc1`='야생 초원닭입니다! 이곳에서 쫓아내십시오!', `FemaleText_loc4`='一只野生农场小鸡！把它踢走！', `FemaleText_loc5`='一隻野生山雞!把他踢出去!', `FemaleText_loc7`='¡Un pollo de la pradera salvaje! ¡Échalo de aquí!' WHERE `ID`=58914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭털로 변장한 마모트입니다! 속임수를 쓴 마모트임을 밝혀내십시오!', `MaleText_loc4`='一只披着鸡毛的土拨鼠！让它现出原形！', `MaleText_loc5`='一隻用雞羽毛偽裝的土撥鼠!揭穿這個假貨!', `MaleText_loc7`='¡Una marmota disfrazada con plumas de gallina! ¡Descubre su farsa y revela su verdadera identidad!', `FemaleText_loc1`='닭털로 변장한 마모트입니다! 속임수를 쓴 마모트임을 밝혀내십시오!', `FemaleText_loc4`='一只披着鸡毛的土拨鼠！让它现出原形！', `FemaleText_loc5`='一隻用雞羽毛偽裝的土撥鼠!揭穿這個假貨!', `FemaleText_loc7`='¡Una marmota disfrazada con plumas de gallina! ¡Descubre su farsa y revela su verdadera identidad!' WHERE `ID`=58915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 엄마 꼬꼬댁!', `MaleText_loc4`='老农山掌的获奖小鸡——咯咯妈妈！', `MaleText_loc5`='老丘爪的得獎名雞，咯雞媽媽!', `MaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Mamá Clueca!', `FemaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 엄마 꼬꼬댁!', `FemaleText_loc4`='老农山掌的获奖雏鸡——咯咯妈妈！', `FemaleText_loc5`='老丘爪的得獎名雞，咯雞媽媽!', `FemaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Mamá Clueca!' WHERE `ID`=58916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 우리는 친구가 된 거예요. 전 피시라고 불러주세요.$B$B하하! 난 너무 웃기다니까!$B$B그냥 장난친 거예요... 모두 저를 피시라고 불러요. 전부 제 친구들이거든요!', `FemaleText_loc4`='既然我们是朋友了，你可以叫我玉儿。$B$B哈哈！我真逗！$B$B我开玩笑的……每个人都叫我玉儿！因为每个人都是我的朋友！', `FemaleText_loc5`='如今我們是朋友，你可以叫我小魚。$B$B哈哈!我真是好笑!$B$B我只是在開玩笑...每個人都叫我小魚!因為每個人都是我的朋友!', `FemaleText_loc7`='Ahora que somos $gamigos:amigas; puedes llamarme Pez.$B$B¡Ja, ja! ¡Qué graciosa soy!$B$BEs broma... ¡todo el mundo me llama Pez! ¡Es que todo el mundo es amigo mío!' WHERE `ID`=58917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 밑둥반점 부인!', `MaleText_loc4`='老农山掌的获奖小鸡——斑臀女士！', `MaleText_loc5`='老丘爪的得獎名雞，點點夫人!', `MaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Sra. Moteada!', `FemaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 밑둥반점 부인!', `FemaleText_loc4`='老农山掌的获奖小鸡——斑臀女士！', `FemaleText_loc5`='老丘爪的得獎名雞，點點夫人!', `FemaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Sra. Moteada!' WHERE `ID`=58918;
