UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠는 항상 친구는 달콤한 순무보다 더 좋은 거라고 하셨어요. 그래서 $n $g아저씨:아줌마;가 제 친구인 거예요!', `FemaleText_loc4`='老爸常告诫我——甜菜味虽美，友情价更高。那就是为什么你会是我的朋友，$n！', `FemaleText_loc5`='我老爸總是告訴我朋友比甜菜頭更有價值。那就是為什麼你是我朋友，$n!', `FemaleText_loc7`='Mi papá siempre me decía que los amigos valen más que las nabas dulces. ¡Por eso eres mi $gamigo:amiga;, $n!' WHERE `ID`=58921;
