UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 비실날개!', `MaleText_loc4`='老农山掌的获奖小鸡——抖翅！', `MaleText_loc5`='老丘爪的得獎名雞，亂飛!', `MaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Tropezones!', `FemaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 비실날개!', `FemaleText_loc4`='老农山掌的获奖小鸡——抖翅！', `FemaleText_loc5`='老丘爪的得獎名雞，亂飛!', `FemaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Tropezones!' WHERE `ID`=58925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 벌레잡이 베티!', `MaleText_loc4`='老农山掌的获奖小鸡——雄赳赳的贝蒂！', `MaleText_loc5`='老丘爪的得獎名雞，跳跳貝蒂!', `MaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Clara Clocló!', `FemaleText_loc1`='늙은 힐포우의 가축 대회 입상 닭, 벌레잡이 베티!', `FemaleText_loc4`='老农山掌的获奖小鸡——雄赳赳的贝蒂！', `FemaleText_loc5`='老丘爪的得獎名雞，跳跳貝蒂!', `FemaleText_loc7`='¡La gallina premiada del viejo Zarpa Collado, Clara Clocló!' WHERE `ID`=58926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 우리 $n 님! 그 무시무시한 용인 데스윙 이야기 좀 다시 해주세요.', `FemaleText_loc4`='嘿，我的好朋友！再给我讲讲那头可怕的巨龙——死亡之翼的故事！', `FemaleText_loc5`='你好，我的好朋友!再跟我說一次關於那條可怕的龍，死亡之翼的故事!', `FemaleText_loc7`='¡Hola, mi $gbuen amigo:buena amiga;! ¡Cuéntame otra vez esa historia del temible dragón, Alamuerte!' WHERE `ID`=58927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 늙은 엉겅퀴 노인은 동굴에 갇히게 됐는데, 그의 충직한 무샨인 보보를 부르려고 휘파람을 부는 수밖에 없겠는 거예요!$B$B그리자 얼마 지나지 않아서 쿵쾅거리는 소리가 들리고, 보보가 그 동굴 안으로 구멍을 파기 시작했어요!$B$B그다음 동굴이 흔들리더니 천정이 무너져내리기 시작했죠.$B$B그래서 늙은 엉겅퀴 노인은 보보의 등에 올라탔어요. 그다음에 무슨 일이 일어났는지 아세요?', `FemaleText_loc4`='老农阿蓟被困在了洞穴里，于是他吹哨召唤他忠诚的穆山兽——波波！$B$B很快，他就听到了一声巨响，是波波在洞穴里炸出了一个洞！$B$B那头穆山兽听从了主人的召唤而来！$B$B而后，整个洞穴开始摇晃起来，洞顶开始坍塌。$B$B老农阿蓟跳上波波的后背，你知道后来发生了什么吗？', `FemaleText_loc5`='寂老頭被困在洞裡，所以他就吹口哨呼喚他忠實的牡山獸，波波!$B$B過沒多久，他就聽到轟的一聲，是波波把那洞窟撞破了一個大洞!$B$B那頭牡山獸聽到主人的呼喚前來找他!$B$B然後整個洞窟就開始搖晃，天花板開始崩塌。$B$B所以寂老頭跳到波波的背上，然後你知道發生了什麼事嗎?', `FemaleText_loc7`='Entonces Cardo el Viejo estaba encerrado en la cueva, ¡así que no se le ocurrió otra cosa que silbar para llamar a su leal mushan, Bobo!$B$BY al poco tiempo escuchó un ruido tremendo, ¡y entonces Bobo salió de repente de un agujero de la cueva!$B$B¡Ese mushan había oído a su amo y había ido a buscarlo!$B$B¿Y entonces sabes qué pasa? Que la cueva entera empieza a temblar y el techo empieza a derrumbarse.$B$BAsí que Cardo el Viejo salta a lomos de Bobo... ¿y sabes qué pasó después?' WHERE `ID`=58928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 제가 어릴 때는 웃긴 이름이 진짜 많았어요. 피시는 정말 이상한 이름이 아니에요. 아니, 아주 진짜 보통 이름이라고요!', `FemaleText_loc4`='知道吗，我的好朋友。我这辈子见过不少有趣的名字。玉儿真不算奇怪。不，一点儿都不奇怪！', `FemaleText_loc5`='你知道嗎，我的好朋友，我一生看過許多好笑的名字。小魚真的一點都不奇怪。不，這根本就是很正常的名字!', `FemaleText_loc7`='Verás, mi $gbuen amigo:buena amiga;, he oído un montón de nombres graciosos en mi vida. Pez no me parece tan raro. ¡Me parece hasta normal!' WHERE `ID`=58929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠는 항상 좋은 친구는 싸구려 당근보다 더 좋은 거라고 하셨어요. 그래서 우리 $n $g아저씨:아줌마;가 제 좋은 친구인 거예요!', `FemaleText_loc4`='老爸常告诫我——萝卜虽爽口，友情价更高。那就是为什么你会是我的好朋友，$n！', `FemaleText_loc5`='我老爸總是告訴我好朋友比胡蘿蔔片更有價值。那就是為什麼你是我好朋友，$n!', `FemaleText_loc7`='Mi papá siempre me decía que los buenos amigos valen más que una zanahoria fresca. ¡Por eso tú eres mi $gbuen amigo:buena amiga;, $n!' WHERE `ID`=58930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 오늘은 뭐하세요?', `FemaleText_loc4`='你好，邻居！你今天打算做啥？', `FemaleText_loc5`='你好啊，鄰居!你今天要做什麼啊?', `FemaleText_loc7`='¡Qué hay, vecino! ¿Cómo estamos hoy?' WHERE `ID`=58931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 저는 이야기를 너무 좋아해요. 그래서 이야기라면 전부 다 듣고 싶어요!$B$B하지만 우리 둘이서 좋은 이야기를 만들었다는 생각도 들어요. 안 그래요?', `FemaleText_loc4`='你好，邻居！我太爱听故事了，我真想把它们都听个遍！$B$B不过你知道的，我想我们一起编了不少好故事，不是吗？', `FemaleText_loc5`='你好，鄰居!我太喜歡故事了，我想要聽所有的故事!$B$B但你知道嗎，我覺得我們也一起創造了一些好故事，你不覺得嗎?', `FemaleText_loc7`='¡Hola, vecino! ¡Me gustan tanto las historias que quiero escucharlas todas!$B$BPero bueno, creo que hemos creado buenas historias $gjuntos:juntas;, ¿no crees?' WHERE `ID`=58932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래서 동굴이 무너지자 늙은 엉겅퀴 노인과 보보는 있는 힘을 다해 달렸어요! 언덕 위에 있는 땅 밖으로 확 하고 빠져나올 때까지 동굴 안에서 요리조리 방향을 바꾸고 뒤틀면서 말이죠!$B$B그렇게 동굴을 빠져나오자 동굴 입구가 바로 뒤에서 닫혔어요. 마치 땅이 삼켜버리듯 말이죠.$B$B늙은 엉겅퀴 노인은 몸이 부들부들 떨렸지만, 집으로 가서 가장 먼저 보물로 가득 찬 동굴로 가는 지도를 만들었어요. 아직 그 동굴이 있을지도 모르니까요. 그렇죠?$B$B정말 현명한 노인이었던 거죠. 왜냐하면 다음 날에는 기억이 잘 나지 않았고, 그 다음 날에는 더욱더 기억이 안 났거든요. 그러다가 나중에는 그 동굴로 가는 길을 완전히 잊어버렸어요.', `FemaleText_loc4`='那洞穴开始坍塌，老农阿蓟和波波拼命跑！他们腾挪闪躲，在山洞中穿梭，直到在那山上破地而出！$B$B然后那个洞穴在他们身后合拢起来，就好像被大地吞没了一样。$B$B老农阿蓟浑身打颤，但是他到家做的第一件事就是给那个堆满财宝的洞穴画了一张藏宝图。因为那洞穴或许还在那儿，不是吗？$B$B他做了件正确的事，因为到了第二天，他就想不起来洞穴在哪儿了。接着又过了一天，他忘得更厉害了，后来就连那洞穴的事也忘得一干二净。', `FemaleText_loc5`='洞窟開始崩塌下來，而寂老頭和波波拼老命地逃跑!他們左彎右拐地穿過洞窟，直到他們從那山丘的地面衝了出來!$B$B然後他們背後的洞窟就像被大地吞噬一樣，整個塌了下來。$B$B寂老頭還在發抖，但他回到家的第一件事就是畫一張那裝滿寶藏洞窟的地圖。因為它或許還在那裡，對吧?$B$B幸好他有這麼做，因為隔天他就記得不那麼清楚了，再隔天他忘了更多，直到他把洞窟的事完全遺忘。', `FemaleText_loc7`='De modo que la cueva se está derrumbando, y Cardo el Viejo y Bobo corren todo lo que pueden. ¡Dan vueltas y más vueltas por la cueva hasta que salen impulsados desde el suelo en esa montaña!$B$BY lo que ocurrió después es que la cueva se cerró tras ellos, como si se la hubiera tragado la tierra.$B$BCardo el Viejo tiembla, pero lo primero que hace al llegar a casa es dibujar un mapa hacia esa cueva llena de tesoros. Porque quizá siga allí, ¿no?$B$BMenos mal que lo hizo, porque al día siguiente ya no se acordaba, y al siguiente menos aún, hasta que un día se olvidó por completo de la cueva.' WHERE `ID`=58933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 우리 식구 $n 님. 그런데 우리 무슨 이야기하던 중이었죠? 이름 이야기는 아니었어요!$B$B아빠는 항상 이렇게 말씀하셨죠. 분홍 멜론을 양파라고 불러도 계속 먹을 거 아니겠냐고.', `FemaleText_loc4`='嘿，邻居，我们到底在谈些什么啊？名字什么的无所谓啦！$B$B就像我爸常说的那样——即便你爱吃的粉瓜被叫作洋葱，你还是会吃的，对不？', `FemaleText_loc5`='嘿，鄰居，我們到底在說些什麼?不就是個名字嗎?$B$B就像我老爸常說的，就算把粉紅甜瓜叫成洋蔥，你還是會把它吃掉，對吧?', `FemaleText_loc7`='Oye, $gvecino:vecina;, ¿y de qué estamos hablando? ¡Qué más dará un nombre!$B$BComo mi papá decía siempre, te comerías igualmente un melón rosa aunque se llamara cebolla, ¿verdad?' WHERE `ID`=58934;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠는 항상 좋은 이웃은 땅보다도 좋은 거라고 하셨어요. 이 정도면 말 다한 거죠 뭐! 그래서 우리 식구 $n $g아저씨:아줌마;가 제 가장 친한 친구인 거예요!', `FemaleText_loc4`='老爸常告诫我——土地诚可贵，友邻价更高。现在真被他说中了！$B$B那就是为什么你会是我的邻居，$n！', `FemaleText_loc5`='我老爸總是告訴我鄰居比土地更有價值。那可不是隨便說說!那就是為什麼你是我鄰居，$n!', `FemaleText_loc7`='Mi papá siempre me decía que los vecinos valen más que la tierra. ¡Muy bien dicho!$B$B¡Por eso eres mi $gvecino:vecina;, $n!' WHERE `ID`=58935;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 여기 있는 돼지들을 돌보고 있답니다.', `FemaleText_loc4`='我在这附近照看着几头猪。', `FemaleText_loc5`='我負責照顧這一帶的小豬們。', `FemaleText_loc7`='Yo cuido de los cerdos de por aquí.' WHERE `ID`=58936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 돼지들은 오늘 잘 있답니다!', `FemaleText_loc4`='嘿，哥们！这些猪今天看起来不错嘛！', `FemaleText_loc5`='嘿，兄弟!豬群今天過得還可以!', `FemaleText_loc7`='¡Hola, colega! ¡Los cerdos están estupendos hoy!' WHERE `ID`=58937;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 내 친구 $n 님! 아직 내려가서 제 돼지 안 보셨죠?', `FemaleText_loc4`='你好，朋友！你下去见过我的猪了吗？', `FemaleText_loc5`='你好啊，朋友!你有去下面看過我的豬群了嗎?', `FemaleText_loc7`='¡Qué hay, $gamigo:amiga;! ¿Ya has visto a mis cerdos?' WHERE `ID`=58938;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 $n 님! 왜 우리 엄마 아빠가 제 이름을 돼지라고 안 지어줬는지 정말 모르겠네요.', `FemaleText_loc4`='你好，我的好朋友！为啥我爸妈没给我起名叫猪呢，我还挺费解的。', `FemaleText_loc5`='你好啊，我的好朋友!為什麼我老媽和老爸沒把我取名為豬豬，我一點都不明白。', `FemaleText_loc7`='¡Qué hay, mi $gbuen amigo:buena amiga;! Que por qué mi mamá y mi papá no me pusieron de nombre Cerdo... pues no lo sé.' WHERE `ID`=58939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 돼지들은 농장에서 어떻게 지내나요? 아주 행복할 거라고 믿어요!', `FemaleText_loc4`='嘿，邻居！你农场里的那些猪咋样？我敢打赌它们一定过得相当快活！', `FemaleText_loc5`='嘿，鄰居!你農場裡的豬還好嗎?我敢說他們非常快樂!', `FemaleText_loc7`='¡Hola, $gvecino:vecina;! ¿Qué tal están esos cerdos de tu granja? ¡Seguro que están muy, muy contentos!' WHERE `ID`=58940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 새로 온 거야?', `MaleText_loc4`='你是新来的吗？', `MaleText_loc5`='你新來的嗎?', `MaleText_loc7`='¿Tú $gnuevo:nueva; aquí?' WHERE `ID`=58941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 치 치 엄청 바쁘다. 뭐 원하는 거 있어?', `MaleText_loc4`='嘿，吱吱真的很忙。你想要什么？', `MaleText_loc5`='嘿，奇奇很忙。你需要什麼東西嗎?', `MaleText_loc7`='Oye, Chee Chee muy okupado. ¿Tú kiere algo?' WHERE `ID`=58942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치가 키우는 양 많이 겁먹었다... 언덕에 나쁜 원숭이들 있어! 나쁜 원숭이들!', `MaleText_loc4`='吱吱的羊羊好怕怕……山里的坏猴子！坏猴子！', `MaleText_loc5`='奇奇的羊羊好害怕...壞猴子就在山丘上!壞猴子!', `MaleText_loc7`='Las ovejas de Chee Chee tiene mucho miedo... ¡monos malos en la montaña! ¡Monos malos!' WHERE `ID`=58943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 치 치 너 알고 있다. 나 도와줬잖아, 그렇지?', `MaleText_loc4`='嗨，我认识你。你帮过我，对吗？', `MaleText_loc5`='呦，我以前認識你。你幫助過我，對嗎?', `MaleText_loc7`='Colega, yo te konoce de antes. Tú me ayuda, ¿sí?' WHERE `ID`=58944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치 문제가 심각하다. 아주, 아주 심각해.', `MaleText_loc4`='吱吱有大麻烦了。很大、很大的麻烦。', `MaleText_loc5`='奇奇有大麻煩了。很大，很大的麻煩。', `MaleText_loc7`='Chee Chee tiene gran problema. Grandes, grandes problemas.' WHERE `ID`=58945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치 농장에서 아주 열심히 일한다. 그랬더니 나쁜 원숭이들이 다 가져갔어!', `MaleText_loc4`='吱吱为农场付出很多，现在被坏猴子夺走了！', `MaleText_loc5`='奇奇為了農場努力工作。現在壞猴子跑來要奪走它!', `MaleText_loc7`='Chee Chee trabaja duro para la granja. ¡Ahora los monos malos se lleva todo!' WHERE `ID`=58946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 너 치 치 친구잖아, 그렇지?', `MaleText_loc4`='嘿，你是吱吱的哥们，对吗？', `MaleText_loc5`='嘿。你是奇奇的好兄弟，對吧?', `MaleText_loc7`='Oye. Tú es colega de Chee Chee, ¿sí?' WHERE `ID`=58947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 치 치 골이 아픈 문제 있다. 아주, 아주 골치 아파. 나 좀 도와줄래?', `MaleText_loc4`='吱吱遇到大麻烦了。很大、很大的麻烦。你能帮帮吱吱吗，哥们？', `MaleText_loc5`='奇奇有大麻煩了。很大，很大的麻煩。兄弟幫幫奇奇?', `MaleText_loc7`='Chee Chee tiene gran problema. Grandes, grandes problemas. ¿Colega ayuda a Chee Chee?' WHERE `ID`=58948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치 농장에서 열심히 일한다. $n|1은;는; 그거 알잖아, 그렇지?', `MaleText_loc4`='吱吱为农场付出很多，你能明白的，对吗哥们？', `MaleText_loc5`='奇奇為了農場努力工作。兄弟明白的，對吧?', `MaleText_loc7`='Chee Chee trabaja duro para granja. Colega entiende, ¿verdad?' WHERE `ID`=58949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 내 친구 $n, 골치 아픈 문제 있다. 그런데 친구까지 골치 아플 필요는 없다.', `MaleText_loc4`='嘿，朋友。我遇到麻烦了，但又不想连累你。', `MaleText_loc5`='嘿，朋友，我有些麻煩，但沒必要也成為你的麻煩。', `MaleText_loc7`='Oye, $gamigo:amiga;. Yo tiene problemas, pero no tiene ke ser tus problemas también.' WHERE `ID`=58950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 내 친구 $n, 농장 일은 어떻게 돼 가는 거야?', `MaleText_loc4`='嘿，朋友，农场现在怎么样啦？', `MaleText_loc5`='嘿，朋友，你的農場還好嗎?', `MaleText_loc7`='Oye, $gamigo:amiga;, ¿kómo va la cosa en tu granja?' WHERE `ID`=58951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치는 호젠에서 유일하게 농장 갖고 있다!$B$B<자랑스럽게 가슴을 두드리는 치 치>$B$B내 친구 $n, 가끔 내 농장 놀러 와. 알았지?', `MaleText_loc4`='吱吱是唯一一个有农场的猢狲！$B$B<吱吱骄傲地拍打自己的胸脯。>$B$B你，朋友，有空来转转，好吗？', `MaleText_loc5`='奇奇是唯一擁有農場的猴人!$B$B<奇奇自豪地捶了捶胸口。>$B$B你，朋友，有空來我的農場參觀，好嗎?', `MaleText_loc7`='¡Chee Chee es el úniko hozen con granja propia!$B$B<Chee Chee se golpea el pecho con orgullo.>$B$BTú, $gamigo:amiga;, viene a visitarme a mi granja alguna vez, ¿si?' WHERE `ID`=58952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n! 가끔 치 치랑 한잔해야 해? 알았지?', `MaleText_loc4`='我的好朋友！有空来和吱吱喝两杯，怎么样？', `MaleText_loc5`='我的好朋友!有空來找奇奇喝酒，好嗎?', `MaleText_loc7`='¡Mi $gbuen amigo:buena amiga;! Tú bebe kon Chee Chee alguna vez, ¿sí?' WHERE `ID`=58953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n, 일은 잘 돼가?', `MaleText_loc4`='好朋友，你过得怎么样啊？', `MaleText_loc5`='好朋友，事情都還順你意嗎?', `MaleText_loc7`='$gBuen amigo:Buena amiga;, ¿todas tus kosas va bien?' WHERE `ID`=58954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n, 치 치는 농장에 양만 키운다!$B$B양 갖고 싶어하면 다들 치 치에게 온다.', `MaleText_loc4`='吱吱的农场只有羊！$B$B谁想要羊，就来找吱吱。', `MaleText_loc5`='奇奇的農地只養綿羊!$B$B有人想要綿羊，他們就會來找奇奇。', `MaleText_loc7`='¡Chee Chee kría a las únikas ovejas en los campos!$B$BSi alguien kiere ovejas, viene a Chee Chee.' WHERE `ID`=58955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 우리 식구 $n! 너 양 좋아해?', `MaleText_loc4`='嘿，邻居！你喜欢羊吗？', `MaleText_loc5`='嘿，鄰居!你喜歡這綿羊嗎?', `MaleText_loc7`='¡Oye, $gvecino:vecina;! ¿Te gusta las ovejas?' WHERE `ID`=58956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 덕분에 걱정이 한결 덜해졌다.', `MaleText_loc4`='邻居，多亏你，我减轻了不少麻烦。', `MaleText_loc5`='鄰居，因為你，我的麻煩些許減少了。', `MaleText_loc7`='$gVecino:Vecina;, gracias a ti, mis problemas son algo menos.' WHERE `ID`=58957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 나는 좋은 양만 준다! 어때?', `MaleText_loc4`='我把我最好的羊给你，邻居！你觉得怎么样？', `MaleText_loc5`='我只會給你優質的綿羊，鄰居!你覺得如何?', `MaleText_loc7`='¡Yo da solo ovejas buenas para ti, $gvecino:vecina;! ¿Ké tú piensa?' WHERE `ID`=58958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 안녕하세요! 음... 아무래도 저는... 가봐야겠어요...$B$B<목소리가 기어들듯 작아지며 얼굴이 붉어지는 엘라>', `FemaleText_loc4`='哦！嗨！呃……我或许该……走……$B$B<艾拉红着脸，窃窃私语道。>', `FemaleText_loc5`='喔!嗨!嗯...或許我應該...離開...$b$b<隨著艾拉說話聲音越來越小，她的臉紅了起來。>', `FemaleText_loc7`='¡Ah! ¡Hola! Um... Quizá debería... marcharme...$B$B<Ella se pone colorada a medida que su voz se va reduciendo a un susurro.>' WHERE `ID`=58959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순무... 좋아하세요?$B$B<얼굴이 붉어지며 손을 바르르 떠는 엘라>', `FemaleText_loc4`='你喜欢……芜菁吗？$B$B<艾拉脸红了，摇了摇头。>', `FemaleText_loc5`='你喜歡...菜頭嗎?$B$B<艾拉紅著臉搖搖頭。>', `FemaleText_loc7`='¿Te gustan las... nabas?$B$B<Ella se pone colorada y niega con la cabeza.>' WHERE `ID`=58960;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고양이 좋아하세요? 저는 너무 좋아해요!$B$B<갑자기 너무 크게 말해서 깜짝 놀라 부끄럽게 웃는 엘라>', `FemaleText_loc4`='你喜欢猫咪吗？我喜欢！$B$B<艾拉为她的冒失愣住了，害羞地笑了笑。>', `FemaleText_loc5`='你喜歡小貓嗎?我愛死他們了!$B$B<艾拉似乎對自己的唐突感到驚訝而害羞地微笑。>', `FemaleText_loc7`='¿Te gustan los gatitos? ¡A mí me encantan!$B$B<Ella se sorprende por su repentino arrebato y sonríe tímidamente.>' WHERE `ID`=58961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님. 잘 지내시죠?', `FemaleText_loc4`='嘿，你好啊，$n。今天过得怎么样？', `FemaleText_loc5`='嘿，$n。你今天好嗎?', `FemaleText_loc7`='Hola, $n. ¿Cómo estás hoy?' WHERE `ID`=58962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저는 가족 농장에서 순무를 기른답니다. 아... 이걸 알고 싶어하셨는지는 모르겠네요...', `FemaleText_loc4`='我在我家的农场里种芜菁。哦……我也不知道你想不想听那个……', `FemaleText_loc5`='我在我的農場種菜頭。喔...我不知道你是否有興趣知道...', `FemaleText_loc7`='Cultivo nabas en mi granja familiar. Oh... no sé si querías saber eso...' WHERE `ID`=58963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 제가 고양이를 그 정도로 많이 키우지는 않아요. 제 말은, 이 정도는 적당한 숫자라는 거죠.', `FemaleText_loc4`='我的猫也没那么多，不是吗？我意思是，这么想还是说得过去的。', `FemaleText_loc5`='我並沒有那麼多貓，對吧?我是指，當你仔細想想這數量還是很合理的。', `FemaleText_loc7`='No tengo tantos gatos, ¿verdad? Es decir, es un número bastante razonable si lo piensas.' WHERE `ID`=58964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 내 친구 $n 님! 오늘 날이 아주 좋지 않아요?', `FemaleText_loc4`='嘿，你好啊，朋友！多好的天，不是吗？', `FemaleText_loc5`='你好，朋友!今天真是個美好的日子。', `FemaleText_loc7`='¡Hola, $gamigo:amiga;! ¿Verdad que hace un día precioso?' WHERE `ID`=58965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 그 순무로 술을 만들면 꽤 맛있다는 거 아세요?', `FemaleText_loc4`='你知道吗？用芜菁酿出来的酒味道可好了。', `FemaleText_loc5`='你知道菜頭可以釀出相當美味的酒嗎?', `FemaleText_loc7`='¿Sabías que con las nabas se hace una cerveza muy sabrosa?' WHERE `ID`=58966;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 고양이는 제 친구가 돼준답니다. 부모님께서 돌아가신 뒤로는 밭에서 일하는 게 외로웠거든요...$B$B아, 이렇게 많이 말하고 싶지는 않았는데.', `FemaleText_loc4`='这些猫一直陪伴着我。自从我父母离世后，一个人在农场很寂寞……$B$B哦不，我并不想和你说这么多的。', `FemaleText_loc5`='這群貓陪伴著我。自從我的父母過世後，我在農場裡相當孤單...$b$b喔不，我沒有打算要跟你說這麼多。', `FemaleText_loc7`='Los gatos me hacen compañía. Me he sentido muy sola desde que mis padres fallec...$B$BOh no, no quería contarte tantas cosas.' WHERE `ID`=58967;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 $n 님. 아, 제가 우리 $n 님이라고 불러도 괜찮죠?', `FemaleText_loc4`='你好，我的好朋友。哦，我管你叫我的好朋友，你介意吗？', `FemaleText_loc5`='哈囉，好朋友。喔，我可以稱呼你為好朋友嗎?', `FemaleText_loc7`='Hola, $gbuen amigo:buena amiga;. ¿Te importa si te llamo mi $gbuen amigo:buena amiga;?' WHERE `ID`=58968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 저는 남는 시간에 모든 종류의 맥주를 연구해보고 있어요. 스톰스타우트 양조장이 길 바로 건너편에 있으니, 가끔 그렇게 해보고 싶은 생각이 안 들 수가 없더라고요.$B$B아, 그런데 이건 아무래도 저기 있는 양조장에서 만든 것만큼은 맛이 좋지 않아요.', `FemaleText_loc4`='我在闲暇时间会利用各种各样的酒来做实验。$B$B而且风暴烈酒酿造厂就在街对面，我有时更按耐不住了。$B$B哦，但是也没有其他地方能酿造出比这儿更好的酒了。', `FemaleText_loc5`='我在空閒時實驗過許多種酒。$B$B因為風暴烈酒酒坊就在對面，我有時不自主地就會有靈感。$B$B喔，但是這些酒跟他們那邊釀的酒比還差得遠了。', `FemaleText_loc7`='He estado experimentando con todo tipo de cervezas en mi tiempo libre.$B$BCon la Cervecería del Trueno al otro lado de la calle, no puedo evitar sentir la inspiración de vez en cuando.$B$BEn fin, pero estas no son ni la mitad de buenas que las que hacen allí.' WHERE `ID`=58969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 고양이가 몇 마리냐고요?$B$B아, 음... 몇 마리인지 잊어버린 것 같아요...', `FemaleText_loc4`='我有多少只猫？$B$B噢，呃……我想我已经数不清了……', `FemaleText_loc5`='我有幾隻貓啊?$B$B喔，嗯嗯...我想我已經記不清楚了...', `FemaleText_loc7`='¿Cuántos gatos tengo?$b$bMmm... Creo que he perdido la cuenta...' WHERE `ID`=58970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 오늘 아침에 보니 순무가 아주 좋아 보이더라고요.', `FemaleText_loc4`='你好，邻居！今早的芜菁看上去真不错啊。', `FemaleText_loc5`='你好啊，鄰居!今天早上的菜頭看起來真是有夠棒。', `FemaleText_loc7`='¡Qué hay, $gvecino:vecina;! Las nabas tienen una pinta estupenda esta mañana.' WHERE `ID`=58971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님, 그러니까 저는 제 맥주를 마을 이웃들에게 나눠주고 있었어요. 그러니까 모두 무척 좋아하더라고요! 정말 믿을 수가 없어요!', `FemaleText_loc4`='我将我的一些酒分享给镇子里的人，每个人都大加赞赏！我真是不敢相信！', `FemaleText_loc5`='我在鎮上分享了一些我的酒，而每個人都極力讚賞。我簡直不敢相信!', `FemaleText_loc7`='He estado dando a probar mis cervezas por la ciudad... ¡y todo el mundo está encantado! ¡No me lo puedo creer!' WHERE `ID`=58972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님, 루나는 어떻게 지내요? 정말 귀여운 고양이랍니다!', `FemaleText_loc4`='露娜还好吗？她可乖啦！', `FemaleText_loc5`='月神還好嗎?她實在是隻可愛的小貓!', `FemaleText_loc7`='¿Cómo está Luna? ¡Es una gata maravillosa!' WHERE `ID`=58973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 주둔지로 가는 수송대가 곧 떠나요! 모이세요!', `MaleText_loc4`='前往寇塔营地的商队就要出发了！快集合！', `MaleText_loc5`='往柯沓營地的車隊正要離開!集合!', `MaleText_loc7`='¡El convoy para el Campamento Base Kota está a punto de salir! ¡Acérquense!' WHERE `ID`=58974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밭에 안 좋은 일이 생겼군. 토깽이나 호젠 중 어떤 놈이 말썽을 피우든, 좋진 않을 걸세.', `MaleText_loc4`='田里有麻烦啦。我告诉你，不论是兔妖还是猢狲，都不是什么好东西。', `MaleText_loc5`='農地裡有些麻煩。不管是兔妖還是猴人，我跟你說，反正都不是好事。', `MaleText_loc7`='Tengo problemas en el campo. Ya sean mures o hozen, te aseguro que no pinta bien.' WHERE `ID`=58975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다네. 내가 바로 농사꾼 연합의 조합장이지. 그런데 그건 왜 묻나?', `MaleText_loc4`='没错，我就是阡陌客的首领。你为什么要问这个？', `MaleText_loc5`='沒錯，我就是耕者工會的頭頭。你為什麼這麼問?', `MaleText_loc7`='Sí, soy el líder del gremio de labradores. ¿Por qué me lo preguntas?' WHERE `ID`=58976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 이곳에 있는 밭들은 작황이 아주 좋기는 하지만, 그게 다 등골 빠지게 열심히 일한 덕분이라네!', `MaleText_loc4`='的确，这里的农田非常肥沃，但这都缘于我们起早贪黑、没日没夜的辛勤劳作！', `MaleText_loc5`='沒錯這裡的農地很富足，但那是因為辛勤工作到背都快斷掉的成果。', `MaleText_loc7`='¡Claro que los campos son muy prósperos por aquí! ¡Pero eso es porque nos dejamos el lomo trabajándolo!' WHERE `ID`=58977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $n, 토깽이나 호젠 놈들과 싸워본 적이 있나?', `MaleText_loc4`='嘿，哥们，你有没有对付猢狲或兔妖的经验？', `MaleText_loc5`='嘿，兄弟，你有處理過猴人或兔妖的經驗嗎?', `MaleText_loc7`='Oye, colega, ¿tienes experiencia en el trato con los hozen o lo mures?' WHERE `ID`=58978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $n, 제대로 된 농부들이라면 모두 농사꾼 연합 소속이라는 걸 알고 있었나?', `MaleText_loc4`='哥们，你知不知道每位风尘仆仆的农夫都是阡陌客的一员？', `MaleText_loc5`='兄弟，你知道每個好農夫都是耕者工會的成員嗎?', `MaleText_loc7`='Colega, ¿sabías que cualquier granjero que se precie es miembro del gremio de labradores?' WHERE `ID`=58979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야 누군가 했더니 $n 아닌가! 방금 밭에서 기나긴 하루를 보내고 오는 중이라네.', `MaleText_loc4`='嘿，要不是我的哥们$n！我恐怕要在农田里耗上一整天了。', `MaleText_loc5`='嘿，這不是我的兄弟$n嗎!我剛從農地裡忙了一天回來。', `MaleText_loc7`='¡Anda, pero si es mi colega $n! Vengo ahora mismo de un largo día en el campo.' WHERE `ID`=58980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 $n, 혹시 호젠이나 토깽 놈들을 상대해본 적이 있나?', `MaleText_loc4`='嘿，朋友，你有没有对付猢狲或兔妖的经验？', `MaleText_loc5`='嘿，朋友，你有處理過猴人或兔妖的經驗嗎?', `MaleText_loc7`='Oye, $gamigo:amiga;, ¿tienes experiencia en el trato con los hozen o lo mures?' WHERE `ID`=58981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 내 친구. 오늘 밭 상태는 어떻던가?', `MaleText_loc4`='嘿，朋友，今天的地看起来怎么样啊？', `MaleText_loc5`='嘿，朋友，今天土壤看起來如何?', `MaleText_loc7`='Oye, $gamigo:amiga;, ¿qué tal está la tierra hoy?' WHERE `ID`=58982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 $n 아닌가! 이리 와서 함께 한잔하세나.', `MaleText_loc4`='$n，我的朋友！让我们来一起喝一杯吧。', `MaleText_loc5`='我的朋友，$n!讓我們一起分享這酒吧。', `MaleText_loc7`='¡Mi $gamigo:amiga; $n! Vamos a tomar un trago juntos.' WHERE `ID`=58983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n, 토깽 놈들을 박멸하려면 알아 둬야 할 게 몇 가지 있다네.', `MaleText_loc4`='好朋友，你肯定知道一两个消灭兔妖的办法。', `MaleText_loc5`='我的好朋友，你一定對消滅兔妖略知一二。', `MaleText_loc7`='Mi $gbuen amigo:buena amiga;, debes saber un par de cosas sobre cómo exterminar a los mures.' WHERE `ID`=58984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 좋은 친구끼리는 항상 농사에 관한 비법을 공유한다네. 우리 $n, 이제 내게 말해주게. 이런 채소를 어떻게 길러낸 건가?', `MaleText_loc4`='知道吗，好朋友常常会分享他们的务农小秘密。现在告诉我吧，你是如何把你的蔬菜种成那样的？', `MaleText_loc5`='你知道的，好朋友們總會分享他們的種田秘訣。現在告訴我，你是怎麼讓你的蔬菜長成那樣的?', `MaleText_loc7`='Ya sabes, los buenos amigos comparten sus secretos de labranza. Dime... ¿cómo haces para que tus verduras estén así?' WHERE `ID`=58985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밭에서 기나긴 하루를 보내고 오면 목이 마르기 마련이지. 무슨 말인지 알지 않나, 우리 $n?', `MaleText_loc4`='在田里劳作一整天，会让人口干舌燥。你懂我的意思吧，好朋友？', `MaleText_loc5`='在田裡工作了整天實在讓人口渴，你知道我的意思吧，兄弟?', `MaleText_loc7`='Un largo día en el campo da mucha sed... ¿sabes adónde quiero ir a parar, mi $gbuen amigo:buena amiga;?' WHERE `ID`=58986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 그 무샨 야수는 어떻게 지내고 있나? 정말 예쁘지, 안 그런가?', `MaleText_loc4`='嘿，邻居，那头穆山兽活儿干得怎么样啊？她可是个大美人，不是吗？', `MaleText_loc5`='嘿，鄰居，那隻牡山獸有幫上你的忙嗎?她真是個美人，不是嗎?', `MaleText_loc7`='Oye, $gvecino:vecina;, ¿qué tal te va con aquella bestia mushan? ¿No te parece una preciosidad?' WHERE `ID`=58987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리는 한식구가 된 걸세. 그러니 이제 농사 비법을 말해줘야만 하네. 비료를 쓰나? 성장 촉진제는? 잡초 제거제 같은 건? 어서 말해보게나, 우리 식구 $n!', `MaleText_loc4`='既然我们现在成邻居了，你得告诉我你的务农小秘密。你用化肥了？增长素？除草剂？快告诉我嘛！', `MaleText_loc5`='既然我們現在是鄰居了，你必須告訴我你的種田秘訣。你有使用肥料嗎?成長劑?滅草劑?快告訴我!', `MaleText_loc7`='Ahora que somos vecinos, tienes que contarme tus secretos de labranza. ¿Utilizas fertilizantes? ¿Productos de crecimiento? ¿Herbicidas? ¡Dímelo, venga!' WHERE `ID`=58988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑군, 우리 식구 $n. 시원한 맥주 한 잔 어떤가?', `MaleText_loc4`='你好，邻居。想来杯冰镇啤酒吗？', `MaleText_loc5`='你好啊，鄰居。要不要來杯冰啤酒啊?', `MaleText_loc7`='Qué hay, $gvecino:vecina;. ¿Te apetece una cerveza fría?' WHERE `ID`=58989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 여행자여. 이제 괜찮습니다.', `MaleText_loc4`='谢谢你，旅行者。我觉得我现在能行了。', `MaleText_loc5`='謝謝你，旅者。我想我現在能撐過了。', `MaleText_loc7`='Gracias, $gviajero:viajera;. Creo que saldré adelante.' WHERE `ID`=58990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인 상대할 시간 따윈 없네. 이제 나 좀 내버려 두게나.', `MaleText_loc4`='我可没时间和陌生人打交道。现在请你离开。', `MaleText_loc5`='我沒時間浪費在陌生人身上。現在請你不要打攪我。', `MaleText_loc7`='No tengo tiempo para forasteros. Ahora déjame tranquilo, por favor.' WHERE `ID`=58991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바쁜 거 안 보이나? 할 일이 있단 말이네, 이방인 친구.', `MaleText_loc4`='没看到我正忙吗？我在做事情呢，陌生人。', `MaleText_loc5`='你看不出來我很忙嗎?我有工作要做，陌生人。', `MaleText_loc7`='¿Es que no ves que estoy ocupado? Tengo mucho trabajo que hacer, $gforastero:forastera;.' WHERE `ID`=58992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시나리오를 마쳤습니다. 만세!', `MaleText_loc4`='你打赢了场景战役。万岁！', `MaleText_loc5`='你已經完成了這個事件。喔耶!', `MaleText_loc7`='¡HAS GANADO EN ESTE ESCENARIO! ¡VIVA!' WHERE `ID`=58993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 거 정말! 이 늙은이 좀 그냥 놔두란 말이네!', `MaleText_loc4`='呸！让老头我清静清静！', `MaleText_loc5`='唉!不要打攪我這老人。', `MaleText_loc7`='¡Bah! ¡Deja en paz a este viejo!' WHERE `ID`=58994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사하다는 말씀을 드리고 싶습니다. 이제 다시 훈련을 시작해야겠습니다.', `MaleText_loc4`='非常感谢。我现在该回去训练了。', `MaleText_loc5`='我很感謝你。我現在得要回去訓練了。', `MaleText_loc7`='Tienes mi gratitud. Ahora debería volver al entrenamiento.' WHERE `ID`=58995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 난 좀 바쁘다네. 안 보이나?', `MaleText_loc4`='唉，我很忙，你看不到吗？', `MaleText_loc5`='哼嗯嗯。我在忙，你看不出來嗎?', `MaleText_loc7`='Uff. Estoy ocupado. ¿Es que no lo ves?' WHERE `ID`=58996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구에게나 다 이렇게 귀찮게 구는 건가? 제기랄.', `MaleText_loc4`='你总是这么烦人吗？真是的。', `MaleText_loc5`='你都是這樣纏著每個人嗎?我的天啊。', `MaleText_loc7`='¿Acosas así a todo el mundo? Puff.' WHERE `ID`=58997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 예전에 이 근처에서 본 적이 있다는 건 안다네. 하지만 그래서 친구라는 건 아닐세. 저리 가게!', `MaleText_loc4`='呸！我知道我见过你，但那并不意味着我们是朋友。快滚！', `MaleText_loc5`='呸!我知道我看過你，但那不代表我們是朋友。走開!', `MaleText_loc7`='¡Bah! Sé que hemos coincidido por ahí, pero eso no significa que seamos amigos. ¡Lárgate!' WHERE `ID`=58998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 얕은 상처에 제 의지가 꺾이지는 않을 겁니다.', `MaleText_loc4`='一点皮肉伤而已，轻伤不下火线嘛。', `MaleText_loc5`='一點皮肉之傷是無法阻止我戰鬥的。', `MaleText_loc7`='Una simple herida no me apartará de la batalla.' WHERE `ID`=58999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $n. 내가 좀 바쁘다네. 나중에 오면 안 되겠나?', `MaleText_loc4`='嘿，哥们，我现在很忙。你能过会儿再来吗？', `MaleText_loc5`='嘿，兄弟，我很忙。你可以晚點再來嗎?', `MaleText_loc7`='Mira, colega, estoy ocupado ahora mismo. ¿No puedes volver más tarde?' WHERE `ID`=59000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네 참 수다스럽구먼. 언제까지 떠들어댈 건가?', `MaleText_loc4`='哥们，你可真是个话痨。你嘴巴啥时候闲过？', `MaleText_loc5`='兄弟，你真的有個大嘴巴。它能停一下嗎?', `MaleText_loc7`='Colega, no te callas ni debajo del agua... ¿Alguna vez dejas descansar la boca?' WHERE `ID`=59001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $n, 그러니까... 가끔 이렇게 보니 반갑군.', `MaleText_loc4`='哥们，你知道某些时候……还是很高兴见到你的。', `MaleText_loc5`='兄弟，你知道的...有時候能看見你在附近也不壞。', `MaleText_loc7`='Mira, colega... A veces me alegro de tenerte cerca.' WHERE `ID`=59002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 내 친구, 지금은 좀 바쁘다네. 뭐 필요한 거라도 있나?', `MaleText_loc4`='嘿，朋友，我有点小忙。我这儿有你需要的东西吗？', `MaleText_loc5`='嘿，朋友，我有點忙。你需要什麼東西嗎?', `MaleText_loc7`='Mira, $gamigo:amiga;, estoy un poco ocupado ahora. ¿Se te ofrece algo?' WHERE `ID`=59003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 내 친구, 말이라는 건 해야 할 때만 하는 법이지. 하지만 가끔 조용한 것 말고 다른 소리를 듣는 것도 괜찮긴 하군.', `MaleText_loc4`='朋友，你真是一逮到机会嘴巴就说个不停。不过时不时的听人唠叨两句总比死一般的沉寂要好多了。', `MaleText_loc5`='朋友，你只要逮到機會就滔滔不絕的說個不停。但偶爾打破沉默聽點別的聲音也還不錯啦。', `MaleText_loc7`='$gAmigo:Amiga;, cómo te gusta darle a la lengua cuando te dan la oportunidad... pero es agradable oír algo que no sea el silencio de vez en cuando.' WHERE `ID`=59004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 병든 닭 세 마리와 알을 낳지 않는 닭 두 마리가 있네. 자네 말 들어주기에는 나도 고민이 너무 많다네, 도시 친구.', `MaleText_loc4`='我有三只生病的小鸡和两只不下蛋的母鸡。我自己都焦头烂额了，哪还有心思管你，城里人。', `MaleText_loc5`='我有三隻生病的公雞和另外兩隻不下蛋的母雞。我已經有太多麻煩，更沒心思去聽你的了，城市佬。', `MaleText_loc7`='Tengo a tres pollos enfermos y otras dos gallinas que no están poniendo. Tengo demasiados problemas como para escuchar los tuyos, zarpa urbanita.' WHERE `ID`=59005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $n, 지난밤에 닭 두 마리가 없어졌다네. 호젠 놈들이 한 짓인 게 분명해.', `MaleText_loc4`='嘿，哥们。昨晚我有两只小鸡失踪了，我敢打赌是猢狲干的好事。', `MaleText_loc5`='嘿，兄弟，我有兩隻雞昨晚不見了。我敢打賭一定是猴人在背後搞鬼。', `MaleText_loc7`='Oye, colega. Anoche se me perdieron dos gallinas. Seguro que los hozen están detrás de esto.' WHERE `ID`=59006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 내 친구. 내가 기른 닭이 낳은 신선한 계란 먹어봤나? 정말 맛이 끝내준다네.', `MaleText_loc4`='你好，朋友。有没有尝过我家的新鲜鸡蛋啊？超美味的，我跟你说。', `MaleText_loc5`='你好啊，朋友。你有試過我的雞生下的新鮮雞蛋嗎?告訴你，很很很美味喔。', `MaleText_loc7`='Qué hay, $gamigo:amiga;. ¿Has probado los huevos frescos de mis gallinas? Bueeeenísimos, hazme caso.' WHERE `ID`=59007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 내 친구. 오늘 들러줘서 고맙군.', `MaleText_loc4`='嘿，朋友，感谢你今天的来访。', `MaleText_loc5`='嘿，朋友，謝謝你今天來拜訪。', `MaleText_loc7`='Oye, $gamigo:amiga;, gracias por visitarme hoy.' WHERE `ID`=59008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 우리 $n 아닌가! 뭐 도와줄 거라도 있나?', `MaleText_loc4`='嘿，这不是我的好朋友$n嘛！我能帮你什么忙吗？', `MaleText_loc5`='嘿，是我的好朋友$n!有什麼事需要我幫忙嗎?', `MaleText_loc7`='¡Anda, pero si es $gmi buen amigo:mi buena amiga; $n! ¿Puedo hacer algo por ti?' WHERE `ID`=59009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n, 오늘 뭐 좋은 소식이라도 없나?', `MaleText_loc4`='我的好朋友，你今天给我带什么消息了吗？', `MaleText_loc5`='我的好朋友，你今天有任何新聞要跟我說嗎?', `MaleText_loc7`='$gMi buen amigo:Mi buena amiga;, ¿tienes algo que contarme hoy?' WHERE `ID`=59010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 $n, 가끔 나는 자네가 들러주는 걸 기다린다고 말해야겠군.', `MaleText_loc4`='你知道吗，$n，我得承认我偶尔会盼望你的到来。', `MaleText_loc5`='你知道，$n，我必須承認我偶而會期待你來拜訪。', `MaleText_loc7`='Mira, $n, tengo que admitir que me encanta recibir tus visitas de vez en cuando.' WHERE `ID`=59011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 우리 $n. 자네 농장에 닭이 몇 마리 있어야겠다고 생각했다네. 어떻게 생각하나?', `MaleText_loc4`='嘿，$n，我一直在想你的农场是否需要一些小鸡。你认为呢？', `MaleText_loc5`='嘿，$n，我一直認為你的農場需要一些雞。你覺得如何?', `MaleText_loc7`='Oye, $n, he pensado que tu granja necesita unas cuantas gallinas. ¿Qué te parece?' WHERE `ID`=59012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 반갑네. 오늘도 날이 좋구먼.', `MaleText_loc4`='你好，邻居。今天天气不错啊。', `MaleText_loc5`='你好啊，鄰居。今天是個好日子。', `MaleText_loc7`='Qué hay, $gvecino:vecina;. Hace un día estupendo.' WHERE `ID`=59013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 반갑네! 오늘 밭이 아주 갈색으로 반짝반짝 빛나는군.', `MaleText_loc4`='嘿，邻居！今天地里看起来就像是一枚闪闪发光的新铜币。', `MaleText_loc5`='嘿，鄰居!農地今天乾淨得就像嶄新的閃亮銅器一樣。', `MaleText_loc7`='¡Hola, $gvecino:vecina;! Los campos están relucientes hoy.' WHERE `ID`=59014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 우리 식구 $n! 만나서 반갑네! 언제라도 여기 들르게. 알았지?', `MaleText_loc4`='你好，邻居！很高兴见到你！你随时都可以来找我，听到了吗？', `MaleText_loc5`='你好啊，鄰居!很高興見到你!歡迎你隨時來找我，聽到了嗎?', `MaleText_loc7`='¡Qué hay, $gvecino:vecina;! ¡Me alegro de verte! Ven a visitarme cuando quieras, ¿vale?' WHERE `ID`=59015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n, 그 닭들은 잘지내나?$B$B닭들이 낳은 계란이 있나 둘러보게. 그놈들은 가장 요상한 장소에 계란을 숨겨놓거든!', `MaleText_loc4`='你好吗，$n？那些小鸡还好吗？$B$B一定要仔细找找它们的蛋，那些该死的小家伙就喜欢把蛋藏在最古怪的地方！', `MaleText_loc5`='嗯，$n?那些雞怎麼樣了?$B$B務必四處找找他們的蛋。那些臭東西會把它們藏在最詭異的地方!', `MaleText_loc7`='Bueno, $n... ¿Cómo van esas gallinas?$B$BNo olvides buscar los huevos por ahí. ¡Esos malditos bichos los esconden en los lugares más extraños!' WHERE `ID`=59016;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용히 해주세요. 집중해서 끝내야 할 임무가 있단 말이에요.', `FemaleText_loc4`='安静，陌生人。我需要集中精神来完成手头的任务。', `FemaleText_loc5`='安靜，陌生人。我手上的工作需要完全的專注。', `FemaleText_loc7`='Silencio, $gforastero:forastera;. Tengo que concentrarme bien para la tarea que tengo entre manos.' WHERE `ID`=59017;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신과 다툴 일은 없어요.', `FemaleText_loc4`='我对你没什么意见，陌生人。', `FemaleText_loc5`='我對你沒什麼抱怨，陌生人。', `FemaleText_loc7`='No estoy peleada contigo, $gforastero:forastera;.' WHERE `ID`=59018;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침묵해야만 나무들이 말하는 걸 들을 수 있을 거예요.', `FemaleText_loc4`='只有在寂静中，我们才能听到林木间的窃窃私语。', `FemaleText_loc5`='只有在寂靜中，我們能聽到樹木說話。', `FemaleText_loc7`='Únicamente en silencio podremos oír a los árboles hablar.' WHERE `ID`=59019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용히 해주세요. 제가 집중하는 데 방해하지 마시고요.', `FemaleText_loc4`='安静，$r。请别分散我的注意力。', `FemaleText_loc5`='安靜，$r。請不要打斷我的專注。', `FemaleText_loc7`='Silencio, $r. No perturbes mi concentración.' WHERE `ID`=59020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예전에 이 지역에서 본 적이 있어요. 처음 봤을 때부터 $c님인 걸 알아봤답니다.', `FemaleText_loc4`='我在这一带见过你。我能从你这身行头上看出来，你是一个$c。', `FemaleText_loc5`='我曾在這地區看過你們。我可以從你的外表看出你是一個$c。', `FemaleText_loc7`='Te he visto otras veces por aquí. Por tu aspecto, diría que eres $gun:una; $c.' WHERE `ID`=59021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말할 때 얻는 지혜보다는, 들을 때 얻는 지혜가 더 많답니다.', `FemaleText_loc4`='能说会道只能得点小聪明，善于倾听才会明白大智慧。', `FemaleText_loc5`='說話並不會讓一個人得到多少智慧。但聆聽可以讓一個人得到許多智慧。', `FemaleText_loc7`='Hablando se adquiere poca sabiduría. Escuchando se adquiere mucha sabiduría.' WHERE `ID`=59022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 무샨 야수들은 지금 당신이 내는 소리에도 겁을 집어먹는답니다.', `FemaleText_loc4`='嘿，哥们，你弄出来的噪音都能把一群穆山兽给吓跑了。', `FemaleText_loc5`='嘿，兄弟，你製造的噪音大到足以嚇跑一群牡山獸。', `FemaleText_loc7`='Oye, colega, con el ruido que estás haciendo podrías espantar a una manada de bestias mushan.' WHERE `ID`=59023;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제게 $c|1이;가; 된다는 게 어떤 건지 말하지 마세요, $n 님. 그냥 보여주시면 돼요.', `FemaleText_loc4`='别跟我讲什么样才算一个$c，露两手给我瞧瞧。', `FemaleText_loc5`='不要告訴我作為一個$c是怎樣的。展現給我看。', `FemaleText_loc7`='No me cuentes cómo es ser $gun:una; $c. Demuéstramelo.' WHERE `ID`=59024;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저는 호젠의 움직임을 연구하고 있어요. 놈들의 약점을 찾아내면 바로 한 방 날릴 거예요.', `FemaleText_loc4`='我在研究猢狲的动作。等我找到他们的弱点时，我就会出击。', `FemaleText_loc5`='我正在研究猴人的行動。當我發現他們的弱點時，我就會發動攻擊。', `FemaleText_loc7`='Estoy estudiando los movimientos de los hozen. Cuando descubra su punto débil, atacaré.' WHERE `ID`=59025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 무샨 야수들은 지금 당신이 내는 소리에도 겁을 집어먹는답니다.', `FemaleText_loc4`='我的朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。', `FemaleText_loc5`='我的朋友，你製造的噪音大到足以嚇跑一群牡山獸。', `FemaleText_loc7`='$gAmigo mío:Amiga mía;, con el ruido que estás haciendo podrías ahuyentar a una manada de bestias mushan.' WHERE `ID`=59026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 조만간 누가 전투에 더 능한지 알게 될 거예요. 당신, 아니면 저겠죠.', `FemaleText_loc4`='我的朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。', `FemaleText_loc5`='我的朋友，總有一天我們會在戰鬥中分出誰比較強，是你，還是我。', `FemaleText_loc7`='$gAmigo mío:Amiga mía;, un día de estos veremos quién es más fuerte en combate... tú o yo.' WHERE `ID`=59027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='현명한 판다렌은 전투를 서두르지 않아요. 그래서 현명한 이가 전투에서 승리하는 거랍니다.', `FemaleText_loc4`='智者不会仓促行事。智者运筹帷幄、决胜千里。', `FemaleText_loc5`='一個有智慧的人不會急著投入戰爭。一個有智慧的人會贏得戰爭。', `FemaleText_loc7`='Un hombre sabio no se precipita a la guerra. Un hombre sabio gana la guerra.' WHERE `ID`=59028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 무샨 야수들은 지금 당신이 내는 소리에도 겁을 집어먹는답니다.', `FemaleText_loc4`='我的好朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。', `FemaleText_loc5`='我的好朋友，你製造的噪音大到足以嚇跑一群牡山獸。', `FemaleText_loc7`='$gMi buen amigo:Mi buena amiga;, con el ruido que estás haciendo podrías ahuyentar a una manada de bestias mushan.' WHERE `ID`=59029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 조만간 누가 전투에 더 능한지 알게 될 거예요. 당신, 아니면 저겠죠.', `FemaleText_loc4`='我的好朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。', `FemaleText_loc5`='我的朋友，總有一天我們會在戰鬥中分出誰比較強，是你，還是我。', `FemaleText_loc7`='$gMi buen amigo:Mi buena amiga;, un día de estos veremos quién es más fuerte en combate... tú o yo.' WHERE `ID`=59030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 고향에서는 좋은 친구에게 나무를 주는 게 가장 멋진 선물이랍니다.$B$B왜인지 아세요, 우리 $n 님?$B$B나무는 평화와 성장, 그리고 생명을 의미하거든요. 그걸로 우정을 축복하는 거랍니다.', `FemaleText_loc4`='在我的家乡，一个人能送给好朋友的最好的礼物，就是一棵树了。$B$B你知道为什么吗？$B$B树代表了和平、成长和生命。它是对友情的一种祝福。', `FemaleText_loc5`='在我的家鄉，送給一個好朋友最棒的禮物就是一棵樹。$B$B你知道為什麼嗎?$B$B因為一棵樹代表了平靜，成長和生命。它是友情的祝福。', `FemaleText_loc7`='En mi tierra, el mejor regalo que se puede hacer a un amigo es un árbol.$B$B¿Sabes por qué?$B$BEl árbol representa la paz, el crecimiento y la vida. Es una bendición de la amistad.' WHERE `ID`=59031;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님이 오늘은 아주 조용히 다니시네요.', `FemaleText_loc4`='邻居，你今天手脚蛮轻得嘛。', `FemaleText_loc5`='鄰居，你今天走路很安靜。', `FemaleText_loc7`='$gVecino:Vecina;, hoy te mueves silenciosamente.' WHERE `ID`=59032;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님이 싸우신다면 언제라도 기꺼이 함께 싸울게요.', `FemaleText_loc4`='邻居，我会很高兴和你并肩作战的，无论何时。', `FemaleText_loc5`='鄰居，我隨時樂意和你並肩作戰。', `FemaleText_loc7`='$gVecino:Vecina;, estaré encantada de luchar a tu lado cuando quieras.' WHERE `ID`=59033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님, 나무가 마음에 드시나요? 묘목은 제가 직접 골랐답니다.', `FemaleText_loc4`='你喜欢这颗树吗？树苗可是我亲自挑选的。', `FemaleText_loc5`='你喜歡你的樹嗎?那樹苗是我親自挑選的喔。', `FemaleText_loc7`='¿Te gusta tu árbol? Elegí el esqueje personalmente.' WHERE `ID`=59034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 좋은 가게를 만드는 비밀을 알려 드릴까요? 그건 바로 유통이랍니다. 물건을 원하는 이들에게 가져다주는 방법이 필요해요.', `FemaleText_loc4`='嘿，朋友，你知道做成好买卖的诀窍吗？那就是销售。你需要一条渠道，将你的货物卖到需要的人手中。', `FemaleText_loc5`='嘿，朋友，你知道一個好市集的秘訣嗎?就是配送。你得有法子將你的貨物運送到想要買的人們手中。', `FemaleText_loc7`='Oye, $gamigo:amiga;, ¿sabes cuál es el secreto de un buen mercado? La distribución. Necesitas tener una manera de llevar tus productos a la gente que los necesita.' WHERE `ID`=59035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 제가 무슨 생각 했는지 아세요? 당신은 고향에 있는 친구들과도 계속 연락할 방법이 필요해요.$B$B당신 집에 잠깐 들러서 우체통을 설치해줄 수 있는 목수를 알고 있어요. 제 생각 어때요?', `FemaleText_loc4`='你知道我在想什么吗，我的好友？你需要一个方法，能够在家中和你所有的朋友保持联系。$B$B我认识一个木匠，他可以上门帮你安装邮箱。这主意不错吧。', `FemaleText_loc5`='你知道我最近在想什麼，我的好朋友?你需要一個在家也能和你的所有朋友保持聯絡的方法。$B$B我認識一個木匠可以來幫你安裝一個郵箱。你覺得這主意如何?', `FemaleText_loc7`='¿Sabes qué he estado pensando, mi $gbuen amigo:buena amiga;? Necesitas una manera de mantener el contacto con todos tus amigos desde casa.$B$BConozco a un carpintero que puede venir a instalarte un buzón. ¿Qué te parece mi idea?' WHERE `ID`=59036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 식구 $n 님, 우체통에 편지는 제대로 오고 있나요? 제 생각 좋았죠?', `FemaleText_loc4`='那邮箱用起来感觉如何啊？是个不错的主意吧？', `FemaleText_loc5`='那個郵箱還好用吧?是個好主意，不是嗎?', `FemaleText_loc7`='¿Qué tal te va con el buzón? No es mala idea, ¿eh?' WHERE `ID`=59037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 친구 $n 님, 농부 윤의 집이 정말 휑해 보이지 않나요?', `FemaleText_loc4`='嘿，朋友，你不觉得农夫老愚的房子看起来空荡荡的吗？', `FemaleText_loc5`='嘿，朋友，你不覺得那個農夫尹的房子看起來家徒四壁嗎?', `FemaleText_loc7`='Oye, $gamigo:amiga;, ¿no te parece que la casa del granjero Yoon tiene un aspecto bastante desangelado?' WHERE `ID`=59038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 $n 님, 제가 집안 장식하는 법을 좀 알고 있답니다. 농부 윤의 집에 어떤 게 필요한지 정확하게 알고 있어요!', `FemaleText_loc4`='我对家居装潢略知一二，我的好朋友。我知道农夫老愚的房子缺什么！', `FemaleText_loc5`='我對裝潢略知一二，我的好朋友。我知道農夫尹的房子需要些什麼!', `FemaleText_loc7`='Sé un par de cosas sobre decoración, mi $gbuen amigo:buena amiga;. ¡Sé exactamente lo que el granjero Yoon necesita para su casa!' WHERE `ID`=59039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 우리 식구 $n 님! 농부 윤의 집에 들여놓은 새 가구 어때요? 네, 그거 제가 직접 고른 거랍니다!', `FemaleText_loc4`='嘿，邻居！你觉得农夫老愚家里的新家具看起来如何啊？没错，那都是我亲自挑选的！', `FemaleText_loc5`='嘿，鄰居!你覺得農夫尹房子裡的新家具如何?沒錯，那些是我親自選出的!', `FemaleText_loc7`='¡Hola, $gvecino:vecina;! ¿Qué te parecen los nuevos muebles de la casa del granjero Yoon? ¡Sí, los he elegido yo misma!' WHERE `ID`=59040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치는 계곡 볶음 요리 먹는 거 좋아한다! 그거 찾으면 갖다 줘!', `MaleText_loc4`='吱吱爱吃谷地小炒。你要是找到了，就带给我！', `MaleText_loc5`='奇奇愛吃峽谷快炒。找到任何快炒，都拿來給我!', `MaleText_loc7`='A Chee Chee le enkanta komer revuelto del valle. ¡Si tú enkuentra, tráemelo!' WHERE `ID`=59041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게든 부상당한 이들을 치료해 주십시오. 도움이 될 겁니다.', `FemaleText_loc4`='不管你做什么，只要能够帮伤员重新站起来，我们都感激不尽。', `FemaleText_loc5`='任何能幫忙傷者恢復的協助，我們都很感激', `FemaleText_loc7`='Agradecería cualquier ayuda para atender a los heridos.' WHERE `ID`=59042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치 하늘 보는 거 좋아한다. 너무 예쁘고... 너무 파랗다...', `MaleText_loc4`='吱吱喜欢看天空，那么美……那么蓝……', `MaleText_loc5`='奇奇喜歡看著天空。多麼漂亮...多麼湛藍...', `MaleText_loc7`='A Chee Chee le gusta mirar el cielo. Tan bonito... tan azul...' WHERE `ID`=59043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 선물이요? 당신은 제게 아무것도 달라고 하지 않았으면 좋겠어요!', `FemaleText_loc4`='噢，礼物？我还以为你没打算送我东西呢！', `FemaleText_loc5`='喔，禮物?我希望你不是想要送我東西!', `FemaleText_loc7`='Ah, ¿regalos? ¡Espero que no estés pensando en regalarme nada!' WHERE `ID`=59044;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음, 알다시피... 저는 고양이가 좋아요!', `FemaleText_loc4`='你了解我的……我喜欢猫！', `FemaleText_loc5`='你知道我的...我喜歡貓!', `FemaleText_loc7`='Bueno, ya me conoces... ¡me gustan los gatos!' WHERE `ID`=59045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 말씀하시니까 생각난 건데... 엄마가 정말 맛있는 새우 만두를 만들어주시곤 하셨어요.$B$B하아... 엄마가 보고 싶어요...', `FemaleText_loc4`='既然你提到了……我妈做的虾饺最好吃了。$B$B唉……我好想她……', `FemaleText_loc5`='被你這麼提到了...我媽媽以前會做最棒的鮮蝦蒸餃。$B$B唉...我想念她...', `FemaleText_loc7`='Ahora que lo dices... mi madre hacía las mejores empanadillas de gambas.$B$BAy... cómo la echo de menos...' WHERE `ID`=59046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 아시듯이 제 멋진 외모와 동일한 칭찬을 들을 수 있는 건 이곳 근처에서 자라나는 진귀한 흰색 꽃뿐입니다.$B$B사막에서 바늘 찾는 것 같이 아주 드물지요.', `MaleText_loc4`='你知道吗，我唯一赞赏的是一种生长在这附近的稀有的白色百合，它们和我的外表不分伯仲。$B$B可是，它非常难得。', `MaleText_loc5`='你知道除了自己的相貌外，只有一種東西是我同樣欣賞的，那是一種生長在這地區的罕見白花。$B$B但是它極度地難找。', `MaleText_loc7`='Verás, lo único que me merece tanta admiración como mi propia belleza es una extraña flor blanca que crece por estos lares.$B$BSin embargo, es muy difícil de encontrar.' WHERE `ID`=59047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들새 숯불구이 드셔 본 적 있습니까?$B$B얼마나 맛이 좋은지! 지금 바로 먹을 수만 있다면 뭐든지 줄 겁니다!', `MaleText_loc4`='你吃过香烤野雉吗？$B$B嗯！我真想立刻尝上几口！', `MaleText_loc5`='你有嚐過炭烤野雉嗎?$B$B嗯嗯嗯!現在，要我為那滋味付出什麼代價都可以!', `MaleText_loc7`='¿Alguna vez has probado el ave silvestre asada?$B$B¡Mmm! Lo que daría por probarla ahora mismo...' WHERE `ID`=59048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐 전부 좋아하기는 하지만, 저는 동물이 가장 좋아요!', `FemaleText_loc4`='的确，我是很博爱，但我最喜欢的还是动物！', `FemaleText_loc5`='我什麼東西都喜歡，但是我還是最喜歡動物!', `FemaleText_loc7`='Bueno, me gusta casi todo, ¡pero los animales lo que más!' WHERE `ID`=59049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다양한 자원이 갖춰져 있으면 전투를 유리하게 끌고 갈 수 있습니다.$b$b주변 숲에서 채집한 식물들을 사용해서 치료제를 만들었습니다. 부상자들을 치료하기에 충분한 양이면 좋겠군요. 되도록 많은 병사가 필요하니까요.', `FemaleText_loc4`='充分的储备常常能扭转不利的战局。$b$b我已经把从林子里采来的草药调好了，但愿这些能够用。在战场上，我们需要所有能够战斗的人全部上场。', `FemaleText_loc5`='保持隨機應變常能讓戰鬥的優勢轉向自己。$b$b我用周遭森林裡的植物調配出這個藥方。希望這就足夠了。我們的戰場上需要每一個可用的戰士。', `FemaleText_loc7`='Tener recursos puede inclinar la balanza de la victoria a tu favor más de una vez.$b$bHe creado este remedio con plantas del bosque que nos rodea. Con suerte, bastará. Necesitamos a todos los luchadores en el campo de batalla.' WHERE `ID`=59050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 언제나 비취색을 좋아했답니다. 숲처럼 진한 녹색이라서요.', `FemaleText_loc4`='你知道吗，我一直都很喜欢玉石的颜色。如此翠绿，就和那森林一样。', `FemaleText_loc5`='你知道，我一直都很喜歡玉的顏色。這麼地翠綠，就像森林一樣。', `FemaleText_loc7`='Mira, siempre me ha gustado el color del jade. Tan verde... como el bosque.' WHERE `ID`=59051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 바보 같은 질문이네요! 제가 힌트를 드릴게요. 제가 가장 좋아하는 음식에는 제 이름이 들어간답니다! 한 번 이상일 거예요!', `FemaleText_loc4`='多傻的问题啊！我给你个提示吧。我最喜爱的食物里有我的名字！或许还不止一个哦！', `FemaleText_loc5`='真是個蠢問題!我給你個提示。我最愛的食物裡面有我的名字!也許出現不只一次!', `FemaleText_loc7`='¡Qué pregunta más estúpida! Te daré una pista. ¡Mi comida favorita contiene mi nombre! ¡Quizá más de una vez!' WHERE `ID`=59052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 선물은 안 주셔도 되는데! 아, 하지만 저는 선물을 정말 좋아하니까 주셔도 될 거예요.', `FemaleText_loc4`='哦，你不必啦！哦，但我确实喜欢礼物，所以……或许……你还是送吧。', `FemaleText_loc5`='喔，你不必這樣!喔，但我的確喜歡禮物，所以也許你應該這樣。', `FemaleText_loc7`='¡Oh, no tenías por qué! Oh, pero me encantan los regalos... quizá sí tenías por qué.' WHERE `ID`=59053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 예쁜 거나 반짝거리는 거라면 다 좋아요.', `FemaleText_loc4`='我喜欢所有漂亮的或是闪闪发光的东西。', `FemaleText_loc5`='只要是漂亮或閃亮的東西我都喜歡。', `FemaleText_loc7`='Me gusta cualquier cosa bonita o que brille.' WHERE `ID`=59054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 제 마음을 잘 아시네요. 저는 겸손한 여자라서 루비만 갖고 싶어한답니다.$B$B뭐라고요? 제가 다이아몬드를 갖고 싶다고 하는 게 아니잖아요!', `FemaleText_loc4`='哦，你了解我的。我是个谦逊的女孩，所以我只想要些红宝石。$B$B什么？我又不是跟你要钻石！', `FemaleText_loc5`='喔，你知道我的。我是個謙虛的女孩，所以我只會要求紅寶石。$B$B什麼?我又不是在要求鑽石!', `FemaleText_loc7`='Oh, ya sabes que soy una chica humilde, así que solo pediría rubíes.$B$B¿Qué? ¡Ni que estuviera pidiendo diamantes!' WHERE `ID`=59055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 요즘 들어 화주 연어가 너무 먹고 싶어요.', `FemaleText_loc4`='好吧，最近我特别想吃焰灵鲑鱼。', `FemaleText_loc5`='最近我一直很想要吃火靈鮭魚。', `FemaleText_loc7`='Bueno, últimamente he tenido ganas de comer salmón de espíritu de fuego.' WHERE `ID`=59056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네에겐 거짓말하지 않겠네. 나는 이 네 바람의 계곡에서 가장 권력자라네. 주민들 모두 내게 값진 선물을 보내주지.', `MaleText_loc4`='我可没骗你哦，$n。我是这谷里数一数二的大人物。大多数人都会送我非常贵重的礼物。', `MaleText_loc5`='我不會騙你，$n。我是這峽谷中最有權勢的人之一。大部分的人會送我珍貴的禮物。', `MaleText_loc7`='Bueno, no te voy a engañar, $n. Soy uno de los hombres más poderosos del Valle. Casi todo el mundo me envía regalos de gran valor.' WHERE `ID`=59057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 가지만 말해주겠네, $n. 나는 옥을 좋아한다네. 하지만 제일 좋아하지는 않네. 모두 나한테 선물로 옥만 줘서 말이야!', `MaleText_loc4`='我要告诉你一件事，$n。我喜欢玉石，但那不是我的最爱。所有人都给我玉石，老是这样！', `MaleText_loc5`='我要告訴你一件事，$n。我喜歡玉，但那不是我的最愛。大家都一直把玉送給我!', `MaleText_loc7`='Voy a serte sincero, $n. Me gusta el jade, pero no es mi favorito. ¡Siempre me lo regala todo el mundo!' WHERE `ID`=59058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고 보니 요새 숯불로 구운 호랑이 스테이크가 너무 먹고 싶더군! 계곡에는 호랑이가 그리 많지 않으니 그 요리를 만들기도 어렵다네.', `MaleText_loc4`='既然你提到了，我想吃碳烤虎肉排都想了好久了！我们谷里并没有多少老虎，所以这盘菜不是那么好搞的哦。', `MaleText_loc5`='既然你提起了，我想吃火烤老虎肉排已經一段時間了!我們峽谷中沒有很多老虎，所以這道菜很難找。', `MaleText_loc7`='Ahora que lo dices, ¡llevo mucho tiempo con ganas de comer filete de tigre a la brasa! No tenemos muchos tigres por el valle, así que es un plato difícil de encontrar.' WHERE `ID`=59059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닐세, 나 같이 늙은 노인네에겐 아무것도 필요 없다네. 하지만 내 아들은... 푸른 깃털을 수집하는 걸 좋아했지...', `MaleText_loc4`='不，像我这么一个老头已不需要任何东西了。但我的儿子……他现在喜欢收集蓝色羽毛……', `MaleText_loc5`='不，像我這樣的老人不需要任何東西。但是我兒子...他喜歡收集藍羽...', `MaleText_loc7`='No, un viejo como yo no necesita nada. Pero mi hijo... Le encantaba coleccionar plumas azules...' WHERE `ID`=59060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아들이 푸른 깃털을 찾으면, 엄마가 뽀뽀해주는 거라고 말하곤 했다네. 하늘 위에서 말이지.$B$B<코끝이 너무 찡해서 잠시 말을 멈추는 늙은 힐포우>', `MaleText_loc4`='每当我的儿子找到一根蓝色羽毛时，常会说那是他在天国的妈妈，给他的一个吻。$B$B<老农山掌停顿住，因为哽噎无法继续。>', `MaleText_loc5`='當我的兒子發現一根藍羽，他總會說那是他母親從天上給他的親吻。$B$B<老丘爪停了下來，哽咽著無法繼續。>', `MaleText_loc7`='Cuando mi hijo encontraba una pluma azul, solía decir que era un beso de parte de su madre, desde el cielo.$B$B<El viejo Zarpa Collado se detiene, demasiado emocionado para continuar.>' WHERE `ID`=59061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아내는 정말 맛있는 거북이 조림을 만들어주곤 했다네. 당연히 그 음식을 먹으면 옛날 일이 생각 날 거야.', `MaleText_loc4`='我妻子常会做一道美味的炖龟肉，那味道一定能带来美好的回忆。', `MaleText_loc5`='我老婆以前會做一道美味的燉龜肉。那道菜的滋味會勾起許多回憶。', `MaleText_loc7`='Mi mujer preparaba una tortuga estofada para chuparse los dedos. Sin duda, el sabor de ese plato me traería recuerdos.' WHERE `ID`=59062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 자연에서 온 게 좋아요.', `FemaleText_loc4`='我喜欢纯天然的东西。', `FemaleText_loc5`='我喜歡天然的東西。', `FemaleText_loc7`='Me gustan las cosas que proceden de la naturaleza.' WHERE `ID`=59063;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여자가 일을 하다 보니 배가 고프네요. 무슨 말인지 아시겠죠? 뭔가 좀 맛있는 걸 먹고 싶어요.', `FemaleText_loc4`='干我们这行的女孩常会感到饥饿，你知道吗？我真希望我有好东西吃。', `FemaleText_loc5`='像我這樣工作的女孩很容易餓，你知道嗎?真希望我有美味的食物可以吃。', `FemaleText_loc7`='A una chica que trabaja como yo se le despierta mucha hambre, ¿sabes? Ojalá tuviera algo delicioso para comer.' WHERE `ID`=59064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽃도 좋긴 한데, 제가 가장 좋아하는 건 아니에요.', `FemaleText_loc4`='花是很美，但那不是我的最爱。', `FemaleText_loc5`='鮮花很好，但它們不是我的最愛。', `FemaleText_loc7`='Las flores están bien, pero no son mi elemento favorito.' WHERE `ID`=59065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 새를 무서워해요! 깃털이 예쁘기는 하지만, 제가 좋아하는 건 아니랍니다.', `FemaleText_loc4`='我害怕鸟！它们的羽毛的确很艳丽，但那不是我的最爱。', `FemaleText_loc5`='我很怕鳥!他們的羽毛很漂亮，但他們不是我的最愛。', `FemaleText_loc7`='¡Me dan miedo los pájaros! Sus plumas pueden ser muy bonitas, pero no son mi elemento favorito.' WHERE `ID`=59066;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원꽃 물고기 드셔 보셨나요? 제가 가장 좋아하는 요리랍니다.', `FemaleText_loc4`='你有没有吃过锦绣鱼？那是我的最爱。', `FemaleText_loc5`='你有吃過恆春魚嗎?那是我最愛的食物。', `FemaleText_loc7`='¿Has probado alguna vez el pescado de Flor Eterna? Es mi comida favorita.' WHERE `ID`=59067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 너무 예쁘네요. 감사합니다!', `FemaleText_loc4`='这真是太可爱了，谢谢你！', `FemaleText_loc5`='這真是可愛，謝謝你!', `FemaleText_loc7`='¡Es maravilloso, gracias!' WHERE `ID`=59068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병들이 전투에 참여할 준비가 되었는지 한번 확인해라. 아마 실전 기술을 더 익혀야 할 것이다.', `MaleText_loc4`='看看这些新兵能否接受挑战。他们需要在战斗之前先积累些经验。', `MaleText_loc5`='看看這群新兵是否能接受挑戰。他們需要學學進階戰鬥。', `MaleText_loc7`='Comprueba si los nuevos reclutas quieren un desafío. Podrían recibir una lección de combate avanzado.' WHERE `ID`=59069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 음... 감사해요... 이러지 않으셔도 되는데...!', `FemaleText_loc4`='哦，为什么……谢谢你……你没必要……！', `FemaleText_loc5`='喔，唉呀...謝謝你...你不必這樣的...!', `FemaleText_loc7`='¡Oh, vaya... gracias... no tenías por qué...!' WHERE `ID`=59070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠식 볶음 요리다! 고맙다 대장!', `MaleText_loc4`='猢狲小炒！谢谢你老大！', `MaleText_loc5`='猴人快炒!謝了老闆!', `MaleText_loc7`='¡Revuelto! ¡Gracias, $gjefe:jefa;!' WHERE `ID`=59071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 치 치 배고팠다. 고마워!', `MaleText_loc4`='哦，吱吱饿了。多谢！', `MaleText_loc5`='喔喔，奇奇餓了。謝啦!', `MaleText_loc7`='Ooh, Chee Chee tiene mucha hambre. ¡Gracias!' WHERE `ID`=59072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 예뻐 예뻐! 너무 파랗고... 너무 부드럽고... 고마워!', `MaleText_loc4`='哦，太美了，太美了！那么蓝……那么软……谢谢！', `MaleText_loc5`='喔喔，相當漂亮!多麼藍...多麼軟...謝啦!', `MaleText_loc7`='¡Ooh, bonito, bonito! ¡Qué azul... qué suave... gracias!' WHERE `ID`=59073;
