UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 몰래 도와주시는 분이 틀림없군요! 뭐, 이젠 정체가 드러났군요. 어쨌든 감사합니다!', `MaleText_loc4`='你一定是我的神秘崇拜者！好吧，现在没那么神秘了。多谢！', `MaleText_loc5`='你一定是我的秘密仰慕者!好吧，現在不那麼秘密了。謝啦!', `MaleText_loc7`='¡Tú debes de ser mi $gadmirador secreto:admiradora secreta;! Bueno, ya no tan $gsecreto:secreta;... ¡Gracias!' WHERE `ID`=59076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='습지대 백합을 찾아냈단 말씀이십니까? 제가 가장 좋아하는 꽃입니다. 감사합니다!', `MaleText_loc4`='你找到了泽地百合？这些是我的最爱。谢谢你！', `MaleText_loc5`='你找到一朵溼地百合?這些是我的最愛，謝啦!', `MaleText_loc7`='¿Has encontrado un lirio de marisma? Son mis favoritos. ¡Gracias!' WHERE `ID`=59077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 요리 저 주시는 겁니까? 이야, 감사합니다!', `MaleText_loc4`='这烤肉是给我的？哇，谢谢！', `MaleText_loc5`='這烤肉是給我的嗎?喔，真感謝!', `MaleText_loc7`='¿Este asado es para mí? ¡Vaya, gracias!' WHERE `ID`=59078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제때에 가져오셨군요. 슬슬 배가 고파 오고 있었습니다.', `MaleText_loc4`='来的正是时候，我刚好感到饿了。', `MaleText_loc5`='來得好。我正好肚子餓了。', `MaleText_loc7`='Justo a tiempo. Empezaba a tener hambre.' WHERE `ID`=59079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 쌍둥이 생선 구이를 직접 만드셨어요?', `FemaleText_loc4`='这份鸳鸯鱼拼盘是你做的？', `FemaleText_loc5`='這道雙魚拼盤是你自己做的嗎?', `FemaleText_loc7`='¿Has hecho tú $gmismo:misma; esta fuente de peces gemelos?' WHERE `ID`=59080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 이 쌍둥이 생선 구이 맛있어 보이네요. 고마워요!', `FemaleText_loc4`='我的老天，这份鸳鸯鱼拼盘闻着太诱人了。谢谢你！', `FemaleText_loc5`='喔，我的天，這道雙魚拼盤聞起來真美味，謝啦!', `FemaleText_loc7`='Oh, vaya, esta fuente de peces gemelos huele estupendamente. ¡Gracias!' WHERE `ID`=59081;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호젠의 싸움 솜씨가 얼마나 좋은지 한번 보자고요.', `FemaleText_loc4`='让我们瞧瞧猢狲准备在战斗中弄什么鬼吧。', `FemaleText_loc5`='讓我們看看猴人在戰鬥中還有什麼花招。', `FemaleText_loc7`='Veamos lo que nos tienen preparado los hozen.' WHERE `ID`=59082;
