UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 정말 예쁜 고양이네요. 제게 주셔서 정말 고마워요.', `FemaleText_loc4`='真是一只漂亮的小猫，$n。谢谢你把它送给我。', `FemaleText_loc5`='這真是一隻漂亮的貓，$n。謝謝你把它送我。', `FemaleText_loc7`='Es un gato precioso, $n. Gracias por regalármelo.' WHERE `ID`=59084;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 이거 제게 주시는 거예요? 어떻게 감사해야 할지 모르겠네요!', `FemaleText_loc4`='哇，你要把它送给我？我都不知道该怎么感谢你了！', `FemaleText_loc5`='哦喔喔喔，你要把那送我?我不知道該如何謝你!', `FemaleText_loc7`='Oh, vaya, ¿me lo regalas? ¡No sé cómo puedo agradecértelo!' WHERE `ID`=59085;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제게 선물을 주시는 거예요? 아, 정말. 이러지 않으셔도 되는데!', `FemaleText_loc4`='你要送我一个礼物？哈哈谢谢啦，你太客气了！', `FemaleText_loc5`='你要給我個禮物?噢謝了，你不必這樣!', `FemaleText_loc7`='¿Un regalo para mí? ¡Oh, vaya, no tenías por qué!' WHERE `ID`=59086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭡니까? 아. 뭐든지 간에... 정말 좋군요. *딸꾹*', `MaleText_loc4`='这是什么？哦，管它呢，真是好东西……嗝！', `MaleText_loc5`='這是什麼?喔，管它是什麼都很棒...嗝!', `MaleText_loc7`='¿Qué esh eshto? Oh, shea lo que shea, me gushta... ¡hip!' WHERE `ID`=59087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, $n 님! 소용돌이치는 안갯국을 제게 가져오신 건가요? 제가 이 요리를 얼마나 좋아하는지 아신 거예요?', `FemaleText_loc4`='为什么$n！你给我带了一些迷雾汤？你不知道我爱死这东西了吗？', `FemaleText_loc5`='唉呀$n!你真的拿了繚繞薄霧湯要給我?你知道我愛死這道菜了?', `FemaleText_loc7`='¡Vaya, $n! ¿Me has traído sopa de niebla espiral? ¿Sabías que me encanta?' WHERE `ID`=59088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 정말 숨이 막힐 정도로 예쁜 꽃이네요. 이 꽃의 꽃말이 행운이란 거 아시나요?', `FemaleText_loc4`='哦，多么令人惊艳的花啊。你知道这些代表了幸运吗？', `FemaleText_loc5`='喔，多麼令人讚嘆的花朵啊。你知道這花代表著幸運嗎?', `FemaleText_loc7`='Oh, vaya flor más excepcional. ¿Sabes que dicen que da suerte?' WHERE `ID`=59089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오 이런, 제게 주실 게 있다고요? 너무 고마워서 어쩌죠?', `FemaleText_loc4`='我的老天，你要送我东西？我该如何感谢你啊？', `FemaleText_loc5`='喔，我的天，你要送我東西?我要怎麼謝謝你?', `FemaleText_loc7`='Anda, ¿me traes un regalo? Vaya, ¿cómo podré agradecértelo?' WHERE `ID`=59090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 정말 멋져요. 볼품없는 제게 이렇게 예쁜 선물을 주시다니. 감사해요!', `FemaleText_loc4`='瞧啊，你给小老太吉娜送了一个这么可爱的礼物。谢谢你！', `FemaleText_loc5`='喔，看看你，送給老吉娜這麼可愛的禮物。謝謝你!', `FemaleText_loc7`='Pero mira qué encanto, dándole a la pequeña Gina un regalo tan maravilloso... ¡Gracias!' WHERE `ID`=59091;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 화주 연어는 맛있어 보이네요. 직접 요리하신 거였으면 좋겠어요.', `FemaleText_loc4`='这个焰灵鲑鱼看起来很美味。我希望这是你亲手做的。', `FemaleText_loc5`='這個火靈鮭魚看起來真美味。我希望這是你自己做的。', `FemaleText_loc7`='Este salmón de espíritu de fuego tiene una pinta deliciosa. Espero que lo hayas hecho tú.' WHERE `ID`=59092;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 이 화주 연어를 어서 먹고 싶어서 못 참겠네요.', `FemaleText_loc4`='哦，我等不及要尝尝这个焰灵鲑鱼了。', `FemaleText_loc5`='喔喔喔，我等不及要試試這道火靈鮭魚。', `FemaleText_loc7`='Oooh, estoy deseando probar este salmón de espíritu de fuego.' WHERE `ID`=59093;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여자를 어떻게 감동시키는지 확실히 알고 계시네요! 다이아몬드는 아니지만, 어쨌든 너무 좋아요!', `FemaleText_loc4`='你为何如此懂得取悦一名女士的！虽然不是钻石，但我就是喜欢！', `FemaleText_loc5`='你真的很了解如何打動一個淑女!這不是鑽石，但我還是很喜歡。', `FemaleText_loc7`='¡Vaya, sí que sabes cómo impresionar a una dama! ¡No es un diamante, pero me encanta igualmente!' WHERE `ID`=59094;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 루비는 제 치마랑 너무 잘 어울리는 것 같아요. 안 그래요?', `FemaleText_loc4`='这颗红宝石配这身衣服真是太美了，你觉得呢？', `FemaleText_loc5`='這紅寶石搭配這禮服看起來美極了，你不覺得嗎?', `FemaleText_loc7`='Este rubí quedará precioso con mi vestido, ¿no te parece?' WHERE `ID`=59095;
