UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 맥주 있습니다!', `MaleText_loc4`='在这里酿造！', `MaleText_loc5`='這有啤酒!', `MaleText_loc7`='¡Aquí hay cerveza!' WHERE `ID`=59146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동굴에 가 있을 테니, 거기로 오세요.', `FemaleText_loc4`='朋友，我们洞穴里见。', `FemaleText_loc5`='朋友，到上頭的洞穴和我碰面吧。', `FemaleText_loc7`='Reúnete conmigo en la cueva si te parece bien.' WHERE `ID`=59147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 조구. 내일 어떤 곡식을 수확하면 되겠습니까?', `MaleText_loc4`='嘿，贾古，明天的收成会怎么样啊？', `MaleText_loc5`='嘿，酒骨，明天的作物怎麼樣?', `MaleText_loc7`='Oye, Jogu, ¿qué se dice sobre la cosecha de mañana?', `FemaleText_loc1`='안녕하세요 조구. 내일 어떤 곡식을 수확하면 될까요?', `FemaleText_loc4`='嘿，贾古，明天的收成会怎么样啊？', `FemaleText_loc5`='嘿，酒骨，明天的作物怎麼樣?', `FemaleText_loc7`='Oye, Jogu, ¿qué se dice sobre la cosecha de mañana?' WHERE `ID`=59148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으음... 머리가 어지럽군요... 나중에 다시 물어보십시오.', `MaleText_loc4`='呃……我脑袋晕乎乎的……一会再说吧。', `MaleText_loc5`='呃呃呃...我的腦袋迷迷糊糊的...晚點再來。', `MaleText_loc7`='Uff... me cueshta penshar ahora... vuelve másh tarde.' WHERE `ID`=59149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오!... 오오오! 느낌이 팍팍 옵니다! 당신 미래에... 거대한 녹색 양배추가 보입니다.', `MaleText_loc4`='哦……哦！我感到刺痛无比！我看见……巨大的绿色卷心菜……在你的未来里。', `MaleText_loc5`='喔喔喔...喔喔喔喔!我感覺到刺刺的!我在你的未來看見...巨大的綠色捲心菜。', `MaleText_loc7`='¡Uuu... uuu! ¡Me eshtá entrando un coshquilleo! Veo... enormesh repollosh verdesh en tu futuro.' WHERE `ID`=59150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츄릅아삭 당근이라고 들어보셨습니까? 내일이 가장 츄릅아삭할 겁니다.', `MaleText_loc4`='你听说过爽脆胡萝卜吗？它们明天会变得更加爽脆。', `MaleText_loc5`='你有聽過脆嫩多汁胡蘿蔔嗎?明天將是它們最多汁的時候。', `MaleText_loc7`='¿Shabesh lo que esh una zanahoria Jugoasaz? Mañana estarán másh jugoshash que nunca.' WHERE `ID`=59151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 파를 싫어한다고 말씀드린 적 있습니까? 전 진짜 싫어합니다!$B$B<우렁차게 트림하는 조구>$B$B제게는 안 좋은 일이지만, 내일쯤이면 파가 아주 잘 익었을 겁니다.', `MaleText_loc4`='我有没有告诉过你我讨厌葱？我讨厌它们！$B$B<贾古打了个响嗝儿。>$B$B可不幸的是，明天将是它们的生长旺季。', `MaleText_loc5`='我有告訴過你我討厭青蔥嗎?討厭死了!$B$B<酒骨大聲地打了個嗝。>$B$B對我來說很不幸的是，它們明天開始就進入旺季。', `MaleText_loc7`='¿Te he dicho alguna vez que odio lash cebolletash? ¡Lash odio!$b$b<Jogu eructa sonoramente.>$b$bPor deshgracia para mí, mañana eshtarán en temporada alta.' WHERE `ID`=59152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박입니다! 아주 거대하고, 웅장한 호박이 될 겁니다!', `MaleText_loc4`='南瓜！会长出巨大、无比大的南瓜！', `MaleText_loc5`='南瓜!那將會是個龐大、巨大的南瓜!', `MaleText_loc7`='¡Calabazash! ¡Sherán calabazash enormesh, giganteshcash!' WHERE `ID`=59153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부추 하나에 뛰어들어도 두 개를 뽑겠군요.', `MaleText_loc4`='种下一份韭花，你也许能收获两份。', `MaleText_loc5`='買個紅花蔥，你也許會有額外收穫。', `MaleText_loc7`='Planta un puerro y a lo mejor conshiguesh dosh.' WHERE `ID`=59154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 미래에 분홍색 순무가 보입니다.', `MaleText_loc4`='我在你的未来里看到了粉色芜菁。', `MaleText_loc5`='我在你的未來中看到許多粉紅菜頭。', `MaleText_loc7`='Veo nabash roshash en tu futuro.' WHERE `ID`=59155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하얀색 순무 밭입니다. 싱싱하고 매콤하군요!', `MaleText_loc4`='地里长满了白色芜菁。脆爽劲辣！', `MaleText_loc5`='滿滿的白菜頭。生鮮且辛辣!', `MaleText_loc7`='Camposh de nabash blancash. ¡Crudash y picantesh!' WHERE `ID`=59156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 딸기를 심어야 하느냐고요? 물론 요술딸기를 심으셔야죠!', `MaleText_loc4`='你该种植哪种浆果？当然是女巫浆果啦！', `MaleText_loc5`='你該種哪種莓?當然是巫莓啊!', `MaleText_loc7`='¿Que qué bayash hay que plantar? ¡Morujash, evidentemente!' WHERE `ID`=59157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 박의 색깔이 우윳빛 옥색으로 물드는군요. 내일이 이 채소를 기르기에 완벽한 날이 되겠군요...', `MaleText_loc4`='碧玉瓜有着温润如玉的色泽。我想……明天会是种植这种蔬菜的好日子。', `MaleText_loc5`='翠玉瓜有著乳白翠玉的顏色。明天將會有種植這種蔬菜的完美條件...我覺得啦。', `MaleText_loc7`='Losh calabacinesh de jade son del color del jade claro. Mañana lash condicionesh para cultivarlosh serán perfectash... en mi opinión.' WHERE `ID`=59158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일 년 중 이맘때는 줄무늬 멜론이 아주 달콤하죠! 줄무늬 멜론 씨앗을 심으십시오. 그러면 다음 날 수확할 수 있을 겁니다.', `MaleText_loc4`='每年一到这个时节，菜瓜就变得多汁爽口！把种子撒在地里，天亮就能收获果实。', `MaleText_loc5`='條紋甜瓜在每年這時節都相當多汁!把一些種子投入土裡，你隔天就會有收穫。', `MaleText_loc7`='¡Losh melonesh a rayash eshtán muy jugoshosh en eshta época del año! Planta semillash en la tierra y mañana tendrásh la cosecha.' WHERE `ID`=59159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기 찾고 계십니까? 여기 아주 많습니다.$b$b지금 굽고 있는 것 말입니다.', `MaleText_loc4`='你想吃肉？我这里有很多。$b$b我的意思是，在我的烤架上。', `MaleText_loc5`='在找肉嗎?我這裡就有許多肉。$b$b我的意思是在我的烤肉架上。', `MaleText_loc7`='¿Buscas carne? Yo tengo mucha.$b$bEn la parrilla, quiero decir.' WHERE `ID`=59160;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 명상하는 동안 저들을 막아 주세요. 곧 우리가 구하는 답을 찾을 겁니다.', `FemaleText_loc4`='在我冥想时挡住那些精怪。我们很快就能找到答案了。', `FemaleText_loc5`='在我冥想時擋住那些生物。很快我們就會找到想要的答案。', `FemaleText_loc7`='Ocúpate de esas criaturas mientras medito. Pronto tendremos nuestras respuestas.' WHERE `ID`=59161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<학은 말을 하지 않지만, 그의 목소리가 당신의 마음속에 울려 퍼집니다.>$B$B가라... 너무 늦기 전에...$B$B이제 다... 틀렸다.', `MaleText_loc4`='<那鹤并没有开口，可他的话语却充满你的脑海。>$B$B趁还来得及……快走……$B$B一切都已……无可挽回。', `MaleText_loc5`='<這隻鶴並沒有說話，但是他的話語充滿你的心智。>$B$B去吧...趁你還能夠的時候...$b$b已經...沒希望了。', `MaleText_loc7`='<La grulla no habla, sino que sus palabras llenan tu mente.>$B$BVete... mientras puedas...$B$BTodo está... perdido.' WHERE `ID`=59162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<손을 뻗어 츠지를 만집니다.>', `MaleText_loc4`='<伸手碰触赤精。>', `MaleText_loc5`='<伸手出去碰觸赤吉。>', `MaleText_loc7`='<Extiende la mano para tocar a Chi-Ji.>', `FemaleText_loc1`='<손을 뻗어 츠지를 만집니다.>', `FemaleText_loc4`='<伸手碰触赤精。>', `FemaleText_loc5`='<伸手出去碰觸赤吉。>', `FemaleText_loc7`='<Extiende la mano para tocar a Chi-Ji.>' WHERE `ID`=59163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제단에 있는 종을 흔들었습니다. 질문을 하거나 소원을 빌어보십시오!', `MaleText_loc4`='你摇响了神龛上的铃铛。你现在可以向它提问，许愿也行！', `MaleText_loc5`='你拉一下神殿上的鐘。問它個問題或許個願!', `MaleText_loc7`='Tañes la campana del santuario. ¡Formula una pregunta o pide un deseo!' WHERE `ID`=59166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치는 서쪽의 계단식 밭에서 일하는 양치기입니다.', `MaleText_loc4`='吱吱是位猢狲牧羊人，就在西边的梯田上工作。', `MaleText_loc5`='奇奇是在西邊臺地上工作的猴人牧羊人。', `MaleText_loc7`='Chee Chee es un pastor hozen que trabaja en el bancal al oeste.' WHERE `ID`=59167;
