UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼와 저는 어떤 관계입니까?', `MaleText_loc4`='我和阿烁的关系怎么样？', `MaleText_loc5`='我和阿秀的關係如何?', `MaleText_loc7`='¿Qué relación tengo con Sho?', `FemaleText_loc1`='쇼와 저는 어떤 관계인가요?', `FemaleText_loc4`='我和阿烁的关系怎么样？', `FemaleText_loc5`='我和阿秀的關係如何?', `FemaleText_loc7`='¿Qué relación tengo con Sho?' WHERE `ID`=59185;
