UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람이 물고기에게 소원을 빌때는...', `MaleText_loc4`='当一个人有求于一条鱼的时候……', `MaleText_loc5`='當人向魚請求幫忙...', `MaleText_loc7`='Cuando uno pide a un pez un favor...' WHERE `ID`=59187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 속마음을 판독하기 어렵도다...', `MaleText_loc4`='往往只是因为他想要找一条肥硕的鱼……', `MaleText_loc5`='你很難猜透他真正的意圖...', `MaleText_loc7`='... es difícil medir su candor...' WHERE `ID`=59188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대부분 사리사욕에 눈이 멀어...', `MaleText_loc4`='来端上餐桌……', `MaleText_loc5`='他總是在找氣派的碟子...', `MaleText_loc7`='... a menudo busca para su asador...' WHERE `ID`=59189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안방에서 연회를 열고자 한다네.', `MaleText_loc4`='呜呼，人为刀俎，我为鱼肉！', `MaleText_loc5`='這樣才好端上桌。', `MaleText_loc7`='... un plato de delicioso sabor.' WHERE `ID`=59190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치, 제 농장 일 좀 도와주시겠습니까?', `MaleText_loc4`='嘿，吱吱，愿意到我的农场来做帮手吗？', `MaleText_loc5`='嘿，奇奇，你想要當我的雇農嗎?', `MaleText_loc7`='Oye, Chee Chee, ¿te gustaría ser mi jornalero?', `FemaleText_loc1`='치 치, 제 농장 일 좀 도와주시겠어요?', `FemaleText_loc4`='嘿，吱吱，愿意到我的农场来做帮手吗？', `FemaleText_loc5`='嘿，奇奇，你想要當我的雇農嗎?', `FemaleText_loc7`='Oye, Chee Chee, ¿te gustaría ser mi jornalero?' WHERE `ID`=59192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 엘라. 농부 윤의 밭일 좀 도와주시겠습니까?', `MaleText_loc4`='嘿，艾拉，愿意加入我和农夫老愚的农场吗？', `MaleText_loc5`='嗨，艾拉，妳想到農夫尹的農場加入我們一起工作嗎?', `MaleText_loc7`='Hola Ella, ¿te gustaría unirte al granjero Yoon y a mí en su granja?', `FemaleText_loc1`='안녕하세요, 엘라. 윤의 밭일 좀 도와주시겠어요?', `FemaleText_loc4`='嘿，艾拉，愿意加入我和农夫老愚的农场吗？', `FemaleText_loc5`='嗨，艾拉，妳想到農夫尹的農場加入我們一起工作嗎?', `FemaleText_loc7`='Hola Ella, ¿te gustaría unirte al granjero Yoon y a mí en su granja?' WHERE `ID`=59193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피시, 제 농장 일을 도와주시면 어떻겠습니까?', `MaleText_loc4`='嘿，玉儿，愿意做我农场的合伙人吗？', `MaleText_loc5`='嘿，小魚，當我農場的夥伴如何?', `MaleText_loc7`='Oye, Pez, ¿qué te parecería ser mi socia en la granja?', `FemaleText_loc1`='피시, 제 농장 일을 도와주시면 어떨까요?', `FemaleText_loc4`='嘿，玉儿，愿意做我农场的合伙人吗？', `FemaleText_loc5`='嘿，小魚，當我農場的夥伴如何?', `FemaleText_loc7`='Oye, Pez, ¿qué te parecería ser mi socia en la granja?' WHERE `ID`=59194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 펑. 윤과 제가 농장 일을 하는 데 당신의 도움이 정말 필요합니다.', `MaleText_loc4`='你好，农夫老方。我和农夫老愚的农场真的很需要你。', `MaleText_loc5`='你好啊，農夫老豐。農夫尹和我真的需要你到我們的農場來。', `MaleText_loc7`='Qué hay, granjero Fung. El granjero Yoon y yo te necesitamos en nuestra granja.', `FemaleText_loc1`='안녕하십니까, 펑. 윤과 제가 농장 일을 하는 데 당신의 도움이 정말 필요해요.', `FemaleText_loc4`='你好，农夫老方。我和农夫老愚的农场真的很需要你。', `FemaleText_loc5`='你好啊，農夫老豐。農夫尹和我真的需要你到我們的農場來。', `FemaleText_loc7`='Qué hay, granjero Fung. El granjero Yoon y yo te necesitamos en nuestra granja.' WHERE `ID`=59195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나, 우리 농장 일 좀 도와주시겠습니까?', `MaleText_loc4`='吉娜，愿意帮我们运营农场吗？', `MaleText_loc5`='吉娜，妳想要怎麼幫我們管理這農場?', `MaleText_loc7`='Gina, ¿qué te parecería ayudarnos a llevar la granja?', `FemaleText_loc1`='지나, 우리 농장 일 좀 도와주시겠어요?', `FemaleText_loc4`='吉娜，愿意帮我们运营农场吗？', `FemaleText_loc5`='吉娜，妳想要怎麼幫我們管理這農場?', `FemaleText_loc7`='Gina, ¿qué te parecería ayudarnos a llevar la granja?' WHERE `ID`=59196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하오한 씨, 태양노래 농장 일 좀 도와주시겠습니까?', `MaleText_loc4`='泥爪先生，您愿意帮我们打理日歌农场吗？', `MaleText_loc5`='泥爪先生，你願意到日歌農莊幫我忙嗎?', `MaleText_loc7`='Sr. Zarpa Fangosa, ¿podrías echarnos una mano en el Rancho Cantosol?', `FemaleText_loc1`='하오한 씨, 태양노래 농장 일 좀 도와주시겠어요?', `FemaleText_loc4`='泥爪先生，您愿意帮我们打理日歌农场吗？', `FemaleText_loc5`='泥爪先生，你願意到日歌農莊幫我忙嗎?', `FemaleText_loc7`='Sr. Zarpa Fangosa, ¿podrías echarnos una mano en el Rancho Cantosol?' WHERE `ID`=59197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 조구. 태양노래 농장에 있는 연못 안으로 가는 게 어떻겠습니까?', `MaleText_loc4`='嘿，贾古，你愿不愿意搬到日歌农场的池塘去？', `MaleText_loc5`='嘿，酒骨，你想不想搬到日歌農莊中的池塘裡?', `MaleText_loc7`='Oye, Jogu, ¿qué te parecería trasladarte al estanque del Rancho Cantosol?', `FemaleText_loc1`='안녕하세요, 조구. 태양노래 농장에 있는 연못 안으로 가는 게 어떻겠어요?', `FemaleText_loc4`='嘿，贾古，你愿不愿意搬到日歌农场的池塘去？', `FemaleText_loc5`='嘿，酒骨，你想不想搬到日歌農莊中的池塘裡?', `FemaleText_loc7`='Oye, Jogu, ¿qué te parecería trasladarte al estanque del Rancho Cantosol?' WHERE `ID`=59198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 힐포우. 제 농장 일을 도와주시겠습니까?', `MaleText_loc4`='你好，老农山掌。到我的农场来和我作伴如何啊？', `MaleText_loc5`='你好啊，老丘爪。你想不想要在我的農場陪我啊?', `MaleText_loc7`='Qué hay, viejo Zarpa Collado. ¿Qué te parecería acompañarme en mi granja?', `FemaleText_loc1`='안녕하세요, 힐포우. 제 농장 일을 도와주시겠어요?', `FemaleText_loc4`='你好，老农山掌。到我的农场来和我作伴如何啊？', `FemaleText_loc5`='你好，老丘爪。你想不想要在我的農場陪我啊?', `FemaleText_loc7`='Qué hay, viejo Zarpa Collado. ¿Qué te parecería acompañarme en mi granja?' WHERE `ID`=59199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 쇼. 한숨 돌리고 나서 잠깐 제 농장을 보러 와주십시오.', `MaleText_loc4`='嘿，阿烁。休息一下，来我的农场帮我看会庄稼吧。', `MaleText_loc5`='嘿，阿秀，休息休息，來幫我看顧一下農場吧。', `MaleText_loc7`='Oye, Sho, tómate un descanso y ven a ver mi granja un rato.', `FemaleText_loc1`='안녕하세요, 쇼. 한숨 돌리고 나서 잠깐 제 농장을 보러 와주세요.', `FemaleText_loc4`='嘿，阿烁。休息一下，来我的农场帮我看会庄稼吧。', `FemaleText_loc5`='嘿，阿秀，休息休息順便幫忙看顧一下我的農場。', `FemaleText_loc7`='Oye, Sho, tómate un descanso y ven a ver mi granja un rato.' WHERE `ID`=59200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, 티나. 농부 윤이 농장 일을 도울 이를 찾고 있습니다. 함께 도와주시겠습니까...?', `MaleText_loc4`='嘿，迪娜，我听说农夫老愚的农场需要点帮助。你能否……？', `MaleText_loc5`='嘿，蒂娜，我聽說農夫尹的農場需要幫忙。妳願意...?', `MaleText_loc7`='Oye, Tina, he oído que el granjero Yoon necesita ayuda en su granja. ¿Te importaría...?', `FemaleText_loc1`='안녕하세요, 티나. 농부 윤이 농장 일을 도울 이를 찾고 있어요. 함께 도와주시겠어요...?', `FemaleText_loc4`='嘿，迪娜，我听说农夫老愚的农场需要点帮助。你能否……？', `FemaleText_loc5`='嘿，蒂娜，我聽說農夫尹的農場需要幫忙。妳願意...?', `FemaleText_loc7`='Oye, Tina, he oído que el granjero Yoon necesita ayuda en su granja. ¿Te importaría...?' WHERE `ID`=59201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 대장! 치 치 할 일 끝난 다음 곧 그리로 간다.', `MaleText_loc4`='好的，老板！吱吱还有事要做，过会就去。', `MaleText_loc5`='是的，老闆!奇奇有些事要做，然後他就會馬上過去。', `MaleText_loc7`='¡Vale, $gjefe:jefa;! Chee Chee tiene kosas que hacer, luego vuelve pronto.' WHERE `ID`=59202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이죠. 제가 약간 도와드릴 수 있을 것 같아요! 잠시 뒤에 거기서 만나요.', `FemaleText_loc4`='没问题，我觉得我能帮上点忙！我一会儿去那找你。', `FemaleText_loc5`='當然，我想我可以幫上一點忙。等會那裡見。', `FemaleText_loc7`='¡Por supuesto, supongo que podría ayudar un poco! Nos vemos allí en un rato.' WHERE `ID`=59203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠는 도움이 필요한 이웃이 있으면 도와주라고 하셨어요! 다른 일 좀 보고 나서 바로 갈게요!', `FemaleText_loc4`='我爸爸经常说助人为快乐之本！我手头还有些事要处理，回头一忙完就去找你！', `FemaleText_loc5`='我老爸總是說要幫助需要幫忙的鄰居!我再處理一些事情，然後馬上過去!', `FemaleText_loc7`='Mi papá siempre me decía que había que ayudar a un vecino necesitado. ¡Tengo que ocuparme de un par de cosas, pero iré en un periquete!' WHERE `ID`=59204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 물어보시나 궁금해하고 있었습니다. 물론이죠. 다른 일 좀 잠깐 보고 나서 바로 가겠습니다.', `MaleText_loc4`='我还在想你什么时候会问我呢。没问题，等我料理完这边的事后，我马上过去。', `MaleText_loc5`='我正在想你什麼時候會問咧。沒問題。讓我處理一些事情，然後我會馬上過去。', `MaleText_loc7`='Me preguntaba cuándo me lo ibas a pedir. Por supuesto. Deja que me ocupe de un par de cosas y voy enseguida.' WHERE `ID`=59205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 알겠어요. 가끔 밭일을 할 수도 있죠 뭐. 당신이니까 도와드리는 거예요. 아셨죠? 그리고 음... 제가 아무래도 윤을 너무 좋아하나봐요...', `FemaleText_loc4`='那么好吧，我想我时不时的可以去农场帮忙。我只是看在你的面子上，你懂吗？好吧……我想这回我也给了老愚先生一个大大的面子……', `FemaleText_loc5`='好吧，我想我可以時不時過去農場那邊。我是為了你才這麼做，聽到了嗎?還有...我想我迷上尹先生了。', `FemaleText_loc7`='De lujo... supongo que podría pegarme un salto hasta la granja de vez en cuando. Esto solo lo hago por ti, ¿lo pillas? Y bueno... Supongo que me ha caído simpático el Sr. Yoon...' WHERE `ID`=59206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니까? 저 연못이 전부 제 거라고요? 바로 가겠습니다!', `MaleText_loc4`='真的？整个池塘，都是我的？我马上就去！', `MaleText_loc5`='真的嗎?整個池塘都是我的?我會馬上過去!', `MaleText_loc7`='¿En serio? ¿Todo ese estanque solo para mí? ¡Ahora mismo voy!' WHERE `ID`=59207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일은 뭉뭉에게 잠깐 맡기고 윤의 농장을 한번 보러 가야겠네. 그 친구가 네 바람의 계곡 전 지역에서 가장 훌륭한 토양을 일궈냈으니까 말일세! 일단 옷부터 좀 챙겨 입어야겠군.', `MaleText_loc4`='我想我可以把这里交给蒙蒙看管一会儿，我去老愚那边转转。他的确有着整个谷里最肥沃的土地！先让我把手头的事情理理顺。', `MaleText_loc5`='我想我可以把事情交給芒芒一下子然後去尹的田裡看看。他那裡的確有峽谷中最好的土壤!先讓我把我的東西整理好。', `MaleText_loc7`='Supongo que podría dejar que Mung-Mung se encargue de todo durante un rato y echarle un vistazo a la granja de Yoon. ¡Tiene la mejor tierra de todo el valle! Espera a que ponga todo en orden primero.' WHERE `ID`=59208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 내가 잠깐 들러도 닭들은 신경 안 쓸 걸세. 나중에 그곳에서 만나세나.', `MaleText_loc4`='我想我的小鸡是不会介意我出去串会儿门的。我一会就去找你。', `MaleText_loc5`='我想雞群不會在意我過去拜訪一下。待會那裡見。', `MaleText_loc7`='Bueno, supongo que a las gallinas no les importará que les haga una visitilla. Nos vemos allí luego.' WHERE `ID`=59209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='태양노래 농장에 제 도움이 필요하다고요? 저는 장비를 좀 챙길게요. 저와 그곳에서 만나요.', `FemaleText_loc4`='日歌农场需要我帮忙吗？让我去拿装备，我会去那里找你。', `FemaleText_loc5`='日歌農莊需要我的幫助?讓我整理一下裝備，我們在那裡見。', `FemaleText_loc7`='¿Que el Rancho Cantosol necesita mi ayuda? Voy a recoger mi equipo y nos vemos allí.' WHERE `ID`=59210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 말했던 때가 됐군요! 농부 윤이 언제쯤 저를 알아볼까 궁금해하는 중이었어요. 당신 먼저 가세요. 제가 곧 그리로 갈게요.', `FemaleText_loc4`='正好是你要求的时间！我正在考虑农夫老愚什么时候才会想到我。你先去吧，我很快就到。', `FemaleText_loc5`='也該是你這麼問的時候了!我原本在想農夫尹到底什麼時候會注意到我。你先走，我馬上就到。', `FemaleText_loc7`='¡Ya era hora de que me lo pidieras! Me preguntaba cuándo se daría cuenta el granjero Yoon de que existo. Adelántate tú, que yo voy en un momento.' WHERE `ID`=59211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 대장. 내가 생각해봤는데... 대장 치 치한테 식구같이 정말 잘해줬다. 그래서 내가 농장에 양을 좀 보내주고 싶어. 양들 벌써 농장에서 기다리고 있을 거다. 치 치가 준 양 잘 돌봐줘, 응?', `MaleText_loc4`='嘿，老板，我一直在想。你对吱吱真好，所以我想送只羊给你。羊已经准备好了，你会好好照顾吱吱的羊，对吗？', `MaleText_loc5`='嘿，老大，我一直在想。你一直都對奇奇很好，所以我想要送一隻綿羊給你的農場。它應該已經在等你了。你要好好照顧奇奇的綿羊，好嗎?', `MaleText_loc7`='Oye, $gjefe:jefa;, yo está pensando. Tú fue muy $gbueno:buena; con Chee Chee, así que yo kiere darte una oveja para tu granja. Ya debe estar esperando. Tú kuida muy bien de ovejas de Chee Chee, ¿vale?' WHERE `ID`=59212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, 잠깐만 기다려보세요... 제가... 그러니까... 우린 이제 식구처럼 친해졌으니까... 제가 가장 좋아하는 고양이를 드릴게요. 이름은 루나예요! 당신이 농장에서 외로워하지 않았으면 해서... <흐느끼는 엘라>... 루나를 잘 돌봐주세요, 네? 조금 있다가 데리고 갈게요.', `FemaleText_loc4`='嘿，等一等……我……好吧……你是我的好友……我想把我最爱的猫咪——露娜，送给你！我不想你在农场里感到孤单寂寞……<呜咽>……一定要好好照顾她，记住了吗？我稍后会把她送过来。', `FemaleText_loc5`='嘿，等一下...我...嗯...你是一個這麼好的朋友，然後...我想給你我最愛的小貓，月神!我不希望你在農場感到寂寞還有...<啜泣>...好好照顧她，好嗎?我晚點會帶她過去。', `FemaleText_loc7`='Oye, espera un momento... yo... verás... has sido muy $gbuen amigo:buena amiga; y... ¡quiero regalarte mi gatita favorita, Luna! No quiero que te sientas $gsolo:sola; en tu granja y... <solloza>... bueno, tú cuídala mucho, ¿vale? Te la llevaré más tarde.' WHERE `ID`=59213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 당신과 저는 한 식구라고 해도 될 정도로 친해졌으니까, 진지하게 말해 드릴게요. 농장에 돼지 한두 마리 없다는 건 말도 안 되는 일이랍니다! 당신이 보고 있지 않을 때 제가 몇 마리 가져다 놓고... 짜잔! 농장에 돼지가 돌아다니는 거예요.', `FemaleText_loc4`='好吧，既然我们现在是好邻居了，我也就实话实说了。你的农场里没有一两头猪真是太不像话了！等你回头想明白了，我会带几头猪给你！你会有猪的。', `FemaleText_loc5`='既然我們成了鄰居，我可以跟你說實話。你的農場裡沒有一兩頭像樣的豬真是太不對了!我會趁你不注意帶一些過去。然後，噠啦!你有豬了。', `FemaleText_loc7`='Bueno, ahora que tú y yo somos $gvecinos:vecinas;, puedo contarte la verdad. ¡No es de recibo que no tengas un buen cerdo o dos en tu granja! Te traeré unos cuantos cuando no estés mirando y... ¡tachán! Ya tienes cerdos.' WHERE `ID`=59214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리는 한 식구가 됐으니 제가 줄 수 있는 최고의 선물을 해줘야겠군요! 제 야크 중에서 아주 멋진 놈으로 한 마리 골라 드리겠습니다! 나중에 잠깐 들러서 축사에 놓고 가겠습니다.', `MaleText_loc4`='既然我们现在是邻居了，我决定送你一个作为邻居所能送出的最好的礼物！我打算送你一头珍贵的牦牛！我一会儿就把它送到你的围栏里。', `MaleText_loc5`='既然我們現在是鄰居了，我決定要送你身為一個鄰居所能給出的最好禮物!我要從我珍貴犛牛中挑一頭犛牛給你!我晚點會過來把她留在你的圍欄裡。', `MaleText_loc7`='¡Ahora que somos vecinos, he decidido hacerte el mejor regalo que un vecino puede dar a alguien! ¡Voy a darte uno de mis preciados yaks! Me pasaré más tarde y lo dejaré en tu establo.' WHERE `ID`=59215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 당신과 저는 진짜 한 식구가 된 거예요. 그냥 같은 동네에 사는 것 정도가 아니고 말이죠. 제게 정말 많은 것을 해주셨으니, 제가 조금이라도 도움을 드려야 할 것 같아요. 다른 이들에게 조금 부탁해서 당신 농장 바로 앞에 우체통을 설치했어요. 이제는 당신도 친구들과 연락을 주고받을 수 있답니다!', `FemaleText_loc4`='我和你现在成邻居了，不光从地理角度上来讲。你为我做了很多事，我想是时候回馈你的友情了。我请人帮忙在你的农场装了一个邮箱，现在你可以通过邮箱和所有的朋友保持联系了！', `FemaleText_loc5`='你跟我，我們現在是好鄰居了，不只是地理上的涵義。你為我做了這麼多，我想該輪到我幫你一點忙。我找了一些人幫忙，在你的農場安裝了一個郵箱。現在你可以和你的所有朋友保持聯絡!', `FemaleText_loc7`='Ahora tú y yo somos muy $gbuenos vecinos:buenas vecinas;, y no hablo solo en términos geográficos. Has hecho mucho por mí, y creo que ahora me toca a mí ayudarte un poco. He pedido unos cuantos favores y he conseguido que te instalen tu propio buzón en la granja. ¡Ahora podrás mantener el contacto con todos tus amigos!' WHERE `ID`=59216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 이 마을에 처음 왔을 때는 정말 하나도 믿음이 가지 않는 친구였네만, 이제는 자랑스럽게 나와 한 식구라고 말할 수 있다네. 우정의 표시로 뭔가 좀 커다란 놈을 선물하고 싶군. 아마 벌써 자네 농장에 가 있을 걸세. 이름은 피피 양이고, 순무 먹는 것을 좋아한다네!', `MaleText_loc4`='你刚来谷里的时候，我对你还不太了解，但现在我可以自豪的管你叫邻居了。作为代表我们友情的象征，我想给你的农场送一件大礼，她可能已经在那里了。她的名字叫菲菲小姐，她喜欢吃芜菁哦！', `MaleText_loc5`='你最初來到峽谷時我不太確定是否能相信你，但現在我可以很驕傲地稱你為鄰居。做為我們友情的象徵，我想要給你的農場一個大禮物。她應該已經在那裡了。她的名字是妃妃小姐，還有她喜歡吃菜頭!', `MaleText_loc7`='No me fiaba mucho de ti cuando llegaste al valle, pero ahora puedo decir con orgullo que te considero mi $gvecino:vecina;. Como prueba de mi amistad, me gustaría darte algo importante para tu granja. Ya debe de haber llegado. ¡Se llama señorita Fifi y le encanta comer nabas!' WHERE `ID`=59217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 지금껏 정말 좋은 친구였네. 이제 우리는 한 식구가 됐으니 내 닭을 몇 마리 줘야겠군. 많지는 않지만 농장에 생기가 돌게 해줄 걸세. 곧 보내주도록 하지.', `MaleText_loc4`='知道吗，你作为我的朋友已经有些日子了。既然我们现在成了邻居，我打算送你一些小鸡。虽然不多，但他们会让你的农场显得更有生气。我一会儿把他们送过来。', `MaleText_loc5`='你知道的，你和我成為很好的朋友已經一陣子了。如今我們是鄰居，我要給你幾隻我的雞。不算厚禮，但牠們應該可以讓你的農場更有一點活力。我會把牠們送過來。', `MaleText_loc7`='Verás, hace tiempo que eres $gun buen amigo:una buena amiga; para mí. Ahora que somos vecinos, quiero regalarte unas cuantas gallinas. No es mucho, pero le darán un poco de alegría a tu granja. Te las enviaré.' WHERE `ID`=59218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만요. 제가 쭈욱 생각해봤는데... 그동안 제게 정말 많은 것을 해주셨으니 저도 한 식구 같은 당신에게 보답으로 뭔가를 드려야겠어요. 제가 자란 곳에는 아주 예쁜 오렌지 나무를 키운답니다. 당신 농장에 제가 하나 심어 드렸어요. 이곳 농작물이 자라나는 속도를 볼 때, 집에 돌아갔을 때 이미 꽃이 피어 있어도 그리 놀랄 일은 아닐 거예요.', `FemaleText_loc4`='等一下。我一直在想……你为我做了这么多事，是时候给你一些东西来作为回报了。在我们那儿种着美丽的橘子树，我在你的农场里种了一棵。从这周围的生长态势来看，等你回到农场时那棵橘子树已开满鲜花，我也不会感到惊讶的。', `FemaleText_loc5`='等一下。我一直在想...你為我做了這麼多，是時候給你某樣小東西當作回禮了。在我的家鄉，我們種植美麗的柳橙樹。我在你的農場裡種了一棵。看到這地方作物的成長方式，當你回到農場它就算已經開花了，我也不會感到驚訝。', `FemaleText_loc7`='Espera un momento. He estado pensando... has hecho mucho por mí, así que ya va siendo hora de que te dé algo como agradecimiento. En mi tierra cultivamos unos naranjos preciosos. He plantado uno en tu granja. Viendo cómo crecen las cosas por aquí, no me sorprendería que hubiera florecido ya cuando vuelvas a la granja.' WHERE `ID`=59219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $n 님. 저는 당신과 한 식구니까, 정말 뭔가를 좀 해 드리고 싶어요. 농장을 조금 단장해야 할 것 같다는 생각이 들어서 일꾼들을 시켜 당신 집 안에 새 가구를 들여놨어요. 마음에 들면 좋겠네요!', `FemaleText_loc4`='哦，$n，作为你的挚友，我真想送你些东西。我觉得你的农场需要一点装饰，所以我找人给你家装了些新家具。希望你会喜欢！', `FemaleText_loc5`='喔$n，作為我最好的朋友，我很想要給你某樣東西。我覺得你的農場需要一點裝潢，所以我找些人在你房子裡放了些新家具。希望你會喜歡!', `FemaleText_loc7`='Oh, $n, como tu mejor amiga que soy, me gustaría mucho regalarte algo. He pensado que a tu granja le vendría bien una pequeña renovación, así que les he pedido a unos amigos que instalen unos cuantos muebles nuevos en tu casa. ¡Espero que te gusten!' WHERE `ID`=59220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 농장 일을 도와줄 이를 고용할 수도 있습니까?', `MaleText_loc4`='我能雇人帮忙打理农场吗？', `MaleText_loc5`='我能徵人在我的農場中幫忙嗎?', `MaleText_loc7`='¿Puedo contratar a alguien para que me ayude en la granja?', `FemaleText_loc1`='제 농장 일을 도와줄 이를 고용할 수도 있나요?', `FemaleText_loc4`='我能雇人帮忙打理农场吗？', `FemaleText_loc5`='我能徵人在我的農場中幫忙嗎?', `FemaleText_loc7`='¿Puedo contratar a alguien para que me ayude en la granja?' WHERE `ID`=59221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 친한 친구만이 농장 일을 도와줄 것입니다.', `MaleText_loc4`='只有挚友才行。', `MaleText_loc5`='只有最好的朋友才行。', `MaleText_loc7`='Solo los mejores amigos pueden ayudarte.' WHERE `ID`=59223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 대장. 양들이 아주 튼튼해 보인다.', `MaleText_loc4`='嘿，老板，你的羊看起来很不错哦。', `MaleText_loc5`='嘿，老闆，你的綿羊看起來挺不錯的。', `MaleText_loc7`='Oye, $gjefe:jefa;, tus ovejas tienen muy buena pinta.' WHERE `ID`=59224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 안녕하세요, $n 님! 오늘 농장이 아주 예뻐 보이네요.', `FemaleText_loc4`='哦……为什么，你好，$n！你的农场今天看起来很不错啊。', `FemaleText_loc5`='喔...唉呀，哈囉$n!你的農場今天看起來很漂亮。', `FemaleText_loc7`='Oh... vaya, ¡hola, $n! Tu granja está radiante hoy.' WHERE `ID`=59225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 돼지가 아주 튼튼해 보이네요!', `FemaleText_loc4`='你好，邻居！你的猪看上去很不错啊！', `FemaleText_loc5`='你好啊，鄰居!你的豬群看起來真是有夠棒的。', `FemaleText_loc7`='¡Qué hay, vecino! ¡Tus cerdos tienen una pinta estupenda!' WHERE `ID`=59226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 정원이 정말 끝내준다는 말 밖에 할 게 없네요. 물론 제가 하루 종일 잡초를 뽑기는 했지만...', `MaleText_loc4`='我不得不说，$n，你的园子看起来太棒了！当然了，因为我每天都在帮你除草……', `MaleText_loc5`='我必需要說，$n，你的花園看起來棒極了!當然啦，我拔了整天的草...', `MaleText_loc7`='¡He de admitir, $n, que tu jardín está radiante! Por supuesto, he estado arrancando hierbajos todo el día...' WHERE `ID`=59227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='농부 윤은 정말 매력적이에요! 뭘 해야 할지 알려주면 계속 해준다니까요!', `FemaleText_loc4`='农夫老愚真可爱！我叫他做什么，他就做什么！', `FemaleText_loc5`='農夫尹真是個可愛的人!我不斷告訴他該做什麼事，而他就會去做!', `FemaleText_loc7`='¡El granjero Yoon es un encanto! No dejo de decirle cosas que tiene que hacer, ¡y él va y las hace!' WHERE `ID`=59228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n 님, 연못이 정말 멋지군요.', `MaleText_loc4`='这池塘真是太棒了，邻居。', `MaleText_loc5`='這池塘真的很棒，鄰居。', `MaleText_loc7`='Ese estanque es estupendo, $gvecino:vecina;.' WHERE `ID`=59229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘진 않군, 나쁘지 않아! 내 입에서 이런 말이 나오면 자네 농장이 잘 돌아가고 있다는 말이네. 언젠가 자네도 이 하오한 머드클로같이 성공할 거야!', `MaleText_loc4`='不赖，不赖！我凭良心讲，你的农场搞的真不赖。或许有一天，你会像郝瀚·泥爪一样成功呢！', `MaleText_loc5`='不賴，真不賴!要我來說的話，你的農場經營得很順利。也許有一天你也能像好漢·泥爪般成功。', `MaleText_loc7`='¡No está mal, no está mal! Te lo digo yo, tu granja va como la seda. ¡Quizá algún día tengas tanto éxito como Haohan Zarpa Fangosa!' WHERE `ID`=59230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 닭들이 아주 행복해 보이는구먼.', `MaleText_loc4`='你好，邻居。你的小鸡看起来很开心啊。', `MaleText_loc5`='你好啊，鄰居。你的雞看起來很開心。', `MaleText_loc7`='Qué hay, $gvecino:vecina;. Tus gallinas parecen muy contentas.' WHERE `ID`=59231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 끝났어요, $n 님. 하지만 안심해서는 안 돼요. 이 토깽 놈들은 "토깽이다!"라고 말하는 것보다 더 빠르게 굴을 파대니까요.', `FemaleText_loc4`='都搞定了，$n，但不要放松警惕。那些兔妖挖洞速度比你说“兔妖挖洞！”这几个字还快。', `FemaleText_loc5`='沒有敵人蹤跡，$n。但別放鬆你的警戒心。那些兔妖鑽洞的速度可以比你說「有個兔妖洞!」的速度還快。', `FemaleText_loc7`='Todo despejado, $n. Pero no bajes la guardia. Esos mures pueden cavar un túnel en menos que tú dices "¡Mur al hoyo!".' WHERE `ID`=59232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 농부 윤은 정말이지 신사라니까요! 새로 들여놓은 가구가 멋지다는 말까지 해줬거든요!', `FemaleText_loc4`='哦，农夫老愚真是一位绅士！他甚至还说他很喜欢那些新家具！', `FemaleText_loc5`='喔，農夫尹真是個紳士!他甚至說了他喜歡那些新家具!', `FemaleText_loc7`='¡Oh, el granjero Yoon es todo un caballero! ¡Incluso me ha dicho que le gustaban los nuevos muebles!' WHERE `ID`=59233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 여행자님! 맥주 좀 드세요.', `FemaleText_loc4`='欢迎，旅行者！来点麦芽酒吧。', `FemaleText_loc5`='歡迎你，旅行者!自己去拿些啤酒吧。', `FemaleText_loc7`='¡$GBienvenido, viajero:Bienvenida, viajera;! Sírvete un poco de cerveza.' WHERE `ID`=59234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낯선 이의 발걸음이 점점 뜸해지고 있답니다.', `FemaleText_loc4`='我们在这里已经很少能见到新面孔了。', `FemaleText_loc5`='我們很少在這裡看見新面孔出沒了。', `FemaleText_loc7`='¡Ya no vemos muchas caras nuevas por aquí últimamente!' WHERE `ID`=59235;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요즘 같은 때 감히 산길을 지나려고 하는 이가 많지 않아요. 미친 짓이라 생각하는 사람도 있을걸요.', `FemaleText_loc4`='已经没有多少人有勇气穿越山脉了，朋友。如今，某些人会说你一定是疯了才要这么干。', `FemaleText_loc5`='已經很少有人願意挑戰這座山了，朋友。如今，人們可能會說你是瘋了才會去做這件事。', `FemaleText_loc7`='Muy poca gente se atreve a cruzar el paso de la montaña. De hecho, debes estar $gloco:loca; si lo haces en los tiempos que corren.' WHERE `ID`=59236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖이 추운데 얼른 들어와서 편히 쉬세요!', `FemaleText_loc4`='进来暖和暖和，朋友。不要太拘束！', `FemaleText_loc5`='進來避寒吧，朋友，把這裡當自己家!', `FemaleText_loc7`='¡Entra, ponte $gcómodo:cómoda; y deja el frío atrás!' WHERE `ID`=59237;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 새 손님이시군요! 정말 반가워요!', `FemaleText_loc4`='哦！一位新客人！非常欢迎你，朋友！', `FemaleText_loc5`='喔!一個新顧客!朋友，非常歡迎你!', `FemaleText_loc7`='¡Ah! ¡Un nuevo cliente! ¡$GBienvenido, amigo:Bienvenida, amiga;!' WHERE `ID`=59238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 한 식구처럼 잘해주셨으니 이제부터 제가 예언을 공짜로 해드리겠습니다. 정말 한 푼도 안 드는 거죠! 그냥 이따금 오셔서 저랑 맥주나 마십시다, 네?', `MaleText_loc4`='嘿，邻居。既然你是我这么要好的朋友，从现在起，我将免费给你提供收成预测。绝对免费！只要时不时的来跟我喝两杯，怎么样？', `MaleText_loc5`='嘿，鄰居，因為你一直當我是好朋友，從現在開始我會免費提供你作物的預測。絕對免費!只是要偶爾過來陪我喝酒，如何?', `MaleText_loc7`='Oye, $gvecino:vecina;, como has sido tan $gbuen amigo:buena amiga; para mí, de ahora en adelante voy a darte predicciones sobre cosechas sin cobrarte nada. ¡Nada en absoluto! Simplemente ven a tomar un trago conmigo de vez en cuando, ¿vale?' WHERE `ID`=59239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술은 마치 마법 같다오. 안 그렇소? 재료 한 가지만 살짝 바꾸면, 생명의 비약을 죽음의 비약으로 바꿀 수 있으니 말이오.', `MaleText_loc4`='炼金跟魔法有点像，不是吗？只要略作增减，其效果就会从妙手回春，变成杀人不眨眼。', `MaleText_loc5`='鍊金術有點像魔法，你不認為嗎?只要稍稍改變其中一項成分，小小的一滴液體可以治癒你，也可以殺了你。', `MaleText_loc7`='La alquimia se parece un poco a la magia, ¿no crees? Solo con cambiar un ingrediente, un simple filtro puede sanarte o matarte.' WHERE `ID`=59240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가게에는 진기하고 귀한 물건이 많다오. 마음대로 봐도 좋지만, 만지지는 마시오.', `MaleText_loc4`='我这里卖的都是既神奇又难得的宝贝。快来瞧瞧吧，不过别乱碰。', `MaleText_loc5`='我的店裡充滿了各種令人驚奇的珍稀玩意。只看不摸是明智的選擇。', `MaleText_loc7`='Mi tienda está llena de objetos maravillosos y difíciles de encontrar. Es buena idea mirar, pero no tocar.' WHERE `ID`=59241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물량은 한정돼 있지만, 늘 거래처에서 최고급품만 사들인다오.', `MaleText_loc4`='补给品有限，可我只从贸易者手中购买最好的货物。', `MaleText_loc5`='補給有限，但我只從商人手中接受最好的東西。', `MaleText_loc7`='Los suministros no abundan, pero solo acepto a los mejores comerciantes.' WHERE `ID`=59242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내 영면을 방해하는 것이냐?', `MaleText_loc4`='是谁，胆敢打扰我永恒的沉睡？！', `MaleText_loc5`='誰膽敢打攪我永恆的沉眠?!', `MaleText_loc7`='¡¿Quién osa perturbar mi sueño?!', `FemaleText_loc1`='누가 감히 내 영면을 방해하는 거지?', `FemaleText_loc4`='是谁，胆敢打扰我永恒的沉睡？！', `FemaleText_loc5`='誰膽敢打攪我永恆的沉眠?!', `FemaleText_loc7`='¡¿Quién osa perturbar mi sueño?!' WHERE `ID`=59243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산이 화가 났어요. 길을 떠나기에 운때가 좋지 않아요.', `MaleText_loc4`='高山发怒了，陌生人。现在可不适合出行。', `MaleText_loc5`='陌生人，山脈生氣了。現在不是旅行的好時機。', `MaleText_loc7`='La montaña está enfadada. No es conveniente viajar.' WHERE `ID`=59244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 떠나기에 아주 운수가 좋은 날이에요! 동풍은 복을 가져오거든요.', `MaleText_loc4`='今天可是旅行的吉日啊，朋友！东风吹来了好运气。', `MaleText_loc5`='朋友，今天是旅行的幸運日!東風吹來更多好運。', `MaleText_loc7`='¡Un día espléndido para viajar! Los vientos del este traen muy buena fortuna.' WHERE `ID`=59245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠이 아니라 첸 스톰스타우트입니다!', `MaleText_loc4`='我不叫岑——我是陈·风暴烈酒！', `MaleText_loc5`='我不姓岑...我是老陳·風暴烈酒!', `MaleText_loc7`='¡No soy Zan, soy Chen Cerveza de Trueno!' WHERE `ID`=59246;
