UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 일가족은 어디 있어요? 왜 양조장에 호젠이 득실거리죠?', `MaleText_loc4`='风暴烈酒家的其他人去哪儿了？这里怎么都是猢狲？', `MaleText_loc5`='其他風暴烈酒家的人呢?為什麼酒坊裡面全是猴人?', `MaleText_loc7`='¿Dónde están los demás Cerveza de Trueno? ¿Por qué está la cervecería llena de hozen?' WHERE `ID`=59248;
