UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신록지대를 벗어나고 있습니다. 야크가 도망치려고 합니다!', `MaleText_loc4`='你正在离开翠绿草场。你的牦牛快失控了！', `MaleText_loc5`='你將要離開蒼翠牧場的範圍。你的犛牛就快要掙脫了!', `MaleText_loc7`='Te estás saliendo de la Franja Verdeante. ¡Tu yak está a punto de soltarse!', `FemaleText_loc1`='신록지대를 벗어나고 있습니다. 야크가 도망치려고 합니다!', `FemaleText_loc4`='你正在离开翠绿草场。你的牦牛快失控了！', `FemaleText_loc5`='你將要離開蒼翠牧場的範圍。你的犛牛就快要掙脫了!', `FemaleText_loc7`='Te estás saliendo de la Franja Verdeante. ¡Tu yak está a punto de soltarse!' WHERE `ID`=59261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벼락 잔치를 시작해 보지요, 블랜치.', `MaleText_loc4`='让我们开始闪电派对吧，布兰琪。', `MaleText_loc5`='讓這場閃電派對開始吧，白蘭琪。', `MaleText_loc7`='Que empiece la fiesta de relámpagos, Clara.', `FemaleText_loc1`='벼락 잔치를 시작해 보죠, 블랜치.', `FemaleText_loc4`='让我们开始闪电派对吧，布兰琪。', `FemaleText_loc5`='讓這場閃電派對開始吧，白蘭琪。', `FemaleText_loc7`='Que empiece la fiesta de relámpagos, Clara.' WHERE `ID`=59262;
