UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤를 더 불러내고 있어요! 저것들을 먼저 없애세요!', `MaleText_loc4`='它在召唤更多的煞魔！先集中消灭它们，$p！', `MaleText_loc5`='它在召喚出更多的煞!先集中解決它們，$p!', `MaleText_loc7`='¡Está llamando a más sha! ¡Hay que acabar con ellos primero!' WHERE `ID`=59264;
