UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 희망이 승리했군...', `MaleText_loc4`='看来终究还是希望占了上风……', `MaleText_loc5`='看來希望終究還是獲勝的一方。', `MaleText_loc7`='Parece que la esperanza ha triunfado, después de todo...' WHERE `ID`=59266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기뻐할 시간이 없다. 나의 가르침을 따르는 추종자들이 아직도 밖에서 싸우고 있어.', `MaleText_loc4`='没有时间庆祝了——现在还有很多赤精之道的信徒在外面战斗。', `MaleText_loc5`='沒有時間慶祝了，外面還有許多「道」的追隨者在戰鬥。', `MaleText_loc7`='No hay tiempo para celebraciones. Muchos seguidores de la senda siguen luchando.' WHERE `ID`=59267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정원 중심에 있는 조각상에서 보자꾸나. 거기서 이야기하마.', `MaleText_loc4`='到寺庙庭院中心的雕像附近与我会面。我们在那谈谈。', `MaleText_loc5`='到寺廟中庭附近的鶴雕像找我，到那邊再說吧。', `MaleText_loc7`='Reúnete conmigo cerca de la estatua en el centro de las tierras del templo. Tenemos que hablar.' WHERE `ID`=59268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망에 무릎 꿇어서는 안 된다.', `MaleText_loc4`='我们决不能向绝望低头。', `MaleText_loc5`='我們絕不能屈服於絕望。', `MaleText_loc7`='No debemos rendirnos al desaliento.' WHERE `ID`=59269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유옌, $c|1이야;야;. 일손을 도우러 오셨어요, $c씨?', `MaleText_loc4`='看哪，育温，是个$c。你是来帮忙的吗，$c$g先生:小姐;？', `MaleText_loc5`='武妍，你看，是個$c。$c$g先生:小姐;，你是來幫忙的嗎?', `MaleText_loc7`='Mira, Uyen, es $gun:una; $c. ¿Has venido a ayudarnos, $gseñor:señora; $c?' WHERE `ID`=59270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저긴 상황이 어때요? 우리 민족 구해줄 거지요?', `MaleText_loc4`='情况怎么样？你会救出我的同胞们的，对吧？', `MaleText_loc5`='外頭的情況如何?你會救出我的人民，對吧?', `MaleText_loc7`='¿Cómo van las cosas? Has venido a rescatar a mi pueblo, ¿verdad?' WHERE `ID`=59271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 몸놀림은, 음... 처음 보네요. 당신 정말 무서운 사람이군요.', `MaleText_loc4`='我很久没见过那样的战斗了，自从……嗯，应该说，我从来就没见过那样的战斗。你可真是个高手啊，$n。', `MaleText_loc5`='我好久沒看到這樣的戰鬥了，自從...嗯，我想我這輩子都沒看過像這樣的戰鬥。你真是個爆炸性人物，$n。', `MaleText_loc7`='No he visto un estilo de lucha como ese desde... bueno, nunca he visto un estilo de lucha como ese. Eres todo un espectáculo, $n.' WHERE `ID`=59272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 왔어, 마누라. 근데 왜 내 야크는 한 마리도 안 보이지?', `MaleText_loc4`='快看啊妈，$n回来了。你怎么没找到我的牦牛？', `MaleText_loc5`='媽你看，$n回來了。你為什麼沒帶我的犛牛回來?', `MaleText_loc7`='Vaya, mira mamá. Ha vuelto $n. ¿Por qué vuelves sin mis yaks?' WHERE `ID`=59273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크를 데려왔군요, $n! 자, 이제 저기 있는 우리로 녀석들을 몰아 넣자고요.', `MaleText_loc4`='你找到它们了，$n！来。我们只要把它们关进围栏里就行了。', `MaleText_loc5`='$n，你找到牠們了!我們只要把牠們趕進圍欄裡就行了。', `MaleText_loc7`='¡Lo has conseguido, $n! Déjalos allí en el redil si no te importa.' WHERE `ID`=59274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 마누라. $n|1이야;야;. 안 그래도 당신 얘기 하던 참이에요.', `MaleText_loc4`='妈，快看是谁来了，是$n。我们刚才正谈论你呢。', `MaleText_loc5`='媽你看，是$n。我們正好提到你。', `MaleText_loc7`='Mira, mamá, es $n. Justo estábamos hablando de ti.' WHERE `ID`=59275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 얘기한 게 엊그제 같은데.', `MaleText_loc4`='距离我们上一次交谈，竟然已经过去那么多时间了。', `MaleText_loc5`='感覺距離我們上次談話並沒有很久。', `MaleText_loc7`='No parece que haya pasado tanto tiempo desde la última vez que hablamos.' WHERE `ID`=59276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아요, 알아. 덕분에 우리가 유리해졌어요. 곧 우리 힘으로 저 야운골 놈들을 몰아낼 거라고요. 하지만, 한두 마리 혼내 주고 싶다면 말리진 않겠어요.', `MaleText_loc4`='我知道，我知道。托你的福，我们在这里占了上风，很快就能把那些该死的野牛人赶走了。但话说回来，要是你想再亲手打碎几个脑壳，我也没意见。', `MaleText_loc5`='我知道，我知道。多虧了你，我們現在才能取得上風，很快那些該死的揚古就會被趕出這裡。還是老樣子，如果你有興趣打爛一兩個頭骨，我們不會說什麼的。', `MaleText_loc7`='Ya sé, ya sé. Gracias a ti tenemos ventaja, así que echaremos a esos malditos yaungol de aquí pronto. De todos modos, si te apetece machacar un cráneo o dos, por mi parte no hay problema.' WHERE `ID`=59277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 뭐 신 나는 이야기 없어요? 분명 그동안 한 모험에 대해 얘깃거리가 많을 테지요.', `MaleText_loc4`='$n！你有什么好消息要告诉我们吗？我敢打赌，你肯定又有许多新鲜刺激的冒险故事可说了。', `MaleText_loc5`='$n!你有什麼新鮮事要告訴我們?我打賭你有各種冒險事蹟和精采故事要說。', `MaleText_loc7`='¡$n! ¿Tienes alguna maravilla que contarnos? Seguro que tienes un montón de historias nuevas sobre tus aventuras y eso.' WHERE `ID`=59278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유옌, $n|1이;가; 왔어. 맛난 음식 해 둔 거 없나? $n한테 대접하게 말이야.', `MaleText_loc4`='育温，$n回来了。我们给$g他:她;准备好大餐了吧？嘿嘿，你听懂了没？周？', `MaleText_loc5`='武妍，$n回來了。 我們有什麼「粥」可以給$g他:她;嗎。嘿，懂嗎?粥?', `MaleText_loc7`='Uyen, $n ha vuelto. Tenemos tallarines para $gél:ella;. ¿Lo coges? ¿Tallarín?' WHERE `ID`=59279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 놈들이 아직도 농장에 득시글대서 아주 골치 아파 죽겠어요. 이해해요... 난 당신처럼 멋진 $c|1이;가; 아니거든요. 우리 같은 보통 사람은 이런 골칫거리를 처리하는 데 시간이 좀 걸려요. 그냥 유옌한테 머리통을 좀 때려 주라고 할 수는 있겠지만요, 차마 그럴 수가 없어요. 일단 시작하면 아무도 못 말리거든요...', `MaleText_loc4`='野牛人还在农场上作乱，这说起来可真丢人啊。但你得清楚一点……我可不是像你那么威风的$c。对我们这种普通人来说，处理这些是需要时间的。嗯，我其实可以直接让育温去打烂他们的脑袋。但我不想让她出手，你懂的。', `MaleText_loc5`='這件事有點尷尬，揚古仍然在農場肆虐。你必須了解...我不是一個像你這樣傑出的$c。 對我們這種普通人來說，這需要花點時間。嗯，我可以直接叫武妍去打他們的頭。但你懂的，我不想讓她打上癮。', `MaleText_loc7`='Esta invasión de los yaungol a la granja es una auténtica vergüenza. Pero tienes que comprender... yo no soy $gun:una; gran $c como tú. Para la gente corriente, estas cosas llevan tiempo. Bueno, podría dejar que Uyen les diera una paliza. Pero no quiero provocarla, si entiendes lo que quiero decir.' WHERE `ID`=59280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1을;를; 공격합니다!', `MaleText_loc4`='[DEBUG ONLY]攻击$n!', `MaleText_loc5`='攻擊$n!', `MaleText_loc7`='[DEBUG ONLY] Attacking $n!', `FemaleText_loc1`='$n|1을;를; 공격합니다!', `FemaleText_loc4`='[DEBUG ONLY]攻击$n!', `FemaleText_loc5`='攻擊$n!', `FemaleText_loc7`='[DEBUG ONLY] Attacking $n!' WHERE `ID`=59281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구래! 판다리아에서 제일 유명한 $r $c, $n|1이잖아요;잖아요;! 이리 와요! 한 번 안아 보게!', `MaleText_loc4`='$n，全潘达利亚最有名的$r$c！快过来，给老周一个拥抱！', `MaleText_loc5`='$n，全潘達利亞最有名的$r$c!過來這裡給老周一個擁抱!', `MaleText_loc7`='¡$n, $gel:la; $r $c más $gfamoso:famosa; de toda Pandaria! ¡Ven aquí y dale un abrazo al viejo Tallarín!' WHERE `ID`=59282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가던 길 계속 가세요. 우리 같은 사람이랑 노닥거리는 것보다 더 중요한 일이 있잖아요. 근데 이왕 왔으니 말인데, 밭에서 날뛰는 깡패 토깽 보여요?', `MaleText_loc4`='现在继续吧。你还有更重要的事情要做，别浪费时间造访我们这些人。不过，你来的时候，有没有看见那个在野外疯跑的卑鄙的瓦尔蒙？', `MaleText_loc5`='現在繼續前進吧。比起拜訪我們這種人，你有更重要的事情要做。不過，趁你還在這兒，你有沒有看到那些狡猾的兔妖在田裡四處亂竄啊?', `MaleText_loc7`='Ya está bien. Tienes cosas más importantes que hacer que visitar a gente como nosotros. De todos modos, ya que estás aquí, ¿ves a ese mur de orejas largas que corre por el campo?' WHERE `ID`=59283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요! 호젠을 상대하기가 생각보다 쉽겠는데요.', `FemaleText_loc4`='干得好！这对付猢狲的办法比我预想中的还要简单。', `FemaleText_loc5`='做得好!和猴人打交道會比我預想的還要簡單。', `FemaleText_loc7`='¡Buen trabajo! Encargarnos de los hozen nos resultará más fácil de lo que había anticipado.' WHERE `ID`=59284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 웅얼웅얼 푸념을 합니다.', `FemaleText_loc4`='%s小声嘀咕。', `FemaleText_loc5`='%s不表態地哼了一聲。', `FemaleText_loc7`='%s gruñe de forma reservada.' WHERE `ID`=59285;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1은;는; 별 감흥이 없어 보입니다.', `FemaleText_loc4`='%s看起来不感兴趣。', `FemaleText_loc5`='%s看起來不為所動。', `FemaleText_loc7`='%s no parece impresionada.' WHERE `ID`=59286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1은;는; 당신을 흘끗 보고는 얼굴을 찌푸리더니 침을 뱉습니다.', `FemaleText_loc4`='%s撇了你一眼，又是皱眉又是吐唾沫。', `FemaleText_loc5`='瞥了你一眼後，%s皺眉吐了口口水。', `FemaleText_loc7`='Mientras te echa un vistazo, %s frunce el ceño y escupe.' WHERE `ID`=59287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 한숨을 내쉽니다. 이 상황에 짜증이 난 듯합니다.', `FemaleText_loc4`='%s叹了口气，显然被整体事态激怒了。', `FemaleText_loc5`='%s嘆了口氣，明顯地對這整個情況感到惱火。', `FemaleText_loc7`='%s suspira, claramente exasperada por la situación.' WHERE `ID`=59288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아자! 약골들... 이 손님들은 내가 맡을 테니 썩 꺼져.', `MaleText_loc4`='胆小鬼们……让我来好好招待你们。', `MaleText_loc5`='膽小鬼...讓我來好好招待你們。', `MaleText_loc7`='Gusanos... den lugar a nuestros invitados.' WHERE `ID`=59289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하. 다가와라... 죽음이 너희를 기다린다.', `MaleText_loc4`='靠近点儿……离死亡再近点儿。', `MaleText_loc5`='靠近點...來送死吧。', `MaleText_loc7`='Acérquense... Su muerte los espera.' WHERE `ID`=59290;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 반갑지 않은 손님을 쏘아보며 남편에게 저리 가라는 듯 손짓합니다.', `FemaleText_loc4`='%s一边注视着农场上不断涌现的不速之客，一边向她的丈夫挥手告别。', `FemaleText_loc5`='%s一邊揮手向她丈夫道別一邊怒視著農莊裡不間斷的不速之客。', `FemaleText_loc7`='%s despide a su marido mientras mira fijamente a la inoportuna presencia en su granja.' WHERE `ID`=59291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1은;는; 보는 사람이 없는 줄 알았는지, 조용히 울다가 눈물을 훔치고 다시 꿋꿋한 표정을 짓습니다.', `FemaleText_loc4`='%s低声啜泣着，以为没被任何人发现，然后才擦干眼泪，再次坚定地站了起来。', `FemaleText_loc5`='%s輕聲哭泣以為沒有人發覺，然後她擦乾了眼淚再一次充滿決心站起來。', `FemaleText_loc7`='%s llora en silencio, pensando que nadie se ha dado cuenta, antes de limpiarse las lágrimas y volver a su estoicidad habitual.' WHERE `ID`=59292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 당신을 빤히 쳐다봅니다.', `FemaleText_loc4`='%s只是看着你。', `FemaleText_loc5`='%s只是看著你。', `FemaleText_loc7`='%s te mira fijamente.' WHERE `ID`=59293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1은;는; 미친 듯 날뛰며 밭을 망치는 깡패 토깽의 움직임을 눈으로 쫓는 데 정신이 팔려, 남편의 말을 듣지 못한 듯합니다.', `FemaleText_loc4`='%s盯着卑鄙的瓦尔蒙摧毁她田地的疯狂举动，对丈夫的话充耳不闻。', `FemaleText_loc5`='當%s的雙眼試著要跟上在她田裡瘋狂搞破壞的卑鄙大兔妖時，她似乎沒有聽到她丈夫說的話。', `FemaleText_loc7`='%s no parece escuchar lo que dice su marido, mientras que su mirada está fija en los movimientos enloquecidos del mur de orejas largas que destruye sus campos.' WHERE `ID`=59294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무시무시한 얼음 파도가 방 전체를 휩쓸기 시작합니다.', `FemaleText_loc4`='一股致命的寒冰之潮开始横扫过房间！', `FemaleText_loc5`='死亡的寒冰波濤橫掃過整個房間!', `FemaleText_loc7`='¡Una oleada letal de hielo recorre la sala!' WHERE `ID`=59295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조교 칠하트의 영혼이 성물함으로 도망쳤습니다. 어서 성물함을 파괴하십시오!', `FemaleText_loc4`='指导者寒心的灵魂向她的护命匣逃去。摧毁它！', `FemaleText_loc5`='講師冷心的靈魂逃進了她的骨匣。摧毀它!', `FemaleText_loc7`='El alma de la Instructora Corazón Álgido escapa a su filacteria. ¡Destrúyela!' WHERE `ID`=59296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 보여주마.', `MaleText_loc4`='让你看看我的力量。', `MaleText_loc5`='讓你們看看我的力量。', `MaleText_loc7`='Dejen que les muestre mi poder.' WHERE `ID`=59297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와라, 용이여! 함께 이 침입자들을 처치하자.', `MaleText_loc4`='来我这里，翔龙！让我们一起消灭这些入侵者。', `MaleText_loc5`='來我這裡，蛟龍!讓我們一起消滅這些入侵者。', `MaleText_loc7`='¡Ven a mí, dragón! Juntos destruiremos a los intrusos.' WHERE `ID`=59298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘색 운룡이 공격합니다!', `MaleText_loc4`='碧空翔龙开始攻击！', `MaleText_loc5`='蒼蛟加入了戰鬥!', `MaleText_loc7`='¡El dragón azur se mueve para atacar!' WHERE `ID`=59299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리서 하늘색 운룡이 몸을 꿈틀댑니다!', `MaleText_loc4`='碧空翔龙冲向了远处！', `MaleText_loc5`='蒼蛟在遠處騷動!', `MaleText_loc7`='¡El dragón azur se revuelve en la distancia!' WHERE `ID`=59300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악! 도와줘! 이건 뭐야!? 에이, 상관없어. 지금은 아무도 날 막지 못해. 이제 거의 완성인걸! 쳐다보지만 않으면 괜찮겠지...?', `MaleText_loc4`='啊！救命！那是什么！？没关系，谁也阻止不了我，我就要成功了！如果我不看的话……？', `MaleText_loc5`='喔!天啊!那是什麼呀!?沒差，反正快完成了，沒東西能阻止我!如果放著不管的話...?', `MaleText_loc7`='¡Ah! ¡Socorro! ¿Qué es eso? Es igual; ya nada me detendrá. No cuando estoy tan cerca... A lo mejor si no lo miro...' WHERE `ID`=59301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래 그래 그래! 조금만 더! 아주 살짝만... 허이구야...', `MaleText_loc4`='没错！好的，好的！快成功了！只要一点……噢……', `MaleText_loc5`='喔耶喔耶!快好了!只要再一小撮...唉呀...', `MaleText_loc7`='¡Sí, sí, sí! ¡Estoy cerca! Solo una pizca de... ¡Ay!' WHERE `ID`=59302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 써! 벌꿀 한 방울, 사탕수수 이 정도, 그리고 옥수수? 그래, 옥수수야!', `MaleText_loc4`='太苦了！再加一滴蜂蜜，一块糖，也许再加点玉米？没错，玉米！', `MaleText_loc5`='太苦了!加一滴蜂蜜、一根甜甘蔗，對了加點玉米如何?沒錯，就是玉米!', `MaleText_loc7`='¡Demasiado amargo! Una gota de miel, una caña de azúcar... ¿quizás un poco de maíz? ¡Sí, más maíz!' WHERE `ID`=59303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래, 그래... 아냐, 아냐, 아냐 아냐! 그래! 아냐! 후추!', `MaleText_loc4`='对了，是的，是的……不！不不不！对了！不对！胡椒！', `MaleText_loc5`='沒錯，沒錯，沒錯，沒...不對!對!不對不對!沒錯!不對!胡椒!', `MaleText_loc7`='Sí, sí, sí... ¡No, no, no, no, no, no! ¡Sí! ¡No! ¡Pimientos!' WHERE `ID`=59304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마... 이것은???', `MaleText_loc4`='这……难道就是？？？', `MaleText_loc5`='這...該不會???', `MaleText_loc7`='Es... ¿es posible?' WHERE `ID`=59305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감미로운 맛의 조화, 강렬하고 진한 향! 이것이... 완벽한 맥주다!', `MaleText_loc4`='如此甘醇的味道，迷人的芳香！这是……完美的酒！', `MaleText_loc5`='這種協調的味道，令人陶醉的香氣!這...是完美的佳釀!', `MaleText_loc7`='Qué sabor más armonioso, qué aroma más embriagador... Es... ¡la bebida perfecta!' WHERE `ID`=59306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰스타우트의 명성이 다시 한 번 온 세상에 울려 퍼질 것이다!', `MaleText_loc4`='风暴烈酒的美名必将再次响彻群山！', `MaleText_loc5`='風暴烈酒的名號，將會再一次地響徹這片山丘!', `MaleText_loc7`='¡El nombre Cerveza de Trueno volverá a resonar por todas las colinas!' WHERE `ID`=59307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠나? 내가 우리 명예를 되찾았어! 완벽한 맥주를 만들었다고!', `MaleText_loc4`='又是你！你没看到吗？我终于要出名了：我酿出了完美之酒！', `MaleText_loc5`='又是你!看不出來嗎?我終於贏得名聲!釀出完美佳釀!', `MaleText_loc7`='¿Tú otra vez? ¿No lo entiendes? Por fin me he labrado un nombre. ¡He fermentado la perfección!' WHERE `ID`=59308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 다음엔 맥주를 발효시키자고! 조심하게!', `MaleText_loc4`='下一步，我们要给酒发酵！小心点！', `MaleText_loc5`='接著，我們要讓啤酒發酵!小心!', `MaleText_loc7`='¡Ahora fermentamos la cerveza! ¡Cuidado!' WHERE `ID`=59309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로 열기를 더하는 거야! 냄새를 맡아보게!', `MaleText_loc4`='最后一步，加热！闻闻那香气！', `MaleText_loc5`='最後一個步驟，我們要加熱!聞聞那股香味!', `MaleText_loc7`='¡Y por último, añadimos calor! ¡Qué aroma!' WHERE `ID`=59310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 재료가 너무 불안정해! 지금 이들을 합치면 무슨 일이 일어날지 몰라!', `MaleText_loc4`='酒的成分太混乱了！我不知道要是现在把它们合在一起，会发生什么事！', `MaleText_loc5`='釀造的各種元素太混亂了!如果他們結合在一起，我不知道會發生什麼事!', `MaleText_loc7`='¡Los ingredientes de la cerveza son demasiado caóticos! ¡No sé qué pasará si los combinamos!' WHERE `ID`=59311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휴! 한숨 돌려야겠어요. 여기서 잠깐 쉬어... 뭐지?', `FemaleText_loc4`='唷！我得喘口气。我们在这儿歇一会吧？', `FemaleText_loc5`='呼!我得喘一下。讓我們在這休息一下...什麼?', `FemaleText_loc7`='¡Uf! Necesito un respiro. Vamos a descansar un momen... ¿Qué?' WHERE `ID`=59312;
