UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한숨 돌릴 틈이 없어요. 빨리요! 우리가 도와야 해요!', `FemaleText_loc4`='没时间休息了。快！我们得帮帮他们！', `FemaleText_loc5`='沒時間調整呼吸了。快點!我們得幫助他們!', `FemaleText_loc7`='No hay tiempo para recobrar el aliento. ¡Rápido! ¡Tenemos que ayudarlos!' WHERE `ID`=59314;
