UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 주둔지로 가는 그루멀 일행이 곧 떠나요. 돕고 싶으면 여기서 기다리세요!', `MaleText_loc4`='很快就要有更多土地精启程前往寇塔营地了。要想帮忙就待在这儿！', `MaleText_loc5`='更多的咕嚕摩不久後將離開這裡前往柯沓營地。想幫忙就在這裡等著!', `MaleText_loc7`='En breve más grúmel saldrán hacia el Campamento Base Kota. ¡Espera aquí si quieres ayudar!' WHERE `ID`=59328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제들이여, 이 오만한 외부인을 몰아내자!', `MaleText_loc4`='弟兄们！赶走这些傲慢之徒！', `MaleText_loc5`='兄弟們!解決掉這些猖狂的外來者!', `MaleText_loc7`='¡Hermanos! ¡Encárguense de esos forasteros insolentes!' WHERE `ID`=59329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지붕에서 음영파 화염 궁수들이 나타납니다!', `MaleText_loc4`='影踪派火箭手出现在屋顶！', `MaleText_loc5`='影潘火焰弓箭手出現在屋頂上了!', `MaleText_loc7`='¡Aparecen arqueros de fuego del Shadopan en los tejados!' WHERE `ID`=59330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 궁수들이 모습을 감춥니다.', `MaleText_loc4`='影踪派弓箭手消失了！', `MaleText_loc5`='影潘弓箭手消失了!', `MaleText_loc7`='¡Desaparecen los arqueros del Shadopan!' WHERE `ID`=59331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀들이 지금 어딨는지 지도에 표시해 줄게요. 거기로 찾아가거나, 여기서 다음 일행이 출발할 때까지 기다리세요.', `MaleText_loc4`='我在地图上给你指出土地精现在在哪里。要么去找他们，要么就待在这里等下一拨土地精。', `MaleText_loc5`='我在你的地圖上指出咕嚕摩現在的位置。去找他們，或是在這裡等下一波咕嚕摩出現。', `MaleText_loc7`='Te enseñaré en el mapa dónde están los grúmel. Encuéntralos o espera a la siguiente oleada de grúmel.' WHERE `ID`=59332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 씨앗을 심으면 이 네 바람의 계곡에서 가장 상품의 채소로 자랍니다. 제가 보장하지요!', `MaleText_loc4`='我的种子长出的菜是谷里最好的，我保证！', `MaleText_loc5`='我的種子會長出全山谷最棒的蔬菜。我保證!', `MaleText_loc7`='Mis semillas dan las mejores verduras del valle. ¡Garantizado!' WHERE `ID`=59333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부 윤에게 줄 씨앗을 가지러 왔습니다.', `MaleText_loc4`='我来这儿是为农夫老愚挑选种子的。', `MaleText_loc5`='我到這裡來幫農夫尹挑選種子。', `MaleText_loc7`='Vengo a recoger semillas para el granjero Yoon.', `FemaleText_loc1`='농부 윤에게 줄 씨앗을 가지러 왔어요.', `FemaleText_loc4`='我来这儿是为农夫老愚挑选种子的。', `FemaleText_loc5`='我到這裡來幫農夫尹挑選種子。', `FemaleText_loc7`='Vengo a recoger semillas para el granjero Yoon.' WHERE `ID`=59334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤이라고요? 으음... 전혀 들어본 적 없는 이름인데...', `MaleText_loc4`='老愚？没听说过……', `MaleText_loc5`='尹，是嗎?從沒聽說過他...', `MaleText_loc7`='Yoon, ¿eh? Nunca he oído hablar de él...' WHERE `ID`=59335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤이 태양노래 농장을 물려받은 지 얼마 되지 않아서 그러시겠지요. 이 자리에서도 윤이 서 있는 곳을 볼 수 있습니다.', `MaleText_loc4`='他刚刚继承了日歌农场。从你现在所站的位置就能看见他。', `MaleText_loc5`='他繼承了日歌農莊。你可以從你現在站的位置清楚地看見他。', `MaleText_loc7`='Acaba de heredar el Rancho Cantosol. Desde donde estás puedes verlo, literalmente.', `FemaleText_loc1`='윤이 태양노래 농장을 물려받은 지 얼마 되지 않아서 그러실 거예요. 이 자리에서도 윤이 서 있는 곳을 볼 수 있답니다.', `FemaleText_loc4`='他刚刚继承了日歌农场。从你现在所站的位置就能看见他。', `FemaleText_loc5`='他繼承了日歌農莊。你可以從你現在站的位置清楚地看見他。', `FemaleText_loc7`='Acaba de heredar el Rancho Cantosol. Desde donde estás puedes verlo, literalmente.' WHERE `ID`=59336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 저쪽에 있는 태양노래 농장 말씀이시군요. 그곳에 누가 올지 궁금해하는 중이었습니다.$B$B<눈을 가늘게 뜨고 당신 어깨 너머에 있는 윤을 향해 손을 흔드는 그린필드>$B$B처음 드리는 씨앗 봉투는 무료입니다.$B$B진짜 커다랗고 잘 익은 채소를 가지고 언덕골 상점에 되돌아오면, 누가 씨앗을 줬는지 다른 이들에게 말해주십시오!', `MaleText_loc4`='噢，当然！日歌农场，就在那边。我还好奇谁会搬进那去呢。$B$B<绿野斜眼向你肩后瞥了一眼，并向老愚挥了挥手。>$B$B等你带着大家从没见过的最大、最鲜美的蔬菜回市集时，你就告诉他们你是在哪儿搞到的种子！', `MaleText_loc5`='喔，當然!日歌那個地方，就在那裏。我很好奇誰會搬到那裡去。$B$B<青田的視線越過你的肩膀並向小尹揮揮手。>$B$B當你帶著人們所見過最大、最多汁的蔬菜回到市場來時，你再告訴他們你在哪兒拿到種子的!', `MaleText_loc7`='¡Aah, claro! Cantosol, por aquella parte. Me preguntaba quién se habría establecido allí.$B$B<Campo Fértil mira por encima de tu hombro y saluda a Yoon.>$B$BCuando vuelvas al mercado con las verduras más grandes y jugosas que haya visto nadie, ¡diles dónde compraste las semillas!' WHERE `ID`=59337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감미로운 맛의 조화, 강렬하고 진한 향! 이것이... 완벽한 맥주다!', `MaleText_loc4`='如此和谐的味道，如此令人陶醉的香气！这……真是绝世佳酿啊！', `MaleText_loc5`='如此調和的滋味，如此猛烈的香氣!它是...完美的啤酒!', `MaleText_loc7`='Qué sabor más armonioso, qué aroma más embriagador... Es... ¡la bebida perfecta!' WHERE `ID`=59338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공습병 가도크가 포격 질주를 할 준비를 합니다.', `MaleText_loc4`='突袭者加杜卡准备发动一次扫射！', `MaleText_loc5`='打擊者卡多克準備開始低空掃射!', `MaleText_loc7`='¡Asediador Ga''dok se prepara para un bombardeo!' WHERE `ID`=59339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 문이 무너진다. 어서! 이 방해꾼들을 쓸어버려!', `MaleText_loc4`='城门即将陷落。快！杀光这些暴徒！', `MaleText_loc5`='關口就快被攻破了!快，殺光這些礙事的傢伙!', `MaleText_loc7`='Las puertas están a punto de caer. ¡Rápido! ¡Maten a esos intrusos!' WHERE `ID`=59340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 힘으로, 일어나라!', `MaleText_loc4`='以赞达拉之力，我命令你站起来！', `MaleText_loc5`='以贊達拉之名，我命令你們站起來!', `MaleText_loc7`='¡Por el poder de Zandalar, os ordeno que os alcéis!' WHERE `ID`=59341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클라투, 바라다, 니크토!', `MaleText_loc4`='[异星语]Klatu，Barada，Nikto！', `MaleText_loc5`='克拉圖、巴瑞達、尼克托!', `MaleText_loc7`='¡Klatu, Barada, Nikto!' WHERE `ID`=59342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피에르토툼 로코모토르!', `MaleText_loc4`='[咒文]Piertotum Locomotor（即刻起身）！', `MaleText_loc5`='雕像，行行起!', `MaleText_loc7`='¡Piertotum Locomotor!' WHERE `ID`=59343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총 스왕 샹셩, 모구!', `MaleText_loc4`='[魔古语]Cong siwang shangsheng，mogu！', `MaleText_loc5`='從死亡上升，魔古!', `MaleText_loc7`='¡Cong siwang shangsheng, mogu!' WHERE `ID`=59344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄 데드, 노 엠 응루트.', `MaleText_loc4`='身起魂尸，令律如急急！', `MaleText_loc5`='亡者，復活吧。', `MaleText_loc7`='¡Treguna, mekoides, trecorum satis dee!' WHERE `ID`=59345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비타, 모르티스, 카레오!', `MaleText_loc4`='元神归位，起！', `MaleText_loc5`='生，或死，皆被棄!', `MaleText_loc7`='¡Vita, Mortis, Careo!' WHERE `ID`=59346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은 잠에서 깨어났구나, 친애하는 모구여. 나와 함께 이 땅을 짓밟자.', `MaleText_loc4`='从休眠中醒来吧，我的魔古朋友们。让我们一起粉碎这片土地。', `MaleText_loc5`='從沉眠中醒來吧，我的魔古朋友。我們一起毀滅這塊大地。', `MaleText_loc7`='Deh''pertad de vueh''tro sueño, amigos mogu. Juntos, aplah''taremos eh''tas tierras.' WHERE `ID`=59347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅의 탈환을 방해하는 놈들을 처치하자.', `MaleText_loc4`='消灭那些胆敢阻止我们重夺这片土地的人。', `MaleText_loc5`='摧毀那些想阻止我們搶回這塊土地的人。', `MaleText_loc7`='Deh''truid a los que intentan arrebatarnos eh''tas tierras.' WHERE `ID`=59348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너?! 온통 네 얘기뿐이더군. 내 마법은 강하다. 너는 잔달라를 막을 수 없다!', `MaleText_loc4`='你？！我对你知道得一清二楚。我的魂能很强大。你阻止不了赞达拉部族！', `MaleText_loc5`='你?!我聽說過你。我的魂能很強。你無法阻止贊達拉!', `MaleText_loc7`='¡¿Ustedes?! Lo sé todo de ustedes. Mi juju es fueh''te. ¡Ustedes no van a detener a los Zandalari!' WHERE `ID`=59349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모 아니면 도예요, $n 님. 썬더포우 은거처에는 우리 힘이 필요해요. 마무리할 준비가 됐나요?', `FemaleText_loc4`='一定要全力以赴，$n。雷掌阁需要我们。你准备好了结此事了吗？', `FemaleText_loc5`='必須一口氣搞定，$n。雷爪靜修居需要我們。你準備好做個了結了嗎?', `FemaleText_loc7`='Es todo o nada, $n. El Refugio Zarpa Atronadora nos necesita. ¿Estás $glisto:lista; para acabar con esto?' WHERE `ID`=59350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도마뱀 좀 잡아 봅시다, 블랜치!', `MaleText_loc4`='我们去杀几条蜥蜴人吧，布兰琪！', `MaleText_loc5`='來殺點蜥蜴吧，白蘭琪!', `MaleText_loc7`='¡Vamos a matar unos cuantos lagartos, Clara!', `FemaleText_loc1`='도마뱀 좀 잡아 보죠, 블랜치!', `FemaleText_loc4`='我们去杀几条蜥蜴人吧，布兰琪！', `FemaleText_loc5`='來殺點蜥蜴吧，白蘭琪!', `FemaleText_loc7`='¡Vamos a matar unos cuantos lagartos, Clara!' WHERE `ID`=59351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='들어갈 준비가 되면 말해 주세요...', `FemaleText_loc4`='当你准备好进去时就告诉我……', `FemaleText_loc5`='準備好進去時就告訴我...', `FemaleText_loc7`='Avísenme cuando estén preparados para entrar…' WHERE `ID`=59352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가서 영웅이 되자고요!', `FemaleText_loc4`='让我们做回大英雄吧！', `FemaleText_loc5`='來當個英雄吧!', `FemaleText_loc7`='¡Vamos a ser héroes!' WHERE `ID`=59353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막 기회다, 이 갈래 혀 꿈틀이들아!', `FemaleText_loc4`='最后一次警告，你们这些舌头分叉的爬虫！', `FemaleText_loc5`='該死了，你這個舌頭分岔的滑溜爬蟲!', `FemaleText_loc7`='¡Último aviso, reptiles de lengua bífida!' WHERE `ID`=59354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집으로 돌아갈 필요는 없지만, 여기서 재워 주진 않을 거야.', `FemaleText_loc4`='你们不必滚回老家，但也不准留在这里。', `FemaleText_loc5`='你不必回去，但也不能留在這裡。', `FemaleText_loc7`='No tienen que volver a casa, pero no pueden quedarse aquí.' WHERE `ID`=59355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낭창거리는 꽃이 전방에 끔찍한 가스를 내뿜습니다.', `MaleText_loc4`='蹒跚花苗开始向正前方喷吐秽臭气体。', `MaleText_loc5`='蹣跚之花開始在面前噴放一股腐臭的毒氣。', `MaleText_loc7`='La flor tambaleante empieza a liberar un gas fétido hacia el frente.' WHERE `ID`=59356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기가 깨끗한 것은 한 번도 싸운 적이 없다는 증거지요.', `MaleText_loc4`='一件干净的武器表明它的主人并没有经历过战斗。', `MaleText_loc5`='乾淨的武器標示出一個從沒上過戰場的人。', `MaleText_loc7`='Un arma limpia es señal de que no ha conocido batalla.' WHERE `ID`=59357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, 친구! 일생일대의 돈벌이가 있는데... 들어 보겠소?', `MaleText_loc4`='你好，朋友！想听我介绍一桩一生难遇的好买卖吗？', `MaleText_loc5`='嗨，朋友!有興趣跟我談個千載難逢的交易嗎?', `MaleText_loc7`='¡Hola! ¿Te interesa hacer el negocio del siglo?' WHERE `ID`=59358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기는 몸의 일부여야 합니다. 자기 몸을 돌보듯 무기를 돌보면, 절대 실망할 일이 없을 겁니다.', `MaleText_loc4`='武器应该是战士身体的一部分。像爱惜你自己一样，爱惜你的武器，它就不会让你失望。', `MaleText_loc5`='武器應該是戰士本身的延伸。好好照顧它，就像你照顧自己的身體一樣，如此它永遠不會讓你失望。', `MaleText_loc7`='Un arma debería ser una prolongación del guerrero. Cuídala como si fuera una parte de ti y nunca te fallará.' WHERE `ID`=59359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물 회수는 어떻게 돼 가오, $n? 모구 석상 때문에 너무 골치 아프진 않았으면 좋겠군.', `MaleText_loc4`='找到遗物了吗，$n？但愿那些魔古雕像没给你造成太大的麻烦。', `MaleText_loc5`='$n，取回聖物的任務還順利嗎?希望那些魔古雕像沒給你帶來太多麻煩。', `MaleText_loc7`='¿Cómo va la búsqueda de reliquias, $n? Espero que estas estatuas mogu no supongan un problema para ti.' WHERE `ID`=59360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 유물을 이렇게 많이 가져오다니. 우린 부자가 될 거요!', `MaleText_loc4`='好多魔古遗物啊。我们要发大财了！', `MaleText_loc5`='好多魔古聖物啊。我們要發大財了!', `MaleText_loc7`='Has conseguido muchas reliquias mogu. ¡Vamos a ser ricos!' WHERE `ID`=59361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑소, $n.', `MaleText_loc4`='很高兴再次见到你，$n。', `MaleText_loc5`='很高興又見到你了，$n。', `MaleText_loc7`='Encantado de volver a verte, $n.' WHERE `ID`=59362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 용기를 내서 유물을 더 구하러 가볼까 하는데. 어떻게 생각하오, $n?', `MaleText_loc4`='我正想鼓起勇气去找更多遗物呢。你觉得怎么样，$n？', `MaleText_loc5`='我正在鼓起勇氣去拿更多的聖物。$n，你覺得呢?', `MaleText_loc7`='Estoy reuniendo valor para ir en busca de más reliquias mogu. ¿Qué te parece, $n?' WHERE `ID`=59363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 돌아가서 사 줄 사람을 찾기만 하면, 이 유물로 떼돈을 벌 수 있을 거요.', `MaleText_loc4`='只要等我找到合适的时机返回城镇并找到买家，那些遗物就能为我换回一大堆金币。', `MaleText_loc5`='等我回到鎮上找到買主，這些聖物可以換來大筆大筆的黃金。', `MaleText_loc7`='Estas reliquias me van a proporcionar mucho oro en cuanto tenga tiempo de volver al pueblo y encontrar un comprador.' WHERE `ID`=59364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변두리를 따라 살살 움직이면, 석상의 눈을 피해서 잽싸게 폐허에 들어가서 유물을 집어 올 수 있지 않을까 싶소만.', `MaleText_loc4`='我敢打赌，要是我死守在外围，就能在废墟间自由进出，顺手拿上几件遗物，还能避开那些雕像。', `MaleText_loc5`='我敢打賭，如果我緊沿著外圍，就有辦法迅速進出廢墟，帶走一點聖物而且不被那些雕像逮到。', `MaleText_loc7`='Seguro que si no me acerco mucho, podría entrar en las ruinas, conseguir varias reliquias y evitar a esas estatuas al salir.' WHERE `ID`=59365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에, $n, 모구 머리가 나를 노려보고 있소!', `MaleText_loc4`='噢天呐，$n，这些魔古脑袋正在瞪着我呢！', `MaleText_loc5`='喔天啊，$n，那些魔古腦袋在盯著我看!', `MaleText_loc7`='¡Por los dioses, $n, estas cabezas de mogu me están mirando fijamente!' WHERE `ID`=59366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 재밌는 이야기 듣고 싶소? 모구지아의 모구가 처음부터 토우였던 건 아니라오. 녀석들이 섬기던 주군이 명예롭게 전사하자, 주군과 함께 산 채로 무덤에 묻힌 것이지.', `MaleText_loc4`='$n，有趣的是，魔古岬这里的魔古族原本并不是陶俑。他们是在自己的君主光荣战死后，被殉葬活埋的。', `MaleText_loc5`='$n，讓我告訴你一件有趣的事:魔古岬這裡的魔古並不是一開始就是兵馬俑的。在他們的首領死於一場光榮的戰鬥後，他們被跟他們首領活埋在一起。', `MaleText_loc7`='Un dato curioso, $n: los mogu de Mogujia no siempre fueron de terracota. Los enterraban vivos junto a sus señores cuando estos morían en batallas épicas.' WHERE `ID`=59367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 재미있는 사실이 있소. 모구지아는 대충 "모구의 집"이라는 뜻이라오. 그런데 거기 속으면 안 된다오. 집이 여기만 있는 게 아니거든. 사람들이 그냥 여길 그렇게 부르는 거지. 내가 연구를 좀 해 봤는데, 원래 이 지역의 이름은 초우 요새였다고 하오. 묘하게도 마침 저쪽에 사는 농부와 이름이 같은데, 그냥 우연이겠지.', `MaleText_loc4`='有趣的是——魔古岬是取自“魔古之家”的谐音。但千万别信以为真，他们可并非只有这一个家。这只是人们赋予这地方的名字罢了。我做过一些研究，发现这里原本叫周家堡。诡异得很。一定跟农夫老周的名字存在着某种巧合。', `MaleText_loc5`='說個有趣的小知識:魔古岬的意思也可以算是「魔古的家」。但別讓這個名稱騙了你，這不是他們唯一的家，這只是人們對這個地方的稱呼罷了。我做過一些研究，發現這個地區原本的名字是周家堡。剛好農夫老周也姓周，真是巧合。', `MaleText_loc7`='Aquí tienes un dato curioso: Mogujia más o menos quiere decir "hogar de los mogu". Pero que no te confunda ese nombre. No es su único hogar. Es el nombre que le han dado algunos a este lugar. He indagado un poco y he descubierto que el nombre original de esta zona era Fortaleza Tallarín. Qué raro. Debe de ser una coincidencia que se llame igual que el granjero Tallarín.' WHERE `ID`=59368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 잔달라 트롤이 석상을 살리고 있었는지는 알아냈소?', `MaleText_loc4`='你查明赞达拉巨魔为什么要复活这里的雕像了吗？', `MaleText_loc5`='你找出來為什麼贊達拉食人妖要讓這裡的雕像復活了嗎?', `MaleText_loc7`='¿Ya has descubierto por qué ese trol Zandalari estaba dando vida a esas estatuas?' WHERE `ID`=59369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 양배추들은 금방 자라날 겁니다... 조금만 기다리십시오...', `MaleText_loc4`='卷心菜马上就好了……稍等一下……', `MaleText_loc5`='那些捲心菜應該隨時都會成熟...等一等...', `MaleText_loc7`='Esos repollos estarán listos en cualquier momento... Espera...' WHERE `ID`=59370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 됐습니다! 수확할 만큼 익었군요!', `MaleText_loc4`='我们上！可以采摘了！', `MaleText_loc5`='這就是了!成熟可摘!', `MaleText_loc7`='¡Ya está! ¡Listos para recogerlos!' WHERE `ID`=59371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 연꽃 향 좀 더 있어?', `MaleText_loc4`='有没有弄到更多的莲花熏香？', `MaleText_loc5`='拿到蓮花薰香了嗎?', `MaleText_loc7`='¿Te queda más incienso de loto?' WHERE `ID`=59372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 요즘 통 안 보이던걸. 과연 산을 올라갈 수 있을지 의심스러워지고 있어.', `MaleText_loc4`='还没见着呢。我开始怀疑我们是否能够爬上这座山。', `MaleText_loc5`='什麼都還沒看見，我開始懷疑我們是否能成功爬上山頂。', `MaleText_loc7`='No he visto ninguno. Empiezo a dudar de si seremos capaces de subir a la montaña.' WHERE `ID`=59373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 힘들게 번 금화와 재산을, 형제 깨진주사위가 다 따고 있소! 그루멀을 믿으면 안 되는 거였는데. 덩치가 자기 반만큼도 안 되는 건 절대 믿지 마시오...', `MaleText_loc4`='堂弟破烂骰在搞走我所有辛苦挣来的钱和货物！我早该知道不能相信一个土地精的。绝不能相信任何只有你一半高的东西……', `MaleText_loc5`='破骰兄拿走我辛苦賺來的所有金錢和貨物!我早該知道不能相信一個咕嚕摩。永遠不要相信只有你一半高的東西...', `MaleText_loc7`='¡El hermano Dado Roto se está quedando con todo el oro y los objetos que he conseguido! No debería fiarme de un grúmel. Nunca te fíes de algo que mide la mitad que tú...' WHERE `ID`=59374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삼베 중계지로 가는 수송대가 곧 떠나요! 모이세요!', `MaleText_loc4`='前往粗麻驿站的商队就要出发了！快集合！', `MaleText_loc5`='前往粗麻小站的車隊正要離開!集合!', `MaleText_loc7`='¡El convoy para la Estación Arpillera está a punto de salir! ¡Acercaos!' WHERE `ID`=59375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 위해!', `MaleText_loc4`='为了财富！', `MaleText_loc5`='為了好運!', `MaleText_loc7`='¡Por fortuna!' WHERE `ID`=59376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 여러분! 이리 와서 여행의 향을 깊이 들이마셔요. 행운과 함께 삼베 중계지로 떠나요!', `MaleText_loc4`='土地精们！过来深吸几口旅者熏香吧。它能让你的粗麻驿站之旅好运相伴！', `MaleText_loc5`='咕嚕摩!快來深深吸一口旅用薰香。帶著好運前往粗麻小站吧!', `MaleText_loc7`='¡Grúmel! Vengan y respiren profundamente este incienso de viaje. ¡Que la fortuna los acompañe hasta la Estación Arpillera!' WHERE `ID`=59377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 여러분! 모여서 여행의 향을 깊이 들이마셔요. 행운과 함께 코타 주둔지로 떠나요!', `MaleText_loc4`='土地精！都过来吸一口旅者熏香，带着好运前往寇塔营地！', `MaleText_loc5`='咕嚕摩!快圍成一圈，深深吸一口旅用薰香。帶著好運前往柯沓營地吧!', `MaleText_loc7`='¡Grúmel! Vengan y respiren profundamente este incienso de viaje. ¡Que la fortuna los acompañe hasta el Campamento Base Kota!' WHERE `ID`=59378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈술사들을 처치해 릴리안 보스를 도우십시오!', `MaleText_loc4`='击败白骨编织者以帮助莉莉安·沃斯！', `MaleText_loc5`='擊敗織骨者來援助莉莉安·佛斯!', `MaleText_loc7`='¡Derrota a los tejehuesos para ayudar a Lilian Voss!' WHERE `ID`=59379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀의 힘!', `MaleText_loc4`='土地精之力！', `MaleText_loc5`='咕嚕摩力量!', `MaleText_loc7`='¡Poder grúmel!' WHERE `ID`=59380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내 복덩이 가져가지 마!', `MaleText_loc4`='不！别拿走我的幸运符！', `MaleText_loc5`='不!不要帶走我的幸運星!', `MaleText_loc7`='¡No te llevarás grisgrís!' WHERE `ID`=59381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테서 지독한 불행 냄새가 나.', `MaleText_loc4`='你浑身散发着霉运的味道。', `MaleText_loc5`='你有厄運的臭味。', `MaleText_loc7`='Apestas a mala suerte.' WHERE `ID`=59382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한텐 그루멀짐 못 줘!', `MaleText_loc4`='土地精包裹没你的份儿！', `MaleText_loc5`='不給你咕嚕摩包!', `MaleText_loc7`='¡Tú te quedas sin paquete grúmel!' WHERE `ID`=59383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테 불행이 찾아올 거야!', `MaleText_loc4`='倒霉去吧！', `MaleText_loc5`='祝你壞運!', `MaleText_loc7`='¡Mala fortuna para ti!' WHERE `ID`=59384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 나한테 행운이 찾아오길!', `MaleText_loc4`='今天好运与我同在！', `MaleText_loc5`='今天好運站在我這邊!', `MaleText_loc7`='¡La suerte está conmigo hoy!' WHERE `ID`=59385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한텐 그루멀짐 못 줘!', `MaleText_loc4`='土地精包裹没你的份儿！', `MaleText_loc5`='不給你咕嚕摩包!', `MaleText_loc7`='¡No hay paquete grúmel para ti!' WHERE `ID`=59386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 동영상이 될 부분입니다.$B$B베타 테스터 여러분 사랑합니다.', `MaleText_loc4`='THIS IS WHERE A MOVIE WILL BE$B$BWE LOVE YOU, BETA TESTERS', `MaleText_loc5`='THIS IS WHERE A MOVIE WILL BE', `MaleText_loc7`='AQUÍ VIENE UN VÍDEO$B$BOS QUEREMOS, BETA TESTERS', `FemaleText_loc1`='이곳이 동영상이 될 부분입니다.$B$B베타 테스터 여러분 사랑합니다.', `FemaleText_loc4`='THIS IS WHERE A MOVIE WILL BE$B$BWE LOVE YOU, BETA TESTERS', `FemaleText_loc5`='THIS IS WHERE A MOVIE WILL BE', `FemaleText_loc7`='AQUÍ VIENE UN VÍDEO$B$BOS QUEREMOS, BETA TESTERS' WHERE `ID`=59387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 고마워요! 삼베 중계지에서 기다릴게요.', `MaleText_loc4`='谢谢你的搭救！到粗麻驿站和我会合。', `MaleText_loc5`='感謝你的救援!到粗麻小站找我。', `MaleText_loc7`='¡Gracias por rescatarme! Reúnete conmigo en la Estación Arpillera.' WHERE `ID`=59388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너와 네 친구들은 이곳에서 당분간 눈에 띄지 않는 게 현명할 것이다, 여행자여.', `FemaleText_loc4`='要是你和你的伙伴们能离开这里一段时间，那也许是最明智的，旅行者。', `FemaleText_loc5`='也許最聰明的做法是你和你的夥伴有一段時間不要出現在這裡，旅人。', `FemaleText_loc7`='Si tú y tus compañeros no se dejaran ver por aquí por una temporada, mi sabiduría aumentaría.' WHERE `ID`=59389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 준비가 되었습니다.', `MaleText_loc4`='我做好出发的准备了。', `MaleText_loc5`='我準備好離開了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='떠날 준비가 되었어요.', `FemaleText_loc4`='我做好出发的准备了。', `FemaleText_loc5`='我準備好離開了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=59390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보고할 준비가 됐어, $n! 뭐, 딱히 자랑할 생각은 없지만, 나즈그림 장군님께서 내 작품을 보시면 꽤나 기분이 좋으실 거야.', `MaleText_loc4`='报告都准备好了，$n！我可不是吹牛，纳兹戈林将军一定会对我的工作非常满意的。', `MaleText_loc5`='報告都準備好了，$n!我不想要自誇，但納茲格寧姆將軍應該會對我的成果感到十分滿意。', `MaleText_loc7`='El informe está listo para enviar, $n. No es por alardear, pero el general Nazgrim debería estar bastante contento con mi trabajo.' WHERE `ID`=59391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고서 여기 있습니다, $n 님. 아! 폭탄에 대한 제 생각을 꼭 전해주십시오. 보고서에도 간단히 적어 두었습니다.', `FemaleText_loc4`='报告在这里，$n。哦！记得一定要提炸弹是我的主意哦，我在报告里标出了这一点。', `FemaleText_loc5`='報告在這，$n。喔!務必提到我關於炸彈的主意。我在報告中有將它劃線了。', `FemaleText_loc7`='Aquí está el informe, $n. ¡Ah! Asegúrate de que mencionas mi idea de las bombas. La he subrayado en el papel.' WHERE `ID`=59392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 야만적이군요!', `MaleText_loc4`='这实在是太野蛮了！', `MaleText_loc5`='這真是野蠻!', `MaleText_loc7`='¡Esto es una barbaridad!' WHERE `ID`=59393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 전쟁에 이 원주민들까지 휩쓸리게 하는 것은 잘못된 일입니다. 우린 이들에게 우리의 가장 나쁜 면이 아니라, 가장 좋은 면을 보여줘야 해요...', `MaleText_loc4`='把这些当地人卷入我们的战争是不对的。我们应该把最好的一面展现给他们，而不是最坏的一面……', `MaleText_loc5`='讓這些原住民牽扯到我們之間的戰事裡是錯誤的。我們應該將我們最好的一面教給他們，而非最壞的一面...', `MaleText_loc7`='Enseñarles cómo hacemos la guerra a estos nativos es un error. Deberíamos mostrarles lo mejor de nosotros, no lo peor...' WHERE `ID`=59394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 이 미친 짓을 그만둘 수 있습니다. 이래야 할 필요는 없어요, 쇼키아...', `MaleText_loc4`='现在还有时间制止这一暴行。你没必要这么做，夏琪亚……', `MaleText_loc5`='還有時間阻止這種瘋狂行為。你不需要這麼做，修基雅...', `MaleText_loc7`='Aún hay tiempo de poner fin a esta locura. No tienes que hacerlo, Shokia...' WHERE `ID`=59395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에는 우리가 배울 것이 정말 많습니다. 그런데 당신들은 그저 이곳이 불타는 모습을 지켜볼 뿐이군요.', `MaleText_loc4`='从这片土地上，我们可以学到很多，然而你却只想看着它燃烧。', `MaleText_loc5`='這塊土地有許多我們可以學習的東西，而你卻滿足於看著它在你身旁陷入火海。', `MaleText_loc7`='Esta tierra tiene mucho que enseñarnos y, sin embargo, tú te contentas con verla arder.' WHERE `ID`=59396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고서라고요?! 제가 지금 정신 없이 바쁜 게 안 보이세요, $n 님? 아, 알았다고요. 여기요.', `FemaleText_loc4`='报告？！我现在忙得腾不出手来，$n！好吧好吧，给你。', `FemaleText_loc5`='報告?!我都快忙到快喘不過氣了，$n!喔好吧，拿去。', `FemaleText_loc7`='¿Informe? ¿No ves que estoy ocupada, $n? Oh, de acuerdo. Toma.' WHERE `ID`=59397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나즈그림이 리코 좋아할 거다! 여기! 보고서 끝!', `MaleText_loc4`='纳兹戈林一定会对里克非常满意的！拿去！报告做好了！', `MaleText_loc5`='納茲格寧姆會對瑞可感到非常高興。在這!報告完成了!', `MaleText_loc7`='¡Nazgrim se va a poner muy contento con Riko! Toma, el informe ya está listo.' WHERE `ID`=59398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 원군을 부릅니다!', `MaleText_loc4`='%s大声呼唤增援！', `MaleText_loc5`='%s呼叫援助!', `MaleText_loc7`='¡%s solicita refuerzos!' WHERE `ID`=59399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발 맥주를 사용해 사우록 졸개에게 충격을 가하십시오!', `MaleText_loc4`='用闪电陈酿来攻击蜥蜴人爪牙！', `MaleText_loc5`='使用轟隆酒來擊倒薩烏洛克爪牙!', `MaleText_loc7`='¡Usa el brebaje relámpago para electrocutar a los secuaces saurok!' WHERE `ID`=59400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 사람이 졸개에게 충격을 가하는 동안, 다른 사람이 공격하면 즉시 처치할 수 있습니다.', `MaleText_loc4`='当一名玩家攻击蜥蜴人时，另一名玩家可以马上杀死它。', `MaleText_loc5`='當一名玩家擊倒薩烏洛克的時候，另一名可以立刻摧毀他。', `MaleText_loc7`='Mientras un jugador electrocuta a un saurok, otro puede destruirlo al instante.' WHERE `ID`=59401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 썬더포우 은거처를 구했어요!', `FemaleText_loc4`='你做到啦！雷掌阁守住了！', `FemaleText_loc5`='你成功了!雷爪靜修居安全了!', `FemaleText_loc7`='¡Lo han conseguido! ¡El Refugio Zarpa Atronadora está a salvo!' WHERE `ID`=59402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침 축배를 들기에 딱 좋은 맥주가 있지요. 첫 잔은 제가 사죠. 고마워요, 친구들!', `FemaleText_loc4`='而我也带了美酒来庆祝。第一轮我请。谢谢，朋友们！', `FemaleText_loc5`='我剛好有最適合用來慶祝的酒。第一輪我請了。謝啦，朋友們!', `FemaleText_loc7`='Y tengo la cerveza perfecta para celebrarlo. Invito a la primera ronda. ¡Gracias, amigos!' WHERE `ID`=59403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라오거라. 우릴 정식으로 소개할 터이니.', `MaleText_loc4`='快上前来，我们可以好好认识一下。', `MaleText_loc5`='過來，讓咱們交個朋友。', `MaleText_loc7`='Acérquense para que podamos presentarnos como es debido.' WHERE `ID`=59404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 가요! 저 밑에 또 큰 놈이 하나 보여요!', `MaleText_loc4`='我们继续走！我看到另一个大个的，就在那儿！', `MaleText_loc5`='我們繼續前進吧!我看到那裡有另一隻大的!', `MaleText_loc7`='¡Sigamos adelante! ¡Veo otro grande ahí abajo!' WHERE `ID`=59405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없어요! 계속 싸워야 해요!', `MaleText_loc4`='没时间了，弟兄们！我们要奋战到底！', `MaleText_loc5`='沒時間了，兄弟!我們得繼續戰鬥!', `MaleText_loc7`='¡No hay tiempo, hermanos! ¡Debemos seguir luchando!' WHERE `ID`=59406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아를 위하여!', `MaleText_loc4`='为了潘达利亚！！', `MaleText_loc5`='為了潘達利亞!!', `MaleText_loc7`='¡¡Por Pandaria!!' WHERE `ID`=59408;
