UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 보니까 배고픈데.', `MaleText_loc4`='我觉得肚子饿了。', `MaleText_loc5`='這讓我肚子好餓喔。', `MaleText_loc7`='Eso me dio hambre.' WHERE `ID`=59410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아를 위하여!', `MaleText_loc4`='为了潘达利亚！', `MaleText_loc5`='為了潘達利亞!', `MaleText_loc7`='¡Por Pandaria!' WHERE `ID`=59411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 사마끼들 호젠 잘못 건드렸다!', `MaleText_loc4`='这些蠢货把猢狲惹毛了！', `MaleText_loc5`='這些渾球惹錯猴人了!', `MaleText_loc7`='¡Esos mikos se meten kon makaku ekivocado!' WHERE `ID`=59413;
