UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞다! 장벽 너머로 돌아가! 응가들아!', `MaleText_loc4`='耶！滚回长城那边去吧，蠢货们！', `MaleText_loc5`='滾回你的牆外頭去，你這個便便人!', `MaleText_loc7`='¡Sí! ¡Al otro lado de la muralla, loko!' WHERE `ID`=59415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹는 거 아니야.', `MaleText_loc4`='别说吃的了。', `MaleText_loc5`='不准吃。', `MaleText_loc7`='No kome.' WHERE `ID`=59416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위를 위해!', `MaleText_loc4`='为了锦鱼人！', `MaleText_loc5`='為了錦魚人!', `MaleText_loc7`='¡Por los jinyu!' WHERE `ID`=59417;
