UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔던 곳으로 돌아가라, 사마귀 놈아.', `MaleText_loc4`='打哪儿来的回哪儿去吧，螳螂妖。', `MaleText_loc5`='回你來的地方去，螳螂人。', `MaleText_loc7`='Vuelve por donde viniste, mántide.' WHERE `ID`=59419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 뭘 봐도 배고프잖아.', `MaleText_loc4`='每样东西都让你很饿，晓。', `MaleText_loc5`='你看到什麼東西都會餓，曉。', `MaleText_loc7`='A ti todo te da hambre, Xiao.' WHERE `ID`=59420;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아를 위하여!', `FemaleText_loc4`='为了潘达利亚！！', `FemaleText_loc5`='為了潘達利亞!!!', `FemaleText_loc7`='¡¡¡Por Pandaria!!!' WHERE `ID`=59421;
