UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 복 구해 줘서 정말 고마워요.', `MaleText_loc4`='多谢你拯救了大部分好运气。', `MaleText_loc5`='非常感謝你給我們帶來好運的援救。', `MaleText_loc7`='Muchas gracias por este rescate tan afortunado.' WHERE `ID`=59423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사마귀 팔 조심해! 꽤 날카로워 보여!', `FemaleText_loc4`='小心螳螂妖的爪子，它们很锋利！', `FemaleText_loc5`='離那些爪子遠一點，看起來很銳利!', `FemaleText_loc7`='¡Cuidado con esas garras! ¡Parecen muy afiladas!' WHERE `ID`=59424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알을 처리하세요! 우리는 어미를 상대하죠!', `MaleText_loc4`='$p，注意那些卵！我们必须专心对付母兽！', `MaleText_loc5`='$p，那些蛋交給你!我們專心對付大隻的媽媽!', `MaleText_loc7`='¡Encárgate de esos huevos! ¡Y nosotros de la mamá!' WHERE `ID`=59425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알이 부화하기 전에 파괴하십시오!', `MaleText_loc4`='在蛋孵化前摧毁它们！', `MaleText_loc5`='在那些蛋孵化之前先摧毀它們!', `MaleText_loc7`='¡Destruye los huevos antes de que se abran!' WHERE `ID`=59426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 간 거야?', `MaleText_loc4`='他往哪儿走了？', `MaleText_loc5`='他往哪走了?', `MaleText_loc7`='¿Por dónde se fue?' WHERE `ID`=59427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 조심해!', `MaleText_loc4`='怎么回事？小心，可怕的圆圈来了！', `MaleText_loc5`='什麼鬼?小心，恐怖的圈圈來了!', `MaleText_loc7`='¿Pero ké graku...? ¡Kuidado, esfera mala!' WHERE `ID`=59428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈사태처럼 너를 덮쳐 버릴 테다!', `MaleText_loc4`='我要像雪崩一样碾碎你！', `MaleText_loc5`='我會像雪崩一樣攻擊你!', `MaleText_loc7`='¡Voy a ir a por ti como una avalancha!' WHERE `ID`=59429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 "제설기"라는 기술이다!', `MaleText_loc4`='我管这招叫“雪犁掌！”', `MaleText_loc5`='我稱這招為「吹雪」!', `MaleText_loc7`='¡Este movimiento se llama "el Quitanieves"!' WHERE `ID`=59430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 내 화를 돋궜겠다!', `MaleText_loc4`='你可把我惹火了！', `MaleText_loc5`='你惹火我了!', `MaleText_loc7`='¡Has provocado la cólera!' WHERE `ID`=59431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 짐에 너한테 딱 알맞은 게 하나 있지! 지금 찾아 주지. 아, 여기 없네. 여기도. 아, 여기 있었군. 내 죽음의 주머니 안에!', `MaleText_loc4`='我包里有你要的东西！在这里，让我找找。不对，不在这里，也不在那里。哦找到了，在我的噩运袋里！', `MaleText_loc5`='我的包包有東西要給你!等等，讓我找找。沒有，不在這，也不在那。喔，找到了，在我的必殺袋袋裡!', `MaleText_loc7`='¡Tengo algo para ti en mi saca! Déjame que lo busque. No, no está aquí, aquí tampoco. ¡Oh, aquí está, en mi FALTRIQUERA DE LA MUERTE!' WHERE `ID`=59432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='급소를 노려 주마!', `MaleText_loc4`='就在雪球里！', `MaleText_loc5`='正中雪球!', `MaleText_loc7`='¡Justo en las bolas de nieve!' WHERE `ID`=59433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 향에 취하면 좀 무서워지지!', `MaleText_loc4`='你不会喜欢我吸过熏香后的样子！', `MaleText_loc5`='你不會喜歡我吸一點薰香的時候!', `MaleText_loc7`='¡No te caeré tan bien cuando esté bajo los ligeros efectos del incienso!' WHERE `ID`=59434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금탑에서 만나세.', `MaleText_loc4`='我会在鎏金亭那儿见你。', `MaleText_loc5`='我會跟你在黃金寶塔碰頭。', `MaleText_loc7`='Te veré en la Pagoda Dorada.' WHERE `ID`=59435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉴 시간이 없네, $r.', `MaleText_loc4`='我们没时间休息了，$r。', `MaleText_loc5`='$r，我們沒時間休息了。', `MaleText_loc7`='No tenemos tiempo para descansar, $r.' WHERE `ID`=59436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 봉우리에서의 난리로 많은 양민이 갈 곳을 잃었네. 그들은 우리 골짜기의 문 안에서 안식처를 찾을 걸세.', `MaleText_loc4`='昆莱山的混乱局势使得许多无辜者背井离乡。他们会在我们的山谷中找到安身之处。', `MaleText_loc5`='崑萊峰的動亂讓許多無辜者流離失所。他們會在我們的關內找到棲身之處。', `MaleText_loc7`='La agitación de la Cima Kun-Lai ha desplazado a muchos inocentes. Encontrarán asilo tras nuestras puertas.' WHERE `ID`=59437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 할 수 있는 한은, 안식을 찾는 이들에게 안식을 줄 걸세.', `MaleText_loc4`='我们将竭尽所能，为那些寻求庇护之人提供安全场所。', `MaleText_loc5`='只要我們辦得到，我們就應當為那些尋求庇護的人們提供避風港。', `MaleText_loc7`='Si podemos, daremos refugio a todo aquel que lo necesite.' WHERE `ID`=59438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 최선을 다해 피난민을 보호할 것이나, 모구가 골짜기로 밀어닥치고 있는 상황에서는 이곳도 곧 위험해질지도 모르네.', `MaleText_loc4`='我们将尽全力保护难民，但在魔古族大举杀进山谷的当下，安全不会持续多久。', `MaleText_loc5`='我們會盡全力保護難民，但隨著魔古向山谷推進，或許這裡的安全無法持續太久。', `MaleText_loc7`='Protegeremos lo mejor que podamos a los refugiados, pero con los mogu presionando en el valle este sitio no estará a salvo por mucho tiempo.' WHERE `ID`=59439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일이 너무 많아!', `MaleText_loc4`='有太多工作要做了！', `MaleText_loc5`='有好多工作要做!', `MaleText_loc7`='¡Hay mucho que hacer!' WHERE `ID`=59440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체에서 피를 빨아내 주마!', `MaleText_loc4`='我要榨干你们身体里的鲜血！', `MaleText_loc5`='我會喝光你身上那紅色的血!', `MaleText_loc7`='¡Derramaré la sangre roja de sus cuerpos!' WHERE `ID`=59441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기에서 자네와 동료들은 내 손님일세. 내가 도와줄 일이 있다면 언제든지 말해주게.', `MaleText_loc4`='你和你的同伴都是锦绣谷的贵客。如果你们需要帮助，请尽管开口。', `MaleText_loc5`='在恆春谷你們就是我的客人。有什麼需要幫忙的，儘管告訴我。', `MaleText_loc7`='Tus compañeros y tú son mis invitados en el valle. No dudes en avisarme si hay algo que pueda hacer por ustedes.' WHERE `ID`=59442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제의 투사들이 이 계곡을 휩쓸 것이다!', `MaleText_loc4`='女皇的虫群将席卷整个山谷！', `MaleText_loc5`='女皇的子嗣將會橫掃整座山谷!', `MaleText_loc7`='¡El linaje de Su Majestad arrasará este valle!' WHERE `ID`=59443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀족의 긍지를 위해!', `MaleText_loc4`='为了螳螂妖的荣耀！', `MaleText_loc5`='為了螳螂人的驕傲!', `MaleText_loc7`='¡Por el orgullo de los mántides!' WHERE `ID`=59444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포가 어떤 모습인지 보여주마!', `MaleText_loc4`='我会让你尝尝恐惧的滋味。', `MaleText_loc5`='我會讓你瞧瞧恐懼的模樣。', `MaleText_loc7`='Les mostraré el rostro del miedo.' WHERE `ID`=59445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 쫓습니다! 도망가세요!', `MaleText_loc4`='%s正在追赶你。快跑！', `MaleText_loc5`='%s在追著你。快跑!', `MaleText_loc7`='¡%s te persigue! ¡Corre!' WHERE `ID`=59446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반드시 잡아 주마, 말랑한 것아...', `MaleText_loc4`='我要干掉你，软壳子……', `MaleText_loc5`='我會獵殺你的，軟皮膚的傢伙...', `MaleText_loc7`='Iré por ustedes, pieles blandas...' WHERE `ID`=59447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제의 투사들을 막을 수는 없다! 우리의 수는 무한하다!', `MaleText_loc4`='你无法阻挡女皇的虫群！我们的数量无穷无尽！', `MaleText_loc5`='你無法阻止女皇的子嗣!我們的數量無止無盡!', `MaleText_loc7`='¡No pueden detener al linaje de Su Majestad! ¡Nuestras filas son infinitas!' WHERE `ID`=59448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈 무더기를 클릭하여 뼈 쐐기 공격을 막아내십시오!', `MaleText_loc4`='点击骨堆以保护你免遭骨针的伤害！', `MaleText_loc5`='點擊一個骨堆來保護你不受骸骨尖刺傷害!', `MaleText_loc7`='¡Haz clic en un montón de huesos para defenderte de la Púa ósea!', `FemaleText_loc1`='뼈 무더기를 클릭하여 뼈 쐐기 공격을 막아내십시오!', `FemaleText_loc4`='点击骨堆以保护你免遭骨针的伤害！', `FemaleText_loc5`='點擊一個骨堆來保護你不受骸骨尖刺傷害!', `FemaleText_loc7`='¡Haz clic en un montón de huesos para defenderte de la Púa ósea!' WHERE `ID`=59449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 검은 바탕에 흰 무늬가 있는 걸까요, 흰 바탕에 검은 무늬가 있는 걸까요?', `MaleText_loc4`='你觉得熊猫人身上是黑底白斑，还是白底黑斑？', `MaleText_loc5`='你認為熊貓人是黑底白點，還是白底黑點?', `MaleText_loc7`='¿Dirías que los pandaren son oscuros con manchas blancas, o blancos con manchas oscuras?' WHERE `ID`=59450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 왜 철학을 좋아하는지 아세요? 왜냐하면 판다렌에게는 세상만사가 흑백이 아니거든요.', `MaleText_loc4`='你知道为什么熊猫人爱好哲学吗？因为对于他们来说，世事并不是非黑即白的。', `MaleText_loc5`='你知道為什麼熊貓人喜歡哲學嗎?因為對他們來說，事情並不是非黑即白的。', `MaleText_loc7`='¿Sabes por qué a los pandaren les encanta la filosofía? Porque para ellos las cosas no son solo blancas o negras.' WHERE `ID`=59451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부엌을 털린 판다렌이 어떻게 됐게요? 다크서클이 무릎까지 내려왔대요!', `MaleText_loc4`='那个厨房遭抢的熊猫人怎么了？他被骗啦！', `MaleText_loc5`='一個廚房被洗劫的熊貓人會發生什麼事?他被呼嚨了!', `MaleText_loc7`='¿Qué le dice un jinyu mago a otro? "¡Nada por aquí, nada por allá!"' WHERE `ID`=59452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 제일 값진 물고기가 뭐게요? 금붕어죠!', `MaleText_loc4`='全潘达利亚最宝贵的是什么鱼？是金鱼！', `MaleText_loc5`='全潘達利亞最有價值的魚是什麼魚?金魚!', `MaleText_loc7`='¿Cuál es el pez de mayor valor en toda Pandaria? ¡La carpa dorada!' WHERE `ID`=59453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주점에서 진위 여자를 꼬시려면 어떻게 해야 되게요? 떡밥을 던지면 되죠!', `MaleText_loc4`='你知道如何在酒馆里“钓到”一个锦鱼人妹子吗？下杆就行啦！', `MaleText_loc5`='你知道該如何在酒館釣到錦魚人女性嗎?放條釣線就對了!', `MaleText_loc7`='¿Sabes cómo llamamos a casarse con una jinyu? ¡"Echarle el anzuelo"!' WHERE `ID`=59454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백수 진위를 뭐라고 하는지 아세요? 잉어죠!', `MaleText_loc4`='你该如何称呼一个在天禅院受训的锦鱼人？僧鱼！', `MaleText_loc5`='你會怎麼稱呼一隻曾在天僧寺受訓的錦魚人?一隻禿魚!', `MaleText_loc7`='¿Cómo llamarías a un jinyu que ha entrenado en el Monasterio Tian? ¡Un pez monje!' WHERE `ID`=59455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주위의 물에서 힘을 끌어냅니다!', `MaleText_loc4`='%s抽取周围的水！', `MaleText_loc5`='%s牽引出身邊的水!', `MaleText_loc7`='¡%s absorbe el poder de las aguas circundantes!' WHERE `ID`=59456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피난민들 상황은 어떻습니까?', `MaleText_loc4`='迁居的难民们怎么样了？', `MaleText_loc5`='難民們狀況還好嗎?', `MaleText_loc7`='¿Cómo les va a los refugiados?', `FemaleText_loc1`='피난민들 상황은 어떻나요?', `FemaleText_loc4`='迁居的难民们怎么样了？', `FemaleText_loc5`='難民們狀況還好嗎?', `FemaleText_loc7`='¿Cómo les va a los refugiados?' WHERE `ID`=59457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기에 원군이 도착했습니다.', `MaleText_loc4`='援军已抵达山谷。', `MaleText_loc5`='援軍已抵達谷中。', `MaleText_loc7`='Han llegado refuerzos al valle.', `FemaleText_loc1`='골짜기에 원군이 도착했어요.', `FemaleText_loc4`='援军已抵达山谷。', `FemaleText_loc5`='援軍已抵達谷中。', `FemaleText_loc7`='Han llegado refuerzos al valle.' WHERE `ID`=59458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 골짜기는 어떻습니까?', `MaleText_loc4`='锦绣谷出什么事了？', `MaleText_loc5`='山谷這裡發生什麼事?', `MaleText_loc7`='¿Qué está pasando en el valle?', `FemaleText_loc1`='요즘 골짜기는 어떻습니까?', `FemaleText_loc4`='锦绣谷出什么事了？', `FemaleText_loc5`='山谷這裡發生什麼事?', `FemaleText_loc7`='¿Qué está pasando en el valle?' WHERE `ID`=59459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸을 강하게 단련하면, 마음은 따라온다.', `MaleText_loc4`='保持体魄强健，心智也将随之坚韧。', `MaleText_loc5`='保持肉體強壯，心靈就會跟著強健。', `MaleText_loc7`='Mantén tu cuerpo fuerte, y la mente también lo estará.' WHERE `ID`=59460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음이 영감에 굶주리면, 아름다운 것을 마음에게 먹이로 주세요.', `FemaleText_loc4`='当思维渴望灵感时，请看些美丽的东西。', `FemaleText_loc5`='當心靈缺乏靈感時，就以美好的事物餵養它。', `FemaleText_loc7`='Cuando la mente necesite inspiración, llénala con cosas bonitas.' WHERE `ID`=59461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 손님이로군. 자네를 보니 정말 기쁘구먼.', `MaleText_loc4`='哦，天呐，一个访客。你的到访让我非常开心。', `MaleText_loc5`='喔我的老天，來了個遊客。我真開心看到你的出現。', `MaleText_loc7`='Oh, $gun:una; visitante. Tu presencia me llena de alegría.' WHERE `ID`=59462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각지에서 몰려온 사람들이 마침내 문이 열리는 광경을 보았지요. 당신네 사람들 중에도 벌써 문으로 들어온 사람이 많답니다. 안에서 자기만의 위안과 안식을 찾아 보세요.', `MaleText_loc4`='许多人从四面八方赶来，亲眼见证大门的开启。确实，你的许多族人都已经进去了。你也去里面寻找慰藉和庇护吧。', `MaleText_loc5`='許多人從各地來到這裡，見證大門終於打開的瞬間。確實，許多你的同胞已經進到裡面了。進去尋找你的慰藉和棲身之地吧。', `MaleText_loc7`='Ha venido mucha gente de los cuatro costados del continente para ver cómo se abren las puertas. De hecho, muchos de tus compañeros ya se han adentrado. Busca tu propia paz en el interior.' WHERE `ID`=59463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각지에서 몰려온 사람들이 마침내 문이 열리는 광경을 봤지. 당신네 사람들 중에도 벌써 문으로 들어온 사람이 많아. 안에서 자기만의 위안과 안식을 찾아 봐.', `MaleText_loc4`='许多人从四面八方赶来，亲眼见证大门的开启。确实，你的许多族人都已经进去了。你也去里面寻找慰藉和庇护吧。', `MaleText_loc5`='許多人從各地來到這裡，見證大門終於打開的瞬間。確實，許多你的同胞已經進到裡面了。進去尋找你的慰藉和棲身之地吧。', `MaleText_loc7`='Ha venido mucha gente de los cuatro costados del continente para ver cómo se abren las puertas. De hecho, muchos de tus compañeros ya se han adentrado. Busca tu propia paz en el interior.' WHERE `ID`=59464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다행이군요. 최근 모구의 움직임이 심히 염려돼요. 거의 만 년 동안 이렇게 조직적으로 움직인 적이 없었거든요.', `FemaleText_loc4`='我很高兴听到这个消息。魔古族最近的行动给我造成很大的困扰。他们已经近万年没有如此有组织地行动过了。', `FemaleText_loc5`='我很高興聽到這件事。魔古最近的行動給我造成很大的困擾。近一萬年來，他們從沒出現過如此有組織的行為。', `FemaleText_loc7`='Me alegro de oír eso. Las últimas acciones de los mogu me preocupan mucho. No habían actuado de una manera tan organizada en casi diez mil años.' WHERE `ID`=59465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 웅덩이가 사악한 기운에 물들었다네. 모두 가로쉬 헬스크림 때문이지. 샤의 잔재가 아직도 남아 있다네.', `MaleText_loc4`='拜加尔鲁什·地狱咆哮所赐，圣池被黑暗能量腐蚀了。煞魔余孽也依然在四处流窜。', `MaleText_loc5`='神聖之池已經遭受黑暗力量的污染，都是卡爾洛斯·地獄吼幹的好事。煞的殘留物質還留著。', `MaleText_loc7`='Las Pozas Sagradas han sido corrompidas por energías oscuras por culpa de Garrosh Grito Infernal. Aún hay restos de sha.' WHERE `ID`=59466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='릴리안의 영혼이 $n|1을;를; 노려봅니다!', `FemaleText_loc4`='莉莉安的灵魂盯上$n了！', `FemaleText_loc5`='莉莉安的靈魂注視著$n!', `FemaleText_loc7`='¡El Alma de Lilian se fija en $n!' WHERE `ID`=59467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물이 당신의 몸에 닿자 격렬하게 반응합니다!', `MaleText_loc4`='流水对你的触碰做出了强烈反应！', `MaleText_loc5`='你的觸碰讓水有了激烈的回應!', `MaleText_loc7`='¡El agua reacciona violentamente al tocarla!' WHERE `ID`=59470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 떨어지지 말게. 적이 우리를 보지 못하도록 위장할 테니까.', `MaleText_loc4`='靠紧我。我会将我们伪装起来躲开敌人。', `MaleText_loc5`='緊跟著我。我會維持我們的偽裝騙過敵人。', `MaleText_loc7`='No te alejes de mí. Haré que nos camuflemos frente al enemigo.' WHERE `ID`=59471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 스노우드리프트가 그림자 속으로 사라지고는 자신의 환영들을 만들어 냅니다! 환영들을 공격하여 제거하십시오!', `MaleText_loc4`='雪流大师消失在暗影之中并造出了他的几个幻影！攻击这些幻影，驱散他们！', `MaleText_loc5`='雪迅大師消失在陰影中，創造出數個自身的幻象!攻擊幻象來使其消失!', `MaleText_loc7`='El maestro Ventisca Algente se desvanece en las sombras y crea ilusiones duplicadas de sí mismo. ¡Ataca a las ilusiones para disiparlas!' WHERE `ID`=59472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 스노우드리프트가 맨손으로 공격해 옵니다!', `MaleText_loc4`='雪流大师以他的近身格斗技巧对你发动了攻击！', `MaleText_loc5`='雪迅大師運用他的徒手搏鬥技巧攻擊你!', `MaleText_loc7`='¡El maestro Ventisca Algente te ataca con sus técnicas de puño contra puño!' WHERE `ID`=59473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치지 마, 결과는 똑같을 테니.', `MaleText_loc4`='别跑了，这不过是苟延残喘。', `MaleText_loc5`='不用逃了，該來的躲不掉。', `MaleText_loc7`='No huyan. Solo retrasan lo inevitable.' WHERE `ID`=59474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어와. 물이 딱 좋아!', `MaleText_loc4`='来吧，沐浴在流水之中！', `MaleText_loc5`='進來吧，水沒問題!', `MaleText_loc7`='¡Entren, el agua está buena!' WHERE `ID`=59475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음에 휩쓸려라.', `MaleText_loc4`='接受死亡的洗礼吧。', `MaleText_loc5`='讓死亡流過你的全身!', `MaleText_loc7`='Que la muerte los inunde.' WHERE `ID`=59476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 오게. 방어 병력 사이에 틈이 있네.', `MaleText_loc4`='快来！他们的防线上有道缺口。', `MaleText_loc5`='快過來。他們的防禦有缺口。', `MaleText_loc7`='Ven, rápido. Hay una brecha en sus defensas.' WHERE `ID`=59477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길이 트인 동안 가세. 동굴은 바로 앞일세.', `MaleText_loc4`='让我们趁道路畅通赶快前进，洞穴就在前面。', `MaleText_loc5`='等道路清空後我們就走。山洞就在前方。', `MaleText_loc7`='Vayamos mientras el camino esté despejado. La cueva está algo más adelante.' WHERE `ID`=59478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때를 기다려서 동굴 입구에 폭발물을 설치하게.', `MaleText_loc4`='先等一小会儿，然后把炸药放置在洞穴口。', `MaleText_loc5`='等待安全的時機，然後把炸藥放在洞口。', `MaleText_loc7`='Espera a un momento seguro, y coloca los explosivos en la entrada de la cueva.' WHERE `ID`=59479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 폭풍인도자가 당신의 존재를 감지하고 |cFFFF0000|Hspell:115009|h[에너지 집중]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='影踪派风暴使者对你的出现迅速作出反应，并开始|cFFFF0000|Hspell:115009|h[专注能量]|h|r！', `MaleText_loc5`='影潘風暴召喚者對你的存在做出反應，並開始|cFFFF0000|Hspell:115009|h[集聚能量]|h|r!', `MaleText_loc7`='¡Los extiendetormentas del Shadopan reaccionan a tu presencia y empiezan a |cFFFF0000|Hspell:115009|h[Enfocar energía]|h|r!' WHERE `ID`=59480;
