UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴에 침투할 준비가 됐습니다.', `MaleText_loc4`='我准备好进入洞穴了。', `MaleText_loc5`='我準備好要滲透進洞穴了。', `MaleText_loc7`='Ya puedo entrar a la cueva.', `FemaleText_loc1`='동굴에 침투할 준비가 됐어요.', `FemaleText_loc4`='我准备好进入洞穴了。', `FemaleText_loc5`='我準備好要滲透進洞穴了。', `FemaleText_loc7`='Ya puedo entrar a la cueva.' WHERE `ID`=59493;
