UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $p 님!$B$B완벽한 농부가 되면 어떤 기분이 들까요?', `MaleText_loc4`='你好，$p！$B$B做一名合格的农夫感觉如何呀？', `MaleText_loc5`='你好啊，$p!$B$B當一個全職農民的感覺如何?', `MaleText_loc7`='¡Hola, $p!$B$B¿Qué se siente al dedicarse de verdad a una granja?' WHERE `ID`=59496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사일을 할 때 이렇게... 특이한 냄새가 나는지는 정말 몰랐습니다.', `MaleText_loc4`='我从未想过种地也会有如此多……奇妙的感觉。', `MaleText_loc5`='我從沒想過務農會牽涉到這麼多...異國香料。', `MaleText_loc7`='No imaginaba que en la agricultura habría tantos... aromas exóticos.' WHERE `ID`=59497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 엄지손가락이 녹색으로 안 변했습니까?$B$B제 엄지손가락은 거의 녹색이 다 됐습니다.', `MaleText_loc4`='你的拇指已经变绿了？$B$B我的看起来也差不多一样。', `MaleText_loc5`='你的拇指變綠了沒?$B$B我的看起來幾乎跟之前沒兩樣。', `MaleText_loc7`='¿Tienes los pulgares verdes ya?$B$BLos míos están igual.' WHERE `ID`=59498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에헴.$B$B"하루가 정말 짧군요!"$B$B어떻습니까? 너무 억지스러운가요? 언덕골 시장에가서 이렇게 말하면 욕먹을 것 같지요?', `MaleText_loc4`='嗯哼。$B$B“我觉着白天的时间太短了！”$B$B听起来咋样？太强硬了？你觉得会在市集上流行起来吗？', `MaleText_loc5`='咳嗯。$B$B「我覺得一天24小時不夠用!」$B$B這聽起來如何?太牽強?你想它會在市場裡流行嗎?', `MaleText_loc7`='Ejem.$B$B"¡Supongo que el día no tiene bastantes horas!"$B$B¿Cómo ha sonado eso? ¿Muy forzado? ¿Crees que en el mercado se lo tragarían?' WHERE `ID`=59499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 농사일을 시작하기 전에는 제 식탁 위에 있는 음식이 어디서 오는지 생각해보지 않았습니다.$B$B농사라는 게 정말 더할 나위 없는 깨달음이더군요.', `MaleText_loc4`='在我们开始种地之前，我从没想过餐桌上的食物是从哪儿来的。$B$B可以说，这份经历让人很受启发！', `MaleText_loc5`='在我開始務農之前，我從沒想過餐桌上的食物是從哪裡來的。$B$B現在至少可以說這經驗讓人很有啟發!', `MaleText_loc7`='Nunca pensé de dónde venía la comida hasta que empecé este negocio agrícola.$B$B¡Esta experiencia ha sido como mínimo reveladora!' WHERE `ID`=59500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤, 농사에 대해 조언이 필요합니다.', `MaleText_loc4`='老愚，我需要一些务农的建议。', `MaleText_loc5`='小尹，我需要一些關於農業的建議。', `MaleText_loc7`='Yoon, necesito consejos sobre horticultura.', `FemaleText_loc1`='윤, 농사에 대해 조언이 필요해요.', `FemaleText_loc4`='老愚，我需要一些务农的建议。', `FemaleText_loc5`='小尹，我需要一些關於農業的建議。', `FemaleText_loc7`='Yoon, necesito consejos sobre horticultura.' WHERE `ID`=59501;
