UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문이 안 열려요.', `FemaleText_loc4`='大门被堵住了。', `FemaleText_loc5`='這門卡死了。', `FemaleText_loc7`='La puerta está atrancada.' WHERE `ID`=59511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바짝 마른 채소는 물만 주면 됩니다!$B$B여기 제 할아버지께서 남겨주신 오래되고 녹슨 물뿌리개를 쓰십시오. 밭 바로 옆에 있는 나무 그루터기에 있습니다.', `MaleText_loc4`='干枯的农作物需要水！$B$B你可以用我爷爷留下的那个生锈的老式洒水壶。我把它放在那个树桩旁边了，就在田地边上。', `MaleText_loc5`='乾巴巴的作物需要水!$B$B你可以用我爺爺留下來的那個生鏽的舊灑水壺，我把它擺在田地旁邊的那個樹幹根部。', `MaleText_loc7`='¡Los cultivos mustios solo necesitan agua!$B$BPuedes usar la regadera oxidada que dejó aquí mi abuelo. La tengo ahí, junto a ese tocón, al lado del campo.' WHERE `ID`=59512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 해 보지.', `MaleText_loc4`='让我来试试。', `MaleText_loc5`='讓我來。', `MaleText_loc7`='Deja que lo intente.' WHERE `ID`=59513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바짝 마른 채소는 물만 주면 됩니다!$B$B이제 살수기를 들여놨으니 마른 채소에 아주 쉽게 물을 줄 수 있지요! 밭 가장자리 쪽의 땅 위에 있을 겁니다.', `MaleText_loc4`='干枯的农作物需要水！$B$B有了洒水器我们就可以很轻松地照料它们了！那东西应该就在田地边上。', `MaleText_loc5`='乾巴巴的作物需要水!$B$B現在我們有了自動灑水機，要照顧它們應該很容易!灑水機就在農田旁邊的地上。', `MaleText_loc7`='¡Los cultivos mustios solo necesitan agua!$B$B¡Será fácil encargarse de ellos ahora que tenemos ese rociador! Debe de estar en el suelo, justo al borde del campo.' WHERE `ID`=59514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문 뒤에 바위라도 괴어 둔 건가? 꼼짝도 안 해!', `MaleText_loc4`='他们在门后面放了石头吗？它动都不动！', `MaleText_loc5`='他們把這門用石頭頂住了嗎?根本打不開呀!', `MaleText_loc7`='¿Han apuntalado la puerta con una roca o qué? ¡No hay quien la mueva!' WHERE `ID`=59515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서시오. 여기 열쇠가 있소.', `MaleText_loc4`='让开。我这儿有钥匙。', `MaleText_loc5`='站開點。我這邊有鑰匙。', `MaleText_loc7`='Apártate. Tengo la llave aquí mismo.' WHERE `ID`=59516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 맥주가 있습니다! 마음껏 들이키십시오!', `MaleText_loc4`='啤酒来了！喝光它们，小伙子！', `MaleText_loc5`='啤酒來了!大家乾杯!', `MaleText_loc7`='¡Ha llegado la cerveza! ¡Bebed, chicos!' WHERE `ID`=59517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 맥주군요. 딱 필요하던 것입니다. 감사합니다,', `MaleText_loc4`='啊……啤酒，弟兄们正需要它们。谢谢你，$p。', `MaleText_loc5`='啊...啤酒。正是我的手下需要的。謝謝你，$p。', `MaleText_loc7`='Ah, cerveza. Justo lo que necesitan mis hombres. Gracias.' WHERE `ID`=59518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 한판 멋지게 싸우고, 그 뒤에는 누군가가 맥주를 가져다주다니! 정말 끝내주는 날이군!', `MaleText_loc4`='我们先是干了一仗，接着就有人给我们送来了啤酒！今天还能再爽点吗？', `MaleText_loc5`='先是大戰一番，然後又有個傢伙帶啤酒來!今天還能發生更好的事嗎?', `MaleText_loc7`='¡Primero nos metemos en una pelea y ahora nos traen cerveza! ¡El día no podría ir mejor!' WHERE `ID`=59519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했어, 조조!', `MaleText_loc4`='干得好，乔乔！', `MaleText_loc5`='做得好，喬喬!', `MaleText_loc7`='¡Bien hecho, Jojo!' WHERE `ID`=59521;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장 한가운데로 맥주 배달이라고? 판다리아는 생각보다 살기 좋은 곳인지도 모르겠어...', `FemaleText_loc4`='递送啤酒，去战场中央？也许潘达利亚最终会成为一片乐土……', `FemaleText_loc5`='送啤酒?在戰場中?或許潘達利亞會是個適合安居的地方...', `FemaleText_loc7`='¿Reparto de cerveza, en medio de un campo de batalla? Pandaria no está tan mal, al fin y al cabo...' WHERE `ID`=59522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁금한 게 또 있습니다...', `MaleText_loc4`='我还有个问题……', `MaleText_loc5`='我有另一個問題...', `MaleText_loc7`='Tengo otra pregunta...', `FemaleText_loc1`='궁금한 게 또 있어요...', `FemaleText_loc4`='我还有个问题……', `FemaleText_loc5`='我有另一個問題...', `FemaleText_loc7`='Tengo otra pregunta...' WHERE `ID`=59523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장 한가운데로 맥주 배달이라고? 판다리아는 생각보다 살기 좋은 곳인지도 모르겠군...', `MaleText_loc4`='递送啤酒，去战场中央？也许潘达利亚最终会成为一片乐土……', `MaleText_loc5`='送啤酒?在戰場中?或許潘達利亞會是個適合安居的地方...', `MaleText_loc7`='¿Reparto de cerveza, en medio de un campo de batalla? A lo mejor Pandaria no está tan mal...' WHERE `ID`=59524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈틀거리는 흙은 어떻게 해야 합니까?', `MaleText_loc4`='我该如何处理被占据的土壤？', `MaleText_loc5`='我該怎麼處理被佔用的土地?', `MaleText_loc7`='¿Cómo me ocupo de la tierra ocupada?', `FemaleText_loc1`='꿈틀거리는 흙은 어떻게 해야 하나요?', `FemaleText_loc4`='我该如何处理被占据的土壤？', `FemaleText_loc5`='我該怎麼處理被佔用的土地?', `FemaleText_loc7`='¿Cómo me ocupo de la tierra ocupada?' WHERE `ID`=59525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억센 잡초는 어떻게 해야 합니까?', `MaleText_loc4`='我该如何处理难除的杂草？', `MaleText_loc5`='我該怎麼處理頑固的野草?', `MaleText_loc7`='¿Cómo me ocupo de los hierbajos obcecados?', `FemaleText_loc1`='억센 잡초는 어떻게 해야 하나요?', `FemaleText_loc4`='我该如何处理难除的杂草？', `FemaleText_loc5`='我該怎麼處理頑固的野草?', `FemaleText_loc7`='¿Cómo me ocupo de los hierbajos obcecados?' WHERE `ID`=59526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병든 채소는 벌레가 득시글거리지요. 으웩!$B$B할아버지의 살충제가 밭 근처의 땅에 있습니다. 살충제로 지저분한 벌레 놈들을 혼쭐내주십시오!', `MaleText_loc4`='遭虫害的农作物上爬满了害虫，真恶心！$B$B爷爷的杀虫剂就在田地边上——用它给那些臭虫子点颜色瞧瞧！', `MaleText_loc5`='長蟲的作物上覆蓋了許多寄生蟲。噁!$B$B爺爺的害蟲噴霧器就在田地附近，用它來給那些小蟲噴一個爽快!', `MaleText_loc7`='Los cultivos infestados están cubiertos de bichos. ¡Puaj!$B$BEl pulverizador contra bichos del abuelo está en el suelo cerca del campo. ¡Úsalo para darles una buena lección a esos bichejos!' WHERE `ID`=59527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으르르으으으아아아!', `MaleText_loc4`='呃——啊啊啊！', `MaleText_loc5`='咕哇啊啊啊啊!', `MaleText_loc7`='¡Grrr-r-r-RRAHHH!' WHERE `ID`=59528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병든 채소는 벌레가 득시글거리지요. 으웩!$B$B그래도 이제 우리는 맥파 방출기를 가지고 있으니 병충해를 손쉽게 제거할 수 있습니다. 이걸 켜면 해충제를 사용하는 일 없이 인도적인 방법으로 해충들을 쫓아낼 수 있습니다!$B$B아, 그러면 우리 채소는 유기농 채소로 분류되는 겁니까?', `MaleText_loc4`='遭虫害的农作物上爬满了害虫，真恶心！$B$B不过，既然我们有了脉波发射器，那就应该能轻而易举地消灭它们。用它来赶走那些害虫真是一种人道的方式，毫无杀虫剂成分！$B$B嘿，那是不是说我们的菜也算是有机蔬菜了？', `MaleText_loc5`='長蟲的作物上覆蓋了許多寄生蟲。噁!$B$B不過現在我們有脈衝波發射器，要除掉他們應該很容易。把它打開，然後用人性化的方式驅趕害蟲，不需使用農藥!$B$B嘿，這是不是代表我們的蔬菜是有機蔬菜?', `MaleText_loc7`='Los cultivos infestados están cubiertos de bichos. ¡Puaj!$B$BPero ahora que tenemos el emisor de ondas de pulsos será fácil librarse de ellos. Ponlo en marcha para ahuyentar a esa plaga de una forma humanitaria, ¡sin pesticidas!$B$BOye, ¿eso quiere decir que nuestras verduras cuentan como orgánicas?' WHERE `ID`=59529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 맥주나 배달하러 갑시다!', `MaleText_loc4`='我们来搬点该死的啤酒吧！', `MaleText_loc5`='送點該死的啤酒過去!', `MaleText_loc7`='¡Vamos a repartir CERVEZA de la buena!' WHERE `ID`=59530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 꿈틀거린단 말입니까? 뭐, 할아버지께서 해주셨던 말씀이 있습니다. "당근은 춤을 못춘다!"$B$B밭 바로 아래에 있는 뭔가가 채소를 잡아당기려고 하는 거지요!$B$B남은 채소라도 온전히 수확하고 싶다면, 그 밑에 있는 게 무엇이든 처치해버려야 할 것 같습니다. 가슴 아픈 일이라는 건 알지만, 그것도 다 농사일입니다.', `MaleText_loc4`='有东西在摇晃，嗯？好吧，正如爷爷常说的那样：胡萝卜可不会跳舞！$B$B有东西正试图从我们脚下拉走那些蔬菜！$B$B如果你想保护好这些农作物，恐怕你得杀掉那些在下边作祟的捣蛋鬼。是令人心碎，我知道，但这是工作的一部分。', `MaleText_loc5`='晃來晃去的是吧?嗯，就像我爺爺曾說過的:蘿蔔不會跳舞!$B$B那是我們底下有東西想把蔬菜拉走!$B$B如果你希望作物可以安安穩穩的，不管底下有什麼淘氣鬼，恐怕你都得把他殺了。令人心碎，我知道，但這是工作的一部分。', `MaleText_loc7`='Inquietos, ¿eh? Bueno, como decía el abuelo: ¡las zanahorias no bailan!$B$B¡Algo intenta quitarnos las verduras de debajo de los pies!$B$BMe temo que tendrás que matar a las alimañas que haya ahí debajo si quieres que dejen el cultivo en paz. Es desolador, lo sé, pero es parte del trabajo.' WHERE `ID`=59531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배달 완료! 맥주 배달도 이제 끝이군요.', `MaleText_loc4`='任务完成！没啤酒要送了。', `MaleText_loc5`='就這樣了!已經沒有啤酒了!', `MaleText_loc7`='¡Ya está! He terminado con el reparto de cerveza.' WHERE `ID`=59532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭으로 돌아가서 뭉친 팔을 좀 풀어야겠습니다.', `MaleText_loc4`='我得回石犁村去放松一下我这…该死的老胳膊了。', `MaleText_loc5`='我想我會回石犁村，讓累壞的雙手休息一下。', `MaleText_loc7`='Creo que volveré a Villarroca y descansaré los brazos.' WHERE `ID`=59533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 보면 채소에서 너무나도 아름다운 잎이 돋아납니다. 뜯어먹어 달라고 아주 애원을 하지요.$B$B할아버지께서는 초원매가 시장에 있는 그 누구보다도 맛좋은 호박을 잘 알아보고, 그리고 그... 뭐보다 빠르게더라...$B$B아, "화가 잔뜩 난 호젠보다 더 빠르게 달려든다"고 하셨지요.$B$B어쨌든 중요한 점은, 해로운 짐승으로부터 탐스러운 채소를 지켜내야만 한다는 겁니다.', `MaleText_loc4`='哎，有时候蔬菜长得如此漂亮，就好像是在祈求被人偷走一样。$B$B爷爷说一只平原鹰能比市集上的任何人更好地挑出一个上等的南瓜，然后能以比那啥还快的速度偷走它……呃……$B$B“比热锅上的猢狲还快。”$B$B我猜你会说诸如此类的话？$B$B关键是，你一定要保护诱人的农作物免遭虫害！', `MaleText_loc5`='嗯，有時蔬菜發芽的如此美妙，就像乞求別人來偷似的。$B$B爺爺說過，一隻敏銳的平原隼找出超讚南瓜的能力，比市場中的任何人都要來得強，而且牠抓走南瓜的速度比...呃...$b$b「比熱鍋上的猴人還快。」$B$B我猜，在他那個時代你可以說這種話吧?$B$B重點是，你必須從小動物手中保護這些誘人的作物!', `MaleText_loc7`='Bueno, a veces las verduras brotan TAN bonitas, que prácticamente piden que las roben.$B$BEl abuelo decía que un halcón de la llanura con buena vista podía ver una calabaza de competición mejor que nadie en el mercado, y se lanzaría por ella más rápido que un... esto... $B$B"Más rápido que un hozen en celo."$B$BSupongo que en esa época se podían decir esas cosas.$B$B¡La cuestión es que tendrás que defender los cultivos atrayentes de los animales!' WHERE `ID`=59534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡초투성이 채소에는 잡풀이 아주 가득하지요!$B$B밭고랑에서 잡초를 뽑던 방식과 똑같이 채소 주변에 난 잡풀을 제거해주시면 됩니다. 아주 힘들지요! 잡초를 움켜쥔 다음, 온 힘을 다해 뽑아내십시오. 그러면 결국 뽑혀 나올 겁니다.', `MaleText_loc4`='快闷死的农作物之间夹杂着一种杂草！$B$B你需要像对付长在地里的难除杂草一样对付它们——得花大力气！抓住那些烦人的杂草，尽全力拔出来。该做个了结了。', `MaleText_loc5`='這些快死掉的作物裡頭長了雜草!$B$B你要像處理土壤中頑固的雜草一樣解決它們，那就是埋頭苦拔!抓住那些玩意兒，然後用你的全力拉出來。它終究會到你手上的。', `MaleText_loc7`='¡Los cultivos secos tienen un hierbajo que los asfixia!$B$BOcúpate de ellos igual que de los hierbajos obcecados en un terreno: ¡a mano! Agárralos y tira con todas tus fuerzas. Acabarán cediendo.' WHERE `ID`=59535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야생 채소라?! 아, 정말 깜짝 놀라실 겁니다! 할아버지께서는 야생에서 자란 채소와 씨름해서 항복을 받아내던 이야기를 해주시곤 하셨습니다.$B$B할아버지께서는 "파를 거칠게 다루는 걸 두려워해서는 안 된다"라고 말씀하시곤 했습니다.$B$B저는 항상 할아버지가 조금 이상해지고 있다고 생각했지요.', `MaleText_loc4`='野生的？！真令人吃惊！爷爷常说他降服野生农作物的故事。$B$B“小愚，”他说，“别害怕去拍打你周围的大葱。”$B$B我一直觉得他很伟大。', `MaleText_loc5`='野生的?!這可真是個驚喜啊!爺爺曾說過關於它如何與野生作物搏鬥並馴服它們的故事。$B$B「小尹啊，」他曾這麼說，「不要害怕去打你的大蔥幾巴掌。」$B$B我一直以為他只是在說粗話。', `MaleText_loc7`='¡¿Salvajes?! ¡Qué sorpresa! El abuelo contaba historias sobre tener que luchar con sus cultivos salvajes para someterlos.$B$B"Yoonie", decía, "no tengas miedo de abofetear a las cebolletas".$B$BYo creía que solo estaba diciendo guarrerías.' WHERE `ID`=59536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못 자란 채소라! 정말 오랜만에 들어보는 말이군요!$B$B할아버지께서는 제가 자리에서 일어나거나 어디 가는 것을 싫어하면 못 자랐다고 부르곤 하셨습니다. 제 뒷목을 잡고 번쩍 들어 올리시곤 "못 자란 순무 같구먼!"이라고 말씀하시곤 했지요.$B$B못 자란 채소는 똑바로 자랄 수 있도록 도움의 손길이 필요합니다. 채소를 단단히 붙잡고 잡아당기십시오.', `MaleText_loc4`='小矮子！哈！这个词我很久没听到过了！$B$B当我拒绝起床或者去什么地方的时候，爷爷总是会那么叫我。按照他的说法，他会抓住我的脖子就像“拔出一株矮小的甜菜”那样把我提起来。$B$B这些农作物只要拔一下就能长直了。牢牢抓住它们，然后往上提。', `MaleText_loc5`='矮小作物!哈!我有好一段時間沒聽到這個名字了! $B$B以前我賴床或不想去某個地方時，我爺爺就會這樣叫我。他會抓著我的後頸，把我「像個矮菜頭」一樣提起來，他總是這麼說。$B$B這些作物只需要有人幫個手讓它豎起來。緊緊抓著它們然後舉起來。', `MaleText_loc7`='¡Enanos! ¡Ja! ¡Hacía tiempo que no oía ese término!$B$BEl abuelo me llamaba así cuando no quería levantarme para ir a algún sitio. Me agarraba por el cuello y me levantaba "como una naba enana", como él decía.$B$BEstos cultivos solo necesitan una ayudita para ponerse en vertical. Agárralos bien y tira.' WHERE `ID`=59537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덩굴 잡초라고요? 고약한 작은 악마 놈들이지요. 덩굴 잡초 뿌리는 땅 속 깊숙이 15미터 정도까지 파고들어갑니다. 잡초를 제거하려면 그걸 다 뽑아내야 하지요.$B$B땅 위에 보이는 잡초 끝을 붙잡고 반대편 끝부분이 보일 때까지 그냥 계속 잡아당기십시오. 그것 말고는 별 방법이 없습니다.', `MaleText_loc4`='纠缠的杂草，嗯？卑劣的小恶魔。它们会钻进地下差不多十五码——如果你想根除它们的话，就必须要连根拔起。$B$B抓住杂草露出地面的部分，然后一直向外拔，直到你看到根部被完全拔出来为止。就是这么回事。', `MaleText_loc5`='亂草堆，不是嗎?討厭的小惡魔。他們會深入地下約15碼，如果你想拔掉它，你必須把整根草全部拉出來。$B$B抓住雜草暴露在地面上的根部，然後一直往後拉，直到你看見它全部的根都被拉出來。除此之外沒有別的辦法。', `MaleText_loc7`='Enredaderas, ¿eh? Caen mal. Se meten en el suelo hasta los quince metros o así, y hay que sacarlas enteras para librarse de ellas.$B$BAgarra el extremo que sobresale y ve alejándote hasta que salga el otro extremo. No tiene más misterio.' WHERE `ID`=59538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은 토깽 놈들이 밭 아래로 땅을 파고 들어와 그 안에서 지냅니다. 채소가 주둥이 안에 곧바로 떨어지기를 바라면서 말이지요. 아무래도 놈들은 우리가 별 이유 없이 채소를 통째로 땅에 집어넣고만 있다고 생각하나 봅니다.$B$B''불법 거주자''... 할아버지께서는 놈들을 그렇게 부르셨습니다. 이런 토깽 놈들은 단호하게 짓밟아줘야 합니다. 발로 땅을 쾅쾅 굴러서 쫓아내버리십시오!', `MaleText_loc4`='有时候兔妖会在地里打洞然后住进去，盼着蔬菜能掉到它们头上——我想它们是觉得我们把蔬菜放进土里是有什么原因的。$B$B赖着不走的家伙，我爷爷是这么叫它们的。你得脚踏实地，我是说字面意思。你用脚使劲跺地面，把它们震出来！', `MaleText_loc5`='有時候兔妖會在土壤裡打洞並住在裡面，期待蔬菜自己掉到他們頭上。我想他們不知為何知道我們會把蔬菜全放在地底下。$B$B我爺爺說他們是「住霸王屋的」。你得踏下去。就是字面上的意思。重重踏在地面並把他們徹底趕出來!', `MaleText_loc7`='A veces los mures intentan excavar en los terrenos y vivir allí, esperando que les lluevan las verduras. Creo que piensan que las metemos enteras en el suelo por alguna razón.$B$BOcupas, así los llamaba el abuelo. Tienes que aplastarlos. Literalmente. ¡Pisotea el suelo y acaba con ellos!' WHERE `ID`=59539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억센 잡초라! 끝없는 골칫거리지요. 땅에서 스멀스멀 자라나 밭을 집어삼키려고 위협합니다.$B$B밭을 갈기 전에는, 잡초를 뽑아내야 합니다. 정말이지 잡초를 제거하는 데 쉬운 방법은 없습니다. 그냥 붙잡고 냅다 잡아당기는 거지요!$B$B할아버지 말씀에 따르면 "이름 모를 잡초보다 성질이 더욱 더러워져야 한다!"라고 하시더군요.', `MaleText_loc4`='难除的杂草！它们就是一种顽疾，会在土壤中蔓延，侵占你的土地。$B$B在你耕种之前，你需要先清除杂草。真的没什么窍门——就是抓住它们然后拔出来！$B$B按我爷爷的话说，“你得比那些杂草还顽固！”', `MaleText_loc5`='頑固的雜草!他們是不屈不撓的麻煩東西，在土壤裡滋長，威脅著要占領你的土地。$B$B在你能耕種這塊土地之前，你必須先把雜草除掉。這真的沒有什麼訣竅，就是抓住然後拔起來!$B$B照我爺爺的說法，「你得比雜草更壞!」', `MaleText_loc7`='¡Hierbajos obcecados! Son una molestia constante, invaden el terreno y amenazan con cubrir todas tus tierras.$B$BAntes de poder arar esa parcela, tienes que arrancar los hierbajos. No hay ningún truco, la verdad: ¡solo hay que agarrar y tirar!$B$BComo decía mi abuelo, "¡solo hay que ser más terco que el hierbajo!".' WHERE `ID`=59540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s|1이;가; |cFF006EFD$n|r에게 |cFFFF0000|Hspell:115297|h[영혼 도려내기]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s对|cFF006EFD$n|r施放了|cFFFF0000|Hspell:115297|h[放逐灵魂]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s對|cFF006EFD$n|r施放|cFFFF0000|Hspell:115297|h[逐出靈魂]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_warlock_demonsoul.blp:20|t¡%s lanza |cFFFF0000|Hspell:115297|h[Expulsar alma]|h|r sobre |cFF006EFD$n|r!' WHERE `ID`=59541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 줘서 고마워요!', `MaleText_loc4`='多谢营救！', `MaleText_loc5`='非常感激你的援救!', `MaleText_loc7`='¡Muchas gracias por el rescate!' WHERE `ID`=59542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 다 너 때문이야!', `MaleText_loc4`='都是你的错！', `MaleText_loc5`='這是你的錯!', `MaleText_loc7`='¡Esto es por tu culpa!' WHERE `ID`=59543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 때문이라니? 더러운 야크 산 건 내가 아니잖아.', `MaleText_loc4`='我的错？脏牦牛可不是我弄来的！', `MaleText_loc5`='我的錯?帶不乾淨的犛牛來的人可不是我。', `MaleText_loc7`='¿Por mi culpa? No fui yo el que compró un yak sucio.' WHERE `ID`=59544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살려 줘요! 그루멀 큰일 났어요.', `MaleText_loc4`='帮帮我！土地精遇到麻烦了。', `MaleText_loc5`='救命!咕嚕摩有麻煩了。', `MaleText_loc7`='¡Ayuda! Grúmel en problemas.' WHERE `ID`=59545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 좀 도와 줄래요?', `MaleText_loc4`='要不要帮土地精一把？', `MaleText_loc5`='幫幫一個咕嚕摩?', `MaleText_loc7`='¿Puedes ayudar a un grúmel?' WHERE `ID`=59546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 복덩이 물어내!', `MaleText_loc4`='把我的幸运符还给我！', `MaleText_loc5`='把幸運星還我!', `MaleText_loc7`='¡Devuélveme mi grisgrís!' WHERE `ID`=59547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 바뀌었나? 나는 폐허 마루 입구에 있을 테니 준비가 되면 그리로 오게.', `MaleText_loc4`='你改变主意了？你做好准备时，我会在废墟高地的入口等你。', `MaleText_loc5`='改變心意了嗎?等你準備好，我會在廢墟高地的入口等你。', `MaleText_loc7`='¿Has cambiado de idea? Te esperaré en la entrada al Alto de las Ruinas cuando estés $gpreparado:preparada;.' WHERE `ID`=59548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 폐허 마루 입구에서 기다리겠네.', `MaleText_loc4`='我会在废墟高地的基地等你。', `MaleText_loc5`='我會在廢墟高地的底部等你。', `MaleText_loc7`='Te esperaré en la base del Alto de las Ruinas.' WHERE `ID`=59549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈추게. 지나갈 때까지 기다리지.', `MaleText_loc4`='别动。让他们过去。', `MaleText_loc5`='停。讓他們過。', `MaleText_loc7`='Para. Deja que pasen.' WHERE `ID`=59550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 무리가 지나가기를 기다리세.', `MaleText_loc4`='我们等下一波吧。', `MaleText_loc5`='我們等待下一波。', `MaleText_loc7`='Esperemos a la siguiente oleada.' WHERE `ID`=59551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 싸움을 많이 하거나 그렇지는 않습니다. 확실히 무거운 걸 들고 그러기는 하지만... 뭔가를 때리거나 그러면 근육에 힘이 빠지면서 부들부들 떨리더군요.', `MaleText_loc4`='我不是个好勇斗狠的人。搬运重物，小事一桩……但当我遇到不得已的情况时，我的肌肉也会把那些懦夫和流氓碾碎。', `MaleText_loc5`='我不是一個喜歡打鬥的人。要我拿起重物，沒問題...但是要我揍人，我的肌肉就會變得虛軟無力。', `MaleText_loc7`='Yo no soy muy de pelear. Cargar cosas pesadas, desde luego... pero mis músculos se vuelven débiles y temblorosos cuando se trata de golpear algo.' WHERE `ID`=59552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그, 전장으로 갑시다.', `MaleText_loc4`='让我们上战场吧，泥盏。', `MaleText_loc5`='前往戰場吧，泥杯。', `MaleText_loc7`='Vamos hacia el campo de batalla, Caolín.', `FemaleText_loc1`='머드머그, 전장으로 가시죠.', `FemaleText_loc4`='让我们上战场吧，泥盏。', `FemaleText_loc5`='前往戰場吧，泥杯。', `FemaleText_loc7`='Vamos hacia el campo de batalla, Caolín.' WHERE `ID`=59553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음 만나는 분들입니다. 하지만 판다렌치고 나쁜 이는 없지요.', `MaleText_loc4`='我和他们素昧平生。不过我的熊猫人同胞绝不会是坏人。', `MaleText_loc5`='這輩子從沒遇過他們。這些熊貓人倒不是些壞傢伙。', `MaleText_loc7`='No los había visto en mi vida. Pero si son pandaren, no serán mala gente.' WHERE `ID`=59554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 코르가 스트롱메인이라 하오. 얼라이언스의 포로였다가, 한심하게도 맨몸으로 풀려난 타우렌이지. 반갑소, 판다렌.', `MaleText_loc4`='我叫科尔加·蛮鬃，曾经是联盟的俘虏，现在虽然逃了出来，但是手无寸铁。很高兴见到你，熊猫人。', `MaleText_loc5`='我是闊卡·強鬃，過去是聯盟的階下囚，現在則是孑然一身、手無寸鐵的牛頭人。很高興見到你，熊貓人。', `MaleText_loc7`='Korga Crin de Acero, antiguo prisionero de la Alianza; ahora tauren libre, aunque desarmado. Encantado de conocerte, pandaren.' WHERE `ID`=59555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 좀 도와 주세요!', `MaleText_loc4`='快来人帮帮我！', `MaleText_loc5`='來個人幫幫忙啊!', `MaleText_loc7`='¡Que alguien me ayude!', `FemaleText_loc1`='누가 좀 도와 주세요!', `FemaleText_loc4`='快来人帮帮我！', `FemaleText_loc5`='來人幫幫忙啊!', `FemaleText_loc7`='¡Que alguien me ayude!' WHERE `ID`=59565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 날 방해하지? 그 겁쟁이 낯짝을 내밀고 내 앞에 무릎 꿇어라!', `MaleText_loc4`='谁胆敢打搅我？跪下，抬头让我看看你们怯懦的表情！', `MaleText_loc5`='誰膽敢打擾我?現出你懦弱的面孔，跪在我的面前!', `MaleText_loc7`='¿Quién osa molestarme? Den la cara, cobardes, y arrodíllense ante mí.' WHERE `ID`=59566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하! 불쌍한 생명체들!', `MaleText_loc4`='啊哈哈哈！可怜的生物！', `MaleText_loc5`='啊哈哈哈!真是個可憐的東西!', `MaleText_loc7`='¡Ja, ja, ja! ¡Qué criatura tan patética!' WHERE `ID`=59567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁인데 여기서 좀 꺼내 주세요.', `MaleText_loc4`='拜托，你能帮我离开这儿吗？', `MaleText_loc5`='拜託，你能把我弄出這個地方嗎?', `MaleText_loc7`='¿Puedes sacarme de aquí, por favor?', `FemaleText_loc1`='부탁인데 여기서 좀 꺼내 주세요.', `FemaleText_loc4`='拜托，你能帮我离开这儿吗？', `FemaleText_loc5`='拜託，你能把我弄出這兒嗎?', `FemaleText_loc7`='¿Puedes sacarme de aquí, por favor?' WHERE `ID`=59568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물들한테서 도망치지 않으면, 놈들이 날 죽여 버릴 거예요!', `MaleText_loc4`='如果我不甩掉这些野兽，它们会杀了我的！', `MaleText_loc5`='如果我不離這些野獸遠一點，牠們會殺了我!', `MaleText_loc7`='¡Si me quedo cerca de estas bestias, me matarán!', `FemaleText_loc1`='이 괴물들한테서 도망치지 않으면, 놈들이 날 죽여 버릴 거예요!', `FemaleText_loc4`='如果我不甩掉这些野兽，它们会杀了我的！', `FemaleText_loc5`='如果我不遠離這些野獸，他們會殺了我!', `FemaleText_loc7`='¡Si me quedo cerca de estas bestias, me matarán!' WHERE `ID`=59569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏, 늙은 풋풋한테 까까로 줄 테다.', `MaleText_loc4`='蠢蛋会被老波波大口大口吃掉的。', `MaleText_loc5`='怪怪人會變成好吃的東東被老噗噗吃掉。', `MaleText_loc7`='Makakus serán manduka ñam ñam para el viejo Mu Mu.' WHERE `ID`=59570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이 우낏 먹을 거 포기해야 할 거다. 그렇게 해 줄 테다.', `MaleText_loc4`='该死的蠢蛋会放弃财物的，不管怎样。', `MaleText_loc5`='壞怪怪人無論如何保不住蛋蛋了。', `MaleText_loc7`='Dingue makakus sueltan sus rukos. De un modo u otro.' WHERE `ID`=59571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 우낏. 염소 놔두고 걸어 다닌다.', `MaleText_loc4`='傻乎乎的蠢蛋，走起路来也像个蠢货。', `MaleText_loc5`='笨怪怪人，陪羊羊走路。', `MaleText_loc7`='Makakus tontos. Andan por kabras.' WHERE `ID`=59572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신, 절 좀 풀어 주실래요?', `MaleText_loc4`='嘿，你，能帮我松开绳子吗？', `MaleText_loc5`='嘿，可以幫我鬆綁嗎?', `MaleText_loc7`='Eh, tú. ¿Te importaría liberarme?', `FemaleText_loc1`='거기 당신, 절 좀 풀어 주실래요?', `FemaleText_loc4`='嘿，你，能帮我松开绳子吗？', `FemaleText_loc5`='就是你。你可以幫我鬆綁嗎?', `FemaleText_loc7`='Eh, tú. ¿Te importaría liberarme?' WHERE `ID`=59573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이에요!', `MaleText_loc4`='这边！', `MaleText_loc5`='在這裡!', `MaleText_loc7`='¡Aquí!', `FemaleText_loc1`='이쪽이에요!', `FemaleText_loc4`='这边！', `FemaleText_loc5`='在這裡!', `FemaleText_loc7`='¡Aquí!' WHERE `ID`=59574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 뭘 잘못했다고 이러는 거야?', `MaleText_loc4`='我们对你做过什么？', `MaleText_loc5`='我們對你做了什麼?', `MaleText_loc7`='¿Pero qué te hemos hecho?', `FemaleText_loc1`='우리가 뭘 잘못했다고 이러는 거야?', `FemaleText_loc4`='我们对你做过什么？', `FemaleText_loc5`='我們對你做了什麼?', `FemaleText_loc7`='¿Pero qué te hemos hecho?' WHERE `ID`=59575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가고 싶어요.', `MaleText_loc4`='我只想回家而已。', `MaleText_loc5`='我只想回家。', `MaleText_loc7`='Tan solo quiero volver a casa.', `FemaleText_loc1`='집에 가고 싶어요.', `FemaleText_loc4`='我只想回家而已。', `FemaleText_loc5`='我只想回家。', `FemaleText_loc7`='Tan solo quiero volver a casa.' WHERE `ID`=59576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 부탁이에요.', `MaleText_loc4`='拜托，求你了。', `MaleText_loc5`='拜託，我求求你。', `MaleText_loc7`='Por favor, te lo ruego.', `FemaleText_loc1`='제발, 부탁이에요.', `FemaleText_loc4`='拜托，求你了。', `FemaleText_loc5`='拜託，我求求你。', `FemaleText_loc7`='Por favor, te lo ruego.' WHERE `ID`=59577;
