UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀의 친구가 곧 올 거다. 두고 보자!', `MaleText_loc4`='土地精的朋友就快来了，你等着瞧！', `MaleText_loc5`='咕嚕摩的朋友就快來了，你等著瞧!', `MaleText_loc7`='Los amigos de los grúmel vendrán pronto. ¡Ya lo verás!' WHERE `ID`=59580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 화가 난 거예요?', `MaleText_loc4`='干嘛这么生气？', `MaleText_loc5`='為什麼這麼生氣?', `MaleText_loc7`='¿A qué viene ese mal humor?' WHERE `ID`=59581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀이 뭘 잘못했다고 그래요?', `MaleText_loc4`='我们土地精怎么惹着你了？', `MaleText_loc5`='咕嚕摩對你做過什麼?', `MaleText_loc7`='¿Pero qué te han hecho los grúmel?' WHERE `ID`=59582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스라고요? 난파한 것이 그들의 배라면, 그들과 접촉해야 합니다. 조조, 함께 가지요.', `FemaleText_loc4`='联盟？如果坠毁的飞船是他们的，那就应该马上联络他们。乔乔，一起去吗？', `FemaleText_loc5`='聯盟?如果墜毀的是他們的船，我們得聯絡他們。喬喬，你能跟我來嗎?', `FemaleText_loc7`='¿La Alianza? Si su barco es el que se ha estrellado, tenemos que hablar con ellos. Jojo, ¿me acompañas?' WHERE `ID`=59583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 배를 제거해야 돼요, 코르가. 우리가 당신 선원을 도와주면, 우릴 도와줄래요?', `MaleText_loc4`='我们得把这船弄出来，科尔加。如果我们帮你救人，你会帮我们吗？', `MaleText_loc5`='我們需要移開那艘船，闊卡。如果我們幫助你的船員，你也會幫我們嗎?', `MaleText_loc7`='Korga, tenemos que desencallar ese barco. Si ayudamos a tu tripulación, ¿nos ayudarás?' WHERE `ID`=59584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이오, 새로운 친구여. 그런데 우리 기술자가 아직 숲 속에 있소. 그를 구출해야 하오.', `MaleText_loc4`='我很乐意，朋友。不过我们的工程师下落不明——我们得先去救他。', `MaleText_loc5`='樂意之至，我的新朋友。不過，我們的技師還流落在外，我們得先去救他。', `MaleText_loc7`='Con mucho gusto, camarada, pero nuestro ingeniero aún está en el bosque. Hay que rescatarlo antes.' WHERE `ID`=59585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이 친구가 사람 찾기 전문가죠. 맡겨 줘요.', `MaleText_loc4`='正好我们这儿有个找人的高手，对吧，$p？我们这就出发。', `MaleText_loc5`='我們有個尋人大師在此。對吧，$p?交給我們吧。', `MaleText_loc7`='Bueno, por aquí se nos da muy bien encontrar a la gente. Dalo por hecho.' WHERE `ID`=59586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $c님. 고마워요!', `MaleText_loc4`='谢谢你，$c。谢谢！', `MaleText_loc5`='謝謝你，$c。謝謝你!', `MaleText_loc7`='Gracias, $c. ¡Muchas gracias!', `FemaleText_loc1`='고마워요, $c님. 고마워요!', `FemaleText_loc4`='谢谢你，$c。谢谢！', `FemaleText_loc5`='謝謝你，$c。謝謝你!', `FemaleText_loc7`='Gracias, $c. ¡Muchas gracias!' WHERE `ID`=59587;
