UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁이에요, $c님. 놈들을 쿤라이에서 영영 내쫓아 주세요.', `MaleText_loc4`='拜托了，$c，将他们彻底赶离昆莱山。', `MaleText_loc5`='拜託你，$c，將他們永遠趕出崑萊。', `MaleText_loc7`='Por favor, $c, expúlsalos de Kun-Lai para siempre.', `FemaleText_loc1`='부탁이에요, $c님. 놈들을 쿤라이에서 영영 내쫓아 주세요.', `FemaleText_loc4`='拜托了，$c，将他们彻底赶离昆莱山。', `FemaleText_loc5`='拜託你，$c，將他們永遠趕出崑萊。', `FemaleText_loc7`='Por favor, $c, expúlsalos de Kun-Lai para siempre.' WHERE `ID`=59592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 네 바람의 축복이 따르길, 이방인이여.', `MaleText_loc4`='愿四风庇佑你，陌生人。', `MaleText_loc5`='陌生人，願四風保佑你。', `MaleText_loc7`='Recibe la bendición de los Cuatro Vientos.', `FemaleText_loc1`='당신에게 네 바람의 축복이 따르길, 이방인이여.', `FemaleText_loc4`='愿四风庇佑你，陌生人。', `FemaleText_loc5`='陌生人，願四風保佑你。', `FemaleText_loc7`='Recibe la bendición de los Cuatro Vientos.' WHERE `ID`=59593;
