UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이렇게 싸울 순 없어요.', `MaleText_loc4`='这样下去也不是办法。', `MaleText_loc5`='我們沒辦法這樣一直打下去。', `MaleText_loc7`='No podemos luchar así eternamente.' WHERE `ID`=59595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 경비대장 오큰쉴드 님에게 원군이 필요하다고 말해 주세요!', `MaleText_loc4`='$p，快去通知守卫队长橡盾。告诉他我们急需支援！', `MaleText_loc5`='$p，去跟守衛隊長橡木盾談談。告訴他我們需要援軍!', `MaleText_loc7`='Ve a hablar con el capitán Escudo de Roble. ¡Pídele refuerzos!' WHERE `ID`=59596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 내가 상대할 가치도 없다. 너! 이 하찮은 벼룩들을 밟아 버려라!', `MaleText_loc4`='你不配让我动手。你！碾碎这只微不足道的跳蚤！', `MaleText_loc5`='你不配我出手。你!過來打扁這卑賤的小蟲!', `MaleText_loc7`='No estás a mi altura. ¡Tú! ¡Ven a aplastar a esta pulga insignificante!' WHERE `ID`=59597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요마의 환영을 제거하자 호젠의 정신이 분열됩니다!', `MaleText_loc4`='移除酒灵的幻象对猢狲脆弱的心智造成了伤害！', `MaleText_loc5`='移除魂靈的幻象，能對猴人脆弱的心靈造成傷害!', `MaleText_loc7`='¡Eliminar la ilusión del espíritu daña la frágil mente de los hozen!', `FemaleText_loc1`='요마의 환영을 제거하자 호젠의 정신이 분열됩니다!', `FemaleText_loc4`='移除酒灵的幻象对猢狲脆弱的心智造成了伤害！', `FemaleText_loc5`='移除魂靈的幻象，能對猴人脆弱的心靈造成傷害!', `FemaleText_loc7`='¡Eliminar la ilusión del espíritu daña la frágil mente de los hozen!' WHERE `ID`=59598;
