UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 내려놔!', `MaleText_loc4`='放我下来！', `MaleText_loc5`='放我下來!', `MaleText_loc7`='¡Suéltame!' WHERE `ID`=59600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 불에 던지지 말아 줘요, 호젠 님!', `MaleText_loc4`='别把我丢进火里，猢狲！', `MaleText_loc5`='別把我丟到火裡，猴人!', `MaleText_loc7`='¡No me eches al fuego, hozen!' WHERE `ID`=59601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭘 잘못했나요? 왜 그렇게 성이 났어요?', `MaleText_loc4`='我做了啥对不起你们的事？干嘛这么生气？', `MaleText_loc5`='我對你做了什麼?為什麼這麼生氣?', `MaleText_loc7`='¿Pero qué te he hecho yo? ¿Por qué estás tan enfadado?' WHERE `ID`=59602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내겐 아직 복덩이가 있어. 지금 항복하지 않으면 불운이 찾아올 거야.', `MaleText_loc4`='我还有块幸运符。这是你们最后一次投降的机会，不然就等着倒霉吧。', `MaleText_loc5`='幸運星還在我身上，這是在你倒大楣前最後的投降機會。', `MaleText_loc7`='Todavía me queda un grisgrís. Es tu última oportunidad de rendirte antes de que te persiga la mala fortuna.' WHERE `ID`=59603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비! 모구가 공격해 옵니다!', `MaleText_loc4`='所有人都武装起来！魔古族攻过来了！', `MaleText_loc5`='大家武裝起來!魔古進攻了!', `MaleText_loc7`='¡Todo el mundo a las armas! ¡Los mogu nos atacan!' WHERE `ID`=59604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 본대가 북쪽 문을 돌파했습니다!', `MaleText_loc4`='他们的主力部队突破北门了！', `MaleText_loc5`='他們的主部隊已經突破了北門!', `MaleText_loc7`='¡Su batallón principal ha derribado la puerta del norte!' WHERE `ID`=59605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장 황금탑으로 돌아오라는 명령입니다!', `MaleText_loc4`='你需要立刻回到鎏金亭去！', `MaleText_loc5`='你必須立刻回到黃金寶塔去!', `MaleText_loc7`='¡Se te requiere de inmediato en la Pagoda Dorada!' WHERE `ID`=59606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요, $n. 앗... 정찰병이 오고 있네요.', `FemaleText_loc4`='干得好，$n。等等……我看到一个斥候过来了。', `FemaleText_loc5`='做得好，$n。等等...我看到一個斥候接近了。', `FemaleText_loc7`='Bien hecho, $n. Espera... veo a un explorador acercándose.' WHERE `ID`=59607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<패니 양이 불안하게 느릿느릿 걷습니다. 근처에서 벌어지는 전투 때문에 불안해하거나, 아니면 그 전투에 뛰어들고 싶어하는 것일 수도 있습니다.>', `MaleText_loc4`='<范妮小姐显得局促不安。她既为迫近的战斗而紧张，又渴望能够投身战场。>', `MaleText_loc5`='<范妮小姐不自在地走來走去。如不是她對附近的戰鬥感到緊張，就是她自己渴望著加入戰鬥。>', `MaleText_loc7`='<La señorita Fanny anda arrastrando los pies; se le nota incómoda. Quizá está nerviosa por el próximo combate, o está ansiosa por entrar en la refriega.>' WHERE `ID`=59608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<패니 양이 기대에 찬 눈빛으로 당신을 바라봅니다. 눈동자도 기대감으로 깜박입니다.>$b$b<패티 양을 위한 영광이 순간이 왔습니다.>', `MaleText_loc4`='<范妮小姐期待地看着你，眼神里充满了希望。>$b$b<范妮小姐的荣耀时刻已经到来。>', `MaleText_loc5`='<范妮小姐滿心期待地看著你。她的眼睛閃耀著期望的光芒。>$b$b<范妮小姐的光榮時刻終於到了。>', `MaleText_loc7`='<La señorita Fanny te mira expectante. Le brilla el ojo.>$b$b<Ha llegado el momento de gloria de la señorita Fanny.>' WHERE `ID`=59609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패니 양, 어서 갑시다.', `MaleText_loc4`='我们上，范妮小姐。', `MaleText_loc5`='我們走，范妮小姐。', `MaleText_loc7`='Vamos, señorita Fanny.', `FemaleText_loc1`='패니 양, 어서 가요.', `FemaleText_loc4`='我们上，范妮小姐。', `FemaleText_loc5`='我們走，范妮小姐。', `FemaleText_loc7`='Vamos, señorita Fanny.' WHERE `ID`=59610;
