UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이크티크 거대괴수가 당신을 삼켰습니다!', `MaleText_loc4`='你被伊克提克巨像吞下去了！', `MaleText_loc5`='你被伊克席克巨獸吞噬了!', `MaleText_loc7`='¡El coloso Ik''thik se te ha tragado!' WHERE `ID`=59612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련한 기술을 사용해서... 한 방 날리게!', `MaleText_loc4`='让你的武术训练发挥作用。会聚能量……然后出击！', `MaleText_loc5`='運用你接受過的武術訓練。集中你的能量...然後攻擊!', `MaleText_loc7`='Utiliza tu entrenamiento en artes marciales. Concentra la energía... ¡y GOLPEA!' WHERE `ID`=59613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 때리게!', `MaleText_loc4`='接着打！', `MaleText_loc5`='繼續攻擊!', `MaleText_loc7`='¡Sigue atacando!' WHERE `ID`=59614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 할 수 있네... 하지만 혼자서는 역부족이지. 무샨 야수의 도움이 필요할 걸세. 이름이 아마... 패니 양이었지?', `MaleText_loc4`='你能做到，$p……但你不能孤军奋战。你需要那头穆山兽的帮助，我记得她的名字叫范妮小姐。', `MaleText_loc5`='你能辦到，$p...但不是獨立完成。你會需要牡山獸的幫助。對，我想她的名字是范妮小姐。', `MaleText_loc7`='Puedes hacerlo... pero no sin ayuda. Necesitarás la ayuda de la bestia mushan. Creo que se llamaba señorita Fanny.' WHERE `ID`=59616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌들이여! 계속 싸우십시오! 대피 명령을 모두 취소하겠습니다. 돌밭은 아직 건재합니다!', `MaleText_loc4`='继续战斗，熊猫人！撤销所有的撤退命令！石犁村还没有丢！', `MaleText_loc5`='繼續戰鬥，熊貓人們!取消任何撤退命令!石犁村還沒有淪陷!', `MaleText_loc7`='¡Sigan luchando, pandaren! ¡Cancelen todas las órdenes de retirada! ¡Villarroca no ha caído aún!' WHERE `ID`=59617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셋...', `MaleText_loc4`='三……', `MaleText_loc5`='三...', `MaleText_loc7`='Tres...' WHERE `ID`=59618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘...', `MaleText_loc4`='二……', `MaleText_loc5`='二...', `MaleText_loc7`='Dos...' WHERE `ID`=59619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나...', `MaleText_loc4`='一……', `MaleText_loc5`='一...', `MaleText_loc7`='Uno...' WHERE `ID`=59620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쾅!', `MaleText_loc4`='轰隆！', `MaleText_loc5`='碰!', `MaleText_loc7`='¡BUM!' WHERE `ID`=59621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥. 모구 녀석들, 그 정도로는 어림도 없네!$B$B황금 연꽃이 어떤 희생을 치르더라도 골짜기를 지켜 낼 걸세.$B$B우리가 지키는 비밀은... 너무나 소중하고... 또 강력하다네. 샤오티엔의 손에 넘길 순 없지!', `MaleText_loc4`='哼，那些魔古族得再加把劲了！$B$B金莲教会死守山谷……不惜任何代价。$B$B我们守护的秘密太过珍贵……太过强大……决不能落入韶天之手！', `MaleText_loc5`='哼嗯。那些魔古得更努力試試!$B$B金蓮會將保衛這山谷...不惜一切代價。$B$B我們所保護的秘密太珍貴了...太強大了...絕不能落入嘯天的手裡!', `MaleText_loc7`='Bah. ¡Esos mogu tendrán que esforzarse más!$b$bEl Loto Dorado defenderá el valle... cueste lo que cueste.$b$b¡Los secretos que custodiamos son demasiado valiosos... demasiado poderosos... como para que caigan en manos del Shao-Tien!' WHERE `ID`=59622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리 방어선 안쪽에서 골짜기의 관리인을 공격하다니!$B$B이제 왜 우리에게 자네 도움이 필요한지 알겠는가?$B$B샤오티엔 모구가 골짜기에 침투했다네. 놈들을 이대로 두면 우리의 평온한 고향을 엉망으로 짓밟을 걸세.', `MaleText_loc4`='他们怎么能在距离我们防线如此遥远的大后方，攻击一位守护锦绣谷的金莲护法！$B$B你现在知道我们为什么需要你的帮助了吗？$B$B韶天魔古已经混进了山谷。如果再不加以制止，我们宁静的家园就会遭受难以言喻的毁灭！', `MaleText_loc5`='他們怎麼敢攻擊山谷的管理人，而且是在我們防線這麼深處的地方!$B$B你能理解為什麼我們需要你的幫助了嗎?$B$B嘯天魔古找到了進入山谷的方法。若不處理，他們會給我們平靜的家園帶來難以言喻的毀滅。', `MaleText_loc7`='¿Cómo se atreven a atacar a un cuidador del valle, tan lejos del frente defensivo?$b$b¿Entiendes ahora por qué necesitamos tu ayuda?$b$bLos mogu del Shao-Tien han encontrado la forma de entrar en el valle. Si no les paramos los pies, traerán una devastación inimaginable a nuestro pacífico hogar.' WHERE `ID`=59623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어두운 시대에는 불을 켜면 되죠.', `MaleText_loc4`='当黑暗来临，最好还是点亮一盏明灯。', `MaleText_loc5`='處於黑暗的時代時，最好點亮一盞燈。', `MaleText_loc7`='Cuando la oscuridad prevalece, lo mejor es encender una luz.' WHERE `ID`=59624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보고할 내용이 뭔가요?', `FemaleText_loc4`='你要汇报什么？', `FemaleText_loc5`='你的報告內容是什麼?', `FemaleText_loc7`='¿Tienes algún tipo de información?' WHERE `ID`=59625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기가 너무 평화로워. 너무.', `MaleText_loc4`='锦绣谷很平静。太平静了。', `MaleText_loc5`='山谷很和平。太和平了。', `MaleText_loc7`='El valle está tranquilo. Demasiado tranquilo.' WHERE `ID`=59626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는 가장 아름다운 게 가장 위험하지. 날 보라고.', `MaleText_loc4`='有时候最美丽的事物也是最致命的。看着我！', `MaleText_loc5`='有時最美麗的東西也最致命。看我就知道了!', `MaleText_loc7`='Algunas veces las cosas más bonitas son también las más mortíferas. No hay más que verme.' WHERE `ID`=59627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이러면 놈들도 주춤할 수밖에 없겠지. 잘했네, $n. 자네 혼자 돌아갈 수 있으리라 믿네.', `MaleText_loc4`='很好，那样应该能拖延一下他们的计划。干得好，$n。我相信你可以自己回去。', `MaleText_loc5`='嗯，那應該可以阻擋一下他們的計畫。做得好，$n。我相信你應該知道怎麼回去。', `MaleText_loc7`='Bueno, eso debería detener sus planes. Buen trabajo, $n. Supongo que puedes volver por tu propio pie.' WHERE `ID`=59628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허에 들어갈 생각이라면, 먼저 구오라이 폐허에 있는 쿤 오톰라이트와 이야기해 보게.', `MaleText_loc4`='如果你打算进入废墟，就得先去郭莱遗迹和奎·秋光谈一谈。', `MaleText_loc5`='如果你要滲透進廢墟裡，先到郭萊廢墟找昆·秋光談話。', `MaleText_loc7`='Si quieres infiltrarte en las ruinas, habla antes con Kun Fulgor Otoñal en las Ruinas de Guo Lai.' WHERE `ID`=59629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수레를 방어하십시오!', `MaleText_loc4`='保护马车！', `MaleText_loc5`='守住推車!', `MaleText_loc7`='¡Defiende el carro!' WHERE `ID`=59630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏?!', `MaleText_loc4`='搞什么鬼？！', `MaleText_loc5`='搞什麼鬼?', `MaleText_loc7`='¿Pero qué dingue?' WHERE `ID`=59631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우! 아우! 아우!', `MaleText_loc4`='嗷！嗷！嗷！', `MaleText_loc5`='噢!噢!噢!', `MaleText_loc7`='¡AY! ¡AY! ¡AY!' WHERE `ID`=59632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냠냠쩝쩝.', `MaleText_loc4`='摇头晃脑。', `MaleText_loc5`='喀滋喀滋啃。', `MaleText_loc7`='Ñam ñam.' WHERE `ID`=59633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 벽화의 비밀을 조금만 더 빨리 알아냈다면... 정말 많은 고통을 피할 수 있었을 것이네, $n.', `MaleText_loc4`='如果我能早点发现壁画就好了。很多事本来是可以避免的，$n。', `MaleText_loc5`='要是我能夠早一點理解這壁畫，許多的事情都能夠避免，$n。', `MaleText_loc7`='Ojalá hubiera descubierto el fresco antes. Se podrían haber evitado muchas cosas, $n.' WHERE `ID`=59634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅이... 파괴되었다... 우리도 어쩔 수 없었다...', `MaleText_loc4`='我们的家……被毁了……我们已经尽力了……', `MaleText_loc5`='我們的家...被毀了...我們不得已...', `MaleText_loc7`='Nuestros hogares... destruidos... Hicimos lo que debimos...' WHERE `ID`=59635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다리고 있었다, $p!', `MaleText_loc4`='我一直在等你，$p！', `MaleText_loc5`='我等你很久了，$p!', `MaleText_loc7`='¡Te estaba esperando, $p!' WHERE `ID`=59636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 영혼과 정령이여! 내 너희를 부르니 $p|1을;를; 처치해라!', `MaleText_loc4`='潘达利亚的灵魂和元素，我召唤你们！摧毁$p！', `MaleText_loc5`='潘達利亞的靈魂與元素啊，我呼喚你們!消滅$p!', `MaleText_loc7`='¡Espíritus y elementales de Pandaria, yo los invoco! ¡Destruyan a $p!' WHERE `ID`=59637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?! 내가 직접 끝장내 주마!', `MaleText_loc4`='什么？！我要亲自解决你！', `MaleText_loc5`='什麼?!我要親手解決你!', `MaleText_loc7`='¡¿Qué?! ¡Acabaré contigo yo mismo!' WHERE `ID`=59638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에게서 도둑질하는 놈들은 벌을 받을 것이다.', `MaleText_loc4`='严惩窃取魔古族权柄之徒。', `MaleText_loc5`='從魔古手上偷取東西的人都將受到懲罰。', `MaleText_loc7`='Aquellos que roben a los mogu recibirán su castigo.' WHERE `ID`=59639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망은 없다. 우리가 말하는 이 순간에도 너희의 소중한 골짜기는 우리 모구 손에 들어오고 있다.', `MaleText_loc4`='你的族人已经失败了。眼下，我们魔古族正在侵占你珍爱的山谷。', `MaleText_loc5`='你們的人輸了。即使是我們談話的現在，我們魔古都在攻佔你們珍愛的山谷。', `MaleText_loc7`='Tu pueblo está perdido. En este momento los mogu estamos conquistando su valle.' WHERE `ID`=59640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕은 다시 일어설 것이다!', `MaleText_loc4`='雷电之王将再次崛起！', `MaleText_loc5`='雷王將會再起!', `MaleText_loc7`='¡El Rey del Trueno se alzará de nuevo!' WHERE `ID`=59641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 정말 살아서 여길 나갈 수 있을까요?', `MaleText_loc4`='你真觉得我们能活着离开这里吗？', `MaleText_loc5`='你真的認為我們能夠活著離開這裡嗎?', `MaleText_loc7`='¿De verdad crees que vamos a salir de aquí con vida?' WHERE `ID`=59642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 길을 뚫었습니다. 이제 가면 됩니다.', `MaleText_loc4`='我把道路清理干净了。你可以出发了。', `MaleText_loc5`='我把道路清理乾淨了。你可以出發了。', `MaleText_loc7`='He despejado el camino. Ya puedes seguir.', `FemaleText_loc1`='내가 길을 뚫었어요. 이제 가면 돼요.', `FemaleText_loc4`='我把道路清理干净了。你可以出发了。', `FemaleText_loc5`='我把道路清理乾淨了。你可以出發了。', `FemaleText_loc7`='He despejado el camino. Ya puedes seguir.' WHERE `ID`=59643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 살아남다니 믿을 수가 없네요. 고마워요, 이방인!', `MaleText_loc4`='我真不敢相信我们做到了。谢谢你，陌生人！', `MaleText_loc5`='我不敢相信我們辦到了。陌生人，謝謝你!', `MaleText_loc7`='No me puedo creer que lo hayamos conseguido. ¡Gracias!' WHERE `ID`=59644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들! 마침 잘 왔구나. 씻길 야크가 많단다.', `MaleText_loc4`='我的孩子！来得正好，我们还有很多牦牛要洗。', `MaleText_loc5`='我的孩子!正好趕上。我們有很多犛牛要洗。', `MaleText_loc7`='¡Bien hecho! Justo a tiempo. Hay muchos más yaks que limpiar.' WHERE `ID`=59645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g잘생긴 악마 : 예쁜; $n, 이리로 와요. 석상 문제로 이야기할 게 좀 있거든요...', `FemaleText_loc4`='$n，$g你这帅气的恶魔:你这性感的尤物;，到这儿来。我们得谈谈关于雕像的事……', `FemaleText_loc5`='$n，$g你這個英俊的惡魔:妳這個性感的小東西;，過來這裡。我們得討論關於雕像的事...', `FemaleText_loc7`='$n, $gmacizo:belleza;, acércate. Tenemos que hablar sobre ciertas estatuas...' WHERE `ID`=59646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 이렇게 늦어지는 거예요? 다른 일이 많아요? 그 쪼그만 괴짜 리벳이 뭐 부탁이라도 했나 보죠?!', `FemaleText_loc4`='怎么慢吞吞的？你还有其它事情要忙吗？利维特那个小怪物让你帮他干活了？！', `FemaleText_loc5`='你怎麼來晚了?你在忙別的事嗎?是不是那個小怪物理弗特叫你幫他做事?!', `FemaleText_loc7`='¿A qué viene este retraso? ¿Tienes otros asuntos de los que ocuparte? ¡¿Acaso te ha encargado algo esa rata de Perno?!' WHERE `ID`=59647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 못난이가 왜 아직 살아 있죠? 그 녀석이 모구들을 살리고 있는 거 아녜요?', `FemaleText_loc4`='所以……那个巨魔怎么还没死？就是他复活了这些魔古族，是吧？', `FemaleText_loc5`='那麼...為什麼那個食人妖還沒死?他就是復活了所有魔古的傢伙，對吧?', `FemaleText_loc7`='A ver... ¿por qué todavía no está muerto ese trol? Él es el que está reviviendo a todos esos mogu, ¿no?' WHERE `ID`=59648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요마 바늘잎을 구하러 동굴에 들어가야 되는 날이 정말 싫어요.', `MaleText_loc4`='有时我不得不深入那个洞穴去采集提神松针，那段日子真叫人不堪回首。', `MaleText_loc5`='我最討厭我得到那個山洞裡去尋找靈針的日子了。', `MaleText_loc7`='Odio los días en los que tengo que entrar en las cuevas en busca de púas de duende.' WHERE `ID`=59649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왠지 내게 전할 좋은 소식이 있는 것 같은 느낌이 드는군요. 맞죠, $n?', `FemaleText_loc4`='我为什么会觉得你给我带来了好消息呢，$n？', `FemaleText_loc5`='$n，為什麼我覺得你有好消息要告訴我?', `FemaleText_loc7`='¿Por qué tengo la sensación de que no me traes buenas noticias, $n?' WHERE `ID`=59650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 미친 못난이 녀석의 고함 소리가 그쳤군요. 아, 행복해!', `FemaleText_loc4`='我再也听不见那疯子巨魔的叫喊声了。真是耳根清净啊！', `FemaleText_loc5`='我聽不見那隻瘋食人妖的鬼叫聲了。我的耳朵終於可以好好休息了!', `FemaleText_loc7`='Ya no se oyen más los gritos de ese trol. ¡Música para mis oídos!' WHERE `ID`=59651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌들을 구출해야 해요. 빨리 구출하지 않으면 이곳으로 도망친 판다렌들이 사랑하는 이들을 구한답시고 갔다가 목숨을 잃을 거예요!', `FemaleText_loc4`='我们得救那些熊猫人。如果不快点动手，我们这儿就会出现很多因为冒险寻亲而丧命的逃兵了！', `FemaleText_loc5`='我們得救出那些熊貓人。如果不加緊動作，就會有人叛逃去找他們的親屬然後害自己被殺!', `FemaleText_loc7`='Tenemos que rescatar a esos pandaren. ¡Como no lo hagamos pronto, vamos a tener a un montón de desertores camino de una muerte segura en busca de sus seres queridos!' WHERE `ID`=59652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성공했다는 거 알고 있었어요. 벌써 군대가 불어났으니까요! $n 당신 덕분에 감히 바랄 수도 없었던 만큼 상황이 좋아졌네요.', `FemaleText_loc4`='你成功的消息不胫而走，我们的队伍更壮大了！现在我们的规模比我之前所期望的还要好，这多亏了你，$n。', `FemaleText_loc5`='你成功的消息不脛而走。我們的軍隊增強了許多!都是因為你，我們現在的狀況比我期望的還好得多了，$n。', `FemaleText_loc7`='Las noticias sobre tu éxito te preceden. ¡Nuestros números han aumentado! Estamos en mucha mejor forma de lo que jamás hubiera soñado, y todo gracias a ti, $n.' WHERE `ID`=59653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 이게 누구야? 어인 일로 행차했나요, $n?', `FemaleText_loc4`='瞧啊，这是谁回来了！故地重游吗，$n？', `FemaleText_loc5`='喲，喲，喲，看看誰回來了!尊駕有何貴幹，$n?', `FemaleText_loc7`='¡Vaya, vaya, vaya, mira quién ha vuelto! ¿Te van mal las cosas, $n?' WHERE `ID`=59654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴은 안 돼!', `MaleText_loc4`='别打脸！', `MaleText_loc5`='不要打臉!', `MaleText_loc7`='¡En la cara no!' WHERE `ID`=59655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야운골의 정복자, 동풍의 쉼터의 용사인 $n|1을;를; 향해 모두 경례!', `FemaleText_loc4`='向$n致敬，伟大的野牛人征服者和东风之眠的勇士！', `FemaleText_loc5`='為$n歡呼，強大的揚古征服者與東風之眠的勇士!', `FemaleText_loc7`='¡Aclamad a $n, gran $gconquistador:conquistadora; de los yaungol y $gcampeón:campeona; del Reposo Oriental!' WHERE `ID`=59656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑바로 우리한테 오고 있어요!', `MaleText_loc4`='它冲我们过来了！', `MaleText_loc5`='它正朝我們而來!', `MaleText_loc7`='¡Se dirige justo hacia nosotros!' WHERE `ID`=59657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석들을 화나게 하지 마요!', `MaleText_loc4`='不要激怒他们！', `MaleText_loc5`='別惹他們生氣!', `MaleText_loc7`='¡No los enfades!' WHERE `ID`=59658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽은 척해요! 그러면 재미없어서 가 버릴 거예요.', `MaleText_loc4`='装死！这会令他们觉得无趣，继而走开。', `MaleText_loc5`='快裝死!讓他們感到無聊而離開。', `MaleText_loc7`='¡Hazte el muerto! Se cansarán y nos dejarán en paz.' WHERE `ID`=59659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 좀 있을 건가요, $n?', `FemaleText_loc4`='你打算回来转一转吗，$n？', `FemaleText_loc5`='你會在這待一陣子嗎，$n?', `FemaleText_loc7`='¿Te quedarás un tiempo, $n?' WHERE `ID`=59660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제까지 여기 있어야 장군님이 행군 명령을 내리실까나.', `FemaleText_loc4`='我想知道在将军给我们下达行军命令之前，我们还要在这里待多久。', `FemaleText_loc5`='不知道在將軍下達行軍命令前我們得在這裡待多久。', `FemaleText_loc7`='Me pregunto hasta cuándo estaremos aquí antes de que el general nos dé la orden de marchar.' WHERE `ID`=59661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 혹시 오그리마에 갔다 왔어요? 새로운 소식 없어요?', `FemaleText_loc4`='$n，你回过奥格瑞玛了吗？有什么消息？', `FemaleText_loc5`='$n，你有回去過奧格瑪嗎?有什麼消息?', `FemaleText_loc7`='¿Has pasado por Orgrimmar, $n? ¿Traes alguna noticia?' WHERE `ID`=59662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야영지의 소문을 듣자 하니, 서쪽의 장벽 너머에 있는 탕랑 평원에는 벌레가 득시글거린다는군요. 어떻게 생각해요, $n?', `FemaleText_loc4`='你说的那个营地往西方向，在城墙的另一边。螳螂高原到处都是虫子，你怎么看，$n？', `FemaleText_loc5`='營裡的人都在說西邊長城的另一頭螳螂荒原充斥著蟲子。你怎麼想，$n?', `FemaleText_loc7`='Se rumorea que al otro lado de la muralla, en el oeste, las Estepas de Tong Long están infestadas de bichos. ¿Qué opinas, $n?' WHERE `ID`=59663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뜯어 먹을 신선한 시체를 구할 수 있다면 무슨 짓이라도 할 텐데. 어머, 내가 소리 내 말했나요?', `FemaleText_loc4`='我可不是来给别人当午餐肉啃的。哎呀，我是不是说得太大声了？', `FemaleText_loc5`='如果有個新鮮的屍體給我吃，要我做什麼都可以。啊，我大聲說出來了嗎?', `FemaleText_loc7`='Lo que daría por un cadáver fresco que llevarme a la boca... Vaya, ¿he dicho eso en alto?' WHERE `ID`=59664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 되겠어요. 당신네 귀여운 곰퉁이들한테는 내 말이 통 안 먹히네요. $n, 이리 와서 신참들한테 한 수 가르쳐 줄래요?', `FemaleText_loc4`='我放弃。我没法给你们这些可爱的小熊讲明白了。$n，你能过来给这些新手演示一下吗？', `FemaleText_loc5`='我放棄。我教不會你們這群可愛的呆熊。$n，你可以過來這裡為這些菜鳥示範一下嗎?', `FemaleText_loc7`='Me rindo. No puedo con debiluchos como ustedes. $n, ¿te importa acercarte y enseñar a estos novatos cómo se hace?' WHERE `ID`=59665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 갔어요?', `MaleText_loc4`='他们走了吗？', `MaleText_loc5`='他們走了沒?', `MaleText_loc7`='¿Ya se han ido?' WHERE `ID`=59666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 여자한테 뭐라고 말했다고?!', `FemaleText_loc4`='你告诉她什么？！', `FemaleText_loc5`='你跟他說了啥?!', `FemaleText_loc7`='¡¿QUE LE HAS DICHO QUÉ?!' WHERE `ID`=59667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 북풍의 차디찬 원한을 허락하마!', `MaleText_loc4`='$n，我赐予你北风的冷酷复仇之力！', `MaleText_loc5`='$n，我將北風冰冷的復仇借給你!', `MaleText_loc7`='¡Te ofrezco la fría venganza de los vientos del norte!' WHERE `ID`=59668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 뭐부터 만들어 볼까? 향? 모닥불 장작? 아니면 영원히 불타는 향초?', `MaleText_loc4`='嗯。首先应该做什么？熏香？营火原木？永燃蜡烛？', `MaleText_loc5`='嗯嗯。要先做什麼呢?薰香?營火木材?永燃蠟燭?', `MaleText_loc7`='Mmm. ¿Por dónde empezamos? ¿Incienso? ¿Leña para la hoguera? ¿Vela de llama perpetua?' WHERE `ID`=59669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 그루멀 시장에 복덩이가 굴러들어 왔군요? 우리 만남에서 복 냄새가 나네요.$b$b제 이름은 행운의 여덟동전이에요. 제 최고의 복덩이를 따라 지은 이름이지요. 가장 냄새가 강한 복을 주는 복덩이라고요.', `MaleText_loc4`='啊！土地精大集市迎来了一位幸运儿？我感觉我们的会面会带来好运。$b$b我叫好运的八铜钱。我的名字是根据我最好的幸运符起的，它总能给我带来无比的好运气。', `MaleText_loc5`='啊!有個幸運星來到偉大的咕嚕摩市集了?我從我們的會面裡嗅出好運的味道。$b$b大家叫我好運八錢。這名字來自我最棒的幸運星，它有著聞起來最濃烈的好運。', `MaleText_loc7`='¡Ah! Grisgrís viene al gran Bazar Grúmel, ¿eh? Nuestra reunión huele a fortuna.$b$bMe llaman Fortuno el Calderillas por mi mejor grisgrís, el que tiene un olor a fortuna más acre.' WHERE `ID`=59670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그루멀이라고 해요. 우리는 모든 산길을 꿰고 있지요.$b$b주로 동쪽의 장벽 근처에 있는 음영파 요새로 보급품을 나르는 일을 해요.$b$b그런데 요즘은 워낙 시절이 뒤숭숭하다 보니, 길을 떠나는 그루멀이 아주 위험해요.', `MaleText_loc4`='我们是土地精。我们熟悉山中所有的道路。$b$b最重要的是，我们负责将物资运到东边的长城。影踪派的堡垒。$b$b但眼下是黑暗时期，土地精在途中面临着巨大的危险。', `MaleText_loc5`='我們是咕嚕摩。我們熟悉所有通過山脈的路徑。$b$b最重要的是，我們負責將補給品運到東邊的長城，影潘的堡壘。$b$b但這是一個黑暗的時代，咕嚕摩在路上面對著極大的危險。', `MaleText_loc7`='Somos los grúmel. Conocemos todos los pasos de las montañas.$b$bPrincipalmente, nos dedicamos a traer suministros a la Gran Muralla del este, el bastión del Shadopan.$b$bPero es una época oscura y los grúmel nos enfrentamos a grandes peligros por el camino.' WHERE `ID`=59671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번에 해내다니! 자, 불꽃을 사원 꼭대기로 가져가서 그곳에 있는 두루마리를 태우게.', `MaleText_loc4`='你居然一次就成功了！快，把这火焰带到寺院顶层去，烧掉挂在那里的卷轴。', `MaleText_loc5`='你竟然一試就成功了!現在，把火焰帶到寺廟頂端，燒掉你在那裡找到的卷軸。', `MaleText_loc7`='¡Al primer intento! Rápido, lleva la llama a lo alto del templo y quema el pergamino que allí yace.' WHERE `ID`=59672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 서 있는 이 땅, 셴진 수가 깊은 고통을 겪고 있네. 원인은 모르겠으나, 내 온몸으로 그 아픔을 느낄 수가 있네.', `MaleText_loc4`='神真子，也就是我们脚下的这片土地，正承受着极大的痛苦。虽然我不知道这痛苦从何而来，但我对此感同身受。', `MaleText_loc5`='神真子，我們腳下所踏的這塊土地，正承受著深切的痛苦。儘管不知道起因，但我能感同他所受的這份痛楚。', `MaleText_loc7`='Shen-zin Su, la misma tierra que pisamos y en la que nos encontramos, siente un profundo dolor. Aunque desconozco la causa, puedo sentir su malestar en mi propia piel.' WHERE `ID`=59674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛말에 따르면 네 정령의 목소리를 통하면 셴진 수와 이야기할 수 있다고 하네. 허나 지금은 정령들이 사원에서 도망쳐 버린 데다, 그 힘도 예전 같지가 않지.', `MaleText_loc4`='古代的智慧告诉我们，必须通过四位元素之灵之口，才能与神真子交谈。可是元素之灵们都离开了五晨寺，他们的力量正在衰减。', `MaleText_loc5`='在古老的傳說中，提到可以透過四位元素之靈的聲音和神真子交談。但這些魂靈已經逃離我們的寺廟，祂們的力量也正在消逝。', `MaleText_loc7`='La sabiduría ancestral menciona que se puede hablar con Shen-zin Su a través de los cuatro espíritus elementales. Sin embargo, los espíritus han huido de nuestro grandioso templo y sus poderes se están desvaneciendo.' WHERE `ID`=59675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네는 내가 오랫동안 기다린 영웅일세. 자네가 정령을 찾아내고 다시 한데 모아서 셴진 수와 이야기를 하고 이 땅을 치유해야 하네.', `MaleText_loc4`='$n，你就是我期待已久的勇士。你将要找回并重聚元素之灵。这样，我们才能与神真子沟通并治愈我们的家园。', `MaleText_loc5`='$n，你就是我一直等待的英雄。你將找到並重聚元素之靈，並讓我們得以和神真子交談，治癒我們的土地。', `MaleText_loc7`='$n, eres $gel campeón:la campeona; que he estado esperando durante tanto tiempo. Serás $gel elegido:la elegida; para buscar y reunir a los espíritus elementales con el fin de comunicarnos con Shen-zin Su y curar nuestra tierra.' WHERE `ID`=59676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 가까이 있는 정령은 불의 정령 후오일세. 내가 가장 아끼는 제자들을 찾아가서 후오에 대해 아는 게 있는지 알아 보게.', `MaleText_loc4`='最近的一位元素之灵是上古火灵燧焰。我要你去见见我的几个得意弟子，并向他们询问燧焰的消息。', `MaleText_loc5`='距離此地最近的火之靈是霍。我希望你去找我最有天份的幾名弟子，了解他們對霍有什麼了解。', `MaleText_loc7`='El espíritu más cercano es Huo, el espíritu de la llama. Te voy a pedir que te reúnas con algunos de mis estudiantes más sobresalientes y que adquieras sus conocimientos sobre Huo.' WHERE `ID`=59677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간은 우리 편이 아닐세. 최대한 빨리 떠나게.', `MaleText_loc4`='我们的时间不多了，尽快动身吧。', `MaleText_loc5`='我們的時間有限，準備好就速速前往。', `MaleText_loc7`='El tiempo no nos acompaña. Dirígete allí en cuanto puedas.' WHERE `ID`=59678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='넌 혼자가 아니다! 침략자들에게 내 폭풍을 퍼부어라!', `FemaleText_loc4`='你们并非孤军奋战！将我的风暴倾泻在敌人头上吧！', `FemaleText_loc5`='你並不是孤身作戰!讓這些入侵者嚐嚐我的暴風吧!', `FemaleText_loc7`='¡No te he abandonado! ¡Desata mi tormenta sobre los invasores!' WHERE `ID`=59679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령이 화가 났습니다. 지금 제단에 들어가면 위험합니다...', `MaleText_loc4`='上古火灵十分烦躁。现在进入神龛是很危险的……', `MaleText_loc5`='火靈十分生氣。現在進入廟裡會很危險...', `MaleText_loc7`='El espíritu del fuego está alterado. Es peligroso entrar en el santuario ahora mismo...' WHERE `ID`=59680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 농사꾼들이 저보고 도시 출신이라고 말하는 것 들으셨습니까?$B$B물론 제가 새벽의 꽃에서 자라긴 했지만, 할아버지 댁에 몇 번 들러보긴 했단 말입니다. 순무과 당근이 어떻게 다른지도 알고요! 어쨌든 주황색과 흰색 차이 아닙니까!$B$B할아버지께서는 돌아가시면서 제게 농장을 남겨주셨습니다. 그러니 할아버지를 위해서라도 온 힘을 다할 겁니다! 그런데 어떻게 저 농사꾼들에게 제 실력을 증명해 보여야 할까요?', `MaleText_loc4`='你听见那些阡陌客是怎么评价我这个城里人的吗？$B$B没错，我是在晨芳园里长大的，可我也去过爷爷家几次。我知道胡萝卜和芜菁的区别！毕竟一个红一个白！$B$B爷爷过世后，他把农场留给了我，所以我会为他竭尽全力！但我该怎么赢得那些阡陌客的信任？', `MaleText_loc5`='你有聽說那些耕者怎麼說我是個城市佬的嗎?$B$B沒錯我是在晨綻長大的，但我來看過我爺爺幾次。我知道胡蘿蔔和菜頭的差別!畢竟一個是橘色而一個是白色!$B$B爺爺過世後把農場留給了我，所以我要為了他竭盡我所能!但我要怎樣才能證明給那些耕者看?', `MaleText_loc7`='¿Has oído a los Labradores que me llaman "zarpa urbanita"?$b$bSí, crecí en Floralba, pero visité a mi abuelo varias veces. ¡Sé distinguir una zanahoria de una naba! ¡Una es naranja y la otra es blanca!$b$bCuando el abuelo falleció, me dejó la granja, ¡así que lo haré por él! ¿Pero cómo puedo demostrárselo a los Labradores?' WHERE `ID`=59681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 화염을 일으키고, 그 열기가 네 몸을 타고 흐르는 것을 느껴라.', `MaleText_loc4`='很好。引导火焰，感受它们在你体内的流动。', `MaleText_loc5`='很好。導引火焰，感受他們穿透你的身體。', `MaleText_loc7`='Bien, canaliza las llamas, siéntelas fluir a través de ti.', `FemaleText_loc1`='좋다. 화염을 일으키고, 그 열기가 네 몸을 타고 흐르는 것을 느껴라.', `FemaleText_loc4`='很好。引导火焰，感受它们在你体内的流动。', `FemaleText_loc5`='很好。導引火焰，感受他們穿透你的身體。', `FemaleText_loc7`='Bien, canaliza las llamas, siéntelas fluir a través de ti.' WHERE `ID`=59682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주문을 배워두면 우리에게 맞서는 적의 타락을 깨끗이 씻어낼 수 있을 것이다.', `MaleText_loc4`='好好学习这个法术，用它来烧尽我们敌人身上的污秽。', `MaleText_loc5`='好好學習這個法術，因為它會燒盡與我們為敵者的污染。', `MaleText_loc7`='Apréndete bien este encantamiento porque quemará la contaminación de todos aquellos que se oponen a nosotros.', `FemaleText_loc1`='이 주문을 배워두면 우리에게 맞서는 적의 타락을 깨끗이 씻어낼 수 있을 것이다.', `FemaleText_loc4`='好好学习这个法术，用它来烧尽我们敌人身上的污秽。', `FemaleText_loc5`='好好學習這個法術，因為它會燒盡與我們為敵者的污染。', `FemaleText_loc7`='Apréndete bien este encantamiento porque quemará la contaminación de todos aquellos que se oponen a nosotros.' WHERE `ID`=59683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在2分钟后开始！', `MaleText_loc5`='戰鬥在2分鐘內開始!', `MaleText_loc7`='¡La batalla comienza en dos minutos!' WHERE `ID`=59684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在1分钟后开始！', `MaleText_loc5`='戰鬥在1分鐘內開始!', `MaleText_loc7`='¡La batalla comienza en un minuto!' WHERE `ID`=59685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在30秒后开始！', `MaleText_loc5`='戰鬥在30秒內開始!', `MaleText_loc7`='¡La batalla comienza en treinta segundos!' WHERE `ID`=59686;
