UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 채소가 자라나고 있는데... 이젠 어떻게 해야 합니까?', `MaleText_loc4`='我的农作物在生长……现在该怎么做？', `MaleText_loc5`='我的作物正在生長...現在咧?', `MaleText_loc7`='Mi cultivo está creciendo... ¿y ahora qué?', `FemaleText_loc1`='제 채소가 자라나고 있는데... 이젠 어떻게 해야 하나요?', `FemaleText_loc4`='我的农作物在生长……现在该怎么做？', `FemaleText_loc5`='我的作物正在生長...現在咧?', `FemaleText_loc7`='Mi cultivo está creciendo... ¿y ahora qué?' WHERE `ID`=59688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 광산 수레를 빼앗았습니다!', `MaleText_loc4`='联盟夺取了一辆采矿车！', `MaleText_loc5`='聯盟奪走了礦坑推車!', `MaleText_loc7`='¡La Alianza ha capturado una vagoneta!' WHERE `ID`=59689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 광산 수레를 빼앗았습니다!', `MaleText_loc4`='部落夺取了一辆采矿车！', `MaleText_loc5`='部落奪走了礦坑推車!', `MaleText_loc7`='¡La Horda ha capturado una vagoneta!' WHERE `ID`=59690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 이제 기다리기만 하면 됩니다! 여기 채소는 대부분 자라나기 시작한 다음 날이면 수확할 수 있습니다.$B$B우리가 이렇게 비옥한 계곡에 땅을 가졌다는 게 정말 행운이지 않습니까?', `MaleText_loc4`='现在你该做的就是等！大多数农作物在开始生长之后的第二天就成熟了。$B$B在这样肥沃的山谷里拥有一块土地不是很幸运的事吗？', `MaleText_loc5`='現在你們該做的就是等待!大多數作物在它們開始成長之後的隔天就會長好。$B$B我們能在如此豐饒的山谷中擁有一塊地，這不是件很幸運的事嗎?', `MaleText_loc7`='¡Ahora solo hay que esperar! La mayoría de los cultivos están listos el día después de empezar a crecer.$B$B¿A que tenemos suerte de tener tierras en un valle tan fecundo?' WHERE `ID`=59691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자가 다가오는군요.', `MaleText_loc4`='有挑战者过来了。', `MaleText_loc5`='一名挑戰者接近了。', `MaleText_loc7`='Se acerca $gun:una; contendiente.' WHERE `ID`=59692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='홉탈루스가 찢어질 듯한 울음소리를 냅니다! 토깽이 몰려오고 있습니다!', `MaleText_loc4`='跳跳大王大声呼喊！兔妖来了！', `MaleText_loc5`='跳跳巨兔妖發出一聲響亮的尖叫!兔妖來了!', `MaleText_loc7`='¡Saltadizo grita con fuerza! ¡Vienen los mures!', `FemaleText_loc1`='홉탈루스가 찢어질 듯한 울음소리를 냅니다! 토깽이 몰려오고 있습니다!', `FemaleText_loc4`='跳跳大王大声呼喊！兔妖来了！', `FemaleText_loc5`='跳跳巨兔妖發出一聲響亮的尖叫!兔妖來了!', `FemaleText_loc7`='¡Saltadizo grita con fuerza! ¡Vienen los mures!' WHERE `ID`=59693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 엄청난 분노로 이 야만인들을 공격하길!', `MaleText_loc4`='以我全部的怒火攻击这些野蛮人！', `MaleText_loc5`='集我所有的憤怒之力，打敗這些野蠻人!', `MaleText_loc7`='¡Ataquen a esos bárbaros con toda la fuerza de mi cólera!' WHERE `ID`=59694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복 받아요!', `MaleText_loc4`='祝你好运！', `MaleText_loc5`='祝你好運!', `MaleText_loc7`='¡Que la fortuna te sonría!' WHERE `ID`=59695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 주둔지에서 만나요!', `MaleText_loc4`='让我们在寇塔营地再见！', `MaleText_loc5`='我們到柯沓營地見了!', `MaleText_loc7`='¡Nos vemos en el Campamento Base Kota!' WHERE `ID`=59696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타슬이 킁킁댑니다.', `MaleText_loc4`='塔索尔嗅了嗅空气。', `MaleText_loc5`='塔索嗅著空氣。', `MaleText_loc7`='Flecos olisquea el aire.' WHERE `ID`=59697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_qirajicrystal_04.blp:20|t |c0091D0F8%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_qirajicrystal_04.blp:20|t |c0091D0F8%s|r开始石化所有玩家！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_qirajicrystal_04.blp:20|t |c0091D0F8%s|r開始將所有的玩家石化!', `MaleText_loc7`='|TInterfaceIconsinv_misc_qirajicrystal_04.blp:20|t |c0091D0F8¡%s|r comienza a petrificar a todos los jugadores!' WHERE `ID`=59698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_qirajicrystal_03.blp:20|t |c0093F8D1%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_qirajicrystal_03.blp:20|t |c0093F8D1%s|r开始石化所有玩家！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_qirajicrystal_03.blp:20|t |c0093F8D1%s|r開始將所有的玩家石化!', `MaleText_loc7`='|TInterfaceIconsinv_misc_qirajicrystal_03.blp:20|t |c0093F8D1¡%s|r comienza a petrificar a todos los jugadores!' WHERE `ID`=59699;
