UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_qirajicrystal_05.blp:20|t |c00C3B7EA%s|r|1이;가; 모든 플레이어들을 돌로 만들기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_qirajicrystal_05.blp:20|t |c00C3B7EA%s|r开始石化所有玩家！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_qirajicrystal_05.blp:20|t |c00C3B7EA%s|r開始將所有的玩家石化!', `MaleText_loc7`='|TInterfaceIconsinv_misc_qirajicrystal_05.blp:20|t |c00C3B7EA¡%s|r comienza a petrificar a todos los jugadores!' WHERE `ID`=59701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북방의 위세, 쉬엔이 전투의 부름에 답합니다!', `MaleText_loc4`='雪怒，北方之力，回应了战斗的召唤！', `MaleText_loc5`='雪怒，北方的力量，回應呼喚來參戰!', `MaleText_loc7`='¡Xuen, poder del norte, responde a la llamada de la batalla!' WHERE `ID`=59702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동방의 수호자, 위론이 전장에 나타납니다!', `MaleText_loc4`='玉珑，东方的守护者，出现在战场上！', `MaleText_loc5`='玉龍，東方的守衛，出現在戰場上!', `MaleText_loc7`='¡Yu''Lon, guardián del este, aparece en el campo de batalla!', `FemaleText_loc1`='동방의 수호자, 위론이 전장에 나타납니다!', `FemaleText_loc4`='玉珑，东方的守护者，出现在战场上！', `FemaleText_loc5`='玉龍，東方的守衛，出現在戰場上!', `FemaleText_loc7`='¡Yu''Lon, guardián del este, aparece en el campo de batalla!' WHERE `ID`=59703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서방의 힘, 니우짜오가 전장으로 돌진합니다!', `MaleText_loc4`='砮皂，西方之力，冲进了战场！', `MaleText_loc5`='怒兆，西方的戰力，加入戰鬥!', `MaleText_loc7`='¡Niuzao, fuerza del oeste, irrumpe en la batalla!' WHERE `ID`=59704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가... 파이어바우 스타우트 제조 비법의 맥이 여기서 끊기는 줄만 알았소. 여길 빠져나가게 도와 주시오, 친구!', `MaleText_loc4`='感谢上天……我原本以为自己要把火树烈酒的秘方带进棺材了呢。快帮我离开这儿，朋友！', `MaleText_loc5`='感謝老天...我以為火枝烈酒的秘密會跟我一起進墳墓。幫我離開這裡吧，朋友!', `MaleText_loc7`='Gracias a los cielos... Pensaba que los secretos de la cerveza de Tallo Ardiente morirían conmigo. ¡Ayúdame a salir de aquí!' WHERE `ID`=59705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길 빠져나갑시다.', `MaleText_loc4`='让我们离开这里吧。', `MaleText_loc5`='我們離開這兒吧。', `MaleText_loc7`='Salgamos de aquí.', `FemaleText_loc1`='여길 빠져나가죠.', `FemaleText_loc4`='让我们离开这里吧。', `FemaleText_loc5`='我們離開這兒吧。', `FemaleText_loc7`='Salgamos de aquí.' WHERE `ID`=59706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단단히 붙잡았습니다. 이제 뛰어오르십시오!', `MaleText_loc4`='抓紧了——跳！', `MaleText_loc5`='你抓得很牢。現在，跳!', `MaleText_loc7`='Lo estás agarrando bien... ¡ahora SALTA!', `FemaleText_loc1`='단단히 붙잡았습니다. 이제 뛰어오르십시오!', `FemaleText_loc4`='抓紧了——跳！', `FemaleText_loc5`='你抓得很牢。現在，跳!', `FemaleText_loc7`='Lo estás agarrando bien... ¡ahora SALTA!' WHERE `ID`=59707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새나는 우낏 같으니!', `MaleText_loc4`='臭气熏天！', `MaleText_loc5`='臭怪怪人!', `MaleText_loc7`='¡Apestosos makakus!' WHERE `ID`=59708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구가 우리 방어선을 뚫었어요...$B$B적의 비취 병사 군대를 막는 건 우리에겐 역부족이었어요.$B$B저는 체를 돌보려고 뒤에 남았지만, 나머지 사람들은 마지막 저항을 위해 도시 안으로 후퇴했어요.', `FemaleText_loc4`='魔古族突破了我们的防线……$B$B他们的魔玉战士大军人数太多，我们抵挡不住。$B$B我在后方照顾车，但其他人撤进了城里，准备背水一战。', `FemaleText_loc5`='魔古擊潰了我們的防禦...$b$b他們由翠玉士兵組成的軍隊人數太多，我們無法擊退。$B$B我待在後方照顧奇，但其他人撤退到城市去準備背水一戰。', `FemaleText_loc7`='Los mogu rompieron nuestras defensas...$B$BSu ejército de soldados de jade era demasiado como para que pudiésemos resistir.$B$BYo me quedé atrás para cuidar de Che, pero el resto se retiró a la ciudad para preparar la última defensa.' WHERE `ID`=59709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비는 됐소, $p? 자오민 로가 다리 건너에서 기다리고 있소.', `MaleText_loc4`='我希望你已经准备好了，$p。洛蛟明在桥那边等着你。', `MaleText_loc5`='我希望你準備好了，$p。焦名樓就在橋的另一邊等你。', `MaleText_loc7`='Espero que estés $gpreparado:preparada;, $p. Jaomin Ro te está esperando tras el puente.' WHERE `ID`=59710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 가는 거요? 그 무용이 부럽소. $c|1이여;여;, 당신 앞에 창창한 앞날이 펼쳐지길.', `MaleText_loc4`='你这就要走了？我真羡慕你的强大力量。一路顺风，$c。', `MaleText_loc5`='你這麼快就要走了?我羨慕你的英勇，$c。祝你好運。', `MaleText_loc7`='¿Ya te marchas? Tu destreza es digna de admiración, $c. Te deseo buena suerte.' WHERE `ID`=59711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉿! 발소리 낮추시오. 아이사가 수련하고 있소.', `MaleText_loc4`='嘘！脚步轻点儿。她正在修炼。', `MaleText_loc5`='噓!輕聲走過來。她正在修行。', `MaleText_loc7`='¡Shhhh! Acércate en silencio. Se está entrenando.' WHERE `ID`=59712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 격렬한 |cFFFF0404|Hspell:116040|h[진앙]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='%s开始引导一次强烈的|cFFFF0404|Hspell:116040|h[震中]|h|r！', `MaleText_loc5`='%s開始導引強力的|cFFFF0404|Hspell:116040|h[地源震]|h|r!', `MaleText_loc7`='¡%s empieza a canalizar un violento |cFFFF0404|Hspell:116040|h[Epicentro]|h|r!' WHERE `ID`=59714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 바로 그거야! 아주 타고났군.', `MaleText_loc4`='哈！就这么干！你很有天分。', `MaleText_loc5`='哈!幹得好!你天生就是做這行的。', `MaleText_loc7`='¡Ja! ¡Así se hace! Tienes un don para esto.' WHERE `ID`=59715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와, 친구! 싸움터는 이쪽이야!', `MaleText_loc4`='这边走，朋友！战斗在等着我们！', `MaleText_loc5`='快來，朋友!這裡有架可以打了!', `MaleText_loc7`='¡Ven, camarada! ¡La pelea está por aquí!' WHERE `ID`=59716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 와! 재밌는 부분을 놓쳐서야 되겠어?', `MaleText_loc4`='快过来！你不想错过这么有趣的事吧？', `MaleText_loc5`='快過來!你不會想錯過這些樂趣吧?', `MaleText_loc7`='¡Ven, rápido! No querrás perderte toda la diversión, ¿verdad?' WHERE `ID`=59717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 사고방식이 마음에 드는걸! 가자!', `MaleText_loc4`='我喜欢你的思路！我们走！', `MaleText_loc5`='我喜歡你的想法!走吧!', `MaleText_loc7`='¡Me gusta cómo piensas! ¡Vamos!' WHERE `ID`=59718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 함께 싸우겠소, 친구. 이 싸움은 우리 것이기도 하오.', `MaleText_loc4`='我们将并肩作战，朋友。这不是你一个人的战斗。', `MaleText_loc5`='我們與你並肩作戰，朋友。這不是你一個人的戰鬥。', `MaleText_loc7`='Estamos contigo, pandaren. Esta lucha nos incumbe a todos.' WHERE `ID`=59719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽은 우리가 맡을 테니, 사제들을 지켜 주십시오.', `FemaleText_loc4`='我们守住阵线，你去保护好牧师。', `FemaleText_loc5`='我們會守住前線。你負責保護牧師。', `FemaleText_loc7`='Este frente es nuestro. Mantén a mis sacerdotes a salvo.' WHERE `ID`=59720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서지 마라! 형제들의 목숨이 그대들에게 달렸다!', `FemaleText_loc4`='坚持住，水手们！为了兄弟姐妹们！', `FemaleText_loc5`='守住防線，水手們!弟兄們仰賴你們!', `FemaleText_loc7`='¡Manténganse firmes! ¡Sus hermanos dependen de ustedes!' WHERE `ID`=59721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부상자를 돌봐라! 아직 끝나지 않았다.', `FemaleText_loc4`='保护伤员！战斗还没完呢。', `FemaleText_loc5`='照料傷患!事情還沒有結束。', `FemaleText_loc7`='¡Atiendan a los heridos! Esto aún no ha terminado.' WHERE `ID`=59722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀오소리는 쥐뿔도 신경 쓰지 않습니다.', `MaleText_loc4`='蜂蜜獾熊才不管那些烂事！', `MaleText_loc5`='小蜜獾才不在乎!', `MaleText_loc7`='¡A la nutria de la miel le importa un pimiento!', `FemaleText_loc1`='꿀오소리는 쥐뿔도 신경 쓰지 않습니다.', `FemaleText_loc4`='蜂蜜獾熊才不管那些烂事！', `FemaleText_loc5`='小蜜獾才不在乎!', `FemaleText_loc7`='¡A la nutria de la miel le importa un pimiento!' WHERE `ID`=59723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 다 두고 갈 순 없소. 우리 가족의 유산이란 말이오!', `MaleText_loc4`='我不会扔下这些不管的。这是我家族的遗产！', `MaleText_loc5`='我不會捨棄這些事物，這是我家族的遺產!', `MaleText_loc7`='No voy a dejarlos aquí. ¡Es el legado de mi familia!' WHERE `ID`=59726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 소개를 해야겠군. 나는 한때 영광을 누렸던 이 촌락의 고명한 촌장, 야 파이어바우라 하네.$B$B자네는 강직한 시민인 것 같군.$B$B혹시 내가 이 불쾌한 처지를 벗어날 수 있도록 도와줄 뜻이 있는가? 근처의 퇴각지에 있는 음영파가 자네의 수고에 대해 보답을 할 걸세.', `MaleText_loc4`='请允许我介绍下自己——我叫崖·火树，是这个曾经辉煌村庄的杰出首领。$B$B你显然是这世界上正直的住民。$B$B不知能否麻烦你帮我脱离这个棘手的境地呢？我相信在附近驻扎的影踪派会非常乐意对给您造成的任何不便作出补偿的。', `MaleText_loc5`='容我自我介紹，我是雅·火枝，這座曾繁榮一時的村莊的卓越領導者。$B$B你顯然是這個世界的正直居民。$B$B不知道我能否麻煩你幫我解決這個膠著的狀況?附近密地的影潘肯定樂意補償對你造成的所有不便。', `MaleText_loc7`='Permíteme que me presente, soy Ya Tallo Ardiente, ilustre líder de esta antiguamente magnífica aldea.$B$BEstá claro que eres $gun honesto ciudadano:una honesta ciudadana; del mundo.$B$B¿Me ayudarías a salir de esta situación tan embarazosa? Estoy seguro de que el Shadopan del refugio más cercano te recompensará por las molestias.' WHERE `ID`=59727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 긴말 필요 없고, 갑시다.', `MaleText_loc4`='……够了。走吧。', `MaleText_loc5`='...夠了。我們走。', `MaleText_loc7`='... Ya basta. Vamos.', `FemaleText_loc1`='... 긴말 필요 없고, 가요.', `FemaleText_loc4`='……够了。走吧。', `FemaleText_loc5`='...夠了。我們走。', `FemaleText_loc7`='... Ya basta. Vamos.' WHERE `ID`=59728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 자네같이 앞날이 창창한 젊은이가 올 데가 아닐세.$b$b내가 안전한 곳으로 데려다 줄까?', `FemaleText_loc4`='像你这种阳光年轻的$g男士: 女士;可不该待在这里。$B$B或许你愿意让我护送你去安全的地方，嗯？', `FemaleText_loc5`='這不是一個像你這樣聰明的年輕$g人:小姐;該來的地方。$B$B也許你想要我護送你到安全的地方，嗯?', `FemaleText_loc7`='Este no es lugar para $gun muchacho:una muchacha; brillante como tú.$B$BA lo mejor quieres que te escolte hasta un lugar seguro, ¿eh?' WHERE `ID`=59729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 안전한 곳으로 데려다 주십시오.', `MaleText_loc4`='是啊……你为什么不“护送”我出去呢。', `MaleText_loc5`='沒錯...你何不「護送」我離開這裡。', `MaleText_loc7`='Sí... ¿por qué no me "escoltas" fuera de aquí?', `FemaleText_loc1`='네... 안전한 곳으로 데려다 주세요.', `FemaleText_loc4`='是啊……你为什么不“护送”我出去呢。', `FemaleText_loc5`='沒錯...你何不「護送」我離開這裡。', `FemaleText_loc7`='Sí... ¿por qué no me "escoltas" fuera de aquí?' WHERE `ID`=59730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g 아저씨 : 아줌마;..$B$B저를 데리고 가 주실래요?', `FemaleText_loc4`='拜托了，$g先生: 小姐;……$B$B你会救我出去吗？', `FemaleText_loc5`='拜託，$g先生:女士;...$b$b你可以帶我離開這裡嗎?', `FemaleText_loc7`='Por favor.$B$Bsáqueme de aquí.' WHERE `ID`=59731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이라고;라고; 했나? 내 신변을 보호해 준다면 금화를 좀 주겠네.', `MaleText_loc4`='你叫$n，对吧？如果你能亲自确保我的安全，我会再多给你一些赏钱的。', `MaleText_loc5`='$n，是嗎?假如你能個人擔保我的安全，便能得到一些額外的黃金。', `MaleText_loc7`='¿$n, verdad? Te ofrezco oro a cambio de que garantices mi seguridad personalmente.' WHERE `ID`=59732;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네... 음영파와 함께 싸우는 거였나? 믿을 수 없구먼!', `FemaleText_loc4`='你……在为影踪派效力？我不敢相信！', `FemaleText_loc5`='你是和...影潘並肩合作嗎?我真不敢相信!', `FemaleText_loc7`='¿Estás... trabajando para el Shadopan? ¡No me lo puedo creer!' WHERE `ID`=59733;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 괴물들이 오니까 음영파 사람들이 엄청 심각해졌어요... 계속 "샤"가 어쩌니 하더군요. 그게 뭐죠?', `FemaleText_loc4`='当这些怪物来的时候，影踪派的人都很紧张……他们不停在说“煞魔”。那是什么？', `FemaleText_loc5`='這些怪物出現時，影潘變得很凝重...他們不斷提到「煞」。那是什麼?', `FemaleText_loc7`='Cuando llegaron estos monstruos, los Shadopan se pusieron muy serios... no dejaban de decir "Sha". ¿Qué es eso?' WHERE `ID`=59734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 이래 봬도 제법 무겁다오. 좀 서두르면 안 되겠소?', `MaleText_loc4`='它们看起来可不轻啊。我们可以快点儿吗？', `MaleText_loc5`='這些東西比表面上重多了，我們可以走快點嗎?', `MaleText_loc7`='Pesan más de lo que parece. ¿Podemos ir más rápido?' WHERE `ID`=59735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나 더 가야 하오?', `MaleText_loc4`='我们得走多远？', `MaleText_loc5`='我們必須走多遠?', `MaleText_loc7`='¿Vamos muy lejos?' WHERE `ID`=59736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퇴각지로 돌아가면, 이 통을 따서 목숨을 건진 걸 축하하며 건배합시다!', `MaleText_loc4`='当我们把这些酒带回住所后，就可以开桶庆祝，为胜利干杯了！', `MaleText_loc5`='當我們安全回到秘地時，我們可以打開這些酒為活命乾杯!', `MaleText_loc7`='Cuando volvamos al Refugio, podemos abrir estos y brindar por la vida.' WHERE `ID`=59737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 북쪽의 문으로 쳐들어왔다고 들었소. 그곳에 있던 음영파는 어떻게 되었는지 모르겠군.', `MaleText_loc4`='我听说野牛人冲破了北面的大门。不知那里的影踪派怎么样了？', `MaleText_loc5`='我聽說揚古闖過北方那邊的城門了，不知道那裡的影潘發生了什麼事?', `MaleText_loc7`='He oído que los yaungol han atravesado las puertas del norte. ¿Qué habrá pasado con el Shadopan de allí?' WHERE `ID`=59738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버님이 파이어바우 스타우트를 담그셨고, 할아버님도 담그셨소. 그 전통이 끊어지게 할 수는 없소.', `MaleText_loc4`='我父亲酿制火树烈酒。在他之前还有我的祖父。我决不能让这个家传秘方失传。', `MaleText_loc5`='我父親釀造火枝烈酒，在他之前是他的父親。我不能讓這遺產消失。', `MaleText_loc7`='Mi padre elaboraba cerveza de Tallo Alto. Y su padre antes que él. No puedo permitir que se pierda el legado.' WHERE `ID`=59739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에 따뜻한 맥주만큼 좋은 게 또 없다오. 뼛속까지 따뜻해지면서 속이 시원해진다오. 시원한 맥주는 혼자 드셔도 좋소.', `MaleText_loc4`='没什么比得上一杯暖和的美酒了。让你的身体暖和起来，是一大享受啊。你把那个冷东西留给自己吧。', `MaleText_loc5`='再沒有什麼比得上熱烘烘的烈酒了，它能溫暖你的筋骨讓你全身舒暢。你的冷酒自己留著喝吧。', `MaleText_loc7`='No hay nada mejor que una cerveza templada. Te calienta los huesos y el espíritu. Puedes quedarte con esa cerveza fría.' WHERE `ID`=59740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연한 말씀을... 첸 스톰스타우트를 모르는 사람이 있겠소? 그런데 그의 술통은 비었다더군. 무슨 얘긴지 알겠소?', `MaleText_loc4`='啊，嗯，是的……谁会没有听说过陈·风暴烈酒啊？不过，我听说他的酒桶已经空了，你知道我指的是什么。', `MaleText_loc5`='嗯，是的，當然...誰沒聽說過老陳·風暴烈酒?不過我聽說他的酒桶已經空了，如果你懂我的意思。', `MaleText_loc7`='Bueno, sí, claro... Todo el mundo sabe quién es Chen Cerveza de Trueno; aunque he oído que su barril está vacío, ya me entiendes.' WHERE `ID`=59741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고. 실례한 것 같군! 아까 그 맥주 때문이야!!!', `MaleText_loc4`='啊哦。好像有什么东西漏出来了！是酒！！！', `MaleText_loc5`='哦喔。看來我敲出了一道裂縫!酒啊!!!', `MaleText_loc7`='Oh, oh. ¡Me parece que he provocado una grieta! ¡¡¡La cerveza!!!' WHERE `ID`=59742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네, 음영파를 돕고 있는 겐가? 음영파가 외지인의 도움을 받다니 믿을 수 없군.', `MaleText_loc4`='你一直在为影踪派效命？我无法相信他们居然还让一个外人帮助他们！', `MaleText_loc5`='你和影潘並肩合作嗎?我不敢相信他們讓一個外來人幫他們忙!', `MaleText_loc7`='¿Estás trabajando para el Shadopan? ¡No me puedo creer que se hayan dejado ayudar por alguien de fuera!' WHERE `ID`=59743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골은 인사고 뭐고 없이 그냥 쳐들어왔네! 샤라는 놈들한테 감염되다니, 꼴 좋게 됐어!', `MaleText_loc4`='这些野牛人向来连招呼都不打。直接就攻来了！活该他们被煞魔感染！', `MaleText_loc5`='這些揚古從來不打招呼，老是見人就打!他們被煞寄生是罪有應得!', `MaleText_loc7`='Estos yaungol no se molestan ni en saludar. ¡Se limitan a atacar! ¡Se merecen que les ataquen los sha esos!' WHERE `ID`=59744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마을 사람들이... 다 죽었네. 빈안 마을에 새 저택을 지어야 하나?', `MaleText_loc4`='我所有的家人都死了。也许我应该在滨岸村建一座新庄园？', `MaleText_loc5`='我的人民全都死了。也許我該在濱南村建立一個新的領地?', `MaleText_loc7`='Todo mi pueblo está muerto. A lo mejor debería construir una mansión nueva en la Aldea Binan.' WHERE `ID`=59745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코바이는 예전에 우리를 위협하던 녀석이라네. 원래도 정신이 온전치는 않았지만 지금은 완전히 실성해 버렸지.', `MaleText_loc4`='科拜以前总是威胁我们，没完没了。现在……不管他打的是什么主意，他都输定了。', `MaleText_loc5`='柯巴曾對我們造成一些威脅，就這樣而已。但現在...他顯然已喪失心智。', `MaleText_loc7`='Kobai Khan solía amenazarnos, nada más. Ahora... ha perdido el poco juicio que le quedaba.' WHERE `ID`=59746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영사부 총을 만나면 따끔하게 한 마디 해 줘야겠네. 음영파 주제에 우릴 도우러 오지 않다니!', `MaleText_loc4`='等我见到影踪派翀大师，我会把自己的智慧分一点给他。影踪派的勇气帮不了我们！', `MaleText_loc5`='等我看到影潘宗師沖，我要給他好看。影潘好大的膽子，敢棄我們於不顧!', `MaleText_loc7`='Voy a decirle cuatro cosas al maestro Shado Chong cuando lo vea. ¡Cómo se atreve el Shadopan a no venir en nuestra ayuda!' WHERE `ID`=59747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 파이어바우 변두리마을뿐만 아니라, 온 쿤라이 봉우리의 영웅이라는 데는 아무도 이견이 없을 걸세, $p!', `MaleText_loc4`='我想，要是我称你为昆莱山真正的英雄，没有人会有异议，更不用说火树村了，$p！', `MaleText_loc5`='$p，你真是崑萊峰的英雄，我相信我代表了每個人的心聲，更別提火枝望角了!', `MaleText_loc7`='¡Creo que hablo por todos cuando digo que eres $gun verdadero héroe:una verdadera heroína; de la Cima Kun-Lai, por no mencionar el Rincón Tallo Ardiente, $p!' WHERE `ID`=59748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이런 일에는 익숙하지가 않다네. 나는 웅변의 대가이자 주민의 대변인이지. 끝나려면 아직 멀었나?', `MaleText_loc4`='我真不擅长干这个。我是一位演说大师，人民的外交家。我们在这里的任务快要完成了吧？', `MaleText_loc5`='我真的不是為了這個才準備的。我是個演說家，也是代表人民的外交官。我們到底好了沒?', `MaleText_loc7`='No estoy hecho para esto. Soy un maestro orador y diplomático del pueblo. ¿Ya hemos terminado aquí?' WHERE `ID`=59749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수 가운데서 솟아나고 있는 집채만 한 분노의 파도를 처리할 계획은 세우고 있겠지?!', `MaleText_loc4`='我相信你肯定会对从湖中央喷薄而出的那团汹涌怒气做点什么的，对吧？！', `MaleText_loc5`='我相信你應該已經想好，要怎麼對付從湖中心冒出來的怒煞了吧?!', `MaleText_loc7`='Espero que tengas un plan para acabar con ese enorme flujo de ira que está surgiendo en mitad del lago.' WHERE `ID`=59750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게... 저게 후오요?', `MaleText_loc4`='那……那不是燧焰吗？', `MaleText_loc5`='那是...那是霍嗎?', `MaleText_loc7`='¿Ese es... Huo?' WHERE `ID`=59751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞네! 잘했네, $p!', `MaleText_loc4`='真的是他！干的好，$p！', `MaleText_loc5`='真的是!做得好，$p!', `MaleText_loc7`='¡Lo es! ¡Bien hecho, $p!' WHERE `ID`=59752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하신가!', `FemaleText_loc4`='嗨——呀！', `FemaleText_loc5`='咿哈!', `FemaleText_loc7`='¡Jaiiii ya!' WHERE `ID`=59753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='푸스 로 다!', `FemaleText_loc4`='Fus Ro Dah（力——衡——冲）!', `FemaleText_loc5`='轟砰嘎!', `FemaleText_loc7`='¡Fus Ro Dah!' WHERE `ID`=59754;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네가 배운 백호와 옥룡, 후학의 기술은 내 기술과 맞먹는구먼.', `FemaleText_loc4`='我发现你驾驭白虎、青龙、灵猴和朱鹤的战技的能力不在我之下。', `FemaleText_loc5`='看來你的白虎道、玉蛟道、猴鶴道的技巧都跟我一樣厲害。', `FemaleText_loc7`='Veo que tu técnica del Tigre Blanco, del Dragón de Jade, del Mono y de la Grulla es tan buena como la mía.' WHERE `ID`=59755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도장에서는 울고, 전장에서는 웃게나. 아하하하하하하하하!', `FemaleText_loc4`='现在在道场里痛哭，是为了将来能在战场上大笑。啊哈哈哈哈哈哈！', `FemaleText_loc5`='在道場裡頭哭，就可以在戰場上笑。啊哈哈哈哈哈哈哈!', `FemaleText_loc7`='Llora en el dojo, ríe en el campo de batalla. ¡Ja, ja, ja, ja, ja, ja!' WHERE `ID`=59756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라, 원숭아!', `MaleText_loc4`='拍死那只臭猴子！', `MaleText_loc5`='踢爛他的猴屁股!', `MaleText_loc7`='¡Toma eso macaco!' WHERE `ID`=59757;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다리를 후리게!', `FemaleText_loc4`='扫堂腿！', `FemaleText_loc5`='絕不留情!', `FemaleText_loc7`='¡A la pierna!' WHERE `ID`=59758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리... 마을에서... 당장... 나가!', `FemaleText_loc4`='离……开……我……的……镇子！', `FemaleText_loc5`='滾...出...我...的...鎮!', `FemaleText_loc7`='¡FUERA... DE... MI... PUEBLO!' WHERE `ID`=59759;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물처럼 흐르고, 갈대처럼 휘고... 어쩌고 저쩌고. 그냥 혼꾸멍을 내 주면 되지!', `FemaleText_loc4`='行如流水，韧如芦苇……呱啦，呱啦，呱啦。对准屁股踢就对了！', `FemaleText_loc5`='行如流水，柔如蘆葦...廢話連篇。從屁股踹下去就對了!', `FemaleText_loc7`='Fluye como el agua, dóblate como un junco... bla, bla, bla. ¡Límitate a repartir tortas!' WHERE `ID`=59760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 나이로 나를 판단하지 말게.', `FemaleText_loc4`='你是在以年龄评断我的实力吗？', `FemaleText_loc5`='你是不是也從我的年紀來評斷我?', `FemaleText_loc7`='Ten en cuenta mi edad, ¿quieres?' WHERE `ID`=59761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 마을을 잃었네... 왜 수도원에서 원군이 오지 않는 거지?', `MaleText_loc4`='我们都把镇子给丢了……从禅院来的援军怎么还没赶到？', `MaleText_loc5`='我們已經失去了這個鎮...為什麼僧院那裡沒有派人來呢?', `MaleText_loc7`='Ya hemos perdido el pueblo... ¿Por qué no han llegado refuerzos del Monasterio?' WHERE `ID`=59762;
