UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 짐 못 가져간다!', `MaleText_loc4`='蠢蛋没把运货人带回来！', `MaleText_loc5`='怪怪人別想把東東搶回去!', `MaleText_loc7`='¡Makakus no devuelven sakas!' WHERE `ID`=59764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 까까짐 떳떳하게 훔쳤다! 줬다 뺏기 없다!', `MaleText_loc4`='猢狲肆无忌惮地偷走了果子。有去无回！', `MaleText_loc5`='猴人正大光明偷好吃的東東。別想搶回去!', `MaleText_loc7`='Hozen roban manduka de forma justa y honrada. ¡No devuelven nada!' WHERE `ID`=59765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 여기 못 들어온다!', `MaleText_loc4`='不准蠢蛋肆意妄为！', `MaleText_loc5`='怪怪人走開!', `MaleText_loc7`='¡Prohibido el paso a makakus!' WHERE `ID`=59766;
