UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장이 훔치라 해서 호젠 훔친다!', `MaleText_loc4`='酋长下令掠夺，猢狲们遵命！', `MaleText_loc5`='酋長說搶，猴人就搶!', `MaleText_loc7`='¡Jefe dice sakear, así que hozen sakean!' WHERE `ID`=59768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이 우낏! 못 간다!', `MaleText_loc4`='该死的蠢蛋！回来！', `MaleText_loc5`='該死的怪怪人!給我回來!', `MaleText_loc7`='¡Dingue makaku! ¡Vuelve akí!' WHERE `ID`=59769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 연꽃은 수천 년 동안 골짜기를 지켜 왔다네.$B$B하늘이 우리에게 징조를 보였으며, 우리는 모두 지금이 다시 문을 열어야 할 때임을 굳게 믿는다네.$B$B준비됐는가?', `MaleText_loc4`='金莲教已经监视了这座山谷几千年。$B$B上天已向我们降下了预兆，所以我们要团结一致、坚定信念——现在是再次打开大门的时候了。$B$B你们准备好了吗？', `MaleText_loc5`='金蓮會已看管這個山谷幾千年了。$B$B上天給了我們預兆，而我們聚在一起，因為相信現在正是再次打開大門的時候。$B$B你準備好了嗎?', `MaleText_loc7`='El Loto Dorado ha estado vigilando el valle durante milenios.$B$BLos cielos nos han enviado su señal, y unidos y seguros decimos que es hora de abrir de nuevo las puertas.$B$B¿Estás $gpreparado:preparada;?' WHERE `ID`=59770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 열 준비가 됐습니다.', `MaleText_loc4`='我准备好打开大门了。', `MaleText_loc5`='我準備好要打開大門了。', `MaleText_loc7`='Lo estoy. Abramos las puertas.', `FemaleText_loc1`='문을 열 준비가 됐어요.', `FemaleText_loc4`='我准备好打开大门了。', `FemaleText_loc5`='我準備好要打開大門了。', `FemaleText_loc7`='Lo estoy. Abramos las puertas.' WHERE `ID`=59771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대박 멋진 문 개방 동영상 들어감!!!', `MaleText_loc4`='AWESOME AMAZING GATE OPENING CINEMATIC GOES HERE!!!', `MaleText_loc5`='AWESOME AMAZING GATE OPENING CINEMATIC GOES HERE!!!', `MaleText_loc7`='¡¡¡LA IMPRESIONANTE Y ASOMBROSA CINEMÁTICA DE APERTURA DE LA PUERTA VA AQUÍ!!!', `FemaleText_loc1`='대박 멋진 문 개방 동영상 들어감!!!', `FemaleText_loc4`='AWESOME AMAZING GATE OPENING CINEMATIC GOES HERE!!!', `FemaleText_loc5`='AWESOME AMAZING GATE OPENING CINEMATIC GOES HERE!!!', `FemaleText_loc7`='¡¡¡LA IMPRESIONANTE Y ASOMBROSA CINEMÁTICA DE APERTURA DE LA PUERTA VA AQUÍ!!!' WHERE `ID`=59772;
