UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날뛰는 설인?! 호오. 좋은 생각이 났어요.', `MaleText_loc4`='狂暴的雪人？！嗯……我想到一个绝好的主意。', `MaleText_loc5`='暴走的雪人?!這給了我一個很棒的主意。', `MaleText_loc7`='¡¿Yetis salvajes?! Mmm. Eso me ha dado una gran idea...' WHERE `ID`=59774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가 같은 우낏이 조각니 까까짐 뺏어 가려고 한다!', `MaleText_loc4`='该死的蠢蛋想阻止断牙猢狲抢果子！', `MaleText_loc5`='該死的怪怪人要讓好吃的東東遠離斷齒!', `MaleText_loc7`='¡Dingues makakus van a intentar kedarse con manduka de Dienterroto!' WHERE `ID`=59775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 아무 걱정 말거라.', `MaleText_loc4`='当然。别担心。', `MaleText_loc5`='當然，別擔心。', `MaleText_loc7`='Claro. No te preocupes.', `FemaleText_loc1`='물론이지. 아무 걱정 말거라.', `FemaleText_loc4`='当然。别担心。', `FemaleText_loc5`='當然，別擔心。', `FemaleText_loc7`='Claro. No te preocupes.' WHERE `ID`=59776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈군! 이리 오게, 할 얘기가 있다네.', `MaleText_loc4`='你做到了！过来，我们得谈谈。', `MaleText_loc5`='你終究是辦到了!來吧，我們必須談談。', `MaleText_loc7`='¡Lo has conseguido! Ven, tenemos que hablar.' WHERE `ID`=59777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘든 때일수록 감정을 절제해야 한다네. 그래야 샤에게 이용당하지 않지.', `MaleText_loc4`='在眼下这般黑暗的时期，我们必须控制好自己的情绪，以免被煞利用。', `MaleText_loc5`='即使這時代再難熬，我們必須控制我們的情緒，以免被煞所利用。', `MaleText_loc7`='Aunque los tiempos son duros, debemos controlar nuestras emociones para que no las use el Sha.' WHERE `ID`=59778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노가 사라진 것이 느껴졌다네. 잘했네.', `MaleText_loc4`='我感觉到暴怒消失了。你做得不错。', `MaleText_loc5`='我感覺到惡意之怒的死亡。你做得很好。', `MaleText_loc7`='Sentí el fallecimiento de Furia. Lo has hecho bien.' WHERE `ID`=59781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난 호젠의 눈이 너를 지켜 본다, 응가.', `MaleText_loc4`='生气的猢狲正盯着你看呢，死家伙。', `MaleText_loc5`='憤怒的猴人會盯著你，渣渣。', `MaleText_loc7`='Los ojos de los hozen enfadados están fijos en ti, kraku.' WHERE `ID`=59782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 코가 좋아요. 냄새로 행운과 불운을 구별할 수 있지요. 당신한테서는 행운의 냄새가 나요.', `MaleText_loc4`='土地精的鼻子很灵。能通过气味辨别是好运还是厄运。你身上有好运的气息。', `MaleText_loc5`='咕嚕摩有好鼻子。可以用氣味分辨幸運星和倒楣運。你聞起來是幸運星。', `MaleText_loc7`='Los grúmel tenemos buena nariz. Distinguimos la buena y la mala suerte a través del olfato. Tú hueles a buena fortuna.' WHERE `ID`=59783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 장벽을 지키러 갔어요. 그루멀이 이렇게 복을 누릴 수 있는 것도 음영파 덕택이에요. 음영파가 그루멀을 지켜 주지 못한다는 건, 궁지에 몰려 있다는 얘기예요. 어느 때보다도 그루멀짐이 더 절실하겠죠.', `MaleText_loc4`='影踪派不在这儿，因为他们必须守护城墙。土地精欠影踪派太多了。如果影踪派没能保护土地精，那就意味着他们陷入了危险的境地，而且比任何时候都更需要土地精脚夫。', `MaleText_loc5`='影潘不在這裡，因為長城需要他們防守。咕嚕摩的好運來自影潘，假如影潘無法防衛咕嚕摩那代表他們身陷困境，而且極為需要咕嚕摩的幫助。', `MaleText_loc7`='El Shadopan no está aquí porque la muralla los necesita. Los grúmel deben mucha fortuna al Shadopan. Si el Shadopan no puede defender a los grúmel, significa que están en peligro y necesitan más paquetes grúmel que nunca.' WHERE `ID`=59784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두끼의 찰싹찰싹은 그루멀의 친구였어요. 무려 세 철 동안 족장이었죠. 지금은 두끼의 우끼가 족장인데, 아주 성이 나 있어요. 그루멀이 주는 식량이 곧 끊기겠다 싶으니 도둑질을 시작했어요.', `MaleText_loc4`='呷卟督曾是土地精的朋友。他整整统治了三季。现在改由呜咔督掌权，他是脾气最为暴躁的一个。他认为来自土地精的食物供应很快就会中断，因此他开始四处掠夺。', `MaleText_loc5`='廢猴酋長吉伯跟咕嚕摩友好，當了猴人之前三任的酋長。現在猴人由廢猴酋長烏克率領，他脾氣就壞多了。他以為咕嚕摩不久之後就不會再運送食物，於是展開報復行動。', `MaleText_loc7`='El Dingue Jib era amigo de los grúmel. Vivió tres estaciones completas. El Dingue Makaku, el nuevo jefe, tiene peor humor. Cree que la comida de los grúmel se acabará pronto, así que saquea.' WHERE `ID`=59785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복 많이 받아요. 나는 토끼발이라고 해요. 나는 상인이면서 여행자예요. 그루멀의 복덩이죠.$b$b평화로운 때 만났다면 $p|1이;가; 내 물건을 사는 데서 그쳤겠지만, 운때가 맞게 오늘 만났네요.$b$b앞으로 함께 할 일이 아주 많아요.', `MaleText_loc4`='祝你好运。我是堂弟兔子脚。我是个商人、旅行者，对土地精来说还是一个特大幸运符。$b$b在和平时期，$p买我的商品会有好运。但好运让我们在今天相逢。$b$b我们有很多事情要一起做。', `MaleText_loc5`='願你好運多多。我是兔腳兄。我是商人，旅行者，也是咕嚕摩的大幸運星。$b$b在和平時期，$p會是我的好顧客。但是命運卻要我們在今日見面。$b$b我們一起有很多工作要做。', `MaleText_loc7`='Que tengas mucha fortuna. Soy el hermano Pataconejo. Soy comerciante, viajante y un gran grisgrís para los grúmel.$b$bEn tiempos de paz, $p haría bien en comprar todas mis mercancías. Pero la fortuna nos ha sonreído hoy.$b$bTenemos mucho trabajo que hacer juntos.' WHERE `ID`=59786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 내 야크를 애완 설인에게 먹였어요. 정말 불행한 일이에요.', `MaleText_loc4`='猢狲用我的牦牛来喂养他们的宠物雪人。这运气真是糟糕透顶。', `MaleText_loc5`='猴人把我的犛牛餵給他們的雪人吃。真是有夠倒楣的。', `MaleText_loc7`='Los hozen dieron de comer a mis yaks a sus mascotas yetis. Qué mala fortuna.' WHERE `ID`=59787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제 토끼발은 똑똑하고 키도 큰 데다, 복과 행운의 냄새를 풍겨요. 하지만 코를 골고 썰렁한 농담을 하는 데다, 내 복덩이가 야크편자라며 놀리죠.', `MaleText_loc4`='堂弟兔子脚也许又高又聪明，还浑身散发着好运与福气。但他却对我的幸运符牦牛鞋冷嘲热讽。', `MaleText_loc5`='兔腳兄很高很聰明，聞起來也很幸運。但是他會打鼾，還會拿我的幸運星牛蹄來開爛玩笑。', `MaleText_loc7`='El hermano Pataconejo es muy listo y alto y huele a buena suerte y buena fortuna. Pero ronca y hace chistes malos sobre mi grisgrís herradura de yak.' WHERE `ID`=59788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 복덩이 볼래요? 내가 아주 어렸을 때 날 태우고 다녔던 야크의 편자예요. 그때부터 오랫동안 내게 큰 복을 줬지요.', `MaleText_loc4`='想看我的幸运符吗？我还很小的时候就穿着这双牦牛鞋。多年来这双鞋给我带来了很多好运。', `MaleText_loc5`='想要看我的幸運星嗎?這是我小時候背著我的犛牛的蹄。這麼多年來，這蹄帶給我許多好運。', `MaleText_loc7`='¿Quieres ver mi grisgrís? Esta herradura de yak la conservo desde pequeñito. Me ha dado buena suerte desde hace muchos años.' WHERE `ID`=59789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 복덩이는 뭐예요? 먼 길을 가는 나그네라면 복덩이가 꼭 있어야 해요.', `MaleText_loc4`='你的幸运符是什么？所有旅行着都需要带着幸运符上路。', `MaleText_loc5`='你的幸運星是什麼?所有偉大之路上的旅行者都需要一個幸運星。', `MaleText_loc7`='¿Cuál es tu grisgrís? Todos los viajeros necesitan un grisgrís.' WHERE `ID`=59790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신한테서 복 냄새가 아주 진동을 하네요! 구해 줘서 고마워요, 복덩이! 나는 형제 야크편자라고 해요.', `MaleText_loc4`='你身上散发着好运的气息！万分感谢你救了我，幸运符！你可以叫我堂弟牦牛鞋。', `MaleText_loc5`='你全身都是好運的味道!非常感謝你救了我，幸運星!你可以叫我牛蹄兄。', `MaleText_loc7`='¡Hueles a fortuna! Muchas gracias por salvarme, grisgrís. Puedes llamarme hermano Herradura de Yak.' WHERE `ID`=59791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $r|1은;는; 여러 모로 도움이 되네요. 운수 나쁜 날에 대비해서 몇 명 더 곁에 둬야겠어요.', `MaleText_loc4`='啊，$r是最有用的。未雨绸缪，应该准备更多的$r。', `MaleText_loc5`='啊，$r非常有用。應該要未雨綢繆多準備點$r。', `MaleText_loc7`='$gEl:La; $r es una criatura muy útil. Deberíamos tener más para los días lluviosos.' WHERE `ID`=59792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 왔어요!', `MaleText_loc4`='土地精振作！', `MaleText_loc5`='咕嚕摩!', `MaleText_loc7`='¡Grúmel!' WHERE `ID`=59793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳에 오다니 운수가 나쁜걸.', `MaleText_loc4`='来这里真是倒霉。', `MaleText_loc5`='來這裡會倒楣。', `MaleText_loc7`='Mala fortuna estar aquí.' WHERE `ID`=59794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 불길한 곳이야.', `MaleText_loc4`='这地方真是衰透了。', `MaleText_loc5`='這裡絕不是一個好地方。', `MaleText_loc7`='Mal sitio para estar es este.' WHERE `ID`=59795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠한테서는 불행의 냄새가 나요.', `MaleText_loc4`='猢狲浑身都是霉运的臭味儿。', `MaleText_loc5`='猴人有倒楣的臭味。', `MaleText_loc7`='Los hozen apestan a mala fortuna.' WHERE `ID`=59796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 그루멀짐이다! 좋아.', `MaleText_loc4`='啊！一个土地精包裹。好极了。', `MaleText_loc5`='啊!一個咕嚕摩包包。很好。', `MaleText_loc7`='¡Ah! Un paquete grúmel. Muy bien.' WHERE `ID`=59797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 복덩이들, 본 적이 있어요.', `MaleText_loc4`='我知道这些幸运符。', `MaleText_loc5`='我知道這些幸運星。', `MaleText_loc7`='Conozco estos grisgrís.' WHERE `ID`=59798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해줬네. 이 무기들은 이 전당에 숨겨두고 철저히 관리하겠네. 모구는 이 보물들을 다신 볼 수 없을 거야.', `MaleText_loc4`='你做得很好。我们得看好这些武器，把它们藏在这座大殿里。魔古族休想再见到这些宝物了。', `MaleText_loc5`='做得很好。我們會把這些武器藏在大廳，嚴加保護，不會再讓魔古族見到這些寶物。', `MaleText_loc7`='Lo has hecho bien. Ocultaremos las armas en esta sala y las vigilaremos de cerca. Los mogu no volverán a ver estos tesoros.' WHERE `ID`=59799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 좋은 물건이 잘 모여 있네.', `MaleText_loc4`='啊，一大堆东西。', `MaleText_loc5`='啊，一堆好東西。', `MaleText_loc7`='Ah, un buen alijo de cosas.' WHERE `ID`=59800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네! 천둥왕의 도끼는 우리 것일세.', `MaleText_loc4`='干得好！雷电之王的战斧到手了。', `MaleText_loc5`='做得好!雷王之斧是我們的了。', `MaleText_loc7`='¡Bien hecho! El hacha del Rey del Trueno es nuestra.' WHERE `ID`=59801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 부탁인데 되도록 빨리 겨울의 꽃 문으로 가서 음영사부 마이키를 찾게.', `MaleText_loc4`='$n，我恳求你能否去冬花关，并尽快找到影踪派麦基大师。', `MaleText_loc5`='$n，我懇求你盡快前往冬綻關尋找影潘宗師麥積。', `MaleText_loc7`='$n, te imploro que vayas al Paso del Pétalo Glacial y encuentres al maestro Shado Maikee lo antes posible.' WHERE `ID`=59803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악어들이 마을을 공격하는 건 고대 모구의 저주 때문이라는군.', `MaleText_loc4`='我听说鳄鱼人因为一个上古魔古诅咒而变得具有攻击性。', `MaleText_loc5`='我聽說鱷魚會攻擊是因為一個古老的魔古詛咒。', `MaleText_loc7`='He oído que los crocoliscos están atacando debido a una antigua maldición mogu.' WHERE `ID`=59805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 아무리 그래도 호젠 계속 훔친다!', `MaleText_loc4`='该死的蠢蛋可阻止不了掠夺！', `MaleText_loc5`='該死的怪怪人別想阻止掠奪!', `MaleText_loc7`='¡Dingues makakus no detienen devastación!' WHERE `ID`=59806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악어 따위, 오라면 오라지. 어차피 언젠가는 공격을 멈출 테니까. 굳이 신경 쓸 필요 있나.', `MaleText_loc4`='要我说让那些鳄鱼人放马过来好了。他们最终会臣服，为什么要干涉呢？', `MaleText_loc5`='我說就讓那些鱷魚來吧。他們終究會停止攻擊的。為什麼要干涉呢?', `MaleText_loc7`='Dejemos que los crocoliscos vengan. Ya dejarán de atacar. ¿Por qué interferir?' WHERE `ID`=59807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 태워 버린다!', `MaleText_loc4`='蠢蛋要烧起来了！', `MaleText_loc5`='怪怪人會被燒死!', `MaleText_loc7`='¡Makakus van a arder!' WHERE `ID`=59808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각니 먹을 거 필요하다. 우낏 먹을 거 갖고 있다. 털어라!', `MaleText_loc4`='断牙需要食物。蠢蛋有食物。抢啊！', `MaleText_loc5`='斷齒需要食物。怪怪人有食物。搶啊!', `MaleText_loc7`='Dienterroto necesita komida. Makakus tienen komida. ¡Devastar!' WHERE `ID`=59809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕이 바뀌면 법도 바뀐다. 미안하지만 우낏 털어야겠다!', `MaleText_loc4`='新酋长，新规矩。抱歉，蠢蛋要遭劫了！', `MaleText_loc5`='新的大王，新的規則。抱歉，但是怪怪人將被掠奪!', `MaleText_loc7`='Nuevo rey, nuevas reglas. ¡Lo siento, pero makakus devastados!' WHERE `ID`=59810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뗏목을 마음대로 써도 좋소. 뗏목을 타고 싶으면 여기로 오면 되오. 기다리고 있을 테니까.', `MaleText_loc4`='这木筏归你了，邻居。你要是想用了，随时回来取。它就在这里等着你。', `MaleText_loc5`='這筏子是你的了，鄰居。只要你想要划筏，儘管回到這裡，我會在這等你。', `MaleText_loc7`='Esta balsa es toda tuya. Si alguna vez te apetece navegar, solo tienes que volver aquí. Te estará esperando.' WHERE `ID`=59811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹이 줄 시간이네.', `MaleText_loc4`='喂食的时间到了。', `MaleText_loc5`='該是吃飯的時候了。', `MaleText_loc7`='Hora de alimentarse.' WHERE `ID`=59812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배우는 중', `MaleText_loc4`='学习', `MaleText_loc5`='學習', `MaleText_loc7`='Aprendiendo' WHERE `ID`=59813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿵 딘이 당신을 공격합니다! 목숨을 걸고 싸우십시오!|TInterface\\Icons\\ability_warrior_secondwind.blp:20|t', `MaleText_loc4`='恐钉扑向了你！拼命的时候到了！|TInterface\\Icons\\ability_warrior_secondwind.blp:20|t', `MaleText_loc5`='鋼釘向你突襲!奮戰求生吧!|TInterface\\Icons\\ability_warrior_secondwind.blp:20|t', `MaleText_loc7`='¡Kung Din se ha abalanzado sobre ti! ¡Lucha por sobrevivir! |TInterfaceIconsability_warrior_secondwind.blp:20|t' WHERE `ID`=59814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요!', `FemaleText_loc4`='欢迎你，朋友！', `FemaleText_loc5`='歡迎你，朋友!', `FemaleText_loc7`='¡Hola, $gamigo:amiga;!' WHERE `ID`=59815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽으로 앉으세요. 먹을 걸 좀 가져다 드릴 테니.', `FemaleText_loc4`='到吧台这儿来坐一坐，朋友。我给你拿点吃的。', `FemaleText_loc5`='朋友，自己在酒吧裡找個位置坐。我會弄些食物給你吃。', `FemaleText_loc7`='Siéntate en la barra. Te traeré algo de comida.' WHERE `ID`=59816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님!', `FemaleText_loc4`='你好，$c！', `FemaleText_loc5`='嗨，$c!', `FemaleText_loc7`='¡Hola, $c!' WHERE `ID`=59817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 김이 모락모락 나는 뜨거운 차 한 잔 어떠세요?', `FemaleText_loc4`='嗨，你好！我能在你离开之前请你喝杯新鲜热茶吗？', `FemaleText_loc5`='喔，哈囉!在你離開前，要不要來我這邊喝杯燙手的熱茶呢?', `FemaleText_loc7`='¡Oh, hola! ¿Quieres una taza de té caliente antes de marcharte?' WHERE `ID`=59818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 할머니께서는, 주린 배를 안고 전장에 나가면 몸의 중심을 잡기가 어렵다고 말씀하셨어요.', `FemaleText_loc4`='我外婆常说，饿着肚子打仗会让你站都站不稳！', `FemaleText_loc5`='我奶奶曾經告訴我，空著肚子上戰場會讓一個戰士的平衡感變差!', `FemaleText_loc7`='¡Mi abuela solía decir que entrar en combate con el estómago vacío es malo para el equilibrio!' WHERE `ID`=59819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 이 동네에서 꽤 유명해지셨던걸요!', `FemaleText_loc4`='你好，$n！你在这儿很有名！', `FemaleText_loc5`='嗨，$n!你在這裡的名氣可不小!', `FemaleText_loc7`='¡Hola, $n! ¡Parece que te estás haciendo $gfamoso:famosa; por aquí!' WHERE `ID`=59820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 오셨어요, $n 님! 실종된 길잡이들을 찾으셨기를 바라요!', `FemaleText_loc4`='欢迎回来，$n！你找到了我们失踪的向导！', `FemaleText_loc5`='$n，歡迎回來!我看到你找回我們失蹤的嚮導了!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida;, $n! ¡Veo que has encontrado a los guías perdidos!' WHERE `ID`=59822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 오셨어요, $n 님!', `FemaleText_loc4`='欢迎回来，$n！', `FemaleText_loc5`='$n，歡迎回來!', `FemaleText_loc7`='¡Hola otra vez, $n!' WHERE `ID`=59823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지루가 장신구를 되찾았으니 이제 여관이 좀 조용해지겠어요!', `FemaleText_loc4`='现在季禄拿回了他的那些小玩意儿，或许我能在旅馆里消停一会了！', `FemaleText_loc5`='現在姬盧找回他的小飾品了，或許我在客棧裡會有些好日子過!', `FemaleText_loc7`='¡Ahora que Ji-Lu ha recuperado sus abalorios quizás vuelva la paz a la posada!' WHERE `ID`=59824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 오셨군요, $c님!', `FemaleText_loc4`='又见面了，$c！', `FemaleText_loc5`='嗨，$c，又見到你了!', `FemaleText_loc7`='¡Hola de nuevo, $c!' WHERE `ID`=59825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 여관에 위대한 $n 님이 오시다니 얼마나 기쁜지 몰라요!', `FemaleText_loc4`='伟大的$n光临我的寒舍，真是不胜荣幸！', `FemaleText_loc5`='偉大的$n來到我建造的地方，真是太榮幸了!', `FemaleText_loc7`='¡Es todo un placer tener de nuevo $gal:a la; gran $n en mi establecimiento!' WHERE `ID`=59826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님!', `FemaleText_loc4`='你好，$n！', `FemaleText_loc5`='歡迎，$n!', `FemaleText_loc7`='¡Saludos, $n!' WHERE `ID`=59827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님은 언제든 환영이에요!', `FemaleText_loc4`='这间旅馆永远欢迎你，$n！', `FemaleText_loc5`='$n，旅店永遠歡迎你!', `FemaleText_loc7`='¡Siempre eres $gbienvenido:bienvenida; en la posada, $n!' WHERE `ID`=59828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맥주통 휴게소의 영웅이 돌아오셨군요!', `FemaleText_loc4`='酒坛集的英雄回来了！', `FemaleText_loc5`='獨罈集的英雄回來了!', `FemaleText_loc7`='¡$GEl héroe:La heroína; de Barrilia ha vuelto!' WHERE `ID`=59829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 두 분, 꼼수 쓰지 마세요!', `FemaleText_loc4`='好吧你们两个，好好玩！', `FemaleText_loc5`='好了你們兩個，好好的一起玩!', `FemaleText_loc7`='¡Ustedes dos! ¡Pórtense bien!' WHERE `ID`=59830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 변변찮은 가게에 잘 왔소, $c.', `MaleText_loc4`='欢迎光临小店，$c。', `MaleText_loc5`='$c，歡迎來到我的小店。', `MaleText_loc7`='$GBienvenido:Bienvenida; a mi humilde tienda, $c.' WHERE `ID`=59831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 둘러보시오.', `MaleText_loc4`='请随意挑选。', `MaleText_loc5`='隨意看看我的商品吧。', `MaleText_loc7`='Mira mi mercancía todo lo que quieras.' WHERE `ID`=59832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c! 신선한 향신료에 관심이 있을 것 같이 생겼군! 아니면 여행길에 읽을 책은 어떠시오?', `MaleText_loc4`='你好，$c！看起来你会对新鲜辣椒感兴趣的！也许再来几本旅途中解闷用的书。', `MaleText_loc5`='你好啊，$c!你看起來似乎是個會對新鮮香料感興趣的人!想不想帶幾本書去旅行?', `MaleText_loc7`='¡Saludos, $c! ¡Parece que te podrían interesar especias frescas! ¿O quizás algunos libros para tu aventura?' WHERE `ID`=59833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 오셨소! 야영지 동쪽으로는 우리 가게만 한 곳이 없다오!', `MaleText_loc4`='欢迎！你不会在营地东边找到比这更好的精品了！', `MaleText_loc5`='歡迎!你在東營區不會找到比這裡更好的選擇了!', `MaleText_loc7`='¡$GBienvenido:Bienvenida;! ¡No encontrarás una selección mejor al este del campamento!' WHERE `ID`=59834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 다시 찾아 주시오, $c!', `MaleText_loc4`='一定要再回来看我哦，$c！', `MaleText_loc5`='$c，務必停留一會兒並再來見我!', `MaleText_loc7`='¡Asegúrate de volver a pasar por aquí, $c!' WHERE `ID`=59835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기는 내 고향일세. 고향이 해를 입지 않도록 지키는 것이 나의 의무이자 소망이지.', `MaleText_loc4`='锦绣谷是我的家园，保护它免遭侵犯既是我的责任，亦是我的愿望。', `MaleText_loc5`='這個山谷是我的家。保護這裡不受傷害，是我的責任，也是我的願望。', `MaleText_loc7`='El valle es mi hogar. Mi deber y deseo es protegerlo de todo daño.' WHERE `ID`=59836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 바람이 좋군.', `MaleText_loc4`='今天的风正好。', `MaleText_loc5`='今天的風很好。', `MaleText_loc7`='Los vientos son propicios hoy.' WHERE `ID`=59837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 탈것에 복이 깃들었어.', `MaleText_loc4`='幸运对着土地精的坐骑微笑。', `MaleText_loc5`='好運對咕嚕摩的坐騎微笑。', `MaleText_loc7`='La fortuna sonríe a las monturas grúmel.' WHERE `ID`=59838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 와요!', `MaleText_loc4`='快点儿回来！', `MaleText_loc5`='很快就回來!', `MaleText_loc7`='¡Vuelve pronto!' WHERE `ID`=59839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산은 새는 용서하지만, 기수는 늘 용서하지는 않아.', `MaleText_loc4`='高山会原谅飞鸟，但不一定会宽恕骑手。', `MaleText_loc5`='飛鳥能在高山上自在飛翔，但是騎客就難說了。', `MaleText_loc7`='La montaña perdonará al pájaro, pero no siempre al jinete.' WHERE `ID`=59840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하러 왔소?', `MaleText_loc4`='你来这儿钓鱼？', `MaleText_loc5`='你來這釣魚嗎?', `MaleText_loc7`='¿Has venido a pescar?' WHERE `ID`=59841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악어들이 왜 공격하기 시작했는지 모르겠소. 뭐 달라진 거라도 있나?', `MaleText_loc4`='我想不出是什么东西使得这些鳄鱼开始有攻击性。发生什么事了？', `MaleText_loc5`='我無法想像什麼事情導致這些鱷魚開始攻擊。有什麼改變了嗎?', `MaleText_loc7`='No se me ocurre qué es lo que ha podido provocar los ataques de estos crocoliscos. ¿Qué ha cambiado?' WHERE `ID`=59842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 고맙소, $n. 악어들이 훨씬 얌전해졌소.$b$b우리도 나름대로 할 일을 하고 있지. 물고기를 딱 먹을 만큼만 잡고 있다오.', `MaleText_loc4`='再次感谢你的帮助，$n。最近鳄鱼像以前一样不再那么有攻击性了。$b$b我们也在改善自己的行为，只要鱼够吃，我们再也不会滥捕了。', `MaleText_loc5`='再次感謝你幫的忙，$n。鱷魚的攻擊不像之前那麼頻繁了。$b$b我們也正在盡我們的一份力。我們不再捕捉超過我們所能吃的那麼多魚了。', `MaleText_loc7`='Gracias de nuevo por tu ayuda, $n. Los crocoliscos ya no atacan tanto como antes.$b$bNosotros también estamos poniendo de nuestra parte; no hemos pescado más peces de los que necesitamos para comer.' WHERE `ID`=59843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $r님.', `FemaleText_loc4`='你好，$r。', `FemaleText_loc5`='哈囉，$r。', `FemaleText_loc7`='Hola, $r.' WHERE `ID`=59844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 아무것도 없어요... 가요!', `MaleText_loc4`='这儿没什么好看的……走开！', `MaleText_loc5`='這裡沒什麼好看的...快離開吧!', `MaleText_loc7`='¡No hay nada que ver aquí! ¡Fuera!' WHERE `ID`=59845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 곡식이 담긴 작은 바구니예요...', `MaleText_loc4`='我是一个装满谷物的小篮子……', `MaleText_loc5`='我是個小酒糟桶...', `MaleText_loc7`='Soy un pequeño cesto lleno de grano...' WHERE `ID`=59846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돌아갈 거예요!', `MaleText_loc4`='我不会回去的！', `MaleText_loc5`='我不會回去的!', `MaleText_loc7`='¡No voy a volver!' WHERE `ID`=59847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 무서운 세상을 살아가는 작은 그루멀일 뿐이에요.', `MaleText_loc4`='我只是这个可怕世界里的一个渺小的土地精。', `MaleText_loc5`='我只是這可怕世界上的一個小小咕嚕摩。', `MaleText_loc7`='Solo soy un pequeño grúmel en un mundo peligroso.' WHERE `ID`=59848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 같이 안 갈 겁니까?', `MaleText_loc4`='你确定不想跟我一起去吗？', `MaleText_loc5`='你確定不想跟我一起走嗎?', `MaleText_loc7`='¿Seguro que no quieres venir conmigo?', `FemaleText_loc1`='정말 같이 안 갈 거예요?', `FemaleText_loc4`='你确定不想跟我一起去吗？', `FemaleText_loc5`='你確定不想跟我一起走嗎?', `FemaleText_loc7`='¿Seguro que no quieres venir conmigo?' WHERE `ID`=59849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 갈래요! 그루멀은 여기 있는 게 안전해요.', `MaleText_loc4`='不！土地精在这儿很安全。', `MaleText_loc5`='不!咕嚕摩在這裡很安全。', `MaleText_loc7`='¡No! El grúmel está a salvo aquí.' WHERE `ID`=59850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물속을 조금 더... 쾌적하게 다닐 수 있게 해드리지요.', `FemaleText_loc4`='请允许我让你的水下之旅变得更加……愉悦。', `FemaleText_loc5`='請容我讓你有個更...舒適的水下經驗。', `FemaleText_loc7`='Deja que haga tu experiencia submarina un poco más... placentera.' WHERE `ID`=59851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수영 속도를 다시 높여 주시겠습니까?', `MaleText_loc4`='你能再次帮我提高游泳速度吗？', `MaleText_loc5`='你可以再次提高我的游泳速度嗎?', `MaleText_loc7`='¿Podrías volver a aumentar mi velocidad de nado?', `FemaleText_loc1`='수영 속도를 다시 높여 주시겠어요?', `FemaleText_loc4`='你能再次帮我提高游泳速度吗？', `FemaleText_loc5`='你可以再次提高我的游泳速度嗎?', `FemaleText_loc7`='¿Podrías volver a aumentar mi velocidad de nado?' WHERE `ID`=59852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아!', `MaleText_loc4`='啊啊啊！', `MaleText_loc5`='啊啊啊啊啊啊!', `MaleText_loc7`='¡Aaaaaaaah!' WHERE `ID`=59853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 미쳤다!', `MaleText_loc4`='蠢蛋疯了！', `MaleText_loc5`='怪怪人瘋了!', `MaleText_loc7`='¡Makakus están lokos!' WHERE `ID`=59854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풋풋 풀려났다! 도망쳐라!', `MaleText_loc4`='波波要出来啦！快跑！', `MaleText_loc5`='噗噗鬆綁了!逃啊!', `MaleText_loc7`='¡Poot Poot está suelto! ¡Korran!' WHERE `ID`=59855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미친 설인이다! 미친 설인이다!', `MaleText_loc4`=' 雪人疯了！雪人发疯了！', `MaleText_loc5`='瘋雪人!瘋雪人!', `MaleText_loc7`='¡Yeti loko! ¡Yeti loko!' WHERE `ID`=59856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망했다!', `MaleText_loc4`='真见鬼！', `MaleText_loc5`='死定了我!', `MaleText_loc7`='¡Kraku!' WHERE `ID`=59857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='풋난리다!', `MaleText_loc4`='波波发火啦！', `MaleText_loc5`='便便末日!', `MaleText_loc7`='¡Mumukalipsis!' WHERE `ID`=59858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이크!', `MaleText_loc4`='哎呀！', `MaleText_loc5`='啊!', `MaleText_loc7`='¡Uy!' WHERE `ID`=59859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것은 배고픈 악어의 이야기입니다.', `FemaleText_loc4`='这是一个关于《饥饿的鳄鱼》的故事。', `FemaleText_loc5`='這是關於飢餓的鱷魚的故事。', `FemaleText_loc7`='Esta es la historia de los crocoliscos hambrientos.' WHERE `ID`=59860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나르송 해구의 악어들은 물고기를 먹었습니다. 배불리 먹고 행복하게 살았지요.', `FemaleText_loc4`='纳松海沟里的鳄鱼以鱼类为食，他们过得悠闲自得。', `FemaleText_loc5`='納松海溝的鱷魚吃魚。他們原本很肥很快樂。', `FemaleText_loc7`='Los crocoliscos de la Zanja de Narsong comían peces. Estaban gordos y eran felices.' WHERE `ID`=59861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데 갑자기 상어들이 나타났습니다.', `FemaleText_loc4`='然后鲨鱼来了。', `FemaleText_loc5`='然後鯊魚來了。', `FemaleText_loc7`='Luego llegaron los tiburones.' WHERE `ID`=59862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상어와 물고기를 놓고 경쟁해야 했지만, 악어들은 살아남았지요.', `FemaleText_loc4`='鲨鱼也以鱼类为食，但鳄鱼还是生存了下来。', `FemaleText_loc5`='鯊魚搶魚吃，但鱷魚們存活了下來。', `FemaleText_loc7`='Los tiburones rivalizaron con ellos por los peces, pero los crocoliscos sobrevivieron.' WHERE `ID`=59863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼마 지나지 않아 판다렌들이 왔어요.', `FemaleText_loc4`='不久以后，熊猫人来了。', `FemaleText_loc5`='沒多久之後，熊貓人來了。', `FemaleText_loc7`='Poco después, llegaron los pandaren.' WHERE `ID`=59864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌은 해구의 물에서 물고기를 잡았지만, 그래도 악어들은 살아남았습니다.', `FemaleText_loc4`='熊猫人在海沟里钓鱼，但鳄鱼还是生存了下来。', `FemaleText_loc5`='熊貓人在壕溝水中捕魚，但鱷魚們存活了下來。', `FemaleText_loc7`='Los pandaren pescaban en las aguas de la Zanja, pero los crocoliscos sobrevivieron.' WHERE `ID`=59865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막으로, 호젠이 나르송 해구에 나타났습니다.', `FemaleText_loc4`='最后，猢狲也来到了纳松海沟。', `FemaleText_loc5`='終於，猴人來到了納松海溝。', `FemaleText_loc7`='Por último, llegaron los hozen a la Zanja de Narsong.' WHERE `ID`=59866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호젠은 물고기를 남획했습니다. 다 먹지도 못할 만큼 많은 물고기를 잡았지요.', `FemaleText_loc4`='猢狲大肆捕捞、涸泽而渔，也不管吃不吃得完。', `FemaleText_loc5`='猴人在這地區濫捕，捕捉多到他們根本吃不完的魚。', `FemaleText_loc7`='Los hozen se excedieron en la pesca; pescaban más peces de los que podían comer.' WHERE `ID`=59867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먹을 물고기가 없어지자 배고픈 악어들은 필사적이 되었습니다. 판다렌을 공격한 것은 순전히 배가 고팠기 때문입니다.', `FemaleText_loc4`='因为没鱼可吃，鳄鱼变得饥饿和绝望。他们攻击熊猫人纯粹是因为饥饿难耐。', `FemaleText_loc5`='因為沒有魚可吃，鱷魚們變得飢餓與絕望。他們因為極度飢餓而攻擊了熊貓人。', `FemaleText_loc7`='Al quedarse sin peces para comer, los crocoliscos estaban desesperados. Y atacaron a los pandaren acuciados por el hambre.' WHERE `ID`=59868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두려움에 질린 판다렌은 마을을 지키기 위해 나르송 해구의 악어를 모두 죽였지요.', `FemaleText_loc4`='熊猫人既因为恐惧，又为求自保，杀光了纳松海沟里的鳄鱼。', `FemaleText_loc5`='熊貓人出於害怕和防衛，將納松海溝的鱷魚殺光了。', `FemaleText_loc7`='Los pandaren, atemorizados y en defensa propia, mataron a todos los crocoliscos de la Zanja de Narsong.' WHERE `ID`=59869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 트롤 둘이 앞쪽의 문을 박차고 튀어나옵니다!', `MaleText_loc4`='两个赞达拉巨魔撞破房门，向你冲了过来！', `MaleText_loc5`='有兩個贊達拉食人妖闖過了前方那道門了!', `MaleText_loc7`='¡Un par de trols Zandalari entran por la puerta frente a ti!' WHERE `ID`=59870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신경 꺼! 두고 온 게 뭐든 이제 필요 없으니까!', `MaleText_loc4`='没关系！反正我们也用不着那些了！', `MaleText_loc5`='沒關係!反正我們也不需要那些了!', `MaleText_loc7`='¡No importa! ¡No nos hace falta lo que hay por allá!' WHERE `ID`=59871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 열받게 했겠다!', `MaleText_loc4`='现在你把我惹毛了！', `MaleText_loc5`='現在你惹毛我了!', `MaleText_loc7`='¡Ahora me han hecho enfadar!' WHERE `ID`=59872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 좋다! 놀아주지, 친구들.', `MaleText_loc4`='好吧！游戏时间到，“朋友们”。', `MaleText_loc5`='好吧!是時候玩玩了，「朋友們」。', `MaleText_loc7`='¡Muy bien! Hora de jugar, "colegas".' WHERE `ID`=59873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나르송 악어는 멸종됐습니다... 단지 판다렌들이 자초지종을 알지 못했다는 이유 때문에요.', `FemaleText_loc4`='纳松海沟的鳄鱼不再那么……只因为熊猫人不了解整个事情的来龙去脉。', `FemaleText_loc5`='納松海溝的鱷魚消失了...就因為熊貓人無法看清整件事的前因後果。', `FemaleText_loc7`='El crocolisco de Narsong ya no existe... Simplemente porque los pandaren no conocían toda la historia.' WHERE `ID`=59874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 불의 정령 데려온 사람이다!', `MaleText_loc4`='嘿，你好！是你把火灵带回来的吗？', `MaleText_loc5`='嘿!就是你把火靈帶回來的嗎?', `MaleText_loc7`='¡Oye! ¿Eres tú quien ha traído de vuelta al espíritu del fuego?' WHERE `ID`=59875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불의 정령 뜨거워요? 당연히 뜨겁겠죠?', `MaleText_loc4`='他是不是很烫？我敢说，他肯定很烫！', `MaleText_loc5`='他會燙嗎?我敢說他很燙!', `MaleText_loc7`='¿Quemaba? ¡Seguro que sí!' WHERE `ID`=59876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연하지! 바보 같은 소리 하지 마, 덩.', `MaleText_loc4`='他当然很烫了！别说傻话了，小邓。', `MaleText_loc5`='他當然很燙了!別傻了，小鄧。', `MaleText_loc7`='¡Pues claro que quemaba! No seas tonto, Deng.' WHERE `ID`=59877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았어요, 안녕.', `MaleText_loc4`='好吧，再见。', `MaleText_loc5`='好吧，再見。', `MaleText_loc7`='Bueno, adiós.' WHERE `ID`=59878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 센가 봐요! 마음만 먹으면 저 다리를 걷어차서 두 동강 낼 수도 있겠죠?', `MaleText_loc4`='我敢肯定，你非常强大，哈？如果你愿意，一脚就可以把那座桥踢成两段！', `MaleText_loc5`='我敢說你一定很強，是嗎?只要有心，你說不定能把那座橋一腳踢成兩段!', `MaleText_loc7`='Apuesto a que eres muy fuerte, ¿eh? ¡Probablemente podrías partir en dos ese puente si te lo propusieras!' WHERE `ID`=59879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보. 그건 몰라도 너를 저 언덕 너머로 뻥 차 버릴 수는 있을걸! 히히!', `MaleText_loc4`='不不。但他们肯定能把你踢到山那边去！哈！', `MaleText_loc5`='哇。我敢說他們絕對能把你一腳踢到山的另一邊!哈!', `MaleText_loc7`='Na, na. ¡Pero seguro que podría darte una patada y mandarte a esa colina! ¡Jaa!' WHERE `ID`=59880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또야!', `MaleText_loc4`='又来了！', `MaleText_loc5`='別又來了!', `MaleText_loc7`='¡Otra vez no!' WHERE `ID`=59881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 아무도 못 본 거야, 알았지?', `MaleText_loc4`='你们什么都没看见！', `MaleText_loc5`='你們都沒有看到!', `MaleText_loc7`='¡No habéis visto eso!' WHERE `ID`=59882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 머리!', `MaleText_loc4`='我的辫子！', `MaleText_loc5`='我的辮子!', `MaleText_loc7`='¡Mis trenzas!' WHERE `ID`=59883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕!', `MaleText_loc4`='再见！', `MaleText_loc5`='再見!', `MaleText_loc7`='¡Adiós!' WHERE `ID`=59884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상어가 당신을 떨어뜨리려 합니다. 꽉 잡으십시오!$b$b|TInterface\\Icons\\inv_misc_desecrated_leatherglove.blp:32|t 꽉 잡으십시오!', `MaleText_loc4`='她要把你甩下去，抓紧了！$b$b|TInterface\\Icons\\inv_misc_desecrated_leatherglove.blp:32|t坚持住', `MaleText_loc5`='她在試著拋下你，抓緊了!$b$b|TInterface\\Icons\\inv_misc_desecrated_leatherglove.blp:32|t抓緊', `MaleText_loc7`='¡Intenta lanzarte, agárrate fuerte!$b$b|TInterfaceIconsinv_misc_desecrated_leatherglove.blp:32|t Aguanta.' WHERE `ID`=59885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0404|Hspell:116711|h[불꽃 흡수]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='%s开始对他的武器施放|cFFFF0404|Hspell:116711|h[引导火焰]|h|r！', `MaleText_loc5`='%s開始|cFFFF0404|Hspell:116711|h[牽引火焰]|h|r到他的武器上!', `MaleText_loc7`='¡%s empieza a lanzar |cFFFF0404|Hspell:116711|h[Provocar Llama]|h|r en su arma!' WHERE `ID`=59886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네를 보니 마음이 조금이나마 가벼워지는군, $c. 우리는 두 적과 싸우고 있다네.$B$B문에서는 야운골 무리를 물리치려 애쓰고 있고, 북쪽의 산 위에서는 알 수 없는 세력이 음영파 수도원을 장악했다네.', `MaleText_loc4`='一看到你我的精神就振奋了，$c。我们在两条战线上激战。$B$B在大门处，我们奋力击退野牛人大军。在北边的山上，我们的影踪禅院被未知力量攻占了。', `MaleText_loc5`='我的精神因見到你而高昂，$c。我們在兩道前線作戰。$B$B我們嘗試將城門的揚古部落逼退，而北方山上的影潘僧院已經讓未知的軍隊攻陷了。', `MaleText_loc7`='Mi espíritu se alegra mucho de verte, $c. Luchamos en dos frentes.$B$BEstamos intentando empujar a la horda yaungol de vuelta a la puerta. Y en lo alto de la montaña, en el norte, hemos perdido el Monasterio del Shadopan ante fuerzas desconocidas.' WHERE `ID`=59887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 식으로 날 공격하겠다고, $p? 한심하기 짝이 없구나!', `MaleText_loc4`='你这样攻击我，$p？真是班门弄斧！', `MaleText_loc5`='用這種方式攻擊我，$p?好弱的計畫!', `MaleText_loc7`='¿Así me atacas, $p? ¡Qué plan más estúpido!' WHERE `ID`=59888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크게 한 방 먹여주지!', `MaleText_loc4`='该大巴巴姆上场了！', `MaleText_loc5`='是大爆發的時候啦!!', `MaleText_loc7`='¡¡Es hora del gran BA BAM!!' WHERE `ID`=59889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으어... 깃발은 네 거다.', `MaleText_loc4`='呃……旗帜归你了。', `MaleText_loc5`='嗯唔...旗幟是你的。', `MaleText_loc7`='Aaag... El estandarte es todo tuyo.' WHERE `ID`=59893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 누구야?!', `MaleText_loc4`='那是什么？谁？！', `MaleText_loc5`='搞啥?誰啊?!', `MaleText_loc7`='¿Pero qué...? ¡¿Quién?!' WHERE `ID`=59894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 네 죽은 사부의 깃발을 차지했다. 올 테면 와 봐라, $r!', `MaleText_loc4`='是我拿了你那个死鬼大师的旗帜。来抓我呀，$r！', `MaleText_loc5`='我摘了你死去宗師的旗幟。過來殺我啊，$r!', `MaleText_loc7`='Yo cogí el estandarte de tu maestro muerto. ¡Ven a mí, $r!' WHERE `ID`=59895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 들여보내면 안 돼. 잘못하면 목이 잘린다고.', `MaleText_loc4`='你不能让任何人过去，伙计。否则就等着掉脑袋吧。', `MaleText_loc5`='老兄，別讓任何人通過這裡，要不然你就得賠上小命。', `MaleText_loc7`='No puedes dejar pasar a nadie, colega. O perderás la cabeza.', `FemaleText_loc1`='아무도 들여보내면 안 돼. 잘못하면 목이 잘린다고.', `FemaleText_loc4`='你不能让任何人过去，伙计。否则就等着掉脑袋吧。', `FemaleText_loc5`='老兄，別讓任何人通過這裡，要不然你就得賠上小命。', `FemaleText_loc7`='No puedes dejar pasar a nadie, colega. O perderás la cabeza.' WHERE `ID`=59896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비는 어떻게 돼 가?', `MaleText_loc4`='准备得怎么样了，伙计？', `MaleText_loc5`='老兄，準備工作做得如何?', `MaleText_loc7`='¿Cómo van los preparativos, colega?', `FemaleText_loc1`='준비는 어떻게 돼 가?', `FemaleText_loc4`='准备得怎么样了，伙计？', `FemaleText_loc5`='老兄，準備工作做得如何?', `FemaleText_loc7`='¿Cómo van los preparativos, colega?' WHERE `ID`=59897;
