UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 이쪽이에요. 당신 도움이 필요해요.', `FemaleText_loc4`='嘿，$n，这边。我们需要你的帮助。', `FemaleText_loc5`='嘿，$n，到這兒來。我們需要你的幫忙。', `FemaleText_loc7`='Eh, $n, aquí. Necesitamos tu ayuda.' WHERE `ID`=59908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 좋아. 아주 안 좋아.', `MaleText_loc4`='不好。真的不好。', `MaleText_loc5`='糟了，真的糟了。', `MaleText_loc7`='Esto es malo, muy malo.' WHERE `ID`=59909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭한 카파 한 잔만큼 좋은 게 없지! 콩을 딱 맞게 볶아서 바로 간 다음에 깨끗한 물로 내린 카파 말이야.$b$b지친 나그네나 세심한 수도사에게 완벽한 음료지.', `MaleText_loc4`='什么也比不上一杯上好的咔啡啊！将种子烘焙到恰到好处后，趁热磨碎，再放到纯水中酿造。$B$B对疲惫的旅行者或好学的僧侣来说再好不过了。', `MaleText_loc5`='沒有東西比得上一大杯卡法!種子烘培得剛剛好，新鮮研磨，用純水沖泡。$B$B對疲憊的旅人或用功的僧侶來說是絕配啊。', `MaleText_loc7`='¡No hay nada mejor que una buena taza de kafa! Cuando los granos están tostados en su punto, recién molidos y preparados con agua pura.$B$BEs perfecto para un viajero agotado o un monje estudioso.' WHERE `ID`=59910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 무슨 생각을 한 거지! 복이 달아나겠어!', `MaleText_loc4`='我在想什么啊！真是个倒霉蛋！', `MaleText_loc5`='我在想什麼啊!真是個厄運星!', `MaleText_loc7`='¡En qué estaba pensando! ¡Qué idiota!' WHERE `ID`=59911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 되고 말고.', `MaleText_loc4`='不……不……不好。', `MaleText_loc5`='不...不...不好。', `MaleText_loc7`='No... No... No es bueno.' WHERE `ID`=59912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='염소들한테 열매를 먹이지 말았어야 해.', `MaleText_loc4`='真不该去喂这些山羊。', `MaleText_loc5`='從不該拿來餵羊的。', `MaleText_loc7`='No debería haber dado de comer a las cabras.' WHERE `ID`=59913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, 거기! 나한테 도전하러 온 건가요?', `FemaleText_loc4`='嘿！你是来这儿挑战我的吗？', `FemaleText_loc5`='嘿!你是來挑戰我的?', `FemaleText_loc7`='¡Hey! ¿Has venido a desafiarme a una pelea?' WHERE `ID`=59914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸웁시다!', `MaleText_loc4`='让我们开打吧！', `MaleText_loc5`='出手吧!', `MaleText_loc7`='¡Vamos a pelear!', `FemaleText_loc1`='싸웁시다!', `FemaleText_loc4`='让我们开打吧！', `FemaleText_loc5`='出手吧!', `FemaleText_loc7`='¡Vamos a pelear!' WHERE `ID`=59915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대련이 기대되는군. 물론 나는 이길 생각이야.', `MaleText_loc4`='我很期待我们的对决。毫无疑问，我赢定了。', `MaleText_loc5`='我很期待我們的比武。當然，我會贏。', `MaleText_loc7`='Estoy deseando que llegue nuestra refriega. Por supuesto, espero ganar.' WHERE `ID`=59916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 정말 열심히 훈련했어요! 이제 날 꺾을 순 없을걸요, $n.', `FemaleText_loc4`='我一直在非常刻苦的训练！你现在无法击败我了，$n。', `FemaleText_loc5`='我一直非常辛苦地鍛鍊!現在你是不可能打敗我的，$n。', `FemaleText_loc7`='¡He estado entrenando mucho! Ahora ya no tienes posibilidades de derrotarme, $n.' WHERE `ID`=59917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대의 무술 실력을 빨리 보고 싶군, $c.', `MaleText_loc4`='我很想见识下你的战斗风格，$c。', `MaleText_loc5`='我對你的武術風格非常有興趣，$c。', `MaleText_loc7`='Tengo muchas ganas de ver tu estilo de lucha, $c.' WHERE `ID`=59918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 자기. 멋진 갑옷을 입고 있네요.$b$b당신도 주학의 가르침을 따르나요? 나와 대련할래요?', `FemaleText_loc4`='嘿，你好啊，宝贝儿。你穿的那身花俏装备还真不赖啊。$b$b这么说你也领悟了朱鹤之道？有兴趣过两招吗？', `FemaleText_loc5`='你好，甜心。你在那身花俏的盔甲中看起來挺不錯的。$b$b你領悟了紅鶴之道?有沒有興趣來比劃一下?', `FemaleText_loc7`='Hola, encanto. Te queda estupendamente esa armadura.$b$b¿Así que tú también has encontrado el camino de la Grulla Roja? ¿Te interesaría un duelo?' WHERE `ID`=59919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 요람에는 진위가 별로 없습니다. 아니, 아마도 저 하나뿐일 겁니다.$b$b우리 민족은 보통 츠지의 가르침을 멀리합니다. 하긴, 학은 잉어를 잡아먹으니까요.', `MaleText_loc4`='在这赤精栖木，你找不到其他锦鱼人了。事实上，我想我是唯一的一个。$b$b通常，我的族人会避开赤精和他的教义。毕竟，鹤是以鱼为食的。', `MaleText_loc5`='你在赤吉搖籃這裡不會看到很多錦魚人。事實上，我相信我可能是唯一的一個。$b$b普遍來說，我們迴避赤吉和他的教義。畢竟鶴是會吃魚的。', `MaleText_loc7`='No vas a encontrar a muchos jinyu por aquí, en la Cuna de Chi-Ji. De hecho, creo que yo soy el único.$b$bPor lo general, mi gente rehúye a Chi-Ji y sus enseñanzas. Al fin y al cabo, la grulla come carpas.' WHERE `ID`=59920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='델로니우스에게 당신의 무술 실력에 대해서는 익히 들었습니다. 빨리 내 눈으로 보고 싶군요.', `FemaleText_loc4`='塞隆尼斯跟我讲了很多关于你在战斗中的技巧。我很期待能够亲眼见识一下。', `FemaleText_loc5`='瑟隆諾斯跟我說了許多關於你在戰鬥中的技巧。我期待能親眼目睹。', `FemaleText_loc7`='Thelonius me ha hablado de tu destreza en la batalla. Estoy deseando verla con mis propios ojos.' WHERE `ID`=59921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 나의 적수.$b$b나는 훈련하느라 아주 바빴다.$b$b너도 그랬겠지?', `FemaleText_loc4`='你好，对手。$b$b我正忙着训练。$b$b希望你也是。', `FemaleText_loc5`='哈囉，對手。$b$b我最近忙著鍛鍊。$b$b我希望你也有這麼做。', `FemaleText_loc7`='Hola, rival.$b$bHe estado entrenando mucho.$b$bEspero que tú hayas estado haciendo lo mismo.' WHERE `ID`=59922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투카툭 너 때리고 치고 차고 긁고 물고 찌르고 응가할 테다.', `MaleText_loc4`='图卡图克要揍死你、捶死你、踢死你、抓死你、咬死你、戳死你、踩死你、烦死你……', `MaleText_loc5`='圖克·吐克要揍你捶你踢你抓你咬你戳你打你用便便丟你還有...', `MaleText_loc7`='Tukka-Tuk va a pegar a ti puñetazos y te va a machakar y a patear y a arañar y a morder y a hacer kraku y...' WHERE `ID`=59923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 친구.$b$b이야기는 많이 들었네. 이 섬을 누비면서 대련 상대를 꺾고 있다지? 나도 도전할 각오가 됐네.', `MaleText_loc4`='你好，邻居。$b$b我听说了很多关于你的事，你在这座岛上几乎战无不胜。我想是时候给你个机会来挑战我了。', `MaleText_loc5`='你好啊，鄰居。$b$b我聽說了很多關於你的事。你一直在島上大大小小的比試中贏得勝利。我想我準備好要挑戰你了。', `MaleText_loc7`='¿Qué hay?$b$bMe han hablado mucho de ti. Has estado ganando duelos por toda esta isla. Supongo que es el momento de darte una oportunidad.' WHERE `ID`=59924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 이길 자는 없다.$b$b이 섬에서 몇 주째 머물며 매일 대련을 하고 있지만, 실력들이 내 발끝에도 못 미치더군.$b$b판다리아는 고작 이 정도인가?', `MaleText_loc4`='没人能够击败我。$b$b我来这岛上也有数周时间了，每天都在决斗，至今未尝败绩。$b$b这就是潘达利亚的全部实力了吗？', `MaleText_loc5`='沒有人可以打敗我。$b$b我已經到這島上幾週了，天天與人比試，卻無人能敵。$b$b難道潘達利亞的最強武術不過爾爾?', `MaleText_loc7`='Nadie puede derrotarme.$b$bLlevo semanas en esta isla, batiéndome en duelo cada día, y nadie se ha acercado siquiera a derrotarme.$b$b¿Esto es lo máximo que puede ofrecer Pandaria?' WHERE `ID`=59925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 문파 최고의 수련생들과 맞서서 모두 꺾었군요. 이제 진짜 실력이 어느 정도인지 봅시다.', `MaleText_loc4`='你不仅挑战了我们最强的弟子，还将他们全部击败。现在让我们来瞧瞧你到底是何方神圣……', `MaleText_loc5`='你面對過我們最好的學徒，並將他們全部擊敗。現在讓我們看看你真正的能耐...', `MaleText_loc7`='Te has enfrentado a nuestros mejores alumnos y los has derrotado a todos. Ahora veremos realmente lo que vales...' WHERE `ID`=59926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 날세. 만나서 반갑군, $n.$b$b그럼 시작할까?', `MaleText_loc4`='又是我。很高兴见到你，$n。$b$b我们开始吧？', `MaleText_loc5`='又是我。很高興見到你，$n。$b$b我們可以開始了嗎?', `MaleText_loc7`='Soy yo otra vez. Me alegro de verte, $n.$b$b¿Empezamos?' WHERE `ID`=59927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 제 실력을 시험하는 것은 흔치 않은 일입니다.$b$b당신도 나와 싸울 준비가 된 것 같군요, $n. 제 판단이 옳았는지를 확인해 보지요.', `MaleText_loc4`='今天是测试我能力绝佳的好日子。$b$b我想你已经准备好迎战了，$n。让我们来瞧瞧我说的对不对。', `MaleText_loc5`='這是一個讓我可以測試我的功力的少見吉日。$b$b我想你準備好要和我比劃比劃了，$n。讓我們看看我是否是對的。', `MaleText_loc7`='Raro y feliz es el día en que pongo a prueba mis habilidades.$b$bCreo que ya puedes enfrentarte a mí, $n. Veamos si estoy en lo cierto.' WHERE `ID`=59928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주학의 길은 틀렸어. 나는 진실을 봤다고!$b$b모든 길은 절망으로 이어질 뿐이야! 너희에겐 희망이 없어! 너희 누구에게도!', `FemaleText_loc4`='朱鹤之道注定是一条通往失败的道路，我见过真相！$b$b所有的道路都通向绝望！你没有任何希望！你们都没有！！', `FemaleText_loc5`='紅鶴之道是一條失敗之道。我見識過真相!$b$b所有的道路都通往絕望!你們沒有一點希望!你們全部都是!!', `FemaleText_loc7`='El camino de la Grulla Roja es un camino de fracasos. ¡He visto la verdad!$b$b¡Todos los caminos llevan a la desesperación! ¡No hay esperanza! ¡¡PARA NADIE!!' WHERE `ID`=59929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대련하러 오셨습니까?', `MaleText_loc4`='你是来挑战我的吗？', `MaleText_loc5`='你來這邊是要較量的嗎?', `MaleText_loc7`='¿Has venido a luchar?', `FemaleText_loc1`='대련하러 오셨나요?', `FemaleText_loc4`='你是来挑战我的吗？', `FemaleText_loc5`='你來這邊是要較量的嗎?', `FemaleText_loc7`='¿Has venido a luchar?' WHERE `ID`=59930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, 제 첫 대련이군요!', `FemaleText_loc4`='好吧，你逼我出手的！', `FemaleText_loc5`='好吧，我的第一戰!', `FemaleText_loc7`='¡Muy bien, mi primer enfrentamiento!' WHERE `ID`=59931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠씬 두들겨 맞을 준비 하라고, 약골!', `MaleText_loc4`='准备受死吧，懦夫！', `MaleText_loc5`='準備好被痛打一頓吧，你這弱雞。', `MaleText_loc7`='¡Prepárate para la paliza de tu vida, alfeñique!' WHERE `ID`=59932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘이야말로 내 적수를 꺾고 말겠어요!', `FemaleText_loc4`='今天我将笑到最后！', `FemaleText_loc5`='今天就是我打敗我對手的日子!', `FemaleText_loc7`='¡Hoy es el día en que derrotaré a mi rival!' WHERE `ID`=59933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 당할 고통에 대해 미리 사과하겠네.', `MaleText_loc4`='我为你即将遭受的挫败先提前道个歉。', `MaleText_loc5`='我為了你即將要承受的痛毆事先道歉。', `MaleText_loc7`='Me disculpo ya por la paliza que estás a punto de recibir.' WHERE `ID`=59934;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야아아아아아아앗!!!', `FemaleText_loc4`='呀……呀！！！', `FemaleText_loc5`='耶耶耶耶耶耶耶耶!!!', `FemaleText_loc7`='¡¡¡AAAAAAAAH!!!' WHERE `ID`=59935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승승장구하던 것도 여기서 끝입니다, $n. 당신은 오늘 내 창에 쓰러질 겁니다.', `MaleText_loc4`='你的连胜将止步于此，$n。今天，你会倒在我的枪下。', `MaleText_loc5`='你的連勝紀錄就到此為止，$n。今天你會倒在我的長槍之下。', `MaleText_loc7`='Tu racha de victorias acaba aquí, $n. Hoy caerás ante mi lanza.' WHERE `ID`=59936;
