UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 포기해! 가망이 없어! 난 절대 못 이길걸!', `FemaleText_loc4`='放弃吧！没希望的！你赢不了我！', `FemaleText_loc5`='放棄吧!沒有希望了!你永遠無法打敗我!', `FemaleText_loc7`='¡Ríndete! ¡No tienes nada que hacer! ¡Nunca podrás ganarme!' WHERE `ID`=59938;
