UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 이름을 걸고 당신을 꺾겠습니다!', `MaleText_loc4`='以赤精之名，我要击垮你！', `MaleText_loc5`='以赤吉之名，我會擊敗你!', `MaleText_loc7`='¡Por el nombre de Chi-Ji, acabaré contigo!' WHERE `ID`=59942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 힘을 다해 덤비게, $n.', `MaleText_loc4`='把你的看家本领都拿出来，$n。', `MaleText_loc5`='使出全力吧，$n。', `MaleText_loc7`='Enséñame todo lo que sabes hacer, $n.' WHERE `ID`=59943;
