UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요, $p. 이제 우린 적수예요. 또 만나게 될 거예요.', `FemaleText_loc4`='好吧，$p……我们棋逢对手。你还没见识我的真正实力。', `FemaleText_loc5`='好吧，$p...我們現在是對手了。你等著瞧吧。', `FemaleText_loc7`='De acuerdo, $p. Ahora somos RIVALES. Volveremos a encontrarnos.' WHERE `ID`=59947;
