UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p에게 연속으로 두 번이나 지다니. 말도 안 돼.', `FemaleText_loc4`='我败给了$p，连着两次了？真不敢相信。', `FemaleText_loc5`='我連續兩次輸給$p?我真不敢相信。', `FemaleText_loc7`='¿He perdido contra $p dos veces seguidas? No me lo puedo creer.' WHERE `ID`=59949;
