UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기, 잘 싸우는걸요. 어쩌면 우리, 또 만날지도요.', `FemaleText_loc4`='干得好，宝贝儿。或许我们会再见面的……', `FemaleText_loc5`='好技巧，甜心。也許我會再次見到你...', `FemaleText_loc7`='Te mueves bien, encanto. Tal vez volvamos a vernos...' WHERE `ID`=59951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물속에 살 때 우리 아버지께서 오늘을 예견하셨습니다. 내가 패배한다고 말씀하셨지만, 나는 믿지 않았지요.', `MaleText_loc4`='我父亲说他已经预见到了这一天。他说我会被击败，但我始终没相信。', `MaleText_loc5`='我的父親在水中預見到這天。他告訴我說我會被打敗，但我拒絕相信他。', `MaleText_loc7`='Mi padre predijo este día en las aguas. Me advirtió de que me derrotarían, pero me negué a creerlo.' WHERE `ID`=59952;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수련생에게 진 건 오랜만이군요. 대련해 주셔서 감사합니다.', `FemaleText_loc4`='我有一阵子没输给过弟子了。谢谢你跟我切磋。', `FemaleText_loc5`='我已經很久沒有敗給一個受訓弟子了。很感謝能與你比試。', `FemaleText_loc7`='Hacía mucho tiempo que no perdía contra un alumno. Gracias por la contienda.' WHERE `ID`=59953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떻게... 이건... 안 돼, 안 돼! 또 이럴 순 없어!', `FemaleText_loc4`='怎么会……我不……不，不，不！我又输了！', `FemaleText_loc5`='我是怎麼...我不...不，不，不不不!不要又來啦!', `FemaleText_loc7`='¿Cómo es que...? Yo no... ¡no, no, no! ¡Otra vez no!' WHERE `ID`=59954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투카툭 연약한 $p에게 져서 슬프다. 투카툭 수평선 보면서 삶에 대해 생각해야겠다.', `MaleText_loc4`='败给没用的$p，图卡图克很伤心。图卡图克要去看日落，并思考一下人生。', `MaleText_loc5`='圖克·吐克很難過輸給懦弱的$p。圖克·吐克要凝視地平線思考生命的意義。', `MaleText_loc7`='Tukka-Tuk está muy triste por perder kontra makaku $p. Tukka-Tuk va a mirar al horizonte y pensar sobre la vida.' WHERE `ID`=59955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우는군. 자네는 마치 곡물을 거두듯 승리를 거두고 있군. 나도 응원하겠네.', `MaleText_loc4`='干得好，你如秋风扫落叶般技压群雄，邻居。我会支持你的。', `MaleText_loc5`='好身手。我的鄰居，你就像砍菜吃西瓜一樣，一直輕易就獲得勝利。我會繼續支持你。', `MaleText_loc7`='Te mueves bien. Sigues recolectando victorias como frutas maduras, camarada. Te estaré animando.' WHERE `ID`=59956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 내가 찾던 상대야! 덕분에 다시 수련해야 할 이유가 생겼군.', `MaleText_loc4`='这才是我所期盼的！你给了我一个很好的理由继续刻苦训练。', `MaleText_loc5`='那正是我要找的!你給了我再次接受訓練的理由。', `MaleText_loc7`='¡Justo lo que estaba buscando! Me has dado un motivo para volver a entrenar.' WHERE `ID`=59957;
