UPDATE `locales_broadcast_text` SET `MaleText_loc1`='패배의 맛... 묘하고도 생소하군요. 겸허할 수 있게 해 주어 감사합니다.', `MaleText_loc4`='失败的滋味……很奇怪，也很陌生。谢谢你让我有了新体验。', `MaleText_loc5`='敗陣的滋味...是這麼的奇怪和陌生。謝謝你讓我保持謙卑。', `MaleText_loc7`='El sabor de la derrota... tan extraño y poco familiar. Gracias por ponerme los pies en el suelo.' WHERE `ID`=59960;
