UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우셨습니다. 그럼 다시 만날 때까지...', `MaleText_loc4`='打得好，下次可就说不准了……', `MaleText_loc5`='很棒的比試。下次再見...', `MaleText_loc7`='Bien luchado. Hasta la próxima...', `FemaleText_loc1`='잘 싸우셨어요. 그럼 다시 만날 때까지...', `FemaleText_loc4`='打得好，下次可就说不准了……', `FemaleText_loc5`='很棒的比試。下次再見...', `FemaleText_loc7`='Bien luchado. Hasta la próxima...' WHERE `ID`=59962;
