UPDATE `locales_broadcast_text` SET `MaleText_loc1`='학의 힘이 있으면, 화염을 뛰어넘을 수 있네!', `MaleText_loc4`='$n，有了朱鹤的力量，你就可以跃过火焰了！', `MaleText_loc5`='$n，有了鶴的力量，你就能跳過火焰!', `MaleText_loc7`='¡Gracias al poder de la grulla, puedes saltar las llamas!' WHERE `ID`=59965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰! 돌아가서 계단 밑에 있는 쓰난과 대화하게. 혼자서 전쟁군주의 분노에 맞서선 안 돼!', `MaleText_loc4`='停下！回去和楼梯下面的思南谈一谈。你不能独自面对督军的怒火！', `MaleText_loc5`='停下來!回去階梯的底部跟司南交談。你不該獨自面對督軍的憤怒。', `MaleText_loc7`='¡Para! Date la vuelta y habla con Sinan, al pie de las escaleras. ¡No te enfrentes al señor de la guerra sin ayuda!' WHERE `ID`=59966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 최대한 빨리 오긴 했다만. 늦지 않았으면 좋겠군.', `MaleText_loc4`='等等！我已经尽快赶来了。但愿还不算太晚。', `MaleText_loc5`='等等。我儘快趕來了，希望還不算太遲。', `MaleText_loc7`='¡Aguarda! He venido en cuanto he podido. Espero que no sea tarde.' WHERE `ID`=59967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별건 아니지만 작은 거라도 빌려주마. 최후의 순간에 도움이 됐으면 좋겠구나.', `MaleText_loc4`='虽然我能做的不多，但我会尽全力帮你。但愿能在最后关头帮上忙。', `MaleText_loc5`='雖然不多，但我會把僅存的微薄之力借你。希望能在這最後時刻幫上忙。', `MaleText_loc7`='No es mucho, pero te ofrezco lo poco que tengo. Espero que sea de ayuda en esta hora oscura.' WHERE `ID`=59968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북이를 떠나 열기구를 타고 스톰윈드로 가는 동영상.', `MaleText_loc4`='Video of leaving the turtle and traveling to Stormwind via hot air balloon.', `MaleText_loc5`='乘坐熱氣球離開神真子前往暴風城的影片。', `MaleText_loc7`='Video of leaving the turtle and traveling to Stormwind via hot air balloon.', `FemaleText_loc1`='거북이를 떠나 열기구를 타고 스톰윈드로 가는 동영상.', `FemaleText_loc4`='Video of leaving the turtle and traveling to Stormwind via hot air balloon.', `FemaleText_loc5`='乘坐熱氣球離開神真子前往暴風城的影片。', `FemaleText_loc7`='Video of leaving the turtle and traveling to Stormwind via hot air balloon.' WHERE `ID`=59973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거북이를 떠나 열기구를 타고 오그리마로 가는 동영상.', `MaleText_loc4`='Video of leaving the turtle and traveling to Orgrimmar via hot air balloon.', `MaleText_loc5`='乘坐熱氣球離開神真子前往奧格瑪的影片。', `MaleText_loc7`='Video of leaving the turtle and traveling to Orgrimmar via hot air balloon.', `FemaleText_loc1`='거북이를 떠나 열기구를 타고 오그리마로 가는 동영상.', `FemaleText_loc4`='Video of leaving the turtle and traveling to Orgrimmar via hot air balloon.', `FemaleText_loc5`='乘坐熱氣球離開神真子前往奧格瑪的影片。', `FemaleText_loc7`='Video of leaving the turtle and traveling to Orgrimmar via hot air balloon.' WHERE `ID`=59974;
