UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과부하가 되기 전에 창을 집어서, 놈에게 도로 던지게!', `MaleText_loc4`='在那些矛过载前捡起它们！把它们掷回去！', `MaleText_loc5`='在他們超載前把長矛撿起來!對準他丟回去!', `MaleText_loc7`='¡Recoge esas lanzas antes de que se sobrecarguen! ¡Lánzaselas!' WHERE `ID`=59979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노에 몸을 맡겨!', `MaleText_loc4`='向你的愤怒屈服吧！', `MaleText_loc5`='向你的憤怒屈服吧!', `MaleText_loc7`='¡Abandónense a la ira!' WHERE `ID`=59980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기는 한때 거대한 모구 제국의 권좌였다네. 모구의 치세는 끔찍하고 잔인하고 피비린내 났지.', `MaleText_loc4`='锦绣谷曾是伟大的魔古帝国的权力中心。魔古族统治的时代非常恐怖、残酷和血腥。', `MaleText_loc5`='山谷曾經一度是偉大魔古帝國的權力核心。魔古統治的時代是可怖、殘忍且血腥的。', `MaleText_loc7`='El valle fue en otros tiempos la sede del poder del gran imperio mogu. La época del reinado mogu fue terrible, cruel y sangrienta.' WHERE `ID`=59981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 있는 동안 마음 편히 쉬게나, $n. 골짜기가 자네에게 평화와 행복을 안겨 주길.', `MaleText_loc4`='请在此处休息，$n。我希望山谷会带给你和平与欢乐。', `MaleText_loc5`='請在這裡好好休息，$n。我希望山谷能帶給你許多平靜與快樂。', `MaleText_loc7`='Por favor, descansa aquí, $n. Espero que el valle te proporcione paz y felicidad.' WHERE `ID`=59982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 땅의 영웅이로군. 마침 잘됐네. 이리 와서 이야기 좀 하세, $c.', `MaleText_loc4`='噢，很好，是这一带的$g大英雄:女英雄;啊。过来，我们聊聊吧，$c。', `MaleText_loc5`='喔太好了，這塊土地的$g英雄:女英雄;。來吧$c，我們好好聊聊。', `MaleText_loc7`='Oh, vaya, $gun héroe:una heroína; de la zona. Acércate, hablemos, $c.' WHERE `ID`=59983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c, 여기서 우릴 도우려면 음영사부 전을 찾아야 한다네.', `MaleText_loc4`='如果你是来帮我们的，那你必须要找到影踪派陈大师，$c。', `MaleText_loc5`='$c，如果你是來這裡幫我們的，那務必請你去找影潘宗師震。', `MaleText_loc7`='Debes encontrar al maestro Shado Zhen si pretendes ayudarnos, $c.' WHERE `ID`=59984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 사부가 세상을 떠나다니 슬픔으로 마음이 무겁다네. 휴몽거스와 싸워서 그분의 명예를 되찾아 주겠는가, $n?', `MaleText_loc4`='陈大师的辞世令我们的心情无比沉重。你要去找胡墨戈斯，重拾大师的荣耀吗，$n？', `MaleText_loc5`='我們的心因震大師的逝去而感到沉痛。$n，你能去挑戰胡孟苟斯以恢復大師的榮譽嗎?', `MaleText_loc7`='Nuestros corazones están llenos de pesar por la muerte del maestro Zhen. ¿Te enfrentarás a Gigantón para limpiar su honor, $n?' WHERE `ID`=59985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 폭탄이 준비됐네, $n. 야운골을 막아 줄 텐가?', `MaleText_loc4`='酒桶炸弹准备好了。$n，你要去阻止野牛人吗？', `MaleText_loc5`='$n，炸藥桶準備好了，你要去阻止揚古了嗎?', `MaleText_loc7`='Los barriles bomba están listos. $n, ¿vas a detener a los yaungol?' WHERE `ID`=59986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이 승리를 거두고 돌아오는군. 잘 지내나, $n?', `MaleText_loc4`='原来是我们的$g大英雄:女英雄;得胜凯旋了。你好吗，$n？', `MaleText_loc5`='$g英雄:女英雄;得勝歸來了。$n，你現在感覺如何?', `MaleText_loc7`='$GEl héroe:La heroína; regresa triunfante. ¿Cómo estás, $n?' WHERE `ID`=59987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 한동안 싸우지 않은 걸 다행으로 생각하십시오, $p.', `MaleText_loc4`='你很幸运，我有阵子没动手了，$p。', `MaleText_loc5`='算你幸運，我已經好一陣子沒活動筋骨了，$p。', `MaleText_loc7`='Tienes suerte de que lleve tiempo sin luchar, $p.' WHERE `ID`=59988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:116982|h[보호의 광기]|h|r에 휩싸입니다!', `MaleText_loc4`='%s进入了|cFFFF0000|Hspell:116982|h[护物心切]|h|r！', `MaleText_loc5`='%s進入|cFFFF0000|Hspell:116982|h[護物心切]|h|r狀態!', `MaleText_loc7`='%s entra en |cFFFF0000|Hspell:116982|h[Frenesí protector]|h|r' WHERE `ID`=59989;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, $c! 이쪽이에요!', `FemaleText_loc4`='嘿，$c，到这儿来！', `FemaleText_loc5`='嘿，$c，到這兒來!', `FemaleText_loc7`='¡Eh, $c, por aquí!' WHERE `ID`=59990;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='창발사기가 아직도 창을 쏘고 있어요. 때려 부수는 거 좋아하죠, $c?', `FemaleText_loc4`='那些掷矛者还在攻击。你难道不想消灭他们吗，$c？', `FemaleText_loc5`='這些擲矛弩車仍在發射。$c，你不覺得我們應該把這些玩意兒毀掉嗎?', `FemaleText_loc7`='Esos tiralanzas siguen disparando. ¿No te encanta destruir cosas, $c?' WHERE `ID`=59991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가서 놈들을 혼내 줘, 호랑아!', `FemaleText_loc4`='去解决他们，猛虎！', `FemaleText_loc5`='去宰了他們，勇士!', `FemaleText_loc7`='¡A por ellos!' WHERE `ID`=59992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기서 봅시다, $n!', `FemaleText_loc4`='一会见，$n！', `FemaleText_loc5`='到那裡見，$n!', `FemaleText_loc7`='¡Nos vemos allí, $n!' WHERE `ID`=59993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다칠 각오는 되었겠지요, $n?', `MaleText_loc4`='希望你准备好大战一场了，$n。', `MaleText_loc5`='希望你準備好被揍了，$n。', `MaleText_loc7`='Prepárate para recibir una paliza, $n.' WHERE `ID`=59994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n! 나와 함께할 건가요?', `FemaleText_loc4`='你好，$n！想加入我吗？', `FemaleText_loc5`='嗨，$n!要跟我一起來嗎?', `FemaleText_loc7`='¡Hola, $n! ¿Tienes un momento?' WHERE `ID`=59995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야운골 놈들, 샤가 무섭다고 생각했겠지! 날 만날 때까지는!', `FemaleText_loc4`='这些野牛人还以为煞魔就是世上最可怕的东西了，直到他们遇见了我！', `FemaleText_loc5`='這些揚古之前還以為煞很可怕，直到他們遇上了我就改觀了!', `FemaleText_loc7`='¡Estos yaungol pensaban que los sha daba miedo hasta que me conocieron!' WHERE `ID`=59996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 바탕 싸우면서 흘리는 땀만큼 기분 좋은 게 없지요!', `FemaleText_loc4`='没什么能比热火朝天地打一场来得更舒服了！', `FemaleText_loc5`='沒什麼比在精采的戰鬥中揮灑汗水更棒了!', `FemaleText_loc7`='¡No hay nada mejor para hacer ejercicio que una buena pelea!' WHERE `ID`=59997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한번은, 적이 제 바지가 내려간 걸 보고 넋을 놓고 있는 동안 머리통을 쳐서 쓰러뜨린 적이 있어요. 엉뚱한 데를 보고 있더라고요.', `FemaleText_loc4`='有一次，我的裤子在战斗中掉下来了，我的对手目瞪口呆地看着我，结果被我打碎了脑壳。他的眼睛看错了地方。', `FemaleText_loc5`='有一次我運用戰略打敗了一個對手。因為我打到一半褲子掉下來讓那傢伙看得目瞪口呆，他的目光集中他不該看的地方。', `FemaleText_loc7`='En una ocasión le abrí la cabeza a un enemigo que se quedó estupefacto cuando se me cayeron los pantalones en medio de la batalla. No estaba mirando donde debía.' WHERE `ID`=59998;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='통, 통, 통!', `FemaleText_loc4`='再来，再来！', `FemaleText_loc5`='彈啊，彈啊!', `FemaleText_loc7`='¡Saltarín, saltarín!' WHERE `ID`=59999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야운골을 몇 마리나 죽였는지 모르겠네요. $n, 당신은요?', `FemaleText_loc4`='我已经数不清自己究竟杀死多少野牛人了。你杀了多少，$n？', `FemaleText_loc5`='我算不清我到底殺了多少揚古。$n，你殺了幾個?', `FemaleText_loc7`='He perdido la cuenta de los yaungol que he matado. ¿Cuántos llevas tú, $n?' WHERE `ID`=60000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마이키한테는 비밀이지만, 성격이 저래도 전 그를 사랑해요.', `FemaleText_loc4`='别让麦基知道，可就算他脾气很坏，我还是有点儿喜欢他。', `FemaleText_loc5`='別讓麥積知道，雖然他是個壞脾氣的傢伙，但我還是挺愛他。', `FemaleText_loc7`='Que no se entere Maikee, pero en realidad le quiero aunque sea un gruñón.' WHERE `ID`=60001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 당신! 아군인가, 적군인가?', `MaleText_loc4`='说你呢！你究竟是敌是友？', `MaleText_loc5`='那邊那個!你是朋友還是敵人?', `MaleText_loc7`='¡Eh, tú! ¿Eres $gamigo:amiga; o $genemigo:enemiga;?' WHERE `ID`=60002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 너무 잘나셔서 우릴 못 도와주시겠다고?', `MaleText_loc4`='什么？你真有那么好心，特地来帮我们？', `MaleText_loc5`='啥?我們就不值得你高抬貴手幫忙我們嗎?', `MaleText_loc7`='¿Qué pasa? ¿No merecemos que nos ayudes?' WHERE `ID`=60003;
