UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀하신 분이 여기서 뭐하는 거요?', `MaleText_loc4`='你在这儿干什么？鬼混？', `MaleText_loc5`='你到這裡來做什麼?拜訪貧民窟嗎?', `MaleText_loc7`='¿Para qué has vuelto?' WHERE `ID`=60023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리사 리가 뭐라고 한 거요? 사랑이 어쨌다고?!', `MaleText_loc4`='李丽莎在唠叨什么呢？谈情说爱吗？！', `MaleText_loc5`='那個李麗莎嘴裡碎碎念個什麼?愛?!', `MaleText_loc7`='¿De qué está hablando Leesa Li? ¡¿Amor?!' WHERE `ID`=60024;
