UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 이 야운골 놈들을 끝장내야 하오. 나한텐 종일 여기 서 있는 것보다 중요한 일이 있다고!', `MaleText_loc4`='真该有人来解决掉这些野牛人。我忙得很，可不能一天到晚站在这儿！', `MaleText_loc5`='該有人去把那些揚古解決掉。比起在這裡站整天，我有更重要的事得做!', `MaleText_loc7`='Alguien debería acabar con esos yaungol. ¡Yo tengo mejores cosas que hacer que estar aquí todo el día!' WHERE `ID`=60027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 며칠 전에 훨씬 강한 $c|1이;가; 머리 위로 날아가는 걸 봤소.', `MaleText_loc4`='就在几天前，我还看见一个强大得多的$c从头顶飞过。', `MaleText_loc5`='就在幾天前，我看到一個更強大的$c從頭頂飛過去。', `MaleText_loc7`='Justo el otro día vi a $gun:una; $c mucho más $gpoderoso:poderosa; volando por el cielo.' WHERE `ID`=60028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 리사. 네 $g 남자 친구 : 친구; 왔어!', `MaleText_loc4`='嘿，丽莎。你的$g男朋友:女朋友;在这儿呢！', `MaleText_loc5`='嘿，麗莎。你的$g男朋友:女朋友;在這裡!', `MaleText_loc7`='Eh, Leesa. ¡Ha venido tu $gamiguito:amiguita;!' WHERE `ID`=60029;
