UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽 교차로의 궤도가 변경되었습니다!', `MaleText_loc4`='北部十字路变轨了。', `MaleText_loc5`='北方路口的軌道方向已經改變!', `MaleText_loc7`='¡Se ha cambiado el cruce de vías del norte!' WHERE `ID`=60033;
