UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노가 자유롭게 흐른다!', `MaleText_loc4`='我的怒火一泻千里！', `MaleText_loc5`='我的憤怒源源不絕!', `MaleText_loc7`='¡Mi cólera fluye libremente!' WHERE `ID`=60036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노는 너에게 힘을 준다!', `MaleText_loc4`='怒火给了你力量。', `MaleText_loc5`='你的怒火會帶給你力量!', `MaleText_loc7`='La ira les da fuerzas.' WHERE `ID`=60037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 다시 묻어둘 순 없어!', `MaleText_loc4`='你休想再埋葬我！', `MaleText_loc5`='你無法再次埋葬我!', `MaleText_loc7`='¡No volverán a encerrarme!' WHERE `ID`=60038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직도 츠지의 꽁지깃에 매달려 있나? 녀석이 말하는 어리석은 "희망"에?', `FemaleText_loc4`='还拽着赤精的尾巴，对他那愚蠢的所谓“希望”的执念死守不放啊？', `FemaleText_loc5`='還在當赤吉的跟屁蟲，相信他那套白癡的「希望」理論嗎?', `FemaleText_loc7`='¿Te sigues aferrando a las plumas de cola de Chi-Ji y a sus estúpidas ideas de "esperanza"?' WHERE `ID`=60039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네게 절망의 맛을 보여주지... 그런 다음 이 섬과 함께 가라앉을 테다!', `FemaleText_loc4`='我会让你见识下什么叫绝望……我还要让整个岛臣服在我的脚下！', `FemaleText_loc5`='我會讓你知道什麼叫做絕望...我要把這整座島拖下去跟我一起陪葬!', `FemaleText_loc7`='Yo te enseñaré lo que es la desesperación... ¡y arrastraré a toda esta isla conmigo!' WHERE `ID`=60040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 때문에 복이 달아났어! 내가 삼촌 콩조아의 카파 사업을 망쳤다고!', `MaleText_loc4`='我真是个扫把星！我把表叔激情豆的咔啡交易搞砸了！', `MaleText_loc5`='我真是個厄運星!我破懷了鋒豆叔叔的卡法交易!', `MaleText_loc7`='¡Soy un estúpido! ¡He arruinado el comercio de kafa del tío Grano Sabio!' WHERE `ID`=60041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='염소한테 먹이지 말았어야지, 사촌.', `MaleText_loc4`='你不该去喂这些山羊，表哥。', `MaleText_loc5`='你從不該拿來餵羊的，表兄。', `MaleText_loc7`='No deberías haber dado de comer a las cabras, primo.' WHERE `ID`=60042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게으름을 피우니까 이렇게 되는 거야.', `MaleText_loc4`='好吃懒做的人就是这个下场。', `MaleText_loc5`='這就是你偷懶的下場。', `MaleText_loc7`='Esto es lo que pasa cuando haces el vago.' WHERE `ID`=60043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카파는 그루멀이나 판다렌한테는 좋지만, 염소나 설인이나 호젠한테는 나쁘다고. 그 정도는 알아야지!', `MaleText_loc4`='咔啡对土地精和熊猫人有益，但对山羊、雪人和猢狲无益。这你应该知道啊！', `MaleText_loc5`='卡法對咕嚕摩和熊貓人是好東西，但對羊還有雪人還有猴人不是。你早該知道的!', `MaleText_loc7`='El kafa es bueno para grúmel y pandaren, no para cabras, ni yetis, ni hozen. ¡Deberías saberlo!' WHERE `ID`=60044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 잡아요! 많이 흔들릴 테니까요!', `MaleText_loc4`='坚持住！这会是一次颠簸的旅程！', `MaleText_loc5`='撐住!這趟旅程會很顛簸!', `MaleText_loc7`='¡Aguanta! ¡Va a ser un paseo movidito!' WHERE `ID`=60045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 우리의 길이 펼쳐졌습니다. 샹 사부님과 이야기하세요. 다음 일을 알려주실 겁니다.', `FemaleText_loc4`='我们的前路已经显现。快去找尚喜师父，他会告诉你下一步该怎么做。', `FemaleText_loc5`='我們該走的道路很明確了。去跟尚羲大師談話，他會告訴你接著該怎麼做。', `FemaleText_loc7`='El camino se halla ante nosotros. Habla con el maestro Shang Xi. Él te dirá qué hacer.' WHERE `ID`=60046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 사람... 모두... 죽었네...', `MaleText_loc4`='这个……村子……已经死了……', `MaleText_loc5`='村莊...已經...毀滅了...', `MaleText_loc7`='La... aldea... muertos...' WHERE `ID`=60047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 복덩이 냄새다! 이리 가져다줘요.', `MaleText_loc4`='我闻到了我的幸运符！噢，拜托你把它带给我。', `MaleText_loc5`='我聞到我的幸運星!喔拜託把它帶來給我。', `MaleText_loc7`='¡Huelo a mi grisgrís! Oh, por favor, tráemelo.' WHERE `ID`=60049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와 줘요! 녀석들이 내 복덩이를 훔쳐갔어요!', `MaleText_loc4`='帮帮我！他们夺走了我的幸运符！', `MaleText_loc5`='來人啊!他們搶走我的幸運星!', `MaleText_loc7`='¡Ayuda! ¡Me han robado mi grisgrís!' WHERE `ID`=60050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $n. 여기 좋은 일거리가 있다고.', `MaleText_loc4`='你好啊，$n。干得不错啊，酋长。', `MaleText_loc5`='你好，$n。這裡做得好，老大。', `MaleText_loc7`='Eh, $n. Buen trabajo, colega.' WHERE `ID`=60051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 감감무소식이야? 얼른 농장에 가야지. 혹시 키린이 일 시킨 거야? 게으른 여자 같으니!', `MaleText_loc4`='情况怎样？你得去那个农场。琪麟让你做她的活？她可真懒啊！', `MaleText_loc5`='怎麼回事?你得要趕去那個農場。卡玲叫你來做她的工作嗎?她真是有夠懶的!', `MaleText_loc7`='¿Qué pasa? Tienes que ir a esa granja. ¿Te ha mandado Kiryn para que hagas su trabajo? ¡Es una vaga!' WHERE `ID`=60052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 저 농부들을 돕고 있는 거지? 먹을 걸 좀 구해다 줘. 믿는다고.', `MaleText_loc4`='你在帮那些农夫解决问题是吧，大好人？我们指望你能帮我们抓些虫子。', `MaleText_loc5`='你在幫那些農夫對嗎，王牌?我們正指望你找點食物給我們。', `MaleText_loc7`='¿Estás ayudando a esos granjeros, verdad? Contamos contigo para que nos consigas algo de comer.' WHERE `ID`=60053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부들 문제를 해결했다며? 다행이야. 이제 다른 일을 처리해야겠군.', `MaleText_loc4`='听说你已经帮那些农夫全都摆脱了困境，真是太好了，头儿。现在我们要解决一些新问题了。', `MaleText_loc5`='很高興聽到你讓那些農夫都滿意了，老大。現在我們有些新的事情得做。', `MaleText_loc7`='Qué bien que hayas resuelto lo de esos granjeros, colega. Ahora tenemos que ocuparnos de otros asuntos.' WHERE `ID`=60054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴착 장치를 몽땅 폭파해 버려야 돼, $n. 냄새 나는 야운골 놈들이 우리 머리 위에 화약통을 퍼붓게 둬선 안 된다고!', `MaleText_loc4`='你去炸掉钻油机，$n。我们可不想让腐臭的野牛人继续朝我们头顶上投掷成批的火药桶了！', `MaleText_loc5`='你必須炸掉那些油井，$n。我們不想要臭揚古用會爆炸的火桶來轟炸我們!', `MaleText_loc7`='Tienes que volar esas torres petrolíferas, $n. ¡No queremos que los apestosos yaungol lancen barriles ardiendo sobre nuestras cabezas!' WHERE `ID`=60055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내겐 폭발 소리가 꼭 음악 소리 같지. 이리 와, $n. 한 번 안아 보자고!', `MaleText_loc4`='那些爆炸声真是太悦耳了。来这里，$n。抱一下！', `MaleText_loc5`='那些爆炸的聲音對我的耳朵來說就像天籟。來這裡，$n。給我一個擁抱!', `MaleText_loc7`='El sonido de esas explosiones era música para mis oídos. Ven aquí, $n. ¡Dame un abrazo!' WHERE `ID`=60056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 그 친구야!', `MaleText_loc4`='$g他: 她;在这！', `MaleText_loc5`='$g他:她;在那裡!', `MaleText_loc7`='¡Ahí está!' WHERE `ID`=60057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 여기 좀 보라고. $n|1이야;야;!', `MaleText_loc4`='嘿，看这儿。是$n！', `MaleText_loc5`='嘿，大家看。是$n!', `MaleText_loc7`='Eh, mira quién está aquí. ¡Es $n!' WHERE `ID`=60058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 뭐지, $n? 야운골 군대를 혼자서 상대하겠다고? 너라면 충분히 가능한 얘기지!', `MaleText_loc4`='接下来有什么打算，$n？单枪匹马解决整个野牛人大军？你也同样做得到！', `MaleText_loc5`='接下來呢，$n?你要自己一個人單挑整個揚古軍隊嗎?你可以辦到的!', `MaleText_loc7`='¿Qué va a ser lo siguiente, $n? ¿Vas a ocuparte de todo el ejército yaungol tú $gsolo:sola;? ¡Podrías hacerlo!' WHERE `ID`=60059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 $n|1은;는; 아주 오랜 친구라고. 맞지, $n?', `MaleText_loc4`='我和$n是老交情了。对吧，$n？', `MaleText_loc5`='我和$n是老朋友了。不是嗎，$n?', `MaleText_loc7`='$n y yo ya nos conocemos de hace tiempo. ¿Verdad, $n?' WHERE `ID`=60060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. $n|1이;가; 아는 건 죄다 나한테 배운 거야.', `MaleText_loc4`='是的。$g他: 她;知道的所有东西都是我教的。', `MaleText_loc5`='沒錯。我教了$n所有$g他:她;知道的事。', `MaleText_loc7`='Sí. Yo le he enseñado a $n todo lo que sabe.' WHERE `ID`=60061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사이니까 하는 말인데, 쿤라이 녀석들은 좀 멍청해. 우리랑은 다르다고!', `MaleText_loc4`='这话只对你说，$n，这些昆莱人似乎慢了些。不像我们！', `MaleText_loc5`='我們之間的秘密，$n，這些崑萊人有點遲鈍。跟我們不一樣!', `MaleText_loc7`='Entre tú y yo, $n, estos Kun-Lai son un poco lentos. ¡Nada que ver con nosotros!' WHERE `ID`=60062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐! 더 빨리! 후딱후딱 하란 말야! 어, 안녕, $n. 별일 없지?', `MaleText_loc4`='嘿，你！更快些！砍，砍！哦嘿，你好，$n。发生了什么事？', `MaleText_loc5`='嘿，你!快點!快，快!喔嘿，你好，$n。有什麼事嗎?', `MaleText_loc7`='¡Eh, tú! ¡Más rápido! ¡Corta, corta! Vaya, hola, $n. ¿Qué tal?' WHERE `ID`=60063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 경의를 표해. $n|1이;가; 왔거든!', `MaleText_loc4`='注意礼节。$n在屋里呢！', `MaleText_loc5`='放尊重點。$n在此!', `MaleText_loc7`='Muestren respeto. ¡Ha llegado $n!' WHERE `ID`=60064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들을 모두 처치하고 보호막을 없애는 게 얼마나 중요한 일인지, 아무리 강조해도 지나치지가 않다네, $n.', `MaleText_loc4`='至于杀死那些导魔师并击落护盾这件事究竟有多么重要，用语言已经不足以强调了，$n。', `MaleText_loc5`='我必須一再強調殺死那些導魔師還有解除那護盾有多麼重要，$n。', `MaleText_loc7`='No puedo recalcar lo suficiente lo importante que es que mates a esos canalizadores y rompas ese escudo, $n.' WHERE `ID`=60065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 잘했네. 내가 이곳 상황을 파악하는 동안, 키린과 리벳을 만나 보게.', `MaleText_loc4`='啊，干得好，朋友。我得调查一下周围的情况，你去找琪麟和利维特吧。', `MaleText_loc5`='做得好，朋友。在我評估新環境時，去和卡玲還有理弗特談談。', `MaleText_loc7`='Buen trabajo. Habla con Kiryn y Perno mientras yo estudio los nuevos alrededores.' WHERE `ID`=60066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네. 보호막이 사라졌어. 그런데 자네 여기서 뭐하는 겐가?', `MaleText_loc4`='不错。护盾被击落。但你又回来做什么呢？', `MaleText_loc5`='很好。護盾已經解除了，但是你在這裡做什麼?', `MaleText_loc7`='Bien. El escudo ha caído. Pero, ¿qué haces aquí?' WHERE `ID`=60067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 잘 듣게. 자네는 오르도 레이지메사로 돌아가서 놈들의 대장을 처치해야만 하네.', `MaleText_loc4`='$n，仔细听好。你必须回到怒山大帐，干掉他们的酋长。', `MaleText_loc5`='$n，請仔細聽。你必須回去歐朵駐營地殺了他們的酋長。', `MaleText_loc7`='$n, escucha atentamente, por favor. DEBES volver a la Meseta Infame de Ordo y matar a su jefe.' WHERE `ID`=60068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 지금 웃고 있는 건가? 혹시 오르도 전쟁인도자가 죽었다는 말을 할 참인가?', `MaleText_loc4`='你是不是很开心？你是不是要告诉我斡耳朵战争使者已经死了？', `MaleText_loc5`='你臉上帶著的是微笑嗎?你要告訴我歐朵戰爭使者死了嗎?', `MaleText_loc7`='¿Eso que veo es una sonrisa? ¿Acaso estás a punto de decirme que el belisario de Ordo está muerto?' WHERE `ID`=60069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $n.', `MaleText_loc4`='很高兴见到你，$n。', `MaleText_loc5`='很高興見到你，$n。', `MaleText_loc7`='Me alegro de verte, $n.' WHERE `ID`=60070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 봉우리의 다른 지역에서는 무슨 소식 없나?', `MaleText_loc4`='你从昆莱山的其他地方得到了什么消息？', `MaleText_loc5`='你從崑萊峰其他地方帶來什麼消息?', `MaleText_loc7`='¿Qué información traes del resto de la Cima Kun-Lai?' WHERE `ID`=60071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 한 가지 소식만 더 들을 수 있다면 원이 없겠군. 테일러가 죽었다는 소식 말일세.', `MaleText_loc4`='如果说有什么消息能让我好过一点，$n，那就是泰勒的死讯。', `MaleText_loc5`='若有個消息能讓我今天更美好，$n，那就是泰勒已經死了。', `MaleText_loc7`='Si quieres alegrarme el día, $n, dime que Taylor está muerto.' WHERE `ID`=60072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조만간 자네가 우리 무리에 들어오는 것에 대해 이야기를 나누고 싶군, $n.', `MaleText_loc4`='总有一天我们得谈谈让你加入我队伍的事，$n。', `MaleText_loc5`='總有一天我們得談談關於你加入我隊伍的事，$n。', `MaleText_loc7`='Un día de estos vamos a tener una charla para convencerte de que te unas a mi grupo, $n.' WHERE `ID`=60073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 언제까지 있을 건가? 술이라도 한 잔 할까?', `MaleText_loc4`='你会在这儿逗留一阵子？我们该喝一杯。', `MaleText_loc5`='你會在這裡待一陣子嗎?我們該去喝酒。', `MaleText_loc7`='¿Vas a estar por aquí un rato? Deberíamos beber.' WHERE `ID`=60074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 그냥 서풍의 쉼터로 가서 얼라이언스 멍청이들을 싹 쓸어 버릴 수도 있을 텐데 말일세.', `MaleText_loc4`='你知道，你只需去西风之息，杀光那里的联盟蠢货。', `MaleText_loc5`='你知道，你大可到西風之眠去殺光那些聯盟的蠢材。', `MaleText_loc7`='Podrías ir a Reposo Occidental y matar a todos esos idiotas de la Alianza.' WHERE `ID`=60075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파가 남서쪽에서 고생을 좀 했다던데. 그 일에 대해 뭐 아는 거 없나, $n?', `MaleText_loc4`='我听说影踪派在西南边遇到了麻烦。你知道些什么吗，$n？', `MaleText_loc5`='我聽說影潘在西南方有些麻煩。你知道些什麼嗎，$n?', `MaleText_loc7`='He oído que el Shadopan tiene problemas en el suroeste. ¿Sabes algo de eso, $n?' WHERE `ID`=60076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 이렇게 서 있자니 뚱보에 게으름뱅이가 되는 것 같군. 움직이고 싶네!', `MaleText_loc4`='待在这儿，我只会变得又胖又懒。我得找点事情做做！', `MaleText_loc5`='我光站在這裡變得越來越肥，越來越懶。我需要一些戰鬥!', `MaleText_loc7`='Estar aquí hace que engorde y me vuelva un vago. ¡Necesito algo de acción!' WHERE `ID`=60077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남을 수 있을까? 범의 폭탄!', `MaleText_loc4`='你能撑住吗？猛虎之雷！', `MaleText_loc5`='你能活下來嗎?老虎炸彈!', `MaleText_loc7`='¿Podrás sobrevivir? ¡BOMBA DEL TIGRE!' WHERE `ID`=60078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살상기... 범의 폭탄!', `MaleText_loc4`='致命攻击：猛虎之雷！', `MaleText_loc5`='致命的攻擊:老虎炸彈!', `MaleText_loc7`='Ataque mortal: ¡BOMBA DEL TIGRE!' WHERE `ID`=60079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사신 강림... 범의 폭탄!', `MaleText_loc4`='死从天降：猛虎之雷！', `MaleText_loc5`='死亡降臨:老虎炸彈!', `MaleText_loc7`='Muerte desde el cielo: ¡BOMBA DEL TIGRE!' WHERE `ID`=60080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특수기... 범의 폭탄!', `MaleText_loc4`='特殊攻击：猛虎之雷！', `MaleText_loc5`='特殊攻擊:老虎炸彈!', `MaleText_loc7`='Ataque especial: ¡BOMBA DEL TIGRE!' WHERE `ID`=60081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장하구먼. 나라도 더 잘하진 못했을 걸세! 자, 이제 일 얘기를 해 볼까.', `MaleText_loc4`='换我自己做也不过如此了，我的$g小男孩:小姑娘;！我们现在做正事吧。', `MaleText_loc5`='我自己也沒辦法做得更好了，好$g小子:女孩;!現在，讓我們談談公事。', `MaleText_loc7`='¡Ni yo mismo lo habría hecho mejor, $gmuchacho:muchacha;! Ahora pongámonos manos a la obra.' WHERE `ID`=60082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저쪽 농장에 가 보는 게 어때? 식량이 바닥나고 있거든.', `MaleText_loc4`='你已经去过那个农场了吗？我们这里的食物很快就要吃完了，$g小伙子: 小姑娘;。', `MaleText_loc5`='你已經去過那個農莊了?我們這裡的食物就快吃完了，$g小子:女孩;。', `MaleText_loc7`='¿Ya has ido a esa granja? La comida se nos agotará pronto, $gmozo:moza;.' WHERE `ID`=60083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣자 하니 일을 잘하고 있다더군, $g 총각 : 처녀;. 아주 잘하고 있다고. 다른 건 아니고, 되도록 빨리 농장 일을 마무리해 주면 좋겠어. 여기 사람들이 좀 굶주리고 있거든.', `MaleText_loc4`='传闻你很有些本事，$g小伙子: 小姑娘;。有些本事。我只希望你能在农场尽快完成任务。我们这里有一些人已经快饿得不行了。', `MaleText_loc5`='聽說你做得很好，$g小夥子:姑娘;。做得好。我只要求你盡快完成農場那邊的事。我們這裡有一些肚子很餓的人。', `MaleText_loc7`='La verdad es que estás haciendo un buen trabajo, $gchico:chica;. Un buen trabajo. Solo espero que termines en la granja lo antes posible. Por aquí hay mucha gente hambrienta.' WHERE `ID`=60084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 잘했네. 자네 아주 일류로구먼. 머리통 깨기에 자신 있으면 또 맡기고 싶은 일이 있는데 말이지.', `MaleText_loc4`='在那儿干得不错啊。上乘之作。如果你打算对更多的敌人迎头痛击的话，我现在正好有些任务要交给你。', `MaleText_loc5`='你在那做得很好，一流表現。現在我有其他的工作要交代給你，假如你認為還想要做更多的「粗活」?', `MaleText_loc7`='Excelente trabajo. De lujo. Tengo más trabajo para ti si te apetece destrozar más cráneos.' WHERE `ID`=60085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 굴착 장치가 알아서 폭발해 주진 않을 거거든. 뭐... 그럴 수도 있긴 하지만, 자네 손으로 직접 하는 게 더 재밌지 않겠나, $n?', `MaleText_loc4`='你我都知道那些钻油机不会自己炸成碎片。嗯……也许会，但如果你亲自去做的话，会更有乐趣的，$n。', `MaleText_loc5`='你我都知道那些油井不會自己炸成碎片。嗯...它們也許會，但如果是你做的會更加有趣，$n。', `MaleText_loc7`='Tú y yo sabemos que esas torres petrolíferas no van a volar por los aires solas. Bueno, podría pasar, pero sería mucho más divertido si lo hicieses tú, $n.' WHERE `ID`=60086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 싸움꾼! 이리 와서 이 설리를 한 번 안아 주게나! 굴착 장치가 하나씩 터지더구먼. 하나, 둘, 셋 차례대로 말야! 으하하하하하하하!', `MaleText_loc4`='快过来，你这打斗高手，给苏利一个大大的拥抱！钻油机要爆炸了，一、二、三！啊哈哈哈哈哈哈！', `MaleText_loc5`='到這來給蘇利一個大擁抱，你這火爆小子!一，二，三，油井爆開開!啊哈哈哈哈哈哈!', `MaleText_loc7`='¡Ven aquí y dale a Sully un abrazo! ¡Las torres petrolíferas han volado por los aires, una, dos y tres! ¡Ja, ja, ja, ja, ja, ja!' WHERE `ID`=60087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작할까요!', `MaleText_loc4`='我们上！', `MaleText_loc5`='我們上吧!', `MaleText_loc7`='¡Allá vamos!', `FemaleText_loc1`='시작할까요!', `FemaleText_loc4`='我们上！', `FemaleText_loc5`='我們上吧!', `FemaleText_loc7`='¡Allá vamos!' WHERE `ID`=60088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑니다!', `MaleText_loc4`='我来啦！', `MaleText_loc5`='我來啦!', `MaleText_loc7`='¡Allá voy!', `FemaleText_loc1`='가요!', `FemaleText_loc4`='我来啦！', `FemaleText_loc5`='我來啦!', `FemaleText_loc7`='¡Allá voy!' WHERE `ID`=60089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 내가 제일 아끼는 $g 총각 : 처녀;|1이;가; 가는군. 자네 말일세, $n!', `MaleText_loc4`='$g他: 她;在这！哦，你是我最喜爱的$g小伙子: 小姑娘;，就是你，$n！', `MaleText_loc5`='$g他:她;在那!喔，你是我最喜歡的$g小夥子:姑娘;，沒錯，就是你，$n!', `MaleText_loc7`='¡Ahí está! ¡Oh, eres mi $gfavorito:favorita;, $n!' WHERE `ID`=60090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 드십시오, $r! 싸웁시다!', `MaleText_loc4`='拿起你们的武器，$r！冲啊！', `MaleText_loc5`='舉起你的武器，$r!我們開戰吧!', `MaleText_loc7`='¡Levanta tu arma, $r! ¡Vamos a luchar!', `FemaleText_loc1`='무기를 드세요, $r! 싸웁시다!', `FemaleText_loc4`='拿起你们的武器，$r！冲啊！', `FemaleText_loc5`='舉起你的武器，$r!我們開戰吧!', `FemaleText_loc7`='¡Levanta tu arma, $r! ¡Vamos a luchar!' WHERE `ID`=60091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n보다 나은 $c|1은;는; 본 적이 없다네. 다들 마찬가지일걸.', `MaleText_loc4`='我从没有见过比$n还棒的$c，你们也没见过！', `MaleText_loc5`='我從沒看過比$n更好的$c，你們也一樣!', `MaleText_loc7`='¡Nunca he visto a $gun:una; $c mejor que $n, y ustedes tampoco!' WHERE `ID`=60092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조용히 흐느낍니다.', `MaleText_loc4`='%s黯然落泪。', `MaleText_loc5`='%s自己輕聲哭泣。', `MaleText_loc7`='%s llora en silencio.' WHERE `ID`=60093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지 님께 영광을!', `MaleText_loc4`='荣耀归于赤精！', `MaleText_loc5`='為了赤吉的榮耀!', `MaleText_loc7`='¡Gloria a Chi-Ji!', `FemaleText_loc1`='츠지 님께 영광을!', `FemaleText_loc4`='荣耀归于赤精！', `FemaleText_loc5`='為了赤吉的榮耀!', `FemaleText_loc7`='¡Gloria a Chi-Ji!' WHERE `ID`=60094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대련할 준비는 되었겠지요, $c.', `MaleText_loc4`='你这是给自己找打，$c。', `MaleText_loc5`='你為自己得到了一場決鬥，$c。', `MaleText_loc7`='Te reto a un duelo, $c.', `FemaleText_loc1`='대련할 준비는 되었겠지요, $c.', `FemaleText_loc4`='你这是给自己找打，$c。', `FemaleText_loc5`='你為自己得到了一場決鬥，$c。', `FemaleText_loc7`='Te reto a un duelo, $c.' WHERE `ID`=60095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 이게 누군가. 안녕하신가, $n. 얼른 술통 하나 들고 이리로 오게!', `MaleText_loc4`='看看现在谁在这儿。嘿呀，$n，给我们来瓶酒，到这里来！', `MaleText_loc5`='看看誰來了。你好，$n，拿酒過來這裡!', `MaleText_loc7`='Mira quién está aquí. ¡Hola, $n, acércate y tráenos una pinta!' WHERE `ID`=60096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼 보시지요! 한판 붙읍시다!', `MaleText_loc4`='来啊！打个过瘾！', `MaleText_loc5`='來吧!我們來比劃比劃!', `MaleText_loc7`='¡Venga! ¡Vamos a pelear!', `FemaleText_loc1`='덤벼 보시죠! 한판 붙어 봐요!', `FemaleText_loc4`='来啊！打个过瘾！', `FemaleText_loc5`='來吧!我們來比劃比劃!', `FemaleText_loc7`='¡Venga! ¡Vamos a pelear!' WHERE `ID`=60097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십 년이 지나면 다들 작은 고추 설리랑 $n|1이;가; 냄새 나는 야운골 코앞에서 폭약에 불을 붙여서 굴착 장치를 저세상으로 날려 버린 얘길 하고 있을 걸세!', `MaleText_loc4`='我告诉你，十年之内，大家都会不停谈论“腌菜”老苏利和$n就在那些腐臭的野牛人鼻子底下点火，将他们的钻油机炸飞的事迹！', `MaleText_loc5`='我跟你說，十年後大家都會談論醃漬王蘇利和$n炸翻那些臭揚古的油井，而他們還不知不覺的事蹟。', `MaleText_loc7`='Ya verás, en diez años todo el mundo hablará de cuando el viejo Sully Liante y $n prendieron fuego delante de las narices de esos apestosos yaungol y volaron sus torres petrolíferas en mil pedazos.' WHERE `ID`=60098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 함께 보낸 시간을 생각만 해도 눈물이 글썽글썽해지는구먼.', `MaleText_loc4`='一想到我们一起经历过的事情，我就泪眼汪汪，$g小伙子: 小姑娘;。', `MaleText_loc5`='我光是回想我們共同度過的事就淚眼盈眶，$g小夥子:姑娘;。', `MaleText_loc7`='Se me saltan las lágrimas con solo pensar en todo lo que hemos vivido juntos, $gchaval:chavala;.' WHERE `ID`=60099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 판다렌들도 그럭저럭 잘하고 있다네. 자네 같은 사나움이 조금만 있으면 더 바랄 게 없겠지만 말이야.', `MaleText_loc4`='这些昆莱熊猫人一切都好。他们现在要是能多体现出一点点你身上充满的那种斗志就更好了。', `MaleText_loc5`='這些崑萊熊貓人進步得蠻快的，要是他們可以多點跟你一樣的幹勁就好了。', `MaleText_loc7`='A estos pandaren Kun-Lai no se les está dando nada mal. A ver si ahora muestran algo más de ese afán combativo que a ti te sobra.' WHERE `ID`=60100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽의 파이어바우 변두리마을에 문제가 있다던데, 무슨 얘긴지 아나?', `MaleText_loc4`='我听说西边的火树村遇到了麻烦，是怎么回事啊？', `MaleText_loc5`='我聽說西邊的火枝望角有麻煩是怎麼回事?', `MaleText_loc7`='¿Qué es eso de que hay problemas al oeste, en Rincón Tallo Ardiente?' WHERE `ID`=60101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 간호사도 괜찮은 직업이지. 힘든 일이 다 끝난 다음에 부상병이나 치료하는 것도 나쁘지 않지. 미시카한테 속지 말게.', `MaleText_loc4`='哦，的确，当护士也不错，只需在硬仗打完之后安顿好伤员。别让米希卡耍了你。', `MaleText_loc5`='喔，是啊，困難的工作都完成後，當個護士照顧傷者也很好。別讓那個密西卡愚弄你。', `MaleText_loc7`='Oh, claro, no está mal hacer de enfermero y curar a los colegas una vez que el trabajo duro esté terminado. No dejes que Mishka te engañe.' WHERE `ID`=60102;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 잠시 시간 좀 내 주시겠습니까? 도움이 필요한 일이 있습니다.', `FemaleText_loc4`='$n，能占用你一点时间吗？我们有麻烦需要你帮忙解决。', `FemaleText_loc5`='$n，拜託你，可以耽誤你一點時間嗎?我們有點麻煩需要你幫忙。', `FemaleText_loc7`='$n, ¿tienes un momento? Necesitamos que nos ayudes con un problema.' WHERE `ID`=60103;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구지아는 조사해 보셨습니까? 저 작은 땅콩이 다른 일을 시켰다곤 하지 마세요. 지저분한 일은 자기 손으로 할 것이지.', `FemaleText_loc4`='你调查过魔古岬了吗？可别告诉我那个小矮子又让你到其它地方跑腿了。他就不能自己收拾烂摊子吗？', `FemaleText_loc5`='你調查過魔古岬了嗎?拜託不要告訴我那個小梅干菜矮子要你跑去其他地方。他就不能自己處理他的事情嗎?', `FemaleText_loc7`='¿Has podido investigar Mogujia? Por favor, no me digas que ese enano liante te tiene $gocupado:ocupada; en otra parte. ¿Es que no puede hacer ni su propio trabajo sucio?' WHERE `ID`=60104;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구지아에 대해 좋은 소식은 없습니까, $n?', `FemaleText_loc4`='有什么关于魔古岬的好消息吗，$n？', `FemaleText_loc5`='$n，魔古岬那邊有好消息嗎?', `FemaleText_loc7`='¿Traes buenas noticias sobre Mogujia, $n?' WHERE `ID`=60105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFF00AEEF $n|1이;가; 폭포 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFF00AEEF$n突袭了瀑布补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFF00AEEF $n突襲了瀑布哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_frost_summonwaterelemental.blp:20|t|cFF00AEEF ¡$n ha atacado el Almacén de Cascada!|r' WHERE `ID`=60106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n|1이;가; 폭포 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n突袭了瀑布补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n突襲了瀑布哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_frost_summonwaterelemental.blp:20|t|cFFFF0000¡$n ha atacado el Almacén de Cascada!|r' WHERE `ID`=60107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 못난 녀석을 처리하긴 할 겁니까? 그놈이 모구를 되살리고 있는 것 아닌가요?', `FemaleText_loc4`='你真打算解决掉那个巨魔，对吧？就是他让那些魔古族复活的，是不是？', `FemaleText_loc5`='你應該有打算要料理那隻食人妖，對吧?他就是那個讓那些魔古全復活的人，不是嗎?', `FemaleText_loc7`='Vas a ocuparte de ese trol, ¿verdad? Es el que está reanimando a todos esos mogu, ¿no?' WHERE `ID`=60108;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 못난 녀석이 지껄이는 소릴 듣지 않아도 되니 좋군요! 고맙습니다, $n!', `FemaleText_loc4`='终于再也不用听那巨魔喋喋不休了，这真是太好了！谢谢你，$n！', `FemaleText_loc5`='能夠不用繼續聽到那隻食人妖吼啊吼個不停，真是太好了!謝謝你，$n!', `FemaleText_loc7`='¡Es una maravilla no tener que seguir escuchando a ese trol! ¡Gracias, $n!' WHERE `ID`=60109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|r|cFF00AEEF$n|1이;가; 폭포 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|r|cFF00AEEF$n守住了瀑布补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|r|cFF00AEEF$n保衛了瀑布哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_frost_summonwaterelemental.blp:20|t|r|cFF00AEEF¡$n ha defendido el Almacén de Cascada!|r' WHERE `ID`=60110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사로잡힌 판다렌들이 정말 걱정됩니다. 혹시 그들이 지금 어떤 처지에 놓여 있는지 파악하셨습니까, $n?', `FemaleText_loc4`='我很担心那些被抓走的可怜熊猫人。你去查看过他们的情况了吗，$n？', `FemaleText_loc5`='我很擔心那些被捕的可憐熊貓人。$n，你有機會過去看看他們的情況了嗎?', `FemaleText_loc7`='Me preocupan mucho esos pobres pandaren capturados. ¿Has podido comprobar en qué condiciones están, $n?' WHERE `ID`=60111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n|1이;가; 폭포 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n守住了瀑布补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_summonwaterelemental.blp:20|t|cFFFF0000$n保衛了瀑布哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_frost_summonwaterelemental.blp:20|t|cFFFF0000¡$n ha defendido el Almacén de Cascada!|r' WHERE `ID`=60112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $n! 해내셨군요! 판다렌 가족들이 상봉하는 모습을 보니 마음이 따뜻해집니다.', `FemaleText_loc4`='噢，$n，你做到了！看到熊猫人一家团聚，我的心里也热乎乎的。', `FemaleText_loc5`='喔，$n，你辦到了!看到熊貓人全家團圓讓我心中充滿溫暖。', `FemaleText_loc7`='¡Oh, $n, lo has conseguido! Me conmueve ver cómo se reúnen las familias pandaren.' WHERE `ID`=60113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑습니다, $n. 어떻게 지냈나요?', `FemaleText_loc4`='很高兴再次见到你，$n。你最近怎么样？', `FemaleText_loc5`='$n，再見到你真好。你最近過得如何?', `FemaleText_loc7`='Me alegro de volver a verte, $n. ¿Qué tal te ha ido?' WHERE `ID`=60114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n|1이;가; 트롤 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n突袭了巨魔补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n突襲了食人妖哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF¡$n ha atacado el Almacén de Trol!|r' WHERE `ID`=60115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n|1이;가; 트롤 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n守住了巨魔补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF$n保衛了食人妖哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_waepon_bow_zulgrub_d_01.blp:20|t|cFF00AEEF¡$n ha defendido el Almacén de Trol!|r' WHERE `ID`=60116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n|1이;가; 트롤 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n突袭了巨魔补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n突襲了食人妖哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000¡$n ha atacado el Almacén de Trol!|r' WHERE `ID`=60117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n|1이;가; 트롤 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n守住了巨魔补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000$n保衛了食人妖哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_waepon_bow_zulgrub_d_01.blp:20|t|cFFFF0000¡$n ha defendido el Almacén de Trol!|r' WHERE `ID`=60118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c|1으로서의;로서의; 당신의 능력은 의문의 여지가 없습니다.', `FemaleText_loc4`='作为一个$c，你的勇猛毋庸置疑。', `FemaleText_loc5`='做為一個$c，你的實力是無庸置疑的。', `FemaleText_loc7`='Tu destreza como $c es incuestionable.' WHERE `ID`=60119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먼 곳의 소식은 없습니까, $n? 이제 야운골과의 전쟁에서 승리를 거두었나요?', `FemaleText_loc4`='你带来远方的消息了吗，$n？对抗野牛人的战斗打赢了没有？', `FemaleText_loc5`='$n，你有任何從遠方來的消息嗎?與揚古的戰鬥終於勝利了嗎', `FemaleText_loc7`='¿Traes alguna noticia, $n? ¿Por fin hemos ganado la guerra contra los yaungol?' WHERE `ID`=60120;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침 테일러 제독님과 당신 이야기를 하던 참이었습니다. 잘 지내시죠, $n?', `FemaleText_loc4`='泰勒上将和我刚才还谈到你呢。你好吗，$n？', `FemaleText_loc5`='我跟泰勒上將正好聊到你。你好嗎，$n?', `FemaleText_loc7`='El almirante Taylor y yo estábamos hablando de ti. ¿Cómo estás, $n?' WHERE `ID`=60121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 혹시 이따 시간이 나면 차라도 한 잔 하면서 얘기하는 게 어때요?', `FemaleText_loc4`='$n，如果你稍后有时间的话，也许我们能坐下来边喝茶边聊聊天？', `FemaleText_loc5`='$n，如果待會兒有時間，或許你跟我可以坐下來喝杯茶聊聊天?', `FemaleText_loc7`='$n, si luego tienes tiempo, podríamos sentarnos y hablar mientras nos tomamos un té.' WHERE `ID`=60122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n|1이;가; 다이아몬드 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n突袭了钻石补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n突襲了鑽石哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_diamond_04.blp:20|t|cFF00AEEF¡$n ha atacado el Almacén de Diamante!|r' WHERE `ID`=60123;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안색이 유난히 좋군요, $n. 전 지쳤습니다. 치유사의 일은 끝이 없군요.', `FemaleText_loc4`='你看上去好得很，$n。我已经筋疲力尽了。治疗者总有干不完的活儿。', `FemaleText_loc5`='$n，你的氣色真是驚人的好。我累壞了。一個醫者的工作永遠沒有結束的一天。', `FemaleText_loc7`='Tienes muy buen aspecto, $n. Estoy exhausta. El trabajo de los sanadores nunca termina.' WHERE `ID`=60124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n|1이;가; 다이아몬드 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n突袭了钻石补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n突襲了鑽石哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_diamond_04.blp:20|t|cFFFF0000¡$n ha atacado el Almacén de Diamante!|r' WHERE `ID`=60125;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 저 밖에서 일어나는 일인데도, 통 아귀가 안 맞는 이야기들뿐입니다. $n, 정말 그렇게까지 상황이 안 좋습니까?', `FemaleText_loc4`='关于在远方发生的一切，我们听说了各种互相矛盾的说法。告诉我，$n，事情真像传闻说的那样严重吗？', `FemaleText_loc5`='我們聽了許多故事，都是關於外面世界所發生的爭鬥。告訴我，$n，事情真和故事裡說的一樣糟糕嗎?', `FemaleText_loc7`='Nos llegan rumores contradictorios sobre lo que está ocurriendo lejos de aquí. Dime, $n, ¿es tan malo como parece?' WHERE `ID`=60126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n|1이;가; 다이아몬드 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n守住了钻石补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n保衛了鑽石哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_diamond_04.blp:20|t|cFF00AEEF¡$n ha defendido el Almacén de Diamante!|r' WHERE `ID`=60127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 같은 $c|1이;가; 있으니 한결 마음이 놓이는군요.', `FemaleText_loc4`='有像你这样的$c在身边，我觉得安全多了。', `FemaleText_loc5`='有個像你這樣的$c在附近，我覺得安全多了。', `FemaleText_loc7`='Me siento mucho más segura con $gun:una; $c como tú cerca.' WHERE `ID`=60128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n|1이;가; 다이아몬드 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n守住了钻石补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n保衛了鑽石哨塔!|r', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_diamond_04.blp:20|t|cFFFF0000¡$n ha defendido el Almacén de Diamante!|r' WHERE `ID`=60129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n|1이;가; 용암 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n突袭了熔岩补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n突襲了熔岩哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_shaman_lavaflow:20|t|cFF00AEEF¡$n ha atacado el Almacén de Lava!|r' WHERE `ID`=60130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n|1이;가; 용암 보급고를 공격했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n突袭了熔岩补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n突襲了熔岩哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_shaman_lavaflow:20|t|cFFFF0000¡$n ha atacado el Almacén de Lava!|r' WHERE `ID`=60131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n|1이;가; 용암 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n守住了熔岩补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFF00AEEF$n保衛了熔岩哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_shaman_lavaflow:20|t|cFF00AEEF¡$n ha defendido el Almacén de Lava!|r' WHERE `ID`=60132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n|1이;가; 용암 보급고를 방어했습니다!|r', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n守住了熔岩补给站！|r', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_lavaflow:20|t|cFFFF0000$n保衛了熔岩哨塔!|r', `MaleText_loc7`='|TInterfaceIconsspell_shaman_lavaflow:20|t|cFFFF0000¡$n ha defendido el Almacén de Lava!|r' WHERE `ID`=60133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했습니다, 친구. 이제 미시카와 설리를 만나 보십시오.', `MaleText_loc4`='你又出色地完成了一个任务，朋友。去看看米希卡和苏利是否需要你吧。', `MaleText_loc5`='你又漂亮地完成了工作，朋友。去看密西卡跟蘇利需要幫忙嗎?', `MaleText_loc7`='Un trabajo bien hecho, como siempre. ¿Ya has podido echar una mano a Mishka y a Sully?' WHERE `ID`=60134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오르도 레이지메사가 우리 진지의 경계에서 맴돌고 있습니다, $n. 보호막을 빨리 없애지 않으면 지고 말 것입니다.', `MaleText_loc4`='怒山大帐就在我们的边境上，$n。我要你去摧毁那道屏障，否则我们就会一败涂地。', `MaleText_loc5`='$n，歐朵駐營地位於我們的邊境之處。我需要你立刻去把防護盾解除掉，否則我們全都完了。', `MaleText_loc7`='La Meseta Infame de Ordo está justo en nuestra frontera, $n. Necesito que derribes ese escudo ahora o estamos perdidos.' WHERE `ID`=60135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰병들 말로는 당신이 보호막을 없앴다던데, 왜 곧장 대장을 죽이러 가지 않고 여기 와 있는지 모르겠군요.', `MaleText_loc4`='我的斥候告诉我，说你击落了护盾。我很纳闷，为什么你会回到这儿，而不是在那里追杀他们的首领。', `MaleText_loc5`='我的斥候告訴我說你已經將護盾解除。我很疑惑為什麼你會回到這裡而不是去上面殺死他們的領袖。', `MaleText_loc7`='Mis exploradores dicen que has quitado el escudo. No entiendo por qué estás aquí en vez de estar allí matando a su líder.' WHERE `ID`=60136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸물거릴 시간이 없습니다, $n. 정보원의 말로는 야운골이 곧 전면 공격을 해올 거라고 합니다. 우리 모두 당신이 레이지메사를 처치해 주기를 기대하고 있습니다.', `MaleText_loc4`='抓紧时间，$n。我的智慧告诉我，野牛人即将发动一次全面的生死突袭。我们都指望你能杀死酋长怒山。', `MaleText_loc5`='沒有時間浪費了，$n。我的情報告訴我揚古將要發動一波背水一戰的總攻擊。我們都指望你能殺死怒台酋長。', `MaleText_loc7`='No hay tiempo que perder, $n. Mi servicio de inteligencia dice que los yaungol están a punto de lanzar un último asalto total a la desesperada. Contamos todos contigo para que mates al Jefe de la Meseta Infame.' WHERE `ID`=60137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 제가 얼마나 기쁜지 짐작도 못하실 겁니다. 당신이 제 수하의 장교였다면 승진시켰을 겁니다!', `MaleText_loc4`='你不知道我此刻有多高兴。如果你是我麾下的军官，你会得到提拔的！', `MaleText_loc5`='你不知道我現在有多高興。你要是我的部屬，我一定升你的職!', `MaleText_loc7`='No tienes ni idea de lo feliz que estoy ahora mismo. Si fueras uno de mis oficiales te ascendería.' WHERE `ID`=60138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 아닙니까! 요즘은 좀 어떻습니까? 당신의 업적에 대해서는 여기저기서 듣고 있습니다.', `MaleText_loc4`='$n！你好啊！到处都在传颂你的英勇事迹。', `MaleText_loc5`='$n!你好嗎?我到處聽說關於你的英勇事蹟。', `MaleText_loc7`='$n, ¿cómo estás? Me llegan noticias de aquí y de allá sobre tus heroicidades.' WHERE `ID`=60139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의자를 가져다가 앉으십시오, $n. 말동무가 필요합니다.', `MaleText_loc4`='拉把椅子过来，$n。给我作个伴。', `MaleText_loc5`='抓一張椅子，$n。我需要有人陪我。', `MaleText_loc7`='Acerca una silla, $n. Me vendrá bien algo de compañía.' WHERE `ID`=60140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 겨울의 꽃 문에 발생했다는 문제에 대해 아는 게 있습니까? 야운골이 첫 공격보다 더 대규모로 공격해 온 걸까요?', `MaleText_loc4`='$n，我听说冬花关有麻烦，究竟是怎么回事？野牛人会发起比第一次进攻规模更大的第二次进犯吗？', `MaleText_loc5`='$n，我聽說冬綻關有麻煩是怎麼回事?難道還有一波比第一次還大規模的揚古侵略嗎?', `MaleText_loc7`='$n, ¿qué es eso que he oído de que hay problemas en el Paso del Pétalo Glacial? ¿Se trata de una segunda invasión yaungol todavía mayor que la primera?' WHERE `ID`=60141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다 나즈그림만 죽으면 금상첨화일 텐데 말입니다.', `MaleText_loc4`='你知道今天的特大喜讯是什么吗？纳兹戈林死了。', `MaleText_loc5`='你知道為今天錦上添花的好消息是什麼嗎?納茲格寧姆翹辮子了。', `MaleText_loc7`='¿Sabes qué haría de hoy un día redondo? La muerte de Nazgrim.' WHERE `ID`=60142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 동료들을 몇 모아서 동풍의 쉼터를 불태워 버리는 게 어떻습니까, $n?', `MaleText_loc4`='依我说，你应该召集一帮朋友，将东风之眠烧成灰烬，$n。', `MaleText_loc5`='如果你問我，你應該要找一群朋友去把東風之眠燒成平地，$n。', `MaleText_loc7`='Si quieres mi opinión, deberías reunir a un grupo de amigos y reducir a cenizas Reposo Oriental, $n.' WHERE `ID`=60143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 퇴각지나 파이어바우 변두리마을에는 가보셨습니까, $n? 요즘 샤가 기승을 떨치고 있다 합니다.', `MaleText_loc4`='你去过影踪营地或火树村吗，$n？我听说那里发生了与煞有关的麻烦。', `MaleText_loc5`='$n，你去過影潘密地或火枝望角了嗎?我聽說那邊正醞釀煞的麻煩。', `MaleText_loc7`='¿Has estado en el Refugio del Shadopan o en el Rincón Tallo Ardiente, $n? He oído que se avecinan problemas con los sha.' WHERE `ID`=60144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 또 무슨 활약을 했습니까? 제가 충고 하나 하지요. 전장에서 멀어지는 보직이라면, 승진을 받아들이지 마십시오.', `MaleText_loc4`='$n！你在那里还做了些什么？给你一句忠告；如果晋升会让你退到幕后，不要也罢。', `MaleText_loc5`='$n!你在那邊都在忙什麼?給你一個忠告;不要接受會讓你喪命的升遷。', `MaleText_loc7`='¡$n! ¿Qué más has estado haciendo ahí fuera? Déjame darte un consejo: no aceptes un ascenso que te saque fuera de la acción.' WHERE `ID`=60145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 실적이 거의 완벽하군요. 혹시, 해군에 입대할 생각은 없습니까?', `MaleText_loc4`='那么，$n，你拥有近乎完美的战绩。告诉我，你觉得海军怎么样？', `MaleText_loc5`='嗯，$n，你有個幾乎完美的作戰紀錄。告訴我，你對海軍有什麼想法?', `MaleText_loc7`='Bueno, $n, tienes un historial casi perfecto. Dime, ¿qué opinas de la marina?' WHERE `ID`=60146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 요람에 잘 오셨습니다, 친구여.', `MaleText_loc4`='欢迎来到赤精栖木，朋友。', `MaleText_loc5`='歡迎來到赤吉搖籃，朋友。', `MaleText_loc7`='Te doy la bienvenida a la Cuna de Chi-Ji.' WHERE `ID`=60147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 요람에 잘 오셨습니다, 친구여! 다시 만나 반갑군요.', `MaleText_loc4`='欢迎回到赤精栖木，朋友！我很高兴看到你的归来。', `MaleText_loc5`='歡迎回到赤吉搖籃，朋友!我很高興看到你回來。', `MaleText_loc7`='¡Te doy la bienvenida de nuevo a la Cuna de Chi-Ji! Me alegro de que hayas vuelto.' WHERE `ID`=60148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 새 도전자가 돌아왔군요! 잘 오셨습니다, $n.', `MaleText_loc4`='我们新的挑战者回来了！欢迎你，$n。', `MaleText_loc5`='我們的新挑戰者回來了!歡迎，$n。', `MaleText_loc7`='¡Regresa $gel nuevo:la nueva; aspirante! Te doy la bienvenida, $n.' WHERE `ID`=60149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑군요, $n. 간절히 기다리고 있었습니다.', `MaleText_loc4`='欢迎回来，$n。我一直都很期盼你的回归。', `MaleText_loc5`='歡迎回來，$n。我一直熱切地期待你的歸來。', `MaleText_loc7`='Te doy la bienvenida de nuevo, $n. Estaba deseando que regresaras.' WHERE `ID`=60150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광입니다, $n. 츠지의 요람에 잘 오셨습니다.', `MaleText_loc4`='荣幸之至，$n。欢迎回到赤精栖木。', `MaleText_loc5`='這是我們的榮幸，$n。歡迎回到赤吉搖籃。', `MaleText_loc7`='Es un honor, $n. Te doy la bienvenida de nuevo a la Cuna de Chi-Ji.' WHERE `ID`=60151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 용사께 경례를! 저희를 찾아 주시다니 영광입니다, $n|1이여;여;.', `MaleText_loc4`='向你致敬，赤精的勇士！你能来让我们倍感荣幸，$n。', `MaleText_loc5`='為赤吉的高徒歡呼!您的駕到讓我們感到光榮，$n。', `MaleText_loc7`='¡Saludos, $gcampeón:campeona; de Chi-Ji! Nos honras con tu presencia, $n.' WHERE `ID`=60152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 도전자를 상대할 준비가 되었습니까?', `MaleText_loc4`='你准备好面对下一个挑战者了吗？', `MaleText_loc5`='你準備好要面對你的下一個挑戰者了嗎?', `MaleText_loc7`='¿Estás $glisto:lista; para enfrentarte a tu nuevo contendiente?' WHERE `ID`=60153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 더 드릴 시험이 없습니다, $n. 나중에 다시 오십시오.', `MaleText_loc4`='今天已经没什么要考验你的了，$n。有空常回来看看。', `MaleText_loc5`='我今天沒有其他的試煉可以給你，$n。不久之後再來找我們吧。', `MaleText_loc7`='No tengo más pruebas para ti hoy, $n. Vuelve pronto.' WHERE `ID`=60154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 남방의 천신이신 주학 츠지 님의 성스러운 탄생지입니다. 츠지의 추종자와 수행자가 이곳에 모여 몸을 단련하고 마음을 갈고닦으며, 서로 대련하고, 츠지 님 보시기에 더 나은 존재가 되기 위해 노력하지요. 우리와 함께 수련하셔도 좋습니다, $c|1이여;여;. 강한 마음과 강한 봉만 가져 오십시오.', `MaleText_loc4`='这里便是朱鹤的神圣发源地，他叫赤精，是南部的天神。赤精的追随者和侍僧聚集在此处锻炼身体，磨练心神。他们彼此间互相切磋，以期让朱鹤见证他们的成长。$b$b欢迎你加入我们的训练行列，$c。带着你那烈酒般的雄心和烈酒般的功夫。', `MaleText_loc5`='這裡是南方天神，紅鶴赤吉的神聖誕生之地。赤吉的追隨者和侍僧們聚集在此地鍛鍊他們的身體，磨練他們的心智，相互比試以求得紅鶴更多的垂青。$b$b歡迎你加入我們的訓練，$c。希望你帶著不屈的心和一根堅實的拐杖。', `MaleText_loc7`='Este es el sagrado lugar de nacimiento de Chi-Ji, la Grulla Roja, la Celestial del Sur. Los seguidores y acólitos de Chi-Ji se reúnen en este lugar para entrenar sus cuerpos, afinar sus mentes, batirse en duelo entre sí y hacerse mejores a los ojos de la Grulla Roja.$b$bPuedes a unirte a nosotros en nuestro entrenamiento, $c. Solo necesitarás un corazón y un bastón fuertes.' WHERE `ID`=60155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요.', `MaleText_loc4`='我知道了。', `MaleText_loc5`='我明白了。', `MaleText_loc7`='Ya veo.', `FemaleText_loc1`='그렇군요.', `FemaleText_loc4`='我知道了。', `FemaleText_loc5`='我明白了。', `FemaleText_loc7`='Ya veo.' WHERE `ID`=60156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 어떤 곳입니까?', `MaleText_loc4`='这是什么地方？', `MaleText_loc5`='這是什麼地方?', `MaleText_loc7`='¿Qué es este lugar?', `FemaleText_loc1`='이곳은 어떤 곳인가요?', `FemaleText_loc4`='这是什么地方？', `FemaleText_loc5`='這是什麼地方?', `FemaleText_loc7`='¿Qué es este lugar?' WHERE `ID`=60157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 모드로 전환. 안전 장치 해제.', `MaleText_loc4`='进入防御模式。禁用输出保险。', `MaleText_loc5`='啟動防禦模式。關閉輸出保險設定。', `MaleText_loc7`='Activando modo defensivo. Desactivando mecanismos de prevención.' WHERE `ID`=60158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그래! 네 분노를 행동으로 보여줘! 덤벼봐!', `MaleText_loc4`='好……很好！释放你的怒火吧！试着打倒我吧！', `MaleText_loc5`='沒錯...沒錯!釋放你的怒火!試著擊敗我!', `MaleText_loc7`='¡Sí, sí! ¡Dejen que su ira florezca! ¡Intenten abatirme!' WHERE `ID`=60159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 이랬다!', `MaleText_loc4`='是蠢蛋做的！', `MaleText_loc5`='是怪怪人幹的!', `MaleText_loc7`='¡Makakus hacen esto!' WHERE `ID`=60160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 너 때문이다!', `MaleText_loc4`='都是你的错！', `MaleText_loc5`='都是你的錯!', `MaleText_loc7`='¡Todo kulpa tuya!' WHERE `ID`=60161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 주둥이를 때려라!', `MaleText_loc4`='刺他们左边！', `MaleText_loc5`='把他們插在尖尖上!', `MaleText_loc7`='¡Kraku en el ruko!' WHERE `ID`=60162;
