UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강태공 부두에 잘 왔네, $r. 마음껏 둘러보게나. 강태공이라면 이곳에서 배울 게 많다네.', `MaleText_loc4`='欢迎来到渔人码头，$r。请随意逛逛，你在这里可以学到很多钓鱼知识。', `MaleText_loc5`='歡迎來到釣手泊船處，$r。請隨意到處看看，一名釣手可以在這裡學到很多東西。', `MaleText_loc7`='Bienvenido al Muelle de los Pescadores, $r. Si echas un vistazo alrededor podrás aprender mucho sobre pesca.', `FemaleText_loc1`='강태공 부두에 잘 왔네, $r. 마음껏 둘러보게나. 강태공이라면 이곳에서 배울 게 많다네.', `FemaleText_loc4`='欢迎来到渔人码头，$r。请随意逛逛，你在这里可以学到很多钓鱼知识。', `FemaleText_loc5`='歡迎來到釣手泊船處，$r。請隨意到處看看，一名釣手可以在這裡學到很多東西。', `FemaleText_loc7`='Bienvenido al Muelle de los Pescadores, $r. Si echas un vistazo alrededor podrás aprender mucho sobre pesca.' WHERE `ID`=60182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주문의 힘을 빌면 물속에서 빨리 움직일 수 있을 걸세. 상어라도 만날지 누가 알겠나!', `MaleText_loc4`='这个法术可以提高你在水中的移动速度，以防你遇到鲨鱼！', `MaleText_loc5`='這法術會提升你在水中的速度。以防你撞見一尾鯊魚!', `MaleText_loc7`='Con este encantamiento te moverás más rápido en el agua. ¡Por si acaso te encuentras con un tiburón!', `FemaleText_loc1`='이 주문의 힘을 빌면 물속에서 빨리 움직일 수 있을 걸세. 상어라도 만날지 누가 알겠나!', `FemaleText_loc4`='这个法术可以提高你在水中的移动速度，以防你遇到鲨鱼！', `FemaleText_loc5`='這法術會提升你在水中的速度。以防你撞見一尾鯊魚!', `FemaleText_loc7`='Con este encantamiento te moverás más rápido en el agua. ¡Por si acaso te encuentras con un tiburón!' WHERE `ID`=60183;
