UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래. 원래는 여기에 문이 있어야겠지. 그래서 어쩌라고? 한 번 붙어볼텨?', `MaleText_loc4`='当然，没错。这里原本是有一扇门的。你很激动嘛，想打一架吗？', `MaleText_loc5`='好啦，對啦。這裡應該有一道門。真重要。想為它打一架嗎?', `MaleText_loc7`='Sí, claro. Se suponía que había una pueh''ta aquí. ¿Y qué? ¿Quieres luchar por eso?' WHERE `ID`=60187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지, 멈춰요! 무모하고 멍청한 짓이에요.', `FemaleText_loc4`='季，住手！你这样太莽撞了。', `FemaleText_loc5`='紀，住手!這太魯莽，太愚蠢了!', `FemaleText_loc7`='¡Detente, Ji! Esto es imprudente y peligroso.' WHERE `ID`=60188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이사, 이 방법밖에 없어요. 배를 폭파해서 없애 버린 다음에 상처를 치유하면 돼요. 다른 방법이 없어요.', `MaleText_loc4`='艾莎，这是我们唯一的选择。把船炸掉，然后治愈他的伤口。我们没其他办法了。', `MaleText_loc5`='艾莎，我們只能這麼做。炸開這艘船，然後治療他的傷口，我們別無選擇了。', `MaleText_loc7`='Aysa, no hay alternativa: volamos el barco y después le curamos la herida. Es la única solución posible.' WHERE `ID`=60189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 멈추면 다른 방법을 찾을 수 있을 거예요.', `FemaleText_loc4`='你先住手，然后我们再想想其他办法。', `FemaleText_loc5`='如果你不這麼做，或許我們就能想出別的辦法了。', `FemaleText_loc7`='Si esperas, quizá se nos ocurra algo.' WHERE `ID`=60190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 뭔가 생각날 때까지 마냥 기다리자고요? 셴진 수가 죽어가고 있어요! 가만히 있다가는 모든 게 위험해져요!', `MaleText_loc4`='等我们想到好办法神真子已经死了！艾莎，无所作为会给大家的生命带来危险！', `MaleText_loc5`='所以我們在想出辦法前就這樣枯等嗎?神真子命在旦夕!什麼都不做會讓我們失去一切!', `MaleText_loc7`='¿Esperar a que se nos ocurra algo? ¡Shen-zin Su se está muriendo! Es demasiado arriesgado.' WHERE `ID`=60191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이러는 게 더 위험해요!', `FemaleText_loc4`='你炸船才是最危险的！', `FemaleText_loc5`='這樣做才會讓我們失去一切!', `FemaleText_loc7`='¡ESTO sí que es arriesgado!' WHERE `ID`=60192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 죽더라도 시도는 해 보고 죽어야겠어요.', `MaleText_loc4`='就算再危险我也去要拼一拼。', `MaleText_loc5`='我寧可在死的時候，知道我們至少有嘗試過了。', `MaleText_loc7`='Prefiero morir sabiendo que al menos lo intentamos.' WHERE `ID`=60193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지... 굳이 그러겠다면 말리지 않겠어요. 모든 걸 잃을 수 있다는 것만 알아 둬요. 부디 당신이 옳기를 바라요.', `FemaleText_loc4`='季……如果你一定要这么做，我不会阻止你。我们赌上了一切，但愿你是对的。', `FemaleText_loc5`='紀...如果你堅持這麼做，我不會阻止你，但是我們有可能會失去一切。希望你是對的。', `FemaleText_loc7`='Ji... Si debes hacerlo, no te lo impediré, pero podríamos perderlo todo. Espero que estés en lo cierto.' WHERE `ID`=60194;
