UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아깝다! 떡밥을 몽땅 먹어 치운 걸 보면 큰 놈이었을 텐데!', `MaleText_loc4`='我知道了！肯定是有一条大家伙把我的鱼饵都吃掉了！', `MaleText_loc5`='我差點釣到!一定是很大一條，把我的餌都吃得精光!', `MaleText_loc7`='¡Lo tenía! ¡Seguro que era enorme, se ha comido todo el cebo!', `FemaleText_loc1`='아깝다! 떡밥을 몽땅 먹어 치운 걸 보면 큰 놈이었을 텐데!', `FemaleText_loc4`='我知道了！肯定是有一条大家伙把我的鱼饵都吃掉了！', `FemaleText_loc5`='我差點釣到!一定是很大一條，把我的餌都吃得精光!', `FemaleText_loc7`='¡Lo tenía! ¡Seguro que era enorme, se ha comido todo el cebo!' WHERE `ID`=60201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 입질만 많고 무는 놈은 없네.', `MaleText_loc4`='我今天遇到的鱼都是试探性的轻咬，真正咬钩的很少。', `MaleText_loc5`='咬餌的是很多，上鉤的卻很少。', `MaleText_loc7`='Muchos tirones, pero no pican.', `FemaleText_loc1`='오늘은 입질만 많고 무는 놈은 없네.', `FemaleText_loc4`='我今天遇到的鱼都是试探性的轻咬，真正咬钩的很少。', `FemaleText_loc5`='咬餌的是很多，上鉤的卻很少。', `FemaleText_loc7`='Muchos tirones, pero no pican.' WHERE `ID`=60202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아무리 지라고 해도 이건 너무 무모해요. 말려야 해요. 같이 가실 건가요?', `FemaleText_loc4`='就算是季，这么做也太鲁莽了。我必须阻止他。你要一起去吗？', `FemaleText_loc5`='就算以紀的標準來看這也太魯莽了。我得阻止他。你要來嗎?', `FemaleText_loc7`='Esto es una imprudencia, incluso para Ji. Tengo que detenerlo. ¿Vienes?' WHERE `ID`=60203;
