UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐네... 일어설 수... 있을 것 같네...', `MaleText_loc4`='好吧……我想……我还站得住……', `MaleText_loc5`='好...我想...我站得起來...', `MaleText_loc7`='De acuerdo... Creo... Que puedo ponerme en pie...' WHERE `ID`=60205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따... 땅이 흔들리는 건가?', `MaleText_loc4`='大……大地在晃动吗？', `MaleText_loc5`='我...地板在搖晃嗎?', `MaleText_loc7`='¿Es... está temblando el suelo?' WHERE `ID`=60206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에 밀어닥친 트롤들은 우리에게는 전혀 관심이 없었네. 그냥 우리 식구들을 밀치고는 가던 길을 갔지.

그런데 그 다음에 용병들이 밀어닥쳤다네. 놈들은 우리를 포로로 잡고, 집을 약탈하고, 저항하면 죽이겠다고 협박했지.', `MaleText_loc4`='最先来的是——巨魔……他们对我们漠不关心——径直走过去，把我们的家人推到一边。

然而，后面来的是——雇佣兵。他们囚禁我们，洗劫我们的宅院，还威胁说我们要敢反抗就杀光我们。', `MaleText_loc5`='第一組人是一群食人妖...他們完全不在意我們，從我們旁邊經過，把我們的家人推到路邊。

但是第二組人是一群傭兵。他們把我們囚禁起來，竊取我們家中的財物，還威脅說如果我們抵抗，就要把我們殺了。', `MaleText_loc7`='El primer grupo que vino, los trols, no se preocupó nada por nosotros; pasó de largo apartando a nuestras familias.

Pero los siguientes, los mercenarios, nos hicieron prisioneros, nos robaron y nos amenazaron con matarnos si nos resistíamos.' WHERE `ID`=60207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항을 했어야 하는지도 모르겠네... 우리가... 아니, 내가 원하는 걸 다 가져가게 해 줬는데도 놈들은 우릴 죽였으니 말일세.', `MaleText_loc4`='也许我们应该反抗——因为，即便我们……我……我任由他们恣意夺取想要的一切，可他们还是对我们下了毒手。', `MaleText_loc5`='或許我們該反抗的。因為即使我們...我...允許他們取走他們想要的東西，他們還是把我們殺了。', `MaleText_loc7`='A lo mejor deberíamos haber resistido porque, a pesar de que nosotros... yo... les permití que cogieran lo que quisieran, nos mataron igualmente.' WHERE `ID`=60209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부는 아니라도 대부분 죽였지. 나는 이 마을의 치유사였다네. 놈들에게 당한 다음에 상처를 치료해서... 간신히 목숨을 부지하고 있다네.', `MaleText_loc4`='他们杀死了我们当中的大部分人。我是村里的治疗者——在被刺穿之后，我运用医术救活了自己……可也只是勉强留下一口气罢了。', `MaleText_loc5`='或者應該說，他們把大部分的人給殺了。我是這個村莊的醫者，他們刺傷了我之後，我設法運用我的醫療技術保住自己的命...但也只剩一口氣了。', `MaleText_loc7`='Mataron a la mayoría, en realidad. Yo era el sanador de la aldea y después de que me atravesaran con una espada, pude aplicar algunas de mis habilidades médicas para mantenerme con vida... pero por los pelos.' WHERE `ID`=60210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이사가 한숨을 쉽니다.', `FemaleText_loc4`='艾莎叹了口气。', `FemaleText_loc5`='艾莎嘆了口氣。', `FemaleText_loc7`='Aysa suspira.' WHERE `ID`=60211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가야 하네... 사촌이 사는 마을에 내 기술이 필요할 걸세. 또... 죽어 간 이들의 장례식을 준비해야 하니까.', `MaleText_loc4`='我们应该回去……我相信，我的医术能帮到我表哥的村庄。而且……我们必须准备葬礼，安葬失去的至亲。', `MaleText_loc5`='我們應該要回去...我很肯定我的醫術在表兄的村莊能夠派上用場。而且...我們必須為死去的人準備葬禮。', `MaleText_loc7`='Deberíamos volver. Estoy seguro de que harán falta mis habilidades en la aldea de mi primo. Y... debemos celebrar un funeral por nuestros muertos.' WHERE `ID`=60212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네. 서둘러 마을로 가세!', `MaleText_loc4`='好吧。我们赶快前往村庄！', `MaleText_loc5`='好了。我們趕緊到村裡去吧!', `MaleText_loc7`='¡De acuerdo, vamos rápido a la aldea!' WHERE `ID`=60213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사촌! 괜찮은가?', `MaleText_loc4`='表哥！你还好吗？', `MaleText_loc5`='兄弟!你還好嗎?', `MaleText_loc7`='¡Primo! ¿Estás bien?' WHERE `ID`=60214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮네. 하지만... 마을이...', `MaleText_loc4`='还好，表弟。可是……村庄。', `MaleText_loc5`='是的，兄弟。但...村莊。', `MaleText_loc7`='Sí, primo. Pero, la aldea...' WHERE `ID`=60215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다... 다 알고 있네. 가세. 이야기할 게 있네.', `MaleText_loc4`='我……明白。来，我们得谈谈。', `MaleText_loc5`='我...我了解。來吧，我們必須談談。', `MaleText_loc7`='Entiendo... Ven, tenemos que hablar.' WHERE `ID`=60216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $r님. 함께 싸우게 되어 영광입니다.', `MaleText_loc4`='谢谢你，$r。能和你并肩作战是我的荣幸。', `MaleText_loc5`='謝謝你，$r。能和你並肩作戰是我的榮幸。', `MaleText_loc7`='Gracias, $r. Sería todo un honor luchar a tu lado.' WHERE `ID`=60217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침 잘 왔소! 야운골 놈들에게 내 주먹을 소개시켜 줄 시간이거든!', `MaleText_loc4`='我已经忍了很久了！该让那些野牛人看看我的拳头了！', `MaleText_loc5`='我在等的就是這個!該讓那些揚古見識見識我的拳頭了!', `MaleText_loc7`='¡Justo lo que estaba esperando! ¡Ya es hora de presentar mis puños a esos yaungol!' WHERE `ID`=60218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 빚을 졌습니다, 이방인이여. 제가 도와드리겠습니다.', `MaleText_loc4`='我欠你一份情，陌生人。请让我帮助你吧。', `MaleText_loc5`='我欠你一個人情，陌生人。請讓我協助你。', `MaleText_loc7`='Te debo una, $gforastero:forastera;. Por favor, permíteme ayudarte.' WHERE `ID`=60219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 줘서 고맙소, $G형제:자매;여. 혼자 싸우게 두진 않겠소.', `MaleText_loc4`='谢谢你救了我，$G兄弟:姐妹;。我也不能让你就这么孤军奋战下去。', `MaleText_loc5`='謝謝你讓我自由，$G兄弟:姊妹;。我不能讓你獨自戰鬥。', `MaleText_loc7`='Gracias por liberarme, $ghermano:hermana;. No puedo dejar que luches $gsolo:sola;.' WHERE `ID`=60220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 잡았나?', `MaleText_loc4`='今天运气如何？', `MaleText_loc5`='今天運氣如何?', `MaleText_loc7`='¿Hay suerte?', `FemaleText_loc1`='좀 잡았어요?', `FemaleText_loc4`='今天运气如何？', `FemaleText_loc5`='今天運氣如何?', `FemaleText_loc7`='¿Hay suerte?' WHERE `ID`=60221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀. 자네는?', `MaleText_loc4`='不怎么样。你呢？', `MaleText_loc5`='不好。你呢?', `MaleText_loc7`='No. ¿Y tú?', `FemaleText_loc1`='전혀요. 당신은요?', `FemaleText_loc4`='不怎么样。你呢？', `FemaleText_loc5`='不好。你呢?', `FemaleText_loc7`='No. ¿Y tú?' WHERE `ID`=60222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입질만 살살 오네. 뭐, 곧 물겠지!', `MaleText_loc4`='只遇到过几次试探性的啮咬。但愿很快就能有上钩的！', `MaleText_loc5`='只被咬去了幾個餌。希望很快就有魚上鉤!', `MaleText_loc7`='Unos pequeños tirones. ¡Espero que piquen pronto!', `FemaleText_loc1`='입질만 살살 와요. 뭐, 곧 물겠죠!', `FemaleText_loc4`='只遇到过几次试探性的啮咬。但愿很快就能有上钩的！', `FemaleText_loc5`='只被咬去了幾個餌。希望很快就有魚上鉤!', `FemaleText_loc7`='Unos pequeños tirones. ¡Espero que piquen pronto!' WHERE `ID`=60224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가 구하러 올 줄 알았습니다! 함께 야운골과 싸우지요.', `MaleText_loc4`='我就知道会有人来救我们的！让我来帮你揍野牛人吧。', `MaleText_loc5`='我就知道有人會來救我們!讓我協助你對抗揚古吧。', `MaleText_loc7`='¡Sabía que alguien vendría a buscarnos! Permíteme ayudarte a luchar contra los yaungol.' WHERE `ID`=60225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 어둠을 불러옵니다.', `MaleText_loc4`='$n引发了黑暗。', `MaleText_loc5`='$n造成了黑暗。', `MaleText_loc7`='$n provocó la Oscuridad.' WHERE `ID`=60226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이걸 꿰뚫어 볼 수 있는지 보자!', `MaleText_loc4`='哈！让我们瞧瞧你能不能看穿这个！', `MaleText_loc5`='哈!讓我們看看你能不能搞清楚!', `MaleText_loc7`='¡Ja! ¡A ver si adivinas esto!' WHERE `ID`=60227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복제된... 환영!', `MaleText_loc4`='镜……像！', `MaleText_loc5`='鏡...像!', `MaleText_loc7`='Reflejo... ¡EXACTO!' WHERE `ID`=60228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $r. 저는 혼자 돌아갈 수 있습니다.', `MaleText_loc4`='谢谢你，$r。我自己能回去。', `MaleText_loc5`='謝謝你，$r。我可以自己想辦法回去。', `MaleText_loc7`='Gracias, $r. No hace falta que nadie me ayude a volver.' WHERE `ID`=60229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빚을 졌군요, 이방인. 고맙습니다.', `MaleText_loc4`='我欠你一份情，陌生人。谢谢你。', `MaleText_loc5`='我欠你一個人情，陌生人。謝謝你。', `MaleText_loc7`='Te debo una, $gforastero:forastera;. Gracias.' WHERE `ID`=60230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 줘서 고맙소, $G형제:자매;여. 당신이 아니었으면 야운골의 고문을 하루도 더 버티지 못했을 거요.', `MaleText_loc4`='谢谢你救了我，我的$G兄弟:姐妹;。我本来以为要死在残忍的野牛人手中了。', `MaleText_loc5`='謝謝你讓我自由，$G兄弟:姊妹;。在殘酷的揚古手下我肯定活不過今天。', `MaleText_loc7`='Gracias por liberarme, $ghermano:hermana;. Creo que no habría sobrevivido un solo día más de crueldad yaungol.' WHERE `ID`=60231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 각오를 하고 있었는데... 당신이 새 기회를 주셨군요.', `MaleText_loc4`='我都已经做好了牺牲的准备。可现在……你又给了我一个机会。', `MaleText_loc5`='我本來已經準備等死了。現在...你給了我另一個機會。', `MaleText_loc7`='Ya me había preparado para la muerte. Ahora... me has dado otra oportunidad.' WHERE `ID`=60232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 서로 싸우는 거 보셨습니까? 생각보다 갈등의 골이 깊은 모양입니다.', `MaleText_loc4`='你看到那些自相残杀的野牛人了吗？看来他们的麻烦比我们想象中还要严重啊。', `MaleText_loc5`='你有看過揚古內鬨嗎?看來他們的麻煩比我們想得還要大。', `MaleText_loc7`='¿Has visto cómo los yaungol luchan entre sí? Parece que sus problemas internos son mayores de lo que pensábamos.' WHERE `ID`=60233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 서로 싸우는 거 봤소? 생각보다 갈등의 골이 깊은 모양이오.', `MaleText_loc4`='你看到那些自相残杀的野牛人了吗？看来他们的麻烦比我们想象中还要严重啊。', `MaleText_loc5`='你有看過揚古內鬨嗎?看來他們的麻煩比我們想得還要大。', `MaleText_loc7`='¿Has visto cómo los yaungol luchan entre sí? Parece que sus problemas internos son mayores de lo que pensábamos.' WHERE `ID`=60234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 쳐다보고 있나, 이방인?', `MaleText_loc4`='你在看什么呢，陌生人？', `MaleText_loc5`='你看什麼看，陌生人?', `MaleText_loc7`='¿Qué miras, $gforastero:forastera;?' WHERE `ID`=60235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 죽진 않겠다. 이렇겐 안 돼!', `MaleText_loc4`='我绝不能就这么死掉。绝不！', `MaleText_loc5`='我才不會像這樣死掉。不會是這種死法!', `MaleText_loc7`='No moriré así. ¡Así no!' WHERE `ID`=60236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮게 하지 말고 꺼져라. 혼자 조용히 고통받겠다.', `MaleText_loc4`='走开，别管我。让我安静地体味痛苦吧。', `MaleText_loc5`='走開，讓我自己靜一靜。讓我獨自安靜受苦。', `MaleText_loc7`='Ve y déjame en paz. Déjame sufrir en paz.' WHERE `ID`=60237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽지 않아도 됐는데...$B$B남쪽의 마을... 우리 고향, 우리 가족! 놈들이 모두 죽였어!$B$B내가 조금만 더 강했더라면 구할 수 있었을 텐데!', `MaleText_loc4`='他们不该死的……$B$B南边的村子……我的家园，我的家人！他们都被杀害了！$B$B如果我能再强壮一点该多好，那我就能救下他们了！', `MaleText_loc5`='他們不該死...$b$b南方的村莊...我的家，我的家人!他們把我的家人全殺了!$B$B如果我更強壯一點，或許就能救他們!', `MaleText_loc7`='Ellos no tenían que morir...$B$BLa aldea al sur... ¡Mi hogar, mi familia! ¡Los han matado a todos!$B$BSi hubiese sido más fuerte... ¡podría haberlos salvado!' WHERE `ID`=60238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이겼어야 했어. 내가 더 강하고 더 현명했는데. 내가 이겼어야 했는데!', `MaleText_loc4`='赢的人应该是我。我更强壮，也更聪明。我本来是可以赢过他的！', `MaleText_loc5`='我應該要贏的。我比較強。也比較聰明。我應該可以打敗他的!', `MaleText_loc7`='Tendría que haber vencido. Yo era más fuerte. Tenía más sabiduría. ¡Le habría ganado!' WHERE `ID`=60239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외지인! 음영파의 동지.$B$B<늙은 야운골이 무서운 기세로 알아듣기 힘든 말을 내뱉습니다.>$B$B내 손에 목이 부러지고 싶으면 다가와 봐라.', `MaleText_loc4`='外乡人！影踪派的朋友。$B$B<老野牛人艰难地吐出别扭的词句。>$B$B如果你想让我扭断你的脖子，就尽管靠过来吧！', `MaleText_loc5`='外來者!影潘的盟友。$B$B<這個老揚古用力地吐出幾個奇怪的單字。>$B$B如果你想被我扭斷脖子的話就靠近一點!', `MaleText_loc7`='¡$GForastero:Forastera;! $GAliado:Aliada; del Shadopan.$B$B<El yaungol viejo dice con amargura esas extrañas palabras.>$B$B¡Acércate si quieres que te rompa el cuello!' WHERE `ID`=60240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<늙은 야운골은 증오가 서린 눈빛으로 당신을 쏘아봅니다.>', `MaleText_loc4`='<老野牛人盯着你，眼中充满了仇恨。>', `MaleText_loc5`='<老揚古眼中充滿恨意地瞪著你。>', `MaleText_loc7`='<El viejo yaungol te mira con sus ojos llenos de odio.>' WHERE `ID`=60241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 내 형제를 죽인 놈! 우리 조상의 성지에 형제의 피를 쏟은 놈!$B$B내가 사슬에 묶여 있지만 않았다면 넌 이미 죽은 목숨이다!$B$B<늙은 야운골은 고함으로 힘이 다했는지 씩씩거리며 쓰러집니다.>', `MaleText_loc4`='是你！是你杀了我的兄弟们！是你将他们的热血抛洒在我祖先的圣地上。$B$B要不是被锁着，我现在就杀了你！$B$B<暴怒过后，老野牛人突然瘫倒下来，沉重地喘息着。>', `MaleText_loc5`='你!你殺了我的兄弟們!你把他們的血濺在我祖先的神聖之地上!$B$B要不是我被鍊著，我現在就會殺了你!$B$B<老揚古大吼完之後就整個人跌坐在地，粗重地喘息著。', `MaleText_loc7`='¡Tú! ¡Tú mataste a mis hermanos! ¡Tú derramaste su sangre en el suelo sagrado de mis antepasados!$B$B¡Te mataría ahora mismo si no fuese por estas cadenas!$B$B<El viejo yaungol se derrumba tras su propio arrebato, respirando con dificultad.>' WHERE `ID`=60242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 소용돌이가 활성화되었습니다!', `MaleText_loc4`='能量涡流活跃了起来！', `MaleText_loc5`='能量漩渦啟動了!', `MaleText_loc7`='¡El vórtice de energía está activado!' WHERE `ID`=60243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 게 진짠지 알겠냐?!', `MaleText_loc4`='你能弄清哪个是真的吗？！', `MaleText_loc5`='你能夠分辨哪個是真的嗎?', `MaleText_loc7`='¡¿Puedes adivinar cuál es real?!' WHERE `ID`=60244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어떻게... 알았지...', `MaleText_loc4`='你是……怎么……知道……的……', `MaleText_loc5`='你怎麼...搞...清楚的...', `MaleText_loc7`='Cómo... lo has... adivinado...' WHERE `ID`=60245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 속았지!', `MaleText_loc4`='哈！你被骗了！', `MaleText_loc5`='哈!騙到你了!', `MaleText_loc7`='¡Ja! ¡Te he engañado!' WHERE `ID`=60246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 소용돌이의 힘이 강해집니다!', `MaleText_loc4`='能量涡流增强了！', `MaleText_loc5`='能量漩渦正在累積能量!', `MaleText_loc7`='¡El vórtice de energía se está encendiendo!' WHERE `ID`=60247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다. 상처 치료에 힘을 보태겠습니다.', `MaleText_loc4`='感谢你的帮助。我会去帮忙治疗伤口的。', `MaleText_loc5`='謝謝你的幫忙。我會去幫助那些傷患。', `MaleText_loc7`='Gracias por tu ayuda. Iré a echar una mano con la herida.', `FemaleText_loc1`='도와주셔서 감사합니다. 상처 치료에 힘을 보태겠습니다.', `FemaleText_loc4`='感谢你的帮助。我会去帮忙治疗伤口的。', `FemaleText_loc5`='謝謝你的幫忙。我會去幫助那些傷患。', `FemaleText_loc7`='Gracias por tu ayuda. Iré a echar una mano con la herida.' WHERE `ID`=60248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요! 요마가 떼를 지어 몰려들어요!', `MaleText_loc4`='救命！树精涌过来啦！', `MaleText_loc5`='救命啊!一大群妖精!', `MaleText_loc7`='¡Ayuda! ¡Enjambre de duendes!' WHERE `ID`=60249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 뭔가 큰일을 준비하고 있네. 그들이 고대 무기를 더 입수하지 못하게 막아야 한다네.', `MaleText_loc4`='魔古族正在策划重大的阴谋。我们得阻止他们，决不能再让他们获得远古武器了。', `MaleText_loc5`='魔古正在籌備某種大計畫。我們必須阻止他們取得更多古代兵器。', `MaleText_loc7`='Los mogu se están preparando para algo grande. Tenemos que impedir que se apoderen de más armas antiguas.' WHERE `ID`=60250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 호기심 어린 눈으로 당신을 바라봅니다.>', `MaleText_loc4`='<米师好奇地看着你。>', `MaleText_loc5`='<米什仔細地打量你。>', `MaleText_loc7`='<Mishi te observa, intrigado.>' WHERE `ID`=60251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈 준비가 됐어.', `MaleText_loc4`='我做好出发的准备了。', `MaleText_loc5`='我準備好要離開了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='갈 준비가 됐어.', `FemaleText_loc4`='我做好出发的准备了。', `FemaleText_loc5`='我準備好要離開了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=60252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 내게 도전하느냐?', `MaleText_loc4`='谁敢来挑战我？', `MaleText_loc5`='誰敢來挑戰我?', `MaleText_loc7`='¿Quién osa desafiarme?' WHERE `ID`=60253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 시장에 잘 왔어요!', `MaleText_loc4`='朋友，欢迎来到土地精集市！', `MaleText_loc5`='朋友，歡迎來到咕嚕摩市集。', `MaleText_loc7`='¡$GBienvenido:Bienvenida; al Bazar Grúmel!' WHERE `ID`=60254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀이라면 대개 복덩이를 몇 개씩 지니고 다니죠.$b$b봐요, 주머니에 면을 넣어뒀죠. 대단한 복덩이예요. 참, 독한 향도 빼놓을 수 없죠. 굉장한 복덩이거든요.$b$b냄새가 없는 복은 믿지 마세요. 그건 다른 사람 몫이거든요.', `MaleText_loc4`='大多数土地精身上都会带些幸运符。$b$b瞧，口袋里的棉绒，大号的幸运符。哦，还有这臭臭的熏香，超大号的幸运符。$b$b永远别相信闻不到臭味的幸运符。不过对某些人来说倒是很幸运。', `MaleText_loc5`='咕嚕摩大多會隨身帶幾個幸運星。$b$b看，口袋裡的線頭，大幸運星。喔，還有好聞的薰香，大大的幸運星。$b$b絕對不要相信聞不到的運氣，有時候那是別人的運氣。', `MaleText_loc7`='La mayoría de los grúmel tienen siempre algunos grisgrís.$b$bMira, una pelusa en el bolsillo. Un grisgrís potente. Oh, e incienso oloroso. Un grisgrís muy importante.$b$bNunca confíes en la suerte que no huele. A veces es suerte para otra persona.' WHERE `ID`=60255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제 토끼발이 이 몸, 행운의 여덟동전보다 더 행운아라고 하는 이들이 있어요.$b$b우스운 얘기죠.$b$b간단하잖아요. 그 녀석은 "형제"고 저는 "행운"인데, 누가 더 행운아겠어요?', `MaleText_loc4`='某些人认为堂弟兔子脚的运气要比我——好运的八铜钱还要好。$b$b真搞笑。$b$b原因很简单：他名字里有“堂弟”，而我的名字里有“好运”。显而易见，我运气比他好多了。', `MaleText_loc5`='有些人說兔腳兄擁有比我好運八錢還多的好運。$b$b我覺得很可笑。$b$b道理很簡單:他的稱號是「兄」，而我的稱號是「好運」。誰更好運很明顯了吧。', `MaleText_loc7`='Algunos dicen que el hermano Pata de Conejo tiene mejor fortuna que yo, Fortuno el Calderillas.$b$bYo me río.$b$bEs muy sencillo, a él le llaman "hermano" y a mi "Fortuno". Está claro que yo tengo más suerte.' WHERE `ID`=60256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 설인한테 불을 놓지 마세요. 발광을 하거든요.', `MaleText_loc4`='千万别惹恼了雪人，他们会发飙的。', `MaleText_loc5`='千萬不要用火燒雪人。他們只會更生氣。', `MaleText_loc7`='Nunca le prendas fuego a un yeti. Se vuelven locos.' WHERE `ID`=60257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 사촌 시라가 청첩장을 보냈는데, 그게 당신 때문이라죠?$b$b아주 고맙군요. 이제 우리 집안에 시집 안 간 애물단지는 나뿐이겠네요.', `FemaleText_loc4`='我听说我表弟塞拉给我发结婚请柬，都是你的功劳。$b$b谢谢你啊，现在我成了我们家还没结婚的黑牦牛。', `FemaleText_loc5`='我聽說是你讓我的表親錫拉送喜帖給我。$b$b多謝了，現在輪到我變成家族中沒結婚的玄牛了。', `FemaleText_loc7`='Parece que eres el motivo por el que mi prima Syra me está mandando invitaciones de boda.$b$bMuchas gracias. Ahora voy a ser la yak negra soltera de la familia.' WHERE `ID`=60258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 도망치지 않겠지, 정 두크?', `MaleText_loc4`='这次不跑了吗，江达克？', `MaleText_loc5`='這次不逃了嗎，姜·杜克?', `MaleText_loc7`='¿Esta vez no huyes, Jung Duk?' WHERE `ID`=60259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨거지들은 어디 있나, 족장 나으리? 그놈들이 이번에는 못 도와줄 거다!', `MaleText_loc4`='你的侍卫们哪儿去了，大酋长？这次他们可帮不了你了！', `MaleText_loc5`='你的嘍囉呢，大酋長?他們這次幫不了你吧!', `MaleText_loc7`='¿Dónde están tus esbirros, gran jefe? ¡Esta vez no podrán ayudarte!' WHERE `ID`=60260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 힘 앞에 속임수는 상대도 안 되지! 이 자는 네놈보다 더 강력하다고!', `MaleText_loc4`='在真正的实力面前，谎言毫无用处！我比你更强大！', `MaleText_loc5`='謊言無法跟真正的力量匹敵!我比你強大多了!', `MaleText_loc7`='¡El engaño no es rival para la auténtica fortaleza! ¡Este  es más poderoso que tú!' WHERE `ID`=60261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우하하하하하하! 쓰레기보다 못한 놈. 꼴 좋게 됐다.', `MaleText_loc4`='啊哈哈哈哈！罪有应得，肮脏的东西。', `MaleText_loc5`='啊哈哈哈哈!臭東西罪有應得。', `MaleText_loc7`='¡Ja, ja, ja! Es más de lo que se merece la escoria como tú.' WHERE `ID`=60262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C... 네가 이 한심한 안개도깨비를 돕고 있는 자구나.', `MaleText_loc4`='$C……肯定是你这家伙一直在帮助这些卑鄙的雾行鬼。', `MaleText_loc5`='$C...想必你就是一直幫助這些可憐迷霧潛伏者的人。', `MaleText_loc7`='$C... Tú debes de ser $gel:la; que ha estado ayudando a esos penosos rondadores de bruma.' WHERE `ID`=60263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그것도 끝이다!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Ya basta!' WHERE `ID`=60264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게는 너희 셋을 모조리 없앨 수 있는 횃불이 있다!', `MaleText_loc4`='我的火炬足以消灭你们三个！', `MaleText_loc5`='我有足夠的火炬可以除掉你們三個!', `MaleText_loc7`='¡Tengo antorchas suficientes para acabar con ustedes tres!' WHERE `ID`=60265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='횃불에 굴하지 않으면 횃불로 죽으리라!', `MaleText_loc4`='如果你拒绝向火炬屈服，那你就会死在火炬之下！', `MaleText_loc5`='如果你拒絕屈服於火炬之下，你就會死於火炬!', `MaleText_loc7`='¡Si no te inclinas ante la antorcha, morirás por ella!' WHERE `ID`=60266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼...', `MaleText_loc4`='不……', `MaleText_loc5`='不...', `MaleText_loc7`='No...' WHERE `ID`=60267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음은 너다, 꼬맹이!', `MaleText_loc4`='你是下一个，小东西！', `MaleText_loc5`='小鬼，你是下一個!', `MaleText_loc7`='¡Ahora te toca a ti, mequetrefe!' WHERE `ID`=60268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무... 강해...', `MaleText_loc4`='太……强大了……', `MaleText_loc5`='太...強大了...', `MaleText_loc7`='Demasiado... fuerte...' WHERE `ID`=60269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개도깨비가 하나 더 있는데... 놈의 악취가 난다.', `MaleText_loc4`='这里还有一个雾行鬼……我能闻到它的臭味。', `MaleText_loc5`='這裡還有另一個迷霧潛伏者...我可以聞到他的臭味。', `MaleText_loc7`='Aquí hay otro rondador de bruma... Su hedor es inconfundible.' WHERE `ID`=60270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그림자에 숨어 있다고 모를 줄 아느냐...', `MaleText_loc4`='不要以为你藏在暗影下我就看不到你……', `MaleText_loc5`='別以為我沒看見你躲在陰影裡...', `MaleText_loc7`='No creas que no puedo verte, escondido entre las sombras...' WHERE `ID`=60271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='횃불의 힘에 저항하다니... 대체 왜 안 죽는 거지?', `MaleText_loc4`='你胆敢抵抗火炬的力量……为什么不去死呢，野兽？', `MaleText_loc5`='你抵抗了火炬的力量...為什麼你不會死呢，野獸?', `MaleText_loc7`='Te resistes al poder de la antorcha... ¿Por qué no mueres, sabandija?' WHERE `ID`=60272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 의지가...', `MaleText_loc4`='因为我的意志……', `MaleText_loc5`='因為我的意志...', `MaleText_loc7`='Porque mi voluntad...' WHERE `ID`=60273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...우리 종족의 의지가...', `MaleText_loc4`='……我族人的意志……', `MaleText_loc5`='...我人民的意志...', `MaleText_loc7`='... la voluntad de los míos...' WHERE `ID`=60274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...네놈의 의지보다 강하기 때문이다.', `MaleText_loc4`='……比你的更强大。', `MaleText_loc5`='...比你的還要強大。', `MaleText_loc7`='... es más fuerte que la tuya.' WHERE `ID`=60275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 안 돼!', `MaleText_loc4`='不……不！', `MaleText_loc5`='不...不!', `MaleText_loc7`='No... ¡NO!' WHERE `ID`=60276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원소여, 나를 보호해라!', `MaleText_loc4`='元素庇护着我！', `MaleText_loc5`='元素保護了我!', `MaleText_loc7`='¡Los elementos me protegen!' WHERE `ID`=60277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서진 세상에 자네의 도움이 필요하다네, 제자여. 여행길에 누구와 동행할지 정했나?', `MaleText_loc4`='一个破碎的世界正需要你的帮助，我的学徒。你决定好要跟谁一起走了吗？', `MaleText_loc5`='一個破碎的世界正等待著你的援助，我的弟子。你決定好由誰陪伴你踏上旅程了嗎?', `MaleText_loc7`='Más allá de estos muros yace un mundo devastado que necesita tu ayuda, mi $gestimado alumno:estimada alumna;. ¿Has decidido a quién quieres acompañar en tu periplo?' WHERE `ID`=60278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결심이 섰습니다.', `MaleText_loc4`='我做好抉择的准备了。', `MaleText_loc5`='我準備好做決定了。', `MaleText_loc7`='Estoy listo para tomar una decisión.', `FemaleText_loc1`='결심이 섰습니다.', `FemaleText_loc4`='我做好抉择的准备了。', `FemaleText_loc5`='我準備好做決定了。', `FemaleText_loc7`='Estoy lista para tomar una decisión.' WHERE `ID`=60279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네베레스트를 통과하는 비밀 산길을 알아요. 시간은 사흘 더 걸리지만, 중간에 굉장히 멋진 폭포를 볼 수 있어요. 아주 운이 좋은 길이지요.', `MaleText_loc4`='我知道一条穿越不息山的秘密小径。行程会增加三天，但沿途上有一条十分澄澈清凉的瀑布。绝对不虚此行。', `MaleText_loc5`='我知道一條穿越奈佛勒斯的秘密小徑。得多上花三天的旅程，但你在路上會看到非常純淨美好的瀑布。這是一條最幸運的路途。', `MaleText_loc7`='Conozco un sendero secreto en Nieverest. Se pierden tres días de viaje, pero hay una catarata muy bonita. Es un camino con más fortuna.' WHERE `ID`=60280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등산을 하기 전에 카파를 마시면 복 받아요. 하고 나서 마시면 복이 달아나고요.', `MaleText_loc4`='在远足之前喝上一杯咖啡会交好运。远足之后喝就是厄运了。', `MaleText_loc5`='啟程之前先喝咖啡，會帶來好運。反之則會招來厄運。', `MaleText_loc7`='Da buena suerte beber café antes de caminar. Beberlo después da mala suerte.' WHERE `ID`=60281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토끼발이랑 여덟동전이 서로 자기가 더 행운아라며 싸우고 있어요. 바보 같은 녀석들. 주머니에 면이 들어 있는 것만큼 운 좋은 일이 또 어딨다고.', `MaleText_loc4`='兔子脚和八铜钱为谁运气更好而争论不休。那些愚蠢的土地精竟然不记得，没什么能比在口袋里找到棉绒更走运了。', `MaleText_loc5`='兔腳跟八錢在爭論誰的運氣比較好。傻蛋咕嚕摩，他們忘記沒有比在口袋裡找到棉絮更幸運的了。', `MaleText_loc7`='Pata de Conejo y Calderillas discuten sobre quién tiene más suerte. Esos grúmel tontos olvidan que no hay nada que dé más suerte que encontrar pelusas en el bolsillo.' WHERE `ID`=60282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨끗한 야크를 몰면 복이 찾아와요. 더러운 야크를 몰면 설인이 쫓아오지요.', `MaleText_loc4`='一只干净的牦牛就是幸运的牦牛。一只脏兮兮的牦牛等同于雪人攻击。', `MaleText_loc5`='一隻乾淨的犛牛是隻幸運的犛牛。骯髒的犛牛代表雪人會來攻擊。', `MaleText_loc7`='Un yak limpio es un yak con suerte. Un yak sucio es un ataque de yeti asegurado.' WHERE `ID`=60283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복은 꼭 여자 그루멀 같아요. 찾기는 힘들지만 고생하는 보람이 있죠.', `MaleText_loc4`='好运就像是土地精美女——世间罕有，但却值得你费尽心机去找寻。', `MaleText_loc5`='幸運就像咕嚕摩姑娘:很難找但值得費時尋找。', `MaleText_loc7`='La suerte es como una dama grúmel: es difícil de encontrar, pero merece la pena buscarla.' WHERE `ID`=60284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='3보다 더 큰 수를 셀 때는, 꼭 5를 넘겨서 세야 해요. 4에서 끝내면 안 돼요. 그러면 악운이 찾아오거든요.', `MaleText_loc4`='当你数到3时，就一定要继续数到5。不要在数到4时停下来。厄运总是会降在那些数到4的人身上。', `MaleText_loc5`='當你數到3的時候，就要繼續數到5。千萬不要停在4。大部分的壞運都會落在那些停在4的人頭上。', `MaleText_loc7`='Al contar más de 3, hay que seguir hasta 5, nunca hay que parar en 4. Los que paran en 4 tienen muy mala fortuna.' WHERE `ID`=60285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 산길에 빠삭하지만, 그중에서도 더 좋은 길을 아는 그루멀이 있지요.', `MaleText_loc4`='土地精熟悉所有山路。但总有一些土地精比其他人更擅长认路。', `MaleText_loc5`='咕嚕摩知道每條穿越山區的路。但有些咕嚕摩比其他人知道更好的路。', `MaleText_loc7`='Los grúmel conocemos todos los caminos de las montañas. Pero algunos grúmel conocen mejores caminos que otros.' WHERE `ID`=60286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 약탈은 엄청난 불운이에요. 여행길이 순탄하지 못할 거예요.', `MaleText_loc4`='多数厄运都是由大规模的猢狲劫掠带来的。使旅途变得艰难。', `MaleText_loc5`='大多數的噩運都跟猴人暴力有關。讓旅程變得很糟糕。', `MaleText_loc7`='Un gran saqueo hozen da muy mala suerte. Conlleva malos viajes.' WHERE `ID`=60287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 야만적인 괴물들 편에 서다니 잘못 생각한 거다, $r.', `MaleText_loc4`='这场战斗你站错了边，$r。你居然与野蛮的野兽为伍！', `MaleText_loc5`='你站錯邊了，$r。你跟野蠻的野獸在同一陣線上!', `MaleText_loc7`='Estás en el lado equivocado de esta batalla, $r. ¡Te has aliado con bestias salvajes!' WHERE `ID`=60288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골... 고스...', `MaleText_loc4`='高尔……戈斯……', `MaleText_loc5`='苟...格斯...', `MaleText_loc7`='Gol... goss...' WHERE `ID`=60289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 오술과 싸워야만 한다. 증오를 막아야만 한다.', `MaleText_loc4`='必须立即向奥苏尔人开战。必须消除仇恨。', `MaleText_loc5`='現在必須與歐索戰鬥，必須停止仇恨。', `MaleText_loc7`='Hay que luchar contra Osul ahora. Hay que detener el odio.' WHERE `ID`=60290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고파 죽겠어... 으음, 너!', `MaleText_loc4`='饿死了……嗯！你！', `MaleText_loc5`='好餓喔...嗯!就是你!', `MaleText_loc7`='¡Qué hambre...! ¡Mmm! ¡TÚ!' WHERE `ID`=60291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117910|h[측방 부대]|h|r를 불러 냅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s施放|cFFFF0000|Hspell:117910|h[侧援指令]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_stalwartprotector.blp:20|t%s施放|cFFFF0000|Hspell:117910|h[側翼包抄命令]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_stalwartprotector.blp:20|t¡%s lanza |cFFFF0000|Hspell:117910|h[Órdenes de flanco]|h|r!' WHERE `ID`=60292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 긴 한숨을 내쉽니다.', `MaleText_loc4`='%s发出了一声深深的长叹。', `MaleText_loc5`='%s呼出一口長長的、長長的嘆息。', `MaleText_loc7`='%s deja escapar un suspiro largo, casi interminable.' WHERE `ID`=60293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 이렇지는 않았다.$b$b오술은 우리 적이 아니었다. 우리는 서로 도우며 살았다.', `MaleText_loc4`='情况并不总是这样。$b$b奥苏尔人以前并不是我们的敌人，他们和我们一起生活。我们相互帮助、互通有无。', `MaleText_loc5`='事情不全是這樣子的。$b$b歐索不是我們的敵人，我們一起生活，互相協助。', `MaleText_loc7`='Esto no siempre ha sido así.$b$bLa gente de Osul no eran nuestros enemigos. Vivían a nuestro lado. Nos ayudábamos unos a otros.' WHERE `ID`=60294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어야만 한다면 동지들과 함께 죽을 것이다.$b$b무슨 수를 써서라도 우리 민족이 이렇게 된 데 복수를 한 다음에 죽을 것이다.$b$b수치감에 빠진 적의 얼굴을 똑바로 바라보며 죽을 것이다.', `MaleText_loc4`='如果我快死了，我也要死在我的朋友身边。$b$b能竭尽全力为我的族人报仇，虽死足矣。$b$b能让敌人感到羞愤，虽死足矣。', `MaleText_loc5`='如果我要死，我也會在我朋友的身邊死去。$b$b但要等我知道自己已盡力為人民復仇，我才會死去。$b$b我會緊盯著敵人羞愧的臉而死去。', `MaleText_loc7`='Si voy a morir, moriré con mis amigos a mi lado.$b$bMoriré sabiendo que hice todo lo que pude por vengar a mi pueblo.$b$bMoriré mirando directamente a la cara avergonzada de mi enemigo.' WHERE `ID`=60295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일이 아주 많네.', `MaleText_loc4`='还有很多事情要做呢。', `MaleText_loc5`='有很多事要做。', `MaleText_loc7`='Queda mucho por hacer.' WHERE `ID`=60296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원군이 도착하는 대로 남쪽에 대한 공세를 펼칠 걸세.', `MaleText_loc4`='一旦援军全部就位，我们就继续向南推进。', `MaleText_loc5`='一旦我們的援軍抵達，我們就會開始向南推進。', `MaleText_loc7`='En cuanto lleguen todos nuestros refuerzos reanudaremos nuestros avances hacia el sur.' WHERE `ID`=60297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낯선 이에게 음영파의 임무를 강요할 생각은 없으나, 숙련된 $c의 도움을 거절할 생각도 없네.$B$B이곳은 위험하다네, $r. 그래도 있겠다면야 기쁘게 도움을 받아들이겠네.', `MaleText_loc4`='我从不让陌生人来承担影踪派的责任，但我也不会拒绝一名熟练$c的帮助。$B$B这个地方很危险，$r。如果你坚持要留下，那我也很乐意接受你的帮助。', `MaleText_loc5`='我絕不會要求一個陌生人去承擔影潘的責任，但我也不會拒絕一個技巧高超的$c來協助我。$B$B這地方很危險，$r。如果你堅持要留下來，那麼我會很高興地接受你的援助。', `MaleText_loc7`='Jamás le pediría a $gun:una; $gforastero:forastera; que realizase las labores de un Shadopan, pero tampoco rechazaré la ayuda de $gun:una; $c competente.$B$BEste lugar es peligroso, $r. Si insistes en quedarte, aceptaré tu ayuda de buen grado.' WHERE `ID`=60298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리 움직여야 해요! 우리 지도자들이 설왕설래하는 동안, 야운골을 열 마리는 죽였겠네요.', `FemaleText_loc4`='我们应该采取行动！领袖们扯皮的这点时间，都够我杀掉十个野牛人的了。', `FemaleText_loc5`='我們應該採取行動!當我們的領導人還在浪費口水時，我可能已經殺了10個揚古。', `FemaleText_loc7`='¡Deberíamos hacer algo! Mientras nuestros líderes no dejan de hablar, yo podría haber acabado ya con diez yaungol.' WHERE `ID`=60299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반이 대단한 전략가인 건 맞지만, 아주 뻔한 해결책을 보지 못하는군요.', `FemaleText_loc4`='班是个伟大的战略家，但他没能看清最明显的解决方法。', `FemaleText_loc5`='班是個戰略家，但他沒有看到最明顯的解決方式。', `FemaleText_loc7`='Ban es un gran estratega, pero no suele ser capaz de ver la solución más evidente.' WHERE `ID`=60300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 움직이는군요! 며칠 전에 했어야 했던 일인 것을.', `FemaleText_loc4`='我们终于可以行动了！几天前就该这么做了。', `FemaleText_loc5`='我們終於採取行動了!早就該這樣做了。', `FemaleText_loc7`='¡Por fin entramos en acción! Es algo que debería haber pasado hace días.' WHERE `ID`=60301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 아래 린이 있는지 보이나요? 포로가 굉장히 많은데, 우리 남편은 보이지가 않네요.', `FemaleText_loc4`='你在那儿见到林了吗？俘虏太多了，可我找不到我丈夫。', `FemaleText_loc5`='你在那裏有見到林嗎?有好多囚犯，但我找不到我的丈夫。', `FemaleText_loc7`='¿Ves a Lin ahí abajo? Hay muchos prisioneros, pero no logro ver a mi marido.' WHERE `ID`=60302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다.', `MaleText_loc4`='欢迎你，$r。', `MaleText_loc5`='歡迎，$r。', `MaleText_loc7`='$GBienvenido:Bienvenida;, $r.' WHERE `ID`=60303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑤나는 남편 걱정 때문에 냉정하게 생각하지 못합니다.', `MaleText_loc4`='对他丈夫的担忧已经冲昏了孙娜的头脑。', `MaleText_loc5`='蘇納滿腦子都在擔心她的丈夫。', `MaleText_loc7`='La mente de Suna está inmersa en la preocupación por su marido.' WHERE `ID`=60304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑤나와 항상 의견이 일치하지는 않지만, 저는 늘 쑤나의 의견을 존중하지요.', `MaleText_loc4`='孙娜和我也会有分歧，但我总是很尊重她的观点。', `MaleText_loc5`='蘇納跟我的意見並不總是相同，但我總是會尊重她的意見。', `MaleText_loc7`='Suna y yo no siempre estamos de acuerdo, pero siempre respeto su opinión.' WHERE `ID`=60305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관이라는 직책은 생각보다 무거운 짐이로군요.', `MaleText_loc4`='指挥官的责任比我想象中更重。', `MaleText_loc5`='身為指揮官的擔子比我想的還要沉重。', `MaleText_loc7`='La túnica de comandante es una carga más pesada de lo que creía.' WHERE `ID`=60306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 쑤나는 늘 그랬습니다. 자존심 강하고 결단력 있고 늘 옳지요.$B$B스무 해 동안 한 번도 말싸움에서 이겨 본 적이 없습니다.$B$B그런데 저는 왜 아직도 이러고 있는 건지...', `MaleText_loc4`='唉……她总是这样。自负，执拗，从不认错。$B$B二十年了，我从来都没有在争执中赢过她。$B$B我怎么就不会吸取教训呢？', `MaleText_loc5`='唉...她總是這樣。驕傲、果斷，而且永遠是對的。$B$B二十年來，她從來沒有同意過我的想法。$B$B為什麼我還沒學到教訓呢?', `MaleText_loc7`='Ay... Ella siempre ha sido así. Orgullosa, contundente, y siempre con la razón de su lado.$B$BEn veinte años no he ganado ni una sola discusión.$B$B¿Cómo puede ser que aún no haya aprendido la lección?' WHERE `ID`=60307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타란 님, 이곳의 기반은 이제 탄탄합니다. 기회가 생기는 대로 공격해야 합니다.', `FemaleText_loc4`='踏岚掌门，我们此处的据点已经稳固了。我们应该第一时间出击。', `FemaleText_loc5`='塔蘭大人，我們這裡的據點很安全。我們應該把握第一時間攻擊。', `FemaleText_loc7`='Lord Taran, nuestra posición es segura. Deberíamos atacar a la primera oportunidad.' WHERE `ID`=60308;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 이미 놈들을 수세에 몰아 넣었어요. 놈들의 수가 시시각각 줄고 있다고요.', `FemaleText_loc4`='我们已将他们逼入防御态势了。眼下，他们的人数也在减少。', `FemaleText_loc5`='我們已經逼得他們採取守勢。就連現在，他們的人數也還在減少。', `FemaleText_loc7`='Ya están a la defensiva. Sus filas se debilitan por momentos.' WHERE `ID`=60309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴 리가! 당신이야말로 내 남편이 그 포로 중 하나라는 걸 잊었군요.', `FemaleText_loc4`='我没有忘！是你忘了，我丈夫也在被俘者当中。', `FemaleText_loc5`='我沒忘!是你忘了我的丈夫也被俘虜了。', `FemaleText_loc7`='¡No! Eres tú quien se olvida de que mi marido es uno de los cautivos.' WHERE `ID`=60310;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 확실한 전략을 세워야죠. 하지만 심장을 노릴 수 있는데 왜 팔을 자르죠?', `FemaleText_loc4`='我们当然需要稳健的战术。但在能直捣黄龙时，为何要断臂自保呢？', `FemaleText_loc5`='當然，我們需要完整的策略。但如果可以直取心臟，何必去砍手腳呢?', `FemaleText_loc7`='Claro que necesitamos una estrategia sólida. ¿Pero por qué cortar un brazo cuando podemos atravesar el corazón?' WHERE `ID`=60311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 반댑니다. 야운골의 힘을 얕봐서는 안 됩니다.', `MaleText_loc4`='我不同意。我们不能低估野牛人的实力。', `MaleText_loc5`='我不同意。我們不能低估揚古的實力。', `MaleText_loc7`='No estoy de acuerdo. No debemos subestimar la fuerza de los yaungol.' WHERE `ID`=60312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 마찬가지야. 부상자가 몇인지 알아? 몇이나 포로로 잡혔는지 잊었어?', `MaleText_loc4`='可我们也一样。难道你忘记我们有多少伤员吗？多少人成了俘虏吗？', `MaleText_loc5`='我們也一樣。你沒看到我們受傷的人數嗎?你忘記有多少人被囚禁了嗎?', `MaleText_loc7`='Las nuestras también. ¿No has visto cuántos heridos tenemos? ¿Y cuántos han hecho prisioneros?' WHERE `ID`=60313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출혈이 얼마나 크겠어? 현명한 방법과 멍청한 방법이 따로 있는 거야.', `MaleText_loc4`='可那要白流多少鲜血？战术也是有明智和愚蠢之分的。', `MaleText_loc5`='但那樣會讓多少人傷亡?方法也有分聰明的和愚蠢的。', `MaleText_loc7`='¿Y el derramamiento de sangre? Existe una vía inteligente y otra temeraria.' WHERE `ID`=60314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘 다 진정하게. 할 일이 아주 많으니까. 그리고 린을 무사히 구출하는 것도 아주 중요한 일이네.', `MaleText_loc4`='你们俩都冷静点。我们要做的事还有很多，但援救林是我们的重中之重。', `MaleText_loc5`='你們兩個都冷靜點。我們有很多事要做，把林活著救出來是首要任務之一。', `MaleText_loc7`='Ya es suficiente. Nos queda mucho por hacer, y sacar a Lin con vida es una de nuestras máximas prioridades.' WHERE `ID`=60315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 뽑아다오. 그 결과로 죽는다 해도 탓하지 않겠다.', `MaleText_loc4`='继续，$n，把它拔出来。要是我真死了，你也不必为此负责。', `MaleText_loc5`='繼續，$n。把它拔出來。當我的死期到來時，你無須為我的死負責。', `MaleText_loc7`='Adelante, $n. Sácalo. No serás responsable de mi muerte cuando esta venga.' WHERE `ID`=60316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 우리 민족에게 수치를 주었다.$b$b곧 수치의 진짜 의미를 깨닫게 될 것이다.', `MaleText_loc4`='野牛人羞辱了我的族人。$b$b他们很快就会知道羞辱的真正含义。', `MaleText_loc5`='揚古羞辱了我的人民。$b$b他們很快就會知道何謂真正的羞辱。', `MaleText_loc7`='Los yaungol han deshonrado a mi pueblo.$b$bPronto conocerán el verdadero significado de la deshonra.' WHERE `ID`=60317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<오르비스의 옆구리에서 창을 뽑습니다.>', `MaleText_loc4`='<拿走奥比斯的矛。>', `MaleText_loc5`='<把歐爾比斯身側的矛拔出來。>', `MaleText_loc7`='<Quita la lanza del costado de Orbiss.>', `FemaleText_loc1`='<오르비스의 옆구리에서 창을 뽑습니다.>', `FemaleText_loc4`='<拿走奥比斯的矛。>', `FemaleText_loc5`='<把歐爾比斯身側的矛拔出來。>', `FemaleText_loc7`='<Quita la lanza del costado de Orbiss.>' WHERE `ID`=60318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즉각 살펴봐야 하는 상황이 남쪽에서 발생했네.', `MaleText_loc4`='现在南边出了点状况，需要我立刻去进行处理。', `MaleText_loc5`='南方有狀況發生，我得立刻前去關切。', `MaleText_loc7`='Hay un asunto en el sur que requiere mi atención urgentemente.' WHERE `ID`=60319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 완수하고 나면 오술 봉우리에 있는 반 베어하트에게 보고하게. 내가 임무를 수행하는 동안 반이 그곳을 지휘하도록 했다네.', `MaleText_loc4`='当你完成任务之后，立即向你们的指挥官班·熊心报告。我已经派他全权负责这里的任务了。', `MaleText_loc5`='當你們完成職責後，去向班·熊心回報。從現在起，我把這個任務的指揮權交給他了。', `MaleText_loc7`='Cuando hayan terminado sus obligaciones, informen a Ban Corazón Fiero. Lo dejo al mando mientras dure mi misión.' WHERE `ID`=60320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 또 보세나.', `MaleText_loc4`='我们很快就会再见面的。', `MaleText_loc5`='我們很快就會再見面。', `MaleText_loc7`='Nos volveremos a ver muy pronto.' WHERE `ID`=60321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자, 친구들. 영광이 우릴 기다린다.', `MaleText_loc4`='来吧，朋友。荣耀在等着我们。', `MaleText_loc5`='來吧，朋友。榮耀等著我們。', `MaleText_loc7`='Vamos, amigos. La gloria nos espera.' WHERE `ID`=60322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골고스를 지켜라!', `MaleText_loc4`='保护高尔戈斯！', `MaleText_loc5`='保護苟格斯!', `MaleText_loc7`='¡Protege a Golgoss!' WHERE `ID`=60323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르코니스를 지켜라!', `MaleText_loc4`='保护阿孔尼斯！', `MaleText_loc5`='保護阿空尼斯!', `MaleText_loc7`='¡Protege a Arconiss!' WHERE `ID`=60324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개가 내 몸을 떠나고 있다. 나는 할 수 있는 한, 최대한 오래 이 세상에 남겠다.', `MaleText_loc4`='迷雾正逐渐从我的身上散去。我会尽我所能留在这个世界，不论天长地久。', `MaleText_loc5`='霧氣正在離開我的身體。我會盡我所能活在這個世界上，直到最後。', `MaleText_loc7`='Las nieblas están abandonando mi cuerpo. Me quedaré en este mundo todo lo que pueda. Todo lo que sea necesario.' WHERE `ID`=60325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해... 냈군...', `MaleText_loc4`='我们……做到了……', `MaleText_loc5`='我們...成功了...', `MaleText_loc7`='Lo... Lo conseguimos...' WHERE `ID`=60326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 쿤라이 성문에 정신이 팔려 있는 지금 공격해야 해요.', `FemaleText_loc4`='班，趁他们的注意力都集中在昆莱山，我们得先发制人。', `FemaleText_loc5`='班，我們應該趁他們關注崑萊各關口時，進行攻擊。', `FemaleText_loc7`='Deberíamos atacar ahora, Ban, mientras están concetrados en las puertas de Kun-Lai.' WHERE `ID`=60327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 내 남편을 포로로 잡고 있는 걸 잊었어요? 시간이 없다고요!', `FemaleText_loc4`='你是不是忘了，他们抓走了我丈夫！我们已经没时间了！', `FemaleText_loc5`='你忘了我丈夫還在他們手中嗎?時間不夠了!', `FemaleText_loc7`='¿Olvidaste que tienen prisionero a mi marido? ¡Se nos acaba el tiempo!' WHERE `ID`=60328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 린이 저기 있어요!', `FemaleText_loc4`='可林在他们手上！', `FemaleText_loc5`='但是林還在那裡!', `FemaleText_loc7`='¡Pero Lin está ahí abajo!' WHERE `ID`=60329;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타란 님은 날 선택하셨어야 해요. 출혈을 각오하지 않고서는 승리할 수 없어요.', `FemaleText_loc4`='他应该选我的。只有敢于冒险的人才会取得辉煌的胜利。', `FemaleText_loc5`='他當初應該選我才對。高風險才能帶來偉大的勝利。', `FemaleText_loc7`='Debería haberme elegido a mí. Aquellos que toman grandes riesgos consiguen grandes victorias.' WHERE `ID`=60330;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 지지 않아요.', `FemaleText_loc4`='我们绝不能输。', `FemaleText_loc5`='我們不會輸。', `FemaleText_loc7`='No perderíamos.' WHERE `ID`=60331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 조심만 하면 다 될 것 같아요? 그렇게 조심했는데, 당신 동생이 어떻게 됐죠?', `FemaleText_loc4`='而你却死抱着你的谨慎不放，好像它能救你似的。谨慎能救出你的兄弟吗？', `FemaleText_loc5`='你不停地提出警告，好像這樣就能救你似的。你的警告有救了你的兄弟嗎?', `FemaleText_loc7`='Y tú te aferras a ella como si eso fuera a salvarte. ¿Salvó acaso la precaución a tu hermano?' WHERE `ID`=60332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 린이 죽어야 한 거죠, 반? 내 사랑을 미처 전하지도 못했는데.', `FemaleText_loc4`='为什么牺牲的偏偏是他，班？我都没能让他知道我的心意。', `FemaleText_loc5`='班，為什麼他必須死?我從沒告訴他我的感受。', `FemaleText_loc7`='¿Por qué tuvo que morir, Ban? Nunca le dije lo que sentía.' WHERE `ID`=60333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님이 병력을 거의 다 이끌고 떠나셨어. 지금 공격하는 건 어리석은 짓이야.', `MaleText_loc4`='祝踏岚掌门刚刚带走了我们的大部分战士。现在进攻是愚蠢的决定。', `MaleText_loc5`='塔蘭·祝大人才剛帶著我們大部分的士兵離開。現在進行攻擊是愚蠢的行為。', `MaleText_loc7`='Lord Taran Zhu acaba de irse con la mayoría de nuestros soldados. Atacar ahora sería una locura.' WHERE `ID`=60334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 참아, 쑤나. 나도 너만큼 야운골을 막고 싶어. 하지만 네 남편뿐 아니라 전군의 안전을 생각해야 돼.', `MaleText_loc4`='耐心点，孙娜。我们都想阻止野牛人。可我必须考虑到每一个战士，而不仅仅是你的丈夫。', `MaleText_loc5`='要有耐心，蘇納。我能了解你想阻止揚古的心情。但我必須考慮到每一個士兵，而不是只有你的丈夫。', `MaleText_loc7`='Paciencia, Suna. Comparto tu deseo de detener a los yaungol, pero debo tener en cuenta a todos los soldados, no solo a tu marido.' WHERE `ID`=60335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리 낮춰. 그래서 타란 님이 널 지휘관으로 임명하지 않으신 거야. 너무 무모하니까.', `MaleText_loc4`='你别这么大声。难怪踏岚不选你来做指挥官。你太冒进了。', `MaleText_loc5`='小聲一點。難怪塔蘭不選妳當指揮官。妳太容易冒險了。', `MaleText_loc7`='Baja la voz. No me extraña que Taran no te dejara al mando. Te arriesgas demasiado.' WHERE `ID`=60336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남편을 구할게, 쑤나. 약속해.', `MaleText_loc4`='孙娜，我们会救出他的。我保证。', `MaleText_loc5`='我們會救他，蘇納。我保證。', `MaleText_loc7`='Le salvaremos, Suna. Lo prometo.' WHERE `ID`=60337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 손실도...', `MaleText_loc4`='也可能是最惨重的失败。', `MaleText_loc5`='以及最大的損失。', `MaleText_loc7`='Y grandes pérdidas.' WHERE `ID`=60338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심성이라곤 눈을 씻고 봐도 없구나.', `MaleText_loc4`='你已经把谨慎抛在脑后了。', `MaleText_loc5`='你對忠告不屑一顧。', `MaleText_loc7`='Lanzas la precaución al viento.' WHERE `ID`=60339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린이 그렇게 된 건 누구의 잘못도 아니야.', `MaleText_loc4`='林的事不是任何人的错。', `MaleText_loc5`='林身上發生的事不是任何人的錯。', `MaleText_loc7`='Lo que le ocurrió a Lin... no fue culpa de nadie.' WHERE `ID`=60340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린은 갔어. 산 사람은 살아야지.', `MaleText_loc4`='他已经牺牲了。我们必须朝前看。', `MaleText_loc5`='他死了。我們必須向前看。', `MaleText_loc7`='Ya no está. Debemos seguir adelante.' WHERE `ID`=60341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 상처를 치료하러 가겠습니다. 이 괴물들이 저를 덮치지 못하게 해주십시오.', `MaleText_loc4`='我要赶到伤口那里去。别让那些野兽靠近我。', `MaleText_loc5`='我要去幫助傷患。試著幫我阻擋這些野獸。', `MaleText_loc7`='Me dirijo a la herida. Intenta alejar a estas bestias de mí.', `FemaleText_loc1`='저는 상처를 치료하러 가겠습니다. 이 괴물들이 저를 덮치지 못하게 해주십시오.', `FemaleText_loc4`='我要赶到伤口那里去。别让那些野兽靠近我。', `FemaleText_loc5`='我要去幫助傷患。試著幫我阻擋這些野獸。', `FemaleText_loc7`='Me dirijo a la herida. Intenta alejar a estas bestias de mí.' WHERE `ID`=60342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 살았습니다. 상처 치료에 온 힘을 다하겠습니다.', `MaleText_loc4`='你真是我的大救星。我会尽力治疗那个伤口的。', `MaleText_loc5`='你真是個救星。我會盡全力治療傷患。', `MaleText_loc7`='Me has salvado la vida. Haré todo lo que pueda para curar la herida.', `FemaleText_loc1`='덕분에 살았습니다. 상처 치료에 온 힘을 다하겠습니다.', `FemaleText_loc4`='你真是我的大救星。我会尽力治疗那个伤口的。', `FemaleText_loc5`='你真是個救星。我會盡全力治療傷患。', `FemaleText_loc7`='Me has salvado la vida. Haré todo lo que pueda para curar la herida.' WHERE `ID`=60343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대로 죽는 줄만 알았습니다. 감사합니다!', `MaleText_loc4`='我还以为自己死定了。谢谢你！', `MaleText_loc5`='我還以為自己完蛋了。謝謝你!', `MaleText_loc7`='Creía que me había llegado la hora. ¡Gracias!', `FemaleText_loc1`='그대로 죽는 줄만 알았습니다. 감사합니다!', `FemaleText_loc4`='我还以为自己死定了。谢谢你！', `FemaleText_loc5`='我還以為自己完蛋了。謝謝你!', `FemaleText_loc7`='Creía que me había llegado la hora. ¡Gracias!' WHERE `ID`=60344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 모두 당신 같다면, 기꺼이 같은 편에 서겠습니다!', `MaleText_loc4`='如果所有的熊猫人都像你这么善良，那我相信你们已经赢得了一些新盟友了！', `MaleText_loc5`='如果所有熊貓人都和你一樣，我想你們已經交上一些新朋友了!', `MaleText_loc7`='Si todos los pandaren son como tú, nos vamos a llevar muy bien.', `FemaleText_loc1`='판다렌이 모두 당신 같다면, 기꺼이 같은 편에 서겠어요!', `FemaleText_loc4`='如果所有的熊猫人都像你这么善良，那我相信你们已经赢得了一些新盟友了！', `FemaleText_loc5`='如果所有熊貓人都和你一樣，我想你們已經交上一些新朋友了!', `FemaleText_loc7`='Si todos los pandaren son como tú, nos vamos a llevar muy bien.' WHERE `ID`=60345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물들을 처리해 주시면, 저희가 상처를 처리하겠습니다.', `MaleText_loc4`='你来解决那些野兽，我们来处理伤口。', `MaleText_loc5`='你負責照料這些野獸，我們會照料傷患。', `MaleText_loc7`='Tú encárgate de las bestias, nosotros nos ocuparemos de la herida.', `FemaleText_loc1`='괴물들을 처리해 주시면, 저희가 상처를 처리할게요.', `FemaleText_loc4`='你来解决那些野兽，我们来处理伤口。', `FemaleText_loc5`='你負責照料這些野獸，我們會照料傷患。', `FemaleText_loc7`='Tú encárgate de las bestias, nosotros nos ocuparemos de la herida.' WHERE `ID`=60346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 치유를 하는 동안 괴물들을 막아 주십시오.', `MaleText_loc4`='在我们进行治疗时，别让那些野兽靠近我们。', `MaleText_loc5`='阻止這些生物，讓我們專心治療。', `MaleText_loc7`='Mantén a raya a esas criaturas mientras sanamos.', `FemaleText_loc1`='저희가 치유를 하는 동안 괴물들을 막아 주세요.', `FemaleText_loc4`='在我们进行治疗时，别让那些野兽靠近我们。', `FemaleText_loc5`='阻止這些生物，讓我們專心治療。', `FemaleText_loc7`='Mantén a raya a esas criaturas mientras sanamos.' WHERE `ID`=60347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제든지 불러만 주십시오.', `MaleText_loc4`='我会永远站在你这边的。', `MaleText_loc5`='我隨時都與你並肩作戰。', `MaleText_loc7`='Puedes contar con mi apoyo.', `FemaleText_loc1`='언제든지 불러만 주세요.', `FemaleText_loc4`='我会永远站在你这边的。', `FemaleText_loc5`='我隨時都與你並肩作戰。', `FemaleText_loc7`='Puedes contar con mi apoyo.' WHERE `ID`=60348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하! 타란 님께서 왜 당신에게 지휘를 맡기신 건지! 야운골이 집을 부술 때까지 이불을 뒤집어쓰고 있으라고요?', `FemaleText_loc4`='嗤！踏岚为什么会选你做指挥官？你只会让我们缩在床单里，等着野牛人打上门来！', `FemaleText_loc5`='呸!為什麼塔蘭會讓你負責?你只會讓我們縮在被窩裡發抖，直到揚古打破我們的大門!', `FemaleText_loc7`='¡Bah! ¿Por qué te ha dejado Taran al mando? Si por ti fuera, nos esconderíamos bajo las sábanas hasta que los yaungol echaran la puerta abajo.' WHERE `ID`=60349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_bloodbath.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117948|h[전멸]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_bloodbath.blp:20|t%s开始施放|cFFFF0000|Hspell:117948|h[歼灭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_bloodbath.blp:20|t%s開始施展|cFFFF0000|Hspell:117948|h[殲滅]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_bloodbath.blp:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:117948|h[Aniquilar]|h|r!' WHERE `ID`=60350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발밑의 땅이 울립니다...', `MaleText_loc4`='你脚下的土地在震颤……', `MaleText_loc5`='地面在你腳下震動...', `MaleText_loc7`='El suelo retumba debajo de ti...' WHERE `ID`=60351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기습입니다! 방어하십시오!', `MaleText_loc4`='中埋伏了！保护好你自己！', `MaleText_loc5`='有埋伏!做好防備!', `MaleText_loc7`='¡Es una emboscada! ¡Defiéndete!' WHERE `ID`=60352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 그래도 언제 오나 했소, $r!', `MaleText_loc4`='你来得正及时，$r！', `MaleText_loc5`='你終於出現了，$r!', `MaleText_loc7`='¡Ya era hora de que vinieras, $r!', `FemaleText_loc1`='안 그래도 언제 오나 했어요, $r!', `FemaleText_loc4`='你来得正及时，$r！', `FemaleText_loc5`='你終於出現了，$r!', `FemaleText_loc7`='¡Ya era hora de que vinieras, $r!' WHERE `ID`=60353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원군이 왔다! 자, 좀 도와주시오!', `MaleText_loc4`='援军到了！来吧，$r，来帮我们一把！', `MaleText_loc5`='援軍抵達了!來吧，$r，幫我們一把!', `MaleText_loc7`='¡Han llegado refuerzos! ¡Ven, $r, échanos una mano!', `FemaleText_loc1`='원군이 왔다! 자, 좀 도와주세요!', `FemaleText_loc4`='援军到了！来吧，$r，来帮我们一把！', `FemaleText_loc5`='援軍抵達了!來吧，$r，幫我們一把!', `FemaleText_loc7`='¡Han llegado refuerzos! ¡Ven, $r, échanos una mano!' WHERE `ID`=60354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘됐군, 전장을 좀 누벼 본 것 같은 $c|1이로군;로군;.', `MaleText_loc4`='噢，真不错，像$G他:她;这样的$c完全清楚自己在战场上的位置。', `MaleText_loc5`='喔太好了，一個看起來知道$G他:她;該在戰場上做什麼的$c。', `MaleText_loc7`='Bien, $gun:una; $c que sabe cómo moverse en un campo de batalla.', `FemaleText_loc1`='잘됐네요, 전장을 좀 누벼 본 것 같은 $c|1이로군요;로군요;.', `FemaleText_loc4`='噢，真不错，像$G他:她;这样的$c完全清楚自己在战场上的位置。', `FemaleText_loc5`='喔太好了，一個看起來知道$G他:她;該在戰場上做什麼的$c。', `FemaleText_loc7`='Bien, $gun:una; $c que sabe cómo moverse en un campo de batalla.' WHERE `ID`=60355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을 합쳐 야운골을 물리칩시다, $r님!', `MaleText_loc4`='快帮我们把野牛人赶回去，$r！', `MaleText_loc5`='幫我們擊退揚古，$r!', `MaleText_loc7`='¡Ayúdanos a repeler a los yaungol, $r!', `FemaleText_loc1`='힘을 합쳐 야운골을 물리쳐요, $r님!', `FemaleText_loc4`='快帮我们把野牛人赶回去，$r！', `FemaleText_loc5`='幫我們擊退揚古，$r!', `FemaleText_loc7`='¡Ayúdanos a repeler a los yaungol, $r!' WHERE `ID`=60356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 처치하십시오, $c. 야운골은 차고 넘치니까요!', `MaleText_loc4`='别不好意思，$c。这里的野牛人完全够我们杀的了！', `MaleText_loc5`='別害羞，$c。有一堆揚古夠大家殺!', `MaleText_loc7`='No seas $gtímido:tímida;, $c. ¡Hay yaungol de sobra!', `FemaleText_loc1`='마음껏 처치하세요, $c. 야운골은 차고 넘치니까요!', `FemaleText_loc4`='别不好意思，$c。这里的野牛人完全够我们杀的了！', `FemaleText_loc5`='別害羞，$c。有一堆揚古夠大家殺!', `FemaleText_loc7`='No seas $gtímido:tímida;, $c. ¡Hay yaungol de sobra!' WHERE `ID`=60357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 걱정스러운 눈길로 계곡을 살펴봅니다.>', `MaleText_loc4`='<米师忧心忡忡地搜索着山谷。>', `MaleText_loc5`='<米什憂慮地環視山谷。>', `MaleText_loc7`='<Mishi observa el valle con precaución.>' WHERE `ID`=60358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너희를 참아 주는 건 모두 새로운 동지 때문이다. 날 자극하지 마라, 인간.', `MaleText_loc4`='我是为了我们的新朋友，才容忍你的存在。不要逼我动手，人类。', `MaleText_loc5`='我是看在新盟友的份上才勉強忍受你。別逼我，人類。', `MaleText_loc7`='Solo tolero tu presencia por respeto a nuestros nuevos aliados. No me provoques, humana.' WHERE `ID`=60359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 콘이 여기서 뭐하는 거지?!$B$B...게다가 왜 귀여운 리본을 매고 있는 거지?', `MaleText_loc4`='寇塔空在这里做什么？！$B$B还有……她为什么戴着一个可爱的小蝴蝶结？', `MaleText_loc5`='柯沓峰的恐懼之王在這裡做什麼?!$B$B...而且為什麼她戴著可愛的小蝴蝶結?', `MaleText_loc7`='¡¿Qué hace Kota Kon aquí?!$B$B¿Y por qué lleva un lacito adorable?' WHERE `ID`=60360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 설인은 좋은 카파의 맛을 웬만한 그루멀보다 잘 아는 것 같아. 게다가 자네가 녀석을 봉우리에서 데려온 후로 그루멀을 한 마리도 안 잡아먹었다고.', `MaleText_loc4`='你知道吗，我认为雪人比大多数人更崇尚好咔啡。而且自从你把她带下山后，她还没吃过一个土地精！', `MaleText_loc5`='你知道嗎，我認為那個雪人比大多數人都更懂得欣賞好的卡法莓。而且自從你把她從峰頂帶下來之後，她就再也沒吃過任何一個咕嚕摩了!', `MaleText_loc7`='Creo que esa yeti aprecia el buen kafa más que la mayoría de la gente. ¡Y no se ha comido ni un solo grúmel desde que la trajiste de la cima!' WHERE `ID`=60361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 무슨 짓을 한 거지?! 우린 다 죽었어!!', `MaleText_loc4`='我都做了些什么啊？！我们死定了！！', `MaleText_loc5`='我到底做了什麼?!我們全都死定了!!', `MaleText_loc7`='¡¿QUÉ HE HECHO?! ¡¡ESTAMOS TODOS MUERTOS!!' WHERE `ID`=60362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모르겠어... 이 설인이 여기 있는 게 아무래도 느낌이 안 좋아...$B$B가끔 고개를 돌려 보면, 저 녀석이 날... 뚫어지게 바라보고 있다고.', `MaleText_loc4`='我不知道……把这个雪人带到这里来还是让我有一种不祥的预感……$B$B有时候我发现她在……盯着我看。', `MaleText_loc5`='我不知道...這雪人待在這裡還是讓我覺得不舒服...$b$b有時我會逮到她正...盯著我看。', `MaleText_loc7`='No sé... Todavía me da mala espina esta yeti...$B$BA veces la pillo... mirándome fijamente.' WHERE `ID`=60363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<최근에 심하게 맞은 흔적이 있는 판다렌입니다. 시신이 아직 채 식지 않았습니다.>', `MaleText_loc4`='<这个熊猫人刚刚遭受过殴打和折磨。他的尸体上犹有余温。>', `MaleText_loc5`='<這個熊貓人前不久才剛被人剝光、痛打且分屍。他的屍體還沒完全變冷。>', `MaleText_loc7`='<Este pandaren ha sido desnudado y golpeado hasta la muerte hace poco. Su cuerpo aún guarda calor.>' WHERE `ID`=60364;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='효과가 있습니다! 상처가 아물고 있어요!', `FemaleText_loc4`='成功了！伤口正在愈合！', `FemaleText_loc5`='成功了!傷口開始癒合了!', `FemaleText_loc7`='¡Funciona! ¡La herida se está cerrando!' WHERE `ID`=60365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘레곤이 나락샤의 동력장치를 재활성화하기 시작합니다.', `MaleText_loc4`='伊拉贡开始恢复纳拉克煞引擎了。', `MaleText_loc5`='艾拉岡開始重啟納拉卡煞引擎。', `MaleText_loc7`='Elegon empieza a reactivar el Motor de Nalak''sha.' WHERE `ID`=60366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시신을 살펴봅니다.', `MaleText_loc4`='检查尸体。', `MaleText_loc5`='檢查屍體。', `MaleText_loc7`='Examina el cuerpo.', `FemaleText_loc1`='시신을 살펴봅니다.', `FemaleText_loc4`='检查尸体。', `FemaleText_loc5`='檢查屍體。', `FemaleText_loc7`='Examina el cuerpo.' WHERE `ID`=60367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 남쪽에 있는 깊은 굴과 조각니 야영지에서 우상을 찾아 보세요.', `MaleText_loc4`='去南边的深石窟和断牙营地找神像。', `MaleText_loc5`='到這南邊的斷齒深淵和斷齒營地尋找塑像。', `MaleText_loc7`='Busca ídolos al sur de aquí, en la Zanja y el Campamento Dienterroto.' WHERE `ID`=60368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네, 향에 불을 붙였군.', `MaleText_loc4`='很好，你已经点燃了熏香。', `MaleText_loc5`='很好，你已點燃薰香。', `MaleText_loc7`='Bien, has encendido el incienso.' WHERE `ID`=60369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음이 가벼워지는 듯한 느낌이 들지 않는가?', `MaleText_loc4`='你感觉到了没？你的精神振奋了吗？', `MaleText_loc5`='你感覺不到嗎?你的靈魂正在昇華?', `MaleText_loc7`='¿No lo sientes? ¿Tu espíritu, que se eleva?' WHERE `ID`=60370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 한 일은, 우리 판다렌들이 가장 중요하게 여기는 진실에 대한 찬사일세.', `MaleText_loc4`='知道吗，你所做的一切，正好体现了我们熊猫人推崇备至的一个真理。', `MaleText_loc5`='你知道嗎，你所做的，是向我們熊貓人最注重的真理致上了敬意。', `MaleText_loc7`='Verás, lo que acabas de hacer es un tributo a una verdad que los pandaren valoramos profundamente.' WHERE `ID`=60371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤오하오가 그랬듯이, 우리는 궁극의 운명은 땅과 하나가 되는 것임을 안다네. 세상 만물에 끝은 없지.', `MaleText_loc4`='跟少昊一样，我们知道，我们最终的命运便是和大地融为一体。一切都没有真正的终结之时。', `MaleText_loc5`='就像紹昊一樣，我們知道自己最終的命運就是化身為土地的一部分。沒有什麼事物會完全消逝。', `MaleText_loc7`='Como Shaohao, también sabemos que nuestro destino final es volver a la tierra. No existe un final verdadero.' WHERE `ID`=60372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기쁘게 죽음을 맞이하는 이는 없다네. 허나 공포나 분노, 의심을 품어서도 안 된다네.', `MaleText_loc4`='我们都不可能满怀喜悦地面对死亡——但我们也不应心生恐惧、愤怒或疑虑。', `MaleText_loc5`='我們沒人是帶著喜悅迎接死亡，但我們也不該帶著恐懼、憤怒或疑惑。', `MaleText_loc7`='Ninguno de nosotros recibimos la muerte con alegría, pero tampoco sentimos miedo, ira ni duda.' WHERE `ID`=60373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다렌들, 내 친구들은 죽었으나, 이들의 희생과 자네의 공로 덕분에 판다리아는 앞으로도 건재할 걸세.', `MaleText_loc4`='尽管这些熊猫人——我的朋友们——都已经倒下，但我们知道，通过他们的牺牲和你所付出的可贵努力，潘达利亚将继续焕发生机。', `MaleText_loc5`='雖然我的熊貓人朋友已死，但我們知道，經由他們的犧牲與你高貴的舉動，潘達利亞會繼續存在。', `MaleText_loc7`='Aunque estos pandaren, mis amigos, han muerto, sabemos que gracias a su sacrificio y a tus nobles obras, Pandaria seguirá existiendo.' WHERE `ID`=60374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 죽지만, 그 죽음으로부터 새로운 생명이 피어난다네. 바로 그 진실을 위해 우리는 살고, 일하고, 죽는 것이지.', `MaleText_loc4`='虽然我们也许会死，但我们的消逝将会催生新的生命。这就是我们为之生存、努力和牺牲的真理。', `MaleText_loc5`='雖然我們會死去，但我們的消逝會孕育出新的生命。這就是我們為之而生，為之而戰，且為之而死的真理。', `MaleText_loc7`='A través de nuestra muerte surge vida nueva. Esta es la verdad por la que vivimos, trabajamos y morimos.' WHERE `ID`=60375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이는가? 무덤에서 나무가 자라났네. 이 나무가 언제까지나 이곳에 서서, 이들의 희생과 자네가 표한 경의를 기리기를 바라네.', `MaleText_loc4`='看见了吗？在他们的坟冢上，长出了新的树苗。愿这些树木长盛不衰，永远见证着逝者的牺牲，还有你为他们赢得的荣光。', `MaleText_loc5`='你看見了嗎?他們的墓上長出了樹木。這些樹將永遠紀念他們的犧牲以及你給予他們的榮耀。', `MaleText_loc7`='¿Ves? De sus tumbas crecen árboles. Que estos árboles sean un recordatorio eterno del sacrificio que realizaron y del honor que les has otorgado.' WHERE `ID`=60376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 친구. 자네는 실로 영웅일세.', `MaleText_loc4`='谢谢你，朋友。你是一位真正的英雄。', `MaleText_loc5`='謝謝你，朋友。你是個真正的英雄。', `MaleText_loc7`='Gracias. Eres $gun verdadero héroe:una verdadera heroína;.' WHERE `ID`=60377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 복덩이가 왔군요! 우상이 폭발하는 모습이 여기서도 보였어요.', `MaleText_loc4`='哈哈！是幸运星来了！我在这里都看见神像被炸飞了。', `MaleText_loc5`='哈哈!幸運星來了!我從這裡就看到塑像爆炸。', `MaleText_loc7`='¡Ja, ja! ¡Aquí está el grisgrís! He visto explotar los ídolos desde aquí.' WHERE `ID`=60378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술자라는 사람을 찾으러 가자. 가시 빼는 게 생각만큼 힘들지 않을지도 모르겠어.', `MaleText_loc4`='我们去找那个工程师。或许拔掉这根刺并没有我们想的那么难。', `MaleText_loc5`='我們去找這個技師吧。或許要拔除這根刺沒有想像中那麼困難。', `MaleText_loc7`='Busquemos a ese ingeniero. Quizás deshacerse de esta espina sea más fácil de lo que pensábamos.' WHERE `ID`=60379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 북쪽으로 가 주세요! 형제 야크편자가 호젠에게 호된 짓을 당하기 전에 구해 주세요!', `MaleText_loc4`='急速向北！在猢狲迫害我的堂弟牦牛鞋之前找到他。', `MaleText_loc5`='快去北邊!找到牛蹄兄以免猴人對他做不好的事情。', `MaleText_loc7`='¡Deprisa, al norte! Encuentra al hermano Herradura de Yak antes de que los hozen le hagan algo.' WHERE `ID`=60380;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼애애!', `FemaleText_loc4`='不——！！！！', `FemaleText_loc5`='不～～!', `FemaleText_loc7`='¡NOOO!' WHERE `ID`=60381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='린, 내 마음의 주인! 안 돼, 안 돼요! 이럴 순 없어!', `FemaleText_loc4`='林，亲爱的！不，拜托，不要！怎么会这样！', `FemaleText_loc5`='林，我的心肝!不，拜託，不!這不可能!', `FemaleText_loc7`='¡Lin, corazón de mi alma! ¡No, por favor, NO! ¡No puede ser!' WHERE `ID`=60382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 조금만 더 빨리 왔더라면! 반이 내 말을 들었더라면!', `FemaleText_loc4`='要是班肯听我的就好了！我能早来一步就好了！', `FemaleText_loc5`='如果我能快點趕來!如果班願意聽我的!', `FemaleText_loc7`='Ojalá hubiera venido antes... Ojalá Ban me hubiera hecho caso...' WHERE `ID`=60383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흑, 내 사랑. 이제... 마음 편히... 잠들어요.', `FemaleText_loc4`='嘘，亲爱的。现在，安静地睡吧。', `FemaleText_loc5`='噓，我親愛的，睡吧，寧靜的睡吧。', `FemaleText_loc7`='Shh, mi amor, ahora duerme y descansa en paz.' WHERE `ID`=60384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 죽인 자들은 값을 치를 거예요.', `FemaleText_loc4`='我绝不会放过杀害你的凶手。', `FemaleText_loc5`='殺死你的兇手將被制裁。', `FemaleText_loc7`='Tus asesinos recibirán su castigo.' WHERE `ID`=60385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약속해요.', `FemaleText_loc4`='我发誓。', `FemaleText_loc5`='我會親手做到。', `FemaleText_loc7`='Me aseguraré de ello.' WHERE `ID`=60386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴! 이런데도 야크편자가 복덩이가 아니란 말야? 구해 주신 거 정말 고마워요.', `MaleText_loc4`='呜呼！他们还说牦牛鞋不是幸运符！万分感谢你们的搭救。', `MaleText_loc5`='呀呼!他們還說牛蹄不是個幸運星!多謝你救我。', `MaleText_loc7`='¡Yuju! ¡Y decían que la Herradura de Yak no era un grisgrís! Gracias por rescatarme.' WHERE `ID`=60387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원거리 무기가 있으면, 그루멀을 매달고 있는 밧줄을 쏘아 맞히세요.', `MaleText_loc4`='如果你有远程武器，就用它射断吊起土地精的绳子。', `MaleText_loc5`='如果你有遠程武器，可以用來射斷將咕嚕摩綁在上面的繩子。', `MaleText_loc7`='Si tienes un arma a distancia, puedes utilizarla para disparar a las cuerdas que sostienen a los grúmel.' WHERE `ID`=60388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 제 훈련 임무라고 했어요. 그런데 일이 커지고 있는 것 같네요.', `MaleText_loc4`='他们对我说这只是一次训练任务。可我觉得现在的情况好像远不止此。', `MaleText_loc5`='他們告訴我這是個訓練任務。我總覺得事情變得不只是這樣了。', `MaleText_loc7`='Me dijeron que esto sería una misión de entrenamiento. Me da la impresión de que se está convirtiendo en algo más.' WHERE `ID`=60389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 맹주님 보셨어요? 그분의 무용은 전설적이에요.', `MaleText_loc4`='你之前见到祝踏岚掌门了吗？他的强大力量简直可以媲美神话中的英雄。', `MaleText_loc5`='你之前見過塔蘭·祝大人嗎?他的英勇是個傳奇。', `MaleText_loc7`='¿Has visto a lord Taran Zhu? Su destreza es legendaria.' WHERE `ID`=60390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠을 깔아뭉갤 준비는 됐나요, 아가씨?', `MaleText_loc4`='准备好去弄死些猢狲了吗，姑娘？', `MaleText_loc5`='姑娘，準備打扁一些猴人了嗎?', `MaleText_loc7`='¿Lista para destrozar algunos hozen, pequeña?', `FemaleText_loc1`='호젠을 깔아뭉갤 준비는 됐나요, 아가씨?', `FemaleText_loc4`='准备好去弄死些猢狲了吗，姑娘？', `FemaleText_loc5`='姑娘，準備打扁一些猴人了嗎?', `FemaleText_loc7`='¿Lista para destrozar algunos hozen, pequeña?' WHERE `ID`=60391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 님이 저한테 말을 거셨어요! 실망을 안겨선 안 될 텐데.', `MaleText_loc4`='踏岚掌门已经跟我说了！但愿我不会让他失望。', `MaleText_loc5`='塔蘭大人之前跟我說過話!我希望我沒讓他失望。', `MaleText_loc7`='¡Lord Taran se ha dirigido a mí! Espero no decepcionarle.' WHERE `ID`=60392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 때맞춰서 구출해 주는 이에게 복 있으라.', `MaleText_loc4`='啊！愿及时出手相救的人能交上好运。', `MaleText_loc5`='啊!祝福能掌握最佳時機、完成拯救的人。', `MaleText_loc7`='¡Ah! Buena fortuna a quien organiza un rescate justo a tiempo.' WHERE `ID`=60393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀의 친구, 복 받아요!', `MaleText_loc4`='愿土地精的朋友一路好运！', `MaleText_loc5`='願咕嚕摩的朋友好運!', `MaleText_loc7`='¡Buena fortuna a los amigos de los grúmel!' WHERE `ID`=60394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에서 불운 냄새가 심하게 나요. 호젠한테서는 불운 냄새 더 심하게 나요.', `MaleText_loc4`='牢笼散发着暗示厄运的臭味。猢狲散发的臭味更糟糕。', `MaleText_loc5`='牢籠有倒楣的臭味，猴人有更臭的倒楣味。', `MaleText_loc7`='La jaula apesta a mala fortuna. Y los hozen apestan a incluso peor fortuna.' WHERE `ID`=60395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 일을 또 당하지 않으려면 더 좋은 복덩이를 구해야겠어요.', `MaleText_loc4`='我要一个更好的幸运符以确保这种事不再发生。', `MaleText_loc5`='我需要更好的幸運星來確保這一切不會再度發生。', `MaleText_loc7`='Necesito un grisgrís mejor para asegurarme de que esto no vuelva a pasar.' WHERE `ID`=60396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='향을... 찾아야... 해요...', `MaleText_loc4`='一定……要找到……熏香……', `MaleText_loc5`='必須...找到...薰香...', `MaleText_loc7`='Necesito... encontrar... incienso...' WHERE `ID`=60397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요!', `MaleText_loc4`='非常感谢！', `MaleText_loc5`='非常感謝!', `MaleText_loc7`='Muchas gracias.' WHERE `ID`=60398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 이름을 $p발로 바꿀까 봐요.', `MaleText_loc4`='也许从现在开始，我要称呼自己为$P脚。', `MaleText_loc5`='也許我從現在起就改叫「$P腳」好了。', `MaleText_loc7`='Quizás me llame "Pata de $P" de ahora en adelante.' WHERE `ID`=60399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 콘이다!!', `MaleText_loc4`='是寇塔空！！', `MaleText_loc5`='是柯沓峰的恐懼之王!!', `MaleText_loc7`='¡¡Un Kota Kon!!' WHERE `ID`=60400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 응가쟁이 전당에 가둘 테다!', `MaleText_loc4`='我们要把你关进暴徒末路！', `MaleText_loc5`='我們要把你丟進廢渣園地!', `MaleText_loc7`='¡Nosotros meterte en la Kúpula del Miko!' WHERE `ID`=60401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 남편이 며칠 전에 야운골에게 잡혀 갔어요.$B$B우리가 이야기하는 지금도 위험에 처해 있다고요.', `FemaleText_loc4`='我丈夫在几天前被野牛人抓走了。$B$B在我们说话的时候，他正处在危险之中。', `FemaleText_loc5`='我的丈夫幾天前被揚古抓走了。$B$B他現在身處危險之中。', `FemaleText_loc7`='Mi marido fue capturado por los yaungol hace varios días.$B$BÉl corre peligro en este preciso instante.' WHERE `ID`=60402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 콘 왜 여기 있냐?!', `MaleText_loc4`='该死的寇塔空跑这儿来做什么？！', `MaleText_loc5`='柯沓峰的恐懼之王在這裡做什麼?!', `MaleText_loc7`='¡¿Ké krakus hace un Kota Kon akí?!' WHERE `ID`=60403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안하지만 저는 지금 큰 도움이 안 될 거예요, $n.$B$B남편이 걱정돼 쓰러질 지경이거든요.', `FemaleText_loc4`='我现在恐怕帮不上什么忙，$n。$B$B我太担心我丈夫了。', `FemaleText_loc5`='恐怕我現在派不上什麼用場，$n。$B$B我滿腦子都在擔心我丈夫。', `FemaleText_loc7`='Me temo que no soy de mucha utilidad ahora mismo, $n.$B$BLa preocupación por mi marido está acabando conmigo.' WHERE `ID`=60404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='린이 위험한데 손 놓고 있을 순 없어요.', `FemaleText_loc4`='林正深陷险境，我无法坐视不理。', `FemaleText_loc5`='林身處危險之中，我不能袖手旁觀。', `FemaleText_loc7`='No puedo quedarme parada mientras Lin está en peligro.' WHERE `ID`=60405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼, 안 돼. 내 남편. 이렇게 갈 순 없어요.', `FemaleText_loc4`='不，不，不。林，我亲爱的丈夫，你不能死。', `FemaleText_loc5`='不，不，不。林，我親愛的丈夫。你不能死。', `FemaleText_loc7`='No, no, no. Lin, mi querido esposo. Esto no puede haber pasado.' WHERE `ID`=60406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이 우낏 같으니! 돌아와!', `MaleText_loc4`='该死的蠢蛋！回这儿来！', `MaleText_loc5`='該死的怪怪人!給我回來!', `MaleText_loc7`='¡Dingue makaku! ¡Vuelve akí!' WHERE `ID`=60407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 차가웠어요... 생기라곤 없이 축 쳐져서...', `FemaleText_loc4`='他这么冷，这么无助，毫无生气。', `FemaleText_loc5`='他好冰冷。毫無生氣，死氣沉沉。', `FemaleText_loc7`='Estaba tan frío... Tan quieto e inerte...' WHERE `ID`=60408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말했는데! 반에게 공격해야 한다고 그렇게 말했는데! 다 반 때문이에요!', `FemaleText_loc4`='我早就说了！我早跟班说了应该出击！这都是他的错！', `FemaleText_loc5`='我告訴過他!我告訴班我們必須攻擊!都是他的錯!', `FemaleText_loc7`='¡Se lo dije! ¡Le dije a Ban que debíamos atacar! ¡Esto es todo culpa suya!' WHERE `ID`=60409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 며칠 전에 잘 있으라고 했다고요. 아직도 그 얼굴이 눈에 아른거려요! 그런데 어떻게 죽을 수가 있죠?', `FemaleText_loc4`='他几天前才跟我告别。我的眼前至今还晃动着他的脸。他怎么可能死了呢？', `FemaleText_loc5`='他幾天前才剛我說過再見。我腦中還清楚浮現他的面孔!他怎麼會就這樣死了?', `FemaleText_loc7`='Se despidió de mí hace solo unos días. ¡Aún puedo ver su rostro! ¿Cómo puede estar muerto?' WHERE `ID`=60410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린을 잃은 것은 슬프기 그지없는 일이지만, 저는 우리 군의 병사 하나하나를 생각해야 합니다.$B$B생명은 모두 똑같이 귀한 것이니까요.$B$B한 사람의 생명을 구하고자 많은 사람의 생명을 걸 수는 없습니다.', `MaleText_loc4`='我对林的牺牲深表遗憾，可我必须为部队中的每一个战士考虑。$B$B每一条生命都是宝贵的，都一样值得我们珍惜。$B$B我不能为了救一个人而赌上一群人的性命。', `MaleText_loc5`='對林的死我深感抱歉，但我必須考慮軍隊中的每一個士兵。$B$B每個生命都很珍貴，而且價值相等。$B$B我無法賭上這麼多人的生命去拯救一個人。', `MaleText_loc7`='Siento en el alma la pérdida de Lin, pero debo pensar en todos los soldados de mi ejército.$B$BCada vida es valiosa, y debe considerarse igual al resto.$B$BNo puedo arriesgar la vida de muchos para salvar la de uno.' WHERE `ID`=60411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음은 코타 우낏 털 거다!', `MaleText_loc4`='寇塔蠢蛋接下来要大破坏了！', `MaleText_loc5`='下個要宰的就是柯沓怪怪人!', `MaleText_loc7`='¡Makakus Kota devastados pronto!' WHERE `ID`=60412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 잘 해냈습니다.', `MaleText_loc4`='形势逐渐乐观了起来。', `MaleText_loc5`='我們做得很好。', `MaleText_loc7`='Hemos hecho bien aquí.' WHERE `ID`=60413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 콘 생각보다 훨씬 크다...', `MaleText_loc4`='寇塔空的块头比我想象中的还要大……', `MaleText_loc5`='柯沓峰的恐懼之王比我想的還大隻...', `MaleText_loc7`='Kota Kon más grande ke yo pensaba...' WHERE `ID`=60414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오술 봉우리에서 승리를 거두어 기쁩니다. 작전이 성공적입니다.', `MaleText_loc4`='我为我们在奥苏尔峰的胜利而高兴。我想这是一场成功的战役。', `MaleText_loc5`='我高興我們在歐索峰獲得成功。我認為這是場成功的戰役。', `MaleText_loc7`='Estoy contento por nuestro triunfo en Cima Osul. Diría que está siendo una campaña exitosa.' WHERE `ID`=60415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 님께 보고할 좋은 소식이 많습니다.$B$B오술 봉우리에서의 승전보를 들으시면 기꺼워하시겠지요.', `MaleText_loc4`='我们可以给踏岚掌门带去许多好消息了。$B$B我们在奥苏尔峰这里的胜利一定会让他高兴的。', `MaleText_loc5`='我們將有很多好消息可以回報給塔蘭大人。$B$B我們在歐索峰這裡獲得的勝利，會愉悅地在他耳中迴響。', `MaleText_loc7`='Tendremos muchas buenas nuevas que transmitir a lord Taran.$B$BLas noticias sobre nuestra victoria en Cima Osul serán música para sus oídos.' WHERE `ID`=60416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 이곳에서 처음 지휘한 작전이 제법 성공을 거둔 것 같습니다.', `MaleText_loc4`='我得说，我第一次指挥作战还是相当成功的。', `MaleText_loc5`='我得說我第一次的指揮作戰相當成功。', `MaleText_loc7`='Me atrevería a decir que mi primer mando aquí ha sido un éxito.' WHERE `ID`=60417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 다 뭉갤 순 없을걸!', `MaleText_loc4`='你压不垮我们！', `MaleText_loc5`='你無法把我們全打爛!', `MaleText_loc7`='¡No puede machakarnos a todos!' WHERE `ID`=60418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 승리한 데는 $n, 당신의 공이 컸습니다.', `MaleText_loc4`='我们在这里的胜利都是多亏了你，$n。', `MaleText_loc5`='我們能獲得勝利，都得感謝你，$n。', `MaleText_loc7`='Nuestra victoria se debe en gran parte a ti, $n.' WHERE `ID`=60419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이 전당에서 만나요. 우린 향이랑 더러운 야크를 구해야 하거든요.', `MaleText_loc4`='到暴徒末路与我们会合。我们要找一些熏香和一头肮脏的牦牛。', `MaleText_loc5`='到廢渣園地找我們，我們需要找到一些薰香和一頭髒犛牛。', `MaleText_loc7`='Reúnete con nosotros en la Cúpula del Miko. Tenemos que encontrar incienso y un yak sucio.' WHERE `ID`=60420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족장님을 위해!', `MaleText_loc4`='为了酋长！', `MaleText_loc5`='為了酋長!', `MaleText_loc7`='¡Por el jefe!' WHERE `ID`=60421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<쑤나라는 이름이 수놓인 손수건을 쥐고 있습니다.>', `MaleText_loc4`='<他手里攥着一块手帕，上面绣着一个小字：“娜”。>', `MaleText_loc5`='<他的手還緊抓著一條手帕，上面繡著小字「蘇納贈」。>', `MaleText_loc7`='<En su mano tiene un pañuelo con las iniciales S.G.S.>' WHERE `ID`=60422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경미한 손실을 입었을 뿐입니다. 그 외에는 상황이 꽤 잘 돌아가고 있다고 할 수 있습니다.', `MaleText_loc4`='我们还是遇到了一些小伤亡。除此之外，一切都相当顺利。', `MaleText_loc5`='我們有少數人員傷亡。若不是這樣，我會說事情進展非常順利。', `MaleText_loc7`='Solo hemos sufrido unas cuantas bajas menores. Aparte de eso, yo diría que las cosas van bastante bien.' WHERE `ID`=60423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 린의 용기를 잊지 않을 겁니다.', `MaleText_loc4`='我们一定会表彰林的英勇事迹的。', `MaleText_loc5`='我們將確保林的勇氣得到該有的榮耀。', `MaleText_loc7`='Nos aseguraremos de honrar la valentía de Lin.' WHERE `ID`=60424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 지휘가 생각보다 어렵습니다. 제가 옳은 결정을 내린 걸까요?', `MaleText_loc4`='首次指挥作战比我想象中的要难一些。我的决定到底正确吗？', `MaleText_loc5`='第一次進行指揮作戰比我想的更困難。我做的決定正確嗎?', `MaleText_loc7`='Mi primer mando ha sido más difícil de lo que creía. ¿He tomado la decisión correcta?' WHERE `ID`=60425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 호젠이 약한 줄 아느냐!', `MaleText_loc4`='蠢蛋以为猢狲不堪一击！', `MaleText_loc5`='怪怪人以為猴人很弱!', `MaleText_loc7`='¡Makakus kreen hozen débiles!' WHERE `ID`=60426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 설인 데리고 있다! 들리느냐! 우리는 설인 데리고 있다!', `MaleText_loc4`='天哪，我们找到了一个雪人！你没听错！一个雪人！', `MaleText_loc5`='我們有一個雪人，渣渣!你聽到了嗎?我們有一個雪人!', `MaleText_loc7`='¡Nosotros tienen un yeti, mikos! ¿Ustedes oyen? ¡Tienen un yeti!' WHERE `ID`=60427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가 같은 우낏, 쩝쩝이한테 먹이로 줄 테다!', `MaleText_loc4`='该死的蠢蛋要吃乔普乔普！', `MaleText_loc5`='該死的怪怪人會被餵給強普·強普!', `MaleText_loc7`='¡Dingue makakus será manduka de Krak Krak!' WHERE `ID`=60428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 호젠한테 까까짐 가져가지 말라 한다! 호젠 그래도 가져간다! 몽땅 털어라!', `MaleText_loc4`='蠢蛋不想让猢狲抢走果子！可猢狲照样要抢！抢啊！', `MaleText_loc5`='怪怪人不想要猴人拿他們好吃的東東!但是猴人就是要拿!搶啊!', `MaleText_loc7`='¡Makakus no kieren ke hozen kojan su manduka! ¡Pero hozen van a koger! ¡Devastar!' WHERE `ID`=60429;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<쑤나는 대답 없이 허공을 바라보며 몸을 떱니다.>', `FemaleText_loc4`='<孙娜前后摇晃着，凝望着天空。她没有回答。>', `FemaleText_loc5`='<蘇納來回的搖動，兩眼瞪視著虛空。她沒有回答。>', `FemaleText_loc7`='<Suna se balancea hacia delante y hacia atrás, con la mirada perdida. No responde.>' WHERE `ID`=60430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몽땅 훔쳐라!', `MaleText_loc4`='夺走一切！', `MaleText_loc5`='拿走所有的東西!', `MaleText_loc7`='¡Kogen las kosas!' WHERE `ID`=60431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='털어라! 털어라! 털어라!', `MaleText_loc4`='抢啊！抢啊！抢啊！', `MaleText_loc5`='搶啊!搶啊!搶啊!', `MaleText_loc7`='¡Devastar! ¡Devastar! ¡Devastar!' WHERE `ID`=60432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서는 오랫동안 전쟁이라는 말을 입 밖에 낼 일이 없었습니다.$B$B하지만 지금은... 평화를 되찾기 위해 싸워야 합니다.', `MaleText_loc4`='“战争”这个词已经很久没有在潘达利亚出现过了。$B$B而现在，我们必须为了恢复和平……而战斗。', `MaleText_loc5`='「戰爭」這個字眼，已有很長一段時間沒有在潘達利亞被人提起。$B$B現在，為了恢復和平...我們必須戰鬥。', `MaleText_loc7`='Guerra es una palabra que no se decía desde hace mucho tiempo en Pandaria.$B$BAhora todos debemos luchar... para conseguir la paz.' WHERE `ID`=60433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌기주먹이 쿤라이 지배할 거다!', `MaleText_loc4`='肘锤猢狲将统治昆莱！', `MaleText_loc5`='骨捶一族將會統治崑萊!', `MaleText_loc7`='¡Machakadedos dominarán Kun-Lai!' WHERE `ID`=60434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상에. 내 복덩이야, 날 버리지 말아 줘.', `MaleText_loc4`='噢，天呐。幸运符居然在这会儿坑我。', `MaleText_loc5`='喔老天。幸運星可別在這時候失效。', `MaleText_loc7`='Oh no. No me falles ahora, grisgrís.' WHERE `ID`=60435;
