UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이 녀석 깨우는 게 보통 일이 아냐! 때려도 봤고, 밧줄로 당겨도 봤고, 온몸을 내던져 징도 쳐 봤지만, 전혀 효과가 없어!$B$B뭐, 괜찮아. 아직 좋은 생각이 더 있으니까.', `MaleText_loc4`='嗨！要叫醒这家伙还真不容易！我对他又敲又打，又吼又叫，用绳子拉，用身体压，什么法子都试过了，全都没用！$B$B好吧，我得好好想点别的主意。', `MaleText_loc5`='哈!叫醒這傢伙可不簡單。我試過揍他、用繩子拖他、用吃奶的力氣敲鑼吵他，全都沒效!$b$b啊好吧，我還有其他點子可以用。', `MaleText_loc7`='¡Ja! ¡Despertar a este tipo no es nada sencillo! Lo he golpeado, he intentado tirarlo de una cuerda, me he lanzado contra este gong, ¡y nada!$b$bPero bueno, tengo algunas ideas más para empezar.' WHERE `ID`=60458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 지론은, 영감이 떠오를 때까지 가만히 기다릴 필요는 없다는 거야. 행동이 영감을 이끌어 내지, 영감이 행동을 이끌어 내진 않으니까.$B$B그런 게 바로 후오진의 가르침이야.', `MaleText_loc4`='要我说，“先行动，后思考”才是正确的行事方法。行动可以带来灵感。但光凭思考，什么事都做不了。$B$B这就是火金之道。', `MaleText_loc5`='我一直認為我們不該被教導去等待某種靈感才開始動手。行動總能激發靈感。靈感卻鮮少激發行動。$B$B這就是火金之道。', `MaleText_loc7`='Siempre he creído que no se nos debe enseñar a esperar a estar inspirados para empezar algo. La acción siempre genera inspiración y, al contrario, la inspiración raramente genera acción.$b$bAsí es el camino de los huojin.' WHERE `ID`=60459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 성공이야. 물이면 되는 거였어! 왜 진작 이 생각을 못 했을까.', `MaleText_loc4`='有办法了，浇水！我怎么没早点想到这主意。', `MaleText_loc5`='這就成功啦，只要加點水就好!假如我早點想到這一招就好了。', `MaleText_loc7`='¡Así que solo había que añadir agua! Ojalá se me hubiera ocurrido antes.' WHERE `ID`=60460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책의 표지는 대부분 훼손되었습니다. 그나마 알아볼 수 있는 것은 트롤 문자로 쓰인 듯합니다...', `MaleText_loc4`='这本书的大部分封皮都已经损坏了。从还能辨认的部分看，似乎是巨魔语。', `MaleText_loc5`='這本書的封面大部分已被摧毀，仍可辨識的部分似乎是食人妖的文字...', `MaleText_loc7`='Gran parte de la cubierta de este libro está destrozada. La parte legible parece estar escrita en trol...' WHERE `ID`=60461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도굴꾼 하나가 책장을 흘린 모양입니다. 전승지기 초는 읽을 수 있을 것입니다.', `MaleText_loc4`='这页纸肯定是某个盗墓者遗落的。游学者周卓应该知道上面写了什么。', `MaleText_loc5`='這頁一定是其中一個強盜掉下來的，博學行者阿洲一定看得懂上面寫些什麼。', `MaleText_loc7`='Esta página se le ha debido de caer a uno de los saqueadores. Seguro que el eremita Cho sabe lo que dice.' WHERE `ID`=60462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 의식이 있었는지, 제단이 아직도 따뜻합니다...', `MaleText_loc4`='祭坛还是温热的，肯定刚刚举行过某种仪式……', `MaleText_loc5`='祭壇上仍殘留上個儀式的餘溫...', `MaleText_loc7`='El altar todavía está caliente por algún ritual reciente...' WHERE `ID`=60463;
