UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 잔소리가 끝나는 대로요...', `MaleText_loc4`='别唠叨了，动手吧……', `MaleText_loc5`='只等你停止嘮嘮叨叨...', `MaleText_loc7`='En cuanto te dejes de cháchara...', `FemaleText_loc1`='당신 잔소리가 끝나는 대로요...', `FemaleText_loc4`='别唠叨了，动手吧……', `FemaleText_loc5`='只等你停止嘮嘮叨叨...', `FemaleText_loc7`='En cuanto te dejes de cháchara...' WHERE `ID`=60473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들은 식량을 놓고 싸웠어요. 식량을 나누지 않고 누군가가 다 파괴한 것 같네요. 대체 왜 그랬을까요?', `MaleText_loc4`='他们曾为食物大打出手。但看来他们没能分到食物，有人把补给都毁了。他们为何要这么做呢？', `MaleText_loc5`='他們為了存糧爭執。有人寧願把食物全毀了，也不願意跟別人分享。為什麼他們要這麼做?', `MaleText_loc7`='Lucharon por la comida. Parece que, en lugar de compartirla, alguien la destruyó toda. ¿Por qué harían algo así?' WHERE `ID`=60474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아군도 적군도 없이 마구잡이로 서로 죽인 것 같아요. 대체 왜 그랬을까요?', `MaleText_loc4`='据我观察，这并不是一场派系争斗。这些野牛人为什么会自相残杀呢？', `MaleText_loc5`='在我看來，這場戰鬥裡根本沒有分所謂的敵我。為什麼揚古要這樣互相殺害呢?', `MaleText_loc7`='Por lo que veo, no había bandos en la lucha. ¿Por qué se matarían entre sí los yaungol sin piedad?' WHERE `ID`=60475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 대장이에요. 대장마저 살해당했군요.', `MaleText_loc4`='野牛人酋长，和其他族人一样被杀害了。看来他也没能镇压住最终的混战。', `MaleText_loc5`='那是揚古的酋長，跟其他人一樣被殺了。', `MaleText_loc7`='Es el jefe yaungol, asesinado como todos los demás. Parece que no pudo poner orden en el combate.' WHERE `ID`=60476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 쉬엔 식 쌍발톱을 이길 수 있을까?', `MaleText_loc4`='你能破解我的双爪白虎式吗？', `MaleText_loc5`='你能擊敗我的雪怒雙爪式嗎?', `MaleText_loc7`='¿Podéis derrotar a mi estilo Xuen de doble garra?' WHERE `ID`=60477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 여기가 마음에 안 들어요. 어딘지 모르게 이상한 점이 있어요.', `FemaleText_loc4`='我不喜欢这个地方，$r。这里有点诡异。', `FemaleText_loc5`='我不喜歡個地方，$r。有些地方不對勁。', `FemaleText_loc7`='No me gusta este sitio, $r. Hay algo extraño en él.' WHERE `ID`=60478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을에 있으니 왠지 온몸의 털이 곤두서는 느낌이에요.', `FemaleText_loc4`='这个村子里有种让我毛骨悚然的气息。', `FemaleText_loc5`='這村莊有些地方讓我毛髮直豎。', `FemaleText_loc7`='Hay algo en esta aldea que me pone los pelos de punta.' WHERE `ID`=60479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서의 임무를 마칠 때까지는 쉬지 않을 거예요.', `FemaleText_loc4`='在完成任务之前，我们不能休息。', `FemaleText_loc5`='在這裡的職責完畢以前，我們都不會休息。', `FemaleText_loc7`='No descansaremos hasta cumplir con nuestro deber.' WHERE `ID`=60480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀들이 지금 있는 곳을 지도에 표시해 줄게요. 그곳으로 찾아가거나, 다음 그루멀 무리가 출발할 때까지 여기서 기다리세요.', `MaleText_loc4`='我在地图上给你指出土地精现在在哪里。要么去找他们，要么就待在这里等下一拨土地精。', `MaleText_loc5`='我在你的地圖上指給你看咕嚕摩現在在哪裡。去找他們或在這裡等下一波的咕嚕摩。', `MaleText_loc7`='Te enseñaré en el mapa dónde están los grúmel. Encuéntralos o espera a la siguiente oleada de grúmel.' WHERE `ID`=60481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $n. 반 님께 보고할 게 많네요. 여기부터는 저 혼자 돌아갈게요.', `MaleText_loc4`='谢谢你，$n。我有很多情况要向班报告。我想我能找到回去的路。', `MaleText_loc5`='謝謝你，$n。我有很多事要向班回報。我想我可以自己想辦法回去。', `MaleText_loc7`='Gracias, $n. Tengo que informar de muchas cosas a Ban. Creo que puedo volver por mi cuenta.' WHERE `ID`=60482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 친구들... 어떻게 하면 은둔 고수를 찾을 수 있을까?', `MaleText_loc4`='那么，朋友们……我们该如何找到隐秘大师呢？', `MaleText_loc5`='朋友們...我們該如何找到這個隱居的宗師?', `MaleText_loc7`='Bueno, amigos... ¿cómo vamos a encontrar al maestro oculto?' WHERE `ID`=60483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$g아저씨:아줌마;가 쥐구멍으로 가는 걸 보면 놈들이 미쳐 날뛸 거예요. 그러니까 일단 걷어차버리세요. 그러면 방해받지 않을 거예요.', `FemaleText_loc4`='要是让土拨鼠看到你毁了它们的地洞，一定会气疯的。先把它们解决掉，然后就好办了。', `FemaleText_loc5`='土撥鼠看到你破壞牠們的洞穴會很生氣的。先把牠們趕開，牠們就不會理你了。', `FemaleText_loc7`='Las marmotas se enfadan mucho si te ven estropeando sus madrigueras. Apártalas primero y te dejarán en paz.' WHERE `ID`=60484;
