UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에서 술을 만드는 분이시군요?', `MaleText_loc4`='这么说，你是个酿私酒的？', `MaleText_loc5`='所以，你是一個自宅釀酒師?', `MaleText_loc7`='¿Así que haces cerveza en casa?', `FemaleText_loc1`='집에서 술을 만드는 분이네요?', `FemaleText_loc4`='这么说，你是个酿私酒的？', `FemaleText_loc5`='所以，你是一個自宅釀酒師?', `FemaleText_loc7`='¿Así que haces cerveza en casa?' WHERE `ID`=60517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 맥주를 마실 수 있을 때부터 양조를 했습니다.$b$b어떤 이들은 저보고 저쪽에 있는 오래된 양조장에서 맥주를 살 수 있는데 괜히 시간만 낭비한다고 하지만... 모르겠습니다. 술을 직접 만들어 마시면 좋은 점이 있거든요.', `MaleText_loc4`='是的。我从会喝啤酒开始就在酿造啤酒了。$b$b这里的人说我在浪费时间，我可以去村子里买那种大桶的啤酒。我不那么认为。酿造自己的啤酒总是别有一番趣味。', `MaleText_loc5`='沒錯。從我能夠喝酒開始就在自己釀酒了。$b$b有人說我只是在浪費時間，我可以直接跟那個老牌的大釀酒廠購買啤酒，但...我不知道。能夠釀自己杯裡的酒就是有什麼對勁的地方。', `MaleText_loc7`='Sí. Llevo haciendo cerveza desde que pude beberla.$b$bHay quien dice que pierdo el tiempo, que podría comprar la cerveza de esa gran cervecería de allí abajo, pero... no sé. Es bonito fabricar tu propia jarra de cerveza.' WHERE `ID`=60518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머드머그가 진짜 이름입니까?', `MaleText_loc4`='泥盏是你的真名吗？', `MaleText_loc5`='泥杯是你的真名嗎?', `MaleText_loc7`='¿De verdad te llamas Caolín?', `FemaleText_loc1`='머드머그가 진짜 이름인가요?', `FemaleText_loc4`='泥盏是你的真名吗？', `FemaleText_loc5`='泥杯是你的真名嗎?', `FemaleText_loc7`='¿De verdad te llamas Caolín?' WHERE `ID`=60519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고, 절대 아닙니다. 그건 제가 맥주를 만드는 방법에서 나온 이름입니다.$b$b진흙탕 물에, 또 보시다시피 맥주를 발효시키는 벌레도 약간 있고 말이죠. 다른 이들은 일정한 환경의 말끔한 양조장에서 자란 진짜 효모나 뭐 그런 종류를 씁니다. 저는 진흙탕 물을 쓰지요.$b$b일종의 제 비법입니다.$b$b저는 당신이 생각하는 그런 "배양된" 것들을 쓰지 않을 뿐인 것 같습니다.', `MaleText_loc4`='噢，当然不是了。那只是我酿啤酒的方法。$b$b泥水，你看……里面总会有点小虫子，帮你发酵酒浆。有人会用真正的酵母，就是那种在人为控制的环境下，在正规酒厂里生长出来的东西，诸如此类的。而我喜欢用泥水。$b$b这更合适我。$b$b我就是不像你所说的那种“科班出身”的家伙。', `MaleText_loc5`='喔，才不是。這只是我做啤酒的方法。$b$b怎麼說呢...泥水...裡頭有一些小蟲，可以幫啤酒發酵。有些人用那種在人為控管下，從高檔花俏的釀酒坊所培育出來的真正酵母來發酵;而我則偏好用純天然的泥水。$b$b這就是我的作法。$b$b我想，我大概不是那種所謂「風雅有禮」的人吧。', `MaleText_loc7`='Oh, claro que no. Así es como hago la cerveza.$b$bCon agua y caolín, ¿sabes? Tiene unos bichitos que fermentan la cerveza. Hay quien usa levadura de verdad, cultivada en una cervecería lujosa en condiciones controladas y todo eso. Yo uso agua sucia.$b$bEs mi estilo.$b$bSupongo que no soy lo que se dice "cultivado".' WHERE `ID`=60520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요.', `MaleText_loc4`='哈哈。', `MaleText_loc5`='哈哈。', `MaleText_loc7`='Ja, ja.', `FemaleText_loc1`='그렇군요.', `FemaleText_loc4`='哈哈。', `FemaleText_loc5`='哈哈。', `FemaleText_loc7`='Ja, ja.' WHERE `ID`=60521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다! 그리고... 아, 경례하는 건가...$b$b죄송합니다. 무슨 말을 해야 할지 모르겠군요. 저는 주변에 친구라고 할 만한 이들이 많이 없어서 말입니다.$b$b그러니까, 물론 술을 사러 오는 친구들은 있지만 말입니다.', `MaleText_loc4`='你好！还有，呃……向你致敬，我猜。$b$b不好意思，真不知道该说些什么，我这里通常很少有人来。$b$b当然了，除非是他们来我这里买酒的时候。', `MaleText_loc5`='你好!然後，啊...向您問候。$b$b抱歉。我不確定該說些什麼。我不太習慣有太多人在這裡。$b$b當然了，除非他們是來這裡要買些我的酒。', `MaleText_loc7`='¡Buenas! Y, esto... saludos, supongo.$b$bLo siento. No sé muy bien qué decir. No estoy acostumbrado a tener compañía por aquí.$b$bEs decir, a menos que vengan a comprar mi cerveza, por supuesto.' WHERE `ID`=60522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 싸울 준비는 됐습니까?', `MaleText_loc4`='[PH]准备好战斗了吗？', `MaleText_loc5`='[PH]你準備好要戰鬥了嗎?', `MaleText_loc7`='[PH] Are you ready to fight?', `FemaleText_loc1`='[PH] 싸울 준비는 됐어요?', `FemaleText_loc4`='[PH]准备好战斗了吗？', `FemaleText_loc5`='[PH]你準備好要戰鬥了嗎?', `FemaleText_loc7`='[PH] Are you ready to fight?' WHERE `ID`=60523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 싸울 준비가 됐습니다!', `MaleText_loc4`='[PH]我准备好了！', `MaleText_loc5`='[PH]我準備好要戰鬥了!', `MaleText_loc7`='[PH] I''m ready to fight!', `FemaleText_loc1`='[PH] 싸울 준비가 됐어요!', `FemaleText_loc4`='[PH]我准备好了！', `FemaleText_loc5`='[PH]我準備好要戰鬥了!', `FemaleText_loc7`='[PH] I''m ready to fight!' WHERE `ID`=60524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이제 괜찮을 것 같아요. 고마워요.', `MaleText_loc4`='幸亏有你，我……我想我暂时安全了。', `MaleText_loc5`='我...我想我目前是安全了。謝謝你。', `MaleText_loc7`='Creo... que ya estamos a salvo, de momento, gracias a ti.' WHERE `ID`=60525;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 더럽히는 어둠의 힘이 뭔지 봅시다.', `FemaleText_loc4`='现在！来看看是何种黑暗腐蚀了此地吧！', `FemaleText_loc5`='現在!我們來看看是什麼樣的黑暗污染了這個地方!', `FemaleText_loc7`='Bien. Veamos qué oscuridad corrompe este lugar.' WHERE `ID`=60526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='커다란 토템 세 개를 작동시켜서 도와주세요.', `FemaleText_loc4`='$n，请帮我激活那三个大型图腾。', `FemaleText_loc5`='$n，幫我啟動這三個巨大圖騰。', `FemaleText_loc7`='Activa los tres tótems grandes, por favor.' WHERE `ID`=60527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌어요!', `FemaleText_loc4`='祝你好运！', `FemaleText_loc5`='祝你好運!', `FemaleText_loc7`='¡Buena suerte!' WHERE `ID`=60528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='따라오세요. 이 토템들을 대지를 정화하는 데 써야겠어요.', `FemaleText_loc4`='跟着我。我们要用这些图腾来净化大地。', `FemaleText_loc5`='跟著我。我們要用這些圖騰淨化大地。', `FemaleText_loc7`='Sígueme. Purificaremos la tierra con estos tótems.' WHERE `ID`=60529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 이겼다고요? 아싸!', `FemaleText_loc4`='我赢了？耶！', `FemaleText_loc5`='我贏了?耶!', `FemaleText_loc7`='¿Gano yo? ¡Viva!' WHERE `ID`=60530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아마 이 숲 안에 어딘가 계시겠지요?', `FemaleText_loc4`='我猜他就在森林里的某个地方？', `FemaleText_loc5`='我猜他在這森林中的某處?', `FemaleText_loc7`='Supongo que estará en algún lugar de este bosque.' WHERE `ID`=60531;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 그다지 안전해 보이지 않는군요. 아무래도 전 그냥...', `FemaleText_loc4`='那里看起来可不怎么友好啊，或许我应该……', `FemaleText_loc5`='這裡看起來不太友善。也許我應該要...', `FemaleText_loc7`='No parece que sea muy acogedor... Quizás debería...' WHERE `ID`=60532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니! 포기하기에는 너무 멀리 왔어요!', `FemaleText_loc4`='不！我都走了这么远了，我不会放弃的！', `FemaleText_loc5`='不!到這地步了我不能放棄。', `FemaleText_loc7`='¡No! ¡He llegado muy lejos como para rendirme!' WHERE `ID`=60533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무... 무슨 일이죠?!?', `FemaleText_loc4`='出……出什么事了？！', `FemaleText_loc5`='發...發生什麼事了?!?', `FemaleText_loc7`='¿Qué... qué está pasando?' WHERE `ID`=60534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내겐 이런 규칙이 있지. "나보고 잘생겼다고 하면 술은 공짜"', `MaleText_loc4`='我有个规矩：任何人只要管我叫声帅哥，就有免费的啤酒喝。', `MaleText_loc5`='我有項規矩:任何說我帥氣的人都可以得到免費啤酒。', `MaleText_loc7`='Tengo una norma: cualquiera que me llame guapo recibe una cerveza gratis.' WHERE `ID`=60535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계가 윙윙거리며 동작하기 시작합니다! 아래층으로 가십시오!', `MaleText_loc4`='机器开始嗡嗡作响了！到下层去！', `MaleText_loc5`='這台機器啟動了!到下一層去!', `MaleText_loc7`='¡La máquina vuelve a la vida! ¡Baja al nivel inferior!' WHERE `ID`=60536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117506|h[불멸의 어둠]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s施放|cFFFF0000|Hspell:117506|h[不灭之影]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_rogue_envelopingshadows.blp:20|t%s施放|cFFFF0000|Hspell:117506|h[不死黑影]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_rogue_envelopingshadows.blp:20|t¡%s lanza |cFFFF0000|Hspell:117506|h[Sombras imperecederas]|h|r!' WHERE `ID`=60537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s|1이;가; |cFFFF0000|Hspell:117708|h[광기 유발의 함성]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s施放|cFFFF0000|Hspell:117708|h[癫狂之吼]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\warrior_talent_icon_furyintheblood:20|t%s施放|cFFFF0000|Hspell:117708|h[激狂怒吼]|h|r!', `MaleText_loc7`='|TInterfaceIconswarrior_talent_icon_furyintheblood:20|t¡%s lanza |cFFFF0000|Hspell:117708|h[Grito enloquecedor]|h|r!' WHERE `ID`=60538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 모구 기계가 부서집니다! |cFFFF0000|Hspell:116779|h[티탄의 가스]|h|r가 방을 가득 채웁니다!', `MaleText_loc4`='上古魔古机器损坏了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！', `MaleText_loc5`='古代魔古機器崩毀了!|cFFFF0000|Hspell:116779|h[泰坦氣體]|h|r 充滿了整個房間!', `MaleText_loc7`='¡La Antigua Máquina Mogu se rompe! ¡|cFFFF0000|Hspell:116779|h[Gas Titán]|h|r invade la sala!', `FemaleText_loc1`='고대 모구 기계가 부서집니다! |cFFFF0000|Hspell:116779|h[티탄의 가스]|h|r가 방을 가득 채웁니다!', `FemaleText_loc4`='上古魔古机器损坏了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！', `FemaleText_loc5`='古代魔古機器崩毀了!|cFFFF0000|Hspell:116779|h[泰坦氣體]|h|r 充滿了整個房間!', `FemaleText_loc7`='¡La Antigua Máquina Mogu se rompe! ¡|cFFFF0000|Hspell:116779|h[Gas Titán]|h|r invade la sala!' WHERE `ID`=60539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 모구 기계가 폭주합니다! |cFFFF0000|Hspell:116779|h[티탄의 가스]|h|r가 방을 가득 채웁니다!', `MaleText_loc4`='上古魔古机器超载了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！', `MaleText_loc5`='古代魔古機器超載了!|cFFFF0000|Hspell:116779|h[泰坦氣體]|h|r充滿了整個房間!', `MaleText_loc7`='¡La Antigua Máquina Mogu se sobrecarga! ¡|cFFFF0000|Hspell:116779|h[Gas Titán]|h|r invade la sala!', `FemaleText_loc1`='고대 모구 기계가 폭주합니다! |cFFFF0000|Hspell:116779|h[티탄의 가스]|h|r가 방을 가득 채웁니다!', `FemaleText_loc4`='上古魔古机器超载了！|cFFFF0000|Hspell:116779|h[泰坦寒气]|h|r涌入了房间！', `FemaleText_loc5`='古代魔古機器超載了!|cFFFF0000|Hspell:116779|h[泰坦氣體]|h|r充滿了整個房間!', `FemaleText_loc7`='¡La Antigua Máquina Mogu se sobrecarga! ¡|cFFFF0000|Hspell:116779|h[Gas Titán]|h|r invade la sala!' WHERE `ID`=60540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭을 수비하는 건 당신이 아는 것보다도 훨씬 더 중요합니다.$b$b사마귀 놈들이 돌밭을 점령하면, 이 네 바람의 계곡 전체를 점령하는 것과 별다를 바가 없지요. 이 장벽 너머에는 놈들이 판다리아 전역으로 휘몰아치는 것을 막아낼 게 아무것도 없습니다.', `MaleText_loc4`='守卫石犁村的意义或许比你所了解的还重要。$b$b如果螳螂妖拿下了石犁村，他们就能顺势夺下整个谷。越过这道墙后，就没有什么能够阻止他们彻底扫平整个潘达利亚的了。', `MaleText_loc5`='石犁村的防禦比你所想的還要重要。$b$b如果螳螂人拿下石犁村，他們就形同拿下整座峽谷。越過了這面牆，就再也沒有東西能阻止他們橫掃整個潘達利亞。', `MaleText_loc7`='La defensa de Villarroca es más importante de lo que puedas pensar.$b$bSi los mántides toman Villarroca, podrían tomar también todo este valle. Más allá de esta muralla, no hay nada que les impida arrasar toda Pandaria.' WHERE `ID`=60541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 놈들이 공격하고 있지만, 우리는 그에 비하면 부끄러울 정도로 아무런 준비도 돼 있지 않습니다.$b$b일반적인 상황이라면 놈들은 예측하기가 아주 쉽습니다. 100년마다 규칙적으로 그래왔듯이, 놈들의 다음 공격은 약 10년 안에 이뤄질 것이라고 예상했던 거지요.$b$b현재 침공은 총공격이라고 할 정도의 규모는 아니지만, 공격을 예상하지 못했던 농가를 덮치기에는 충분할 만큼 강력합니다. 제 음영파 대원들이 밤새 장벽을 감시하지 않았더라면 돌밭은 벌써 함락당했겠지요.', `MaleText_loc4`='螳螂妖在发动进攻，而我们却毫无防备，真是惭愧。$b$b在一般情况下，我们是能够预测敌人行动的。我们原本预测螳螂妖的下一次大规模入侵应当发生在十年之后，因为他们总是每百年入侵一次。$b$b当前的侵袭虽算不上“大规模”，但还是足以令普通乡村猝不及防。要不是我的影踪派弟子一直在城墙上警戒的话，石犁村恐怕早已陷落了。', `MaleText_loc5`='螳螂人正在來襲，而我們卻可恥地毫無準備。$b$b在一般情況下，我們的敵人很容易預測。按照他們每百年一次的規律，我們原本預期下一次大規模入侵會在大約十年後。$b$b雖然這算不上「大規模」侵略，但對普通農村而言而是應付不了的威脅。要是我們影潘沒有在牆上保持高度警戒，石犁村可能早已陷落了。', `MaleText_loc7`='Los mántides están atacando; es una vergüenza que estemos tan mal preparados.$b$bEn circunstancias normales, nuestro enemigo es bastante predecible. Sabíamos que el siguiente ataque mántide a gran escala sería en unos diez años, ya que suelen hacerlo una vez cada siglo.$b$bEsta invasión no puede considerarse "a gran escala", pero sigue siendo lo bastante fuerte como para pillar desprevenida a una aldea granjera. Si mis Shadopan no hubieran vigilado tan a conciencia la muralla, Villarroca ya habría caído.' WHERE `ID`=60542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 현재 돌밭 수비 임무는 제가 지휘하고 있습니다. 경비대장 오큰쉴드와 다른 셋은 우리 대원입니다. 지금 우리가 대화하는 이 순간에도 그 세 명의 음영파 대원들은 장벽 아래에 서서 사마귀 놈들의 다음 공격을 방어하기 위해 대기 중입니다. 일반 판다렌이라면 그 존재를 자칫 잊어버릴 뻔했던 적들로부터 판다리아를 지켜내는 것은 우리가 해야 할 일입니다.$b$b돌밭에 있는 아군의 수가 적기는 하지만, 쿤라이 봉우리에서 지원군은 절대 오지 않을 겁니다... 상황이 더 악화되지 않는 한 말이지요. 뭐, 예를 들어 장벽 저쪽의 약한 부분이 무너지거나 하는 그런 상황 말입니다.', `MaleText_loc4`='是的，守护石犁村的重任当前由我、守卫队长橡盾和我们派另外三名弟子担负着。正如之前我所说的，那三名影踪派弟子坚守在长城脚下，等待迎接下一波攻势。这是我们的责任——保护潘达利亚免遭普通老百姓所遗忘了的敌人蹂躏。$b$b虽然我们在石犁村的人数捉襟见肘，但我们还不打算向昆莱山请求增援……除非这里的形势变得更糟。说白了，打个比方，如果长城的弱点被攻破了。', `MaleText_loc5`='是的。目前防禦石犁村的責任落在我、守衛隊長橡木盾以及另外三個同僚的身上。就在此刻，那三位影潘已站在長城底下等待著抵禦下一波的攻擊者。這是我們的職責:守護潘達利亞免受大眾早已遺忘的敵人侵略。$b$b儘管我們在石犁村的人數不多，但我們並不期望崑萊派出援軍...除非狀況又變得更糟，譬如長城的那個弱點崩塌了的話。', `MaleText_loc7`='Sí. La defensa de Villarroca me corresponde actualmente a mí, el capitán de la guardia Escudo de Roble y otros tres de nuestra orden. En estos momentos, esos tres Shadopan están aguantando al pie de la muralla, esperando para contener a la siguiente ola de asaltantes. Este es nuestro trabajo: proteger a Pandaria de enemigos que la gente de a pie ya ha olvidado.$b$bAunque somos muy pocos aquí en Villarroca, no esperamos refuerzos de Kun Lai... a menos que esta situación se agrave. Por ejemplo, si ese punto débil de la muralla se desmoronase.' WHERE `ID`=60543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 전, 어두운 기운을 띈 빛줄기 하나가 날카로운 파열음을 내며 우리 망루를 관통했습니다. 그 빛줄기는 서쪽에서 왔고, 거의 벽을 완전히 뚫고 나갈 뻔했습니다.$b$b아직도 그 빛줄기가 남긴 흔적이 거기 있습니다. 그 흔적으로 이 농부들의 땅이 폐허가 되었지요.$b$b그 후 얼마 지나지 않아 사마귀 정찰병이 뒤따라왔습니다. 그게 놈들의 계획된 공격인 건지, 아니면 우연히 그 상황을 포착해 공격하려고 한 건지는 잘 모르겠습니다. 아마도 그 어두운 기운의 빛줄기인지 뭔지 하는 게 처음으로 뻗어나온 곳으로부터 도망치는 중이었을 겁니다.', `MaleText_loc4`='前几天，我在警戒塔上看到地底爆发出一股黑暗能量。它从西面而来，挤压着城墙，几乎把整个墙体撕裂开来。$b$b你现在还能看到它留下的痕迹。它把这些农夫的土地彻底毁了。$b$b后来，螳螂妖斥候也赶来了。我说不准他们到底是有备而来，还是只想趁火打劫。没准他们也是想逃离那个当初震裂大地的东西呢。', `MaleText_loc5`='幾天前，在我輪班看守的時候，我看到一束黑暗的能量從地面竄出。它自西邊而來，把長城擊出裂縫，還差點就要打穿過去了。$b$b你可以看見疤痕還在那兒，它把這些農夫的土地都毀了。$b$b螳螂人斥候隨後出現。我不知道他們是早就有這攻擊計畫或者只是順便利用這個好機會，也有可能他們根本是在躲避那造成裂縫的東西。', `MaleText_loc7`='Hace unos días, vi un destello de energía oscura chisporroteando a través del suelo desde mi torre de vigilancia. Vino desde el oeste, resquebrajó la muralla y casi lo atravesó por completo.$b$bAún se ven las cicatrices. Arruinó la tierra de estos granjeros.$b$bLos exploradores mántides llegaron poco después. No sabría decir si habían programado este ataque o simplemente aprovecharon una oportunidad. Quizá estén huyendo de lo que fuera que haya provocado la grieta.' WHERE `ID`=60544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 일어난 겁니까?', `MaleText_loc4`='发生什么事了？', `MaleText_loc5`='這裡是什麼狀況?', `MaleText_loc7`='¿Qué está pasando aquí?', `FemaleText_loc1`='여기서 무슨 일이 일어난 건가요?', `FemaleText_loc4`='发生什么事了？', `FemaleText_loc5`='這裡是什麼狀況?', `FemaleText_loc7`='¿Qué está pasando aquí?' WHERE `ID`=60545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 말입니까?', `MaleText_loc4`='影踪派？', `MaleText_loc5`='影潘?', `MaleText_loc7`='¿El Shadopan?', `FemaleText_loc1`='음영파 말인가요?', `FemaleText_loc4`='影踪派？', `FemaleText_loc5`='影潘?', `FemaleText_loc7`='¿El Shadopan?' WHERE `ID`=60546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벽에 무슨 일이 일어났다는 얘깁니까?', `MaleText_loc4`='总之，城墙那儿怎么了？', `MaleText_loc5`='長城到底發生了甚麼事?', `MaleText_loc7`='Pero... ¿qué le ha pasado a la muralla?', `FemaleText_loc1`='벽에 무슨 일이 일어났다는 얘긴가요?', `FemaleText_loc4`='总之，城墙那儿怎么了？', `FemaleText_loc5`='長城到底發生了甚麼事?', `FemaleText_loc7`='Pero... ¿qué le ha pasado a la muralla?' WHERE `ID`=60547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='我明白了。', `MaleText_loc5`='我了解。', `MaleText_loc7`='Entiendo.', `FemaleText_loc1`='알겠어요.', `FemaleText_loc4`='我明白了。', `FemaleText_loc5`='我了解。', `FemaleText_loc7`='Entiendo.' WHERE `ID`=60548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 저는 저 벽에서 평생을 보냈습니다. 모든 것을 포기하며 음영파가 된 것은, 지금과 같은 일이 일어나지 않게 하기 위해서였습니다.$b$b저는 실패했습니다.', `MaleText_loc4`='我在那城墙上花费了一生的心血，$n。我放弃所有的一切成为影踪派弟子，只为阻止像这样的事情发生。$b$b我失败了。', `MaleText_loc5`='我花了一生的時間在那道牆上，$n。我拋棄了一切成為影潘，為了阻止這樣的事發生。$b$b我失敗了。', `MaleText_loc7`='Me he pasado toda la vida en ese muro, $n. Renuncié a todo lo que tenía para convertirme en un Shadopan, para evitar que algo así ocurriera.$b$bHe fracasado.' WHERE `ID`=60549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 지금까지 해주신 모든 일에... 깊은 감사를 드립니다.', `MaleText_loc4`='你为我们所做的一切，$n……我们都铭记在心。', `MaleText_loc5`='$n...我們十分感激你所做的一切。', `MaleText_loc7`='Por todo lo que has hecho, $n... tienes nuestra gratitud.' WHERE `ID`=60550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가.', `MaleText_loc4`='你好。', `MaleText_loc5`='哈囉。', `MaleText_loc7`='Hola.' WHERE `ID`=60551;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 물건들 다 보셨어요? 여기 진짜 끝내준다!', `FemaleText_loc4`='你瞧见这些东西了吗？这地方真是太棒了！', `FemaleText_loc5`='你有看到這些東西嗎?這真是個好地方!', `FemaleText_loc7`='¿Estás viendo todo esto? ¡Este lugar es genial!' WHERE `ID`=60552;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='함께 모험하러 나와줘서 고마워요, $n 님.', `FemaleText_loc4`='谢谢你带我一起出来探险，$n。', `FemaleText_loc5`='謝謝你帶我跟你出來一探究竟，$n。', `FemaleText_loc7`='Gracias por llevarme a explorar contigo, $n.' WHERE `ID`=60553;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸 삼촌은 여기를 걸어 다니며 탐험하기는커녕 앉아서 술만 퍼마시고 있다니, 참!', `FemaleText_loc4`='我真不敢相信陈叔宁愿坐在家中喝的酩酊大醉，也不愿出来走走，来这探险！', `FemaleText_loc5`='我不敢相信老陳叔叔寧願坐下喝啤酒也不願四處走走，探索這個地方!', `FemaleText_loc7`='¡No puedo creer que el tío Chen prefiera sentarse a beber cerveza antes que salir a caminar y explorar este lugar!' WHERE `ID`=60554;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸 삼촌과 약속했기 때문이죠!$b$b이보세요. 삼촌이 아무리 바보 같고, 지루하고, 게으른데다가 살만 찐 늙은 판다렌이기는 하지만, 그렇다고 해서 제가 삼촌을 존경하지 않는 건 아니에요. 삼촌이 어떤 문제도 일으키지 말라고 했으니 전 그 말을 어기지는 않을 거예요.$b$b그리고 제가 보니 혼자 알아서 잘하시는 것 같은데요. 뭘 처치하는 데 저 같은 어린 여자애의 도움이 필요하진 않잖아요.', `FemaleText_loc4`='这可是陈叔逼我保证不这么做的！$b$b听着，陈叔或许是一个笨笨的、无聊的、懒散的、肥肥的老叔，但这并不意味着我不尊重他。他叫我不要卷入任何麻烦中，我也一直都是这么做的。$b$b话说回来，你看上去一个人就能搞定了。你不会要一个小姑娘去帮你打打杀杀吧。', `FemaleText_loc5`='因為老陳叔叔逼我承諾不能這麼做!$b$b你聽好了，老陳也許是個愚笨、無聊、懶惰又肥胖的叔叔，但那並不代表我不尊重他。他告訴我別惹上任何麻煩，而我也不打算忽略他說的話。$b$b況且，你似乎自己一個人也過得很好。你不需要一個小女孩幫你殺東殺西的。', `FemaleText_loc7`='¡Porque el tío Chen me hizo prometer que no lo haría!$b$bMira, puede que Chen sea un tío viejo, gordo, vago, aburrido y estúpido, pero eso no quiere decir que no le respete. Me dijo que no me metiera en problemas y pienso hacerle caso.$b$bAdemás, parece que tú te las arreglas muy bien por tu cuenta. No necesitas a una chiquilla para ayudarte a matar cosas.' WHERE `ID`=60555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 저와 함께 싸우지 않습니까?', `MaleText_loc4`='你为什么不过来帮把手啊？', `MaleText_loc5`='為什麼你沒在幫我戰鬥?', `MaleText_loc7`='¿Por qué no me estás ayudando a pelear?', `FemaleText_loc1`='왜 저와 함께 싸우지 않나요?', `FemaleText_loc4`='你为什么不过来帮把手啊？', `FemaleText_loc5`='為什麼你沒在幫我戰鬥?', `FemaleText_loc7`='¿Por qué no me estás ayudando a pelear?' WHERE `ID`=60556;
