UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이로군;로군;? 의욕이 솟는군.', `MaleText_loc4`='一位$c？非常吸引人。', `MaleText_loc5`='一個$c?真迷人。', `MaleText_loc7`='¿$gUn:Una; $c? Qué interesante.' WHERE `ID`=60561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구, 제가 왔습니다. 함께 샤이 후를 무덤까지 배웅합시다!', `MaleText_loc4`='朋友，我是来帮忙的。让我们把刹嗳呼送进坟墓！', `MaleText_loc5`='朋友，我是來幫忙的。我們會讓夏虎看見自己死期將至!', `MaleText_loc7`='Vengo a ayudar. ¡Shai Hu encontrará su tumba!' WHERE `ID`=60562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 힘을 합쳐 마을 사람들을 중독시킨 자를 물리치러 왔습니다!', `MaleText_loc4`='我是来帮你消灭毒害我族人的祸害的！', `MaleText_loc5`='我來這裡幫你打敗毒害我族人的人!', `MaleText_loc7`='¡Estoy aquí para ayudarte a derrotar al envenenador de mi pueblo!' WHERE `ID`=60563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 샤이 후를 물리칩시다!', `MaleText_loc4`='我们将合力粉碎刹嗳呼！', `MaleText_loc5`='我們會一起毀滅夏虎!', `MaleText_loc7`='¡Juntos aplastaremos a Shai Hu!' WHERE `ID`=60564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 놈들은 죽을 때 폭발합니다... 좋은 수가 생각났습니다! 놈들을 샤이 후 근처에서 죽입시다!', `MaleText_loc4`='这些怪物死时会爆炸……我知道了，我们可以在刹嗳呼身边杀死它们！', `MaleText_loc5`='這些生物死的時候會爆炸...我知道了，到夏虎附近殺死他們!', `MaleText_loc7`='Estas criaturas explotan al morir... ¡Ya sé, mátalas cerca de Shai Hu!' WHERE `ID`=60565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 놈들이 죽을 때 우리도 다치지만, 샤이 후도 다칠 겁니다! 놈들을 샤이 후에게 가까운 곳으로 데려오십시오!', `MaleText_loc4`='嗷！它们死掉时炸伤了我们，不过它们也会伤害到他的！把它们弄到他身边去！', `MaleText_loc5`='噢!他們死時會讓我們受傷，但他們也會傷害夏虎!把這些生物帶到夏虎旁邊!', `MaleText_loc7`='¡Au! ¡Nos hacen daño al morir, pero a él también se lo harán! ¡Acércalas a él!' WHERE `ID`=60567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조화의 토템이 또 필요합니다.', `MaleText_loc4`='我还要一个祥和图腾。', `MaleText_loc5`='我需要另一個和諧圖騰。', `MaleText_loc7`='Necesito otro tótem de armonía.', `FemaleText_loc1`='조화의 토템이 또 필요해요.', `FemaleText_loc4`='我还要一个祥和图腾。', `FemaleText_loc5`='我需要另一個和諧圖騰。', `FemaleText_loc7`='Necesito otro tótem de armonía.' WHERE `ID`=60568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 내가 뭐에 홀린 건가?', `MaleText_loc4`='我——我出什么事了？', `MaleText_loc5`='這，這是什麼感覺?', `MaleText_loc7`='¿Qué... qué fue lo que me invadió?', `FemaleText_loc1`='내... 내가 뭐에 홀린 건가?', `FemaleText_loc4`='我——我出什么事了？', `FemaleText_loc5`='這，這是什麼感覺?', `FemaleText_loc7`='¿Qué... qué fue lo que me invadió?' WHERE `ID`=60569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 큰 증오가... 느껴졌어요...', `MaleText_loc4`='我感觉……满腔愤恨……', `MaleText_loc5`='我覺得...好恨啊...', `MaleText_loc7`='Sentía... tanto odio.', `FemaleText_loc1`='아주 큰 증오가... 느껴졌어요...', `FemaleText_loc4`='我感觉……满腔愤恨……', `FemaleText_loc5`='我覺得...好恨啊...', `FemaleText_loc7`='Sentía... tanto odio.' WHERE `ID`=60570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 끔찍한 짐을 덜어 주셔서 감사합니다.', `MaleText_loc4`='谢谢你把我从那种可怕的梦魇中解救出来。', `MaleText_loc5`='謝謝你將我從那可怕的重擔中解救出來。', `MaleText_loc7`='Gracias por liberarme de esa terrible carga.', `FemaleText_loc1`='그 끔찍한 짐을 덜어 주셔서 고마워요.', `FemaleText_loc4`='谢谢你把我从那种可怕的梦魇中解救出来。', `FemaleText_loc5`='謝謝你將我從那可怕的重擔中解救出來。', `FemaleText_loc7`='Gracias por liberarme de esa terrible carga.' WHERE `ID`=60571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지? 갑자기... 마음이 편안해지는걸...', `MaleText_loc4`='怎么了？我突然感到内心十分祥和……', `MaleText_loc5`='什麼?我突然覺得好平靜...', `MaleText_loc7`='¿Qué? De repente me siento en paz...', `FemaleText_loc1`='뭐지? 갑자기... 마음이 편안해지는걸...', `FemaleText_loc4`='怎么了？我突然感到内心十分祥和……', `FemaleText_loc5`='什麼?我突然覺得好平靜...', `FemaleText_loc7`='¿Qué? De repente me siento en paz...' WHERE `ID`=60572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 혼자 힘으로는 샤의 손아귀에서 벗어나지 못했을 겁니다.', `MaleText_loc4`='谢谢你，朋友。我不可能自己摆脱煞魔的控制。', `MaleText_loc5`='謝謝你，朋友。我無法靠自己從煞的掌握中掙脫出來。', `MaleText_loc7`='Gracias, $gamigo:amiga;. Necesitaba que alguien me ayudase a escapar de las garras del sha.', `FemaleText_loc1`='고마워요. 혼자 힘으로는 샤의 손아귀에서 벗어나지 못했을 거예요.', `FemaleText_loc4`='谢谢你，朋友。我不可能自己摆脱煞魔的控制。', `FemaleText_loc5`='謝謝你，朋友。我無法靠自己從煞的掌握中掙脫出來。', `FemaleText_loc7`='Gracias, $gamigo:amiga;. Necesitaba que alguien me ayudase a escapar de las garras del sha.' WHERE `ID`=60573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤... 때문이었습니까? 모두를 갈기갈기 찢어 버리고 싶은 마음이 들더군요!', `MaleText_loc4`='那是……煞魔吗？我刚才真想把所有人都撕成碎片！', `MaleText_loc5`='那...那是煞的影響嗎?我想把每個人都撕成碎片!', `MaleText_loc7`='¿Eso era... el sha? ¡Quería hacer pedazos a todo el mundo!', `FemaleText_loc1`='샤... 때문이었나요? 모두를 갈기갈기 찢어 버리고 싶은 마음이 들었어요!', `FemaleText_loc4`='那是……煞魔吗？我刚才真想把所有人都撕成碎片！', `FemaleText_loc5`='那...那是煞的影響嗎?我想把每個人都撕成碎片!', `FemaleText_loc7`='¿Eso era... el sha? ¡Quería hacer pedazos a todo el mundo!' WHERE `ID`=60574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 무슨 일이 있었던 거죠? 마음이 한결 가벼워졌네요.', `MaleText_loc4`='我……出什么事了？我现在感觉平静多了。', `MaleText_loc5`='我...發生什麼事了?我現在覺得冷靜多了。', `MaleText_loc7`='Yo... ¿Qué ha pasado? Siento una enorme tranquilidad.', `FemaleText_loc1`='내가... 무슨 일이 있었던 거죠? 마음이 한결 가벼워졌네요.', `FemaleText_loc4`='我……出什么事了？我现在感觉平静多了。', `FemaleText_loc5`='我...發生什麼事了?我現在覺得冷靜多了。', `FemaleText_loc7`='Yo... ¿Qué ha pasado? Siento una enorme tranquilidad.' WHERE `ID`=60575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 샤에게 홀려 있었단 말입니까? 지금까지 그런 줄도 몰랐네요...', `MaleText_loc4`='我被煞魔控制了？我到现在才反应过来……', `MaleText_loc5`='煞掌控我了嗎?我到現在才知道...', `MaleText_loc7`='¿Estaba en las garras del sha? No me había percatado de ello hasta ahora...', `FemaleText_loc1`='내가 샤에게 홀려 있었단 말이에요? 지금까지 그런 줄도 몰랐네요...', `FemaleText_loc4`='我被煞魔控制了？我到现在才反应过来……', `FemaleText_loc5`='煞掌控我了嗎?我到現在才知道...', `FemaleText_loc7`='¿Estaba en las garras del sha? No me había percatado de ello hasta ahora...' WHERE `ID`=60576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 양조장의 일은 그렇게 된 거란다.', `MaleText_loc4`='……这就是我在酿酒厂的遭遇。', `MaleText_loc5`='...那就是酒坊裡所發生的一切。', `MaleText_loc7`='…y eso es lo que pasó en la cervecería.' WHERE `ID`=60577;
