UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.', `MaleText_loc4`='欢迎你，燧焰。这里的人民想念你的温暖。', `MaleText_loc5`='歡迎，火靈。大家非常懷念你的溫暖。', `MaleText_loc7`='Bienvenido, Huo. El pueblo echaba de menos tu calidez.' WHERE `ID`=60608;
