UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서라, 타우렌. 다시 사슬로 묶어 버리기 전에.', `FemaleText_loc4`='放下武器，牛头人，不然我就再把你铐上。', `FemaleText_loc5`='退下，牛頭人。否則我把你捆回鍊子上。', `FemaleText_loc7`='Tauren, retírate antes de que te vuelva a encadenar.' WHERE `ID`=60623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난파선에 아직 선원이 있다! 사람을 보내 부상병을 돌보게 하라!', `FemaleText_loc4`='还有人在船骸里！多派些人去救出那些伤员。', `FemaleText_loc5`='船骸裡還有我們的人!找更多人來照料傷患。', `FemaleText_loc7`='¡Aún hay marineros en los restos! Envíen refuerzos para rescatarlos.' WHERE `ID`=60624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='막사에 치유사가 더 필요하다. 서쪽의 사제들을 불러들여라.', `FemaleText_loc4`='去西边叫些牧师回来，营地需要更多治疗者。', `FemaleText_loc5`='帳篷需要更多治療師。把牧師從西邊召回來。', `FemaleText_loc7`='Necesitamos más sanadores en las tiendas. Traigan sacerdotes de la zona oeste.' WHERE `ID`=60625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽이야! 도움이 필요해!', `MaleText_loc4`='快来这儿，$p！帮帮我们！', `MaleText_loc5`='在這裡，$p!快來幫忙!', `MaleText_loc7`='¡Aquí, $p! ¡Necesitamos ayuda!' WHERE `ID`=60626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 걸 잃을 뻔했지만, 결국은 해냈군요. 셴진 수는 괜찮을 겁니다.', `FemaleText_loc4`='我们孤注一掷，但成功了。神真子会好起来的。', `FemaleText_loc5`='我們冒了很大的風險，好在成功了。神真子不會有事了。', `FemaleText_loc7`='Hemos arriesgado mucho, pero lo hemos conseguido. Shen-zin Su se repondrá.' WHERE `ID`=60627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샹 시 사부님, 얼라이언스가 돌아갈 때 저도 동행하고자 합니다.', `FemaleText_loc4`='尚喜师父，我想要加入联盟，一起返回他们的故乡。', `FemaleText_loc5`='尚羲大師，我想陪聯盟回到他們的家。', `FemaleText_loc7`='Maestro Shang Xi, me gustaría acompañar a la Alianza cuando partan.' WHERE `ID`=60628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 어떤가, 지? 호드와 함께 그들의 땅으로 가겠나?', `MaleText_loc4`='季，你呢？你想加入部落，和他们一起回去吗？', `MaleText_loc5`='你呢，紀?你會跟部落的人們一起回去嗎?', `MaleText_loc7`='¿Y tú, Ji? ¿Te unirás a la Horda en tu viaje de regreso?' WHERE `ID`=60629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 그게 좋을 거 같네요. 지금까지는 호드가 마음에 들고, 제 힘이 그 세상에 도움이 될 거 같거든요.', `MaleText_loc4`='是的……也许那样最好。我喜欢他们，而且我想我能在他们那边大展身手。', `MaleText_loc5`='嗯...或許這樣最好。以目前看到的來說，我喜歡他們，而且聽起來我在那裡會有些用處。', `MaleText_loc7`='Sí... probablemente sea lo mejor. Me han causado buena impresión y creo que podría ser de ayuda en su mundo.' WHERE `ID`=60630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 어떤가, 젊은 제자여? 어디로 갈 텐가?', `MaleText_loc4`='至于你，我年轻的徒儿，你将去往何处？', `MaleText_loc5`='還有你呢，我年輕的徒弟?你有什麼打算?', `MaleText_loc7`='¿Y qué hay de ti, joven estudiante? ¿Adónde irás?' WHERE `ID`=60631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들 모두 셴진 수를 구하는 데 큰 몫을 했네. 자네들이 정말 자랑스럽네.', `MaleText_loc4`='你拯救了神真子，成就了一番伟大的事业。我们所有人都为你骄傲。', `MaleText_loc5`='你們完成了一項偉大的任務，拯救了神真子。我們為你們感到驕傲。', `MaleText_loc7`='Salvar a Shen-zin Su ha sido una gran hazaña. Todos nos sentimos orgullosos.' WHERE `ID`=60632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들의 여정은 아직 끝나지 않은 것 같네. 우리 새 동지들의 고향인 부서진 세상에 우리의 도움이 필요할 터.', `MaleText_loc4`='你的旅程还没有结束。我们的新盟友来自一个破碎的世界，你的能力可以帮助他们。', `MaleText_loc5`='看來你們的旅程還沒有結束。這些新盟友來自一個急需我們幫助的破碎世界。', `MaleText_loc7`='Parece que tus aventuras no terminan aquí. Estos nuevos aliados vienen de un mundo en ruinas y necesitan nuestra ayuda.' WHERE `ID`=60633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가문에 전해 내려오는 봉 맛을 보여 드리죠!', `MaleText_loc4`='是时候感受下棘杖家族的愤怒了！', `MaleText_loc5`='來面對傳家寶杖之怒吧!', `MaleText_loc7`='¡Es el momento de enfrentarse a la ira de la vara familiar!' WHERE `ID`=60634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투로 본 쿠로스!', `MaleText_loc4`='Turo von Kuros！', `MaleText_loc5`='圖洛，馮，庫洛斯!', `MaleText_loc7`='¡Turo von Kuros!' WHERE `ID`=60635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼리마스테!', `MaleText_loc4`='Kalimaste！', `MaleText_loc5`='卡利馬斯!', `MaleText_loc7`='¡Kalimaste!' WHERE `ID`=60636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고쿠라이!', `MaleText_loc4`='Gokku-lai！', `MaleText_loc5`='苟庫拉!', `MaleText_loc7`='¡Gokku-lai!' WHERE `ID`=60637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로칼...', `MaleText_loc4`='Lo-kal……', `MaleText_loc5`='洛庫。', `MaleText_loc7`='¡Lo-kal...' WHERE `ID`=60638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 한 번 싸워 보는군요, $p!', `MaleText_loc4`='终于，$p，我们要在战斗中一决高下了！', `MaleText_loc5`='$p，我們總算能在戰鬥中交手了。', `MaleText_loc7`='¡Por fin nos encontramos cara a cara, $p!' WHERE `ID`=60639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우, 제법 아팠어요! 잘 싸웠어요, 친구.', `MaleText_loc4`='哟，还挺疼！打得不错，朋友。', `MaleText_loc5`='哇喔，那好痛耶!打得好，朋友。', `MaleText_loc7`='¡Vaya, eso duele! Bien luchado.' WHERE `ID`=60640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브램블스태프한테 질 각오가 된 사람 있으면 나와 봐!', `MaleText_loc4`='你们之中谁准备好臣服在棘杖门下了？', `MaleText_loc5`='你們當中有誰準備好要輸給藤杖啦?', `MaleText_loc7`='¿Quién de ustedes está preparado para la derrota ante Vara Enzarzada?' WHERE `ID`=60641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반이 날 죽이라고 보냈느냐? 내 남편을 죽인 것처럼?', `FemaleText_loc4`='这么说，是班派你来杀我的？就像他杀死我丈夫那样？', `FemaleText_loc5`='所以，班派你來殺我嗎?就像他殺了我丈夫一樣?', `FemaleText_loc7`='¿Ban los ha enviado a matarme? ¿Igual que mató a mi marido?' WHERE `ID`=60643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너의 한심한 의식은 아무 의미가 없다! 날 구원하려 들지 마!', `FemaleText_loc4`='你那可怜的仪式毫无意义！我回不了头了！', `FemaleText_loc5`='你可悲的儀式毫無意義!救不了我的!', `FemaleText_loc7`='¡Sus estúpidos rituales son inútiles! ¡No pueden salvarme!' WHERE `ID`=60644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='증오가 내게 널 처치할 힘을 준다!', `FemaleText_loc4`='仇恨给了我足以毁灭你的力量！', `FemaleText_loc5`='仇恨給予我摧毀你的力量!', `FemaleText_loc7`='¡El odio me da la fuerza que necesito para destruirlos!' WHERE `ID`=60645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 증오에... 눈이... 멀었었군요. 반에게... 모두 용서한다고... 전해줘요.', `FemaleText_loc4`='我明白了……仇恨……吞噬了我。告诉班……我……原谅他了。', `FemaleText_loc5`='現在我明白了...我的仇恨...吞噬了我。告訴班...我已...原諒一切。', `FemaleText_loc7`='Ahora lo veo... el odio... me ha consumido. Díganle a Ban... que lo perdono.' WHERE `ID`=60646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우하하하하... 이 불쌍한 애송이들!', `MaleText_loc4`='啊哈哈哈……可怜的爬虫！', `MaleText_loc5`='哈哈哈...你們這群可悲的弱者!', `MaleText_loc7`='Ja, ja, ja... ¡patéticas alimañas!' WHERE `ID`=60647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들의 가장 강력한 용사들도 이 칼바람을 버텨내진 못했다.', `MaleText_loc4`='就连最强大的战士，也像待宰羔羊瑟瑟发抖。', `MaleText_loc5`='就連你們最強的戰士也像待宰羔羊一樣不堪一擊。', `MaleText_loc7`='Hasta sus guerreros más fuertes sucumben como corderos en el matadero.' WHERE `ID`=60648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 너희 차례가 온다. 온 세상이 불탈 때까지, 증오가 분쟁을 불러오리라!', `MaleText_loc4`='马上就轮到你们了。仇恨，将让你们自相残杀，并将整个世界燃尽！', `MaleText_loc5`='總有一天輪到你們。仇恨會讓你們背叛彼此，直到整個世界陷入火海!', `MaleText_loc7`='Ya llegará su turno. El odio los hará enfrentarse entre ustedes hasta que reduzcan este mundo a cenizas.' WHERE `ID`=60649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항복할게요! 당신이 이겼어요.', `FemaleText_loc4`='我投降！你赢了。', `FemaleText_loc5`='我投降!你贏了。', `FemaleText_loc7`='¡Me rindo! Tú ganas.' WHERE `ID`=60650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그루멀과 맥주 마시기 시합을 하는 것보다 더 쉽겠는걸.', `FemaleText_loc4`='这可比和一个土地精拼酒容易多了。', `FemaleText_loc5`='這會比跟咕嚕摩比賽喝酒還要容易。', `FemaleText_loc7`='Esto va a ser más fácil que un duelo de cervezas con un grúmel.' WHERE `ID`=60651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사를 선택하십시오.', `FemaleText_loc4`='选择你的勇士。', `FemaleText_loc5`='選擇你的勇士。', `FemaleText_loc7`='Elige a tu campeón.' WHERE `ID`=60652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 너희 같은 놈들에게 지다니! 잔달라 사제로서 부끄럽기 짝이 없군!', `MaleText_loc4`='呸！被你这种人打败！对赞达拉祭司来说简直是耻辱。', `MaleText_loc5`='哼!被你這種人擊敗!對贊達拉的祭司來說真是丟臉。', `MaleText_loc7`='¡Bah! ¡Vencido por escoria como ustedes! ¡Qué vergüenza para un sacerdote Zandalari!' WHERE `ID`=60653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 상관없어. 장신구를 가져가라. 필요할 테니까.', `MaleText_loc4`='……但这也没什么。拿上战利品，当心你们的小命。', `MaleText_loc5`='...不過也算不了什麼。帶走那些玩意兒吧，你會用得上的。', `MaleText_loc7`='Pero no pasa nada. Tomen sus baratijas; les harán falta.' WHERE `ID`=60654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가야겠다. 내 영혼이 머물 새집으로.', `MaleText_loc4`='我走了。该为我的灵魂找个新家了。', `MaleText_loc5`='我該走了，去替我的靈魂找個新家。', `MaleText_loc7`='Ahora me voy. Es hora de buscar un nuevo hogar para mi alma.' WHERE `ID`=60655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음은 문, 시간은 창이 되리라. 난 다시 돌아온다! 으흐흐하하하하하하!', `MaleText_loc4`='死亡是扇门，而时间是扇窗。我会回来的！啊哈哈哈哈哈哈！', `MaleText_loc5`='死亡是門，時間是窗，我會回來的!啊哈哈哈哈哈!', `MaleText_loc7`='La muerte es una puerta, y el tiempo una ventana. ¡Volveré! ¡JAJAJAJAJAJA!' WHERE `ID`=60656;
