UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 기계가 고장나기 시작합니다! 모든 모구 조형체가 |cffFF0000|Hspell:118041|h[과충전]|h|r 상태가 됩니다!', `MaleText_loc4`='上古机器发生故障了！所有部件都发生了|cffFF0000|Hspell:118041|h[超载]|h|r！', `MaleText_loc5`='這台古代機器故障了!所有的結構都|cffFF0000|Hspell:118041|h[超載]|h|r了!', `MaleText_loc7`='¡La antigua máquina pierde el control! ¡Todos los ensamblajes se |cffFF0000|Hspell:118041|h[sobrecargan]|h|r!', `FemaleText_loc1`='고대 기계가 고장나기 시작합니다! 모든 모구 조형체가 |cffFF0000|Hspell:118041|h[과충전]|h|r 상태가 됩니다!', `FemaleText_loc4`='上古机器发生故障了！所有部件都发生了|cffFF0000|Hspell:118041|h[超载]|h|r！', `FemaleText_loc5`='這台古代機器故障了!所有的結構都|cffFF0000|Hspell:118041|h[超載]|h|r了!', `FemaleText_loc7`='¡La antigua máquina pierde el control! ¡Todos los ensamblajes se |cffFF0000|Hspell:118041|h[sobrecargan]|h|r!' WHERE `ID`=60670;
