UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 어떤 존재를 일깨웠는지 너는 모른다!', `MaleText_loc4`='你根本不明白自己放出了什么！', `MaleText_loc5`='你不知道自己釋放了什麼!', `MaleText_loc7`='¡No sois conscientes de lo que habéis liberado!' WHERE `ID`=60672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기계는 당신을 파멸시킬 겁니다. 임시', `MaleText_loc4`='这机器会彻底毁灭你。PH', `MaleText_loc5`='那機器會是你們的末日。', `MaleText_loc7`='Esta máquina será vuestro final. PH' WHERE `ID`=60673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 벌써 왔는가? 나는 아직 준비가 덜 됐다네... 자네도 그렇고.$B$B세 제단에서 예배를 드린 후에 다시 오게. 우리가 급하다고 해서 산에 불경을 저질러서는 안 되네.', `MaleText_loc4`='啊，你已经到了？我这边还没准备好呢……你也是。$B$B先去祭拜神龛，回头再来找我吧——我们不该匆匆忙忙，这样显得对大山不敬。', `MaleText_loc5`='啊，你已經到了啊?我還沒完成我的準備工作...而且你也是。$B$B向神壇行禮之後再回來找我，我們不能因為匆忙而對高山有所不敬。', `MaleText_loc7`='¿Oh, ya estás aquí? Todavía no he terminado con mis preparativos... y tú tampoco.$B$BHonra los santuarios y vuelve a verme. No debemos faltar al respeto a la montaña con nuestras prisas.' WHERE `ID`=60674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네. 이제 시작할 준비가 됐군.', `MaleText_loc4`='好了，我们已经准备好开始了。', `MaleText_loc5`='好了，我們準備好要開始了。', `MaleText_loc7`='De acuerdo, ya estamos listos para empezar.' WHERE `ID`=60675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 됐다네...', `MaleText_loc4`='差不多好了……', `MaleText_loc5`='就快要完成了...', `MaleText_loc7`='Casi he terminado...' WHERE `ID`=60676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 용감한 $c님.', `MaleText_loc4`='谢谢你，勇敢的$c。', `MaleText_loc5`='謝謝你，勇敢的$c。', `MaleText_loc7`='Gracias, valiente $c.', `FemaleText_loc1`='감사해요, 용감한 $c님.', `FemaleText_loc4`='谢谢你，勇敢的$c。', `FemaleText_loc5`='謝謝你，勇敢的$c。', `FemaleText_loc7`='Gracias, valiente $c.' WHERE `ID`=60677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 당신은 구출됐습니다!', `MaleText_loc4`='[PH]你得救了！', `MaleText_loc5`='[PH]你得救了!', `MaleText_loc7`='[PH] You are saved!', `FemaleText_loc1`='[PH] 당신은 구출됐습니다!', `FemaleText_loc4`='[PH]你得救了！', `FemaleText_loc5`='[PH]你得救了!', `FemaleText_loc7`='[PH] You are saved!' WHERE `ID`=60678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래... 혼자 떠나 버린 게, 쑤나답지 않아서.', `MaleText_loc4`='是啊……孙娜不是会独自逃跑的人。', `MaleText_loc5`='是的...蘇納看來不像是會獨自逃走的人。', `MaleText_loc7`='Sí, bueno... No es propio de Suna irse por su cuenta.' WHERE `ID`=60679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반, 걱정스러워 보여요.', `FemaleText_loc4`='班，你看起来很担心。', `FemaleText_loc5`='班，你看起來很擔心。', `FemaleText_loc7`='Ban, pareces preocupado.' WHERE `ID`=60680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그녀는 남편의 죽음으로 깊은 슬픔에 빠졌을 거예요.', `FemaleText_loc4`='她肯定是对她丈夫的死太伤心了。', `FemaleText_loc5`='她一定是因為丈夫死去而無比悲痛。', `FemaleText_loc7`='Debe de estar desolada por la muerte de su marido.' WHERE `ID`=60681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럴지도요. 하지만 누구의 잘못도 아니에요.', `FemaleText_loc4`='或许吧，但这并不是谁的错。', `FemaleText_loc5`='或許，但這不是任何人的錯。', `FemaleText_loc7`='Es posible, pero nadie tuvo la culpa.' WHERE `ID`=60682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 최선의 행동을 한 거예요. 어떤 지휘관도 미래를 예지하지는 못해요.', `FemaleText_loc4`='你做了你认为最好的选择。没有哪个指挥官能预知未来。', `FemaleText_loc5`='你已經盡力了。沒有任何指揮官能預見未來。', `FemaleText_loc7`='Hiciste lo que consideraste correcto. Ningún comandante puede ver el futuro.' WHERE `ID`=60683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다!', `MaleText_loc4`='非常感谢！', `MaleText_loc5`='非常感謝你!', `MaleText_loc7`='¡Muchas gracias!', `FemaleText_loc1`='정말 고마워요!', `FemaleText_loc4`='非常感谢！', `FemaleText_loc5`='非常感謝你!', `FemaleText_loc7`='¡Muchas gracias!' WHERE `ID`=60684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 우리와 함께 음영파의 피의 맹세를 하지 않았나요? 증오보다 더욱 강한 힘으로 하나가 된 거예요.', `FemaleText_loc4`='你们曾立下过影踪派的血誓，不是吗？比仇恨更强大的力量会将你们团结在一起。', `FemaleText_loc5`='你也一起立下了影潘的血誓，不是嗎?將你和我們緊密聯繫在一起的力量，遠大於仇恨的力量。', `FemaleText_loc7`='¿Tomaron juramento al Shadopan juntos, no es verdad? Los unen poderes mucho más fuertes que el odio.' WHERE `ID`=60685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아뇨, 안 미워해요. 그렇대도 결국엔 풀릴 걸요.', `FemaleText_loc4`='不，她不会恨你的。至少不会一直如此。呵呵呵！', `FemaleText_loc5`='不，她不會恨你。至少不會永遠恨你。哈哈哈哈!', `FemaleText_loc7`='No, no puede odiarte. Al menos, no eternamente. ¡Ja, ja, ja!' WHERE `ID`=60686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으, 이 악취는 뭐죠?', `FemaleText_loc4`='呃，这是什么臭味？', `FemaleText_loc5`='嗚噁，那是什麼臭味?', `FemaleText_loc7`='Puaj, ¿qué es esa peste?' WHERE `ID`=60687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 냄새가 정말 지독하다고요!', `FemaleText_loc4`='可这里散发着死亡的恶臭！', `FemaleText_loc5`='但這地方散發死亡的氣味!', `FemaleText_loc7`='¡Pero este lugar apesta a muerte!' WHERE `ID`=60688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 원망하더군.', `MaleText_loc4`='我知道，她在怪我。', `MaleText_loc5`='她在怪我，你知道的。', `MaleText_loc7`='Me culpa a mí, ¿sabes?' WHERE `ID`=60689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험을 감수하고라도 공격 명령을 내렸어야 했어.', `MaleText_loc4`='我应该冒一次险，让部队出击的。', `MaleText_loc5`='我應該冒險下令攻擊的才對。', `MaleText_loc7`='Debería haber aceptado el riesgo y dado la orden de ataque.' WHERE `ID`=60690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데... 이제 쑤나는 날 미워해.', `MaleText_loc4`='可现在……她肯定很恨我。', `MaleText_loc5`='但現在...她恨死我了。', `MaleText_loc7`='Pero ahora... me odia.' WHERE `ID`=60691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 좋겠어, 야리아.', `MaleText_loc4`='但愿如此。', `MaleText_loc5`='但願如此，雅里亞。', `MaleText_loc7`='Eso espero, Yalia.' WHERE `ID`=60692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 조용하군. 확인해 봐야겠어.', `MaleText_loc4`='这里太安静了。我们得调查一下。', `MaleText_loc5`='太安靜了。我們該去查看一下。', `MaleText_loc7`='Hay demasiado silencio. Deberíamos investigar.' WHERE `ID`=60693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 멈춘다. 모두 내려!', `MaleText_loc4`='全部停下。大家散开！', `MaleText_loc5`='我們在這裡停下來。大家出去!', `MaleText_loc7`='Nos paramos aquí. ¡Todo el mundo fuera!' WHERE `ID`=60694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 쑤나의 흔적이 여기서 끊겼다. 찾기 전엔 떠나지 않겠다.', `MaleText_loc4`='嗯，孙娜的足迹在这儿消失了。找到她之前，我们绝不离开。', `MaleText_loc5`='是的，蘇納的蹤跡從這裡就消失了。在找到她之前我們不會離開。', `MaleText_loc7`='Sí. El rastro de Suna termina aquí. No nos iremos hasta encontrarla.' WHERE `ID`=60695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보십시오! 쑤나 님의 흔적이 저 마을까지 이어집니다.', `MaleText_loc4`='看。孙娜的足迹往前面的村子去了。', `MaleText_loc5`='看!蘇納的蹤跡延伸到前面的村落裡。', `MaleText_loc7`='¡Mira! Las huellas de Suna conducen hasta la aldea.' WHERE `ID`=60696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은... 학살의 현장 같군요.', `MaleText_loc4`='这里看起来就像……屠杀现场。', `MaleText_loc5`='這看起來像是一個...大屠殺的現場。', `MaleText_loc7`='Parece que ha tenido lugar... una masacre.' WHERE `ID`=60697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서요? 저, 정말이십니까?', `MaleText_loc4`='在这里？你……确定吗？', `MaleText_loc5`='在這個地方?你...你確定嗎?', `MaleText_loc7`='¿En este lugar? ¿Estás seguro?' WHERE `ID`=60698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 우낏 이겼다! 그래도 내 뻥 뻥만은 뺏지 마라!', `MaleText_loc4`='哎呀！蠢蛋赢了！别抢走我的轰轰！', `MaleText_loc5`='哎呀!怪怪人贏了。不要拿走我的砰砰就好了!', `MaleText_loc7`='¡Aaaay! ¡Makakus ganan! ¡No lleven bum bums!' WHERE `ID`=60699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐요, 쑤나 님의 물건이에요! 여기서 야영을 하신 모양이에요. 지금은 어디 계신 걸까요?', `MaleText_loc4`='我看见孙娜的东西了！她肯定在这里宿过营。可是她去哪儿了呢？', `MaleText_loc5`='你看，我看見蘇納的東西了!她一定在這裡紮過營。但她在哪兒呢?', `MaleText_loc7`='¡Mira! Estas son las cosas de Suna. Debió de acampar aquí. ¿Pero dónde está?' WHERE `ID`=60700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왠지 마음에 안 드는 곳입니다.', `MaleText_loc4`='我不喜欢这地方的样子。', `MaleText_loc5`='我不喜歡這地方的樣子。', `MaleText_loc7`='No me gusta el aspecto de este sitio.' WHERE `ID`=60701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마... 유령 마을은 아니겠지요?', `MaleText_loc4`='你说，这地方不会……闹鬼……吧？', `MaleText_loc5`='你不認為這地方被...鬼魂佔據了一樣嗎?', `MaleText_loc7`='Tú no crees que este lugar está... maldito, ¿no?' WHERE `ID`=60702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 있었던 건지 알고 싶지 않습니다. 상상만 해도 너무 끔찍해요.', `MaleText_loc4`='我一点都不想知道这里出了什么事。太可怕了，我连想都不敢想。', `MaleText_loc5`='我不想知道這裡發生了什麼事。光用想像的都覺得恐怖。', `MaleText_loc7`='No quiero saber lo que sucedió aquí. El solo hecho de imaginarlo ya es demasiado horrible.' WHERE `ID`=60703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 그렇게 뒤에서 소리 없이 다가오지 마세요!', `MaleText_loc4`='啊！熊吓熊会吓死熊的！', `MaleText_loc5`='嗚啊!不要像這樣鬼鬼祟祟地接近熊貓人!', `MaleText_loc7`='¡Ay! ¡No te acerques a un pandaren así!' WHERE `ID`=60704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑤나 님이 정말 이 근처에 계실까요?', `MaleText_loc4`='孙娜真的会在这个地方嘛？', `MaleText_loc5`='蘇納真的在外面嗎?', `MaleText_loc7`='¿Es cierto que Suna está en algún lugar ahí fuera?' WHERE `ID`=60705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, $r. 여기가 어떤 곳인 것 같습니까?', `MaleText_loc4`='嘿，$r，你对这地方了解多少？', `MaleText_loc5`='嘿，$r，你在這裡做什麼?', `MaleText_loc7`='Eh, $r, ¿qué te parece este lugar?' WHERE `ID`=60706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳은 생전 처음 봅니다. 당신은 본 적 있습니까, $n?', `MaleText_loc4`='我从没见过这样的东西。你呢，$n？', `MaleText_loc5`='我從沒見過像這樣的東西。你見過嗎，$n?', `MaleText_loc7`='Nunca había visto algo así. ¿Y tú, $n?' WHERE `ID`=60707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁먹을 거 없습니다, $r. 우리가 모두를 지킬 테니까요.', `MaleText_loc4`='别害怕，$r。我们会保证所有人的安全的。', `MaleText_loc5`='別害怕，$r。我們會保護每個人的安全。', `MaleText_loc7`='No tengas miedo, $r. Mantendremos a salvo a todo el mundo.' WHERE `ID`=60708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레슬러 때문에 오늘 시합은 재미없겠어.', `MaleText_loc4`='摔跤手要毁掉今天的比赛。', `MaleText_loc5`='摔跤手今天將會摧毀對手。', `MaleText_loc7`='El Luchador va a destrozar a los rivales hoy.' WHERE `ID`=60709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 호젠 녀석이 폭탄 상자를 발견하더니 제가 수도사라도 된 줄 아는 모양이야.', `MaleText_loc4`='显然，一个猢狲找到了一箱炸弹，然后就认为自己是武僧了。', `MaleText_loc5`='顯然一個猴人找到一箱炸彈就以為自己是個武僧了。', `MaleText_loc7`='Al parecer un hozen se ha encontrado una caja de bombas y ahora se cree un monje.' WHERE `ID`=60710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대체 누가 쉬엔 님한테 사우록을 시합에 끼워 주라고 했는지 모르겠단 말야. 힘을 시험하는 거야 좋지만, 이 괴물들은 정말 너무... 사나워.', `MaleText_loc4`='我想知道是谁说服雪怒让蜥蜴人参加比赛的。我喜欢观看力量的对决，但那些生物也太……狂暴了。', `MaleText_loc5`='我很想知道是誰說服雪怒讓薩烏洛克參加比試。我喜歡好好較量彼此的力量，但是那些生物實在...太...暴躁了。', `MaleText_loc7`='Me pregunto quién habrá convencido a Xuen para que deje competir a los saurok. Disfruto mucho con las pruebas de fuerza, pero esas criaturas están tan... furiosas...' WHERE `ID`=60711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 레슬러의 얼굴을 본 적 있어. 진짜라고.', `MaleText_loc4`='你知道，我曾经看见过摔跤手的真面目。真的。', `MaleText_loc5`='你知道，我看過一次摔跤手本來的面目。真的。', `MaleText_loc7`='Un día le vi la cara al Luchador. De verdad.' WHERE `ID`=60712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결속은 잠깐이면 끝나네만, 그동안 나는 무아지경에 빠질 걸세.', `MaleText_loc4`='联结应该只需片刻，但我会完全进入灵魂出窍状态。', `MaleText_loc5`='縛靈儀式應該只需要一點時間，但我的意識會完全深陷在裡面。', `MaleText_loc7`='El vínculo solo me llevará un momento, pero entraré en trance por completo.' WHERE `ID`=60713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤를 봐 주게. 방해하려는 자가 있으면 자네가 처리해 줄 걸로 믿네.', `MaleText_loc4`='保护好我——我相信你能应对任何干扰。', `MaleText_loc5`='掩護我，我相信你能處理任何阻礙。', `MaleText_loc7`='Vigila mi espalda. Confío en que podrás encargarte de cualquier intromisión.' WHERE `ID`=60714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기! 네놈이 내 물건을 가지고 있구나.', `MaleText_loc4`='游学者！你身上有属于我的东西。', `MaleText_loc5`='博學行者!你手上有屬於我的東西。', `MaleText_loc7`='¡EREMITA! Tienes algo que me pertenece.' WHERE `ID`=60715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 위에 숨어 있으면서 네 원소를 부려 흔적을 숨기다니, 머리를 잘 썼군. 그러나 내 기렌들은 여기서도 혀의 존재를 느낄 수 있지.', `MaleText_loc4`='聪明，竟然想到藏在这上面——用元素掩盖踪迹。但我的魁麟猎犬的鼻子灵得很，即便是躲在这儿，也一样会被发现。', `MaleText_loc5`='聰明，躲在那裡，用元素隱藏你的蹤跡。但即使在這兒，我的獵犬還是可以聞到舌頭的氣味。', `MaleText_loc7`='Muy listo escondiéndote aquí, aprovechándote de los elementos para borrar tus huellas. Pero mis canes quilen sienten la Lengua incluso aquí.' WHERE `ID`=60716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 강아지가 우릴 막을 수 있을 것 같으냐? 하!', `MaleText_loc4`='你指望靠这小崽子来阻止我们？哈！', `MaleText_loc5`='你指望這小東西能阻止我們?哈!', `MaleText_loc7`='¿Contabas con que este vástago nos detuviera? ¡Ja!' WHERE `ID`=60717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 됐네. 무슨 일 있었나?', `MaleText_loc4`='都完成了。我错过什么了吗？', `MaleText_loc5`='都完成了。我錯過了什麼嗎?', `MaleText_loc7`='Listo. ¿Me he perdido algo?' WHERE `ID`=60718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네. 오늘이... 자네의 날이네...', `MaleText_loc4`='好吧。今天……是你表现的日子……', `MaleText_loc5`='非常好。今天...算你好運...', `MaleText_loc7`='Muy bien. Hoy... es tu día...' WHERE `ID`=60719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s|1이;가; |cFFF00000|Hspell:117436|h[번개 감옥]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s开始施放|cFFF00000|Hspell:117436|h[闪电囚笼]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s開始施放|cFFF00000|Hspell:117436|h[閃電牢籠]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_staticshock.blp:20|t¡%s empieza a lanzar |cFFF00000|Hspell:117436|h[Prisión de relámpagos]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s|1이;가; |cFFF00000|Hspell:117436|h[번개 감옥]|h|r을 시전하기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s开始施放|cFFF00000|Hspell:117436|h[闪电囚笼]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t%s開始施放|cFFF00000|Hspell:117436|h[閃電牢籠]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_staticshock.blp:20|t¡%s empieza a lanzar |cFFF00000|Hspell:117436|h[Prisión de relámpagos]|h|r!' WHERE `ID`=60720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결속을 계속 진행하십시오, 초.', `MaleText_loc4`='继续进行联结吧，周卓。', `MaleText_loc5`='繼續進行縛靈吧，阿洲。', `MaleText_loc7`='Adelante con el vínculo, Cho.', `FemaleText_loc1`='결속을 계속 진행하세요, 초.', `FemaleText_loc4`='继续进行联结吧，周卓。', `FemaleText_loc5`='繼續進行縛靈吧，阿洲。', `FemaleText_loc7`='Adelante con el vínculo, Cho.' WHERE `ID`=60721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n, 여긴 위험해요. 안전을 위해서 제가 드린 토템을 사용하세요!', `FemaleText_loc4`='$n，外面很危险。为了你自己的安全考虑，一定要使用我给你的图腾！', `FemaleText_loc5`='$n，外頭很危險。使用我給你的圖騰來保護自己的安全!', `FemaleText_loc7`='$n, esto es peligroso. Por tu propia seguridad, utiliza el tótem que te entregué.' WHERE `ID`=60722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 희망으로 데려가 주십시오!', `MaleText_loc4`='送我去地狱咆哮的希望！', `MaleText_loc5`='帶我去地獄吼之望!', `MaleText_loc7`='¡Llévame hasta Esperanza de Grito Infernal!', `FemaleText_loc1`='헬스크림의 희망으로 데려가 주세요!', `FemaleText_loc4`='送我去地狱咆哮的希望！', `FemaleText_loc5`='帶我去地獄吼之望!', `FemaleText_loc7`='¡Llévame hasta Esperanza de Grito Infernal!' WHERE `ID`=60723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수 없군! 전설 속의 모구샨 도서관이야! 이 저장고에서 어떤 지식을 얻을 수 있을지 상상이나 가는가?', `MaleText_loc4`='难以置信！这里是传说中的魔古山藏书馆！你能想象我们可以从这些地宫里发掘出多少秘密吗？', `MaleText_loc5`='真難以置信!這是傳說中的魔古山藏書庫!你能想像我們可以在這棟建築物中學到些什麼嗎?', `MaleText_loc7`='¡Increíble! ¡Es la legendaria Biblioteca Mogu''shan! ¿Eres consciente de todo lo que podríamos aprender de estas cámaras?' WHERE `ID`=60724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 귀한 $n! 복수해 주겠다!', `MaleText_loc4`='我心爱的$n！你会为此付出代价！', `MaleText_loc5`='我寶貴的$n!你會付出代價!', `MaleText_loc7`='¡Mi $gquerido:querida; $n! ¡Pagarás por eso!' WHERE `ID`=60725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 꾸물거리고 있습니까? 조사하러 갑시다!', `MaleText_loc4`='你还在等什么呢？我们快开始调查吧！', `MaleText_loc5`='你還在等什麼?我們去調查吧!', `MaleText_loc7`='¿A qué esperas? ¡A investigar!', `FemaleText_loc1`='뭘 꾸물거리고 있어요? 조사하러 가죠!', `FemaleText_loc4`='你还在等什么呢？我们快开始调查吧！', `FemaleText_loc5`='你還在等什麼?我們去調查吧!', `FemaleText_loc7`='¿A qué esperas? ¡A investigar!' WHERE `ID`=60726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무법천지 상륙지로 데려다 주십시오.', `MaleText_loc4`='请送我去迷航港。', `MaleText_loc5`='帶我到無常海岸去，拜託。', `MaleText_loc7`='Llévame al Desembarco Improvisado.', `FemaleText_loc1`='무법천지 상륙지로 데려다 주세요.', `FemaleText_loc4`='请送我去迷航港。', `FemaleText_loc5`='帶我到無常海岸去，拜託。', `FemaleText_loc7`='Llévame al Desembarco Improvisado.' WHERE `ID`=60727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 보게! 영원한 어둠의 쯔안에 대한 기록이네. 왕국을 공포와 어둠으로 지배했던, 강력한 마술사였지.', `MaleText_loc4`='看这里！永影巫王提安的历史记录于此。他法力无边，曾将整个帝国都笼罩于恐惧与黑暗之中。', `MaleText_loc5`='你看!這是『無窮影』梓安帝的紀年史，他是個強大的巫士，利用恐懼與黑暗掌管王國。', `MaleText_loc7`='¡Mira esto! Es la historia de Zian de la Sombra Infinita, un poderoso hechicero que sembró el terror y la oscuridad en todos los reinos.' WHERE `ID`=60728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 머리를 가져와라!', `MaleText_loc4`='把他们的头给我带来！', `MaleText_loc5`='把他們的頭提來見我!', `MaleText_loc7`='¡Tráeme sus cabezas!' WHERE `ID`=60729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파에게 죽음을! 모든 판다렌에게 죽음을!', `MaleText_loc4`='让影踪派去死吧！让所有的熊猫人都去死吧！', `MaleText_loc5`='影潘去死吧!所有的熊貓人都去死吧!', `MaleText_loc7`='¡Muerte al Shadopan! ¡Muerte a los pandaren!' WHERE `ID`=60730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진하라, 행군하라, 야운골이여! 겁쟁이는 처단할 것이다!', `MaleText_loc4`='野牛人，前进，冲锋！后退者死！', `MaleText_loc5`='前進!向前進軍，揚古們!誰敢逃就死定了!', `MaleText_loc7`='¡Adelante, marchen, yaungol! ¡Los cobardes serán ejecutados!' WHERE `ID`=60731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 뻥 터졌다!', `MaleText_loc4`='蠢蛋被炸飞了！', `MaleText_loc5`='怪怪人被炸了。', `MaleText_loc7`='¡Makakus hacen bum bum!' WHERE `ID`=60732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야츠! 야오! 이 멍청한 것들을 찢어발겨라!', `MaleText_loc4`='涯尺！曜！把这些蠢货撕成碎片！', `MaleText_loc5`='雅琦!姚!把那些蠢材撕成碎片!', `MaleText_loc7`='¡Yachi! ¡Yao! ¡Hagan pedazos a estos necios!' WHERE `ID`=60733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨! 지금입니다! 이야기했던 대로요!', `MaleText_loc4`='现在轮到肯肯了！和我们计划的一样！', `MaleText_loc5`='就是現在，肯·肯!像我們計畫的那樣!', `MaleText_loc7`='¡Ahora, Ken-Ken! ¡Como habíamos planeado!' WHERE `ID`=60734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서 함께 싸우라고 하신 것, 잊지 마십시오.', `MaleText_loc4`='记住，雪怒让我们合作。', `MaleText_loc5`='記住，雪怒叫我們合作。', `MaleText_loc7`='Recuerda, Xuen nos dijo que trabajásemos juntos.' WHERE `ID`=60735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 할 수 있습니다!', `MaleText_loc4`='我们能做到！', `MaleText_loc5`='我們可以辦到的!', `MaleText_loc7`='¡Podemos lograrlo!' WHERE `ID`=60736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 힘을 합치면 이길 수 있습니다.', `MaleText_loc4`='我们合作的话就能赢。', `MaleText_loc5`='只要我們齊心協力就能獲勝。', `MaleText_loc7`='Podemos ganar si trabajamos juntos.' WHERE `ID`=60737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호... 젠... 권... 법!', `MaleText_loc4`='猢……狲！', `MaleText_loc5`='猴...人...!', `MaleText_loc7`='¡HO... ZEN... FU!' WHERE `ID`=60738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨이 알아서 한다!', `MaleText_loc4`='肯肯做到了！', `MaleText_loc5`='肯·肯做得到!', `MaleText_loc7`='¡Ken-Ken tiene esto kontrolado!' WHERE `ID`=60739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웃기지 마라! 컨컨 진위 없어도 이길 수 있다.', `MaleText_loc4`='得了！肯肯才不需要靠锦鱼人帮忙来赢取胜利。', `MaleText_loc5`='哼!肯·肯不需要錦魚人就能贏。', `MaleText_loc7`='¡Bah! Ken-Ken no necesita un jinyu para ganar.' WHERE `ID`=60740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라, 비겁한 촌놈들아! 이 땅은 다시 한 번 온전히 자연의 소유가 된다!', `MaleText_loc4`='跑吧，懦夫！乡巴佬！这片土地将重归自然的怀抱！', `MaleText_loc5`='逃吧，懦弱的村民!這片土地將再度回歸自然!', `MaleText_loc7`='¡Huyan, aldeanos cobardes! ¡Esta tierra vuelve a ser solo de la naturaleza!' WHERE `ID`=60741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수심에 불타는 후이가 녹옥 마을 북쪽에 있는 석공의 집에 나타났습니다. 도전하십시오!', `MaleText_loc4`='仇灰出现在了绿石村北面的工匠区。快去挑战他！', `MaleText_loc5`='復仇之穢出現在綠石村北邊的石匠區裡。挑戰他吧!', `MaleText_loc7`='Hui el Vengativo ha aparecido en el Barrio de Canteros, al norte de la Aldea Verdemar. ¡Ve a desafiarlo!' WHERE `ID`=60742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 우리 용사! 록 록 보고 기합 한 번 넣자!', `MaleText_loc4`='来吧，勇士！冲洛洛来声咆哮！', `MaleText_loc5`='來吧，優勝者!給阿克阿克一聲大吼!', `MaleText_loc7`='¡Vamos! ¡Ruge para Rok Rok!' WHERE `ID`=60743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 안 된다! 오늘은 머핀 그만! 머핀은 결승전 때만 먹는 거다!', `MaleText_loc4`='不！不不不！不能再给你松饼了！结束了才有松饼吃！', `MaleText_loc5`='不!不不不!沒有鬆餅了!鬆餅是我麻吉的!', `MaleText_loc7`='¡No! ¡No, no, no! ¡Se acabaron los bollos para ti! ¡Los bollos no son para los perdedores!' WHERE `ID`=60744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 축하합니다 - 승리했습니다!', `MaleText_loc4`='[PH]恭喜——你获胜了', `MaleText_loc5`='[PH]恭喜你，你是贏家。', `MaleText_loc7`='[PH] CONGRATULATION - YOU ARE WINNER' WHERE `ID`=60745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자여, 힘의 무술 대회에 온 것을 환영한다!', `MaleText_loc4`='挑战者们，欢迎参加我的力量勇者武道会！', `MaleText_loc5`='挑戰者們，歡迎來到我的比武大會!', `MaleText_loc7`='¡Bienvenidos, participantes, a mi Torneo de Fuerza!' WHERE `ID`=60746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목표 달성. *끼릭!*', `MaleText_loc4`='任务目标完成。*点击！*', `MaleText_loc5`='任務目標完成。*點擊!*', `MaleText_loc7`='Objetivo de misión completado. *¡Clic!*' WHERE `ID`=60747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신 바짝 차리세요, $n! 포위당했어요!', `FemaleText_loc4`='小心，$n！我们被包围了！', `FemaleText_loc5`='保持警戒，$n!我們被包圍了!', `FemaleText_loc7`='¡Cuidado, $n! ¡Estamos rodeados!' WHERE `ID`=60748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 샤가 모습을 드러냈군요. 조심하세요!', `FemaleText_loc4`='煞魔总算现身了。小心点！', `FemaleText_loc5`='終於，煞現出它的真面目了。小心!', `FemaleText_loc7`='Por fin el sha ha mostrado su rostro. ¡Ten cuidado!' WHERE `ID`=60749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하지 않으면 증오에 휩쓸릴 거예요.', `FemaleText_loc4`='只要稍有不慎，你就会被自己的仇恨吞噬。', `FemaleText_loc5`='如果你不小心點，你自身的仇恨可能會淹沒你。', `FemaleText_loc7`='Si no tienes cuidado, tu propio odio podría consumirte.' WHERE `ID`=60750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 끝이 아니에요.', `FemaleText_loc4`='我们还没有摆脱困境呢。', `FemaleText_loc5`='我們還沒離開樹林。', `FemaleText_loc7`='Esto aún no ha terminado.' WHERE `ID`=60751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤를 누그러뜨리는 데 성공한 것 같군요... 일단은요.', `FemaleText_loc4`='看来我们压制住了煞魔……但只是暂时的。', `FemaleText_loc5`='看來我們已經設法壓制住煞...目前是這樣。', `FemaleText_loc7`='Parece que hemos vencido al sha... por ahora.' WHERE `ID`=60752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 증오를 억누르다니, 믿을 수 없군요.', `FemaleText_loc4`='我简直不敢相信。你压制住了自己的恨意。', `FemaleText_loc5`='我實在很難相信。你居然能抑制你的仇恨。', `FemaleText_loc7`='Apenas puedo creerlo. Has podido contener tu odio.' WHERE `ID`=60753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옳지! 주먹밥을 먹여 줘!', `MaleText_loc4`='加油，孩子！揍他！', `MaleText_loc5`='上啊小子!賞他一拳!', `MaleText_loc7`='¡Adelante! ¡Libera tu puño!' WHERE `ID`=60754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복이 다 달아나게 흠씬 두들겨 주라고!', `MaleText_loc4`='打跑那个摔跤手的好运！', `MaleText_loc5`='揍到那個摔跤手倒大楣!', `MaleText_loc7`='¡Sacúdele la suerte a golpes a ese Luchador!' WHERE `ID`=60755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석한테 의자를 줘!', `MaleText_loc4`='把椅子给他！', `MaleText_loc5`='把椅子給他!', `MaleText_loc7`='¡Dale con la silla!' WHERE `ID`=60756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 훈련의 끝에 여기 이르렀군요. 형제자매를 실망시켜선 안 돼요!', `MaleText_loc4`='这么多年的训练就是为了今天，我决不能让我的兄弟姐妹们失望！', `MaleText_loc5`='我所受的訓練就是為了此時此刻。我絕不能讓我的師兄弟妹們失望!', `MaleText_loc7`='Mi entrenamiento me ha traído aquí. ¡No puedo decepcionar a mis hermanos y hermanas!' WHERE `ID`=60757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 샤 때문인가요? 교관들이 이야기해 준 것보다 훨씬 심하네요.', `MaleText_loc4`='这就是煞魔的样子吗？比我的师傅们描述的还要可怕啊。', `MaleText_loc5`='這就是煞嗎?這狀況比我的師父描述的還要糟得多。', `MaleText_loc7`='¿Es esta la presencia del sha? Es mucho peor de lo que me contaron mis instructores.' WHERE `ID`=60758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡히면 안 되네!', `MaleText_loc4`='别让它抓住你！', `MaleText_loc5`='別讓它抓到你!', `MaleText_loc7`='¡No dejes que te agarre!' WHERE `ID`=60759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오른쪽, 왼쪽으로 주먹 날리고, 뛰게!', `MaleText_loc4`='多用左右摆拳，多跑动！', `MaleText_loc5`='多用左右打帶跑!', `MaleText_loc7`='¡Izquierda, derecha, izquierda y corre!' WHERE `ID`=60760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 순찰대원들이 그냥 서로 싸우기 시작했어요.$B$B우리도 그렇게 될 뻔했는데, 야리아 님의 빠른 판단 덕분에 무사한 거예요.', `MaleText_loc4`='其他游侠都开始自相残杀了。$B$B我们也差点跟着发疯。多亏雅丽亚反应够快，我们现在安全了。', `MaleText_loc5`='其他遊俠就這樣開始互相殘殺。$B$B我們本來也會這樣，多虧雅里亞腦筋動得快，我們才能安全。', `MaleText_loc7`='El resto de los forestales comenzó a atacarse entre sí.$B$BNosotros también lo habríamos hecho; estamos a salvo gracias a que Yalia piensa rápido.' WHERE `ID`=60761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 샤에게 물들지 않게 마음을 다잡는 법을 배우지만, 샤가 생각보다 강하네요.', `MaleText_loc4`='我们都受过抵抗煞魔影响的意志强化训练，可这比我们想象的还要厉害。', `MaleText_loc5`='我們都受過訓練，加強心靈力量以對抗煞的影響，但它比我們想的更加強大。', `MaleText_loc7`='Todos hemos recibido entrenamiento para fortalecer nuestras mentes contra la influencia del sha, pero es más poderosa de lo que creíamos.' WHERE `ID`=60762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤와의 첫 싸움에서 살아남았네요. 생각보다 훨씬 무서웠어요.', `MaleText_loc4`='好吧，我在和煞魔的首次交锋中幸存了下来。那比我想象的还要吓人。', `MaleText_loc5`='好吧，在與煞的第一次相遇中我存活下來了。這比我預期的還要可怕。', `MaleText_loc7`='Bueno, he sobrevivido a mi primer encuentro con el sha. Ha sido más terrible de lo que esperaba.' WHERE `ID`=60763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 샤와 대적할 때는, 만반의 준비를 갖춘 상태일 거예요.', `MaleText_loc4`='我下次面对煞魔时，会做好准备的。', `MaleText_loc5`='下次面對煞時，我會做好準備。', `MaleText_loc7`='La próxima vez que me enfrente al sha no me faltará preparación.' WHERE `ID`=60764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘한다, 우리 복덩이 $pc!', `MaleText_loc4`='上，上，$pc幸运符！', `MaleText_loc5`='上啊上啊$pc幸運星!', `MaleText_loc7`='¡Vamos, vamos grisgrís de $pc!' WHERE `ID`=60765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 우리를 덮쳤어요. 사상자가 없는 게 다행이지요.', `MaleText_loc4`='煞魔出其不意地控制了我们，幸好没有造成伤亡。', `MaleText_loc5`='煞殺的我們措手不及。幸好，我們沒有人員傷亡。', `MaleText_loc7`='El sha nos cogió por sorpresa. Afortunadamente no hemos sufrido bajas.' WHERE `ID`=60766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 번개 먹고 천둥 쌀 거다!', `MaleText_loc4`='蠢蛋要把闪电和滚雷吃到肚子里去！', `MaleText_loc5`='怪怪人吃我這招閃電和怪咖雷霆!', `MaleText_loc7`='¡Makakus komen rayos y dungan truenos!' WHERE `ID`=60767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런 $pr 우낏 따위 한 방 거리다!', `MaleText_loc4`='你能击败那个$pr蠢蛋！', `MaleText_loc5`='你可以打倒那個$pr怪怪人!', `MaleText_loc7`='¡Derrota a ese makaku $pr!' WHERE `ID`=60768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 우낏한테 받을 빚 있는 것처럼 때려라!', `MaleText_loc4`='痛扁那个蠢蛋，就像讨债一样！', `MaleText_loc5`='痛扁那個怪怪人，就好像他欠你錢一樣!', `MaleText_loc7`='¡Akaba con ese makaku komo si debiera oro!' WHERE `ID`=60769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 $pr 녀석 궁둥이를 갈겨라!', `MaleText_loc4`='干掉$pr那个大坏蛋！', `MaleText_loc5`='抓他個廢渣$pr!', `MaleText_loc7`='¡Dale a ese $pr en el kuku!' WHERE `ID`=60770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아니지! 갈기라고! 그 다음엔 때리고!', `MaleText_loc4`='不不不！打啊！然后猛刺！', `MaleText_loc5`='不不不!先抓!後打!', `MaleText_loc7`='¡No, no, no! ¡Golpe! ¡Y kodazo!' WHERE `ID`=60771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타란과 반은 전략과 병참의 대가예요. 저는 계획하는 것보다는 싸우는 게 좋죠.', `FemaleText_loc4`='踏岚和班都是战略和后勤学大师。相比计划，我更喜欢战斗。', `FemaleText_loc5`='塔蘭與班主控戰略與後勤部隊。我比較喜歡動手，而不是動腦。', `FemaleText_loc7`='Taran y Ban son unos verdaderos maestros de la estrategia y la logística. Yo prefiero luchar a planificar.' WHERE `ID`=60772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 가만히 있는 거지? 공격 명령을 내려야 하는데!', `FemaleText_loc4`='我们为什么还要等下去？他们应该让部队出击！', `FemaleText_loc5`='為什麼我們還要繼續等待?他們應該下令攻擊!', `FemaleText_loc7`='¿Por qué seguimos esperando? ¡Deberían dar ya la orden de atacar!' WHERE `ID`=60773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 남편이 며칠 전에 야운골에게 잡혀 갔어요. 그이가 무사히 돌아오는 걸 보기 전엔 마음을 놓을 수가 없어요.', `FemaleText_loc4`='我丈夫在几天前被野牛人抓走了。在看到他安全归来之前，我一刻都安宁不下来。', `FemaleText_loc5`='我丈夫幾天前被揚古抓走了。在看到他平安回來之前，我絕不罷休。', `FemaleText_loc7`='Mi marido fue capturado por los yaungol hace varios días. No podré descansar hasta que lo vuelva a ver sano y salvo.' WHERE `ID`=60774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽는다고 몰려오는 폭풍이 멎지는 않는다! 천둥왕은 되살아날 것이다!', `MaleText_loc4`='就算我死了，你们也阻止不了即将到来的狂风暴雨！雷电之王必将崛起！', `MaleText_loc5`='我的死無法阻止即將來臨的風暴!雷王將會再起!', `MaleText_loc7`='¡Mi muerte no detendrá esa tormenta que se aproxima! ¡El Rey del Trueno se alzará!' WHERE `ID`=60775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미스, 아뮬렛 찾는 걸 도와주겠니?', `MaleText_loc4`='你能帮我找到护符吗，米师？', `MaleText_loc5`='你能幫忙找找我的護身符「米什」嗎?', `MaleText_loc7`='¿Puedes ayudarme a encontrar mi amuleto, Mishi?', `FemaleText_loc1`='미스, 아뮬렛 찾는 걸 도와주겠니?', `FemaleText_loc4`='你能帮我找到护符吗，米师？', `FemaleText_loc5`='你能幫忙找找我的護身符「米什」嗎?', `FemaleText_loc7`='¿Puedes ayudarme a encontrar mi amuleto, Mishi?' WHERE `ID`=60776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낡은 모자는 최고의 감독이지. 나와 일할 수 있다니 $p 자네는 복덩이구먼.', `MaleText_loc4`='老帽儿是最棒的教练。$p要是听从我的建议，一定会走运的。', `MaleText_loc5`='老帽是最好的教練。$p要聽我的建議才會走好運。', `MaleText_loc7`='El viejo Bombín es el mejor entrenador. $p sería un grisgrís si escuchara mi consejo.' WHERE `ID`=60777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스는 떠날 준비가 된 듯 보입니다.>', `MaleText_loc4`='<米师似乎已经准备离开了。>', `MaleText_loc5`='<米什準備要離開了。>', `MaleText_loc7`='<Mishi parece preparada para marcharse.>' WHERE `ID`=60778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 오셨습니다, $c! 잠시 경치를 즐기고 가십시오!', `FemaleText_loc4`='欢迎，$c！务必要抽出时间欣赏景色啊！', `FemaleText_loc5`='歡迎，$c!別忘了休息一下欣賞風景!', `FemaleText_loc7`='¡Hola, $c! ¡Tómate un descanso y disfruta de las vistas!' WHERE `ID`=60779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 조우친 마을 근처에서 이상한 일은 없었습니까?', `MaleText_loc4`='你注意到在卓金村附近有什么奇怪的事吗？', `MaleText_loc5`='你在驟晴村附近有發現任何不對勁事嗎?', `MaleText_loc7`='¿Has notado algún acontecimiento extraño en la Aldea Zouchin?', `FemaleText_loc1`='혹시 조우친 마을 근처에서 이상한 일은 없었나요?', `FemaleText_loc4`='你注意到在卓金村附近有什么奇怪的事吗？', `FemaleText_loc5`='你在驟晴村附近有發現任何不對勁事嗎?', `FemaleText_loc7`='¿Has notado algún acontecimiento extraño en la Aldea Zouchin?' WHERE `ID`=60780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 아름다운 경치를 보고 나면, 한결 균형 잡힌 시각을 가질 수 있지요.', `MaleText_loc4`='看着这么美丽的风景，一定会让你茅塞顿开。', `MaleText_loc5`='看見這麼美麗的風景讓我對事物有更深的認知。', `MaleText_loc7`='Un paisaje tan bonito te hace ver las cosas con otra perspectiva.' WHERE `ID`=60781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑤나의 위치를 파악할 때까지는 떠나지 않을 겁니다.', `MaleText_loc4`='在找到孙娜之前，我绝不离开。', `MaleText_loc5`='在我們找到蘇納之前，我絕不離開。', `MaleText_loc7`='No me marcharé hasta que encontremos a Suna.' WHERE `ID`=60782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위험을 피하는 건 우리답지 않습니다. 사랑하는 이를 지키기 위해서라면 기꺼이 어둠으로 뛰어들 겁니다.', `MaleText_loc4`='逃避危险绝非我们的本性。为了保护我们所爱的人，我们会毫不犹豫地闯入黑暗之中。', `MaleText_loc5`='逃避危險不是我們的天性。若是為了守護所愛之人，我們會很樂意撲向黑暗。', `MaleText_loc7`='No está en nuestra naturaleza el huir del peligro. Nos adentraremos en la oscuridad sin temor si eso significa proteger a aquellos a los que queremos.' WHERE `ID`=60783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이지 않는 적이야말로 가장 위험한 적이지요.', `MaleText_loc4`='看不见的敌人或许才是最危险的敌人。', `MaleText_loc5`='看不見的敵人或許才是最危險的。', `MaleText_loc7`='Un enemigo al que no has visto es probablemente el más peligroso de todos.' WHERE `ID`=60784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쑤나의 위치를 파악할 때까지는 떠나지 않을 겁니다.', `MaleText_loc4`='在找到孙娜之前，我绝不离开。', `MaleText_loc5`='在我們找到蘇納之前，我絕不離開。', `MaleText_loc7`='No me marcharé hasta que encontremos a Suna.' WHERE `ID`=60785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 걸음도 물러서지 마십시오! 우리는 이곳에서 샤를 몰아내고 말 겁니다!', `MaleText_loc4`='坚守阵地！我们会把煞魔从这里赶出去的！', `MaleText_loc5`='穩住陣腳!我們要把煞從這裡趕出去!', `MaleText_loc7`='¡Aguanten! ¡Echaremos al sha de este lugar!' WHERE `ID`=60786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 사라졌습니다. 악몽도 끝이 났고요.', `MaleText_loc4`='幽灵都离开了。噩梦结束了。', `MaleText_loc5`='邪魂都消失了。噩夢結束了。', `MaleText_loc7`='Los espíritus se han ido. La pesadilla ha terminado.' WHERE `ID`=60787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 시체에서... 색이 빠져나갔습니다.', `MaleText_loc4`='它刚……死去不久。', `MaleText_loc5`='顏色就這樣...離開了它的軀體。', `MaleText_loc7`='Este cuerpo... ha perdido todo color.' WHERE `ID`=60788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의심의 여지가 없습니다. 이들은 샤에게 물들어 있습니다.', `MaleText_loc4`='这一点毫无疑问，这些生物肯定受到了煞魔的影响。', `MaleText_loc5`='無須懷疑，這些生物已經被煞感染了。', `MaleText_loc7`='No hay ninguna duda. Estas criaturas han sufrido el efecto de los sha.' WHERE `ID`=60789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈 덩치 좀 보십시오! 이놈은 분명 번식력이 있는 수컷입니다.', `MaleText_loc4`='看看它们的体型就知道了！这一定是只成年雄性螳螂妖。', `MaleText_loc5`='看看這個尺寸!這隻一定是繁殖期的雄性。', `MaleText_loc7`='¡Son enormes! Este tiene que ser sin duda el semental.' WHERE `ID`=60790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 사마귀 여왕이 이 일에 어떻게든 관련되어 있을 겁니다.', `MaleText_loc4`='这就是说螳螂妖女皇也牵扯其中……不知何故。', `MaleText_loc5`='這代表螳螂人女皇也參與其中...不知原因為何。', `MaleText_loc7`='Eso quiere decir que la reina mántide está implicada... de alguna manera.' WHERE `ID`=60791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체가 흉터투성이입니다. 오래된 흉터로군요.', `MaleText_loc4`='他的身体——伤痕累累。都是些旧伤。', `MaleText_loc5`='他的屍體上布滿了傷痕，很舊的傷痕。', `MaleText_loc7`='Su cuerpo... Está lleno de cicatrices. Cicatrices antiguas.' WHERE `ID`=60792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그것도 그냥 흉터가 아닙니다. 판다렌의 무기가 남긴 흉터입니다.', `MaleText_loc4`='但也不是一般的伤痕，这些伤痕是熊猫人的武器造成的。', `MaleText_loc5`='這不是一般的傷疤，這是熊貓人的武器造成的傷痕。', `MaleText_loc7`='Y no son cualquier tipo de cicatrices. Son de armas pandaren.' WHERE `ID`=60793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깄습니다! 이게 우리가 찾던 것입니다!', `MaleText_loc4`='在这里！这就是我们一直寻找的东西！', `MaleText_loc5`='這就是了!這就是我們要找的東西!', `MaleText_loc7`='¡Aquí está! ¡Esto es lo que estábamos buscando!' WHERE `ID`=60794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크 털이군요.', `MaleText_loc4`='牦牛毛。', `MaleText_loc5`='犛牛毛髮。', `MaleText_loc7`='Pelo de yak.' WHERE `ID`=60795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 왠지 꺼림칙한 곳이지만, 우리 음영파는 위험을 피하지 않아요.', `MaleText_loc4`='这地方让我感到不安，可我们影踪派是不会逃避危险的。', `MaleText_loc5`='這地方讓我很不安，但我們影潘絕不逃避危險。', `MaleText_loc7`='Este lugar me inquieta, pero los Shadopan no huimos del peligro.' WHERE `ID`=60796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='되찾는 자의 목소리가 들리긴 했네만, 아주 희미했다네... 꿈의 내용을 생각해 내려고 할 때처럼 몽롱했지.$B$B또 자네에게 빚을 진 것 같군.', `MaleText_loc4`='我听到了复兴者的威胁，但模糊不清……稍纵即逝，就好像回忆梦里的细节。$B$B看来我又欠你个人情。', `MaleText_loc5`='我聽說了回收者的威脅，但是很模糊...不夠具體，就像試著拼湊出夢境中的細節一樣。$B$B看來我又欠你一個人情了。', `MaleText_loc7`='He escuchado la amenaza del reivindicador, pero me ha parecido muy débil... Distante, como los detalles de un sueño.$B$BParece que estoy en deuda contigo de nuevo.' WHERE `ID`=60797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모 모 그루멀처럼 복 받았다!', `MaleText_loc4`='墨墨交上土地精的好运气了！', `MaleText_loc5`='莫莫現在有咕嚕摩的運氣!', `MaleText_loc7`='¡Mo Mo tiene ahora la suerte del grúmel!' WHERE `ID`=60798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새나는 우낏한테서 다 빼앗을 거다.', `MaleText_loc4`='臭蠢蛋要遭殃了。', `MaleText_loc5`='臭怪怪人要倒大楣了。', `MaleText_loc7`='Apestosos makakus serán devastados.' WHERE `ID`=60799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모 모 제일 운 좋은 호젠 될 거다!', `MaleText_loc4`='墨墨将会是最幸运的猢狲！', `MaleText_loc5`='莫莫會成為最幸運的猴人!', `MaleText_loc7`='¡Mo Mo será el hozen más afortunado!' WHERE `ID`=60800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 아무것도 없군요. 계속 가지요.', `MaleText_loc4`='这里没有。继续前进。', `MaleText_loc5`='沒啥有用的。繼續前進。', `MaleText_loc7`='Aquí no hay nada. A seguir.' WHERE `ID`=60801;
