UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구야? $c|1이라든지;라든지; 뭐 그런 거야?', `FemaleText_loc4`='你以为你是谁？一个$c或者什么别的玩意儿？', `FemaleText_loc5`='你是什麼玩意?什麼$c之類的嗎?', `FemaleText_loc7`='¿Quién se supone que eres? ¿Algún tipo de $c?' WHERE `ID`=60812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거품 나는 노란 맥주? 약골이나 그루멀이 마시는 거지.', `FemaleText_loc4`='起泡沫的黄啤酒是给懦夫和土地精准备的。', `FemaleText_loc5`='氣泡黃啤酒是給蠢驢跟咕嚕摩喝的。', `FemaleText_loc7`='La cerveza amarilla con burbujas es para los débiles y los grúmel.' WHERE `ID`=60813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 맥주를 마실 자격이 된다고 생각해?', `FemaleText_loc4`='你敢来尝尝我酿的酒吗？', `FemaleText_loc5`='你覺得自己夠格接受我的啤酒考驗嗎?', `FemaleText_loc7`='¿Crees que tienes lo que hay que tener para probar mis cervezas?' WHERE `ID`=60814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 맥주를 한 모금만 마시면 네가 얼마나 쓸모없는 녀석인지 알게 될걸.', `FemaleText_loc4`='只要抿上一口，你就会知道自己有多么差劲了。', `FemaleText_loc5`='喝一口我的啤酒，你就會發現到自己是多麼的渺小。', `FemaleText_loc7`='Un trago de mi cerveza y descubrirás lo $gindigno:indigna; que eres en realidad.' WHERE `ID`=60815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 내 상대라고? 이 대회, 생각보다 쉽겠는걸.', `FemaleText_loc4`='我跟你打？哇哦，这场对决比我想得还要简单。', `FemaleText_loc5`='要我跟你打?哇喔，這比賽比我想得更容易。', `FemaleText_loc7`='¿Me toca contra ti? Vaya, esta competición va a ser más fácil de lo que pensaba.' WHERE `ID`=60816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에도 봐 줄 거라 생각하지 마.', `FemaleText_loc4`='下一次你可没那么容易全身而退了。', `FemaleText_loc5`='別以為下次我會讓你逃過。', `FemaleText_loc7`='No creas que la próxima vez te dejaré ganar.' WHERE `ID`=60817;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번엔 네가 이겼지만, 다음엔 내가 더 좋은 맥주를 준비해 둘 거야.', `FemaleText_loc4`='这一回是你赢了，可等我们下次相遇时，我会拿出更好的佳酿。', `FemaleText_loc5`='你贏了這回合，但我們下回再見時，我會有更好的啤酒。', `FemaleText_loc7`='Has ganado este asalto, pero tendré una cerveza mejor en nuestro próximo encuentro.' WHERE `ID`=60818;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 난 충분히 이길 수 있었어. 알지? 조금 더 빨리 "맥주 태세"로 바꾸기만 했으면.', `FemaleText_loc4`='我今天本可以打败你的，你知道吗。我只要更快地切换到“醉酒姿态”就行了。', `FemaleText_loc5`='你知道，我今天可以打敗你的。我只是需要更快切換成我的「啤酒形態」。', `FemaleText_loc7`='¿Sabes que hoy te podía haber derrotado? Tan solo tenía que haber cambiado al "Estilo cervecero" antes.' WHERE `ID`=60819;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단은 승리의 맛을 즐겨 둬. 다음에 만나면 패배의 쓴맛을 보게 될 테니까.$b$b안 그래도 다음 맥주 이름을 "패배의 쓴맛"으로 할까 하거든. 입에 착착 붙는 이름은 아니지만, 그런 이름의 맥주를 마시려면 특별한 실패를 경험해야만 하지.', `FemaleText_loc4`='尽情享受胜利的滋味吧，只是暂时的。下次我们交手时，你会尝到被击败的滋味。$b$b事实上，我会把我接下来要酿的酒起名叫“失败苦酒”——口感不会太糟，但会让喝得人沉浸在失败的痛苦中不能自已。', `FemaleText_loc5`='你就盡情享受勝利的滋味吧。下次我們對戰時，你就會嘗到失敗的痛苦滋味。$b$b事實上，我要把我釀的下個啤酒取這個名字。「失敗的苦澀」。聽起來不怎麼響亮，但只有嘗過失敗滋味的人能夠了解這種啤酒的滋味。', `FemaleText_loc7`='Disfruta del sabor de la victoria. La próxima vez que nos enfrentemos saborearás el amargor de la derrota.$b$bDe hecho, creo que voy a llamar así a mi próxima cerveza. "El amargor de la derrota". No es que sea muy atractivo que digamos, pero hace falta una derrota especial para que alguien se beba algo con ese nombre.' WHERE `ID`=60820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 나그네여. 대회에 다양성이 있는 걸 보니 좋군요.', `MaleText_loc4`='欢迎你，旅行者。看到这次比赛如此多元化，我很高兴。', `MaleText_loc5`='歡迎你，旅行者。看到比賽中有點變數是件好事。', `MaleText_loc7`='Hola. Qué bien que haya tanta variedad en este torneo.' WHERE `ID`=60821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 등 뒤의 호젠은 신경 쓰지 마십시오. 자기 수양... 을 아직 마치지 못했거든요.', `MaleText_loc4`='不必理会我身后的那只猢狲。他的戒律训练正在……进行中。', `MaleText_loc5`='不要在意我背後的猴人。他的紀律訓練...還在進行中。', `MaleText_loc7`='Ignora al hozen de ahí detrás. Su entrenamiento en disciplina está siendo... complicado.' WHERE `ID`=60822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오늘 이곳에 있기 위해 비취 숲으로부터 먼 길을 왔습니다. 이 대회를 통해 실력을 길렀으면 하는 것이 제 바람입니다.', `MaleText_loc4`='我们从翡翠林出发，历尽跋涉才在今天抵达这里。我希望能在这次比赛中提升自己的技能。', `MaleText_loc5`='我們自翠玉林出發後，經歷了一場辛苦的旅程才在今日到達此地。我希望能在這個競賽精進我的武術。', `MaleText_loc7`='Hemos recorrido un largo camino desde el Bosque de Jade hasta llegar aquí. Espero mejorar mis habilidades en este torneo.' WHERE `ID`=60823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과의 대결을 기대하고 있습니다.', `MaleText_loc4`='我对即将到来的挑战充满期待。', `MaleText_loc5`='我期待著我們即將到來的對戰。', `MaleText_loc7`='Estoy deseando empezar nuestro desafío.' WHERE `ID`=60824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나니 좋군요, 친구. 사마귀 무리로부터 돌밭 마을을 구한 것이 바로 엊그제 같은데 말입니다.', `MaleText_loc4`='很高兴再次见到你，朋友。我们帮助石犁村摆脱螳螂妖威胁的经历还历历在目呢，仿佛就发生在昨天。', `MaleText_loc5`='我的朋友，再見到你真好。我們一起將石犁村從一大群螳螂人的手中解救出來的事，好像昨天才發生一樣。', `MaleText_loc7`='Me alegro mucho de volver a verte. Parece que fue ayer cuando salvamos la ciudad de Villarroca de los enjambres de mántides.' WHERE `ID`=60825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭의 구세주와 이야기를 나누는 것은 명예로운 일이지요.', `MaleText_loc4`='与石犁村的救星交谈，总让我感到无比荣幸。', `MaleText_loc5`='很榮幸能與石犁村的救星說話。', `MaleText_loc7`='Siempre es un honor compartir unas palabras con $gel Salvador:la Salvadora; de Villarroca.' WHERE `ID`=60826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭 주민들이 당신에 대해 하는 이야기를 들어 봐야 합니다.', `MaleText_loc4`='你真该听听他们是怎么说你在石犁村的事迹的。', `MaleText_loc5`='你應該聽聽他們如何傳頌你在石犁村的事蹟。', `MaleText_loc7`='Deberías escuchar las historias que cuentan sobre tus hazañas en Villarroca.' WHERE `ID`=60827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$P! 낯익은 얼굴을 여기서 보니 정말 좋군요.', `MaleText_loc4`='$P！能在这儿看到一张友好的面孔真是太好了。', `MaleText_loc5`='$P!能在這裡遇見熟悉的面孔真好。', `MaleText_loc7`='¡$P! Qué alegría ver una cara conocida por aquí.' WHERE `ID`=60828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 만나니 정말 반갑습니다. 네 바람의 계곡에서 함께 싸운 후로 시간이 좀 흘렀군요.', `MaleText_loc4`='很高兴能在这里见到你，我的朋友。距离我们在四风谷携手合作已经有段日子了。', `MaleText_loc5`='我的朋友，在這裡看見你真好。距離我們在四風峽大幹一場的日子，已經好一段時間了。', `MaleText_loc7`='Me alegro mucho de verte. Ha pasado mucho tiempo desde nuestros logros en el Valle de los Cuatro Vientos.' WHERE `ID`=60829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨은 계속 말썽을 피웁니다. 보는 일마다 사사건건 트집이지요. 컨컨과 함께 다니지 않아도 될 날만 기다리고 있습니다.', `MaleText_loc4`='肯肯还是那么招人讨厌，喜欢毁坏任何他所触碰过的东西。我希望有朝一日能够不要再和他一起结伴同行。', `MaleText_loc5`='肯·肯持續給他接觸過的一切帶來麻煩與破壞。我期待有天我可以不需要跟他一起旅行。', `MaleText_loc7`='Ken-Ken sigue siendo un incordio y una distracción para todo el mundo. No veo el día en que no tenga que viajar a su lado.' WHERE `ID`=60830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실력을 시험해 보시지!', `FemaleText_loc4`='试试你的力量！', `FemaleText_loc5`='測試你的能力!', `FemaleText_loc7`='¡Pon a prueba tu fuerza!' WHERE `ID`=60831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아는 것이 힘이다...', `FemaleText_loc4`='有勇无谋，亦是枉然。', `FemaleText_loc5`='知識就是力量。', `FemaleText_loc7`='No hay conocimiento que no otorgue poder.' WHERE `ID`=60832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 모구샨 황제의 고대 금고로군. 흐음... 이 단추는 뭐지...?', `MaleText_loc4`='啊，魔古山帝王的宝库。这个按钮有什么用…?', `MaleText_loc5`='啊，是古代的魔古山帝王墓穴。這個按鈕是幹嘛用的...?', `MaleText_loc7`='Ah, las antiguas Cámaras de los Emperadores de Mogu''shan. ¿Qué hará este botón...?' WHERE `ID`=60833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서는 컨컨과 제가 힘을 합쳤으면 당신을 이길 수 있었을 거라고 하십니다. 다음에는 좀 더 싸울 만한 상대가 되어 있을지도 모르지요.', `MaleText_loc4`='雪怒坚持认为，只要我和肯肯联手，就一定能击败你。或许下回我们能好好的较量一场。', `MaleText_loc5`='雪怒堅持，若我跟肯·肯能學會團隊合作，我們就能擊敗你。或許下次我們能成為更優秀的挑戰者。', `MaleText_loc7`='Xuen insiste en que Ken-Ken y yo te podíamos haber derrotado de haber luchado juntos. Quizás la próxima vez supongamos un mejor desafío.' WHERE `ID`=60834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 싸움이었습니다. 당신이 이렇게까지 강해진 걸 보니 놀랍군요.', `MaleText_loc4`='打得漂亮。真不可思议，你竟然已经变得如此强大了。', `MaleText_loc5`='前面那場戰鬥打得真好。看到你變得這麼強壯，實在讓人驚訝。', `MaleText_loc7`='Bien luchado. Es toda una sorpresa comprobar lo fuerte que te has hecho.' WHERE `ID`=60835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 쉬엔 님께서 짐스러운 호젠 없이 혼자서 당신과 싸울 수 있게 해 주실지도 모르지요.', `MaleText_loc4`='希望下回雪怒能让我直接挑战你，而不是被一个猢狲碍手碍脚。', `MaleText_loc5`='希望下次雪怒會讓我直接跟你對打，而不是多個猴人在那裡礙手礙腳。', `MaleText_loc7`='Esperemos que la próxima vez Xuen me deje enfrentarme a ti directamente sin que me obstaculice un hozen.' WHERE `ID`=60836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레슬러가 우낏 너무 세게 때려서 $pr 잘생겨지겠다.', `MaleText_loc4`='摔跤手会狠狠击打蠢蛋的脸，没准还能顺手给$pr整个容啥的。', `MaleText_loc5`='摔跤手要在怪怪人臉上用力打一拳，讓$pr的長相變好看點。', `MaleText_loc7`='El Luchador pegará a makaku en la kara tan fuerte ke dejará $gguapo:guapa; a $pr.' WHERE `ID`=60837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엉? 너 누구냐? 저리 가라. 레슬러 록 록 감독하고 연습 더 해야 된다!', `MaleText_loc4`='哈？你是谁？快走开。摔跤手要跟教头洛洛多练一会儿！', `MaleText_loc5`='哼嗯?你誰啊?走開。摔跤手需要更多時間跟阿克阿克教練在一起!', `MaleText_loc7`='¿Eh? ¿Kién es? Vete. ¡El Luchador necesita más tiempo con el Entrenador Rok Rok!' WHERE `ID`=60838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 오늘 운 좋은 줄 알아라. 다음에는 레슬러가 이길 거다!', `MaleText_loc4`='蠢蛋今天走运了。摔跤手只好重赛了！', `MaleText_loc5`='怪怪人今天是運氣好。摔跤手會在下次比賽打敗你!', `MaleText_loc7`='Makaku ha tenido suerte hoy. ¡El Luchador te ganará en la revancha!' WHERE `ID`=60839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어흐음!', `MaleText_loc4`='嗯呼嗯呼！', `MaleText_loc5`='嗯嗯噗嗯嗯嗯嗯噗!', `MaleText_loc7`='¡Mmmmmmmmmmm!' WHERE `ID`=60840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='컨컨 여행 많이 해서 왕 센 수도사 됐다.', `MaleText_loc4`='肯肯经历了艰苦的修行，现在已是超级强壮的武僧了。', `MaleText_loc5`='肯·肯經歷了很長的旅程，現在是個超級強壯的僧侶了。', `MaleText_loc7`='Ken-Ken ha viajado mucho y ahora es monje muy poderoso.' WHERE `ID`=60841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끈미끈한 냄새 나서 미안하다. 영리한 애쉬요, 안 깨끗한 진위다.', `MaleText_loc4`='我对这臭味儿感到很抱歉。聪明的阿西约是条臭鱼。', `MaleText_loc5`='抱歉聞起來有滑魚味。聰明的艾須歐不是一個愛乾淨的錦魚人。', `MaleText_loc7`='Yo siente el olor a manduka. Ashyo el Astuto no es jinyu limpio.' WHERE `ID`=60842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이 애쉬요만 아니었으면 컨컨 이겼을 거다.', `MaleText_loc4`='要不是阿西约拖后腿，肯肯赢定了。', `MaleText_loc5`='如果不是艾須歐這個廢渣，肯·肯本來可以贏的。', `MaleText_loc7`='Ken-Ken ganar si Ashyo no fuera un miko.' WHERE `ID`=60843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 컨컨 이길 거다! 애쉬요 있거나 없거나 상관없다.', `MaleText_loc4`='下一次肯肯一定要赢！不管有没有阿西约。', `MaleText_loc5`='下次肯·肯就會贏!不管有沒有艾須歐都一樣。', `MaleText_loc7`='¡La próxima vez gana Ken-Ken! Kon o sin Ashyo.' WHERE `ID`=60844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭의 구세주네! 안녕 안녕.', `MaleText_loc4`='石犁村的英雄！你好啊。', `MaleText_loc5`='石犁村的英雄!哈囉。', `MaleText_loc7`='¡$GEl héroe:La heroína; de Villarroca! Hola, hola.' WHERE `ID`=60845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌밭을 구한 최강 $R|1이다;다;!', `MaleText_loc4`='这就是那位了不起的$R，石犁村的救星！', `MaleText_loc5`='這就是拯救石犁村的超級$R!', `MaleText_loc7`='¡Akí está $gel:la; gran $R que salvó Villarroca!' WHERE `ID`=60846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗, $p! 어쩌다 여기 왔냐? 우리 오늘 싸우는 거냐?', `MaleText_loc4`='噢，$p！你怎么到这儿来了？我们今天要打一场吗？', `MaleText_loc5`='喔，$p!你是怎麼來到這兒的?我們今天要打一場嗎?', `MaleText_loc7`='¡Oh, $p! ¿Tú kómo ha llegado hasta akí? ¿Nosotros luchan hoy?' WHERE `ID`=60847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다! 응가 같은 영리한 애쉬요랑 같이 있기 싫다.', `MaleText_loc4`='噢，很高兴再次见到你！聪明的阿西约是个烂伙伴。', `MaleText_loc5`='喔真高興又見到你!聰明的艾須歐真是難相處。', `MaleText_loc7`='¡Oh, alegre de ver otra vez! Ashyo el Astuto es kompañía dingue.' WHERE `ID`=60848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 코앞으로 다가온 패배의 냄새를 맡는다.', `MaleText_loc4`='闻起来，你似乎马上就要输了。', `MaleText_loc5`='你不久後將會嘗到苦頭。', `MaleText_loc7`='Huele a derrota en tu futuro próximo.' WHERE `ID`=60849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 팀이 너를 박살낼 거다.', `MaleText_loc4`='我的队伍将粉碎你。', `MaleText_loc5`='我的隊伍會宰了你。', `MaleText_loc7`='Mi equipo te aplastará.' WHERE `ID`=60850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 누군지 알아? 내가 누군지 아냐고?', `MaleText_loc4`='你知道我是谁吗？你知道我是谁吗？！', `MaleText_loc5`='你知道我是誰嗎?你知不知道我是誰?!', `MaleText_loc7`='¿Sabes quién soy yo? ¡¿Sabes quién soy yo?!' WHERE `ID`=60851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 이렇게 쉽게 이길 수 없을 거다! 힐한테 자리를 잘 지키라고 일러 뒀으니까.', `MaleText_loc4`='下一次，我才不会这么轻易被打败！我已经让我的治疗者记住他的位置了。', `MaleText_loc5`='下次你會發現我變得更難纏!我已經提醒我的治療者要好好的幹活。', `MaleText_loc7`='¡La próxima vez comprobarás que no soy tan fácil de derrotar! Ya me he asegurado de que mi sanador recuerde su posición.' WHERE `ID`=60852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 나한테 말 걸지 마! 탱! 탱! 이 더러운 녀석을 나한테서 떼 줘!', `MaleText_loc4`='啊！别跟我说话！坦住！坦住！把他的注意力吸引过去，你这蠢货！', `MaleText_loc5`='啊!不要跟我說話!坦克!坦克!快用嘲諷把他從我身上弄走，你這骯髒的東西!', `MaleText_loc7`='¡Ah! ¡Ni me hables! ¡Tanque! ¡Tanque! ¡Quítame esta asquerosidad de encima!' WHERE `ID`=60853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음엔 널 박살낼 거다! 우리 탱이 널 단단히 붙잡고 있을 테니까!', `MaleText_loc4`='我们下次一定会粉碎你！我们的坦克会记得拉好你的仇恨的！', `MaleText_loc5`='下次我們一定會宰了你!我們的坦克下次應該會記得對你產生足夠的威脅值!', `MaleText_loc7`='¡La próxima vez te aplastaremos! ¡Nuestro tanque se acordará de generar la amenaza suficiente!' WHERE `ID`=60854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전리품 냄새가 나는군.', `MaleText_loc4`='你身上有股战利品的气味。', `MaleText_loc5`='你身上有寶物的味道。', `MaleText_loc7`='Hueles a botín.' WHERE `ID`=60855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전멸한 데다 장비도 못 먹었어.', `MaleText_loc4`='我们精疲力尽，而且我也没拿到装备。', `MaleText_loc5`='我們滅團了，害我沒骰到我的裝備。', `MaleText_loc7`='Hemos perdido y no he conseguido mi equipo.' WHERE `ID`=60856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 무자비한 치앙에 대한 기록 같군. 여러 국가를 점령하고, 철권 통치했던 위대한 정복자였네!', `MaleText_loc4`='看上去这些就是无情战王齐昂的记录了。无数诸侯都曾臣服于其铁腕统治之下。', `MaleText_loc5`='這個應該是『殘暴王』羌皇的紀錄，他是個以鐵腕統治臣民的偉大征服者!', `MaleText_loc7`='Esta debe de ser la historia de Qiang el Despiadado, ¡un conquistador que gobernó a sus vasallos con mano de hierro!' WHERE `ID`=60857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 오는 게 꿈이었는데. 정말 좋아요! 오늘 제가 대회에서 우승할 거라고요!', `MaleText_loc4`='我一直梦想来到这里。就是这地方！我将在今天赢得比赛！', `MaleText_loc5`='我一直夢想有一天能站在這裡。就是今天!今天是我贏得比賽的日子!', `MaleText_loc7`='He soñado que estaba aquí hoy. ¡Eso es! ¡Hoy va a ser el día en que gano el torneo!' WHERE `ID`=60858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 봉 보여요? 우리 가문에 대대로 전해 내려오는 봉인데, 바로 여기서 우리 조상님들이 이 봉으로 수백 번 우승을 거머쥐었죠.$b$b봉에 깃든 기운이 느껴져요? 여기 오니까 기운이 훨씬 강해졌어요.', `MaleText_loc4`='看到这把棘杖了吗？这是我家世代相传的神兵，到目前为止已赢过数百场比赛。$b$b你能感受到其中的力量吗？在这儿，它更是前所未有的强大。', `MaleText_loc5`='看到這柄杖了嗎?它在我家族代代相傳，並在這個地點贏得數以百計的競賽。$b$b你能感受到蘊含其中的力量嗎?它在這裡發揮的力量，比我曾去過的任何地方更強大。', `MaleText_loc7`='¿Ves esta vara? Ha pertenecido a mi familia durante generaciones y ha ganado cientos de torneos en este preciso lugar.$b$b¿Sientes su poder? Es mucho más poderosa aquí que en cualquier otro lugar de los que he estado.' WHERE `ID`=60859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 당신이 이겼지만, 내일은 또 모르죠. 아버지는 항상 말씀하셨어요. 처음에 실패하더라도, 피를 닦아 내고 성공할 때까지 도전하라고.', `MaleText_loc4`='嗯，今天你赢了，可那并不代表我明天就不会赢。棘杖老爹总是说，失败是成功之母，擦干血迹，爬起来再战就是了，总有打赢的一天。', `MaleText_loc5`='嗯，今天是你贏了。但那不代表明天我不會獲勝。藤杖爸爸總是說，在哪裡跌倒，就要從哪裡爬起來。', `MaleText_loc7`='Bueno, has ganado hoy, pero eso no significa que vayas a ganar mañana. Papá Vara Enzarzada solía decir que si no tienes éxito a la primera, hay que limpiarse la sangre y volver a intentarlo hasta conseguirlo.' WHERE `ID`=60860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이야기를 들은 적이 있네. 능숙한 궁수이자 천재적인 도둑으로 유명한 날렵한 쑤베타이야. 부자의 재산을 훔쳐내서, 모두 자기가 차지했다고 하지.', `MaleText_loc4`='对这个人物我有所耳闻：迅影匪王速不台。传闻中他是个精通箭术的神偷。他劫富却不济贫，将偷盗之物都归为己有。', `MaleText_loc5`='我曾經聽過這樣一個故事:『迅矯手』蘇比泰王是位技藝高超的弓箭手及天才盜賊。他會偷取富人的財產，全部都據為己有。', `MaleText_loc7`='He oído historias sobre este: Subetai el Raudo, conocido como excelente arquero e ingenioso ladrón. Robaba a los ricos y se quedaba con todo para si mísmo.' WHERE `ID`=60861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 돌밭에서 내 인기를 빼앗아간 "영웅"이군요.$b$b농담이에요, 농담. 대단한 싸움이었죠. 함께 싸울 수 있었던 게 영광이에요.', `MaleText_loc4`='啊！这不是那位在石犁村抢了我风头的“大英雄”嘛！$b$b开个玩笑，开个玩笑。那是场伟大的战役。很荣幸能与你并肩作战。', `MaleText_loc5`='啊!在石犁村搶走我光環的「英雄」。$b$b我開玩笑的，開玩笑的。那是場偉大的戰役。我很榮幸能跟你一起戰鬥。', `MaleText_loc7`='¡Ah! $GEl "héroe":La "heroína"; que me robó el protagonismo en Villarroca.$b$bEs una broma, es una broma. Esa fue una gran batalla. Es un honor haber luchado a tu lado.' WHERE `ID`=60862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$P! 백호사에 잘 오셨어요! 쉬엔 님이 여기서 재미있는 대회를 주최하시죠. 우리 가문이 툭하면 우승하지만요.', `MaleText_loc4`='$P！欢迎来到白虎寺！雪怒正在举行精彩的比赛，我的家族向来都是赢家。', `MaleText_loc5`='$P!歡迎到白虎寺來!雪怒創辦了一場了不起的比賽，我的家族是裡頭的常勝軍。', `MaleText_loc7`='¡$P! ¡$GBienvenido:Bienvenida; al Templo del Tigre Blanco! Xuen organiza un torneo espectacular que mi familia tiene el hábito de ganar.' WHERE `ID`=60863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 저 토깽이가 누굴 데려온 거야? $P, 잘 지냈어요? 대회에 참가하려고 온 거예요?', `MaleText_loc4`='嗯，看看兔妖把谁给拽来了。$P，你近况如何？你是来比赛的吗？', `MaleText_loc5`='嗯，看看是什麼被兔妖拖來了。$P，近來如何?你是風聞競賽之事而來的嗎?', `MaleText_loc7`='Mira quién ha venido. ¿Cómo estás, $P? ¿Has venido a competir?' WHERE `ID`=60864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 누구지? 이 황제에 대해서는 들어본 적이 없네. 실성한 멩이라고? 이 글을 보면, 멩은 왕좌를 차지했던 자 중에서 가장 사악하고 미치광이 같은 지배자였군.', `MaleText_loc4`='这是什么？我还不曾听闻这个帝王。暴虐疯王蒙恩？根据这段描述，蒙恩是迄今为止最邪恶、最疯狂的暴君。', `MaleText_loc5`='這是誰?我從來沒聽過這位大帝。『狂顛心』孟帝?根據這些文字顯示，孟是有史以來名聲最臭、最瘋狂的統治者。', `MaleText_loc7`='¿Y este? No sé nada sobre este emperador. ¿Meng el Demente? Según estos escritos, fue el más despreciable y maníaco de entre todos los que ocuparon el trono imperial.' WHERE `ID`=60865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔어요? 드디어 우리 둘이서 우승을 놓고 겨룰 수 있게 되는 건가요?', `MaleText_loc4`='你来了？这是不是意味着我们终于有机会同场竞争大赛冠军了？', `MaleText_loc5`='你來了?這是不是代表我們終於有機會一較高下，爭取競賽名次?', `MaleText_loc7`='¿Has llegado hasta aquí? ¿Significa esto que por fin tendremos una oportunidad de enfrentarnos por el título del torneo?' WHERE `ID`=60866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오. 그럼 제가 돌밭의 용사와 싸우게 되는 건가요? 굉장한데요!', `MaleText_loc4`='喔，这么说我要对决石犁村的勇士了？太棒了！', `MaleText_loc5`='喔喔喔。這是不是代表我可以跟石犁村的英雄對戰?太美好了!', `MaleText_loc7`='¡Vaya! ¿Significa esto que podré enfrentarme $gal campeón:a la campeona; de Villarroca? ¡Estupendo!' WHERE `ID`=60867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딜리스가 당신의 물건을 훔치려고 합니다.', `MaleText_loc4`='哈吉斯想要掏你的口袋。', `MaleText_loc5`='傷奇思試圖摸走你口袋裡的東西。', `MaleText_loc7`='Destructiss intenta hurgarte en el bolsillo.' WHERE `ID`=60868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와의 경합을 기대하고 있다네.', `MaleText_loc4`='我很期待我们的对决。', `MaleText_loc5`='我期待我們的比賽。', `MaleText_loc7`='Estoy deseando que llegue nuestro enfrentamiento.' WHERE `ID`=60869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔의 청이 바람을 타고 비취 숲에 있는 내 집에 도달했다네. 그런 청은 거절할 수가 없지.', `MaleText_loc4`='有关雪怒挑战赛的消息都传到我在翡翠林的老家那儿去了。我可无法拒绝这样的邀请。', `MaleText_loc5`='雪怒的挑戰傳到了我在翠玉林的家。我無法拒絕這樣的邀請。', `MaleText_loc7`='El desafío de Xuen surcó los vientos hasta mi casa en el Bosque de Jade. No podía rechazar tal invitación.' WHERE `ID`=60870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 풍채는 용사에 걸맞는군. 허나 그만 한 배짱도 있는가.', `MaleText_loc4`='你长着一张英雄脸。天知道你是不是真那么坚毅。', `MaleText_loc5`='你有著勇士的外表。但你沒有勇士的毅力。', `MaleText_loc7`='Tienes el porte de un campeón. Me pregunto si posees también la fortaleza.' WHERE `ID`=60871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구도 자네 실력에 의심을 품을 수 없네, 용사여.', `MaleText_loc4`='没人能质疑你的战斗力，勇士。', `MaleText_loc5`='沒人能質疑你的實力，勇士。', `MaleText_loc7`='Nadie puede negar la fuerza de tus habilidades, $gcampeón:campeona;.' WHERE `ID`=60872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏, 뻥 뻥 뻥튀기를 먹고 살 수 있을 것 같으냐?', `MaleText_loc4`='蠢蛋以为自己能抵挡住轰轰大狂欢？', `MaleText_loc5`='怪怪人覺得自己可以擋得住砰砰大爆炸嗎?', `MaleText_loc7`='¿Makakus piensan ke pueden tomar el Boogaloo Bum Bum?' WHERE `ID`=60873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뻥 뻥한테 끝내주는 뻥 막대 있다.', `MaleText_loc4`='布姆布姆大师这儿有超级强大的火器。', `MaleText_loc5`='砰砰大師有一些超級砰砰棒。', `MaleText_loc7`='El maestro Bum Bum tiene algunos súper palos bum.' WHERE `ID`=60874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏, 이긴 줄 아느냐? 하! 뻥 뻥 절대 항복 안 한다! 우리 비긴 거다!', `MaleText_loc4`='蠢蛋认为它能赢？哈！布姆布姆大师从不说“投降”！咱们死磕到底吧！', `MaleText_loc5`='怪怪人以為他們贏了?哈!砰砰大師從不投降!就算和棋吧!', `MaleText_loc7`='¿Makaku piensa ke ganó? ¡Ja! ¡El maestro Bum Bum nunka dice "rendirse"! ¡Tablas!' WHERE `ID`=60875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘은 여러 가지 모습을 띤다. 어떤 이에게는 무기이고, 어떤 이에게는 짐이지. 내게는, 존재의 방식이고.', `MaleText_loc4`='力量有多种形态。它对某些人是武器，对另一些人则是负担。而对我自己而言，它是生存之道。', `MaleText_loc5`='力量會表現成各種形式。對某些人來說它是武器。對其他人來說是種負擔。至於對我來說，我認為那是一種存在的方式。', `MaleText_loc7`='La fuerza se entiende de muchas maneras. Para unos es un arma. Para otros es una carga. Yo, sin embargo, la veo como una forma de ser.' WHERE `ID`=60876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 그대가 힘의 무술 대회에 참여하다니 기쁘군.', `MaleText_loc4`='$p，欢迎你参加我的力量大赛！', `MaleText_loc5`='$p，歡迎來到我的比武大會。', `MaleText_loc7`='¡Bienvenidos, participantes, a mi Torneo de Fuerza!' WHERE `ID`=60877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서는, 힘도 도구이기에 잘 다루려면 연습이 필요하다고 가르치십니다.', `MaleText_loc4`='雪怒教导我们，力量是一种需要通过不断练习才能驾驭的工具。', `MaleText_loc5`='雪怒教導我們力量是一種需要練習的工具。', `MaleText_loc7`='Xuen nos enseña que la fuerza es una herramienta que requiere práctica.' WHERE `ID`=60878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서는 며칠에 한 번씩 무술 대회를 여십니다. 판다리아에서 가장 강하고 용감한 자가 아니면 감히 도전할 엄두도 못 내지요.', `MaleText_loc4`='雪怒每隔几天就会举办一场力量大赛。只有全潘达利亚最强大最勇敢的挑战者才敢前去比试。', `MaleText_loc5`='每隔幾天，雪怒就會舉辦一場比武大會。只有全潘達利亞最強壯最勇敢的挑戰者，才敢來參加比賽。', `MaleText_loc7`='Cada ciertos días, Xuen celebra un torneo de fuerza. Solo los contendientes más fuertes y valientes de toda Pandaria se atreven a competir.' WHERE `ID`=60879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님의 새끼들을 조심하십시오. 덩치는 작지만 힘은 무지막지합니다.', `MaleText_loc4`='小心雪怒的幼崽。别看他们个子小，它们可以靠纯粹的力量弥补这一弱点。', `MaleText_loc5`='別小看雪怒的孩子。他們雖然個子不大，但是蠻力驚人。', `MaleText_loc7`='Cuidado con los cachorros de Xuen. Compensan su escaso tamaño con pura fuerza.' WHERE `ID`=60880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면, 쉬엔 님은 몇 세기 동안 무술 대회에 참가하신 적이 없다고 합니다.$b$b우리에게 싸울 기회를 주고 싶어서라고 말씀은 하시지만, 제 생각엔 그냥 늙어서 그러시는 것 같습니다. 그분이 정확히 어떤 존재인지는 몰라도, 그런 존재치고는... 늙은 거 아닐까요?', `MaleText_loc4`='相传，雪怒已经有几百年没有在他自己举行的比赛中大显身手了。$b$b他说是这是为了让我们都能有比试的机会。可我觉得，那只是因为他老了。或者……至少是……对于他那样的……存在……来说，已经老了。', `MaleText_loc5`='根據傳說，雪怒已經好幾世紀沒在自己舉辦的賽事中戰鬥了。$b$b祂說是因為祂希望給我們參戰的機會。我猜祂只是老了。或者...至少..對某些事情來說是老了....嗯...不論祂到底說的是什麼啦。', `MaleText_loc7`='Cuenta la leyenda que Xuen no ha luchado en ninguno de sus torneos desde hace siglos.$b$bDice que no compite porque quiere que tengamos posibilidades. Yo creo que se está haciendo viejo. O... al menos... viejo para ser un... bueno... lo que sea que es.' WHERE `ID`=60881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헛! 겨우 그 정도로 팔이 우람하다는 겁니까? 제 팔의 멍에도 그보다는 근육이 많이 붙어 있겠군요.', `MaleText_loc4`='你们管那叫做强壮的臂膀？还没有我瘀伤里的肌肉多呢。', `MaleText_loc5`='你管那些叫強壯的手臂?哈!我身上瘀青裡頭的肌肉都還比較多。', `MaleText_loc7`='¿Eso es lo que tú entiendes por brazos fuertes? ¡Ja! Yo tengo moretones con más músculos.' WHERE `ID`=60882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 호랑이의 눈을 지녔습니까?', `MaleText_loc4`='你有猛虎的眼睛吗？', `MaleText_loc5`='你具備如老虎一般的眼睛嗎?', `MaleText_loc7`='¿Tienes la mirada del tigre?' WHERE `ID`=60883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t아다로그가 |cFFFF0000$n|r|1을;를; 보면서 |cFFFF0000|Hspell:119299|h[지옥불 돌진]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t阿达罗格盯住了|cFFFF0000$n|r并开始施放|cFFFF0000|Hspell:119299|h[地狱冲锋]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t昂布里斯將軍的視線轉到|cFFFF0000$n|r身上，並且開始施展|cFFFF0000|Hspell:119299|h[煉獄衝鋒]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_charge.blp:20|t¡Adarogg fija la mirada |cFFFF0000$n|r y comienza a lanzar |cFFFF0000|Hspell:119299|h[Carga infernal]|h|r!' WHERE `ID`=60884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우승을 축하드립니다, 용사여!', `MaleText_loc4`='恭喜你取得胜利，勇士！', `MaleText_loc5`='恭喜你獲得勝利，勇士!', `MaleText_loc7`='¡Enhorabuena por tu victoria, $gcampeón:campeona;!' WHERE `ID`=60885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 직접 뵙는 것만으로도 영광입니다, 용사여.', `MaleText_loc4`='你的到来令我们大感荣幸，勇士。', `MaleText_loc5`='勇士，你的出現使我們備感榮耀。', `MaleText_loc7`='Nos honras con tu presencia, $gcampeón:campeona;.' WHERE `ID`=60886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 보여주신 위업은 정말 대단했습니다. 정말 대단한 힘입니다!', `MaleText_loc4`='你今天展示的卓越战技真是令我们大开眼界啊。干得好！', `MaleText_loc5`='你今天展現出令人敬佩的力量。做得好!', `MaleText_loc7`='Hoy has realizado impresionantes hazañas de fuerza. ¡Buen trabajo!' WHERE `ID`=60887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 시합은 정말 오랜만에 봅니다!', `MaleText_loc4`='我已经好多天没看到过这么精彩的比赛了！', `MaleText_loc5`='我好一陣子沒看到這樣的比試了!', `MaleText_loc7`='¡Hacía días que no veía un combate así!' WHERE `ID`=60888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우셨습니다, 용사여!', `MaleText_loc4`='打得漂亮，勇士！', `MaleText_loc5`='精彩的戰鬥，勇士!', `MaleText_loc7`='¡Bien luchado, $gcampeón:campeona;!' WHERE `ID`=60889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 싸우시는 모습을 봤습니다. 대회에 참가하는 달인 몇 분만큼 우아하지는 않지만, 강력한 것만은 분명하더군요. 앞으로도 지켜보며 배우겠습니다.', `MaleText_loc4`='我看了你今天的战斗。跟某些前来参加比赛的大师相比，你的拳脚显得略欠章法，但显然更具实用性。我今后会关注你，并向你学习的。', `MaleText_loc5`='我看過你今天的戰鬥了。與一些參賽的大師相比，你的技藝還不夠洗練，但實力已不容置疑。我會繼續關注你的比賽，並向你學習。', `MaleText_loc7`='He visto cómo has luchado hoy. Tienes un estilo menos refinado que algunos de los maestros que participan en el torneo, pero es ciertamente efectivo. Te observaré en próximas ocasiones... y aprenderé.' WHERE `ID`=60890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 혹시 $c입니까? 대회에 참가하는 겁니까? 흥미롭겠는데요.', `MaleText_loc4`='什么，一个$c？也要加入比赛？这下变得更有趣了。', `MaleText_loc5`='喔，一個$c?參加比賽?這應該會很有趣。', `MaleText_loc7`='Oh, ¿$gun:una; $c que participa en el torneo? Esto se pone interesante.', `FemaleText_loc1`='아, 혹시 $c|1이에요;예요;? 대회에 참가하는 거예요? 흥미롭겠는데요.', `FemaleText_loc4`='什么，一个$c？也要加入比赛？这下变得更有趣了。', `FemaleText_loc5`='喔，一個$c?參加比賽?這應該會很有趣。', `FemaleText_loc7`='Oh, ¿$gun:una; $c que participa en el torneo? Esto se pone interesante.' WHERE `ID`=60891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. $c|1이라니;라니; 흥미롭긴 한데, 레슬러나 사부 뻥 뻥을 상대로 얼마나 잘 싸우는지 봅시다.', `MaleText_loc4`='嗯。一位$c可是颇具看点啊，但让我们看看你将如何对抗摔跤手或布姆布姆大师吧。', `MaleText_loc5`='嗯... $c也來參賽，確實很有趣。好，讓我們見識見識你要怎樣對付摔跤手和砰砰大師吧。', `MaleText_loc7`='Hmm. $gUn:Una; $c es interesante, pero veamos cómo te las apañas contra El Luchador o el maestro Bum Bum.', `FemaleText_loc1`='흠. $c|1이라니;라니; 흥미롭긴 한데, 레슬러나 사부 뻥 뻥을 상대로 얼마나 잘 싸우는지 보죠.', `FemaleText_loc4`='嗯。一位$c可是颇具看点啊，但让我们看看你将如何对抗摔跤手或布姆布姆大师吧。', `FemaleText_loc5`='嗯... $c也來參賽，確實很有趣。好，讓我們見識見識你要怎樣對付摔跤手和砰砰大師吧。', `FemaleText_loc7`='Hmm. $gUn:Una; $c es interesante, pero veamos cómo te las arreglas contra El Luchador o el maestro Bum Bum.' WHERE `ID`=60892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날씨가 대회 구경하기에 딱이군요. 안 그렇습니까?', `MaleText_loc4`='真是个比赛的好日子啊，你觉得呢？', `MaleText_loc5`='真是個適合比賽的好日子，你說是吧?', `MaleText_loc7`='Un día estupendo para un torneo, ¿no te parece?', `FemaleText_loc1`='날씨가 대회 구경하기에 딱이네요. 안 그래요?', `FemaleText_loc4`='真是个比赛的好日子啊，你觉得呢？', `FemaleText_loc5`='真是個適合比賽的好日子，你說是吧?', `FemaleText_loc7`='Un día estupendo para un torneo, ¿no te parece?' WHERE `ID`=60893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 네 바람의 계곡에서 온 녀석한테 돈을 걸 거야.$b$b비취 숲에 있는 수도원에서 수련을 했다더라고.', `MaleText_loc4`='我把钱押在了其中一个小毛孩身上，他们都是从四风谷来的。$b$b听说他们曾受训于翡翠林的禅院。', `MaleText_loc5`='那些孩子來自四風峽，我的錢就壓在其中一個的身上。$b$b我聽說他們在翠玉林中的僧院進行訓練。', `MaleText_loc7`='He apostado mi dinero por uno de esos chicos llegados del Valle de los Cuatro Vientos.$b$bHe oído que han entrenado en el monasterio del Bosque de Jade.', `FemaleText_loc1`='나는 네 바람의 계곡에서 온 녀석한테 돈을 걸 거예요.$b$b비취 숲에 있는 수도원에서 수련을 했다더라고요.', `FemaleText_loc4`='我把钱押在了其中一个小毛孩身上，他们都是从四风谷来的。$b$b听说他们曾受训于翡翠林的禅院。', `FemaleText_loc5`='那些孩子來自四風峽，我的錢就壓在其中一個的身上。$b$b我聽說他們在翠玉林中的僧院進行訓練。', `FemaleText_loc7`='He apostado mi dinero por uno de esos chicos llegados del Valle de los Cuatro Vientos.$b$bHe oído que han entrenado en el monasterio del Bosque de Jade.' WHERE `ID`=60894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 사부 윈드퍼가 털끝 하나도 다치지 않고 호젠 열 마리를 상대하는 걸 본 적이 있어.', `MaleText_loc4`='我有一次看见风裘大师被十来个魔古族围攻，结果那些魔古族连一下都没能打中他。', `MaleText_loc5`='我曾見過風毛大師對上十幾個魔古，沒有一個魔古能碰到大師一根寒毛。', `MaleText_loc7`='Una vez vi al maestro Pelaje Recio luchar contra una docena de mogu y ninguno de ellos consiguió asestarle un golpe.', `FemaleText_loc1`='난 사부 윈드퍼가 털끝 하나도 다치지 않고 호젠 열 마리를 상대하는 걸 본 적이 있어요.', `FemaleText_loc4`='我有一次看见风裘大师被十来个魔古族围攻，结果那些魔古族连一下都没能打中他。', `FemaleText_loc5`='我曾見過風毛大師對上十幾個魔古，沒有一個魔古能碰到大師一根寒毛。', `FemaleText_loc7`='Una vez vi al maestro Pelaje Recio luchar contra una docena de mogu y ninguno de ellos consiguió asestarle un golpe.' WHERE `ID`=60895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레슬러는 가면을 절대 안 벗는대. 코가 간지러우면 어떻게 하나?', `MaleText_loc4`='我听说摔跤手从不摘下面具。我很好奇，要是他的鼻子发痒，该怎么解决呢。', `MaleText_loc5`='我聽說摔跤手從不脫下他的面具。我真好奇，如果他鼻子癢的時候該怎麼辦。', `MaleText_loc7`='He oído que El Luchador nunca se quita la máscara. ¿Qué será lo que haga cuando le pique la nariz...?', `FemaleText_loc1`='레슬러는 가면을 절대 안 벗는대요. 코가 간지러우면 어떻게 할까요?', `FemaleText_loc4`='我听说摔跤手从不摘下面具。我很好奇，要是他的鼻子发痒，该怎么解决呢。', `FemaleText_loc5`='我聽說摔跤手從不脫下他的面具。我真好奇，如果他鼻子癢的時候該怎麼辦。', `FemaleText_loc7`='He oído que El Luchador nunca se quita la máscara. ¿Qué será lo que haga cuando le pique la nariz...?' WHERE `ID`=60896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 덕분에 엄청난 거금을 땄습니다! 고맙습니다, 용사님!', `MaleText_loc4`='哇哦！你肯定想不到你刚刚为我赢了多少钱。谢谢你，勇士！', `MaleText_loc5`='哇喔!你不知道你剛剛為我贏了多少錢。謝謝你，勇士!', `MaleText_loc7`='¡Vaya! No te haces una idea del dinero que me has hecho ganar. ¡Muchas gracias, $gcampeón:campeona;!', `FemaleText_loc1`='우와! 덕분에 엄청난 거금을 땄어요! 고마워요, 용사님!', `FemaleText_loc4`='哇哦！你肯定想不到你刚刚为我赢了多少钱。谢谢你，勇士！', `FemaleText_loc5`='哇喔!你不知道你剛剛為我贏了多少錢。謝謝你，勇士!', `FemaleText_loc7`='¡Vaya! No te haces una idea del dinero que me has hecho ganar. ¡Muchas gracias, $gcampeón:campeona;!' WHERE `ID`=60897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 용사님이시군요! 당신이 대회에 매번 참가한다면, 전 떼돈을 벌 겁니다.', `MaleText_loc4`='啊，勇士！你每次比赛都要来啊。那我就要发财了。', `MaleText_loc5`='啊，勇士!你應該回來參加每一場比賽，這樣我就能賺大錢啦。', `MaleText_loc7`='¡Ah, $gcampeón:campeona;! Deberías participar en todos los torneos. Me harías ganar una fortuna.', `FemaleText_loc1`='아, 용사님이시군요! 당신이 대회에 매번 참가한다면, 전 떼돈을 벌 거예요.', `FemaleText_loc4`='啊，勇士！你每次比赛都要来啊。那我就要发财了。', `FemaleText_loc5`='啊，勇士!你應該回來參加每一場比賽，這樣我就能賺大錢啦。', `FemaleText_loc7`='¡Ah, $gcampeón:campeona;! Deberías participar en todos los torneos. Me harías ganar una fortuna.' WHERE `ID`=60898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단한 싸움이었습니다!', `MaleText_loc4`='真是几场漂亮的对决！', `MaleText_loc5`='那幾場戰鬥真是精采!', `MaleText_loc7`='¡Han sido unas peleas formidables!', `FemaleText_loc1`='정말 대단한 싸움이었어요!', `FemaleText_loc4`='真是几场漂亮的对决！', `FemaleText_loc5`='那幾場戰鬥真是精采!', `FemaleText_loc7`='¡Han sido unas peleas formidables!' WHERE `ID`=60899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 비극입니다...', `MaleText_loc4`='悲剧啊……', `MaleText_loc5`='真是一場悲劇...', `MaleText_loc7`='Qué gran tragedia...' WHERE `ID`=60900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 싸움은 평생 처음 봅니다! 정말 굉장했습니다.', `MaleText_loc4`='我以前还从未见到过如此精彩的打斗！你可真了不起。', `MaleText_loc5`='我從沒見過有人能像這樣戰鬥!你真是太不可思議了。', `MaleText_loc7`='¡Nunca había visto a nadie luchar como tú! Has estado increíble.', `FemaleText_loc1`='이런 싸움은 평생 처음 봐요! 정말 굉장했어요.', `FemaleText_loc4`='我以前还从未见到过如此精彩的打斗！你可真了不起。', `FemaleText_loc5`='我從沒見過有人能像這樣戰鬥!你真是太不可思議了。', `FemaleText_loc7`='¡Nunca había visto a nadie luchar como tú! Has estado increíble.' WHERE `ID`=60901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 싸움을 보게 되다니, 이까지 올라온 보람이 있군요!', `MaleText_loc4`='你去寺院习得的这身功夫真是让你不虚此行！', `MaleText_loc5`='光是看到你的戰鬥就不虛此行了!', `MaleText_loc7`='¡Tus peleas hacen que merezca la pena subir al templo!', `FemaleText_loc1`='이런 싸움을 보게 되다니, 이까지 올라온 보람이 있네요!', `FemaleText_loc4`='你去寺院习得的这身功夫真是让你不虚此行！', `FemaleText_loc5`='光是看到你的戰鬥就不虛此行了!', `FemaleText_loc7`='¡Tus peleas hacen que merezca la pena subir al templo!' WHERE `ID`=60902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레슬러가 내 옛 문하생을 꺾었다네. 이제 자네가 내 문하생이 되게. 자네한테서 행운 냄새가... 그리고 땀 냄새가 난다네. 아주 길한 일이지!$b$b레슬러는 굼뜨지만 강하다네. 녀석에게 잡히지 말게나.$b$b또 녀석은 정신력이 약하니, 투기장에 있는 의자로 녀석을 기절시키게.$b$b기운이 빠지면 내 옆에 있는 통을 사용하면 기운이 날 걸세.$b$b행운을 비네, 그루멀의 문하생!', `MaleText_loc4`='那个摔跤手干掉了我的老徒弟，现在你就是我的新徒弟了。你闻着臭臭的……还有汗腥味，这些都代表了好运气！$b$b摔跤手动作迟缓，但孔武有力，别让他抓到你。$b$b还有，他没什么脑子，利用场内的椅子砸晕他。$b$b你要是不行了，就用我旁边的水桶爽一下。$b$b祝你好运，土地精的徒弟！', `MaleText_loc5`='摔跤手打倒了我過去的徒弟。現在你是我的徒弟。你身上散發著好運...與汗水的味道。這可是最幸運的象徵!$b$b摔跤手動作很慢，但很強壯。別讓他靠近你。$b$b還有，他的意志不堅定，你可以用場中的椅子打昏他。$b$b如果累了，用我身邊這桶水來幫你提神。$b$b祝你好運，咕嚕摩的徒弟!', `MaleText_loc7`='El Luchador acabó con mi antiguo aprendiz. Ahora tú serás mi $gaprendiz:aprendiza;. Hueles a suerte y sudor. ¡Cosas que dan buena suerte!$b$bLuchador es lento pero fuerte. No dejes que te agarre.$b$bAdemás, su mente es débil. Utiliza las sillas de la arena para aturdirlo.$b$bSi te sientes débil, utiliza el cubo junto a mí para refrescarte.$b$b¡Buena suerte para ti, $gaprendiz:aprendiza; de grúmel!' WHERE `ID`=60903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 제 남편 걱정은 하지 마세요.$B$B미련퉁이 제 남편은 그냥 자는 거예요. 멍청한 머리를 진짜 세게 한 대 맞았는데, 한 잠자면 그냥 낫는답니다.', `FemaleText_loc4`='噢，不用为他担心。$B$B我那个白痴丈夫只是脑袋上挨了一下，睡一觉就好了。', `FemaleText_loc5`='喔，不用擔心他。$B$B我的笨蛋老公只是因為笨腦袋被打了一記而在睡覺。', `FemaleText_loc7`='Oh, no te preocupes por él.$B$BEl bobo de mi marido solo está durmiendo por culpa de un golpe tremendo en su dura mollera.' WHERE `ID`=60904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참게, 메이. 적의 수가 너무 많네. 자네까지 죽으면 내 아들은 어쩌란 말인가?', `MaleText_loc4`='继续持剑作战，阿梅。他们人太多了——万一你死了，我的儿子怎么办？', `MaleText_loc5`='不要出手，梅。他們人多勢眾，況且你死了的話，我的兒子怎麼辦?', `MaleText_loc7`='Contén tu espada, Mei. Hay demasiados... y si tú mueres, ¿qué será de mi hijo?' WHERE `ID`=60905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 안 된다 안 된다! 레슬러 일어나라! 일어나라!', `MaleText_loc4`='不！不不不不不！摔跤手，站起来！站起来蠢蛋！', `MaleText_loc5`='不!不不不不不!摔跤手站起來!站起來啊怪怪人!', `MaleText_loc7`='¡No! ¡No, no, no, no, no! ¡Luchador, levanta! ¡Levanta, makaku!' WHERE `ID`=60906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 놀고 있는 거냐, 이 까끌까끌한 초보 도마뱀 녀석아?!', `MaleText_loc4`='我的治疗呢？！你这下巴长毛的爬虫小渣滓！', `MaleText_loc5`='還不快治療，你這嘮叨的蜥蜴肉瘤矮子?!', `MaleText_loc7`='¡¿Dónde están mis sanaciones, lagarto desaliñado?!' WHERE `ID`=60907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아악! 이놈이 날 때리잖아! 끌어 가! 끌어 가라고!', `MaleText_loc4`='啊——！它在打我！坦住它！坦住它！', `MaleText_loc5`='啊啊啊!它正在打我!快拉走它!快拉走它!', `MaleText_loc7`='¡Aaah! ¡Me está pegando! ¡Quítamelo! ¡Quítamelo!' WHERE `ID`=60908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 모닥불과 따끈한 음식이 있으면 딱 좋겠군. 좋은 소식을 전하러 왔소?', `MaleText_loc4`='真希望马上能有一堆温暖的营火和一些热饭热菜。有好消息吗？', `MaleText_loc5`='我現在很想升個營火並弄些熱食來吃。你有帶好消息來嗎?', `MaleText_loc7`='Pagaría lo que fuese por una buena fogata y algo de comida caliente. ¿Traes buenas noticias?' WHERE `ID`=60909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최전선으로 귀환하라는 명령을 전하러 왔습니다.', `MaleText_loc4`='我接到命令让你回到前线。', `MaleText_loc5`='我帶來命令，要你回到前線去。', `MaleText_loc7`='Tengo órdenes para ti: vuelve al frente de batalla.', `FemaleText_loc1`='최전선으로 귀환하라는 명령을 전하러 왔어요.', `FemaleText_loc4`='我接到命令让你回到前线。', `FemaleText_loc5`='我帶來命令，要你回到前線去。', `FemaleText_loc7`='Tengo órdenes para ti: vuelve al frente de batalla.' WHERE `ID`=60910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='동료는 언제든 환영이지요. 혹시 전투식량이라도 가져오셨나요?', `FemaleText_loc4`='有朋自远方来，不亦乐乎。是来送给养的吗？', `FemaleText_loc5`='這裡歡迎友善的臉孔，有帶些糧食來嗎?', `FemaleText_loc7`='Se agradece ver una cara conocida. ¿Traes algo de comida?' WHERE `ID`=60911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 며칠째 눈도 한 번 못 붙이고 위치를 지키고 있습니다. 이대로 드러누울 수 있으면 원이 없겠군요.', `FemaleText_loc4`='我们已坚守此岗位数日之久，不眠不休。你不知道我有多么想躺下来休息一下。', `FemaleText_loc5`='我們已經在崗位上沒日沒夜地守了好幾天，你不知道我有多想就地躺下。', `FemaleText_loc7`='Llevamos días sin dormir en este puesto. No te puedes hacer una idea de cuánto necesito tumbarme.' WHERE `ID`=60912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 이렇게 득시글대는 건 처음 봅니다...', `MaleText_loc4`='它们的数量如此庞大，真是前所未见……', `MaleText_loc5`='我從沒見過這麼多的蟲群...', `MaleText_loc7`='Nunca he visto tantos...' WHERE `ID`=60913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인님, 뭘 하셔도 좋지만 저희 남편에게 계란 국수 조리법을 물어보지는 마세요. 밤이 새도록 이야기를 들어야 할 거예요.', `FemaleText_loc4`='无论如何，陌生人，你千万不要向我的丈夫打听他的鸡蛋面秘方。否则那将会成为你经历过的最冗长的一次谈话。', `FemaleText_loc5`='無論你做什麼，陌生人，不要問我丈夫關於他蛋麵食譜的事。那將是你所聽過最長篇大論的對話。', `FemaleText_loc7`='Hagas lo que hagas, $gforastero:forastera; ni se te ocurra preguntar a mi marido por su receta de tallarines de huevo. Puede ser la conversación más larga que hayas tenido en tu vida.' WHERE `ID`=60914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독한 녹옥 맥주를 획득했습니다! 이 맥주를 사용해 다수의 적들을 상대하십시오!', `MaleText_loc4`='你获得了烈性绿石佳酿！在战斗中使用它可以帮助你打败多个敌人。', `MaleText_loc5`='你得到了烈性綠石酒!在戰鬥中使用它來擊敗大量的敵人。', `MaleText_loc7`='¡Has recibido brebaje de Verdemar volátil! Úsalo en combate para poder derrotar a múltiples enemigos.' WHERE `ID`=60915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 복수심에 불타는 후이가 자신의 분노에 나가떨어졌습니다! 이제는 얌전해졌습니다.', `MaleText_loc4`='[PH]仇灰的愤怒已经消退！他已日渐冷静。', `MaleText_loc5`='[PH]他體內復仇之穢的憤怒已經撲滅了!他冷靜下來了。', `MaleText_loc7`='[PH] Vengeful Hui''s anger has been beaten out of him! He has grown calm.' WHERE `ID`=60916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 이보십시오들, 모두 정말 죄송합니다. 친구들...?', `MaleText_loc4`='[PH]嗨，各位。对此我真的感到非常抱歉。朋友……？', `MaleText_loc5`='[PH]嘿老兄，我對這一切感到很抱歉。還是朋友嗎...?', `MaleText_loc7`='[PH] Hey guys, I''m really sorry about all that. Friends...?' WHERE `ID`=60917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 겨누고 있다, 이 원숭이 녀석아!', `MaleText_loc4`='我看见你了，猴子！', `MaleText_loc5`='我看到你了，猴子!', `MaleText_loc7`='¡Te tengo en el punto de mira, macaco!' WHERE `ID`=60918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 얼라이언스에서 드디어 지원군을 보낸 모양이지? $c님, 앞으로 오십시오!', `MaleText_loc4`='这么说，联盟终于下决心派援兵来了，嗯？快到前线上去，$c！', `MaleText_loc5`='聯盟終於決定要派點援軍過來了嗎?快到前線去，$c!', `MaleText_loc7`='Así que la Alianza se ha decido por fin a enviar algunos refuerzos, ¿eh? ¡Al frente, $c!' WHERE `ID`=60919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 올 줄 알았습니다! 한 번도 의심한 적 없어요!', `MaleText_loc4`='我就知道他们会派援军来的！我对此深信不疑！', `MaleText_loc5`='我早就知道他們會派援軍來!從來都沒有懷疑過!', `MaleText_loc7`='¡Sabía que enviarían refuerzos! ¡Nunca me cupo la menor duda!' WHERE `ID`=60920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 방어벽을 넘어 옵니다! 막아내십시오!', `MaleText_loc4`='他们正越过我们的工事！把他们打回去！', `MaleText_loc5`='他們正越過我們的據點!將他們逼退!', `MaleText_loc7`='¡Están traspasando las barricadas! ¡Hacedlos retroceder!' WHERE `ID`=60921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽느냐 죽이느냐 하는 상황입니다! 저 미치광이 괴물들의 미간을 정확히 조준하십시오!', `MaleText_loc4`='伙计们，是生是死就看这一战了！不要盲目射击，直到你们能看清他们眼中的疯狂时，再狠狠宣泄你们的子弹吧！', `MaleText_loc5`='不這麼做就死路一條，弟兄們!看見他們瘋狂的眼神再開始射擊!', `MaleText_loc7`='¡Soldados, es un asunto de vida o muerte! ¡No disparen hasta que vean la locura en sus ojos!' WHERE `ID`=60922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 멍하니 서서 뭘 하는 겁니까, $r님? 모두 전투에 참여해야 합니다!', `MaleText_loc4`='你在那儿发什么愣呢，$r？我们需要所有人都上前线！', `MaleText_loc5`='你待在這裡做甚麼，$r?我們需要每個人到前線去!', `MaleText_loc7`='¿A qué estás esperando, $r? ¡Necesitamos a todo el mundo en el frente!' WHERE `ID`=60923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='본부에서 영웅들을 보내줄 때가 되었다고 생각했습니다. 저기 나가서 싸우십시오, $c님!', `MaleText_loc4`='他们也该从总部派几个英雄过来了。出来战斗吧，$c！', `MaleText_loc5`='是他們該從總部送些英雄過來了的時候了。快出去戰鬥，$c!', `MaleText_loc7`='Ya era hora de que enviaran a algunos héroes del cuartel general. ¡Ve y lucha, $c!' WHERE `ID`=60924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 꼬리 긴 망나니들에게 얼라이언스의 힘을 보여줍시다! 돌격!', `MaleText_loc4`='让那些长尾巴的混蛋看看联盟的力量吧！冲锋！', `MaleText_loc5`='讓我們給那些長尾毛賊瞧瞧聯盟的能耐!衝鋒!', `MaleText_loc7`='¡Demostremos a esos peludos anaranjados de qué está hecha la Alianza! ¡Cargad!' WHERE `ID`=60925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 끝없이 몰려듭니다, $c님! 저들을 막아낼 수 있게 도와주십시오!', `MaleText_loc4`='他们人太多了，$c！快帮我们挡住他们！', `MaleText_loc5`='他們的數量無窮無盡，$c!幫我們抵擋他們!', `MaleText_loc7`='¡Sus efectivos son innumerables, $c! ¡Ayúdanos a retenerlos!', `FemaleText_loc1`='적들이 끝없이 몰려듭니다, $c님! 저들을 막아낼 수 있게 도와주십시오!', `FemaleText_loc4`='他们人太多了，$c！快帮我们挡住他们！', `FemaleText_loc5`='他們的數量無窮無盡，$c!幫助我們將他們擋下!', `FemaleText_loc7`='¡Sus efectivos son innumerables, $c! ¡Ayúdanos a retenerlos!' WHERE `ID`=60926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R님, 여깁니다! 적을 몰아냅시다!', `MaleText_loc4`='$R，这边！把他们赶回来！', `MaleText_loc5`='$R，來這裡!逼退他們!', `MaleText_loc7`='¡Aquí, $r! ¡Hazlos retroceder!', `FemaleText_loc1`='$R님, 여깁니다! 적을 몰아냅시다!', `FemaleText_loc4`='$R，这边！把他们赶回来！', `FemaleText_loc5`='$R，來這裡!逼退他們!', `FemaleText_loc7`='¡Aquí, $r! ¡Hazlos retroceder!' WHERE `ID`=60927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 스톰윈드에서 지원군을 보냈나요? $C님 나가신다!', `MaleText_loc4`='嚯，他们从暴风城派援军来了吗？$C都上战场了！', `MaleText_loc5`='喔，他們從暴風城派來更多援軍了嗎?$C要上場啦!', `MaleText_loc7`='Vaya, ¿han enviado más refuerzos de Ventormenta? ¡$C en el campo!', `FemaleText_loc1`='이야, 스톰윈드에서 지원군을 보냈나요? $C님 나가신다!', `FemaleText_loc4`='嚯，他们从暴风城派援军来了吗？$C都上战场了！', `FemaleText_loc5`='喔，他們從暴風城派來更多援軍了嗎?$C要上場啦!', `FemaleText_loc7`='Vaya, ¿han enviado más refuerzos de Ventormenta? ¡$C en el campo!' WHERE `ID`=60928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위하여!', `MaleText_loc4`='为了联盟！', `MaleText_loc5`='為了聯盟!', `MaleText_loc7`='¡Por la Alianza!', `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=60929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다... 더는 견뎌낼 수 없었습니다.', `MaleText_loc4`='非常感谢……我已经坚持不了多久了。', `MaleText_loc5`='非常感謝...再久一點的話我可能就抵擋不住了。', `MaleText_loc7`='Muchas gracias... No habría aguantado mucho más.' WHERE `ID`=60930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 돌아오셨군요! 정말 고맙습니다. 이걸 받아주십시오 우리가 만든 술 중 가장 강력한 술이지요. 바로 독한 녹옥 맥주입니다.', `MaleText_loc4`='啊，你回来了！太感谢你了。拜托，请你一定要收下这个。这是我们这儿最烈的酒：烈性绿石佳酿。', `MaleText_loc5`='啊，你回來了!十二萬分的感謝你。請拿走這個，這是我們最夠力的創作:烈性綠石酒。', `MaleText_loc7`='¡Ah, habéis vuelto! Mil gracias. Por favor, tomad esto. Es nuestra creación más potente: el brebaje de Verdemar volátil.' WHERE `ID`=60931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구르단 부족이 폐하와 권력에 굶주린 너희 애송이들에게 보여주마. 왜 우리가 폐하를 보좌해야 하는지!', `MaleText_loc4`='格尔桑氏族会向王上和其他像你们这样利欲熏心的骗子证明，我们才是王上真正的拥护者！', `MaleText_loc5`='葛薩恩部族會讓你們這些想要權力的傢伙知道為什麼我們才是王身邊真正的勇士!', `MaleText_loc7`='¡El clan Gurthan demostrará al Rey y a los impostores sedientos de poder como ustedes por qué merecemos su confianza!' WHERE `ID`=60932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 카게쉬 부족이 왕을 보좌할 만한 힘을 가진 유일한 부족인지 보여주겠다!', `MaleText_loc4`='克尔格西氏族会让你知道，为什么只有强者才配站在我们国王的身边！', `MaleText_loc5`='卡傑許部族會展示出強者才有資格替王效勞的原因!', `MaleText_loc7`='¡El clan Kargesh les demostrará por qué solo los más fuertes merecen servir al Rey!' WHERE `ID`=60933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하르닥 부족이 왜 모구 최고의 부족인지 보여주마!', `MaleText_loc4`='哈飒克氏族会向所有人证明，我们才是血统最纯正的魔古！', `MaleText_loc5`='哈薩科會讓所有人看看為什麼我們才是真正的魔古!', `MaleText_loc7`='¡El clan Harthak les demostrará por qué somos los más puros de los mogu!' WHERE `ID`=60934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야호! 우리가 놈들을 몰아냈습니다! 그래, 이 원숭이들아! 꽁지가 빠지게 도망가라!', `MaleText_loc4`='呀——哈，我们击退了他们！这就对了，猴子们，夹着你们的小尾巴逃跑吧！', `MaleText_loc5`='耶耶哈，我們把他們逼退了!!沒錯，猴崽子們，快夾著尾巴逃跑吧。', `MaleText_loc7`='¡Hurra, les hemos hecho retroceder! ¡Eso es, macacos, vayan con sus sucias colas a otra parte!' WHERE `ID`=60935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 강철 맛은 견딜 수 없었던 모양입니다. 정말 큰 활약을 보여주셨습니다, $n 님.', `MaleText_loc4`='看来他们抵挡不住联盟的利剑了。干得好，$n。', `MaleText_loc5`='看來他們消受不了聯盟刀劍的滋味。做得好，$n。', `MaleText_loc7`='Parece que no les ha gustado probar el acero de la Alianza. Buen trabajo, $n.' WHERE `ID`=60936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족이 타락했습니다...

이곳의 전사 샤이 후가 처음으로 오염된 물을 마셨습니다.

그는 강력해지고 대담해지더니, 다른 이들에게도 물을 마시라고 했지요.

저는 그러면 안 된다고 경고했습니다. 위험과 타락이 느껴졌기 때문입니다...', `MaleText_loc4`='我的人民被腐蚀了……

我们当地的战士刹嗳呼是第一个饮用污染水的人。

他变得更强壮，尝到了甜头，并鼓励其他人也这么做。

我警告过他们不要听他的。我感觉到了危险，是腐蚀术……', `MaleText_loc5`='我的人民被腐化了...

當地的戰士夏虎是第一個喝下汙腐之水的人。

他變得強壯、大膽，並慫恿其他人做同樣的事。

我警告過他們不要。我察覺到危險、腐敗逼近...', `MaleText_loc7`='Mi gente, corrompida...

Shai Hu, un guerrero local, fue el primero en beber de las aguas contaminadas.

Se hizo más fuerte y valiente, e instó a los demás a hacer lo mismo.

Les advertí que no lo hicieran. Percibí peligro, corrupción...' WHERE `ID`=60937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와... 내 발굽 지이인짜 크구나...', `MaleText_loc4`='天啊……我的蹄子好大……', `MaleText_loc5`='哦喔...我的蹄子好大...', `MaleText_loc7`='Uooo... Mis pezuñas son enooormes...' WHERE `ID`=60938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀 부적이 효과를 보이고 있어...', `MaleText_loc4`='这些土地精护身符开始起作用了……', `MaleText_loc5`='這些咕嚕摩的幸運符開始見效了...', `MaleText_loc7`='Estos amuletos grúmel están empezando a surtir efecto...' WHERE `ID`=60939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀이 빚는 술은 참 이상하단 말이야.', `MaleText_loc4`='这些土地精酿的酒真奇怪。', `MaleText_loc5`='這些咕嚕摩製造了一杯古怪的烈酒。', `MaleText_loc7`='Estos grúmel hacen un grog extraño.' WHERE `ID`=60940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하네... 그루멀 녀석들이 말하는 복 냄새가 나는 것 같아...', `MaleText_loc4`='这感觉……就好像我能闻到土地精的臭味……', `MaleText_loc5`='就...就好像我可以聞到咕嚕摩幸運的氣味...', `MaleText_loc7`='Es... es como si pudiera oler la suerte de los grúmel...' WHERE `ID`=60941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복이 굴러드는 소리가 들리는 것 같아...', `MaleText_loc4`='我觉得我变得更加幸运了……', `MaleText_loc5`='我好像聽見自己變得更幸運的聲音...', `MaleText_loc7`='Creo que puedo oír cómo aumenta mi suerte...' WHERE `ID`=60942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리들은 운명을 지배할 이 정당한 권리를 결코 포기하지 않을 것이다!', `MaleText_loc4`='我们绝不交出决定我们族人命运的权利！', `MaleText_loc5`='我們永遠不會放棄主導我們人民命運的權利!', `MaleText_loc7`='¡Nunca renunciaremos al derecho a controlar el destino de nuestro pueblo!' WHERE `ID`=60943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족이 진짜 부족이다! 그건 영원불멸의 진리야!', `MaleText_loc4`='我们氏族才是真正的氏族！任何闯入者都无法改变这一点！', `MaleText_loc5`='我們是真正的部族!外來者無法改變這一點!', `MaleText_loc7`='¡Nuestro clan es el único clan! ¡Ningún intruso cambiará eso!' WHERE `ID`=60944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼! 우리의 힘은 제국 최강이다!', `MaleText_loc4`='这不可能！我们是全帝国最强大的！', `MaleText_loc5`='不可能!我們的力量是帝國裡最強的!', `MaleText_loc7`='¡Imposible! ¡Nuestra fuerza no tiene rival en todo el imperio!' WHERE `ID`=60945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가라. 우리 팀 일은 우리가 알아서 한다.', `MaleText_loc4`='滚开，我们队能自己解决。', `MaleText_loc5`='走開。我的隊伍可以自己處理。', `MaleText_loc7`='Márchate. Mi equipo puede arreglárselas solo.' WHERE `ID`=60946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탱키스가 나한테 불똥이 튀지 않게 할 줄만 알았어도 이 꼴이 되진 않았을 텐데.', `MaleText_loc4`='要是坦齐斯能够照看好他的治疗者，我们也不至于搞的一塌糊涂。', `MaleText_loc5`='如果坦奇思懂得讓他的醫者遠離火線，那我們就不會陷在這一團混亂裡面。', `MaleText_loc7`='No estaríamos metidos en este lío si Tanquiss hubiera aprendido a quitarle la amenaza a su sanador.' WHERE `ID`=60947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 구석에 그루멀빵이 있었지 뭐야! 끝내주게 맛있네! 오늘은 정말 최고의 날이야!', `MaleText_loc4`='我在笼子的角落里发现一个土地精烤饼，太好吃了！真是最棒的一天！', `MaleText_loc5`='我在我籠子的角落發現一塊咕嚕摩蛋糕。超好吃的!今天真是棒透了!', `MaleText_loc7`='He encontrado un pastel grúmel en un rincón de mi jaula. ¡Estaba delicioso! ¡El mejor día de mi vida!' WHERE `ID`=60948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나에 님! 그 안에 계십시오! 여행자여, 자애로운 어머니께 필요한 건 없으신지 여쭤봐 주십시오. 그분은 이 안의 생존자들을 치유하기 위해 쉴 틈 없이 애쓰고 계십니다.', `MaleText_loc4`='待在屋里，韩妮！冒险者，请你看看这位温柔的大妈有什么要帮忙的。她正不知疲倦地照料着屋里的幸存者。', `MaleText_loc5`='待在裡面，漢妮!冒險者，請去看看漢妮是否需要任何東西。她正不眠不休地照顧著裡面的倖存者。', `MaleText_loc7`='¡No salgas, Hanae! $gAventurero:Aventurera;, comprueba si la dulce madre necesita algo. Trabaja sin descanso para atender a los sobrevivientes.' WHERE `ID`=60949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위험하다고요? 하! 이 정도는 아무 것도 아니죠!$B$B가장 위험한 상황을 이겨내야 가장 맛있는 음식을 손에 넣을 수 있다는 말도 못 들어보셨나요?', `FemaleText_loc4`='危险？哈！我才不怕什么危险！$B$B难道你不知道最美味的食物也是最难获得的吗？', `FemaleText_loc5`='危險?哈!我吃危險長大的!$B$B你不知道最難取得的食物也都是最美味的食物嗎?', `FemaleText_loc7`='¿Peligro? ¡Ja! Me rio en la cara del peligro.$b$b¿No sabes que los platos más ricos son los más peligrosos de conseguir?' WHERE `ID`=60950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 모구에게 맞설 수 있을 줄 알았습니다. 그저 당신 같은 분께서 그 방법을 알려주기만 하면 되는 거였습니다.', `MaleText_loc4`='我知道，他们完全有反抗魔古族的力量——只是需要一个像你这样英雄为他们做出榜样。', `MaleText_loc5`='我就知道他們有能力可以反抗魔古，他們只需要一個像你這樣的人教他們如何去做。', `MaleText_loc7`='Sabía que dentro de ellos escondían el poder para derrotar a los mogu. Solo necesitaban a alguien como tú para enseñarles a exteriorizarlo.' WHERE `ID`=60951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 오셨는지는 모르지만, 오늘 하신 것처럼 계속해서 정의를 위해 싸워 주실 분이시라면, 판다리아에 오신 것을 진심으로 환영합니다.$B$B감사합니다.', `MaleText_loc4`='我不知道你是从哪儿来的，但只要你继续能如今天这般主持正义，那潘达利亚欢迎你的到来。$B$B谢谢你。', `MaleText_loc5`='我不知道你來自何方，但假如你繼續像你今天這樣為了正義挺身而出，你在潘達利亞將到處受歡迎。$B$B謝謝你。', `MaleText_loc7`='No sé de dónde has salido, pero si sigues defendiendo la justicia como lo has hecho hoy, serás $gbienvenido:bienvenida; en Pandaria.' WHERE `ID`=60952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이여, 서두르십시오! 샤이 후가 피에 목말라 있습니다!', `MaleText_loc4`='再快些，史密斯！刹嗳呼渴望鲜血！', `MaleText_loc5`='快點，鐵匠!夏虎渴望鮮血!', `MaleText_loc7`='¡Más rápido, herrero! ¡Shai Hu está sediento de sangre!' WHERE `ID`=60953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일이 끝나기는 하는 겁니까? 또 격려가 필요합니까?', `MaleText_loc4`='你到底要到什么时候才能完成呀，铁匠？你是不是还想要额外的鼓励？', `MaleText_loc5`='你到底什麼時候才會完成工作，鐵匠?也許你需要額外的激勵?', `MaleText_loc7`='¿Podrás terminar algún día, herrero? Quizá necesitas que te anime un poco...' WHERE `ID`=60954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리 일하지 않으면 오라키가 내 목을 칠 겁니다! 그 전에 내가 당신 목을 칠 거고요.', `MaleText_loc4`='如果你不快点干完，太蛇就要把我杀掉了，史密斯！到时候我先把你杀掉。', `MaleText_loc5`='你再不快點的話，歐拉奇會砍我的頭，鐵匠!而我會砍你的頭!', `MaleText_loc7`='¡Orachi me cortará la cabeza si no trabajas más rápido, herrero! Y yo cortaré la tuya.' WHERE `ID`=60955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 다물어라, 사제! 내 일에 대해 뭘 안다고 떠드느냐!', `MaleText_loc4`='安静，牧师！你根本不了解我的工作！', `MaleText_loc5`='肅靜，司祭!你一點都不了解我的成就!', `MaleText_loc7`='¡Silencio, sacerdote! ¡Tú no sabes nada sobre mi trabajo!' WHERE `ID`=60956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 무례하게 지껄여 봤자 나는 눈 하나 깜짝하지 않는다.', `MaleText_loc4`='你无礼的话吓不倒我，蠢货。', `MaleText_loc5`='你那無禮的言語嚇唬不了我的，蠢材。', `MaleText_loc7`='Tu insolente charlatanería no me intimida, idiota.' WHERE `ID`=60957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마실 것 좀 줄까? 내 맥주는 맥주 중에서도 가장 쓴데, 과연 그걸 마실 자격이 있을까?', `FemaleText_loc4`='你需要什么？我这里有最烈的老酒。你敢试试吗？', `FemaleText_loc5`='你需要什麼嗎?我釀的是世上最苦澀的啤酒。你有資格喝這啤酒嗎?', `FemaleText_loc7`='¿Deseas algo? Mi cerveza es la más amarga. ¿Crees que la mereces?' WHERE `ID`=60958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다.', `MaleText_loc4`='我要感谢你。', `MaleText_loc5`='我非常感謝你。', `MaleText_loc7`='Tienes mi gratitud.', `FemaleText_loc1`='정말 감사해요.', `FemaleText_loc4`='我要感谢你。', `FemaleText_loc5`='我非常感謝你。', `FemaleText_loc7`='Tienes mi gratitud.' WHERE `ID`=60959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다.', `MaleText_loc4`='没错。', `MaleText_loc5`='是的。我願意。', `MaleText_loc7`='Sí, quiero.', `FemaleText_loc1`='네, 알겠습니다.', `FemaleText_loc4`='没错。', `FemaleText_loc5`='是的。我願意。', `FemaleText_loc7`='Sí, quiero.' WHERE `ID`=60960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 알겠습니다.', `MaleText_loc4`='没错。', `MaleText_loc5`='是的。我願意。', `MaleText_loc7`='Sí, quiero.', `FemaleText_loc1`='네, 알겠습니다.', `FemaleText_loc4`='没错。', `FemaleText_loc5`='是的。我願意。', `FemaleText_loc7`='Sí, quiero.' WHERE `ID`=60961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 전문화를 초기화하고 싶습니다.', `MaleText_loc4`='我想要重置我的职业专精。', `MaleText_loc5`='我想要遺忘我的職業專精。', `MaleText_loc7`='Quiero restablecer mi especialización de clase.', `FemaleText_loc1`='직업 전문화를 초기화하고 싶습니다.', `FemaleText_loc4`='我想要重置我的职业专精。', `FemaleText_loc5`='我想要遺忘我的職業專精。', `FemaleText_loc7`='Quiero restablecer mi especialización de clase.' WHERE `ID`=60962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문양을 제거하고 싶습니다.', `MaleText_loc4`='我想要移除我的雕文。', `MaleText_loc5`='我想要移除我的雕紋。', `MaleText_loc7`='Deseo restablecer mis glifos.', `FemaleText_loc1`='문양을 제거하고 싶습니다.', `FemaleText_loc4`='我想要移除我的雕文。', `FemaleText_loc5`='我想要移除我的雕紋。', `FemaleText_loc7`='Deseo restablecer mis glifos.' WHERE `ID`=60963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다!', `MaleText_loc4`='太感谢你了！', `MaleText_loc5`='我非常感謝你!', `MaleText_loc7`='¡Tenéis mi gratitud!', `FemaleText_loc1`='고마워요!', `FemaleText_loc4`='太感谢你了！', `FemaleText_loc5`='我非常感謝你!', `FemaleText_loc7`='¡Tenéis mi gratitud!' WHERE `ID`=60964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹옥 마을에 희망이 보이는군요! 감사합니다!', `MaleText_loc4`='绿石村有救了！谢谢你！', `MaleText_loc5`='綠石有希望了!謝謝你!', `MaleText_loc7`='¡Hay esperanza para Verdemar! ¡Gracias!', `FemaleText_loc1`='녹옥 마을에 희망이 보이네요! 고마워요!', `FemaleText_loc4`='绿石村有救了！谢谢你！', `FemaleText_loc5`='綠石有希望了!謝謝你!', `FemaleText_loc7`='¡Hay esperanza para Verdemar! ¡Gracias!' WHERE `ID`=60965;
