UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네베레스트 산에서 녹색 새의 깃털을 주웠다네. 네베레스트에는 원래 녹색 새가 안 살거든. 그러니 굉장한 복덩이지.', `MaleText_loc4`='我曾在不息山上捡到过一根大绿鸟的羽毛。在不息山上可没有绿鸟啊。这真是个幸运符。', `MaleText_loc5`='我曾在奈佛勒斯從一隻大綠鳥身上拿到一根羽毛。奈佛勒斯那裡從來沒有綠色的鳥。這是很棒的好運氣。', `MaleText_loc7`='Una vez encontré una pluma de un enorme pájaro verde en Nieverest. Ningún pájaro verde sobrevuela Nieverest. Es un grisgrís muy bueno.' WHERE `ID`=60968;
