UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘밤 여기 머물면서 내 물건을 사면 복이 찾아올 걸세.', `MaleText_loc4`='今晚留在这儿，选购我的商品，好运定会伴你左右。', `MaleText_loc5`='今晚留在這兒，買我的商品，好運一定會照耀在你身上。', `MaleText_loc7`='Quédate aquí esta noche, compra mis mercancías y la fortuna te sonreirá con toda seguridad.' WHERE `ID`=60971;
