UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 모구에 저항하려 하느냐? 죽음으로 사죄하라!', `MaleText_loc4`='你胆敢反抗魔古族？那么你就死定了！', `MaleText_loc5`='你膽敢違抗魔古?你會為此喪命!', `MaleText_loc7`='¿Te atreves a desafiar a los mogu? Entonces, morirás.' WHERE `ID`=60988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영광스러운 우리 제국이 부활할 것이다! 하지만 그때쯤 너희는 존재하지 않을 것이다!', `MaleText_loc4`='我们的帝国壮丽辉煌！而你们都将看不到那一天！', `MaleText_loc5`='我們的帝國會再次興盛!而你活不到那天了!', `MaleText_loc7`='Nuestro imperio será glorioso. ¡Y tú no lo verás!' WHERE `ID`=60989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에 복종하지 않는 놈들은 용납하지 않겠다!', `MaleText_loc4`='我绝不容忍这种违逆！', `MaleText_loc5`='我不會容忍這種踰矩犯上!', `MaleText_loc7`='¡No toleraré esta desobediencia!' WHERE `ID`=60990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 의식은 거행해 본 적이 없습니다. 정확히 어떤 일이 일어날지 모릅니다.', `MaleText_loc4`='我从来没有举行过这样的仪式。我根本就不知道接下来会发生什么。', `MaleText_loc5`='我從來沒有進行過這個儀式，不清楚到底會發生什麼。', `MaleText_loc7`='Nunca he realizado este ritual. No sé qué es lo que va a pasar a ciencia cierta.' WHERE `ID`=60991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대로부터 전해 내려온 의식인데, 지금까지는 이 의식을 거행할 필요가 한 번도 없었지요.', `MaleText_loc4`='这是从古时候传下来的，但我们的人民从来不需要用到这个。', `MaleText_loc5`='這從古代就流傳下來，但是從來沒有人使用過它。', `MaleText_loc7`='Se ha transmitido desde tiempos ancestrales, pero nadie de nuestra gente ha necesitado utilizarlo desde entonces.' WHERE `ID`=60992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것으로 우리 민족의 영혼에서 타락의 기운을 몰아낼 수 있을지 보지요.', `MaleText_loc4`='让我们看看这个是否足以净化我族人被腐化的灵魂。', `MaleText_loc5`='讓我們看看這是否足夠淨化我人民靈魂中的腐敗。', `MaleText_loc7`='Veamos si es suficiente para limpiar la corrupción de las almas de mi pueblo.' WHERE `ID`=60993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부들이 도발하는 동안에는 고르말이 받는 피해가 증가합니다!', `MaleText_loc4`='格玛尔遭到了农夫的嘲讽，受到额外的伤害！', `MaleText_loc5`='戈爾莫被農夫嘲諷時會受到額外的傷害!', `MaleText_loc7`='¡Gormal recibe daño extra mientras lo provoca un granjero!' WHERE `ID`=60994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 무리를 경계해야 합니다. 조상님, 혹시라도 놈들이 최전선을 기습하기라도 하면 우리를 보살펴 주십시오.', `MaleText_loc4`='那便是我们顾虑已久的虫群。如果他们决意突破前线，那我们只有祈求先祖保佑了。', `MaleText_loc5`='我們得為蟲群做好準備。如果他們決定衝開前線，我們只能祈求祖先保佑了。', `MaleText_loc7`='Ese enjambre es lo que nos espera. Que los ancestros nos ayuden si deciden atacar el frente de batalla.' WHERE `ID`=60995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='후임이 오면, 주 통로를 통해 침투를 시도하는 사마귀가 아주 많다고 전해 주세요. 쉬운 보직이 아니에요.', `FemaleText_loc4`='让换我班的人知道有多少螳螂妖试图从主通道悄悄溜进来，这个岗位可马虎不得。', `FemaleText_loc5`='讓接替我的人知道，曾有很多螳螂人試著從主通道溜進來。這可不是個輕鬆的崗位。', `FemaleText_loc7`='Dile a mi reemplazo que un montón de mántides han estado intentando entrar a hurtadillas por el canal principal. No es un puesto fácil.' WHERE `ID`=60996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기대한 것보다 더 좋은 소식이군. 빨리 따뜻한 침대에 들고 싶소.', `MaleText_loc4`='比我预期的消息还要好。我需要一张暖床。', `MaleText_loc5`='這還真是個好消息。希望能有張溫暖的床。', `MaleText_loc7`='Es aún mejor de lo que esperaba. Necesito una buena cabezadita.' WHERE `ID`=60997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='휴식이라니, 식량보다 더 좋네요. 여기 조금 더 있어야 할 줄 알았어요.', `FemaleText_loc4`='比给养还要好——休息。我觉得我一时半会还不会离开这里。', `FemaleText_loc5`='比糧食更好的東西是休息。我想我得離開這裡一會兒。', `FemaleText_loc7`='Esto es incluso mejor que la comida. Descanso. Pensé que estaría aquí aun más tiempo.' WHERE `ID`=60998;
