UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어떻게 된 거지? 왜 의식이 메이에게 영향을 주고 있지?', `MaleText_loc4`='发……发生什么了？为什么她会受到仪式的影响？', `MaleText_loc5`='怎...怎麼回事?為什麼儀式會影響到她?', `MaleText_loc7`='¿Qué... qué está ocurriendo? ¿Por qué le está afectando a ella el ritual?' WHERE `ID`=61000;
