UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백호사 무술 대회의 첫 번째 규칙은, 백호사 무술 대회에 대해 이야기하지 않는 겁니다.', `MaleText_loc4`='白虎寺比武大赛第一条规则：我们从不提白虎寺比武大赛。', `MaleText_loc5`='白虎寺錦標賽的第一條規矩:我們不談論白虎寺錦標賽。', `MaleText_loc7`='La primera regla del Torneo del Templo del Tigre: nadie habla sobre el Torneo del Templo del Tigre.' WHERE `ID`=61002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 죽은 목숨이라고 생각했습니다. 당신은 제 생명의 은인이십니다.', `MaleText_loc4`='我以为自己死定了。我欠你一条命。', `MaleText_loc5`='若不是你出現，我有可能會被老虎吃掉。我欠你一條命。', `MaleText_loc7`='Creía que estaba condenado. Te debo la vida.', `FemaleText_loc1`='이제 죽은 목숨이라고 생각했어요. 당신은 제 생명의 은인이에요.', `FemaleText_loc4`='我以为自己死定了。我欠你一条命。', `FemaleText_loc5`='要不是你出現，我可能已經被老虎吃掉了。我欠你一條命。', `FemaleText_loc7`='Creía que estaba condenada. Te debo la vida.' WHERE `ID`=61003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사합니다. 얼라이언스를 위하여!', `MaleText_loc4`='谢谢你救了我。为了联盟！', `MaleText_loc5`='感謝你救了我。為了聯盟!', `MaleText_loc7`='Gracias por rescatarme. ¡Por la Alianza!', `FemaleText_loc1`='구해주셔서 감사해요. 얼라이언스를 위하여!', `FemaleText_loc4`='谢谢你救了我。为了联盟！', `FemaleText_loc5`='感謝你救了我。為了聯盟!', `FemaleText_loc7`='Gracias por rescatarme. ¡Por la Alianza!' WHERE `ID`=61004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구. 치열한 전투였습니다. 하지만 얼라이언스의 푸른 병력이 승리할 줄 알았습니다!', `MaleText_loc4`='谢谢，朋友。真是枪林弹雨啊，但我知道联盟的蓝色一定会全线告捷！', `MaleText_loc5`='謝謝，朋友。那還真是場猛烈的火拼，但我知道聯盟會渡過難關的!', `MaleText_loc7`='Muchas gracias. Ha sido una batalla encarnizada, ¡pero sé que la Alianza es digna de confianza!', `FemaleText_loc1`='고마워요. 치열한 전투였어요. 하지만 얼라이언스의 푸른 병력이 승리할 줄 알았죠!', `FemaleText_loc4`='谢谢，朋友。真是枪林弹雨啊，但我知道联盟的蓝色一定会全线告捷！', `FemaleText_loc5`='謝謝，朋友。那還真是場猛烈的火拼，但我知道聯盟會渡過難關的!', `FemaleText_loc7`='Muchas gracias. Ha sido una batalla encarnizada, ¡pero sé que la Alianza es digna de confianza!' WHERE `ID`=61005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 친구. 걱정 마십시오. 그냥 긁힌 상처입니다. 이제 다시 태어난 것처럼 기운이 나네요!', `MaleText_loc4`='谢谢你，朋友。别担心，只是皮外伤。我现在又生龙活虎了！', `MaleText_loc5`='謝謝你，朋友。別擔心，這只是擦傷。現在我感覺煥然一新!', `MaleText_loc7`='Gracias. No te preocupes, solo era un rasguño. ¡Me siento como nuevo!', `FemaleText_loc1`='고마워요. 너무 걱정 마세요. 그냥 긁힌 상처니까요. 이제 다시 태어난 것처럼 기운이 나네요!', `FemaleText_loc4`='谢谢你，朋友。别担心，只是皮外伤。我现在又生龙活虎了！', `FemaleText_loc5`='謝謝你，朋友。別擔心，這只是擦傷。現在我感覺煥然一新!', `FemaleText_loc7`='Gracias. No te preocupes, solo era un rasguño. ¡Me siento como nueva!' WHERE `ID`=61006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 동료를 만나니 기분이 좋습니다! 여기서 죽게 될 거라고 생각하던 참이었습니다.', `MaleText_loc4`='又见到一张联盟的脸孔，真是太好了！我还以为自己死定了。', `MaleText_loc5`='能看見另一個聯盟的臉孔真好!我還以為我會死在這裡。', `MaleText_loc7`='¡Me alegro de ver otra cara de la Alianza! Pensaba que iba a morir aquí.', `FemaleText_loc1`='얼라이언스 동료를 만나니 기분이 좋네요! 여기서 죽게 될 거라고 생각했거든요.', `FemaleText_loc4`='又见到一张联盟的脸孔，真是太好了！我还以为自己死定了。', `FemaleText_loc5`='能看見另一個聯盟的臉孔真好!我還以為我會死在這裡。', `FemaleText_loc7`='¡Me alegro de ver otra cara de la Alianza! Pensaba que iba a morir aquí.' WHERE `ID`=61007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저것이 마을 사람들을 조종하고 있었던 거로군요! 이제 어떻게 해야 할지 알겠습니다.', `MaleText_loc4`='那……一定就是控制着村民的东西！我现在知道我们必须做什么了。', `MaleText_loc5`='那...東西一定就是控制村民的禍首!我現在知道該怎麼做了。', `MaleText_loc7`='¡Esa... cosa debía de ser lo que controlaba a los aldeanos! Ahora sé lo que tenemos que hacer.' WHERE `ID`=61008;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음이 갑자기 평안해졌어요. 어떻게 된 거죠?', `FemaleText_loc4`='我感觉平静多了。发生什么了？', `FemaleText_loc5`='我感覺平靜多了。發生了什麼事?', `FemaleText_loc7`='Me siento mucho más tranquila. ¿Qué ha pasado?' WHERE `ID`=61009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 대체 무엇이지요?!', `MaleText_loc4`='那是什么？！', `MaleText_loc5`='那是什麼?!', `MaleText_loc7`='¡¿Qué es eso?!' WHERE `ID`=61010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 의식을 시작하자 당신의 몸에서 웬 괴물이 튀어나왔습니다. $p 님이 놈을 처치했지요!', `MaleText_loc4`='当我开始举行仪式时，从你身体里钻出了一只野兽。$p杀死了它！', `MaleText_loc5`='當我開始儀式時一頭野獸從你身上浮現出來。$p殺了它!', `MaleText_loc7`='Una bestia salió de ti cuando inicié el ritual. ¡$p acabó con ella!' WHERE `ID`=61011;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 마음 속에서 뭔가의 존재가 느껴졌어요... 불타는 고통과 분노가요.', `FemaleText_loc4`='我感到自己的心神被攫住，脑中出现灼热的痛楚，还有愤怒……', `FemaleText_loc5`='我感受到一股存在，我的心中有一種燒灼的疼痛與憤怒...', `FemaleText_loc7`='Sentí una presencia, una rabia y un dolor ardiente en mi mente...' WHERE `ID`=61012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락의 웅덩이가 있는 곳을 알려 주시면, 제가 지팡이로 정화하겠습니다. 혹시라도 뭔가 튀어나오면 처리해 주십시오!', `MaleText_loc4`='指出腐蚀之池，我会用法杖净化它们。你要打败出现的怪物！', `MaleText_loc5`='指出腐化之池，我會用我的法杖淨化它們。你得打倒浮現的生物!', `MaleText_loc7`='Señálame las pozas de corrupción y utilizaré mi bastón para purificarlas. ¡Deberás acabar con las criaturas que emerjan!' WHERE `ID`=61013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 신병, 이 잠수모를 가져가요. 필요할 일이 있을 거예요.', `MaleText_loc4`='嘿，新丁，拿着这个潜水头盔。你到了那儿以后或许用得着。', `MaleText_loc5`='嘿，菜鳥，把這潛水頭盔拿去。你可能需要它。', `MaleText_loc7`='Oye, $gnovato:novata;, toma esta escafandra. Puede que la necesites ahí fuera.' WHERE `ID`=61014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈출하려면 황금 연꽃의 그림자를 무찔러야 합니다!', `MaleText_loc4`='击败金莲之影以脱身！', `MaleText_loc5`='擊敗金蓮之影以逃脫!', `MaleText_loc7`='¡Derrota a la Sombra del Loto dorado para escapar!', `FemaleText_loc1`='탈출하려면 황금 연꽃의 그림자를 무찔러야 합니다!', `FemaleText_loc4`='击败金莲之影以脱身！', `FemaleText_loc5`='擊敗金蓮之影以逃脫!', `FemaleText_loc7`='¡Derrota a la Sombra del Loto dorado para escapar!' WHERE `ID`=61015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군님도 함께 가시겠습니까?', `MaleText_loc4`='你要来吗？', `MaleText_loc5`='你要來嗎?', `MaleText_loc7`='¿Vienes?', `FemaleText_loc1`='장군님도 함께 가시겠어요?', `FemaleText_loc4`='你要来吗？', `FemaleText_loc5`='你要來嗎?', `FemaleText_loc7`='¿Vienes?' WHERE `ID`=61016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 시작하겠습니다. 채비를 하십시오.', `MaleText_loc4`='我要开始仪式了。做好准备！', `MaleText_loc5`='我要開始進行儀式了。準備好!', `MaleText_loc7`='Voy a iniciar el ritual. ¡Prepárate!' WHERE `ID`=61017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다. 뭐가 나올지 모르니 단단히 각오하십시오!', `MaleText_loc4`='现在，朋友，做好准备，击败出现的一切敌人！', `MaleText_loc5`='就是現在，朋友，準備好對付任何出現的東西!', `MaleText_loc7`='Bueno, camarada. ¡Prepárate para acabar con lo que sea que emerja!' WHERE `ID`=61018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 웅덩이는 아까 것보다 나을지도...', `MaleText_loc4`='希望这个不会比上一个更糟……', `MaleText_loc5`='希望這一個不會比上次那個更糟...', `MaleText_loc7`='Espero que esta no sea peor que la anterior...' WHERE `ID`=61019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 파발락이 원군을 부릅니다!', `MaleText_loc4`='将军帕瓦拉克在呼唤援军！', `MaleText_loc5`='帕伐拉克將軍呼叫援軍!', `MaleText_loc7`='¡El General Pa''valak pide refuerzos!' WHERE `ID`=61020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진준 님, 갑시다. 복수의 때가 왔습니다!', `MaleText_loc4`='来吧，金祖恩，我们还要报仇呢。', `MaleText_loc5`='來吧，金浚，我們還有仇要報!', `MaleText_loc7`='¡Vamos, Zin''Jun, hay una venganza lista para servir!', `FemaleText_loc1`='진준 님, 가시죠. 복수의 때가 왔어요!', `FemaleText_loc4`='来吧，金祖恩，我们还要报仇呢。', `FemaleText_loc5`='來吧，金浚，我們還有仇要報!', `FemaleText_loc7`='¡Vamos, Zin''Jun, hay una venganza lista para servir!' WHERE `ID`=61021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c, 당신에게는 가르칠 것이 없습니다.', `MaleText_loc4`='我没什么可教你的，$c。', `MaleText_loc5`='我已經沒東西可以教你了，$c。', `MaleText_loc7`='No tengo nada que enseñarte, $c.', `FemaleText_loc1`='$c, 당신에게는 가르칠 것이 없습니다.', `FemaleText_loc4`='我没什么可教你的，$c。', `FemaleText_loc5`='我已經沒東西可以教你了，$c。', `FemaleText_loc7`='No tengo nada que enseñarte, $c.' WHERE `ID`=61022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我可以幫你什麼嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?', `FemaleText_loc1`='어떻게 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我可以幫你什麼嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=61023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 호드의 것이 되어야 하네.$b$b어떤 핑계도 용납할 수 없어!', `MaleText_loc4`='这片土地必须准备好迎接我们的舰队。$b$b无需任何理由！', `MaleText_loc5`='這塊土地必須準備好迎接艦隊。$b$b沒有任何藉口!', `MaleText_loc7`='Esta tierra tiene que estar lista para la flota.$b$b¡No hay excusas!' WHERE `ID`=61024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 받았어!', `MaleText_loc4`='我的！', `MaleText_loc5`='這是我的!', `MaleText_loc7`='¡Mío!' WHERE `ID`=61025;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 미련곰퉁이... 도저히 미워할 수가 없네요.$B$B이방인이여, 정말 고마워요.', `FemaleText_loc4`='这老家伙……我没法朝他发火。$B$B谢谢你，陌生人。', `FemaleText_loc5`='這隻老熊...我就是無法一直對他生氣。$B$B謝謝你，陌生人。', `FemaleText_loc7`='Este viejo oso... No puedo enfadarme con él.$b$bGracias, $gforastero:forastera;.' WHERE `ID`=61026;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장벽 뒤에 있는 벌레가 한 마리 더 줄었네요.', `FemaleText_loc4`='又少了一只躲在封锁线后的害虫。', `FemaleText_loc5`='封鎖線後又少了一隻害蟲。', `FemaleText_loc7`='Una alimaña menos detrás del bloqueo.' WHERE `ID`=61027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 도와드리고 싶어요, 전승지기님. 하지만 지금 상황이 너무 안 좋아요.', `FemaleText_loc4`='我也很想帮你，游学者，但是你得明白我也是身陷困境！', `FemaleText_loc5`='我很想要幫助你，博學行者，但是你必須了解我真的是無計可施了!', `FemaleText_loc7`='Me encantaría ayudarte, eremita, ¡pero tienes que entender que estoy entre la espada y la pared!' WHERE `ID`=61028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 우리 망할 남편만큼이나 고집쟁이시네요!', `FemaleText_loc4`='嗨！你跟我那死鬼丈夫真是一样的顽固！', `FemaleText_loc5`='嘎!你簡直跟我那臭丈夫一樣頑固。', `FemaleText_loc7`='Aj. ¡Eres tan testarudo como el cabezón de mi marido!' WHERE `ID`=61029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구야! 만 부인, 소개하고 싶은 이가 있습니다.', `MaleText_loc4`='看看谁来了！孟太太，我想给你引见个人。', `MaleText_loc5`='看看誰來了!蔓恩太太，我想介紹一個人給妳認識。', `MaleText_loc7`='¡Pero mira quién llegó! Sra. Mann, me gustaría presentarle a alguien.' WHERE `ID`=61030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어 올리는 중', `MaleText_loc4`='上升', `MaleText_loc5`='上升', `MaleText_loc7`='Elevando', `FemaleText_loc1`='들어 올리는 중', `FemaleText_loc4`='上升', `FemaleText_loc5`='上升', `FemaleText_loc7`='Elevando' WHERE `ID`=61031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 오래 머물 거라고는 생각하지 마, 친구.$b$b장군님이 그러는데, 이곳은 임시 주둔지래.', `MaleText_loc4`='别太放松了，伙计。$b$b将军说，这些房子只是临时的。', `MaleText_loc5`='別在這住得太自在了，夥伴。$b$b將軍說這些只是臨時居所而已。', `MaleText_loc7`='No te acomodes mucho, $gcompañero:compañera;.$b$bEl general dice que este sitio es temporal.' WHERE `ID`=61032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 조상님의 축복을 받아 주십시오. 대단한 건 아니지만, 지팡이가 없는 상태로는 이 정도가 한계입니다. 그래도 호수를 가로지르는 데는 보탬이 될 겁니다.', `MaleText_loc4`='请接受先祖的祝福吧。尽管微不足道，但没有法杖我能给你的就只有这些，它将助你渡过墨鳃潭。', `MaleText_loc5`='請接受先祖的祝福。雖然很有限，但我在手中沒有法杖的情況下也只能做到這樣了，這將幫助你穿過湖水。', `MaleText_loc7`='Por favor, acepta la bendición de los ancestros. No es mucho, pero es todo lo que puedo darte sin mi bastón... y te ayudaré a cruzar la Presa.' WHERE `ID`=61033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 환영의 여군주를 상대하려면 그 정도 박력은 있어야지. 자, 그럼 실력을 보여줘!', `FemaleText_loc4`='噢，要想挑战幻影女士可是需要很大勇气的。那么，就让我看看你们有什么本事吧！', `FemaleText_loc5`='喔，要挑戰幻術之女可不是那麼簡單。如何?讓我看看你有多少料吧!', `FemaleText_loc7`='Hay que tener agallas para desafiar a la señora de las ilusiones. ¿Y bien? ¡Deslúmbrenme!' WHERE `ID`=61034;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즐겁게 춤을 추다가 그대로 누워!', `FemaleText_loc4`='灰飞烟灭，跟我一起堕落吧！', `FemaleText_loc5`='灰燼，灰燼，都是會落地!', `FemaleText_loc7`='¡Polvo eres y en polvo te convertirás!' WHERE `ID`=61035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 양탄자에 피가 묻지 않게 조심해줄래?', `FemaleText_loc4`='噢，小心点，别把血滴在地毯上了，亲爱的。', `FemaleText_loc5`='噢，小心不要把血流到地毯上，親愛的。', `FemaleText_loc7`='Ay. Intenta no sangrar en la alfombra, cariño.' WHERE `ID`=61036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에 또 봐!', `FemaleText_loc4`='祝你下次走运！', `FemaleText_loc5`='祝你們下次好運。', `FemaleText_loc7`='¡Que les vaya mejor la próxima vez!' WHERE `ID`=61037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='억... 죽는 게... 아프다니? 말도 안 돼...', `FemaleText_loc4`='呃……死亡……痛楚？都是假象……', `FemaleText_loc5`='唔...死亡...會痛嗎?好不真實啊...', `FemaleText_loc7`='Aah... ¿la muerte... duele? Increíble...' WHERE `ID`=61039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와서 오늘 운수를 확인해 봐! 하하하하하...', `FemaleText_loc4`='来试试你的运气吧！哈哈哈哈哈……', `FemaleText_loc5`='來吧，試試你的運氣!哈，哈，哈哈哈...', `FemaleText_loc7`='¡Vengan a probar suerte! Ja, ja, jaaa…' WHERE `ID`=61041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물예언자 말이 맞았습니다... 다들 미쳐 버렸어요!', `MaleText_loc4`='责法者说得没错……他们已经疯了！', `MaleText_loc5`='律言者是對的...他們已經發瘋了!', `MaleText_loc7`='El legislador tenía razón... ¡se han vuelto locos!' WHERE `ID`=61042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 당신은 그놈들 편이 아니지요? 도와주십시오!', `MaleText_loc4`='你……你不是他们一伙的吧，是吗？你得帮帮我！', `MaleText_loc5`='你...你不是跟他們一伙的吧?你得幫幫我!', `MaleText_loc7`='Tú... tú no eres uno de ellos, ¿verdad? ¡Tienes que ayudarme!' WHERE `ID`=61043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 틀렸어요... 우리 부족 사람들은 제정신이 아닙니다!', `MaleText_loc4`='没希望了……我们的同胞已经失去了理智！', `MaleText_loc5`='沒有希望了...我們的人民已經失去理智!', `MaleText_loc7`='No hay esperanza... ¡nuestra gente ha perdido la cabeza!' WHERE `ID`=61044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 희망이 있습니다. 고라이가 살아서 남쪽에 있습니다. 가십시오!', `MaleText_loc4`='还有希望——苟莱还活着，他在南边。走！', `MaleText_loc5`='還有希望，郭萊還活著，快去南邊。快走!', `MaleText_loc7`='Todavía hay esperanza... Gorai sigue vivo, en el sur. ¡Vamos!', `FemaleText_loc1`='아직 희망이 있어요. 고라이가 살아서 남쪽에 있어요. 가세요!', `FemaleText_loc4`='还有希望——苟莱还活着，他在南边。走！', `FemaleText_loc5`='還有希望，郭萊還活著，快去南邊。快走!', `FemaleText_loc7`='Todavía hay esperanza... Gorai sigue vivo, en el sur. ¡Vamos!' WHERE `ID`=61045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='느낌이 어때... 어지러워?', `FemaleText_loc4`='晕了吧？', `FemaleText_loc5`='感到有點...頭暈嗎?', `FemaleText_loc7`='¿Se sienten un poco... mareados?' WHERE `ID`=61046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 내게 도전한 첫 상대는 아니다. 하지만 마지막 상대도 아닐 거다.', `MaleText_loc4`='你们不是第一批来挑战我的人，苦力们，也不会是最后一批。', `MaleText_loc5`='你們不是第一批挑戰我的，小卒子們。也不會是最後一批。', `MaleText_loc7`='No son los primeros en desafiarme, plebeyos. Ni serán los últimos.' WHERE `ID`=61047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐야. 내 왕관을 훔친답시고 더 온 건가? 조그맣고 약한 놈들이.', `MaleText_loc4`='怎么，又有人想来抢我的王冠了？一群软弱的小爬虫。', `MaleText_loc5`='這些人是誰?又是來竊取我王冠的人?真是弱小啊。', `MaleText_loc7`='¿Cómo? ¿Vienen más a arrebatarme la corona? Son pequeños y débiles.' WHERE `ID`=61048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 이름은 알고 있다네. 내가 받은 보고가 사실이라면, 우리에게 도움이 될 것 같더군.', `MaleText_loc4`='我认识你。如果我收到的报告情况属实，我的确需要一位像你这样的$g大侠:女侠;帮助。', `MaleText_loc5`='我聽說過你。如果我收到的報告內容屬實，那我用得上像你這樣的$g男子漢:女勇士;。', `MaleText_loc7`='Te conozco. Si los informes que he venido recibiendo son ciertos, me vendría bien $gun hombre:una mujer; como tú.' WHERE `ID`=61049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스가 자네를 칭찬하더군. 그것만 보아도 자네 됨됨이를 알 수 있지.', `MaleText_loc4`='陶矢对你的评价很高。她对你的尊重就很能说明一些问题。', `MaleText_loc5`='陶氏對你有很高的評價，她對你的尊敬說明了一切。', `MaleText_loc7`='Taoshi no escatima halagos al hablar sobre ti. El respeto que te profesa dice mucho.' WHERE `ID`=61050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 증오의 샤를 쫓고 있다네. 자네도 우리와 함께했으면 좋겠군.', `MaleText_loc4`='我们在追踪恨之煞。我想让你加入我们。', `MaleText_loc5`='我們在跟蹤仇恨之煞，希望你能加入追捕的行列。', `MaleText_loc7`='Estamos siguiendo al Sha del odio. Quiero que te unas a la caza.' WHERE `ID`=61051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘은 무한하다!', `MaleText_loc4`='我的力量无穷无尽！', `MaleText_loc5`='我的力量沒有止盡!', `MaleText_loc7`='¡MI FUERZA NO TIENE LÍMITE!' WHERE `ID`=61052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구여... 남쪽으로 가 보지요!', `MaleText_loc4`='谢谢你，朋友……我会向南进发！', `MaleText_loc5`='謝謝你，朋友...我會啟程前往南邊!', `MaleText_loc7`='Gracias, $gamigo:amiga;... ¡partiré hacia el sur!' WHERE `ID`=61053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고라이가 살았단 말입니까? 가서 찾아 봐야겠군요. 고맙습니다!', `MaleText_loc4`='苟莱还活着？我要去找他。谢谢你，朋友！', `MaleText_loc5`='郭萊還活著?我會去找到他。謝謝你，朋友!', `MaleText_loc7`='¿Que Gorai sigue vivo? Iré a buscarlo. ¡Gracias, $gamigo:amiga;!' WHERE `ID`=61054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 무기의 위력을 느껴라!', `MaleText_loc4`='见识见识我的神兵利器吧，爬虫们！', `MaleText_loc5`='來嚐嚐我斧頭的厲害，弱者們!', `MaleText_loc7`='¡Enfréntense al poder de mi arsenal, gusanos!' WHERE `ID`=61055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 용감한 분이군요... 고맙습니다!', `MaleText_loc4`='你非常勇敢……谢谢你！', `MaleText_loc5`='你非常勇敢...謝謝你!', `MaleText_loc7`='Eres muy valiente... ¡gracias!' WHERE `ID`=61056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은. 난 원소의 힘을 부릴 수 있다!', `MaleText_loc4`='蠢货，我掌握着元素的力量！', `MaleText_loc5`='蠢貨，我擁有元素的力量!', `MaleText_loc7`='¡Necios! ¡Domino el poder de los elementos!' WHERE `ID`=61057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광대놀음은 여기까지다! 고통을 안겨주마, 겁쟁이들아!', `MaleText_loc4`='我受够这场闹剧了！感受你们的痛苦吧，懦夫！', `MaleText_loc5`='鬧夠了!我要讓你們痛不欲生，膽小鬼!', `MaleText_loc7`='¡ACABEMOS CON ESTA FARSA! ¡Van a sufrir, cobardes!' WHERE `ID`=61058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신의 얼굴에 피를 뱉습니다.', `MaleText_loc4`='%s的鲜血溅到了你的脸上。', `MaleText_loc5`='%s把血吐在你的臉上。', `MaleText_loc7`='%s escupe sangre en tu cara.' WHERE `ID`=61059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오의 샤를 상대하려면 음영파 최고의 인재가 필요하다네. 또한, 그런다 해도 모두 살아남지 못할 공산이 크지.', `MaleText_loc4`='我们需要集结影踪派最强大的力量来对付恨之煞。即便这样，也不是所有人都能活下来。', `MaleText_loc5`='我們需要最強大的影潘提供協助，以對抗仇恨之煞。而且即使如此，我們當中或許有人還是沒辦法活著出來。', `MaleText_loc7`='Necesitaremos la mayor fuerza que nos pueda ofrecer el Shadopan para enfrentarnos al Sha del odio. Y es probable que, incluso así, no todos nosotros logremos sobrevivir.' WHERE `ID`=61060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다 왔네. 내 안에서 부자연스러운 증오가 끓는 것이 느껴지네.', `MaleText_loc4`='我们接近了。我能感受到我心中异样的仇恨在不断燃烧。', `MaleText_loc5`='我們接近了。我能感受到心中燃燒著不自然的仇恨。', `MaleText_loc7`='Nos acercamos. Ya puedo sentir cómo el odio antinatural empieza a arder en mi interior.' WHERE `ID`=61061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 고대의 벽화는 한때 비취를 새겨넣은 작품이었네. 하지만 이제 폐허로 변해, 그 안의 지혜도 사라지고 말았지.', `MaleText_loc4`='这幅古老的壁画曾镶满了玉石，但现在已经残破，其中的智慧也失传了。', `MaleText_loc5`='這幅古老的壁畫曾經嵌著翠玉，可是現在已經荒廢了，上面的知識也隨之逝去。', `MaleText_loc7`='Este antiguo fresco tenía incrustaciones de jade, pero cayó en ruinas. Ahora su saber nos resulta indescifrable.' WHERE `ID`=61062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 우리는 모두 시험에 들겠지만, 끝내 이기고 말 걸세.', `MaleText_loc4`='今天，我们都将接受最后的考验，但胜利一定属于我们。', `MaleText_loc5`='我們今天都要接受測試，但我們會勝利。', `MaleText_loc7`='Hoy, todos nos someteremos a una dura prueba. Y venceremos.' WHERE `ID`=61063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인들이 갑작스럽게 판다리아에 나타났으니, 역사의 가르침이 더 필요할 것이네.', `MaleText_loc4`='随着陌生人突然出现在潘达利亚，我相信历史给我们的教训将会发挥作用。', `MaleText_loc5`='現在許多陌生人突然出現在潘達利亞，我認為我們需要從歷史中學習教訓。', `MaleText_loc7`='Con la repentina llegada de forasteros a Pandaria, nos serán necesarias las lecciones que nos ha enseñado el pasado.' WHERE `ID`=61064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고작... 이 정도냐...?', `MaleText_loc4`='你们这也叫……战斗……？', `MaleText_loc5`='這就是你們的全力?', `MaleText_loc7`='¿A eso... le llaman... luchar?' WHERE `ID`=61065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 알아요. 그런데 용의 심장 작업이 너무 늦어졌고, 비취도 모자르다고요!', `FemaleText_loc4`='我明白了，游学者。可是由于玉石短缺，神龙之心的项目进度已经严重落后了！', `FemaleText_loc5`='我了解，博學行者。但蟠龍之心工程的進度已經嚴重落後，而我們沒有多餘的玉石了!', `FemaleText_loc7`='Lo entiendo, eremita, pero el proyecto del Corazón del Dragón lleva retraso y no nos sobran las piedras.' WHERE `ID`=61066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 우리 전당에 외부인을 들였지? 하르닥과 카게쉬 부족 놈들이나 이런 배신을 저지를 것이다!', `MaleText_loc4`='谁让外人闯进大厅的？只有哈飒克或克尔格西氏族才会干出这种叛逆的行径！', `MaleText_loc5`='是誰讓外來者進入我們的殿堂?只有哈薩科或卡傑許部族會做出這種背叛的行為!', `MaleText_loc7`='¿Quién dejó entrar a los forasteros? ¡Solo los clanes Harthak o Kargesh se rebajarían a cometer tal traición!' WHERE `ID`=61067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을 내놓아라, 필멸자여! 죽은 자들의 환대를 거절하지 마라!', `MaleText_loc4`='啊，没错。交出你们的灵魂吧，凡人！这里是亡者的殿堂！', `MaleText_loc5`='噢，很好，交出你們的靈魂吧，凡人!這裡是亡者的殿堂!', `MaleText_loc7`='Preparen sus almas, mortales. ¡Se adentran en las cámaras de los muertos!' WHERE `ID`=61068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 뼈를 부수는 일이 얼마나 쉬운지 봐라!', `MaleText_loc4`='看看我是怎么碾碎你们的骨头吧！不费吹灰之力！', `MaleText_loc5`='看我怎樣輕鬆打碎你們的骨頭!', `MaleText_loc7`='¡Mira con qué facilidad aplasto tus huesos!' WHERE `ID`=61069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎 꿇어라, 겁쟁아!', `MaleText_loc4`='跪下吧，懦夫！', `MaleText_loc5`='跪下來吧，懦夫!', `MaleText_loc7`='¡Arrodíllate, cobarde!' WHERE `ID`=61070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 기다리십시오, 만 부인. 안개 너머에서 온 이방인들이 계속해서 절 놀라게 하더군요.', `MaleText_loc4`='耐心点，孟太太。这些迷雾之外的陌生人总能给我带来惊喜。', `MaleText_loc5`='耐心點，蔓恩太太。這些來自迷霧彼端的陌生人充滿了驚奇。', `MaleText_loc7`='Ten paciencia, Sra. Mann. Estos forasteros de más allá de la niebla no dejan de sorprenderme.' WHERE `ID`=61071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구르단 부족의 개들이나 자신의 잘못을 남에게 돌린다! 너희 부족이 가장 절실하니 분명 너희가 범인이다!', `MaleText_loc4`='只有格尔桑氏族的狗才会将自己的失败归咎于他人！你们氏族最丧心病狂了，一定是你们干的！', `MaleText_loc5`='只有葛薩恩的瘋狗會為他們自己的失敗指責別人!你們的部族嫌疑最大!一定是你們!', `MaleText_loc7`='¡Solo los perros del clan Gurthan culpan a los demás de sus propios errores! Su clan está desesperado. ¡Han sido ustedes!' WHERE `ID`=61072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 허약해 보이는 양반이 석공의 집을 정리한다고요? 배도 홀쭉하잖아요!', `FemaleText_loc4`='你相信这些草包能够搞定工匠区？他们的肚子上都没有几两肉！', `FemaleText_loc5`='你希望我相信這傢伙可以把石匠區清乾淨?我看他連肚子都還沒長出來咧!', `FemaleText_loc7`='¿Esperas que semejante enclenque se ocupe del Barrio de Canteros? ¡Si está en los huesos!' WHERE `ID`=61073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구르단 부족 말이 맞아! 불명예스런 하르닥 부족이나 목적 달성을 위해 하등 종족을 개입시키겠지. 배신자는 너희야!', `MaleText_loc4`='格尔桑氏族说得对！只有卑贱的哈飒克氏族才会让下等种族帮忙做事。你们一定是叛徒！', `MaleText_loc5`='葛薩恩部族說得對!只有不講道義的哈薩科部族會使喚低等種族。你們一定是叛徒!', `MaleText_loc7`='¡El clan Gurthan tiene razón! Solo el despreciable clan Harthak se valdría de una raza inferior. ¡Ustedes deben ser los traidores!' WHERE `ID`=61074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_arcane_blast.blp:20|t %s|1이;가; |cFFFF0000|Hspell:117914|h[완전한 파멸]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_arcane_blast.blp:20|t %s开始施放|cFFFF0000|Hspell:117914|h[横扫千军]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_arcane_blast.blp:20|t %s開始施放|cFFFF0000|Hspell:117914|h[全面殲滅]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_arcane_blast.blp:20|t ¡%s comienza a lanzar |cFFFF0000|Hspell:117914|h[Aniquilación total]|h|r!' WHERE `ID`=61075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 제 부모도 몰라보는 무샨 몰이꾼들아!! 너희 부족을 탓하려 한들 그 두뇌로는 버겁겠지. 왕위 찬탈은 말할 것도 없다.', `MaleText_loc4`='闭嘴，你们这些没娘养的穆山兽放牧人！我本以为是你们氏族的错，可你们比三岁小孩都笨，更别说篡权了。', `MaleText_loc5`='閉嘴，你們這些沒娘的牡山獸牧童!我本來想指責你們部族，但你們的豬腦連小孩的拼圖都玩不好，更別說篡位了。', `MaleText_loc7`='¡Silencio, patéticos pastores mu''shan! Culparía a su clan, ¿pero cómo van a usurpar el poder si no aciertan a solucionar un rompecabezas?' WHERE `ID`=61076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각본을 잘 짜왔군. 하지만 우린 속지 않아. 너희 부족은 서로 결탁한 게 분명해. 폐하의 영광을 위해, 제국의 이름으로 너희 모두를 쓰러뜨리겠다!', `MaleText_loc4`='这是精心策划的政变，但我们也不傻。显然你们这些氏族相互勾结。为了王上的荣耀，消灭你们！', `MaleText_loc5`='劇本寫得不錯，但騙不過我們。你們的部族顯然已經勾結。為了王的榮耀，為了我們的帝國，你們都去死吧!', `MaleText_loc7`='Muy buena representación, pero no nos engañan. Es evidente que sus clanes se han aliado. Por la gloria de nuestro Rey, ¡nuestro imperio acabará con ustedes!' WHERE `ID`=61077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카게쉬 부족은 이런 모욕을 참지 않겠다! 곧 우리 힘의 증거로 너희의 목을 폐하께 바쳐주마!', `MaleText_loc4`='克尔格西氏族不会容许这等侮辱！我们很快就要把你们的头颅献给国王，证明我们的力量！', `MaleText_loc5`='卡傑許部族不會容許這樣的侮辱!我們會提著你們的頭向王證明我們的力量!', `MaleText_loc7`='¡El clan Kargesh no tolerará tales insultos! ¡Ofreceremos sus cabezas al Rey como prueba de nuestro poder!' WHERE `ID`=61078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대담한 카라쉬 님과 다른 형제들을 풀어준 $r|1이;가; 바로 당신이군요! 정말 감사합니다.', `MaleText_loc4`='你一定就是那个救了勇敢的卡拉什和我们其他兄弟的$r了！我们真的很感激你。', `MaleText_loc5`='你一定就是拯救了英勇的卡爾勒什還有我們其他弟兄的$r。我們都得感謝你。', `MaleText_loc7`='¡Tú debes ser $gel:la; $r que liberó a Karasshi el Audaz y a nuestros hermanos! Te debemos nuestro agradecimiento.' WHERE `ID`=61079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대담한 카라쉬 님이 $r 한 분을 자주 뵐 수 있을 거라고 하셨는데, 그게 바로 당신이군요.', `MaleText_loc4`='勇敢的卡拉什说会有一个$r经过这里。他说的肯定就是你了。', `MaleText_loc5`='英勇的卡爾勒什提到有個$r會經過。那個人一定就是你了', `MaleText_loc7`='Karasshi el Audaz mencionó que $gun:una; $r pasaría por aquí. Tú debes ser esa persona.' WHERE `ID`=61080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형제들을 도와준 분이시군요. 감사합니다.', `MaleText_loc4`='你一定就是那个救了我们兄弟的人，谢谢你。', `MaleText_loc5`='你一定是那個幫助我們弟兄的人，謝謝你。', `MaleText_loc7`='Tú debes ser $gel:la; que ayudó a nuestros hermanos. Gracias.' WHERE `ID`=61081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R 님, 어서 오십시오. 대담한 카라쉬 님이 당신의 활약상을 우리에게도 들려주셨습니다.', `MaleText_loc4`='$R，欢迎你的光临。勇敢的卡拉什已经把你的事迹都告诉我们了。', `MaleText_loc5`='$R，歡迎你來到這裡。英勇的卡爾勒什已經告訴我們你的事蹟了。', `MaleText_loc7`='Sé $gbienvenido:bienvenida;, $r. Karasshi el Audaz ya nos ha hablado de tus hazañas.' WHERE `ID`=61082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님 맞으십니까? 형제들을 구해주셔서 정말 감사합니다.', `MaleText_loc4`='$C是吗？感谢你把我们的兄弟带回来。', `MaleText_loc5`='$C，不是嗎?感謝你把我們的兄弟帶回來。', `MaleText_loc7`='$C, ¿verdad? Gracias por devolvernos a nuestros hermanos.' WHERE `ID`=61083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 하루를 보내십시오, $r님.', `MaleText_loc4`='日安，$r。', `MaleText_loc5`='你好，$r。', `MaleText_loc7`='Buen día, $r.' WHERE `ID`=61084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r님, 물이 당신을 축복하길 기원합니다.', `MaleText_loc4`='愿流水祝福你，$r。', `MaleText_loc5`='願水祝福你，$r。', `MaleText_loc7`='Que las aguas te bendigan, $r.' WHERE `ID`=61085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 몸 상태가 좀 어떠십니까, $n 님?', `MaleText_loc4`='你今天过得如何，$n？', `MaleText_loc5`='你今天過得如何，$n?', `MaleText_loc7`='¿Cómo te va hoy, $n?' WHERE `ID`=61086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽉 잡으십시오!', `MaleText_loc4`='抓紧了！', `MaleText_loc5`='抓緊了!', `MaleText_loc7`='¡Agárrate bien!' WHERE `ID`=61087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 녹옥거미들! 한 방 먹여요!', `MaleText_loc4`='这些发疯的蜘蛛！给它们点颜色瞧瞧，$p！', `MaleText_loc5`='瘋狂的啃咬者!給牠們一點顏色瞧瞧，$p!', `MaleText_loc7`='¡Malditas alimañas! ¡Dales una buena paliza!' WHERE `ID`=61088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들이 도무지 포기할 줄을 모르는군요!', `MaleText_loc4`='这些该死的虫子真是没完没了了？！', `MaleText_loc5`='討厭的小動物就是不懂得放棄，對吧?!', `MaleText_loc7`='¡Esos bichos no saben cuándo rendirse!' WHERE `ID`=61089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벽화에 다 왔습니다. 힘내세요!', `MaleText_loc4`='我们快到壁画那儿了。坚持到底！', `MaleText_loc5`='我們已經快到壁畫了。後面的快跟上!', `MaleText_loc7`='Ya casi llegamos al fresco. ¡Aguanta un poco más!' WHERE `ID`=61090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요. 야영지 동쪽 입구에서 만나요. 방어진이 허술한 곳을 찾아서 보완해야 해요.', `FemaleText_loc4`='干得好，到封锁线东边的入口找我。我们要找到防线的漏洞，并把它补上。', `FemaleText_loc5`='做得好，到封鎖線的東邊入口跟我碰頭。我們必須找到防線的缺口並把它補起來。', `FemaleText_loc7`='Buen trabajo. Reúnete conmigo en la entrada este del bloqueo. Tenemos que encontrar la brecha en las defensas y taparla.' WHERE `ID`=61091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 의식을 시작하십시오.', `MaleText_loc4`='我准备好了。开始举行仪式。', `MaleText_loc5`='我準備好了，開始儀式。', `MaleText_loc7`='Estoy preparado. Inicia el ritual.', `FemaleText_loc1`='준비됐어요. 의식을 시작하세요.', `FemaleText_loc4`='我准备好了。开始举行仪式。', `FemaleText_loc5`='我準備好了，開始儀式。', `FemaleText_loc7`='Estoy preparada. Inicia el ritual.' WHERE `ID`=61092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈에서 살이라... 쯧쯧... 그들의 영혼은 부서졌다!', `MaleText_loc4`='剜肉剔骨……嘶……他们的灵魂将被粉碎！', `MaleText_loc5`='從骨頭剝下的新鮮的肉...嘶...他們的靈魂被撕裂了!', `MaleText_loc7`='¡Carne y hueso... Tsss... sus almas están rotas!' WHERE `ID`=61093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게도 무너지는군.', `MaleText_loc4`='这么快就粉身碎骨了。', `MaleText_loc5`='兩三下就粉身碎骨了。', `MaleText_loc7`='Caen con tanta facilidad...' WHERE `ID`=61094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손가락 까닥도 안 했는데.', `MaleText_loc4`='收割的时候到了。', `MaleText_loc5`='收割的時候到了。', `MaleText_loc7`='Como un cordero en el matadero.' WHERE `ID`=61095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 위대한 영혼이여! 내게 대지의 힘을 부여하라!', `MaleText_loc4`='噢，伟大的神灵！赐予我大地的力量！', `MaleText_loc5`='噢，偉大的靈魂!賜予我大地之力!', `MaleText_loc7`='¡Oh, gran espíritu! ¡Otórgame el poder de la tierra!' WHERE `ID`=61096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 고귀한 자여! 나와 함께 발라내자! 뼈에서 살을!', `MaleText_loc4`='噢，至高的神！借我之手融化他们的血肉吧！', `MaleText_loc5`='噢，至高的神啊!藉由我來融化他們的血肉吧!', `MaleText_loc7`='¡Oh, exaltado! ¡Soy tu herramienta para desgarrar la carne de los huesos!' WHERE `ID`=61097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 세기의 현자여! 내게 비전의 지혜를 불어넣어라!', `MaleText_loc4`='噢，上古的贤者！赐予我魔法的智慧吧！', `MaleText_loc5`='噢，上古的賢者!賜予我秘法的智慧!', `MaleText_loc7`='¡Oh, sabio eterno! ¡Transmíteme tu sabiduría Arcana!' WHERE `ID`=61098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과거의 위대한 영웅들이여! 너희의 방패를 빌려다오!', `MaleText_loc4`='先烈的英灵！用你的盾保护我吧！', `MaleText_loc5`='英雄之靈!以盾護我之身!', `MaleText_loc7`='¡Almas de campeones antiguos! ¡Concédanme su escudo!' WHERE `ID`=61099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 공포가 기다리는지... 그들이 알았더라면...', `MaleText_loc4`='如果他们知道……前路有多么恐怖……', `MaleText_loc5`='他們...不知道等著他們的恐怖...', `MaleText_loc7`='Si supieran... los horrores que les esperan...' WHERE `ID`=61100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 너를 힘의 용사라 불러주지! 네 앞에 선 적들이 공포로 벌벌 떨지어다.', `MaleText_loc4`='哈，很好！我赐予你力量勇者的称号！你的威名将令敌人闻风丧胆。', `MaleText_loc5`='幹得好!在此，我宣布你為神力勇士!願你的敵人聽見這個稱號便顫抖不已。', `MaleText_loc7`='¡Bien hecho! ¡Has triunfado en el Torneo de Fuerza! Que tus enemigos tiemblen ante ti.' WHERE `ID`=61101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 계속 여기 있을 순 없습니다! 달리 방법이 없군요!
<화염 연꽃 향을 사용합니다.>', `MaleText_loc4`='你不能待在这里！这是你逼我的！
<使用业火莲熏香。>', `MaleText_loc5`='你不能待在這兒!你讓我別無選擇!
<使用火焰蓮花薰香。>', `MaleText_loc7`='¡Bueno, es que no puedes quedarte aquí! ¡No me dejas elección!
<Utiliza el incienso de loto de fuego.>', `FemaleText_loc1`='그래도 계속 여기 있을 순 없잖아요! 달리 방법이 없군요!
<화염 연꽃 향을 사용합니다.>', `FemaleText_loc4`='你不能待在这里！这是你逼我的！
<使用业火莲熏香。>', `FemaleText_loc5`='你不能待在這兒!你讓我別無選擇!
<使用火焰蓮花薰香。>', `FemaleText_loc7`='¡Bueno, es que no puedes quedarte aquí! ¡No me dejas elección!
<Utiliza el incienso de loto de fuego.>' WHERE `ID`=61102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 처치했군요! 대단합니다!', `MaleText_loc4`='他死了！你成功了！', `MaleText_loc5`='他死了!你成功了!', `MaleText_loc7`='¡Está muerto! ¡Lo has conseguido!' WHERE `ID`=61103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 저는 난민들이 있는 곳으로 돌아가겠습니다. 그곳으로 오시면 제대로 사례를 하지요.', `MaleText_loc4`='朋友，我要回避难所了。在那和我碰头，我们好感谢你。', `MaleText_loc5`='朋友，我會回到難民那裡。到那裡找我們，讓我們好好感謝你。', `MaleText_loc7`='Vuelvo con los refugiados. Nos veremos allí y podré darte las gracias como es debido.' WHERE `ID`=61104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주민들이여, 그분이십니다! 먹물아가미에 새 생명을 주신 $n 님이십니다!', `MaleText_loc4`='同胞们，$g他:她;来了！帮墨鳃重获新生的$n！', `MaleText_loc5`='我的人民啊，$g他:她;就在這兒!讓墨鰓重獲新生的人。$n!', `MaleText_loc7`='¡Mi gente, aquí $glo:la; tienen! $gEl:La; que dio nueva vida a Branquias de Tinta. ¡$n!' WHERE `ID`=61105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 감사를 표합니다, 친구여. 당신의 이름은 우리 민족의 역사에 기록될 것입니다.', `MaleText_loc4`='再次感谢你，朋友。我们将把你的名字写入史册，永远铭记。', `MaleText_loc5`='再次感謝你，朋友。我們會將你的名字記載在我們的歷史中。', `MaleText_loc7`='Gracias de nuevo, $gamigo:amiga;. Recordaremos tu nombre en la historia de nuestro pueblo.' WHERE `ID`=61106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 $n|1을;를; 위해 만세!', `MaleText_loc4`='为$n欢呼！', `MaleText_loc5`='$n萬歲!', `MaleText_loc7`='¡Aclamen todos a $n!' WHERE `ID`=61107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보면 알겠지만 이 녀석은 불량 야크예요, $r. 그 녀석을 쓰다듬어 보세요.', `MaleText_loc4`='正如你所见，这并不是一头完美的牦牛。去吧，$r。去摸摸它。', `MaleText_loc5`='如你所見，這是隻有缺陷的犛牛。沒關係，$r。試著摸摸牠。', `MaleText_loc7`='Como puedes ver, este es un yak defectuoso. Adelante, $r. Intenta acariciarlo.' WHERE `ID`=61108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나라면 안 하겠어요...', `MaleText_loc4`='我要是你的话，我不会那样做……', `MaleText_loc5`='如果我是你，我不會這樣做...', `MaleText_loc7`='Yo de ti no lo haría...' WHERE `ID`=61109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤죠? 나쁜 야크라고요. 이번에는 먹이를 줘 봐요.', `MaleText_loc4`='你看吧？差劲的牦牛。继续，$r。试着喂它。', `MaleText_loc5`='你看到沒?壞犛牛。好了，繼續吧，$r。餵牠看看。', `MaleText_loc7`='¿Ves? Yak malo. Ahora intenta darle de comer, $r.' WHERE `ID`=61110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야크 사원이 어떤 곳인지 모르시는 것 같군요.', `FemaleText_loc4`='我想你并不了解牦牛寺是做什么的。', `FemaleText_loc5`='我想你不清楚犛牛寺廟的功能。', `FemaleText_loc7`='Creo que no entiendes cómo funciona el templo del yak.' WHERE `ID`=61111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봤죠?! 걸핏하면 문다고요. 게다가 말도 잘 안 들어요. 녀석을 한 번 움직여 보세요.', `MaleText_loc4`='看到了吧！？很爱咬人。还不听使唤。试着让它动两下，$r。', `MaleText_loc5`='你看!?超會咬人，而且也不聽話。$r，試著移動牠。', `MaleText_loc7`='¿Ves? No deja de morder. Y tampoco sigue órdenes. Intenta hacer que se mueva, $r.' WHERE `ID`=61112;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 들으세요, 그루멀. 이곳은 위대한 검은 야크 니우짜오 님을 봉양하는 사원이에요. 우리는 그분의 종이자 이 사원의 관리자고요. "야크를 교환"해 드리는 건 우리 일이 아니에요.', `FemaleText_loc4`='试着去理解，土地精。这是伟大玄牛砮皂的寺庙。我们是他的奴仆，也是这座寺庙的守护者。我们从不“更换牦牛”。', `FemaleText_loc5`='咕嚕摩，你要試著了解。這是怒兆寺，偉大玄牛的寺院。我們是這座寺的僕人與守護者。我們不會「替換犛牛」。', `FemaleText_loc7`='Intenta comprenderlo, grúmel. Esto es un templo a Niuzao, el gran Buey Negro. Nosotros somos sus sirvientes, y protegemos este templo. No "cambiamos yaks".' WHERE `ID`=61113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 그럼 AS는 받을 수 있나요? 사람을 태우려 들지도 않는걸요.', `MaleText_loc4`='我知道了。那我至少能让我的牦牛干活吧？它连个人都背不动。', `MaleText_loc5`='我懂了。那能不能至少換掉我的?牠根本不讓別人騎在身上。', `MaleText_loc7`='Ya veo... ¿Podrías al menos reparar el mío? Ni siquiera deja que lo monten.' WHERE `ID`=61114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸른안장 사촌... 그렇게 떼 쓰지 마. 게다가 이 $r에게 못할 짓을 하고 있잖아.', `MaleText_loc4`='表哥蓝马鞍……你太固执了，而且你对$r也太刻薄了。', `MaleText_loc5`='藍鞍表弟...你太堅持了。而且你對$r的態度很不好。', `MaleText_loc7`='Primo Sillín Azul... Eres demasiado persistente. Y te estás portando mal con $gel:la; $r.' WHERE `ID`=61115;
