UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩔 수 없군요. 북쪽에 있는 호수 근처에 야생 야크가 많이 있어요. 그중 한 마리로 "교환해" 가세요.', `FemaleText_loc4`='好吧，北边的湖附近有许多野牦牛。你可以从中挑一头来“更换”你的牦牛。', `FemaleText_loc5`='很好。北邊湖畔有很多野生犛牛，你可以把你的犛牛跟其中一隻「交換」一下。', `FemaleText_loc7`='De acuerdo. Hay un montón de yaks salvajes cerca del lago que hay al norte. Puedes "cambiar" tu yak por uno de esos.' WHERE `ID`=61117;
