UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 내 아들을 데려갔네... 내 재산도 가져갔고. 난 모든 걸 잃었다네. 진위들이 대체 무엇 때문에 그렇게 된 거지?', `MaleText_loc4`='他们抓走了我的儿子……抢走了我的货物，我失去了一切。究竟是什么把这些锦鱼人变成了这样？', `MaleText_loc5`='他們抓走我的兒子...他們搶走我的貨物，我失去了一切。究竟是什麼改變了這些錦魚人的行為呢?', `MaleText_loc7`='Se llevaron a mi hijo... Se llevaron mis mercancías, lo he perdido todo. ¿Qué ha podido pasar para que cambien tanto estos jinyu?' WHERE `ID`=61143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들... 재산은 되찾았지만 아들 녀석은 어찌 될지...', `MaleText_loc4`='我的儿子……虽然我找回了货物，可我的儿子会有什么下场？', `MaleText_loc5`='我的兒子...雖然我已找回我的貨品，但我兒子會怎麼樣?', `MaleText_loc7`='Mi hijo... aunque he recuperado mis cosas, ¿qué será de él?' WHERE `ID`=61144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이렇게 큰 복을 받다니! 내 아들, 내 밥줄을 모두 되찾을 줄이야...

예전엔 이 정도면 그냥 살 만하다고 생각했는데... 알고 보니 나는 정말 복 받은 거였구나!', `MaleText_loc4`='好运是多么眷顾我啊？我的儿子，我的生意，全都回来了……

真没想到，我有一天会为这些东西而心满意足。我真是太幸运了！', `MaleText_loc5`='我的運氣居然這麼好?我兒子活著回到我身邊了...

想到我在一天內就能獲得這麼多，我真的是太幸運了!', `MaleText_loc7`='¿Cómo puede sonreírme tanto la fortuna? Mi hijo y mi sustento han vuelto a mí...

