UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진주지느러미 부족은 우리를 믿지 않네. 우선 우리에게 악한 의도가 전혀 없음을 보여줘야 하네.', `MaleText_loc4`='珠鳍部族不信任我们，我们必须向他们表明我们没有恶意。', `MaleText_loc5`='珠鰭一族不相信我們。我們必須向他們證明自己沒有惡意。', `MaleText_loc7`='Los Aleta de Nácar no confían en nosotros. Tenemos que demostrarles que no pretendemos ningún mal.' WHERE `ID`=61156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 종족과 친분을 맺는 편이 현명할 것 같네.', `MaleText_loc4`='结交这些人或许是个明智的主意。', `MaleText_loc5`='和這些人做朋友也許是件明智的事。', `MaleText_loc7`='Lo más inteligente sería hacernos amigos de esta gente.' WHERE `ID`=61157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지친 여행자여, 당신을 여기로 실어 온 물을 축복합니다. 우리 여관의 잔잔한 안개 속에서 푹 쉬십시오.', `MaleText_loc4`='感谢将你送来我店里的水流，疲劳的旅者。请在旅店内的舒缓之雾中消除你的疲劳吧。', `MaleText_loc5`='保佑水流，疲憊的旅者，它將你帶來我的岸邊。在我旅店平靜的霧氣中好好休息吧。', `MaleText_loc7`='Benditas sean las aguas que te arrastraron hasta mi orilla, $gfatigado viajero:fatigada viajera;. Descansa entre el vaho relajante de mi posada.' WHERE `ID`=61158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친절하게 맞아 주셔서 감사합니다.', `MaleText_loc4`='感谢你的热情好客。', `MaleText_loc5`='謝謝你的熱情款待。', `MaleText_loc7`='Gracias por tu hospitalidad.', `FemaleText_loc1`='친절하게 맞아 주셔서 감사해요.', `FemaleText_loc4`='感谢你的热情好客。', `FemaleText_loc5`='謝謝你的熱情款待。', `FemaleText_loc7`='Gracias por tu hospitalidad.' WHERE `ID`=61159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 말로 할 수 있는 일은 여기까지인 것 같군. 이제 행동으로 진주지느러미 부족에게 우리 뜻을 보여줘야겠어.', `MaleText_loc4`='好吧，你已用尽了所有的外交手段。现在，我们只能靠自己的实际行动来向珠鳍部族证明我们的诚意了。', `MaleText_loc5`='你已經在外交手段上盡了最大努力。現在我們只能以我們的行動向珠鰭證明自己。', `MaleText_loc7`='Bueno, has hecho lo que has podido a través de la diplomacia. Ahora, solo nos queda demostrar nuestra valía a los Aleta de Nácar con nuestros actos.' WHERE `ID`=61160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산길에서 기껏 살아났는데 여기서 죽게 됐구나!', `MaleText_loc4`='你在崎岖的山路中都幸存了下来，没想到却死在了这里！', `MaleText_loc5`='你千辛萬苦撐過山道，但只會死在這裡!', `MaleText_loc7`='¡Has sobrevivido al paso de la montaña para acabar muriendo aquí!' WHERE `ID`=61161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 물예언자로서 많은 의식을 거행합니다. 하지만 지금까지 한 번도 거행해 보지 않은 의식이 하나 있습니다. 바로 정신의 타락을 정화하는 의식이지요.

샤오하오 황제께서 판다리아 땅을 거닐던 전설 속 시대 이후로는 쓸 필요가 없었던 의식입니다.

그런데 지금은 필요할 것 같군요...', `MaleText_loc4`='作为水语者，我举行过许多仪式。可其中一种仪式，我却从来没有举行过——那就是净化精神腐蚀的仪式。

这是一种古老的仪式，自从少昊行走在潘达利亚的传说时代结束后，就再也没有使用过。

恐怕我们现在要用到它了……', `MaleText_loc5`='做為一個水語者，我執行過很多儀式。但有一個儀式我從沒執行過，那就是淨化內心腐化的儀式。

這是個古老的儀式，從紹昊仍在潘達利亞的傳說時代開始，我們就不曾有需要執行過這個儀式。

現在我們恐怕需要了...', `MaleText_loc7`='Como orador del agua, realicé muchos rituales. Sin embargo, hay uno que nunca he realizado: purificar la corrupción mental.

Es un ritual ancestral que no hemos necesitado desde días legendarios, cuando Shaohao transitaba por Pandaria.

Me temo que ahora lo necesitamos...' WHERE `ID`=61162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 싸워, 약골들아!', `MaleText_loc4`='加油打啊，胆小鬼们！', `MaleText_loc5`='攻擊大力點，弱雞!', `MaleText_loc7`='¡Luchad con más tesón, debiluchos!' WHERE `ID`=61163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 느껴 봐! 분노의 일격을 날리라고!', `MaleText_loc4`='感受你的怒火吧！将它融入你的攻击吧！', `MaleText_loc5`='感受你的憤怒!化憤怒為力量!', `MaleText_loc7`='¡Sientan la ira! ¡Utilízenla en sus golpes!' WHERE `ID`=61164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군. 인정사정 봐 주지 말란 말야!', `MaleText_loc4`='真是绵软无力。拿出点血性来！', `MaleText_loc5`='真是可悲的一擊。再殘暴一點!', `MaleText_loc7`='Vaya golpe patético. ¡Más brutalidad!' WHERE `ID`=61165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 약해!', `MaleText_loc4`='真是太弱了！', `MaleText_loc5`='太弱了!', `MaleText_loc7`='¡Demasiado débil!' WHERE `ID`=61166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 같아서는 타락한 동족을 모두 정화하고 싶지만, 지도자로서 타락에 빠지지 않은 동족을 버릴 수는 없습니다.

이 사악한 힘이 더 퍼지지 못하게 막아야 합니다. 그런 다음에 아직 깨끗한 이들을 이끌고 자유를 찾아 떠나겠습니다.', `MaleText_loc4`='虽然我很愿意净化所有被腐化的同胞，但我也不能让那些未被腐化的族人变成一盘散沙。

我们必须阻止邪恶之力的蔓延，然后我将领导那些纯洁如初的族人走向自由。', `MaleText_loc5`='雖然我很想要淨化我被污染的弟兄們，但我也不能讓其他沒被污染的人陷入群龍無首的狀態。

我們必須阻止這種惡劣影響繼續蔓延，然後我會領導我們之中仍然純潔的人們到安全的地方去。', `MaleText_loc7`='Aunque me encantaría purificar a todos mis hermanos corruptos, no puedo permitir que aquellos que no han sucumbido a la corrupción se queden sin su líder.

Debemos detener esta influencia maligna y luego llevaré a aquellos de los nuestros que sigan siendo puros a la libertad.' WHERE `ID`=61167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이벤트를 초기화합니다. [PH]', `MaleText_loc4`='重置事件。[PH]', `MaleText_loc5`='重置事件。[PH]', `MaleText_loc7`='Reset the event. [PH]', `FemaleText_loc1`='이벤트를 초기화합니다. [PH]', `FemaleText_loc4`='重置事件。[PH]', `FemaleText_loc5`='重置事件。[PH]', `FemaleText_loc7`='Reset the event. [PH]' WHERE `ID`=61168;
