UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요. 저는 관리인 폰치예요. 우리 만난 적이 있던가요? 제가 기억력이 썩 좋지 않아서요.', `MaleText_loc4`='你好。我是管理者彭启。我们以前见过面吗？我的记性不太好。', `MaleText_loc5`='哈囉。我是園丁彭奇。我們以前見過面嗎?我的記憶力不太好。', `MaleText_loc7`='Hola, soy el guardés Ponch. ¿Nos hemos visto antes? No tengo muy buena memoria.' WHERE `ID`=61181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFE9A2E수액 방울|r이 나무에서 뿜어져 나옵니다!', `MaleText_loc4`='|cFFFE9A2E腐蚀血球|r开始从树上渗出来了！', `MaleText_loc5`='|cFFFE9A2E樹汁水珠|r開始從樹上冒出來!', `MaleText_loc7`='¡Empiezan a salir |cFFFE9A2Eglóbulos de savia|r del árbol!' WHERE `ID`=61182;
