UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 내려놔요! 내가 심판 보려고 했단 말이에요!', `MaleText_loc4`='嘿！把我放回去！我要去给一场比赛当裁判！', `MaleText_loc5`='嘿!放我回去!我原本要為一場比賽擔任裁判的!', `MaleText_loc7`='¡Oye! ¡Devuélveme a mi sitio! ¡Iba a arbitrar un combate!' WHERE `ID`=61185;
