UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싫어! 지금 잠깐 못 자면 이따가 큰 낮잠 못 잔단 말이에요.', `MaleText_loc4`='不！！！在进入大赛前我要小试身手。', `MaleText_loc5`='不!如果不打盹一下我就無法好好睡大覺的。', `MaleText_loc7`='¡Noo! Si no me echo otra siesta no estaré listo para mi gran cabezada.' WHERE `ID`=61188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 누군지 몰라요? 난 무시무시한 포식자라고요! 할퀴어 버릴 테다!', `MaleText_loc4`='你难道不知道我是做什么的？我是一个凶猛的掠食者！我要剁了你！', `MaleText_loc5`='你不知道我是什麼嗎?我是個兇猛的掠食者!我會把你剁碎!', `MaleText_loc7`='¿No sabes lo que soy? ¡Soy un fiero depredador! ¡Voy a partirte en dos!' WHERE `ID`=61189;
