UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 싸움이라고?', `MaleText_loc4`='你把那也叫战斗吗？', `MaleText_loc5`='你稱那個為戰鬥?', `MaleText_loc7`='¿A eso llamas tú pelear?' WHERE `ID`=61195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통바지 아저씨! 힘내요! 주먹을 힘껏 내질러요!', `MaleText_loc4`='来啊，软脚先生！用力出拳啊！', `MaleText_loc5`='上啊軟腳先生!用點力打啊!', `MaleText_loc7`='¡Vamos, don Tirillas! ¡Golpea con ganas!' WHERE `ID`=61196;
