UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우승!', `MaleText_loc4`='胜利！', `MaleText_loc5`='勝利!', `MaleText_loc7`='¡Victoria!' WHERE `ID`=61198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐예요? 그걸 공격이라고 한 거예요? 아닌 것 같던데. 도와 달라고 소리치는 것 같았다고요.', `MaleText_loc4`='噢，得了吧。那是什么？那是一记重拳吗？看起来一点也不像。倒像是在哭着求人救命呢。', `MaleText_loc5`='喔拜託，那是什麼啊?那是出拳嗎?那看起來不像出拳。那看起來像哭著求救。', `MaleText_loc7`='Oh, vamos. ¿Qué ha sido eso? ¿Era un puñetazo? A mí no me lo ha parecido. Me ha parecido una llamada de socorro.' WHERE `ID`=61199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 폰치예요. 마당을 쓸고 새끼들을 돌보지요. 사람들 말로는 제가 옛날에 용사였대요. 꽤나 멋있었겠죠?', `MaleText_loc4`='我是彭启。我打扫地面，还照看小猫。他们说我曾经是位勇士。那一定很棒吧。', `MaleText_loc5`='我是彭奇。我負責打掃和照顧幼虎。他們跟我說我曾經是個冠軍。那時候一定很棒。', `MaleText_loc7`='Me llamo Ponch. Limpio el terreno y cuido de los gatitos. Me han dicho que una vez fui un campeón. Debió de estar bien.' WHERE `ID`=61200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가... 찾고 있었던 것 같은데, 뭔지 기억이 안 나요.', `MaleText_loc4`='我……我觉得我是在找寻什么东西。但又记不起来在找什么。', `MaleText_loc5`='我...我感覺我在尋找某種東西。但是我不記得是什麼了。', `MaleText_loc7`='Si... siento como si buscara algo, pero no me acuerdo de qué.' WHERE `ID`=61201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 길에 쌓인 나뭇잎을 쓸어 버리는 걸 좋아해요. 나뭇잎이 많으면 요마가 꼬이거든요. 수도사들은 요마 싫어해요.', `MaleText_loc4`='我喜欢清扫小径上的落叶。过多的落叶会引来林精。寺庙武僧不喜欢林精。', `MaleText_loc5`='我喜歡將小徑上的樹葉掃掉。太多樹葉會引來妖精，廟裡的僧侶不喜歡妖精。', `MaleText_loc7`='Me gusta quitar las hojas de los senderos. El exceso de hojas atrae a los duendes. A los monjes del templo no les gustan los duendes.' WHERE `ID`=61202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 구석에 몰렸다!', `MaleText_loc4`='他走投无路了！', `MaleText_loc5`='他無路可逃了!', `MaleText_loc7`='¡Está acorralado!', `FemaleText_loc1`='놈이 구석에 몰렸다!', `FemaleText_loc4`='他走投无路了！', `FemaleText_loc5`='他無路可逃了!', `FemaleText_loc7`='¡Está acorralado!' WHERE `ID`=61203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 잡았다!', `MaleText_loc4`='我们抓住他了！', `MaleText_loc5`='我們抓到他了!', `MaleText_loc7`='¡Lo tenemos!', `FemaleText_loc1`='놈을 잡았다!', `FemaleText_loc4`='我们抓住他了！', `FemaleText_loc5`='我們抓到他了!', `FemaleText_loc7`='¡Lo tenemos!' WHERE `ID`=61204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적어도 왕자님이 살아 계신 건 확인했군요. 수고 많으셨습니다, $n 님. 그런데 루샨 장로가 당신을 찾더군요. 가서 이야기해 보십시오.', `MaleText_loc4`='至少我们知道安度因还活着。干得好，$n。现在，去找长老卢山吧。他已经问起你好几次了。', `MaleText_loc5`='至少我們知道安杜因還活著。做得好，$n。現在去找長者廬山談談。他已經找你一段時間了。', `MaleText_loc7`='Al menos sabemos que Anduin está vivo. Bien hecho, $n. Ahora ve a hablar con el ancestro Lusshan. Ha estado preguntando por ti.' WHERE `ID`=61205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 루더스! 안 보고 싶을 거야!', `MaleText_loc4`='再见了，拉瑟斯！我们不会想念你的！', `MaleText_loc5`='再見了，魯瑟斯!我們不會想念你的!', `MaleText_loc7`='¡Pírate, Riendas! ¡No te echaremos de menos!' WHERE `ID`=61206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 왜 온 거지? 대체 원하는 게 뭔가?', `MaleText_loc4`='你们来这里干什么？你们有什么目的？', `MaleText_loc5`='你是為何而來?你的意圖是什麼?', `MaleText_loc7`='¿Por qué has venido aquí? ¿Cuáles son tus intenciones?' WHERE `ID`=61207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화로운 동맹을 원한다고 했지만, 탄탄한 방어구와 여러 무기를 지니고 있군.$B$B그건 뭐라고 변명할 텐가?', `MaleText_loc4`='你们嘴上说是为和平而来，但实际上却是武装到了牙齿。$B$B这你们该作何解释？', `MaleText_loc5`='你說你為和平而來，但你卻穿著堅固的護甲和攜帶著許多武器。$B$B你要如何解釋?', `MaleText_loc7`='Afirmas que vienes en son de paz, pero vistes pesada armadura y llevas muchas armas.$b$b¿Cómo explicas eso?' WHERE `ID`=61208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게는 우리 부족의 안전이 가장 중요한 문제이네. 조금 조심스럽게 행동한다고 해서 비난하지는 않겠지?', `MaleText_loc4`='部族的安全才是我首要考虑的，你会怪我过于谨慎吗？', `MaleText_loc5`='一族的安危是我最優先的顧慮。我這樣的謹慎，你能怪我嗎?', `MaleText_loc7`='La seguridad de la tribu es mi mayor preocupación. ¿Me culpas por ser tan cauteloso?' WHERE `ID`=61209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 전문화를 초기화하려면 어떻게 해야 합니까?', `MaleText_loc4`='我该如何重置我的职业专精？', `MaleText_loc5`='我要怎麼重設我的職業專精?', `MaleText_loc7`='¿Cómo restablezco mi especialización de clase?', `FemaleText_loc1`='직업 전문화를 초기화하려면 어떻게 해야 하나요?', `FemaleText_loc4`='我该如何重置我的职业专精？', `FemaleText_loc5`='我要怎麼重設我的職業專精?', `FemaleText_loc7`='¿Cómo restablezco mi especialización de clase?' WHERE `ID`=61210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문양을 제거하려면 어떻게 해야 합니까?', `MaleText_loc4`='我该如何重置我的雕文？', `MaleText_loc5`='我要怎麼重設我的職業雕紋?', `MaleText_loc7`='¿Cómo restablezco mis glifos?', `FemaleText_loc1`='문양을 제거하려면 어떻게 해야 하나요?', `FemaleText_loc4`='我该如何重置我的雕文？', `FemaleText_loc5`='我要怎麼重設我的職業雕紋?', `FemaleText_loc7`='¿Cómo restablezco mis glifos?' WHERE `ID`=61211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 고기다!', `MaleText_loc4`='新鲜的肉！', `MaleText_loc5`='新鮮的肉!', `MaleText_loc7`='¡Carne fresca!' WHERE `ID`=61212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일로 이곳에 온 겁니까, 이방인?', `MaleText_loc4`='你们来此有何贵干，陌生人？', `MaleText_loc5`='你來這裡有什麼事，陌生人?', `MaleText_loc7`='¿Qué te trae por aquí, $gforastero:forastera;?' WHERE `ID`=61213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$R|1이여;여;, 섣부른 행동은 하지 마십시오. 우리가 지켜보고 있습니다.', `MaleText_loc4`='$R，别想在这里搞事。我们盯着你呢。', `MaleText_loc5`='$R，不要輕舉妄動。我們正盯著你。', `MaleText_loc7`='$R, no intentes hacer ninguna estupidez. Te estamos vigilando.' WHERE `ID`=61214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 대체 왜 온 겁니까, 외부인?', `MaleText_loc4`='你来这里干什么，外乡人？', `MaleText_loc5`='你是為何而來，外來人?', `MaleText_loc7`='¿Por qué has venido aquí, $gintruso:intrusa;?' WHERE `ID`=61215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 불친절한 게 아닙니다, 이방인. 그저 조심하는 것 뿐입니다.', `MaleText_loc4`='我们不是不友善，陌生人。我们只是很谨慎。', `MaleText_loc5`='我們並非不友善，陌生人，只是謹慎。', `MaleText_loc7`='No somos hostiles, sino precavidos.' WHERE `ID`=61216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 믿음을 얻으려면 노력해야 합니다.', `MaleText_loc4`='信任是要争取的，陌生人。', `MaleText_loc5`='信任是要爭取而來的，陌生人。', `MaleText_loc7`='Te has ganado nuestra confianza, $gforastero:forastera;.' WHERE `ID`=61217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 왜 우리가 당신을 믿어야 합니까?', `MaleText_loc4`='我们为什么要相信你，陌生人？', `MaleText_loc5`='我們為什麼要相信你，陌生人?', `MaleText_loc7`='¿Por qué deberíamos confiar en ti, $gextraño:extraña;?' WHERE `ID`=61218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허! 대단했습니다. 당신과 함께라면 심심할 틈이 없겠어요.', `MaleText_loc4`='嚯嚯！真快呀！我喜欢你，$c。有你在就很好玩儿。', `MaleText_loc5`='呵哈哈!差一點!我喜歡你，$c。你讓事情變得很有趣。', `MaleText_loc7`='¡Uooo! ¡Qué emoción! Me caes bien, contigo pasan cosas interesantes.' WHERE `ID`=61219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑스런 꿀백합! 채석장에서 돌아왔어! 여보야를 위해 비취를 가져왔지.', `MaleText_loc4`='雪百合！我们从采石场回来啦！我特别为你带回一车玉石哦，我的小甜心。', `MaleText_loc5`='雪百合!我們從礦場回來了!我有個專屬於你的特別禮物，我的小甜甜。', `MaleText_loc7`='¡Lirio de las nieves, ya volvimos de la cantera! Tenemos una entrega muy especial para ti, cariño.' WHERE `ID`=61220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곰돌씨! 아니... 너무 늦었잖아요.', `FemaleText_loc4`='亲爱的！！我是说……时间快到了。', `FemaleText_loc5`='我的蜜糖熊熊!!我是說...時間差不多了。', `FemaleText_loc7`='¡Oso meloso! Digo... Ya era hora.' WHERE `ID`=61221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꿀백합 같은 소리 하시네! 내가... 우리가 얼마나 걱정했는데...', `FemaleText_loc4`='别叫我“雪百合”笨蛋！我……我们都快担心死你啦！', `FemaleText_loc5`='別叫我雪百合!我擔...我們都擔心死了。', `FemaleText_loc7`='¡No me vengas con "lirio de las nieves"! Estaba... Estábamos preocupadísimos por ti.' WHERE `ID`=61222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하게 해서 미안해, 우리 달콤털 여왕님. 사실, 여기 이 친구가 날 살려줬어. 정말 다행이었지.', `MaleText_loc4`='抱歉让你久等了，甜心。我知道你有多担心。事实上，是这个陌生人救了我这把老骨头。真不可思议。', `MaleText_loc5`='抱歉讓妳久等了，小糖毛。我知道妳有多擔心。實際上，是這位陌生人救了我的老骨頭。想不到吧。', `MaleText_loc7`='Siento haberte hecho esperar, azucarillo. Sé lo mucho que te preocupas. La verdad es que me han tenido que salvar el pellejo. ¿Quién lo hubiera dicho?' WHERE `ID`=61223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 의미심장하게 윙크합니다.', `MaleText_loc4`='%s偷偷对你眨了眨眼。', `MaleText_loc5`='%s對你詭異地眨了眨眼。', `MaleText_loc7`='%s te lanza un guiño disimulado.' WHERE `ID`=61224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 비취는 내가 아니라, 여기 전승지기님이 기다리고 계셨... 오...', `FemaleText_loc4`='还有这车玉石并不是给我的，豪！尊敬的游学者一直在等——噢……', `FemaleText_loc5`='還有這批貨可不是為了我而送的，老郝!高貴的博學行者已經等了...喔...', `FemaleText_loc7`='¡Y la entrega no es para mí, Hao! El honorable eremita ha estado esperan... oh...' WHERE `ID`=61225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공포의 광장으로 도망칩니다!', `MaleText_loc4`='%s退回了恐惧之境！', `MaleText_loc5`='%s往恐怖瀚洋撤退了!', `MaleText_loc7`='¡El %s se retira a la Extensión aterradora!' WHERE `ID`=61226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 늘 땅에 발을 딛고 있어야 한다.', `MaleText_loc4`='魔古族就应该脚踏实地。', `MaleText_loc5`='魔古永遠都不該倒下。', `MaleText_loc7`='Los pies de un Mogu siempre deberían estar en el suelo.' WHERE `ID`=61227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거워!', `MaleText_loc4`='它烧起来了！', `MaleText_loc5`='燒起來了!', `MaleText_loc7`='¡Quema!' WHERE `ID`=61228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 시작되었으니, 네가 막을 순 없을 것이다!', `MaleText_loc4`='一旦开始，你便无法阻止！', `MaleText_loc5`='你無法阻止已發生的事!', `MaleText_loc7`='¡No puedes detener lo que se ha iniciado!' WHERE `ID`=61229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근위병들은 시작일 뿐이다!', `MaleText_loc4`='这些守卫者只是个开始！', `MaleText_loc5`='這些守護者只是個開場罷了!', `MaleText_loc7`='¡Eh''tos guah''dianes son solo el principio!' WHERE `ID`=61230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 군대가 우리에게 이 땅을 되찾아 줄 것이다!', `MaleText_loc4`='雷电之王的大军将为我们夺回这片土地！', `MaleText_loc5`='雷王的軍隊會為我們拿回這塊土地!', `MaleText_loc7`='¡El ejéh''cito del Rey del Trueno va a recuperar eh''tas tierras para nosotros!' WHERE `ID`=61231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕이 돌아올 것이다!', `MaleText_loc4`='雷电之王会回来的！', `MaleText_loc5`='雷王將會再臨!', `MaleText_loc7`='¡El Rey del Trueno va a regresar!' WHERE `ID`=61232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴지느냐? 천둥이 다가오고 있다...', `MaleText_loc4`='你能感觉到吗？雷电之王离我们越来越近了……', `MaleText_loc5`='你感覺到了嗎?雷霆越來越接近了...', `MaleText_loc7`='¿Puedes sentih''lo? El Trueno se eh''tá aceh''cando...' WHERE `ID`=61233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 감사합니다. 이제 훈련을 충분히 받은 것 같습니다.', `MaleText_loc4`='谢谢你，$n。我已经训练得很充分了。', `MaleText_loc5`='謝謝你，$N。我已經受到充足的訓練了。', `MaleText_loc7`='Gracias, $n. He entrenado bastante.' WHERE `ID`=61234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다, $n 님. 이 단검으로 수많은 적을 쓰러뜨리겠습니다.', `MaleText_loc4`='谢谢你的帮助，$n。我的匕首将刺穿许多敌人的心脏。', `MaleText_loc5`='謝謝你的幫忙，$N。我的匕首會刺穿許多敵人。', `MaleText_loc7`='Gracias por tu ayuda, $n. Mis dagas cortarán a muchos enemigos.' WHERE `ID`=61235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 검과 방패로 가족과 친구들을 보호하겠습니다.', `MaleText_loc4`='有了这把剑和这面盾，我会守护好我的朋友及家人。', `MaleText_loc5`='有了這個盾牌和劍，我會保護我的朋友和家人。', `MaleText_loc7`='Con este escudo y esta espada, protegeré a mi familia y a mis amigos.' WHERE `ID`=61236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 물의 비밀을 깨닫게 되었습니다. 이 재능을 사용하여 마을을 돕겠습니다.', `MaleText_loc4`='我现在已经了解水的奥秘了，我将利用这些天赋来帮助村子。', `MaleText_loc5`='我已了解水的奧秘。我會運用這份賞賜來幫助村莊。', `MaleText_loc7`='Ahora conozco los secretos de las aguas. Utilizaré estos dones para ayudar al pueblo.' WHERE `ID`=61237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님! 형제들과 함께 전투에 뛰어들기 전에, 저는 우선 치유 기술을 연습해야 합니다.', `MaleText_loc4`='你好啊，$n！在我上战场和兄弟并肩作战之前，我必须先练好我的治疗术。', `MaleText_loc5`='你好，$n!在我和弟兄們一起上場戰鬥前，我必須練習治癒之術。', `MaleText_loc7`='¡Saludos, $n! Antes de unirme con mis hermanos en la batalla, debo practicar las artes de la sanación.' WHERE `ID`=61238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 칼날은 날카롭지만, 제 실력은 아직 무딥니다. 배울 준비가 되었습니다, $n 님.', `MaleText_loc4`='我的刀很锋利，但我的技巧太笨拙了。我准备好向你学习了，$n。', `MaleText_loc5`='我的刀刃銳利，但我的技巧還需磨練。我準備好要學習了，$n。', `MaleText_loc7`='Mis hojas son incisivas, pero mi habilidad está desafilada. Estoy listo para aprender, $n.' WHERE `ID`=61239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신의 방패가 되겠습니다, $n 님. 당신을 보호하게 해 주십시오. 그러면 우리 마을을 지킬 만큼 실력이 늘겠지요!', `MaleText_loc4`='让我用盾牌来保护你吧，$n。请让我保护你，这样我才能更好地保护我的村子！', `MaleText_loc5`='讓我的盾為你效力，$n。容許我保護你，這樣我才能更好地保衛我的村莊。', `MaleText_loc7`='Deja que te preste mi escudo, $n. ¡Permíteme protegerte, pues es la mejor forma de defender a mi pueblo!' WHERE `ID`=61240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술을 가르쳐 주십시오, $n 님! 물의 힘을 조율하여 적을 무찌르겠습니다!', `MaleText_loc4`='教教我，$n！我要借用水的力量来消灭我们的敌人！', `MaleText_loc5`='教導我，$n!我會運用水的力量消滅我們的敵人!', `MaleText_loc7`='¡Enséñame, $n! ¡Concentraré las fuerzas del agua para destruir a nuestros enemigos!' WHERE `ID`=61241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먹을 거 필요해요? 나 혼자 다 만들었어요!', `FemaleText_loc4`='想来点吃的吗？我自己做的！', `FemaleText_loc5`='想要一點食物嗎?全部都是我自己做的!', `FemaleText_loc7`='¿Quieres algo de comer? ¡Lo he preparado yo!' WHERE `ID`=61242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 복종해라, 짐승아!', `MaleText_loc4`='服从我，畜生！', `MaleText_loc5`='服從我，野獸!', `MaleText_loc7`='¡Obedéceme, bestia!' WHERE `ID`=61243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라와! 아니면 이 자리에서 널 익혀서 먹겠다.', `MaleText_loc4`='跟着！否则我立马就把你煮了吃掉。', `MaleText_loc5`='跟好!否則我會當場把你煮來吃掉。', `MaleText_loc7`='¡Ven aquí! O te cocinaré y comeré aquí mismo.' WHERE `ID`=61244;
