UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $p. 우리 대원이 아닌 것치고는 잘 싸우는군. 이제부터는 내가 맡겠소.', `MaleText_loc4`='谢谢你，$p。虽然不是我们的一员，但你打得很好。剩下的就交给我吧。', `MaleText_loc5`='謝謝你，$p。對個外人來說你很會戰鬥。接下來的我能處理。', `MaleText_loc7`='Gracias, $p. Peleas bien para no ser de nuestra orden. Ya me ocupo yo del resto.' WHERE `ID`=61270;
