UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코바이가 우리를 공격하는 야운골 무리의 지도자라네... 하지만 문제의 근원은 그놈이 아닌 것 같네.', `MaleText_loc4`='科拜带领野牛人袭击了我们……但我并不认为他是问题的根源。', `MaleText_loc5`='柯巴率領揚古攻擊我們...但我不認為他是我們麻煩的源頭。', `MaleText_loc7`='Kobai dirige a los yaungol que nos están atacando... pero no creo que él sea el origen de nuestros problemas.' WHERE `ID`=61280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 적에게 덫을 놓는 거지...', `MaleText_loc4`='现在，我们触动进攻者周围的陷阱机关……', `MaleText_loc5`='現在，啟動我們對敵人設下的陷阱。', `MaleText_loc7`='Y ahora... activamos la trampa sobre nuestros asaltantes...' WHERE `ID`=61281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원에서 아무 기별이 없으니... 걱정이네.', `MaleText_loc4`='禅院……我有点担心，他们怎么一点消息都没有……', `MaleText_loc5`='僧院...沒聽到任何他們的消息讓我很擔心。', `MaleText_loc7`='El Monasterio... me preocupa que no hayamos tenido noticias de ellos...' WHERE `ID`=61282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑주술사들이 오그리마에 진정한 위협으로 다가오기 전에 막아야 하네.', `MaleText_loc4`='我们必须在他们真正威胁到奥格瑞玛之前阻止黑暗萨满。', `MaleText_loc5`='我們必須在黑暗薩滿成為奧格瑪真正的威脅之前，先阻止他們。', `MaleText_loc7`='Debemos detener al Chamán oscuro antes de que se conviertan en una verdadera amenaza para Orgrimmar.' WHERE `ID`=61283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 최정예 정찰병들이 돌아오지 않고 있어.', `MaleText_loc4`='我手下最好的斥候还没有回来。', `MaleText_loc5`='我最優秀的斥候還沒回來。', `MaleText_loc7`='Mis mejores exploradores aún no han vuelto.' WHERE `ID`=61284;
