UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 어머니는 나이가 너무 많아서 첫 왕국의 건립을 봤다지!', `MaleText_loc4`='你们的母亲老得经历过第一帝国的建立！', `MaleText_loc5`='你的媽媽老到經歷過第一個王朝的興起!', `MaleText_loc7`='¡Tu madre es tan vieja que vio nacer el primer reino!' WHERE `ID`=61291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 아버지는 너무 약해서 판다렌이 측은한 마음에 저녁 식사에 초대했다지!', `MaleText_loc4`='你们的父亲软弱无能，甚至要依靠熊猫人施舍的嗟来之食活命！', `MaleText_loc5`='你的爸爸弱到連熊貓人都可憐他，帶他回家吃晚餐!', `MaleText_loc7`='¡Tu padre es tan débil que un pandaren se apiadó de él y lo invitó a cenar!' WHERE `ID`=61292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 부족은 너무 저질이라 호젠의 "멍청한" 농담에도 등장한다지!', `MaleText_loc4`='你们的氏族下等至极，连猢狲都敢嘲笑你们！', `MaleText_loc5`='你的部族卑微到猴人都拿你們當笑柄!', `MaleText_loc7`='¡Tu clan es tan despreciable que hasta los hozen se ríen de él!' WHERE `ID`=61293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무기는 어디서 났나, 언니가 주던?', `MaleText_loc4`='你是从哪找到那把武器的，你姐姐那？', `MaleText_loc5`='你那把武器是跟誰拿的，你姊姊嗎?', `MaleText_loc7`='¿A quién le has quitado esa arma, a tu hermana?' WHERE `ID`=61294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿! $c님! 이쪽이에요! 계단 옆! 쳐다보지는 말고 그냥 이리로 와요!', `FemaleText_loc4`='喂！$c！我在楼梯这边！别盯着我看！过来就是了。', `FemaleText_loc5`='噓!$c!到階梯這裡來!不要看我!過來就對了。', `FemaleText_loc7`='¡Pst! ¡$c! ¡Aquí, junto a las escaleras! ¡No, no me mires! Solo ven aquí.' WHERE `ID`=61295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 무적의 사마귀 군단에 정면으로 맞서시겠다? 죽여주마!', `MaleText_loc4`='蠢货！竟敢正面挑战强大的螳螂妖？你会死得很快的。', `MaleText_loc5`='蠢蛋!敢跟螳螂人的力量正面衝突?你的死期就要到了!', `MaleText_loc7`='¡Necios! ¿Atacan al ejército mántide de frente? ¡Sus muertes serán rápidas!' WHERE `ID`=61296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무리전사들이여, 공격! 뼈에서 살을 발라내!', `MaleText_loc4`='虫群，攻击！把他们统统撕碎！', `MaleText_loc5`='蟲群們，攻擊!將他們碎屍萬段!', `MaleText_loc7`='¡Enjambristas, ataquen! ¡Arránquenles la carne de los huesos!' WHERE `ID`=61297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 누더기골렘이 순수한 죽음의 숨결을 내뿜습니다! 곁에서 물러나십시오!', `MaleText_loc4`='煞魔畸体正在喷吐精纯死气！快离开他身边！', `MaleText_loc5`='被煞附身的憎惡體吐出純粹死亡的氣息!遠離他!', `MaleText_loc7`='¡La abominación sha exhala muerte pura! ¡Aléjate de él!' WHERE `ID`=61298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='융단 폭격 실시! 호박날개를 출격시켜!', `MaleText_loc4`='对平台进行地毯式轰炸！派遣琥珀之翼！', `MaleText_loc5`='地毯式轟炸這座平台!派琥珀之翼出動!', `MaleText_loc7`='¡Bombardeen la plataforma! ¡Envíen al alacárabe!' WHERE `ID`=61299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러나라! 무모하게 죽음을 향해 뛰어드는 꼴이다! 생각을 좀 해 봐야겠다...', `MaleText_loc4`='后退！你们这是在往死路上撞啊！我得想想……', `MaleText_loc5`='撤退!你只是無意義地送死!我必須想想...', `MaleText_loc7`='¡Deteneos! ¡Vais derechos a la muerte! Creo que...' WHERE `ID`=61300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리! 더 빨리 공격해라! 우리 모두를 막아낼 순 없을 거다!', `MaleText_loc4`='快点！我们必须再快点！他们不可能把我们全挡住！', `MaleText_loc5`='快一點!我們必須更迅速地攻擊!他們無法抵擋我們全部!', `MaleText_loc7`='¡Más deprisa! ¡Debemos atacar más deprisa! ¡No pueden repelernos a todos a la vez!' WHERE `ID`=61301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='광전사 돌입! 모두 파괴하라!', `MaleText_loc4`='冲进去，狂战士们！把他们统统都消灭！', `MaleText_loc5`='進去吧，狂戰士!把他們全部消滅!', `MaleText_loc7`='¡Adelante, rabiosos! ¡Destruidlos a todos!' WHERE `ID`=61302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두! 모두 퍼부어라! 저 겁쟁이들을 없애버려! 감히 우리를 바보로 만들다니!', `MaleText_loc4`='全体都有，全力进攻！他们在愚弄我们，杀了这些懦夫！', `MaleText_loc5`='大家聽著!把所有的東西都送過去!殺死這些懦夫，他們害我們看起來像傻瓜!', `MaleText_loc7`='¡A todos! ¡Enviadlos a todos! ¡Exterminad a estos cobardes, nos están ridiculizando!' WHERE `ID`=61303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그까짓 방어 태세는 아무 것도 아니다! 내가 모두 무너뜨리고 네놈들 머리카락을 기념품으로 챙겨가 주마!', `MaleText_loc4`='你们的防御毫无意义！我要把你们的脑袋砍下来当成战利品！', `MaleText_loc5`='你的防禦一點用都沒有!我要宰了你並把你的頭當作戰利品!', `MaleText_loc7`='¡Sus defensas no sirven para nada! ¡Les arrancaré la cabeza y las guardaré como trofeos!' WHERE `ID`=61304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑주술사의 힘이 너를 집어 삼키리라!', `MaleText_loc4`='让黑暗萨满的力量压倒你吧！', `MaleText_loc5`='黑暗薩滿的力量將淹沒你!', `MaleText_loc7`='¡El poder del Chamán oscuro te aplastará!' WHERE `ID`=61305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽는 건... 아무 의미도... 없다...', `MaleText_loc4`='我的死亡……毫无……意义……', `MaleText_loc5`='我的死...不算...什麼...', `MaleText_loc7`='Mi muerte... no significa... nada.' WHERE `ID`=61306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 얼라이언스에 합류하겠느냐?', `MaleText_loc4`='你确定要加入联盟吗？', `MaleText_loc5`='你確定你準備好要加入聯盟了嗎?', `MaleText_loc7`='¿Estás $gseguro:segura; de que estás $gpreparado:preparada; para unirte a la Alianza?' WHERE `ID`=61307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 말라 버렸어! 더 필요해!', `MaleText_loc4`='我渴死啦！再来点儿！', `MaleText_loc5`='我好渴!還要更多!', `MaleText_loc7`='¡Estoy seco! ¡Necesito recargar!' WHERE `ID`=61308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통을 받아라!', `MaleText_loc4`='苦难降临！', `MaleText_loc5`='吃苦頭吧!', `MaleText_loc7`='¡Aquí viene el dolor!' WHERE `ID`=61309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡담할 시간이 없네, $n.', `MaleText_loc4`='我可没时间闲聊，$n。', `MaleText_loc5`='我沒時間小聊了，$n。', `MaleText_loc7`='No tengo tiempo para chácharas, $n.' WHERE `ID`=61310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 일인가?', `MaleText_loc4`='你最好别拿琐事来烦我。', `MaleText_loc5`='這件事最好很重要。', `MaleText_loc7`='Espero que esto sea importante.' WHERE `ID`=61311;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 이들이 걱정되네요, $n 님.', `FemaleText_loc4`='我很担心其他人，$n。', `FemaleText_loc5`='我很擔心其他人，$n。', `FemaleText_loc7`='Me preocupa el resto, $n.' WHERE `ID`=61312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 이 밑에서 뭘 하려는 걸까요?', `FemaleText_loc4`='部落到底想在这里干什么？', `FemaleText_loc5`='部落想在那下面做什麼?', `FemaleText_loc7`='¿Qué intenta hacer la Horda allí?' WHERE `ID`=61313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔달라 부족은 도착하자마자 저 불쌍한 마을을 덮쳤습니다. 마을을 방어할 숙련된 전사도 전혀 없는데 말입니다! 당신이 도와줘야 합니다. 신이 무사히 마을로 갈 수 있게 해 줄 겁니다.', `FemaleText_loc4`='赞达拉部族伏击了那些可怜的村民。他们手无寸铁，根本无法保护自己！你必须帮帮他们。阿信会确保你能够安全抵达那个村子。', `FemaleText_loc5`='當贊達拉抵達時，那個可憐的村莊遭到伏擊。他們甚至沒有任何有戰鬥技巧的戰士可以保護自己!你必須去幫助他們。小新會確保你安全抵達村莊。', `FemaleText_loc7`='Esa pobre aldea sufrió una emboscada cuando llegaron los Zandalari. ¡Ni siquiera cuentan con buenos luchadores para defenderse! Tienes que ayudarles. Shin se ocupará de que llegues a la aldea sin problemas.' WHERE `ID`=61314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 누굴 선택하실 것 같나?', `MaleText_loc4`='你觉得王上会选谁？', `MaleText_loc5`='你認為國王會選誰?', `MaleText_loc7`='¿A quién crees que elegirá el rey?' WHERE `ID`=61315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족이 온 땅에서 가장 위대하니, 필시 우리 부족을 택하실 것이다!', `MaleText_loc4`='我们的氏族是这片土地上最了不起的氏族，他肯定会选我们！', `MaleText_loc5`='我們部族是這片土地上最偉大的，他必須選擇我們。', `MaleText_loc7`='¡Nuestro clan es el más poderoso de toda la zona, debe elegirnos a nosotros!' WHERE `ID`=61316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 부족은 아마 이제 마법을 쓰지도 못할걸. 그래서야 왕께 무슨 쓸모가 있겠나!', `MaleText_loc4`='我敢打赌，其他氏族甚至连魔法都不会用了。他们根本不可能为王上带来任何好处！', `MaleText_loc5`='我敢說那部族已經不能再使用魔法了。他們對國王還能有什麼幫助!', `MaleText_loc7`='Seguro que los otros clanes ya ni utilizan la magia. ¡Al rey no le servirán de nada!' WHERE `ID`=61317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 일부러 우리를 싸움을 붙이려고 한다는 얘길 들었다. 이래서야 얼마 지나지 않아 그렇게 되겠군.', `MaleText_loc4`='我听说王上打算强迫我们彼此厮杀。不可能，这样的话代价太大了。', `MaleText_loc5`='我聽說大王要強迫我們互相戰鬥。要讓那成真也不是什麼難事就是了。', `MaleText_loc7`='He oído que el Rey nos va a hacer luchar unos contra otros. Seguro que pasaba de todos modos.' WHERE `ID`=61318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 부족이 많아서야 싸움이 없을 수 없지.', `MaleText_loc4`='所有氏族都聚集在这里。我敢打赌，一场厮杀在所难免。', `MaleText_loc5`='所有的部族都在這裡，我敢打賭，戰爭就要爆發了。', `MaleText_loc7`='Con todos estos clanes por aquí seguro que la pelea empieza pronto.' WHERE `ID`=61319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕께서 일부러 우리를 싸움을 붙이려고 한다는 얘길 들었다. 이래서야 얼마 지나지 않아 그렇게 되겠군.', `MaleText_loc4`='我听说王上打算强迫我们彼此厮杀。不可能，这样的话代价太大了。', `MaleText_loc5`='我聽說大王要強迫我們互相戰鬥。要讓那成真也不是什麼難事就是了。', `MaleText_loc7`='He oído que el Rey nos va a hacer luchar unos contra otros. Seguro que pasaba de todos modos.' WHERE `ID`=61320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사우록이 우리 전리품을 가지고 도망친다. 잡아라!', `MaleText_loc4`='那个蜥蜴人在偷我们的战利品，抓住他！', `MaleText_loc5`='那個薩烏洛克就快要拿著我們的財寶逃跑了，抓住他!', `MaleText_loc7`='¡Ese saurok está huyendo con nuestro botín! ¡A por él!' WHERE `ID`=61321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사우록을 잡아라!', `MaleText_loc4`='抓住那个蜥蜴人！', `MaleText_loc5`='抓住那個薩烏洛克!', `MaleText_loc7`='¡Hay que coger a ese saurok!' WHERE `ID`=61322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공포의 광장 밑으로 꺼집니다!', `MaleText_loc4`='%s潜入了恐惧之境的水下！', `MaleText_loc5`='%s潛伏到恐怖瀚洋的水面之下!', `MaleText_loc7`='¡El %s se sumerge bajo la Extensión aterradora!' WHERE `ID`=61323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공포의 광장에 나타납니다!', `MaleText_loc4`='%s从恐惧之境的水下冒了出来！', `MaleText_loc5`='%s從恐怖瀚洋的水中出現了!', `MaleText_loc7`='¡El %s emerge de la Extensión aterradora!' WHERE `ID`=61324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 얼마나 더 있어야 되나 궁금해지던 차였습니다.', `MaleText_loc4`='我都开始怀疑，自己究竟要在这里待多久。', `MaleText_loc5`='我正在想自己能在那邊撐多久。', `MaleText_loc7`='¡Empezaba a preguntarme cuánto tiempo estaría aquí!', `FemaleText_loc1`='우리를 위해 큰일을 하시는군요.', `FemaleText_loc4`='朋友，你真是帮了我们大忙了。', `FemaleText_loc5`='你幫了很大的忙，朋友。', `FemaleText_loc7`='Nos has hecho un gran favor, valiente.' WHERE `ID`=61326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 그래도 제 불쌍한 뼈마디가 삐걱거리던 참이었습니다.', `MaleText_loc4`='我这把可怜的老骨头都要在这里僵住了。', `MaleText_loc5`='我想我還能動...', `MaleText_loc7`='Mis pobres y viejos huesos se estaban empezando a agarrotar...', `FemaleText_loc1`='덕분에 이 야만인들이 또 쳐들어오면 개운한 몸으로 싸울 수 있겠어요.', `FemaleText_loc4`='托你的福，等那些野蛮人回来时，我的体力应该已经恢复过来了。', `FemaleText_loc5`='多虧了你，我能在那些野蠻人回來前充分休息了。', `FemaleText_loc7`='Gracias a ti estaré descansada cuando vuelvan esos bárbaros.' WHERE `ID`=61327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 조우친을 공격하다니, 잔달라 트롤 녀석들 후회하게 될 겁니다!', `MaleText_loc4`='那些赞达拉巨魔会后悔进犯卓金村的！', `MaleText_loc5`='那些贊達拉會後悔攻擊驟晴村!', `MaleText_loc7`='¡Esos Zandalari se arrepentirán de atacar Zouchin!', `FemaleText_loc1`='온몸이... 쑤셔요...', `FemaleText_loc4`='真……疼啊……', `FemaleText_loc5`='好...痛...', `FemaleText_loc7`='Estoy... agarrotada...' WHERE `ID`=61328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 친구.', `MaleText_loc4`='非常感谢你，朋友。', `MaleText_loc5`='朋友，我非常感謝你。', `MaleText_loc7`='Te estoy muy agradecido, $gamigo:amiga;.', `FemaleText_loc1`='당신은 제 영웅이에요!', `FemaleText_loc4`='你是我的英雄！', `FemaleText_loc5`='你是我的英雄!', `FemaleText_loc7`='¡Eres mi héroe!' WHERE `ID`=61330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여로에서 스스로에 대해 생각보다 많은 것을 깨닫게 된다네.', `MaleText_loc4`='有时，我们能在旅途中意外地看清自己。', `MaleText_loc5`='有時我們所走過的路讓我們學到更多，而且程度超乎我們的預期。', `MaleText_loc7`='En ocasiones, las sendas que recorremos nos enseñan más sobre nosotros mismos de lo que cabría esperar.' WHERE `ID`=61331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 사람들의 도움을 받으면 잔달라 부족을 추적할 수 있을 걸세.', `MaleText_loc4`='在村民的帮助下，我们一定能找到那些赞达拉巨魔。', `MaleText_loc5`='有了村民的幫助，我們一定可以找到贊達拉。', `MaleText_loc7`='Con la ayuda de los aldeanos seguro que encontraremos a los Zandalari.' WHERE `ID`=61332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 연이 다시 닿기를 비네, $n! 그때까지 안전하고 뜻깊은 여로를 걷게나.', `MaleText_loc4`='希望我们会再次相见，$n。在那之前，祝你的旅途平安且充满意义。', `MaleText_loc5`='$n，我希望我們能再見面!在那之前，願你的旅程安全且充滿意義。', `MaleText_loc7`='¡Espero que nuestros caminos vuelvan a cruzarse, $n! Hasta entonces, te deseo un viaje sin contratiempos y lleno de sentido.' WHERE `ID`=61333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 주웠어! 내 거야!', `MaleText_loc4`='我找到它了！它是我的了！', `MaleText_loc5`='我找到了!它是我的了!', `MaleText_loc7`='¡Yo la encontré! ¡Es mía!' WHERE `ID`=61334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내 칼을 빼앗으려고 하는 거야? 내 거란 말이야!', `MaleText_loc4`='你为什么想抢走我的剑？这是我的剑！', `MaleText_loc5`='為什麼你想拿走我的劍?這是「我的」劍!', `MaleText_loc7`='¿Por qué intentas llevarte mi espada? ¡Es MI espada!' WHERE `ID`=61335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼을 내버려 둬! 줬다가 뺐는 게 어딨어!', `MaleText_loc4`='离我的剑远点！不准把它拿走！', `MaleText_loc5`='離我跟我的劍遠點!不准再拿走了!', `MaleText_loc7`='¡Déjame, y deja la espada! ¡No vale volver a cogerla!' WHERE `ID`=61336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이가 칼을 잃어버리면, 그 칼은 그때부터 멍청이 칼이 아니지!', `MaleText_loc4`='如果一个傻瓜把剑弄丢了，那这把剑就不再属于这个傻瓜了！', `MaleText_loc5`='如果笨蛋丟了劍，那這把劍就不再是笨蛋的劍了!', `MaleText_loc7`='¡Si hombre tonto pierde espada ya no es espada de hombre tonto!' WHERE `ID`=61337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 칼 도둑아. 저리 가!', `MaleText_loc4`='卑鄙的抢剑贼。滚开！', `MaleText_loc5`='卑鄙的偷劍賊，滾開!', `MaleText_loc7`='Malvados roba-espadas. ¡Fuera!' WHERE `ID`=61338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰, 못된 녀석! 네 칼도 빼앗아 버리는 수가 있다!', `MaleText_loc4`='住手，卑鄙的家伙！小心我去抢你的剑！', `MaleText_loc5`='別那麼小氣嘛!也許我把你的劍也拿走!', `MaleText_loc7`='¡Paren, alimañas! ¡A lo mejor también me llevo su espada!' WHERE `ID`=61339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주운 사람이 임자야! 모르는 척하지 마.', `MaleText_loc4`='谁拿到就是谁的！别傻了。', `MaleText_loc5`='誰拿走就是誰的!別傻了。', `MaleText_loc7`='¡El que la vio primero se la queda! Basta de tonterías.' WHERE `ID`=61340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 거야!', `MaleText_loc4`='是我的！', `MaleText_loc5`='我的!', `MaleText_loc7`='¡MÍA!' WHERE `ID`=61341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡사로 데려다 주십시오.', `MaleText_loc4`='带我去青龙寺。', `MaleText_loc5`='帶我去玉蛟寺。', `MaleText_loc7`='Llévame al Templo del Dragón de Jade.', `FemaleText_loc1`='옥룡사로 데려다 주세요.', `FemaleText_loc4`='带我去青龙寺。', `FemaleText_loc5`='帶我去玉蛟寺。', `FemaleText_loc7`='Llévame al Templo del Dragón de Jade.' WHERE `ID`=61342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부님의 불꽃이 필요합니다.', `MaleText_loc4`='我需要火焰，师父。', `MaleText_loc5`='我需要那火焰，大師。', `MaleText_loc7`='Necesito la llama, maestro.', `FemaleText_loc1`='사부님의 불꽃이 필요합니다.', `FemaleText_loc4`='我需要火焰，师父。', `FemaleText_loc5`='我需要那火焰，大師。', `FemaleText_loc7`='Necesito la llama, maestro.' WHERE `ID`=61343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국수가 맛있습니다! 맛있는 국수 한 그릇 먹고 가세요!', `MaleText_loc4`='热腾腾的面条哦，来一碗香气扑鼻的汤面吧！', `MaleText_loc5`='這裡有好吃的麵條，來一碗好吃的湯麵吧!', `MaleText_loc7`='¡Tallarines! ¡Probad nuestra deliciosa sopa de tallarines!' WHERE `ID`=61344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찐 만두 있어요! 아주 맛깔스러운 고기 만두요! 와서 드셔보세요!', `MaleText_loc4`='小笼包，美味多汁的猪肉小笼包！快来吃啊！', `MaleText_loc5`='蒸包子，美味的蒸豬肉包子!快來吃啊!', `MaleText_loc7`='¡Empanadillas al vapor! ¡Venid a por las deliciosas empanadillas de cerdo al vapor!' WHERE `ID`=61345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끈따끈한 국수 한 그릇 드시고 가세요! 국물이 끝내줘요!', `MaleText_loc4`='热气腾腾的汤面，快来吃一碗热乎乎的汤面啊！', `MaleText_loc5`='熱騰騰的湯麵，來碗熱湯麵吧!', `MaleText_loc7`='¡Sopa de tallarines recién hecha! ¡Vengan por su sopa de tallarines caliente!' WHERE `ID`=61346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있고 신선하고 든든한 식사를 하시려면 여기로 오세요! 타오네 국수를 맛보세요!', `MaleText_loc4`='新鲜可口、健康美味！快来尝尝陶记的汤面吧！', `MaleText_loc5`='美味、新鮮、健康又好吃!來碗陶記的熱湯麵吧!', `MaleText_loc7`='¡Fresca, sana y deliciosa! ¡No os perdáis la sopa de tallarines de Tao!' WHERE `ID`=61347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만리장벽 바깥에 이보다 매운 양념은 없습니다! 맛있게 매콤한 국수!', `MaleText_loc4`='不到长城非好汉，不喝靓汤真遗憾！鲜香美味的酸辣汤啊！', `MaleText_loc5`='來嚐嚐長城內最辣的香料!美味的麻辣湯!', `MaleText_loc7`='¡Probad las especias más picantes de aquí a la gran muralla! ¡A la rica sopa picante!' WHERE `ID`=61348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구수한 두부가 왔습니다! 와서 맛보세요! 판다리아 전체에서 가장 구수한 두부입니다!', `MaleText_loc4`='臭豆腐，快来尝尝臭豆腐啊！我们这儿有全潘达利亚最臭的臭豆腐！', `MaleText_loc5`='臭豆腐，快來吃臭豆腐!我有全潘達利亞最臭的臭豆腐!', `MaleText_loc7`='¡No os perdáis el rico tofu pestilente! ¡No lo hay más apestoso en toda Pandaria!' WHERE `ID`=61349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 한숨을 쉽니다.', `MaleText_loc4`='%s叹了口气。', `MaleText_loc5`='%s嘆了口氣。', `MaleText_loc7`='%s suspira.' WHERE `ID`=61350;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 안녕하세요! 옥룡사에 잘 오셨어요! 편히 쉬다 가세요.', `FemaleText_loc4`='呵呵，$c，欢迎来到青龙寺！请不要拘束。', `FemaleText_loc5`='唉呀，$c，歡迎到東方神廟來!請隨意逛逛。', `FemaleText_loc7`='Hola, $c, ¡$gbienvenido:bienvenida; al Templo Oriental! Ponte $gcómodo:cómoda;.' WHERE `ID`=61351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피곤해 보이시는군요, 여행자님. 이리 오셔서 따끈하게 불을 쬐면서 맛있는 맥주를 드셔 보세요.', `FemaleText_loc4`='你看上去很疲倦，旅行者。过来跟我们一起烤烤火，好好喝上一杯吧。', `FemaleText_loc5`='這位旅人，你看起來很疲倦。來分享我們溫暖的爐火與好吃的燉菜。', `FemaleText_loc7`='Parece que el cansancio te invade, $gviajero:viajera;. Comparte nuestra cerveza al calor de un buen fuego.' WHERE `ID`=61352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서오세요, $r님. 마음껏 둘러보세요.', `FemaleText_loc4`='欢迎，$r。随便转转吧。', `FemaleText_loc5`='歡迎你，$r。請自己四處逛逛吧。', `FemaleText_loc7`='$gBienvenido:Bienvenida;, $r. Echa un vistazo por aquí.' WHERE `ID`=61353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희 여관에 잘 오셨어요, 여행자님. 따뜻한 음식과 포근한 침대가 우리 자랑이랍니다.', `FemaleText_loc4`='欢迎来到我的旅店，旅行者。我们这儿有好酒好菜，还有松软的床。', `FemaleText_loc5`='旅人，歡迎到我的客棧來。我們有熱騰騰的飯菜跟柔軟的床鋪。', `FemaleText_loc7`='Te doy la bienvenida a mi posada, $gviajero:viajera;. Tenemos comida caliente y cómodas camas.' WHERE `ID`=61354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바람에 실려 여기까지 오셨군요! 모험은 잠시 잊고 푹 쉬세요, $c님.', `FemaleText_loc4`='瞧啊，是什么风把你给吹来了！快进来好好休息一下吧，$c。', `FemaleText_loc5`='看看是什麼風把你吹到我家門口!暫且放下你的冒險，休息一下吧，$c。', `FemaleText_loc7`='Mira lo que me han traído los vientos. Tómate un descanso de tus aventuras y reposa, $c.' WHERE `ID`=61355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 겨루어 자네의 기량을 보이게.', `MaleText_loc4`='面对我，发挥出你全部的潜力吧。', `MaleText_loc5`='面對我。讓我看看你全部的潛能。', `MaleText_loc7`='Enfréntate a mí. Muéstrame todo tu potencial.' WHERE `ID`=61356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 네가 올 곳이 아니다.', `MaleText_loc4`='这里不欢迎你。', `MaleText_loc5`='你在這裡並不受歡迎。', `MaleText_loc7`='Tu presencia aquí no es bienvenida.' WHERE `ID`=61357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 신성한 곳이다. 외부인이 함부로 올 곳이 아니다.', `MaleText_loc4`='这里是神圣的地方，不欢迎陌生人。', `MaleText_loc5`='這是一個神聖的地方，不歡迎陌生人。', `MaleText_loc7`='Este es un lugar sagrado. Los forasteros no son bienvenidos.' WHERE `ID`=61358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 대체 뭐냐?', `MaleText_loc4`='你到底是什么“玩意”？', `MaleText_loc5`='你到底有何「意圖」?', `MaleText_loc7`='¿Qué clase de "cosa" eres tú?' WHERE `ID`=61359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저지대 냄새가 풍기는군. 그곳으로 돌아가라. 이 산에 여행자가 평안히 지낼 곳은 없다.', `MaleText_loc4`='你身上有山下人的气味，你应该回到他们那里去。这些山里没有你们旅行者想要找的平静。', `MaleText_loc5`='你聞起來像低地的人。你應該回去那裡。這些山脈對旅行者來說一點都不和平。', `MaleText_loc7`='Hueles a tierras bajas. Deberías regresar a ellas. No hay paz en estas montañas para los viajantes.' WHERE `ID`=61360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 있으면 평안하지 못할 것이다.', `MaleText_loc4`='你在这里不会得到安宁。', `MaleText_loc5`='我不會施予你內心平靜的。', `MaleText_loc7`='Aquí no encontrarás paz.' WHERE `ID`=61361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 꼭 전투 전에 모여드는 까마귀 같구나.', `MaleText_loc4`='你就像大战在即之前盘旋的腐食鸟。', `MaleText_loc5`='你的到來就像戰鬥前在天空盤旋的食腐鳥。', `MaleText_loc7`='Vienes como las aves carroñeras antes de una batalla.' WHERE `ID`=61362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 높은 뜻을 받듭니다. 저지대인과 한담을 나눌 시간도, 저지대인의 도전에 응할 시간도 없습니다.', `MaleText_loc4`='我们奉行服务至上的理念。我可没功夫闲聊，也没时间接受低地人的挑战。', `MaleText_loc5`='我們遵行的道路可是最崇高的服務，我沒有時間可以花在瑣碎的對話或低地人的挑戰之上。', `MaleText_loc7`='Nuestra costumbre es el máximo servicio. No tengo tiempo para conversaciones nimias o desafíos de un habitante de las tierras bajas.' WHERE `ID`=61363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 경험이 많은 분 같군요. 그러나 그것이 본인을 위한 것이었습니까, 타인을 위한 것이었습니까?', `MaleText_loc4`='你看上去似乎身经百战。告诉我，你是为自己而战，还是为别人？', `MaleText_loc5`='你看起來像是個見識過許多戰鬥的人。但是告訴我，你是為了自己，還是為了他人而戰?', `MaleText_loc7`='Tienes aspecto de haber presenciado muchos combates, pero dime... ¿fue por tu propia cuenta o al servicio de otros?' WHERE `ID`=61364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 장벽의 감시자, 어둠의 수호자이며, 음영의 달인입니다. 우리는 판다리아 중심부에 어떤 악이 도사리고 있는지 압니다. 우리는... 음영파입니다.', `MaleText_loc4`='我们是长城的守护者，是黑暗的监督者，是暗影的大师。我们深知潜藏在潘达利亚最深处的邪魔。我们……就是影踪派。', `MaleText_loc5`='我們是長城的守護者，黑暗的看守者，暗影的大師。我們知道潘達利亞潛藏了什麼樣的邪惡。我們...是影潘。', `MaleText_loc7`='Somos los vigilantes del muro, los guardianes de la oscuridad, los maestros de las sombras. Sabemos que el mal acecha en el corazón de Pandaria. Somos... el Shadopan.' WHERE `ID`=61365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 숲에 가 보셨습니까? 네 바람의 계곡에는요? 쿤라이의 저지대에는요?$b$b그곳 사람들은 평화를 누리고 있습니까? 아직도 그 평화를 얻기 위해 어떤 대가를 치러야 하는지, 그들의 평화를 지키기 위해 음영파가 얼마나 피를 흘려야 하는지 모르고 있습니까?$b$b모르는 게 낫겠군요. 무지한 자일수록 평화를 잘 누릴 수 있고, 태평하게 삶을 즐길 수 있으니까요.', `MaleText_loc4`='你去过翡翠林吗？去过四风谷吗？去过昆莱的山脚下吗？$b$b告诉我，那里的人们享受和平的生活吗？他们是否仍然不知道，换取那和平所付出的代价？那是用多少影踪派弟子的鲜血换来的啊！$b$b我想他们还是不知道的好。就让他们浑然不觉地享受和平吧，这样他们才能无忧无虑地过好每一天。', `MaleText_loc5`='你去過翠玉林嗎?四風峽?崑萊的低地?$b$b告訴我，他們還喜歡他們的和平嗎?他們對和平所要付出的代價還是一無所知嗎?影潘還得灑出多少鮮血來維持他們的和平?$b$b我想他們最好還是不要知道。無知的人才能享受和平，如此他們才能無憂無慮過他們的平靜生活。', `MaleText_loc7`='¿Has estado en el Bosque de Jade? ¿En el Valle de los Cuatro Vientos? ¿En las tierras bajas de Kun-Lai?$b$bDime, ¿disfrutan de su paz? ¿Siguen sin saber el precio que cuesta esa paz? ¿Cuánta sangre del Shadopan deberá derramarse para mantener su paz?$b$bSupongo que es mejor que no lo sepan. La paz la disfrutan mejor los ignorantes que pueden vivir la vida sin preocupaciones.' WHERE `ID`=61366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 도마뱀 녀석들. 네놈들이 우리 막강한 야운골을 이길 수 있을 것 같더냐?', `MaleText_loc4`='愚蠢的蜥蜴人，你们以为能击败强大的野牛人？', `MaleText_loc5`='笨蜥蜴，你自以為能打敗強大的揚古?', `MaleText_loc7`='Estúpidos lagartos. ¿Creíais poder derrotar a los poderosos yaungol?' WHERE `ID`=61367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 놈이나 더 있느냐?', `MaleText_loc4`='你们还能有多少人？', `MaleText_loc5`='你們還有多少人?', `MaleText_loc7`='¿Cuántos más de ustedes hay?' WHERE `ID`=61368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록은 닭고기 맛이라던데. 한 번 먹어 볼까나.', `MaleText_loc4`='我听说蜥蜴人的味道像鸡肉，让我们来瞧瞧。', `MaleText_loc5`='我聽說薩烏洛克吃起來像雞肉，我們來看看是不是真的。', `MaleText_loc7`='He oído que los saurok saben a pollo. Vamos a comprobarlo.' WHERE `ID`=61369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 왜 이렇게 먼 북쪽까지 왔느냐? 그리고 왜 우리 땅에 침입했느냐?', `MaleText_loc4`='你们为什么不远万里来北方？为什么要侵犯我们的土地？', `MaleText_loc5`='你為什麼到這麼遠的北方來?你為什麼擅闖我們的土地?', `MaleText_loc7`='¿Por qué habéis venido tan al norte? ¿Y por qué estáis cruzando nuestras tierras?' WHERE `ID`=61370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 셋이다. 너희를 혼꾸멍내 주는 데 필요한 인원보다 두 명이나 더 많지.', `MaleText_loc4`='我们总共有三个人，其实只靠我自己就能吞下你的脑袋。', `MaleText_loc5`='我們有三個人，比起把你的頭啃掉需要的人數還多了兩個。', `MaleText_loc7`='Somos tres... y me sobran dos para comerte la cabeza.' WHERE `ID`=61371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 우릴 잡았을 때 우리는 백호사에 가는 길이었지. 우리 힐리스가 잠깐 졸고 있었던 게 다행인 줄 알아라...', `MaleText_loc4`='你抓住我们的时候，我们正前往白虎寺。算你走运，我们的治疗者在打盹……很显然。', `MaleText_loc5`='當你捉住我們的時候，我們正在前往白虎寺的路上。顯然...對你來說很幸運的是我們的治療者在打瞌睡。', `MaleText_loc7`='Íbamos de camino al Templo del Tigre cuando nos cogisteis. Tenéis suerte de que nuestro sanador estuviera durmiendo... según parece.' WHERE `ID`=61372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 마침 너한테 "먹일" 게 있어! 가까이 와 봐...', `MaleText_loc4`='噢，我有东西给你“尝尝”！靠近点……', `MaleText_loc5`='喔我有東西要給你「嚐嚐」!再靠近一點...', `MaleText_loc7`='¡Oh, tengo algo que quiero que "pruebes"! Acércate un poco más...' WHERE `ID`=61373;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 $r|1을;를; 보게 될 줄은 몰랐네요. 잘 오셨어요.$b$b거래할 물품이 있으세요? 부족한 물품이 많거든요.', `FemaleText_loc4`='我没想到在这里还能看见$r，非常欢迎。$b$b请问，你们有补给进行交易吗？我们这一类的物资比较匮乏。', `FemaleText_loc5`='我沒有預期在此地見到$r。當然非常歡迎你。$b$b拜託，你有補給品可以交易嗎?我們很多東西都快用完了。', `FemaleText_loc7`='No esperaba encontrarme a los de tu raza en estas tierras. Desde luego, son bienvenidos.$b$b¿Tienes provisiones para comerciar? Nos estamos quedando sin varias provisiones.' WHERE `ID`=61374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!', `MaleText_loc4`='入侵者！', `MaleText_loc5`='入侵者!', `MaleText_loc7`='¡Intruso!' WHERE `ID`=61375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에서 벌벌 떨어라!', `MaleText_loc4`='怕了吧！', `MaleText_loc5`='畏懼我吧!', `MaleText_loc7`='¡Témeme!' WHERE `ID`=61376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 네놈의 사신이다!', `MaleText_loc4`='遇到我你就死到临头了！', `MaleText_loc5`='我代表你的死亡!', `MaleText_loc7`='¡Soy tu muerte!' WHERE `ID`=61377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자로군!', `MaleText_loc4`='挑战！', `MaleText_loc5`='一個挑戰!', `MaleText_loc7`='¡Un desafío!' WHERE `ID`=61378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 이제 우리 거다!', `MaleText_loc4`='这块地现在是我们的了！', `MaleText_loc5`='這土地現在是我們的了!', `MaleText_loc7`='¡Ahora esta tierra es nuestra!' WHERE `ID`=61379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 네놈을 모두 지배할 것이다.', `MaleText_loc4`='煞会把你们全占据了。', `MaleText_loc5`='煞會將你們全部帶走。', `MaleText_loc7`='El sha se los llevará a todos.' WHERE `ID`=61380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곱게 죽어라!', `MaleText_loc4`='善终吧！', `MaleText_loc5`='乖乖受死吧!', `MaleText_loc7`='¡Que tengas una buena muerte!' WHERE `ID`=61381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에서 설설 기어라!', `MaleText_loc4`='在我面前颤抖吧！', `MaleText_loc5`='在我面前顫抖吧!', `MaleText_loc7`='¡Tiembla ante mí!' WHERE `ID`=61382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 내 뒤통수를 치려고!', `MaleText_loc4`='你认为自己能占上风吗？', `MaleText_loc5`='你以為能偷襲我?', `MaleText_loc7`='¿Creías que podías sorprenderme?' WHERE `ID`=61383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 두 주먹으로 널 뭉개 주마.', `MaleText_loc4`='我会用双拳痛扁你的。', `MaleText_loc5`='我會用我的雙拳揍扁你。', `MaleText_loc7`='Te machacaré con mis propios puños.' WHERE `ID`=61384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자고 있었는데!', `MaleText_loc4`='我那时在睡觉！', `MaleText_loc5`='我原本在睡覺!', `MaleText_loc7`='¡Estaba durmiendo!' WHERE `ID`=61385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이처럼 이부자리에서 죽진 않겠다.', `MaleText_loc4`='我可不会像个懦夫一样躺在床上等死。', `MaleText_loc5`='我不會像個懦夫一樣死在床上。', `MaleText_loc7`='No pienso morir en la cama como un cobarde.' WHERE `ID`=61386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 태운 재로 담배를 피우겠다.', `MaleText_loc4`='我要将你挫骨扬灰。', `MaleText_loc5`='我會把你的骨灰當菸抽。', `MaleText_loc7`='Me fumaré tus cenizas.' WHERE `ID`=61387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 흉터도 너보다는 나이가 많겠군.', `MaleText_loc4`='我在外作战的时候你还穿着开裆裤呢。', `MaleText_loc5`='我身上的傷痕比你還年長。', `MaleText_loc7`='Tengo llagas más viejas que tú.' WHERE `ID`=61388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건방진 애송이! 날 이길 수 있을 것 같으냐?', `MaleText_loc4`='不知天高地厚的小崽子！你以为你能打败我吗？', `MaleText_loc5`='自傲的小鬼!你以為能打敗我?', `MaleText_loc7`='¡Cachorro presuntuoso! ¿Creías que podías vencerme?' WHERE `ID`=61389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘이 네 제삿날이다.', `MaleText_loc4`='今天就是你的死期。', `MaleText_loc5`='今天就是你的死期。', `MaleText_loc7`='Hoy vas a morir.' WHERE `ID`=61390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리도 너희와 똑같이 이 땅을 차지할 권리가 있다!', `MaleText_loc4`='和你一样，我们也是这块地的主人！', `MaleText_loc5`='我們有權在此地生活，就跟你們一樣。', `MaleText_loc7`='¡Tenemos el mismo derecho a esta tierra que ustedes!' WHERE `ID`=61391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어차피 죽는다면 싸우다 죽겠다!', `MaleText_loc4`='就算我死，也要死在战场上！', `MaleText_loc5`='如果我會死，也會死在戰鬥中!', `MaleText_loc7`='¡Si muero, será en combate!' WHERE `ID`=61392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정화 중', `MaleText_loc4`='净化', `MaleText_loc5`='淨化吧', `MaleText_loc7`='Limpieza', `FemaleText_loc1`='정화 중', `FemaleText_loc4`='净化', `FemaleText_loc5`='淨化吧', `FemaleText_loc7`='Limpieza' WHERE `ID`=61393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 놈들! 너희가 바친 경비병들도 이 미개한 놈들을 궁전에서 쫓아내지 못했다.', `MaleText_loc4`='废物！你们信誓旦旦地表忠心，却连这些低等生物都赶不出我的宫殿。', `MaleText_loc5`='你們這些沒用的東西!就連你們獻上的守衛，都擋不住這些低等的生物。', `MaleText_loc7`='¡Inútiles! ¡Todos! Ni los guardias que me ofrecen como tributo pueden impedir que entren gusanos en mi palacio.' WHERE `ID`=61394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만회, 아니, 증명해라. 침입자들을 처치해라. 놈들의 머리를 바치는 부족은 내 총애를 얻을 것이다!', `MaleText_loc4`='将功补过，肃清这些入侵者。哪个部族能够立下首功，就将得到我的青睐！', `MaleText_loc5`='重新...不，證明你們的價值吧。解決這些入侵者。把他們的頭顱帶來的部族將會獲得我的恩典!', `MaleText_loc7`='Redímanse y demuestren su valía. Encárguense de los intrusos. ¡El clan que me traiga sus cabezas se ganará mi favor!' WHERE `ID`=61395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 생명의 웅덩이를 정화했습니다!', `MaleText_loc4`='$n净化了生命之池！', `MaleText_loc5`='$n淨化了生命之池!', `MaleText_loc7`='¡$n ha purificado la Poza de vida!', `FemaleText_loc1`='$n|1이;가; 생명의 웅덩이를 정화했습니다!', `FemaleText_loc4`='$n净化了生命之池！', `FemaleText_loc5`='$n淨化了生命之池!', `FemaleText_loc7`='¡$n ha purificado la Poza de vida!' WHERE `ID`=61396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌? 무슨 일로 스톰윈드에 왔느냐?', `MaleText_loc4`='熊猫人？你来暴风城干什么？', `MaleText_loc5`='熊貓人?你到暴風城來有什麼事?', `MaleText_loc7`='¿Pandaren? ¿Qué te trae a Ventormenta?' WHERE `ID`=61397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 폐하 말인가? 바리안 린 국왕 폐하는 스톰윈드 왕궁 안에 계시다.', `MaleText_loc4`='皇帝？你可以去暴风要塞见瓦里安“国王”。', `MaleText_loc5`='皇帝?你可以在暴風要塞裡找到瓦里安國王。', `MaleText_loc7`='¿Emperador? Encontrarás al REY Varian dentro del Castillo de Ventormenta.' WHERE `ID`=61398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<%s|1이;가; 조조의 기둥을 바라봅니다.>', `MaleText_loc4`='<%s盯着乔乔的柱子看。>', `MaleText_loc5`='<%s看著喬喬的柱子。>', `MaleText_loc7`='<%s mira el pilar de Jojo.>' WHERE `ID`=61399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드로 입성하면 행실에 조심하라, 판다렌. 이제 넌 얼라이언스의 영토에 들어왔으니...', `MaleText_loc4`='进了暴风城可得注意你的言行，熊猫人。你现在站在联盟的领土上。', `MaleText_loc5`='在暴風城裡頭要注意你們的行為，熊貓人。你們現在在聯盟的領土上。', `MaleText_loc7`='Compórtense como es debido en Ventormenta, pandaren. Ahora están en territorio de la Alianza.' WHERE `ID`=61400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 저것 봐! 놀이다!', `MaleText_loc4`='嘿，看！豺狼人！', `MaleText_loc5`='嘿，看哪!豺狼人!', `MaleText_loc7`='¡Mira! ¡Gnolls!' WHERE `ID`=61401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바보, 눈이 삐었구나. 저게 어디가 놀이야?', `FemaleText_loc4`='那可不是豺狼人，笨蛋。睁大你的眼睛瞧瞧。', `FemaleText_loc5`='那些不是豺狼人，傻蛋。用用你的眼睛。', `FemaleText_loc7`='No son gnolls, idiota. Abre los ojos.' WHERE `ID`=61402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저건 펄볼그라고 하는 거야.', `FemaleText_loc4`='那是熊怪。', `FemaleText_loc5`='那些是熊怪。', `FemaleText_loc7`='Son FÚRBOLGS.' WHERE `ID`=61403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선생님... 보세요!', `FemaleText_loc4`='老师……你看！', `FemaleText_loc5`='老師...你看!', `FemaleText_loc7`='Profe... ¡Mira!' WHERE `ID`=61404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 저들은 판다렌이라고 한단다.', `MaleText_loc4`='噢，那是熊猫人，莫妮。', `MaleText_loc5`='是的，那些是熊貓人，莫尼。', `MaleText_loc7`='Sí, son pandaren, Moni.' WHERE `ID`=61405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌이라고요? 여기, 스톰윈드에?', `FemaleText_loc4`='熊猫人？在这里？在暴风城？', `FemaleText_loc5`='熊貓人?在暴風城裡?', `FemaleText_loc7`='¿Pandaren? ¿Aquí, en Ventormenta?' WHERE `ID`=61406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤헤... 판다렌이라. 얼라이언스에 합류하려나 보군.', `MaleText_loc4`='呵呵……熊猫人。你一定是来加入联盟的吧。', `MaleText_loc5`='嘿...熊貓人。你一定是到這兒來加入聯盟的。', `MaleText_loc7`='Eh... Pandaren. Debes haber venido para unirte a la Alianza.' WHERE `ID`=61407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 선택했다. 내겐 좋은 일이지.', `MaleText_loc4`='好身手。这招对我特别管用。', `MaleText_loc5`='很好的行動。這個工作很適合我。', `MaleText_loc7`='Buena jugada. A mí me ha ido bien.' WHERE `ID`=61408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서... 가기나 해.', `MaleText_loc4`='我们……继续前进吧。', `MaleText_loc5`='我們...還是繼續往前走吧。', `MaleText_loc7`='Eh... Sigamos.' WHERE `ID`=61409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드에 오신 것을 환영합니다!', `FemaleText_loc4`='欢迎来到暴风城！', `FemaleText_loc5`='歡迎來到暴風城!', `FemaleText_loc7`='¡$GBienvenido:Bienvenida; a Ventormenta!' WHERE `ID`=61410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌? 요즘 헛 것이 보이나...', `MaleText_loc4`='熊猫人？我肯定是眼花了……', `MaleText_loc5`='熊貓人?我一定是看到幻覺了...', `MaleText_loc7`='¿Pandaren? Eshtoy teniendo vishionesh...' WHERE `ID`=61411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 해, 나아내. 외부인이 다가오잖아.', `MaleText_loc4`='闭嘴，纳娜伊。那些外来人过来了。', `MaleText_loc5`='安靜，納乃。有外人接近了。', `MaleText_loc7`='Cuidado, Naanae. Se acercan forasteros.' WHERE `ID`=61412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='외부인이 맞긴 한데 좋은 일로 오는 거잖아.', `FemaleText_loc4`='外来人，的确如此——不过他们的动机是好的。', `FemaleText_loc5`='沒錯，是外人，但他們的意圖是好的。', `FemaleText_loc7`='Sí, son forasteros. Pero sus intenciones son buenas.' WHERE `ID`=61413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 봐, 루카스. 저들 사이에서 강한 빛이 뿜어져 나오고 있어. 특히 저 판다렌.', `FemaleText_loc4`='仔细看看，卢卡斯。他们身上的圣光很强烈。尤其是那个人。', `FemaleText_loc5`='仔細看，盧卡斯。他們身上的聖光很強。尤其是那一個。', `FemaleText_loc7`='Presta atención, Lucas. La Luz es fuerte en ellos. En particular en $gaquel:aquella;.' WHERE `ID`=61414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 가자.', `FemaleText_loc4`='我们继续前进吧。', `FemaleText_loc5`='我們繼續前進吧。', `FemaleText_loc7`='Continuemos.' WHERE `ID`=61415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 빛...?', `MaleText_loc4`='圣光是什么？', `MaleText_loc5`='什麼是聖光?', `MaleText_loc7`='¿Qué es la Luz?' WHERE `ID`=61416;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스에 합류하러 왔습니다. 국왕 폐하를 만나게 해주십시오.', `FemaleText_loc4`='我们是来加入联盟的。我们要求觐见你们的皇帝。', `FemaleText_loc5`='我們來這裡加入聯盟。我們希望你們的皇帝能接見我們。', `FemaleText_loc7`='Hemos venido a unirnos a la Alianza. Queremos que tu emperador nos conceda una audiencia.' WHERE `ID`=61417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 여길 걸어가는 모습을 보게 될 줄이야.', `MaleText_loc4`='真没想到我能在这里见到你们的族人。', `MaleText_loc5`='想不到我會看到你們這個種族的人經過這裡。', `MaleText_loc7`='Jamás pensé que vería a alguien de tu especie por aquí.', `FemaleText_loc1`='판다렌이 여길 걸어가는 모습을 보게 될 줄이야.', `FemaleText_loc4`='真没想到我能在这里见到你们的族人。', `FemaleText_loc5`='想不到我會看到你們這個種族的人經過這裡。', `FemaleText_loc7`='Jamás pensé que vería a alguien de tu especie por aquí.' WHERE `ID`=61418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 귀찮은 꼬맹이들이 수십 마리 있어. 녀석들이 우릴 괴롭히는 통에 보주를 모을 수가 없다니까. 죽이기는 고사하고 잡을 수도 없는걸.$B$B그나마 무기를 잃어버리지 않은 게 다행이지 뭐야. 누구랑 다르게...', `MaleText_loc4`='这儿有一大群让人讨厌的捣蛋鬼。它们一直骚扰着我们，我们都没法抓住到宝珠。没能把它们抓住千刀万剐。$B$B不过，至少我还没把武器弄丢，不像某些人……', `MaleText_loc5`='這些麻煩的臭小子有好幾十個。有他們在旁邊搗亂，我們沒法撿那些球，也沒辦法把他們抓起來宰了。$B$B至少我沒失去我的武器，不像有些人...', `MaleText_loc7`='Hay docenas de esos pequeños diablillos. No puedo coger los orbes con ellos fastidiándonos. No puedo cogerlos a todos y matarlos.$B$BAl menos no he perdido mi arma, como otra gente...' WHERE `ID`=61419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전... 으... 전 최선을 다하고 있다고요, 알겠어요?! 보주를 손에 들고 있으면, 요마들이 자꾸 쳐서 떨어뜨리거나 제가 한눈 팔 때를 틈타 훔쳐 간다고요!$B$B이 녀석들 정말 싫어요!', `MaleText_loc4`='我……呃……听着，我已经尽力了，好吗？！这些山精不停地敲打我的手，让宝珠从我手上掉下来，或是趁我不注意的时候把它们偷走。$B$B我恨死这些东西了！', `MaleText_loc5`='我...呃...聽著，我盡全力在做了好嗎?!妖精不斷把球從我手中打下來，不然就是趁我不注意時把球偷回去!$B$B我恨死這些東西了!', `MaleText_loc7`='Yo... Eh... Mira, estoy haciéndolo lo mejor que puedo, ¿vale? Los duendes no dejan de tirarme los orbes de las manos... y eso cuando no los roban directamente cuando miro a otro lado.$B$B¡Odio a esas cosas!' WHERE `ID`=61420;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 가죠. 여기서 제대로 활약하려면 동료가 필요할 겁니다.', `FemaleText_loc4`='走，$p，进城吧。如果我们想在这儿有所作为，就得先交些朋友。', `FemaleText_loc5`='我們走吧，$p。若想為這裡出點力，必需要先找到盟友。', `FemaleText_loc7`='En marcha. Si pretendemos hacer algo de provecho aquí, necesitaremos aliados.' WHERE `ID`=61421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것 좀 보세요!', `FemaleText_loc4`='看这个！', `FemaleText_loc5`='看看這個!', `FemaleText_loc7`='¡Mira!' WHERE `ID`=61422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 좋은 소식이네요. 우리가 얼라이언스에 합류하면 심심하진 않을 것 같아요.', `FemaleText_loc4`='嗯，真是个好消息。只要我们加入联盟，就不会没事情做了。', `FemaleText_loc5`='嗯，很好。一旦加入聯盟，我們肯定有做不完的事。', `FemaleText_loc7`='Bueno, eso son buenas noticias. Está claro que una vez nos unamos a la Alianza no nos faltarán cosas por hacer.' WHERE `ID`=61423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 셋, 잠시 걷자꾸나.', `MaleText_loc4`='你们三个，跟我走走。', `MaleText_loc5`='你們三個，跟我一起來。', `MaleText_loc7`='Caminen conmigo, ustedes tres.' WHERE `ID`=61424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 합류하고 싶다고...', `MaleText_loc4`='我知道你们想要加入联盟。', `MaleText_loc5`='我明白你們想加入聯盟。', `MaleText_loc7`='Tengo entendido que quieren unirse a la Alianza.' WHERE `ID`=61425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 항상 동료가 필요했다. 전쟁이 한창인 지금 너희를 거절할 순 없겠지.', `MaleText_loc4`='我们向来欢迎新盟友。我不是四处树敌的傻瓜，尤其是在战争时期。', `MaleText_loc5`='我們一向需要盟友，尤其是在這種戰爭時期，笨蛋才會拒絕你們。', `MaleText_loc7`='Siempre necesitamos aliados. Sería una estupidez rechazarlos, especialmente en tiempos de guerra.' WHERE `ID`=61426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그 전에 너희들이 알아둬야 할 것이 있다.', `MaleText_loc4`='但是，我希望你们要明白一些事情。', `MaleText_loc5`='但是有幾件事情想先讓你們明白。', `MaleText_loc7`='Pero hay ciertas cosas que quiero que entiendan.' WHERE `ID`=61427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 말씀하세요.', `FemaleText_loc4`='明白，请继续。', `FemaleText_loc5`='沒錯。繼續。', `FemaleText_loc7`='Claro. Adelante.' WHERE `ID`=61428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫째, 얼라이언스의 종족들은 서로를 믿고 돕는다.', `MaleText_loc4`='首先：联盟各种族之间必须团结互助。', `MaleText_loc5`='首先:聯盟中的各個種族會互相照應。', `MaleText_loc7`='Primero: las razas de la Alianza cuidan unas de otras.' WHERE `ID`=61429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 일원에게 도움이 필요하면 기꺼이 도와야 한다. 그들이 인간이든, 노움이든, 드레나이든... 혹은 너희처럼 판다렌이든...', `MaleText_loc4`='你们应该向有需要的联盟成员伸出援手，无论他们是人类、侏儒、德莱尼……还是你们熊猫人。', `MaleText_loc5`='我們希望你們能援助需要幫忙的聯盟成員，不論他們是人類、地精、德萊尼...或者像你這樣的熊貓人。', `MaleText_loc7`='Se esperara que ayuden a los miembros necesitados de la Alianza, ya sean humanos, gnomos, draenei... o pandaren como ustedes.' WHERE `ID`=61430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳이 방어의 구멍이에요. 사마귀들이 정찰병 모르게 방벽 너머로 숨어들고 있어요.$B$B포위당하기 전에 놈들을 막아야 해요.', `FemaleText_loc4`='这条小径便是防线的缺口。螳螂妖正偷偷绕过斥候，向我们的防御工事袭来。$B$B我们要在被包围之前截断他们。', `FemaleText_loc5`='防禦的分界線就在這條小徑。螳螂人偷偷摸摸地派遣斥候穿過小徑，在防禦據點四周游走。$B$B我們必須在遭到包圍之前，先行阻止他們。', `FemaleText_loc7`='La brecha en sus defensas está en este camino. Los mántides están esquivando a los exploradores y sorteando la barricada.$B$BTenemos que cortar sus líneas antes de que nos rodeen.' WHERE `ID`=61431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단순하지만 의미 있는 지침이지. 이해하겠느냐?', `MaleText_loc4`='这个原则很简单，但意义重大。你们能理解吗？', `MaleText_loc5`='這是個簡單但意義非凡的準則。你明白嗎?', `MaleText_loc7`='Es una norma sencilla, pero importante. ¿Entienden?' WHERE `ID`=61432;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론입니다.', `FemaleText_loc4`='当然。', `FemaleText_loc5`='當然了。', `FemaleText_loc7`='Desde luego.' WHERE `ID`=61433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 이제 두 번째 지침을 설명하겠다.', `MaleText_loc4`='很好。由此我要引申出第二点。', `MaleText_loc5`='很好。因為這會引出我的第二個重點。', `MaleText_loc7`='Bien. Porque eso me lleva a mi segundo punto.' WHERE `ID`=61434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 판다렌이 너희 셋과 같은 선택을 한 것은 아니다.', `MaleText_loc4`='并不是所有的熊猫人都选择了和你们一样的道路。', `MaleText_loc5`='並不是所有熊貓人都選擇跟你們三個相同的道路。', `MaleText_loc7`='No todos los pandaren han elegido el mismo camino que ustedes.' WHERE `ID`=61435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 이들은 호드에 합류했다.', `MaleText_loc4`='其中一些加入了部落。', `MaleText_loc5`='有些人站在部落那邊。', `MaleText_loc7`='Algunos se han aliado con la Horda.' WHERE `ID`=61436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 호드의 다른 야만족들과 마찬가지로 너희의 새로운 적이다.', `MaleText_loc4`='他们，以及依附部落的其他野蛮部族，都是你们的新敌人。', `MaleText_loc5`='他們跟部落的其他野蠻氏族，就是你的新敵人。', `MaleText_loc7`='Esos pandaren, junto con los demás clanes bárbaros de la Horda, ahora son sus enemigos.' WHERE `ID`=61437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 때 친구라 생각했던 이, 또는 사랑했던 이라고 하더라도 그들은 모두 숙명의 적이다.', `MaleText_loc4`='也许他们曾经是你们的好友，甚至是爱人，现在都将成为不共戴天的仇敌。', `MaleText_loc5`='那些你曾經認為是朋友的人，甚至可能是你曾經愛過的人，現在都是你不共戴天的敵人。', `MaleText_loc7`='Aquellos que antes consideraban amigos, o incluso aquellos que una vez amaron, ahora son sus adversarios.' WHERE `ID`=61438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무나도 미안하지만, 전선이 그어진 이상, 적과 노닥이는 모습은 절대로 용납할 수 없다. 이는 얼라이언스를 위험에 노출시키는 짓이기 때문이다.', `MaleText_loc4`='我很遗憾，但双方的界线已经划清。我绝不容许有任何的通敌行为，因为这可能将整个联盟置于危险之中。', `MaleText_loc5`='我深感遺憾，不過既然開戰了，我不能容忍我們的人跟敵人稱兄道弟，因為這樣會讓聯盟陷入危機。', `MaleText_loc7`='Lo lamento mucho, pero los frentes están definidos. No toleraré la confraternización con el enemigo; podrían exponer la Alianza a graves peligros.' WHERE `ID`=61439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 이해하겠느냐?', `MaleText_loc4`='我说得够清楚了吗？', `MaleText_loc5`='我說得夠清楚嗎?', `MaleText_loc7`='¿Me he expresado con claridad?' WHERE `ID`=61440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네... 물론이지요.', `FemaleText_loc4`='好吧…当然。', `FemaleText_loc5`='是的...當然。', `FemaleText_loc7`='Sí... entiendo.' WHERE `ID`=61441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아. 이제 설명은 끝났다.', `MaleText_loc4`='非常好。我们就快要结束了，$p。', `MaleText_loc5`='很好，這樣就差不多了，$p。', `MaleText_loc7`='Muy bien. Casi hemos terminado.' WHERE `ID`=61442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 효과적이었어요.', `FemaleText_loc4`='致命一击。', `FemaleText_loc5`='致命的效率。', `FemaleText_loc7`='Eficiencia letal.' WHERE `ID`=61443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파에겐 상대가 안 되네요.', `FemaleText_loc4`='它还没准备好面对影踪派。', `FemaleText_loc5`='它還沒準備好面對影潘。', `FemaleText_loc7`='No estaba preparada para el Shadopan.' WHERE `ID`=61444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벽 뒤로 가면 좀 더 나을 거다, 사마귀 놈아.', `FemaleText_loc4`='螳螂妖，天堂有路你不走，地狱无门你来投。', `FemaleText_loc5`='乖乖在封鎖線那裡，你或許還有機會，螳螂人。', `FemaleText_loc7`='Te habría ido mejor en el frente, mántide.' WHERE `ID`=61445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 땅에 들어왔는데도 어떻게 이길 수 있다고 생각하는지...', `FemaleText_loc4`='是什么让他们自以为能够穿越我们的防线……', `FemaleText_loc5`='是什麼樣的絕望，讓他們認為有機會闖過我們的封鎖線...', `FemaleText_loc7`='¿Qué desesperación les impulsa a atravesar nuestras filas...?' WHERE `ID`=61446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 칼날을 무서워하게 될 거다.', `FemaleText_loc4`='螳螂妖不吃点苦头不会知道我们的厉害。', `FemaleText_loc5`='螳螂人，你們會懂得畏懼我們的刀劍的。', `FemaleText_loc7`='Aprenderás a temer nuestras espadas, mántide.' WHERE `ID`=61447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 너희 여왕에게 보내는 답신이다.', `FemaleText_loc4`='螳螂妖，你的女皇会知道你的死讯。', `FemaleText_loc5`='螳螂人，把這個訊息帶回去給你們的女皇。', `FemaleText_loc7`='Llévale ese mensaje a tu Reina, mántide.' WHERE `ID`=61448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공포의 황무지로 돌아가라, 사마귀 놈아.', `FemaleText_loc4`='你真不该离开恐惧废土，螳螂妖。', `FemaleText_loc5`='螳螂人，你們根本不該離開悚然荒野。', `FemaleText_loc7`='No deberías haber salido del Desierto del Pavor, mántide.' WHERE `ID`=61449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 제안하신 대련 말입니다...', `MaleText_loc4`='关于你们提议的比试……', `MaleText_loc5`='關於你提議的比試...', `MaleText_loc7`='Sobre ese combate de entrenamiento que propusiste...', `FemaleText_loc1`='그 제안하신 대련 말입니다...', `FemaleText_loc4`='关于你们提议的比试……', `FemaleText_loc5`='關於你提議的比試...', `FemaleText_loc7`='Sobre ese combate de entrenamiento que propusiste...' WHERE `ID`=61450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다.', `MaleText_loc4`='我想我已经做好准备了。', `MaleText_loc5`='我想我現在準備好了。', `MaleText_loc7`='Creo que ya puedo seguir ese camino.', `FemaleText_loc1`='준비되었어요.', `FemaleText_loc4`='我想我已经做好准备了。', `FemaleText_loc5`='我想我現在準備好了。', `FemaleText_loc7`='Creo que ya puedo seguir ese camino.' WHERE `ID`=61451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아에서 일어나는 모든 화와 악에는, 완벽한 해결책이 존재하지요. 저는 모든 문제가 다 마찬가지라고 생각합니다.', `FemaleText_loc4`='对于潘达利亚的每次不幸和灾难，总有一个完美的解决方案。我觉得这一点适用于所有的问题。', `FemaleText_loc5`='潘達利亞上的每個邪惡或病疫，都有一種完美的免費方式去治癒它。我發現這是個很好的比喻，可以適用於所有問題。', `FemaleText_loc7`='Por cada mal que surge en Pandaria, hay siempre una cura perfectamente complementaria. Creo que es una buena analogía para todos los problemas.' WHERE `ID`=61452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 되면 알려다오.', `MaleText_loc4`='你准备好之后就告诉我一声。', `MaleText_loc5`='當你準備好了就告訴我。', `MaleText_loc7`='Avisadme cuando estéis listos.' WHERE `ID`=61453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼, 판다렌... 너의 실력을 보여봐라!', `MaleText_loc4`='现在，熊猫人……让我看看你的本事吧！', `MaleText_loc5`='來吧，熊貓人...讓我看看你有什麼招數!', `MaleText_loc7`='Ahora, pandaren... ¡demuéstrame de lo que eres capaz!' WHERE `ID`=61454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치지 마라! 한 번 덤벼봐!', `MaleText_loc4`='别这么快退缩！好好打一场！', `MaleText_loc5`='不要留情!咱們痛快的來一場吧!', `MaleText_loc7`='¡No te acobardes! ¡Atácame!' WHERE `ID`=61455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 문제지? 이것보단 잘 싸울 줄 알았는데.', `MaleText_loc4`='怎么了？你肯定不止这点本事吧。', `MaleText_loc5`='怎麼了?你的表現應該要更好才對。', `MaleText_loc7`='¿Qué pasa? Vas a tener que hacerlo mejor.' WHERE `ID`=61456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하세요! 새로 모시게 된 왕이 다치기라도 하면...', `FemaleText_loc4`='当心，$p！别把你的新国王打伤了……', `FemaleText_loc5`='小心，$p!你不會想傷害到你的新國王...', `FemaleText_loc7`='¡Cuidado! No querrás herir a tu nuevo rey...' WHERE `ID`=61457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 판다렌! 날 때려봐!', `MaleText_loc4`='来啊，熊猫人！打我啊！', `MaleText_loc5`='來啊，熊貓人!打我啊!', `MaleText_loc7`='¡Vamos, pandaren! ¡PÉGAME!' WHERE `ID`=61458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 이런 기분, 정말 몇 년만에 느껴보는군! 걱정 말거라, 새 친구여... 이보다 더 큰 상처를 입어도 봤으니. 이런 투지를 가진 자들은 얼마든지 환영이다!', `MaleText_loc4`='哈哈哈哈哈！好多年没有这么痛快过了！别担心，我的新朋友……我还受过比这更重的伤呢。联盟欢迎你这样勇敢的斗士！现在，我们来谈正事吧……', `MaleText_loc5`='哈哈哈哈!我好多好多年沒有這種感覺了!新朋友，$p，別擔心..這對我來說只是小傷。聯盟歡迎像你這樣的戰鬥精神!現在讓我們回到正事上頭...', `MaleText_loc7`='¡Ja, ja, ja! ¡Hacía AÑOS que no me sentía así! No te preocupes... Estuve en peores riñas. Un espíritu luchador como el tuyo será bienvenido en la Alianza. Ahora vayamos al grano...' WHERE `ID`=61459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장벽 너머에 이렇게 많은 지식이 잠들어 있을 줄 누가 알았겠나? 이곳의 풍부한 지식과 자네가 여행을 하며 발견하는 전승을 모으면, 우리의 잊힌 과거에 대한 이야기를 몇 편 짜 맞출 수 있을 것 같네.$b$b어느 이야기를 듣고 싶은가?', `MaleText_loc4`='谁能想到这些墙壁后面隐藏着那么多的知识。从这里的大量知识和你在旅途中的所见所闻之中，我相信我可以拼凑出一些有关我们被遗忘的历史的一些传说。$b$b你想要听哪一段？', `MaleText_loc5`='誰想得到會有這麼多知識隱藏在這裡面。藉由這裡的資料寶庫，和你在旅行中蒐集的傳說，我應該可以編纂出幾個關於我們過去失傳的故事。$b$b你想聽哪一個?', `MaleText_loc7`='Quién se habría imaginado la cantidad de conocimiento oculta tras estos muros. Entre la valiosa información que hay aquí y las historias que has descubierto en tus viajes creo que ya puedo hilar unos pocos cuentos de nuestro pasado olvidado.$b$b¿Cuál te gustaría escuchar?' WHERE `ID`=61460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''사우록과 역경 사이''를 듣고 싶습니다.', `MaleText_loc4`='蜥蜴人与困境。', `MaleText_loc5`='薩烏洛克最難的抉擇', `MaleText_loc7`='Entre el saurok y la pared.', `FemaleText_loc1`='''사우록과 역경 사이''를 듣고 싶어요.', `FemaleText_loc4`='蜥蜴人与困境。', `FemaleText_loc5`='薩烏洛克最難的抉擇', `FemaleText_loc7`='Entre el saurok y la pared.' WHERE `ID`=61461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 이야기의 시초는 오래전 폭군 티엔 황제의 시대로 거슬러 올라간다네.', `MaleText_loc4`='我们的故事发生在很久很久之前，荒暴无道的皇帝阗在位的时候。', `MaleText_loc5`='我們的故事，從久遠之前，可怕的梓安帝的時代就開始了。', `MaleText_loc7`='Nuestra historia comienza hace mucho, en la época del monstruoso emperador Tian.' WHERE `ID`=61462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제에게는 믿을 만한 전령이 필요했지.', `MaleText_loc4`='这位皇帝需要一些可靠的信使和转运人。', `MaleText_loc5`='大帝需要可信賴的使者與送貨員。', `MaleText_loc7`='Al emperador le hacían falta mensajeros y repartidores de confianza.' WHERE `ID`=61463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서, 어쩌다가 발견한 작고 이상한 생물을 골짜기의 힘으로 변형시켰다네.', `MaleText_loc4`='他找来了一个古怪的洞穴小生物，并用锦绣谷的力量改造了它。', `MaleText_loc5`='所以他利用他找到的一隻古怪的小型洞穴生物，並用山谷的力量扭曲牠。', `MaleText_loc7`='Así que atrapó a una diminuta criatura cavernosa y la transformó con los poderes del valle.' WHERE `ID`=61464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제가 그렇게 해서 만든 것이 바로 "그루멀"이었지.', `MaleText_loc4`='他所创造出来的，就是“土地精”。', `MaleText_loc5`='他創造的生物，就是「咕嚕摩」。', `MaleText_loc7`='Lo que creó fueron los "grúmel".' WHERE `ID`=61465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_blackironbomb.blp:20|t |cFFdd7400시크티크 호박날개|r가 단상을 |cFFFF0000|Hspell:120559|h[폭격]|h|r하기 위해 자리를 잡습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_blackironbomb.blp:20|t|cFFdd7400希克提克琥珀飞翼|r就位之后开始|cFFFF0000|Hspell:120559|h[轰击]|h|r平台！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_blackironbomb.blp:20|t|cFFdd7400西克席克琥珀之翼|r移動到定點|cFFFF0000|Hspell:120559|h[轟炸]|h|r平台!', `MaleText_loc7`='|TInterfaceIconsinv_misc_blackironbomb.blp:20|t ¡El |cFFdd7400alacárabe Sik''thik|r se pone en posición para |cFFFF0000|Hspell:120559|h[Bombardear]|h|r la plataforma!' WHERE `ID`=61466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연을 타고 다른 곳으로 가고 싶습니다.', `MaleText_loc4`='我想乘风筝出游。', `MaleText_loc5`='我想搭風箏去某個地方。', `MaleText_loc7`='Me gustaría llevar una cometa a algún sitio.', `FemaleText_loc1`='연을 타고 다른 곳으로 가고 싶어요.', `FemaleText_loc4`='我想乘风筝出游。', `FemaleText_loc5`='我想搭風箏去某個地方。', `FemaleText_loc7`='Me gustaría llevar una cometa a algún sitio.' WHERE `ID`=61467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연을 타고 장벽 위로 가야 합니다!', `MaleText_loc4`='我需要乘风筝到长城上去！', `MaleText_loc5`='我需要一只風箏來飛到長城上頭!', `MaleText_loc7`='¡Necesito una cometa para subir a la muralla!', `FemaleText_loc1`='연을 타고 장벽 위로 가야 해요!', `FemaleText_loc4`='我需要乘风筝到长城上去！', `FemaleText_loc5`='我需要一只風箏來飛到長城上頭!', `FemaleText_loc7`='¡Necesito una cometa para subir a la muralla!' WHERE `ID`=61468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='듣자 하니... 연을 타고 장벽에 가야 한다고?', `MaleText_loc4`='我听别人说……你需要乘风筝到长城上去？', `MaleText_loc5`='我聽其他人說...你需要一只風箏來飛到長城去?', `MaleText_loc7`='Según me han dicho... ¿necesitas una cometa para llegar a la muralla?' WHERE `ID`=61469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘의 본질에 대해 이야기를 해보세. 나는 손에 칼을 들고 있네. 자네에게 물어보지. 누가 힘을 지녔을까?', `MaleText_loc4`='我们来谈谈力量的本质。我的手里握着一把剑。我问你：是谁支配着力量？', `MaleText_loc5`='讓我們談談關於自然的力量。我手中握著一把劍。我問你:誰掌握了力量?', `MaleText_loc7`='Hablemos de la naturaleza del poder. Sostengo una espada y te pregunto: ¿quién tiene el poder?' WHERE `ID`=61470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나겠지. 칼이 있으니까!', `MaleText_loc4`='是我，因为我拿着剑！', `MaleText_loc5`='是我，因為我掌握了這把劍!', `MaleText_loc7`='¡Yo! ¡Porque tengo la espada!' WHERE `ID`=61471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별일도 아닌데 집착하시긴.', `MaleText_loc4`='小事，小事。', `MaleText_loc5`='小問題，都是小問題。', `MaleText_loc7`='Pequeños detalles.' WHERE `ID`=61472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 첸 스톰스타우트. 우리 모두가 영웅이 된답시고 본분을 저버리고 공포의 황무지를 뛰어다니며 세계를 구할 순 없네. 우리 중 어떤 이들은... "예술가"야.', `MaleText_loc4`='“陈·风暴烈酒”，我们当不了英雄。我们不能抛弃自己的职责，去恐惧废土晃悠，拯救世界。我们是……“艺术家”。', `MaleText_loc5`='聽好，「老陳」，並非每個人都能放下責任變成英雄，在悚然荒野除暴安良拯救世界。我們之中有些人只是...「藝術家」。', `MaleText_loc7`='Escucha, "Chen Cerveza de Trueno". No todos podemos ser héroes, huir de nuestras responsabilidades, viajar por el Desierto del Pavor y salvar el mundo. Algunos somos... "artistas".' WHERE `ID`=61473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그래, 그래. 그런 일도 생기지.', `MaleText_loc4`='是啊，是啊。着火了。', `MaleText_loc5`='對對，有時候是這樣。', `MaleText_loc7`='Sí, sí. Suele pasar.' WHERE `ID`=61474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군요. 가오 아저씬 어디 계시죠?', `MaleText_loc4`='原来是这样——那高老伯呢？', `MaleText_loc5`='這樣啊...那高叔叔人呢?', `MaleText_loc7`='Entiendo... ¿y dónde está el tío Gao?' WHERE `ID`=61475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과자 먹을 시간이 어딨어요! 음... 딱 한 개만 먹을까나...?', `MaleText_loc4`='没时间吃甜饼了！好吧，来一块。就一块。嗯。', `MaleText_loc5`='沒時間吃餅乾了。好吧，來一塊。就一塊。', `MaleText_loc7`='¡No hay tiempo para galletas! Bueno, una. Solo una. Mmmm...' WHERE `ID`=61476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 유령 과자잖아. 전혀 배가 안 불러!', `MaleText_loc4`='等等——这些是幽魂饼干。它们根本填不饱肚子！', `MaleText_loc5`='等等，這些是鬼餅乾。這裡面根本沒東西!', `MaleText_loc7`='Espera... ¡son galletas fantasma! ¡No llenan nada!' WHERE `ID`=61477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가오 아저씨, 아저씨가 양조장 관리를 맡았다면서요. 어떻게 된 거죠?', `MaleText_loc4`='高老伯，这酿酒厂是由你看着的。你都干了什么？', `MaleText_loc5`='高叔叔，這個酒坊是你要負責照顧的。你做了什麼?', `MaleText_loc7`='Tío Gao, te dejaron a cargo de esta cervecería. ¿Qué has hecho?' WHERE `ID`=61478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대가는요? 양조장이 쓰레기장이 됐잖아요!', `MaleText_loc4`='那代价呢？酒厂被毁了！都毁了！', `MaleText_loc5`='用什麼代價換的?酒坊已經毀了!糟蹋了!', `MaleText_loc7`='¿A qué precio? ¡Desvalijaron la cervecería! ¡La infestaron!' WHERE `ID`=61479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 젠 왔니? 아줌마가 보고 싶었어?', `FemaleText_loc4`='噢，你好啊，岑。欢迎你来看望风暴烈酒大婶。', `FemaleText_loc5`='噢，你好啊，岑。很高興你來看望風暴烈酒姑媽。', `FemaleText_loc7`='Ah, hola, Zan. Qué bueno que vengas a visitar a tu tía Cerveza de Trueno.' WHERE `ID`=61480;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 젠! 화내는 모습이 아빠랑 완전 붕어빵이네.', `FemaleText_loc4`='噢，岑！你可真像你的父亲。', `FemaleText_loc5`='噢，岑!你讓我想起你父親。', `FemaleText_loc7`='Ah, Zan, me recuerdas tanto a tu padre...' WHERE `ID`=61481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아 바깥 날씨 정말 좋지 않니?', `FemaleText_loc4`='今天外头肯定是个好天气！', `FemaleText_loc5`='今天外面的天氣一定不錯!', `FemaleText_loc7`='¡De verdad que hace un día precioso!' WHERE `ID`=61482;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너 에스미네 순무 크기 봤어?', `FemaleText_loc4`='你注意到艾思木家芜菁的个头了吗？', `FemaleText_loc5`='你有看到伊斯梅的菜頭多大嗎?', `FemaleText_loc7`='¿Has visto el tamaño de las nabas de Esme?' WHERE `ID`=61483;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='버려졌다고? 어쩜 말을 그렇게 하니! 다른 사람들이 벽 너머로 간 동안 가오 아저씨가 관리하고 있는데. 기대되지 않니?', `FemaleText_loc4`='没人管？天哪，才不是呢！高老伯是负责人，其他人都在长城那边呢。很了不起吧？', `FemaleText_loc5`='廢棄?噢，當然沒有!其他人在長城那裡的時候，這裡是高叔叔在負責呢。很棒吧?', `FemaleText_loc7`='¿Abandonada? Oh, cielos, ¡no! El tío Gao está a cargo mientras los demás están al otro lado de la muralla. ¿No es emocionante?' WHERE `ID`=61484;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아 맞다! 너 과자 먹을래?', `FemaleText_loc4`='来吃点小甜饼吧。', `FemaleText_loc5`='來吃點餅乾吧。', `FemaleText_loc7`='¿Quieres una galletita, tesoro?' WHERE `ID`=61485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝없는 군대가 황제의 적들을 처단하리.', `MaleText_loc4`='无尽大军碾碎皇帝之敌。', `MaleText_loc5`='無盡的大軍會碾碎帝王的敵人。', `MaleText_loc7`='El Ejército Infinito aplastará a los enemigos del Emperador.' WHERE `ID`=61486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 분노가 온 언덕에 울려퍼진다.', `MaleText_loc4`='皇帝之怒响彻群山。', `MaleText_loc5`='帝王之怒響徹群山。', `MaleText_loc7`='La ira del Emperador resuena por las colinas.' WHERE `ID`=61487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 힘이 철의 손아귀가 되어 이 땅을 옥죈다.', `MaleText_loc4`='皇帝之力铁血治国。', `MaleText_loc5`='帝王之力以鐵拳掌握大地。', `MaleText_loc7`='La fuerza del Emperador subyuga esta tierra con puño de hierro.' WHERE `ID`=61488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 용기는 영원히 불타오른다.', `MaleText_loc4`='皇帝之勇光照万世。', `MaleText_loc5`='帝王之勇永久不滅。', `MaleText_loc7`='El coraje del Emperador arde eternamente.' WHERE `ID`=61489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 숨결이 잦아든다.', `MaleText_loc4`='皇帝之息渐灭。', `MaleText_loc5`='帝王之息漸息。', `MaleText_loc7`='El aliento del Emperador remite.' WHERE `ID`=61490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 숨결이 커진다.', `MaleText_loc4`='皇帝之息重燃。', `MaleText_loc5`='帝王之息重生。', `MaleText_loc7`='El aliento del Emperador resurge.' WHERE `ID`=61491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 의지가 바라보는 모든 것을 지배한다.', `MaleText_loc4`='皇帝之志统御万物。', `MaleText_loc5`='帝王之志統御萬物。', `MaleText_loc7`='La voluntad del Emperador domina todo lo que ve.' WHERE `ID`=61492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 모두 세 가지 필생의 맹세를 합니다.

이 땅을 지키고, 이 민족을 지키고, 제자를 교육하겠다는 맹세이지요.

음영파가 죽으면, 그 속박에서 해방시켜 주어야 합니다.', `MaleText_loc4`='每个影踪派门人都要立下三条誓言：

守卫这片土地，保护这里的人民，以及教导下一代。

作为一个影踪派的门人，有生之年都不得违此誓言。', `MaleText_loc5`='每一名影潘都許下三個永恆的誓約:

要保衛這片土地、保衛上頭的百姓、並訓練他們的後人。

當影潘死去，他們便從這些束縛中解脫。', `MaleText_loc7`='Todos los Shadopan hacen tres juramentos eternos:

Defender esta tierra, proteger a su gente y entrenar a sus pupilos.

Cuando un Shadopan muerte, debe ser liberado de estas obligaciones.' WHERE `ID`=61493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 힘든 싸움이었네. 친구들을 잃어 슬프기 그지없군.

그나마 그 친구들이 내 전장용 급주 장치를 완성해서 다행이야.

내 스타우트 맥주의 힘이 없었다면 얼마나 많은 이를 잃었을지...', `MaleText_loc4`='啊，那场战斗很惨烈，失去了不少朋友。

尽管如此，我还是很高兴他们帮我建造了战场恢复装置。

要是没有它，没有我烈酒的力量，天知道还会死多少人……', `MaleText_loc5`='啊，這是場艱困的戰鬥。失去朋友真令人悲傷。

不過，我很高興自己讓他們打造了戰場提神裝置。

少了它，和我黑啤酒的勁頭，誰知道還會失去多少...', `MaleText_loc7`='Ah, ha sido una batalla complicada. Es una pena haber perdido amigos.

No obstante, me alegro de haberles ordenado construir el dispositivo de refresco en el campo de batalla.

Sin él y sin la fuerza de mi cerveza negra, quién sabe cuánta gente más habría perecido...' WHERE `ID`=61494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 몸무게의 다섯 배나 되는 짐을 질 수 있다고 하지. 땀도 절대 훌리지 않고, 후각도 매우 뛰어나다네.', `MaleText_loc4`='一个土地精可以负担相当于其本身体重五倍的重物。他们从不流汗，还有着超凡的嗅觉。', `MaleText_loc5`='咕魯魔可以背起自己體重五倍的東西。他們從不流汗。他們有傑出的嗅覺。', `MaleText_loc7`='Un grúmel puede llevar cinco veces su propio peso. Nunca sudan, y cuentan con un sentido del olfato increíble.' WHERE `ID`=61495;
