UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 쫓습니다! 도망가세요!', `MaleText_loc4`='%s在追击你！快跑！', `MaleText_loc5`='%s在追你!快跑!', `MaleText_loc7`='¡%s te está persiguiendo! ¡Huye!' WHERE `ID`=61555;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 누구도 이 장벽을 넘어올 순 없어요.$B$B제가 지키고 있으니까요.', `FemaleText_loc4`='谁也不能越过这道城墙。$B$B这是我的城墙。', `FemaleText_loc5`='沒有任何東西可以越過這道牆。$B$B這可是「我的」長城。', `FemaleText_loc7`='Nada va a atravesar esta muralla.$B$BEs MI muralla.' WHERE `ID`=61556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전한 여행길이 되길!', `MaleText_loc4`='一路平安！', `MaleText_loc5`='一路平安!', `MaleText_loc7`='¡Que tengáis un viaje tranquilo!' WHERE `ID`=61557;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파는 수 세기 동안 이 벽을 지켜왔지만, 자존심을 지킨다는 명목으로 외부인의 도움을 거절하지는 않고 싶어요.', `FemaleText_loc4`='几个世纪以来，影踪派一直守卫着这道城墙，但我也不会因为骄傲自大而拒绝外人的帮助。', `FemaleText_loc5`='許久以來，影潘一直堅守著長城。但我不會因為驕傲而拒絕外來的援助。', `FemaleText_loc7`='El Shadopan ha defendido esta muralla durante siglos, pero no voy a rechazar la ayuda de forasteros solo por orgullo.' WHERE `ID`=61558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 최고입니다!', `MaleText_loc4`='我们至高无上！', `MaleText_loc5`='我們是最偉大的!', `MaleText_loc7`='¡Somos los mejores!' WHERE `ID`=61559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 부족들은 필요없습니다!', `MaleText_loc4`='其他氏族一无是处！', `MaleText_loc5`='其他的部族微不足道!', `MaleText_loc7`='¡Los demás clanes no son nada!' WHERE `ID`=61560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 다른 부족들은 시간 낭비일 뿐입니다. 폐하!', `MaleText_loc4`='您不必把时间花费在其他氏族身上，伟大的王上！', `MaleText_loc5`='其他部族都是浪費您的時間，偉大的王!', `MaleText_loc7`='¡Los demás clanes no son dignos de ti, gran Rey!' WHERE `ID`=61561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족은 진정한 선조들의 방식을 따릅니다. 우리야말로 왕의 호의를 받아 마땅합니다!', `MaleText_loc4`='我们氏族一直谨遵先祖定下的规矩。与其他氏族相比，我们更应该得到王上的青睐！', `MaleText_loc5`='我們的部族一直遵循祖先的宗法。我們才值得獲得王的恩典!', `MaleText_loc7`='Nuestro clan sigue las tradiciones de los ancestros. ¡Merecemos el favor del Rey más que todos los demás!' WHERE `ID`=61562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희 부족의 힘 없이 모구는 정당한 영광을 쟁취할 수 없습니다!!', `MaleText_loc4`='若非我族之力量，魔古无法重夺那份荣耀！', `MaleText_loc5`='沒有我們部族的力量，魔古不可能取回屬於我們的榮耀!', `MaleText_loc7`='¡Los mogu no recuperaremos la gloria sin la fuerza de nuestro clan!' WHERE `ID`=61563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 한심한 놈들이 당신을 섬깁니다, 폐하. 놈들은 우리의 위대한 역사를 우롱합니다!', `MaleText_loc4`='这些可悲的氏族不值一提，陛下。他们玷污了我族伟大的遗产！', `MaleText_loc5`='王啊，別為這些可悲的部族浪費時間。他們玷污了我們的珍貴遺產!', `MaleText_loc7`='Esos patéticos clanes no están a tu altura, mi Rey. ¡Mancillan nuestro gran legado!' WHERE `ID`=61564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희들은 약하다.', `FemaleText_loc4`='你们的实力真弱。', `FemaleText_loc5`='才小貓兩三隻啊!', `FemaleText_loc7`='Sus fuerzas no bastan.' WHERE `ID`=61565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 존재로 인해 떠도는 영혼이 동요합니다!', `MaleText_loc4`='你的出现惊扰了游荡的灵魂！', `MaleText_loc5`='你的存在擾亂了徘徊不散的靈魂!', `MaleText_loc7`='¡Su presencia molesta a un espíritu persistente!', `FemaleText_loc1`='당신의 존재로 인해 떠도는 영혼이 동요합니다!', `FemaleText_loc4`='你的出现惊扰了游荡的灵魂！', `FemaleText_loc5`='你的存在擾亂了徘徊不散的靈魂!', `FemaleText_loc7`='¡Su presencia molesta a un espíritu persistente!' WHERE `ID`=61566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 장수가 모습을 드러냈네! 자, 이제 마무리를 해 보세!', `MaleText_loc4`='野牛人督军露脸了！来吧，让我们做个了结！', `MaleText_loc5`='揚古督軍現身了!來，結束這一切吧!', `MaleText_loc7`='¡El señor de la guerra yaungol asoma la cabeza! ¡Pongamos fin a esto!' WHERE `ID`=61567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 술통들... 모두 내가 담근 최고급 맥주라네. 그래도 영예롭게 불타올랐군!', `MaleText_loc4`='这些桶……有些是我最珍爱的好酒。至少它们曾焕发出荣耀！', `MaleText_loc5`='我的酒桶...有些可是我的頂級佳釀啊。至少是在榮耀的火光中化為灰燼。', `MaleText_loc7`='Todos esos barriles... Mi mejor creación. ¡Al menos tuvieron un final épico!' WHERE `ID`=61568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주는 원군을 보내지 않으려 하네. 우리는 지금 엄청난 대군을 상대하고 있다네. 음영파가 아무리 강인하다고는 해도, 다른 방법을 찾아야만 하네.', `MaleText_loc4`='祝踏岚不会向我们派援军了，我们要在此面对一支庞大的军队。他们或许跟我们影踪派一样强悍，我们得另外想个办法了。', `MaleText_loc5`='塔蘭·祝不願送來援軍。我們得在這裡和一支大軍作戰。儘管我們影潘十分強悍，我們還是得採用不同的對策。', `MaleText_loc7`='Taran Zhu no nos va a enviar refuerzos. Nos estamos enfrentando a un ejército enorme. Por muy Shadopan que seamos, tendremos que adoptar un enfoque diferente.' WHERE `ID`=61570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들 같으니! 너희는 나도, 야운골도 꺾을 수 없다!', `MaleText_loc4`='蠢货！你无法打败我！你无法打败野牛人！', `MaleText_loc5`='一群傻子!你們無法擊敗我!你們無法擊敗揚古!', `MaleText_loc7`='¡Necios! ¡No podéis derrotarme! ¡No podéis derrotar a los yaungol!' WHERE `ID`=61571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐, 린은 어딨죠?', `FemaleText_loc4`='等等——林去哪儿了？', `FemaleText_loc5`='等等，林在哪裡?', `FemaleText_loc7`='Espera... ¿Dónde está Lin?' WHERE `ID`=61572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 하지만 먼저, 이 망할 야운골부터 처리해야 하오. 받아라!', `MaleText_loc4`='……但首先，我要解决掉这些该死的野牛人！看招！', `MaleText_loc5`='...但首先，我得料理這些該死的揚古。你別擋我的路!', `MaleText_loc7`='... pero antes, voy a encargarme de estos malditos yaungol. ¡Estáis acabados!' WHERE `ID`=61573;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 남편 어디 있냐고요!?', `FemaleText_loc4`='我的丈夫在哪？', `FemaleText_loc5`='我的丈夫在哪裡?', `FemaleText_loc7`='¿Dónde está mi marido?' WHERE `ID`=61574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공 다, 이 파리들을 처리해라. 나는 린인가 하는 이놈을 오술 고원으로 데려가겠다.', `MaleText_loc4`='贡达，把这些苍蝇都解决掉，我来把这个——林，是吧？——带回奥苏尔台地。', `MaleText_loc5`='恭大，料理這些蒼蠅，我要把這個...林?是嗎?我要把他帶回歐索台地。', `MaleText_loc7`='Gong Da, ocúpate de estos mosquitos mientras yo me llevo a este... ¿Lin te llamabas?... de vuelta a Osul Mesa.' WHERE `ID`=61575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 주군!', `MaleText_loc4`='遵命，主人！', `MaleText_loc5`='是的，主人!', `MaleText_loc7`='¡Sí, mi señor!' WHERE `ID`=61576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 찾으러 경비대에서 누군가를 보낸 거군요?!$B$B정말 감사합니다.', `MaleText_loc4`='他们派了人来找我？！$B$B谢天谢地……', `MaleText_loc5`='他們派人來找我?!$B$B感謝風啊。', `MaleText_loc7`='¡¿Han enviado a alguien a buscarme?!$B$BGracias a los vientos.' WHERE `ID`=61577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아, 살살 다루십시오!', `MaleText_loc4`='嘿，把那东西拿远点儿！', `MaleText_loc5`='嘿，處理那東西要小心點!', `MaleText_loc7`='¡Oye, cuidado con eso!' WHERE `ID`=61578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오! 저를 태우면 안 됩니다...', `MaleText_loc4`='小心！别烧着我……', `MaleText_loc5`='小心!別把肉排燒了...', `MaleText_loc7`='¡Cuidado! No vayas a quemar las chuletas...' WHERE `ID`=61579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어, 저한테 겨누지 마십시오!', `MaleText_loc4`='哎哟，别拿那东西指着我！', `MaleText_loc5`='嗚啊，別對著這個方向!', `MaleText_loc7`='¡Oye, apunta con eso hacia otro lado!' WHERE `ID`=61580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고! 여기 판다렌 불타 죽네!', `MaleText_loc4`='嘿！我可是一个活的、一点就着的熊猫人！', `MaleText_loc5`='嘿!這裡有活生生的「易燃」熊貓人!', `MaleText_loc7`='¡Oye! ¡Aquí hay pandaren inflamables!' WHERE `ID`=61581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 수 있을 때 달리십시오!', `MaleText_loc4`='快跑吧，否则就迟了！', `MaleText_loc5`='在你還能跑時快跑吧!', `MaleText_loc7`='¡Corred mientras podáis!', `FemaleText_loc1`='도망칠 수 있을 때 달리세요!', `FemaleText_loc4`='快跑吧，否则就迟了！', `FemaleText_loc5`='在你還能跑時快跑吧!', `FemaleText_loc7`='¡Corred mientras podáis!' WHERE `ID`=61582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 너무 강합니다!', `MaleText_loc4`='他们太强大了！', `MaleText_loc5`='他們太強了!', `MaleText_loc7`='¡Son demasiado fuertes!', `FemaleText_loc1`='적이 너무 강해요!', `FemaleText_loc4`='他们太强大了！', `FemaleText_loc5`='他們太強了!', `FemaleText_loc7`='¡Son demasiado fuertes!' WHERE `ID`=61583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고마워. 근데 우린 아직도 사마귀 군대 사이에 발이 묶여 있어.', `MaleText_loc4`='多谢你赶来救援，可是我们仍然被螳螂妖大军包围着。', `MaleText_loc5`='謝謝你的救援。不過，我們現在仍然困在螳螂大軍之中。', `MaleText_loc7`='Gracias por el rescate, pero seguimos atrapados en medio del ejército mántide.' WHERE `ID`=61584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따라와라. 할 이야기가 있다.', `MaleText_loc4`='跟我来。我们得谈谈。', `MaleText_loc5`='跟我來。我們需要談談。', `MaleText_loc7`='Ven conmigo. Tenemos que hablar.' WHERE `ID`=61585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 호드를 선택한 것은 아주 현명한 결정이었다.', `MaleText_loc4`='你们加入我的部落是一个明智的选择。', `MaleText_loc5`='你們加入我的部落是明智的決定。', `MaleText_loc7`='Unirte a mi Horda ha sido una decisión sabia.' WHERE `ID`=61586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 이들은 우리를 야만인이라고... 아제로스의 "싸움꾼"이라고 하지.', `MaleText_loc4`='有人称呼我们是野蛮人…是艾泽拉斯的“劣等种族”。', `MaleText_loc5`='有人說我們是野蠻人...艾澤拉斯的「低等種族」。', `MaleText_loc7`='Hay quienes nos llama bárbaros... las "razas salvajes" de Azeroth.' WHERE `ID`=61587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 무지하며, 현실을 모른다. 네 주위를 둘러봐라, 판다렌.', `MaleText_loc4`='他们愚昧无知，对事实视而不见。看看周围吧，熊猫人。', `MaleText_loc5`='他們只是無知又盲從。看看四周，熊貓人。', `MaleText_loc7`='Son ignorantes; no ven la realidad. Mira a tu alrededor, pandaren.' WHERE `ID`=61588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 오크보다 든든한 아군은 없다.', `MaleText_loc4`='你会发现，兽人是最好的战友。', `MaleText_loc5`='你找不到比獸人更好的戰友。', `MaleText_loc7`='No encontrarás mejor compañero de batalla que un orco.' WHERE `ID`=61589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌은 여러모로 유용한 자들이지. 봐라, 이자는 주술사이다.', `MaleText_loc4`='牛头人都多才多艺。看——这位就是一名萨满。', `MaleText_loc5`='牛頭人貢獻良多。看，這位是薩滿。', `MaleText_loc7`='Los tauren han encontrado formas de ayudar. Mira: este es un chamán.' WHERE `ID`=61590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저길 봐. 헤쳐나가기엔 너무 수가 많아.', `MaleText_loc4`='看看外面。敌人太多了，我们对付不过来。', `MaleText_loc5`='看看底下。我們還有很多敵人要對付。', `MaleText_loc7`='Miren. Son demasiados para un ataque frontal.' WHERE `ID`=61591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프도 검을 다룰 줄은 알지.', `MaleText_loc4`='连血精灵都能挥剑战斗。', `MaleText_loc5`='連血精靈都能揮劍戰鬥。', `MaleText_loc7`='Hasta un elfo de sangre empuña una espada.' WHERE `ID`=61592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠는가? 호드의 모두가 자신의 몫은 해내야 한다는 것이다. 너와 네 친구들도 예외는 아니지.', `MaleText_loc4`='看见吗？在我的部落里，每个人都有用武之地。你和你的朋友们也不例外。', `MaleText_loc5`='看到了嗎?在我的部落裡每一個人都做出貢獻，你和你的朋友們也不例外。', `MaleText_loc7`='¿Lo ves? En mi Horda, todos nos ganamos el sustento. Tus amigos y tú no serán la excepción.' WHERE `ID`=61593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 이해하겠나, 판다렌?', `MaleText_loc4`='你们明白我的话吗，熊猫人？', `MaleText_loc5`='你明白我的意思嗎，熊貓人?', `MaleText_loc7`='¿Entiendes lo que te digo, pandaren?' WHERE `ID`=61594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 대족장님.', `MaleText_loc4`='当然，酋长。', `MaleText_loc5`='是的，大酋長。', `MaleText_loc7`='Sí, Jefe de Guerra.' WHERE `ID`=61595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 좋다.', `MaleText_loc4`='唔。很好。', `MaleText_loc5`='嗯。很好。', `MaleText_loc7`='Mm. Bien.' WHERE `ID`=61596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실, 난 그 섬을 탈출한 판다렌이 너희뿐만이 아니라는 걸 알고 있다.', `MaleText_loc4`='我们继续。我知道，从那岛上逃出来的熊猫人不止你们几个。', `MaleText_loc5`='繼續吧。我知道你不是唯一從那座島上逃出來的熊貓人。', `MaleText_loc7`='Pasemos a otra cosa. Sé que no son los únicos pandaren que han escapado de esa isla.' WHERE `ID`=61597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 놈들은 얼라이언스에 합류했지.', `MaleText_loc4`='你们的一些族人选择加入了联盟。', `MaleText_loc5`='你們一些族人選擇了加入聯盟。', `MaleText_loc7`='Sé que algunos de los suyos se han unido a la Alianza.' WHERE `ID`=61598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 이제 네 적이다.', `MaleText_loc4`='现在，他们就是你们的敌人。', `MaleText_loc5`='現在開始，他們就是你的敵人。', `MaleText_loc7`='Ahora son tus enemigos.' WHERE `ID`=61599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 친구나 가족 중에서도 호드의 숙적, 얼라이언스를 택한 자들이 있을 것이다. 그들 역시 더는 네 친구가 아니다... 네 가족도 아니다.', `MaleText_loc4`='你们的一些朋友和亲人可能也已经选择与部落的敌人为伍。从此他们将不再是朋友……不再是家人。', `MaleText_loc5`='你的一些親朋好友可能選擇與部落的敵人為伍。他們不再是你的朋友...也不是你的親人。', `MaleText_loc7`='Es posible que algunos de tus amigos o parientes se hayan aliado con los enemigos de la Horda. Ya no son tus amigos. Ya no son tu familia.' WHERE `ID`=61600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 휘장을 입는 순간, 그들은 죽은 것이다. 전장에서 감정에 이끌려 우물쭈물하는 꼴은 결코 용납되지 않는다. 호드의 배신자는 배신자로서 죽을 것이다!', `MaleText_loc4`='当他们穿上联盟战袍，他们已经死了。我绝不允许任何部落成员私通外敌。部落的叛徒必将以罪人的身份受死！', `MaleText_loc5`='從他們穿上聯盟戰袍的那一刻起，他們就已經死了。我絕不容許任何部落成員私通外敵。部落的叛徒將以叛亂罪受死!', `MaleText_loc7`='Murieron en el momento en que se pusieron el tabardo de la Alianza. No toleraré ningún trato con el enemigo. ¡Quien traicione a la Horda morirá como un traidor!' WHERE `ID`=61601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 알아듣겠나?', `MaleText_loc4`='我说得够清楚了吗？', `MaleText_loc5`='我說得夠清楚了嗎?', `MaleText_loc7`='¿Ha quedado claro?' WHERE `ID`=61602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 알 것 같습니다.', `MaleText_loc4`='是的……我想是的。', `MaleText_loc5`='我...我相信...是的。', `MaleText_loc7`='E... Eso creo. Sí.' WHERE `ID`=61603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다.', `MaleText_loc4`='很好。', `MaleText_loc5`='很好。', `MaleText_loc7`='Bien.' WHERE `ID`=61604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예의 골짜기에서 만나지. 너희에게 줄... 선물이 있다.', `MaleText_loc4`='到荣誉谷来见我。我有一份……礼物送给你。', `MaleText_loc5`='到榮譽谷來見我吧。我有一份...禮物給你。', `MaleText_loc7`='Reúnete conmigo en el Valle del Honor. Tengo un regalo para ti.' WHERE `ID`=61605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹의 투기장에 온 것을 환영한다, 판다렌. 내가 준비를 마칠 때까지 잠시 쉬고 있도록.', `MaleText_loc4`='欢迎来到勇气竞技场，熊猫人。我先去准备，你们随意参观。', `MaleText_loc5`='歡迎來到勇武競技場，熊貓人。在我準備的時候，你們可以放輕鬆點。', `MaleText_loc7`='Te doy la bienvenida a El Círculo del Valor, pandaren. Descansa mientras lo preparo todo.' WHERE `ID`=61606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이제 준비가 된 것 같군. 자, 신참들아... 싸움을 준비해라.', `MaleText_loc4`='哈！看来我们已经准备好了。现在，新来的……准备战斗吧！', `MaleText_loc5`='哈!看起來我們準備好了。現在，新來的...準備戰鬥吧!', `MaleText_loc7`='¡Ja! Parece que ya estamos. Ahora, novatos... prepárense para luchar.' WHERE `ID`=61607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 대체 뭐지?', `MaleText_loc4`='这是干什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué es eso?' WHERE `ID`=61608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 너희에게 주는 선물이다... 선물이자 시험이지.', `MaleText_loc4`='这是我的礼物：一份馈赠，一场试炼。', `MaleText_loc5`='這就是我的禮物。一份禮物，和一場試煉。', `MaleText_loc7`='Este es mi regalo... Un regalo y una prueba.' WHERE `ID`=61609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설의 판다렌과 그들의 이국적인 전투 방식에 대해선 일찍이 들어본 적 있었지. 이제 직접 확인하고 싶다.', `MaleText_loc4`='我听说过传奇的熊猫人英雄以及他们高超的武艺。现在我就想见识见识。', `MaleText_loc5`='我聽說過關於傳奇般的熊貓人英雄和他們精良的武技。現在我想親眼看看。', `MaleText_loc7`='He oído hablar de los legendarios pandaren y de sus exóticos estilos de lucha. Ahora quiero verlos.' WHERE `ID`=61610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 오는 기회가 아니다, 판다렌. 호드의 대족장에게 네 능력을 증명해 봐라!', `MaleText_loc4`='机会难得啊，熊猫人。向部落的酋长证明你的实力吧！', `MaleText_loc5`='這是個難得的機會，熊貓人。向部落的大酋長證明你的實力吧!', `MaleText_loc7`='Tienes una oportunidad única, pandaren. ¡Demuestra tu valía ante el Jefe de Guerra de la Horda!' WHERE `ID`=61611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='록타르 오가르! 승리가 아니면 죽음을!', `MaleText_loc4`='Lok''tar ogar！不胜利，毋宁死！', `MaleText_loc5`='(獸人語)Lok''tar ogar!不勝即亡!', `MaleText_loc7`='¡Lok''tar ogar! ¡Victoria o muerte!' WHERE `ID`=61612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠어. 네가 내 뒤를 봐 주지 않았으면 목숨을 잃었을지도 몰라.', `MaleText_loc4`='打的好。要不是你帮忙，恐怕我很难在这场战斗中活下来。', `MaleText_loc5`='打得漂亮，沒有你幫忙的話，我大概撐不過那場戰鬥。', `MaleText_loc7`='Bien hecho. De no ser por ti, no creo que hubiera sobrevivido a esa batalla.' WHERE `ID`=61613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롬카, 판다렌. 호드 합류를 환영한다.', `MaleText_loc4`='Throm-ka，熊猫人。欢迎加入部落。', `MaleText_loc5`='你好，熊貓人。歡迎加入部落。', `MaleText_loc7`='Throm-ka, pandaren. Bienvenidos a la Horda.' WHERE `ID`=61614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골 타르를 뒤집어써 앞을 볼 수가 없습니다!', `MaleText_loc4`='你全身覆盖着野牛人焦油，而且什么也看不见！', `MaleText_loc5`='你全身沾滿了揚古焦油，什麼都看不見!', `MaleText_loc7`='¡Te han cubierto de alquitrán yaungol y no ves nada!' WHERE `ID`=61615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 무단침입자군!', `MaleText_loc4`='愚蠢的入侵者！', `MaleText_loc5`='愚蠢的入侵者!', `MaleText_loc7`='¡Estúpido intruso!' WHERE `ID`=61617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 깜빡할 사이에 없애주마!', `MaleText_loc4`='我们会让你死个痛快！', `MaleText_loc5`='我們會讓你死得很痛快!', `MaleText_loc7`='¡Te daremos una muerte rápida!' WHERE `ID`=61618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 고기로군!', `MaleText_loc4`='新鲜血肉！', `MaleText_loc5`='新鮮的肉!', `MaleText_loc7`='¡Carne fresca!' WHERE `ID`=61619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개칼날 비늘군주를 위한 살점이구나!', `MaleText_loc4`='你们的血肉献给邪鳞领主！', `MaleText_loc5`='獻給鱗王的血肉!', `MaleText_loc7`='¡Carne para el Señor de escamas!' WHERE `ID`=61620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내장을 끄집어내라!', `MaleText_loc4`='开膛破肚！', `MaleText_loc5`='把它開膛剖腹!', `MaleText_loc7`='¡Destrípalo!' WHERE `ID`=61621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼을 적실 피군!', `MaleText_loc4`='我的刀渴望鲜血！', `MaleText_loc5`='讓我的刀刃沾滿鮮血!', `MaleText_loc7`='¡Sangre para mi hoja!' WHERE `ID`=61622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛좋은 새 생명체군!', `MaleText_loc4`='新鲜美味的家伙！', `MaleText_loc5`='新的美味生物!', `MaleText_loc7`='¡Una nueva y sabrosa criatura!' WHERE `ID`=61623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각내주지!', `MaleText_loc4`='把它撕开！', `MaleText_loc5`='把牠撕裂!', `MaleText_loc7`='¡Abridlo en canal!' WHERE `ID`=61624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 가거라, 아이야. 곧 다시 만나게 될 것이다.', `FemaleText_loc4`='再见，小家伙。我们后会有期。', `FemaleText_loc5`='再見了，小傢伙。我們會再見面的。', `FemaleText_loc7`='Adiós, joven. Te veré muy pronto.' WHERE `ID`=61625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 여길 걸어가는 모습을 보게 될 줄이야.', `MaleText_loc4`='真没想到我能在这里见到你们的族人。', `MaleText_loc5`='想不到我會看到你們這個種族的人經過這裡。', `MaleText_loc7`='Nunca pensé que vería a uno de los de tu especie caminando por aquí.', `FemaleText_loc1`='판다렌이 여길 걸어가는 모습을 보게 될 줄이야.', `FemaleText_loc4`='真没想到我能在这里见到你们的族人。', `FemaleText_loc5`='想不到我會看到你們這個種族的人經過這裡。', `FemaleText_loc7`='Nunca pensé que vería a uno de los de tu especie caminando por aquí.' WHERE `ID`=61626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들어와라. 대족장님이 기다리고 계시다.', `MaleText_loc4`='快去吧。大酋长在等着你们呢。', `MaleText_loc5`='來吧。大酋長在等你們。', `MaleText_loc7`='Vamos, el Jefe de Guerra te está esperando.', `FemaleText_loc1`='들어와라. 대족장님이 기다리고 계시다.', `FemaleText_loc4`='快去吧。大酋长在等着你们呢。', `FemaleText_loc5`='來吧。大酋長在等你們。', `FemaleText_loc7`='Vamos, el Jefe de Guerra te está esperando.' WHERE `ID`=61627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 봐! 지 파이어포우랑 $p|1이잖아;잖아;!', `MaleText_loc4`='看！是季·火掌和$p！', `MaleText_loc5`='看!是紀·火爪與$p!', `MaleText_loc7`='¡Mira! ¡Son Ji Zarpa Ígnea y $p!' WHERE `ID`=61628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에게서 코르가 스트롱메인을 구출한 자들이야!', `MaleText_loc4`='就是他们帮助科尔加·蛮鬃逃出了联盟的魔掌！', `MaleText_loc5`='他們就是幫助闊卡·強鬃從聯盟逃出來的人!', `MaleText_loc7`='¡Ellos ayudaron a Korga Crin de Acero a escapar de la Alianza!' WHERE `ID`=61629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 좀 봐!', `MaleText_loc4`='快看！', `MaleText_loc5`='看看這個!', `MaleText_loc7`='¡Observa esto!' WHERE `ID`=61630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 좋은 소식이군. 우리가 호드에 합류하면 할 일이 없어 심심하진 않을 것 같으니.', `MaleText_loc4`='嗯，真是个好消息。一旦我们加入部落，就不会没事可做了。', `MaleText_loc5`='嗯，非常好。一旦加入部落，我們肯定有做不完的事。', `MaleText_loc7`='Bueno, son buenas noticias. Cuando nos unamos a la Horda, siempre tendremos algo que hacer.' WHERE `ID`=61631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌! 이리 와라.', `MaleText_loc4`='熊猫人！过来。', `MaleText_loc5`='熊貓人!過來。', `MaleText_loc7`='¡Pandaren! Acércate.' WHERE `ID`=61632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 황제 폐하, 저는 지 파이어...', `MaleText_loc4`='尊敬的地狱咆哮陛下，我是季…', `MaleText_loc5`='地獄吼大帝，我是紀火...', `MaleText_loc7`='Emperador Grito Infernal, soy Ji Zarpa...' WHERE `ID`=61633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 대족장 헬스크림이다!', `MaleText_loc4`='叫我地狱咆哮酋长！', `MaleText_loc5`='是地獄吼大酋長!', `MaleText_loc7`='¡JEFE DE GUERRA Grito Infernal!' WHERE `ID`=61634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 일어서라.', `MaleText_loc4`='好了，起来吧。', `MaleText_loc5`='好了，起來吧。', `MaleText_loc7`='Ahora, levántate.' WHERE `ID`=61635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야기 좀 하지, 판다렌.', `MaleText_loc4`='我们得谈谈，熊猫人。', `MaleText_loc5`='我們得談談，熊貓人。', `MaleText_loc7`='Tenemos que hablar, pandaren.' WHERE `ID`=61636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오그리마에 온 걸 환영하네!', `FemaleText_loc4`='欢迎来到奥格瑞玛！', `FemaleText_loc5`='歡迎來到奧格瑪!', `FemaleText_loc7`='Te doy la bienvenida a Orgrimmar.' WHERE `ID`=61637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에 합류하러 왔는가?', `MaleText_loc4`='你们是来投效部落的吗？', `MaleText_loc5`='你是來為部落效力的嗎?', `MaleText_loc7`='¿Has venido a servir a la Horda?', `FemaleText_loc1`='호드에 합류하러 왔는가?', `FemaleText_loc4`='你们是来投效部落的吗？', `FemaleText_loc5`='你是來為部落效力的嗎?', `FemaleText_loc7`='¿Has venido a servir a la Horda?' WHERE `ID`=61638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 이방인. 여긴 빨리 지나가는 게 좋을 걸.', `MaleText_loc4`='你最好快点穿过这个地区，陌生人。', `MaleText_loc5`='最好快點通過這個區域，陌生人。', `MaleText_loc7`='Es mejor moverse rápidamente por esta zona, $gforastero:forastera;.' WHERE `ID`=61639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님은 오그리마의 이 지역에서 오크가 아닌 종족이 돌아다니는 걸 싫어하시거든.', `MaleText_loc4`='酋长可不喜欢兽人以外的家伙在奥格瑞玛的这一地区闲逛。', `MaleText_loc5`='大酋長可不會善待在奧格瑪這個區塊遊蕩的非獸人。', `MaleText_loc7`='Al Jefe de Guerra no le hace mucha gracia que los no orcos merodeen por esta parte de Orgrimmar.' WHERE `ID`=61640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조... 종족별로 지역을 분리시킨 건가요?', `MaleText_loc4`='他……他在城里搞种族隔离？', `MaleText_loc5`='他...他在這個城市實行隔離政策嗎?', `MaleText_loc7`='¿Está... está segregando la ciudad?' WHERE `ID`=61641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직여. 헬스크림 님의 눈이 너희를 지켜보고 있으니.', `MaleText_loc4`='那就继续向前走吧。地狱咆哮之眼注视着你。', `MaleText_loc5`='接下來，繼續向前。地獄吼的雙眼在盯著你。', `MaleText_loc7`='Muévete. Grito Infernal no te pierde de vista.' WHERE `ID`=61642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 지금까지도 상인, 전령, 안내인, 짐꾼으로서 쿤라이 봉우리를 등정하는 원정대를 위해 일하지.', `MaleText_loc4`='直到今天，他们依然在高耸入云的昆莱山上扮演着商人、信使、向导和送货人的角色。', `MaleText_loc5`='今日，對前往崑萊峰頂的遠征隊來說，他們仍然是商人、信差、導遊與搬貨工。', `MaleText_loc7`='Hoy siguen haciendo de comerciantes, mensajeros, guías y porteadores en las expediciones que suben a la cima Kun-Lai.' WHERE `ID`=61643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와.', `MaleText_loc4`='哇。', `MaleText_loc5`='呼啊。', `MaleText_loc7`='¡Hala!' WHERE `ID`=61644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와.', `FemaleText_loc4`='哇。', `FemaleText_loc5`='呼啊。', `FemaleText_loc7`='¡Hala!' WHERE `ID`=61645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝내준다!', `MaleText_loc4`='真酷！', `MaleText_loc5`='酷!', `MaleText_loc7`='¡Impresionante!' WHERE `ID`=61646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 미신을 신봉하는 종족이라네. 자기가 가장 아끼는 부적, 즉 "복덩이"를 따라 이름을 짓지.', `MaleText_loc4`='他们是非常迷信的种族，经常以他们最喜爱的护身符——或者叫“幸运符”为名。', `MaleText_loc5`='他們是非常迷信的民族，經常使用他們最愛的護身符，或所謂的「幸運星」，做為名字。', `MaleText_loc7`='Son un pueblo muy supersticioso, y suelen adoptar el nombre de sus talismanes favoritos, los "grisgrís."' WHERE `ID`=61647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멋지다!', `FemaleText_loc4`='真酷！', `FemaleText_loc5`='酷!', `FemaleText_loc7`='¡Impresionante!' WHERE `ID`=61648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 냄새가 나지 않는 행운은 믿지 않는다네. 그래서 그루멀을 처음 만날 때는 배설물을 한 주머니 들고 가는 게 좋지.', `MaleText_loc4`='土地精质疑一切他们闻不到的运气，所以带上一口袋粪去见陌生的土地精是个不错的选择。', `MaleText_loc5`='咕嚕摩聞不到他們所謂的好運時都會起疑，所以要跟一個新的咕嚕摩見面時，帶上一包肥料是必要的。', `MaleText_loc7`='Los grúmel recelan de cualquier suerte que no puedan oler, así que a la hora de encontrarse con nuevos grúmel es necesario presentar un puñado de estiércol.' WHERE `ID`=61649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 묘한 종족이야.', `MaleText_loc4`='真是个奇怪的种族。', `MaleText_loc5`='的確是個非常奇怪的種族。', `MaleText_loc7`='Es una raza ciertamente rara.' WHERE `ID`=61650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 자즐! 저 멍청하게 생긴 녀석들 가는 것 좀 봐.', `MaleText_loc4`='嘿，萨兹尔！快看那些走过来的傻瓜。', `MaleText_loc5`='嘿，薩所!看看現在走過來的那些飯桶。', `MaleText_loc7`='¡Oye, Zazzle! Mira a esos que vienen por ahí.' WHERE `ID`=61651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 보기엔 그냥 웃기게 생긴 것 같은데?', `FemaleText_loc4`='要我说的话，他们的样子很滑稽。', `FemaleText_loc5`='如果你問我，我會說看起來很好笑。', `FemaleText_loc7`='Se ven raros, la verdad.' WHERE `ID`=61652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 꽤 웃기게 생긴 거 인정.', `MaleText_loc4`='是啊……真的很滑稽。', `MaleText_loc5`='是啊...看起來真好笑。', `MaleText_loc7`='Sí... bien raros.' WHERE `ID`=61653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저그 저그.', `MaleText_loc4`='哼哼。', `MaleText_loc5`='是的，是的。', `MaleText_loc7`='Zug zug.' WHERE `ID`=61654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 생선 좋아한다.', `MaleText_loc4`='我喜欢鱼。', `MaleText_loc5`='我喜歡魚。', `MaleText_loc7`='Yo gusta pescado.' WHERE `ID`=61655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진데? 나도 생선 좋아해!', `MaleText_loc4`='那太好了！我也喜欢鱼！', `MaleText_loc5`='那很棒!我也喜歡魚!', `MaleText_loc7`='¡Estupendo! ¡A mí también me gusta el pescado!' WHERE `ID`=61656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='린은 지금 마음이 착잡할 거예요. 전투에서 절친한 친구인 즈야오를 잃었거든요.

린이 무모한 짓을 하는 건 원치 않아요. 그이가 없으면 저는 어떻게 할지...', `FemaleText_loc4`='林很伤心——智遥是他的好友，但却战死沙场。

我不想林轻率行事。失去了他我该怎么办……', `FemaleText_loc5`='林很生氣。志姚是他的好朋友，卻在戰鬥中陣亡。

我不希望林做出有欠思慮的事。如果失去他，我不知道該怎麼辦...', `FemaleText_loc7`='Lin está triste... Zhiya era su mejor amigo y lo hemos perdido en la batalla.

No quiero que Lin haga ninguna locura. No sé lo que haría si lo perdiera...' WHERE `ID`=61657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즈야오도 죽고, 스야도 죽고, 리우도 죽고...

쑤나는 내게 진정하라지만, 명예를 생각하면 그럴 수가 없소.

타란 주는 왜 우리끼리 길을 지키게 내버려 둔 채 수도원에 숨어 있는지, 왜 우릴 모른 체하는지, 왜 원군을 보내지 않는 건지...

이런 의문으로 마음이 착잡하다오.', `MaleText_loc4`='智遥牺牲了。诗雅牺牲了。刘牺牲了。

孙娜让我平息心中的怒火，但事关荣誉又岂能息事宁人。

我们孤军防守关隘时，祝踏岚却安坐在禅院里吗？为什么要对我们紧锁大门？为什么不派援兵？

这些问题困扰着我。', `MaleText_loc5`='志姚死了，世亞死了，劉也死了。

蘇納建議我冷靜下來，但我的自尊無法忍耐。

塔蘭·祝安穩地躲在僧院裡，讓我們獨自保衛隘口?為什麼把我們關在外面?為什麼不派援軍?

這些問題糾纏著我。', `MaleText_loc7`='Zhiyao ha muerto. Shiya ha muerto. Liu ha muerto.

Suna me aconseja calma, pero el honor me exige otra cosa.

¿Taran Zhu está tan tranquilo en el monasterio mientras nosotros defendemos el paso solos? ¿Por qué no nos deja pasar? ¿Por qué no nos envía refuerzos?

Estas preguntas me atormentan.' WHERE `ID`=61658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 일은 널 시키면 되는데, 내 칼에 왜 피를 묻히나?', `MaleText_loc4`='明明是你在替我干脏活，我为什么要弄脏自己的武器呢？', `MaleText_loc5`='有你去幫我做一些骯髒工作，我何必讓我的刀沾上血呢?', `MaleText_loc7`='¿Por qué tengo que manchar mis espadas de sangre cuando te tengo a ti para que me hagas el trabajo sucio?' WHERE `ID`=61659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요 없는 질문은 하지 마라, 벽을 걷는 자여. 눈앞에 놓인 일에 집중하도록.', `MaleText_loc4`='别问那么多无聊的问题，城墙行者。把注意力集中在当前的任务上。', `MaleText_loc5`='別問沒必要的問題，壁行者。專注於手邊的任務。', `MaleText_loc7`='No hagas preguntas innecesarias, caminamuros. Céntrate en la tarea que tienes entre manos.' WHERE `ID`=61660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와 함께 있는 줄 알았는데?', `MaleText_loc4`='我以为他跟你在一起？', `MaleText_loc5`='我以為他跟你在一起?', `MaleText_loc7`='Creía que estaba contigo.' WHERE `ID`=61661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 괜찮소... 하지만 우리 친구 $p|1이;가; 궁지에 몰린 것 같군. 가서 도움을 청하겠소...', `MaleText_loc4`='我很好……只是我们的朋友$p好像被完全盖住了。我去找人帮忙……', `MaleText_loc5`='我還好...但看來我們這位朋友$p全身都是焦油。我去找人幫忙...', `MaleText_loc7`='Estoy bien... pero parece que $gnuestro amigo:nuestra amiga; $p aquí presente está completamente $gimpregnado:impregnada;. Iré a buscar ayuda...' WHERE `ID`=61662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 쑤나...', `MaleText_loc4`='噢！孙娜……', `MaleText_loc5`='啊呃!蘇納...', `MaleText_loc7`='¡Oh! Suna...' WHERE `ID`=61663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셋!', `MaleText_loc4`='3！', `MaleText_loc5`='三!', `MaleText_loc7`='¡TRES!', `FemaleText_loc1`='셋!', `FemaleText_loc4`='3！', `FemaleText_loc5`='三!', `FemaleText_loc7`='¡TRES!' WHERE `ID`=61664;
