UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전 시작!', `MaleText_loc4`='挑战开始！', `MaleText_loc5`='挑戰開始!', `MaleText_loc7`='¡Comienza el desafío!', `FemaleText_loc1`='도전 시작!', `FemaleText_loc4`='挑战开始！', `FemaleText_loc5`='挑戰開始!', `FemaleText_loc7`='¡Comienza el desafío!' WHERE `ID`=61667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전 완료!', `MaleText_loc4`='挑战结束！', `MaleText_loc5`='挑戰結束!', `MaleText_loc7`='¡Has completado el desafío!', `FemaleText_loc1`='도전 완료!', `FemaleText_loc4`='挑战结束！', `FemaleText_loc5`='挑戰結束!', `FemaleText_loc7`='¡Has completado el desafío!' WHERE `ID`=61668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되었습니다.', `MaleText_loc4`='我想我已经准备好了。', `MaleText_loc5`='我想我準備好要走了。', `MaleText_loc7`='Creo que ha llegado el momento de dar ese paseo.', `FemaleText_loc1`='준비되었어요.', `FemaleText_loc4`='我想我已经准备好了。', `FemaleText_loc5`='我想我準備好要走了。', `FemaleText_loc7`='Creo que ha llegado el momento de dar ese paseo.' WHERE `ID`=61669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<타이 호는 말이 없습니다.>', `MaleText_loc4`='<泰侯沉默不语。>', `MaleText_loc5`='<泰豪完全地沉默。>', `MaleText_loc7`='<Tai Ho guarda silencio.>' WHERE `ID`=61670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배급원의 일에는 끝이 없어요. 음영파의 힘은 위에서 나오지요.$b$b그리고 어느 정도는, 간에서요.', `MaleText_loc4`='供给官的活儿永远干不完。影踪派正向它的胃部进军。$b$b接着，将进入它的肝脏。', `MaleText_loc5`='物資供應者的工作永遠不會結束。影潘需要飽飽的胃才能作戰。$b$b而且，某種程度上，還需要健全的肝。', `MaleText_loc7`='El trabajo de proporcionar suministros nunca termina. El Shadopan vive a través de su estómago.$b$bY hasta cierto punto, de su hígado.' WHERE `ID`=61671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치하십시오. 저는 그림자 속에 숨어서 시체를 뒤지겠습니다.', `MaleText_loc4`='你去把他们弄出来。我会躲在暗影中搜寻他们。', `MaleText_loc5`='你負責把他們殺了。我會躲在暗處並搜查他們的屍體。', `MaleText_loc7`='Tú los eliminas. Yo me esconderé en las sombras y registraré sus cuerpos.' WHERE `ID`=61672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혼자 밖에 있다는 말이군요! 찾아야만 해요!', `FemaleText_loc4`='他独自留在外面了？！我们得去找他！', `FemaleText_loc5`='那麼他是一個人在外面!我們得找到他!', `FemaleText_loc7`='¡Entonces está solo! ¡Tenemos que encontrarlo!' WHERE `ID`=61673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 타란 주에 대한 존경심 때문에 그분이 수도원을 봉쇄한 데 의심을 품지 않았습니다.

그 다음에는, 야운골이 쳐들어오는 바람에 전선에서 싸우느라 바빠서, 왜 수도원이 원군을 보낼 여력이 없는지 이상하게 생각할 겨를이 없었지요.

음영파 대원 셋이 죽고 하나가 사로잡히고 나니, 제 인내심도 바닥이 나는군요. 수도원으로 가서 타란 주를 만나야겠습니다.', `MaleText_loc4`='起初，出于对祝踏岚的服从和尊敬，我没有质疑他关闭禅院的决定。

然后，当野牛人首次来袭，我忙于应战无法离开前线去询问他为什么不派援军。

现在，影踪派有三人牺牲，一人被俘，我已经没有耐心了——没有了。我打算去禅院，向祝踏岚讨个说法。', `MaleText_loc5`='起初，我對塔蘭·祝的服從與尊敬讓我不去質疑他對外關閉僧院的決定。

而揚古開始發動攻擊時，我又專注於眼前的戰鬥，從不懷疑他是否派來援軍。

如今，三名影潘戰死沙場，一名被俘，我的耐性已經消耗殆盡到達極限。我要過去僧院，請求和塔蘭·祝會面。', `MaleText_loc7`='Al principio, mi deferencia y respecto por Taran Zhu me prohibían cuestionar su decisión de cerrar el monasterio a los forasteros.

Luego, cuando los yaungol nos atacaron por primera vez, mi concentración en la batalla me impidió abandonar las líneas del frente para cuestionar su incapacidad para enviar refuerzos.

Ahora, tres Shadopan yacen muertos, uno ha sido capturado, y mi paciencia está más que al límite... se ha agotado. Pienso ir al monasterio y exigir audiencia con Taran Zhu.' WHERE `ID`=61674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다. 타십시오, 친구.', `MaleText_loc4`='我们到了。上来吧，朋友。', `MaleText_loc5`='我們到了。上來吧，朋友。', `MaleText_loc7`='Ya estamos. ¡Sube a bordo!' WHERE `ID`=61675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님께서 아무도 들이지 말라 명하셨다.', `MaleText_loc4`='祝踏岚掌门有令，任何人都不能通过。', `MaleText_loc5`='塔蘭·祝大人有令，禁止任何人通行。', `MaleText_loc7`='Por orden de lord Taran Zhu, nadie puede pasar.' WHERE `ID`=61676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반 베어하트와 함께 왔습니다. 타란 주를 만나게 해 주시오!', `MaleText_loc4`='我和班·熊心一起，想找祝踏岚讨个说法！', `MaleText_loc5`='我和班·熊心一起前來，我們要求和塔蘭·祝會面!', `MaleText_loc7`='¡He venido con Ban Corazón Fiero, y exigimos audiencia con Taran Zhu!', `FemaleText_loc1`='반 베어하트와 함께 왔어요. 타란 주를 만나게 해 주세요!', `FemaleText_loc4`='我和班·熊心一起，想找祝踏岚讨个说法！', `FemaleText_loc5`='我和班·熊心一起前來，我們要求和塔蘭·祝會面!', `FemaleText_loc7`='¡He venido con Ban Corazón Fiero, y solicitamos audiencia con Taran Zhu!' WHERE `ID`=61677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐?! 네 맘대로 만날 수 있는 분이 아니다!', `MaleText_loc4`='说法？！你们想讨说法？！', `MaleText_loc5`='要求?!你們要求?!', `MaleText_loc7`='¡¿Exigen?! ¡¿Ustedes exigen?!' WHERE `ID`=61678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원 안에서 만나지요!', `MaleText_loc4`='我们禅院里见！', `MaleText_loc5`='我們在僧院裡見。', `MaleText_loc7`='¡Nos vemos dentro del Monasterio!' WHERE `ID`=61682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 있는 나무의 어두운 뿌리 아래, 고대의 공포가 깨어납니다...', `MaleText_loc4`='在附近一棵树那黑暗的根须下，一个古老的恐惧苏醒了……', `MaleText_loc5`='一個古老的恐懼，從鄰近樹木底下的黑暗樹根甦醒了...', `MaleText_loc7`='Entre las oscuras raíces del árbol cercano se despierta un horror ancestral...' WHERE `ID`=61684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안합니다, 외지인이여. 공무를 수행하러 오신 게 아니라면 도와드릴 수 없습니다.', `MaleText_loc4`='对不起，局外人。除非你是因公事至此，否则，我可帮不了你什么。', `MaleText_loc5`='我很抱歉，外地人。除非你為公務上的正事前來，否則我恐怕沒法幫助你。', `MaleText_loc7`='Lo siento, $gforastero:forastera;. A menos que hayas venido en viaje oficial, me temo que no puedo ayudarte.' WHERE `ID`=61687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이에 암운이 감돌고 있습니다. 오랫동안 모습을 드러낸 적 없는 존재가 돌아올까 봐, 야운골은 그 전조에 지나지 않을까 봐 두렵습니다.', `MaleText_loc4`='一股邪风在昆莱肆虐。我担心有一股沉寂多年的力量即将归来，而这些野牛人只是前兆而已。', `MaleText_loc5`='崑萊之上吹著不祥的風。某種消聲匿跡多年的陰影恐怕就要回歸，這些揚古只不過是徵兆而已。', `MaleText_loc7`='Un viento de mal agüero recorre Kun-Lai. Temo el regreso de una presencia ausente durante muchos años, y estos yaungol son solo un síntoma de ello.' WHERE `ID`=61688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 뭔가... 변한 느낌입니다. 왜 그런지는 모르겠지만, 곧 알게 되겠지요.', `MaleText_loc4`='感觉……这里好像有什么不太对劲。不知道是什么，但我希望我们能尽快将其找出来。', `MaleText_loc5`='上頭有點...不太對勁。我不知道是什麼，但我們可能很快就會知道了。', `MaleText_loc7`='Hay una sensación... diferente aquí arriba. No sé lo que es, pero espero descubrirlo pronto.' WHERE `ID`=61689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 음영파 대원을 죽여야 하다니 믿을 수 없군요... 세상이 어떻게 되려는지?', `MaleText_loc4`='我不敢相信我们必须消灭掉我们社团的一员……这个世界怎么了？', `MaleText_loc5`='我不敢相信我們得殺死自己的同伴...這世界到底發生什麼事了?', `MaleText_loc7`='No puedo creer que tuviéramos que matar a uno de mi orden... ¿qué le ha pasado al mundo?' WHERE `ID`=61690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 말 그대로 날려 버렸군요. 놈들의... 비명 소리가 여기까지 들렸어요.

비명? 장벽에서 떨어지는 야운골이 내는 소리에 어울리는 말인가?', `FemaleText_loc4`='你真的把他们打飞了。我在这都能听见他们的……哞哞地惨叫。

哞哞叫？那就是你对野牛人跌落城墙时所发出惨叫声的形容吗？', `FemaleText_loc5`='嗯，你真是把他們打得遠遠的。我打從這裡就聽見他們的...唉唉叫。

唉唉叫?這可以用來形容揚古飛過牆的聲音嗎?', `FemaleText_loc7`='Vaya, sí que les has hecho volar. Podía oír su... balido desde aquí.

¿Balido? ¿Así es como llamas al sonido que hace un yaungol cayendo de una muralla?' WHERE `ID`=61691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 폭발 소리가 이 위에서도 들리던걸요.

라오친의 발상이 모두 꽝인 건 아니었군요.', `FemaleText_loc4`='哇噢！我能听到城墙上爆炸的声音。

我想老陈的想法并不都很糟。', `FemaleText_loc5`='哇!我在長城上面就聽見爆炸聲。

看來老秦想的點子並不是全部都很糟糕。', `FemaleText_loc7`='Guau. Oía las explosiones desde lo alto de la muralla.

Supongo que no todas las ideas de Lao-Chen son horribles.' WHERE `ID`=61692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='린을 구할 수 있다면 뭐든지, 내 마지막 숨이라도 내 놓겠어요.', `FemaleText_loc4`='为了救林，我会竭尽全力，直到剩下最后一口气。', `FemaleText_loc5`='就算犧牲一切，用盡我最後一口氣，我也要解救林。', `FemaleText_loc7`='Daría lo que fuera, hasta mi último aliento, por salvar a Lin.' WHERE `ID`=61693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런다고 우리 형제자매가 돌아오지는 않겠지만, 우리가 야운골보다 나은 존재라는 걸 알면 그나마 발 뻗고 잘 수는 있을 거요.', `MaleText_loc4`='这并不能让我们的兄弟姐妹复生，但知道自己胜过野牛人，会让我们晚上睡得更安稳。', `MaleText_loc5`='這並不會讓兄弟姊妹們回來，但知道我們不是像揚古一樣的禽獸，讓人良心安穩得多。', `MaleText_loc7`='No nos va a devolver a nuestros hermanos y hermanas, pero saber que somos mejores que los yaungol nos ayuda a dormir mejor por las noches.' WHERE `ID`=61694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 봐라, $n. 야수들이 소굴에 들끓고 있다!', `MaleText_loc4`='看，$n。那头野兽在它的巢穴里醒过来了！', `MaleText_loc5`='你看，$n。野獸在牠的巢穴裡騷動!', `MaleText_loc7`='Mira, $n. ¡La bestia sale de su guarida!' WHERE `ID`=61695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 공격이라고?!

아무래도 이 야운골 놈들은 우리가 놈들을 탕랑 평원까지, 아니 바다까지 밀어붙이기 전에는 수그러들지 않겠소.', `MaleText_loc4`='又一轮攻击？！

看来除非我们将他们逼退回螳螂高原，这些野牛人是不会善罢甘休的。甚至是逼退到大海里去。', `MaleText_loc5`='另一次攻擊?!

這些揚古不被趕回螳螂荒原是不會學乖的。或許趕進海裡會更好。', `MaleText_loc7`='¡¿Otro ataque?!

Estos yaungol no pararán hasta que les obliguemos a retroceder hasta Tong Long. O mejor aún, hasta el fondo del mar.' WHERE `ID`=61696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 치명적인 연기 안에 서 있습니다!', `MaleText_loc4`='你站在一片致命的云雾中！', `MaleText_loc5`='你正身處在致命氣體中!', `MaleText_loc7`='¡Estás dentro de una nube mortal!' WHERE `ID`=61697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 마음의 평화와 고요를 되찾았소. 이제야 형제자매의 죽음을 묵묵히 애도할 수 있겠군.', `MaleText_loc4`='和平与安宁终于来临。这也许足够让我去追思那些逝去的兄弟姐妹们。', `MaleText_loc5`='一切終於風平浪靜。或許我終於能為逝去的戰友們哀悼了。', `MaleText_loc7`='Por fin un poco de paz y tranquilidad. Quizá la suficiente para poder reflexionar sobre la pérdida de nuestros hermanos y hermanas.' WHERE `ID`=61698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 계획이 실현되는 걸 보면 정말 기분이 좋다네.', `MaleText_loc4`='我不得不说，计划酝酿出来时，我非常开心。', `MaleText_loc5`='我必須說，我最愛計畫順利實現的感覺。', `MaleText_loc7`='Tengo que decirte una cosa... me encanta que los planes salgan bien.' WHERE `ID`=61699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형제자매를 잃고 린을 야운골에게 빼앗긴 데다 내 맥주까지 잃었으니... 이제 길을 떠나야겠네.

이번엔 사마귀 놈들을 혼내 줄까나...', `MaleText_loc4`='经过这一切之后……我们的兄弟姐妹们离我而去，林被野牛人抓走，我的啤酒也不见了，我想是时候继续前进了。

也许我会去找螳螂妖战斗……', `MaleText_loc5`='經過了這麼多事情...我們的戰友陣亡、林被揚古俘虜、我的啤酒也毀了，我想是離開這裡的時候了。

也許我該找螳螂人算帳...', `MaleText_loc7`='Después de todo esto... la pérdida de nuestros hermanos y hermanas, Lin capturado por los yaungol, mi cerveza echada a perder... creo que va siendo hora de avanzar.

Quizá lleve la lucha hasta los mántides...' WHERE `ID`=61700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에 처음 오셨으니, 음영파에 대해 잘 모르시겠군요.', `MaleText_loc4`='作为刚刚抵达这片土地的陌生人，你也许还不熟悉影踪派。', `MaleText_loc5`='做為初到這片土地的陌生人，你或許對影潘並不熟悉。', `MaleText_loc7`='Como no perteneces a estas tierras, seguramente no conocerás el Shadopan.' WHERE `ID`=61702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 임무는 판다리아의 마지막 황제이자 음영파의 창시자이신 샤오하오 님의 시대로부터 계속되고 있습니다.', `MaleText_loc4`='我们的历史悠久，可以追溯到少昊时代，他是影踪派的创始人，也是潘达利亚的末代皇帝。', `MaleText_loc5`='我們的職責淵源已久，最早可以追溯到紹昊的時代，他是我們的創始者，也是潘達利亞最後一個皇帝。', `MaleText_loc7`='Nuestro cometido es muy antiguo; data de la época de Shaohao, nuestro fundador y el último emperador de Pandaria.' WHERE `ID`=61703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅엔 어둠의 기운이 서려 있습니다. 분노, 증오, 공포, 의심...', `MaleText_loc4`='黑暗能量笼罩着这片土地。愤怒、仇恨、恐惧、猜疑……', `MaleText_loc5`='黑暗能量籠罩著這片土地。憤怒、仇恨、恐懼、懷疑...', `MaleText_loc7`='Energías oscuras oprimen esta tierra. La ira, el odio, el miedo, la duda…' WHERE `ID`=61704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 부정적인 감정은 물리적인 형체를 갖출 수 있는데, 이런 어둠의 기운을 "샤"라고 부르지요.', `MaleText_loc4`='这些负面情感可以表现为实体形态。我们把这些黑暗能量称为“煞”。', `MaleText_loc5`='這些負面情緒能以有形的形態出現。我們把這種黑暗能量稱之為「煞」。', `MaleText_loc7`='Esas emociones negativas pueden manifestarse como entes físicos. A esa energía oscura la llamamos "sha".' WHERE `ID`=61705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 신성한 임무는, 샤를 감시하고 억제하는 것, 또 샤가 사람들을 어둠으로 물들이면 무찌르는 것입니다.', `MaleText_loc4`='监视并禁锢煞魔是我们神圣的责任。不管它在哪里玷污人们的心灵，我们都要打败它。', `MaleText_loc5`='監視並監禁煞是我們的神聖職責。只要是它讓我們人民的心陷入黑暗，就打敗它。', `MaleText_loc7`='Nuestro deber sagrado es controlar y encerrar a los sha, derrotarlos allá donde oscurezcan el corazón de nuestro pueblo.' WHERE `ID`=61706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네 병사들이 우리 해안에 상륙한 이후, 샤가 그 어느 때보다 기승을 부리고 있습니다.', `MaleText_loc4`='自从你们的士兵登上这片土地，煞魔就骚动起来，其表现之活跃，实为我生平仅见。', `MaleText_loc5`='就在你們的士兵登陸我們的海岸時，我這輩子從沒看過煞如此的活躍。', `MaleText_loc7`='Nunca en mi vida había visto a los sha tan activos como cuando llegaron sus soldados.' WHERE `ID`=61707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아엔 상비군이 없습니다. 우리 음영파가 처음이자 마지막 방어선이지요.', `MaleText_loc4`='潘达利亚没有常驻军队。我们影踪派，是这儿最早的——也是唯一的，防御阵线。', `MaleText_loc5`='潘達利亞沒有常備軍隊。我們影潘，是潘達利亞上第一個，也是唯一的防衛線。', `MaleText_loc7`='Pandaria no cuenta con un ejército propiamente dicho. Nosotros, el Shadopan, somos la primera y única línea de defensa.' WHERE `ID`=61708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님께서 부친의 뒤를 이어 음영파의 맹주로 계십니다. 그런데 왜 지금 수도원 문을 걸어 잠근 걸까요?', `MaleText_loc4`='祝踏岚子承父业，领导着影踪派。可他却选择关闭我们的禅院大门——这是为什么呢？', `MaleText_loc5`='塔蘭·祝領導影潘，就像他父親在他之前所做的一樣。但他選擇關上我們僧院的大門，為什麼?', `MaleText_loc7`='Taran Zhu dirige el Shadopan, como su padre antes que él. Pero ha decidido cerrar las puertas del monasterio... ¿Por qué?' WHERE `ID`=61709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 알아내야만 합니다. 음영파가 없다면, 어둠이 판다리아를 삼켜버리고 말 겁니다.', `MaleText_loc4`='我们必须查明原因。如果没有影踪派，潘达利亚一定会被黑暗吞噬……', `MaleText_loc5`='我們必須找出原因。沒有影潘，潘達利亞一定會被黑暗吞沒...', `MaleText_loc7`='Debemos averiguarlo. Sin el Shadopan, Pandaria se sumirá en las tinieblas…' WHERE `ID`=61710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님께서 부친의 뒤를 이어 음영파의 맹주로 계십니다. 그런데 왜 지금, 수도원 문을 걸어 잠근 걸까요?', `MaleText_loc4`='祝踏岚子承父业，领导着影踪派。可他却选择关闭我们的禅院大门——这是为什么呢？', `MaleText_loc5`='塔蘭·祝領導影潘，就像他父親在他之前所做的一樣。但他選擇關上我們僧院的大門，為什麼?', `MaleText_loc7`='Taran Zhu dirige el Shadopan, como su padre antes que él. Pero ha decidido cerrar las puertas del monasterio... ¿Por qué?' WHERE `ID`=61711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 알아내야만 합니다. 음영파가 없다면 어둠이 판다리아를 삼켜 버리고 말 겁니다.', `MaleText_loc4`='我们必须查明原因。如果没有影踪派，潘达利亚定会被黑暗吞噬……', `MaleText_loc5`='我們必須找出原因。沒有影潘，潘達利亞一定會被黑暗吞沒...', `MaleText_loc7`='Debemos averiguarlo. Sin el Shadopan, Pandaria se sumirá en las tinieblas…' WHERE `ID`=61712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라오친! 우리가 이겼는데 왜 우십니까?', `MaleText_loc4`='老陈！我们今天干得不错。你哭什么呀？', `MaleText_loc5`='老秦!我們贏得了勝利。你為什麼要哭呢?', `MaleText_loc7`='¡Lao-Chin! Hemos ganado la batalla. ¿Por qué lloras?' WHERE `ID`=61713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 적의 대장과 싸울 때, 도망치는 적을 쫓아간 모양이야.', `MaleText_loc4`='在我们阻截敌人时，他准是去追逃跑的野牛人了。', `MaleText_loc5`='他一定趁我們攔截揚古首領時，跑去追趕那些竄逃的揚古了。', `MaleText_loc7`='Debe haber perseguido a los yaungol mientras interceptábamos a su líder.' WHERE `ID`=61714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참아, 쑤나! 우리끼리 탕랑 평원으로 가면 문제가 더 커질 뿐이야. 수도원에서 원군을 얻는 것이 먼저야.', `MaleText_loc4`='耐心点，孙娜！如果我们贸然进入螳螂高原，那问题就复杂了。我们必须把注意力集中在禅院和援兵上。', `MaleText_loc5`='有點耐心，蘇納!如果我們單獨深入螳螂荒原，只會讓問題變得更複雜。我們必須專注於僧院，並取得援軍。', `MaleText_loc7`='¡Paciencia, Suna! Entrar en Tong Long solos es demasiado arriesgado. Debemos centrarnos en el monasterio y en conseguir refuerzos.' WHERE `ID`=61715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이유는 모르겠으나 수도원 문을 걸어 잠근 타란 주는... 음영파의 필생의 임무를 위태롭게 했습니다.', `MaleText_loc4`='祝踏岚不知出于何种原因关闭了禅院，这已经危及到我们永恒的使命。', `MaleText_loc5`='不論為了什麼，塔蘭·祝關閉僧院的舉動危及到了這永恆的使命。', `MaleText_loc7`='Al cerrar el monasterio, sea por la razón que fuera, Taran Zhu ha puesto en peligro ese cometido eterno.' WHERE `ID`=61716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산꼭대기 요새에 손 놓고 앉아서 판다리아의 몰락을 바라만 볼 수는 없습니다. 그렇기 때문에 당신이 저와 함께 타란 주를 만나야 하는 것이지요.', `MaleText_loc4`='潘达利亚分崩离析时，我们绝不可以安坐在山顶堡垒中袖手旁观。那就是为什么你和我必须跟祝踏岚讨个说法。', `MaleText_loc5`='我們絕不能枯等在山頂的防禦陣地，坐看潘達利亞分崩離析。那就是你我必須會見塔蘭·祝的原因。', `MaleText_loc7`='No podemos quedarnos de brazos cruzados en nuestra fortaleza en lo alto de la montaña mientras Pandaria se cae a pedazos. Por eso tú y yo debemos exigir audiencia con Taran Zhu.' WHERE `ID`=61717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방향만 가르쳐 주십시오. 짐은 제가 지겠습니다.', `MaleText_loc4`='给我指出正确的方向。我来搬。', `MaleText_loc5`='幫我指出正確的方向就好，我會帶著補給物。', `MaleText_loc7`='Solo dime la dirección, y yo llevaré la carga.' WHERE `ID`=61718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 출발해 볼까요!', `MaleText_loc4`='行动起来吧！', `MaleText_loc5`='那我們走吧!', `MaleText_loc7`='¡Entonces, vamos!' WHERE `ID`=61719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞장서십시오. 식량은 제가 지고 가겠습니다.', `MaleText_loc4`='你来带路。我来搬食物。', `MaleText_loc5`='你帶路，我帶食物。', `MaleText_loc7`='Ve delante. Yo llevaré la comida.' WHERE `ID`=61720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원 주변에 식량이 많이 비축되어 있을 겁니다.', `MaleText_loc4`='寺院周围应该有很充足的食物储备。', `MaleText_loc5`='這個寺廟的四周應該儲存許多食物。', `MaleText_loc7`='Debería haber suficiente comida en este templo.' WHERE `ID`=61721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 뭔데 감히 음영파에게 이래라 저래라 하느냐?', `MaleText_loc4`='你们以为自己是谁，居然敢找影踪派讨说法？', `MaleText_loc5`='你有什麼資格敢要求影潘?', `MaleText_loc7`='¿Quiénes son ustedes para exigir del Shadopan?' WHERE `ID`=61722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마무리하십시오! 장벽에서 떨어뜨리십시오!', `MaleText_loc4`='干掉他！把他从长城上踢下去！', `MaleText_loc5`='解決他!把他打扁在牆上!', `MaleText_loc7`='¡Acaba con él! ¡Échalo de la muralla de una patada!' WHERE `ID`=61723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계 상태 변수가 초기화되었습니다.', `MaleText_loc4`='世界状态变量已重置。', `MaleText_loc5`='世界情勢的變數已被重設。', `MaleText_loc7`='Se han reiniciado las variables del estado del mundo.', `FemaleText_loc1`='세계 상태 변수가 초기화되었습니다.', `FemaleText_loc4`='世界状态变量已重置。', `FemaleText_loc5`='世界情勢的變數已被重設。', `FemaleText_loc7`='Se han reiniciado las variables del estado del mundo.' WHERE `ID`=61724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 납골당에서 행패를 부리느냐?', `MaleText_loc4`='是谁，竟敢惊扰这座陵墓？', `MaleText_loc5`='誰膽敢侵擾墓地?', `MaleText_loc7`='¿Quién osa perturbar esta cripta?' WHERE `ID`=61725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 과부하되기 직전입니다!', `MaleText_loc4`='%s马上就要过载了！', `MaleText_loc5`='%s要超載了!', `MaleText_loc7`='¡%s se empieza a sobrecargar!' WHERE `ID`=61726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이것은 그냥 호박석 덩어리가 아닙니다. 안에는 사마귀가 있습니다!>', `MaleText_loc4`='<这可不仅仅是一块琥珀——里面有一只螳螂妖！>', `MaleText_loc5`='<這不只是一大塊琥珀，琥珀裡面有一隻螳螂人!>', `MaleText_loc7`='<Esto es más que un simple trozo de ámbar; ¡dentro hay un mántide!>' WHERE `ID`=61727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0404|Hspell:116784|h[야생의 불꽃]|h|r에 휩싸입니다!', `MaleText_loc4`='你受到了|cFFFF0404|Hspell:116784|h[野性火花]|h|r的影响！', `MaleText_loc5`='你受到了|cFFFF0404|Hspell:116784|h[烈焰星火]|h|r的效果!', `MaleText_loc7`='¡Estás bajo los efectos de |cFFFF0404|Hspell:116784|h[Chispa de fuego salvaje]|h|r!', `FemaleText_loc1`='당신은 |cFFFF4809|Hspell:116784|h[야생의 불꽃]|h|r에 휩싸입니다!', `FemaleText_loc4`='你受到了|cFFFF4809|Hspell:116784|h[野性火花]|h|r的影响！', `FemaleText_loc5`='你受到了|cFFFF4809|Hspell:116784|h[烈焰星火]|h|r的效果!', `FemaleText_loc7`='¡Estás bajo los efectos de |cFFFF4809|Hspell:116784|h[Chispa de fuego salvaje]|h|r!' WHERE `ID`=61728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시가 여제를 배신했다. 이 대가로 네 시체가 궁전 벽에 걸릴 거다.', `MaleText_loc4`='卡拉克西背叛了女皇陛下。你们的尸体会因此被挂在宫殿的墙壁上。', `MaleText_loc5`='卡拉西背叛了她的女王。為此，你的屍體將被串在宮殿的牆上。', `MaleText_loc7`='Los Klaxxi han traicionado a su majestad. Sus cadáveres serán colgados de los muros de palacio por esto.' WHERE `ID`=61729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 동족을 배신한 건... 여제였다...', `MaleText_loc4`='但是……是女皇背叛了……我们的族人……', `MaleText_loc5`='是...女皇背叛了...我們人民...', `MaleText_loc7`='Es... la Emperatriz quien ha traicionado... a nuestro pueblo...' WHERE `ID`=61730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 의지에 감히 의문을 품다니!', `MaleText_loc4`='你居然敢质疑她的意愿！', `MaleText_loc5`='你竟敢質疑她的意志!', `MaleText_loc7`='¡Cómo osas cuestionar Su voluntad!' WHERE `ID`=61731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭐지?! 이제 놈들이 우리를 제압하려고 장벽을 넘어오는 모양이군? 아둔한 것들!', `MaleText_loc4`='这是什么？！现在它们跨过城墙，是来找我们麻烦的？这群笨蛋！', `MaleText_loc5`='在搞什麼?!現在他們還越過長城來對付我們?一群蠢蛋!', `MaleText_loc7`='¡¿Qué es esto?! ¿Ahora saltan la muralla para enfrentarse a nosotros? ¡Serán necios!' WHERE `ID`=61732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이여;여;... 내게 다가오라...', `MaleText_loc4`='$C……靠近我……', `MaleText_loc5`='$C...靠近我...', `MaleText_loc7`='$C... acércate...' WHERE `ID`=61733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시체 더미를 파괴해 미라가 된 시체를 멈추십시오!', `MaleText_loc4`='摧毁尸体堆以阻止僵尸化的躯体！', `MaleText_loc5`='摧毀屍體堆來阻止屍體轉化為殭屍!', `MaleText_loc7`='¡Destruye los montones de cadáveres para detener a los cadáveres zombis!' WHERE `ID`=61734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함부로 불장난을 하다간 화상 입어요.', `MaleText_loc4`='玩火者，必自焚。', `MaleText_loc5`='玩火，你可能會引火自焚。', `MaleText_loc7`='Si juegas con fuego, acabarás quemándote.', `FemaleText_loc1`='함부로 불장난을 하다간 화상 입어요.', `FemaleText_loc4`='玩火者，必自焚。', `FemaleText_loc5`='玩火，你可能會引火自焚。', `FemaleText_loc7`='Si juegas con fuego, acabarás quemándote.' WHERE `ID`=61735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 같이 가 주시겠습니까?', `MaleText_loc4`='你愿意陪我去吗？', `MaleText_loc5`='你會陪我嗎?', `MaleText_loc7`='¿Vienes conmigo?', `FemaleText_loc1`='저와 같이 가 주시겠어요?', `FemaleText_loc4`='你愿意陪我去吗？', `FemaleText_loc5`='你會陪我嗎?', `FemaleText_loc7`='¿Vienes conmigo?' WHERE `ID`=61736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 함께해 주십시오.', `MaleText_loc4`='加入我吧。', `MaleText_loc5`='加入我。', `MaleText_loc7`='Ven conmigo.', `FemaleText_loc1`='저와 함께해 주세요.', `FemaleText_loc4`='加入我吧。', `FemaleText_loc5`='加入我。', `FemaleText_loc7`='Ven conmigo.' WHERE `ID`=61737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파가 되기 위해서는 몸, 마음, 영혼을 다 바쳐야 합니다.', `MaleText_loc4`='要想成为影踪派的一员，$G他:她;就必须全心全意地投入影踪派的事业。', `MaleText_loc5`='要成為一個影潘，必須奉獻出$G他的:她的;身體、心靈與靈魂。', `MaleText_loc7`='Para convertirte en Shadopan, tienes que dedicarte en cuerpo y alma.' WHERE `ID`=61738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 수는 적지만, 힘으로 수를 보완합니다.', `MaleText_loc4`='影踪派虽然人数稀少，但我们能用强大的力量来弥补这一点。', `MaleText_loc5`='影潘人數很少，但我們以實力彌補了這一點。', `MaleText_loc7`='Los Shadopan somos pocos en número, pero lo compensamos con nuestra fuerza.' WHERE `ID`=61739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽에서는 사마귀 무리가 들썩입니다.$B$B북서쪽에서는 모구가 흑마법을 부리고 있지요.$B$B북쪽에서는 야운골이 밀고 들어옵니다.$B$B할 일은 많고 시간은 없지요.', `MaleText_loc4`='西边，螳螂妖蠢蠢欲动。$B$B西北边，魔古族正在阴谋作乱。$B$B北边，野牛人步步紧逼。$B$B我们有太多事情要做了，时间紧迫。', `MaleText_loc5`='西邊，有螳螂人在躁動。$B$B西北邊，有魔古在練習他們的黑暗技藝。$B$B北邊，有揚古向我們進逼。$B$B太多事情要做，而時間太少。', `MaleText_loc7`='Los mántides se agitan por el oeste.$B$BPor el noroeste los mogu practican sus oscuras artes.$B$BPor el norte los yaungol no dejan de presionarnos.$B$BHay demasiado que hacer y no tenemos suficiente tiempo.' WHERE `ID`=61740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 대원은 모두 서로의 이름을 압니다. 함께 수련하고 함께 싸우고 함께 살아남은 사이니까요.$B$B당신 또한 그렇게 말할 수 있게 된다면, 우리의 일원이 된 준비가 된 겁니다.', `MaleText_loc4`='每一个影踪派战士都能叫出彼此的名字。我们一同训练，并肩作战，同生共死。$B$B当你能做到这一点时，或许就做好了加入我们的准备。', `MaleText_loc5`='每個影潘都知道彼此的名字。我們一起受訓，一起作戰，並一起倖存下來。$B$B當你也能說出這樣的話時，那麼或許你已準備好要成為我們的兄弟。', `MaleText_loc7`='Todos los Shadopan se conocen por su nombre. Hemos entrenado, luchado y sobrevivido juntos.$B$BCuando puedas decir lo mismo quizás puedas entrar en nuestra hermandad.' WHERE `ID`=61741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불태울 준비, 다 됐어요!', `MaleText_loc4`='我随时准备点燃这地方！', `MaleText_loc5`='我要燒光這個地方!', `MaleText_loc7`='¡Vamos a prender fuego a este sitio!', `FemaleText_loc1`='불태울 준비, 다 됐어요!', `FemaleText_loc4`='我随时准备点燃这地方！', `FemaleText_loc5`='我要燒光這個地方!', `FemaleText_loc7`='¡Vamos a prender fuego a este sitio!' WHERE `ID`=61742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐아아아아!', `MaleText_loc4`='啊！！', `MaleText_loc5`='喝啊啊啊啊!!', `MaleText_loc7`='¡¡ARGH!!' WHERE `ID`=61743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 도와줘요! 요마예요!', `MaleText_loc4`='啊！救命！林精！', `MaleText_loc5`='啊!幫幫忙!有妖精!', `MaleText_loc7`='¡Ah! ¡Socorro! ¡Duendes!' WHERE `ID`=61744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 떼 줘요! 떼 줘요!', `MaleText_loc4`='帮我弄走它们！帮我弄走它们！', `MaleText_loc5`='把他們趕走!快把他們趕走!', `MaleText_loc7`='¡Quitádmelos de encima! ¡Quitádmelos de encima!' WHERE `ID`=61745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 따가워! 아얏! 아얏!', `MaleText_loc4`='太蜇人了！哎哟！哎哟！', `MaleText_loc5`='好刺!噢!噢!', `MaleText_loc7`='¡Cómo pincha! ¡Ay! ¡Ay!' WHERE `ID`=61746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘요!', `MaleText_loc4`='救命！', `MaleText_loc5`='幫幫我!', `MaleText_loc7`='¡Socorro!' WHERE `ID`=61747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 바늘잎이 얼굴에 박혔어!', `MaleText_loc4`='啊！我脸上全是刺！', `MaleText_loc5`='啊!我臉上有刺!', `MaleText_loc7`='¡Ah! ¡Tengo pinchos en la cara!' WHERE `ID`=61748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아파 죽겠어!', `MaleText_loc4`='疼死我了！', `MaleText_loc5`='喔好痛!', `MaleText_loc7`='¡Ay, qué dolor!' WHERE `ID`=61749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가!', `MaleText_loc4`='快滚开！', `MaleText_loc5`='快滾開!', `MaleText_loc7`='¡Dejadme en paz!' WHERE `ID`=61750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 야크를 되찾고 싶었을 뿐인데...', `MaleText_loc4`='我只不过想要回我的牦牛……', `MaleText_loc5`='我只想要回我的犛牛...', `MaleText_loc7`='Yo solo quería que volvieran mis yaks...' WHERE `ID`=61751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기다려요...', `FemaleText_loc4`='等等……', `FemaleText_loc5`='再等等...', `FemaleText_loc7`='Espera un poco...' WHERE `ID`=61752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금이에요!', `FemaleText_loc4`='上！', `FemaleText_loc5`='就是現在!', `FemaleText_loc7`='¡Ya!' WHERE `ID`=61753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북부 경비대는 어디 있는 건가? 야영지에 오기 전까지 자네 병사들을 한 명도 못 봤네. 나태해졌군, 가오란.', `MaleText_loc4`='北边的哨探在哪里？你的人全都龟缩在营地，居然没人放哨侦查。你开始松懈了，高岚。', `MaleText_loc5`='北方的哨兵在哪?我到達營區之前，完全沒見到你的人。你鬆懈了，高仁。', `MaleText_loc7`='¿Y los centinelas del norte? No vi ni uno de tus hombres antes de llegar al campamento. Se están descuidando, Gao-ran.' WHERE `ID`=61754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경하는 맹주님. 그렇지 않습니다. 오히려 간신히 연명하고 있지요. 전선은 포위되었고, 병사들은 몸을 사리지 않고 싸우고 있습니다. 단 한 명의 병사도 낭비할 수 없습니다.', `MaleText_loc4`='恕我冒犯，祝掌门，我们没有丝毫松懈。我们兵力不足、四面受敌，我的人都已经精疲力竭，再也抽不出一点人手了。', `MaleText_loc5`='容我尊敬地報告，大人，我們並沒有鬆懈。我們已經捉襟見肘。每條戰線都遭到圍攻，我的人都精疲力盡，撥不出任何兵力了。', `MaleText_loc7`='Con el debido respeto, señor, no nos estamos descuidando. Somos pocos. Nos atacan desde todos los frentes, mis hombres están exhaustos y no puedo prescindir de ningún guerrero.' WHERE `ID`=61755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 후퇴하지 않겠네. 다음에 공격해 올 사마귀 떼가 태어나려면 아직도 세월이 많이 남았네. 탕랑 평원을 호락호락 넘겨주진 않을 걸세.', `MaleText_loc4`='不，我们绝不撤军。在螳螂妖繁殖下一代虫群之前，我们还有很多年时间。我可不想把螳螂高原拱手相让。', `MaleText_loc5`='不，我們不會撤退。距離下個螳螂群誕生還有好幾年，我不會眼睜睜看著螳螂荒原平白落入他們手中。', `MaleText_loc7`='No, no nos retiraremos. Los mántides tardarán años en reunir su siguiente enjambre. No les serviré las Estepas de Tong Long en bandeja.' WHERE `ID`=61756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹주님, 이 정도 규모의 사마귀 떼는 90년 만에 처음입니다. 제 병사들은 이 전선을 유지하기 위해 며칠째 잠도 못 자고 있습니다.', `MaleText_loc4`='祝掌门，九十多年来，螳螂妖的数量从未如此泛滥。士兵们夜以继日、不眠不休地战斗，死守这道防线。', `MaleText_loc5`='祝大人，我們已經有90幾年沒看過這麼多成群的螳螂人了。我的人為了守住防線已經好幾天沒睡覺了。', `MaleText_loc7`='Lord Zhu, no hemos visto a tantos mántides desde el enjambre de hace 90 años. Mis hombres llevan días sin dormir intentando defender este frente.' WHERE `ID`=61757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽으로 후퇴하는 건 어떻습니까? 만약 사마귀의 총병력이 쳐들어 온다면 막을 곳은 그곳뿐입니다.', `MaleText_loc4`='或许我们应该撤退到城墙那里？即便是螳螂妖全数出动，我们也绝对能将它们挡住。', `MaleText_loc5`='或許我們該撤回長城?如果螳螂人傾巢而出，我們有自信可以把他們擋在那兒。', `MaleText_loc7`='Quizás deberíamos replegarnos hasta la muralla. Si nos ataca todo el ejército mántide, allí podremos contenerlos.' WHERE `ID`=61758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오의 샤를 사냥할 강력한 판다렌을 찾으러 왔네만, 일단은 이곳 방벽을 강화하는 일부터 돕겠네.', `MaleText_loc4`='我是来找一些强壮的熊猫人猎杀恨之煞的，但是我们会先帮你加固路障。', `MaleText_loc5`='我來尋找強壯的熊貓人以獵捕仇恨之煞，但是會先留在這兒幫你鞏固據點的防禦。', `MaleText_loc7`='Había venido para reclutar pandaren fuertes y dar caza al Sha del odio, pero antes te ayudaremos a fortificar la barricada.' WHERE `ID`=61759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스, 북쪽으로 가서 사마귀 놈들이 측면을 치지 못하게 하게. 수비는 내가 맡겠네.', `MaleText_loc4`='陶矢，去北边看看有没有螳螂妖骚扰我们的侧翼。我去看看防御工事。', `MaleText_loc5`='陶氏，到北邊去確認側翼沒有螳螂人。我要去檢查防禦工事。', `MaleText_loc7`='Taoshi, ve al norte y asegúrate de que no hay mántides en el flanco. Me ocupo de las defensas.' WHERE `ID`=61760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들이 기뻐할 것입니다. 맹주님.', `MaleText_loc4`='将士们很荣幸与您并肩作战，祝掌门。', `MaleText_loc5`='有你加入士兵們一定很高興，祝大人。', `MaleText_loc7`='Los hombres se alegrarán de contar contigo, lord Zhu.' WHERE `ID`=61761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가오란, 내가 최전선에 너무 오랜만에 와보는 것 같군. 자네의 오랜 노고에 감사하네.', `MaleText_loc4`='高岚，我已经很长时间没有视察前线了。感谢你长期以来的努力。', `MaleText_loc5`='高仁，我已經太久沒到前線來了。你長期的努力值得讚賞。', `MaleText_loc7`='Hace demasiado tiempo que no visito el frente, Gao-ran. Agradezco tu prolongado esfuerzo.' WHERE `ID`=61762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 증오의 샤를 쫓아 서쪽으로 계속 가야만 하네.', `MaleText_loc4`='$p，我们现在得继续向西前进，去追踪恨之煞了。', `MaleText_loc5`='$p，我們該跟著仇恨之煞往西走了。', `MaleText_loc7`='Es hora de avanzar hacia el oeste, hacia el Sha del Odio.' WHERE `ID`=61763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 어서 가세.', `MaleText_loc4`='来吧，我们走。', `MaleText_loc5`='來吧，我們走。', `MaleText_loc7`='Vamos. En marcha.' WHERE `ID`=61764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들과 싸우기 전에 최고의 실력을 갖춘 음영파가 더 필요할 걸세. 가다가 야영지에 좀 들러봐야겠군.', `MaleText_loc4`='我们需要更多身经百战的影踪派弟子才能挑战它。我们会在沿途的营地停留。', `MaleText_loc5`='我們需要更多老練的影潘才有能力對抗它，我們得在路上所經過的營地停下來。', `MaleText_loc7`='Nos hacen falta más Shadopan veteranos para enfrentarnos a él. Buscaremos en los campamentos por el camino.' WHERE `ID`=61765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<끈적끈적한 노란색 액체가 킬루크의 턱에서 흘러나옵니다.>', `MaleText_loc4`='<粘稠的、橘黄的液体缓缓地从克尔鲁克的颚骨渗出。>', `MaleText_loc5`='<黏稠的橘色液體從基爾魯克的下顎緩緩滲出。>', `MaleText_loc7`='<Un líquido naranja pegajoso brota de las mandíbulas de Kil''ruk.>' WHERE `ID`=61766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리가 어지럽군... 아직도... 몸이 이상한데.', `MaleText_loc4`='我的头好晕……我还……没有完全恢复。', `MaleText_loc5`='我頭昏眼花的...我...還沒清醒。', `MaleText_loc7`='La cabeza me da vueltas... aún... aún no soy yo mismo.' WHERE `ID`=61767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='즉시 하겠습니다.', `FemaleText_loc4`='遵命，祝掌门。', `FemaleText_loc5`='馬上辦，祝宗主。', `FemaleText_loc7`='Ahora mismo, lord Zhu.' WHERE `ID`=61768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부디 당신이 나아가는 길이 평온하기를 바랍니다, 여행자여.$b$b무슨 일로 여기 오셨나요?', `FemaleText_loc4`='愿道路指引你的方向，旅行者。$b$b是什么风把你吹来了？', `FemaleText_loc5`='路途順利嗎，旅人。$b$b什麼風把你吹來的?', `FemaleText_loc7`='Que la carretera se eleve para ti, $gviajero:viajera;.$b$b¿Qué te trae por aquí?' WHERE `ID`=61769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 할 수 있는 일은 다 했네. 잘 있게, 가오란. 더 많은 병사들을 최대한 빨리 보내 주겠네.', `MaleText_loc4`='我们都已经尽力了。再见，高岚。我会尽快派部队来支援你。', `MaleText_loc5`='我們已在這裡盡了一切努力。再會吧，高仁。我會儘快派更多人過來。', `MaleText_loc7`='Hemos hecho todo lo posible. Adiós, Gao-ran. Enviaré más tropas en cuanto pueda.' WHERE `ID`=61770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 맹주님. 행운을 빌겠습니다.', `MaleText_loc4`='非常感谢，祝掌门。祝你好运。', `MaleText_loc5`='非常感謝，祝大人。祝你狩獵順利。', `MaleText_loc7`='Gracias, lord Zhu. Buena suerte con tu cacería.' WHERE `ID`=61771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴지는군. 증오의 샤가 여기 있었네.', `MaleText_loc4`='是的。恨之煞来过这里。', `MaleText_loc5`='是的，仇恨之煞已經穿過這裡。', `MaleText_loc7`='Sí. El Sha del Odio ha estado aquí.' WHERE `ID`=61772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='느껴지나요...?', `FemaleText_loc4`='你们感觉到了吗……？', `FemaleText_loc5`='你感覺到了嗎...?', `FemaleText_loc7`='¿Sientes eso...?' WHERE `ID`=61773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야영지가 난장판이군요. 무슨 일이죠?', `FemaleText_loc4`='他们的营地陷入了混乱，发生了什么事？', `FemaleText_loc5`='他們的營地一團亂。發生什麼事?', `FemaleText_loc7`='El campamento está en ruinas. ¿Qué pasó?' WHERE `ID`=61774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 수습생. 병사들은 어디 있나?', `MaleText_loc4`='新兵，我们的军队在哪？', `MaleText_loc5`='你，新來的。部隊在哪裡?', `MaleText_loc7`='Tú, iniciado. ¿Dónde están las tropas?' WHERE `ID`=61775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님! 병사들은 다리에서 사마귀 공격 부대를 저지하는 중입니다.', `MaleText_loc4`='祝掌门！他们在桥那边，抵挡一支螳螂妖部队，大人。', `MaleText_loc5`='祝宗主!他們在橋上拖延螳螂人的攻勢，長官。', `MaleText_loc7`='¡Lord Zhu! En el puente, señor, luchando contra un escuadrón de asalto de mántides.' WHERE `ID`=61776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들이 야영지 정비하는 걸 도와주게나. 나는 다리 쪽 상황을 봐야겠네.', `MaleText_loc4`='$p，陶矢，帮他们把营地整理干净。我去看看桥下的战况。', `MaleText_loc5`='$p，陶氏，幫這些人讓營區步上軌道，我要評估橋上的情勢。', `MaleText_loc7`='Ayuda a estos hombres con su campamento. Yo evaluaré la situación.' WHERE `ID`=61777;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나머지는 제가 처리할게요. 당신은 저 화살로 다리에서 공격하세요.', `FemaleText_loc4`='我会处理接下来的事情，你带着那些箭矢去桥下加入战斗。', `FemaleText_loc5`='剩下的我會處理。你把那些箭帶著，到橋上展開行動。', `FemaleText_loc7`='Yo me encargo del resto. Tú toma esas flechas y baja al combate en el puente.' WHERE `ID`=61778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"복덩이"가 뭡니까?', `MaleText_loc4`='“幸运符”是什么？', `MaleText_loc5`='什麼是「幸運星」?', `MaleText_loc7`='¿Qué es un "grisgrís"?', `FemaleText_loc1`='"복덩이"가 뭐죠?', `FemaleText_loc4`='“幸运符”是什么？', `FemaleText_loc5`='什麼是「幸運星」?', `FemaleText_loc7`='¿Qué es un "grisgrís"?' WHERE `ID`=61779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복덩이요? 복과 행운이 깃든 사람이나 장소나 물건이지요.$b$b그루멀한테 복덩이라 불리는 건 최고의 찬사랍니다.$b$b복덩이는 보통 특별한 냄새를 지니고 있어요. 그루멀은 코가 예민해서 냄새로 복을 찾거든요.', `MaleText_loc4`='幸运符？是指能带来好运和财富的人、地方或物品。$b$b幸运符是土地精给予最高的赞美之词。$b$b通常，幸运符本身拥有独特的气息。土地精灵敏的嗅觉可以通过幸运符的气味找到好运。', `MaleText_loc5`='幸運星?那可以是一個帶有好運的人、地方或東西。$b$b被咕嚕摩稱作幸運星是一種最大的讚美。$b$b幸運星通常都有種特殊的味道。咕嚕摩的鼻子對幸運的味道很敏銳。', `MaleText_loc7`='¿Un grisgrís? Pues una persona, lugar o cosa que da buena suerte y fortuna.$b$bEl mayor elogio que te puede hacer un grúmel es llamarte grisgrís.$b$bNormalmente, los grisgrís tienen un olor especial. El olfato de los grúmel es especialista en encontrar la suerte por su aroma.' WHERE `ID`=61780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 질문을 하고 싶습니다.', `MaleText_loc4`='我想问问其他的。', `MaleText_loc5`='我想問點別的事情。', `MaleText_loc7`='Me gustaría hacer otra pregunta.', `FemaleText_loc1`='다른 질문을 하고 싶어요.', `FemaleText_loc4`='我想问问其他的。', `FemaleText_loc5`='我想問點別的事情。', `FemaleText_loc7`='Me gustaría hacer otra pregunta.' WHERE `ID`=61781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀이 뭡니까?', `MaleText_loc4`='什么是土地精？', `MaleText_loc5`='什麼是咕嚕摩?', `MaleText_loc7`='¿Qué es un grúmel?', `FemaleText_loc1`='그루멀이 뭐죠?', `FemaleText_loc4`='什么是土地精？', `FemaleText_loc5`='什麼是咕嚕摩?', `FemaleText_loc7`='¿Qué es un grúmel?' WHERE `ID`=61782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 그루멀이죠! 산악 수송대이자, 산길의 짐꾼, 산길 안내인, 보급품 배달부지요.$b$b우리는 모구 왕조 때부터 삼베길을 오갔어요. 지금도 장벽을 지키는 사람들에게 식량을 공급하고 있고요.$b$b복 냄새를 기가 막히게 잘 맡기도 하죠!', `MaleText_loc4`='我们为什么是土地精呢！山中的驳车。小径上的送货人。山间的向导，还有补给品运送员。$b$b我们给城墙上的守护者提供食物，我们也是从魔古帝国开元就在粗麻小径上穿梭的人。$b$b我们也拥有最棒的鼻子，可以嗅出好运的味道！', `MaleText_loc5`='我們就是咕嚕摩!山間的渡手，小徑的搬運工，山脈的嚮導，補給品的送件人。$b$b我們負責餵飽長城的衛士，打從魔古王朝就在粗麻小徑上到處穿梭。我們還有擅長聞到好運氣的鼻子!', `MaleText_loc7`='¿Cómo? ¡Nosotros somos los grúmel! Los transportadores de la montaña. Los empacadores de los senderos. Los guías de las montañas y los distribuidores de suministros.$b$bSomos la gente que lleva alimentos a los defensores de la muralla, y somos la gente que transita la Senda Arpillera desde los tiempos de las dinastías mogu.$b$bAdemás... ¡tenemos las narices más mejores para oler la suerte!' WHERE `ID`=61783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 사마귀 의회를 섬기러 깨어났다. 하지만 넌 클락시바가 아니구나...', `MaleText_loc4`='誓死为议会效命。但你不是卡拉克西瓦……', `MaleText_loc5`='我回來為議會服務。但你不是卡拉西瓦...', `MaleText_loc7`='He regresado para servir al consejo. Pero tú no eres un Klaxxi''va...' WHERE `ID`=61784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 상어호의 잔해로 데려가 주십시오!', `MaleText_loc4`='送我去天鲨号残骸！', `MaleText_loc5`='帶我到天鯊號殘骸那裏去!', `MaleText_loc7`='¡Llévame hasta los Restos del Tiburón Celeste!', `FemaleText_loc1`='하늘 상어호의 잔해로 데려가 주세요!', `FemaleText_loc4`='送我去天鲨号残骸！', `FemaleText_loc5`='帶我到天鯊號殘骸那裏去!', `FemaleText_loc7`='¡Llévame hasta los Restos del Tiburón Celeste!' WHERE `ID`=61785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 큰소리로 짖어 도움을 요청합니다!', `MaleText_loc4`='%s大声向附近的盟友求救！', `MaleText_loc5`='%s大聲嗷叫，向周圍的盟友求援!', `MaleText_loc7`='¡%s ladra con fuerza y llama a los aliados cercanos en su ayuda!', `FemaleText_loc1`='%s|1이;가; 큰소리로 짖어 도움을 요청합니다!', `FemaleText_loc4`='%s大声向附近的盟友求救！', `FemaleText_loc5`='%s大聲嗷叫，向周圍的盟友求援!', `FemaleText_loc7`='¡%s ladra con fuerza y llama a los aliados cercanos en su ayuda!' WHERE `ID`=61786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰은... 맥주 취향이 좀 특이하지요. 그런데 딱히 친구들을 위해서 맥주를 준비하는 것 같지는 않아요.', `FemaleText_loc4`='我想说，被遗忘者……在酒方面的口味非常独特。但是，我感觉他们不是在为朋友准备。', `FemaleText_loc5`='我得說，被遺忘者對酒的品味很...奇特。不過，我有種感覺他們的酒不總是用來給自己人喝的。', `FemaleText_loc7`='He de decir que los Renegados tienen un... gusto extraño cuando se trata de cerveza. Aunque creo que no la preparan para amigos exactamente.' WHERE `ID`=61787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 상어호의 잔해로 데려가 주십시오!', `MaleText_loc4`='送我去天鲨号残骸！', `MaleText_loc5`='帶我到天鯊號殘骸那裏去!', `MaleText_loc7`='¡Llévame hasta los Restos del Tiburón Celeste!', `FemaleText_loc1`='하늘 상어호의 잔해로 데려가 주세요!', `FemaleText_loc4`='送我去天鲨号残骸！', `FemaleText_loc5`='帶我到天鯊號殘骸那裏去!', `FemaleText_loc7`='¡Llévame hasta los Restos del Tiburón Celeste!' WHERE `ID`=61788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네?', `FemaleText_loc4`='什么事？', `FemaleText_loc5`='如何?', `FemaleText_loc7`='¿Sí?' WHERE `ID`=61789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀에 대해 그렇게 궁금하다면, 클락시베스로 돌아가는 길에 더 많은 것을 말해주겠다.$B$B그게 아니라면 나를 가만 놓아두거라.', `MaleText_loc4`='如果你对螳螂妖真这么感兴趣，我会在前往卡拉克西维斯的路上继续说给你听。$B$B现在别妨碍我工作。', `MaleText_loc5`='如果你對螳螂人很好奇，我會在往卡拉西斐斯的路上告訴你更多事。$B$B如果不是，那就讓我好好工作。', `MaleText_loc7`='Si tienes mucha curiosidad por los mántides, te explicaré más cosas de camino a Klaxxi''vess.$b$bSi no, déjame trabajar.' WHERE `ID`=61790;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포세이큰은 뭐든지 빨리 배우네요. 한때 살아 있었던 늙은 개에게도 새로운 재주를 가르칠 수 있는 모양이에요.', `FemaleText_loc4`='被遗忘者的学习速度很快。我猜你可以教那个老……嗯，那个，曾经生龙活虎的那个老家伙一些新技巧。', `FemaleText_loc5`='被遺忘者的學習能力很強。看來老狗...或者說曾經活過的老狗，終究能學會新把戲。', `FemaleText_loc7`='Estos renegados son alumnos aventajados. Imagino que podrás enseñarle a un... perro viejo antes vivo algunos nuevos trucos.' WHERE `ID`=61791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐랍니까?', `MaleText_loc4`='她在说什么？', `MaleText_loc5`='她在說什麼?', `MaleText_loc7`='¿Qué está diciendo?' WHERE `ID`=61792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사', `MaleText_loc4`='武僧', `MaleText_loc5`='武僧', `MaleText_loc7`='Monje', `FemaleText_loc1`='수도사', `FemaleText_loc4`='武僧', `FemaleText_loc5`='武僧', `FemaleText_loc7`='Monje' WHERE `ID`=61793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구 내곽에 있다. 만날 취해 있다.', `MaleText_loc4`='就在军事区的内环。她醉得很厉害。', `MaleText_loc5`='在內環的軍事區。她酒喝得真兇。', `MaleText_loc7`='En cinturón interior del Barrio de la Guerra. Bebe mucho.', `FemaleText_loc1`='군사 지구 내곽에 있다. 만날 취해 있다.', `FemaleText_loc4`='就在军事区的内环。她醉得很厉害。', `FemaleText_loc5`='在內環的軍事區。她酒喝得真兇。', `FemaleText_loc7`='En cinturón interior del Barrio de la Guerra. Bebe mucho.' WHERE `ID`=61794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무섭고 못된 여자다. 우리더러 냄새 난다고 한다. 수도사 군사 지구 내곽에 있다.', `MaleText_loc4`='她可吓人了，总是很刻薄，还说我们很臭。她就在军事区的内环。', `MaleText_loc5`='她嚇到我了。她很刻薄，還說我們聞起來很臭。她在內環的軍事區。', `MaleText_loc7`='Me da miedo, es mala y dice que oler mal. Está en Barrio de la Guerra, cinturón interior.', `FemaleText_loc1`='무섭고 못된 여자다. 우리더러 냄새 난다고 한다. 수도사 군사 지구 내곽에 있다.', `FemaleText_loc4`='她可吓人了，总是很刻薄，还说我们很臭。她就在军事区的内环。', `FemaleText_loc5`='她嚇到我了。她很刻薄，還說我們聞起來很臭。她在內環的軍事區。', `FemaleText_loc7`='Me da miedo, es mala y dice que oler mal. Está en Barrio de la Guerra, cinturón interior.' WHERE `ID`=61795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상급 수도사는 군사 지구 내곽에 있네. 우리 죽음경비병에게 자기 민족의 전투 방식을 가르치고 있지.', `MaleText_loc4`='武僧训练师在军事区的内圈。她正在训练一些亡灵卫兵学习她族人的战斗方法。', `MaleText_loc5`='那個武僧訓練師就在內環的軍事區。她在訓練我們部分的亡靈守衛，傳授她們人民的戰鬥方式。', `MaleText_loc7`='El instructor de monjes está en el anillo del Barrio de la Guerra. Está instruyendo a algunos de nuestros Guardias de la muerte en el estilo de lucha de su gente.', `FemaleText_loc1`='상급 수도사는 군사 지구 내곽에 있네. 우리 죽음경비병에게 자기 민족의 전투 방식을 가르치고 있지.', `FemaleText_loc4`='武僧训练师在军事区的内圈。她正在训练一些亡灵卫兵学习她族人的战斗方法。', `FemaleText_loc5`='那個武僧訓練師就在內環的軍事區。她在訓練我們部分的亡靈守衛，傳授她們人民的戰鬥方式。', `FemaleText_loc7`='El instructor de monjes está en el anillo del Barrio de la Guerra. Está instruyendo a algunos de nuestros Guardias de la muerte en el estilo de lucha de su gente.' WHERE `ID`=61796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군사 지구 내곽에 있다네.', `MaleText_loc4`='你可以在军事区的内环区域找到她。', `MaleText_loc5`='你會在內環的軍事區找到她。', `MaleText_loc7`='Está en el Barrio de la Guerra, en el anillo interior.', `FemaleText_loc1`='군사 지구 내곽에 있다네.', `FemaleText_loc4`='你可以在军事区的内环区域找到她。', `FemaleText_loc5`='你會在內環的軍事區找到她。', `FemaleText_loc7`='Está en el Barrio de la Guerra, en el anillo interior.' WHERE `ID`=61797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 년 전, 모구가 모든 힘을 쥐고 있었네. 이 땅을 철권 통치했어. 하지만 왕국이 점차 커지면서, 이를 감독하고 통제할 방법이 필요했지.', `MaleText_loc4`='几千年前，魔古族掌握着所有的力量，他们残暴地统治着这片土地。但是随着帝国的不断发展壮大，他们需要维持秩序并加以控制。', `MaleText_loc5`='幾千年前，魔古掌握了所有的權力。他們以鐵腕統治這片土地。但隨著帝國擴張，他們需要方法來管轄並控制帝國。', `MaleText_loc7`='Hace muchos milenios, los mogu tenían todo el poder. Gobernaban estas tierras con mano de hierro, pero cuando el imperio creció les hizo falta una forma de controlarlo.' WHERE `ID`=61798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 골짜기의 힘과, 생물의 겉모습을 변화시키는 자신들의 능력을 사용해서 난폭한 도마뱀 종족을 타락시키고, 살아있는 무기로 만들었네. 사우록 군대를 만들었지. 황제의 의지를 실천하려고 만들어진, 피에 굶주린 야만족들이었네.', `MaleText_loc4`='他们利用山谷的力量以及他们独有的血肉塑造魔法，将一种凶猛的蜥蜴改造成了具有生命的武器。他们打造了一支军队，一支蜥蜴人大军。这是一群嗜血的怪兽，他们的作用就是巩固皇权。', `MaleText_loc5`='他們使用恆春谷的力量，以及他們那種使血肉變異的魔法，將一支兇殘的蜥蜴種族扭曲塑造成活生生的武器。他們創造了一支軍隊。一支薩烏洛克軍隊。這群嗜血的野蠻人被創造來執行皇帝的意志。', `MaleText_loc7`='Utilizaron los poderes del valle y su propia magia de modelado de carne para crear un arma viviente, una raza de feroces lagartos. Crearon un ejército, un ejército de saurok. Salvajes sedientos de sangre nacidos para ejecutar la voluntad del emperador.' WHERE `ID`=61799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇지만 살아있는 무기에는 문제가 하나 있었네. 뭔지 알겠나?', `MaleText_loc4`='呃，但是创造一种有生命的武器会出现一个问题，你知道吗？', `MaleText_loc5`='啊，但創造活生生的武器會有個問題。你看出來了嗎?', `MaleText_loc7`='Ah, pero crear un arma viviente implica un problema. ¿Sabes cuál es?' WHERE `ID`=61800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 누가 힘을 쥐었을까?', `MaleText_loc4`='现在是谁在支配着力量？', `MaleText_loc5`='現在，掌握權力的，是誰?', `MaleText_loc7`='¿Ahora quién tiene el poder?' WHERE `ID`=61801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼 없는 사우록은, 그 작은 도마뱀 두뇌로도 자신의 지위가 어떤 것인지 깨달았네. 이들은 모구의 적을 죽였어.', `MaleText_loc4`='凶残的蜥蜴人虽然头脑并不发达，但还是很快意识到他们的真实处境。它们先残杀魔古的敌人。', `MaleText_loc5`='即使腦容量只有蜥蜴那麼一丁點大，那些沒有心的薩烏洛克，也馬上就了解他們真正的處境。他們殺死魔古的敵人。', `MaleText_loc7`='Los saurok desalmados no tardaron en darse cuenta de la situación, incluso con sus cerebros de lagartija. Mataron a los enemigos de los mogu.' WHERE `ID`=61802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 모구 제국의 백성들도 죽였지.', `MaleText_loc4`='接着，他们屠戮魔古的臣民。', `MaleText_loc5`='接著，他們殺死被魔古支配的人。', `MaleText_loc7`='Luego mataron a los súbditos de los mogu.' WHERE `ID`=61803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지 않아, 모구들을 죽이기 시작했고.', `MaleText_loc4`='很快，他们便开始残杀魔古。', `MaleText_loc5`='很快的，他們開始殺魔古。', `MaleText_loc7`='Pronto empezaron a matar a los propios mogu.' WHERE `ID`=61804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 황제는 사우록을 모두 제거할 것을 명령했네. 종족 전체를 멸망시키려고 했지만, 소용이 없었네. 사우록은 지금까지도 판다리아를 위협한다네.', `MaleText_loc4`='于是魔古皇帝下令铲除蜥蜴人。他想将整个蜥蜴人种族铲除，却无济于事。他们至今仍在潘达利亚肆虐。', `MaleText_loc5`='魔古皇帝隨即下令，清除所有的薩烏洛克。他試圖抹消整個薩烏洛克族，但是沒有用。時至今日，薩烏洛克仍在潘達利亞上肆虐。', `MaleText_loc7`='El emperador mogu había ordenado purgar a todos los saurok. Intentó exterminar a toda la raza, pero sin éxito. A día de hoy siguen infestando Pandaria.' WHERE `ID`=61805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠나? 힘을 손에 넣긴 쉽지만, 가볍게 생각해서는 안 되네.', `MaleText_loc4`='明白了吧——力量得来容易，却不可轻易给予。', `MaleText_loc5`='所以你明白了，要取得力量很容易，但不該輕易給與。', `MaleText_loc7`='Ya ves. El poder se quita con facilidad, pero no debería darse a la ligera.' WHERE `ID`=61806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사', `MaleText_loc4`='武僧', `MaleText_loc5`='武僧', `MaleText_loc7`='Monje', `FemaleText_loc1`='수도사', `FemaleText_loc4`='武僧', `FemaleText_loc5`='武僧', `FemaleText_loc7`='Monje' WHERE `ID`=61807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아이사 말씀입니까? 스톰윈드 왕궁 북서쪽, 호수 근처에서 다른 판다렌을 훈련시키고 있었습니다.', `MaleText_loc4`='哦，艾莎？我想我看到她在湖边训练其他熊猫人，就在暴风要塞的西北方向。', `MaleText_loc5`='喔艾莎?我應該有看到她在暴風要塞西北邊的湖旁訓練其他熊貓人。', `MaleText_loc7`='Ah, ¿Aysa? Creo que la he visto instruyendo a otros pandaren cerca del lago, al noroeste del Castillo de Ventormenta.', `FemaleText_loc1`='아, 아이사 말씀입니까? 스톰윈드 왕궁 북서쪽, 호수 근처에서 다른 판다렌을 훈련시키고 있었습니다.', `FemaleText_loc4`='哦，艾莎？我想我看到她在湖边训练其他熊猫人，就在暴风要塞的西北方向。', `FemaleText_loc5`='喔艾莎?我應該有看到她在暴風要塞西北邊的湖旁訓練其他熊貓人。', `FemaleText_loc7`='Ah, ¿Aysa? Creo que la he visto instruyendo a otros pandaren cerca del lago, al noroeste del Castillo de Ventormenta.' WHERE `ID`=61808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 도시는 고향의 도시와는 매우 다르군요...

아, 무엇을 도와드릴까요?', `FemaleText_loc4`='这座城市和我的家乡完全不同……

啊，朋友，我能帮你什么忙吗？', `FemaleText_loc5`='這個城市跟老家那裏很不一樣...

啊，朋友，我能幫你什麼忙呢?', `FemaleText_loc7`='Esta ciudad es tan distinta a mi hogar...

Ah, $gamigo:amiga; ¿en qué puedo ayudarte?' WHERE `ID`=61809;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅에는 참 신기하고 흥미로운 것이 많군요. 색다르긴 하지만, 인상 깊습니다.', `FemaleText_loc4`='这片土地上有太多陌生又新奇的东西了。虽然和我的家乡非常不同，可给我留下了深刻的印象。', `FemaleText_loc5`='這片土地上有那麼多奇怪和有趣的事。它很不同，但我非常印象深刻。', `FemaleText_loc7`='Hay infinidad de cosas interesantes y extrañas en esta tierra. Es distinta, pero no deja de impresionarme.' WHERE `ID`=61810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참게... 놈들이 다가오기를 기다리게!', `MaleText_loc4`='耐心……等他们送上门！', `MaleText_loc5`='耐心點...讓他們過來我們這邊!', `MaleText_loc7`='Paciencia... ¡que vengan ellos!' WHERE `ID`=61811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격!!!', `MaleText_loc4`='打！！！', `MaleText_loc5`='攻擊!!!', `MaleText_loc7`='¡¡¡ATACAD!!!' WHERE `ID`=61812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론입니다. 맹주님.', `FemaleText_loc4`='是，祝掌门。', `FemaleText_loc5`='當然，祝宗主。', `FemaleText_loc7`='Por supuesto, lord Zhu.' WHERE `ID`=61813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움판은 저쪽이다, $R.', `MaleText_loc4`='战斗是这么打的，$R。', `MaleText_loc5`='戰鬥是在「那個」方向，$R。', `MaleText_loc7`='La batalla es por ALLÍ, $R.' WHERE `ID`=61814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아니라 저 큰 놈을 쳐야지.', `MaleText_loc4`='你应该去打那个大个子，不是我。', `MaleText_loc5`='你應該去打大傢伙，而不是我。', `MaleText_loc7`='Se supone que debes pegar al grandote, no a mí.' WHERE `ID`=61815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가서 싸워라!', `MaleText_loc4`='快滚回来战斗！', `MaleText_loc5`='出去外頭戰鬥!', `MaleText_loc7`='¡Vuelve ahí y lucha!' WHERE `ID`=61816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족장님께서 날 말리시는 걸 다행으로 알아라.', `MaleText_loc4`='算你走运，我们的部族首领没有让我出手。', `MaleText_loc5`='算你運氣好，我們的部族首領攔住了我。', `MaleText_loc7`='Tienes suerte de que el líder de nuestro clan me esté sujetando.' WHERE `ID`=61817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 귀찮게 하다니 잘못 생각한 거다, $R.', `MaleText_loc4`='你找错魔古了，$R。', `MaleText_loc5`='你惹錯魔古了，$R。', `MaleText_loc7`='Te has metido con el Mogu equivocado, $R.' WHERE `ID`=61818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사', `MaleText_loc4`='武僧', `MaleText_loc5`='武僧', `MaleText_loc7`='Monje', `FemaleText_loc1`='수도사', `FemaleText_loc4`='武僧', `FemaleText_loc5`='武僧', `FemaleText_loc7`='Monje' WHERE `ID`=61819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 밑 빠진 독의 리우 말입니까? 부싯돌 선술집에서 술 마시기 대회에 참가하고 있는데, 그렇게 오래 마시는 사람은 처음입니다. 선술집은 아이언포지 성문에서 바로 북쪽에 있습니다.', `MaleText_loc4`='噢，千杯不醉刘伶？他大部分时间都在铁炉堡大门北边的石火旅店里跟人拼酒。', `MaleText_loc5`='喔，『千杯不醉』劉?他在石火旅店參加一場史上最久的喝酒競賽。就在鐵爐堡北邊的門那邊。', `MaleText_loc7`='Oh, ¿Liu de la Jarra Insaciable? Lleva una eternidad en un concurso de beber en la Taberna Roca de Fuego, al norte de las puertas de Forjaz.', `FemaleText_loc1`='아, 밑 빠진 독의 리우 말입니까? 부싯돌 선술집에서 술 마시기 대회에 참가하고 있는데, 그렇게 오래 마시는 사람은 처음입니다. 선술집은 아이언포지 성문에서 바로 북쪽에 있습니다.', `FemaleText_loc4`='噢，千杯不醉刘伶？他大部分时间都在铁炉堡大门北边的石火旅店里跟人拼酒。', `FemaleText_loc5`='喔，『千杯不醉』劉?他在石火旅店參加一場史上最久的喝酒競賽。就在鐵爐堡北邊的門那邊。', `FemaleText_loc7`='Oh, ¿Liu de la Jarra Insaciable? Lleva una eternidad en un concurso de beber en la Taberna Roca de Fuego, al norte de las puertas de Forjaz.' WHERE `ID`=61820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 싸움꾼이십니까? 그 판다렌 친구는 부싯돌 선술집에 있습니다.', `MaleText_loc4`='啊，你是武僧吧？你可以在石火旅店找到你的熊猫人朋友。', `MaleText_loc5`='喔，打拳的是吧?你會在石火旅店找到你那個熊貓人朋友。', `MaleText_loc7`='¿Así que te gusta pelear? Encontrarás a tu amigo pandaren en la Taberna Roca de Fuego.', `FemaleText_loc1`='아, 싸움꾼이십니까? 그 판다렌 친구는 부싯돌 선술집에 있습니다.', `FemaleText_loc4`='啊，你是武僧吧？你可以在石火旅店找到你的熊猫人朋友。', `FemaleText_loc5`='喔，打拳的是吧?你會在石火旅店找到你那個熊貓人朋友。', `FemaleText_loc7`='¿Así que te gusta pelear? Encontrarás a tu amigo pandaren en la Taberna Roca de Fuego.' WHERE `ID`=61821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 어떻게 싸우는지는 아직 몰라도, 왜 싸워야 하는지는 알아요!', `FemaleText_loc4`='或许我还不知道该如何战斗，但我知道什么值得我去战斗！', `FemaleText_loc5`='也許我還不知道該如何戰鬥，但我知道該為何而戰!', `FemaleText_loc7`='¡Puede que aún no haya aprendido a luchar, pero desde luego sé por qué merece la pena luchar!' WHERE `ID`=61822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠는 아직도 나한테 이래라 저래라 할 수 있다고 생각해요! 내가 이제 어린애가 아니라는 걸 아빠도 알아야 해요.', `FemaleText_loc4`='我父亲还以为他能对我颐指气使！我不再是个小孩子了，他应该认识到这一点。', `FemaleText_loc5`='我父親以為他還能提點我!我已經不是小孩子了，他需要明白這一點。', `FemaleText_loc7`='¡Mi padre cree que todavía me puede decir lo que tengo que hacer! Tendrá que hacerse a la idea de que ya no soy una niña.' WHERE `ID`=61823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 남들처럼 우리 마을을 지키기 위해 싸울 권리가 있다고요. 날 훈련시켜 줄 영웅만 있으면 되는데...', `FemaleText_loc4`='我和村子的所有人一样，都有为家乡而战的权利。要是我认识一个能训练我的英雄就好了……', `FemaleText_loc5`='我跟村莊裡的任何人一樣，有權利為保衛家園而戰。如果我認識某個可以訓練我的英雄...', `FemaleText_loc7`='Tengo el mismo derecho que cualquiera de esta aldea de luchar por mi hogar. Ojalá conociera a un héroe que me entrenase...' WHERE `ID`=61824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사람들은 내 취향이야. 물론 가로쉬는 좀 뻣뻣하긴 하지만, 어쨌든 일이 진행되고 있다는 느낌이 들잖아!

어쨌든, 수도사의 길에 대해서 뭘 알려 줄까?', `MaleText_loc4`='这些人很对我的胃口。当然了，加尔鲁什可能有点严厉，不过你能感到他们是干实事的人！

算了，你要我教你点什么武僧技能呢，朋友？', `MaleText_loc5`='這些是跟我同一類的人。當然，也許卡爾洛斯有一點過激，但你真的能感覺到他們要做點什麼事情!

總之，你想知道關於武僧的什麼事呢，朋友?', `MaleText_loc7`='Esta es mi gente. Bueno, puede que Garrosh sea un poco intenso, ¡pero al menos se nota que tienen un objetivo!

En fin, ¿qué puedo enseñarte sobre ser monje, $gamigo:amiga;?' WHERE `ID`=61825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 사람들은 나와 세상을 보는 눈이 비슷해. 자기 먹을 건 자기가 챙겨야 한다는 그런 거 말야.', `MaleText_loc4`='这里的人有着和我相似的世界观。你必须打出自己的一片天地，你明白吗？', `MaleText_loc5`='這裡的人們真的能夠以我的方式來看待這個世界。你得找到自己的立場，懂嗎?', `MaleText_loc7`='La gente de aquí ve el mundo igual que yo. Uno tiene que buscarse su sitio ¿sabes?' WHERE `ID`=61826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이거 일이 잘 안 되는 것 같네요...', `FemaleText_loc4`='看来我们的任务是为我们量身定制的……', `FemaleText_loc5`='看來我們要中斷我們的行動了...', `FemaleText_loc7`='Ya sabemos lo que tenemos que hacer.' WHERE `ID`=61827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비되면 알려주세요.', `FemaleText_loc4`='我们就等你了。', `FemaleText_loc5`='$p，準備好就一起上。', `FemaleText_loc7`='Estoy lista si tú lo estás.' WHERE `ID`=61828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요. 이제 가서 맹주님과 만나요. 여기서 우리가 할 건 다 했어요.', `FemaleText_loc4`='干得好，我们回去和祝掌门会合。这里也没什么事可做了。', `FemaleText_loc5`='做得好，我們回去和祝宗主見面吧。這兒已經沒什麼事可以做了。', `FemaleText_loc7`='Bien hecho. Vamos a reunirnos con lord Zhu. Aquí ya no podemos hacer nada.' WHERE `ID`=61829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어벽 뒤에 숨어요!', `FemaleText_loc4`='躲到路障后面去！', `FemaleText_loc5`='到防禦據點後面找掩護!', `FemaleText_loc7`='¡Ponte a resguardo detrás de la barricada!' WHERE `ID`=61830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어벽 뒤로 가요!', `FemaleText_loc4`='快到路障后面去！', `FemaleText_loc5`='快到防禦據點後方!', `FemaleText_loc7`='¡Utiliza la barricada para protegerte!' WHERE `ID`=61831;
