UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 지 말인가? 명예의 골짜기에 있는 판다렌 정자에서, 싸움을 구경하면서 전사들과 이야기하고 있다네.', `MaleText_loc4`='哦，季？他在荣誉谷的熊猫人小亭，正在一边观看比赛一边和战士们交谈。', `MaleText_loc5`='喔，紀?他就在榮譽谷的熊貓人涼亭觀賞比武，和戰士們談話。', `MaleText_loc7`='Ah, ¿Ji? Está en el pabellón pandaren en el Valle del Honor, viendo los combates y hablando con los guerreros.', `FemaleText_loc1`='아, 지 말인가? 명예의 골짜기에 있는 판다렌 정자에서, 싸움을 구경하면서 전사들과 이야기하고 있다네.', `FemaleText_loc4`='哦，季？他在荣誉谷的熊猫人小亭，正在一边观看比赛一边和战士们交谈。', `FemaleText_loc5`='喔，紀?他就在榮譽谷的熊貓人涼亭觀賞比武，和戰士們談話。', `FemaleText_loc7`='Ah, ¿Ji? Está en el pabellón pandaren en el Valle del Honor, viendo los combates y hablando con los guerreros.' WHERE `ID`=61833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지는 보통 판다렌 정자에 있다네. 투기장 근처에 있지. 지는 싸움 구경을 좋아하거든. 가끔씩은 직접 참가하기도 한다더군.', `MaleText_loc4`='季通常都在熊猫人小亭。那个地方离竞技场很近，他喜欢看别人打架。我听说他偶尔还会参加比赛。', `MaleText_loc5`='紀通常待在熊貓人涼亭旁邊。就在競技場附近，因為他喜歡看人比武。我聽說他偶爾甚至會自己下場。', `MaleText_loc7`='Ji normalmente está en el pabellón pandaren. Está cerca de la arena, y le encanta mirar los combates. Incluso de vez en cuando participa.', `FemaleText_loc1`='지는 보통 판다렌 정자에 있다네. 투기장 근처에 있지. 지는 싸움 구경을 좋아하거든. 가끔씩은 직접 참가하기도 한다더군.', `FemaleText_loc4`='季通常都在熊猫人小亭。那个地方离竞技场很近，他喜欢看别人打架。我听说他偶尔还会参加比赛。', `FemaleText_loc5`='紀通常待在熊貓人涼亭旁邊。就在競技場附近，因為他喜歡看人比武。我聽說他偶爾甚至會自己下場。', `FemaleText_loc7`='Ji normalmente está en el pabellón pandaren. Está cerca de la arena, y le encanta mirar los combates. Incluso de vez en cuando participa.' WHERE `ID`=61834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 시작합시다!', `MaleText_loc4`='让我们开始训练吧！', `MaleText_loc5`='我們開始訓練吧!', `MaleText_loc7`='¡Vamos a entrenar!', `FemaleText_loc1`='훈련을 시작하죠!', `FemaleText_loc4`='让我们开始训练吧！', `FemaleText_loc5`='我們開始訓練吧!', `FemaleText_loc7`='¡Vamos a entrenar!' WHERE `ID`=61835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 한번 시작해 보자고요!', `FemaleText_loc4`='好了！让我们开始干正事吧！', `FemaleText_loc5`='好啦!我們去做點正經事吧!', `FemaleText_loc7`='¡Muy bien! ¡Manos a la obra!' WHERE `ID`=61836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 탄약을 다 쓰고는 날아가 버립니다!', `MaleText_loc4`='%s弹药告罄，直接飞走了！', `MaleText_loc5`='%s的彈藥耗盡，飛走了!', `MaleText_loc7`='¡%s se queda sin munición y huye!' WHERE `ID`=61838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 도와드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='我可以幫你嗎?', `MaleText_loc7`='¿Cómo puedo ayudarte?', `FemaleText_loc1`='어떻게 도와드릴까요?', `FemaleText_loc4`='我能帮你什么忙吗？', `FemaleText_loc5`='我可以幫你嗎?', `FemaleText_loc7`='¿Cómo puedo ayudarte?' WHERE `ID`=61839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게는 가르칠 것이 없습니다, $c님.', `MaleText_loc4`='我没什么可教你的，$c。', `MaleText_loc5`='我沒什麼可以教你了，$c。', `MaleText_loc7`='No tengo nada que enseñarte, $c.', `FemaleText_loc1`='당신에게는 가르칠 것이 없습니다, $c님.', `FemaleText_loc4`='我没什么可教你的，$c。', `FemaleText_loc5`='我沒什麼可以教你了，$c。', `FemaleText_loc7`='No tengo nada que enseñarte, $c.' WHERE `ID`=61840;
