UPDATE `locales_broadcast_text` SET `MaleText_loc1`='란펀은 신전 정원에 있는 호수에서 명상을 하고 있습니다. 듣자 하니 란펀이 끓이는 차는 매우 향기롭다더군요.', `MaleText_loc4`='兰风就在神殿花园的湖上冥想。我听说她非常擅长泡茶。', `MaleText_loc5`='蘭芬在神殿花園的湖上冥想。我聽說她泡的茶很讚。', `MaleText_loc7`='Encontrarás a Lanfen meditando junto al lago en Los Jardines del Templo. Dicen que hace un té maravilloso.', `FemaleText_loc1`='란펀은 신전 정원에 있는 호수에서 명상을 하고 있습니다. 듣자 하니 란펀이 끓이는 차는 매우 향기롭다더군요.', `FemaleText_loc4`='兰风就在神殿花园的湖上冥想。我听说她非常擅长泡茶。', `FemaleText_loc5`='蘭芬在神殿花園的湖上冥想。我聽說她泡的茶很讚。', `FemaleText_loc7`='Encontrarás a Lanfen meditando junto al lago en Los Jardines del Templo. Dicen que hace un té maravilloso.' WHERE `ID`=61842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간을 내 주셔서 고마워요. 다음에도 훈련을 시켜 주셨으면 좋겠네요.', `FemaleText_loc4`='多谢你的宝贵时间。我希望你以后能重新考虑训练我。', `FemaleText_loc5`='謝謝你花的時間，希望你未來會重新考慮訓練我。', `FemaleText_loc7`='Gracias por tu tiempo. Espero que te replantees instruirme en el futuro.' WHERE `ID`=61843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사', `MaleText_loc4`='武僧', `MaleText_loc5`='武僧', `MaleText_loc7`='Monje', `FemaleText_loc1`='수도사', `FemaleText_loc4`='武僧', `FemaleText_loc5`='武僧', `FemaleText_loc7`='Monje' WHERE `ID`=61844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정기의 봉우리에 있는 체 라를 찾아가십시오. 그곳에서 상급 주술사들을 만나고 있더군요.', `MaleText_loc4`='你可以在灵魂高地找到冉瑟。她正在那里与萨满祭司训练师会面。', `MaleText_loc5`='哲菈就在靈魂高地，她在那裡與薩滿訓練師們會談。', `MaleText_loc7`='Encontrarás a Tseh Rah en el Alto de los Espíritus. Se ha estado reuniendo con los instructores de chamanes de la zona.', `FemaleText_loc1`='정기의 봉우리에 있는 체 라를 찾아가십시오. 그곳에서 상급 주술사들을 만나고 있더군요.', `FemaleText_loc4`='你可以在灵魂高地找到冉瑟。她正在那里与萨满祭司训练师会面。', `FemaleText_loc5`='哲菈就在靈魂高地，她在那裡與薩滿訓練師們會談。', `FemaleText_loc7`='Encontrarás a Tseh Rah en el Alto de los Espíritus. Se ha estado reuniendo con los instructores de chamanes de la zona.' WHERE `ID`=61845;
