UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼는 원정순찰대 광장에서 수련을 하고 있습니다.', `MaleText_loc4`='老肖正在远行者广场练武呢。', `MaleText_loc5`='老修就在遠行者廣場，練習他的功夫。', `MaleText_loc7`='Es posible encontrar al viejo Sho en la Plaza del Errante, practicando sus movimientos.', `FemaleText_loc1`='쇼는 원정순찰대 광장에서 수련을 하고 있습니다.', `FemaleText_loc4`='老肖正在远行者广场练武呢。', `FemaleText_loc5`='老修就在遠行者廣場，練習他的功夫。', `FemaleText_loc7`='Es posible encontrar al viejo Sho en la Plaza del Errante, practicando sus movimientos.' WHERE `ID`=61847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 무도가 판은 교역 지구의 나머지 부분이 내려다보이는 전사의 정원에서 전사들과 함께 수련을 하고 있습니다.', `MaleText_loc4`='武魂潘劲正在俯瞰贸易阶梯的战士平台上和战士们一起训练呢。', `MaleText_loc5`='『武道之靈』潘就在位於貿易區上方的戰士區和戰士們一起訓練。', `MaleText_loc7`='Pan del Espíritu Marcial se entrena con los guerreros en el Bancal del Guerrero, que se alza sobre el resto de la Grada de los Mercaderes.', `FemaleText_loc1`='진정한 무도가 판은 교역 지구의 나머지 부분이 내려다보이는 전사의 정원에서 전사들과 함께 수련을 하고 있습니다.', `FemaleText_loc4`='武魂潘劲正在俯瞰贸易阶梯的战士平台上和战士们一起训练呢。', `FemaleText_loc5`='『武道之靈』潘就在位於貿易區上方的戰士區和戰士們一起訓練。', `FemaleText_loc7`='Pan del Espíritu Marcial se entrena con los guerreros en el Bancal del Guerrero, que se alza sobre el resto de la Grada de los Mercaderes.' WHERE `ID`=61848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사', `MaleText_loc4`='武僧', `MaleText_loc5`='武僧', `MaleText_loc7`='Monje', `FemaleText_loc1`='수도사', `FemaleText_loc4`='武僧', `FemaleText_loc5`='武僧', `FemaleText_loc7`='Monje' WHERE `ID`=61849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적 호젠을 상대하는 비결은, 허를 찌르는 것이지요.', `MaleText_loc4`='对付猢狲海盗的秘诀就在于出其不意。', `MaleText_loc5`='跟猴人海盜週旋的訣竅就在於出其不意。', `MaleText_loc7`='El truco para lidiar con hozen piratas es el factor sorpresa.' WHERE `ID`=61850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 그러니까... 해적 호젠을 상대하는 새로운 비결을 말씀드리자면, 그냥 방금처럼만 하십시오.', `MaleText_loc4`='好吧……那么……对付猢狲海盗的新招数就是把你刚才做的再做一遍。', `MaleText_loc5`='好吧...那麼...跟猴人海盜週旋的新訣竅，就是做你剛剛在這裡做過的事。', `MaleText_loc7`='Vale... Pues... El nuevo truco para lidiar con hozen piratas es eso que acabáis de hacer.' WHERE `ID`=61851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 저 소리 들리십니까? 작은 날개가 파닥거리는 소리 같은데...', `MaleText_loc4`='等等！你听到了吗？听上去就像细小的翅膀拍动的声音……', `MaleText_loc5`='等等!你聽見了嗎?聽起來像是小翅膀拍動的聲音...', `MaleText_loc7`='¡Esperad! ¿Oís eso? Parece el aleteo de unas alas diminutas...' WHERE `ID`=61852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=61853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬 전체에 우리의 존재를 들키기 전에 빨리 움직이는 게 좋겠군요.', `MaleText_loc4`='我们最好抢在全岛的敌人都发现我们之前继续前进.', `MaleText_loc5`='在整座島的人都發現我們在這兒之前，我們最好繼續行動。', `MaleText_loc7`='Será mejor seguir adelante antes de que la isla entera sepa que estamos aquí.' WHERE `ID`=61854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠에 검투사가? 무기는 다 어디서 난 거지?', `MaleText_loc4`='猢狲角斗士？它们从哪儿找来的这些武器？', `MaleText_loc5`='猴人鬥士?他們是去哪找到那些武器的?', `MaleText_loc7`='¿Gladiadores hozen? ¿De dónde han sacado tantas armas?' WHERE `ID`=61855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 맥주를 만들기에 썩 괜찮은 자리군요.', `MaleText_loc4`='好吧！这地方看起来并不妨碍酿酒。', `MaleText_loc5`='嗯!這裡看起來比任何地方都要適合釀造啤酒。', `MaleText_loc7`='¡Bueno! Este sitio parece tan bueno como cualquier otro para elaborar brebajes.' WHERE `ID`=61856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해적보다 더 나쁜 게 딱 하나 있는데, 뭔지 아십니까? 호젠 해적이죠! 놈들은 우리 해변에 쳐들어와서는 생선과 배, 맥주를 훔쳐갑니다. 맥주만큼은 누구도 훔쳐갈 수 없습니다... 누구도요.', `MaleText_loc4`='你知道比海盗更坏的是什么吗？猢狲海盗！它们袭击了我们的海岸，把鲜鱼、船只和美酒全都偷走了。没有人能偷走我们的酒……没有人。', `MaleText_loc5`='知道什麼比海盜更糟嗎?就是猴人海盜!他們打劫我們的海岸，偷走我們的魚、船、還有啤酒。沒有人可以偷走我們的啤酒...沒有人。', `MaleText_loc7`='¿Sabes qué es peor que un pirata? ¡Un pirata hozen! Asaltan nuestras costas y nos roban el pescado, los barcos y el brebaje. Nadie se lleva nuestro brebaje... Nadie.' WHERE `ID`=61857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='我们开始吧！', `MaleText_loc5`='我們開始吧!', `MaleText_loc7`='¡En marcha!', `FemaleText_loc1`='가요!', `FemaleText_loc4`='我们开始吧！', `FemaleText_loc5`='我們開始吧!', `FemaleText_loc7`='¡En marcha!' WHERE `ID`=61858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장 우끼는 괴혈병이 있습니다! 녀석에게서 오렌지를 숨기십시오!', `MaleText_loc4`='乌克头领正在传播败血症！别让他靠近橘子！', `MaleText_loc5`='烏克船長患了壞血病!把柳橙拿離他遠點!', `MaleText_loc7`='¡El capitán Ook está desarrollando escorbuto! ¡Que no se acerque a la naranja!' WHERE `ID`=61859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘가르기 줄 준비하는 중', `MaleText_loc4`='准备拉索', `MaleText_loc5`='準備好吊索', `MaleText_loc7`='Preparando tirolina', `FemaleText_loc1`='하늘가르기 줄 준비하는 중', `FemaleText_loc4`='准备拉索', `FemaleText_loc5`='準備好吊索', `FemaleText_loc7`='Preparando tirolina' WHERE `ID`=61860;
