UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새까지?! 대체 언제 새를 길들이는 법까지 배웠지?', `MaleText_loc4`='还有鸟？他们是怎么学会驯鸟的啊？！', `MaleText_loc5`='還有鳥?!他們是怎麼學會馴服這些鳥的?', `MaleText_loc7`='¡¿Pájaros también?! ¡¿Cómo han aprendido a domesticar pájaros?!' WHERE `ID`=61862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 꼬마 친구한테 인사해라!', `MaleText_loc4`='跟我的小朋友说声嗨！', `MaleText_loc5`='和我的小小朋友打個招呼吧!', `MaleText_loc7`='¡Dile hola a mi amiguito!' WHERE `ID`=61863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 두 동강 내 주마!', `MaleText_loc4`='我要把你劈成两半！', `MaleText_loc5`='我要把你劈成兩半!', `MaleText_loc7`='¡Yo os korta en dos!' WHERE `ID`=61864;
