UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼 물고기 먹고 싶다! 물고기 먹으면 너희 해치울 힘 난다!', `MaleText_loc4`='乌克要吃鱼！吃鱼长力气，杀坏蛋！', `MaleText_loc5`='烏奇要吃魚!魚會給我力量解決你們這些廢渣!', `MaleText_loc7`='¡Ookie kiere peskado! ¡Peskado da fuerza para akabar con mikos!' WHERE `ID`=61870;
