UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가마솥은... 맥주를 만드는 데 딱이군요.', `MaleText_loc4`='这个大锅很适合煮我们的……酒。', `MaleText_loc5`='這大鍋真是太完美了，可以用來釀我們的...啤酒。', `MaleText_loc7`='Este caldero será perfecto para elaborar nuestro... brebaje.' WHERE `ID`=61872;
