UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거, 제 배가 꼬르륵거리는 소립니까, 아니면 커다란 게 다가오는 소립니까?', `MaleText_loc4`='是我的肚子叫叫唤，还是有什么大家伙过来了？', `MaleText_loc5`='是我的肚子在響，還是有什麼大傢伙過來了?', `MaleText_loc7`='¿Ese ruido es mi estómago, o se acerca algo GRANDE?' WHERE `ID`=61874;
