UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가할 준비는 됐겠지!', `MaleText_loc4`='准备受死吧，坏蛋！', `MaleText_loc5`='你最好做好被便便砸的準備!', `MaleText_loc7`='¡PREPÁRENSE PARA KE LES HAGA KRAKU EN LOS WAKUS!' WHERE `ID`=61877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쾅콰콰쾅!', `MaleText_loc4`='砰！叭叭——碰！', `MaleText_loc5`='砰!砰砰砰!', `MaleText_loc7`='¡Bam ba-ba-BAM!' WHERE `ID`=61878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 오렌지를 손에 넣었습니다!', `MaleText_loc4`='$n拿到了橘子！', `MaleText_loc5`='$n拿到柳橙了!', `MaleText_loc7`='¡$n tiene la naranja!' WHERE `ID`=61879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선장 우끼의 괴혈병이 심해집니다!', `MaleText_loc4`='乌克头领获得了完全型败血症！', `MaleText_loc5`='烏克船長得了嚴重壞血病!', `MaleText_loc7`='¡El capitán Ook tiene escorbuto!' WHERE `ID`=61880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 오렌지를 던졌습니다!', `MaleText_loc4`='$n扔出了橘子！', `MaleText_loc5`='$n丟了柳橙!', `MaleText_loc7`='¡$n ha tirado la naranja!' WHERE `ID`=61881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 때문에 화나서 못 살겠다!', `MaleText_loc4`='你们惹火我啦！', `MaleText_loc5`='你讓我非常火大!', `MaleText_loc7`='¡Me están MOLESTANDO!' WHERE `ID`=61882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 응가들아! 오렌지 내놔라!', `MaleText_loc4`='坏蛋！把橘子给我！', `MaleText_loc5`='你這廢渣!把柳橙給我!', `MaleText_loc7`='¡Mikos! ¡Dadme esa naranja!' WHERE `ID`=61883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불공평하다! 우낏 세 놈이 나 하나한테 덤비는 거냐?!', `MaleText_loc4`='不公平！你们这些蠢蛋竟然三打一？！', `MaleText_loc5`='不公平!你們三個怪怪人對付我一個?!', `MaleText_loc7`='¡No es justo! ¡¿Tres makakus kontra mí solo?!' WHERE `ID`=61884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 오렌지를 가져가?! 이건 모욕이다!', `MaleText_loc4`='你拿了我的橘子？！你这是当面挑衅！', `MaleText_loc5`='你拿走我的柳橙?!簡直是一巴掌打在我臉上!', `MaleText_loc7`='¡¿Me kitáis la naranja?! ¡Ké bofetada!' WHERE `ID`=61885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 오렌지 필요하다! 내놔라!', `MaleText_loc4`='我要橘子！给我！', `MaleText_loc5`='我需要那個柳橙!給我!', `MaleText_loc7`='¡Yo necesita esa naranja! ¡Dame!' WHERE `ID`=61886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 훨씬 낫다! 이제 너 응가들 혼날 거다!', `MaleText_loc4`='哈！这下好多了！现在你们这些坏蛋要倒霉了！', `MaleText_loc5`='哈!好多了!現在你們這些廢渣要糟糕了!', `MaleText_loc7`='¡Ja! ¡Mucho mejor! ¡Ahora se las verán, mikos!' WHERE `ID`=61887;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='광산에 거미들이 다시 나타났다는 말을 들었단다. 다친 이가 없었으면 좋겠는데...', `FemaleText_loc4`='我听说矿坑又遭到了蜘蛛的侵袭。但愿没有人受伤。', `FemaleText_loc5`='我聽說礦坑又出現大量的蜘蛛了，真希望沒人因此受傷。', `FemaleText_loc7`='He oído que las minas estás infestadas de arañas otra vez. Espero que nadie salga herido.' WHERE `ID`=61888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안개 너머의 이방인들이 비취 숲 전역에 나타나기 시작했다는구나. 불안한 시절이야.', `FemaleText_loc4`='他们说，从迷雾另一边来的陌生人进入了翡翠林。真是个古怪的时代。', `FemaleText_loc5`='他們說霧之外的陌生人已經現身，穿越翠玉林。很怪的時間點。', `FemaleText_loc7`='Se comenta que han empezado a aparecer extraños de más allá de la niebla por el Bosque de Jade. Corren tiempos insólitos...' WHERE `ID`=61889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대지 요마들이 녹옥 채석장의 채굴 현장을 못마땅해 한다고 들었단다. 우리에게 화풀이라도 하는 건 아니겠지?', `FemaleText_loc4`='我听说，土灵在绿石采掘场闹得很不愉快。但愿他们不会拿我们出气。', `FemaleText_loc5`='我聽說有些大地之靈因為綠石採石場而不大開心。我希望他們不會拿我們來出氣。', `FemaleText_loc7`='Me han contado que algunos espíritus de la tierra están descontentos con la Cantera Verdemar. Espero que no la tomen con nosotros.' WHERE `ID`=61890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 국수 맛이 어떠니?', `FemaleText_loc4`='今天的面条怎么样？', `FemaleText_loc5`='今天的麵條如何?', `FemaleText_loc7`='¿Cómo están hoy los tallarines?' WHERE `ID`=61891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 킬루크, 저 먼 과거에서 돌아온 전사다.', `MaleText_loc4`='我是克尔鲁克，来自久远时代的战士。', `MaleText_loc5`='我是基爾魯克，一個來自久遠以前的戰士。', `MaleText_loc7`='Soy Kil''ruk, un guerrero de una era muy antigua.' WHERE `ID`=61892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 시대에 여긴 모구 요새였지. 나는 기쁘게 이 장벽에 놈들의 피를 뿌렸다.', `MaleText_loc4`='在我的年代，这是个魔古族据点。我有幸用他们的鲜血涂满了墙壁。', `MaleText_loc5`='在我的時代，這裡是一個魔古堡壘。當時能把他們的血塗在長城上是我的榮耀。', `MaleText_loc7`='En mi época, esto era un bastión de los mogu. Fue un honor pintar estos muros con su sangre.' WHERE `ID`=61893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 명예로운 행동으로 나는 용장이란 이름을 얻고 호박 속에 보존되었지. 이 제국에 수술이 필요해지는 그날까지.', `MaleText_loc4`='我的功绩为我赢得了英杰的美名。我作为英雄被保存在琥珀之中，在帝国需要的时候……苏醒。', `MaleText_loc5`='由於這些功績，人們稱我為「聖螳」。我是暫時被保存在琥珀裡的英雄，以備帝國需要被...「修正」。', `MaleText_loc7`='Por mis hazañas, me nombraron "dechado": un héroe preservado en ámbar, para cuando hubiera que... enderezar al imperio.' WHERE `ID`=61894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 대체 어떤 힘이 우리 땅을 휩쓸고 우리 나무를 망치는가?', `MaleText_loc4`='唤醒者，是什么力量燃烧我们的土地，腐化我们的林木？', `MaleText_loc5`='喚醒者，燃燒土地、污染樹木的，是什麼樣的力量?', `MaleText_loc7`='Dime: ¿qué poder es ese que quema nuestra tierra y corrompe nuestros árboles?' WHERE `ID`=61895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁전이! 이건 우리 방식이 아니다. 왜 클락시가 움직였는지 알겠군.', `MaleText_loc4`='皇宫！简直……面目全非。我明白为什么卡拉克西要被迫采取行动了。', `MaleText_loc5`='皇宮!這不是...我們的作法。我明白為什麼卡拉西會被迫採取行動了。', `MaleText_loc7`='¡El palacio! Esa no... no es nuestra filosofía. Entiendo por qué los Klaxxi tienen que actuar.' WHERE `ID`=61896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시는 가장 현명한 지도자들로 구성된 의회다. 여제를 감시하는 역할을 하지.', `MaleText_loc4`='他们是由最睿智的文化领袖组成的议会。负责监督女皇。', `MaleText_loc5`='那是由我們最睿智的文化領袖所組成的議會。他們負責監督女皇的權力。', `MaleText_loc7`='Son un consejo de nuestros líderes culturales más sabios. Son el contrapunto al poder de la Emperatriz.' WHERE `ID`=61897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 분은 가마솥을 좀 지켜 주십쇼. 나머지는 웅가 밀림 맥주를 찾아서 가져와 주시고요!', `MaleText_loc4`='你们来个人和我一起看管酿酒的大锅。其他人去找一些盎迦丛林酒，然后交给我！', `MaleText_loc5`='你們挑一個人跟我去確保大鍋的安全，其他人去找些仰加叢林啤酒回來!', `MaleText_loc7`='Que uno de ustedes se quede conmigo para mantener el caldero a salvo. ¡Los demás! ¡Vayan a buscar brebaje de jungla de Unga y tráiganlo!' WHERE `ID`=61898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제가 타락하거나 우리 문명을 위험에 빠뜨리면, 그녀를 옥좌에서 끌어내리는 것이 클락시의 임무이다.', `MaleText_loc4`='一旦女皇堕入腐化或威胁到我们的文明，卡拉克西就一定让她皇位不保。', `MaleText_loc5`='如果她墮落腐敗，或者會危害到我們文明，卡拉西誓言要推翻她。', `MaleText_loc7`='Los Klaxxi han jurado derrocar a la Emperatriz si sucumbe a la corrupción o si pone en peligro a nuestro pueblo.' WHERE `ID`=61899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같은 이가 또 있다. 각 시대의 용장이 호박 속에 보존되어, 여제의 속삭임이 미치지 않는 곳에 묻혔지.', `MaleText_loc4`='各时代的英杰，包括我，都被凝固在时间长河中，埋藏在女皇无法控制的地方。', `MaleText_loc5`='還有其他像我這樣的人。每個時代的聖螳會被凍結在時間裡，安全地埋藏起來，不受女皇低語的影響。', `MaleText_loc7`='No soy el único. Hay dechados de todas las épocas, congelados en el tiempo y enterrados lejos de los susurros de la Emperatriz.' WHERE `ID`=61900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오로지 의회에만 복종하며, 의회의 뜻이 실현되었을 때만 멈춘다.', `MaleText_loc4`='我们只响应议会的召唤。完成他们的意志再进入沉睡。', `MaleText_loc5`='我們只回應議會的呼喚。在貫徹議會的意志後，才能休息。', `MaleText_loc7`='Solo respondemos ante el consejo. Solo descansamos cuando se ha hecho su voluntad.' WHERE `ID`=61901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여기 내가 말하던 친구가 있군.', `MaleText_loc4`='啊，这就是我跟你说起过的那位$c。', `MaleText_loc5`='啊，這就是我跟你提過的那個人。', `MaleText_loc7`='Ah, aquí está quien te había mencionado.' WHERE `ID`=61902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전을 시작하시겠습니까?', `MaleText_loc4`='你想要开始挑战吗？', `MaleText_loc5`='你想開始挑戰嗎?', `MaleText_loc7`='¿Quieres comenzar el desafío?', `FemaleText_loc1`='도전을 시작하시겠습니까?', `FemaleText_loc4`='你想要开始挑战吗？', `FemaleText_loc5`='你想開始挑戰嗎?', `FemaleText_loc7`='¿Quieres comenzar el desafío?' WHERE `ID`=61903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 이 사마귀 놈들을 없애 버리면, 다리를 되찾을 수 있네.', `MaleText_loc4`='很好！让我们解决掉这些螳螂妖，然后夺回那座桥。', `MaleText_loc5`='好!先擺脫這些螳螂人，然後去奪回橋樑。', `MaleText_loc7`='¡Bien! Despachemos a los mántides y luego retomaremos el puente.' WHERE `ID`=61904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹주님께서 곧 돌아오실 걸세.', `MaleText_loc4`='祝掌门，我们很快回来。', `MaleText_loc5`='祝宗主，我們很快就會搞定。', `MaleText_loc7`='Lord Zhu, volvemos enseguida.' WHERE `ID`=61905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 시작하겠습니다.', `MaleText_loc4`='是的，我要开始挑战。', `MaleText_loc5`='是的，開始挑戰吧。', `MaleText_loc7`='Sí, comenzar el desafío.', `FemaleText_loc1`='예, 시작하겠어요.', `FemaleText_loc4`='是的，我要开始挑战。', `FemaleText_loc5`='是的，開始挑戰吧。', `FemaleText_loc7`='Sí, comenzar el desafío.' WHERE `ID`=61906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 둘 다 일을 마치면 내게 돌아오게.', `MaleText_loc4`='我很乐意。任务完成之后赶紧回来。', `MaleText_loc5`='我很樂意。你們兩個完成之後來跟我回報。', `MaleText_loc7`='Será un placer. Vuelvan a verme cuando hayan terminado.' WHERE `ID`=61907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 이 벌레들을 몰아내세!', `MaleText_loc4`='来吧，$p，让我们击退这些虫子！', `MaleText_loc5`='來吧，$p，我們把這些昆蟲打回去!', `MaleText_loc7`='¡Vamos! ¡Acabemos con esos insectos!' WHERE `ID`=61908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결전의 장소는 바로 여길세!', `MaleText_loc4`='我们将坚守这里！', `MaleText_loc5`='我們就死守在這裡!', `MaleText_loc7`='¡Es el momento de hacerles frente!' WHERE `ID`=61909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 마시게. 약간 독할 걸세.', `MaleText_loc4`='把这个喝下去。后劲儿有点大。', `MaleText_loc5`='把這喝了，它後勁十足。', `MaleText_loc7`='Bebe esto. Tiene un poco de chispa.' WHERE `ID`=61910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 마시게!', `MaleText_loc4`='来口这个尝尝！', `MaleText_loc5`='嚐一口吧!', `MaleText_loc7`='¡Dale un sorbo a esto!' WHERE `ID`=61911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 퍼부어 주게!', `MaleText_loc4`='把这个倒回去！', `MaleText_loc5`='把這倒入你的喉嚨吧!', `MaleText_loc7`='¡Hasta la última gota!' WHERE `ID`=61912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통을 걷어차!', `MaleText_loc4`='把桶踢向他们！', `MaleText_loc5`='把酒桶往他們踢過去!', `MaleText_loc7`='¡Lánzales el barril!' WHERE `ID`=61913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떨어지게!', `MaleText_loc4`='加把劲！', `MaleText_loc5`='快閃開!', `MaleText_loc7`='¡Aléjate!' WHERE `ID`=61915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 눌렀군, 계속 그렇게 하게!', `MaleText_loc4`='他中招了，继续！', `MaleText_loc5`='你抓到他了，繼續保持!', `MaleText_loc7`='¡Ya casi está! ¡Sigue así!' WHERE `ID`=61916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 쓰러졌네!', `MaleText_loc4`='他快不行了！', `MaleText_loc5`='他快要倒下了!', `MaleText_loc7`='¡Ya casi cae!' WHERE `ID`=61917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 자네, 이번 임무에 아주 적격이었네.', `MaleText_loc4`='干得好，$p！选你真是选对人了。', `MaleText_loc5`='$p，做得好!選你來執行任務真是選對了。', `MaleText_loc7`='¡Buen trabajo! Nadie lo habría hecho mejor.' WHERE `ID`=61918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님께 돌아가게. 나도 곧 뒤따라가겠네.', `MaleText_loc4`='回去找祝踏岚吧。我很快就会追上你的。', `MaleText_loc5`='你先想辦法回塔蘭·祝身邊，我很快就會趕上。', `MaleText_loc7`='Ve a ver a Taran Zhu. Yo te alcanzaré dentro de un rato.' WHERE `ID`=61919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십자로는 여기서 멀지 않다네. 거기서 마지막 지원자를 찾아보세나.', `MaleText_loc4`='十字路口离这儿不远。我们去那儿寻找最后一名成员。', `MaleText_loc5`='十字路口就在不遠處，我們去那裡尋找最後一個成員吧。', `MaleText_loc7`='El cruce está cerca. Allí buscaremos a nuestro último miembro.' WHERE `ID`=61920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들이 누롱이란 자를 칭찬하더군요. 만나게 되어 기쁩니다.', `MaleText_loc4`='弟兄们都对这位砮荣赞誉有加。终于能得见本尊了。', `MaleText_loc5`='我的人對砮龍有很高的評價，真高興終於能見到他。', `MaleText_loc7`='Mis hombres hablan muy bien de ese tal Nurong. Será un honor conocerlo.' WHERE `ID`=61921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매사냥꾼 누롱 님 말씀이시죠?', `FemaleText_loc4`='是鹰眼大师砮荣吗？', `FemaleText_loc5`='你們所指的是鷹大師砮龍嗎?', `FemaleText_loc7`='¿Entonces será el maestro de halcones Nurong?' WHERE `ID`=61922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 너 예쁜 걸 아주 많이 갖고 있구나! 얼른 내놔!', `MaleText_loc4`='噢，你身上有这么多好东西可以偷呀！给我！', `MaleText_loc5`='喔喔喔，你有好多漂亮東西可以偷!給我!', `MaleText_loc7`='¡Uoooh! ¡Tienes muchas cosas bonitas que robar! ¡Dame cosas!' WHERE `ID`=61923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='못된 것...', `MaleText_loc4`='小气鬼……', `MaleText_loc5`='壞傢伙...', `MaleText_loc7`='$GTacaño:Tacaña;...' WHERE `ID`=61924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라오친, 그러면 증오의 샤를 사냥하는 데 합세하게나. 부하들은 자네 없이도 다리를 수비하고 야영지를 정비할 수 있을 걸세.', `MaleText_loc4`='你会和我们一起猎杀恨之煞的，对吧，老陈。你的人应该能独自守住大桥，并修缮营地。', `MaleText_loc5`='老秦，你要加入我們追捕仇恨之煞的行動。這裡的人應該有辦法守住橋樑並自己修復營地。', `MaleText_loc7`='Debes unirte a nuestra caza del Sha del odio, Lao-Chen. Tus hombres son capaces de defender el puente y reparar el campamento solos.' WHERE `ID`=61925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 맹주님의 명령에 따르겠습니다.', `MaleText_loc4`='当然。我任你差遣，祝掌门。', `MaleText_loc5`='當然。我的人就是你的人，祝宗主。', `MaleText_loc7`='Por supuesto. Mi bastón te pertenece, lord Zhu.' WHERE `ID`=61926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리 쪽 일은 잘 해결됐나 보군?', `MaleText_loc4`='看来你们在大桥的战斗中打了胜仗？', `MaleText_loc5`='我想你在橋那裡應該很成功吧?', `MaleText_loc7`='¿Entonces tuvieron éxito en el puente?' WHERE `ID`=61927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 제 새 친구가 맹활약을 펼쳐 줬습니다!', `MaleText_loc4`='没错。我新朋友的表现令人震惊！', `MaleText_loc5`='我們是很成功。我這位新朋友的表現令人震驚!', `MaleText_loc7`='Así es. ¡Mi camarada se desempeñó de maravilla!' WHERE `ID`=61928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇네. 마지막 전투가 벌어지면 그 친구의 석궁 솜씨가 필요할 걸세.', `MaleText_loc4`='是的。在最后的战斗到来时，我们需要他这样的神箭手。', `MaleText_loc5`='是的，當最後一戰來臨時我們需要他對弩的專業技巧。', `MaleText_loc7`='Sí. Cuando llegue el momento, nos hará falta su pericia con la ballesta.' WHERE `ID`=61929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 지내는 걸 보니 반갑군, 런싸이. 우리는 매사냥꾼 누롱을 찾아왔네. 어디 있나?', `MaleText_loc4`='看到你很高兴，任塞。我们是来这儿找鹰眼大师砮荣的。在哪儿能找到他？', `MaleText_loc5`='任賽，見到你沒事真好。我們是為了鷹大師砮龍而來。我們要到哪找他?', `MaleText_loc7`='Me alegro de verte, Rensai. Venimos por el maestro de halcones Nurong. ¿Dónde está?' WHERE `ID`=61931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 타란 주 님. 그는 천리감시 전망대에서 제 부하들과 적 공격을 방어하고 있습니다.', `MaleText_loc4`='很高兴见到你，祝掌门。他和我剩下的人在远戍哨站坚守。', `MaleText_loc5`='幸會，祝宗主。他跟我其他部下在一起，守著遠眺者瞰臺的防線。', `MaleText_loc7`='Saludos, lord Zhu. Está con el resto de mis hombres, defendiendo el Alto de Vigilancia.' WHERE `ID`=61932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리감시 전망대? 협곡 아래에 사마귀 놈들이 있다는 보고는 못 들었는데.', `MaleText_loc4`='远戍哨站？我没听到报告说下面的沟里有螳螂妖。', `MaleText_loc5`='遠眺者瞰臺?我沒聽說下面的裂口傳來有關螳螂人的報告。', `MaleText_loc7`='¿El Alto de Vigilancia? No me han informado de la presencia de mántides en la sima.' WHERE `ID`=61933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='협곡이 아니라 하늘입니다. 놈들이 수도 없이 몰려오고 있습니다.', `MaleText_loc4`='不，不是沟里。它们会飞。数量庞大，前所未见。', `MaleText_loc5`='不，不是在裂口，是在空中。數量之多前所未見。', `MaleText_loc7`='No, no están en la sima. Son voladores. Más de los que hemos visto jamás.' WHERE `ID`=61935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스, 증오의 샤가 가까이 있네. 찾아서 내게 보고하게나.', `MaleText_loc4`='陶矢，恨之煞就在附近。找到它，回来跟我报告。', `MaleText_loc5`='陶氏，仇恨之煞很接近了。找到它，然後向我回報。', `MaleText_loc7`='Taoshi, el Sha del odio está cerca. Encuéntralo e infórmame.' WHERE `ID`=61936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상하군요... 이놈은 매끈한 돌 조각을 몇 개 지니고 있습니다.', `MaleText_loc4`='奇怪……这个家伙带着一些打磨过的石头。', `MaleText_loc5`='奇怪...這傢伙帶著幾片磨光的石片。', `MaleText_loc7`='Es extraño... Tiene trozos de piedras pulidas.' WHERE `ID`=61938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망 사항일 뿐이지만, 니우짜오의 조각상에서 떨어진 거였으면 좋겠군요.', `MaleText_loc4`='希望它们来自砮皂的雕像。我们只能祈祷了。', `MaleText_loc5`='但願它們來自於怒兆的雕像，我們只能這麼希望。', `MaleText_loc7`='Con suerte, provendrán de la estatuilla de Niuzao. Es nuestra esperanza.' WHERE `ID`=61939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 돌이 나왔습니다... 아까 발견한 돌 조각과 맞아떨어지는군요.', `MaleText_loc4`='另一块石头……它的标记和我们找到的其他石头上的标记比较相符。', `MaleText_loc5`='另一塊石頭...它跟我們找到的其他標記吻合。', `MaleText_loc7`='Otra piedra... y tiene las mismas marcas que el resto que encontramos.' WHERE `ID`=61940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='답에 가까워지고 있는 것 같습니다, $p. 계속 살펴봅시다.', `MaleText_loc4`='我想我们很快就会有所发现了，$p。继续在周围找找。', `MaleText_loc5`='$p，我覺得我們找對地方了。我們繼續四處找找看吧。', `MaleText_loc7`='Creo que estamos acercándonos a algo, $p. Sigue buscando.' WHERE `ID`=61941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 아무것도 몰랐다면, 이게 돌로 된 쇠꼬리인 줄 알았을 겁니다.', `MaleText_loc4`='如果我没记错的话，这应该是根石牛尾。', `MaleText_loc5`='不知情的話，我會說這是條石牛尾巴。', `MaleText_loc7`='Si tuviese que decir algo, diría que esto era una cola de buey de piedra.' WHERE `ID`=61942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 머리만 찾으면 되는군요. 멀리 있지는 않을 겁니다.', `MaleText_loc4`='现在只剩下头了，它应该在不远的地方。', `MaleText_loc5`='現在只剩下頭部了，它應該就在不遠處。', `MaleText_loc7`='Todo lo que queda ahora es la cabeza. Y no puede estar muy lejos.' WHERE `ID`=61943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리를 찾았습니다. 완벽하게 맞아 들어가는군요.', `MaleText_loc4`='头在这儿。装起来也刚刚好。', `MaleText_loc5`='這是頭部，完全吻合。', `MaleText_loc7`='Aquí está la cabeza. Y también encaja a la perfección.' WHERE `ID`=61944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니우짜오 님이 맡기신 일을 완수했군요. 이제 다시 진짜 조사를 시작해야겠습니다.', `MaleText_loc4`='我们已经完成了砮皂的差事。现在得回去做一些真正的调查了。', `MaleText_loc5`='我們已經履行了怒兆的差事，現在是時候回去做些真正的調查工作了。', `MaleText_loc7`='Ya hemos hecho el recado de Niuzao. Ahora es el momento de realizar una investigación de verdad.' WHERE `ID`=61945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랜치의 원기회복의 비약 안에 서 있으면 생명력과 마나가 회복됩니다!', `MaleText_loc4`='站在布兰琪的恢复药剂中可恢复生命值和法力值！', `MaleText_loc5`='站在白蘭琪的回復藥劑中，以回復生命值與法力值!', `MaleText_loc7`='¡Colócate sobre el elixir de reabastecimiento de Clara para recuperar salud y maná!', `FemaleText_loc1`='블랜치의 원기회복의 비약 안에 서 있으면 생명력과 마나가 회복됩니다!', `FemaleText_loc4`='站在布兰琪的恢复药剂中可恢复生命值和法力值！', `FemaleText_loc5`='站在白蘭琪的回復藥劑中，以回復生命值與法力值!', `FemaleText_loc7`='¡Colócate sobre el elixir de reabastecimiento de Clara para recuperar salud y maná!' WHERE `ID`=61946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천리감시 전망대를 도와주고, 누롱을 다시 이리 데려오게나. 마지막 결전의 시기가 아주 빨리 다가오는군.', `MaleText_loc4`='$p，去远戍哨站帮忙，然后把砮荣带回来。决战在即，刻不容缓。', `MaleText_loc5`='$p，到遠眺者瞰臺去幫忙，並把砮龍帶回我們這兒來。最後的戰役就要展開。', `MaleText_loc7`='Ayuda en el Alto de Vigilancia y trae de vuelta a Nurong. El enfrentamiento final se acerca sin demora.' WHERE `ID`=61947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 준비해! 포격 준비... 발사!', `MaleText_loc4`='装弹！预备……瞄准……开火！', `MaleText_loc5`='充填大砲!準備...瞄準...發射!', `MaleText_loc7`='¡Armen los cañones! Preparen... apunten... ¡fuego!' WHERE `ID`=61948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여리고 약한 놈들!', `MaleText_loc4`='他们太软弱了！', `MaleText_loc5`='他們很軟弱!', `MaleText_loc7`='¡Son blandos y débiles!' WHERE `ID`=61949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언덕으로 후퇴...!', `MaleText_loc4`='退回山里去！', `MaleText_loc5`='撤退到山丘那裡!', `MaleText_loc7`='¡Retírense a las colinas!' WHERE `ID`=61950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 시체를 가져와라!', `MaleText_loc4`='把他们的尸体带回来！', `MaleText_loc5`='把他們的屍體帶給我!', `MaleText_loc7`='¡Tráiganme sus cadáveres!' WHERE `ID`=61951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 위로요! 도움이 필요합니다!', `MaleText_loc4`='$c，在这儿！我需要帮手！', `MaleText_loc5`='$C，在這裡!我需要你幫忙!', `MaleText_loc7`='¡Aquí arriba! ¿Me puedes dar una mano?' WHERE `ID`=61952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훔치고 강탈하라, 음화화화화!', `MaleText_loc4`='抢呀，杀呀，啊哈哈哈哈！', `MaleText_loc5`='燒殺擄掠，哇哈哈哈!', `MaleText_loc7`='¡Saqueo y rapiña, ja, ja, ja!' WHERE `ID`=61953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 떼가 접근 중입니다! 제 대포를 맡으십시오! 어서요!', `MaleText_loc4`='一大群飞行兵冲过来了！拿上我的火炮，$c，动作快！', `MaleText_loc5`='另一波飛行物接近了!!$c，拿起我的大砲，快!', `MaleText_loc7`='¡Se acerca una oleada de enemigos voladores! ¡Rápido, toma mi cañón!' WHERE `ID`=61954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게... 저게 뭡니까? 저게 정말 날아서 넘어오는 겁니까?', `MaleText_loc4`='那……那是什么？它真打算飞过去吗？', `MaleText_loc5`='那...那是什麼東西?它真的想要飛過來嗎?', `MaleText_loc7`='¿Qué... qué es eso? ¿De veras va a cruzar volando?' WHERE `ID`=61955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까워지고 있습니다! 쏴 버리십시오!', `MaleText_loc4`='它靠近了！把它击落！', `MaleText_loc5`='它飛過來了!把它射下來!', `MaleText_loc7`='¡Se está acercando! ¡Derríbalo! ¡Ahora!' WHERE `ID`=61956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 이제 내려가서 끝을 봅시다.', `MaleText_loc4`='干得漂亮！我们降到那边，准备收工。', `MaleText_loc5`='做得好!我們下去把它解決吧。', `MaleText_loc7`='¡Buen trabajo! Bajemos para acabar con él.' WHERE `ID`=61957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등 뒤 껍질에 틈이 있습니다. 그곳을 공격하십시오!', `MaleText_loc4`='它背部的壳裂开了。哪儿疼打哪儿！', `MaleText_loc5`='它背後的殼破了，攻擊破裂的地方!', `MaleText_loc7`='Tiene el caparazón roto por atrás. ¡Dale donde le duele!' WHERE `ID`=61958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤에서 공격하면 더 효과적일 겁니다.', `MaleText_loc4`='从背后攻击事半功倍。', `MaleText_loc5`='從背後攻擊會更有效。', `MaleText_loc7`='Los ataques por la espalda serán más efectivos.' WHERE `ID`=61959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 주의를 끌었습니다! 온 힘을 다해 공격하십시오!', `MaleText_loc4`='我吸引了它的注意！全力攻击！', `MaleText_loc5`='我吸引到它的注意力了!火力全開!', `MaleText_loc7`='¡Yo lo distraigo! ¡Ataca con todas tus fuerzas!' WHERE `ID`=61960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 저를 노립니다. 뒤로 가서 온 힘을 다해 공격하십시오!', `MaleText_loc4`='它在追我，绕到它后边去，使出全力攻击它！', `MaleText_loc5`='現在它跟在我後面了，繞到它後面去，盡你所能攻擊它!', `MaleText_loc7`='Viene a por mí. ¡Ve por detrás y hazle todo el daño que puedas!' WHERE `ID`=61961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈레온의 등에 타고 있던 전사들이 뛰어내려 전투에 참여합니다!', `MaleText_loc4`='好战者从炮舰上跳下来，加入了战斗！', `MaleText_loc5`='好戰者從帆船後面跳出來加入戰場!', `MaleText_loc7`='¡Los belicistas saltan del lomo de Galeón y se unen a la batalla!' WHERE `ID`=61962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하더라도 공격당하면 안 됩니다!', `MaleText_loc4`='不管你做什么，别让它击中你！', `MaleText_loc5`='不管你怎麼做，別讓它碰到你就對了!', `MaleText_loc7`='Pase lo que pase, ¡que no te golpee!' WHERE `ID`=61963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warstomp.blp:20|t 갈레온이 |cFFFF0000|Hspell:121787|h[발 구르기]|h|r를 하려고 합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warstomp.blp:20|t炮舰即将施放|cFFFF0000|Hspell:121787|h[践踏]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warstomp.blp:20|t帆船將要|cFFFF0000|Hspell:121787|h[劇烈晃動]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warstomp.blp:20|t¡Galeón se dispone a realizar un |cFFFF0000|Hspell:121787|h[Pisotón]|h|r!' WHERE `ID`=61964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 노립니다! 어서 도망치십시오.', `MaleText_loc4`='它在追你！别让它接近。', `MaleText_loc5`='它就跟在你後面!別讓它接近。', `MaleText_loc7`='¡Va a por ti! No dejes que se acerque.' WHERE `ID`=61965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t 갈레온이 |cFFFF0000|Hspell:121600|h[대포 포화]|h|r를 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t炮舰即将施放|cFFFF0000|Hspell:121600|h[火炮弹幕]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t帆船準備發射|cFFFF0000|Hspell:121600|h[火砲彈幕]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_vehicle_siegeenginecannon.blp:20|t¡Galeón se prepara para lanzar una |cFFFF0000|Hspell:121600|h[Tromba de cañón]|h|r!' WHERE `ID`=61966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기절했습니다. 이번에 끝내버립시다!', `MaleText_loc4`='它晕了。现在是消灭它的好机会！', `MaleText_loc5`='它無法行動了，現在是解決它的好時機!', `MaleText_loc7`='Está aturdido. ¡Es nuestra oportunidad para matarlo!' WHERE `ID`=61967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고수시군요.', `MaleText_loc4`='厉害。', `MaleText_loc5`='做得漂亮。', `MaleText_loc7`='Brillante.' WHERE `ID`=61968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 싸워서 영광입니다.', `MaleText_loc4`='很荣幸能与你并肩作战。', `MaleText_loc5`='我很榮幸能與你一起戰鬥。', `MaleText_loc7`='Me enorgullece luchar a tu lado.' WHERE `ID`=61969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님께서 부르시는 거라면 서두르는 게 좋겠습니다. 어서 가시죠.', `MaleText_loc4`='要是祝掌门想见我们，最好别让他等太久。出发吧。', `MaleText_loc5`='如果祝宗主要找我們，我們最好別讓他等太久。我們走吧。', `MaleText_loc7`='Si lord Zhu preguntó por mí, no debemos hacerlo esperar. Vamos.' WHERE `ID`=61970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느낌이 좋지 않습니다.', `MaleText_loc4`='这个地方看起来不太好。', `MaleText_loc5`='這看起來不是個好地方。', `MaleText_loc7`='Este sitio no tiene buena pinta.' WHERE `ID`=61971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오의 샤가 숨은 곳을 찾아냈네.', `MaleText_loc4`='我们已经找到恨之煞的藏身之地了。', `MaleText_loc5`='我們已經找到仇恨之煞的藏身之處。', `MaleText_loc7`='Hemos encontrado el escondite del Sha del odio.' WHERE `ID`=61972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, 누롱. 함께하게 되어 기쁘네.', `MaleText_loc4`='欢迎，砮荣。有你加入真不错。', `MaleText_loc5`='歡迎你，砮龍。很高興有你的加入。', `MaleText_loc7`='Bienvenido, Nurong. Es bueno que estés con nosotros.' WHERE `ID`=61973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다... 틀림없습니다. 이 길이 맞습니다.', `MaleText_loc4`='是的……应该就是这里了。我们走对路了。', `MaleText_loc5`='沒錯...這一定就是了。我們走的是正確的路。', `MaleText_loc7`='Sí... Esto debe ser. Vamos en la dirección correcta.' WHERE `ID`=61974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 갈까요? 위로, 아니면 아래로?', `MaleText_loc4`='往哪个方向走？往上，还是往下？', `MaleText_loc5`='要走哪條路?往上還是往下?', `MaleText_loc7`='¿Por dónde vamos? ¿Hacia arriba o hacia abajo?' WHERE `ID`=61975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴집니까, $p? 이곳이 공포의 샤가 잡혀 있던 곳입니다.', `MaleText_loc4`='你能感觉到吗，$p？这就是惧之煞的藏身之处。', `MaleText_loc5`='$p，你感覺到了嗎?這就是恐懼之煞被封住的地方。', `MaleText_loc7`='¿Lo sientes, $p? Aquí es donde tenían al Sha del miedo.' WHERE `ID`=61976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침착하십시오, $p. 공포를 생각하지 말고, 목표를 생각하십시오.', `MaleText_loc4`='保持冷静，$p。把注意力集中在你的目标上，不要去想你的恐惧。', `MaleText_loc5`='冷靜點，$p。專注於你的目標，而非恐懼。', `MaleText_loc7`='$GTranquilo:Tranquila;, $p. Céntrate en tu objetivo, y no en tus temores.' WHERE `ID`=61977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바라시는 대로 그 유물을 찾도록 하지요. $p, 스라티크 습격지에서 만납시다.', `MaleText_loc4`='如你所愿，我们会找到你的神器的。$p——我会在瑟拉提克入侵地与你会合。', `MaleText_loc5`='如你所願，我們會找到你要的雕像。$p，我跟你在斯拉席克侵略哨站碰頭。', `MaleText_loc7`='Como desees. Encontraremos tu artefacto. $p, te veré en la Incursión de Sra''thik.' WHERE `ID`=61978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 제가 보여드릴게요.', `FemaleText_loc4`='来，$p，我指给你看。', `FemaleText_loc5`='來，$p，你來看看這個。', `FemaleText_loc7`='Ven, te mostraré.' WHERE `ID`=61979;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='망원경으로 보세요.', `FemaleText_loc4`='透过望远镜看。', `FemaleText_loc5`='用望遠鏡去看。', `FemaleText_loc7`='Mira por el catalejo.' WHERE `ID`=61980;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='증오의 샤가 저 사마귀집 안에 있어요... 거기 있는 강력한 숙주에게 끌린 것 같군요.', `FemaleText_loc4`='恨之煞就在那个螳螂妖建筑里……我猜想它是被一个强大的寄主吸引过去的。', `FemaleText_loc5`='仇恨之煞在那螳螂人的建築裡...我懷疑它被那裡的強大宿主吸引。', `FemaleText_loc7`='El Sha del odio está dentro de esa estructura mántide... Sospecho que buscaba un poderoso anfitrión.' WHERE `ID`=61981;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사마귀집으로 들어가려면, 이 주변의 사마귀 지휘관들이 가진 수정이 필요해요.', `FemaleText_loc4`='要想进去，得从这儿的螳螂妖头领身上找到经过特殊转化的水晶。', `FemaleText_loc5`='為了進去，我們需要從這地區的螳螂人頭目身上取得特別的調諧水晶。', `FemaleText_loc7`='Para entrar, necesitaremos cristales sintonizados de algunos de los líderes mántides de la zona.' WHERE `ID`=61982;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지휘관들 위치는 여기...', `FemaleText_loc4`='那些头领在这儿……', `FemaleText_loc5`='這些頭目的位置在這裡...', `FemaleText_loc7`='Localicé a los líderes aquí…' WHERE `ID`=61983;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기...', `FemaleText_loc4`='这儿……', `FemaleText_loc5`='這裡...', `FemaleText_loc7`='... aquí...' WHERE `ID`=61984;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 여기예요.', `FemaleText_loc4`='还有这儿。', `FemaleText_loc5`='還有這裡...', `FemaleText_loc7`='... y aquí.' WHERE `ID`=61985;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 처치해서 수정을 획득하세요. 어렵진 않을 거예요.', `FemaleText_loc4`='杀掉他们，夺取水晶。就这么简单。', `FemaleText_loc5`='殺了他們，取走水晶。這應該夠簡單了。', `FemaleText_loc7`='Mátenlos y quítenles los cristales. No debería ser muy difícil.' WHERE `ID`=61986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 오시오, $r. 이야기하고 싶은 게 있소. 더는 우리의 비밀을 지킬 수 없게 되었군.', `MaleText_loc4`='过来，$r，我想和你谈谈。我们的秘密再也藏不住了。', `MaleText_loc5`='$r，過來這裡。我想跟你聊聊。我們的秘密藏不了太久。', `MaleText_loc7`='Ven, $r. Quiero hablar contigo. Ya no podemos ocultar nuestro secreto.' WHERE `ID`=61987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각대로군요. 감사합니다, 오고 부자여. $p, 지하묘지에서 만납시다.', `MaleText_loc4`='跟我想的一样。谢谢你，奥戈斯。$p——我会到墓穴与你会合。', `MaleText_loc5`='就跟我懷疑的一樣。謝謝你，奧苟。$p，我會跟你在墓穴碰頭。', `MaleText_loc7`='Tal y como sospechaba. Gracias, Ogos. $p, te veré en las catacumbas.' WHERE `ID`=61988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스, 라오친, 누롱, 모두 임무를 수행하게. 각자 자리를 잡고 우리 신호를 기다리도록.', `MaleText_loc4`='陶矢、老陈、砮荣，你们都已分配好各自的任务。到指定地点准备，等我们的信号。', `MaleText_loc5`='陶氏，老秦，砮龍，你們都領到任務了。在各自的地點準備好，等候我們的訊號。', `MaleText_loc7`='Taoshi, Lao-Chen, Nurong, ya tienen asignadas sus misiones. Ubíquense en sus posiciones y esperen la señal.' WHERE `ID`=61989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스, 족쇄와 반지를 가져왔나?', `MaleText_loc4`='陶矢，你带镣铐和扣环了吗？', `MaleText_loc5`='陶氏，你有帶鐐銬跟戒指來嗎?', `MaleText_loc7`='Taoshi, ¿tienes los grilletes y los anillos?' WHERE `ID`=61990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련 내용을 기억하게. 증오에 굴복하지 않는다면 살아남을 걸세.', `MaleText_loc4`='要记住你们训练时学到的东西。如果想活命，就别屈服于仇恨。', `MaleText_loc5`='記住你受的訓練。只要你不屈服於仇恨，就能活著出來。', `MaleText_loc7`='Recuerden su adiestramiento. Mientras no nos rindamos al odio, saldremos de esta con vida.' WHERE `ID`=61991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전과 마찬가지입니다. 당신이 적을 처치하면 제가 수색하지요.', `MaleText_loc4`='和以前的做法一样。你去杀，我来找。', `MaleText_loc5`='進行方式跟以前一樣。你負責獵殺，我負責搜索。', `MaleText_loc7`='Lo mismo que antes. Tú matas y yo busco.' WHERE `ID`=61993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느낌이 좋지 않군요. 들어갑시다, $n.', `MaleText_loc4`='这个地方看起来真恶心。来，$n。我们到里面去。', `MaleText_loc5`='這地方看起來不大好惹。來吧，$n。我們進去。', `MaleText_loc7`='Este lugar no tiene buena pinta. Vamos, $n. Vayamos dentro.' WHERE `ID`=61994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들에게 자네가 도착하기 전까지 공격을 대기하라고 지시했네. 늦지 말게나.', `MaleText_loc4`='$p，我已经命令我的人等你们到了再发动进攻。不要拖延。', `MaleText_loc5`='$p，我的人已接獲指示，等你們抵達再攻擊。別遲到了。', `MaleText_loc7`='He ordenado a mis hombres que aguarden tu llegada antes de atacar. No te retrases.' WHERE `ID`=61995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 수정을 가지고 있나?', `MaleText_loc4`='你们每个人都拿到水晶了吗？', `MaleText_loc5`='你們都有水晶嗎?', `MaleText_loc7`='¿Cada uno tiene los cristales?' WHERE `ID`=61997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네.', `FemaleText_loc4`='是。', `FemaleText_loc5`='是的。', `FemaleText_loc7`='Sí.' WHERE `ID`=61998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예.', `MaleText_loc4`='是的。', `MaleText_loc5`='嗯。', `MaleText_loc7`='Sí.' WHERE `ID`=61999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네.', `MaleText_loc4`='是的。', `MaleText_loc5`='是的。', `MaleText_loc7`='Sí.' WHERE `ID`=62000;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠습니다, 맹주님.', `FemaleText_loc4`='是……祝掌门。', `FemaleText_loc5`='...是的，祝宗主。', `FemaleText_loc7`='... Sí, lord Zhu.' WHERE `ID`=62001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가세.', `MaleText_loc4`='出发。', `MaleText_loc5`='我們走吧。', `MaleText_loc7`='Adelante.' WHERE `ID`=62002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다가와라, 약자들아... 너희의 최후와 맞서 봐라!', `MaleText_loc4`='来吧，羔羊们……来面对死亡吧！', `MaleText_loc5`='來吧，小羊們...過來面對你們的滅亡!', `MaleText_loc7`='Vengan, corderos... ¡vengan y enfrenten la muerte!' WHERE `ID`=62004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 안에 증오가 있는 한, 넌 내 사냥감이다. 넌 이미 내 거야.', `MaleText_loc4`='当仇恨驱使你们来猎杀我时，你们就已经输了。', `MaleText_loc5`='你心裡的恨意促使你來獵殺我。你已經屬於我了。', `MaleText_loc7`='El odio de su interior es lo que los ha conducido hasta aquí. Ya son míos.' WHERE `ID`=62005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기해라. 저항하면 할수록 네 안의 증오가 끓어오를 테니.', `MaleText_loc4`='放弃吧。你越是奋战，心中的仇恨就愈发的炽热。', `MaleText_loc5`='放棄吧。你越抗拒，你心裡的恨意就越激昂。', `MaleText_loc7`='Ríndanse. Mientras más luchen, más alimentarán el odio de su corazón.' WHERE `ID`=62006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블랜치가 근처에 아군이 없음을 알고 후퇴합니다!', `MaleText_loc4`='布兰琪发现附近没有盟友，因此撤退了！', `MaleText_loc5`='白蘭琪察覺附近已沒有盟友，於是撤退了!', `MaleText_loc7`='¡Clara nota que ya no hay aliados cerca y se retira!', `FemaleText_loc1`='블랜치가 근처에 아군이 없음을 알고 후퇴합니다!', `FemaleText_loc4`='布兰琪发现附近没有盟友，因此撤退了！', `FemaleText_loc5`='白蘭琪察覺附近已沒有盟友，於是撤退了!', `FemaleText_loc7`='¡Clara nota que ya no hay aliados cerca y se retira!' WHERE `ID`=62007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 빈사 상태입니다!', `MaleText_loc4`='你差点就死了！', `MaleText_loc5`='你快死了!', `MaleText_loc7`='¡Ya casi estás $gmuerto:muerta;!', `FemaleText_loc1`='당신은 빈사 상태입니다!', `FemaleText_loc4`='你差点就死了！', `FemaleText_loc5`='你快死了!', `FemaleText_loc7`='¡Ya casi estás $gmuerto:muerta;!' WHERE `ID`=62008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날바람 킬루크, 깨어났구나. 클락시바 티크는 어디 있나?', `MaleText_loc4`='掠风者。你醒了。卡拉克西瓦·提克呢？', `MaleText_loc5`='奪風者。你醒了。卡拉西瓦·提克呢?', `MaleText_loc7`='Atracavientos, has despertado. ¿Qué hay del Klaxxi''va Tik?' WHERE `ID`=62009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 뭐지? 성역에 저런 쓰레기를 데려오다니.', `MaleText_loc4`='你给我们的圣地带来了什么脏东西？', `MaleText_loc5`='你帶進我們聖堂的是什麼汙穢的生物?', `MaleText_loc7`='¿Qué es esta escoria que has traído a nuestro santuario?' WHERE `ID`=62010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 찾아온 클락시바는 여제의 수하에게 당하고 말았습니다.', `MaleText_loc4`='你派出的卡拉克西瓦已经沦为女皇的仆从。', `MaleText_loc5`='你派去的卡拉西瓦已死在女皇爪牙的手下啦。', `MaleText_loc7`='El Klaxxi''va que enviaste ha caído ante un súbdito de su majestad.' WHERE `ID`=62011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 쓰레기가, 여제의 수하를 처치하고 저를 깨워 줬습니다.', `MaleText_loc4`='这个……你所谓的“脏东西”击败了那仆从，还唤醒了我。', `MaleText_loc5`='這個...「髒東西」擊敗了女皇的手下，並見證我的覺醒。', `MaleText_loc7`='Esta... "escoria" derrotó al súbdito y me despertó.' WHERE `ID`=62012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열등한 종족의 도움 따윈 필요 없다! 당장 치워 버려!', `MaleText_loc4`='我们不需要低贱种族的帮助！干掉它！', `MaleText_loc5`='我們不需要下等種族的幫忙!把他趕出去!', `MaleText_loc7`='¡No necesitamos la ayuda de razas inferiores! ¡Deshazte de eso!' WHERE `ID`=62013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리하겠습니다, 클락시바.', `MaleText_loc4`='马上，卡拉克西瓦。', `MaleText_loc5`='遵命，卡拉西瓦。', `MaleText_loc7`='Ahora mismo, Klaxxi''va.' WHERE `ID`=62014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 더 도전합시다!', `MaleText_loc4`='让我们再给他一下子！', `MaleText_loc5`='我們再試一次!', `MaleText_loc7`='¡Vamos a intentarlo otra vez!', `FemaleText_loc1`='한 번 더 도전해 봐요!', `FemaleText_loc4`='让我们再给他一下子！', `FemaleText_loc5`='我們再試一次!', `FemaleText_loc7`='¡Vamos a intentarlo otra vez!' WHERE `ID`=62015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니다.', `MaleText_loc4`='不。', `MaleText_loc5`='不。', `MaleText_loc7`='No.' WHERE `ID`=62016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자가 쓸모 있을지도 모르지. 어떤 식으로든.', `MaleText_loc4`='唤醒者也许会有用武之地。不论是以哪种方式。', `MaleText_loc5`='喚醒者也許能派上用場。不論是用哪種方法。', `MaleText_loc7`='Es posible que el heraldo nos sea útil. De una forma u otra.' WHERE `ID`=62017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 죽어 가고 있습니다!', `MaleText_loc4`='你要死了！', `MaleText_loc5`='你快死了!', `MaleText_loc7`='¡Te mueres!', `FemaleText_loc1`='당신은 죽어 가고 있습니다!', `FemaleText_loc4`='你要死了！', `FemaleText_loc5`='你快死了!', `FemaleText_loc7`='¡Te mueres!' WHERE `ID`=62018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 빈사 상태입니다!', `MaleText_loc4`='你就快死了！', `MaleText_loc5`='你快死了!', `MaleText_loc7`='¡Estás cerca de la muerte!', `FemaleText_loc1`='당신은 빈사 상태입니다!', `FemaleText_loc4`='你就快死了！', `FemaleText_loc5`='你快死了!', `FemaleText_loc7`='¡Estás cerca de la muerte!' WHERE `ID`=62019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 죽기 직전입니다!', `MaleText_loc4`='你濒临死亡！', `MaleText_loc5`='你幾乎快死了!', `MaleText_loc7`='¡Estás casi $gmuerto:muerta;!', `FemaleText_loc1`='당신은 죽기 직전입니다!', `FemaleText_loc4`='你濒临死亡！', `FemaleText_loc5`='你幾乎快死了!', `FemaleText_loc7`='¡Estás casi $gmuerto:muerta;!' WHERE `ID`=62020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽지 마십시오!', `MaleText_loc4`='别死！', `MaleText_loc5`='別死啊!', `MaleText_loc7`='¡No te mueras!', `FemaleText_loc1`='죽지 마십시오!', `FemaleText_loc4`='别死！', `FemaleText_loc5`='別死啊!', `FemaleText_loc7`='¡No te mueras!' WHERE `ID`=62021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너의 모든 것을 짓밟아주마!', `MaleText_loc4`='我要摧毁你们拥有的一切！', `MaleText_loc5`='你的一切都會由我來消滅!', `MaleText_loc7`='¡Todo lo que son es MÍO y lo puedo destruir!' WHERE `ID`=62022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박날개가 날아온다, 조심해!', `MaleText_loc4`='琥珀之翼飞进来了，小心！', `MaleText_loc5`='琥珀之翼要飛進來了，小心!', `MaleText_loc7`='¡El alacárabe vuela hacia aquí! ¡Cuidado!' WHERE `ID`=62023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사마귀가 숙주군. 잡고 있게나. 놈에게서 증오를 몰아내야겠네!', `MaleText_loc4`='那个螳螂妖就是它的宿主。用锁链锁住它，逼出恨之煞！', `MaleText_loc5`='那隻螳螂人是宿主。把他鍊起來，我們會把仇恨從他的身體扯離!', `MaleText_loc7`='El mántide es su anfitrión. Encadenadlo. ¡Le arrancaremos el odio del cuerpo!' WHERE `ID`=62024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴병이 폭발물을 갖고 있어! 다가오기 전에 날려버려!', `MaleText_loc4`='毁灭者身上有炸药。直接攻击会导致他们自爆！', `MaleText_loc5`='石毀者帶著炸藥!直接攻擊會造成爆炸!', `MaleText_loc7`='¡Los más rápidos llevan bombas! ¡Cualquier ataque directo los hará estallar!' WHERE `ID`=62025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀를 막게! 오래 걸리지는 않을 걸세.', `MaleText_loc4`='控制住螳螂妖！这不会要太多时间。', `MaleText_loc5`='拖住這隻螳螂人!這不會花太多時間的。', `MaleText_loc7`='¡Sujeten al mántide! No tomará mucho tiempo.' WHERE `ID`=62026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀를 막게! 거의 다 됐네.', `MaleText_loc4`='挡住螳螂妖！我们就快完成了。', `MaleText_loc5`='繼續逼迫這隻螳螂人!我們快完成了。', `MaleText_loc7`='¡Contengan al mántide! Casi terminamos.' WHERE `ID`=62027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오여, 이리 나와 패배를 맞이하라!', `MaleText_loc4`='恨之煞，出来受死吧！', `MaleText_loc5`='仇恨啊，出來面對你的失敗!', `MaleText_loc7`='¡Odio! ¡Sal y enfréntate a la derrota!' WHERE `ID`=62028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파여, 때가 왔다! 너희들은 오직 이 순간을 위해 훈련해온 거다!', `MaleText_loc4`='该你们上场了，影踪派的勇士们！养兵千日，用兵一时！', `MaleText_loc5`='影潘，該是你們表現的時候了!你們所受的訓練就是為了這一刻!', `MaleText_loc7`='¡Este es su momento, Shadopan! ¡Para esto los han entrenado!' WHERE `ID`=62029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주, 정말 어리석구나. 내게서 도망치더니 이젠 끓어오르는 증오로 가득 차 돌아왔군. 넌... 이제... 내 거다!', `MaleText_loc4`='祝踏岚，你多么愚蠢。你逃出了我的手心，却带着满腔的仇恨。你……是……我的！', `MaleText_loc5`='塔蘭·祝，你太愚蠢了。你逃離了我，卻帶著滿心滋長的恨意回來。你...是...我的了!', `MaleText_loc7`='Taran Zhu, eres un necio. Huiste de mí solo para volver con el odio hirviendo en tu interior. Eres... MÍO.' WHERE `ID`=62030;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='족쇄! 바로 지금!', `FemaleText_loc4`='用镣铐，快！', `FemaleText_loc5`='禁錮他，就是現在!', `FemaleText_loc7`='¡Los grilletes! ¡YA!' WHERE `ID`=62031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 무리의 먹이로 쓸 수는 있겠지.', `MaleText_loc4`='或许，可以成为虫群的食物！', `MaleText_loc5`='替蟲群當砲灰，也許有用...', `MaleText_loc7`='Carne de cañón, como mucho…' WHERE `ID`=62032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사원에는 무슨 일로 왔소, $r?', `MaleText_loc4`='是什么风把你吹到这儿来的，$r？', `MaleText_loc5`='$r，什麼風把你吹到我們的寺廟來了?', `MaleText_loc7`='¿Qué te trae a nuestro templo, $r?' WHERE `ID`=62033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 이곳에서 아버지의 발자취를 따른다는 데 자부심을 느낍니다.$b$b아직 끝나지 않은 발자취이지요.', `MaleText_loc4`='我很自豪能在这儿将我父亲的传说延续下去。$b$b补充一句，这是一个不断延续的传说。', `MaleText_loc5`='能在這裡繼續我父親的遺志，我感到很驕傲。$b$b而我得說，是個持續成長的志願。', `MaleText_loc7`='Me enorgullece saber que estoy prosiguiendo el legado de mi padre.$b$bUn legado que no deja de crecer, debería añadir.' WHERE `ID`=62034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지?! 함정인가?', `MaleText_loc4`='这是什么？！一个陷阱？', `MaleText_loc5`='這是什麼?!陷阱?', `MaleText_loc7`='¡¿Qué es esto?! ¿Una trampa?' WHERE `ID`=62035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 움직이지 않고 흔들리지 않는 수호자라네.$b$b우리가 움직일 때는 그 누구도 멈춰 세울 수 없고, 우리가 멈춰 서 있을 때는 누구도 우리를 움직일 수 없지.', `MaleText_loc4`='我们是守护者——既稳若磐石又心如止水。$b$b我们移动时，没有什么东西能阻止我们。我们站定时，没有什么东西能动摇我们。', `MaleText_loc5`='我們是堅定不屈且冷靜自若的保衛者。$b$b一旦我們開始行動，沒有任何事物可以阻擋我們。當我們靜止不動，沒有任何事物可以動搖我們。', `MaleText_loc7`='Somos los protectores: inamovibles e imperturbables. $b$bCuando avanzamos, nada nos detiene. Cuando nos quedamos quietos, nada hace que nos movamos.' WHERE `ID`=62036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영악한 음영파 놈들... 내 너희를 과소평가했구나. 하지만 네 지도자는 내 거다. 날 풀어줘야 놈도 풀려날 수 있지.', `MaleText_loc4`='狡猾的影踪派……我低估了你们。可你们的领袖已经是我的了。谁想要救他，就必须同时释放我。', `MaleText_loc5`='聰明的影潘...我低估你們了。可是你們的領袖在我手裡。你們不解放我，就沒辦法救出他。', `MaleText_loc7`='Bien jugado, Shadopan... Los he subestimado, pero ahora su líder es mío. No pueden liberarlo sin liberarme a mí también.' WHERE `ID`=62037;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 맹주님도 원하신다. 네놈의 속박은 우리의 의무였지. 맹주님도 그 끝을 보실 거다.', `FemaleText_loc4`='这便是他的意愿。我们的职责就是将你封印，而他会见证这一切。', `FemaleText_loc5`='如他所願。我們發過誓要禁錮你，而他會確保我們達成。', `FemaleText_loc7`='Es su voluntad y nuestro deber sagrado encerrarte, y él se encarga de que así sea.' WHERE `ID`=62038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야크가 목축, 노동 따위에나 걸맞은 하찮은 동물이라고 생각하는 이들도 있어요. 흑우의 자손인 야크가 지닌 아름다움을 알아보는 이는 거의 없지요.', `FemaleText_loc4`='有些人认为牦牛是低等动物，只配用来放牧和做一些低贱的劳动。很少有人能看到他们的内在美，那才是这些——玄牛的子嗣——真正拥有的东西。', `FemaleText_loc5`='有些人認為這些犛牛是低等動物，只適合放牧跟粗重勞動。很少有人能看出這些玄牛後裔與生俱來的優美。', `FemaleText_loc7`='Algunos creen que estos yaks son bestias inferiores, solo aptas para el pastoreo y tareas de baja estofa. Pocos son conscientes de la belleza innata que poseen estas criaturas, la prole del Buey Negro.' WHERE `ID`=62039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 희생이 모두에게 힘을 줬습니다.', `MaleText_loc4`='他的牺牲令我们大受鼓舞。', `MaleText_loc5`='他的犧牲激勵了我們。', `MaleText_loc7`='Su sacrificio nos inspira a todos.' WHERE `ID`=62041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 당신 없이는 못 해냈을 거예요.', `FemaleText_loc4`='$p，没有你我们做不到。谢谢你。', `FemaleText_loc5`='$p，沒有你我們做不到。謝謝你。', `FemaleText_loc7`='No podríamos haberlo hecho sin ti. Gracias.' WHERE `ID`=62042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먼저 가세요. 따라갈게요.', `FemaleText_loc4`='该你了，我会跟着你。', `FemaleText_loc5`='你帶頭，我會跟著你進去。', `FemaleText_loc7`='Ve tú primero. Te sigo.' WHERE `ID`=62043;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요.', `FemaleText_loc4`='干得好。', `FemaleText_loc5`='做得好。', `FemaleText_loc7`='Buen trabajo.' WHERE `ID`=62044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 엄호하겠습니다. 준비되면 이동하십시오.', `MaleText_loc4`='我掩护你。等你准备好就出发。', `MaleText_loc5`='我會掩護你，準備好隨時可以行動。', `MaleText_loc7`='Te cubriré. Parte cuando quieras.' WHERE `ID`=62045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 훌륭했습니다!', `MaleText_loc4`='真厉害！', `MaleText_loc5`='太了不起了!', `MaleText_loc7`='¡Impresionante!' WHERE `ID`=62046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께하겠네.', `MaleText_loc4`='我与你同在。', `MaleText_loc5`='我會與你一起行動。', `MaleText_loc7`='Estoy contigo.' WHERE `ID`=62047;
