UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우셨습니다.', `MaleText_loc4`='打得漂亮。', `MaleText_loc5`='打得漂亮。', `MaleText_loc7`='Has luchado bien.' WHERE `ID`=62116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 우낏 약하게 했어. 사촌들이 널 끝내줄 거야!', `MaleText_loc4`='我耗光你的力气。我的兄弟们会干掉你的！', `MaleText_loc5`='我削弱你的力量，接著我的表兄弟們會解決你!', `MaleText_loc7`='Yo te ha debilitado. ¡Mis hermanos akabarán contigo!' WHERE `ID`=62117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 많다. 너도 곧 죽을 거야, 외지인.', `MaleText_loc4`='好多猢狲。你马上就死了，迷路鬼。', `MaleText_loc5`='太多猴人了。飛仔，你死期不遠了。', `MaleText_loc7`='Demasiados hozen. Tú morirá pronto, $gextraño:extraña;.' WHERE `ID`=62118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='냄새나는 구리구리 외지인!', `MaleText_loc4`='干掉迷路鬼！', `MaleText_loc5`='臭兮兮的飛仔!你得學學該怎麼尊重猴人!', `MaleText_loc7`='¡$gExtraño apestoso:Extraña apestosa;!' WHERE `ID`=62119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 너희 보물 모두 뺏었다, 외지인 녀석아.', `MaleText_loc4`='你的财宝都归猢狲啦，迷路鬼！', `MaleText_loc5`='現在猴人手上有你的寶物，飛仔。', `MaleText_loc7`='Ahora los hozen tienen tus tesoros, $gextraño:extraña;.' WHERE `ID`=62120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외지인한테서 썩은 응가 냄새 난다!', `MaleText_loc4`='迷路鬼都发臭啦！', `MaleText_loc5`='飛仔聞起來像爛便便!', `MaleText_loc7`='¡$gExtraño:Extraña; huele a miko pocho!' WHERE `ID`=62121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 바로 뒤에 있습니다.', `MaleText_loc4`='我就在你身后。', `MaleText_loc5`='我就在你後面。', `MaleText_loc7`='Te cubro las espaldas.' WHERE `ID`=62122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노련하게 해내셨군요.', `MaleText_loc4`='水准高超。', `MaleText_loc5`='做得漂亮。', `MaleText_loc7`='Qué destreza.' WHERE `ID`=62123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쯤이면 놈들이 도망칠 법도 한데...', `MaleText_loc4`='你也许觉得他们应该学会逃跑。', `MaleText_loc5`='還以為他們應該學會怎麼逃命了。', `MaleText_loc7`='A estas alturas ya deberían haber aprendido a huir, ¿no?' WHERE `ID`=62124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불나방이 따로 없군요. 안 그렇습니까?', `MaleText_loc4`='飞蛾扑火，对不对？', `MaleText_loc5`='真是有自毀傾向的蟲子，不是嗎?', `MaleText_loc7`='Que bichos tan suicidas, ¿verdad?' WHERE `ID`=62125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 약간 신나긴 했습니다.', `MaleText_loc4`='嗯，真是令人兴奋。', `MaleText_loc5`='好吧，還算是有點刺激。', `MaleText_loc7`='Bueno, eso ha sido casi emocionante.' WHERE `ID`=62126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단하시군요.', `MaleText_loc4`='你让我大开眼界，朋友。', `MaleText_loc5`='你真讓我刮目相看，朋友。', `MaleText_loc7`='Me impresionas, camarada.' WHERE `ID`=62127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화끈하게 싸우시더군요. 좋습니다.', `MaleText_loc4`='你的战斗充满激情。我喜欢。', `MaleText_loc5`='你戰鬥時很有活力。我喜歡。', `MaleText_loc7`='Luchas con brío. Me gusta.' WHERE `ID`=62128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 어디서 배우셨습니까?', `MaleText_loc4`='你是从哪儿学的？', `MaleText_loc5`='你在哪兒學會這招的?', `MaleText_loc7`='¿Dónde aprendiste a hacer eso?' WHERE `ID`=62129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단하시군요.', `MaleText_loc4`='我真服了你。', `MaleText_loc5`='我的榮幸。', `MaleText_loc7`='Te felicito.' WHERE `ID`=62130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀들이 또 덤벼드는 게 참 신기하군요.', `MaleText_loc4`='真奇怪，这些螳螂妖总能卷土重来。', `MaleText_loc5`='搞不懂為什麼這些螳螂人還是不停來送死。', `MaleText_loc7`='No me explico que los mántides sigan viniendo a por más.' WHERE `ID`=62131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 그러다간 우리에게 다 당할 텐데 말이죠.', `MaleText_loc4`='你现在可能觉得我们已经把他们杀光了。', `MaleText_loc5`='你大概會想我們早把他們全殺光了。', `MaleText_loc7`='Ya los deberíamos haber matado a todos.' WHERE `ID`=62132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 못 알아듣나 보군요.', `MaleText_loc4`='可我觉得他们还没有受到教训。', `MaleText_loc5`='我不認為他們理解我們的訊息。', `MaleText_loc7`='No creo que estén captando el mensaje.' WHERE `ID`=62133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사마귀 친구들이라면 대환영입니다.', `MaleText_loc4`='好好招待了我们的螳螂妖朋友一番。', `MaleText_loc5`='得好好地歡迎我們的螳螂人朋友。', `MaleText_loc7`='Qué bienvenida para nuestros amigos mántides.' WHERE `ID`=62134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝나면 야영지로 돌아오십시오... 의논할 것이 많습니다.', `MaleText_loc4`='结束之后返回营地……我们有很多事情要讨论。', `MaleText_loc5`='等你完成之後就回營地來。我們有很多事得討論。', `MaleText_loc7`='Vuelve al campamento cuando termines. Tenemos mucho de lo que hablar.' WHERE `ID`=62135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조명탄이 올라갔습니다. 이제 뻥 뻥 맥주 지킴이를 발사할 수 있습니다.', `MaleText_loc4`='锁定信号弹。布姆布姆佳酿守卫者可以发射了。', `MaleText_loc5`='看到信號彈了。碰碰啤酒防衛者可以開火了。', `MaleText_loc7`='Se ha avistado una bengala. Ya se puede disparar el defensor de brebaje Bum Bum.' WHERE `ID`=62136;
