UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 안 되는 클락시바조차도 다 떠나버렸구나.$B$B내가 잠든 동안 무슨 일이 일어났건 건가?', `MaleText_loc4`='存活下来的卡拉克西瓦太少了。$B$B我沉睡的时候，发生了什么事？', `MaleText_loc5`='居然只剩下這麼少的卡拉西瓦。$B$B在我沉睡的時候，我的人民發生了什麼事?', `MaleText_loc7`='Ahora quedan muy pocos Klaxxi''va.$B$B¿Qué le ha ocurrido a mi gente mientras yo dormía?' WHERE `ID`=62165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 클락시의 의지를 믿는다. 그들은 우리 종족을 위해 무엇이 최선인지를 알고 있으니.', `MaleText_loc4`='我信任卡拉克西的意志。他们会作出符合我族人民最高利益的决定。', `MaleText_loc5`='我相信卡拉西的意志。他們知道該怎麼做才對我們的人民最好。', `MaleText_loc7`='Confío en la voluntad de los Klaxxi. Saben qué es lo mejor para nuestro pueblo.' WHERE `ID`=62166;
