UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<사마귀 의원이 커다란 눈을 가늘게 뜨며 당신을 잠시 바라봅니다.>', `MaleText_loc4`='<螳螂妖议员眯着他的大眼睛瞟了你一眼。>', `MaleText_loc5`='<螳螂人委員用他巨大的眼睛看了你一下。>', `MaleText_loc7`='<El concejal mántide fija sus enormes ojos en ti brevemente.>' WHERE `ID`=62172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제는 이 군단을 압박해 그 과정에서 우리 땅을 초토화시킬 것이다.$B$B대가가 너무 크군.', `MaleText_loc4`='女皇会在此过程中驱使虫群，同时也会摧毁我们自己的土地。$B$B代价太大了。', `MaleText_loc5`='女皇會奴役這個蟲群，並在過程中把我們的土地夷為平地。$B$B代價太高了。', `MaleText_loc7`='La Emperatriz pretende forzar este enjambre, arrasando así nuestras propias tierras.$B$BEl precio es demasiado alto.' WHERE `ID`=62173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇구나... 당신은 목표에게서 절대로 눈을 떼지 않는군요. 철저한 집중!', `FemaleText_loc4`='我知道了……视线锁定目标。全神贯注！', `FemaleText_loc5`='我明白了...你的雙眼絕不從目標身上移開。完全的專注!', `FemaleText_loc7`='Ya lo entiendo... Tus ojos nunca se apartan del objetivo. ¡Concentración total!' WHERE `ID`=62174;
