UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠는 너무 과잉보호를 해요. 도무지 뭘 할 수가 없다니까요!', `FemaleText_loc4`='我的父亲对我过于保护了，从来不让我做任何事情！', `FemaleText_loc5`='我爸實在太過度保護了。他從來就不准我做任何事!', `FemaleText_loc7`='Mi padre es muy sobreprotector. ¡Nunca me deja hacer nada!' WHERE `ID`=62181;
