UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생각보다 훨씬 고생스럽네요...', `FemaleText_loc4`='这比我想象中的可要困难多了……', `FemaleText_loc5`='這裡的工作比我想的還要多...', `FemaleText_loc7`='Esto cuesta mucho más de lo que yo pensaba...' WHERE `ID`=62184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸우는 게 춤추는 거랑 비슷하다면 큰일인데 말이죠. 난 춤은 꽝이거든요...', `FemaleText_loc4`='如果学战斗跟学跳舞一样，那我可就麻烦了。我是个很糟糕的舞者……', `FemaleText_loc5`='如果戰鬥就像跳舞，那我大概就有麻煩了。我是個糟糕的舞者...', `FemaleText_loc7`='Si luchar es igual que bailar, me he metido en un buen lío. Bailo fatal...' WHERE `ID`=62185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='장비가 더 좋았다면 피해를 더 많이 줄 수 있을 텐데...', `FemaleText_loc4`='我帮不上忙。但我想知道是不是我的装备好一些，就能制造出更多的伤害……', `FemaleText_loc5`='我忍不住要想，如果我有更好的武器，或許就能造成更大的損害...', `FemaleText_loc7`='No dejo de pensar que quizás podría infligir más daño si tuviera mejor equipo...' WHERE `ID`=62186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔달라 부족 얘기는 내가 어릴 때 말을 잘 듣게 하려고 지어낸 얘긴 줄 알았어요.', `FemaleText_loc4`='在我小时候，我总以为赞达拉部族是他们故意编出来吓唬我，好让我变乖的。', `FemaleText_loc5`='我小時候一直以為贊達拉是大人杜撰出來的，目的是要叫我乖一點。', `FemaleText_loc7`='Siempre pensé que los Zandalari eran seres inventados para que me portara bien cuando era más pequeña.' WHERE `ID`=62187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 모험가 기질을 타고난 것 같아요. 유랑도의 판다렌처럼 말이에요...', `FemaleText_loc4`='我认为自己天生就是个冒险家。跟迷踪岛上的那些熊猫人一样……', `FemaleText_loc5`='我想我天生就是一個探險家。就像那些從漂流島來的熊貓人一樣...', `FemaleText_loc7`='Creo que nací para ser aventurera, como los pandaren de La Isla Errante...' WHERE `ID`=62188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 폐허에는 유령이 있다고 해요. 난 유령 따윈 없다고 생각하지만요. 하긴, 잔달라 부족도 없는 줄 알았었죠.', `FemaleText_loc4`='这些废墟似乎有鬼魂出没。虽然我并不相信有什么鬼魂，但我也不相信有什么赞达拉。', `FemaleText_loc5`='這些廢墟八成有鬧鬼。不過我不相信鬼魂。而且我也不相信贊達拉。', `FemaleText_loc7`='Se supone que estas ruinas están malditas, aunque yo no creo en fantasmas. Pero bueno, tampoco creía en los Zandalari.' WHERE `ID`=62189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 해변은 정말 평화로운 곳이었는데... 이 야만인들 때문에 더럽혀졌네요!', `FemaleText_loc4`='这片海滩曾经是个多么宁静的地方。现在被这些蛮族给玷污了！', `FemaleText_loc5`='這片海灘以前是個多麼和平的地方，現在這裡都被那些野蠻人污染了!', `FemaleText_loc7`='Esta playa solía ser un lugar pacífico. ¡Ahora está infestada de estos bárbaros!' WHERE `ID`=62190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 파괴와... 죽음... 끝이 나긴 할까요?', `FemaleText_loc4`='太多的毁灭……太多的死亡……什么时候才是个尽头？', `FemaleText_loc5`='這麼多的破壞...這麼多的死亡...這一切會有停止的一天嗎?', `FemaleText_loc7`='Cuánta destrucción. Cuánta muerte. ¿Acabará esto algún día?' WHERE `ID`=62191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 이제, 돌격!', `FemaleText_loc4`='……现在，冲锋！', `FemaleText_loc5`='...現在，衝鋒!', `FemaleText_loc7`='¡Ahora! ¡A la carga!' WHERE `ID`=62192;
