UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기분 좋은 하루를 보내시길 바라요, $r님.', `FemaleText_loc4`='希望你今天过的愉快，$r。', `FemaleText_loc5`='$r，希望你有美好的一天。', `FemaleText_loc7`='Espero que estés disfrutando de este día, $r.' WHERE `ID`=62198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 가장 좋아하는 계절은 봄이에요. 당신은 어느 계절이 좋으세요?', `FemaleText_loc4`='春天是四季中我最喜欢的季节。你最喜欢哪个季节？', `FemaleText_loc5`='春天是四季當中我最喜歡的季節。你最喜歡哪個季節?', `FemaleText_loc7`='La primavera es mi estación del año favorita. ¿Cuál es la tuya?' WHERE `ID`=62199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바쁠 때는 하루가 너무 빨리 지나가요.$B$B가끔은 모든 일을 멈추고, 지금 이 순간을 즐겨야 해요.', `FemaleText_loc4`='我忙的时候日子过得很快。$B$B我必须提醒我自己停下脚步、享受当下。', `FemaleText_loc5`='忙碌的時候時間過得特別快。$B$B我得提醒自己停一停，好好享受這時刻。', `FemaleText_loc7`='Los días pasan rápido cuando estoy ocupada.$b$bDebo recordarme a mí misma que tengo que hacer una pausa y disfrutar del momento.' WHERE `ID`=62200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤가 다가오고 있나요?', `FemaleText_loc4`='煞魔逼近了？', `FemaleText_loc5`='煞越來越接近了嗎?', `FemaleText_loc7`='¿Se acercan los sha?' WHERE `ID`=62201;
