UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이들이 겁에 질리긴 했지만, 다들 괜찮을 거예요. 우리가 지켜줄 테니까요!', `FemaleText_loc4`='孩子们受到了惊吓，但他们会没事的。我们会保障他们的安全！', `FemaleText_loc5`='孩子們很害怕，但他們會沒事的。我們會保護他們的安全!', `FemaleText_loc7`='Los niños tienen miedo, pero estarán bien. ¡Los protegeremos!' WHERE `ID`=62203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훈련시켜 줘서 고마워요, $n. 언젠가 당신 같은 훌륭한 용사가 될 거예요!', `FemaleText_loc4`='谢谢你的训练，$n。我希望有朝一日能成为像你一样棒的斗士！', `FemaleText_loc5`='$n，謝謝你的訓練。希望有天我會變成跟你一樣棒的戰士!', `FemaleText_loc7`='Gracias por tu instrucción, $n. ¡Espero ser algún día tan buena luchadora como tú!' WHERE `ID`=62204;
