UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 근처에 있어서 다행이었죠?!', `FemaleText_loc4`='你很幸运，能跟着我，嗯？！', `FemaleText_loc5`='你在我附近是你運氣好，知道嗎?!', `FemaleText_loc7`='¡Menos mal que estabas cerca de mí, ¿eh?!' WHERE `ID`=62212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거 봐요! 돌이 미끄럽다니까요!', `FemaleText_loc4`='我告诉过你！那些岩石很滑的！', `FemaleText_loc5`='我告訴過你了!這些岩石會滑!', `FemaleText_loc7`='¡Te lo dije! ¡Estas rocas son resbaladizas!' WHERE `ID`=62213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 조심해야 해요!', `FemaleText_loc4`='你得多加小心！', `FemaleText_loc5`='你一定得更小心點!', `FemaleText_loc7`='¡Debes tener más cuidado!' WHERE `ID`=62214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 하나씩 줄게요...', `FemaleText_loc4`='每个人都有一个……', `FemaleText_loc5`='每個人都有一個...', `FemaleText_loc7`='Hay para todos...' WHERE `ID`=62215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에 제가 옆에 없으면 어떡하려고 그래요?', `FemaleText_loc4`='下次我可不一定能救得了你！', `FemaleText_loc5`='下次我可能不會在你身邊救你了!', `FemaleText_loc7`='¡Quizás la próxima vez no esté aquí para salvarte!' WHERE `ID`=62216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고! 괴물들이 녹옥 마을을 공격하고 있습니다! 도망치십시오!', `MaleText_loc4`='咦！怪物们在攻击绿石村！快跑！', `MaleText_loc5`='咿!怪獸正在攻擊綠石村!快跑啊!', `MaleText_loc7`='¡Aaah! ¡Unos monstruos están atacando la Aldea Verdemar! ¡HUYAMOS!', `FemaleText_loc1`='아아아! 괴물들이 녹옥 마을을 공격하고 있어요! 도망치세요!', `FemaleText_loc4`='咦！怪物们在攻击绿石村！快跑！', `FemaleText_loc5`='咿!怪獸正在攻擊綠石村!快跑啊!', `FemaleText_loc7`='¡Aaah! ¡Unos monstruos están atacando la Aldea Verdemar! ¡HUYAMOS!' WHERE `ID`=62217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적을 쓰러뜨리는 데 가장 중요한 건, 바른 자세예요. 무기를 크게 휘두르지 마세요. 절도 있게 공격하세요.', `FemaleText_loc4`='正确的战斗姿态是打败敌人的关键所在。不要疯狂挥舞你的武器。进攻要有章法。', `FemaleText_loc5`='好的架勢是擊敗敵人的關鍵。別胡亂揮舞你的武器。攻擊之間要進退有據。', `FemaleText_loc7`='Estar en buena forma es la clave para derrotar a tus enemigos. No blandas tu arma sin sentido. Sé disciplinado con tus ataques.' WHERE `ID`=62218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적은 우릴 봐 주지 않아요. 우리도 똑같이 대접해 줘야죠.', `FemaleText_loc4`='你的敌人不会对你仁慈。你应该以牙还牙。', `FemaleText_loc5`='你的敵人不會手下留情。用相同的態度去對待他。', `FemaleText_loc7`='Tu enemigo no tendrá piedad. Haz tú lo mismo.' WHERE `ID`=62219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약점을 드러내서는 안 돼요.', `FemaleText_loc4`='不要暴露你的弱点。', `FemaleText_loc5`='不要暴露自己的弱點。', `FemaleText_loc7`='No reveles tus debilidades.' WHERE `ID`=62220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기 실력에 자신감을 가지면 많은 도움이 되지요. 하지만 과신하다가는 목숨을 잃을 수도 있어요.', `FemaleText_loc4`='对自己的能力要有信心，这会让你一往无前。但过度自信会很快给你招来杀身之祸。', `FemaleText_loc5`='對自身技巧抱有信心非常重要。但自信過度也會很快害死自己。', `FemaleText_loc7`='La confianza en tus habilidades te hará llegar lejos. El exceso de confianza hará que te maten rápidamente.' WHERE `ID`=62221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 더 어린 연꽃을 좀 뽑기 시작하세요. 너무 많이는 말고요.', `FemaleText_loc4`='去吧，拔掉一些小花，别拔太多。', `FemaleText_loc5`='去摘一些剛開沒多久的花。但不要太多。', `FemaleText_loc7`='Adelante, empieza a arrancar algunas de las flores más jóvenes. Pero no demasiadas.' WHERE `ID`=62222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 이곳이 조용하군요. 좋습니다.', `MaleText_loc4`='今天这里很安静，真好。', `MaleText_loc5`='今天這裡很安靜。很好。', `MaleText_loc7`='Hoy está esto muy tranquilo. Bien.' WHERE `ID`=62223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저와 같이 가 주셨으면 합니다.', `MaleText_loc4`='我希望你今天能跟着我。', `MaleText_loc5`='我希望你跟我來。', `MaleText_loc7`='Hoy quiero que vengas conmigo.', `FemaleText_loc1`='오늘 저와 같이 가 주셨으면 해요.', `FemaleText_loc4`='我希望你今天能跟着我。', `FemaleText_loc5`='我希望你跟我來。', `FemaleText_loc7`='Hoy quiero que vengas conmigo.' WHERE `ID`=62224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 길은 쿤라이 정상으로 이어진답니다. 그루멀 가게에 와서 물건을 사면 행운이 깃들죠.', `MaleText_loc4`='这条路通往昆莱山。祝那些沿着它去土地精商店购物的人好运。', `MaleText_loc5`='這條路通往崑萊峰。順這條路到咕嚕摩商店購物的人會很好運。', `MaleText_loc7`='Este camino lleva a la Cima Kun-Lai. Buena suerte a quienes la recorren para comprar en las tiendas de los grúmel.' WHERE `ID`=62225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 온 걸 보니 강한가 보군. 그래, 그래... 괜찮은 실험 대상이 되겠어.', `MaleText_loc4`='你们一定非常强大，才能走这么远。是的……你们会成为合格的试验品。', `MaleText_loc5`='你們一定很強，才能來到這裡。沒錯，沒錯，你們會成為很棒的實驗品。', `MaleText_loc7`='Deben de ser poderosos para haber llegado hasta aquí. Sí... Son dignos de convertirse en mi sujetos para mis experimentos.' WHERE `ID`=62226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내 실험체 몇 개를 봤나 보군. 이리 와라. 내 영광스러운 업적을 모두 보여주지.', `MaleText_loc4`='啊，看来你已经见识了我的部分实验。再靠近点儿，我在这里的杰作会让你大开眼界。', `MaleText_loc5`='啊，看來你已經見識過我一部分的實驗。靠近一點，見證我完整的傑作吧。', `MaleText_loc7`='Ah, ya veo que han descubierto algunos de mis experimentos. Acérquense para ver la verdadera gloria de mi trabajo.' WHERE `ID`=62227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용서하십시오, 여왕님...', `MaleText_loc4`='原谅我，女皇……', `MaleText_loc5`='原諒我，女皇...', `MaleText_loc7`='Perdóname, Emperatriz...' WHERE `ID`=62228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신이 강하다고 생각하겠지. 아무것도 모르는군. 이제 내 가장 위대한 창조물을 봐라!', `MaleText_loc4`='你们肯定觉得自己很厉害吧。真是愚昧。看看吧，我最伟大的创造！', `MaleText_loc5`='你們一定認為自己很強。真是無知。看好了，我最偉大的作品!', `MaleText_loc7`='Se creen muy poderosos. Qué poco saben. ¡Contemplen mi mayor creación!' WHERE `ID`=62229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 한 거냐? 안 돼. 내 연구는 이렇게 끝나지 않아. 그렇겐 못 해!', `MaleText_loc4`='你们都干了些什么？不，我的工作不会就这样结束。我决不允许！', `MaleText_loc5`='你們做了什麼?不，我的實驗不會這樣結束。我絕不容許!', `MaleText_loc7`='¿Qué han hecho? No, mi trabajo no terminará así. ¡No lo permitiré!' WHERE `ID`=62230;
