UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아!', `MaleText_loc4`='好极了！', `MaleText_loc5`='很好!', `MaleText_loc7`='¡Excelente!' WHERE `ID`=62232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복도 많군. 이런 선물을 받다니.', `MaleText_loc4`='幸运儿们，有份大礼要送给你们。', `MaleText_loc5`='收下這份幸運的大禮吧。', `MaleText_loc7`='Tienes suerte de recibir este don.' WHERE `ID`=62233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음에서 생명이, 그리고 생명에서, 죽음이...', `MaleText_loc4`='没有死就没有生，没有生，何来死……', `MaleText_loc5`='有死就有生，有生就有死...', `MaleText_loc7`='De la muerte surge la vida, y de la vida, la muerte...' WHERE `ID`=62234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발 조심하라고!', `MaleText_loc4`='看看你们脚下！', `MaleText_loc5`='小心看路!', `MaleText_loc7`='¡Mira dónde pisas!' WHERE `ID`=62235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 누가 밀림 맥주 훔쳐간다고?', `MaleText_loc4`='什么？有人偷了丛林烈酒？', `MaleText_loc5`='什麼?有人偷走了叢林啤酒?', `MaleText_loc7`='¿Ké? ¿Alguien roba brebaje de jungla?' WHERE `ID`=62237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라! 일어나라! 녀석들이 밀림 맥주 훔쳐간다!', `MaleText_loc4`='醒醒！醒醒！他们在偷丛林烈酒！', `MaleText_loc5`='醒醒!醒醒!他們把叢林啤酒偷走了!', `MaleText_loc7`='¡Arriba! ¡Arriba! ¡Alguien roba brebaje de jungla!' WHERE `ID`=62238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이냐? 오늘 무슨 요일이냐?', `MaleText_loc4`='怎么了？今天是什么日子？', `MaleText_loc5`='發生什麼事?今天是什麼日子啊?', `MaleText_loc7`='¿Ké pasa? ¿Ké día es hoy?' WHERE `ID`=62239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우우욱!', `MaleText_loc4`='呕……', `MaleText_loc5`='呃噁!!', `MaleText_loc7`='¡¡BEEEEJ!!' WHERE `ID`=62240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다치지 않는 말릭이 깨어나는 동안 사마귀 무리를 물리치십시오!', `MaleText_loc4`='在无伤者玛里克苏醒过程中挡住虫群！', `MaleText_loc5`='在『毫髮無傷』的瑪力克甦醒之前，擋住蟲群!', `MaleText_loc7`='¡Contén el enjambre hasta que Malik el Indemne se despierte!' WHERE `ID`=62241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 돌아왔다. 클락시의 부름에 응답하노라.', `MaleText_loc4`='我回来了。我听到了卡拉克西的召唤。', `MaleText_loc5`='我聽從卡拉西的召喚，回來了。', `MaleText_loc7`='He vuelto. Respondo a la llamada de los Klaxxi.' WHERE `ID`=62242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다치지 않는 말릭.', `MaleText_loc4`='无伤者玛里克。', `MaleText_loc5`='『毫髮無傷』的瑪力克。', `MaleText_loc7`='Malik el Indemne.' WHERE `ID`=62243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 빗맞는 것조차도 허용하지 않지. 하지만 수많은 적이 네 창에 조각났다.', `MaleText_loc4`='没有一击能伤你分毫，却有无数敌人倒在你的战戟之下。', `MaleText_loc5`='你連一點小擦傷都沒有，但你的長戟殺死了無數的敵人。', `MaleText_loc7`='Nunca te llegaron a dar ni un golpe de refilón, pero innumerables enemigos cayeron ante tu alabarda.' WHERE `ID`=62244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 많은 적이 또 몰려옵니다, 클락시바여. 이렇게 어려운 때에 제가 도울 수 있어 영광입니다.', `MaleText_loc4`='还有数不尽的敌人正在涌来，卡拉克西瓦。我很荣幸能在困难之时为大家而战。', `MaleText_loc5`='而還有更多數不清的敵人攻過來，卡拉西瓦。能在需要的時候派上用場是我的榮幸。', `MaleText_loc7`='Y muchos más que caerán, Klaxxi''va. Es un honor servir en tiempos de necesidad.' WHERE `ID`=62245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 준비를 하라. 병참장교와 만나 무장하도록. 여기 있는 일꾼들이 언제든 도와줄 것이다.', `MaleText_loc4`='而你也要效力。去军需官那把自己武装起来吧。这里的虫群听你调遣。', `MaleText_loc5`='那就讓您出力吧。到軍需官那裡去將自己武裝起來。這裡的小蟲們可隨時供您使喚。', `MaleText_loc7`='Y bien que servirás. Pídele armas al intendente. Nuestros zánganos están a tu disposición.' WHERE `ID`=62246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 다른 이들이 말하는 것처럼 정말 강한가요?', `FemaleText_loc4`='你真有别人说的那么强吗？', `FemaleText_loc5`='你真的有大家說的那麼強嗎?', `FemaleText_loc7`='¿Eres tan fuerte como dicen los demás?' WHERE `ID`=62247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전합니다!', `MaleText_loc4`='我要挑战你！', `MaleText_loc5`='我向你挑戰!', `MaleText_loc7`='¡Te reto!', `FemaleText_loc1`='도전하겠어요!', `FemaleText_loc4`='我要挑战你！', `FemaleText_loc5`='我向你挑戰!', `FemaleText_loc7`='¡Te reto!' WHERE `ID`=62248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 마지막 재료였네! 잘했네, $p! 이제 축제를 시작할 수 있겠군!', `MaleText_loc4`='那是最后一部分原料！做得好，$p！现在可以开始欢庆节日了！', `MaleText_loc5`='那是最後的材料!做得好，$p!現在節慶可以開始了!', `MaleText_loc7`='¡Ese es el último ingrediente! ¡Buen trabajo, $p! ¡El festival ya puede comenzar!' WHERE `ID`=62249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터가 어려운 부분이지. 모두 물러서게나. 완벽한 뻥뻥주를 만드는 데는 정확성이 생명이거든!', `MaleText_loc4`='现在到了最难的部分。大家都往后退，酿造完美的昆莱劲酒关键在于精度！', `MaleText_loc5`='現在是困難的部分來了。大家退後，崑萊好勁道的訣竅就是精準!', `MaleText_loc7`='Ahora viene la parte difícil. ¡Que todo el mundo retroceda, la precisión es la clave de una perfecta pateadora de Kun-Lai!' WHERE `ID`=62250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 줘서 고마워! 잔치를 시작할 준비는 됐어?', `MaleText_loc4`='谢谢你救了我们！你准备好开始这场宴会了吗？', `MaleText_loc5`='謝謝你救了我們!你準備好開始這個行動嗎?', `MaleText_loc7`='¡Gracias por salvarnos! ¿Están listos para empezar la fiesta?' WHERE `ID`=62251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어할 준비가 됐습니다!', `MaleText_loc4`='我们做好防御准备了！', `MaleText_loc5`='我們準備要進行防禦了!', `MaleText_loc7`='¡Estamos preparados para la defensa!', `FemaleText_loc1`='방어할 준비가 됐어요!', `FemaleText_loc4`='我们做好防御准备了！', `FemaleText_loc5`='我們準備要進行防禦了!', `FemaleText_loc7`='¡Estamos preparados para la defensa!' WHERE `ID`=62252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀는 태어날 때 자아는 거의 없이 전투를 향한 목마름만을 갖고 태어난다. 군단에 합류하는 것은 단지 문화적 의례가 아니다. 그것은 육체적인 성숙을 위한 촉매제다.$B$B전투에서 살아 돌아온 자만이 무리살이에서 충분한 자격을 갖춘 개개의 시민으로 승격된다.', `MaleText_loc4`='螳螂妖生来脑子就缺根筋，却极度渴望战争。参与到集群战争中不仅仅是一种文化上的进阶仪式——还是身体成熟的催化剂。$B$B只有那些从战场上归来的勇士，才能从聚生虫成长为有完整自主意识的个体公民。', `MaleText_loc5`='螳螂人生來就缺乏頭腦，但十分好戰。參與蟲群並不只是一種文化儀式的演進，還是讓我們的生理趨於成熟的催化劑。$B$B只有那些從戰場上生還的螳螂人，可以由群生幼螳發展成心智成熟的獨立公民。', `MaleText_loc7`='Al nacer, lo único que tienen los mántides en la cabeza es un ferviente deseo de batalla. Formar parte de un enjambre no es solo un rito cultural de madurez; es el catalizador de nuestra maduración física.$B$BSolo aquellos que regresan de la batalla pueden pasar de ser un enjambrista a un ciudadano individual e independiente.' WHERE `ID`=62253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원 고마워, 친구.', `MaleText_loc4`='谢谢你的援助，朋友。', `MaleText_loc5`='謝謝你的援助，朋友。', `MaleText_loc7`='Gracias por el apoyo, amigos.' WHERE `ID`=62254;
