UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, $n 님이다!', `MaleText_loc4`='喔……$n！', `MaleText_loc5`='哇喔，$n!', `MaleText_loc7`='¡Ueeee, $n!', `FemaleText_loc1`='우와, $n 님이다!', `FemaleText_loc4`='喔……$n！', `FemaleText_loc5`='哇喔，$n!', `FemaleText_loc7`='¡Ueeee, $n!' WHERE `ID`=62257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제에 잘 오셨습니다, $n 님!', `MaleText_loc4`='欢迎参加宴会，$n！', `MaleText_loc5`='歡迎來到派對，$n!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la fiesta, $n!', `FemaleText_loc1`='축제에 잘 오셨어요, $n 님!', `FemaleText_loc4`='欢迎参加宴会，$n！', `FemaleText_loc5`='歡迎來到派對，$n!', `FemaleText_loc7`='¡$gBienvenido:Bienvenida; a la fiesta, $n!' WHERE `ID`=62258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님이 와 주셨으니 최고의 맥주달 축제가 되겠군요!', `MaleText_loc4`='有了$n参加，这将会成为最完美的酿月祭！', `MaleText_loc5`='有了$n在這兒，這將會是最棒的酒月節!', `MaleText_loc7`='¡Con $n aquí, este va a ser el mejor festival de la historia!', `FemaleText_loc1`='$n 님이 와 주셨으니 최고의 맥주달 축제가 되겠는걸요!', `FemaleText_loc4`='有了$n参加，这将会成为最完美的酿月祭！', `FemaleText_loc5`='有了$n在這兒，這將會是最棒的酒月節!', `FemaleText_loc7`='¡Con $n aquí, este va a ser el mejor festival de la historia!' WHERE `ID`=62259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 오실까 궁금하던 차였습니다, $n 님!', `MaleText_loc4`='我刚才还在想你什么时候会来呢，$n！', `MaleText_loc5`='$n，我還在想你什麼時候才會到這兒呢!', `MaleText_loc7`='¡Me preguntaba cuándo llegarías, $n!', `FemaleText_loc1`='언제 오실까 궁금하던 차였어요, $n 님!', `FemaleText_loc4`='我刚才还在想你什么时候会来呢，$n！', `FemaleText_loc5`='$n，我還在想你什麼時候才會到這兒呢!', `FemaleText_loc7`='¡Me preguntaba cuándo llegarías, $n!' WHERE `ID`=62260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님!', `MaleText_loc4`='嗨，$n！', `MaleText_loc5`='嘿，$n!', `MaleText_loc7`='¡Hola, $n!', `FemaleText_loc1`='안녕하세요, $n 님!', `FemaleText_loc4`='嗨，$n！', `FemaleText_loc5`='嘿，$n!', `FemaleText_loc7`='¡Hola, $n!' WHERE `ID`=62261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜만이네요, $n 님.', `MaleText_loc4`='好久不见，$n。', `MaleText_loc5`='好久不見了，$n。', `MaleText_loc7`='Cuánto tiempo, $n.', `FemaleText_loc1`='오랜만이네요, $n 님.', `FemaleText_loc4`='好久不见，$n。', `FemaleText_loc5`='好久不見了，$n。', `FemaleText_loc7`='Cuánto tiempo, $n.' WHERE `ID`=62262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, $n 님이 오셨네!', `MaleText_loc4`='嗨，是$n！', `MaleText_loc5`='嘿，是$n耶!', `MaleText_loc7`='¡Vaya, es $n!', `FemaleText_loc1`='이야, $n 님이 오셨네!', `FemaleText_loc4`='嗨，是$n！', `FemaleText_loc5`='嘿，是$n耶!', `FemaleText_loc7`='¡Vaya, es $n!' WHERE `ID`=62263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희와 한잔하시지요, $n 님!', `MaleText_loc4`='跟我们喝一杯吧，$n！', `MaleText_loc5`='跟我們一起喝杯啤酒吧，$n!', `MaleText_loc7`='¡Tómate una cerveza con nosotros, $n!', `FemaleText_loc1`='저희와 한잔하시죠, $n 님!', `FemaleText_loc4`='跟我们喝一杯吧，$n！', `FemaleText_loc5`='跟我們一起喝杯啤酒吧，$n!', `FemaleText_loc7`='¡Tómate una cerveza con nosotros, $n!' WHERE `ID`=62264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $n! 혹시 잠깐 시간 있나?', `MaleText_loc4`='很高兴见到你，$n！你有空吗？', `MaleText_loc5`='很高興見到你，$n!你有空嗎?', `MaleText_loc7`='¡Me alegro de verte, $n! ¿Tienes un minuto?' WHERE `ID`=62265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 와 주어 기쁘네, $n! 오늘 밤은 맥주달 축제가 열리는 밤인데, 나의 특제 쿤라이 뻥뻥주의 재료가 아직 하나도 안 왔지 뭔가. 재료를 가져오라고 조수들을 보냈는데 모두 감감무소식일세. 자네가 어떻게 된 영문인지 알아봐 주겠나?', `MaleText_loc4`='我很高兴你能来这，$n！今晚是酿月祭，而我最拿手的昆莱劲酒所需的原料都还没有运到。我派了助手出去收集它们，可一个都没回来。你能去帮我查查他们怎么了吗？', `MaleText_loc5`='真高興在這裡見到你，$n!今晚是酒月節，但沒有人送來我著名的崑萊好勁道的材料。我派我的助手出去收集材料，但沒有一個人回來。你能去看看是什麼事耽誤了他們嗎?', `MaleText_loc7`='¡Cuánto me alegro de que estés aquí, $n! Esta noche es el Festival de la Cerveza Lunar y no me ha llegado ninguno de los ingredientes de mi famosa pateadora de Kun-Lai. Mandé a mis ayudantes a buscarlos, pero no ha vuelto ninguno. ¿Podrías averiguar por qué se retrasan tanto?' WHERE `ID`=62266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조수 키우는 어디 있습니까?', `MaleText_loc4`='我在哪儿能找到助手琪舞？', `MaleText_loc5`='我要到哪裡去找助手琪佑?', `MaleText_loc7`='¿Dónde puedo encontrar a la ayudante Kieu?', `FemaleText_loc1`='조수 키우는 어디 있나요?', `FemaleText_loc4`='我在哪儿能找到助手琪舞？', `FemaleText_loc5`='我要到哪裡去找助手琪佑?', `FemaleText_loc7`='¿Dónde puedo encontrar a la ayudante Kieu?' WHERE `ID`=62267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주달 축제 밤이 되면, 먹물아가미 호수에서 물의 정령들이 의식을 거행한다네. 우리는 몇 년 동안 정령에게 제물을 바치고, 그 대가로 쿤라이 뻥뻥주의 재료인 깨끗한 물이 담긴 병을 받았지. 조수 타르트를 호수에 보냈는데, 아직 돌아오지 않았네. 북쪽으로 가서 조수가 왜 늦어지는지 알아봐 주겠나, $n?', `MaleText_loc4`='在酿月祭的夜晚举行仪式，就可以在墨鳃潭见到水灵。过去这些年，我们都会向水灵敬献贡品，以获取一瓶纯净之水用于酿造昆莱劲酒。我派助手塔蒂去湖那儿了，可她还没有回来。你可以去北方查查她出什么事了吗，$n？', `MaleText_loc5`='在酒月節之夜，你可以在墨鰓湖上找到正在舉行儀式的水靈。多年來，我們獻上貢品，跟水靈交換用來製造崑萊好勁道 的純淨清水。我派助手塔特到湖那裡去了，但她一直沒回來。你能到北方去看看什麼事情讓她耽擱了嗎，$n?', `MaleText_loc7`='En la noche de la Cerveza Lunar se pueden encontrar espíritus del agua en la presa Branquias de Tinta. A lo largo de los años les hemos realizado ofrendas a cambio de un vial de agua pura que se usa en la fabricación de la pateadora de Kun-Lai. Envié a la ayudante Tart al lago pero no ha vuelto aún. ¿Podrías dirigirte hacia el norte y descubrir qué la retiene, $n?' WHERE `ID`=62268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야운골이다!', `FemaleText_loc4`='野牛人！', `FemaleText_loc5`='揚古!', `FemaleText_loc7`='¡YAUNGOL!' WHERE `ID`=62269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조수 타르트는 어디 있습니까?', `MaleText_loc4`='我在哪儿能找到助手塔蒂？', `MaleText_loc5`='我要到哪裡去找助手塔特?', `MaleText_loc7`='¿Dónde puedo encontrar a la ayudante Tart?', `FemaleText_loc1`='조수 타르트는 어디 있나요?', `FemaleText_loc4`='我在哪儿能找到助手塔蒂？', `FemaleText_loc5`='我要到哪裡去找助手塔特?', `FemaleText_loc7`='¿Dónde puedo encontrar a la ayudante Tart?' WHERE `ID`=62270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 온, 포퍼스. 가자!', `FemaleText_loc4`='快点，波普，我们走！', `FemaleText_loc5`='來吧，啪啪。我們走吧!', `FemaleText_loc7`='Vamos, Botones. ¡Vámonos!' WHERE `ID`=62271;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $p 님! 이제 깨끗한 물을 뜰 수 있겠어요!', `FemaleText_loc4`='做得好，$p！现在我可以收集纯净之水了！', `FemaleText_loc5`='做得好，$p!現在我能收集純淨的水!', `FemaleText_loc7`='¡Buen trabajo, $p! ¡Ahora puedo recoger el agua pura!' WHERE `ID`=62272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키우, 타르트, 부자키! 재료를 모두 던져 넣게나!', `MaleText_loc4`='琪舞、塔蒂、布扎齐，快把原料扔进去！', `MaleText_loc5`='琪佑，塔特，溥查濟把材料丟進去!', `MaleText_loc7`='¡Kieu, Tart, Buzaki, echen los ingredientes!' WHERE `ID`=62273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님! 양조사 부프 님께서 물의 정령에게서 깨끗한 물이 담긴 병을 받아 오라고 하셨는데, 포퍼스가 제물을 먹어 버렸어요. 이제 정령들을 설득할 방법이 없어져 버린 데다, 정령들이 썩 상냥해 보이지도 않네요. 저 대신 좀 설득해 주시겠어요?', `FemaleText_loc4`='$n！酒仙布夫派我从水灵这取一小瓶纯净水，但是波普吃了我们的贡品。现在，我没有办法说服他们给我一瓶，而且他们看上去并不十分友好。你认为你能为我说服他们吗？', `FemaleText_loc5`='$n!釀酒大師布夫派我去水靈那裡取一瓶純淨的水，但啪啪把所有的貢品都吃掉了。現在我無法說服他們給我一瓶水，而且他們看起來不大友善。你可以幫我說服他們嗎?', `FemaleText_loc7`='¡$n! El maestro cervecero Boof me mandó por un vial de agua pura de los espíritus del agua, pero Botones se ha comido la ofrenda. Ahora no tengo manera de convencerlos para que me den uno y no parecen muy amistosos. ¿Crees que podrías persuadirlos de mi parte?' WHERE `ID`=62274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곡물 자루를 가져오라고 조수 키우를 보냈는데 감감무소식일세. 대신 확인하러 좀 가 주겠나? 곡물 창고는 마을 서쪽 끝에 있다네.', `MaleText_loc4`='我派助手琪舞去贮粮塔取回一袋粮食，可她还没有回来。你可以去帮我查查她怎么了吗？你可以在小镇的西侧找到贮粮塔。', `MaleText_loc5`='我派助手琪佑到倉庫去取一包穀物，但她還沒回來。你可以去幫我確認她的狀況嗎?你可以在小鎮的西邊界處找到倉庫。', `MaleText_loc7`='Mandé a la ayudante Kieu a los silos a recoger un saco de grano, pero todavía no ha regresado. ¿Podrías ir a buscarla? Encontrarás los silos en el extremo oeste de la ciudad.' WHERE `ID`=62275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코타 봉우리에 잘 왔어요. 엄청나게 유명한 코타 카파의 원산지죠. 카파의 독특한 향을 맡으면 복이 와요.', `MaleText_loc4`='欢迎来到寇塔峰。非常有名的寇塔咔啡的产地。幸运符懂得品味异域的美酒。', `MaleText_loc5`='歡迎來到柯沓峰。超美味柯沓卡法莓的發源地。一個好幸運星會懂得嚐嚐這種異國風味的佳釀。', `MaleText_loc7`='Te doy la bienvenida a la Cumbre Kota, hogar del archiconocido kafa Kota. Un grisgrís sabio no dudaría en oler y catar brebajes exóticos.' WHERE `ID`=62276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 변변찮은 야영지에 잘 오셨어요.', `MaleText_loc4`='欢迎来到我们最最卑微的营地。', `MaleText_loc5`='歡迎來到我們的小營地。', `MaleText_loc7`='Te doy la bienvenida a nuestro humilde campamento.' WHERE `ID`=62277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 복덩이는 뭐예요?', `MaleText_loc4`='你的幸运符是什么？', `MaleText_loc5`='你的幸運星是什麼?', `MaleText_loc7`='¿Cuál es tu grisgrís?' WHERE `ID`=62278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFF01DFD7파란색|r 공을 차지했습니다!', `MaleText_loc4`='$n取走了|cFF01DFD7蓝色|r的球！', `MaleText_loc5`='$n奪走了|cFF01DFD7藍色|r異能球!', `MaleText_loc7`='¡$n ha tomado el orbe |cFF01DFD7azul|r!' WHERE `ID`=62279;
