UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFF01DF01녹색|r 공을 차지했습니다!', `MaleText_loc4`='$n取走了|cFF01DF01绿色|r的球！', `MaleText_loc5`='$n奪走了|cFF01DF01綠色|r異能球!', `MaleText_loc7`='¡$n ha tomado el orbe |cFF01DF01verde|r!' WHERE `ID`=62281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFFBF00FF보라색|r 공을 차지했습니다!', `MaleText_loc4`='$n取走了|cFFBF00FF紫色|r的球！', `MaleText_loc5`='$n奪走了|cFFBF00FF紫色|r異能球!', `MaleText_loc7`='¡$n ha tomado el orbe |cFFBF00FFmorado|r!' WHERE `ID`=62282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF01DFD7파란색|r 공이 돌아왔습니다!', `MaleText_loc4`='|cFF01DFD7蓝色|r宝珠被放回了！', `MaleText_loc5`='|cFF01DFD7藍色|r異能球已回到初始位置!', `MaleText_loc7`='¡El orbe |cFF01DFD7azul|r ha sido devuelto!' WHERE `ID`=62283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFBF00FF보라색|r 공이 돌아왔습니다!', `MaleText_loc4`='|cFFBF00FF紫色|r宝珠被放回了！', `MaleText_loc5`='|cFFBF00FF紫色|r異能球已回到初始位置!', `MaleText_loc7`='¡El orbe |cFFBF00FFmorado|r ha sido devuelto!' WHERE `ID`=62284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF8000주황색|r 공이 돌아왔습니다!', `MaleText_loc4`='|cFFFF8000橙色|r宝珠被放回了！', `MaleText_loc5`='|cFFFF8000橘色|r異能球已回到初始位置!', `MaleText_loc7`='¡El orbe |cFFFF8000naranja|r ha sido devuelto!' WHERE `ID`=62285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF01DF01녹색|r 공이 돌아왔습니다!', `MaleText_loc4`='|cFF01DF01绿色|r宝珠被放回了！', `MaleText_loc5`='|cFF01DF01綠色|r異能球已回到初始位置!', `MaleText_loc7`='¡El orbe |cFF01DF01verde|r ha sido devuelto!' WHERE `ID`=62286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신중을 기해야 하네. 샨쩌 부족은 우리가 잘 알지 못하는 흑마법을 쓰거든.', `MaleText_loc4`='我们必须步步为营。山泽部族在练习一些我们仍无法完全理解的黑暗魔法。', `MaleText_loc5`='我們必須謹慎行事。衫織部族會使用我們還不是很了解的黑魔法。', `MaleText_loc7`='Debemos ir con cuidado. La tribu Shan''ze practica una magia negra que aún no comprendemos del todo.' WHERE `ID`=62287;
