UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음 만났을 때보다 강해지셨군요.', `MaleText_loc4`='你比我们初见时长进了许多。', `MaleText_loc5`='自從上次一別，你成長了許多。', `MaleText_loc7`='Has progresado mucho desde que nos conocimos.', `FemaleText_loc1`='처음 만났을 때보다 강해지셨군요.', `FemaleText_loc4`='你比我们初见时长进了许多。', `FemaleText_loc5`='自從上次一別，你成長了許多。', `FemaleText_loc7`='Has progresado mucho desde que nos conocimos.' WHERE `ID`=62324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 함께 싸운다면 영광일 거예요. 언덕에 있을 테니 필요하면 말해 주세요.', `MaleText_loc4`='和你并肩战斗是我的荣幸。如果你需要我，就来山上找我吧。', `MaleText_loc5`='能在戰場上加入你是我的榮幸。如需我的幫忙，就到山丘上跟我說一聲。', `MaleText_loc7`='Será un honor para mí acompañarte en la batalla. Búscame en la colina si me necesitas.', `FemaleText_loc1`='전투에서 함께 싸운다면 영광일 거예요. 언덕에 있을 테니 필요하면 말해 주세요.', `FemaleText_loc4`='和你并肩战斗是我的荣幸。如果你需要我，就来山上找我吧。', `FemaleText_loc5`='能在戰場上加入你是我的榮幸。如需我的幫忙，就到山丘上跟我說一聲。', `FemaleText_loc7`='Será un honor para mí acompañarte en la batalla. Búscame en la colina si me necesitas.' WHERE `ID`=62325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[PH] 분노 전사는 어떻게 훈련합니까?', `MaleText_loc4`='[PH]你是如何训练一名狂暴战士的？', `MaleText_loc5`='你會怎麼訓練狂怒戰士?', `MaleText_loc7`='[PH] ¿Cómo entrenarías a un Guerrero de la Furia?', `FemaleText_loc1`='[PH] 분노 전사는 어떻게 훈련합니까?', `FemaleText_loc4`='[PH]你是如何训练一名狂暴战士的？', `FemaleText_loc5`='我希望瞭解一下雙天賦專精。', `FemaleText_loc7`='[PH] ¿Cómo entrenarías a un Guerrero de la Furia?' WHERE `ID`=62326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기에 있는 노예는 한 놈도 남김 없이 갈가리 찢어 버릴 테다. 그 하찮은 봉기 때문에 너희는 모조리 죽게 될 것이다!', `MaleText_loc4`='我要撕碎山谷中所有的奴隶，你们这微不足道的暴动只有死路一条！', `MaleText_loc5`='我會撕裂這個山谷中剩下的每一個奴隸。你們小小的起義會以你們所有人的死亡為終結!', `MaleText_loc7`='Haré pedazos a todos y cada uno de los esclavos de este valle. ¡Su insignificante rebelión será su muerte!' WHERE `ID`=62328;
