UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s|1이;가; |cFFF00000|Hspell:117283|h[정화의 물]|h|r에 의해 치유되려고 합니다! 그를 이동시키십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s将受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！移动他！', `MaleText_loc5`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s將得到|cFFF00000|Hspell:117283|h[淨化之水]|h|r的治療!移開他!', `MaleText_loc7`='|TInterfaceIconsability_shaman_fortifyingwaters.blp:20|t¡%s está a punto de ser curado por |cFFF00000|Hspell:117283|h[Aguas purificadoras]|h|r! ¡Muévelo!', `FemaleText_loc1`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s|1이;가; |cFFF00000|Hspell:117283|h[정화의 물]|h|r에 의해 치유되려고 합니다! 그를 이동시키십시오!', `FemaleText_loc4`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s将受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！移动他！', `FemaleText_loc5`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s將得到|cFFF00000|Hspell:117283|h[淨化之水]|h|r的治療!移開他!', `FemaleText_loc7`='|TInterfaceIconsability_shaman_fortifyingwaters.blp:20|t¡%s está a punto de ser curado por |cFFF00000|Hspell:117283|h[Aguas purificadoras]|h|r! ¡Muévelo!' WHERE `ID`=62340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s|1이;가; |cFFF00000|Hspell:117283|h[정화의 물]|h|r에 의해 치유되고 있습니다! 마법을 해제하십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s正受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！驱散他！', `MaleText_loc5`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s將得到|cFFF00000|Hspell:117283|h[淨化之水]|h|r的治療!驅散他!', `MaleText_loc7`='|TInterfaceIconsability_shaman_fortifyingwaters.blp:20|t¡%s está siendo curado por |cFFF00000|Hspell:117283|h[Aguas purificadoras]|h|r! ¡Disípaselo!', `FemaleText_loc1`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s|1이;가; |cFFF00000|Hspell:117283|h[정화의 물]|h|r에 의해 치유되고 있습니다! 마법을 해제하십시오!', `FemaleText_loc4`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s正受到|cFFF00000|Hspell:117283|h[净化之水]|h|r的治疗效果！驱散他！', `FemaleText_loc5`='|TInterface\\Icons\\ability_shaman_fortifyingwaters.blp:20|t%s將得到|cFFF00000|Hspell:117283|h[淨化之水]|h|r的治療!驅散他!', `FemaleText_loc7`='|TInterfaceIconsability_shaman_fortifyingwaters.blp:20|t¡%s está siendo curado por |cFFF00000|Hspell:117283|h[Aguas purificadoras]|h|r! ¡Disípaselo!' WHERE `ID`=62341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 많은 전투를 목도했고, 많은 동료를 치유했으며, 많은 영혼을 정화했고, 제가 내린 명령에 많은 적이 목숨을 잃었습니다.

이 도시 안이 안전해 보일 수도 있지만, 착각은 금물입니다. 전쟁은 마치 유행병처럼 이 땅을 괴롭히고 있고, 선택받은 몇 명만이 살아남아 후세에 이야기를 전하게 되지요.', `MaleText_loc4`='我见识过许多场战斗，医治了许多盟友，净化了许多灵魂，在我的指挥下许多敌人都死了。

你可能觉得躲在城墙下会很安全，但请别弄错了，战争会像瘟疫一样席卷大地，只有很少一部分幸运的人能活下来，讲述这悲惨的往事。', `MaleText_loc5`='我見過許多場戰鬥，治療過許多盟友，淨化過許多靈魂，而且在我的指揮下殺過許多敵人。

你在城市裡或許覺得很安全，但別搞錯了，戰爭像傳染病一樣傳遍這些土地，而只有少數獲選的人能活下來訴說這些故事。', `MaleText_loc7`='He presenciado innumerables batallas, sanado a mis aliados, purificado incontables almas, y muchos enemigos han sido víctimas de mis órdenes.

Puede que te sientas $gseguro:segura; dentro de las murallas de esta ciudad, pero no te equivoques: la guerra asola estas tierras como una pandemia, y solo unos pocos elegidos viven para contarlo.' WHERE `ID`=62342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 생각할 게 많네, $n. 이제 가서 뭔가 도움이 되는 일을 하게.', `MaleText_loc4`='我有很多事要操心，$n。出去找点事，证明你的价值。', `MaleText_loc5`='我得好好思考一下，$n。別待在這裡，去做點有用的事。', `MaleText_loc7`='Tengo mucho en que pensar, $n. Sal y haz algo útil.' WHERE `ID`=62343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지루해 죽겠어요! 빨리 악당을 잡으러 가자고요.', `MaleText_loc4`='好无聊啊！我们去追捕些坏人吧。', `MaleText_loc5`='我好無聊!我們去獵殺一些壞傢伙吧。', `MaleText_loc7`='¡Qué aburrimiento! Vamos a acabar con algunos malos.', `FemaleText_loc1`='지루해 죽겠어요! 빨리 악당을 잡으러 가자고요.', `FemaleText_loc4`='好无聊啊！我们去追捕些坏人吧。', `FemaleText_loc5`='我好無聊!我們去獵殺一些壞傢伙吧。', `FemaleText_loc7`='¡Qué aburrimiento! Vamos a acabar con algunos malos.' WHERE `ID`=62344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 뭔가에 불을 지르고 싶어서 근질근질해요!', `MaleText_loc4`='我早已按耐不住了！', `MaleText_loc5`='我很想燒掉些什麼東西!', `MaleText_loc7`='¡Quiero prenderle fuego a algo, ahora mismo!', `FemaleText_loc1`='벌써 뭔가에 불을 지르고 싶어서 근질근질해요!', `FemaleText_loc4`='我早已按耐不住了！', `FemaleText_loc5`='我很想燒掉些什麼東西!', `FemaleText_loc7`='¡Quiero prenderle fuego a algo, ahora mismo!' WHERE `ID`=62345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열심히 훈련 중인 거 안 보여요?', `MaleText_loc4`='你没看见我正在刻苦训练吗？', `MaleText_loc5`='我很認真在訓練，你看不出來嗎?', `MaleText_loc7`='¿No ves que estoy entrenando?', `FemaleText_loc1`='열심히 훈련 중인 거 안 보여요?', `FemaleText_loc4`='你没看见我正在刻苦训练吗？', `FemaleText_loc5`='我很認真在訓練，你看不出來嗎?', `FemaleText_loc7`='¿No ves que estoy entrenando?' WHERE `ID`=62346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말만 해요. 도우러 갈 테니까.', `MaleText_loc4`='只要你一句话，我就会来帮你。', `MaleText_loc5`='只要開口，我就會幫忙。', `MaleText_loc7`='Tan solo dilo, y al instante podrás contar con mi ayuda.', `FemaleText_loc1`='말만 해요. 도우러 갈 테니까.', `FemaleText_loc4`='只要你一句话，我就会来帮你。', `FemaleText_loc5`='只要開口，我就會幫忙。', `FemaleText_loc7`='Tan solo dilo, y al instante podrás contar con mi ayuda.' WHERE `ID`=62347;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼음의 차가운 손가락을 피할 수 있는 이는 별로 없지요.', `FemaleText_loc4`='很少有人能够在严寒下存活。', `FemaleText_loc5`='只有少數人能對抗冰的寒冷手指，並存活下來。', `FemaleText_loc7`='Pocos pueden sobrevivir a los fríos dedos del hielo.' WHERE `ID`=62348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림자의 춤이라는 것, 들어 보셨나요? 전투 중에 추는 춤이지요.$B$B죽음과 추는 춤이에요.', `FemaleText_loc4`='你听说过暗影之舞吗？这是在战斗中上演的舞蹈。$B$B它是死亡之舞。', `FemaleText_loc5`='你有聽過影舞嗎?這是在戰場上跳的舞。$B$B它是死亡之舞。', `FemaleText_loc7`='¿Has oído hablar de la danza de las sombras? Es el baile que ejecutas en una batalla.$B$BEs un baile con la muerte.' WHERE `ID`=62349;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='페이 리처럼 열정적으로 춤추는 이도 있고, 야리아처럼 자극하지 않으면 춤을 추지 않는 이도 있어요.', `FemaleText_loc4`='有些人的舞蹈充满激情并热衷于此，比如非离。$B$B而有些人却不喜欢，除非被激怒，比如雅丽亚。', `FemaleText_loc5`='有些人跳舞時帶有巨大的激情與熱誠，比如菲里。$B$B也有人是不跳舞的，除非他們被激怒，比如雅里亞。', `FemaleText_loc7`='Algunos bailan con una pasión y entusiasmo enormes, como Fei Li.$B$BOtros no bailan hasta que se les provoca, como Yalia.' WHERE `ID`=62350;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그림자의 춤을 잘 추는 비결은 절제예요.$B$B정확성.$B$B민첩성.$B$B그리고 우아함.$B$B단 한 동작이 넘쳐서도 모자라서도 안 되지요.', `FemaleText_loc4`='暗影之舞的秘密在于掌控力。$B$B精确。$B$B敏捷。$B$B优雅。$B$B动作不能多一步，也不能缺一步。', `FemaleText_loc5`='影舞的秘密在於控制。$B$B精確。$B$B敏捷。$B$B優美。$B$B動作絕不會太多，也不會太少。', `FemaleText_loc7`='El secreto de la danza de las sombras es el control.$B$BLa precisión.$B$BLa agilidad.$B$BLa elegancia.$B$BNi un movimiento de más, ni de menos.' WHERE `ID`=62351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항상 의지를 담아 공격해야 해요.', `FemaleText_loc4`='每一击都应传达你的最终意图。', `FemaleText_loc5`='每一擊都該傳遞出你的最終目的。', `FemaleText_loc7`='Todo golpe debe venir precedido por la mayor concentración posible.' WHERE `ID`=62352;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 명상을 통해 지혜를 얻고자 합니다.', `FemaleText_loc4`='我通过冥想寻求智慧。', `FemaleText_loc5`='我透過冥想來尋求智慧。', `FemaleText_loc7`='Busco la sabiduría a través de la meditación.' WHERE `ID`=62353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내면이 균형을 이루어야 평화를 찾을 수 있지요.', `FemaleText_loc4`='只有通过内在的平衡，我们才能让自己内心平静下来。', `FemaleText_loc5`='只有透過內在的平衡，我們才能找到自身的平靜。', `FemaleText_loc7`='Solo podemos encontrar la paz interior a través del equilibrio.' WHERE `ID`=62354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음이 평화로우면, 분노도 증오도 의심도 공포도 느껴지지 않습니다.', `FemaleText_loc4`='内心平静下来，我们就不会发怒、憎恨、怀疑和恐惧。', `FemaleText_loc5`='有了平靜的心，我們不會感覺到憤怒、仇恨、懷疑，以及恐懼。', `FemaleText_loc7`='Si nuestro corazón está en paz, no sentimos ira, odio, duda ni miedo.' WHERE `ID`=62355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 가장 큰 적은 우리입니다.', `FemaleText_loc4`='我们最大的敌人就是自己。', `FemaleText_loc5`='我們最大的敵人就是自己。', `FemaleText_loc7`='No hay peor enemigo que nosotros mismos.' WHERE `ID`=62356;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어차피 할 시합이라면 승리를 목표로 하세요.', `FemaleText_loc4`='如果你打这场比赛，就一定要全力以赴。', `FemaleText_loc5`='如果你要玩遊戲，就要贏。', `FemaleText_loc7`='Si juegas, hazlo para ganar.' WHERE `ID`=62357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 용사님.', `MaleText_loc4`='谢谢你，勇士。', `MaleText_loc5`='謝謝你，勇敢的人。', `MaleText_loc7`='Te lo agradezco, valiente.', `FemaleText_loc1`='고마워요, 용사님.', `FemaleText_loc4`='谢谢你，勇士。', `FemaleText_loc5`='謝謝你，勇敢的人。', `FemaleText_loc7`='Te lo agradezco, valiente.' WHERE `ID`=62358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움의 손길이 닿기 전에 죽는 게 아닌가 싶었습니다.

감사합니다.', `MaleText_loc4`='我以为等援军赶到我早就凶多吉少了

谢谢你。', `MaleText_loc5`='我還以為在幫手來之前我就會死了。

謝謝你。', `MaleText_loc7`='Creía que desfallecería antes de recibir ayuda.

Gracias.', `FemaleText_loc1`='도움의 손길이 닿기 전에 죽는 게 아닌가 싶었답니다.

고마워요.', `FemaleText_loc4`='我以为等援军赶到我早就凶多吉少了

谢谢你。', `FemaleText_loc5`='我還以為在幫手來之前我就會死了。

謝謝你。', `FemaleText_loc7`='Creía que desfallecería antes de recibir ayuda.

Gracias.' WHERE `ID`=62359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장에서 보여주신 강대함에 고개가 숙여지는군요. 감사합니다, 이방인님.', `MaleText_loc4`='你在战斗中表现的英勇真让我汗颜。谢谢你，陌生人。', `MaleText_loc5`='你在戰場上的英勇表現讓我自嘆不如。謝謝你，陌生人。', `MaleText_loc7`='Tu destreza en la batalla es una lección de humildad. Gracias, $gdesconocido:desconocida;.', `FemaleText_loc1`='전장에서 보여주신 강대함에 고개가 숙여지네요. 고마워요, 이방인님.', `FemaleText_loc4`='你在战斗中表现的英勇真让我汗颜。谢谢你，陌生人。', `FemaleText_loc5`='你在戰場上的英勇表現讓我自嘆不如。謝謝你，陌生人。', `FemaleText_loc7`='Tu destreza en la batalla es una lección de humildad. Gracias, $gdesconocido:desconocida;.' WHERE `ID`=62360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹옥 도장이 당신에게 감사의 빚을 졌군요.

일이 끝나면 거하게 한잔하시지요!', `MaleText_loc4`='绿石道场欠你一份人情。

这事结束后我们要好好喝上几杯！', `MaleText_loc5`='綠石道場欠你一個大恩情。

事情結束後我們一起喝一杯吧!', `MaleText_loc7`='El dojo Verdemar te debe su gratitud.

¡Bebamos cuando esto acabe!', `FemaleText_loc1`='녹옥 도장이 당신에게 감사의 빚을 졌네요.

일이 끝나면 거하게 한잔하시죠!', `FemaleText_loc4`='绿石道场欠你一份人情。

这事结束后我们要好好喝上几杯！', `FemaleText_loc5`='綠石道場欠你一個大恩情。

事情結束後我們一起喝一杯吧!', `FemaleText_loc7`='El dojo Verdemar te debe su gratitud.

¡Bebamos cuando esto acabe!' WHERE `ID`=62361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다... 더는 견뎌낼 수 없었습니다.

아, 이제 더는 못하겠군요.

우리 녹옥 맥주 보급품을 전부 도난당하지 않았더라면 정말 좋았을 텐데! 그랬으면 제가 강력한 맥주를 당신에게 만들어줄 수 있었을 겁니다...', `MaleText_loc4`='非常感谢……我差点就坚持不住了。

哎呀，我现在这样是没法再战斗了。

要是我们所有的绿石佳酿没有被偷该多好啊！那样我就可以做出一个能为你带来不可思议能量的配方……', `MaleText_loc5`='非常感謝你...要是時間再拖久一點我就撐不住了。

可惜，我已沒辦法再繼續下去了。

要是我們的綠石酒存貨沒被偷走就好了!不然我就能幫你製造一份具有神奇力量的飲料...', `MaleText_loc7`='Muchas gracias... No habría aguantado mucho más.

Por desgracia, no estoy en condiciones de seguir.

¡Ojalá no nos hubieran robado todas nuestras reservas de brebaje de Verdemar! Os habría elaborado una bebida con un poder maravilloso...' WHERE `ID`=62362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚싯대에 너무 의지하면 못 써! 진짜 낚시꾼은 손으로 고길 잡지.', `MaleText_loc4`='鱼竿仅仅只是辅助工具！真正的渔夫用自己的手捕鱼。', `MaleText_loc5`='釣竿是邪道!真正的釣魚人只用自己的雙手。', `MaleText_loc7`='¡Las cañas de pescar son muletas! Los auténticos pescadores usan las manos.' WHERE `ID`=62363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번은 자네 조상 세 명만 한 고기를 잡은 적도 있어. 결국 놓치긴 했지만, 한 1분은 족히 잡고 있었을걸.', `MaleText_loc4`='我曾经抓到过一条鱼，大小有你三个祖先加起来这么大。虽然最后它逃走了，但是逮到那条鱼的喜悦感是任何东西都无法比拟的。', `MaleText_loc5`='我曾經抓到比你祖宗三個人疊起來還大的魚。確實，牠跑走了，但我抓到牠有整整一分鐘。', `MaleText_loc7`='Una vez capturé un pez del tamaño de tres de tus ancestros. Sí, se escapó, pero lo tuve atrapado durante casi un minuto.' WHERE `ID`=62364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상어가 너무 화가 나서 육지까지 쫓아온 적 있어?', `MaleText_loc4`='你以前惹急过鲨鱼，让它跳出水来在陆地上追你吗？', `MaleText_loc5`='你有沒試過讓鯊魚抓狂到衝出水裡到陸上來抓人?', `MaleText_loc7`='¿Alguna vez has enfadado tanto a un tiburón que haya salido del agua para perseguirte por tierra?' WHERE `ID`=62365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 고기를 잡으려면 무슨 미끼가 좋냐고? 낚싯바늘에 결혼반지를 끼워.', `MaleText_loc4`='钓最大的鱼要用的最好鱼饵？把结婚戒指挂到你的鱼钩上。', `MaleText_loc5`='釣上大魚的最好誘餌?在鉤子上放結婚戒指。', `MaleText_loc7`='¿El mejor cebo para los peces más grandes? Pon un anillo de boda en el anzuelo.' WHERE `ID`=62366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수 밑바닥에 뭐가 있는지 아무도 몰라. 거기 가 본 녀석들 빼곤 말이지. 아, 그 녀석들한테 얘기를 들은 녀석들도 빼고.', `MaleText_loc4`='没人知道环礁湖底有些什么，除了那些去过下面的人们。还有那些和去过下面交流过的人。', `MaleText_loc5`='沒有人知道湖底有什麼，除了少數曾經親自去到湖底的人，以及後來有和他們聊過話的人。', `MaleText_loc7`='Nadie sabe lo que hay en el fondo de esa laguna, excepto los que han estado ahí abajo. Y la gente con la que hablaron después.' WHERE `ID`=62367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버터구이 크라켄 다리를 먹어본 적 있어? 그런 별미가 없지.', `MaleText_loc4`='你尝过黄油海怪腿吗？真是世间美味。', `MaleText_loc5`='嚐過奶油焗章魚腳嗎?超好吃的。', `MaleText_loc7`='¿Has probado alguna vez las patas de kraken hervidas y rebozadas con mantequilla? Lo mejor del mundo.' WHERE `ID`=62368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<잠에 빠진 소리를 냅니다.>', `MaleText_loc4`='<他睡得很熟。>', `MaleText_loc5`='<他睡得非常沉。>', `MaleText_loc7`='<Duerme profundamente.>' WHERE `ID`=62369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, 친구여. 뭐 마실 거라도 가져다드릴까요?', `MaleText_loc4`='你好，朋友。你要喝些什么？', `MaleText_loc5`='你好啊，朋友。我能幫你弄杯什麼喝的嗎?', `MaleText_loc7`='Saludos, $gamigo:amiga;. ¿Puedo servirte una jarra de lo que sea?' WHERE `ID`=62370;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마실 건 잘 드시고 다니셨나요?', `FemaleText_loc4`='最近有没喝上什么好酒？', `FemaleText_loc5`='你喜歡喝酒嗎?', `FemaleText_loc7`='¿Has estado bebiendo?' WHERE `ID`=62371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 머물든 말든 마음대로 하시오.', `MaleText_loc4`='我想你可以留下来。', `MaleText_loc5`='看來你是要留下了。', `MaleText_loc7`='Supongo que puedes quedarte aquí.' WHERE `ID`=62372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 그렇게 명랑해야겠소?', `MaleText_loc4`='你一定要这样喋喋不休吗？', `MaleText_loc5`='你一定要這麼爽朗開懷嗎?', `MaleText_loc7`='¿Tienes que armar tanto ruido?' WHERE `ID`=62373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 이름이 스톰스타우트입니까?', `MaleText_loc4`='你真的叫风暴烈酒？', `MaleText_loc5`='風暴烈酒是你的真名嗎?', `MaleText_loc7`='¿En serio te llamas Cerveza de Trueno?', `FemaleText_loc1`='정말로 이름이 스톰스타우트인가요?', `FemaleText_loc4`='你真的叫风暴烈酒？', `FemaleText_loc5`='風暴烈酒是你的真名嗎?', `FemaleText_loc7`='¿En serio te llamas Cerveza de Trueno?' WHERE `ID`=62374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 터졌다는 거요? 난 원래 이랬는데.', `MaleText_loc4`='什么爆发？我一向如此。', `MaleText_loc5`='爆發什麼的我最喜歡了。', `MaleText_loc7`='¿Qué brote? Yo soy así siempre.' WHERE `ID`=62375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 말고 머물 데 없소?', `MaleText_loc4`='你一定要待在这吗？', `MaleText_loc5`='你一定要待在這裡嗎?', `MaleText_loc7`='¿Tienes que quedarte aquí?' WHERE `ID`=62376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈은 그 궤짝에다 넣으쇼.', `MaleText_loc4`='就把你的钱留在箱子里吧。', `MaleText_loc5`='把錢留在保險箱裡就對了。', `MaleText_loc7`='Deja el dinero en el arca.' WHERE `ID`=62377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 당신이군.', `MaleText_loc4`='噢，就只有你。', `MaleText_loc5`='喔，原來是你。', `MaleText_loc7`='Oh, solo eres tú.' WHERE `ID`=62378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 아마 아무것도 안 사겠지. 다른 이들처럼.', `MaleText_loc4`='我敢说你甚至不会买任何一件东西。就像其他人一样。', `MaleText_loc5`='我猜你根本不想買東西。就和其他人一樣。', `MaleText_loc7`='Seguro que no vas a comprar nada. Igual que todos los demás.' WHERE `ID`=62379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관을 열지 말았어야 해. 여긴 너무 우울하잖아.', `MaleText_loc4`='我就不该开这家旅店。这里真是太压抑了。', `MaleText_loc5`='我根本不該開這間旅店的。這裡真讓人沮喪。', `MaleText_loc7`='Nunca debí abrir esta posada. Esto es deprimente.' WHERE `ID`=62380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<졸음이 가득한 목소리를 웅얼거리며 잠깐씩 코를 고는 싸움꾼 단>$b$b그렇다네... 스톰스타우트고말고...', `MaleText_loc4`='<大丹发出各种声响，夹杂着沉重的鼾声和断断续续的呓语。>$b$b没错……就是风暴烈酒……', `MaleText_loc5`='<大丹發出一陣陣愛睏的咕噥聲與鼻息聲。>$b$b對...風暴烈酒很好...', `MaleText_loc7`='<Gran Dan hace una combinación de ronquidos y gruñidos somnolientos.>$b$bSí... Cerveza de Trueno, vale...' WHERE `ID`=62381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 스톰스타우트라는 성을 가진 이가 지나가는 것을 보셨습니까?', `MaleText_loc4`='你见过有个叫风暴烈酒的人经过这里吗？', `MaleText_loc5`='你有見過任何名叫風暴烈酒的人經過這裡嗎?', `MaleText_loc7`='¿Has visto a alguien apellidado Cerveza de Trueno por aquí?', `FemaleText_loc1`='여기 스톰스타우트라는 성을 가진 이가 지나가는 것을 보셨나요?', `FemaleText_loc4`='你见过有个叫风暴烈酒的人经过这里吗？', `FemaleText_loc5`='你有見過任何名叫風暴烈酒的人經過這裡嗎?', `FemaleText_loc7`='¿Has visto a alguien apellidado Cerveza de Trueno por aquí?' WHERE `ID`=62382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇 명 봤습니다. 가장 큰 거구인 한이 마지막으로 코르베스에 싸우러 갔지요.$b$b사실 그리곤 며칠간 한을 보지 못했습니다. 아무 일 없었으면 좋겠군요...', `MaleText_loc4`='是的，见过一些。其中最壮硕的那个名叫韩，他最后一个出发加入了库尔维斯的战斗。$b$b事实上，我已经好几天没见着他了。希望一切顺利……', `MaleText_loc5`='是的，有見過幾個。個子最大的那個，漢恩，上次見到，他要去柯爾斐斯戰鬥。$b$b事實上，我已經好幾天沒見到他了。我希望一切都沒事...', `MaleText_loc7`='Sí, a unos cuantos. El más grande, Han, fue el último en irse a luchar a Kor''vess.$b$bLa verdad es que no lo he visto en varios días. Espero que esté bien...' WHERE `ID`=62383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조정원에서 스톰스타우트라는 성을 가진 이가 지나가는 것을 보셨습니까?', `MaleText_loc4`='你在落日酒坊这里见到过叫风暴烈酒的吗？', `MaleText_loc5`='你有在釀酒園裡見到任何名叫風暴烈酒的人嗎?', `MaleText_loc7`='¿Has visto a algún Cerveza de Trueno aquí, en el Jardín de la Cebada?', `FemaleText_loc1`='양조정원에서 스톰스타우트라는 성을 가진 이가 지나가는 것을 보셨나요?', `FemaleText_loc4`='你在落日酒坊这里见到过叫风暴烈酒的吗？', `FemaleText_loc5`='你有在釀酒園裡見到任何名叫風暴烈酒的人嗎?', `FemaleText_loc7`='¿Has visto a algún Cerveza de Trueno aquí, en el Jardín de la Cebada?' WHERE `ID`=62384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 있는 게으른 단 말고요? 물론이죠!$b$b에비가 북쪽으로 사냥하러 가기 전에 잠깐 같이 있었답니다. 정말 매력적적인 여자죠.$b$b게다가 큰엄마 스톰스타우트를 기억 못 하겠어요?', `FemaleText_loc4`='你是指除了在那边的懒汉大丹以外的其他人吗？当然！$b$b在艾薇去北方捕猎，我和她共处了一段时间。真是个乖巧可人的姑娘。$b$b当然，谁又能忘掉风暴烈酒大妈呢？', `FemaleText_loc5`='你是說除了那邊那個懶鬼大丹以外嗎?當然有!$b$b在愛薇往北去狩獵之前，我花了點時間跟她在一起。真是個甜美的女孩。$b$b還有，當然了，誰能忘記風暴烈酒大娘呢?', `FemaleText_loc7`='¿Aparte del vago de Dan ese? ¡Claro!$b$bEstuve un rato con Evie antes de que se fuera a cazar al norte. Es una chica estupenda.$b$bY por supuesto, ¿quién podría olvidarse de Mamá Cerveza de Trueno?' WHERE `ID`=62385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 반갑네.', `MaleText_loc4`='很高兴见到你，$n。', `MaleText_loc5`='很高興見到你，$n。', `MaleText_loc7`='Me alegro de verte.' WHERE `ID`=62386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 보니 반갑군.', `MaleText_loc4`='能再见到你真好，$n。', `MaleText_loc5`='能再見到你真好，$n。', `MaleText_loc7`='Estoy encantado de volver a verte.' WHERE `ID`=62387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 더 있고 싶네만, 스톰스타우트 일가가 어떻게 되었는지 알아내러 가야 하네.', `MaleText_loc4`='我愿意多留一会，可我得去看看，风暴烈酒家的其他人怎么样了。', `MaleText_loc5`='我想多留一會，但是我得去看看風暴烈酒家的其他人怎麼了。', `MaleText_loc7`='Me quedaría más tiempo, pero tengo que averiguar qué ha sido de los demás Cerveza de Trueno.' WHERE `ID`=62388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 인연이 다시 닿기를 진심으로 바라네.', `MaleText_loc4`='真心希望我们能再次相见。', `MaleText_loc5`='真心希望我們能再相見。', `MaleText_loc7`='Espero de veras que nos volvamos a encontrar.' WHERE `ID`=62389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 의지에 반하여 |cFFFF0000|Hspell:122398|h[호박석 폭발]|h|r을 일으키기 시작합니다!', `MaleText_loc4`='你很不情愿地开始施放一次|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r！', `MaleText_loc5`='你無法控制自己，開始施放|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r!', `MaleText_loc7`='¡En contra de tu voluntad, comienzas a lanzar una |cFFFF0000|Hspell:122398|h[Deflagración de ámbar]|h|r!', `FemaleText_loc1`='당신은 의지에 반하여 |cFFFF0000|Hspell:122398|h[호박석 폭발]|h|r을 일으키기 시작합니다!', `FemaleText_loc4`='你很不情愿地开始施放一次|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r！', `FemaleText_loc5`='你無法控制自己，開始施放|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r!', `FemaleText_loc7`='¡En contra de tu voluntad, comienzas a lanzar una |cFFFF0000|Hspell:122398|h[Deflagración de ámbar]|h|r!' WHERE `ID`=62390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석 괴수가 |cFFFF0000|Hspell:122398|h[호박석 폭발]|h|r을 준비합니다!', `MaleText_loc4`='琥珀畸怪准备好|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r了！', `MaleText_loc5`='琥珀巨怪準備好施放|cFFFF0000|Hspell:122398|h[琥珀爆炸]|h|r!', `MaleText_loc7`='¡La monstruosidad de ámbar prepara una |cFFFF0000|Hspell:122398|h[Deflagración de ámbar]|h|r!' WHERE `ID`=62391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 이름이 에비였다고 하더구나.', `MaleText_loc4`='他们说你叫艾薇。', `MaleText_loc5`='他們說你叫愛薇。', `MaleText_loc7`='Dicen que te llamabas Evie.' WHERE `ID`=62392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 귀여운 아이였다고도 하더구나.', `MaleText_loc4`='说你是个可爱的姑娘。', `MaleText_loc5`='他們說妳是個甜美的女孩。', `MaleText_loc7`='Dicen que eras una chica encantadora.' WHERE `ID`=62393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 본 적은 없지만... 넌 우리 가족이었단다.', `MaleText_loc4`='不曾见你……但你是我的家人。', `MaleText_loc5`='我不認識妳...但妳是我的家人。', `MaleText_loc7`='Nunca te conocí... pero eras parte de la familia.' WHERE `ID`=62394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 세상에서는 가는 곳마다 기쁨과 아름다움이 가득하기를.', `MaleText_loc4`='愿你来生的旅途充满快乐与美好。', `MaleText_loc5`='願你在來生的旅途能充滿快樂與美好。', `MaleText_loc7`='Que tu viaje al otro mundo esté repleto de alegría y belleza.' WHERE `ID`=62395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가거라, 에비 스톰스타우트.', `MaleText_loc4`='再见了，艾薇·风暴烈酒。', `MaleText_loc5`='再見了，愛薇·風暴烈酒。', `MaleText_loc7`='Adiós, Evie Cerveza de Trueno.' WHERE `ID`=62396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리와 닮았었는데.', `MaleText_loc4`='她长得很像丽丽。', `MaleText_loc5`='她長得很像莉莉。', `MaleText_loc7`='Se parecía a Li Li.' WHERE `ID`=62397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처의 호박석 웅덩이에서 격렬히 거품이 나기 시작합니다!', `MaleText_loc4`='琥珀附近的水池开始剧烈地冒泡！', `MaleText_loc5`='附近的琥珀池開始大量冒出泡泡!', `MaleText_loc7`='¡Las pozas de ámbar cercanas empiezan a burbujear violentamente!' WHERE `ID`=62398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 그 정도면 내 시간을 충분히 갉아먹었다. 사소한 미물 따위에 주의를 뺏기진 않겠다.', `MaleText_loc4`='够了！你已经浪费了我太多时间。我不能为这种低贱的小人物分心。', `MaleText_loc5`='夠了!你們已經浪費我太多時間了。我不會再花費心思在如此低下的生物上了。', `MaleText_loc7`='¡Basta! Ya han desperdiciado mi tiempo demasiado. No me distraeré con criaturas tan insignificantes.' WHERE `ID`=62399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 과업은 다른 곳에서도... 계속될 거야...', `MaleText_loc4`='我的伟业将在别处……继续。', `MaleText_loc5`='我的工作會在別處...繼續下去...', `MaleText_loc7`='Mi obra seguirá adelante... en otra parte.' WHERE `ID`=62400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이제 더는 못하겠군요. 우리 녹옥 맥주 보급품을 전부 도난당하지 않았더라면 정말 좋았을 텐데!', `MaleText_loc4`='唉，我无法继续前行了。要是我们的绿石佳酿没被偷光就好了！', `MaleText_loc5`='可惜，我已沒辦法再繼續下去了。如果我們的綠石酒存貨沒被偷走就好了!', `MaleText_loc7`='Por desgracia, no estoy en condiciones de seguir. ¡Ojalá no nos hubieran robado todas nuestras reservas de brebaje de Verdemar!' WHERE `ID`=62401;
