UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주문은 한 번에 하나만 해 주세요.', `FemaleText_loc4`='请每次只下一个订单。', `FemaleText_loc5`='拜託，一次一個命令就好。', `FemaleText_loc7`='Un pedido cada vez, por favor.' WHERE `ID`=62442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최대한 빨리 만들고 있어요.', `FemaleText_loc4`='我正在以最快的速度酿酒。', `FemaleText_loc5`='我正以最快的速度在釀啤酒。', `FemaleText_loc7`='Estoy destilando lo más rápido que puedo.' WHERE `ID`=62443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 운이 좋군요! 마침 아주 좋은 물건이 들어왔거든요.', `FemaleText_loc4`='你真走运！我们刚进了一大批新货。', `FemaleText_loc5`='你運氣很好!我們剛好進了一批很棒的新貨。', `FemaleText_loc7`='¡Estás de suerte! Nos ha llegado un nuevo envío.' WHERE `ID`=62444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='특선주를 추천할게요.', `FemaleText_loc4`='应该试试特别的。', `FemaleText_loc5`='該試一下特別的。', `FemaleText_loc7`='Deberías probar el especial.' WHERE `ID`=62445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 함께 날아가자, 깨우는 자여. 그러면 내가 칼날바람의 길을 보여주겠다.', `MaleText_loc4`='和我一同飞翔吧，唤醒者，我要让你见识下掠风者的风采。', `MaleText_loc5`='跟我一起飛，喚醒者，我會讓你看看奪風者的方式。', `MaleText_loc7`='Vuela conmigo, heraldo, y te mostraré cómo actúa el Atracavientos.' WHERE `ID`=62446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 대전에서 나를 쓰러뜨릴 수 있다고 생각하나? 그렇다면 바로 지금 싸워보세.', `MaleText_loc4`='你以为自己能在一场宠物大战里打败我？走上前来，试试身手吧！', `MaleText_loc5`='你以為能在寵物對戰中打敗我嗎? 放馬過來吧，看看鹿死誰手!', `MaleText_loc7`='¿Crees que puedes vencerme en un duelo de mascotas? ¡Acércate y averigüémoslo!', `FemaleText_loc1`='애완동물 대전에서 나를 쓰러뜨릴 수 있다고 생각하나? 그렇다면 바로 지금 싸워보세.', `FemaleText_loc4`='你以为自己能在一场宠物大战里打败我？走上前来，试试身手吧！', `FemaleText_loc5`='你以為能在寵物對戰中打敗我嗎? 放馬過來吧，看看鹿死誰手!', `FemaleText_loc7`='¿Crees que puedes vencerme en un duelo de mascotas? ¡Acércate y averigüémoslo!' WHERE `ID`=62447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 칼날바람이여. [클락시 강화 효과]', `MaleText_loc4`='我需要你的帮助，掠风者。', `MaleText_loc5`='協助我，奪風者。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Atracavientos. [Mejora Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 칼날바람이여. [클락시 강화 효과]', `FemaleText_loc4`='我需要你的帮助，掠风者。', `FemaleText_loc5`='協助我，奪風者。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Atracavientos. [Mejora Klaxxi]' WHERE `ID`=62448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셰크지르의 손아귀로 데려가주십시오.', `MaleText_loc4`='请带我飞到夏柯希尔之巢', `MaleText_loc5`='請載我飛到杉齊爾窩巢。', `MaleText_loc7`='Por favor, llévame volando hasta Las Garras de Shek''zeer.', `FemaleText_loc1`='셰크지르의 손아귀로 데려가주세요.', `FemaleText_loc4`='请带我飞到夏柯希尔之巢', `FemaleText_loc5`='請載我飛到杉齊爾窩巢。', `FemaleText_loc7`='Por favor, llévame volando hasta Las Garras de Shek''zeer.' WHERE `ID`=62449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 충분히 모이면 내가 하늘에서 내려와 공격하겠다.', `MaleText_loc4`='把足够多的敌人聚到一起，然后我将从天空发起攻击。', `MaleText_loc5`='聚攏足夠的敵人，我將會從空中出擊。', `MaleText_loc7`='Reúne a suficientes enemigos y atacaré desde el cielo.' WHERE `ID`=62450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이에 있는 어떤 적이라도 뭉개버릴 수 있는 강력한 힘으로 너를 내려주겠다. 내릴 곳을 신중하게 선택해라.', `MaleText_loc4`='我把你送至地面的那股力量足以消灭着落点附近的任何敌人。请你谨慎挑选好你要着落的地方。', `MaleText_loc5`='我會讓你用足以摧毀附近的所有人的力道降落。小心選擇你的落地點。', `MaleText_loc7`='Te dejaré caer con la fuerza suficiente como para diezmar a cualquiera que esté cerca. Elige bien dónde aterrizar.' WHERE `ID`=62451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 곧 여제 폐하의 뜻이다.', `MaleText_loc4`='我们是女皇意志的延伸。', `MaleText_loc5`='我們是女皇意志的體現。', `MaleText_loc7`='Somos la extensión de la voluntad de nuestra Emperatriz.' WHERE `ID`=62452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 폐하의 신성한 이름을 받든다.', `MaleText_loc4`='我们只以她的神圣之名效忠。', `MaleText_loc5`='我們只為了侍奉她的聖名而存在。', `MaleText_loc7`='Nuestro destino es servir en nombre de la Divina.' WHERE `ID`=62453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의문도 고민도 없다. 그저 행할 뿐.', `MaleText_loc4`='从不质疑，也不思考，我们只需行动。', `MaleText_loc5`='毫無質疑，從不思考，我們只是行動。', `MaleText_loc7`='No cuestionamos; no reflexionamos. Solo actuamos.' WHERE `ID`=62454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 폐하께서 우리에게 뜻하신 바를 실현하기 위해 싸우고, 일하고, 섬긴다.', `MaleText_loc4`='我们战斗、劳作、效命，以使女皇对我们的期望成真。', `MaleText_loc5`='我們戰鬥，勞動，服侍她，讓她的願景化為現實。', `MaleText_loc7`='Luchamos, trabajamos y servimos para que Su visión se convierta en nuestra realidad.' WHERE `ID`=62455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 기쁨이 우리의 보람이며, 그분의 슬픔은 우리의 실패다.', `MaleText_loc4`='她的幸福就是对我们的犒赏，她的悲伤就是我们的失败。', `MaleText_loc5`='她的快樂就是我們的獎賞，她的憂傷就是我們的失敗。', `MaleText_loc7`='Su felicidad es nuestra recompensa; Su pesar, nuestro fracaso.' WHERE `ID`=62456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여제 폐하를 위해 망설임 없이 목숨을 바칠 것이다. 폐하의 빛이 없다면 우리의 목숨은 암흑에 묻혀 사라질 것이다.', `MaleText_loc4`='我们会毫不犹豫的为女皇献出生命。她就是明灯，没有她，我们的生命都将陷入无边黑暗。', `MaleText_loc5`='我們會毫不遲疑地將生命獻給女皇。她就是光明，沒有她，我們的生命將在黑暗中迷失。', `MaleText_loc7`='Daremos nuestras vidas por la Emperatriz sin dudarlo. Ella es la luz, y sin Ella nuestras vidas se perderían en la oscuridad.' WHERE `ID`=62457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 쭉정이가 공포에 휩쓸려 문간에 굴러다니는구나. 폐하께서 일으키신 폭풍이 저들을 날려 버릴 것이다.', `MaleText_loc4`='世界的糟粕被恐惧所驱使，在我们的门前飘摇；她的皇廷风暴会将他们一举驱散。', `MaleText_loc5`='塵俗之人受到恐懼的推動，從我們的門前踉蹌而過;她尊貴的暴風會將它們拂去。', `MaleText_loc7`='La escoria del mundo se arrastra hasta nuestro umbral, aterrorizada; Su tormenta regia la expulsará.' WHERE `ID`=62458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 태산과 같은 폐하의 뜻에 부딪히는 파도에 지나지 않는다. 일어나고 또 일어나도 허무하게 스러지고 말 것이다.', `MaleText_loc4`='女皇的神圣意志犹如高山，而他们就像是拍打高山的海浪。纵使滚滚而来，也必将一事无成。', `MaleText_loc5`='他們不過只是拍碎在她山岩般神聖意志的浪濤。他們或許會一次又一次地再起，但終將一事無成。', `MaleText_loc7`='No son más que olas que se rompen contra el promontorio de Su voluntad. Pueden alzarse cuantas veces quieran sin conseguir nada.' WHERE `ID`=62459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성하신 분께서 침입자에게 맞서라 하신다.', `MaleText_loc4`='神祗命我们对抗这些闯入者。', `MaleText_loc5`='聖女皇催促我們迎戰這些入侵者。', `MaleText_loc7`='La Divina nos ordena que nos enfrentemos a los intrusos.' WHERE `ID`=62460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 신성한 품에 들 자격이 없는 자들이었다.', `MaleText_loc4`='他们根本不配沐浴她神圣的光辉。', `MaleText_loc5`='他們顯然沒有資格得到她神聖的擁抱。', `MaleText_loc7`='Entonces no eran dignos de Su abrazo divino.' WHERE `ID`=62461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 굳건하며 동요하지 않는다.', `MaleText_loc4`='我们一往无前。我们坚定不移。', `MaleText_loc5`='我們矢志不渝。我們屹立不搖。', `MaleText_loc7`='No nos inmutamos. Seguimos firmes.' WHERE `ID`=62462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하께 선택받은 목소리, 우리가 나설 차례다.', `MaleText_loc4`='就让我们——女皇钦点的声音，来执行使命。', `MaleText_loc5`='所以我們才受選，成為她的聲音。', `MaleText_loc7`='Nos corresponde a nosotros, Su voz elegida.' WHERE `ID`=62463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통 가까이에 서서 맥주를 받으십시오!', `MaleText_loc4`='站在酒桶边取些啤酒吧！', `MaleText_loc5`='站在靠近桶子的地方好抓住啤酒!', `MaleText_loc7`='¡Acércate al barril para atrapar el brebaje!' WHERE `ID`=62464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성하신 분께서 당신의 신성한 뜻을 실현하라고 우리에게 목소리를 주셨다. 우리는 도구일 뿐이다.', `MaleText_loc4`='我们被神祗选中，为女皇神圣的意志赋予不朽的声音。我们任她差遣。', `MaleText_loc5`='聖女皇選上我們將她神聖的意志傳達給凡人。我們只是實現她意志的軀殼。', `MaleText_loc7`='La Divina nos ha elegido para dar voz mortal a Su pensamiento eterno. Solo somos el brazo que ejecuta Su voluntad.' WHERE `ID`=62465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 신성한 이곳을 더럽히려 하다니.', `MaleText_loc4`='神祗决不容许你玷污此地，外来者。', `MaleText_loc5`='聖女皇不會容忍你玷污這裡，外來者。', `MaleText_loc7`='La Divina no tolerará que profanes este lugar.' WHERE `ID`=62466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그저 섬길 뿐이고, 너는 그저 죽을 뿐이다.', `MaleText_loc4`='我们惟命是从，而你，惟死乃终。', `MaleText_loc5`='我們為了服侍而生，你是為了死亡而生。', `MaleText_loc7`='Nuestro destino es servir; el tuyo, morir.' WHERE `ID`=62467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 들이쉬는 공기를 통해 폐하께서 우리 목소리에 힘을 주신다.', `MaleText_loc4`='藉由空气，女皇为我们的声音赋予力量。', `MaleText_loc5`='透過我們呼吸的空氣，她強化了我們的聲音。', `MaleText_loc7`='A través del aire que respiramos, Ella refuerza nuestra voz.' WHERE `ID`=62468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 분노의 목소리를 보라.', `MaleText_loc4`='聆听女皇神圣怒火的声音吧。', `MaleText_loc5`='見識聖女皇之怒化成的聲音。', `MaleText_loc7`='Escucha la voz de Su cólera divina.' WHERE `ID`=62469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 목소리가 그분의 뜻에 형체를 부여한다.', `MaleText_loc4`='我们的声音承载着女皇的意志。', `MaleText_loc5`='我們的聲音實現她的意志。', `MaleText_loc7`='Nuestra voz da forma a Su voluntad.' WHERE `ID`=62470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 뜻은 위대하다. 그 뜻을 받들지 않으면 죽여 주겠다.', `MaleText_loc4`='女皇的意志凌驾于我们所有人之上。要么从命，要么受死。', `MaleText_loc5`='她的意志比我們更偉大。加入我們，不然就死吧。', `MaleText_loc7`='Su voluntad es más grande que nosotros. Únete a nosotros o muere.' WHERE `ID`=62471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분의 큰 은혜에 우리는 감사할 따름이다.', `MaleText_loc4`='女皇恩赐浩荡，我们感激涕零。', `MaleText_loc5`='她的恩賜浩蕩，我們感激涕零。', `MaleText_loc7`='Sus dones son abundantes; nuestra gratitud, infinita.' WHERE `ID`=62472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분께서 우리를 시험하신다. 실망을 안겨 드릴 순 없다.', `MaleText_loc4`='她在考验我们。我们不会让她失望。', `MaleText_loc5`='她考驗我們。我們不會讓她失望。', `MaleText_loc7`='Nos pone a prueba. No la defraudaremos.' WHERE `ID`=62473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 전당을 장식하는 호박석 같이 굳세리라. 폐하의 힘을 받아, 신성한 궁전에 침입하는 자를 없애 버리리라.', `MaleText_loc4`='我们如缔造殿堂的琥珀坚不可摧。凭借女皇之力，我们将消灭任何胆敢闯入她神圣家园的入侵者。', `MaleText_loc5`='我們如同建構大廳的琥珀一樣堅定。有了她的力量，我們會戰勝所有膽敢入侵她神聖家園的人。', `MaleText_loc7`='Somos tan inflexibles como el ámbar que da forma a estas salas. Con Su fuerza venceremos a todo aquel que profane Su morada divina.' WHERE `ID`=62474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 어두운 공허의 절망에 지지 않으리라. 우리가 죽는 것이 그분의 뜻이라면, 그대로 따르리라.', `MaleText_loc4`='我们不会向黑暗虚空的绝望屈服。如果女皇要我们去死，我们便照做。', `MaleText_loc5`='我們不會屈服於黑暗虛空的絕望之下。如果她的意志要我們滅亡，那麼我們就該滅亡。', `MaleText_loc7`='No sucumbiremos ante la desesperación del vacío oscuro. Si Ella desea que perezcamos, así lo haremos.' WHERE `ID`=62475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말을 걸어 보지 그래요?', `MaleText_loc4`='也许你该和她谈一谈。', `MaleText_loc5`='或許你該去和她說。', `MaleText_loc7`='Tal vez deberías hablar con ella.', `FemaleText_loc1`='말을 걸어 보지 그래요?', `FemaleText_loc4`='也许你该和她谈一谈。', `FemaleText_loc5`='或許你該去和她說。', `FemaleText_loc7`='Tal vez deberías hablar con ella.' WHERE `ID`=62476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이사한테? 뭐라고 해야 할지 모르겠는걸. 예쁘다고 말해야 하나? 그러면 징그럽게 생각하진 않을까? 아니면 그 자세를 동경한다고 말해야 하나? 하지만 그러면 내게 매력이 없다고 생각할지도 몰라!', `MaleText_loc4`='艾莎？我不知道该和她说些什么。也许我应该说“你长得很迷人”，但她会不会觉得我这样很怪？或许我可以告诉她我很钦慕她那从容不迫的姿态 ——但我又怕她觉得我这个人缺乏个性！', `MaleText_loc5`='艾莎?我不知道該跟她說什麼。如果我說她很美麗，她會不會覺得詭異?或者我該說我崇拜她美妙的體態，但那樣她或許會覺得我太沒個性!', `MaleText_loc7`='¿Aysa? No sé qué decirle. ¿Debería decirle que es preciosa o se asustará? Tal vez podría decirle que admiro su porte, pero entonces pensará que no tengo nada de personalidad.' WHERE `ID`=62477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들 말이, 이 산은 설인 천지라더군.', `MaleText_loc4`='你知道吗，他们说这些山里全是雪人。', `MaleText_loc5`='你知道的，他們說山裡到處都是雪人。', `MaleText_loc7`='Verás, dicen que estas montañas están infestadas de yetis.' WHERE `ID`=62478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 뭐... 그냥... "사람들"이지.', `MaleText_loc4`='哦……好吧……你知道……“他们”。', `MaleText_loc5`='呃...嗯...你知道嘛...「他們」。', `MaleText_loc7`='Eh... bueno... ya sabes... gente.' WHERE `ID`=62479;
