UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 그 얘길 해준 농부한테 그렇게 얘기해 보지 그래. 불쌍하게도 침략자들한테 농작물을 몽땅 빼앗겼더라고.', `MaleText_loc4`='把我所知道的转告给那个农夫。可怜的家伙在遭受入侵时失去了他所有的庄稼。', `MaleText_loc5`='你去和告訴我這件事的農夫說。入侵者搶了那可憐傢伙的所有庄稼。', `MaleText_loc7`='Eso díselo al granjero que me lo contó. Al pobre hombre los invasores le robaron todas sus cosechas.' WHERE `ID`=62490;
