UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님! 제가 사마귀를 막아내는 걸 도와주실 거죠?', `FemaleText_loc4`='$p！你会帮助我阻止螳螂妖吗？', `FemaleText_loc5`='$p!你會幫我阻止螳螂人嗎?', `FemaleText_loc7`='¡$p! ¿Me ayudarás a detener a los mántides?' WHERE `ID`=62531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시하십시오, $p 님. 맥주 양조하는 거나 도와주시지요.', `MaleText_loc4`='别管她，$p。帮我们酿啤酒吧。', `MaleText_loc5`='別理她，$p。來幫我們釀這個啤酒。', `MaleText_loc7`='No le hagas caso, $p. Ayúdanos a elaborar esta cerveza.' WHERE `ID`=62532;
