UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 밑에 $n|1이;가; 있는 것을 감지하고 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆察觉到$n在它下方并开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆發覺$n在他下面，並開始施放|cFFFF0000|Hspell:122774|h[碾碎]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon detecta a $n debajo de sí y empieza a lanzar |cFFFF0000|Hspell:122774|h[Machaque]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 밑에 $n|1이;가; 있는 것을 감지하고 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 시전하기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆察觉到$n在它下方并开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆發覺$n在他下面，並開始施放|cFFFF0000|Hspell:122774|h[碾碎]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon detecta a $n debajo de sí y empieza a lanzar |cFFFF0000|Hspell:122774|h[Machaque]|h|r!' WHERE `ID`=62534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 페로몬 방출을 감지하고 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆感觉到了信息素，开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆聞到飄過的費洛蒙，並開始施放|cFFFF0000|Hspell:122774|h[碾碎]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon nota el paso de Feromonas y empieza a lanzar |cFFFF0000|Hspell:122774|h[Machaque]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 페로몬 방출을 감지하고 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 시전하기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆感觉到了信息素，开始施放|cFFFF0000|Hspell:122774|h[重碾]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆聞到飄過的費洛蒙，並開始施放|cFFFF0000|Hspell:122774|h[碾碎]|h|r!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon nota el paso de Feromonas y empieza a lanzar |cFFFF0000|Hspell:122774|h[Machaque]|h|r!' WHERE `ID`=62535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가세, 올론! 맥주가 눈앞에 있다네!', `MaleText_loc4`='来吧，吴龙！ 美酒在召唤！', `MaleText_loc5`='來吧，歐龍!啤酒的呼喚!', `MaleText_loc7`='¡Vamos, Olon! ¡El deber cervecero nos llama!' WHERE `ID`=62536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이얏호! 맥주다아아아아!', `MaleText_loc4`='耶！啤酒！', `MaleText_loc5`='好耶!啤酒啤酒啤酒!!', `MaleText_loc7`='¡Sí! ¡¡CERVEEEEZA!!' WHERE `ID`=62537;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='둘 다 어디 가시는 거예요?', `FemaleText_loc4`='你们两个要去哪儿？', `FemaleText_loc5`='你們兩個要去哪兒?', `FemaleText_loc7`='¿Adónde van ustedes dos?' WHERE `ID`=62538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가긴 어딜 간다고 그러나.', `MaleText_loc4`='哪儿都不去。', `MaleText_loc5`='沒去哪兒。', `MaleText_loc7`='A ninguna parte.' WHERE `ID`=62539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리키툰 마을로!', `MaleText_loc4`='里基屯村！', `MaleText_loc5`='雷基頓村!', `MaleText_loc7`='¡A la Aldea Rikkitun!' WHERE `ID`=62540;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리키툰이라... 바로 그거야!', `FemaleText_loc4`='里基屯……就是那里！', `FemaleText_loc5`='雷基頓...這就是了!', `FemaleText_loc7`='Rikkitun... ¡Eso es!' WHERE `ID`=62541;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"먼 옛날 태고의 주문"... 이건 틀림없이 리키툰 마을을 말하는 거예요.', `FemaleText_loc4`='“咒法妖精”……那所指的一定是里基屯树精。', `FemaleText_loc5`='「精靈與根源之咒」...這一定跟雷基頓妖精有關。', `FemaleText_loc7`='"Ensalmos de hada y primigenios"... debe de referirse a los duendes de Rikkitun.' WHERE `ID`=62542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 가야겠어요! 거기서 만나요, $p 님.', `FemaleText_loc4`='我也去！在那儿见，$p。', `FemaleText_loc5`='我也要去!到那裡見了，$p。', `FemaleText_loc7`='¡Yo también voy! Nos vemos allí, $p.' WHERE `ID`=62543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악명 높은 이 붉은 연기의 텐우에게 도전하고 싶으십니까? 어서 오십시오. 실력 좀 한번 봅시다!', `MaleText_loc4`='你想挑战恶名昭著的“赤烟”腾武？来吧，朋友，让我们看看你的本事！', `MaleText_loc5`='你想挑戰惡名遠播『人間赤煙』添武嗎?來吧，朋友，看看你有幾兩重!', `MaleText_loc7`='¿Pretendes desafiar a Tenwu del Humo Rojo? ¡Ven y demuestra qué sabes hacer!' WHERE `ID`=62544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하, 어떤 꼴을 당할지 잘 모르시는 거 같군요...', `MaleText_loc4`='哈哈哈，我看你根本不知道自己在做什么……', `MaleText_loc5`='哈哈哈，你還搞不清楚自己的處境吧...', `MaleText_loc7`='Ja, ja, ja... Creo que no sabes en lo que te estás metiendo.' WHERE `ID`=62545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 살살 해 드리겠습니다.', `MaleText_loc4`='别担心，我会手下留情的。', `MaleText_loc5`='放心，我會手下留情的。', `MaleText_loc7`='No te preocupes, te trataré bien.' WHERE `ID`=62546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 좀 하시는군요... 하지만 아직 멀었습니다!', `MaleText_loc4`='不错，还不错……可还没完呢！', `MaleText_loc5`='不錯，不錯...但是還沒結束咧!', `MaleText_loc7`='No está mal, no está mal... ¡pero aún no hemos terminado!' WHERE `ID`=62547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 그 근육이 그냥 생긴 건 아니었군요!', `MaleText_loc4`='好吧！看来那些肌肉也不光是摆设！', `MaleText_loc5`='好吧!看來那些肌肉並非虛有其表!', `MaleText_loc7`='¡Vaya! ¡Parece que esos músculos no están solo de adorno!' WHERE `ID`=62548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 확실히 인정받으셨군요. 쉬운 일이 아닌데!', `MaleText_loc4`='你确实赢得了我的尊重。这可不容易，我的朋友！', `MaleText_loc5`='贏得了我的尊敬。這可不是容易的事，朋友!', `MaleText_loc7`='Te has ganado mi respeto. No es poca cosa, colega.' WHERE `ID`=62549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 함께라면 아주 재미있는 시간이 될 겁니다.', `MaleText_loc4`='嚯嚯，我们一定可以找到很多乐趣的！', `MaleText_loc5`='喔呵呵，看起來我們兩個有得玩了!', `MaleText_loc7`='¡Ja, ja, ja! ¡Tú y yo lo vamos a pasar MUY bien!' WHERE `ID`=62550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 재미있었어, 안 그래?', `MaleText_loc4`='哈，很有趣，对吧？', `MaleText_loc5`='呵，還挺有趣的，不是嗎?', `MaleText_loc7`='Eso fue divertido, ¿no?' WHERE `ID`=62551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책장 뜯는 중', `MaleText_loc4`='撕碎书页', `MaleText_loc5`='撕下書頁。', `MaleText_loc7`='Arrancar página' WHERE `ID`=62552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품 회수하는 중', `MaleText_loc4`='收集补给品', `MaleText_loc5`='收集補給品。', `MaleText_loc7`='Reunir provisiones' WHERE `ID`=62553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 무덤에서 너무나 많은 감정이 흘러 나왔다네. 너무나 많은 분노와 공포가...', `MaleText_loc4`='这么多的情绪被从陵墓中释放出来。到处充满了愤怒和恐惧……', `MaleText_loc5`='這些墓穴散發出這麼多情感。這麼多憤怒與恐懼...', `MaleText_loc7`='Se han liberado muchas emociones de las tumbas. Mucha ira, mucho temor...' WHERE `ID`=62554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 무덤에는 많은 비밀이 숨겨져 있다네, $n.', `MaleText_loc4`='这些陵墓里隐藏了许多的秘密，$n。', `MaleText_loc5`='這些墓穴藏著許多秘密，$n。', `MaleText_loc7`='Estas tumbas albergan muchos secretos, $n.' WHERE `ID`=62555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 황제들은 하인들을 산 채로 자기 무덤에 묻곤 했다네. 영혼을 결속해 영원히 복종하게 하기 위해서지.', `MaleText_loc4`='很多魔古帝王都让他们的仆从殉葬以困住他们的灵魂，这些仆从只能永远侍奉他们的主人。', `MaleText_loc5`='許多魔古統治者讓他們的僕人陪葬，讓他們的靈魂永遠服侍自己。', `MaleText_loc7`='Muchos de los emperadores mogu enterraron a sus sirvientes con ellos, atrapando sus espíritus en servidumbre para toda la eternidad.' WHERE `ID`=62556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 오니 뼛속까지 오한이 드는군, $c.', `MaleText_loc4`='这个地方让我感到寒冷彻骨，$c。', `MaleText_loc5`='這地方讓我打骨子裡發冷，$c。', `MaleText_loc7`='Este sitio me pone los pelos de punta, $c.' WHERE `ID`=62557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼결속은 야만적인 풍습이라네. 죽은 자로부터 영원한 평화를 빼앗는 것은 이루 말할 수 없이 잔인한 일이지.', `MaleText_loc4`='束缚灵魂是非常残暴的法术。剥夺死者永恒的安宁是一种无法形容的残忍行为。', `MaleText_loc5`='縛靈術是種殘酷的技巧。剝奪死者的永眠是無可言喻的殘忍行為。', `MaleText_loc7`='La vinculación de espíritus es una práctica muy salvaje. Privar a los muertos de su paz eterna es de una crueldad atroz.' WHERE `ID`=62558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽이 현실이 될 수 있다는 걸, 이 계곡이 보여 준다네.', `MaleText_loc4`='我们的噩梦不是天方夜谭，这个山谷就是最好的证明。', `MaleText_loc5`='這山谷證明了我們的夢魘可以成為現實。', `MaleText_loc7`='Este valle es la prueba de que nuestras pesadillas pueden hacerse realidad.' WHERE `ID`=62559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁본 뜨기', `MaleText_loc4`='制造拓片', `MaleText_loc5`='製造拓文。', `MaleText_loc7`='Crear calco' WHERE `ID`=62560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잠들어 있을 때는 호박석이 나를 지켜줬지만, 시간이 지날수록 그 힘이 빠져나가는 것이 느껴졌다.$B$B그때 네가 나를 깨우지 않았더라면, 나는 그대로 영원한 잠에 빠졌을 것이다.', `MaleText_loc4`='是琥珀在我沉睡时让我继续存活，不过我能感觉到它的力量随着时间逐渐消逝。$B$B如果你刚才试图唤醒我时没有成功，我恐怕将永远无法苏醒。', `MaleText_loc5`='琥珀在我沉睡時維持我的生命，但我覺得力量隨著時間流失了。$B$B如果你沒喚醒我，恐怕我就會沉入永恆的睡眠中了。', `MaleText_loc7`='El ámbar me mantuvo con vida mientras dormía, pero sentía que sus poderes iban disminuyendo con el tiempo.$B$BSi no me hubieras despertado en ese momento, me temo que no habría tardado en caer en un sueño eterno.' WHERE `ID`=62561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 시초자여. [클락시 증강 효과]', `MaleText_loc4`='我今天需要你的帮忙，至尊者。', `MaleText_loc5`='協助我，至高者。(卡拉西增強效果)', `MaleText_loc7`='Préstame tu ayuda, Perfecto. [Aumento Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 시초자여. [클락시 증강 효과]', `FemaleText_loc4`='我今天需要你的帮忙，至尊者。', `FemaleText_loc5`='協助我，至高者。(卡拉西增強效果)', `FemaleText_loc7`='Préstame tu ayuda, Perfecto. [Aumento Klaxxi]' WHERE `ID`=62562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 자릴. [클락시 강화 효과]', `MaleText_loc4`='我今天需要你的帮忙，夏克里尔。', `MaleText_loc5`='協助我，薩瑞爾。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Xaril. [Mejora Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 자릴. [클락시 강화 효과]', `FemaleText_loc4`='我今天需要你的帮忙，夏克里尔。', `FemaleText_loc5`='協助我，薩瑞爾。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Xaril. [Mejora Klaxxi]' WHERE `ID`=62563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 해부자여. [클락시 강화 효과]', `MaleText_loc4`='我今天需要你的帮忙，切割者。', `MaleText_loc5`='協助我，『開膛手』。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Disector. [Mejora Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 해부자여. [클락시 강화 효과]', `FemaleText_loc4`='我今天需要你的帮忙，切割者。', `FemaleText_loc5`='協助我，『開膛手』。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Disector. [Mejora Klaxxi]' WHERE `ID`=62564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 피 추적자여. [클락시 증강 효과]', `MaleText_loc4`='我今天需要你的帮忙，觅血者。', `MaleText_loc5`='協助我，覓血者。(卡拉西增強效果)', `MaleText_loc7`='Préstame tu ayuda, Cruento. [Aumento Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 피 추적자여. [클락시 증강 효과]', `FemaleText_loc4`='我今天需要你的帮忙，觅血者。', `FemaleText_loc5`='協助我，覓血者。(卡拉西增強效果)', `FemaleText_loc7`='Préstame tu ayuda, Cruento. [Aumento Klaxxi]' WHERE `ID`=62565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='PH', `MaleText_loc4`='PH', `MaleText_loc5`='PH', `MaleText_loc7`='PH' WHERE `ID`=62566;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여... 여긴 어디지? 어떻게 된 거지?', `FemaleText_loc4`='我……在……哪儿？出什么事了？', `FemaleText_loc5`='我...喔...在哪?這是怎麼回事?', `FemaleText_loc7`='Ah... dónde... ¿Qué está pasando?' WHERE `ID`=62567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰엄마는 사악한 고대의 곤충한테 조종당하고 있었어요.', `MaleText_loc4`='你被某种古老而又邪恶的虫子控制住了心智。', `MaleText_loc5`='你被某種古老的邪惡昆蟲生物控制了心靈。', `MaleText_loc7`='Una especie de insecto antiguo malvado te estaba controlando mentalmente.' WHERE `ID`=62568;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하, 그래? 뭐, 더 심한 일도 겪어 봤는걸. 그러고 보니 넌 누구니?', `FemaleText_loc4`='噢，对。呸，我遇到过更糟的事呢。你是谁？', `FemaleText_loc5`='這樣呀，哼，我遇過更糟的呢。那你又是誰?', `FemaleText_loc7`='Ah, eso. Bah, he pasado cosas peores. ¿Y tú quién eres exactamente?' WHERE `ID`=62569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 유랑도에서 온 첸 스톰스타우트라고 합니다.', `MaleText_loc4`='我是陈·风暴烈酒。来自迷踪岛。', `MaleText_loc5`='我是老陳·風暴烈酒，來自漂流島。', `MaleText_loc7`='Soy Chen Cerveza de Trueno. De La Isla Errante.' WHERE `ID`=62570;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰스타우트라고? 말도 안 돼. 농담이겠지. 진짜라고? 유랑도의 스톰스타우트가 판다리아에? 나머지 가족들은 어딨니?', `FemaleText_loc4`='风暴烈酒？不，你骗人。真的？迷踪岛的风暴烈酒族人，来到了潘达利亚！那其他的亲人呢？', `FemaleText_loc5`='風暴烈酒?不可能，你在騙我。是真的?風暴烈酒從漂流島來到潘達利亞...那其他族人在哪?', `FemaleText_loc7`='¿CERVEZA DE TRUENO? No. Es una broma. ¿En serio? ¡Un Cerveza de Trueno de La Isla Errante aquí, en Pandaria! ¿Dónde está el resto de la familia?' WHERE `ID`=62571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수액전문가들에게 돌아가는 길에 설명하지요.', `MaleText_loc4`='在回树脂大师家的路上我再解释给你听。', `MaleText_loc5`='回去找樹汁大師的路上我再解釋吧。', `MaleText_loc7`='Te lo explicaré mientras volvemos con los Maestros de Savia.' WHERE `ID`=62572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기! 클락시다! 저 수정에 힘을 쏟아... 도망치지 못하게 해라!', `MaleText_loc4`='那儿！卡拉克西！控制住水晶……别让它跑了！', `MaleText_loc5`='注意!是卡拉西的人!一起束縛住水晶...別讓他逃了!', `MaleText_loc7`='¡Allí! ¡Los Klaxxi! Contengan el cristal... ¡No dejen que escape!' WHERE `ID`=62573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유...', `MaleText_loc4`='自由……', `MaleText_loc5`='自由...', `MaleText_loc7`='Libertad...' WHERE `ID`=62574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='800하고도 77년 동안, 나는 수정 안에서 기다렸다... 수십 년을 세어가며 그림자가 균열을 지나가는 것을 봤지.', `MaleText_loc4`='八百七十七年来，我在那块水晶中等待……看白驹过隙，数岁月流逝。', `MaleText_loc5`='八百七十七年來，我一直在水晶裡等待...我看著陰影越過裂谷，數過十年又十年的光陰。', `MaleText_loc7`='He estado esperando en ese cristal durante ochocientos setenta y siete años... viendo sombras pasar a través de las grietas, contando las décadas.' WHERE `ID`=62575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 나는 다른 곳으로 가야 한다.', `MaleText_loc4`='现在，别的地方还需要我。', `MaleText_loc5`='現在，其他地方需要我。', `MaleText_loc7`='Ahora me necesitan en otra parte.' WHERE `ID`=62576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 제가 어떤 물건을 제공하는지 보실까요...', `MaleText_loc4`='等到你看见我要给你的东西……', `MaleText_loc5`='待在這裡，等著看我要給你的東西...', `MaleText_loc7`='Espera a ver lo que tengo preparado para ti...' WHERE `ID`=62577;
