UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 여기 써먹을 수 있는 정신나간 생각이 떠올랐는데, 너희 도움이 필요해.', `MaleText_loc4`='唔……我想到一个疯狂的主意，但这需要你们的帮助，英雄们。', `MaleText_loc5`='嗯...我有個或許管用的瘋狂點子，但是需要你們這些英雄幫忙。', `MaleText_loc7`='Mmm... Tengo una idea descabellada que podría funcionar, pero necesitaré su ayuda.' WHERE `ID`=62580;
