UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_holy_surgeoflight.blp:20|t%s|1이;가; |cFFFF0000|Hspell:122789|h[태양 광선]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_holy_surgeoflight.blp:20|t%s施放了|cFFFF0000|Hspell:122789|h[阳光]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_holy_surgeoflight.blp:20|t%s施放|cFFFF0000|Hspell:122789|h[太陽光束]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_holy_surgeoflight.blp:20|t¡%s lanza |cFFFF0000|Hspell:122789|h[Rayo de sol]|h|r!' WHERE `ID`=62585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무리전사들이 올라온다! 수액으로 움직임을 늦춰!', `MaleText_loc4`='虫群从斜坡上来了，快用树脂让他们减速。', `MaleText_loc5`='蟲群正往斜坡上來--用樹液減慢他們的速度!', `MaleText_loc7`='¡Suben enjambristas por la rampa! ¡Usen la savia para ralentizarlos!' WHERE `ID`=62586;
