UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두! 모두 내보내! 이 겁쟁이들을 처치해! 이놈들이 우릴 바보로 만들고 있어!', `MaleText_loc4`='所有人！全力出击！消灭这些懦夫，我们不能再被他们愚弄了！', `MaleText_loc5`='大家聽著!全力進攻!宰了這些懦夫，他們讓我們看起來像傻瓜!', `MaleText_loc7`='¡Todos! ¡Envíenlos a todos! ¡Exterminen a estos cobardes, nos están poniendo en ridículo!' WHERE `ID`=62589;
