UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리키툰 마을에 온 것을 진심으로 환영한다, 이방인.', `MaleText_loc4`='里基屯村欢迎你，外乡人。', `MaleText_loc5`='真誠的歡迎你來到雷基頓村，外來者。', `MaleText_loc7`='Te damos la bienvenida a la Aldea Rikkitun, $gforastero:forastera;.' WHERE `ID`=62592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈라진 칼날이 준비됐습니다. 그리고 원하시던 씨앗도 가져왔습니다. 이제 주문을 시작해주십시오.', `MaleText_loc4`='分叉之刃已经准备好了，我们已经献出了馈赠。 施放你的咒语吧。', `MaleText_loc5`='叉刃準備就緒，我們也把禮物送給你了。請執行你的咒語。', `MaleText_loc7`='La espada de doble hoja está preparada, y le hemos concedido nuestro don. Por favor, realiza tu conjuro.', `FemaleText_loc1`='갈라진 칼날이 준비됐어요. 그리고 원하시던 씨앗도 가져왔고요. 이제 주문을 시작해주세요.', `FemaleText_loc4`='分叉之刃已经准备好了，我们已经献出了馈赠。 施放你的咒语吧。', `FemaleText_loc5`='叉刃準備就緒，我們也把禮物送給你了。請執行你的咒語。', `FemaleText_loc7`='La espada de doble hoja está preparada, y le hemos concedido nuestro don. Por favor, realiza tu conjuro.' WHERE `ID`=62593;
