UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어휴, 정말 끔찍한 맛이군.', `MaleText_loc4`='是啊。这太可怕了。', `MaleText_loc5`='沒錯，這真的很可怕。', `MaleText_loc7`='Sí. Esto es horrible.' WHERE `ID`=62596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸... 공포 맥주라고 부르고 싶군. 맛 좀 보겠나, 리아?', `MaleText_loc4`='我想我可以称呼它为……恐惧老酒。你想尝尝吗，丽亚？', `MaleText_loc5`='我想我要稱它為...恐懼烈酒。妳想來一點嗎，莉亞?', `MaleText_loc7`='Creo que lo llamaré... Cerveza del pavor. ¿Quieres probar un poco, Lya?' WHERE `ID`=62597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 괜찮아요! 이미 이 조리법은 맥주 조리법이 아니라는 게 판명된 것 같은데요.', `FemaleText_loc4`='不用了！我想我们已经证明了这并不是一个啤酒配方。', `FemaleText_loc5`='不了謝謝!我想我們已經證明這不是個啤酒配方。', `FemaleText_loc7`='¡No, gracias! Creo que ya se ha visto que esto no era una receta de cerveza.' WHERE `ID`=62598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네. 올론, 자네는 어떤가?', `MaleText_loc4`='好吧。那你呢，吴龙？', `MaleText_loc5`='非常好。你呢，歐龍?', `MaleText_loc7`='Muy bien. ¿Y tú qué me dices, Olon?' WHERE `ID`=62599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야호! 맥주우우우우우우!', `MaleText_loc4`='耶！啤酒！！！', `MaleText_loc5`='好耶!啤酒啤酒啤酒!!!', `MaleText_loc7`='¡SÍ! ¡¡¡CERVEZAAA!!!' WHERE `ID`=62600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙네. 최고의 맥주를 만들지는 않았지만, 모험은 충분히 한 것 같군.', `MaleText_loc4`='谢谢你的帮助，$p。我们也许没有酿出最好的啤酒，不过我们倒是经历了一场惊心动魄的冒险。', `MaleText_loc5`='謝謝你的幫助，$p。我們或許沒做出最好的啤酒，但我們確實經歷了一場冒險。', `MaleText_loc7`='Gracias por tu ayuda, $p. Puede que no hayamos hecho la mejor cerveza, pero al menos hemos vivido una gran aventura.' WHERE `ID`=62601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모험심이 생기면 언제든지 이 맥주통에서 맥주를 따라 마시게나.', `MaleText_loc4`='你要是想找点刺激，这个木桶里的酒随时可供你饮用。', `MaleText_loc5`='當你想冒險犯難一下時，就隨意從這桶子裡喝點啤酒吧。', `MaleText_loc7`='No te cortes en tomar un poco de cerveza de este barril si te da un arrebato de audacia.' WHERE `ID`=62602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 지금 저랑 싸울 수 있다고 생각하나 보지?', `MaleText_loc4`='哈！你以为自己能挑战我了吗？', `MaleText_loc5`='哈!你已經準備好要跟我過招了嗎?', `MaleText_loc7`='¡Ja! ¿Crees que puedes desafiarme?', `FemaleText_loc1`='하! 지금 저랑 싸울 수 있다고 생각하나 봐요?', `FemaleText_loc4`='哈！你以为自己能挑战我了吗？', `FemaleText_loc5`='哈!你已經準備好要跟我過招了嗎?', `FemaleText_loc7`='¡Ja! ¿Crees que puedes desafiarme?' WHERE `ID`=62603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대결이 끝나면 서 있지도 못할걸요?', `MaleText_loc4`='但愿待会儿你还能站得住。', `MaleText_loc5`='等等看你打完還站不站得起來。', `MaleText_loc7`='Espero que aún puedas ponerte en pie cuando acabemos.', `FemaleText_loc1`='대결이 끝나면 서 있지도 못할걸요?', `FemaleText_loc4`='但愿待会儿你还能站得住。', `FemaleText_loc5`='等等看你打完還站不站得起來。', `FemaleText_loc7`='Espero que aún puedas ponerte en pie cuando acabemos.' WHERE `ID`=62604;
