UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저와 같이 가 주셨으면 합니다.', `MaleText_loc4`='我希望你今天能跟着我。', `MaleText_loc5`='我今天希望你跟我一起來。', `MaleText_loc7`='Hoy quiero que vengas conmigo.', `FemaleText_loc1`='오늘 저와 같이 가 주셨으면 해요.', `FemaleText_loc4`='我希望你今天能跟着我。', `FemaleText_loc5`='我希望你今天跟我一起來。', `FemaleText_loc7`='Hoy quiero que vengas conmigo.' WHERE `ID`=62606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하러 왔습니다!', `MaleText_loc4`='我是来挑战你的！', `MaleText_loc5`='我在這裡向你挑戰!', `MaleText_loc7`='¡He venido a enfrentarme a ti!', `FemaleText_loc1`='도전하러 왔어요!', `FemaleText_loc4`='我是来挑战你的！', `FemaleText_loc5`='我在這裡向你挑戰!', `FemaleText_loc7`='¡He venido a enfrentarme a ti!' WHERE `ID`=62607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐야, 마음이 변한 거예요? 이해해요. 나라도 나와는 싸우기 싫을 테니까.', `FemaleText_loc4`='怎么，你改变主意了？我自己也知道，跟一个像我这样的人挑战不是什么好主意。', `FemaleText_loc5`='什麼，你改變心意了?我了解。換做是我自己，也不想跟我戰鬥。', `FemaleText_loc7`='Cómo, ¿has cambiado de idea? Lo entiendo. Yo tampoco querría enfrentarme a alguien como yo.' WHERE `ID`=62608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 해 봅시다.', `MaleText_loc4`='让我们开始吧。', `MaleText_loc5`='我們打吧。', `MaleText_loc7`='Adelante.', `FemaleText_loc1`='한번 해 보죠.', `FemaleText_loc4`='让我们开始吧。', `FemaleText_loc5`='我們打吧。', `FemaleText_loc7`='Adelante.' WHERE `ID`=62609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼요!', `MaleText_loc4`='放马过来吧！', `MaleText_loc5`='來吧!', `MaleText_loc7`='¡Ven por mí!', `FemaleText_loc1`='덤벼요!', `FemaleText_loc4`='放马过来吧！', `FemaleText_loc5`='來吧!', `FemaleText_loc7`='¡Ven por mí!' WHERE `ID`=62610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이, 겨우 요 정도예요?', `MaleText_loc4`='来吧，你就这点能耐？', `MaleText_loc5`='來啊，你就只有這點本事嗎?', `MaleText_loc7`='¡Vamos! ¿Es todo lo que sabes hacer?', `FemaleText_loc1`='에이, 겨우 요 정도예요?', `FemaleText_loc4`='来吧，你就这点能耐？', `FemaleText_loc5`='來啊，你就只有這點本事嗎?', `FemaleText_loc7`='¡Vamos! ¿Es todo lo que sabes hacer?' WHERE `ID`=62611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그보단 잘해야죠!', `MaleText_loc4`='使出你的看家本事来！', `MaleText_loc5`='再加把勁啊你!', `MaleText_loc7`='¡Seguro que puedes hacerlo mejor!', `FemaleText_loc1`='그보단 잘해야죠!', `FemaleText_loc4`='使出你的看家本事来！', `FemaleText_loc5`='再加把勁啊你!', `FemaleText_loc7`='¡Seguro que puedes hacerlo mejor!' WHERE `ID`=62612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보기보단 강하군요.', `MaleText_loc4`='你比你看起来要厉害。', `MaleText_loc5`='看不出來你還挺厲害的。', `MaleText_loc7`='Pegas más fuerte de lo que esperaba.', `FemaleText_loc1`='보기보단 강하군요.', `FemaleText_loc4`='你比你看起来要厉害。', `FemaleText_loc5`='看不出來你還挺厲害的。', `FemaleText_loc7`='Pegas más fuerte de lo que esperaba.' WHERE `ID`=62613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히... 정말 멋진 대결이었어요.', `MaleText_loc4`='我承认……这场战斗让人印象深刻。', `MaleText_loc5`='我承認...你的確是有兩下子。', `MaleText_loc7`='Admito que ha sido un combate excelente.', `FemaleText_loc1`='솔직히... 정말 멋진 대결이었어요.', `FemaleText_loc4`='我承认……这场战斗让人印象深刻。', `FemaleText_loc5`='我承認...你的確是有兩下子。', `FemaleText_loc7`='Admito que ha sido un combate excelente.' WHERE `ID`=62614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 한 번 싸워 봤으니까, 정한 거예요. 우린 친구예요!', `MaleText_loc4`='好吧，不打不相识。我们现在是朋友了！', `MaleText_loc5`='好，不打不相識。我們以後就是朋友了!', `MaleText_loc7`='Bueno, ahora que hemos luchado, ¡somos camaradas!', `FemaleText_loc1`='자, 한 번 싸워 봤으니까, 정한 거예요. 우린 친구예요!', `FemaleText_loc4`='好吧，不打不相识。我们现在是朋友了！', `FemaleText_loc5`='好，不打不相識。我們以後就是朋友了!', `FemaleText_loc7`='Bueno, ahora que hemos luchado, ¡somos camaradas!' WHERE `ID`=62615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원하신다면 언제라도 다시 대결해 드릴게요.', `MaleText_loc4`='只要你需要，我都愿意和你再战一回。', `MaleText_loc5`='只要你需要，我很樂意再跟你對戰。', `MaleText_loc7`='Estaré encantada de volver a luchar contigo cuando quieras.', `FemaleText_loc1`='원하신다면 언제라도 다시 대결해 드릴게요.', `FemaleText_loc4`='只要你需要，我都愿意和你再战一回。', `FemaleText_loc5`='只要你需要，我很樂意再跟你對戰。', `FemaleText_loc7`='Estaré encantada de volver a luchar contigo cuando quieras.' WHERE `ID`=62616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 약한 맥주를 스타우트 맥주와 섞으면...

아, 그래. 안녕하신가!', `MaleText_loc4`='嗯……如果我将一些淡酒和烈酒混合……

哦，我的天。瞧瞧这玩意儿！', `MaleText_loc5`='嗯...如果你把一些蒼白混合在...

喔，對了。哈囉!', `MaleText_loc7`='Mmm... Si mezclo algo de rubia con negr... 

Ah, ¡hola!' WHERE `ID`=62617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 저와 같이 가 주셨으면 합니다.', `MaleText_loc4`='我希望你今天能跟着我。', `MaleText_loc5`='我希望你今天跟我一起來。', `MaleText_loc7`='Hoy quiero que vengas conmigo.', `FemaleText_loc1`='오늘 저와 같이 가 주셨으면 해요.', `FemaleText_loc4`='我希望你今天能跟着我。', `FemaleText_loc5`='我希望你今天跟我一起來。', `FemaleText_loc7`='Hoy quiero que vengas conmigo.' WHERE `ID`=62618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하러 왔습니다!', `MaleText_loc4`='我是来挑战你的！', `MaleText_loc5`='我在這裡向你挑戰!', `MaleText_loc7`='¡He venido a enfrentarme a ti!', `FemaleText_loc1`='도전하러 왔어요!', `FemaleText_loc4`='我是来挑战你的！', `FemaleText_loc5`='我在這裡向你挑戰!', `FemaleText_loc7`='¡He venido a enfrentarme a ti!' WHERE `ID`=62619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 질문이 있습니다.', `MaleText_loc4`='我另外有个问题。', `MaleText_loc5`='我有個不同的問題。', `MaleText_loc7`='Tengo una pregunta distinta.', `FemaleText_loc1`='다른 질문이 있어요.', `FemaleText_loc4`='我另外有个问题。', `FemaleText_loc5`='我有個不同的問題。', `FemaleText_loc7`='Tengo una pregunta distinta.' WHERE `ID`=62620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 손님이군! 판다리아에 이런 날이 올 줄이야. 안개가 걷히고, 세상과 다시 만났지. 싸우러 온 건 아니면 좋겠는데?', `MaleText_loc4`='一位访客！潘达利亚正在非常时期——迷雾散去，再次现世。你应该是为了和平而来的吧？', `MaleText_loc5`='啊，有訪客!這是潘達利亞的重要時刻...迷霧已經散去，我們回歸世界。你不是來打仗的，對吧?', `MaleText_loc7`='¡Ah, tengo visita! Es una época increíble para Pandaria: la niebla se ha disipado y volvemos al mundo. ¡Espero que vengas en son de paz!' WHERE `ID`=62621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF00dc29시크티크 무리전사|r 한 무리와 |cFF815d18시크티크 전사|r 하나가 전투에 참여합니다.', `MaleText_loc4`='一波|cFF00dc29希克提克虫群|r和|cFF815d18希克提克战士|r加入了战斗。', `MaleText_loc5`='一群|cFF00dc29西克席克雄兵|r和一個|cFF815d18西克席克戰士|r加入戰場。', `MaleText_loc7`='Una horda de |cFF00dc29enjambristas Sik''thik|r y un |cFF815d18guerrero Sik''thik|r se unen a la batalla.' WHERE `ID`=62622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFB600B8시크티크 파괴병|r 한 무리와 |cFF815d18시크티크 전사|r 하나가 전투에 참여합니다.', `MaleText_loc4`='一波|cFFB600B8希克提克毁灭者|r和|cFF815d18希克提克战士|r加入了战斗。', `MaleText_loc5`='一群|cFFB600B8西克席克石毀者|r和一個|cFF815d18西克席克戰士|r加入戰場。', `MaleText_loc7`='Una horda de |cFFB600B8demoledores Sik''thik|r y un |cFF815d18guerrero Sik''thik|r se unen a la batalla.' WHERE `ID`=62623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런. 반갑군, 이방인! 내 꿈결 맥주를 맛봤나? 그 환영은 해석 불가야. 절반의 진실과 절반의 환상, 어느 게 어느 건지 누가 알겠나?', `MaleText_loc4`='啊，你好，陌生人！洄梦仙酒味道如何？酒不醉人人自醉，雾里看花花非花。半梦半醒，谁是谁非？', `MaleText_loc5`='唉呀唉呀，你好啊，陌生人!你嚐過了我的夢幻之釀，對嗎?它的幻象不容易解讀:一半真，一半假。誰能區分虛與實呢?', `MaleText_loc7`='Vaya, vaya. ¡Hola! ¿Has probado mi brebaje de ensueño? Las visiones que provoca son difíciles de interpretar; en parte realidad y en parte ilusión. ¿Pero cómo distinguirlas?' WHERE `ID`=62624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 함께 걷지. 서로에게서 배울 수 있을 것 같군. 자네들, 정원 가꾸는 거 좋아하나?', `MaleText_loc4`='你我相识一场，不如陪我走走。你们那儿的人可喜欢园艺？', `MaleText_loc5`='跟我來，讓我們交流一下。你們的族人喜歡園藝嗎?', `MaleText_loc7`='Paseemos juntos y aprendamos el uno del otro. ¿Tu pueblo aprecia la jardinería?' WHERE `ID`=62625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 몰아내려 한다! 공중 지원 실시!', `MaleText_loc4`='他们令我们无法接近！快派空中支援！', `MaleText_loc5`='他們在拖延我們，派遣空中支援!', `MaleText_loc7`='¡Se resisten! ¡Traigan el apoyo aéreo!' WHERE `ID`=62626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박날개, 가라! 저항군들을 쓸어버려!', `MaleText_loc4`='琥珀之翼，快去！围歼那些抵抗者！', `MaleText_loc5`='琥珀之翼進攻!把抵抗的人包圍起來!', `MaleText_loc7`='Alacárabe, ¡ven aquí! ¡Asedia a los rebeldes!' WHERE `ID`=62627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 정원용 가위 하나를 건네주며 커다랗고 다듬어지지 않은 나무를 가리킵니다.', `MaleText_loc4`='%s递给你一把剪刀，指着一棵未经修剪的高大树木。', `MaleText_loc5`='%s遞給你一雙大剪刀，並朝一棵巨大而亂七八糟的大樹比了比。', `MaleText_loc7`='%s te entrega unas tijeras de podar y señala un gran árbol descuidado.' WHERE `ID`=62628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내면의 어둠을 느껴라!', `MaleText_loc4`='感受其中的黑暗吧！', `MaleText_loc5`='感受內心的黑暗!', `MaleText_loc7`='¡Siente la oscuridad interior!' WHERE `ID`=62629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 섬세한 손질이지. 나무의 뜻에 따라야 하네.', `MaleText_loc4`='好极了，完美的修剪。所谓顺木之天，以致其性。', `MaleText_loc5`='這就對了，精緻的修剪。讓樹木自己做主。', `MaleText_loc7`='Eso es, cortes delicados. Deja que el árbol decida.' WHERE `ID`=62630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자기 마음에 들지 않는 것은 모두 잘라버리는 이도 있지만, 그랬다간 나무의 가치를 죽이고 만다네. 그건 판다렌 방식이 아니야.', `MaleText_loc4`='有些人觉得哪里不如意就剪掉，那实在是取了这棵树的性命。此绝非熊猫人处世之道。', `MaleText_loc5`='有些人拿起刀子，把不喜歡的枝葉全砍了，可是這樣會毀了整株樹。這不是熊貓人的做法。', `MaleText_loc7`='Algunos usan el cuchillo para podar todo lo que no les gusta, pero eso mataría al árbol. Y ese no es el estilo pandaren.' WHERE `ID`=62631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 보게! 이런 아름다움이 숨어 있다고 누가 알았겠나? 자네의 그 "얼라이언스"도 주위 세계를 섬세하게 손질하여 변화시키고 있군. 재미있어.', `MaleText_loc4`='哦看呐，谁又能知道如此美丽的东西藏于此中呢？看来你们联盟善于通过精心的修剪来改变周围的世界。真有趣。', `MaleText_loc5`='哇!誰料得到這裡藏了個這麼美麗的東西!我明白了，你們這個「聯盟」以精準的手段改變周圍的世界。有意思。', `MaleText_loc7`='¡Vaya! ¿Quién hubiera dicho que algo tan bonito se ocultaba en este lugar? Veo que esta "Alianza" tuya corta con precisión para moldear el mundo que nos rodea. Interesante.' WHERE `ID`=62632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 "전승지기"네. 판다렌에게는... 일종의 역사가지. 내 도구는 언어, 말이야.', `MaleText_loc4`='我是一个“游学者”——为我的人民跋涉历史的长河。我擅于运用言辞的力量。', `MaleText_loc5`='我是個「博學行者」─算是我們族人的歷史學家。語言就是我的工具。', `MaleText_loc7`='Soy un "eremita": una especie de historiador para mi pueblo. Mi instrumento es la palabra.' WHERE `ID`=62633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안타깝게도, 내 예술적 재능이 조금 부족하군. 자네라면 여기 벽을 어떻게 장식하겠나?', `MaleText_loc4`='不幸的是，我的——呃——艺术天赋相对匮乏。你觉得我该怎么装饰这高墙？', `MaleText_loc5`='遺憾的是，呃，我的藝術修養不太夠。是你的話會怎麼裝飾我的牆壁呢?', `MaleText_loc7`='Por desgracia, carezco de talentos artísticos. ¿Qué harías tú para decorar esta pared?' WHERE `ID`=62634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아는 얼굴이군. 뭘 배워 왔는지 한번 볼까.', `MaleText_loc4`='噢，对。我记得你。让我们瞧瞧你学会了什么。', `MaleText_loc5`='喔對，我記得你，來看看你學了些什麼。', `MaleText_loc7`='Ah, sí. Me acuerdo de ti. Veamos lo que has aprendido.' WHERE `ID`=62635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 도전한다고? 어디 솜씨 좀 볼까.', `MaleText_loc4`='来次挑战，哈？看看你有什么本事。', `MaleText_loc5`='挑戰是嗎?來看看你的本領吧。', `MaleText_loc7`='¿Un desafío? A ver de qué eres capaz.' WHERE `ID`=62636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔한 기술은 안 썼으면 좋겠군.', `MaleText_loc4`='希望你的招式不会让人一眼看穿。', `MaleText_loc5`='希望你的行動不會輕易被看穿。', `MaleText_loc7`='Espero que tu técnica no sea demasiado predecible.' WHERE `ID`=62637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그 기술을 써 보겠다고? 해 보게!', `MaleText_loc4`='噢，你想试试那招？来吧！', `MaleText_loc5`='喔，你想試試看那個嗎?上吧!', `MaleText_loc7`='Ah, ¿vas a probar con ese movimiento? ¡Por favor!' WHERE `ID`=62638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그러나? 싸우는 방법을 잊었나?', `MaleText_loc4`='怎么了，你忘记怎么出招了？', `MaleText_loc5`='怎麼了，你忘了該如何戰鬥了嗎?', `MaleText_loc7`='¿Qué pasa? ¿Olvidaste cómo se lucha?' WHERE `ID`=62639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아... 꽤 괜찮은 솜씨였네.', `MaleText_loc4`='好吧…这招还不错。', `MaleText_loc5`='好吧...這招還不賴。', `MaleText_loc7`='De acuerdo... Eso estuvo bastante bueno.' WHERE `ID`=62640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 처음 보는 기술이군. 이제 보니 정말 잘 싸우는데.', `MaleText_loc4`='哇哦！我以前从来没见过那招。看来你确实不赖。', `MaleText_loc5`='哇喔!這招我還真沒見過。我想你真的是相當不賴。', `MaleText_loc7`='¡Vaya! Eso no lo había visto nunca. Parece que sabes lo que haces.' WHERE `ID`=62641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네, 함께 가지. 자네 기술을 연구해야 하니까!', `MaleText_loc4`='当然，我跟你走。还得研究一下你的招式呢！', `MaleText_loc5`='當然，我會跟你一起走，我要研究你的招式!', `MaleText_loc7`='Claro que iré contigo. ¡Tengo que estudiar tus movimientos!' WHERE `ID`=62642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있으니 필요하면 부르게.', `MaleText_loc4`='任何时候只要你需要我，我都在这儿。', `MaleText_loc5`='無論何時，我都會在這裡。', `MaleText_loc7`='Estaré allá donde me necesites.' WHERE `ID`=62643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래? 좋지! 자네 실력을 얼른 보고 싶군.', `MaleText_loc4`='好了？出发！我迫切的想知道你有点什么本领。', `MaleText_loc5`='如何?我們走吧!我很想看看你有幾兩重。', `MaleText_loc7`='¿Y bien? ¡Vamos! Tengo ganas de ver qué guardas.' WHERE `ID`=62644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 해 보지요!', `MaleText_loc4`='好的，让我们开始吧！', `MaleText_loc5`='好了，我們開始吧!', `MaleText_loc7`='Adelante.', `FemaleText_loc1`='좋아요. 해 봐요!', `FemaleText_loc4`='好的，让我们开始吧！', `FemaleText_loc5`='好了，我們開始吧!', `FemaleText_loc7`='Adelante.' WHERE `ID`=62645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무 말도 하지 말게. 그림으로 표현해 보게. 판다렌은 아름다움을 좋아하고, 또 주위 모든 곳에서 찾네.', `MaleText_loc4`='不必说话。你的存在即是表达。我们熊猫人崇尚至美，而至美就存在于我们身边：', `MaleText_loc5`='一個字也別說。讓你的形象說話。我們熊貓人以美為尊，美存在於我們的周遭。', `MaleText_loc7`='No digas nada. Deja que hable tu imagen. Los pandaren apreciamos la belleza y la encontramos en todas partes.' WHERE `ID`=62646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구부러진 나무와, 떠오르는 태양의 색, 전사의 격렬하고 완벽한 칼부림에서도.', `MaleText_loc4`='枝干的曲线，旭日的色彩，甚至是武士舞出剑弧的完美瞬间。', `MaleText_loc5`='樹木的曲線，黎明的色彩，甚至是戰士優雅劍法中的完美姿態。', `MaleText_loc7`='En las curvas de un árbol, en los colores de un amanecer o incluso en la forma perfecta de una espada exquisitamente forjada.' WHERE `ID`=62647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기도 그림 실력은 많이 부족하다네. 자네가 더 잘할 수 있지 않을까?', `MaleText_loc4`='游学者的技艺不够精妙，缺少专业的技术指导。 也许你能做得更好？', `MaleText_loc5`='博學行者在藝術方面不僅缺乏精緻度，也毫無專業技巧。或許你能做得更好?', `MaleText_loc7`='El arte del eremita carece de sutileza y destreza técnica. Quizás tú puedas hacerlo mejor.' WHERE `ID`=62648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<안두인 왕자의 초상화를 그립니다.>', `MaleText_loc4`='<画一幅安度因王子的肖像画。>', `MaleText_loc5`='<幫安杜因王子畫肖像。>', `MaleText_loc7`='<Pinta un retrato del príncipe Anduin.>', `FemaleText_loc1`='<안두인 왕자의 초상화를 그립니다.>', `FemaleText_loc4`='<画一幅安度因王子的肖像画。>', `FemaleText_loc5`='<幫安杜因王子畫肖像。>', `FemaleText_loc7`='<Pinta un retrato del príncipe Anduin.>' WHERE `ID`=62649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물이여, 일어나라! 놈들의 살을 마음껏 뜯어라!', `MaleText_loc4`='起来吧，我的宠物们！去吃了他们！', `MaleText_loc5`='醒來吧我的寵物!啃食他們的血肉!', `MaleText_loc7`='¡Despierten, mascotas mías! ¡Dénse un festín con su carne!' WHERE `ID`=62650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 손으로 너를 끝장내고 말겠다!', `MaleText_loc4`='我要亲眼见证你的死亡！', `MaleText_loc5`='我會親手幹掉你!', `MaleText_loc7`='¡Yo mismo me encargaré de acabar contigo!' WHERE `ID`=62651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 누구지? 왕자라고? 아이로군. 하지만 어린 시절이 없었어. 눈을 보면 알 수 있네.', `MaleText_loc4`='这是谁啊？什么王子？一个孩子。啊，一个没有童年的孩子——他的眼神告诉我了。', `MaleText_loc5`='這是誰?你說他是王子?還是個孩子。啊，可是他沒有童年─從他的眼裡就看得出來。', `MaleText_loc7`='¿Quién es ese? ¿Un príncipe, dices? Un niño. Ah, pero no ha tenido infancia, me lo dicen sus ojos.' WHERE `ID`=62652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들은 아주 어린 아이에게도 많은 것을 요구하는군.', `MaleText_loc4`='我感到你们从很小的时候就开始崇拜伟大的东西。', `MaleText_loc5`='可見你們族人有著遠大的期望，即使對小孩也是。', `MaleText_loc7`='Veo que tu gente espera grandes cosas, incluso de los jóvenes.' WHERE `ID`=62653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 일은 거의 끝났네. 이리 와서 내 이국적인 새들을 보게. 어디, 자네가 먹이를 주면 어떨까.', `MaleText_loc4`='我的任务就快完成了。来吧，来看看我收养的珍禽异鸟。能喂喂它们可是你的福气哦。', `MaleText_loc5`='我的差事快告一段落了。來吧，看看我收藏的珍貴鳥兒。你將有榮幸可以餵餵牠們。', `MaleText_loc7`='Ya casi he terminado mis tareas. Ven a ver mi colección de pájaros exóticos. Te concederé el honor de alimentarlos.' WHERE `ID`=62654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자 놈아! 호박석은 우리 것이다! 사마귀를 위한 게 아니야!', `MaleText_loc4`='这琥珀是我们的，闯入者！琥珀不是给螳螂妖准备的！', `MaleText_loc5`='這個琥珀是我們的，入侵者!螳螂人沒資格使用琥珀!', `MaleText_loc7`='¡Este ámbar es nuestro, $gintruso:intrusa;! ¡El ámbar no es para los mántides!' WHERE `ID`=62655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 용장은 여제님의 것이다! 너는 가질 수 없어!', `MaleText_loc4`='这个英杰是女皇的！ 你休想得到他！', `MaleText_loc5`='這個聖螳是要給女皇的!你不能取走它!', `MaleText_loc7`='¡Este dechado es para la Emperatriz! ¡No para ti!' WHERE `ID`=62656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 전승지기라고 하네. 판다렌의... 역사가라고 할 수 있지.', `MaleText_loc4`='我被称作游学者——可以说是我们熊猫人里的史学家。', `MaleText_loc5`='我被稱為博學行者...是我們人民的歷史學家。', `MaleText_loc7`='Soy lo que llaman un "eremita"; una especie de historiador para mi pueblo.' WHERE `ID`=62657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 군단과 싸우라고 클락시가 너를 보냈단 말인가? 그렇게 강인한 클락시가 이렇게 변하다니. 덤벼라 꼬맹아. 할 수 있으면 용장을 데려가 봐라!', `MaleText_loc4`='卡拉克西派你去对付虫群？ 啊，如此强大的人居然堕落到这个地步。 过来，小朋友。 如果可以的话，请带上这位英杰！', `MaleText_loc5`='卡拉西派你來對抗蟲群?啊，強大的他竟墮落到這種程度。來吧，小蒼蠅。來取得聖螳，如果你辦得到的話!', `MaleText_loc7`='¿Te han enviado los Klaxxi para enfrentarte al enjambre? Ay, cómo han caído los grandes... Ven, mosquito. Ven a por el dechado, ¡si puedes!' WHERE `ID`=62658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 따라오게, 여행자여. 서로에 대해 조금 더 알아보세.', `MaleText_loc4`='跟着我，旅行者。让我们彼此多了解一下对方。', `MaleText_loc5`='跟我來，旅行者。讓我們更進一步了解彼此。', `MaleText_loc7`='Sígueme, viajero. Quiero que nos conozcamos mejor.' WHERE `ID`=62659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 대전으로 겨루어 보시겠습니까? 한 판 붙읍시다!', `MaleText_loc4`='你以为你能在宠物战斗中胜过我？让我们开始吧！', `MaleText_loc5`='你能在寵物對戰中贏過我嗎?來戰鬥吧!', `MaleText_loc7`='¿Crees que puedes vencerme en un duelo de mascotas? ¡Luchemos!', `FemaleText_loc1`='애완동물 대전으로 겨루어 보시겠어요? 한 판 붙어 보죠!', `FemaleText_loc4`='你以为你能在宠物战斗中胜过我？让我们战斗吧！', `FemaleText_loc5`='你能在寵物對戰中贏過我嗎?來戰鬥吧!', `FemaleText_loc7`='¿Crees que puedes vencerme en un duelo de mascotas? ¡Luchemos!' WHERE `ID`=62660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 싸워봅시다!', `MaleText_loc4`='让我们来大战一场吧！', `MaleText_loc5`='戰吧!', `MaleText_loc7`='¡A pelear!', `FemaleText_loc1`='한번 싸워봐요!', `FemaleText_loc4`='让我们来大战一场吧！', `FemaleText_loc5`='戰吧!', `FemaleText_loc7`='¡A pelear!' WHERE `ID`=62661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지식이 나를 지켜주고, 나는 검 대신 붓을 휘두른다네.', `MaleText_loc4`='也可以说，知识是我的护甲，羽毛笔就是我的利剑。', `MaleText_loc5`='所以，知識就是我的盔甲，而筆呢，就是我的劍。', `MaleText_loc7`='Como tal, mi armadura es el saber y mi arma es la pluma, no la espada.' WHERE `ID`=62662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 과거는 수수께끼와 같은 장막에 싸여 있네.', `MaleText_loc4`='潘达利亚的历史甚至对我们来说都笼罩着迷雾。', `MaleText_loc5`='潘達利亞的過去，連我們都覺得很神秘。', `MaleText_loc7`='Gran parte del pasado de Pandaria es un misterio, hasta para nosotros.' WHERE `ID`=62663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러려면 쉬지 않고 고대의 실마리를 찾고, 이를 해석할 지혜를 쌓아야 하네.', `MaleText_loc4`='这需要我们不倦地探索远古留下的线索，用智慧来揭示真相。', `MaleText_loc5`='這需要無止境地尋找古老的線索，和解譯線索的智慧。', `MaleText_loc7`='Tal deber exige una búsqueda incansable de rastros antiguos y la astucia para descifrarlos.' WHERE `ID`=62664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 다 왔군. 조심하게. 전에 여기서 곤란한 일이 있었으니까.', `MaleText_loc4`='啊，我们到了。小心——我曾经在这个地方遇到过麻烦。', `MaleText_loc5`='啊，我們到了。小心，我曾經在這一帶遇過麻煩。', `MaleText_loc7`='Ah, ya llegamos. Ten cuidado; no sería la primera vez que esta zona me da problemas.' WHERE `ID`=62665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='졌습니다. 계속 가시겠다면, 산꼭대기에 있는 도장에서 사부 스노우드리프트를 찾으십시오.', `MaleText_loc4`='你已经胜过我了。如果你还想继续前行，就到山顶的道场去找雪流大师吧。', `MaleText_loc5`='你已擊敗了我。如果你想繼續前進，就到山頂的道場去找雪迅大師。', `MaleText_loc7`='Me has derrotado. Busca al maestro Ventisca Algente en el dojo de lo alto de la montaña si quieres seguir adelante.', `FemaleText_loc1`='졌습니다. 계속 가시겠다면, 산꼭대기에 있는 도장에서 사부 스노우드리프트를 찾으십시오.', `FemaleText_loc4`='你已经胜过我了。如果你还想继续前行，就到山顶的道场去找雪流大师吧。', `FemaleText_loc5`='你已擊敗了我。如果你想繼續前進，就到山頂的道場去找雪迅大師。', `FemaleText_loc7`='Me has derrotado. Busca al maestro Ventisca Algente en el dojo de lo alto de la montaña si quieres seguir adelante.' WHERE `ID`=62666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:123244|h[숨기]|h|r를 시전합니다!', `MaleText_loc4`='%s施放了|cFFFF0000|Hspell:123244|h[隐藏]|h|r！', `MaleText_loc5`='%s施放|cFFFF0000|Hspell:123244|h[隱藏]|h|r!', `MaleText_loc7`='¡%s lanza |cFFFF0000|Hspell:123244|h[Esconderse]|h|r!' WHERE `ID`=62667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...마침내... 내 시간이 왔구나.', `MaleText_loc4`='终……于……我的时代来临了。', `MaleText_loc5`='終...於...我的時候到了。', `MaleText_loc7`='Por... fin... ha llegado el momento.' WHERE `ID`=62668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할 일이 아주 많다. 하지만 깨우는 자여... 그보다 먼저 내가 힘을 회복하도록 도와다오.', `MaleText_loc4`='有很多事情要做。不过首先，唤醒者……帮助我恢复体力。', `MaleText_loc5`='還有許多事要做。但首先，喚醒者...幫我取回我的力量。', `MaleText_loc7`='Hay... mucho que hacer. Pero antes, heraldo... ayúdame a recobrar... mi fuerza.' WHERE `ID`=62669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기의 임무는 역사를 다시 발견하고, 그 장막을 하나씩 벗겨내는 거야.', `MaleText_loc4`='游学者的使命就是要让历史重见天日——将迷雾一团一团地驱散。', `MaleText_loc5`='博學行者的責任就是重新發掘我們的歷史...一步步地把迷霧撥開。', `MaleText_loc7`='El deber sagrado de un eremita es redescubrir nuestra historia: develar el misterio, parte por parte.' WHERE `ID`=62670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:123461|h[저리 가!]|h|r를 시전합니다!', `MaleText_loc4`='%s施放了|cFFFF0000|Hspell:123461|h[滚开！]|h|r', `MaleText_loc5`='%s施放|cFFFF0000|Hspell:123461|h[滾開!]|h|r', `MaleText_loc7`='%s lanza |cFFFF0000|Hspell:123461|h[¡Aléjense!]|h|r' WHERE `ID`=62671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 본지도 여러 해가 지났구나, 깨우는 자여. 많은 것이 변했다.', `MaleText_loc4`='我上次看到这个地方，已经是很多年前了，唤醒者。很多东西都变了。', `MaleText_loc5`='距離我上次看到這個地方已經過去許多年了，喚醒者。改變真大。', `MaleText_loc7`='Hacía muchos años que no veía este lugar, heraldo. Han cambiado muchas cosas.' WHERE `ID`=62672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화 제어소로 가려면 어서 빨리 일을 마쳐야 한다.', `MaleText_loc4`='我们必须尽快工作，让这个信标重新运作起来。', `MaleText_loc5`='我們得快點讓信號塔開始運作。', `MaleText_loc7`='Debemos trabajar rápidamente para que la baliza vuelva a estar operativa.' WHERE `ID`=62673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 그렇지. 호박석의 맛을 잊지 않은 거군.', `MaleText_loc4`='嗯。琥珀的味道让人难以忘怀。', `MaleText_loc5`='啊，沒錯。沒有人忘得了琥珀的滋味。', `MaleText_loc7`='Ah, sí. El sabor del ámbar no se olvida.' WHERE `ID`=62674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 눈이 어떻게 된 건가? 저 멀리 있는 벽은 뭐지?', `MaleText_loc4`='我的眼睛欺骗了我？远处的城墙是怎么回事？', `MaleText_loc5`='我看錯了嗎?在遠方的那個是長城嗎?', `MaleText_loc7`='¿Me engañan los ojos? ¿Qué es esa muralla que se ve en la distancia?' WHERE `ID`=62675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상이 아직 성숙하지 않을 때, 첫 번째 키파리 나무가 자라났다.', `MaleText_loc4`='遥想混沌初开之时，第一批凯帕圣树花开如锦。', `MaleText_loc5`='過去，當世界還很年輕，第一棵奇帕利樹盛開的時候。', `MaleText_loc7`='Allá cuando el mundo aún era joven florecieron los primeros árboles kypari.' WHERE `ID`=62676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무에서 호박석이 흘러나와 우리에게 양분을 줬지. 우리는 그것을 대지의 생명이 담긴 피란 뜻의 키파라이트라고 불렀다.', `MaleText_loc4`='那些树上流出的琥珀养育了我们。 我们把它叫做凯帕琥珀，大地的血液。', `MaleText_loc5`='從那些樹中流出的琥珀哺育了我們。我們稱之為奇帕利，大地的命脈。', `MaleText_loc7`='De estos árboles fluía el ámbar que nos servía de alimento. Kyparita, lo llamábamos, la sangrevida de la tierra.' WHERE `ID`=62677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키파라이트는 우리의 상처를 치유해주고, 용감하게 만들어줬다. 그 맛은 달콤하고도 화끈거렸으며, 우리가 다른 열등한 종족들을 정복할 힘을 주었다.', `MaleText_loc4`='它治愈我们的伤口，强健我们的身体。它尝起来芳香中带着火辣，它赐予我们力量来征服其他弱小的种族。', `MaleText_loc5`='它治癒我們受的傷，並讓我們變得勇敢。它嚐起來既甜蜜又熾熱，並給我們力量去征服其他低等種族。', `MaleText_loc7`='Curaba nuestras heridas y nos hacía audaces. Sabía a dulzura y a fuego, y nos daba fuerzas para conquistar a las razas inferiores.' WHERE `ID`=62678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러라, 깨우는 자여. 고대의 호박석이 내 힘을 계속 빨아들인다. 이젠 너 조차도 처치할 힘이 없구나.', `MaleText_loc4`='快点，唤醒者。我得竭力克制自己才能不把你撕成碎片。', `MaleText_loc5`='快點，喚醒者。我得用盡全身的力氣，才能克制自己不要把你撕成碎片。', `MaleText_loc7`='Date prisa, heraldo. Me está costando horrores no hacerte pedazos.' WHERE `ID`=62679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어가 정말 많이 바뀌었구나. 이곳이 어딘지 알 수가 없다.', `MaleText_loc4`='卡利姆多改变了很多。我都不认识这个地方了。', `MaleText_loc5`='卡林多變了很多。我都認不得這個地方了。', `MaleText_loc7`='Kalimdor ha cambiado mucho. No reconozco este lugar.' WHERE `ID`=62680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 탑이 무너진 건가? 내 형제들의 소리가 하나도 들리지 않는다.', `MaleText_loc4`='古塔倒塌了吗？ 我从我的同胞那里听不到任何消息。', `MaleText_loc5`='古代高塔倒下了嗎?我聽不到我弟兄們的聲音。', `MaleText_loc7`='¿Han caído las torres ancestrales? No recibo noticias de mis hermanos.' WHERE `ID`=62681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 네가 나를 깨우러 온 건가? 클락시는 왜 그들의 일원을 보내지 않은 거지?', `MaleText_loc4`='你为何前来唤醒我？卡拉克西部族为何不派遣他们自己的成员前来？', `MaleText_loc5`='為什麼會派你來喚醒我?為什麼卡拉西不派他們自己的人來?', `MaleText_loc7`='¿Por qué te han mandado para despertarme? ¿Por qué los Klaxxi no han enviado a uno de los suyos?' WHERE `ID`=62682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 우리 부족의 성스러운 의식을 시작하겠다.', `MaleText_loc4`='我现在要举行我族人的神圣仪式。', `MaleText_loc5`='我現在將舉行我們人民的神聖儀式。', `MaleText_loc7`='Ahora llevaré a cabo el ritual sagrado de mi pueblo.' WHERE `ID`=62683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 있는 샤 생물이 제가 찾는 그늘을 가지고 있습니다... 물론 가까이 있는 야생 동물들에게서도 조금 찾을 수 있기는 합니다. 행운을 빌어드리죠!', `MaleText_loc4`='附近的煞魔生物有我需要的阴影……但是你也可以在附近的野生动物身上找到一些。 祝你好运！', `MaleText_loc5`='附近的煞之生物身上有我正在尋找的魔影...不過你在附近的野生動物身上或許也能找到一點。祝你好運!', `MaleText_loc7`='Las criaturas cercanas del sha poseen la sombra que estoy buscando... aunque podrías encontrar un poco en la fauna de los alrededores. ¡Buena suerte!' WHERE `ID`=62684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 정령을 부려 자기를 |cFFFF0000|Hspell:123250|h[보호]|h|r하게 합니다!', `MaleText_loc4`='%s召唤了一些元素来|cFFFF0000|Hspell:123250|h[保护]|h|r她！', `MaleText_loc5`='%s活化了一些元素來|cFFFF0000|Hspell:123250|h[保護]|h|r她!', `MaleText_loc7`='¡%s reanima varios elementales para |cFFFF0000|Hspell:123250|h[Protegerla]|h|r!' WHERE `ID`=62685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방심하지 마십시오.', `MaleText_loc4`='提高你的警惕，朋友。', `MaleText_loc5`='睜大眼睛，朋友。', `MaleText_loc7`='Mantén los ojos bien abiertos.' WHERE `ID`=62686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 다쳤습니까? 필요한 거라도 있습니까?', `MaleText_loc4`='你受伤了吗？你需要什么吗？', `MaleText_loc5`='你受傷了嗎?你需要什麼嗎?', `MaleText_loc7`='¿Te han herido? ¿Necesitas algo?' WHERE `ID`=62687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마십시오. 적이 언제 쳐들어올지 모릅니다.', `MaleText_loc4`='保持警惕。敌人随时可能发动攻击。', `MaleText_loc5`='保持警戒，敵人隨時會進行攻擊。', `MaleText_loc7`='Ten precaución. El enemigo puede atacar en cualquier momento.' WHERE `ID`=62688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잡담은 됐고 싸움이나 합시다.', `MaleText_loc4`='多战斗，少说话。', `MaleText_loc5`='多戰鬥，少說話。', `MaleText_loc7`='Mas pelea y menos hablar.', `FemaleText_loc1`='잡담은 됐고 싸움이나 하지요.', `FemaleText_loc4`='多战斗，少说话。', `FemaleText_loc5`='多戰鬥，少說話。', `FemaleText_loc7`='Menos cháchara y más lucha.' WHERE `ID`=62689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 왜 그래요?', `MaleText_loc4`='嗯？你想要什么？', `MaleText_loc5`='幹嘛?你想要什麼?', `MaleText_loc7`='¿Sí? ¿Qué quieres?', `FemaleText_loc1`='음? 왜 그래요?', `FemaleText_loc4`='嗯？你想要什么？', `FemaleText_loc5`='幹嘛?你想要什麼?', `FemaleText_loc7`='¿Sí? ¿Qué quieres?' WHERE `ID`=62690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가죠!', `MaleText_loc4`='出发！', `MaleText_loc5`='我們走吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='어서 가죠!', `FemaleText_loc4`='出发！', `FemaleText_loc5`='我們走吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=62691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 너는 내가 살던 시대의 사마귀 제국을 봤어야 한다. 우리의 세력은 눈이 닿을 수 있는 곳까지 아주 멀리 퍼져 나갔지.', `MaleText_loc4`='你真该看看我那个时候的螳螂帝国，唤醒者。我们的领土一直延伸到视线的尽头。', `MaleText_loc5`='你該看看在我那個時代的螳螂人帝國，喚醒者。我們的血脈一直延伸到你視線所能及之處。', `MaleText_loc7`='Deberías haber visto el imperio mántide en mis tiempos, heraldo. Nuestras vess llegaban hasta donde alcanzaba la vista.' WHERE `ID`=62692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴할 것이 있으면, 그 수를 헤아릴 수조차 없을 정도로 많은 사마귀가 하늘을 어둡게 만들었다.', `MaleText_loc4`='当毁灭的召唤降临，我族的大军遮天蔽日。', `MaleText_loc5`='當我們聽見劫掠的呼喚，我們龐大的數量連天空都能遮蔽。', `MaleText_loc7`='Cuando oímos la llamada de la devastación, oscurecimos los cielos con nuestras tropas.' WHERE `ID`=62693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 나를 호박석 안에서 잠들도록 뉘였을 때, 군단의 수많은 목소리가 내 이름을 외치는 것을 들었다. 하지만 지금은 그저 침묵뿐이구나.', `MaleText_loc4`='在他们让我沉眠于琥珀之前，我曾听过数百万计的虫群呼喊着我的名字。而现在，我什么都听不见。', `MaleText_loc5`='他們讓我進入琥珀沉睡之前，我聽到成千上萬的蟲群在呼喊我的名字。現在，我只聽見沉寂。', `MaleText_loc7`='Antes de que me durmieran en ámbar, escuché un millón de voces del enjambre pronunciando mi nombre. Ahora, lo único que oigo es el silencio.' WHERE `ID`=62694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기묘한 생물체는 무엇인가?', `MaleText_loc4`='这些奇怪的生物是什么？', `MaleText_loc5`='這些奇怪的生物是什麼?', `MaleText_loc7`='¿Qué son estas extrañas criaturas?' WHERE `ID`=62695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 호박석을 어디로 가져가는 거지? 대장간은 어디 있는 건가? 호박석을 만드는 이들은 어디 있지?', `MaleText_loc4`='他们把琥珀带去哪里了？熔炉在哪儿？琥珀锻工在哪儿？', `MaleText_loc5`='他們把琥珀運到哪去了?熔爐在哪裡?琥珀工匠又在哪裡?', `MaleText_loc7`='¿Adónde se llevan el ámbar? ¿Dónde están las forjas? ¿Dónde están los forjadores de ámbar?' WHERE `ID`=62696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석의 가치를 아는 이가 또 있는 것 같구나.', `MaleText_loc4`='看起来好像有其他人也发现了琥珀的价值。', `MaleText_loc5`='似乎還有其他人知道琥珀的價值。', `MaleText_loc7`='Parece que no somos los únicos conocedores del valor del ámbar.' WHERE `ID`=62697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와하아으르그러르럴브를', `MaleText_loc4`='哇呀呀呀呀', `MaleText_loc5`='哇咕啵嚕咕啵嚕', `MaleText_loc7`='WHHARRGLBLRRGLBRGL' WHERE `ID`=62698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기의 일은 매우 진중하다네, 나그네여.$b$b풍부한 지식을 활용해 사물의 본질을 꿰뚫어 보아야 하지.', `MaleText_loc4`='一名游学者的工作是沉重枯燥的，旅行者。$b$b他必须运用纷繁复杂的知识去认识事物的本质。', `MaleText_loc5`='博學行者的工作十分沉重，旅行者。$b$b他必須吸收豐富的知識以看見事物的本質。', `MaleText_loc7`='El trabajo de un eremita es lento y pesado, $gviajero:viajera;.$b$bUno ha de recurrir a una cantidad impresionante de conocimientos para ver las cosas tal cual son.' WHERE `ID`=62699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 여기가 어디지? 무슨 일이 일어난 건가?$B$B미안하구나. 내가 잠깐 잠이 들었다.', `MaleText_loc4`='嗯？我在哪儿？发生了什么？$B$B对不起，我一定是迷迷糊糊的睡着了。', `MaleText_loc5`='嗯?我在哪裡?發生什麼事?$B$B我很抱歉，我一定是睡著了。', `MaleText_loc7`='¿Eh? ¿Dónde estoy? ¿Qué ocurre?$B$BLo siento, debo de haberme quedado frito.' WHERE `ID`=62700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뒤로... 돌아!', `MaleText_loc4`='有关于……脸！', `MaleText_loc5`='關於...臉!', `MaleText_loc7`='En la... ¡kara!' WHERE `ID`=62701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유의 맥주가 옵니다! 가서 가져오세요!', `MaleText_loc4`='治愈佳酿来啦！来尝尝吧！', `MaleText_loc5`='治癒啤酒來了!快來拿!', `MaleText_loc7`='¡Brebaje sanador preparado! ¡Venid a por él!' WHERE `ID`=62702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 돌은 2,500년 전 이곳에 살았던 위대한 호젠 군주에 대한 이야기를 담고 있네. 자네들의 지도자는 어떤가? 시인인가? 전사인가? 언젠가 만나보고 싶군.', `MaleText_loc4`='这块石头讲述了两千五百年前一位伟大猢狲督军的故事。你们的领袖什么样？是诗人还是战士？我真想见见。', `MaleText_loc5`='這塊石頭記載了2500年前的一位偉大猴人戰將。你們的領袖像什麼?詩人?戰士?我希望有天能見見他們。', `MaleText_loc7`='Esta piedra habla de un gran señor de la guerra hozen que vivió aquí hace 2,500 años. ¿Cómo son tus líderes? ¿Poetas? ¿Guerreros? Me gustaría conocerlos algún día.' WHERE `ID`=62703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 이 무른피부 녀석!', `MaleText_loc4`='去死吧，软皮！', `MaleText_loc5`='死吧，軟皮傢伙!', `MaleText_loc7`='¡Muere, piel suave!' WHERE `ID`=62704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게! 사우록 약탈꾼이 다가오네!', `MaleText_loc4`='作好准备！蜥蜴人突袭者来了！', `MaleText_loc5`='準備好!薩烏洛克強盜來了!', `MaleText_loc7`='¡Prepárate! ¡Se acercan asaltantes saurok!' WHERE `ID`=62705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찬탈자들이 세상을 다시 만든 뒤로는 많은 세력이 우리 종족을 위협했다. 앞으로 나아갈 길은 좁기만 했지.', `MaleText_loc4`='自从篡位者改变了世界后，我们的种族就受到了很多威胁。前途渺茫。', `MaleText_loc5`='篡位者改造世界後，我們的種族面臨許多威脅。前方的道路十分狹窄。', `MaleText_loc7`='Muchas fueron las amenazas a las que se enfrentó nuestra raza después de que los usurpadores rehicieran el mundo. El camino se presentaba estrecho.' WHERE `ID`=62706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조상들은 그분이 부활을 보기 위해 먼 미래를 내다봤지만, 거기서 본 것은 수많은 위협에 처한 우리 종족이었다. 그 위험은 아직도 그대로이니, 우리를 멸망시킬 수도 있다.', `MaleText_loc4`='我们的祖先曾经看到了遥远的未来，看到了他的再生，但是我们看到的却是族人受到了诸多危险的困扰。 如果对这种危险置之不理，我们将会灭亡。', `MaleText_loc5`='我們的祖先預見未來他的重生，但相反的。我們見到我們種族遭遇許多危險。如果置之不理的話，這些危險可能會摧毀我們。', `MaleText_loc7`='Nuestros ancestros vieron el futuro para presenciar su renacimiento, pero en lugar de eso vieron a nuestra raza amenazada por muchos peligros. Peligros que, de no ser controlados, podrían destruirnos.' WHERE `ID`=62707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 가장 위대한 전사를 호박석에 넣어 잠재웠다가, 사마귀 군단이 정말 어려운 상황에 깨우도록 한 것은 내가 추천한 일이었다.', `MaleText_loc4`='是我建议我们最伟大的战士们进入琥珀休眠，然后在虫群最需要帮助的时候唤醒他们。', `MaleText_loc5`='是我提出建議，將我們最偉大的戰士封存在琥珀中沉睡，等到蟲群最需要的時刻再把他們喚醒。', `MaleText_loc7`='Fui yo quien sugirió que se introdujera a nuestros mejores guerreros en ámbar para dormir, y despertarlos cuando el enjambre sufriera su mayor necesidad.' WHERE `ID`=62708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 깨어날 수 없는 잠이었다. 거대한 위험이었지. 또한 거대한 희생이었다. 하지만 필요한 일이었다.', `MaleText_loc4`='这一觉睡下去，也许再也无法醒来。风险极高。代价极大。但却必须这么做。', `MaleText_loc5`='每個進入這種睡眠的人都有可能永遠無法甦醒。極大的風險，極大的犧牲。但有其必要。', `MaleText_loc7`='Era el sueño del que uno podría no despertar jamás. Era un gran riesgo, un gran sacrificio, pero era necesario.' WHERE `ID`=62709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서, 내가 첫 번째 용장이 되었다. 그래서 내가 시초자인 것이지.', `MaleText_loc4`='所以，我是第一个英杰。这也正是我为何是至尊者的原因。', `MaleText_loc5`='因此，我是第一個聖螳。這也是為什麼，我是「至高者」。', `MaleText_loc7`='De este modo, me convertí en el primer dechado, y por eso soy el Perfecto.' WHERE `ID`=62710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 지금, 클락시가 우리를 전투에 부르고 있다. 이제, 나는 깨어났다!', `MaleText_loc4`='现在，卡拉克西号召我们战斗。现在，我已从沉睡中苏醒。', `MaleText_loc5`='而現在，卡拉西呼喚我們上戰場。現在，我已甦醒。', `MaleText_loc7`='Y ahora los Klaxxi nos convocan para la batalla. Ya estoy despierto.' WHERE `ID`=62711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록은 모구의 시대부터 이 땅을 약탈해 왔네. 협상이 불가능한 종족이지만, 우린 계속해서 노력한다네! 다른 도리가 없을 때만 이렇게 싸우지.', `MaleText_loc4`='蜥蜴人从魔古时期以来就一直肆虐于这片土地。他们不可能与我们达成和解。但是，我们从未停止过尝试！战争只是下策。', `MaleText_loc5`='薩烏洛克自從魔古的年代就開始肆虐這裡。完全無法跟他們講理。但是，我們會嘗試下去!我們只會在不得已的時候動手。', `MaleText_loc7`='Los saurok plagan esta tierra desde la época de los mogu. No se puede negociar con ellos, ¡pero lo seguimos intentando! Solo los combatimos como último recurso.' WHERE `ID`=62712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 스의 상이 불길하게 일렁입니다.', `MaleText_loc4`='雷施的倒影荡起不祥的涟漪。', `MaleText_loc5`='蕾希的影像不祥地蕩漾。', `MaleText_loc7`='El reflejo de Lei Shi ondea de forma amenazadora.' WHERE `ID`=62713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 스의 상이 한 번 더 일렁입니다.', `MaleText_loc4`='她的倒影又再次震荡起来。', `MaleText_loc5`='她的影像第二次波動起來。', `MaleText_loc7`='Su reflejo ondea por segunda vez.' WHERE `ID`=62714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 나타납니다!', `MaleText_loc4`='%s出现了！', `MaleText_loc5`='%s出現了!', `MaleText_loc7`='¡%s aparece!' WHERE `ID`=62715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙네. 이 기록은 연구에 꼭 필요하다네. 자네들도 지식의 가치를 잘 알겠지? 그럴 거라고 믿네. 그렇게 거대한 비행선을 타고 왔으니 말이야.', `MaleText_loc4`='感谢你的帮助——这些笔记对我的研究至关重要。你的人民也同样重视知识吗？我想是的，因为你是乘坐一艘巨大的飞船来的。', `MaleText_loc5`='感謝你的幫忙。這些資料對我的研究很重要。你們也重視知識，對吧?我想也是，你們搭乘的飛船非常壯觀。', `MaleText_loc7`='Gracias por tu ayuda; estas notas son cruciales para mis estudios. Tu gente también valora el conocimiento, ¿verdad? Lo digo porque llegaron en una gran nave.' WHERE `ID`=62716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 필요한 건 모두 챙겼네. 어서, 저들이 돌아오기 전에 피하세!', `MaleText_loc4`='好了。快，我们得在他们回来之前继续前进。', `MaleText_loc5`='我已經準備好了。快，趁他們回來前快走吧!', `MaleText_loc7`='Tengo todo lo necesario. Rápido, ¡vámonos antes de que vuelvan!' WHERE `ID`=62717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌의 역사는 이 정도로 끝내지. 이제 자네 얘기를 하세.', `MaleText_loc4`='熊猫人的历史就说到这儿吧。谈谈你的种族，旅行者。', `MaleText_loc5`='聽夠熊貓人的歷史了。跟我說說你們的種族吧，旅行者。', `MaleText_loc7`='Pero ya basta de historia pandaren. Hablemos un poco sobre tu gente.' WHERE `ID`=62718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 행동을 보면서 이미 많은 것을 알았네. 자네에게선 젊은이의 열정과 노병의 경험이 함께 보이더군. 일생 동안 전장에서 살았겠지?', `MaleText_loc4`='仅仅观察你的动作，我已获益良多。你的招式既充满年轻人的热忱，又有老手的稳健。想必你是久经沙场了吧？', `MaleText_loc5`='我看著你的舉動已經了解到很多。你用年輕人的狂熱戰鬥，但擁有老兵的經驗。想必你一生都在戰鬥，對吧?', `MaleText_loc7`='He aprendido mucho solo con verte en acción. Luchas con el fervor de la juventud, pero también con la experiencia de un aguerrido veterano. La guerra ha ocupado toda tu vida, ¿verdad?' WHERE `ID`=62719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그렇군! 이게 바로 키파리 자르다!', `MaleText_loc4`='对，是真的！这是凯帕圣树·扎尔！', `MaleText_loc5`='是的，沒錯!這確實是奇帕利札爾!', `MaleText_loc7`='¡Sí, es cierto! ¡Es Kypari Zar!' WHERE `ID`=62720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 왜 내부에서 생명력이 뿜어져 나오는 느낌이 안 드는 거지? 왜 뿌리에 호박석 진액이 흐르는 걸 느낄 수 없는 건가?', `MaleText_loc4`='为什么我在其中感觉不到生命的迹象？在其根茎叶脉间为什么没有琥珀树脂在流动？', `MaleText_loc5`='為什麼我感覺不到裡頭發散出來的生命力?為什麼我感覺不到琥珀樹液在它的血脈中流動?', `MaleText_loc7`='¿Por qué no noto vida emanando de su interior? ¿Por qué no noto savia de ámbar fluyendo por sus venas?' WHERE `ID`=62721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무를 시험해봐야겠구나. 깨우는 자여, 내가 이 일을 수행하는 동안 나를 보호해다오!', `MaleText_loc4`='我必须检查这棵树。在我做检查时保护好我，唤醒者！', `MaleText_loc5`='我必須檢查這棵樹。喚醒者，在我進行這項任務的時候保護我!', `MaleText_loc7`='Debo examinar el árbol. ¡Protégeme mientras realizo esta tarea, heraldo!' WHERE `ID`=62722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 됐다. 키파리 자르가... 참을 수 없는 고통으로 울부짖는구나.', `MaleText_loc4`='完成了。凯帕圣树·扎尔……因不堪忍受的痛苦而呻吟着。', `MaleText_loc5`='完成了。奇帕利札爾...在難以忍受的苦痛中哭喊。', `MaleText_loc7`='Ya está. Kypari Zar... grita debido a una agonía insoportable.' WHERE `ID`=62723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연을 빌리고 싶으세요?', `FemaleText_loc4`='有兴趣租个风筝吗？', `FemaleText_loc5`='想租個風箏嗎?', `FemaleText_loc7`='¿Te interesa alquilar una cometa?' WHERE `ID`=62724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부 펑의 연을 한 개 빌리고 싶습니다.', `MaleText_loc4`='我想去借农夫老方的风筝。', `MaleText_loc5`='我想借一個農夫老豐的風箏。', `MaleText_loc7`='Quiero tomar prestada una de las cometas del granjero Fung.', `FemaleText_loc1`='농부 펑의 연을 한 개 빌리고 싶어요.', `FemaleText_loc4`='我想去借农夫老方的风筝。', `FemaleText_loc5`='我想借一個農夫老豐的風箏。', `FemaleText_loc7`='Quiero tomar prestada una de las cometas del granjero Fung.' WHERE `ID`=62725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 네!$b$b펑이 그러는데 당신이 원하면 예쁜 걸로 골라 쓰라고 하더라고요. 아무래도 당신이 마음에 드나 봐요.', `FemaleText_loc4`='哦，没问题！$b$b农夫老方说，如果你想要，你可以使用一只他精美的风筝。显然他喜欢上你了。', `FemaleText_loc5`='喔，當然!$b$b農夫老豐說過，如果你想，你可以從他那些超花俏的風箏中選一個去用。他顯然很喜歡你。', `FemaleText_loc7`='¡Oh, claro!$b$bEl granjero Fung dijo que, si querías, podías usar una de sus cometas BUENAS. Parece ser que le has caído bien.' WHERE `ID`=62726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기본형 붉은 연을 가져가겠습니다.', `MaleText_loc4`='我要拿标准红色风筝。', `MaleText_loc5`='我要紅色標準風箏。', `MaleText_loc7`='Me llevaré la cometa roja normal.', `FemaleText_loc1`='기본형 붉은 연을 가져갈게요.', `FemaleText_loc4`='我要拿标准红色风筝。', `FemaleText_loc5`='我要紅色標準風箏。', `FemaleText_loc7`='Me llevaré la cometa roja normal.' WHERE `ID`=62727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높이 띄울 수 있는 푸른 연을 가져가겠습니다.', `MaleText_loc4`='我要拿高空蓝色风筝。', `MaleText_loc5`='我要藍色飛高高風箏。', `MaleText_loc7`='Me llevaré la cometa azul de gran altitud.', `FemaleText_loc1`='높이 띄울 수 있는 푸른 연을 가져갈게요.', `FemaleText_loc4`='我要拿高空蓝色风筝。', `FemaleText_loc5`='我要藍色飛高高風箏。', `FemaleText_loc7`='Me llevaré la cometa azul de gran altitud.' WHERE `ID`=62728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 날 수 있는 노란색 연을 가져가겠습니다.', `MaleText_loc4`='我要拿迅捷黄色风筝。', `MaleText_loc5`='我要黃色迅捷風箏。', `MaleText_loc7`='Me llevaré la cometa amarilla rápida.', `FemaleText_loc1`='빨리 날 수 있는 노란색 연을 가져갈게요.', `FemaleText_loc4`='我要拿迅捷黄色风筝。', `FemaleText_loc5`='我要黃色迅捷風箏。', `FemaleText_loc7`='Me llevaré la cometa amarilla rápida.' WHERE `ID`=62729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='춤추듯 움직이는 녹색 연을 가져가겠습니다.', `MaleText_loc4`='我要拿热舞绿色风筝。', `MaleText_loc5`='我要綠色跳舞風箏。', `MaleText_loc7`='Me llevaré la cometa verde bailarina.', `FemaleText_loc1`='춤추듯 움직이는 녹색 연을 가져갈게요.', `FemaleText_loc4`='我要拿热舞绿色风筝。', `FemaleText_loc5`='我要綠色跳舞風箏。', `FemaleText_loc7`='Me llevaré la cometa verde bailarina.' WHERE `ID`=62730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여긴 특별한 장소라네. 우리 증조부, 증조모께서는 이 숲을 집이라고 부르셨네. 이리 오게. 잠깐이면 되네.', `MaleText_loc4`='啊，这是个特别的地方。我的祖辈们曾把这片林子当做家。来吧，我们很快就好。', `MaleText_loc5`='啊，這是個特別的地方。我的上上一代在森林的這一帶定居。來吧，這只要耽擱一下子。', `MaleText_loc7`='Ah, este es un lugar especial. Esta parte del bosque era el hogar de mis bisabuelos. Ven, solo tardaremos un instante.' WHERE `ID`=62731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 고대의 장소로군. 최근에 무척 특별한 곳이 되었지.', `MaleText_loc4`='另一个古老的地方，这个地方在近些年中变得更加特殊了。', `MaleText_loc5`='另一個古老的地方，這裡在近幾年來變得更加特別。', `MaleText_loc7`='Otro sitio antiguo; durante los últimos años, este ha visto cómo su condición de especial ha ido aumentando.' WHERE `ID`=62732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박 채취', `MaleText_loc4`='收集琥珀', `MaleText_loc5`='採收琥珀。', `MaleText_loc7`='Recolectar ámbar' WHERE `ID`=62733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리, 로. 밑에 있는 친구들에게 가 봐.', `MaleText_loc4`='李，罗，照看好下面的朋友们。', `MaleText_loc5`='小禮跟小樓，到下頭去照顧我們的朋友。', `MaleText_loc7`='Li y Lo, sigan a nuestros valientes abajo.' WHERE `ID`=62734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 문은 잠겼어. 그래도 열 방법이 없는 건 아니지.', `MaleText_loc4`='啊，大门锁住了，但我想我有办法弄开它。', `MaleText_loc5`='啊，這道門鎖上了，但我想我有東西可以打開它。', `MaleText_loc7`='Ah, esta puerta está cerrada, pero creo que tengo algo para abrirla.' WHERE `ID`=62735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자... 30초짜리 도화선...', `MaleText_loc4`='让我看看……三十秒的引线……', `MaleText_loc5`='讓我看看...第三十二條引線...', `MaleText_loc7`='A ver... Mecha de treinta segundos...' WHERE `ID`=62736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 30초짜리라고 했나? 3초짜린데.', `MaleText_loc4`='我说三十了？我是想说三。', `MaleText_loc5`='哦喔，我說三十嗎?我的意思是三。', `MaleText_loc7`='Ay, ¿dije treinta? Quise decir tres.' WHERE `ID`=62737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가, 어서! 공격을 멈춰야 해!', `MaleText_loc4`='快去，快！你必须阻止攻城！', `MaleText_loc5`='去吧，快!你必須阻止它們的攻擊!', `MaleText_loc7`='¡Dense prisa! ¡Deben poner fin al asedio!' WHERE `ID`=62738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 혼자 움직일 수 있을 만큼 강해졌구나. 이... 샤의 존재를 어서 의회에 보고해야만 한다. 다음에 나와 다시 만난다면 클락시베스에서 만나게 될 것이다.', `MaleText_loc4`='我感觉我能照顾自己了，$n。我必须要立即将这……邪煞……报告给议会。如果我们还能见面，应该是在卡拉克西维斯了。', `MaleText_loc5`='我覺得我已經夠強壯，可以靠自己繼續了，$n。我必須立刻向議會回報...這個...煞的存在。下次我們再見，應該是在卡拉西斐斯了。', `MaleText_loc7`='Me siento lo bastante fuerte para continuar yo solo, $n. Debo informar de esta presencia... sha... al consejo de inmediato. Si volvemos a encontrarnos, será en Klaxxi''vess.' WHERE `ID`=62739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공기 방울에서 나옵니다.', `MaleText_loc4`='%s从她的保护气泡中浮现而出。', `MaleText_loc5`='%s從她的防護泡泡中出現。', `MaleText_loc7`='%s emerge de su burbuja protectora.' WHERE `ID`=62740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 먹을 게... 필요하구나.', `MaleText_loc4`='我……需要……食物。', `MaleText_loc5`='我...需要...食物。', `MaleText_loc7`='Necesito... sustento.' WHERE `ID`=62741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 수 있다고 생각했던 것보다도 훨씬 오래 잠에 빠졌구나. 너무 많은 것이 바뀌었다.', `MaleText_loc4`='真没想到我竟然睡了如此之久。许多事情都变了。', `MaleText_loc5`='我可能睡得比我想的還要久。好多事物都改變了。', `MaleText_loc7`='He dormido mucho más tiempo de lo que creía posible. Han cambiado tantas cosas...' WHERE `ID`=62742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 깨어났을 때, 클락시가 너에 대해 이야기해줬다. 필요 없는 존재는 아닌 것 같구나.', `MaleText_loc4`='当我醒来时，卡拉克西对我提起了你。看来你并非毫无用处。', `MaleText_loc5`='當我醒來時，卡拉西跟我提到你。看來你不是完全沒有用處。', `MaleText_loc7`='Cuando desperté, los Klaxxi me hablaron de ti. Parece que no eres inútil del todo.' WHERE `ID`=62743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시는 내가 깨어나자마자 나의 존재를 감지해 수도 없이 내게 의견을 전달했다.$B$B그들은 내 의구심을 받아들였지. 여제는 이제 더는 제국을 지배할 만한 존재가 아니다. 이제 여제는 정화되어야만... 한다.', `MaleText_loc4`='我一苏醒，卡拉克西就感觉到了我的存在，把敢于透露的一切都告诉了我。$B$B他们证实了我的怀疑。女皇果然不再适合统治帝国。她必须被……荡除。', `MaleText_loc5`='一旦我醒過來，卡拉西就會立刻感受到我的存在，並盡可能地將這件事傳播出去。$B$B他們證實了我的猜測。女皇不再適合統治帝國。必須將她...淨化。', `MaleText_loc7`='En cuanto me desperté, los Klaxxi percibieron mi presencia y me transmitieron todo cuanto se atrevieron a enviar.$b$bConfirmaron mis propias sospechas. La Emperatriz ya no está capacitada para liderar el imperio. Debe ser... purificada.' WHERE `ID`=62744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시 의회는 내 의무다. 그들이 어떠한 것을 요구하든, 나는 복종해야만 한다.', `MaleText_loc4`='我效命于卡拉克西议会。不管他们要我做什么，我都必须服从。', `MaleText_loc5`='我的責任是效忠卡拉西議會。無論他們要求我做什麼，我都必須遵從。', `MaleText_loc7`='Mi deber lo dicta el consejo de los Klaxxi. Ellos ordenan, yo obedezco.' WHERE `ID`=62745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 이 세상을 알아보지 못하겠다. 모든 것이 낯설구나. 하지만 나는 완수해야 할 위대한 의무가 있다.', `MaleText_loc4`='我一点都不认识这个世界了。所有事物都那么陌生，然而还有伟大的使命在等着我。', `MaleText_loc5`='我認不得這個世界了。一切都好陌生，但我還有重要的職責得完成。', `MaleText_loc7`='Ya no reconozco este mundo. Todo me resulta desconocido, pero tengo un gran deber por cumplir.' WHERE `ID`=62746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐구나! 꼭 내가 될 거라고 아는 것처럼 말이야!$B$B아지만 아직도 정체 상태가 원래의 계산을 넘어서고 있다.', `MaleText_loc4`='成功了，我就知道行的！$B$B但即便如此，静止的效果还是超过了我原先的计算。', `MaleText_loc5`='它管用，跟我想的一樣!$B$B但即使如此，靜滯所造成的影響還是超出我的預料。', `MaleText_loc7`='¡Ha funcionado, justo como yo pensaba!$B$BPero aun así, los efectos de la estasis han superado incluso mis cálculos iniciales.' WHERE `ID`=62747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황무지 전역에 걸쳐 키파리가 죽어가고 있다.$B$B이... 샤... 때문이 아닐까 염려스럽구나.', `MaleText_loc4`='放眼整片废土，凯帕圣树正在凋零。$B$B我恐怕……煞……就是这一切的罪魁祸首。', `MaleText_loc5`='在荒野各處，奇帕利都快死了。$B$B恐怕這個...煞...就是原因。', `MaleText_loc7`='Los kypari están muriendo por todo el desierto.$B$BMe temo que este... sha... es la razón.' WHERE `ID`=62748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='건강한 키파리가 하나가 멀리 남서쪽에 남아 있지만, 우리가 말하는 지금 이 순간에도 여제의 노예들이 그걸 파괴하고 있다.', `MaleText_loc4`='远在西南方向，存活着一棵健康的凯帕圣树，但就在此时，女皇的奴隶正在试图毁灭它。', `MaleText_loc5`='在遙遠的西南方還有健康的奇帕利樹存活著，但在我們說話的同時，女皇的奴隸們也正在摧毀它。', `MaleText_loc7`='Queda un kypari sano a lo lejos, al suroeste, pero los esclavos de la Emperatriz lo están destruyendo ahora mismo.' WHERE `ID`=62749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키파리가 멸종하도록 놓아두면, 엄청난 보물을 잃는 것이다.$B$B호박석은 생명이다.', `MaleText_loc4`='如果我们放任凯帕圣树灭绝，这将是巨大的损失。$B$B琥珀即是生命。', `MaleText_loc5`='如果我們任由奇帕利滅絕，那麼我們將失去偉大的寶物。$B$B琥珀就是生命。', `MaleText_loc7`='Si dejamos que los kypari se extingan, habremos perdido un gran tesoro.$B$BEl ámbar es vida.' WHERE `ID`=62750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레자가 아이를 낳을 때까진 안 되네. 기다려야 하네.', `MaleText_loc4`='莱莎还在临产的时候可不行。我们还得等等。', `MaleText_loc5`='麗紗生孩子的時候不行。我們必須等待。', `MaleText_loc7`='No mientras Leza esté de parto. Debemos esperar.' WHERE `ID`=62751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선택이라니... 우리가 길을 떠난 이후로 선택이란 걸 해 본 적이 있었나?', `MaleText_loc4`='这段旅程何曾给过我们选择的机会？', `MaleText_loc5`='經過這段旅程，你覺得我們有什麼選擇嗎?', `MaleText_loc7`='¿Qué parte de nuestro viaje te dio la impresión de que había elección?' WHERE `ID`=62752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 원래 전투 임무가 아니라네.', `MaleText_loc4`='这本不该是一项战斗任务。', `MaleText_loc5`='這本來不是個戰鬥任務的。', `MaleText_loc7`='Se suponía que esta no era una misión de combate.' WHERE `ID`=62753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데즈코, 이것은 호드의 무기라네. 얼라이언스를 상대로 쓰게.', `MaleText_loc4`='德兹科，这是一件部落的武器。用它来狠狠的教训联盟。', `MaleText_loc5`='戴斯可，這是部落的武器。你應該對聯盟使用它。', `MaleText_loc7`='Dezco, esta es un arma de la Horda. Debes usarla contra la Alianza.' WHERE `ID`=62754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지. 하지만 원래는 얼라이언스가 자네 아내가 본 것과 똑같은 환영을 보고 이까지 따라올 줄도 몰랐지.', `MaleText_loc4`='联盟也不该照搬你妻子所设想的远景。', `MaleText_loc5`='聯盟不該跟著你妻子看見的幻象過來的。', `MaleText_loc7`='Y se suponía que la Alianza no estaba siguiendo las mismas visiones que tenía tu mujer.' WHERE `ID`=62755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데즈코, 우리는 계속 서쪽으로 나아가야 하네. 이곳은 위험하네.', `MaleText_loc4`='德兹科，我们必须向西方推进。我们留在这儿很容易受到攻击。', `MaleText_loc5`='戴斯可，我們應該繼續往西推進。這裡對我們來說很不利。', `MaleText_loc7`='Dezco, deberíamos seguir hacia el oeste. Aquí somos vulnerables.' WHERE `ID`=62756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 친구여, 자네 아내 덕분에 이곳까지 온 것은 고마운 일이네. 하지만 아이를 낳기엔 나쁜 때를 선택했군.', `MaleText_loc4`='感谢你的妻子带领我们来到这里，老朋友，只怪她在这个节骨眼生孩子。', `MaleText_loc5`='我很感念你妻子引領我們來到這裡的功勞，老友。但她真是選了絕差的時機來生孩子。', `MaleText_loc7`='Agradezco que tu mujer nos llevara hasta aquí, viejo amigo, pero eligió un mal momento para tener un hijo.' WHERE `ID`=62757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 나아졌구나.$B$B힘을 완전히 회복하려면 시간이 좀 걸리겠지만, 그래도 싸울 수 있을 정도로 강해졌다.', `MaleText_loc4`='我感觉好多了。$B$B我需要再休息一段时间才能完全恢复，不过至少我已经能够参加战斗了。', `MaleText_loc5`='我覺得好多了。$B$B我得花上一點時間才能完全恢復我的力量，但至少，我已強壯到足以戰鬥了。', `MaleText_loc7`='Me encuentro mejor.$B$BTardaré un tiempo en recuperar todas mis fuerzas, pero al menos estoy lo bastante fuerte como para luchar.' WHERE `ID`=62758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에서 살점과 호박석을 찾을 수 있었다니 행운아구나, 깨우는 자여.$B$B근처에 아무것도 없었다면, 너는 내 양분이 되었을 것이다.', `MaleText_loc4`='能在附近找到琥珀和鲜肉可真是辛运，唤醒者。$B$B如果都没有的话，我早就把你吃了。', `MaleText_loc5`='你運氣不錯，能在附近找到琥珀跟新鮮的肉，喚醒者。$B$B如果找不到，你就會變成我的糧食。', `MaleText_loc7`='Has tenido suerte de poder encontrar ámbar y carne cerca, heraldo.$B$BSi no hubieras podido encontrar nada, habrías sido mi sustento.' WHERE `ID`=62759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 판다렌은 조상을 숭배하지 않네. 하지만 그분들이 우리에게 물려주신 기억과 지혜를 존중하지.', `MaleText_loc4`='我们熊猫人并不崇拜祖先，不过我们尊崇他们传承下来的记忆和智慧。', `MaleText_loc5`='我們熊貓人不崇拜祖先。但是，我們尊重關於他們的記憶，及他們流傳下來的智慧。', `MaleText_loc7`='Los pandaren no adoramos a nuestros ancestros, pero veneramos su memoria y la sabiduría que nos han transmitido.' WHERE `ID`=62760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 전에 들려줬던 모구 이야기는, 바로 우리 증조부께서 내게 알려주신 거네.', `MaleText_loc4`='我刚才与你分享的魔古族传说，最早是我曾祖父讲给我听的。', `MaleText_loc5`='我剛跟你說的，關於魔古的歷史，是我的曾曾祖父告訴我的。', `MaleText_loc7`='Fue mi bisabuelo el que me contó la historia de los mogu que te relaté antes.' WHERE `ID`=62761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 너는 분명히 나약한 존재지만, 네가 마음에 든다. 나는 뛰어난 능력으로 전장에서 용장이 되었지. 내가 죽음조차도 농락할 수 있다는 말이 있을 정도다. 앞으로 수행할 임무에서 너를 지켜내기 위해 이 소중한 진통제 능력을 주마.', `MaleText_loc4`='尽管你有一些明显的缺点，但我越来越喜欢你了，唤醒者。 我之所为能成为英杰，是因为在战场上勇猛善战。人们说我甚至能骗过死神。我现在就把这个起死回生的本领教给你，让你能在未来的任务中保住性命。', `MaleText_loc5`='儘管你有明顯的弱點，但我已經喜歡上你了，喚醒者。我之所以成為聖螳是因為我在戰場上的英勇表現。有人說我可以騙過死神。我將這個能力借給你。鎮痛療傷，這可以在你進行接下來的任務時保護你。', `MaleText_loc7`='A pesar de tus evidentes debilidades, te he tomado cariño, heraldo. Me nombraron dechado por mi pericia en el campo de batalla. Decían que podía engañar a la mismísima muerte. Te prestaré esa facultad, Analgésico, para protegerte en la misión que nos espera.' WHERE `ID`=62762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희귀한 애완동물을 잡는 데 관심이 있습니다만?', `MaleText_loc4`='有兴趣去抓一些稀有宠物么？', `MaleText_loc5`='有興趣捕捉一些稀有寵物嗎?', `MaleText_loc7`='¿Te interesa capturar mascotas raras?', `FemaleText_loc1`='희귀한 애완동물을 잡는 데 관심이 있는데요?', `FemaleText_loc4`='有兴趣去抓一些稀有宠物么？', `FemaleText_loc5`='有興趣捕捉一些稀有寵物嗎?', `FemaleText_loc7`='¿Te interesa capturar mascotas raras?' WHERE `ID`=62763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아 하니 희귀한 애완동물에 관심이 있을 듯하군.', `MaleText_loc4`='你看起来像是对稀有宠物感兴趣的人吧？', `MaleText_loc5`='你看起來對稀有寵物感興趣?', `MaleText_loc7`='Tienes aspecto de interesarte por las mascotas raras.', `FemaleText_loc1`='보아 하니 희귀한 애완동물에 관심이 있을 듯하군요.', `FemaleText_loc4`='你看起来像是对稀有宠物感兴趣的人吧？', `FemaleText_loc5`='你看起來對稀有寵物感興趣?', `FemaleText_loc7`='Tienes aspecto de interesarte por las mascotas raras.' WHERE `ID`=62764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 예쁜 토끼를 본 적 있소? 직접 잡을 수 있게 도와주지!', `MaleText_loc4`='你以前见过这么漂亮的兔子么？我能帮你抓一只属于你自己的！', `MaleText_loc5`='你有看過這麼漂亮的兔子嗎?我能幫你抓一隻!', `MaleText_loc7`='¿Has visto alguna vez un conejo tan bonito? ¡Puedo ayudarte a capturar uno!', `FemaleText_loc1`='이렇게 예쁜 토끼를 본 적 있나요? 직접 잡을 수 있게 도와드릴게요!', `FemaleText_loc4`='你以前见过这么漂亮的兔子么？我能帮你抓一只属于你自己的！', `FemaleText_loc5`='你有看過這麼漂亮的兔子嗎?我能幫你抓一隻!', `FemaleText_loc7`='¿Has visto alguna vez un conejo tan bonito? ¡Puedo ayudarte a capturar uno!' WHERE `ID`=62765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 옛 제국의 길이에요. 예전 모구 제국이 포로를 이곳으로 데려와 고문했다더군요.', `MaleText_loc4`='这是古老的帝王之路。据说魔古帝国曾经把他们的囚徒带到这里受刑。', `MaleText_loc5`='這是舊帝國時代的一條老路。他們說魔古帝國曾經把囚犯帶到這裡來折磨。', `MaleText_loc7`='Este es el antiguo Camino Imperial. Dicen que el imperio mogu traía aquí a sus prisioneros para torturarlos.' WHERE `ID`=62766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 파고 있는 걸까요? 모구가 저렇게 도구와 무기를 잘 다루는 건 처음 봐요.', `MaleText_loc4`='他们在挖什么？在这之前我从没见过魔古族使用这样的工具和武器。', `MaleText_loc5`='他們在挖什麼?我以前從沒見過魔古使用那樣的工具與武器。', `MaleText_loc7`='¿Qué están desenterrando? Nunca he visto a mogu usar herramientas y armas como esas.' WHERE `ID`=62767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모구들은 이 근처에서 온 게 아닌 것 같군요. 약탈을 하는 게 아니라, 옛 유물을 찾고 있어요.', `MaleText_loc4`='我不认为这些魔古来自这里。看起来他们像是在收集这些古老的圣物，而不是在埋藏或者掠夺它们。', `MaleText_loc5`='我不認為這些魔古是從這裡來的。他們似乎是要收集舊遺物，而不是挖東西或搶劫。', `MaleText_loc7`='Creo que estos mogu no son de aquí. Parecen estar buscando reliquias antiguas, no atrincherándose o saqueando.' WHERE `ID`=62768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? 난 바쁘단 말이다.', `MaleText_loc4`='什么事？我忙着呢。', `MaleText_loc5`='那是什麼?我很忙。', `MaleText_loc7`='¿Qué pasa? Estoy ocupado.' WHERE `ID`=62769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 될까?', `MaleText_loc4`='这些够了么？', `MaleText_loc5`='這夠了嗎?', `MaleText_loc7`='¿Con esto será suficiente?' WHERE `ID`=62770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수복의 군주께서 보시도록 다른 것들과 함께 둬.', `MaleText_loc4`='把它和其他的放在一起，以便复国领主前来检查。', `MaleText_loc5`='把它跟其他的東西放在一起給回收者領主檢查。', `MaleText_loc7`='Ponlo con los demás para la inspección del Señor Reivindicador.' WHERE `ID`=62771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 저는 싸움의 고수입니다. 또 이 세상의 동식물에 관련된 지식도 많지요. 제가 당연히 도움되지 않겠습니까?', `MaleText_loc4`='可是，我是一个战斗大师，对这个世界的植物和动物都有着丰富的知识。我的这身本事难道帮不上忙吗？', `MaleText_loc5`='不過，我是個戰鬥大師，還具有廣博的動植物知識。我一定能幫上什麼忙?', `MaleText_loc7`='Pero soy un maestro luchador, con un amplio conocimiento de la flora y la fauna de este mundo. Seguro que puedo ayudarte.' WHERE `ID`=62772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다. 이건 우리의 문제입니다. 우리 손으로 직접 해결해야 합니다.', `MaleText_loc4`='不——自己的问题，自己解决。', `MaleText_loc5`='不，這是我們的問題，我們必須自己處理。', `MaleText_loc7`='No. Es nuestro problema, tenemos que solucionarlo por nuestra cuenta.' WHERE `ID`=62773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 여기 생존자가 또 있군요. 손재주도 좋은 것 같은데... 당신이 전투 기술을 가르쳐줄 수 있지 않겠습니까?', `MaleText_loc4`='但是，又来了一个幸存者。 看起来他们身体很健康……或许你可以教授他们一些战斗技巧？', `MaleText_loc5`='不過，有另一個倖存者來了。看起來也是一把好手...或許你能把戰鬥技能教給他?', `MaleText_loc7`='Pero ahí viene otro superviviente. Parece hábil con las manos... Quizás puedas enseñarle tus habilidades de lucha.' WHERE `ID`=62774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 영광일 겁니다.', `MaleText_loc4`='当然可以！这是我的荣幸。', `MaleText_loc5`='當然!這是我的榮幸。', `MaleText_loc7`='¡Claro! Será un honor.' WHERE `ID`=62775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨...?', `MaleText_loc4`='什么……？', `MaleText_loc5`='搞什麼...?', `MaleText_loc7`='¿Pero qué...?' WHERE `ID`=62776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 소리는 뭐지?', `MaleText_loc4`='那是什么声音？', `MaleText_loc5`='那是甚麼聲音?', `MaleText_loc7`='¿Qué fue ese ruido?' WHERE `ID`=62777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽 쪽에서 났습니다.', `MaleText_loc4`='是从……墙那边传来的。', `MaleText_loc5`='是...從牆上來的，長官。', `MaleText_loc7`='Ve... venía de la muralla, señor.' WHERE `ID`=62778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 났는지는 됐고, 뭐였냐고?', `MaleText_loc4`='我知道是从哪儿传来的，可那到底是什么？', `MaleText_loc5`='我知道是哪邊來的，是什麼東西?', `MaleText_loc7`='Ya sé de dónde venía. Pero, ¿qué era?' WHERE `ID`=62779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭한 노예감이군.', `MaleText_loc4`='你们会成为出色的帝国奴隶。', `MaleText_loc5`='你可以成為一個很好的帝國奴隸', `MaleText_loc7`='Seréis buenos esclavos para el Imperio.' WHERE `ID`=62780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼...', `MaleText_loc4`='不……不……', `MaleText_loc5`='不...不...', `MaleText_loc7`='No... no...' WHERE `ID`=62781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원 전투 준비!', `MaleText_loc4`='弟兄们！拿起武器！', `MaleText_loc5`='所有人!準備作戰!', `MaleText_loc7`='¡Hombres! ¡A las armas!' WHERE `ID`=62782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 자네! 전방에 있는 오큰쉴드를 돕게!', `MaleText_loc4`='你们三个！去前面协助橡盾队长！', `MaleText_loc5`='你們三個!$n!協助前面的守衛隊長橡木盾!', `MaleText_loc7`='¡Ustedes tres! ¡Ayuden al capitán Escudo de Roble en el frente!' WHERE `ID`=62783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그린틸! 블랙소일! 왼쪽 측면을 방어하게! 기습당하면 안 되니까!', `MaleText_loc4`='绿耕！黑土！掩护我们的左侧！我可不想遭到偷袭！', `MaleText_loc5`='青磧!黑土!掩護左翼!我不希望遭到伏擊!', `MaleText_loc7`='¡Brote Glauco! ¡Tierra Bruna! ¡Cubran el flanco izquierdo! ¡No quiero sorpresas!' WHERE `ID`=62784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레벤, 오른쪽을 맡게나! 이젠 혼자 알아서 하게!', `MaleText_loc4`='莱文，你去右侧！靠你自己了！', `MaleText_loc5`='利文，走右邊!你得靠自己了!', `MaleText_loc7`='¡Leven, al flanco derecho! ¡Estarás solo!' WHERE `ID`=62785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 들 수 있는 자들은 마을을 방어하라! 놈들이 이 선을 넘어오게 해선 안 된다! 너희는...', `MaleText_loc4`='其他人！如果你们拿得动武器，就去保护村庄！别让他们越过防线！你们……', `MaleText_loc5`='其他人!如果你能揮動武器，保護這個村莊!不要讓他們越過這條線!你們...', `MaleText_loc7`='¡El resto! ¡Si pueden empuñar un arma, defiendan la aldea! ¡Que no pasen de aquí! Ustedes…' WHERE `ID`=62786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 진정한 주인이 누군지 곧 알게 될 것이다.', `MaleText_loc4`='你们这些劣等种族马上就会明白谁才是你们真正的主人。', `MaleText_loc5`='你的族類很快就會知道誰才是真正的主子。', `MaleText_loc7`='Pronto aprenderán quiénes son los auténticos amos.' WHERE `ID`=62787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제를 알게 해 주마.', `MaleText_loc4`='你们将会了解自己的处境。', `MaleText_loc5`='我會讓你認清自己的立場。', `MaleText_loc7`='Vas a aprender cuál es tu sitio.' WHERE `ID`=62788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승산이 없을 것 같군...', `MaleText_loc4`='我们毫无机会……', `MaleText_loc5`='我們不會有勝算的...', `MaleText_loc7`='No tenemos ninguna posibilidad...' WHERE `ID`=62789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전원, 모두 후퇴! 후퇴!', `MaleText_loc4`='所有人，退后！退……', `MaleText_loc5`='所有人，撤退，撤退...!', `MaleText_loc7`='¡Retirada! RETI...' WHERE `ID`=62790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야야야!!!', `MaleText_loc4`='啊啊啊！', `MaleText_loc5`='吼啊啊啊啊!!!', `MaleText_loc7`='¡¡¡Rrrraaaa!!!' WHERE `ID`=62791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까?', `MaleText_loc4`='你是谁？', `MaleText_loc5`='你是誰?', `MaleText_loc7`='¿Y tú quién eres?' WHERE `ID`=62792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 모구의 힘에 맞설 수 있다고 생각하느냐?', `MaleText_loc4`='你觉得自己能挑战魔古的力量？', `MaleText_loc5`='你以為你能挑戰魔古的力量嗎?', `MaleText_loc7`='¿Creías que podías desafiar el poder de los mogu?' WHERE `ID`=62793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 누구면 어떤가? 자네를 도우러 왔으면 됐지.', `MaleText_loc4`='何必管我们是谁？我们是来帮你的。', `MaleText_loc5`='我們是誰很重要嗎?我們是來幫忙的。', `MaleText_loc7`='¿Acaso importa quiénes seamos? Estamos aquí para ayudar.' WHERE `ID`=62794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보십시오! 누가 쇠스랑 좀 주시죠!', `MaleText_loc4`='嘿！给我一把干草叉！', `MaleText_loc5`='嘿!給我一把乾草叉!', `MaleText_loc7`='¡Eh! ¡Dame una de esas horquetas!' WHERE `ID`=62795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복한다고? 왜지? 침략자들이 벽을 깨부수니까?', `MaleText_loc4`='你投降了？为什么？因为这群入侵者能摧毁一道长城？别忘了你还有另一道长城…是由那些管这里叫做家的人…比肩铸成的。', `MaleText_loc5`='你們要投降?為什麼?就因為入侵者把長城拆了?', `MaleText_loc7`='¿Iban a rendirse? ¿Por qué? ¿Porque los invasores pueden derribar una muralla? Tienen otra muralla, una formada por personas que han hecho de este sitio su HOGAR.' WHERE `ID`=62796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벽은 또 있네... 이곳을 고향이라 부르는 이들로 이루어진 벽 말일세.', `MaleText_loc4`='别忘了你还有另一道长城…是由那些管这里叫做家的人…比肩铸成的。', `MaleText_loc5`='你們還有一道長城...是把這個地方當「家園」的人組成的。', `MaleText_loc7`='Tenéis otra muralla, una construida de personas que han hecho de este sitio su HOGAR.' WHERE `ID`=62797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 이 땅을 지키기 위해서라면 목숨도 내놓을 수 있네.', `MaleText_loc4`='我们任何人都甘愿放弃生命，以守护这片土地。', `MaleText_loc5`='我們所有人都願意為保護這片土地獻出生命。', `MaleText_loc7`='Todos nosotros daríamos la vida para proteger esta tierra.' WHERE `ID`=62798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 우리 것일세...', `MaleText_loc4`='这片土地属于我们……', `MaleText_loc5`='這片土地，屬於我們...', `MaleText_loc7`='Nos pertenece a nosotros...' WHERE `ID`=62799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조상님의 것이며...', `MaleText_loc4`='属于我们的祖先……', `MaleText_loc5`='屬於我們的祖先...', `MaleText_loc7`='... a nuestros ancestros...' WHERE `ID`=62800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 자손의 것일세.', `MaleText_loc4`='属于我们的子孙。', `MaleText_loc5`='屬於我們的子孫。', `MaleText_loc7`='... a nuestros hijos.' WHERE `ID`=62801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 기필코 지켜내고 말 걸세.', `MaleText_loc4`='这决不会被改变。', `MaleText_loc5`='我們不會讓這一點改變。', `MaleText_loc7`='Y no permitiremos que eso cambie.' WHERE `ID`=62802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이곳 하늘안개 섬 지역의 야생 동식물 목록을 작성하며 거닐고 있는데 갑자기...

쾅!<손으로 폭발하는 모양을 흉내 내는 모조>

그렇게 커다란 폭발음은 여태껏 들어본 적이 없었다네!', `MaleText_loc4`='我只是在随处走走，记录一些艾泽雷斯特当地的野生生物，突然……

砰的一声！<墨乔用手比划着爆炸的样子。>

我认为那是我有生以来听到过的最响的爆炸声！', `MaleText_loc5`='我獨自走著，把藍謎島當地的野生動物編列成冊，突然...

磅!<莫仇用手比出爆炸的模樣。>

我這輩子沒聽過那麼大的爆炸聲!', `MaleText_loc7`='Estaba simplemente caminando, catalogando la fauna local de Bruma Azur, cuando de pronto...

¡ZAS! <Mojo imita una explosión con sus manos.>

Creo que jamás he escuchado una explosión tan potente en toda mi vida.' WHERE `ID`=62803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제국은 부흥할 것이다!', `MaleText_loc4`='帝国再次崛起了！', `MaleText_loc5`='帝國再起了!', `MaleText_loc7`='¡El Imperio se alza de nuevo!' WHERE `ID`=62804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제국을 위하여!', `MaleText_loc4`='为了帝国！', `MaleText_loc5`='為了帝國!', `MaleText_loc7`='¡Por el Imperio!' WHERE `ID`=62805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자다!', `MaleText_loc4`='入侵者！', `MaleText_loc5`='入侵者!', `MaleText_loc7`='¡Intruso!' WHERE `ID`=62806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 천둥왕의 것이다!', `MaleText_loc4`='这片土地属于雷电之王。', `MaleText_loc5`='這些土地屬於雷王。', `MaleText_loc7`='Estas tierras pertenecen al Rey del Trueno.' WHERE `ID`=62807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 제국에 맞서느냐?', `MaleText_loc4`='你胆敢挑战帝国？', `MaleText_loc5`='你膽敢挑戰帝國?', `MaleText_loc7`='¿Osáis desafiar al Imperio?' WHERE `ID`=62808;
