UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 구해 줄 판다렌은 여기 없다.', `MaleText_loc4`='现在没有熊猫人来救你们了。', `MaleText_loc5`='這裡可沒有熊貓人能救你。', `MaleText_loc7`='Ahora los pandaren no están aquí para salvaros.' WHERE `ID`=62810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 시대는 끝났다.', `MaleText_loc4`='你们主宰世界的时代已经过去了。', `MaleText_loc5`='你們在這土地上的時代已經過去了。', `MaleText_loc7`='Su era en este mundo ha pasado.' WHERE `ID`=62811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수복의 군주를 위하여!', `MaleText_loc4`='为了复国领主！', `MaleText_loc5`='為了回收者領主!', `MaleText_loc7`='¡Por el Señor Reivindicador!' WHERE `ID`=62812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개 숙여 애원하라!', `MaleText_loc4`='在我面前颤抖吧，懦夫！', `MaleText_loc5`='在我面前跪下!', `MaleText_loc7`='¡Tiembla ante mí, suplicante!' WHERE `ID`=62813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비를 빌어라.', `MaleText_loc4`='乞哀告怜吧。', `MaleText_loc5`='跪地求饒吧。', `MaleText_loc7`='Rogad misericordia.' WHERE `ID`=62814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생명은 내가 접수하겠다.', `MaleText_loc4`='你的死期到了。', `MaleText_loc5`='你的小命就要沒了。', `MaleText_loc7`='Tu vida ha terminado.' WHERE `ID`=62815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우리를 방해하느냐?', `MaleText_loc4`='你们胆敢阻碍我们？', `MaleText_loc5`='你膽敢阻擋我們?', `MaleText_loc7`='¿Osáis interponeros en nuestro camino?' WHERE `ID`=62816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 태생이 노예다.', `MaleText_loc4`='你们注定将成为奴仆。', `MaleText_loc5`='你的族類將成為我們的奴隸。', `MaleText_loc7`='Su pueblo será nuestro siervo.' WHERE `ID`=62817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 제국의 분노를 목도하라!', `MaleText_loc4`='感受新帝国的愤怒吧！', `MaleText_loc5`='見識新生帝國的憤怒吧!', `MaleText_loc7`='¡Observad la furia del nuevo Imperio!' WHERE `ID`=62818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용장! 클락시 침입자다!', `MaleText_loc4`='嗞嗞！英杰！卡拉克西渗透者！', `MaleText_loc5`='喀嘶嘶!聖螳!卡拉西入侵者!', `MaleText_loc7`='¡Kzzsst! ¡Dechado! ¡Infiltrado de los Klaxxi!' WHERE `ID`=62819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑을 지켜라!', `MaleText_loc4`='守住塔！', `MaleText_loc5`='守住高塔!', `MaleText_loc7`='¡Proteged la torre!' WHERE `ID`=62820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알아서 무덤을 파는구나, 침입자 녀석아!', `MaleText_loc4`='自寻死路，入侵者！', `MaleText_loc5`='你是在找死，入侵者!', `MaleText_loc7`='¡Estás cavando tu propia tumba, intruso!' WHERE `ID`=62821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 훔쳐가는 놈이군! 이곳은 여제님의 탑이란 말이다!', `MaleText_loc4`='偷信号的贼！这是女皇的塔！', `MaleText_loc5`='信號小偷!這是女皇的塔!', `MaleText_loc7`='¡Ladrón de señales! ¡Esta torre pertenece a la Emperatriz!' WHERE `ID`=62822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 조상에 대한 이야기도 듣고 싶군, 이방인. 향에 불을 붙이고, 고향에 대해 생각해 보지 않겠나?', `MaleText_loc4`='我很希望能了解你的先祖，陌生人。点燃那束香，让我们一起回想你的故乡，怎么样？', `MaleText_loc5`='我很想聽關於你們祖先的事蹟，陌生人。點燃薰香，讓我們來看看你們的出處，嗯?', `MaleText_loc7`='Me gustaría mucho oír hablar de tus ancestros. Enciende el incienso y reflexionemos sobre tus orígenes.' WHERE `ID`=62823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 다른 세계에서 온... 위대한 전사의 혈통이라니! 판다렌은 자신의 고향을 떠나는 일이 많지 않다네. 자네는 정말 자랑스러워할 만하군.', `MaleText_loc4`='真令人震惊！世代都是伟大的战士……来自全然不同的世界！熊猫人很少会离开自己的家园。你真该为自己的身份感到骄傲。', `MaleText_loc5`='真精采!偉大戰士的血統...還是從另一個世界而來的!熊貓人很少離開他們家園。你理應為自己感到驕傲。', `MaleText_loc7`='¡Impresionante! Un linaje de grandes guerreros... ¡y de otro planeta, por si fuera poco! Los pandaren no solemos abandonar nuestra tierra natal. Haces bien en enorgullecerte de tus raíces.' WHERE `ID`=62824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 흥미롭군. 자네 안색이 좋지 않다고 생각했는데, 이제 이유를 알겠네. 끔찍한 어둠의 무게를 짊어지고 있어. 그럼에도 앞으로 나아간다니, 정말 강인한 의지야!', `MaleText_loc4`='真不可思议。你们看上去病怏怏的——现在我知道了真相。你们遭受着可怕黑暗的侵袭，但却奋勇向前，多么强大的力量！', `MaleText_loc5`='真令人讚嘆。我本來以為你看起來不健康，但如今我看到真相了。你們在恐怖黑暗的沉重負擔下受苦。你們能向前邁進真是不簡單!', `MaleText_loc7`='Fascinante. Pensaba que te asolaba una enfermedad, pero ahora lo entiendo. Tu gente sufre bajo el yugo de una terrible oscuridad. Deben de ser muy fuertes, solo por haber seguido adelante.' WHERE `ID`=62825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 자네들도 조상을 존경하고 땅을 아끼는군. 우린 공통점이 무척 많다네! 아, 하지만 자네 조상들은 유목민이셨군. 우리 판다렌은 집과 고향의 편안함을 좋아한다네. 여행을 하는 이는 많지 않아.', `MaleText_loc4`='看哪。你们的族人也崇敬先祖，珍爱土地。我们的共同点真多！啊，可你们的先祖是游牧民，而我们熊猫人则喜欢待在温暖舒适的家里。很少有人外出远行。', `MaleText_loc5`='看啊。你們人民也尊敬祖先，珍惜大地。我們十分相似!哦，但你們祖先是遊牧民族，而熊貓人喜歡家庭和火爐的溫暖。我們當中很少有旅行者。', `MaleText_loc7`='Quién me lo iba a decir. Tu pueblo también venera a sus ancestros y cuida la tierra. ¡Nos parecemos mucho! Ah, veo que tus antepasados eran nómadas; los pandaren preferimos la comodidad del hogar. No verás muchos viajeros entre nosotros.' WHERE `ID`=62826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 생각했던 대로야. 자네 혈통은 세계의 여명기로까지 거슬러 올라가는군. 고대 트롤 제국은 정말 강인했지. 자네 눈 속에도 강력한 의지의 불꽃이 보이는군. 다시 제국을 세우려 하나?', `MaleText_loc4`='噢——果然不出所料。你们的祖先诞生于世界起源之日；强大的巨魔帝国盛极一时。你的眼中闪烁着复兴的火花和强大的意志，不是吗？', `MaleText_loc5`='噢...跟我想的一樣。你們祖先從創世之初就存在。食人妖的帝國十分古老而強大。你的眼中也有著強大意志的光芒...你希望再次強大，對嗎?', `MaleText_loc7`='Lo sospechaba. Tu linaje se remonta al albor del mundo. Los antiguos imperios de los trols fueron esplendorosos. Veo una chispa en tu mirada, un anhelo acuciante: el de recuperar ese esplendor.' WHERE `ID`=62827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 고귀한 혈통이군! 자네들은 막대한 힘을 소유하고, 그 대가로 끔찍한 짐을 져야 했어. 그 고통 역시 막대했겠지. 왜 자네들이 "피의" 엘프가 되었는지 알겠군.', `MaleText_loc4`='啊，你身世高贵！然而可怕的重担总是随着强大的力量而来；力量无穷，则痛苦无尽。现在我明白为什么你们自称为“血”精灵了。', `MaleText_loc5`='啊，你們的血統十分高貴!你們的人民有著強大的力量，以及隨之而來的可怕負擔。強大同時也是你們的苦難。現在我知道為什麼你們叫「血精靈」了。', `MaleText_loc7`='¡Qué linaje tan noble! Tu pueblo posee un gran poder, así como la pesada carga que lo acompaña. Su sufrimiento ha sido igual de tremendo. Ahora entiendo por qué se hacen llamar elfos "de sangre".' WHERE `ID`=62828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 흥미롭군. 자네 조상들은 대부분 불 속에서 돌아가셨네. 아, 저런. 발전이라는 이름 아래 크나큰 위험을 자초하고 말았어! 판다렌에게도 그런 열정이 있다면 좋을 텐데.', `MaleText_loc4`='嗯……真有趣。你的大多数祖先都葬身于烈火。天哪。你的族人为了进步，不惜以身犯险！真希望有更多熊猫人具备这种觉悟。', `MaleText_loc5`='這真有趣。你們有許多祖先在火中喪生。噢。你們的人民為了進步而置個人安全於險境!真希望熊貓人也有這樣的精神。', `MaleText_loc7`='Vaya... Qué interesante. La mayoría de tus antepasados murieron entre llamas. Qué cosa. Tu gente corre grandes riesgos en aras del progreso. Ojalá hubiera más pandaren con su iniciativa.' WHERE `ID`=62829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 자네도 역사를 잘 알고 있겠지! 유랑도 출신의 판다렌이니까. 솔직히 말해, 그 섬이 그저 전설 속의 존재인 줄 알았네. 그곳의 판다렌은 본토에 비해 모험을 좋아한다지... 모험의 피를 타고났어!', `MaleText_loc4`='啊，你的过往似曾相识！我承认，我曾以为你的家乡迷踪岛只是个传说。岛上的熊猫人比大陆上的更爱冒险……冒险的精神流淌在你们血液中！', `MaleText_loc5`='啊，你對於自己的過去非常了解!從漂流島來的熊貓人。我承認，我以為你們的故鄉只是個傳說。從島上來的熊貓人比大陸上的更愛冒險...你們的天性如此!', `MaleText_loc7`='¡Ah, pero si tú ya conoces tu pasado! Un pandaren de La Isla Errante... Confieso que pensaba que tu hogar era un mito. Los pandaren de la isla son mucho más intrépidos que los de Pandaria. ¡Lo llevan en la sangre!' WHERE `ID`=62830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 이게... 어떻게 된...', `MaleText_loc4`='不！发生了……什么……', `MaleText_loc5`='不!...發生了...什麼事...', `MaleText_loc7`='¡No! ¿Qué está... ocurriendo...?' WHERE `ID`=62831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피 추적자 스키르가 돌아왔다! 으으으윽...', `MaleText_loc4`='觅血者斯基尔归来了！啊……', `MaleText_loc5`='『覓血者』斯其爾回來了!嗚咕咕咕咕...', `MaleText_loc7`='¡Skeer el Cruento ha regresado! Aaaagghhh...' WHERE `ID`=62832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다, 클락시바여, 의회의 명령은 무엇입니까? 피 추적자가 듣고 복종하겠습니다.', `MaleText_loc4`='是，卡拉克西瓦。议会下达了什么命令？斯基尔倾听。斯基尔服从。', `MaleText_loc5`='是的，卡拉西瓦。議會的命令是什麼?斯其爾聆聽。斯其爾遵從。', `MaleText_loc7`='Sí, Klaxxi''va. ¿Qué ordena el consejo? Skeer escucha. Skeer obedece.' WHERE `ID`=62833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 앗! 내가 무슨...? 혹시...? 너무... 흐릿해.', `MaleText_loc4`='我……啊……噢！我……？眼睛……好……模糊。', `MaleText_loc5`='我...啊..喔!我曾經...?我是不是...?這一切...都太...模糊了。', `MaleText_loc7`='Yo... ah... ¿eh? ¿Yo he...? ¿Era yo...? Todo... estaba... turbio.' WHERE `ID`=62834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가야 해요.', `MaleText_loc4`='我必须走了。', `MaleText_loc5`='我現在得走了。', `MaleText_loc7`='Ahora me tengo que ir.' WHERE `ID`=62835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐린 물을 맑게 해야 해요. 혹시... 도와 줄래요?', `MaleText_loc4`='我不能再让水变浑了。你……你愿意帮忙吗？', `MaleText_loc5`='我必須讓水變得清澈，不再混濁。你...你願意幫忙嗎?', `MaleText_loc7`='No puedo dejar que el agua se quede turbia. ¿Me... me ayudarán?' WHERE `ID`=62836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t 가랄론이 다리 한 쪽을 |cFFFF0000|Hspell:123495|h[고칩니다]|h|r!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t加拉隆|cFFFF0000|Hspell:123495|h[治疗]|h|r他的一条腿！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t加拉隆|cFFFF0000|Hspell:123495|h[修補]|h|r他的一隻腳!', `MaleText_loc7`='|TInterfaceIconsspell_nature_healingwavelesser.blp:20|t ¡Garalon |cFFFF0000|Hspell:123495|h[Alivia]|h|r una de sus piernas!', `FemaleText_loc1`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t 가랄론이 다리 한 쪽을 |cFFFF0000|Hspell:123495|h[고칩니다]|h|r!', `FemaleText_loc4`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t加拉隆|cFFFF0000|Hspell:123495|h[治疗]|h|r他的一条腿！', `FemaleText_loc5`='|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t加拉隆|cFFFF0000|Hspell:123495|h[修補]|h|r他的一隻腳!', `FemaleText_loc7`='|TInterfaceIconsspell_nature_healingwavelesser.blp:20|t ¡Garalon |cFFFF0000|Hspell:123495|h[Alivia]|h|r una de sus piernas!' WHERE `ID`=62837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 것들! 더 열심히 싸워라! 보잘것없는 판다렌에게 질 수는 없지 않느냐!', `MaleText_loc4`='蠢货！卖力点！别让这些弱小的熊猫人打败你！', `MaleText_loc5`='蠢材們!更賣力戰鬥!別讓這些弱小的熊貓人擊敗你們!', `MaleText_loc7`='¡Idiotas! ¡Luchen con más fiereza! ¡No dejen que estos patéticos pandaren les derroten!' WHERE `ID`=62838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆准备|cFFFF0000|Hspell:122774|h[重碾]|h|r他的对手！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆準備要|cFFFF0000|Hspell:122774|h[碾碎]|h|r他的對手!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon se prepara para lanzar |cFFFF0000|Hspell:122774|h[Machaque]|h|r contra sus oponentes!', `FemaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t 가랄론이 |cFFFF0000|Hspell:122774|h[으깨기]|h|r를 준비합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆准备|cFFFF0000|Hspell:122774|h[重碾]|h|r他的对手！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t加拉隆準備要|cFFFF0000|Hspell:122774|h[碾碎]|h|r他的對手!', `FemaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t ¡Garalon se prepara para |cFFFF0000|Hspell:122774|h[Machacar]|h|r a sus oponentes!' WHERE `ID`=62839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 어린 사우록이여! 그리고 파괴해라!', `MaleText_loc4`='再抬高一点！ 然后消灭它们！', `MaleText_loc5`='把小傢伙丟上來!然後摧毀它!', `MaleText_loc7`='¡Levántate, pequeño! ¡Y destruye!' WHERE `ID`=62840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가랄론의 육중한 장갑이 갈라지면서 쪼개지기 시작합니다!', `MaleText_loc4`='加拉隆的巨型盔甲开始碎裂了！', `MaleText_loc5`='加拉隆巨大的裝甲開始破裂並粉碎!', `MaleText_loc7`='¡La enorme coraza de Garalon empieza a agrietarse y romperse!', `FemaleText_loc1`='가랄론의 육중한 장갑이 갈라지면서 쪼개지기 시작합니다!', `FemaleText_loc4`='加拉隆的巨型盔甲开始碎裂了！', `FemaleText_loc5`='加拉隆巨大的裝甲開始破裂並粉碎!', `FemaleText_loc7`='¡La enorme coraza de Garalon empieza a agrietarse y romperse!' WHERE `ID`=62841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최초의 공식 전투 행사, 파멸의 투기장에 온 걸 환영해.', `MaleText_loc4`='欢迎参加我们首个获得官方批准的格斗赛事，破军比武场！', `MaleText_loc5`='歡迎參加我們第一個官方批准的格鬥技挑戰:殲滅競技場!', `MaleText_loc7`='¡Bienvenidos a nuestro primer evento de combate con permiso oficial, la Arena de la Aniquilación!' WHERE `ID`=62842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이거야... 깨우는 자여. 피 냄새가 네게 새 힘을 주지 않나?', `MaleText_loc4`='啊……唤醒者，鲜血的气味是否让你重新焕发了活力？', `MaleText_loc5`='啊，太棒了...喚醒者，鮮血的氣味不會讓你充滿嶄新的力量嗎?', `MaleText_loc7`='Ah, sí... ¿No renueva tus fuerzas el aroma de la sangre, heraldo?' WHERE `ID`=62843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나약하고! 멍청한 것들! 네놈들은 피 추적자에 맞설 수 없다!', `MaleText_loc4`='懦夫！蠢货！你们根本无法阻挡觅血者！', `MaleText_loc5`='弱者!蠢蛋!你不能站在覓血者前面!', `MaleText_loc7`='¡Mequetrefes! ¡Necios! ¡No podréis aguantar ante el Cruento!' WHERE `ID`=62844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 버텨라, 깨우는 자여! 놈들도 막바지다!', `MaleText_loc4`='只需要再等一小会，唤醒者！ 他们快要撑不住了！', `MaleText_loc5`='再撐一會兒，喚醒者!他們只剩最後一人了!', `MaleText_loc7`='¡Solo un poco más, heraldo! ¡Están en las últimas!' WHERE `ID`=62845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하구나, 깨우는 자여. 나는 여기 잠깐 더 머물며 내 칼날의 갈증을 채울 것이다. 내가 돌아온 것을 다른 이에게 말해도 되지만, 내 신속한 날개가 너보다 먼저 클락시베스로 나를 데려가 줄 것이다.', `MaleText_loc4`='干得好，唤醒者。我会再留一会，满足我刀刃的渴望。你可以告诉其它人我回来了，但我相信我迅捷的双翼会让我赶在你之前飞抵卡拉克西维斯。', `MaleText_loc5`='做得好，喚醒者。我會留一會兒，填補我手上這把刀的飢渴。你可以告訴其他人我回來了，但我想我的翅膀會讓我早你一步回到卡拉西斐斯。', `MaleText_loc7`='Bien hecho, heraldo. Me quedaré un rato más para saciar la sed de mi hoja. Puedes notificar a los demás de mi regreso, pero creo que mis veloces alas me llevarán a Klaxxi''vess antes de que llegues.' WHERE `ID`=62846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징을 울린 다음에, 수도사들에게 자네 실력을 보여 줘! ...방법은 상관없어.', `MaleText_loc4`='那就敲响那面铜锣，让这些武僧看看你有多大能耐！……无论用怎样的方法，嘿嘿。', `MaleText_loc5`='然後重重往那個鑼敲下去，讓這些僧侶看看你的本事!...用什麼方法都行，嘿。', `MaleText_loc7`='¡Pues GOLPEEN ESE GONG y demuéstrenles a estos monjes de lo que son capaces! ... de un modo u otro, je.' WHERE `ID`=62847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무리살이! 배설물이나 먹는 지저분한 놈들아! 네놈들이 우리 동굴을 더럽혔다. 도망치지는 못한다!', `MaleText_loc4`='聚生虫！肮脏的食粪者！你玷污了我们的洞穴。你休想逃走！', `MaleText_loc5`='螳螂的種!骯髒的東西!你玷污了我們的洞穴。你逃不了的!', `MaleText_loc7`='¡Enjambristas! ¡Sucios tragaestiércol! Profanan nuestra gruta. ¡No escaparán!' WHERE `ID`=62848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 내 목소리가? 이제 내 자식들이 말을 어떻게 듣지? 전처럼 날 사랑할까? 클락시처럼 날 배신하려나?', `MaleText_loc4`='怎么了？臣民们都不听我的了？他们还会爱自己的女皇吗？会不会像卡拉克西一样背叛我？', `MaleText_loc5`='我的聲音，不見了?這樣我的子民怎麼聽得見我?他們還會愛他們的女皇嗎?他們會不會像卡拉西一樣背叛我?', `MaleText_loc7`='¿He perdido la voz? ¿Cómo me oirán mis súbditos? ¿Aún amarán a su Emperatriz? ¿Se volverán contra mí, como los Klaxxi?' WHERE `ID`=62849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 보낸 거냐? 감히 그럴 리가 없어! 그렇지?', `MaleText_loc4`='他们派你来的？他们不敢！不敢的……', `MaleText_loc5`='是他們派你來的嗎?他們沒那個膽!是他們嗎?', `MaleText_loc7`='¿Los han enviado ellos? ¡No osarían! ¿Verdad que no?' WHERE `ID`=62850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 내 최강의 용사들이 너희의 오만함을 심판하리라. 그들은 여왕인 날 보호할 테지!', `MaleText_loc4`='你！我骁勇的勇士们会让你为自己的傲慢付出代价。他们一定会保护自己的女皇！', `MaleText_loc5`='你!你會為你的傲慢付出慘痛代價，我偉大的英雄們不會輕易放過你的。他們必定會保護他們的女皇!', `MaleText_loc7`='¡Ustedes! Sufrirán por su insolencia a manos de mis mejores campeones. ¡Ellos sí que protegerán a su Emperatriz!' WHERE `ID`=62851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 자식들은 들어라! 너희의 여왕이 외부인들에게 위협받고 있다. 모두 처치해!', `MaleText_loc4`='臣民们，听我说！你们的女皇受到了外来者的威胁。他们要杀死我……杀死我们所有人！干掉他们！', `MaleText_loc5`='聽著，我的子民啊!你們的女皇受到這些外來者威脅。他們想殺了我...殺光我們所有人!消滅他們!', `MaleText_loc7`='¡Escúchenme, súbditos! Estos forasteros amenazan a su Emperatriz. Pretenden matarme... ¡matarnos a todos! ¡Destrúyanlos!' WHERE `ID`=62852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님에 대한 도전은 여기까지다!', `MaleText_loc4`='反对女皇的叛乱到此为止了！', `MaleText_loc5`='你對女皇的挑戰就到此為止了!', `MaleText_loc7`='¡Sus desaires a la Emperatriz acaban aquí!' WHERE `ID`=62853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아가 여왕님의 날개 밑에서 멸망하리라!', `MaleText_loc4`='全潘达利亚都将拜倒在女皇之翼下！', `MaleText_loc5`='整個潘達利亞都會匍匐在女皇之翼下!', `MaleText_loc7`='¡Toda Pandaria caerá bajo las alas de la Emperatriz!' WHERE `ID`=62854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하... 이렇게... 지다니...', `MaleText_loc4`='女皇……我……让你失望了……', `MaleText_loc5`='女皇，我讓您失望了...', `MaleText_loc7`='Emperatriz... Te he... fallado...' WHERE `ID`=62855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 뜻이다!', `MaleText_loc4`='这是女皇的命令！', `MaleText_loc5`='這是女皇的命令!', `MaleText_loc7`='¡La Emperatriz lo ordena!' WHERE `ID`=62856;
