UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 하늘은 여왕님 거야!', `MaleText_loc4`='天空属于女皇！', `MaleText_loc5`='天空屬於女皇!', `MaleText_loc7`='¡Los cielos pertenecen a la Emperatriz!' WHERE `ID`=62859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투하면 코르티크다!', `MaleText_loc4`='库尔提克势不可挡！', `MaleText_loc5`='闊席克是無敵的!', `MaleText_loc7`='¡Los Kor''thik no conocen rival en el combate!' WHERE `ID`=62860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스라티크는 이 땅의 원소들을 부려 적들을 평생 사로잡아둘 수 있지!', `MaleText_loc4`='瑟里提克掌控世间元素，将他们的敌人永世囚禁！', `MaleText_loc5`='瑟里席克能融化琥珀，將敵人永遠禁錮起來!', `MaleText_loc7`='¡Los Sra''thik moldean el ámbar y aprisionan a sus enemigos durante toda la eternidad!' WHERE `ID`=62861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자르티크는 날개를 변형시킬 수 있다!', `MaleText_loc4`='强大的扎尔提克操纵风之意志！', `MaleText_loc5`='強大的薩爾席克能以意志控制風!', `MaleText_loc7`='¡Los poderosos Zar''thik controlan el viento a su voluntad!' WHERE `ID`=62862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님을 위한 죽음은 영광이다!', `MaleText_loc4`='为女皇而死乃是荣耀！', `MaleText_loc5`='為女皇而死是一種榮耀!', `MaleText_loc7`='¡Morir por la Emperatriz es un honor!' WHERE `ID`=62863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여왕님의 날개는 꺾이지 않아!', `MaleText_loc4`='女皇之翼拒绝失败！', `MaleText_loc5`='女皇之翼絕不會殞落!', `MaleText_loc7`='¡LAS ALAS DE LA EMPERATRIZ NO PUEDEN FRACASAR!' WHERE `ID`=62864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죗값을 치르게 해주지!', `MaleText_loc4`='你们要为此等罪行付出代价！', `MaleText_loc5`='你要為你的罪過付出代價!', `MaleText_loc7`='¡PAGARÁN POR SUS TRANSGRESIONES!' WHERE `ID`=62865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이처럼 싸우는군!', `MaleText_loc4`='你们就是一群懦夫！', `MaleText_loc5`='你戰鬥的方式像個懦夫!', `MaleText_loc7`='¡Luchan como cobardes!' WHERE `ID`=62866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 도와라!', `MaleText_loc4`='帮帮我，同胞们！', `MaleText_loc5`='弟兄們幫我!', `MaleText_loc7`='¡Ayúdenme, hermanos!' WHERE `ID`=62867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남으려면, 싸워야 한다.', `MaleText_loc4`='为了生存，你必须战斗。', `MaleText_loc5`='為了活下來，你必須戰鬥。', `MaleText_loc7`='Debes luchar para poder sobrevivir.' WHERE `ID`=62868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화는 약자에게나 필요한 거다!', `MaleText_loc4`='只有弱者才希望和平！', `MaleText_loc5`='弱者才需要和平!', `MaleText_loc7`='¡La paz es para los débiles!' WHERE `ID`=62869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 아는 길은 오직 전사의 길뿐이다.', `MaleText_loc4`='我知道的唯一办法是战斗。', `MaleText_loc5`='我只知道如何成為戰士。', `MaleText_loc7`='El único camino que conozco es el del guerrero.' WHERE `ID`=62870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강자만이 살아남는다.', `MaleText_loc4`='只有强者才能生存。', `MaleText_loc5`='只有最強的人能夠活下來。', `MaleText_loc7`='Solo los más fuertes sobreviven.' WHERE `ID`=62871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불가능해! 왜 내 힘이 약해진 거지?', `MaleText_loc4`='不可能！ 为什么我的力量如此不济？', `MaleText_loc5`='不可能!我的力量怎麼會讓我失望?', `MaleText_loc7`='¡Imposible! ¿Por qué me fallan las fuerzas?' WHERE `ID`=62872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 숨을 돌리고 나면... 곧바로 적 100명을 베어버릴 것이다.', `MaleText_loc4`='我要杀死一百个敌人！ 只等我……先喘口气。', `MaleText_loc5`='我要殺掉一百個敵人!只要我能先...喘口氣。', `MaleText_loc7`='¡Mataré a un centenar de enemigos! Tan pronto como... recupere el aliento.' WHERE `ID`=62873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시들이 자고 난 후 나른함에 대해 경고해줬지만, 이정도로 심할 줄은 몰랐구나.', `MaleText_loc4`='他们告诫过我刚醒来时很虚弱，可我没想到有这么糟。', `MaleText_loc5`='他們警告過我喚醒時的不適，但我沒想到事情會這麼糟糕。', `MaleText_loc7`='Ya me advirtieron de que tendría náuseas al despertarme, pero no creía que fuera tan horrible.' WHERE `ID`=62874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮을 것이다.$B$B전투에서 얻은 수천 개의 흉터에 비하면 이쯤이야 아무것도 아니지!', `MaleText_loc4`='我会好起来的。$B$B这点小事情和战斗时留下的数千个伤疤相比，不算什么！', `MaleText_loc5`='我會沒事的。$B$B這跟在戰場上受過的成千上百的傷，根本不能相比!', `MaleText_loc7`='Me pondré bien.$B$B¡Esto no es nada comparado con las miles de cicatrices de la batalla!' WHERE `ID`=62875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말은 적게 하고, 더 많이 싸우라고 했다.', `MaleText_loc4`='我认为我们要少说话多战斗。', `MaleText_loc5`='我說我們得少說點話，多戰鬥。', `MaleText_loc7`='Creo que necesitamos hablar menos y luchar más.' WHERE `ID`=62876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험의 규칙은 간단하다. 이 표적 허수아비들은 분말 폭탄으로 무장하고 있다. 이중 하나라도 폭발하면, 시험은 끝이다.', `MaleText_loc4`='试炼规则很简单。这些活动假人都装有炸弹。只要其中一个爆炸了，你的试炼就算失败。', `MaleText_loc5`='試煉的規則很簡單。這些活動假人都裝著火藥炸彈。只要其中一個爆炸，你的試煉就結束了。', `MaleText_loc7`='Las reglas de la prueba son sencillas. Estos objetivos están equipados con bombas de pólvora. Si explota una, la prueba ha terminado.' WHERE `ID`=62877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 네 능력 중 하나가 우리의 대련을 더 즐겁게 해주겠군. 사원 치유사들을 적들로부터 최대한 오랫동안 보호해라.', `MaleText_loc4`='呃，或许你有个技能能让我们的训练课程变得更加有趣。尽你所能，保护寺院的治疗者免受入侵者的攻击。', `MaleText_loc5`='啊，或許你有能力讓我們的對打課程變得更有趣些。從襲擊者手中保護寺廟醫者，時間越長越好。', `MaleText_loc7`='Ah, es posible que alguna de tus facultades haga nuestras sesiones de entrenamiento más interesantes. Protege a los sanadores del templo todo el tiempo que puedas.' WHERE `ID`=62878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시험에는 우리의 대담한 학생들이 함께 할 것이다. 그들이 계속 싸울 수 있게 지원하여 네 실력을 증명해라.', `MaleText_loc4`='加入试炼的还有几位更……鲁莽的……弟子。想要证明你自己，就别让他们闲下来。', `MaleText_loc5`='我們會有幾個...魯莽的...弟子，在這個試煉中加入你。在戰鬥中保護他們，藉此證明你的能力。', `MaleText_loc7`='En esta prueba te acompañarán algunos de nuestros estudiantes más... temerarios. Demuestra tu pericia cuidando de todos ellos.' WHERE `ID`=62879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금 더 재미있게 해볼까.', `MaleText_loc4`='我们让这变得更有趣些。', `MaleText_loc5`='我們來讓事情變的更有趣點。', `MaleText_loc7`='Vamos a hacerlo un poco más interesante.' WHERE `ID`=62880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발이 빠르길 빌겠다!', `MaleText_loc4`='希望你的腿脚够利索！', `MaleText_loc5`='希望你的腳程夠快!', `MaleText_loc7`='¡Espero que tengas buenos reflejos!' WHERE `ID`=62881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호. 하지만 이것도 가능할까?', `MaleText_loc4`='漂亮。但这个你能行吗？', `MaleText_loc5`='了不起。但你能應付這個嗎?', `MaleText_loc7`='Impresionante. ¿Pero puedes enfrentarte a esto?' WHERE `ID`=62882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 나갈 생각은 버려라.', `MaleText_loc4`='别想逃出我的手心。', `MaleText_loc5`='誰都別想逃。', `MaleText_loc7`='No hay forma de huir de mí.' WHERE `ID`=62883;
