UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병력은... 끝이 없다! 너흰... 이길 수 없어...', `MaleText_loc4`='我们……无穷无尽！你们……赢不了……', `MaleText_loc5`='我們的數量沒有止盡!你們...贏不了的...', `MaleText_loc7`='¡Nuestro ejército... es... infinito! ¡No pueden ganar!' WHERE `ID`=62889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='문을 봉하고 출구를 막아! 침입자들을 처치해!', `FemaleText_loc4`='封锁大门！堵住出口！消灭这些入侵者！', `FemaleText_loc5`='關上大門!擋住出口!消滅這些入侵者!', `FemaleText_loc7`='¡Cerrien las puertas! ¡Bloqueen las salidas! Acaben con los intrusos.' WHERE `ID`=62890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 제국에 맞서는 모든 이들에게 죽음을!', `FemaleText_loc4`='胆敢挑战我帝国的人都只有死路一条！', `FemaleText_loc5`='殺死所有膽敢挑戰我帝國的人!', `FemaleText_loc7`='¡Muerte a todo aquel que desafíe a mi imperio!' WHERE `ID`=62891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으악... 으... 내가... 지다니.', `FemaleText_loc4`='呃……啊……我……败了。', `FemaleText_loc5`='嗚...啊...我...失敗了。', `FemaleText_loc7`='Agh... ah ... He... fracasado.' WHERE `ID`=62892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='패배의 맛이 어떠냐!', `FemaleText_loc4`='品尝失败吧，陌生人！', `FemaleText_loc5`='嚐嚐失敗的滋味吧，陌生人!', `FemaleText_loc7`='¡Experimenta la derrota!' WHERE `ID`=62893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숨을 멎어라!', `FemaleText_loc4`='窒息而死！', `FemaleText_loc5`='安息吧!', `FemaleText_loc7`='¡Deja de respirar!' WHERE `ID`=62894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노래... 그래! 고통을 노래해!', `FemaleText_loc4`='吟唱……对！痛苦地吟唱！', `FemaleText_loc5`='歌唱吧...對!在痛苦中歌唱!', `FemaleText_loc7`='¡Canten! ¡Sí, canten de agonía!' WHERE `ID`=62895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 나를 섬겨라!', `FemaleText_loc4`='你现在要效命于我了！', `FemaleText_loc5`='你現在就要服從我!', `FemaleText_loc7`='¡Ahora me servirán a mí!' WHERE `ID`=62896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것이 내 권위에 도전한 자의 운명이다.', `FemaleText_loc4`='质疑权威的人就是这个下场。', `FemaleText_loc5`='這就是挑戰權威的下場。', `FemaleText_loc7`='Tal es el destino de aquellos que cuestionan la autoridad.' WHERE `ID`=62897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘... 힘이 더 필요해! 경비병! 날 보호해라!', `FemaleText_loc4`='力量……我必须有更大的力量！守卫！保护你们的女皇！', `FemaleText_loc5`='力量...我必須獲得更多力量!守衛!保護你的女皇!', `FemaleText_loc7`='Poder... ¡Necesito más poder! ¡Guardias! ¡Protejan a su Emperatriz!' WHERE `ID`=62898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이길 수 없는 전투였어.', `MaleText_loc4`='你卷入了一场必败的战斗。', `MaleText_loc5`='你加入了必敗的戰爭。', `MaleText_loc7`='Luchas por una causa perdida.' WHERE `ID`=62899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 외부인들을 처치하겠다.', `FemaleText_loc4`='我要处决这些不速之客。', `FemaleText_loc5`='我要好好處置這些外來者。', `FemaleText_loc7`='Me encargaré de los forasteros.' WHERE `ID`=62900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더... 더! 더 있어야 해!', `FemaleText_loc4`='更多……更多！我要更多！', `FemaleText_loc5`='更多...力量!我還要更多力量!', `FemaleText_loc7`='¡Más... más! ¡Necesito más!' WHERE `ID`=62901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제공권에서 밀려.', `MaleText_loc4`='空中优势。', `MaleText_loc5`='空中優勢。', `MaleText_loc7`='Superioridad aérea.' WHERE `ID`=62902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상대로군.', `MaleText_loc4`='早有预料。', `MaleText_loc5`='如我所料。', `MaleText_loc7`='Era de esperarse.' WHERE `ID`=62903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 주인님.', `FemaleText_loc4`='遵命，主人。', `FemaleText_loc5`='是的，主人。', `FemaleText_loc7`='Sí, amo.' WHERE `ID`=62904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 이방인들을 처치해야만 한다, 여제여! 그대의 신민을 정복하러 온 자들이다!', `MaleText_loc4`='你必须消灭这些外来者，女皇！他们来征服你的子民了！', `MaleText_loc5`='妳必須消滅這些外來者，女皇!他們要來征服妳的人民!', `MaleText_loc7`='¡Debes acabar con estos forasteros, Emperatriz! ¡Han venido a conquistar a tu pueblo!' WHERE `ID`=62905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 것! 내 앞에서 죽어라, 하찮은 곤충아. 너희 종족은 내게 아무런 가치가 없다!', `MaleText_loc4`='啊……真是没用！跪倒在我面前受死吧，肮脏的虫子。你们的种族对我毫无价值。', `MaleText_loc5`='啊啊啊啊啊...沒用的廢物!軟弱地死在我面前吧，卑劣的蟲子。你們對我來說毫無價值!', `MaleText_loc7`='¡INÚTIL! Cae a mis pies y muere, insecto despreciable. ¡Tu especie no me sirve de nada!' WHERE `ID`=62906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 놈들은 자신 있으면 날 찾아 봐라. 다른 놈들처럼 비명을 지르며 죽어가겠지만.', `MaleText_loc4`='至于你们其余的人，如果有胆量就来找我吧。和其他人一样，你们都将惨叫着死去。', `MaleText_loc5`='至於你們，有膽就來找我吧。你們會像其他人一樣，在尖叫中死去。', `MaleText_loc7`='En cuanto a ustedes: vengan por mí si se atreven. Morirán gritando, como todos los demás…' WHERE `ID`=62907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽거나 항복해라. 너희는 날 이길 수 없어.', `MaleText_loc4`='死亡或是屈服。你们打败不了我。', `MaleText_loc5`='不投降就死。你們打不贏我的。', `MaleText_loc7`='Ríndanse o mueran. No pueden derrotarme.' WHERE `ID`=62908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 끝이다.', `MaleText_loc4`='一切都完了。', `MaleText_loc5`='全部滅絕。', `MaleText_loc7`='Todo es en vano.' WHERE `ID`=62909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 희망을 버려라.', `MaleText_loc4`='放弃希望吧。', `MaleText_loc5`='放棄一切的希望。', `MaleText_loc7`='Abandona toda esperanza.' WHERE `ID`=62910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망을 받아들여라.', `MaleText_loc4`='拥抱你的绝望吧。', `MaleText_loc5`='擁抱你的絕望。', `MaleText_loc7`='Acepta tu desesperación.' WHERE `ID`=62911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 내게서 도망칠 수 없어. 나는... 온... 세상에... 존재한다...', `MaleText_loc4`='你们逃不出我的掌心。我……无处……不在……', `MaleText_loc5`='你們逃不了的。我在...每一次...呼吸之中...', `MaleText_loc7`='No escaparán de mí. Estoy... en... cada... suspiro…' WHERE `ID`=62912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 얼마나 무력하게 무너졌는지 봐라.', `MaleText_loc4`='看着自己四分五裂吧。', `MaleText_loc5`='你還真容易就被看透。', `MaleText_loc7`='Contempla cómo te aniquilo sin esfuerzo.' WHERE `ID`=62913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 안에 도사린 어둠에 굴복해라.', `MaleText_loc4`='屈服于灵魂深处的黑暗吧。', `MaleText_loc5`='向你靈魂中的黑暗面屈服吧。', `MaleText_loc7`='Sucumbe a la oscuridad de tu alma.' WHERE `ID`=62914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술과 힘을 증명하기 위한 첫 상대로, 가장 강력한 용거북인 흉터껍질을 소개하지!', `MaleText_loc4`='在展现的技巧和力量的首场比试中，我们将要上场的是——最强大的龙龟“刀疤壳”！', `MaleText_loc5`='在我們首場技能與力量的表演中，我們為你帶來最強大的龍龜，疤殼!', `MaleText_loc7`='¡Para nuestra primera demostración de habilidad y poder les presentamos a Escaraza, la poderosa tortuga dragón!' WHERE `ID`=62915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴, 아수라장이 됐군! 누가 수도원 주방에 연락 좀 하지그래. 오늘 저녁은 거북 수프라고!', `MaleText_loc4`='哎呦，真是一团糟啊！ 快派人通知禅院膳房： 我们今天晚上喝龟汤！', `MaleText_loc5`='呼，真是一團亂!找個人去通知僧院廚房，跟他們說今晚有烏龜湯可以喝了!', `MaleText_loc7`='¡Vaya, qué lío! Que alguien informe a las cocinas del monasterio: ¡esta noche cenamos sopa de tortuga!' WHERE `ID`=62916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 그루멀을 잡아먹는 괴수, 키가 5미터에 달하는 분노의 털북숭이, 쿤라이 봉우리를 떠도는 눈밭의 공포, 졸그럼의 차례야!', `MaleText_loc4`='现在要出场的是令土地精胆寒的庞然大物，十五英尺的长毛怪物，昆莱山特有的雪山恶兽，乔古鲁！', `MaleText_loc5`='現在上場的是專吃咕嚕摩、身高十五英尺的大毛怪，崑萊之峰土生土長的冰雪恐懼，悠格魯姆!', `MaleText_loc7`='Es la hora del goliat tragagrúmel, cuatro metros y medio de furia peluda, el terror que acecha en las nieves de la Cima Kun-Lai, ¡JOL''GRUM!' WHERE `ID`=62917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이쿠! 졸그럼이 자네들 같은 살상 기계를 셋이나 상대할 준비는 안 돼 있었던 모양인걸! 준비 얘기가 나와서 말인데...', `MaleText_loc4`='哎哟！ 看来乔古鲁面对这三个杀人机器还没有做好充分的战斗准备！ 说起准备……', `MaleText_loc5`='啊噢!保守的說，悠格魯姆這個雪人還沒準備好要跟三個殺人機器對戰!說到準備好...', `MaleText_loc7`='¡AY! ¡Creo que podemos decir que Jol''Grum no estaba del todo preparado para esta batalla con estas tres máquinas de matar! Hablando de estar preparado...' WHERE `ID`=62918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 꼬마는 친구를 사귀러 왔지... 친해지고 나면 불태워 버리려고 말이야! 판다리아에서 가장 귀엽고 발랄한 꼬마 방화광, 리우양을 소개하겠네!', `MaleText_loc4`='她来这里结交新朋友……然后放火烧他们！这是潘达利亚最漂亮的小淘气纵火者，流炀！', `MaleText_loc5`='她是來這裡交朋友的...然後用火燒他們!這就是潘達利亞最漂亮的俏皮小縱火狂，劉楊!', `MaleText_loc7`='Ha venido a hacer amigos... ¡y a prenderles fuego después! ¡Es la pirómana más mona y juguetona de Pandaria, la pequeña Liuyang!' WHERE `ID`=62919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='촛불처럼 꺼져 버렸군! 과연 누가 이 삼총사와 대적할 수 있을까?!', `MaleText_loc4`='就像蜡烛被掐灭一般！就没有他们三个打败不了的人？', `MaleText_loc5`='就像蠟燭一樣被吹熄了!有這三個傢伙打敗不了的人嗎?', `MaleText_loc7`='¡Apagada como una vela! ¡¿Hay alguien a quien no puedan derrotar estos tres?!' WHERE `ID`=62920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크가 쳐들어왔다고?! 아니지! 탕랑 평원의 방랑 전사, 도끼의 달인 차간 파이어후프라고!', `MaleText_loc4`='刚有人说牦牛攻击了吗？这是斧头大师查干·焰蹄，螳螂高原上游荡的战士！', `MaleText_loc5`='剛剛有人說到犛牛攻擊嗎?!這就是斧頭大師，徘徊在螳螂荒原上的戰士，查剛·火蹄!', `MaleText_loc7`='¡¿Alguien ha dicho ataque de yak?! ¡Es el maestro del hacha Chagan Pezuña Ígnea, guerrero errante de las Estepas de Tong Long!' WHERE `ID`=62921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 볼 만했어! 우리 대단한 싸움꾼들이 차간을 푸짐한 야운골 바비큐로 만들어버렸군...', `MaleText_loc4`='多么激烈的战斗啊！ 我们的斗士干净利索地把查干剁成了一堆碎肉，我们可以准备野牛人烧烤了……', `MaleText_loc5`='真是場精彩的戰鬥啊!我們優良的鬥士們將查剛變成一份揚古風味烤肉了...', `MaleText_loc7`='¡Qué batalla! Nuestros grandes combatientes le han servido a Chagan una buena ración de barbacoa yaungoliana...' WHERE `ID`=62922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 사납고 고약해서 평온의 봉우리에서 쫓겨났다고 하는, 게거품 물고 늘 바나나 타령인 원숭이 수도사, 구름술사 코보를 소개하지!', `MaleText_loc4`='如此野蛮恶毒，被赶下晴日峰的就是愤怒和疯狂的猴子武僧驾云者科博！', `MaleText_loc5`='狂野又猛烈的他被踢下寂靜峰，這就是瘋狂又口吐白沫、總是處於暴走狀態的猴子武僧大師『控雲者』柯博!', `MaleText_loc7`='Tan salvaje y cruel que lo expulsaron del Pico de la Serenidad: ¡es el frenesí de boca espumosa, el siempre loco maestro monje mono DOBLANUBES KOBO!' WHERE `ID`=62923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 피 튀기고 명예로운 싸움이었다고! 우리 영웅 셋이서 코보에게 파멸의 투기장이 원숭이 장난이 아니란 걸 보여 주셨군.', `MaleText_loc4`='多么血腥而激烈的战斗啊！我们的三位英雄向科博证明了一件事情：破军比武场可不是闹着玩的儿戏。', `MaleText_loc5`='這是場多麼光榮又血淋淋的戰鬥!我們的三位英雄們向柯博證明了殲滅競技場可不是鬧著玩的。', `MaleText_loc7`='¡Qué batalla tan sangrienta! Nuestros tres héroes le han enseñado a Kobo que en la Arena de la Aniquilación no sirven las monerías.' WHERE `ID`=62924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나랑 기구를 같이 타게 돼서 귀찮은 건 아니죠? 아빠는 항상 낯선 이에게 이야기하지 말라고 했지만, 당신은 상냥해 보이거든요.', `FemaleText_loc4`='我希望你不介意和我共享气球。我父亲经常告诫我不要和陌生人说话，但你看上去很友善。', `FemaleText_loc5`='我希望你不介意跟我一起搭乘這個氣球。我父親總是告訴我不要跟陌生人說話，但你看起來很友善。', `FemaleText_loc7`='Espero que no te importe que compartamos el globo. Mi padre siempre me decía que no hablara con desconocidos, pero tú tienes aspecto amigable.' WHERE `ID`=62925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조우친 지구, 정말 아름답지 않나요? 전 평생 여기 살았어요.', `FemaleText_loc4`='卓金界美丽吧？我一辈子都生活在这里。', `FemaleText_loc5`='驟晴縣是不是很美?我這輩子都住在這裡。', `FemaleText_loc7`='¿No te parece preciosa la provincia de Zouchin? He vivido aquí toda mi vida.' WHERE `ID`=62926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠는 조우친의 벽 너머는 아가씨에겐 너무 위험하다고 생각해요. 맥주통 휴게소에서 보급품을 구해 와야 할 때만 날 내보내 주시죠.', `FemaleText_loc4`='我父亲认为对于一个淑女来说，到卓金村城墙外面去太危险了。只有当我们需要去酒坛集采购补给时，他才让我离开。', `FemaleText_loc5`='我父親認為驟晴之外的世界對女生來說太過危險了，所以只有我們需要獨罈集的補給品的時候，他才肯讓我離開驟晴。', `FemaleText_loc7`='Mi padre piensa que salir de los muros de Zouchin es demasiado peligroso para una dama. Solo me deja ir cuando necesitamos provisiones de Barrilla.' WHERE `ID`=62927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 내가 보기에 나는 얌전한 아가씨 노릇에는 소질이 없어요. 그것보단 당신같이 모험가가 되는 편이 나을 것 같아요.', `FemaleText_loc4`='在我看来，我不是很擅长做淑女，我可能更适合做一个你这样的探险者。', `FemaleText_loc5`='我所知道的是，我並不擅長做個淑女，所以或許我更適合像你一樣成為一個冒險家。', `FemaleText_loc7`='Estoy pensando que no se me da muy bien ser una dama. A lo mejor me iría mejor siendo aventurera, como tú.' WHERE `ID`=62928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으스스한 폐허예요. 정말 오래됐죠...', `FemaleText_loc4`='那些废墟真吓人。它们太古老了……', `FemaleText_loc5`='那些廢墟讓我毛骨悚然。它們真是古老...', `FemaleText_loc7`='Esas ruinas me ponen los pelos de punta. Son tan antiguas...' WHERE `ID`=62929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 배들을 봐요! 어디서 온 거지?!', `FemaleText_loc4`='看看那些船！它们从哪而来？', `FemaleText_loc5`='看看那些船!他們是從哪兒來的?', `FemaleText_loc7`='¡Mira esos botes! ¡¿De dónde vienen?!' WHERE `ID`=62930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에! 오두막이! 왜 무력한 마을 사람들을 공격하는 거지?', `FemaleText_loc4`='哦不！看看那些小屋！ 他们为什么要攻击手无寸铁的村民？', `FemaleText_loc5`='喔不!看看那些小屋!為什麼他們要攻擊毫無防禦能力的村莊?', `FemaleText_loc7`='¡Oh, no! ¡Mira esas cabañas! ¿Por qué atacan a aldeanos indefensos?' WHERE `ID`=62931;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마을이 공격당하고 있어요! 우리 가족이 무사해야 할 텐데.', `FemaleText_loc4`='我的村庄在受到攻击！我希望家人都安好。', `FemaleText_loc5`='我的村莊受到攻擊!我希望我的家人都沒事。', `FemaleText_loc7`='¡Están atacando mi aldea! Espero que mi familia esté bien.' WHERE `ID`=62932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠 말이 틀렸어요. 조우친조차도 위험하잖아요!', `FemaleText_loc4`='看起来我父亲也错了。即使是在卓金也会是危险的！', `FemaleText_loc5`='看來我父親錯了。就連驟晴也會陷入危險!', `FemaleText_loc7`='Parece que mi padre se equivocaba. ¡Hasta Zouchin puede ser peligrosa!' WHERE `ID`=62933;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 가족이 무사한지 보러 가야겠어요. 우릴 도와줘요!', `FemaleText_loc4`='我要去看看我的家人。请帮帮我们！', `FemaleText_loc5`='我得去確認家人的狀況。請幫助我!', `FemaleText_loc7`='Tengo que ver cómo está mi familia. ¡Ayúdanos, por favor!' WHERE `ID`=62934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들이여! 사마귀들을 추락시켜라!', `MaleText_loc4`='弓箭手！把那些飞行螳螂妖射下来！', `MaleText_loc5`='弓箭手!把空中的螳螂人射下來!', `MaleText_loc7`='¡Arqueros! ¡Derriben a los mántides voladores!' WHERE `ID`=62935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활을 겨누고 공중의 적들을 공격하라!', `MaleText_loc4`='弯弓射箭，攻击那些飞虫！', `MaleText_loc5`='備好弓箭，攻擊飛行的敵人!', `MaleText_loc7`='¡Preparen las flechas y ataquen a los voladores!' WHERE `ID`=62936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름 준비... 부어라, 당장!', `MaleText_loc4`='把油准备好……泼出去！', `MaleText_loc5`='備好熱油...澆下去，動手!', `MaleText_loc7`='¡Listo el aceite! ¡Viertan... ahora!' WHERE `ID`=62937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름을 부어!', `MaleText_loc4`='把油倒下去！', `MaleText_loc5`='把油潑下去!', `MaleText_loc7`='¡Láncenlo todo!' WHERE `ID`=62938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 써서 놈에게 올라타십시오!', `MaleText_loc4`='用火炮把自己发射出去！', `MaleText_loc5`='用大砲把自己發射出去、攻擊他!', `MaleText_loc7`='¡A los cañones! ¡Lancen contra él!' WHERE `ID`=62939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈의 갑옷이 부서졌습니다. 지금 공격하십시오!', `MaleText_loc4`='他的护甲破了。趁现在攻击他！', `MaleText_loc5`='他的盔甲受損了。快攻擊他!', `MaleText_loc7`='Se quebró su armadura. ¡Ataquen ahora!' WHERE `ID`=62940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 들어라. 나, 칼날군주 타야크가 상대해주마.', `MaleText_loc4`='自求多福吧，入侵者。我——刀锋领主塔亚克，将是你们的对手。', `MaleText_loc5`='自求多福吧，入侵者。我，刀鋒領主塔亞克，將是你們的對手。', `MaleText_loc7`='¡En guardia, invasores! Yo, Ta''yak, Señor de las Espadas, seré su contrincante.' WHERE `ID`=62941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완벽해.', `MaleText_loc4`='完美的一击。', `MaleText_loc5`='完美的斬擊。', `MaleText_loc7`='Un corte perfecto.' WHERE `ID`=62942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 칼날군주의 기술이다.', `MaleText_loc4`='这就是刀锋领主的绝技。', `MaleText_loc5`='這就是刀鋒領主的技巧。', `MaleText_loc7`='Esta es la técnica de un Señor de las Espadas.' WHERE `ID`=62943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 항상 누군가를 이렇게 베어버리고, 이 소리를 듣길 원했지. 하지만 믿을 수 없군. 이 소리가 내 몸에서 나게 될 줄이야.', `MaleText_loc4`='刀锋啜饮鲜血的声音如此美妙，如此令我着迷。可这声音竟来自于我的身体，真是讽刺。', `MaleText_loc5`='我一直希望有一天能像這樣砍人，聽到那樣的聲音。但是這聲音居然是從我自己的胸口傳出，真可笑。', `MaleText_loc7`='Siempre quise dar un golpe como ese, escuchar ese sonido algún día. Pero que le haya pasado a mi protórax es ridículo.' WHERE `ID`=62944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈의 갑옷이 부서졌습니다. 지금 공격하십시오!', `MaleText_loc4`='他的护甲破了。趁现在攻击他！', `MaleText_loc5`='他的盔甲破了。現在攻擊他!', `MaleText_loc7`='Se quebró su armadura. ¡Ataquen ahora!' WHERE `ID`=62945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 무적의 군주들 중 가장 위엄 넘치는 황제, 멩을 소환했느냐?', `MaleText_loc4`='谁胆敢召唤我蒙恩，至高无上的君王？！', `MaleText_loc5`='是誰，竟敢召喚諸皇之中最尊貴的孟帝?', `MaleText_loc7`='¿Quién osa invocar al emperador Meng, el más majestuoso de los monarcas?' WHERE `ID`=62946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 황제를 화나게 했다! 그러므로 사형을 선고한다!', `MaleText_loc4`='你犯下了欺君之罪，处以死刑！', `MaleText_loc5`='你激怒了皇帝!判決就是死刑!', `MaleText_loc7`='¡Han enfurecido al Emperador! ¡LA SENTENCIA ES LA MUERTE!' WHERE `ID`=62947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 난 죽고 싶지 않아!', `MaleText_loc4`='我……我不想死！', `MaleText_loc5`='我...我不想死啊!', `MaleText_loc7`='¡No... no quiero morir!' WHERE `ID`=62948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사형을... 당하는 쪽은... 너희였는데.', `MaleText_loc4`='被处决的……本该……是你……', `MaleText_loc5`='死刑...應該是...你們的...', `MaleText_loc7`='La sentencia... debía ser... para ustedes…' WHERE `ID`=62949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼날에 잘려나가는 볏단처럼, 모두 내 앞에 쓰러져라!', `MaleText_loc4`='如同刀下蝼蚁，统统倒在我脚下吧！', `MaleText_loc5`='像鐮刀前的稻桿一樣，全都倒在我面前吧!', `MaleText_loc7`='¡Todos caerán ante mí como el bambú ante una espada!' WHERE `ID`=62950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누가 감히 황제 멩에 맞서리!', `MaleText_loc4`='谁都不能违抗蒙恩的至高王权！', `MaleText_loc5`='沒有人能對抗孟帝的帝王之威!', `MaleText_loc7`='¡Nadie sobrevive a su majestad imperial MENG!' WHERE `ID`=62951;
