UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 끝없는 고통을 너희들에게도 나눠주마!', `MaleText_loc4`='让你们也尝尝我无尽的痛苦！', `MaleText_loc5`='你們也會嚐到我的無盡苦痛!', `MaleText_loc7`='¡Mi agonía eterna también será la suya!' WHERE `ID`=63265;
