UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통은... 이걸로, 끝인가...?', `MaleText_loc4`='一切……终于……结束了吗？', `MaleText_loc5`='終於可以...解脫...了嗎...?', `MaleText_loc7`='¿Es esto... el final? ¿Por fin?' WHERE `ID`=63267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼을... 영혼을 더!', `MaleText_loc4`='还要……更多灵魂！', `MaleText_loc5`='更多...更多靈魂!', `MaleText_loc7`='¡Más... Más almas!' WHERE `ID`=63268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 네 몸뚱이를 찾아와라!', `MaleText_loc4`='找一个容器……然后重返人世！', `MaleText_loc5`='去找軀殼...然後回來!', `MaleText_loc7`='Busca una víctima... ¡y vuelve!' WHERE `ID`=63269;
