UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노한 영혼에 안식은 없다!', `MaleText_loc4`='愤怒的亡者……无法安息！', `MaleText_loc5`='憤怒的亡者...不需要休息!', `MaleText_loc7`='¡No hay paz... para los muertos vengativos!' WHERE `ID`=63271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 물... 어떻게든... 저항해야... 공포에 휩싸여선... 안 돼...', `MaleText_loc4`='不……这水……我必须……坚持住……我不会……害怕……', `MaleText_loc5`='不...這些水...我必須...抵抗...我不應該...懼怕...', `MaleText_loc7`='No... el agua... Debo... resistir... No... tendré miedo...' WHERE `ID`=63272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 너희가 있을 곳이 아니다! 이 물은 보호해야 해... 물러서지 않겠다면 처치해주마!', `MaleText_loc4`='你不属于这里！我必须保护水流……我要驱逐你，要不就杀死你！', `MaleText_loc5`='你不屬於這裡!我必須保護這些水...我將驅逐你，或是殺了你!', `MaleText_loc7`='¡No deben estar aquí! He de proteger el agua... ¡Si no puedo expulsarlos, los mataré!' WHERE `ID`=63273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물을... 보호해다오...', `MaleText_loc4`='保护……水流……', `MaleText_loc5`='請保護...這些水...', `MaleText_loc7`='Protejan... el agua...' WHERE `ID`=63274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙다, 이방인이여. 날 자유롭게 해줘서.', `MaleText_loc4`='谢谢你，陌生人。我自由了。', `MaleText_loc5`='謝謝你，陌生人。我重獲自由了。', `MaleText_loc7`='Gracias, forasteros. Me han liberado.' WHERE `ID`=63275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠에 잠겨라.', `MaleText_loc4`='在黑暗中死去吧。', `MaleText_loc5`='死在黑暗裡吧。', `MaleText_loc7`='Muere en la oscuridad.' WHERE `ID`=63276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이 너희를 감싼다...', `MaleText_loc4`='黑夜将你包围……', `MaleText_loc5`='黑夜籠罩...', `MaleText_loc7`='La noche te envuelve.' WHERE `ID`=63277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장담하건대 $p|1은;는; 제가 만난 중 최고의 전사입니다. 그가 방어책을 세우는 데 도움을 줄 것입니다.', `MaleText_loc4`='我向你们保证，$p是我所见过最优秀的战士。$G他:她;一定能帮你们的村庄做好准备。', `MaleText_loc5`='我向你保證，$p是我見過最棒的戰士。$G他:她;更能協助你的村莊進行整備。', `MaleText_loc7`='Te aseguro que $p es $gel mejor luchador:la mejor luchadora; que he visto. $GÉl:Ella; te ayudará mejor a preparar a tu aldea.' WHERE `ID`=63278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼...!', `MaleText_loc4`='不……！', `MaleText_loc5`='不...!', `MaleText_loc7`='¡No...!' WHERE `ID`=63279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 용서해줘!', `MaleText_loc4`='原谅我！', `MaleText_loc5`='原諒我!', `MaleText_loc7`='¡Perdóname!' WHERE `ID`=63280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주민들이 휴식을 취하는 게 급선무입니다. 쉬는 동안은 저희가 마을을 지키겠습니다.', `MaleText_loc4`='首先，你们的村庄需要休息。我们会一直提供保护，直到他们休息好为止。', `MaleText_loc5`='首先，你的村民需要休息。我們可以提供你一段時間的保護，讓他們有機會喘口氣。', `MaleText_loc7`='Para empezar, tus aldeanos necesitan descansar. Podemos ofrecerte protección el tiempo suficiente para que descansen.' WHERE `ID`=63281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 $p|1이;가; 마을을 방어하는 법을 가르쳐 줄 것입니다.', `MaleText_loc4`='$p还能教你们的村民学些自卫的本领。', `MaleText_loc5`='$p也能教你的村民如何保護自己。', `MaleText_loc7`='$p también puede enseñar a tus aldeanos a defenderse por sí mismos.' WHERE `ID`=63282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대신 청하는 것은, 예언자 카르줄을 찾을 수 있게 도와 달라는 것뿐입니다. 여러분이 주변의 섬에 대해서 저보다 더 잘 아시니까요. 여러분이 지식은 큰 보탬이 될 것입니다.', `MaleText_loc4`='我们唯一的要求，就是请你们帮忙寻找先知克哈祖尔。你们对这周围的岛屿更加熟悉。你们的知识是无比宝贵的。', `MaleText_loc5`='我們只想找到預言者跨茲庫。你比我們更了解這附近的島嶼。你的知識可能很有價值。', `MaleText_loc7`='Solo pedimos ayuda para encontrar al profeta Khar''zul. Tú conoces las islas de alrededor mejor que nosotros. Tus conocimientos serían de un valor incalculable.' WHERE `ID`=63283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넘치는... 공포!', `MaleText_loc4`='震慑灵魂的……恐惧！', `MaleText_loc5`='驚恐...無比!', `MaleText_loc7`='¡Miedo... sobrecogedor!' WHERE `ID`=63284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망치거나... 죽어라!', `MaleText_loc4`='快逃……不然就死！', `MaleText_loc5`='逃離此地..不然就死!', `MaleText_loc7`='¡Salgan de este lugar... o mueran!' WHERE `ID`=63285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허울 좋은 약속! 당신들은 우릴 도울 수 없소. 잔달라 부족은 무자비하단 말이오!', `MaleText_loc4`='承诺，承诺！你无论如何也救不了我们了。赞达拉残忍至极！', `MaleText_loc5`='保證，保證!你根本沒辦法拯救我們。贊達拉非常殘忍!', `MaleText_loc7`='Promesas, promesas. No puedes hacer nada para salvarnos. Los Zandalari son despiadados.' WHERE `ID`=63286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당장은 마을을 지켜 낼 수 있다 해도, 놈들은 수가 훨씬 많소! 도저히 이길 수가 없소!', `MaleText_loc4`='即便我们能保护自己，也是寡不敌众！我们绝对赢不了！', `MaleText_loc5`='即使我們能夠保護自己，他們的人數也遠超過我們!我們根本不可能贏!', `MaleText_loc7`='Aunque pudiéramos defendernos nosotros mismos, nos superan en número. No hay posibilidad de ganar.' WHERE `ID`=63287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이 온다...', `MaleText_loc4`='日落月升……', `MaleText_loc5`='白晝轉為黑夜...', `MaleText_loc7`='El día da paso a la noche...' WHERE `ID`=63288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠이 커진다...', `MaleText_loc4`='黑暗滋长……', `MaleText_loc5`='黑暗蔓延...', `MaleText_loc7`='Crece la oscuridad...' WHERE `ID`=63289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 사라져...', `MaleText_loc4`='光明消退……', `MaleText_loc5`='光明消逝...', `MaleText_loc7`='La luz se desvanece...' WHERE `ID`=63290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤에서... 낮이 되었다!', `MaleText_loc4`='黑夜…变成白昼！', `MaleText_loc5`='黑夜...轉為白晝!', `MaleText_loc7`='¡La noche... da paso al día!' WHERE `ID`=63291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='햇살이... 비춘다...', `MaleText_loc4`='阳光……照耀……', `MaleText_loc5`='陽光...普照...', `MaleText_loc7`='El sol... se abre paso...' WHERE `ID`=63292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시... 새벽이구나...', `MaleText_loc4`='再度……黎明……', `MaleText_loc5`='黎明...再次降臨...', `MaleText_loc7`='De nuevo... el amanecer...' WHERE `ID`=63293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자넨 늘 너무 부정적이네, 호우!', `FemaleText_loc4`='你总是那么消极啊，侯！', `FemaleText_loc5`='侯長老總是這麼悲觀。', `FemaleText_loc7`='¡Qué negativo eres siempre, Hou!' WHERE `ID`=63294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아닐 수도 있네, 호우. 전승지기는 자신이 있는 모양이네. 그 보호의 대가는 무엇이오?', `FemaleText_loc4`='那也许不是真的，侯。游学者似乎很有信心。你的保护要让我们付出什么代价？', `FemaleText_loc5`='侯長老，事情可不一定是如此，博學行者似乎很有信心。我們要做什麼來換取您的保護呢?', `FemaleText_loc7`='Puede que no sea cierto, Hou. El eremita parece estar seguro. ¿Cuánto nos costará tu protección?' WHERE `ID`=63295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋소. 잔달라 부족 퇴치를 도와준다면 예언자 찾는 걸 도와드리겠소.', `FemaleText_loc4`='非常好。如果你能帮我们击退赞达拉，我们就告诉你该怎样找到先知。', `FemaleText_loc5`='非常好。只要你幫我們擊退贊達拉，我們就會幫你找到預言者。', `FemaleText_loc7`='Muy bien. Si nos ayudas a ahuyentar a los Zandalari, te ayudaremos a encontrar al profeta.' WHERE `ID`=63296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 널 부숴주마.', `MaleText_loc4`='我要粉碎你。', `MaleText_loc5`='我要殺了你。', `MaleText_loc7`='Los haré pedazos.' WHERE `ID`=63297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 절대 지지 않아. 내가 제일 세거든.', `MaleText_loc4`='我不会被打败。我不可战胜。', `MaleText_loc5`='我是無懈可擊的不敗神話。', `MaleText_loc7`='Nadie puede derrotarme. Acabo con todos.' WHERE `ID`=63298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주먹이 빨갛구나... 네 피 덕분에!', `MaleText_loc4`='我的双拳沾满了……你的鲜血！', `MaleText_loc5`='你的血染紅了我的拳!', `MaleText_loc7`='Mis puños se tiñen de escarlata... ¡con tu sangre!' WHERE `ID`=63299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽으라면 죽어.', `MaleText_loc4`='要是你死了，就结束了。', `MaleText_loc5`='該死的時候，就死一死。', `MaleText_loc7`='Si mueres, mueres.' WHERE `ID`=63300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 검은 최고다!', `MaleText_loc4`='我的利刃攻无不克！', `MaleText_loc5`='我的刀所向無敵!', `MaleText_loc7`='¡Mi acero no tiene igual!' WHERE `ID`=63301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 완벽한 기술!', `MaleText_loc4`='战技绝伦！', `MaleText_loc5`='無與倫比的技巧!', `MaleText_loc7`='¡Una técnica perfecta!' WHERE `ID`=63302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 전설인데!', `MaleText_loc4`='可是……我的传说！', `MaleText_loc5`='我...我的傳說...', `MaleText_loc7`='¡Pero... mi leyenda!' WHERE `ID`=63303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전설은 지금부터 시작이다!', `MaleText_loc4`='我就是传说！', `MaleText_loc5`='我的傳說由此開始!', `MaleText_loc7`='¡Mi leyenda comienza ahora!' WHERE `ID`=63304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘들게 왔겠지만, 모두 헛수고다. 상으로 고통 없이 죽여주마.', `MaleText_loc4`='你们大老远来到这里，就为了送死。我会让你们死得很干脆。', `MaleText_loc5`='想到你們大老遠跑來這裡送死。我會痛快地送你們上路。', `MaleText_loc7`='Y pensar que han llegado tan lejos solo para morir... Los honraré con una muerte digna.' WHERE `ID`=63305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 사라질 것이다. 어둠이 너를 감쌀 것이다. 그리고 너는 어둠 속을 움직이는 그림자에 공포를 느낄 것이다.', `MaleText_loc4`='你心中的光明将会寂灭。黑暗会笼罩你。潜伏其中的阴影会令你胆寒。', `MaleText_loc5`='光明將遠離你，黑暗會籠罩你。而潛伏其中的陰影將讓你感到恐懼。', `MaleText_loc7`='Su luz se apagará. La oscuridad los envolverá y temerán las sombras que se mueven en su interior.' WHERE `ID`=63306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포가 뭔지 알려 주마!', `MaleText_loc4`='你会知道什么是恐惧！', `MaleText_loc5`='你會嘗到恐懼的滋味!', `MaleText_loc7`='¡Conocerán el miedo!' WHERE `ID`=63307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 질식해라.', `MaleText_loc4`='淹溺在恐惧中吧。', `MaleText_loc5`='被恐懼淹沒吧。', `MaleText_loc7`='Que el terror te asfixie.' WHERE `ID`=63308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망쳐라!', `MaleText_loc4`='逃跑吧！', `MaleText_loc5`='逃啊!', `MaleText_loc7`='¡Huyaaaan!' WHERE `ID`=63309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 질려 웅크려라!', `MaleText_loc4`='在恐惧中颤抖！', `MaleText_loc5`='蜷縮在恐懼中吧!', `MaleText_loc7`='¡Tiemblen de terror!' WHERE `ID`=63310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포를 이기기가 그리 쉬울 줄 아느냐?', `MaleText_loc4`='你以为这么容易就能战胜内心的恐惧吗？', `MaleText_loc5`='你以為能輕易戰勝恐懼嗎?', `MaleText_loc7`='¿Creen que es tan fácil superar sus miedos?' WHERE `ID`=63311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움이 일어난다! 녀석은 굶주린 채 빛을 찾는다.', `MaleText_loc4`='恐惧升腾！它循光而去。它在渴望。', `MaleText_loc5`='恐懼來臨了!它探尋光明。它渴望吞噬。', `MaleText_loc7`='¡El temor crece y busca la luz! Tiene hambre.' WHERE `ID`=63312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전승지기여, 우리를 어떻게 도울 작정이오?', `FemaleText_loc4`='你打算怎么帮我们，游学者？', `FemaleText_loc5`='你打算怎麼幫助我們，博學行者?', `FemaleText_loc7`='¿Qué es lo que piensas hacer para ayudarnos, eremita?' WHERE `ID`=63313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구르단에게 영광을!', `MaleText_loc4`='为了格尔桑的荣耀！', `MaleText_loc5`='葛薩恩的榮耀!', `MaleText_loc7`='¡Por la gloria de Gurthan!' WHERE `ID`=63314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것이 하르닥의 힘이다!', `MaleText_loc4`='见识哈飒克的力量吧！', `MaleText_loc5`='這就是哈薩科的力量!', `MaleText_loc7`='¡Este es el poder de los Harthak!' WHERE `ID`=63315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카게쉬를 위해!', `MaleText_loc4`='为了克尔格西！', `MaleText_loc5`='為了卡傑許!', `MaleText_loc7`='¡Por los Kargesh!' WHERE `ID`=63316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 시간이다!', `MaleText_loc4`='死亡时间到！', `MaleText_loc5`='受死吧，你們!', `MaleText_loc7`='¡Ya es hora de morir!' WHERE `ID`=63317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으흐흐! 아프겠군!', `MaleText_loc4`='噢吼吼！那可真疼。', `MaleText_loc5`='喔哈哈，那一定很痛。', `MaleText_loc7`='¡Jo, jo, jo! Eso debe haber dolido.' WHERE `ID`=63318;
