UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포가 마음에 드리웁니다... 저항할 수가 없어요.', `MaleText_loc4`='恐惧攫住了我的心神。我……无力抵抗。', `MaleText_loc5`='恐懼籠罩了我的心靈。我...無法抵擋。', `MaleText_loc7`='El miedo me nubla la mente. No puedo resistirlo.' WHERE `ID`=63321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포와 맞서 싸우십시오. 전 이제 잠시나마... 평화를 얻겠군요.', `MaleText_loc4`='你面对自己的恐惧。迎接片刻的……安宁。', `MaleText_loc5`='面對你的恐懼。那一刻將是...平靜的。', `MaleText_loc7`='Se enfrentan al miedo. Un momento de paz...' WHERE `ID`=63322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄은 충분하니... 선물로 줄게!', `MaleText_loc4`='我带的炸弹足够……炸飞你们！', `MaleText_loc5`='我的炸彈足夠炸死...所有的人!', `MaleText_loc7`='He traído bombas suficientes... ¡para todos ustedes!' WHERE `ID`=63323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨으십시오. 제가 샤의 명령대로 여러분을 쓰러뜨리지 않도록!', `MaleText_loc4`='快躲起来吧，以免我奉煞魔之命，将你们赶尽杀绝！', `MaleText_loc5`='尋找掩護，免得我在煞的命令之下殺了你!', `MaleText_loc7`='Buscad refugio, ¡u os abatiré como lo ordena el sha!' WHERE `ID`=63324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 망했다...', `MaleText_loc4`='我……搞砸了……', `MaleText_loc5`='我...失敗了...', `MaleText_loc7`='Son... la... bomba…' WHERE `ID`=63325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤의 힘이 너무 강합니다... 제게 여러분을 죽이라고 명령합니다.', `MaleText_loc4`='它的力量如此强大。它要我消灭你。', `MaleText_loc5`='它的力量如此強大。它強迫我消滅你。', `MaleText_loc7`='Es demasiado poderoso... Me obliga a acabar con ustedes.' WHERE `ID`=63326;
