UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 맞설 수 있는 자는 없습니다. 여러분 역시 쓰러질 겁니다.', `MaleText_loc4`='没人能对抗恐惧。你必将消亡。', `MaleText_loc5`='沒有人能對抗恐懼。你將會死去。', `MaleText_loc7`='Nadie puede resistirse al miedo. Perecerán.' WHERE `ID`=63331;
