UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 봐주지 마라, 난 진짜로 싸울 테니!', `MaleText_loc4`='我可不会留情面！', `MaleText_loc5`='使出全力吧，我可不會手下留情!', `MaleText_loc7`='No se contengan; ¡yo no lo haré!' WHERE `ID`=63334;
