UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술을 더 연마하거라.', `MaleText_loc4`='武艺不精。', `MaleText_loc5`='你的技巧還需要磨練。', `MaleText_loc7`='Necesitas trabajar tu técnica.' WHERE `ID`=63336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또다시 갇힐 순 없어. 음영파는 날 막을 수 없다. 그건 네 놈도 마찬가지지!', `MaleText_loc4`='你们休想再封印我。影踪派阻止不了我。你们也不行！', `MaleText_loc5`='我絕不會再被囚禁。影潘的傢伙阻擋不了我。你們也不行!', `MaleText_loc7`='No volverán a encerrarme. El Shadopan no pudo conmigo. ¡Ustedes tampoco podrán!' WHERE `ID`=63337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 가슴이 폭력에 물들어 있는 한... 난... 다시... 돌아올 것이다.', `MaleText_loc4`='只要你们心中的暴虐不除……我……就会……回来的……', `MaleText_loc5`='只要你們心中還存有暴力，我就..會回來...', `MaleText_loc7`='Siempre que la violencia anide en sus corazones... volveré…' WHERE `ID`=63338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭력에 의한 죽음...', `MaleText_loc4`='又一次暴虐的死亡……', `MaleText_loc5`='給你個痛快...', `MaleText_loc7`='Otra muerte violenta...' WHERE `ID`=63339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오의 샤가 내 몸에서는 물론, 수도원에서도 도망쳤네. 정말 고맙네, 이방인이여. 음영파가 자네에게 빚을 졌군. 자, 이제부터 할 일이 아주 많다네...', `MaleText_loc4`='恨之煞离开了我的身体……也离开了禅院。我必须要谢谢你，陌生人。影踪派欠你个人情。现在，还有很多事情要做……', `MaleText_loc5`='仇恨之煞已逃離我的身體...以及僧院。我必須感謝你，陌生人。影潘欠你一次。現在，還有很多工作要做...', `MaleText_loc7`='El Sha del odio ha abandonado mi cuerpo... y el monasterio. Se los agradezco, forasteros. El Shadopan está en deuda con ustedes. Ahora queda mucho trabajo por hacer...' WHERE `ID`=63340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주와 음영파는 내 거다. 다가와서 내 손에 죽어라. 앞으로 내게 맞서고 최후를 맞이할 모든 이들처럼!', `MaleText_loc4`='祝踏岚和影踪派是我的。快过来受死吧，跟我作对的人都不会有好下场！', `MaleText_loc5`='塔蘭·祝和影潘都是我的。你們快過來受死吧!所有膽敢違逆我的人全都得死!', `MaleText_loc7`='Taran Zhu y el Shadopan me pertenecen. Vengan y mueran a mis manos, como morirá todo aquel que se oponga a mí.' WHERE `ID`=63341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오가 모두를 잠식하고 지배하리라!', `MaleText_loc4`='仇恨将吞噬一切，征服一切！', `MaleText_loc5`='仇恨會吞噬並征服萬物!', `MaleText_loc7`='¡El odio lo consumirá y lo conquistará todo!' WHERE `ID`=63342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼!', `MaleText_loc4`='不……不！', `MaleText_loc5`='不...不!', `MaleText_loc7`='No... ¡NO!' WHERE `ID`=63343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 패배에 분개하라!', `MaleText_loc4`='为你的失败而愤怒吧。', `MaleText_loc5`='為自己的失敗而憤怒吧。', `MaleText_loc7`='¡Ódiate por tu derrota!' WHERE `ID`=63344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 증오가 날 살찌운다!', `MaleText_loc4`='你的仇恨滋养了我！', `MaleText_loc5`='用你的恨意餵養我!', `MaleText_loc7`='¡Aliméntame con tu odio!' WHERE `ID`=63345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공부하러 온 게 아니라면, 널 수업 교재로 써야겠다.', `MaleText_loc4`='如果你不是来学习的，我就会把你当成教材。', `MaleText_loc5`='如果你不是來上課的，那就來當我的活教材吧。', `MaleText_loc7`='Si no han venido a estudiar, servirán como especímenes.' WHERE `ID`=63346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파발락이 못 했던 일을 내가 해주지!', `MaleText_loc4`='我会完成帕瓦拉克做不到的事！', `MaleText_loc5`='我會完成帕伐拉克辦不到的事!', `MaleText_loc7`='¡Yo conseguiré lo que Pa''valak no pudo!' WHERE `ID`=63347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 군대를 헤치고 먼 길을 오느라 고생 많았다. 하지만 내가... 너희를 처치한다. 그리고 다리는 내가 건설할 거야.', `MaleText_loc4`='尽管你们从我的大军中杀出一条血路，来到了这里，但是……我会杀了你们，我会把桥造起来。', `MaleText_loc5`='你也許做得很好。你也許從我的軍隊中殺出了一條血路，但我...我會殺了你，而且我會把橋建起來。', `MaleText_loc7`='Han llegado hasta aquí... se han abierto paso a través de mi ejército, pero... los mataré y construiré el puente.' WHERE `ID`=63348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다... 다리를...', `MaleText_loc4`='架……桥……', `MaleText_loc5`='那座...橋...', `MaleText_loc7`='El... puente...' WHERE `ID`=63349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 비켜.', `MaleText_loc4`='滚开。', `MaleText_loc5`='擋我者死!', `MaleText_loc7`='Fuera de mi camino.' WHERE `ID`=63350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 일해! 동이 트기 전까지 다리를 완성해야 한다!', `MaleText_loc4`='回去工作！这桥必须在曙光初露时完成！', `MaleText_loc5`='回去工作!我希望這座橋在第一道曙光出現之前蓋好!', `MaleText_loc7`='¡Vuelvan al trabajo! Quiero que el puente esté terminado al amanecer.' WHERE `ID`=63351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비명과 울부짖는 소리가 전당에 울려퍼지는구나.', `MaleText_loc4`='尖叫和犬吠声回响在大厅里。', `MaleText_loc5`='尖叫聲與斷斷續續的回聲在大廳裡迴盪。', `MaleText_loc7`='Los gritos y los ladridos retumban por las salas.' WHERE `ID`=63352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬을 수색해서 보의 가마솥에 던져 넣을 맥주를 찾으십시오. 단, 보를 호위할 사람은 남겨 두십시오.', `MaleText_loc4`='在岛上搜索美酒，添加到珀的大锅里，但要留人在附近保护珀！', `MaleText_loc5`='在島上蒐尋更多啤酒來倒入布林的大鍋。記得要有人在附近保護布林!', `MaleText_loc7`='Busca brebaje para añadirlo al caldero de Bo, ¡pero que alguien se quede cerca para protegerlo!' WHERE `ID`=63353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들 모두 냠냠해 버려, 두크!', `MaleText_loc4`='狠狠地打！', `MaleText_loc5`='揍他們個大廢渣!', `MaleText_loc7`='¡Machákalos, gran Kaka!' WHERE `ID`=63354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 커다란 두크 쓰러뜨렸다고?', `MaleText_loc4`='无毛怪打死了大乌克门？！', `MaleText_loc5`='怪怪人打大廢渣!?', `MaleText_loc7`='¿El makaku ha hecho kraku a gran Kaka?' WHERE `ID`=63355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏은 꿀꺽 먹혀버릴 거야!', `MaleText_loc4`='蠢蛋要被揍扁了！', `MaleText_loc5`='怪怪人準備完蛋!', `MaleText_loc7`='¡El makaku va a acabar jeringado!' WHERE `ID`=63356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼 쾅!', `MaleText_loc4`='使劲打！', `MaleText_loc5`='去他的!', `MaleText_loc7`='¡Hazles kraku!' WHERE `ID`=63357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아!', `MaleText_loc4`='啊啊！', `MaleText_loc5`='啊啊啊啊啊啊!', `MaleText_loc7`='¡AHHHHH!' WHERE `ID`=63358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이 호젠 잡아먹는다!', `MaleText_loc4`='蠢蛋是猢狲的大克星！', `MaleText_loc5`='怪怪的巨大猴人殺手!', `MaleText_loc7`='¡Makaku es gran jeringador de hozen!' WHERE `ID`=63359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 이방인! 이곳의 호젠들에게 강한 인상을 남겼더군. 이제 호젠은 자네들을 두려워하고 있네.', `MaleText_loc4`='你好，陌生人！你给那些猢狲留下了很深的印象。我敢说他们已经开始害怕你了。', `MaleText_loc5`='哈囉，陌生人!你還真是讓這裡的猴人印象深刻。我敢說他們開始怕你了。', `MaleText_loc7`='¡Hola, desconocido! Estás causando revuelo entre los hozen de la zona. Yo diría que empiezan a tenerte miedo.' WHERE `ID`=63360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 숨쉬는... 진짜 트롤이라니! 이야기 속 모습과 똑같군. 호젠에게 매서운 맛을 보여줬던데.', `MaleText_loc4`='天呐——一个活的巨魔！你跟故事里讲的完全一样。你已经狠狠教训过那些猢狲了。', `MaleText_loc5`='活生生的食人妖!你跟故事上說的一樣。看來你給了猴人不少教訓。', `MaleText_loc7`='¡Por mis barbas! ¡Un trol de verdad! Eres exactamente como los describen las historias. Les has dado una lección a los hozen.' WHERE `ID`=63361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 화났습니다!', `MaleText_loc4`='%s发怒了！！', `MaleText_loc5`='%s很生氣!!', `MaleText_loc7`='¡%s está enfadado!' WHERE `ID`=63362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘을 나는 배와 함께 추락한 모양이군. 자네에게 묻고 싶은 게 많네. 하지만 이곳은 대화하기에 좋지 않군.', `MaleText_loc4`='你肯定是从那艘坠毁的飞船上下来的。我有很多问题要问你，但这不是聊天的地方。', `MaleText_loc5`='你一定是來自那些墜毀的飛天船。我有很多問題想問你，但這個地方不適合聊天。', `MaleText_loc7`='Debes de ser uno de los forasteros de la nave que se estrelló. Tengo muchas preguntas que hacerte, pero este no es buen sitio para platicar.' WHERE `ID`=63363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 여유가 있을 때, 여기 언덕 위쪽에 있는 이야기의 동굴로 찾아와 주게.', `MaleText_loc4`='等你有空的时候，请到这座山上的千言洞来找我！', `MaleText_loc5`='等你有空的時候，請到這山上的箴言之穴找我說話!', `MaleText_loc7`='Cuando tengas tiempo para platicar, reúnete conmigo en la Cueva de las Palabras, en lo alto de la colina.' WHERE `ID`=63364;
