UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<영웅적인 그림을 그립니다.>', `MaleText_loc4`='<画出英雄的图案。>', `MaleText_loc5`='<畫一些英雄人物。>', `MaleText_loc7`='<Pinta algo heroico.>', `FemaleText_loc1`='<영웅적인 그림을 그립니다.>', `FemaleText_loc4`='<画出英雄的图案。>', `FemaleText_loc5`='<畫一些英雄人物。>', `FemaleText_loc7`='<Pinta algo heroico.>' WHERE `ID`=63367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 하하하... 얼라이언스가 무엇을 위해 싸우는지 알겠군.', `MaleText_loc4`='啊！呵呵--现在我知道你们联盟为何而战了。', `MaleText_loc5`='啊!哈哈─我現在懂得你們的聯盟是為何而戰了。', `MaleText_loc7`='¡Ah! Ja, ja. Ya veo por qué lucha tu Alianza.' WHERE `ID`=63368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 우리가 조금 더 오동통한 건 사실이지만, 자네들과 우린 그렇게 다르지 않다는 걸 알겠어.', `MaleText_loc4`='当然我不介意你们多喂我的鸟儿一点肉，但我开始发现你们和熊猫人之间也并没有太大的差异嘛。', `MaleText_loc5`='我喜歡把鳥兒餵肥一點，沒錯。可是我能明白你們族人和我們其實差異不大。', `MaleText_loc7`='A mí los pájaros me gustan con algo más de carne, no sé si me entiendes, pero ya veo que no somos tan diferentes.' WHERE `ID`=63369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 붉은색과 푸른색 벌판이 초록 땅에서 거칠게 충돌하는군.', `MaleText_loc4`='让我们来看看……成片的红色和蓝色，在绿色的土地上剧烈碰撞。', `MaleText_loc5`='看看這是什麼?一整片的紅色與藍色，猛烈衝撞在綠色的大地上。', `MaleText_loc7`='¿Qué tenemos aquí? Mareas rojas y azules enfrentándose en una tierra verde.' WHERE `ID`=63370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 의미일까? 자네 마음 속에 거친 혼란이 느껴지는군.', `MaleText_loc4`='这意味着什么？我听到了你心中的忐忑，我的新朋友。', `MaleText_loc5`='這代表什麼呢?我看得出來你的心裡充滿了混亂，我的新朋友。', `MaleText_loc7`='¿Qué podría significar? Veo que tu corazón está muy agitado.' WHERE `ID`=63371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 위대한 얼라이언스의 전사인가? 문장으로 사자를 골랐군.', `MaleText_loc4`='我明白了——联盟伟大将士中的一员，是吗？你们选择雄狮作为徽记。', `MaleText_loc5`='我懂了─你們聯盟戰士的一名精銳，是嗎?你們的紋章是頭獅子。', `MaleText_loc7`='Ya veo, uno de los grandes guerreros de tu Alianza, ¿verdad? Has elegido el león como emblema.' WHERE `ID`=63372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들은 강인하고 맹렬하다는 걸 알겠네. 하지만 항상 기억하게. 사자는 배고플 때만 살상한다는 걸.', `MaleText_loc4`='你们的人民勇敢而强悍。但请记住，雄狮只在饥饿时才会杀戮。', `MaleText_loc5`='你們的族人既勇敢又兇猛。可是永遠別忘了，獅子只有飢餓的時候才殺戮。', `MaleText_loc7`='Tu pueblo es valiente y feroz. Pero recuerda siempre que el león solo mata cuando tiene hambre.' WHERE `ID`=63373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 여기 오는군. 그래, 그래. 여기서 친구를 사귀기가 얼마나 쉬운지 알겠나?', `MaleText_loc4`='它们都在这儿，是的，就这样。你看，在这儿交朋友是不是很简单？', `MaleText_loc5`='牠們過來了，很好，很好。你明白在這裡交朋友有多容易了嗎?', `MaleText_loc7`='Ahí están, sí, sí. ¿Ves que fácil es hacer amigos aquí?' WHERE `ID`=63374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하게. 판다리아에서는 동맹을 만드는 데 칼이 꼭 필요하지 않다는 사실을.', `MaleText_loc4`='请记住，在潘达利亚，不是所有的盟友都必须用刀剑来赢得的。', `MaleText_loc5`='請記住，在潘達利亞不是只有兵戎相見，才能贏得盟友的。', `MaleText_loc7`='Por favor, recuerda que en Pandaria no todos los aliados se ganan a punta de espada.' WHERE `ID`=63375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 내 새들이 자네를 좋아하는군. 나도 그래야겠어.', `MaleText_loc4`='好吧……我的鸟儿可喜欢你了。我听它们的。', `MaleText_loc5`='嗯...我的鳥兒喜歡你。我就效法牠們吧。', `MaleText_loc7`='Vaya... mis pájaros te han tomado cariño. Yo creo que haré lo mismo. ' WHERE `ID`=63376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 친구! 내가 어떻게 도와주면 되겠나?', `MaleText_loc4`='欢迎你，我来自联盟的新朋友！能为你效劳吗？', `MaleText_loc5`='歡迎，來自聯盟的新朋友!我能幫上什麼忙嗎?', `MaleText_loc7`='¡Te doy la bienvenida, miembro de la Alianza! ¿En qué puedo ayudarte?' WHERE `ID`=63377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다! 천둥왕이 일어나 이 땅을 네게서 빼앗을 것이다.', `MaleText_loc4`='太迟了！雷电之王将会崛起，从你手上夺取这片土地。', `MaleText_loc5`='你來遲了!雷王將會再起，並從你手中奪走這片土地。', `MaleText_loc7`='¡Llegan tarde! El Rey del Trueno se alzará y les arrebatará esta tierra.' WHERE `ID`=63378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 유해를 어디로 가져간 거냐?!', `MaleText_loc4`='雷电之王的遗骸哪儿去了？！', `MaleText_loc5`='雷王的遺體被拿到哪兒去了?!', `MaleText_loc7`='¡¿Adónde se han llevado los restos del Rey del Trueno?!', `FemaleText_loc1`='천둥왕의 유해를 어디로 가져간 거냐?!', `FemaleText_loc4`='雷电之王的遗骸哪儿去了？！', `FemaleText_loc5`='雷王的遺體被拿到哪兒去了?!', `FemaleText_loc7`='¡¿Adónde se han llevado los restos del Rey del Trueno?!' WHERE `ID`=63379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님! 덕분에 살았습니다! 저희는 안전한 곳으로 피신하겠습니다.', `MaleText_loc4`='$p！是你救了我们！我们会到安全的地方去。', `MaleText_loc5`='$p!你救了我們!我們會到某個安全的地方去。', `MaleText_loc7`='¡$p! ¡Nos has salvado! Vayamos a algún lugar seguro.', `FemaleText_loc1`='$p 님! 덕분에 살았어요! 저희는 안전한 곳으로 피신할게요.', `FemaleText_loc4`='$p！是你救了我们！我们会到安全的地方去。', `FemaleText_loc5`='$p!你救了我們!我們會到某個安全的地方去。', `FemaleText_loc7`='¡$p! ¡Nos has salvado! Vayamos a algún lugar seguro.' WHERE `ID`=63380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골은 너무 강합니다... 아무래도 당신네 사람들에게 의지해야겠습니다.', `MaleText_loc4`='野牛人太强大了……也许我们需要寻求你族人的庇护。', `MaleText_loc5`='揚古的力量如此強大...或許我們得仰賴你的人民保護我們。', `MaleText_loc7`='Los yaungol son muy poderosos... Quizás debamos recurrir a tu gente en busca de protección.', `FemaleText_loc1`='야운골은 너무 강해요... 아무래도 당신네 사람들에게 의지해야겠어요.', `FemaleText_loc4`='野牛人太强大了……也许我们需要寻求你族人的庇护。', `FemaleText_loc5`='揚古的力量如此強大...或許我們得仰賴你的人民保護我們。', `FemaleText_loc7`='Los yaungol son muy poderosos... Quizás debamos recurrir a tu gente en busca de protección.' WHERE `ID`=63381;
