UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누... 눈 앞에서 일생이 주마등처럼 지나갔습니다!', `MaleText_loc4`='我……我差点就去见死神了！', `MaleText_loc5`='我...我看見我的人生從我眼前閃過!', `MaleText_loc7`='¡He... he visto la vida pasar por delante de mis ojos!', `FemaleText_loc1`='누... 눈 앞에서 일생이 주마등처럼 지나갔어요!', `FemaleText_loc4`='我……我差点就去见死神了！', `FemaleText_loc5`='我...我看見我的人生從我眼前閃過!', `FemaleText_loc7`='¡He... he visto la vida pasar por delante de mis ojos!' WHERE `ID`=63383;
