UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용이 도원 밖으로 나가려 하지 않습니다! 도원으로 돌아가십시오!', `MaleText_loc4`='你的翔龙不能离开百木园！马上回百木园去！', `MaleText_loc5`='你的蛟不會跑到落英園以外的地方!立刻回到落英園去!', `MaleText_loc7`='¡Tu dragón no se aventurará más allá de El Arboretum! ¡Vuelve ahora a El Arboretum!', `FemaleText_loc1`='용이 도원 밖으로 나가려 하지 않습니다! 도원으로 돌아가십시오!', `FemaleText_loc4`='你的翔龙不能离开百木园！马上回百木园去！', `FemaleText_loc5`='你的蛟不會跑到落英園以外的地方!立刻回到落英園去!', `FemaleText_loc7`='¡Tu dragón no se aventurará más allá de El Arboretum! ¡Vuelve ahora a El Arboretum!' WHERE `ID`=63386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발각됐군! 싸울 준비를 하게. 이 협곡을 벗어나야 해!', `MaleText_loc4`='他们是怎么发现我们的？拿起武器——我们必须冲出这条峡谷！', `MaleText_loc5`='他們怎麼找到我們的?拿起武器!我們必須離開這個狹谷!', `MaleText_loc7`='¿Cómo nos han encontrado? Preparad las armas, ¡tenemos que salir de este cañón!' WHERE `ID`=63387;
