UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 여제 폐하께 반항하다니 어리석구나!', `MaleText_loc4`='真是蠢货，竟敢违抗女皇！', `MaleText_loc5`='你是個蠢蛋才會反抗女皇!', `MaleText_loc7`='¡Todo aquel que se oponga a la emperatriz es un necio!' WHERE `ID`=63391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아 전체가 여제 폐하 앞에 절할 것이다!', `MaleText_loc4`='潘达利亚的子民都要臣服于女皇陛下！', `MaleText_loc5`='整個潘達利亞都要拜伏在女皇的腳下!', `MaleText_loc7`='¡Toda Pandaria se inclinará ante la Emperatriz!' WHERE `ID`=63392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련장을 벗어나고 있습니다! 추락하기 전에 도원이나 비취봉우리 바다로 돌아가십시오!', `MaleText_loc4`='你快要超出训练场地了！返回百木园或玉塔海，否则就要被甩下去了！', `MaleText_loc5`='你跑到訓練場以外的地方了!在你被拋下前，回到落英園或玉尖海去!', `MaleText_loc7`='¡Estás saliendo de los límites del espacio de entrenamiento! ¡Vuelve a El Arboretum o a El Mar de la Aguja de Jade antes de que te pierdas!', `FemaleText_loc1`='훈련장을 벗어나고 있습니다! 추락하기 전에 도원이나 비취봉우리 바다로 돌아가십시오!', `FemaleText_loc4`='你快要超出训练场地了！返回百木园或玉塔海，否则就要被甩下去了！', `FemaleText_loc5`='你跑到訓練場以外的地方了!在你被拋下前，回到落英園或玉尖海去!', `FemaleText_loc7`='¡Estás saliendo de los límites del espacio de entrenamiento! ¡Vuelve a El Arboretum o a El Mar de la Aguja de Jade antes de que te pierdas!' WHERE `ID`=63393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크가 열광의 페로몬을 들이마십니다!', `MaleText_loc4`='皇家宰相佐尔洛克吸入狂热信息素！', `MaleText_loc5`='女皇大臣索拉格吸入狂熱費洛蒙!', `MaleText_loc7`='¡El visir imperial Zor''lok inhala las feromonas de celo!' WHERE `ID`=63394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 무용을 백호 님 앞에서 증명해 보일 준비가 됐나?', `MaleText_loc4`='你做好在猛虎之眼展示武艺的准备了吗？', `MaleText_loc5`='你準備好要在白虎的雙眼注視下展現你的武藝本領了嗎?', `MaleText_loc7`='¿Están listos para demostrar sus habilidades marciales aquí, en el ojo del tigre?' WHERE `ID`=63395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 전투를 치를 준비가 됐나? 징을 울리고 시작하게!', `MaleText_loc4`='准备好再次战斗了？敲响那面锣！即刻开始！', `MaleText_loc5`='準備進行下一場戰鬥了嗎?敲響那面鑼，然後，上吧!', `MaleText_loc7`='¿Listos para la siguiente pelea? ¡Que suene ese gong y A LUCHAR!' WHERE `ID`=63396;
