UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠뻑이의 선원이 되고 싶으시다고요? 그렇다면 다른 이들과 똑같이 밑바닥부터 시작하셔야 해요.', `FemaleText_loc4`='你想成为“闷水壶”的船员？那你恐怕得像其他人那样，从头做起。', `FemaleText_loc5`='你想成為『濕佬』的船員的一份子嗎?那你就得跟每個人一樣從基層做起。', `FemaleText_loc7`='¿Quieres ser parte de la tripulación de Aguado? Entonces empezarás desde abajo, como todos los demás.' WHERE `ID`=63416;
