UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t 가랄론이 높이 날아올라 |cFFFF0000|Hspell:128555|h[대규모 으깨기]|h|r를 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t加拉隆飞上高空，准备发起|cFFFF0000|Hspell:128555|h[重碾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t 加拉隆高高飛起，準備使出|cFFFF0000|Hspell:128555|h[重磅碾壓]|h|r!', `MaleText_loc7`='|TInterfaceIconswarrior_talent_icon_thunderstruck.blp:20|t¡Garalon alza el vuelo y prepara un |cFFFF0000|Hspell:128555|h[Machaque masivo]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t 가랄론이 높이 날아올라 |cFFFF0000|Hspell:128555|h[대규모 으깨기]|h|r를 준비합니다!', `FemaleText_loc4`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t加拉隆飞上高空，准备发起|cFFFF0000|Hspell:128555|h[重碾]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\warrior_talent_icon_thunderstruck.blp:20|t 加拉隆高高飛起，準備使出|cFFFF0000|Hspell:128555|h[重磅碾壓]|h|r!', `FemaleText_loc7`='|TInterfaceIconswarrior_talent_icon_thunderstruck.blp:20|t¡Garalon alza el vuelo y prepara un |cFFFF0000|Hspell:128555|h[Machaque masivo]|h|r!' WHERE `ID`=63425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쾅! 수많은 야운골을 날려 버렸습니다! 저런, 도망치는군요!', `MaleText_loc4`='[PH——假装这里有一个完美的过场动画。]砰！你赶跑了那群野牛人！哦伙计，他们跑掉了！', `MaleText_loc5`='[PH-Pretend there is a totally awesome cutscene here。]砰!你炸掉了一批揚古!喔老兄，他們在逃跑!', `MaleText_loc7`='[PH - Pretend there is a totally awesome cutscene here.]BOOM! You just blew up a bunch of yaungol! Oh man, they''re running away!' WHERE `ID`=63426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린이 놈들을 쫓아갑니다. 안 돼! 린!', `MaleText_loc4`='[PH]林正在追赶他们。哦不！林！', `MaleText_loc5`='[PH]林正在追趕他們。喔不!林!', `MaleText_loc7`='[PH]Lin''s chasing after them. Oh no! Lin!' WHERE `ID`=63427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(문 저편에서) 무식하게 생긴 야운골 대장이 나타나더니 으르렁거립니다. 보스전에 대비해야겠군요!', `MaleText_loc4`='[PH]野蛮的野牛人首领出现了（从大门另一侧），对你怒吼着。你最好准备和首领进行战斗！', `MaleText_loc5`='[PH]一個野生揚古首領出現(在門的另一頭)並對你大吼。你最好準備好面對一場首領戰!', `MaleText_loc7`='[PH]A wild yaungol boss appears (from beyond the gate) and roars at you. You best get ready for a boss fight!' WHERE `ID`=63428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 비켜주겠나? 사진 좀 찍어야 한단 말일세.', `MaleText_loc4`='你不介意吧？我们打算在这里拍张照片。', `MaleText_loc5`='你介意嗎?我們想拍張照，在這裡拍。', `MaleText_loc7`='¿Te importa? Estamos intentando hacer una foto.' WHERE `ID`=63429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가서 이 사진을 딸에게 보내고 싶어 못 참겠군. 깜짝 놀랄 걸세!', `MaleText_loc4`='我等不及要把这张照片寄给我家乡的女朋友了。她肯定会抓狂的！', `MaleText_loc5`='我等不及要把這張照片帶回家給我女兒看。她會嚇死!', `MaleText_loc7`='Estoy deseando mandarle esta foto a mi chica. ¡Va a flipar!' WHERE `ID`=63430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 보자...$B$B"적절한 조리개 값 찾기. 조리개 숫자는 초점 거리를 ''실제'' 조리개 지름으로 나눈 값이다."$B$B이거 정말 머리가 쑤시는군요.', `MaleText_loc4`='让我们瞧瞧这里……$B$B“找到合适的光圈值。光圈值等于焦距除以‘有效光圈孔径’。”$B$B这可真让我头疼。', `MaleText_loc5`='讓我看看...$b$b「找出合適的光圈。焦距除以『有效的』光圈直徑就是光圈的數字。」$B$B這些字讓我的頭好痛。', `MaleText_loc7`='Vamos a ver...$B$B"Buscar el número f adecuado. El número f es la longitud de foco dividida por el diámetro de apertura efectiva".$B$BEsto me da dolor de cabeza.', `FemaleText_loc1`='어디 보자...$B$B"적절한 조리개 값 찾기. 조리개 숫자는 초점 거리를 ''실제'' 조리개 지름으로 나눈 값이다."$B$B이거 정말 머리가 쑤시네요.', `FemaleText_loc4`='让我们瞧瞧这里……$B$B“找到合适的光圈值。光圈值等于焦距除以‘有效光圈孔径’。”$B$B这可真让我头疼。', `FemaleText_loc5`='讓我看看...$b$b「找出合適的光圈。焦距除以『有效的』光圈直徑就是光圈的數字。」$B$B這些字讓我的頭好痛。', `FemaleText_loc7`='Vamos a ver...$B$B"Buscar el número f adecuado. El número f es la longitud de foco dividida por el diámetro de apertura efectiva".$B$BEsto me da dolor de cabeza.' WHERE `ID`=63431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작년에 돈을 조금 번 덕분에 새 카메라를 우편으로 주문할 수 있었습니다!', `MaleText_loc4`='幸亏我们上一季发了笔小财，我才能邮购到这台新式相机！', `MaleText_loc5`='感謝我們上一季賺進的一小筆財富，我終於能郵購這台奇特的新相機了!', `MaleText_loc7`='Gracias a la pequeña fortuna que ganamos la temporada pasada, pude comprar por correo esta bonita cámara nueva.', `FemaleText_loc1`='작년에 돈을 조금 번 덕분에 새 카메라를 우편으로 주문할 수 있었답니다!', `FemaleText_loc4`='幸亏我们上一季发了笔小财，我才能邮购到这台新式相机！', `FemaleText_loc5`='感謝我們上一季賺進的一小筆財富，我終於能郵購這台奇特的新相機了!', `FemaleText_loc7`='Gracias a la pequeña fortuna que ganamos la temporada pasada, pude comprar por correo esta bonita cámara nueva.' WHERE `ID`=63432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 지금 사진 찍는 데 정말 집중하고 있습니다.', `MaleText_loc4`='我现在正在潜心提高自己的摄影技术。', `MaleText_loc5`='我現在真的很專注於攝影。', `MaleText_loc7`='Me estoy concentrando mucho en la fotografía.', `FemaleText_loc1`='전 지금 사진 찍는 데 정말 집중하고 있어요.', `FemaleText_loc4`='我现在正在潜心提高自己的摄影技术。', `FemaleText_loc5`='我現在真的很專注於攝影。', `FemaleText_loc7`='Me estoy concentrando mucho en la fotografía.' WHERE `ID`=63433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 좀 찍어주지 않겠나? 팔에 힘이 빠지고 있다네!', `MaleText_loc4`='你能快点儿吗？我手臂都酸了！', `MaleText_loc5`='你能不能快點?我的手好酸!', `MaleText_loc7`='¿Quieres darte prisa? ¡Se me cansan los brazos!', `FemaleText_loc1`='빨리 좀 찍어주실래요? 팔에 힘이 빠지고 있단 말이에요!', `FemaleText_loc4`='你能快点儿吗？我手臂都酸了！', `FemaleText_loc5`='你能不能快點?我的手好酸!', `FemaleText_loc7`='¿Quieres darte prisa? ¡Se me cansan los brazos!' WHERE `ID`=63434;
