UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다리십시오! 원래 예술 작품은 시간이 좀 걸리잖습니까!', `MaleText_loc4`='再等一秒！艺术是催不出来的！', `MaleText_loc5`='再一下下!藝術是急不得的!', `MaleText_loc7`='¡Un segundo! ¡No se puede hacer arte con prisas!', `FemaleText_loc1`='잠깐만 기다리세요! 원래 예술 작품은 시간이 좀 걸리잖아요!', `FemaleText_loc4`='再等一秒！艺术是催不出来的！', `FemaleText_loc5`='再一下下!藝術是急不得的!', `FemaleText_loc7`='¡Un segundo! ¡No se puede hacer arte con prisas!' WHERE `ID`=63436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"...최단거리에서 초점을 잡으면, 현재 거리의 절반 거리에서부터 무한대 거리까지 쭉 최대의 선예도를 얻는다..."', `MaleText_loc4`='“……调焦至超焦距可确保取得从该距离的一半至无限距离的最大清晰度……”', `MaleText_loc5`='......在超過焦距的距離對焦，能確保從這個距離的一半到無窮遠的地方，都能有最大的清晰度...', `MaleText_loc7`='"...enfocar a la distancia hiperfocal asegura la máxima nitidez desde la mitad de la distancia hasta el infinito..."', `FemaleText_loc1`='"...최단거리에서 초점을 잡으면, 현재 거리의 절반 거리에서부터 무한대 거리까지 쭉 최대의 선예도를 얻는다..."', `FemaleText_loc4`='“……调焦至超焦距可确保取得从该距离的一半至无限距离的最大清晰度……”', `FemaleText_loc5`='......在超過焦距的距離對焦，能確保從這個距離的一半到無窮遠的地方，都能有最大的清晰度...', `FemaleText_loc7`='"...enfocar a la distancia hiperfocal asegura la máxima nitidez desde la mitad de la distancia hasta el infinito..."' WHERE `ID`=63437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 이게 지금 자네가 말하는 최단거리라는 건가?', `MaleText_loc4`='嘿，那你觉得你现在的“超焦距”是什么？', `MaleText_loc5`='嘿，現在你覺得你的「超過焦距的距離」是什麼東西?', `MaleText_loc7`='Oye, ¿cuál crees que será ahora mismo tu "distancia hiperfocal"?', `FemaleText_loc1`='이봐요, 이게 지금 당신이 말하는 최단거리라는 건가요?', `FemaleText_loc4`='嘿，那你觉得你现在的“超焦距”是什么？', `FemaleText_loc5`='嘿，現在你覺得你的「超過焦距的距離」是什麼東西?', `FemaleText_loc7`='Oye, ¿cuál crees que será ahora mismo tu "distancia hiperfocal"?' WHERE `ID`=63438;
