UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 저렇게 꿈지럭대는 거야?', `MaleText_loc4`='他在那边干什么呢？', `MaleText_loc5`='他在那裏做什麼?', `MaleText_loc7`='¿Qué está haciendo ahí?', `FemaleText_loc1`='뭘 저렇게 꿈지럭대는 거지?', `FemaleText_loc4`='他在那边干什么呢？', `FemaleText_loc5`='他在那裏做什麼?', `FemaleText_loc7`='¿Qué está haciendo ahí?' WHERE `ID`=63458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밖에 있는 멍청이 둘은 신경 쓰지 말게나. "상어 사진 찍기"라는 유행에 빠진 친구들이니까.$B$B그 친구들이 몇 달만 지나면 참 멍청해 보이는 사진이라고 느끼는 데 돈을 걸지.', `MaleText_loc4`='别理外面那两个白痴——他们患上“鲨鱼狂热综合症”了。$B$B我敢打赌，他们对那照片的新鲜劲持续不了几个月。', `MaleText_loc5`='別在意外頭那兩個蠢蛋，他們正著迷於某種被稱為「玩鯊」的新風潮裡。$B$B我敢打賭，過兩個月他們就會覺得那些照片看起來很蠢。', `MaleText_loc7`='No hagas caso a esos dos idiotas de fuera. Están siguiendo una moda llamada "tiburonear".$B$BApuesto que dentro de un par de meses les dará vergüenza ver esa foto.' WHERE `ID`=63459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끝내줄 걸세!', `MaleText_loc4`='这简直酷毙了！', `MaleText_loc5`='這會超級經典的!', `MaleText_loc7`='¡Esto va a ser la monda!' WHERE `ID`=63460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 제때에 와 줬구나. 내가 잠든 동안 여제의 수하들이 나를 파괴할 뻔했다.', `MaleText_loc4`='你来得正是时候，唤醒者。副官想趁我熟睡时消灭我。', `MaleText_loc5`='你來的時間剛剛好，喚醒者。隨從可能會在我沉眠時毀了我。', `MaleText_loc7`='Has llegado justo a tiempo, heraldo. Los adjuntos me habrían matado mientras dormía.' WHERE `ID`=63461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 꿈속에서조차도 그들의 사악한 생각을 들을 수 있었다... 여제의 사악한 생각 말이다.', `MaleText_loc4`='哪怕是在睡梦中，我都能听见他们的黑暗思想……她的黑暗思想。', `MaleText_loc5`='即使在夢中，我都能聽見他們黑暗的思想...「她」黑暗的思想。', `MaleText_loc7`='Hasta en sueños podía escuchar sus pensamientos oscuros... los de ellos, y los de ELLA.' WHERE `ID`=63462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 상어 옆에서 사진을 찍을 수 있을 걸세. 순서를 기다리게나!', `MaleText_loc4`='再等一分钟鲨鱼就给你用，还没轮到你呢！', `MaleText_loc5`='你馬上就可以使用鯊魚了，等會就輪到你!', `MaleText_loc7`='¡Podrás usar el tiburón en un minuto, espera tu turno!' WHERE `ID`=63463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기구를 타지요. 따라오십시오!', `MaleText_loc4`='我们可以用气球。跟我来！', `MaleText_loc5`='我們可以用氣球。跟我來!', `MaleText_loc7`='Podemos usar el globo. ¡Sígueme!' WHERE `ID`=63464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제는 자신의 실패 원인을 두려워한다. 하지만 그 두려움 자체 탓에 그녀가 실패한 것이다. 그녀는 이미 광기의 경계를 넘어섰다..', `MaleText_loc4`='女皇惧怕自己的灭亡，而惧怕本身就会为她招致灭亡。她已经超出了疯狂的底线。', `MaleText_loc5`='女皇恐懼自身的毀滅，然而恐懼本身就是她毀滅的原因。她已深深陷入瘋狂了。', `MaleText_loc7`='La Emperatriz teme su perdición, pero su perdición es el miedo mismo. Ha caído en el abismo de la locura.' WHERE `ID`=63465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제국이 저지른 범죄 행위에 내릴 처벌이 아주 많다. 깨우는 자여, 허비할 시간이 없다. 밖에서 나와 만나자.', `MaleText_loc4`='我们要严惩女皇犯下的重罪。别浪费时间了，唤醒者。到外面找我。', `MaleText_loc5`='帝國犯下太多需要懲罰的罪行。我們沒有時間浪費了，喚醒者。到外面跟我碰頭。', `MaleText_loc7`='Hay muchos crímenes del imperio pendientes de castigo. No tenemos tiempo que perder, heraldo. Reúnete conmigo fuera.' WHERE `ID`=63466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 장로님. 실망을 안기지 않겠습니다.', `MaleText_loc4`='长者，谢谢你们。我们一定不负所望。', `MaleText_loc5`='謝謝長老。你們不會失望的。', `MaleText_loc7`='Gracias, ancestros. No los decepcionaremos.' WHERE `ID`=63467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 관상을 보아하니 돈이 좀 되겠는데, 파멸의 투기장에서 한판 해 보는 게 어때?', `MaleText_loc4`='你似乎能帮我们赚点钱。$B$B来破军比武场转转怎么样，伙计？', `MaleText_loc5`='你看起來可以幫我們賺些錢。$B$B有沒有考慮來苦痛露天競技場打一場，夥伴?', `MaleText_loc7`='Parece que podrías hacernos ganar algo de dinero.$b$b¿Qué tal una vuelta por la Arena de la Aniquilación, colega?' WHERE `ID`=63468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 뼈와 살을 분리해라!', `MaleText_loc4`='把他们的血肉从骨头上剥下来！', `MaleText_loc5`='把他們生吞活剝!', `MaleText_loc7`='¡Arránquenles la carne de los huesos!' WHERE `ID`=63469;
