UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $r님. 전승지기 초 님이 당신에 대해 전부 말씀해 주셨어요. 아, 뭐, 적어도 중요한 이야기는 전부 하신 셈이죠. 그래도 여기 주민들은 아직 낯을 가릴지 모르니, 먼저 다른 이들과 친해지시는 게 좋을 거예요.', `MaleText_loc4`='嘿，你好啊，$r。游学者周卓把你的事都告诉我了，至少是重要的部分。可这附近的人对你还不太了解，所以你最好先赢得他们的好感。', `MaleText_loc5`='你好啊，$r。博學行者阿洲跟我說過好多好多關於你的事。至少都是一些重要的部分。這附近的傢伙們對你可能還有些疑慮，所以你或許會想先在他們面前表現出好的一面。', `MaleText_loc7`='Hola, $r. El eremita Cho me ha contado toooodo de ti. O al menos lo más importante. La gente de por aquí puede que tenga algunas dudas con respecto a ti, así que yo que tú intentaría caerles bien.' WHERE `ID`=63481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 이방인인가? 자네들도 맛있는 맥주를 좋아하나? 그렇다면, 여기 골든드래프트 특제 맥주를 한번 맛보게!', `MaleText_loc4`='又来了个陌生人？你爱品酒吗？要是你有兴趣，不妨尝尝金酿特饮！', `MaleText_loc5`='又一個陌生人?你們這類人喜歡好喝的啤酒嗎?如果喜歡，那就試試金流特藏佳釀!', `MaleText_loc7`='¿$gOtro forastero:Otra forastera;? ¿A los tuyos les va la cerveza? ¡Si es así, prueba una de la reserva de Brisa Dorada!' WHERE `ID`=63482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이방인이시여, 당신은 호젠처럼 야만적이고 열정적인 편입니까?$b$b아니면 진위처럼 조용하고 사려 깊은 편입니까?', `MaleText_loc4`='那么，陌生人，你是狂野疯狂如猢狲呢？$b$b还是安静深沉如锦鱼人？', `MaleText_loc5`='嗯，陌生人，你是像猴人那種狂野又瘋狂的類型嗎?$b$b還是像錦魚人那種沉默又好沉思的類型?', `MaleText_loc7`='Entonces, $gforastero:forastera;, ¿eres salvaje y $gloco:loca; como los hozen?$b$b¿O $gtranquilo:tranquila; y $greflexivo:reflexiva; como los jinyu?', `FemaleText_loc1`='자, 이방인이시여, 당신은 호젠처럼 야만적이고 열정적인 편인가요?$b$b아니면 진위처럼 조용하고 사려 깊은 편인가요?', `FemaleText_loc4`='那么，陌生人，你是狂野疯狂如猢狲呢？$b$b还是安静深沉如锦鱼人？', `FemaleText_loc5`='嗯，陌生人，你是像猴人那種狂野又瘋狂的類型嗎?$b$b還是像錦魚人那種沉默又好沉思的類型?', `FemaleText_loc7`='Entonces, $gforastero:forastera;, ¿eres salvaje y $gloco:loca; como los hozen?$b$b¿O $gtranquilo:tranquila; y $greflexivo:reflexiva; como los jinyu?' WHERE `ID`=63483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽 너머에서 오셨습니까?', `MaleText_loc4`='你是来自长城的另一边吗？', `MaleText_loc5`='你是從牆的另一邊來的嗎?', `MaleText_loc7`='¿Vienes de más allá de la muralla?', `FemaleText_loc1`='장벽 너머에서 오셨나요?', `FemaleText_loc4`='你是来自长城的另一边吗？', `FemaleText_loc5`='你是從牆的另一邊來的嗎?', `FemaleText_loc7`='¿Vienes de más allá de la muralla?' WHERE `ID`=63484;
