UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 저기... 음... 어... 제가 생각했던 것과는 무척 다른 모습이시군요. 당신 같은 이가 또 있습니까?', `MaleText_loc4`='哇哦，你看起来……嗯……那个……跟我想的不太一样。你还有同类吗？', `MaleText_loc5`='哇喔。你看起來...嗯...啊...跟我期待的不一樣。那裡有更多像你一樣的人嗎?', `MaleText_loc7`='Guau. Tienes un aspecto... Eh... Algo distinto de lo que me esperaba. ¿Hay más como tú?', `FemaleText_loc1`='우와, 저기... 음... 어... 제가 생각했던 것과는 무척 다른 모습이시네요. 당신 같은 이가 또 있나요?', `FemaleText_loc4`='哇哦，你看起来……嗯……那个……跟我想的不太一样。你还有同类吗？', `FemaleText_loc5`='哇喔。你看起來...嗯...啊...跟我期待的不一樣。那裡有更多像你一樣的人嗎?', `FemaleText_loc7`='Guau. Tienes un aspecto... Eh... Algo distinto de lo que me esperaba. ¿Hay más como tú?' WHERE `ID`=63486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옷 색깔이 아주 독특하군요. 직접 만든 옷입니까?', `MaleText_loc4`='你衣服的颜色真有趣啊。是你自己做的吗？', `MaleText_loc5`='你穿的是啥奇怪的顏色啊。你自己織的嗎?', `MaleText_loc7`='Vistes con unos colores interesantes. ¿Lo has tejido tú $gsolo:sola;?', `FemaleText_loc1`='옷 색깔이 아주 독특하군요. 직접 만든 옷인가요?', `FemaleText_loc4`='你衣服的颜色真有趣啊。是你自己做的吗？', `FemaleText_loc5`='你穿的是啥奇怪的顏色啊。你自己織的嗎?', `FemaleText_loc7`='Vistes con unos colores interesantes. ¿Lo has tejido tú $gsolo:sola;?' WHERE `ID`=63487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 같은 이들이 또 있습니까?', `MaleText_loc4`='你还有同类吗？', `MaleText_loc5`='那裡有更多像你這樣的人嗎?', `MaleText_loc7`='¿Hay más como tú?', `FemaleText_loc1`='당신과 같은 이들이 또 있나요?', `FemaleText_loc4`='你还有同类吗？', `FemaleText_loc5`='那裡有更多像你這樣的人嗎?', `FemaleText_loc7`='¿Hay más como tú?' WHERE `ID`=63488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 안녕하십니까. 당신 모습을 보니, 많은 이야기를 품고 계실 것 같습니다.', `MaleText_loc4`='噢，你好啊陌生人。你看上去像是个经历丰富的家伙。', `MaleText_loc5`='喔，你好啊陌生人。你的模樣看起來好像有很多故事可以分享。', `MaleText_loc7`='Ey, hola $gforastero:forastera;. Tienes pinta de ser una criatura con muchas historias que contar.', `FemaleText_loc1`='아, 안녕하세요. 당신 모습을 보니, 많은 이야기를 품고 계실 것 같네요.', `FemaleText_loc4`='噢，你好啊陌生人。你看上去像是个经历丰富的家伙。', `FemaleText_loc5`='喔，你好啊陌生人。你的模樣看起來好像有很多故事可以分享。', `FemaleText_loc7`='Ey, hola $gforastero:forastera;. Tienes pinta de ser una criatura con muchas historias que contar.' WHERE `ID`=63489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='턱선이 무척 독특하시군요. 피부색도... 어디 출신이십니까?', `MaleText_loc4`='你下巴的轮廓真迷人。衣着又如此鲜艳。你是打哪儿来的？', `MaleText_loc5`='你的下巴真是迷人。而且這麼的自然。你從哪裡來的?', `MaleText_loc7`='Tienes un perfil de mandíbula fascinante. Y qué colores. ¿De dónde vienes?', `FemaleText_loc1`='턱선이 무척 독특하시네요. 피부색도... 어디 출신이신가요?', `FemaleText_loc4`='你下巴的轮廓真迷人。衣着又如此鲜艳。你是打哪儿来的？', `FemaleText_loc5`='你的下巴真是迷人。而且這麼的自然。你從哪裡來的?', `FemaleText_loc7`='Tienes un acento extraño. ¿Vienes del Valle de los Cuatro Vientos?' WHERE `ID`=63490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 이런 방어구가 있었나...', `MaleText_loc4`='嗯。什么护甲……', `MaleText_loc5`='唔。這什麼盔甲...', `MaleText_loc7`='Mmm... Qué armadura...' WHERE `ID`=63491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인인가? 이런, 저걸 봐. 어디서 가져온 건지 정말 궁금한걸.', `MaleText_loc4`='有个陌生人？快瞧瞧。我很好奇他是从哪儿来的。', `MaleText_loc5`='陌生人?唉呀看哪。不知道它是從哪裡來的。', `MaleText_loc7`='¿Un $gforastero:forastera;? Fíjate. Me pregunto de dónde viene.', `FemaleText_loc1`='이방인인가요? 이런, 저걸 보세요. 어디서 가져온 건지 정말 궁금하네요.', `FemaleText_loc4`='有个陌生人？快瞧瞧。我很好奇他是从哪儿来的。', `FemaleText_loc5`='陌生人?唉呀看哪。不知道它是從哪裡來的。', `FemaleText_loc7`='¿Un $gforastero:forastera;? Fíjate. Me pregunto de dónde viene.' WHERE `ID`=63492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무척 기이하고 흥미로운 생물이로군. 평화적인 목적으로 내 마을에 찾아온 건가?', `MaleText_loc4`='真是个陌生又古怪的生物。你是带着和平的意图到我村子里来的吗？', `MaleText_loc5`='真是個稀奇又古怪的生物。你來到我鎮上是基於善意的嗎?', `MaleText_loc7`='Qué criatura tan extraña y curiosa. ¿Vienes a mi ciudad con intenciones pacíficas?' WHERE `ID`=63493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 오신 분입니까? 무척... 이상한 모습이군요.', `MaleText_loc4`='又一个陌生人？还长得……那么奇怪。', `MaleText_loc5`='又是個陌生人?而且...長得好奇怪。', `MaleText_loc7`='¿$GOtro:Otra; $gforastero:forastera;? Y... con unas pintas de lo más extrañas.' WHERE `ID`=63494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 불쌍하게도 이렇게 말랐다니... 아무래도 굶주린 것 같군요.', `MaleText_loc4`='可怜的小东西。骨瘦如柴……一定饿坏了。', `MaleText_loc5`='那可憐的生物。它好瘦...它一定餓壞了。', `MaleText_loc7`='Pobre criatura. Tiene tal delgadez... Debe estar muriéndose de hambre.' WHERE `ID`=63495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초 님이 말씀하셨던 그 이방인이로군요. 다른 이들이 또 있나 궁금합니다.', `MaleText_loc4`='这就是周卓提到的那位陌生人。不知是否就他一个。', `MaleText_loc5`='這就是阿洲提到的那個陌生人。我很好奇會不會有更多陌生人來。', `MaleText_loc7`='Es $gel:la; $gforastero:forastera; que mencionó Cho. Me pregunto si habrá más.' WHERE `ID`=63496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 오게, 이방인. 이곳을 지나가는 여행객을 본 것도 정말 오랜만이군.', `MaleText_loc4`='欢迎你，陌生人。我好久没见到新面孔途径此地了。', `MaleText_loc5`='歡迎你，陌生人。我已經有很久很久沒見到新的旅行者來到這裡了。', `MaleText_loc7`='$GBienvenido:Bienvenida; $gforastero:forastera;. Hace ya mucho tiempo que no veía a alguien nuevo viajando por la zona.' WHERE `ID`=63497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 어디서 온 건가? 격조 높은 술이 없는 곳이겠지? 안 그런가?', `MaleText_loc4`='能告诉我你来自哪里吗？某个美酒欠奉的地方？嗯？', `MaleText_loc5`='我很好奇你是從哪兒來的?', `MaleText_loc7`='Lo que me pregunto es... ¿De dónde vienes? ¿De algún lugar en el que falta bebida de calidad? ¿Eh?' WHERE `ID`=63498;
