UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초 님은 당신 같은 분이 "이인가안"이라고 하시던데... 호젠이랑 비슷한 건가요?', `MaleText_loc4`='周卓说你是个“人类”。那是什么，跟猢狲一样吗？', `MaleText_loc5`='阿洲說你是個「猴類」。那是猴人的一種嗎?', `MaleText_loc7`='"Cho dijo que eres un "umano". ¿Es como un hozen?', `FemaleText_loc1`='초 님은 당신 같은 분이 "이인가안"이라고 하시던데... 호젠이랑 비슷한 거예요?', `FemaleText_loc4`='周卓说你是个“人类”。那是什么，跟猢狲一样吗？', `FemaleText_loc5`='阿洲說你是個「猴類」。那是猴人的一種嗎?', `FemaleText_loc7`='"Cho dijo que eres un "umano". ¿Es como un hozen?' WHERE `ID`=63535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그렇게 마르셨어요?', `MaleText_loc4`='你怎么那么瘦啊？', `MaleText_loc5`='為什麼你這麼瘦?', `MaleText_loc7`='¿Por qué estás tan $gdelgado:delgada;?', `FemaleText_loc1`='어떻게 그렇게 날씬하세요?', `FemaleText_loc4`='你怎么那么瘦啊？', `FemaleText_loc5`='為什麼你這麼瘦?', `FemaleText_loc7`='¿Por qué estás tan $gdelgado:delgada;?' WHERE `ID`=63536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 몸이 초록색이세요?', `MaleText_loc4`='你怎么绿乎乎的？', `MaleText_loc5`='為什麼你這麼綠?', `MaleText_loc7`='¿Por qué eres tan verde?', `FemaleText_loc1`='왜 얼굴이 초록색이세요?', `FemaleText_loc4`='你怎么绿乎乎的？', `FemaleText_loc5`='為什麼你這麼綠?', `FemaleText_loc7`='¿Por qué eres tan verde?' WHERE `ID`=63537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그렇게 항상 으르렁거리세요?', `MaleText_loc4`='你干嘛要发出好多愤怒的声音？', `MaleText_loc5`='為什麼你一直發出憤怒的聲音?', `MaleText_loc7`='¿Por qué haces tantos sonidos de enfado?', `FemaleText_loc1`='왜 그렇게 화난 소리를 내세요?', `FemaleText_loc4`='你干嘛要发出好多愤怒的声音？', `FemaleText_loc5`='為什麼你一直發出憤怒的聲音?', `FemaleText_loc7`='¿Por qué haces tantos sonidos de enfado?' WHERE `ID`=63538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품을 옮겨라!', `MaleText_loc4`='移走那些补给品！', `MaleText_loc5`='把這些補給品搬走!', `MaleText_loc7`='¡Moved esos suministros!' WHERE `ID`=63539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 이곳은 새벽의 꽃이네! 비취 숲에 피어난 판다렌 문화의 꽃이지. 이곳 사람들에게 좋은 인상을 남기고 싶나? 많은 주민들이 자네 도움을 필요로 할 걸세.', `MaleText_loc4`='朋友，这里是晨芳园！熊猫人在翡翠林的生活中心。要是你想给人留下深刻的印象，相信这里有很多居民在等你帮忙。', `MaleText_loc5`='朋友，這裡是晨綻，熊貓人在翠玉林的生活中心。如果你有心製造好印象，我很肯定這裡有許多市民都需要你的協助。', `MaleText_loc7`='¡Esto es Floralba! Es el corazón de la vida pandaren en El Bosque de Jade. Si quieres causar buena impresión, estoy seguro de que muchos ciudadanos necesitan tu ayuda.' WHERE `ID`=63540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금 잠시 떠나야겠네. 토야가 나를 위해 비취를 모으고 있네. 일을 마치면 자네가 그 비취를 갖고 황제의 예언으로 찾아와 주게. 그러면 역사가 우리에게 감춰 두었던 비밀을 볼 수 있을지도 모르니까.', `MaleText_loc4`='我先失陪了。托亚正在帮我搜集玉石。等他集齐之后，希望你能帮忙带到皇帝的预言地来交给我，那样我们也许就能知道，历史究竟对我们隐藏了什么秘密。', `MaleText_loc5`='我必須暫時離開你。托亞正在為我的計畫蒐集玉。等他完成工作，我希望你把玉帶來帝王之兆給我，這樣我們或許能挖掘出隱藏在歷史中的秘密。', `MaleText_loc7`='Ahora debo dejarte. Toya está cogiendo jade para mi proyecto. Cuando termine, me gustaría que me lo trajeses al Augurio del Emperador, para así intentar descubrir los secretos que nos ha guardado la historia.' WHERE `ID`=63541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 딱 맞춰 왔군. 난 지금 막 떠나려던 참이네. 자네는 부디 이곳에 남아서, 토야가 비취를 모으는 동안 마을을 둘러보게.', `MaleText_loc4`='你来得可真是时候。我正准备离开。但请你留下逛逛村庄，托亚正在搜集我们需要的玉石。', `MaleText_loc5`='你來的正好。我正要離開。但當托亞去取我們需要的玉時，請你務必留下來享受小鎮風光。', `MaleText_loc7`='Llegas justo a tiempo. Estaba a punto de irme. Por favor, quédate y disfruta de la ciudad mientras Toya reúne el jade que necesitamos.' WHERE `ID`=63542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 만나요!', `MaleText_loc4`='回头见！', `MaleText_loc5`='晚點見!', `MaleText_loc7`='¡Hasta luego!', `FemaleText_loc1`='다음에 또 만나요!', `FemaleText_loc4`='回头见！', `FemaleText_loc5`='晚點見!', `FemaleText_loc7`='¡Hasta luego!' WHERE `ID`=63543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 갈게요!', `MaleText_loc4`='再见！', `MaleText_loc5`='再見!', `MaleText_loc7`='¡Adiós!', `FemaleText_loc1`='잘 가세요!', `FemaleText_loc4`='再见！', `FemaleText_loc5`='再見!', `FemaleText_loc7`='¡Adiós!' WHERE `ID`=63544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 놀러 갈래요.', `MaleText_loc4`='我要去玩了。', `MaleText_loc5`='我要去玩了。', `MaleText_loc7`='Me voy a jugar.', `FemaleText_loc1`='전 놀러 갈게요.', `FemaleText_loc4`='我要去玩了。', `FemaleText_loc5`='我要去玩了。', `FemaleText_loc7`='Me voy a jugar.' WHERE `ID`=63545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전갈은 조심조심 다루시오. 순해 보이지만 싸울 때는 괴물이 되거든!', `MaleText_loc4`='小心那蝎子，他看起来也许很友善，可真打起来简直是头野兽！', `MaleText_loc5`='小心蠍子，他看起來或許很友善，但在戰場上他可是隻野獸!', `MaleText_loc7`='Cuidado con el escorpión; puede que parezca amistoso, ¡pero es una bestia en la batalla!', `FemaleText_loc1`='전갈은 조심조심 다루세요. 순해 보이지만 싸울 때는 괴물이 되거든요!', `FemaleText_loc4`='小心那蝎子，他看起来也许很友善，可真打起来简直是头野兽！', `FemaleText_loc5`='小心蠍子，他看起來或許很友善，但在戰場上他可是隻野獸!', `FemaleText_loc7`='Cuidado con el escorpión; puede que parezca amistoso, ¡pero es una bestia en la batalla!' WHERE `ID`=63546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 내 고양이를 넘보는 건가?', `MaleText_loc4`='你在看我的猫？', `MaleText_loc5`='你在瞧我的貓嗎?', `MaleText_loc7`='¿Estás mirando a mi gato?', `FemaleText_loc1`='지금 제 고양이를 넘보는 건가요?', `FemaleText_loc4`='你在看我的猫？', `FemaleText_loc5`='你在瞧我的貓嗎?', `FemaleText_loc7`='¿Estás mirando a mi gato?' WHERE `ID`=63547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 강태공님! 이 근처에는 오래 계셨나요? 저는 여기 이 친구 "대어잡이"와 함께 대어를 찾아 세상을 떠돌지요!$b$b어쩌다가 이곳을 발견했는데, 주민들이 물자와 술을 아낌없이 내 주길래 그냥 눌러앉기로 했습니다!', `MaleText_loc4`='你好啊，钓友！你来这里多久了？我和我的搭档“大钩”山南海北地到处寻找大鱼！$b$b我们偶然来到这里，当地人十分友好，又是给补给品，又是好酒好菜地招待，所以我们打算留下来啦！', `MaleText_loc5`='哈囉，釣手同志!你在這邊待得久嗎?我和我這位夥伴「大魚鉤」在四處旅行，尋找另一次吊上大魚的機會!$b$b我們偶然來到這裡地方，發現當地人很友善，又有美味的酒，所以我們決定留下來不走啦!', `MaleText_loc7`='¡Hola, $gcompañero:compañera; $gpescador:pescadora;! ¿Llevas mucho tiempo por esta zona? Mi amigo "Gran Anzuelo" y yo llevamos viajando mucho tiempo en busca de la siguiente gran captura!$b$bEncontramos este lugar por accidente, y como la gente de aquí se portó con los suministros y la bebida, decidimos quedarnos algo más.' WHERE `ID`=63548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강태공 일을 돕고 있습니까? 보상을 구경하시지요!', `MaleText_loc4`='一直在为钓鱼者效劳？这些奖励是给你的！', `MaleText_loc5`='和釣手隊一起工作嗎?看看這些戰利品!', `MaleText_loc7`='¿Has estado trabajando para los pescadores? ¡Echa un vistazo a estas recompensas!' WHERE `ID`=63549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기에 있는 모구샨 궁전은 87에서 89 레벨의 플레이어가 공략할 수 있는 던전으로 지금 시험해볼 수 있습니다. 던전 안으로 순간이동하기 전에 파티를 맺은 상태여야 합니다. 만남의 돌은 아직 사용할 수 없습니다.

모구샨 궁전에서 나오려면, 던전 안에 있는 입구로 빠져나오면 됩니다. 그러면 바로 달라란으로 이동하게 되지요. 죽어서 영혼이 빠져나갔다면 다시 NPC와 대화하여 순간이동해야 합니다.', `MaleText_loc4`='位于锦绣谷的魔古山宫殿已开放测试。该地下城适合87至89级的玩家。请组满队伍后再传送至地下城。该地下城的集合石尚未开放。

穿过地下城内的常规出口，即可离开魔古山宫殿并被传送回达拉然。如果角色死亡并选择释放灵魂，请从该NPC处传送回去。', `MaleText_loc5`='位於恆春谷的87-89級地城，魔古山宮，現在已可進行測試。本地城的集合石功能尚未建構完成，因此請先組好完整隊伍再傳送進地城。

如要離開魔古山宮，請從地城內正常的出口離開，你就會被傳送到達拉然。倘若不幸死亡並已釋放靈魂，你應當經由這位NPC來傳送回去。', `MaleText_loc7`='El Palacio Mogu''shan, una mazmorra de nivel 87-89 en el Valle de la Flor Eterna, ya está disponible para pruebas. Antes de teletransportarte a la mazmorra, asegúrate de que el grupo está formado. Las rocas de encuentro para esta mazmorra todavía no están disponibles.

Para abandonar el Palacio Mogu''shan, simplemente sal por la salida normal dentro de la mazmorra y serás teletransportado a Dalaran. Si mueres y liberas espíritu, puedes teletransportarte de nuevo con este PNJ.' WHERE `ID`=63550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0404|Hspell:119311|h[칼날 빗발]|h|r 함정을 활성화합니다!', `MaleText_loc4`='%s激活了他的|cFFFF0404|Hspell:119311|h[利刃之流]|h|r陷阱！', `MaleText_loc5`='%s啟動他的|cFFFF0404|Hspell:119311|h[刃流術]|h|r陷阱!', `MaleText_loc7`='¡%s activa su trampa de |cFFFF0404|Hspell:119311|h[Corriente de filos]|h|r!' WHERE `ID`=63551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 파티원 모두 준비되었습니다. 모구샨 궁전으로 순간이동시켜 주십시오!', `MaleText_loc4`='我已组好队伍，准备好被传送到魔古山宫殿了！', `MaleText_loc5`='我已經在我的隊伍裡，準備好可以傳送到魔古山宮了!', `MaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme al Palacio Mogu''shan!', `FemaleText_loc1`='저와 파티원 모두 준비되었습니다. 모구샨 궁전으로 순간이동시켜 주십시오!', `FemaleText_loc4`='我已组好队伍，准备好被传送到魔古山宫殿了！', `FemaleText_loc5`='我已經在我的隊伍裡，準備好可以傳送到魔古山宮了!', `FemaleText_loc7`='¡Estoy con mi grupo y quiero teletransportarme al Palacio Mogu''shan!' WHERE `ID`=63552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 모구샨 궁전으로 다시 보내 주십시오!', `MaleText_loc4`='送我回魔古山宫殿！', `MaleText_loc5`='將我帶回魔古山宮!', `MaleText_loc7`='¡Llévame de vuelta al Palacio Mogu''shan!', `FemaleText_loc1`='절 모구샨 궁전으로 다시 보내 주십시오!', `FemaleText_loc4`='送我回魔古山宫殿！', `FemaleText_loc5`='將我帶回魔古山宮!', `FemaleText_loc7`='¡Llévame de vuelta al Palacio Mogu''shan!' WHERE `ID`=63553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0404|Hspell:120142|h[석궁]|h|r 함정을 활성화합니다!', `MaleText_loc4`='%s激活了他的|cFFFF0404|Hspell:120142|h[战弩]|h|r陷阱！', `MaleText_loc5`='%s啟動他的|cFFFF0404|Hspell:120142|h[弩]|h|r陷阱!', `MaleText_loc7`='¡%s activa su trampa de |cFFFF0404|Hspell:120142|h[Ballesta]|h|r!' WHERE `ID`=63554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0404|Hspell:119374|h[소용돌이치는 도끼]|h|r 함정을 활성화합니다!', `MaleText_loc4`='%s激活了他的|cFFFF0404|Hspell:119374|h[旋风斧]|h|r陷阱！', `MaleText_loc5`='%s啟動他的|cFFFF0404|Hspell:119374|h[旋風斧]|h|r陷阱!', `MaleText_loc7`='¡%s activa su trampa de |cFFFF0404|Hspell:119374|h[Torbellino de hachas]|h|r!' WHERE `ID`=63555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 부흥할 것이다!', `MaleText_loc4`='我们必将再次崛起！', `MaleText_loc5`='我們將會東山再起!', `MaleText_loc7`='¡Nos alzaremos de nuevo!' WHERE `ID`=63556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구르단 정원으로 데려가주십시오.', `MaleText_loc4`='请带我飞向格尔桑平台。', `MaleText_loc5`='請載我飛到葛薩恩臺地。', `MaleText_loc7`='Por favor, llévame volando hasta el Bancal Gurthan.', `FemaleText_loc1`='구르단 정원으로 데려가주세요.', `FemaleText_loc4`='请带我飞向格尔桑平台。', `FemaleText_loc5`='請載我飛到葛薩恩臺地。', `FemaleText_loc7`='Por favor, llévame volando hasta el Bancal Gurthan.' WHERE `ID`=63557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에 대한 이야기는 나도 들었네. 자네가 변화의 바람을 타고 다닌다고 하더군.', `MaleText_loc4`='我听闻了你旅行的消息。你乘变幻之风而来。', `MaleText_loc5`='我已經聽說你旅行的傳聞。你乘著改變的風而來。', `MaleText_loc7`='Me han llegado noticias sobre tus viajes. Cabalgas sobre los vientos del cambio.' WHERE `ID`=63558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 궁금하군. 자네 고향에는, 평화로운 시절이라는 게 있기는 한가?', `MaleText_loc4`='我很好奇，在你的家乡，有和平可言吗？', `MaleText_loc5`='我很好奇。在你的家鄉，曾經有和平的時刻嗎?', `MaleText_loc7`='Tengo curiosidad... En el lugar del que vienes, ¿alguna vez hay paz?' WHERE `ID`=63559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 우리 땅에서 머문 소감이 어떤가? 배울 만한 게 있었나?', `MaleText_loc4`='你觉得我们的土地怎么样？你学到什么了吗？', `MaleText_loc5`='你喜歡我們這片土地嗎?你有什麼收穫嗎?', `MaleText_loc7`='¿Qué te ha parecido nuestra tierra? ¿Has aprendido algo?' WHERE `ID`=63560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집안에는 대대로 윈드퍼 강타라는 기술이 전해 내려오네.$b$b옛말에 따르면 모구 제국의 지배를 받던 암흑기에 이 기술이 처음 사용되었고, 결국 판다렌에게 자유를 안겨주는 데 기여했다고 하네.', `MaleText_loc4`='打从黑暗时期开始，风裘拳击的武艺就在我的家族里代代相传。$b$b据说这套拳法最早是在魔古帝国的黑暗统治时代被发明的，在熊猫人争取自由的伟业中发挥了不小的作用。', `MaleText_loc5`='風毛拳的技巧從黑暗的時代開始，在我們族中代代相傳。$b$b據說這種拳法的歷史可以回溯到受魔古帝國統治的黑暗時代，並且在為熊貓人爭取自由的戰鬥中盡過一份力。', `MaleText_loc7`='El arte del Puñetazo Pelaje Recio se ha transmitido de generación en generación en mi familia desde los días oscuros.$b$bSe dice que este puñetazo se probó por primera vez durante los días oscuros del imperio mogu, y ayudó a los pandaren a conquistar su libertad.' WHERE `ID`=63561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 마치 한 줄기 돌풍처럼, 폭풍을 몰고 올 것 같군.', `MaleText_loc4`='你的到来，犹如暴风雨来临前的一阵疾风。', `MaleText_loc5`='你的來訪就像暴風雨前的凜風一般。', `MaleText_loc7`='Tu visita es como la racha de viento que precede a la tormenta.' WHERE `ID`=63562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 저 숲에서 호젠에게 사로잡혔지만 살아남았다고 들었네. 앞으로 당분간은 자네와 함께 즐거운 경험을 할 것 같군.$b$b여행자여, 누추하지만 우리 고향에 온 것을 환영하네.', `MaleText_loc4`='我听说你造访了林中的猢狲，并活了下来。看来我们会在今后的日子里发现你身上的特别之处。$b$b欢迎光临寒舍，旅行者。', `MaleText_loc5`='我聽說你在森林猴人那裡作客並活了下來。我想在未來，我們還能在你身上看到更多有趣的事。$b$b歡迎你，旅人，來到我們的家園。', `MaleText_loc7`='Me han dicho que fuiste $gun:una; $ginvitado:invitada; de los hozen del bosque y sobreviviste. Sospecho que veremos cosas interesantes de ti durante los próximos días.$b$bTe doy la bienvenida, $gviajero:viajera;, a nuestra humilde morada.' WHERE `ID`=63563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람에 맞설 때는 부러지는 것보다 굽히는 게 낫지... 무슨 말인지 알겠나?', `MaleText_loc4`='斜风细雨，总好过血风肉雨……明白？我只是开个玩笑。', `MaleText_loc5`='吹歪的風比吹散的好...你有聽懂嗎?我開了個玩笑。', `MaleText_loc7`='El viento es mejor doblado que roto. ...¿Lo pillas? Era un chiste.' WHERE `ID`=63564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 진위가 호젠에 맞서 일어설 수 있는 용기를 준 게 바로 자네였군.$b$b진위가 그렇게 용감한 모습을 보인 것도 정말 오랜만이었지. 누추하지만, 우리 마을에 잘 왔네.', `MaleText_loc4`='原来就是你让锦鱼人重振勇气，对抗猢狲的。$b$b这般勇气我们已经许久未见了。欢迎光临寒舍。', `MaleText_loc5`='看來你就是讓錦魚人們鼓起勇氣，挺身保衛家園不受猴人侵略的那個人了。$b$b我們已經很久沒看到這樣的勇氣了。歡迎你來到我們的家。', `MaleText_loc7`='Así que tú eres la criatura que proporcionó a los jinyu el valor suficiente para resistir contra los hozen.$b$bEso es algo que no vemos desde hace mucho tiempo. Te doy la bienvenida a nuestra humilde morada.' WHERE `ID`=63565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 정말 잘 싸웠네, $p. 명예로운 칭호를 받을 자격이 충분하네.', `MaleText_loc4`='你今天战斗得很是英勇，$p。愿你能不辱威名。', `MaleText_loc5`='你今天在戰鬥中表現得很好，$p。希望你以自己為傲。', `MaleText_loc7`='Hoy has luchado bien, $p. Espero que luzcas con honor tu título.' WHERE `ID`=63566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:107140|h[자기력 장막]|h|r을 시전합니다. 한데 뭉쳐 치유의 힘을 분출시키십시오!', `MaleText_loc4`='%s施放了|cFFFF0000|Hspell:107140|h[磁力帷幕]|h|r。 集合以释放治疗能量！', `MaleText_loc5`='%s施放|cFFFF0000|Hspell:107140|h[磁能障蔽]|h|r。聚集在一起來釋放出治癒的能量!', `MaleText_loc7`='%s lanza |cFFFF0000|Hspell:107140|h[Embozo magnético]|h|r. ¡Agrúpate para liberar la energía sanadora!' WHERE `ID`=63567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 초 님이 말씀하시던 이방인이 자네로군.$b$b새벽의 꽃에 잘 왔네! 나는 페이지 골든드래프트라고 하고, 우리 집안은 판다리아에서 가장 맛있는 맥주를 만든다네.$b$b양조사의 이름을 더럽히며 이곳저곳 민폐만 끼치는 원더브루 집안과는 다르다고. 그 집 아들이 우리 딸을 넘보는 것도 같던데... 절대로 그럴 수는 없지! 골든드래프트와 원더브루는 어울리지 않아.', `MaleText_loc4`='那么……你就是周卓提到的那位陌生人。$b$b欢迎来到晨芳园！我是佩吉·金酿，我家是潘达利亚一流的酿酒世家。$b$b我们跟那个游酒家族可不一样，他们只会以次充好，到处败坏酒仙的美名。我甚至还发现有个毛小子盯上了我的女儿。真过分！金酿家族决不会沦落到跟游酒家族为伍。', `MaleText_loc5`='所以...你就是阿洲提過的那個陌生人。$b$b歡迎來到晨綻!我是佩吉·金流，我們家族釀的是全潘達利亞最高級的酒。$b$b不像蕩酒家那些四處遊蕩，搞臭釀酒大師美名的傢伙。我甚至隱約看過他們家的小兒子打量著我們家的女兒。真受不了!金流家和蕩酒家的就是合不來。', `MaleText_loc7`='Así que tú eres $gel:la; $gforastero:forastera; $gdel:de la; que hablaba Cho.$b$b¡$GBienvenido:Bienvenida; a Floralba! Yo soy Peiji Brisa Dorada, y mi familia fabrica la mejor cerveza de toda Pandaria.$b$bNo como esos Pócima Errante, que no dejan de manchar a escondidas el buen nombre de los maestros cerveceros por todos lados. Creo que hasta una vez pillé a su hijo pequeño mirando a mi hija. No toleraré ese tipo de cosas. Los Brisa Dorada y los Pócima Errante no se mezclan entre ellos.' WHERE `ID`=63568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 계속 비취를 구해볼게요. 주위를 돌아보면서 도움이 필요한 이는 없는지 알아보세요.', `MaleText_loc4`='我继续去寻找玉石了。你可以四处问问，看有没有人需要帮手。', `MaleText_loc5`='我要繼續找更多的玉。或許會想到處問問，看看是否有人需要幫忙。', `MaleText_loc7`='Voy a seguir buscando jade. Puede que sea conveniente preguntar si alguien quiere echar una mano.' WHERE `ID`=63569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 강한 그루끼끼들만 이름 이름이라고 불러준다.$b$B언젠가 너도 $n $n|1이;;라고 불릴 날이 있을 거야.', `MaleText_loc4`='猢狲只给高手起叠名。$b$b也许有一天，他们会管你叫$n$n。', `MaleText_loc5`='猴人只給優秀的殺手取名名。$b$b或許有一天他們會叫你$n$n。', `MaleText_loc7`='Los hozen solo dan un nombre nombre a los buenos jeringadores.$b$bPuede que un día te llamen $n $n.' WHERE `ID`=63570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 끝이오!', `MaleText_loc4`='我们完了！', `MaleText_loc5`='我們完蛋了!', `MaleText_loc7`='¡Estamos condenados!' WHERE `ID`=63571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님들, 서두르십시오! 몸을 숨겨야 합니다!', `MaleText_loc4`='快点，长者！你们必须藏起来！', `MaleText_loc5`='快點，長老!快點躲好!', `MaleText_loc7`='¡Rápido, ancestros! ¡Deben esconderse!' WHERE `ID`=63572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 시라 골든드래프트라는 아이가 내 아들에게 추파를 던지는 모습을 분명히 봤소. 그냥 내버려 둘 수는 없지.', `MaleText_loc4`='我发誓，我看见那个小塞拉·金酿给我们孩子“脸色看”。真受不了。', `MaleText_loc5`='我發誓，我看到小錫拉·金流對我的小兒子擠眉弄眼。真受不了。', `MaleText_loc7`='"Juro que he visto a esa pequeña Syra Brisa Dorada cómo miraba a mi niño. No lo soporto".' WHERE `ID`=63573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 와 계셔서 다행입니다! 낚싯대는 던져 버리고 좀 도와주십시오!', `MaleText_loc4`='谢天谢地，你来了！快把钓鱼竿扔下来，把我们救出去！', `MaleText_loc5`='謝天謝地!你來了!把魚竿丟了過來幫忙!', `MaleText_loc7`='¡Menos mal que estás aquí! ¡Tira esa caña de pescar y ayúdanos!', `FemaleText_loc1`='당신이 와 계셔서 다행이에요! 낚싯대는 던져 버리고 좀 도와주세요!', `FemaleText_loc4`='谢天谢地，你来了！快把钓鱼竿扔下来，把我们救出去！', `FemaleText_loc5`='謝天謝地!你來了!把魚竿丟了過來幫忙!', `FemaleText_loc7`='¡Menos mal que estás aquí! ¡Tira esa caña de pescar y ayúdanos!' WHERE `ID`=63574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코보크는 여러 해 동안의 동면을 잘 견뎌낸 것 같다.', `MaleText_loc4`='科沃克似乎在冬眠中经受住了岁月的考验。', `MaleText_loc5`='科沃克似乎對長年沉眠適應得很好。', `MaleText_loc7`='Parece que Kovok ha aguantado bien los años de hibernación.' WHERE `ID`=63575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이로 가나? 저 배에 오르면 내가 거기까지 태워 주지.', `MaleText_loc4`='要去昆莱？跳到船上来，我载你一程。', `MaleText_loc5`='要去崑萊嗎?跳上船吧，我送你一程。', `MaleText_loc7`='¿Vas a Kun-Lai? Salta en el bote y te llevaré hasta allí.' WHERE `ID`=63576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동료 강태공이군요! 이 동네 낚시꾼들에게서 사들인 장비가 몇 가지 있습니다. 필요한 게 있으면 말씀하십시오!', `MaleText_loc4`='原来是一位钓鱼爱好者！我从这些当地的渔夫手里弄到了各种装备，要用什么就跟我说！', `MaleText_loc5`='啊，是釣手同志!我這裡有當地漁民的各種設備。需要什麼就盡管說吧!', `MaleText_loc7`='¡Vaya, $gun:una; $gcompañero:compañera; $gpescador:pescadora;! Tengo bastante equipo procedente de los pescadores locales así que si quieres algo solo me lo tienes que decir.' WHERE `ID`=63577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 연구는 계속되어야 한다.', `MaleText_loc4`='我的研究必须继续下去。', `MaleText_loc5`='我的研究必須繼續下去。', `MaleText_loc7`='Mi investigación debe continuar.' WHERE `ID`=63578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 이러면 안 돼! 지금 멈출 순 없다. 내 변이는 계속되어야 해!', `MaleText_loc4`='不，不，不！我不能停下来。我的变异体必须活下去！', `MaleText_loc5`='不，不，不!我不能現在停止。我的突變種必須活著!', `MaleText_loc7`='¡No, no, no! Ahora no puedo detenerme. ¡Mis mutaciones tienen que vivir!' WHERE `ID`=63579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 손에 특별한 혼합물을 발라뒀다. 적을 이길 때마다 그 시체에 특별한 독이 주입될 것이다. 그 결과를 잘 관찰한 다음, 네게 유리하게 이용해야 한다.', `MaleText_loc4`='唤醒者，我已经在你的手上涂了特殊的混合物。每次你打败敌人，他们的尸体将被注入一种特殊的毒素。观察效果，并利用它们取胜。', `MaleText_loc5`='喚醒者，我在你的手上抹了一層特殊的藥劑。每當你擊敗一名敵人，他們的屍體就會被注入一種特殊的毒液。觀察結果，利用他們佔取優勢。', `MaleText_loc7`='Te he recubierto las manos con una mezcla especial, heraldo. Cada vez que derrotes a un enemigo, se inyectará su cadáver con una toxina especial. Observa los resultados, y úsalos en tu provecho.' WHERE `ID`=63580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 모든 생명체는 다 쓸모가 있다. 하지만 그걸 알아내려면 처치해야만 한다!', `MaleText_loc4`='万物皆有用处，唤醒者，可你必须得杀了它们才能找到！', `MaleText_loc5`='每種生物都有他的用途，喚醒者，但你必須把他們宰了才找得到!', `MaleText_loc7`='Todas las criaturas tienen su propósito, heraldo, ¡pero debes matarlas para descubrirlo!' WHERE `ID`=63581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 호박석이 너를 지켜주고 살찌울 것이다.', `MaleText_loc4`='愿琥珀庇护滋养着你，唤醒者。', `MaleText_loc5`='願琥珀保護並滋養你，喚醒者。', `MaleText_loc7`='Que el ámbar te proteja y alimente, heraldo.' WHERE `ID`=63582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 힘을 네게 주마. 이제 적에게 피해를 줄 때마다 생명력을 조금씩 흡수하게 될 것이다.', `MaleText_loc4`='让我的力量成为你的力量。你每次进行破坏性的攻击时，都会相应地偷取对手的生命值。', `MaleText_loc5`='讓我的力量成為你的力量。你每次造成傷害，都能把敵人一部分的生命偷走。', `MaleText_loc7`='Que mi fuerza sea tu fuerza. Por cada uno de tus ataques que inflija daño, le robarás parte de la vida a tu oponente.' WHERE `ID`=63583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 무기에 특별한 혈청을 발라뒀다. 적에게 피해를 줘 이 혈청을 주입해라. 혈청을 과도하게 주입하면, 놈들의 신체 구조에 과부하가 올 것이다.', `MaleText_loc4`='我已经在你的武器上涂了特殊的浆液。把它注入敌人体内。如果注入过多，就会超出他们身体的负荷。', `MaleText_loc5`='我已經在你的武器上頭塗了特殊的血清。將它注射到你的敵人體內。過多的注射可以讓他們的系統超載。', `MaleText_loc7`='He embadurnado tus armas con un suero especial. Inyéctaselo a tus enemigos. Tras varias inyecciones, sus organismos se sobrecargarán.' WHERE `ID`=63584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오너라, 깨우는 자여. 우리의 적을 만나보자.', `MaleText_loc4`='来吧，唤醒者。我们去会会敌人。', `MaleText_loc5`='來吧，喚醒者。讓我們看看我們的敵人。', `MaleText_loc7`='Ven, heraldo. Enfrentémonos a nuestros enemigos.' WHERE `ID`=63585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 처음으로 잠들고서 얼마나 많은 해가 흐른 건가? 이 베스와 궁전, 그리고 나의 여제님... 모든 것이 바뀌었구나.', `MaleText_loc4`='从我入睡以来，已经过去了多少年？这地方，这宫殿，还有我的女皇。一切都变了。', `MaleText_loc5`='在我第一次陷入沉睡之後，經過了多少年?這斐斯，這宮殿，我的女皇。一切都變了。', `MaleText_loc7`='¿Cuántos años han pasado desde que empezó mi sueño? Este vess, este palacio, mi Emperatriz... Todos han cambiado.' WHERE `ID`=63586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 흰 갯병은 샤가 한 짓인가? 이제 보니 질병이 우리 사회에 퍼지고 있구나. 감염된 자는 없애야만 한다!', `MaleText_loc4`='这片白色惨雾是邪煞的杰作？我现在终于明白，在我们的文化间蔓延着何种邪恶。必须净化那些受感染者！', `MaleText_loc5`='那覆蓋在我們家園上的白色疫病是煞的傑作嗎?看來我們的整個文明都被這種疾病給污染了。必須把它給除掉!', `MaleText_loc7`='¿Esta contaminación blanca es obra del sha? Ahora entiendo la infección que se extiende por toda nuestra civilización. ¡Hay que purgar a los infectados!' WHERE `ID`=63587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아래에 있는 사마귀들을 보아라. 여제가 군단에게 너무 일찍 명령을 내렸다! 여제가 혼란의 망상에 빠졌다는 징조다.', `MaleText_loc4`='看看下方那些螳螂妖。女皇这么早就派大军出袭了！这是她心智失常的又一迹象。', `MaleText_loc5`='看看我們底下的那些螳螂人。女皇太早讓他們離巢了!又是一個她已混亂迷惑的徵兆。', `MaleText_loc7`='Mira a los mántides de abajo. ¡La Emperatriz ha convocado un enjambre demasiado pronto! Una señal más de sus delirios caóticos.' WHERE `ID`=63588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 벌써 모여드는 거지? 아직 그럴 때가 안 됐는데.', `MaleText_loc4`='它们怎么已经开始聚集了？还没到时候啊。', `MaleText_loc5`='為什麼他們已經成群?時間還沒到。', `MaleText_loc7`='¿Por qué están formando un enjambre? Todavía no ha llegado la hora.' WHERE `ID`=63589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡에 난 길을 가다 보면 참 이상해요. 땅이 너무 평평해서 말이죠. 그리고 무척 더워요.$b$b쿤라이 봉우리가 그립네요.', `MaleText_loc4`='在山谷小路上行走的感觉很是诡异。这里的地面也太平了。还那么热。$b$b我想念昆莱。', `MaleText_loc5`='在山谷道路上旅行的感覺真奇怪。地面這麼平坦。而且天氣好熱。$b$b我想念崑萊。', `MaleText_loc7`='Es extraño viajar por los caminos del valle. Aquí el suelo es muy llano. Y hace mucho calor.$b$bEcho de menos Kun-Lai.' WHERE `ID`=63590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 놈들을 움직이고 있군. 겁에 질려 있구나.', `MaleText_loc4`='有东西在驱使它们。它们被吓坏了。', `MaleText_loc5`='有某種東西在逼迫他們。他們...嚇壞了。', `MaleText_loc7`='Algo los impulsa. Están asustados.' WHERE `ID`=63591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상관없다. 나조차도 놈들의 마음을 더럽히는 악의 존재를 느낄 수 있으니. 이제 이들의 광기를 끝내자.', `MaleText_loc4`='不论如何，就连我都能感受到荼毒它们心智的邪恶。我们必须终止它们的疯狂！', `MaleText_loc5`='這不重要。就連我都能感受到污染他們心靈的那股邪惡。讓我們終結他們的瘋狂行為。', `MaleText_loc7`='No importa. Hasta yo puedo sentir el mal que contamina sus mentes. ¡Debemos acabar con su locura!' WHERE `ID`=63592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 잠이 짧았구나. 바람의 군주인 멜자라크를 알아보겠군. 한때 내 형제였지만, 지금은 아니다.', `MaleText_loc4`='我的睡眠很短暂。我认出了天空之主梅尔加拉克。他曾经是我的兄弟。现在，已经不是了。', `MaleText_loc5`='看來我的睡眠十分短暫。我認識瑪爾加拉克，天空的主人。他曾經是我的兄弟。現在，再也不是了。', `MaleText_loc7`='Veo que mi sueño fue breve. Reconozco a Mel''jarak, señor de los cielos. Una vez fue mi hermano. Ya no.' WHERE `ID`=63593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 잠이 짧았구나. 궁전 바로 앞에 있는 타야크를 알아보겠군. 여제의 강력한 칼날군주지. 내 시대에는 그와 맞설 상대가 없었다.', `MaleText_loc4`='我的睡眠很短暂。我认出了塔亚克，就在宫殿门前。他是女皇麾下的刀锋勇士。在我的时代，他战无不胜。', `MaleText_loc5`='看來我的睡眠十分短暫。我認識宮殿前面那個塔亞克。女皇的刃之英雄。在我的時代，他無人可敵。', `MaleText_loc7`='Veo que mi sueño fue breve. Reconozco a Ta''yak ahí, justo delante del palacio. El campeón de espadas de la Emperatriz. En mi época estaba invicto.' WHERE `ID`=63594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 잠이 짧았구나. 저기 있는 운속을 알아보겠는걸. 자신의 이름을 호박석구체자로 다시 지었군. 하하! 실력은 항상 나만 못했지.', `MaleText_loc4`='我的睡眠很短暂。我认出了昂舒克。他现在管自己叫琥珀塑形者。哈！他的本事始终在我之下。', `MaleText_loc5`='看來我的睡眠十分短暫。我認識那邊那個翁索克。我知道他把自己改名為塑珀者。哈!他的技能從來沒超越過我。', `MaleText_loc7`='Veo que mi sueño fue breve. Reconozco a Un''sok ahí abajo. Veo que se ha rebautizado como formador de ámbar. ¡Ja! Sus habilidades nunca superaron a las mías.' WHERE `ID`=63595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 잠이 짧았구나. 조르로크를 알아보겠군. 여제의 대변인이자 말 잘 듣는 애완동물이지.', `MaleText_loc4`='我的睡眠很短暂。我认出了佐尔洛克，女皇的传声筒。对她唯命是从的小跟班。', `MaleText_loc5`='我明白自己的睡眠十分短暫。我認識索拉格，女皇之聲。他是女皇乖巧的小寵物。', `MaleText_loc7`='Veo que mi sueño fue breve. Reconozco a Zor''lok, voz de la Emperatriz. Su mascota obediente.' WHERE `ID`=63596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아갈 준비 됐습니다, 자릴.', `MaleText_loc4`='我准备好起飞了，夏克里尔。', `MaleText_loc5`='我準備好要飛行了，薩瑞爾。', `MaleText_loc7`='Quiero volar ya, Xaril.', `FemaleText_loc1`='날아갈 준비 됐어요, 자릴.', `FemaleText_loc4`='我准备好起飞了，夏克里尔。', `FemaleText_loc5`='我準備好要飛行了，薩瑞爾。', `FemaleText_loc7`='Quiero volar ya, Xaril.' WHERE `ID`=63597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르이크가 준 피해를 복구하려면 시간이 좀 걸리겠지만, 어려운 일은 아니다.', `MaleText_loc4`='修复遭到科尔里克破坏的地方需要一些时间，但可以完成。', `MaleText_loc5`='修復柯利克造成的傷害需要時間，但終究是可修復的。', `MaleText_loc7`='Reparar los daños provocados por Kor’ik llevará tiempo, pero puede hacerse.' WHERE `ID`=63598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서쪽에서 찰칵 소리가 희미하게 들려 옵니다...', `MaleText_loc4`='你听见从西边传来了微弱的咔嗒声……', `MaleText_loc5`='你聽到西邊傳來微弱的卡嗒聲..', `MaleText_loc7`='Oyes un ligero ruido de traqueteo procedente del oeste...' WHERE `ID`=63599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼 곳에서 고음으로 윙윙거리는 소리가 들려옵니다.', `MaleText_loc4`='从远处传来了高音嗡鸣声……', `MaleText_loc5`='尖銳的嗡鳴聲從遠方傳來...', `MaleText_loc7`='Percibes un zumbido estridente en la distancia...' WHERE `ID`=63600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석이 산산히 부서집니다!', `MaleText_loc4`='宝石粉碎了！', `MaleText_loc5`='寶石破碎了!', `MaleText_loc7`='¡La gema está temblando!' WHERE `ID`=63601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동쪽 벽을 따라 문득 빛이 어른거립니다...', `MaleText_loc4`='你看到沿东墙发出了一道闪光……', `MaleText_loc5`='你在東邊強上看到微光一閃而過。', `MaleText_loc7`='Observas una tenue luz en la muralla del este...' WHERE `ID`=63603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조수 부자키는 어디 있습니까?', `MaleText_loc4`='我在哪能找到助手布扎齐？', `MaleText_loc5`='我要到哪裡去找助手溥查濟?', `MaleText_loc7`='¿Dónde puedo encontrar al ayudante Buzaki?', `FemaleText_loc1`='조수 부자키는 어디 있나요?', `FemaleText_loc4`='我在哪能找到助手布扎齐？', `FemaleText_loc5`='我要到哪裡去找助手溥查濟?', `FemaleText_loc7`='¿Dónde puedo encontrar al ayudante Buzaki?' WHERE `ID`=63604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 할 일은 없습니까?', `MaleText_loc4`='我还能做些什么吗？', `MaleText_loc5`='還有什麼我能做的嗎?', `MaleText_loc7`='¿Puedo hacer algo más?', `FemaleText_loc1`='또 할 일은 없나요?', `FemaleText_loc4`='我还能做些什么吗？', `FemaleText_loc5`='還有什麼我能做的嗎?', `FemaleText_loc7`='¿Puedo hacer algo más?' WHERE `ID`=63605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 한 대 꽝!', `MaleText_loc4`='蠢蛋挨了一下！', `MaleText_loc5`='揍扁怪怪人!', `MaleText_loc7`='¡Makaku golpeado!' WHERE `ID`=63606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이를 때려눕혔다!', `MaleText_loc4`='蠢货被打中了！', `MaleText_loc5`='他馬的廢渣!', `MaleText_loc7`='¡Kakador HECHO KRAKU!' WHERE `ID`=63607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛 좀 봐라, 이 응가쟁이야!', `MaleText_loc4`='被打中了，蠢货！', `MaleText_loc5`='去死吧，廢渣!', `MaleText_loc7`='¡Jeríngate, kakador!' WHERE `ID`=63608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 재료는 우리 가문에 대대로 전해 오는 비법인데, 크라사랑 밀림에서 나는 거라네. 며칠 전에 조수 부자키를 보내서 가져오라고 했는데, 간밤에 안개 속의 주점에 도착했다는 소식을 전해 들었다네. 고대의 통로로 가서 조수가 왜 늦어지는지 알아봐 주겠나? 설마 아직도 주점에서 곯아떨어져 있는 건 아니겠지!', `MaleText_loc4`='最后一种成分，是我们家族世代相传的秘密，来自于卡桑琅丛林。我几天前派了助手布扎齐去寻找这种成分，收到的消息是他昨天晚上到达了迷雾酒肆。你能前往远古之路去看看是什么让他耽搁了吗？他最好不要在酒馆里睡过了头！', `MaleText_loc5`='最後的成分，一個來自喀撒朗蠻荒、在我的家族中代代相傳的秘密。幾天前，我派助手溥查濟去幫我把這個材料取來，並得知他昨晚已到達霧隱客棧。你能不能前往上古通道，去看看是什麼事耽誤了他?他最好不是還在旅店裡睡覺!', `MaleText_loc7`='El último ingrediente, un secreto transmitido de generación en generación en mi familia, viene de la Espesura Krasarang. Mandé al ayudante Buzaki a recogerlo hace unos días, y recibí noticias de que había llegado a la Taberna en la Niebla anoche. ¿Puedes entrar en el Pasaje Antiguo y averiguar por qué tarda tanto? ¡Más le vale no estar dormido en la taberna!' WHERE `ID`=63609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸물거리지 마십시오, 친구들!', `MaleText_loc4`='放机灵点，伙计！', `MaleText_loc5`='振作點，夥計們!', `MaleText_loc7`='¡Deprisa!' WHERE `ID`=63610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='없애야 할 호드가 있습니다! 냄새가 나요!', `MaleText_loc4`='有部落可以杀了，小子们！我闻到了！', `MaleText_loc5`='小夥子們，這裡有部落的人可殺!我能聞到他們!', `MaleText_loc7`='¡Hay miembros de la Horda a los que matar! ¡Puedo olerlos!' WHERE `ID`=63611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽거나, 죽이거나, 둘 중 하나입니다! 물러설 수는 없어요!', `MaleText_loc4`='非生即死，伙计们！无路可退！', `MaleText_loc5`='不前進就得死，夥計們!不能回頭!', `MaleText_loc7`='¡O ellos, o nosotros! ¡No hay vuelta atrás!' WHERE `ID`=63612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이 몇 마리는 얼라이언스의 상대가 되지 않습니다!', `MaleText_loc4`='区区几只猴子，也配跟联盟作对！', `MaleText_loc5`='幾隻猴子無法與聯盟對抗!', `MaleText_loc7`='¡Unos cuantos monos no son nada para la Alianza!' WHERE `ID`=63613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라, 이 짐승들아! 얼라이언스의 이름으로 이 땅을 점령하겠다!', `MaleText_loc4`='退下，野蛮人！我以联盟之名宣布对这片土地的占有权！', `MaleText_loc5`='退下吧，野蠻人!我宣布這塊土地屬於聯盟!', `MaleText_loc7`='¡Retírense, salvajes! ¡Reclamo esta tierra en nombre de la Alianza!' WHERE `ID`=63614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 버티십시오! 지원군이 오고 있습니다!', `MaleText_loc4`='坚持住，兄弟们！援军很快就到！', `MaleText_loc5`='撐住，弟兄們!援軍來了!', `MaleText_loc7`='¡Aguanten! ¡Ya llegan los refuerzos!' WHERE `ID`=63615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 대 맞아봐, 이 우끼-', `MaleText_loc4`='被击中了，蠢——', `MaleText_loc5`='去死吧，怪－', `MaleText_loc7`='Jeríngate, wik-' WHERE `ID`=63616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 말릭. [클락시 강화 효과]', `MaleText_loc4`='我今天需要你的协助，玛里克。', `MaleText_loc5`='協助我，瑪力克。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Malik. [Mejora Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 말릭. [클락시 강화 효과]', `FemaleText_loc4`='我今天需要你的协助，玛里克。', `FemaleText_loc5`='協助我，瑪力克。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Malik. [Mejora Klaxxi]' WHERE `ID`=63617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 속임수는 물과 같아야 한다. 적의 힘에 반발하지 않고, 그저 함께 흘러야 하지. 적의 공격이 너를 서서히 지나치게 한 다음, 공격을 꽂아 넣어라.', `MaleText_loc4`='唤醒者，秘诀就如同流水之道。不要与敌人的力量硬碰硬——而是要以柔克刚，让他的重拳擦身而过。这时候，再对他还以颜色。', `MaleText_loc5`='喚醒者，訣竅在於要像水一樣。不要和敵人的力量正面對抗，只要隨著它流動。讓他的攻擊流過你的身邊。然後趁這個時機刺穿他。', `MaleText_loc7`='El truco, heraldo, es ser como el agua. No te resistas a la fuerza de tu enemigo; fluye con ella. Deja que sus golpes pasen de largo. Y entonces LO EMPALAS.' WHERE `ID`=63618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펄럭이 필요해?', `MaleText_loc4`='要不要土拨鼠？', `MaleText_loc5`='需要有人拍手嗎?', `MaleText_loc7`='¿Necesitas una aleta?' WHERE `ID`=63619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽의 꽃으로 보내 주십시오.', `MaleText_loc4`='送我去晨芳园。', `MaleText_loc5`='送我到晨綻去。', `MaleText_loc7`='Envíame a Floralba.', `FemaleText_loc1`='새벽의 꽃으로 보내 주세요.', `FemaleText_loc4`='送我去晨芳园。', `FemaleText_loc5`='送我到晨綻去。', `FemaleText_loc7`='Envíame a Floralba.' WHERE `ID`=63620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, $p님! 다 끝인 줄로만 알았습니다.', `MaleText_loc4`='谢谢你，$p！我以为自己死定了。', `MaleText_loc5`='謝了，$p!我還以為我完蛋了。', `MaleText_loc7`='¡Gracias, $p! Creía que era mi fin.' WHERE `ID`=63621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록 놈들이 나타난 데다 배까지 난파되는 바람에 겁에 질렸습니다.', `MaleText_loc4`='当我看到那些蜥蜴人时，我慌了，打翻了船。', `MaleText_loc5`='當我看到那麼多的薩烏洛克時，我慌了手腳，並毀了我的船。', `MaleText_loc7`='Me entró el pánico cuando vi a todos esos saurok y destrocé mi barco.' WHERE `ID`=63622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 축제가 시작되기 전에 양조사 부프 님께 가야겠습니다. 구해 주셔서 감사합니다, $p님!', `MaleText_loc4`='我得赶在节庆活动开始前，把这个交给酒仙布夫。再次感谢你的搭救之恩，$p！', `MaleText_loc5`='我必須在節慶開始前把這個送去給釀酒大師布夫。再次感謝你救了我，$p!', `MaleText_loc7`='Tengo que llevarle esto al Maestro cervecero Boof antes de que comience el festival. ¡Gracias de nuevo por salvarme, $p!' WHERE `ID`=63623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 좋습니다! 와 주셨군요. 이제 "해적" 호젠 놈들에게 우리 마을을 공격하면 어떻게 되는지 알려 줘야겠군요.', `MaleText_loc4`='啊！好！你成功了。是时候让这些“海盗”猢狲明白，它们为什么不该袭击我们的村庄。', `MaleText_loc5`='啊!很好!你成功了。該是時候讓這些猴人海盜了解，為什麼他們不該搶劫我們的村莊。', `MaleText_loc7`='¡Ah! ¡Bien! Lo habéis conseguido. Es hora de enseñar a esos hozen "piratas" por qué es mala idea asaltar nuestras aldeas.' WHERE `ID`=63624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발하시겠습니까?', `MaleText_loc4`='你确定已经准备好出发了？', `MaleText_loc5`='你確定你準備好要出去了嗎?', `MaleText_loc7`='¿Seguro que quieres partir?', `FemaleText_loc1`='출발하시겠습니까?', `FemaleText_loc4`='你确定已经准备好出发了？', `FemaleText_loc5`='你確定你準備好要出去了嗎?', `FemaleText_loc7`='¿Seguro que quieres partir?' WHERE `ID`=63625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 호박석은 용장의 유예를 준다. 네가 죽음에 가까워지면, 자동으로 동작할 것이다.', `MaleText_loc4`='唤醒者，琥珀为英杰提供了喘息之机。如果你濒临死亡，它会自动激活。', `MaleText_loc5`='琥珀可以延續聖螳的生命，喚醒者。如果你陷入瀕死的境地，它會自動啟動。', `MaleText_loc7`='El ámbar ofrece el descanso de un dechado, heraldo. Si estás a punto de morir, se activará solo.' WHERE `ID`=63626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자비는 필요 없다! 피비린내를 즐겨라! 공격을 더 할수록 생명력이 더 많이 회복될 것이다.', `MaleText_loc4`='绝不手软！汲取鲜血之气！你越是攻击，越能获得更多的生命值。', `MaleText_loc5`='不要憐憫他們!在血的氣味中茁壯生長!你攻擊得越多，生命就回復得越多!', `MaleText_loc7`='¡No tengas piedad! ¡Disfruta del olor de la sangre! Cuanto más ataques, más salud recuperarás.' WHERE `ID`=63627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 의식을 잃은 것 같네요. 제가 깨워 보지요.', `FemaleText_loc4`='看来他只是失去意识了。我应该能把他叫醒。', `FemaleText_loc5`='看來他只是昏過去了。我應該能叫醒他。', `FemaleText_loc7`='Parece que solo está inconsciente. Creo que podré despertarlo.' WHERE `ID`=63628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 축제로 돌아가요, $p 님. 이따가 저희 집을 찾아 주세요. 제가 특별한 걸 만들고 있거든요!', `FemaleText_loc4`='让我们回到节日中来吧，$p。到我家坐坐，我正在做一些特别的东西！', `FemaleText_loc5`='我們回到慶典上吧，$p。晚點記得到我的房子那裡，我在做點特別的!', `FemaleText_loc7`='Volvamos al festival, $p. Pásate por mi casa después, ¡estoy preparando algo especial!' WHERE `ID`=63629;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양조사님! 마을 밖에서 바타리 정찰대가 목격됐습니다!', `FemaleText_loc4`='酒仙！在村外发现了巴塔里侦察小队！', `FemaleText_loc5`='釀酒大師!有人在村莊外面看到巴塔利斥候隊!', `FemaleText_loc7`='¡Maestro cervecero! ¡Han avistado grupos de exploración Bataari fuera de la aldea!' WHERE `ID`=63630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건... 이야! 다들 데려왔군요!', `MaleText_loc4`='那是……嘿！你把他们带回来了！', `MaleText_loc5`='那是...嘿!你帶他們回來了!', `MaleText_loc7`='Eso es... ¡OYE! ¡Los has traído de vuelta!' WHERE `ID`=63631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 살았습니다! 정말 대단한 영웅이시군요!', `MaleText_loc4`='是你救了我！你真是大英雄！', `MaleText_loc5`='你救了我!真是個英雄!', `MaleText_loc7`='¡Me has salvado! ¡Qué heroicidad!', `FemaleText_loc1`='덕분에 살았어요! 정말 대단한 영웅이시군요!', `FemaleText_loc4`='是你救了我！你真是大英雄！', `FemaleText_loc5`='你救了我!真是個英雄!', `FemaleText_loc7`='¡Me has salvado! ¡Qué heroicidad!' WHERE `ID`=63632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c|1이라면;라면; 야운골 따위 한 방에 날려 버릴 줄 알았습니다!', `MaleText_loc4`='我一直都知道$pc能打败野牛人！', `MaleText_loc5`='我早就知道$pc可以打敗揚古!', `MaleText_loc7`='¡Siempre supe que $gun:una; $pc podría con un yaungol!', `FemaleText_loc1`='$c|1이라면;라면; 야운골 따위 한 방에 날려 버릴 줄 알았어요!', `FemaleText_loc4`='我一直都知道$pc能打败野牛人！', `FemaleText_loc5`='我早就知道$pc可以打敗揚古!', `FemaleText_loc7`='¡Siempre supe que $gun:una; $pc podría con un yaungol!' WHERE `ID`=63633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어디서 오신 분입니까? 아무튼 감사합니다!', `MaleText_loc4`='你是……你是打哪儿来的？谢谢你！', `MaleText_loc5`='你...你從哪裡來的?謝謝你!', `MaleText_loc7`='¿De... de dónde has salido? ¡Gracias!', `FemaleText_loc1`='어... 어디서 오신 분이죠? 아무튼 고마워요!', `FemaleText_loc4`='你是……你是打哪儿来的？谢谢你！', `FemaleText_loc5`='你...你從哪裡來的?謝謝你!', `FemaleText_loc7`='¿De... de dónde has salido? ¡Gracias!' WHERE `ID`=63634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 공기는 참 깨끗하네요.', `FemaleText_loc4`='这里的空气真干净。', `FemaleText_loc5`='這裡的空氣真乾淨。', `FemaleText_loc7`='Aquí el aire es muy limpio.' WHERE `ID`=63635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 유랑도에서 자랐어요. 그곳은 땅이 너무 비좁아 사냥할 것도 없었고, 그러다 보니까 포식자라고 할만한 것도 정말 없었죠.$b$b그런데 여기는... 여기에는 거대한 무샨과 늑대들, 그리고 모든 종류의 포식자들이 돌아다녀요. 바로 사냥꾼의 꿈이 실현된 거랍니다.', `FemaleText_loc4`='我是在迷踪岛上长大的。那里空间有限。没地方让我们狩猎，也没有什么值得一提的凶禽猛兽。$b$b可这里……这里有大块头的穆山兽，有野狼，还有各种各样的食肉动物。这里简直是让猎手美梦成真的乐园。', `FemaleText_loc5`='我在漂流島長大。那裡的空間十分有限。從來就沒有狩獵的地方，也沒有值得一提的掠食動物。$b$b但這裡...這裡有巨大的牡山獸，狼，以及各式各樣的掠食動物。這裡是獵人夢想中的樂園。', `FemaleText_loc7`='Me crié en La Isla Errante. Allí el espacio era muy limitado. Nunca había sitio para cazar ni depredadores dignos de mención.$b$bPero aquí... Aquí están los grandes mushan y los lobos y toda clase de depredadores. Esto es el sueño de un cazador hecho realidad.' WHERE `ID`=63636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아에 처음 오셨나요? 저도 그렇답니다. 다른 이들이 이곳에 대해 말해주던 게 기억나요. 너무 신난답니다!', `FemaleText_loc4`='头一次来潘达利亚？我也是。我还记得他们讲述的关于这个地方的故事。真令人兴奋！', `FemaleText_loc5`='第一次來到潘達利亞?我也是。我記得他們跟我說過關於這個地方的那些故事。真興奮啊!', `FemaleText_loc7`='¿Es tu primera visita a Pandaria? La mía también. Recuerdo las historias que nos contaban sobre este lugar. ¡Qué emocionante!' WHERE `ID`=63637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네싱워리 탐험대는 가시덤불 골짜기에서 처음 만났어요. 그때부터 서로 만나다 헤어지다 했었죠. 이제 드디어 네싱워리 탐험대에 제가 합류했어요!', `FemaleText_loc4`='我最早是在荆棘谷遇见奈辛瓦里的成员的。在那之后，我就陆续跟他们见过几次面。终于在他们的远征队里找到了自己的一席之地！', `FemaleText_loc5`='我第一次見到奈辛瓦里遠征隊是在荊棘谷。後來我又斷斷續續地遇上他們好幾次。最後我終於在他們的遠征隊中贏得一席之地!', `FemaleText_loc7`='Conocí por primera vez a los Nesingwary en Tuercespina. Desde entonces me encuentro con ellos de vez en cuando. ¡Por fin he conseguido un puesto en su safari!' WHERE `ID`=63638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 당신이 누군지 알겠어요. 유랑도에서 오신 분 맞죠?$b$b판다리아에 있으니 기분이 참 묘하지 않나요?$b$b저는 항상 판다리아가 그냥 전설일 뿐이라고 생각했답니다. 정말 존재한다는 게 믿기지 않아요!', `FemaleText_loc4`='噢！我想我认识你。你是从迷踪岛来的是不？$b$b身处潘达利亚的感觉很奇妙吧？$b$b我一直以为这地方不过是传说罢了。真不敢相信，它竟然真实存在着！', `FemaleText_loc5`='喔!我想我認得你。你是從漂流島來的對吧?$b$b踏上潘達利亞的感覺可不是挺怪的嗎?$b$b我一直以為這地方不過只是個傳說。我不敢相信潘達利亞真的存在!', `FemaleText_loc7`='¡Oh! Creo que te reconozco. Eres de La Isla Errante, ¿no?$b$b¿No es extraño estar en Pandaria?$b$bSiempre pensé que este lugar no era más que una leyenda. ¡No me puedo creer que exista de verdad!' WHERE `ID`=63639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기는 동물도 정말 많고, 땅도 무지하게 넓어요.$b$b유랑도에는 땅이 너무 좁아서 포식자들이 사냥할 수 있을 정도로 크게 자라지도 못한답니다.', `FemaleText_loc4`='这里生机盎然，一望无垠。$b$b迷踪岛上地方狭小，猛兽根本没空间茁壮成长，供猎人捕杀。', `FemaleText_loc5`='這裡有好多生命。還有好多空間。$b$b反觀漂流島，絕不可能有足夠的空間讓掠食動物長成可以狩獵的大小。', `FemaleText_loc7`='Aquí hay mucha vida. Y mucho espacio.$b$bEn La Isla Errante no había espacio suficiente para que los depredadores llegaran a ser lo bastante grandes para cazarlos.' WHERE `ID`=63640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 잘하셨어요! 네싱워리 탐험대를 찾으셨군요. 방향 감각이 없으면 그 밀림은 돌아다니기 약간 어렵답니다.$b$b저 모구 놈들이 제 사냥을 계속 방해하고 있어요.', `FemaleText_loc4`='啊，很好！你找到远征队了。要是没有点旅行天赋，很容易在丛林里迷失方向。$b$b那些魔古族没完没了地妨碍我狩猎。', `FemaleText_loc5`='啊太好了!你找到狩旅團了。如果沒有一點方向感，要在這叢林裡找路會有些困難。$b$b那些魔古一直在妨礙我狩獵。', `FemaleText_loc7`='¡Ah, muy bien! Has encontrado el safari. Es un poco difícil moverse por esa jungla sin un buen sentido de la orientación.$b$bEsos mogu no dejaban de molestarme mientras cazo.' WHERE `ID`=63641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\creatureportrait_bubble.blp:20|t%s|1이;가; |cFFFF0000|Hspell:124653|h[물 보호막]|h|r을 시전합니다! 용오름을 사용해 터뜨리십시오!', `MaleText_loc4`='|Tinterface/Icons/creatureportrait_bubble.blp:20|t%s施放了|cFFFF0000|Hspell:124653|h[水体防护层]|h|r！用水柱破坏它！', `MaleText_loc5`='|TInterface\\Icons\\creatureportrait_bubble.blp:20|t%s正在施放|cFFFF0000|Hspell:124653|h[水之殼]|h|r!使用水柱術來打破它!', `MaleText_loc7`='|TInterface/Icons/creatureportrait_bubble.blp:20|t¡%s lanza |cFFFF0000|Hspell:124653|h[Caparazón acuático]|h|r! ¡Usa los chorros de agua para romperlo!' WHERE `ID`=63642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사냥꾼을 샤낭을 합니다. 그리고 예술가는... 예술을 하지요.$b$b저는 제 예술 작품에 사냥의 야성미를 담으려고 이곳에 왔습니다.$b$b우리는 낯선 땅에 와 있고, 우리가 잡은 사냥감 또한 낯선 것들이다 보니 다른 대륙에서 이것들을 알아보는 이가 많지 않습니다.$b$b제 예술 활동을 통해 당신과 네싱워리 탐험대의 성공을 증명해줄 겁니다.', `MaleText_loc4`='猎手狩猎。艺术家……则钻研艺术。$b$b我来这里是为了用艺术来表现狩猎的凶残。$b$b我们身处陌生的土地，而且在这世界上也没几个人熟悉我们要猎杀的这种奇怪生物。$b$b通过我的艺术，我能证明你的成功，以及奈辛瓦里远征队的成功。', `MaleText_loc5`='一個獵人要做的就是狩獵。一個藝術家...就要創作藝術。$b$b我到這裡是為了透過我的藝術來表達狩獵的兇猛。$b$b我們在一個陌生的地方，也因此我們所捕捉的奇怪獵物，只有少數幾個世界知名的人很清楚牠們是什麼東西。$b$b透過我的藝術，我證明你的成功，以及奈辛瓦里遠征隊的成功。', `MaleText_loc7`='Un cazador caza. Un artista... arta.$b$bEstoy aquí para capturar la ferocidad de la jungla a través de mi arte.$b$bEstamos en tierras ignotas, y pocos en el mundo conocido están familiarizados con las extrañas criaturas que cazamos.$b$bMediante mi arte demuestro tu éxito y el éxito de los Nesingwary.' WHERE `ID`=63643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쭉 들이켜세요, $p 님. 완전히 다 마시기 전에는 바다에 발가락 하나라도 담글 생각 하지 마세요.', `FemaleText_loc4`='喝下去，$p。在你把脚趾头伸进海里之前，我要看那瓶子变空。', `FemaleText_loc5`='喝完，$p。在你不省人事之前，我要見到你把這瓶子喝乾。', `FemaleText_loc7`='Bebe, $p. Quiero ver ese vial vacío antes de que metas un dedo del pie en el mar.' WHERE `ID`=63644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 마셨네요. 해초랑 뜨거운 쓰레기 맛 같지 않아요?', `FemaleText_loc4`='可以出发了。味道像是混合了海草和热垃圾，是吧？', `FemaleText_loc5`='來，給你。嚐起來像海藻加上沸騰垃圾的味道，對吧?', `FemaleText_loc7`='Eso es. Sabe a algas y basura caliente, ¿verdad?' WHERE `ID`=63645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='북풍 주점에 잘 오셨습니다.', `FemaleText_loc4`='欢迎光临北风酒馆。', `FemaleText_loc5`='歡迎來到北風客棧。', `FemaleText_loc7`='Te doy la bienvenida a la taberna Vientonorte.' WHERE `ID`=63646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하십니까! 오늘 밤 묵을 방이 필요하십니까?', `FemaleText_loc4`='你好啊朋友！想找个房间过夜吗？', `FemaleText_loc5`='你好啊，朋友!你需要房間休息一晚嗎?', `FemaleText_loc7`='¡Hola! ¿Te hace falta una habitación para pasar la noche?' WHERE `ID`=63647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물 위를 걸을 수 있게 도와주시겠습니까?', `MaleText_loc4`='你能让我不掉进水里吗，塔蒂？', `MaleText_loc5`='你能幫我出到水面上嗎，塔特?', `MaleText_loc7`='¿Me puedes ayudar a moverme por el agua, Tart?', `FemaleText_loc1`='물 위를 걸을 수 있게 도와주시겠어요?', `FemaleText_loc4`='你能让我不掉进水里吗，塔蒂？', `FemaleText_loc5`='你能幫我出到水面上嗎，塔特?', `FemaleText_loc7`='¿Me puedes ayudar a moverme por el agua, Tart?' WHERE `ID`=63648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 무기를 쓸 일이 생길 줄은 몰랐네...', `MaleText_loc4`='我从没想过自己会被迫重拾武器作战……', `MaleText_loc5`='我從沒想過我得重新拾起武器，再次使用它...', `MaleText_loc7`='Jamás pensé que tendría que volver a empuñar un arma...' WHERE `ID`=63649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조우친은 이 세상의 어둠으로부터 안전하다는 착각을 하고 있었다네.', `MaleText_loc4`='我几乎骗过了自己，相信卓金在这个世界上能免受黑暗的侵袭。', `MaleText_loc5`='我差點就騙過自己，以為驟晴村可以不受世界上黑暗的侵襲。', `MaleText_loc7`='Casi me había convencido a mí mismo de que Zouchin estaba a salvo de la oscuridad del mundo.' WHERE `ID`=63650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 가족과 함께 평화롭게 살기 위해 전투에서 물러났다네. 하지만 전투가 날 쉽게 놓아주지 않을 모양이군.', `MaleText_loc4`='我退出战斗，与世无争地和家人温馨度日。但看来战场不肯让我轻易离开啊。', `MaleText_loc5`='我之前從戰場上退休，並與我的家人一起平靜的過日子。看來戰場不會那麼輕易地讓我退休。', `MaleText_loc7`='Me retiré de la batalla para vivir en paz con mi familia. Parece que la batalla no dejará que me retire tan fácilmente...' WHERE `ID`=63651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한때 괜찮은 전사였다네. 나이를 먹으면서 실력이 줄지는 않았기를 바라야겠군.', `MaleText_loc4`='我曾经是位骁勇的战士。希望时间没有将我的战斗技能消磨殆尽。', `MaleText_loc5`='我曾是一個偉大的戰士。希望時間沒有從我身上奪走太多技能。', `MaleText_loc7`='Una vez fui un gran luchador. Esperemos que la edad no me haya arrebatado toda la habilidad.' WHERE `ID`=63652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주민들에게 무기를 쥐여 준다고 해서 마을을 지킬 수 있는 건 아닐세. 자신 있게 무기를 쓸 수 있도록 가르쳐야 하지.', `MaleText_loc4`='要让这村庄做好战斗的准备，不光是把武器交到村民的手里就行了。我们得教会他们，如何满怀信心地驾驭武器。', `MaleText_loc5`='為村莊進行準備，並不只是把武器放在他們手中而已。我們必須教導他們如何自信地使用武器。', `MaleText_loc7`='Para preparar la aldea no basta con dar armas a la gente. Debemos enseñarles a blandirlas con aplomo.' WHERE `ID`=63653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 한 번 감사드려요, $p 님! 당장 양조사 부프 님께 가져다드려야겠네요.', `FemaleText_loc4`='再次感谢，$p！我会立刻把它交给酒仙布夫。', `FemaleText_loc5`='再次感謝你，$p!我會立刻把這東西帶去給釀酒大師布夫。', `FemaleText_loc7`='¡Gracias de nuevo, $p! Le llevaré esto al maestro cervecero Boof enseguida.' WHERE `ID`=63654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인... 도망쳐...', `MaleText_loc4`='安度因……快跑……', `MaleText_loc5`='安杜因...快逃...', `MaleText_loc7`='Anduin... corre...' WHERE `ID`=63655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 만났구나, 안개 너머의 낯선 아이야.', `FemaleText_loc4`='又见面了，迷雾之外的陌生人。', `FemaleText_loc5`='又見面了，來自迷霧彼端的陌生人。', `FemaleText_loc7`='Nos volvemos a encontrar, extraño de más allá de la niebla.' WHERE `ID`=63656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 전투로 아주 비싼 값을 치렀구나. 내 부활은 몇 년 더 기다려야겠다.', `FemaleText_loc4`='这场战争代价高昂。就连我也要若干年后才能重生。', `FemaleText_loc5`='這場戰鬥對我造成很大的負擔，再生要花上數年之久。', `FemaleText_loc7`='Esta batalla ha sido agotadora. Mi renacimiento tendrá que esperar varios años.' WHERE `ID`=63657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 일에서 깨달음을 얻거라!', `FemaleText_loc4`='有所领悟吧！', `FemaleText_loc5`='記住這個教訓，陌生人!', `FemaleText_loc7`='¡Aprende bien esta lección!' WHERE `ID`=63658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 안개가 걷혔는지는 모르겠구나. 하지만 이유가 있을 것이다.', `FemaleText_loc4`='我不知道迷雾为何一分为二，但其中一定有原因。', `FemaleText_loc5`='我不明白迷霧為何散去，但是我知道一定是有原因的。', `FemaleText_loc7`='No sé por qué se ha despejado la niebla, pero sé que hay una razón.' WHERE `ID`=63659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅에 전쟁을 끌어들이려 너희가 온 것은 분명 아니겠지. 판다리아에는 어둠이 숨어 있으니. 그건 너도 직접 보았었다!', `FemaleText_loc4`='你显然不是要将战争带到这儿来。在潘达利亚潜藏着黑暗——你已经亲眼见到了！', `FemaleText_loc5`='你出現在這裡顯然不是為了帶來戰火。黑暗潛伏在潘達利亞之中，你自己親身見識過了!', `FemaleText_loc7`='Está claro que no has venido a traer tu guerra a estas tierras. Hay una oscuridad oculta en Pandaria; la has visto con tus propios ojos.' WHERE `ID`=63660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 안개가 걷힌 데에는 틀림없이 이유가 있다. 네가 그 이유다. 네 역할을 찾아라.', `FemaleText_loc4`='但我能肯定你就是迷雾分开的原因。弄清你来这里的意图吧。', `FemaleText_loc5`='不過我很肯定，迷霧散去必定有原因，就是因為你。找出你在此的使命。', `FemaleText_loc7`='De lo que estoy segura es de que la niebla se disipó por una razón. Y tú eres esa razón. Encuentra tu propósito.' WHERE `ID`=63661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 바람의 계곡에 가면 이 땅에 대해 많이 배울 수 있을 것이다.', `FemaleText_loc4`='你能从四风谷了解到许多与这片土地有关的事。', `FemaleText_loc5`='在四風峽可以學到許多關於這片土地的知識。', `FemaleText_loc7`='Puedes aprender muchas cosas sobre esta tierra en el Valle de los Cuatro Vientos.' WHERE `ID`=63662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안개 너머에서 이곳을 찾아온 손님이 또 있다. "첸 스톰스타우트"라고 하지. 판다렌이지만, 다른 땅에서 왔단다.', `FemaleText_loc4`='还有另一位迷雾之外的访客。叫“陈·风暴烈酒”，是个熊猫人，但却来自不同的故乡。', `FemaleText_loc5`='在這還有一名迷霧彼端的訪客，叫做「老陳·風暴烈酒」，他是熊貓人，不過來自不同的地方。', `FemaleText_loc7`='Hay otro visitante de más allá de la niebla. Se llama "Chen Cerveza de Trueno". Es un pandaren, pero de otra tierra.' WHERE `ID`=63663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸과 함께 이 땅을 걸어라. 이곳의 사람들과 친구가 되어라. 시간이 지나면 답을 찾을 것이다.', `FemaleText_loc4`='和陈一起在这片土地上走走。跟这里的住民交交朋友。你终究会找到答案的。', `FemaleText_loc5`='和這個老陳一起旅行吧。和這裡的人們交朋友。你會隨著時間找到答案的。', `FemaleText_loc7`='Recorre esta tierra con Chen. Haz amigos entre nuestra gente. Con el tiempo hallarás respuestas.' WHERE `ID`=63664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가거라, 낯선 아이야. 다시 만나면 너를 ''친구''라고 부르고 싶구나.', `FemaleText_loc4`='后会有期。希望我们下次碰面时能成为“朋友”。', `FemaleText_loc5`='再見了，陌生人。希望下次見面時，我可以稱你為朋友。', `FemaleText_loc7`='Adiós. La próxima vez que nos veamos, espero que ya no seamos extraños, sino amigos.' WHERE `ID`=63665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대공포로 사마귀를 맞혀 떨어뜨리십시오!', `MaleText_loc4`='开炮！击落那些螳螂妖！', `MaleText_loc5`='使用火砲!把螳螂人射下來!', `MaleText_loc7`='¡Usad los cañones! ¡Disparad a los mántides!' WHERE `ID`=63666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<신호기가 부드럽게 웅웅거립니다>', `MaleText_loc4`='<灯塔低声嗡鸣着。>', `MaleText_loc5`='<信號塔柔和地發出嗡鳴聲。>', `MaleText_loc7`='<La baliza zumba con suavidad.>' WHERE `ID`=63667;
