UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좀 쫓아 주세요!', `FemaleText_loc4`='把它们从我身边赶走！', `FemaleText_loc5`='把他們從我身邊弄走!', `FemaleText_loc7`='¡Quitadmelos de encima!' WHERE `ID`=63670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 죽기엔 아직 젊다고요!', `FemaleText_loc4`='我还年轻，我不想死！', `FemaleText_loc5`='我還年輕，我不能死!', `FemaleText_loc7`='¡Soy demasiado joven para morir!' WHERE `ID`=63671;
