UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람 살려!', `FemaleText_loc4`='救命！救命！', `FemaleText_loc5`='救命!救命!', `FemaleText_loc7`='¡Socorro! ¡Socorro!' WHERE `ID`=63674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으아아아악!', `FemaleText_loc4`='啊——！', `FemaleText_loc5`='啊啊啊啊啊啊!', `FemaleText_loc7`='¡Aaaaaaah!' WHERE `ID`=63675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상어가 또 필요합니다!', `MaleText_loc4`='我需要另一只鲨鱼！', `MaleText_loc5`='我需要另一條鯊魚!', `MaleText_loc7`='¡Necesito otro tiburón!', `FemaleText_loc1`='상어가 또 필요해요!', `FemaleText_loc4`='我需要另一只鲨鱼！', `FemaleText_loc5`='我需要另一條鯊魚!', `FemaleText_loc7`='¡Necesito otro tiburón!' WHERE `ID`=63676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상어 잡는 데 관심 있습니까?', `MaleText_loc4`='有兴趣抓只鲨鱼吗？', `MaleText_loc5`='有興趣抓一條鯊魚嗎?', `MaleText_loc7`='¿Quieres capturar un tiburón?', `FemaleText_loc1`='상어 잡는 데 관심 있나요?', `FemaleText_loc4`='有兴趣抓只鲨鱼吗？', `FemaleText_loc5`='有興趣抓一條鯊魚嗎?', `FemaleText_loc7`='¿Quieres capturar un tiburón?' WHERE `ID`=63677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $p 님! 저 녀석들이 절 잡아먹으려고 했어요!', `FemaleText_loc4`='谢谢你，$p！它们要吃掉我！', `FemaleText_loc5`='謝了，$p!他們差點就要吃了我!', `FemaleText_loc7`='¡Gracias, $p! ¡Iban a comerme!' WHERE `ID`=63678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토깽들이 곡식을 먹어 치우고 있어요!', `FemaleText_loc4`='兔妖把粮食都吃光了！', `FemaleText_loc5`='兔妖正在吃掉所有的穀物!', `FemaleText_loc7`='¡Los mures se están comiendo todo el grano!' WHERE `ID`=63679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 토깽을 없애 주시겠어요?', `FemaleText_loc4`='$n，你能帮我解决掉这些兔妖吗？', `FemaleText_loc5`='$n你能幫我趕走這些兔妖嗎?', `FemaleText_loc7`='$n, ¿puedes ayudarme a acabar con estos mures?' WHERE `ID`=63680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 토깽 잡아요!', `FemaleText_loc4`='抓住那些兔妖！', `FemaleText_loc5`='解決那些兔妖!', `FemaleText_loc7`='¡Ve por esos mures!' WHERE `ID`=63681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훠이!', `FemaleText_loc4`='嘘！', `FemaleText_loc5`='去去!', `FemaleText_loc7`='¡Fuera!' WHERE `ID`=63682;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저리 가!', `FemaleText_loc4`='离开那儿！', `FemaleText_loc5`='滾出這裡!', `FemaleText_loc7`='¡Largo de ahí!' WHERE `ID`=63683;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곡물을 구해요, $p 님!', `FemaleText_loc4`='救救粮食吧，$p！', `FemaleText_loc5`='拯救穀物，$p!', `FemaleText_loc7`='¡Salva el grano, $p!' WHERE `ID`=63684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토깽이들을 없애 버려요!', `FemaleText_loc4`='抓住那些兔妖，$p！', `FemaleText_loc5`='解決那些兔妖，$p!', `FemaleText_loc7`='¡Ve por esos mures, $p!' WHERE `ID`=63685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무리 어미예요! 조심하세요!', `FemaleText_loc4`='是巢穴主母！小心，$p！', `FemaleText_loc5`='小心，$p!是巢母!', `FemaleText_loc7`='¡Es la madre del cubil! ¡Cuidado, $p!' WHERE `ID`=63686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파가 웬 종을 보냈군. 샨 부가 음영파를 잘못 본 모양이야...', `MaleText_loc4`='影踪派竟然让跟班替他们办事？也许山怖搞错了……', `MaleText_loc5`='影潘派了個奴才來做他們的工作?或許衫布看錯他們了...', `MaleText_loc7`='¿El Shadopan envía a un lacayo para que haga su trabajo? Puede que Shan Bu estuviera equivocado respecto a ellos.' WHERE `ID`=63687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 넌... 이미... 실패했다...', `MaleText_loc4`='哈哈！你……已经……失败了……', `MaleText_loc5`='哈!你...已經...失敗了...', `MaleText_loc7`='¡Ja! Ya... has... fracasado...' WHERE `ID`=63688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곡물 창고에 아직도 토깽이 있어요! 좀 쫓아 주세요, 네?', `FemaleText_loc4`='粮仓里还有兔妖！你能帮我赶走它们吗，$p？', `FemaleText_loc5`='還是有很多兔妖在倉庫裡!你可以幫我把他們嚇走嗎，$p?', `FemaleText_loc7`='¡Todavía hay más mures en los silos! ¿Puedes ahuyentarlos, $p?' WHERE `ID`=63689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 적을 잊고 숨 돌릴 곳이 필요하시오? 딱 적당한 장소에 적당한 인물을 찾아오셨구려.', `MaleText_loc4`='想在战斗中停下来喘口气？那你可来对地方，找对人了。', `MaleText_loc5`='需要在戰鬥中喘口氣嗎?你來對地方，也找對人了。', `MaleText_loc7`='¿Necesitas un descanso de tus enemigos? Has acudido al lugar idóneo y a la persona idónea.' WHERE `ID`=63690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 내 칼이 어디 갔지?', `MaleText_loc4`='噢……我好像把剑弄丢了。', `MaleText_loc5`='喔...我似乎弄丟我的劍了。', `MaleText_loc7`='Vaya... Creo que he perdido la espada.' WHERE `ID`=63691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세계의 분리가 아제로스의 대륙을 찢어 놓았을 때, 우리 판다렌은 세계의 다른 부분이 모두 파괴됐을 거라고 생각했지.', `MaleText_loc4`='当分裂之力将艾泽拉斯大陆撕扯开来时，我们熊猫人以为世界其它地区都遭到了彻底毁灭。', `MaleText_loc5`='當大爆炸將艾澤拉斯大陸撕裂時，我們熊貓人認為世界的其他地方已被徹底摧毀。', `MaleText_loc7`='Cuando el Gran Cataclismo quebró los continentes de Azeroth, los pandaren creímos que el resto del mundo había desaparecido.' WHERE `ID`=63692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 수백 년이 흐르고, 한 젊은 모험가가 바깥 세상을 돌아보기로 결심했네. 리우 랑이라는 이 청년은... 거북이 등을 타고 세계를 향해 떠났어!', `MaleText_loc4`='然而在几个世纪之后，有位名叫刘浪的年轻探险家决定出去看看。他开始了对世界的探索……而他骑的竟是一只海龟！', `MaleText_loc5`='但過了幾世紀之後，有個年輕的冒險家決定去探索外面的世界。他的名字叫做劉浪。而他就這樣乘著海龜啟程了。', `MaleText_loc7`='Pero unos siglos más tarde, un joven explorador decidió averiguar qué había ahí fuera. Se llamaba Liu Lang y partió para descubrir el mundo... ¡sobre el caparazón de una tortuga!' WHERE `ID`=63693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 조각상과 노래로 그 용기를 기리고 있네. 하지만 자네도 그가 떠나던 모습을 지켜봤다면, 음, 꽤나 바보 같아 보인다고 생각했을 걸세.', `MaleText_loc4`='我们用雕像和歌谣赞美他的英勇气魄，可如果你在他出海的那天守在岸边——我相信，你会觉得他当时的样子傻得很。', `MaleText_loc5`='我們用雕像與歌曲來讚美他的勇氣，但如果你真的有在海邊參與那個大日子...嗯，我很肯定，他看起來一定很蠢。', `MaleText_loc7`='Celebramos su valentía con estatuas y canciones, pero si hubieras estado en la playa aquel día... Seguro que parecía bastante ridículo.' WHERE `ID`=63694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허허, 판다렌들이 얼마나 비웃었던지. 하지만 리우 랑은 생각보다 훨씬 영리했어. 바다 거북은 언제나 자기가 태어난 고향 해안으로 돌아오거든. 그래서 이 땅이 안개에 싸여 있을 때에도, 그는 돌아올 수 있었지.', `MaleText_loc4`='噢，那些熊猫人不遗余力地嘲笑他。可是刘浪比人们想象得要聪明。海龟总能回到自己出生的岸边。于是，尽管迷雾笼罩着我们的土地，刘浪总能安然返家。', `MaleText_loc5`='喔，熊貓人是如何地嘲笑著他。但劉浪比任何人想的都要聰明。海龜要下蛋時一定會回到海邊。因此，即使我們的土地被霧氣籠罩，牠總是可以找到回家的路。', `MaleText_loc7`='Ah, como se rieron de él. Pero Liu Lang era más listo de lo que parecía. Las tortugas marinas siempre vuelven a la playa en la que nacieron. Por eso, a pesar de la niebla que nos rodea, siempre volvía a casa.' WHERE `ID`=63695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리우 랑은 몇 년에 한 번씩 돌아와서는, 모래 위의 신비한 도시와 끝없는 초원에 사는 유목민들, 얼음 아래 묻힌 거대한 제국과 황금으로 덮인 마법 왕국에 대한 이야기를 들려줬지.', `MaleText_loc4`='他每隔几年便回来——讲述旅途中的奇遇：沙漠中的神秘城市，无边草原上的游牧民族，寒冰之下的伟大帝国，还有黄金镀成的神奇王国。', `MaleText_loc5`='每隔幾年他就會回來，帶著許多故事，像是沙灘上的神秘城市，遊牧民族生活在一望無際的綠色平原，冰層下的偉大帝國，還有一個鑲著黃金的魔法王國。', `MaleText_loc7`='Regresaba cada pocos años con historias de misteriosas ciudades en la arena, pueblos nómadas en verdes praderas, un gran imperio bajo el hielo y un reino mágico ribeteado de oro...' WHERE `ID`=63696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 돌아올 때마다, 더 많은 판다렌들이 그를 따라서 점점 자라나는 거북이 등에 올랐네. 우리 중 가장 용감한 친구들이었지. 탐험가들이자, 모험가들이었어.', `MaleText_loc4`='他每次回来，都有更多的熊猫人响应刘浪的召唤，爬到那日渐拥挤的龟背上，与他同行。他们是勇敢的探险家，是冒险王。', `MaleText_loc5`='每次他回來，就有更多的熊貓人響應劉浪的召喚，一起坐到那隻越長越大的海龜背上。他們是我們之中最勇敢的人，是探險家，冒險者。', `MaleText_loc7`='Cada vez que volvía, más y más pandaren respondían a la llamada de Liu Lang y se subían a su tortuga cada vez más grande. Eran los más valientes de entre nosotros: los exploradores, los aventureros.' WHERE `ID`=63697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 리우 랑의 교훈이네, 친구. 모험가는 모두의 비웃음을 사지만, 돌아올 때면 모든 것이 달라지네.', `MaleText_loc4`='那就是刘浪给我们的启示，朋友。人们总爱嘲笑探险家。他们笑啊，笑啊……等他回来就不笑了。', `MaleText_loc5`='這就是劉浪給我們的啟示，朋友。每個人總會嘲笑那個探險者。他們笑個不停...直到他回來。', `MaleText_loc7`='Esa es la lección de Liu Lang, amigo mío: todo el mundo se ríe del explorador. Siempre se ríen... hasta que vuelve.' WHERE `ID`=63698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 사건도 그 시작은 미천한 일이 많지. 잔잔한 호수를 상상해 보게. 고요하고, 마치 거울 같은 호수라네.', `MaleText_loc4`='于无声之处起波澜。比如说，一个宁静的池塘。水面平滑如镜。', `MaleText_loc5`='偉大的事件往往有著卑微的開端。試想一下:一個安靜的池塘。平靜。水面就像玻璃帷幕一樣。', `MaleText_loc7`='A menudo los grandes acontecimientos tienen comienzos humildes. Piensa en un estanque tranquilo. El agua parece de cristal.' WHERE `ID`=63699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 돌을 던지네. 작은 일이지만, 곧 물결이 호수 전체를 뒤덮겠지!', `MaleText_loc4`='直到我丢进一块石子。如此微不足道——但瞬间，涟漪就会袭遍整个水面！', `MaleText_loc5`='直到我丟了一顆石頭下去。這麼一個小東西。但很快，漣漪就會擴散到整個湖面!', `MaleText_loc7`='Hasta que lanzo una piedra. Es muy pequeña, pero pronto las ondas cubren todo el lago.' WHERE `ID`=63700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위의 시작도 미천했네. 원시 생물이었던 진위는 운 좋게 골짜기의 마력 깃든 호수 옆에 터를 잡았지.', `MaleText_loc4`='锦鱼人也有着卑微的出身。本来只是一种原始生物，但有幸能生长在谷内含有魔法的池塘附近。', `MaleText_loc5`='錦魚人也有著卑微的出身。他們曾是未開化的生物，但他們夠幸運，住在山谷中具有魔法的池水附近。', `MaleText_loc7`='Los jinyu también son de origen humilde. Antes eran criaturas primitivas, pero tuvieron la suerte de vivir cerca de los pozos encantados del valle.' WHERE `ID`=63701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호수의 마법이 그들의 몸과 마음을 성장시켰네. 그렇게 진위는 판다리아의 위대한 고대 문명 중 하나가 되었지.', `MaleText_loc4`='池塘的魔力滋养着他们的心智、壮大着他们的躯体，把他们变成了潘达利亚最伟大的古老生物之一。', `MaleText_loc5`='池子的魔法開啟了他們的心智，並讓他們的身體成長，直到他們成為潘達利亞最偉大的古代生物之一。', `MaleText_loc7`='La magia de los pozos les expandió la mente y les desarrolló el cuerpo, hasta que se convirtieron en una de las mayores culturas de Pandaria.' WHERE `ID`=63702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위 중 가장 현명한 이들은, 마치 우리가 장로들과 이야기를 나누는 것처럼 강물과 대화를 할 수 있다네.', `MaleText_loc4`='锦鱼人中的智者确实非常睿智——他们与河流交流的方式，只有我族的长者才能知晓一二。', `MaleText_loc5`='最聰明的錦魚人真的非常非常聰明，他們可以跟河流對話，就像你我徵詢我們長輩的意見一樣。', `MaleText_loc7`='Los jinyu más sabios son extremadamente sabios. Hablan con los ríos como tú y yo hablamos con los ancestros.' WHERE `ID`=63703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속삭이는 물소리에서 미래의 이야기를 듣지.', `MaleText_loc4`='在水流的低语声中，他们能听见未来。', `MaleText_loc5`='在水的低語中，他們可以聽見未來。', `MaleText_loc7`='Cuando las aguas susurran, se puede oír el futuro.' WHERE `ID`=63704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위와 물예언자들은 판다리아의 역사에서 중요한 사건들의 중심에 서 있네.', `MaleText_loc4`='锦鱼人水语者们，在潘达利亚历史上的重要事件中，都扮演着核心角色。', `MaleText_loc5`='錦魚人跟他們的水語者，在潘達利亞歷史中的重大事件，總是居於核心地位。', `MaleText_loc7`='Los jinyu y sus oradores del agua han participado en los mayores acontecimientos de la historia de Pandaria.' WHERE `ID`=63705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 예언이 제국을 세웠고, 노예를 해방시켰고, 일만 년 전 아제로스를 파괴한 세계의 분리에 대해, 마지막 황제께 경고했었지.', `MaleText_loc4`='他们的真知灼见筑起了帝国，解救了奴隶，还在一万年前艾泽拉斯大分裂来临之前，向末代皇帝发出了警告。', `MaleText_loc5`='他們透過預知幻象協助帝國建立、釋放了奴隸，並早在一萬年前就警告末代皇帝:大爆炸將降臨並撕裂艾澤拉斯。', `MaleText_loc7`='Sus visiones han levantado imperios, liberado esclavos y advertido a nuestro último emperador del Gran Cataclismo que devastó Azeroth hace diez mil años.' WHERE `ID`=63706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 보게. 작디작은 목소리가 세계를 바꾼다네. 다음에 돌을 던질 일이 있을 때는, 이 이야기를 떠올려 보게!', `MaleText_loc4`='想想看——哪怕是最微弱的声音也能改变世界。下次当你决定掷出石子时，考虑一下吧，朋友。', `MaleText_loc5`='想想看:最微小的聲音可以改變整個世界。下次你決定開始丟石頭時，考慮到這一點，朋友!', `MaleText_loc7`='Piénsalo bien: hasta la voz más pequeña puede cambiar el mundo. ¡Tenlo en cuenta la próxima vez que decidas lanzar piedras!' WHERE `ID`=63707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그래, 사마귀에 대해 알고 싶다고? 조심하게. 판다렌의 국경에는 호기심 많은 아이들의 무덤이 즐비하니까.', `MaleText_loc4`='噢，我的弟子——你想要了解螳螂妖？我提醒你，边境前线上到处都是我原先弟子的坟冢。', `MaleText_loc5`='喔，我的學生啊，你想研究螳螂人?警告你:熊貓人的邊境上到處散落著從前學生的墳墓。', `MaleText_loc7`='Ah, estudiante, ¿quieres saber más sobre los mántides? Te lo advierto: la frontera pandaren está sembrada de tumbas de antiguos pupilos.' WHERE `ID`=63708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀는 가혹한 스승이네.', `MaleText_loc4`='螳螂妖是严酷的老师。', `MaleText_loc5`='螳螂人是嚴厲的老師。', `MaleText_loc7`='Los mántides son maestros intransigentes.' WHERE `ID`=63709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매 세대마다 사마귀는 용의 척추 장벽을 떼지어 공격하네. 놈들이 많은 판다렌을 살해하기 때문에, 우리도 사마귀들을 많이 없앤다네. 하지만 또 다음 세대에 놈들은 다시 쳐들어오지. 왜 이런 짓을 할까?', `MaleText_loc4`='螳螂妖世代都汇集大军涌上蟠龙脊。它们杀死许多熊猫人，于是我们加倍奉还。可它们的后代又会卷土重来。为何要如此？', `MaleText_loc5`='每個世代，總有數量龐大的螳螂人攻擊蟠龍脊的城牆。他們殺了許多熊貓人，所以我們也多次削減他們的數量做為回報。然而每個世代，他們都會再來攻擊一次。為什麼他們要這樣做?', `MaleText_loc7`='Cada generación los mántides arrasan el Espinazo del Dragón en gran número. Matan a muchos pandaren, así que respondemos matando a muchos mántides. Pero cada generación vuelven a atacar. ¿Por qué lo hacen?' WHERE `ID`=63710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 판다렌도 모른다네.', `MaleText_loc4`='我们熊猫人不知道。', `MaleText_loc5`='我們熊貓人不知道答案。', `MaleText_loc7`='Los pandaren no lo sabemos.' WHERE `ID`=63711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 기록을 살펴보면 사마귀는 항상 여기 있었다네. 모구가 이곳을 지배하기도 전부터지. 대체 어디서 왔을까?', `MaleText_loc4`='古书上说，螳螂妖一直都在这里。它们甚至比魔古族出现得还要早。它们是哪儿来的？', `MaleText_loc5`='我們的古代文獻指出，螳螂人始終都在那裡。他們的起源甚至早於魔古。他們是從哪裡來的?', `MaleText_loc7`='Nuestros escritos antiguos indican que los mántides siempre han estado aquí. Son anteriores incluso a los mogu. ¿De dónde vienen?' WHERE `ID`=63712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 판다렌도 모른다네.', `MaleText_loc4`='我们熊猫人不知道。', `MaleText_loc5`='我們熊貓人不知道答案。', `MaleText_loc7`='Los pandaren no lo sabemos.' WHERE `ID`=63713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면... 자네가 사마귀의 친구가 될 수 있다면, 그들이 그 비밀이 뭔지 알려줄 수도 있겠지. 하지만 이 점은 기억하게.', `MaleText_loc4`='如果你能和螳螂妖交上朋友，赢取了信任，那他们会告诉你螳螂妖的秘密。可我提醒你：', `MaleText_loc5`='或許，假如你跟螳螂人做朋友，並在他們之中贏得名望，他們就會把他們的秘密傳授給你。但我警告你:', `MaleText_loc7`='A lo mejor, si logras conseguir la amistad de los mántides, ganarte una reputación entre ellos, te contarían sus secretos. Pero te lo advierto:' WHERE `ID`=63714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀의 친구가 된 이는 아무도 없었네.', `MaleText_loc4`='从来没人和螳螂妖交过朋友。', `MaleText_loc5`='從來沒有人能跟螳螂人交朋友。', `MaleText_loc7`='Nadie ha conseguido la amistad de los mántides.' WHERE `ID`=63715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 아는 건 하나뿐이네. 사마귀들이 여러 세대에 걸쳐 수만 명의 판다렌을 학살하는 동안, 우리는 삶의 가치를 배웠네. 소중하지만 연약한 선물, 한 순간에 손쉽게 꺼지는... 그런 삶...', `MaleText_loc4`='我们熊猫人只知道——螳螂妖屠杀我们的族人，一代又一代地杀害了无数的熊猫人，它们让我们懂得了生命的价值。人生苦短，稍纵即逝，一不留神……灰飞烟灭。', `MaleText_loc5`='我們熊貓人所知道的是: 藉由殘殺我們的人民，藉由屠殺成千上萬的熊貓人，如此一代又一代，他們教導了我們生命的價值。生命是珍貴而又稍縱即逝的禮物。輕易地在一瞬間熄滅。', `MaleText_loc7`='Lo que sí sabemos los pandaren es que, al masacrar a nuestra gente, al matar a decenas de miles de pandaren, generación tras generación, nos han enseñado a valorar la vida. Es un regalo valioso, pero efímero, que se puede extinguir... en un instante.' WHERE `ID`=63716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그걸 사마귀가 우리에게 가르쳐줬네.', `MaleText_loc4`='这就是螳螂妖教会我们的东西。', `MaleText_loc5`='螳螂人教了我們這一點。', `MaleText_loc7`='Eso es lo que nos han enseñado los mántides.' WHERE `ID`=63717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 이 세계에서 무엇이 가장 두렵나? 두려움을 이겨냈나? 아니면 두려움이 자네를 이겼나?', `MaleText_loc4`='你在这个世界上最怕什么？你是否能战胜恐惧，还是被恐惧征服？', `MaleText_loc5`='你在世界上最害怕的是什麼?你是否征服了你的恐懼...還是你的恐懼征服了你?', `MaleText_loc7`='¿Qué es lo que más temes en el mundo? ¿Has dominado tu miedo... o tu miedo te ha dominado a ti?' WHERE `ID`=63718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 오래 전, 세계가 분리되기 전에 모구 황제들이 판다리아를 지배했네. 우리는 노예가 되었고, 두려움에 사로잡혔지.', `MaleText_loc4`='在世界崩裂之前的古老时代，魔古族皇帝统治着潘达利亚。我们的族人被当成奴隶，而且畏惧不已。', `MaleText_loc5`='在大爆炸尚未發生前的古代，魔古皇帝統治著整個潘達利亞。我們人民被當做奴隸，而且他們非常恐懼。', `MaleText_loc7`='En la antigüedad, antes del Gran Cataclismo, los emperadores mogu dominaban Pandaria. Mi pueblo estaba esclavizado y tenía miedo.' WHERE `ID`=63719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 고통과 고문, 그리고 어둠의 마법과 잔인한 무기들의 달인이었네. 판다렌, 호젠, 진위, 그 누구도 그들의 힘을 거역할 수 없었어. 우리는 두려웠네.', `MaleText_loc4`='魔古族是痛苦与折磨的高手，还精于使用黑暗魔法和恐怖武器。任何熊猫人、猢狲和锦鱼人都无力与之对抗。恐惧笼罩着熊猫人。', `MaleText_loc5`='魔古擅長以黑魔法和殘酷的武器，給予人們痛苦與折磨。沒有任何熊貓人、猴人或錦魚人能夠反抗魔古掌控的力量。而我的人民很恐懼。', `MaleText_loc7`='Los mogu eran maestros del dolor y de la tortura, de la magia oscura y de las armas brutales. Ningún pandaren, hozen ni jinyu podía resistirse a su poder. Mi pueblo tenía miedo.' WHERE `ID`=63720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 척추를 세운 건 모구였어. 불쌍한 노예들이 끌려가 용의 척추를 세우고 방어하다가 사마귀의 먹이가 되었지. 우리는 두려웠네.', `MaleText_loc4`='是魔古族建造了蟠龙脊。运气最差的奴隶从事建造和防御工作，充当抵挡螳螂妖的炮灰。我的族人害怕极了。', `MaleText_loc5`='是魔古打造了蟠龍脊。最倒楣的奴隸會被送去加強蟠龍脊的結構與防禦，去當做螳螂人的飼料。而我的人民很恐懼。', `MaleText_loc7`='Fueron los mogu los que construyeron el Espinazo del Dragón. Enviaron a los esclavos más desgraciados a ayudar en su construcción y defensa; carne de cañón. Mi pueblo tenía miedo.' WHERE `ID`=63721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕국이 커지면서, 모구는 골짜기의 비밀을 시험해 보기 시작했네. 살아 있는 육신과 바위로 끔찍한 무기를 만들었어. 우리는 두려웠네.', `MaleText_loc4`='帝国羽翼渐丰，魔古族窥探谷中的秘密，进行实验。他们用活人的血肉和石头造出了可怕的武器。我的族人惶恐不已。', `MaleText_loc5`='隨著帝國擴張，魔古開始利用山谷的秘密泉水來做實驗。他們用活生生的肉體與石頭打造可怕的武器。而我的人民很恐懼。', `MaleText_loc7`='A medida que el imperio crecía, los mogu comenzaron a experimentar con los secretos del valle. Crearon armas vivientes de carne y piedra. Mi pueblo tenía miedo.' WHERE `ID`=63722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자만심에 빠져, 모구는 자신들을 몰락시키는 것이 적이 아니라 자신들에게 억눌린 자들이라는 사실을 알지 못했네. 한 노예가 일어서는 날...', `MaleText_loc4`='而狂妄的魔古族万万没想到，最后推翻它们统治的，并非敌人，而是受压迫的民众。没想到会有一天，奴隶会挺身而起……', `MaleText_loc5`='由於他們的傲慢，魔古從沒預見到使他們垮台的，並不是敵人，而是那些被壓迫者。當奴隸站起來的那天...', `MaleText_loc7`='En su orgullo, los mogu nunca imaginaron que su perdición no vendría de sus enemigos, sino de sus víctimas. Un día un esclavo se alzó…' WHERE `ID`=63723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 우리는 두렵지 않았네.', `MaleText_loc4`='……并且不再畏惧。', `MaleText_loc5`='...他們再也不會恐懼。', `MaleText_loc7`='...y dejó de tener miedo.' WHERE `ID`=63724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불! 가장 신비한 원소야. 우릴 따뜻하게 하고, 음식을 요리하고, 난로 불은 집을 가정으로 바꿔 놓지. 불이 선한 손에 들어간다면 철을 검과 쟁기로 바꾸지만, 통제를 벗어나면 도시를 파괴해버린다네.', `MaleText_loc4`='火是最有魔力的元素。它能带来温暖，烹制食物。是它把一座房屋变成了一个家。如果善加利用，火能把钢铁铸成刀剑或犁头。但若放任不管，大火也能烧毁整座城市。', `MaleText_loc5`='火!它是最神奇的元素。它溫暖我們，它烹煮我們的食物。它是讓房子成為家的爐火。正確的使用它，火焰可以將鐵塑造成劍或鋤頭。若失去控制，火焰可以摧毀一整座城市。', `MaleText_loc7`='¡El fuego! Es el elemento más mágico. Nos calienta y cocina nuestra comida. Es el fuego lo que hace de una casa, un hogar. En las manos adecuadas, el fuego puede convertir el hierro en espadas o en arados. Sin control, el fuego puede destruir una ciudad.' WHERE `ID`=63725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불은 변화의 도구라네.', `MaleText_loc4`='火是变化的工具。', `MaleText_loc5`='火，是用來改變的工具。', `MaleText_loc7`='El fuego es el instrumento del cambio.' WHERE `ID`=63726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 전, 건장한 유목민 사냥꾼들이 세계를 떠돌았네. 무슨 운명의 장난인지, 그들은 세계의 분리가 아제로스의 대륙을 조각냈을 때, 이곳 판다리아에 있었어. 이 방랑자들은 거칠고 위험한 땅, 탕랑 평원에 갇히고 말았네.', `MaleText_loc4`='很久以前，一群强健的游牧猎手在世界各处游荡。命运和他们开了个玩笑——在艾泽拉斯大分裂发生时，他们刚好来到潘达利亚。这群游荡者被困在了螳螂高原这片荒芜而危险的土地。', `MaleText_loc5`='很久以前，有一群游牧獵人在世界四處漫遊。由於命運的捉弄，大爆炸劈開艾澤拉斯大陸時，他們剛好在潘達利亞。這些流浪者發現他們被困在螳螂荒原，一片荒蕪而危險的土地。', `MaleText_loc7`='Hace mucho tiempo, un grupo de cazadores nómadas exploraba el mundo. Por fortuna, se encontraban en Pandaria cuando el Gran Cataclismo dividió los continentes de Azeroth. Los exploradores quedaron atrapados en las Estepas de Tong Long, una tierra desolada y peligrosa.' WHERE `ID`=63727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 고귀한 사냥꾼들은 스스로 살아남는 법을 찾았네. 불이 그 열쇠였지. 땅 속에서 기름을 끌어올려 집을 덥히고, 음식을 요리하고, 적을 불태웠지. 그들은 강해졌어.', `MaleText_loc4`='那些高尚的猎手想出了自给自足的办法。其中火是关键。他们从地下掘油，用火来温暖房屋，烧饭做菜，烧灼敌人。他们变得强大起来了。', `MaleText_loc5`='那些高貴的獵人自己發現了生存之道。火就是關鍵。他們把油從地底下抽上來。他們使用這些油讓家裡溫暖，烹煮食物，並燒死敵人。他們越來越強大。', `MaleText_loc7`='Los nobles cazadores consiguieron sobrevivir solos. El fuego fue la clave. Extrajeron petróleo del suelo. Lo utilizaron para calentar sus hogares, cocinar su comida y quemar a sus enemigos. Se hicieron fuertes.' WHERE `ID`=63728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명의 불길에서 야운골이 태어났네. 자신들 외에는 어떤 법에도 따르지 않았기에, 장벽 너머에서도 살아남았어.', `MaleText_loc4`='命运之火熊熊燃烧，野牛人诞生了。他们定居在长城之外，拒绝臣服于除自己之外的任何律法。', `MaleText_loc5`='從命運的火焰中，揚古誕生了。他們在城牆的另一側生活，因為除了自己，他們拒絕遵守任何法律。', `MaleText_loc7`='De las llamas del destino nacieron los yaungol. Sobreviven al otro lado de la muralla porque se niegan a someterse a ninguna ley ajena.' WHERE `ID`=63729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명이 야운골에게 가혹했을까? 불이 선한지 악한지 물어보는 것과 같네.', `MaleText_loc4`='命运对野牛人是否不公？这就等于是问火究竟是好还是坏。', `MaleText_loc5`='命運對揚古很殘酷嗎?這就像你會問火是好或是壞。', `MaleText_loc7`='¿Ha sido cruel el destino con los yaungol? Es igual que preguntar si el fuego es bueno o malo.' WHERE `ID`=63730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명은 불과 같지. 우릴 만들 수도, 부술 수도 있어.', `MaleText_loc4`='命运就像火焰——既能塑造我们，也能毁灭我们。', `MaleText_loc5`='命運就像火焰;它可以塑造我們，也可以摧毀我們。', `MaleText_loc7`='El destino es como el fuego: nos forma o nos destruye.' WHERE `ID`=63731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중요한 건 그걸로 뭘 하느냐는 거네.', `MaleText_loc4`='关键在于，你如何利用它。', `MaleText_loc5`='重要的是你如何使用它。', `MaleText_loc7`='Lo único que importa es lo que haces con él.' WHERE `ID`=63732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 가장 위대했던 마지막 황제, 샤오하오 님에 대해 알고 싶다고? 그의 모험을 모두 들려줄 시간은 없지만, 일만 년 전 그분의 행동이 지금까지도 이 세계를 움직이고 있다네.', `MaleText_loc4`='啊！你想打听我们最伟大的末代帝王少昊？朋友，我可没时间陪你追溯他一生中的冒险奇遇，可他在万年以前采取的行动，直到今天仍然影响深远。', `MaleText_loc5`='啊!你想學習關於我們最後也最偉大的皇帝，紹昊的事嗎?我的朋友，我沒有時間在這裡敘述他所有的冒險故事，但他在一萬年前的所做所為，時至今日仍然影響著我們。', `MaleText_loc7`='¡Ah! ¿Quieres que te hable de nuestro último y más ilustre emperador, Shaohao? No tengo tiempo para contarte todas sus aventuras, pero sus actos de hace más de diez mil años siguen teniendo impacto hoy en día.' WHERE `ID`=63733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분은 비취 숲에서 마음 속 의심을 내버렸지. 크라사랑 밀림에서는 절망을 벗어냈고, 탕랑 평원에서는 공포를 극복했어. 쿤라이의 높은 봉우리에서는 분노와 증오, 폭력을 상대로 승리했네.', `MaleText_loc4`='我们知道，他在翡翠林中荡除了自己的疑虑，在卡桑琅丛林里消除了自己的绝望，在螳螂高原上战胜了自己的恐惧，在昆莱山的巅峰击败了自己的愤怒、仇恨和暴力。', `MaleText_loc5`='我們知道他在翠玉林中清除了他的疑慮。他在喀撒朗蠻荒中淨化了他的絕望。他在螳螂荒原克服了他的恐懼。並且，他在崑萊山巔擊敗了憤怒、仇恨與暴力。', `MaleText_loc7`='Sabemos que purgó sus dudas en El Bosque de Jade, que se liberó de la desesperación en la Espesura Krasarang, que superó su miedo en las Estepas de Tong Long y que derrotó a la ira, al odio y a la violencia en lo alto de la Cima Kun-Lai.' WHERE `ID`=63734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 신성한 장소를 기리기 위해 사원도 세웠다네.', `MaleText_loc4`='人们为纪念这些圣地而建造了寺院。', `MaleText_loc5`='這些事蹟都為人所熟知;而且有廟宇紀念這些最神聖的地方。', `MaleText_loc7`='Eso es lo que sabemos. Hay templos que rememoran esos lugares sagrados.' WHERE `ID`=63735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 자네에게 하고 싶은 말은, 여행에서 돌아와 이 골짜기에 선 그분의 마음을 생각해 보라는 거네. 자신을 위해 열린 문 앞에 선 우리 황제님은 의심도, 공포도, 증오도 없는 순수한 빛이었어...', `MaleText_loc4`='但请你想象一下，他归返的那一天，置身于这个山谷中。那一刻，大门为他缓缓开启，我们的皇帝成为了焕发纯净之光的造物——胸中无疑无惧亦无恨……', `MaleText_loc5`='但我希望，你能想像他結束旅程，回來站在這個山谷中的那一天。想像他站在這裡時，大門為他而開。當時，我們的皇帝是身上散發純淨光芒的生物:沒有懷疑，沒有恐懼、沒有仇恨...', `MaleText_loc7`='Pero quiero que te imagines de pie, en este valle, el día en que volvió de su viaje. Imagínate cuando las puertas se abrieron ante él. Para entonces nuestro Emperador era pura luz: sin dudas, sin miedo, sin odio...' WHERE `ID`=63736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그분이 돌아오실 때 골짜기의 나무들이 모두 꽃을 피웠다고 하네. 그 꽃은 지금까지 피어 있고.', `MaleText_loc4`='据说，当时山谷中所有的林木都花开满枝，群芳争艳，一直盛开到今天。', `MaleText_loc5`='據說當他走進山谷時，谷中所有的樹都開花了，並一直綻放到今日。', `MaleText_loc7`='Se dice que todos los árboles del valle florecieron cuando entró y siguen floreciendo hoy.' WHERE `ID`=63737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 모두가 신성했던 황제님처럼 살 수 있다면... 모든 짐을 내려놓고 우주와 조화를 이룰 수 있다면 얼마나 좋겠나. 그것이 바로 그분의 뜻일 거야. 세계의 분리라는 공포로부터 판다리아를 숨겨 주고, 땅과 하나가 되신 황제님의 뜻이라고.', `MaleText_loc4`='但愿我们所有人都能像圣祖皇帝那样生活。像他那样卸下肩头的重担，和宇宙相生共存。我相信，这就是在他化归大地，使潘达利亚免受灾变侵袭之前……想要传达给我们的。', `MaleText_loc5`='希望我們都能像我們最神聖的帝王那樣活著。我們能將所有的負擔放到一邊，並與宇宙和諧共存...我相信，在他成為土地的一部分，並將潘達利亞藏起來免於遭受大爆炸的恐怖之前，這就是他傳遞給我們的訊息。', `MaleText_loc7`='Ojalá pudiéramos vivir como nuestro Emperador sagrado. Ojalá pudiéramos apartar nuestras cargas y existir en armonía con el cosmos. Creo que ese era su mensaje... antes de convertirse en uno con la tierra y apartar Pandaria del terror del Gran Cataclismo.' WHERE `ID`=63738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 황제님.', `MaleText_loc4`='谢谢你，尊敬的皇帝陛下。', `MaleText_loc5`='謝謝你，親愛的皇帝。', `MaleText_loc7`='Gracias, querido Emperador.' WHERE `ID`=63739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느날, 어린 아이의 장난에 지친 한 아버지가 아이를 꾸짖었네. "넌 꼭 호젠처럼 행동하는구나!" 하지만 아이는 여전했지.', `MaleText_loc4`='有一天，一位父亲厌倦了幼子的顽劣。“你简直像只猢狲！”父亲斥责道。可那孩子还是我行我素。', `MaleText_loc5`='有天，一個父親對他年輕孩子的不當行為感到厭倦。父親大罵:「你的行為就像個猴人一樣!」。但是他的兒子還是行為不檢。', `MaleText_loc7`='Un día, un pandaren se cansó de las travesuras de su cachorro. "¡Te comportas como un hozen!", le dijo. Pero su hijo siguió portándose mal.' WHERE `ID`=63740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 아버지는 아이를 숲으로 데려가서 호젠이 사는 모습을 보여줬네. 그리고 물었지. "호젠이 어떤 녀석들인지 알겠지? 저렇게 살고 싶어?"', `MaleText_loc4`='为了教训他，父亲把儿子拽到林子里，让他看看猢狲是如何生活的。“你知道猢狲是什么样了吧？你想像它们那样生活吗？”', `MaleText_loc5`='為了好好給他上一課，這個父親把兒子拖到森林去，看看猴人是怎麼生活的。他問:「你看到猴人是什麼樣子了嗎?你想像這樣過日子嗎?」', `MaleText_loc7`='Para darle una lección, el padre llevó al cachorro al bosque para ver cómo vivían los hozen. "¿Ves cómo son?", le preguntó. "¿Quieres vivir como ellos?".' WHERE `ID`=63741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 정말 생기 넘치는 종족이네. 수명이 길지 않아서 스무 살을 넘기는 일이 별로 없지. 족장이라고 해도 열 넷이나 열 다섯이야. 열 네 살짜리가 얼마나 성숙하겠나? 한번 생각해 보게!', `MaleText_loc4`='猢狲很是活泼好动。可那是个短命的种族，很少有猢狲能活过二十岁。它们的领袖也只是十四或十五岁。你十四岁时有多成熟？好好想想吧！', `MaleText_loc5`='猴人的確精神非常旺盛。他們是個短命的種族，只有少數猴人能活過20歲生日。他們的首領都是14或15歲。你14歲的時候能有多成熟?想想吧!', `MaleText_loc7`='Los hozen son muy vivaces. Es una raza poco longeva; la mayoría no pasan de los 20 años. Sus líderes tienen 14 ó 15. ¿Cómo eras cuando tenías 14 años? ¡Medita sobre eso!' WHERE `ID`=63742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후에, 아버지가 아이에게 뭘 배웠냐고 물었지.', `MaleText_loc4`='然后，父亲问儿子学到了什么。', `MaleText_loc5`='後來，那個父親問他的孩子學到了什麼。', `MaleText_loc7`='Más tarde, el padre le preguntó a su cachorro lo que había aprendido.' WHERE `ID`=63743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이가 답했네. "우린 작은 밭에서 힘들게 일하지만, 호젠은 온 세계를 자신들의 밭으로 삼고 있어요. 우린 촛불 하나를 켜고 감사하며 살지만, 호젠은 별빛을 한껏 즐기며 살아요. 그리고 전 매일 학교에 가지만, 호젠은 행동을 하며 스스로 깨닫는다는 걸 배웠어요."', `MaleText_loc4`='儿子答道：“我学到的是，我们终日在那一亩三分地上劳作，可猢狲却把整个世界当成自己的花园。我们以寥落的烛光照明，可猢狲却能尽享漫天星光。我每天都要上学读书，可猢狲却在实践中掌握本领。”', `MaleText_loc5`='孩子說:「我學到，我們在小農場上辛苦工作，但對猴人來說，整個世界就像是他們的花園;我學到，我們藉著燭光斜斜地往外看，但猴人享受星星的光芒;我學到，我們每天要去上學，但猴人邊做邊學。」', `MaleText_loc7`='"He aprendido que trabajamos y aramos en nuestra pequeña granja, pero que los hozen tienen todo el mundo a su disposición", dijo el cachorro. "He aprendido que parpadeamos ante la luz de una vela, pero que los hozen disfrutan de las estrellas. He aprendido que voy a la escuela, pero que los hozen aprenden haciendo".' WHERE `ID`=63744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 아이는 마지막으로 이렇게 말했지. "호젠처럼 살겠어요!"', `MaleText_loc4`='最后儿子总结道，“我还是乐得做只猢狲！”', `MaleText_loc5`='然後孩子總結說:「我應該非常喜歡活的像個猴人!」', `MaleText_loc7`='Y el cachorro concluyó: "¡Me gustaría mucho vivir como un hozen!".' WHERE `ID`=63745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 더 현명한 걸까? 아버지일까, 아이일까?', `MaleText_loc4`='那么是谁更聪明？是父亲，还是儿子？', `MaleText_loc5`='那麼，誰才是比較聰明的那個呢?父親還是孩子?', `MaleText_loc7`='¿Quién era más sabio? ¿El padre o el cachorro?' WHERE `ID`=63746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 그건 자네가 결정할 문제네.', `MaleText_loc4`='这个问题就要让你自己去回答了。', `MaleText_loc5`='朋友，這件事，由你決定。', `MaleText_loc7`='Eso, estudiante, debes decidirlo tú.' WHERE `ID`=63747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 누군가가 제게 도전한지도 꽤 됐지요.', `MaleText_loc4`='已经很久没人敢挑战我了。', `MaleText_loc5`='已經有很長一段時間沒有碰到膽子大到敢來挑戰我的人了。', `MaleText_loc7`='Hace mucho tiempo que nadie tiene el valor de desafiarme.' WHERE `ID`=63748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 투기장에서 봅시다.', `MaleText_loc4`='竞技场上见。', `MaleText_loc5`='我們擂台上見。', `MaleText_loc7`='Te veré en el cuadrilátero.' WHERE `ID`=63749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 봐 주지 마십시오.', `MaleText_loc4`='全力以赴。', `MaleText_loc5`='放馬過來吧。', `MaleText_loc7`='No te contengas.' WHERE `ID`=63750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 잘 싸우셨습니다. 계속하십시오.', `MaleText_loc4`='打得很好！再接再厉。', `MaleText_loc5`='身手還不差嘛!別停呀。', `MaleText_loc7`='¡Luchas bien! No pares ahora.' WHERE `ID`=63751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐어어어야?! 안 돼애애애!', `MaleText_loc4`='白羽？！不——！', `MaleText_loc5`='白羽?!不!!!!', `MaleText_loc7`='¡¿Plumablanca?! ¡Nooo!' WHERE `ID`=63752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헉헉... 저를... 넘어섰군요...', `MaleText_loc4`='你……把我……打败了……', `MaleText_loc5`='你...已經...超越我了...', `MaleText_loc7`='Me... has... vencido...' WHERE `ID`=63753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감동받았습니다. 옆에서 함께 싸운다면 영광일 겁니다.', `MaleText_loc4`='你可真不简单。能与你并肩战斗是我的荣幸。', `MaleText_loc5`='你的身手確實不凡。能和你並肩作戰是我的榮幸。', `MaleText_loc7`='Eres impresionante. Será un honor luchar a tu lado.' WHERE `ID`=63754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칭찬해드리고 싶군요. 제가 이렇게 쉽게 진 것도 참 오랜만이거든요.', `MaleText_loc4`='向你致敬，朋友。我都不记得，上次被别人轻易战胜是什么时候了。', `MaleText_loc5`='朋友，我向你致敬。已經想不起來上次輸這麼慘是什麼時候了。', `MaleText_loc7`='Te felicito, amigo. No recuerdo la última vez que alguien me derrotó con tanta destreza.' WHERE `ID`=63755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니우짜오... 그를 구해야만 합니다!', `MaleText_loc4`='砮皂……我们必须得救他！', `MaleText_loc5`='怒兆...我們必須拯救祂!', `MaleText_loc7`='Niuzao... ¡hay que salvarlo!' WHERE `ID`=63756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 갑시다.', `MaleText_loc4`='好。我们走吧。', `MaleText_loc5`='好了。走吧。', `MaleText_loc7`='Bien. Vamos.', `FemaleText_loc1`='좋아요. 가지요.', `FemaleText_loc4`='好。我们走吧。', `FemaleText_loc5`='好了。走吧。', `FemaleText_loc7`='Bien. Vamos.' WHERE `ID`=63757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하! 위대한 니우짜오. 서쪽의 강자. 성스러운 천신이자 약자들의 수호자.', `MaleText_loc4`='啊哈哈，伟大的砮皂。西方之力。神圣之神。弱者的保护神。', `MaleText_loc5`='哈哈哈哈，偉大的怒兆，鎮守西方的神獸，弱者的保護者..', `MaleText_loc7`='Ja, ja, ja, el gran Niuzao. La fuerza del oeste. La divinidad celestial. El protector de los débiles.' WHERE `ID`=63758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 있던 공포의 샤가 도망쳤군!', `MaleText_loc4`='你的囚犯，惧之煞，已经跑了。', `MaleText_loc5`='你負責鎮守的恐懼之煞已經逃走。', `MaleText_loc7`='Tu prisionero, el Sha del miedo, ha huido.' WHERE `ID`=63759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 신의 힘을 휘둘렀지만, 패하고 말았군!', `MaleText_loc4`='你掌握着神的力量，可你却被打败了！', `MaleText_loc5`='你擁有神的力量，但是你卻被擊敗了!', `MaleText_loc7`='¡Disfrutas de los poderes de un dios, pero te han derrotado!' WHERE `ID`=63760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신의 책무는 감내하기 힘들지.', `MaleText_loc4`='神灵的责任显然太过沉重。', `MaleText_loc5`='看來，當神真的很累啊。', `MaleText_loc7`='El manto de un dios debe ser muy pesado.' WHERE `ID`=63761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의무를 내려놓고 안식을 취해라.', `MaleText_loc4`='卸下你的责任，安息吧。', `MaleText_loc5`='放下擔子，好好休息吧。', `MaleText_loc7`='Deja tu deber a un lado y descansa.' WHERE `ID`=63762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 그 어깨에 지워진 모든 이의 짐을 버텨냈지. 그런데 그자들은 네게 어떻게 했나?', `MaleText_loc4`='你用双肩苦苦挑起了整个民族的负担。而他们是怎么回报你的呢？', `MaleText_loc5`='你一肩擔起了所有人的安危，結果他們卻是怎樣回報你的?', `MaleText_loc7`='Llevas el peso de todo un pueblo a tus espaldas. ¿Y cómo te lo han pagado?' WHERE `ID`=63763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 고맙다는 말도 없는 이들을 위해 묵묵히 고통을 겪지.', `MaleText_loc4`='你默默地为一群不知感激的人承受着痛苦。', `MaleText_loc5`='為了這群不知感激的東西，你任勞任怨、默默受苦。', `MaleText_loc7`='Sufres en silencio por un pueblo que no te lo agradece.' WHERE `ID`=63764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 맥주통 던지기 대회에서 6년 연속 우승했습니다! 원하신다면 이 맥주통을 마을 어디에든 던져서 뭐든 맞춰 드리지요! 위치만 가리켜 주십시오. 어떠십니까?', `MaleText_loc4`='我是连续六届投掷美酒大赛的冠军！要是你喜欢，我能让这瓶美酒绕村庄飞上一圈，来个陈酿打击！你要做的只是给我指明目标。要不要试试？', `MaleText_loc5`='六年來，我一直都是丟啤酒大賽的贏家!如果你想，我可以把這啤酒丟出去，一路穿過整個村子，並造成烈酒打擊!你只需要把落點指出來。你覺得如何?', `MaleText_loc7`='He ganado la competición de lanzamiento de cerveza seis años. Si quieres puedo lanzar este brebaje para que atraviese toda la villa y provoque un golpe de brebaje. Solo tienes que apuntar. ¿Te gustaría?', `FemaleText_loc1`='전 맥주통 던지기 대회에서 6년 연속 우승했습니다! 원하신다면 이 맥주통을 마을 어디에든 던져서 뭐든 맞춰 드리지요! 위치만 가리켜 주십시오. 어떠십니까?', `FemaleText_loc4`='我是连续六届投掷美酒大赛的冠军！要是你喜欢，我能让这瓶美酒绕村庄飞上一圈，来个陈酿打击！你要做的只是给我指明目标。要不要试试？', `FemaleText_loc5`='六年來，我一直都是丟啤酒大賽的贏家!如果你想，我可以把這啤酒丟出去，一路穿過整個村子，並造成烈酒打擊!你只需要把落點指出來。你覺得如何?', `FemaleText_loc7`='He ganado la competición de lanzamiento de brebaje seis años. Si quieres puedo lanzar este brebaje para que atraviese toda la villa y provoque un golpe de brebaje. Solo tienes que apuntar. ¿Te gustaría?' WHERE `ID`=63765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다! 보고 싶군요!', `MaleText_loc4`='当然！那再好不过了！', `MaleText_loc5`='當然!我很想看看!', `MaleText_loc7`='¡Por supuesto! ¡Me encantaría verlo!', `FemaleText_loc1`='좋죠! 보고 싶네요!', `FemaleText_loc4`='当然！那再好不过了！', `FemaleText_loc5`='當然!我很想看看!', `FemaleText_loc7`='¡Por supuesto! ¡Me encantaría verlo!' WHERE `ID`=63766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮습니다...', `MaleText_loc4`='不用了，谢谢……', `MaleText_loc5`='不，謝了...', `MaleText_loc7`='No, gracias...', `FemaleText_loc1`='괜찮아요...', `FemaleText_loc4`='不用了，谢谢……', `FemaleText_loc5`='不，謝了...', `FemaleText_loc7`='No, gracias...' WHERE `ID`=63767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 절대로... 굴하지... 않는다!', `MaleText_loc4`='我……绝不……放弃！', `MaleText_loc5`='我絕對不會投降!', `MaleText_loc7`='¡JAMÁS me rendiré!' WHERE `ID`=63768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우두머리 시린이빨 악어가 갓 부화한 시린이빨 악어를 소환합니다.', `MaleText_loc4`='寒噬主母开始召唤寒噬幼雏。', `MaleText_loc5`='冰蝕族母開始召喚冰蝕幼鱷。', `MaleText_loc7`='La matriarca Muerdefrío empieza a invocar proles Muerdefrío.', `FemaleText_loc1`='우두머리 시린이빨 악어가 갓 부화한 시린이빨 악어를 소환합니다.', `FemaleText_loc4`='寒噬主母开始召唤寒噬幼雏。', `FemaleText_loc5`='冰蝕族母開始召喚冰蝕幼鱷。', `FemaleText_loc7`='La matriarca Muerdefrío empieza a invocar proles Muerdefrío.' WHERE `ID`=63769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크가 단상으로 날아갑니다!', `MaleText_loc4`='皇家宰相佐尔洛克朝他其中一个平台飞去了！', `MaleText_loc5`='女皇大臣索拉格飛向他的其中一個露臺!', `MaleText_loc7`='¡El visir imperial Zor''lok vuela hacia una de las plataformas!' WHERE `ID`=63770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t황실 장로 조르로크가 |cFFFF0000|Hspell:122336|h[음파 고리]|h|r를 날려 보냅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t皇家宰相佐尔洛克在整个房间里发送|cFFFF0000|Hspell:122336|h[超声波之环]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t女皇大臣索拉格送出|cFFFF0000|Hspell:122336|h[強音波紋]|h|r穿過整個房間!', `MaleText_loc7`='|TInterfaceIconsability_warrior_battleshout.blp:20|t¡El visir imperial Zor''lok lanza |cFFFF0000|Hspell:122336|h[Anillos sónicos]|h|r por la sala!' WHERE `ID`=63771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t황실 장로 조르로크가 숨을 크게 |cFFFF0000|Hspell:122852|h[들이쉽니다]|h|r!', `MaleText_loc4`='|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t皇家宰相佐尔洛克深深地|cFFFF0000|Hspell:122852|h[吸气]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t女皇大臣索拉格大口|cFFFF0000|Hspell:122852|h[吸氣]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_druid_stamedingroar.blp:20|t¡El visir imperial Zor''lok |cFFFF0000|Hspell:122852|h[Inhala]|h|r gran cantidad de aliento!' WHERE `ID`=63772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t황실 장로 조르로크가 엄청난 기세로 |cFFFF0000$n|r|1을;를; 향해 숨을 |cFFFF0000|Hspell:122761|h[내쉽니다]|h|r!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t皇家宰相佐尔洛克对|cFFFF0000$n|r使劲|cFFFF0000|Hspell:122761|h[吐气]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t女皇大臣索拉格大力向|cFFFF0000$n|r|cFFFF0000|Hspell:122761|h[吐氣]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_psychicscream.blp:20|t¡El visir imperial Zor''lok |cFFFF0000|Hspell:122761|h[Exhala]|h|r con gran fuerza hacia |cFFFF0000$n|r!' WHERE `ID`=63773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\warrior_disruptingshout.blp:20|t황실 장로 조르로크가 |cFFFF0000|Hspell:122713|h[힘과 활력]|h|r을 실어 고함을 내지릅니다!', `MaleText_loc4`='|TInterface\\Icons\\warrior_disruptingshout.blp:20|t皇家宰相佐尔洛克用|cFFFF0000|Hspell:122713|h[力与魄]|h|r进行呼喊！', `MaleText_loc5`='|TInterface\\Icons\\warrior_disruptingshout.blp:20|t女皇大臣索拉格用|cFFFF0000|Hspell:122713|h[力量與氣魄]|h|r大吼!', `MaleText_loc7`='|TInterfaceIconswarrior_disruptingshout.blp:20|t¡El visir imperial Zor''lok grita con |cFFFF0000|Hspell:122713|h[Fuerza y reverberación]|h|r!' WHERE `ID`=63774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\trade_archaeology_delicatemusicbox.blp:20|t황실 장로 조르로크가 |cFFFF0000|Hspell:123791|h[여제의 노래]|h|r를 부릅니다. 조르로크와 전투를 시작하기 전까지 모든 플레이어가 피해를 입습니다.', `MaleText_loc4`='|Tinterface/Icons/trade_archaeology_delicatemusicbox.blp:20|t皇家宰相佐尔洛克吟唱了|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r，对所有玩家造成伤害，直到他们开始和他战斗！', `MaleText_loc5`='|Tinterface/Icons/trade_archaeology_delicatemusicbox.blp:20|t女皇大臣索拉格唱起|cFFFF0000|Hspell:123791|h[女皇之歌]|h|r，對所有玩家造成損害，直到玩家開始與他作戰!', `MaleText_loc7`='|TInterface/Icons/trade_archaeology_delicatemusicbox.blp:20|t¡El visir imperial Zor''lok canta la |cFFFF0000|Hspell:123791|h[Canción de la Emperatriz]|h|r y daña a todos los jugadores hasta que entren en combate con él!' WHERE `ID`=63775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t황실 장로 조르로크가 목소리로 공격대 대원들을 |cFFFF0000|Hspell:122740|h[개종]|h|r시켜 자기 편에서 싸우게 합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t皇家宰相佐尔洛克用他的声音|cFFFF0000|Hspell:122740|h[策反]|h|r团队成员攻击自己的同伴！', `MaleText_loc5`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t女皇大臣索拉格使用他的聲音突擊成員，並將他們|cFFFF0000|Hspell:122740|h[轉換]|h|r成他這邊的人!', `MaleText_loc7`='|TInterfaceIconsspell_arcane_mindmastery.blp:20|t¡El visir imperial Zor''lok usa su voz para |cFFFF0000|Hspell:122740|h[Convertir]|h|r a miembros de la banda para que luchen a su lado!' WHERE `ID`=63776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t바람군주 멜자라크가 |cFFF00000|Hspell:121896|h[소용돌이 칼날]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t风领主梅尔加拉克开始施放|cFFF00000|Hspell:121896|h[回旋之刃]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t風領主瑪爾加拉克開始施放|cFFF00000|Hspell:121896|h[迴旋刀刃]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_bladestorm.blp:20|t¡El señor del viento Mel''jarak empieza a lanzar |cFFF00000|Hspell:121896|h[Hoja giratoria]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t바람군주 멜자라크가 |cFFF00000|Hspell:121896|h[소용돌이 칼날]|h|r을 시전하기 시작합니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t风领主梅尔加拉克开始施放|cFFF00000|Hspell:121896|h[回旋之刃]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\ability_warrior_bladestorm.blp:20|t風領主瑪爾加拉克開始施放|cFFF00000|Hspell:121896|h[迴旋刀刃]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_warrior_bladestorm.blp:20|t¡El señor del viento Mel''jarak empieza a lanzar |cFFF00000|Hspell:121896|h[Hoja giratoria]|h|r!' WHERE `ID`=63779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 대체...?! 이건 계약서가 아니군! 편지가 아닌가. 갑판장 아리에가 손으로 직접 쓴 것 같은데?', `MaleText_loc4`='这是……？！这不是海图！是一封信。是阿林亲笔写的吗？', `MaleText_loc5`='什麼鬼...?!這不是證書!這是一封信。上頭是艾利的筆跡嗎?', `MaleText_loc7`='¡¿Pero qué...?! ¡Esto no es la hoja de ruta! Es una carta. ¿Es la letra de Arie?' WHERE `ID`=63780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"선장님, 지금 이 편지를 읽으신다면, 누군가를 보내 계약서를 찾으려고 했다는 거겠죠. 흠, 그렇지만 너무 늦었답니다."', `MaleText_loc4`='“亲爱的‘闷水壶’，等你看到这封信的时候，说明你终于鼓起勇气派人来寻找旧海图了。可你来得太迟了。”', `MaleText_loc5`='親愛的濕佬，如果你正在讀這封信，那就意味你終於有膽派某人來找這個老證書了。不過，你來晚了。', `MaleText_loc7`='"Querido Aguado: si estás leyendo esto, eso significa que por fin has tenido las agallas de enviar a alguien en busca de la antigua hoja de ruta. Pues bien, llegas demasiado tarde."' WHERE `ID`=63781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"우리는 안개돌이호를 장벽 너머 이렇게 멀리까지 항해하려고 임대하지는 않았다는 것을 알고 있어요. 원래는 비취 숲 앞바다에서 간단한 일만 하도록 되어 있다는 것도 알고 있고요."', `MaleText_loc4`='“我们知道雾海飞跃者并非受雇前往超出长城这么远的地方。我们知道本来只是要在翡翠林海岸上执行日常任务。”', `MaleText_loc5`='我們知道躍霧者並沒有被僱用到要深入長城外這麼遠的地方。我們知道，這本該只是翠玉林海岸外的一個例行公事而已。', `MaleText_loc7`='"Sabemos que no contrataron El Saltanieblas para llegar tan lejos de la muralla. Sabemos que se suponía que iba a ser un trabajo de rutina cerca de la costa de El Bosque de Jade."' WHERE `ID`=63782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"일주일 동안 편안하게 낚시나 하는 줄 알았는데, 우리는 대륙에서 가장 위험한 지역에 좌초되는 엄청난 불운을 겪었고, 또 선장님께서 감만 믿고 뛰어드는 바람에 거의 죽기 일보 직전까지 갔죠."', `MaleText_loc4`='“原本只是历时一个礼拜的轻松捕鱼作业，竟然演变成了一场疯狂的灾难，害我们在这片大陆最危险的地方搁浅，差点让所有人都丢掉性命，这一切都是因为你对直觉的执着追寻。”', `MaleText_loc5`='應該只是輕鬆釣魚的一周，變成狂暴的災難，讓我們擱淺在這片大陸最危險的地方，還幾乎害我們喪命，這都是因為你無法停止追逐你的直覺。', `MaleText_loc7`='"Lo que debía ser una semana de pesca fácil se convirtió en una terrible desgracia que acabó con nuestro naufragio en el lugar más peligroso del continente y casi con la muerte de todos nosotros, todo porque no podías dejar de hacer caso a tus corazonadas."' WHERE `ID`=63783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"우리는 그저 선장님께 고맙다고 말하고 싶어요."', `MaleText_loc4`='“可我们只想说——谢谢你。”', `MaleText_loc5`='我們只想說:謝謝你。', `MaleText_loc7`='"Solo queríamos decirte: Gracias."' WHERE `ID`=63784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"머나먼 수평선에 있는 부를 쫓아 주신 것에 감사하고, 꿈을 꾸게 해주신 것도 감사해요. 그리고 무엇보다도, 지금까지 함께 해주신 것도 고맙고요."', `MaleText_loc4`='“谢谢你远赴遥远的地平线追逐财宝。谢谢你敢于做梦。最重要的是，谢谢你让我们与你同行。”', `MaleText_loc5`='謝謝你追逐遙遠地平線那端的幸運。謝謝你的夢想。最重要的是，謝謝你帶著我們一起。', `MaleText_loc7`='"Gracias por buscar la fortuna en el lejano horizonte. Gracias por soñar. Y sobre todo, gracias por llevarnos contigo."' WHERE `ID`=63785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"우리는 언제나 당신의 선원일 거예요, 선장님. 배가 있던 없건, 우리는 당신이 어딜 가든 그 뒤를 따를게요."', `MaleText_loc4`='“我们永远都是你的船员，‘闷水壶’。有船也好，无船也罢。我们都会追随你到天涯海角。”', `MaleText_loc5`='我們永遠都是你的船員，濕佬。不論有沒有船。我們會跟隨你到天涯海角。', `MaleText_loc7`='"Siempre seremos tu tripulación, Aguado. Con barco o sin él. Te seguiremos donde sea."' WHERE `ID`=63786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"선원 일동 드림. 멍멍이도 같이."', `MaleText_loc4`='“此致，全体船员——和狗。”', `MaleText_loc5`='真摯的，我們所有人。包含小狗。', `MaleText_loc7`='"Atentamente, todos nosotros. Incluido Perro."' WHERE `ID`=63787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야...', `MaleText_loc4`='哇哦……', `MaleText_loc5`='哇喔...', `MaleText_loc7`='Vaya...' WHERE `ID`=63788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 잠깐만 실례해도 되겠습니까? 음... 눈에 뭐가 자꾸 들어가서 그럽니다...', `MaleText_loc4`='失陪一会儿，$p。我，呃……我两只眼睛都进东西了。', `MaleText_loc5`='我能請你先離開一下嗎，$p?我，嗯...我雙眼裡有點東西。', `MaleText_loc7`='¿Me disculpas un momento, $p? Tengo, eh... Tengo algo en los dos ojos.' WHERE `ID`=63789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님, 전방에 얼라이언스 조난 신호입니다.', `MaleText_loc4`='指挥官，在前方发现联盟求救信号。', `MaleText_loc5`='指揮官，從前方收到聯盟的求救信號。', `MaleText_loc7`='Comandante, recibimos una señal de socorro de la Alianza.', `FemaleText_loc1`='사령관님, 전방에 얼라이언스 조난 신호입니다.', `FemaleText_loc4`='指挥官，在前方发现联盟求救信号。', `FemaleText_loc5`='指揮官，從前方收到聯盟的求救信號。', `FemaleText_loc7`='Comandante, recibimos una señal de socorro de la Alianza.' WHERE `ID`=63790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위로!', `MaleText_loc4`='停！', `MaleText_loc5`='拉高機頭!', `MaleText_loc7`='¡Levanten!', `FemaleText_loc1`='위로!', `FemaleText_loc4`='停！', `FemaleText_loc5`='拉高機頭!', `FemaleText_loc7`='¡Levanten!' WHERE `ID`=63791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 공격합니다!', `MaleText_loc4`='他们在朝我们开火，长官！', `MaleText_loc5`='他們對我們開火了，長官!', `MaleText_loc7`='¡Nos disparan, señor!', `FemaleText_loc1`='우릴 공격합니다!', `FemaleText_loc4`='他们在朝我们开火，长官！', `FemaleText_loc5`='他們對我們開火了，長官!', `FemaleText_loc7`='¡Nos disparan, señor!' WHERE `ID`=63792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽! 맞았어요!', `MaleText_loc4`='呃！我们被击中了！', `MaleText_loc5`='呃!我們被擊中了!', `MaleText_loc7`='¡Aah! ¡Nos han dado!', `FemaleText_loc1`='윽! 맞았어요!', `FemaleText_loc4`='呃！我们被击中了！', `FemaleText_loc5`='呃!我們被擊中了!', `FemaleText_loc7`='¡Ah! ¡Nos han dado!' WHERE `ID`=63793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 장비가 먹통이에요! 조종할 수가 없어요!', `MaleText_loc4`='我们的系统失灵了，指挥官！我控制不了这架飞机了！', `MaleText_loc5`='我們的系統都錯亂了，指揮官!我無法控制飛機!', `MaleText_loc7`='¡Los sistemas están bloqueados, Comandante! ¡Estamos perdiendo el control!', `FemaleText_loc1`='비행 장비가 먹통이에요! 조종할 수가 없어요!', `FemaleText_loc4`='我们的系统失灵了，指挥官！我控制不了这架飞机了！', `FemaleText_loc5`='我們的系統都錯亂了，指揮官!我無法控制飛機!', `FemaleText_loc7`='¡Los sistemas están bloqueados, Comandante! ¡No controlo el avión!' WHERE `ID`=63794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐죠? 저건... 육지인가요?', `MaleText_loc4`='什么？那是……陆地吗？', `MaleText_loc5`='什麼?那是...陸地?', `MaleText_loc7`='¿Qué? ¿Eso es... TIERRA?', `FemaleText_loc1`='뭐죠? 저건... 육지인가요?', `FemaleText_loc4`='什么？那是……陆地吗？', `FemaleText_loc5`='什麼?那是...陸地?', `FemaleText_loc7`='¿Qué? ¿Eso es... TIERRA?' WHERE `ID`=63795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 잡아먹으려 하더니 꼴 좋다!', `FemaleText_loc4`='看那些兔妖再敢吃我！', `FemaleText_loc5`='看那些兔妖還敢不敢試著吃我!', `FemaleText_loc7`='¡Así aprenderán esos mures a intentar comerme!' WHERE `ID`=63796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 축제를 시작하기 전에 양조사 부프 님께 곡물을 가져다드려야 해요. 거기서 만나요, $p 님!', `FemaleText_loc4`='我得把粮食交给酒仙，然后我们就能欢庆节日啦！回头见，$p！', `FemaleText_loc5`='我得把這榖物拿給釀酒大師布夫，好讓我們能夠開始節慶。到那裡見囉，$p!', `FemaleText_loc7`='Necesito llevarle este grano al maestro cervecero Boof para que pueda empezar el festival. ¡Nos vemos allí, $p!' WHERE `ID`=63797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날더러 미쳤다고 할지도 모르지만, 난 이곳의 따뜻한 날씨가 좋다오! 북풍의 땅에서는 늘 왕따가 된 기분이었는데, 이곳 날씨는 내게 아주 잘 맞을 것 같소!', `MaleText_loc4`='你就当我疯了吧，我简直爱死这温暖的好天气了！我总觉得自己在苔原时像个流浪儿，可我觉得这新气候真是帮了我大忙！', `MaleText_loc5`='或許我是瘋了，但我愛死這溫暖的天氣了!我在凍原上總是覺得自己被遺棄在那裡，但這種新天氣對我來說棒極了!', `MaleText_loc7`='¡Pensarás que estoy loco, pero me encanta este calor! En la Tundra siempre me sentía fuera de lugar, ¡pero creo que este nuevo clima me vendrá muy bien!', `FemaleText_loc1`='날더러 미쳤다고 할지도 모르지만, 난 이곳의 따뜻한 날씨가 좋아요! 북풍의 땅에서는 늘 왕따가 된 기분이었는데, 이곳 날씨는 내게 아주 잘 맞을 것 같아요!', `FemaleText_loc4`='你就当我疯了吧，我简直爱死这温暖的好天气了！我总觉得自己在苔原时像个流浪儿，可我觉得这新气候真是帮了我大忙！', `FemaleText_loc5`='或許我是瘋了，但我愛死這溫暖的天氣了!我在凍原上總是覺得自己被遺棄在那裡，但這種新天氣對我來說棒極了!', `FemaleText_loc7`='¡Pensarás que estoy loca, pero me encanta este calor! En la Tundra siempre me sentía fuera de lugar, ¡pero creo que este nuevo clima me vendrá muy bien!' WHERE `ID`=63798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향에서 이렇게 먼 곳에서 뭐 하십니까?', `MaleText_loc4`='你在离家这么远的地方干什么呢？', `MaleText_loc5`='你到離家這麼遠的地方來做什麼?', `MaleText_loc7`='¿Qué haces tan lejos de casa?', `FemaleText_loc1`='고향에서 이렇게 먼 곳에서 뭐 하세요?', `FemaleText_loc4`='你在离家这么远的地方干什么呢？', `FemaleText_loc5`='你到離家這麼遠的地方來做什麼?', `FemaleText_loc7`='¿Qué haces tan lejos de casa?' WHERE `ID`=63799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽은 지금 상황이 안 좋소. 스컬지 문제는 해결이 됐지만, 우리는 계속 이동하면서 식량을 찾고 있소. 그래서 난 떠나서 새로운 낚시터를 찾아야겠다고 마음 먹었지!$b$b바다를 거의 한 달 떠돈 끝에 도착한 곳이 여기라오. 여행 전에 절인 청어를 한 상자 꾸려 둔 것이 다행이지 뭐요!', `MaleText_loc4`='呃，北上变得越发困难了。尽管天灾的麻烦已经得到解决，我们还得不断迁移和觅食。我下定决心，是时候出去寻找新渔场了！$b$b在海上漂流了近一个月之后，我来到了这里。幸好我带了几箱腌鲱鱼，否则途中就要饿肚子了！', `MaleText_loc5`='嗯，北地的情勢越來越惡劣。儘管天譴軍團的問題得到解決，我們仍在不斷遷徙並尋找食物。因此我決定，該是出發去找新漁場的時候了!$b$b在海上度過將近一個月後，我來到了這裡。幸好我打包了幾箱醃青魚來渡過這段旅程!', `MaleText_loc7`='Bueno, las cosas estaban cada vez más difíciles en el norte. Aunque el problema de la Plaga está solucionado, siempre estamos moviéndonos y buscando comida. ¡Decidí que ya era hora de salir a buscar nuevas zonas de pesca!$b$bTras casi un mes en el mar, acabé aquí. ¡Menos mal que traje unas cuantas cajas de arenque escabechado para el viaje!', `FemaleText_loc1`='북쪽은 지금 상황이 안 좋아요. 스컬지 문제는 해결이 됐지만, 우리는 계속 이동하면서 식량을 찾고 있거든요. 그래서 전 떠나서 새로운 낚시터를 찾아야겠다고 마음 먹었어요!$b$b바다를 거의 한 달 떠돈 끝에 도착한 곳이 여기죠. 여행 전에 절인 청어를 한 상자 꾸려 둔 것이 다행이지 뭐예요!', `FemaleText_loc4`='呃，北上变得越发困难了。尽管天灾的麻烦已经得到解决，我们还得不断迁移和觅食。我下定决心，是时候出去寻找新渔场了！$b$b在海上漂流了近一个月之后，我来到了这里。幸好我带了几箱腌鲱鱼，否则途中就要饿肚子了！', `FemaleText_loc5`='嗯，北地的情勢越來越惡劣。儘管天譴軍團的問題得到解決，我們仍在不斷遷徙並尋找食物。因此我決定，該是出發去找新漁場的時候了!$b$b在海上度過將近一個月後，我來到了這裡。幸好我打包了幾箱醃青魚來渡過這段旅程!', `FemaleText_loc7`='Bueno, las cosas estaban cada vez más difíciles en el norte. Aunque el problema de la Plaga está solucionado, siempre estamos moviéndonos y buscando comida. ¡Decidí que ya era hora de salir a buscar nuevas zonas de pesca!$b$bTras casi un mes en el mar, acabé aquí. ¡Menos mal que traje unas cuantas cajas de arenque escabechado para el viaje!' WHERE `ID`=63800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 몇 년 동안 기 폭발 기술을 수련했습니다. 당신 곁에서 싸울 수 있다면 그런 영예가 없을 겁니다. 제 도움이 필요하십니까?', `MaleText_loc4`='我潜心苦练了好几年，以掌握真气冲击的要诀，很荣幸能与你并肩战斗。你需要我的协助吗？', `MaleText_loc5`='我花了很多年時間來掌控氣功破的技巧，能和你並肩作戰是我的榮幸。你想要我的協助嗎?', `MaleText_loc7`='He estudiado durante años para dominar el arte de la explosión chi y me honraría luchar a tu lado. ¿Te gustaría que te ayudara?' WHERE `ID`=63801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오히려 제 영예입니다. 함께 가시지요!', `MaleText_loc4`='非常荣幸，全力以赴吧！', `MaleText_loc5`='應該說是我的榮幸。上陣吧!', `MaleText_loc7`='El honor es mío, ¡a tu puesto!', `FemaleText_loc1`='오히려 제 영예죠. 함께 가시죠!', `FemaleText_loc4`='非常荣幸，全力以赴吧！', `FemaleText_loc5`='應該說是我的榮幸。上陣吧!', `FemaleText_loc7`='El honor es mío, ¡a tu puesto!' WHERE `ID`=63802;
