UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF4809|Hspell:116784|h[공포의 심장]|h|r에게 선택되었습니다!', `MaleText_loc4`='你被|cFFFF4809|Hspell:116784|h[恐惧之心]|h|r选中了！', `MaleText_loc5`='你被|cFFFF4809|Hspell:116784|h[恐懼之心]|h|r選上了!', `MaleText_loc7`='¡El |cFFFF4809|Hspell:116784|h[Corazón de miedo]|h|r te ha seleccionado!', `FemaleText_loc1`='당신은 |cFFFF4809|Hspell:116784|h[공포의 심장]|h|r에게 선택되었습니다!', `FemaleText_loc4`='你被|cFFFF4809|Hspell:116784|h[恐惧之心]|h|r选中了！', `FemaleText_loc5`='你被|cFFFF4809|Hspell:116784|h[恐懼之心]|h|r選上了!', `FemaleText_loc7`='¡El |cFFFF4809|Hspell:116784|h[Corazón de miedo]|h|r te ha seleccionado!' WHERE `ID`=63804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석이 응결되어 |cFFFF0404|Hspell:125803|h[호박석 덫]|h|r을 형성합니다!', `MaleText_loc4`='琥珀凝结后形成了|cFFFF0404|Hspell:125803|h[琥珀陷阱]|h|r！', `MaleText_loc5`='琥珀凝結起來，形成一個|cFFFF0404|Hspell:125803|h[琥珀陷阱]|h|r !', `MaleText_loc7`='¡El ámbar se fusiona para formar una |cFFFF0404|Hspell:125803|h[Trampa de ámbar]|h|r!', `FemaleText_loc1`='호박석이 응결되어 |cFFFF0404|Hspell:125803|h[호박석 덫]|h|r을 형성합니다!', `FemaleText_loc4`='琥珀凝结后形成了|cFFFF0404|Hspell:125803|h[琥珀陷阱]|h|r！', `FemaleText_loc5`='琥珀凝結起來，形成一個|cFFFF0404|Hspell:125803|h[琥珀陷阱]|h|r !', `FemaleText_loc7`='¡El ámbar se fusiona para formar una |cFFFF0404|Hspell:125803|h[Trampa de ámbar]|h|r!' WHERE `ID`=63805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<멍멍이가 짓궂은 표정으로 당신을 바라봅니다.>', `MaleText_loc4`='<狗狗疑惑地看着你。>', `MaleText_loc5`='<小狗困惑地看著你。>', `MaleText_loc7`='<Perro te mira con curiosidad.>' WHERE `ID`=63806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿨쿨쿨쿨', `MaleText_loc4`='ZzzZZzzzz', `MaleText_loc5`='ZzzZZzzzz', `MaleText_loc7`='ZzzZZzzzz', `FemaleText_loc1`='쿨쿨쿨쿨', `FemaleText_loc4`='ZzzZZzzzz', `FemaleText_loc5`='ZzzZZzzzz', `FemaleText_loc7`='ZzzZZzzzz' WHERE `ID`=63807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오! 마을을 지켜야 합니다. 위치로 가서 임무를 수행하십시오!', `MaleText_loc4`='醒醒！我们必须守卫村庄，到炮台那去，帮帮我们！', `MaleText_loc5`='醒過來!我們必須保衛村莊，去拿你的迫擊砲來幫我們!', `MaleText_loc7`='¡DESPIERTA! ¡Tenemos que defender la aldea! ¡Tenemos que defender la aldea! ¡Coge tu mortero y ayúdanos!', `FemaleText_loc1`='일어나세요! 마을을 지켜야 해요. 위치로 가서 임무를 수행하세요!', `FemaleText_loc4`='醒醒！我们必须守卫村庄，到炮台那去，帮帮我们！', `FemaleText_loc5`='醒過來!我們必須保衛村莊，去拿你的迫擊砲來幫我們!', `FemaleText_loc7`='¡DESPIERTA! ¡Tenemos que defender la aldea! ¡Tenemos que defender la aldea! ¡Coge tu mortero y ayúdanos!' WHERE `ID`=63808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별로 도움이 될 것 같지 않으니, 자게 내버려 둡시다.', `MaleText_loc4`='他们好像帮不上什么忙，让他们继续睡吧。', `MaleText_loc5`='他們看起來不大有用，我們應該讓他們繼續睡。', `MaleText_loc7`='No parece que puedan ayudarnos, deberíamos dejar que duerman.', `FemaleText_loc1`='별로 도움이 될 것 같지 않으니, 자게 내버려 둬요.', `FemaleText_loc4`='他们好像帮不上什么忙，让他们继续睡吧。', `FemaleText_loc5`='他們看起來不大有用，我們應該讓他們繼續睡。', `FemaleText_loc7`='No parece que puedan ayudarnos, deberíamos dejar que duerman.' WHERE `ID`=63809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 따뜻한 온천의 물줄기 사이로 신나게 헤엄칩니다.', `MaleText_loc4`='%s在温水的出水口间兴奋地游曳着。', `MaleText_loc5`='%s興奮地游過溫水孔。', `MaleText_loc7`='%s nada con emoción por los respiraderos de agua tibia.' WHERE `ID`=63810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 안개돌이호의 뱃머리를 매만지며 훌쩍입니다.', `MaleText_loc4`='%s摩挲着雾海飞跃者的船头，低声啜泣着。', `MaleText_loc5`='%s擦著躍霧者的船頭並啜泣著。', `MaleText_loc7`='%s se frota contra la proa de El Saltanieblas y gimotea.' WHERE `ID`=63811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고래 시체에 영역을 표시하기 전에 조심스럽게 둘러봅니다.', `MaleText_loc4`='%s谨慎地环顾四周，然后才在鲸鱼的尸体上留下印记。', `MaleText_loc5`='%s謹慎地環顧四周，然後才在鯨魚屍體上留下他的標記。', `MaleText_loc7`='%s mira alrededor con cautela antes de dejar su marca en el cadáver de la ballena.' WHERE `ID`=63812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 땅을 다스리는 위대한 천신이 네 분 계십니다.$B$B생명을 주시는 동방의 옥룡 위론 님.$B$B남방의 희망, 주학 츠지 님.$B$B북방을 그 힘으로 지키고 계신 백호 쉬엔 님.$B$B그리고 서방에 당당히 서 계신 흑우 니우짜오 님입니다.$B$B최근 샤의 출현과 함께 네 사원이 모두 혼란에 휩싸였지요. 그곳에 도움이 필요합니다, $r님.', `FemaleText_loc4`='四个至尊天神统治着这片土地。$B$B青龙玉珑，东方的生命赋予者。$B$B朱雀赤精，南方的希望。$B$B白虎雪怒，他的力量维护着北方的和平。$B$B玄牛砮皂，他屹立在西方的天际。$B$B最近，随着煞魔的蠢蠢欲动，杂念已经开始席卷各个寺院。他们需要我们的帮助，$r。', `FemaleText_loc5`='有四尊聖獸天尊統治著這片土地。$B$B『玉蛟』玉龍，東方的生命賜予者。$B$B『紅鶴』赤吉，南方的希望。$B$B『白虎』雪怒，以其力量鎮守著北方。$B$B『玄牛』怒兆，屹立於西方。$B$B最近隨著煞的進逼，祂們的神殿都被捲入了混亂之中。祂們需要我們的幫助，$r。', `FemaleText_loc7`='Hay cuatro Augustos Celestiales que gobiernan esta tierra.$B$BYu''lon el Dragón de Jade, dador de vida del este.$B$BChi-Ji la Grulla Roja, esperanza del sur.$B$BXuen el Tigre Blanco, cuya fuerza sostiene al norte.$B$BY Niuzao el Buey Negro, que se mantiene fuerte en el oeste.$B$BRecientemente, con la llegada del sha, el conflicto se ha adueñado de sus templos. Necesitan nuestra ayuda, $r.' WHERE `ID`=63813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파에게는 영원한 임무가 있습니다. 오래전 땅속에 봉인된 사악한 샤의 기운을 감시하는 임무이지요.$B$B불행히도 샤가 감옥을 빠져나왔습니다. 우리가 다시 한 번 물리쳐야 하지요.', `MaleText_loc4`='影踪派时刻保持警惕，监视着被封入地底已久的黑暗煞能。$B$B不幸的是，邪煞逃离了囚牢，我们现在必须再次将它击败。', `MaleText_loc5`='影潘保持著永恆的警戒，監視著很久以前被封印在大地中的黑暗煞之能量。$B$B很不幸地，煞從它們的牢籠逃脫了，如今我們必須再次擊敗它們。', `MaleText_loc7`='El Shadopan guarda la vigilia eterna, controlando las oscuras energías de los sha que encerraron mucho tiempo atrás.$B$BPor desgracia, los sha han escapado de su prisión y ahora debemos volver a derrotarlos.' WHERE `ID`=63814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시하기엔 딱 좋은 날이군요. 안 그렇습니까? $n 님도 낚시꾼 맞으시죠? 원하신다면 조금 오래된 낚시용 미끼가 있습니다. 여기 물고기들이 그걸 보고 입질을 할지는 잘 모르겠군요.', `MaleText_loc4`='真是适合垂钓的好日子，你觉得呢？你也是渔夫吗，$n？要是你有兴趣，我这刚好有一种古老的鱼饵，对这片水域里的鱼尤其有吸引力。', `MaleText_loc5`='真是個適合釣魚的美麗日子，你不覺得嗎?你是個釣手嗎，$n?喜歡的話，我有個老釣餌，在這水域特別有效。', `MaleText_loc7`='Un día precioso para pescar, ¿no te parece? ¿Eres $gun pescador:una pescadora;, $n? Tengo este viejo cebo de pesca, si lo quieres. En estas aguas funciona de maravilla.' WHERE `ID`=63815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끼를 주십시오. 감사합니다.', `MaleText_loc4`='很好，谢谢。', `MaleText_loc5`='我很喜歡，謝謝你。', `MaleText_loc7`='Me encantaría, muchas gracias.', `FemaleText_loc1`='미끼를 주세요. 고맙습니다.', `FemaleText_loc4`='很好，谢谢。', `FemaleText_loc5`='我很喜歡，謝謝你。', `FemaleText_loc7`='Me encantaría, muchas gracias.' WHERE `ID`=63816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 연꽃은 영원꽃 골짜기를 지키는 임무를 맡고 있습니다.$B$B저희를 돕고 싶다면 현재 골짜기를 점령하고 있는 적을 물리치십시오.$B$B석양 주둔지에 있는 안지 오톰라이트를 찾아가면 다른 일거리도 줄 겁니다.', `MaleText_loc4`='金莲教肩负着守卫锦绣谷的重任。$B$B如果你想帮助我们，就去打败那些目前占据着锦绣谷的敌人吧。$B$B你也可以去残阳关卫戍营的训练场找安济·秋光，获取下一步的任务。', `MaleText_loc5`='金蓮會的職責就是保衛恆春谷。$B$B如果你想幫我們，就去打敗佔據山谷的敵人，他們與金蓮會為敵。$B$B你也可以和落陽要塞訓練營地的安吉·秋光談談，接取進一步的任務。', `MaleText_loc7`='El Loto Dorado tiene el cometido de defender el Valle de la Flor Eterna.$B$BSi deseas ayudarnos, derrota a los enemigos del Loto Dorado que invaden el valle.$b$bTambién puedes hablar con Anji Fulgor Otoñal, en el campamento de entrenamiento del Baluarte del Sol Poniente, para que te asigne más tareas.' WHERE `ID`=63817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑은 그야말로 물 반, 고기 반이지요!$B$B지금도 바다에서 대어를 잡고 싶지만, 아침에 낚은 고기를 팔아야 해서 여기 왔습니다. 여긴 배고픈 이가 많거든요!', `MaleText_loc4`='卡桑琅的鱼简直凶猛至极！$B$B我本该继续留在海上，跟那大家伙较劲，可我得来这里贩卖今早的收获。有好多饥肠辘辘的人正张嘴等着吃饭呢！', `MaleText_loc5`='喀撒朗的魚咬起人來像發瘋一樣!$B$B我還是寧願在海上用捲線釣一隻大魚，但我得來到這裡把今早釣到的魚貨賣掉。有一大堆嗷嗷待哺的嘴在等著我!', `MaleText_loc7`='¡Los peces están picando como locos en Krasarang!$B$BSeguiría en el mar, tratando de atrapar al pez gordo, pero he venido aquí a vender la pesca de esta mañana. ¡Tengo un montón de bocas hambrientas que alimentar aquí!' WHERE `ID`=63818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡에 가 봤어?$B$B우리 농장 일꾼들은 여기 영원꽃 골짜기의 위기에 대해 듣고는, 피난민 먹일 식량을 열심히 기르고 있다.$B$B시골에서 한숨 돌리고 싶으면, 언덕골을 찾아와라!', `MaleText_loc4`='你去过四风谷吗？$B$B听说山谷中出现了危机，我们这些阡陌客正努力为这些难民种植食物。$B$B如果你想到乡间走走，请到半山来看我们！', `MaleText_loc5`='你有去過四風峽嗎?$B$B雇農們聽說了山谷這裡的危機。我們的耕者正拼命工作，讓難民有食物吃。$B$B如果你有興趣到鄉下走走，就來半丘找我們!', `MaleText_loc7`='¿Has estado alguna vez en el Valle de los Cuatro Vientos?$B$BNos hemos enterado de la crisis aquí en el valle, y nuestros labradores trabajan duro cultivando comida para estos refugiados.$B$B¡Si te apetece pasar un rato en el campo, visítanos en El Alcor!' WHERE `ID`=63819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게, 걸어서 그 통로를 통과하려는 건 아니겠지? 거기엔 사우록이 떼지어 돌아다닌다네. 게다가 놈들은 영역 본능이 강하지.', `MaleText_loc4`='你好。我想你不会愿意徒步穿过那条隧道的。蜥蜴人今天在外面集结了军队，那是一支强大的护卫队。', `MaleText_loc5`='你好啊。我不認為你會想用兩條腿走下那條通道。現在薩烏洛克人數眾多，而且他們領域性很強。', `MaleText_loc7`='Hola. No te recomiendo que bajes ese túnel a pie. Los saurok están en bloque hoy y son bastante territoriales.' WHERE `ID`=63820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 빛, 소멸됨.', `MaleText_loc4`='生命之火熄灭。', `MaleText_loc5`='生命的火花消失了。', `MaleText_loc7`='La chispa de la vida se desvanece.' WHERE `ID`=63821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존재, 사라짐.', `MaleText_loc4`='曾有的已经消失。', `MaleText_loc5`='生命不復存在。', `MaleText_loc7`='Lo que fue ya no es.' WHERE `ID`=63822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 조치, 성공.', `MaleText_loc4`='反制成功。', `MaleText_loc5`='防禦對策成功。', `MaleText_loc7`='Contramedidas aplicadas.' WHERE `ID`=63823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다가와라. 티탄의 힘을 느껴라.', `MaleText_loc4`='过来！感受泰坦的力量！', `MaleText_loc5`='靠近!感受泰坦的力量吧!', `MaleText_loc7`='¡Acérquense! ¡Sientan el poder de los titanes!' WHERE `ID`=63824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예비 전력 사용.', `MaleText_loc4`='抽取备用能量。', `MaleText_loc5`='後備能量擷取中。', `MaleText_loc7`='Recurriendo a reserva de energía.' WHERE `ID`=63825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골!? 지금!?', `MaleText_loc4`='野牛人！？现在！？', `MaleText_loc5`='揚古!?現在!?', `MaleText_loc7`='¡¿Yaungol?! ¡¿Ahora?!' WHERE `ID`=63826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지에 잠식당해라!', `MaleText_loc4`='让能量吞噬你们！', `MaleText_loc5`='讓能量吞噬你們!', `MaleText_loc7`='¡Que la energía os consuma!' WHERE `ID`=63827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전선 비활성화.', `MaleText_loc4`='导管断线。', `MaleText_loc5`='導體已關閉。', `MaleText_loc7`='Conductos desactivados.' WHERE `ID`=63828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 뻥뻥주를 노리고 온 게로군! $p, 정찰대를 확인하고 마을 방비를 단단히 하게! 그렇게 호락호락 내 맥주를 넘겨주진 않을 걸세!', `MaleText_loc4`='他们肯定是在找寻昆莱劲酒！$p，调查一下这些眼线，建立村庄的防线！他们休想轻易就拿走我的酒！', `MaleText_loc5`='他們一定是衝著崑萊好勁道來的!$p，去調查揚古來襲的問題，並且在村莊設置防禦!絕不能讓他們輕輕鬆鬆就拿走我的酒!', `MaleText_loc7`='¡Deben andar detrás de la pateadora de Kun-Lai! ¡$p, investiga estos avistamientos y prepara las defensas de la aldea! ¡No se llevarán mi brebaje sin una pelea!' WHERE `ID`=63829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 맥주가 완성될 때까지 이곳을 지키겠네. 그러고 나면 뻥뻥주를 이용해서 바타리 놈들을 상대할 수 있지! 나머지는 모두 안전한 곳으로 피하게!', `MaleText_loc4`='在酿出好酒之前，我会全力保护它们的。然后我们就可以用这些酒来对付巴塔里掠夺者！这样一来，其他人就安全了！', `MaleText_loc5`='在啤酒釀好之前我會保護它。接著我們可以用釀好的啤酒去對付這些巴塔利劫掠者!其他人，到安全的地方去!', `MaleText_loc7`='Defenderé la cerveza hasta que esté lista. ¡Entonces podremos usarla contra estos asaltantes Bataari! ¡Todos los demás, busquen un lugar seguro!' WHERE `ID`=63830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 소용돌이 감소.', `MaleText_loc4`='能量涡流缓降。', `MaleText_loc5`='能量漩渦減緩中。', `MaleText_loc7`='Vórtice de energía disminuyendo.' WHERE `ID`=63831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동력 전환.', `MaleText_loc4`='能量重新定向。', `MaleText_loc5`='能量重新定向中。', `MaleText_loc7`='Redirigiendo energía.' WHERE `ID`=63832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에너지 전선 활성화. 동력 안정.', `MaleText_loc4`='能量导管激活，趋向稳定。', `MaleText_loc5`='能量導體已啟動，擷取穩定。', `MaleText_loc7`='Conductos de energía activados. Suministro estable.' WHERE `ID`=63833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤이 펑이 내려앉을 준비를 합니다!', `MaleText_loc4`='黑风即将准备登陆！', `MaleText_loc5`='黑峰準備要登陸了!', `MaleText_loc7`='¡Hei Feng se prepara para aterrizar!' WHERE `ID`=63834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존재 만료... 내 역할은 끝이다. 으으으...', `MaleText_loc4`='存在终止……开始解体……', `MaleText_loc5`='存在已終結...我不復存在...', `MaleText_loc7`='La existencia termina... No soy nada...' WHERE `ID`=63835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고대 왕국의 암흑기 이후로, 우리 판다렌은 신비한 양조술에 의지해 기운을 살리고 힘을 북돋았지요.$B$B지금 이 순간에도 양조사들은 훌륭한 술을 만들기 위해 세상을 떠돌며 귀하고 강력한 재료를 찾고 있답니다.$B$B바람과도 같은 양조사들을 찾아서 도와주면 멋진 물건을 손에 넣을 수 있을지도 모르지요. 적어도 술은 잔뜩 마실 수 있을 테고요!', `FemaleText_loc4`='从古代王国的黑暗时期开始，我们熊猫人就开始依靠神秘的酿造工艺保持充沛的精力和体力。$B$B甚至在我们谈话的时候，我们的酒仙仍然在周游世界，寻找罕见和充满力量的成分来酿造最好的酒。$B$B找到这些行踪不定的酒仙并且帮助他们的人，可以得到香甜可口的美酒。至少，你能喝个够！', `FemaleText_loc5`='自從舊王國的黑暗時代開始，我們熊貓人就藉助於釀酒的神秘技巧來保持我們高昂的精神和力量。$B$B就算在我們交談的同時，釀酒大師們也正在世界各地遊蕩，尋覓稀有且強力的材料來釀造最好的酒。$B$B那些能找出這些難以捉摸的釀酒大師並給予他們幫助之人，可以獲得充滿風味的物品。最少最少，你會喝到很多的酒!', `FemaleText_loc7`='Desde los oscuros días del antiguo reino, los pandaren hemos recurrido al arte místico de la cervecería para conservar el espíritu y la fuerza intactos.$b$bEn este mismo momento muchos maestros cerveceros recorren el mundo en busca de ingredientes raros y poderosos con los que elaborar la cerveza más refinada.$b$bAquellos que buscan a estos esquivos maestros cerveceros y les ayudan pueden acabar ganando objetos muy sabrosos. Como mínimo, ¡beberás un montón!' WHERE `ID`=63836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웬 고블린한테 받은 건데, 이걸 쓰면 선로 위를 달리는 건 뭐든지 멈출 수 있다더군. 한번 써 보겠나?', `MaleText_loc4`='我是从地精那里得到这个的，他说它可以阻止任何东西靠近，想试一下吗？', `MaleText_loc5`='我是從一個哥布林那裡拿到這東西的，他說它能嚇阻任何東西，想試試看嗎?', `MaleText_loc7`='Conseguí esto de un goblin, dijo que podría detener todo, ¿quieres intentarlo?', `FemaleText_loc1`='웬 고블린한테 받은 건데, 이걸 쓰면 선로 위를 달리는 건 뭐든지 멈출 수 있다더군요. 한번 써 보겠어요?', `FemaleText_loc4`='我是从地精那里得到这个的，他说它可以阻止任何东西靠近，想试一下吗？', `FemaleText_loc5`='我是從一個哥布林那裡拿到這東西的，他說它能嚇阻任何東西，想試試看嗎?', `FemaleText_loc7`='Conseguí esto de un goblin, dijo que podría detener todo, ¿quieres intentarlo?' WHERE `ID`=63837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지요! 써 보겠습니다.', `MaleText_loc4`='当然了！我一定要试一试。', `MaleText_loc5`='當然!我來試試看。', `MaleText_loc7`='¡Claro! Lo probaré.', `FemaleText_loc1`='좋죠! 써 볼게요.', `FemaleText_loc4`='当然了！我一定要试一试。', `FemaleText_loc5`='當然!我來試試看。', `FemaleText_loc7`='¡Claro! Lo probaré.' WHERE `ID`=63838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사양하겠습니다. 더파 씨가 가지고 계십시오.', `MaleText_loc4`='不必了，你可以留着它，迪嘭先生。', `MaleText_loc5`='想都別想，德帕先生。你留著它吧。', `MaleText_loc7`='Ni pensarlo, puedes quedarte con eso, señor Derpa.', `FemaleText_loc1`='사양할게요. 더파 씨가 가지고 계세요.', `FemaleText_loc4`='不必了，你可以留着它，迪嘭先生。', `FemaleText_loc5`='想都別想，德帕先生。你留著它吧。', `FemaleText_loc7`='Ni pensarlo, puedes quedarte con eso, señor Derpa.' WHERE `ID`=63839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 살았나? 고맙습니다... 정말 고마워요!', `MaleText_loc4`='我……还活着？谢谢你……太感谢你了！', `MaleText_loc5`='我...還活著?謝謝你...非常謝謝你!', `MaleText_loc7`='¿Sigo... con vida? ¡Gracias... muchas gracias!', `FemaleText_loc1`='내가... 살았나? 고맙습니다... 정말 고마워요!', `FemaleText_loc4`='我……还活着？谢谢你……太感谢你了！', `FemaleText_loc5`='我...還活著?謝謝你...非常謝謝你!', `FemaleText_loc7`='¿Sigo... con vida? ¡Gracias... muchas gracias!' WHERE `ID`=63840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파에게는 영원한 임무가 있습니다. 오래전 땅속에 봉인된 사악한 샤의 기운을 감시하는 임무이지요.$B$B불행히도 샤가 감옥을 빠져나왔습니다. 우리가 다시 한 번 물리쳐야 하지요.', `MaleText_loc4`='影踪派永远保持警惕，不断监视着很久以前封入地下的黑暗煞魔的能量。$B$B不幸的是，煞魔逃出了他们的囚牢，现在我们必须再次击败他们。', `MaleText_loc5`='影潘保持著永恆的警戒，看守著許久以前被封印在大地之下的黑暗煞之能量。$B$B很不幸地，煞已經從他們的監牢逃脫，而現在我們必須再次擊敗他們。', `MaleText_loc7`='El Shadopan guarda la vigilia eterna, controlando las oscuras energías de los sha que encerraron mucho tiempo atrás.$B$BPor desgracia, los sha han escapado de su prisión y ahora debemos volver a derrotarlos.' WHERE `ID`=63841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황금 연꽃은 영원꽃 골짜기를 지키는 임무를 맡고 있습니다.$B$B저희를 돕고 싶다면 현재 골짜기를 점령하고 있는 적을 물리치십시오.$B$B석양 주둔지에 있는 안지 오톰라이트를 찾아가면 다른 일거리도 줄 겁니다.', `FemaleText_loc4`='金莲教肩负着守卫锦绣谷的重任。$B$B如果你想帮助我们，就去打败那些目前占据着锦绣谷的敌人吧。$B$B你也可以去残阳关卫戍营的训练场找安济·秋光，获取下一步的任务。', `FemaleText_loc5`='金蓮會的職責就是保衛恆春谷。$B$B如果你想幫我們，就幫我們擊敗佔領恆春谷的敵人。$B$B你也可以去落陽要塞的訓練營找安吉·秋光看看有沒有進一步的工作。', `FemaleText_loc7`='El Loto Dorado tiene el cometido de defender el Valle de la Flor Eterna.$B$BSi deseas ayudarnos, derrota a los enemigos del Loto Dorado que invaden el valle.$b$bTambién puedes hablar con Anji Fulgor Otoñal, en el campamento de entrenamiento del Baluarte del Sol Poniente, para que te asigne más tareas.' WHERE `ID`=63842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 다스리는 위대한 천신이 네 분 계십니다.$B$B생명을 주시는 동방의 옥룡 위론 님.$B$B남방의 희망, 주학 츠지 님.$B$B북방을 그 힘으로 지키고 계신 백호 쉬엔 님.$B$B그리고 서방에 당당히 서 계신 흑우 니우짜오 님입니다.$B$B최근 샤의 출현과 함께 네 사원이 모두 혼란에 휩싸였지요. 그곳에 도움이 필요합니다, $r님.', `MaleText_loc4`='共有四位至尊天神统御着这片土地。$B$B东方生命之神，青龙玉珑。$B$B南方希望之神，朱鹤赤精。$B$B北方力量之神，白虎雪怒。$B$B西方巍峨之神，玄牛砮皂。$B$B近来，随着邪煞的出现，这四位天神的寺院都陷入了混乱。他们需要我们的帮助，$r。', `MaleText_loc5`='有四尊聖獸天尊統治著這片土地。$B$B『玉蛟』玉龍，東方的生命賜予者。$B$B『紅鶴』赤吉，南方的希望。$B$B『白虎』雪怒，以其力量鎮守著北方。$B$B『玄牛』怒兆，屹立於西方。$B$B最近隨著煞的進逼，祂們的神殿都被捲入了混亂之中。祂們需要我們的幫助，$r。', `MaleText_loc7`='Hay cuatro Augustos Celestiales que gobiernan esta tierra.$B$BYu''lon el Dragón de Jade, dador de vida del este.$B$BChi-Ji la Grulla Roja, esperanza del sur.$B$BXuen el Tigre Blanco, cuya fuerza sostiene al norte.$B$BY Niuzao el Buey Negro, que se mantiene fuerte en el oeste.$B$BRecientemente, con la llegada del sha, el conflicto se ha adueñado de sus templos. Necesitan nuestra ayuda, $r.' WHERE `ID`=63843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r님, 혹시 낚시에 끌린 적이 있습니까?$B$B그렇다면 크라사랑 밀림의 강태공들을 찾아가 보는 게 좋을 겁니다.', `FemaleText_loc4`='告诉我，$r，你对钓鱼心怀向往吗？$B$B如果答案是肯定的，那你应该去卡桑琅丛林找垂钓翁。', `FemaleText_loc5`='告訴我，$r，你有曾經嚮往過釣魚嗎?$B$B如果有的話，你或許會想要去拜訪在喀撒朗蠻荒裡的釣手隊。', `FemaleText_loc7`='Dime, $r, ¿alguna vez has ansiado pescar?$B$BSi es así, te convendría visitar a Los Pescadores, en la Espesura Krasarang.' WHERE `ID`=63844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 근면한 판다리아 농부의 모임, 농사꾼 연합의 일원입니다. 우리에 대해 더 알고 싶다면, 네 바람의 계곡에 있는 언덕골로 가 보시지요.', `MaleText_loc4`='我是阡陌客的成员，这个组织是由潘达利亚的辛勤农夫组成的。如果你想对我们有更多的了解，可以到四风谷的半山来找我们。', `MaleText_loc5`='我是個耕者工會成員，也就是潘達利亞辛勤工作的農夫們之一。假如你想要知道更多關於我們的事，我們的公會就在四風峽中的半丘。', `MaleText_loc7`='Soy miembro de los Labradores, los trabajadores granjeros de Pandaria. Si deseas aprender más sobre nosotros, estamos en El Alcor, en el Valle de los Cuatro Vientos.' WHERE `ID`=63845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 왕국의 암흑기 이후로, 우리 판다렌은 신비한 양조술에 의지해 기운을 살리고 힘을 북돋았다오.$B$B지금 이 순간에도 양조사들은 훌륭한 술을 만들기 위해 세상을 떠돌며 귀하고 강력한 재료를 찾고 있지요.$B$B바람과도 같은 양조사들을 찾아서 도와주면 멋진 물건을 손에 넣을 수 있을지도 모른다오. 적어도 술은 잔뜩 마실 수 있을 테고 말이오!', `MaleText_loc4`='从古王国的黑暗统治时期开始，我们熊猫人就开始钻研酿酒这门神秘艺术，来振作精神，强身健体。$B$B就在我们说话间，酒仙们还在世界各地奔走，寻觅稀有强劲的原料，以制出绝品佳酿。$B$B那些有幸找到这些隐秘大师，并向他们提供帮助的人，也许能获得风味十足的物品。至少能饱饮美酒！', `MaleText_loc5`='自從舊王國的黑暗時代開始，我們熊貓人就藉助於釀酒的神秘技巧來保持我們高昂的精神和力量。$B$B就算在我們交談的同時，釀酒大師們也正在世界各地遊蕩，尋覓稀有且強力的材料來釀造最好的酒。$B$B那些能找出這些難以捉摸的釀酒大師並給予他們幫助之人，可以獲得充滿風味的物品。最少最少，你會喝到很多的酒!', `MaleText_loc7`='Desde los oscuros días del antiguo reino, los pandaren hemos recurrido al arte místico de la cervecería para conservar el espíritu y la fuerza intactos.$b$bEn este mismo momento muchos maestros cerveceros recorren el mundo en busca de ingredientes raros y poderosos con los que elaborar la cerveza más refinada.$b$bAquellos que buscan a estos esquivos maestros cerveceros y les ayudan pueden acabar ganando objetos muy sabrosos. Como mínimo, ¡beberás un montón!' WHERE `ID`=63846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바라건대 이번 뱃길엔 아무 문제도 없으면 좋겠군.', `MaleText_loc4`='希望这次我们不会再嗝儿个没完了。', `MaleText_loc5`='希望這次我們不會打嗝。', `MaleText_loc7`='Espero que esta vez no nos encontremos contratiempos.' WHERE `ID`=63847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 쿤라이에 가본 적 있나? 멋진 곳이라네. 구비구비 펼쳐진 농장에 아름다운 산들... 위험한 거라곤 전혀 없고 말일세.', `MaleText_loc4`='以前到过昆莱吗？昆莱是个好地方。绵延不绝的农田。巍峨秀美的山脉。而且一点儿危险也没有。', `MaleText_loc5`='以前去過崑萊嗎?那是個很棒的地方。像流水一般綿延的農田，美麗的山巒。而且絕對沒有任何的危險。', `MaleText_loc7`='¿Habías estado alguna vez en Kun-Lai? Es genial. Grandes tierras de cultivo. Montañas preciosas... y absolutamente nada peligroso.' WHERE `ID`=63848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게... 그렇지. 호젠 문제가 있긴 하지.', `MaleText_loc4`='额……对。就是有猢狲捣乱。', `MaleText_loc5`='嗯...是啦。那裡是有猴人的問題。', `MaleText_loc7`='Bueno... sí. Hay problemas con los hozen.' WHERE `ID`=63849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록이 들고 있는 창은 그냥 과시용이야. 배에서 안 나가고, 놈들이랑 눈 안 마주치고, 창에 맞지만 않으면 괜찮다고.', `MaleText_loc4`='长矛只是吓唬人用的。只要我们待在船上，不跟它们有眼神接触，也不被长矛击中，应该就不会有危险。', `MaleText_loc5`='那些長矛只是擺著好看的。只要我們待在船中而且避免眼神接觸，或是被長矛擊中，我們應該就不會有太大的問題。', `MaleText_loc7`='Las lanzas solo están para asustar. Mientras no salgamos del bote, no establezcamos contacto visual y no nos clavemos una lanza, todo irá bien.' WHERE `ID`=63850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전하다니까. 바로 얼마 전에도 전승지기 초 님과 그분의 이상한 동료를 태워다 드렸지.', `MaleText_loc4`='安全得很。我不久前刚送过游学者周卓和他诡异的同伴们。', `MaleText_loc5`='很安全的。我不久之前才用這方法帶著博學行者阿洲和他奇怪的同伴們上來。', `MaleText_loc7`='Es seguro. Traje hasta aquí arriba al eremita Cho y a sus extraños compañeros no hace mucho tiempo.' WHERE `ID`=63851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그건 네가 잘못한 거지. 향을 그자 얼굴에 대고 흔들어댔... 잠깐, 뭔가 이상한데...', `MaleText_loc4`='你又来了。在他跟前摆弄那熏香……等等。这好像有些不对劲。', `MaleText_loc5`='你活該。誰叫你像這樣在他面前揮你的薰香...等一下。這樣做好像有點不大對勁。', `MaleText_loc7`='Te lo estabas buscando. Agitando el incienso en sus narices... Espera un segundo. Algo me da mala espina.' WHERE `ID`=63852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사람들은 뭐야? 피난민인가? 무슨 일이 생긴 거야? 이거, 싸우는 소린가?', `MaleText_loc4`='那些是难民吗？那边发生什么事了？我听见的是战斗的声音吗？', `MaleText_loc5`='那些是難民嗎?那裡發生了什麼事?我聽到的是打鬥的聲音嗎?', `MaleText_loc7`='¿Son refugiados? ¿Qué está pasando? ¿Oigo una lucha?' WHERE `ID`=63853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들은 농부지, 전사가 아니라고! 우리가 도와줘야 해!', `MaleText_loc4`='这些人是农民，不是战士！他们也许需要我们的帮助！', `MaleText_loc5`='這些人都是農夫，不是戰士!他們可能需要我們的幫助!', `MaleText_loc7`='¡Esa gente son granjeros, no guerreros! ¡Necesitan nuestra ayuda!' WHERE `ID`=63854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 호랑이도 있지.', `MaleText_loc4`='对，还有猛虎。', `MaleText_loc5`='是的，還有老虎。', `MaleText_loc7`='Sí, y los tigres.' WHERE `ID`=63855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 그루멀 공격해요.', `MaleText_loc4`='猢狲会攻击土地精。', `MaleText_loc5`='猴人攻擊咕嚕摩。', `MaleText_loc7`='Hozen atacan a Grúmel.' WHERE `ID`=63856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호랑이도요.', `MaleText_loc4`='猛虎。', `MaleText_loc5`='老虎群。', `MaleText_loc7`='Tigres.' WHERE `ID`=63857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록 되게 위험해요.', `MaleText_loc4`='蜥蜴人危险得很。', `MaleText_loc5`='薩烏洛克非常危險。', `MaleText_loc7`='Los saurok son muy peligrosos.' WHERE `ID`=63858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 통로에 사우록 많이 살아요.', `MaleText_loc4`='在远古之路住着许多蜥蜴人。', `MaleText_loc5`='有很多的薩烏洛克住在上古通道中。', `MaleText_loc7`='Muchos saurok viven en el Pasaje Antiguo.' WHERE `ID`=63859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 "오크"라는 자가 나 때리려고 했어요.', `MaleText_loc4`='那“兽人”想打我。', `MaleText_loc5`='這個「獸人」試過要揍我。', `MaleText_loc7`='El "orco" ha intentado golpearme.' WHERE `ID`=63860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을을 아무리 뒤져도 도무지 제 방패를 찾을 수가 없습니다! 돕고 싶은 마음은 굴뚝 같지만, 방패가 없으면 전 무용지물이라고요!', `MaleText_loc4`='我的盾牌不见了，我在村子里都找遍了！我希望自己能帮上忙，可没有盾牌，我什么也做不了！', `MaleText_loc5`='我找不到我的盾牌。我已經翻遍了整個村莊!我真希望我能幫忙，但沒有盾牌，我就一無是處了!', `MaleText_loc7`='No logro encontrar mi escudo, ¡he mirado por toda la aldea! Ojala pudiera ayudar, pero sin mi escudo no valgo para nada.', `FemaleText_loc1`='마을을 아무리 뒤져도 도무지 제 방패를 찾을 수가 없어요! 돕고 싶은 마음은 굴뚝 같지만, 방패가 없으면 전 무용지물이에요!', `FemaleText_loc4`='我的盾牌不见了，我在村子里都找遍了！我希望自己能帮上忙，可没有盾牌，我什么也做不了！', `FemaleText_loc5`='我找不到我的盾牌。我已經翻遍了整個村莊!我真希望我能幫忙，但沒有盾牌，我就一無是處了!', `FemaleText_loc7`='No logro encontrar mi escudo, ¡he mirado por toda la aldea! Ojala pudiera ayudar, pero sin mi escudo no valgo para nada.' WHERE `ID`=63861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 등에 메고 있잖습니까. 자, 이제 일어나서 거드십시오!', `MaleText_loc4`='……你的盾牌就在你背上。赶紧起来帮帮我们！', `MaleText_loc5`='...你的盾牌就在你的背上。快點站起來然後幫助我們!', `MaleText_loc7`='... Tienes el escudo en la espalda. ¡Ahora levántate y AYÚDANOS!', `FemaleText_loc1`='... 등에 메고 있잖아요. 자, 이제 일어나서 거드세요!', `FemaleText_loc4`='……你的盾牌就在你背上。赶紧起来帮帮我们！', `FemaleText_loc5`='...你的盾牌就在你的背上。現在站起來然後幫助我們!', `FemaleText_loc7`='... Tienes el escudo en la espalda. ¡Ahora levántate y AYÚDANOS!' WHERE `ID`=63862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 못 봤습니다. 오히려 못 찾는 게 나을지도 모르지요...', `MaleText_loc4`='抱歉，我也没看见。也许这样倒好……', `MaleText_loc5`='抱歉我之前也沒看到它。也許這樣最好...', `MaleText_loc7`='Lo siento, yo tampoco lo he visto. Quizás sea mejor así...', `FemaleText_loc1`='저도 못 봤어요. 오히려 못 찾는 게 나을지도 모르죠...', `FemaleText_loc4`='抱歉，我也没看见。也许这样倒好……', `FemaleText_loc5`='抱歉我之前也沒看到它。也許這是最好的...', `FemaleText_loc7`='Lo siento, yo tampoco lo he visto. Quizás sea mejor así...' WHERE `ID`=63863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 덕분에 찾았네요! 이제 야운골 놈들과 싸우러 가야겠군요.', `MaleText_loc4`='哈哈！你找到它了！现在该去抗击野牛人了。', `MaleText_loc5`='哈!你找到它了!現在是反擊揚古的時候了。', `MaleText_loc7`='¡Ah! ¡Lo has encontrado! ¡Es hora de luchar contra esos yaungol!', `FemaleText_loc1`='오! 덕분에 찾았네요! 이제 야운골 놈들과 싸우러 가야겠군요.', `FemaleText_loc4`='哈哈！你找到它了！现在该去抗击野牛人了。', `FemaleText_loc5`='哈!你找到它了!現在是反擊揚古的時候了。', `FemaleText_loc7`='¡Ah! ¡Lo has encontrado! ¡Es hora de luchar contra esos yaungol!' WHERE `ID`=63864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 창피하군요. 싸우러 갑시다!', `MaleText_loc4`='这可真令人尴尬。战斗吧！', `MaleText_loc5`='好吧。那真是尷尬。戰鬥吧!', `MaleText_loc7`='¡Qué vergüenza! ¡A luchar!', `FemaleText_loc1`='이런, 창피하네요. 싸우러 가요!', `FemaleText_loc4`='这可真令人尴尬。战斗吧！', `FemaleText_loc5`='好吧。那真是尷尬。戰鬥吧!', `FemaleText_loc7`='¡Qué vergüenza! ¡A luchar!' WHERE `ID`=63865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설마 그런 곳에 있을 줄이야... 어쨌든, 이제 싸우지요!', `MaleText_loc4`='没想到我的盾牌竟然在这儿，无所谓了，战斗吧！', `MaleText_loc5`='我的盾牌居然會出現在這種不可能出現的地方，不管了，我們上吧!', `MaleText_loc7`='¡Qué sitio más raro para mi escudo! ¡En cualquier caso, vamos a pelear!', `FemaleText_loc1`='설마 그런 곳에 있을 줄이야... 어쨌든, 이제 싸우죠!', `FemaleText_loc4`='没想到我的盾牌竟然在这儿，无所谓了，战斗吧！', `FemaleText_loc5`='我的盾牌居然會出現在這種不可能出現的地方，不管了，我們上吧!', `FemaleText_loc7`='¡Qué sitio más raro para mi escudo! ¡En cualquier caso, vamos a pelear!' WHERE `ID`=63866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장막의 계단은 고야 마님의 보호 아래 있습니다.', `MaleText_loc4`='雾纱栈道在郭雅夫人的保护之下。', `MaleText_loc5`='朦朧天梯受到苟雅女士的保護。', `MaleText_loc7`='La Escalera Velada está bajo la protección de la Señora Goya.', `FemaleText_loc1`='장막의 계단은 고야 마님의 보호 아래 있습니다.', `FemaleText_loc4`='雾纱栈道在郭雅夫人的保护之下。', `FemaleText_loc5`='朦朧天梯受到苟雅女士的保護。', `FemaleText_loc7`='La Escalera Velada está bajo la protección de la Señora Goya.' WHERE `ID`=63867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 속의 주점엔 보이는 것보다 많은 게 숨어 있지요.', `MaleText_loc4`='在迷雾酒肆里，你会大有收获。', `MaleText_loc5`='在霧隱客棧可以找到許多東西。', `MaleText_loc7`='Se puede encontrar mucho más en la Taberna en la Niebla.', `FemaleText_loc1`='안개 속의 주점엔 보이는 것보다 많은 게 숨어 있지요.', `FemaleText_loc4`='在迷雾酒肆里，你会大有收获。', `FemaleText_loc5`='在霧隱客棧可以找到許多東西。', `FemaleText_loc7`='Se puede encontrar mucho más en la Taberna en la Niebla.' WHERE `ID`=63868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주점은 이것저것 너무 캐묻지 않는 이들을 위한 곳입니다.', `MaleText_loc4`='迷雾酒肆只为话少的宾客服务。', `MaleText_loc5`='客棧歡迎不會問太多問題的。', `MaleText_loc7`='La taberna sirve a aquellos que no hacen demasiadas preguntas.', `FemaleText_loc1`='이 주점은 이것저것 너무 캐묻지 않는 이들을 위한 곳입니다.', `FemaleText_loc4`='迷雾酒肆只为话少的宾客服务。', `FemaleText_loc5`='客棧歡迎不會問太多問題的。', `FemaleText_loc7`='La taberna sirve a aquellos que no hacen demasiadas preguntas.' WHERE `ID`=63869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤이 펑이 숨을 깊게 들이쉽니다. 그의 뒤로 숨으십시오!', `MaleText_loc4`='黑风深呼吸了！到他背后去！', `MaleText_loc5`='黑峰正在深呼吸!移動到他背後去!', `MaleText_loc7`='¡Hei Feng respira hondo! ¡Ponte detrás de él!' WHERE `ID`=63870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $p. 우린 꽤 오랫동안 자네를 주시하고 있었지.$b$b자네는 변화의 폭풍을 몰고 오는 돌풍 같은 존재일세.', `MaleText_loc4`='欢迎你，$p。我们已经关注你很久了。$b$b你就像是预示着变化风暴即将到来的一股疾风。', `MaleText_loc5`='歡迎，$p。我們已經觀察你一段時間了。$B$B你是宣布改變的風暴即將來臨前的一陣強風。', `MaleText_loc7`='Te doy la bienvenida, $p. Te hemos estado observando durante un tiempo.$b$bEres la ráfaga de viento que anuncia la tormenta del cambio.' WHERE `ID`=63871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 탕랑 평원에서 내 형제를 도왔다는 말을 들었네. 누롱은 어떻게 지내나? 어쩌다가 눈을 잃었는지는 이야기해 주던가?', `MaleText_loc4`='我听说，你跟我弟弟一起在螳螂高原效力。那小家伙怎么样？他给你讲过他是怎么失去那只眼睛的吗？', `MaleText_loc5`='我聽說你在螳螂荒原時負責服侍我的兄弟。那個年輕人過的如何?他有沒有告訴你他是如何失去眼睛的?', `MaleText_loc7`='Me han informado de que serviste junto a mi hermano en las Estepas de Tong Long. ¿Qué tal está? ¿Llegó a contarte cómo perdió el ojo?' WHERE `ID`=63872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑습니다, $p 님. 저희는 당신이 이 땅에 도착하여 여러 일을 이루어내는 것을 지켜보고 있었습니다.', `MaleText_loc4`='欢迎你，$p。自从你踏上这片土地，我们就一直密切注意着你的才能。', `MaleText_loc5`='歡迎你，$p。自從你踏上我們的土地以來，我們就一直在觀察你的才能。', `MaleText_loc7`='Te doy la bienvenida, $p. Hemos estado siguiendo tus logros desde tu llegada a nuestra tierra.', `FemaleText_loc1`='반가워요, $p 님. 저희는 당신이 이 땅에 도착하여 여러 일을 이루어내는 것을 지켜보고 있었지요.', `FemaleText_loc4`='欢迎你，$p。自从你踏上这片土地，我们就一直密切注意着你的才能。', `FemaleText_loc5`='歡迎你，$p。自從你踏上我們的土地以來，我們就一直在觀察你的才能。', `FemaleText_loc7`='Te doy la bienvenida, $p. Hemos estado siguiendo tus logros desde tu llegada a nuestra tierra.' WHERE `ID`=63873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘을 날아서가 아니고는 여기 오기 힘들죠. 사우록 때문에 말입니다.$b$b물론, 덕분에 안개 속의 주점에 누가 숨어들기도 어렵지요.', `MaleText_loc4`='蜥蜴人阻断了往来这里的交通，只有飞行才能抵达。$b$b当然，也骤然加大了溜进迷雾酒肆的难度。', `MaleText_loc5`='因為薩烏洛克，任何人想用飛行以外的方式來到這裡都很困難。$b$b當然，他們也讓溜出霧隱客棧這件事變得非常困難。', `MaleText_loc7`='Los saurok se lo ponen muy difícil a cualquiera que quiera visitar nuestra tierra y no venga volando.$b$bComo es obvio, esto dificulta mucho el acceso a la Taberna en la Niebla.', `FemaleText_loc1`='하늘을 날아서가 아니고는 여기 오기 힘들죠. 사우록 때문에 말이에요.$b$b물론, 덕분에 안개 속의 주점에 누가 숨어들기도 어렵지요.', `FemaleText_loc4`='蜥蜴人阻断了往来这里的交通，只有飞行才能抵达。$b$b当然，也骤然加大了溜进迷雾酒肆的难度。', `FemaleText_loc5`='因為薩烏洛克，任何人想用飛行以外的方式來到這裡都很困難。$b$b當然，他們也讓溜出霧隱客棧這件事變得非常困難。', `FemaleText_loc7`='Los saurok se lo ponen muy difícil a cualquiera que quiera visitar nuestra tierra y no venga volando.$b$bComo es obvio, esto dificulta mucho el acceso a la Taberna en la Niebla.' WHERE `ID`=63874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 매 조심하십시오. 깨문답니다.', `MaleText_loc4`='小心我的雄鹰。她会咬人的。', `MaleText_loc5`='待在我的老鷹附近時要很小心。她很愛咬人。', `MaleText_loc7`='Ten cuidado con mi hacha, que muerde.', `FemaleText_loc1`='제 매 조심하세요. 깨문답니다.', `FemaleText_loc4`='小心我的雄鹰。她会咬人的。', `FemaleText_loc5`='待在我的老鷹附近時要很小心。她很愛咬人。', `FemaleText_loc7`='Ten cuidado con mi hacha, que muerde.' WHERE `ID`=63875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산길은 매우 위험한 곳이 될 수도 있습니다.', `MaleText_loc4`='山路上可能危机四伏。', `MaleText_loc5`='山路是危險的地方。', `MaleText_loc7`='Las carreteras de las montañas pueden ser muy peligrosas.', `FemaleText_loc1`='산길은 매우 위험한 곳이 될 수도 있지요.', `FemaleText_loc4`='山路上可能危机四伏。', `FemaleText_loc5`='山路是危險的地方。', `FemaleText_loc7`='Las carreteras de la montañas pueden ser muy peligrosas.' WHERE `ID`=63876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매사냥꾼 노룽 님에게 안대에 대해서는 절대 묻지 마십시오. 밤이 새도록 이야기를 늘어놓으실 테니.', `MaleText_loc4`='别问鹰眼大师砮荣他的眼罩是怎么回事。他唠叨起来没完没了。', `MaleText_loc5`='絕對別問鷹大師砮龍關於他的眼罩的問題。他一開始說就停不下來的。', `MaleText_loc7`='No le preguntes nunca a Maestro de halcones Norung sobre su parche del ojo. Te contará una historia interminable.', `FemaleText_loc1`='매사냥꾼 노룽 님에게 안대에 대해서는 절대 묻지 마세요. 밤이 새도록 이야기를 늘어놓으실 테니까요.', `FemaleText_loc4`='别问鹰眼大师砮荣他的眼罩是怎么回事。他唠叨起来没完没了。', `FemaleText_loc5`='絕對別問鷹大師砮龍關於他的眼罩的問題。他一開始說就停不下來的。', `FemaleText_loc7`='No le preguntes nunca a Maestro de halcones Norung sobre su parche del ojo. Te contará una historia interminable.' WHERE `ID`=63877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리해야 할 거다, 깨우는 자여. 이곳은 안전하지 않구나.', `MaleText_loc4`='我们得加快速度了，唤醒者。这里并不安全。', `MaleText_loc5`='我們必須快點工作，喚醒者。這個區域不安全', `MaleText_loc7`='Tenemos que trabajar deprisa, heraldo. Esta área no es segura.' WHERE `ID`=63878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 정신력이 참 강하구나. 지금도 내가 너와 대화하려고 애써야 한다니... 너를 조종하는 것은 거의 불가능하겠다.', `MaleText_loc4`='你的精神很是强大，唤醒者。就连现在，我都在奋力与你交流。想要控制你几乎是不可能的……', `MaleText_loc5`='你的心靈很堅強，喚醒者。就連現在，我都得費盡力氣才能跟你溝通。要控制你幾乎是不可能的事...', `MaleText_loc7`='Tu mente es fuerte, heraldo. Todavía me cuesta comunicarme contigo. Controlarte sería casi imposible...' WHERE `ID`=63879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생각에 호기심이 생기는구나. 네가 하는 일에는 목적이 있다. 네 복잡함이 무척 인상적이구나.', `MaleText_loc4`='你的思想吸引着我。你的行动充满目的性。你的复杂程度令人印象深刻。', `MaleText_loc5`='你的想法讓我很好奇。你的行動中帶有目的。你的複雜程度讓人驚嘆。', `MaleText_loc7`='Tus pensamientos me intrigan. Tus acciones responden a un propósito. Tu complejidad es impresionante.' WHERE `ID`=63880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 지식은 대부분 육체적인 능력만큼이나 전장에서 쓸모가 있을 것이다. 너와 같은 깨우는 자의 마음에는 커다란 잠재력이 보이지.', `MaleText_loc4`='你的心智如同你的战技，迟早会有用武之地。我在你的心神中看到了这样的潜力，唤醒者。', `MaleText_loc5`='在戰場上，你的智慧幾乎就像你的戰鬥技能一樣有用。我在你這樣的心靈中看到許多潛力，喚醒者。', `MaleText_loc7`='Tu inteligencia será casi tan útil como tu destreza en la batalla. Veo mucho potencial en una mente como la tuya, heraldo.' WHERE `ID`=63881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 왔다. 이 무기로 우리는 여제의 군대를 파괴할 것이다!', `MaleText_loc4`='好了。有了这把武器，一定能把女皇的军队打得落花流水！', `MaleText_loc5`='我們到了。有了這個武器，我們將能摧毀女皇的軍隊!', `MaleText_loc7`='Ya hemos llegado. ¡Con esta arma aniquilaremos el ejército de la Emperatriz!' WHERE `ID`=63882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그물을 꽤 잘 다루니 저 고약한 야운골 놈들을 그물로 잡을 수 있을 거요.', `MaleText_loc4`='我擅长投网，我能网住那些可恶的野牛人。', `MaleText_loc5`='我很擅長使用網子，我能把那些討厭的揚古困在網裡面。', `MaleText_loc7`='Tengo bastante maña con estas redes, podría atrapar en ellas a esos sucios yaungol.' WHERE `ID`=63883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 가서 놈들을 묶어 버립시다!', `MaleText_loc4`='好吧，把他们绑起来！', `MaleText_loc5`='好吧，我們去把他們綑起來!', `MaleText_loc7`='¡Muy bien, vamos a atarlos!', `FemaleText_loc1`='좋아요. 가서 놈들을 묶어 버리자고요!', `FemaleText_loc4`='好吧，把他们绑起来！', `FemaleText_loc5`='好吧，我們去把他們綑起來!', `FemaleText_loc7`='¡Muy bien, vamos a atarlos!' WHERE `ID`=63884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮습니다. 그물은 그냥 보관하십시오.', `MaleText_loc4`='没关系，你继续捣鼓那些网吧。', `MaleText_loc5`='那沒問題，你在那些網上撐著。', `MaleText_loc7`='No pasa nada, quédate con esas redes.', `FemaleText_loc1`='괜찮아요. 그물은 그냥 보관하세요.', `FemaleText_loc4`='没关系，你继续捣鼓那些网吧。', `FemaleText_loc5`='那沒問題，你在那些網上撐著。', `FemaleText_loc7`='No pasa nada, quédate con esas redes.' WHERE `ID`=63885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤이 펑이 내려앉습니다!', `MaleText_loc4`='黑风上岸了！', `MaleText_loc5`='黑峰著陸了!', `MaleText_loc7`='¡Hei Feng aterriza!' WHERE `ID`=63886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기 잡는 데는 도가 텄으니, 이번엔 야운골을 잡아 봐야겠군!', `MaleText_loc4`='我已经掌握了捕鱼的技巧，现在要去捕野牛人了！', `MaleText_loc5`='我已經精通捕魚了，現在該進階成捕捉揚古!', `MaleText_loc7`='Ya domino la pesca, ¡así que a pescar yaungol!' WHERE `ID`=63887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 믿음직한 그물이 마을을 저버리지 않을 거요!', `MaleText_loc4`='我和我可靠的渔网一定不会让村庄失望！', `MaleText_loc5`='我和我可靠的網子不會使村子失望!', `MaleText_loc7`='¡Yo y mis fieles redes no decepcionaremos a esta aldea!' WHERE `ID`=63888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지식의 연단에 잘 왔네. 판다리아의 고대에 대한 지식과 지혜가 이토록 많이 보존되어 있는 곳은 또 없다네.', `MaleText_loc4`='欢迎来到闻道之座。这里是蕴藏着潘达利亚古代知识与智慧的伟大宝库。', `MaleText_loc5`='歡迎來到知識之座。你找不到比這裡更棒的關於古代潘達利亞的資訊與智慧的寶庫。', `MaleText_loc7`='Te damos la bienvenida al Trono del Saber. Nunca ha existido un repositorio de información y sabiduría más extenso acerca del pasado de Pandaria.' WHERE `ID`=63889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님이시겠군요.$b$b기다리고 있었어요.', `FemaleText_loc4`='你一定是$n。$b$b我一直在等你。', `FemaleText_loc5`='你一定就是$n了。$b$b我一直在等待著你。', `FemaleText_loc7`='Tú debes ser $n.$b$bTe estaba esperando.' WHERE `ID`=63890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루끼끼 언덕까지 타고 갈 연이 필요합니다.', `MaleText_loc4`='我可以乘坐风筝前往古鲁金山。', `MaleText_loc5`='我需要用風箏飛到葛魯山丘。', `MaleText_loc7`='Me gustaría utilizar una cometa hasta el Cerro Makaku.', `FemaleText_loc1`='그루끼끼 언덕까지 타고 갈 연이 필요해요.', `FemaleText_loc4`='我可以乘坐风筝前往古鲁金山。', `FemaleText_loc5`='我需要用風箏飛到葛魯山丘。', `FemaleText_loc7`='Me gustaría utilizar una cometa hasta el Cerro Makaku.' WHERE `ID`=63891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩔 수 없군. 내가 직접 처리하겠다!', `MaleText_loc4`='那就来吧。我会亲自动手！', `MaleText_loc5`='那就這樣吧。我會親自動手!', `MaleText_loc7`='Está bien. ¡Lo haré por mi cuenta!' WHERE `ID`=63892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 안개를 부립니다. 치유가 필요한 자에게 도움을 줄 수 있지요.', `MaleText_loc4`='我与迷雾同在，疗伤救人。', `MaleText_loc5`='我與迷霧同在並治療需要之人。', `MaleText_loc7`='Soy uno con la niebla y sano a quienes lo necesitan.', `FemaleText_loc1`='저는 안개를 부립니다. 치유가 필요한 자에게 도움을 줄 수 있지요.', `FemaleText_loc4`='我与迷雾同在，疗伤救人。', `FemaleText_loc5`='我與迷霧同在並治療需要之人。', `FemaleText_loc7`='Soy una con la niebla y sano a quienes lo necesitan.' WHERE `ID`=63893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 도움이 필요합니다.', `MaleText_loc4`='我们需要你的帮助。', `MaleText_loc5`='我們需要你的協助。', `MaleText_loc7`='Necesitamos tu ayuda.', `FemaleText_loc1`='당신의 도움이 필요해요.', `FemaleText_loc4`='我们需要你的帮助。', `FemaleText_loc5`='我們需要你的協助。', `FemaleText_loc7`='Necesitamos tu ayuda.' WHERE `ID`=63894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 치유 능력은 필요없습니다.', `MaleText_loc4`='我们不需要你的治疗技能。', `MaleText_loc5`='我們不需要你的治療技巧。', `MaleText_loc7`='No necesitamos tus habilidades sanadoras.', `FemaleText_loc1`='당신의 치유 능력은 필요없어요.', `FemaleText_loc4`='我们不需要你的治疗技能。', `FemaleText_loc5`='我們不需要你的治療技巧。', `FemaleText_loc7`='No necesitamos tus habilidades sanadoras.' WHERE `ID`=63895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, 용사여. 우리 모두를 구해줬군.', `MaleText_loc4`='谢谢你，$p。你救了我们大家。', `MaleText_loc5`='謝謝你，$p。勇士，你救了我們大家。', `MaleText_loc7`='Muchas gracias. Nos has salvado a todos.' WHERE `ID`=63896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 귀찮은 전승지기 놈에게서 필요한 건 다 얻었다.', `MaleText_loc4`='我们已经从那好管闲事的游学者身上得到需要的东西了。', `MaleText_loc5`='我們已經從那愛管閒事的博學大師得到我們需要的東西。', `MaleText_loc7`='Tenemos lo que necesitamos del eremita entrometido.' WHERE `ID`=63897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해가 뜨기 전이 가장 어둡다는 것을 기억하게나.', `MaleText_loc4`='记住，正是在最黑暗的时刻，光明才格外耀眼。', `MaleText_loc5`='別忘了，最黑暗的時候，也是光明最耀眼的時刻。', `MaleText_loc7`='Recuerda: en la hora más oscura, la luz brilla con más fuerza.' WHERE `ID`=63898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네.', `MaleText_loc4`='干得好，英雄们。', `MaleText_loc5`='做得好，各位英雄。', `MaleText_loc7`='Bien hecho, héroes.' WHERE `ID`=63899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원에 침입한 자가 있습니다!', `MaleText_loc4`='入侵者攻进了寺院！', `MaleText_loc5`='入侵者已經突破神廟了!', `MaleText_loc7`='¡Han entrado intrusos en el templo!' WHERE `ID`=63900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해 빠진 도마뱀 같으니! 네 가죽으로 천둥왕 폐하의 왕좌를 장식해야겠다!', `MaleText_loc4`='软弱的蜥蜴！我要用你的皮装饰雷电之王的御座！', `MaleText_loc5`='孱弱的蜥蜴!你的皮將成為雷王王座的裝飾品!', `MaleText_loc7`='¡LAGARTO DEBILUCHO! ¡Tu pellejo adornará el trono del Rey del Trueno!' WHERE `ID`=63901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퉁! 네놈의 시체를 네놈이 기르는 쓸모없는 야수들에게 먹이로 줘야겠구나!', `MaleText_loc4`='唐骨！我要把你们这些没用的畜生大卸八块！', `MaleText_loc5`='湯!我要把你的屍體拿去餵你那些沒用的野獸!', `MaleText_loc7`='¡TUNG! ¡Tu cadáver alimentará a tus bestias inútiles!' WHERE `ID`=63902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓸모없는 도마뱀 같으니! 감히 천둥왕 폐하께 실망을 드리다니!', `MaleText_loc4`='没用的巫师！你竟敢让雷电之王失望！', `MaleText_loc5`='廢物巫師!你竟膽敢讓雷王失望!', `MaleText_loc7`='¡Mago inútil! ¿Cómo te atreves a fallarle al Rey del Trueno?' WHERE `ID`=63903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장 로구? 이럴 수가! 지금 와서 이렇게 쓰러질 줄이야...', `MaleText_loc4`='统领容古？！不可能！你现在居然退却了……', `MaleText_loc5`='露骨隊長?!不可能!想到你們現在會畏縮...', `MaleText_loc7`='¡¿EL CAPITÁN RO-GU?! ¡Imposible! Pensar que pudieras flaquear ahora...' WHERE `ID`=63904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영예로운 천둥왕 레이 션 폐하의 전령인 나, 장군 준이 너희에게 결투를 청하노라!', `MaleText_loc4`='我，尊贵的雷电之王雷神的使者，烛恒将军，前来向你挑战！', `MaleText_loc5`='我，曾將軍，榮耀的雷王雷神的傳令官，在此向你挑戰!', `MaleText_loc7`='¡Yo, el general Zhun, heraldo del glorioso Rey del Trueno Lei Shen, os desafío!' WHERE `ID`=63905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로구, 퉁, 폰, 히디스! 유물을 지켜라! 목숨을 바쳐서라도!', `MaleText_loc4`='容古、唐骨、冯恩、希提斯——用你们的生命……守住神器！', `MaleText_loc5`='露骨、湯、馮、黑西絲:好好的守衛這些神器...就算要用你們的性命!', `MaleText_loc7`='Ro-Gu, Tung, Fon, Hithiss: Cuiden los artefactos... ¡con sus VIDAS!' WHERE `ID`=63906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 속으로는 제가 나무꾼이라고 생각했습니다!', `MaleText_loc4`='我早知道自己有着一颗伐木工的心！', `MaleText_loc5`='我早就知道我是個天生的樵夫!', `MaleText_loc7`='¡Siempre supe que había nacido para ser leñador!', `FemaleText_loc1`='항상 속으로는 제가 나무꾼이라고 생각했어요!', `FemaleText_loc4`='我早知道自己有着一颗伐木工的心！', `FemaleText_loc5`='我早就知道我是個天生的樵夫!', `FemaleText_loc7`='¡Siempre supe que había nacido para ser leñadora!' WHERE `ID`=63907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공예가의 기질이 보이는군요, $p 님. 목공예가로서 나무를 잘라낼 수 있겠습니까? 그러시다면 제가 도움될 만한 물건을 좀 드리겠습니다.', `MaleText_loc4`='你看起来像个手艺人，$pc。你能像木匠那样切割么？要是可以，我倒是有东西能帮上你的忙。', `MaleText_loc5`='你看起來像位工匠，$pc。你覺得你能像個木匠一樣工作嗎?如果可以，我有些幫得上你的東西。', `MaleText_loc7`='Tienes pinta de $gartesano:artesana;, $pc. ¿Crees que vales para ebanista? Si es así, tengo algo que podría serte de ayuda.' WHERE `ID`=63908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진주지느러미 마을로 가는 연이 필요합니다.', `MaleText_loc4`='我要坐风筝前往珠鳍村。', `MaleText_loc5`='我需要用風箏飛到珠鰭村。', `MaleText_loc7`='Me gustaría utilizar una cometa hasta el Poblado Aleta de Nácar.', `FemaleText_loc1`='진주지느러미 마을로 가는 연이 필요해요.', `FemaleText_loc4`='我要坐风筝前往珠鳍村。', `FemaleText_loc5`='我需要用風箏飛到珠鰭村。', `FemaleText_loc7`='Me gustaría utilizar una cometa hasta el Poblado Aleta de Nácar.' WHERE `ID`=63909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 다시 만나서 반갑습니다. 제 미끼는 어떻던가요?', `MaleText_loc4`='又见面了，$n。我的鱼饵怎么样？', `MaleText_loc5`='哈囉又見面了，$n。我的魚餌好用嗎?', `MaleText_loc7`='Hola de nuevo, $n. ¿Cómo te va con mi señuelo?' WHERE `ID`=63910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 다시 만나서 반갑습니다. 제 도끼는 어떻던가요?', `MaleText_loc4`='又见面了，$n。我的斧子怎么样？', `MaleText_loc5`='哈囉又見面了，$n。我的斧頭好用嗎?', `MaleText_loc7`='Hola de nuevo, $n. ¿Cómo te va con mi hacha?' WHERE `ID`=63911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나중에 다시 뵙겠습니다, $n 님.', `MaleText_loc4`='下次再见吧，$n。', `MaleText_loc5`='下次再會囉，$n。', `MaleText_loc7`='Hasta la próxima, $n.' WHERE `ID`=63912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜는 잊지 않겠네. 죽는 줄만 알았네.', `MaleText_loc4`='我将永远感激你，我还以为自己死定了。', `MaleText_loc5`='我會永遠感激你;我以為我死定了。', `MaleText_loc7`='Mi eterna gratitud; creía que era mi fin.' WHERE `ID`=63913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숨겨진 이야기가 너무 많아요. 역사도요. 정말 흥미롭지 않나요?', `FemaleText_loc4`='还有那么多精彩的故事等着我们去探寻。那么多历史。难道不使人着迷吗？', `FemaleText_loc5`='有許多偉大的故事可以發掘。這麼多的歷史，很迷人不是嗎?', `FemaleText_loc7`='Hay muchas historias que descubrir. Mucha historia. ¿Nos es fascinante?' WHERE `ID`=63914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주로, 처형을 시작해라!', `MaleText_loc4`='裘诺：处决他！', `MaleText_loc5`='酒肉:處決他!', `MaleText_loc7`='Juro: ¡EJECÚTALO!' WHERE `ID`=63915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 살 수 있을 거라곤 기대도 안 했습니다... 최선을 다해 돕겠습니다!', `MaleText_loc4`='谢谢！我们都没想到能活下来……我会尽我所能帮助你！', `MaleText_loc5`='謝謝!我們都沒想過還能存活下來...我會盡全力支援你!', `MaleText_loc7`='¡Gracias! Ninguno de nosotros esperaba sobrevivir... ¡Os ayudaré lo mejor que pueda!' WHERE `ID`=63916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나머지 사람들은 이미 끌려가서 죽임을 당했습니다. 죄송하지만... 몸이 말을 듣지 않아 더 갈 수가 없군요.', `MaleText_loc4`='他们已经拖走并杀害了其余的人。对不起……我太虚弱了，不能继续了……', `MaleText_loc5`='他們把其他人拖走並殺害了。我很抱歉...我太虛弱了，無法繼續...', `MaleText_loc7`='Ya han sacado y asesinado a los demás. Lo siento... estoy muy débil para continuar.' WHERE `ID`=63917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 가능하다면 전승지기 푸 님을 구해 주십시오... 저는... 실패했습니다...', `MaleText_loc4`='谢谢你！请你，救救……游学者福云，如果你可以的话……我……失败了……', `MaleText_loc5`='謝謝你!拜託，如果可以的話...救救博學行者傅...我...失敗了...', `MaleText_loc7`='¡Gracias, gracias! Por favor, salvad al eremita Fu si podéis... Yo... he fracasado...' WHERE `ID`=63918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 아주 위험한 곳에 발을 들였어요. 사우록이 엄청 화 나서 지나가는 모든 배를 공격해요. 우린 조심해야 해요.', `MaleText_loc4`='我们已经进入了危险地带，宝贝儿。蜥蜴人在这里变得极为狂暴，会把途径此地的所有船只统统击沉。我们千万要多加小心。', `MaleText_loc5`='我的幸運星啊，我們已經進入了一個危險的地方。在此的薩烏洛克變得非常憤怒並攻擊所有經過這裡的船隻。我們必須提高戒備。', `MaleText_loc7`='Nos hemos adentrado en un lugar peligroso, mi grisgrís. Aquí, los saurok se han vuelto rabiosos y están atacando a todos los botes que pasan. No debemos bajar la guardia.' WHERE `ID`=63919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 준은 코트모구의 사원의 고대 유물을 사악한 주군, 천둥왕에게 바치려고 한다네. 보고 있을 수만은 없네!', `MaleText_loc4`='烛恒将军准备把寇魔古寺的古代神器交给他的邪恶君主，雷电之王。我们不能让这种情况发生！', `MaleText_loc5`='曾將軍計畫將科特魔古神廟的古代神器進貢給他邪惡的主子，雷王。我們不能讓這件事發生!', `MaleText_loc7`='El general Zhun pretende entregarle los antiguos artefactos del Templo de Kotmogu a su malvado señor, el Rey del Trueno. ¡No podemos permitirlo!' WHERE `ID`=63920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디, 유물이 장군의 손에 들어가지 않게 해 주게! 나는 영원꽃 골짜기로 돌아가 황금 연꽃에 이 사실을 알려야겠네. 다시 한 번 감사하네.', `MaleText_loc4`='拜托了，一定不能让它们落入将军的手里！我要返回锦绣谷向金莲报告。再次感谢！', `MaleText_loc5`='求求你，你不能讓將軍得到它們!我將回到恆春谷向金蓮會報告。再一次地，非常謝謝你!', `MaleText_loc7`='¡Por favor, tenéis que evitar que lleguen a manos del general! Volveré al Valle de la Flor Eterna a informar al Loto Dorado. ¡Gracias de nuevo!' WHERE `ID`=63921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 기대가 가득한 눈으로 당신을 바라봅니다.>', `MaleText_loc4`='<米师满怀期待地望着你。>', `MaleText_loc5`='<米什期待地看著你。>', `MaleText_loc7`='<Mishi te mira expectante.>' WHERE `ID`=63922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘부터 당신은 음영파의 일원입니다.', `MaleText_loc4`='今天，我们欢迎你加入影踪派。', `MaleText_loc5`='今天，我們歡迎你加入影潘。', `MaleText_loc7`='Hoy te damos la bienvenida al Shadopan.' WHERE `ID`=63923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 인내심이 우릴 강하게 하고, 용기가 우릴 이끌고, 명예가 우릴 일깨우지요.', `MaleText_loc4`='你的毅力壮大着我们。你的勇气指引着我们。你的荣耀激励着我们。', `MaleText_loc5`='你的毅力給我們力量，你的勇氣引領我們，你的榮譽激勵了我們。', `MaleText_loc7`='Tu perseverancia nos fortalece. Tu coraje nos dirige. Tu honor nos inspira.' WHERE `ID`=63924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘부터 당신은 우리와 함께 한 길을 가는 겁니다.', `MaleText_loc4`='从今天起，你就是我们的同胞手足。', `MaleText_loc5`='從今天開始，你就是我們兄弟的一員了。', `MaleText_loc7`='De hoy en adelante serás de los nuestros.' WHERE `ID`=63925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파의 일원이 된 것을 축하합니다!', `MaleText_loc4`='欢迎你，$p，影踪派的同胞！', `MaleText_loc5`='歡迎，$p。影潘的一份子!', `MaleText_loc7`='Te damos la bienvenida, miembro del Shadopan.' WHERE `ID`=63926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도, 이 마을도 저버리지 않겠습니다.', `MaleText_loc4`='我不会让你和这村子失望。', `MaleText_loc5`='我不會讓你，或這個村子失望。', `MaleText_loc7`='No te fallaré ni a ti ni a esta aldea.', `FemaleText_loc1`='당신도, 이 마을도 저버리지 않겠어요.', `FemaleText_loc4`='我不会让你和这村子失望。', `FemaleText_loc5`='我不會讓你，或這個村子失望。', `FemaleText_loc7`='No te fallaré ni a ti ni a esta aldea.' WHERE `ID`=63927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 우물을 지키는 일을 맡았어. 아주 중요한 일이지!', `MaleText_loc4`='我奉命守卫这口井。这是重要的任务！', `MaleText_loc5`='我得要守衛這口井。這是重要的工作!', `MaleText_loc7`='Mi deber es proteger el pozo. ¡Es un trabajo importante!' WHERE `ID`=63928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구들은 나더러 느리다지만, 나는 걔들보다 뜀박질이 빨라!', `MaleText_loc4`='朋友们说我有些慢，可我比他们所有人跑得都快！', `MaleText_loc5`='我的朋友們說我有點遲緩，但我跑得比他們都還要快!', `MaleText_loc7`='Mis amigos dicen que soy un poco lento, ¡pero corro más rápido que todos ellos!' WHERE `ID`=63929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우물은 아주 중요해. 나한테 지키라고 하길 잘한 거야.', `MaleText_loc4`='这口井至关重要。幸好他们派我来看守它。', `MaleText_loc5`='這口井非常重要。還好他們要我看著它。', `MaleText_loc7`='El pozo es muy importante. Menos mal que me han pedido que lo vigile.' WHERE `ID`=63930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 "코아, 가서 우물을 지켜."라고 말했어.', `MaleText_loc4`='“科亚”，他们说，“去看守水井。”他们就说了这些。', `MaleText_loc5`='『寇亞』，他們說，『去看守水井』。他們是這麼說的。', `MaleText_loc7`='"Koa", me dijeron, "Ve y protege el pozo". Eso es lo que me dijeron.' WHERE `ID`=63931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 다들 이렇게 겁에 질린 거지? 트롤이 우리 우물에 못 오게 할 거야! 나는 뛰어난 경비병이니까!', `MaleText_loc4`='大家为什么都这么害怕？我不会让那些巨魔接近我们的水井！我是个合格的守卫！', `MaleText_loc5`='為什麼每個人都這麼害怕?我不會讓那些食人妖接近我們的井!我是個好守衛!', `MaleText_loc7`='¿Por qué tiene miedo la gente? ¡No dejaré que los trols lleguen al pozo! ¡Soy un buen guardia!' WHERE `ID`=63932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 나는 코아야! 내 친구가 돼 줄래?', `MaleText_loc4`='你好！我是科亚！你愿意跟我做朋友吗？', `MaleText_loc5`='嗨!我是寇亞!你能當我的朋友嗎?', `MaleText_loc7`='¡Hola! ¡Soy Koa! ¿Podemos ser amigos?' WHERE `ID`=63933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신에게 죽음에서 삶을 끌어내는 능력을 줄 수 있습니다.', `MaleText_loc4`='我能让你从死亡中获得生命。', `MaleText_loc5`='我能讓你起死回生。', `MaleText_loc7`='Puedo permitirte obtener vida de la muerte.' WHERE `ID`=63934;
