UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 모두 죽을 거야!', `MaleText_loc4`='我们都要死了！', `MaleText_loc5`='我們全都會死!', `MaleText_loc7`='¡Vamos a morir!', `FemaleText_loc1`='왜 우릴 공격하는 거지?!', `FemaleText_loc4`='他们为什么要攻击我们？！', `FemaleText_loc5`='他們為什麼攻擊我們?!', `FemaleText_loc7`='¡¿Por qué nos atacan?!' WHERE `ID`=63937;
