UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무슨 일이 벌어지고 있습니다. 정확히 어떤 성질의 것인지는 분명하지 않습니다.', `MaleText_loc4`='这里发生了一些事情。具体的情况还有待进一步查明。', `MaleText_loc5`='這裡有些不對勁。但又說不上來到底是什麼。', `MaleText_loc7`='Algo pasa aquí. Aunque su naturaleza exacta no está clara.', `FemaleText_loc1`='여기서 무슨 일이 벌어지고 있습니다. 정확히 어떤 성질의 것인지는 분명하지 않습니다.', `FemaleText_loc4`='这里发生了一些事情。具体的情况还有待进一步查明。', `FemaleText_loc5`='這裡有些不對勁。但又說不上來到底是什麼。', `FemaleText_loc7`='Algo pasa aquí. Aunque su naturaleza exacta no está clara.' WHERE `ID`=63939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보호모는 꼭 마법 같아요. 한번 써 보시겠습니까? 남는 게 있거든요!', `MaleText_loc4`='这帽子有魔力，你想试试吗？我们还有多余的！', `MaleText_loc5`='這個盔帽就像魔法一樣，你想試試嗎?我們還有多的!', `MaleText_loc7`='Este casco parece mágico, ¿quieres probarlo? ¡Tenemos de sobra!', `FemaleText_loc1`='이 보호모는 꼭 마법 같아요. 한번 써 보시겠어요? 남는 게 있거든요!', `FemaleText_loc4`='这帽子有魔力，你想试试吗？我们还有多余的！', `FemaleText_loc5`='這個盔帽就像魔法一樣，你想試試嗎?我們還有多的!', `FemaleText_loc7`='Este casco parece mágico, ¿quieres probarlo? ¡Tenemos de sobra!' WHERE `ID`=63940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지요!', `MaleText_loc4`='当——然！', `MaleText_loc5`='絕-對-要!', `MaleText_loc7`='¡Por supuesto!', `FemaleText_loc1`='물론이죠!', `FemaleText_loc4`='当——然！', `FemaleText_loc5`='絕-對-要!', `FemaleText_loc7`='¡Por supuesto!' WHERE `ID`=63941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮습니다. 침략 때문에 정신을 똑바로 차려야 하니까요.', `MaleText_loc4`='不用了，谢谢，我必须时刻提防入侵。', `MaleText_loc5`='不了，謝謝，我想要對入侵保持戒備。', `MaleText_loc7`='No, gracias, tengo que estar alerta para la invasión.', `FemaleText_loc1`='괜찮아요. 침략 때문에 정신을 똑바로 차려야 하니까요.', `FemaleText_loc4`='不用了，谢谢，我必须时刻提防入侵。', `FemaleText_loc5`='不了，謝謝，我想要對入侵保持戒備。', `FemaleText_loc7`='No, gracias, tengo que estar alerta para la invasión.' WHERE `ID`=63942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 평소엔 평화로운 나루터였는데, 어쩌다 이렇게 됐는지 원. 이 야운골이 다 어디에서 몰려온 거지?', `MaleText_loc4`='这里一向风平浪静。可你看看现在。这些野牛人是从哪儿来的？', `MaleText_loc5`='通常這是很平靜的一站。現在看看它。這所有的揚古都是從哪裡來的?', `MaleText_loc7`='Esta suele ser una parada tranquila. Pero mira ahora... ¿De dónde han salido todos estos yaungol?' WHERE `ID`=63943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북서쪽으로 가실 거면 그루멀 시장을 찾아보세요. 좋은 장신구랑 복덩이 많이 팔아요. 복은 찾는 자에게 가는 거예요.', `MaleText_loc4`='如果你往西北走，可以去土地精集市逛逛。那有许多好看的饰品和幸运符。光顾那里的人总能交上好运。', `MaleText_loc5`='如果你往西北方走，留意尋找咕嚕摩市集。那裡有賣許多的好飾品和幸運星。會給尋求幸運的人帶來好運。', `MaleText_loc7`='Si te diriges al noroeste, busca el Bazar Grúmel. Allí hay muy buenos abalorios y grisgrís a la venta. Traen buena fortuna a aquellos que la buscan.' WHERE `ID`=63944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바타리 전투 설인이 고대의 통로 쪽에서 다가옵니다!', `MaleText_loc4`='一只巴塔里战斗雪人从远古之路过来了！', `MaleText_loc5`='一個巴塔利戰爭雪人從上古通道方向接近了!', `MaleText_loc7`='¡Se acerca un yeti de guerra Bataari desde el Pasaje Antiguo!' WHERE `ID`=63945;
