UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 맥주달 축제가 정말 좋습니다. 매년 목이 빠지게 기다리지요.', `MaleText_loc4`='我喜欢酿月祭，每年都期盼着这节日的到来。', `MaleText_loc5`='我愛死酒月節了，我每年都期待它的到來。', `MaleText_loc7`='Me encanta el Festival de la Cerveza Lunar, cada año estoy deseando que llegue.', `FemaleText_loc1`='전 맥주달 축제가 정말 좋아요. 매년 목이 빠지게 기다려요.', `FemaleText_loc4`='我喜欢酿月祭，每年都期盼着这节日的到来。', `FemaleText_loc5`='我愛死酒月節了，我每年都期待它的到來。', `FemaleText_loc7`='Me encanta el Festival de la Cerveza Lunar, cada año estoy deseando que llegue.' WHERE `ID`=63950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크. 야크는 절대 변하질 않지요.', `MaleText_loc4`='牦牛。牦牛从不改变。', `MaleText_loc5`='犛牛。犛牛永遠不變。', `MaleText_loc7`='Yak. El yak nunca cambia.' WHERE `ID`=63951;
