UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 가면 위험한가요?', `MaleText_loc4`='一个人去很危险吧？', `MaleText_loc5`='自己過去會有危險嗎?', `MaleText_loc7`='¿Es peligroso ir solo?' WHERE `ID`=63953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁인데 쿤라이로 돌아가는 길을 알려 주실 수 있으세요?', `MaleText_loc4`='你能好心告诉我怎么回昆莱吗？', `MaleText_loc5`='你願意好心的告訴我怎麼回到崑萊嗎?', `MaleText_loc7`='¿Serías tan amable de decirme cómo volver a Kun-Lai?' WHERE `ID`=63954;
