UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 살덩이와 맥주로 이루어진 한심한 동물일 뿐이에요.', `MaleText_loc4`='我只不过是个胡吃海喝的可怜虫。', `MaleText_loc5`='我只是由肉和酒構成的可悲生物。', `MaleText_loc7`='Solo soy una criatura patética de carne y cerveza.' WHERE `ID`=63957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 날씨와 좋은 맥주와 좋은 생선... 뭘 더 바라겠소?', `MaleText_loc4`='风和日丽，醇酒佳酿，肥美鲜鱼，还有什么不满足的？', `MaleText_loc5`='美好的一天、一瓶美味的酒，和一條鮮美的魚，你還能奢求什麼?', `MaleText_loc7`='Una día maravilloso, una cerveza maravillosa y un pescado maravilloso, ¿qué más se puede pedir?' WHERE `ID`=63958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많이 넣으면 많이 들어가지요.', `MaleText_loc4`='放入越多，进去越多。', `MaleText_loc5`='塞的東西越多，進去的東西就越多。', `MaleText_loc7`='Si metes más cosas en la cosa, entran más cosas.' WHERE `ID`=63959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 판다렌과는 잘 어울리지 않지만, 맥주를 위해서라면 어울리지요!', `MaleText_loc4`='我很少和熊猫人交流，一旦交流……必定与美酒有关！', `MaleText_loc5`='我並沒有經常和熊貓人來往，但當我如此做時...是為了酒!', `MaleText_loc7`='No suelo interactuar con los pandaren, pero cuando lo hago... ¡es por la cerveza!' WHERE `ID`=63960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 예쁜 걸 깔고 앉다니 너무해요.', `MaleText_loc4`='坐在这么漂亮的东西上面真是不好意思。', `MaleText_loc5`='坐在這麼漂亮的東西上真浪費。', `MaleText_loc7`='Es una pena quedarse sentado encima de algo tan bonito.' WHERE `ID`=63961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 맥주통 던지기 대회에서 6년 연속 우승했습니다. 판다리아 최강이지요!', `MaleText_loc4`='我是连续六届投掷美酒大赛的冠军！我是全潘达利亚的最强者。', `MaleText_loc5`='我已經連續衛冕投擲啤酒大賽六年了!我是全潘達利亞最強壯的人。', `MaleText_loc7`='¡He ganado el concurso de lanzamiento de cerveza seis años seguidos! Soy el más fuerte de toda Pandaria.', `FemaleText_loc1`='전 맥주통 던지기 대회에서 6년 연속 우승했어요. 판다리아 최강이죠!', `FemaleText_loc4`='我是连续六届投掷美酒大赛的冠军！我是全潘达利亚的最强者。', `FemaleText_loc5`='我已經連續衛冕投擲啤酒大賽六年了!我是全潘達利亞最強壯的人。', `FemaleText_loc7`='¡He ganado el concurso de lanzamiento de cerveza seis años seguidos! Soy la más fuerte de toda Pandaria.' WHERE `ID`=63962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈이란 게 이런 걸까?', `MaleText_loc4`='做梦的感觉就是这样吗？', `MaleText_loc5`='這就是做夢的感覺嗎?', `MaleText_loc7`='¿Así son los sueños?' WHERE `ID`=63963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주달 축제는 수련을 하다가 잠시 머리를 식히기에 딱 좋습니다.', `MaleText_loc4`='我发现酿月祭是个让我暂别研究，劳逸结合的好机会。', `MaleText_loc5`='我發覺酒月節是讓我從修行中忙裡偷閒的好機會。', `MaleText_loc7`='El Festival de la Cerveza Lunar es un excelente descanso de mis estudios.' WHERE `ID`=63964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='십 년이에요. 전 십 년 동안 성실하게 야크 털을 빗었어요.', `MaleText_loc4`='十年了。我任劳任怨地刷牦牛十年了。', `MaleText_loc5`='十年。我忠實地刷洗了十年的犛牛。', `MaleText_loc7`='Diez años. Llevo cepillando yaks diez años.' WHERE `ID`=63965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야크와 말싸움을 할 때는 이론이 두 개 있어야 해요. 둘 다 안 먹히지만요.', `MaleText_loc4`='在与牦牛争论时有两大理论。可哪个也不起作用。', `MaleText_loc5`='對犛牛講道理是沒有用的。', `MaleText_loc7`='Hay dos teorías para discutir con un yak. Ninguna funciona.' WHERE `ID`=63966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 여기 왔더니 순무가 있더라고요. 진짜예요!', `MaleText_loc4`='我只是来找芜菁的，我发誓！', `MaleText_loc5`='我只是來找幾顆菜頭的，我發誓!', `MaleText_loc7`='¡Solo he venido a buscar nabas, lo juro!' WHERE `ID`=63967;
