UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장막의 계단은 곧 다시 우리 것이 되리라!', `MaleText_loc4`='隐秘阶梯很快就会回到我们手里！', `MaleText_loc5`='朦朧天梯很快就會回到我們手中!', `MaleText_loc7`='¡La Escalera Velada será nuestra de nuevo muy pronto!' WHERE `ID`=64016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤가 판다렌을 약화시켰다! 지금이 바로 놈들을 장막의 계단에서 영원히 몰아낼 때다!', `MaleText_loc4`='煞弱化了熊猫人！是时候将他们彻底赶出隐秘阶梯了！', `MaleText_loc5`='煞已經削弱了熊貓人!現在是將他們永遠驅離朦朧天梯的好時機!', `MaleText_loc7`='¡El sha ha debilitado a los pandaren! Es hora de echarles de la Escalera Velada para siempre!' WHERE `ID`=64017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='털기 딱 좋은 여행자들이구나! 짐을 빼앗아라! 전부 빼앗아 버려!', `MaleText_loc4`='这些旅行者真是绝佳的抢劫目标！把他们的东西抢走！把他们的东西全都抢走！！！', `MaleText_loc5`='這些旅人是大肥羊!搶走他們的東西!搶走他們所有的東西!!!', `MaleText_loc7`='¡Estos viajeros están listos para que les roben! ¡Coged sus cosas! ¡Coged todas sus cosas!' WHERE `ID`=64018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전부 빼앗아! 하나도 남김없이 털어 버려!', `MaleText_loc4`='全都偷走！把他们所有的东西都偷走！', `MaleText_loc5`='偷走每個東西!偷走他們所有的東西!', `MaleText_loc7`='¡Robadles todos! ¡Robadles todos lo que lleven!' WHERE `ID`=64019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 고야 마님을 섬기는 "회수 전문가"일세. 이 길을 여행자들이 자유롭게 오갈 수 있도록 하는 게 마님의 뜻이지.$b$b그리고 내 역할은, 특정 비양심적인 놈들이 마님의 호의를 이용하는 걸 막는 거고 말일세.', `MaleText_loc4`='我是郭雅夫人的“救援专家”。是她的意愿引导着这条道路上来来往往的人流。$b$b我的职责是确保某些贪得无厌的人不要滥用她的热情款待。', `MaleText_loc5`='我是夫人苟雅女士的「討取專家」。這條路上的交通往來都是由她的意志所掌管。$b$b而我的角色就是確保某些肆無忌憚的人不會佔夫人好客心的便宜。', `MaleText_loc7`='Yo soy el "experto cobrador" de la señora Goya. Es su voluntad la que guía el ir y venir de los viajeros por este camino.$b$bEs mi función asegurarme que de los menos escrupulosos no se aprovechen de la hospitalidad de la señora.' WHERE `ID`=64020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어를 단단히 하십시오. 웅가 잉구 해적은 무시무시한 놈들입니다. 맥주는 잘 만들지만요!', `MaleText_loc4`='多加小心。盎迦猴岛的海盗非常可怕。可他们酿的酒不错！', `MaleText_loc5`='提高警覺。仰加印古的海盜們令人聞風喪膽。但他們也懂得釀造好酒!', `MaleText_loc7`='No bajes la guardia. Los piratas de Unga Ingoo son temibles. ¡Pero hacen un brebaje magnífico!' WHERE `ID`=64021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주가 더 필요합니다. 남서쪽의 해적선을 찾아 보면 있을지도 모르겠군요.', `MaleText_loc4`='我们需要更多美酒。可以到西南边的海盗船上找找看。', `MaleText_loc5`='我們需要更多酒。西南方的海盜船也許值得一探。', `MaleText_loc7`='Necesitamos más brebaje. Un buen sitio para buscar podría ser el barco pirata al suroeste.' WHERE `ID`=64022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주가 더 필요합니다. 북서쪽의 섬을 찾아 보는 게 어떨지요? 그쪽 해변에서 잔치가 벌어지는 모습을 본 것 같습니다.', `MaleText_loc4`='我们需要更多美酒。你应该去西北边的岛上找找。我想我看见那边有海滩派对。', `MaleText_loc5`='我們需要更多酒。你應該去西北方的島嶼搜尋。我想我看到那裡有個海灘派對。', `MaleText_loc7`='Necesitamos más brebaje. Deberías buscar en la isla al noroeste. Me pareció ver una fiesta en la playa por allí.' WHERE `ID`=64023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주가 더 필요합니다. 여기서 서쪽에 있는 해변 동굴에 보관되어 있을지도 모릅니다.', `MaleText_loc4`='我们需要更多美酒。沿海岸西边的洞穴里也许还有存货。', `MaleText_loc5`='我們需要更多酒。也許有些酒被藏匿在沿著海岸向西走的洞窟中。', `MaleText_loc7`='Necesitamos más brebaje. En la cueva al oeste de aquí, junto a la playa, podría haber un poco.' WHERE `ID`=64024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주가 더 필요합니다. 남동쪽의 산봉우리에서 호젠들이 술을 퍼 마시는 걸 본 것 같습니다.', `MaleText_loc4`='我们需要更多美酒。我好像看见猢狲在东南边的山峰上狂饮作乐。', `MaleText_loc5`='我們需要更多酒。我想我看到在東南方的山頂上有飲酒作樂的猴人。', `MaleText_loc7`='Necesitamos más brebaje. Me pareció ver a unos hozen bebiendo brebajes en la montaña al sureste.' WHERE `ID`=64025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도대체 누가 맥주 옆에 폭탄 더미와 대포를 두겠습니까? 뭐, 잘됐지요. 호젠에겐 쓰레기일지 몰라도, 양조사에게는 해변 방어 수단이 되니까요.', `MaleText_loc4`='谁会把一堆炸弹和一门大炮放在自己的美酒旁边？啊，好吧。猢狲眼里的垃圾，到了酿酒师这，就会变成海岸防御工事。', `MaleText_loc5`='誰會沒事在他們的酒旁邊放著一堆炸彈和一門大砲?啊隨便啦。猴人不要的垃圾剛好可以用來當作釀酒大師的海灘防禦工事。', `MaleText_loc7`='¿Quién dejaría un montón de bombas y un cañón al lado de su brebaje? En fin. La basura de un hozen es la defensa en la playa de un maestro cervecero.' WHERE `ID`=64026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 우끼 선장이라고? 전설 속의 인물인 줄만 알았는데.', `MaleText_loc4`='噢不！乌克头领？我以为他只是传说。', `MaleText_loc5`='喔不!烏克船長?我以為他只是個傳說。', `MaleText_loc7`='¡Oh, no! ¿El capitán Ook? Creía que no era más que una leyenda.' WHERE `ID`=64027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 맥주를 잔과 통에 담아서 온 섬에 흩어 놓은 것 같습니다.', `MaleText_loc4`='看来猢狲把酒杯和酒桶弄得满岛都是。', `MaleText_loc5`='看來猴人把他們的酒裝在酒杯和酒桶中散佈在整個島上。', `MaleText_loc7`='Parece que los hozen han desperdigado su brebaje en jarras y barriles por toda la isla.' WHERE `ID`=64028;
