UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침 판다리아 전역에서 손님들이 와 있으니, 도움을 받을 수 있을 거예요.', `FemaleText_loc4`='我们这儿有来自潘达利亚各地的造访者，他们肯定可以帮助我们解决这些掠夺者。', `FemaleText_loc5`='在潘達利亞到處都有許多的來訪者，無疑地他們會幫助我們抵抗這些劫掠者。', `FemaleText_loc7`='Tenemos muchos visitantes de toda Pandaria, seguro que pueden ayudarnos con estos asaltantes.' WHERE `ID`=64054;
