UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈안 낚시꾼에 대해서 이야기해 주십시오.', `MaleText_loc4`='告诉我关于滨岸渔民的事情。', `MaleText_loc5`='告訴我關於濱南漁夫的事。', `MaleText_loc7`='Háblame de los pescadores de Binan.', `FemaleText_loc1`='빈안 낚시꾼에 대해서 이야기해 주세요.', `FemaleText_loc4`='告诉我关于滨岸渔民的事情。', `FemaleText_loc5`='告訴我關於濱南漁夫的事。', `FemaleText_loc7`='Háblame de los pescadores de Binan.' WHERE `ID`=64066;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='크라사랑 밀림 맥주는 아주 폭발성이 크답니다! 야운골이 접근하는 곳 근처에 맥주통을 놓아두고 터뜨리면 돼요. 맥주통을 하나 집으면 제가 어디에 둬야 할지 표시해 드리지요.', `FemaleText_loc4`='卡桑琅荒原啤极其易爆，$n！我们可以将酒桶放在野牛人的必经之路上，然后点火。拿上酒桶，我会做好标记，告诉你应该把它们放在哪里。', `FemaleText_loc5`='喀撒朗蠻酒極度不穩定，$n!我們可以將酒桶放置在揚古通道附近然後引爆它們。去拿一桶來，我會在應該放置它們的地方上面做記號。', `FemaleText_loc7`='¡La cerveza salvaje de Krasarang es extremadamente inestable, $n! Podríamos colocar los barriles cerca de donde se aproximarán los yaungol y hacerlos estallar entonces. Coge uno y pondré marcas donde deberíamos colocarlos.' WHERE `ID`=64067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브리아우 샨은 맥주통 던지기 대회 우승자예요. 맥주통을 공중에 띄운 다음에 야운골 머리 위로 떨어뜨릴 수 있지요! 아까 여관 옆에 있는 걸 봤어요. 가서 도움을 청해 보세요!', `FemaleText_loc4`='布莱瓦·肖是投掷啤酒桶的高手，$n。他可以把酒桶扔到空中，然后让酒桶在野牛人中间摔碎！我今天上午在旅馆附近看到过他。去看看他是否愿意帮忙吧！', `FemaleText_loc5`='布萊尚是投擲啤酒的冠軍，$n。他可以把酒桶投到空中然後讓它砸到這些揚古的頭上!我今天稍早在旅店那邊有看到他。去看看他是否能夠幫忙!', `FemaleText_loc7`='Briaw Shan es un campeón de lanzamiento de cerveza, $n. ¡Podría lanzar un barril al aire y hacer que cayera encima de estos yaungol! Antes lo vi cerca de la posada. ¡Ve a ver si puede ayudarnos!' WHERE `ID`=64068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='축제 때 사용하려고 마을 곳곳에 폭죽통을 놓아 뒀어요. 폭죽통을 적당한 위치에 설치하고 한 번 쳐 주면 엄청난 파괴력을 발휘하지요. 폭죽통을 하나 들면, 놓아야 할 위치를 알려 드리지요.', `FemaleText_loc4`='我们的小镇上到处都有用于庆祝节日的大桶烟火。$n。把它们放在正确的位置，给它们来个恰到好处的打击，让它们可以造成各种各样的破坏。带上一桶烟花，我会在放置烟花的地方做标记。', `FemaleText_loc5`='我們整個村裡到處都有用來慶祝的煙火桶，$n。把它們放置在正確的地點然後用力地搥打它們幾下，就會造成各式各樣的破壞效果。去拿一桶來，我會在應該放置它們的地點上面做記號。', `FemaleText_loc7`='Tenemos barriles de fuegos artificiales por todo el pueblo para las celebraciones del festival, $n. Coloca unos cuantos en los lugares correctos y dales un buen golpe para que provoquen una gran destrucción. Coge un barril y te indicaré los lugares donde debemos colocarlos.' WHERE `ID`=64069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 마을에는 맥주달 축제를 즐기러 온 티엔 문하생들이 있어요! 아마도 지금까지 갈고닦은 실력으로 우릴 도와줄 수 있겠죠. 야운골을 막아 달라고 이야기해 보세요!', `FemaleText_loc4`='小镇上有天禅院弟子在庆祝酿月祭，$n！他们可以用学到的技艺帮助我们。和他们谈一谈，看他们是否可以阻止那些野牛人！', `FemaleText_loc5`='村子裡有一些天僧寺門徒在慶祝酒月節，$n!無疑地他們可以用他們受過的訓練幫助我們。去和他們交談，看看他們是否能阻止這些揚古!', `FemaleText_loc7`='¡Hay discípulas de Tian en el pueblo celebrando la Cerveza Lunar, $n! Seguro que podrían usar su adiestramiento para ayudarnos. ¡Habla con ellas para ver si pueden detener a estos yaungol!' WHERE `ID`=64070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='창고 안과 여관 뒤에 손상된 대포가 좀 있어요. 혹시 대포를 고칠 수 있다면, 마을사람들이 그걸로 야운골을 날려 버릴 수 있을 거예요!', `FemaleText_loc4`='旅馆后面的仓库里有一些破损的大炮，$n。如果你可以修复这些大炮，村民们就可以用它们击退野牛人！', `FemaleText_loc5`='在倉庫裡和旅店後面有一些受損的火砲，$n。如果你能修復它們，村民們就可以使用它們來轟炸揚古!', `FemaleText_loc7`='Hay algunos cañones dañados en los almacenes y detrás de la posada, $n. ¡Si pudieras repararlos, los aldeanos podrían usarlos contra los yaungol!' WHERE `ID`=64071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='골짜기 명사수들이 하룻밤 묵으려고 마을에 와 있어요. 오래전부터 박격포로 석양문을 사마귀로부터 지킨 이들이지요. 지금은 자고 있는데, 한번 깨워 보세요!', `FemaleText_loc4`='小镇上有一些锦绣谷神射手，他们在这里过夜休息，$n。他们用迫击炮在残阳关和螳螂妖战斗了很多年。你看一下能不能叫醒他们！', `FemaleText_loc5`='村子裡有一些停下來過夜休息的谷地神射手，$n。他們在落陽關用迫擊砲抵禦螳螂人已經很多年了。去看看你是否能叫醒他們!', `FemaleText_loc7`='Hay algunos tiradores del valle que se quedaron aquí a pasar la noche, $n. Llevan muchos años defendiendo la Puerta del Sol Poniente contra los mántides con sus morteros. ¡A ver si puedes despertarlos!' WHERE `ID`=64072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티엔 수도원에서 온 티엔 운무사들이 마을에 있어요. 그들의 운무 실력을 이용하면 더 오래 싸울 수 있을 거예요! 함께 싸워 달라고 부탁해 보세요.', `FemaleText_loc4`='小镇上有来自天禅院的天禅院织雾者，$n。他们在制造迷雾方面的能力可以帮助我们战斗得更久。请他们在战斗中帮助我们。', `FemaleText_loc5`='這裡有從天僧寺來的天僧寺織霧者，$n。他們織霧的技巧能讓我們作更長時間的戰鬥!去請求他們在這場仗中協助我們。', `FemaleText_loc7`='Aquí hay tejedores de la niebla de Tian del monasterio Tian, $n. ¡Sus habilidades tejiendo niebla nos permitirían luchar durante más tiempo! Pídeles que nos ayuden en esta batalla.' WHERE `ID`=64073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유쾌한 주민 몇 명이 뭐든지 더 잘할 수 있게 해주는 보호모를 만들었다더군요. 좀 미심쩍긴 하지만, 보호모를 써서 나쁠 일이야 있겠어요? 가서 이야기하면 하나쯤 빌려 줄지도 모르겠네요.', `FemaleText_loc4`='小镇上有一些快活的村民，他们说他们制造了一种能够让所有事情更加顺利进行的头盔。虽然我表示怀疑，但戴上头盔又没有什么损失，你说呢？和他们谈一谈，看他们是不是愿意借你一个。', `FemaleText_loc5`='村子裡有一些快活村民聲稱他們製作了一種盔帽能讓他們做所有事都更加得心應手。雖然我持懷疑的態度，但有盔帽可以戴不會是壞事，對吧?去和他們談談，看看他們是否願意借你一頂。', `FemaleText_loc7`='Hay algunos habitantes joviales en el pueblo que afirman haber creado un casco que los hace mejores en todo. Aunque soy escéptica, llevar un casco no puede ser malo, ¿no? Habla con ellos para ver si te prestan uno.' WHERE `ID`=64074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='츠안쯔는 매년 우리 축제에 축복을 하러 오지요. 전투에 직접 참여하지는 않겠지만, 우릴 도와줄 수 있을지도 몰라요. 가서 한번 이야기해 보세요.', `FemaleText_loc4`='齐延姿每年都来祝福我们的节日，$n。他不会参加战斗，但或许可以帮我们做一些其他事情。问问他是否能帮我们做些事情。', `FemaleText_loc5`='向茲每年都會來祝福我們的慶典，$n。他不會參加戰鬥但也許他能做某些事來幫助我們。去問看看他是否能做任何事。', `FemaleText_loc7`='Cianz viene todos los años a bendecir nuestro festival, $n. No luchará en la batalla, pero quizás pueda hacer alguna cosa para ayudarnos. Pregúntale si puede hacer algo.' WHERE `ID`=64075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='매년 백호사에서 쉬엔 방패병들이 내려오지요. 야운골의 진군을 막고 놈들이 이 마을에 들어오지 못하게 막아줄지도 몰라요. 우릴 도와줄 마음이 있는지, 한번 물어 보세요.', `FemaleText_loc4`='雪怒执盾手每年都会从白虎寺来到山下，$n。他们或许可以阻止野牛人的入侵，以免野牛人进入村庄。和他们谈一谈，看他们是否可以帮助我们。', `FemaleText_loc5`='雪怒盾防者每年都會從白虎寺下山來到這裡，$n。他們能夠阻擋揚古推進並防止他們進到村子裡。去和他們談談，看看他們是否可以協助我們。', `FemaleText_loc7`='Los portadores de escudos Xuen bajan todos los años del Templo del Tigre Blanco, $n. Podrían bloquear el avance yaungol y evitar que entren en la aldea. Habla con ellos para ver si pueden ayudarnos.' WHERE `ID`=64076;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더파 더파는 가끔 마을에 와서는, 쿤라이 봉우리를 돌아다니면서 모은 이상한 물건들을 팔려고 해요. 가서 혹시 무기로 쓸 만한 것이 있는지 알아보세요.', `FemaleText_loc4`='迪嘭迪嘭时不时地来到镇上，向我们出售在昆莱山附近搜集到的奇怪的小玩意儿。和他谈一谈，看他有没有可以给我们当做武器的东西。', `FemaleText_loc5`='德帕·德帕偶爾會遊蕩到村子裡來，試著把他在崑萊峰附近搜尋找到的古怪玩意兒賣給我們。去和他談談，看看他是否有任何東西可以讓我們當作武器。', `FemaleText_loc7`='Derpa Derpa entra en el pueblo de vez en cuando e intenta vendernos extraños cachivaches que ha encontrado rebuscando en la Cima Kun-Lai. Habla con él para ver si tiene algo que pueda servirnos de arma.' WHERE `ID`=64077;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빈안 낚시꾼들은 눈 감고도 술 취한 호젠을 그물로 잡을 수 있지요. 분명 야운골도 잡아 줄 수 있을 거예요. 낚시꾼들이랑 얘기해서 마을 방어를 도와 달라고 부탁하세요!', `FemaleText_loc4`='滨岸渔民闭着眼睛都可以用渔网捉到醉醺醺的猢狲，$n。他们当然也可以帮我们捉一些野牛人了。和他们谈一谈帮助我们保卫村庄的事情吧！', `FemaleText_loc5`='濱南漁夫矇著眼都可以用網子抓住狡猾的猴人，$n。無疑地他們可以幫我們困住幾個揚古。去和他們協商幫助我們防禦村子!', `FemaleText_loc7`='Los pescadores de Binan podrían capturar a un hozen engrasado en sus redes con los ojos cerrados, $n. Seguro que pueden frenar a unos cuantos yaungol. ¡Habla con ellos para que nos ayuden a defender la aldea!' WHERE `ID`=64078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 방비책은 없습니까?', `MaleText_loc4`='还有其他防御吗？', `MaleText_loc5`='還有任何其他防禦措施嗎?', `MaleText_loc7`='¿Hay alguna otra defensa?', `FemaleText_loc1`='다른 방비책은 없나요?', `FemaleText_loc4`='还有其他防御吗？', `FemaleText_loc5`='還有任何其他防禦措施嗎?', `FemaleText_loc7`='¿Hay alguna otra defensa?' WHERE `ID`=64079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 뻥뻥주가 완성됐네, $n! 판다리아 최고의 맥주를 맛볼 준비가 됐나? 경고하겠는데, 이 맥주를 마시고 나면 뭐든지 걷어차고 싶어질지도 모르네. 뭐, 걷어차 줄 야운골이 널려 있으니 잘됐지!', `MaleText_loc4`='昆莱劲酒完成了，$n！准备好见识一下潘达利亚最好的酒了吗？我要警告你，喝过这种酒之后，可能会产生踢东西的冲动。这是件好事，因为有太多的野牛人需要被踢飞了！', `MaleText_loc5`='崑萊好勁道已經釀好了，$n!你準備好要嚐嚐全潘達利亞最好的酒了嗎?我得先警告你，這酒你喝下去後可能會讓你想亂踢東西。不過這是件好事，因為我們有很多欠人踢屁股的揚古!', `MaleText_loc7`='¡La pateadora de Kun-Lai está lista, $n! ¿Estás en disposición de probar el mejor brebaje de Pandaria? Te aviso desde ya que, tras beber esta mezcla, puede que quieras dar patadas a las cosas. ¡Lo cual está muy bien, porque tenemos a un montón de yaungol que necesitan que se les patee!' WHERE `ID`=64080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 다 차지하기 전에 빨리 주십시오!', `MaleText_loc4`='快给我点儿！在野牛人夺走之前！', `MaleText_loc5`='快點給我一些!在揚古把它全部搶走之前!', `MaleText_loc7`='¡Dame un poco, rápido! ¡Antes de que los yaungol se hagan con todo!', `FemaleText_loc1`='야운골이 다 차지하기 전에 빨리 주세요!', `FemaleText_loc4`='快给我点儿！在野牛人夺走之前！', `FemaleText_loc5`='快點給我一些!在揚古把它全部搶走之前!', `FemaleText_loc7`='¡Dame un poco, rápido! ¡Antes de que los yaungol se hagan con todo!' WHERE `ID`=64081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 뻥뻥주가 완성됐네, $p! 이제 이걸로 야운골 놈들을 걷어차 줄 수 있겠군.', `MaleText_loc4`='昆莱劲酒完成了，$p！我们现在用它们来教训野牛人了！', `MaleText_loc5`='崑萊好勁道已經釀好了，$p!現在我們可以利用它來揍扁這些揚古!', `MaleText_loc7`='¡La pateadora de Kun-Lai está lista, $p! ¡Ahora podemos usarla para patear algunos traseros yaungol!' WHERE `ID`=64082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사 부프에게 가서 쿤라이 뻥뻥주를 얻으십시오!', `MaleText_loc4`='向酒仙布夫要一些昆莱劲酒！', `MaleText_loc5`='去找釀酒大師布夫要一些崑萊好勁道!', `MaleText_loc7`='Ve con el maestro cervecero Boof para conseguir pateadora de Kun-Lai.' WHERE `ID`=64083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우릴 방해하다니, 값을 치르게 해 주마!', `MaleText_loc4`='你们要为这场骚扰付出代价！', `MaleText_loc5`='你會為這次擾亂付出代價!', `MaleText_loc7`='¡Pagarás por esta intromisión!' WHERE `ID`=64084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 어찌 감히 이 계곡에 발을 들이느냐!', `MaleText_loc4`='你们竟敢进入山谷！', `MaleText_loc5`='你竟敢踏入這谷中!', `MaleText_loc7`='¿Cómo te atreves a pisar este valle?' WHERE `ID`=64085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입한 것을 후회하게 해 주마!', `MaleText_loc4`='你们会后悔入侵这里的！', `MaleText_loc5`='你會後悔擅闖此處!', `MaleText_loc7`='¡Te arrepentirás de esta intrusión!' WHERE `ID`=64086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 죽음은 느리고도 고통스러우리라!', `MaleText_loc4`='你会缓慢而且痛苦地死去！', `MaleText_loc5`='你會死得既緩慢又痛苦!', `MaleText_loc7`='¡Tu muerte no será ni rápida ni indolora!' WHERE `ID`=64087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 족속은 이 계곡에 들어올 수 없다!', `MaleText_loc4`='你们的族类不允许进入山谷！', `MaleText_loc5`='你的族類不被允許進入谷中!', `MaleText_loc7`='¡Tu especie no debería entrar en el valle!' WHERE `ID`=64088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 올 곳이 아니다!', `MaleText_loc4`='你们在这里不受欢迎！', `MaleText_loc5`='這裡不歡迎你!', `MaleText_loc7`='¡Los de tu calaña no sois bienvenidos!' WHERE `ID`=64089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너를 시작으로 여럿이 죽을 것이다!', `MaleText_loc4`='第一个就要杀死你！', `MaleText_loc5`='你會是許多人之中最先死的一個!', `MaleText_loc7`='¡La tuya será la primera muerte de muchas!' WHERE `ID`=64090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 목숨을 우리 황제께 제물로 바치면 딱 좋겠구나!', `MaleText_loc4`='你的小命正好用来祭奠我们的帝王！', `MaleText_loc5`='你的生命將會是獻給我們帝王的好祭品!', `MaleText_loc7`='¡Tu vida será un buen sacrificio para nuestro emperador!' WHERE `ID`=64091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 적의 시체 위에 제국을 재건할 것이다!', `MaleText_loc4`='我们要在敌人的尸体上重建帝国！', `MaleText_loc5`='我們將把帝國建立在我們敵人的屍體之上!', `MaleText_loc7`='¡Reconstruiremos nuestro imperio sobre los cadáveres de nuestros enemigos!' WHERE `ID`=64092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하지 않겠다면 죽어라!', `MaleText_loc4`='不服从者格杀勿论！', `MaleText_loc5`='你得服侍，否則你將沒命!', `MaleText_loc7`='¡Servirás o morirás!' WHERE `ID`=64093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 나약함은 불쾌하구나!', `MaleText_loc4`='你们的软弱让人恼火！', `MaleText_loc5`='你的軟弱讓我不快!', `MaleText_loc7`='¡Tu debilidad me ofende!' WHERE `ID`=64094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 죽인다고 네게 닥칠 운명을 피할 수는 없다...', `MaleText_loc4`='我的死不会让你们得到救赎的……', `MaleText_loc5`='我的死亡不會讓你倖免於即將來臨的事物...', `MaleText_loc7`='Mi muerte no te salvará de lo que se avecina...' WHERE `ID`=64095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리도 잠깐이다...', `MaleText_loc4`='你们的胜利只是暂时的……', `MaleText_loc5`='你的勝利只是短暫的...', `MaleText_loc7`='Tu victoria será breve...' WHERE `ID`=64096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 두 제국이 다시 뭉치면, 세상이 그 아래 무너지리라...', `MaleText_loc4`='当两个伟大的帝国重新合并，整个世界都会在他们面前颤抖……', `MaleText_loc5`='當兩個偉大的帝國重新聯合之時，這個世界將會崩裂於其下...', `MaleText_loc7`='Cuando los dos grandes imperios se unan, el mundo se derrumbará a su alrededor...' WHERE `ID`=64097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 늦었다...', `MaleText_loc4`='你们太晚了……', `MaleText_loc5`='你太遲了...', `MaleText_loc7`='Llegas tarde...' WHERE `ID`=64098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 죽는다 해서 네게 좋을 것은 전혀 없다!', `MaleText_loc4`='我的死对你们没有任何好处！', `MaleText_loc5`='我的死亡不會讓你得到任何好處!', `MaleText_loc7`='¡Mi muerte no te sirve para nada!' WHERE `ID`=64099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 바다에서 뭘 건질 수 있을까요?', `MaleText_loc4`='大海今天会为我们带来什么？', `MaleText_loc5`='海潮今天會帶給我們什麼?', `MaleText_loc7`='¿Qué nos traerá hoy el mar?' WHERE `ID`=64100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 섬뜩하게 생겼군요. 안 그렇습니까? 이런 건 처음 봅니다만, 온종일 이것만 잡히는군요.', `MaleText_loc4`='他们让人不寒而栗，你说呢？我从来没有见过他们，但我一直在追捕他们。', `MaleText_loc5`='牠們令人毛骨悚然，不是嗎?以前從來沒有看過牠們，但我已經一整天都只釣到牠們了。', `MaleText_loc7`='Dan repelús, ¿verdad? No los había visto nunca, pero llevo todo el día capturándolos.' WHERE `ID`=64101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 우리에게서 빼앗을 순 없다!', `MaleText_loc4`='你们休想夺走我们的土地！', `MaleText_loc5`='你無法從我們手中奪走這塊土地的!', `MaleText_loc7`='¡No nos arrebatarán eh''ta tierra!', `FemaleText_loc1`='이 땅을 우리에게서 빼앗을 순 없다!', `FemaleText_loc4`='你们休想夺走我们的土地！', `FemaleText_loc5`='你無法從我們手中奪走這塊土地的!', `FemaleText_loc7`='¡No nos arrebatarán eh''ta tierra!' WHERE `ID`=64102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 제국을 건드린 걸 후회하게 될 거다!', `MaleText_loc4`='与我们的帝国作对可不明智！', `MaleText_loc5`='你惹錯帝國了!', `MaleText_loc7`='¡Te eh''tás metiendo con el imperio equivocado!', `FemaleText_loc1`='우리 제국을 건드린 걸 후회하게 될 거다!', `FemaleText_loc4`='与我们的帝国作对可不明智！', `FemaleText_loc5`='你惹錯帝國了!', `FemaleText_loc7`='¡Te eh''tás metiendo con el imperio equivocado!' WHERE `ID`=64103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 잔달라의 차지가 될 운명이었다!', `MaleText_loc4`='赞达拉部族要定这片土地了！', `MaleText_loc5`='這塊土地是屬於贊達拉所有!', `MaleText_loc7`='¡Eh''ta tierra eh''tá deh''tinada a pertenecer a los Zandalari!', `FemaleText_loc1`='이 땅은 잔달라의 차지가 될 운명이었다!', `FemaleText_loc4`='赞达拉部族要定这片土地了！', `FemaleText_loc5`='這塊土地是屬於贊達拉所有!', `FemaleText_loc7`='¡Eh''ta tierra eh''tá deh''tinada a pertenecer a los Zandalari!' WHERE `ID`=64104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 두 제국은 우리 땅을 되찾을 것이다!', `MaleText_loc4`='我们的帝国将会夺回自己的东西！', `MaleText_loc5`='我們的帝國將取得屬於我們的東西!', `MaleText_loc7`='¡Nueh''tros imperios nos devolverán lo que nos pertenece!', `FemaleText_loc1`='우리 두 제국은 우리 땅을 되찾을 것이다!', `FemaleText_loc4`='我们的帝国将会夺回自己的东西！', `FemaleText_loc5`='我們的帝國將取得屬於我們的東西!', `FemaleText_loc7`='¡Nueh''tros imperios nos devolverán lo que nos pertenece!' WHERE `ID`=64105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_volcano.blp:20|t%s|1이;가; |cFFFF0000|Hspell:125391|h[불의 전선]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_volcano.blp:20|t%s开始施放|cFFFF0000|Hspell:125391|h[火焰裂隙]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_volcano.blp:20|t%s開始施放|cFFFF0000|Hspell:125391|h[火痕]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_volcano.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:125391|h[Líneas de fuego]|h|r!' WHERE `ID`=64106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석 종양이 %s의 상처로 스며들어 생명력을 회복시킵니다.', `MaleText_loc4`='琥珀增生影响到了%s的伤口，正在补充它的活力。', `MaleText_loc5`='琥珀增生侵入%s的傷口，補充它的活力。', `MaleText_loc7`='Un bulto de ámbar se filtra en las heridas de %s y repone su vitalidad.' WHERE `ID`=64107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 쓰러지더니 갑자기 숨을 다합니다.', `MaleText_loc4`='%s正在逐渐丧失体力，突然之间倒下了。', `MaleText_loc5`='%s突然倒地，斷氣了。', `MaleText_loc7`='%s se derrumba y expira de repente.' WHERE `ID`=64108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상이 손에 뭔가를 들고 있는 것 같습니다...', `MaleText_loc4`='雕像的手里似乎有什么东西……', `MaleText_loc5`='這雕像似乎握著某物...', `MaleText_loc7`='Parece que la estatua tiene algo...' WHERE `ID`=64109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각상 손의 물건을 줍습니다.', `MaleText_loc4`='取出他手中的东西。', `MaleText_loc5`='從他的手中取走物品。', `MaleText_loc7`='Coge el objeto que tiene en la mano.', `FemaleText_loc1`='조각상 손의 물건을 줍습니다.', `FemaleText_loc4`='取出他手中的东西。', `FemaleText_loc5`='從他的手中取走物品。', `FemaleText_loc7`='Coge el objeto que tiene en la mano.' WHERE `ID`=64110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='변명은 이제 지겹다, 여제! 당장 이 멍청이들을 쓸어버리지 않으면 내가 몸소 널 죽이겠다!', `MaleText_loc4`='别找借口了，女皇！消灭这些傻瓜，否则我会亲手杀了你！', `MaleText_loc5`='不要再找藉口了，女皇!消滅這些侏儒，否則我會親自殺了妳!', `MaleText_loc7`='¡Se acabaron las excusas, Emperatriz! ¡Acaba con estos despreciables o te mataré yo mismo!' WHERE `ID`=64111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁인도자 코비가 도끼를 떨어뜨렸습니다. 집어 드십시오!', `MaleText_loc4`='战争使者虬碧的斧子掉了。快拿起来！', `MaleText_loc5`='戰爭使者闊畢掉下了他的斧頭。奪取一把!', `MaleText_loc7`='El belisario Qobi ha soltado sus hachas. ¡Coge una!' WHERE `ID`=64112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_dust.blp:20|t%s|1이;가; |cFFFF0000|Hspell:124359|h[굴 파기]|h|r를 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_dust.blp:20|t%s开始|cFFFF0000|Hspell:124359|h[掘地]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_dust.blp:20|t%s開始|cFFFF0000|Hspell:124359|h[鑽地]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_dust.blp:20|t¡%s empieza a |cFFFF0000|Hspell:124359|h[Excavar]|h|r!' WHERE `ID`=64113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아아아!', `MaleText_loc4`='啊！', `MaleText_loc5`='耶咿咿咿咿!', `MaleText_loc7`='¡UIIIIIIIII!' WHERE `ID`=64114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 전투 애완동물을 치유하거나 되살리고 싶습니다.', `MaleText_loc4`='我要治疗和复活我的战斗宠物。', `MaleText_loc5`='我想要治療並復活我的戰寵。', `MaleText_loc7`='Me gustaría curar y revivir a mis mascotas de duelo.', `FemaleText_loc1`='제 전투 애완동물을 치유하거나 되살리고 싶어요.', `FemaleText_loc4`='我要治疗和复活我的战斗宠物。', `FemaleText_loc5`='我想要治療並復活我的戰寵。', `FemaleText_loc7`='Me gustaría curar y revivir a mis mascotas de duelo.' WHERE `ID`=64115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요 녀석, 예쁘기도 하지...', `MaleText_loc4`='你看我的宠物如何？', `MaleText_loc5`='你覺得我的寵物怎麼樣?', `MaleText_loc7`='¿Qué te parece mi mascota?', `FemaleText_loc1`='요 녀석, 예쁘기도 하지...', `FemaleText_loc4`='你看我的宠物如何？', `FemaleText_loc5`='你覺得我的寵物怎麼樣?', `FemaleText_loc7`='¿Qué te parece mi mascota?' WHERE `ID`=64116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 맡길 일이 있소.', `MaleText_loc4`='我有一个任务要交给你。', `MaleText_loc5`='我有任務要交給你。', `MaleText_loc7`='Tengo una tarea para ti.', `FemaleText_loc1`='당신에게 맡길 일이 있어요.', `FemaleText_loc4`='我有一个任务要交给你。', `FemaleText_loc5`='我有任務要交給你。', `FemaleText_loc7`='Tengo una tarea para ti.' WHERE `ID`=64117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야만인 놈들, 우리 마을에 다시 쳐들어오려면 잘 생각해야 될 거다!', `MaleText_loc4`='你们这些野蛮人最好考虑清楚还要不要攻击我们的村庄！', `MaleText_loc5`='下次你們這些野蠻人在攻擊我們村莊前得好好考慮了!', `MaleText_loc7`='¡La próxima vez lo pensarán dos veces antes de atacar nuestra aldea, bárbaros!' WHERE `ID`=64118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='유해를 어디 숨겼는지 말할 수밖에 없을걸!', `FemaleText_loc4`='你要告诉我遗迹藏在哪里！', `FemaleText_loc5`='告訴我們遺體被藏在什麼地方!', `FemaleText_loc7`='¡Dinos dónde han ocultado los restos!' WHERE `ID`=64119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 멋진 낚싯대 중 아무거나 골라서 조심스럽게 잡아당기십시오. 그러면 줄 끝에 꿈틀거리는 게 뭐든지 간에 바늘에 걸려들게 될 겁니다.', `MaleText_loc4`='从这些上好的鱼竿中选择一根，然后小心地拉鱼线。这样可以更加轻松地钓到东西。', `MaleText_loc5`='從這些優良的竿子裡挑選任何一根，然後小心地收拉釣魚線。這應該能讓魚鈎吊起另一端在搖晃的東西，不管它到底是啥。', `MaleText_loc7`='Elige una de estas fabulosas cañas y tira del sedal con cuidado. Eso ayudará a ajustarle el anzuelo a lo que esté agitándose al otro extremo.' WHERE `ID`=64120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 거참 이상하군요... 잘 살펴보십시오. 그리고 할 수 있으면 다른 낚싯대도 잡아당겨 보십시오.', `MaleText_loc4`='嗯，这可不太常见……解决掉它，然后再拉另一根鱼线。', `MaleText_loc5`='嗯那很不尋常...把它處理掉，當你好了之後收拉另一條釣魚線。', `MaleText_loc7`='Vaya, qué raro... Encárgate de eso y tira otro sedal cuando puedas.' WHERE `ID`=64121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으... 뭘 잡았는지는 모르겠지만, 대물이군요. 이놈을 낚을 때까지 온 힘을 다해 주십시오!', `MaleText_loc4`='哈……我在这里收获颇丰。我去把这宝贝儿送上岸，你继续好好拉鱼线吧！', `MaleText_loc5`='哦哦哦...我釣到一條大的。趁我把這寶貝釣起時繼續保持你的好表現。', `MaleText_loc7`='Grrr... sea lo que sea, es grande. ¡Sigue trabajando con esos sedales mientras me hago con esta maravilla!' WHERE `ID`=64122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 저런 게... 다 있지... 으아아아아!', `MaleText_loc4`='什么……以……玛祖……之名……啊！！', `MaleText_loc5`='瑪祖啊...這...是...什麼...啊啊啊啊!!', `MaleText_loc7`='En... el... nombre... de... Mazu... ¡¡RRRGGG!!' WHERE `ID`=64123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 지금 맛본 꿈결 맥주는 의식을 확장시켜서 이 땅 위에서 일어나는 모든 사건을 볼 수 있게 한다네. 내가 꿈결 맥주를 제대로 활용하는 방법을 가르쳐 주지. 그러면 왕자를 찾을 수 있을 걸세!$b$b그러려면 우선, 신선한 새 맥주 만드는 일을 좀 도와주게.', `MaleText_loc4`='你早些时候品尝的洄梦仙酒可以强化你的感觉，让你看到游离在世界之外的东西。我会教你如何正确使用，我们将会找到你的王子！$b$b但首先，请帮我酿一批新酒。', `MaleText_loc5`='你先前嘗過的夢幻之釀可以延伸你的意識，讓你看見發生在大地各處的事件。我會傳授你適當使用它的方法，而後就能找到你的王子!$b$b但首先，你得幫我造一批出來。', `MaleText_loc7`='El brebaje de ensueño que probaste antes puede ampliar tu conciencia y mostrarte sucesos de otros lugares. Yo te enseñaré a utilizarlo como se debe, y encontraremos a tu príncipe.$b$bPero antes, ayúdame a crear una nueva remesa.' WHERE `ID`=64124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑판장님께서 당신을 도와주라고 하셨습니다.', `MaleText_loc4`='甲板长官说你需要帮助。', `MaleText_loc5`='甲板長說你需要幫忙。', `MaleText_loc7`='La jefa de muelle decía que necesitabas ayuda.', `FemaleText_loc1`='갑판장님께서 당신을 도와주라고 하셨어요.', `FemaleText_loc4`='甲板长官说你需要帮助。', `FemaleText_loc5`='甲板長說你需要幫忙。', `FemaleText_loc7`='La jefa de muelle decía que necesitabas ayuda.' WHERE `ID`=64125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 꿈결 맥주는 매우 강력하다네. 정신을 집중해야만 명확한 환상을 볼 수 있지!', `MaleText_loc4`='优质的洄梦仙酒酒力强劲。你要有高度集中的意识来分辨各种影像！', `MaleText_loc5`='品質良好的夢幻之釀具有「非常」強大的力量。需要專注的心神才能從幻象中理出清晰的印象!', `MaleText_loc7`='Un buen brebaje de ensueño es MUY poderoso. Necesita de una mente centrada para obtener claridad en las visiones.' WHERE `ID`=64126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 중심을 잡아야 하네. 집중을 하든 긴장을 풀든, 언제나 중심에 머물러야 하네.', `MaleText_loc4`='现在，你要紧守本心。你可以集中或者放松精神，但是必须守住本心。', `MaleText_loc5`='現在，你必須保持在中央。要專注或放鬆都可以，但最重要的是，留在中央。', `MaleText_loc7`='Ahora, debes CENTRARTE. Te puedes concentrar o relajar, pero sobre todo, permanece en el centro.' WHERE `ID`=64127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 좋아. 쉽게 마음이 흔들리지 않는군. 판다렌들은 집중력이 무척 뛰어나다네. 그게 약점이 되기도 하고.', `MaleText_loc4`='啊，很好，看来要让你分心并不容易。我们熊猫人总是只关注当下，有时反而是种妨碍。', `MaleText_loc5`='嗯，好，我看得出來你不容易分心。我們熊貓人非常專注於當下，有時候甚至過了頭。', `MaleText_loc7`='Bien, veo que no te distraes fácilmente. Nosotros, los pandaren, nos centramos en cada momento; a veces demasiado.' WHERE `ID`=64128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네. 놀라지는 않았겠지? 판다렌은 어떤 상황에서도 평정심을 가장 중시하네.', `MaleText_loc4`='抱歉，没吓着你吧？我们熊猫人最推崇高山崩于前而色不变的气度。', `MaleText_loc5`='抱歉，剛才沒有嚇到你吧?隨時隨地都能保持冷靜對我們熊貓人很重要。', `MaleText_loc7`='Lo siento. No te has asustaste, ¿verdad? Los pandaren valoramos la calma ante todo.' WHERE `ID`=64129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디, 이건... 어떤가?', `MaleText_loc4`='那我就……这样？', `MaleText_loc5`='那麼...這個呢?', `MaleText_loc7`='¿Qué tal... ESTO?' WHERE `ID`=64130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단하군! 평온 그 자체야. 자네가 좋아질 줄 알았지.', `MaleText_loc4`='看呐！多么闲逸的风度。我很喜欢你。', `MaleText_loc5`='看看你!多麼祥和啊。我就知道我會喜歡你。', `MaleText_loc7`='¡Mírate! La imagen de la serenidad. Sabía que tenías potencial.' WHERE `ID`=64131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭉뭉 너 없으면 큰일 난다! 뭉뭉 너한테 빚졌어. 너하고 윤은 알고 보니 나쁜 놈들은 아니었어.', `MaleText_loc4`='没有你，蒙蒙就变成了大臭蛋！蒙蒙会感谢你的。或许你和老愚也不是那么没用。', `MaleText_loc5`='少了你，芒芒就只能被又大又臭的便便給淹沒了!芒芒永遠欠你。或許你和小尹不是那麼沒用。', `MaleText_loc7`='¡Mung-Mung en porkería grande si ti! Mung-Mung en deuda contigo. A lo mejor tú y Yoon no sois tan inútiles.' WHERE `ID`=64132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들에게 저도 훌륭한 농부가 될 수 있다는 걸 보여주겠습니다!$B$B이 밭을 네 바람의 계곡에서 가장 풍요로운 밭 중 하나로 만들 겁니다!$B$B하지만 판다렌 혼자 하기에는 일이 너무 많기는 합니다. 자, 저 좀 도와주시겠습니까?', `MaleText_loc4`='你猜怎么？我要向他们证明，我也可以成为大师级农夫！$B$B我要把这个农场变成山谷里最繁荣的农场！$B$B但是，这对于一个熊猫人来说有点过于繁重了。你愿意帮助我吗？', `MaleText_loc5`='你知道嗎?我要證明給他們看，我也能夠成為一個農務專家!$B$B我要讓這座農場成為峽谷中最富足的農場之一!$B$B但這樣的工作對一個熊貓人來說太沉重了。如何?你願意幫我嗎?', `MaleText_loc7`='¿Sabes qué? ¡Les pienso demostrar que yo también puedo ser un maestro granjero!$B$B¡Voy a hacer de esta granja una de las más prósperas del valle!$B$BNo obstante, es demasiado trabajo para un solo pandaren. ¿Qué dices? ¿Me ayudarás?' WHERE `ID`=64133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤, 어떻게 하실 생각입니까?', `MaleText_loc4`='你要做什么，农夫老愚？', `MaleText_loc5`='你打算怎麼做，農夫尹?', `MaleText_loc7`='¿Qué vas a hacer, granjero Yoon?', `FemaleText_loc1`='윤, 어떻게 하실 생각인가요?', `FemaleText_loc4`='你要做什么，农夫老愚？', `FemaleText_loc5`='你打算怎麼做，農夫尹?', `FemaleText_loc7`='¿Qué vas a hacer, granjero Yoon?' WHERE `ID`=64134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 도와주시다니 정말 감사합니다, $r님. 제가 빚을 졌군요.', `MaleText_loc4`='真是万分感谢你对我的帮助，$r。我欠你的人情。', `MaleText_loc5`='你來幫我真是太仁慈了，$r。我欠你個人情。', `MaleText_loc7`='Ha sido extremadamente amable de tu parte ayudarme, $r. Estoy en deuda contigo.' WHERE `ID`=64135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보십시오 이방인님... *딸꾹* 목마른 여행자에게 적선 좀 하시렵니까?', `MaleText_loc4`='嗨，陌生人……可不可以借些钱给口渴的旅行者？', `MaleText_loc5`='唷，陌生人...你有點酒錢給一個口渴的旅人嗎?', `MaleText_loc7`='Ey, $gforashtero:forashtera;... ¿tienes alguna moneda para un viajero sediento?' WHERE `ID`=64136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기에게 마실 것을 사주신다고요?', `MaleText_loc4`='给鱼买杯酒？', `MaleText_loc5`='給條魚買點酒如何?', `MaleText_loc7`='¿Comprash una bebida a un pez?' WHERE `ID`=64137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n 님께서 무슨 일로 제 연못에 오셨습니까?', `MaleText_loc4`='今天什么风把你给吹来了，我的$G兄弟:姐妹;？', `MaleText_loc5`='$G兄弟:姊妹;，是什麼風把你吹來我的井邊?', `MaleText_loc7`='¿Qué te trae a mi pozo hoy, $ghermano:hermana;?' WHERE `ID`=64138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 식구 $n 님, 물이 *딸꾹* 오늘 아주 좋은 점괘를 말해주는군요.', `MaleText_loc4`='水流预示着今天会有好运气，$n。', `MaleText_loc5`='今天，水給了個很好的兆頭，$n。', `MaleText_loc7`='Lash aguash hablan de buena fortuna, hoy, $n.' WHERE `ID`=64139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보십시오 $n 님, 불쌍한 진위에게 한 푼만 주시겠습니까?', `MaleText_loc4`='嗨，哥们，可不可以资助一下可怜的锦鱼？', `MaleText_loc5`='唷，兄弟!有點錢和一條可憐的錦魚人分享嗎?', `MaleText_loc7`='¡Ey, colega! ¿Tienesh una moneda que dar a un pobre jinyu?' WHERE `ID`=64140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 저는 지금 목이 너무 말라 죽게 생겼습니다.', `MaleText_loc4`='我渴坏了，哥们。', `MaleText_loc5`='我渴死了，兄弟。', `MaleText_loc7`='Tengo muchíshima shed, colega.' WHERE `ID`=64141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 $n 님, 잠깐 저와 함께 여기 앉아 보시죠.', `MaleText_loc4`='锦鱼的朋友，来和我坐一会儿。', `MaleText_loc5`='錦魚人的朋友，來陪我坐一會兒。', `MaleText_loc7`='$gAmigo:Amiga; de jinyu, ven a shentarte conmigo un poco.' WHERE `ID`=64142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 친구 $n 님, 같이 앉아서 한잔 안 하시겠습니까?', `MaleText_loc4`='嗨，朋友，介意和我一起喝一杯吗？', `MaleText_loc5`='唷，朋友，想坐下來陪我喝一杯嗎?', `MaleText_loc7`='Ey, $gamigo:amiga; ¿por qué no te shientash conmigo y compartesh una bebida?' WHERE `ID`=64143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 제 좋은 친구인 $n 님이시군요. 오늘은 어쩐지 제 기분이 생생합니다. 아마 음식에 양념을 좀 덜 뿌려 먹어서 그런 것 같군요.', `MaleText_loc4`='嗨，我的好朋友，$n。我今天感觉清醒多了。或许是因为我少吃了一些酱油。', `MaleText_loc5`='嘿，是我的好朋友$n。我今天感覺特別清醒。或許是因為我稍微戒了一點酒。', `MaleText_loc7`='Ey, ¡es mi $gbuen amigo:buena amiga;! Hoy me siento con más lucidez. Tal vez porque me he cortado un poco con la salsa.' WHERE `ID`=64144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 저는 지금 당신과 좋은 친구가 되기로 했습니다. 또 다른 이들과도 친구가 될 수도 있을 것 같고 말입니다.', `MaleText_loc4`='你知道的，我决定把你当做朋友了。这让我想到，或许我可以再交一些朋友。', `MaleText_loc5`='你知道嗎，我決定把你當成朋友。這讓我感覺或許還能擁有其他的朋友。', `MaleText_loc7`='Sabes, he decidido que me gusta que seamos amigos. Me hace pensar que puedo tener otros amigos también.' WHERE `ID`=64145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노나 의심처럼 부정적인 감정은, 여기 판다리아에서는 묘한 힘을 지니게 된다네. 조만간 그걸 깨닫게 될 거야.', `MaleText_loc4`='负面情绪，如愤怒或疑虑，会在潘达利亚表现出一种诡异的力量。你将来就会明白的。', `MaleText_loc5`='負面的情緒，像是憤怒或猜惑，在潘達利亞這裡有著奇特的力量。不過，這個以後你自然會發現的。', `MaleText_loc7`='Las emociones negativas, como la ira o la duda, adquieren un extraño poder en Pandaria. Ya lo descubrirás cuando corresponda.' WHERE `ID`=64146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 큰 신세를 졌네요. 그러니 이렇게 하죠. 제가 아버님께 말씀드려서 당신이 농사꾼 연합에 가입할 수 있도록 해줄게요.', `FemaleText_loc4`='我欠你的，所以我要告诉你。我会和我的父亲说，让你们加入阡陌客。', `FemaleText_loc5`='我欠你一次。這樣吧，我會和我父親談談，讓你們加入耕者工會。', `FemaleText_loc7`='Te debo una, así que mira lo que te digo. Hablaré con mi padre para que os deje uniros al gremio de labradores.' WHERE `ID`=64147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 느껴지나? 영혼이 완벽하게 고요해졌네!', `MaleText_loc4`='感觉到了吗？源自灵魂的完美宁静！', `MaleText_loc5`='嗯，你感覺到了嗎?這種祥和寧靜的完美感覺!好，再繼續慢慢感受夢幻之釀的效果。', `MaleText_loc7`='¿Lo sientes? ¡La quietud perfecta del alma!' WHERE `ID`=64148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 화난 게의 성질을 더 돋웠습니다!', `MaleText_loc4`='啊哦！你惹毛了一些愤怒的螃蟹！', `MaleText_loc5`='哦喔!你驚動了一些生氣的螃蟹!', `MaleText_loc7`='¡Oh, oh! ¡Has revuelto a algunos cangrejos enfadados!', `FemaleText_loc1`='당신은 화난 게의 성질을 더 돋웠습니다!', `FemaleText_loc4`='啊哦！你惹毛了一些愤怒的螃蟹！', `FemaleText_loc5`='哦喔!你驚動了一些生氣的螃蟹!', `FemaleText_loc7`='¡Oh, oh! ¡Has revuelto a algunos cangrejos enfadados!' WHERE `ID`=64149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 거미의 성질을 더 돋웠습니다!', `MaleText_loc4`='啊哦！你惹毛了一些蜘蛛！', `MaleText_loc5`='哦喔!你驚動了一些小蜘蛛!', `MaleText_loc7`='¡Oh, oh! ¡Has revuelto a unas cuantas arañas!', `FemaleText_loc1`='당신은 거미의 성질을 더 돋웠습니다!', `FemaleText_loc4`='啊哦！你惹毛了一些蜘蛛！', `FemaleText_loc5`='哦喔!你驚動了一些小蜘蛛!', `FemaleText_loc7`='¡Oh, oh! ¡Has revuelto a unas cuantas arañas!' WHERE `ID`=64150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='친절한 $r님, 우리는 바람을 따라 여행 중이랍니다. 잠시 저희 노래를 들어 볼래요?', `FemaleText_loc4`='我们跟随着风的指引四处游荡，好心的$r。你愿意倾听一会儿吗？', `FemaleText_loc5`='我們無拘無束地到處旅行，好$r。你想要聆聽一會兒嗎?', `FemaleText_loc7`='Viajamos donde nos lleva el viento, $r. ¿Querrías escuchar un rato?' WHERE `ID`=64151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여행하면서 많은 노래를 불렀지만, 아직도 부를 노래가 더 남았답니다.', `FemaleText_loc4`='在旅途中，我们唱过很多的歌曲，但还有很多歌曲没有唱。', `FemaleText_loc5`='在我們的旅途中，我們唱過許多歌曲，但還有許多的歌曲可以唱。', `FemaleText_loc7`='Es nuestros viajes, hemos cantado muchas canciones, pero aún quedan muchas por cantar.' WHERE `ID`=64152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고향의 물을 부르노니... 적을 내게로 끌어 오라!', `MaleText_loc4`='我要召唤故乡的水……把我的敌人交给我吧！', `MaleText_loc5`='我呼喚家鄉的水...將我的敵人送到我這裡來!', `MaleText_loc7`='Les pido a las aguasss de mi tierra natal... ¡TRAIGAN A MIS ENEMIGOS!' WHERE `ID`=64153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부족과 저는 이곳 근처에 있는 강과 연못을 조사하고 있습니다. 이렇게 활력이 넘치는 물은 본 적이 없군요.', `MaleText_loc4`='我和我们的人民正在研究附近的河流和水塘。我们以前从来没有见过如此具有活力的水。', `MaleText_loc5`='我的族人和我正在研究附近的河流和池塘。我們以前從沒看過能如此令人煥然一新的水。', `MaleText_loc7`='Mi gente y yo estamos estudiando los ríos y estanques cercanos. Nunca habíamos visto un agua tan revitalizadora.' WHERE `ID`=64154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡에 있는 물의 고유한 특성이 바로 이 지역이 모든 것들을 풍요롭게 만드는 주요 원인 같습니다.', `MaleText_loc4`='我们认为正是山谷中的独特水质造就了这片繁荣的区域。', `MaleText_loc5`='我們認為谷中這種獨特的水質是造成這地區如此豐沛的主因。', `MaleText_loc7`='Creemos que la cualidades únicas del agua del valle son la razón principal para que haya tanta abundancia en la región.' WHERE `ID`=64155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연못에 있는 물이... 꽤 놀랍군요.', `MaleText_loc4`='这个水塘里的水……非常糟糕。', `MaleText_loc5`='這池塘中的水...相當糟糕。', `MaleText_loc7`='El agua de este estanque es... bastante horrible.' WHERE `ID`=64156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안됐지만, 우리 형제인 조구는 부모님이 돌아가신 뒤로는 잘 지내지 못합니다.', `MaleText_loc4`='不幸的是，我们的兄弟贾古自从家人去世之后就活得很消沉。', `MaleText_loc5`='不幸地，我們的弟兄酒骨在他家人死後過得並不好。', `MaleText_loc7`='Por desgracia, nuestro hermano Jogu no está muy bien desde que murió su familia.' WHERE `ID`=64157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조구는 우리와는 다른 부족 출신입니다. 더 멀리 북쪽에서 왔는데, 여기 온 이유에 대해서는 별로 말하지 않을 겁니다.', `MaleText_loc4`='贾古来自另外一个部落。他来自遥远的北方，很少提起自己为什么会来到这里。', `MaleText_loc5`='酒骨和我們來自不同的部族。他是從遙遠北方來的，而且不願多談是什麼原因讓他來到此地。', `MaleText_loc7`='Jogu es de una tribu diferente a la nuestra. Vino de lejos, del norte, y no habla mucho de lo que le ha traído hasta aquí.' WHERE `ID`=64158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있는 우리 형제는 땀 흘리며 열심히 일하는 대신, 무관심과 술독에 빠져 슬픔을 달래고 있습니다.', `MaleText_loc4`='那边的那位兄弟只是借酒消愁，对世事不闻不问，从不辛苦工作。', `MaleText_loc5`='在那邊的我們弟兄將他的悲傷沉溺於冷漠與酒水中，而不是工作與辛勞。', `MaleText_loc7`='Nuestro hermano de allí ahoga sus penas en la apatía y el vino en vez de trabajar y esforzarse.' WHERE `ID`=64159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 이거 꽤 센데요!', `MaleText_loc4`='哟！这酒真带劲儿！', `MaleText_loc5`='呼!這酒還真猛!', `MaleText_loc7`='¡Guau! ¡Esa cerveza es fuerte!' WHERE `ID`=64160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 음식 정말 맛있군요. 여기 영원히 있고 싶습니다.', `MaleText_loc4`='这里的食物非常美味。我从没想过要离开。', `MaleText_loc5`='這食物真美味!我永遠都不想離開了!', `MaleText_loc7`='Está comida está deliciosa. No quiero irme nunca.' WHERE `ID`=64161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지잉 사부님께서는 우리가 조사를 계속 해야 한다고 하셨지만, 가끔 여기 와서 쉬니까 좋더군요.', `MaleText_loc4`='基赢大师说我们必须继续研究，但偶尔来这里放松一下也是不错的事情。', `MaleText_loc5`='紀銀主人說我們必須繼續我們的研究，但偶而來這輕鬆一下並不壞。', `MaleText_loc7`='El maestro Jiying dice que tenemos que continuar con nuestra investigación, pero se está bien venir aquí de vez en cuando, para relajarse.' WHERE `ID`=64162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<거대한 호랑이의 두툼한 털가죽을 부드럽게 문질러 보지만, 호랑이는 당신에게 신경도 쓰지 않습니다.>', `MaleText_loc4`='<当你抚摸这只大猫浓密的皮毛时，她只是冲着你动了动耳朵。>', `MaleText_loc5`='<即使當你的手指撫摸過這隻大貓的厚毛時，她也只勉強地向你動了一下耳朵。>', `MaleText_loc7`='<El gran felino ni se inmuta por tu presencia, ni siquiera cuando deslizas tus dedos por su grueso pelaje.>' WHERE `ID`=64163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<거대한 새가 낯을 가리는 듯 당신을 외면합니다.>', `MaleText_loc4`='<这只大鸟躲开了你。>', `MaleText_loc5`='<這隻巨鳥迴避了你。>', `MaleText_loc7`='<Has asustado al enorme pájaro, el cual huye de ti.>' WHERE `ID`=64164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 호드 생존자들과 함께 만나다니 행운이구려. 우리의 형제들이 이 새로운 땅 어딘가에 쓸려온 줄은 알지 못했다오.', `MaleText_loc4`='能与其他的部落幸存者重聚真是太幸运了。我根本没想到，还有别的同胞也被冲上了这片全新的土地。', `MaleText_loc5`='我們很幸運地能和這些部落倖存者會合。我原本不知道有其他弟兄被沖到這片新土地的別處。', `MaleText_loc7`='Tuvimos suerte de encontrar más supervivientes de la Horda. No sabía que nuestros hermanos habían desembarcado en otros puntos de esta nueva tierra.' WHERE `ID`=64165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 모르겠네, $r 친구. 이 커다란 채소는 뭔가 좀 이상해 보이는군. 다들 어떻게 이런 걸 아무렇지도 않게 먹는 건가? 고기는 다 어디로 간 거지?', `MaleText_loc4`='我不知道，$r。这么大的蔬菜看起来不对劲，武僧。他们怎么可以跟没事儿似的吃这种东西？怎么看不到肉呢？', `MaleText_loc5`='我不知道，$r。這株大蔬菜看起來不對勁。他們怎麼能若無其事地只吃菜?他們的肉都到哪去了?', `MaleText_loc7`='No sé, $r. Eh''tas verduras no parecen eh''tar bien. ¿Cómo pueden comérselas como si nada? ¿Dónde tienen la carne?' WHERE `ID`=64166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='데즈코 님께서 이곳을 정찰하기 위해 우리를 먼저 보내셨어요. 레자 님의 환영에서 봤던 엄청난 치유력을 가진 곳으로 가는 길을 찾은 것 같아요.', `FemaleText_loc4`='德兹科派我们来侦察这片地区。我们也许已经找到了莱莎幻像中出现的伟大治疗之力。', `FemaleText_loc5`='戴斯可派我們前來探查這個地區。我們也許找到了一條通往在麗紗幻象中強大療效的途徑。', `FemaleText_loc7`='Dezco nos ordenó adelantarnos para explorar esta región. Puede que hayamos encontrado una ruta a la gran sanación de la visión de Leza.' WHERE `ID`=64167;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 주민들은 우리가 찾는 엄청난 치유력을 가진 물이 틀림없이... 스톰스타우트 양조장이라고 주장하더라고요. 왜 그렇게 주장하는지 연구해봐야겠어요.', `FemaleText_loc4`='当地人坚称，我们要找的伟大治愈之水不过是……风暴烈酒而已。我们得调查下这种说法的真实性。', `FemaleText_loc5`='這裡的本地人堅持我們所尋找的強大療效之水不會比一個...風暴烈酒酒坊還遠。我們也許得調查一下他們的說法。', `FemaleText_loc7`='Los nativos insisten en que las aguas de sanación se encuentran cerca de una tal... Cervecería del Trueno. Habrá que investigarla.' WHERE `ID`=64168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 트롤은 음식 맛에 불평을 늘어놓지만, 우리보다 더 많이 먹어치우더라고요!', `FemaleText_loc4`='这巨魔抱怨食物不好吃，但他吃的比谁都多。', `FemaleText_loc5`='這個食人妖抱怨食物不好，但他吃得比我們都還要多。', `FemaleText_loc7`='El trol se queja de la comida, pero come más que todos nosotros.' WHERE `ID`=64169;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서쪽에 있는 벽 보신 적 있어요? 그 뒤에는 뭐가 있을까요?', `FemaleText_loc4`='你看到西面的长城了吗？我在想长城的外面有什么呢？', `FemaleText_loc5`='你有看到西邊的那座長城嗎?我很想知道它的另一邊有什麼?', `FemaleText_loc7`='¿Has visto la muralla del oeste? ¿Qué habrá al otro lado?' WHERE `ID`=64170;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있는 모든 게... 다... 달라... 너무나 달라!', `FemaleText_loc4`='这里所有的东西……都那么……那么……不同！', `FemaleText_loc5`='這裡所有的東西...都...很...很不一樣!', `FemaleText_loc7`='¡Todo aquí es... tan... tan... diferente!' WHERE `ID`=64171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테일러 제독이 어린 왕자를 찾으러 우리를 이곳으로 보냈다네. 이들이 여기서 맥주를 양조한다는 거 아나?', `MaleText_loc4`='海军上将泰勒派我们来此寻找年轻的王子。你能想到他们这里也酿啤酒吗？', `MaleText_loc5`='泰勒上將派我們來這裡尋找年輕的王子。你知道他們在這裡釀造啤酒嗎?', `MaleText_loc7`='El almirante Taylor nos ha enviado a buscar al joven príncipe. ¿Sabías que aquí fabrican CERVEZA?' WHERE `ID`=64172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 열심히 안두인 왕자를 찾아다니고 있다네. 지금 잠깐 멈춰서 요기를 하는 중이지.', `MaleText_loc4`='我们正在努力寻找安度因王子。顺道路过，来吃些干粮酒水。', `MaleText_loc5`='我們很努力地在尋找安杜因王子。我們只是停下來吃點東西喝點酒。', `MaleText_loc7`='Nos estamos esforzando al máximo en buscar al príncipe Anduin. Es solo que nos hemos parado a comer algo y a dar un trago.' WHERE `ID`=64173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 이들이 그러는데, 판다리아에는 맥주 종류만 5천 가지가 넘는다고 하더군! 그걸 다 마셔보기 전에는 절대 안 떠날 걸세!', `MaleText_loc4`='他们说潘达利亚有五千多种酒。我在尝遍这些酒之前是不会离开的！', `MaleText_loc5`='據說潘達利亞有超過五千種酒。在我嚐過所有酒之前我是不會離開的!', `MaleText_loc7`='Dicen que hay más de quinientas cervezas en Pandaria. ¡No me iré hasta que probarlas todas!' WHERE `ID`=64174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r님! 마실 거 하나 집어들고 함께 하시죠!', `MaleText_loc4`='过来和我们喝一杯，$r！', `MaleText_loc5`='拿一杯酒加入我們，$r!', `MaleText_loc7`='¡Coge algo de beber y únete a nosotros. $r!' WHERE `ID`=64175;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='콜이 맛있는 조리법을 이야기하는 걸 듣는 게 마냥 좋아요. 고기를 굽는 법이 그렇게 많은지 정말 몰랐답니다.', `FemaleText_loc4`='我就是喜欢听柯谈论他那些美味的食谱。我从不知道竟然有那么多种烤肉的方法。', `FemaleText_loc5`='我就是喜歡聽老柯談論他的美味食譜。我從來不曉得原來烤肉也有那麼多種方法。', `FemaleText_loc7`='Me encanta escuchar a Kol mientras habla de sus deliciosas recetas. No sabía que hubiera tantas formas de cocinar carne a la parrilla.' WHERE `ID`=64176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='콜이 만든 요리 드셔보셨어요? 아무리 먹어도 안 질릴 것 같아요.', `FemaleText_loc4`='你有没有尝过柯的厨艺？我好像怎么都吃不够。', `FemaleText_loc5`='你有嚐過老柯煮的菜嗎?我好像永遠都吃不膩。', `FemaleText_loc7`='¿Has probado la cocina de Kol? Yo no me harto de ella.' WHERE `ID`=64177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 계속 제 말투가 좋다고 그러네요. 그래서 제 어떤 말투가 그런지 계속 물어봤답니다.', `FemaleText_loc4`='他经常告诉我说他喜欢我的口音，我就一直问他，什么口音？', `FemaleText_loc5`='他一直告訴我說他喜歡我的口音，而我就一直問，什麼口音?', `FemaleText_loc7`='No para de decirme que le gusta mi acento, y yo sigo preguntando, ¿qué acento?' WHERE `ID`=64178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $c님. 여기서 만나다니 반갑군요. 당신도 어린 왕자를 찾으라는 명령을 받고 오신 겁니까?', `MaleText_loc4`='嘿，$c，很高兴在这见到你！你也是被派去寻找小王子的？', `MaleText_loc5`='嘿，$c，遇見你真好啊!你也是被派來尋找年輕王子的嗎?', `MaleText_loc7`='¡Hola, $c! ¡Qué casualidad verte aquí! ¿A ti también te han encargado buscar al joven príncipe?' WHERE `ID`=64179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 주민들은 확실히 전원적인 생활을 하는군요. 덕분에 저도 마법봉을 내려놓고 괭이를 들어보는 게 어떨까 하는 생각이 드는군요.', `MaleText_loc4`='这里的本地人过着美好的田园生活。这不禁令我怀疑，自己是不是该放下魔杖，拿起锄头。', `MaleText_loc5`='這裡的當地人有著悠閒的田園生活。幾乎讓我也想放下魔杖，扛起鋤頭。', `MaleText_loc7`='Esta gente lleva una vida idílica. Hacen que me pregunta si debería dejar la varita y coger una azada.' WHERE `ID`=64180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 마법봉을 파는 장사꾼입니다. 당신이나 저나 다행인 게... 배가 가라앉았는데도 제 마법봉이 무사하다는 겁니다!', `MaleText_loc4`='我是专卖魔杖的小贩。我们都很幸运，我的大部分魔杖都躲过了那次海难！', `MaleText_loc5`='我是個魔杖小販。對你和我來說都很幸運的是，我大部分的魔杖都從船難中存留了下來。', `MaleText_loc7`='Soy un vendedor ambulante de varitas. Por suerte para ti y para mí, la mayoría de mis varitas sobrevivieron al naufragio.' WHERE `ID`=64181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 이는 지쳤을 때 쉴 줄 안다네.', `MaleText_loc4`='聪明的人会在疲劳时休息。', `MaleText_loc5`='聰明的人會在疲勞時休息。', `MaleText_loc7`='Un hombre sabio descansa cuando se siente cansado.' WHERE `ID`=64182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 가장 훌륭한 맥주는 네 바람의 계곡의 바로 이곳, 스톰스타우트 양조장에서 만들어졌다네.$B$B뭐, 나로서는 그렇게 생각한다만.', `MaleText_loc4`='整个潘达利亚最好的酒就产自这个山谷的风暴烈酒酿造厂。$B$B嗯，至少我是这么认为的。', `MaleText_loc5`='全潘達利亞最好的酒就是在峽谷中風暴烈酒酒坊這裡釀造的。$B$B至少我是這麼認為啦。', `MaleText_loc7`='La mejor cerveza de toda Pandaria se fabrica aquí en el valle, en la Cervecería del Trueno.$B$BBueno, al menos eso creo yo.' WHERE `ID`=64183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기쁨으로 잔을 가득 채우게. 그러면 그 기쁨을 마시는 거라네. 슬픔으로 잔을 가득 채우면 슬픔을 마시게 되지.$B$B어떤 술을 마실지 현명하게 선택하게.', `MaleText_loc4`='开心的时候，喝酒能够助兴。难过的时候，喝酒只会愁上加愁。$B$B喝酒要做好选择，我的朋友。', `MaleText_loc5`='將你的酒杯倒滿歡樂，你就能暢飲歡樂。將你的酒杯倒滿悲傷，你就只能喝下悲傷。$B$B明智地選擇你的酒，我的朋友。', `MaleText_loc7`='Llena la copa con alegría y beberás alegría. Llena la copa con penas y beberás penas.$B$BElige sabiamente la cerveza, $gamigo:amiga;.' WHERE `ID`=64184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 배가 빵빵하게 부른 게 바로 행복한 거라네.$B$B맛있는 음식으로 배를 채우게. 그러면 영혼에도 온기가 가득 찰 걸세.', `MaleText_loc4`='啊，我认为最开心的事情就是吃的饱饱的。$B$B让美味的食物填饱你的肚子，你的灵魂也会感受到温暖。', `MaleText_loc5`='啊啊，我相信快樂就是一個飽滿的肚皮。$B$B把你的胃裝滿美好的食物，你的靈魂就會充滿溫暖。', `MaleText_loc7`='Aaaah, creo que la felicidad consiste en tener la tripa llena.$B$BLlena tu estómago de buena comida y llenarás tu alma de calor.' WHERE `ID`=64185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에서 나는 과일을 먹는 건 몸에 좋다네. 하지만 너무 많이 먹진 말게나.', `MaleText_loc4`='享受美味的水果是件开心的事情，但不要吃太多。', `MaleText_loc5`='能享用大地的果實是件好事，但不能過量。', `MaleText_loc7`='Es agradable disfrutar de los frutos de la tierra, pero sin excesos.' WHERE `ID`=64186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r님, 행운이 가득하시기를 바랍니다! 동생과 저는 복덩이를 나눠 드리러 아주 멀리에서 왔습니다.', `MaleText_loc4`='祝你好运，$r！我和我的兄弟大老远赶来就是为了给人带来幸运符的。', `MaleText_loc5`='祝你超級好運，$r!我和我的兄弟大老遠來到這裡分享我們的幸運星。', `MaleText_loc7`='¡Buena suerte para ti, $r! Mi hermano y yo venimos desde lejos para compartir nuestros grisgrís.' WHERE `ID`=64187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$r님, 행운이 가득하시기를 바라요! 형과 저는 복덩이를 나눠 드리러 아주 멀리에서 왔어요.', `MaleText_loc4`='祝你好运，$r！我和我的兄弟大老远赶来就是为了给人带来幸运符的。', `MaleText_loc5`='祝你超級好運，$r!我和我的兄弟大老遠來到這裡分享我們的幸運星。', `MaleText_loc7`='¡Buena suerte para ti, $r! Mi hermano y yo venimos desde lejos para compartir nuestros grisgrís.' WHERE `ID`=64188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀들은 냄새를 아주 잘 맡죠. 냄새만으로도 행운과 불행의 차이를 가려낼 수 있어요. 당신에게는 행운의 냄새가 나네요.', `MaleText_loc4`='土地精的鼻子可灵敏了。能够通过气味分辨出好运和歹运。你身上的气味代表着好运。', `MaleText_loc5`='咕嚕摩有好鼻子。可以用氣味分辨幸運星和倒楣運。你聞起來是幸運星。', `MaleText_loc7`='Los grúmel tenemos buena nariz. Podemos oler la diferencia entre la buena y la mala suerte. Tú hueles a buena fortuna.' WHERE `ID`=64189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 부탁하는데, 이 마을에 손임으로 있는 동안에는 서로 얌전히 있도록 하지. 피를 흘리면 주인장이 친절하게 굴진 않을 테니까.', `MaleText_loc4`='拜托，既然我们是村里的客人，就守规矩些。要是我们大开杀戒，主人们恐怕不会善罢甘休。', `MaleText_loc5`='拜託，讓我們在這個村子裡作客時能保持文明。我猜想這裡的主人們可不會對血鬥無動於衷。', `MaleText_loc7`='Seamos cordiales mientras disfrutamos de la hospitalidad de esta aldea. Sospecho que nuestros anfitriones no reaccionarían positivamente ante el derramamiento de sangre.' WHERE `ID`=64190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 모르겠군, $r. 이 커다란 채소는 뭔가 좀 이상해 보이는데. 다들 어떻게 이런 걸 아무렇지도 않게 먹는 건가? 고기는 다 어디로 간 거지?', `MaleText_loc4`='我不知道，$r。这么大的蔬菜看起来不对劲，伙计。他们怎么可以若无其事地吃这种东西？肉都去哪儿了？', `MaleText_loc5`='我不知道，$r。這株大蔬菜看起來不對勁。他們怎麼能若無其事地只吃菜?他們的肉都到哪去了?', `MaleText_loc7`='No sé, $r. Eh''tas verduras no parecen eh''tar bien. ¿Cómo pueden comérselas como si nada? ¿Dónde tienen la carne?' WHERE `ID`=64191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 평화로운 곳에서는 서로 피를 흘리진 않았으면 좋겠어요.', `FemaleText_loc4`='我们不要让杀戮席卷这片净土，$G兄弟:姐妹;。', `FemaleText_loc5`='不要把流血衝突帶到這平靜的地方，$g兄弟:姊妹;。', `FemaleText_loc7`='No debemos profanar este hermoso lugar con la violencia, $ghermano:hermana;.' WHERE `ID`=64192;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조사를 하러 드넓은 대양과 깊은 밀림을 돌아다녔는데, 하필 또 이곳에서 맞닥뜨리게 되네요. 정말이지 우리의 분쟁은 피할 수 없는 것 같아요. 어딜 가든 말이죠.', `FemaleText_loc4`='我们一路搜寻，跨越了千山万水，可却偏巧在这里狭路相逢。看来不管走到哪里，我们的冲突都是难以避免的啊。', `FemaleText_loc5`='我們的搜索遍及廣大的海洋與幽深的叢林，但我們偏偏還是在這個地方相遇了。我們的衝突似乎真的是不管走到哪裡都無可避免。', `FemaleText_loc7`='Nuestra búsqueda nos ha conducido a través de grandes océanos y selvas profundas, pero nos hemos encontrado aquí. Parece que nuestro conflicto es inevitable, sin importar adónde vayamos.' WHERE `ID`=64193;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 다 보고 있다고요.', `FemaleText_loc4`='我一直在观察你，$r。', `FemaleText_loc5`='我在盯著你，$r。', `FemaleText_loc7`='Te estoy viendo, $r.' WHERE `ID`=64194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 못생긴 친구. 내가 마음만 먹으면 지금 당장에라도 자네에게 한 방 먹여줄 수 있다네. 어쨌든, 이 친구들이 여기서 맥주를 양조한다는 거 알고 있었나?', `MaleText_loc4`='嗨，丑八怪，我恨不得立刻给你一拳……如果我觉得可以教训你！但是，你知道这里的人也会酿造啤酒吗？', `MaleText_loc5`='嘿醜八怪，如果我認為我能打中你...我現在就會給你一拳!不管怎樣，你知道他們在這裡釀啤酒嗎?', `MaleText_loc7`='Ey, rata, podría darte un puñetazo ahora mismo... ¡si pensara que acertaría! En fin, ¿sabes que aquí fabrican cerveza?' WHERE `ID`=64195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서로 피를 흘리는 대신... 춤 대결로 화해하는 게 어떻겠나?', `MaleText_loc4`='除了打得头破血流，不如用跳舞来解决……我们之间的分歧吧？', `MaleText_loc5`='與其流血殺人，我們不如以鬥舞來解決我們之間的差異...你認為如何?', `MaleText_loc7`='En vez de verter sangre, ¿por qué no resolvemos nuestras diferencias con un duelo de baile?' WHERE `ID`=64196;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이보세요, 여긴 싸움을 시작할 데가 못 돼요. 여기서 싸우면 아무도 이 음식을 즐겁게 먹지 못할 거예요.', `FemaleText_loc4`='嘿够了，这可不是打架的地方。不然谁也别想吃到这美食。', `FemaleText_loc5`='嘿，這裡不是起爭端的地方。要不然沒人能好好地享受食物。', `FemaleText_loc7`='¡Oye! Este no es lugar para peleas. Si no os comportáis, no habrá comida para nadie.' WHERE `ID`=64197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보십시오, $r님! 허튼수작 부릴 생각 마십시오! 전 마법봉을 몇 개나 숨기고 있고, 그걸 쓰는 것도 무서워하지 않습니다!', `MaleText_loc4`='嘿，$r，别没事找事！我袖子里藏着好几把魔杖，我可不介意把它们对准你！', `MaleText_loc5`='嘿$r，不要做蠢事。我袖子裡有好幾根魔杖，而且我可不怕拿它們出來對付你!', `MaleText_loc7`='¡Oye, $r, ni se te ocurra hacer algo raro! ¡Tengo muchas varitas en la manga y no dudaré en usarlas!' WHERE `ID`=64198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음악은 마음과 몸, 그리고 영혼에 좋답니다!', `FemaleText_loc4`='音乐对人的心灵、身体和灵魂都有好处！', `FemaleText_loc5`='音樂對心靈、身體，和靈魂都很好!', `FemaleText_loc7`='¡La música es buena para la mente, el cuerpo y el alma!' WHERE `ID`=64199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 경치를 보러 왔나?', `MaleText_loc4`='你是来享受这里的美景的吗？', `MaleText_loc5`='你來這裡看風景的嗎?', `MaleText_loc7`='¿Has venido a disfrutar de las vistas?', `FemaleText_loc1`='여기 경치를 보러 왔나?', `FemaleText_loc4`='你是来享受这里的美景的吗？', `FemaleText_loc5`='你來這裡看風景的嗎?', `FemaleText_loc7`='¿Has venido a disfrutar de las vistas?' WHERE `ID`=64200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 이 바람이 느껴지는가? 변화를 싣고 불어오는 바람이네.', `MaleText_loc4`='你能闻到风的气息吗，陌生人？它们带来了变化。', `MaleText_loc5`='你有感覺到風嗎，陌生人?它們帶來改變。', `MaleText_loc7`='¿Percibes el aroma del viento, $gforastero:forastera;? Traen cambio.', `FemaleText_loc1`='이방인이여, 이 바람이 느껴지는가? 변화를 싣고 불어오는 바람이네.', `FemaleText_loc4`='你能闻到风的气息吗，陌生人？它们带来了变化。', `FemaleText_loc5`='你有感覺到風嗎，陌生人?它們帶來改變。', `FemaleText_loc7`='¿Percibes el aroma del viento, $gforastero:forastera;? Traen cambio.' WHERE `ID`=64201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 여기에서 판다리아의 신비에 대해 명상을 한다네.', `MaleText_loc4`='我们在这里思考潘达利亚的各种奇观。', `MaleText_loc5`='在這裡我們冥想沉思關於潘達利亞的奇事。', `MaleText_loc7`='Desde aquí meditamos sobre las maravillas de Pandaria.', `FemaleText_loc1`='우리는 여기에서 판다리아의 신비에 대해 명상을 한다네.', `FemaleText_loc4`='我们在这里思考潘达利亚的各种奇观。', `FemaleText_loc5`='在這裡我們冥想沉思關於潘達利亞的奇事。', `FemaleText_loc7`='Desde aquí meditamos sobre las maravillas de Pandaria.' WHERE `ID`=64202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벼랑 끝에 서면, 황홀한 경치 때문에 숨 쉬는 것도 잊어버리는 일이 많으니 조심하게.', `MaleText_loc4`='站在悬崖边上时，不要忘记了呼吸。', `MaleText_loc5`='站在斷崖絕壁上時，別忘了要呼吸。', `MaleText_loc7`='Cuando estés al borde del precipicio, no te olvides de respirar.', `FemaleText_loc1`='벼랑 끝에 서면, 황홀한 경치 때문에 숨 쉬는 것도 잊어버리는 일이 많으니 조심하게.', `FemaleText_loc4`='站在悬崖边上时，不要忘记了呼吸。', `FemaleText_loc5`='站在斷崖絕壁上時，別忘了要呼吸。', `FemaleText_loc7`='Cuando estés al borde del precipicio, no te olvides de respirar.' WHERE `ID`=64203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 전망대에 잘 왔네. 혹시 연을 가지고 왔나?', `MaleText_loc4`='欢迎来到青龙瞭望台。你有没有带风筝？', `MaleText_loc5`='歡迎來到蟠龍之望。你有碰巧帶著風箏嗎?', `MaleText_loc7`='$GBienvenido:Bienvenida; al Mirador del Dragón. No habrás traído contigo una cometa por casualidad, ¿verdad?', `FemaleText_loc1`='용의 전망대에 잘 왔네. 혹시 연을 가지고 왔나?', `FemaleText_loc4`='欢迎来到青龙瞭望台。你有没有带风筝？', `FemaleText_loc5`='歡迎來到蟠龍之望。你有碰巧帶著風箏嗎?', `FemaleText_loc7`='$GBienvenido:Bienvenida; al Mirador del Dragón. No habrás traído contigo una cometa por casualidad, ¿verdad?' WHERE `ID`=64204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부들이 근처에 있는 밭에서 밀을 가져오면, 우리는 여기에서 그걸 빻아 곡식을 분류합니다.$B$B어떤 곡식은 음식으로 만들고, 또 어떤 건 돈을 받고 팝니다. 하지만 대부분은 스톰스타우트 양조장으로 가지요... 아시겠지만... 바로 맥주 때문입니다!', `MaleText_loc4`='附近地方的农夫把他们的大麦送到这里，我们磨成面粉并对谷物进行分类。$B$B有些谷物要做成食物，有些谷物拿去卖掉，但大部分都送到风暴烈酒酿造厂……你猜对了……酿啤酒！', `MaleText_loc5`='農夫們從附近的農地運來他們的小麥，然後我們在這裡將穀物磨碎及分類。$B$B有些穀物會被做成食物，但大部分都會被運到風暴烈酒酒坊做成...你猜對了...啤酒!', `MaleText_loc7`='Los granjeros de los campos cercanos traen el trigo, y nosotros los pasamos por el molino y clasificamos el grano aquí.$B$BParte del grano se convertirá en comida, otra parte servirá para comerciar, pero la mayor porción se envía a la Cervecería del Trueno para... imagínatelo... cerveza.' WHERE `ID`=64205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 평화로운 곳이네. 우리는 감시하고, 명상하고, 기술을 연마하고... 그것으로 만족하지.', `MaleText_loc4`='这是一个安宁的地方。我们欣赏风景，我们沉思，我们制作工艺品，我们心满意足。', `MaleText_loc5`='這是個平靜的地方。我們觀看、冥想、鑽研我們的技藝，我們很知足。', `MaleText_loc7`='Este es un remanso de paz. Aquí observamos, meditamos, trabajamos en nuestra artesanía, y nos sentimos contentos.', `FemaleText_loc1`='이곳은 평화로운 곳이네. 우리는 감시하고, 명상하고, 기술을 연마하고... 그것으로 만족하지.', `FemaleText_loc4`='这是一个安宁的地方。我们欣赏风景，我们沉思，我们制作工艺品，我们心满意足。', `FemaleText_loc5`='這是個平靜的地方。我們觀看、冥想、鑽研我們的技藝，我們很知足。', `FemaleText_loc7`='Este es un remanso de paz. Aquí observamos, meditamos, trabajamos en nuestra artesanía, y nos sentimos contentos.' WHERE `ID`=64206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽의 꽃에는 가 봤나? 그렇다면 혹시 골든드래프트 맥주 한 통 남은 건 없고?$b$b여기까지 배달을 시키기가 쉽지 않아서 말이야.', `MaleText_loc4`='你有没有去过晨芳园？你去那里的时候有没有多拿一个金酿的木桶？$b$b把它们运过来可不是什么轻松的事情。', `MaleText_loc5`='你有去過晨綻嗎?你有碰巧從那裏額外多帶了一個金流的桶子嗎?$b$b要把那些東西運來這裡不是件簡單的事。', `MaleText_loc7`='¿Has estado en Floralba? No habrás cogido por casualidad un barril extra de Brisa Dorada, ¿verdad?$b$bNo es que sea lo más sencillo del mundo el que los envíen aquí.', `FemaleText_loc1`='새벽의 꽃에는 가 봤나? 그렇다면 혹시 골든드래프트 맥주 한 통 남은 건 없고?$b$b여기까지 배달을 시키기가 쉽지 않아서 말이야.', `FemaleText_loc4`='你有没有去过晨芳园？你去那里的时候有没有多拿一个金酿的木桶？$b$b把它们运过来可不是什么轻松的事情。', `FemaleText_loc5`='你有去過晨綻嗎?你有碰巧從那裏額外多帶了一個金流的桶子嗎?$b$b要把那些東西運來這裡不是件簡單的事。', `FemaleText_loc7`='¿Has estado en Floralba? No habrás cogido por casualidad un barril extra de Brisa Dorada, ¿verdad?$b$bNo es que sea lo más sencillo del mundo el que los envíen aquí.' WHERE `ID`=64207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 님의 조각상이! ... 파괴되고 말았군.', `MaleText_loc4`='青龙！它……它碎掉了。', `MaleText_loc5`='玉蛟!它...它斷了。', `MaleText_loc7`='¡El Dragón de Jade! Se... Se ha roto.', `FemaleText_loc1`='옥룡 님의 조각상이! ... 파괴되고 말았군.', `FemaleText_loc4`='青龙！它……它碎掉了。', `FemaleText_loc5`='玉蛟!它...它斷了。', `FemaleText_loc7`='¡El Dragón de Jade! Se... Se ha roto.' WHERE `ID`=64208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아들에게 말했죠. 디온 말이에요. 비 오는 날에는 야크들을 바깥으로 데려나가지 말라고 했답니다. 그랬는데 어쨌는지 아세요? 비만 오면 야크들을 데려나간답니다.$B$B야크들이 아픈 것도 당연하죠!$B$B아... 어쩌다가 우리 아들이 이렇게 멍청하게 컸지?', `FemaleText_loc4`='我告诉过我的儿子，我告诉过迪恩，下雨时不要将牦牛带到牧场。然后他做了什么？他在雨天将牦牛带到牧场。$B$B现在我们的牦牛生病了，这并不奇怪！$B$B唉呀！我怎么会生出这样一个愚蠢的儿子？', `FemaleText_loc5`='我告訴過我兒子，我告訴過迪昂，下雨天不要把犛牛帶到牧場去。而他做了什麼好事?他在下雨天把犛牛帶出去。$B$B犛牛會生病一點都不令人意外!$B$B哎呀!我是怎麼養出這樣得笨兒子?', `FemaleText_loc7`='Se lo dije a mi hijo, se lo dije a Dion, no lleves a los yaks al campo cuando llueva. ¿Y qué es lo que hace? Saca a los yaks cuando llueve.$B$B¡No es de extrañar que ahora los yaks estén enfermos!$B$B¡Ay! ¿Cómo he criado un hijo tan despistado?' WHERE `ID`=64209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 아들은 많이 먹지 않아요. 좀 보세요! 거죽만 남아서 앙상하잖아요! 좀 더 먹여야겠어요.', `FemaleText_loc4`='我的儿子吃的不多。看看他！骨瘦如柴！我要多给他吃点儿。', `FemaleText_loc5`='我兒子吃的不夠多。看看他!骨瘦如柴又皮包骨!我必須餵他吃多一點。', `FemaleText_loc7`='Mi hijo no come bastante. ¡Míralo! Tan esquelético y tan esmirriado! Debo alimentarle más.' WHERE `ID`=64210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 우리 아들만 이렇게 키가 작은 거죠? 키가 훤칠하고, 힘도 세기를 바랐는데 말이에요.$B$B디온이 어렸을 때 집 안에서는 우산을 펴지 말라고 했어요. "아이고, 그러면 커서도 키가 안 자란다고!" 이러면서 말이죠.$B$B그랬더니 어쨌는지 아세요? 온종일 우산을 가지고 노는 거예요! 나 참!', `FemaleText_loc4`='为什么我的儿子就得是个矮子？我想要高大、强壮的儿子。$B$B在他小的时候，我就告诉他，不要在室内撑雨伞。我说，这样你会长不高！$B$B然后他做了什么？他总是打着雨伞玩！在房子里面！', `FemaleText_loc5`='為什麼我兒子這麼矮?我想要的是高大、強壯又年輕的兒子。$B$B在他小時候我告訴過他在屋內不要打傘。你會長不高!$B$B他做了什麼好事?他沒事就是在玩雨傘!在屋內!呿!', `FemaleText_loc7`='¿Por qué será mi hijo tan bajo? Yo quería un hijo alto, fuerte y joven. $B$BLe dije de pequeño que no abriera paraguas dentro de casa. ¡Crecerás poco, le decía! $B$B¿Y qué hace? ¡Juega con los paraguas todo el tiempo! ¡Dentro! ¡El colmo!' WHERE `ID`=64211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아들 디온이 그러는데 엄마가 만들어주는 만두가 네 바람의 계곡에서 제일 맛있대요!$B$B아이고, 귀여운 내 새끼.', `FemaleText_loc4`='我的儿子迪恩说，妈妈做的饺子是全谷最好吃的！$B$B噢哈哈哈。真是我的好儿子。', `FemaleText_loc5`='我兒子迪昂說老媽做的餃子是整個峽谷中最棒的!$B$B喔呼呼呼。我的好兒子。', `FemaleText_loc7`='Mi hijo Dion dice que mamá hace las mejores albóndigas de todo el valle.$B$BOoohoohoohooo. Ese es mi chico.' WHERE `ID`=64212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 오렌지를 아주 좋아한답니다. 그런데 네 바람의 계곡에서는 구하기가 어려워요.$B$B그래서 아들에게 시장에서 오렌지를 사오라고 동전을 좀 줬답니다.$B$B그랬더니 어쨌는지 아세요? 콩을 사온 거지 뭐예요!$B$B우리는 농부가 아닌데 말이죠! 우리는 야크를 키우잖아요! 이 멍청한 콩으로 대체 뭘 해야 하는 거죠, 네?', `FemaleText_loc4`='妈妈喜欢吃橙子，但在谷里很难找到橙子。$B$B我给我的儿子一些铜钱，让他去市集上买一些橘子。$B$B然后他做了什么？他买了一些豆子！$B$B我们又不是农民！我们是放养牦牛的牧民！我问你，我该怎么处理这些愚蠢的豆子？', `FemaleText_loc5`='老媽喜歡柳橙，但峽谷裡很難找到柳橙。$B$B我要我兒子去市集買一些柳橙，所以我給了他一些銅幣。$B$B他做了什麼好事?他買了些豆子!$B$B我們又不是農夫!我們是犛牛牧人!我該拿這些蠢豆子怎麼辦，我問你?', `FemaleText_loc7`='A mamá le encantan las naranjas, pero son difíciles de encontrar en el valle.$B$BLe dije a mi hijo que comprara naranjas en el valle, así que le di una moneda.$B$B¿Y qué hace? ¡Va y compra frijoles!$B$B¡No somos granjeros, somos pastores de yaks! ¿Qué hago yo con unas estúpidos frijoles?' WHERE `ID`=64213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠과 진위는 항상 싸워 왔네. 하지만 이렇게까지는 아니었지...', `MaleText_loc4`='猢狲和锦鱼人总是在战斗，但从来没有像这样……', `MaleText_loc5`='猴人和錦魚人總是在交戰，但從來不像這樣...', `MaleText_loc7`='Los hozen y los jinyu siempre se han peleado entre ellos, pero nunca de esta manera...', `FemaleText_loc1`='호젠과 진위는 항상 싸워 왔네. 하지만 이렇게까지는 아니었지...', `FemaleText_loc4`='猢狲和锦鱼人总是在战斗，但从来没有像这样……', `FemaleText_loc5`='猴人和錦魚人總是在交戰，但從來不像這樣...', `FemaleText_loc7`='Los hozen y los jinyu siempre se han peleado entre ellos, pero nunca de esta manera...' WHERE `ID`=64214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 아들 디온은 하루 종일 밖에 나가 있어요. 일도 너무 열심히 하고요. 너무 자랑스러워요.', `FemaleText_loc4`='我的儿子迪恩整天在牧场。他这么努力工作。妈妈很自豪。', `FemaleText_loc5`='我兒子迪昂整天都在牧場裡。他非常努力工作。讓老媽很驕傲。', `FemaleText_loc7`='Mi hijo Dion estará en el campo todo el día. Trabaja muy duro. Mamá está muy orgullosa.' WHERE `ID`=64215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 님의 조각상이... 이제 우리는 어떻게 해야 하지?', `MaleText_loc4`='青龙……它现在想做什么？', `MaleText_loc5`='玉蛟...它現在會怎麼做?', `MaleText_loc7`='El Dragón de Jade... ¿Qué pasará ahora?', `FemaleText_loc1`='옥룡 님의 조각상이... 이제 우리는 어떻게 해야 하지?', `FemaleText_loc4`='青龙……它现在想做什么？', `FemaleText_loc5`='玉蛟...它現在會怎麼做?', `FemaleText_loc7`='El Dragón de Jade... ¿Qué pasará ahora?' WHERE `ID`=64216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일은 어떤 의미일까? 판다리아의 평화는 끝난 건가? 이제 우리에겐... 파멸뿐일까?', `MaleText_loc4`='这是什么意思？潘达利亚的和平结束了吗？这是命中注定的吗？', `MaleText_loc5`='這代表什麼意義?潘達利亞的和平結束了?我們完蛋了嗎?', `MaleText_loc7`='¿Qué significa esto? ¿Es el fin de la paz en Pandaria? ¿Estamos condenados?', `FemaleText_loc1`='이 일은 어떤 의미일까? 판다리아의 평화는 끝난 건가? 이제 우리에겐... 파멸뿐일까?', `FemaleText_loc4`='这是什么意思？潘达利亚的和平结束了吗？这是命中注定的吗？', `FemaleText_loc5`='這代表什麼意義?潘達利亞的和平結束了?我們完蛋了嗎?', `FemaleText_loc7`='¿Qué significa esto? ¿Es el fin de la paz en Pandaria? ¿Estamos condenados?' WHERE `ID`=64217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 보러 오신 건가요? 아, 잠깐 앉아보세요!$B$B저번에 들었던 소문을 이야기해드릴게요.$B$B지나 머드클로 있잖아요? 아버지인 하오한 씨와 사이가 안 좋다더라고요!$B$B하오한 씨는 지나를 저쪽 신록지대에 사는 농부 펑과 결혼시키고 싶어했지만, 지나는 싫어했대요! 자기 말로는 시장을 운영하고 싶다고 그러더라고요.$B$B아이고, 요즘 젊은 애들은 왜 그러는지 모르겠네요? 잘생기고 젊은 남자랑 결혼해서 가정을 이루는 게 싫은가?$B$B특히 펑은... 정말 매력 덩어리인데. 아주 잘생겼고, 채소도 엄청나게 크게 키워내고 말이죠.$B$B왜 저는 그렇게 젊고 멋진 아들이 없는 건지 참!!', `FemaleText_loc4`='你来看妈妈吗？噢，坐一会儿！$B$B我告诉你，几天前，我听到一些流言。$B$B我听说吉娜·泥爪和她的父亲郝瀚·泥爪合不来！$B$B他想把她嫁给农夫老方，但她不愿意！她说她想经营她的市集。$B$B唉呀！现在的年轻姑娘们是怎么了？不想嫁给英俊的小伙子，不想成家吗？$B$B特别是老方……他这么抢手！人长得好看，又种出这么大棵的蔬菜。$B$B我的儿子怎么就没那么年轻英俊？！', `FemaleText_loc5`='你是來看老媽的嗎?喔，坐下來歇會兒!$B$B讓我跟你說，我有天聽到了一些小道消息。$B$B我聽說吉娜·泥爪和她爸爸好漢·泥爪相處得並不好!$B$B他想把她嫁給在蒼翠牧場那邊的農夫老豐，但她不願意!她說她想要經營她的市集。$B$B哎呀!這年頭的年輕女孩是怎麼了?不想要嫁給帥氣的年輕人組成家庭?$B$B特別是那個老豐...他是個這麼好的對象!長得那麼帥，又種植那麼大的蔬菜。$B$B為什麼我沒有個像他那麼帥的年輕兒子?!', `FemaleText_loc7`='¿Vienes a ver a mamá? ¡Oh, siéntate un poco!$B$BDeja que te cuente, el otro día oí un cotilleo.$B$B¡Oí que Gina Zarpa Fangosa y su padre Haohan Zarpa Fangosa no se llevan bien!$B$BÉl la quería casar con el granjero Fung, de la franja, ¡pero ella no quiere! Quería llevar su propio mercado, dijo.$B$B¡Ay! ¿En qué se han convertido las chicas de hoy en día? ¿No quieren casarse con un hombre guapo y tener una famila?$B$BSobre todo ese Fung... ¡es un partidazo! Tan apuesto, y cultiva unas verduras bien hermosas.$B$B¿Por qué yo no tendré un hijo joven y guapo como él?' WHERE `ID`=64218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 대체 우리 아들은 언제쯤이면 예쁘고 젊은 아가씨를 만날 수 있을까요? 하는 일이라고는 하루 종일 야크들 주변만 맴도니 참!$B$B어떤 여자가 냄새 나는 야크치기를 원하겠어요, 네? 아이고, 정말 한걱정이에요...', `FemaleText_loc4`='噢，我的儿子什么时候能遇见一位年轻漂亮的女子？他整天围着牦牛转！$B$B哪个女孩愿意嫁给臭烘烘的牦牛牧人啊？唉呀，妈妈真担心……', `FemaleText_loc5`='喔，我兒子什麼時候才能遇到一個年輕好姑娘?他整天就只是跟犛牛在一起!$B$B什麼樣的女孩會想要一群臭到不行的犛牛，嗯?哎呀，老媽擔心太多了...', `FemaleText_loc7`='¿Cuándo va a conocer a mi hijo a una buena chica? ¡Todo lo que hace estar con los yaks todo el día!$B$B¿Qué chica va a querer a un pastor de yaks apestoso? Ay, ay, ay... mamá está muy preocupada.' WHERE `ID`=64219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 안녕하세요, $r님!$B$B여기가 우리 농사에 관련된 역사와 지식을 보관하는 곳이랍니다.$B$B이 지역 날씨와 수확량, 네 바람의 계곡에 있는 모든 식물과 종자에 대한 상세한 정보와 더불어 나중에 재배해야 할지도 모르는 모든 작물의 종자까지도 보관되어 있죠.$B$B이 지식은 우리에게 정말 중요해요. 이 땅에 재앙이 닥치더라도 이 씨앗들은 안전해야만 한답니다.', `FemaleText_loc4`='啊，你好，$r！$B$B这是保留我们所有耕种历史和知识的地方。$B$B我们记录当地的天气，以及相应的收成，详细到谷里的每一粒种子和每一棵植物，甚至我们可能会不断种植的一堆种子。$B$B这些知识对我们而言是神圣的。即使有一天灾难会降临到这片土地上，我们也必须要保存这些种子。', `FemaleText_loc5`='啊，哈囉，$r!$B$B我們把所有農耕的歷史與知識都保存在這裡。$B$B我們有地方的天氣和收成結果記綠、生長在峽谷中的每個種子和每株作物的詳細注記，甚至還有個存放所有我們會需要種植的作物種子的銀行。$B$B這些知識對我們來說是神聖的。假如災難有天降臨在這塊土地上，我們的種子必須被保存下來。', `FemaleText_loc7`='¡Ah, hola, $r!$B$BAquí es donde conservamos toda nuestra historia y nuestro conocimiento acerca de la agricultura.$B$BTenemos registros del tiempo local y de la cosecha resultante, notas detalladas para cada semilla y cada planta que crece en el valle, e incluso un banco de semillas de todas las plantas que podemos necesitar cultivar.$B$BEste conocimiento es sagrado para nosotros. Si alguna vez ocurriera un desastre en esta tierra, la semillas deben ser puestas a salvo.' WHERE `ID`=64220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 여행자님. 저는 또 다른 명작을 만들어내려고 열심히 일하는 중입니다!', `MaleText_loc4`='你好，旅行者。我在努力工作，打造我的下一个杰作！', `MaleText_loc5`='哈囉，旅人。我正在努力製作我的下一個傑作!', `MaleText_loc7`='Hola, viajante. ¡Me estoy dejando el pellejo en la creación de mi nueva obra maestra!' WHERE `ID`=64221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 님의 조각상이 부서졌다고? 대체 어쩌다 그런 일이 일어났지?', `MaleText_loc4`='青龙雕像被毁坏了吗？怎么可能发生这样的事？', `MaleText_loc5`='玉蛟雕像被破壞了?怎麼可能會發生這種事?', `MaleText_loc7`='¿Que la estatua del Dragón de Jade ha sido destruida? ¿Cómo ha podido suceder?', `FemaleText_loc1`='옥룡 님의 조각상이 부서졌다고? 대체 어쩌다 그런 일이 일어났지?', `FemaleText_loc4`='青龙雕像被毁坏了吗？怎么可能发生这样的事？', `FemaleText_loc5`='玉蛟雕像被破壞了?怎麼可能會發生這種事?', `FemaleText_loc7`='¿Que la estatua del Dragón de Jade ha sido destruida? ¿Cómo ha podido suceder?' WHERE `ID`=64222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 가만히 새를 보는 것 안 좋아하세요? 저도 날 수 있으면 좋겠어요.', `FemaleText_loc4`='难道你只喜欢看着鸟儿吗？我真想我也能飞。', `FemaleText_loc5`='你難道不喜歡就這樣看著小鳥嗎?我好希望我也能飛翔。', `FemaleText_loc7`='¿No te encanta ver a los pájaros? A mí también me encantaría poder volar.' WHERE `ID`=64223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='농부들은 비가 오게 해달라며 기도를 하지만, 저는 안 해요! 장사를 완전히 망친다고요. 제 시장을 보세요! 흠뻑 젖었잖아요!', `FemaleText_loc4`='农民祈求降雨，但我不！雨天对做生意来说非常糟糕。看看我的市集！湿透了！', `FemaleText_loc5`='農夫們祈求能下雨，但我可不想!那對生意不好。看看我的市集!溼答答的!', `FemaleText_loc7`='Los granjeros rezan para que llueva, pero yo no. Es un asunto muy peliagudo. ¡Mira mi mercado! ¡Está empapado!' WHERE `ID`=64224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 비가 정말 많이 오네요! 뭐, 날이 좋든 나쁘든, 저는 장사를 해야 해요!', `FemaleText_loc4`='今天得在雨中做牦牛和穆山兽生意！好吧，无论天晴下雨，我都要经营这个市集。', `FemaleText_loc5`='今天下著傾盆大雨!我有個市集得經營，雨天或晴天都一樣!', `FemaleText_loc7`='¡Hoy llueven yaks y mushan! ¡Tengo un mercado que llevar, llueva o luzca el sol!' WHERE `ID`=64225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님! 하늘을 보십시오! 비가 옵니다! 농작물들이 좋아하겠지요, 네?', `MaleText_loc4`='看看天空，$n！下雨了！对作物生长应该有好处吧？', `MaleText_loc5`='看天空，$n!下雨了!應該對農作物有幫助，嗯?', `MaleText_loc7`='¡Mira al cielo, $n! ¡Está lloviendo! Será bueno para los cultivos, ¿eh?' WHERE `ID`=64226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 이 폭풍우 좀 보십시오! 뭐, 농작물은 물을 좋아하니까요, 안 그렇습니까?', `MaleText_loc4`='哇，看看这场暴风雨！嗯，作物喜欢喝水，对不对？', `MaleText_loc5`='哇喔，看看這場風暴!農作物喜歡水，對吧?', `MaleText_loc7`='¡Guau! ¡Mira qué tormenta! Bueno, al grano le gusta el agua, ¿no?' WHERE `ID`=64227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 조각상이 파괴되었다고 하셨습니까? 어떻게 그런 일이?', `MaleText_loc4`='青龙雕像被毁坏了吗？怎么可能发生这样的事？', `MaleText_loc5`='玉蛟像被毀了?怎麼可能發生這種事?', `MaleText_loc7`='¿Que la estatua del Dragón de Jade ha sido destruida? ¿Cómo ha podido suceder?', `FemaleText_loc1`='옥룡 조각상이 파괴되었다고요? 어떻게 그런 일이?', `FemaleText_loc4`='青龙雕像被毁坏了吗？怎么可能发生这样的事？', `FemaleText_loc5`='玉蛟像被毀了?怎麼可能發生這種事?', `FemaleText_loc7`='¿Que la estatua del Dragón de Jade ha sido destruida? ¿Cómo ha podido suceder?' WHERE `ID`=64228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 "샤"라는 게 뭡니까? 어디서 온 것입니까?', `MaleText_loc4`='“煞魔”是什么？它从哪里来的？', `MaleText_loc5`='這個「煞」是什麼東西?是從哪來的?', `MaleText_loc7`='"¿Qué es ese "sha"? ¿De dónde viene?', `FemaleText_loc1`='이 "샤"라는 게 뭐죠? 어디서 온 건가요?', `FemaleText_loc4`='“煞魔”是什么？它从哪里来的？', `FemaleText_loc5`='這個「煞」是什麼東西?是從哪來的?', `FemaleText_loc7`='"¿Qué es ese "sha"? ¿De dónde viene?' WHERE `ID`=64229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 치유할 수 있게 우릴 도와주시겠습니까?', `MaleText_loc4`='你会帮助我们治愈土地吗？', `MaleText_loc5`='你願意幫我們治癒這片土地嗎?', `MaleText_loc7`='¿Nos ayudarás a sanar esta tierra?', `FemaleText_loc1`='이 땅을 치유할 수 있게 우릴 도와주실 건가요?', `FemaleText_loc4`='你会帮助我们治愈土地吗？', `FemaleText_loc5`='你願意幫我們治癒這片土地嗎?', `FemaleText_loc7`='¿Nos ayudarás a sanar esta tierra?' WHERE `ID`=64230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 호젠과 진위! 둘이 서로를 싫어하는 건 알았지만, 일이 이렇게까지 될 줄은 몰랐습니다...', `MaleText_loc4`='可怜的猢狲和锦鱼人！我们知道他们不喜欢对方，但走到今天这一步……', `MaleText_loc5`='可憐的猴人和錦魚人!我們本來就知道他們彼此不和，但鬧到這種程度...', `MaleText_loc7`='¡Pobres hozen y jinyu! Sabíamos que no se gustaban, pero no hasta este punto...', `FemaleText_loc1`='불쌍한 호젠과 진위! 둘이 서로를 싫어하는 건 알았지만, 일이 이렇게까지 될 줄은 몰랐어요...', `FemaleText_loc4`='可怜的猢狲和锦鱼人！我们知道他们不喜欢对方，但走到今天这一步……', `FemaleText_loc5`='可憐的猴人和錦魚人!我們本來就知道他們彼此不和，但鬧到這種程度...', `FemaleText_loc7`='¡Pobres hozen y jinyu! Sabíamos que no se gustaban, pero no hasta este punto...' WHERE `ID`=64231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠과 진위가 모두 그 전투에서 멸망한 겁니까? 생존자는 없습니까?', `MaleText_loc4`='所有锦鱼人和猢狲都在那次战斗中灭亡了吗？有幸存者吗？', `MaleText_loc5`='所有的錦魚人和猴人都在那場戰鬥中死了嗎?有倖存者嗎?', `MaleText_loc7`='¿Han muerto todos los hozen y todos los jinyu en esa batalla? ¿Ha habido supervivientes?', `FemaleText_loc1`='호젠과 진위가 모두 그 전투에서 멸망한 건가요? 생존자는 없나요?', `FemaleText_loc4`='所有锦鱼人和猢狲都在那次战斗中灭亡了吗？有幸存者吗？', `FemaleText_loc5`='所有的錦魚人和猴人都在那場戰鬥中死了嗎?有倖存者嗎?', `FemaleText_loc7`='¿Han muerto todos los hozen y todos los jinyu en esa batalla? ¿Ha habido supervivientes?' WHERE `ID`=64232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 샤에 맞서실 겁니까?', `MaleText_loc4`='你会帮助我们对付煞魔吗？', `MaleText_loc5`='你會幫我們對抗煞嗎?', `MaleText_loc7`='¿Nos ayudarás a luchar contra el sha?', `FemaleText_loc1`='우리와 함께 샤에 맞서실 건가요?', `FemaleText_loc4`='你会帮助我们对付煞魔吗？', `FemaleText_loc5`='你會幫我們對抗煞嗎?', `FemaleText_loc7`='¿Nos ayudarás a luchar contra el sha?' WHERE `ID`=64233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 많은 것을... 잃었군.$b$b난 두렵네, $n. 이 모든 것이 시작에 불과하다는 것이...', `MaleText_loc4`='失去了……这么多。$b$b我担心，$n，这仅仅只是个开始。', `MaleText_loc5`='失去了...這麼多。$b$b而我恐怕，這只是一個開始，$n。', `MaleText_loc7`='Hemos perdido tanto...$b$bY me temo, $n, que esto es solo el principio.' WHERE `ID`=64234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희와는 할 말이 없다! $p에게만 말할 것이다.', `MaleText_loc4`='我没什么要对你说的！我只和$p说话。', `MaleText_loc5`='我對你沒什麼好說的!我只會和$p說話。', `MaleText_loc7`='¡No tengo nada que decirles! Solo hablaré con $p.' WHERE `ID`=64235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음? 뭐라고 하셨습니까?', `MaleText_loc4`='嗯？你说什么？', `MaleText_loc5`='哦?你剛剛說什麼?', `MaleText_loc7`='¿Eh? ¿Qué has dicho?' WHERE `ID`=64236;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상어를 볼 수 있나요?', `FemaleText_loc4`='我们会看到鲨鱼吗？', `FemaleText_loc5`='我們會看到鯊魚嗎?', `FemaleText_loc7`='¿Vamos a ver tiburones?' WHERE `ID`=64237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 시간이 있으면.', `MaleText_loc4`='如果还有时间的话。', `MaleText_loc5`='如果有時間的話。', `MaleText_loc7`='Si hay tiempo.' WHERE `ID`=64238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래된 상자는 먼지로 뒤덮여 있습니다...', `MaleText_loc4`='古老的箱子布满灰尘……', `MaleText_loc5`='這古老的箱子上覆滿了灰塵...', `MaleText_loc7`='El cofre antiguo está cubierto de polvo.' WHERE `ID`=64239;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어디 가는 거예요?', `FemaleText_loc4`='我们去哪儿？', `FemaleText_loc5`='我們要去哪啊?', `FemaleText_loc7`='¿Dónde vamos?' WHERE `ID`=64240;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시장에서 생선을 사 올 시간이란다.', `FemaleText_loc4`='该是去市集买鱼的时候了。', `FemaleText_loc5`='是時候去市集買魚了。', `FemaleText_loc7`='Es hora de coger el pescado en el mercado.' WHERE `ID`=64241;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 멀었나요?', `FemaleText_loc4`='我们到了吗？', `FemaleText_loc5`='我們到了沒啊?', `FemaleText_loc7`='¿Hemos llegado ya?' WHERE `ID`=64242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 왔어. 조금만 더 참으렴.', `MaleText_loc4`='我们快到了。还有一小段路程。', `MaleText_loc5`='我們就快到了。只剩一點點路程。', `MaleText_loc7`='Ya casi. Solo un poco más.' WHERE `ID`=64243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 저 업어주실 수 있어요?', `FemaleText_loc4`='爸爸，你能抱我吗？', `FemaleText_loc5`='你能背我嗎，爸爸?', `FemaleText_loc7`='¿Me llevas, papá?' WHERE `ID`=64244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 된다, 얘야. 조금 걸어야 다리가 멋지고 튼튼해진단다. 언젠가 이 아빠처럼 강한 사람이 되고 싶지 않니?', `MaleText_loc4`='不行，亲爱的。我要你的腿长得即好看又结实。你希望有一天像我一样强壮，对吗？', `MaleText_loc5`='不，蜜糖熊熊。我需要你讓那些腿長得又好又壯。你有一天想和我一樣強壯，對吧?', `MaleText_loc7`='Nada de tonterías. Necesito que tengas esas piernas fuertes y en forma. Algún día querrás ser tan fuerte como yo, ¿verdad?' WHERE `ID`=64245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이게 여기 뒤에 있을 줄은 정말 몰랐네요.', `FemaleText_loc4`='哇！我从来不知道这会回到这里。', `FemaleText_loc5`='哇喔!我從來不知道後面有這東西。', `FemaleText_loc7`='¡Guau! No sabía que esto estuviera aquí.' WHERE `ID`=64246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으으으으, 무섭지 않아요? 저기 안에 귀신이 있지 않을까요?', `FemaleText_loc4`='哇！这不可怕吗？你觉得那里有鬼吗？', `FemaleText_loc5`='喔喔喔喔，這不是很嚇人嗎?你覺得這裡有鬼嗎?', `FemaleText_loc7`='Oooooh, ¿no da miedo? ¿Crees que hay fantasmas allí?' WHERE `ID`=64247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으으으으으으으! 저게 뭐야?', `FemaleText_loc4`='呃！那是什么东西？', `FemaleText_loc5`='噁噁噁!那是什麼東西?', `FemaleText_loc7`='¡Eeeeeeeh! ¿Qué es eso?' WHERE `ID`=64248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 있다! 저기 늙은 엉겅퀴 노인의 보물이 있어요!', `FemaleText_loc4`='就在那！老农阿蓟的宝藏！', `FemaleText_loc5`='在那裡!寂老頭的寶藏!', `FemaleText_loc7`='¡Ahí está! ¡El tesoro de Cardo el Viejo!' WHERE `ID`=64249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우우우우우우우우우우와!', `FemaleText_loc4`='哇噢！', `FemaleText_loc5`='哇喔哇喔!', `FemaleText_loc7`='¡Guuuuuau!' WHERE `ID`=64250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야 신난다! 우리가 찾아냈어요! 이건 엉겅퀴 노인의 숨겨진 보물이라고요! 우와! 우와! 우와!', `FemaleText_loc4`='万岁！我们找到了！我们找到了！老农阿蓟的秘密宝藏！哦天哪哦天哪哦天哪！！！', `FemaleText_loc5`='太神奇了!我們找到了!我們真的找到了!寂老頭的隱藏寶藏!喔老天喔老天喔老天!!!', `FemaleText_loc7`='¡Carámbanos! ¡Lo hemos encontrado! ¡De verdad lo encontramos! El tesoro escondido de Cardo el Viejo. ¡Oh, cielos, cielos!' WHERE `ID`=64251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네? 처녀라고요? 흠, 아버지께서 북쪽에 있는 강을 그렇게 부르시곤 하던 게 기억나네요. 그것 말고는 짐작가는 게 없네요.', `FemaleText_loc4`='少女，不是吗？嗯，我记得那就是我父亲过去常说的北面的河流。除此之外，我没有其他线索。', `FemaleText_loc5`='你問「淑女」代表什麼嗎?嗯嗯，我記得我爸以前都是用「淑女」來稱呼北邊那條河。除此之外，我一點頭緒都沒有。', `FemaleText_loc7`='La doncella, ¿eh? Recuerdo que así solía llamar mi padre a ese río del norte. Si no es eso, no tengo ni la más remota idea.' WHERE `ID`=64252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메아리는 뭐고 어둠은 뭐냐고요? 간단하지 않습니까! 바로 동굴입니다!', `MaleText_loc4`='什么回声，那黑黑的是什么？这还不知道！是个山洞！', `MaleText_loc5`='什麼東西會有回聲而且很幽暗?很簡單:一個山洞!', `MaleText_loc7`='¿Dónde hay eco y está oscuro? ¡Es fácil! ¡En una cueva!' WHERE `ID`=64253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음, 잘 모르겠습니다. $r님. 제가 알아들을 수 있는 건 계곡에 관한 부분뿐이군요. 바로 여기니까요! 네 바람의 계곡 말입니다!', `MaleText_loc4`='嗯，我还真不知道呢，$r。我以为是山谷的一部分，就是这里！四风谷！', `MaleText_loc5`='嗯嗯，我想我不知道，$r。我能理解的就只有關於峽谷的那部分 - 就在這裡!四風峽!', `MaleText_loc7`='Mmm, me parece que no lo sé, $r. Todo lo que entiendo es la parte acerca del valle, ¡es justo aquí! ¡El Valle de los Cuatro Vientos!' WHERE `ID`=64254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 조상의 계단 이야기는 들어본 적 있습니다. 여기 주민 중 누가 북쪽에 있는 산을 그렇게 부르더군요.', `MaleText_loc4`='噢，我听说过先祖的阶梯。有些人就是这么称呼北面的群山的。', `MaleText_loc5`='喔，我有聽說過「祖階」。有些人就是用「祖階」來稱呼北方的那些山峰。', `MaleText_loc7`='Oh, he oído hablar de la escalera de los ancestros. Así llaman a esas montañas del norte algunos lugareños.' WHERE `ID`=64255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 단서들이 뭘 의미하는지 아시겠습니까?', `MaleText_loc4`='你可以找到什么线索吗？', `MaleText_loc5`='你能從這些線索看出任何蛛絲馬跡嗎?', `MaleText_loc7`='¿Puedes hacer algo con estas pistas?', `FemaleText_loc1`='이 단서들이 뭘 의미하는지 아시겠어요?', `FemaleText_loc4`='你可以找到什么线索吗？', `FemaleText_loc5`='你能從這些線索看出任何蛛絲馬跡嗎?', `FemaleText_loc7`='¿Puedes hacer algo con estas pistas?' WHERE `ID`=64256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 처녀가 금부채 뒤에서 웃고 있다는 이야기 들어보신 적 있습니까?', `MaleText_loc4`='你听过少女掩扇而笑的声音吗？', `MaleText_loc5`='你有曾經聽說過「金扇掩面淑女嫣」嗎?', `MaleText_loc7`='¿Has oído hablar alguna vez de doncellas riendo tras un abanico?', `FemaleText_loc1`='한 처녀가 금부채 뒤에서 웃고 있다는 이야기 들어보신 적 있나요?', `FemaleText_loc4`='你听过少女掩扇而笑的声音吗？', `FemaleText_loc5`='你有曾經聽說過「金扇掩面淑女嫣」嗎?', `FemaleText_loc7`='¿Has oído hablar alguna vez de doncellas riendo tras un abanico?' WHERE `ID`=64257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조상의 계단은 어디 있습니까?', `MaleText_loc4`='我在哪里可以找到先祖的阶梯？', `MaleText_loc5`='我能在哪裡找到「祖階」呢?', `MaleText_loc7`='¿Dónde puedo encontrar la escalera de los ancestros?', `FemaleText_loc1`='조상의 계단은 어디 있나요?', `FemaleText_loc4`='我在哪里可以找到先祖的阶梯？', `FemaleText_loc5`='我能在哪裡找到「祖階」呢?', `FemaleText_loc7`='¿Dónde puedo encontrar la escalera de los ancestros?' WHERE `ID`=64258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 메아리치는 어둠 안으로 비밀을 속삭일 수 있는 곳은 어디입니까?', `MaleText_loc4`='在哪里可以对有回音的黑洞中发出低语？', `MaleText_loc5`='在哪裡才能有人能做出「絕密輕語翩，回聲幽暗間」呢?', `MaleText_loc7`='¿Dónde puede alguien susurrar secretos a un eco oscuro?', `FemaleText_loc1`='누군가가 메아리치는 어둠 안으로 비밀을 속삭일 수 있는 곳은 어디인가요?', `FemaleText_loc4`='在哪里可以对有回音的黑洞中发出低语？', `FemaleText_loc5`='在哪裡才能有人能做出「絕密輕語翩，回聲幽暗間」呢?', `FemaleText_loc7`='¿Dónde puede alguien susurrar secretos a un eco oscuro?' WHERE `ID`=64259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 대전에서 저를 이기실 수 있겠어요? 여자들은 대부분 뱀을 싫어하지만, 저는 뱀이 귀엽답니다!', `MaleText_loc4`='你可以让我加入战斗吗？大多数小女孩讨厌蛇，但我觉得蛇很可爱！', `MaleText_loc5`='你覺得自己有能力打贏我嗎?大部分女孩都討厭蛇，但我覺得牠們很可愛!', `MaleText_loc7`='¿Crees que puedes vencerme en duelo? ¡La mayoría de las chicas odian las serpientes, pero yo creo que son preciosas!', `FemaleText_loc1`='애완동물 대전에서 저를 이기실 수 있겠어요? 여자들은 대부분 뱀을 싫어하지만, 저는 뱀이 귀엽답니다!', `FemaleText_loc4`='你可以让我加入战斗吗？大多数小女孩讨厌蛇，但我觉得蛇很可爱！', `FemaleText_loc5`='你覺得自己有能力打贏我嗎?大部分女孩都討厭蛇，但我覺得牠們很可愛!', `FemaleText_loc7`='¿Crees que puedes vencerme en duelo? ¡La mayoría de las chicas odian las serpientes, pero yo creo que son preciosas!' WHERE `ID`=64260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 우리 가족은 강태공 연합에서 신선한 생선을 구입하고 마을에 공급하는 일을 합니다. 혹시 생선 한 마리 사 가시겠습니까?', `MaleText_loc4`='我和我的家人将新鲜的鱼从渔人码头带到镇上。你想买一些吗？', `MaleText_loc5`='我的家族和我正從釣手隊那裡將鮮魚運來城鎮裡。你想要買一些嗎?', `MaleText_loc7`='Mi familia y yo llevamos pescado fresco de los pescadores a la ciudad. ¿Quieres comprar algo?' WHERE `ID`=64261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 마을에서 스리라 마을까지는 꽤 먼 길이지만, 그래도 가는 길에는 무척 기분이 좋아요. 게다가 우리 아리엘과 함께 야외로 나오는 건, 더 좋은 일이죠.', `FemaleText_loc4`='从镇上到香里拉有很长一段路，但走路对精神有好处。这肯定有助于让小艾黎到户外活动。', `FemaleText_loc5`='從城鎮走到斯里拉要走一段很長的路，但對精神很好。而且在這戶外能爬高一些肯定有些幫助。', `FemaleText_loc7`='Es una larga caminata desde la ciudad a Sri-La, pero es buena para el espíritu. Y no cabe duda que viene bien para coger aire del exterior.' WHERE `ID`=64262;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모르는 분하고 얘기하면 안 돼요.', `FemaleText_loc4`='我不应该和陌生人说话。', `FemaleText_loc5`='我不應該和陌生人說話。', `FemaleText_loc7`='Se supone que no debo hablar con forasteros.' WHERE `ID`=64263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='5.0 요리 - 요리 제자 기본 1', `MaleText_loc4`='5.0 烹饪——烹饪学生缺省1', `MaleText_loc5`='5.0 Cooking - Cooking Student Default 1', `MaleText_loc7`='Cocina 5.0 Cooking - Estudiante de cocina por defecto 1' WHERE `ID`=64264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 저기 아래에 있는 큰 물고기 보이세요?', `FemaleText_loc4`='你看到那边的大鱼了吗，$n？', `FemaleText_loc5`='你有看到在下面的那條大魚嗎，$n?', `FemaleText_loc7`='¿Ves ese pez grande ahí, $n?' WHERE `ID`=64265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몰래 다가오려고 하지 마세요! 아빠는 항상 저보고 뒤에도 눈이 달렸다고 하셨으니까요!', `FemaleText_loc4`='你不要试图接近我！我的朋友总说我的脑后门上长着眼睛！', `FemaleText_loc5`='你別想偷偷摸摸地對我搞鬼!我老爸總是說我後腦有長眼睛!', `FemaleText_loc7`='¡No intentes pillarme por sorpresa! ¡Mi padre siempre decía que tenía ojos en el cogote!' WHERE `ID`=64266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 도와드릴까요?', `FemaleText_loc4`='我能为你做些什么吗，$n？', `FemaleText_loc5`='我能為你做什麼嗎，$n?', `FemaleText_loc7`='¿Qué puedo hacer por ti, $n?' WHERE `ID`=64267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야! 아직도 우리가 늙은 엉겅퀴 노인의 보물을 찾아냈다는 게 믿기지 않아요, 우리 식구 $n 님. 전설은 결국 전설일 뿐인 것 같지만, 그래도 그걸 이야기하는 건 여전히 좋아요!', `FemaleText_loc4`='哇噢！我仍然无法相信，我们发现了老农阿蓟的宝藏。我想所有这些民间故事并非完全真实，但我还是乐意讲给他们听！', `FemaleText_loc5`='嗚耶!我還是無法相信我們找到了寂老頭的寶藏。我想那些民間故事畢竟不是那麼真實，但我還是喜歡說!', `FemaleText_loc7`='¡Guuuau! No me puedo creer que hayamos encontrado el tesoro de Cardo el Viejo. Parece que esos cuentos de viejas no eran ciertos, después de todos. ¡Pero me gusta contarlos igual!' WHERE `ID`=64268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙은 엉겅퀴 노인 이야기를 해주십시오.', `MaleText_loc4`='告诉我老农阿蓟的故事。', `MaleText_loc5`='告訴我寂老頭的故事。', `MaleText_loc7`='Cuéntame la historia de Cardo el Viejo.', `FemaleText_loc1`='늙은 엉겅퀴 노인 이야기를 해주세요.', `FemaleText_loc4`='告诉我老农阿蓟的故事。', `FemaleText_loc5`='告訴我寂老頭的故事。', `FemaleText_loc7`='Cuéntame la historia de Cardo el Viejo.' WHERE `ID`=64269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 들리는 말로는 그 지도를 손에 넣으면 잃어버린 보물을 찾을 수 있다더라고요...', `FemaleText_loc4`='现在他们说，无论谁得到地图，都可以找到失去的宝藏……', `FemaleText_loc5`='如今人們都說只要能拿到那張地圖的人，就能找到那失落的寶藏...', `FemaleText_loc7`='Ahora dicen que cualquiera que pudiera ponerle las manos encima al mapa encontraría el tesoro...' WHERE `ID`=64270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그렇습니까? 더 이야기해주십시오.', `MaleText_loc4`='噢？告诉我更多详情。', `MaleText_loc5`='是嗎?再多說一點。', `MaleText_loc7`='¿Ah, sí? Cuéntame más.', `FemaleText_loc1`='아, 그래요? 더 이야기해주세요.', `FemaleText_loc4`='噢？告诉我更多详情。', `FemaleText_loc5`='是嗎?再多說一點。', `FemaleText_loc7`='¿Ah, sí? Cuéntame más.' WHERE `ID`=64271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가라. 내 기술을 수습생들에게 전수해라.', `MaleText_loc4`='现在，把我的技术传授给新人。', `MaleText_loc5`='快去，把我的技巧傳授給新兵們。', `MaleText_loc7`='Ahora ve a impartir mis técnicas a los iniciados.' WHERE `ID`=64272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅에 샤가 활개를 치도록 한 놈들을 그냥 두지 않겠다.', `MaleText_loc4`='我们不会容忍那些将煞魔释放到我们家园的人们。', `MaleText_loc5`='我們不會容忍將煞釋放到我們的土地之上的人。', `MaleText_loc7`='No toleraremos a aquellos que han liberado al sha en nuestra tierra.' WHERE `ID`=64273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 샤를 몰아냈다. 너희 종족도 우리 앞에 쓰러질 것이다.', `MaleText_loc4`='我们将煞魔击退，同样也会击败你们。', `MaleText_loc5`='我們逼退了煞，你的族類也會在我們面前敗亡。', `MaleText_loc7`='Hemos derrotado al sha, y ustedes caerán ante nosotros también.' WHERE `ID`=64274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 봤던 물고기가 어찌나 컸던지, 상어인 줄 알았었어요... 가만, 생각해 보니 정말 상어였을 수도 있겠네요.', `MaleText_loc4`='有一次，我看见一条非常大的鱼，你发誓它是鲨鱼。现在想起来了……', `MaleText_loc5`='我有一次看到一條超大的魚，大到會讓你發誓那是條鯊魚。想到這個...', `MaleText_loc7`='Una vez vi un pez tan grande como un tiburón. Ahora que lo pienso...' WHERE `ID`=64275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낚시꾼이시라고요? 그렇게 연약한 팔로, 무거운 방어구를 입고 낚시를 할 수 있겠어요?', `MaleText_loc4`='你是渔夫？和他们无力的手臂和沉重的护甲吗？', `MaleText_loc5`='你是個漁夫?就憑那軟趴趴的雙臂和那身重甲?', `MaleText_loc7`='¿Tú, $gpescador:pescadora;? ¿Con esos brazos tan fofos y esa armadura pesada?' WHERE `ID`=64276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 해안에 잘 오셨습니다! 이곳에선 별의별 물건들이 해안에 밀려들지요.', `MaleText_loc4`='欢迎光临潘达利亚海岸！这里一切可能冲刷海岸的东西已经或者将冲刷上海岸。', `MaleText_loc5`='歡迎來到潘達利亞的海岸!在這裡所有能被沖上岸的東西都曾經，或將會，被沖上岸。', `MaleText_loc7`='¡$GBienvenido:Bienvenida; a la costa de Pandaria! Donde todo lo que puede arrastrar la corriente ha sido o será arrastrado por ella.' WHERE `ID`=64277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 미끼를 사용하시나요? 전에 제가 알던 판다렌은 자신의 팔을 미끼로 써서 물고기들을 끌어들이더라고요.$b$b수타면의 달인이라고도 불렸었는데...$b$b소문을 듣자 하니, 이제 은퇴하고 남쪽으로 내려갔다고 하더군요.', `MaleText_loc4`='你用什么样的诱饵？我知道一个熊猫人会使用自己的手掌做饵来钓鱼。$b$b我们叫他搏鱼者。$b$b听说他退休了，境况越来越糟。', `MaleText_loc5`='你用的魚餌是哪一種?我以前認識一個熊貓人，他會用他自己的手臂當魚餌。$b$b我們稱他為『麵王』。據謠傳他已經退休然後到南方去了。', `MaleText_loc7`='¿Qué tipo de cebo utilizas? Una vez conocí a un pandaren que utilizaba su propio brazo para atraer a los peces.$b$bLe llamábamos el Tallarines.$b$bLos rumores dicen que se ha retirado y se ha ido al sur.' WHERE `ID`=64278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라켄을 보신 적 있나요? 아주 오래 전에 진 노인이 크라켄을 낚았었는데, 하도 "구린" 냄새가 나서 놓아버렸다고 하더라고요.$b$b지금도 진 노인이 크라켄을 다시 잡을 수 있을지에 대해 내기가 벌어지고 있습니다.', `MaleText_loc4`='可曾见过海怪？老金称自己从前捕到一条，但又放回去了，因为它“腥味太重”了。$b$b我们打赌，看他是否还能再次捕到。', `MaleText_loc5`='你以前有曾經看過海怪嗎?老金聲稱有一次抓到一隻但把它放走了，因為它看起來太「野性」。$b$b我們有一筆賭注賭他是否有一天能再次找到它。', `MaleText_loc7`='¿Alguna vez has visto un kraken? El viejo Jin dice haber pescado uno hace mucho tiempo, pero lo dejó escapar porque "apestaba."$b$bHemos hecho una porra sobre si lo volverá a encontrar o no.' WHERE `ID`=64279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 당신 고향에서는 어떤 물고기가 잡힙니까?', `MaleText_loc4`='那么，那鱼长什么样，你又从哪里来？', `MaleText_loc5`='所以，你家鄉那邊的魚都是什麼樣子的?', `MaleText_loc7`='Entonces, ¿Cómo son los peces en el sitio del que vienes?' WHERE `ID`=64280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지는 여기 해안이 안개로 덮여 있었습니다만, 무슨 이유에서인지 모두 걷힌 모양이네요.', `MaleText_loc4`='常年笼罩着这片海滩的迷雾散去了，这背后一定有什么原因。', `MaleText_loc5`='通常這些海岸都被迷霧所覆蓋。看起來它們都因為什麼緣故而消散了。', `MaleText_loc7`='Generalmente estas costas están cubiertas de bruma. Parece que se han despejado por alguna razón.' WHERE `ID`=64281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어류식 격투술을 전문적으로 연구했던 수도사님을 한 분 알아요. 전투 시에는 꽤나 "제한적인" 무술이었지만, 끝내주게 맛있는 매운탕을 끓이시던 게 기억나네요.', `FemaleText_loc4`='我认识一名武僧，他擅长使用斗鱼招式。招数虽然相当有限，但是他炖的鱼汤非常好吃。', `FemaleText_loc5`='我以前認識一個專精鬥魚式的武僧。那招式沒什麼用處，但他會做一道超美味的燉魚。', `FemaleText_loc7`='Una vez conocí a un monje que estaba especializado en luchar contra peces. Era algo bastante limitado, pero podía hacer un caldo de pescado increíble.' WHERE `ID`=64282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 처음 오셨나요? 아이들에게 주의를 줄 때와 같은 말씀을 드려야겠네요. 미끼 한 줌과 적당한 출구 전략 없이는 물에 들어가지 마세요.', `FemaleText_loc4`='新来的吗？这就像我们告诉孩子们，没有手握大把的诱饵和撤退策略就不要下水。', `FemaleText_loc5`='新來的嗎?我們都是這麼跟小孩子說，沒有一把轉移注意力的誘餌和逃脫戰略的話，就不要下水。', `FemaleText_loc7`='¿Eres $gnuevo:nueva; aquí? Como les decimos a los niños, no te metas en el agua sin un buen cebo como distracción y una buena estrategia de huida.' WHERE `ID`=64283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전에 한 아이가 방방 뛰면서 상어와 문어의 잡종을 봤다고 얘기하더군요.$b$b바다에는 온갖 이상한 생물이 산다는 걸 알지만, 음... 그런 놈은 좀 우스꽝스러울 것 같아요.', `FemaleText_loc4`='有个孩子发誓，有一天，他看到了在鲨鱼和章鱼之间的一个十字形物。$b$b我知道海洋中有很多奇怪的事情，但在我看来，都很无聊。', `FemaleText_loc5`='有個小孩信誓旦旦的說他有天看到一隻又像鯊魚又像章魚的怪物。$b$b我知道海裡有許多奇奇怪怪的東西，但對我來說那聽起來特別愚蠢。', `FemaleText_loc7`='Uno de los niños jura y perjura que el otro día vieron un animal que era un cruce entre tiburón y pulpo.$b$bSé que en el mar hay un montón de cosas extrañas, pero esto ya me parece demasiado.' WHERE `ID`=64284;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해안에 추락한 비행선에 대해 알고 계세요? 혹시 당신 일행은 아닌가요?$b$b이곳의 안개가 그런 "선물"들을 가져다 주는 일이 종종 있어요.', `FemaleText_loc4`='你可能已经看到船撞上我们的海岸。你的船也有过那样的遭遇吗？$b$b迷雾常常给我们带来那样的“礼物”。', `FemaleText_loc5`='你也許看過船隻在我們的岸邊撞毀。裡面有剛好某一艘是你的嗎?$b$b迷霧經常為我們帶來一些那樣的「禮物」。', `FemaleText_loc7`='Es probable que ya hayas visto los barcos naufragados en nuestras costas. ¿Alguno de ellos era tuyo?$b$bLa niebla nos suele traer "regalos" como ese.' WHERE `ID`=64285;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡 기수들이 당신을 보냈나요? 그 운룡들이 우리가 잡은 물고기들을 자꾸 훔쳐간다고요.', `FemaleText_loc4`='是翔龙骑士派你来的吗？他们的翔龙不断偷取我们最好的渔获物。', `FemaleText_loc5`='是蛟龍騎士派你來的嗎?他們的蛟龍一直把我們釣到的大魚偷走。', `FemaleText_loc7`='¿Te envían los Jinetes de Dragones? Sus dragones no dejan de robarnos las mejores capturas.' WHERE `ID`=64286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 오랫동안 낚시를 하다 보면, 별의별 걸 다 볼 수 있어요. 전에 한번은 팔다리가 달린 물범도 봤다니까요. 게다가 말까지 하더라고요!', `FemaleText_loc4`='在这里捕鱼的时间长了，就见怪不怪了。我看到过长了胳膊和腿的海象。而且，那海象还会说话！', `FemaleText_loc5`='只要在這裡釣魚夠久，你就能看到各種事物。我有一次看到長著腿和手臂的海象。不僅如此，它還會說話!', `FemaleText_loc7`='Aquí verás de todo si pasas el suficiente tiempo pescando. Una vez vi una morsa con pies y manos. Y para más inri, ¡sabía hablar!' WHERE `ID`=64287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 고향의 바다는 어떤 모습인가요?', `FemaleText_loc4`='你们那的大海是什么样的？', `FemaleText_loc5`='你家鄉那邊的海洋是什麼樣子的?', `FemaleText_loc7`='¿Cómo es el mar en el sitio del que vienes?' WHERE `ID`=64288;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 여기 진위들을 대하기가 영 불편해요. 하지만 낚시하는 법도 알고, 그것도 우리보다 훨씬 잘 하니, 제가 뭐라고 할 수는 없죠.', `FemaleText_loc4`='我总对这里的锦鱼人感到奇怪。但他们知道如何捕鱼，而且技术比我们更高，所以我有什么资格去评判呢。', `FemaleText_loc5`='我經常對這裡的錦魚人感到疑惑。但他們比我們其餘的人還更懂得捕魚，所以我有什麼資格能評斷他們。', `FemaleText_loc7`='Algunas veces me pregunto cómo les irá a los jinyu de por aquí. Pero ellos saben pescar mejor aún que nosotros, así que ¿quién soy yo para juzgar?' WHERE `ID`=64289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님은 제가 제일 좋아하는 선생님이에요!', `MaleText_loc4`='你是我最好的老师！', `MaleText_loc5`='你是我最喜歡的老師了!', `MaleText_loc7`='¡Eres mi profesor favorito!', `FemaleText_loc1`='선생님은 제가 제일 좋아하는 선생님이에요!', `FemaleText_loc4`='你是我最好的老师！', `FemaleText_loc5`='你是我最喜歡的老師了!', `FemaleText_loc7`='¡Eres mi profesor favorito!' WHERE `ID`=64290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 자라서 판다리아 최고의 주방장이 될 거예요.', `MaleText_loc4`='等我长大了，我要成为潘达利亚最棒的大厨。', `MaleText_loc5`='等我長大，我要當潘達利亞最好的廚師。', `MaleText_loc7`='Cuando sea mayor, quiero ser el mejor cocinero de Pandaria.', `FemaleText_loc1`='저는 자라서 판다리아 최고의 주방장이 될 거예요.', `FemaleText_loc4`='等我长大了，我要成为潘达利亚最棒的大厨。', `FemaleText_loc5`='等我長大，我要當潘達利亞最好的廚師。', `FemaleText_loc7`='Cuando sea mayor, quiero ser la mejor cocinera de Pandaria.' WHERE `ID`=64291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야! 이거 정말 신나는데요! 진짜 보물 사냥을 하다니!', `FemaleText_loc4`='噢，这太令人兴奋了！现实版的寻宝！', `FemaleText_loc5`='喔喔，這真是刺激!一場真實的尋寶歷險!', `FemaleText_loc7`='¡Oooh, es emocionante! ¡Una auténtica caza del tesoro!' WHERE `ID`=64292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저, 나중에 훌륭한 요리사가 될 수 있을까요?', `MaleText_loc4`='你觉得我会成为一名好厨师吗？', `MaleText_loc5`='你覺得我會變成一個好廚師嗎?', `MaleText_loc7`='¿Crees que algún día seré un buen cocinero?', `FemaleText_loc1`='저, 나중에 훌륭한 요리사가 될 수 있을까요?', `FemaleText_loc4`='你觉得我会成为一名好厨师吗？', `FemaleText_loc5`='你覺得我會變成一個好廚師嗎?', `FemaleText_loc7`='¿Crees que algún día seré un buen cocinero?' WHERE `ID`=64293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에는 뭘 배우나요?', `MaleText_loc4`='我们接下来要学什么？', `MaleText_loc5`='我們接下來要學什麼?', `MaleText_loc7`='¿Qué me toca aprender ahora?', `FemaleText_loc1`='다음에는 뭘 배우나요?', `FemaleText_loc4`='我们接下来要学什么？', `FemaleText_loc5`='我們接下來要學什麼?', `FemaleText_loc7`='¿Qué me toca aprender ahora?' WHERE `ID`=64294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 제자가 되기 위해 노력할게요.', `MaleText_loc4`='我会尽力当个好学生。', `MaleText_loc5`='我會盡力當一個好學生。', `MaleText_loc7`='Intentaré ser un buen estudiante.', `FemaleText_loc1`='좋은 제자가 되기 위해 노력할게요.', `FemaleText_loc4`='我会尽力当个好学生。', `FemaleText_loc5`='我會盡力當一個好學生。', `FemaleText_loc7`='Intentaré ser un buen estudiante.' WHERE `ID`=64295;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저거 진짜 무서워 보이네요! $n 님! 덕분에 살았어요!', `FemaleText_loc4`='那件事看上去太可怕了！你救了我们的命，$n！', `FemaleText_loc5`='那玩意看起來實在有夠可怕!你救了我們所有人的性命，$n!', `FemaleText_loc7`='¡Esa cosa da bastante miedo! ¡Nos has salvado la vida, $n!' WHERE `ID`=64296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문 - 옵션 1 - 시험 - HW', `MaleText_loc4`='小道消息——选项1——测试——HW', `MaleText_loc5`='Gossip - Option 1 - Test - HW', `MaleText_loc7`='Gossip - Option 1 - Test - HW', `FemaleText_loc1`='소문 - 옵션 1 - 시험 - HW', `FemaleText_loc4`='小道消息——选项1——测试——HW', `FemaleText_loc5`='Gossip - Option 1 - Test - HW', `FemaleText_loc7`='Gossip - Option 1 - Test - HW' WHERE `ID`=64297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문 - 옵션 2 - 시험 - HW', `MaleText_loc4`='小道消息——选项2——测试——HW', `MaleText_loc5`='Gossip - Option 2 - Test - HW', `MaleText_loc7`='Gossip - Option 2 - Test - HW', `FemaleText_loc1`='소문 - 옵션 2 - 시험 - HW', `FemaleText_loc4`='小道消息——选项2——测试——HW', `FemaleText_loc5`='Gossip - Option 2 - Test - HW', `FemaleText_loc7`='Gossip - Option 2 - Test - HW' WHERE `ID`=64298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시... 이제 얘기할 마음이 나?', `FemaleText_loc4`='那么……想谈谈这个事儿吗？', `FemaleText_loc5`='所以...想要談談嗎?', `FemaleText_loc7`='Entonces... ¿Quieres hablar de ello?' WHERE `ID`=64299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니.', `MaleText_loc4`='不想了。', `MaleText_loc5`='沒有。', `MaleText_loc7`='Nop.' WHERE `ID`=64300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말? 누구나 한 번쯤 겪는 일이라던데.', `FemaleText_loc4`='你确定？我听说每个人都或多或少碰到过这样的事。', `FemaleText_loc5`='你確定?我聽說在某個階段這在每個人身上都曾發生過。', `FemaleText_loc7`='¿Seguro? He oído que a todo el mundo le pasa alguna vez.' WHERE `ID`=64301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수습생이 그렇지.', `MaleText_loc4`='完全是新手。', `MaleText_loc5`='死不足惜的新兵。', `MaleText_loc7`='Principiantes.' WHERE `ID`=64302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련이 부족했던 모양이군.', `MaleText_loc4`='他们应该用功一点。', `MaleText_loc5`='他們早該更加努力練功。', `MaleText_loc7`='Deberían haber estudiado más.' WHERE `ID`=64303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 하나만으로는 부족하지.', `MaleText_loc4`='一招半式不解决问题。', `MaleText_loc5`='只會一招半式是不夠的。', `MaleText_loc7`='Una sola técnica no basta.' WHERE `ID`=64304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 낙제로군. 너희는 어떨까?', `MaleText_loc4`='他们没通过测试，你呢？', `MaleText_loc5`='他們無法通過考驗。你可以嗎?', `MaleText_loc7`='Ellos no pasaron la prueba. ¿Lo harás tú?' WHERE `ID`=64305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다고? 좋군. 내 무술 실력을 확인할 제자들이 있었으면 더 좋았겠지만...', `MaleText_loc4`='他们来了？很好。要是我的学生们能在这旁观，从我即将展示的高超武艺中学上几招就好了……', `MaleText_loc5`='他們來了?很好。要是我的學生能在這裡，從我即將展示的高超武藝中學上幾招就好了...', `MaleText_loc7`='¿Se acercan? Bien. Ojalá estuvieran aquí mis estudiantes para aprender del espectáculo marcial que estamos a punto de presenciar...' WHERE `ID`=64306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='살아서 빠져나왔어요! 이야, 제 친구들이 이 이야기를 다 들을 때까지 기다려주세요. 하나도 안 믿겠지만요! 또 만나요, $n 님!', `FemaleText_loc4`='我们成功了！儿子啊儿子，等到我的朋友们全都知晓这件事。他们永远也不会相信它！再见，$n！', `FemaleText_loc5`='我們成功活著逃出來了!喔老天，等到我的朋友們聽說關於這整件事的消息時，他們一定不會相信!下次再會，$n!', `FemaleText_loc7`='¡Hemos logrado sobrevivir! Oh, espera a que mis amigos escuchen esto. ¡No se lo van a creer jamás! ¡Nos vemos luego, $n!' WHERE `ID`=64307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님... 정말... 놀랍군요! 이 기록들은 우리 농부들에게 소중한 지식을 알려줬어요. 늙은 엉겅퀴 노인에게는 이런 기록을 남겨줬으니 정말 큰 빚을 졌고, 또 당신이 이걸 찾아줬으니 당신에게도 빚을 졌네요. 감사합니다!', `FemaleText_loc4`='这真是……太不同寻常了，$n！这些备注为我们的农民提供了宝贵的知识。我们衷心感谢老农阿蓟保存了这些记录，我们也感谢你发现了这些记录。谢谢你！', `FemaleText_loc5`='這...真是太棒了，$n!這些記錄能給我們的農夫提供非常珍貴的知識。寂老頭能保留這些記錄，而你能找回它們，著實讓我們欠了一筆大人情。感謝你!', `FemaleText_loc7`='¡Esto es impresionante, $n! Estas notas proporcionan un conocimiento de gran valor a nuestros granjeros. Estamos en deuda con Cardo el Viejo por conservar estos registros y contigo por recuperarlos. ¡Gracias!' WHERE `ID`=64308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0404|Hspell:116417|h[비전 공명]|h|r으로 채워집니다!', `MaleText_loc4`='你受到|cFFFF0404|Hspell:116417|h[奥术回响]|h|r的影响！', `MaleText_loc5`='你受到了|cFFFF0404|Hspell:116417|h[秘法共鳴]|h|r的效果!', `MaleText_loc7`='¡Estás bajo los efectos de |cFFFF0404|Hspell:116417|h[Resonancia arcana]|h|r!', `FemaleText_loc1`='당신은 |cFFFF4809|Hspell:116417|h[비전 공명]|h|r으로 채워집니다!', `FemaleText_loc4`='你受到|cFFFF4809|Hspell:116417|h[奥术回响]|h|r的影响！', `FemaleText_loc5`='你受到了|cFFFF4809|Hspell:116417|h[秘法共鳴]|h|r的效果!', `FemaleText_loc7`='¡Estás bajo los efectos de |cFFFF4809|Hspell:116417|h[Resonancia arcana]|h|r!' WHERE `ID`=64309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개돌이호 2세는 여기 바로 남동쪽에 있는 부두에 있네. 어서 가세나!', `MaleText_loc4`='雾海飞跃者二世在东南方向的码头。出发！', `MaleText_loc5`='躍霧者二世停在東南方離這不遠的碼頭裡。走吧!', `MaleText_loc7`='El Saltanieblas Jr. está en el muelle al sureste de aquí. ¡Vamos!' WHERE `ID`=64310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작살포를 작동시키게!', `MaleText_loc4`='鱼叉炮准备！', `MaleText_loc5`='去操縱那門魚叉砲!', `MaleText_loc7`='¡Encárgate del cañón de arpones!' WHERE `ID`=64311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뱃머리와 좌현, 그리고 우현 부력 주머니와 선미를 노리게...', `MaleText_loc4`='瞄准前部、左侧、右侧浮力囊，以及后部……', `MaleText_loc5`='瞄準船首，左舷和右舷的浮力袋，還有船尾...', `MaleText_loc7`='Apunta a la proa, las bolsas de flotación de babor y estribor, y la popa...' WHERE `ID`=64312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 미안하네... 다시 말해주지.', `MaleText_loc4`='呃，对不起……让我换一种说法。', `MaleText_loc5`='喔，抱歉...讓我換一個說法。', `MaleText_loc7`='Eeh, perdón... Lo diré de otra forma.' WHERE `ID`=64313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴을 겨냥하게! 그리고 측면! 또 엉덩이 쪽! 약간 부드러운 데 말이네.', `MaleText_loc4`='先来个迎面痛击！接着打两侧！然后打尾巴！你知道的，这些是软肋。', `MaleText_loc5`='砲擊它的臉!還有兩側!還有它的尾椎!你知道的，就是屁股啦。', `MaleText_loc7`='¡Dispárale a la cara! ¡Y a los costados! ¡Y a la retaguardia! Ya sabes, a las partes blandas.' WHERE `ID`=64314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백발백중이군!', `MaleText_loc4`='漂亮的射击！', `MaleText_loc5`='精準的砲擊!', `MaleText_loc7`='¡Buen disparo!' WHERE `ID`=64315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 어떠냐, 이 늙은 오징어야?!', `MaleText_loc4`='哈哈！老鱿鱼，你觉得怎么样？！', `MaleText_loc5`='哈哈!你覺得如何呀，你這老烏賊?!', `MaleText_loc7`='¡Ja, ja! ¡¿Qué te parece eso, calamar?!' WHERE `ID`=64316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마쭈 님이시여, 제 손을 인도하소서...', `MaleText_loc4`='玛祖，指引我出击……', `MaleText_loc5`='瑪祖，指引我的手臂...', `MaleText_loc7`='Mazu, guía mi brazo...' WHERE `ID`=64317;
