UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지! 다시 물 밑으로 기어들어가라고!', `MaleText_loc4`='对极了！滚回深渊中去吧！', `MaleText_loc5`='就是這樣!滾回海底去吧!', `MaleText_loc7`='¡Eso es! ¡Vuelve a las profundidades!' WHERE `ID`=64320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딘가 새는 것 같은데!', `MaleText_loc4`='它好像被打漏了！', `MaleText_loc5`='看來他打出了一條裂縫!', `MaleText_loc7`='¡Parece que tiene una fuga!' WHERE `ID`=64321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런게 바로 일류 작살 사냥법이지!', `MaleText_loc4`='那简直是一流的叉鱼技术！', `MaleText_loc5`='那真是高超的魚叉操作技巧!', `MaleText_loc7`='¡Eres un hacha con el arpón!' WHERE `ID`=64322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 손님인가? 거 참!', `MaleText_loc4`='还有更多访客吗？呸！', `MaleText_loc5`='更多來訪者?哼!', `MaleText_loc7`='¿Más visitantes? ¡Bah!' WHERE `ID`=64323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 어떻게 여기까지 왔는진 모르겠지만... 행운은 항상 마음이 열린 이에게 찾아온다고 해요.', `MaleText_loc4`='不知道我是怎么来到这的。但是……好运常常降临开明的人。', `MaleText_loc5`='我不確定我是怎麼跑到這來的。但是...好運通常會找上心胸開闊的人。', `MaleText_loc7`='No tengo muy claro de cómo he llegado aquí, pero... La buena suerte suele aliarse con aquellos que tienen la mente abierta.' WHERE `ID`=64324;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치유의 중요성을 절대 얕보지 마세요.', `FemaleText_loc4`='永远不要低估治疗的重要性。', `FemaleText_loc5`='絕對不要低估治療的重要性。', `FemaleText_loc7`='Nunca subestimes la importancia de la sanación.' WHERE `ID`=64325;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='치유가 전투의 흐름을 돌려 놓는 일이 많아요.', `FemaleText_loc4`='治疗可以扭转战局。', `FemaleText_loc5`='治療扭轉過許多戰役的頹勢。', `FemaleText_loc7`='La sanación ha hecho variar el curso de más de una guerra.' WHERE `ID`=64326;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='썬더포우 은거처에 잘 오셨습니다. 이곳에서는 기를 집중하여 치유하는 법을 배우지요.', `FemaleText_loc4`='欢迎光临雷掌阁。在这里，我们将我们的技艺重点放在将我们的真气融入治疗中。', `FemaleText_loc5`='歡迎來到雷爪靜修居。我們在這裡練習將我們的真氣集中在治療之上的技巧。', `FemaleText_loc7`='$GBienvenido:Bienvenida; al Refugio Zarpa Atronadora. Aquí practicamos el concentrar nuestro chi en la sanación.' WHERE `ID`=64327;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삶 속에서 당신이 배워야 할 단 한 가지가 있다면, 바로 언제나 배워야 할 것이 있다는 점일 거예요.', `FemaleText_loc4`='如果你开始学习一样东西，你会发现还有很多要学。', `FemaleText_loc5`='如果生命中有一件事是你能學習的，那就是學無止境。', `FemaleText_loc7`='Si hay algo que puedes aprender de la vida, es que siempre hay cosas que aprender.' WHERE `ID`=64328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더포우 은거처에 잘 왔네. 방어구를 보고 오해하지는 말게. 여기는 치유 기술을 훈련하는 곳이라네.', `MaleText_loc4`='欢迎来到雷掌阁。别被盔甲蒙骗了。我们这是进行治疗训练的。', `MaleText_loc5`='歡迎來到雷爪靜修居。不要讓護甲欺騙了你。我們這裡訓練的是治療練習。', `MaleText_loc7`='$GBienvenido:Bienvenida; al Refugio Zarpa Atronadora. Que la armadura no te confunda: aquí practicamos ejercicios de sanación.', `FemaleText_loc1`='썬더포우 은거처에 잘 오셨습니다. 방어구를 보고 오해하지는 마십시오. 여기는 치유 기술을 훈련하는 곳입니다.', `FemaleText_loc4`='欢迎来到雷掌阁。别被盔甲蒙骗了。我们这是进行治疗训练的。', `FemaleText_loc5`='歡迎來到雷爪靜修居。不要讓護甲欺騙了你。我們這裡訓練的是治療練習。', `FemaleText_loc7`='$GBienvenido:Bienvenida; al Refugio Zarpa Atronadora. Que la armadura no te confunda: aquí practicamos ejercicios de sanación.' WHERE `ID`=64329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부근은 매우 조용한 편이네. 가끔씩 찾아오는 사우록 사냥꾼들을 제외하면 별로 문제가 없어. 그리고 사우록은 폭풍우가 칠 때만 나타난다네.', `MaleText_loc4`='这里平时相当平静。只有蜥蜴人狩猎小队会偶尔来给我们添些麻烦。而且蜥蜴人一般只在狂风暴雨来袭时才会出现。', `MaleText_loc5`='這裡通常相當平靜。我們唯一的問題就是偶爾會出現的薩烏洛克劫獵隊伍。而且薩烏洛克似乎只會在猛烈風暴時出現。', `MaleText_loc7`='Aquí las cosas suelen estar en calma. Solo tenemos problemas con las partidas de caza de saurok. Y los saurok solo salen cuando hay una tormenta fuerte.', `FemaleText_loc1`='이 부근은 매우 조용한 편입니다. 가끔씩 찾아오는 사우록 사냥꾼들을 제외하면 별로 문제가 없어요. 그리고 사우록은 폭풍우가 칠 때만 나타나지요.', `FemaleText_loc4`='这里平时相当平静。只有蜥蜴人狩猎小队会偶尔来给我们添些麻烦。而且蜥蜴人一般只在狂风暴雨来袭时才会出现。', `FemaleText_loc5`='這裡通常相當平靜。我們唯一的問題就是偶爾會出現的薩烏洛克劫獵隊伍。而且薩烏洛克似乎只會在猛烈風暴時出現。', `FemaleText_loc7`='Aquí las cosas suelen estar en calma. Solo tenemos problemas con las partidas de caza de saurok. Y los saurok solo salen cuando hay una tormenta fuerte.' WHERE `ID`=64330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사 블랜치는 만나 봤나? 이곳 남쪽과 동쪽에 있는 길을 돌아다니고 있을 걸세. 가끔씩 정말 놀라운 맛의 맥주를 가지고 여길 찾아오곤 하지.', `MaleText_loc4`='你见到酒仙布兰彻了吗？她经常在南边和东边的路上徘徊，总会带上口感绝妙的佳酿来造访我们，在这里家喻户晓。', `MaleText_loc5`='你有見過釀酒大師白蘭琪嗎?她遊蕩在這裡南邊和東邊的道路上。為人所知的是她會帶著一些她較令人驚奇的酒來拜訪我們。', `MaleText_loc7`='¿Has conocido ya a la maestra cervecera Clara? Vaga por los caminos que hay al sur y al este de aquí. Se la conoce porque ya ha venido alguna vez con alguna de sus increíbles creaciones.', `FemaleText_loc1`='양조사 블랜치는 만나 보셨습니까? 이곳 남쪽과 동쪽에 있는 길을 돌아다니고 있을 겁니다. 가끔씩 정말 놀라운 맛의 맥주를 가지고 여길 찾아오곤 하지요.', `FemaleText_loc4`='你见到酒仙布兰彻了吗？她经常在南边和东边的路上徘徊，总会带上口感绝妙的佳酿来造访我们，在这里家喻户晓。', `FemaleText_loc5`='你有見過釀酒大師白蘭琪嗎?她遊蕩在這裡南邊和東邊的道路上。為人所知的是她會帶著一些她較令人驚奇的酒來拜訪我們。', `FemaleText_loc7`='¿Has conocido ya a la maestra cervecera Clara? Vaga por los caminos que hay al sur y al este de aquí. Se la conoce porque ya ha venido alguna vez con alguna de sus increíbles creaciones.' WHERE `ID`=64331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 치유하는 법을 배우고 있습니다. 한 가지 문제는, 치유를 하려면 먼저 다쳐야 한다는 겁니다.', `MaleText_loc4`='我在努力学习如何治疗。问题在于，你得先受伤，才能被治疗。', `MaleText_loc5`='我正試著學習如何治療。問題是在你被治療之前你得先受傷。', `MaleText_loc7`='Estoy aprendiendo a realizar sanaciones. El problema es que tienes que hacerte daño antes de sanarte.', `FemaleText_loc1`='전 치유하는 법을 배우고 있습니다. 한 가지 문제는, 치유를 하려면 먼저 다쳐야 한다는 겁니다.', `FemaleText_loc4`='我在努力学习如何治疗。问题在于，你得先受伤，才能被治疗。', `FemaleText_loc5`='我正試著學習如何治療。問題是在你被治療之前你得先受傷。', `FemaleText_loc7`='Estoy aprendiendo a realizar sanaciones. El problema es que tienes que hacerte daño antes de sanarte.' WHERE `ID`=64332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 어떤 사람이 말하길, 제가 "치유를 너무 많이" 한다고 하더군요. 너무 혼란스럽습니다.', `MaleText_loc4`='前几天，有人说我“过量治疗”了。真让人困惑。', `MaleText_loc5`='有天某人說我「治療過剩」。都把我搞糊塗了。', `MaleText_loc7`='El otro día, alguien me dijo que estaba "sobresanándome". Ya no sé qué hacer.', `FemaleText_loc1`='전에 어떤 사람이 말하길, 제가 "치유를 너무 많이" 한다고 하더군요. 너무 혼란스럽습니다.', `FemaleText_loc4`='前几天，有人说我“过量治疗”了。真让人困惑。', `FemaleText_loc5`='有天某人說我「治療過剩」。都把我搞糊塗了。', `FemaleText_loc7`='El otro día, alguien me dijo que estaba "sobresanándome". Ya no sé qué hacer.' WHERE `ID`=64333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 다른 사람의 고통을 몰아내는 법을 배우고 있습니다. 정말 멋진 일 아닌가요?', `MaleText_loc4`='我在学习如何帮别人消除痛苦。很厉害吧？', `MaleText_loc5`='我正在學習如何把痛楚從某人身上打掉。很棒不是嗎?', `MaleText_loc7`='Estoy aprendiendo a quitar el dolor a la gente. ¿Qué te parece?', `FemaleText_loc1`='저는 다른 사람의 고통을 몰아내는 법을 배우고 있습니다. 정말 멋진 일 아닌가요?', `FemaleText_loc4`='我在学习如何帮别人消除痛苦。很厉害吧？', `FemaleText_loc5`='我正在學習如何把痛楚從某人身上打掉。很棒不是嗎?', `FemaleText_loc7`='Estoy aprendiendo a quitar el dolor a la gente. ¿Qué te parece?' WHERE `ID`=64334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 말할 수 없습니다. 집중을... 해야 해요.', `MaleText_loc4`='现在不能说话。必须……集中精神。', `MaleText_loc5`='現在不能說話。必須...專心。', `MaleText_loc7`='Ahora no puedo hablar. Tengo... que... concentrarme.', `FemaleText_loc1`='지금은 말할 수 없습니다. 집중을... 해야 해요.', `FemaleText_loc4`='现在不能说话。必须……集中精神。', `FemaleText_loc5`='現在不能說話。必須...專心。', `FemaleText_loc7`='Ahora no puedo hablar. Tengo... que... concentrarme.' WHERE `ID`=64335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차를 우려내는 데도 그렇게 여러 가지 방법이 있는 줄은 전혀 몰랐습니다.', `MaleText_loc4`='我从来不知道，泡茶有多少讲究。', `MaleText_loc5`='我從來不知道泡茶有這麼多花樣。', `MaleText_loc7`='Jamás imaginé que hubiese tal cantidad de modos de hacer té.', `FemaleText_loc1`='차를 우려내는 데도 그렇게 여러 가지 방법이 있는 줄은 전혀 몰랐습니다.', `FemaleText_loc4`='我从来不知道，泡茶有多少讲究。', `FemaleText_loc5`='我從來不知道泡茶有這麼多花樣。', `FemaleText_loc7`='Jamás imaginé que hubiese tal cantidad de modos de hacer té.' WHERE `ID`=64336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨을... 숨을 잘 못 쉬겠어요. 덕분에 목숨을 건졌네요.', `MaleText_loc4`='我……都快透不过气了。多亏你救了我。', `MaleText_loc5`='我...我快不能呼吸了。我還活著都得謝謝你。', `MaleText_loc7`='Apenas... apenas puedo respirar. Estoy vivo gracias a ti.', `FemaleText_loc1`='숨을... 숨을 잘 못 쉬겠어요. 덕분에 목숨을 건졌네요.', `FemaleText_loc4`='我……都快透不过气了。多亏你救了我。', `FemaleText_loc5`='我...我快不能呼吸了。我還活著都得謝謝你。', `FemaleText_loc7`='Apenas... apenas puedo respirar. Estoy viva gracias a ti.' WHERE `ID`=64337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 양돌이... 그렇게 끝없이 방황하더니 결국 목숨을 잃었습니다.', `MaleText_loc4`='可怜的小羊……到处乱走终于害了他。', `MaleText_loc5`='可憐的羊羊...他靜不下來地遊蕩終於使他丟了性命。', `MaleText_loc7`='Pobre ovejita... su errar incansable la llevó a su fin.' WHERE `ID`=64338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 갑자기 덮쳤어요. 경비병들도 손을 쓸 수 없는 상황이었어요.', `MaleText_loc4`='他们的到来毫无征兆。令守卫束手无策。', `MaleText_loc5`='他們來得一點警告都沒有。守衛們根本無能為力。', `MaleText_loc7`='Llegaron sin avisar. Los guardias no pudieron hacer nada.', `FemaleText_loc1`='적이 갑자기 덮쳤어요. 경비병들도 손을 쓸 수 없는 상황이었어요.', `FemaleText_loc4`='他们的到来毫无征兆。令守卫束手无策。', `FemaleText_loc5`='他們來得一點警告都沒有。守衛們根本無能為力。', `FemaleText_loc7`='Llegaron sin avisar. Los guardias no pudieron hacer nada.' WHERE `ID`=64339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 아름다운 곳에 살아도 위험은 있군요...', `MaleText_loc4`='看来住在太过美丽的地方是有风险的……', `MaleText_loc5`='看來住在這麼美麗的地方也是會有些危險的...', `MaleText_loc7`='Parece que vivir en un lugar tan bonito tiene sus riesgos...', `FemaleText_loc1`='이렇게 아름다운 곳에 살아도 위험은 있군요...', `FemaleText_loc4`='看来住在太过美丽的地方是有风险的……', `FemaleText_loc5`='看來住在這麼美麗的地方也是會有些危險的...', `FemaleText_loc7`='Parece que vivir en un lugar tan bonito tiene sus riesgos...' WHERE `ID`=64340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 따위에게 겁먹고 도망치진 않을 거예요. 여기가 이제 우리 고향인걸요.', `MaleText_loc4`='这些魔古族吓不走我们。现在这里是我们的家了。', `MaleText_loc5`='這些魔古無法嚇跑我們。現在這裡是我們的家了。', `MaleText_loc7`='Estos mogu no nos van a ahuyentar. Ahora este es nuestro hogar.', `FemaleText_loc1`='모구 따위에게 겁먹고 도망치진 않을 거예요. 여기가 이제 우리 고향인걸요.', `FemaleText_loc4`='这些魔古族吓不走我们。现在这里是我们的家了。', `FemaleText_loc5`='這些魔古無法嚇跑我們。現在這裡是我們的家了。', `FemaleText_loc7`='Estos mogu no nos van a ahuyentar. Ahora este es nuestro hogar.' WHERE `ID`=64341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 살아남은 건 모두 당신 덕분이에요... 잊지 않을게요.', `MaleText_loc4`='多亏有你，我才活了下来……我不会忘记你的恩德。', `MaleText_loc5`='我還活著都得感謝你...我不會忘記這份恩情。', `MaleText_loc7`='Si estoy vivo es gracias a ti... no lo olvidaré.', `FemaleText_loc1`='제가 살아남은 건 모두 당신 덕분이에요... 잊지 않을게요.', `FemaleText_loc4`='多亏有你，我才活了下来……我不会忘记你的恩德。', `FemaleText_loc5`='我還活著都得感謝你...我不會忘記這份恩情。', `FemaleText_loc7`='Si estoy viva es gracias a ti... no lo olvidaré.' WHERE `ID`=64342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이군요! 바로 며칠 전에 내 동생을 구한 사람이요! 당신은 정말 영웅이에요!', `MaleText_loc4`='我认识你！你在不到一个星期前才救过我的兄弟。你是位真正的英雄！', `MaleText_loc5`='我認識你!你在還不到一個星期前救了我兄弟。你是個真正的英雄!', `MaleText_loc7`='¡Yo te conozco! Salvaste a mi hermano hace apenas una semana. ¡Eres $gun auténtico héroe:una auténtica heroína;!', `FemaleText_loc1`='당신이군요! 바로 며칠 전에 내 동생을 구한 사람이요! 당신은 정말 영웅이에요!', `FemaleText_loc4`='我认识你！你在不到一个星期前才救过我的兄弟。你是位真正的英雄！', `FemaleText_loc5`='我認識你!你在還不到一個星期前救了我兄弟。你是個真正的英雄!', `FemaleText_loc7`='¡Yo te conozco! Salvaste a mi hermano hace apenas una semana. ¡Eres $gun auténtico héroe:una auténtica heroína;!' WHERE `ID`=64343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝인 줄만 알았어요... 죽는 줄 알았죠. 고마워요, 이방인.', `MaleText_loc4`='我还以为……我还以为自己死定了。谢谢你，陌生人。', `MaleText_loc5`='我以為就那樣了... 我以為我死定了。謝謝你，陌生人。', `MaleText_loc7`='Creía que... creía que iba a morir. Gracias, $gdesconocido:desconocida;.', `FemaleText_loc1`='끝인 줄만 알았어요... 죽는 줄 알았죠. 고마워요, 이방인.', `FemaleText_loc4`='我还以为……我还以为自己死定了。谢谢你，陌生人。', `FemaleText_loc5`='我以為就那樣了... 我以為我死定了。謝謝你，陌生人。', `FemaleText_loc7`='Creía que... creía que iba a morir. Gracias, $gdesconocido:desconocida;.' WHERE `ID`=64344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만, 뭔가 적군 같은 게 오고 있다!', `MaleText_loc4`='等等！有敌人来了！', `MaleText_loc5`='等等!不知道什麼東西帶著敵意正在接近!', `MaleText_loc7`='¡Espera! ¡Se acerca algo hostil!' WHERE `ID`=64345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에 한 수습생이 제게 장난을 쳤어요. 자기 "치유의 안개" 냄새를 한번 맡아 보라더군요. 아... 그건 치유와 전혀 관계 없는 냄새였어요.', `MaleText_loc4`='有个新来的，前几天跟我开了个玩笑。他说我应该闻得到他身上的“治疗迷雾”。治疗跟迷雾有什么关系啊。', `MaleText_loc5`='有天一個學徒對我惡作劇。他說我該聞聞看他的「治療之霧」。那個霧根本就和治療一點關係都沒有。', `MaleText_loc7`='Uno de los iniciados me gastó una broma el otro día. Dijo que tenía que olfatear sus "brumas sanadoras". No había nada de sanador en esa bruma.', `FemaleText_loc1`='전에 한 수습생이 제게 장난을 쳤어요. 자기 "치유의 안개" 냄새를 한번 맡아 보라더군요. 아... 그건 치유와 전혀 관계 없는 냄새였어요.', `FemaleText_loc4`='有个新来的，前几天跟我开了个玩笑。他说我应该闻得到他身上的“治疗迷雾”。治疗跟迷雾有什么关系啊。', `FemaleText_loc5`='有天一個學徒對我惡作劇。他說我該聞聞看他的「治療之霧」。那個霧根本就和治療一點關係都沒有。', `FemaleText_loc7`='Uno de los iniciados me gastó una broma el otro día. Dijo que tenía que olfatear sus "brumas sanadoras". No había nada de sanador en esa bruma.' WHERE `ID`=64346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들이 몰려오고 있다!', `MaleText_loc4`='出现攻击者！', `MaleText_loc5`='攻擊者接近了!', `MaleText_loc7`='¡Se acercan atacantes!' WHERE `ID`=64347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 목숨을 구했습니다.', `MaleText_loc4`='我欠你一条命。', `MaleText_loc5`='我欠你一命。', `MaleText_loc7`='Te debo la vida.', `FemaleText_loc1`='덕분에 목숨을 구했습니다.', `FemaleText_loc4`='我欠你一条命。', `FemaleText_loc5`='我欠你一命。', `FemaleText_loc7`='Te debo la vida.' WHERE `ID`=64348;
