UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 돕겠습니다. 이제 어디로 갑니까?', `MaleText_loc4`='你赢得了我的帮助。现在去哪儿？', `MaleText_loc5`='你值得我協助。現在去哪?', `MaleText_loc7`='Te has ganado mi ayuda. ¿Adónde vamos?', `FemaleText_loc1`='당신을 돕겠습니다. 이제 어디로 가나요?', `FemaleText_loc4`='你赢得了我的帮助。现在去哪儿？', `FemaleText_loc5`='你值得我協助。現在去哪?', `FemaleText_loc7`='Te has ganado mi ayuda. ¿Adónde vamos?' WHERE `ID`=64350;
