UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 친구여. 함께 싸우겠습니다.', `MaleText_loc4`='谢谢你，朋友。让我与你并肩战斗吧。', `MaleText_loc5`='十分感謝，朋友。讓我與你並肩作戰。', `MaleText_loc7`='Te estoy muy agradecido. Déjame luchar a tu lado.', `FemaleText_loc1`='고맙습니다, 친구여. 함께 싸우겠습니다.', `FemaleText_loc4`='谢谢你，朋友。让我与你并肩战斗吧。', `FemaleText_loc5`='十分感謝，朋友。讓我與你並肩作戰。', `FemaleText_loc7`='Te estoy muy agradecida. Déjame luchar a tu lado.' WHERE `ID`=64353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에 너무 오래 갇혀 있었습니다... 모구에게 그 소감을 알려줘야겠네요...', `MaleText_loc4`='在那笼子里待太久了。我要让这些魔古族知道，我对囚禁感觉如何……', `MaleText_loc5`='在那籠子裡待太久了。我會讓這些魔古體會一下我對遭到囚禁的看法...', `MaleText_loc7`='He pasado demasiado tiempo en esa jaula. Les voy a enseñar a esos mogu lo que pienso de su cautiverio...', `FemaleText_loc1`='우리에 너무 오래 갇혀 있었습니다... 모구에게 그 소감을 알려줘야겠네요...', `FemaleText_loc4`='在那笼子里待太久了。我要让这些魔古族知道，我对囚禁感觉如何……', `FemaleText_loc5`='在那籠子裡待太久了。我會讓這些魔古體會一下我對遭到囚禁的看法...', `FemaleText_loc7`='He pasado demasiado tiempo en esa jaula. Les voy a enseñar a esos mogu lo que pienso de su cautiverio...' WHERE `ID`=64354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늦지 않게 구해 주셔서 감사합니다, 영웅님.', `MaleText_loc4`='感谢你及时出手相救，英雄。', `MaleText_loc5`='謝謝你及時伸出援手，英雄。', `MaleText_loc7`='Gracias por rescatarme a tiempo.', `FemaleText_loc1`='늦지 않게 구해 주셔서 감사합니다, 영웅님.', `FemaleText_loc4`='感谢你及时出手相救，英雄。', `FemaleText_loc5`='謝謝你及時伸出援手，英雄。', `FemaleText_loc7`='Gracias por rescatarme a tiempo.' WHERE `ID`=64355;
