UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 함께하며, 절대 쓰러지지 않는다!', `MaleText_loc4`='我们联合起来。我们永远不会倒下！', `MaleText_loc5`='我們團結一心。我們永不言敗!', `MaleText_loc7`='Lucharemos juntos. ¡No caeremos nunca!', `FemaleText_loc1`='우리는 함께하며, 절대 쓰러지지 않는다!', `FemaleText_loc4`='我们联合起来。我们永远不会倒下！', `FemaleText_loc5`='我們團結一心。我們永不言敗!', `FemaleText_loc7`='Lucharemos juntos. ¡No caeremos nunca!' WHERE `ID`=64361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 연꽃은 절대로 무릎꿇지 않는다.', `MaleText_loc4`='金莲教永远不会屈服。', `MaleText_loc5`='金蓮會永不屈服。', `MaleText_loc7`='El Loto Dorado no se rendirá jamás.', `FemaleText_loc1`='황금 연꽃은 절대로 무릎꿇지 않는다.', `FemaleText_loc4`='金莲教永远不会屈服。', `FemaleText_loc5`='金蓮會永不屈服。', `FemaleText_loc7`='El Loto Dorado no se rendirá jamás.' WHERE `ID`=64362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 골짜기를 모구에게 내어 주지 않겠다!', `MaleText_loc4`='锦绣谷永远不会陷入魔古族手中！', `MaleText_loc5`='這片山谷絕不會落入魔古的手中!', `MaleText_loc7`='¡El Valle nunca caerá en manos de los mogu!', `FemaleText_loc1`='무슨 일이 있어도 골짜기를 모구에게 내어 주지 않겠다!', `FemaleText_loc4`='锦绣谷永远不会陷入魔古族手中！', `FemaleText_loc5`='這片山谷絕不會落入魔古的手中!', `FemaleText_loc7`='¡El Valle nunca caerá en manos de los mogu!' WHERE `ID`=64363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤오티엔은 죽음으로 뛰어드는 것이다!', `MaleText_loc4`='韶天赴死！', `MaleText_loc5`='嘯天前來自尋死路!', `MaleText_loc7`='¡Los Shao-Tien marchan hacia sus propias muertes!', `FemaleText_loc1`='샤오티엔은 죽음으로 뛰어드는 것이다!', `FemaleText_loc4`='韶天赴死！', `FemaleText_loc5`='嘯天前來自尋死路!', `FemaleText_loc7`='¡Los Shao-Tien marchan hacia sus propias muertes!' WHERE `ID`=64364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복하지 않으면 죽이겠다!', `MaleText_loc4`='屈服还是倒下！', `MaleText_loc5`='不屈服就得死!', `MaleText_loc7`='¡Ríndete o muere!', `FemaleText_loc1`='항복하지 않으면 죽이겠다!', `FemaleText_loc4`='屈服还是倒下！', `FemaleText_loc5`='不屈服就得死!', `FemaleText_loc7`='¡Ríndete o muere!' WHERE `ID`=64365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 태세가 잘못됐네. 디딤발은 균형이 흐트러졌고, 머리도 아직 너무 무르군.$b$b배울 준비가 되었다는 생각이 들면 다시 돌아오게.', `MaleText_loc4`='你的姿势错了。你完全站不稳脚跟。你的头脑太笨。$b$b当你已经学到准备去学的东西时，请返回这里。', `MaleText_loc5`='你的姿勢錯誤。你腳站立的方式根本不平衡，你的頭放的太軟了。$b$b等你感覺自己準備好學習時再回到這裡來。', `MaleText_loc7`='Tu posición es errónea. Tu paso está desequilibrado. Tu cabeza es muy blanda.$b$bVuelve cuando hayas aprendido que ya puedes aprender.' WHERE `ID`=64366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 샤오티엔의 힘 아래 불탈 것이다!', `MaleText_loc4`='你会被韶天族的威力所烧焦！', `MaleText_loc5`='你會死在嘯天的力量之下!', `MaleText_loc7`='¡Arderéis bajo el poder de los Shao-Tien!', `FemaleText_loc1`='너희는 샤오티엔의 힘 아래 불탈 것이다!', `FemaleText_loc4`='你会被韶天族的威力所烧焦！', `FemaleText_loc5`='你會死在嘯天的力量之下!', `FemaleText_loc7`='¡Arderéis bajo el poder de los Shao-Tien!' WHERE `ID`=64367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 피투성이 시체로 골짜기를 뒤덮을 것이다!', `MaleText_loc4`='我们将取你的血来祭奠这个山谷！', `MaleText_loc5`='你們染血的屍體將會填滿整個山谷!', `MaleText_loc7`='¡Cubriremos el Valle con sus cuerpos ensangrentados!', `FemaleText_loc1`='너희의 피투성이 시체로 골짜기를 뒤덮을 것이다!', `FemaleText_loc4`='我们将取你的血来祭奠这个山谷！', `FemaleText_loc5`='你們染血的屍體將會填滿整個山谷!', `FemaleText_loc7`='¡Cubriremos el Valle con sus cuerpos ensangrentados!' WHERE `ID`=64368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 눈은 바로 앞에 있는 것도 보지 못하는군. 분명히 잘못된 식습관 때문일 거야.', `MaleText_loc4`='你的眼睛已经看不见面前的事物。毫无疑问，这是你平时不良的饮食习惯所造成的。', `MaleText_loc5`='你的眼睛看不見面前的東西。無疑地這是你不良的飲食習慣所造成的結果。', `MaleText_loc7`='Tus ojos no te permiten ver lo que tienes ante ti. Sin duda es el resultado de unos hábitos alimenticios poco sanos.' WHERE `ID`=64369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼은 내 것이다! 마음껏 괴롭혀 주마!', `MaleText_loc4`='你的灵魂将被我折磨！', `MaleText_loc5`='你的靈魂將會落入我手裡並接受我的折磨!', `MaleText_loc7`='¡Torturaré tu alma!', `FemaleText_loc1`='네 영혼은 내 것이다! 마음껏 괴롭혀 주마!', `FemaleText_loc4`='你的灵魂将被我折磨！', `FemaleText_loc5`='你的靈魂將會落入我手裡並接受我的折磨!', `FemaleText_loc7`='¡Torturaré tu alma!' WHERE `ID`=64370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제께서 돌아오시면 너희 종족은 모조리 멸망할 것이다!', `MaleText_loc4`='归来的国王将消灭你整个种族！', `MaleText_loc5`='大帝的回歸會為你整個種族帶來毀滅!', `MaleText_loc7`='¡El retorno del Emperador acabará con toda tu raza!', `FemaleText_loc1`='황제께서 돌아오시면 너희 종족은 모조리 멸망할 것이다!', `FemaleText_loc4`='归来的国王将消灭你整个种族！', `FemaleText_loc5`='大帝的回歸會為你整個種族帶來毀滅!', `FemaleText_loc7`='¡El retorno del Emperador acabará con toda tu raza!' WHERE `ID`=64371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 목숨을 빼앗아 주마!', `MaleText_loc4`='我的杀戮之轮将从你的头颅上辗过！', `MaleText_loc5`='我要敲碎你的腦袋!', `MaleText_loc7`='¡Voy a destrozar tu cráneo!', `FemaleText_loc1`='네 목숨을 빼앗아 주마!', `FemaleText_loc4`='我的杀戮之轮将从你的头颅上辗过！', `FemaleText_loc5`='我要敲碎你的腦袋!', `FemaleText_loc7`='¡Voy a destrozar tu cráneo!' WHERE `ID`=64372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='묵사발을 만들어 주마, $r!', `MaleText_loc4`='我要将你的首级顶在长矛上，$r！', `MaleText_loc5`='$r，我要把你的腦袋插在矛尖上!', `MaleText_loc7`='¡Clavaré tu cabeza en una pica, $r!', `FemaleText_loc1`='묵사발을 만들어 주마, $r!', `FemaleText_loc4`='我要将你的首级顶在长矛上，$r！', `FemaleText_loc5`='$r，我要把你的腦袋插在矛尖上!', `FemaleText_loc7`='¡Clavaré tu cabeza en una pica, $r!' WHERE `ID`=64373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 죽음으로도 내 손아귀를 벗어나지 못한다!', `MaleText_loc4`='你就算是死了，也休想从我的手心里逃脱！', `MaleText_loc5`='你就算死也無法脫離我的掌控!', `MaleText_loc7`='¡Ni siquiera la muerte te librará de mí!', `FemaleText_loc1`='너는 죽음으로도 내 손아귀를 벗어나지 못한다!', `FemaleText_loc4`='你就算是死了，也休想从我的手心里逃脱！', `FemaleText_loc5`='你就算死也無法脫離我的掌控!', `FemaleText_loc7`='¡Ni siquiera la muerte te librará de mí!' WHERE `ID`=64374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 몸부림은 한심하고 나약하다!', `MaleText_loc4`='瞧瞧你那可怜而又懦弱的反抗！', `MaleText_loc5`='你只是可悲又虛弱的掙扎著!', `MaleText_loc7`='¡Su lucha es lamentable y débil!', `FemaleText_loc1`='네 몸부림은 한심하고 나약하다!', `FemaleText_loc4`='瞧瞧你那可怜而又懦弱的反抗！', `FemaleText_loc5`='你只是可悲又虛弱的掙扎著!', `FemaleText_loc7`='¡Su lucha es lamentable y débil!' WHERE `ID`=64375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직임이 꼭 임신한 야크 같군. 자네는 아직 여기서 훈련할 준비가 안 되었네.', `MaleText_loc4`='你走起路来的步履犹如一头怀孕的牦牛。你还没有达到能在这里训练的要求。', `MaleText_loc5`='你的動作就像頭懷孕的犛牛。你還沒準備好在這受訓。', `MaleText_loc7`='Te mueves como un yak en cinta. Aún no te puedes instruir aquí.' WHERE `ID`=64376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물 위에서 달리려면, 아주 빨리 뛰어야 하네.', `MaleText_loc4`='要想在水上奔跑，那么你必须跑得特别快。', `MaleText_loc5`='想在水面上奔跑，你得跑得飛快才行。', `MaleText_loc7`='Para correr sobre el agua hay que correr muy rápido.' WHERE `ID`=64377;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤오티엔 모구가 이 폐허에 큰 관심을 보이고 있어요. 폐허 깊은 곳에 묻힌 힘을 되찾으려는 거예요. 폐허에 모구의 시체를 널어 놓겠어요.', `FemaleText_loc4`='韶天族对这堆废墟似乎非常感兴趣。他们打算恢复其深处的力量。而我会将他们的尸首丢弃在上面。', `FemaleText_loc5`='嘯天對這些廢墟有很高的興趣。他們打算從地底深處找回力量。我打算讓他們的屍體遍佈那些廢墟。', `FemaleText_loc7`='Los Shao-Tien se han interesado enormemente por estas ruinas. Pretenden recuperar poder de sus profundidades. Mi intención es que sus cadáveres queden esparcidos por ellas.' WHERE `ID`=64378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수련생들은 약해요. 사마귀나 모구를 직접 상대하기는커녕, 장벽 위를 걸어다닐 각오조차 안 돼 있죠. 그들이 믿음직해지려면 시간이 좀 걸릴 거예요.', `FemaleText_loc4`='这些受训者太不堪一击了。他们根本还没学会飞檐走璧，更别说直接面对螳螂妖或魔古族了。还需要很长一段时间的训练，他们才能真正派上用场。', `FemaleText_loc5`='這些弟子很弱。他們還沒準備好去駐守長城，更別提和螳螂人或魔古正面交鋒。還必須再訓練一段時間我們才能放心的交給他們真正的任務。', `FemaleText_loc7`='Estos alumnos son muy débiles. No están preparados para patrullar la muralla, y mucho menos para enfrentarse a los mántides o los mogu cara a cara. Aún queda mucho tiempo para que podamos contar con ellos realmente.' WHERE `ID`=64379;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 모두 레벤의 지휘 하에 장벽 너머에서 습격 작전을 수행하곤 했어요. 숱한 사마귀와 야운골을 상대로 검술을 갈고닦았지요. 모구는 우리가 약한 줄 알아요. 착각의 대가를 톡톡히 치르게 될 거예요.', `FemaleText_loc4`='通过城墙，我们全都在长途跋涉中效力于莱文。我们用野牛人和螳螂妖的血来祭奠我们的刀刃！这些低估我们实力的魔古族，会由于他们的错误判断而致命。', `FemaleText_loc5`='我們全都在利文麾下服役，並參加過到長城外的遠征。我們磨利我們的劍刃，抵抗過無數的螳螂人和揚古。這些魔古以為我們很弱，但這錯誤的判斷會讓他們付出慘痛的代價。', `FemaleText_loc7`='Todos hemos servido a las órdenes de Leven en incursiones al otro lado de la muralla. Hemos afilado nuestras espadas contra innumerables mántides y yaungol. Estos mogu nos consideran débiles, pero ese error de juicio les va a costar caro.' WHERE `ID`=64380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 황무지에 있으면서, 지형을 잘 파악하고 적의 동향을 이해하는 것의 중요성을 알게 되었소. 승리가 목표든 생존이 목표든, 최선의 길은 항상 적보다 두 발짝 앞서는 것이라오.', `MaleText_loc4`='踏上恐惧废土，使我明白了探查地形与洞悉敌人行动的重要性。不论是为了取胜还是存活，先发制人总能事半功倍。', `MaleText_loc5`='進入悚然荒野讓我學到認識土地和了解敵人動向的重要性。不論最終目的是勝利或只是存活，達成目標的最佳方式永遠是超前你的對手兩步。', `MaleText_loc7`='Recorrer el Desierto del Pavor me ha enseñado el valor de conocer el terreno y comprender los movimientos del enemigo. Tanto si el objetivo es la victoria como la mera supervivencia, la mejor táctica siempre es estar dos pasos por delante de tu oponente.' WHERE `ID`=64381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백전노장은 평화로운 환경에 적응하기 힘들겠지만, 그게 우리의 임무요. 마을 사람들은 전쟁을 원하지 않소. 꼭 필요한 경우가 아니라면 이 마을을 전쟁터로 만들어서는 안 되오.', `MaleText_loc4`='对于身经百战的老兵来说，很难适应和平环境，但那是我们的职责。这些村民厌恨战争，除非别无选择，否则就不要把战火引到他们门前。', `MaleText_loc5`='要一名身經百戰的老兵習慣和平時光不是件容易的事，但那是我們的職責。這些老百姓不想要戰爭，若非必要，我們不該將戰爭帶到他們的家門口。', `MaleText_loc7`='Puede que sea difícil para un veterano curtido acostumbrarse a un entorno tranquilo, pero ese es nuestro deber. Estos aldeanos no buscan la guerra; no se la acerquemos hasta su puerta si no es necesario.' WHERE `ID`=64382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단하지 않나?!', `MaleText_loc4`='他是不是很了不起？！', `MaleText_loc5`='他很雄偉，不是嗎?', `MaleText_loc7`='¡¿No es magnífico?!' WHERE `ID`=64383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹일 입은 너무 많은데, 먹일 재료는 늘 모자란다오!', `MaleText_loc4`='有这么多人要去养活，可是从来没有足够的食物去喂饱他们！', `MaleText_loc5`='有這麼多張嘴要養，但從來都沒有足夠的材料來餵飽他們!', `MaleText_loc7`='Tenemos muchas bocas que alimentar y nunca contamos con los ingredientes suficientes para ello.' WHERE `ID`=64384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코보크, 이리 오거라.', `MaleText_loc4`='到我这里来科沃克。', `MaleText_loc5`='到我這來，科沃克。', `MaleText_loc7`='Ven a mí, Kovok.' WHERE `ID`=64385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투 셴 봉기에 참여하신 저희 조상님 한 분이 지금 이 묘지에 묻혀 계십니다. 할 수만 있다면 참배를 하고 싶은데, 영혼들이 통 잠잠해지질 않아서 말이지요.', `MaleText_loc4`='我的一位先祖参加了徒圣起义，他的尸体就躺在这墓地里。我愿意放弃我的自尊去接受和平，但是墓地里的鬼魂知道这个世界是没有和平可言的。', `MaleText_loc5`='我的一位先祖參加過在土神的起義，現在長眠於這些墳墓之中。如果可以的話我會致上我的敬意，但那裡的靈魂並沒有安息。', `MaleText_loc7`='Uno de mis antepasados participó en el levantamiento de Tu Shen, y ahora se encuentra entre las tumbas. Le presentaría mis respetos si pudiera, pero los espíritus de allí no conocen la paz.' WHERE `ID`=64386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련생은 모름지기 패배의 쓴맛을 알아야 합니다. 그래야만 승리의 진가를 알아볼 수 있기 때문이지요.', `MaleText_loc4`='只有让受训者尝到了失败的滋味，他们才会明白胜利的意义。', `MaleText_loc5`='讓弟子們學到戰敗的痛苦是很重要的事。那樣他們才能體會勝利的價值。', `MaleText_loc7`='Es importante para los alumnos conocer el sabor de la derrota para poder apreciar el valor de la victoria.' WHERE `ID`=64387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<허가 엄숙한 표정으로 당신을 바라봅니다.>', `MaleText_loc4`='<他对你露出了满脸的狰狞。>', `MaleText_loc5`='<他可怕地看著你。>', `MaleText_loc7`='<Zheng te lanza una mirada sombría.>' WHERE `ID`=64388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 다가가자 허의 눈이 반짝 빛납니다.>', `MaleText_loc4`='<当你靠近的时候，他变得异常兴奋。>', `MaleText_loc5`='<他的雙眼在你接近時一亮。>', `MaleText_loc7`='<Los ojos de Zheng se iluminan cuando te acercas.>' WHERE `ID`=64389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<허가 멍하니 당신을 바라봅니다.>', `MaleText_loc4`='<他面无表情地注视着你。>', `MaleText_loc5`='<他無神地瞪視著你。>', `MaleText_loc7`='<Zheng te mira inexpresivamente.>' WHERE `ID`=64390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 작전에서 두뇌와 미모를 담당하고 있지. 안지가 힘이랑 두 번째 미모를 담당하고 있고 말야.$B$B우린 미모가 넘친다니까.', `MaleText_loc4`='我喜欢把自己看作此次行动的幕后智囊和台前花旦。安济的四肢发达。并且她也是个台前花旦。$B$B我们这里已经有很多台前花旦了。', `MaleText_loc5`='我喜歡把自己定位為智囊，也是這次行動中美好的事。安吉是肌肉派，也是第二個美好的事。$B$B我們有很多美好的事。', `MaleText_loc7`='Me gusta pensar que soy el cerebro y la belleza de esta operación. Anji es la fuerza bruta. Y la segunda belleza.$B$BTenemos muchas bellezas.' WHERE `ID`=64391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 거미가 싫어. 움직이는 석상도 싫어. 뭘 훔쳐가는 요마도 싫고. 이 폐허엔 내가 싫어하는 게 너무 많아. 다행히 안지가 있어 줘서, 내 미모를 유지할 수 있지!', `MaleText_loc4`='我讨厌蜘蛛。还有那些移动的神像。以及偷东西的精灵。这片废土上的一切我都讨厌。幸运的是，我还有安济，她可以让我的容貌完美无瑕！', `MaleText_loc5`='我不喜歡蜘蛛。或是會動的雕像。或是會偷東西的妖精。這廢墟裡有很多我不喜歡的東西。幸運的是，有安吉在這裡讓我保持漂漂亮亮的!', `MaleText_loc7`='No me gustan las arañas. Ni las estatuas que se mueven. Ni los duendes que te roban objetos. Hay muchas cosas que no me gustan en estas ruinas. Afortunadamente para mí, ¡Anji está aquí para mantenerme con buen aspecto!' WHERE `ID`=64392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기엔 샤오티엔이 우리에게서 숨을 수 있는 구석이 없네. 놈들은 음영파의 끈기를 얕보고 있어.', `MaleText_loc4`='韶天族在这个山谷里没有可以藏身之处，他们低估了影踪派的坚韧不屈。', `MaleText_loc5`='在這山谷裡，嘯天的傢伙無處可藏。他們低估了影潘的頑強。', `MaleText_loc7`='No hay un rincón en este valle en el que el Shao-Tien pueda ocultarse de nosotros. Infravaloran la tenacidad del Shadopan.' WHERE `ID`=64393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 돌아오고 서쪽에서 사마귀 무리가 일어나는 등 위협이 커지자 수련생 수가 늘어났다네. 좋은 일이지. 곧 필요하게 될 테니.', `MaleText_loc4`='魔古族的归来以及西边的螳螂妖纷涌而至，他们带来的威胁不断加剧，这些都引来了比以往更多的受训者。这很好。他们会派上用场的。', `MaleText_loc5`='魔古回歸所帶來的威脅日益增長，加上西邊群聚的螳螂人，讓受訓弟子的數量大幅超越平常。這樣很好。我們會有需要他們的一天。', `MaleText_loc7`='Las amenazas producidas por el regreso de los mogu y por los enjambres mántides al oeste han provocado que haya muchos más alumnos. Eso está bien. Nos harán falta.' WHERE `ID`=64394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 강력한 적이지만, 나와 부하들이 공포의 황무지에서 상대했던 무시무시한 적에 비하면 아무것도 아니지. 우리가 골짜기를 지켜 낼 수 있다는 데 추호의 의심도 없네.', `MaleText_loc4`='魔古族可能是一个强大的威胁，但跟我和我的士兵所面对的恐惧废土的恐惧比起来，它根本不能恫吓住我们。我们一定可以在山谷中挖出一个洞来。', `MaleText_loc5`='魔古是重大的威脅，但和我們在悚然荒野遇到的恐怖相比根本不算什麼。我毫不懷疑我們有辦法守住山谷。', `MaleText_loc7`='Los mogu son una gran amenaza, pero no son nada en comparación con los horrores a los que mis hombres y yo hemos tenido que enfrentarnos en el Desierto del Pavor. No me cabe duda que podemos defender el valle.' WHERE `ID`=64395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리도 당신처럼 이 골짜기에 처음 왔어요. 쿤라이에서 고향을 잃어서 문이 열릴 때 들어왔거든요. 지을 것도 많고 고칠 것도 많아요.', `FemaleText_loc4`='我们跟你们一样对这个山谷一无所知。当闸门一打开，我们就来了。失去了我们在昆莱的家园。想必在这里我们可重建它。', `FemaleText_loc5`='我們和你一樣剛來到這個山谷。我們失去了在崑萊的家，並在關口打開時來到這裡。有很多需要建設，也有很多需要維護。', `FemaleText_loc7`='Somos tan nuevos en este valle como tú. Vinimos cuando se abrieron las puertas, tras perder nuestros hogares en Kun-Lai. Hay mucho que construir, mucho que arreglar.' WHERE `ID`=64396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 저주라도 받은 건 아닌지 의심스러울 지경이에요. 끔찍한 일이 끊이질 않으니 말이에요.$B$B애써 기분 좋은 척하면서, 조금이라도 좋은 일이 생기면 기뻐하는 것밖에 할 수 있는 일이 없죠.', `FemaleText_loc4`='我想我们也许被某种方式给诅咒了。我们所遭受的恐惧，似乎从来没有停止。$B$B有时你所有能做的就是尽量保持良好的精神状态，或许可以对变化无常的曲折命运抱一丝淡淡的感激，而不必在乎到底最后的归宿为何。', `FemaleText_loc5`='我懷疑我們的命運是否受到什麼詛咒。發生在我們身上的恐怖厄運似乎永無休止。$B$B有時候，你唯一能做的就是保持樂觀的精神，或者為了任何一點運氣上的轉變而感到欣慰。不論是變好，或是變壞。', `FemaleText_loc7`='Me pregunto si nuestro destino está maldito. Los horrores que hemos sufrido parecen no tener fin.$B$BA veceslo único que puedes hacer es intentar mantener un buen espíritu y, quizás, apreciar los giros caprichosos del destino.' WHERE `ID`=64397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 판다리아에서 가장 풍요로운 땅일세! 머리만 잘 쓰면 부자가 될 수 있겠어!', `MaleText_loc4`='这是整个潘达利亚最美丽的地方！聪明人在这里可以赚得盆满钵满！', `MaleText_loc5`='這是全潘達利亞最富裕的土地!只要夠聰明，就可以在這裡大發一筆的!', `MaleText_loc7`='Esta es la tierra más pródiga de toda Pandaria. ¡Alguien listo podría enriquecerse aquí!' WHERE `ID`=64398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 생긴 마을만큼 돈 벌기 좋은 곳도 없지! 필요한 물건도 많고, 거래할 물건도 많고. 여기서라면 피둥피둥 살을 찌우며 행복하게 살 수 있겠어!', `MaleText_loc4`='充满生机的村庄是谋生的绝佳去处！这里需要很多物资，所以能进行各种各样的贸易。我想我确实可以在这里过着无忧无虑的生活！', `MaleText_loc5`='一個新生的村落是謀生的好地方!需要這麼多的貨物，需要那麼多的交易。我想我可以在這裡開心賺得肥肥的!', `MaleText_loc7`='¡Un aldea incipiente es el lugar perfecto para vivir! Hay mucha mercancía, mucha mercancía con la que comerciar. ¡Creo que aquí sería feliz y engordaría!' WHERE `ID`=64399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람이 이곳에 발을 들이기 전에, 이 골짜기가 매우 평화롭고 아름다운 곳이라는 이야기를 귀에 못이 막히도록 들었다네. 그런데 정작 와 보니, 온갖 괴물들이 머리를 부수려 하거나 다리를 물어뜯으려 하지 뭔가.$B$B그 이야기가 거짓이었던 건가, 아니면 우리가 함께 지내기에 그렇게 끔찍한 존재인 건가? 이 내가 있으니 설마 후자일 리는 없을 거라 믿네. 말도 안 되는 얘기니 말이야.', `MaleText_loc4`='早在很久之前，我就听说这是个非常宁静、美丽的山谷，那个时候没有人被允许进入。现在我们置身其中，发现到处都是形形色色的野兽，不是想打碎我们的脑袋就是想咬掉我们的脚。$B$B所以这个传说是个谎言，或者说我们只是令人憎恶的不速之客？我还是摒弃后一种想法吧，因为那样想的话就太自欺欺人了。', `MaleText_loc5`='在我們被禁止進來之前，我一直聽說這座山谷是多麼的平靜又美麗。現在我們終於來到這裡了，結果卻有各式各樣的野獸在等著扭掉我們的頭、啃掉我們的腳。$B$B所以到底是故事在騙人，還是我們不是受歡迎的好客人?我還是把後者的可能性給排除了，因為那樣想未免太傻了。', `MaleText_loc7`='No he oído nada más que historias acerca de lo pacífico y hermoso que era este valle, antes de que ninguno pudiéramos entrar. Ahora que estamos aquí, resulta que hay todo tipo de bestias deseando partirnos la cabeza o mordernos los pies.$B$B¿Es que son mentira las historias o es que somos muy mala compañía? Me excluyo humildemente de la última posibilidad, sería absurdo no hacerlo.' WHERE `ID`=64400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 정말 으시시하군. 안 그런가? 게다가 덫까지 놓다니... 손님을 이렇게 냉대할 수가 있나. 모구 녀석들, 장식하는 법을 좀 배워야겠어.', `MaleText_loc4`='这里所有的一切都让人毛骨悚然，不是吗？还有这些陷阱，真是让人太不舒服了。这些魔古族真应该将这些陷阱做得隐蔽些。', `MaleText_loc5`='好吧，這真是太見鬼了，對吧?還有這些陷阱，真是不太友善。這些魔古真的該好好接受一點關於裝潢的建議。', `MaleText_loc7`='Esto da un poco de miedo, ¿verdad? Y estas trampas no son muy halagüeñas. Esos mogu deberían aceptar consejos de decoración.' WHERE `ID`=64401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 걱정되는 일이 있다네. 이 계곡에 피는 꽃이 정말로 영원하다면, 새로 꽃이 피는 건 좀 위험한 일 아닌가? 꽃에 파묻혀 숨도 못 쉬게 될걸. 꽃이 아무리 향기가 좋고 부드러워도 그건 곤란하지.$B$B혹시 모르니까 나는 작은 꽃을 짓밟고 다닌다네. 균형을 유지하기 위해서지.', `MaleText_loc4`='如果这个山谷里百花盛开是真正永恒的，那么对于刚长出来的新芽来说是相当危险的，不是吗？这正是我所担心的地方。我们将会在香软且令人窒息的花海中畅游。$B$B为了安全起见，我将小朵的花踩在脚下碾碎，只是为了保持事物的平衡，你明白吗？', `MaleText_loc5`='我常常想，這片山谷裡的花真的是永遠盛開的嗎?那樣若有花新開出來，不就很危險嗎?我們會必須游過一整片令人窒息的花海，雖然說那樣是很香又很軟啦。$B$B為求謹慎，我喜歡把那些較小的花踩扁在腳下。為了保持萬物的平衡，你懂嗎?', `MaleText_loc7`='A veces me pregunto: si las flores de este valle son eternas de verdad, sería peligroso que crecieran unas nuevas, ¿no? Nadaríamos en un mar de flores asfixiantes, aunque fueran olorosas y suaves.$B$BMe gusta ir sobre seguro y aplastar las pequeñas con la bota, solo para mantener el equilibrio, ¿sabes?' WHERE `ID`=64402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루크는 친구한테 잘해.', `MaleText_loc4`='鲁克对朋友很好。', `MaleText_loc5`='茹克對朋友很好。', `MaleText_loc7`='Rook trata bien amigos.' WHERE `ID`=64403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='루크는 모구 뭉개 주고 싶어! 근데 마을 사람들이 위험해! 루크가 마을 사람들 지킬 테니까 모구 뭉개 줄래?', `MaleText_loc4`='鲁克想要捣毁魔古族，但是那些村民会处在危险之中！如果鲁克保护村民的安全，你会帮助他捣毁魔古族吗？', `MaleText_loc5`='茹克想要打爆魔古，但村民們不安全!如果茹克保護村民安全，你能幫忙打爆魔古嗎?', `MaleText_loc7`='Rook quiere aplastar mogu, ¡pero habitantes no seguros! Si Rook cuida de los habitantes, ¿ayudarás a machacar mogu?' WHERE `ID`=64404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 모구는 부서진 기둥이랑 벽을 지은 걸까? 다른 사람들처럼 건물을 다 안 짓고 말이야. 모구는 멍청한가 봐.', `MaleText_loc4`='为什么老魔古在这里修建破碎的柱子和墙壁？为什么不像其他人一样建造完整的建筑物？愚蠢的魔古。', `MaleText_loc5`='為什麼老魔古在這裡建造壞掉的柱子和牆?為什麼不像其他人一樣建造完整的房子?魔古笨笨。', `MaleText_loc7`='¿Por qué los mogu construyen pilares y muros rotos aquí? ¿Por qué no construyen edificios completos como todo el mundo? Los mogu están fatal.' WHERE `ID`=64405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 폐허에는 고대 모구의 비밀이 수도 없이 잠들어 있습니다. 이 골짜기 전체가 한때는 모구의 땅이었지요. 아직 판다렌이 발을 들인 적이 없는 곳도 있고요.', `FemaleText_loc4`='在这些废墟中藏有许多古魔古族的秘密。这里曾经整个都属于他们，甚至某些角落中还可以发现被熊猫人践踏过的脚印。', `FemaleText_loc5`='有許多古老的魔古秘密藏在這些廢墟之中。這整座峽谷有一度為他們所有，而有些角落熊貓人還尚未踏足過。', `FemaleText_loc7`='Entre estas ruinas yacen innumerables secretos ancestrales mogu. Todo este valle fue suyo en otro tiempo, y algunos rincones del mismo no han sido pisados aún por pies pandaren.' WHERE `ID`=64406;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구는 포로에게 무자비합니다. 우리의 용맹한 전사들이 모구에게 사로잡힌다면 한시도 낭비해서는 안 되지요.', `FemaleText_loc4`='魔古族是凶残的绑匪。如果我们勇敢的战士已经落入他们手里，那么不管在任何时候，我们就不应该再去冒险了。', `FemaleText_loc5`='魔古對俘虜很殘酷。要是我們有戰士落入他們的手裡，我們也不該賭上時間去援救他們。', `FemaleText_loc7`='Los mogu son captores crueles. No deberíamos arriesgarnos si uno de nuestros valientes guerreros ha caído en sus manos.' WHERE `ID`=64407;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어두운 때일수록, 끈기 있는 마음과 격려의 손길이 진가를 발휘하지요.', `FemaleText_loc4`='在最黑暗的时代，通常只有耐心的精神和可靠的手可以担负起最大的责任。', `FemaleText_loc5`='在最黑暗的時代裡，堅忍的靈魂和堅毅的手往往擁有最高的價值。', `FemaleText_loc7`='En los tiempos más oscuros, a menudo el espíritu paciente y la mano firme son las cualidades más valiosas.' WHERE `ID`=64408;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을에 닥친 불행은 안타까울 따름이에요. 고난이 끊이질 않는 것 같아요. 게다가 골짜기에 모구가 출현했으니, 앞으로도 당분간은 그럴 것 같네요.', `FemaleText_loc4`='我为这个村子的将来潸然泪下。只要魔古族呆在山谷里一天，他们和魔古族之间的痛苦噩梦似乎永远没有结束的时候。', `FemaleText_loc5`='我為這村莊的命運而哭泣。他們的苦日子似乎沒有盡頭。有魔古出現在山谷，苦難結束的時間多半要更加延長了。', `FemaleText_loc7`='Lloro por la fortuna de esta aldea. Sus tiempos difíciles parecen no terminar nunca, y con los mogu en el valle, la situación aún tardará en mejorar.' WHERE `ID`=64409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련생들은 생존의 장에서 반사 능력을 기름으로써 장벽 너머에서 살아남을 수 있게 됩니다. 그곳의 적은 인정사정이 없거든요.', `MaleText_loc4`='修建在生存之环中的反射可以使受训者在城墙外得以生存。在那里，威胁更不容易被放任。', `MaleText_loc5`='在生存競技場裡磨鍊出來的反應能力是讓這些受訓弟子能在長城外還能生存的原因。在長城外，各種危險威脅都比這競技場更為致命。', `MaleText_loc7`='Los reflejos desarrollados en el ring de supervivencia son lo que mantienen a estos alumnos vivos al otro lado de la muralla. Allí, las amenazas son mucho menos indulgentes.' WHERE `ID`=64410;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 부탁을 하시네요! 농부 윤이 언제쯤 저를 알아볼까 궁금해하는 중이었어요. 당신 먼저 가세요. 저는 시장 일을 끝마치고서 뒤따라갈게요.', `FemaleText_loc4`='正好是你要求的时间！我想知道农夫老愚会什么时候通知我。你先走，今天市集的生意结束后，我会在那里和你会合。', `FemaleText_loc5`='也該是你這麼問的時候了!我原本在想農夫尹到底會不會注意到我。你先走，我把市集的工作做忙之後馬上就過去。', `FemaleText_loc7`='¡Ya era hora de que me lo pidieras! Me preguntaba cuándo se daría cuenta el granjero Yoon de que existo. Adelántate tú, que yo voy en cuanto termine en el mercado.' WHERE `ID`=64411;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='태양노래 농장에 제 도움이 필요하다고요? 오늘 시장 일을 끝마치고 거기서 저와 만나요.', `FemaleText_loc4`='日歌农场需要我帮忙吗？今天市集的生意结束后，我会在那里和你会合。', `FemaleText_loc5`='日歌農莊需要我的幫助?我今天市集忙完後會去那裡和你會合。', `FemaleText_loc7`='¿Que el Rancho Cantosol necesita mi ayuda? Nos vemos allí en cuanto termine en el mercado.' WHERE `ID`=64412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 내가 잠깐 다른 곳에 들러도 닭들은 신경 안 쓸 걸세. 오늘 시장에서 장사를 마무리하고 그곳에서 나와 만나세나.', `MaleText_loc4`='如果只待一小会儿，我想这些小鸡是不会介意的。今天市集的生意结束后，我会在那里和你会合。', `MaleText_loc5`='我想雞群不會在意我過去拜訪一下。等我做完今天在市場這裡的工作，我會和你在那裡見。', `MaleText_loc7`='Bueno, supongo que estas gallinas no les importará que les haga una visitilla. Nos vemos allí luego cuando termine en el mercado.' WHERE `ID`=64413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일은 뭉뭉에게 잠깐 맡기고 윤의 농장을 한번 보러 가도 될 것 같군. 일단 시장에서 볼일부터 좀 봐야겠네.', `MaleText_loc4`='也许我可以暂时将事情交给蒙蒙来做，然后去老愚那里看一看。但是，我得先完成今天在市集上的生意。', `MaleText_loc5`='我想我可以把事情交給芒芒一下子然後去尹的田裡看看。等我做完在市場這裡的工作吧。', `MaleText_loc7`='Supongo que podría dejar que Mung-Mung se encargue de todo durante un rato y echarle un vistazo a la granja de Yoon. Espera a que ponga todo en orden en el mercado primero.' WHERE `ID`=64414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니까? 저 연못이 전부 제 거라고요? 곧바로 가겠습니다... 이 술 좀 마저 다 마시고... *딸꾹*!', `MaleText_loc4`='真的吗？整个池塘都是我的了？在我喝完这杯酒之后……我会在那里……嗝！', `MaleText_loc5`='真的嗎?整個池塘都是我的?我會馬上過去...等我喝完這杯酒之後...嗝!', `MaleText_loc7`='¿En serio? ¿Todo ese estanque solo para mí? ¡Ahora mismo voy! En cuanto me termine la bebida... ¡hip!' WHERE `ID`=64415;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 알겠어요. 가끔 농사일을 할 수도 있죠, 뭐. 그런데 지금 당장은 갈 수 없어요. 일단 시장에서 끝내야 할 볼일이 있어서요.', `FemaleText_loc4`='好了，我想我又可以在去农场的路上活蹦乱跳了。但我还不能马上这么做。我有些要先在市集上完成的生意。', `FemaleText_loc5`='好吧，我想我可以偶爾過去農場那邊。但我不能馬上去。我得先忙完市集這裡的事。', `FemaleText_loc7`='Bueno, vale, creo que podría pasarme por la granja de vez en cuando. No lo puedo hacer ahora mismo, eso sí. Tengo que terminar unos asuntos en el mercado primero.' WHERE `ID`=64416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제 물어보시나 궁금해하고 있었습니다. 물론이죠. 하지만 오늘은 안 됩니다. 시장에서 볼일을 다 보고 나면 곧바로 가겠습니다!', `MaleText_loc4`='我一直在想你什么时候会问起。一定的，但不是今天。一旦市集上的生意做完，我就会过去！', `MaleText_loc5`='我正在想你什麼時候會問咧。當然沒問題，不過不是今天。一旦我完成了市場的工作，我會馬上過去的。', `MaleText_loc7`='Me preguntaba cuándo me lo ibas a pedir. Por supuesto, pero hoy no puedo. Deja que me ocupe de un par de cosas en el mercado y me paso enseguida.' WHERE `ID`=64417;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 아빠는 도움이 필요한 이웃이 있으면 도와주라고 하셨어요! 그런데 여기 시장에서 다른 일 좀 먼저 봐야 해요. 최대한 빨리 갈게요!', `FemaleText_loc4`='我爸爸经常告诉我要在危难之际帮助邻居！我得先去市集上办一些事情才行。我会尽快过去的。', `FemaleText_loc5`='我老爸總是說要幫助需要幫忙的鄰居!我先處理市集這裡的一些事情，然後馬上過去!', `FemaleText_loc7`='¡Mi padre siempre decía que había que ayudar a un vecino en apuros! Solo tengo que encargarme de un par de cosas aquí en el mercado primero. ¡Estaré allí tan pronto como pueda!' WHERE `ID`=64418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이죠. 제가 약간 도와드릴 수 있을 것 같아요! 그런데 오늘은 시장을 떠날 수 없답니다. 하지만 최대한 빨리 갈게요.', `FemaleText_loc4`='当然，我想我能帮到你一些事情！我今天不能马上离开市集，不过我会尽快去那里的。', `FemaleText_loc5`='當然，我想我可以幫上一點忙。我今天無法離開市集，但我會盡快趕去那裡。', `FemaleText_loc7`='¡Por supuesto, supongo que podría ayudar un poco! No puedo dejar el mercado hoy pero estaré allí lo antes posible.' WHERE `ID`=64419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다, 대장! 그런데 치 치 오늘은 시장에서 할 일 있다. 그거 하고 나면 곧바로 간다.', `MaleText_loc4`='好的，老板！吱吱今天在市集上有些事情要办，然后他会很快去那里的。', `MaleText_loc5`='是的，老闆!奇奇在市場還有事要做，然後他就會馬上過去。', `MaleText_loc7`='¡Vale, $gjefe:jefa;! Chee Chee tiene kosas que hacer en el merkado, luego vuelve pronto.' WHERE `ID`=64420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록 하나가 보석을 일부 챙겨서는 숨겨진 계단을 달려 내려갑니다!', `MaleText_loc4`='一个蜥蜴人抱着一些宝藏逃到了隐藏的阶梯下面！', `MaleText_loc5`='一個薩烏洛克帶著一些寶藏跑下一段隱藏的階梯!', `MaleText_loc7`='¡Un saurok está bajando unas escaleras a toda prisa con parte del tesoro!' WHERE `ID`=64421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 용장이 물리적 능력으로 선택받은 것은 아니다, 깨우는 자여.', `MaleText_loc4`='不是所有的英杰都因为身手矫健而被选中的，唤醒者。', `MaleText_loc5`='並非所有的聖螳都是因為戰鬥技巧而獲選的，喚醒者。', `MaleText_loc7`='No todos los dechados fueron elegidos por sus habilidades físicas, heraldo.' WHERE `ID`=64422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 아름다운 생명체군. 그렇게 생각하지 않나? 크기가 작다고 얕보지 말거라. 어린 쿤총이라도 치명적이니까.$b$b내가 발견하지 전까지는, 쿤총은 그 지능을 거의 고려하지 않은 채 무기로 쓰이곤 했다. 쿤총을 제어하려고 수많은 노력을 들이고 나서야 비로소 우리가 쿤총을 완전히 이해하지 못하고 있다는 생각이 들었지.$b$b쿤총과 유대 관계를 형성함으로써 우리는 더는 강력하게 제어하지 않아도 되었고, 그 대신 동료 관계가 생겨났다.$b$b코보크가 내 실험의 다음 단계였지.', `MaleText_loc4`='多美的生物啊，你不觉得吗？别被它的小身材给骗了。恐虫在幼年时期也有着致命的杀伤力。$b$b在我的发现之前，恐虫只被当做武器，几乎无人关注它们的智力。我们竭力控制它们，直到我突然意识到，我们对它们的了解还远远不够。$b$b通过与这个物种建立起纽带，我们不再需要对其强行施加控制，而是形成一种伙伴关系。$b$b科沃克将是我的下一个实验对象。', `MaleText_loc5`='多麼美麗的生物啊，你不同意嗎?別讓其小小的體型欺騙你。就算在幼生期，崑蟲還是很致命。$b$b在我的發現之前，崑蟲被用來當作武器使用，毫無顧及牠們的智能。我們努力嘗試要控制牠們，直到我想到我們對牠們並無全盤的了解。$b$b藉由和牠們形成一種聯結，我們不再需要強制性地施加控制。取而代之的是一種夥伴的關係。$b$b科沃克就是我實驗中的下一步。', `MaleText_loc7`='Una criatura bellísima, ¿no te parece? No te dejes engañar por su pequeño tamaño. Incluso jóvenes, los kunchong son letales.$b$bAntes de mi descubrimiento, los kunchong se utilizaban como armas, sin pensar en su inteligencia. Nos costaba mucho controlarlos, hasta que me di cuenta de que no los comprendíamos del todo.$b$bFormando un vínculo con las criaturas, ya no necesitábamos ejercer un control a la fuerza. En su lugar, surgió una asociación.$b$bKovok fue el siguiente paso de mi experimento.' WHERE `ID`=64423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호박석 감옥에 갇혔습니다. 풀어 주십시오!', `MaleText_loc4`='$n被困在琥珀监牢！释放他们！', `MaleText_loc5`='$n被困在一個琥珀監獄裡!把他們放出來!', `MaleText_loc7`='¡Una prisión de ámbar ha atrapado a $n! ¡Hay que abrirla!', `FemaleText_loc1`='$n|1이;가; 호박석 감옥에 갇혔습니다. 풀어 주십시오!', `FemaleText_loc4`='$n被困在琥珀监牢！释放他们！', `FemaleText_loc5`='$n被困在一個琥珀監獄裡!把他們放出來!', `FemaleText_loc7`='¡Una prisión de ámbar ha atrapado a $n! ¡Hay que abrirla!' WHERE `ID`=64424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t바람군주 멜자라크가 |cFFF00000|Hspell:122407|h[칼날의 비]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t风领主梅尔加拉克开始施放|cFFF00000|Hspell:122407|h[刃雨]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t風領主瑪爾加拉克開始施放|cFFF00000|Hspell:122407|h[刀刃之雨]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_sword_2h_mantid_01.blp:20|t¡El señor del viento Mel''jarak empieza a lanzar |cFFF00000|Hspell:122407|h[Lluvia de espadas]|h|r!' WHERE `ID`=64425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람군주 멜자라크가 동료가 다섯 이상 행동 불가 상태가 된 것을 감지하고 풀어 줍니다!', `MaleText_loc4`='风领主梅尔加拉克察觉到4个以上的盟友丧失了能力，并释放了他们！', `MaleText_loc5`='風領主瑪爾加拉克查覺到他有4個以上的盟友被癱瘓而釋放了他們。', `MaleText_loc7`='¡El señor del viento Mel''jarak nota que más de 4 de sus aliados están incapacitados y los libera!' WHERE `ID`=64426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 대체...', `MaleText_loc4`='这简直是……', `MaleText_loc5`='搞什麼...', `MaleText_loc7`='Pero qué...' WHERE `ID`=64427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대괴수다!!', `MaleText_loc4`='巨兽！！', `MaleText_loc5`='巨大海怪!', `MaleText_loc7`='¡¡LEVIATÁN!!' WHERE `ID`=64428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이들에게 알려야 해!', `MaleText_loc4`='我们要警告其他人！', `MaleText_loc5`='我們必須警告其他人!', `MaleText_loc7`='¡Tenemos que avisar a los demás!' WHERE `ID`=64429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아아!', `MaleText_loc4`='啊啊啊！！', `MaleText_loc5`='啊啊啊啊啊!!', `MaleText_loc7`='¡¡Aaaaaaaaah!!' WHERE `ID`=64430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀을 지키는 건 꿈의 직업이라고 하긴 어렵지요. 하지만 보수가 짭짤하거든요. 게다가 산길에서 재미있는 구경도 많이 할 수 있지요.', `MaleText_loc4`='守卫土地精可不是我梦想的职业，不过他们给的报酬倒是不错。此外在山路上你会遇见很多奇怪的事情。', `MaleText_loc5`='保衛咕嚕摩的工作不是我會稱為我生命中夢想的角色，但他們支付很高的酬勞。你還能在山路上看見許多奇怪的東西。', `MaleText_loc7`='Proteger a los grúmel no es exactamente mi gran sueño, pero me pagan bien. Además, se ven cosas de lo más extrañas por el camino.', `FemaleText_loc1`='그루멀을 지키는 건 꿈의 직업이라고 하긴 어렵죠. 하지만 보수가 짭짤하거든요. 게다가 산길에서 재미있는 구경도 많이 할 수 있어요.', `FemaleText_loc4`='守卫土地精可不是我梦想的职业，不过他们给的报酬倒是不错。此外在山路上你会遇见很多奇怪的事情。', `FemaleText_loc5`='保衛咕嚕摩的工作不是我會稱為我生命中夢想的角色，但他們支付很高的酬勞。你還能在山路上看見許多奇怪的東西。', `FemaleText_loc7`='Proteger a los grúmel no es exactamente mi gran sueño, pero me pagan bien. Además, se ven cosas de lo más extrañas por el camino.' WHERE `ID`=64431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저지대에서 왔습니까? 저지대 사람이 이까지 오는 건 드문 일입니다.', `MaleText_loc4`='你来自低地？我们没怎么见过来自低地的人会走这条路。', `MaleText_loc5`='你是從低地來的嗎?我們不常在這條路上看到低地人。', `MaleText_loc7`='¿Vienes de las tierras bajas? No suele subir mucha gente.', `FemaleText_loc1`='저지대에서 왔나요? 저지대 사람이 이까지 오는 건 드문 일이에요.', `FemaleText_loc4`='你来自低地？我们没怎么见过来自低地的人会走这条路。', `FemaleText_loc5`='你是從低地來的嗎?我們不常在這條路上看到低地人。', `FemaleText_loc7`='¿Vienes de las tierras bajas? No suele subir mucha gente.' WHERE `ID`=64432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산에는 무슨 일로 왔습니까?', `MaleText_loc4`='什么风把你吹到山上来了？', `MaleText_loc5`='是什麼原因讓你上山的?', `MaleText_loc7`='¿Qué te trae hasta lo alto de la montaña?', `FemaleText_loc1`='산에는 무슨 일로 왔나요?', `FemaleText_loc4`='什么风把你吹到山上来了？', `FemaleText_loc5`='是什麼原因讓你上山的?', `FemaleText_loc7`='¿Qué te trae hasta lo alto de la montaña?' WHERE `ID`=64433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루멀은 보통 음영파의 보호를 받지요. 아마 용의 척추 쪽이 위험한 모양입니다.', `MaleText_loc4`='土地精经常有影踪派守护在其左右。我猜在蟠龙脊上一定有危险。', `MaleText_loc5`='咕嚕摩通常有影潘保衛他們。我猜想蟠龍脊上一定有危險。', `MaleText_loc7`='A los grúmel los suele proteger el Shadopan. Debe de haber algún peligro en el Espinazo del Dragón.', `FemaleText_loc1`='그루멀은 보통 음영파의 보호를 받지요. 아마 용의 척추 쪽이 위험한 모양이에요.', `FemaleText_loc4`='土地精经常有影踪派守护在其左右。我猜在蟠龙脊上一定有危险。', `FemaleText_loc5`='咕嚕摩通常有影潘保衛他們。我猜想蟠龍脊上一定有危險。', `FemaleText_loc7`='A los grúmel los suele proteger el Shadopan. Debe de haber algún peligro en el Espinazo del Dragón.' WHERE `ID`=64434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤의 고함 소리를 들었습니까? 놈의 목소리가 계속 바람에 실려 옵니다. 좋지 않아요. 아주 좋지 않지요.', `MaleText_loc4`='你听说过煞魔吗？在风里，我们经常听到它的声音。不妙。大事不妙。', `MaleText_loc5`='你有聽說過煞嗎?我們一直從風中聽到他們的聲音傳來。不妙，非常不妙。', `MaleText_loc7`='¿Has oído al sha? No dejamos de oír su voz en el viento. Eso no es bueno. Eso no es nada bueno.', `FemaleText_loc1`='샤의 고함 소리를 들었어요? 놈의 목소리가 계속 바람에 실려 와요. 좋지 않아요. 아주 좋지 않지요.', `FemaleText_loc4`='你听说过煞魔吗？在风里，我们经常听到它的声音。不妙。大事不妙。', `FemaleText_loc5`='你有聽說過煞嗎?我們一直從風中聽到他們的聲音傳來。不妙，非常不妙。', `FemaleText_loc7`='¿Has oído al sha? No dejamos de oír su voz en el viento. Eso no es bueno. Eso no es nada bueno.' WHERE `ID`=64435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 산악 호젠이 기승을 부리고 있습니다. 산길을 다닐 때 조심하십시오.$b$b놈들이 음영파가 없다는 걸 알아채고 이곳으로 쳐들어오는 것도 시간문제입니다.', `MaleText_loc4`='高山猢狲正在肆虐。在这条路上行走要多加小心。$b$b迟早他们会发现影踪派不在这里，并会向我们追赶而来。', `MaleText_loc5`='山上的猴人正在大肆劫掠。當你行走在路上時要小心。$b$b他們發現影潘不在此地並大舉向我們進軍也許只是時間問題罷了。', `MaleText_loc7`='Los hozen de la montaña están arrasando. Ten cuidado cuando viajes por los caminos.$b$bEs cuestión de tiempo que se den cuenta de que el Shadopan no está aquí y decidan saquearnos.', `FemaleText_loc1`='요즘 산악 호젠이 기승을 부리고 있어요. 산길을 다닐 때 조심하세요.$b$b놈들이 음영파가 없다는 걸 알아채고 이곳으로 쳐들어오는 것도 시간문제예요.', `FemaleText_loc4`='高山猢狲正在肆虐。在这条路上行走要多加小心。$b$b迟早他们会发现影踪派不在这里，并会向我们追赶而来。', `FemaleText_loc5`='山上的猴人正在大肆劫掠。當你行走在路上時要小心。$b$b他們發現影潘不在此地並大舉向我們進軍也許只是時間問題罷了。', `FemaleText_loc7`='Los hozen de la montaña están arrasando. Ten cuidado cuando viajes por los caminos.$b$bEs cuestión de tiempo que se den cuenta de que el Shadopan no está aquí y decidan saquearnos.' WHERE `ID`=64436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번은 그루멀 시장에서 요상하게 생긴 동물을 봤습니다. 등이 굽은 진위처럼 생겼는데, 성질이 나쁘고 "아옳옳옳" 비슷한 소리를 내더군요.$b$b아마 그루멀 하나가 해변에서 데리고 올라왔겠지요.', `MaleText_loc4`='有一次，在土地精集市我看到了一个奇怪的生物。看上去像一只蹲着的锦鱼人，但是他脾气很坏，口中叫嚷着“呒啊噶呒啊呒啊噶呒噶呒噶”。$b$b我猜是某个土地精把他从海岸线那里带过来的。', `MaleText_loc5`='我有一次在咕嚕摩市集看到一個奇怪的生物。它看起來就像個彎下腰的錦魚人，但脾氣很差然後會說像「呣咯咯呣呣咯呣咯呣咯」的話。$b$b我想應該是有個咕嚕摩將它從海岸邊帶上來的。', `MaleText_loc7`='Una vez vi a una criatura extraña en El Bazar Grúmel. Parecía un jinyu encorvado, pero era violento y decía algo así como "Mrggmrmrgmgmgl".$b$bMe imagino que un grúmel lo traería de la costa.', `FemaleText_loc1`='한번은 그루멀 시장에서 요상하게 생긴 동물을 봤어요. 등이 굽은 진위처럼 생겼는데, 성질이 나쁘고 "아옳옳옳" 비슷한 소리를 내더군요.$b$b아마 그루멀 하나가 해변에서 데리고 올라왔겠지요.', `FemaleText_loc4`='有一次，在土地精集市我看到了一个奇怪的生物。看上去像一只蹲着的锦鱼人，但是他脾气很坏，口中叫嚷着“呒啊噶呒啊呒啊噶呒噶呒噶”。$b$b我猜是某个土地精把他从海岸线那里带过来的。', `FemaleText_loc5`='我有一次在咕嚕摩市集看到一個奇怪的生物。它看起來就像個彎下腰的錦魚人，但脾氣很差然後會說像「呣咯咯呣呣咯呣咯呣咯」的話。$b$b我想應該是有個咕嚕摩將它從海岸邊帶上來的。', `FemaleText_loc7`='Una vez vi a una criatura extraña en El Bazar Grúmel. Parecía un jinyu encorvado, pero era violento y decía algo así como "Mrggmrmrgmgmgl".$b$bMe imagino que un grúmel lo traería de la costa.' WHERE `ID`=64437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘은 이 길에 음영파가 전혀 다니지 않습니다. 나쁜 징조입니다.$b$b다음 사마귀 공격까지는 아직 몇 년이 남아 있거든요.', `MaleText_loc4`='影踪派最近并没有走过这条路。这可不太好。$b$b我们猜想还有几年的时间，才会遇到螳螂妖再次蜂拥而至。', `MaleText_loc5`='最近都沒有影潘來到這裡。這不會件好事。$b$b我們原本應該還有幾年才會碰到下一次的螳螂人入侵。', `MaleText_loc7`='Últimamente no vienen muchos miembros del Shadopan. Eso no puede ser bueno.$b$bSe suponía que aún quedaban unos años hasta el siguiente enjambre mántide.', `FemaleText_loc1`='요즘은 이 길에 음영파가 전혀 다니지 않아요. 나쁜 징조예요.$b$b다음 사마귀 공격까지는 아직 몇 년이 남아 있거든요.', `FemaleText_loc4`='影踪派最近并没有走过这条路。这可不太好。$b$b我们猜想还有几年的时间，才会遇到螳螂妖再次蜂拥而至。', `FemaleText_loc5`='最近都沒有影潘來到這裡。這不會件好事。$b$b我們原本應該還有幾年才會碰到下一次的螳螂人入侵。', `FemaleText_loc7`='Últimamente no vienen muchos miembros del Shadopan. Eso no puede ser bueno.$b$bSe suponía que aún quedaban unos años hasta el siguiente enjambre mántide.' WHERE `ID`=64438;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 정말 설탕같이 달콤한 분이네요.', `FemaleText_loc4`='你真是太好了，$n。', `FemaleText_loc5`='你就像蜜糖般可愛，$n。', `FemaleText_loc7`='¡Eres una dulzura, $n!' WHERE `ID`=64439;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 제게 이렇게 친절히 대해주시다니!', `FemaleText_loc4`='亲爱的，你对我太好了！', `FemaleText_loc5`='甜心，你對我真好!', `FemaleText_loc7`='¡Encanto, eres muy amable!' WHERE `ID`=64440;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 제 생각을 해주시다니 정말 멋진 분이시네요.', `FemaleText_loc4`='你还想着我真是太好了，亲爱的。', `FemaleText_loc5`='你能想起我真好，親愛的。', `FemaleText_loc7`='Es muy amable de tu parte el pensar en mí.' WHERE `ID`=64441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 짙은 붉은색이네요! 제가 이 색깔 제일 좋아하는 거 모르셨죠?', `FemaleText_loc4`='颜色真红！你不知道这是我最喜欢的颜色吗？', `FemaleText_loc5`='真是鮮紅!你不知道那是我最愛的顏色嗎?', `FemaleText_loc7`='¡Es tan rojo! ¿Sabes que es mi color favorito?' WHERE `ID`=64442;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 정말 아름다워요. 제가 보석을 좋아하는 걸 어떻게 아셨어요?', `FemaleText_loc4`='哦天啊，太漂亮了。你怎么知道我喜欢珠宝？', `FemaleText_loc5`='喔我的天，這真美麗。你怎麼知道我喜歡珠寶?', `FemaleText_loc7`='¡Oh, cielos, qué preciosidad! ¿Cómo sabías que me gustaban las joyas?' WHERE `ID`=64443;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, $n 님. 여자는 루비가 아무리 많아도 모자란답니다.', `FemaleText_loc4`='谢谢你，$n。女孩子总是觉得自己少一颗红宝石。', `FemaleText_loc5`='謝謝你，$n。一個女孩永遠不會嫌紅寶石太多。', `FemaleText_loc7`='Gracias, $n. Una chica nunca tiene suficientes rubíes.' WHERE `ID`=64444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이러시지 않아도 되는데! 그래도 기뻐요.', `FemaleText_loc4`='你可以不用这样的！但是我很高兴你这么做了。', `FemaleText_loc5`='你不用這麼做的!但我很高興你有這麼做。', `FemaleText_loc7`='¡No tenías por qué! Pero me alegra que lo hicieras.' WHERE `ID`=64445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 달콤하네요. 당신 혹시 설탕 인형 아니에요?', `FemaleText_loc4`='你不就是一个$G甜心:宝贝;吗？', `FemaleText_loc5`='你豈不是個蜜糖$G帥哥:派;嗎?', `FemaleText_loc7`='Eres una auténtica monada.' WHERE `ID`=64446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어머, 부끄러워라. 제가 해달라는 거 다 해주시네요!', `FemaleText_loc4`='胡说什么，你要宠坏我了！', `FemaleText_loc5`='噢糟糕，你快把我寵壞了!', `FemaleText_loc7`='¡Ay, me estás malcriando!' WHERE `ID`=64447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t$n|1이;가; |cFFF00000|Hspell:121881|h[호박석 감옥]|h|r에 갇혔습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t$n被困在一个|cFFF00000|Hspell:121881|h[琥珀监牢]|h|r里！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_uncutgemnormal.blp:20|t$n被困在一個|cFFF00000|Hspell:121881|h[琥珀監獄]|h|r之中!', `MaleText_loc7`='|TInterfaceIconsinv_misc_uncutgemnormal.blp:20|t¡Una |cFFF00000|Hspell:121881|h[Prisión de ámbar]|h|r ha atrapado a $n!' WHERE `ID`=64448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 감정은 잘 모르겠지만, 고마워요.', `FemaleText_loc4`='我是一个不善于表达自己感情的人，不过谢谢你。', `FemaleText_loc5`='我不是很擅長這種情感啊、情緒之類的東西。但謝謝你。', `FemaleText_loc7`='No soy muy buena con todo el tema de los sentimientos, pero gracias.' WHERE `ID`=64449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $c님. 저를 신경 써주시다니.', `FemaleText_loc4`='谢谢你，$c。你让我感到很荣幸。', `FemaleText_loc5`='謝謝你，$c。你讓我很光榮。', `FemaleText_loc7`='Gracias, $c. Me honras.' WHERE `ID`=64450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $n 님. 제가 빚을 졌네요.', `FemaleText_loc4`='谢谢你，$n。我欠你一个人情。', `FemaleText_loc5`='謝謝你，$n。我欠你一次。', `FemaleText_loc7`='Gracias, $n. Estoy en deuda contigo.' WHERE `ID`=64451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님은 너무 친절한 분이시네요. 제가 어떻게 이걸 다 갚아야 할까요?', `FemaleText_loc4`='你太好了，$c。我该怎么报答你呢？', `FemaleText_loc5`='你人太好了，$c。我該怎麼回報你?', `FemaleText_loc7`='Eres demasiado amable, $c. ¿Cómo podré devolverte esto?' WHERE `ID`=64452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$c님, 이런 거 안 해주셔도 되는데... 고마워요.', `FemaleText_loc4`='不用了，$c。是我应该谢谢你才对。', `FemaleText_loc5`='你不用這樣的，$c。謝謝你。', `FemaleText_loc7`='No tenías por qué, $c. Gracias.' WHERE `ID`=64453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 적들을 추적하고 나면 여자라도 배가 고파진답니다. 고마워요.', `FemaleText_loc4`='一直在追那些敌人，我一个女孩子家还真是有点饿了。谢谢你。', `FemaleText_loc5`='獵殺了那麼多敵人，女孩確實是肚子餓了。謝謝你。', `FemaleText_loc7`='A una chica le entra hambre tras matar a todos esos enemigos. Gracias.' WHERE `ID`=64454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 이거 맛있어 보이네요. 감사합니다, $c님.', `FemaleText_loc4`='噢，看起来很好吃。谢谢你，$c。', `FemaleText_loc5`='喔，這看起來太好吃了。謝謝你，$c。', `FemaleText_loc7`='Oh, tiene una pinta deliciosa. Gracias, $c.' WHERE `ID`=64455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음... 전사는 항상 강력함을 유지해야 한답니다. 고마워요.', `FemaleText_loc4`='嗯……战士应该要学会保持自己的体力。谢谢你。', `FemaleText_loc5`='唔...一個戰士確實需要維持體力。謝謝你。', `FemaleText_loc7`='Mmm... Una guerrera necesita conservar las fuerzas. Gracias.' WHERE `ID`=64456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나 경계를 늦추지 말아야 하지만, 저는 항상 뜨거운 음식을 먹으려고 잠깐씩 쉰답니다!', `FemaleText_loc4`='警戒是一刻也不能掉以轻心的，但我始终会腾出时间吃顿热饭的！', `FemaleText_loc5`='我永遠不會放鬆警戒，但也永遠樂於休息吃頓大餐!', `FemaleText_loc7`='La vigilia nunca termina, ¡pero siempre puedo tomarme un descanso para una comida caliente!' WHERE `ID`=64457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 먹어도 됩니까? 무슨 맛인지는 먹어봐야만 알 테니까...', `MaleText_loc4`='我可以吃吗？我想只有一个办法才知道答案……', `MaleText_loc5`='我能吃它嗎?我想只有一個方法能證實...', `MaleText_loc7`='¿Me la puedo comer? Imagino que sholo hay un modo de shaberlo...' WHERE `ID`=64458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 의식이 확장하고 있어. 자네가 찾는 이에게 집중하게. 어린 왕자... 새끼 사자. 시간과 공간을 넘어... 영혼의 눈을 뜨게. 그가 보이나?', `MaleText_loc4`='你的感知力正在延伸。集中默念你要找的人。那位小王子——那头小狮子。他穿越时空……打开你的心眼。看见他了吗？', `MaleText_loc5`='你的意識正逐漸擴張。集中精神，專心想著你要尋找的那個人。那位小王子，年幼的雄獅。他就在這裡，對吧?跋涉過時間和空間...張開你的靈魂之眼。你看見他了嗎?', `MaleText_loc7`='Tu conciencia se expande. Concéntrate en lo que estás buscando. El Príncipe, el joven león. Viaja a través del tiempo y el espacio... Abre los ojos de tu alma. ¿Lo ves?' WHERE `ID`=64459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 이걸 먹으면 제 다음 예언에 집중하는 데 도움이 좀 되겠군요.', `MaleText_loc4`='嗯……这会给我一些提示，以便我专注于下一次预测。', `MaleText_loc5`='唔，下次預測時，這讓我有東西保持專注了。', `MaleText_loc7`='Mmm. Eshto me permitirá concentrarme para mi shiguiente predicción.' WHERE `ID`=64460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멋진 선물이군요, $n 님. 감사합니다.', `MaleText_loc4`='这是很整洁，$n。谢谢你，哥们。', `MaleText_loc5`='真素不錯$n。感謝，兄弟。', `MaleText_loc7`='¡Eshto me gushta mucho, $n! Graciash.' WHERE `ID`=64461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 전 이거 정말 좋아합니다. 감사합니다.', `MaleText_loc4`='我非常喜欢这里，$n。谢谢你。', `MaleText_loc5`='我很喜歡這郭，$n。感謝。', `MaleText_loc7`='Me encanta, $n. Graciash.' WHERE `ID`=64462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 생각해주셔서 고맙군요. 아무도 안 그러는데 말입니다.', `MaleText_loc4`='谢谢你这么为我着想，哥们。只有你才会这样想着我。', `MaleText_loc5`='謝謝你想到我，兄弟。都沒有其他人想到。', `MaleText_loc7`='Graciash por penshar en mí, colega. Nadie másh lo hace.' WHERE `ID`=64463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 친절하신 $G신사:숙녀;분이시군요... *딸꾹*!', `MaleText_loc4`='你太好了，$G女士:先生;……嗝！', `MaleText_loc5`='你真素個好$G女人:人;...嗝!', `MaleText_loc7`='Qué amabilidad, $gsheñorita:sheñor;... ¡hip!' WHERE `ID`=64464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사과 진짜 맛있어 보이는군요. 감사합니다!', `MaleText_loc4`='这些苹果看起来很好吃。谢谢！', `MaleText_loc5`='這蘋果看起來很好粗。謝謝!', `MaleText_loc7`='¡Eshta manzana parece deliciosha! ¡Graciash!' WHERE `ID`=64465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사과 제게 주시는 겁니까? 감사합니다!', `MaleText_loc4`='这个苹果是给我的吗？谢谢！', `MaleText_loc5`='給我的蘋果?謝謝!', `MaleText_loc7`='¿Una manzana para mí? ¡Graciash!' WHERE `ID`=64466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 뭡니까? 토마토인가요? 석류인가? 아! 사과구나!', `MaleText_loc4`='那是什么？西红柿？石榴吗？噢！是苹果！', `MaleText_loc5`='那是什摸?番茄?石榴?喔!是蘋果。', `MaleText_loc7`='¿Qué esh esho? ¿Un tomate? ¿Una granada? ¡Oh! ¡Una manzana!' WHERE `ID`=64467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불타올라라!', `MaleText_loc4`='燃烧！', `MaleText_loc5`='燃燒吧!', `MaleText_loc7`='¡Arde!' WHERE `ID`=64468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 그거 사과입니까? 사과야, 날 만나니까 좋지?.. *딸꾹*!', `MaleText_loc4`='那是苹果吗？见到我你一定很高兴……嗝！', `MaleText_loc5`='那素蘋果嗎?你一定很喜歡見到我...嗝!', `MaleText_loc7`='¿Esho esh una manzana? Debesh alegrarte de verme... ¡hip!' WHERE `ID`=64469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그거 맛있어 보이는군요. 여기 있는 제 차가운 술과 잘 어울릴 겁니다.', `MaleText_loc4`='哦，它看起来很好吃。它搭配我的冷饮一起吃会很不错。', `MaleText_loc5`='喔那看起來真好粗。一定很配我的冷飲。', `MaleText_loc7`='Ooooh, parece deliciosho. Irá perfecto con eshta bebida fría.' WHERE `ID`=64470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언자가 미래를 보려면 음식이 필요하지요. 감사합니다!', `MaleText_loc4`='一个神谕者需要食物才能预见未来。谢谢！', `MaleText_loc5`='先知需要食物來預測未來。謝謝!', `MaleText_loc7`='Un oráculo neceshita comida para ver el futuro. ¡Graciash!' WHERE `ID`=64471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 가족이 이 요리를 만들어 먹곤 했습니다... 지금은 모두 하늘로 가버렸지만, 이 요리는 아직도 좋아합니다.', `MaleText_loc4`='我家族以前常常做这个……现在他们都走了，但是我还是喜欢这道菜。', `MaleText_loc5`='我家裡常做這個...他們都不在了，但我還是喜歡這道菜。', `MaleText_loc7`='Mi familia solía preparar esho... ya no eshtán, pero a mí me shigue encantando eshte plato.' WHERE `ID`=64472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이러지 않아도 되는데. 고맙네그려.', `MaleText_loc4`='哦，你不用这样的。谢谢。', `MaleText_loc5`='喔，你不用這樣的。謝謝。', `MaleText_loc7`='Oh, no tenías por qué. Gracias.' WHERE `ID`=64473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 난 줄 게 없구먼. 아, 어쨌든 고맙네.', `MaleText_loc4`='但是我没有什么可以给你的。哪里哪里，还是要谢谢你。', `MaleText_loc5`='但我都沒給你任何東西。啊，總之謝謝你了。', `MaleText_loc7`='Pero yo no tengo nada para ti. Vaya porra. Gracias de todos modos.' WHERE `ID`=64474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 친절한 $r 양반이구먼.', `MaleText_loc4`='你真是太好了，$r。', `MaleText_loc5`='你真是太好了，$r。', `MaleText_loc7`='Eso es extremadamente amable, $r.' WHERE `ID`=64475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 중 몇 개는 쓸 수 있겠구먼. 고맙네.', `MaleText_loc4`='我猜我可以用它们中的一个。谢谢你。', `MaleText_loc5`='我想這些會有用的。謝謝你。', `MaleText_loc7`='Algún uso le daré. Gracias.' WHERE `ID`=64476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 멋진 건 나한테 과분하다네. 그런데 자네가 가지라고 우길 것 같군.', `MaleText_loc4`='我不值得拥有这么好的东西。我想你会坚持。', `MaleText_loc5`='我配不上這麼好的東西，但我想你會堅持要我收下吧。', `MaleText_loc7`='No merezco nada tan bueno. Pero imagino que insistirás.' WHERE `ID`=64477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거절하지는 않겠지만, 나한테 이러지 않아도 되는데... 고맙네, $r 양반.', `MaleText_loc4`='我不能拒绝，但你可以。谢谢，$r。', `MaleText_loc5`='我不能拒絕，但你真的不用這樣的。謝謝你，$r。', `MaleText_loc7`='No puedo decir que, pero no debiste hacerlo. Gracias, $r.' WHERE `ID`=64478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들이 이런 깃털을 찾는 걸 좋아하곤 했다네.', `MaleText_loc4`='我的儿子之前喜欢收集这些羽毛。', `MaleText_loc5`='以前，我的兒子很喜歡去找這些羽毛。', `MaleText_loc7`='A mi hijo le solía entusiasmar encontrar estas plumas.' WHERE `ID`=64479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 깃털을 보니 아들 생각이 나는군. 고맙네. $r 양반.', `MaleText_loc4`='这些羽毛让我回忆起我的儿子。谢谢你，$r。', `MaleText_loc5`='這些羽毛喚起許多關於我兒子的回憶。謝謝你，$r。', `MaleText_loc7`='Estas plumas me traen recuerdos de mi hijo. Gracias, $r.' WHERE `ID`=64480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들은 이 깃털을 정말 좋아했다네. 하늘과 같은 색인 푸른색이어서 말이지. 항상 내게 언젠가 자기도 날아갈 거라고 말했지.', `MaleText_loc4`='我的儿子很喜欢这些羽毛，因为它们像天空一样蓝。他总是说，他总有一天要飞翔。', `MaleText_loc5`='我的兒子喜歡這些羽毛，因為他們像天一樣藍。他總說有一天他要在天上飛。', `MaleText_loc7`='Mi hijo amaba estas plumas porque eran azules como el cielo. Siempre decía que un día volaría.' WHERE `ID`=64481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $n. 내 아들도 이걸 보고 싶어할 텐데 말이야.', `MaleText_loc4`='谢谢你，$n。我儿子原本喜欢见到这个。', `MaleText_loc5`='謝謝你，$n。我的兒子看到這個會高興的。', `MaleText_loc7`='Gracias, $n. A mi hijo le habría gustado ver esto.' WHERE `ID`=64482;
