UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 외로운 늙은이에게 신경 써줘서 고맙네, $n.', `MaleText_loc4`='谢谢你为一个孤独的老人着想，$n。', `MaleText_loc5`='謝謝你有心想到一個孤單的老人，$n。', `MaleText_loc7`='Gracias por pensar en un viejo solitario, $n.' WHERE `ID`=64485;
