UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 이거 나 주는 건가? 고맙네.', `MaleText_loc4`='哦，嚯嚯，这是给我的吗？谢谢你。', `MaleText_loc5`='喔呵呵，這是給我的?謝謝你。', `MaleText_loc7`='Oh, jo, jo, ¿esto es para mí? Gracias.' WHERE `ID`=64487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌을 행복하게 만드는 법을 잘 알고 있군. 고맙네.', `MaleText_loc4`='你的确知道怎么让一个熊猫人开心。谢谢。', `MaleText_loc5`='你真的知道該怎麼讓一個熊貓人開心。謝謝。', `MaleText_loc7`='Sabes bien cómo hacer feliz a un pandaren. Gracias.' WHERE `ID`=64488;
