UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호랑이 스테이크라고? 내가 제일 좋아하는 요리지! 어떻게 알았나?', `MaleText_loc4`='虎肉排？这是我的最爱！你怎么知道的？', `MaleText_loc5`='老虎肉排?我最喜歡吃了!你怎麼知道?', `MaleText_loc7`='¿Filete de tigre? ¡Es mi preferido! ¿Cómo lo sabías?' WHERE `ID`=64494;
