UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여자들이 어떤 선물을 좋아하는지 아주 잘 아시네요! 고마워요!', `FemaleText_loc4`='你当然知道如何讨女孩喜欢！谢谢！', `FemaleText_loc5`='你真了解如何討女孩歡心!謝啦!', `FemaleText_loc7`='¡Tú sí que sabes cómo dorar la píldora a una chica! ¡Gracias!' WHERE `ID`=64498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제게 잘 보이려고 하시는 것 같은데... 그렇죠, $r님? 잘하시는 거예요!', `FemaleText_loc4`='你想得到我的青睐，不是吗，$r？嗯，对你来说有好处！', `FemaleText_loc5`='你想要討好我嗎，$r?你好棒!', `FemaleText_loc7`='Quieres caerme bien, ¿eh, $r? ¡Bien por ti!' WHERE `ID`=64499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저세상으로 보내 주마!', `MaleText_loc4`='死亡！拥抱你的命运！', `MaleText_loc5`='死吧!擁抱你的命運!', `MaleText_loc7`='¡Acepta tu destino y muere!' WHERE `ID`=64500;
