UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 너무나 좋은 선물이에요. 고마워요.', `FemaleText_loc4`='你给我的礼物真是太好了。谢谢你。', `FemaleText_loc5`='你剛剛給我的禮物真是棒極了。謝謝你。', `FemaleText_loc7`='Es un regalo excelente el que me has dado. Gracias.' WHERE `ID`=64505;
