UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골의 불 앞에서 멀쩡하지 못할 것이다!', `MaleText_loc4`='你无法经受住野牛人的烈焰！！', `MaleText_loc5`='你無法抵抗揚古之火!', `MaleText_loc7`='¡No puedes enfrentarte al fuego de los yaungol!' WHERE `ID`=64509;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 소용돌이치는 안갯국을 직접 만드신 거예요? 맛있는 냄새가 나네요.', `FemaleText_loc4`='你会自己做迷雾汤吗？它闻起来很香。', `FemaleText_loc5`='那碗繚繞薄霧湯是你自己煮的嗎?它聞起來好香。', `FemaleText_loc7`='¿Has hecho tú esa sopa de niebla espiral? Huele de maravilla.' WHERE `ID`=64510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅과 함께 태워 주마!', `MaleText_loc4`='你们会与你们的土地一起被燃焦！', `MaleText_loc5`='你們會和你們的土地一起燃燒!', `MaleText_loc7`='¡Arderás junto con tus tierras!' WHERE `ID`=64511;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 마음을 얻는 두 가지 방법이 있는데, 그게 뭔지 아세요? 하나는 제 시장의 우수고객이 돼 주시는 거고, 또 하나는 제게 소용돌이치는 안갯국을 주시는 거랍니다!', `FemaleText_loc4`='有两种方式可以赢得吉娜的芳心，你知道是什么吗？一个是成为我市集的常客，另一个是迷雾汤！', `FemaleText_loc5`='你知道有兩種方法可以打動吉娜的心嗎?一個是當我市集的好顧客，另一個就是繚繞薄霧湯!', `FemaleText_loc7`='¿Sabes que hay dos maneras de conquistar a Gina? Una, siendo un buen cliente en su mercado, y la otra, ¡la sopa de niebla espiral!' WHERE `ID`=64512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 정말 맛있어 보이네요. 고마워요, $n 님.', `FemaleText_loc4`='噢，看起来很好吃。谢谢你，$n。', `FemaleText_loc5`='喔，那看起來很美味。謝謝你，$n。', `FemaleText_loc7`='Oh, tiene una pinta exquisita. Gracias, $n.' WHERE `ID`=64513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멋진 선물이군요, $r님. 감사합니다.', `MaleText_loc4`='这个礼物太好了，$r。谢谢你。', `MaleText_loc5`='那真是個超棒的禮物，$r。謝謝你。', `MaleText_loc7`='¡Es un regalo excelente, $r! Gracias.' WHERE `ID`=64514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 친절을 제가 어떻게 다 갚아 드려야 할지...', `MaleText_loc4`='我怎样才能报答你的好意呢？', `MaleText_loc5`='我要怎樣才能回報你的好?', `MaleText_loc7`='¿Cómo podré devolverte tanta amabilidad?' WHERE `ID`=64515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 이제 보니 나쁜 $r|1이;가; 아니었군요.', `MaleText_loc4`='嘿，你毕竟还不是那么糟糕，$r。', `MaleText_loc5`='唷，你真是個好傢伙，$r。', `MaleText_loc7`='Ey, no al final no eres mala gente, $r.' WHERE `ID`=64516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 좋아지기 시작하는군요, $r님.', `MaleText_loc4`='我开始喜欢上你了，$r。', `MaleText_loc5`='我開始喜歡上你了，$r。', `MaleText_loc7`='Estás empezando a gustarme, $r.' WHERE `ID`=64517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이렇게 잘해주시면 제가 채소를 정말 많이 키울 수 있는 비법을 알려 드릴지도 모릅니다.', `MaleText_loc4`='你一直这样的话，我也只好告诉你我种出这么多蔬菜的秘密。', `MaleText_loc5`='保持下去，我或許會跟你分享我種出這麼多蔬菜的秘密。', `MaleText_loc7`='Sigue así y tendré que compartir mi secreto para lograr que crezcan tantas verduras.' WHERE `ID`=64518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있어 보이는 요리군요. 직접 만드신 것이었으면 좋겠습니다.', `MaleText_loc4`='这烤肉看起来很好吃。但愿是你自己做的。', `MaleText_loc5`='這烤肉看起來美味極了。我希望是你親手做的。', `MaleText_loc7`='Este asado parece delicioso. Espero que lo hayas hecho tú.' WHERE `ID`=64519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에서 직접 만든 요리보다 좋은 건 없지요! 맛이 좋습니다!', `MaleText_loc4`='一点也不像是自己烤的！好吃！', `MaleText_loc5`='家庭烤肉最棒了!好吃!', `MaleText_loc7`='¡Nada como un asado casero! ¡Delicioso!' WHERE `ID`=64520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 이제 우리 땅이다!', `MaleText_loc4`='现在这是我们的土地！', `MaleText_loc5`='現在這是我們的土地了!', `MaleText_loc7`='¡Ahora esta tierra nos pertenece!' WHERE `ID`=64521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어머니께서 항상 이 꽃엔 행운이 깃들어 있다고 하셨습니다.', `MaleText_loc4`='我妈妈总是跟我说，这些花象征好运。', `MaleText_loc5`='我媽媽總是跟我說這些花能帶來好運。', `MaleText_loc7`='Mi madre me decía siempre que estas flores traían suerte.' WHERE `ID`=64522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 야운골의 땅이다!', `MaleText_loc4`='这些是野牛人的土地！', `MaleText_loc5`='這些是揚古的土地!', `MaleText_loc7`='¡Estas son tierras yaungol!' WHERE `ID`=64523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 행운이 깃든 꽂을 나눠주시다니 정말 멋진 분이시군요.', `MaleText_loc4`='你真是太好，送如此幸运的花给我。', `MaleText_loc5`='你真是太好了，跟我分享這幸運花。', `MaleText_loc7`='Es extremadamente amable de tu parte compartir esa flor de la suerte conmigo.' WHERE `ID`=64524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 땅은 우리가 접수하겠다!', `MaleText_loc4`='我们宣布你们的土地归我们所有！', `MaleText_loc5`='我們要將你們的土地據為己有!', `MaleText_loc7`='¡Nos apropiaremos de estas tierras!' WHERE `ID`=64525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 이는 제가 왜 그렇게 꽃을 좋아하는지 물어볼지도 모르겠군요. 하지만 그게 바로 접니다. 이 대지의 아름다움을 감상하는 그 모습 말입니다.', `MaleText_loc4`='有些人可能会问我为什么这么喜欢花。我只是在欣赏这片土地的美丽。', `MaleText_loc5`='有些人或許會問，為什麼我這麼喜歡花?那是因為我喜歡這片美麗的土地。', `MaleText_loc7`='Algunos pueden preguntarse por qué me gustan tanto las flores. Solo aprecio la belleza de esta tierra.' WHERE `ID`=64526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 정말 이 선물 제게 주시는 거죠? 고맙습니다!', `FemaleText_loc4`='你确定，$n？哇，谢谢你！', `FemaleText_loc5`='你確定嗎，$n?哇喔，謝謝你!', `FemaleText_loc7`='¿Seguro, $n? Guau, ¡gracias!' WHERE `ID`=64527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다시 바닷바람을 쐬니 기분이 좋군.', `MaleText_loc4`='啊，再次把盐放进旧皮草的感觉很好。', `MaleText_loc5`='啊啊，讓這身老皮再泡泡海水真不錯。', `MaleText_loc7`='Aah, es agradable volver a notar la sal en el pelaje.' WHERE `ID`=64528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이런. 답례로 드릴 게 아무것도 없네요! 에이...', `FemaleText_loc4`='噢，不好，我没有给你任何东西作为回报！嘘……', `FemaleText_loc5`='喔不，我沒有回禮可以給你!噗...', `FemaleText_loc7`='¡Oh, no! ¡Y yo no tengo nada para ti!' WHERE `ID`=64529;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님은 정말 좋은 분이시네요. 당신 같은 분을 알아서 정말 기분이 좋아요.', `FemaleText_loc4`='是的，太好了，$n。我很高兴认识像你这样的人。', `FemaleText_loc5`='你真好，$n。我很高興能夠認識像你這樣的人。', `FemaleText_loc7`='Qué amable eres, $n. Me alegra conocer a alguien como tú.' WHERE `ID`=64530;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 우리 아빠가 항상 이 고양이 조각상엔 행운이 깃들어 있다고 말해주셨답니다!', `FemaleText_loc4`='噢，我的爸爸总是说，这些小猫图形是象征好运！', `FemaleText_loc5`='喔，我老爸總是說這些小貓像很好運!', `FemaleText_loc7`='Oh, ¡mi padre siempre decía que estás pequeñas figuras de gatos traían suerte!' WHERE `ID`=64531;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비취는 정말 상서로운 물건이죠. 모르셨죠? 제게 주셔서 고맙습니다.', `FemaleText_loc4`='翡翠是好运的象征，你不知道吗？谢谢你把它送给我。', `FemaleText_loc5`='玉會帶來極佳的好運，你不知道嗎?謝謝你把這送我。', `FemaleText_loc7`='El jade trae mucha suerte, ¿lo sabías? Gracias por dármelo.' WHERE `ID`=64532;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비취를 몸에 지니는 건 악령을 쫓아내는 부적을 지니는 것과 같답니다. 이 작은 고양이 조각상을 제게 주셔서 너무 감사해요! 이게 저를 안전하게 지켜줄 거예요. 왠지 그런 느낌이 드네요.', `FemaleText_loc4`='拥有一小块翡翠就可以辟邪。非常感谢你送我这只小猫咪！我知道，它会保佑我平安。', `FemaleText_loc5`='擁有一小塊玉就像擁有一個能阻擋惡靈的護符。非常謝謝你送我這隻玉貓!它能保佑我平安，我很肯定。', `FemaleText_loc7`='Contar con un pequeño fragmento de jade es como tener un amuleto que te guarde de los malos espíritus. ¡Gracias por este gatito! Me mantendrá a salvo, estoy segura.' WHERE `ID`=64533;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $n 님. 정말 친절도 하셔라.', `FemaleText_loc4`='噢，你真是太客气了，$n。', `FemaleText_loc5`='喔，你真是太好了，$n。', `FemaleText_loc7`='¡Oh, qué amable eres, $n!' WHERE `ID`=64534;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 저를 생각해주시다니. 정말 친절한 분이시네요.', `FemaleText_loc4`='你真是太好了，还能想到我。', `FemaleText_loc5`='你能想起我真是太好了。', `FemaleText_loc7`='Qué amable, te has acordado de mí.' WHERE `ID`=64535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 고향을 빼앗겼다! 그러니 너희 땅을 빼앗아야겠다!', `MaleText_loc4`='我们的家园被人侵占了！所以我们要抢占你们的！', `MaleText_loc5`='我們的家被偷走了!所以我們將奪走你們的!', `MaleText_loc7`='¡Nos robaron nuestros hogares, así que nosotros robaremos los suyos!' WHERE `ID`=64536;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심장지에 있는 이들 중에서 제게 이런 선물을 주시는 건가요? 정말 영광이라는 말 말고는 어떻게 말해야 할지조차도 모르겠어요.', `FemaleText_loc4`='在汇风岭的所有这些人之中，你把它送给我了吗？我甚至不知道该说什么，这是我莫大的荣幸。', `FemaleText_loc5`='在中央平原的所有人之中，你要把這送給我?除了我感到非常光榮，我都不知道該說什麼了。', `FemaleText_loc7`='De toda la gente de los Cultivos Florecientes, ¿me la das a mí? No sé ni qué decir, excepto que me honra.' WHERE `ID`=64537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='死亡！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡Muere!' WHERE `ID`=64538;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 고양이 좋아하는 거 어떻게 아셨어요?', `FemaleText_loc4`='你是怎么知道我喜欢猫的？', `FemaleText_loc5`='你怎麼知道我喜歡貓?', `FemaleText_loc7`='¿Cómo sabías que me gustaban los gatos?' WHERE `ID`=64539;
