UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오우우, 치 치 주는 멋진 선물이다! 고마워!', `MaleText_loc4`='噢，不错礼物的送给吱吱！谢谢你！', `MaleText_loc5`='喔，很適合奇奇的好禮物!謝謝!', `MaleText_loc7`='¡Oh, bonito regalo para Chee Chee! ¡Gracias!' WHERE `ID`=64541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 준다고? 안 그래도 되는데, 고마워!', `MaleText_loc4`='给吱吱的吗？你可以不用这样的！', `MaleText_loc5`='給奇奇?你好客氣!', `MaleText_loc7`='¿Para Chee Chee? ¡No deberías!' WHERE `ID`=64542;
