UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치 치 깃털 주는 거야? 고마워.', `MaleText_loc4`='给吱吱的羽毛吗？谢谢你。', `MaleText_loc5`='給奇奇的羽毛?謝謝。', `MaleText_loc7`='¿Pluma para Chee Chee? Gracias.' WHERE `ID`=64544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장... 이거 너무 멋지다. 고마워.', `MaleText_loc4`='老板……这个真不错。谢谢你。', `MaleText_loc5`='老闆...這真是很好。謝謝。', `MaleText_loc7`='$gJefe:Jefa;... está muy bien. Gracias.' WHERE `ID`=64545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장 진짜 멋지다. 고마워!', `MaleText_loc4`='你太酷了，老板。谢谢你！', `MaleText_loc5`='你很酷，老闆。謝謝!', `MaleText_loc7`='Tú mola bastante, $gjefe:jefa;. ¡Gracias!' WHERE `ID`=64546;
