UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 우릴 막을 수 없다!', `MaleText_loc4`='你不能阻止我们！', `MaleText_loc5`='你無法阻止我們!', `MaleText_loc7`='¡No puedes detenernos!' WHERE `ID`=64548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새로 차지한 밭에서 일을 할 노예가 또 생겼군!', `MaleText_loc4`='我们新牧场的又一个奴隶！', `MaleText_loc5`='我們的農地又多了一個新奴隸!', `MaleText_loc7`='¡Otro esclavo para nuestros nuevos campos!' WHERE `ID`=64549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 야운골에게 도전하느냐?', `MaleText_loc4`='你胆敢挑战野牛人吗？', `MaleText_loc5`='你膽敢挑戰揚古!?', `MaleText_loc7`='¿Osas desafiar a los yaungol?' WHERE `ID`=64550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그분을 봤다네.$B$B바다의 여신, 마쭈 님 말일세.$B$B내 인생 중 최악의 폭풍이 불던 날이었지. 어린 데다가 경험도 부족했던 때였고. 나는 배 밖으로 떨어졌고, 모든 게 새카매졌고, 이제 끝장이라는 생각이 들었다네.$B$B그러다가 마쭈 님께서 내 앞에 나타나셨지. 여름날의 오후처럼 선명한 모습으로 말일세. 얼마나 아름다운지 자네는 상상도 못할 걸세. 목에는 조개껍데기로 만든 목걸이가, 그리고 엉덩이에는 진주로 엮은 줄이 둘려 있었지. 마쭈 님은 미소를 지으시며 가녀린 팔을 내게 내미셨네.$B$B그 다음 내가 기억하는 건, 멍멍이가 나를 업고 수면 밖으로 다시 나왔고, 선원들이 나를 끌어올려 배에 태운 거라네. 멍멍이는 처음 보는 바다사자였다네. 선원들이 그러는데 갑자기 어디선가 나타났다고 하더군. 하지만 나는 어디서 나타났는지 안다네.', `MaleText_loc4`='你知道吗，我看见她了。$B$B玛祖。海之女神。$B$B我人生中最猛烈的风暴。我那时候年轻，而且缺乏经验。我从船上跌进海里。到处都是漆黑一片，我完蛋了。$B$B然后她出现在我面前，像夏天的午后一样清新。那样的美丽是你无法想象的，她的脖子上戴着贝壳，臀部挂着一串串的珍珠。她微笑着并且伸出纤细的手臂。$B$B然后我只记得，狗把我背在背上，并且船员拉我上了船。之前从未见过他，船员都说不知道他是从哪里冒出来的。但我知道他从哪里来。', `MaleText_loc5`='我看見她了，你知道的。$B$B瑪祖，海上的女神。$B$B我一生碰到過最險惡的風暴。我還很年輕而且經驗不足。我落入了海中。四周變得一片漆黑，我原本死定了。$B$B然後她在我面前出現，就像夏天午後般清晰。美麗到你無法想像，貝殼圍繞著她的頸子，成串的珍珠在她的腰間。她露出微笑並伸出了她修長的手臂。$B$B我所記得的下一件事就已經回到海面上，老狗背著我，然後船員把我拉回到船上。以前從來沒看過他，船員說他不知是從哪冒出來的。但是我知道他是從哪來的。', `MaleText_loc7`='La vi, ¿sabes?$B$BA Mazu. La diosa del mar.$B$BLa peor tormenta de mi vida. Era joven e inexperto. Me caí por la borda. Todo se puso oscuro. Era mi fin.$B$BEntonces apareció ante mí, clara como una tarde de verano. Con una belleza que no te puedes imaginar, conchas alrededor del cuello y ristras de perlas en las caderas. Sonrió y extendió su esbelto brazo.$B$BLo siguiente que recuerdo es que Perro me sostenía en su lomo en la superficie y la tripulación me subió a bordo. No lo había visto nunca; la tripulación dijo que había salido de la nada. Pero yo sé de dónde salió.' WHERE `ID`=64551;
