UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 치 치와 가장 친한 친구가 되었습니다. 치 치에게 당신의 농장 일을 도와줄 수 있는지 물어봐도 될 겁니다.', `MaleText_loc4`='你和吱吱已经成了挚友。也许你可以和他聊聊，看他是否愿意为农场帮帮忙。', `MaleText_loc5`='你和奇奇是最好的朋友。也許你可以和他談談，看他是否願意來農場幫忙。', `MaleText_loc7`='Chee Chee es tu mejor amigo. Tal vez puedas pedirle que ayude en la granja.' WHERE `ID`=64567;
