UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 엘라는 가장 친한 친구가 되었습니다. 이제 엘라는 농부 윤의 일을 기꺼이 도와줄 겁니다.', `MaleText_loc4`='你和艾拉已经成了挚友。也许她会愿意帮助农夫老愚一阵子。', `MaleText_loc5`='你和艾拉是最好的朋友。也許你可以和她談談，看她是否願意幫農夫尹。', `MaleText_loc7`='Ella es tu mejor amiga. Tal vez puedas pedirle que ayude en la granja.' WHERE `ID`=64572;
