UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 피시와 가장 친한 친구가 되었습니다. 피시가 당신의 농장 일을 돕게 하려면 더 많이 친해져야 합니다.', `MaleText_loc4`='你和玉儿已经成了挚友。凭借她对动物的了解，她或许能帮你解决农场里的问题。', `MaleText_loc5`='你和小魚是最好的朋友。以她對動物的知識，她大概可以幫農場相當大的忙。', `MaleText_loc7`='Pez es tu mejor amiga. Con sus conocimientos sobre animales, sería de gran ayuda en la granja.' WHERE `ID`=64576;
