UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 당신과 농부 펑은 가장 친한 친구가 되었습니다. 펑은 태양노래 농장 일을 기꺼이 도와줄 것입니다.', `MaleText_loc4`='不知不觉之中，你和农夫老方已经成了挚友。他或许乐意帮助日歌农场。', `MaleText_loc5`='不知怎地，你和農夫老豐成了最好的朋友。他或許會願意到日歌農莊幫忙。', `MaleText_loc7`='Por alguna razón, el granjero Fung es tu mejor amigo. Tal vez puedas pedirle que ayude en el Rancho Cantosol.' WHERE `ID`=64580;
