UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 지나는 가장 친한 친구가 되었습니다. 지나는 모든 일에 참견하기를 좋아하니 틀림없이 농장에 들러서 일을 도와줄 겁니다.', `MaleText_loc4`='你和吉娜已经成了挚友。她乐于插手别人的事，所以，毫无疑问她会在农场上花些时间的。', `MaleText_loc5`='你和吉娜是最好的朋友。她很愛管每個人的閒事，所以無疑地她會花點時間來田裡幫忙。', `MaleText_loc7`='Gina es tu mejor amiga. Le encanta meter las narices en los asuntos de los demás, así que seguro que ayudará en la granja.' WHERE `ID`=64584;
