UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 하오한의 우정이 돈독하니 농사꾼 연합의 대표인 그가 기꺼이 손을 빌려줄 게 틀림 없습니다.', `MaleText_loc4`='当你和郝瀚成为挚友时，毫无疑问他这个阡陌客的首领会向你伸出援手给予帮助。', `MaleText_loc5`='由於你和好漢有著如此深厚的友誼，無疑地這位耕者工會的頭頭會願意過來幫個忙。', `MaleText_loc7`='Cuando se tiene una amistad como la que tú tienes con Haohan, no hay duda de que el propio líder del gremio de labradores se pasaría a echar una mano.' WHERE `ID`=64588;
