UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 주정뱅이 조구는 함께 수확기를 여러 번 보냈습니다. 이런 조구 말고 누가 당신 농장에 도움이 되겠습니까?', `MaleText_loc4`='你和醉鬼贾古已经一起经历了那么多收获季。除了他还有谁会是你农场的一笔财富？', `MaleText_loc5`='你和『酒鬼』酒骨一起度過了這麼多耕季。除了他還會有誰能成為你農場重要的一份子?', `MaleText_loc7`='Jogu el Ebrio y tú habéis pasado juntos muchos ciclos de cosecha. ¿Quién sino él sería de gran ayuda en tu granja?' WHERE `ID`=64592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 늙은 힐포우는 많이 친해졌습니다.', `MaleText_loc4`='你和老农山掌是哥们了。', `MaleText_loc5`='你和老丘爪是夥伴。', `MaleText_loc7`='El viejo Zarpa Collado es tu colega.' WHERE `ID`=64593;
