UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 늙은 힐포우는 좋은 친구가 되었습니다.', `MaleText_loc4`='你和老农山掌已经成了好友。', `MaleText_loc5`='你和老丘爪是好朋友。', `MaleText_loc7`='El viejo Zarpa Collado es un buen amigo.' WHERE `ID`=64595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 늙은 힐포우를 위해 많은 것을 도와줬으니 지금 그가 당신을 보고 싶어할 겁니다. 늙은 힐포우에게 농장 일을 도와달라고 부탁하십시오.', `MaleText_loc4`='你为老农山掌做了这么多，这个老家伙可能正在怀念有你陪伴的时光。你应该叫他来农场帮助。', `MaleText_loc5`='你為老丘爪做了那麼多事，那個老傢伙現在大概在想念你的陪伴。你該去請他到農莊幫忙。', `MaleText_loc7`='Has hecho mucho por el viejo Zarpa Collado; probablemente, ese vejete estará echando de menos tu compañía ahora mismo.' WHERE `ID`=64596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 쇼는 많이 친해졌습니다.', `MaleText_loc4`='你和阿烁是哥们了。', `MaleText_loc5`='你和阿秀是夥伴。', `MaleText_loc7`='Sho es tu colega.' WHERE `ID`=64597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 쇼는 친구가 되었습니다.', `MaleText_loc4`='你和阿烁是朋友了。', `MaleText_loc5`='你和阿秀是朋友。', `MaleText_loc7`='Sho es tu amigo.' WHERE `ID`=64598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 쇼는 친한 친구가 되었습니다.', `MaleText_loc4`='你和阿烁已经成了好友。', `MaleText_loc5`='你和阿秀是好朋友。', `MaleText_loc7`='Sho es un buen amigo.' WHERE `ID`=64599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 쇼에게 당신의 가치를 증명했습니다. 쇼는 당신이 필요하면 뒤를 봐주겠다고 했습니다. 그런 일 대신 당신 곡식을 지켜달라고 부탁할 수도 있습니다.', `MaleText_loc4`='你已经向阿烁证明了你自己。她说如果你在任何时候需要帮助，她都会义不容辞。你可以请她来帮你照看庄稼。', `MaleText_loc5`='你已經對阿秀證明自己。她的確說當你需要時她會幫你撐腰。撐腰是不用，但你可以叫她幫你看顧農作物。', `MaleText_loc7`='Has demostrado tu valía a Sho. Dijo que te guardaría las espaldas si lo necesitaras alguna vez. En lugar de eso, podrías pedirle que vigilara tus cultivos.' WHERE `ID`=64600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 티나는 많이 친해졌습니다.', `MaleText_loc4`='你和迪娜是哥们了。', `MaleText_loc5`='你和蒂娜是夥伴。', `MaleText_loc7`='Tina es tu colega.' WHERE `ID`=64601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 티나는 친구가 되었습니다.', `MaleText_loc4`='你和迪娜是朋友了。', `MaleText_loc5`='你和蒂娜是朋友。', `MaleText_loc7`='Tina es tu amiga.' WHERE `ID`=64602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 티나는 좋은 친구가 되었습니다.', `MaleText_loc4`='你和迪娜已经成了好友。', `MaleText_loc5`='你和蒂娜是好朋友。', `MaleText_loc7`='Tina es una buena amiga.' WHERE `ID`=64603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티나는 당신이 가장 친한 친구라고 합니다. 당신 농장에 기꺼이 들르고 싶어할 겁니다.', `MaleText_loc4`='按照迪娜的说法，你和她已经成了挚友。她或许会很乐意造访你的农场。', `MaleText_loc5`='蒂娜說的，你是她最好的朋友。她大概會想要去你的田裡參觀一下。', `MaleText_loc7`='Según Tina, eres su mejor $gamigo:amiga;. Seguramente le encantará visitar tu granja.' WHERE `ID`=64604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람칼날들이 갇힌 동료를 구하러 갑니다!', `MaleText_loc4`='风刃火速前往救助他们被困的盟友！', `MaleText_loc5`='風刃衝去援助他們受困的盟友!', `MaleText_loc7`='¡Las espadas del viento corren en ayuda de su aliado atrapado!', `FemaleText_loc1`='바람칼날들이 갇힌 동료를 구하러 갑니다!', `FemaleText_loc4`='风刃火速前往救助他们被困的盟友！', `FemaleText_loc5`='風刃衝去援助他們受困的盟友!', `FemaleText_loc7`='¡Las espadas del viento corren en ayuda de su aliado atrapado!' WHERE `ID`=64605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔네, 젊은 친구.', `MaleText_loc4`='欢迎，我年轻的朋友。', `MaleText_loc5`='歡迎，我年輕的朋友。', `MaleText_loc7`='Te doy la bienvenida, joven.' WHERE `ID`=64606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투스카르가 어떻게 판다리아에 왔습니까?', `MaleText_loc4`='海象人如何来到潘达利亚的？', `MaleText_loc5`='一個巨牙海民是怎麼來到潘達利亞的?', `MaleText_loc7`='¿Cómo ha llegado un colmillarr hasta Pandaria?', `FemaleText_loc1`='투스카르가 어떻게 판다리아에 왔죠?', `FemaleText_loc4`='海象人如何来到潘达利亚的？', `FemaleText_loc5`='一個巨牙海民是怎麼來到潘達利亞的?', `FemaleText_loc7`='¿Cómo ha llegado un colmillarr hasta Pandaria?' WHERE `ID`=64607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이야기를 할 때가 됐다네, 내 $c 친구여. 게와 바다의 이야기, 등에 나무가 자란 거북의 이야기를...', `MaleText_loc4`='我的$c朋友，是时候谈些其他事情了。比如螃蟹和海洋，海龟和树木……', `MaleText_loc5`='是時候了，我的$c朋友，該聊聊其他事情。關於螃蟹、海洋、烏龜和樹...', `MaleText_loc7`='Mi $gquerido amigo:querida amiga; $c, ha llegado el momento de hablar de otras cosas. De cangrejos, de los mares, de tortugas a lo lejos...' WHERE `ID`=64608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이야기를 할 때가 됐다네, 내 $r 친구여. 호젠과 그루멀의 이야기, 내 배가 꼬르륵거리는 이야기를...', `MaleText_loc4`='我的$r朋友，是时候谈些其他事情了。比如猢狲和土地精，还有我的肚子饿了……', `MaleText_loc5`='是時候了，我的$r朋友，該聊聊其他事情。關於猴人、咕嚕摩，和我的胃是如何隆隆地響...', `MaleText_loc7`='Mi $gquerido amigo:querida amiga; $r, ha llegado el momento de hablar de otras cosas. De monos, de grúmel, de sombreros con forma de conos...' WHERE `ID`=64609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이야기를 할 때가 됐다네, 내 작은 친구여. 모구와 트롤의 이야기, 강의 트롤 진위의 이야기를...', `MaleText_loc4`='我的小朋友，是时候谈些其他事情了。比如魔古族和巨魔，或者锦鱼人的河流通行费……', `MaleText_loc5`='是時候了，我的小朋友，該聊聊其他事情。關於魔古、食人妖，和錦魚人河流過路費...', `MaleText_loc7`='Mi $gpequeño amigo:pequeña amiga;, ha llegado el momento de hablar de otras cosas. De mogu, de trols, de jinyu y de gnolls...' WHERE `ID`=64610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이야기를 할 때가 됐다네, 내 바보 친구여. 설인과 야크의 이야기, 불시에 습격하는 상어 떼의 이야기를...', `MaleText_loc4`='我的傻朋友，是时候谈些其他事情了。比如雪人和牦牛，或者随机的鲨鱼袭击事件……', `MaleText_loc5`='是時候了，我憨厚的朋友，該聊聊其他事情。關於雪人、犛牛，和鯊魚的隨機攻擊...', `MaleText_loc7`='Mi $gcurioso amigo:curiosa amiga;, ha llegado el momento de hablar de otras cosas. De yetis, de yaks, y de muchas cosas más...' WHERE `ID`=64611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀라지 마세요, $n 님.$B$B모구와의 싸움을 돕기 위해서 꿈속에서 제 모습을 투사하고 있는 거랍니다.', `FemaleText_loc4`='不要惊慌，$n。$B$B我将梦中的自我投射在这里，以便帮助你对抗魔古族。', `FemaleText_loc5`='不須驚慌，$n。$B$B我把我夢境中的自身投射於此以協助你抵抗魔古。', `FemaleText_loc7`='No te preocupes, $n.$B$BEstoy proyectándome en sueños aquí para ayudarte en tus esfuerzos contra los mogu.' WHERE `ID`=64612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 아름답지 않나? 몇 년 전에 낚아 올린 거라네. 마치 그분을 닮았지... 시간 나면 조각상에 대해 물어보게나.', `MaleText_loc4`='她真漂亮，不是吗？几年前它被捞出来，它看起来就像她一样……改天问我关于它的事情。', `MaleText_loc5`='她很美，不是嗎?我在幾年前釣起來的，它看起來就跟她一模一樣...改天跟我聊聊那件事。', `MaleText_loc7`='Preciosa, ¿verdad? La pesqué hace unos años. Es igual que ella... Pregúntame sobre eso algún día.' WHERE `ID`=64613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다.', `MaleText_loc4`='没关系。', `MaleText_loc5`='算了，別在意。', `MaleText_loc7`='Déjalo.', `FemaleText_loc1`='됐어요.', `FemaleText_loc4`='没关系。', `FemaleText_loc5`='算了，別在意。', `FemaleText_loc7`='Déjalo.' WHERE `ID`=64614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $r님! 오늘은 어떤 음악을 듣고 싶으세요?', `FemaleText_loc4`='你好，$r！今天你想听什么音乐？', `FemaleText_loc5`='哈囉，$r!你今天想聽什麼樣的音樂啊?', `FemaleText_loc7`='¡Hola, $r! ¿Qué selección musical querrías escuchar hoy?' WHERE `ID`=64615;
