UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람군주 멜자라크가 동료가 행동 불가 상태가 된 것을 감지하고 풀어 줍니다!', `MaleText_loc4`='风领主梅尔加拉克察觉到一个盟友丧失了能力，并释放了他们！', `MaleText_loc5`='風領主瑪爾加拉克查覺到有個盟友被癱瘓而釋放了他們。', `MaleText_loc7`='¡El señor del viento Mel''jarak nota que un aliado está incapacitado y lo libera!' WHERE `ID`=64625;
