UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구우 클라우드스트라이크의 영혼을 정화하셨군요. 음영파의 감사를 받아 주십시오.', `MaleText_loc4`='你洗礼了古·穿云的灵魂，影踪派感谢你。', `MaleText_loc5`='你淨化了古·雲擊的靈魂，這影潘感謝你。', `MaleText_loc7`='Has purificado el alma de Gu Golpe Celeste. El Shadopan te lo agradece.' WHERE `ID`=64629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스노우드리프트 사부께서 당신이 싸움에서 좀처럼 꺾이지 않는다며 칭찬하시더군요.', `MaleText_loc4`='雪流大师高度赞扬你在战斗中的表现。', `MaleText_loc5`='雪迅大師對於你在戰鬥中能與敵人對抗給予很高的評價。', `MaleText_loc7`='El maestro Ventisca Algente habla muy bien de tu forma de luchar.' WHERE `ID`=64630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 맹주님께서는 증오의 샤를 쫓아 장벽을 넘어 서쪽으로 가셨습니다. 부디 성공하시기를 바랍니다.', `MaleText_loc4`='祝踏岚领主已经出城墙向西追捕恨之煞。我希望他追捕顺利。', `MaleText_loc5`='塔蘭•祝大人已經往西方前進並越過長城去追捕仇恨之煞。我希望追捕行動進行地順利。', `MaleText_loc7`='Lord Taran Zhu viaja hacia el oeste, al otro lado de la muralla, para dar caza al Sha del odio. Espero que le vaya bien.' WHERE `ID`=64631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 음영파를 지배하던 샤의 힘이 약해졌습니다. 감사합니다.', `MaleText_loc4`='恨之煞不能再以我们的人民相威胁了，这多亏有你。我们感谢你。', `MaleText_loc5`='感謝你終止了煞對我們族人的控制。我們非常感激你。', `MaleText_loc7`='Gracias a ti, el sha ha perdido el control que ejercía sobre nuestro pueblo. Te lo agradecemos.' WHERE `ID`=64632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파를 위해 큰일을 하셨습니다, $p 님.', `MaleText_loc4`='你帮了影踪派一个大忙，$p。', `MaleText_loc5`='你幫了影潘一個大忙，$p。', `MaleText_loc7`='Has servido bien al Shadopan, $p.', `FemaleText_loc1`='음영파를 위해 큰일을 하셨습니다, $p 님.', `FemaleText_loc4`='你帮了影踪派一个大忙，$p。', `FemaleText_loc5`='你幫了影潘一個大忙，$p。', `FemaleText_loc7`='Has servido bien al Shadopan, $p.' WHERE `ID`=64633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님. 지켜보고 있었어요.', `FemaleText_loc4`='再次问候，$c。我一直在注视着你。', `FemaleText_loc5`='又見面了，$c。我一直在觀察著你。', `FemaleText_loc7`='Hola de nuevo, $c. Te he estado observando.' WHERE `ID`=64634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 대단한 용기를 보여 주셨습니다, $p 님. 음영파의 감사를 받아 주십시오.', `MaleText_loc4`='你很勇敢，$p。影踪派感谢你。', `MaleText_loc5`='你展現了偉大的勇氣，$p。影潘感謝你。', `MaleText_loc7`='Has demostrado un gran valor, $p. El Shadopan te lo agradece.', `FemaleText_loc1`='당신은 대단한 용기를 보여 주셨습니다, $p 님. 음영파의 감사를 받아 주십시오.', `FemaleText_loc4`='你很勇敢，$p。影踪派感谢你。', `FemaleText_loc5`='你展現了偉大的勇氣，$p。影潘感謝你。', `FemaleText_loc7`='Has demostrado un gran valor, $p. El Shadopan te lo agradece.' WHERE `ID`=64635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 무술 실력은 따를 자가 없군요. 배우고 싶은 것이 많습니다.', `MaleText_loc4`='你的武术技能无人能比。我还有很多想向你学习。', `MaleText_loc5`='你的武術技巧無人能及。我還有許多東西想向你學習。', `MaleText_loc7`='Tus artes marciales no tienen parangón. Me gustaría aprender muchas cosas de ti.', `FemaleText_loc1`='당신의 무술 실력은 따를 자가 없군요. 배우고 싶은 것이 많습니다.', `FemaleText_loc4`='你的武术技能无人能比。我还有很多想向你学习。', `FemaleText_loc5`='你的武術技巧無人能及。我還有許多東西想向你學習。', `FemaleText_loc7`='Tus artes marciales no tienen parangón. Me gustaría aprender muchas cosas de ti.' WHERE `ID`=64636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 진정 무술의 달인입니다. 이렇게 마주할 수 있어 영광입니다.', `MaleText_loc4`='你的确是武术格斗的高手。你的到来是我的荣幸。', `MaleText_loc5`='你是個不折不扣的武術戰鬥大師。你的光臨讓我倍感榮耀。', `MaleText_loc7`='Eres un ejemplo a seguir en las artes marciales. Me honras con tu presencia.', `FemaleText_loc1`='당신은 진정 무술의 달인입니다. 이렇게 마주할 수 있어 영광입니다.', `FemaleText_loc4`='你的确是武术格斗的高手。你的到来是我的荣幸。', `FemaleText_loc5`='你是個不折不扣的武術戰鬥大師。你的光臨讓我倍感榮耀。', `FemaleText_loc7`='Eres un ejemplo a seguir en las artes marciales. Me honras con tu presencia.' WHERE `ID`=64637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='슈는 우리에게 소중한 존재입니다. 슈를 찾아야 해요. 하지만 슈에게는 어린아이 같은 면이 있어서, 놀라게 해서는 안 됩니다.$B$B저는 명상을 통해 슈가 어디에 있는지, 그리고 어떻게 하면 잘 다가갈 수 있을지 알아내겠습니다. 참을성 있게 기다리세요.', `FemaleText_loc4`='舒对我们而言非常重要。我们需要找到他，但是他各方面更趋向于小孩子，所以我们绝不能用我们的方法吓唬他。$B$B我会想想他可能待的地方，以及怎么样接近他最合适。耐心等待，我的朋友。', `FemaleText_loc5`='舒對我們來說很重要。我們必須找到他，但是他像小孩一樣，所以我們接近時不能嚇到他。$B$B我將透過冥想來找出他身在何處，該如何和他接觸。有點耐心，我的朋友。', `FemaleText_loc7`='Shu es muy valioso para nosotros. Tenemos que encontrarlo, pero se comporta como un niño pequeño, así que no debemos asustarlo.$b$bMeditaré dónde puede estar y cuál es la mejor forma de acercarnos a él. Ten paciencia.' WHERE `ID`=64638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='슈를 대할 때는 성급하게 굴지 마세요. 하는 행동은 어린아이 같지만, 제법 나이도 많고 강력하답니다.', `FemaleText_loc4`='对涓流要有耐心。他的行为举止也许像个孩子，实际上却是古老而强大的生灵。', `FemaleText_loc5`='對舒有點耐心。他就像個小孩子，但他相當古老，也相當強大。', `FemaleText_loc7`='Ten paciencia con Shu. Actúa como un niño, pero es bastante mayor, y muy poderoso.' WHERE `ID`=64639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사괍니다! 신선한 사과 가져가십시오!', `MaleText_loc4`='卖苹果！卖新鲜的苹果！', `MaleText_loc5`='蘋果，來買新鮮的蘋果!', `MaleText_loc7`='¡Manzanas, compra manzanas!' WHERE `ID`=64640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡에서 가장 크고, 맛도 최고로 달콤하고, 모양도 제일 예쁜 사과입니다! 여기서 사가십시오!', `MaleText_loc4`='四风谷里最大、最多汁、最可爱的苹果！就在这里！', `MaleText_loc5`='峽谷裡最大、最多汁、最漂亮的蘋果!來這裡買喔!', `MaleText_loc7`='Las más grandes, jugosas y hermosas del valle. ¡Se venden aquí!' WHERE `ID`=64641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사과 사십시오, 하루에 사과 한 개면 사제도 필요 없습니다!', `MaleText_loc4`='来买苹果喽！每天都闻苹果香，不用牧师开药方！', `MaleText_loc5`='來買些蘋果吧!一天一顆蘋果，牧師遠離你!', `MaleText_loc7`='¡Compra manzanas! ¡Cada día una manzana es cosa sana!' WHERE `ID`=64642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니까... 잘 모르겠습니다만... 그냥 굴려버릴까요, 아니면 어떻게...?', `MaleText_loc4`='这么说，你不过是想……我不知道……滚着玩还是怎么样？', `MaleText_loc5`='所以，你是想...我不知道...把它一路滾回去嗎，還是怎麼處理?', `MaleText_loc7`='Entonces quieres... no sé... ¿llevártela rodando o algo así?' WHERE `ID`=64643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만... 지금 이게 움직이는 겁니까?', `MaleText_loc4`='等等……它在动？', `MaleText_loc5`='等等...它在動嗎?', `MaleText_loc7`='Espera... ¿Se está moviendo?' WHERE `ID`=64644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 그럼 됐습니다.', `MaleText_loc4`='好吧。', `MaleText_loc5`='好吧。', `MaleText_loc7`='De acuerdo.' WHERE `ID`=64645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 방금 무슨 일이 일어났는지 아시는 것 같습니다만?', `MaleText_loc4`='我猜你知道刚才发生了什么？', `MaleText_loc5`='我猜想你多少知道剛剛發生了什麼事?', `MaleText_loc7`='Supongo que sabrás algo de lo que acaba de pasar.' WHERE `ID`=64646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실... 아니, 됐습니다. 알고 싶지도 않습니다. 저는 제 낚싯줄이나 보러 가야겠습니다.', `MaleText_loc4`='其实，算了——我并不想知道。我要回去了。', `MaleText_loc5`='還是算了 - 我根本不想知道。我要回去顧我的釣線了。', `MaleText_loc7`='Mira, olvídalo. Ni siquiera quiero saberlo. Voy a volver a mis sedales.' WHERE `ID`=64647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피를 보게 해 주마.', `MaleText_loc4`='朋友，你要吃苦头了。', `MaleText_loc5`='你將會流血，老兄。', `MaleText_loc7`='Vas a sangrar, colega.' WHERE `ID`=64648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무리 발버둥을 쳐도 우리 잔달라를 막을 순 없다.', `MaleText_loc4`='朋友，你阻挡不了赞达拉人。', `MaleText_loc5`='你阻止不了贊達拉，老兄。', `MaleText_loc7`='No puedes detener a los Zandalari, colega.' WHERE `ID`=64649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘됐다. 내 랩터가 배고파하던 참이었거든.', `MaleText_loc4`='好。我的迅猛龙饿了。', `MaleText_loc5`='很好。我的迅猛龍餓了。', `MaleText_loc7`='Bien. Mi raptor tiene hambre.' WHERE `ID`=64650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 배신자 검은창이 아니라 잔달라를 상대하고 있는 것이다.', `MaleText_loc4`='你现在面对的是赞达拉人。而不是一些暗矛部族的叛徒。', `MaleText_loc5`='你現在面對的是贊達拉。而不是暗矛的叛徒。', `MaleText_loc7`='Ahora te enfrentas a los Zandalari, no a un traidor Lanza Negra.' WHERE `ID`=64651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 트롤을 잘못 건드렸다.', `MaleText_loc4`='你惹了不该惹的巨魔。', `MaleText_loc5`='你惹錯食人妖了。', `MaleText_loc7`='Te metes con los trols equivocados.' WHERE `ID`=64652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 편에 설지 정할 때는 잘 생각해야지.', `MaleText_loc4`='小心选择你的阵营，兄弟。', `MaleText_loc5`='小心選邊站啊，兄弟。', `MaleText_loc7`='Elige tu bando con cuidado, hermano.' WHERE `ID`=64653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 여기 묻어 버릴 테다.', `MaleText_loc4`='这里就是你的葬身之地。', `MaleText_loc5`='我們要把你埋在這裡。', `MaleText_loc7`='Te enterraremos aquí.' WHERE `ID`=64654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라는 부흥할 것이다.', `MaleText_loc4`='赞达拉人将会东山再起。', `MaleText_loc5`='贊達拉將會再次崛起。', `MaleText_loc7`='Los Zandalari nos alzaremos de nuevo.' WHERE `ID`=64655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 우릴 막지 못한다.', `MaleText_loc4`='朋友，你阻挡不了我们。', `MaleText_loc5`='你阻止不了我們，老兄。', `MaleText_loc7`='No nos detendrás, colega.' WHERE `ID`=64656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 마법의 맛을 봐라!', `MaleText_loc4`='让你尝尝赞达拉魔法的厉害！', `MaleText_loc5`='嚐嚐贊達拉的魔法!', `MaleText_loc7`='¡Prueba la magia Zandalari!' WHERE `ID`=64657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전율하라, 멍청한 것들아! 메뚜기왕이 깨어났다!', `MaleText_loc4`='颤抖吧，不知悔改的人们！蝗虫已经苏醒了！', `MaleText_loc5`='顫抖吧，蠢材們!暴虐蝗蟲已經甦醒!', `MaleText_loc7`='¡Tiemblen, insensatos! ¡La langosta ha despertado!' WHERE `ID`=64658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우그르러를!', `MaleText_loc4`='WHARRGARBL！！！', `MaleText_loc5`='哇啊嘎吧!!!', `MaleText_loc7`='¡¡¡UAARRGARBL!!!' WHERE `ID`=64659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 다음 전리품으로 만들어 주마.', `MaleText_loc4`='你将成为我下一个战利品。', `MaleText_loc5`='你將成為我下一個戰利品。', `MaleText_loc7`='Serás mi nuevo trofeo.' WHERE `ID`=64660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라는 옛날의 영광을 되찾을 것이다.', `MaleText_loc4`='赞达拉人将重建昔日的光辉岁月。', `MaleText_loc5`='贊達拉將會重振古法。', `MaleText_loc7`='Los Zandalari recuperaremos las antiguas tradiciones.' WHERE `ID`=64661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라와 모구를 모두 꺾을 순 없다!', `MaleText_loc4`='你无法打败联手的赞达拉巨魔和魔古族！', `MaleText_loc5`='你無法同時擊敗贊達拉和魔古!', `MaleText_loc7`='¡No puedes vencer a los Zandalari y a los mogu!' WHERE `ID`=64662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어으으으... <콜록> 메뚜기왕은 죽지 않았다! <콜록> <콜록>', `MaleText_loc4`='呃……<咳嗽>暴食蝗没事儿！<咳嗽><咳嗽>', `MaleText_loc5`='咳...<咳嗽>暴虐蝗蟲很好!<咳嗽><咳嗽>', `MaleText_loc7`='Uuuh... <tose> ¡La langosta está bien! <tose> <tose>' WHERE `ID`=64663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시가 부른다...', `MaleText_loc4`='卡拉克西召唤……', `MaleText_loc5`='卡拉西召喚...', `MaleText_loc7`='Los Klaxxi me llaman...' WHERE `ID`=64664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='갓 구운 빵 팔아요!', `FemaleText_loc4`='新鲜的面包啊！', `FemaleText_loc5`='新鮮麵包!', `FemaleText_loc7`='¡Pan fresco!' WHERE `ID`=64665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 물속에서도 별문제 없을 것 같네요. 계속 열심히 하세요.', `FemaleText_loc4`='看起来你在水中没什么不妥的啊。继续这样干。', `FemaleText_loc5`='看來你在水中沒什麼大礙。繼續保持好表現。', `FemaleText_loc7`='Parece que puedes apañártelas en el agua. Sigue así.' WHERE `ID`=64666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황제게가 최고랍니다. 달콤한 맛과 푸른 금빛 몸이 특징이죠.', `FemaleText_loc4`='全是关于那些君王蟹的事情。亲爱的，他们就是蓝色黄金。', `FemaleText_loc5`='帝王蟹才是最重要的。牠們是香甜的藍色黃金。', `FemaleText_loc7`='Lo importante son esos cangrejos emperador. Son un oro dulce y azul.' WHERE `ID`=64667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람군주 멜자라크가 원군을 부릅니다!', `MaleText_loc4`='风领主梅尔加拉克调遣援兵了！', `MaleText_loc5`='風領主瑪爾加拉克召喚增援!', `MaleText_loc7`='¡El señor del viento Mel''jarak pide refuerzos!' WHERE `ID`=64668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쑤다오 선장님이 원래 계약서에 있던 항로에서 한참이나 벗어나고 나서 여기에서 난파됐어요. 선장님은 우리를 속일 수 있을 거로 생각했나 봐요. 나 참!$B$B솔직히 말하면, 선장님이 그렇게 해줘서 우린 아주 고마워하고 있어요. 우리 중 하루를 대충 보내는 이들은 하나도 없거든요.', `FemaleText_loc4`='在闷水壶带我们偏离了原始的航向后，我们就在这里失事了。他以为能把我们当傻子耍。哈哈！$B$B说实话，我们很乐意看他尝试这么去做。我们每个人都不是“泛泛之辈”。', `FemaleText_loc5`='『濕佬』讓我們駛離原訂航線後，我們的船就在這裡沉沒了。他原本以為他能夠愚弄我們，哈!$B$B老實說，我們都很高興他至少有試過。我們沒有一個人是那種想要「輕鬆過一天」的。', `FemaleText_loc7`='Naufragamos aquí cuando Aguado nos desvió de nuestra ruta original. Creyó que podía jugárnosla. ¡Ja!$B$BA decir verdad, nos alegramos de que lo intentara. Ninguno de nosotros es amante del "trabajo fácil".' WHERE `ID`=64669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕골 시장에 오신 것을 환영해요, $r님.', `FemaleText_loc4`='欢迎来到半山市集，$r。', `FemaleText_loc5`='歡迎來到半丘市集，$r。', `FemaleText_loc7`='$gBienvenido:Bienvenida; al Mercado del Alcor, $r.' WHERE `ID`=64670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나 공정한 가격에 거래되는 언덕골 시장에 오신 걸 환영해요!', `FemaleText_loc4`='欢迎来到半山市集，这里的价格一直很公道！', `FemaleText_loc5`='歡迎來到價錢最公道的半丘市集!', `FemaleText_loc7`='Te doy la bienvenida al Mercado del Alcor, en el que los precios siempre son justos.' WHERE `ID`=64671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오랜만이네요, $n 님. 다시 돌아오셔서 반가워요.', `FemaleText_loc4`='好久不见了，$n。欢迎回来。', `FemaleText_loc5`='好久不見，$n。歡迎回來。', `FemaleText_loc7`='Cuánto tiempo sin vernos, $n. Bien $ghallado:hallada;.' WHERE `ID`=64672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 마실 거라도 가져다 드릴까요?', `MaleText_loc4`='你需要喝点什么，$r？', `MaleText_loc5`='我能給你弄點喝的東西嗎，$r?', `MaleText_loc7`='¿Podría ponerte algo de beber, $r?' WHERE `ID`=64673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘을 뭘 마시고 싶으십니까?', `MaleText_loc4`='你今天想喝点什么，$n？', `MaleText_loc5`='你今天想要喝什麼，$n?', `MaleText_loc7`='¿Qué te gustaría beber hoy, $n?' WHERE `ID`=64674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 농사를 지으면 목이 많이 마르지 않습니까?', `MaleText_loc4`='干着农活肯定让你很渴吧，$n？', `MaleText_loc5`='種田讓人感到口很乾吧，$n?', `MaleText_loc7`='Labrar debe de dar muchísima sed, ¿eh, $n?' WHERE `ID`=64675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 도전하겠습니다.', `MaleText_loc4`='我要向你挑战。', `MaleText_loc5`='我向你挑戰。', `MaleText_loc7`='Te desafío.', `FemaleText_loc1`='당신에게 도전하겠어요.', `FemaleText_loc4`='我要向你挑战。', `FemaleText_loc5`='我向你挑戰。', `FemaleText_loc7`='Te desafío.' WHERE `ID`=64676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='셋! 둘! 하나! 시작!', `MaleText_loc4`='3！2！1！开始！', `MaleText_loc5`='3...2...1...開始!', `MaleText_loc7`='3... 2... 1... ¡A LUCHAR!' WHERE `ID`=64677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상상도 못할 일이 일어났다. 테라모어 공성 작전이 실패했다.', `MaleText_loc4`='不可思议的事情发生了——我们对塞拉摩的围攻失败了。', `MaleText_loc5`='難以置信的事情發生了:我們對塞拉摩的進攻失敗了。', `MaleText_loc7`='Ha ocurrido lo imposible: el asedio de Theramore ha fracasado.' WHERE `ID`=64678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누들스! 양념 그렇게 많이 치지 말라고 했잖아!', `FemaleText_loc4`='米线！我告诉你不要放这么多调料嘛！', `FemaleText_loc5`='麵麵!我告訴過你不要加太多調味料!', `FemaleText_loc7`='¡Fideos! ¡Te dije que no te pasaras con las especias!' WHERE `ID`=64679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 누들스. 국물엔 뭘 넣을 거지?', `FemaleText_loc4`='喔喔，米线，你在汤里放的什么啊？', `FemaleText_loc5`='嘩麵麵，你在湯裡加了什麼東西?', `FemaleText_loc7`='Vaya, Fideos, ¿qué pones en la sopa?' WHERE `ID`=64680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으음... 국물 맛이 끝내주는군. 잘했어, 누들스!', `FemaleText_loc4`='嗯。这汤味道不错。干得好，米线！', `FemaleText_loc5`='嗯嗯，這湯喝起來很美味。做得好，麵麵!', `FemaleText_loc7`='Mmm. La sopa está deliciosa. Bien hecho, Fideos.' WHERE `ID`=64681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시작할 준비는 되었습니까? 실력을 보여 주십시오.', `MaleText_loc4`='这么说，你准备开始了？让我们看看你有什么能耐。', `MaleText_loc5`='所以，你準備好要開始了嗎?讓我們見識見識你有多少斤兩。', `MaleText_loc7`='¿Todo listo para comenzar? Veamos qué puedes ofrecer.' WHERE `ID`=64682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='出发！', `MaleText_loc5`='我們開始吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='가요!', `FemaleText_loc4`='出发！', `FemaleText_loc5`='我們開始吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=64683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 우리의 비상 대책이다. 자네 임무는 테라모어 섬에 침투하는 것이다.', `MaleText_loc4`='应急计划由你前去执行。你的任务是混进塞拉摩岛。', `MaleText_loc5`='你就是緊急應變計畫。你的任務是潛入塞拉摩島。', `MaleText_loc7`='Ustedes son el plan B. Su misión es infiltrarse en Isla Theramore.' WHERE `ID`=64684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 장벽에 오신 것을 환영해요, $c님.$B$B자, 이제 사마귀들을 처치해버리자고요!', `FemaleText_loc4`='欢迎来到我的地盘，$c。$B$B现在，让我们教训教训这些螳螂妖！', `FemaleText_loc5`='歡迎來到我的長城，$c。$B$B現在讓我們踢爆螳螂人的屁股!', `FemaleText_loc7`='$gBienvenido:Bienvenida; a mi muro, $c.$B$B¡Ahora, vamos a machacar a esos mántides!' WHERE `ID`=64685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아쉽군. 언제나 중심을 잡아야 하네. 이 땅에서 살아남으려면 내면의 조화가 반드시 필요하네. 어서, 다시 한번 해 보게! 인내는 판다렌의 미덕이네.', `MaleText_loc4`='啊，只差一点。你得守住本心。要在这里生存下去，平和的心态是关键。来，再试一次！耐心也是熊猫人的美德。', `MaleText_loc5`='啊，就差一點。可是你必須保持在中央。內心的和諧會是你在這塊大地上生存的關鍵。來吧，我們再試一次!耐心是熊貓人的美德。', `MaleText_loc7`='Ah, casi. Tienes que CENTRARTE. La armonía interior es crucial para sobrevivir en esta tierra. ¡Probemos de nuevo!' WHERE `ID`=64686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃을 중앙에 있게 해야 합니다!', `MaleText_loc4`='让火花保持在中间位置！', `MaleText_loc5`='讓火花保持在中心!', `MaleText_loc7`='¡Sigue concentrándote!' WHERE `ID`=64687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관문분쇄자의 시야에서 벗어나십시오.', `MaleText_loc4`='不要被攻城车发现。', `MaleText_loc5`='不要進入石毀車的視線範圍之內。', `MaleText_loc7`='Aléjate del objetivo del demoledor.' WHERE `ID`=64688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠이 얼굴에 달라붙었습니다! 떨어뜨리려면 뛰어오르십시오!', `MaleText_loc4`='你面前有一只猢狲！赶紧跳开，摆脱它！', `MaleText_loc5`='有個猴人在你臉上!跳躍來把它甩掉!', `MaleText_loc7`='¡Tienes un hozen en la cara! ¡Salta para quitártelo de encima!' WHERE `ID`=64689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오 이런! 위급한 상황 때문에 자네 결의가 굳어졌군. 내 할 일은 끝난 것 같네.', `MaleText_loc4`='天呐！急迫的形势坚定了你的决心。我在这儿的任务已经完成了。', `MaleText_loc5`='喔!新的危機加深了你的決心。我想我的工作已經大功告成了。', `MaleText_loc7`='¡Vaya! Un nuevo apremio ha reforzado tu determinación. Creo que aquí terminó mi trabajo.' WHERE `ID`=64690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사 시나리오에 참여하는 사람은 용맹 점수를 획득할 수 있다오. 또, 양조사와 다니면서 발견하는 진기한 물품은 모두 가져도 좋소.', `MaleText_loc4`='参加酒仙场景战役的人可赢得勇气。要是你在与酒仙一同冒险时发现任何罕见物品，尽管将其收入囊中！', `MaleText_loc5`='參與釀酒大師事件的人將獲得勇氣。如果你在和釀酒大師冒險途中發現任何稀有的物品，那些都是你的!', `MaleText_loc7`='Aquellos que participen en las gestas de los maestros cerveceros obtendrán valor. Y si encuentras un objeto raro mientras vives aventuras con un maestro cervecero, ¡puedes quedártelo!' WHERE `ID`=64691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 가장 큰 양조장은 네 바람의 계곡에 있는 스톰스타우트 양조장이라오. 모험을 원한다면 거기부터 가 보는 게 좋을 거요.$B$B양조사들은 천성이 떠돌이인지라 온 세상을 떠돌며 귀한 재료를 찾거나 새로운 술을 연구한다오.$B$B그런 양조사들은 보통 시나리오에서 만날 수 있지.$B$B양조사 츄는 "녹옥 마을" 시나리오에서 적을 막고 있다오.$B$B양조사 보는 "웅가 잉구" 시나리오에서 열대의 맛을 찾고 있지.$B$B양조사 부프는 "맥주달 축제" 시나리오에서 이 계절을 만끽하고 있고, 양조사 블랜치는 "양조 폭풍" 시나리오에서 뭔가 충격적인 것을 만들고 있다오.', `MaleText_loc4`='潘达利亚地区最大的酿酒厂是四风谷的风暴烈酒酿造厂。如果你想冒险，可以从那里开始。$B$B酒仙实质上也是游荡者，并且他们经常四处闲逛，寻找稀有原料或调配新酒。$B$B这些酒仙通常会出现在独特的场景战役里。$B$B酒仙曲子在绿石村场景战役中抵御敌人。$B$B珀酒仙在盎迦猴岛场景战役中寻找热带配料。$B$B酒仙布夫在酿月祭场景战役中欢庆佳节，酒仙布兰琪在酝酿风暴场景战役中准备让人大吃一惊。', `MaleText_loc5`='潘達利亞中最大的酒坊就是四風峽中的風暴烈酒酒坊。如果你想要尋找探險的機會，從那裡開始應該不錯。$B$B釀酒大師們天性喜好到處遊蕩，到處都能發現他們漫遊於這片土地，尋找稀有的材料或調製新的酒。$B$B這樣的釀酒大師經常會在獨特的事件中被發現。$B$B釀酒大師祖在綠石村事件中抵禦敵人。$B$B釀酒大師阿波在仰加印古事件中尋找熱帶風味。$B$B釀酒大師布夫在酒月節事件中歡慶，而釀酒大師白蘭琪則在雷電佳釀事件中釀造某種驚人的東西。', `MaleText_loc7`='La mayor cervecería de Pandaria es la Cervecería del Trueno, en el Valle de los Cuatro Vientos. Puedes empezar por ahí si buscas aventuras.$b$bLos maestros cerveceros son errantes por naturaleza, así que viajan por todo el continente en busca de ingredientes raros o preparando nuevas recetas.$b$bTales maestros cerveceros suelen hallarse en gestas únicas.$b$bEl maestro cervecero Tzu se defiende del enemigo en la gesta de la Aldea Verdemar.$b$bEl maestro cervecero Bo busca sabores tropicales en la gesta de Unga Ingoo.$b$bEl maestro cervecero Boof celebra la temporada en la gesta del Festival de la Cerveza Lunar y, por último, la maestra cervecera Blanche cocina un plato chocante en Cervezas y Truenos.' WHERE `ID`=64692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사를 도우면 보상을 받을 수 있습니까?', `MaleText_loc4`='帮助酒仙有奖励吗？', `MaleText_loc5`='幫助釀酒大師們有獎賞嗎?', `MaleText_loc7`='¿Hay alguna recompensa por ayudar a los maestros cerveceros?', `FemaleText_loc1`='양조사를 도우면 보상을 받을 수 있나요?', `FemaleText_loc4`='帮助酒仙有奖励吗？', `FemaleText_loc5`='幫助釀酒大師們有獎賞嗎?', `FemaleText_loc7`='¿Hay alguna recompensa por ayudar a los maestros cerveceros?' WHERE `ID`=64693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움을 필요로 하는 양조사는 어디서 만날 수 있습니까?', `MaleText_loc4`='我在哪里可以找到可能需要帮助的酒仙？', `MaleText_loc5`='我能在哪裡找到需要協助的釀酒大師們呢?', `MaleText_loc7`='¿Dónde puedo encontrar a maestros cerveceros que necesiten ayuda?', `FemaleText_loc1`='도움을 필요로 하는 양조사는 어디서 만날 수 있나요?', `FemaleText_loc4`='我在哪里可以找到可能需要帮助的酒仙？', `FemaleText_loc5`='我能在哪裡找到需要協助的釀酒大師們呢?', `FemaleText_loc7`='¿Dónde puedo encontrar a maestros cerveceros que necesiten ayuda?' WHERE `ID`=64694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 어느 양조사를 돕고 싶소?', `MaleText_loc4`='你今天想帮助哪个酒仙？', `MaleText_loc5`='你今天想要協助哪一位釀酒大師?', `MaleText_loc7`='¿A qué maestro cervecero te gustaría ayudar hoy?' WHERE `ID`=64695;
