UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비했나? 아주 좋아! 날 따라오게.', `MaleText_loc4`='东西都弄到了吗？很好！跟我来', `MaleText_loc5`='東西都準備好了?很好!跟我來。', `MaleText_loc7`='¿Lo tienes todo? ¡Muy bien! Sígueme.' WHERE `ID`=64697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주달 축제 대기열에 등록합니다.', `MaleText_loc4`='排队等待酿月祭场景战役。', `MaleText_loc5`='加入酒月節佇列。', `MaleText_loc7`='Únete a la cola para el Festival de la Cerveza Lunar.', `FemaleText_loc1`='맥주달 축제 대기열에 등록합니다.', `FemaleText_loc4`='排队等待酿月祭场景战役。', `FemaleText_loc5`='加入酒月節佇列。', `FemaleText_loc7`='Únete a la cola para el Festival de la Cerveza Lunar.' WHERE `ID`=64698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿈결 맥주가 자네가 마음으로 구하는 걸 보여주려면, 먼저 자네가 내면의 조화를 이루어야 하네. 내가 그 방법을 알려주지.', `MaleText_loc4`='要想靠洄梦仙酒找到你想找的东西，那你必须保持祥和的心境。我来演示给你看。', `MaleText_loc5`='為了讓夢幻之釀可以展現出你要的答案，你的內心必須達到和諧的境地。我可以教你。', `MaleText_loc7`='Para que este brebaje de ensueño te muestre todo lo que buscas, debes alcanzar la armonía interior. Te mostraré cómo.' WHERE `ID`=64699;
