UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조사 블랜치는 폭풍이 몰아치는 와중에 폭발 맥주를 만들려고 하고 있소. 그런데 무시무시한 적이 방해를 하고 있다지.', `MaleText_loc4`='酒仙布兰彻努力在暴风雨中制造闪电陈酿，但是受到了一些难缠敌人的阻碍。', `MaleText_loc5`='釀酒大師白蘭琪正嘗試在一個風暴中央釀造閃電淡啤酒，但有些難以對付的敵人在防礙她。', `MaleText_loc7`='La maestra Clara está tratando de elaborar brebaje relámpago en mitad de una tormenta, pero unos enemigos formidables se están interponiendo en su camino.' WHERE `ID`=64707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 클락시베스로 돌아가서 의회를 만날 것이다. 코보크를 잘 돌봐라.', `MaleText_loc4`='我将返回卡拉克西维斯会见议会。请照顾好科沃克。', `MaleText_loc5`='我將會回到卡拉西斐斯和議會商議。請照顧好科沃克。', `MaleText_loc7`='Volveré a Klaxxi''vess para reunirme con el consejo. Por favor, cuida de Kovok.' WHERE `ID`=64708;
