UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿속이 |cFFFF0404|Hspell:124862|h[파멸의 환영]|h|r 으로 가득 찹니다!', `MaleText_loc4`='你的思想被|cFFFF0404|Hspell:124862|h[死亡幻象]|h|r感染了！', `MaleText_loc5`='你的神智遭到|cFFFF0404|Hspell:124862|h[死亡幻覺]|h|r的影響!', `MaleText_loc7`='¡|cFFFF0404|Hspell:124862|h[Visiones del final]|h|r invaden tu mente!', `FemaleText_loc1`='머릿속이 |cFFFF0404|Hspell:124862|h[파멸의 환영]|h|r 으로 가득 찹니다!', `FemaleText_loc4`='你的思想被|cFFFF0404|Hspell:124862|h[死亡幻象]|h|r感染了！', `FemaleText_loc5`='你的神智遭到|cFFFF0404|Hspell:124862|h[死亡幻覺]|h|r的影響!', `FemaleText_loc7`='¡|cFFFF0404|Hspell:124862|h[Visiones del final]|h|r invaden tu mente!' WHERE `ID`=64796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 아무도 없지요. 다만 "황금 연꽃"이라는 조직이 골짜기를 지키고 있습니다. 황금 연꽃의 대원은 천신들이 직접 뽑는데, 뽑히는 사람은 드뭅니다.$b$b저는 아주 어릴 때부터 골짜기에 대한 이야기를 들었지요. 그런 곳이 정말 존재한다니 믿어집니까?$b$b웅덩이에 대한 전설이 사실이라고 생각하십니까? 저도 직접 볼 수 있었으면 좋겠군요!', `MaleText_loc4`='几乎没人。由被称为“金莲教”的组织担任护卫。天神钦定金莲教人在锦绣谷担任警戒，但人数不多。$b$b打我小时候起，我就听过锦绣谷的故事。你相信这个地方真的存在吗？$b$b你认为圣池的传说是真的吗？我希望我可以亲眼见识一下！', `MaleText_loc5`='幾乎沒有人。它被一群被稱做「金蓮會」的人看守著。金蓮會的成員都是由天尊一個一個挑選出來，以維持對谷中的警戒，但被挑中的人並不多。$b$b我還小時就聽說過恆春谷的故事。你能相信這樣的地方真的存在嗎?$b$b你覺得那些池子的傳說會是真的嗎?真希望我能親眼去看看!', `MaleText_loc7`='Casi nadie. Lo guarda un grupo llamado "El Loto Dorado". Los miembros de El Loto Dorado son seleccionados directamente por los celestiales para proteger el valle, pero pocos son los elegidos.$b$bHe oído historias sobre el valle desde cachorro. ¿Crees que tal sitio realmente existe?$b$b¿Crees que la leyenda de las pozas es cierta? ¡Me encantaría comprobarlo en persona!' WHERE `ID`=64797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 대체 뭐지?', `MaleText_loc4`='那到底是什么东西？', `MaleText_loc5`='那天殺的是什麼東西?', `MaleText_loc7`='¿Qué demonios es eso?' WHERE `ID`=64798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 내 아들을 그렇게 쉽게 잡을 순 없지.', `MaleText_loc4`='噢！你不会那么容易抓到我的人。', `MaleText_loc5`='喔!可不能讓你那麼輕易地逮到我的孩子。', `MaleText_loc7`='¡Ah! No te vas a llevar a mi chico tan fácilmente.' WHERE `ID`=64799;
