UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋든 나쁘든, 총은 내가 들고 있다.', `MaleText_loc4`='好还是坏，我手里拿着枪我说了算。', `MaleText_loc5`='不論好壞，我是拿槍的那個人。', `MaleText_loc7`='Buen, malo, soy el tipo con el arma.' WHERE `ID`=64802;
