UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 사냥할 때는 당신의 그 반짝거리는 눈 좀 가리십시오. 위치가 드러나니까요.', `MaleText_loc4`='下次去打猎的时候，蒙住你那发光的眼睛。不然就会暴露你的位置。', `MaleText_loc5`='下次狩獵時，把你那雙閃亮的眼睛遮起來。那讓你穿幫了。', `MaleText_loc7`='La próxima vez que vayas a cazar, cúbrete ese ojo brillante tuyo. Te descubre.' WHERE `ID`=64808;
