UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 여기 다리 끝 근처일세.', `MaleText_loc4`='$p，在这边，桥尾附近。', `MaleText_loc5`='$p，在靠近橋的盡頭這裡。', `MaleText_loc7`='$p, por aquí, cerca del extremo del puente.' WHERE `ID`=64811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네.$B$B자네가 아니었으면 해내지 못했을 걸세.', `MaleText_loc4`='干得好。$B$B没有你，我们就无法成功。', `MaleText_loc5`='做得非常好。$B$B如果沒有你，我們根本不會成功。', `MaleText_loc7`='Excelente.$B$BNo lo habríamos conseguido sin ti.' WHERE `ID`=64812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 개의 사원을 지키면 위대한 천신회에서의 입지가 강화될 겁니다. 강력한 힘을 지닌 물건을 살 수 있게 되지요.$B$B게다가, 이 땅을 가장 큰 적에게서 지켜 내는 데 한 몫 할 수 있습니다.', `FemaleText_loc4`='保护这四座寺庙，你就会受到至尊天神的褒奖，得以购买功能强大的物品。$B$B此外，你还可以提供帮助，保护这片土地免受强敌的攻击。', `FemaleText_loc5`='藉著防衛四座寺廟，你將獲得聖獸天尊陣營的偉大聲望。你將獲得購買力量強大物品的資格。$B$B除此之外，你將能幫助這片土地抵禦一些我們最強大的敵人。', `FemaleText_loc7`='Al defender los cuatro templos, te ganarás una gran reputación ante los Augustos Celestiales. Se te concederá el privilegio de comprar objetos de gran poder.$B$BAdemás, estarás ayudando a defender esta tierra de algunos de nuestros mayores enemigos.' WHERE `ID`=64813;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옥룡 위론 님께서는 동쪽을 지키십니다. 불행히도 옥룡을 모시는 사원이 의심의 사에게 장악당했지요.$B$B지금도 사원에는 당신의 도움이 필요합니다. 우리는 샤를 물리치기 위해 최선을 다해야 합니다!', `FemaleText_loc4`='青龙玉珑，在东边担任警戒。很不幸，青龙寺已经落入疑之煞的魔掌。$B$B尽管如此，寺庙还是需要我们的帮助。我们必须尽全力将疑之煞困在港湾中！', `FemaleText_loc5`='『玉蛟』玉龍在東方守護著我們。不幸的是，她的寺廟被疑惑之煞攻佔。$B$B現在玉蛟寺需要我們的幫助。我們必須盡最大的努力將煞從寺中趕出!', `FemaleText_loc7`='Yu''lon, el Dragón de Jade, se ocupa de la vigilancia del este. Por desgracia, su templo ha caído ante el Sha de la duda.$B$BEl templo necesita nuestra ayuda urgentemente. ¡Tenemos que hacer todo lo que podamos para mantener a raya al sha!' WHERE `ID`=64814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='백호 쉬엔 님께서는 북방의 찬바람을 막아 주십니다.$B$B오늘 쉬엔 님께서는 이 땅에서 가장 강한 용사들을 시험하려고 하신다는군요.$B$B스스로 자격이 된다고 생각하면, 북쪽에 있는 백호사를 찾아가서 도전해 보십시오!', `FemaleText_loc4`='白虎雪怒顶着寒冷的北风担任守卫工作。$B$B今天，雪怒试图通过列一系列比赛找到该地区最出色的勇士。$B$B如果你相信自己的能力，就北行至白虎寺，迎接挑战！', `FemaleText_loc5`='『白虎』雪怒防衛著北方的寒風。$B$B如今，他以一連串的試煉考驗這片土地上的偉大勇士們。$B$B如果你相信自己夠資格，前往北方的白虎寺，然後提出你的挑戰!', `FemaleText_loc7`='Xuen, el Tigre Blanco, nos protege contra los fríos vientos del norte.$B$BHoy quiere desafiar a los principales campeones de la tierra con una serie de pruebas.$B$BSi te ves capaz, viaja al norte, hasta el Templo del Tigre Blanco, ¡y desafíalo!' WHERE `ID`=64815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='츠지 님께서는 남쪽의 주학사를 지키십니다.$B$B샤의 출현으로 이 땅이 혼란에 빠진 후로 질서를 되찾으려고 애쓰고 계시지요.$B$B츠지 님을 돕고 싶다면 크라사랑 밀림에 있는 츠지의 요람으로 가십시오.', `FemaleText_loc4`='赤精守护着南方的朱鹤寺。$B$B在煞魔暴乱造成地区混乱之后，她一直试图重新重铸秩序。$B$B如果你想帮助她，就去卡桑琅丛林中的赤精栖木。', `FemaleText_loc5`='赤吉照管著南方的紅鶴寺。$B$B她正試著要從煞爆發後導致的混亂中重整秩序。$B$B如果你想要幫助她，前往位於喀撒朗蠻荒的赤吉搖籃。', `FemaleText_loc7`='Chi-Ji vigila el Templo de la Grulla Roja, al sur.$B$BEstá tratando de recuperar el orden después de que la erupción del sha sembrara el caos en la tierra.$B$BSi quieres ayudarla, viaja hasta la Cuna de Chi-Ji en la Espesura Krasarang.' WHERE `ID`=64816;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흑우 니우짜오 님께서는 장벽 뒤의 적들을 꿋꿋이 막아 내고 계십니다.$B$B밀려오는 사마귀 무리를 물리치는 데 도움이 절실하다더군요.$B$B돕고 싶다면 서쪽의 탕랑 평원에 있는 사원으로 가십시오.', `FemaleText_loc4`='玄牛砮皂将敌人阻挡在城墙之外。$B$B他也非常需要帮助，以击退渐渐入侵的螳螂妖。$B$B如果你想提供帮助，就西行至螳螂高原上的寺院。', `FemaleText_loc5`='『玄牛』怒兆，屹立不搖地對抗長城之外的敵人。$B$B他極度需要協助以擊退進逼的螳螂人。$B$B如果你想要幫忙，前往西方位於螳螂荒原的玄牛寺。', `FemaleText_loc7`='Niuzao, el Buey Negro, se mantiene firme ante los enemigos de más allá del muro.$B$BNecesita ayuda desesperadamente para repeler la creciente amenaza mántide.$B$BSi quieres ayudar, viaja hasta el templo en las Estepas de Tong Long, al este.' WHERE `ID`=64817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 저희가 추구하는 대의를 위해 목숨을 거는 분들께는 보답을 해드려야 마땅하지요.$B$B골짜기를 지키는 데 도움을 주시면, 우리 변경의 안전을 유지할 수 있을 뿐만 아니라, 저희가 보유한 강력한 보물을 손에 넣을 수 있습니다.', `MaleText_loc4`='当然。我们应该奖励那些冒死护谷的人。$B$B通过帮助保护锦绣谷，你不仅可以使边界安宁，而且还能获得我们浩如烟海的强大珍宝。', `MaleText_loc5`='當然。獎賞為我們的理念而赴湯蹈火的人是天經地義的。$B$B協助防禦恆春谷不只能保持我們的邊界安全，還讓你有資格取得我們眾多力量強大的寶物。', `MaleText_loc7`='Por supuesto. Es de justicia recompensar a aquellos que arriesgan sus vidas por nuestra causa.$B$BAl ayudar a defender el valle, no solo conseguirás mantener a salvo nuestras fronteras, sino que también te habrás ganado el acceso a nuestras enormes reservas de poderosos tesoros.' WHERE `ID`=64818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기가 큰 위험에 처해 있습니다.$B$B가로쉬 헬스크림이 고대의 악마에게서 나온 암흑의 유물인 이샤라즈의 심장으로 성스러운 골짜기의 물을 오염시켰습니다. 그 악행의 결과는... 그 눈으로 직접 보실 수 있습니다.$B$B샤의 잔여물이 우리 존재 자체를 위협하고 있습니다. 싸우는 수밖에 없습니다.', `MaleText_loc4`='锦绣谷正处于危难当中，$r。$B$B加尔鲁什·地狱咆哮用一件来自上古邪神的黑暗神器——亚煞极之心污染了这座圣谷中的水流。而他的恶行所造成的后果……呃……你也已经看见了。$B$B现在，煞魔余孽已经威胁到了我们的生存。我们别无选择，必须战斗。', `MaleText_loc5`='恆春谷陷入了莫大的危機，$r。$B$B卡爾洛斯·地獄吼已經用亞煞拉懼之心污染了谷內的水源，那是遠古惡魔的黑暗聖物。他所作所為產生的影響...這...你自己在谷裡也能看到。$B$B現在，煞的殘留物質已經嚴重威脅到我們的生存環境，我們別無選擇，只有挺身一戰。', `MaleText_loc7`='El Valle de la Flor Eterna se encuentra en grave peligro, $r.$b$bGarrosh Grito Infernal ha contaminado las aguas de nuestro valle sagrado con el Corazón de Y''Shaarj, una reliquia oscura de un mal antiguo. Los efectos de semejante acto... En fin, los puedes ver con tus propios ojos.$b$bAhora los restos de los sha amenazan nuestra misma existencia. No tenemos alternativa: debemos luchar.' WHERE `ID`=64819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 골짜기를 위해 할 일이 없습니다. 당신이 모구 지도자를 처치한 직후 모구가 사라졌거든요. 덕분에 우리 모두 안전해졌습니다.', `MaleText_loc4`='此时此刻，锦绣谷不需要再做什么事情了，$n。你杀死魔古部落首领之后，魔古族就立马土崩瓦解了。我们现在安全了，谢谢你。', `MaleText_loc5`='現在谷中已經沒有任何事要做了，$n。魔古在你殺死他們的首領後沒多久就消失了。我們現在很安全，這都要感謝你。', `MaleText_loc7`='Ya no hay nada más que hacer por el valle en este momento, $n. Los mogu desaparecieron poco después de que mataras a su líder. Estamos a salvo, gracias a ti.' WHERE `ID`=64820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전승지기는 세상을 떠돌며 새로운 이야기를 찾고 옛이야기를 전파합니다.$B$B우리는 판다리아의 장소와 사람에 얽힌 다채로운 이야기를 연구하지요.$B$B그런 이야기를 직접 듣고 싶다면, 이곳 영원꽃 골짜기의 모구샨 궁전 입구 위쪽에 있는 지식의 연단을 찾아가서 전승지기 초와 이야기하십시오.', `FemaleText_loc4`='游学者周走遍世界，发现了新的传说，也重新阐释了旧的故事。$B$B我们仔细研究了潘达利亚地区丰富的地理人文历史。$B$B如果你自己想听某些故事，就与闻道之座的游学者周卓交谈。闻道之座在锦绣谷魔古山宫殿入口上方。', `FemaleText_loc5`='博學行者在這世界中旅行，尋找新的傳說並傳承舊有的歷史。$B$B我們探訪潘達利亞中各地人文的豐富歷史。$B$B如果你想要聽這些故事，前往位在恆春谷，魔古山宮入口之上的知識之座和博學行者阿洲談談。', `FemaleText_loc7`='Los eremitas recorremos el mundo descubriendo nuevas historias y contando otras antiguas.$B$BExploramos la rica historia de los lugares y la gente de Pandaria.$B$BSi quieres escuchar algunas de estas historias en persona, habla con el eremita Cho en el Trono del Saber, encima de la entrada al Palacio Mogu''shan aquí, en el Valle de la Flor Eterna.' WHERE `ID`=64821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전승지기는 판다리아의 주요 지역을 탐험하면서 문화재를 찾는 임무를 줄 겁니다.$B$B한 이야기에 속하는 유물을 모두 찾으면, 이야기를 처음부터 끝까지 다 들을 수 있답니다.$B$B유물을 모두 찾고 책을 모두 모으면 전승지기가 될 수 있지요!$B$B연구원이 되고 싶다면, 지식의 연단에 있는 전승지기 초와 이야기하십시오.', `FemaleText_loc4`='游学者将派你到潘达利亚的重要地区，以收回当地的文化神器。$B$B一旦找到属于一个系列的所有神器，你就可以听完整个故事的来龙去脉。$B$B找到所有文化神器，收集所有图书，变成一个游学者！$B$B如果你觉得有趣，就闻道之座的游学者周卓交谈。', `FemaleText_loc5`='博學行者將會派你前去探訪潘達利亞中重要的區域，以取回各種文物。$B$B一旦你找齊屬於同一套的所有文物，你就能從頭到尾地聆聽整段故事。$B$B找到所有的文物，並收集所有的書以成為一名博學行者!$B$B如果你有興趣成為研究員，你就應該去和知識之座的博學行者阿洲談談。', `FemaleText_loc7`='Los eremitas te enviarán a explorar zonas importantes de Pandaria para recuperar artefactos culturales.$B$BCuando encuentres todos los artefactos que componen la colección, podrás escuchar la historia de principio a fin.$B$B¡Encuentra todos los artefactos y colecciona todos los libros para convertirte en $gun:una; eremita!$B$BSi te interesa convertirte en $gun investigador:una investigadora;, habla con el eremita Cho en el Trono del Saber.' WHERE `ID`=64822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여정 자체가 보상이지요, 젊은이. 이야기의 내용에서 즐거움을 찾는 거야말로 비길 데 없는 보물이니까요.$B$B참, 한 가지 더 있어요. 지체 높은 전승지기는 아주 특별한 선물을 받지요. 바로 구름을 탈 수 있는 능력입니다.', `FemaleText_loc4`='旅途本身就是馈赠，年轻人。在故事中寻找快乐，你就会得到无与伦比的财富。$B$B对了，还有件事。在游学者中地位升高的人还能获得特殊的礼物——驾云而行的能力。', `FemaleText_loc5`='旅途本身就是我們的報酬，年輕人。從故事中找尋樂趣，你將獲得無與倫比的財富。$B$B啊對了，還有一件事。在博學行者的行列中晉升者會被賦予一項十分特殊的禮物。那就是乘雲的能力。', `FemaleText_loc7`='El viaje es una recompensa en sí mismo, joven. Busca el placer de contar una historia y volverás con una riqueza inimaginable.$b$bAh, sí, una cosa más. Aquellos que ascienden de rango entre los eremitas reciben un don muy especial: la capacidad de cabalgar sobre las nubes.' WHERE `ID`=64823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 가장 훌륭하고 뛰어난 이들만 받아들여 훈련시키는 고대의 결사입니다.$B$B자신의 쓸모를 증명할 수 있다면, 여러 가지 강력한 물품을 구입할 수 있을 겁니다.', `MaleText_loc4`='影踪派是一个古老的组织，它只接受和培训最为精干和最有价值的成员。$B$B如果你能证明自己的价值，许多强大的物品就能为你所用。', `MaleText_loc5`='影潘是個古老的組織，只接受與訓練最好的菁英。$B$B如果你能設法讓自己派上用場，你會發現自己有資格取得許多強大的物品。', `MaleText_loc7`='El Shadopan es una orden ancestral que acepta e instruye a los mejores y más capaces.$B$BSi demuestras ser de utilidad, tendrás a tu disposición muchos objetos poderosos.' WHERE `ID`=64824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파의 신뢰를 얻는 길이 몇 가지 있지요.$B$B음영파는 쿤라이 봉우리의 파이어바우 변두리마을에 출현한 샤를 상대하느라 바쁩니다. 그곳의 음영파 대원을 도와주면, 우리 결사에 들어오기 위한 기반을 마련할 수 있을 겁니다.$B$B음영파 수도원에도 문제가 있지요. 그곳의 형제자매를 도와줄 수도 있습니다.$B$B또, 분노의 샤가 북쪽에 있는 쿤라이의 평원을 떠돌고 있습니다. 분노의 샤를 처치하면 음영파의 호의를 살 수 있겠지요.$B$B마지막으로, 음영파 분대가 탕랑 평원에서 증오의 샤를 쫓고 있습니다. 그들에게도 도움이 필요할지 모릅니다.$B$B음영파와 끈끈한 관계를 맺고 싶다면, 우선 황금 연꽃과 매우 우호적 평판을 달성해야 합니다. 그러고 나서 탕랑 평원의 음영파 주둔지에 있는 형제자매와 이야기하십시오.', `MaleText_loc4`='要想赢得我们的尊重，有以下几种办法。$B$B我们现正在昆莱山的火树村应对邪煞的攻势。帮助我们，你就能在我们的门徒间占得一席之地。$B$B影踪禅院也遇到了麻烦。你或许能帮帮我们在那里的兄弟姐妹。$B$B怒之煞在北面的昆莱旷野上横行。将它击败，你就能在我们的成员当中树立威信。$B$B最后，一支影踪分遣队被派往螳螂高原追击恨之煞。他们或许也需要帮助。$B$B如果你希望赢得我们最高的敬意，你必须证明自己，与金莲教的关系要先达到崇敬。然后，再到螳螂高原的影踪卫戍营来找我的兄弟姐妹们谈谈。', `MaleText_loc5`='你有一些種方法可以贏得我們的尊敬。$B$B我們正忙著在崑萊峰的火枝望角應付煞的爆發。到那裡幫助我們，你就能在我們的兄弟間占有一席之地。$B$B影潘僧院也正處於困難之中。你也許能夠給予我們在那裡的兄弟姊妹一些協助。$B$B憤怒之煞出沒在北方的崑萊原野之中。擊敗它，你就會獲得我們的尊重。$B$B有一隊的影潘到螳螂荒原追捕仇恨之煞。他們可能需要幫忙。$B$B如果你想要贏得我們最高的尊敬，首先你必須獲得金蓮的崇敬地位。你做到之後，到螳螂荒原的影潘要塞和我的兄弟姊妹們交談。', `MaleText_loc7`='Hay muchas formas de ganarse nuestra estima.$b$bNos enfrentamos a las erupciones de sha del Rincón Tallo Ardiente, en la Cima Kun-Lai. Ayudarnos allí sería un primer paso.$b$bEl Monasterio del Shadopan también está en peligro. Tal vez puedas ayudar a nuestros hermanos.$b$BEl Sha de la ira asola los campos de Kun-Lai, al norte. Si lo derrotas, ganarás gran respeto en nuestra orden.$b$bUn contingente del Shadopan persigue al Sha del odio en las Estepas de Tong Long. Quizás necesiten ayuda.$b$bSi deseas ganarte la mayor estima, primero debes demostrar tu valía alcanzando el estado de $gvenerado:venerada; con el Loto Dorado. Solo entonces deberás hablar con mis hermanos y hermanas del Cuartel del Shadopan, en las Estepas de Tong Long.' WHERE `ID`=64825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적함을 태워라. 비행 조련사를 도륙하고 전쟁 병기를 파괴해라. 그리고 우리 첩자를 구출하라!', `MaleText_loc4`='烧毁他们的船只，杀掉飞行管理员，破坏战争机器。同时保证我方间谍的安全！', `MaleText_loc5`='燒了他們的船隻，宰了他們的飛行管理員，破壞他們的戰爭機械，然後救回我們的間諜!', `MaleText_loc7`='Quemen sus barcos. Maten a su maestro de vuelo. Saboteen sus máquinas de guerra. ¡Y rescaten a nuestro espía!' WHERE `ID`=64826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽에서 막 돌아온 참입니다.$B$B그곳에 있을 때, 용의 척추 너머에서 온 클락시라는 세력에 대한 소문을 들었습니다. 아마도, 사마귀 제국에 등을 돌린 사마귀 장로의 의회인 듯합니다. 지금은 사마귀 여제에 정면으로 맞서고 있지요.$B$B이 사마귀들이 지닌 힘은 제 눈으로 똑똑히 보았습니다.$B$B소문이 사실이라면 이... 클락시... 라는 자들과 동맹을 맺고 힘을 합쳐서 사마귀 무리를 막을 방법이 있을지도 모릅니다.', `MaleText_loc4`='我刚刚从城墙那边回来。$B$B我在那边听说了一些关于卡拉克西螳螂妖的谣言。据说他们来自蟠龙脊之外，可能是从螳螂妖帝国分裂出来的螳螂妖长老议会。如今他们正公然违抗螳螂妖女皇的命令。$B$B我亲眼见识了这些螳螂妖的法力。$B$B如果这些谣言可信，我们就有可能找到一条途径联合这些……卡拉克西……并和他们共同阻止螳螂妖虫群。', `MaleText_loc5`='我剛從長城那邊回來。$B$B我在那裡聽說有關一個遠在蟠龍脊之外、被稱為卡拉西的陣營的傳聞。據稱他們是一個從螳螂人帝國分支出來的長老議會，並且致力於直接反抗螳螂人皇后。$B$B我曾親眼見證過螳螂人所持有的力量。$B$B因此如果傳聞屬實，也許有什麼方法可以和這些...卡拉西...結盟，並和他們合作阻止螳螂人大軍。', `MaleText_loc7`='Acabo de regresar de la muralla.$B$BAllí he oído hablar de una facción a la que llaman los Klaxxi del otro lado del Espinazo del Dragón. Supuestamente, son un consejo de ancianos mántides que se han escindido del imperio mántide, y ahora desafían directamente a la reina de los mántides.$B$BHe visto con mis propios ojos el poder que ostentan esos mántides.$B$BSi los rumores son ciertos, quizás podamos aliarnos con esos... Klaxxi... y colaborar con ellos para detener el enjambre mántide.' WHERE `ID`=64827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 모르는 일입니다, $r님. 그걸 알고자 하는 건 어리석고도 미친 짓이지요!$B$B어쨌든 클락시를 만나려면 장벽을 넘어 공포의 황무지로 가는 수밖에 없는 듯합니다.', `MaleText_loc4`='这对我来说是个难解之谜，$r。如果你想找到他们，你就太傻、太疯狂了！$B$B但是我认为遇见卡拉克西的唯一途径是冒险越过这座城墙，到达恐惧废土。', `MaleText_loc5`='那對我來說是個謎，$r。如果你想要查明，你就是又瘋又蠢!$B$B但我推測想要和卡拉西商議除了深入悚然荒野之外也別無他法了。', `MaleText_loc7`='Es un misterio para mí, $r. ¡Si quieres averiguarlo, estás $loco:loca;!$B$BPero supongo que no hay otra forma de conocer a los Klaxxi que cruzar la muralla y entrar en el Desierto del Pavor.' WHERE `ID`=64828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 모르겠습니다, $r님.$B$B클락시에 대해서는 아는 게 거의 없으니까요. 그들은 꽤 무자비한 듯하니, 돌아오는 건 순간적인 죽음뿐일지도 모릅니다.$B$B하지만 그들의 문명은 꽤 방대하고 진보되어 있습니다. 잘만 하면 막대한 힘을 전수받을 수 있을지도 모르지요.$B$B진실을 알아내는 방법은 하나뿐입니다.', `MaleText_loc4`='我不知道，$r。$B$B我们对卡拉克西所知甚少。他们看起来非常冷酷无情，你去了只会送死。$B$B而且他们的文明非常博大精深。如果你处理得当的话，他们或许会赐予你强大的力量。$B$B只有一种方法能知道最后的结果。', `MaleText_loc5`='我不知道，$r。$B$B我們對卡拉西所知是少之又少。他們似乎相當殘忍，所以或許你的唯一獎賞會是痛快地死去。$B$B但話又說回來，他們的文明相當龐大且先進。如果你能成功和他們協商，或許他們會給予你未知的力量。$B$B只有一個方法可以查明。', `MaleText_loc7`='No lo sé, $r.$B$BSabemos muy poco sobre los Klaxxi. Parecen muy despiadados, así que quizás tu única recompensa sería una muerte rápida.$b$bPor otro lado, su civilización es bastante extensa y avanzada. Si juegas bien tus cartas, es posible que te concedan un poder inefable.$B$BSolo hay una manera de averiguarlo.' WHERE `ID`=64829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아군이 재집결하는 동안 적을 혼란시켜라. 헬스크림 님께서 지켜보신다!', `MaleText_loc4`='扰乱他们，让我们重新部署。地狱咆哮的双眼注视着你！', `MaleText_loc5`='在我們重整隊伍時讓他們陷入混亂。地獄吼的雙眼在盯著你!', `MaleText_loc7`='Siembren el caos mientras nos reagrupamos. ¡Grito Infernal los observa!' WHERE `ID`=64830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지 파이어포우가 당신을 따뜻하게 안아 줍니다.', `MaleText_loc4`='季·火掌热烈欢迎你的回归。', `MaleText_loc5`='紀·火爪用溫暖的擁抱歡迎你回來。', `MaleText_loc7`='Ji Zarpa Ígnea te devuelve el abrazo cálidamente.' WHERE `ID`=64831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡단은 비취 숲을 지키는 임무를 띠고 있습니다. 저희는 비취 숲의 옥룡사 바로 북쪽에 있는 도원에서 훈련하고 있지요.', `FemaleText_loc4`='云端翔龙骑士团发誓保卫翡翠林。我们在翡翠林青龙寺正北面的百木园进行训练。', `FemaleText_loc5`='雲蛟衛立誓防衛翠玉林。我們在翠玉林中玉蛟寺北方不遠的落英園受訓。', `FemaleText_loc7`='La Orden del Dragón Nimbo ha jurado defender el Bosque de Jade. Entrenamos en El Arboretum, al norte del Templo del Dragón de Jade, en el Bosque de Jade.' WHERE `ID`=64832;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡단에서 승급하는 것만큼 큰 영예도 없습니다.$B$B실력을 증명하고 나면 운룡을 타고 마음껏 이 땅을 날아다닐 수 있지요.$B$B또한 "운룡 타기" 기술을 배울 수 있습니다. 그러면 판다리아에서 나는 운룡 탈것을 모두 탈 수 있게 되지요.', `FemaleText_loc4`='在云端翔龙骑士团中获得晋升是一种莫大的荣耀。$B$B一旦证明了自己，你就能把翔龙当成飞行坐骑，任意驰骋。$B$B你还能学会骑乘云端翔龙的技能，可以骑乘潘达利亚的任何一条云端翔龙。', `FemaleText_loc5`='沒有什麼事能比在雲蛟衛中晉升階級更光榮。$B$B一旦你證明了你自己的價值，你將能自由地與你的蛟龍飛行坐騎一同遨遊世界。$B$B你也會學到雲蛟騎術，讓你能騎乘潘達利亞的任何雲蛟。', `FemaleText_loc7`='No hay mayor honor que ir ascendiendo de rango en la Orden del Dragón Nimbo.$B$BCuando hayas demostrado tu valía, serás libre de surcar los cielos a lomos de tu dragón.$b$bTambién aprenderás la habilidad Montar sobre dragón nimbo, que te permitirá utilizar cualquier montura de dragón nimbo de Pandaria.' WHERE `ID`=64833;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운룡단에 들어오면 용 기수가 되기 위한 길을 걷게 됩니다.$B$B새끼 운룡을 부화시킨 후 매일 함께 훈련하면서 다 자랄 때까지 돌보아야 하지요.', `FemaleText_loc4`='一旦进入云端翔龙骑士团，你就可以利用翔龙坐骑开始一段旅程。$B$B你可以孵化一头幼小的翔龙，每天培训它，看着它长大成年。', `FemaleText_loc5`='你一旦加入雲蛟衛，將以雲蛟騎士的身分開始你的旅程。$B$B你得從一顆蛋開始孵育你的小蛟龍，每天訓練他，看著他一天天茁壯。', `FemaleText_loc7`='Cuando entres en la Orden del Dragón Nimbo, comenzarás el viaje de un jinete de dragones.$B$BCriarás a un bebé dragón desde que salga del huevo, entrenarás con él cada día y lo verás crecer hasta la edad adulta.' WHERE `ID`=64834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통이 폭발하면서 %s에 붙은 불을 끕니다!', `MaleText_loc4`='酒桶破裂了，扑灭了%s的火焰！', `MaleText_loc5`='桶子爆炸，澆熄了%s的火焰!', `MaleText_loc7`='El barril explota, extinguiendo las llamas de %s.' WHERE `ID`=64835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부를 돕는다고 보석이 생기거나 싸움 실력이 느는 건 아니다.$B$B농사일은 그런 게 아니니까.$B$B느린 삶이지만 좋은 삶이다. 두카 잘 아니까, 두카한테 물어봐라!$B$B밭을 가꿔서 농작물을 심고, 기른 음식을 먹을 수 있지! 두카가 제일 좋아하는 부분이 바로 그거다!$B$B구미가 당기면 언덕골에 가서 직접 봐라!', `MaleText_loc4`='嗯，阡陌客不会让你变得富有，而且也不会让你变强大以应付战事。$B$B耕田劳作略有不同。$B$B那是一种慢节奏的惬意生活。你问杜凯算是问对人了！$B$B你可以建立自己的农场、种植自己的庄稼，并且享受自己的劳动果实。杜凯最喜欢的就是这个！$B$B所以，如果你感兴趣的话，就亲自去半山看看！', `MaleText_loc5`='耕者工會沒辦法讓你穿金戴銀或幫你強身健體。$B$B那些都不是一個農夫生活的重點。$B$B如果你能堅持下去，你可能會遇到一些非常有趣的人們。你能建構出屬於你自己的農場，種植你自己的農作物，並享受你自己辛勞的成果。你還能獲得工匠獎章。$B$B如果這些聽起來很有趣，那你就該親自去半丘一趟，眼見為憑!', `MaleText_loc7`='Bueno, los Labradores no te van a cubrir de joyas ni prepararte para la guerra.$B$BNo, la vida de un granjero no tiene nada que ver con eso.$B$BSi te pones a ello, conocerás a gente bastante interesante. Podrás formar tu propia granja, plantar tus propios cultivos, y disfrutar de los frutos de tu propio trabajo.$B$BSi todo esto te parece interesante, ¡entonces ve a El Alcor y compruébalo en persona!' WHERE `ID`=64836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 두카 뭐부터 말해야 되지!?$B$B우선 농부는 씨앗 뿌리고 작물 거둔다. 채소는 요리에 쓰거나 시장에 팔거나 다른 사람과 거래하거나 할 수 있다. 심으면 특별한 보상을 받을 수 있는 희귀한 씨앗이 있다는 얘기도 들었다... 작은 애완동물 같은 거 말이다!$B$B언덕골에는 만날 사람도 많다! 거기 사는 사람들은 나 같은 원숭이가 봐도 정말 재미있다. 선물을 주고 친해지면, 선물을 받을 수 있을지도 모른다!$B$B밭에 있다 보면 할 일이 아주 많다!', `MaleText_loc4`='哦，杜凯要从哪里说起呢？！$B$B首先，农夫需要播种和收获庄稼。你出售的庄稼可以用于烧饭、拍卖出售、卖给其他买家，或者换购其它东西。我还听说，农夫可以种植一些稀有种子以获得特殊物品……比如小宠物！$B$B另外，你应该去见见半山的每一个人！这里的住民有趣极了，就连像我这样的捣蛋鬼都喜欢他们。你给他们礼物，与他们做好朋友，他们就会用贴心的馈赠来回报你！$B$B在田野周围总有许多事情可做！', `MaleText_loc5`='喔，都卡該從哪裡開始?!$B$B首先，農夫要播種和收割農作物。蔬菜可以用於烹飪、拿去市場賣、和其他買家交易，或是很多其他的。我甚至聽說過能長出獨特物品的稀有種子...比如說小寵物!$B$B還可以在半丘遇到許多人!就連對我這樣的猴子來說，住在那一帶的人們也非常有趣。你給他們禮物，做好朋友。他們或許也會給你好禮物!$B$B在農地裡總是有許多事可以做!', `MaleText_loc7`='Ah, ¿por dónde empezar?$b$bEn primer lugar, la vida de un granjero implica plantar semillas y cosechar cultivos. Las verduras se pueden utilizar en la cocina, vender en el mercado, comerciar con otros compradores y mucho más. Hasta he oído hablar de semillas raras que se pueden plantar para obtener objetos únicos... ¡o hasta una mascota poco común!$b$b¡Y tienes que conocer a todo El Alcor! Nuestros vecinos son muy interesantes, hasta para un mono como yo. Hazles regalos, traba amistad con ellos, y a lo mejor ellos también te hacen regalos a ti.$b$b¡Siempre hay algo que hacer en el campo!' WHERE `ID`=64837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 포병대가 왔습니다. 영웅들이여, 서둘러야 합니다!', `MaleText_loc4`='螳螂妖炮兵在那里，你们要快一点，各位英雄！', `MaleText_loc5`='螳螂人火砲到達了，你們必須盡快，英雄們!', `MaleText_loc7`='¡La artillería mántide ya está aquí, deben darse prisa, héroes!' WHERE `ID`=64838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 낚시하기가 제일 좋은 곳은 크라사랑 밀림 남동쪽에 있는 강태공 부두지요. 언제든 오셔서 낚싯대를 드리워도 됩니다!', `MaleText_loc4`='卡桑琅丛林东南部的渔人码头最适合垂钓了。欢迎大家来访垂钓！', `MaleText_loc5`='你能在喀撒朗蠻荒東南角的釣手泊船處找到最好的漁具店。歡迎任何人來拜訪我們和挑一根釣魚竿!', `MaleText_loc7`='La mejor pesca se puede encontrar en el Muelle de los Pescadores, al sureste de la Espesura Krasarang. ¡Animamos a todo el mundo a visitarnos y coger una caña de pescar!' WHERE `ID`=64839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얻는 게 뭐냐니, 그게 무슨 말입니까? 무슨 질문이 그렇지요?$B$B바다에서 대어를 건져 올리는 기쁨으로는 부족합니까? 목뒤에 햇볕을 받으며 흩날리는 바닷물을 맛보는 건요? 친구들과 느긋이 앉아서 시원한 맥주를 따는 건요?$B$B그걸로 부족하단 겁니까?!?$B$B내 장담하는데, 낚시꾼으로서의 삶은 비할 데 없이 보람찰 겁니다!$B$B우선 낚시 기술을 향상시킬 수 있지요. 기술이 향상되면 좋은 낚싯대를 살 수 있습니다.$B$B존경받는 낚시꾼은 특별한 물고기 애완동물, 물속을 달리는 탈것, 개인용 낚시 뗏목도 얻을 수 있고 말입니다!', `MaleText_loc4`='你问我你能从中得些什么好处，这么说是什么意思呢？那是个什么问题？$B$B难道从海里钓到大鱼还不够快乐吗？那么阳光照在你的脖子上，感觉怎么样呢？咸咸的海水飞洒到你的脸上，感觉怎么样呢？和朋友闲坐在一起，喝一杯冷啤感觉怎么样？$B$B这还不够吗？！？$B$B让我告诉你吧，$G渔夫:渔妇;的生活简直无与伦比！$B$B你可以从头学习提高钓鱼技能。帮助当地人可以获得一些工匠代币。获得足够的技能，你就可以购买功能强大的钓竿。$B$B倍受尊重的渔夫可以使用垂钓宠物和阔步者坐骑。这里竟然还有一个捕鱼木筏，我的天啊！', `MaleText_loc5`='你說你能得到什麼是什麼意思?那是什麼怪問題?$B$B把大魚從海中釣起來的樂趣還不夠嗎?那太陽光照在你脖子上、海洋鹽水噴灑在你臉上的感覺如何?和你的朋友們悠閒地喝著冰涼啤酒又如何?$B$B那樣還不夠嗎?!?$B$B讓我告訴你，$G漁夫:海女;的生活比任何東西都還要棒!$B$B首先，你可以增進你的釣魚技能。幫助當地人還可以得到工匠獎章。只要技能夠高超，你可以購買強力的釣魚竿。$B$B受人敬仰的漁夫還可以得到特別的小魚寵物和一隻水黽坐騎。甚至還有個捕魚筏，這樣還不夠嗎!', `MaleText_loc7`='¿Cómo que qué ganas con esto? ¿Qué clase de pregunta es esa?$b$b¿No es bastante la alegría de pescar al gran pez? ¿Y la sensación del sol en el cuello y la espuma del océano en la cara? ¿Y qué hay de abrir una bebida fría mientras te relajas con tus amigos?$b$b¡¿No es suficiente?!$b$b¡Te aseguro que la vida de $gun pescador:una pescadora; es incomparable!$b$bPuedes empezar mejorando tu habilidad en pesca. Si ayudas a la gente, te darán fichas de artesano. Si aumentas tu habilidad, podrás comprar poderosas cañas de pescar.$b$bLos pescadores más respetados pueden acceder a un pez mascota especial y a una montura de zancudo acuático. ¡Hay hasta una balsa de pesca, por los siete mares!' WHERE `ID`=64840;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양조사 시나리오에 참여하는 사람은 용맹 점수를 획득할 수 있어요. 또, 양조사와 다니면서 발견하는 진기한 물품은 모두 가져도 좋아요.', `FemaleText_loc4`='参加酒仙场景战役的人可赢得勇气。要是你在与酒仙一同冒险时发现任何罕见物品，尽管将其收入囊中！', `FemaleText_loc5`='參與釀酒大師事件的人將獲得勇氣。如果你在和釀酒大師冒險途中發現任何稀有的物品，那些都是你的!', `FemaleText_loc7`='Aquellos que participen en las gestas de los maestros cerveceros obtendrán valor. Y si encuentras un objeto raro mientras vives aventuras con un maestro cervecero, ¡puedes quedártelo!' WHERE `ID`=64841;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아에서 가장 큰 양조장은 네 바람의 계곡에 있는 스톰스타우트 양조장이에요. 모험을 원한다면 거기부터 가 보는 게 좋을 거예요.$B$B양조사들은 천성이 떠돌이인지라 온 세상을 떠돌며 귀한 재료를 찾거나 새로운 술을 연구해요.$B$B그런 양조사들은 보통 시나리오에서 만날 수 있죠.$B$B양조사 츄는 녹옥 마을 시나리오에서 적을 막고 있어요.$B$B양조사 보는 웅가 잉구 시나리오에서 열대의 맛을 찾고 있죠.$B$B양조사 부프는 맥주달 축제 시나리오에서 이 계절을 만끽하고 있고, 양조사 블랜치는 양조 폭풍 시나리오에서 뭔가 충격적인 것을 만들고 있어요.', `FemaleText_loc4`='潘达利亚地区最大的酿酒厂是四风谷的风暴烈酒酿造厂。如果你想冒险，可以从那里开始。$B$B酒仙实质上也是游荡者，并且他们经常四处闲逛，寻找稀有原料或调配新酒。$B$B这些酒仙通常会出现在独特的场景战役里。$B$B酒仙曲子在绿石村场景战役中抵御敌人。$B$B珀酒仙在盎迦猴岛场景战役中寻找热带配料。$B$B酒仙布夫在酿月祭场景战役中欢庆佳节，酒仙布兰琪在酝酿风暴场景战役中准备让人大吃一惊。', `FemaleText_loc5`='潘達利亞中最大的酒坊就是四風峽中的風暴烈酒酒坊。如果你想要尋找探險的機會，從那裡開始應該不錯。$B$B釀酒大師們天性喜好到處遊蕩，到處都能發現他們漫遊於這片土地，尋找稀有的材料或調製新的酒。$B$B這樣的釀酒大師經常會在獨特的事件中被發現。$B$B釀酒大師祖在綠石村事件中抵禦敵人。$B$B釀酒大師阿波在仰加印古事件中尋找熱帶風味。$B$B釀酒大師布夫在酒月節事件中歡慶，而釀酒大師白蘭琪則在雷電佳釀事件中釀造某種驚人的東西。', `FemaleText_loc7`='La mayor cervecería de Pandaria es la Cervecería del Trueno, en el Valle de los Cuatro Vientos. Puedes empezar por ahí si buscas aventuras.$b$bLos maestros cerveceros son errantes por naturaleza, así que viajan por todo el continente en busca de ingredientes raros o preparando nuevas recetas.$b$bTales maestros cerveceros suelen hallarse en gestas únicas.$b$bEl maestro cervecero Tzu se defiende del enemigo en la gesta de la Aldea Verdemar.$b$bEl maestro cervecero Bo busca sabores tropicales en la gesta de Unga Ingoo.$b$bEl maestro cervecero Boof celebra la temporada en la gesta del Festival de la Cerveza Lunar y, por último, la maestra cervecera Blanche cocina un plato chocante en Cervezas y Truenos.' WHERE `ID`=64842;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='양조사 블랜치는 폭풍이 몰아치는 와중에 폭발 맥주를 만들려고 하고 있어요. 그런데 무시무시한 적이 방해를 하고 있다죠.', `FemaleText_loc4`='酒仙布兰彻努力在暴风雨中制造闪电陈酿，但是受到了一些难缠敌人的阻碍。', `FemaleText_loc5`='釀酒大師白蘭琪正嘗試在一個風暴中央釀造閃電淡啤酒，但有些難以對付的敵人在防礙她。', `FemaleText_loc7`='La maestra Clara está tratando de elaborar brebaje relámpago en mitad de una tormenta, pero unos enemigos formidables se están interponiendo en su camino.' WHERE `ID`=64843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='웅가 잉구의 사악한 호젠 해적에게서 밀림 맥주를 되찾으세요!', `FemaleText_loc4`='把丛林酒从盎迦猴岛那些邪恶猢狲海盗的巢穴中抢救出来。', `FemaleText_loc5`='從仰加印古的邪惡猴人海盜手中取回叢林啤酒。', `FemaleText_loc7`='Rescata el brebaje de jungla de las garras de los malvados piratas hozen de Unga Ingoo.' WHERE `ID`=64844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맛있는 술을 양조하고, 야운골 공격자들을 막아 내세요.', `FemaleText_loc4`='酿造一些美酒，抵挡野牛人的袭击。', `FemaleText_loc5`='釀造美味的東西並抵禦揚古攻擊者。', `FemaleText_loc7`='Elabora algo delicioso y defiéndete de los atacantes yaungol.' WHERE `ID`=64845;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='녹옥 마을 주민을 짓궂고 (위험한) 숲 생물에게서 구출하세요.', `FemaleText_loc4`='把绿石村村民从那些顽皮（和危险）的森林居民手中解救出来。', `FemaleText_loc5`='從淘氣(與危險)的叢林居民手中救回綠石村民。', `FemaleText_loc7`='Rescata a los aldeanos de Verdemar de los traviesos (y peligrosos) moradores del bosque.' WHERE `ID`=64846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 어느 양조사를 돕고 싶으세요?', `FemaleText_loc4`='你今天想帮助哪个酒仙？', `FemaleText_loc5`='你今天想要協助哪一位釀酒大師?', `FemaleText_loc7`='¿A qué maestro cervecero te gustaría ayudar hoy?' WHERE `ID`=64847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마침 잘 오셨습니다! 도움이 필요했어요!', `FemaleText_loc4`='感谢神真子你来了。我需要你帮忙！', `FemaleText_loc5`='神真子保佑!你終於來了。我需要你的幫助。', `FemaleText_loc7`='Gracias a Shen-zin Su que estás aquí. ¡Necesito tu ayuda!' WHERE `ID`=64848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈이 무기를 들면 피하세요. 보기보다 강합니다.', `FemaleText_loc4`='当它举起武器的时候一定要小心，这一击的威力非同小可。', `FemaleText_loc5`='當它舉起武器時要閃開，它的威力遠比外表還要強大。', `FemaleText_loc7`='Aléjate cuando alce su arma. Es aún más fuerte de lo que parece.' WHERE `ID`=64849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일당을 부르고 있습니다! 제가 놈을 막는 동안 나머지를 처리하세요.', `FemaleText_loc4`='它在召唤援军！我来拖住它，你把增援干掉。', `FemaleText_loc5`='它在呼喚幫手!在你應付他們的時候我來對付他。', `FemaleText_loc7`='¡Está pidiendo refuerzos! Lo mantendré ocupado mientras te ocupas de ellos.' WHERE `ID`=64850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈이 지치고 있습니다. 계속하세요!', `FemaleText_loc4`='它快要被拖垮了。坚持住！', `FemaleText_loc5`='它已經累了。堅持下去!', `FemaleText_loc7`='Lo estamos agotando. ¡Sigue así!' WHERE `ID`=64852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 때맞춰 오시지 않았다면 큰일 날 뻔했어요.', `FemaleText_loc4`='没有你我肯定无法做到这些。你来得太及时了。', `FemaleText_loc5`='要不是你，我真不曉得該怎麼辦。幸好你來了。', `FemaleText_loc7`='No sé lo que habría hecho sin ti. Me alegro de que vinieras.' WHERE `ID`=64853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지붕에서 음영파 얼음 궁수들이 나타납니다!', `MaleText_loc4`='影踪派冰箭手出现在屋顶！', `MaleText_loc5`='影潘寒冰弓箭手出現在屋頂之上!', `MaleText_loc7`='¡Aparecen arqueros de hielo del Shadopan en los tejados!' WHERE `ID`=64855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `MaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `MaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `MaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?', `FemaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `FemaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `FemaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `FemaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?' WHERE `ID`=64856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `MaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `MaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `MaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?', `FemaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `FemaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `FemaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `FemaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?' WHERE `ID`=64857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 혼자는 더 잘해낼 수 없었을 거예요.$B$B뭐, 하지도 못했을 거예요.', `FemaleText_loc4`='我自己没法做得更好。$B$B嗯，也许不能。', `FemaleText_loc5`='我自己都沒辦法做得更好了。$B$B嗯，也許不行啦。', `FemaleText_loc7`='Yo misma no lo habría hecho mejor.$B$BBueno, seguramente no.' WHERE `ID`=64858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배에 불이 붙었다! 병사들이여, 항구로!', `MaleText_loc4`='船着火了！士兵们，立即回港！', `MaleText_loc5`='船隻著火了!士兵們，快趕去港口!', `MaleText_loc7`='¡Los barcos arden! ¡Soldados, al puerto!' WHERE `ID`=64859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님, 여기 출구 쪽이에요.', `FemaleText_loc4`='$p，在出口这里。', `FemaleText_loc5`='$p，在出口這裡。', `FemaleText_loc7`='$p, aquí, en la salida.' WHERE `ID`=64860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장은 건물 2층에 있습니다. 입구에 들어서서 보면 왼쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='拍卖行位于二楼，在你进入的建筑物的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='拍賣場就在二樓，你一進門後，整個建築的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='La casa de subastas se encuentra en la segunda planta, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='경매장은 건물 2층에 있습니다. 입구에 들어서서 보면 왼쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='拍卖行位于二楼，在你进入的建筑物的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='拍賣場就在二樓，你一進門後，整個建築的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='La casa de subastas se encuentra en la segunda planta, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행은 건물 2층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='银行位于二楼，在你进入的建筑物的右侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='銀行在二樓，就在你進門後，整棟建築的右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='El banco se encuentra en la segunda planta, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='은행은 건물 2층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='银行位于二楼，在你进入的建筑物的右侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='銀行在二樓，就在你進門後，整棟建築的右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='El banco se encuentra en la segunda planta, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 조련사는 중앙 난간뜰에 있습니다. 양쪽의 계단을 올라간 후 건물 앞을 보면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='飛行管理員位於主要平臺上，就在雙向樓梯的頂端，進入主建築物之前的地方。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='El maestro de vuelo se encuentra en el patio principal, en lo alto de las escaleras gemelas antes de entrar en el edificio principal.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='비행 조련사는 중앙 난간뜰에 있습니다. 양쪽의 계단을 올라간 후 건물 앞을 보면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='飛行管理員位於主要平臺上，就在雙向樓梯的頂端，進入主建築物之前的地方。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='El maestro de vuelo se encuentra en el patio principal, en lo alto de las escaleras gemelas antes de entrar en el edificio principal.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관은 건물 1층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='旅店就在主要樓層上，一進門後，整棟建築的右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='La posada se encuentra en la planta principal, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='여관은 건물 1층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='旅店就在主要樓層上，一進門後，整棟建築的右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='La posada se encuentra en la planta principal, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인 자울 슈는 건물 앞의 중앙 난간뜰에 있습니다. 비행 조련사 옆에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='在你进入主楼之前，可以在主露台上发现兽栏管理员贾许。他站在飞行管理员的旁边。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='獸欄管理員傑爾·許，就在進入主要建築物之前的主平臺上。他就站在飛行管理員的隔壁。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Jaul Hsu, el maestro de establos, se encuentra en el patio principal, antes de entrar en el edificio principal. Suele estar junto al maestro de vuelo.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='야수 관리인 자울 슈는 건물 앞의 중앙 난간뜰에 있습니다. 비행 조련사 옆에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='在你进入主楼之前，可以在主露台上发现兽栏管理员贾许。他站在飞行管理员的旁边。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='獸欄管理員傑爾·許，就在進入主要建築物之前的主平臺上。他就站在飛行管理員的隔壁。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Jaul Hsu, el maestro de establos, se encuentra en el patio principal, antes de entrar en el edificio principal. Suele estar junto al maestro de vuelo.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리얼은 주 건물 위층에 있는 복도에 점포를 차리고 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='以太在樓上走廊設了商店，就在你進入主要建築物後的右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Los etéreos están asentados en el pasillo de la planta de arriba, nada más entrar en el edificio principal, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='에테리얼은 주 건물 위층에 있는 복도에 점포를 차리고 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='以太在樓上走廊設了商店，就在你進入主要建築物後的右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Los etéreos están asentados en el pasillo de la planta de arriba, nada más entrar en el edificio principal, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 재료를 파는 야니라 문펠은, 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='雅拉·月落在工匠大厅内兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='洋納拉·月落在工匠大廳裡叫賣原料，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Yanyra Lunabaja trafica con componentes y se encuentra en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='마법 재료를 파는 야니라 문펠은, 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='雅拉·月落在工匠大厅内兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='洋納拉·月落在工匠大廳裡叫賣原料，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Yanyra Lunabaja trafica con componentes y puedes encontrarlo en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바늘잡이 레이셴은 아름다운 옷을 만들기로 유명합니다.$B$B건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 일하지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='铁针莱绅那漂亮的衣服是众所周知的事情。$B$B她在工匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='『針王』萊慎以她的漂亮衣服而出名。$B$B她在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Raishen la Aguja es muy conocida por sus preciosas prendas.$b$bTrabaja en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='바늘잡이 레이셴은 아름다운 옷을 만들기로 유명합니다.$B$B건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 일하지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='铁针莱绅那漂亮的衣服是众所周知的事情。$B$B她在工匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='『針王』萊慎以她的漂亮衣服而出名。$B$B她在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Raishen la Aguja es muy conocida por sus preciosas prendas.$b$bTrabaja en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클라라 헨리가 마법부여용품을 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 찾을 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='克拉拉·亨利携带着附魔物资。你可以在工匠大厅内找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='克蕾拉·亨利販售附魔材料。她在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Clara Henry lleva suministros de encantamiento. Puedes encontrarla en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='클라라 헨리가 마법부여용품을 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 찾을 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='克拉拉·亨利携带着附魔物资。你可以在工匠大厅内找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='克蕾拉·亨利販售附魔材料。她在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Clara Henry lleva suministros de encantamiento. Puedes encontrarla en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 두루마리를 만드시는군요! 잉크와 피지를 찾는 거라면, 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 구할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在工匠大厅内可以发现他们，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='啊，卷軸製造者。你一定是在找墨水和上等的皮紙，對嗎?你可以在工匠大廳找到這些東西，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¡Ah, un fabricante de pergaminos! Supongo que buscarás tintas y papel de vitela... Puedes encontrar todo eso en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 두루마리를 만드시는군요! 잉크와 피지를 찾는 거라면, 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에서 구할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在工匠大厅内可以发现他们，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='啊，卷軸製造者。你一定是在找墨水和上等的皮紙，對嗎?你可以在工匠大廳找到這些東西，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¡Ah, un fabricante de pergaminos! Supongo que buscarás tintas y papel de vitela... Puedes encontrar todo eso en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 이곳에는 약초 상인이 있습니다. 토미 팅커스페이드는 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，城市里有药材供应商。在工匠大厅内可以发现托米·补铲，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='是的，城市裡有個草藥商人。湯米·焊鍋鏟在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Sí, hay un vendedor de hierbas en la ciudad. Puedes encontrar a Tommy Palahonda en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='예, 이곳에는 약초 상인이 있습니다. 토미 팅커스페이드는 건물 입구에 들어서서 왼쪽으로 가면 나오는 별의 시장에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，城市里有药材供应商。在工匠大厅内可以发现托米·补铲，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='是的，城市裡有個草藥商人。湯米·焊鍋鏟在工匠大廳裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Sí, hay un vendedor de hierbas en la ciudad. Puedes encontrar a Tommy Palahonda en la sala del artesano, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 연금술사 그린모스는 별의 시장에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你正在寻找的药剂师。他配制一些真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……绿苔药师在工匠大厅出售他的商品。我会在你的地图上标记这个位置。', `MaleText_loc5`='你在找藥劑師對嗎。他能製作真的很神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...藥劑師綠苔在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... el boticario Verdemusgo vende sus mercancías en la sala del artesano. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 연금술사 그린모스는 별의 시장에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你正在寻找的药剂师。他配制一些真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……绿苔药师在工匠大厅出售他的商品。我会在你的地图上标记这个位置。', `FemaleText_loc5`='你在找藥劑師對嗎。他能製作真的很神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...藥劑師綠苔在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... el boticario Verdemusgo vende sus mercancías en la sala del artesano. Te marcaré su ubicación en el mapa.' WHERE `ID`=64872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끈한 요리를 만들고 싶으신가요? 필요한 건 모두 조조에게서 구할 수 있을 겁니다. 조조는 별의 시장에서 장사를 하고 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='准备煮一顿热饭吗？你可以在乔乔那找到你所需的一切。她在工匠大厅出售商品。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='準備好煮一桌熱騰騰的飯菜?你可以在喬喬那裡找到你一切所需。她在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Quieres cocinar una comida caliente? Jojo te facilitará todo lo que necesites. Vende sus mercancías en la sala del artesano.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='따끈한 요리를 만들고 싶으신가요? 필요한 건 모두 조조에게서 구할 수 있을 겁니다. 조조는 별의 시장에서 장사를 하고 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='准备煮一顿热饭吗？你可以在乔乔那找到你所需的一切。她在工匠大厅出售商品。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='準備好煮一桌熱騰騰的飯菜?你可以在喬喬那裡找到你一切所需。她在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Quieres cocinar una comida caliente? Jojo te facilitará todo lo que necesites. Vende sus mercancías en la sala del artesano.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이는 모두 별의 시장에서 일합니다. 건물 입구에 들어서서 왼쪽으로 가면 나오지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='铁匠一直在工匠大厅内工作，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='鐵匠們全都在工匠大廳裡做事，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Todos los herreros trabajan en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='대장장이는 모두 별의 시장에서 일합니다. 건물 입구에 들어서서 왼쪽으로 가면 나오지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='铁匠一直在工匠大厅内工作，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='鐵匠們全都在工匠大廳裡做事，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Todos los herreros trabajan en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광용품은 별의 시장에서 구입할 수 있습니다. 건물 입구에 들어서서 왼쪽으로 가면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='你可以在工匠大厅内购买采矿用品，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='採礦工具全都在工匠大廳裡買，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Puedes comprar suministros de minería en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='채광용품은 별의 시장에서 구입할 수 있습니다. 건물 입구에 들어서서 왼쪽으로 가면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='你可以在工匠大厅内购买采矿用品，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='採礦工具全都在工匠大廳裡買，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Puedes comprar suministros de minería en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별의 시장에 기계공학자가 있었던 것 같군요. 건물 입구에 들어서서 왼쪽으로 가면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='我依稀记得在工匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='我記得工匠大廳裡有個工程師，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Creo recordar que hay un ingeniero en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='별의 시장에 기계공학자가 있었던 것 같군요. 건물 입구에 들어서서 왼쪽으로 가면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='我依稀记得在工匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='我記得工匠大廳裡有個工程師，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Creo recordar que hay un ingeniero en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공용품과 가죽 말입니까? 무두장이를 찾는 거로군요. 제 기억이 맞다면 별의 시장에 한 명 있습니다.$B$B지도에 위치를 표시해 드리지요.', `MaleText_loc4`='皮革加工和皮草？你肯定在寻找一位皮匠。如果我没记错的话，应该在工匠大厅内。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='製皮和材料?你要找的是個皮匠。沒記錯的話，工匠大廳裡有一個，$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Peletería y cuero? Debes de estar buscando un peletero. Hay uno en la sala del artesano, creo recordar.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='가죽세공용품과 가죽 말입니까? 무두장이를 찾는 거로군요. 제 기억이 맞다면 별의 시장에 한 명 있습니다.$B$B지도에 위치를 표시해 드리지요.', `FemaleText_loc4`='皮革加工和皮草？你肯定在寻找一位皮匠。如果我没记错的话，应该在工匠大厅内。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='製皮和材料?你要找的是個皮匠。沒記錯的話，工匠大廳裡有一個，$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Peletería y cuero? Debes de estar buscando un peletero. Hay uno en la sala del artesano, creo recordar.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 부상이 심하지는 않았으면 좋겠군요! 치유사들은 주 전당의 중앙 계단 오른쪽에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='噢，我希望伤势并不严重！治疗者在主大厅内，也就是中央楼梯的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='喔，我希望傷勢不嚴重!治療師們都在主廳裡，就在中央樓梯的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¡Oh, espero que la lesión no sea grave! Puedes encontrar a los sanadores en la sala principal, justo a la izquierda de las escaleras centrales.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 부상이 심하지는 않았으면 좋겠군요! 치유사들은 주 전당의 중앙 계단 오른쪽에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='噢，我希望伤势并不严重！治疗者在主大厅内，也就是中央楼梯的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='喔，我希望傷勢不嚴重!治療師們都在主廳裡，就在中央樓梯的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¡Oh, espero que la lesión no sea grave! Puedes encontrar a los sanadores en la sala principal, justo a la izquierda de las escaleras centrales.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공사신가요? 좋은 기술이지요. 보석세공용품은 별의 시장에 있는 베로에게서 살 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='珠宝加工？这的确是件精细活儿。你可以从工匠大厅的贝诺那购买物资。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='珠寶設計?那真是很不錯的技藝。你可以在工匠大廳跟貝羅買材料。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Joyería? Desde luego, es un trabajo delicado. Puedes comprar material a Bero en la sala del artesano.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='보석세공사신가요? 좋은 기술이지요. 보석세공용품은 별의 시장에 있는 베로에게서 살 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='珠宝加工？这的确是件精细活儿。你可以从工匠大厅的贝诺那购买物资。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='珠寶設計?那真是很不錯的技藝。你可以在工匠大廳跟貝羅買材料。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Joyería? Desde luego, es un trabajo delicado. Puedes comprar material a Bero en la sala del artesano.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식과 음료를 찾으십니까? 그렇다면 여관에 있는 스웨디시 셰프를 찾아가십시오.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你在寻找食物和饮料吗？如果是的话，客栈的晃碟大厨那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='你在找吃的和喝的嗎?那樣的話，旅店裡的揮灑料理大廚有你所想要的一切。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Estás buscando comida y bebida? Si es así, el chef Sue Ko de la posada tiene justo lo que necesitas.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='음식과 음료를 찾으십니까? 그렇다면 여관에 있는 스웨디시 셰프를 찾아가십시오.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你在寻找食物和饮料吗？如果是的话，客栈的晃碟大厨那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='你在找吃的和喝的嗎?那樣的話，旅店裡的揮灑料理大廚有你所想要的一切。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Estás buscando comida y bebida? Si es así, el chef Sue Ko de la posada tiene justo lo que necesitas.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술을 찾으십니까? 양조사 둘이 맛 좋은 술을 팔면서 이곳을 떠돌아다니지요.$B$B혹시라도 못 만난다면, 꾀꼬리 휴게실의 하라 에일벨리와 여관의 사르야 티플라워에게서 바로 살 수 있습니다.', `MaleText_loc4`='在找啤酒吗？好的，有两名酒仙在城市里徘徊，出售优良的啤酒。$B$B如果你没有遇见他们，夜莺旅馆的哈兰·酒腹或旅店的萨娅·茗流可以帮你安排好一切的。', `MaleText_loc5`='找酒喝是吧?好，城市裡有兩個釀酒大師在沿街叫賣他們的頂級美酒。$B$B如果你沒遇到他們，夜鶯迎賓廳的哈拉·酒肚和旅店裡的薩雅·茶花可以解決你的困擾。', `MaleText_loc7`='Buscas cerveza, ¿eh? Bueno, hay dos maestros cerveceros por la ciudad vendiendo sus excelentes brebajes.$B$BSi no te los encuentras, Hara Panza Llena, en el Salón del Ruiseñor, o Sarya Té Floral, en la posada, te harán el favor.', `FemaleText_loc1`='술을 찾으십니까? 양조사 둘이 맛 좋은 술을 팔면서 이곳을 떠돌아다니지요.$B$B혹시라도 못 만난다면, 꾀꼬리 휴게실의 하라 에일벨리와 여관의 사르야 티플라워에게서 바로 살 수 있습니다.', `FemaleText_loc4`='在找啤酒吗？好的，有两名酒仙在城市里徘徊，出售优良的啤酒。$B$B如果你没有遇见他们，夜莺旅馆的哈兰·酒腹或旅店的萨娅·茗流可以帮你安排好一切的。', `FemaleText_loc5`='找酒喝是吧?好，城市裡有兩個釀酒大師在沿街叫賣他們的頂級美酒。$B$B如果你沒遇到他們，夜鶯迎賓廳的哈拉·酒肚和旅店裡的薩雅·茶花可以解決你的困擾。', `FemaleText_loc7`='Buscas cerveza, ¿eh? Bueno, hay dos maestros cerveceros por la ciudad vendiendo sus excelentes brebajes.$B$BSi no te los encuentras, Hara Panza Llena, en el Salón del Ruiseñor, o Sarya Té Floral, en la posada, te harán el favor.' WHERE `ID`=64881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단것이 당기시나요? 그렇다면 홍모란을 찾으셔야지요.$B$B홍모란은 보통 중앙 난간뜰이나 주 전당을 돌아다닌답니다.', `MaleText_loc4`='嘴馋想要吃些甜品吗？你需要找到粉牡丹。$B$B她通常在神殿的前露台或正殿徘徊。', `MaleText_loc5`='忍不住想吃甜食嗎?你得去找粉紅牡丹。$B$B她通常在前臺或寺廟大殿那裡那裡遊走。', `MaleText_loc7`='¿Te apetece algo dulce? Tienes que buscar a Peonía Rosada.$B$BSuele estar dando vueltas por el patio delantero o la sala principal del santuario.', `FemaleText_loc1`='단것이 당기시나요? 그렇다면 홍모란을 찾으셔야지요.$B$B홍모란은 보통 중앙 난간뜰이나 주 전당을 돌아다닌답니다.', `FemaleText_loc4`='嘴馋想要吃些甜品吗？你需要找到粉牡丹。$B$B她通常在神殿的前露台或正殿徘徊。', `FemaleText_loc5`='忍不住想吃甜食嗎?你得去找粉紅牡丹。$B$B她通常在前臺或寺廟大殿那裡那裡遊走。', `FemaleText_loc7`='¿Te apetece algo dulce? Tienes que buscar a Peonía Rosada.$B$BSuele estar dando vueltas por el patio delantero o la sala principal del santuario.' WHERE `ID`=64882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빵 상인은 일곱 별의 제단 곳곳을 돌아다니지만, 보통은 주 전당이나 중앙 난간뜰에 있지요.', `MaleText_loc4`='面包师通常在神殿徘徊。他徘徊在正殿周围或露台上。', `MaleText_loc5`='烘焙師通常在寺廟附近遊走。他就在大殿或者外面的平臺上。', `MaleText_loc7`='El panadero suele estar dando vueltas alrededor del santuario. Estará en la sala principal o fuera, en el patio.', `FemaleText_loc1`='빵 상인은 일곱 별의 제단 곳곳을 돌아다니지만, 보통은 주 전당이나 중앙 난간뜰에 있지요.', `FemaleText_loc4`='面包师通常在神殿徘徊。他徘徊在正殿周围或露台上。', `FemaleText_loc5`='烘焙師通常在寺廟附近遊走。他就在大殿或者外面的平臺上。', `FemaleText_loc7`='El panadero suele estar dando vueltas alrededor del santuario. Estará en la sala principal o fuera, en el patio.' WHERE `ID`=64883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마이클 베데르닉과 이야기하면 됩니다. 고기를 잔뜩 갖고 있거든요.$B$B지도에 위치를 표시해 드리지요. 행운을 빕니다!', `MaleText_loc4`='你需要与米歇尔·扫榻谈谈。他供应充足的肉类。$B$B我会在你的地图上标记这个位置。祝你好运！', `MaleText_loc5`='你得去找麥可·貝德尼克。他有充足的肉類補給。$B$B我會替你在地圖上標出位置。祝好運!', `MaleText_loc7`='Tienes que hablar con Michael Bedernik. Tiene un amplio surtido de carnes.$B$BTe marcaré su ubicación en el mapa. ¡Buena suerte!', `FemaleText_loc1`='마이클 베데르닉과 이야기하면 됩니다. 고기를 잔뜩 갖고 있거든요.$B$B지도에 위치를 표시해 드리지요. 행운을 빕니다!', `FemaleText_loc4`='你需要与米歇尔·扫榻谈谈。他供应充足的肉类。$B$B我会在你的地图上标记这个位置。祝你好运！', `FemaleText_loc5`='你得去找麥可·貝德尼克。他有充足的肉類補給。$B$B我會替你在地圖上標出位置。祝好運!', `FemaleText_loc7`='Tienes que hablar con Michael Bedernik. Tiene un amplio surtido de carnes.$B$BTe marcaré su ubicación en el mapa. ¡Buena suerte!' WHERE `ID`=64884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불장난이 하고 싶으신가요? 말 난 김에 저도 폭죽을 좀 사러 가야겠군요! 상인은 중앙 난간뜰에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='考虑过引爆一个或两个烟花吗？我应该自己去买些烟花！主露台上可以发现供应商。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='想要製造個幾朵火花嗎?我也很想去買一些煙火!煙火商人就在主平臺上。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Estás pensando en prender un par de chispas? ¡Tendría que ir yo mismo a comprar unos fuegos artificiales! El vendedor se encuentra fuera, en el patio principal.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='불장난이 하고 싶으신가요? 말 난 김에 저도 폭죽을 좀 사러 가야겠군요! 상인은 중앙 난간뜰에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='考虑过引爆一个或两个烟花吗？我应该自己去买些烟花！主露台上可以发现供应商。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='想要製造個幾朵火花嗎?我也很想去買一些煙火!煙火商人就在主平臺上。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Estás pensando en prender un par de chispas? ¡Tendría que ir yo misma a comprar unos fuegos artificiales! El vendedor se encuentra fuera, en el patio principal.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=64885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 호랑이시여, 안개 너머에서 온 이방인들은 신뢰할 수 없습니다. 비취 숲에 있는 잔해들이 그 증겁니다.', `MaleText_loc4`='虎神，不能相信那些来自迷雾之外的陌生人。翡翠林中的残骸便是最好的证明。', `MaleText_loc5`='白虎，這些來自迷霧之外的陌生人是不能信任的，翠玉林的殘骸就是最好的證明。', `MaleText_loc7`='Gran tigre, no podemos confiar en los forasteros que han surgido de la niebla. El desastre de El Bosque de Jade es la prueba.' WHERE `ID`=64886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비전 장비를 실은 우리 비행선이 도착하면, 모두가 섬과 함께 박살이 날 겁니다.', `MaleText_loc4`='一艘飞艇正在逼近，上面装载的弹药足以夷平塞拉摩，炸飞岛上所有人。', `MaleText_loc5`='眼下就有一艘飛船慢慢飛近，滿載可將塞拉摩島夷平的秘法能量，島上的人卻還渾然不覺。', `MaleText_loc7`='Ahora mismo se acerca una nave. Su munición arcana arrasará Isla Theramore y a todos sus habitantes.' WHERE `ID`=64887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 난 내 눈으로 직접 봤네. 모구 군단이 힘으로 골짜기를 뒤흔드는 모습을. 우리에겐 그런 대규모 전투 경험이 없네!', `MaleText_loc4`='……我亲眼见过他们：魔古军团正在猛攻锦绣谷。我们可不擅长大规模作战！', `MaleText_loc5`='...我親眼見到了:魔古大軍，成群結隊地衝進恆春谷。我們沒有受過大規模作戰的訓練!', `MaleText_loc7`='... Las he visto con mis propios ojos: legiones mogu que invaden el valle. ¡No estamos adiestrados para este tipo de combate!' WHERE `ID`=64888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘못을 바로잡을 기회를 주세요.', `MaleText_loc4`='给我们纠正错误的机会吧。', `MaleText_loc5`='給我們修正錯誤的機會。', `MaleText_loc7`='Dennos una oportunidad para corregir las cosas.' WHERE `ID`=64889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐군요. 혹시라도 실버문을 지나면 한번 들르십시오. 알 디엘 샬라...', `MaleText_loc4`='好了。要是你途径银月城，来跟我打个招呼，好吗？祝你好运……', `MaleText_loc5`='好了。要是你經過銀月城，就來打聲招呼吧，嗯?Al diel shala(旅途平安)...', `MaleText_loc7`='Muy bien. Si pasan por Lunargenta, vengan a hacerme una visita, ¿de acuerdo? Al diel shala…' WHERE `ID`=64890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 여행자님. 황금 등불에 잘 오셨어요!', `FemaleText_loc4`='你好，旅行者。欢迎光临金色神灯！', `FemaleText_loc5`='你好啊，旅人。歡迎來到金燈籠!', `FemaleText_loc7`='Saludos, viajante. ¡Te doy la bienvenida a El Farol Áureo!' WHERE `ID`=64892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지친 발을 쉬게 해 주세요, $r님. 안에는 좋은 음식과 음료가 있답니다.', `FemaleText_loc4`='停下脚步，休息一会，$r。精美的食物和饮料等着你。', `FemaleText_loc5`='讓你疲憊的雙足休息一下吧，$r。裡面有美味的食物和飲料等著你。', `FemaleText_loc7`='Reposa tus cansados pies, $r. Te esperan una buena comida y bebida.' WHERE `ID`=64893;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 너무 야위셨네요, $r님. 뭔가 드셔야겠어요. 먹을 것을 가져다 드릴 테니 앉으세요.', `FemaleText_loc4`='噢，你看起来很瘦，$r。你必须吃些东西。坐下，我给你拿些吃的东西。', `FemaleText_loc5`='喔，你看起來太瘦了，$r。你必須吃點東西。坐下來我去幫你準備。', `FemaleText_loc7`='Oh, estás en los huesos, $r. Tienes que comer algo. Siéntate y te prepararé alguna cosa.' WHERE `ID`=64894;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황금 등불에서는 술이 마르는 날이 없고, 빈 술통이 안 굴러다니는 날이 없지요! 뭘 가져다 드릴까요?', `FemaleText_loc4`='在金色神灯，大家吃喝不停，这里是客流不断！你想要些什么吗？', `FemaleText_loc5`='在金燈籠，酒閥不會關上，酒桶不會停止滾動!你想要什麼嗎?', `FemaleText_loc7`='¡Aquí en El Farol Áureo, los grifos nunca se vacían y los barriles nunca paran de rodar! ¿Qué te pongo?' WHERE `ID`=64895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원꽃 골짜기 최고의 여관, 황금 등불에 잘 오셨어요. 혹시라도 누가 반박하려 한다면, 제 주먹을 보여주겠어요.', `FemaleText_loc4`='欢迎光临谷里最好的旅店——金色神灯。如果有人想跟我争，我就让他尝尝我的拳头。', `FemaleText_loc5`='歡迎來到金燈籠，恆春谷裡最好的旅店。如果有人想跟我爭論這一點，我會讓他們嚐嚐我的拳頭。', `FemaleText_loc7`='Te doy la bienvenida a El Farol Áureo, la mejor posada del valle. Si alguien me lleva la contraria, tendrá que discutirlo con mis puños.' WHERE `ID`=64896;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 여관의 깃털 침대는 사천 리 안에서 가장 폭신하지요. 한 번 누워 보시겠어요?', `FemaleText_loc4`='我这里有最柔软的羽毛床，千里难寻。你想试试吗？', `FemaleText_loc5`='我這裡有千哩內你能找到最柔軟的羽毛床。你想要試試看嗎?', `FemaleText_loc7`='Tengo las camas de plumas más suaves en mil kilómetros a la redonda. ¿Te gustaría probar una?' WHERE `ID`=64897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='든든히 먹고 계시겠지요, $r님? 부디 몸을 좀 챙기세요.', `FemaleText_loc4`='你吃饱了吗，$r？请记得要好好照顾自己。', `FemaleText_loc5`='你吃得夠嗎，$r?請記得照顧你自己啊。', `FemaleText_loc7`='¿Estás comiendo suficiente, $r? Recuerda que tienes que cuidarte.' WHERE `ID`=64898;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 여관은 집만큼, 아니 집보다 더 안락하답니다. 이곳에 계시는 동안 편히 지내세요.', `FemaleText_loc4`='我的旅店舒适得像家一样。请别客气，随意。', `FemaleText_loc5`='我的旅店有所有家的舒適，還不只呢。在這裡請不要客氣。', `FemaleText_loc7`='Mi posada tiene todas las comodidades de un hogar, y muchas más. Por favor, siéntete como en tu casa aquí.' WHERE `ID`=64899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용액, 물약, 비약, 영약 있습니다!', `MaleText_loc4`='酊剂、药水、药膏和补品！', `MaleText_loc5`='酊劑、藥水、藥膏和滋補劑!', `MaleText_loc7`='¡Tinturas, pociones, filtros y tónicos!' WHERE `ID`=64900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약병, 약병을 여기로 가져오십시오!', `MaleText_loc4`='瓶子，来买瓶子！', `MaleText_loc5`='瓶子，來這買瓶子喔!', `MaleText_loc7`='¡Viales, comprad viales aquí!' WHERE `ID`=64901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끈따끈한 갓 구운 빵 팔아요!', `MaleText_loc4`='热乎乎，新出炉的面包！', `MaleText_loc5`='熱呼呼、新鮮烤好的麵包喔!', `MaleText_loc7`='¡Pan caliente recién hecho!' WHERE `ID`=64902;
