UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고치 안으로 도망칩니다!', `MaleText_loc4`='%s撤退到她的护体中！', `MaleText_loc5`='%s撤退到她的繭裡!', `MaleText_loc7`='¡%s se retira a su crisálida!', `FemaleText_loc1`='%s|1이;가; 고치 안으로 도망칩니다!', `FemaleText_loc4`='%s撤退到她的护体中！', `FemaleText_loc5`='%s撤退到她的繭裡!', `FemaleText_loc7`='¡%s se retira a su crisálida!' WHERE `ID`=64906;
