UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사랑하는 사람에게 꽃을 선물하는 건 어떠세요? 꽃 사세요!', `FemaleText_loc4`='美丽的鲜花送给你爱的人！拿好你的鲜花！', `FemaleText_loc5`='美麗的鮮花送給你愛人!來買花!', `FemaleText_loc7`='¡Flores preciosas para tus seres queridos! ¡Compra flores!' WHERE `ID`=64909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='귀한 꽃이 시들기 전에 사 가세요! 꽃 팔아요!', `FemaleText_loc4`='在这些罕见的花朵枯萎之前，取得它们！鲜花待售！', `FemaleText_loc5`='在凋謝之前快來買這些稀有的鮮花!鮮花拍賣!', `FemaleText_loc7`='¡Haceos con estas flores excepcionales antes de que se marchiten! ¡Flores a la venta!' WHERE `ID`=64910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 샤가 불협화음의 장을 |cFFFF0404|Hspell:126121|h[타락]|h|r시킵니다!', `MaleText_loc4`='惧之煞|cFFFF0404|Hspell:126121|h[腐蚀]|h|r不谐力场！', `MaleText_loc5`='恐懼之煞|cFFFF0404|Hspell:126121|h[腐化]|h|r了一片不和諧的音域!', `MaleText_loc7`='¡El sha del miedo |cFFFF0404|Hspell:126121|h[Corrompe]|h|r un campo de disonancia!', `FemaleText_loc1`='공포의 샤가 불협화음의 장을 |cFFFF0404|Hspell:126121|h[타락]|h|r시킵니다!', `FemaleText_loc4`='惧之煞|cFFFF0404|Hspell:126121|h[腐蚀]|h|r不谐力场！', `FemaleText_loc5`='恐懼之煞|cFFFF0404|Hspell:126121|h[腐化]|h|r了一片不和諧的音域!', `FemaleText_loc7`='¡El sha del miedo |cFFFF0404|Hspell:126121|h[Corrompe]|h|r un campo de disonancia!' WHERE `ID`=64911;
