UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 운동할 시간이다.', `MaleText_loc4`='好吧，舒展一下身体。', `MaleText_loc5`='該伸展一下筋骨囉。', `MaleText_loc7`='Bueno, es hora de desperezarse.' WHERE `ID`=64914;
