UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하, 호랑이한테 물어 오라고 하면 이렇게 되는구나.', `MaleText_loc4`='呵呵，这就是我试图让一只猫去捡回来的东西。', `MaleText_loc5`='嘿嘿，這就是我要一隻貓去接東西的下場。', `MaleText_loc7`='Jeje, eso me pasa por decirle a un gato que busque.' WHERE `ID`=64916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 우리 엄마, 아빠가 좋아.', `MaleText_loc4`='我爱我的妈妈和爸爸。', `MaleText_loc5`='我愛我老媽和老爸。', `MaleText_loc7`='Quiero a mi papá y mi mamá.' WHERE `ID`=64917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐요! 저 녀석, 아침엔 항상 조금 기분이 안 좋아요.', `MaleText_loc4`='看看他！早上的时候他总是有些脾气暴躁。', `MaleText_loc5`='看看他!他早上總是有點暴躁。', `MaleText_loc7`='¡Míralo! Siempre está un poco malhumorado por las mañanas.' WHERE `ID`=64918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 저것 봐! 엄청 크다!', `MaleText_loc4`='哇哦，瞧瞧那个！真大啊！', `MaleText_loc5`='哇喔，看那個!超大的!', `MaleText_loc7`='¡Guau! ¡Mira eso! ¡Es enorme!' WHERE `ID`=64919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집을 두 개 합친 것보다 더 커!', `MaleText_loc4`='比两座房子还大！', `MaleText_loc5`='牠比兩棟房子還要大!', `MaleText_loc7`='¡Es más grande que dos casas juntas!' WHERE `ID`=64920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 가까이 가면 안 돼, 마이아. 네 머리를 물어뜯을 거야!', `MaleText_loc4`='马亚，不要太靠近！它会咬掉你的头！', `MaleText_loc5`='不要太靠近，麥雅!它會把你的頭咬掉!', `MaleText_loc7`='¡No te acerques mucho, Maia! ¡Podría arrancarte la cabeza!' WHERE `ID`=64921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니거든, 이 바보야!', `FemaleText_loc4`='不，它不是的！不要傻了！', `FemaleText_loc5`='不，才不是!別傻了!', `FemaleText_loc7`='¡No me va a hacer nada! No seas tonto.' WHERE `ID`=64922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사탕 먹고 싶어!', `FemaleText_loc4`='我想要些糖果！', `FemaleText_loc5`='我想要糖果!', `FemaleText_loc7`='¡Quiero caramelos!' WHERE `ID`=64923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 호랑이 만지지 마, 마이아! 너를 저녁으로 먹어 버릴걸!', `MaleText_loc4`='马亚，不要触摸大老虎！它会把你当美餐！', `MaleText_loc5`='不要碰大老虎，麥雅!它會把你當晚餐吃掉!', `MaleText_loc7`='¡No toques al gran tigre, Maia! ¡Te va a comer para cenar!' WHERE `ID`=64924;
