UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마, 마이아. 내가 지켜줄게.', `MaleText_loc4`='不要担心，马亚，我会保护你。', `MaleText_loc5`='別擔心，麥雅，我會保護你。', `MaleText_loc7`='No te preocupes, Maia, yo te protegeré.' WHERE `ID`=64928;
