UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 집중의 눈동자를 되찾게 둘 순 없어요. 당신이 호드의 잔당을 없애면, 내가 눈동자를 확보하죠.', `FemaleText_loc4`='绝对不能让部落找到聚焦之虹。消灭他们军队的所有残余力量，我会保护好神器。', `FemaleText_loc5`='絕對不能讓部落奪回聚源虹膜。消滅他們剩餘的部隊，我會保護神器。', `FemaleText_loc7`='No podemos permitir que la Horda recupere el Iris de enfoque. Eliminen todo lo que queda de su escuadrón y yo aseguraré el artefacto.' WHERE `ID`=64956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순간이동하려면 눈동자에 정신을 집중해야 해요. 날 지켜 줘요!', `FemaleText_loc4`='我必须在传送前调校好聚焦之虹。保护我！', `FemaleText_loc5`='傳送之前聚源虹膜必須和我同步調和。保護我!', `FemaleText_loc7`='Debo armonizar el Iris de enfoque antes de moverlo. ¡Protéjanme!' WHERE `ID`=64957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 종족은 비열한 겁쟁이다, 오크. 미친 개나 다름없지. 모조리 죽여 주마.', `FemaleText_loc4`='你的族人都是卑劣的懦夫，兽人。你们都会像疯狗一样被消灭，别想得到聚焦之虹。', `FemaleText_loc5`='你們是卑劣的懦夫，獸人。你們只不過是一群瘋狗，你們一定會被消滅的!', `FemaleText_loc7`='Tu gente y tú son unos cobardes miserables, orco. No son más que perros rabiosos y nosotros los sacrificaremos.' WHERE `ID`=64958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자비에 침을 뱉는다? 그렇다면 너희에게 자비는 없다. 학살을 원하느냐? 가로쉬는 생각보다 훨씬 많은 피를 볼 것이다.', `FemaleText_loc4`='对怜悯吐口水？那你就得不到怜悯了。你想要杀戮？那就让加尔鲁什给你收尸吧。', `FemaleText_loc5`='你們覺得慈悲很可笑?那你們就不會得到任何憐憫。你們想要大屠殺?卡爾洛斯會得到比他想要的鮮血還要多更多!', `FemaleText_loc7`='¿Escupes ante la piedad? Entonces no la tendrás. ¿Quieres una masacre? Garrosh tendrá más sangre de la que se esperaba.' WHERE `ID`=64959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 널 지킬 수 없다! 저 계집을 죽이고, 폭탄을 가져와라!', `MaleText_loc4`='恐怕没人能保护你。杀了这个贱人，把那炸弹带回来。', `MaleText_loc5`='沒有人能保護你。殺死這個塞拉摩賤人，然後把炸彈拿來給我。', `MaleText_loc7`='Nadie puede protegerte. Maten a la maldita Valiente y tráiganme esa bomba.' WHERE `ID`=64960;
