UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말은 씩씩하구나. 네가 자비를 구걸할 때 그 얼굴에 침을 뱉어 주마.', `MaleText_loc4`='真是豪言壮语啊。等你乞求怜悯时，我会把口水吐你脸上。', `MaleText_loc5`='勇敢的言詞，法師。等你向我求饒時，我會當面吐妳口水。', `MaleText_loc7`='Valientes palabras, maga. Cuando supliques piedad te escupiré en la cara.' WHERE `ID`=64962;
