UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 나 같은 사람을 좋아할 것 같소? 나는... 털이 별로 없는데!', `MaleText_loc4`='你觉得她可能对我这样的人来电吗？我很……不赞同！', `MaleText_loc5`='你覺得她可能會對我這種人有感覺嗎?我是那麼地...無毛!', `MaleText_loc7`='¿Crees que podría llegar a sentir algo por alguien como yo? Soy tan... ¡poco peludo!' WHERE `ID`=64966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 가슴 털이 수북한 남자를 좋아할 거요. 난 어쩌면 좋소?', `MaleText_loc4`='我敢打赌，她喜欢雄壮的男人。我该怎么办？', `MaleText_loc5`='我敢說她一定喜歡她的男人有毛茸茸的胸膛。我該怎麼辦?', `MaleText_loc7`='Seguro que le gustan los hombres con pelo en el pecho. ¿Qué puedo hacer?' WHERE `ID`=64967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도원에 들어가서 수도사 훈련을 받으면 나을 것 같소? 그러면 그녀가 감탄할까?', `MaleText_loc4`='难道你觉得我应该去那些禅院中受训做一名武僧？你知道的，为了让她留下深刻的印象。', `MaleText_loc5`='你覺得我應該去找一座僧院受訓成為一個武僧嗎?你知道，讓她印象深刻?', `MaleText_loc7`='¿Crees que debería ir a uno de esos monasterios e instruirme para convertirme en monje? Ya sabes, para impresionarla...' WHERE `ID`=64968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 똥배가 없소. 똥배가 필요하다오. 그래, 똥배를 만들어야겠어!', `MaleText_loc4`='我没有大啤酒肚。我需要一个大啤酒肚。好吧。说做就做！', `MaleText_loc5`='我沒有大大的啤酒肚。我需要一個大啤酒肚。就是這樣。我正在努力!', `MaleText_loc7`='No tengo barriga cervecera. Necesito una barriga cervecera. Muy bien. ¡Manos a la obra!' WHERE `ID`=64969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀는 술이 센 남자를 좋아한다오. 그래서 매일 밤 진탕 술을 마셔서 주량을 늘리고 있지.', `MaleText_loc4`='我知道她喜欢千杯不醉的男人，所以我每天晚上喝得烂醉，来锻炼我的酒量。', `MaleText_loc5`='我知道她喜歡有酒量的男人，所以我每晚都喝得爛醉鍛鍊酒量。', `MaleText_loc7`='Sé que le gustan los hombres que aguantan el alcohol, así que para aumentando mi tolerancia me estoy emborrachando todas las noches.' WHERE `ID`=64970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남자들은 원래 이렇게 고백에 뜸을 들이나요?', `FemaleText_loc4`='怎么所有的男人都不急着约女人出来？', `FemaleText_loc5`='所有男人在邀女人出去時都這麼遲鈍嗎?', `FemaleText_loc7`='¿Son todos los hombres tan lentos a la hora de pedir una cita a una mujer?' WHERE `ID`=64971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절 좋아하는 것 같긴 한데, 확실히는 모르겠어요. 어떻게 생각하세요, $r님?', `FemaleText_loc4`='我觉得他喜欢我，但我不确定。你是怎么想的，$r？', `FemaleText_loc5`='我想他喜歡我，但是我不確定。你覺得怎樣，$r?', `FemaleText_loc7`='Creo que le gusto, pero no estoy segura. ¿A ti qué te parece, $r?' WHERE `ID`=64972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 그가 내가 너무 털북숭이라고 생각하면 어쩌죠? 까맣고 하얀 여자를 싫어하면 어떡해요?', `FemaleText_loc4`='噢，不，如果他认为我太多毛了呢？如果他不喜欢黑白相间的女子呢？', `FemaleText_loc5`='喔不，如果他覺得我毛太多怎麼辦?如果他不喜歡女人毛色是黑白的呢?', `FemaleText_loc7`='Oh no, ¿y si piensa que soy demasiado peluda? ¿Y si no le gustan las mujeres blancas y negras?' WHERE `ID`=64973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='열심히 꼬리를 치고 있지만, 전혀 눈치를 못 채는 것 같아요!', `FemaleText_loc4`='我使出浑身解数调情，但我想他没收到讯息！', `FemaleText_loc5`='我已經盡量和他調情了，但我不認為他有查覺到!', `FemaleText_loc7`='¡Estoy tonteando todo lo que puedo, pero creo que no pilla las indirectas!' WHERE `ID`=64974;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 계속 만능 스패너와 과충전된 축전기 얘기만 늘어놓고 있어요. 여자 꼬시는 데 정말 도가 텄지 뭐예요. 쯧!', `FemaleText_loc4`='他总是谈论扳手和超载电容器。他肯定知道哄骗女孩。嗷！', `FemaleText_loc5`='他一直在談論扳手和超載電容器。他還真是會讓女孩會錯意。吼!', `FemaleText_loc7`='No deja de hablar de llaves de tuerca arcoluz y de condensadores sobrecargados. Desde luego, sabe cómo hablar con una chica. ¡Rawr!' WHERE `ID`=64975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그의 예쁘장한 얼굴이 마음에 들어요.', `FemaleText_loc4`='我当然喜欢他漂亮的脸蛋。', `FemaleText_loc5`='我還真喜歡他帥氣的臉。', `FemaleText_loc7`='Me encanta su cara bonita.' WHERE `ID`=64976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 얼라이언스 생존자들이! 지원군을... 요청한다...', `MaleText_loc4`='有联盟幸存者！快派……援军……', `MaleText_loc5`='有聯盟倖存者!快派出...增援...', `MaleText_loc7`='¡Hay sobrevivientes de la Alianza! Envíen... refuerzos…' WHERE `ID`=64977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사냥꾼이 갖고 싶어 하는 활을 차지한 적이 있었어요."', `MaleText_loc4`='[%s]忏悔：我曾经拿了一张猎人想要的弓。', `MaleText_loc5`='[%s]坦承:我曾經搶走一把獵人想要的弓。', `MaleText_loc7`='[%s] confiesa: Una vez cogí un arco que quería un cazador.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사냥꾼이 갖고 싶어 하는 활을 차지한 적이 있었어요."', `FemaleText_loc4`='[%s]忏悔：我曾经拿了一张猎人想要的弓。', `FemaleText_loc5`='[%s]坦承:我曾經搶走一把獵人想要的弓。', `FemaleText_loc7`='[%s] confiesa: Una vez cogí un arco que quería un cazador.' WHERE `ID`=64978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음에 드는 방어구가 있습니까, $r님? 이 희귀한 방어구들은 판다리아에서 가장 험난한 던전에서 실력을 증명해야만 얻을 수 있습니다.$B$B그 던전들은, 직접 찾아서 들어가야 합니다. 빠른 속도로 시험을 통과하는 사람은 방어구 제작 달인들의 환심을 살 수 있고, 그러면 어느 날 희귀한 방어구를 우편으로 받게 될지도 모르지요.', `FemaleText_loc4`='想看些你喜欢的护甲吗，$r？只有你在潘达利亚最具挑战性的地牢中证明自己的价值，你才能获得这些罕见的护甲套件。$B$B你必须寻找这些地牢，并步行进入。以足够快的速度赢得挑战的人们应得到我们大铸甲师的尊敬，也许还会在邮件中收到一个罕见护甲礼物。', `FemaleText_loc5`='有看到你喜歡的護甲嗎，$r?這些稀有的護甲套裝只能藉由在潘達利亞最富挑戰性的地城中證明你的價值才能取得。$B$B你必須步行找出並進入這些地城。以夠快速度通過挑戰的人就能贏得我們的護甲大師的尊敬，並且可能在信箱裡發現稀有護甲禮物在等著他們。', `FemaleText_loc7`='¿Ves alguna armadura que te guste, $r? Solo puedes conseguir estas excepcionales armaduras demostrando tu valía en las mazmorras más peligrosas de Pandaria.$B$BDebes buscar esas mazmorras y acceder a ellas a pie. Aquellos que superen los desafíos con gran rapidez se ganarán el respeto de nuestros maestros armeros, y podrían tener una armadura excepcional esperándoles en el buzón.' WHERE `ID`=64979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 함께하기를, $r.', `MaleText_loc4`='光明与你同在，$r。', `MaleText_loc5`='願光明與你同在，$r。', `MaleText_loc7`='Que la Luz te acompañe, $r.' WHERE `ID`=64980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드 왕자가 무방비한 상태입니다! 왜 호드를 위해 그를 사로잡지 않는 겁니까?', `MaleText_loc4`='暴风城的王子毫无防备！我们为什么不为了部落抓住他呢？', `MaleText_loc5`='暴風城的王子沒有人守護!我們何不把他抓走獻給部落?', `MaleText_loc7`='¡El Príncipe de Ventormenta está desprotegido! ¿Por qué no lo capturamos para la Horda?', `FemaleText_loc1`='스톰윈드 왕자가 무방비한 상태예요! 왜 호드를 위해 그를 사로잡지 않는 거죠?', `FemaleText_loc4`='暴风城的王子毫无防备！我们为什么不为了部落抓住他呢？', `FemaleText_loc5`='暴風城的王子沒有人守護!我們何不把他抓走獻給部落?', `FemaleText_loc7`='¡El Príncipe de Ventormenta está desprotegido! ¿Por qué no lo capturamos para la Horda?' WHERE `ID`=64981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음에 드는 방어구가 있습니까, $r님? 이 희귀한 방어구들은 판다리아에서 가장 험난한 던전에서 실력을 증명해야만 얻을 수 있습니다.$B$B그 던전들은, 직접 찾아서 들어가야 합니다. 빠른 속도로 시험을 통과하는 사람은 방어구 제작 달인들의 환심을 살 수 있고, 그러면 어느 날 희귀한 방어구를 우편으로 받게 될지도 모르지요.', `MaleText_loc4`='想看些你喜欢的护甲吗，$r？只有你在潘达利亚最具挑战性的地牢中证明自己的价值，你才能获得这些罕见的护甲套件。$B$B你必须寻找这些地牢，并步行进入。以足够快的速度赢得挑战的人们应得到我们大铸甲师的尊敬，也许还会在邮件中收到一个罕见护甲礼物。', `MaleText_loc5`='有看到你喜歡的護甲嗎，$r?這些稀有的護甲套裝只能藉由在潘達利亞最富挑戰性的地城中證明你的價值才能取得。$B$B你必須步行找出並進入這些地城。以夠快速度通過挑戰的人就能贏得我們的護甲大師的尊敬，並且可能在信箱裡發現稀有護甲禮物在等著他們。', `MaleText_loc7`='¿Ves alguna armadura que te guste, $r? Solo puedes conseguir estas excepcionales armaduras demostrando tu valía en las mazmorras más peligrosas de Pandaria.$B$BDebes buscar esas mazmorras y acceder a ellas a pie. Aquellos que superen los desafíos con gran rapidez se ganarán el respeto de nuestros maestros armeros, y podrían tener una armadura excepcional esperándoles en el buzón.' WHERE `ID`=64982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 가로쉬 헬스크림의 신봉자다운 말이오. 우리 "대족장"께서 자랑스러워하시겠군.$b$b그러나 나의 호드는 무방비한 아이와는 싸우지 않소. 또한, 위대한 천신께서 지켜보시는 가운데 감히 이 성스러운 방으로 우리의 전쟁을 끌어들일 생각도 없소.$b$b게다가, 이 아이는 대부족장 바인 블러드후프의 우정과 신임을 얻은 아이요. 그런 연유로, 나는 이 아이를 지키려 하오.$b$b지금으로서는 말이오.', `MaleText_loc4`='哈！口气真像加尔鲁什·地狱咆哮的信徙。我们的“酋长”会感到自豪的。$b$b但是我的部落不与手无寸铁的孩童打仗。我也不敢当着一位至尊天神的面在这个神圣殿堂开战。$b$b此外，这个小子取得了贝恩·血蹄大酋长的友谊和信任。出于这个原因，我要保护他。$b$b至少现在要保护。', `MaleText_loc5`='哈哈!你說話就像個真正的地獄吼學徒一樣。我們的「大酋長」會很驕傲的。$b$b但是我的部落不會對手無寸鐵的小孩動手。我也不敢將我們的戰爭帶到這個神聖的房間，就在聖獸天尊的面前。$b$b此外，這個小孩子獲得了牛頭人酋長貝恩·血蹄的友情和信任。因此，他將受到我的保護。$b$b以目前來說。', `MaleText_loc7`='¡Ja! Has hablado como lo haría un verdadero discípulo de Garrosh Grito Infernal. Nuestro "Jefe de Guerra" estaría orgulloso.$b$bPero MI Horda no ataca a niños indefensos. Y tampoco me atrevería a llevar la guerra a esta cámara sagrada, y ante un Augusto Celestial.$b$bAdemás, el pequeño se ha ganado la amistad y la confianza del Gran jefe Baine Pezuña de Sangre. Por eso, considéralo mi protegido.$b$bPor ahora.' WHERE `ID`=64983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 내 가족은 아주 오래전 이 저주받은 장소의 희생양이 되었다.$B$B겁 없이 강령술에 손대려는 자들이 우리 가족의 운명에서 교훈을 얻길.$B$B내가 저주를 푸는 걸 도와 다오, $c|1이여;여;. 암흑스승 간들링을 없애야 한다.', `MaleText_loc4`='我和我的家人很早以前就是这个地方的牺牲品。$B$B让我们的命运警告那些想要插手巫术的人们。$B$B帮我解除诅咒，$c。消灭黑暗院长加丁。', `MaleText_loc5`='我和我的家族成為了此地的受害者，似乎已經是很久以前的事了。$B$B讓我們的命運做為對其他涉足死靈法術之人的警告。$B$B幫助我解開這個詛咒，$c。消滅黑暗院長加丁。', `MaleText_loc7`='Mi familia y yo caímos víctimas de este lugar me da la sensación que hace mucho tiempo.$B$BQue nuestro destino sirva de advertencia para aquellos que jueguen con la nigromancia. $B$BAyúdame a acabar con la maldición, $c. Destruye al maestro oscuro Gandling.' WHERE `ID`=64984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기...$b$b이 아름다운 곳을 대족장이 파괴할 거라 그 누가 상상이나 했을까.$b$b황금 연꽃은 모구에게 언젠가 이 땅을 다시 빼앗기진 않을까 걱정했소. 보아하니 가로쉬의 교만이 이정도일 거라곤 그들도 차마 생각 못한 것 같군.', `MaleText_loc4`='锦绣谷。$b$b谁能想到，酋长竟然忍心摧毁如此美丽的地方。$b$b金莲教总担心有朝一日，魔古族会重新占领这里。看来他们是低估了加尔鲁什的狂妄程度。', `MaleText_loc5`='恆春谷。$b$b誰想得到那個大酋長有本事摧毀這麼漂亮的地方。$b$b金蓮會擔心有一天魔古會再度控制這裡，但看樣子他們是小看了卡爾洛斯的本事。', `MaleText_loc7`='El Valle de la Flor Eterna.$b$b¿Quién iba a pensar que el Jefe de Guerra sería capaz de destruir un lugar tan hermoso?$b$bEl Loto Dorado temía que los mogu reconquistaran el valle, pero al final resulta que subestimaron el orgullo de Garrosh.' WHERE `ID`=64985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님.$b$b딱 좋을 때 와 주셨군요.', `MaleText_loc4`='噢，你好，$n。$b$b你的时机再好不过了。', `MaleText_loc5`='喔，哈囉，$n。$b$b你的時機挑得不能再更好了。', `MaleText_loc7`='Ah, hola, $n.$b$bNo podrías llegar en mejor momento.' WHERE `ID`=64986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 고향을 잃었지만, 우리가 살아 있는 한... 다른 곳에 고향을 건설하면 됩니다.', `MaleText_loc4`='我们无家可归，但只要我们还活着，就会在其他地方重建家园。', `MaleText_loc5`='我們失去了家園，但只要我們還活著，我們就還能建立家園...在某個地方。', `MaleText_loc7`='Hemos perdido nuestro hogar, pero mientras sigamos vivos, siempre podremos crear un nuevo hogar... en algún lado.' WHERE `ID`=64987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남았으니 하루 더 싸울 수 있겠군요.', `MaleText_loc4`='我们会卷土重来，$r。', `MaleText_loc5`='我們為擇日再戰而活著，$r。', `MaleText_loc7`='Vivimos para luchar otro día, $r.' WHERE `ID`=64988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물소리를 따라오다 보니 이 찬란한 골짜기에 이르렀습니다.$B$B이곳에 있는 웅덩이의 물은 지금까지 한 번도 보지 못한 것입니다.', `MaleText_loc4`='我们循着水声，来到这个壮丽的锦绣谷。$B$B这些池水不同于我们以往所见。', `MaleText_loc5`='我們跟隨著水聲，來到了這個燦爛的峽谷。$B$B我們以前從來沒看過像這些池子裡面的水。', `MaleText_loc7`='Seguimos el sonido del agua y llegamos a este resplandeciente valle.$B$BNunca había visto un agua como la de estas pozas.' WHERE `ID`=64989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 숲에서 일어난 일은 끔찍한 비극이었지요. 실수를 되풀이하지 않으려면, 과거의 실수로부터 배워야만 합니다.$B$B이 도서관은 지식의 보고입니다. 이미 샤에 대해서 많은 것을 알게 되었지요.', `MaleText_loc4`='在翡翠林所发生的是一场可怕的悲剧。我坚信，只有向他们学习，才能避免重蹈覆辙。$B$B这个图书馆里有很多知识。我已经了解到很多关于煞魔的知识。', `MaleText_loc5`='在翠玉林中所發生的是件恐怖的悲劇。我堅信唯一能避免重蹈覆轍的方法，就是從過錯中學習。$B$B在這個圖書館中有許多知識。我已經了解關於煞的許多事了。', `MaleText_loc7`='Lo que ocurrió en el Bosque de Jade fue una tragedia horrible. Estoy convencido de que la única forma de no repetir nuestros errores es aprender de ellos.$b$bHay mucho conocimiento en esta biblioteca. Ya he aprendido mucho sobre los sha.' WHERE `ID`=64990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 길드 금고에서 뭔가 슬쩍한 적이 있어요."', `MaleText_loc4`='[%s]忏悔：我曾从我的公会银行“借过”东西。', `MaleText_loc5`='[%s]坦承:我曾經向我的公會銀行「借貸」過東西。', `MaleText_loc7`='[%s] confiesa: He cogido "prestadas" cosas del banco de mi hermandad.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 길드 금고에서 뭔가 슬쩍한 적이 있어요."', `FemaleText_loc4`='[%s]忏悔：我曾从我的公会银行“借过”东西。', `FemaleText_loc5`='[%s]坦承:我曾經向我的公會銀行「借貸」過東西。', `FemaleText_loc7`='[%s] confiesa: He cogido "prestadas" cosas del banco de mi hermandad.' WHERE `ID`=64991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때는 진위가 이곳의 권좌에 앉아 판다리아 전역을 다스렸습니다.$B$B우리는 고대의 지혜를 되찾을 수 있도록, 역사에서 최대한 교훈을 얻어야 합니다.', `MaleText_loc4`='锦鱼人曾经从这个地方，以这个权力座位统治整个潘达利亚。$B$B我们必须学习所有历史知识，这样，我们才有可能收复失地。', `MaleText_loc5`='曾經，錦魚人從這地方統治著整個潘達利亞，從這個權力的王座。$B$B我們必須向歷史學習所有我們能學到的事物，這樣我們才可能再一次取回我們遠古的智慧。', `MaleText_loc7`='Hubo un tiempo en que los jinyu gobernaban toda Pandaria desde este lugar, desde este trono de poder.$B$BDebemos aprender todo lo que podamos de la historia para poder recuperar nuestra sabiduría ancestral.' WHERE `ID`=64992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 해변에 불시착한 후로 방방곡곡을 돌아다녔지.$B$B옥룡사에서부터 크라사랑 해변, 네베레스트 산 꼭대기까지 안 가본 곳이 없다네!$B$B이 땅은 참 흥미로워. 그래서 지금까지 발견한 것을 모두 기록해 두었지.$B$B빨리 탐험가 연맹 동료들에게 내가 본 것을 이야기해주고 싶어 견딜 수가 없군!', `MaleText_loc4`='我自从溃败流落以这个海岸，便一直流浪。$r！$B$B一直以来，我从青龙寺到卡桑琅海岸，再到不息山山顶。$B$B这个地方很有名，我已经整理了我的所有发现。$B$B我迫不及待地将我的所见所闻告诉我探险者协会协会的同事！', `MaleText_loc5`='自從我墜落在這岸上起，我就一直到處遊蕩探險，$r!$B$B從玉蛟寺到喀撒朗海岸，一路到奈佛勒斯山我都去過!$B$B這裡真是充滿了驚奇，然後我也一直有在記錄我所有的發現。$B$B真等不及要把我看到的一切都告訴探險者協會的同僚啊!', `MaleText_loc7`='¡Desde que atraqué en esta orilla, no he hecho más que vagar sin rumbo, $r!$B$B¡He recorrido desde el Templo del Dragón de Jade hasta la cima del Monte Nieverest!$B$BEsta tierra es excepcional, y he estado catalogando todos mis hallazgos.$B$B¡Estoy deseando contarles a mis compañeros de la Liga de Expedicionarios todo lo que he visto!' WHERE `ID`=64993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 진정 믿을만할 자인지는 절대 모르는 거다. 네가 나라면 알 수 있을지도 모르지만.', `MaleText_loc4`='你永远不知道谁真正可以信任。要是你是我，你就会知道。', `MaleText_loc5`='你永遠不知道誰真的能夠信任。除非你是我;那你就會知道了。', `MaleText_loc7`='Nunca se sabe en quién se puede confiar. A menos que seas yo; entonces lo sabes.' WHERE `ID`=64994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제의 첩자는 없는 곳이 없다.', `MaleText_loc4`='女皇的间谍无处不在。', `MaleText_loc5`='女皇在四處都佈有間諜。', `MaleText_loc7`='La Emperatriz tiene espías por todas partes.' WHERE `ID`=64995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘으로 권력을 얻은 자는, 가끔 그 권력 안에 자신이 혼자 있음을 깨닫게 될 것이다.', `MaleText_loc4`='那些试图通过武力夺取政权的人往往会发现自己孤单。', `MaleText_loc5`='以力量尋求權力之人通常都會發現自己是孤單一人。', `MaleText_loc7`='Los que buscan el poder mediante la fuerza a menudo se encuentran con que se han quedado solos.' WHERE `ID`=64996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모셨던 여제님 역시 두려움과 피해의 망상에 빠져 계셨다. 결과적으로 여제님에게 종말을 가져온 것은 자신의 두려움이었다.', `MaleText_loc4`='我的女皇也恐惧和偏执。她的恐惧最终导致她的灭亡。', `MaleText_loc5`='不只如此，我所服侍的女皇因害怕而變得神經質。最終她自己的恐懼讓她步向了死亡。', `MaleText_loc7`='La emperatriz a la que serví también estaba asustada y paranoica. Al final, fue su miedo lo que propició su caída.' WHERE `ID`=64997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 어릴 때부터 수에 밝았지요!$B$B이곳 원주민들이 제가 암산으로 덧셈, 뺄셈을 하고 미분 방정식을 푸는 걸 보더니, 그 자리에서 바로 절 고용했어요!', `FemaleText_loc4`='我向来擅长算数！$B$B当地人见识了我心算加、减和微分方程的速度后，他们立马就聘用了我！', `FemaleText_loc5`='我總是對數字很有敏感度!$B$B有一次，當地人見識到我飛快的心算加法、減法和各種恆等式之後，當場就雇用了我!', `FemaleText_loc7`='¡Siempre se me han dado muy bien los números!$B$B¡Cuando los nativos se dieron cuenta de lo rápido que sumaba, restaba y hacía ecuaciones diferenciales de cabeza, me contrataron al instante!' WHERE `ID`=64998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 들리는 여제의 속삭임을 견뎌내려면 마음을 굳게 먹어야 한다. 마음이 약해지면 눈치도 못 채는 사이에 여제의 의지에 빠지게 될 것이다.', `MaleText_loc4`='你必须时刻保持坚强的意志，以承受从女皇处不断传来的窃窃私语。薄弱的意志将使你在不知不觉中落入她的手中。', `MaleText_loc5`='你必須保持你的堅強心智來承受女皇那似乎永不停止的低語。心智脆弱的人將會不知不覺地臣服於她。', `MaleText_loc7`='Debes fortalecer tu mente para soportar los susurros continuos de la Emperatriz. Las mentes débiles caen ante ella sin siquiera percatarse.' WHERE `ID`=64999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 영원꽃 골짜기를 보니 말이야, 어딘지 모르게... 낯익은 느낌이 드네.$B$B겉모습은 그렇지 않다는 거 알지만, 그런 느낌을 떨쳐 버릴 수가 없어. 그게 무슨 뜻인 것 같나!?', `MaleText_loc4`='现在，我已经见过这个谷，我得说，这里有些地方感觉有点……熟悉。$B$B我知道，它并不像它，但我不能摆脱这种感觉。你认为那意味着什么！？', `MaleText_loc5`='如今我看過谷中之後，我必須說，這裡有些地方感覺有點...熟悉。$B$B我知道這不太可能，但我卻無法甩掉這種感覺。你覺得這意味著什麼?', `MaleText_loc7`='Ahora que he podido echar un vistazo al valle, puedo decir que hay algo en este lugar que me resulta un poco... familiar.$B$BYa sé que no lo parece, pero no me puedo quitar esa sensación. ¡¿Qué crees que significa?!' WHERE `ID`=65000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단하지 않소? 나는 이들의 최고 팬이라오!', `MaleText_loc4`='他们是不是很伟大？我是他们的头号粉丝！', `MaleText_loc5`='他們很棒對吧?我是他們的頭號愛好者!', `MaleText_loc7`='¿No te parecen geniales? ¡Soy su fan número uno!' WHERE `ID`=65001;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, $r님! 잠시 제 이야기 좀 들어보세요.', `FemaleText_loc4`='欢迎，$r！留下来听一会。', `FemaleText_loc5`='歡迎，$r!留下來聽一陣子吧。', `FemaleText_loc7`='¡Te doy la bienvenida, $r! Quédate un rato y escucha.' WHERE `ID`=65002;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꾀꼬리 휴게실에 오신 것을 환영해요, $c님. 언제 같이 놀아드릴까요?', `FemaleText_loc4`='欢迎光临夜莺旅馆，$c。今天我们可以为你做些什么？', `FemaleText_loc5`='歡迎來到夜鶯迎賓廳，$c。我們能為你演奏什麼?', `FemaleText_loc7`='Te damos la bienvenida a nuestro Salón del Ruiseñor, $c. ¿Qué podemos tocar para ti hoy?' WHERE `ID`=65003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도서관에는 어마어마한 지식이 잠들어 있군요.', `MaleText_loc4`='这个图书馆里的知识令人震惊。', `MaleText_loc5`='這座圖書館中所蘊藏的知識真是驚人。', `MaleText_loc7`='El conocimiento que hay en esta biblioteca es asombroso.' WHERE `ID`=65004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 장비에 보석 박는 걸 맨날 까먹어요."', `MaleText_loc4`='[%s]忏悔：我总是忘记给装备镶宝石。', `MaleText_loc5`='[%s]坦承:我總是忘了插寶石在我的裝備上。', `MaleText_loc7`='[%s] confiesa: Siempre se me olvida ponerle gemas a mi equipo.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 장비에 보석 박는 걸 맨날 까먹어요."', `FemaleText_loc4`='[%s]忏悔：我总是忘记给装备镶宝石。', `FemaleText_loc5`='[%s]坦承:我總是忘了插寶石在我的裝備上。', `FemaleText_loc7`='[%s] confiesa: Siempre se me olvida ponerle gemas a mi equipo.' WHERE `ID`=65005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 잃어버린 시간의 원시비룡을 여섯 달 동안 찾아다녔어요."', `MaleText_loc4`='[%s]忏悔：我花了半年时间刷迷失始祖幼龙。', `MaleText_loc5`='[%s]坦承:我花了六個月的時間追尋時光迷逝元龍。', `MaleText_loc7`='[%s] confiesa: Pasé seis meses persiguiendo al protodraco Tiempo Perdido.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 잃어버린 시간의 원시비룡을 여섯 달 동안 찾아다녔어요."', `FemaleText_loc4`='[%s]忏悔：我花了半年时间刷迷失始祖幼龙。', `FemaleText_loc5`='[%s]坦承:我花了六個月的時間追尋時光迷逝元龍。', `FemaleText_loc7`='[%s] confiesa: Pasé seis meses persiguiendo al protodraco Tiempo Perdido.' WHERE `ID`=65006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 알터랙 계곡에 가서 팀을 전혀 돕지 않은 적이 있어요."', `MaleText_loc4`='[%s]忏悔：我进入奥特兰克山谷，却根本没有帮助我的队伍。', `MaleText_loc5`='[%s]坦承:我去奧特蘭克山谷戰場卻根本沒為我的隊伍出力。', `MaleText_loc7`='[%s] confiesa: Fui al Valle de Alterac y no ayudé a mi equipo en absoluto.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 알터랙 계곡에 가서 팀을 전혀 돕지 않은 적이 있어요."', `FemaleText_loc4`='[%s]忏悔：我进入奥特兰克山谷，却根本没有帮助我的队伍。', `FemaleText_loc5`='[%s]坦承:我去奧特蘭克山谷戰場卻根本沒為我的隊伍出力。', `FemaleText_loc7`='[%s] confiesa: Fui al Valle de Alterac y no ayudé a mi equipo en absoluto.' WHERE `ID`=65007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 승강기 타다 죽은 적이 한 번 있어요. 아니다, 한 번이 아니던가...?"', `MaleText_loc4`='[%s]忏悔：我被电梯杀过。好像还不只一次。', `MaleText_loc5`='[%s]坦承:我曾經在電梯摔死。可能還不只一次。', `MaleText_loc7`='[%s] confiesa: Una vez me mató un ascensor. Puede que más de una vez.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 승강기 타다 죽은 적이 한 번 있어요. 아니다, 한 번이 아니던가...?"', `FemaleText_loc4`='[%s]忏悔：我被电梯杀过。好像还不只一次。', `FemaleText_loc5`='[%s]坦承:我曾經在電梯摔死。可能還不只一次。', `FemaleText_loc7`='[%s] confiesa: Una vez me mató un ascensor. Puede que más de una vez.' WHERE `ID`=65008;
