UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 성기사가 되고 싶었어요."', `MaleText_loc4`='[%s]忏悔：我一直想成为一名圣骑士。', `MaleText_loc5`='[%s]坦承:我一直都想當個聖騎士。', `MaleText_loc7`='[%s] confiesa: Siempre he querido ser un paladín.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 성기사가 되고 싶었어요."', `FemaleText_loc4`='[%s]忏悔：我一直想成为一名圣骑士。', `FemaleText_loc5`='[%s]坦承:我一直都想當個聖騎士。', `FemaleText_loc7`='[%s] confiesa: Siempre he querido ser un paladín.' WHERE `ID`=65010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "트롤은 좀 징그러워요."', `MaleText_loc4`='[%s]忏悔：巨魔的脚趾吓死我了。', `MaleText_loc5`='[%s]坦承:食人妖腳趾有點讓我毛骨悚然。', `MaleText_loc7`='[%s] confiesa: Los dedos de los pies de los trols me dan escalofríos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "트롤은 좀 징그러워요."', `FemaleText_loc4`='[%s]忏悔：巨魔的脚趾吓死我了。', `FemaleText_loc5`='[%s]坦承:食人妖腳趾有點讓我毛骨悚然。', `FemaleText_loc7`='[%s] confiesa: Los dedos de los pies de los trols me dan escalofríos.' WHERE `ID`=65011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 불 속에 서 있었던 적이 있어요."', `MaleText_loc4`='[%s]忏悔：我喜欢玩火自焚。', `MaleText_loc5`='[%s]坦承:我曾『立於火中』。', `MaleText_loc7`='[%s] confiesa: He permanecido en el fuego.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 불 속에 서 있었던 적이 있어요."', `FemaleText_loc4`='[%s]忏悔：我喜欢玩火自焚。', `FemaleText_loc5`='[%s]坦承:我曾『立於火中』。', `FemaleText_loc7`='[%s] confiesa: He permanecido en el fuego.' WHERE `ID`=65012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 준비되지 않았으면서 공대장에게 준비됐다고 한 적이 있어요."', `MaleText_loc4`='[%s]忏悔：我告诉团长，我已经准备好了，但事实上，我没有准备好。', `MaleText_loc5`='[%s]坦承:我曾經告訴我的團隊隊長我準備好了，但我事實上還沒。', `MaleText_loc7`='[%s] confiesa: Le dije al líder de mi banda que estaba listo, pero en realidad no estaba listo.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 준비되지 않았으면서 공대장에게 준비됐다고 한 적이 있어요."', `FemaleText_loc4`='[%s]忏悔：我告诉团长，我已经准备好了，但事实上，我没有准备好。', `FemaleText_loc5`='[%s]坦承:我曾經告訴我的團隊隊長我準備好了，但我事實上還沒。', `FemaleText_loc7`='[%s] confiesa: Le dije al líder de mi banda que estaba lista, pero en realidad no estaba lista.' WHERE `ID`=65013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 달라란에서 떨어진 적이 있어요."', `MaleText_loc4`='[%s]忏悔：我从达拉然上摔下去过。', `MaleText_loc5`='[%s]坦承:我從達拉然上摔下來過。', `MaleText_loc7`='[%s] confiesa: Me caí de Dalaran.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 달라란에서 떨어진 적이 있어요."', `FemaleText_loc4`='[%s]忏悔：我从达拉然上摔下去过。', `FemaleText_loc5`='[%s]坦承:我從達拉然上摔下來過。', `FemaleText_loc7`='[%s] confiesa: Me caí de Dalaran.' WHERE `ID`=65014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라 핀클스위치라는 전투 애완동물 전문가가 중앙 난간뜰에서 애완동물을 훈련하고 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='有个名叫萨拉·芬克斯维奇的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='有個叫做薩拉·芬克開關的戰寵訓練師在主要平臺上訓練她的寵物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Hay una instructora de mascotas de duelo llamada Sara Fusta Severa que entrena a sus mascotas en el patio principal.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='사라 핀클스위치라는 전투 애완동물 전문가가 중앙 난간뜰에서 애완동물을 훈련하고 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='有个名叫萨拉·芬克斯维奇的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='有個叫做薩拉·芬克開關的戰寵訓練師在主要平臺上訓練她的寵物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Hay una instructora de mascotas de duelo llamada Sara Fusta Severa que entrena a sus mascotas en el patio principal.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=65015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 탈것을 처음 살 때 친구한테 돈을 뜯었어요."', `MaleText_loc4`='[%s]忏悔：我向一位朋友要了很多金子去买我的第一头坐骑。', `MaleText_loc5`='[%s]坦承:我向朋友借了一些錢來買我的第一隻坐騎。', `MaleText_loc7`='[%s] confiesa: Le pedí oro a un amigo para comprar mi primera montura.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 탈것을 처음 살 때 친구한테 돈을 뜯었어요."', `FemaleText_loc4`='[%s]忏悔：我向一位朋友要了很多金子去买我的第一头坐骑。', `FemaleText_loc5`='[%s]坦承:我向朋友借了一些錢來買我的第一隻坐騎。', `FemaleText_loc7`='[%s] confiesa: Le pedí oro a un amigo para comprar mi primera montura.' WHERE `ID`=65016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여름 난간뜰 1층에 낚시용품 상인이 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，楼下就有渔具供应商，就在夏之台的一楼。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='是的，下面有個釣魚貨品商人，就在夏日露臺的第一層。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Sí, hay un vendedor de suministros de pesca en el piso de abajo, en el primer nivel de El Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 여름 난간뜰 1층에 낚시용품 상인이 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，楼下就有渔具供应商，就在夏之台的一楼。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='是的，下面有個釣魚貨品商人，就在夏日露臺的第一層。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Sí, hay un vendedor de suministros de pesca en el piso de abajo, en el primer nivel de El Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=65017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "공략 확고라고 말했는데 사실은 쥐뿔도 몰랐어요. 엄청 창피했지요."', `MaleText_loc4`='[%s]忏悔：我告诉队友说，这个地下城我以前来过，但其实我完全不知道自己该干什么。真尴尬。', `MaleText_loc5`='[%s]坦承:我曾經說過我以前打過某個地城，但事實上我根本一竅不通，非常難堪。', `MaleText_loc7`='[%s] confiesa: Dije que ya había estado en la mazmorra, pero no tenía ni idea de lo que hacía. Fue vergonzoso.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "공략 확고라고 말했는데 사실은 쥐뿔도 몰랐어요. 엄청 창피했지요."', `FemaleText_loc4`='[%s]忏悔：我告诉队友说，这个地下城我以前来过，但其实我完全不知道自己该干什么。真尴尬。', `FemaleText_loc5`='[%s]坦承:我曾經說過我以前打過某個地城，但事實上我根本一竅不通，非常難堪。', `FemaleText_loc7`='[%s] confiesa: Dije que ya había estado en la mazmorra, pero no tenía ni idea de lo que hacía. Fue vergonzoso.' WHERE `ID`=65018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 별 이유 없이 노움을 쥐어박은 적이 있어요. 그날 일진이 사나웠거든요."', `MaleText_loc4`='[%s]忏悔：我曾经打了一个侏儒。没有原因。我就是那天心情不好。', `MaleText_loc5`='[%s]坦承:我曾經揍過地精。沒有什麼理由，只是因為那天我不太高興。', `MaleText_loc7`='[%s] confiesa: Una vez le di un puñetazo a un gnomo. Sin motivo. Tenía un mal día.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 별 이유 없이 노움을 쥐어박은 적이 있어요. 그날 일진이 사나웠거든요."', `FemaleText_loc4`='[%s]忏悔：我曾经打了一个侏儒。没有原因。我就是那天心情不好。', `FemaleText_loc5`='[%s]坦承:我曾經揍過地精。沒有什麼理由，只是因為那天我不太高興。', `FemaleText_loc7`='[%s] confiesa: Una vez le di un puñetazo a un gnomo. Sin motivo. Tenía un mal día.' WHERE `ID`=65019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 친구가 입찰한 물품에 상회 입찰한 적이 있어요. 별로 갖고 싶지도 않았으면서요."', `MaleText_loc4`='[%s]忏悔：我出比朋友更高的价格买下我其实并不想要的拍卖品。', `MaleText_loc5`='[%s]坦承:我曾經在拍賣場跟朋友搶過一個我根本不想要的東西。', `MaleText_loc7`='[%s] confiesa: Superé la puja de un amigo en la subasta de un objeto que en realidad no me interesaba.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 친구가 입찰한 물품에 상회 입찰한 적이 있어요. 별로 갖고 싶지도 않았으면서요."', `FemaleText_loc4`='[%s]忏悔：我出比朋友更高的价格买下我其实并不想要的拍卖品。', `FemaleText_loc5`='[%s]坦承:我曾經在拍賣場跟朋友搶過一個我根本不想要的東西。', `FemaleText_loc7`='[%s] confiesa: Superé la puja de un amigo en la subasta de un objeto que en realidad no me interesaba.' WHERE `ID`=65020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "제가 던전에 가는 건, 아제로스를 더 살기 좋은 곳으로 만들기 위해서가 아니에요. 전리품 때문이지요."', `MaleText_loc4`='[%s]忏悔：我去地下城不是为了使艾泽拉斯变得更好，而是为了战利品。', `MaleText_loc5`='[%s]坦承:我到地城去不是為了要讓艾澤拉斯更美好，我只是想要拿裝備。', `MaleText_loc7`='[%s] confiesa: No entro en las mazmorras para hacer de Azeroth un lugar mejor, sino solo por el botín.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "제가 던전에 가는 건, 아제로스를 더 살기 좋은 곳으로 만들기 위해서가 아니에요. 전리품 때문이지요."', `FemaleText_loc4`='[%s]忏悔：我去地下城不是为了使艾泽拉斯变得更好，而是为了战利品。', `FemaleText_loc5`='[%s]坦承:我到地城去不是為了要讓艾澤拉斯更美好，我只是想要拿裝備。', `FemaleText_loc7`='[%s] confiesa: No entro en las mazmorras para hacer de Azeroth un lugar mejor, sino solo por el botín.' WHERE `ID`=65021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 안퀴라즈가 열릴 때 없었어요. 어디서 글을 읽었을 뿐이에요."', `MaleText_loc4`='[%s]忏悔：其实，我没有参加安其拉的开门仪式。我只是读过这个故事。', `MaleText_loc5`='[%s]坦承:我沒有參與安其拉的開啟，只有聽說過這件事。', `MaleText_loc7`='[%s] confiesa: En realidad no estuve presente cuando abrieron Ahn''Qiraj. Solo leí sobre el tema.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 사실 안퀴라즈가 열릴 때 없었어요. 어디서 글을 읽었을 뿐이에요."', `FemaleText_loc4`='[%s]忏悔：其实，我没有参加安其拉的开门仪式。我只是读过这个故事。', `FemaleText_loc5`='[%s]坦承:我沒有參與安其拉的開啟，只有聽說過這件事。', `FemaleText_loc7`='[%s] confiesa: En realidad no estuve presente cuando abrieron Ahn''Qiraj. Solo leí sobre el tema.' WHERE `ID`=65022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 신도레이가 누군지 전혀 몰라요."', `MaleText_loc4`='[%s]忏悔：我完全不知道辛多雷是个谁。', `MaleText_loc5`='[%s]坦承:我壓根不知道哪些人是辛多雷。', `MaleText_loc7`='[%s] confiesa: En realidad no tengo ni idea de quiénes son los Sin''dorei.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 신도레이가 누군지 전혀 몰라요."', `FemaleText_loc4`='[%s]忏悔：我完全不知道辛多雷是个谁。', `FemaleText_loc5`='[%s]坦承:我壓根不知道哪些人是辛多雷。', `FemaleText_loc7`='[%s] confiesa: En realidad no tengo ni idea de quiénes son los Sin''dorei.' WHERE `ID`=65023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 모든 탈것을 평등하게 대하지 않아요."', `MaleText_loc4`='[%s]忏悔：我对我所有的坐骑并非一视同仁。', `MaleText_loc5`='[%s]坦承:我沒有公平對待我的所有坐騎。', `MaleText_loc7`='[%s] confiesa: No trato igual a todas mis monturas.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 모든 탈것을 평등하게 대하지 않아요."', `FemaleText_loc4`='[%s]忏悔：我对我的所有坐骑并非一视同仁。', `FemaleText_loc5`='[%s]坦承:我沒有公平對待我的所有坐騎。', `FemaleText_loc7`='[%s] confiesa: No trato igual a todas mis monturas.' WHERE `ID`=65024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 고고학에 손을 대긴 했지만, 역사에는 별로 관심이 없어요."', `MaleText_loc4`='[%s]忏悔：我研究考古学，但对历史并不感兴趣。', `MaleText_loc5`='[%s]坦承:我有試過考古學，但我對歷史一點興趣也沒有。', `MaleText_loc7`='[%s] confiesa: Hago mis pinitos en arqueología, pero no me interesa mucho la historia.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 고고학에 손을 대긴 했지만, 역사에는 별로 관심이 없어요."', `FemaleText_loc4`='[%s]忏悔：我研究考古学，但对历史并不感兴趣。', `FemaleText_loc5`='[%s]坦承:我有試過考古學，但我對歷史一點興趣也沒有。', `FemaleText_loc7`='[%s] confiesa: Hago mis pinitos en arqueología, pero no me interesa mucho la historia.' WHERE `ID`=65025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "드레나이 웃음소리는 듣기만 해도 짜증이 나요."', `MaleText_loc4`='[%s]忏悔：德莱尼人的笑声真的让我很烦。', `MaleText_loc5`='[%s]坦承:德萊尼的笑聲真的讓我受不了。', `MaleText_loc7`='[%s] confiesa: La risa de los draenei me resulta irritante.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "드레나이 웃음소리는 듣기만 해도 짜증이 나요."', `FemaleText_loc4`='[%s]忏悔：德莱尼人的笑声真的让我很烦。', `FemaleText_loc5`='[%s]坦承:德萊尼的笑聲真的讓我受不了。', `FemaleText_loc7`='[%s] confiesa: La risa de los draenei me resulta irritante.' WHERE `ID`=65026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "미용실에 안 간 지 몇 달 됐어요. 가위를 든 고블린이라니. 상상만 해도 소름 끼쳐요."', `MaleText_loc4`='[%s]忏悔：我几个月没进理发店了。拿着剪刀的地精。叫人不寒而栗。', `MaleText_loc5`='[%s]坦承:我已經幾個月沒去過美容沙龍了。哥布林拿著剪刀。真恐怖。', `MaleText_loc7`='[%s] confiesa: Llevo meses sin ir a una peluquería. Goblins con tijeras. Me dan escalofríos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "미용실에 안 간 지 몇 달 됐어요. 가위를 든 고블린이라니. 상상만 해도 소름 끼쳐요."', `FemaleText_loc4`='[%s]忏悔：我几个月没进理发店了。拿着剪刀的地精。叫人不寒而栗。', `FemaleText_loc5`='[%s]坦承:我已經幾個月沒去過美容沙龍了。哥布林拿著剪刀。真恐怖。', `FemaleText_loc7`='[%s] confiesa: Llevo meses sin ir a una peluquería. Goblins con tijeras. Me dan escalofríos.' WHERE `ID`=65027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 판다렌이 펄볼그의 일종인 줄 알았어요."', `MaleText_loc4`='[%s]忏悔：我曾经以为熊猫人和熊怪是亲戚。', `MaleText_loc5`='[%s]坦承:我以為熊貓人是一種熊怪。', `MaleText_loc7`='[%s] confiesa: Creía que los pandaren eran un tipo de fúrbolg.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 판다렌이 펄볼그의 일종인 줄 알았어요."', `FemaleText_loc4`='[%s]忏悔：我曾经以为熊猫人和熊怪是亲戚。', `FemaleText_loc5`='[%s]坦承:我以為熊貓人是一種熊怪。', `FemaleText_loc7`='[%s] confiesa: Creía que los pandaren eran un tipo de fúrbolg.' WHERE `ID`=65028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "아, 전 양초 가져갔어요."', `MaleText_loc4`='[%s]忏悔：噢，我抢过别人的蜡烛。', `MaleText_loc5`='[%s]坦承:喔，我有拿蠟燭。', `MaleText_loc7`='[%s] confiesa: Oh, yo cogí la vela.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "아, 전 양초 가져갔어요."', `FemaleText_loc4`='[%s]忏悔：噢，我抢过别人的蜡烛。', `FemaleText_loc5`='[%s]坦承:喔，我有拿蠟燭。', `FemaleText_loc7`='[%s] confiesa: Oh, yo cogí la vela.' WHERE `ID`=65029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "이건 작은 차질일 뿐이에요."', `MaleText_loc4`='[%s]忏悔：让老鼠打破了大门不过是个小小的反击。', `MaleText_loc5`='[%s]坦承:這只是一場挫敗。', `MaleText_loc7`='[%s] confiesa: Esto solo es un contratiempo.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "이건 작은 차질일 뿐이에요."', `FemaleText_loc4`='[%s]忏悔：让老鼠打破了大门不过是个小小的反击。', `FemaleText_loc5`='[%s]坦承:這只是一場挫敗。', `FemaleText_loc7`='[%s] confiesa: Esto solo es un contratiempo.' WHERE `ID`=65030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 아무도 안 볼 때 물건에 불을 붙이고 ''불의 세례를 받아라'' 하고 외쳐요."', `MaleText_loc4`='[%s]忏悔：在没有人看见时，我会烧东西，并且大喊大叫“让火焰净化一切”。', `MaleText_loc5`='[%s]坦承:我會在沒有人的時候把東西點火，然後大喊「讓火焰淨化一切」!', `MaleText_loc7`='[%s] confiesa: Quemo cosas y grito PURGAR CON FUEGO cuando no me ve nadie.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 아무도 안 볼 때 물건에 불을 붙이고 ''불의 세례를 받아라'' 하고 외쳐요."', `FemaleText_loc4`='[%s]忏悔：在没有人看见时，我会烧东西，并且大喊大叫“让火焰净化一切”。', `FemaleText_loc5`='[%s]坦承:我會在沒有人的時候把東西點火，然後大喊讓火焰淨化一切!', `FemaleText_loc7`='[%s] confiesa: Quemo cosas y grito PURGAR CON FUEGO cuando no me ve nadie.' WHERE `ID`=65031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "실은 당신이 기억 안 나요... 산속에서."', `MaleText_loc4`='[%s]忏悔：在风暴峭壁时我真的忘了你是谁。', `MaleText_loc5`='[%s]坦承:我不記得我在山裡有看過你。', `MaleText_loc7`='[%s] confiesa: En realidad no te recuerdo en las montañas.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "실은 당신이 기억 안 나요... 산속에서."', `FemaleText_loc4`='[%s]忏悔：在风暴峭壁时我真的忘了你是谁。', `FemaleText_loc5`='[%s]坦承:我不記得我在山裡有看過你。', `FemaleText_loc7`='[%s] confiesa: En realidad no te recuerdo en las montañas.' WHERE `ID`=65032;
