UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "너무 비슷비슷한 이름이 많아서 헷갈려요."', `MaleText_loc4`='[%s]忏悔：我每次看到那些缩写就头疼，什么KLZ DPS CJQ 1Q9来强力的，完全看不懂啊。', `MaleText_loc5`='[%s]坦承:那些有一堆奇怪符號的名字我根本看不懂。', `MaleText_loc7`='[%s] confiesa: Todos estos nombres con tantos apóstrofes me resultan muy confusos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "너무 비슷비슷한 이름이 많아서 헷갈려요."', `FemaleText_loc4`='[%s]忏悔：我每次看到那些缩写就头疼，什么KLZ DPS CJQ 1Q9来强力的，完全看不懂啊。', `FemaleText_loc5`='[%s]坦承:那些有一堆奇怪符號的名字我根本看不懂。', `FemaleText_loc7`='[%s] confiesa: Todos estos nombres con tantos apóstrofes me resultan muy confusos.' WHERE `ID`=65034;
