UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "사실 전 준비가 안 돼 있었어요. 하지만 아무도 모르잖아요?"', `MaleText_loc4`='[%s]忏悔：我真的没有准备好。谁知道我是不是自寻死路呢？', `MaleText_loc5`='[%s]坦承:我根本沒有準備。又有誰知道?', `MaleText_loc7`='[%s] confiesa: En realidad no estaba preparado. ¿Quién se lo iba a imaginar?', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "사실 전 준비가 안 돼 있었어요. 하지만 아무도 모르잖아요?"', `FemaleText_loc4`='[%s]忏悔：我真的没有准备好。谁知道我是不是自寻死路呢？', `FemaleText_loc5`='[%s]坦承:我根本沒有準備。又有誰知道?', `FemaleText_loc7`='[%s] confiesa: En realidad no estaba preparada. ¿Quién se lo iba a imaginar?' WHERE `ID`=65036;
