UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 빛에게 힘을 달라고 말하지만, 그 힘이 정말 빛에서 나오는지는 잘 모르겠어요."', `MaleText_loc4`='[%s]忏悔：我要求圣光给我力量，但我不确定它是否真的会给。', `MaleText_loc5`='[%s]坦承:我有請求聖光賜我力量過，但我不清楚到底有何差別。', `MaleText_loc7`='[%s] confiesa: Pido a la Luz que me dé fuerzas, pero no estoy seguro de si lo hace.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 빛에게 힘을 달라고 말하지만, 그 힘이 정말 빛에서 나오는지는 잘 모르겠어요."', `FemaleText_loc4`='[%s]忏悔：我要求圣光给我力量，但我不确定它是否真的会给。', `FemaleText_loc5`='[%s]坦承:我有請求聖光賜我力量過，但我不清楚到底有何差別。', `FemaleText_loc7`='[%s] confiesa: Pido a la Luz que me dé fuerzas, pero no estoy segura de si lo hace.' WHERE `ID`=65038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "얼마 안 되는 거리를 탈것을 타고 갈 때가 있어요. 엎어지면 코 닿을 데도요."', `MaleText_loc4`='[%s]忏悔：有时候路途很短，我也会使用我的坐骑。我是说真的很短的路程。', `MaleText_loc5`='[%s]坦承:我有時會用坐騎走一小段路。非常非常短的距離也一樣。', `MaleText_loc7`='[%s] confiesa: A veces uso mi montura para recorrer distancias muy cortas. MUY cortas.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "얼마 안 되는 거리를 탈것을 타고 갈 때가 있어요. 엎어지면 코 닿을 데도요."', `FemaleText_loc4`='[%s]忏悔：有时候路途很短，我也会使用我的坐骑。我是说真的很短的路程。', `FemaleText_loc5`='[%s]坦承:我有時會用坐騎走一小段路。非常非常短的距離也一樣。', `FemaleText_loc7`='[%s] confiesa: A veces uso mi montura para recorrer distancias muy cortas. MUY cortas.' WHERE `ID`=65039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 밀하우스가 착한 놈인지 나쁜 놈인지 모르겠어요."', `MaleText_loc4`='[%s]忏悔：我不知道米尔豪斯是不是一个好人。', `MaleText_loc5`='[%s]坦承:我不知道米歐浩斯是好人還是壞人。', `MaleText_loc7`='[%s] confiesa: No sé si Molino es buena persona o no.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 밀하우스가 착한 놈인지 나쁜 놈인지 모르겠어요."', `FemaleText_loc4`='[%s]忏悔：我不知道米尔豪斯是不是一个好人。', `FemaleText_loc5`='[%s]坦承:我不知道米歐浩斯是好人還是壞人。', `FemaleText_loc7`='[%s] confiesa: No sé si Molino es buena persona o no.' WHERE `ID`=65040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "가로쉬가 제정신이 아닌 건 알지만, 뭔가가 있긴 해요."', `MaleText_loc4`='[%s]忏悔：我知道加尔鲁什是个混蛋，但他也有不为人知的一面……', `MaleText_loc5`='[%s]坦承:我知道他是個渾蛋，但卡爾洛斯就是有某種特質...', `MaleText_loc7`='[%s] confiesa: Sé que es un idiota, pero Garrosh tiene algo...', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "가로쉬가 제정신이 아닌 건 알지만, 뭔가가 있긴 해요."', `FemaleText_loc4`='[%s]忏悔：我知道加尔鲁什是个混蛋，但他也有不为人知的一面……', `FemaleText_loc5`='[%s]坦承:我知道他是個渾蛋，但卡爾洛斯就是有某種特質...', `FemaleText_loc7`='[%s] confiesa: Sé que es un idiota, pero Garrosh tiene algo...' WHERE `ID`=65041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "마법사가 주문을 외우는 걸 봤는데, 피해가 어찌나 큰지 입이 떡 벌어지더라고요."', `MaleText_loc4`='[%s]忏悔：我被法师biu过一次，然后那伤害……我当时就给跪了。', `MaleText_loc5`='[%s]坦承:我曾經看過法師的法術傷害誇張到讓我的下巴都掉下來了。', `MaleText_loc7`='[%s] confiesa: Una vez vi a un mago lanzar un hechizo y me quedé boquiabierto al ver el daño.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "마법사가 주문을 외우는 걸 봤는데, 피해가 어찌나 큰지 입이 떡 벌어지더라고요."', `FemaleText_loc4`='[%s]忏悔：我被法师biu过一次，然后那伤害……我当时就给跪了。', `FemaleText_loc5`='[%s]坦承:我曾經看過法師的法術傷害誇張到讓我的下巴都掉下來了。', `FemaleText_loc7`='[%s] confiesa: Una vez vi a un mago lanzar un hechizo y me quedé boquiabierta al ver el daño.' WHERE `ID`=65042;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 이곳의 환영을 보고 여기까지 찾아왔어요. 하지만 그 환영 속의 모습조차도 이 골짜기의 아름다움에는 비할 바가 못 되네요.', `FemaleText_loc4`='我们被这里的景色吸引。但是，即使是这样的景色，也无法与四风谷的美景相比。', `FemaleText_loc5`='我們是被幻象吸引到這裡來的。但和這山谷的美麗實景一比，就連幻象都顯得蒼白無力。', `FemaleText_loc7`='Nos sentimos atraídos hasta este lugar por las visiones. Pero incluso estas palidecen en comparación con la belleza del Valle.' WHERE `ID`=65043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "전 사실 요리사 모자를 쓰고 리치 왕을 쓰러뜨렸어요."', `MaleText_loc4`='[%s]忏悔：过去的很长一段时间里，我都以为小样本事件的复数写法就是数据流。', `MaleText_loc5`='[%s]坦承:有很長一段時間，不管有沒有經過證實，我以為很多人講同樣的話就代表那是對的。', `MaleText_loc7`='[%s] confiesa: Durante mucho tiempo, creí que el plural de anécdota era datos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "전 사실 요리사 모자를 쓰고 리치 왕을 쓰러뜨렸어요."', `FemaleText_loc4`='[%s]忏悔：过去的很长一段时间里，我都以为小样本事件的复数写法就是数据流。', `FemaleText_loc5`='[%s]坦承:有很長一段時間，不管有沒有經過證實，我以為很多人講同樣的話就代表那是對的。', `FemaleText_loc7`='[%s] confiesa: Durante mucho tiempo, creí que el plural de anécdota era datos.' WHERE `ID`=65044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "가끔은 별로 멀리 있지도 않으면서 흑마법사한테 소환을 부탁할 때가 있어요."', `MaleText_loc4`='[%s]忏悔：有时候，其实我离得不远，但我还是叫术士拉我。', `MaleText_loc5`='[%s]坦承:有時候我根本就快到了，我還是會叫術士召喚我。', `MaleText_loc7`='[%s] confiesa: A veces le pido a un brujo que me invoque cuando en realidad no estoy tan lejos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "가끔은 별로 멀리 있지도 않으면서 흑마법사한테 소환을 부탁할 때가 있어요."', `FemaleText_loc4`='[%s]忏悔：有时候，其实我离得不远，但我还是叫术士拉我。', `FemaleText_loc5`='[%s]坦承:有時候我根本就快到了，我還是會叫術士召喚我。', `FemaleText_loc7`='[%s] confiesa: A veces le pido a un brujo que me invoque cuando en realidad no estoy tan lejos.' WHERE `ID`=65045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "퀘스트를 할 때 혼자 있고 싶어서, 친구들이 말을 걸어도 못 들은 척할 때가 있어요."', `MaleText_loc4`='[%s]忏悔：有时候我想独自一个人做任务，便假装听不见我的朋友说话……', `MaleText_loc5`='[%s]坦承:有時候我只想一個人解任務，所以我會假裝沒看到朋友說的話...', `MaleText_loc7`='[%s] confiesa: A veces, cuando hago misiones, quiero estar solo, así que finjo que no oigo a mis amigos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "퀘스트를 할 때 혼자 있고 싶어서, 친구들이 말을 걸어도 못 들은 척할 때가 있어요."', `FemaleText_loc4`='[%s]忏悔：有时候我想独自一个人做任务，便假装听不见我的朋友说话……', `FemaleText_loc5`='[%s]坦承:有時候我只想一個人解任務，所以我會假裝沒看到朋友說的話...', `FemaleText_loc7`='[%s] confiesa: A veces, cuando hago misiones, quiero estar sola, así que finjo que no oigo a mis amigos.' WHERE `ID`=65046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 먼 길을 왔습니다. 그리고 그 와중에 많은 친구를 잃었지요.$b$b하지만 이곳은 정말... 아름답군요!', `MaleText_loc4`='走了很长一段路才到这里。沿途之中我们错过了很多。$b$b但是……看看这个地方。太不可思议了！', `MaleText_loc5`='來到這裡是一段遙遠的旅途。一路上我們失去了許多。$b$b但是...看看這地方。真是驚人!', `MaleText_loc7`='El viaje hasta aquí ha sido muy largo. Y hemos perdido a muchos por el camino.$b$bA pesar de todo... mirad este lugar. ¡Es impresionante!', `FemaleText_loc1`='여기까지 먼 길을 왔어요. 그리고 그 와중에 많은 친구를 잃었지요.$b$b하지만 이곳은 정말... 아름답군요!', `FemaleText_loc4`='走了很长一段路才到这里。沿途之中我们错过了很多。$b$b但是……看看这个地方。太不可思议了！', `FemaleText_loc5`='來到這裡真是一段遙遠的旅途。一路上我們失去了許多。$b$b但是...看看這地方。真是驚人!', `FemaleText_loc7`='El viaje hasta aquí ha sido muy largo. Y hemos perdido a muchos por el camino.$b$bA pesar de todo... mirad este sitio. ¡Es impresionante!' WHERE `ID`=65047;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='먹거리가 필요하신가요, 여행자님?', `FemaleText_loc4`='旅行者，你想吃点什么吗？', `FemaleText_loc5`='想吃點什麼嗎，旅人?', `FemaleText_loc7`='¿Un bocado para echarse a la boca, viajante?' WHERE `ID`=65048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음식과 음료 팔아요!', `FemaleText_loc4`='出售食物和饮料！', `FemaleText_loc5`='專賣食物和飲料!', `FemaleText_loc7`='¡Comida y bebida a la venta!' WHERE `ID`=65049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주전부리가 당기시나요, $r님?', `FemaleText_loc4`='来份点心怎么样，$r？', `FemaleText_loc5`='想來些點心嗎，$r?', `FemaleText_loc7`='¿Te apetece un aperitivo, $r?' WHERE `ID`=65050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 열어 주셔서 감사합니다, $p 님. 이렇게 당신과 함께 있는 것만으로도 영광입니다.', `MaleText_loc4`='感谢你为我们打开大门，$p。你的到来是我们的荣幸。', `MaleText_loc5`='謝謝你為我們打開大門，$p。你的在場令我們感到光榮。', `MaleText_loc7`='Gracias por abrirnos las puertas, $p. Nos honras con tu presencia.', `FemaleText_loc1`='문을 열어 주셔서 감사해요, $p 님. 이렇게 당신과 함께 있는 것만으로도 영광이에요.', `FemaleText_loc4`='感谢你为我们打开大门，$p。你的到来是我们的荣幸。', `FemaleText_loc5`='謝謝你為我們打開大門，$p。你的在場令我們感到光榮。', `FemaleText_loc7`='Gracias por abrirnos las puertas, $p. Nos honras con tu presencia.' WHERE `ID`=65051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 여기까지 따라왔습니다. 이 고요한 곳에서마저 바람결에서 전쟁의 냄새가 나는군요.', `MaleText_loc4`='联盟跟随我们到这里。即使在这个宁静的地方，我也能闻到硝烟的味道。', `MaleText_loc5`='聯盟跟蹤我們來到了此處。就算在這如此寧靜的地方，我也從風中嗅到了戰爭的氣息。', `MaleText_loc7`='La Alianza nos ha seguido hasta aquí. Incluso en este sereno lugar huelo la guerra en el viento.', `FemaleText_loc1`='얼라이언스가 여기까지 따라왔어요. 이 고요한 곳에서마저 바람결에서 전쟁의 냄새가 나는군요.', `FemaleText_loc4`='联盟跟随我们到这里。即使在这个宁静的地方，我也能闻到硝烟的味道。', `FemaleText_loc5`='聯盟跟蹤我們來到了此處。就算在這如此寧靜的地方，我也從風中嗅到了戰爭的氣息。', `FemaleText_loc7`='La Alianza nos ha seguido hasta aquí. Incluso en este sereno lugar huelo la guerra en el viento.' WHERE `ID`=65052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구, 사마귀, 얼라이언스... 모두 이 유서 깊은 곳의 안전을 위협하는 존재입니다. 무슨 일이 있어도 지켜 내야 합니다.', `MaleText_loc4`='魔古族、螳螂妖和联盟都威胁到这个古老的地方的安全。我们必须不惜一切代价保护它。', `MaleText_loc5`='魔古、螳螂人、還有聯盟全都對這古老地方的安全造成威脅。我們必須不計代價保護它。', `MaleText_loc7`='Los mogu, los mántides y la Alianza amenazan las seguridad de este lugar milenario. Debemos protegerlo a toda costa.', `FemaleText_loc1`='모구, 사마귀, 얼라이언스... 모두 이 유서 깊은 곳의 안전을 위협하는 존재예요. 무슨 일이 있어도 지켜 내야 해요.', `FemaleText_loc4`='魔古族、螳螂妖和联盟都威胁到这个古老的地方的安全。我们必须不惜一切代价保护它。', `FemaleText_loc5`='魔古、螳螂人、還有聯盟全都對這古老地方的安危造成威脅。我們必須不計代價保護它。', `FemaleText_loc7`='Los mogu, los mántides y la Alianza amenazan la seguridad de este lugar milenario. Debemos protegerlo a toda costa.' WHERE `ID`=65053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 야운골에게 고향을 잃었어요. 하지만 이곳에서... 우린 새 출발을 할 거예요.', `FemaleText_loc4`='野牛人侵占了我们的家园！但这个地方……这个地方为我们提供一个新的开始。', `FemaleText_loc5`='揚古讓我們失去了家園。但這地方...這地方讓我們有了新的開始。', `FemaleText_loc7`='Perdimos nuestro hogar ante los yaungol. Pero este lugar... este lugar nos ofrece un nuevo comienzo.' WHERE `ID`=65054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야운골이 마을에 쳐들어왔을 때는 다 끝이라고 생각했네. 판에 박힌 말이긴 하지만, 수도사들이 곧잘 하는 "하늘이 무너져도 솟아날 구멍이 있다"라는 말이 사실이었다네.$b$b제대로 말한 거 맞나? 수도사의 가르침은 별로 귀담아 듣질 않아서 말이야.', `MaleText_loc4`='当野牛人袭击我们家园的时候，我以为全都完了。这是老生常谈，但老武僧说得对：“东方不亮，西方亮。”$b$b或者和这差不多的说法。他们的教导是不是太泛泛了。', `MaleText_loc5`='當揚古攻擊我們的家園時，我以為所有希望都沒了。雖然是陳腔濫調，但老一輩的武僧說:「當一扇門關上時，另一扇門將會打開。」還真是沒錯。$b$b我記得是那樣講的啦。我以前對他們的教誨不太感興趣。', `MaleText_loc7`='Creí que ya no había nada que hacer cuando el yaungol atacó nuestro hogar. Suena a cliché, pero los viejos monjes tienen razón cuando dicen: "Cuando una puerta se cierra, otra se abre".$b$bO algo así. No presto mucha atención a sus enseñanzas.' WHERE `ID`=65055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 운룡 보러 가면 안 돼요?', `MaleText_loc4`='我们可以去看看青龙吗？', `MaleText_loc5`='我們能去看看蛟龍嗎?', `MaleText_loc7`='¿Podemos ir a ver los dragones?' WHERE `ID`=65056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 안 된단다, 얘야. 할 일이 있거든.', `MaleText_loc4`='今天不行，小家伙。我们有任务在身。', `MaleText_loc5`='今天不行，小朋友。我們還有差事要辦。', `MaleText_loc7`='Hoy no, criatura. Tenemos tareas que cumplir.' WHERE `ID`=65057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 타우렌 봐도 돼요? 야운골처럼 생겼어요.', `MaleText_loc4`='我们可以去看看牛头人吗？他们看起来像野牛人。', `MaleText_loc5`='我們能看看牛頭人嗎?他們長得好像揚古。', `MaleText_loc7`='¿Podemos ir a ver a los tauren? Se parecen a los yaungol.' WHERE `ID`=65058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 언데드 누나 보러 가면 안 돼요? 우습게 생겼어요.', `MaleText_loc4`='我们可以去看看亡灵女士吗？她看起来很有趣的。', `MaleText_loc5`='我們能去看看那不死族女士嗎?她看起來真奇怪。', `MaleText_loc7`='¿Podemos ir a ver a la mujer no muerta? Tiene una pinta graciosa.' WHERE `ID`=65059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 가서 고블린이랑 놀면 안 돼요? 내가 키가 더 커요!', `MaleText_loc4`='我们可以和地精玩耍吗？我比他们高！', `MaleText_loc5`='我們能去和哥布林玩嗎?我比他們還高!', `MaleText_loc7`='¿Podemos ir a jugar con los goblins? ¡Mido más que ellos!' WHERE `ID`=65060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 집에 가면 안 돼요?', `MaleText_loc4`='我们什么时候可以回家？', `MaleText_loc5`='我們什麼時後才能回家?', `MaleText_loc7`='¿Cuándo podemos irnos a casa?' WHERE `ID`=65061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 장난감이랑 놀고 싶어요. 집에 가면 안 돼요?', `MaleText_loc4`='我想念我的玩具。我们可以回家了吗？', `MaleText_loc5`='我想念我的玩具。我們能回家了嗎?', `MaleText_loc7`='Echo de menos mis juguetes. ¿Podemos volver a casa?' WHERE `ID`=65062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 쿤라이로 돌아가면 안 돼요? 여긴 냄새가 이상해요.', `MaleText_loc4`='我们可以回到昆莱吗？这里的空气闻着很奇怪。', `MaleText_loc5`='我們能回去崑萊嗎?這裡的空氣聞起來好奇怪。', `MaleText_loc7`='¿Podemos volver a Kun-Lai? El aire huele raro aquí.' WHERE `ID`=65063;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안하지만 여기 조금 더 있어야 된단다. 호드가 우릴 지켜 주고 있잖니.', `FemaleText_loc4`='很抱歉，我们需要在这里呆一会儿。部落保护着我们的安全。', `FemaleText_loc5`='我很抱歉，但我們得在這裡待上一會兒。部落在保護我們的安全。', `FemaleText_loc7`='Lo siento pero tengo que quedarme aquí un rato. La Horda nos mantiene a salvo.' WHERE `ID`=65064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요! 제 애완동물과 싸우고 싶으신가요?', `FemaleText_loc4`='你好！你想和我宠物决斗吗？', `FemaleText_loc5`='嗨!你想和我的寵物對戰嗎?', `FemaleText_loc7`='¡Hola! ¿Te gustaría enfrentarte a mis mascotas?' WHERE `ID`=65065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $r님. 저는 몸집이 작지만, 애완동물 대전에서 몸집은 중요하지 않죠!', `FemaleText_loc4`='你好，$r。我也许比较小，但是在宠物的战斗中身材大小并不重要！', `FemaleText_loc5`='歡迎，$r。我或許很小，但體型在寵物對戰裡並不重要!', `FemaleText_loc7`='Saludos, $r. ¡Puede que sea pequeña, pero el tamaño no importa en un duelo de mascotas!' WHERE `ID`=65066;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $c님! 제 애완동물들 너무 귀엽지 않나요?', `FemaleText_loc4`='你好，$c！你不觉得我的宠物很可爱吗？', `FemaleText_loc5`='嗨，$c!你覺得我的寵物可愛嗎?', `FemaleText_loc7`='¡Hola, $c! ¿No te parece que mis mascotas son adorables?' WHERE `ID`=65067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑구나, 얘야. 밭에 나가 본 적이 있니?', `FemaleText_loc4`='你好，亲爱的。你一直都在战场上吗？', `FemaleText_loc5`='哈囉，親愛的。去過外面的草原了嗎?', `FemaleText_loc7`='Hola, encanto. ¿Has estado en los campos?' WHERE `ID`=65068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 뭐 가져다줄 거라도 있니?', `FemaleText_loc4`='有什么我可以帮你吗？', `FemaleText_loc5`='我能幫你找些什麼嗎?', `FemaleText_loc7`='¿Hay algo que pueda darte?' WHERE `ID`=65069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='괭이는 정직한 이의 무기란다.', `FemaleText_loc4`='锄头是忠实的$G男人的:女人的;武器。', `FemaleText_loc5`='鋤頭是真$G男人:女人;的武器。', `FemaleText_loc7`='Una azada es el arma de $gun hombre honesto:una mujer honesta;.' WHERE `ID`=65070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑구나, $n. 난 심장지 주변에서 일어나는 일이라면 모두 알고 있단다. 이 나이 쯤 되면 입방정이 심한 친구 한둘은 있기 마련이거든.', `FemaleText_loc4`='你好啊，$n。汇风岭附近发生的一切我都已经了然于胸了，宝贝儿。活到我这把年纪，总会交到几个大嘴巴的朋友。', `FemaleText_loc5`='哈囉，$n。我知道中央平原附近發生的所有事情，親愛的。長到像我這樣的年紀一定會交到幾個口風不緊的朋友。', `FemaleText_loc7`='Hola, $n. Sé todo lo que se cuece en los Cultivos Florecientes, cariño. No se llega a mi edad sin hacerse unos cuantos amigos parlanchines.' WHERE `ID`=65071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작이군. 끝까지 살아남아 주길 바란다.', `MaleText_loc4`='我们走吧。千万别把自己的命给搭上。', `MaleText_loc5`='上吧。在結束之前試著保住你自己的性命。', `MaleText_loc7`='Allá vamos. Intenten seguir vivos hasta el final.' WHERE `ID`=65072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t %s|1이;가; 너무 많이 먹어서 |cFFFF0000|Hspell:126126|h[구토]|h|r를 하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t %s吃得太多，开始|cFFFF0000|Hspell:126126|h[呕吐]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t%s吃太多了而且開始 |cFFFF0000|Hspell:126126|h[嘔吐]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_corpseexplode.blp:20|t %s ha comido demasiado y empieza a|cFFFF0000|Hspell:126126|h[Regurgitar]|h|r.' WHERE `ID`=65073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 널 잡으러 간다, 칠하트! 복수의 시간이다!', `MaleText_loc4`='寒心，我们为你而来！血债血偿的时候到了！', `MaleText_loc5`='我們將會逮到你，冷心!報仇的時候到了!', `MaleText_loc7`='¡Vamos por ti, Corazón Álgido! ¡Hora de la venganza!' WHERE `ID`=65074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s|1이;가; 먹이를 |cFFFF0000|Hspell:126187|h[무쇠턱]|h|r에 가둡니다! 지금 처치하십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s用他的|cFFFF0000|Hspell:126187|h[钳颚]|h|r诱捕猎物！杀了他！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t%s將他的獵物困在他的|cFFFF0000|Hspell:126187|h[邪顎攻擊]|h|r裡!殺死他!', `MaleText_loc7`='|TInterfaceIconsinv_misc_monsterfang_02.blp:20|t %s atrapa a su presa en sus|cFFFF0000|Hspell:126187|h[Mandíbulas de saña]|h|r. ¡Dale fin!' WHERE `ID`=65075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남자는 가족의 명예를 지켜야 한다네.', `MaleText_loc4`='人必须尊重他的家族。', `MaleText_loc5`='一個人必須為他的家族帶來榮耀。', `MaleText_loc7`='Un hombre debe honrar a su familia.' WHERE `ID`=65076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조교의 영혼이 파괴되자 말하는 해골이 킬킬거리며 웃습니다.', `MaleText_loc4`='当缚魂魔袋看到指导者的灵魂被摧毁的时候，它开心地笑了起来。', `MaleText_loc5`='說話頭顱在講師的靈魂被摧毀時很快樂地格格發笑。', `MaleText_loc7`='La calavera parlante ríe socarronamente mientras se destruye el alma de la instructora.' WHERE `ID`=65077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하는 해골은 전당 안에 들어서기를 망설이는 듯하더니, 결국은 당신을 따라 들어옵니다.', `MaleText_loc4`='尽管缚魂魔袋看上去不大愿意进入大厅，但是还是跟了上来。', `MaleText_loc5`='說話頭顱似乎對進入大廳感到猶豫，然而它還是跟著你走了進去。', `MaleText_loc7`='La calavera parlante parece dudar si entrar en la sala, pero aun así, procede.' WHERE `ID`=65078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿수가 딸리는 군대가 먹는 피자 이름이 뭔지 아십니까?$B$B...$B$B튀자!', `MaleText_loc4`='一支人数众多的军队拿什么做点心？$B$B……$B$B撤退！', `MaleText_loc5`='寡不敵眾的軍隊該怎麼辦呢?$B$B...$b$b撤退!', `MaleText_loc7`='¿Cómo les gustan los huevos a los jinyu?$b$b...$b$b¡Pasados por agua!' WHERE `ID`=65079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 치유사는 아닙니다만, 만나보니 참 치유사 같지 않습니까?', `MaleText_loc4`='我不是以治疗者而是牧师的身份来见你！', `MaleText_loc5`='我不是治療師，但我是個牧師，很高興見到你!', `MaleText_loc7`='¿Sabes cuál es el animal favorito de un sacerdote? ¡El sacerdito!' WHERE `ID`=65080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흑마법사한테 흑심 많을 거 같다고요? 그런 거 없어요. 검은 의도는 있어도. 하하하하!', `MaleText_loc4`='不要问我怎么对付术士。我避开他们。哈哈哈哈！', `MaleText_loc5`='別問我要怎麼和術士戰鬥。我會避開他們。哈哈哈哈!', `MaleText_loc7`='No me preguntes cómo luchar contra un brujo. Yo les hago el VACÍO. ¡Ja, ja, ja, ja!' WHERE `ID`=65081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 방어 전담이 싸우기 전에 불안해 했냐고요?$B$B...$B$B맨날 죽기 일쑤니까요!', `MaleText_loc4`='坦克为什么会在战斗之前感到紧张？$B$B……$B$B因为他们总是很忐忑！', `MaleText_loc5`='坦克戰鬥前為什麼那麼緊張?$B$B...$b$b因為他是個顫士!', `MaleText_loc7`='¿Por qué estaba el tanque sucio desde antes de la lucha?$B$B...$B$B¡Porque era un guarrero!' WHERE `ID`=65082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린 폐하가 머무시는 방에 샤가 들러붙어서 빛이 나면...$B$B잘 모르겠군요.$B$B...샤방샤방한 느낌일까요?', `MaleText_loc4`='如果瓦里安国王倒台，会怎么样？$B$B……$B$B我不知道，但应该会发生不小的震动！', `MaleText_loc5`='如果瓦里安國王腐敗墮落了會發生什麼事?$B$B...$b$b我不知道，但我知道這「煞王」肯定會很嚇人!', `MaleText_loc7`='¿Qué pasaría si el rey Varian se corrompiera? $B$B...$B$B¡No sé, pero sería bastante impreSHAnante!' WHERE `ID`=65083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...딸꾹!...$B$B...그... 뭐시냐... 거스가 뭡니까?', `MaleText_loc4`='……呃……！$B$B……什么是……什么是“内脏”……？', `MaleText_loc5`='...噶...!$B$B...什麼是...什麼是「噶屁」...?', `MaleText_loc7`='... ¡hip...!$B$B...¿Qué es un... qué es un "gus"...?' WHERE `ID`=65084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난... 차마 볼 수가 없군.', `MaleText_loc4`='我实在不忍心看。', `MaleText_loc5`='我看不下去。', `MaleText_loc7`='No puedo mirar.' WHERE `ID`=65085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말하는 해골이 입을 꾹 다물고 다음 방으로 가버립니다.', `MaleText_loc4`='缚魂魔袋一言不发地进入第二个大厅。', `MaleText_loc5`='說話頭顱一句話都沒說就繼續走進了下一個房間。', `MaleText_loc7`='La calavera parlante sigue hasta la siguiente cámara sin decir una palabra.' WHERE `ID`=65086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내가 제일 총애하는 암살자 아니신가! 안 그래도 판다리아에서 만났으면 했는데.', `MaleText_loc4`='啊，这不是我最仰慕的刺客大师吗！我一直希望能在潘达利亚找到你呢。', `MaleText_loc5`='啊，我最喜歡的殺手!我一直希望在潘達利亞看到你。', `MaleText_loc7`='¡Pero si es mi asesino maestro favorito! Esperaba poder verte aquí, en Pandaria.' WHERE `ID`=65087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘됐군. 얘기 좀 하지.', `MaleText_loc4`='很好。我们谈谈吧。', `MaleText_loc5`='很好。我們談談吧。', `MaleText_loc7`='Muy bien. Hablemos.' WHERE `ID`=65088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통! 마실 걸 가져와라.', `MaleText_loc4`='童福！拿酒来。', `MaleText_loc5`='童!來點喝的，謝謝。', `MaleText_loc7`='¡Tong! Algo de beber, por favor.' WHERE `ID`=65089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아버지, 데스윙은 온 아제로스를 파괴하려 했었지.', `MaleText_loc4`='我的父亲死亡之翼，曾经想摧毁整个艾泽拉斯。', `MaleText_loc5`='我的父親死亡之翼想要摧毀整個艾澤拉斯。', `MaleText_loc7`='Mi padre, Alamuerte, intentó destruir todo Azeroth.' WHERE `ID`=65090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 그는 제정신이 아니었다. 하지만 하나는 옳았어. 우리 세계는... 너무나도 연약해.', `MaleText_loc4`='没错，他是误入歧途，可他却说对了一件事——我们的世界……确实脆弱不堪。', `MaleText_loc5`='他的行為當然不對，但是有件事情他說得沒錯。我們的世界很...脆弱。', `MaleText_loc7`='Estaba desencaminado, claro está, pero tenía razón en una cosa: nuestro mundo es... frágil.' WHERE `ID`=65091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 어둠뿐인 이 우주에서 단 하나의 빛이다. 폭풍우 속의 촛불이지.', `MaleText_loc4`='我们是晦暗宇宙中的一点光亮。是飘摇在暴风雨中的烛光。', `MaleText_loc5`='我們是暗影中的一點光芒。風暴中的一支蠟燭。', `MaleText_loc7`='Somos una mota de luz en un universo de sombras. Una vela en una tormenta.' WHERE `ID`=65092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은 그런 생각을 한다. 이 세계의 불안정함이, 아버지를 광기로 몰고 간 게 아닐까.', `MaleText_loc4`='有时我会想，正是我们这个世界的动荡，逼疯了我的父亲。', `MaleText_loc5`='有時候我覺得是我們世界的不穩定把我父親逼瘋的。', `MaleText_loc7`='A veces creo que es precisamente la precariedad de nuestro mundo lo que enloqueció a mi padre.' WHERE `ID`=65093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 고맙다, 통.', `MaleText_loc4`='啊，谢谢你，童福。', `MaleText_loc5`='啊，謝謝你，童。', `MaleText_loc7`='Ah, gracias, Tong.' WHERE `ID`=65094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 본론으로 돌아가서, 지금 우리는 심판의 날을 향해 달리고 있다. 아니, 현재 벌어지는 얼라이언스와 호드의 분쟁을 얘기하는 게 아니야.', `MaleText_loc4`='现在，言归正传——我觉得一场末世浩劫正在酝酿。不，我说的不是联盟和部落之间的冲突。', `MaleText_loc5`='現在，說到重點:我相信我們快要面臨清算了。不，我不是在說聯盟與部落之間的矛盾。', `MaleText_loc7`='A lo que iba: creo que se acerca un ajuste de cuentas. Y no, no hablo del conflicto actual entre la Alianza y la Horda.' WHERE `ID`=65095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말을 믿어라. 가로쉬 헬스크림이 테라모어에서 만들어낸 어둠은 아무것도 아니다. 바로 지금도 우리 연약한 고향을 향해 돌진하는, 그 공포에 비하면 말이지.', `MaleText_loc4`='相信我——加尔鲁什·地狱咆哮在塞拉摩的所作所为，跟现在降临于我们脆弱家园的浩劫相比，根本算不了什么。', `MaleText_loc5`='相信我...卡爾洛斯·地獄吼在塞拉摩所做的跟目前正在朝我們脆弱家園逼近的恐怖比起來根本不值一提。', `MaleText_loc7`='Créeme: lo que hizo Garrosh Grito Infernal en Theramore no es nada comparado con los horrores que amenazan a nuestro frágil hogar.' WHERE `ID`=65096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 전쟁이 매우 신경 쓰이긴 하는군. 왜인지 알겠나?', `MaleText_loc4`='可战争深深困扰着我。你理解我的顾虑吗？', `MaleText_loc5`='但是這場戰爭十分令我困擾。你能了解我的煩惱嗎?', `MaleText_loc7`='Pero la guerra me preocupa. ¿Entiendes mi problema?' WHERE `ID`=65097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분열된 아제로스는 절대로 그 끔찍한 어둠에 맞설 수 없다.', `MaleText_loc4`='四分五裂的艾泽拉斯根本无力对抗黑暗。', `MaleText_loc5`='分裂的艾澤拉斯根本無法抵抗黑暗。', `MaleText_loc7`='Un Azeroth dividido jamás podrá resistir a la oscuridad.' WHERE `ID`=65098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁은 끝나야 해. 그것도 빨리! 전쟁이 우리 힘을 갉아먹기 전에.', `MaleText_loc4`='这场战争必须尽快结束。否则，它会耗尽我们的力量！', `MaleText_loc5`='這場戰爭必須立刻結束。不能讓它消耗我們的力量!', `MaleText_loc7`='Esta guerra debe acabar, pronto. ¡Antes de que nos deje sin fuerzas!' WHERE `ID`=65099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 알아 주면 좋겠군. 나는 이 원정에서 너희 얼라이언스를 전폭적으로 지지하고 있다.', `MaleText_loc4`='请你相信，联盟在这场战役中，能得到我毫无保留、坚定不移的支持。', `MaleText_loc5`='我要你知道，你們聯盟在這場戰役中有我堅定的完全支持。', `MaleText_loc7`='Quiero que sepas que tu Alianza tiene mi apoyo total e incondicional en esta campaña.' WHERE `ID`=65100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너희 호드의 충실한 친구라는 건 믿어 줬으면 좋겠군.', `MaleText_loc4`='你大可放心，我的忠诚与部落同在。', `MaleText_loc5`='你可以安心，我的忠誠在你們部落這一方。', `MaleText_loc7`='Te aseguro que mi lealtad pertenece a tu Horda.' WHERE `ID`=65101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 분쟁을 어떻게 빠르고 확실하게 끝낼 것인가? 그 해답은 너와 같은 영웅들에게서 찾아야겠지.', `MaleText_loc4`='我们该如何迅速果断地平息这场冲突？相信答案就在你们这些英雄心里。', `MaleText_loc5`='我們如何快速而決定性地結束這場戰爭?我相信像你這樣的英雄就是答案。', `MaleText_loc7`='¿Cómo terminamos el conflicto de forma rápida y permanente? Creo que los héroes como tú son la respuesta.' WHERE `ID`=65102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼저 네 실력을 확인해야겠다. 그 후에 적절한 장비를 주지.', `MaleText_loc4`='我们必须确定你能够执行这项任务……并把你武装起来。', `MaleText_loc5`='我們必須確保你能完成任務...然後給你相對的裝備。', `MaleText_loc7`='Debemos asegurarnos de que puedes encargarte de esta tarea... y luego equiparte adecuadamente.' WHERE `ID`=65103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남아 주길 바란다! 우리가 만들어갈 전설은 이제 막 시작이니까.', `MaleText_loc4`='尽量保命！我们才刚刚开始这场传奇之旅。', `MaleText_loc5`='試著活下去!我們的傳說旅程才剛剛開始。', `MaleText_loc7`='¡Mantente con vida! Acabamos de empezar un viaje legendario.' WHERE `ID`=65104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 나의 영웅이 승리를 거두고 돌아왔군.', `MaleText_loc4`='啊！我的英雄回来了。', `MaleText_loc5`='啊!我的英雄凱旋而歸。', `MaleText_loc7`='¡Ah! Ha vuelto mi héroe conquistador.' WHERE `ID`=65105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정원은 저 언덕 위에 있다. 정신 바짝 차려라. 저곳에서 돌아온 이는 거의 없다.', `MaleText_loc4`='平台就在山上。多加小心，访客几乎全都有去无回。', `MaleText_loc5`='豐泉台就在這山上。保持警戒，很少訪客能生離此處。', `MaleText_loc7`='La terraza está en lo alto de la colina. No bajes la guardia; no suelen volver muchos visitantes.' WHERE `ID`=65106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴이 창백하군, 친구여! 공포에 굴복하지는 않았겠지?', `MaleText_loc4`='你看起来面色苍白，朋友！相信你还没有被恐惧打败吧？', `MaleText_loc5`='你的臉色蒼白，朋友!你該不會被恐懼打倒吧!', `MaleText_loc7`='¡Qué palidez la tuya! No habrás dejado que el miedo te supere, ¿verdad?' WHERE `ID`=65107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 챙길 물건이 좀 있어서 말이야. 그곳에서 보지!', `MaleText_loc4`='请允许我收拾一下东西，然后我会前去找你。', `MaleText_loc5`='請讓我先收拾我的東西，然後跟你在那裡碰面。', `MaleText_loc7`='Permíteme que recoja mis cosas y me reuniré contigo allí.' WHERE `ID`=65108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각이 필요할 때면 여길 찾아오지. 숨막히는 경치야. 그렇지 않나?', `MaleText_loc4`='我经常来这儿思考。这景色真让人叹为观止，你觉得呢？', `MaleText_loc5`='我常來這裡思考。這裡的風景十分壯觀，你不覺得嗎?', `MaleText_loc7`='Suelo venir aquí a menudo para pensar. Es una vista imponente, ¿no crees?' WHERE `ID`=65109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아는 보석 같은 땅이야. 참으로 아름답지. 지켜 주고 싶어지지 않나?', `MaleText_loc4`='潘达利亚真是一颗明珠。美轮美奂。使你想要去保护她，是吧？', `MaleText_loc5`='潘達利亞的確是個寶地。真美。讓你想要保護她，對吧?', `MaleText_loc7`='Pandaria es una joya. ¿Tal belleza no te inspira protegerla?' WHERE `ID`=65110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 온 아제로스에 대해 난 같은 감정을 느낀다.', `MaleText_loc4`='我对艾泽拉斯也有同感。', `MaleText_loc5`='我也這麼看待艾澤拉斯。', `MaleText_loc7`='Siento lo mismo por Azeroth.' WHERE `ID`=65111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으로 훌륭한 일을 해 주었다, 친구여. 하지만 이건 우리가 함께 할 일의 시작일 뿐이야.', `MaleText_loc4`='你成就斐然，我的朋友。我保证，这只是我们合作的开始。', `MaleText_loc5`='你做了許多好事，朋友。我能保證這只是我們許多合作的開始。', `MaleText_loc7`='Has logrado grandes hazañas. Te aseguro que esto es solo el comienzo de nuestra colaboración.' WHERE `ID`=65112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='똑똑히 보아라. 네가 쓰러뜨린 적들의 힘을.', `MaleText_loc4`='向你的手下败将学习力量。', `MaleText_loc5`='看好了:你消滅的敵人擁有的力量。', `MaleText_loc7`='Contempla el poder de los enemigos que has derrotado...' WHERE `ID`=65113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 네가 능가한 그들의 지혜를.', `MaleText_loc4`='向不如你聪明的人学习智慧。', `MaleText_loc5`='你智取的敵人擁有的智慧。', `MaleText_loc7`='...y la sabiduría de los que has vencido.' WHERE `ID`=65114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 네가 쓰러뜨린 공포의 화신이다. 이제 이것이 네 적의 가슴속에 두려움을 불러일으키길!', `MaleText_loc4`='看！它就是你所战胜的恐惧实体。愿它将恐惧注入你敌人的体内！', `MaleText_loc5`='這裡!你所征服的恐懼象徵。願它能使你的敵人心中感到無比的畏懼!', `MaleText_loc7`='¡Aquí! La encarnación del miedo que has conquistado. ¡Que infunda el terror en el corazón de tus enemigos!' WHERE `ID`=65115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 내 선물을 더해 주지. 착각하지 마라. 검은용군단은 아직 건재하다!', `MaleText_loc4`='终于等到了我要给你的礼物。别搞错了——黑龙军团还活着！', `MaleText_loc5`='最後，來自我的禮物。不要弄錯了:黑龍軍團依然存在!', `MaleText_loc7`='Por último, un regalo de mi parte. No te equivoques: ¡el Vuelo Negro vive!' WHERE `ID`=65116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 내 할일은 끝났다. 샤의 기운이 깃든 무기를 이 물건으로 강화할 수 있지.', `MaleText_loc4`='好了。我的工作完成了。你现在能大大提高任何感染煞能的武器的威力。', `MaleText_loc5`='來吧。我的工作完成了。你現在能大幅強化任何被煞影響的武器。', `MaleText_loc7`='Ya está. Mi trabajo ha terminado. Ahora puedes aumentar el poder de cualquier arma de influencia sha.' WHERE `ID`=65117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 시작이다, 친구여! 가장 힘겨운 도전이 우리를 기다리고 있어.', `MaleText_loc4`='我们才刚刚开始，朋友！最大的挑战还在前头。', `MaleText_loc5`='我們才剛剛開始，朋友!我們最大的挑戰還在前方。', `MaleText_loc7`='¡No hemos hecho más que empezar! Nuestros mayores desafíos nos esperan.' WHERE `ID`=65118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁의 물결이 이 땅을 덮칠 때, 너와 난 준비되어 있어야 한다!', `MaleText_loc4`='但当战火烧到这片海岸时，你和我都会做好准备！', `MaleText_loc5`='但等到戰爭來到這片海岸，你跟我都會準備好!', `MaleText_loc7`='Pero cuando la guerra llegue a estas costas, tú y yo estaremos preparados.' WHERE `ID`=65119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나 반갑군, $n! 라벤홀트 장원에서 내가 준 무기는 잘 썼겠지?$b$b여기 판다리아에서도 너에게 맡기고 싶은 "임무"가 있다. 지난번처럼 너의 모든 능력을 발휘해야 할 테지만, 다시 한 번 말하건대... 그럴 만한 가치가 있을 것이야!$b$b일을 시작하려면 일단 이 땅에 익숙해지는 것이 중요하다. 경험을 더 쌓고 여기로 돌아오너라.', `MaleText_loc4`='很高兴再次见到你，$n！我相信我在拉文霍德给你的武器，已经派上大用场了，对吗？$b$b在潘达利亚，我有另一个“任务”给你。这将再次需要你的所有技能，我再次向你保证……这将是值得的！$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。', `MaleText_loc5`='很高興再次看到你，$n!相信我在拉文霍德莊園給你的武器對你很有幫助?$b$b我在潘達利亞有另一項「任務」要交給你。這會需要你全力以赴，但同樣的...我保證這一切都會有價值的!$b$b在我們開始之前，熟悉這片土地的地形對你來說是首要任務。等你在這裡得到更多經驗時再來找我。', `MaleText_loc7`='¡Qué bueno volver a verte, $n! Supongo que las armas que te entregué en Ravenholdt te han servido de ayuda, ¿no es así?$b$bTengo otro "recado" para ti aquí en Pandaria. Esto volverá a exigir tus mejores habilidades y de nuevo puedo asegurarte que... ¡merecerá la pena!$b$bAntes de comenzar, es importante que te familiarices con el terreno. Ven a verme de nuevo una vez hayas obtenido más experiencia.' WHERE `ID`=65120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다. 이름이 $n|1이었;였;던가? 그래, 그래... 동부 왕국에서 너와 내가 매듭짓지 못한 일이 있는 것 같군. 판다리아에 대해서 어떻게 생각하나?$b$b네게 맡기고 싶은 임무가 있다. 네가 이번엔 그 도전을 감당할 수 있다면 말이지만. 내 장담하건대, 이 임무를 완수하면 고생한 보람이 있을 것이야.$b$b일을 시작하려면 일단 이 땅에 익숙해지는 것이 중요하다. 경험을 더 쌓고 여기로 돌아오너라.', `MaleText_loc4`='你好，又见面了。$n，是它吗？是的，没错……我相信我们在东部王国留下了一些未完成的事业。你怎么找到潘达利亚的？$b$b如果你赢得这次挑战，我便再给你另一个任务。我保证这值得你去做。$b$b在我们开始前，重要的是你自己要熟悉地形。一旦你获得更多的经验，就来拜访我。', `MaleText_loc5`='又見面了。你是$n，對嗎?是的是的...我記得我們在東部王國還有些未完成的工作。尋找潘達利亞的事狀況如何?$b$b如果你願意接受挑戰，我有另一項任務要交給你。最後的報酬保證會讓你感到值得。$b$b在我們開始之前，熟悉這片土地的地形對你來說是首要任務。等你在這裡得到更多經驗時再來找我。', `MaleText_loc7`='Hola de nuevo. Era $n, ¿verdad? Sí, eso era... Creo que tenemos asuntos por concluir en Reinos del Este. ¿Qué te va pareciendo Pandaria?$b$bTengo otra tarea para ti, si es que estás a la altura del desafío. Te garantizo que la recompensa lo estará.$b$bAntes de comenzar, es importante que te familiarices con el terreno. Ven a verme de nuevo cuando hayas obtenido más experiencia.' WHERE `ID`=65121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 아래위로 훑어보는 검은 왕자>$b$b만나서 반갑다, $c|1이여;여;. 넌 선구자인 것 같구나... 수수께끼의 새로운 땅을 조사하는 탐험가 말이다. 이 신비로운 판다리아 대륙에 대해서 어떻게 생각하나?$b$b보아하니 일을 제대로 할 줄 아는 인물 같은데, 이 땅에 대해 대충 파악하고 나면 날 찾아와 줬으면 좋겠군.$b$b나는 계속 여기 있을 것이다.', `MaleText_loc4`='<黑王子上下打量了你一番。>$b$b很高兴见到你，$c，探索新世界的先锋。在神秘大陆潘达利亚上冒险的感觉如何？$b$b你看起来就像是个办事可靠的人。我希望当你完成对这块大陆的游历之后，就立即回来找我。$b$b我会在这里等你。', `MaleText_loc5`='<黑龍王子上下打量你。>$b$b很高興看見你，$c。看來你是一個先鋒，奇妙新世界裡的一介探險者。你是怎麼找到這神秘的潘達利亞大陸的?$b$b你看起來像是有本事完成使命的人。等你熟悉這片土地的地形，我希望你回來找我。$b$b我就在這裡。', `MaleText_loc7`='<El Príncipe Negro te mira de arriba abajo.>$b$bMe alegro de que nos hayamos encontrado, $c. Todo apunta a que formas parte de la vanguardia, $gun:una; $gexplorador:exploradora; en una tierra nueva y extraña. ¿Qué te parece el misterioso continente de Pandaria?$b$bTienes el aspecto de alguien que consigue hacer las cosas que se propone. Quiero que vuelvas a verme una vez te familiarices con el terreno.$b$bNo me moveré de aquí.' WHERE `ID`=65122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 "래시온"이라는 이름을 사용한다. 이 세상에 남은 마지막 검은용이지.$b$b내 아버지는 세계파괴자이자 죽음의 위상인 데스윙이다... 하지만 그렇다고 날 나쁘게 보진 않았으면 좋겠군.$b$b타락으로 동족을 모두 파멸시킨 아버지에게 애정은 없다. 내가 아직 알 속에 있을 때 그 알을 훔쳐, 실험으로 날 만들어낸 붉은용군단에 대해서도 애정이 없기는 마찬가지다.$b$b이렇게 이야기하는 게 좋겠군. 나는... 어디에도 속해 있지 않다. 그리고 언제나 나와 비슷한 영웅들을 찾고 있지.', `MaleText_loc4`='我所选择的名字是“拉希奥”。据我所知，我是最后一条黑龙。$b$b我的父亲是死亡之翼。他是灭世者、死亡的化身、毁灭者……但我希望你不会因此而排斥我。$b$b我不爱我的父亲，他的堕落摧毁了我的族群，我也不喜欢红龙军团，他把我的蛋偷去做试验，期望改造我。$b$b这么说吧，我如今是……孑然一身。而且，我一直在寻找志同道合的英雄。', `MaleText_loc5`='我選擇了「怒西昂」這個名字。據我所知，我是最後的黑龍。$b$b我的父親乃死亡之翼，碎界者，死亡化身，毀滅者...但我希望你不會因此而敵視我。$b$b我對用腐敗摧毀我們種族的父親毫無敬愛之情...對於偷走龍蛋並進行實驗使我誕生的紅龍軍團也並無親愛之心。$b$b可以說，我...毫無歸屬。而我總是在找尋擁有相同想法的英雄。', `MaleText_loc7`='He elegido el nombre de "Wrathion". Por lo que yo sé, soy el último de los dragones negros.$b$bMi padre fue Alamuerte, el Rompemundos, el Aspecto de la Muerte, el Destructor... Pero espero que no me lo tengas en cuenta.$b$bNo tengo ningún cariño hacia mi padre, cuya corrupción destruyó mi raza, o hacia el Vuelo Rojo, quien robó y experimentó con mi huevo para crearme.$b$bDigamos, simplemente, que no estoy en ningún bando. Y siempre estoy a la búsqueda de héroes de corte similar.' WHERE `ID`=65123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 누구십니까?', `MaleText_loc4`='你是谁？', `MaleText_loc5`='你是誰?', `MaleText_loc7`='¿Quién eres?', `FemaleText_loc1`='당신은 누구시죠?', `FemaleText_loc4`='你是谁？', `FemaleText_loc5`='你是誰?', `FemaleText_loc7`='¿Quién eres?' WHERE `ID`=65124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 뭘 하고 계신 겁니까?', `MaleText_loc4`='你在潘达利亚做什么？', `MaleText_loc5`='你在潘達利亞做什麼?', `MaleText_loc7`='¿Qué estás haciendo en Pandaria?', `FemaleText_loc1`='판다리아에서 뭘 하고 계신 건가요?', `FemaleText_loc4`='你在潘达利亚做什么？', `FemaleText_loc5`='你在潘達利亞做什麼?', `FemaleText_loc7`='¿Qué estás haciendo en Pandaria?' WHERE `ID`=65125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 내게도 비밀이 좀 있어도 되지 않겠나, $n?$b$b난 안개가 걷히고 얼마 되지 않아 여기 도착했다. 이 대륙 근해에서 해전이 벌어졌단 소식을 라벤홀트의 동료들에게 전해 듣고 바로 날아왔지.$b$b이 땅은 만 년 동안이나 숨겨져 있었다. 나는 그 오랜 비밀을 이제 막 파헤치기 시작했을 뿐이다!', `MaleText_loc4`='我当然可以有一些秘密。你不同意吗，$n？$b$b迷雾散去后不久，我就到达了……在我的同事拉文霍德了解了一次远离海岸的海战后，我可以飞到这里。$b$b这里已经被隐藏了一万年。我才刚刚开始探索之旅！', `MaleText_loc5`='顯然我連「一點」秘密都不能有。不是這樣嗎，$n?$b$b迷霧散去後不久，我就來到這裡。我在拉文霍德的同伴發現這海岸邊的一場海戰之後，我就跟著他們飛到這裡。$b$b這片土地隱藏了有一萬年之久。我也不過剛開始探索它的深度!', `MaleText_loc7`='Sin duda alguna, se me permite tener ALGUNOS secretos. ¿No estás de acuerdo, $n?$b$bLlegué poco después de que las brumas se dispersaran; pude volar hasta aquí después de que mis colegas de Ravenholdt supieran de una batalla naval más allá de estas costas.$b$bEstas tierra ha estado escondida durante 10000 años. No he hecho más que empezar a sondear sus secretos.' WHERE `ID`=65126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 돌아와서 기쁘군, $n! 지금쯤이면 이 낯선 판다리아 대륙에도 익숙해졌겠지?$b$b너의 실력이야 과거의 경험을 통해 이미 잘 알고 있으니 시험 따위는 집어치우지. 바로 본론으로 들어가자고.$b$b세상에 도전할 준비는 됐나?', `MaleText_loc4`='你回来我很高兴，$n！我相信你现在已经适应了潘达利亚这片奇怪的新大陆，对吗？$b$b你过去已经证明了自己，这样我们就可以免去任何类似的测试或试验。让我们马上开始。$b$b你准备好改变世界了吗？', `MaleText_loc5`='很高興看到你回來了，$n!相信你已經適應了潘達利亞這片新土地?$b$b你在過去就已向我證明過自己的價值，所以我們可以省去所有的測試或試煉那一套，直接切入正題吧。$b$b你準備好改變世界了嗎?', `MaleText_loc7`='¡Me alegro de que hayas vuelto, $n! Supongo que ahora ya estás $gacostumbrado:acostumbrada; a este extraño nuevo continente de Pandaria, ¿no es así?$b$bYa has demostrado tu valía con anterioridad, así que podemos ahorrarnos cualquier tipo de prueba o examen. Vayamos al grano.$b$b¿Estás $gpreparado:preparada; para cambiar el mundo?' WHERE `ID`=65127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, $c|1이여;여;! 판다리아 전역에 퍼진 내 소식통들이 말하길, 네가 여기서 무척 바빴다더군. 나는 너처럼 그렇게... "진취적인" 필멸자들을 존경하지.$b$b우리는 역사의 기로에 서 있다. 네가 나와 함께 당당히 운명에 맞설 준비가 됐다면, 훗날 그간의 노고에 걸맞은 훌륭한 보상을 얻게 될 거라고 내 약속하지.', `MaleText_loc4`='欢迎，$c！我的眼线遍布潘达利亚，我得知，你一直都在忙碌着。我敬佩具备……“主动性”的凡人们。$b$b我们正处在一个历史的转折点上。如果你愿意带着我去迎接命运，我会确保你的付出能得到丰厚的回报。', `MaleText_loc5`='歡迎，$c!我在潘達利亞各地的聯絡人告訴我你在這裡過得相當忙碌。我很欣賞你們凡人的這種...「動力」。$b$b從歷史上來看，我們正處於一個轉捩點。如果你準備好和我一起面對眼前的命運，我會確保你為付出的努力得到豐厚的報酬。', `MaleText_loc7`='¡$gBienvenido:Bienvenida;, $c! Mis contactos por toda Pandaria me han informado de que has estado bastante $gocupado:ocupada; por aquí. Los admiro, mortales, por su... "iniciativa".$b$bEstamos ante un momento en el que la historia puede cambiar de manera radical. Si estás $gpreparado:preparada; para encontrarte con el destino, ven conmigo y me aseguraré de que se te recompense de manera adecuada por tus esfuerzos.' WHERE `ID`=65128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 우리의 여정은 이제 막 시작이다, $n.', `MaleText_loc4`='我们的熊猫人战役才刚刚开始，$n。', `MaleText_loc5`='我們在潘達利亞的戰役才剛剛開始，$n。', `MaleText_loc7`='No hemos hecho más que empezar nuestra campaña pandaren, $n.' WHERE `ID`=65129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드디어 아버지가 그토록 찾던 젊음의 웅덩이를 찾은 것 같아요. 이제 티란데 님께 전할 정보를 최대한 많이 수집해야 해요.', `FemaleText_loc4`='我相信我们最终可以找到我父亲的青春之池。我们可以为泰兰德提供尽可能多的信息。', `FemaleText_loc5`='我相信我們或許終於找到我父親的青春之池了。我們得盡力為泰蘭妲蒐集最多的情報。', `FemaleText_loc7`='Creo que hemos encontrado al fin las Pozas de la Juventud de mi padre. Debemos reunir toda la información que podamos para Tyrande.' WHERE `ID`=65130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 파수꾼들은 이 땅에 온 이후로 많은 위험을 겪었어요. 앞으로 무슨 일이 일어나든, 우린 준비돼 있어요.', `FemaleText_loc4`='因为我们来到这片新的土地，所以我的哨兵面临许多危险。我们准备好迎接任何挑战。', `FemaleText_loc5`='來到這片新土地後，我的哨兵曾面臨數不清的危險。我們準備好面對未來的一切了。', `FemaleText_loc7`='Mis centinelas han afrontado muchos peligros desde que llegamos a esta nueva tierra. Estamos listas para cualquier cosa que nos depare el futuro.' WHERE `ID`=65131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원꽃 골짜기에 온 후로 우리 부대의 사기가 높아졌어요.', `FemaleText_loc4`='在进入四风谷后，我军的士气有所提高。', `FemaleText_loc5`='進入山谷後，我部隊的士氣提升了。', `FemaleText_loc7`='La moral de mi escuadrón ha aumentado desde que entramos en el valle.' WHERE `ID`=65132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 골짜기는 진정 천국이에요.', `FemaleText_loc4`='四风谷真是个的天堂。', `FemaleText_loc5`='這山谷真是個天堂。', `FemaleText_loc7`='Este valle es un auténtico paraíso.' WHERE `ID`=65133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 보는 게 아버지의 꿈이었죠. 아버지의 뜻을 제가 대신 이루겠어요.', `FemaleText_loc4`='亲眼见到这个地方是我父亲的梦想。我必须在这里完成他的心愿。', `FemaleText_loc5`='我父親的夢想就是看看這個地方。我必須代替他實現這個願望。', `FemaleText_loc7`='Ver este valle era el sueño de mi padre. Debo hacer realidad sus deseos en su lugar.' WHERE `ID`=65134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽 해안에서 불길한 바람이 불어오는군. 준비되었나?', `MaleText_loc4`='从南部海岸刮来了一阵恶风。你准备好了吗？', `MaleText_loc5`='喪風從南方海岸吹來。你準備好面對了嗎?', `MaleText_loc7`='Un viento de enfermedad viene de las costas del sur. ¿Estás $gpreparado:preparada;?' WHERE `ID`=65135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조사가 끝날 때까지 골짜기에 머무르려 해요. 그 다음에는 고향으로 돌아갈 방법을 찾아 봐야지요.', `FemaleText_loc4`='在收集我们所要的信息之前，我们都在这个谷里休息。然后，我们必须想方设法回家。', `FemaleText_loc5`='我們會在山谷中駐紮，直到我們的研究完成。到時候，我們會找尋回家的方法。', `FemaleText_loc7`='Descansaremos aquí en el valle hasta que finalicemos nuestra investigación. Después, tendremos que encontrar un camino a casa.' WHERE `ID`=65136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기에는 모종의 장벽이 있어서, 차원문 마법을 쓸 수가 없습니다.', `MaleText_loc4`='这里有一些屏障保护着四风谷，阴止我使用传送门魔法。', `MaleText_loc5`='有某種護盾籠罩著這個山谷，讓我無法使用傳送法術。', `MaleText_loc7`='Hay una especie de barrera que protege este valle. Me impide utilizar mi magia de portal.' WHERE `ID`=65137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 이렇게 골짜기에서 만난 건 단순한 우연이 아니겠죠.', `FemaleText_loc4`='我们能在这个四风谷遇见还真巧。', `FemaleText_loc5`='我們能在這山谷遇見彼此並不只是偶然。', `FemaleText_loc7`='Que nos encontremos en este valle no es simple casualidad.' WHERE `ID`=65138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬의 교만이 골짜기를 파괴했어요. 예전의 모습을 결코 되찾지 못하겠죠.', `FemaleText_loc4`='加尔鲁什的狂妄摧毁了锦绣谷。这是无法治愈的创伤。', `FemaleText_loc5`='卡爾洛斯的傲慢摧毀了恆春谷。曾經的美好已經永不再來。', `FemaleText_loc7`='El orgullo de Garrosh ha asolado el valle. Nunca volverá a ser lo que era.' WHERE `ID`=65139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티란데 님께서는 저희를 빛의 선봉대로서 이곳에 파견하셨어요.', `FemaleText_loc4`='泰兰德派我们来这里寻找圣光。', `FemaleText_loc5`='泰蘭妲派我們這裡擔任找尋聖光的先鋒。', `FemaleText_loc7`='Tyrande nos ha enviado aquí como avanzadilla de la Luz.' WHERE `ID`=65140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 나무는 남쪽 밀림의 나무보다 더 아름답네요.', `FemaleText_loc4`='这里的树比我在南部丛林见过的都更漂亮。', `FemaleText_loc5`='這裡的樹比我在南方叢林所見過的樹都要更美。', `FemaleText_loc7`='Los árboles de aquí son aún más bonitos que los de la jungla del sur.' WHERE `ID`=65141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 원정을 다녔는데도, 이런 곳은 처음 봅니다.', `FemaleText_loc4`='我从来没有见过像这样的地方。', `FemaleText_loc5`='我從來也沒見過像這樣的地方。', `FemaleText_loc7`='Nunca en mi vida había visto un lugar como este.' WHERE `ID`=65142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 골짜기의 물이 과연 전설의 "젊음의 웅덩이"일까요? 어쩌면 불멸성을 다시 손에 넣을 수 있을지도 모르겠군요.', `FemaleText_loc4`='这山谷里的池水莫非就是传说中的“青春之池”？也许我们可以再次掌握永生……', `FemaleText_loc5`='這谷中的池水難道就是傳說中的『青春之池』?。或許再度獲得永生之日距離我們不遠...', `FemaleText_loc7`='¿Podría ser que las aguas de este valle fueran las legendarias "Pozas de la Juventud"? Quizá podamos disfrutar de la inmortalidad de nuevo...' WHERE `ID`=65143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구가 골짜기에 침투했다는 보고가 있었습니다. 하지만 우리를 꺾지는 못할 겁니다.', `FemaleText_loc4`='我们已经听说了魔古族遍布四风谷的消息。他们不会胜过我们的。', `FemaleText_loc5`='我們收到魔古軍隊入侵這山谷的消息。他們絕對闖不過我們這關。', `FemaleText_loc7`='Hemos recibido informes de mogu infiltrándose en este valle. No cruzarán nuestras líneas.' WHERE `ID`=65144;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 웅덩이를 수색하는 한편으로, 이 도시의 경계를 순찰하며 사람들을 보호할 것입니다.', `FemaleText_loc4`='我们在研究池水的同时，还会巡逻城市的边界，保护这里的人。', `FemaleText_loc5`='在我們研究青春之池的同時，我們會在城市的邊緣巡邏，保護這些人。', `FemaleText_loc7`='Mientras investigamos las pozas, patrullaremos las fronteras de la ciudad y protegeremos a esta gente.' WHERE `ID`=65145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='솔직히 말하면 처음에는 밸드린의 환영을 믿지 않았습니다. 그런데 이곳은 묘한 마법의 기운을 발산합니다. 과연 전설의 "젊음의 웅덩이" 때문일까요?', `FemaleText_loc4`='说实话，我起初并不相信瓦尔德林看见的幻像。但这地方确实散发着不同寻常的魔法之力——难道这就是传说中的“青春之池”？', `FemaleText_loc5`='老實說，我最開始並不相信費爾迪林的幻象。但這地方充滿了不尋常的魔法，難道這就是傳說中的『青春之池』?', `FemaleText_loc7`='Sinceramente, antes no creía que las visiones de Vaeldrin fueran ciertas, pero este lugar emana una magia extraña. ¿Podrían ser las legendarias Pozas de la Juventud?' WHERE `ID`=65146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 있으면 그 유명한 빈안의 맥주달 축제를 즐겨 보게. 나도 거기서 내 장기인 쿤라이 뻥뻥주를 만들 거라네.', `MaleText_loc4`='如果你有时间，你应该参观滨岸有名的酿月祭。我会酿造一些著名的昆莱劲酒。', `MaleText_loc5`='如果你有時間，你應該去濱南有名的酒月節看看。我會釀一些我最有名的崑萊好勁道酒。', `MaleText_loc7`='Si tienes ocasión, deberías visitar el famoso Festival de la Cerveza Lunar. Elaboraré mi famoso brebaje Pateadora de Kun-Lai.' WHERE `ID`=65147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면, 이 골짜기에서 큰 전투가 벌어져 황금빛 들판이 용감한 수도사들의 피로 붉게 물들었다고 하네. 모구 황제였던 천둥왕 레이 션의 군대는 필사적으로 싸웠으나 결국 지고 말았지.', `MaleText_loc4`='传说在这四风谷发生了大会战，许多勇敢武僧的鲜血将金色的原野染成了红色。魔古皇帝雷电之王雷神的军队战斗野蛮，但是最终被攻克。', `MaleText_loc5`='傳說在谷中曾經有一場偉大的戰役，金黃的原野被許多勇敢武僧的血染成鮮紅。魔古皇帝『雷王』雷神的大軍殺紅了眼，但最終他們還是被武僧們擊潰了。', `MaleText_loc7`='La leyenda habla de una gran batalla que tuvo lugar en este mismo valle, esta batalla transformó de carmesí los campos dorados con la sangre de muchos monjes valientes. Los ejércitos de Lei Shen, el Rey del Trueno, emperador de los mogu, lucharon con brutalidad pero al final fueron vencidos.' WHERE `ID`=65148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 간들링! 놈을 없애!', `MaleText_loc4`='去死吧，加丁！杀了他！', `MaleText_loc5`='死吧，加丁!殺了他!', `MaleText_loc7`='¡Muere, Gandling! ¡Mátenlo!' WHERE `ID`=65149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함선이 200척이나 있는데 하필 내 아들이 탄 배가 사라지다니!', `MaleText_loc4`='我有两百多艘船，唯独载着我儿子的那艘……不见了！', `MaleText_loc5`='兩百艘船任我指揮，載著我兒子的那艘卻消失了!', `MaleText_loc7`='¡Doscientas naves a mi disposición, y es la de mi HIJO la que hace falta!' WHERE `ID`=65150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해요. 아직 돌아갈 순 없어요.', `MaleText_loc4`='我很抱歉，可我暂时还不能回去。', `MaleText_loc5`='我很抱歉，但我還不能回去。', `MaleText_loc7`='Lo siento, pero todavía no puedo regresar.' WHERE `ID`=65151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 골짜기를 찾아보겠어요...', `MaleText_loc4`='我决心去寻找那座溪谷……溪谷……溪谷……', `MaleText_loc5`='我決定要去找尋那山谷...山谷...', `MaleText_loc7`='He decidido ir a buscar el valle... buscar el valle... buscar el valle...' WHERE `ID`=65152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해안을 휩쓸고 이 신대륙을 붉게 물들여라!', `MaleText_loc4`='抢占那片海滩，将那岛屿染成红色！', `MaleText_loc5`='席捲海岸，把這塊新大陸染紅!', `MaleText_loc7`='¡IRRUMPAN en la costa y tiñan de ROJO el nuevo continente!' WHERE `ID`=65153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|t|cFFFF0000|Hspell:126228|h[떠도는 영혼]|h|r이 당신을 괴롭힙니다! 처치하십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|t你受|cFFFF0000|Hspell:126228|h[撕裂的灵魂]|h|r的影响！杀了它！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_improvedsoulleech:20|t你受到|cFFFF0000|Hspell:126228|h[分割之魂]|h|r影響!殺了它!', `MaleText_loc7`='|TInterfaceIconsability_warlock_improvedsoulleech:20|tTe está afectando |cFFFF0000|Hspell:126228|h[Alma separada]|h|r! ¡Dale fin!' WHERE `ID`=65154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 션이 죽은 후, 골짜기 위에는 며칠이나 칠흑 같은 구름이 떠 있었다네. 레이 션이 마지막 순간 불러 낸 폭풍은, 골짜기에 비를 내리고 언덕에 날카로운 벼락을 내리 꽂았지.', `MaleText_loc4`='雷神溃败后的这些天，四风谷被最深黑色的乌云笼罩。雷神在他临终前召唤出异世的风暴笼罩四风谷，伴随着降雨和锯齿状的闪电长矛劈落在山上。', `MaleText_loc5`='雷神敗亡後的接下來幾天，谷中被最漆黑的烏雲遮蓋住。雷神在他死前召喚來了異界風暴，在谷中下起了傾盆大雨，像鋸齒長矛般的閃電不停地打在山丘上。', `MaleText_loc7`='Durante días, tras la caída de Lei Shen, el valle estaba cubierto con una nube del negro más oscuro. La tormenta de otro mundo, que había invocado Lei Shen en sus momentos finales, cubrió todo el valle de lluvia y lanzó relámpagos dentados en las colinas.' WHERE `ID`=65155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍에 씻긴 전사자의 피가 흰꽃잎 호수로 흘러들면서, 호수 물은 검붉은 색으로 변했지. 폭풍은 마지막으로 호수 한가운데를 내리쳤고, 그러자 물에 불이 붙었다네. 호수는 며칠이나 핏빛으로 불타 올랐지.', `MaleText_loc4`='亡者的鲜血被风暴冲刷到琼花湖，把湖水染成深红色。凭借最后一口气，风暴袭击了湖中心，点燃了湖水本身。湖水被烧了很多天，呈现出深红色。', `MaleText_loc5`='戰死者的血液被風暴沖洗到了白瓣湖之中，將湖水染得深紅。就在最後一刻，風暴閃電擊中了湖心，將整個湖面點燃。白瓣湖就這麼燒了許多天，發出赤紅的光芒。', `MaleText_loc7`='La sangre de los caídos se limpió con la tormenta y fue arrastrada al lago Pétalo Níveo, tiñendo las aguas de un rojo intenso. En su aliento final, la tormenta cayó en el centro del lago y prendió fuego al agua misma. El lago ardió con un tono carmesí durante muchos días.' WHERE `ID`=65156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 잦아들고 나니, 새끼 운룡 한 마리가 호수 중앙을 날고 있는 모습이 보였다네. 비늘은 폭풍와 불길의 기운으로 불꽃이 튀었고, 날아가는 곳마다 구름이 생겨났지. 우리 민족은 그 운룡에게 ''폭풍의 후예 알라니''라는 이름을 붙여 주었다네.', `MaleText_loc4`='当大火平息，云端翔龙孵化，在湖中心周围飞行。它的鳞屑点燃风暴和火焰。在它所到之处，天空中呈现祥云朵朵。我的人把它称为阿拉尼，风暴之子的意思。', `MaleText_loc5`='當火焰消退後，有一隻雲蛟幼龍在湖心周圍盤旋。它的鱗片會發出閃電和火焰，它所到之處都會有巨大的烏雲在空中形成。我們族人稱它為阿拉尼，風暴之子。', `MaleText_loc7`='Cuando el fuego se extinguió, se pudo ver una cría de dragón nimbo volando alrededor del centro del lago. Sus escamas brillaban con la tormenta y el fuego, y por donde volaba, se formaban inmensas nubes en el cielo. Mi gente lo llamó Alani el Natormento.' WHERE `ID`=65157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알라니는 가장 밝은 번갯불만 볼 수 있고, 가장 큰 천둥 소리만 들을 수 있다고 하네. 알라니의 주의를 끌려면, 알라니를 낳은 하늘의 정수를 이용해야 할 걸세.', `MaleText_loc4`='他们说，阿拉尼只能看到最亮的闪电，也许只能听到最响惊雷的回声。你如果希望得到她的注意，则需要利用催生了她的天空本身。', `MaleText_loc5`='有人說阿拉尼只能看見最強大閃電的閃光，只能聽見最震撼雷聲的回音。如果你想要得到她的注意，你必須掌控讓她誕生的天空之精華。', `MaleText_loc7`='Se dice que Alani solo puede ver el centelleo de los relámpagos más grandes y que solo podía escuchar el eco de los truenos más sonoros. Si desearas llamar su atención tendrías que controlar las auténtica esencia del cielo que lo generaron.' WHERE `ID`=65158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 다음엔 어떻게 됐습니까?', `MaleText_loc4`='然后发生了什么事？', `MaleText_loc5`='然後發生了什麼事?', `MaleText_loc7`='¿Y ENTONES qué pasó?', `FemaleText_loc1`='그 다음엔 어떻게 됐나요?', `FemaleText_loc4`='然后发生了什么事？', `FemaleText_loc5`='然後發生了什麼事?', `FemaleText_loc7`='¿Y ENTONES qué pasó?' WHERE `ID`=65159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, 친구! 이곳을 찾는 이는 드문데... 영원꽃 골짜기에 얽힌 이야기를 듣고 싶은가?', `MaleText_loc4`='你好，朋友！我这里通常不会有太多人造访，你是否想听听锦绣谷的故事？', `MaleText_loc5`='你好，朋友!我這裡很少會有訪客，你想要聽聽恆春谷的故事嗎?', `MaleText_loc7`='Saludos, $gamigo:amiga;. No recibo muchas visitas por aquí. ¿Quieres escuchar un cuento del Valle de la Flor Eterna?' WHERE `ID`=65160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네!', `MaleText_loc4`='我想！', `MaleText_loc5`='我想!', `MaleText_loc7`='¡Sí!', `FemaleText_loc1`='네!', `FemaleText_loc4`='我想！', `FemaleText_loc5`='我想!', `FemaleText_loc7`='¡Sí!' WHERE `ID`=65161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 말 되는군요!', `MaleText_loc4`='这很有意义！', `MaleText_loc5`='有道理!', `MaleText_loc7`='¡Esto tiene mucho sentido!', `FemaleText_loc1`='그거 말 되네요!', `FemaleText_loc4`='这很有意义！', `FemaleText_loc5`='有道理!', `FemaleText_loc7`='¡Esto tiene mucho sentido!' WHERE `ID`=65162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 우낏! 맥주는 호젠 거다!', `MaleText_loc4`='该死的蠢蛋！啤酒是给猢狲的！', `MaleText_loc5`='蠢怪怪人!酒是屬於猴人的!', `MaleText_loc7`='¡Makaku tonto! ¡Brebaje es para hozen!' WHERE `ID`=65164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주야, 도망쳐!', `MaleText_loc4`='倒酒！', `MaleText_loc5`='酒流出來了!', `MaleText_loc7`='¡A por el brebaje!' WHERE `ID`=65165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너한테 줄 맥주 없다!', `MaleText_loc4`='没有你的啤酒！', `MaleText_loc5`='不給你酒!', `MaleText_loc7`='¡No hay cerveza para ustedes!' WHERE `ID`=65166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이이이야아아아!', `MaleText_loc4`='嘿呀！', `MaleText_loc5`='嘿呀!', `MaleText_loc7`='¡Ayarrrrrrrr!' WHERE `ID`=65167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 년 동안 누구도 손대지 않은 모구의 고대 금고라니... 어떤 비밀이 기다릴지 누가 알겠나?', `MaleText_loc4`='魔古族的古老地宫，数千年来封存未动，谁知道里面有什么秘密？', `MaleText_loc5`='魔古的古老墓穴，幾千年來未曾被打擾。誰知道藏了什麼秘密?', `MaleText_loc7`='Las antiguas cámaras de los mogu, intactas tras miles de años... ¿quién sabe qué secretos albergan?' WHERE `ID`=65168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 하나! 하나는 응가!', `MaleText_loc4`='人人为我！我为乌克！', `MaleText_loc5`='人人為我!我為烏克!', `MaleText_loc7`='¡Todos para uno! ¡Y uno para Ook!' WHERE `ID`=65169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊은 판다렌 전사들이 이 무덤에서 쓰러졌네. 조심해야 하네.', `MaleText_loc4`='许多年轻的熊猫人都在这墓穴里……蒸发了。时刻保持警惕。', `MaleText_loc5`='許多年輕的熊貓人戰士在這個...墓穴中消失了。保持警戒啊。', `MaleText_loc7`='Muchos jóvenes guerreros pandaren han desaparecido en esta... tumba. No bajes la guardia.' WHERE `ID`=65170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 자신들의 힘으로 대지의 바위를 조종했네. 수백 년이 지난 지금도 그 마법이 남아 있지.', `MaleText_loc4`='魔古族对大地的石头有着极大的控制力。他们的魔法直到数个世纪之后余力犹存。', `MaleText_loc5`='魔古對地上的石頭有強大的掌控力。在許多世紀過後，這些魔法還存在著。', `MaleText_loc7`='Los mogu ostentaban un gran poder sobre la piedra. Su magia aún se conserva, siglos después.' WHERE `ID`=65171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 기렌이 문을 지키고 있군. 깨우지 않게 조심하게.', `MaleText_loc4`='庞大的魁麟似乎在把守大门。小心前行，以免唤醒它们。', `MaleText_loc5`='大型的麒麟獸似乎在守護那道門。小心行動，免得把它們吵醒。', `MaleText_loc7`='Parece que esos grandes quilen custodian la puerta. Mira dónde pisas o los despertarás.' WHERE `ID`=65172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주... 아슬아슬했군!', `MaleText_loc4`='真险哪！', `MaleText_loc5`='差一點!', `MaleText_loc7`='¡Estuvo cerca!' WHERE `ID`=65173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자들이 죽으면서 문이 작동한 것 같아. 이 안에 무엇이 있을지 걱정이 되네.', `MaleText_loc4`='随着守卫的死去，大门的装置似乎被激活了。不知我们会在里面有何遭遇。', `MaleText_loc5`='門的機關似乎被守衛的死亡觸發了。我很害怕裡面可能會找到的東西。', `MaleText_loc7`='Creo que la muerte de los guardianes ha activado el mecanismo de la puerta. No quiero pensar en lo que habrá dentro.' WHERE `ID`=65174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어떤 정령을 깨운 것 같군.', `MaleText_loc4`='我们似乎唤醒了什么东西的灵魂。', `MaleText_loc5`='我們似乎喚醒了某種靈魂。', `MaleText_loc7`='Parece que hemos despertado a algún tipo de espíritu.' WHERE `ID`=65175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이야기가 사실이었군...', `MaleText_loc4`='看来传说是真的……', `MaleText_loc5`='看來故事是真的...', `MaleText_loc7`='Así que las historias eran ciertas...' WHERE `ID`=65176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 깨우지 말아야 할 것을 깨웠네. 이 감옥에서 도망치게 할 수는 없어! 자네가 없애야 하네!', `MaleText_loc4`='我们打扰了不该打扰的东西。决不能让他逃离这囚牢！你必须消灭他！', `MaleText_loc5`='我們打擾了不該打擾的東西。不能讓他逃出這個牢籠!你必須摧毀他!', `MaleText_loc7`='Hemos despertado a alguien que no habría que despertar. ¡No puede escapar de la prisión! ¡Debes matarlo!' WHERE `ID`=65177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저주받은 펑은 모구의 네 황제에게 배신당하고, 매번 육신이 파괴되었지만, 늘 다시 살아났네.', `MaleText_loc4`='受诅者魔封遭到了四位魔古皇帝的背叛，他的身体每次都被摧毁，然后再度复活。', `MaleText_loc5`='『咒魔』馮被魔古的四個皇帝背叛，多次摧毀了他的身體，但不斷重生。', `MaleText_loc7`='Feng el Detestable fue traicionado por cuatro emperadores mogu. Destrozaron su cuerpo cada vez, pero siguió alzándose.' WHERE `ID`=65178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호로젠들아! 모여라!', `MaleText_loc4`='猢狲打刀手！集合！', `MaleText_loc5`='猴子槍兵!集合!', `MaleText_loc7`='¡Korsarios hozen! ¡Reuníos!' WHERE `ID`=65179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='펑이 완전히 사라진 건 아닐 거야...', `MaleText_loc4`='这不会是我们最后一次看见魔封……', `MaleText_loc5`='這不會是我們最後一次看到馮...', `MaleText_loc7`='No es la última vez que vemos a Feng…' WHERE `ID`=65180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족이라니! 모구의 고대 동맹이야! 금고 깊은 곳에 있는 전설의 무기를 찾는 것이 틀림없네!', `MaleText_loc4`='赞达拉——魔古族的古老盟友！他们一定在宝库深处寻找传说中的武器！', `MaleText_loc5`='贊達拉，魔古的古老盟友!他們一定在尋找墓穴內的傳說武器!', `MaleText_loc7`='¡Los Zandalari, antiguos aliados de los mogu! Deben de buscar el arma legendaria de las profundidades de las cámaras.' WHERE `ID`=65181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏이다!', `MaleText_loc4`='蠢蛋！', `MaleText_loc5`='怪怪人!', `MaleText_loc7`='¡Makakus!' WHERE `ID`=65182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔치 망치러 왔다!', `MaleText_loc4`='不速之客！', `MaleText_loc5`='派對破壞者!', `MaleText_loc7`='¡Kolados!' WHERE `ID`=65183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이이야아아!', `MaleText_loc4`='嘿呀！', `MaleText_loc5`='嘿呀!', `MaleText_loc7`='¡Ayarrrr!' WHERE `ID`=65184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 맥주 못 가져간다!', `MaleText_loc4`='你没有拿酒！', `MaleText_loc5`='你不可以拿酒!', `MaleText_loc7`='¡No koge brebaje!' WHERE `ID`=65185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 궁둥이 차 줘라!', `MaleText_loc4`='拿下他们的头目！', `MaleText_loc5`='拿走他們的蛋蛋!', `MaleText_loc7`='¡Koged sus rukos!' WHERE `ID`=65186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼 선장님을 위해!', `MaleText_loc4`='为了乌克头领！', `MaleText_loc5`='為了烏克船長!', `MaleText_loc7`='¡Por el kapitán Ook!' WHERE `ID`=65187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미리 얘기를 못해서 미안하군! 이 금고에는 믿을 수 없는 힘을 지닌 무기가 숨어 있네! 저들을 막게!', `MaleText_loc4`='抱歉我没有早点告诉你！在这宝库里有一把威力无穷的武器！阻止他们！', `MaleText_loc5`='我很抱歉沒有提早告訴你們!這些墓穴藏著一把不可思議的強大武器!阻止他們!', `MaleText_loc7`='Siento no habértelo contado antes. Estas cámaras albergan un arma de increíble poder. ¡Detenlos!' WHERE `ID`=65188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 여기 남아서, 이 연단을 더 조사해 보겠네...', `MaleText_loc4`='我要留下，进一步调查这里……', `MaleText_loc5`='我會留在這裡深入調查這個裝置...', `MaleText_loc7`='Me quedaré aquí para investigar el estrado…' WHERE `ID`=65189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단상 아래에서 비밀 통로가 열렸네. 이쪽이야!', `MaleText_loc4`='这台子底下有个秘密通道，来这边！', `MaleText_loc5`='平台下有一條秘密通道打開了，往這裡走!', `MaleText_loc7`='¡Se ha abierto un pasadizo secreto bajo la plataforma! ¡Por aquí!' WHERE `ID`=65190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바닥에 쌓인 먼지를 보게. 몇 세기 동안 이 통로를 지나간 이가 없었을 거야.', `MaleText_loc4`='看看地上的灰尘，这黑暗的殿堂已有几百年无人踏入了。', `MaleText_loc5`='看看地板上的灰塵，這些黑暗的大廳已經有幾世紀沒有人踏入了。', `MaleText_loc7`='Mira cuánto polvo hay en el suelo. Nadie ha pisado estas salas desde hace muchos siglos.' WHERE `ID`=65191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때, 모구는 판다리아의 모든 종족을 자신들의 사악한 목적을 위해 지배했네.', `MaleText_loc4`='魔古族曾奴役潘达利亚的所有种族，并让他们屈从于自己的邪恶意志。', `MaleText_loc5`='魔古曾奴役潘達利亞上的所有種族，讓他們屈服在惡毒的意志之下。', `MaleText_loc7`='Hace mucho tiempo los mogu esclavizaron a todas las razas de Pandaria y las sometieron a su voluntad.' WHERE `ID`=65192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 진위들은 이렇게 갇혀 영원히 모구를 섬기는군.', `MaleText_loc4`='这些锦鱼人被囚禁在永恒的奴役之中。', `MaleText_loc5`='這些錦魚人已經被奴役的枷鎖綁住了不知多久。', `MaleText_loc7`='Estos jinyu han sido víctimas de una esclavitud eterna.' WHERE `ID`=65193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웅웅거리는 소리가 희미하게 들리네... 이쪽 방향이야!', `MaleText_loc4`='我听见了微弱的嗡鸣声。是从这个方向传来的！', `MaleText_loc5`='我聽到一陣微弱的嗡嗡聲，是從這個方向來的!', `MaleText_loc7`='Oigo un zumbido distante. ¡Viene de esta dirección!' WHERE `ID`=65194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났군. 그렇지만... 땅 아래 이 기계들이 얼마나 많이 감춰져 있을까? 모구의 어두운 비밀에 대해 우리가 모르는 게 얼마나 많을까?', `MaleText_loc4`='那就结束了。可是……地下藏有多少这种机器？我们对魔古族的黑暗秘密又知道多少？', `MaleText_loc5`='就這樣了。但是...還有多少這種機器被藏在地下?魔古還有多少黑暗的秘密是我們所不知道的?', `MaleText_loc7`='Entonces ya está hecho. Pero... ¿cuántas de estas máquinas se ocultan bajo la tierra? ¿Cuánto ignoramos de los oscuros secretos de los mogu?' WHERE `ID`=65195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대의 적과 우리 사이의 전쟁은 아직 끝나지 않은 것 같군.', `MaleText_loc4`='恐怕我们对抗远古敌人的战斗还远未结束。', `MaleText_loc5`='我擔心這場對抗我們古老敵人的戰爭離結束還很遠。', `MaleText_loc7`='Me temo que la guerra contra nuestros antiguos enemigos acaba de empezar.' WHERE `ID`=65196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 실제로 작동하는 모구의 기계 장치라니.', `MaleText_loc4`='难以置信！一台真真切切的魔古建造机器。', `MaleText_loc5`='太驚人了!一台由魔古打造、到現在還能運作的機器。', `MaleText_loc7`='¡Impresionante! Una máquina de construcción mogu que funciona.' WHERE `ID`=65197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악한 자의 손에 들어가게 해서는 안 되네.', `MaleText_loc4`='千万不能让它落入恶人之手。', `MaleText_loc5`='我們不能讓這台機器落入壞人手中。', `MaleText_loc7`='No podemos permitir que caiga en malas manos.' WHERE `ID`=65198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼 없는 괴물들을 끝없이 만들어 내겠지... 이런 기계 때문에 생겨날 비극을 생각하니 몸서리쳐지는군.', `MaleText_loc4`='无数没有灵魂的、畸形的怪物，浩浩荡荡……想到这机器中会涌出怎样的邪恶，我就打寒颤。', `MaleText_loc5`='沒有靈魂的無盡怪物大軍...我不敢想像這台機器能造成多麼慘重的傷害。', `MaleText_loc7`='Un ejército de abominaciones desalmadas... Me estremezco al pensar en la violencia que podría brotar de esta máquina.' WHERE `ID`=65199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴해야 하네. 지금, 여기서. 판다리아에 위험을 초래하지 않게.', `MaleText_loc4`='就在此地，就趁现在，必须在它危害潘达利亚之前摧毁它。', `MaleText_loc5`='你一定要毀掉它。此時，此刻，避免它對潘達利亞造成傷害。', `MaleText_loc7`='Debes destruirla. Aquí y ahora, antes de que algún mal se cierna sobre Pandaria.' WHERE `ID`=65200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계를 켜게. 내가 뒤에서 문을 잠그겠네.', `MaleText_loc4`='打开这台机器，我会帮你锁住后面的门。', `MaleText_loc5`='打開那台機器，我會把你身後那道門鎖上。', `MaleText_loc7`='Enciende la máquina. Yo cerraré la puerta.' WHERE `ID`=65201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 학이 자네 걸음을 이끌기를.', `MaleText_loc4`='让神鹤指引你的脚步。', `MaleText_loc5`='願偉大的紅鶴指引你的路。', `MaleText_loc7`='Que la Gran Grulla guíe tus pasos.' WHERE `ID`=65202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 돌아와라, 비겁한 놈!', `MaleText_loc4`='不！回来，懦夫！', `MaleText_loc5`='不!給我回來，懦夫!', `MaleText_loc7`='¡No! ¡Vuelve, cobarde!' WHERE `ID`=65203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 훌륭한 독은 아주 많다. 어떤 독은 널 산채로 끓여 죽일 수도 있고, 어떤 건 네 살을 먹기도 한다. 또 어떤 독은 몸 안에서 밖으로 폭발할 수도 있지.$B$B그 다양성이 아주 훌륭하다.', `MaleText_loc4`='唤醒者，这有许多奇妙的毒药。有些毒药可以活煮了你。有些会吞噬你的肉。有些会炸开你的肚子。$B$B这么多奇妙的毒药。', `MaleText_loc5`='世上有許多奇妙的劇毒，喚醒者。有些能讓你活生生地全身沸騰而死。有些會侵噬你的血肉。有些會讓你從體內爆裂而死。$B$B許多許多奇妙的種類。', `MaleText_loc7`='Hay muchos venenos maravillosos, heraldo. Algunos pueden cocerte $gvivo:viva;. Otros te devoran la carne. Otros te hacen estallar desde dentro.$B$BHay muchas variedades maravillosas.' WHERE `ID`=65204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 저걸 없애라! 간들링을 잡으러 가야지!', `MaleText_loc4`='快，摧毁它们。我们要追赶加丁！', `MaleText_loc5`='快點，摧毀那個東西。我們必須抓住加丁。', `MaleText_loc7`='Vamos, destruid esa cosa. ¡Tenemos que pillar a Gandling!' WHERE `ID`=65205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 독을 마셔본 적이 있나? 처음에는 몇 방울만, 그리고 아주 부드러운 것으로 선택해서 마셔야 한다.$B$B엄청난 고통에 시달릴 수도 있다. 더듬이를 한 개, 아니면 둘 다 잃을 수도 있지.$B$B하지만 독을 오랫동안 계속 마시면, 그 독에 꽤 익숙해질 것이다.', `MaleText_loc4`='唤醒者，你试喝过毒药吗？开始时，你必须服用毒性非常温和的，第一次几滴就行了。$B$B然后，你很可能会生一场大病，也许甚至会失去一根或两根触须。$B$B但是，只要时间足够长，你就会慢慢适应。', `MaleText_loc5`='你有試過飲毒嗎，喚醒者?你必須先從毒性微弱的開始，起初只能喝幾滴。$B$B你將會感到十分不適。你也許還會掉幾根觸鬚。$B$B但久而久之你就會相當習慣了。', `MaleText_loc7`='¿Has probado alguna vez a beber veneno, heraldo? Debes empezar con algo muy suave, solo unas gotas al principio.$B$BLo más probable es que caigas gravemente $genfermo:enferma;. Puede que hasta pierdas una antena o dos.$B$BPero si lo haces el tiempo suficiente, te acostumbrarás.' WHERE `ID`=65206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자!', `MaleText_loc4`='出发！', `MaleText_loc5`='我們走!', `MaleText_loc7`='¡Vamos!' WHERE `ID`=65207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 한때 여제 셰크지르 님께서 가장 총애하시던 황실 연금술사였다. 내 실력을 따라올 자가 없었지.', `MaleText_loc4`='我曾经是夏柯希尔女皇最看重的皇家炼金术士，技术无人能及。', `MaleText_loc5`='我曾經是女皇杉齊爾最倚重的皇家鍊金師，我的地位一人之下，萬人之上。', `MaleText_loc7`='En un tiempo fui el alquimista real más preciado de la emperatriz Shek''zeer, sin igual, por encima de todos los demás.' WHERE `ID`=65208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='푸하! 운속이 일꾼이었을 때가 아직도 기억나는군. 처음에는 독을 섞는 것도 무서워했었지. 내가 혼자 가서 그를 만나봐야겠군. 그러면 누구의 연금술이 최고인지 알게 될 것이다.', `MaleText_loc4`='唉！我记得当时昂舒克还微不足道，不敢配制他的第一份毒药。我量他不敢独自面对我。然后，我们将比比谁的炼金术才是终极的。', `MaleText_loc5`='哼!我還記得翁索克仍是隻小蟲的時候，害怕配製他的第一個毒劑。他如果敢單獨面對我，我們就可以知道誰的鍊金術才是最卓越的。', `MaleText_loc7`='¡Bah! Recuerdo cuando Un''sok era solo un zángano, con miedo a mezclar su primera toxina. Que se atreva a enfrentarse a mí cara a cara. Entonces veremos quién posee la alquimia suprema.' WHERE `ID`=65209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤오티엔에게 절해라!', `MaleText_loc4`='向韶天鞠躬行礼！', `MaleText_loc5`='臣服於嘯天之下!', `MaleText_loc7`='¡Inclínate ante el Shao-Tien!' WHERE `ID`=65210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 약하다!', `MaleText_loc4`='你太弱了！', `MaleText_loc5`='你太弱!', `MaleText_loc7`='¡Son débiles!' WHERE `ID`=65211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것.', `MaleText_loc4`='傻孩子。', `MaleText_loc5`='愚蠢的小孩。', `MaleText_loc7`='¡$gCrío estúpido:Cría estúpida;!' WHERE `ID`=65212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 있군! 어서 놈을 없애라, $p!', `MaleText_loc4`='他就在那！现在杀了他，$p！', `MaleText_loc5`='他在那裡!現在把他殺了，$p!', `MaleText_loc7`='¡Ahí está! ¡Mátenlo!' WHERE `ID`=65213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 또 안개 너머에서 온 이방인인가.', `MaleText_loc4`='啊，又一个来自迷雾之外的旅行者。', `MaleText_loc5`='啊，另一個迷霧彼端來的陌生人。', `MaleText_loc7`='Ah, otro forastero de más allá de la niebla.' WHERE `ID`=65214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만 년 전, 마지막 판다렌 황제가 내 조언을 구하러 왔었지. 그 역시 갈등에 빠져 있었어. 네 말이 맞는지 보자꾸나, 타란. 이 이방인이 영혼의 혼란을 어떻게 잠재우는지 보자.', `MaleText_loc4`='一万年前，末代熊猫人皇帝曾向我讨教治国之道。他也是一个充满矛盾的人。让我们看看你是否正确，踏岚。看看这个陌生人如何应对灵魂的骚动。', `MaleText_loc5`='一萬年前，末代熊貓人大帝前來尋求我的建言，當時的他內心中也同樣滿是衝突。塔蘭，我們就看看你是否正確吧，就看看這個陌生人如何面對靈魂的騷動。', `MaleText_loc7`='Hace diez mil años, el último emperador pandaren vino en busca de consejo. Él también se sentía invadido por el conflicto. Veamos si tienes razón, Taran. Descubramos cómo lidia este forastero con la inquietud del alma.' WHERE `ID`=65215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 저들은 이 땅을 뒤덮을 겁니다! 언제까지 지켜봐야만 한다는 겁니까?', `MaleText_loc4`='很快他们将霸占整个大陆！我们何以划清界限？', `MaleText_loc5`='他們很快就會占領整座大陸!我們還能退到哪裡?', `MaleText_loc7`='¡Pronto invadirán todo el continente! ¿Dónde ponemos el límite?' WHERE `ID`=65216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 숲에서 자네가 도움을 준답시고 거드는 걸 봤네. 이 호드니 얼라이언스니 하는 것들은... 도무지 자제심이라고는 없더군. 네놈들이 지나간 길에는 파괴와 고통뿐이지.', `MaleText_loc4`='我们在翡翠林亲眼目睹了你所谓的“帮助”。那些“部落”，还有你的“联盟”——你们连自身都无法掌控，你们真是悲哀。', `MaleText_loc5`='我們在翠玉林見識過你們是怎麼「幫忙」的。你們這些「部落」還有「聯盟」，根本控制不了自己的天性。你們只會製造悲劇。', `MaleText_loc7`='Hemos presenciado su "ayuda" en El Bosque de Jade. "Horda" y "Alianza"... No controlan su propia naturaleza. La desgracia los persigue.' WHERE `ID`=65217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎 꿇어라, 벌레 같은 놈.', `MaleText_loc4`='草民，跪下。', `MaleText_loc5`='跪下，蟲子。', `MaleText_loc7`='Arrodíllate, sabandija.' WHERE `ID`=65218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군.', `MaleText_loc4`='可怜。', `MaleText_loc5`='可悲。', `MaleText_loc7`='Patético.' WHERE `ID`=65219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와드리고 싶을 뿐이에요. 골짜기를 지키겠어요.', `MaleText_loc4`='我们是来提供援助的。我们能帮忙保护溪谷。', `MaleText_loc5`='我們是來幫忙的。我們可以幫忙保護恆春谷。', `MaleText_loc7`='Hemos venido a ofrecerles ayuda. Les ayudaremos a proteger el valle.' WHERE `ID`=65220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈을 잡아! 여자는 신경 쓰지 마라!', `MaleText_loc4`='快去阻止加丁！别管这个女亡灵了！', `MaleText_loc5`='阻止他!不要理她!', `MaleText_loc7`='¡Deténganlo! ¡Olvídense de ella!' WHERE `ID`=65221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<허가 복도 저쪽을 뚫어져라 바라봅니다.>', `MaleText_loc4`='<他专心地俯视大厅。>', `MaleText_loc5`='<他專注地低頭看著大廳。>', `MaleText_loc7`='<Zheng mira hacia delante, concentrado.>' WHERE `ID`=65222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s|1이;가; |cFFFF0000|Hspell:126299|h[영혼 방출]|h|r을 시전하기 시작합니다! 빨리 움직이십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s开始施放|cFFFF0000|Hspell:126299|h[灵魂释放]|h|r！快跑开！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s開始施放|cFFFF0000|Hspell:126299|h[靈魂釋放]|h|r!快點移動!', `MaleText_loc7`='|TInterfaceIconsability_warlock_baneofhavoc:20|t%s comienza a lanzar |cFFFF0000|Hspell:126299|h[Desatar almas]|h|r! ¡Moveos rápido!' WHERE `ID`=65223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어...', `MaleText_loc4`='这一刻终于到来了。', `MaleText_loc5`='終於。', `MaleText_loc7`='Por fin.' WHERE `ID`=65224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났군. 저주가 풀렸다. 고맙다, $p. 고맙다!', `MaleText_loc4`='结束了。诅咒被解除。谢谢你，$p。谢谢！', `MaleText_loc5`='結束了。詛咒被破除了。謝謝你，$p。謝謝你!', `MaleText_loc7`='Se acabó. La maldición se ha acabado. Gracias, $p. ¡Gracias!' WHERE `ID`=65225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고프다!', `MaleText_loc4`='我饿了！', `MaleText_loc5`='我感到飢餓!', `MaleText_loc7`='¡Me muero de hambre!' WHERE `ID`=65226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먹어야만 한다!', `MaleText_loc4`='我必须吃东西！', `MaleText_loc5`='我必須進食!', `MaleText_loc7`='¡Tengo que comer!' WHERE `ID`=65227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 황금 연꽃이 납신 건가...', `MaleText_loc4`='这么说，金莲教也来了……', `MaleText_loc5`='金蓮會還知道要來啊...', `MaleText_loc7`='Así que el Loto Dorado ha llegado...' WHERE `ID`=65228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 너무 늦었다. 비취 군대는 내 거야.', `MaleText_loc4`='你们太迟了。碧玉军团是我的了。', `MaleText_loc5`='你們真是有夠慢，翠玉軍團現在是我的了。', `MaleText_loc7`='Llegan demasiado tarde. El ejército de jade es mío.' WHERE `ID`=65229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그들과 함께, 나는 황금 연꽃을 처치하고 천둥왕의 이름으로 골짜기를 손에 넣을 것이다!', `MaleText_loc4`='而有了他们，我将以雷电之王的名义碾碎金莲教，夺回锦绣谷！', `MaleText_loc5`='有了他們，我便能擊敗金蓮會，以雷王之名奪回山谷!', `MaleText_loc7`='Con él aplastaré el Loto Dorado y tomaré el valle en nombre del Rey del Trueno.' WHERE `ID`=65230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 벌레들아!', `MaleText_loc4`='死吧，爬虫！', `MaleText_loc5`='死吧，弱者!', `MaleText_loc7`='¡Mueran, debiluchos!' WHERE `ID`=65231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 군대의 거대한 힘은 모두 내 손안에 있다!', `MaleText_loc4`='无穷无尽的碧玉军团归我掌握！', `MaleText_loc5`='我掌握了翠玉軍團的無窮力量!', `MaleText_loc7`='¡El poder eterno del ejército de jade me pertenece!' WHERE `ID`=65232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 도적 친구는 생각만큼 영리하지 못한 것 같군.', `MaleText_loc4`='你那潜行者朋友自以为身手矫健。', `MaleText_loc5`='你那盜賊朋友的身手並不如他所想的靈敏。', `MaleText_loc7`='Su amigo pícaro no es tan ágil como cree.' WHERE `ID`=65233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 조각상이 놈을 뭉개 버릴 것이다. 그 자리에는 가루가 된 시체만 남겠지.', `MaleText_loc4`='我的石雕将碾碎他的生命，只留下四分五裂的躯壳。', `MaleText_loc5`='我的雕像會毀滅他的生命，留下支離破碎的軀體。', `MaleText_loc7`='Mi estatua lo aplastará y no dejará más que un cadáver destrozado.' WHERE `ID`=65234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구를 죽게 놔 둬라...', `MaleText_loc4`='他被你送上了绝路……', `MaleText_loc5`='你丟下朋友不顧他的死活...', `MaleText_loc7`='Dejan morir a su amigo…' WHERE `ID`=65235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 훌륭하군... 죽을 게 뻔한 친구를 구하겠다니...', `MaleText_loc4`='多么高尚……来拯救一个必死的朋友……', `MaleText_loc5`='多高尚啊...想拯救朋友逃過死劫...', `MaleText_loc7`='Qué noble... rescatar a un amigo de una muerte segura...' WHERE `ID`=65236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 모두 헛수고일 뿐. 끌고 가라!', `MaleText_loc4`='……徒劳无功。抓住他们！', `MaleText_loc5`='...卻是白忙一場。帶走他們!', `MaleText_loc7`='... y todo para nada. ¡Atrápenlos!' WHERE `ID`=65237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항해 봐야 소용없다.', `MaleText_loc4`='你的挣扎毫无意义。', `MaleText_loc5`='你的掙扎只是白費力氣。', `MaleText_loc7`='Sus esfuerzos son inútiles.' WHERE `ID`=65238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 이 골짜기에 숨겨진 강력한 비밀을 몰라. 내가 가져가마. 그리고 너희 족속을 모조리 쓸어 버리겠다.', `MaleText_loc4`='你对这座山谷蕴藏的强大秘密一无所知。我将得到它们，消灭你们所有人。', `MaleText_loc5`='你對這個山谷所隱藏的重大秘密一無所知。我要帶走他們，然後摧毀你們所有的族人。', `MaleText_loc7`='No conocen los poderosos secretos que se ocultan en este valle. Me haré con ellos y los destruiré a todos.' WHERE `ID`=65239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 죄수들은 우리에 던져 버려라. 나중에 처리하지.', `MaleText_loc4`='将这些俘虏投进囚笼。让下面的人看好他们。', `MaleText_loc5`='把這些俘虜丟進籠子裡，讓這些人自生自滅。', `MaleText_loc7`='Enjaulen a estos prisioneros. Que los hombres se diviertan con ellos.' WHERE `ID`=65240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 새로운 모험이 시작되려고 하는군.$B$B내 눈에 보이는 저게 빛인가?', `MaleText_loc4`='我的下一个伟大的冒险即将开始。$B$B我看到的那是一道圣光吗？', `MaleText_loc5`='我下一次偉大的冒險就要開始了。$B$B我看到的那是一道光嗎?', `MaleText_loc7`='Mi siguiente gran aventura está a punto de comenzar. $B$B¿Eso que veo es una luz?' WHERE `ID`=65241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 전투 투구...', `MaleText_loc4`='雷电之王的战盔……', `MaleText_loc5`='雷王的戰盔啊...', `MaleText_loc7`='El yelmo de combate del Rey del Trueno...' WHERE `ID`=65242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병들은 쓸모없는 것 같군. 내 직접 너희를 상대하겠다.', `MaleText_loc4`='看来我的守卫都是废物。我还得亲自来对付你们。', `MaleText_loc5`='看來我的守衛不管用，我得親自來料理你。', `MaleText_loc7`='Parece que mis guardias son unos inútiles. Tendré que encargarme yo de ustedes.' WHERE `ID`=65243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 가둬 두는 것으론 끝나지 않을 것이다. 몸에서 사지를 절단해 주마!', `MaleText_loc4`='这次就不用囚笼了，我要直接把你们的四肢扯下来！', `MaleText_loc5`='這次可沒有籠子了，我要把你大卸八塊!', `MaleText_loc7`='Esta vez no habrá jaulas. ¡Les arrancaré las extremidades una a una!' WHERE `ID`=65244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘 앞에 떨어라!', `MaleText_loc4`='屈服于我的力量！', `MaleText_loc5`='在我的力量前顫抖吧!', `MaleText_loc7`='¡Tiemblen ante mi poder!' WHERE `ID`=65245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸에서 생명을 앗아가 주지!', `MaleText_loc4`='我要熄灭你的生命之火！', `MaleText_loc5`='我會撲滅你體內的生命之火!', `MaleText_loc7`='¡Extraeré la vida de tu cuerpo!' WHERE `ID`=65246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 뽑아 내겠다!', `MaleText_loc4`='我要撕裂你的灵魂！', `MaleText_loc5`='然後挖出你的靈魂!', `MaleText_loc7`='¡Os arrancaré el alma!' WHERE `ID`=65247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭력... 보셨습니까? 저들에겐 그것뿐입니다.', `MaleText_loc4`='暴力。看见没有？充满了他们的身体。', `MaleText_loc5`='瞧見了沒?暴力，這些人內心充滿了暴力。', `MaleText_loc7`='Violencia. ¿Lo ven? Los domina por completo.' WHERE `ID`=65248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각보단 강하군. 하지만 투구는 여전히 내 거야...', `MaleText_loc4`='你没我想得那么弱，但战盔还是我的……', `MaleText_loc5`='你沒有我想的那麼弱，但是戰盔仍是我的...', `MaleText_loc7`='No sois tan débiles como pensaba, pero el yelmo es mío.' WHERE `ID`=65249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아악! 마법사, 다음번에 만나면 살아 나가지 못할 것이다.', `MaleText_loc4`='啊啊！！法师，我们下次见面时，我一定要让你人头落地。', `MaleText_loc5`='哇啊啊啊啊!法師，下回相遇時，我會讓你身首異處。', `MaleText_loc7`='¡Aaaaarrrgh! Mago, la próxima vez que te vea te arrancaré la cabeza.' WHERE `ID`=65250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 우리는 투사예요. 거친 땅에서 왔기 때문이죠. 우린 악마와, 죽음과 싸웠고, 세계의 종말과도 맞서야 했어요!', `MaleText_loc4`='对……我们是战士。可我们来自饱经肆虐的土地。我们击退过恶魔，也击退过死亡，甚至阻止过世界末日的到来！', `MaleText_loc5`='是的。我們是戰士。但是我們來自動盪的地方。我們擊退過惡魔，擊退過死亡，甚至阻止過世界末日!', `MaleText_loc7`='Sí, somos luchadores, pero provenimos de una tierra violenta. Hemos luchado contra demonios, contra la muerte, ¡incluso contra el fin del mundo!' WHERE `ID`=65251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 날 방해하지? 그 겁쟁이 낮짝을 내밀고 내 앞에 무릎 꿇어라!', `MaleText_loc4`='是谁竟敢打扰我？跪下！让我看看你那懦弱的脸！', `MaleText_loc5`='誰膽敢打擾我?現出你懦弱的面孔，跪在我的面前!', `MaleText_loc7`='¿Quién osa molestarme? Den la cara, cobardes, y arrodíllense ante mí.' WHERE `ID`=65252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 준비나 해라, 이 악당!', `MaleText_loc4`='准备受死吧，恶棍！', `MaleText_loc5`='受死吧，惡人!', `MaleText_loc7`='¡PREPÁRATE PARA MORIR!' WHERE `ID`=65253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음하하하! 불쌍한 생명체들!', `MaleText_loc4`='啊哈哈哈！真是可怜的生物！', `MaleText_loc5`='啊哈哈哈!真是個可憐的東西!', `MaleText_loc7`='¡Ja, ja, ja! ¡Qué criatura tan patética!' WHERE `ID`=65254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 내가 상대할 가치도 없다. 너! 이 하찮은 벼룩들을 밟아 버려라!', `MaleText_loc4`='你不配让我动手。达苟！碾碎这只微不足道的跳蚤！', `MaleText_loc5`='你對我而言沒有價值。達郭!過來打扁這卑賤的小蟲!', `MaleText_loc7`='No estás a mi altura. ¡Tú! Ven a aplastar a esta pulga insignificante.' WHERE `ID`=65255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 창으로 꿰뚫어 주마!', `MaleText_loc4`='用我的长矛终结你！', `MaleText_loc5`='我的長矛會解決你!', `MaleText_loc7`='¡Mi lanza los atravesará!' WHERE `ID`=65256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마주한 네 절망에 고개를 떨궈라!', `MaleText_loc4`='颤抖着迎接你的末日吧！', `MaleText_loc5`='恐懼於你自身的毀滅吧!', `MaleText_loc7`='¡Tiemblen ante la visión de su propia muerte!' WHERE `ID`=65257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실이네. 이들은 강하네. 우리가 배울 게 많아.', `MaleText_loc4`='是的。他们很强，有很多值得我们学习的地方。', `MaleText_loc5`='的確。他們很強壯。他們可以教導我們很多事情。', `MaleText_loc7`='Es cierto. Son fuertes. Tienen mucho que enseñarnos.' WHERE `ID`=65258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 전쟁군주의 위력을 보여주마!', `MaleText_loc4`='我要让你瞧瞧督军的真正力量！', `MaleText_loc5`='我會讓你見識真正的督軍擁有怎樣的力量!', `MaleText_loc7`='¡Les mostraré la fuerza de un verdadero señor de la guerra!' WHERE `ID`=65259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망칠 곳은 없다, 벌레들아!', `MaleText_loc4`='你无路可走了，懦夫！', `MaleText_loc5`='弱者，你無處可逃了!', `MaleText_loc7`='¡No tienes escapatoria, gusano!' WHERE `ID`=65260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 것. 너희가 모구 제국의 힘을 막을 수 있을 것 같나?', `MaleText_loc4`='蠢货。你竟然妄想与魔古帝国展开全面对抗？', `MaleText_loc5`='蠢蛋。你竟然想阻擋魔古帝國的主力部隊嗎?', `MaleText_loc7`='¡Necio! ¿Crees que puedes acabar con el poder del imperio mogu?' WHERE `ID`=65261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 고통스럽게 죽여 주마, 벌레들아.', `MaleText_loc4`='你休想痛痛快快地死，懦夫。', `MaleText_loc5`='我不會讓你死得很痛快，弱者。', `MaleText_loc7`='No te concederé una muerte rápida, insecto.' WHERE `ID`=65262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 약하다!', `MaleText_loc4`='你太没用了！', `MaleText_loc5`='你很弱!', `MaleText_loc7`='¡Son débiles!' WHERE `ID`=65263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이대로 뭉개 주마!', `MaleText_loc4`='我要粉碎你！', `MaleText_loc5`='我會把你碾碎!', `MaleText_loc7`='¡Los aplastaré!' WHERE `ID`=65264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 가져 마땅한 것을 되찾겠다!', `MaleText_loc4`='我们要夺回本该属于我们的一切！', `MaleText_loc5`='我們將取回屬於我們的東西!', `MaleText_loc7`='¡Recuperaremos lo que nos pertenece por derecho!' WHERE `ID`=65265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 자신의 어리석음을 탓해라!', `MaleText_loc4`='愚不可及，自作自受！', `MaleText_loc5`='恐懼於你自身的愚蠢吧!', `MaleText_loc7`='¡Contemplen su propia locura!' WHERE `ID`=65266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 새로 태어났다!', `MaleText_loc4`='我获得了新生！', `MaleText_loc5`='我重新復生了!', `MaleText_loc7`='¡He nacido de nuevo!' WHERE `ID`=65267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 혈관의 피가 독으로 가득 찼다. 다시는 독을 두려워하지 않으리라. 이제 나는 진정한 완전체다!', `MaleText_loc4`='我体内的血液里流满了毒素。我再也不怕任何毒药了。我可真是自己的杰作！', `MaleText_loc5`='我體內的血液現在充滿了毒性。我將不再畏懼任何的劇毒。我實在是我自己的最高傑作啊!', `MaleText_loc7`='La sangre de mis venas está ahora repleta de toxinas. No volveré a temer a ningún veneno. ¡Sin duda soy mi propia obra maestra!' WHERE `ID`=65268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 독을 좀 맛보겠나? 한 방울이라도 마셔보는 게 어떤가?', `MaleText_loc4`='你不想尝尝毒药吗，唤醒者？一滴也不要？', `MaleText_loc5`='你不想嚐嚐看劇毒嗎，喚醒者?連一滴也不想?', `MaleText_loc7`='¿No quieres probar el veneno, heraldo? ¿Ni siquiera una gota?' WHERE `ID`=65269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이제 사마귀가 아니다. 나는... 그것보다 더한 존재다.', `MaleText_loc4`='我再也不是螳螂妖了。我变得……更加强大。', `MaleText_loc5`='我不再是個螳螂人。我已經變得...更強大。', `MaleText_loc7`='Ya no soy un mántide. Soy algo... más.' WHERE `ID`=65270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볶음의 길을 배우고 싶습니다.', `MaleText_loc4`='我想要学习烹炒之道。', `MaleText_loc5`='我想要接受快炒之道的訓練。', `MaleText_loc7`='Necesito instrucción en el arte del wok.', `FemaleText_loc1`='볶음의 길을 배우고 싶어요.', `FemaleText_loc4`='我想要学习烹炒之道。', `FemaleText_loc5`='我想要接受快炒之道的訓練。', `FemaleText_loc7`='Necesito instrucción en el arte del wok.' WHERE `ID`=65271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='양조의 길을 배우고 싶습니다.', `MaleText_loc4`='我想要学习酿造之道。', `MaleText_loc5`='我想要接受釀酒之道的訓練。', `MaleText_loc7`='Necesito instrucción en el arte de la cerveza.', `FemaleText_loc1`='양조의 길을 배우고 싶어요.', `FemaleText_loc4`='我想要学习酿造之道。', `FemaleText_loc5`='我想要接受釀酒之道的訓練。', `FemaleText_loc7`='Necesito instrucción en el arte de la cerveza.' WHERE `ID`=65272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집과 가족을 지키기 위한 것처럼 정당한 이유의 싸움은 고귀하지. 하지만 복수는? 분노는? 그런 감정들이 이 자에겐 강하게 흐르고 있다.', `MaleText_loc4`='我们赞同为正义事业而战是光荣的：如保卫家园或家人。可复仇呢？愤怒呢？我能在此人内心深处感觉到这些情绪。', `MaleText_loc5`='我們同意，保衛家園和親友，為了這種正義而戰是高貴的行為。但是復仇呢?憤怒呢?我感覺到這些情緒深植在他的心裡。', `MaleText_loc7`='Estamos de acuerdo en que es noble luchar por una causa justa, como defender el hogar o la familia. ¿Pero qué hay de la venganza? ¿Y de la ira? Siento que están arraigadas en esta criatura.' WHERE `ID`=65273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 매일 새로운 기록과 오래된 기록을 정리해요. 고대의 지혜가 담긴 두루마리일 때도 있고, 잉크장인이 그린 영원꽃 골짜기의 그림일 때도 있지요.$b$b저희가 전승을 보존하는 건, 후세가 우리의 성공... 그리고 실패로부터 배울 수 있게 하기 위해서죠.', `FemaleText_loc4`='我每天都存入各种新旧资料。有时是古老的智慧书卷，有时则是某位墨水大师创作的山谷写生图。$b$b我们保存着这些知识，以便让后人能从我们的成功……和失败中借鉴一二。', `FemaleText_loc5`='每天，我都歸檔一點新的東西和一點舊的東西。有時候是古老的智慧卷軸。有時候是一名水墨大師關於山谷的畫。$b$b我們保存這些知識，讓世世代代的子孫都能學習我們的成功...或者失敗之處。', `FemaleText_loc7`='Cada día archivo algo nuevo y algo viejo. A veces es un antiguo pergamino de sabiduría. Otras, una pintura del Valle de algún maestro calígrafo.$b$bPreservamos nuestra tradición para que las generaciones futuras aprendan de nuestros éxitos... y nuestros errores.' WHERE `ID`=65274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 안개를 피하려면 단 위로 올라가십시오!', `MaleText_loc4`='站到高处，避开暗影之雾！', `MaleText_loc5`='站在高處來躲避暗影迷霧!', `MaleText_loc7`='¡Súbete a una superficie elevada para evitar la Niebla de las Sombras!', `FemaleText_loc1`='어둠 안개를 피하려면 단 위로 올라가십시오!', `FemaleText_loc4`='站到高处，避开暗影之雾！', `FemaleText_loc5`='站在高處來躲避暗影迷霧!', `FemaleText_loc7`='¡Súbete a una superficie elevada para evitar la Niebla de las Sombras!' WHERE `ID`=65275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s|1이;가; |cFFFF0000|Hspell:126384|h[빨간색 화강암]|h|r으로 변합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s变成了|cFFFF0000|Hspell:126384|h[红色花岗岩]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_bloodstone_03:20|t%s轉變成了|cFFFF0000|Hspell:126384|h[紅崗岩]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_bloodstone_03:20|t%s se transforma en |cFFFF0000|Hspell:126384|h[granito rojo]|h|r.' WHERE `ID`=65276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s|1이;가; |cFFFF0000|Hspell:126401|h[녹색 화강암]|h|r으로 변합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s变成了|cFFFF0000|Hspell:126401|h[绿色花岗岩]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_gem_stone_01:20|t%s轉變成了|cFFFF0000|Hspell:126401|h[綠崗岩]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_gem_stone_01:20|t%s se transforma en |cFFFF0000|Hspell:126401|h[granito verde]|h|r.' WHERE `ID`=65277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_ore_cobalt:20|t%s|1이;가; |cFFFF0000|Hspell:126405|h[파란색 화강암]|h|r으로 변합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_ore_cobalt:20|t%s变成了|cFFFF0000|Hspell:126405|h[蓝色花岗岩]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_ore_cobalt:20|t%s轉變成了|cFFFF0000|Hspell:126405|h[藍崗岩]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_ore_cobalt:20|t%s se transforma en |cFFFF0000|Hspell:126405|h[granito azul]|h|r.' WHERE `ID`=65278;
