UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맛있는 냄새가 나지 않습니까?', `MaleText_loc4`='闻上去香极了，是吧？', `MaleText_loc5`='聞起來很美味，不是嗎?', `MaleText_loc7`='Huele de maravilla, ¿verdad?', `FemaleText_loc1`='맛있는 냄새가 나지 않나요?', `FemaleText_loc4`='闻上去香极了，是吧？', `FemaleText_loc5`='聞起來很美味，不是嗎?', `FemaleText_loc7`='Huele de maravilla, ¿verdad?' WHERE `ID`=65284;
