UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부엌에서 사용할 재료와 용품이 필요합니다.', `MaleText_loc4`='我需要给厨房补充些食材和炊具。', `MaleText_loc5`='我的廚房需要材料和設備。', `MaleText_loc7`='Necesito ingredientes y equipamiento para mi cocina.', `FemaleText_loc1`='부엌에서 사용할 재료와 용품이 필요해요.', `FemaleText_loc4`='我需要给厨房补充些食材和炊具。', `FemaleText_loc5`='我的廚房需要材料和設備。', `FemaleText_loc7`='Necesito ingredientes y equipamiento para mi cocina.' WHERE `ID`=65288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새벽이 밝아올 때, 망치는 떨어질 걸세.', `MaleText_loc4`='在黎明破晓时分，重锤将要砸落。', `MaleText_loc5`='當曙光升起，錘子當落下。', `MaleText_loc7`='Cuando se alza el amanecer, el martillo debe descansar.' WHERE `ID`=65289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 삶 속에서 가장 가장 좋은 게 뭐냐고?

형제와 노래, 맥주지!', `MaleText_loc4`='生命中什么最美好？

当然是小曲和美酒啊，兄弟们！', `MaleText_loc5`='生活中最棒的是什麼?

兄弟朋友、歌謠和啤酒!', `MaleText_loc7`='¿Qué es lo mejor de la vida?

¡Los hermanos, las baladas y la cerveza!' WHERE `ID`=65290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 맥주처럼 짜릿한 여자가 좋더군.', `MaleText_loc4`='我喜欢女人就像我喜欢啤酒——丰满而醇厚。', `MaleText_loc5`='我喜歡女人就像我喜歡我的啤酒一樣飽滿。', `MaleText_loc7`='Me gusta que las mujeres sean como las cervezas: con mucho cuerpo.' WHERE `ID`=65291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사랑밖에 난 모르니까, 아마도 내일은 행복할 걸세.', `MaleText_loc4`='我为爱甘愿付出一切。可我不会这么做。至少，现在不行。', `MaleText_loc5`='我會為了愛情做任何事，但我還不會那樣做。至少，不是馬上。', `MaleText_loc7`='Haría lo que fuese por amor. Pero no haré eso. Al menos ahora no.' WHERE `ID`=65292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 아이들은 정말 골칫덩이예요.', `FemaleText_loc4`='这群小子可真麻烦。', `FemaleText_loc5`='這些孩子還真難控制。', `FemaleText_loc7`='Estos chicos son unos trastos.' WHERE `ID`=65293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이들에게 이곳으로 소풍을 데려오겠다고 약속했었는데, 여긴 좀 위험한 곳이네요. 전에는 당신 같은 이방인들 사이에서 진짜 전투가 벌어졌다고 들었어요.$b$b그리고... 거북이에서 온 이도 있다고...$b$b전 그 커다란 거북이가 전설 속에나 나오는 거라고 생각했었는데...', `FemaleText_loc4`='我答应带他们在这儿野餐，可这里太危险了。就在几天前，我听说有几个像你一样的陌生人打了起来。$b$b还有个从……龟背上来的人。$b$b我一直以为那海龟只是个传说。', `FemaleText_loc5`='我答應這些孩子來這上面野餐，但這裡很危險。有一天，我聽見像你這樣的陌生人在這裡動刀動槍。$b$b還有從...烏龜上來到這裡的人。$b$b我一直以為烏龜只是傳說。', `FemaleText_loc7`='Les prometí a los chicos un picnic aquí, pero es un sitio peligroso. El otro día escuché que hubo una pelea entre forasteros como tú.$b$bY alguien de... la tortuga.$b$bSiempre pensé que la tortuga era una leyenda.' WHERE `ID`=65294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서 육식 동물들과 문제가 벌어지는 일은 별로 없어요. 비가 올 때는 사우록이 나타나기도 하는데, 번개가 치고 폭풍이 몰려들 때만 그러거든요.', `FemaleText_loc4`='我们这里并不常遭遇掠食者。有时，如果下雨的话，蜥蜴人会出现。可他们只在电闪雷鸣的暴风雨来袭时才会来。', `FemaleText_loc5`='我們這裡不常有掠食者的麻煩。下雨時，薩烏洛克或許會跑出來，但只有在下雷雨的時候才會。', `FemaleText_loc7`='No solemos tener problemas con los depredadores por aquí. Algunas veces, cuando llueve, los saurok salen. Pero eso solo es cuando hay una tormenta con relámpagos.' WHERE `ID`=65295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마아아아아! 형이 자꾸 찔러요!', `MaleText_loc4`='妈妈！刘总是找我麻烦！', `MaleText_loc5`='媽媽!小劉一直戳我啦!', `MaleText_loc7`='¡Mamá! ¡Liu no deja de pegarme!' WHERE `ID`=65296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형이 제 진위 장신구를 뺏어 갔어요!', `MaleText_loc4`='刘抢走了我的锦鱼人饰品！', `MaleText_loc5`='小劉把我的錦魚人飾品拿走了啦!', `MaleText_loc7`='¡Liu me ha robado mi baratija jinyu!' WHERE `ID`=65297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형이 제 발을 밟았어요!', `MaleText_loc4`='刘刚才踩了我一脚！', `MaleText_loc5`='小劉踩到我的腳了啦!', `MaleText_loc7`='¡Liu me ha pisado el pie!' WHERE `ID`=65298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마! 형이 자꾸 호젠처럼 굴어요!', `MaleText_loc4`='妈妈！刘总是像个猢狲一样！', `MaleText_loc5`='媽媽!小劉一直像個猴人亂鬧啦!', `MaleText_loc7`='¡Mamá! ¡Liu no deja de portarse como un hozen!' WHERE `ID`=65299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마아아아! 형이 때렸어요!', `MaleText_loc4`='妈妈！刘打了我一拳！', `MaleText_loc5`='媽媽!小劉打我啦!', `MaleText_loc7`='¡Mamá! ¡Liu me ha dado un puñetazo!' WHERE `ID`=65300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 언제!', `MaleText_loc4`='不，我没有！', `MaleText_loc5`='我才沒有!', `MaleText_loc7`='¡No, no es verdad!' WHERE `ID`=65301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쟤가 먼저 했다고요!', `MaleText_loc4`='是他先惹我的！', `MaleText_loc5`='他先開始的!', `MaleText_loc7`='¡Él empezó!' WHERE `ID`=65302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 하라고 했잖아!', `MaleText_loc4`='是你让我这么做的！', `MaleText_loc5`='是你要我做的!', `MaleText_loc7`='¡Tú me obligaste!' WHERE `ID`=65303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼!', `MaleText_loc4`='不是！', `MaleText_loc5`='不!要!', `MaleText_loc7`='¡Nooo! ¡Uhhh!' WHERE `ID`=65304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만해. 둘 다 꼭 호젠처럼 굴고 있잖니!', `FemaleText_loc4`='够了。你们俩简直是一对猢狲！', `FemaleText_loc5`='夠了。你們兩個簡直像兩隻猴人一樣!', `FemaleText_loc7`='¡Basta! ¡Os estáis comportando como un par de hozen!' WHERE `ID`=65305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 그만두지 않으면 짐 싸서 집에 갈 거야. 정말 그러고 싶니?', `FemaleText_loc4`='要是你们不听话，我就马上结束野餐，带你们回家。你们愿意这样吗？', `FemaleText_loc5`='如果你們不乖一點，我們就不要野餐，馬上回家了。這就是你們要的嗎?', `FemaleText_loc7`='Si no os comportáis como es debido, acabo con el picnic y nos vamos a casa. ¿Es eso lo que queréis?' WHERE `ID`=65306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티, 형을 자꾸 고자질하면 못써. 리우, 동생이 고자질할 거리를 자꾸 만들지 말렴.', `FemaleText_loc4`='泰，别说你哥哥坏话了。刘，你也别给你弟弟说坏话的理由。', `FemaleText_loc5`='阿泰，不要再告你弟弟的狀了。小劉，不要給你哥哥告狀的理由。', `FemaleText_loc7`='Ty, deja de chivarte de tu hermano. Liu, no des razones a tu hermano para chivarse.' WHERE `ID`=65307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만해. 둘 다. 똑똑한 애들이 왜 그러니? 진위처럼 현명하게 행동하고 사이 좋게 지내지 못하겠니? 꼭 호젠처럼 못되게 굴어야겠어?', `FemaleText_loc4`='你们两个都给我住手。别弄得自己傻乎乎的。你们就不能像聪明的锦鱼人一样好好相处吗？还是说，你们就乐意毛毛躁躁地像个猢狲？', `FemaleText_loc5`='夠了，你們兩個。你們已經懂事了，可以學學錦魚人的智慧好好相處嗎?還是你們想繼續表現得跟頑劣的猴人一樣?', `FemaleText_loc7`='Basta, los dos. Sois más listos que esto. ¿Podéis ser listos como un jinyu y llevaros bien? ¿O os vais a seguir comportando mal como un hozen?' WHERE `ID`=65308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하게.', `MaleText_loc4`='发起挑战吧。', `MaleText_loc5`='提出你的挑戰。', `MaleText_loc7`='Presenta tu desafío.' WHERE `ID`=65309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 정신이 혼란스러울 수도 있다, 깨우는 자여. 너의 눈이 진실을 보는 첫 순간은 항상 어려운 법이지.', `MaleText_loc4`='这也许会让你茫然迷失，唤醒者。第一次亲眼看见，总是很困难的。', `MaleText_loc5`='這可能會讓你暫時昏眩，喚醒者。你的眼睛第一次真正看見東西時總是會有些困難。', `MaleText_loc7`='Esto puede desorientarte de forma momentánea, heraldo. Siempre es difícil la primera vez que tus ojos ven de verdad.' WHERE `ID`=65310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아... 강철의 양조사라니.', `MaleText_loc4`='非常好……金铁酒仙。', `MaleText_loc5`='很好...金屬釀酒大師。', `MaleText_loc7`='Muy bien... Maestro cervecero del metal.' WHERE `ID`=65311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 폭풍의 아들 딸이네!', `MaleText_loc4`='我们都是暴风雨的儿女！', `MaleText_loc5`='我們全都是風暴的兒女!', `MaleText_loc7`='¡Todos somos hijos de la tormenta!' WHERE `ID`=65312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 트롤이 옛날이야기에나 나오는 존재인 줄 알았어요.', `FemaleText_loc4`='我一直以为巨魔只在古老的故事中存在。', `FemaleText_loc5`='我一直以為食人妖只是老故事裡的素材。', `FemaleText_loc7`='Siempre creí que los trols solo existían en cuentos antiguos.' WHERE `ID`=65313;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, $p! 당신의 용기 덕분에 우리가 싸움을 버텨 낼 수 있었어요.', `FemaleText_loc4`='谢谢你，$p！是你的勇气激励着我们战斗。', `FemaleText_loc5`='謝謝你，$p!你的勇氣讓我們撐過這場戰役。', `FemaleText_loc7`='¡Gracias, $p! Tu valor ha conseguido que ganemos la batalla.' WHERE `ID`=65314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘든 싸움이었어요. 지금까지 우리에게 골치라고 해 봐야, 사우록 침략자나 배고픈 호젠 정도였지요.$b$b이 트롤들은... 싸우는 태세가 달라요.', `FemaleText_loc4`='真是一场艰苦的战斗。我们从前只需要提防蜥蜴人突袭者和偶尔前来捣乱的饥饿猢狲。$b$b那些巨魔……他们作战的方式很不一样。', `FemaleText_loc5`='這真是一場硬仗。我們過去得擔心的不過是薩烏洛克盜匪，或少數飢餓的猴人。$b$b那些食人妖...他們戰鬥的方式截然不同。', `FemaleText_loc7`='Ha sido un combate arduo. Por aquí solo estamos acostumbrados a enfrentarnos con asaltantes saurok y algún que otro hozen enfadado.$b$bEsos trols... luchan distinto.' WHERE `ID`=65315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롤들이 뭘 찾으러 온 거였죠?', `FemaleText_loc4`='那些巨魔在找什么？', `FemaleText_loc5`='那些食人妖想要的是什麼?', `FemaleText_loc7`='¿Qué querían los trols?' WHERE `ID`=65316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 알게 될 거다. 우리 중에 배신자가 있다.', `MaleText_loc4`='现在你会看见。叛徒就混在我们自己人里。', `MaleText_loc5`='現在你將會發現。叛徒就藏在我們之中。', `MaleText_loc7`='Ahora verás. Hay traidores ocultos entre nuestras filas.' WHERE `ID`=65317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시한 전투였습니다.', `MaleText_loc4`='真是可怕的战斗。', `MaleText_loc5`='那真是場可怕的戰鬥。', `MaleText_loc7`='Ha sido una batalla terrible.' WHERE `ID`=65318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린 시절 수도원에서 방어 수업을 받을 때 졸았던 게 후회되는군요.', `MaleText_loc4`='我现在真希望自己年少在禅院里受训时，没在防御课上打瞌睡。', `MaleText_loc5`='現在我好希望我還小的時候，在僧院上那些防禦課程的時候沒有打瞌睡。', `MaleText_loc7`='Ahora desearía no haberme dormido durante las clases de defensa en el monasterio, cuando era cachorro.' WHERE `ID`=65319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤들이 대체 뭘 찾으러 온 걸까요? 여긴 그저 소박한 어촌일 뿐인데 말입니다.', `MaleText_loc4`='那些巨魔们想干什么？这只是个简单的小渔村。', `MaleText_loc5`='那些食人妖在找什麼?我們只不過是個平凡的漁村。', `MaleText_loc7`='¿Qué querían los trols? No somos más que una aldea pesquera.' WHERE `ID`=65320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤이라니... 진짜 트롤이었습니다! 이야기로는 들었지만, 실제로 보게 될 줄이야. 게다가 이야기와 똑같이 사납더군요.', `MaleText_loc4`='巨魔。那些是真正的巨魔！我们听过他们的传说。可现在亲眼看见了。他们跟故事里说的一样凶残。', `MaleText_loc5`='食人妖。那些是不折不扣的食人妖!我們曾經在故事中聽說過他們，但從沒面對面地見到他們。他們就和故事中描述的一般兇猛。', `MaleText_loc7`='Trols. ¡Eran trols de verdad! Nos habían contado historias sobre ellos. Pero verlos en persona... Y son tan feroces como decían los cuentos.' WHERE `ID`=65321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 분노는 우리의 일부예요. 하지만 통제할 수 있어요. 오크는 한때 분노에 이끌리고 피에 굶주린 채 살았어요. 하지만 결국엔 이겨냈죠.', `MaleText_loc4`='没错，愤怒在我们周身流淌。可我们懂得控制。兽人曾被愤怒驱策——终日活在对鲜血的渴望中——但还是战胜了它。', `MaleText_loc5`='我們都懷有憤怒，沒錯。但是我們懂得控制。獸人曾經被憤怒驅使...終日活在對鮮血的渴求中...但他們戰勝了它。', `MaleText_loc7`='La ira forma parte de todos nosotros, es verdad. Pero valoramos el control. Antes, los orcos obedecían solo a la ira; vivían con una sed de sangre perpetua, pero la superaron.' WHERE `ID`=65322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희들은 서로 이기려고 날뛸 뿐이야!', `MaleText_loc4`='你们想战胜的，只是彼此！', `MaleText_loc5`='你們只想著征服彼此!', `MaleText_loc7`='¡Solo quieren conquistarse mutuamente!' WHERE `ID`=65323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노가 없는 삶은 죽음과 같네. 오히려 우리가 이겨내야 할 숙제지. 우린 분노를 이김으로써, 큰 힘을 얻게 된다네.', `MaleText_loc4`='只有死人才不会愤怒。但我们要学会克制。击败心中的愤怒，才能获得力量。', `MaleText_loc5`='完全不生氣就算不上是活著了。我們要克服這點。擊敗內心的怒氣，我們就能獲得更大的力量。', `MaleText_loc7`='Vivir sin ira no es vivir. Es nuestro deber superarla. Cuando la derrotamos, obtenemos una gran fuerza.' WHERE `ID`=65324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t라오페의 영혼이 |cFFFF0000|Hspell:126471|h[약자 억압]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t牢非的灵魂施放了|cFFFF0000|Hspell:126471|h[倚强凌弱]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t老菲之靈施放|cFFFF0000|Hspell:126471|h[壓制弱者]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_battleshout.blp:20|tEl espíritu de Lao-Fe lanza |cFFFF0000|Hspell:126471|h[Oprimir a los débiles]|h|r.' WHERE `ID`=65325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 말했다, 즈. 안개 너머에서 온 이방인들에게 열정이 부족하진 않지. 허나 통제할 수 있을지는 봐야겠다. 분노 너머로 증오가 있다. 이는 모든 불행의 원천이지. 이건 뭐지? 네 증오에서 얼굴이 보이는군!', `MaleText_loc4`='说得好，智。来自迷雾之外的陌生人们虽然不缺乏热情，但我们得看看他们的自制力。愤怒出自仇恨，仇恨乃万苦之源。看，这就是你心中仇恨的模样！', `MaleText_loc5`='值，說得好。這些穿越迷霧進來的外地人，他們的情感的確豐富，不過可以觀察一下他們是否真能控制。除了怒氣，還有憎恨，這是所有悲劇的源頭。什麼?你的憎恨居然有個具體的面貌!', `MaleText_loc7`='Bien dicho, Zhi. Los forasteros de más allá de la niebla rebosan de emociones; veamos si pueden controlarlas. Tras la ira se oculta el odio, el origen de todo sufrimiento. ¿Cómo? ¡Tu odio tiene rostro!' WHERE `ID`=65326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보셨습니까? 이들이 서로 얼마나 증오하는지 보십시오! 전장에 그 증오를 품고 나가서 무덤까지 가져갈 겁니다!', `MaleText_loc4`='看见没有？这些外来者如此憎恨彼此！他们身披仇恨上阵，再把仇恨带进坟墓！', `MaleText_loc5`='瞧?這些外來者是如何痛恨彼此!他們帶著仇恨戰鬥，然後帶著它同歸於盡!', `MaleText_loc7`='¡Miren! ¡Vean cuánto se odian los forasteros! ¡Marchan con su odio hacia la batalla y se lo llevan a la tumba!' WHERE `ID`=65327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그렇지 않아요. 우리에겐 증오가 전부가 아니라고요!', `MaleText_loc4`='不，那不是真的——对我们来说绝对不止这样！', `MaleText_loc5`='不，那不是真的...我們不只是這樣而已!', `MaleText_loc7`='¡No! No puede ser verdad. ¡Somos capaces de mucho más!' WHERE `ID`=65328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭지 않나. 이들은 우리 땅에 많은 것들을 가져왔지만, 전쟁의 그림자도 함께 몰고 왔어.', `MaleText_loc4`='真有趣。他们带来了很多东西，但也带来了战争的阴影。', `MaleText_loc5`='有意思，他們帶來了許多事物進入我們的土地，同時也帶來戰爭的陰影。', `MaleText_loc7`='Es curioso. Aportan mucho a nuestra tierra, pero también traen la sombra de la guerra.' WHERE `ID`=65329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평화가 찾아올 거예요. 맹세할게요. 낡은 증오는 사라질 거고요. 믿어 주세요.', `MaleText_loc4`='和平终将来临。我发誓。往昔的仇恨将不复存在。你要相信我。', `MaleText_loc5`='和平終將到來。我發誓，昔日的仇恨會消失。你要相信我。', `MaleText_loc7`='La paz llegará. Lo juro. El odio del pasado desaparecerá. Tienes que creerme.' WHERE `ID`=65330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_searingarrow.blp:20|t후오슈앙이 |cFFFF0000|Hspell:126304|h[불타오르는 화살]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_searingarrow.blp:20|t火霜施放了|cFFFF0000|Hspell:126304|h[烈焰之箭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_searingarrow.blp:20|t霍雙施放|cFFFF0000|Hspell:126304|h[燃焰之箭]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_searingarrow.blp:20|t¡Huo-Shuang lanza |cFFFF0000|Hspell:126304|h[Flecha llameante]|h|r!' WHERE `ID`=65331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_iceshard.blp:20|t후오슈앙이 |cFFFF0000|Hspell:126321|h[얼어붙은 화살]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_iceshard.blp:20|t火霜施放了|cFFFF0000|Hspell:126321|h[霜冻箭矢]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_iceshard.blp:20|t霍雙施放|cFFFF0000|Hspell:126321|h[冰封箭]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_frost_iceshard.blp:20|t¡Huo-Shuang lanza |cFFFF0000|Hspell:126321|h[Flecha congelada]|h|r!' WHERE `ID`=65332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르이크! 얼마나 오랫동안 여제를 위해 일한 거냐?!', `MaleText_loc4`='科尔里克！你为女皇效命多久了？！', `MaleText_loc5`='柯利克!你為女皇效勞多久了!', `MaleText_loc7`='¡Kor’ik! ¿Cuánto tiempo llevas trabajando para la Emperatriz?' WHERE `ID`=65333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용장이 깨어난 게 느껴진다.', `MaleText_loc4`='我看见英杰被唤醒了。', `MaleText_loc5`='我發覺聖螳已經甦醒了。', `MaleText_loc7`='Veo que el dechado está despierto.' WHERE `ID`=65334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 이 용장은 진실을 말하지 않는구나. 호박석에 담겼을 때 그의 마음이 견뎌내지 못했다.', `MaleText_loc4`='英杰满嘴胡话，唤醒者。封存让他精神失常了。', `MaleText_loc5`='聖螳所說的不是事實，喚醒者。他一定是在封存時失去了他的理智。', `MaleText_loc7`='Este dechado no dice la verdad, heraldo. Su mente no habrá sobrevivido al encierro.' WHERE `ID`=65335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 이런 광기속에서 사는 것을 허용치 않을 것이다. 클락시는 그를 제압하기를 원할 것이야.', `MaleText_loc4`='我们不能再让他这么疯癫下去了。卡拉克西希望制止他。', `MaleText_loc5`='我們不能讓他活在這種瘋狂狀態下。卡拉西會希望將他除掉。', `MaleText_loc7`='No podemos permitir que viva en esta locura. Los Klaxxi querrán sacrificarlo.' WHERE `ID`=65336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 클락시는 아둔하구나! 네놈의 오만함 때문에 죽게 될 것이다!', `MaleText_loc4`='你和卡拉克西都是蠢货！傲慢会让你走向灭亡！', `MaleText_loc5`='你和卡拉西都是群蠢材!你的傲慢會成為你的末日!', `MaleText_loc7`='¡Los Klaxxi y tú son unos estúpidos! ¡Su arrogancia acabará con ustedes!' WHERE `ID`=65337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기에서는 너 자신이 광기일 뿐이다, 코르이크! 영원히 너를 눈치채지 못할 거라고 생각했나?', `MaleText_loc4`='这里疯的只有你自己，科尔里克！你真以为自己能永远不被发现？', `MaleText_loc5`='這裡唯一的瘋子就是你，柯利克!你真的以為你能永遠不被發現嗎?', `MaleText_loc7`='¡La única locura aquí es la tuya, Kor''ik! ¿De verdad pensabas que siempre pasarías desapercibido?' WHERE `ID`=65338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 속이진 못할 거다. 우리는 진짜 네 모습을 알고 있어!', `MaleText_loc4`='你骗不了我们。我们能看穿你的真实身份！', `MaleText_loc5`='你無法欺騙我們。我們將你看透!', `MaleText_loc7`='No nos engañarás. ¡Te vemos como lo que eres!' WHERE `ID`=65339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 모습은... 아버지예요!', `MaleText_loc4`='那看起来像是……我父亲！', `MaleText_loc5`='那看起來像是...我父親!', `MaleText_loc7`='Se parece a... ¡mi padre!' WHERE `ID`=65340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 모습은... 가로쉬 헬스크림이에요!', `MaleText_loc4`='那……好像是加尔鲁什·地狱咆哮！', `MaleText_loc5`='那...好像是卡爾洛斯·地獄吼!', `MaleText_loc7`='Se parece a... ¡Garrosh Grito Infernal!' WHERE `ID`=65341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네, $c. 자네에게 피해를 줄 생각은 없다네.$B$B나는 여기서 붉은십자군인 체하고 있다네. 놈들이 요새 어찌해볼 수 없을 정도로 타락하고 사악해졌거든.$B$B놈들을 완전히 궤멸하려면 자네의 도움이 필요하네.', `FemaleText_loc4`='你好，$c。我并无恶意。$B$B我在这以血色十字军成员的身份出现，是因为他们已经无可救药地堕入了腐化与邪恶。$B$B我需要你的帮助，彻底终结他们的罪孽。', `FemaleText_loc5`='幸會，$c。我沒有傷害你的企圖。$B$B我是以血色十字軍一員的身分來到這裡，因為他們已經變得無可救藥的腐化而邪惡。$B$B我需要你的幫助來徹底終結他們。', `FemaleText_loc7`='Hola, $c. No te deseo mal alguno.$b$bMe hago pasar por un miembro de la Cruzada Escarlata porque se han vuelto malvados y corruptos más allá de toda redención.$B$BNecesito tu ayuda para acabar con ellos de una vez por todas.' WHERE `ID`=65342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 안 돼... 난 여기서 죽는구나...', `MaleText_loc4`='哦……哦不……我要死在这里了。', `MaleText_loc5`='喔...喔不...我就要死在這了...', `MaleText_loc7`='Oh... Oh, no... Voy a morir aquí...' WHERE `ID`=65343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아닙니다! 자, 이걸 받으십시오!', `MaleText_loc4`='不，你不会的！拿上这个！', `MaleText_loc5`='你才不會!來!拿著這個!', `MaleText_loc7`='¡No! ¡No lo harás! ¡Toma esto!', `FemaleText_loc1`='아니에요! 자, 이걸 받으세요!', `FemaleText_loc4`='不，你不会的！拿上这个！', `FemaleText_loc5`='你才不會!來!拿著這個!', `FemaleText_loc7`='¡No! ¡No lo harás! ¡Toma esto!' WHERE `ID`=65344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_soulburn.blp:20|t %s|1이;가; |cFFFF0000|Hspell:126288|h[척살]|h|r을 시전하고 있습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_soulburn.blp:20|t %s正在施放|cFFFF0000|Hspell:126288|h[屠杀]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_soulburn.blp:20|t%s正在施放|cFFFF0000|Hspell:126288|h[虐殺]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_soulburn.blp:20|t %s está lanzando |cFFFF0000|Hspell:126288|h[Diezmar]|h|r.' WHERE `ID`=65345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물이 기름에 뒤덮였습니다. 불을 붙이십시오!', `MaleText_loc4`='那野兽浑身裹满了油，把他点燃！', `MaleText_loc5`='那野獸身上都是油，快對他放火!', `MaleText_loc7`='¡La bestia está cubierta de aceite! ¡Quemadla!' WHERE `ID`=65346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들이여, 공격을 개시하십시오! 놈을 불태우십시오!', `MaleText_loc4`='弓箭手，放箭！让他燃烧起来！', `MaleText_loc5`='弓箭手，攻擊!燒死他!', `MaleText_loc7`='¡Arqueros, ataquen!' WHERE `ID`=65347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름에 불을 붙이십시오!', `MaleText_loc4`='点燃热油！', `MaleText_loc5`='快將油給點燃!', `MaleText_loc7`='¡Prended el aceite!' WHERE `ID`=65348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미줄에서 뛰어내려 도망치십시오!', `MaleText_loc4`='跳起以从网中挣脱！', `MaleText_loc5`='用跳躍來脫離網子!', `MaleText_loc7`='¡Salta para librarte de las redes!', `FemaleText_loc1`='거미줄에서 뛰어내려 도망치십시오!', `FemaleText_loc4`='跳起以从网中挣脱！', `FemaleText_loc5`='用跳躍來脫離網子!', `FemaleText_loc7`='¡Salta para librarte de las redes!' WHERE `ID`=65349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이자는 분노를 통제할 수 있다. 어린 아이의 말과 이 영웅의 행동을 봤을 때, 이해가 가는구나. 안개 너머에서 온 자들은 전쟁으로 단련되었다. 전쟁은 상처를 남겼지만, 그만큼 배운 것도 많아. 난 이들을 믿는다.', `MaleText_loc4`='这个凡人证明了自己驾驭愤怒的能力。通过后辈们的话语和这位英雄的举动，我想我已经明白了。那些来自迷雾之外的人久经战火磨砺。他们伤痕累累，但已有所觉悟。我相信他们。', `MaleText_loc5`='很好，這個人的確證明了自己可以控制怒氣，透過幼虎告訴我的，以及這位英雄的事蹟，我想我明白了。這群從迷霧之外進來的外地人因戰爭而堅強。沒錯，雖然傷痕累累，但是他們也學到不少。我相信他們。', `MaleText_loc7`='Este héroe ha demostrado su dominio sobre la ira. Gracias a sus actos y a las palabras del cachorro, por fin lo comprendo. Los forasteros están curtidos en la batalla. Aún sufren, sí, pero han aprendido mucho. Confío en ellos.' WHERE `ID`=65350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 엄청난 실수를 하시는 겁니다!', `MaleText_loc4`='你犯了个可怕的错误！', `MaleText_loc5`='你犯下嚴重的大錯!', `MaleText_loc7`='¡Están cometiendo un grave error!' WHERE `ID`=65351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 결정된 일이다. 영원꽃 골짜기는 모두에게 열려 있을 것이다. 이방인들이 저지른 죄는 결코 가볍지 않으나... 난 그들이 잘못을 저질렀을 때 되돌릴 수 있음을 안다.', `MaleText_loc4`='我决定了，锦绣谷将继续对外来者开放。他们确实犯下了很大的罪孽……但是，我从他们身上看到了纠正错误的能力。', `MaleText_loc5`='就這樣吧。恆春谷將繼續開放。外來者的罪孽的確深重...但我看到了他們知錯能改的能力。', `MaleText_loc7`='Se ha decidido. El Valle de la Flor Eterna seguirá abierto. Las transgresiones de los extranjeros han sido enormes... pero veo en ellos la capacidad de corregir lo que se hizo mal.' WHERE `ID`=65352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 백호 님. 곧 알게 되실 거예요. 우리 얼라이언스와 호드가 선한 존재라는 걸요.', `MaleText_loc4`='谢谢你，白虎大师。我会证明给你看。相信我的族人——还有部落——内心本善。', `MaleText_loc5`='謝謝你，白虎大師。你會看到的。我相信我的人民，和部落，本性都是善良的。', `MaleText_loc7`='Gracias, maestro Tigre Blanco. Ya lo verás. Creo que mi pueblo y la Horda son buenos por naturaleza.' WHERE `ID`=65353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 이들과 논의하겠다. 문에서 보지.', `MaleText_loc4`='我要征求其他人的意见。大门口见。', `MaleText_loc5`='我去和其他人商量。我們在大門那邊碰面。', `MaleText_loc7`='Consultaré a los demás. Reúnete conmigo a las puertas.' WHERE `ID`=65354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제 셰크지르 님께서 널 파괴할 것이다!', `MaleText_loc4`='女皇夏柯希尔会消灭你！', `MaleText_loc5`='衫齊爾女皇將會摧毀你們!', `MaleText_loc7`='¡La emperatriz Shek''zeer te destruirá!' WHERE `ID`=65355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 신념에는 감탄했소, 작은 이여. 한데 우리 대족장님을 만난 적이 있소?', `MaleText_loc4`='我发现你的信念很振奋人心，小家伙。可不知你见过我们的酋长吗？', `MaleText_loc5`='你的信仰十分有趣，小傢伙。但我很好奇你見過我們的大酋長沒有...', `MaleText_loc7`='Tu fe es una fuente de inspiración, pequeño, pero me pregunto si alguna vez has conocido a nuestro Jefe de Guerra.' WHERE `ID`=65356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제 셰크지르 님께서 네 계획을 알고 계신다. 네놈의 배신은 벌을 받으리라...', `MaleText_loc4`='女皇夏柯希尔知道了你的计划。你要为背叛而受到惩罚……', `MaleText_loc5`='衫齊爾女皇知道你們的計畫。你們背棄的行為將會受到懲罰...', `MaleText_loc7`='La emperatriz Shek''zeer conoce tus planes. Tu traición será castigada...' WHERE `ID`=65357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 내가 맥주를 완성할 동안 야운골을 막게!', `MaleText_loc4`='$n，在我把酒酿好之前，不要让野牛人靠近！', `MaleText_loc5`='$n，在我完成釀酒時將揚古擋下!', `MaleText_loc7`='$n, ¡despacha a los yaungol mientras termino el brebaje!' WHERE `ID`=65358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤에 물든 무기를 하나 더 강화하고 싶습니다. 도와주시겠습니까?', `MaleText_loc4`='我想再升级另一把感染了煞能的武器。你能帮忙吗？', `MaleText_loc5`='我想要升級另一把煞化武器。你能幫忙嗎?', `MaleText_loc7`='Me gustaría mejorar otra arma influenciada por el sha. ¿Me puedes ayudar?', `FemaleText_loc1`='샤에 물든 무기를 하나 더 강화하고 싶습니다. 도와주시겠어요?', `FemaleText_loc4`='我想再升级另一把感染了煞能的武器。你能帮忙吗？', `FemaleText_loc5`='我想要升級另一把煞化武器。你能幫忙嗎?', `FemaleText_loc7`='Me gustaría mejorar otra arma influenciada por el sha. ¿Me puedes ayudar?' WHERE `ID`=65359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 넌 그런 무기를 쥘 자격이 있음을 충분히 증명했지만, 무기를 강화하는 데 드는 재료는 그냥 생기는 것이 아니다.$b$b고야와 이야기해서 준비해 주지. 하지만 값이 싸지는 않을 것이다.$b$b그리고 공포의 결정을 장착한 무기는 하나만 착용할 수 있다는 걸 명심하도록.', `MaleText_loc4`='你确实已经证明了自己的价值，可材料也是要花钱的。$b$b我想我可以跟郭雅夫人做些安排，但价格可不便宜。$b$b请注意，任何时候都只能装备一块恐惧水晶。', `MaleText_loc5`='顯然你已經證明自己的價值，但你仍需要付出代價才能取得材料。$b$b我肯定能從苟雅女士那裡取得一些原料，但價格絕對不會便宜。$b$b請記住你在同一時間只能裝備一個恐懼水晶。', `MaleText_loc7`='Has demostrado merecerlo con creces, pero los materiales no son gratis.$b$bEstoy seguro de que podré llegar a un acuerdo con la señora Goya, pero no será barato.$b$bTen en cuenta que solo se puede equipar un cristal del miedo a la vez.' WHERE `ID`=65360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 해주십시오. 민첩성을 올리고 싶습니다. <10,000 골드를 지불합니다.>', `MaleText_loc4`='物有所值。我希望提升自己的敏捷。<付10,000金币。>', `MaleText_loc5`='很值得。我想要強化我的敏捷。<付10,000金。>', `MaleText_loc7`='Merece la pena. Deseo aumentar mi agilidad. <Paga 10000 de oro.>', `FemaleText_loc1`='그래도 해주세요. 민첩성을 올리고 싶어요. <10,000 골드를 지불합니다.>', `FemaleText_loc4`='物有所值。我希望提升自己的敏捷。<付10,000金币。>', `FemaleText_loc5`='很值得。我想要強化我的敏捷。<付10,000金。>', `FemaleText_loc7`='Merece la pena. Deseo aumentar mi agilidad. <Paga 10000 de oro.>' WHERE `ID`=65361;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 백호에 대한 전설을 들으며 자라났어요. 판다렌에게는 영웅이시죠. 여기서 수련할 수 있다니 영광이에요.', `FemaleText_loc4`='我是听着白虎的传说长大的。他是潘达利亚人民的英雄。很荣幸能来此受训。', `FemaleText_loc5`='我是聽著白虎的傳說長大的。他是熊貓人的英雄，能在這裡受訓真是我的榮幸。', `FemaleText_loc7`='Crecí con las leyendas del Tigre Blanco. Es un héroe para los pandaren. Es un auténtico honor entrenarme aquí.' WHERE `ID`=65362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 여기 남아서 코르이크의 시체를 살펴보겠다. 네가 이 임무들을 완수하면 클락시베스에서 나와 다시 만나게 될 것이다.', `MaleText_loc4`='我留下检查科尔里克的遗骸。等你完成这些任务之后，我会和你在卡拉克西维斯见面。', `MaleText_loc5`='我會留在這裡檢視柯利克的殘骸。當你完成這些任務時，回到卡拉西斐斯找我。', `MaleText_loc7`='Me quedaré aquí para examinar los restos de Kor''ik. Me reuniré contigo en Klaxxi''vess cuando hayas terminado tus tareas.' WHERE `ID`=65363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s|1이;가; |cFFFF0000|Hspell:126652|h[무리거미 부르기]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t %s施放了|cFFFF0000|Hspell:126652|h[召唤虫群]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_hunter_pet_spider.blp:20|t%s施放|cFFFF0000|Hspell:126652|h[呼喚蟲群]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_hunter_pet_spider.blp:20|t ¡%s lanza |cFFFF0000|Hspell:126652|h[Llamar enjambristas]|h|r!' WHERE `ID`=65364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='횃불이 또 필요합니다.', `MaleText_loc4`='再给我一个火炬。', `MaleText_loc5`='我需要另一根火炬。', `MaleText_loc7`='Necesito otra antorcha.', `FemaleText_loc1`='횃불이 또 필요해요.', `FemaleText_loc4`='再给我一个火炬。', `FemaleText_loc5`='我需要另一根火炬。', `FemaleText_loc7`='Necesito otra antorcha.' WHERE `ID`=65365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부하들아! 이 우끼에게 걸맞는 맥주를 가져와라!', `MaleText_loc4`='小的们！给我找桶好酒来！', `MaleText_loc5`='手下們!給我拿一瓶值得烏克喝的酒來!', `MaleText_loc7`='¡Esbirros! ¡Traen brebaje digno de Ook!' WHERE `ID`=65366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해변을 쳐라! 맥주를 훔쳐라!', `MaleText_loc4`='攻进库房！偷取美酒！', `MaleText_loc5`='突襲海岸!偷走他們的酒!', `MaleText_loc7`='¡Asaltad la costa! ¡Robadles el brebaje!' WHERE `ID`=65367;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 이 보급품을 받으세요. 임무 수행에 필요할 거예요.', `FemaleText_loc4`='给，拿上这些补给品吧。你在任务中会用得上。', `FemaleText_loc5`='來，收下這些補給。你在任務中會需要它們的。', `FemaleText_loc7`='Toma estas provisiones. Las necesitarás para tus misiones.' WHERE `ID`=65369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_idol_02.blp:20|t가라잘이 |cFFFF0000|Hspell:122151|h[부두 인형]|h|r이 될 플레이어를 임의로 선택합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_idol_02.blp:20|t戈拉亚选择随机玩家，使其变成了|cFFFF0000|Hspell:122151|h[巫毒娃娃]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_idol_02.blp:20|t卡拉賈挑選了一名隨機玩家變成|cFFFF0000|Hspell:122151|h[巫毒人偶]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_idol_02.blp:20|t¡Gara''jal selecciona a jugadores aleatorios para convertirlos en |cFFFF0000|Hspell:122151|h[Muñecos de vudú]|h|r!' WHERE `ID`=65370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF0000|Hspell:122151|h[부두 인형]|h|r이 되었습니다! 당신이 받는 피해가 공격대의 다른 부두 인형에게 복제됩니다!', `MaleText_loc4`='你变成了|cFFFF0000|Hspell:122151|h[巫毒娃娃]|h|r！你所受到的伤害，会被复制到你团队其他的巫毒娃娃身上！', `MaleText_loc5`='你是一個|cFFFF0000|Hspell:122151|h[巫毒人偶]|h|r!你受到的傷害將被複製到你團隊中其他的巫毒人偶身上!', `MaleText_loc7`='¡Eres un |cFFFF0000|Hspell:122151|h[Muñeco de vudú]|h|r! ¡El daño que recibes se copia a los demás muñecos de vudú de tu banda!', `FemaleText_loc1`='|cFFFF0000|Hspell:122151|h[부두 인형]|h|r이 되었습니다! 당신이 받는 피해가 공격대의 다른 부두 인형에게 복제됩니다!', `FemaleText_loc4`='你变成了|cFFFF0000|Hspell:122151|h[巫毒娃娃]|h|r！你所受到的伤害，会被复制到你团队其他的巫毒娃娃身上！', `FemaleText_loc5`='你是一個|cFFFF0000|Hspell:122151|h[巫毒人偶]|h|r!你受到的傷害將被複製到你團隊中其他的巫毒人偶身上!', `FemaleText_loc7`='¡Eres un |cFFFF0000|Hspell:122151|h[Muñeco de vudú]|h|r! ¡El daño que recibes se copia a los demás muñecos de vudú de tu banda!' WHERE `ID`=65371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|t가라잘이 당신을 영혼의 세계로 완전히 |cFFFF0000|Hspell:116727|h[추방]|h|r했습니다! 현실 세계로 돌아오기 위해서는 영혼 절단자를 모두 처치해야 합니다.', `MaleText_loc4`='|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|t戈拉亚使你彻底|cFFFF0000|Hspell:116727|h[被放逐]|h|r到了灵魂世界！你和你的同伴必须击败所有灵魂撕裂者，才能返回现实世界。', `MaleText_loc5`='|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|t卡拉賈將你完全|cFFFF0000|Hspell:116727|h[放逐]|h|r到靈魂世界之中了!你和你的盟友必須擊敗所有的靈魂分離者以回到真實世界。', `MaleText_loc7`='|TInterfaceIconsinv_enchant_voidsphere.blp:20|t¡Gara''jal te ha |cFFFF0000|Hspell:116727|h[Desterrado]|h|r totalmente al mundo de los espíritus! Tus aliados y tú debéis derrotar a todos los segadores de almas para volver al mundo real.' WHERE `ID`=65373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉화가 서로 노래하고 있다, 이방인이여. 중요한 소식이 전달됐다.$b$b너의 귀로는 그 소식을 들을 수 없다. 오직 클락시가 신뢰하는 자만이 봉화의 노래를 들을 수 있다.', `MaleText_loc4`='信标彼此呼应，外来者。传递重要的信息。$b$b你的耳朵听不见那些信息。只有赢得卡拉克西信任的人才能听到他们说的话。', `MaleText_loc5`='外來人，信標會對彼此歌唱。送出重要的訊息。$b$b你的耳朵聽不見這些訊息。只有卡拉西相信的人能聽見他們的話。', `MaleText_loc7`='Las balizas cantan unas para otras, heraldo. Se envían mensajes importantes.$b$bTus oídos no los oirán. Solo aquellos en los que confían los Klaxxi pueden escuchar las palabras que pronuncian.' WHERE `ID`=65374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 믿음을 위해 희생하는 것은 영광스러운 일이 될 것이다.', `MaleText_loc4`='能为我所笃信的一切牺牲自己，是我的荣耀。', `MaleText_loc5`='能夠為我相信的事物奉獻自己是我的榮耀。', `MaleText_loc7`='Sería un honor sacrificarme por mis creencias.' WHERE `ID`=65375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_shaman_astralshift.blp:20|t당신의 영혼이 현실 세계의 육체로 돌아갈 수 있을 만큼 치유되었습니다!|cFFFF0000|Hspell:120715|h[되살아난 영혼]|h|r 버튼을 눌러서 영혼을 구하십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_shaman_astralshift.blp:20|t你的灵魂已得到充分治愈，能与现实世界中的躯体合二为一了！用你的|cFFFF0000|Hspell:120715|h[复苏之魂]|h|r动作按钮来拯救自己的灵魂！', `MaleText_loc5`='|TInterface\\Icons\\ability_shaman_astralshift.blp:20|t你的靈魂已經獲得足夠的治療，可以回歸真實世界中的身體了!使用你的|cFFFF0000|Hspell:120715|h[復活靈魂]|h|r快捷鍵以拯救你的靈魂!', `MaleText_loc7`='|TInterfaceIconsability_shaman_astralshift.blp:20|tTu espíritu se ha sanado lo suficiente como para volver a su cuerpo en el mundo real. ¡Utiliza tu botón |cFFFF0000|Hspell:120715|h[Espíritu revitalizado]|h|r para salvar tu espíritu!' WHERE `ID`=65376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 좀 바쁘다, 이방인이여.', `MaleText_loc4`='我很忙，外来者。', `MaleText_loc5`='我很忙，外來人。', `MaleText_loc7`='Estoy ocupado, heraldo.' WHERE `ID`=65377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 영혼의 세계로 |cFFFF0000|Hspell:116161|h[횡단]|h|r했습니다! 스스로 치유하거나 동료에게 치유를 받아 30초 내에 영혼의 생명력을 90%까지 채우지 않으면 죽게 됩니다!', `MaleText_loc4`='你已经|cFFFF0000|Hspell:116161|h[灵魂越界]|h|r到了灵魂世界！你或某位同伴必须在30秒内为你的灵魂回复90%的生命，否则你就将消亡！', `MaleText_loc5`='你已經|cFFFF0000|Hspell:116161|h[跨界]|h|r到了靈魂世界!你或你的一名盟友必須在30秒內將你的靈魂恢復到90%生命力，否則你將會死亡!', `MaleText_loc7`='¡Has |cFFFF0000|Hspell:116161|h[Cruzado]|h|r al mundo de los espíritus! Un aliado o tú debéis sanar tu espíritu hasta el 90% de salud dentro de 30 s o morirás.' WHERE `ID`=65378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 클락시가 내 계급을 상승시킬 거다. 그러면 호박석을 먹어도 되겠지.', `MaleText_loc4`='终有一天，卡拉克西会晋升我的地位。会允许我消耗琥珀。', `MaleText_loc5`='總有一天，卡拉西會提升我的階級。我將有資格吞食琥珀。', `MaleText_loc7`='Algún día los Klaxxi me ascenderán de rango. Me permitirán consumir ámbar.' WHERE `ID`=65379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 클락시는 누군가를 쉽사리 신뢰하지 않는다. 나 또한 클락시 앞에 서는 것조차도 여러 해가 걸렸다.', `MaleText_loc4`='卡拉克西从不轻易相信别人，外来者。我花了很多年时间才令他们正眼相看。', `MaleText_loc5`='卡拉西不會輕易信任他人，外來人。光是要面見他們就花了我許多年的時間。', `MaleText_loc7`='Los Klaxxi no otorgan su confianza a la ligera, heraldo. Me ha costado muchos años que se percaten de mi existencia.' WHERE `ID`=65380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 재능이 아주 뛰어나다. 어떤 이들은 정말 보기 드문 존재지.', `MaleText_loc4`='我们人人都有天赋，外来者。只不过有些人表现得没那么明显。', `MaleText_loc5`='每個人都有獨特的天賦，外來者。只是有些人不如其他人那麼明顯。', `MaleText_loc7`='Todos tenemos nuestros talentos, heraldo. Es solo que algunos son menos evidentes que otros.' WHERE `ID`=65381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_challangingroar.blp:20|t가라잘이 |cFFFF0000|Hspell:117752|h[광기]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_challangingroar.blp:20|t戈拉亚施放了|cFFFF0000|Hspell:117752|h[狂乱]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_challangingroar.blp:20|t卡拉賈施放|cFFFF0000|Hspell:117752|h[狂亂]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_druid_challangingroar.blp:20|t¡Gara''jal lanza |cFFFF0000|Hspell:117752|h[Frenesí]|h|r!' WHERE `ID`=65382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 절반쯤 끝난 것 같군. 안 그런가? 붉은십자군 전당은 함락됐고, 붉은십자군 수도원만 남았으니까 말이네.$B$B내가 없어지더라도 놀라지 말게 붉은십자군 수도원에 빨리 가야 해서 말이지.', `FemaleText_loc4`='我想我们差不多干完一半了，对吧？已经解决了血色大厅，还剩下血色修道院。$B$B要是我突然消失了你可别吃惊——我得快点赶到那里。', `FemaleText_loc5`='看來我們已經完成一半了，不是嗎?攻陷了血色大廳，接著就是血色修道院。$B$B若看到我消失了不用擔心，我得儘快過去那裡。', `FemaleText_loc7`='Diría que ya hemos recorrido la mitad del camino, ¿no crees? Cámaras Escarlata terminadas, queda el Monasterio Escarlata.$B$BNo te sorprendas si desaparezco; tengo que llegar allí deprisa.' WHERE `ID`=65383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='밖에 시체가 아주 많이 있더군. 정말 훌륭하네, $p.', `FemaleText_loc4`='真是尸横遍地啊。干得不错，$p。', `FemaleText_loc5`='外面屍橫遍野。幹得好，$p。', `FemaleText_loc7`='Hay muchos cadáveres aquí. Bien hecho, $p.' WHERE `ID`=65384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='십자군 전서를 획득했나?', `FemaleText_loc4`='你拿到书典了吗？', `FemaleText_loc5`='你拿到聖典了嗎?', `FemaleText_loc7`='¿Conseguiste el códice?' WHERE `ID`=65385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두건 쓴 성전사가 무릎을 꿇고 화염술사의 시체를 조사하며 무언가를 찾습니다.', `FemaleText_loc4`='蒙面的十字军战士跪下来检查织焰者的尸体，同时在寻找着什么。', `FemaleText_loc5`='戴頭罩的十字軍跪下來檢視織焰者的屍體，找尋著什麼東西。', `FemaleText_loc7`='La cruzada encapuchada se arrodilla para examinar el cadáver del tejedor de fuego, en busca de algo.' WHERE `ID`=65386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 다시 양조를 시작해야겠군요.', `MaleText_loc4`='现在，继续酿酒！', `MaleText_loc5`='現在，繼續釀酒去!', `MaleText_loc7`='¡Prosigamos con la preparación!' WHERE `ID`=65387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝거리는 건 내 거야!', `MaleText_loc4`='那闪闪发亮的宝贝是我的！', `MaleText_loc5`='閃亮亮是我的!', `MaleText_loc7`='¡El brillante esss mío!' WHERE `ID`=65388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 가질 수 없어!', `MaleText_loc4`='你休想夺走！', `MaleText_loc5`='你不能得到它!', `MaleText_loc7`='¡No essss para ti!' WHERE `ID`=65389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 거야!', `MaleText_loc4`='它是我的！', `MaleText_loc5`='它是我的!', `MaleText_loc7`='¡Esss mío!' WHERE `ID`=65390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 반짝이...', `MaleText_loc4`='我那亮晶晶的宝贝……', `MaleText_loc5`='我的閃亮亮...', `MaleText_loc7`='Brilla...' WHERE `ID`=65391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기수들이 몰려온다!', `MaleText_loc4`='骑兵来了！', `MaleText_loc5`='騎兵接近!', `MaleText_loc7`='¡Se acercan asaltantes!' WHERE `ID`=65392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 손으로 우리 마을을 지키다니 자랑스러워요.', `FemaleText_loc4`='我为成功守住我们的村庄而感到骄傲。', `FemaleText_loc5`='能夠保衛我們的村莊讓我很驕傲。', `FemaleText_loc7`='Estoy orgullosa de haber defendido nuestra aldea.' WHERE `ID`=65393;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠, 난 이제 아빠가 늘 걱정하던 힘없는 아이가 아니에요.', `FemaleText_loc4`='父亲，我再也不是让你担忧的无助孩童了。', `FemaleText_loc5`='父親，我不再是讓你擔心的那個無助的孩子了。', `FemaleText_loc7`='Padre, ya no soy la niña indefensa por la que te preocupabas.' WHERE `ID`=65394;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞으로도 우리 마을을 지킬 수 있도록, 훈련을 계속하고 싶어요.', `FemaleText_loc4`='我愿意继续训练，使自己能永远守护我们的家园。', `FemaleText_loc5`='我向要繼續受訓，那樣我就能一直保衛我的家園。', `FemaleText_loc7`='Quiero proseguir con mi entrenamiento para ser siempre capaz de defender nuestro hogar.' WHERE `ID`=65395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠가 다시 무기를 들 일이 없도록 내가 마을을 지키겠어요.', `FemaleText_loc4`='我会确保这村庄的安全，让你能安心地卸下武器。', `FemaleText_loc5`='我會保護這個村子的安全，那樣你就不用再使用武器了。', `FemaleText_loc7`='Yo protegeré esta aldea para que tú puedas retirar tus armas.' WHERE `ID`=65396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지로서 이렇게 자랑스러워 본 적이 없구나, 쇼미.', `MaleText_loc4`='从没有哪个父亲为自己的孩子感到如此骄傲过，朔弥。', `MaleText_loc5`='沒有哪個父親能為他的孩子感到這麼驕傲，琇蜜。', `MaleText_loc7`='No existe padre que se sienta más orgulloso de su hija, Shomi.' WHERE `ID`=65397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 다 영광스럽다, 딸아. 정말 자랑스러운 순간이구나.', `MaleText_loc4`='你的言辞令我倍感荣耀，女儿。这是个值得骄傲的时刻。', `MaleText_loc5`='你的話讓我感到光榮，女兒。這真是令人驕傲的時刻。', `MaleText_loc7`='Tus palabras me honran, hija. Este momento me llena de orgullo.' WHERE `ID`=65398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 앞으로도 내 딸이고, 나는 늘 너를 걱정하겠지만, 네가 네 앞가림을 할 수 있다는 건 알겠구나.', `MaleText_loc4`='你永远都是我的小女孩，我始终都会牵挂你，可我知道，你现在能自己照顾自己了。', `MaleText_loc5`='你永遠都會是我的小女兒，我也永遠會為你擔心。但我現在知道妳可以照顧好自己了。', `MaleText_loc7`='Siempre serás mi niña y siempre me preocuparé por ti, pero ahora sé que puedes defenderte sola.' WHERE `ID`=65399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 소식일세. 이곳의 기운과 유물에 대한 조사가 결실을 맺기 시작했네.$B$B이곳에 있는 모구 장치를 조금 이해할 수 있게 되었다네. 게다가 우리한테 유리하게 쓰는 방법도 알게 되었지. 이 건물의 벽 자체가 안에 있는 적의 힘을 흡수해서 약화시킨다네.', `MaleText_loc4`='真是好消息。我们对这里的能量和神器的研究有回报了。$B$B我们已经对在这里找到的魔古族装置有所了解，更令人振奋的是，还找到了让它们为我所用的方法。这座建筑的围墙会汲取和削弱任何置身其中的敌人的力量。', `MaleText_loc5`='這消息太好了。我們對這地方的能量和古物的研究開始有收穫了。$B$B我們稍微解開了在這裡發掘出的魔古裝置的功用，更棒的是，我們還找到能利用這些裝置的方法。這棟建築的牆壁能吸取裡面所有敵人的力量。', `MaleText_loc7`='Buenas noticias. Nuestros estudios de la energía de este lugar y sus artefactos empieza a dar resultados.$b$bHemos adquirido cierta comprensión de los dispositivos mogu que se encuentran aquí, y lo que es mejor, cómo utilizarlos a nuestro favor. Las paredes mismas de esta estructura debilitarán el poder de todos los enemigos que haya en su interior.' WHERE `ID`=65400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='완전히 이해하지 못하는 수수께끼는 건드리지 않는 편이 좋을지도 모릅니다. 혹시 약화 장치를 무력화할 수 있습니까? 저와 동료들은 알아서 할 수 있습니다. 우린 괜찮을 거예요.', `MaleText_loc4`='最好不要擅动我们尚未完全理解的神秘事物。也许你应该去停掉那些弱化的装置。我和同伴能自己照顾自己。我们一定会没事的。', `MaleText_loc5`='最好不要玩弄還沒徹底理解的秘密。也許你應該關閉那個抑制裝置。我的同伴和我可以照顧好自己，我們會沒事的。', `MaleText_loc7`='Quizás sea mejor no interferir en misterios que no entendemos del todo. A lo mejor deberías desactivar los dispositivos de atenuación. Mis compañeros y yo podemos arreglárnoslas solos. Seguro que no nos pasará nada.', `FemaleText_loc1`='완전히 이해하지 못하는 수수께끼는 건드리지 않는 편이 좋을지도 몰라요. 혹시 약화 장치를 무력화할 수 있나요? 저와 동료들은 알아서 할 수 있어요. 우린 괜찮을 거예요.', `FemaleText_loc4`='最好不要擅动我们尚未完全理解的神秘事物。也许你应该去关掉那些弱化的装置。我和同伴能自己照顾自己。我们一定会没事的。', `FemaleText_loc5`='最好不要玩弄還沒徹底理解的秘密。也許你應該關閉那個抑制裝置。我的同伴和我可以照顧好自己，我們會沒事的。', `FemaleText_loc7`='Quizás sea mejor no interferir en misterios que no entendemos del todo. A lo mejor deberías desactivar los dispositivos de atenuación. Mis compañeros y yo podemos arreglárnoslas solos. Seguro que no nos pasará nada.' WHERE `ID`=65401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 장치를 무력화해 주십시오.', `MaleText_loc4`='是的，请停用装置。', `MaleText_loc5`='是的，請關閉那些裝置。', `MaleText_loc7`='Sí, desactiva los dispositivos.', `FemaleText_loc1`='네, 장치를 무력화해 주세요.', `FemaleText_loc4`='是的，请停用装置。', `FemaleText_loc5`='是的，請關閉那些裝置。', `FemaleText_loc7`='Sí, desactiva los dispositivos.' WHERE `ID`=65402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말인가? 이곳은 위험한 곳일세. 처음으로 투입된 연구원들도 아직도 돌아오지 않았지. 약화 장치를 무력화하고 나면 우리는 이 폐허를 무사히 확보할 때까지 이곳을 떠나 있을 걸세. 즉, 장치를 다시 켤 수 없다는 얘기지.$B$B다시 묻겠네. 정말인가?', `MaleText_loc4`='你确定吗？这地方很危险，而且我们的首批研究人员都还没能安然返回。如果我们禁用了弱化力场，我们就要离开，直到遗迹被安全守住后才能回来，而且不能再次激活装置。$B$B我再问一次——你确定吗？', `MaleText_loc5`='你確定嗎?這是個危險的地方，我們第一批研究隊伍出去探險，至今還沒回來。如果我們關閉抑制力場，我們會離開這裡，直到確保廢墟安全了才回來。那些裝置也無法再度開啟。$B$B讓我再問你一次，你確定嗎?', `MaleText_loc7`='¿Seguro? Este es un lugar peligroso; nuestros primeros investigadores aún no han vuelto de su expedición. Si desactivamos el campo de atenuación, abandonaremos las ruinas hasta que estén aseguradas y no podremos reactivarlo.$b$bTe lo pregunto de nuevo: ¿seguro que quieres hacerlo?' WHERE `ID`=65403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 늦었다.', `MaleText_loc4`='你太迟了。', `MaleText_loc5`='你來晚了。', `MaleText_loc7`='Llegan demasiado tarde.' WHERE `ID`=65404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 유해는 징벌의 섬으로 갔다...', `MaleText_loc4`='雷电之王的遗骸已被带去末劫岛了。', `MaleText_loc5`='他們把雷王遺體帶去清算之島了。', `MaleText_loc7`='Se llevaron los restos del Rey del Trueno a la Isla de las Almas Perdidas…' WHERE `ID`=65405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 고대 의식을 치렀고...', `MaleText_loc4`='我们举行了古老的仪式……', `MaleText_loc5`='我們施行了古老儀式...', `MaleText_loc7`='Realizamos los rituales antiguos...' WHERE `ID`=65406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금도, 판다리아의 진정한 황제는 다시 살아나 있다.', `MaleText_loc4`='现在，潘达利亚的真命天子要再次降临这个世界了。', `MaleText_loc5`='就是現在，真正的潘達利亞大帝再次復甦。', `MaleText_loc7`='El VERDADERO Emperador de Pandaria vive y respira una vez más.' WHERE `ID`=65407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부디 큰일은 안 나야 할 텐데.', `MaleText_loc4`='我真希望你知道自己在做什么。', `MaleText_loc5`='我真的希望你知道自己在幹啥。', `MaleText_loc7`='Espero sinceramente que sepas lo que haces.' WHERE `ID`=65408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌 찬탈자들에게 재앙 있으리! 모구가 다시 이 땅을 지배하면 우리 잔달라 부족에게 새 터전이 생기리라...', `MaleText_loc4`='向熊猫人篡位者致哀吧！魔古族将再度崛起，赞达拉也将得到新的家园……', `MaleText_loc5`='篡位的熊貓人大難臨頭了!魔古族會再次統治這片大地，而我們贊達拉會獲得新的家園...', `MaleText_loc7`='¡Ay de los usurpadores pandaren! Los mogu gobernarán esta tierra y los Zandalari tendremos un nuevo hogar.' WHERE `ID`=65409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해를 챙겨라, 형제들이여!', `MaleText_loc4`='守住遗骸，兄弟们！', `MaleText_loc5`='各位兄弟，保護遺體!', `MaleText_loc7`='¡Protejan los restos, hermanos!' WHERE `ID`=65410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕은 부활할 것이다...', `MaleText_loc4`='雷电之王必将重生……', `MaleText_loc5`='雷王會再次復甦...', `MaleText_loc7`='El Rey del Trueno volverá a la vida...' WHERE `ID`=65411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕은 살아난다! 두 제국은 다시 하나가 되리라...', `MaleText_loc4`='雷电之王复活了！我们的帝国再次团结在一起……', `MaleText_loc5`='雷王是不滅的，我們的王國將會再度統一。', `MaleText_loc7`='¡El Rey del Trueno vive! Nueh''tros imperios eh''tán unidos otra vez...' WHERE `ID`=65412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 이 땅이 필요해! 대격변이 우리 고향을 파괴했어!', `MaleText_loc4`='我们需要这片土地！大灾变毁了我们的家园！', `MaleText_loc5`='我們需要這片土地!大災變摧毀了我們的家園!', `MaleText_loc7`='¡Necesitamos eh''ta tierra! El Cataclismo deh''truyó nueh''tro hogar.' WHERE `ID`=65413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 시작일 뿐이다... 우리가 그냥 쉽게 죽을 거라 생각 마...', `MaleText_loc4`='这只是个开始……我们可不会接二连三地倒下……', `MaleText_loc5`='這才剛剛開始...我們不會坐以待斃的...', `MaleText_loc7`='Eh''to acaba de empezar... No nos dejaremos matar sin más...' WHERE `ID`=65414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왔구나... 오염의 근원인 이곳에. 우리가 돕겠다. 우리의 노래가 이 뒤틀린 곳의 벽에 메아리치며, 우리 종족을 버린 자들의 의지를 약화시킬 것이다.', `MaleText_loc4`='你终于来到了这污染的中心地带。我们会助你一臂之力。我们的歌声会在这扭曲之地四处回响，让那些遗弃我族的人，决心尽数瓦解。', `MaleText_loc5`='你來了，來到污染的中心。我們會幫助你。我們的歌會迴響過這扭曲地方的牆壁，削弱遺棄我們種族的那些人的決心。', `MaleText_loc7`='Así que han venido hasta aquí, hasta el corazón de la contaminación. Los ayudaremos. Nuestro canto resonará por los muros de este siniestro lugar y debilitará la determinación de aquellos que han traicionado a nuestra raza.' WHERE `ID`=65415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움 없이도 할 수 있습니다. 물러나십시오. 당신이 돌아올 때면 여제는 쓰러져 있고 문제도 해결되어 있을 겁니다.', `MaleText_loc4`='我们绝对能独自应对。撤退吧。等你们回来时就会发现女皇被杀死了，你们的麻烦也已得到解决。', `MaleText_loc5`='我們完全有能力不靠外援就完成這件事。撤退吧。當你回來時，你會發現女皇已死，你的麻煩得到解決。', `MaleText_loc7`='Somos más que capaces de manejar esto sin su ayuda. Retírense. Cuando vuelvan, la Emperatriz habrá muerto y sus problemas estarán resueltos.', `FemaleText_loc1`='도움 없이도 할 수 있어요. 물러나세요. 당신이 돌아올 때면 여제는 쓰러져 있고 문제도 해결되어 있을 거예요.', `FemaleText_loc4`='我们绝对能独自应对。撤退吧。等你们回来时就会发现女皇被杀死了，你们的麻烦也已得到解决。', `FemaleText_loc5`='我們完全有能力不靠外援就完成這件事。撤退吧。當你回來時，你會發現女皇已死，你的麻煩得到解決。', `FemaleText_loc7`='Somos más que capaces de manejar esto sin su ayuda. Retírense. Cuando vuelvan, la Emperatriz habrá muerto y sus problemas estarán resueltos.' WHERE `ID`=65416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 우리가 알아서 처리하겠습니다.', `MaleText_loc4`='是的，我们会用自己的方式解决此事。', `MaleText_loc5`='是的，我們會用自己的方法料理這件事。', `MaleText_loc7`='Sí. Lo haremos a nuestra manera.', `FemaleText_loc1`='예, 우리가 알아서 처리할게요.', `FemaleText_loc4`='是的，我们会用自己的方式解决此事。', `FemaleText_loc5`='是的，我們會用自己的方法料理這件事。', `FemaleText_loc7`='Sí. Lo haremos a nuestra manera.' WHERE `ID`=65417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 오만인가, 어리석음인가? 이곳의 벽 안에서 사신이 너희를 기다리고 있다. 우리가 떠나면 너희는 도움을 받지 못한다. 네가 무슨 말을 하는지는 알고 그러는 거냐?', `MaleText_loc4`='这是傲慢还是愚蠢？你们很可能会死在这里。如果我们走了，你们会陷入孤立无援的境地。你知道自己在说什么吗？', `MaleText_loc5`='這是傲慢或是愚蠢?在這些牆壁之間等待的，將是你的死亡。如果我們將你留在這裡，你將會孤立無援。你知道自己在講什麼嗎?', `MaleText_loc7`='¿Te motiva la arrogancia o la mera imprudencia? Los espera la muerte en este lugar. Si nos vamos, no tendrán ayuda. ¿Te das cuenta de lo que dices?' WHERE `ID`=65418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정 그렇다면야.', `MaleText_loc4`='随便吧。', `MaleText_loc5`='那就這麼辦吧。', `MaleText_loc7`='Así sea.' WHERE `ID`=65419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFFFF0000|Hspell:121970|h[덫에 걸렸습니다]|h|r! 통을 클릭해서 구해 주십시오!', `MaleText_loc4`='$n|cFFFF0000|Hspell:121970|h[被捕获]|h|r了！点击桶，把$G他:她;放出来！', `MaleText_loc5`='$n|cFFFF0000|Hspell:121970|h[被困住]|h|r!點擊桶子以釋放$G他:她;!', `MaleText_loc7`='¡$n está |cFFFF0000|Hspell:121970|h[$gAtrapado:Atrapada;]|h|r! Para $gliberarlo:liberarla; haz clic en el barril.' WHERE `ID`=65420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 아래 천둥이 자고...', `MaleText_loc4`='昆莱山下，雷电在沉睡……', `MaleText_loc5`='雷王沉眠於崑萊之下...', `MaleText_loc7`='Bajo la Cima Kun-Lai duerme el trueno...' WHERE `ID`=65421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전 잦아든 폭풍이 쉬네...', `MaleText_loc4`='久违的风暴沉寂无声……', `MaleText_loc5`='那裡的風暴早已止息...', `MaleText_loc7`='La tormenta descansa en su dulce sueño...' WHERE `ID`=65422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러나 형제 왕국의 피로...', `MaleText_loc4`='可兄弟王国的鲜血……', `MaleText_loc5`='但是友邦之血維持著...', `MaleText_loc7`='Pero la sangre del reino hermano...' WHERE `ID`=65423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빼앗긴 민족은 살아나리...', `MaleText_loc4`='令被逐者生机犹存……', `MaleText_loc5`='喪國之人一線生機...', `MaleText_loc7`='Da vida a los desheredados...' WHERE `ID`=65424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 피로 그는 깨어나고...', `MaleText_loc4`='赞达拉的鲜血将带他归返……', `MaleText_loc5`='以贊達拉之血，他將會被救出...', `MaleText_loc7`='Se tomará con sangre Zandalari...' WHERE `ID`=65425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 목소리로 눈을 뜨리...', `MaleText_loc4`='赞达拉的声音将使他苏醒……', `MaleText_loc5`='因贊達拉之聲，他將會甦醒...', `MaleText_loc7`='Se despertará con voz Zandalari...' WHERE `ID`=65426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장은 여자가 있을 곳이 아니에요!', `MaleText_loc4`='战场不是女孩子该待的地方！', `MaleText_loc5`='戰場不是一個女孩該來的地方!', `MaleText_loc7`='¡El campo de batalla no es lugar para una niña!' WHERE `ID`=65427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시만 박히지 않았더라도 나도 밖에서 마을을 지키고 있을 거예요!', `MaleText_loc4`='如果不是因为我被刺扎到，我肯定也已经跑去守卫我们的村子了！', `MaleText_loc5`='我要不是被刺扎到了，我也會出去防衛我們的村莊!', `MaleText_loc7`='¡Si no hubiera pisado una astilla, yo también estaría defendiendo la aldea!' WHERE `ID`=65428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼미는 싸우려고 하면 안 돼요. 싸움은 남자의 일이니까요!', `MaleText_loc4`='朔弥不会想去战斗的。那是男人的责任！', `MaleText_loc5`='琇蜜不應該想要戰鬥。那是男人的工作!', `MaleText_loc7`='Shomi no debería querer luchar. ¡Es un trabajo de hombres!' WHERE `ID`=65429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼미는 정말 어린애예요!', `MaleText_loc4`='朔弥还是个孩子！', `MaleText_loc5`='琇蜜真是孩子氣!', `MaleText_loc7`='¡Shomi es una niña!' WHERE `ID`=65430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신을 바라보는 코보크의 눈이 커집니다.>', `MaleText_loc4`='<科沃克睁大眼睛望着你。>', `MaleText_loc5`='<科沃克睜大著眼睛看著你。>', `MaleText_loc7`='<Kovok te mira con ojos como platos.>' WHERE `ID`=65431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<염려스러운 눈으로 당신을 바라보는 코보크>', `MaleText_loc4`='<科沃克关切地看着你。>', `MaleText_loc5`='<科沃克擔心地看著你。>', `MaleText_loc7`='<Kovok te observa con preocupación.>' WHERE `ID`=65432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<코보크가 행복하게 재잘거리는 것 같습니다...>', `MaleText_loc4`='<你觉得……科沃克欢快地叫着。>', `MaleText_loc5`='<科沃克快樂地叫了幾聲...你覺得啦。>', `MaleText_loc7`='<Kovok suena feliz... o eso crees.>' WHERE `ID`=65433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 평생 잔달라 부족을 볼 일이 있을 줄은 몰랐네.', `MaleText_loc4`='我这一辈子也没想过会见到赞达拉巨魔。', `MaleText_loc5`='我這輩子從沒想過會看到贊達拉。', `MaleText_loc7`='Jamás en la vida pensé que vería a los Zandalari.' WHERE `ID`=65434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을은 내가 기억하는 한 늘 평화로웠다네. 우리 무기도, 우리 전사도 녹이 슬었지.', `MaleText_loc4`='这村子打从我记事之前就一直平静得很。我们的武器肯定和我们的战士一样，锈得不会动了。', `MaleText_loc5`='從我有記憶以來，這村子就是這麼和平。我們的武器肯定已經朽壞，就和我們生疏的戰士一樣。', `MaleText_loc7`='Nuestra aldea ha conocido la paz desde que tengo memoria. Nuestras armas están tan oxidadas como nuestros luchadores.' WHERE `ID`=65435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기적이 일어나지 않는 한 이 공격을 막아 낼 순 없네.', `MaleText_loc4`='要是能经受住这次攻击，那可真是奇迹了。', `MaleText_loc5`='我們需要奇蹟才能從這場攻擊裡活下來。', `MaleText_loc7`='Necesitaremos un milagro para sobrevivir a este ataque.' WHERE `ID`=65436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 다 하고 나면, 잔달라 놈들은 뭐에 당했는지도 모를 걸세!', `MaleText_loc4`='那些赞达拉巨魔到死都不会知道是什么击中了他们！', `MaleText_loc5`='等我完成後，那些贊達拉連怎麼死的都不知道!', `MaleText_loc7`='Cuando termine con ellos, ¡los Zandalari no sabrán qué les ha pasado!' WHERE `ID`=65437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 평화를 되찾을 수 있겠군!', `MaleText_loc4`='终于能重获和平了！', `MaleText_loc5`='終於，可以恢復和平了!', `MaleText_loc7`='¡Por fin se podrá restablecer la paz!' WHERE `ID`=65438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 진정한 영웅일세!', `MaleText_loc4`='你是真正的英雄！', `MaleText_loc5`='你是真正的英雄!', `MaleText_loc7`='¡Eso es un héroe de verdad!' WHERE `ID`=65439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 다시 뜨개질을 시작할 수 있겠군! 겨울 목도리가 저절로 완성되는 건 아니거든!', `MaleText_loc4`='我终于能继续回去织毛线了！那些冬天戴的围巾可不会自己跑出来！', `MaleText_loc5`='我終於可以回去織我的東西了!那些圍巾可不會自己長出來!', `MaleText_loc7`='¡Por fin puedo volver a mi labor! Las bufandas de invierno no se hacen solas.' WHERE `ID`=65440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 존경과 감사를 받아 주게.', `MaleText_loc4`='我们要向你表达敬意与感谢。', `MaleText_loc5`='你贏得了我們的尊敬與感謝。', `MaleText_loc7`='Cuentas con nuestro respeto y nuestro agradecimiento.' WHERE `ID`=65441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 일로 많은 것을 배웠네.', `MaleText_loc4`='这些事让我懂得了许多。', `MaleText_loc5`='這些事件讓我學到了這麼多。', `MaleText_loc7`='Estos acontecimientos me han enseñado mucho.' WHERE `ID`=65442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덕분에 내 딸이 어떤 아인지 알게 되었네.', `MaleText_loc4`='谢谢你让我看清楚我自己的女儿。', `MaleText_loc5`='謝謝你開了我的眼界，讓我理解到我女兒真正的潛力。', `MaleText_loc7`='Gracias por haberme descubierto quién es realmente mi hija.' WHERE `ID`=65443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 우리 마을을 구했을 뿐 아니라, 우리 가족도 바로잡아 주었네.', `MaleText_loc4`='你不仅救了我们的村庄，还修复了我的家庭。', `MaleText_loc5`='你不只拯救了我們的村莊，更修復了我的家庭。', `MaleText_loc7`='No solo has salvado a nuestra aldea; también has reunido a mi familia.' WHERE `ID`=65444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='덕분에 정말 많이 성장했어요!', `FemaleText_loc4`='是你让我成长了许多！', `FemaleText_loc5`='我成長了好多，都是你的功勞!', `FemaleText_loc7`='¡Gracias a ti he crecido mucho!' WHERE `ID`=65445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 연이 다시 닿는 날을 기다릴게요!', `FemaleText_loc4`='愿我们能再次相见！', `FemaleText_loc5`='我期待和你再會的那一天!', `FemaleText_loc7`='¡Espero que nuestros caminos se vuelvan a cruzar pronto!' WHERE `ID`=65446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에는 내가 당신을 구할지도 모르죠!', `FemaleText_loc4`='也许下一次就轮到我救你了！', `FemaleText_loc5`='或許下一次，會是我來拯救你!', `FemaleText_loc7`='¡A lo mejor la próxima vez te salve yo a ti!' WHERE `ID`=65447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 세상에 나갈 준비가 됐는데, 세상이 날 맞이할 준비가 됐는지 모르겠네요!', `FemaleText_loc4`='我已经为世界做好了准备，可不知世界准备好了没有！', `FemaleText_loc5`='我準備好面對世界了，但不知道世界準備好迎接我了沒!', `FemaleText_loc7`='Estoy lista para el mundo, ¡pero no sé si el mundo está listo para mí!' WHERE `ID`=65448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해를 찾으려면 빨리 움직여야 하네.', `MaleText_loc4`='要是我们想找到遗骸，就必须赶快行动。', `MaleText_loc5`='我們得快點工作，才能找到那些遺體。', `MaleText_loc7`='Tendremos que obrar rápido para hacernos con los restos.' WHERE `ID`=65449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 사람 한 사람이 중요하네. 모래 알갱이가 없으면, 모래밭에 누워서 바다를 바라볼 수도 없지.', `MaleText_loc4`='每个村民都算在内。不积沙粒，何来享受海滨美景的广阔沙滩。', `MaleText_loc5`='每個村民的力量都不可或缺。積沙才能成塔。', `MaleText_loc7`='Cada aldeano cuenta. Si no fuera por cada granito de arena, no tendríamos playas en las que disfrutar del océano.' WHERE `ID`=65450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난관에 부닥칠 때마다 교훈을 얻을 수 있다네.', `MaleText_loc4`='从我们面临的每次挑战中，都有教训可以吸取。', `MaleText_loc5`='我們面對的每一次挑戰，都有一個教訓蘊含在裡面。', `MaleText_loc7`='Cada desafío al que nos enfrentamos es una lección por aprender.' WHERE `ID`=65451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마을이 싸움에서 이긴 것은 자네 덕분이네.', `MaleText_loc4`='这个村庄的胜利要归功于你。', `MaleText_loc5`='村子能夠得到勝利都得感謝你。', `MaleText_loc7`='Esta aldea te debe su victoria.' WHERE `ID`=65452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유해를 잃었다 해서 패배했다고 생각하는 건 어리석은 일일세. 이 마을을 본받아 앞으로 많은 이들이 천둥왕에게 맞설 걸세. 이건 큰 승리라네!', `MaleText_loc4`='一味地为弄丢遗骸而悔恨是愚蠢的。这个村子是最先挺身对抗雷电之王的先驱之一。这是一场伟大的胜利！', `MaleText_loc5`='如果執著在失去遺體這場敗仗上，那我們就太愚蠢了。這村莊將是奮起對抗雷王的第一道狼煙。這是場偉大的勝利!', `MaleText_loc7`='Sería estúpido no ver más que una derrota en la pérdida de los restos. Esta aldea es la primera de las muchas que se alzarán contra el Rey del Trueno. ¡Es una gran victoria!' WHERE `ID`=65453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕에게 맞설 때, 우리는 준비되어 있을 걸세.', `MaleText_loc4`='当我们直面雷电之王时，我们一定会做好准备。', `MaleText_loc5`='等到要面對雷王時，我們會準備好的。', `MaleText_loc7`='Cuando nos enfrentemos al Rey del Trueno, estaremos preparados.' WHERE `ID`=65454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='긍정적인 측면도 많은데 부정적인 측면만 보아서는 안 된다네.', `FemaleText_loc4`='有这么多值得高兴的事，我们不能只想着消极的方面。', `FemaleText_loc5`='當事情還有光明面時，我們不能光關注那黑暗面。', `FemaleText_loc7`='No debemos ver solamente lo negativo cuando hay muchas cosas positivas.' WHERE `ID`=65455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 역경도 언젠가는 지나갈 테고, 그러고 나면 우리는 강해져 있겠지.', `FemaleText_loc4`='这些困难都会过去，我们会因此变得越发强大。', `FemaleText_loc5`='我們會渡過這些難關，並且變得更加堅強。', `FemaleText_loc7`='Estas penurias pasarán y nos harán más fuertes.' WHERE `ID`=65456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네가 우릴 도와줄 거라 믿어 의심치 않네.', `FemaleText_loc4`='我相信你能帮助我们。', `FemaleText_loc5`='我相信你有辦法幫助我們。', `FemaleText_loc7`='Estoy segura de que podrás ayudarnos.' WHERE `ID`=65457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을이 힘을 되찾은 것은 자네 덕분일세!', `FemaleText_loc4`='是你帮这村庄找回了力量！', `FemaleText_loc5`='多虧了你，這村子又找回了他的力量!', `FemaleText_loc7`='¡Gracias a ti esta aldea ha recuperado su fuerza!' WHERE `ID`=65458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕에 맞서 들고일어나는 마을은 우리가 끝이 아닐 걸세!', `FemaleText_loc4`='不会只有我们一个村庄挺身对抗雷电之王！', `FemaleText_loc5`='我們不會是唯一起來對抗雷王的村子!', `FemaleText_loc7`='¡No seremos la única aldea que se alza contra el Rey del Trueno!' WHERE `ID`=65459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어부를 사귀어 두면 좋다네. 절대 배고플 일이 없거든!', `FemaleText_loc4`='和渔夫交朋友总是好事。你永远也不会挨饿！', `FemaleText_loc5`='和漁夫成為朋友永遠是個好主意。你永遠不愁肚子餓!', `FemaleText_loc7`='Es una buena idea trabar amistad con un pescador. ¡Nunca se pasa hambre!' WHERE `ID`=65460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍하오! 잔달라를 우리가 대체 어떻게 이긴단 말이오?', `MaleText_loc4`='这太可怕了！我们怎样才能打败赞达拉？', `MaleText_loc5`='這真是太糟糕了!我們哪有辦法能打敗贊達拉?', `MaleText_loc7`='¡Esto es terrible! ¿Cómo podremos derrotar a los Zandalari?' WHERE `ID`=65461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 작은 마을일 뿐이오... 우리가 아무리 발버둥 친다 해도 천둥왕의 군대을 꺾을 수 있겠소?', `MaleText_loc4`='我们只是个不起眼的小村庄……我们该怎么做才能打败雷电之王的军队？', `MaleText_loc5`='我們不過是個小村子...我們哪有可能擊敗雷王的軍隊?', `MaleText_loc7`='Solo somos una pequeña aldea... ¿Qué podemos hacer contra el ejército del Rey del Trueno?' WHERE `ID`=65462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머릿수로 상대도 안 되오! 이건 미친 짓이오!', `MaleText_loc4`='他们人太多了！这简直疯狂！', `MaleText_loc5`='他們的數量太多了!這太瘋狂了!', `MaleText_loc7`='¡Nos superan en número! ¡Esto es una locura!' WHERE `ID`=65463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침략자들을 꺾을 수 있을 줄 알았소!', `MaleText_loc4`='我早知道我们能打败入侵者！', `MaleText_loc5`='我就知道我們能擊敗入侵者!', `MaleText_loc7`='¡Sabía que podíamos derrotar a los invasores!' WHERE `ID`=65464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전에는 이상한 말을 하긴 했지만, 당신의 능력을 한 순간도 의심한 적이 없소!', `MaleText_loc4`='不管我以前说过什么，我从没怀疑过你的能力！', `MaleText_loc5`='儘管我說過那些話，但我從來不懷疑你的能力!', `MaleText_loc7`='No importa lo que haya podido decir antes. ¡Nunca dudé de tu capacidad!' WHERE `ID`=65465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 놈들, 우릴 얕잡아 본 게 실수였소!', `MaleText_loc4`='赞达拉决不该低估我们！', `MaleText_loc5`='贊達拉不該低估我們的能力!', `MaleText_loc7`='¡Los Zandalari no deberían habernos subestimado!' WHERE `ID`=65466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을은 평소에 정말 평화로워요.', `FemaleText_loc4`='这个村庄一向宁静怡人。', `FemaleText_loc5`='這村子通常是那麼的和平。', `FemaleText_loc7`='Normalmente esta aldea es muy tranquila.' WHERE `ID`=65467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도슈처럼 완고한 사람도 결국은 변하기 마련이죠.', `FemaleText_loc4`='改变是难以避免的，即便是对于像杜术这样的老顽固来说也是一样。', `FemaleText_loc5`='就連對道舒那麼頑固的人來說，改變也是不可避免的。', `FemaleText_loc7`='El cambio es inevitable, hasta para alguien tan testarudo como Doshu.' WHERE `ID`=65468;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 딸애한테는 정신력과 끈기가 있어요! 딸애보다는 오히려 남편이 더 걱정인걸요.', `FemaleText_loc4`='我的女儿浑身充满了志气和坚毅！她比我丈夫还让我省心。', `FemaleText_loc5`='我的女兒有堅毅的精神!擔心她還不如擔心我丈夫。', `FemaleText_loc7`='¡Mi hija tiene espíritu y perseverancia! Me preocupa más mi marido que ella.' WHERE `ID`=65469;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='끝났네. 해냈군, $p!', `FemaleText_loc4`='完成了。你做到了，$p！', `FemaleText_loc5`='結束了。你成功了，$p!', `FemaleText_loc7`='Se acabó. ¡Lo conseguiste, $p!' WHERE `ID`=65470;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 이젠 속임수는 이걸로 충분하네.', `FemaleText_loc4`='欺骗到此为止吧。', `FemaleText_loc5`='終於不用再隱瞞了。', `FemaleText_loc7`='Y ahora, basta de engaños.' WHERE `ID`=65471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑네. 난 릴리안이라고 하네. 내가 그 칼날을 가져가도 괜찮겠나?', `FemaleText_loc4`='你好，我叫莉莉安。你不会介意我拿走这两柄利刃，对吧？', `FemaleText_loc5`='哈囉，我的名字是莉莉安。你不介意我拿走這些武器吧?', `FemaleText_loc7`='Hola, me llamo Lilian. No te importa si me quedo con estas espadas, ¿verdad?' WHERE `ID`=65472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두건 쓴 성전사가 칼날에 깊이 찔린 종교재판관의 시체를 내려다봅니다.', `FemaleText_loc4`='蒙面的十字军战士凝视着检查官被刀片刺穿的尸体。', `FemaleText_loc5`='戴頭罩的十字軍睥睨著高階審判官那劍痕累累的屍體。', `FemaleText_loc7`='La cruzada encapuchada echa un vistazo al cadáver desgarrado del alto inquisidor.' WHERE `ID`=65473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...아야라고?', `MaleText_loc4`='……哎呦？', `MaleText_loc5`='...好痛?', `MaleText_loc7`='¿...Ay?' WHERE `ID`=65474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네... 아버지. 죄송하지만 여기에 제 머리가 끼여서 말이죠.', `MaleText_loc4`='是的……爸爸。对不起，我脑袋被那东西给控制住了。', `MaleText_loc5`='是的...老爸。抱歉我讓我的頭整個被那東西給迷住了。', `MaleText_loc7`='Sí... papá. Perdón por dejar que esa cosa me atrapara la cabeza.' WHERE `ID`=65475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내... 아들의 머리에서... 떨어져!', `MaleText_loc4`='滚出……我儿子……的脑袋！', `MaleText_loc5`='滾...出...我孩子的...腦袋!', `MaleText_loc7`='¡Sal... de la cabeza... de mi hijo!' WHERE `ID`=65476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 이 정도쯤이야 시작에 불과하죠. 우리가 누군지 잊은 겁니까?', `MaleText_loc4`='嗯，那至少是个开始。你记得自己是谁吗？', `MaleText_loc5`='嗯，那至少是個開始。你記得你是誰嗎?', `MaleText_loc7`='Bueno, es un comienzo. ¿Recuerdas quién eres?' WHERE `ID`=65477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 바로 정신력이었지. 그게 차이란다. 그리고 걱정하지 말거라. 큰 사냥감을 잡는 게 쉽다면 다들 잡고 다닐 것 아니겠니.', `MaleText_loc4`='那是精神控制，儿子。是有区别的。别担心。如果“王牌狩猎”那么容易，那就人人都能做到了。', `MaleText_loc5`='是心靈控制，孩子。那有點不一樣。別擔心。如果大狩獵遊戲有這麼簡單，每個人都能做到了。', `MaleText_loc7`='Era control mental, hijo. No es lo mismo. No te preocupes; si la caza mayor fuera fácil, todo el mundo lo haría.' WHERE `ID`=65478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''안개 속의 호젠''을 듣고 싶습니다.', `MaleText_loc4`='雾锁猢狲。', `MaleText_loc5`='霧中的猴人。', `MaleText_loc7`='Hozen en la niebla.', `FemaleText_loc1`='''안개 속의 호젠''을 듣고 싶어요.', `FemaleText_loc4`='雾锁猢狲。', `FemaleText_loc5`='霧中的猴人。', `FemaleText_loc7`='Hozen en la niebla.' WHERE `ID`=65479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''물고기 이야기''를 듣고 싶습니다.', `MaleText_loc4`='锦鱼传。', `MaleText_loc5`='錦魚人的故事。', `MaleText_loc7`='Cuentos de peces.', `FemaleText_loc1`='''물고기 이야기''를 듣고 싶어요.', `FemaleText_loc4`='锦鱼传。', `FemaleText_loc5`='錦魚人的故事。', `FemaleText_loc7`='Cuentos de peces.' WHERE `ID`=65480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''모구의 검은 심장''을 듣고 싶습니다.', `MaleText_loc4`='魔古的黑心。', `MaleText_loc5`='魔古的黑心。', `MaleText_loc7`='El corazón oscuro de los mogu.', `FemaleText_loc1`='''모구의 검은 심장''을 듣고 싶어요.', `FemaleText_loc4`='魔古的黑心。', `FemaleText_loc5`='魔古的黑心。', `FemaleText_loc7`='El corazón oscuro de los mogu.' WHERE `ID`=65481;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 만나서 반갑네, $n. 자네가 오지 않을까 봐 잠깐 걱정이 됐다네.$B$B이제 마무리를 해볼까? 붉은십자군은 스스로 멸망하진 않을 게 확실하니까 말이네.', `FemaleText_loc4`='很高兴再次见到你，$n。我还担心你不会来。$B$B让我们完成这个任务吧？血色十字军已经证明，它不会自行了结。', `FemaleText_loc5`='很高興再次見到你，$n。有段時間，我擔心你不會過來了。$B$B讓我們把這件事給了結掉吧，如何?顯然血色十字軍是不會自我了斷的。', `FemaleText_loc7`='Me alegro de volver a verte, $n. Durante un instante, me preocupaba que no vinieses.$B$BAcabemos con esto, ¿de acuerdo? La Cruzada Escarlata ha dado sobradas muestras de que no va a disolverse por sí sola.' WHERE `ID`=65482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''사마귀 군단의 심장''을 듣고 싶습니다.', `MaleText_loc4`='螳螂群之心。', `MaleText_loc5`='螳族之心', `MaleText_loc7`='Corazón del enjambre mántide.', `FemaleText_loc1`='''사마귀 군단의 심장''을 듣고 싶어요.', `FemaleText_loc4`='螳螂群之心。', `FemaleText_loc5`='螳族之心', `FemaleText_loc7`='Corazón del enjambre mántide.' WHERE `ID`=65483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''무엇이 싸울 가치가 있는가''를 듣고 싶습니다.', `MaleText_loc4`='为何而战。', `MaleText_loc5`='什麼才值得一戰。', `MaleText_loc7`='Por qué merece la pena luchar.', `FemaleText_loc1`='''무엇이 싸울 가치가 있는가''를 듣고 싶어요.', `FemaleText_loc4`='为何而战。', `FemaleText_loc5`='什麼才值得一戰。', `FemaleText_loc7`='Por qué merece la pena luchar.' WHERE `ID`=65484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''야운골의 노래''를 듣고 싶습니다.', `MaleText_loc4`='野牛人之歌。', `MaleText_loc5`='揚古之歌。', `MaleText_loc7`='La canción de los yaungol.', `FemaleText_loc1`='''야운골의 노래''를 듣고 싶어요.', `FemaleText_loc4`='野牛人之歌。', `FemaleText_loc5`='揚古之歌。', `FemaleText_loc7`='La canción de los yaungol.' WHERE `ID`=65485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''샤오하오의 일곱 짐''을 듣고 싶습니다.', `MaleText_loc4`='少昊的七罪责。', `MaleText_loc5`='紹昊背負的七件重擔。', `MaleText_loc7`='Las siete cargas de Shaohao.', `FemaleText_loc1`='''샤오하오의 일곱 짐''을 듣고 싶어요.', `FemaleText_loc4`='少昊的七罪责。', `FemaleText_loc5`='紹昊背負的七件重擔。', `FemaleText_loc7`='Las siete cargas de Shaohao.' WHERE `ID`=65486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''리우 랑의 노래''를 듣고 싶습니다.', `MaleText_loc4`='刘浪之歌。', `MaleText_loc5`='劉浪的民謠。', `MaleText_loc7`='La balada de Liu Lang.', `FemaleText_loc1`='''리우 랑의 노래''를 듣고 싶어요.', `FemaleText_loc4`='刘浪之歌。', `FemaleText_loc5`='劉浪的民謠。', `FemaleText_loc7`='La balada de Liu Lang.' WHERE `ID`=65487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장벽 너머에 이렇게 많은 지식이 잠들어 있을 줄 누가 알았겠나? 게다가 아직도 추가할 수 있는 게 많다네.$b$b이 땅을 탐험하면서 혹시 흥미로운 물건이 없는지 눈여겨보게. 우리 과거에 대해 더 알 수 있을지도 모르니까. 역사를 조금씩 짜 맞추다 보면 이야기를 한두 편 들려줄 수 있게 될지도 모르지.', `MaleText_loc4`='谁知道在这些厚墙内隐藏着多少知识呢。我们还能让这座宝库变得更加宏大。$b$b在你探索这片土地时，留心寻找那些不同寻常的物品，或许能帮我们加深对过往的了解。当你对我们的历史有足够的认识时，我就能与你分享一两个故事。', `MaleText_loc5`='誰想得到會有這麼多知識隱藏在這裡面。而我們有許多資料可以添加到這裡面。$b$b在你探索我們土地時，多注意能幫我們學習更多歷史的有意義題材。將足夠的歷史串連起來後，我或許就能跟你分享幾個完整的故事。', `MaleText_loc7`='¿Quién nos iba a decir que habría tanta sabiduría escondida tras estos muros? Y aún podemos añadir muchas cosas.$b$bA medida que explores nuestra tierra, busca objetos interesantes que puedan ayudarnos a aprender cosas sobre nuestra historia. Si reúnes los fragmentos suficientes, puede que te cuente alguna historia.' WHERE `ID`=65488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 탐험가를 만나니 좋군! 새로운 땅을 발견하면 바로 요새와 사원부터 찾는 이들이 있다네.$b$b난 아닐세.$b$b한 민족을 이해하려면, 발품을 팔아야 한다네. 가세, 나와 함께 이 땅을 걸으세! 본토의 판다렌이 진정 소중히 여기는 것이 무엇인지 알아 보세.$b$b이것이 바로 방랑자의 도리지.', `MaleText_loc4`='能见到另一位探险者真是太好了！当某些人发现一片新土地时，他们总会立刻动身前往堡垒和寺院。$b$b我跟他们可不一样。$b$b要想深入了解一个地方的人，你就必须脚踏实地。来吧，随我四处逛逛！让我们看看这些陆地熊猫人真正重视的是什么。$b$b这才是云游者之道。', `MaleText_loc5`='能見到另一個探險家真好!有些人在發現一塊新的土地時，他們會立刻尋找堡壘或是寺廟。$b$b我不是。$b$b要想了解一群人，你必須不辭辛勞才行。來吧，和我一起在這片土地上走走!讓我們看看這些本土的熊貓人真正重視的是什麼。$b$b這就是浪人之道。', `MaleText_loc7`='¡Me gusta conocer a otros exploradores! Hay gente que, al descubrir una tierra nueva, va directa a las fortalezas y los templos.$b$bYo no.$b$bPara conocer a la gente hay que ensuciarse los pies. Ven, ¡recorre esta tierra conmigo! Veamos qué es lo que más valoran los pandaren del continente.$b$bEs la filosofía del viajero.' WHERE `ID`=65489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 조카 리 리는 판다리아를 탐험하고 싶어 몸이 근질근질한 모양일세. 하지만 이곳저곳 무작정 돌아다녀서는 절대로 새 땅에 대해 알 수 없지. 만나는 모든 사람과 대화를 나누고, 한 장소가 자기 영혼의 일부가 될 때까지 그곳을 경험해야 한다네.$b$b그게 바로 방랑자의 도리거든!', `MaleText_loc4`='我的侄女丽丽无法静下心来探索潘达利亚。但如果只是蜻蜓点水般的东游西逛，是不可能了解一片全新土地的。重要的是，要跟你遇见的每一个人交谈，用心体会每一个地方，直到它已深入你的灵魂。$b$b这才是云游者之道！', `MaleText_loc5`='我的姪女莉莉非常沒有耐心，急著想要探索潘達利亞。但隨便地到處亂跑是無法讓你了解一塊新土地的。和每個你遇到的人交談、體驗一個地方直到它成為你靈魂的一部分是很重要的。$b$b這就是浪人之道!', `MaleText_loc7`='Mi sobrina Li Li está muy impaciente por explorar Pandaria, pero no se conoce una tierra nueva corriendo de un lado a otro. Es importante hablar con todo el mundo, experimentar un lugar hasta que se convierta en parte de tu alma.$b$bEs la filosofía del viajero.' WHERE `ID`=65490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리 리는 왜 내가 항상 각지의 술을 맛보는지 이해를 못 한다네. 하지만 내 경험으로는, 뭘 마시는지 보면 어떤 사람인지를 알 수 있지.$b$b본토 판다렌의 맥주를 맛본 적 있는가? 색이 어둡고 맛이 산뜻하지. 한 모금만 마시면 천천히 음미하면서 마시는 술이란 걸 알 수 있네. 서두르지 않으며, 친구들과 함께하는 시간을 즐기는 민족의 술이지.$b$b자네는 뭘 마시는가, $c? 그리고 그것이 자네에 대해 무엇을 말해 주는가?', `MaleText_loc4`='丽丽不明白为什么我总是停下来品尝各地的美酒。可根据我的经验，一个人群的性格，就体现在他们喝的东西里！$b$b你尝过大陆熊猫人的啤酒了吗？口感既清冽，又醇厚。只需品上一口，你就会知道，这酒是经由悉心慢酿而成。喝这酒的人，也必然是淡然恬静，不慌不忙，乐于与朋友分享美好的时光。$b$b你喝什么呢，$c？它又如何反映着你的性格，嗯？', `MaleText_loc5`='莉莉不了解為什麼我總是停下來品嚐當地的酒。但在我的經驗之中，你從人們喝的東西就能學到關於他們的許多事!$b$b你有試過本土熊貓人的酒嗎?非常清新，顏色非常深。只喝一小口你就知道那些酒得慢慢品嚐。這就是步調緩慢的人所喝的酒，他們樂於跟他們的朋友共度時間。$b$b你都喝什麼東西，$c?它能告訴我什麼關於你的事，嗯?', `MaleText_loc7`='Li Li no entiende por qué siempre me paro a probar la cerveza local, pero he comprobado que lo que bebe la gente dice mucho de ella.$b$b¿Has probado la cerveza de los pandaren del continente? Muy amarga, muy oscura. Un sorbo y ya sabes que la han preparado para beberla despacio. Es la bebida de gente que no tiene prisa, que disfruta pasando el rato con sus amigos.$b$b¿Tú qué bebes, $c? ¿Y qué diría tu bebida de ti?' WHERE `ID`=65491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다렌 농부들은 참 재미난 친구들일세! 서로 유대가 아주 끈끈하지. 마을 사람끼리 서로 다 아니 말일세.$b$b칼림도어나 동부 왕국의 대도시와는 전혀 달라.', `MaleText_loc4`='这些熊猫人农夫真是一群有趣的家伙！这是个紧密相连的社区。人人都熟悉彼此。$b$b跟卡利姆多或东部王国的那些大城市很不一样！', `MaleText_loc5`='這些熊貓人農夫是群有趣的人!一個非常緊密聯繫的群體，每個人都認識彼此。$b$b這和卡林多與東部王國的大城市很不一樣。', `MaleText_loc7`='¡Estos granjeros pandaren son de lo más entretenidos! Una comunidad muy cercana. Todo el mundo se conoce.$b$bEs muy distinto de las grandes ciudades de Kalimdor o los Reinos del Este.' WHERE `ID`=65492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 왜 늘 그렇게 급한가, $n? 경험을 쌓는 데 급급해서는, 도움이 필요한 이를 미친 듯이 찾아 다니는 것 같네.$b$b삶이란 그저 채우기만 하면 되는 잔이 아니라네! 잠시 머물면서 그곳을 즐겨 보게나!', `MaleText_loc4`='你为何总是这么行色匆匆呢，$n？你不断地帮助一个又一个陌生人，醉心于丰富自己的经验。$b$b人生不只是一个供你装满水的玻璃杯，去享受你已发现的佳境吧！', `MaleText_loc5`='為什麼你總是那麼匆忙，$n?好像你瘋狂地衝刺，從這個需要幫助的陌生人跑到另一個，就只為了得到新的經驗一樣。$b$b生活不單純只是一個被你裝得滿滿的杯子!停下來一下，欣賞你發現的地方!', `MaleText_loc7`='¿Por qué siempre tienes prisa, $n? Es como si corrieras de un desconocido en apuros a otro, todo por vivir nuevas experiencias.$b$b¡La vida no es solamente un vaso que hay que llenar! Quédate un rato y disfruta de los lugares que has descubierto.' WHERE `ID`=65493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가족은 판다리아를 떠나 세상을 탐험하려고 유랑도에 올랐지. 여러 세대 전의 일이라네.$b$b그런데 이곳 판다리아에도 스톰스타우트 가문 사람들이 있다는 걸 알았지 뭔가! 오래전 잃어버린 가족이지. 어떤 사람들일까? 나처럼 아직도 양조를 하고 있을까? 자네와 나처럼 모험가일까?', `MaleText_loc4`='我的家人离开潘达利亚大陆去探索迷踪岛以外的世界。这是几代人之前的事。$b$b但是我知道潘达利亚这里还有其他风暴烈酒家族的成员！我失散已久的家人。他们长什么样子？他们还像我一样在酿酒吗？他们是和你我一样的冒险家吗？', `MaleText_loc5`='我的家族離開了潘達利亞大陸，前往探索漂流島上的世界。那是好幾代以前的事了。$b$b但是我發現還有其他的風暴烈酒族人，就在這，在潘達利亞!我失落多年的家族。他們是怎麼樣的人呢?他們還有跟我一樣在釀酒嗎?他們跟你我一像是探險家嗎?', `MaleText_loc7`='Mi familia abandonó Pandaria para explorar el mundo a lomos de La Isla Errante. Hace muchas generaciones de eso.$b$bPero he descubierto que hay más Cerveza de Trueno, ¡aquí, en Pandaria! Mi antigua familia. ¿Cómo serán? ¿Aún prepararán cerveza, como yo? ¿Serán aventureros, como tú y como yo?' WHERE `ID`=65494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계곡에서 시간을 보내다 보면 동네 사람들과 친해질지도 모른다네. 언젠가 밭 한 뙈기를 장만해서 정착하게 될지도 모르지.$b$b상상해 보게. 세파에 찌든 $c인 자네가 정착해서 밭을 일구는 모습을!$b$b<첸이 눈을 감고는 배 속에서 나오는 웃음을 웃습니다.>', `MaleText_loc4`='如果你在这谷里待足够长的时间，也许你能与所有当地人交上朋友。甚至有一天，你可以安顿下来，拥有属于自己的一亩三分地。$b$b想象一下，你这厌倦尘世的$c，却在这里安顿下来，管理农场！$b$b<陈闭上双眼，捧腹大笑。>', `MaleText_loc5`='如果你待在谷中夠久，也許你能跟所有當地人成為朋友。或許甚至有一天你能在屬於你自己的農地安頓下來。$b$b想像一下，你這為世界奔波勞累的$c，安頓下來管理一個農場!$b$b<老陳閉上了他的眼睛捧腹大笑。>', `MaleText_loc7`='Si pasaras tiempo suficiente en este valle, a lo mejor podrías trabar amistad con todos los vecinos. Incluso podrías asentarte algún día en tu propia granja.$b$bImagínatelo: tú, $gel:la; $c trotamundos, ¡sentando la cabeza y llevando una granja!$b$b<Chen cierra los ojos y se ríe alegremente.>' WHERE `ID`=65495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방랑자의 도리를 받아들이게! 그건 행동이라기보다는 마음가짐일세.$b$b자네가 만나는 사람 하나하나가 이야기고, 가는 장소 하나하나가 모험이지. 마시는 술은 모두 평생 최고의 술이고.$b$b그 정도면 괜찮은 삶 아닌가?', `MaleText_loc4`='拥抱云游者之道吧！与其说这是一个行动过程，不如说是一种态度。$b$b你遇到的每一个人都是一个故事。你去过的每一个地方都是一次冒险奇遇。你喝的每一杯酒都是前所未见的美酒。$b$b这种生活还算不错，对吧？', `MaleText_loc5`='遵循浪人之道!它不是一種行為準則，而是一種態度。$b$b每個你遇到的人都是一個故事。每個你到過的地方都是一段冒險。每種你喝過的飲料都是最棒的。$b$b這種生活還不賴，不是嗎?', `MaleText_loc7`='¡Acepta la filosofía del errante! No es tanto un plan de acción como una actitud.$b$bCada persona que conoces es una historia. Cada sitio que visitas es una aventura. Cada trago que tomas es el mejor que has probado.$b$bNo es mala vida, ¿verdad?' WHERE `ID`=65496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<첸이 고개를 끄덕여 알은척을 하지만, 왠지 시무룩해 보입니다.>', `MaleText_loc4`='<陈点头表示同意你的观点，但他看上去却一反常态地沉着脸。>', `MaleText_loc5`='<老陳點頭對你打招呼，但看起來跟平時不一樣地繃著臉。>', `MaleText_loc7`='<Chen te saluda con la cabeza, pero tiene un aspecto inusualmente triste.>' WHERE `ID`=65497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 세계에 갔던 탓에 일시적으로 |cFFFF0000|Hspell:117723|h[부서진 영혼]|h|r 상태가 되었습니다! 부서진 영혼 상태가 끝나기 전에 다시 영혼의 세계에 들어가려고 하면 즉시 죽음을 맞게 됩니다!', `MaleText_loc4`='灵魂世界之旅暂时在你身上留下了|cFFFF0000|Hspell:117723|h[脆弱灵魂]|h|r的效果！如果你在脆弱灵魂效果结束之前再次试图前往灵魂世界，你将立即消亡！', `MaleText_loc5`='進出靈魂世界使你暫時獲得|cFFFF0000|Hspell:117723|h[虛弱靈魂]|h|r狀態!如果你在虛弱靈魂結束前再度進入靈魂世界，你將會立刻死亡!', `MaleText_loc7`='Viajar por el mundo de los espíritus te ha dejado temporalmente con el |cFFFF0000|Hspell:117723|h[Alma endeble]|h|r. Si intentas viajar al mundo de los espíritus otra vez antes de que Alma endeble expire, ¡morirás al instante!' WHERE `ID`=65498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신성한 물이 더럽혀졌지만, 아직 희망은 있습니다. 우리 민족에 전해 오는 고대의 의식은, 아무리 강한 타락도 정화할 수 있습니다. 물이 정화되면, 물을 타락시킨 자의 힘도 약해지지요.', `MaleText_loc4`='这些神圣之水被污染了，但希望仍在。即便是面对如此巨大的腐蚀之力，我们古老的仪式也能坚持完成净化。当水复原后，污染之人的力量就会衰退。', `MaleText_loc5`='雖然這神聖的水被污染了，但希望並沒有因此喪失。就算對著強大的腐化，我們古老的祭儀依然能承受這種污染並加以淨化。當水回復清淨時，其污染者的力量也會衰減。', `MaleText_loc7`='El agua sagrada está corrupta, pero aún queda esperanza. Nuestros antiguos rituales perduran y purifican, incluso frente a una corrupción tan grande. A medida que el agua se recupera, la fuerza de aquellos que la contaminan se debilita.' WHERE `ID`=65499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물은 공포를 먹고 살지만, 우리는 공포를 느끼지 않습니다. 굳이 이곳을 정화해 주실 필요는 없으니, 의식을 중단하십시오.', `MaleText_loc4`='这种生物也许能从恐惧中汲取力量，但我们心中可没有恐惧。停止你的仪式，因为我们不需要别人帮忙净化这个地方。', `MaleText_loc5`='這生物或許以恐懼為食，但我們心中沒有絲毫恐懼讓他吞噬。停止你的祭儀，因為我們不需要任何幫助就能淨化這個地方。', `MaleText_loc7`='Es posible que este ser se alimente del miedo, pero nosotros no se lo daremos. Interrumpan su ritual; no necesitamos ayuda para purificar este lugar.', `FemaleText_loc1`='이 괴물은 공포를 먹고 살지만, 우리는 공포를 느끼지 않아요. 굳이 이곳을 정화해 주실 필요는 없으니, 의식을 중단하세요.', `FemaleText_loc4`='这种生物也许能从恐惧中汲取力量，但我们心中可没有恐惧。停止你的仪式，因为我们不需要别人帮忙净化这个地方。', `FemaleText_loc5`='這生物或許以恐懼為食，但我們心中沒有絲毫恐懼讓他吞噬。停止你的祭儀，因為我們不需要任何幫助就能淨化這個地方。', `FemaleText_loc7`='Es posible que este ser se alimente del miedo, pero nosotros no se lo daremos. Interrumpan su ritual; no necesitamos ayuda para purificar este lugar.' WHERE `ID`=65500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의식을 중단하면 재개할 수 없으며, 그렇게 되면 타락이 온전한 힘을 쓸 수 있습니다. 그 용기는 감탄스럽지만, 당신이 실패하면 우리는 모두 파멸할 것입니다. 당신이 무슨 말을 한 건지 알고 있습니까? 그 결과를 감당할 수 있습니까?', `MaleText_loc4`='一旦停止这个仪式，我们将不能重新开始，腐蚀会保有全部力量。你的勇气令人钦佩，但如果你失败了，我们将无力回天。你明白你在做什么吗？你清楚后果吗？', `MaleText_loc5`='一旦祭儀停止，我們就無法重新開始，這裡的腐化會擁有完整的力量。你的勇氣令人讚嘆，但如果你失敗了，我們全都要毀滅。你知道自己在要求什麼嗎?你能了解它的後果嗎?', `MaleText_loc7`='Si interrumpimos el ritual, no podremos retomarlo y la corrupción seguirá intacta. Tu valor es admirable, pero si fracasan, nos habrán condenado a todos. ¿Entiendes lo que pides? ¿Entiendes las consecuencias?' WHERE `ID`=65501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역사적인 순간이군요, $n. 문 뒤에는 뭐가 있을까요?', `MaleText_loc4`='这是一个历史性的时刻，$n。你觉得在门外有什么在等着我们？', `MaleText_loc5`='這是歷史性的一刻，$n。你認為門的另一邊會有些什麼?', `MaleText_loc7`='Es un momento histórico, $n. ¿Qué crees que hay detrás de las puertas?' WHERE `ID`=65502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 "네 주인이 누구지?" 하면 "쇼너프요!" 하는 거다?', `MaleText_loc4`='当我问：“谁是主人？”你回答：“烁奴夫！”', `MaleText_loc5`='當我說:「誰是主人?」時，你們要回答:「修努夫!」。', `MaleText_loc7`='Cuando yo digo "¿Quién es el maestro?", tú respondes "¡Shonuf!".' WHERE `ID`=65503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 너무 멋져!', `MaleText_loc4`='我燃起了战欲！', `MaleText_loc5`='我身上有亮光!', `MaleText_loc7`='¡Tengo el resplandor!' WHERE `ID`=65504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 죽음을 맞이해라.', `MaleText_loc4`='来，面对死亡吧。', `MaleText_loc5`='來吧，面對你的死亡。', `MaleText_loc7`='Ven y enfréntate a la muerte.' WHERE `ID`=65505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 갑옷을 전리품으로 차지할 것이다!', `MaleText_loc4`='我要把你的护甲当成战利品！', `MaleText_loc5`='你的護甲會成為我的戰利品!', `MaleText_loc7`='¡Me llevaré tu armadura como trofeo!' WHERE `ID`=65506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_bomb_05.blp:20|t파괴자 키프틸락이 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:107268|h[파괴 공작]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_bomb_05.blp:20|t破坏者吉普提拉克对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:107268|h[破坏]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_bomb_05.blp:20|t『破壞者』奇普提拉克施放|cFFFF0000|Hspell:107268|h[破壞炸彈]|h|r在|cFFFF0000$n|r身上!', `MaleText_loc7`='|TInterfaceIconsinv_misc_bomb_05.blp:20|t¡El saboteador Kip''tilak lanza |cFFFF0000|Hspell:107268|h[Sabotaje]|h|r sobre |cFFFF0000$n|r!' WHERE `ID`=65507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음이 네 눈앞에 있다.', `MaleText_loc4`='你死到临头了。', `MaleText_loc5`='你就站在死神面前。', `MaleText_loc7`='La muerte te espera.' WHERE `ID`=65508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:107268|h[파괴 공작]|h|r에 당했습니다!', `MaleText_loc4`='你已被|cFFFF0000|Hspell:107268|h[破坏]|h|r击中！', `MaleText_loc5`='你被綁上|cFFFF0000|Hspell:107268|h[破壞炸彈]|h|r了!', `MaleText_loc7`='¡Te han |cFFFF0000|Hspell:107268|h[saboteado]|h|r!', `FemaleText_loc1`='당신은 |cFFFF0000|Hspell:107268|h[파괴 공작]|h|r에 당했습니다!', `FemaleText_loc4`='你已被|cFFFF0000|Hspell:107268|h[破坏]|h|r击中！', `FemaleText_loc5`='你被綁上|cFFFF0000|Hspell:107268|h[破壞炸彈]|h|r了!', `FemaleText_loc7`='¡Te han |cFFFF0000|Hspell:107268|h[saboteado]|h|r!' WHERE `ID`=65509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴자 키프틸락이 연쇄 폭발을 일으킵니다!', `MaleText_loc4`='破坏者吉普提拉克引发了一连串的爆炸！', `MaleText_loc5`='『破壞者』奇普提拉克引發了一連串的爆炸!', `MaleText_loc7`='¡El saboteador Kip''tilak detona una serie de explosiones!' WHERE `ID`=65510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 보니 반갑네.', `MaleText_loc4`='很高兴在这里见到你，孩子。', `MaleText_loc5`='很高興在這裡看到你，孩子。', `MaleText_loc7`='Me alegro de verte, joven.' WHERE `ID`=65511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예. 공포를 이기기 위해서는, 눈도 깜짝하지 않고 공포를 똑바로 쳐다보아야 합니다.', `MaleText_loc4`='我做的到。战胜恐惧的方法便是直视它，坚定不移，毫不动摇。', `MaleText_loc5`='我了解。擊敗恐懼的唯一方法就是正視它，毫不退卻，毫不動搖。', `MaleText_loc7`='Lo entiendo. La forma de derrotar al miedo es mirarle directamente a los ojos, sin parpadear, sin inmutarse.', `FemaleText_loc1`='네. 공포를 이기기 위해서는, 눈도 깜짝하지 않고 공포를 똑바로 쳐다보아야 해요.', `FemaleText_loc4`='我做的到。战胜恐惧的方法便是直视它，坚定不移，毫不动摇。', `FemaleText_loc5`='我了解。擊敗恐懼的唯一方法就是正視它，毫不退卻，毫不動搖。', `FemaleText_loc7`='Lo entiendo. La forma de derrotar al miedo es mirarle directamente a los ojos, sin parpadear, sin inmutarse.' WHERE `ID`=65512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_parry.blp:20|t사부 스노우드리프트가 |cFFFF0000|Hspell:106454|h[막기 자세]|h|r를 취합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_parry.blp:20|t雪流大师启用他的|cFFFF0000|Hspell:106454|h[招架姿态]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_parry.blp:20|t雪迅大師擺出了|cFFFF0000|Hspell:106454|h[招架姿態]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_parry.blp:20|t¡El maestro Ventisca Algente activa su |cFFFF0000|Hspell:106454|h[Estilo de parada]|h|r!' WHERE `ID`=65513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 가호가 따르길, 용감한 이여.', `MaleText_loc4`='愿灵魂与你同在，勇者。', `MaleText_loc5`='願魂靈們與你同在，勇敢的人。', `MaleText_loc7`='Que los espíritus te guíen, valiente.' WHERE `ID`=65514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_earthbind.blp:20|t사부 스노우드리프트가 |cFFFF0000|Hspell:106434|h[선풍각]|h|r을 사용합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_earthbind.blp:20|t雪流大师使用他的|cFFFF0000|Hspell:106434|h[飓风腿]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_earthbind.blp:20|t雪迅大師使出了|cFFFF0000|Hspell:106434|h[龍捲踢]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_earthbind.blp:20|t¡El maestro Ventisca Algente utiliza su |cFFFF0000|Hspell:106434|h[Patada de tornado]|h|r!' WHERE `ID`=65515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_hunter_sickem.blp:20|t사부 스노우드리프트가 |cFFFF0000$n|r|1을;를; |cFFFF0000|Hspell:118961|h[추격]|h|r하려고 합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_hunter_sickem.blp:20|t雪流大师将目光转向了|cFFFF0000$n|r，开始|cFFFF0000|Hspell:118961|h[追逐]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_hunter_sickem.blp:20|t雪迅大師將他的注意力放在|cFFFF0000$n|r身上，開始|cFFFF0000|Hspell:118961|h[追擊]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_hunter_sickem.blp:20|t¡El maestro Ventisca Algente se fija en |cFFFF0000$n|r para |cFFFF0000|Hspell:118961|h[Perseguir]|h|r!' WHERE `ID`=65516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 봅시다!', `MaleText_loc4`='让我们弄清楚！', `MaleText_loc5`='讓我們試試吧!', `MaleText_loc7`='¡Averigüémoslo!', `FemaleText_loc1`='어디 한번 보죠!', `FemaleText_loc4`='让我们弄清楚！', `FemaleText_loc5`='讓我們試試吧!', `FemaleText_loc7`='¡Averigüémoslo!' WHERE `ID`=65517;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 이 정도면 꽤 괜찮겠군. 마치 나를 위해 준비된 것 같네.', `FemaleText_loc4`='很好，这些利刃无坚不摧。它们仿佛从始至终都是为我存在的。', `FemaleText_loc5`='是的，這些就行了。它們就好像跟我是天造地設的一樣。', `FemaleText_loc7`='Sí, estas valdrán. Dan la impresión de que estuviesen hechas para mí desde un principio.' WHERE `ID`=65518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 스노우드리프트가 당신을 |cFFFF0000|Hspell:118961|h[추격]|h|r하고 있습니다! 만약에 잡히면 |cFFFF0000|Hspell:106352|h[회오리 꽂기]|h|r 기술에 당하게 됩니다! 추격이 끝날 때까지 사부 스노우드리프트를 피해 도망다니십시오!', `MaleText_loc4`='雪流大师正在|cFFFF0000|Hspell:118961|h[追逐]|h|r你！如果被他抓住，他就会对你使用|cFFFF0000|Hspell:106352|h[狂风掼]|h|r！在追逐效果结束前，离雪流大师远点！', `MaleText_loc5`='雪迅大師正在|cFFFF0000|Hspell:118961|h[追擊]|h|r你!如果被他追上，他會對你使出他的絕招|cFFFF0000|Hspell:106352|h[龍捲摔]|h|r!逃離他直到追擊結束!', `MaleText_loc7`='¡El maestro Ventisca Algente te está |cFFFF0000|Hspell:118961|h[Persiguiendo]|h|r! Si te atrapa, utilizará su técnica |cFFFF0000|Hspell:106352|h[Embate de tornado]|h|r contra ti. ¡Aléjate del maestro Ventisca Algente hasta que Perseguir expire!', `FemaleText_loc1`='사부 스노우드리프트가 당신을 |cFFFF0000|Hspell:118961|h[추격]|h|r하고 있습니다! 만약에 잡히면 |cFFFF0000|Hspell:106352|h[회오리 꽂기]|h|r 기술에 당하게 됩니다! 추격이 끝날 때까지 사부 스노우드리프트를 피해 도망다니십시오!', `FemaleText_loc4`='雪流大师正在|cFFFF0000|Hspell:118961|h[追逐]|h|r你！如果被他抓住，他就会对你使用|cFFFF0000|Hspell:106352|h[狂风掼]|h|r！在追逐效果结束前，离雪流大师远点！', `FemaleText_loc5`='雪迅大師正在|cFFFF0000|Hspell:118961|h[追擊]|h|r你!如果被他追上，他會對你使出他的絕招|cFFFF0000|Hspell:106352|h[龍捲摔]|h|r!逃離他直到追擊結束!', `FemaleText_loc7`='¡El maestro Ventisca Algente te está |cFFFF0000|Hspell:118961|h[Persiguiendo]|h|r! Si te atrapa, utilizará su técnica |cFFFF0000|Hspell:106352|h[Embate de tornado]|h|r contra ti. ¡Aléjate del maestro Ventisca Algente hasta que Perseguir expire!' WHERE `ID`=65519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_weapon_hand_30.blp:20|t사부 스노우드리프트가 |cFFFF0000|Hspell:106853|h[염화의 주먹]|h|r을 사용합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_weapon_hand_30.blp:20|t雪流大师使出了|cFFFF0000|Hspell:106853|h[怒雷破]|h|r的招数！', `MaleText_loc5`='|TInterface\\Icons\\inv_weapon_hand_30.blp:20|t雪迅大師使用他的|cFFFF0000|Hspell:106853|h[狂拳連打]|h|r技能!', `MaleText_loc7`='|TInterfaceIconsinv_weapon_hand_30.blp:20|t¡El maestro Ventisca Algente utiliza su técnica |cFFFF0000|Hspell:106853|h[Puños de furia]|h|r!' WHERE `ID`=65520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비설이 |cFFFF0000|Hspell:106706|h[무쇠 회오리]|h|r로 쫓을 대상으로 |cFFFF0000$n|r|1을;를; 택합니다!', `FemaleText_loc4`='飞雪选择|cFFFF0000$n|r，作为用|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r追踪的目标！', `FemaleText_loc5`='飛雪選擇用|cFFFF0000|Hspell:106706|h[鋼刃迴旋斬]|h|r追擊|cFFFF0000$n|r!', `FemaleText_loc7`='¡Nieve Volátil persigue a |cFFFF0000$n|r con su |cFFFF0000|Hspell:106706|h[Acero giratorio]|h|r!' WHERE `ID`=65522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='비설이 |cFFFF0000|Hspell:|h[무쇠 회오리]|h|r 기술을 쓰며 당신을 쫓습니다! 다른 사람으로 목표를 바꿀 때까지 도망다니십시오!', `FemaleText_loc4`='飞雪正在用|cFFFF0000|Hspell:|h[钢铁漩涡]|h|r追赶你！在她选中其他人之前，离她远点！', `FemaleText_loc5`='飛雪正在用她的|cFFFF0000|Hspell:|h[鋼刃迴旋斬]|h|r追擊你!趕快逃跑，直到她選擇攻擊其他人!', `FemaleText_loc7`='Nieve Volátil te persigue con su técnica |cFFFF0000|Hspell:|h[Acero giratoriol]|h|r. ¡Huye hasta que elija a otro!' WHERE `ID`=65523;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\inv_sword_24.blp:20|t비설이 |cFFFF0000|Hspell:106706|h[무쇠 회오리]|h|r 기술을 씁니다!', `FemaleText_loc4`='|TInterface\\Icons\\inv_sword_24.blp:20|t飞雪使出了|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r的招数！', `FemaleText_loc5`='|TInterface\\Icons\\inv_sword_24.blp:20|t飛雪使出了|cFFFF0000|Hspell:106706|h[鋼刃迴旋斬]|h|r!', `FemaleText_loc7`='|TInterfaceIconsinv_sword_24.blp:20|t¡Nieve Volátil utiliza su técnica |cFFFF0000|Hspell:106706|h[Acero giratorio]|h|r!' WHERE `ID`=65524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 신입생이 당신을 |cFFFF0000|Hspell:106774|h[명예로운 도전]|h|r의 상대로 선택했습니다! 질 때까지 당신을 공격할 것입니다!', `MaleText_loc4`='影踪派新人将你选作|cFFFF0000|Hspell:106774|h[荣誉之战]|h|r的目标！在落败之前，他们会使出浑身解数来对付你！', `MaleText_loc5`='一個影潘學徒挑選你進行|cFFFF0000|Hspell:106774|h[光榮戰鬥]|h|r!他們會攻擊你直到被擊敗為止!', `MaleText_loc7`='¡Un novicio del Shadopan te ha elegido para un |cFFFF0000|Hspell:106774|h[Combate honorable]|h|r! Te atacará hasta derrotarte.', `FemaleText_loc1`='음영파 신입생이 당신을 |cFFFF0000|Hspell:106774|h[명예로운 도전]|h|r의 상대로 선택했습니다! 질 때까지 당신을 공격할 것입니다!', `FemaleText_loc4`='影踪派新人将你选作|cFFFF0000|Hspell:106774|h[荣誉之战]|h|r的目标！在落败之前，他们会使出浑身解数来对付你！', `FemaleText_loc5`='一個影潘學徒挑選你進行|cFFFF0000|Hspell:106774|h[光榮戰鬥]|h|r!他們會攻擊你直到被擊敗為止!', `FemaleText_loc7`='¡Un novicio del Shadopan te ha elegido para un |cFFFF0000|Hspell:106774|h[Combate honorable]|h|r! Te atacará hasta derrotarte.' WHERE `ID`=65525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t무기전문가 할란이 함께 싸울 동료 두 명을 부릅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t武器大师哈兰召唤了两名同伴加入战斗！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t武器大師哈倫召來兩名他的盟友加入戰鬥!', `MaleText_loc7`='|TInterfaceIconsability_warrior_battleshout.blp:20|t¡El maestro de armas Harlan llama a dos de sus aliados para que se unan al combate!' WHERE `ID`=65526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_weapon_halberd_05.blp:20|t무기전문가 할란이 |cFFFF0000|Hspell:111216|h[빛의 칼날]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_weapon_halberd_05.blp:20|t武器大师哈兰施放了|cFFFF0000|Hspell:111216|h[光明之刃]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_weapon_halberd_05.blp:20|t器大師哈倫施放|cFFFF0000|Hspell:111216|h[聖光之刃]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_weapon_halberd_05.blp:20|t¡El maestro de armas Harlan invoca |cFFFF0000|Hspell:111216|h[Hojas de Luz]|h|r!' WHERE `ID`=65527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기전문가 할란이 사용한 |cFFFF0000|Hspell:|h[빛의 칼날]|h|r을 맞고 전사했습니다. 할란은 빛의 칼날을 사용할 때 두 방향 중 한 방향으로 움직입니다. 할란이 어느 방향으로 움직이는지 파악해서 피하십시오!', `MaleText_loc4`='你被武器大师哈兰的|cFFFF0000|Hspell:|h[光明之刃]|h|r技能杀死了。武器大师哈兰在使用该技能时会从两个方向中任选其一行进，所以试着根据他的行进路线作出反应，以免于被他击中！', `MaleText_loc5`='你死在武器大師哈倫的|cFFFF0000|Hspell:|h[聖光之刃]|h|r技能之下。武器大師哈倫在他使用此技能時會選擇兩個方向其中之一行進，所以試著對他行進的方向做出反應，你就能避開他的路線。', `MaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:|h[Hojas de Luz]|h|r del maestro de armas Harlan. Cuando utiliza esta facultad, el maestro de armas Harlan viaja en una dirección de dos posibles, así que intenta reaccionan cuando elija una dirección para apartarte de su camino.', `FemaleText_loc1`='무기전문가 할란이 사용한 |cFFFF0000|Hspell:|h[빛의 칼날]|h|r을 맞고 전사했습니다. 할란은 빛의 칼날을 사용할 때 두 방향 중 한 방향으로 움직입니다. 할란이 어느 방향으로 움직이는지 파악해서 피하십시오!', `FemaleText_loc4`='你被武器大师哈兰的|cFFFF0000|Hspell:|h[光明之刃]|h|r技能杀死了。武器大师哈兰在使用该技能时会从两个方向中任选其一行进，所以试着根据他的行进路线作出反应，以免于被他击中！', `FemaleText_loc5`='你死在武器大師哈倫的|cFFFF0000|Hspell:|h[聖光之刃]|h|r技能之下。武器大師哈倫在他使用此技能時會選擇兩個方向其中之一行進，所以試著對他行進的方向做出反應，你就能避開他的路線。', `FemaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:|h[Hojas de Luz]|h|r del maestro de armas Harlan. Cuando utiliza esta facultad, el maestro de armas Harlan viaja en una dirección de dos posibles, así que intenta reaccionan cuando elija una dirección para apartarte de su camino.' WHERE `ID`=65528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t황실 장로 조르로크가 당신에게 |cFFFF0000|Hspell:122761|h[내쉬기]|h|r를 사용하려고 합니다! 생존 기술을 사용하거나, 생존 능력이 높은 동료를 당신과 조르로크 사이에 세우십시오!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t皇家宰相佐尔洛克已经将你选作|cFFFF0000|Hspell:122761|h[吐气]|h|r技能的目标！利用你的生存技能，或让生存能力较强的同伴站在你和皇家宰相佐尔洛克之间！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t女皇大臣索拉格以你當作他|cFFFF0000|Hspell:122761|h[吐氣]|h|r技能的目標!使用你的存活技能或讓一名有高存活能力的盟友站在你和女皇大臣索拉格之間。', `MaleText_loc7`='|TInterfaceIconsspell_shadow_psychicscream.blp:20|t¡El visir imperial Zor''lok te ha seleccionado como objetivo de su facultad |cFFFF0000|Hspell:122761|h[Exhalar]|h|r! Utiliza tus facultades de supervivencia o pídele a un aliado con gran capacidad de supervivencia que se interponga entre el visir imperial Zor''lok y tú.', `FemaleText_loc1`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t황실 장로 조르로크가 당신에게 |cFFFF0000|Hspell:122761|h[내쉬기]|h|r를 사용하려고 합니다! 생존 기술을 사용하거나, 생존 능력이 높은 동료를 당신과 조르로크 사이에 세우십시오!', `FemaleText_loc4`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t皇家宰相佐尔洛克已经将你选作|cFFFF0000|Hspell:122761|h[吐气]|h|r技能的目标！利用你的生存技能，或让生存能力较强的同伴站在你和皇家宰相佐尔洛克之间！', `FemaleText_loc5`='|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t女皇大臣索拉格以你當作他|cFFFF0000|Hspell:122761|h[吐氣]|h|r技能的目標!使用你的存活技能或讓一名有高存活能力的盟友站在你和女皇大臣索拉格之間。', `FemaleText_loc7`='|TInterfaceIconsspell_shadow_psychicscream.blp:20|t¡El visir imperial Zor''lok te ha seleccionado como objetivo de su facultad |cFFFF0000|Hspell:122761|h[Exhalar]|h|r! Utiliza tus facultades de supervivencia o pídele a un aliado con gran capacidad de supervivencia que se interponga entre el visir imperial Zor''lok y tú.' WHERE `ID`=65529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:122713|h[힘과 활력]|h|r에 의해 죽었습니다. |cFFFF0000|Hspell:122706|h[소음 방지]|h|r 지역에 들어가서 힘와 활력으로 받는 피해를 최소화하고, 자신이나 동료의 치유 능력을 써서 살아남으십시오.', `MaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122713|h[力与魄]|h|r杀死了。试着进入|cFFFF0000|Hspell:122706|h[噪音取消]|h|r区域来尽量降低力与魄的伤害，并进行自我治疗或让同伴用治疗技能来保你不死。', `MaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:122713|h[力量與氣魄]|h|r之下。試著進入其中一個|cFFFF0000|Hspell:122706|h[定音區]|h|r來使力量與氣魄的傷害降到最低，並且請盟友或自己使用治療技能來讓你保命。', `MaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:122713|h[Fuerza y reverberación]|h|r del visir imperial Zor''lok. Intenta entrar en una de las zonas de |cFFFF0000|Hspell:122706|h[Cancelación de ruido]|h|r para reducir el daño de Fuerza y reverberación y utiliza tus facultes de sanación o las de un aliado para seguir con vida.', `FemaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:122713|h[힘과 활력]|h|r에 의해 죽었습니다. |cFFFF0000|Hspell:122706|h[소음 방지]|h|r 지역에 들어가서 힘와 활력으로 받는 피해를 최소화하고, 자신이나 동료의 치유 능력을 써서 살아남으십시오.', `FemaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122713|h[力与魄]|h|r杀死了。试着进入|cFFFF0000|Hspell:122706|h[噪音取消]|h|r区域来尽量降低力与魄的伤害，并进行自我治疗或让同伴用治疗技能来保你不死。', `FemaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:122713|h[力量與氣魄]|h|r之下。試著進入其中一個|cFFFF0000|Hspell:122706|h[定音區]|h|r來使力量與氣魄的傷害降到最低，並且請盟友或自己使用治療技能來讓你保命。', `FemaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:122713|h[Fuerza y reverberación]|h|r del visir imperial Zor''lok. Intenta entrar en una de las zonas de |cFFFF0000|Hspell:122706|h[Cancelación de ruido]|h|r para reducir el daño de Fuerza y reverberación y utiliza tus facultes de sanación o las de un aliado para seguir con vida.' WHERE `ID`=65530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:123791|h[여제의 노래]|h|r에 의해 죽었습니다. 공격대원 한 명이 황실 장로 조르로크가 있는 단상 위에 올라가, 황실 장로 조르로크와 전투에 돌입해야 합니다.', `MaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r杀死了。要确保让你自己或其中一位盟友移动至皇家宰相佐尔洛克所在的平台，并与皇家宰相佐尔洛克交战。', `MaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:123791|h[女皇之歌]|h|r之下。確保你或你的一名盟友移動到女皇大臣索拉格所在的平台和他交戰。', `MaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:123791|h[Canción de la Emperatriz]|h|r del visir imperial Zor''lok. Asegúrate de que tú o uno de tus aliados os desplazáis a la plataforma en la que está el visir imperial Zor''lok y entabláis combate con él.', `FemaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:123791|h[여제의 노래]|h|r에 의해 죽었습니다. 공격대원 한 명이 황실 장로 조르로크가 있는 단상 위에 올라가, 황실 장로 조르로크와 전투에 돌입해야 합니다.', `FemaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r杀死了。要确保让你自己或其中一位盟友移动至皇家宰相佐尔洛克所在的平台，并与皇家宰相佐尔洛克交战。', `FemaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:123791|h[女皇之歌]|h|r之下。確保你或你的一名盟友移動到女皇大臣索拉格所在的平台和他交戰。', `FemaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:123791|h[Canción de la Emperatriz]|h|r del visir imperial Zor''lok. Asegúrate de que tú o uno de tus aliados os desplazáis a la plataforma en la que está el visir imperial Zor''lok y entabláis combate con él.' WHERE `ID`=65531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크가 당신을 |cFFFF0000|Hspell:122740|h[개종]|h|r시켜 사마귀 제국을 위해 싸우게 만들었습니다! 당신을 여제의 손아귀에서 구하려면, 동료들이 당신의 생명력을 50% 이하로 떨어뜨려야만 합니다.', `MaleText_loc4`='皇家宰相佐尔洛克已将你|cFFFF0000|Hspell:122740|h[策反]|h|r为替螳螂妖帝国战斗！你原来的同伴必须把使你的生命降低至50%，才能帮你摆脱女皇的控制！', `MaleText_loc5`='女皇大臣索拉格對你使用|cFFFF0000|Hspell:122740|h[轉化]|h|r，讓你為螳螂人帝國而戰!你的前盟友們必須將你的生命力減到50%以將你從女皇的控制中解放!', `MaleText_loc7`='¡El visir imperial Zor''lok te ha |cFFFF0000|Hspell:122740|h[Convertido]|h|r para que luches a favor del imperio mántide! Tus antiguos aliados deben reducir tu salud al 50% para liberarte del control de la Emperatriz!', `FemaleText_loc1`='황실 장로 조르로크가 당신을 |cFFFF0000|Hspell:122740|h[개종]|h|r시켜 사마귀 제국을 위해 싸우게 만들었습니다! 당신을 여제의 손아귀에서 구하려면, 동료들이 당신의 생명력을 50% 이하로 떨어뜨려야만 합니다.', `FemaleText_loc4`='皇家宰相佐尔洛克已将你|cFFFF0000|Hspell:122740|h[策反]|h|r为替螳螂妖帝国战斗！你原来的同伴必须把使你的生命降低至50%，才能帮你摆脱女皇的控制！', `FemaleText_loc5`='女皇大臣索拉格對你使用|cFFFF0000|Hspell:122740|h[轉化]|h|r，讓你為螳螂人帝國而戰!你的前盟友們必須將你的生命力減到50%以將你從女皇的控制中解放!', `FemaleText_loc7`='¡El visir imperial Zor''lok te ha |cFFFF0000|Hspell:122740|h[Convertido]|h|r para que luches a favor del imperio mántide! Tus antiguos aliados deben reducir tu salud al 50% para liberarte del control de la Emperatriz!' WHERE `ID`=65532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:122336|h[음파 고리]|h|r 기술에 의해 죽었습니다. 황실 장로 조르로크가 |cFFFF0000|Hspell:122496|h[감쇠]|h|r를 시전하기 시작하면 조르로크에게서 떨어져 음파 고리를 피해야 합니다.', `MaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122336|h[超声波之环]|h|r技能杀死了。当皇家宰相佐尔洛克开始施放|cFFFF0000|Hspell:122496|h[音波衰减]|h|r时，一定要从他身边走开，并躲避他发出的超声波之环。', `MaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:122336|h[強音波紋]|h|r技能之下。當女皇大臣索拉格開始施放|cFFFF0000|Hspell:122496|h[音波散射]|h|r時，確保你遠離他並閃躲他放出的強音波紋。', `MaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:122336|h[Anillos sónicos]|h|r del visir imperial Zor''lok. Cuando el visir imperial Zor''lok comience a lanzar |cFFFF0000|Hspell:122496|h[Atenuación]|h|r, asegúrate de que te alejas de él y esquivas los anillos sónicos que emite.', `FemaleText_loc1`='황실 장로 조르로크의 |cFFFF0000|Hspell:122336|h[음파 고리]|h|r 기술에 의해 죽었습니다. 황실 장로 조르로크가 |cFFFF0000|Hspell:122496|h[감쇠]|h|r를 시전하기 시작하면 조르로크에게서 떨어져 음파 고리를 피해야 합니다.', `FemaleText_loc4`='你被皇家宰相佐尔洛克的|cFFFF0000|Hspell:122336|h[超声波之环]|h|r技能杀死了。当皇家宰相佐尔洛克开始施放|cFFFF0000|Hspell:122496|h[音波衰减]|h|r时，一定要从他身边走开，并躲避他发出的超声波之环。', `FemaleText_loc5`='你死在女皇大臣索拉格的|cFFFF0000|Hspell:122336|h[強音波紋]|h|r技能之下。當女皇大臣索拉格開始施放|cFFFF0000|Hspell:122496|h[音波散射]|h|r時，確保你遠離他並閃躲他放出的強音波紋。', `FemaleText_loc7`='Has muerto víctima de la facultad |cFFFF0000|Hspell:122336|h[Anillos sónicos]|h|r del visir imperial Zor''lok. Cuando el visir imperial Zor''lok comience a lanzar |cFFFF0000|Hspell:122496|h[Atenuación]|h|r, asegúrate de que te alejas de él y esquivas los anillos sónicos que emite.' WHERE `ID`=65533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t야만의 콰이가 |cFFFF0000|Hspell:119922|h[충격파]|h|r 능력을 사용합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t力冠三军库乌艾使用了|cFFFF0000|Hspell:119922|h[震荡波]|h|r技能！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_earthquake.blp:20|t『蠻士』奎使用他的|cFFFF0000|Hspell:119922|h[震懾波]|h|r技能!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_earthquake.blp:20|t¡Kuai el Bruto utiliza su facultad |cFFFF0000|Hspell:119922|h[Ola de choque]|h|r!' WHERE `ID`=65534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_supriseattack.blp:20|t무쉬바가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:119946|h[찢어발기기]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_supriseattack.blp:20|t穆辛巴对|cFFFF0000$n|r施放了|cFFFF0000|Hspell:119946|h[毁灭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_supriseattack.blp:20|t姆西巴施放|cFFFF0000|Hspell:119946|h[劫掠]|h|r在|cFFFF0000$n|r身上!', `MaleText_loc7`='|TInterfaceIconsability_druid_supriseattack.blp:20|t¡Mu''Shiba lanza |cFFFF0000|Hspell:119946|h[Devastar]|h|r sobre |cFFFF0000$n|r!' WHERE `ID`=65536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_elemental_primal_air.blp:20|t교활한 밍이 |cFFFF0000|Hspell:119981|h[소용돌이의 춤]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_elemental_primal_air.blp:20|t鬼谋神算冥谷子召唤了|cFFFF0000|Hspell:119981|h[回旋风暴]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_elemental_primal_air.blp:20|t奸詐的明召喚了一個|cFFFF0000|Hspell:119981|h[神威旋風]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_elemental_primal_air.blp:20|t¡Ming el Astuto invoca un |cFFFF0000|Hspell:119981|h[Derviche giratorio]|h|r!' WHERE `ID`=65537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|t교활한 밍이 |cFFFF0000|Hspell:120099|h[자기장]|h|r을 형성합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|t鬼谋神算冥谷子生成了一个|cFFFF0000|Hspell:120099|h[磁场]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|t奸詐的明製造了一個|cFFFF0000|Hspell:120099|h[磁能力場]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_druid_ursolsvortex.blp:20|t¡Ming el Astuto crea un |cFFFF0000|Hspell:120099|h[Campo magnético]|h|r!' WHERE `ID`=65538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t무쌍의 하이옌이 |cFFFF0000$n|r|1을;를; |cFFFF0000|Hspell:123655|h[필사의 일격]|h|r으로 공격합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t势不可挡哈伊岩用|cFFFF0000|Hspell:123655|h[外伤打击]|h|r攻击了|cFFFF0000$n|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_savageblow.blp:20|t無人能擋的海嚴以|cFFFF0000|Hspell:123655|h[劇創痛擊]|h|r攻擊|cFFFF0000$n|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_savageblow.blp:20|t¡Haiyan el Imparable golpea a |cFFFF0000$n|r con un |cFFFF0000|Hspell:123655|h[Golpe traumático]|h|r!' WHERE `ID`=65539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 모였군. 역사적인 순간이오, $n. 죽어가는 아내가 이 문 뒤에 있는 빛의 도시를 보았소. 실제로는 무엇이 있을 것 같소?', `MaleText_loc4`='我们全都在这。这是个历史性的时刻，$n。我的妻子在弥留之际预见到了在这些大门之外的光明之城。你觉得我们会找到什么？', `MaleText_loc5`='我們都在此。這是歷史性的一刻，$n。我將死的妻子想像在門外有一座光之城。你認為我們會發現什麼?', `MaleText_loc7`='Ya estamos todos. es un momento histórico, $n. Mi mujer vio una ciudad de luz detrás de estas puertas antes de morir. ¿Qué crees que encontraremos?' WHERE `ID`=65540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쌍의 하이옌에게 |cFFFF0000|Hspell:123655|h[필사의 일격]|h|r을 맞았습니다! 이 효과가 지속되는 동안 자신에게 걸린 치유 주문의 효과가 감소합니다!', `MaleText_loc4`='势不可挡哈伊岩用|cFFFF0000|Hspell:123655|h[外伤打击]|h|r攻击了你！在效果持续期间，治疗技能只会为你回复较少的生命值！', `MaleText_loc5`='無人能擋的海嚴以|cFFFF0000|Hspell:123655|h[劇創痛擊]|h|r攻擊你!此效果持續時，使用在你身上的治療技能效果將會降低!', `MaleText_loc7`='¡Haiyan el Imparable te ha golpeado con un |cFFFF0000|Hspell:123655|h[Golpe traumático]|h|r! Las facultades de sanación que se usen contigo serán menos eficientes mientras persista el efecto.' WHERE `ID`=65541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확인하려면 한 가지 방법밖에 없지요...', `MaleText_loc4`='只有一种办法可以弄清楚……', `MaleText_loc5`='只有一個方法能夠查明...', `MaleText_loc7`='Solo hay una forma de averiguarlo...', `FemaleText_loc1`='확인하려면 한 가지 방법밖에 없지요...', `FemaleText_loc4`='只有一种办法可以弄清楚……', `FemaleText_loc5`='只有一個方法能夠查明...', `FemaleText_loc7`='Solo hay una forma de averiguarlo...' WHERE `ID`=65542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t무쌍의 하이옌이 |cFFFF0000$n|r|1을;를; 대상으로 |cFFFF0000|Hspell:120195|h[유성]|h|r을 시전하려 합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t势不可挡哈伊岩用|cFFFF0000|Hspell:120195|h[流星]|h|r瞄准了|cFFFF0000$n|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t無人能擋的海嚴把|cFFFF0000$n|r當作|cFFFF0000|Hspell:120195|h[隕石術]|h|r的目標!', `MaleText_loc7`='|TInterfaceIconsspell_fire_meteorstorm.blp:20|t¡Haiyan el Imparable selecciona a |cFFFF0000$n|r como objetivo de un |cFFFF0000|Hspell:120195|h[Meteorito]|h|r!' WHERE `ID`=65543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쌍의 하이옌에게 |cFFFF0000|Hspell:120195|h[유성]|h|r을 맞고 죽었습니다! 무쌍의 하이옌이 이 능력을 사용할 때는 동료들과 한데 모여서 피해를 나눠 받으십시오.', `MaleText_loc4`='你被势不可挡哈伊岩的|cFFFF0000|Hspell:120195|h[流星]|h|r杀死了！一定要在势不可挡哈伊岩使用该技能时与你的同伴站在一起，从而分担伤害。', `MaleText_loc5`='你死在無人能擋的海嚴|cFFFF0000|Hspell:120195|h[隕石術]|h|r之下!當無人能擋的海嚴使用此技能時，確保你和你的盟友站在一起以分攤傷害。', `MaleText_loc7`='Has muerto víctima del |cFFFF0000|Hspell:120195|h[Meteorito]|h|r de Haiyan el Imparable. Asegúrate de agruparte con tus aliados cuando Haiyan el Imparable utilice esta facultad para que os dividáis el daño entre todos.' WHERE `ID`=65544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_fireball.blp:20|t무쌍의 하이옌이 |cFFFF0000|Hspell:120167|h[점화]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_fireball.blp:20|t势不可挡哈伊岩开始施放|cFFFF0000|Hspell:120167|h[燃烧]|h|r了！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_fireball.blp:20|t無人能擋的海嚴開始施放|cFFFF0000|Hspell:120167|h[焚燒]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_fire_fireball.blp:20|t¡Haiyan el Imparable empieza a lanzar |cFFFF0000|Hspell:120167|h[Conflagrar]|h|r!' WHERE `ID`=65545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 목숨을 걸고 골짜기를 지킬 겁니다!', `MaleText_loc4`='我会用自己的生命守护山谷！', `MaleText_loc5`='我會以我的性命防衛恆春谷!', `MaleText_loc7`='¡Defenderé el valle con mi vida!', `FemaleText_loc1`='저는 목숨을 걸고 골짜기를 지킬 거예요!', `FemaleText_loc4`='我会用自己的生命守护山谷！', `FemaleText_loc5`='我會以我的性命防衛恆春谷!', `FemaleText_loc7`='¡Defenderé el valle con mi vida!' WHERE `ID`=65546;
