UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야만인들을 골짜기에서 몰아냅시다!', `MaleText_loc4`='把这些畜生从山谷里赶出去！', `MaleText_loc5`='把那些蠻人趕出谷中!', `MaleText_loc7`='¡Expulsad a estos bárbaros del valle!', `FemaleText_loc1`='이 야만인들을 골짜기에서 몰아내요!', `FemaleText_loc4`='把这些畜生从山谷里赶出去！', `FemaleText_loc5`='把那些蠻人趕出谷中!', `FemaleText_loc7`='¡Expulsad a estos bárbaros del valle!' WHERE `ID`=65552;
