UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 바쳐 골짜기를 지키는 것은 영예입니다!', `MaleText_loc4`='能用生命守卫山谷，是我的荣耀！', `MaleText_loc5`='以我的性命防衛恆春谷是一種榮耀!', `MaleText_loc7`='¡Defender el valle con mi vida es un honor!', `FemaleText_loc1`='목숨을 바쳐 골짜기를 지키는 것은 영예입니다!', `FemaleText_loc4`='能用生命守卫山谷，是我的荣耀！', `FemaleText_loc5`='以我的性命防衛恆春谷是一種榮耀!', `FemaleText_loc7`='¡Defender el valle con mi vida es un honor!' WHERE `ID`=65554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 승리했습니다!', `MaleText_loc4`='这是我们的战斗！', `MaleText_loc5`='我們贏得戰鬥了!', `MaleText_loc7`='¡La batalla es nuestra!', `FemaleText_loc1`='전투에서 승리했어요!', `FemaleText_loc4`='这是我们的战斗！', `FemaleText_loc5`='我們贏得戰鬥了!', `FemaleText_loc7`='¡La batalla es nuestra!' WHERE `ID`=65555;
