UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 또 내 용맹을 시험할 기회인가.', `MaleText_loc4`='啊——哈！检验我力量的机会又到了。', `MaleText_loc5`='哈哈!又有機會測試我的力量了。', `MaleText_loc7`='¡Ajá! Una buena ocasión para medir mis fuerzas.' WHERE `ID`=65557;
