UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 평화를 찾기를.', `MaleText_loc4`='愿他们获得宁静。', `MaleText_loc5`='願他們安息。', `MaleText_loc7`='Que encuentren la paz.', `FemaleText_loc1`='저들이 평화를 찾기를.', `FemaleText_loc4`='愿他们获得宁静。', `FemaleText_loc5`='願他們安息。', `FemaleText_loc7`='Que encuentren la paz.' WHERE `ID`=65563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서 우리에게 용기를 가르치셨습니다.', `MaleText_loc4`='雪怒教会了我们勇气。', `MaleText_loc5`='雪怒給了我們勇氣。', `MaleText_loc7`='Xeun nos ha enseñado el valor.', `FemaleText_loc1`='쉬엔 님께서 우리에게 용기를 가르치셨어요.', `FemaleText_loc4`='雪怒教会了我们勇气。', `FemaleText_loc5`='雪怒給了我們勇氣。', `FemaleText_loc7`='Xeun nos ha enseñado el valor.' WHERE `ID`=65564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기가 한결 안전해졌군요.', `MaleText_loc4`='山谷现在更加安全了。', `MaleText_loc5`='恆春谷現在更安全了。', `MaleText_loc7`='Ahora el valle es más seguro.', `FemaleText_loc1`='골짜기가 한결 안전해졌군요.', `FemaleText_loc4`='山谷现在更加安全了。', `FemaleText_loc5`='恆春谷現在更安全了。', `FemaleText_loc7`='Ahora el valle es más seguro.' WHERE `ID`=65565;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='릴리안 보스가 종교재판관 화이트메인의 시체에서 칼을 뽑아내자 칼날의 모양이 변합니다.', `FemaleText_loc4`='当她从怀特迈恩的尸体上将刀刃拔出时，刀刃变换了。', `FemaleText_loc5`='當她從懷特邁恩屍體上拔出劍刃時，那劍刃起了變化。', `FemaleText_loc7`='Las espadas se transforman mientras las recoge del cadáver de Melenablanca.' WHERE `ID`=65567;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작은 그루멀이 얼마나 배짱이 좋은지, 원. 어찌나 흥정을 잘 하는지, 이 가격대로라면 나는 곧 파산할 거예요.', `FemaleText_loc4`='你能相信这个小土地精的胆量吗？这个精明的小谈判者马上就能以他的价格把我搞破产。', `FemaleText_loc5`='你能相信這個小咕嚕摩的膽量嗎?這精明的小奸商用不了多久就能用他的價格讓我破產啦。', `FemaleText_loc7`='¿Te puedes creer la cara que tiene este pequeño grúmel? Este astuto negociador de bolsillo me dejará sin blanca con sus precios.' WHERE `ID`=65568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뻐끔!', `MaleText_loc4`='嗯哼！', `MaleText_loc5`='真有趣!', `MaleText_loc7`='¡FUMMM!' WHERE `ID`=65569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허가 다가오는 석상들을 가리키며 도움을 청합니다.', `MaleText_loc4`='他指着前来的雕像，希望得到你的帮助。', `MaleText_loc5`='他做手勢指向逼近的雕像，要求你的協助。', `MaleText_loc7`='Zheng señala las estatuas que se acercan, como pidiéndote ayuda.' WHERE `ID`=65570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어 태세를 유지하십시오!', `MaleText_loc4`='保持高度警惕！', `MaleText_loc5`='一個猴人強盜正在偷酒!阻止他!', `MaleText_loc7`='¡No bajéis la guardia!', `FemaleText_loc1`='방어 태세를 유지하세요!', `FemaleText_loc4`='保持高度警惕！', `FemaleText_loc5`='一個猴人強盜正在偷酒!阻止他!', `FemaleText_loc7`='¡No bajéis la guardia!' WHERE `ID`=65571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠 도둑이 맥주를 훔치고 있습니다! 막으십시오!', `MaleText_loc4`='有猢狲强盗在偷酒！快阻止他！', `MaleText_loc5`='一個猴人強盜正在偷酒!阻止他!', `MaleText_loc7`='¡Un bandido hozen se lleva el brebaje! ¡A por él!', `FemaleText_loc1`='호젠 도둑이 맥주를 훔치고 있습니다! 막으십시오!', `FemaleText_loc4`='有猢狲强盗在偷酒！快阻止他！', `FemaleText_loc5`='一個猴人強盜正在偷酒!阻止他!', `FemaleText_loc7`='¡Un bandido hozen se lleva el brebaje! ¡A por él!' WHERE `ID`=65572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $n! 전승지기가 이 계단 아래에서 이야기를 시작하려는 참이니, 궁금하다면 들어 보시오.', `MaleText_loc4`='你好啊$n！游学者正在楼下讲学，要是你有兴趣不妨去听听。', `MaleText_loc5`='哈囉$n!如果你想聽的話，博學行者她正在樓梯下面那邊開始授課。', `MaleText_loc7`='¡Hola, $n! La eremita está a punto de dar comienzo a su lección, al pie de las escaleras, por si quieres escuchar.' WHERE `ID`=65573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 것들.', `MaleText_loc4`='可怜的生物。', `MaleText_loc5`='可悲的生物。', `MaleText_loc7`='Patéticas criaturas.' WHERE `ID`=65574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이라는 게 뭔지 보여 주마.', `MaleText_loc4`='我要教会你们力量的意义。', `MaleText_loc5`='我將教你何為力量。', `MaleText_loc7`='Yo os enseñaré el significado de la fuerza.' WHERE `ID`=65575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 션 님이 돌아오신다, 약골.', `MaleText_loc4`='雷神回来了，弱者。', `MaleText_loc5`='雷神回來了，弱者。', `MaleText_loc7`='Lei Shen ha vuelto, gusano.' WHERE `ID`=65576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기는 샤오티엔의 것이다!', `MaleText_loc4`='山谷属于韶天！', `MaleText_loc5`='此谷是屬於嘯天的!', `MaleText_loc7`='¡El valle pertenece a los Shao-Tien!' WHERE `ID`=65577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 다시 한 번 판다리아를 지배할 것이다!', `MaleText_loc4`='我们会再次统治潘达利亚！', `MaleText_loc5`='我們將再度統治整個潘達利亞!', `MaleText_loc7`='¡Reinaremos sobre Pandaria una vez más!' WHERE `ID`=65578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 손아귀에서 벗어날 순 없다!', `MaleText_loc4`='谁也别想从我们的力量面前逃脱！', `MaleText_loc5`='你逃離不了我們的力量!', `MaleText_loc7`='¡Nadie puede huir de nuestra fuerza!' WHERE `ID`=65579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 것.', `MaleText_loc4`='愚蠢的孩童。', `MaleText_loc5`='愚蠢的小孩。', `MaleText_loc7`='Críos estúpidos.' WHERE `ID`=65580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 포기해라.', `MaleText_loc4`='快放弃吧。', `MaleText_loc5`='現在快放棄。', `MaleText_loc7`='Ríndete.' WHERE `ID`=65581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 예쁘게 자르고 다지는 사우록 사무라이, 마키 워터블레이드에게 공손하게 절하라고!', `MaleText_loc4`='他的剑一旦出鞘，敌人已经没有好下场！请对蜥蜴人武士水刃马基恭敬地鞠躬！', `MaleText_loc5`='他會毫不手軟地把你斬塊切丁!請恭敬地向薩烏洛克武士，真樹·水刃鞠躬!', `MaleText_loc7`='¡Dará tajos y cortes y mandobles! ¡Haced una reverencia a Maki Espadagua, samurái saurok!' WHERE `ID`=65582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 노래는 최초의 판다렌 탐험가, 리우 랑의 노래란다.', `FemaleText_loc4`='这是第一位熊猫人探险者——刘浪之歌。', `FemaleText_loc5`='這就是關於第一個熊貓人探險家的「劉浪之歌」。', `FemaleText_loc7`='Esta es la canción de Liu Lang, el primer explorador pandaren.' WHERE `ID`=65583;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옛 언어로 쓰여 있기 때문이야. 황제와 학자가 쓰던 말이란다. 지금은 이 말을 쓰는 사람이 거의 없어.', `FemaleText_loc4`='这首歌是由古文写成，那是皇帝和学者们使用的语言。现在几乎已经没人会说了。', `FemaleText_loc5`='這歌詞是用文言寫成的，那是屬於皇帝和學者的語言。很少有人這樣講話了。', `FemaleText_loc7`='La canción está escrita en la lengua antigua, la lengua de los emperadores y los eruditos. Una lengua casi muerta.' WHERE `ID`=65584;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑의 모험에 대한 노래지.', `FemaleText_loc4`='歌曲描绘了他的冒险之旅。', `FemaleText_loc5`='主要是有關於他的冒險。', `FemaleText_loc7`='Cuenta todas sus aventuras.' WHERE `ID`=65585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용감한 리우 랑은 바다거북을 타고 세상을 탐험하러 나섰단다.', `FemaleText_loc4`='勇敢的刘浪骑在海龟背上，出发去探索这个世界。', `FemaleText_loc5`='勇敢的劉浪乘著烏龜出發去探索世界。', `FemaleText_loc7`='El valiente Liu Lang se lanzó a explorar el mundo a lomos de una tortuga de mar.' WHERE `ID`=65586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 거북의 이름을 기억하는 사람 있니? 인?', `FemaleText_loc4`='有人记得那只海龟的名字吗？尹记得吗？', `FemaleText_loc5`='有人記得那烏龜的名字嗎，小瑛?', `FemaleText_loc7`='¿Alguien recuerda el nombre de la tortuga? ¿Yin?' WHERE `ID`=65587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞았어. 거북의 이름은 셴진 수였지. 처음에는 리우 랑이 앉으면 딱 맞을 정도로 작았단다.', `FemaleText_loc4`='没错，那只海龟被称作神真子。一开始，他的大小只容得下刘浪一人坐在上面。', `FemaleText_loc5`='對了，那烏龜叫神真子。最初，他的大小只夠劉浪一個人坐在上面。', `FemaleText_loc7`='Así es, la tortuga se llamaba Shen-zin Su. Al principio, era tan pequeña que sobre ella solo se podía sentar Liu Lang.' WHERE `ID`=65588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 자라고 자라고 또 자라서, "유랑도"라 불릴 정도로 커졌지.', `FemaleText_loc4`='后来他越变越大，大得惊人，所以现在有些人叫他“迷踪岛”。', `FemaleText_loc5`='他長啊長啊長，長得那麼大，大到有些人叫他「漂流島」。', `FemaleText_loc7`='Pero creció y creció y creció, y se hizo tan grande que ahora algunos la llaman "La Isla Errante".' WHERE `ID`=65589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='질문 있니, 하오?', `FemaleText_loc4`='有问题吗，昊？', `FemaleText_loc5`='有問題嗎?小豪?', `FemaleText_loc7`='Tienes alguna pregunta, ¿Hao?' WHERE `ID`=65590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 하오. 우리 마을은 셴진 수의 등 위에 있단다.', `FemaleText_loc4`='是的，昊——我们的家就在神真子的背上。', `FemaleText_loc5`='是的，小豪，我們的家就在神真子的背上。', `FemaleText_loc7`='Sí, Hao. Vivimos sobre el caparazón de Shen-zin Su.' WHERE `ID`=65591;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑은 세상을 탐험하면서 많은 걸 발견했단다. 왜 그러니, 하오?', `FemaleText_loc4`='刘浪在探索世界的过程中有许多发现——噢——怎么了，昊？', `FemaleText_loc5`='劉浪在探索世界時發現了這麼多東西。喔，怎麼樣，小豪?', `FemaleText_loc7`='Lui Lang descubrió muchas cosas al explorar el mundo. Oh, sí, ¿Hao?' WHERE `ID`=65592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 질문이구나. 수많은 세대가 흐르는 동안 셴진 수와 이야기한 사람은 아무도 없었어. 리우 랑하고만 이야기했거든.', `FemaleText_loc4`='这个问题问得好。历代以来，没人和神真子说过话。他只对刘浪开口。', `FemaleText_loc5`='那是個好問題。好幾代以來，沒有人和神真子說過話。他只和劉浪說過話。', `FemaleText_loc7`='Esa es una buena pregunta. Nadie ha hablado con Shen-zin Su durante generaciones. Solo habló con Liu Lang.' WHERE `ID`=65593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 셴진 수는 우리가 여기 있다는 걸 안단다. 그리고 우리 하나하나를 아끼지.', `FemaleText_loc4`='可我相信，神真子知道我们在这儿。而且他在乎我们每一个人！', `FemaleText_loc5`='但我相信神真子知道我們在這裡。他關心我們每一個人!', `FemaleText_loc7`='Pero no dudo que Shen-zin Su sabe dónde estamos. ¡Y cuida de todos nosotros!' WHERE `ID`=65594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하오는 특별히 더 아낄 거야! 리우 랑이 이런 말을 한 적이 있거든. "질문을 던지는 자는 고귀하다."', `FemaleText_loc4`='尤其是昊！刘浪曾经说过：“频频提问的人最为可贵。”', `FemaleText_loc5`='特別是小豪!劉浪曾經說過，「每事問，是禮也。」', `FemaleText_loc7`='¡Sobre todo de Hao! Liu Lang dijo una vez: "Noble aquel que siempre haga preguntas".' WHERE `ID`=65595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"우리는 모두 어린아이를 닮아야 한다. 이 세상이 우리의 원로이며, 우리에게 가르칠 것이 많기 때문이다."', `FemaleText_loc4`='“我们都该表现得像个孩子，因为世界才是长者，有很多东西要教给我们。”', `FemaleText_loc5`='「我們都該保持童子之心，因為世界是我們的師長，那裡有那麼多東西可以教我們。」', `FemaleText_loc7`='"Todos deberíamos ser como niños, porque el mundo es mucho mayor, y tiene muchas cosas que enseñarnos."' WHERE `ID`=65596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얘들아, 얘들아! 잘 들어야지.', `FemaleText_loc4`='弟子们！弟子们！集中精神。', `FemaleText_loc5`='同學們!同學!專心一點。', `FemaleText_loc7`='¡Estudiantes! ¡Estudiantes! Ahora presten atención.' WHERE `ID`=65597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑이 얼마나 자주 판다리아로 돌아갔는지 아는 사람?', `FemaleText_loc4`='有人知道刘浪多久回潘达利亚一次吗？', `FemaleText_loc5`='有人知道劉浪多久回潘達利亞一次嗎?', `FemaleText_loc7`='¿Sabe alguien con qué frecuencia volvía Liu Lang a Pandaria?' WHERE `ID`=65598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하. 아니란다, 인. 리우 랑은 탐험하면서 밥을 먹었거든.', `FemaleText_loc4`='哈哈，不是的，尹。刘浪走到哪儿就吃到哪儿。', `FemaleText_loc5`='哈哈，不，小瑛。劉浪會在他發現的每個地方吃東西。', `FemaleText_loc7`='Ja, ja, no, Yin. Liu Lang comería donde explorara.' WHERE `ID`=65599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑은 5년에 한 번씩 판다리아 본토로 돌아갔단다.', `FemaleText_loc4`='他每隔五年返回潘达利亚的主大陆一次。', `FemaleText_loc5`='他每五年回潘達利亞的主大陸一次。', `FemaleText_loc7`='Volvía al continente principal de Pandaria cada cinco años.' WHERE `ID`=65600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맞아, 인. 본토는 안개에 가려 있지.', `FemaleText_loc4`='你说得对，尹。它被藏起来了，藏在迷雾后面。', `FemaleText_loc5`='你是對的，小瑛。它的確是隱藏在迷霧裡面。', `FemaleText_loc7`='Sí, eso es, Yin. Está oculta, tras una capa de niebla.' WHERE `ID`=65601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑이 어떻게 매번 본토를 찾아갈 수 있었는지 기억하는 사람? 난?', `FemaleText_loc4`='有人记得刘浪总是如何找到它的吗？楠？', `FemaleText_loc5`='有人記得劉浪為什麼能永遠知道到哪找潘達利亞嗎?小楠?', `FemaleText_loc7`='¿Recuerda alguien cómo lograba siempre encontrarla? ¿Nan?' WHERE `ID`=65602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 맞아! 리우 랑은 항상 고향을 찾아갈 수 있었단다. 5년마다 돌아와서는 모험가를 더 데리고 갔지.', `FemaleText_loc4`='没错！刘浪总能设法回到家乡。每隔五年他就会回去，带走更多的探险者。', `FemaleText_loc5`='沒錯!劉浪永遠都知道怎麼回家。每隔五年，他都會回到這裡，接走更多的探險者。', `FemaleText_loc7`='¡Eso es! Liu Lang siempre lograba volver a casa. Cada cinco años volvería para llevarse más exploradores.' WHERE `ID`=65603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 하오! 가장 용감한 판다렌만이 리우 랑과 함께 거북을 타고 세상을 탐험했단다.', `FemaleText_loc4`='是的，昊！只有最勇敢的熊猫人才会爬上龟背，与刘浪一同外出探索世界。', `FemaleText_loc5`='沒錯，小豪!只有最勇敢的熊貓人能加入劉浪，在烏龜上探索整個世界。', `FemaleText_loc7`='¡Sí, Hao! Solo los pandaren más valientes se unieron a Liu Lang para explorar el mundo en su tortuga.' WHERE `ID`=65604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셴진 수는 오랫동안 육지에 도달하지 못했지만, 그래도 판다렌들은 주저 없이 모험에 나섰단다.', `FemaleText_loc4`='神真子很久没有上岸了。可那也没能阻止某些熊猫人外出探险。', `FemaleText_loc5`='神真子有很久沒有靠岸了。但反正那也阻止不了某些熊貓人出去探險。', `FemaleText_loc7`='Shen-zin Su no ha pisado tierra desde hace mucho tiempo. Pero eso no ha evitado que algunos pandaren siguieran explorando.' WHERE `ID`=65605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 첸과 리 리처럼 말이야! 그들은 고향을 떠나 세상을 탐험하지. 언젠가는 너희도 그렇게 될지도 모른단다.', `FemaleText_loc4`='是的，就像陈和丽丽！他们出去探索世界了。也许有一天，你们也会。', `FemaleText_loc5`='是的，就像老陳和莉莉!他們出去探索世界了。或許有一天，你也會和他們一樣。', `FemaleText_loc7`='¡Sí, como Chen y Li Li! Ellos están fuera, explorando el mundo. ¡Tal vez ustedes algún día lo hagan!' WHERE `ID`=65606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋은 질문이구나, 인. 리우 랑은 이곳 유랑도에서 일생 동안 세상을 탐험하면서, 자식을 여럿 길렀단다.', `FemaleText_loc4`='很高兴你提出了这个问题，尹。刘浪一生都在探索世界，还在迷踪岛上养育了许多子女。', `FemaleText_loc5`='很高興妳問了，小瑛。劉浪用一輩子去探索世界，並在這座漂流島上養大了許多孩子。', `FemaleText_loc7`='Me alegra que lo preguntes, Yin. Liu Lang exploró el mundo durante toda su vida, y tuvo muchos hijos aquí en La Isla Errante.' WHERE `ID`=65607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='할아버지가 된 리우 랑은 마지막으로 판다리아를 찾았지.', `FemaleText_loc4`='最后他变得非常老迈，最后一次造访了潘达利亚。', `FemaleText_loc5`='最終，他變得非常非常老了，並最後一次拜訪了潘達利亞。', `FemaleText_loc7`='Al final, ya muy viejo, visitó Pandaria una última vez.' WHERE `ID`=65608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 함께 탐험을 하고자 하는 이가 없어서 그냥 떠났단다.', `FemaleText_loc4`='但却没有其他人愿意和他一同探险。于是他离开了。', `FemaleText_loc5`='但沒有其他人想跟他一起出去探險，所以他就離開了。', `FemaleText_loc7`='Pero nadie más quería ir a explorar con él. Así que se fue.' WHERE `ID`=65609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셴진 수는 그 후로 다시는 판다리아에 돌아가지 않았지.', `FemaleText_loc4`='神真子再也没有返回潘达利亚。', `FemaleText_loc5`='神真子再也沒回去潘達利亞過。', `FemaleText_loc7`='Shen-zin Su no ha vuelto jamás a Pandaria.' WHERE `ID`=65610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지친 리우 랑은 가장 오랜 친구인 셴진 수에게 작별 인사를 했단다.', `FemaleText_loc4`='疲惫不已的刘浪告别了神真子——这位与他交情至深的老朋友。', `FemaleText_loc5`='疲倦的劉浪，向他最老的朋友神真子告別。', `FemaleText_loc7`='Ya cansado, Liu Lang le dijo adiós a Shen-zin Su, su más vieja amiga.' WHERE `ID`=65611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러고는 지팡이의 숲으로 올라갔지. 탐험을 할 때 항상 지니고 다니던 대나무 우산을 들고서 말이야.', `FemaleText_loc4`='然后，刘浪去了禅杖林，身上背着那柄随他四处游历的竹伞。', `FemaleText_loc5`='然後，劉浪去到杖木林，帶著他旅行時總是帶在身邊的那把竹傘。', `FemaleText_loc7`='Tras esto, Liu Lang fue al Bosque de Bastones, con una sombrilla de bambú que se llevaba siempre en sus aventuras.' WHERE `ID`=65612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑은 우산을 펼쳐서 땅에 꽂고는, 시원한 그늘 아래 앉았단다.', `FemaleText_loc4`='他撑开竹伞，把伞柄插进地里，坐在伞下乘凉。', `FemaleText_loc5`='他打開他的傘，插在地上，坐在它陰涼的庇蔭下。', `FemaleText_loc7`='La abrió, la plantó en la tierra y se sentó bajo su fresca sombra.' WHERE `ID`=65613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런 다음, 눈을 감고 섬과 하나가 되었지. 그런데 무슨 일이 일어났는지 아니?', `FemaleText_loc4`='他闭上双眼，与大地融为一体。然后——你们知道发生了什么吗？', `FemaleText_loc5`='他閉上眼睛，變成大地的一部分。然後，你猜發生了什麼事?', `FemaleText_loc7`='Cerró los ojos y se fundió con la tierra. Y entonces, ¿saben lo que pasó?' WHERE `ID`=65614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑의 우산... 우산에서 싹이 텄단다! 우산이 뿌리를 내리고 꽃을 피우더니, 나무가 되었지!', `FemaleText_loc4`='他的竹伞……发芽了！生根，开花，变成了一颗树！', `FemaleText_loc5`='他的傘...發芽了!它長了根，開了花，變成了一棵大樹!', `FemaleText_loc7`='Su sombrilla... ¡germinó! Le salieron raíces, floreció y se convirtió en un árbol.' WHERE `ID`=65615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사실이란다. 지팡이의 숲에 가면 아직도 그 나무를 볼 수 있어.', `FemaleText_loc4`='嗯，是真的。要是你去禅杖林，就能看见了。', `FemaleText_loc5`='嗯，那是真的喔。如果你去到杖木林，你就能看見它。', `FemaleText_loc7`='Bien, es verdad. Si van alguna vez al Bosque de Bastones, lo verán.' WHERE `ID`=65616;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리보다 먼저 살다 가신 어르신들의 지팡이와 함께, 커다란 나무로 자라고 있지.', `FemaleText_loc4`='那些在我们之前到来的长者，他们的禅杖也已生根发芽，那里已经长出参天密林。', `FemaleText_loc5`='它就在我們之前所有長者的手杖旁邊，長成一棵巨樹。', `FemaleText_loc7`='Además de todos los otros bastones de los ancianos que nos precedieron, creciendo ahora como árboles gigantes.' WHERE `ID`=65617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 슬픈 이야기가 아니야! 리우 랑 스스로도 이런 말을 했지. "잘 살다 가는 사람을 애도하지 마라."', `FemaleText_loc4`='这不是个难过的故事！刘浪自己说过：“生时精彩，死亦无憾。”', `FemaleText_loc5`='這不是個傷心的故事!劉浪自己曾經說，「精采的一生毋須哀泣。」', `FemaleText_loc7`='¡No es una historia triste! Liu Lang lo dijo, "Nunca llores una vida bien vivida."' WHERE `ID`=65618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 생각에도 리우 랑은 매우 값진 삶을 살았단다. 우리가 지금 이렇게 살 수 있는 것은 모두, 최초의 판다렌 탐험가 리우 랑 덕분이니까.', `FemaleText_loc4`='在我看来，刘浪的人生无比精彩。我们的一切都得益于刘浪——这位熊猫人探险者始祖。', `FemaleText_loc5`='而我想他確實活了非常非常精采的一生。我們擁有的一切都是因為劉浪。第一個熊貓人探險者。', `FemaleText_loc7`='Y creo que él vivió una muy buena vida. Le debemos todo lo que tenemos a Liu Lang, el primer explorador pandaren.' WHERE `ID`=65619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 리우 랑을 언제까지나 기억하기 위해, 그의 이야기를 하지.', `FemaleText_loc4`='我们讲述他的故事，是为了让他能够被永远铭记。', `FemaleText_loc5`='我們傳述他的故事，讓他可以永遠被記得。', `FemaleText_loc7`='Nosotros contamos su historia para que sea recordado siempre.' WHERE `ID`=65620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 루오린! 정말 아름다운 노래였어요.', `FemaleText_loc4`='洛林，谢谢你！你的歌喉美极了。', `FemaleText_loc5`='謝謝你，若凌!那真是太美了。', `FemaleText_loc7`='¡Gracias, Ruolin! Ha sido precioso.' WHERE `ID`=65621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방금 온 학생들을 위해 한 번만 더 불러 주시겠어요?', `FemaleText_loc4`='你能再唱一遍吗，唱给那些刚刚到来的弟子听？', `FemaleText_loc5`='你能夠為剛來的學生再唱一遍嗎?', `FemaleText_loc7`='¿Puedes contarlo una vez más para los estudiantes que acaban de llegar?' WHERE `ID`=65622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고귀한 마키에게 어울리는 명예로운 최후로군... 그의 부족도 자랑스러워할 거야. 마키의 죽음으로 멸종된 것만 아니라면 말이지!', `MaleText_loc4`='高贵马基的光荣结局……如果他不是他们当中的最后一个，我敢肯定，他的部族会感到自豪！', `MaleText_loc5`='對高貴的真樹來說是一個光榮的了結...我確信他的部族會很驕傲，如果他不是他們一族最後一人的話!', `MaleText_loc7`='Un fin honorable para el noble Maki... Estoy seguro de que su clan estaría orgulloso, ¡si no hubiera sido él el último!' WHERE `ID`=65623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파는 항상 그루멀의 친구였어요. 근데 왜 들여보내 주지 않는 거죠?', `MaleText_loc4`='影踪派一直是土地精的朋友。他们为什么不让我们进去做生意？', `MaleText_loc5`='影潘和咕嚕摩一直都是朋友。他們為什麼不讓我們進去做買賣?', `MaleText_loc7`='El Shadopan siempre ha sido amigo de los grúmel. ¿Por qué no nos dejan entrar para comerciar?' WHERE `ID`=65624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 멀고 먼 길을 왔어요. 그런데 음영파가 우리 물건이 필요 없다고 하네요. 정말 이상한 일이에요.', `MaleText_loc4`='我们长途跋涉。现在影踪派却说，他们不想要我们的商品。真是太奇怪了。', `MaleText_loc5`='我們走了長長的路。現在影潘說他們不想要我們的貨物。這真的很奇怪。', `MaleText_loc7`='Hemos venido desde muy lejos. Ahora el Shadopan dice que no quiere nuestros bienes. Es extraño.' WHERE `ID`=65625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난 호젠, 날뛰는 설인, 더러운 야크를 뚫고 여기까지 왔더니, 음영파가 우릴 모른 척하네요.$b$b정말 엄청난 불행이죠.', `MaleText_loc4`='我们一路上曾遇到愤怒的猢狲、发狂的雪人和肮脏的牦牛，最后来到这里。现在，影踪派把我们当陌生人。$b$b运气真是不好。', `MaleText_loc5`='我們經過了憤怒的猴人、橫衝直撞的雪人、還有骯髒的犛牛才來到這裡。現在影潘好像把我們當成陌生人。$b$b這真是倒大楣。', `MaleText_loc7`='Hemos pasado por hozen furiosos, yetis salvajes y yaks sucios para llegar hasta aquí. Ahora el Shadopan actúa como si fuésemos desconocidos.$b$bQué mala fortuna.' WHERE `ID`=65626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코가 시려워요. 아주 나쁜 징조예요.', `MaleText_loc4`='我的鼻子凉了。这是非常糟糕的预兆。', `MaleText_loc5`='我的鼻子好冰。這是非常不好的徵兆。', `MaleText_loc7`='Tengo la nariz fría. Es muy mala señal.' WHERE `ID`=65627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오는 길에 야크를 잃어 버렸어요. 아주 불길해요.', `MaleText_loc4`='我在前来的途中丢失了牦牛。这可真糟糕。', `MaleText_loc5`='我在來這裡的路上損失了我的犛牛。這真是糟透了。', `MaleText_loc7`='Perdí a mi yak por el camino. Eso no es nada bueno.' WHERE `ID`=65628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 음영파 대원이 우릴 들여보내 주지 않으면, 내 복덩이 냄새를 맡게 해 줄 거예요.', `MaleText_loc4`='如果这个影踪派弟子不快点让我们进去，我就让他闻闻我的幸运符。', `MaleText_loc5`='如果影潘不快點讓我們進去的話，我會讓他們聞聞我的幸運星。', `MaleText_loc7`='Si este Shadopan no nos deja entrar pronto, me va a oler el grisgrís.' WHERE `ID`=65629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 이상한 일이에요. 음영파는 우리 우량 고객이거든요. 우린 음영파에게 보급품을 팔고, 음영파는 우릴 보호해 주지요.$b$b그런데 왜 이제 와서 우릴 쫓아내려는 건지 이해가 안 돼요.', `MaleText_loc4`='太奇怪了。影踪派是我们最好的客户。我们将物资出售给他们，他们则保证我们的安全。$b$b现在为什么要对我们不理不睬？我无法理解。', `MaleText_loc5`='這真的很奇怪。影潘是我們最好的顧客。我們賣補給品給他們，他們保護我們安全。$b$b他們為什麼要趕我們走?我真的搞不懂。', `MaleText_loc7`='Qué extraño. El Shadopan es nuestro mejor cliente. Nosotros les enviamos suministros y ellos nos mantienen a salvo.$b$b¿Por qué nos rechazan? No lo entiendo.' WHERE `ID`=65630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 한 마디도 이해가 안 되는데요.', `MaleText_loc4`='我怎么一句都听不懂？', `MaleText_loc5`='為什麼我連一個字都不懂?', `MaleText_loc7`='¿Por qué no puedo entender una sola palabra?' WHERE `ID`=65631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 속을 스치듯 움직이는 살인적인 주먹의 소유자, 음흉하고도 조용한 진위 암살자, 사테이 뷰를 소개하지!', `MaleText_loc4`='现在掠过死亡迷雾，迎向他双拳的是——阴险沉着的锦鱼人杀手——萨塔耶·布宇！', `MaleText_loc5`='揮舞著死亡之拳輕快地穿過迷霧，邪惡且穩重的錦魚人殺手:沙喋·鰾現身!', `MaleText_loc7`='A través de la niebla, con la muerte en los puños, se acerca un asesino jinyu siniestro y sereno: ¡Satay Byu!' WHERE `ID`=65632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살인 생선의 전성기가 비린내 나는 최후를 맞았군.', `MaleText_loc4`='噢，这个风光无限的杀手鲤鱼终于要变成俎上鱼肉。', `MaleText_loc5`='喔喔，一個殺手錦魚的殺人生涯就此終結。', `MaleText_loc7`='Oooh, ahí va una carpa asesina cuyos días de matar se han ido por el desagüe.' WHERE `ID`=65633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노래 내용이 뭐예요?', `FemaleText_loc4`='那首歌是关于什么的？', `FemaleText_loc5`='關於什麼的歌?', `FemaleText_loc7`='¿Qué cuenta esta canción?' WHERE `ID`=65634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셴진 수요!', `FemaleText_loc4`='神真子！', `FemaleText_loc5`='神真子!', `FemaleText_loc7`='¡Shen-zin Su!' WHERE `ID`=65635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들, 파멸의 투기장의 새로운 우승자에게 환호를!', `MaleText_loc4`='所有人，请为破军比武场的新冠军欢呼！', `MaleText_loc5`='大家，請為我們殲滅競技場的新冠軍們歡呼!', `MaleText_loc7`='¡Un gran aplauso para los NUEVOS CAMPEONES de la Arena de la Aniquilación!' WHERE `ID`=65636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 커다란 거북이 등에 산다고요?!', `MaleText_loc4`='我们住在一只巨龟的背上？！', `MaleText_loc5`='我們住在一隻大烏龜的背上?!', `MaleText_loc7`='¡¿Vivimos a lomos de una tortuga gigante?!' WHERE `ID`=65637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿, 하오. 너 똑바로 안 들었구나?', `FemaleText_loc4`='嘘，昊。你一直都没注意听吗？', `FemaleText_loc5`='噓!小豪。你都沒專心聽嗎?', `FemaleText_loc7`='Jo, Hao. ¿Es que nunca prestas atención?' WHERE `ID`=65638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩐지 산에 지느러미발이 달려 있는 게 이상하다 했어!', `MaleText_loc4`='我刚还觉得纳闷呢，怎么山峰会长蹼！', `MaleText_loc5`='我就覺得奇怪，山怎麼會有鰭!', `MaleText_loc7`='Es verdad que me sorprendía que las montañas tuvieran aletas...' WHERE `ID`=65639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기 사는 걸 거북이도 알아요?', `MaleText_loc4`='海龟知道我们在这儿吗？', `MaleText_loc5`='這烏龜知道我們在這裡嗎?', `MaleText_loc7`='¿Y la tortuga sabe que estamos aquí?' WHERE `ID`=65640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하오도요?', `FemaleText_loc4`='甚至是昊？', `FemaleText_loc5`='甚至是小豪?', `FemaleText_loc7`='¿Hasta de Hao?' WHERE `ID`=65641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야!', `MaleText_loc4`='嘿！', `MaleText_loc5`='嘿!', `MaleText_loc7`='¡Oye!' WHERE `ID`=65642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞아, 너희 다 나를 닮아야 돼.', `MaleText_loc4`='对，你们都该跟我学学。', `MaleText_loc5`='沒錯，你們都應該多學學我。', `MaleText_loc7`='Sí, todos deberían ser como yo.' WHERE `ID`=65643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우엑! 차라리 이 다리에서 뛰어내리겠다.', `FemaleText_loc4`='得了！我宁可从这桥上跳下去。', `FemaleText_loc5`='咧!我寧願從這橋上跳下去。', `FemaleText_loc7`='¡Bah! Antes me tiro de este puente.' WHERE `ID`=65644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...배고플 때마다요?', `FemaleText_loc4`='……每当他饿了的时候？', `FemaleText_loc5`='...每當他肚子餓的時候?', `FemaleText_loc7`='¿... Siempre que tenía hambre?' WHERE `ID`=65645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 판다리아는 숨겨져 있잖아요? 아무도 못 찾게요!', `FemaleText_loc4`='可潘达利亚不是被藏起来了吗？没人能找到它！', `FemaleText_loc5`='但潘達利亞不是藏起來了嗎?沒有人能找到它!', `FemaleText_loc7`='¿Pero Pandaria no está oculta en algún lugar? ¡Nadie puede encontrarla!' WHERE `ID`=65646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바다거북은 항상 자기가 태어난 해변으로 돌아오니까요!', `FemaleText_loc4`='因为海龟总会返回他们出生的海岸！', `FemaleText_loc5`='因為海龜永遠會回到他們出生的沙灘上!', `FemaleText_loc7`='¡Porque las tortugas de mar siempre vuelven a la playa en la que nacieron!' WHERE `ID`=65647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러면 우리 엄마, 아빠랑 할머니, 할아버지가 다 탐험가였단 말이에요?', `MaleText_loc4`='那是不是说，我们的爸爸妈妈爷爷奶奶也都是探险者？', `MaleText_loc5`='那代表我們的爸爸媽媽，還有爺爺奶奶全都是探險家嗎?', `MaleText_loc7`='¿Eso quiere decir que nuestros papás y mamás y abuelos eran todos exploradores?' WHERE `ID`=65648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 이제 우린 별로 탐험을 안 하잖아요.', `FemaleText_loc4`='可我们现在不怎么探险了，对吧？', `FemaleText_loc5`='但我們不再四處探險了，不是嗎?', `FemaleText_loc7`='Pero ya no exploramos mucho, ¿verdad?' WHERE `ID`=65649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='첸이랑 리 리 스톰스타우트처럼요?', `FemaleText_loc4`='就像陈和丽丽·风暴烈酒！', `FemaleText_loc5`='就像老陳和莉莉·風暴烈酒!', `FemaleText_loc7`='¡Como Chen y Li Li Cerveza de Trueno!' WHERE `ID`=65650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 세상을 탐험하고 싶어!', `MaleText_loc4`='我想要探索世界！', `MaleText_loc5`='我想要探索世界!', `MaleText_loc7`='¡Yo quiero explorar el mundo!' WHERE `ID`=65651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='설마. 세상은 트롤 천지인걸.', `FemaleText_loc4`='不行。到处都是巨魔。', `FemaleText_loc5`='你才不行。那裡都是食人妖。', `FemaleText_loc7`='No. Está lleno de trols.' WHERE `ID`=65652;
