UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름 바닥돌은 괜찮고, 다른 바닥돌은 나쁘다네. 입구의 계단 밑에 있던 바닥돌 때문에 알았지. 또 한 번 내 날카로운 눈 덕분에 나의 연약한 육신을 보전했군!', `MaleText_loc4`='云瓷砖不错。其他瓷砖不好。在入口楼梯的底部有一块瓷砖差点害我摔跤。我敏锐的目光又一次挽救了我美好的形象！', `MaleText_loc5`='雷雲地磚是安全的，其他類型的地磚則不是安全的。在入口樓梯底部的那個地磚讓我得到了靈感，我銳利的眼睛又再一次救了我纖細的面容!', `MaleText_loc7`='La baldosa con la nube es buena. Las demás, malas. Había una baldosa al pie de las escaleras que me ha dado una pista. ¡Mis ojos de águila han vuelto a salvar mis delicadas facciones!' WHERE `ID`=65672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 아무래도 우리 말고도 누가 있는 것 같군요... 당신이 이 악당들을 처치해 주면, 그동안 저는 맥주를 만들겠습니다.', `MaleText_loc4`='噢宝贝儿！看来我们有伴了……你解决那些混蛋，我去酿酒。', `MaleText_loc5`='喔老天!看來我們有同伴了...你對付那些雜種，我會開始釀酒。', `MaleText_loc7`='¡Vaya! Parece que tenemos compañía... Ustedes encárgense de ellos y yo daré comienzo a la preparación.' WHERE `ID`=65673;
