UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠지만, 그렇다고 자만해서는 안 됩니다.', `MaleText_loc4`='我们打得很好，但也不能冒进。', `MaleText_loc5`='我們打得很好，但是不應該魯莽躁進。', `MaleText_loc7`='Luchamos bien, pero no deberíamos confiarnos.' WHERE `ID`=65811;
