UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다른 이들의 평화를 지키려고 싸웁니다.', `MaleText_loc4`='为同胞们的福祉而战。', `MaleText_loc5`='我們努力作戰，讓其他人能過和平的日子。', `MaleText_loc7`='Luchamos para que otros puedan vivir en paz.' WHERE `ID`=65813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸우시더군요. 하지만 자만하지 마십시오.', `MaleText_loc4`='你打得很好，但不要太自满了。', `MaleText_loc5`='你打得很好，當心別過度自信。', `MaleText_loc7`='Luchas bien, pero no te confíes.' WHERE `ID`=65814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰러진 이들을 위해!', `MaleText_loc4`='为了牺牲的人们！', `MaleText_loc5`='為了倒下的同伴!', `MaleText_loc7`='¡Por los caídos!' WHERE `ID`=65815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들이 더는 헛된 피를 흘리지 않게 하겠습니다!', `MaleText_loc4`='你们休想再伤害无辜者们！', `MaleText_loc5`='你的族人不會再無辜受難!', `MaleText_loc7`='¡Tu calaña no volverá a derramar sangre inocente!' WHERE `ID`=65816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이겼습니다.', `MaleText_loc4`='我们赢得了战斗。', `MaleText_loc5`='我們贏了。', `MaleText_loc7`='Ganamos la batalla.' WHERE `ID`=65817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 없어지면 한결 더 편해질 겁니다.', `MaleText_loc4`='只有这家伙死掉，我才能松口气。', `MaleText_loc5`='這場仗結束了，我也覺得輕鬆多了。', `MaleText_loc7`='Respiraré más tranquilo ahora que ya no existe.' WHERE `ID`=65818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼!', `MaleText_loc4`='不！', `MaleText_loc5`='不!', `MaleText_loc7`='¡No!' WHERE `ID`=65819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못참겠군요.', `MaleText_loc4`='无法容忍。', `MaleText_loc5`='這是天理不容的。', `MaleText_loc7`='Esto debe parar.' WHERE `ID`=65820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파를 위하여!', `MaleText_loc4`='为了影踪派！', `MaleText_loc5`='為了影潘!', `MaleText_loc7`='¡Por el Shadopan!' WHERE `ID`=65821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인내심을 가지십시오! 승리가 눈앞에 있습니다.', `MaleText_loc4`='坚持住！胜利在望了。', `MaleText_loc5`='加油!勝利就在我們手中。', `MaleText_loc7`='¡Perseveren! La victoria está a nuestro alcance.' WHERE `ID`=65822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠습니다. 전투에서 살아남았다니 기쁘군요.', `MaleText_loc4`='打得好。我很高兴你能活下来。', `MaleText_loc5`='打得好，很高興你活著回來。', `MaleText_loc7`='Luchaste bien. Me alegro de que hayas sobrevivido.' WHERE `ID`=65823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 싸워서 영광이었습니다.', `MaleText_loc4`='和你并肩作战是我的荣幸。', `MaleText_loc5`='我很榮幸能與你並肩作戰。', `MaleText_loc7`='Es un honor luchar a tu lado.' WHERE `ID`=65824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리의 기쁨을 함께 누리지 못하는 이들을 기려야겠습니다.', `MaleText_loc4`='我要去缅怀那些不能与我们分享胜利的人了。', `MaleText_loc5`='我會緬懷那些無法與我們分享這場勝利的夥伴。', `MaleText_loc7`='Voy a meditar sobre aquellos que no pueden compartir esta victoria con nosotros.' WHERE `ID`=65825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련이 필요합니다.', `MaleText_loc4`='我需要训练。', `MaleText_loc5`='我需要一些訓練。', `MaleText_loc7`='Busco instrucción.', `FemaleText_loc1`='훈련이 필요해요.', `FemaleText_loc4`='我需要训练。', `FemaleText_loc5`='我需要一些訓練。', `FemaleText_loc7`='Busco instrucción.' WHERE `ID`=65826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊힌 비밀로 가득한 신대륙이라! 혹시 새로운 자료를 발견하면 이곳의 전승지기와 저에게 가져오십시오. 대신 다른 연구 자료를 드릴 테니까요.', `MaleText_loc4`='一片充满失落秘密的新大陆！跟这里的游学者和我分享你了解到的一切，我会让你参与到其它的项目中来。', `MaleText_loc5`='一個充滿被遺忘秘密的新大陸!和這裡的博學行者們還有我分享你所知道的事，我就會讓你參與我的一些其他計畫。', `MaleText_loc7`='¡Un continente nuevo lleno de secretos olvidados! Comparte tus descubrimientos con los eremitas y conmigo, y yo compartiré contigo algunos de mis otros proyectos.', `FemaleText_loc1`='잊힌 비밀로 가득한 신대륙이라! 혹시 새로운 자료를 발견하면 이곳의 전승지기와 저에게 가져오십시오. 대신 다른 연구 자료를 드릴 테니까요.', `FemaleText_loc4`='一片充满失落秘密的新大陆！跟这里的游学者和我分享你了解到的一切，我会让你参与到其它的项目中来。', `FemaleText_loc5`='一個充滿被遺忘秘密的新大陸!和這裡的博學行者們還有我分享你所知道的事，我就會讓你參與我的一些其他計畫。', `FemaleText_loc7`='¡Un continente nuevo lleno de secretos olvidados! Comparte tus descubrimientos con los eremitas y conmigo, y yo compartiré contigo algunos de mis otros proyectos.' WHERE `ID`=65827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 연구 자료를 보고 싶습니다.', `MaleText_loc4`='让我参与你其它的项目吧。', `MaleText_loc5`='讓我參與你的其他計畫。', `MaleText_loc7`='Comparte tus otros proyectos.', `FemaleText_loc1`='다른 연구 자료를 보고 싶어요.', `FemaleText_loc4`='让我参与你其它的项目吧。', `FemaleText_loc5`='讓我參與你的其他計畫。', `FemaleText_loc7`='Comparte tus otros proyectos.' WHERE `ID`=65828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네, 제군들! $p 덕분에 우리는 야운골에게서 쿤라이 봉우리를 탈환하고, 이곳을 다시 안전하게 만들 걸세. 호드를 위하여!', `MaleText_loc4`='好了，新兵们！多亏了$p，我们能从野牛人手里夺回昆莱山，让它重获安宁了。为了部落！', `MaleText_loc5`='好了，新兵們!多虧$p的幫忙，我們要從揚古手中收復崑萊，讓他再次成為安全的家園!為了部落!', `MaleText_loc7`='¡Escuchen, reclutas! Gracias a $p, vamos a recuperar la Cima Kun-Lai de manos de los yaungol y nos encargaremos de que vuelva a ser un lugar seguro. ¡Por la Horda!' WHERE `ID`=65829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 큰일을 해 주었네, 친구. 덕분에 든든한 활동 기반을 다졌네. 또 자네 도움이 필요한 곳이 있는지 보게나.', `MaleText_loc4`='你在这里做得十分出色，朋友。我们应该很快就能建立起强大的行动基地了——去看看还有没有别人需要你的帮助。', `MaleText_loc5`='你做得非常好，朋友。再過不久，我們應該就能在這裡建立堅固的作戰基地。去看看有沒有人需要你的幫助。', `MaleText_loc7`='Has hecho un gran trabajo, camarada. A partir de ahora deberíamos tener una sólida base de operaciones aquí. Ve a ver si alguien más necesita tu ayuda.' WHERE `ID`=65830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=65831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제군들, $p|1이;가; 자네들과 얼라이언스를 구했음을 잊지 말아라! 그리고 이제 우리가 쿤라이를 구할 것이다!', `MaleText_loc4`='新兵们，我要让你们记住，是$p救了你们，是联盟将要拯救昆莱！', `MaleText_loc5`='新兵，我要你們記得是$p拯救了你們。聯盟將要收復崑萊!', `MaleText_loc7`='Reclutas, quiero que recordéis que fue $p quien os salvó, ¡y la Alianza quien salvará Kun-Lai!' WHERE `ID`=65832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 큰일을 해 주셨습니다. 이제 이곳의 활동 기반을 유지하는 데 큰 문제가 없을 겁니다.', `MaleText_loc4`='你干得十分出色。我们现在应该能轻松守住这里的行动基地了。', `MaleText_loc5`='你做得非常好。我們應該能不花什麼力氣，就在這裡建立起作戰基地了。', `MaleText_loc7`='Has hecho un trabajo excelente. No deberíamos tener mayores problemas para mantener nuestra base de operaciones aquí.' WHERE `ID`=65833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 위하여!', `MaleText_loc4`='为了联盟！', `MaleText_loc5`='為了聯盟!', `MaleText_loc7`='¡Por la Alianza!', `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=65834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 증오한다!', `FemaleText_loc4`='我恨你们所有人！', `FemaleText_loc5`='我恨你們所有人!', `FemaleText_loc7`='¡Los odio a todos!' WHERE `ID`=65835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜? 왜 하필 린이지?', `FemaleText_loc4`='为什么？为什么非得是他？', `FemaleText_loc5`='為什麼?為什麼要是他?', `FemaleText_loc7`='¿Por qué? ¿Por qué tuvo que ser él?' WHERE `ID`=65836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='복수할 것이다!', `FemaleText_loc4`='我会讨回公道！', `FemaleText_loc5`='我會討回公道!', `FemaleText_loc7`='¡Haré justicia!' WHERE `ID`=65837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음에는 죽음으로!', `FemaleText_loc4`='以命偿命！', `FemaleText_loc5`='一命償一命!', `FemaleText_loc7`='¡Muerte por muerte!' WHERE `ID`=65838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='출발하기 전에 페이 리와 이야기하세요. 적을 상대할 때 페이의 기술이 유용하게 쓰일 거예요.', `FemaleText_loc4`='出发前别忘了跟非离谈谈。她的技能会有力地帮你对付我们的敌人。', `FemaleText_loc5`='離開時不要忘記跟菲里說話。你會發現她的技巧非常適合用來對付敵人。', `FemaleText_loc7`='No olvides hablar con Fei Li antes de partir. Verás que sus habilidades son útiles contra nuestros enemigos.' WHERE `ID`=65839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상했던 것보다도 훨씬 강해지셨군요.', `MaleText_loc4`='你的进步比我预想中快得多。', `MaleText_loc5`='你已經成長得比我預期中更強壯了。', `MaleText_loc7`='Te has hecho mucho más fuerte de lo que esperaba.', `FemaleText_loc1`='예상했던 것보다도 훨씬 강해지셨군요.', `FemaleText_loc4`='你的进步比我预想中快得多。', `FemaleText_loc5`='你已經成長得比我預期中更強壯了。', `FemaleText_loc7`='Te has hecho mucho más fuerte de lo que esperaba.' WHERE `ID`=65840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 치유사가 필요하면 말해 주세요.', `MaleText_loc4`='如果你需要我协助作战，就告诉我一声。', `MaleText_loc5`='如果你在戰場上需要治療者的話，請跟我說。', `MaleText_loc7`='Si alguna vez necesitas sanación en la batalla, habla conmigo.', `FemaleText_loc1`='전투에서 치유사가 필요하면 말해 주세요.', `FemaleText_loc4`='如果你需要我协助作战，就告诉我一声。', `FemaleText_loc5`='如果你在戰場上需要治療者的話，請跟我說。', `FemaleText_loc7`='Si alguna vez necesitas sanación en la batalla, habla conmigo.' WHERE `ID`=65841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 함께 싸우면 정말 영광일 거예요.', `MaleText_loc4`='和你并肩战斗是我的荣幸。', `MaleText_loc5`='能在戰場上加入你是我的榮幸。', `MaleText_loc7`='Será un honor para mí acompañarte en la batalla.', `FemaleText_loc1`='전투에서 함께 싸우면 정말 영광일 거예요.', `FemaleText_loc4`='和你并肩战斗是我的荣幸。', `FemaleText_loc5`='能在戰場上加入你是我的榮幸。', `FemaleText_loc7`='Será un honor para mí acompañarte en la batalla.' WHERE `ID`=65842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 힘을 믿어라. 그분께서 우릴 영광으로 인도하시리라!', `MaleText_loc4`='相信女皇的力量吧！她会引领我们走向辉煌！', `MaleText_loc5`='相信女皇的力量。她會帶領我們得勝!', `MaleText_loc7`='Confíen en el poder de su Emperatriz. ¡Ella nos conducirá a la gloria!' WHERE `ID`=65843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 무리는 이 땅에 존재했던 그 어느 제국보다도 더 위대해질 것이다!', `MaleText_loc4`='团结起来，虫群会比这片土地上的任何帝国都要强大！', `MaleText_loc5`='同心協力，蟲群會成為這塊大地有史以來最強大的帝國!', `MaleText_loc7`='¡Juntos elevaremos al enjambre más que cualquier otro imperio de esta tierra' WHERE `ID`=65844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 뜻이 곧 우리의 뜻이다. 폐하의 위대함이 곧 우리의 위대함이다. 폐하의 승리는 곧 무리의 승리다!', `MaleText_loc4`='女皇的意志就是我们的意志。女皇的伟大就是我们的伟大。女皇的胜利就是虫群的胜利！', `MaleText_loc5`='女皇的意志就是我們的意志。她的偉業就是我們的偉業。她的勝利就是蟲群的勝利!', `MaleText_loc7`='La voluntad de nuestra Emperatriz es nuestra voluntad. Su grandeza es la nuestra. ¡Su victoria es la del enjambre!' WHERE `ID`=65845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 여제 폐하의 목소리에 반항하느냐? 무리는 목소리의 말을 따른다!', `MaleText_loc4`='你竟敢藐视女皇的声音？这声音足以号令整个虫群！', `MaleText_loc5`='你膽敢質疑女皇之聲?女皇之聲一出，蟲群拜服!', `MaleText_loc7`='¿Te atreves a desafiar a la voz de la Emperatriz? ¡Lo que la voz dice, el enjambre lo escucha!' WHERE `ID`=65846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 감히! 너는 무리의 일원이 아니구나!', `MaleText_loc4`='亵渎！你不是虫群的一员！', `MaleText_loc5`='放肆!你不是蟲群的一分子!', `MaleText_loc7`='¡Blasfemia! ¡No perteneces al enjambre!' WHERE `ID`=65847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 여제 폐하의 신성한 분노 앞에서 하찮은 존재일 뿐! 너 역시 쓰러질 것이다!', `MaleText_loc4`='你只是个对抗女皇圣怒的渣滓！你也必将灭亡！', `MaleText_loc5`='區區一人也敢反抗女皇的聖怒，你也會倒下的!', `MaleText_loc7`='¡No eres más que un ser contra la ira divina de la Emperatriz! ¡Tú también fracasarás!' WHERE `ID`=65848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군단은 적들을 베어내는 칼날이다.', `MaleText_loc4`='虫群将像利刃般刺穿我们的敌人！', `MaleText_loc5`='蟲群就是切碎我們敵人的刀!', `MaleText_loc7`='¡El enjambre es la espada que segará a nuestros enemigos!' WHERE `ID`=65849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베기 한 번이면 충분해.', `MaleText_loc4`='只需一刀就够了。', `MaleText_loc5`='砍一刀就夠了。', `MaleText_loc7`='Un corte bastará.' WHERE `ID`=65850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적들은 우리의 칼날에 쓰러지리라!', `MaleText_loc4`='敌人将在我们的利刃下毙命！', `MaleText_loc5`='我們的敵人會在刀鋒下喪命!', `MaleText_loc7`='¡Nuestros enemigos caerán ante nuestras espadas!' WHERE `ID`=65851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날의 날카로움을 시험해 볼까?', `MaleText_loc4`='你想试试我利刃的刀锋吗？', `MaleText_loc5`='你想試試我的刀鋒有多利嗎?', `MaleText_loc7`='¿Quieres probar el filo de mi espada?' WHERE `ID`=65852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시의 불복종 냄새가 난다! 그만 뛰어다니고 칼날군주를 상대해 봐!', `MaleText_loc4`='我闻到了卡拉克西大逆不道的臭味！站住，面对刀锋领主吧！', `MaleText_loc5`='我聞到不服從卡拉西的臭味!停下來，面對刀鋒領主!', `MaleText_loc7`='¡Huelo el hedor de la desobediencia Klaxxi! ¡No corras y enfréntate al Señor de las Espadas!' WHERE `ID`=65853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하하... 고작 그 정도냐?', `MaleText_loc4`='啊哈哈哈哈哈……这样疼不疼？', `MaleText_loc5`='啊哈哈哈哈...這樣會痛對吧?', `MaleText_loc7`='Ja, ja, ja... ¿Se suponía que eso me iba a doler?' WHERE `ID`=65854;
