UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이런. 이건 제가 먹으려고 했던 건데! 뭐, 엘라가 이게 필요하다면 더 안 먹을래요. 여기 있어요. 가져가세요!', `FemaleText_loc4`='哎呀，我自己正要吃呢！好吧，要是艾拉想要，我就不能不给。接着，拿去吧！', `FemaleText_loc5`='啊啊可惡，我本來要吃這些的!好吧，如果艾拉需要，那我就不吃了。來吧，拿去!', `FemaleText_loc7`='¡Ay, vaya! Me los iba a comer yo... Bueno, si Ella los necesita, ya no me los como. ¡Toma!' WHERE `ID`=65906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘라가 쓸 무를 찾으신다고요? 네, 제가 남는 게 하나 있습니다. 여기 있습니다.', `MaleText_loc4`='可爱的小艾拉要一根萝卜？是的，我肯定能让出一根。给你。', `MaleText_loc5`='給艾拉的小蘿蔔?嗯，我當然能分一條出來。拿去吧。', `MaleText_loc7`='¿Un rábano para la pequeña Ella? Claro que te daré uno. Toma.' WHERE `ID`=65907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘라가 맥주 양조를 처음으로 시도해본다고? 허, 그거 놀랍군! 행운을 빌어줘야겠네. 알겠지만, 맥주 양조는 초보자가 금방 따라 할 수 있는 게 아니라네. 어쨌든 여기 남는 호수멜론 하나 주겠네.', `MaleText_loc4`='小艾拉在试着酿酒？好吧，我是！祝她好运。你知道，酿造不是新手可以掌握的。无论如何，我可以让给她一个湖瓜。', `MaleText_loc5`='小艾拉想嘗試釀酒?太驚奇啦!我祝她順利成功。不過要知道，釀酒可不是新手隨隨便便就能辦到的。但反正，我是可以分點湖生甜瓜給她。 ', `MaleText_loc7`='¿La pequeña Ella quiere ser cervecera? ¡Vaya! Le deseo suerte. No es fácil para los novatos, ¿sabes? Pero bueno, puedo darle una badea.' WHERE `ID`=65908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 먹으려고 복숭아를 사는 거였다면 비싸게 팔 생각이었는데, 엘라는 제 시장의 우수 고객이랍니다. 이건 그냥 드릴게요. 딱 이번만이에요. 아셨죠!?', `FemaleText_loc4`='我本该向你收取买那个桃子的一大笔钱，但考虑到艾拉是我最好的顾客，这个就免费送给你。仅此一次，听到了吧！', `FemaleText_loc5`='我應該要跟你好好收一筆這桃子的錢，但艾拉是這麼好的客人，這一次就由本店招待吧。聽清楚，只有這一次啊!', `FemaleText_loc7`='Te iba a cobrar una buena cantidad por ese melocotón, pero Ella es tan buena cliente en mi mercado que esta va de parte de la casa. Solo esta, ¡me oyes!' WHERE `ID`=65909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='"얼굴을 해로 향하면, 그림자는 뒤로 늘어질 것이다"라는 말이 있지요.$b$b당신의 앞날이 밝기를 바라요, $n!', `FemaleText_loc4`='有句话是这么说的——“你的脸朝向太阳，阴影将落在你身后。”$b$b我希望你能发现光明的未来，$n！', `FemaleText_loc5`='俗語說，「面向陽光，陰影就會被你拋諸腦後。」$b$b我希望你在前方找到很多光明的日子，$n!', `FemaleText_loc7`='Se dice: "Mira hacia el sol y las sombras caerán tras de ti".$b$b¡Espero que te aguarden muchos días luminosos, $n!' WHERE `ID`=65910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와! 이거 정말 끝내주는군요! 더 마시려면 어디로 가야 합니까?', `MaleText_loc4`='哇！这可是个好东西！在哪里能找到更多？', `MaleText_loc5`='哇!這東西真是太美妙了!哪裡能弄到更多?', `MaleText_loc7`='¡Guau! ¡Eshto eshtá muy bueno! ¿Dónde puedo consheguir másh?' WHERE `ID`=65911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 정말 끝내주는 맛이군요! 훌륭합니다! 이렇게 훌륭한 맥주는 정말 오랜만에 마셔보는군요. 누가 양조한 겁니까?', `MaleText_loc4`='嗯，这味道好极了！好极了！这是我这么长时间以来尝到的最好的东西。是谁酿造的？', `MaleText_loc5`='哼嗯，這真是太棒了。太棒啦!!這是我嚐過最棒的玩意了。誰釀出來的?', `MaleText_loc7`='Mmm, ¡esto es estupendo! ¡ESTUPENDO! Es lo mejor que he probado en mucho tiempo. ¿Quién lo ha fabricado?' WHERE `ID`=65912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와... $n 님, 맥주 맛이 정말 좋군요. 한 두잔 더 마셔도 괜찮겠... 딸꾹!', `MaleText_loc4`='嗯，口味太棒了，$n。我不会介意再来一杯……或两杯……嗝！', `MaleText_loc5`='哼嗯，這味道太棒了，$n。我不介意再多喝個一兩杯...嗝!', `MaleText_loc7`='Mmm, qué sabor tan delicioso, $n. No me importaría probar otra ronda... o dos... ¡hic!' WHERE `ID`=65913;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으으음.. 이렇게 복잡미묘하면서도 투명한 맛은... 음... 스톰스타우트 양조장의 황금기 이래로는 마셔본 적이 없는걸! 이걸 양조한 이가 누군지는 모르겠지만, 재능이 정말 뛰어나구나.', `FemaleText_loc4`='嗯，自从……风暴烈酒酿造厂的黄金时代过后……我就没有尝到过口感如此醇厚清冽的美酒！无论是谁酿的，他都是一个真正的人才。', `FemaleText_loc5`='哼嗯，自從...自從風暴烈酒酒坊的黃金時代過去後，我就沒嚐過這麼豐富又純淨的滋味了!釀出這玩意的傢伙肯定有些天才。', `FemaleText_loc7`='Mmm, no había probado una cerveza con esta complejidad y claridad desde... bueno... desde la edad dorada del la Cervecería del Trueno. Quien la haya fabricado tiene talento de verdad.' WHERE `ID`=65914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 길 중에 가장 뛰어난 길의 실력이 곧 당신의 요리 실력입니다.', `MaleText_loc4`='从一而精，此为烹饪之道。', `MaleText_loc5`='你烹飪的技巧最好也只會和你最精通之道一樣。', `MaleText_loc7`='Tu habilidad en cocina equivale a tu senda más avanzada.', `FemaleText_loc1`='여러 길 중에 가장 뛰어난 길의 실력이 곧 당신의 요리 실력입니다.', `FemaleText_loc4`='从一而精，此为烹饪之道。', `FemaleText_loc5`='你烹飪的技巧最好也只會和你最精通之道一樣。', `FemaleText_loc7`='Tu habilidad en cocina equivale a tu senda más avanzada.' WHERE `ID`=65915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으음... 흐음... 이건 정말... 끝내주는 맛이군. 자네 친구 엘라는 정말 솜씨가 뛰어난데! 엘라에게 스톰스타우트 양조장에 있는 가오 아저씨와 이야기해보라고 하게나. 곧 엘라의 새로운 집이 될 것 같으니까 말일세.', `MaleText_loc4`='嗯。嗯……这……简直是……令人吃惊。你的朋友艾拉真是太有天赋了！让她去找我在酿造厂的高老伯谈一谈。我想她已经在我们风暴烈酒家族里找到了自己的位置。', `MaleText_loc5`='唔唔唔。唔唔唔唔...這個...簡單來說...美極了。你的朋友艾拉擁有真正的天份。叫她去酒坊跟我的高叔叔聊聊。我想她可以在我們風暴烈酒這裡找到一個新家。', `MaleText_loc7`='Mmmm. Mmmmm... Esto es... en una palabra... excelente. ¡Tu amiga Ella tiene talento de verdad! Dile que vaya a hablar con mi tío Gao, en la cervecería. Creo que ha encontrado su sitio entre los Cerveza de Trueno.' WHERE `ID`=65916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 걱정스러운 눈으로 바라봅니다.>', `MaleText_loc4`='<米师关切地看着你。>', `MaleText_loc5`='<米什擔心地看著你。>', `MaleText_loc7`='<Mishi te mira con preocupación.>' WHERE `ID`=65917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스는 당신의 행동에 어리둥절해합니다.>', `MaleText_loc4`='<米师不明白你为什么这么做。>', `MaleText_loc5`='<米什對你的舉動感到疑惑。>', `MaleText_loc7`='<Mishi no entiende tus acciones.>' WHERE `ID`=65918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 당신이 뭘 하는 건지 궁금해합니다.>', `MaleText_loc4`='<米师不明白你在做什么。>', `MaleText_loc5`='<米什納悶你在做什麼。>', `MaleText_loc7`='<Mishi se pregunta qué estás haciendo.>' WHERE `ID`=65919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 호기심이 인다는 듯이 당신 쪽으로 고개를 기울입니다.>', `MaleText_loc4`='<米师歪着脑袋，好奇地看着你。>', `MaleText_loc5`='<米什好奇地對你歪著頭。>', `MaleText_loc7`='<Mishi ladea la cabeza y te mira con curiosidad.>' WHERE `ID`=65920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 가만히 쳐다봅니다.>', `MaleText_loc4`='<米师看着你。>', `MaleText_loc5`='<米什盯著你。>', `MaleText_loc7`='<Mishi te observa.>' WHERE `ID`=65921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 기분이 매우 좋습니다!>', `MaleText_loc4`='<米师很高兴和你在一起！>', `MaleText_loc5`='<米什跟你在一起非常開心!>', `MaleText_loc7`='<¡Mishi está muy contento contigo!>' WHERE `ID`=65922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 들떠서 아래위로 움직입니다.>', `MaleText_loc4`='<米师兴奋得上窜下跳。>', `MaleText_loc5`='<米什興奮地上下跳。>', `MaleText_loc7`='<Mishi flota arriba y abajo, emocionado.>' WHERE `ID`=65923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 미소를 짓습니다.>', `MaleText_loc4`='<米师冲着你笑。>', `MaleText_loc5`='<米什對你微笑。>', `MaleText_loc7`='<Mishi te sonríe.>' WHERE `ID`=65924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 기뻐서 아래위로 움직입니다.>', `MaleText_loc4`='<米师欢快得上窜下跳。>', `MaleText_loc5`='<米什歡欣地上下跳。>', `MaleText_loc7`='<Mishi flota arriba y abajo, alegre.>' WHERE `ID`=65925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<미스가 기분이 좋습니다!>', `MaleText_loc4`='<米师很快乐！>', `MaleText_loc5`='<米什很高興!>', `MaleText_loc7`='<¡Mishi está contento!>' WHERE `ID`=65926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매운 주먹질을 해서 수레에 달라붙은 호젠을 떨어뜨려요!', `MaleText_loc4`='用香料喷洒将猢狲从车上赶下去！', `MaleText_loc5`='用香料拳把猴人從推車上打下來!', `MaleText_loc7`='¡Dales un Puñetazo especiado a los hozen para tirarlos de la carreta!', `FemaleText_loc1`='매운 주먹질을 해서 수레에 달라붙은 호젠을 떨어뜨려요!', `FemaleText_loc4`='用香料喷洒将猢狲从车上赶下去！', `FemaleText_loc5`='用香料拳把猴人從推車上打下來!', `FemaleText_loc7`='¡Dales un Puñetazo especiado a los hozen para tirarlos de la carreta!' WHERE `ID`=65927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수레에 올라타는 호젠한테는 매운 주먹질 맛을 보여 줘요!', `MaleText_loc4`='对跳到车上的猢狲使用香料喷洒！', `MaleText_loc5`='對在推車上跳的猴人使用香料拳!', `MaleText_loc7`='¡Dales un Puñetazo especiado a los hozen que saltan a la carreta!', `FemaleText_loc1`='수레에 올라타는 호젠한테는 매운 주먹질 맛을 보여 줘요!', `FemaleText_loc4`='对跳到车上的猢狲使用香料喷洒！', `FemaleText_loc5`='對在推車上跳的猴人使用香料拳!', `FemaleText_loc7`='¡Dales un Puñetazo especiado a los hozen que saltan a la carreta!' WHERE `ID`=65928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴! 지금부터는 아무 일 없을 거예요!', `MaleText_loc4`='哇！一切都应该从此一帆风顺！', `MaleText_loc5`='呼!接下來所有事情應該都會很順利!', `MaleText_loc7`='¡Fiu! ¡A partir de ahora todo debería ir cuesta abajo!', `FemaleText_loc1`='휴! 지금부터는 아무 일 없을 거예요!', `FemaleText_loc4`='哇！一切都应该从此一帆风顺！', `FemaleText_loc5`='呼!接下來所有事情應該都會很順利!', `FemaleText_loc7`='¡Fiu! ¡A partir de ahora todo debería ir cuesta abajo!' WHERE `ID`=65929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인이 나락샤의 동력장치에 이렇게까지 가까이 온 것은 처음이다.', `MaleText_loc4`='从没有任何外来者与纳拉克煞引擎如此接近。', `MaleText_loc5`='這是任何外來者所到過最接近納拉卡煞引擎的地方。', `MaleText_loc7`='Ningún forastero se había acercado tanto al Motor de Nalak''sha.' WHERE `ID`=65930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해 냈어요! 지금부터는 안전해요!', `MaleText_loc4`='看来我们成功了！我们畅通无阻了！', `MaleText_loc5`='看來我們成功了!我們度過危機了!', `MaleText_loc7`='¡Creo que lo hemos conseguido! ¡Todo despejado!', `FemaleText_loc1`='해 냈어요! 지금부터는 안전해요!', `FemaleText_loc4`='看来我们成功了！我们畅通无阻了！', `FemaleText_loc5`='看來我們成功了!我們度過危機了!', `FemaleText_loc7`='¡Creo que lo hemos conseguido! ¡Todo despejado!' WHERE `ID`=65931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 사라졌어요! 휴! 이제 길이 안전하겠네요.', `MaleText_loc4`='不见了！哇！看来障碍已经消除。', `MaleText_loc5`='他們走了!呼!看來小徑安全了。', `MaleText_loc7`='¡Se han ido! ¡Fiu! Parece que el camino está despejado.', `FemaleText_loc1`='놈들이 사라졌어요! 휴! 이제 길이 안전하겠네요.', `FemaleText_loc4`='不见了！哇！看来障碍已经消除。', `FemaleText_loc5`='他們走了!呼!看來小徑安全了。', `FemaleText_loc7`='¡Se han ido! ¡Fiu! Parece que el camino está despejado.' WHERE `ID`=65932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해 냈어요! 지금부터는 별일 없을 거예요.', `MaleText_loc4`='我们成功了！从这里开始，应该畅通无阻了。', `MaleText_loc5`='我們成功了!小徑接下來應該很安全。', `MaleText_loc7`='¡Lo conseguimos! A partir de ahora el camino debería estar despejado.', `FemaleText_loc1`='해 냈어요! 지금부터는 별일 없을 거예요.', `FemaleText_loc4`='我们成功了！从这里开始，应该畅通无阻了。', `FemaleText_loc5`='我們成功了!小徑接下來應該很安全。', `FemaleText_loc7`='¡Lo conseguimos! A partir de ahora el camino debería estar despejado.' WHERE `ID`=65933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 복덩이여! 저게 대체 뭐지!?', `MaleText_loc4`='噢！伟大的幸运符！那是什么？！', `MaleText_loc5`='喔偉大的幸運星啊!那是什麼鬼東西!?', `MaleText_loc7`='¡Por todos los grisgrís! ¡¿Qué es eso?!', `FemaleText_loc1`='위대한 복덩이여! 저게 대체 뭐지!?', `FemaleText_loc4`='噢！伟大的幸运符！那是什么？！', `FemaleText_loc5`='喔偉大的幸運星啊!那是什麼鬼東西!?', `FemaleText_loc7`='¡Por todos los grisgrís! ¡¿Qué es eso?!' WHERE `ID`=65934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 운이 나쁠 수가! 저게 대체 뭐야!?', `MaleText_loc4`='噢！最不幸的日子！那是什么？', `MaleText_loc5`='喔真是超級倒大楣的日子!那是什麼鬼東西!?', `MaleText_loc7`='¡Por toda la mala suerte! ¡¿Qué es eso?!', `FemaleText_loc1`='이렇게 운이 나쁠 수가! 저게 대체 뭐야!?', `FemaleText_loc4`='噢！最不幸的日子！那是什么？', `FemaleText_loc5`='喔真是超級倒大楣的日子!那是什麼鬼東西!?', `FemaleText_loc7`='¡Por toda la mala suerte! ¡¿Qué es eso?!' WHERE `ID`=65935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제-- 헉, 이렇게 운이 나쁠 수가! 저게 대체 뭐야!?', `MaleText_loc4`='我们最不幸的日子！那是什么？', `MaleText_loc5`='我們應...喔真是超級倒大楣的日子!那是什麼鬼東西!?', `MaleText_loc7`='Deberíam... ¡Por toda la mala suerte! ¡¿Qué es eso?!', `FemaleText_loc1`='이제-- 헉, 이렇게 운이 나쁠 수가! 저게 대체 뭐야!?', `FemaleText_loc4`='我们最不幸的日子！那是什么？', `FemaleText_loc5`='我們應...喔真是超級倒大楣的日子!那是什麼鬼東西!?', `FemaleText_loc7`='Deberíam... ¡Por toda la mala suerte! ¡¿Qué es eso?!' WHERE `ID`=65936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아악! 설인이 쫓아온다!', `MaleText_loc4`='噢！雪人跟来了！', `MaleText_loc5`='噢啊!小徑上有雪人!', `MaleText_loc7`='¡Aaaaah! ¡Yeti en el camino!', `FemaleText_loc1`='으아아아악! 설인이 쫓아온다!', `FemaleText_loc4`='噢！雪人跟来了！', `FemaleText_loc5`='噢啊!小徑上有雪人!', `FemaleText_loc7`='¡Aaaaah! ¡Yeti en el camino!' WHERE `ID`=65937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아악! 설인이 쫓아온다! 야크야! 더 빨리, 더 빨리!', `MaleText_loc4`='噢！后边有雪人！快走，牦牛！快点，再快点！', `MaleText_loc5`='噢啊!小徑上有雪人!犛牛快跑!快點，再快點!', `MaleText_loc7`='¡Aaaaah! ¡Yeti en el camino! ¡Venga, yak! ¡Más rápido, más rápido!', `FemaleText_loc1`='으아아아악! 설인이 쫓아온다! 야크야! 더 빨리, 더 빨리!', `FemaleText_loc4`='噢！后边有雪人！快走，牦牛！快点，再快点！', `FemaleText_loc5`='噢啊!小徑上有雪人!犛牛快跑!快點，再快點!', `FemaleText_loc7`='¡Aaaaah! ¡Yeti en el camino! ¡Más rápido, más rápido!' WHERE `ID`=65938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아악! 설인이 쫓아온다! 아직 안전한 게 아니었어!', `MaleText_loc4`='噢！雪人跟来了！看来我们还没有摆脱这些麻烦呢！', `MaleText_loc5`='噢啊!小徑上有雪人!看來我們還沒度過危機!', `MaleText_loc7`='¡Aaaaah! ¡Yeti en el camino! ¡Todavía no estamos a salvo!', `FemaleText_loc1`='으아아아악! 설인이 쫓아온다! 아직 안전한 게 아니었어!', `FemaleText_loc4`='噢！雪人跟来了！看来我们还没有摆脱这些麻烦呢！', `FemaleText_loc5`='噢啊!小徑上有雪人!看來我們還沒度過危機!', `FemaleText_loc7`='¡Aaaaah! ¡Yeti en el camino! ¡Todavía no estamos a salvo!' WHERE `ID`=65939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비밀을 안고 죽어라.', `MaleText_loc4`='你就带着这些秘密一起进棺材吧。', `MaleText_loc5`='這些秘密會和你一起死去。', `MaleText_loc7`='Estos secretos morirán con ustedes.' WHERE `ID`=65940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 유랑객의 축제에 가는 길입니다. 같이 가시지요!', `MaleText_loc4`='我们正要去参加云游节。你一定得跟我们一起去！', `MaleText_loc5`='我們在前往遊子節的路上。你應該加入我們!', `MaleText_loc7`='Nos dirigimos al Festival del Errante. ¡Deberías venir con nosotros!', `FemaleText_loc1`='우리는 유랑객의 축제에 가는 길이에요. 같이 가요!', `FemaleText_loc4`='我们正要去参加云游节。你一定得跟我们一起去！', `FemaleText_loc5`='我們在前往遊子節的路上。你應該加入我們!', `FemaleText_loc7`='Nos dirigimos al Festival del Errante. ¡Deberías venir con nosotros!' WHERE `ID`=65941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유랑객의 축제가 오늘 밤 열립니다. 당신도 오십니까?', `MaleText_loc4`='今晚就是云游节了。你要来参加吗？', `MaleText_loc5`='今晚就是遊子節了。你會來嗎?', `MaleText_loc7`='Esta noche es el Festival del Errante. ¿Vas a venir?', `FemaleText_loc1`='유랑객의 축제가 오늘 밤 열려요. 당신도 오시나요?', `FemaleText_loc4`='今晚就是云游节了。你要来参加吗？', `FemaleText_loc5`='今晚就是遊子節了。你會來嗎?', `FemaleText_loc7`='Esta noche es el Festival del Errante. ¿Vas a venir?' WHERE `ID`=65942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유랑객의 축제가 뭡니까?', `MaleText_loc4`='云游节是什么？', `MaleText_loc5`='什麼是遊子節?', `MaleText_loc7`='¿Qué es el Festival del Errante?', `FemaleText_loc1`='유랑객의 축제가 뭐죠?', `FemaleText_loc4`='云游节是什么？', `FemaleText_loc5`='什麼是遊子節?', `FemaleText_loc7`='¿Qué es el Festival del Errante?' WHERE `ID`=65943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면 리우 랑이 어느 날 커다란 거북을 타고 판다리아 너머의 바다를 탐험하러 떠났다고 합니다. 그런데 몇 년마다 한 번씩 돌아와서 함께 여행할 탐험가를 찾았다고 하지요. 지금까지도, 판다렌이 공상에 빠져 있거나 멍하니 먼 곳을 보고 있으면 "거북을 기다린다"라고 말하지요.$b$b판다렌은 대개 모험심이 강하진 않습니다. 집에서 따뜻한 난로 곁에 있고 싶어 하지요. 하지만 공상가도 있기는 있습니다... 오늘 우리는 남쪽 바다 앞 거북 해안에 모여서 바다를 바라보며 리우 랑의 모험심을 기리지요.$b$b그것을 유랑객의 축제라고 합니다.', `MaleText_loc4`='相传刘浪曾经骑在一只巨龟背上，去探索潘达利亚之外的广阔海域。他每隔几年会回来一次，并邀请新的探险家与他同行。直到今天，每当有熊猫人做白日梦或者呆望天空的时候，我们便会问他们是不是在“等待海龟”。$b$b大部分熊猫人并不爱冒险。他们喜欢温暖舒适的居家生活。但我们中仍然有一些梦想家……今晚我们将聚集在南部海岸的海龟沙滩眺望大海，纪念刘浪的冒险精神。$b$b这就是“云游节”。', `MaleText_loc5`='傳說劉浪曾經坐在巨龜的背上出海去探索潘達利亞以外的海域。每過幾年他就會回來，每次都會尋求新的探險家和他一起旅行。直到今日，每當熊貓人在做白日夢或舉目遠望時，我們會問他們是不是在「等待海龜」。$b$b大部分的熊貓人不是很有冒險精神，他們喜歡待在靠近爐子和家的地方。但我們有些人依然是夢旅者...今晚我們將聚集在南岸的海龜海灘，遠眺海洋並讚揚劉浪的冒險精神。$b$b這被稱為遊子節。', `MaleText_loc7`='Cuenta la leyenda que una vez Liu Lang se fue para explorar los mares más allá de Pandaria a lomos de una tortuga gigante. Volvía cada pocos años, siempre en busca de exploradores que viajaran con él. Hoy en día, cada vez que un pandaren sueña despierto o se queda mirando al infinito, le decimos que está "esperando a la tortuga".$b$bLa mayoría de los pandaren no son muy aventureros... Les gusta quedarse cerca de su tierra y de su hogar. Pero algunos somos soñadores... Esta noche nos reunimos en la Playa de la Tortuga, en la costa sur, para observar el mar y celebrar el espíritu aventurero de Liu Lang.$b$bY eso se llama el Festival del Errante.', `FemaleText_loc1`='전설에 따르면 리우 랑이 어느 날 커다란 거북을 타고 판다리아 너머의 바다를 탐험하러 떠났다고 해요. 그런데 몇 년마다 한 번씩 돌아와서 함께 여행할 탐험가를 찾았다고 하죠. 지금까지도, 판다렌이 공상에 빠져 있거나 멍하니 먼 곳을 보고 있으면 "거북을 기다린다"라고 말해요.$b$b판다렌은 대개 모험심이 강하진 않아요. 집에서 따뜻한 난로 곁에 있고 싶어 하죠. 하지만 공상가도 있기는 있어요... 오늘 우리는 남쪽 바다 앞 거북 해안에 모여서 바다를 바라보며 리우 랑의 모험심을 기리지요.$b$b그것을 유랑객의 축제라고 해요.', `FemaleText_loc4`='相传刘浪曾经骑在一只巨龟背上，去探索潘达利亚之外的广阔海域。他每隔几年会回来一次，并邀请新的探险家与他同行。直到今天，每当有熊猫人做白日梦或者呆望天空的时候，我们便会问他们是不是在“等待海龟”。$b$b大部分熊猫人并不爱冒险。他们喜欢温暖舒适的居家生活。但我们中仍然有一些梦想家……今晚我们将聚集在南部海岸的海龟沙滩眺望大海，纪念刘浪的冒险精神。$b$b这就是“云游节”。', `FemaleText_loc5`='傳說劉浪曾經坐在巨龜的背上出海去探索潘達利亞以外的海域。每過幾年他就會回來，每次都會尋求新的探險家和他一起旅行。直到今日，每當熊貓人在做白日夢或舉目遠望時，我們會問他們是不是在「等待海龜」。$b$b大部分的熊貓人不是很有冒險精神，他們喜歡待在靠近爐子和家的地方。但我們有些人依然是夢旅者...今晚我們將聚集在南岸的海龜海灘，遠眺海洋並讚揚劉浪的冒險精神。$b$b這被稱為遊子節。', `FemaleText_loc7`='Cuenta la leyenda que una vez Liu Lang se fue para explorar los mares más allá de Pandaria a lomos de una tortuga gigante. Volvía cada pocos años, siempre en busca de exploradores que viajaran con él. Hoy en día, cada vez que un pandaren sueña despierto o se queda mirando al infinito, le decimos que está "esperando a la tortuga".$b$bLa mayoría de los pandaren no son muy aventureros... Les gusta quedarse cerca de su tierra y de su hogar. Pero algunos somos soñadores... Esta noche nos reunimos en la Playa de la Tortuga, en la costa sur, para observar el mar y celebrar el espíritu aventurero de Liu Lang.$b$bY eso se llama el Festival del Errante.' WHERE `ID`=65944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 유랑객의 축제랍니다, $n 님! 모험심 강한 판다렌들이 모여서 안개 너머로 간 최초의 탐험가를 기리는 축제지요.$b$b사색에 잠기고 노래를 부르는 시간입니다. 와 주셔서 감사합니다!', `MaleText_loc4`='这就是云游节，$n！具有冒险精神的熊猫人在这里聚集一堂，庆祝第一位冒险穿越迷雾的探险家。$b$b这是沉思和歌颂的时刻。感谢你的加入！', `MaleText_loc5`='這就是遊子節，$n!擁有冒險精神的熊貓人會聚集於此，然後讚揚第一個冒險前往迷霧彼方的探險家。$b$b這是屬於沉思與歌謠的時間。謝謝你加入我們!', `MaleText_loc7`='¡Esto es el Festival del Errante, $n! Donde los pandaren de espíritu aventurero se reúnen para celebrar al primer explorador que atravesó la niebla.$b$bEs un momento de reflexión y música. ¡Gracias por venir!', `FemaleText_loc1`='이게 유랑객의 축제랍니다, $n 님! 모험심 강한 판다렌들이 모여서 안개 너머로 간 최초의 탐험가를 기리는 축제죠.$b$b사색에 잠기고 노래를 부르는 시간이에요. 와 주셔서 감사해요!', `FemaleText_loc4`='这就是云游节，$n！具有冒险精神的熊猫人在这里聚集一堂，庆祝第一位冒险穿越迷雾的探险家。$b$b这是沉思和歌颂的时刻。感谢你的加入！', `FemaleText_loc5`='這就是遊子節，$n!擁有冒險精神的熊貓人會聚集於此，然後讚揚第一個冒險前往迷霧彼方的探險家。$b$b這是屬於沉思與歌謠的時間。謝謝你加入我們!', `FemaleText_loc7`='¡Esto es el Festival del Errante, $n! Donde los pandaren de espíritu aventurero se reúnen para celebrar al primer explorador que atravesó la niebla.$b$bEs un momento de reflexión y música. ¡Gracias por venir!' WHERE `ID`=65945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이라도 있습니까?', `MaleText_loc4`='这里在举行什么活动？', `MaleText_loc5`='這裡是什麼狀況?', `MaleText_loc7`='¿De qué va esto?', `FemaleText_loc1`='무슨 일이라도 있나요?', `FemaleText_loc4`='这里在举行什么活动？', `FemaleText_loc5`='這裡是什麼狀況?', `FemaleText_loc7`='¿De qué va esto?' WHERE `ID`=65946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님! 이건 "유랑객의 축제"라고 해요. 최초의 판다렌 탐험가의 행적을 기리고, 해안에 모여서 바다를 바라보는 축제지요.$b$b판다리아를 감싼 안개가 너무나 짙어서, 저기 해안 바로 앞에 있는 큰 바위마저도 안 보이던 시절이 있었어요. 하지만 오늘은 정말 아름다운 밤이죠! 와서 우리와 함께해 주셔서 기뻐요.', `FemaleText_loc4`='欢迎光临，$n！$b$b这是“云游节”，我们都聚集在海滩上眺望大海，以纪念第一个熊猫人探险家的事迹。$b$b笼罩潘达利亚的迷雾曾经非常浓密，那时你甚至看不到近海处的大岩石。现在再看看这里，多么美丽的夜晚啊！我很高兴你能来这里参加这个盛会。', `FemaleText_loc5`='歡迎，$n!$b$b這是「遊子節」，我們藉此慶祝第一位熊貓人探險家的事蹟，並聚集在海灘上凝望海的另一邊。$b$b曾經，籠罩潘達利亞的迷霧是這麼的厚，你甚至看不見岸邊的那一塊大石頭。現在看哪，多麼美麗的夜晚!很高興有你在這裡一起欣賞。', `FemaleText_loc7`='¡Te doy la bienvenida, $n!$b$bEste es el "Festival del Errante," en el que celebramos las hazañas del primer explorador pandaren y nos reunimos en la playa para estar cerca del mar.$b$bHubo un tiempo en que la niebla que cubría Pandaria era tan densa que, en ocasiones, no se podía ver aquella enorme roca de la costa. Pero mírala ahora... ¡hace una noche maravillosa! Me alegro de que estés aquí para ver esto.' WHERE `ID`=65947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전승지기 초 님! 우리를 찾아 주셔서 기뻐요.', `FemaleText_loc4`='游学者周卓！我很高兴你能和我们一起度过这一周。', `FemaleText_loc5`='博學行者阿洲!真高興有你跟我們一起渡過這個禮拜。', `FemaleText_loc7`='¡Eremita Cho! Me alegro mucho de que estés con nosotros esta semana.' WHERE `ID`=65948;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='리우 랑의 노래를 불러 주시겠어요?', `FemaleText_loc4`='你可以为我们唱刘浪之歌吗？', `FemaleText_loc5`='你能替我們詠唱劉浪之歌嗎?', `FemaleText_loc7`='¿Podrías cantarnos la canción de Liu Lang?' WHERE `ID`=65949;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목소리가 정말 아름답네요. 초 님의 노래를 듣다 보면 마치 관현악단의 연주를 듣는 것만 같아요!', `FemaleText_loc4`='你的声音太动人了。有时我甚至觉得能在你的歌声中听到整支乐队的美妙乐音！', `FemaleText_loc5`='你的音色太美了。我發誓，有時候在你唱歌時我彷彿能聽到整支管弦樂團的聲音!', `FemaleText_loc7`='Tienes una voz preciosa. ¡A veces te juro que puedo oír a toda una orquesta cuando cantas!' WHERE `ID`=65950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 전승지기님!', `FemaleText_loc4`='游学者，谢谢你！', `FemaleText_loc5`='謝謝你，博學行者!', `FemaleText_loc7`='¡Gracias, eremita!' WHERE `ID`=65951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 자네가 우리와 함께 유랑객의 축제를 즐기다니 기쁘군!$b$b판다렌은 모험심이 강한 편은 아니라고들 하지. 하지만 이들의 얼굴을 보게. 그래, 보이는가? 공상가의 반짝이는 눈을 하고 있어!$b$b곧 온 세상을 누비며 활약하는 판다렌 모험가들의 이야기가 들려올 거라고 나는 믿네! 자넨 어떤가?', `MaleText_loc4`='$n！很高兴看到你来和我们一起庆祝云游节！$b$b人们常说熊猫人不是探险的料。但是看看周围的这些人的脸庞，啊，你看到了吗？这些属于梦想家的闪亮眼睛！$b$b我相信不久的将来，就会出现更多被世人传颂的熊猫人冒险家，他们会遍布世界的各个角落并有所作为。你不这样觉得吗？', `MaleText_loc5`='$n!我很高興見到你在和我們一起慶祝遊子節!$b$b常有人說熊貓人不是喜愛冒險的種族。但看看四周這些面孔，啊，你看見了嗎?夢旅者眼中充滿的光芒!$b$b我認為不久後的有一天，將會有更多的熊貓人探險家可以讓人談論，並在世界各地發揮影響力。你不覺得嗎?', `MaleText_loc7`='¡$n! Me alegra verte celebrando el Festival del Errante con nosotros.$b$bA menudo se dice que los pandaren no somos muy aventureros, pero mira las caras que te rodean... ¿Lo ves? ¡Son los ojos estrellados de los soñadores!$b$bCreo que un día, pronto, habrá muchos más pandaren aventureros recorriendo el mundo. ¿Tú no?' WHERE `ID`=65952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 정말 놀랄 일이 하나 있네. 이들이 뭘 기리는 것 같은가? 또 이 날을 기념하기 위해 무슨 술을 마셔야 한다고 생각하는가?', `MaleText_loc4`='我要给你一个惊喜。你猜他们正在庆祝什么？你认为庆祝这个节日，喝什么比较合适呢？', `MaleText_loc5`='有個驚喜要給你。你以為他們在慶祝什麼?還有你認為什麼才是能夠代表這場合的適當飲料呢?', `MaleText_loc7`='Tengo una sorpresa para ti. ¿Qué crees que están celebrando? ¿Y cuál crees que sería la bebida adecuada para la ocasión?' WHERE `ID`=65953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와, 굉장하네요! 저 불빛 좀 보세요!$b$b뭘 하는 걸까요? 거북 등에 탄 저 사람은 누구죠?$b$b자아아암깐! 저건 혹시 리우 랑?$b$b그럼 저 거북이 셴진 수겠군요. 역시! 저건 작은 아기 유랑도의 석상이에요!$b$B우린 고향에 온 거예요, 첸 아저씨!$b$b뭐, 그 비슷하다고요.', `FemaleText_loc4`='哇，不可思议！快看这些灯！$b$B你觉得那是什么？骑在海龟背上的那个家伙是谁？$b$b等等，那是刘浪吗？$b$b那只海龟肯定就是神真子了。没错！那座雕像就是一座微缩的迷踪岛！$b$B陈叔，我们回到家了！$b$b嗯，几乎算到家了。', `FemaleText_loc5`='哇，太棒了!看看那些光線!$b$b你想是發生什麼事了?在烏龜上的那傢伙是誰?$b$b等等!!!!那是劉浪嗎?$b$b那烏龜肯定是神真子。真的是!那雕像刻的是小寶寶漂流島!$b$b我們到家了，老陳叔叔!$b$b某種層面上啦。', `FemaleText_loc7`='¡Guau, increíble! ¡Mira todas esas luces!$b$B¿Qué crees que está pasando? ¿Quién es el tipo que está encima de la tortuga?$b$bEspeeera... ¿es ese Liu Lang?$b$bEsa tortuga debe de ser Shen-zin Su. ¡Claro que es! ¡Esa estatua es de una Isla Errante diminuta!$b$B¡Estamos en casa, tío Chen!$b$bBueno, más o menos.' WHERE `ID`=65954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가쉬눌의 폭풍 토템을 피하거나 파괴하십시오.', `MaleText_loc4`='避开或者破坏嘎什努尔的风暴图腾。', `MaleText_loc5`='避開或摧毀加須奴的風暴圖騰。', `MaleText_loc7`='Evita los tótems de tormenta de Gash''nul o destrúyelos.' WHERE `ID`=65955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 와이번에서 내립니다.', `MaleText_loc4`='%s从他的驭风者上下来了。', `MaleText_loc5`='%s從雙足飛龍的背上下來。', `MaleText_loc7`='%s se ha desmontado de su jinete del viento.' WHERE `ID`=65956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='콰쾅 아직 멀쩡하게 맥주 터뜨리고 있다!', `MaleText_loc4`='巴巴姆还没醉，巴巴姆还能喝！', `MaleText_loc5`='砰嘎還活著砰嘎那些酒!', `MaleText_loc7`='¡Ba-Bam todavía jeringa!' WHERE `ID`=65957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이처럼 춤추는구나!', `MaleText_loc4`='来跳支猢狲舞吧！', `MaleText_loc5`='像隻猴子般跳舞!', `MaleText_loc7`='¡Bailando komo makaku!' WHERE `ID`=65958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이이야아아! 나 맥주 가졌다.', `MaleText_loc4`='嘿呀！我这儿有酒。', `MaleText_loc5`='嘿呀!我搶到酒了!', `MaleText_loc7`='¡Holaaa! Tengo brebaje.' WHERE `ID`=65959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우키 아직도 요리랑 양조랑 한다!', `MaleText_loc4`='乌克还在做饭和酿酒！', `MaleText_loc5`='烏奇還是活蹦亂跳!', `MaleText_loc7`='¡Ookie sigue kocinando y preparando!' WHERE `ID`=65960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그루카 그루카가 잔치 분위기 띄울 거다!', `MaleText_loc4`='戈卡戈卡要点亮这个派对！', `MaleText_loc5`='鍋卡蟈卡要讓派對更精彩!', `MaleText_loc7`='¡Grooka Grooka va a traer alegría a la fiesta!' WHERE `ID`=65961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 새끼 운룡과 공놀이를 하고 싶습니다.', `MaleText_loc4`='我想跟翔龙宝宝练习接球。', `MaleText_loc5`='我想要和一隻蛟龍幼龍練習傳接球。', `MaleText_loc7`='Me gustaría practicar con un bebé dragón.', `FemaleText_loc1`='제 새끼 운룡과 공놀이를 하고 싶어요.', `FemaleText_loc4`='我想跟翔龙宝宝练习接球。', `FemaleText_loc5`='我想要和一隻蛟龍幼龍練習傳接球。', `FemaleText_loc7`='Me gustaría practicar con un bebé dragón.' WHERE `ID`=65962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='벌써 아기 용과 공놀이를 하고 계신 것 같군, $n. 한번에 용 한 마리와만 놀 수 있네.$B$B우선 지금 용과 노는 것을 마친 후에, 다음 용과 공놀이를 시작하게.', `FemaleText_loc4`='看来你已经在跟翔龙宝宝练习接球了，$n。你每次只能跟一条翔龙玩接球。$B$B在跟其他翔龙练习之前，请先完成你当前的训练课程。', `FemaleText_loc5`='看來你已經在和你的蛟龍玩傳接球了，$n。你一次只能和一條蛟龍玩傳接球。$B$B在與其他蛟龍一起練習之前，請先完成目前的訓練課程。', `FemaleText_loc7`='Parece que ya estás jugando con tu dragón, $n. Solo puedes jugar con un dragón a la vez.$b$bTermina tu sesión de entrenamiento actual antes de practicar con otro dragón.' WHERE `ID`=65963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공놀이가 끝났습니다. 용을 다시 데려가십시오.', `MaleText_loc4`='我完成练习了。请收回你的雏龙。', `MaleText_loc5`='我練習完了。請你收回你的幼龍。', `MaleText_loc7`='Ya he terminado de practicar. Toma tu prole.', `FemaleText_loc1`='공놀이가 끝났어요. 용을 다시 데려가세요.', `FemaleText_loc4`='我完成练习了。请收回你的雏龙。', `FemaleText_loc5`='我練習完了。請你收回你的幼龍。', `FemaleText_loc7`='Ya he terminado de practicar. Toma tu prole.' WHERE `ID`=65964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 아주 번쩍번쩍하는군. 마음에 든다곤 못하겠어. "사람 냄새"가 안 나는 것 같아서 말야.', `MaleText_loc4`='这里到处都熠熠生辉。我未必会喜欢这里。它似乎少了点“居家”的味道。', `MaleText_loc5`='這地方全都閃閃亮亮。我不確定我喜歡這樣。似乎少了些「陳舊」的味道。', `MaleText_loc7`='Este sitio está todo reluciente. No sé si me gusta. Creo que le falta ese olor a sitio "habitado".' WHERE `ID`=65965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬을 수색해서 보의 가마솥에 던져 넣을 맥주를 찾으십시오. 단, 보를 호위할 사람은 남겨 두십시오.', `MaleText_loc4`='在岛上搜索美酒，添加到珀的大锅里，但要留人在附近保护珀！', `MaleText_loc5`='搜索這座島嶼來為阿波的大鍋收集啤酒!但要有一個人留在附近保護阿波!', `MaleText_loc7`='¡Registra la isla en busca de brebaje para el caldero de Bo! ¡Pero no te olvides de dejar a una persona cerca para defenderlo!', `FemaleText_loc1`='섬을 수색해서 보의 가마솥에 던져 넣을 맥주를 찾으십시오. 단, 보를 호위할 사람은 남겨 두십시오.', `FemaleText_loc4`='在岛上搜索美酒，添加到珀的大锅里，但要留人在附近保护珀！', `FemaleText_loc5`='搜索這座島嶼來為阿波的大鍋收集啤酒!但要有一個人留在附近保護阿波!', `FemaleText_loc7`='¡Registra la isla en busca de brebaje para el caldero de Bo! ¡Pero no te olvides de dejar a una persona cerca para defenderlo!' WHERE `ID`=65966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탱탱공을 용에게 던진 후, 얼마나 오랫동안 떨어뜨리지 않을 수 있는지 도전해 보게! 놀이가 끝나면 다시 내게 말을 걸면 되네. 내가 용을 다시 데려다 줄 테니까. 행운을 비네!', `MaleText_loc4`='将弹力球扔向你的翔龙，看你们能让它在空中停留多长时间！完成练习后请告诉我，我会带走你的翔龙。祝你好运！', `MaleText_loc5`='把蹦蹦球丟給你的蛟龍，看看你能讓它保持在空中多久!當你不想繼續玩時來跟我說，我就會收回你的蛟龍。祝你好運!', `MaleText_loc7`='Lánzale la pelota de goma a tu dragón y prueba cuánto tiempo puedes jugar sin que caiga al suelo. Cuando hayas terminado, habla conmigo y me llevaré al dragón. ¡Buena suerte!', `FemaleText_loc1`='탱탱공을 용에게 던진 후, 얼마나 오랫동안 떨어뜨리지 않을 수 있는지 도전해 보게! 놀이가 끝나면 다시 내게 말을 걸면 되네. 내가 용을 다시 데려다 줄 테니까. 행운을 비네!', `FemaleText_loc4`='将弹力球扔向你的翔龙，看你们能让它在空中停留多长时间！完成练习后请告诉我，我会带走你的翔龙。祝你好运！', `FemaleText_loc5`='把蹦蹦球丟給你的蛟龍，看看你能讓它保持在空中多久!當你不想繼續玩時來跟我說，我就會收回你的蛟龍。祝你好運!', `FemaleText_loc7`='Lánzale la pelota de goma a tu dragón y prueba cuánto tiempo puedes jugar sin que caiga al suelo. Cuando hayas terminado, habla conmigo y me llevaré al dragón. ¡Buena suerte!' WHERE `ID`=65967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어땠나? 잘 했겠지?', `MaleText_loc4`='那么，情况如何？应该还不错吧？', `MaleText_loc5`='嗯，進行得如何?希望還不錯?', `MaleText_loc7`='¿Qué? ¿Qué tal ha ido? Espero que bien.', `FemaleText_loc1`='어땠나? 잘 했겠지?', `FemaleText_loc4`='那么，情况如何？应该还不错吧？', `FemaleText_loc5`='嗯，進行得如何?希望還不錯?', `FemaleText_loc7`='¿Qué? ¿Qué tal ha ido? Espero que bien.' WHERE `ID`=65968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고치는 중', `MaleText_loc4`='固定', `MaleText_loc5`='修理中', `MaleText_loc7`='Arreglando', `FemaleText_loc1`='고치는 중', `FemaleText_loc4`='固定', `FemaleText_loc5`='修理中', `FemaleText_loc7`='Arreglando' WHERE `ID`=65969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아의 아이들아, 안개가 걷혔다. 이게 좋은 일이든 나쁜 일이든, 우리 땅은 세상에 열렸다.', `FemaleText_loc4`='潘达利亚的子民们，迷雾已经散去。无论如何，这片土地都将对外开放。', `FemaleText_loc5`='潘達利亞的孩子們。迷霧已散去。不管好壞，大陸已經完全開放。', `FemaleText_loc7`='Hijos de Pandaria. La niebla ha caído. Para bien o para mal, nuestra tierra está abierta para todos.' WHERE `ID`=65970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 힘을 합쳐 이 신성한 장소를 되살리자. 전쟁에 망가진 이 세상을 치유하는 첫 번째 단계이지.', `FemaleText_loc4`='让我们团结一致，重建这片神圣的土地，向治愈这个破碎的世界迈出第一步。', `FemaleText_loc5`='讓我們團結起來，一起重建這個神聖的地方，開始治療這個被戰火肆虐的世界。', `FemaleText_loc7`='Unámonos para reconstruir este lugar sagrado, será el primer paso en la sanación de un mundo destrozado por la guerra.' WHERE `ID`=65971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 안개 너머에서 온 자들을 믿는다.', `MaleText_loc4`='我信任来自迷雾之外的朋友们。', `MaleText_loc5`='我對那些從迷霧彼端過來的朋友有信心。', `MaleText_loc7`='Yo tengo fe en nuestros amigos de más allá de la niebla.' WHERE `ID`=65972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 이들의 힘은 귀감이 된다. 그렇기에 우리에게 꼭 필요하지. 그들의 마음이 순수하다는 것을 믿어야 한다.', `MaleText_loc4`='嗯……这股力量是种鼓舞……至关重要。要相信他们的心是纯洁的。', `MaleText_loc5`='能鼓舞人心的力量...正是我們迫切需要的。我們必須相信他們有顆純潔的心靈。', `MaleText_loc7`='Su fuerza es una inspiración muy necesaria. Debemos confiar en la pureza de su corazón.' WHERE `ID`=65973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱... 하나만... 더!', `MaleText_loc4`='只要……再来……一次！', `MaleText_loc5`='只要...再接...一球!', `MaleText_loc7`='¡Solo... uno... más!' WHERE `ID`=65974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가... 근처에...', `MaleText_loc4`='联盟……在逼近……', `MaleText_loc5`='聯盟...接近...', `MaleText_loc7`='Alianza... cerca...' WHERE `ID`=65975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 네게 주마. 가서 우리의 적을 무찔러라!', `MaleText_loc4`='我的力量就是你的力量。让我们一起去消灭我们的敌人吧！', `MaleText_loc5`='讓我的力量成為你的力量。去將我們的敵人消滅!', `MaleText_loc7`='Que mi fuerza sea la tuya. ¡Ve y destruye a nuestros enemigos!' WHERE `ID`=65976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 페로몬은 다수의 적을 상대할 때 아주 유용할 것이다.', `MaleText_loc4`='在对付多个敌人时，我的信息素将会有所帮助。', `MaleText_loc5`='我的費洛蒙在對付多個敵人的時候應該會很有用。', `MaleText_loc7`='Mis feromonas te vendrán bien a la hora de luchar contra varios enemigos.' WHERE `ID`=65977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장치를 작동시키십시오.', `MaleText_loc4`='快去打开这个东西。', `MaleText_loc5`='沒問題，去啟動它吧。', `MaleText_loc7`='Adelante, enciéndelo.', `FemaleText_loc1`='장치를 작동시키세요.', `FemaleText_loc4`='快去打开这个东西。', `FemaleText_loc5`='沒問題，去啟動它吧。', `FemaleText_loc7`='Adelante, enciéndelo.' WHERE `ID`=65978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니, 아니에요. 일어나지 마세요. 당신이 싸울 곳은 여기가 아니에요. 좀 쉬세요.', `FemaleText_loc4`='不，不，不要起来。这里没有战争，士兵，你需要休息。', `FemaleText_loc5`='不不，別起身。你的戰場不在這裡，士兵。你需要休息。', `FemaleText_loc7`='No, no, no intentes levantarte. Tu guerra no es esa, soldado; necesitas descansar.' WHERE `ID`=65979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s|1이;가; |cFFFF0000|Hspell:126299|h[영혼 방출]|h|r을 시전하기 시작합니다! 물속에 들어가십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s开始施放|cFFFF0000|Hspell:126299|h[灵魂释放]|h|r！快跳进水里！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s開始施放|cFFFF0000|Hspell:126299|h[靈魂釋放]|h|r!快跳進水中!', `MaleText_loc7`='|TInterfaceIconsability_warlock_soulsiphon:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:126299|h[Desatar almas]|h|r! ¡Métete en el agua!' WHERE `ID`=65980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 구조가 묘하군. 전통적인 모구 건축 양식과는 여러 모로 다르네. 이 방도 일종의 장치인 듯한데, 내 기록에는 그 목적에 대한 내용이 없네. 
$b그걸 알아내려면, 장치를 작동시킨 다음에 관찰하는 수밖에 없지.
$b뭐, 나빠도 얼마나 나쁘겠나?', `MaleText_loc4`='这里的建筑很奇怪，与传统的魔古族设计风格有很多不同之处。这个房间似乎是某种装置，但是从我的笔记上看不出它的用途。
$b我们只有去激活它然后观察，才能弄清其用途。
$b最糟糕的情况会是什么呢？', `MaleText_loc5`='這裡的建築結構很奇怪，和傳統的魔古設計有很多的不同之處。這個房間似乎是某種裝置，但我在我的筆記中找不到任何關於其用途的記載。
$b我們想查出這東西的用途只有一種方法，就是啟動它然後觀察。
$b最糟還能有什麼事發生?', `MaleText_loc7`='Esta arquitectura es extraña. Se diferencia bastante del diseño mogu tradicional. Esta sala parece ser un dispositivo de algún tipo, pero en mis notas no pone nada acerca de su propósito.
$bLa única forma de averiguar qué es es activarla y observar.
$b¿Qué es lo peor que podría pasar?' WHERE `ID`=65981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 몇 시간째 안개 속을 날고 있습니다, 장군님. 선원들이 불안해하기 시작했어요...', `MaleText_loc4`='我们在迷雾中航行了好几个小时了，将军。船员们感觉很不好……', `MaleText_loc5`='我們在這團迷霧裡已經飛了好幾個小時了，將軍。大家開始不安了...', `MaleText_loc7`='Llevamos horas volando en esta niebla, General. La tripulación empieza a inquietarse...' WHERE `ID`=65982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만해라, 병사! 죽는 한이 있어도 이 땅을 찾아야 한다.', `MaleText_loc4`='坚守岗位，士兵！就算死也要找到那片陆地。', `MaleText_loc5`='士兵，回到崗位上!我們會不計代價，找出這塊大陸。', `MaleText_loc7`='¡Vuelve a tu puesto, soldado! Encontraremos esa tierra o moriremos en el intento.' WHERE `ID`=65983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 함선이다!', `MaleText_loc4`='联盟舰船！左舷方向！', `MaleText_loc5`='聯盟船艦!在左舷!', `MaleText_loc7`='¡Barco de la Alianza a babor!' WHERE `ID`=65984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격-!', `MaleText_loc4`='攻击！', `MaleText_loc5`='攻擊!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=65985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우현에 적함이다! 포탄 장전! 사격 개시!', `MaleText_loc4`='右舷发现敌舰！炮火准备！自由射击！', `MaleText_loc5`='右舷出現敵艦!做好準備!自由開火!', `MaleText_loc7`='¡Barco enemigo a estribor! ¡Preparad las armas! ¡Fuego a discreción!' WHERE `ID`=65986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t%s|1이;가; |cFFFF0000$n|r|1을;를; 보면서 |cFFFF0000|Hspell:127245|h[치명적인 일격]|h|r을 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t%s将目光转向|cFFFF0000$n|r并开始施放|cFFFF0000|Hspell:127245|h[致命一击]|h|r！快跑开！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_charge.blp:20|t%s的視線停留在|cFFFF0000$n|r身上，並且開始施展|cFFFF0000|Hspell:127245|h[致命撞擊]|h|r!快跑!', `MaleText_loc7`='|TInterfaceIconsability_warrior_charge.blp:20|t¡%s fija su mirada en |cFFFF0000$n|r y empieza a lanzar |cFFFF0000|Hspell:127245|h[Arremetida fatal]|h|r! Muévete!' WHERE `ID`=65987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가... 여기에...', `MaleText_loc4`='部落……来了……', `MaleText_loc5`='部落...在這裡...', `MaleText_loc7`='Horda... aquí...' WHERE `ID`=65988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명중이다! 적함이 침몰한다!', `MaleText_loc4`='直接命中！她掉下去了！', `MaleText_loc5`='命中目標!它就要墜毀啦!', `MaleText_loc7`='¡Golpe directo! ¡Se hunde!' WHERE `ID`=65989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육지다!', `MaleText_loc4`='陆地，吼吼！', `MaleText_loc5`='發現陸地!', `MaleText_loc7`='¡Tierra!' WHERE `ID`=65990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 방에는 힘이 넘쳐 흐르네. 하지만 지금까지 봤던 것과는 전혀 다르군.', `MaleText_loc4`='这个房间里涌动着能量，但是和我们所见过的完全不同。', `MaleText_loc5`='這個房間充滿能量，但感覺跟之前遇過的不同。', `MaleText_loc7`='Esta sala vibra de energía, pero no se parece a nada que conozcamos.' WHERE `ID`=65991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥미롭군. 이런 이야기는 들어본 적도 없어. 모구가 비밀을 잘 숨겨뒀었군.', `MaleText_loc4`='太棒了，我从没听说过这样的事。魔古族很擅长保密。', `MaleText_loc5`='真有趣，我從沒聽過像這樣的故事。魔古保密的本事不錯。', `MaleText_loc7`='Fascinante. Nunca había oido hablar de nada de todo esto. Los mogu saben ocultar sus secretos.' WHERE `ID`=65992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 이 장치를 조종하는 단말기인 것 같군. 어디 보자...', `MaleText_loc4`='这好像是这个装置的控制终端。看这儿……', `MaleText_loc5`='這看起來像是控制裝置的終端機，我來看看...', `MaleText_loc7`='Esto parece un terminal para controlar el dispositivo. Veamos…' WHERE `ID`=65993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일 새로운 이방인들이 해안에 밀려 올라오는 것 같네요.$b$b이 녀석들은 어제 저녁까지만 해도 서로 총질을 해대고 있었어요. 앞으로도 이런 일이 계속되는 건 아니길 바랄 수 밖에요.', `MaleText_loc4`='每天都有越来越多的陌生人登上我们的海滩。$b$b直到昨天晚上，这群人才停止向对方射击。但愿这不是什么事情即将发生的预兆。', `MaleText_loc5`='每天似乎有越來越多的陌生人被沖上我們的海灘。$b$b這群人直到昨晚都還在試著要對彼此開火。我希望這不是接下來情況的徵兆。', `MaleText_loc7`='Cada día llegan más forasteros a nuestras costas.$b$bLos de esta tanda estaban intentando matarse unos a otros hasta anoche. Espero que no sea un avance de lo que está por llegar.', `FemaleText_loc1`='매일 새로운 이방인들이 해안에 밀려 올라오는 것 같네요.$b$b이 녀석들은 어제 저녁까지만 해도 서로 총질을 해대고 있었어요. 앞으로도 이런 일이 계속되는 건 아니길 바랄 수 밖에요.', `FemaleText_loc4`='每天都有越来越多的陌生人登上我们的海滩。$b$b直到昨天晚上，这群人才停止向对方射击。但愿这不是什么事情即将发生的预兆。', `FemaleText_loc5`='每天似乎有越來越多的陌生人被沖上我們的海灘。$b$b這群人直到昨晚都還在試著要對彼此開火。我希望這不是接下來情況的徵兆。', `FemaleText_loc7`='Cada día llegan más forasteros a nuestras costas.$b$bLos de esta tanda estaban intentando matarse unos a otros hasta anoche. Espero que no sea un avance de lo que está por llegar.' WHERE `ID`=65994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 이상합니다, 장군님... 고도가 떨어져요!', `MaleText_loc4`='呃，情况不对，将军……我们下降得……很快！', `MaleText_loc5`='呃...將軍，不太對勁...我們在往下墜!而且很快!', `MaleText_loc7`='Eh... Algo va mal, General. ¡Perdemos altitud! ¡Y rápido!' WHERE `ID`=65995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='센서 가동. 모든 코어 최고 효율로 작동.', `MaleText_loc4`='传感器上线。所有核心满功率运转。', `MaleText_loc5`='感應器已啟動。所有核心高效運作中。', `MaleText_loc7`='Sensores activados. Todos los núcleos operan con eficiencia óptima.' WHERE `ID`=65996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 중', `MaleText_loc4`='启用', `MaleText_loc5`='啟動中', `MaleText_loc7`='Activando', `FemaleText_loc1`='준비 중', `FemaleText_loc4`='启用', `FemaleText_loc5`='啟動中', `FemaleText_loc7`='Activando' WHERE `ID`=65997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신원 확인 결과 불일치. 미확인 개체 감지됨.', `MaleText_loc4`='认证矩阵不匹配。检测到不明物体。', `MaleText_loc5`='識別矩陣不符合。偵測到未知物體。', `MaleText_loc7`='Error de matriz de identificación. Entidades desconocidas detectadas.' WHERE `ID`=65998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:116529|h[동력 차단]|h|r을 시전합니다!', `MaleText_loc4`='%s开始施放|cFFFF0000|Hspell:116529|h[能源关闭]|h|r！', `MaleText_loc5`='%s施放|cFFFF0000|Hspell:116529|h[能量中斷]|h|r!', `MaleText_loc7`='¡%s lanza |cFFFF0000|Hspell:116529|h[Apagar]|h|r!' WHERE `ID`=65999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 말을 하다니... 우리가 생각했던 모구의 능력 이상인 것 같은데.', `MaleText_loc4`='太神奇了！它说话了……看来我们低估了魔古族的能力。', `MaleText_loc5`='真厲害!會說話呢...看起來魔古的能力比我們想像的強。', `MaleText_loc7`='¡Magnífico! Puede hablar... Esto va más allá de lo que creíamos capaces a los mogu.' WHERE `ID`=66000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 일이 복잡해지겠군. 이제 자네에게 맡겨두고, 난 안전한 곳에서 지켜보겠네.', `MaleText_loc4`='噢……这恐怕要糟糕。我还是把它留给你，然后远远地看着吧。', `MaleText_loc5`='喔老天...接下來可能會不太妙。我還是走遠一點看好了...', `MaleText_loc7`='Caray... Esto podría acabar mal. Observaré desde una distancia prudencial.' WHERE `ID`=66001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 거라도 있습니까?', `MaleText_loc4`='你需要什么东西吗？', `MaleText_loc5`='你需要任何東西嗎?', `MaleText_loc7`='¿Necesitas algo?' WHERE `ID`=66002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 적을 사냥할 겁니다.', `MaleText_loc4`='我们要追捕敌人。', `MaleText_loc5`='我們將獵殺我們的敵人。', `MaleText_loc7`='Daremos caza a nuestros enemigos.' WHERE `ID`=66003;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 적의 목을 노리는 칼날이 될 거예요.', `FemaleText_loc4`='我会成为插入敌人咽喉的那把利刃。', `FemaleText_loc5`='我會成為割開我們敵人喉嚨的刀刃。', `FemaleText_loc7`='Seré la espada en la garganta de nuestros enemigos.' WHERE `ID`=66004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기계가 파괴되었으니, 이제 모구의 힘도 약해지겠지.', `MaleText_loc4`='机器已经被摧毁了，魔古族的力量也被削弱了。', `MaleText_loc5`='機器已經摧毀了，魔古的力量應該削弱了。', `MaleText_loc7`='La máquina ha sido destruida y el poder de los mogu se debilita.' WHERE `ID`=66005;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파에게 맞서 살아날 자는 없어요.', `FemaleText_loc4`='没有人敢和影踪派作对。', `FemaleText_loc5`='沒有人能抵擋影潘。', `FemaleText_loc7`='Nadie podrá enfrentarse al Shadopan.' WHERE `ID`=66006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 원반은 낯이 익군. 하지만 어디서 온 건지는 모르겠어.', `MaleText_loc4`='这些圆盘很眼熟，但我无法找到其出处。', `MaleText_loc5`='這些圓盤看起來很眼熟，但我忘記在哪看過。', `MaleText_loc7`='Estos discos me resultan familiares, pero no recuerdo por qué...' WHERE `ID`=66007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원반들이 내게 말을 거는군... 나는...', `MaleText_loc4`='圆盘……在召唤我……我必须……', `MaleText_loc5`='這些圓盤...在呼喚我...我必須...', `MaleText_loc7`='Los discos me llaman... Debo...' WHERE `ID`=66008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이... 이제 모든 것이 분명히 보이네.', `MaleText_loc4`='我……我终于看清了一切。', `MaleText_loc5`='我...我...我現在...完全明白了。', `MaleText_loc7`='A-ahora lo veo todo claro.' WHERE `ID`=66009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄...? 모구가 고대 티탄의 기술을 발굴하고 활용해서, 자신들의 제국을 발전시키려는 모양이야!', `MaleText_loc4`='泰坦……？看来魔古族篡改了古代泰坦技术，并以此发展壮大他们的帝国！', `MaleText_loc5`='泰坦...?嗯...看起來魔古收集並重新改寫了古泰坦科技，用來發展他們的帝國!', `MaleText_loc7`='¿Los titanes? Parece que los mogu recuperaron y modificaron la antigua tecnología de los titanes para hacer prosperar su imperio.' WHERE `ID`=66010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가야 하네. 아직 끝나지 않았어.', `MaleText_loc4`='我们得走了，还有更多事情要做。', `MaleText_loc5`='我們得走了，我們還沒完成調查。', `MaleText_loc7`='Debemos irnos. Aún no hemos terminado.' WHERE `ID`=66011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붉은 연기의 텐우가 인사를 합니다.', `MaleText_loc4`='“赤烟”腾武向你问好。', `MaleText_loc5`='『人間赤煙』添武向你問好。', `MaleText_loc7`='Tenwu del Humo Rojo te saluda.' WHERE `ID`=66012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파의 적은 모조리 붉은 연기의 텐우 앞에 쓰러지리라!', `MaleText_loc4`='影踪派的所有敌人都将倒在“赤烟”腾武面前。', `MaleText_loc5`='所有的影潘之敵都將倒在『人間赤煙』添武的腳下!', `MaleText_loc7`='¡Todos los enemigos del Shadopan caerán ante Tenwu del Humo Rojo!' WHERE `ID`=66013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들을 장벽에서 계속 떨어뜨려. 라이곤이 문으로 가야 한다.', `MaleText_loc4`='别让那些弓箭手登上墙头。让莱公冲到大门前。', `MaleText_loc5`='別讓弓箭手接近長城。必須讓雷剛抵達大門。', `MaleText_loc7`='Limpien la muralla de arqueros. Raigonn debe llegar a la puerta.' WHERE `ID`=66014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 이걸 맛보시오.', `MaleText_loc4`='来……尝尝这个吧。', `MaleText_loc5`='這裡...試試看這個。', `MaleText_loc7`='Toma... prueba esto.' WHERE `ID`=66015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이런. 흠. 마음에 안 든다면... 미안하오.', `MaleText_loc4`='噢，是啊。唔，我……很抱歉没能让你称心如意……', `MaleText_loc5`='喔，沒錯。嗯，我很...抱歉這不是你所喜好的...', `MaleText_loc7`='Ah, sí. Mm. Siento... que no te haya gustado...' WHERE `ID`=66016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 여자는 뼈랑 수액으로 이루어진 것 같다오! 진짜 비위가 강하다니까...', `MaleText_loc4`='她早该变成一堆枯骨和烂泥了！她还真有一个好胃啊……', `MaleText_loc5`='她應該要化為一堆白骨和黏液才對啊!果然是『無敵鐵胃』...', `MaleText_loc7`='¡Debería ser un montón de huesos y babas! Es de estómago fuerte, desde luego...' WHERE `ID`=66017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 민족에는 두 문파가 존재한다네. 투슈이는 인내심 있고 생각이 깊으며 신중하지. 후오진은 과격하고 적극적이며 활동적이지. 두 문파 모두 우리에게 나름대로 도움을 주며, 서로가 없이는 존재할 수 없다네.', `MaleText_loc4`='在我的族人间存在两大修行戒律。土水派耐心沉稳，谨慎从容；火金派凶猛激进，活跃积极。两种戒律各有用途，而又相辅相成，缺一不可。', `MaleText_loc5`='我們的人民之間存在有兩種層面的信條。土水是耐心、深思與從容之道。火金則是狂熱、積極與進取之道。兩種規律都為我們帶來裨益，任何一種都無法脫離另一種而自存。', `MaleText_loc7`='Hay dos disciplinas entre nuestra gente. Los tushui son pacientes, reflexivos y cuidadosos. Los huojin son feroces, activos y decididos. Las dos disciplinas nos ayudan a su manera y ninguna de las dos podría existir sin la otra.' WHERE `ID`=66018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 수련장에서 추구하는 바는, 젊은 판다렌이 잠재력을 실현할 수 있게 돕는 걸세. 진정한 달인이 되기 위해서는 시간과 수련이 필요하지. 그러나 자신이 가야 할 길의 시작을 찾는 것도 대단히 가치 있는 일일세.', `MaleText_loc4`='我主要是帮助年轻的熊猫人在这些方面发掘他们的潜力。虽然真正掌握技巧需要大量的时间和练习，但首先寻找到一种合适的方法也十分重要。', `MaleText_loc5`='我盼望的只是在這裡幫助年輕熊貓人探索他們自身的潛力。真正的成就來自於大量的時間和大量的練習，但在最初找到適合自身的道路，也是具有價值的一件事。', `MaleText_loc7`='Lo que deseo por encima de todo es ayudar a los pandaren jóvenes a explorar su potencial en este lugar. La maestría auténtica llega con mucho tiempo y mucha práctica, pero encontrar el comienzo de un camino adecuado también tiene su valor.' WHERE `ID`=66019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 버... 지...', `MaleText_loc4`='父……亲……', `MaleText_loc5`='父...親...。', `MaleText_loc7`='Pa... dre...' WHERE `ID`=66020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 물론이죠.', `FemaleText_loc4`='啊，当然。', `FemaleText_loc5`='啊，當然。', `FemaleText_loc7`='Ah, claro.' WHERE `ID`=66021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='인내에서 힘을 찾으세요.', `FemaleText_loc4`='耐心地寻找你的力量。', `FemaleText_loc5`='在忍耐中找到力量。', `FemaleText_loc7`='Encuentra fuerza en la paciencia.' WHERE `ID`=66022;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와! 어, 이것 참... 희한한 맛이네요.', `FemaleText_loc4`='哇！嗯，太有趣了！', `FemaleText_loc5`='哇!呃，真是...有趣。', `FemaleText_loc7`='¡Vaya! Es, eh... interesante.' WHERE `ID`=66023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무리를 움직이는 자가 누구냐? 클락시의 물음에 답하라!', `MaleText_loc4`='是谁控制着这个虫群！出来！ 回应卡拉克西的召唤。', `MaleText_loc5`='誰掌管這批蟲群?現身吧!回答卡拉西的問題。', `MaleText_loc7`='¿Quién lidera este enjambre? ¡Aparece! Responde ante los Klaxxi.' WHERE `ID`=66024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름을 말해라. 우리가 나눌 얘기는 그것뿐이다.', `MaleText_loc4`='报上名来，傀儡，让我们的历史记载更完整些。', `MaleText_loc5`='傀儡，說出你的名字，完成我們的歷史。', `MaleText_loc7`='Revela tu nombre, insecto, para que nuestros anales estén completos.' WHERE `ID`=66025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 "폐하"는 이제 끝이야. 당장 물러서라. 아니면 죽음을 맞는 수밖에.', `MaleText_loc4`='你的“女皇”已经倒下了。卡拉克西做出了判决。让开，否则就死。', `MaleText_loc5`='你的「女皇」已經一敗塗地。卡拉西做出了裁決，退下，或被消滅。', `MaleText_loc7`='Tu "Emperatriz" ha caído. Los Klaxxi han pronunciado sentencia. Apártate o te destruiremos.' WHERE `ID`=66026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 그런 소릴!', `MaleText_loc4`='亵渎！', `MaleText_loc5`='褻瀆者!', `MaleText_loc7`='¡Blasfemia!' WHERE `ID`=66027;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음을 잘 추슬러야만 시련에 맞설 수 있습니다.', `FemaleText_loc4`='只有集中精力，才能直面任何考验。', `FemaleText_loc5`='唯有專注的心能真正準備好迎接任何試煉。', `FemaleText_loc7`='Solo la mente ordenada está preparada para cualquier juicio.' WHERE `ID`=66028;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음이 평화로워야 전투에 대비해 몸을 단련할 수 있습니다.', `FemaleText_loc4`='只有冷静的头脑能够做好战斗的准备。', `FemaleText_loc5`='只有寧靜的心能讓身體完全準備好面對戰鬥。', `FemaleText_loc7`='Solo una mente en paz puede tener un cuerpo preparado para la batalla.' WHERE `ID`=66029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='금속공학의 신비에 매료되셨습니까? 제련술은 어때요? 강철과 합금을 혼합하는 기술의 아름다움은요?', `FemaleText_loc4`='你喜欢神奇的冶金技术、奥妙的熔炼技艺、优美的合金秘法吗？', `FemaleText_loc5`='你對冶金、熔煉的奧秘感到驚嘆嗎?你能感受融合金屬來製造合金的美麗嗎?', `FemaleText_loc7`='¿Te fascinan las maravillas de la metalurgia? ¿El arte de la fundición? ¿La belleza de mezclar metales y aleaciones?' WHERE `ID`=66030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 돌아왔다.', `MaleText_loc4`='<咳嗽><结巴>我……我回来了。', `MaleText_loc5`='我...回來了。', `MaleText_loc7`='<tos> <carraspeo> He... regresado.' WHERE `ID`=66031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안전띠 매세요... 농담이에요. 우린 안전띠가 없거든요!', `MaleText_loc4`='系好你的安全带……开玩笑啦，我们没有安全带！', `MaleText_loc5`='把你的安全帶扣緊...開玩笑的，我們沒有安全帶!', `MaleText_loc7`='Abrochaos los cinturones... ¡Es broma! ¡No tenemos cinturones!', `FemaleText_loc1`='안전띠 매세요... 농담이에요. 우린 안전띠가 없거든요!', `FemaleText_loc4`='系好你的安全带……开玩笑啦，我们没有安全带！', `FemaleText_loc5`='把你的安全帶扣緊...開玩笑的，我們沒有安全帶!', `FemaleText_loc7`='Abrochaos los cinturones... ¡Es broma! ¡No tenemos cinturones!' WHERE `ID`=66032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 멀었어요?', `MaleText_loc4`='我们到了吗，雪人？', `MaleText_loc5`='我們到了嗎，雪人?', `MaleText_loc7`='¿Ya hemos llegado, yeti?', `FemaleText_loc1`='아직 멀었어요?', `FemaleText_loc4`='我们到了吗，雪人？', `FemaleText_loc5`='我們到了嗎，雪人?', `FemaleText_loc7`='¿Ya hemos llegado, yeti?' WHERE `ID`=66033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 너는 그간의 행동으로 클락시의 믿음을 얻어냈다.', `MaleText_loc4`='唤醒者，你的功劳为你赢得了我们的信任。', `MaleText_loc5`='喚醒者，你的行為贏得了卡拉西的信任。', `MaleText_loc7`='Heraldo, tus hazañas han hecho ganarte la confianza de los Klaxxi.' WHERE `ID`=66034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야크가 산길을 잘 알았으면 좋겠네요. 전 모르거든요!', `MaleText_loc4`='希望这头牦牛知道上山的路，因为我不知道！', `MaleText_loc5`='我希望這些犛牛清楚上山的路，因為我不知道!', `MaleText_loc7`='Espero que este yak sepa cómo llegar a lo alto... ¡porque yo desde luego no!', `FemaleText_loc1`='이 야크가 산길을 잘 알았으면 좋겠네요. 전 모르거든요!', `FemaleText_loc4`='希望这头牦牛知道上山的路，因为我不知道！', `FemaleText_loc5`='我希望這些犛牛清楚上山的路，因為我不知道!', `FemaleText_loc7`='Espero que este yak sepa cómo llegar a lo alto... ¡porque yo desde luego no!' WHERE `ID`=66035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네베레스트에는 처음 가는 건가요? 저도예요!', `MaleText_loc4`='这是你第一次来不息山？我也一样！', `MaleText_loc5`='這是你第一次要登上奈佛勒斯山?我也是!', `MaleText_loc7`='¿Es la primera vez que vienes a Nieverest? ¡Yo también!', `FemaleText_loc1`='네베레스트에는 처음 가는 건가요? 저도예요!', `FemaleText_loc4`='这是你第一次来不息山？我也一样！', `FemaleText_loc5`='這是你第一次要登上奈佛勒斯山?我也是!', `FemaleText_loc7`='¿Es la primera vez que vienes a Nieverest? ¡Yo también!' WHERE `ID`=66036;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투슈이의 마음가짐이 지혜에 이르는 유일한 길은 아님을 알지만, 그럼에도 받아들일 수 없는 선택은 있습니다. 너무 위험해서 해서는 안 되는 모험, 용서할 수 없는 판단이 있지요...$B$B이제 저는 셴진 수를 떠나려 합니다. 저는 델로라 라이언하트 님의 자신감과 용맹에 감탄했고, 그분에게 들은 바로는 얼라이언스가 괜찮은 이들인 듯합니다. 그곳에 정착하게 될지는 아직 모르겠지만, 저의 길이 어디로 이어지든지 이 섬 바깥의 세상에 도움이 될 방법을 찾으려 합니다.$B$B많은 일이 있었지만, 당신과 함께한 시간은 즐거웠습니다, $n 님. 저와 함께 가 주셨으면 하지만, 쉬운 결정은 아니라는 것 알고 있습니다.', `FemaleText_loc4`='我明白，土水派之道并非通向智慧之门的唯一途径。但，有些选择依然令人无法接受，有些风险仍然令人难以承担，有些决定始终让我难以原谅……$B$B现在，是我离开神真子的时候了。我敬重德罗娜·莱因哈特的信心和勇气，她口中有关联盟的故事对她的人民赞誉有加。我还不知道自己是否能在那里找到归宿，但是无论我的道路通向何方，我都会找到一个方法来帮助迷踪岛之外的世界。$B$B无论如何，我很喜欢我们共处的这段短暂时光，$n。我希望你可以和我一起走，但我明白做这个决定并不容易。', `FemaleText_loc5`='我明白土水之道並非唯一的智慧之路，但有些選擇終究是不可接受的。其中的風險太高，永遠都不該想去嘗試。我無法原諒這樣的抉擇...$b$b我離開神真子的時候到了。我欽佩戴羅拉·獅心的自信和勇氣。她口中關於聯盟的故事為她的人民下了良好的註解。我不知道自己是否能在那裡找到歸屬感，但不論我到哪裡，都能找到一條幫助那島外世界的道路。$B$B無論如何，我很喜歡我們曾一起度過的短暫時光，$n。我希望你能加入我，但我理解這並不是能輕易做出的決定。', `FemaleText_loc7`='Comprendo que el camino de los tushui no es el único hacia la sabiduría, pero desde luego hay opciones inaceptables. Riesgos demasiado peligrosos como para asumirlos. Decisiones que no puedo perdonar... $b$bEs hora de que deje a Shen-zin Su. Ha crecido mi respeto hacia Delora Corazón de León por su confianza y valor, y los cuentos de la Alianza hablan bien de su gente. Aún no sé si hallaré allí mi hogar, pero vaya donde vaya, encontraré el modo de ayudar al mundo más allá de esta isla.$B$BA pesar de todo, he disfrutado el tiempo que hemos pasado juntos, $n. Espero que te unas a mí, pero comprendo que esa no es una decisión fácil.' WHERE `ID`=66037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그 보상을 얻으리라. 잠시 걷지.', `MaleText_loc4`='你将受到嘉奖。随我来。', `MaleText_loc5`='跟我來，領取你的獎賞。', `MaleText_loc7`='Te recompensaremos. Acompáñame.' WHERE `ID`=66038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정상에 도착할 때까지는 못 쉬어! 응? 알았어?', `MaleText_loc4`='只有登上山顶，我们才能休息！嗨？明白了吗？', `MaleText_loc5`='我們在到達山頂之前都不能休息!嘿?你有聽懂嗎?', `MaleText_loc7`='¡Veremos la nieve esta en la cima! ¿Eh? ¿Lo pillas?', `FemaleText_loc1`='정상에 도착할 때까지는 못 쉬어! 응? 알았어?', `FemaleText_loc4`='只有登上山顶，我们才能休息！嗨？明白了吗？', `FemaleText_loc5`='我們在到達山頂之前都不能休息!嘿?你有聽懂嗎?', `FemaleText_loc7`='¡Veremos la nieve esta en la cima! ¿Eh? ¿Lo pillas?' WHERE `ID`=66039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사마귀족은 고대 종족이다. 너희와 손잡은 판다렌은 아이에 불과해. 물론 그들에게도 역할이 있지.', `MaleText_loc4`='我们螳螂妖是个古老的种族。你结识的熊猫人——不过是孩童。他们有自己要扮演的角色。', `MaleText_loc5`='我們螳螂人是古老的種族，與你來往的熊貓人一族跟我們相比...就像孩子罷了。他們有他們的使命。', `MaleText_loc7`='Los mántides somos una raza antigua. Los pandaren con los que tratas no son más que niños. Tienen su propia misión.' WHERE `ID`=66040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순환의 때마다, 우리 어린것들이 판다렌의 장벽을 덮친다. 약자는 죽고, 강자만 돌아오지.', `MaleText_loc4`='每次轮回，我们年轻的虫群涌上长城。熊猫人杀光弱者。而强者得以返回。', `MaleText_loc5`='每次循環，新生的螳螂人朝長城進攻，弱的被殺了，強的存活回來。', `MaleText_loc7`='Cada ciclo, nuestros jóvenes arrasan sus murallas. Los pandaren matan a los débiles. Los fuertes regresan.' WHERE `ID`=66041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 세대를 거듭하며, 우리는 더욱 강해진다.', `MaleText_loc4`='代代繁衍，我们变得越发强大。', `MaleText_loc5`='因此每過一個世代，我們就變得更加強壯。', `MaleText_loc7`='Cada generación nos volvemos más fuertes.' WHERE `ID`=66042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 역시 수레를 점검 받는 편이 좋았을지도.', `MaleText_loc4`='嗯，也许我应该将小货车带来，这样操作起来会更方便一些。', `MaleText_loc5`='嗯嗯，也許我畢竟還是應該把推車送去調整一下。', `MaleText_loc7`='Mmm, a lo mejor debería haber llevado el carro a revisar después de todo.', `FemaleText_loc1`='흠, 역시 수레를 점검 받는 편이 좋았을지도.', `FemaleText_loc4`='嗯，也许我应该将小货车带来，这样操作起来会更方便一些。', `FemaleText_loc5`='嗯嗯，也許我畢竟還是應該把推車送去調整一下。', `FemaleText_loc7`='Mmm, a lo mejor debería haber llevado el carro a revisar después de todo.' WHERE `ID`=66043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 문명이 시작되기 전, 우리 제국은 광활했다. 형제 왕국인 안퀴라즈, 아졸네룹과 함께 세상을 호령했지.', `MaleText_loc4`='在你们之前，我们的帝国早已广大无边。我们与姐妹王国安其拉和艾卓-尼鲁布平分这个世界。', `MaleText_loc5`='在你們的歷史開始前，我們的帝國雄霸一方，與姊妹王朝安其拉與阿茲歐-奈幽，三分天下。', `MaleText_loc7`='Antes de que comenzara nuestra historia, el imperio era extenso. Compartíamos el mundo con nuestros reinos gemelos, Ahn''Qiraj y Azjol-Nerub.' WHERE `ID`=66044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 신은 수가 많고 강력했어. 우린 이샤라즈의 일곱 머리를 섬겼지.', `MaleText_loc4`='我们的神祗众多而强大。我们螳螂妖崇拜的是七首亚煞极。', `MaleText_loc5`='我們有許多神，個個力量強大。我們螳螂人侍奉的是七頭的亞煞拉懼。', `MaleText_loc7`='Nuestros dioses eran muchos y poderosos. Adorábamos a las siete cabezas de Y''Shaarj.' WHERE `ID`=66045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신은 위대했고, 그 분노는 끔찍했다. 이샤라즈는 희망을 삼키고 절망을 불렀다. 용기를 들이마시고 공포를 내뿜었지.', `MaleText_loc4`='上古尊者很伟大，可发起怒来令人胆寒。他吞噬希冀，招引绝望；他吸进勇气，呼出恐惧。', `MaleText_loc5`='祂是偉大的上古之神，祂的兇猛最是駭人。祂吞噬希望，招致絕望;祂吸入勇氣，呼出畏懼。', `MaleText_loc7`='El Antiguo era magnífico, y su ira, terrible. Consumía la esperanza y sembraba el desaliento. Respiraba valor y exhalaba miedo.' WHERE `ID`=66046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강탈자들... 너희가 티탄이라 부르는 자들이 왔을 때, 이샤라즈는 파멸했다.', `MaleText_loc4`='被你们称为“泰坦”的篡位者到来时，亚煞极遭到了毁灭。', `MaleText_loc5`='後來篡位者出現，你們稱呼他們為「泰坦」。結果亞煞拉懼被殺了。', `MaleText_loc7`='Cuando llegaron los usurpadores, aquellos a los que llamas "titanes", destruyeron a Y''Shaarj.' WHERE `ID`=66047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 끔찍한 마지막 숨결이 이 땅을 물들였지만, 지금 남은 어둠은 과거의 영광에 비하면 그림자에 불과해.', `MaleText_loc4`='他最后的恐怖呼吸变成挥之不散的阴影，可跟他先前的荣耀相比不值一提。', `MaleText_loc5`='祂最後的恐怖之息至今還侵擾著這片大地，但此陰影比起祂過往榮耀來說根本就微不足道。', `MaleText_loc7`='Su último aliento maldice esta tierra desde entonces, pero las sombras que dejó son meros susurros de su antigua gloria.' WHERE `ID`=66048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라. 네가 자격이 있기에 말해주는 것이다.', `MaleText_loc4`='我们信任你，所以给你这个警告。', `MaleText_loc5`='現在我告訴你這些，是因為你贏得這個警訊。', `MaleText_loc7`='Te lo cuento porque te has ganado esta advertencia.' WHERE `ID`=66049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 신은 우리의 신이 아니다, 이방인이여.', `MaleText_loc4`='你的神将不再是神，外来者。', `MaleText_loc5`='你的神不是正統的神，外來者。', `MaleText_loc7`='Tus dioses no son los nuestros, forastero.' WHERE `ID`=66050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들이 돌아오면, 우리 사마귀족은 다시 한 번 그 옆에 설 것이다.', `MaleText_loc4`='一旦上古尊者归来，螳螂妖将再一次追随他们。', `MaleText_loc5`='若上古之神回來，我們螳螂人會再次侍奉祂們。', `MaleText_loc7`='Si los Antiguos vuelven algún día, los mántides volveremos a servirlos.' WHERE `ID`=66051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너희 중 현명한 자들도 그리하겠지.', `MaleText_loc4`='你们当中的智者也会如此。', `MaleText_loc5`='你們之中的聰明人也會這麼做。', `MaleText_loc7`='Los más sabios de entre ustedes harán lo mismo.' WHERE `ID`=66052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기할 건 여기까지다. 자, 보상을 받아라. 그리고 오늘 얻은 가르침을 기억해라.', `MaleText_loc4`='要说的就这么多。来吧，拿上你的奖赏。记住你今天学到的一切。', `MaleText_loc5`='我的話就說到這裡。來吧，拿走你的獎賞，記住你今天學到的東西。', `MaleText_loc7`='Eso es todo lo que debes saber. Ven, toma tu recompensa. Y recuerda lo que has aprendido hoy.' WHERE `ID`=66053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 정말 힘든 결정이 줄을 잇는구나. 그래도 우리 모두를 위해 힘들어도 과감하게 결정을 내려야 하지. 나는 해야 하는 일을 했고, 내가 그러지 않았다면 우리 모두 파멸했을지도 몰라... 하지만 슬프게도 모두 그렇게 생각하진 않는 것 같아.$B$B난 이제 셴진 수를 떠나야겠어. 이곳 사람들은 나처럼 힘든 결정을 내리지 않아도 되도록, 그리고 내가 더 큰 세상을 위해 싸울 수 있도록 말이야.$B$B코르가를 안 지는 오래 안 됐지만, 겉모습만 달랐지 형제라도 해도 될 것 같아. 코르가처럼 용감하고 명예로운 사람이라면 기꺼이 옆에 서고 싶어. 함께 했던 그 모든 일을 생각하면 너도 내 $g형제:자매;가 되면 좋을 텐데. 네가 함께 가 주면 좋겠지만, 생각이 많이 필요한 결정이란 건 알아.', `MaleText_loc4`='看来今天注定是充满了艰难抉择的一天。为了我们大家着想，我必须勇敢地面对这些抉择。我做了我必须做的事情，如果不这样做，我们可能已经全都命丧黄泉了……不幸的是，并非所有人都这样想。$B$B我想现在是时候离开神真子了，这样大家就不用为我的艰难抉择而背上负担，我也可以为更多的人继续战斗。$B$B我和科尔加相识不久，但一见如故，如果不是因为肤色不同，我们本应成为兄弟，我敬佩他的勇敢和气节，能够与他并肩作战是我的荣耀。你也本应成为我的$g兄弟:姐妹;，毕竟我们一起出生入死过。我希望你能加入我们，但我理解事情并非如此简单。', `MaleText_loc5`='這些日子似乎得做無數的困難決定。為了眾人的安危，擁有做這些決定的勇氣是十分重要的。我做的是我必須做的...但教人悲傷的是，並非所有人都這樣認為。$B$B我離開神真子的時候到了，那樣一來，這裡的人或許就能不因我所做的艱難決定而困擾，而我或許也能為了拯救一個更大的世界而戰。$B$B我只認識闊卡很短的時間，但他彷彿是我穿著不同外皮的兄弟一般。在他身上有我隨時樂意與之並肩作戰的英勇和榮耀的特質。而在我們一起經歷過那麼多事之後，你也可以像是我的$g兄弟:姊妹;一般。我希望你能加入我們，但我理解你得考慮的事情很多。', `MaleText_loc7`='El día de hoy está lleno de decisiones difíciles. Tener el valor de tomarlas es importante, por el bien de todos. Hice lo que debía, y podríamos habernos condenado si no lo hubiera hecho... pero no todo el mundo lo ve así.$b$bEs hora de irme de Shen-zin Su, de que sus habitantes queden libres de la carga de mi decisión, y de que luche por el bien de un mundo mucho más grande.$b$bConozco poco a Korga, pero podríamos haber sido hermanos si hubiera nacido con otra piel. Posee una valentía y un honor que apoyaría gustosamente. Después de todo lo que hemos pasado, tú también podrías ser mi $ghermano:hermana;. Espero que vengas con nosotros, pero entiendo que hay muchos factores a tener en cuenta.' WHERE `ID`=66054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 가족은 벌써 천 년이 넘게 비취와 보석을 조각해 왔어요. 제 솜씨를 보여드리면, 아마 깜짝 놀라실 걸요.', `FemaleText_loc4`='我的家族以制作玉石和宝石为生，这门手艺已经传承了将近十代人。我能传授给你的技艺可能会令你大吃一惊。', `FemaleText_loc5`='我的家族製作玉石和珠寶已經有將近十代的經驗了。你或許會為我所能教給你的感到驚訝。', `FemaleText_loc7`='Mi familia ha trabajado el jade y las gemas durante casi diez generaciones. Te sorprenderías con lo que te puedo enseñar a hacer.' WHERE `ID`=66055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='솔직히 말하면, 꽤 즐거워 보였어요!', `FemaleText_loc4`='我不得不承认，这非常有趣！', `FemaleText_loc5`='我不得不說，那看起來很好玩!', `FemaleText_loc7`='¡He de admitir que parecía de lo más divertido!' WHERE `ID`=66056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='게다가 친구도 새로 사귄 것 같군요.', `FemaleText_loc4`='看来你交到了一位新朋友。', `FemaleText_loc5`='看來你交了一個新朋友。', `FemaleText_loc7`='Y además has hecho un nuevo amigo.' WHERE `ID`=66057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘든 상대였네요...', `FemaleText_loc4`='他真难对付……', `FemaleText_loc5`='他可真是難纏啊...', `FemaleText_loc7`='Este era duro de pelar...' WHERE `ID`=66058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치와 집게. 망치와 집게. 하루 종일 망치와 집게.', `MaleText_loc4`='精力充沛，不知疲倦。一天到晚都在埋头苦干。', `MaleText_loc5`='錘子和火鉗。錘子和火鉗。整天都是錘子和火鉗。', `MaleText_loc7`='Yunque y martillo. Yunque y martillo. Me como un solomillo, y más yunque y martillo.' WHERE `ID`=66059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔해 밑에 치유사들이 있어. 구해야 돼!', `MaleText_loc4`='不少治疗者被困在了残骸里。救他们出来！', `MaleText_loc5`='殘骸底下有些治療師!救出他們。', `MaleText_loc7`='Hay sanadores bajo los restos del accidente. ¡Ve y sácalos de allí!' WHERE `ID`=66060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 치유사들을 찾아 여기로 데려와! 상처를 치유해야 해.', `MaleText_loc4`='帮助那些治疗者摆脱敌人！我们需要他们来这儿治愈伤口。', `MaleText_loc5`='找到治療師，幫他們脫離戰鬥。我們需要他們來傷口這裡治療!', `MaleText_loc7`='Encuentra a los sanadores y retíralos del combate. Los necesitamos aquí, en la herida.' WHERE `ID`=66061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 치유사들을 지켜! 우리 목숨이 달려 있어.', `MaleText_loc4`='别离开太远，保护治疗者！我们全指望他们了。', `MaleText_loc5`='靠緊一點，保衛這些治療師。我們的命都仰賴他們了。', `MaleText_loc7`='No te alejes, ¡y mantén a salvo a los sanadores! Nuestras vidas dependen de ello.' WHERE `ID`=66062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='치유사들이 쓰러지면, 셴진 수가 죽어. 우리 모두 죽는다고. 반드시 지켜!', `MaleText_loc4`='要是治疗者们遭遇不测，神真子和我们都死定了。保护好他们！', `MaleText_loc5`='如果失去這些治療師，神真子就會死，連同我們所有人一起喪命!保護好他們。', `MaleText_loc7`='Si perdemos a los sanadores, Shen-zin Su muere, y nosotros con él. ¡Protégelos!' WHERE `ID`=66063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자, 친구. 호드가 기다리고 있어!', `MaleText_loc4`='来吧，朋友。部落在等着我们！', `MaleText_loc5`='來吧，朋友。部落在等我們!', `MaleText_loc7`='Vamos, camarada. ¡La Horda nos aguarda!' WHERE `ID`=66064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 "대족장"이란 자가 얼마나 대단한지 보자고.', `MaleText_loc4`='让我们看看这位“大酋长”是何方神圣。', `MaleText_loc5`='來看看他們這位「大酋長」有什麼本事。', `MaleText_loc7`='Veamos de qué pasta está hecho su famoso "Jefe de Guerra".' WHERE `ID`=66065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 함께하면 호드의 힘을 이용해 더 나은 세상을 만들 수 있어!', `MaleText_loc4`='结合部落的力量，我们一起把这个世界变得更好！', `MaleText_loc5`='團結一致，我們可以用部落的力量讓世界更美好!', `MaleText_loc7`='¡Juntos aprovecharemos el poder de la Horda para crear un mundo mejor!' WHERE `ID`=66066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|t당신은 |cFFFF0000|Hspell:127275|h[사형 선고]|h|r를 받았습니다!', `MaleText_loc4`='|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|t你要被|cFFFF0000|Hspell:127275|h[处刑]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|t你被|cFFFF0000|Hspell:127275|h[處刑標記]|h|r!', `MaleText_loc7`='|TInterfaceIconswarrior_talent_icon_lambstotheslaughter.blp:20|t¡Te han |cFFFF0000|Hspell:127275|h[Marcado para la ejecución]|h|r!' WHERE `ID`=66067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<아이사는 수련에 몰두해 있는 것 같습니다.>', `FemaleText_loc4`='<艾莎似乎正沉浸在她的功课中。>', `FemaleText_loc5`='<艾莎似乎深深沉浸在她的練習中。>', `FemaleText_loc7`='<Aysa parece estar profundamente concentrada en sus ejercicios.>' WHERE `ID`=66068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 복덩이가 배우러 왔군요? 가르칠 기술이 아주 많지요.', `MaleText_loc4`='你是来学习的？真是个幸运的家伙。我能教给你很多东西。', `MaleText_loc5`='啊!幸運星來這學習的嗎?我有很多技巧可以指導你。', `MaleText_loc7`='¡Ah! ¿Un grisgrís viene a aprender? Tengo muchas cosas que enseñar.' WHERE `ID`=66069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s|1이;가; |cFFFF0000|Hspell:124967|h[힘 끌어내기]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s开始施放|cFFFF0000|Hspell:124967|h[吸取能量]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s開始施放|cFFFF0000|Hspell:124967|h[吸收能量]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_staticshock.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:124967|h[Extraer poder]|h|r!' WHERE `ID`=66070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s|1이;가; |cFFFF0000|Hspell:119360|h[힘 끌어내기]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s开始施放|cFFFF0000|Hspell:119360|h[吸取能量]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_staticshock.blp:20|t %s開始施放|cFFFF0000|Hspell:119360|h[吸收能量]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shaman_staticshock.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:119360|h[Extraer poder]|h|r!' WHERE `ID`=66071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 물약을 좋아하신다고요? 양조사들이 혼합물을 만들기도 하지만, 그건 물약이나 치료제처럼 섬세한 면이 없어요.', `FemaleText_loc4`='啊！一个药剂爱好者？酒仙们知道如何调配化合物，但却常常遗漏药剂或疗法的精细配方。', `FemaleText_loc5`='啊!喜歡藥水嗎?釀酒大師會製造一些混合物，但他們的藥水或藥劑經常會出一點小槌。', `FemaleText_loc7`='Ah, ¿te encantan las pociones? Los maestros cerveceros realizan sus propios brebajes, pero a menudo pierden algunas de las mejores recetas de una poción o remedio.' WHERE `ID`=66072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위키 필요해?', `MaleText_loc4`='你要找光板儿？', `MaleText_loc5`='你想找威奇?', `MaleText_loc7`='¿Tú llama a Wikky?', `FemaleText_loc1`='위키 필요해?', `FemaleText_loc4`='你要找光板儿？', `FemaleText_loc5`='你想找威奇?', `FemaleText_loc7`='¿Tú llama a Wikky?' WHERE `ID`=66073;
