UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 기이한 신대륙에는 약초와 치료제가 풍부합니다. 그저 무엇을 찾아야 할지 알기만 하면 됩니다.', `FemaleText_loc4`='这片陌生的新土地上长满了各种草药和药石，但你要先学会如何去寻找它们。', `FemaleText_loc5`='這奇特的新大陸有這麼多獨特的草藥和藥物。只要你知道自己要找的是什麼。', `FemaleText_loc7`='Esta extraña tierra tiene mucho que ofrecer en forma de hierbas y remedios, si sabes lo que buscas.' WHERE `ID`=66156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='릴리안의 영혼이 영혼의 세계 안으로 사라집니다! 이제 릴리안의 영혼은 피해를 입지 않습니다!', `MaleText_loc4`='莉莉安的灵魂逐融入了亡者的国度！她将免疫一切伤害！', `MaleText_loc5`='莉莉安的靈魂遁入靈魂的領域，無法受到傷害!', `MaleText_loc7`='¡El alma de Lilian desaparece en el reino de los espíritus! ¡Ahora es imposible dañarla!', `FemaleText_loc1`='릴리안의 영혼이 영혼의 세계 안으로 사라집니다! 이제 릴리안의 영혼은 피해를 입지 않습니다!', `FemaleText_loc4`='莉莉安的灵魂逐融入了亡者的国度！她将免疫一切伤害！', `FemaleText_loc5`='莉莉安的靈魂遁入靈魂的領域，無法受到傷害!', `FemaleText_loc7`='¡El alma de Lilian desaparece en el reino de los espíritus! ¡Ahora es imposible dañarla!' WHERE `ID`=66157;
