UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 태핀을 보러 왔군요. 그렇죠? 제 별명은 들어 보셨나요? 제 무두질 솜씨 때문에 사람들이 절 "무두 종결자"라고 부르던 때도 있었죠.', `MaleText_loc4`='你是来看老泰平的吗？听说过我的绰号吗？为了表现我的剥皮技艺，人们曾经称我为“理发师”。', `MaleText_loc5`='你是來找老塔乒的嗎?有聽說過我的綽號嗎?有一段時間人們因為我剝皮的技巧稱我為「美容師」。', `MaleText_loc7`='¿O sea que has venido a ver al viejo Tapin? ¿Te han contado mi apodo? Hubo una época en la que me llamaban "el barbero" por mi habilidad en desuello.' WHERE `ID`=66165;
