UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자크 초우가 툴툴거립니다.', `MaleText_loc4`='周泽客小声的嘀咕着。', `MaleText_loc5`='查克·周咕噥抱怨著。', `MaleText_loc7`='Zach Chow refunfuña.' WHERE `ID`=66177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<숨어 있는 곳에서 나타나는 사마귀>$b$b물러서라, $r.$b$b여제는 제정신이 아니다. 우리 클락시는 여제의 옥좌를 공격하려고 함께 모이고 있지만, 아직 준비되지 않았다. 그리고 너도 그렇고 말이지.$b$b곧 공격할 때가 되겠지만... 지금은 아니다.', `MaleText_loc4`='<螳螂妖从藏身处显身。>$b$b退后，$r。$b$b女皇已经疯了。我们卡拉克西正在召集人马，准备向她的王座发动突袭，但是我们尚未做好准备。你也一样。$b$b进攻的时刻即将到来……但不是现在。', `MaleText_loc5`='<螳螂人從藏身處現身。>$b$b退後，$r。$b$b女皇的心智失常。我們卡拉西正在聚集我們的軍隊要對她的王座發動攻擊，但是我們還沒有準備好。而你也還沒準備好。$b$b攻擊的時機不遠...但不是現在。', `MaleText_loc7`='<El mántide surge de su escondite.>$b$bNo te acerques, $r.$b$bLa Emperatriz no está en su sano juicio. Los Klaxxi estamos reuniendo un ejército para asaltar su trono, pero aún no estamos preparados. Tú tampoco lo estás.$b$bLa hora de atacar se acerca... pero aún no ha llegado.' WHERE `ID`=66178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 활약 덕분에, 호젠은 이제 자네들을 두려워하네. 잠시만 기다리게...', `MaleText_loc4`='多亏了你，猢狲开始忌惮你的族人了。暂且等我一下——', `MaleText_loc5`='多虧你出手，猴人現在很怕你們。請稍等我一下...', `MaleText_loc7`='Gracias a tus actos, los hozen les temen. Perdóname un segundo…' WHERE `ID`=66179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 여기 있군. 만사천 년도 넘는 시간 전에, 이 땅은 무시무시한 폭군이었던 "모구" 종족의 지배를 받았네.', `MaleText_loc4`='啊！好了。在一万四千多年以前，这整片大陆由一个名叫“魔古”的可怕督军部族统治。', `MaleText_loc5`='啊，找到了。在一萬四千年前，這整片土地是由一群好戰的恐怖種族「魔古」所統治。', `MaleText_loc7`='Aquí está. Hace 14,000 años, toda esta tierra estaba gobernada por una terrible raza de señores de la guerra llamados "mogu".' WHERE `ID`=66180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 공포로 이 땅을 지배했지만... 첫 판다렌 수도사들이 백성들에게 용기를 가르치면서, 모두 달라졌네.', `MaleText_loc4`='魔古族用恐惧统治臣民，用恐惧维持强权……直到第一代熊猫人武僧激发了人民的勇气。', `MaleText_loc5`='魔古以恐懼進行統治。而恐懼讓他們保有權力...直到第一位熊貓人武僧教導我們「勇氣」。', `MaleText_loc7`='Los mogu se valían del miedo para mantenerse en el poder... hasta que los primeros monjes pandaren inculcaron valor a mi pueblo.' WHERE `ID`=66181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고, 모구의 시대는 끝났지.', `MaleText_loc4`='于是魔古族的政权被推翻了。', `MaleText_loc5`='然後我們就推翻了魔古。', `MaleText_loc7`='Acabaron por derrocar a los mogu.' WHERE `ID`=66182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포로 백성을 이끄는 자는, 용기가 없는 백성들만 지배할 수 있다네.', `MaleText_loc4`='你看，凭恐惧统治的帝王，只能在臣民缺乏勇气时才能永掌大权。', `MaleText_loc5`='你懂吧，透過恐懼領導的人只能在被統治的人缺乏勇氣時維持統治。', `MaleText_loc7`='¿Entiendes? Los que gobiernan mediante el miedo solo conservan el poder si a sus súbditos les falta valor.' WHERE `ID`=66183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 알기 힘든 종족이지만, 겁쟁이는 아니네. 두려움도 금세 극복할 거야. 싸우기 싫다면... 일깨워 줘야 해!', `MaleText_loc4`='猢狲有许多特点，但并不懦弱——至少不会一直懦弱。如果你不想和他们交战，就必须……激励他们！', `MaleText_loc5`='猴人缺點不少，但他們不是膽小鬼。至少不會害怕太久。如果你不想跟他們打下去，你必須...鼓舞他們!', `MaleText_loc7`='Los hozen serán muchas cosas, pero no son cobardes. No por mucho tiempo. Si no quieres enfrentarte a ellos... ¡inspíralos!' WHERE `ID`=66184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 도와주겠네. 하지만 우선 자네들에 대해 조금 더 알고 싶군. 잠시만 나와 함께 가겠나?', `MaleText_loc4`='我会帮助你，可我想先对你的族人有所了解。你愿意花点时间随我走走吗？', `MaleText_loc5`='我會幫你，但我想先進一步了解你們的種族。你願意跟我一起走一會兒嗎?', `MaleText_loc7`='Te ayudaré, pero antes me gustaría saber algunas cosas sobre tu pueblo. ¿Quieres pasear conmigo un rato?' WHERE `ID`=66185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 이요쿠크. [클락시 강화 효과]', `MaleText_loc4`='我今天需要你的帮忙，伊约库克。', `MaleText_loc5`='協助我，尹幽卡。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Iyyokuk. [Mejora Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 이요쿠크. [클락시 강화 효과]', `FemaleText_loc4`='我今天需要你的帮忙，伊约库克。', `FemaleText_loc5`='協助我，尹幽卡。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Iyyokuk. [Mejora Klaxxi]' WHERE `ID`=66186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 무리지기여. [클락시 증강 효과]', `MaleText_loc4`='我今天需要你的帮忙，虫群卫士。', `MaleText_loc5`='協助我，蟲群守護者。(卡拉西增強效果)', `MaleText_loc7`='Préstame tu ayuda, Guardaenjambres. [Aumento Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 무리지기여. [클락시 증강 효과]', `FemaleText_loc4`='我今天需要你的帮忙，虫群卫士。', `FemaleText_loc5`='協助我，蟲群守護者。(卡拉西增強效果)', `FemaleText_loc7`='Préstame tu ayuda, Guardaenjambres. [Aumento Klaxxi]' WHERE `ID`=66187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 메뚜기왕이여. [클락시 증강 효과]', `MaleText_loc4`='我今天需要你的帮忙，暴食蝗。', `MaleText_loc5`='協助我，暴虐蝗蟲。(卡拉西強化效果)', `MaleText_loc7`='Préstame tu ayuda, Langosta. [Aumento Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 메뚜기왕이여. [클락시 증강 효과]', `FemaleText_loc4`='我今天需要你的帮忙，暴食蝗。', `FemaleText_loc5`='協助我，暴虐蝗蟲。(卡拉西強化效果)', `FemaleText_loc7`='Préstame tu ayuda, Langosta. [Aumento Klaxxi]' WHERE `ID`=66188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제게 도움을 주십시오, 배후자여. [클락시 증강 효과]', `MaleText_loc4`='我今天需要你的帮忙，操纵者。', `MaleText_loc5`='協助我，操縱者。(卡拉西增強效果)', `MaleText_loc7`='Préstame tu ayuda, Manipulador. [Aumento Klaxxi]', `FemaleText_loc1`='제게 도움을 주세요, 배후자여. [클락시 증강 효과]', `FemaleText_loc4`='我今天需要你的帮忙，操纵者。', `FemaleText_loc5`='協助我，操縱者。(卡拉西增強效果)', `FemaleText_loc7`='Préstame tu ayuda, Manipulador. [Aumento Klaxxi]' WHERE `ID`=66189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 처치할 때마다, 내 회전 칼날 능력의 사용법을 알게 될 것이다. 적이 너를 공격하도록 놓아두어라. 그러면 그 공격을 맞는 대신 네가 적을 공격하게 될 것이다.', `MaleText_loc4`='在杀死一个敌人的时候，你将可以使用我的利刃回旋技能。你可以任凭敌人攻击你，这些攻击都将转嫁到他们自己身上。', `MaleText_loc5`='當你殺死一名敵人，你將會獲得使用迴刃反擊技能的能力。當你的敵人試著攻擊你時，你就會對他們進行反擊。', `MaleText_loc7`='Al matar a un enemigo, podrás utilizar mi facultad Giro de hojas. Que tus enemigos intenten atacarte; serás tú quien les golpee a ellos.' WHERE `ID`=66190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 마지막 검은용이신 왕자님을 섬긴다.$b$b내게 불만이 있으면 왕자님께 말씀드려라.', `MaleText_loc4`='我为那位大人效力，他是该族最后的血脉。$b$b如果你对我有意见，就去向王子殿下诉说吧。', `MaleText_loc5`='我服侍殿下，他是家族中最後一人。$b$b如果你對我有意見，去和王子談談。', `MaleText_loc7`='Sirvo a su majestad, el último de su linaje.$b$bSi tienes algún problema conmigo, háblalo con el príncipe.', `FemaleText_loc1`='전 그냥 이것저것 살피고 있을 뿐입니다. 그게 잘못은 아니잖아요?$b$b누군가의 손에 들어가야 할 소식이 있다면, 제가 전해드리지요. 그런 게 아니라면 가던 길 가시고요.', `FemaleText_loc4`='我会时刻盯着你的，$c。但这并无恶意。$b$b如果你有任何消息，我会替你转达。如果没有，你最好不要停下。', `FemaleText_loc5`='我只是在保持警戒，$c。這沒有壞處。$b$b如果你有任何消息要給我，我會傳達上去。如果沒有，你最好走開。', `FemaleText_loc7`='Me limito a tener los ojos abiertos, $c. Eso no tiene nada de malo.$b$bSi tienes algo que contarme, lo transmitiré. Si no, será mejor que te pongas en marcha.' WHERE `ID`=66191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음을 열고, 깨달아라. 기회를 포착하고, 활용해라!', `MaleText_loc4`='保持头脑的开放与清醒。善于发现并利用机会！', `MaleText_loc5`='保持心智開闊，清醒。看見機會。利用機會!', `MaleText_loc7`='Ten la mente abierta y despierta. Reconoce las oportunidades. ¡Aprovéchalas!' WHERE `ID`=66192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 네 무기에 특별한 혼합물을 발라뒀다. 적의 시체마다 돌연변이 유발 인자를 감염시켜서... 흐음... 결과는 네가 직접 봐야만 하겠구나.', `MaleText_loc4`='唤醒者，我已经在你的武器上涂了特殊的混合物。你刀下的每具尸体都会感染一种诱变剂……好吧……你必须亲眼见证它的效果。', `MaleText_loc5`='我已經在你的武器塗上了我的特別調劑，喚醒者。你會使所有的屍體染上一種突變物質，能讓...嗯...你必須自己親眼見識結果。', `MaleText_loc7`='He impregnado tus armas con mi mezcla especial, heraldo. Infectarás todos los cadáveres con un mutágeno que... bueno... Es mejor verlo en persona.' WHERE `ID`=66193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 추적용 페로몬은 귀중한 가치가 있는 대상이 무엇인지 알려줄 것이다.', `MaleText_loc4`='这种追踪信息素会帮你发现有巨大价值的目标。', `MaleText_loc5`='這種追蹤費洛蒙會讓你有能力看到極具價值的目標。', `MaleText_loc7`='Esta feromona de rastreo te revelará objetivos de gran valor.' WHERE `ID`=66194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 쓸어버려!', `MaleText_loc4`='干掉他们！', `MaleText_loc5`='解決他們!', `MaleText_loc7`='¡Acaba con ellos!' WHERE `ID`=66195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 승리의 열쇠는 바로 제어력이다. 내 능력을 이용해 적들의 마음을 제어해라. 그리고 아군으로 만들어라.', `MaleText_loc4`='胜利的关键是控制，唤醒者。你可以使用我的技能控制敌人的心智，将它变为盟友。', `MaleText_loc5`='勝利的關鍵就是控制，喚醒者。使用我的技巧來支配一名敵人的心智，將其轉變成一名盟友。', `MaleText_loc7`='La clave de la victoria es el control, heraldo. Utiliza mis facultades para dominar la mente de un enemigo y convertirlo en tu aliado.' WHERE `ID`=66196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 발견할 테니, 자네는 사게.', `MaleText_loc4`='我去找，你出钱。', `MaleText_loc5`='我來找，你來買。', `MaleText_loc7`='Yo lo encuentro, tú lo compras.' WHERE `ID`=66197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF0000|Hspell:127404|h[황금 창]|h|r을 피하려면 다가가십시오!', `MaleText_loc4`='靠近以避开|cFFFF0000|Hspell:127404|h[黄金战矛]|h|r！', `MaleText_loc5`='移近以閃避|cFFFF0000|Hspell:127404|h[黃金長矛]|h|r!', `MaleText_loc7`='¡Acércate para evitar |cFFFF0000|Hspell:127404|h[Lanza dorada]|h|r!' WHERE `ID`=66198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|t노예감독 히디스가 |cFFFF0000|Hspell:127414|h[야수의 부름]|h|r으로 동료들의 힘을 강화합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|t奴监希提斯使用|cFFFF0000|Hspell:127414|h[原始呼唤]|h|r提升了其盟友的实力！', `MaleText_loc5`='|TInterface\\Icons\\ability_hunter_pet_devilsaur.blp:20|t奴隸管理者黑西絲以|cFFFF0000|Hspell:127414|h[原始呼喚]|h|r增強他盟友的力量!', `MaleText_loc7`='|TInterfaceIconsability_hunter_pet_devilsaur.blp:20|t¡El maestro de esclavos Hithiss aumenta el poder de sus aliados con una |cFFFF0000|Hspell:127414|h[Llamada primigenia]|h|r!' WHERE `ID`=66199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디... 어딨어? 쓸모없는 놈들... 젠장!', `MaleText_loc4`='在……在哪儿？卑劣无能，一无是处……真该死！', `MaleText_loc5`='它...它去哪了?沒用的東西...該死!', `MaleText_loc7`='¿Dónde... dónde está? Inútil... patético... ¡malditos sean!' WHERE `ID`=66200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함정... 이었나...', `MaleText_loc4`='这是个……陷阱……', `MaleText_loc5`='這...是個...陷阱...', `MaleText_loc7`='Era... era una trampa...' WHERE `ID`=66201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='별거 아니군!', `MaleText_loc4`='不堪一击！', `MaleText_loc5`='不堪一擊!', `MaleText_loc7`='¡Demasiado fácil!' WHERE `ID`=66202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발버둥이라도 쳐봐!', `MaleText_loc4`='何苦还要挣扎？！', `MaleText_loc5`='掙扎有什麼意思呢?', `MaleText_loc7`='¿Por lo menos te esforzaste?' WHERE `ID`=66203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 쉽게 죽는 거 아니야?!', `MaleText_loc4`='哈哈，那么轻易就死了！', `MaleText_loc5`='哈哈，一下子就解決你了!', `MaleText_loc7`='¡Ja! ¡Con qué facilidad mueren!' WHERE `ID`=66204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 실패한 놈들은 죽어 마땅한 놈들이었어. 너희는 쭉정이를 걸러낸 것 뿐이다!', `MaleText_loc4`='呸！失败者活该受死，你们只不过是淘汰了弱者！', `MaleText_loc5`='哼!失敗者活該受死，你們只不過是淘汰了弱者!', `MaleText_loc7`='¡Bah! Los que han caído merecían morir. ¡No han hecho más que purgar a los débiles!' WHERE `ID`=66205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 직접 처치해주마. 각오해라!', `MaleText_loc4`='看来我必须亲自动手。那就来吧！', `MaleText_loc5`='看起來我得親自動手。那就來吧!', `MaleText_loc7`='Entonces debo acabar el trabajo yo mismo. ¡Así sea!' WHERE `ID`=66206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t장군 준이 적을 향해 |cFFFF0000|Hspell:127334|h[고통의 파동]|h|r을 방출합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t烛恒将军对他的敌人释放了|cFFFF0000|Hspell:127334|h[痛苦之潮]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t曾將軍釋放了一個|cFFFF0000|Hspell:127334|h[痛苦光波]|h|r在他的敵人身上!', `MaleText_loc7`='|TInterfaceIconsspell_nature_lightningoverload.blp:20|t¡El general Zhun desata una |cFFFF0000|Hspell:127334|h[Ola de dolor]|h|r contra sus enemigos!' WHERE `ID`=66207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있어! 별로 안 아플 테니까.', `MaleText_loc4`='别动，这一点儿都不疼！', `MaleText_loc5`='別動!這一點都不會痛。', `MaleText_loc7`='¡Quédense quietos! Esto no les dolerá.' WHERE `ID`=66208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 개들에게 줄 신선한 고기들!', `MaleText_loc4`='啊，喂狗的鲜肉送上门了！', `MaleText_loc5`='啊!獵犬又有鮮肉吃了!', `MaleText_loc7`='¡Ah! ¡Carne fresca para los perros!' WHERE `ID`=66209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살을 꿰뚫어라!', `MaleText_loc4`='刺穿血肉。', `MaleText_loc5`='刺穿身體。', `MaleText_loc7`='Desgarren la carne.' WHERE `ID`=66210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발톱으로... 놈들을 찢어발겨!', `MaleText_loc4`='宝贝儿…把他们切成碎片！', `MaleText_loc5`='刀鋒...把他們切碎!', `MaleText_loc7`='Hojas... ¡cortenlos en pedazos!' WHERE `ID`=66211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피야! 이리로 튀어라!', `MaleText_loc4`='鲜血！在我身边流淌吧！', `MaleText_loc5`='鮮血!盡情地流吧!', `MaleText_loc7`='¡Sangre! ¡Fluye a mi alrededor!' WHERE `ID`=66212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우물쭈물하지 마. 처치해!', `MaleText_loc4`='别傻看着。杀光他们！', `MaleText_loc5`='別坐著看戲。殺光他們!', `MaleText_loc7`='No se queden ahí parados. ¡Mátenlos!' WHERE `ID`=66213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 멍청한 놈들! 이 약골들을 처치하고 나면 너희 차례다.', `MaleText_loc4`='笨狗！等我杀死这些废物之后再来教训你！', `MaleText_loc5`='啊!愚蠢的動物!等我殺光這些弱者，我再來教訓你們。', `MaleText_loc7`='¡Bah! ¡Estúpidos animales! Los sacrificaré en cuanto acabe con estas cucarachas.' WHERE `ID`=66214;
