UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레처럼 뭉개 주마!', `MaleText_loc4`='碾碎你们，就像碾碎虫子！', `MaleText_loc5`='我們會像打扁蟲子一樣打扁你們!', `MaleText_loc7`='¡Los aplastaremos como insectos!' WHERE `ID`=66224;
