UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘을... 합쳤는데도... 지다니...', `MaleText_loc4`='即使……联手……我们也败了……', `MaleText_loc5`='就算...聯手...我們還是失敗...', `MaleText_loc7`='Aun juntos... hemos fracasado...' WHERE `ID`=66226;
