UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개에게 자비란 없다!', `MaleText_loc4`='闪电绝无怜悯！', `MaleText_loc5`='閃電毫不留情!', `MaleText_loc7`='¡Los rayos no conocen la piedad!' WHERE `ID`=66228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 음영파에 도전할 순 없다!', `MaleText_loc4`='谁也不许违抗影踪派！', `MaleText_loc5`='沒有人能違抗影潘!', `MaleText_loc7`='¡Nadie osa desafiar al Shadopan!' WHERE `ID`=66229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='궁수들이여, 공격!', `MaleText_loc4`='弓箭手，攻击！', `MaleText_loc5`='弓箭手，放箭!', `MaleText_loc7`='¡Arqueros, ataquen!' WHERE `ID`=66230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 쏴라! 모두 처치해!', `MaleText_loc4`='继续放箭！一个也别想跑！', `MaleText_loc5`='繼續放箭，不留活口!', `MaleText_loc7`='¡Sigan disparando! ¡Que no escape ni uno!' WHERE `ID`=66231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 처치했군. 봐주지 마라!', `MaleText_loc4`='又干掉一个。再接再厉！', `MaleText_loc5`='又幹掉一個。保持下去!', `MaleText_loc7`='Ha caído otro. ¡No paren!' WHERE `ID`=66232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축제를 구해 주셔서 고마워요, $n 님!', `MaleText_loc4`='感谢你挽救了节日，$n！', `MaleText_loc5`='謝謝你救了慶典，$n!', `MaleText_loc7`='¡Gracias por salvar el festival, $n!' WHERE `ID`=66233;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요, $n 님. 당신이 없었으면 해 내지 못했을 거예요.', `FemaleText_loc4`='干得好，$n。多亏了你我们才能做到这一切。', `FemaleText_loc5`='幹得好，$n。少了你我們絕辦不到。', `FemaleText_loc7`='Buen trabajo, $n. No lo habríamos conseguido sin ti.' WHERE `ID`=66234;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야운골이 사방에서 몰려오고 있어요! 빨리, 놈들이 마을을 태우기 전에 방비를 마쳐 주세요!', `FemaleText_loc4`='野牛人从四面八方包围过来了，$n！快，保卫村庄，别让他们烧了它！', `FemaleText_loc5`='揚古從四面八方湧上來了，$n!快，在他們把這裡燒毀之前保衛村莊!', `FemaleText_loc7`='¡Los yaungol vienen de todas direcciones, $n! ¡Rápido, defiende la aldea antes de que la quemen!' WHERE `ID`=66235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파에게 외부인의 도움은 필요없다! 이 침입자들을 쫓아내라!', `MaleText_loc4`='影踪派不需要外人的帮助！送走这些不速之客！', `MaleText_loc5`='影潘不需要外人幫忙!趕走這些入侵者!', `MaleText_loc7`='¡El Shadopan no necesita ayuda de forasteros! ¡Eliminen a los intrusos!' WHERE `ID`=66236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warstomp.blp:20|t %s|1이;가; |cFFFF0000|Hspell:127480|h[분쇄의 격돌]|h|r을 시전하기 시작합니다! 도망치십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_warstomp.blp:20|t %s开始施放|cFFFF0000|Hspell:127480|h[碾压重击]|h|r！快走开！', `MaleText_loc5`='|TInterface\\Icons\\ability_warstomp.blp:20|t%s開始施放|cFFFF0000|Hspell:127480|h[粉碎猛擊]|h|r!快閃開!', `MaleText_loc7`='|TInterfaceIconsability_warstomp.blp:20|t ¡%s empieza a lanzar |cFFFF0000|Hspell:127480|h[Embate aplastante]|h|r! ¡Aléjate!' WHERE `ID`=66237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 떨어진 무기를 줍습니다.', `MaleText_loc4`='%s捡起掉落的武器。', `MaleText_loc5`='%s撿起了一把掉在地上的武器。', `MaleText_loc7`='%s recoge un arma caída.' WHERE `ID`=66238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다! 놈들이 전승지기님을 해치지 못하게 해야 합니다!', `MaleText_loc4`='来吧！我们不能让他们伤害游学者！', `MaleText_loc5`='快來!我們不能讓他們傷害博學行者!', `MaleText_loc7`='¡Rápido! ¡No podemos permitir que hagan daño al eremita!' WHERE `ID`=66239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파에는 비밀이 아주 많습니다. 뛰어난 품질의 무기와 방어구를 만드는 법도 있는데, 그건 고급 비밀에 속합니다.', `MaleText_loc4`='影踪派有许多秘密。这其中的最高机密就是如何制造品质超凡的武器和护甲。', `MaleText_loc5`='影潘有許多秘密。其中極為重要的就是如何打造出品質卓越的武器和護甲。', `MaleText_loc7`='El Shadopan tiene muchos secretos. Entre los más importantes está cómo fabricar armas y armaduras de una calidad sobresaliente.' WHERE `ID`=66240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 맥주가 생각보다 좀 독하군요...', `MaleText_loc4`='哦……老天。这酒比我预想中更烈一些……', `MaleText_loc5`='喔...老天。那酒比我預期的還要更加濃烈...', `MaleText_loc7`='Oh... vaya. Ese brebaje es un poco más fuerte de lo que esperaba...' WHERE `ID`=66241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 맥주가 생각보다 좀 독하군요... 전...', `MaleText_loc4`='哦……老天。这酒比我预想中更烈一些……我……', `MaleText_loc5`='喔...老天。那酒比我預期的還要更加濃烈...我...', `MaleText_loc7`='Oh... vaya. Ese brebaje es un poco más fuerte de lo que esperaba... Yo...' WHERE `ID`=66242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 눈을 쉬어야겠습니다...', `MaleText_loc4`='只是需要打个盹……', `MaleText_loc5`='我只須要讓眼睛休息一下...', `MaleText_loc7`='Solo necesito descansar un poco los ojos...' WHERE `ID`=66243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 오직 클락시바만을 섬긴다.', `MaleText_loc4`='我只为卡拉克西瓦效力。', `MaleText_loc5`='我只服侍卡拉西瓦。', `MaleText_loc7`='Solo sirvo a los Klaxxi''va.' WHERE `ID`=66244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 여기서부터는 제가 전승지기님을 골짜기까지 호위하겠습니다.', `MaleText_loc4`='我们由衷地感谢你！我会在这儿目送游学者安全地前往锦绣谷。', `MaleText_loc5`='我們感謝你!我會確保博學行者從這裡安全抵達恆春谷。', `MaleText_loc7`='¡Os lo agradecemos! Me aseguraré de que el eremita llega a salvo al valle.' WHERE `ID`=66248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주통을 되찾았습니다! 정말 감사합니다...', `MaleText_loc4`='你找回了一桶酒！我真是感激不尽……', `MaleText_loc5`='取回一桶酒了!我謙恭地感謝你...', `MaleText_loc7`='¡Has recuperado un barril! Mi más humilde agradecimiento...' WHERE `ID`=66249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀한 녹옥 맥주통이군요! 만세!', `MaleText_loc4`='一桶珍贵的绿石佳酿！好哇！', `MaleText_loc5`='一桶珍貴的綠石酒!呀呼!', `MaleText_loc7`='Un precioso barril de brebaje de Verdemar. ¡Viva!' WHERE `ID`=66250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 저 성가신 놈들이 우리 소중한 맥주를 좀도둑질하면 어떻게 되는지 알았을 겁니다!', `MaleText_loc4`='这可以给那些窃取我们道场珍贵产品的小偷们一个教训！', `MaleText_loc5`='那會讓那些討厭鬼知道偷取我們道場最珍貴物品的下場!', `MaleText_loc7`='¡Eso enseñará a esa plaga a no mangar nuestro producto más valioso!' WHERE `ID`=66251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 맥주통이 원래 있던 곳으로 돌아왔군요. 감사합니다!', `MaleText_loc4`='啊，物归原主了。谢谢你！', `MaleText_loc5`='啊，物歸原位。感謝你!', `MaleText_loc7`='Ah, de vuelta a donde pertenece. ¡Gracias!' WHERE `ID`=66252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을을 구했을 때는 모험가였지만, 맥주를 회수해 왔을 땐 영웅이 되셨군요!', `MaleText_loc4`='一位冒险家挽救了村庄，而一位英雄将美酒物归原主！', `MaleText_loc5`='普通冒險家就能拯救村子，但真正的英雄才能救回美酒!', `MaleText_loc7`='Un aventurero salva la aldea, pero un héroe trae la cerveza de vuelta.' WHERE `ID`=66253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 훌륭한 맥주를 되찾았습니다! 정말 감사합니다.', `MaleText_loc4`='我们的佳酿回来了！我们所有人都由衷地感谢你。', `MaleText_loc5`='我們美好的酒拿回來了!我們全都很感激你。', `MaleText_loc7`='¡Nuestra excelente cerveza está de vuelta! Os lo agradecemos todos.' WHERE `ID`=66254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변의 숲으로 들어가 도난당한 맥주통을 찾아서 가져오시면 강력한 힘이 집약된 맥주를 만들어 드릴 수 있는데 말입니다...', `MaleText_loc4`='如果你有胆量进入周围的森林，把被盗的酒桶找回来带给我，我就会为你调制一种具有神奇力量的浓缩生啤……', `MaleText_loc5`='如果你進入周遭的森林，發現並找回任何被偷走的桶子，我就能調製一劑擁有奇妙力量的濃縮酒漿給你...', `MaleText_loc7`='Si os pudierais aventurar por el bosque de alrededor y traer de vuelta los barriles robados, os podría elaborar un brebaje con un poder maravilloso...' WHERE `ID`=66255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘됐군요! 이 한심한 수습생들 상대하기도 지겨웠습니다!', `MaleText_loc4`='好！这些差劲的新兵快让我无聊死了！', `MaleText_loc5`='很好!這些可悲的學徒讓我感到無聊!', `MaleText_loc7`='¡Bien! ¡Estos iniciados patéticos me estaban aburriendo!' WHERE `ID`=66256;
