UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기의 수호자들이여, 30분 내에 황금탑으로 돌아가게!', `MaleText_loc4`='山谷的防御者们，你们必须在30分钟之内返回鎏金亭！', `MaleText_loc5`='山谷的防衛者，我們需要你在30分鐘內返回黃金寶塔!', `MaleText_loc7`='¡Defensores del Valle, necesitamos su regreso a la Pagoda Dorada en 30 minutos!', `FemaleText_loc1`='골짜기의 수호자들이여, 30분 내에 황금탑으로 돌아가세요!', `FemaleText_loc4`='山谷的防御者们，你们必须在30分钟之内返回鎏金亭！', `FemaleText_loc5`='山谷的防衛者，我們需要你在30分鐘內返回黃金寶塔!', `FemaleText_loc7`='¡Defensores del Valle, necesitamos su regreso a la Pagoda Dorada en 30 minutos!' WHERE `ID`=66268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 군대가 정문에 밀어닥치고 있네! 모든 수호자가 15분 내에 황금탑으로 돌아가야 하네!', `MaleText_loc4`='魔古大军正涌向正门！所有防御者必须在15分钟之内返回鎏金亭！', `MaleText_loc5`='魔古的部隊湧向主城門了!所有的防衛者在15分鐘內回到黃金寶塔!', `MaleText_loc7`='¡Las fuerzas mogu se acumulan en la puerta principal! Todos los defensores deben regresar a la Pagoda Dorada en 15 minutos!', `FemaleText_loc1`='모구 군대가 정문에 밀어닥치고 있어요! 모든 수호자가 15분 내에 황금탑으로 돌아가야 해요!', `FemaleText_loc4`='魔古大军正涌向正门！所有防御者必须在15分钟之内返回鎏金亭！', `FemaleText_loc5`='魔古的部隊湧向主城門了!所有的防衛者在15分鐘內回到黃金寶塔!', `FemaleText_loc7`='¡Las fuerzas mogu se acumulan en la puerta principal! Todos los defensores deben regresar a la Pagoda Dorada en 15 minutos!' WHERE `ID`=66269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자들이여, 5분 후면 황금탑으로 소환될 걸세!', `MaleText_loc4`='防御者们，你们将在5分钟后被召回鎏金亭！', `MaleText_loc5`='防衛者，你還有5分鐘可以回到黃金寶塔!', `MaleText_loc7`='¡Defensores, tenéis 5 minutos antes de que os reclamen en la Pagoda Dorada!', `FemaleText_loc1`='수호자들이여, 5분 후면 황금탑으로 소환될 거예요!', `FemaleText_loc4`='防御者们，你们将在5分钟后被召回鎏金亭！', `FemaleText_loc5`='防衛者，你還有5分鐘可以回到黃金寶塔!', `FemaleText_loc7`='¡Defensores, tenéis 5 minutos antes de que os reclamen en la Pagoda Dorada!' WHERE `ID`=66271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋네, 돌아왔군.', `MaleText_loc4`='很好，你回来了。', `MaleText_loc5`='很好，你回來了。', `MaleText_loc7`='Menos mal que habéis regresado.', `FemaleText_loc1`='좋습니다, 돌아오셨군요.', `FemaleText_loc4`='很好，你回来了。', `FemaleText_loc5`='很好，你回來了。', `FemaleText_loc7`='Menos mal que habéis regresado.' WHERE `ID`=66272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰대에 따르면 30분 후에 모구의 공격이 시작된다고 하네! 골짜기 서부에서 빠져나오게!', `MaleText_loc4`='斥候回报，魔古将于30分钟后发起攻势！扫清西部山谷！', `MaleText_loc5`='斥候回報，魔古將在30分鐘內進攻!將西邊山谷淨空!', `MaleText_loc7`='¡Los exploradores nos informan de una ofensiva mogu en 30 minutos! ¡Despejad el valle del oeste!', `FemaleText_loc1`='정찰대에 따르면 30분 후에 모구의 공격이 시작된다고 하네! 골짜기 서부에서 빠져나오게!', `FemaleText_loc4`='斥候回报，魔古将于30分钟后发起攻势！扫清西部山谷！', `FemaleText_loc5`='斥候回報，魔古將在30分鐘內進攻!將西邊山谷淨空!', `FemaleText_loc7`='¡Los exploradores nos informan de una ofensiva mogu en 30 minutos! ¡Despejad el valle del oeste!' WHERE `ID`=66273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자들이여, 15분 내로 골짜기 서부에서 나오게! 모구 공격대가 야영지를 떠나고 있네!', `MaleText_loc4`='防御者们，你们还有15分钟的时间来扫清西部山谷！魔古的突袭部队已经离营出发了！', `MaleText_loc5`='防衛者，你還有15分鐘可以淨空西邊山谷!魔古突擊部隊正在離開他們的營地!', `MaleText_loc7`='¡Defensores, tenéis 15 minutos para despejar el valle del oeste! ¡Las partidas de asalto mogu están saliendo de sus campamentos!', `FemaleText_loc1`='수호자들이여, 15분 내로 골짜기 서부에서 나오게! 모구 공격대가 야영지를 떠나고 있네!', `FemaleText_loc4`='防御者们，你们还有15分钟的时间来扫清西部山谷！魔古的突袭部队已经离营出发了！', `FemaleText_loc5`='防衛者，你還有15分鐘可以淨空西邊山谷!魔古突擊部隊正在離開他們的營地!', `FemaleText_loc7`='¡Defensores, tenéis 15 minutos para despejar el valle del oeste! ¡Las partidas de asalto mogu están saliendo de sus campamentos!' WHERE `ID`=66274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 5분 후에 골짜기 서부에 들이닥칠 걸세! 수호자들이여, 지금이 빠져나올 마지막 기회네!', `MaleText_loc4`='魔古族将在5分钟后入侵西部的山谷！防御者们，这是你们扫清山谷的最后机会！', `MaleText_loc5`='魔古在5分鐘內就會襲擊西邊山谷了!防衛者，這是淨空的最後機會!', `MaleText_loc7`='¡Los mogu van a asaltar el valle del oeste en 5 minutos! ¡Defensores, esta es su última oportunidad para evacuar!', `FemaleText_loc1`='모구가 5분 후에 골짜기 서부에 들이닥칠 걸세! 수호자들이여, 지금이 빠져나올 마지막 기회네!', `FemaleText_loc4`='魔古族将在5分钟后入侵西部的山谷！防御者们，这是你们扫清山谷的最后机会！', `FemaleText_loc5`='魔古在5分鐘內就會襲擊西邊山谷了!防衛者，這是淨空的最後機會!', `FemaleText_loc7`='¡Los mogu van a asaltar el valle del oeste en 5 minutos! ¡Defensores, esta es su última oportunidad para evacuar!' WHERE `ID`=66275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신 나게 한 번 놀아 볼까, $n?', `MaleText_loc4`='我会配合你的，$n！', `MaleText_loc5`='我們一起大吃特吃吧，$n!', `MaleText_loc7`='¡Ya me he cansado, $n!', `FemaleText_loc1`='신 나게 한 번 놀아 볼까, $n?', `FemaleText_loc4`='我会配合你的，$n！', `FemaleText_loc5`='我們一起大吃特吃吧，$n!', `FemaleText_loc7`='¡Ya me he cansado, $n!' WHERE `ID`=66276;
