UPDATE `locales_broadcast_text` SET `MaleText_loc1`='카로즈, 자네의 그 "영웅심"에 대해선 들어봤네. 다른 이들이 그러는데, 자네가 모구 일꾼들의 야영지와 농장을 공격한 덕분에 장벽이 완성되는 게 수십 년이나 늦어졌다더군.', `MaleText_loc4`='我听说过你的“英雄事迹”，暴食蝗。据说你突袭了魔古族劳工营和农田，使长城的完工时间推迟了几十年。', `MaleText_loc5`='我已經聽說了你的「英雄事蹟」，蝗蟲。他們說你對魔古勞工營地與農地的突襲行動，造成長城得延後數十年才能完成。', `MaleText_loc7`='He oído hablar de tu "heroísmo," Langosta. Dicen que tus asaltos a los campos de cultivo y los campos de trabajos forzados mogu retrasaron la finalización de la muralla durante décadas.' WHERE `ID`=66293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 이루어낸 성과에 대해서는 뭐라 할 순 없겠지만, 도망치는 농민이나 일꾼들을 사냥해서야 어떻게 자랑스러운 군단의 전사로서 그 이름을 드높일 수 있겠나?', `MaleText_loc4`='我无法否认你的战果，但是荣耀的虫群战士怎么能把自己的名声建立在追杀溃逃的农夫和雇农上呢？', `MaleText_loc5`='我是無法抵賴你的戰績，但一個蟲群的驕傲戰士怎麼會靠追趕四散逃逸的農民與工人來揚名?', `MaleText_loc7`='No puedo rebatir tus resultados, ¿pero cómo puede un guerrero orgulloso del enjambre hacerse un nombre acabando con campesinos y jornaleros que huyen?' WHERE `ID`=66294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽게 말이지. 힘 안 들이고 잡아 없애면서도 명성이 높아지는데 뭘 그러나.', `MaleText_loc4`='很简单：因为你在追杀他们时不用跳很远。', `MaleText_loc5`='簡單:你殺第一個人跟第二個人中間的空檔不用跳那麼遠。', `MaleText_loc7`='Muy fácil: no hay que saltar tanto entre muerte y muerte.' WHERE `ID`=66295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스키르, 자네의 재생 능력이 참으로 흥미롭군. 몇 가지 실험을 해보고 싶은데, 동의해주려나 모르겠네.', `MaleText_loc4`='觅血者，你的再生能力让我着迷。我不知道你是否愿意做一些测试。', `MaleText_loc5`='覓血者，你的再生能力讓我著迷。不知道你是否同意進行一些測試。', `MaleText_loc7`='Cruento, tus poderes regeneradores me fascinan. ¿Estarías dispuesto a someterte a unas cuantas pruebas?' WHERE `ID`=66296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 실험 말인가?', `MaleText_loc4`='什么样的测试？', `MaleText_loc5`='什麼樣的測試?', `MaleText_loc7`='¿Qué tipo de pruebas?' WHERE `ID`=66297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 소량의 세포 손상 유도 실험일세. 피부 조직 표본 약간과 극소음 고심도 유전자 감식 1회 정도가 되겠군. 칼을 심하게 대거나 그런 건 아니라네!', `MaleText_loc4`='只不过是一些简单的细胞穿刺感应，可能还要进行一些组织取样，再进行一次深入的超声波基因探查。不会造成严重损伤的！', `MaleText_loc5`='只是一個小小的細胞損傷引入，或許取幾分組織樣本，或使用微聲波基因探測器。沒有什麼可怕的侵入性行為!', `MaleText_loc7`='Solo una pequeña inducción traumática celular, quizás unas cuantas muestras de tejido, una sesión de investigación genética microsónica profunda... ¡Nada demasiado invasivo!' WHERE `ID`=66298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막에 말한 게 뭔가?', `MaleText_loc4`='你说最后一步是什么？', `MaleText_loc5`='最後那部分是什麼?', `MaleText_loc7`='¿Qué es eso último que has dicho?' WHERE `ID`=66299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피부 조직 표본 말인가?', `MaleText_loc4`='组织取样吗？', `MaleText_loc5`='組織樣本?', `MaleText_loc7`='¿Muestras de tejido?' WHERE `ID`=66300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그다음 말일세.', `MaleText_loc4`='后面那句。', `MaleText_loc5`='在那之後。', `MaleText_loc7`='Después de eso.' WHERE `ID`=66301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼을 심하게 대거나 그런 건 아니라는 것?', `MaleText_loc4`='不会造成严重损伤的？', `MaleText_loc5`='沒什麼可怕的侵入性行為?', `MaleText_loc7`='¿Nada demasiado invasivo?' WHERE `ID`=66302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 이야기하지.', `MaleText_loc4`='我们没什么可以聊的了。', `MaleText_loc5`='我們的談話到此為止了。', `MaleText_loc7`='Esta conversación ha terminado.' WHERE `ID`=66303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무리지기여, 두 번씩이나 무리를 벗어나는 기분이 어떤가? 너의 여제도 망상에 빠졌었지, 그렇지 않나?', `MaleText_loc4`='再次起义是什么感觉，虫群卫士？你的女皇也曾被妄想控制，不是吗？', `MaleText_loc5`='再次成為叛徒的感覺如何啊，蟲群守護者?你的女皇也陷入偏執當中了，不是嗎?', `MaleText_loc7`='¿Qué se siente al rebelarse por segunda vez, Guardaenjambres? Tu emperatriz también se había visto afectada por la paranoia, ¿no es así?' WHERE `ID`=66304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 여제 제크하라는 어머니처럼 우리를 걱정하는 척하며 자신의 진의를 숨겼다. 여제는 그 강압적인 방식이 우리를 보호하기 위해서라고 주장했지.', `MaleText_loc4`='大女皇赞柯哈兰以慈爱之名掩盖自己的真正目的。她声称是自己的独裁统治是为了保护我们。', `MaleText_loc5`='澤哈拉女皇用女人般關懷的態度來隱藏她真正的意圖。她宣稱為了保護我們，她傲慢的作風是必要的。', `MaleText_loc7`='La gran emperatriz Zek''hara ocultó sus verdaderas intenciones bajo su máscara de madre preocupada. Decía que sus acciones dominantes eran necesarias para protegernos.' WHERE `ID`=66305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실 여제는 지배욕에 사로잡혀 있었던 것이다. 그녀는 자신에게 주어진 시간 이후에도 권력을 쥐고 있기를 갈망했지. 또한 그 열망을 이루기 위해서라면 우리의 영원한 순환을 기꺼이 희생할 터였다. 그래서 우리는 여제를 처치할 수밖에 없었다.', `MaleText_loc4`='实际上，她只是恋栈权位而已。她渴望延长自己的统治，并为了实现这一目标而牺牲了我们永恒的轮回。我们别无选择，只能杀死她。', `MaleText_loc5`='事實是，她有控制狂。她渴望掌握住她那早已流逝的權力，並不惜犧牲我們永恆的週期來達到她的目的。除了殺死她，我們沒有其他的選擇。', `MaleText_loc7`='En realidad, estaba obsesionada con el control. Quería perpetuarse en el poder mucho más tiempo de lo debido, y estaba dispuesta a sacrificar nuestro ciclo eterno para conseguirlo. No nos quedó otra opción que acabar con ella.' WHERE `ID`=66306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞는 말이다.', `MaleText_loc4`='当然。', `MaleText_loc5`='當然。', `MaleText_loc7`='Claro.' WHERE `ID`=66307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 위대한 여제 셰크지르가 우리 대지에 저지르는 만행을 보니... 그 생각이 더욱 확실해지는군.', `MaleText_loc4`='所以在看到大女皇夏柯希尔在我们土地上的所作所为之后……我就已下定决心。', `MaleText_loc5`='看過杉齊爾女皇對我們土地所做的事之後...你們不需要再說服我了。', `MaleText_loc7`='Y en vista de lo que la gran emperatriz Shek''zeer le está haciendo a nuestra tierra... no necesito que me convenzan.' WHERE `ID`=66308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 보존되기 전까지 셰크지르 밑에 있었다. 그녀의 광기는, 야망같이 이성적인 그 무엇이 아니었다.', `MaleText_loc4`='你知道，我曾经为夏柯希尔效力过一段时间。那是在我被封印之前的事情了。她的疯狂和野心一样毫无理性可言。', `MaleText_loc5`='我曾一度為杉齊爾效命，你知道的。在我被封存進琥珀之前。所謂的野心和她的瘋狂相比都嫌太理性了。', `MaleText_loc7`='Serví a Shek''zeer durante un tiempo, ¿sabes? Antes de que me preservaran. Su locura no es tan racional como la ambición.' WHERE `ID`=66309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무리 짓는 것을 금지하려고 했을 때에는 “생명을 무의미하게 잃는 것”을 막기 위해서 그러는 거라고 했었다.', `MaleText_loc4`='当她试图禁锢虫群时，用她的话说，是为了防止“无谓的牺牲”。', `MaleText_loc5`='當她試圖禁止蟲群時，她說是為了防止她所謂的「生命的無謂損失」。', `MaleText_loc7`='Cuando trató de prohibir el enjambre, era para evitar, según dijo, "una pérdida de vidas sin sentido".' WHERE `ID`=66310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제는 아무도 믿지 않는다. 피해망상이 그녀의 마음을 갉아먹고 있지. 걷잡을 수 없는 공포에 휘둘려버린 것이다.', `MaleText_loc4`='她不相信任何人。妄想侵蚀了她的心智。无尽的恐惧驱使着她的行动。', `MaleText_loc5`='她不信任任何人。偏執腐蝕了她的心。她的行動受到無情恐懼的逼迫。', `MaleText_loc7`='No confía en nadie. La paranoia se ha apoderado de su mente. Está controlada por un miedo implacable.' WHERE `ID`=66311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기분이 어떠냐고? 지금 내 기분을 묻는 거라면, 나는 후회하지 않는다. 클락시의 의지를 따른 게 자랑스럽다.', `MaleText_loc4`='那种感觉如何？我并不后悔，如果这就是你想问的。能够为卡拉克西效力是我的荣幸。', `MaleText_loc5`='這是什麼樣的感覺?我不會感到遺憾，如果這是你所問的話。我很榮幸能為卡拉西的意志效命。', `MaleText_loc7`='¿Que qué se siente? No me arrepiento de nada, si es a lo que te refieres. Me honra servir a la voluntad de los Klaxxi.' WHERE `ID`=66312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시초자시여, 옆에서 섬기게 되어 영광입니다. 저는 당신이 남긴 기록을 깊이 연구했었습니다.', `MaleText_loc4`='能够随侍在您身边是一种荣耀，至尊者。我曾深入研究过您的工作。', `MaleText_loc5`='能在你身邊為你服務是種榮幸，至高者。我曾廣泛地研讀你的事蹟。', `MaleText_loc7`='Es un honor servir a tu lado, Principal. He estudiado ampliamente tu trabajo.' WHERE `ID`=66313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 보존실을 개발하는 과정을 자세히 기록으로 남겨 주신 덕분에, 코보크도 보존할 수 있는 개선된 보존실을 만들 수 있었습니다.', `MaleText_loc4`='多亏您在开发封印仓时留下的详细记录，我才得以在此处建造出保存科沃克的改进版封印仓。', `MaleText_loc5`='多虧你在保管室中挖掘資料時留下的仔細筆記，我才能創造出一個調整過的版本，讓科沃克在這裡繼續保存下去。', `MaleText_loc7`='Gracias a las minuciosas notas que escribiste mientras elaborabas la cámara de preservación, pude crear una versión modificada para preservar también a Kovok.' WHERE `ID`=66314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군, 코보크는 확실히... 건강해 보이는군.', `MaleText_loc4`='是的，他看起来确实……健康。', `MaleText_loc5`='是的，他看起來很...健康。', `MaleText_loc7`='Sí, desde luego tiene un aspecto... saludable.' WHERE `ID`=66315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 작업이 여기까지 올 수 있으리라고는 상상도 못했네. 이건 키파리가 위대한 힘을 가졌다는 증걸세. 키파리를 위한 것이 아니었다면, 우리 문명이 절대 회복되지 않았을 것일세. 이것을 꼭 기억하게나.', `MaleText_loc4`='我从来没有想到我的工作会有如此进展。这是凯帕圣树伟大力量的一次证明。如果没有它们，我们的文明永远都将无法复兴。请记住这一点。', `MaleText_loc5`='我從沒想過我的工作會走到這個程度。這是奇帕利偉大力量的證明。少了它們，我們的文明就不會恢復。記住這一點。', `MaleText_loc7`='Nunca pensé que mi trabajo llegaría tan lejos. Es una prueba del gran poder de los kypari. De no ser por ellos, nuestra civilización nunca se habría recuperado. No lo olvides.' WHERE `ID`=66316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지고 있는 야수가 참 인상적이군, 배후자여. 아주 흥미로운걸.', `MaleText_loc4`='操纵者，你的这头野兽真是令人印象深刻。非常有趣。', `MaleText_loc5`='你擁有一隻了不起的野獸，操縱者。非常有魅力。', `MaleText_loc7`='Tienes a una bestia bastante impresionante, Manipulador. Muy intrigante.' WHERE `ID`=66317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야.', `MaleText_loc4`='不。', `MaleText_loc5`='不。', `MaleText_loc7`='No.' WHERE `ID`=66318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑작스럽고, 급속한 성장 뒤에 오랫동안 정체되어 있군.', `MaleText_loc4`='多年来一直出于休眠停滞的状态，现在又突然快速增长。', `MaleText_loc5`='那幾年的停滯不前之後是突然快速的增長。', `MaleText_loc7`='Todos esos años en estasis seguidos de un crecimiento rápido y repentino.' WHERE `ID`=66319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물어볼 생각도 하지 마라.', `MaleText_loc4`='问也别问。', `MaleText_loc5`='連問都不要問。', `MaleText_loc7`='Rotundamente no.' WHERE `ID`=66320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그저... 그 야수의 유전자가 많은 것을 말해준다고 하는 것일 뿐일세.', `MaleText_loc4`='我只是随口说说……我敢打赌，他的基因将揭示一段引人入胜的故事……', `MaleText_loc5`='我只是講講...我敢說從他的基因可以看出一些苗頭。', `MaleText_loc7`='Solo digo que... seguro que sus genes podrían contar muchas historias...' WHERE `ID`=66321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 나는 그저 해부자 자네가 음파 조작에 저항력을 가지고 있지 않아 보인다고 말하는 것뿐이지.', `MaleText_loc4`='我也只是随口说说，切割者，看来你对声波操控不具有任何抵抗力。', `MaleText_loc5`='還有這也只是講講，開膛手，你看起來對聲波操縱不具有任何抵抗能力。', `MaleText_loc7`='Y yo solo digo, Disector, que tú no pareces poseer ninguna resistencia a la manipulación sónica.' WHERE `ID`=66322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 가슴에 갑자기 지대한 "흥미"를 가져보는 건 어떤가? 자네는 분명히 손재주가 뛰어나니 필요하다면 혼자서도 짧은 시간 안에 가슴을 여는 수술을 할 수도 있을 텐데.', `MaleText_loc4`='要是你突然对自己的腹腔“来了兴趣”会怎么样？我敢打赌，只要稍作诱导，你那双巧手就能在几秒钟内把自己剖开。', `MaleText_loc5`='假如讓你突然對自己的胸腔「著迷」了起來，你覺得怎麼樣?我敢打賭，透過適當的壓迫，你的巧手可以在短短數秒鐘執行「自我活體解剖」的工作。', `MaleText_loc7`='¿Qué te parecería sentirte repentinamente "intrigado" por tu propio tórax? Estoy seguro de que tus hábiles manos podrían realizar una autovivisección en cuestión de segundos si se vieran obligadas.' WHERE `ID`=66323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 알겠네.', `MaleText_loc4`='说得好。', `MaleText_loc5`='你的意見我聽到了。', `MaleText_loc7`='Capto el mensaje.' WHERE `ID`=66324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으으으... 뭐라도 없애버려야 해. 여기 내 주변에 있는 모든 것들이 나를 미치게 하고 있어.', `MaleText_loc4`='哎呀……我得去杀掉点什么。我等得都要发疯了。', `MaleText_loc5`='嘎...我需要殺掉些什麼。在這裡空等快把我逼瘋了。', `MaleText_loc7`='Grrr... necesito matar a alguien. Esta espera me está volviendo loco.' WHERE `ID`=66325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기, 조용히 해.', `MaleText_loc4`='你，安静。', `MaleText_loc5`='安靜，你這傢伙。', `MaleText_loc7`='Silencio.' WHERE `ID`=66326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사, 그렇게 굴러 다니면 어지럽지 않나?', `MaleText_loc4`='武僧，翻滚不会让你感到头晕吗？', `MaleText_loc5`='僧侶們，這些滾動不會讓你們頭暈嗎?', `MaleText_loc7`='Monjes, ¿no os mareáis con tanta vuelta?' WHERE `ID`=66327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 양조에 뛰어나지는 않지만, 웅가 잉구에 있는 놈들은 좋은 재료를 훔치는 모양입니다.', `MaleText_loc4`='猢狲不一定是最好的酿酒师，但是盎迦猴岛的那些猢狲似乎偷到了最好的原料。', `MaleText_loc5`='猴人並不是最佳的釀酒人，但仰加印古的那些傢伙不知為何偷走了最好的釀酒配方。', `MaleText_loc7`='Los hozen no son siempre los mejores cerveceros, pero los de Unga Ingoo se las arreglan para robar los mejores ingredientes.' WHERE `ID`=66328;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='티엔 수도원에 잘 오셨어요.', `FemaleText_loc4`='欢迎来到天禅院。', `FemaleText_loc5`='歡迎來到天僧寺。', `FemaleText_loc7`='Te doy la bienvenida al Monasterio Tian.' WHERE `ID`=66329;
