UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, $n 님! 저는 제자들과 함께 양조사 부프 님의 유명한 맥주를 맛보면서 맥주달 축제를 즐기려고 왔답니다!', `FemaleText_loc4`='很高兴见到你，$n！我和我的学生来品尝酒仙布夫酿造的美酒，顺便庆祝酿月祭！', `FemaleText_loc5`='見到你真好，$n!我跟我的學生來嘗試釀酒大師布夫有名的啤酒，並慶祝酒月節!', `FemaleText_loc7`='¡Me alegro de verte, $n! Mis alumnos y yo hemos venido a probar la famosa cerveza del Maestro cervecero Boof y a celebrar la Cerveza Lunar!' WHERE `ID`=66331;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 운무사로서 어려움에 처한 이들을 도와야 하지요.', `FemaleText_loc4`='作为织雾者，我们必须始终为需要帮助的人提供保护。', `FemaleText_loc5`='做為織霧者，我們總是必須保護那些需要保護的事物。', `FemaleText_loc7`='Como tejedores de niebla, debemos proteger siempre a los necesitados.' WHERE `ID`=66332;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='운무사 니엔 님은 엄격한 스승이시지만 마음은 여리시죠.', `FemaleText_loc4`='织雾者年云也许有些严厉，但实际上是个心地善良的老师。', `FemaleText_loc5`='織霧者年茵是個嚴格的師父，但她的心腸其實很軟。', `FemaleText_loc7`='La tejedora de niebla Nian es una maestra estricta, pero tiene buen corazón.' WHERE `ID`=66333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자매들이여, 마을에 우리 도움이 필요하다. 전선으로 가서 부상자를 치유해라!', `FemaleText_loc4`='姐妹们，村庄需要我们的援助。到前线上去，治疗伤员！', `FemaleText_loc5`='姊妹們，村民需要我們的幫助。到前線去治療傷患吧!', `FemaleText_loc7`='Hermanas, la aldea nos necesita. ¡Diríjanse al frente y sanen a los heridos!' WHERE `ID`=66334;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네!', `FemaleText_loc4`='是，夫人！', `FemaleText_loc5`='是的，夫人!', `FemaleText_loc7`='¡Sí, señora!' WHERE `ID`=66335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 전승지기 푸 님을 처형하려 합니다. 부디 처형을 막을 수 있게 도와주십시오...', `MaleText_loc4`='他们打算处死游学者福云！你一定要帮我阻止他们……', `MaleText_loc5`='他們打算處決博學行者傅!拜託，你得幫我阻止他們...', `MaleText_loc7`='¡Quieren ejecutar al eremita Fu! Por favor, ayúdame a detenerlos...' WHERE `ID`=66336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전승지기님이 목숨을 잃으시면, 동료들의 죽음은 헛일이 될 겁니다...

함께 가셔서 처형을 막아 주시겠습니까?', `MaleText_loc4`='如果游学者被杀害，我们的牺牲就白费了……

你愿意和我一起去阻止他们的处决吗？', `MaleText_loc5`='如果博學行者被殺，我們會有許多人白白的死去...

你願意加入我去阻止這件事嗎?', `MaleText_loc7`='Si el eremita es asesinado, muchos de los nuestros habrán muerto en vano...

¿Querrías acompañarme a detener la ejecución?' WHERE `ID`=66337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 구합시다.', `MaleText_loc4`='我们去救他吧。', `MaleText_loc5`='我們去救他吧。', `MaleText_loc7`='Vamos a salvarle.', `FemaleText_loc1`='가서 구해요.', `FemaleText_loc4`='我们去救他吧。', `FemaleText_loc5`='我們去救他吧。', `FemaleText_loc7`='Vamos a salvarle.' WHERE `ID`=66338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔 님께서 우리에게 힘의 의미를 가르치셨습니다.', `MaleText_loc4`='雪怒教给了我们力量的意义。', `MaleText_loc5`='雪怒教導我們力量的真義。', `MaleText_loc7`='Xuen nos ha enseñado el significado de la fuerza.' WHERE `ID`=66339;
