UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 축제를 보니 쿤라이가 얼마나 아름다운지 새삼 깨닫게 되네요.', `MaleText_loc4`='这个节日让我意识到昆莱山是多么美丽。', `MaleText_loc5`='這個慶典提醒了我，崑萊是個多麼美麗的地方。', `MaleText_loc7`='El festival me recuerda lo bonita que es Kun-Lai.' WHERE `ID`=66341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가, $n. 축제를 즐기고 계신가?', `MaleText_loc4`='你好，$n。你喜欢这个节日吗？', `MaleText_loc5`='你好啊，$n。你喜歡這個節慶嗎?', `MaleText_loc7`='Saludos, $n. ¿Estás disfrutando del festival?' WHERE `ID`=66342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주민들을 보호해야 하네! 내가 정문을 맡을 테니, 나머지는 흩어져서 야운골을 상대하게! 한 놈도 놓쳐서는 안 되네!', `MaleText_loc4`='我们必须保护村民！我来把守前门，你们其他人分散开，别放任何野牛人过去！', `MaleText_loc5`='我們必須保衛村莊!我會守住前門，你們其他人分散開來，別讓任何揚古通過!', `MaleText_loc7`='¡Hay que defender a los aldeanos! Yo me encargo de la puerta principal. Ustedes sepárense y no dejen que pase ningún yaungol.' WHERE `ID`=66343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 새끼 운룡들도 애완동물 대전에 참여할 수 있습니까?', `MaleText_loc4`='这些翔龙幼龙可以参加宠物战斗吗？', `MaleText_loc5`='這些蛟龍寶寶適合當作戰寵嗎?', `MaleText_loc7`='¿Estas crías de dragón son aptas para las batallas de mascotas?', `FemaleText_loc1`='이 새끼 운룡들도 애완동물 대전에 참여할 수 있나요?', `FemaleText_loc4`='这些翔龙幼龙可以参加宠物战斗吗？', `FemaleText_loc5`='這些蛟龍寶寶適合當作戰寵嗎?', `FemaleText_loc7`='¿Estas crías de dragón son aptas para las batallas de mascotas?' WHERE `ID`=66345;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 수련장에도 애완동물 조련사가 있다네. 운룡은 사실 못하는 게 없으니, 다른 애완동물과 대결하는 것 정도야 일도 아니지! 새끼 운룡을 찾아내려면 우선 다 자란 용과 친구가 되어야 하네. 운룡회의 일원으로 승격하면, 도원 여기저기서 새끼 운룡들을 만날 수 있을 거야.', `FemaleText_loc4`='我在我们的训练场地看到一个宠物斗士。云端翔龙无论做什么都一样表现出色，包括与其他宠物战斗！要获得雏龙的关键在于与一只成年翔龙建立良好的关系。只要你在骑士团中的声望达到崇拜，就可以在百木园的各个角落找到它们。', `FemaleText_loc5`='看來，有個寵物對戰者來到了我們訓練場啊。雲蛟幾乎天生就是萬能的，包括跟其他寵物對戰!找到蛟寶寶的關鍵就是跟成年蛟龍建立友誼。一旦你在雲蛟衛的聲望達到崇拜，你就會發現牠們存在於落英園各處。', `FemaleText_loc7`='Veo que tenemos a un luchador para el duelo de mascotas en nuestros campos de entrenamiento. Los dragones nimbo están hechos para cualquier cosa, ¡incluso para luchar contra otras mascotas! La clave para encontrar las crías es hacerse amigo de un adulto. Una vez que te eleven a la orden, las encontrarás repartidas por todo el arboreto.' WHERE `ID`=66346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거대한 모구 조형체 둘이 큰 벽감에 나타납니다!', `MaleText_loc4`='两个巨型构造体出现在大型的壁龛中！', `MaleText_loc5`='兩個泰坦造物出現在大壁龕裡!', `MaleText_loc7`='¡Aparecen dos construcciones titánicas en las enormes habitaciones!', `FemaleText_loc1`='거대한 모구 조형체 둘이 큰 벽감에 나타납니다!', `FemaleText_loc4`='两个巨型构造体出现在大型的壁龛中！', `FemaleText_loc5`='兩個泰坦造物出現在大壁龕裡!', `FemaleText_loc7`='¡Aparecen dos construcciones titánicas en las enormes habitaciones!' WHERE `ID`=66347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 준 님의 명예를 위하여!', `MaleText_loc4`='为了烛恒将军的荣耀！', `MaleText_loc5`='為了曾將軍的榮光!', `MaleText_loc7`='¡Por la gloria del general Zhun!' WHERE `ID`=66348;
