UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 검은 최고다!', `MaleText_loc4`='我的刀法举世无双！', `MaleText_loc5`='我的刀舉世無雙!', `MaleText_loc7`='¡Mi espada no tiene igual!' WHERE `ID`=66351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 두루마리 감독관 폰 님의 제자 앞을 가로막느냐?', `MaleText_loc4`='你竟敢站在司书冯恩的弟子面前？！', `MaleText_loc5`='你膽敢站在文卷大師馮的學生面前?!', `MaleText_loc7`='¡¿Os atrevéis a enfrentaros a un alumno del Maestro de pergaminos Fon?!' WHERE `ID`=66352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한없는 고통을 맛보게 해 주마!', `MaleText_loc4`='你将痛不欲生！', `MaleText_loc5`='你的痛苦將會永無止境!', `MaleText_loc7`='¡Su agonía será interminable!' WHERE `ID`=66353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리통을 부숴 버릴 테다!', `MaleText_loc4`='我要砸碎你的脑袋！', `MaleText_loc5`='我要打爆你的頭!', `MaleText_loc7`='¡Os voy a machacar el cráneo!' WHERE `ID`=66354;
