UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물을 치유할 보급품을 받으려면 비용을 지불해야 합니다.', `MaleText_loc4`='为物资支付一些费用是必需的。', `MaleText_loc5`='購買補給品的小小費用是必須的。', `MaleText_loc7`='Hay una modesta tarifa para suministros.', `FemaleText_loc1`='애완동물을 치유할 보급품을 받으려면 비용을 지불해야 합니다.', `FemaleText_loc4`='为物资支付一些费用是必需的。', `FemaleText_loc5`='購買補給品的小小費用是必須的。', `FemaleText_loc7`='Hay una modesta tarifa para suministros.' WHERE `ID`=66369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방패에는 파수병 쿠야오라는 이름이 새겨져 있습니다. 그 아이의 아버지 것입니다.', `MaleText_loc4`='盾牌上刻着：哨兵姚枯。它属于那个男孩的父亲。', `MaleText_loc5`='盾牌上刻著:哨兵庫堯。它屬於這男孩的父親。', `MaleText_loc7`='El escudo tiene grabado "Centinela Ku-Yao". Pertenece al padre del niño.', `FemaleText_loc1`='방패에는 파수병 쿠야오라는 이름이 새겨져 있습니다. 그 아이의 아버지 것입니다.', `FemaleText_loc4`='盾牌上刻着：哨兵姚枯。它属于那个男孩的父亲。', `FemaleText_loc5`='盾牌上刻著:哨兵庫堯。它屬於這男孩的父親。', `FemaleText_loc7`='El escudo tiene grabado "Centinela Ku-Yao". Pertenece al padre del niño.' WHERE `ID`=66370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침낭은 비어 있습니다. 쿠야오는 이곳에 없습니다.', `MaleText_loc4`='姚枯的被窝是空的。他不在这。', `MaleText_loc5`='庫堯的床舖是空的。他不在這裡。', `MaleText_loc7`='El lecho de Ku-Yao esta vacío. No está aquí.', `FemaleText_loc1`='침낭은 비어 있습니다. 쿠야오는 이곳에 없습니다.', `FemaleText_loc4`='姚枯的被窝是空的。他不在这。', `FemaleText_loc5`='庫堯的床舖是空的。他不在這裡。', `FemaleText_loc7`='El lecho de Ku-Yao esta vacío. No está aquí.' WHERE `ID`=66371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수병 쿠야오의 야크, 하차입니다.', `MaleText_loc4`='这是哈查，哨兵姚枯的牦牛。', `MaleText_loc5`='這是哈查，哨兵庫堯的犛牛。', `MaleText_loc7`='Este es Ha-Cha, el yak del centinela Ku-Yao.', `FemaleText_loc1`='파수병 쿠야오의 야크, 하차입니다.', `FemaleText_loc4`='这是哈查，哨兵姚枯的牦牛。', `FemaleText_loc5`='這是哈查，哨兵庫堯的犛牛。', `FemaleText_loc7`='Este es Ha-Cha, el yak del centinela Ku-Yao.' WHERE `ID`=66372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠야오를 찾는다고? 며칠 전부터 안 보이던데. 무슨 일이 생긴 건 아니겠지?', `MaleText_loc4`='你在寻找姚枯吗？我好几天没有看到他了。你说他会不会遇到麻烦了？', `MaleText_loc5`='你在找庫堯?我好幾天沒見到他了。你該不會認為他有麻煩了吧，是嗎?', `MaleText_loc7`='¿Buscas a Ku-Yao? Hace días que no lo veo. ¿No pensarás que se ha metido en líos?', `FemaleText_loc1`='쿠야오를 찾는다고요? 며칠 전부터 안 보이던데. 무슨 일이 생긴 건 아니겠죠?', `FemaleText_loc4`='你在寻找姚枯吗？我好几天没有看到他了。你说他会不会遇到麻烦了？', `FemaleText_loc5`='你在找庫堯?我好幾天沒見到他了。你該不會認為他有麻煩了吧，是嗎?', `FemaleText_loc7`='¿Buscas a Ku-Yao? Hace días que no lo veo. ¿No pensarás que se ha metido en líos?' WHERE `ID`=66373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요. 이제 계속 아빠를 찾아야겠어요.', `MaleText_loc4`='感谢你的帮助，$g先生:女士;。我现在要继续寻找我的爸爸了。', `MaleText_loc5`='謝謝你的幫忙，$g先生:女士;。我現在要繼續去找我的父親了。', `MaleText_loc7`='Gracias por tu ayuda, $gseñor:señorita;. Ahora voy a seguir buscando a mi papá.' WHERE `ID`=66374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 아빠를 찾았으면 좋겠네요.', `MaleText_loc4`='希望我能找到他。', `MaleText_loc5`='我希望我能找到他。', `MaleText_loc7`='Espero encontrarlo.' WHERE `ID`=66375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 음영파로군. 나를 도와주러 온 거요?', `MaleText_loc4`='你……影踪派。你是来帮助我的？', `MaleText_loc5`='你...影潘。你來這兒幫我的嗎?', `MaleText_loc7`='Tú... Shadopan. ¿Has venido a ayudarme?' WHERE `ID`=66376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아들... 아들이 여기 있다고? 살아서?!', `MaleText_loc4`='我的儿子……他在这儿？安然无恙！？', `MaleText_loc5`='我的兒子...他在這兒?還活著!?', `MaleText_loc7`='Mi hijo... ¿está aquí? ¡¿Vivo?!' WHERE `ID`=66377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 아들 쿠모가 당신을 찾고 있습니다.', `MaleText_loc4`='是的。你的儿子莫苦，他一直在寻找你。', `MaleText_loc5`='是的。你的兒子，庫摩，他在找你。', `MaleText_loc7`='Sí. Tu hijo, Ku-Mo, te ha estado buscando.', `FemaleText_loc1`='맞아요. 아들 쿠모가 당신을 찾고 있어요.', `FemaleText_loc4`='是的。你的儿子莫苦，他一直在寻找你。', `FemaleText_loc5`='是的。你的兒子，庫摩，他在找你。', `FemaleText_loc7`='Sí. Tu hijo, Ku-Mo, te ha estado buscando.' WHERE `ID`=66378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿠모는 지금 음영파 주둔지에 있습니다. 여기 연이 있으니 타고 가십시오!', `MaleText_loc4`='他现在身处影踪卫戍营。这儿有只风筝。去看看他吧！', `MaleText_loc5`='他現在人在影潘要塞。這是風箏。去見他吧!', `MaleText_loc7`='Está en el Cuartel del Shadopan ahora mismo. Toma esta cometa. ¡Ve a verlo!', `FemaleText_loc1`='쿠모는 지금 음영파 주둔지에 있어요. 여기 연이 있으니 타고 가세요!', `FemaleText_loc4`='他现在身处影踪卫戍营。这儿有只风筝。去看看他吧！', `FemaleText_loc5`='他現在人在影潘要塞。這是風箏。去見他吧!', `FemaleText_loc7`='Está en el Cuartel del Shadopan ahora mismo. Toma esta cometa. ¡Ve a verlo!' WHERE `ID`=66379;
