UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명의 웅덩이를 정화하려면 플레이어 세 명이 필요합니다!', `MaleText_loc4`='需要三名玩家才能净化生命之池！', `MaleText_loc5`='需要三個玩家來淨化生命之池!', `MaleText_loc7`='¡Hacen falta tres jugadores para purificar la Poza de vida!', `FemaleText_loc1`='생명의 웅덩이를 정화하려면 플레이어 세 명이 필요합니다!', `FemaleText_loc4`='需要三名玩家才能净化生命之池！', `FemaleText_loc5`='需要三個玩家來淨化生命之池!', `FemaleText_loc7`='¡Hacen falta tres jugadores para purificar la Poza de vida!' WHERE `ID`=66381;
