UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호박석 덩어리가 아마도 클락시가 찾는 바로 그걸 겁니다.', `MaleText_loc4`='这可能就是卡拉克西正在寻找的那块琥珀。', `MaleText_loc5`='這塊琥珀或許就是卡拉西要找的東西。', `MaleText_loc7`='Este trozo de ámbar podría ser exactamente lo que buscan los Klaxxi.' WHERE `ID`=66385;
