UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와...', `MaleText_loc4`='哇……', `MaleText_loc5`='呼啊...', `MaleText_loc7`='Guau...' WHERE `ID`=66390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 잠들었을 때에도 나는 여제의 공포를 들었다.', `MaleText_loc4`='即使在梦中，我也能听到她的恐惧。', `MaleText_loc5`='即使在睡眠中，我還是能聽到她的驚懼。', `MaleText_loc7`='Hasta en sueños oigo su terror.' WHERE `ID`=66391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움이 여제의 마음과 몸을 사로잡고 있다. 이제 여제는 제국을 다스릴 만한 존재가 아니다.', `MaleText_loc4`='恐惧控制了她的灵魂和躯体。女皇已经不再适合统治帝国。', `MaleText_loc5`='恐懼掌握了她的身體與心靈。女皇不再適合統治這個帝國了。', `MaleText_loc7`='El miedo invade su cuerpo y su mente. La Emperatriz ya no está capacitada para gobernar el imperio.' WHERE `ID`=66392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨어날 시간이 분명히 얼마 남지 않았을 텐데, 그들은 아직도 내게 오지를 않았다. 클락시는 왜 기다리는 건가?', `MaleText_loc4`='觉醒的时刻就要到来，但他们还没有来找我。卡拉克西还在等什么？', `MaleText_loc5`='甦醒的時刻必定已然接近，但他們還沒來找我。卡拉西在等什麼?', `MaleText_loc7`='La hora del despertar debe de estar próxima, pero no han venido a verme. ¿Por qué esperan los Klaxxi?' WHERE `ID`=66393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 존재가 다가온다! 밖에 있는 누군가가 내 목소리를 들을 수 있어! 그런데... 클락시는 아니구나.', `MaleText_loc4`='有气息在逼近！有人能听见我说话！可……那不是卡拉克西。', `MaleText_loc5`='有東西接近了!外頭有人聽見我的聲音!但...那不是卡拉西。', `MaleText_loc7`='¡Se acerca una presencia! ¡Alguien puede oírme! Pero... no es un Klaxxi.' WHERE `ID`=66394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지! 부서뜨려라! 이 호박석의 수면에서 나를 풀어다오!', `MaleText_loc4`='是的！把它打破！将我从琥珀的沉眠中释放出来！', `MaleText_loc5`='沒錯!打破它!將我從琥珀沉眠中解放出來!', `MaleText_loc7`='¡Sí! ¡Rómpelo! ¡Libérame de este sueño de ámbar!' WHERE `ID`=66395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥 임프 포기', `MaleText_loc4`='放弃邪能小鬼', `MaleText_loc5`='放棄魔化小鬼', `MaleText_loc7`='Abandonar diablillo vil', `FemaleText_loc1`='지옥 임프 포기', `FemaleText_loc4`='放弃邪能小鬼', `FemaleText_loc5`='放棄魔化小鬼', `FemaleText_loc7`='Abandonar diablillo vil' WHERE `ID`=66397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허군주 포기', `MaleText_loc4`='放弃虚空领主', `MaleText_loc5`='放棄虛無領主', `MaleText_loc7`='Abandonar señor del vacío', `FemaleText_loc1`='공허군주 포기', `FemaleText_loc4`='放弃虚空领主', `FemaleText_loc5`='放棄虛無領主', `FemaleText_loc7`='Abandonar señor del vacío' WHERE `ID`=66398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬바라 포기', `MaleText_loc4`='放弃破坏魔', `MaleText_loc5`='放棄希瓦拉', `MaleText_loc7`='Abandonar shivarra', `FemaleText_loc1`='쉬바라 포기', `FemaleText_loc4`='放弃破坏魔', `FemaleText_loc5`='放棄希瓦拉', `FemaleText_loc7`='Abandonar shivarra' WHERE `ID`=66399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자 포기', `MaleText_loc4`='放弃眼魔', `MaleText_loc5`='放棄觀察者', `MaleText_loc7`='Abandonar observador', `FemaleText_loc1`='감시자 포기', `FemaleText_loc4`='放弃眼魔', `FemaleText_loc5`='放棄觀察者', `FemaleText_loc7`='Abandonar observador' WHERE `ID`=66400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='격노수호병 포기', `MaleText_loc4`='放弃愤怒卫士', `MaleText_loc5`='放棄憤怒守衛', `MaleText_loc7`='Abandonar guardia de cólera', `FemaleText_loc1`='격노수호병 포기', `FemaleText_loc4`='放弃愤怒卫士', `FemaleText_loc5`='放棄憤怒守衛', `FemaleText_loc7`='Abandonar guardia de cólera' WHERE `ID`=66401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 시도해 볼 준비가 되면 말씀하십시오.', `MaleText_loc4`='等你准备好再试一遍的时候，来找我谈谈。', `MaleText_loc5`='準備好再次嘗試時就來跟我說。', `MaleText_loc7`='Habla conmigo cuando quieras volver a intentarlo.', `FemaleText_loc1`='다시 시도해 볼 준비가 되면 말씀하세요.', `FemaleText_loc4`='等你准备好再试一遍的时候，来找我谈谈。', `FemaleText_loc5`='準備好再次嘗試時就來跟我說。', `FemaleText_loc7`='Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=66402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소멸됐다!', `MaleText_loc4`='灭亡吧！', `MaleText_loc5`='消滅了!', `MaleText_loc7`='Extinguido.' WHERE `ID`=66403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 건 화가 나던?', `MaleText_loc4`='这让你生气吗？', `MaleText_loc5`='這讓你生氣了嗎?', `MaleText_loc7`='¿Eso te hace enfadar?' WHERE `ID`=66404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 느껴라!', `MaleText_loc4`='感受你的愤怒！', `MaleText_loc5`='感受你的怒火!', `MaleText_loc7`='¡Siente tu ira!' WHERE `ID`=66405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노가 널 잠식하리라!', `MaleText_loc4`='让怒火吞噬你！', `MaleText_loc5`='讓你的怒火吞噬你...', `MaleText_loc7`='Deja que la ira te consuma...' WHERE `ID`=66406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 분노로 날 살찌워라!', `MaleText_loc4`='让我痛饮你的愤怒！', `MaleText_loc5`='獻上你的怒火吧!', `MaleText_loc7`='¡Fortalézcanme con su rabia!' WHERE `ID`=66407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노를 보여주마!', `MaleText_loc4`='我的怒火无人能挡！！', `MaleText_loc5`='釋放我的怒火!', `MaleText_loc7`='¡MI FURIA NO TIENE LÍMITES!' WHERE `ID`=66408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑 가까이에 내려주겠다. 이런 호의를 자주 바라지는 마라.', `MaleText_loc4`='我会把你放在塔附近。不要掉以轻心。', `MaleText_loc5`='我會讓你落在高塔附近。不要太習慣這種事。', `MaleText_loc7`='Te dejaré cerca de la torre. No te acostumbres.' WHERE `ID`=66409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탑이 바로 저기 있다. 내가 하늘에서 엄호해주겠다. 어서 서둘러라.', `MaleText_loc4`='塔就在那边。我会在空中掩护你。动作快。', `MaleText_loc5`='塔就在那裡。我會從空中掩護你。動作要快。', `MaleText_loc7`='La torre está ahí mismo. Te cubriré desde el cielo. Date prisa.' WHERE `ID`=66410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승강기 통로에서 삐걱거리는 소리가 들려 옵니다!', `MaleText_loc4`='从升降机井里传来一声刺耳的噪音！', `MaleText_loc5`='你聽見升降梯井中傳來摩擦的噪音!', `MaleText_loc7`='Oyes un ruido de engranajes que proviene del hueco del ascensor.', `FemaleText_loc1`='승강기 통로에서 삐걱거리는 소리가 들려 옵니다!', `FemaleText_loc4`='从升降机井里传来一声刺耳的噪音！', `FemaleText_loc5`='你聽見升降梯井中傳來摩擦的噪音!', `FemaleText_loc7`='Oyes un ruido de engranajes que proviene del hueco del ascensor.' WHERE `ID`=66411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심장 수술할 시간이다!', `MaleText_loc4`='该给你们做个心脏小手术了！', `MaleText_loc5`='心臟手術的時間到了!', `MaleText_loc7`='¡Hora de operar a corazón abierto!' WHERE `ID`=66412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸은... 과학을 위해... 기증해 줘...', `MaleText_loc4`='将我的……身体……献给科学……', `MaleText_loc5`='我的身體...獻給...科學...', `MaleText_loc7`='Donen... mi cuerpo... a la ciencia…' WHERE `ID`=66413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수술 대성공!', `MaleText_loc4`='又一次成功的手术！', `MaleText_loc5`='手術又成功啦!', `MaleText_loc7`='¡Otra operación realizada con éxito!' WHERE `ID`=66414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 랜달 P. 워커가 산책을 가야겠군요.', `MaleText_loc4`='我想该兰达尔·P·沃克登场了。', `MaleText_loc5`='我想來做個蘭達爾·P式的散步的時候到了。', `MaleText_loc7`='Creo que es hora de ir a dar un paseo.' WHERE `ID`=66415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 길이 없군요. 랜달 P. 워커는 헤엄을 쳐야겠습니다.', `MaleText_loc4`='嗯……无路可走。看来兰达尔·P·沃克得游泳了。', `MaleText_loc5`='嗯...沒有路了。我猜我得進行蘭達爾·P式的游泳了。', `MaleText_loc7`='Mmm... No hay camino. Tendré que nadar.' WHERE `ID`=66416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='즐거웠습니다. 이제 랜달 P. 워커는 좀 쉬어야겠군요.', `MaleText_loc4`='那可真不错。现在兰达尔·P·沃克该休息了。', `MaleText_loc5`='真是令人愉快。現在是蘭達爾·P式的休息時間。', `MaleText_loc7`='Ha estado bien. Ahora es el momento de descansar.' WHERE `ID`=66417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|Tinterface\\Icons\\item_earthenmight.blp:20|t %s|1이;가; |cFFFF0000|Hspell:128107|h[지각 융기]|h|r를 시전합니다! 조심하십시오!', `MaleText_loc4`='|TInterface\\Icons\\item_earthenmight.blp:20|t %s开始施放|cFFFF0000|Hspell:128107|h[升腾大地]|h|r！小心！', `MaleText_loc5`='|TInterface\\Icons\\item_earthenmight.blp:20|t%s開始施放|cFFFF0000|Hspell:128107|h[大地怒震]|h|r!小心!', `MaleText_loc7`='|TInterfaceIconsitem_earthenmight.blp:20|t ¡%s empieza a lanzar |cFFFF0000|Hspell:128107|h[Levantar tierra]|h|r! ¡Ten cuidado!' WHERE `ID`=66418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='랜달 P. 워커가 뛰어올라야겠군요.', `MaleText_loc4`='兰达尔·P·沃克看来该跳跃了。', `MaleText_loc5`='看來做個蘭達爾·P式的跳躍的時候到了。', `MaleText_loc7`='Parece que es hora de saltar.' WHERE `ID`=66419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다, 클락시바여. 의회의 명령을 듣는 것을 내 얼마나 오래도록 기다렸던가!', `MaleText_loc4`='是，卡拉克西瓦。长久以来，我一直在苦等议会的命令！', `MaleText_loc5`='是的，卡拉西瓦。我等了多久才聽見議會的命令啊!', `MaleText_loc7`='Sí, Klaxxi''va. ¡Cuánto tiempo he esperado para escuchar la orden del consejo!' WHERE `ID`=66420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다. 내가 처음으로 긴 잠에 빠져든 뒤로 많은 일이 일어났구나.', `MaleText_loc4`='我明白。自从我开始长眠，已经发生了翻天覆地的变化。', `MaleText_loc5`='我明白。自從我第一次陷入長眠以來，許多事物已經改變了。', `MaleText_loc7`='Ya veo. Han pasado muchas cosas desde que comenzó mi largo sueño.' WHERE `ID`=66421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신호를 교란시키진 못할 거다!', `MaleText_loc4`='你休想破坏调谐！', `MaleText_loc5`='你不能干擾音頻!', `MaleText_loc7`='¡No interrumpiréis la armonización!' WHERE `ID`=66422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 힘의 근원은 무엇인가? 대답하기 전에 곰곰히 생각해 보게. 모험가들은 무기나 장비, 비전의 힘이 담긴 고서라고 답하는 일이 많더군.', `MaleText_loc4`='你的力量源自哪里？回答前好好想想。很多人都归因于他们手中的武器、身上的装备，或是奥术力量宝典。', `MaleText_loc5`='你的力量之源是什麼?想清楚再回答。許多冒險家會說那是他們的武器，或是裝備，或是具有秘法力量的書籍。', `MaleText_loc7`='¿Cuál es la fuente de tu poder? Piénsalo bien antes de contestar. Muchos aventureros señalan sus armas, o su equipo, o libros de conocimientos arcanos.' WHERE `ID`=66423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래전, 우리 판다렌이 모구 제국의 노예였을 때, 우리는 무기를 지니고 다니는 것이 금지되었다네. 우린 전사가 아니었어. 그리고 마법과 칼 없이 모구와 싸울 수 있을 거라고는 누구도 생각하지 않았네.', `MaleText_loc4`='很久以前，我的族人还是魔古帝国的奴隶，他们被禁止携带武器。他们不是战士，既无魔法也无钢铁，没人相信他们能对抗魔古族。', `MaleText_loc5`='很久很久以前，我們的人民還是魔古帝國的奴隸的時候，我們完全被禁止攜帶任何武器。我們不是戰士。而沒有人相信我們能手無寸鐵地與魔古戰鬥。', `MaleText_loc7`='Hace mucho, cuando mis antepasados eran esclavos del imperio mogu, tenían prohibido llevar armas. No éramos luchadores. Y nadie creía que pudiéramos enfrentarnos a los mogu sin magia ni acero.' WHERE `ID`=66424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 새벽의 주먹, 캉이 우리 눈을 뜨게 해 주기 전까지는.', `MaleText_loc4`='直到曙光之拳——康，拨开了我们的双眼。', `MaleText_loc5`='直到康恩，破曉之拳，替我們開了眼。', `MaleText_loc7`='Hasta que Kang, el Puño del Primer Alba, nos abrió los ojos.' WHERE `ID`=66425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어느 날, 수도사 캉이 다른 노예들에게 도전했네. "날 때려봐!" 이렇게 외쳤지.', `MaleText_loc4`='有一天，这位饱受爱戴的武僧向他的奴隶同伴们发起了挑战。“过来打我！”他命令道。', `MaleText_loc5`='有一天，這個受人敬愛的僧侶向他的奴隸同伴提出挑戰。他大叫:「打我!」。', `MaleText_loc7`='Un día, el venerable monje desafió a sus compañeros esclavos. "¡Golpéenme!", les dijo a sus hermanos.' WHERE `ID`=66426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깜짝 놀란 노예들이 캉을 둘러싸고 때리려고 했지. 하나씩 모두 실패했는데, 캉은 마치 춤추는 것처럼 주먹을 막아내고, 바람 속 갈대처럼 공격을 피했다고 하네.', `MaleText_loc4`='奴隶们非常诧异，尝试着攻击康，结果无一例外地失败了。他如舞者般格挡着他们的拳脚，如风中芦苇般闪避着他们的攻击。', `MaleText_loc5`='在驚訝中，被囚禁的熊貓人奴隸們試著攻擊康恩。他們一個接一個地失敗了，因為他像舞者一般地擋住他們的拳頭，也像風中的蘆葦一樣閃避他們的攻擊。', `MaleText_loc7`='Los pobres esclavos pandaren, sorprendidos, trataron de golpear a Kang. Uno por uno, fracasaron, ya que Kang interceptada sus ataques como si bailara y los esquivaba al ritmo del viento.' WHERE `ID`=66427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 말했네. "모구의 채찍을 맞아 우리 등은 단단해졌어. 요새를 짓느라 우리 팔은 강인해졌고, 적의 곁에서 일하느라 우리 머리는 예리해졌다고. 모구가 강하다고 생각해? 우리가 바로 모구의 힘이야!"', `MaleText_loc4`='“我们的脊背因鞭打而变得硬实，”他告诉他们，“我们的手臂因建造堡垒而变得强壮。我们的头脑因与敌共处而变得敏锐。你们以为魔古族更强大？我想说，我们才是他们的力量！”', `MaleText_loc5`='「我們的背因魔古的鞭打而變的堅硬。」他這樣告訴他們。「我們的雙臂因建造他們的堡壘而強壯。我們的心靈因為在敵人身邊工作而變的敏銳。你們認為魔古比較強大?我說我們才是他們的力量!」', `MaleText_loc7`='"Nuestras espaldas están endurecidas por los látigos de los mogu", les dijo. "Nuestros brazos están fuertes por haber construido sus fortalezas. Nuestras mentes están agudizadas por trabajar para el enemigo. ¿Creen que los mogu son más fuertes? ¡Nosotros somos su fuerza!".' WHERE `ID`=66428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부, 벽돌공, 목동과 대장장이까지... 모두 캉 앞에 고개를 숙이고 말했지. "우리에게 싸우는 법을 가르쳐 주십시오."', `MaleText_loc4`='那些农夫、砖瓦工、牧羊人和铁匠纷纷跪拜说道，“康，教教我们如何战斗吧。”', `MaleText_loc5`='農夫、砌磚工、牧羊人跟鐵匠...他們都向康恩鞠躬。他們說:「教教我們!教我們如何戰鬥。」', `MaleText_loc7`='Los granjeros, los obreros, los pastores, los herreros... Todos se inclinaron ante Kang. "Enséñanos", les dijo. "Enséñanos a luchar".' WHERE `ID`=66429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 들었을 때는, 모두 전사가 되어 있었어.', `MaleText_loc4`='而当他们起身时……他们已成为战士。', `MaleText_loc5`='而當他們揭竿而起時...他們都已經成為了戰士。', `MaleText_loc7`='Y cuando se alzaron... se alzaron como guerreros.' WHERE `ID`=66430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 목소리, 자네 손. 그게 진정한 영웅의 힘이네. 잘 사용하면 세계를 변화시킬 수 있을 거야.', `MaleText_loc4`='你的声音。你的双手。这些成就了真正的英雄。善加利用……你便能改变世界。', `MaleText_loc5`='你的言語。你的雙手。這些才是英雄真正的工具。好好利用它們...你就能改變世界。', `MaleText_loc7`='Tu voz. Tus manos. Esas son las armas de los auténticos héroes. Úsalas bien... y podrás cambiar el mundo.' WHERE `ID`=66431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나뭇진이 굳지 않게 하려면 뛰어오르십시오!', `MaleText_loc4`='跳起以阻止树脂硬化！', `MaleText_loc5`='用跳躍防止樹脂硬化!', `MaleText_loc7`='¡Salta para impedir que la resina se endurezca!', `FemaleText_loc1`='나뭇진이 굳지 않게 하려면 뛰어오르십시오!', `FemaleText_loc4`='跳起以阻止树脂硬化！', `FemaleText_loc5`='用跳躍防止樹脂硬化!', `FemaleText_loc7`='¡Salta para impedir que la resina se endurezca!' WHERE `ID`=66432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 땅벌레들. 내 구역에 들어오면 너희를 이 밖으로 내던지고, 그 죽는 소리를 감상해주마!', `MaleText_loc4`='没翅膀的可怜虫也敢踏足我的地盘。我马上就会听见你从平台上摔下去时发出的惨叫！', `MaleText_loc5`='沒有翅膀的可憐蟲。你們踏入的可是我的地盤，我要好好來聽你們從殿堂墜落的臨死嚎叫。', `MaleText_loc7`='Patéticas orugas sin alas. Entren en mis dominios, ¡y escucharé sus gritos de agonía mientras caen de esta terraza!' WHERE `ID`=66433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세트티크! 정렬! 판다리아의 바람을 누가 지배하는지 보여줘라!', `MaleText_loc4`='赛特提克，列阵！让他们瞧瞧谁才是潘达利亚的御风者！', `MaleText_loc5`='賽特席克，現身吧!讓他們瞧瞧潘達利亞的御風者!', `MaleText_loc7`='¡Set''thik! ¡En formación! ¡Demúestrenles quién controla los vientos de Pandaria!' WHERE `ID`=66434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 숨결이여, 우리에게 무적의 가랄론을 내리소서!', `MaleText_loc4`='女皇之息，带来强大的加拉隆吧！', `MaleText_loc5`='女皇之息啊，把強大的加拉隆帶來這裡吧!', `MaleText_loc7`='Aliento de la Emperatriz, ¡tráenos al poderoso Garalon!' WHERE `ID`=66435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가랄론, 놈들의 뼈를 갈아버려라!', `MaleText_loc4`='加拉隆，碾碎他们的骨头！', `MaleText_loc5`='加拉隆，把他們連骨頭一起碾成灰!', `MaleText_loc7`='Garalon, ¡pulveriza sus huesos!' WHERE `ID`=66436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 수가! 너희들! 난간뜰 꼭대기로! 여왕님을 지켜야 한다!', `MaleText_loc4`='不可能！瑟里提克、扎尔提克、库尔提克，到平台顶上来！我们必须守卫女皇！', `MaleText_loc5`='不可能!瑟里席克，薩爾席克，闊席克，到殿堂頂端!我們得保護女皇!', `MaleText_loc7`='¡Imposible! Sra''thik, Zar''thik, Kor''thik, ¡a lo alto de la terraza! ¡Debemos defender a la Emperatriz!' WHERE `ID`=66437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용거북 때문에 왔는가, 젊은이? 미안하네. 자네가 우리 민족의 친우라는 걸 증명하기 전에는 도와줄 수가 없네.', `MaleText_loc4`='孩子，我想你是为龙龟而来的吧？很抱歉。你得先证明自己是我族人民的忠实盟友才行。', `MaleText_loc5`='我想你是為了龍龜而來的吧，孩子?我很抱歉。在你證明自己是我的人民的忠實盟友之前，我都不會幫你。', `MaleText_loc7`='Creía que habías venido por las tortugas dragón. Lo siento. No puedo ayudarte hasta que demuestres ser un leal aliado de mi pueblo.', `FemaleText_loc1`='용거북 때문에 왔는가, 젊은이? 미안하네. 자네가 우리 민족의 친우라는 걸 증명하기 전에는 도와줄 수가 없네.', `FemaleText_loc4`='孩子，我想你是为龙龟而来的吧？很抱歉。你得先证明自己是我族人民的忠实盟友才行。', `FemaleText_loc5`='我想你是為了龍龜而來的吧，孩子?我很抱歉。在你證明自己是我的人民的忠實盟友之前，我都不會幫你。', `FemaleText_loc7`='Creía que habías venido por las tortugas dragón. Lo siento. No puedo ayudarte hasta que demuestres ser un leal aliado de mi pueblo.' WHERE `ID`=66438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용거북 때문에 왔는가, 젊은이?', `MaleText_loc4`='孩子，我想你是为龙龟而来的吧？', `MaleText_loc5`='我想你是為了龍龜而來的吧，孩子?', `MaleText_loc7`='¿Supongo que vienes por las tortugas dragón?', `FemaleText_loc1`='용거북 때문에 왔는가, 젊은이?', `FemaleText_loc4`='孩子，我想你是为龙龟而来的吧？', `FemaleText_loc5`='我想你是為了龍龜而來的吧，孩子?', `FemaleText_loc7`='¿Supongo que vienes por las tortugas dragón?' WHERE `ID`=66439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 용거북을 팔고 있습니까?', `MaleText_loc4`='哪种龙龟是可以出售的？', `MaleText_loc5`='有哪些龍龜是要賣的?', `MaleText_loc7`='¿Qué tortugas dragón están a la venta?', `FemaleText_loc1`='어떤 용거북을 팔고 있습니까?', `FemaleText_loc4`='哪种龙龟是可以出售的？', `FemaleText_loc5`='有哪些龍龜是要賣的?', `FemaleText_loc7`='¿Qué tortugas dragón están a la venta?' WHERE `ID`=66440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 승리했습니다!', `MaleText_loc4`='部落胜利了！', `MaleText_loc5`='部落勝利了!', `MaleText_loc7`='¡La Horda gana!' WHERE `ID`=66441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 승리했습니다!', `MaleText_loc4`='联盟获胜！', `MaleText_loc5`='聯盟勝利了!', `MaleText_loc7`='¡La Alianza gana!' WHERE `ID`=66442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지 오다니 잘 됐군. 내 힘과 기술을 모두에게 증명할 수 있겠어!', `MaleText_loc4`='但愿他们能闯过来。这样才能让人们看清我的实力！', `MaleText_loc5`='我希望他們能順利來到這裡，這樣大家就會明白我的力量和技巧了!', `MaleText_loc7`='Espero que lleguen hasta aquí. ¡Así todos verán mi fuerza y mi pericia!' WHERE `ID`=66443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 너희 모두 여기 온 걸 후회하게 될 거다...', `MaleText_loc4`='哈哈！你们很快就会后悔选了这条路……', `MaleText_loc5`='啊哈!你們很多人很快就會希望沒有來過這裡...', `MaleText_loc7`='¡Ajá! Pronto todos desearán no haber venido nunca…' WHERE `ID`=66444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 나는... 이제 누가...?!', `MaleText_loc4`='不……我是……谁还能……？！', `MaleText_loc5`='但是...我是...誰取代...?!', `MaleText_loc7`='Pero... si yo... ¿quién...?' WHERE `ID`=66445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 뼈를 조각해 병사들의 무기를 장식해야겠다!', `MaleText_loc4`='我要把你的骨头雕成武器上的装饰品！', `MaleText_loc5`='你們的骨頭都會成為我族戰士武器上的裝飾品!', `MaleText_loc7`='¡Decoraremos las armas de nuestros guerreros con tus huesos!' WHERE `ID`=66446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 이길 생각을 해?!', `MaleText_loc4`='你以为自己会有机会吗？！', `MaleText_loc5`='你們認為有可能打敗我?!', `MaleText_loc7`='¡¿Creías que tenías alguna posibilidad?!' WHERE `ID`=66447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석 연금술의 힘을 보여주마...', `MaleText_loc4`='让我给你们展示一下琥珀炼金术吧……', `MaleText_loc5`='容我向你們展示琥珀鍊金術的威力...', `MaleText_loc7`='Permítanme que les muestre el poder de la alquimia de ámbar…' WHERE `ID`=66448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, 외부인들이여. 스노우드리프트 사부님께서 도장 안에서 기다리고 계십니다. 사부님 앞에서는 예를 차리십시오.', `MaleText_loc4`='欢迎你，外来者。雪流大师正在学院里等着你呢。请对大师表示应有的尊重。', `MaleText_loc5`='歡迎，外來者。雪迅大師在學校裡等你。請記得要對大師表現出適當的尊敬。', `MaleText_loc7`='Bienvenidos, forasteros. El maestro Ventisca Algente los espera dentro de la escuela. Recuerden mostrarle el debido respeto al maestro.', `FemaleText_loc1`='안녕하세요, 외부인들이여. 스노우드리프트 사부님께서 도장 안에서 기다리고 계세요. 사부님 앞에서는 예를 차리세요.', `FemaleText_loc4`='欢迎你，外来者。雪流大师正在学院里等着你呢。请对大师表示应有的尊重。', `FemaleText_loc5`='歡迎，外來者。雪迅大師在學校裡等你。請記得要對大師表現出適當的尊敬。', `FemaleText_loc7`='Bienvenidos, forasteros. El maestro Ventisca Algente los espera dentro de la escuela. Recuerden mostrarle el debido respeto al maestro.' WHERE `ID`=66449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제 셰크지르가 우리 제국을 혼란에 빠뜨린 것 같구나. 이것은 반드시 짚고 넘어가야 한다. 하지만 그보다 먼저, 내 힘을 회복해야만 한다.', `MaleText_loc4`='看来女皇夏柯希尔已经把我们的帝国搞得乌烟瘴气。这个问题必须得到解决。但首先，我得恢复自己的力量。', `MaleText_loc5`='看來杉齊爾女皇讓我們的帝國墮入混亂。我們必須解決這件事。但首先，我必須取回我的力量。', `MaleText_loc7`='Parece que la emperatriz Shek''zeer ha dejado que el caos se apodere de nuestro imperio. Debemos solucionarlo, pero antes tengo que recuperar fuerzas.' WHERE `ID`=66451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 날개가 정말 빠르다고 하지 않았나? 움직임이 제일 느리구나, 깨우는 자여.', `MaleText_loc4`='我没说过我能神速翱翔么？你移动得可真慢啊，唤醒者。', `MaleText_loc5`='我沒說過我的翅膀飛起來很快嗎?你移動的速度慢多了，喚醒者。', `MaleText_loc7`='¿No te dije que mis alas eran veloces? Te mueves con gran lentitud, heraldo.' WHERE `ID`=66452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 있는 붉은십자군 병력은 그들의 지휘관이 공격당할 때 보좌해줄 만반의 태세를 갖추고 있습니다.', `MaleText_loc4`='附近的血色十字军兵力正蓄势待发，一旦指挥官遭到攻击，立刻出手相助。', `MaleText_loc5`='附近的血色十字軍部隊已經準備好在他們的指揮官遭受攻擊時支援他。', `MaleText_loc7`='Los efectivos de la Cruzada Escarlata están listos para ayudar a su comandante si este recibe algún ataque.' WHERE `ID`=66453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2...', `MaleText_loc4`='2……', `MaleText_loc5`='2...', `MaleText_loc7`='2...' WHERE `ID`=66454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 정말 날씨가 좋군요.', `MaleText_loc4`='今天可真是个好日子。', `MaleText_loc5`='今天真是個好日子。', `MaleText_loc7`='Hace un día precioso.' WHERE `ID`=66455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걷기를 좋아하십니까? 전 정말 좋아합니다.', `MaleText_loc4`='你喜欢步行么？我很喜欢。', `MaleText_loc5`='你喜歡散步嗎?我喜歡散步。', `MaleText_loc7`='¿Te gusta andar? A mí sí.' WHERE `ID`=66456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 얼마나 걸은 건지 모르겠군요.', `MaleText_loc4`='我已经不知道我们走了多久了。', `MaleText_loc5`='我已經不知道我們到底走多久了。', `MaleText_loc7`='Ya he perdido la cuenta de cuánto hemos andado.' WHERE `ID`=66457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 언제 오셨습니까?', `MaleText_loc4`='噢！你什么时候来的？', `MaleText_loc5`='喔!你什麼時候到這裡的?', `MaleText_loc7`='¡Oh! ¿Cuándo has venido?' WHERE `ID`=66458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천천히 오래 걷는 것만큼 혈액순환에 좋은 일이 없지요.', `MaleText_loc4`='没什么能比长长的慢速步行更能促进血液循环了。', `MaleText_loc5`='沒什麼比長時間慢慢散步更能促進你的血液循環。', `MaleText_loc7`='No hay nada mejor para la circulación que un paseo largo y tranquilo.' WHERE `ID`=66459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시나 물어볼까 봐 미리 대답하는데, 아직 멀었습니다.', `MaleText_loc4`='再你开口发问之前先回答你——没到，还远着呢。', `MaleText_loc5`='在你還沒開口問之前我先說了吧:不，我們還沒到。', `MaleText_loc7`='Antes de que preguntes: no, todavía no hemos llegado.' WHERE `ID`=66460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 저만큼 이 산책을 즐기고 계셨으면 좋겠군요.', `MaleText_loc4`='希望你跟我一样享受这个过程。', `MaleText_loc5`='我希望你跟我一樣享受。', `MaleText_loc7`='Espero que estés disfrutando tanto como yo.' WHERE `ID`=66461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다정한 $r $c|1과;와; 함께 산책하면 시간이 잘 가지요.', `MaleText_loc4`='有像你这么友好的$r$c同行，真是让人足下生风啊。', `MaleText_loc5`='當你身邊有個友善的$r$c時，散步的時光總是過得特別快。', `MaleText_loc7`='Los paseos siempre se hacen más llevaderos caminando al lado de $gun:una; $r $c.' WHERE `ID`=66462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 있을 만큼 있었던 것 같습니다. 함께 산책 가시겠습니까?', `MaleText_loc4`='我想我在这里待得够久了，你愿意随我一起走走吗？', `MaleText_loc5`='我想我在這裡停留得夠久了。你想跟我一起去走走嗎?', `MaleText_loc7`='Creo que ya he pasado suficiente tiempo aquí. ¿Te gustaría dar un paseo conmigo?' WHERE `ID`=66463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산책이요? 좋습니다!', `MaleText_loc4`='走走？好啊！', `MaleText_loc5`='散步?當然好!', `MaleText_loc7`='¿Un paseo? ¡Claro!', `FemaleText_loc1`='산책이요? 좋죠!', `FemaleText_loc4`='走走？好啊！', `FemaleText_loc5`='散步?當然好!', `FemaleText_loc7`='¿Un paseo? ¡Claro!' WHERE `ID`=66464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 가게에 잘 왔네, 나그네여!', `MaleText_loc4`='欢迎光临我的小店，旅行者！', `MaleText_loc5`='歡迎到我的商店來，旅行者!', `MaleText_loc7`='¡Te doy la bienvenida a mi tienda!' WHERE `ID`=66465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 진기한 물품을 찾는가? 그렇다면 제대로 찾아왔네!', `MaleText_loc4`='啊！你要找神奇的物品？那你可来对地方了！', `MaleText_loc5`='啊!所以你在尋找不可思議的物品嗎?那你就來對地方了!', `MaleText_loc7`='¡Ah! ¿Buscas objetos de leyenda? ¡Has venido al sitio adecuado!' WHERE `ID`=66466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음껏 봐도 좋지만, 마음껏 만지지는 말게!', `MaleText_loc4`='请随意浏览，但不要乱碰！', `MaleText_loc5`='請隨意看看，但不可隨意碰觸!', `MaleText_loc7`='¡Mira sin miedo, pero ten miedo de tocar!' WHERE `ID`=66467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법 지도를 한번 보겠나? 아, 아닐세. 품절이로군.', `MaleText_loc4`='也许你会对魔法地图感兴趣？噢算了，都卖光了。', `MaleText_loc5`='或許你對魔法地圖會有興趣?喔算了，我們都賣光了。', `MaleText_loc7`='¿Te interesaría comprar un mapa mágico? Bueno, es igual, los hemos vendido todos.' WHERE `ID`=66468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람이 자네를 이끌기를!', `MaleText_loc4`='愿风指引你的旅途！', `MaleText_loc5`='願風指引你的旅程!', `MaleText_loc7`='¡Que los vientos te guíen!' WHERE `ID`=66469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 비네, 친구!', `MaleText_loc4`='祝你好运，朋友！', `MaleText_loc5`='祝你好運，朋友!', `MaleText_loc7`='¡Te deseo buena suerte!' WHERE `ID`=66471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불로 속죄하라!', `MaleText_loc4`='净化火焰！', `MaleText_loc5`='以火淨化!', `MaleText_loc7`='¡Fuego purificador!' WHERE `ID`=66472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무기는 어디서 났나, 언니가 주던?', `MaleText_loc4`='那把武器是你姐姐给你的吗？', `MaleText_loc5`='你那把武器是跟誰拿的，你姊姊嗎?', `MaleText_loc7`='¿A quién le quitaste esa arma, a tu hermana?' WHERE `ID`=66473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 무기는 어디서 났나, 언니가 주던?', `MaleText_loc4`='那把武器是你姐姐给你的吗？', `MaleText_loc5`='你那把武器是跟誰拿的，你姊姊嗎?', `MaleText_loc7`='¿A quién le quitaste esa arma, a tu hermana?' WHERE `ID`=66474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 때문에 내가 너에게 물건을 팔 거라고 생각하나?', `MaleText_loc4`='你怎么知道我会愿意卖给你啊，外来者？', `MaleText_loc5`='你怎麼會認為我會把東西賣給你，外來者?', `MaleText_loc7`='¿Qué te hace pensar que vendo a los forasteros?' WHERE `ID`=66475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기다려라, 클락시가 내게 말한다. 네, 의회여. 저는 여제가 무슨 뜻이 있는지 들었습니다. 여제의 통치는 끝나야 합니다.', `MaleText_loc4`='等等。卡拉克西在跟我说话。是的，议会，我听到了女皇的意图。必须终结她的统治。', `MaleText_loc5`='等等。卡拉西跟我說話。是的，議會，我聽說過女皇的意圖。必須終結她的統治。', `MaleText_loc7`='Espera. Los Klaxxi me hablan. Sí, consejo, he oído las intenciones de la Emperatriz. Su reinado debe terminar.' WHERE `ID`=66476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의회여, 더는 이야기해주시지 않아도 됩니다. 제 두 눈으로 직접 고향을 봐야겠습니다. 셰크지르가 가져온 패망을 제가 직접 보겠습니다.', `MaleText_loc4`='不必多说了，议会。我要用自己的双眼看看过去的家园。我要凝视夏柯希尔酿下的恶果！', `MaleText_loc5`='不用再說了，議會。我會去親眼看看我的老家。我會見證杉齊爾造成的廢墟。', `MaleText_loc7`='No digas más, consejo. Veré mi antiguo hogar con mis propios ojos. Deseo contemplar la ruina que Shek''zeer ha provocado.' WHERE `ID`=66477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다, 클락시바여.', `MaleText_loc4`='马上，卡拉克西瓦。', `MaleText_loc5`='遵命，卡拉西瓦。', `MaleText_loc7`='Inmediatamente, Klaxxi''va.' WHERE `ID`=66478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석에 들어가기 전, 나는 커다란 모험을 했다.$B$B나는 호박석이 나 또는 수천 년에 걸쳐 행해졌던 세심한 실험조차도 절대 이뤄낼 수 없던 기적을 낳을 수 있다는 것을 깨달았다.$B$B내가 용장이 되기 전, 나는 스스로 치명적인 독 12개를 내 몸에 주사했지. 내 예상대로 생명을 불어넣어 주는 호박석의 특성이 중독되는 것을 보호해줬지. 그리고 나머지는 시간이 해결해줬다.$B$B그리고 이젠 내가 원하는 독이라면 어떠한 두려움 없이 다룰 수 있게 되었다.', `MaleText_loc4`='在我被封进琥珀之前，我孤注一掷地赌了一把。$B$B我意识到琥珀能创造出令我望尘莫及的奇迹，哪怕我在再实验室里精心研究一千年也赶不上。$B$B在我变成英杰前，我往自己体内注入了大量致命毒素。我想是琥珀维持生命的特性令我免于一死，剩下的都是时间的功劳。$B$B现在，我已经能无所畏惧地应对我想要的任何毒素。', `MaleText_loc5`='在我被封存進琥珀之前，我下了一個很大的賭注。$B$B我了解到琥珀可以實現我永遠都無法達成的奇蹟，即使花上一千年小心謹慎地實驗也不可能。$B$B在成為聖螳之前，我給自己注射了一打致命的毒藥。就跟我猜想的一樣，琥珀賦予生命的特質保護了我，而時間完成了剩下的工作。$B$B而現在，我可以毫不畏懼地操控任何我想操縱的毒藥。', `MaleText_loc7`='Antes de que me preservaran en ámbar, hice una jugada arriesgada.$b$bMe di cuenta de que el ámbar podía realizar un milagro del que yo nunca sería capaz, ni siquiera tras mil años de cuidadosos experimentos.$b$bMe inyecté una docena de venenos letales. Las propiedades vitales del ámbar me protegieron, como esperaba, y el tiempo se encargó del resto.$b$b¡Ahora tolero todos los venenos sin miedo!' WHERE `ID`=66479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 말랑말랑한 녀석은 제법 도움이 되겠군. 이리 오너라, 깨우는 자여.', `MaleText_loc4`='这个身体柔软的家伙应该也能效力。来吧，唤醒者。', `MaleText_loc5`='這個柔軟的傢伙應該很合用。來吧，喚醒者。', `MaleText_loc7`='Este tan suave servirá. Ven, heraldo.' WHERE `ID`=66480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 질문입니다. 우리가 정말 이상하기는 하지요... 장벽의 이쪽에서 살기로 한 판다렌은 흔치 않으니까 말입니다.$b$b간단히 말씀드리자면, 우리는 맥주를 만듭니다. 그냥 아무 맥주나 만드는 게 아니고... 거대한 키파리 나무 수액으로 숙성시킨 맥주를 만듭니다.', `MaleText_loc4`='这个问题问得好。我们是一群奇怪的家伙……很少有熊猫人会选择住在长城的这一侧。$b$b长话短说吧，我们是酿酒的。但可不是什么酒都酿……是用伟大的凯帕圣树的树脂酿酒。', `MaleText_loc5`='那是個好問題。我們是一群奇怪的傢伙...很少有熊貓人會選擇在長城的這一側生活。$b$b簡單說來，我們正在釀啤酒。但可不是隨便的啤酒...是用偉大奇帕利樹的樹汁釀出來的啤酒。', `MaleText_loc7`='Buena pregunta. Somos un poco extraños... Pocos pandaren deciden vivir a este lado de la muralla.$b$bEn resumen, fabricamos cerveza. Pero no una cerveza cualquiera... cerveza elaborada con la savia de los árboles kypari.' WHERE `ID`=66481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...역겹겠지요. 알고 있습니다. 하지만 그렇지만도 않습니다.$b$b이 키파리 나무가 만들어내는 호박석에는 놀라운 치유 특성이 있습니다. 사마귀들은 호박석의 이러한 특성만으로는 만족하지는 않지만 말입니다. 놈들은 호박석을 먹기도 하고, 건축물과 무기에 사용하기도 합니다... 심지어는 그들의 위대한 영웅을 매장할 때 이 호박석으로 염을 한다는 전설도 들었습니다.', `MaleText_loc4`='……有点恶心，我知道。可事实并非如此。$b$b这些大树生成的琥珀具有神奇的治愈能力。但欲求不满的螳螂妖还进一步消耗它，用来制造武器和建筑……我甚至听到过这样的传说，螳螂妖会将它们的大英雄封存在琥珀里，以使其永存不朽。', `MaleText_loc5`='...噁心。我知道。但事實並非如此。$b$b這些樹所生產的琥珀有著驚人的治療功效。螳螂人愛死了。他們吞食琥珀，拿琥珀來製造武器和蓋房子...我甚至聽說他們將最偉大的英雄保存在這種玩意裡。', `MaleText_loc7`='... repugnante, lo sé. ¡Pero no lo es!$b$bEl ámbar que producen estos árboles tiene unas propiedades curativas impresionantes. Los mántides dependen de él. Lo consumen, lo utilizan para sus armas, para su arquitectura... Hasta he oído leyendas de que embalsaman a sus héroes legendarios con él.' WHERE `ID`=66482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇습니다. 수액전문가의 전통은 무수한 세대 이전으로 거슬러 올라갑니다. 저는 단지 수액에 목마른 판다렌일 뿐이지요.$b$b하지만 가끔 제가 마지막이 아닐까 염려스럽기도 합니다.', `MaleText_loc4`='没错。树脂大师的起源可追溯到无数世代以前。我在广大渴求树脂的熊猫人中，只是一位无名小卒。$b$b但有时候，我担心自己也许是最后一代传人了。', `MaleText_loc5`='沒錯。樹汁大師的傳統傳遞了無數世代。我不過是渴望樹汁的熊貓人中的一條支脈。$b$b但有時候，我害怕我或許也是最後的傳人。', `MaleText_loc7`='Exacto. Las tradiciones de los maestros de savia se originaron hace innumerables generaciones. Yo no soy más que un eslabón de una larga cadena de pandaren sedientos de savia.$b$bSin embargo, a veces pienso que seré el último eslabón.' WHERE `ID`=66483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무가 죽어가고 있습니다. 키파리 보르는 이미 죽었습니다... 샤의 제물이 되었지요. 다시는 호박석을 만들어내지 못할 겁니다. 이젠 나무 같아 보이지도 않는군요.$b$b몇 그루 안 되는 키파리 나무에서 호박석이 만들어지고 있지만, 이것마저도 사마귀들이 과하게 채취해가거나, 샤에게 빼앗길 위험에 처해 있습니다. 어느 쪽이 되든, 수액을 얻을 수 없으면 수액전문가도 있을 수 없습니다. 그렇게 되면 저는 제 예전 직업으로 돌아가야만 할 겁니다.', `MaleText_loc4`='大树正在消亡。凯帕圣树·沃尔已经死了……沦为了邪煞的牺牲品。它再也不会生出琥珀。甚至连外形都不再像是一棵树。$b$b仅剩的几棵仍在生成琥珀的大树也面临着被螳螂妖过度开采的困境，或是处在邪煞的威胁之下。不论如何，一旦没有了树脂，也就不会再有树脂大师。到那时，我就只能重操旧业了。', `MaleText_loc5`='這些樹正在死去。奇帕利之樹已經完了...淪為煞的犧牲品。它再也無法生產琥珀。甚至看起來再也不像棵樹了。$b$b少數還能生產琥珀的樹若非遭到螳螂人的過度開採，就是即將屈服於煞。不管哪種，沒了樹汁，就不需要樹汁大師。那樣一來，我就得回去做我的老本行了。', `MaleText_loc7`='Los árboles se mueren. Kypari Vor ya ha muerto... víctima del sha. Nunca volverá a producir ámbar. Ya ni siquiera parece un árbol.$b$bLos pocos árboles productores de ámbar que quedan, o bien los mántides los están recolectando en exceso, o bien corren peligro de sucumbir al sha. En cualquier caso, si no hay savia, no hay maestros de savia. Y entonces tendría que volver a mi antiguo trabajo.' WHERE `ID`=66484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만두를 만들었습니다.$b$b<한숨을 내쉬는 부>', `MaleText_loc4`='滚汤团啊。$b$b<吴暮叹息着。>', `MaleText_loc5`='包餃子的。$b$b<老余嘆了口氣。>', `MaleText_loc7`='Moldeador de albóndigas.$b$b<Vu suspira.>' WHERE `ID`=66485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 무엇을 하고 있습니까?', `MaleText_loc4`='你在这里做什么？', `MaleText_loc5`='你在這裡做什麼?', `MaleText_loc7`='¿Qué haces aquí?', `FemaleText_loc1`='여기서 무엇을 하고 있나요?', `FemaleText_loc4`='你在这里做什么？', `FemaleText_loc5`='你在這裡做什麼?', `FemaleText_loc7`='¿Qué haces aquí?' WHERE `ID`=66486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수액으로 맥주를 만든단 말입니까? 그건 좀...', `MaleText_loc4`='用树脂酿的酒……那听起来……', `MaleText_loc5`='樹汁做的酒?聽起來真是...', `MaleText_loc7`='¿Cerveza de savia? Suena...', `FemaleText_loc1`='수액으로 맥주를 만든다고요? 그건 좀...', `FemaleText_loc4`='用树脂酿的酒……那听起来……', `FemaleText_loc5`='樹汁做的酒?聽起來真是...', `FemaleText_loc7`='¿Cerveza de savia? Suena...' WHERE `ID`=66487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 당신은 그 수액으로 맥주도 만드는 거군요.', `MaleText_loc4`='而你用它酿酒。', `MaleText_loc5`='然後你拿它來做酒。', `MaleText_loc7`='Y haces cerveza con eso.', `FemaleText_loc1`='그리고 당신은 수액으로 맥주도 만드는 거군요.', `FemaleText_loc4`='而你用它酿酒。', `FemaleText_loc5`='然後你拿它來做酒。', `FemaleText_loc7`='Y haces cerveza con eso.' WHERE `ID`=66488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 그렇습니까?', `MaleText_loc4`='为什么？', `MaleText_loc5`='為什麼?', `MaleText_loc7`='¿Por qué?', `FemaleText_loc1`='왜 그렇나요?', `FemaleText_loc4`='为什么？', `FemaleText_loc5`='為什麼?', `FemaleText_loc7`='¿Por qué?' WHERE `ID`=66489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에는 어떤 일을 하셨습니까?', `MaleText_loc4`='你的旧业是什么？', `MaleText_loc5`='你的老本行是什麼?', `MaleText_loc7`='¿Cuál era tu antiguo trabajo?', `FemaleText_loc1`='예전에는 어떤 일을 하셨나요?', `FemaleText_loc4`='你的旧业是什么？', `FemaleText_loc5`='你的老本行是什麼?', `FemaleText_loc7`='¿Cuál era tu antiguo trabajo?' WHERE `ID`=66490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:128419|h[속력 축적]|h|r 중입니다!', `MaleText_loc4`='%s正在|cFFFF0000|Hspell:128419|h[疾跑]|h|r！', `MaleText_loc5`='%s正在|cFFFF0000|Hspell:128419|h[聚速]|h|r!', `MaleText_loc7`='¡El %s está |cFFFF0000|Hspell:128419|h[Ganando velocidad]|h|r!' WHERE `ID`=66491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 봐주지 마라!', `MaleText_loc4`='继续！决不手软！', `MaleText_loc5`='別手軟!不要留情!', `MaleText_loc7`='No dudéis. ¡No mostréis piedad!' WHERE `ID`=66492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버텨! 그리고 나머지도 처치해!', `MaleText_loc4`='坚守阵地，全都杀光！', `MaleText_loc5`='堅持住，殺光剩下的活口!', `MaleText_loc7`='¡Resistid y matad al resto!' WHERE `ID`=66493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 실패한 놈들은 죽어 마땅한 놈들이었어. 너희는 쭉정이를 걸러낸 것뿐이다!', `MaleText_loc4`='呸！失败者活该受死，你们只不过是淘汰了弱者！', `MaleText_loc5`='哈!失敗者活該受死。你們不過是淘汰了弱者!', `MaleText_loc7`='¡Bah! Los que han caído merecían morir. ¡No habéis hecho más que purgar a los débiles!' WHERE `ID`=66496;
