UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 여기서 우리가 할 일은 다 했다. 어서 클락시 의회에 승리의 소식을 전하자꾸나. 클락시 의회는 우리가 돌아오기를 기다리고 있다.', `MaleText_loc4`='我们在这里的工作暂时结束了。让我们将胜利的消息传达给卡拉克西议会吧。他们在等我们回去。', `MaleText_loc5`='我們在這裡的工作暫時結束了。讓我們向卡拉西議會傳達勝利的消息。他們在等著我們回去。', `MaleText_loc7`='Nuestro trabajo aquí ha terminado, por ahora. Llevemos noticias de nuestra victoria al consejo de los Klaxxi. Esperan nuestra llegada.' WHERE `ID`=66541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 감탄했네, 젊은 제자여. 실로 대단한 힘을 지녔군.', `MaleText_loc4`='你令我刮目相看，年轻的弟子。在你体内蕴藏着巨大的力量。', `MaleText_loc5`='你讓我印象深刻，我年輕的學生。在你身上有強大的力量。', `MaleText_loc7`='Me asombras, joven estudiante. Cuentas con una gran fuerza.' WHERE `ID`=66542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이지? 왜 이렇게 빨리 공격하는 거야?', `MaleText_loc4`='发生什么事了？我们怎么这么快就要发动群袭？', `MaleText_loc5`='發生了什麼事?為什麼我們這麼快就離巢了?', `MaleText_loc7`='¿Qué está pasando? ¿Por qué formamos un enjambre tan pronto?' WHERE `ID`=66543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 안 돼, 너무 빨리 공격했어. 부하와 이야기해봐야겠군!', `MaleText_loc4`='不，不……这群袭发动得过早了。我必须跟副官谈谈！', `MaleText_loc5`='不...這樣離巢太早了。我得跟隨從說才行!', `MaleText_loc7`='No, no... Este enjambre es prematuro. ¡Tengo que hablar con el adjunto!' WHERE `ID`=66544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 왜 여기 있는 거지?', `MaleText_loc4`='我为什么……会在这儿……', `MaleText_loc5`='我為什麼...在這裡?!', `MaleText_loc7`='¿Por qué estoy... aquí?' WHERE `ID`=66545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기가 어디지? 우리가... 공격하고 있었어?!', `MaleText_loc4`='我们在哪儿？我们是在……群袭？！', `MaleText_loc5`='我們在哪?我們正要...離巢了?!', `MaleText_loc7`='¿Dónde estamos? Estamos formando... ¡¿un enjambre?!' WHERE `ID`=66546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌들은 단단히 준비했었군. 이번 공격은 어리석었다.', `MaleText_loc4`='熊猫人早就有所准备。这攻击真是愚蠢。', `MaleText_loc5`='熊貓人有所準備。這場攻擊是愚昧的。', `MaleText_loc7`='Los pandaren estaban preparados. Este ataque ha sido una locura.' WHERE `ID`=66547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 아니야. 아직 공격할 때가 아니야.', `MaleText_loc4`='这是不对的。还没到发起群袭的时候。', `MaleText_loc5`='這是錯的。還不是離巢的時候。', `MaleText_loc7`='Esto está mal. No es época de enjambre.' WHERE `ID`=66548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장벽으로는 사마귀의 위세를 막지 못한다!', `MaleText_loc4`='这道长城阻止不了螳螂妖的力量！', `MaleText_loc5`='這座破爛的長城無法阻止強大的螳螂人大軍!', `MaleText_loc7`='¡Esta muralla no puede contener la fuerza de los mántides!' WHERE `ID`=66549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 여제님의 의지를 실행할 것이다! 우리는 이 장벽을 무너뜨리고 그 뒤에 있는 대지를 집어삼킬 것이다!', `MaleText_loc4`='我在此执行女皇的意志！我们要粉碎这道长城，吞噬另一侧的土地！', `MaleText_loc5`='我要貫徹她的旨意!我們會摧毀長城，吞噬它後方的土地!', `MaleText_loc7`='¡Ejecuto su voluntad! ¡Derribaremos la muralla y devoraremos las tierras del otro lado!' WHERE `ID`=66550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 그 향이 더 있습니까?', `MaleText_loc4`='你不会恰巧有另一捆那种熏香吧？', `MaleText_loc5`='你不會剛好帶了另一捆線香吧?', `MaleText_loc7`='¿Por casualidad no te sobrará un fardo de incienso?', `FemaleText_loc1`='혹시 그 향이 더 있나요?', `FemaleText_loc4`='你不会恰巧有另一捆那种熏香吧？', `FemaleText_loc5`='你不會剛好帶了另一捆線香吧?', `FemaleText_loc7`='¿Por casualidad no te sobrará un fardo de incienso?' WHERE `ID`=66551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 함선은 제가 어떻게든 지키겠습니다.$B$B몸조심하십시오!', `MaleText_loc4`='我会尽量将船留在这里。$B$B多加小心！', `MaleText_loc5`='我會盡可能讓船停在這裡。$B$B一定要平安!', `MaleText_loc7`='Mantendré el barco aquí todo lo que pueda.$b$b¡Ten cuidado!' WHERE `ID`=66552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최선을 다해 함선과 선원들을 지키겠습니다.$B$B우리 걱정은 하지 마십시오!', `MaleText_loc4`='我们会尽力保护船只和船员。$B$B别为我们担心！', `MaleText_loc5`='我們會盡力保衛這艘船和船員。$B$B別擔心我們!', `MaleText_loc7`='Defenderemos el barco y a su tripulación todo lo que podamos.$b$b¡No te preocupes por nosotros!', `FemaleText_loc1`='최선을 다해 함선과 선원들을 지킬게요.$B$B우리 걱정은 하지 마세요!', `FemaleText_loc4`='我们会尽力保护船只和船员。$B$B别为我们担心！', `FemaleText_loc5`='我們會盡力保衛這艘船和船員。$B$B別擔心我們!', `FemaleText_loc7`='Defenderemos el barco y a su tripulación todo lo que podamos.$b$b¡No te preocupes por nosotros!' WHERE `ID`=66553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까?$B$B방금 프라우드무어 님의 탑이... 무너졌습니다!', `MaleText_loc4`='这里发生了什么事？！$B$B普罗德摩尔女士的塔就这么……消失了！', `MaleText_loc5`='發生了什麼事?!$B$B普勞德摩爾女士的塔...憑空消失了!', `MaleText_loc7`='¡¿Qué ha pasado aquí?!$b$bLa torre de Lady Valiente ha... ¡desaparecido!', `FemaleText_loc1`='무슨 일이죠?$B$B방금 프라우드무어 님의 탑이... 무너졌어요!', `FemaleText_loc4`='这里发生了什么事？！$B$B普罗德摩尔女士的塔就这么……消失了！', `FemaleText_loc5`='發生了什麼事?!$B$B普勞德摩爾女士的塔...憑空消失了!', `FemaleText_loc7`='¡¿Qué ha pasado aquí?!$b$bLa torre de Lady Valiente ha... ¡desaparecido!' WHERE `ID`=66554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 끔찍하군!$B$B대체 누가 이런 짓을?!', `MaleText_loc4`='真是灾难！$B$B会是什么人干的？！', `MaleText_loc5`='真是場災難!$B$B到底是怎麼造成的?', `MaleText_loc7`='¡Qué desastre!$b$b¿Qué ha podido causar esto?', `FemaleText_loc1`='정말 끔찍하네요!$B$B대체 누가 이런 짓을?!', `FemaleText_loc4`='真是灾难！$B$B会是什么人干的？！', `FemaleText_loc5`='真是場災難!$B$B到底是怎麼造成的?', `FemaleText_loc7`='¡Qué desastre!$b$b¿Qué ha podido causar esto?' WHERE `ID`=66555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남은 자가 있을지...', `MaleText_loc4`='不知还有没有人活下来……', `MaleText_loc5`='不曉得有沒有人生還...', `MaleText_loc7`='Me pregunto si habrá sobrevivido alguien...', `FemaleText_loc1`='살아남은 자가 있을지...', `FemaleText_loc4`='不知还有没有人活下来……', `FemaleText_loc5`='不曉得有沒有人生還...', `FemaleText_loc7`='Me pregunto si habrá sobrevivido alguien...' WHERE `ID`=66556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 짓입니까?!$B$B빛이여 우리 모두를 구하소서...', `MaleText_loc4`='是部落干的吗？！$B$B圣光啊，救救我们……', `MaleText_loc5`='是部落做的嗎?!$B$B願聖光拯救我們...', `MaleText_loc7`='¡¿La Horda ha hecho esto?!$b$bQue la Luz nos ampare...', `FemaleText_loc1`='호드의 짓인가요?!$B$B빛이여 우리 모두를 구하소서...', `FemaleText_loc4`='是部落干的吗？！$B$B圣光啊，救救我们……', `FemaleText_loc5`='是部落做的嗎?!$B$B願聖光拯救我們...', `FemaleText_loc7`='¡¿La Horda ha hecho esto?!$b$bQue la Luz nos ampare...' WHERE `ID`=66557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 빛이여... 테라모어가! 여기 무슨 일이 있었던 거지?!', `MaleText_loc4`='以圣光之名……塞拉摩！这里究竟发生了什么事？！', `MaleText_loc5`='聖光啊...塞拉摩!這裡發生了什麼事?!', `MaleText_loc7`='Por la Luz... ¡Theramore! ¡¿Qué ha pasado aquí?!' WHERE `ID`=66558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이브, 갑판 밑으로 내려가. 다른 이들은 모두 주위를 경계하고 공격에 대비하라.', `MaleText_loc4`='埃比，到甲板下面藏好。其他人加强戒备，准备迎战。', `MaleText_loc5`='艾畢，躲到甲板下去。其他全員，保持警戒準備迎接攻擊。', `MaleText_loc7`='Abe, baja a la bodega y escóndete. Todos los demás, monten una guardia y prepárense para un ataque.' WHERE `ID`=66559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누군가가 용감히 나서서 조사를 해준다면, 우린 이곳에서 그 동안 배를 지키고 있겠다.', `MaleText_loc4`='要是有人敢深入调查，我们会尽量将船停在这里。', `MaleText_loc5`='如果有人夠勇敢去調查，我們會盡力把船停泊在這裡夠久的時間。', `MaleText_loc7`='Si alguien tiene el valor de investigar, mantendremos el barco aquí todo el tiempo que podamos.' WHERE `ID`=66560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 선장님!', `MaleText_loc4`='是——是，长官！', `MaleText_loc5`='是的，長官!', `MaleText_loc7`='¡S-sí, señor!' WHERE `ID`=66561;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선장님! 함선의 선원들을 안전하게 지켜주십시오. 함선이 공격받는다면 우리가 지키겠습니다.', `FemaleText_loc4`='船长！请让船员安全待在船上。一旦遭到攻击，我们会保护舰船！', `FemaleText_loc5`='船長!請讓你的船員平安待在船上。我們會在船隻受到攻擊時負責防衛。', `FemaleText_loc7`='¡Capitán! Deja a tu tripulación segura en el barco. Nosotros lo defenderemos si nos atacan.' WHERE `ID`=66562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함선이다! 얼라이언스 함선이야!', `MaleText_loc4`='有艘船！联盟的船！', `MaleText_loc5`='那是艘船!聯盟的船!', `MaleText_loc7`='¡Eso es un barco! ¡Un barco de la ALIANZA!' WHERE `ID`=66563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상관없어! 배에 탄 놈들을 모조리 처치하겠다! 그런트들이여, 공격하라!', `MaleText_loc4`='我不管！甲板上的一个不留！动手吧，弟兄们！', `MaleText_loc5`='我不在乎!我要把他們通通殺光!來吧，蠻卒們!', `MaleText_loc7`='¡Me da igual! ¡VOY A MATAR A TODO LO QUE HAYA A BORDO! ¡Muévanse, muchachos!' WHERE `ID`=66564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고작 수송선일 뿐이다, 구르드. 전함이 아니야.', `FemaleText_loc4`='只是艘运输船，格鲁德。不是战舰。', `FemaleText_loc5`='只是艘運輸船，火星塞。不是艘戰艦。', `FemaleText_loc7`='Es solo un transporte, Grud. No es una nave de guerra.' WHERE `ID`=66565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문 뒤에 뭐가 있는지 늘 궁금했습니다.', `MaleText_loc4`='我一直想知道，在那些大门背后究竟有什么。', `MaleText_loc5`='我一直在想那些門後有些什麼。', `MaleText_loc7`='Siempre me he preguntado qué habría tras esas puertas.', `FemaleText_loc1`='문 뒤에 뭐가 있는지 늘 궁금했어요.', `FemaleText_loc4`='我一直想知道，在那些大门背后究竟有什么。', `FemaleText_loc5`='我一直在想那些門後有些什麼。', `FemaleText_loc7`='Siempre me he preguntado qué habría tras esas puertas.' WHERE `ID`=66566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 보십시오! 대단합니다!', `MaleText_loc4`='看看这地方！真令人吃惊！', `MaleText_loc5`='看看這地方!真是太美妙了!', `MaleText_loc7`='¡Contempla este lugar! ¡Es asombroso!', `FemaleText_loc1`='여기 좀 보세요! 대단해요!', `FemaleText_loc4`='看看这地方！真令人吃惊！', `FemaleText_loc5`='看看這地方!真是太美妙了!', `FemaleText_loc7`='¡Contempla este lugar! ¡Es asombroso!' WHERE `ID`=66567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='먼 나라에서 온 영웅이 호랑이 신 쉬엔을 설득해서 골짜기 문을 열었다고 합니다. 언젠가 그분을 뵙게 될 날이 올지도 모르지요.', `MaleText_loc4`='我听说，是来自远方的英雄说服了虎神雪怒，让它打开了山谷的大门。没准哪天我能见见他们。', `MaleText_loc5`='我聽說有些從遙遠土地來的英雄說服了虎神雪怒開放山谷。或許有一天我能見到他們。', `MaleText_loc7`='He oído que $gun héroe:una heroína; de una tierra lejana convenció a Xuen, el dios tigre, para que abriera el valle. A lo mejor $glo:la; conoceré algún día.', `FemaleText_loc1`='먼 나라에서 온 영웅이 호랑이 신 쉬엔을 설득해서 골짜기 문을 열었다고 해요. 언젠가 그분을 뵙게 될 날이 올지도 모르죠.', `FemaleText_loc4`='我听说，是来自远方的英雄说服了虎神雪怒，让它打开了山谷的大门。没准哪天我能见见他们。', `FemaleText_loc5`='我聽說有些從遙遠土地來的英雄說服了虎神雪怒開放山谷。或許有一天我能見到他們。', `FemaleText_loc7`='He oído que $gun héroe:una heroína; de una tierra lejana convenció a Xuen, el dios tigre, para que abriera el valle. A lo mejor $glo:la; conoceré algún día.' WHERE `ID`=66568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파의 말로는, 이곳이 모든 쿤라이 피난민의 안식처가 될 거라고 했습니다. 여기서야말로 평화를 누릴 수 있을지도 모르겠군요.', `MaleText_loc4`='影踪派告诉我们，这里是为昆莱难民挡风遮雨的避风港。也许我们终于能在这里寻获宁静。', `MaleText_loc5`='影潘告訴我們這裡會是屬於所有崑萊難民的樂園。也許在這裡，我們終於能找到平靜。', `MaleText_loc7`='El Shadopan nos dijo que este lugar acogería a todos los refugiados de Kun-Lai. A lo mejor aquí encontraremos al fin la paz.', `FemaleText_loc1`='음영파의 말로는, 이곳이 모든 쿤라이 피난민의 안식처가 될 거라고 했어요. 여기서야말로 평화를 누릴 수 있을지도 모르겠네요.', `FemaleText_loc4`='影踪派告诉我们，这里是为昆莱难民挡风遮雨的避风港。也许我们终于能在这里寻获宁静。', `FemaleText_loc5`='影潘告訴我們這裡會是屬於所有崑萊難民的樂園。也許在這裡，我們終於能找到平靜。', `FemaleText_loc7`='El Shadopan nos dijo que este lugar acogería a todos los refugiados de Kun-Lai. A lo mejor aquí encontraremos al fin la paz.' WHERE `ID`=66569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문 뒤의 세상에 대해서는 온갖 이야기를 다 들었지만, 이런 곳일 줄은 상상도 못했습니다.', `MaleText_loc4`='关于在大门背后有些什么，我听到过形形色色的传说。真没想到竟然是这样的。', `MaleText_loc5`='我聽說過各種關於門後的故事。我從沒想到會是這樣的。', `MaleText_loc7`='He oído todo tipo de historias sobre lo que se oculta tras las puertas. Nunca imaginé que sería algo así.', `FemaleText_loc1`='문 뒤의 세상에 대해서는 온갖 이야기를 다 들었지만, 이런 곳일 줄은 상상도 못했어요.', `FemaleText_loc4`='关于在大门背后有些什么，我听到过形形色色的传说。真没想到竟然是这样的。', `FemaleText_loc5`='我聽說過各種關於門後的故事。我從沒想到會是這樣的。', `FemaleText_loc7`='He oído todo tipo de historias sobre lo que se oculta tras las puertas. Nunca imaginé que sería algo así.' WHERE `ID`=66570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기에 정착할 수 있을지도 모르겠군요.', `MaleText_loc4`='也许我们能在山谷里找到新家。', `MaleText_loc5`='也許我們可以在這山谷建立新的家園。', `MaleText_loc7`='A lo mejor encontraremos un nuevo hogar en este valle.', `FemaleText_loc1`='영원꽃 골짜기에 정착할 수 있을지도 모르겠네요.', `FemaleText_loc4`='也许我们能在山谷里找到新家。', `FemaleText_loc5`='也許我們可以在這山谷建立新的家園。', `FemaleText_loc7`='A lo mejor encontraremos un nuevo hogar en este valle.' WHERE `ID`=66571;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 온다! 할터스! 준비해!', `FemaleText_loc4`='他们来了，哈特斯！做好准备！', `FemaleText_loc5`='他們來了，赫特斯!做好準備!', `FemaleText_loc7`='¡Aquí vienen, Halters! ¡Prepárate!' WHERE `ID`=66572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 정말 판다리아의 고대 황제들이 살았단 말입니까? 정말 아름답군요.', `MaleText_loc4`='这里真是潘达利亚古代皇帝的家园么？真是太美了。', `MaleText_loc5`='這真的是潘達利亞古代皇帝的家嗎?真美。', `MaleText_loc7`='¿Es verdad que los antiguos emperadores de Pandaria vivían aquí? Es hermoso.', `FemaleText_loc1`='이곳에 정말 판다리아의 고대 황제들이 살았단 말이에요? 정말 아름답네요.', `FemaleText_loc4`='这里真是潘达利亚古代皇帝的家园么？真是太美了。', `FemaleText_loc5`='這真的是潘達利亞古代皇帝的家嗎?真美。', `FemaleText_loc7`='¿Es verdad que los antiguos emperadores de Pandaria vivían aquí? Es hermoso.' WHERE `ID`=66573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문이 열리는 광경을 내 눈으로 보다니... 손주에게 들려줄 이야기로군요.', `MaleText_loc4`='亲眼见证大门的开启……这一幕必定会在我的子孙万代间流传不绝。', `MaleText_loc5`='親眼見到門的開啟...這會是我可以跟兒孫們講述一輩子的故事。', `MaleText_loc7`='Presenciar la apertura de las puertas... Es una experiencia que transmitiré a los hijos de mis hijos.', `FemaleText_loc1`='문이 열리는 광경을 내 눈으로 보다니... 손주에게 들려줄 이야기로군요.', `FemaleText_loc4`='亲眼见证大门的开启……这一幕必定会在我的子孙万代间流传不绝。', `FemaleText_loc5`='親眼見到門的開啟...這會是我可以跟兒孫們講述一輩子的故事。', `FemaleText_loc7`='Presenciar la apertura de las puertas... Es una experiencia que transmitiré a los hijos de mis hijos.' WHERE `ID`=66574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어를 위하여!', `MaleText_loc4`='为了塞拉摩！', `MaleText_loc5`='為了塞拉摩!', `MaleText_loc7`='¡POR THERAMORE!' WHERE `ID`=66575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생물의 등에서 뭔가가 희미하게 빛납니다.', `MaleText_loc4`='在那家伙的背上仿佛有什么东西闪了一下。', `MaleText_loc5`='在那生物的背上有某種東西放出一抹微光。', `MaleText_loc7`='Hay algo en la espalda de la criatura que refleja la luz.' WHERE `ID`=66576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물건을 집습니다.', `MaleText_loc4`='拿上那件物品。', `MaleText_loc5`='拿取物件。', `MaleText_loc7`='Coge el objeto.', `FemaleText_loc1`='물건을 집습니다.', `FemaleText_loc4`='拿上那件物品。', `FemaleText_loc5`='拿取物件。', `FemaleText_loc7`='Coge el objeto.' WHERE `ID`=66577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고치기에는 피해가 너무 심하구나.', `MaleText_loc4`='有许多伤害亟待补救。', `MaleText_loc5`='有很多損害得去修復。', `MaleText_loc7`='Hay muchos daños por reparar.' WHERE `ID`=66578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르이크는 우리를 가장 먼저 배신했을 뿐이다. 그 누구도 믿을 수 없다.', `MaleText_loc4`='科尔里克只是第一个背叛我们的人。谁也不能相信。', `MaleText_loc5`='柯利克只是第一個背叛我們的。沒有人可以信任。', `MaleText_loc7`='Kor''ik solo ha sido el primero en traicionarnos. No podemos confiar en nadie.' WHERE `ID`=66579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 전쟁이 다가왔다.', `MaleText_loc4`='战争已经来临，唤醒者。', `MaleText_loc5`='戰爭來了，喚醒者。', `MaleText_loc7`='La guerra ha llegado, heraldo.' WHERE `ID`=66580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생물의 껍질이 빛을 발하고 있습니다.', `MaleText_loc4`='那家伙的甲壳在闪光。', `MaleText_loc5`='這生物的殼閃爍著光芒。', `MaleText_loc7`='El caparazón de la criatura reluce.' WHERE `ID`=66581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잘루가 오늘은 뭘 해 드릴까나?', `MaleText_loc4`='贾鲁今天能为你做些什么？', `MaleText_loc5`='賈廬能為你提供什麼服務?', `MaleText_loc7`='¿Qué puede Jaluu hacer por ti?' WHERE `ID`=66582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늘 불가능한 것을 이루려고 노력하게.', `MaleText_loc4`='永远努力成就不可能的事。', `MaleText_loc5`='總是渴望完成不可能的任務。', `MaleText_loc7`='Intenta siempre conseguir lo imposible.' WHERE `ID`=66583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하루하루 명예와 용기를 추구하기를, $r.', `MaleText_loc4`='愿你在今后的日子里荣耀相伴，勇敢无畏，$r。', `MaleText_loc5`='或許你總是尋求榮譽和勇氣，$r。', `MaleText_loc7`='Busca honor y coraje cada día de tu vida, $r.' WHERE `ID`=66584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 믿음직한 동료에게만 황금 연꽃의 비밀을 털어놓는다네.', `MaleText_loc4`='我们只会对最可信赖的盟友透露金莲至深的秘密。', `MaleText_loc5`='我們只向最受信任的盟友揭露金蓮會重大的秘密。', `MaleText_loc7`='Solo los aliados de mayor confianza descubren los secretos más profundos del Loto Dorado.' WHERE `ID`=66585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 마치... 쇳덩어리 같군...', `MaleText_loc4`='你简直是……钢筋铁骨……', `MaleText_loc5`='你簡直...堅不可摧...', `MaleText_loc7`='Son como... una barra de hierro…' WHERE `ID`=66586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기에 잘 왔네, 친구. 편히 머물게.', `MaleText_loc4`='欢迎到山谷来，朋友。一切随意，别惹麻烦。', `MaleText_loc5`='歡迎來到山谷，朋友。留下來安心休息吧。', `MaleText_loc7`='Te doy la bienvenida al valle. Quédate y vive en paz.' WHERE `ID`=66587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 도와!', `MaleText_loc4`='快来帮忙！', `MaleText_loc5`='救我!', `MaleText_loc7`='¡AYUDADME!' WHERE `ID`=66588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운이 함께하기를, $r. 이곳에서 판다리아의 모든 세력의 대표를 만날 수 있다네. 경험을 좀 더 쌓은 다음에 우리를 찾아오게. 흥미진진한 모험과 엄청난 보상이 기다린다네.', `FemaleText_loc4`='祝你好运，$r。你在这里能找到潘达利亚所有阵营的代表。当你经验再丰富些时，就回来与我们交谈吧。伟大的冒险和丰厚的奖励在等着你。', `FemaleText_loc5`='祝好運，$r。你能在這裡找到潘達利亞各個陣營的代表。等你獲得更多經驗，回來找我們談談。偉大的冒險和優渥的獎賞等待著你。', `FemaleText_loc7`='Buena fortuna, $r. Aquí encontrarás representantes de todas las facciones de Pandaria. Cuando tengas algo más de experiencia a tus espaldas, ven a hablar con nosotros. Te esperan grandes aventuras y grandes recompensas.' WHERE `ID`=66589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운의 별이 자네 머리 위에서 빛나길, $c. 이곳에서 판다리아의 모든 세력의 대표를 만날 수 있다네. 대표들과 이야기를 나눠서, 자네가 바로 그들이 찾는 모험가인지 확인해 보게.', `FemaleText_loc4`='愿幸运之星照耀着你，$c。你在这里能找到潘达利亚所有阵营的代表。与他们交谈，看看你是不是他们要找的勇敢冒险者。', `FemaleText_loc5`='祝你吉星高照，$c。你能在這裡找到潘達利亞各個陣營的代表。和他們談談，看你是不是他們所需要的勇敢冒險者。', `FemaleText_loc7`='Que una estrella de la suerte se cruce en tu camino, $c. Aquí encontrarás representantes de todas las facciones de Pandaria. Habla con ellos para descubrir si eres $guno de los grandes aventureros:una de las grandes aventureras; que buscan.' WHERE `ID`=66590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 어떤 곳입니까?', `MaleText_loc4`='这里是什么地方？', `MaleText_loc5`='這是什麼地方?', `MaleText_loc7`='¿Qué es este lugar?', `FemaleText_loc1`='이곳은 어떤 곳인가요?', `FemaleText_loc4`='这里是什么地方？', `FemaleText_loc5`='這是什麼地方?', `FemaleText_loc7`='¿Qué es este lugar?' WHERE `ID`=66591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경보를 울려라! 항구에 얼라이언스가 나타났다!', `MaleText_loc4`='警报！联盟从港口靠近！', `MaleText_loc5`='警報!聯盟接近港口了!', `MaleText_loc7`='¡ALERTA! ¡La Alianza se acerca por el puerto!' WHERE `ID`=66592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직여!', `MaleText_loc4`='动起来，狗崽子们！', `MaleText_loc5`='走啊，狗奴才!', `MaleText_loc7`='¡Rápido, perros!', `FemaleText_loc1`='어서 움직여!', `FemaleText_loc4`='动起来，狗崽子们！', `FemaleText_loc5`='走啊，狗奴才!', `FemaleText_loc7`='¡Rápido, perros!' WHERE `ID`=66593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리빨리 해!', `MaleText_loc4`='赶紧干活，苦工！', `MaleText_loc5`='快點，苦工們!', `MaleText_loc7`='¡Daos prisa, peones!', `FemaleText_loc1`='빨리빨리 해!', `FemaleText_loc4`='赶紧干活，苦工！', `FemaleText_loc5`='快點，苦工們!', `FemaleText_loc7`='¡Daos prisa, peones!' WHERE `ID`=66594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발길질 당하고 싶지 않으면 서둘러!', `MaleText_loc4`='麻利些，狗崽子们，不然就解雇你们！', `MaleText_loc5`='快點，狗奴才，否則我就開始要用踹的了!', `MaleText_loc7`='¡Dense prisa, perros, o conocerán LA BOTA!', `FemaleText_loc1`='발길질 당하고 싶지 않으면 서둘러!', `FemaleText_loc4`='麻利些，狗崽子们，不然就解雇你们！', `FemaleText_loc5`='快點，狗奴才，否則我就開始要用踹的了!', `FemaleText_loc7`='¡Dense prisa, perros, o conocerán LA BOTA!' WHERE `ID`=66595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직여! 이 게으른 벌레들 같으니!', `MaleText_loc4`='快点！快点！你们这群懒虫！', `MaleText_loc5`='快!快，你們這些懶蟲!', `MaleText_loc7`='¡Venga! ¡VENGA, gusanos perezosos!', `FemaleText_loc1`='움직여! 이 게으른 벌레들 같으니!', `FemaleText_loc4`='快点！快点！你们这群懒虫！', `FemaleText_loc5`='快!快，你們這些懶蟲!', `FemaleText_loc7`='¡Venga! ¡VENGA, gusanos perezosos!' WHERE `ID`=66596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 나그네여. 원하신다면 이곳에 머무르세요. 위층에는 은행과 각 도시로 통하는 차원문이 있어요. 온갖 상인들이 건물 안에 가게를 차리고 있답니다. 마음껏 둘러 보세요.', `FemaleText_loc4`='欢迎你，旅行者。如果你愿意，就把这里当成自己的家吧。楼上有银行和城市传送门。出售各种商品的小贩都已经在这座建筑附近摆摊开店了。请随意选购。', `FemaleText_loc5`='歡迎，旅人。儘管把這裡當自己家。在樓上有銀行和城市傳送門。各種交易商人已經在建築物周圍設好店鋪。隨意看看吧。', `FemaleText_loc7`='Te doy la bienvenida, $gviajero:viajera;. Asiéntate aquí, si lo deseas. Arriba encontrarás las cámaras del banco y los portales de ciudad. Los vendedores de todas las profesiones ya se están estableciendo por todo el edificio. Explora todo lo que quieras.' WHERE `ID`=66597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 도시에는 뭐가 있습니까?', `MaleText_loc4`='我能在镇上找到什么？', `MaleText_loc5`='我能在城市這裡找到什麼?', `MaleText_loc7`='¿Qué puedo encontrar en esta ciudad?', `FemaleText_loc1`='이 도시에는 뭐가 있나요?', `FemaleText_loc4`='我能在镇上找到什么？', `FemaleText_loc5`='我能在城市這裡找到什麼?', `FemaleText_loc7`='¿Qué puedo encontrar en esta ciudad?' WHERE `ID`=66598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운이 필요한가, $r? 잘 살기 위해서는 모두들 행운이 조금 필요한 법이지.$B$B걱정할 것 없네. 내가 자네 쪽으로 운이 기울도록 해 줄 수 있네!', `MaleText_loc4`='需要幸运女神的眷顾么，$r？人人都要借助好运来让自己心想事成！$B$B别急，我能帮你扭转颓势！', `MaleText_loc5`='想要改運嗎，$r?每個人都需要一點運氣來讓事情一帆風順。$B$B別擔心，我能幫忙你扭轉乾坤!', `MaleText_loc7`='¿Necesitas que la fortuna te sonría, $r? ¡A todo el mundo le viene bien un poco de suerte!$b$bNo te preocupes, yo puedo ayudarte a equilibrar la balanza a tu favor.' WHERE `ID`=66599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운이 함께하기를, $r. 이곳에서 판다리아의 모든 세력의 대표를 만날 수 있다네. 경험을 좀 더 쌓은 다음에 우리를 찾아오게. 흥미진진한 모험과 엄청난 보상이 기다린다네.', `MaleText_loc4`='欢迎你，$r。你在这里能找到潘达利亚所有阵营的代表。当你的经验再丰富一些时，就回来与我们交谈吧。前方有伟大的冒险和丰厚的奖励在等着你。', `MaleText_loc5`='歡迎，$r。你能在這裡找到潘達利亞各個陣營的代表。等你獲得更多經驗，回來找我們談談。偉大的冒險和優渥的獎賞等待著你。', `MaleText_loc7`='Te doy la bienvenida, $r. Aquí encontrarás representantes de todas las facciones de Pandaria. Cuando tengas algo más de experiencia a tus espaldas, ven a hablar con nosotros. Te esperan grandes aventuras y grandes recompensas.' WHERE `ID`=66600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑네, $r. 이곳에서 판다리아의 모든 세력의 대표를 만날 수 있다네. 대표들과 이야기를 나눠서, 자네가 바로 그들이 찾는 모험가인지 확인해 보게.', `MaleText_loc4`='欢迎你，$r。你在这里能找到潘达利亚所有阵营的代表。与他们交谈，看看你是不是他们所要寻找的勇敢冒险者。', `MaleText_loc5`='歡迎，$r。你能在這裡找到潘達利亞各個陣營的代表。和他們談談，看你是不是他們所需要的勇敢冒險者。', `MaleText_loc7`='Te doy la bienvenida, $r. Aquí encontrarás representantes de todas las facciones de Pandaria. Habla con ellos para descubrir si eres $guno de los grandes aventureros:una de las grandes aventureras; que buscan.' WHERE `ID`=66601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호! 호호호.$B$B요호호, 동점이군.$B$B나는 방금 판다리아라는 땅에서 막 돌아온 참이오. 완만한 언덕과 거친 산, 그리고 맛이 이상한 럼주의 땅이지. 비취 숲이란 곳에 불시착을 했는데, 내 화물 때문에 그곳이 황폐해졌소. 지금으로선 네 바람의 계곡에 데려다 줄 수는 있소.$B$B날 믿소, $c?', `MaleText_loc4`='喔，嚯！喔嚯嚯。$B$B呦嚯嚯，扯平。$B$B我刚从潘达利亚回来，那里丘陵起伏，山势崎岖，还有味道最为诡异的朗姆酒。我的船在翡翠林中失事了，我的货物把当地变得无法居住，可与此同时，我能带你风驰电掣般地前往四风谷。$B$B你相信我吗，$c？', `MaleText_loc5`='喔齁!喔齁齁。$B$B甚至，呦齁齁。$B$B我剛從潘達利亞回來，見過那裡的丘陵和山脈，和我所嚐過最怪的蘭姆酒。我的船墜毀在翠玉林，我的貨物掉到鳥不生蛋的地方。但在此同時，我可以先帶你過去四風峽。馬上就到。$B$B你相信我嗎，$c?', `MaleText_loc7`='¡Oh, jo! Oh, jo, jo.$B$BY más, yo, jo, jo.$b$bAcabo de volver de la tierra de Pandaria, con sus verdes colinas y sus afiladas montañas, por no hablar del ron más extraño que he probado jamás. Estrellé mi barco en el Bosque de Jade y mi cargamento ha provocado que la zona sea inhabitable, pero hasta entonces puedo llevarte al Valle de los Cuatro Vientos en un pispás.$b$b¿Confías en mí, $c?' WHERE `ID`=66602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아, 내가 하는 일을 하고 싶진 않을 걸, 친구.$B$B썩 꺼지시오!', `MaleText_loc4`='呀，你对我这儿的东西都没兴趣，$g小男孩:小女孩;。$B$B快走开！', `MaleText_loc5`='唉啊，你不會想碰那些我在處理的東西，$g小子:小妞;。$B$B快滾吧你!', `MaleText_loc7`='Aaarrrr, no quieres tener nada que ver con lo que me traigo entre manos, $ghijo:señorita;.$B$B¡Largo de aquí!' WHERE `ID`=66603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 계속 해라.', `MaleText_loc4`='很好。再接再厉。', `MaleText_loc5`='幹得好。保持下去。', `MaleText_loc7`='Buen trabajo. Sigue así.' WHERE `ID`=66604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다. 이제 거의 끝났어!', `MaleText_loc4`='干得好。到此为止！', `MaleText_loc5`='非常好。用不了多久了!', `MaleText_loc7`='Bien hecho. ¡Ya queda poco!' WHERE `ID`=66605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 여기부터 끝내면, 모두 럼주를 마시게 해주마!', `MaleText_loc4`='把这里的活儿干完，人人都有朗姆酒喝！', `MaleText_loc5`='先解決這裡，後面有一大堆蘭姆酒等著你們所有人!', `MaleText_loc7`='Primero termina aquí, ¡y entonces tendrás ron de sobra!' WHERE `ID`=66606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이 넘치는군. 훌륭해!', `MaleText_loc4`='如此能量。真了不起！', `MaleText_loc5`='真有能量。很好!', `MaleText_loc7`='Cuánta energía. ¡Excelente!' WHERE `ID`=66607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 함선에서 온 거냐? 어리석군. 테라모어는 이제 호드 땅이다!', `MaleText_loc4`='你是从那船上下来的？真不明智。塞拉摩现在是部落的地盘了！', `MaleText_loc5`='你是從船上來的?真傻。塞拉摩是部落的土地了!', `MaleText_loc7`='¿Venís de ese barco? Mala idea. ¡Ahora Theramore es territorio de la HORDA!' WHERE `ID`=66608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 제독님께서 우리가 비취 숲에서 약탈한 물건을 당신에게 팔라며 저를 이곳으로 보내셨습니다. 약탈품 중 당신이 여행할 때 쓸모 있는 게 있을 거로 생각하셨나 봅니다.$B$B당신이 원하신다면 주 대륙으로 데려다 줄 수도 있습니다.', `MaleText_loc4`='呀，将军派我到这儿来，把我们从翡翠林抢来的战利品卖给你。他认为这会对你的旅途有所帮助。$B$B如果你愿意的话，我还能带你返回大陆。', `MaleText_loc5`='呀啊，上將派我到這裡賣一些我們從翠玉林搜刮來的戰利品給你。我們覺得應該對你有幫助。$B$B若你想回主大陸，我也能幫你。', `MaleText_loc7`='Aaarrrr, el almirante me ha enviado a venderte parte del botín que saqueamos del Bosque de Jade. Cree que podría ayudarte durante el viaje.$b$bSi quieres, también puedo llevarte al continente.' WHERE `ID`=66609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡', `MaleText_loc4`='四风谷', `MaleText_loc5`='四風峽', `MaleText_loc7`='Valle de los Cuatro Vientos', `FemaleText_loc1`='네 바람의 계곡', `FemaleText_loc4`='四风谷', `FemaleText_loc5`='四風峽', `FemaleText_loc7`='Valle de los Cuatro Vientos' WHERE `ID`=66613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 파십니까?', `MaleText_loc4`='你有哪些商品要出售？', `MaleText_loc5`='你是賣什麼的?', `MaleText_loc7`='¿Qué vendes?', `FemaleText_loc1`='어떤 물건을 파시나요?', `FemaleText_loc4`='你有哪些商品要出售？', `FemaleText_loc5`='你是賣什麼的?', `FemaleText_loc7`='¿Qué vendes?' WHERE `ID`=66614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 최후가 눈앞에 있다!', `MaleText_loc4`='你死期将至！', `MaleText_loc5`='你的末日將近!', `MaleText_loc7`='Tu hora se acerca.' WHERE `ID`=66615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수여, 죽을 때 너에게 선택의 기회가 있었다는 걸 기억해라.', `MaleText_loc4`='在临死之前，畜生，记得我曾给过你机会。', `MaleText_loc5`='當你要死的時候，別忘了，我可是有給你選擇的機會。', `MaleText_loc7`='Cuando agonices, bestia, recuerda que te di a elegir.' WHERE `ID`=66616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방방곡곡에서 모여든 상인들이 이곳에 자리 잡았지요. 뭘 찾으십니까?', `MaleText_loc4`='来自各地的商贩都进城了。你要找什么？', `MaleText_loc5`='來自各地的商人都進到了城市裡。你在找什麼?', `MaleText_loc7`='A la ciudad han llegado vendedores de todas partes. ¿Qué andas buscando?', `FemaleText_loc1`='방방곡곡에서 모여든 상인들이 이곳에 자리 잡았지요. 뭘 찾으십니까?', `FemaleText_loc4`='来自各地的商贩都进城了。你要找什么？', `FemaleText_loc5`='來自各地的商人都進到了城市裡。你在找什麼?', `FemaleText_loc7`='A la ciudad han llegado vendedores de todas partes. ¿Qué andas buscando?' WHERE `ID`=66617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 것이 보이지 않습니까?$B$B뭘 찾으시나요? 제가 도와드리겠습니다.', `MaleText_loc4`='你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。', `MaleText_loc5`='沒在城市裡找到你需要的東西?$B$B你在找什麼?或許我能幫你。', `MaleText_loc7`='¿No has encontrado lo que buscas en la ciudad?$b$b¿Qué necesitas? A lo mejor puedo ayudarte.', `FemaleText_loc1`='필요한 것이 보이지 않습니까?$B$B뭘 찾으시나요? 제가 도와드리겠습니다.', `FemaleText_loc4`='你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。', `FemaleText_loc5`='沒在城市裡找到你需要的東西?$B$B你在找什麼?或許我能幫你。', `FemaleText_loc7`='¿No has encontrado lo que buscas en la ciudad?$b$b¿Qué necesitas? A lo mejor puedo ayudarte.' WHERE `ID`=66618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 직업 상급자를 찾으신다고요? 불행히도 영원꽃 골짜기까지 온 직업 상급자는 한 명도 없습니다.$B$B대도시에서 찾아 보시기 바랍니다.', `MaleText_loc4`='噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。', `MaleText_loc5`='喔，在找你的職業訓練師?很可惜，沒有人能夠來到恆春谷這裡。$B$B你可以回到你的主城去找尋他們。', `MaleText_loc7`='Ah, ¿buscas a tu instructor de clase? Por desgracia, no ha venido ninguno al Valle de la Flor Eterna.$b$bTendrás que volver a tu capital para ver a uno.', `FemaleText_loc1`='아, 직업 상급자를 찾으신다고요? 불행히도 영원꽃 골짜기까지 온 직업 상급자는 한 명도 없습니다.$B$B대도시에서 찾아 보시기 바랍니다.', `FemaleText_loc4`='噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。', `FemaleText_loc5`='喔，在找你的職業訓練師?很可惜，沒有人能夠來到恆春谷這裡。$B$B你可以回到你的主城去找尋他們。', `FemaleText_loc7`='Ah, ¿buscas a tu instructor de clase? Por desgracia, no ha venido ninguno al Valle de la Flor Eterna.$b$bTendrás que volver a tu capital para ver a uno.' WHERE `ID`=66619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 전문가를 찾으십니까?$B$B달인들은 판다리아 전역에 흩어져 있습니다. 누굴 찾는지 이야기해 주세요.$B$B찾는 사람이 판다리아에 없으면, 대도시에서 찾아봐도 됩니다. 대도시의 전문가에게서도 기술을 배울 수 있으니까요.', `MaleText_loc4`='在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。', `MaleText_loc5`='在找專業技能訓練師?$B$B禪師級的訓練師散佈在潘達利亞各處。告訴我你要找誰。$B$B如果你沒法在潘達利亞找到你所想要找的人，你還是可以回到主城找那裡的專業訓練師。他們應該也能增進你的技藝。', `MaleText_loc7`='¿Buscas a un instructor de profesión?$b$bLos instructores maestros zen se encuentran por toda Pandaria. Dime a quién buscas.$b$bSi no encuentras a la persona que buscas aquí, en Pandaria, siempre puedes hablar con los maestros de tu capital. También deberían poder mejorar tu habilidad en la profesión que has elegido.', `FemaleText_loc1`='기술 전문가를 찾으십니까?$B$B달인들은 판다리아 전역에 흩어져 있습니다. 누굴 찾는지 이야기해 주세요.$B$B찾는 사람이 판다리아에 없으면, 대도시에서 찾아봐도 됩니다. 대도시의 전문가에게서도 기술을 배울 수 있으니까요.', `FemaleText_loc4`='在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。', `FemaleText_loc5`='在找專業技能訓練師?$B$B禪師級的訓練師散佈在潘達利亞各處。告訴我你要找誰。$B$B如果你沒法在潘達利亞找到你所想要找的人，你還是可以回到主城找那裡的專業訓練師。他們應該也能增進你的技藝。', `FemaleText_loc7`='¿Buscas a un instructor de profesión?$b$bLos instructores maestros zen se encuentran por toda Pandaria. Dime a quién buscas.$b$bSi no encuentras a la persona que buscas aquí, en Pandaria, siempre puedes hablar con los maestros de tu capital. También deberían poder mejorar tu habilidad en la profesión que has elegido.' WHERE `ID`=66620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡, 비단촌에 있는 비단장인 차이를 찾으시는군요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。', `MaleText_loc5`='到四風峽的絲綢場找絲綢大師老蔡。我會替你在地圖上標記出位置。', `MaleText_loc7`='Buscas al maestro de seda Tsai, en los Campos de Seda, en el Valle de los Cuatro Vientos. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='네 바람의 계곡, 비단촌에 있는 비단장인 차이를 찾으시는군요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。', `FemaleText_loc5`='到四風峽的絲綢場找絲綢大師老蔡。我會替你在地圖上標記出位置。', `FemaleText_loc7`='Buscas al maestro de seda Tsai, en los Campos de Seda, en el Valle de los Cuatro Vientos. Te marcaré su ubicación en el mapa.' WHERE `ID`=66621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑 밀림의 강태공 부두에 있는 내트 페이글을 찾아가면 낚시 기술을 배울 수 있습니다. 위치를 표시해 드리지요.', `MaleText_loc4`='你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。', `MaleText_loc5`='你可以前往喀撒朗蠻荒的釣手泊船處來拜訪納特·帕格並提升釣魚技能。讓我替你在地圖上標記出來。', `MaleText_loc7`='Para mejorar tu habilidad en pesca, visita a Nat Pagle en el Muelle de los Pescadores, en la Espesura Krasarang. Te señalaré dónde está.', `FemaleText_loc1`='크라사랑 밀림의 강태공 부두에 있는 내트 페이글을 찾아가면 낚시 기술을 배울 수 있습니다. 위치를 표시해 드리지요.', `FemaleText_loc4`='你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。', `FemaleText_loc5`='你可以前往喀撒朗蠻荒的釣手泊船處來拜訪納特·帕格並提升釣魚技能。讓我替你在地圖上標記出來。', `FemaleText_loc7`='Para mejorar tu habilidad en pesca, visita a Nat Pagle en el Muelle de los Pescadores, en la Espesura Krasarang. Te señalaré dónde está.' WHERE `ID`=66622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광의 대가는 비취 숲의 녹옥 채석장에 있습니다. 아마 그들에게서 기술을 배울 수 있을 겁니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='大师级矿工就在翡翠林的绿石采掘场。他们也许能帮你提升技能。我会在你的地图上标出他们的位置。', `MaleText_loc5`='在翠玉林的綠石採石場有採礦大師。他們應該能幫你增進技能。我會替你在地圖上標記出來。', `MaleText_loc7`='Hay maestros mineros en la Cantera Verdemar, en el Bosque de Jade. Seguro que pueden ayudarte a mejorar tu habilidad. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='채광의 대가는 비취 숲의 녹옥 채석장에 있습니다. 아마 그들에게서 기술을 배울 수 있을 겁니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='大师级矿工就在翡翠林的绿石采掘场。他们也许能帮你提升技能。我会在你的地图上标出他们的位置。', `FemaleText_loc5`='在翠玉林的綠石採石場有採礦大師。他們應該能幫你增進技能。我會替你在地圖上標記出來。', `FemaleText_loc7`='Hay maestros mineros en la Cantera Verdemar, en el Bosque de Jade. Seguro que pueden ayudarte a mejorar tu habilidad. Te marcaré su ubicación en el mapa.' WHERE `ID`=66623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공 전문가는 쿤라이 봉우리의 그루멀 시장에 있습니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。', `MaleText_loc5`='你可以在崑萊峰的咕嚕摩市集找到製皮訓練師。我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un instructor de peletería en El Bazar Grúmel, en la Cima Kun-Lai. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='가죽세공 전문가는 쿤라이 봉우리의 그루멀 시장에 있습니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。', `FemaleText_loc5`='你可以在崑萊峰的咕嚕摩市集找到製皮訓練師。我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un instructor de peletería en El Bazar Grúmel, en la Cima Kun-Lai. Te marcaré su ubicación en el mapa.' WHERE `ID`=66624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽 너머 공포의 황무지에 사는 클락시 중에 연금술의 대가가 있다고 하더군요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。', `MaleText_loc5`='我聽說卡拉西有大師級的鍊金師。就在長城之後的遙遠悚然荒野裡。我會替你在地圖上標記出位置。', `MaleText_loc7`='He oído que algunos Klaxxi son maestros alquimistas, al otro lado de la muralla, en el Desierto del Pavor. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='장벽 너머 공포의 황무지에 사는 클락시 중에 연금술의 대가가 있다고 하더군요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。', `FemaleText_loc5`='我聽說卡拉西有大師級的鍊金師。就在長城之後的遙遠悚然荒野裡。我會替你在地圖上標記出位置。', `FemaleText_loc7`='He oído que algunos Klaxxi son maestros alquimistas, al otro lado de la muralla, en el Desierto del Pavor. Te marcaré su ubicación en el mapa.' WHERE `ID`=66625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡, 네싱워리 탐험대에 무두질 전문가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='在四風峽的奈辛瓦里狩旅團有一名剝皮訓練師。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un instructor de desuello en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='네 바람의 계곡, 네싱워리 탐험대에 무두질 전문가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='在四風峽的奈辛瓦里狩旅團有一名剝皮訓練師。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un instructor de desuello en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여에 관해서라면, 비취 숲, 새벽의 꽃에 있는 마법손 라이와 이야기하면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='關於附魔的需求，你得去翠玉林的晨綻找『術爪』籟。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Para cualquier tema relacionado con el encantamiento, deberías hablar con Lai Zarpa Hechicera en Floralba, en el Bosque de Jade.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='마법부여에 관해서라면, 비취 숲, 새벽의 꽃에 있는 마법손 라이와 이야기하면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='關於附魔的需求，你得去翠玉林的晨綻找『術爪』籟。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Para cualquier tema relacionado con el encantamiento, deberías hablar con Lai Zarpa Hechicera en Floralba, en el Bosque de Jade.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾으시는 사람은 네 바람의 계곡, 네싱워리 탐험대에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='你要找的人就在四風峽的奈辛瓦里狩旅團。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='La persona que buscas se encuentra en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='찾으시는 사람은 네 바람의 계곡, 네싱워리 탐험대에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='你要找的人就在四風峽的奈辛瓦里狩旅團。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='La persona que buscas se encuentra en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달인 라오를 찾으시는군요! 라오는 영원꽃 골짜기에 있는 석양 주둔지에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='你要找的肯定是廖禪師!他就在恆春谷的落陽要塞工作。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='¡Creo que buscas al maestro zen Lao! Trabaja en el Baluarte del Sol Poniente, en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='달인 라오를 찾으시는군요! 라오는 영원꽃 골짜기에 있는 석양 주둔지에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='你要找的肯定是廖禪師!他就在恆春谷的落陽要塞工作。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='¡Creo que buscas al maestro zen Lao! Trabaja en el Baluarte del Sol Poniente, en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 영원꽃 골짜기에 있는 모구샨 궁전 위, 지식의 연단에 고고학의 대가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='知識之座那裡有一名考古學大師，就在恆春谷的魔古山宮之上。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un maestro arqueólogo en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='이곳 영원꽃 골짜기에 있는 모구샨 궁전 위, 지식의 연단에 고고학의 대가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='知識之座那裡有一名考古學大師，就在恆春谷的魔古山宮之上。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un maestro arqueólogo en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 치유사 난을 찾으시는군요. 난은 일곱 별의 제단 안에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='噢是的，你一定是在找治疗者楠。她就在七星殿里。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='喔是了，你該去找楠大夫。你可以在七星廟裡找到她。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Ah, sí, buscas a la sanadora Nan. La encontrarás dentro del Santuario de las Siete Estrellas.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 치유사 난을 찾으시는군요. 난은 일곱 별의 제단 안에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='噢是的，你一定是在找治疗者楠。她就在七星殿里。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='喔是了，你該去找楠大夫。你可以在七星廟裡找到她。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Ah, sí, buscas a la sanadora Nan. La encontrarás dentro del Santuario de las Siete Estrellas.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리 기술을 배우고 싶으신가요?$B$B그렇다면 아이언포우 가문을 찾아가셔야 합니다. 네 바람의 계곡, 언덕골 시장에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。', `MaleText_loc5`='想要增進廚藝技能，是嗎?$B$B你該去找鐵爪家的人。他們就住在四風峽的半丘市集。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='¿Te interesa mejorar tus dotes culinarias?$b$bDeberías hablar con la familia Zarpa Férrea. Se encuentran en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='요리 기술을 배우고 싶으신가요?$B$B그렇다면 아이언포우 가문을 찾아가셔야 합니다. 네 바람의 계곡, 언덕골 시장에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。', `FemaleText_loc5`='想要增進廚藝技能，是嗎?$B$B你該去找鐵爪家的人。他們就住在四風峽的半丘市集。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='¿Te interesa mejorar tus dotes culinarias?$b$bDeberías hablar con la familia Zarpa Férrea. Se encuentran en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초학을 배우고 싶으시군요. 비취 숲에 있는 전문가와 이야기해 보십시오.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='如果你想对草药学有更深的了解，我建议你去找翡翠林中的训练师谈谈。$B$B我会为你在地图上标出位置。', `MaleText_loc5`='如果你想了解更多關於草藥學的事，建議你去翠玉林找訓練師。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Si deseas aprender más sobre el arte de la herboristería, te sugiero que hables con el instructor del Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='약초학을 배우고 싶으시군요. 비취 숲에 있는 전문가와 이야기해 보십시오.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='如果你想对草药学有更深的了解，我建议你去找翡翠林中的训练师谈谈。$B$B我会为你在地图上标出位置。', `FemaleText_loc5`='如果你想了解更多關於草藥學的事，建議你去翠玉林找訓練師。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Si deseas aprender más sobre el arte de la herboristería, te sugiero que hables con el instructor del Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 영원꽃 골짜기, 지식의 연단에 주문각인 전문가가 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。', `MaleText_loc5`='是的，在恆春谷的知識之座有一名銘文學訓練師。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Sí, conozco a un instructor de inscripción en el Trono del Saber, en el Valle de la Flor Eterna.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 영원꽃 골짜기, 지식의 연단에 주문각인 전문가가 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。', `FemaleText_loc5`='是的，在恆春谷的知識之座有一名銘文學訓練師。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Sí, conozco a un instructor de inscripción en el Trono del Saber, en el Valle de la Flor Eterna.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 세공사 마이를 찾으시는군요. 마이는 비취 숲에 있는 녹옥 마을에 삽니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='你該去找『塑玉者』梅。她就在翠玉林的綠石村。', `MaleText_loc7`='Buscas a Mai, la Moldeadora de Jade. La encontrarás en la Aldea Verdemar, en el Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='비취 세공사 마이를 찾으시는군요. 마이는 비취 숲에 있는 녹옥 마을에 삽니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='你該去找『塑玉者』梅。她就在翠玉林的綠石村。', `FemaleText_loc7`='Buscas a Mai, la Moldeadora de Jade. La encontrarás en la Aldea Verdemar, en el Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 애완동물 한 마리 가지면 안 돼요, 핀클스위치 아줌마? 네?', `FemaleText_loc4`='能给我们一些宠物吗，芬克斯维奇小姐？拜托了。', `FemaleText_loc5`='我們能跟你拿一些寵物嗎，芬克開關小姐?拜託?', `FemaleText_loc7`='¿Nos das alguna de tus mascotas, señorita Fusta Severa? ¿Por favor?' WHERE `ID`=66636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼, 얘들아. 너흰 아직 너무 작아!', `FemaleText_loc4`='不，不，小家伙们。你们还太小了！', `FemaleText_loc5`='不不，小傢伙們。你們還太小了!', `FemaleText_loc7`='No, no, pequeños. ¡Todavía no sois lo bastante mayores!' WHERE `ID`=66637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이...', `MaleText_loc4`='噢，天哪……', `MaleText_loc5`='啊，天啊...', `MaleText_loc7`='¡Jo!' WHERE `ID`=66638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름길잡이 렁이 판다리아에서 비행하는 법을 가르쳐 줄 겁니다. 중앙 난간뜰에서 운룡을 타고 있지요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='穿云行者凌大师能教你如何在潘达利亚飞行。他正骑着云端翔龙停在主露台上。我会在你的地图上标出他的位置。', `MaleText_loc5`='踏雲者嶺能教導你如何在潘達利亞飛行。他在主要平臺上，乘著他的雲蛟。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El mensajero del cielo Leng puede enseñarte a volar en Pandaria. Monta su dragón nimbo en el patio principal. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='구름길잡이 렁이 판다리아에서 비행하는 법을 가르쳐 줄 겁니다. 중앙 난간뜰에서 운룡을 타고 있지요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='穿云行者凌大师能教你如何在潘达利亚飞行。他正骑着云端翔龙停在主露台上。我会在你的地图上标出他的位置。', `FemaleText_loc5`='踏雲者嶺能教導你如何在潘達利亞飛行。他在主要平臺上，乘著他的雲蛟。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El mensajero del cielo Leng puede enseñarte a volar en Pandaria. Monta su dragón nimbo en el patio principal. Te marcaré su ubicación en el mapa.' WHERE `ID`=66639;
