UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흠, 내가 쟤보다 키가 큰 것 같은데.', `FemaleText_loc4`='哼。我可能比她还高呢。', `FemaleText_loc5`='唔。我可能比她高。', `FemaleText_loc7`='Bah. Seguramente soy más alto que ella.' WHERE `ID`=66641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기에는 전투모병관이 없습니다.$B$B전장이나 투기장 대기열에 등록하려면 대도시로 돌아가야 할 겁니다.', `MaleText_loc4`='在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。', `MaleText_loc5`='山谷這裡沒有戰場軍官。$B$B你必須回到你的主城來加入戰場或競技場的佇列。', `MaleText_loc7`='No hay maestros de batalla en el valle.$b$bSi quieres ponerte a la cola de los campos de batalla o las arenas de guerra, tendrás que volver a tu capital.', `FemaleText_loc1`='영원꽃 골짜기에는 전투모병관이 없습니다.$B$B전장이나 투기장 대기열에 등록하려면 대도시로 돌아가야 할 겁니다.', `FemaleText_loc4`='在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。', `FemaleText_loc5`='山谷這裡沒有戰場軍官。$B$B你必須回到你的主城來加入戰場或競技場的佇列。', `FemaleText_loc7`='No hay maestros de batalla en el valle.$b$bSi quieres ponerte a la cola de los campos de batalla o las arenas de guerra, tendrás que volver a tu capital.' WHERE `ID`=66642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형상변환이나 공허 보관소를 이용하시려면 대도시에 가셔야 합니다.', `MaleText_loc4`='你可以在自己的主城使用幻化和虚空仓库服务。', `MaleText_loc5`='塑形和虛空倉庫服務就在你老家的主城裡。', `MaleText_loc7`='Los servicios de transfiguración y depósito del vacío están disponibles en tu capital.', `FemaleText_loc1`='형상변환이나 공허 보관소를 이용하시려면 대도시에 가셔야 합니다.', `FemaleText_loc4`='你可以在自己的主城使用幻化和虚空仓库服务。', `FemaleText_loc5`='塑形和虛空倉庫服務就在你老家的主城裡。', `FemaleText_loc7`='Los servicios de transfiguración y depósito del vacío están disponibles en tu capital.' WHERE `ID`=66643;
