UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저런, 저런. 사제님은 지금 누굴 도울 수 있는 형편이 아니에요. 팔이 둘 다 부러졌잖아요! 약을 가져다 드릴게요.', `FemaleText_loc4`='好了，好了，牧师。你现在谁也帮不了，自己的两条胳膊都断了！我给你敷点药。', `FemaleText_loc5`='唉呀呀，牧師。你現在可沒辦法治療任何人了。你的雙手都斷了!讓我給你弄些藥來。', `FemaleText_loc7`='Tranquilo, tranquilo, sacerdote. No estás en condiciones de ayudar a nadie. ¡Tienes los dos brazos rotos! Te traeré algún medicamento.' WHERE `ID`=66660;
