UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일용품이 필요하십니까? 보니에게서 살 수 있을 겁니다. 보니는 황금 등불에서 장사를 하지요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='想买杂货？伯妮那儿应该有你要找的东西。她就在金色神灯卖杂货。我会在你的地图上标出位置。', `MaleText_loc5`='你在找雜貨嗎?繃尼會有你需要的東西。她在金燈籠開業。我會替你把位置在標記在地圖上。', `MaleText_loc7`='¿Buscas pertrechos? Bonni tiene lo que necesitas. Vende su mercancía en El Farol Áureo. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='일용품이 필요하십니까? 보니에게서 살 수 있을 겁니다. 보니는 황금 등불에서 장사를 하지요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='想买杂货？伯妮那儿应该有你要找的东西。她就在金色神灯卖杂货。我会在你的地图上标出位置。', `FemaleText_loc5`='你在找雜貨嗎?繃尼會有你需要的東西。她在金燈籠開業。我會替你把位置在標記在地圖上。', `FemaleText_loc7`='¿Buscas pertrechos? Bonni tiene lo que necesitas. Vende su mercancía en El Farol Áureo. Te marcaré su ubicación en el mapa.' WHERE `ID`=66674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행상 하나가 황금 등불에서 장사를 하는 걸 봤습니다.위치를 지도에 표시해 드리지요.', `MaleText_loc4`='我看到有个小贩在金色神灯摆摊卖货。我会在你的地图上标出位置。', `MaleText_loc5`='我看到有個小販在金燈籠做買賣。我會替你把位置在標記在地圖上。', `MaleText_loc7`='He visto a un buhonero que vendía cosas en El Farol Áureo. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='행상 하나가 황금 등불에서 장사를 하는 걸 봤습니다.위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='我看到有个小贩在金色神灯摆摊卖货。我会在你的地图上标出位置。', `FemaleText_loc5`='我看到有個小販在金燈籠做買賣。我會替你把位置在標記在地圖上。', `FemaleText_loc7`='He visto a un buhonero que vendía cosas en El Farol Áureo. Te marcaré su ubicación en el mapa.' WHERE `ID`=66675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마누라...', `MaleText_loc4`='我想你会说……', `MaleText_loc5`='看來你可以說...', `MaleText_loc7`='Supongo que se podría decir...' WHERE `ID`=66676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배가 빵빵한 게 정말 이쁘죠?', `MaleText_loc4`='我想你会说，她在烤箱里藏了个小宝宝。', `MaleText_loc5`='看來，你可以說她還有個麵包在爐子裡!', `MaleText_loc7`='¡Supongo que se podría decir que tengo un bollo en el horno!' WHERE `ID`=66677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러게... 삼겹살이 스무 근은 나오겠어...', `MaleText_loc4`='你妻子怎么还在用烤箱？我还等着烤肉呢！', `MaleText_loc5`='你老婆為什麼還在用爐子?我要烤肉!', `MaleText_loc7`='¿Por qué sigue usando el horno tu mujer? ¡Tengo que cocinar la carne!' WHERE `ID`=66678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마이클 베데르닉이 침을 흘립니다.', `MaleText_loc4`='米歇尔·扫榻咆哮起来。', `MaleText_loc5`='麥可·貝德尼克咆哮著。', `MaleText_loc7`='Michael Bedernik gruñe.' WHERE `ID`=66679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그만해요!', `FemaleText_loc4`='你们两个都给我闭嘴！', `FemaleText_loc5`='你們兩個，夠了!', `FemaleText_loc7`='¡Ustedes dos! ¡Ya basta!' WHERE `ID`=66680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠다, 제자여. 네가 진정 나의 가르침... 주학의 가르침을 실천하고 있음을 잘 알겠다.', `MaleText_loc4`='打得不错，弟子。你已用行动证明，自己真正领会了我的……朱鹤之道.', `MaleText_loc5`='打得好，弟子。你證明了自己是我真正的傳承者...鶴之道的傳承者。', `MaleText_loc7`='Has luchado bien, estudiante. Has demostrado que te entregas a mi senda... la Senda de la Grulla.' WHERE `ID`=66681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망은 어디에서나 피어난다... 이 잊힌 밀림의 어두운 구석에서조차도...', `MaleText_loc4`='希望之花会在各处盛开……哪怕是在被遗忘丛林的阴暗角落也不例外。', `MaleText_loc5`='希望能在任何地方綻放...就連在這蠻荒叢林的黑暗角落也不例外。', `MaleText_loc7`='La esperanza puede florecer en cualquier parte... hasta en este rincón oscuro de una selva olvidada.' WHERE `ID`=66682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너와 같은 영웅이 씨앗을 심기만 하면 된다.', `MaleText_loc4`='所需要的就是一位像你这样的英雄，来播下种子。', `MaleText_loc5`='它只需要有個像你這樣的英雄來撒下種子。', `MaleText_loc7`='Solo necesita que los héroes como tú planten la semilla.' WHERE `ID`=66683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 악몽을 멈춰라!', `MaleText_loc4`='停止这噩梦！', `MaleText_loc5`='終止這個夢魘!', `MaleText_loc7`='¡Detén esta pesadilla!' WHERE `ID`=66684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 조종당하지 않을 것이다!', `MaleText_loc4`='我不会被控制！', `MaleText_loc5`='我不會受到控制!', `MaleText_loc7`='¡Nadie puede controlarme!' WHERE `ID`=66685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어느 병참장교를 찾으십니까? 제가 도움을 드릴 수 있을지도요.', `MaleText_loc4`='啊，你在找什么军需官？也许我能帮你找到他们。', `MaleText_loc5`='啊，你在找軍需官?也許我可以幫你找到他們。', `MaleText_loc7`='¿Qué intendente estás buscando? A lo mejor te puedo ayudar a encontrarlo.', `FemaleText_loc1`='아, 어느 병참장교를 찾으십니까? 제가 도움을 드릴 수 있을지도요.', `FemaleText_loc4`='啊，你在找什么军需官？也许我能帮你找到他们。', `FemaleText_loc5`='啊，你在找軍需官?也許我可以幫你找到他們。', `FemaleText_loc7`='¿Qué intendente estás buscando? A lo mejor te puedo ayudar a encontrarlo.' WHERE `ID`=66686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강태공 연합 병참장교를 찾으십니까? 내트 페이글 말씀이군요. 크라사랑 밀림의 강태공 부두에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='在找釣手隊軍需官?那就是納特·帕格了。你可以在喀撒朗蠻荒的釣手泊船處找到他。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='¿Buscas al intendente de los Pescadores? Es Nat Pagle. Lo encontrarás en el Muelle de los Pescadores, en la Espesura Krasarang.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='강태공 연합 병참장교를 찾으십니까? 내트 페이글 말씀이군요. 크라사랑 밀림의 강태공 부두에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='在找釣手隊軍需官?那就是納特·帕格了。你可以在喀撒朗蠻荒的釣手泊船處找到他。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='¿Buscas al intendente de los Pescadores? Es Nat Pagle. Lo encontrarás en el Muelle de los Pescadores, en la Espesura Krasarang.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=66687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텅 썬더몰트와 이야기하시면 됩니다! 그는 네 바람의 계곡, 스톰스타우트 양조장에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你应该跟邓·雷酒谈谈！他就在四风谷的风暴烈酒酿造厂。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='你得去找譚格·雷麥!你可以在四風峽的風暴烈酒酒坊找到他。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='¡Tienes que hablar con Teng Malta Tronadora! Se encuentra en la Cervecería del Trueno, en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='텅 썬더몰트와 이야기하시면 됩니다! 그는 네 바람의 계곡, 스톰스타우트 양조장에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你应该跟邓·雷酒谈谈！他就在四风谷的风暴烈酒酿造厂。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='你得去找譚格·雷麥!你可以在四風峽的風暴烈酒酒坊找到他。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='¡Tienes que hablar con Teng Malta Tronadora! Se encuentra en la Cervecería del Trueno, en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼 연합 병참장교는 지나 머드클로입니다. 언덕골에서 시장을 운영하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='如果你在找耕者軍需官，吉娜·泥爪就是你所要找的女孩。她在半丘市集開店。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='Si buscas a la intendente de los Labradores, entonces Gina Zarpa Fangosa es tu chica. Estará encargándose del mercado en El Alcor.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='농사꾼 연합 병참장교는 지나 머드클로입니다. 언덕골에서 시장을 운영하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='如果你在找耕者軍需官，吉娜·泥爪就是你所要找的女孩。她在半丘市集開店。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='Si buscas a la intendente de los Labradores, entonces Gina Zarpa Fangosa es tu chica. Estará encargándose del mercado en El Alcor.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡단 병참장교는 싼 레드스케일입니다.$B$B비취 숲의 도원에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='飒安·红鳞是云端翔龙骑士团的军需官。$B$B你可以在翡翠林的百木园找到他。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='桑·紅鱗是雲蛟衛的軍需官。$B$B你可以在翠玉林的落英園找到他。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='San Escama Roja es el intendente de la Orden del Dragón Nimbo.$b$bLo encontrarás en El Arboretum, en el Bosque de Jade.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='운룡단 병참장교는 싼 레드스케일입니다.$B$B비취 숲의 도원에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='飒安·红鳞是云端翔龙骑士团的军需官。$B$B你可以在翡翠林的百木园找到他。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='桑·紅鱗是雲蛟衛的軍需官。$B$B你可以在翠玉林的落英園找到他。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='San Escama Roja es el intendente de la Orden del Dragón Nimbo.$b$bLo encontrarás en El Arboretum, en el Bosque de Jade.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 죄송하지만 클락시에 대해서는 잘 모릅니다. 하지만 그들의 도시, 클락시베스가 공포의 황무지 서쪽 끝에 있다는 풍문은 들은 적이 있습니다. 거기 클락시 병참장교가 있을지도 모르겠네요.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='嗯，恐怕我對卡拉西所知甚少，但我曾聽說過他們的城市叫卡拉西斐斯，就坐落在遙遠西方的悚然荒野裡。也許你可以在那裡找到卡拉西軍需官。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Mmm... Me temo que no sé gran cosa sobre los Klaxxi, pero he oído rumores de que tienen una ciudad, Klaxxi''vess, muy al oeste, en el Desierto del Pavor. A lo mejor allí encontrarás al intendente de los Klaxxi.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='흠... 죄송하지만 클락시에 대해서는 잘 모릅니다. 하지만 그들의 도시, 클락시베스가 공포의 황무지 서쪽 끝에 있다는 풍문은 들은 적이 있습니다. 거기 클락시 병참장교가 있을지도 모르겠네요.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='嗯，恐怕我對卡拉西所知甚少，但我曾聽說過他們的城市叫卡拉西斐斯，就坐落在遙遠西方的悚然荒野裡。也許你可以在那裡找到卡拉西軍需官。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Mmm... Me temo que no sé gran cosa sobre los Klaxxi, pero he oído rumores de que tienen una ciudad, Klaxxi''vess, muy al oeste, en el Desierto del Pavor. A lo mejor allí encontrarás al intendente de los Klaxxi.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 병참장교는 탕랑 평원의 음영파 주둔지에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='影潘軍需官就在螳螂荒原的影潘要塞。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente del Shadopan está en el Cuartel del Shadopan, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='음영파 병참장교는 탕랑 평원의 음영파 주둔지에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='影潘軍需官就在螳螂荒原的影潘要塞。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente del Shadopan está en el Cuartel del Shadopan, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 너그러운 잘루를 찾으시는군요! 그는 제 바로 옆에 있습니다.', `MaleText_loc4`='啊，你要找宽仁的贾鲁！他就在我身旁。', `MaleText_loc5`='啊，你在找『慷慨使』賈廬!他就在我旁邊。', `MaleText_loc7`='¡Ah, buscas a Jaluu el Generoso! Está justo a mi lado.', `FemaleText_loc1`='아, 너그러운 잘루를 찾으시는군요! 그는 제 바로 옆에 있습니다.', `FemaleText_loc4`='啊，你要找宽仁的贾鲁！他就在我身旁。', `FemaleText_loc5`='啊，你在找『慷慨使』賈廬!他就在我旁邊。', `FemaleText_loc7`='¡Ah, buscas a Jaluu el Generoso! Está justo a mi lado.' WHERE `ID`=66693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 천신회 병참장교인 현자 화이트하트는 이곳 영원꽃 골짜기에 있습니다. 여름 난간뜰 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='至尊天神军需官就在山谷里。白心贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者白心和其他的議員都在夏日露臺的低窪地區。$B$B我會替你在地圖上標記出他的位置。', `MaleText_loc7`='El intendente de los Augustos Celestiales está aquí, en el valle. El sabio Corazón Albo acompaña a los demás representantes de facción en la sección inferior del Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='위대한 천신회 병참장교인 현자 화이트하트는 이곳 영원꽃 골짜기에 있습니다. 여름 난간뜰 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='至尊天神军需官就在山谷里。白心贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者蓮綻和其他的議員都在金輝臺的低窪地區。$B$B我會替你在地圖上標記出他的位置。', `FemaleText_loc7`='El intendente de los Augustos Celestiales está aquí, en el valle. El sabio Corazón Albo acompaña a los demás representantes de facción en la sección inferior del Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 천신회 병참장교인 현자 로터스블룸은 이곳 영원꽃 골짜기에 있습니다. 여름 난간뜰 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者蓮綻和其他的議員都在夏日露臺的低窪地區。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='La intendente de los Augustos Celestiales está aquí, en el valle. La sabia Flor de Loto acompaña a los demás representantes de facción en la sección inferior del Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='위대한 천신회 병참장교인 현자 로터스블룸은 이곳 영원꽃 골짜기에 있습니다. 여름 난간뜰 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者蓮綻和其他的議員都在夏日露臺的低窪地區。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='La intendente de los Augustos Celestiales está aquí, en el valle. La sabia Flor de Loto acompaña a los demás representantes de facción en la sección inferior del Bancal del Verano.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄 신 탸오를 찾으시는군요. 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 위, 지식의 연단에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='你該去找譚杏桃。她人在知識之座，就這座恆春谷裡的魔古山宮上。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Buscas a Tan Shin Tiao. La encontrarás en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='탄 신 탸오를 찾으시는군요. 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 위, 지식의 연단에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='你該去找譚杏桃。她人在知識之座，就這座恆春谷裡的魔古山宮上。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Buscas a Tan Shin Tiao. La encontrarás en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹 병참장교인 사령관 옥스하트는 탕랑 평원의 니우짜오 사원에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='勇氣點數軍需官指揮官牛心就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente de valor, el comandante Corazón de Buey, se encuentra en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='용맹 병참장교인 사령관 옥스하트는 탕랑 평원의 니우짜오 사원에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='勇氣點數軍需官指揮官牛心就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente de valor, el comandante Corazón de Buey, se encuentra en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탕랑 평원의 니우짜오 사원에 있는 사령관 로 핑을 찾아가면 정의의 징표로 거래를 할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='指揮官駱平可以和你交易正義印記，他就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Puedes intercambiar tus marcas de justicia con el comandante Lo Ping. Está en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='탕랑 평원의 니우짜오 사원에 있는 사령관 로 핑을 찾아가면 정의의 징표로 거래를 할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='指揮官駱平可以和你交易正義印記，他就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Puedes intercambiar tus marcas de justicia con el comandante Lo Ping. Está en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66698;
