UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='플리브 씨가 제게 박제 전문가가 되는 법을 가르쳐주고 계세요. 제 생각이지만, 플리브 씨의 방식은 너무 구식이라서 우리 노움의 "기발한" 천재성이 도움을 줄 수 있을 것 같아요.', `FemaleText_loc4`='普利波先生在教我如何做一位标本剥制师。我个人觉得他的思想过于陈旧了，应该从侏儒工程学中找点儿灵感。', `FemaleText_loc5`='痞利浦先生在教導我如何當一個標本剝製師。個人來說，我覺得他有點太過時了，應該稍微學點地精的「工業美學」', `FemaleText_loc7`='El señor Pleeb me está enseñando a ser una taxidermista. En mi opinión, está un poco anticuado y le vendría bien un poco de ingenio gnómico... o ingeniería gnómica.' WHERE `ID`=66728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 젊은이! 우레전차 XT 9000을 작동시키는 데 성공했나?', `MaleText_loc4`='噢，小伙子！你让那个雷霆坦克XT-9000开始工作了吗？', `MaleText_loc5`='喂，小子!你讓那個雷坦XT 9000運作起來了沒?', `MaleText_loc7`='¡Oye, chaval! ¿Ya has conseguido que funcione aquel Truenotanque XT 9000?' WHERE `ID`=66729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요, 아직입니다.', `MaleText_loc4`='不，先生。我不这么认为。', `MaleText_loc5`='不，長官。我想還沒。', `MaleText_loc7`='No, señor. Me temo que no.' WHERE `ID`=66730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 혹시 크라사랑 쪽으로 갈 일이 있었습니까?$B$B한번 가 보는 게 좋을 겁니다. 대풍년이라도 든 듯이 고기가 잘 잡히거든요.$B$B우리 아버지 말씀대로, 빠른 낚시꾼이 고기를 잡지요!', `MaleText_loc4`='朋友，你最近去过卡桑琅吗？$B$B真该去一探究竟。那里水产丰富，绝对能让你满网而归。$B$B我父亲说过，早起的渔夫有鱼吃！', `MaleText_loc5`='朋友，你最近曾旅行到喀撒朗蠻荒嗎?$B$B過去那裏是個聰明的決定。那裡的漁獲真是無比豐盛。$B$B就像我父親說過的，早起的漁夫有魚抓!', `MaleText_loc7`='¿Te han conducido tus viajes a Krasarang últimamente?$b$bSería buena idea aventurarse por allá. Los peces son tan abundantes como la cosecha más afortunada.$b$bComo decía mi padre, ¡el pescador que madruga se lleva el botín!' WHERE `ID`=66731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑 밀림 남동쪽에 있는 강태공 부두에는, 판다리아에서 가장 왕성하게 활동하는 낚시꾼들이 모여 있습니다.$B$B망망대해와 함께 보람찬 하루를 보내고 싶다면, 부디 저희를 찾아 주십시오.', `MaleText_loc4`='位于卡桑琅丛林东南部的渔人码头是潘达利亚这一带所有的钓鱼发烧友都倾心向往的好地方。$B$B如果你愿意忙里偷闲，在海边享受一日静谧的好时光，就来找我们吧。', `MaleText_loc5`='喀撒朗蠻荒東南角的釣手泊船處是潘達利亞這一帶優秀釣手隊的家。$B$B如果你喜歡花上一天和大海作伴，竭誠歡迎你賞光來拜訪我們。', `MaleText_loc7`='El Muelle de los Pescadores, en la zona sureste de la Espesura Krasarang, es donde se reúnen los pescadores más devotos de Pandaria.$b$bSi te gusta pasar el día en el mar, te animo a que nos honres con tu presencia.' WHERE `ID`=66732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보상이... 꼭 필요합니까?$B$B조과를 거두는 기쁨 자체가 보상 아닙니까? 망망대해를 보며 느끼는 설렘은 어떻고요? 낚시를 통해서만 느낄 수 있는 동지애는요?$B$B아직 멀었군요, $r.$B$B그저 제 생각만이 아닙니다. 낚시를 통해서 많은 것을 얻을 수 있습니다.$B$B낚시 기술도 향상시킬 수 있고, 언젠가 막강한 낚싯대를 살 수도 있지요.$B$B최고의 낚시꾼은 특별한 물고기 애완동물이라든지, 물속을 달리는 탈것이라든지, 낚시 뗏목을 얻을 수도 있습니다.', `MaleText_loc4`='你想要……奖励？$B$B成功捕到一条大鱼的快乐还不算是奖励？那么身临大海的兴奋呢？还有仅凭一根钓竿就能获得的归属感？$B$B你还有很多东西要学，$r。$B$B抛开我的个人见解不谈，光是垂钓的学问就能让你钻研好久了。$B$B你可以提高自己的钓鱼技能。今后，你能买到强大的钓竿。$B$B倍受尊重的渔夫还能获得特殊的鱼类宠物、水黾坐骑，甚至还有捕鱼木筏。', `MaleText_loc5`='你想要...報酬?$B$B把大魚從海中釣起來的樂趣還不夠嗎?寬廣大海帶來的戰慄?一個人和一根釣竿之間的斷背情誼?$B$B你有很多要學的，$r。$B$B先不管我的觀點，釣魚的技藝能帶來很多東西。$B$B你可以增進你的釣魚技能。有一天，你將可以購買強力的釣魚竿。$B$B受人敬仰的漁夫還可以得到特別的小魚寵物、一隻水黽坐騎和捕魚筏。', `MaleText_loc7`='Buscas... ¿una recompensa?$b$b¡Pero si la alegría de pescar un pez es recompensa suficiente! ¡La emoción del mar abierto! ¡La camaradería que solo puede proporcionar una caña de pescar!$b$bTe queda mucho por aprender, $r.$b$bDejando de lado mi opinión, el arte de la pesca tiene mucho que ofrecer.$b$bPuedes mejorar tu habilidad en pesca. Algún día podrás comprar poderosas cañas de pescar.$b$bLos pescadores más respetados pueden acceder a un pez mascota especial, una montura de zancudo acuático y una balsa de pesca.' WHERE `ID`=66733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 큰 빚을 졌습니다.', `MaleText_loc4`='谢谢。多亏你了。', `MaleText_loc5`='謝謝你。我大大地欠你一次。', `MaleText_loc7`='Gracias. Te debo una.' WHERE `ID`=66734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에 갇혀 있는 동안 들은 것이 많습니다. 런싸이 님께 말씀드리면 기뻐하실 겁니다.', `MaleText_loc4`='我在被囚禁时偷听到了不少消息。任塞一定会对我所带来的情报感到很高兴的。', `MaleText_loc5`='我不小心從牢籠那裏聽到很多。聽到我要跟他講的事情，任賽會很高興的。', `MaleText_loc7`='He oído muchas cosas desde la jaula. Rensai estará satisfecho con todo lo que tengo que contarle.' WHERE `ID`=66735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 또 만나지요, 친구.', `MaleText_loc4`='希望我们很快就能再次相见，我的新朋友。', `MaleText_loc5`='希望我們能早日再見，我的新朋友。', `MaleText_loc7`='Espero que nos veamos de nuevo, mi $gnuevo amigo:nueva amiga;.' WHERE `ID`=66736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='납골당에 침입자가 들어왔다! 살아서 나가게 하지 마라!', `MaleText_loc4`='地穴里闯进了入侵者！别让他们活着出去！', `MaleText_loc5`='有人闖進墓穴!別讓他們活著離開!', `MaleText_loc7`='¡Intrusos en la cripta! ¡No dejen que salgan con vida!' WHERE `ID`=66737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너도 곧 시체가 돼서 여기 묻힐 거다, 애송이 $c 놈아!', `MaleText_loc4`='你很快就会跟那些被遗忘的尸体一样被埋在这里了，小$c！', `MaleText_loc5`='很快你就要加入被埋這裡的屍體了，渺小的$c!', `MaleText_loc7`='¡Pronto el tuyo será uno más de todos estos cadáveres, $gpequeño:pequeña; $c!' WHERE `ID`=66738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅이 사마귀 무리에게 짓밟히지 않은 것은 모두 음영파의 끊임없는 노력 덕분이라오. 생색을 내려는 건 아니오. 이제는 우리 힘만으로는 이 땅을 지켜 낼 수 없는 시점이 되었소.', `MaleText_loc4`='影踪派的不懈戍守，是这片土地至今仍未被螳螂妖大军席卷的唯一理由。我们不求感谢，可我们眼下再也无力独自完成这项任务了。', `MaleText_loc5`='影潘孜孜不倦的努力是唯一讓這片土地免於受螳螂人肆虐的原因。我們不為此要求感謝，但我們正面臨著無法單靠自己完成這項任務的艱難時刻。', `MaleText_loc7`='La vigilia incansable del Shadopan es lo único que impide que el enjambre mántide arrase esta tierra. No pedimos que nos lo agradezcan, pero hemos llegado a un punto en el que ya no podemos llevar a cabo semejante tarea sin ayuda.' WHERE `ID`=66739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 번개 덫을 밟았습니다!', `MaleText_loc4`='$n踩中了闪电陷阱！', `MaleText_loc5`='$n踩到了一個閃電陷阱!', `MaleText_loc7`='¡$n ha pisado una trampa de relámpagos!', `FemaleText_loc1`='$n|1이;가; 번개 덫을 밟았습니다!', `FemaleText_loc4`='$n踩中了闪电陷阱！', `FemaleText_loc5`='$n踩到了一個閃電陷阱!', `FemaleText_loc7`='¡$n ha pisado una trampa de relámpagos!' WHERE `ID`=66740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함선이 불길에 휩싸이기 전에 내리십시오!', `MaleText_loc4`='在船被烈焰吞噬前，赶快逃离！', `MaleText_loc5`='在船被火焰吞沒前逃出來!', `MaleText_loc7`='¡Bájate del barco antes de que el fuego lo consuma!' WHERE `ID`=66741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라, $n. 이 땅의 분노는 아직도 잠잠해질 기미가 안 보인다. 너의 존재 자체가 이 땅에게는 지금까지 없었던 고통이다.', `MaleText_loc4`='多加小心，$r。这片土地的怒火尚未平息。你的到来令它感到前所未有的不安。', `MaleText_loc5`='腳步輕點，$r。這片土地的憤怒還沒有平息。你的存在讓它承受前所未有的痛苦。', `MaleText_loc7`='Ve con cuidado, $r. La ira de esta tierra aún no se ha saciado. Tu mera presencia le provoca una angustia que no había sufrido nunca.' WHERE `ID`=66742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 얻을 것이 없는 전쟁을 계속하는가? 꿈에서 수천 명이 지르는 단말마의 비명이 너를 괴롭히지 않는가?', `MaleText_loc4`='我们为什么要继续在一场毫无裨益的战斗中继续苦战？千万条生命临死前的叫喊，竟没让你夜夜噩梦缠身？', `MaleText_loc5`='我們為什麼要繼續進行毫無益處的戰爭?難道你沒在夢裡聽見千萬名死者的哀嚎?', `MaleText_loc7`='¿Por qué seguimos luchando en una guerra en la que no tenemos nada que ganar? ¿Tus sueños no se ven invadidos por miles de gritos agónicos?' WHERE `ID`=66743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁이 끝나면 어떻게 될까? 이런 참상을 목도하고도 다시 일상으로 돌아갈 수 있겠는가?', `MaleText_loc4`='战争结束后又会怎么样？在亲眼见证了这些恐怖的场面之后，你还想继续拥有风平浪静的人生么？', `MaleText_loc5`='我們的戰爭結束時會發生什麼事?你想要若無其事地回歸文明生活，遺忘你所曾見過的恐怖?', `MaleText_loc7`='¿Qué sucederá cuando acaben nuestras guerras? ¿Crees que podrás volver a la vida civil sin incidentes, a pesar de los horrores que has presenciado?' WHERE `ID`=66744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 에테리얼의 본심을 모른 채 그들과 교류한다. 우리가 스스로의 몰락을 앞당기고 있는 것은 아닌가?', `MaleText_loc4`='我们公开与虚灵达成了交易，却对它们的真实意图一无所知。我们是不是在给自己准备葬礼？', `MaleText_loc5`='我們毫不顧忌地與以太族來往，對他們真正的企圖一無所知。我們會不會造成了自己的末日?', `MaleText_loc7`='Tratamos con los etéreos abiertamente, sin conocer sus verdaderas intenciones. ¿Podríamos estar ayudándolos a planear nuestra propia destrucción?' WHERE `ID`=66745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에는 아직 언데드가 우글거린다. 우리 고향은 폐허가 되었다. 판다리아에서는 증오와 의심이 피어오른다. 불타는 군단이 다시 우리 해안에 상륙하기라도 한다면 과연 승산이 있을까?', `MaleText_loc4`='北方仍有亡灵肆虐。我们的家乡满目疮痍。潘达利亚四处散发着我们的仇恨与怀疑。当燃烧军团再次踏上我们的海岸时，这个世界还有什么希望？', `MaleText_loc5`='北方仍有不死族肆虐。我們的家園淪為廢墟。潘達利亞滲透著我們的憎恨和猜疑。當燃燒軍團再次降臨我們的世界，一切還有什麼希望?', `MaleText_loc7`='El norte aún apesta a no-muertos. Nuestros hogares yacen en ruinas. Pandaria rezuma de nuestro odio y nuestras dudas. ¿Qué esperanza habrá para este mundo cuando vuelva la Legión Ardiente?' WHERE `ID`=66746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 심장은 어둠으로 가득하다. 이래서야 우리가 끊임없이 제압하려 하는 악마와 다를 게 무엇인가?', `MaleText_loc4`='我们的内心何时变得跟我们竭力压制的巨大邪恶一样充满黑暗？', `MaleText_loc5`='什麼時候，我們的心會像我們不斷試著擊敗的邪惡存在一樣充滿了黑暗?', `MaleText_loc7`='¿Cuándo estarán nuestros corazones tan llenos de oscuridad como el gran mal que tanto nos esforzamos por subyugar?' WHERE `ID`=66747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네게서 증오와 폭력과 의심의 냄새가 난다. 네 영혼은 오랜 고난의 무게에 짓눌려 있다. 왜 파멸에 이를 것이 뻔한 길을 계속 가는가?', `MaleText_loc4`='我能闻到你心中仇恨、暴力和怀疑的气味。你的灵魂承受着毕生苦难的重量。为什么你还要在一条通往毁灭的道路上继续走下去？', `MaleText_loc5`='我可以聞到你的憎恨，你的暴戾、你的疑惑。你的靈魂承擔著一輩子的沉重負荷。你為什麼要繼續走在一條只通往毀滅的道路?', `MaleText_loc7`='Puedo oler tu odio, tu violencia, tus dudas. Tu alma carga con el peso de una vida de sufrimiento. ¿Por qué sigues recorriendo un camino que solo puede conducirte a la ruina?' WHERE `ID`=66748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쪽으로 앉아서 드세요! 푸짐한 식사를 하는 데는 정해진 시간이 없지요!', `MaleText_loc4`='快来坐下吃点东西吧！任何时候都该畅享美餐！', `MaleText_loc5`='過來坐下，吃點東西!隨時隨地都是享用豐盛大餐的好時機!', `MaleText_loc7`='¡Siéntate y come! ¡Nunca es mal momento para una comida casera!' WHERE `ID`=66749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 와서 드세요!', `MaleText_loc4`='快来尝尝！', `MaleText_loc5`='過來嚐嚐!', `MaleText_loc7`='¡Ven aquí!' WHERE `ID`=66750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='따끈한 음식 한 입, 시원한 맥주 한 잔이면 싸우다 생긴 상처도 좀 빨리 낫지 않을까요?', `MaleText_loc4`='一份热腾腾的饭菜，一杯透心凉的啤酒，绝对能让战斗的伤口复原得更快些，对吧？', `MaleText_loc5`='大吃一口再大乾一杯肯定會讓傷口治療得更快，對吧?', `MaleText_loc7`='Seguro que un plato caliente y una pinta fresca ayudan a curar esas heridas de guerra, ¿eh?' WHERE `ID`=66751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 드워프를 내 새 의자에서 쫓아 주면 음식을 공짜로 드리지요!', `MaleText_loc4`='要是你能把这矮子从我的新椅子上赶走，我就免费请你吃一顿！', `MaleText_loc5`='如果你能讓這矮人滾下我的新椅子，我就給你免費的大餐!', `MaleText_loc7`='¡Te daré una comida gratis si consigues echar a este enano de mi silla nueva!' WHERE `ID`=66752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리, 또 다른 용화포가 필요합니다.', `MaleText_loc4`='李，再给我一支龙枪。', `MaleText_loc5`='李，我需要另一把龍槍。', `MaleText_loc7`='Li, necesito otra pistola de dragón.', `FemaleText_loc1`='리, 또 다른 용화포가 필요해요.', `FemaleText_loc4`='李，再给我一支龙枪。', `FemaleText_loc5`='李，我需要另一把龍槍。', `FemaleText_loc7`='Li, necesito otra pistola de dragón.' WHERE `ID`=66753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용화포가 나무에서 자라나는 것 같아요?', `FemaleText_loc4`='你认为这些是长在树上的？', `FemaleText_loc5`='你以為這東西是長在樹上的嗎?', `FemaleText_loc7`='¿Te crees que crecen en los árboles?' WHERE `ID`=66754;
