UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요, $n 님. 저는 기계공학에 소양이 있으신 분께만 경매인으로서 도움을 드리고 있습니다. 안타깝게도 당신은 기계공학에는 문외한이시군요. 가 주십시오.', `MaleText_loc4`='你好，$n。只有精通工程学的人才能使用我的拍卖服务。很遗憾，你不在此列。只好请你离开了。', `MaleText_loc5`='你好啊，$n。我的拍賣服務只提供給對工程學有研究的人。遺憾的是，你並沒有這方面的知識。請離開。', `MaleText_loc7`='Buenos días, $n. Mis servicios como subastador están disponibles para usuarios con habilidad en ingeniería. Por desgracia, tú no tienes. Márchate, por favor.' WHERE `ID`=66772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매의 발톱도 무섭지만, 매의 우아한 날개도 그만큼 무섭지요.', `MaleText_loc4`='鹰隼翱翔时的优美身姿甚是养眼，但其利爪的威力也不可小觑。', `MaleText_loc5`='獵鷹的爪子只和牠飛行時的優雅一樣有用。', `MaleText_loc7`='Las garras de un halcón son valiosas, pero no tanto como la gracia de su vuelo.' WHERE `ID`=66773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설령 무기가 손에서 빠져나가도 걱정하지 마시오. 맨몸으로 어떤 적이든 상대할 수 있다오.', `MaleText_loc4`='即便没有武器在手，也无需害怕。单凭你的身体就足以对抗任何敌人。', `MaleText_loc5`='武器脫手時也不用害怕，你的身體已足以對付任何敵人。', `MaleText_loc7`='Si pierdes tu arma, no temas. Tu cuerpo es herramienta más que suficiente para vencer a cualquier enemigo.' WHERE `ID`=66774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서는 갑주가 곧 피부라오. 갑주를 보호하고 존중하면, 갑주도 우리를 보호하고 존중해 준다오.', `MaleText_loc4`='在战斗中，你的护甲就是你的皮肤。保护它，善待它，它就会以同样的方式回报你。', `MaleText_loc5`='你的護甲就是你戰鬥時的皮膚。保護它，尊重它，它也會對你做一樣的事。', `MaleText_loc7`='En el combate, tu armadura es tu piel. Protégela y hónrala, y ella hará lo mismo por ti.' WHERE `ID`=66775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열정의 불꽃은, 다른 이들의 불씨에도 옮겨 붙는다오.', `MaleText_loc4`='心中熊熊燃烧的激情火焰，也会让他人感同身受。', `MaleText_loc5`='激情之火只能用來點燃他人的火種。', `MaleText_loc7`='Las llamas de la pasión solo sirven para encender el fuego de los demás.' WHERE `ID`=66776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는, 작디작은 말벌이 크디큰 황소보다 더 큰 힘을 발휘한다오.', `MaleText_loc4`='有时，弱不禁风的黄蜂会比力大无穷的公牛更有威力。', `MaleText_loc5`='有時候，脆弱的蜜蜂比強大的野牛更能發揮作用。', `MaleText_loc7`='A veces la frágil avispa es más efectiva que el poderoso toro.' WHERE `ID`=66777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 안 들여보내 준다니, 말이 돼? 다른 사람도 아니고 이 나를 말이야!', `MaleText_loc4`='你能相信他们竟然不放我进去么？在所有人当中偏偏是我？', `MaleText_loc5`='你能相信他們竟然不讓我進去嗎?竟然是我?', `MaleText_loc7`='¿Te puedes creer que no me dejan entrar? ¡A quién y a mí!' WHERE `ID`=66778;
