UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멍청한 녀석은 통 이해를 못 한다오. 부정적인 감정을 무절제하게 표출하고 있단 말이오. 계속 그런 식으로 행동하면 우리 모두가 그 대가를 치르게 될 거요.', `MaleText_loc4`='这个蠢货不明白。他毫无顾忌地放任自己的负面情绪。如果任其发展，我们所有人都会尝到苦果。', `MaleText_loc5`='這傻子不懂。他帶著強烈放棄的負面能量。若繼續下去，我們都得承受嚴重的後果。', `MaleText_loc7`='Este necio no lo entiende. Porta emociones negativas con un abandono temerario. Si sigue así, todos sufriremos las consecuencias.' WHERE `ID`=66782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다렌 늙은이는 답답하기 짝이 없군요. 어떻게 감정 없이 싸울 수가 있겠습니까? 불가능합니다!', `MaleText_loc4`='这个老熊猫人愚蠢至极。我们怎能不带着情绪战斗？那不可能！', `MaleText_loc5`='這個老熊貓人是個傻子。我們要怎麼拋棄情緒去戰鬥?這是不可能的!', `MaleText_loc7`='Ese viejo pandaren no tiene ni idea. ¿Cómo vamos a luchar sin emoción? ¡Es imposible!' WHERE `ID`=66783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분이 우리보다는 이 땅에 대해 더 잘 아십니다. 말을 새겨듣는 게 좋을 겁니다.', `MaleText_loc4`='他比我们更加了解这片土地。也许你该留意他的告诫。', `MaleText_loc5`='他比我們更熟悉這片土地。也許你該聽他的警告。', `MaleText_loc7`='Sabe más sobre esta tierra que nosotros. Quizás deberías escuchar sus advertencias.', `FemaleText_loc1`='이분이 우리보다는 이 땅에 대해 더 잘 아시는걸요. 말을 새겨듣는 게 좋을 거예요.', `FemaleText_loc4`='他比我们更加了解这片土地。也许你该留意他的告诫。', `FemaleText_loc5`='他比我們更熟悉這片土地。也許你該聽他的警告。', `FemaleText_loc7`='Sabe más sobre esta tierra que nosotros. Quizás deberías escuchar sus advertencias.' WHERE `ID`=66784;
