UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 진위들, 조용히 좀 하쇼. 안 그래도 잘 안 낚인단 말요!', `MaleText_loc4`='嘘，锦鱼人。在这儿钓鱼已经够困难了！', `MaleText_loc5`='噓，錦魚人。在這裡釣魚已經夠難了!', `MaleText_loc7`='Shh, jinyu. ¡Ya es bastante difícil pescar!' WHERE `ID`=66804;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음에는 티나하고 같이 와야겠어요. 걔라면 이곳의 식물을 정말 좋아할 거예요!', `FemaleText_loc4`='我下次一定要带上迪娜，她会爱死这些植物的！', `FemaleText_loc5`='下一次，我要邀請蒂娜和我一起來，她會愛死這些植物的!', `FemaleText_loc7`='La próxima vez le pediré a Tina que me acompañe. ¡Le encantarían estas plantas!' WHERE `ID`=66805;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 거스 아저씨의 농담이 절실하네요. 여긴 너무 무서워요!', `FemaleText_loc4`='我现在真想听古大叔讲笑话，这地方太吓人了！', `FemaleText_loc5`='現在的我真想聽谷思叔叔講個笑話，這個地方嚇死人了!', `FemaleText_loc7`='Ahora mismo me vendría bien uno de los chistes del tío Gus, ¡este sitio da miedo!' WHERE `ID`=66806;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 언젠가 탐험가가 되고 싶어요!', `FemaleText_loc4`='将来，我也要成为探险家！', `FemaleText_loc5`='有一天，我想當個探險者!', `FemaleText_loc7`='¡Algún día seré una exploradora!' WHERE `ID`=66808;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트위츠를 한참 못 봤는데, 잘 지내면 좋겠네요!', `FemaleText_loc4`='我已经有段时间没见过提兹了，希望她一切安好！', `FemaleText_loc5`='我有很久沒看到蛻姿了，希望她一切都好!', `FemaleText_loc7`='Hace tiempo que no veo a Pía, espero que esté bien.' WHERE `ID`=66809;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요! 탁자에서 신발 치워요! 그 발도요!', `FemaleText_loc4`='嘿！别把鞋踩在桌子上！还有脚！', `FemaleText_loc5`='嘿!別把鞋子放到桌上!還有腳也是!', `FemaleText_loc7`='¡Oye! ¡Quita los zapatos de la mesa! ¡Y LOS PIES!' WHERE `ID`=66810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언젠가는 골짜기 밖의 세상을 보고 싶지만, 여긴 정말 아름답긴 해요!', `FemaleText_loc4`='要是有一天能离开山谷也是不错的，可这里真是太漂亮了！', `FemaleText_loc5`='如果有一天能離開恆春谷就好了，但這裡真是太漂亮了!', `FemaleText_loc7`='Estaría bien salir del valle algún día, pero es tan bonito...' WHERE `ID`=66811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='간식이라도 가져다 드릴까요?', `FemaleText_loc4`='你要不要吃点什么？', `FemaleText_loc5`='要來點飲料嗎?', `FemaleText_loc7`='¿Quieres algo de picar?' WHERE `ID`=66812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 우리 수면실로 가는 길을 찾는다면 그걸 이용할 수 있을 것이다.', `MaleText_loc4`='要是你能进入我们的睡室，那就自便吧。', `MaleText_loc5`='如果你能找到方法進入我們的睡眠室，你就能使用它們。', `MaleText_loc7`='Si consigues encontrar nuestros dormitorios, puedes utilizarlos.' WHERE `ID`=66813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 쓸모가 있는 한은 머물러도 좋다, 이방인이여.', `MaleText_loc4`='看在你还有用的份上，你可以留下，外来者。', `MaleText_loc5`='只要能派上用場，你就能留在這裡，外來人。', `MaleText_loc7`='Mientras seas útil, puedes quedarte, $gforastero:forastera;.' WHERE `ID`=66814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시바가 너를 살려두도록 허락했다는 것에 놀랐지만, 그 결정에 의문을 품진 않겠다.', `MaleText_loc4`='真没想到卡拉克西瓦竟允许你活着，反正也轮不到我管。', `MaleText_loc5`='我很驚訝卡拉西瓦會允許你活下來，但我並沒有資格去質疑。', `MaleText_loc7`='Me sorprende que los Klaxxi te hayan perdonado la vida, pero no me corresponde cuestionar su decisión.' WHERE `ID`=66815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 우리에게 쓸모 있는 존재일 동안은 편안한 휴식처를 제공해 주겠다.', `MaleText_loc4`='只要你对我们还有用处，我就会为你安排膳宿。', `MaleText_loc5`='我會提供你住宿，只要你對我們有用。', `MaleText_loc7`='Te ofreceré alojamiento mientras nos sigas siendo de ayuda.' WHERE `ID`=66816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 우리 곡식에서 떨어져!', `MaleText_loc4`='你！离我们的庄稼远点儿！', `MaleText_loc5`='你!別靠近我們的作物!', `MaleText_loc7`='¡Tú! ¡Aléjate de nuestros cultivos!' WHERE `ID`=66817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하하하!', `MaleText_loc4`='哈哈哈哈哈！', `MaleText_loc5`='哈哈哈哈哈哈!', `MaleText_loc7`='¡Ja, ja, ja!' WHERE `ID`=66818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼굴을 긁어버릴 거야!', `MaleText_loc4`='吃我一耙！', `MaleText_loc5`='給你吃一耙子!', `MaleText_loc7`='¡Rastrillo en la cara!' WHERE `ID`=66819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이이이잇!', `MaleText_loc4`='啊呀！', `MaleText_loc5`='啊啊咿咿咿咿!', `MaleText_loc7`='¡AYYYYY!' WHERE `ID`=66820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='토깽이 최고야! 넌 나빠!', `MaleText_loc4`='我们种得更好！你这讨厌鬼！', `MaleText_loc5`='我們長得更好!你壞!', `MaleText_loc7`='¡Nosotros nos volvemos mejores! ¡Tú, peor!' WHERE `ID`=66821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 난폭해!', `MaleText_loc4`='我们可不好惹！', `MaleText_loc5`='我們撒野大鬧!', `MaleText_loc7`='¡Peleamos!' WHERE `ID`=66822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"그렇게 빛나는 칼날은 판다리아에 왔다가 떠났다. 마지막으로 어디로 향했는지는 아무도 모른다."$B$B우리 민족의 전승은 수많은 이야기가 얽혀 이루어진 것이네. 고서가 영원히 보존되도록 제본하는 게 나의 일이지.', `MaleText_loc4`='“闪光之刃就是这么来到了潘达利亚，而后又离开，从此下落不明。”$B$B在我们的人民间充满了精彩丰富的传说故事。我要做的就是将它们收集起来，使其能千秋万代地流传下去。', `MaleText_loc5`='「那就是閃亮之劍來到又離開潘達利亞的經過，沒有人知道它的最終目的地。」$B$B我們人民的傳說是無數故事交織而成的。我的工作就是裝訂這些書冊，讓它們可以千世流傳。', `MaleText_loc7`='"Y así es como la hoja resplandeciente vino a Pandaria y se marchó, sin que sepamos su destino final".$b$bEl saber de nuestra gente está repleto de historias. Mi trabajo es encuadernar los libros de forma que duren mil vidas.' WHERE `ID`=66823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이제 겨우 발견하기 시작한 고대 세계에 대한 지식이 이곳에 다 있군!', `MaleText_loc4`='在这里贮存着关于这个古老世界浩如烟海的广博知识，而我们才刚刚开始知晓而已！', `MaleText_loc5`='我們才剛開始發掘這塊地方，想不到居然埋藏了這麼多關於古老世界的知識!', `MaleText_loc7`='Aquí hay almacenado muchísimo saber del mundo antiguo que acabamos de empezar a descubrir...' WHERE `ID`=66824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대 테라모어에서 살아나가지 못할 거다!', `MaleText_loc4`='你休想活着离开塞拉摩！', `MaleText_loc5`='你絕對無法活著離開塞拉摩!', `MaleText_loc7`='¡Nunca saldrán de Theramore con vida!' WHERE `ID`=66826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네에게 두 배의 행운이 깃들기를, $r.$B$B행운의 부적을 찾고 있다면 내가 도와줄 수 있네.', `FemaleText_loc4`='祝你好运连连，$r。$B$B如果你在找好运符，我马上就能让你如愿以偿。', `FemaleText_loc5`='祝你加倍好運，$r。$B$B如果你在找幸運物，我正好可以幫助你。', `FemaleText_loc7`='Doble fortuna, $r.$b$bSi buscas un talismán de la suerte, puedo conseguirte uno en un periquete.' WHERE `ID`=66827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 두 배의 행운이 깃들기를, $r.$B$B행운의 부적을 찾고 있다면 내가 도와줄 수 있네.', `MaleText_loc4`='祝你好运连连，$r。$B$B如果你在找好运符，我马上就能让你如愿以偿。', `MaleText_loc5`='祝你加倍好運，$r。$B$B如果你在找幸運物，我正好可以幫助你。', `MaleText_loc7`='Doble fortuna, $r.$b$bSi buscas un talismán de la suerte, puedo conseguirte uno en un periquete.' WHERE `ID`=66828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고양이가 있는데 친구가 왜 필요해?', `FemaleText_loc4`='有猫相伴，谁还需要朋友？', `FemaleText_loc5`='有了貓，誰還需要朋友?', `FemaleText_loc7`='¿Quién necesita amigos cuando se tienen gatos?' WHERE `ID`=66829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 저 바다와 같은 감사를 드립니다! 이제 저 혼자 스리라 마을로 돌아가겠습니다.', `MaleText_loc4`='感谢大海，陌生人！我能自己返回香里拉村了。', `MaleText_loc5`='多謝大海，陌生人!我可以自己回去斯里拉了。', `MaleText_loc7`='¡Gracias al mar, $gforastero:forastera;! Puedo volver solo a la Aldea Sri-La.', `FemaleText_loc1`='이방인이여, 저 바다와 같은 감사를 드릴게요! 이제 저 혼자 스리라 마을로 돌아가겠어요.', `FemaleText_loc4`='感谢大海，陌生人！我能自己返回香里拉村了。', `FemaleText_loc5`='多謝大海，陌生人!我可以自己回去斯里拉了。', `FemaleText_loc7`='¡Gracias al mar, $gforastero:forastera;! Puedo volver sola a la Aldea Sri-La.' WHERE `ID`=66830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해안에서 낚시를 하다가 거미의 공격을 받았습니다! 이렇게 구해주시다니, 정말 감사합니다.', `MaleText_loc4`='我当时正在岸边钓鱼，突然就遭到了蜘蛛的袭击！多谢你救了我。', `MaleText_loc5`='蜘蛛抓到我時，我正在海岸邊釣魚!謝謝你救了我。', `MaleText_loc7`='¡Estaba pescando en la orilla cuando me atraparon las arañas! Gracias por salvarme.', `FemaleText_loc1`='해안에서 낚시를 하다가 거미의 공격을 받았어요! 이렇게 구해주시다니, 정말 고마워요.', `FemaleText_loc4`='我当时正在岸边钓鱼，突然就遭到了蜘蛛的袭击！多谢你救了我。', `FemaleText_loc5`='蜘蛛抓到我時，我正在海岸邊釣魚!謝謝你救了我。', `FemaleText_loc7`='¡Estaba pescando en la orilla cuando me atraparon las arañas! Gracias por salvarme.' WHERE `ID`=66831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡단이 당신을 보냈습니까? 축복해야 할 일이군요. 다른 이들도 도와주십시오!', `MaleText_loc4`='是云端翔龙骑士团派你来的吗？祝福他们。请帮帮其他人吧！', `MaleText_loc5`='雲蛟衛派你來的嗎?祝福他們。請幫助其他人!', `MaleText_loc7`='¿Te ha enviado la Orden del Dragón Nimbo? Benditos sean. ¡Ayuda a los demás!', `FemaleText_loc1`='운룡단이 당신을 보냈나요? 축복해야 할 일이네요. 다른 이들도 도와주세요!', `FemaleText_loc4`='是云端翔龙骑士团派你来的吗？祝福他们。请帮帮其他人吧！', `FemaleText_loc5`='雲蛟衛派你來的嗎?祝福他們。請幫助其他人!', `FemaleText_loc7`='¿Te ha enviado la Orden del Dragón Nimbo? Benditos sean. ¡Ayuda a los demás!' WHERE `ID`=66832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 희생자들이... 정말 끔찍한 소리를 내더군요. 구하러 와주셔서 감사합니다!', `MaleText_loc4`='其他受害者……他们的声音惨不忍闻。多谢你救了我！', `MaleText_loc5`='其他受害者...他們發出這麼可怕的聲音。謝謝你來救我!', `MaleText_loc7`='Las demás víctimas... Hacían unos ruidos horribles. ¡Gracias por venir a rescatarme!', `FemaleText_loc1`='다른 희생자들이... 정말 끔찍한 소리를 내더군요. 이렇게 와주셔서 정말 고마워요!', `FemaleText_loc4`='其他受害者……他们的声音惨不忍闻。多谢你救了我！', `FemaleText_loc5`='其他受害者...他們發出這麼可怕的聲音。謝謝你來救我!', `FemaleText_loc7`='Las demás víctimas... Hacían unos ruidos horribles. ¡Gracias por venir a rescatarme!' WHERE `ID`=66833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 게 끝이라고 생각했는데... 당신과 운룡단에 감사합니다. 이제 혼자서 탈출하겠습니다.', `MaleText_loc4`='我以为自己死定了。谢谢你，也谢谢骑士团。我能自己离开这里了。', `MaleText_loc5`='我以為我完蛋了。謝謝你，謝謝雲蛟衛。我可以自己離開了。', `MaleText_loc7`='Creía que había llegado mi hora. Os doy las gracias a ti y a la Orden. Ya puedo salir por mi cuenta.', `FemaleText_loc1`='모든 게 끝이라고 생각했는데... 당신과 운룡단에 감사드려요. 이제 혼자서 탈출할게요.', `FemaleText_loc4`='我以为自己死定了。谢谢你，也谢谢骑士团。我能自己离开这里了。', `FemaleText_loc5`='我以為我完蛋了。謝謝你，謝謝雲蛟衛。我可以自己離開了。', `FemaleText_loc7`='Creía que había llegado mi hora. Os doy las gracias a ti y a la Orden. Ya puedo salir por mi cuenta.' WHERE `ID`=66834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 한때는 밭일을 했지만, 오래전 얘기지. 나는 싸우는 편이 더 좋네. 자넨 안 그런가?', `MaleText_loc4`='我曾经有个农场，但那是在很久之前了。我想要痛快地大战一场，你呢？', `MaleText_loc5`='我曾經擁有一座農場。但那已經是好久以前的事了。我寧願享受一場好的戰鬥，你覺得呢?', `MaleText_loc7`='Antes tenía una granja, pero fue hace mucho tiempo. Prefiero un buen duelo. ¿Tú no?' WHERE `ID`=66835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='토끼를 두 마리만 잡았는데, 이젠 너무 많아졌어요!', `FemaleText_loc4`='我原本只逮到了两只兔子。可现在却有这么多！', `FemaleText_loc5`='我本來只抓到兩隻兔子。現在我有一大堆!', `FemaleText_loc7`='Solo atrapé dos conejos, ¡y ahora tengo un montón!' WHERE `ID`=66836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스톰윈드로 데려가주십시오.', `MaleText_loc4`='带我去暴风城。', `MaleText_loc5`='帶我去暴風城。', `MaleText_loc7`='Llévame a Ventormenta.', `FemaleText_loc1`='스톰윈드로 데려가주세요.', `FemaleText_loc4`='带我去暴风城。', `FemaleText_loc5`='帶我去暴風城。', `FemaleText_loc7`='Llévame a Ventormenta.' WHERE `ID`=66837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 데려가주십시오.', `MaleText_loc4`='带我去奥格瑞玛。', `MaleText_loc5`='帶我去奧格瑪。', `MaleText_loc7`='Llévame a Orgrimmar.', `FemaleText_loc1`='오그리마로 데려가주세요.', `FemaleText_loc4`='带我去奥格瑞玛。', `FemaleText_loc5`='帶我去奧格瑪。', `FemaleText_loc7`='Llévame a Orgrimmar.' WHERE `ID`=66838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줄 분이 올 거라고는 생각도 못했습니다. 제게 새로운 희망을 주셨습니다, 이방인이여.', `MaleText_loc4`='我没想到还会有人来帮忙。你给我了新的希望，陌生人。', `MaleText_loc5`='我本來不覺得會有人來救援了。你給了我新希望，陌生人。', `MaleText_loc7`='No pensaba que recibiríamos ayuda. Me has dado esperanzas, $gforastero:forastera;.', `FemaleText_loc1`='도와줄 분이 올 거라고는 생각도 못했어요. 제게 새로운 희망을 주셨군요, 이방인이여.', `FemaleText_loc4`='我没想到还会有人来帮忙。你给我了新的希望，陌生人。', `FemaleText_loc5`='我本來不覺得會有人來救援了。你給了我新希望，陌生人。', `FemaleText_loc7`='No pensaba que recibiríamos ayuda. Me has dado esperanzas, $gforastero:forastera;.' WHERE `ID`=66839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미줄에 갇혀 있는 동안, 의심과 절망이라는 감정에 사로잡혀야 했습니다. 당신은 제 내면의 공포로부터 절 구해주신 겁니다.', `MaleText_loc4`='当我被困在网中时，我心中充满了怀疑与绝望。是你把我从自己的恐惧中解救了出来。', `MaleText_loc5`='當我被困在網中時，我感到這麼的疑惑和絕望。你將我從我自己的恐懼中拯救出來。', `MaleText_loc7`='Cuando estaba atrapado en esa telaraña, tenía una sensación de duda y desesperación. Me has liberado de mis propios temores.', `FemaleText_loc1`='거미줄에 갇혀 있는 동안, 의심과 절망이라는 감정에 사로잡혀야 했어요. 당신은 제 내면의 공포로부터 절 구해주신 거예요.', `FemaleText_loc4`='当我被困在网中时，我心中充满了怀疑与绝望。是你把我从自己的恐惧中解救了出来。', `FemaleText_loc5`='當我被困在網中時，我感到這麼的疑惑和絕望。你將我從我自己的恐懼中拯救出來。', `FemaleText_loc7`='Cuando estaba atrapada en esa telaraña, tenía una sensación de duda y desesperación. Me has liberado de mis propios temores.' WHERE `ID`=66840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 도와주러 오지 않을 거라고 생각하고 있었습니다. 모두가 절 잊어버린 줄 알았습니다. 당신을 보내주다니, 운룡단에 정말 감사합니다.', `MaleText_loc4`='我开始害怕，担心自己不会得救了。自己被所有人遗忘了。感谢骑士团派你来救我！', `MaleText_loc5`='我開始害怕沒有人來救援。害怕每個人都忘了我。多虧雲蛟營派你過來!', `MaleText_loc7`='Empezaba a temer que no vendría nadie. Que todo el mundo se había olvidado de mí. ¡Agradezco a la Orden que te hayan enviado!', `FemaleText_loc1`='아무도 도와주러 오지 않을 거라고 생각하고 있었어요. 모두가 절 잊어버린 줄 알았거든요. 당신을 보내주다니, 운룡단에 정말 고맙네요.', `FemaleText_loc4`='我开始害怕，担心自己不会得救了。自己被所有人遗忘了。感谢骑士团派你来救我！', `FemaleText_loc5`='我開始害怕沒有人來救援。害怕每個人都忘了我。多虧雲蛟營派你過來!', `FemaleText_loc7`='Empezaba a temer que no vendría nadie. Que todo el mundo se había olvidado de mí. ¡Agradezco a la Orden que te hayan enviado!' WHERE `ID`=66841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미를 무서워하나? 어떤 이들은 끝없이 울창한 숲을 헤맬 때 그 거미들이 몸속으로 기어오르는 걸 느끼곤 하지.', `MaleText_loc4`='你怕蜘蛛吗？据某些在这片无尽森林中往来的旅者说，他们老觉得身上有蜘蛛在爬。', `MaleText_loc5`='你害怕蜘蛛嗎?有些人在茂密的樹林中遊蕩時，會感覺到牠們在自己的皮膚上爬行。', `MaleText_loc7`='¿Te dan miedo las arañas? Hay quien las siente recorriendo su piel mientras caminan por el bosque infinito...' WHERE `ID`=66842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 술 좀 없나?... *딸꾹* 도대체 술이라고는 하나도 찾을 수가 없군!', `MaleText_loc4`='你看见朗姆酒了吗？……嗝儿！我到处都找遍了！', `MaleText_loc5`='你有刊到偶們的蘭姆酒嗎...嗝!我好像到粗都找不到它!', `MaleText_loc7`='¿Hash vishto el ron? ... ¡hic! ¡No lo encuentro pol ninguna palte!' WHERE `ID`=66843;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드는 대가를 치를 겁니다. 제가 이... 흉물에서 집중의 눈동자를 되찾으면... 가로쉬는 진정한 파괴를 보게 될 거예요. 오그리마는... 가라앉을 겁니다.', `FemaleText_loc4`='部落要为自己在这里犯下的恶行付出代价。$B$B等我从这……怪物身上拿到聚焦之虹……加尔鲁什就会明白毁灭的真正含义。$B$B奥格瑞玛……必将覆灭。', `FemaleText_loc5`='部落會為了在這裡做的事付出代價。$B$B等我從這...怪物手上拿回聚源虹膜...卡爾洛斯會知道毀滅的真正含意。$B$B奧格瑪將被淹沒。', `FemaleText_loc7`='La Horda pagará por los estragos que ha causado aquí. En cuanto le arrebate el Iris de enfoque a esta... abominación... Garrosh comprenderá el verdadero significado de la destrucción. Orgrimmar... CAERÁ.' WHERE `ID`=66844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 한때는 밭일을 했지만, 오래전 얘기지. 나는 싸우는 편이 좋네. 자넨 안 그런가?', `MaleText_loc4`='我曾经有个农场，但那是在很久之前了。我想要痛快地大战一场，你呢？', `MaleText_loc5`='我曾經擁有一座農場。但那已經是好久以前的事了。我寧願享受一場好的戰鬥，你覺得呢?', `MaleText_loc7`='Antes tenía una granja, pero fue hace mucho tiempo. Prefiero un buen duelo. ¿Tú no?' WHERE `ID`=66845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그동안 우리는 폐허에 있는 호드를 처리하겠습니다.', `MaleText_loc4`='在你工作的同时，我们会把部落从废墟里赶出去。', `MaleText_loc5`='我們會在你工作時清除廢墟中的部落。', `MaleText_loc7`='Despejaremos las ruinas de miembros de la Horda mientras trabajas.', `FemaleText_loc1`='그동안 우리는 폐허에 있는 호드를 처리할게요.', `FemaleText_loc4`='在你工作的同时，我们会把部落从废墟里赶出去。', `FemaleText_loc5`='我們會在你工作時清除廢墟中的部落。', `FemaleText_loc7`='Despejaremos las ruinas de miembros de la Horda mientras trabajas.' WHERE `ID`=66846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거미를 무서워하나? 어떤 이들은 끝없이 울창한 숲을 헤맬 때 그 거미들이 몸속으로 기어오르는 걸 느끼곤 하지.', `MaleText_loc4`='你怕蜘蛛吗？据某些在这片无尽森林中往来的旅者说，他们老觉得身上有蜘蛛在爬。', `MaleText_loc5`='你怕蜘蛛嗎?有些人在一望無際的樹林中遊走時，可以感覺到牠們爬過身上的皮膚。', `MaleText_loc7`='¿Te dan miedo las arañas? Hay quien las siente recorriendo su piel mientras caminan por el bosque infinito...' WHERE `ID`=66847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진심으로 감사드려요. 집중의 눈동자를 제거했으니, 이 폭탄은 이제 가로쉬의 잔인성을 보여주는 증거, 그 이상은 아니에요. 변화의 바람이 불고 있어요. 아제로스는 전쟁의 문턱에 있고요. 죄송하지만 가야겠군요... 생각할 게 많거든요. 그럼, 안녕히.', `FemaleText_loc4`='请接受我最诚挚的谢意。聚焦之虹已被移除，这个失去能量的炸弹现在只是加尔鲁什暴行的邪恶佐证。变幻之风猛烈刮过，艾泽拉斯处在战争的边缘。抱歉，请你们原谅我……我总是有许多顾虑。再见。', `FemaleText_loc5`='你們都擁有我最深的謝意。在聚源虹膜被移除後，這顆沒有生命的炸彈不過是卡爾洛斯殘暴的噁心象徵。變動的風正強烈的吹著，艾澤拉斯正在戰爭邊緣。很抱歉，我必須離開...有太多需要思考了。再見了。', `FemaleText_loc7`='Cuenten todos con mi más sincero agradecimiento. Sin el Iris de enfoque, esta bomba inerte no es más que otro testimonio atroz de la brutalidad de Garrosh. Los vientos de cambio soplan con fuerza; la guerra se cierne sobre Azeroth. Discúlpenme, pero debo dejarlos... Tengo mucho en que pensar. Adiós.' WHERE `ID`=66848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕히...', `FemaleText_loc4`='再见……', `FemaleText_loc5`='再見...', `FemaleText_loc7`='Adiós...' WHERE `ID`=66849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역사가의 일에는 끝이 없습니다. 늘 기억해야 하는 중요한 일이 일어나고 있기 때문이지요.$B$B마침, 당신네 사람들이 이곳에 오게 된 연고를 조사하기 시작한 참입니다. 이름을 알려 주시겠어요? 후세가 당신의 이야기를 알 수 있도록이요.', `FemaleText_loc4`='你瞧，历史学家的工作是永远也干不完的。那些需要我们铭记的重要事件总是层出不穷。$B$B我已经开始收集你们的人来到这片土地的相关史料。你叫什么来着？我得把它记下来，好让我们的子孙后代能读到你的故事，了解你的传说。', `FemaleText_loc5`='歷史學家的工作永遠沒有結束的時候。隨時都會發生重要的事情，等待我們去記錄。$B$B我正開始收集你們人民來到這裡的歷史。告訴我你的名字，好讓世世代代的後人都能讀到你的故事。', `FemaleText_loc7`='El trabajo de una historiadora no termina nunca, ¿sabes? Siempre está sucediendo algo importante que debemos recordar.$b$bHe empezado a registrar la historia de la llegada de tu gente. ¿Cómo te llamas, para que las generaciones futuras lean tu historia y conozcan tus hazañas?' WHERE `ID`=66850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 이름은...', `MaleText_loc4`='我的名字是……', `MaleText_loc5`='我的名字是...', `MaleText_loc7`='Me llamo...', `FemaleText_loc1`='제 이름은...', `FemaleText_loc4`='我的名字是……', `FemaleText_loc5`='我的名字是...', `FemaleText_loc7`='Me llamo...' WHERE `ID`=66851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그랬군요. 당신의 업적에 대한 이야기는 익히 들었습니다, $N 님. 당신이 오래 기억되도록, 당신에 대한 이야기를 쓰겠습니다. 약속하지요.', `FemaleText_loc4`='哦，原来就是你啊。我听说过你的事迹，$N。我一定会把你的故事写下来，让你名留青史，我说到做到。', `FemaleText_loc5`='啊，所以這就是你的身分。我已經聽說過你的事蹟，$N。我向你保證，我會把你的故事寫下來，讓你名留千古。', `FemaleText_loc7`='Ah, ya sé quién eres. He oído historias de tus aventuras, $n. Escribiré relatos sobre ti para que te recuerden para siempre, te lo prometo.' WHERE `ID`=66852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젠지! 이분은 $n 님이잖은가! 최근에 이분이 무슨 일을 하셨는지 못 들었는가? 우리 민족을 위해 정말 많은 일을 해 주셨단 말이네.', `MaleText_loc4`='简宁！这就是$n。你最近也听过$g他的:她的;事迹了吧？$G他:她;为我们的人民做了许多事。', `MaleText_loc5`='珍姬!這位就是$n。你最近沒聽說過$g他:她;的事蹟嗎?$g他:她;為我們的人民做了很多事。', `MaleText_loc7`='¡Jenji! $gEste:Esta; es $n, evidentemente. ¿No has oído hablar de sus últimas hazañas? Ha hecho mucho por nuestro pueblo.' WHERE `ID`=66853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송합니다, 조언자님. 미처 못 알아봤네요!', `FemaleText_loc4`='很抱歉，建言者。我没能认出$G他:她;来！', `FemaleText_loc5`='很抱歉，顧問先生。我沒認出$g他:她;來。', `FemaleText_loc7`='Disculpa, consejero. ¡No $glo:la; había reconocido!' WHERE `ID`=66854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당장 당신의 모험담을 써야겠어요!', `FemaleText_loc4`='我现在就开始动笔写你的冒险故事！', `FemaleText_loc5`='我會立刻記錄下你的冒險!', `FemaleText_loc7`='¡Me pondré a escribir tus aventuras ahora mismo!' WHERE `ID`=66855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초토화 단계 전환 시작. 안녕히.', `MaleText_loc4`='进入彻底毁灭程序。再见。', `MaleText_loc5`='啟動完全毀滅程序，再見。', `MaleText_loc7`='Activando secuencia de destrucción total. Adiós.' WHERE `ID`=66856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은, 말 없는 메뚜기가 발길질을 피하는 법을 가장 잘 알지요.', `MaleText_loc4`='俗话说得好，树大易招风，菇小可避雨。', `MaleText_loc5`='沉默的蚱蜢經常知道怎麼逃避靴子。', `MaleText_loc7`='A menudo el saltamontes silencioso es el que mejor sabe cómo evitar la bota.' WHERE `ID`=66857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물고기가 나무에 오르지 못한다 해서 책잡으면, 그 물고기는 평생을 제가 못났다고 생각하며 살게 되지요.', `MaleText_loc4`='尺有所长，寸有所短。量才器使，知人善用。', `MaleText_loc5`='如果你用爬樹的能力來評判一條魚，牠的一生將在自以為無能中度過。', `MaleText_loc7`='Si juzgas a un pez por su capacidad para trepar por los árboles, se pasará la vida pensando que es indigno.' WHERE `ID`=66858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일찍 일어나는 새는 벌레를 잡고, 참을성 있는 판다렌은 맛있는 맥주를 받지요.', `MaleText_loc4`='早起的鸟儿有虫吃，但耐心的熊猫人才有美酒喝。', `MaleText_loc5`='早起的鳥兒有蟲吃，但耐心的熊貓人有酒喝。', `MaleText_loc7`='Los pandaren saben que no por mucho madrugar amanece más temprano.' WHERE `ID`=66859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭력은 당장에는 이로운 것 같을지 모르나, 그로 인한 해악은 영원히 사라지지 않습니다.', `MaleText_loc4`='暴力虽能逞一时之快，但所造恶业永难消除。', `MaleText_loc5`='暴力或許在短時間內看起來有益，但它所留下的邪惡影響將永遠留存。', `MaleText_loc7`='La violencia puede parecer efectiva durante un tiempo, pero el mal que engendra permanece para siempre.' WHERE `ID`=66860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오를 이기는 것은 사랑뿐입니다.', `MaleText_loc4`='以德报怨，以爱消恨。', `MaleText_loc5`='只有愛能驅散憎恨。', `MaleText_loc7`='Solo el amor puede expulsar al odio.' WHERE `ID`=66861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지혜를 전수해 주십시오, 조언자님.', `MaleText_loc4`='与我分享你的智慧吧，建言者。', `MaleText_loc5`='請賦予我你的智慧，諫言者。', `MaleText_loc7`='Transmíteme tu sabiduría, consejero.', `FemaleText_loc1`='지혜를 전수해 주세요, 조언자님.', `FemaleText_loc4`='与我分享你的智慧吧，建言者。', `FemaleText_loc5`='請賦予我你的智慧，諫言者。', `FemaleText_loc7`='Transmíteme tu sabiduría, consejero.' WHERE `ID`=66862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청소하는 중', `MaleText_loc4`='清理中', `MaleText_loc5`='清理中', `MaleText_loc7`='Limpiando', `FemaleText_loc1`='청소하는 중', `FemaleText_loc4`='清理中', `FemaleText_loc5`='清理中', `FemaleText_loc7`='Limpiando' WHERE `ID`=66863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 이들이 모르지만, 나도 한때는 투사였다. 호드의 재미를 위해 싸우는 검투사였지. 그래서 나도 싸우는 법에 대해서는 제법 아는 편이다.', `MaleText_loc4`='很多人都不知道我曾经当过角斗士，专门取悦部落那些野兽们。所以我也多少懂一点武术。', `MaleText_loc5`='很多人不知道，但我曾經也是個戰士，一名為部落提供消遣的角鬥士，所以關於實戰我也略知一二。', `MaleText_loc7`='Poca gente lo sabe, pero una vez fui un luchador de arena. Un gladiador, para regocijo de la Horda. Sé un par de cosas sobre las artes marciales.' WHERE `ID`=66865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼애애애! 소중한 장화가!', `MaleText_loc4`='不！！我的宝贝鞋子！', `MaleText_loc5`='不!!寶貝鞋子!', `MaleText_loc7`='¡Nooooo! ¡Zapatos bonitos!' WHERE `ID`=66866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져, 이 장화 도둑아!', `MaleText_loc4`='滚开，偷鞋贼！', `MaleText_loc5`='滾開，偷鞋賊!', `MaleText_loc7`='¡Fuera, robazapatos!' WHERE `ID`=66867;
