UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 오늘 함께할 수가 없습니다. 곧 있을 잔치를 위해서 생선을 준비해야 하거든요!', `FemaleText_loc4`='我今天不能加入你们了，朋友们。宴会在即，我得把鱼准备好！', `FemaleText_loc5`='我今天無法和你一起去，朋友。我必須為了即將到來的宴席準備我的魚!', `FemaleText_loc7`='Hoy no puedo ir con ustedes, amigos. ¡Tengo que preparar el pescado para el festín!' WHERE `ID`=66875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모그레인...', `FemaleText_loc4`='莫格莱尼……', `FemaleText_loc5`='莫格萊尼...', `FemaleText_loc7`='Mograine...' WHERE `ID`=66876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원꽃 골짜기를 지키는 데 도움을 주신 여러분을 위한 감사의 표시로 황금 연꽃이 잔칫상을 마련했으니, 마음껏 즐겨 주세요.', `FemaleText_loc4`='为了答谢你们为保护锦绣谷所做的贡献，金莲教将举办一场盛大的宴会。请你务必要来参加。', `FemaleText_loc5`='拜託，參加金蓮所擺設的流水席，用來感謝你們幫忙保護恆春谷的功勞。', `FemaleText_loc7`='Adelante, participa en el bufé que ha preparado el Loto Dorado como agradecimiento a tu gente por ayudarnos a proteger el Valle de la Flor Eterna.' WHERE `ID`=66877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $r님.$B$B저는 이곳 판다리아에서 자라난 어린 묘목입니다. 판다리아와 하나가 되어 티란데 님께서 이곳에 숨겨진 이야기를 아실 수 있도록 하기 위해서지요. 여군주님의 소망을 실현하기 위해, 여기 스트롱보우 형제가 저를 다 자랄 때까지 지키겠다고 자원했습니다.', `MaleText_loc4`='欢迎你，$r。$B$B我还只是一棵小树苗，我将在潘达利亚扎根，与这片土地融为一体。这样，泰兰德才能从它蕴藏的故事中受益。为了达成她的心愿，强弓家族自愿留下来保护我渡过幼年期。', `MaleText_loc5`='歡迎，$r。$B$B我不過是個年輕的小樹苗，到這裡成長為潘達利亞的一部分，讓泰蘭妲可以從這裡所流傳的故事中獲益。強弓們自願保衛年幼的我，好讓我們的女主人如願以償。', `MaleText_loc7`='Saludos, $r.$b$bSolo soy un joven esqueje que ha crecido en Pandaria para ser uno con la tierra. Así, Tyrande podrá beneficiarse de las historias que conoce. Los Arcofuerte se han ofrecido a protegerme durante mi infancia, para que podamos cumplir los deseos de nuestra señora.' WHERE `ID`=66878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 새끼 운룡들은 이곳에서 안전하게 보호하겠습니다.', `MaleText_loc4`='别担心，雏龙在这里会很安全的。', `MaleText_loc5`='別擔心，蛟寶寶在這裡相當安全。', `MaleText_loc7`='No te preocupes. Las proles están a salvo.' WHERE `ID`=66879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 몇 년 동안 수많은 수련생들을 만나봤지만, 당신은 뭔가 다르군요.', `MaleText_loc4`='这些年来，我见过不少弟子，但你似乎有些与众不同。', `MaleText_loc5`='這些年來我看過許多弟子，但你有些不同。', `MaleText_loc7`='He visto a muchos estudiantes a lo largo de los años, pero tú tienes algo diferente.' WHERE `ID`=66880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신입 단원이라고? 아, 좋아, 아주 좋아. 혹시 안리 장로님과는 얘기해 봤습니까?', `MaleText_loc4`='一个新弟子？啊，不错，很好。你和安离长老谈过了吗？', `MaleText_loc5`='新弟子?$B$B啊是的，很好。你和安麗長老說過話了嗎?', `MaleText_loc7`='¿$gUn nuevo:Una nueva; estudiante? Ah, sí, muy bien. ¿Has hablado con la ancestro Anli?' WHERE `ID`=66881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡에게 항상 친절하고 존중하는 태도를 보인다면, 운룡도 당신을 신뢰할 겁니다.', `MaleText_loc4`='对你的翔龙表现出你的善意和尊重，它就会慢慢信赖你。', `MaleText_loc5`='用溫柔和尊重來養育你的雲蛟，牠就會越來越信任你。', `MaleText_loc7`='Trata a tu dragón nimbo con amabilidad y respeto, y acabará confiando en ti.' WHERE `ID`=66882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='긴 여행을 할 때는, 한 번에 한 발씩 걷는 것이 좋지.', `FemaleText_loc4`='不积跬步，无以至千里。', `FemaleText_loc5`='千里之行，始於足下。', `FemaleText_loc7`='Lo mejor es recorrer los largos viajes paso a paso.' WHERE `ID`=66883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 수련생들을 모두 지켜보는 걸 좋아한다네. 자네가 수련하는 모습도 언제나 지켜보겠네.', `FemaleText_loc4`='我会密切注意所有的弟子。我非常渴望看到你的进步。', `FemaleText_loc5`='我喜歡關注我所有的學生。我會熱切地觀察你的進展。', `FemaleText_loc7`='Me gusta seguir el progreso de todos nuestros estudiantes. Observaré el tuyo con interés.' WHERE `ID`=66884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야생 운룡은 새끼를 낳는 일이 매우 드물기 때문에, 그 알은 상상할 수 없을 만큼 귀하지.$B$B우리가 이렇게 야생 운룡들을 보호하고 돕지 않는다면, 머지않아 모두 사라지고 말 거야.', `FemaleText_loc4`='野生云端翔龙的生育率非常低。所以，每一枚翔龙蛋都是极其珍贵的。$B$B如果我们不努力保护野生云端翔龙，它们或许就会彻底绝种。', `FemaleText_loc5`='野生雲蛟很少繁殖，也因此，每顆蛋都是極度珍貴。$B$B如果我們不努力幫忙和保護野生雲蛟，牠們有一天可能會消失。', `FemaleText_loc7`='Los dragones nimbo salvajes se reproducen muy raramente; por ello, cada huevo es extremadamente valioso.$b$bSi no nos esforzamos en ayudar y proteger a los dragones nimbo salvajes, es posible que algún día se extingan.' WHERE `ID`=66885;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야생 운룡 중에서도 마노 운룡은 정말 희귀한 존재라네. 눈에 잘 띄지 않는 이 검은 운룡들은 북동쪽에 있는 바람맞이 섬에 알을 낳는다고 알려져 있어.$B$B혹시 마노 알을 발견하거든, 즉시 내게 가져오게. 두둑히 보상해 주겠네.', `FemaleText_loc4`='在所有的野生翔龙中，玛瑙翔龙是最稀有的。据悉，这些难得一见的黑色云端翔龙会在东北边的临风岛上产卵。$B$B如果你在那里发现任何玛瑙翔龙蛋，请把它们带来给我。我会好好奖赏你的。', `FemaleText_loc5`='在所有野生雲蛟中，瑪瑙蛟是為稀有的。這些神出鬼沒的黑色雲蛟最常在東北方的嘯風島上下蛋。$B$B如果你找到任何瑪瑙蛟蛋，請帶來給我。我會慷慨地報答你。', `FemaleText_loc7`='De todos los dragones salvajes, el de ónice es el menos común. Se sabe que esos esquivos dragones nimbo negros ponen sus huevos en la Isla de Barlovento, al noreste.$b$bSi encuentras huevos de ónice, tráemelos. Te recompensaré generosamente.' WHERE `ID`=66886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날을 따라올 수 있겠느냐?', `MaleText_loc4`='你能抵御我的刀法？', `MaleText_loc5`='你能跟得上我的刀法嗎?', `MaleText_loc7`='¿Pueden seguir mi acero?' WHERE `ID`=66887;
