UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 샨쩌의 뜻을 거스르려 하느냐!', `MaleText_loc4`='你竟敢反抗山泽部族？！', `MaleText_loc5`='你敢與衫織為敵?!', `MaleText_loc7`='¿Te atreves a airar a los Shan''ze?' WHERE `ID`=66889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안식을 취하지 못하는 영혼이 또 있군...', `MaleText_loc4`='又一个不安的灵魂……', `MaleText_loc5`='又一個無法安息的魂靈...', `MaleText_loc7`='Otro espíritu inquieto...' WHERE `ID`=66890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 불쌍한 육신에서 널 풀어주고, 우리에게 마음껏 봉사할 수 있게 해 주마!', `MaleText_loc4`='我会让你摆脱那副可怜的皮囊，把你重塑成我们的仆人！', `MaleText_loc5`='我會把你從那可悲的形體中解放出來，重塑成我們的僕人!', `MaleText_loc7`='¡Te liberaré de esa patética forma y te modelaré para que nos sirvas!' WHERE `ID`=66891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육신은 이렇게 무너지지만... 영혼은... 견뎌낼 수 있다...', `MaleText_loc4`='躯体或将腐朽……但灵魂……不灭……', `MaleText_loc5`='身體毀了...但魂靈...仍可存在...', `MaleText_loc7`='El cuerpo falla... pero el espíritu... permanece...' WHERE `ID`=66892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 우릴 막을 수 없다! 우리가 폭풍을 불러올 것이다!', `MaleText_loc4`='你休想阻止我们！我们的大军将带来狂风骤雨！', `MaleText_loc5`='你不能阻止我們!我們的軍隊會引領即將到來的風暴!', `MaleText_loc7`='¡No puedes detenernos! ¡Nuestro ejército estará a la cabeza de la tormenta que se aproxima!' WHERE `ID`=66893;
