UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 내놓아라!', `MaleText_loc4`='把你的灵魂交付给岩石之躯吧！', `MaleText_loc5`='將你的魂靈讓給石頭的軀體吧!', `MaleText_loc7`='¡Entrega tu espíritu a un cuerpo de piedra!' WHERE `ID`=66895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨이... 널 차지할 것이다...', `MaleText_loc4`='山泽……会抓住你的……', `MaleText_loc5`='衫...會帶走你...', `MaleText_loc7`='Los Shan... te atraparán...' WHERE `ID`=66896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말도 안 돼...', `MaleText_loc4`='这不可能……', `MaleText_loc5`='不可能...', `MaleText_loc7`='Imposible...' WHERE `ID`=66897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='붙잡고 싶은 생기 넘치는 영혼이군...', `MaleText_loc4`='送上门的灵魂……', `MaleText_loc5`='活生生的靈魂等人擷取...', `MaleText_loc7`='Un espíritu fuerte para la cosecha...' WHERE `ID`=66898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 담을 병을 준비해 뒀다!', `MaleText_loc4`='我的魂瓮正等着你呢！', `MaleText_loc5`='我有個罐子用來裝你!', `MaleText_loc7`='¡Tengo un tarro vacío que te está esperando!' WHERE `ID`=66899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 녀석들과 함께 영원히 우릴 섬기게 될 거다!', `MaleText_loc4`='你会和其他人一样，永世为奴！', `MaleText_loc5`='你要加入其他人的行列，永世服侍我們!', `MaleText_loc7`='¡Te unirás a los demás en el servicio eterno!' WHERE `ID`=66900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보 같으니! 네 운명은 정해졌다!', `MaleText_loc4`='蠢货！你死定了！', `MaleText_loc5`='蠢蛋!你的命運已經決定了!', `MaleText_loc7`='¡Gusano! ¡Tu suerte está echada!' WHERE `ID`=66901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 뼈 사이에서 영혼을 끄집어내 주마!', `MaleText_loc4`='我要把你的灵魂抽出来！', `MaleText_loc5`='我會刨開你的骨肉，把靈魂給剝離出來!', `MaleText_loc7`='¡Te arrancaré el alma de los huesos!' WHERE `ID`=66902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 참아라, 곧 끝날 거다...', `MaleText_loc4`='别动，很快就过去了……', `MaleText_loc5`='乖乖待著，很快就結束了...', `MaleText_loc7`='No te muevas. Pronto acabará todo...' WHERE `ID`=66903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음은 네 처벌의 시작일 뿐이다!', `MaleText_loc4`='死亡只是你受罚的开始！', `MaleText_loc5`='死亡只是你最初的懲罰!', `MaleText_loc7`='¡La muerte no es más que el comienzo de tu castigo!' WHERE `ID`=66904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 영혼이군. 내가 차지해야겠다!', `MaleText_loc4`='不错的灵魂——归我了。', `MaleText_loc5`='很好的靈魂...我想我要了。', `MaleText_loc7`='Bonito espíritu. Me lo quedo.' WHERE `ID`=66905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노한 과수원 침벌레가 머리 위에 나타납니다!', `MaleText_loc4`='一只狂怒的果园钉刺者出现了！', `MaleText_loc5`='一隻憤怒的果園刺蜂在你頭上出現了!', `MaleText_loc7`='¡Un aguijoneador de huerto salvaje aparece sobre ti!' WHERE `ID`=66906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하렴! 놈들이 자넬 보면 경보를 울릴 거야.$B$B황금 연꽃이 우릴 구하라고 보냈나? 죽거나 사로잡히지 않은 건 나뿐이야...', `FemaleText_loc4`='小心！要是让他们看见你，他们就会发出警报的。$B$B是金莲教派你来救我的吗？除了我，别人都被杀死或抓走了……', `FemaleText_loc5`='小心!如果他們看見你，將會提高戒備。$B$B是金蓮會派你來援救我們的嗎?我是唯一沒有被殺或被俘虜的...', `FemaleText_loc7`='¡Cuidado! Si te ven, darán la alarma.$b$b¿Te ha enviado el Loto Dorado a rescatarnos? Soy la única que no está muerta o cautiva...' WHERE `ID`=66907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원정대는 어떻게 된 겁니까?', `MaleText_loc4`='探险队出什么事了？', `MaleText_loc5`='遠征隊出了什麼事?', `MaleText_loc7`='¿Qué ha sido de la expedición?', `FemaleText_loc1`='원정대는 어떻게 된 거죠?', `FemaleText_loc4`='探险队出什么事了？', `FemaleText_loc5`='遠征隊出了什麼事?', `FemaleText_loc7`='¿Qué ha sido de la expedición?' WHERE `ID`=66908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포로가 있는 곳으로 데려다 주시겠습니까?', `MaleText_loc4`='你能带我们去找那些俘虏吗？', `MaleText_loc5`='你能帶我們去囚犯那裡嗎?', `MaleText_loc7`='¿Puedes llevarnos hasta los prisioneros?', `FemaleText_loc1`='포로가 있는 곳으로 데려다 주시겠어요?', `FemaleText_loc4`='你能带我们去找那些俘虏吗？', `FemaleText_loc5`='你能帶我們去囚犯那裡嗎?', `FemaleText_loc7`='¿Puedes llevarnos hasta los prisioneros?' WHERE `ID`=66909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 사원을 조사하고 있는데 모구 장군 하나가 수행원들을 이끌고 나타났지.$B$B우리 중에 즉시 죽임을 당하지 않은 이들은 포로로 잡혔어.$B$B놈들이 내가 죽은 줄 알고 가는 바람에, 난 지금까지 여기 숨어 있었지.$B$B모구가 왜 여기 왔는진 모르겠지만, 좋은 의도일 리는 없어!', `FemaleText_loc4`='我们当时正在调查寺庙，一个魔古军阀突然带着大批随从闯了进来。$B$B好多人当场毙命，剩下的都被抓走了。$B$B他们以为我死了，我一直躲在这里才逃过一劫。$B$B我不知道那些魔古族来这里干什么，但肯定不是好事！', `FemaleText_loc5`='我們正在調查寺廟，突然有個魔古督軍帶著他的手下出現。$B$B沒被立刻殺死的都成了俘虜。$B$B我被留下來等死，從那時就一直躲在這裡。$B$B我不知道魔古在這裡做什麼，但肯定不是好事!', `FemaleText_loc7`='Estábamos estudiando el templo cuando llegó un señor de la guerra mogu con su séquito.$b$bAquellos que no murieron en el momento fueron hechos prisioneros.$b$bA mí me dieron por muerta y he estado escondida desde entonces.$b$bNo sé para qué han venido los mogu, ¡pero no puede ser nada bueno!' WHERE `ID`=66910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남동쪽에 있는 폭포 쪽으로 끌려갔어. 내가 데려다 주지.', `FemaleText_loc4`='他们被带到东南边的瀑布那里去了。我带你们去。', `FemaleText_loc5`='他們被帶去東南邊的一個瀑布。我會帶你過去。', `FemaleText_loc7`='Se los llevaron hacia una catarata, al sureste. Te conduciré hasta allí.' WHERE `ID`=66911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심해야 돼. 모구와 사우록 노예들이 사원 경내를 순찰하고 있거든. 길가의 풀밭에는 놈들이 부리는 야수들이 도사리고 있고 말이야.', `FemaleText_loc4`='我们一定得小心。寺庙的地界上有魔古族和他们的蜥蜴人奴隶巡逻，而路边的草丛里则潜伏着他们驯养的畜生。', `FemaleText_loc5`='我們千萬要小心。寺廟裡到處都有魔古和他們的薩烏洛克奴隸在巡邏。他們的野獸潛伏在路旁的草叢裡。', `FemaleText_loc7`='Debeos tener cuidado. Los mogu y sus esclavos saurok patrullan el terreno del templo, y sus bestias acechan por la hierba que hay fuera de los caminos.' WHERE `ID`=66912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='중앙 안마당은 철통같이 방비되고 있어. 둘러 가야 해.', `FemaleText_loc4`='中庭的守卫十分森严。我们得绕过去。', `FemaleText_loc5`='中庭受到嚴密的把守。我們要另外找路。', `FemaleText_loc7`='El patio central está muy vigilado. Daremos un rodeo.' WHERE `ID`=66913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 영혼을 처치하여 페이즈의 지팡이에 힘을 불어넣으십시오!', `MaleText_loc4`='杀死古代灵魂来为裴智之杖充能！', `MaleText_loc5`='殺死遠古幽魂來充能培志之杖!', `MaleText_loc7`='¡Mata espíritus antiguos para potenciar el bastón de Pei-Zhi!', `FemaleText_loc1`='고대 영혼을 처치하여 페이즈의 지팡이에 힘을 불어넣으십시오!', `FemaleText_loc4`='杀死古代灵魂来为裴智之杖充能！', `FemaleText_loc5`='殺死遠古幽魂來充能培志之杖!', `FemaleText_loc7`='¡Mata espíritus antiguos para potenciar el bastón de Pei-Zhi!' WHERE `ID`=66914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 뭐하는 짓이냐?! 하, 상관없지. 이제 그 지팡이는 필요 없다.', `MaleText_loc4`='你知道自己在做什么吗？！算了——我也不需要那根法杖了。', `MaleText_loc5`='你到底在做啥啊?!算了，我不再需要這法杖了。', `MaleText_loc7`='¡¿Qué te crees que estás haciendo?! Da igual, ya no necesito el bastón.' WHERE `ID`=66915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 뱀 어때요? 뱀들은 당신을 싫어하는 느낌이 드네요!', `MaleText_loc4`='你喜欢我的蛇吗？我感觉它们不喜欢你！', `MaleText_loc5`='你喜歡我的蛇嗎?我感覺牠們不喜歡你!', `MaleText_loc7`='¿Te gustan mis serpientes? ¡Me da la sensación de que tú no les gustas a ellas!', `FemaleText_loc1`='제 뱀 어때요? 뱀들은 당신을 싫어하는 느낌이 드네요!', `FemaleText_loc4`='你喜欢我的蛇吗？我感觉它们不喜欢你！', `FemaleText_loc5`='你喜歡我的蛇嗎?我感覺牠們不喜歡你!', `FemaleText_loc7`='¿Te gustan mis serpientes? ¡Me da la sensación de que tú no les gustas a ellas!' WHERE `ID`=66916;
