UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 새끼 운룡이 실망한 듯 인상을 찌푸리며 당신을 노려봅니다. 당신이 다른 새끼 운룡과 놀고 있는 모습을 본 것 같습니다.>$B$B<한 번에 새끼 운룡 한 마리와만 놀 수 있습니다. 이 새끼 운룡과 공놀이를 하려면, 장로 안리와 대화하여 지금 함께 놀고 있는 새끼 운룡을 먼저 돌려보내십시오.>', `MaleText_loc4`='<雏龙失望地瞪着你。它看见你在和其他雏龙玩耍。>$B$B<你一次只能和一条雏龙玩耍。在跟这条雏龙玩接球之前，先去和安离长老谈谈，把你目前的这条雏龙归还给他吧。>', `MaleText_loc5`='<你的蛟寶寶用失望的表情看著你。牠看到你和其他蛟寶寶玩了。>$B$B<你一次只能和一隻蛟寶寶一起玩。在和這一隻玩傳接球之前，先和安麗長老說話，歸還你當前的蛟寶寶。>', `MaleText_loc7`='<Tu prole te fulmina con una mirada de decepción. Ve que estás jugando con otra prole.>$b$b<Solo puedes jugar con una prole a la vez. Habla con la ancestro Anli para devolver tu prole actual antes de jugar con esta.>' WHERE `ID`=66933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<새끼 운룡이 실망한 듯 인상을 찌푸리며 당신을 노려봅니다. 당신이 다른 새끼 운룡과 놀고 있는 모습을 본 것 같습니다.>$B$B<한 번에 새끼 운룡 한 마리와만 놀 수 있습니다. 이 새끼 운룡과 공놀이를 하려면, 장로 안리와 대화하여 지금 함께 놀고 있는 새끼 운룡을 먼저 돌려보내십시오.>', `MaleText_loc4`='<雏龙失望地瞪着你。它看见你在和其他雏龙玩耍。>$B$B<你一次只能和一条雏龙玩耍。在跟这条雏龙玩接球之前，先去和安离长老谈谈，把你目前的这条雏龙归还给他吧。>', `MaleText_loc5`='<蛟寶寶用失望的表情看著你。牠看到你和其他蛟寶寶玩了。>$B$B<你一次只能和一隻蛟寶寶一起玩。在和這一隻玩傳接球之前，先和安麗長老說話，歸還你當前的蛟寶寶。>', `MaleText_loc7`='<La prole te fulmina con una mirada de decepción. Ve que estás jugando con otra prole.>$b$b<Solo puedes jugar con una prole a la vez. Habla con la ancestro Anli para devolver tu prole actual antes de jugar con esta.>' WHERE `ID`=66934;
