UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 용감한 행위는 오래도록 기억될 거요.', `MaleText_loc4`='人们将铭记你的英勇事迹。', `MaleText_loc5`='你勇敢的行為會被記憶。', `MaleText_loc7`='Tu valor y hazañas serán recordados.' WHERE `ID`=66936;
