UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117697|h[암흑의 방패]|h|r를 시전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s开始施放|cFFFF0000|Hspell:117697|h[黑暗之盾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s開始施放|cFFFF0000|Hspell:117697|h[黑暗之盾]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_sacrificialshield.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:117697|h[Escudo de la oscuridad]|h|r!' WHERE `ID`=66939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육체적 부상을 이겨낼 때마다 교훈을 얻을 수 있으며, 패배할 때마다 성장할 기회를 얻을 수 있다.', `MaleText_loc4`='每一次受伤，都是学习的过程。每一次失败，都是成长的机会。', `MaleText_loc5`='身體上的每一道傷都是一次課程。每次失敗都是一次成長的機會。', `MaleText_loc7`='Cada herida corporal sufrida es una lección aprendida. Cada derrota es una oportunidad para el crecimiento.' WHERE `ID`=66941;
