UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님! 몸이... 내 뜻대로 움직이지 않습니다... 도망치세요!', `MaleText_loc4`='$p！我……失去控制了……走开！', `MaleText_loc5`='$p!我...無法自主...快走開!', `MaleText_loc7`='¡$p! No... tengo... el control... ¡Corre!' WHERE `ID`=66944;
