UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내면의 평화를 찾으면, 장애물도 이성적으로 볼 수 있게 된다.', `MaleText_loc4`='找寻内心的平静，这能帮助你理性地看待前路上的阻碍。', `MaleText_loc5`='找到內心的平靜，這會讓你更理性地看待眼前障礙。', `MaleText_loc7`='Encontrar la paz interior te permitirá ver los obstáculos con claridad.' WHERE `ID`=66946;
