UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `MaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `MaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `MaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?', `FemaleText_loc1`='우리는 다행히 문이 열린 후에 영원꽃 골짜기에 도착했습니다. 그리고 여기서 안전한 쉼터를 찾았지요.$B$B혹시 길을 잃었습니까? 뭔가 찾도록 도와드릴까요?', `FemaleText_loc4`='我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？', `FemaleText_loc5`='當山谷的關門打開時，我們有幸能找到它。我們得到庇護，並找到安身立命的天堂。$B$B你迷路了嗎?有什麼我能幫忙的嗎?', `FemaleText_loc7`='Tuvimos la suerte de encontrar el valle poco después de que abriera sus puertas. Buscamos refugio y encontramos un lugar seguro.$B$B¿Te has perdido? ¿Necesitas que te ayude a encontrar algo?' WHERE `ID`=66958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장은 건물 2층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='拍卖行位于二楼，就在建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='拍賣場就在你一進門後，整個建築的二樓右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='La casa de subastas se encuentra en la segunda planta, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='경매장은 건물 2층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='拍卖行位于二楼，就在建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='拍賣場就在你一進門後，整個建築的二樓右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='La casa de subastas se encuentra en la segunda planta, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은행은 건물 2층에 있습니다. 입구에 들어서서 보면 왼쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='银行位于二楼，就在建筑物进门的左手边。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='銀行就在你一進門後，整棟建築的二樓左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='El banco se encuentra en la segunda planta, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='은행은 건물 2층에 있습니다. 입구에 들어서서 보면 왼쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='银行位于二楼，就在建筑物进门的左手边。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='銀行就在你一進門後，整棟建築的二樓左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='El banco se encuentra en la segunda planta, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비행 조련사는 중앙 난간뜰에 있습니다. 양쪽의 계단을 올라간 후 건물 앞을 보면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='飛行管理員位於主要平臺上，就在雙向樓梯的頂端，進入主建築物之前的地方。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='El maestro de vuelo se encuentra en el patio principal, en lo alto de las escaleras gemelas antes de entrar en el edificio principal.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='비행 조련사는 중앙 난간뜰에 있습니다. 양쪽의 계단을 올라간 후 건물 앞을 보면 되지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='飛行管理員位於主要平臺上，就在雙向樓梯的頂端，進入主建築物之前的地方。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='El maestro de vuelo se encuentra en el patio principal, en lo alto de las escaleras gemelas antes de entrar en el edificio principal.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘춤꾼 슌이 판다리아에서 비행하는 법을 가르쳐 줄 겁니다. 중앙 난간뜰에서 옥룡을 타고 있지요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='舞空者书恩可以教你如何在潘达利亚飞行。他就在主露台上，骑着他的云端翔龙。我会在你的地图上标出位置。', `MaleText_loc5`='天舞者湘能教導你如何在潘達利亞飛行。他在主要平臺上，乘著他的雲蛟。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El bailarín del cielo Shun puede enseñarte a volar en Pandaria. Monta su dragón nimbo en el patio principal. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='하늘춤꾼 슌이 판다리아에서 비행하는 법을 가르쳐 줄 겁니다. 중앙 난간뜰에서 옥룡을 타고 있지요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='舞空者书恩可以教你如何在潘达利亚飞行。他就在主露台上，骑着他的云端翔龙。我会在你的地图上标出位置。', `FemaleText_loc5`='天舞者湘能教導你如何在潘達利亞飛行。他在主要平臺上，乘著他的雲蛟。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El bailarín del cielo Shun puede enseñarte a volar en Pandaria. Monta su dragón nimbo en el patio principal. Te marcaré su ubicación en el mapa.' WHERE `ID`=66962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여관은 건물 1층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='旅店就在一進門後，整棟建築的主要樓層右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='La posada se encuentra en la planta principal, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='여관은 건물 1층에 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='旅店就在一進門後，整棟建築的主要樓層右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='La posada se encuentra en la planta principal, nada más entrar en el edificio, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부드러운 싼이라는 전투 애완동물 전문가가 중앙 난간뜰에서 애완동물을 훈련하고 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='有个名叫文雅的萨恩的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='有個叫做溫柔的珊的戰寵訓練師在主要平臺上訓練她的寵物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Hay una instructora de duelos llamada Buen San que entrena a sus mascotas en el patio principal.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='부드러운 싼이라는 전투 애완동물 전문가가 중앙 난간뜰에서 애완동물을 훈련하고 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='有个名叫文雅的萨恩的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='有個叫做溫柔的珊的戰寵訓練師在主要平臺上訓練她的寵物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Hay una instructora de duelos llamada Buen San que entrena a sus mascotas en el patio principal.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에테리얼은 주 건물 위층에 있는 회랑에 점포를 차리고 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='以太在樓上走廊設了商店，就在你進入主要建築物後的右手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Los etéreos están asentados en el pasillo de la planta de arriba, nada más entrar en el edificio principal, a la derecha.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='에테리얼은 주 건물 위층에 있는 회랑에 점포를 차리고 있습니다. 입구에 들어서서 보면 오른쪽이지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='以太在樓上走廊設了商店，就在你進入主要建築物後的右手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Los etéreos están asentados en el pasillo de la planta de arriba, nada más entrar en el edificio principal, a la derecha.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수 관리인 추적자 랑은 건물 앞의 중앙 난간뜰에 있습니다. 전투 애완동물 전문가 옆에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='你可以在主楼外的主露台上找到兽栏管理员追踪者老朗。他就站在战斗宠物训练师的旁边。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='獸欄管理員追蹤者嵐，就在進入主要建築物之前的主平臺上。他就站在戰寵訓練師的隔壁。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='El rastreador Lang, el maestro de establos, se encuentra en el patio principal, antes de entrar en el edificio principal. Está al lado del maestro de vuelo.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='야수 관리인 추적자 랑은 건물 앞의 중앙 난간뜰에 있습니다. 전투 애완동물 전문가 옆에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='你可以在主楼外的主露台上找到兽栏管理员追踪者老朗。他就站在战斗宠物训练师的旁边。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='獸欄管理員追蹤者嵐，就在進入主要建築物之前的主平臺上。他就站在戰寵訓練師的隔壁。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='El rastreador Lang, el maestro de establos, se encuentra en el patio principal, antes de entrar en el edificio principal. Está al lado del maestro de vuelo.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방방곡곡에서 모여든 상인들이 이곳에 자리 잡았지요. 뭘 찾으십니까?', `MaleText_loc4`='来自各地的商贩都进城了。你要找什么？', `MaleText_loc5`='來自各地的商人都進到了城市裡。你在找什麼?', `MaleText_loc7`='A la ciudad han llegado vendedores de todas partes. ¿Qué andas buscando?', `FemaleText_loc1`='방방곡곡에서 모여든 상인들이 이곳에 자리 잡았지요. 뭘 찾으십니까?', `FemaleText_loc4`='来自各地的商贩都进城了。你要找什么？', `FemaleText_loc5`='來自各地的商人都進到了城市裡。你在找什麼?', `FemaleText_loc7`='A la ciudad han llegado vendedores de todas partes. ¿Qué andas buscando?' WHERE `ID`=66967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 연금술사 그린모스는 별의 시장에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你正在寻找的药剂师。他配制一些真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……绿苔药师在工匠大厅出售他的商品。我会在你的地图上标记这个位置。', `MaleText_loc5`='你在找藥劑師對嗎。他能製作神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...藥劑師綠苔在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... el boticario Verdemusgo vende sus mercancías en la sala del artesano. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 연금술사 그린모스는 별의 시장에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你正在寻找的药剂师。他配制一些真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……绿苔药师在工匠大厅出售他的商品。我会在你的地图上标记这个位置。', `FemaleText_loc5`='你在找藥劑師對嗎。他能製作神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...藥劑師綠苔在工匠大廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... el boticario Verdemusgo vende sus mercancías en la sala del artesano. Te marcaré su ubicación en el mapa.' WHERE `ID`=66968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복자의 무덤은 자네 바로 아래에 있다네. 흙길을 따라가면 입구에 다다를 걸세. 서둘러야 하네!', `MaleText_loc4`='征服者陵墓就在你的正下方。沿着这条土路就能找到入口。动作快！', `MaleText_loc5`='征服者之墓就在你的正下方。跟著砂土的痕跡到入口前面去。你必須儘快!', `MaleText_loc7`='La Tumba de los Conquistadores se encuentra justo debajo de ti. Sigue el camino hasta la entrada. ¡Tienes que darte prisa!' WHERE `ID`=66969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대장장이는 모두 별의 시장에서 일합니다. 건물 입구에 들어서서 왼쪽으로 가면 나오지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='铁匠们都在工匠大厅里工作，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='鐵匠們全都在工匠大廳裡做事，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Todos los herreros trabajan en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='대장장이는 모두 별의 시장에서 일합니다. 건물 입구에 들어서서 왼쪽으로 가면 나오지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='铁匠们都在工匠大厅里工作，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='鐵匠們全都在工匠大廳裡做事，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Todos los herreros trabajan en la sala del artesano, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한잔 하고 싶으신가요? 좋은 술을 찾는다면 맥주창고에 가야 하지요! 지도에 위치를 표시해 드리겠습니다.', `MaleText_loc4`='在找啤酒吗？烈酒窖有最香醇的美酒！我会在你的地图上标出位置。', `MaleText_loc5`='找酒喝是吧?好，酒罈之廳就是找酒喝的好去處!我會替你在地圖上標出位置。', `MaleText_loc7`='¿Buscas cerveza, eh? ¡Las mejores están en La Bodega! Te la marcaré en el mapa.', `FemaleText_loc1`='한잔 하고 싶으신가요? 좋은 술을 찾는다면 맥주창고에 가야 하지요! 지도에 위치를 표시해 드리겠습니다.', `FemaleText_loc4`='在找啤酒吗？烈酒窖有最香醇的美酒！我会在你的地图上标出位置。', `FemaleText_loc5`='找酒喝是吧?好，酒罈之廳就是找酒喝的好去處!我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Buscas cerveza, eh? ¡Las mejores están en La Bodega! Te la marcaré en el mapa.' WHERE `ID`=66971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화살을 구해서 여길 떠야 해요.', `MaleText_loc4`='我们得拿到那些箭矢，然后离开这儿。', `MaleText_loc5`='我們得拿到那些箭然後離開這裡。', `MaleText_loc7`='Tenemos que hacernos con esas flechas y largarnos de aquí.' WHERE `ID`=66972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화살통을 하나 더 주시겠습니까?', `MaleText_loc4`='新兵，能再给我一个箭袋吗？', `MaleText_loc5`='師弟，我能再拿一束箭嗎?', `MaleText_loc7`='Iniciado, ¿me das otro carcaj, por favor?', `FemaleText_loc1`='화살통을 하나 더 주시겠어요?', `FemaleText_loc4`='新兵，能再给我一个箭袋吗？', `FemaleText_loc5`='師弟，我能再拿一束箭嗎?', `FemaleText_loc7`='Iniciado, ¿me das otro carcaj, por favor?' WHERE `ID`=66973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리사 지망생인가 보죠? 필요한 건 모두 보리꽃에게서 구할 수 있을 겁니다. 보리꽃은 맥주창고에서 장사를 하고 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='啊，看来你想当厨师对吧？你可以在大麦花那里找到你所需要的一切。她就在烈酒窖里卖货。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='啊，所以你是個未來的大廚，是嗎?你可以在大麥花那裡找到你一切所需。她在酒罈之廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Ah, así que eres $gun:una; aspirante a $gcocinero:cocinera;, ¿verdad? Flor de Cebada te facilitará todo lo que necesites. Vende sus mercancías en La Bodega.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='요리사 지망생인가 보죠? 필요한 건 모두 보리꽃에게서 구할 수 있을 겁니다. 보리꽃은 맥주창고에서 장사를 하고 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='啊，看来你想当厨师对吧？你可以在大麦花那里找到你所需要的一切。她就在烈酒窖里卖货。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='啊，所以你是個未來的大廚，是嗎?你可以在大麥花那裡找到你一切所需。她在酒罈之廳裡販賣貨物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Ah, así que eres $gun:una; aspirante a $gcocinero:cocinera;, ¿verdad? Flor de Cebada te facilitará todo lo que necesites. Vende sus mercancías en La Bodega.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데렌다 엔클신이 마법부여용품을 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 찾을 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='德兰达·安克辛携带着附魔物资。在师匠大厅内可以找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='德倫達·安可欣販售附魔材料。她在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Derenda Enkleshin lleva suministros de encantamiento. Puedes encontrarla en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='데렌다 엔클신이 마법부여용품을 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 찾을 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='德兰达·安克辛携带着附魔物资。在师匠大厅内可以找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='德倫達·安可欣販售附魔材料。她在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Derenda Enkleshin lleva suministros de encantamiento. Puedes encontrarla en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가의 방에 기계공학자가 있었던 것 같군요. 건물 입구에 들어서서 왼쪽으로 가면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='我依稀记得在师匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='我記得師匠之間裡有個工程師，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Creo recordar que hay un ingeniero en la Cámara de los Maestros, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='대가의 방에 기계공학자가 있었던 것 같군요. 건물 입구에 들어서서 왼쪽으로 가면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='我依稀记得在师匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='我記得師匠之間裡有個工程師，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Creo recordar que hay un ingeniero en la Cámara de los Maestros, nada más entrar en el edificio principal, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불장난이 하고 싶으신가요? 말 난 김에 저도 폭죽을 좀 사러 가야겠군요! 상인은 대가의 방에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='考虑过燃放一两个烟花吗？我应该自己去买些烟花！在师匠大厅内可以找到商贩。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='想要放幾朵煙花嗎?我也很想去買一些煙火!煙火商人就在師匠之間裡。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Estás pensando en soltar chispas? ¡Yo también debería comprar fuegos artificiales! El vendedor se encuentra en la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='불장난이 하고 싶으신가요? 말 난 김에 저도 폭죽을 좀 사러 가야겠군요! 상인은 대가의 방에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='考虑过燃放一两个烟花吗？我应该自己去买些烟花！在师匠大厅内可以找到商贩。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='想要放幾朵煙花嗎?我也很想去買一些煙火!煙火商人就在師匠之間裡。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Estás pensando en soltar chispas? ¡Yo también debería comprar fuegos artificiales! El vendedor se encuentra en la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까운 곳에서 응급치료를 받을 수 있으니 걱정하지 마세요. 치유사들은 대가의 방 안에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='别担心，急救人员离这不远。治疗者就在师匠大厅里。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='急救服務就在不遠處，別擔心。治療師們都在師匠之間裡，就在中央樓梯的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='No te preocupes, los primeros auxilios se administran cerca de aquí. Los sanadores están en el interior de la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='가까운 곳에서 응급치료를 받을 수 있으니 걱정하지 마세요. 치유사들은 대가의 방 안에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='别担心，急救人员离这不远。治疗者就在师匠大厅里。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='急救服務就在不遠處，別擔心。治療師們都在師匠之間裡，就在中央樓梯的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='No te preocupes, los primeros auxilios se administran cerca de aquí. Los sanadores están en el interior de la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야... 야운골 놈들!

놈들이 내 농장과 근처의 마을, 동풍의 쉼터에 쳐들어와서 사람을 죽이고... 살아남은 사람들을 쫓아냈어요!

가까스로 이곳에 그중 몇 명을 모았어요. 빈안 마을에서 도와준다는 얘긴 없나요?', `MaleText_loc4`='那些……野牛人！

他们攻击了我的农场，还有附近的东风之眠……他们杀了许多人，还把剩下的村民都赶走了！

我设法在这里聚集了一些乡亲。有滨岸村的人来帮忙么？', `MaleText_loc5`='揚古...!

他們攻擊了我的農場，還有附近的村莊東風之眠...殺了一些人，然後趕走剩下沒死的人!

我設法集結了一些人，但是濱南那裡有辦法提供援助嗎?', `MaleText_loc7`='¡Los... los yaungol!

Han atacado mi granja y la aldea cercana, Reposo Viento del Este... Han matado a algunos de nosotros, y a los demás los han expulsado.

He conseguido que algunos nos reunamos aquí. ¿Se sabe si viene ayuda de Binan?' WHERE `ID`=66979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 호드의 일원입니다. 여러분을 구하고 마을을 재건하러 왔습니다.', `MaleText_loc4`='我来自部落。我们是来救你们，并帮你们重建村庄的。', `MaleText_loc5`='我來自部落。我們是來這裡拯救你並重建你村莊的。', `MaleText_loc7`='Soy de la Horda. Hemos venido a salvarlos y reconstruir su aldea.', `FemaleText_loc1`='저는 호드의 일원입니다. 여러분을 구하고 마을을 재건하러 왔어요.', `FemaleText_loc4`='我来自部落。我们是来救你们，并帮你们重建村庄的。', `FemaleText_loc5`='我來自部落。我們是來這裡拯救你並重建你村莊的。', `FemaleText_loc7`='Soy de la Horda. Hemos venido a salvarlos y reconstruir su aldea.' WHERE `ID`=66980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반, 폭발물을 더 받을 수 있습니까?', `MaleText_loc4`='班，能再多给我一些炸药吗？', `MaleText_loc5`='班，你能否給我更多炸藥?', `MaleText_loc7`='Ban, ¿me darías más explosivos?', `FemaleText_loc1`='반, 폭발물을 더 받을 수 있을까요?', `FemaleText_loc4`='班，能再多给我一些炸药吗？', `FemaleText_loc5`='班，你能否給我更多炸藥?', `FemaleText_loc7`='Ban, ¿me darías más explosivos?' WHERE `ID`=66981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 평온의 전당에 낚시용품 상인이 있지요. 낚시에 방해가 되지 않게 조용히 하십시오.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，在静思之厅内有渔具供应商。动作要轻，以免吓跑大鱼！$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='是的，寧靜大廳裡有個釣魚貨品商人。請保持安靜，以免破壞了釣上魚的機會!$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Sí, hay un vendedor de suministros de pesca dentro de la Sala de la Quietud. No hagas ruido, ¡no vayas a ahuyentar a los peces!$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 평온의 전당에 낚시용품 상인이 있지요. 낚시에 방해가 되지 않게 조용히 하십시오.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，在静思之厅内有渔具供应商。动作要轻，以免吓跑大鱼！$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='是的，寧靜大廳裡有個釣魚貨品商人。請保持安靜，以免破壞了釣上魚的機會!$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Sí, hay un vendedor de suministros de pesca dentro de la Sala de la Quietud. No hagas ruido, ¡no vayas a ahuyentar a los peces!$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식과 음료를 찾으십니까? 여름의 쉼터에 있는 미판이 아주 좋은 음식을 팔지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='你在寻找食物和饮料吗？如果是的话，夏之眠的米凡那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='你在找吃的和喝的嗎?那樣的話，盛夏之眠裡的米范有你所想要的一切。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Estás buscando comida y bebida? Si es así, Mifan tiene justo lo que necesitas en Reposo Estival.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='음식과 음료를 찾으십니까? 여름의 쉼터에 있는 미판이 아주 좋은 음식을 팔지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='你在寻找食物和饮料吗？如果是的话，夏之眠的米凡那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='你在找吃的和喝的嗎?那樣的話，盛夏之眠裡的米范有你所想要的一切。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Estás buscando comida y bebida? Si es así, Mifan tiene justo lo que necesitas en Reposo Estival.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 온 후로 상황이 좋아지고 있어요!

하지만 농장에 두고 온 친구들이 어떻게 됐을지 걱정이네요...', `MaleText_loc4`='你知道，自打你来了之后，情况确实好了许多！

可我还是很担心农场上的朋友们……', `MaleText_loc5`='你知道嗎，自從你來到這裡，事情真的開始變順利了!

但我忍不住想到，不曉得我在農場那裡的朋友都怎麼樣了...', `MaleText_loc7`='La cosa ha empezado a mejorar desde que viniste, ¿sabes?

Pero no puedo evitar pensar en lo que les sucedió a mis amigos de la granja...' WHERE `ID`=66984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일용품을 찾으십니까? 그렇다면 두 발가락 말리를 찾아가면 됩니다. 여름의 쉼터 안에 있지요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='想买杂货？胼趾马利那儿应该有你要找的东西。他就在夏之眠。我会在你的地图上标出位置。', `MaleText_loc5`='你在找雜貨嗎?雙趾瑪里會有你需要的東西。他就在盛夏之眠開業。我會替你把位置在標記在地圖上。', `MaleText_loc7`='¿Buscas pertrechos? Marli Dos Pulgares tiene lo que necesitas. Está en Reposo Estival. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='일용품을 찾으십니까? 그렇다면 두 발가락 말리를 찾아가면 됩니다. 여름의 쉼터 안에 있지요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='想买杂货？胼趾马利那儿应该有你要找的东西。他就在夏之眠。我会在你的地图上标出位置。', `FemaleText_loc5`='你在找雜貨嗎?雙趾瑪里會有你需要的東西。他就在盛夏之眠開業。我會替你把位置在標記在地圖上。', `FemaleText_loc7`='¿Buscas pertrechos? Marli Dos Pulgares tiene lo que necesitas. Está en Reposo Estival. Te marcaré su ubicación en el mapa.' WHERE `ID`=66985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 이곳에는 약초 상인이 있습니다. 하푸나 랜드워커는 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，城市里有草药供应商。在师匠大厅内可以找到哈夫纳·地行者，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='是的，城市裡有個草藥商人。哈弗娜·陸行者在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Sí, hay un vendedor de hierbas en la ciudad. Puedes encontrar a Hafuna Caminante Terrestre en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='예, 이곳에는 약초 상인이 있습니다. 하푸나 랜드워커는 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，城市里有草药供应商。在师匠大厅内可以找到哈夫纳·地行者，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='是的，城市裡有個草藥商人。哈弗娜·陸行者在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Sí, hay un vendedor de hierbas en la ciudad. Puedes encontrar a Hafuna Caminante Terrestre en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 두루마리를 만드시는군요! 잉크와 피지를 찾는 거라면, 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 구할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在师匠大厅里可以找到这些，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='啊，卷軸製造者。你一定是在找墨水和上等的皮紙，對嗎?你可以在師匠之間找到這些東西，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¡Ah, un fabricante de pergaminos! Supongo que buscarás tintas y papel de vitela... Puedes encontrar todo eso en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 두루마리를 만드시는군요! 잉크와 피지를 찾는 거라면, 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 구할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在师匠大厅里可以找到这些，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='啊，卷軸製造者。你一定是在找墨水和上等的皮紙，對嗎?你可以在師匠之間找到這些東西，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¡Ah, un fabricante de pergaminos! Supongo que buscarás tintas y papel de vitela... Puedes encontrar todo eso en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보석세공사신가요? 좋은 기술이지요. 보석세공용품은 대가의 방에 있는 바나리스 화이트송에게서 살 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='珠宝加工？这的确是件精细活儿。你可以从师匠大厅的瓦纳里斯·白歌那购买物资。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='珠寶設計?那真是很不錯的技巧。你可以在師匠之間跟范那里斯·白歌買材料。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Joyería? Desde luego, es un trabajo delicado. Puedes comprar material a Vanaris Cantoblanco, en la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='보석세공사신가요? 좋은 기술이지요. 보석세공용품은 대가의 방에 있는 바나리스 화이트송에게서 살 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='珠宝加工？这的确是件精细活儿。你可以从师匠大厅的瓦纳里斯·白歌那购买物资。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='珠寶設計?那真是很不錯的技巧。你可以在師匠之間跟范那里斯·白歌買材料。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Joyería? Desde luego, es un trabajo delicado. Puedes comprar material a Vanaris Cantoblanco, en la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전문 가죽세공인은 쿤라이 봉우리의 그루멀 시장에 있습니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。', `MaleText_loc5`='你可以在崑萊峰的咕嚕摩市集找到製皮訓練師。我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un instructor de peletería en El Bazar Grúmel, en la Cima Kun-Lai. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='전문 가죽세공인은 쿤라이 봉우리의 그루멀 시장에 있습니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。', `FemaleText_loc5`='你可以在崑萊峰的咕嚕摩市集找到製皮訓練師。我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un instructor de peletería en El Bazar Grúmel, en la Cima Kun-Lai. Te marcaré su ubicación en el mapa.' WHERE `ID`=66989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가죽세공용품과 가죽 말입니까? 무두장이를 찾는 거로군요. 제 기억이 맞다면 대가의 방에 한 명 있습니다.$B$B지도에 위치를 표시해 드리지요.', `MaleText_loc4`='皮革加工和皮草？你一定是在寻找皮匠。如果我没记错的话，在师匠大厅里有一位。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='製皮和材料?你要找的是個皮匠。就在你進入主建築物後的左手邊。沒記錯的話，師匠之間裡有一個。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='¿Peletería y cuero? Debes de estar buscando un peletero. Hay uno en la Cámara de los Maestros, creo recordar.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='가죽세공용품과 가죽 말입니까? 무두장이를 찾는 거로군요. 제 기억이 맞다면 대가의 방에 한 명 있습니다.$B$B지도에 위치를 표시해 드리지요.', `FemaleText_loc4`='皮革加工和皮草？你一定是在寻找皮匠。如果我没记错的话，在师匠大厅里有一位。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='製皮和材料?你要找的是個皮匠。就在你進入主建築物後的左手邊。沒記錯的話，師匠之間裡有一個。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='¿Peletería y cuero? Debes de estar buscando un peletero. Hay uno en la Cámara de los Maestros, creo recordar.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광용품은 대가의 방 안쪽에 있는 라지에 콜렌치에게 구입할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='在可以在师匠大厅里找拉兹·煤钳购买采矿用品。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='採礦工具全都在師匠之間的後面跟雷希·煤扳買，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Puedes comprarle suministros de minería a Razzie Llavecarbón, al fondo de la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='채광용품은 대가의 방 안쪽에 있는 라지에 콜렌치에게 구입할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='在可以在师匠大厅里找拉兹·煤钳购买采矿用品。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='採礦工具全都在師匠之間的後面跟雷希·煤扳買，就在你進入主建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Puedes comprarle suministros de minería a Razzie Llavecarbón, al fondo de la Cámara de los Maestros.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시이나 선위버가 마법 재료를 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='辛娜·织日在师匠大厅里兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='詩娜·日織者在師匠之間裡叫賣原料，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='A Sheena Tejesol se la conoce por vender componentes en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='시이나 선위버가 마법 재료를 팝니다. 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='辛娜·织日在师匠大厅里兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='詩娜·日織者在師匠之間裡叫賣原料，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='A Sheena Tejesol se la conoce por vender componentes en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 아무리 암울해도 이 내가 희망을 잃어서는 안 되지. 야운골의 폭력에 굴해서는 안 되지.$B$B자네는... 우릴 도우러 왔는가?', `MaleText_loc4`='尽管前景黯淡，可我决不会放弃希望。我们不能向野牛人的暴力低头。

你……是来帮我们的？', `MaleText_loc5`='儘管一切看起來十分黑暗，但我絕不能放棄希望。我們絕不能屈服於揚古的暴力。

你...是來幫助我們的嗎?', `MaleText_loc7`='Aunque la situación parezca nefasta, no debo abandonar la esperanza. No debemos dejar que la violencia de los yaungol nos acobarde.

¿Has... has venido a ayudarnos?' WHERE `ID`=66993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 호드의 일원입니다. 여러분을 구하고 마을을 재건하러 왔습니다.', `MaleText_loc4`='我来自部落。我们是来救你们，并帮你们重建村庄的。', `MaleText_loc5`='我來自部落。我們是來這裡拯救你並重建你村莊的。', `MaleText_loc7`='Soy de la Horda. Hemos venido a salvarlos y reconstruir su aldea.', `FemaleText_loc1`='저는 호드의 일원입니다. 여러분을 구하고 마을을 재건하러 왔어요.', `FemaleText_loc4`='我来自部落。我们是来救你们，并帮你们重建村庄的。', `FemaleText_loc5`='我來自部落。我們是來這裡拯救你並重建你村莊的。', `FemaleText_loc7`='Soy de la Horda. Hemos venido a salvarlos y reconstruir su aldea.' WHERE `ID`=66994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인정하겠네. 한창 암울했을 때는 우리가 살아남지 못할 거라 생각했다네. 자네와 동료들 덕에 내 생각이 틀리게 되어 다행일세.', `MaleText_loc4`='我必须承认，在那最黑暗的时刻，我不敢相信我们还能活下来。多亏你和你的族人，幸好事情没往我预想的方向发展。', `MaleText_loc5`='我必須承認，在最黑暗的時刻來臨時，我並不相信我們有辦法活下來。多虧了你和你的同伴，我很高興我錯了。', `MaleText_loc7`='Debo admitir que, en los momentos más oscuros, no creí que sobreviviría. Me alegro de que tu gente y tú hayáis demostrado que me equivocaba.' WHERE `ID`=66995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베짜는 아가씨 에샤가 재봉 솜씨로 유명하지요.$B$B에샤는 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='织花女士伊莎那一流的制衣手艺人尽皆知。$B$B她在师匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `MaleText_loc5`='『紡織女王』愛莎以她的漂亮衣服而出名。$B$B她在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Esha, la Dama del Telar, es muy conocida por sus preciosas prendas.$B$BTrabaja en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='베짜는 아가씨 에샤가 재봉 솜씨로 유명하지요.$B$B에샤는 건물 입구에 들어서서 왼쪽으로 가면 나오는 대가의 방에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='织花女士伊莎那一流的制衣手艺人尽皆知。$B$B她在师匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。', `FemaleText_loc5`='『紡織女王』愛莎以她的漂亮衣服而出名。$B$B她在師匠之間裡做事，就在你進入建築物後的左手邊。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Esha, la Dama del Telar, es muy conocida por sus preciosas prendas.$B$BTrabaja en la Cámara de los Maestros, nada más entrar en el edificio, a la izquierda.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=66996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여름의 쉼터에 직업용품을 파는 여인이 있습니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='我知道有个小贩在夏之眠摆摊卖货。我会在你的地图上标出位置。', `MaleText_loc5`='我看到有個小販在盛夏之眠做買賣。我會替你把位置在標記在地圖上。', `MaleText_loc7`='Conozco a una vendedora de objetos comerciables en Reposo Estival. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='여름의 쉼터에 직업용품을 파는 여인이 있습니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='我知道有个小贩在夏之眠摆摊卖货。我会在你的地图上标出位置。', `FemaleText_loc5`='我看到有個小販在盛夏之眠做買賣。我會替你把位置在標記在地圖上。', `FemaleText_loc7`='Conozco a una vendedora de objetos comerciables en Reposo Estival. Te marcaré su ubicación en el mapa.' WHERE `ID`=66997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모구 놈들은 대체 어디서 온 거지?', `MaleText_loc4`='这些魔古都是从哪儿冒出来的？', `MaleText_loc5`='這些魔古都是打哪兒來的啊?', `MaleText_loc7`='¿De dónde han salido todos estos mogu?', `FemaleText_loc1`='이 모구 놈들은 대체 어디서 온 거지?', `FemaleText_loc4`='这些魔古都是从哪儿冒出来的？', `FemaleText_loc5`='這些魔古都是打哪兒來的啊?', `FemaleText_loc7`='¿De dónde han salido todos estos mogu?' WHERE `ID`=66998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해 주셔서 감사합니다, $c님. 이제 임무를 수행할 수 있을지도 모르겠습니다.', `MaleText_loc4`='谢谢你救了我们，$c。希望我们的任务不会以失败而告终。', `MaleText_loc5`='$c，謝謝你救了我們。幸運的話，我們的任務還有一線希望。', `MaleText_loc7`='Gracias por rescatarnos, $c. Con suerte, todavía podremos recuperar nuestra misión.', `FemaleText_loc1`='구해 주셔서 감사해요, $c님. 이제 임무를 수행할 수 있을지도 모르겠네요.', `FemaleText_loc4`='谢谢你救了我们，$c。希望我们的任务不会以失败而告终。', `FemaleText_loc5`='$c，謝謝你救了我們。幸運的話，我們的任務還有一線希望。', `FemaleText_loc7`='Gracias por rescatarnos, $c. Espero que ahora nuestra misión no esté perdida.' WHERE `ID`=66999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 "엘프"라는 생물체들은 믿을 만한 겁니까?', `MaleText_loc4`='这些“精灵”……他们信得过吗？', `MaleText_loc5`='「精靈」這種生物值得信任嗎?', `MaleText_loc7`='Estas criaturas "elfas"... ¿son de fiar?', `FemaleText_loc1`='이 "엘프"라는 생물체들은 믿을 만한 건가요?', `FemaleText_loc4`='这些“精灵”……他们信得过吗？', `FemaleText_loc5`='「精靈」這種生物值得信任嗎?', `FemaleText_loc7`='Estas criaturas "elfas"... ¿son de fiar?' WHERE `ID`=67000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀로도 모자라 모구까지... 정말이지 암울한 시기로군요.', `MaleText_loc4`='先是螳螂妖，接着又是魔古。真是暗无天日啊。', `MaleText_loc5`='先是螳螂人，然後是魔古。最近的日子真是難熬。', `MaleText_loc7`='Primero los mántides... y luego los mogu. Desde luego, son días oscuros.', `FemaleText_loc1`='사마귀로도 모자라 모구까지... 정말이지 암울한 시기네요.', `FemaleText_loc4`='先是螳螂妖，接着又是魔古。真是暗无天日啊。', `FemaleText_loc5`='先是螳螂人，然後是魔古。最近的日子真是難熬。', `FemaleText_loc7`='Primero los mántides... y luego los mogu. Desde luego, son días oscuros.' WHERE `ID`=67001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='금지된 밀림에 무슨 일로 오셨는지는 몰라도 와 주셔서 정말 기쁩니다. 당신이 아니었다면 우리는 노예가 되거나... 더 심한 꼴을 당했을 겁니다.', `MaleText_loc4`='我不知道你为什么会来禁忌之林，但我很高兴你来了。要不是你，我们可能已经成了奴隶……或者更糟。', `MaleText_loc5`='我不知道是什麼風把你吹到禁忌叢林來的，但我很高興你來了。你拯救我們免於淪為奴隸...或者更糟的命運。', `MaleText_loc7`='No sé qué es lo que te ha traído a la Jungla Prohibida, pero me alegro de que estés aquí. Nos has salvado de la esclavitud... o de algo peor.', `FemaleText_loc1`='금지된 밀림에 무슨 일로 오셨는지는 몰라도 와 주셔서 정말 기뻐요. 당신이 아니었다면 우리는 노예가 되거나... 더 심한 꼴을 당했을 거예요.', `FemaleText_loc4`='我不知道你为什么会来禁忌之林，但我很高兴你来了。要不是你，我们可能已经成了奴隶……或者更糟。', `FemaleText_loc5`='我不知道是什麼風把你吹到禁忌叢林來的，但我很高興你來了。你拯救我們免於淪為奴隸...或者更糟的命運。', `FemaleText_loc7`='No sé qué es lo que te ha traído a la Jungla Prohibida, pero me alegro de que estés aquí. Nos has salvado de la esclavitud... o de algo peor.' WHERE `ID`=67002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 언제부터 마법 차원문을 열 수 있게 된 거지?', `MaleText_loc4`='魔古族什么时候学会了使用魔法传送门？', `MaleText_loc5`='魔古什麼時候學會用魔法傳送門了?', `MaleText_loc7`='¿Cuándo han aprendido los mogu a manejar portales mágicos?', `FemaleText_loc1`='모구가 언제부터 마법 차원문을 열 수 있게 된 거지?', `FemaleText_loc4`='魔古族什么时候学会了使用魔法传送门？', `FemaleText_loc5`='魔古什麼時候學會用魔法傳送門了?', `FemaleText_loc7`='¿Desde cuándo han aprendido los mogu a utilizar portales mágicos?' WHERE `ID`=67003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 하필 최악의 때에 공격해 왔습니다. 안 그래도 사마귀 놈들이 몰려오고 있거든요. 장벽도 소용없을 겁니다.', `MaleText_loc4`='魔古族偏偏在这个时候攻击我们。螳螂妖也不消停，即便是连长城也挡不住他们。', `MaleText_loc5`='魔古選了最糟的時機來攻擊。螳螂人們行動了，即使是巨大的長城也無法使他們停下來。', `MaleText_loc7`='Los mogu han elegido el peor momento para atacar. Los mántides están de camino, y ni siquiera la gran muralla podrá contenerlos.', `FemaleText_loc1`='모구가 하필 최악의 때에 공격해 왔어요. 안 그래도 사마귀 놈들이 몰려오고 있거든요. 장벽도 소용없을 거예요.', `FemaleText_loc4`='魔古族偏偏在这个时候攻击我们。螳螂妖也不消停，即便是连长城也挡不住他们。', `FemaleText_loc5`='魔古選了最糟的時機來攻擊。螳螂人們行動了，即使是巨大的長城也無法使他們停下來。', `FemaleText_loc7`='Los mogu han elegido el peor momento para atacar. Los mántides están de camino, y ni siquiera la gran muralla podrá contenerlos.' WHERE `ID`=67004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 꿈에 자꾸 사마귀가 나와서, 주학사에 꿈풀이를 하러 가던 길이었습니다.', `MaleText_loc4`='我们连做梦都是螳螂妖的进攻。我们希望朱鹤寺能为我们解梦。', `MaleText_loc5`='我們的夢境反覆地受到螳螂人侵擾。我們希望紅鶴寺可以針對這些夢境給我們一點開示。', `MaleText_loc7`='Los mántides se aparecen en nuestros sueños. Esperábamos que el Templo de la Grulla pudiera explicarnos estas visiones.', `FemaleText_loc1`='우리 꿈에 자꾸 사마귀가 나와서, 주학사에 꿈풀이를 하러 가던 길이었어요.', `FemaleText_loc4`='我们连做梦都是螳螂妖的进攻。我们希望朱鹤寺能为我们解梦。', `FemaleText_loc5`='我們的夢境反覆地受到螳螂人侵擾。我們希望紅鶴寺可以針對這些夢境給我們一點開示。', `FemaleText_loc7`='Los mántides se aparecen en nuestros sueños. Esperábamos que el Templo de la Grulla pudiera explicarnos estas visiones.' WHERE `ID`=67005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바콘과 이야기하면 됩니다. 고기를 잔뜩 갖고 있거든요. 그것도 아주 신선하다더군요.$B$B지도에 위치를 표시해 드리지요. 행운을 빕니다!', `MaleText_loc4`='你需要与巴空谈谈。他供应充足的肉类，听说新鲜得很。$B$B我会在你的地图上标记这个位置。祝你好运！', `MaleText_loc5`='你得去找巴空。他有充足的肉類補給，而且聽說都很新鮮。$B$B我會替你在地圖上標出位置。祝好運!', `MaleText_loc7`='Tienes que hablar con Ba''kon. Tiene un amplio surtido de carnes. He oído que son muy frescas.$B$BTe marcaré su ubicación en el mapa. ¡Buena suerte!', `FemaleText_loc1`='바콘과 이야기하면 됩니다. 고기를 잔뜩 갖고 있거든요. 그것도 아주 신선하다더군요.$B$B지도에 위치를 표시해 드리지요. 행운을 빕니다!', `FemaleText_loc4`='你需要与巴空谈谈。他供应充足的肉类，听说新鲜得很。$B$B我会在你的地图上标记这个位置。祝你好运！', `FemaleText_loc5`='你得去找巴空。他有充足的肉類補給，而且聽說都很新鮮。$B$B我會替你在地圖上標出位置。祝好運!', `FemaleText_loc7`='Tienes que hablar con Ba''kon. Tiene un amplio surtido de carnes. He oído que son muy frescas.$B$BTe marcaré su ubicación en el mapa. ¡Buena suerte!' WHERE `ID`=67006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단것이 당기시나요? 그렇다면 황설탕을 찾으셔야지요.$B$B황설탕은 보통 건물 1층을 돌아다니지만, 가끔씩은 한잔 하러 맥주창고에 들르기도 합니다.', `MaleText_loc4`='嘴馋想要吃些甜品吗？你需要找到米色糖。$B$B他通常在底层徘徊，尽管他时不时地会跑进烈酒窖里慰劳自己。', `MaleText_loc5`='忍不住想吃甜食嗎?你得去找米黃·蜜糖。$B$B他通常會在一樓那裡閒逛，但偶而也會跑去酒罈之廳那裡找東西吃。', `MaleText_loc7`='¿Te apetece algo dulce? Tienes que buscar a Azúcar Moreno.$B$BSuele estar dando vueltas por el piso de abajo, aunque a veces entra en La Bodega para darse un capricho de vez en cuando.', `FemaleText_loc1`='단것이 당기시나요? 그렇다면 황설탕을 찾으셔야지요.$B$B황설탕은 보통 건물 1층을 돌아다니지만, 가끔씩은 한잔 하러 맥주창고에 들르기도 합니다.', `FemaleText_loc4`='嘴馋想要吃些甜品吗？你需要找到米色糖。$B$B他通常在底层徘徊，尽管他时不时地会跑进烈酒窖里慰劳自己。', `FemaleText_loc5`='忍不住想吃甜食嗎?你得去找米黃·蜜糖。$B$B他通常會在一樓那裡閒逛，但偶而也會跑去酒罈之廳那裡找東西吃。', `FemaleText_loc7`='¿Te apetece algo dulce? Tienes que buscar a Azúcar Moreno.$B$BSuele estar dando vueltas por el piso de abajo, aunque a veces entra en La Bodega para darse un capricho de vez en cuando.' WHERE `ID`=67007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야... 야운골 놈들!

놈들이 내 농장과 근처의 마을, 서풍의 쉼터에 쳐들어와서 사람을 죽이고... 살아남은 사람들을 쫓아냈어요!

가까스로 이곳에 그중 몇 명을 모았어요. 혹시 빈안 마을에서 도와준다는 이야기는 없던가요?', `MaleText_loc4`='那些……野牛人！

它们袭击了我的农场，还有附近的西风之息……杀死了不少人，然后把剩下的全都赶走了！

我在这里集结了一些乡亲。滨岸村会来帮忙吗？', `MaleText_loc5`='揚古...!

他們攻擊了我的農場，還有附近的村莊，西風之眠...殺了我們一些人，然後沒死的人則被趕走了!

我設法集結了一些人，但是，濱南村那裡有消息說會來援助嗎?', `MaleText_loc7`='¡Los... los yaungol!

Han atacado mi granja y la aldea cercana, Reposo Viento del Oeste... Han matado a algunos de nosotros, y a los demás los han expulsado.

He conseguido que algunos nos reunamos aquí. ¿Se sabe si viene ayuda de Binan?' WHERE `ID`=67008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 얼라이언스의 일원입니다. 여러분을 구하고 마을을 재건하러 왔습니다.', `MaleText_loc4`='我来自联盟。我们是来救你们的，帮忙重建村庄。', `MaleText_loc5`='我來自聯盟。我們是來這裡拯救你並重建你村莊的。', `MaleText_loc7`='Soy de la Alianza. Hemos venido a salvarlos y reconstruir su aldea.', `FemaleText_loc1`='저는 얼라이언스의 일원입니다. 여러분을 구하고 마을을 재건하러 왔어요.', `FemaleText_loc4`='我来自联盟。我们是来救你们的，帮忙重建村庄。', `FemaleText_loc5`='我來自聯盟。我們是來這裡拯救你並重建你村莊的。', `FemaleText_loc7`='Soy de la Alianza. Hemos venido a salvarlos y reconstruir su aldea.' WHERE `ID`=67009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기술 전문가를 찾으십니까?$B$B달인들은 판다리아 전역에 흩어져 있습니다. 누굴 찾는지 이야기해 주세요.$B$B찾는 사람이 판다리아에 없으면, 대도시에서 찾아봐도 됩니다. 대도시의 전문가에게서도 기술을 배울 수 있으니까요.', `MaleText_loc4`='在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。', `MaleText_loc5`='在找專業技能訓練師?$B$B禪師級的訓練師散佈在潘達利亞各處。告訴我你要找誰。$B$B如果你在潘達利亞找不到你想要找的人，你可以回到主城找那裡的專業訓練師。他們應該也能增進你的技藝。', `MaleText_loc7`='¿Buscas a un instructor de profesión?$b$bLos instructores maestros zen se encuentran por toda Pandaria. Dime a quién buscas.$b$bSi no encuentras a la persona que buscas aquí, en Pandaria, siempre puedes hablar con los maestros de tu capital. También deberían poder mejorar tu habilidad en la profesión que has elegido.', `FemaleText_loc1`='기술 전문가를 찾으십니까?$B$B달인들은 판다리아 전역에 흩어져 있습니다. 누굴 찾는지 이야기해 주세요.$B$B찾는 사람이 판다리아에 없으면, 대도시에서 찾아봐도 됩니다. 대도시의 전문가에게서도 기술을 배울 수 있으니까요.', `FemaleText_loc4`='在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。', `FemaleText_loc5`='在找專業技能訓練師?$B$B禪師級的訓練師散佈在潘達利亞各處。告訴我你要找誰。$B$B如果你在潘達利亞找不到你想要找的人，你可以回到主城找那裡的專業訓練師。他們應該也能增進你的技藝。', `FemaleText_loc7`='¿Buscas a un instructor de profesión?$b$bLos instructores maestros zen se encuentran por toda Pandaria. Dime a quién buscas.$b$bSi no encuentras a la persona que buscas aquí, en Pandaria, siempre puedes hablar con los maestros de tu capital. También deberían poder mejorar tu habilidad en la profesión que has elegido.' WHERE `ID`=67010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 얼라이언스의 일원입니다. 여러분을 구하고 마을을 재건하러 왔습니다.', `MaleText_loc4`='我来自联盟。我们是来救你们的，帮忙重建村庄。', `MaleText_loc5`='我來自聯盟。我們是來這裡拯救你並重建你村莊的。', `MaleText_loc7`='Soy de la Alianza. Hemos venido a salvarlos y reconstruir su aldea.', `FemaleText_loc1`='저는 얼라이언스의 일원입니다. 여러분을 구하고 마을을 재건하러 왔어요.', `FemaleText_loc4`='我来自联盟。我们是来救你们的，帮忙重建村庄。', `FemaleText_loc5`='我來自聯盟。我們是來這裡拯救你並重建你村莊的。', `FemaleText_loc7`='Soy de la Alianza. Hemos venido a salvarlos y reconstruir su aldea.' WHERE `ID`=67011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장벽 너머 공포의 황무지에 사는 클락시 중에 연금술의 대가가 있다고 하더군요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。', `MaleText_loc5`='我聽說卡拉西有大師級的鍊金師。就在長城之後的遙遠悚然荒野裡。我會替你在地圖上標記出位置。', `MaleText_loc7`='He oído que algunos Klaxxi son maestros alquimistas, al otro lado de la muralla, en el Desierto del Pavor. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='장벽 너머 공포의 황무지에 사는 클락시 중에 연금술의 대가가 있다고 하더군요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。', `FemaleText_loc5`='我聽說卡拉西有大師級的鍊金師。就在長城之後的遙遠悚然荒野裡。我會替你在地圖上標記出位置。', `FemaleText_loc7`='He oído que algunos Klaxxi son maestros alquimistas, al otro lado de la muralla, en el Desierto del Pavor. Te marcaré su ubicación en el mapa.' WHERE `ID`=67012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 영원꽃 골짜기에 있는 모구샨 궁전 위, 지식의 연단에 고고학의 대가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='知識之座那裡有一名考古學大師，就在恆春谷的魔古山宮之上。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un maestro arqueólogo en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='이곳 영원꽃 골짜기에 있는 모구샨 궁전 위, 지식의 연단에 고고학의 대가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='知識之座那裡有一名考古學大師，就在恆春谷的魔古山宮之上。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un maestro arqueólogo en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달인 라오를 찾으시는군요! 라오는 영원꽃 골짜기에 있는 석양 주둔지에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='你要找的肯定是廖禪師!他就在恆春谷的落陽要塞工作。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='¡Creo que buscas al maestro zen Lao! Trabaja en el Baluarte del Sol Poniente, en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='달인 라오를 찾으시는군요! 라오는 영원꽃 골짜기에 있는 석양 주둔지에서 일합니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='你要找的肯定是廖禪師!他就在恆春谷的落陽要塞工作。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='¡Creo que buscas al maestro zen Lao! Trabaja en el Baluarte del Sol Poniente, en el Valle de la Flor Eterna.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요리 기술을 배우고 싶으신가요?$B$B그렇다면 아이언포우 가문을 찾아가셔야 합니다. 네 바람의 계곡, 언덕골 시장에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。', `MaleText_loc5`='想增進廚藝技能，是嗎?$B$B你該去找鐵爪家的人。他們就住在四風峽的半丘市集。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='¿Te interesa mejorar tus dotes culinarias?$b$bDeberías hablar con la familia Zarpa Férrea. Se encuentran en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='요리 기술을 배우고 싶으신가요?$B$B그렇다면 아이언포우 가문을 찾아가셔야 합니다. 네 바람의 계곡, 언덕골 시장에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。', `FemaleText_loc5`='想增進廚藝技能，是嗎?$B$B你該去找鐵爪家的人。他們就住在四風峽的半丘市集。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='¿Te interesa mejorar tus dotes culinarias?$b$bDeberías hablar con la familia Zarpa Férrea. Se encuentran en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법부여에 관해서라면, 비취 숲, 새벽의 꽃에 있는 마법손 라이와 이야기하면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='關於附魔的需求，你得去翠玉林的晨綻找『術爪』籟。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Para cualquier tema relacionado con el encantamiento, deberías hablar con Lai Zarpa Hechicera en Floralba, en el Bosque de Jade.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='마법부여에 관해서라면, 비취 숲, 새벽의 꽃에 있는 마법손 라이와 이야기하면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='關於附魔的需求，你得去翠玉林的晨綻找『術爪』籟。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Para cualquier tema relacionado con el encantamiento, deberías hablar con Lai Zarpa Hechicera en Floralba, en el Bosque de Jade.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='찾으시는 사람은 네 바람의 계곡, 네싱워리 탐험대에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='你要找的人就在四風峽的奈辛瓦里狩旅團。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='La persona que buscas se encuentra en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='찾으시는 사람은 네 바람의 계곡, 네싱워리 탐험대에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='你要找的人就在四風峽的奈辛瓦里狩旅團。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='La persona que buscas se encuentra en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 있다는 게 감사히 느껴지는 멋진 날이로군요, 안 그렇습니까?', `MaleText_loc4`='真是美好的一天啊，不是吗？', `MaleText_loc5`='能夠活下來真好，不是嗎?', `MaleText_loc7`='Es un día maravilloso para seguir con vida, ¿verdad?' WHERE `ID`=67018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 앞을 보십시오. 절대 뒤돌아보면 안 됩니다.', `MaleText_loc4`='凡事向前看，不要回头。', `MaleText_loc5`='永遠像前看，別向後看。', `MaleText_loc7`='Mira siempre hacia delante, nunca hacia atrás.' WHERE `ID`=67019;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마노 운룡을 본 적이 있나요? 바람맞이 섬에 알을 낳는다고 하던데요. 그 알을 발견하거든 안리 장로님께 가져다 드리세요. 두둑한 보상을 받을 수 있을 거예요.', `FemaleText_loc4`='你见过玛瑙翔龙吗？它们会在临风岛上产卵。要是你能把龙蛋带给安离长老，一定能得到应有的回报。', `FemaleText_loc5`='你有看到瑪瑙蛟嗎?牠們會在嘯風島上下蛋。如果你找到這樣的蛋，請帶去給安麗長老，你會得到應得的報酬。', `FemaleText_loc7`='¿Has visto los dragones de ónice? Ponen sus huevos en la Isla de Barlovento. Si encuentras uno y se lo llevas a la ancestro Anli, te recompensará como es debido.' WHERE `ID`=67020;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘 경주에 참여해 보신 적 있나요? 참여하실 생각이라면, 행운을 빌게요.', `FemaleText_loc4`='你参加飞行竞技赛了吗？祝你好运。', `FemaleText_loc5`='你有加入天際競賽嗎?如果有的話，祝你好運。', `FemaleText_loc7`='¿Has participado en la carrera de los cielos? Si vas a participar, te deseo suerte.' WHERE `ID`=67021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하, 알라시넬을 찾으시는군요. 두 달의 제단 안으로 가시면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='噢是的，你一定是在找艾拉西尼尔。她就在双月殿里。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='喔是了，你該去找艾拉欣娜。你可以在雙月廟裡找到她。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Ah, sí, buscas a Ala''thinel. La encontrarás dentro del Santuario de las Dos Lunas.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아하, 알라시넬을 찾으시는군요. 두 달의 제단 안으로 가시면 됩니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='噢是的，你一定是在找艾拉西尼尔。她就在双月殿里。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='喔是了，你該去找艾拉欣娜。你可以在雙月廟裡找到她。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Ah, sí, buscas a Ala''thinel. La encontrarás dentro del Santuario de las Dos Lunas.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑 밀림의 강태공 부두에 있는 내트 페이글을 찾아가면 낚시 기술을 배울 수 있습니다. 위치를 표시해 드리지요.', `MaleText_loc4`='你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。', `MaleText_loc5`='你可以前往喀撒朗蠻荒的釣手泊船處，找納特·帕格來提升你的釣魚技能。讓我替你在地圖上標記出來。', `MaleText_loc7`='Para mejorar tu habilidad en pesca, visita a Nat Pagle en el Muelle de los Pescadores, en la Espesura Krasarang. Te señalaré dónde está.', `FemaleText_loc1`='크라사랑 밀림의 강태공 부두에 있는 내트 페이글을 찾아가면 낚시 기술을 배울 수 있습니다. 위치를 표시해 드리지요.', `FemaleText_loc4`='你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。', `FemaleText_loc5`='你可以前往喀撒朗蠻荒的釣手泊船處，找納特·帕格來提升你的釣魚技能。讓我替你在地圖上標記出來。', `FemaleText_loc7`='Para mejorar tu habilidad en pesca, visita a Nat Pagle en el Muelle de los Pescadores, en la Espesura Krasarang. Te señalaré dónde está.' WHERE `ID`=67023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 영원꽃 골짜기, 지식의 연단에 주문각인 전문가가 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。', `MaleText_loc5`='是的，在恆春谷的知識之座有一名銘文學訓練師。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Sí, conozco a un instructor de inscripción en el Trono del Saber, en el Valle de la Flor Eterna.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 영원꽃 골짜기, 지식의 연단에 주문각인 전문가가 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。', `FemaleText_loc5`='是的，在恆春谷的知識之座有一名銘文學訓練師。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Sí, conozco a un instructor de inscripción en el Trono del Saber, en el Valle de la Flor Eterna.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 세공사 마이를 찾으시는군요. 마이는 비취 숲에 있는 녹옥 마을에 삽니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='你可以去找『塑玉者』梅。她就在翠玉林的綠石村。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Buscas a Mai, la Moldeadora de Jade. La encontrarás en la Aldea Verdemar, en el Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='비취 세공사 마이를 찾으시는군요. 마이는 비취 숲에 있는 녹옥 마을에 삽니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='你可以去找『塑玉者』梅。她就在翠玉林的綠石村。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Buscas a Mai, la Moldeadora de Jade. La encontrarás en la Aldea Verdemar, en el Bosque de Jade.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 보기보다는 좋은 일이 더 많았습니다.', `MaleText_loc4`='事情总没有看上去那么糟。', `MaleText_loc5`='事情總是沒表面上看起來那麼糟。', `MaleText_loc7`='Las cosas siempre son mejores de lo que parecen.' WHERE `ID`=67026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='채광의 대가는 비취 숲의 녹옥 채석장에 있습니다. 아마 그들에게서 기술을 배울 수 있을 겁니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='采矿大师就在翡翠林的绿石采掘场。他们也许能帮你提升技能。我会在你的地图上标出他们的位置。', `MaleText_loc5`='在翠玉林的綠石採石場有採礦大師。他們應該能幫你增進技能。我會替你在地圖上標記出來。', `MaleText_loc7`='Hay maestros mineros en la Cantera Verdemar, en el Bosque de Jade. Seguro que pueden ayudarte a mejorar tu habilidad. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='채광의 대가는 비취 숲의 녹옥 채석장에 있습니다. 아마 그들에게서 기술을 배울 수 있을 겁니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='采矿大师就在翡翠林的绿石采掘场。他们也许能帮你提升技能。我会在你的地图上标出他们的位置。', `FemaleText_loc5`='在翠玉林的綠石採石場有採礦大師。他們應該能幫你增進技能。我會替你在地圖上標記出來。', `FemaleText_loc7`='Hay maestros mineros en la Cantera Verdemar, en el Bosque de Jade. Seguro que pueden ayudarte a mejorar tu habilidad. Te marcaré su ubicación en el mapa.' WHERE `ID`=67027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡, 네싱워리 탐험대에 무두질 전문가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='在四風峽的奈辛瓦里狩旅團有一名剝皮訓練師。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Hay un instructor de desuello en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='네 바람의 계곡, 네싱워리 탐험대에 무두질 전문가가 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='在四風峽的奈辛瓦里狩旅團有一名剝皮訓練師。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Hay un instructor de desuello en el Safari Nesingwary, en el Valle de los Cuatro Vientos.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 바람의 계곡, 비단촌에 있는 비단장인 차이를 찾으시는군요. 위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。', `MaleText_loc5`='到四風峽的絲綢場找絲綢大師老蔡。我會替你在地圖上標記出位置。', `MaleText_loc7`='Buscas al maestro de seda Tsai, en los Campos de Seda, en el Valle de los Cuatro Vientos. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='네 바람의 계곡, 비단촌에 있는 비단장인 차이를 찾으시는군요. 위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。', `FemaleText_loc5`='到四風峽的絲綢場找絲綢大師老蔡。我會替你在地圖上標記出位置。', `FemaleText_loc7`='Buscas al maestro de seda Tsai, en los Campos de Seda, en el Valle de los Cuatro Vientos. Te marcaré su ubicación en el mapa.' WHERE `ID`=67029;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 운룡이 다가오는군요, $n. 준비를 마치고 운룡에 올라타면 시작하겠습니다.', `FemaleText_loc4`='你的云端翔龙来了，$n。等你准备好就骑到它背上，我们开始。', `FemaleText_loc5`='你的雲蛟接近了，$n。準備好時就跳上來，好讓我們開始喔。', `FemaleText_loc7`='Tu dragón nimbo se acerca, $n. Cuando estés $glisto:lista;, sube y empezaremos.' WHERE `ID`=67030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 쇼미를 잘못 생각하고 있었던 것 같아요...', `MaleText_loc4`='我想我对朔弥的看法是错的……', `MaleText_loc5`='看來我對琇蜜的想法錯了...', `MaleText_loc7`='Creo que me equivoqué con Shomi...' WHERE `ID`=67031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장로님들 말씀이 맞았어요. 표지를 보고 책을 판단하면 안 된다는 거요.', `MaleText_loc4`='长者们说得对——人确实不可貌相。', `MaleText_loc5`='長老說的沒錯，我們不該以貌取人。', `MaleText_loc7`='Los ancestros tienen razón, no hay que juzgar por las apariencias.' WHERE `ID`=67032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇼미가 저한테도 싸우는 법을 가르쳐 줄까요?', `MaleText_loc4`='你觉得朔弥能向我展示她的战技吗？', `MaleText_loc5`='你覺得琇蜜會願意教教我她戰鬥的本事嗎?', `MaleText_loc7`='¿Crees que Shomi me enseñará sus facultades de combate?' WHERE `ID`=67033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 이런 말 했다곤 하지 마세요. 근데 쇼미가 마을을 지키는 데 정말 큰 몫을 한 것 같아요.', `MaleText_loc4`='别让她知道我说过这些，可我认为朔弥确实将村庄守得很好。', `MaleText_loc5`='別告訴她是我講的，但我覺得琇蜜在保衛村子的行動中表現得很出色。', `MaleText_loc7`='No le cuentes que te lo he dicho, pero creo que Shomi hizo un trabajo estupendo al defender la aldea.' WHERE `ID`=67034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 내가 잡을 거야!', `MaleText_loc4`='我要抓住你！', `MaleText_loc5`='我會逮住你!', `MaleText_loc7`='¡Te atraparé!' WHERE `ID`=67035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메이, 천천히 가. 나 힘들어!', `MaleText_loc4`='慢点儿，梅，我累了！', `MaleText_loc5`='慢一點，小美，我累了!', `MaleText_loc7`='¡Para ya, Mei, me estoy cansando!' WHERE `ID`=67036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네가 이기게 해주려고 그러는 것뿐이야.', `MaleText_loc4`='我是故意让你赢的。', `MaleText_loc5`='我是讓你的。', `MaleText_loc7`='Te estoy dejando ganar.' WHERE `ID`=67037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 나 신발에 돌 들어갔어.', `MaleText_loc4`='哎呦，我鞋里有颗石子。', `MaleText_loc5`='喔，我鞋子裡有個石頭。', `MaleText_loc7`='Ay, se me ha metido una piedra en el zapato.' WHERE `ID`=67038;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='메롱! 못 잡을걸!', `FemaleText_loc4`='啦啦！你抓不到我！', `FemaleText_loc5`='哈!你抓不到我!', `FemaleText_loc7`='¡Ja! ¡No puedes!' WHERE `ID`=67039;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쫓아와봐, 이 느림보 멍청아!', `FemaleText_loc4`='来呀，瞧你慢的！', `FemaleText_loc5`='來啊，你這個慢烏龜!', `FemaleText_loc7`='¡Venga, lentorro!' WHERE `ID`=67040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 시작도 안 했어!', `FemaleText_loc4`='我压根就没认真！', `FemaleText_loc5`='我根本還沒開始耶!', `FemaleText_loc7`='¡Apenas me esfuerzo!' WHERE `ID`=67041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로, 넌 나 못 잡아!', `FemaleText_loc4`='你抓不到我，罗！', `FemaleText_loc5`='你抓不到我的!樓!', `FemaleText_loc7`='¡No puedes atraparme, Lo!' WHERE `ID`=67042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 놈들과 같이 죽어라, 노예 놈아!', `MaleText_loc4`='跟其他人一块去死吧，奴隶！', `MaleText_loc5`='和其他人一樣去死吧，奴隸!', `MaleText_loc7`='¡Muere como el resto, esclavo!' WHERE `ID`=67043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노예들을 쿤라이 봉우리로 끌고 가라! 차원문을 열어라!', `MaleText_loc4`='把这些奴隶送到昆莱山！打开传送门！', `MaleText_loc5`='把這些奴隸送去崑萊峰!打開傳送門!', `MaleText_loc7`='¡Llevad estos esclavos a la Cima Kun-Lai! ¡Abrid el portal!' WHERE `ID`=67044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께 하루라도 빨리 유물을 전해야 한다.', `MaleText_loc4`='主人等这些神器已经等得不耐烦了。', `MaleText_loc5`='主人等不及要得到這些古物。', `MaleText_loc7`='El maestro no puede esperar más tiempo por estos artefactos.' WHERE `ID`=67045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 봉우리로 통하는 차원문을 열어라! 이 멍청이들아! 빨리!', `MaleText_loc4`='打开通往昆莱山的传送门，你们这群蠢货！赶快！', `MaleText_loc5`='打開通往崑萊峰的傳送門，蠢蛋!快點!', `MaleText_loc7`='¡Abran el portal a la Cima Kun-Lai, imbéciles! ¡Rápido!' WHERE `ID`=67046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 노예! 너 따위 죽으나 사나 내겐 똑같다.', `MaleText_loc4`='安静点，奴隶！你们活着跟死了没什么两样。', `MaleText_loc5`='安靜點，奴隸!搞清楚，你要是死了，我們可是一點損失都沒有。', `MaleText_loc7`='¡Silencio, esclavo! Vales lo mismo muerto que vivo.' WHERE `ID`=67047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 실력이 녹슬고 있네... 내 자물쇠따개도 그렇고. 부탁인데, 런한테는 날 여기서 봤다고 말하지 말아 주게.', `MaleText_loc4`='我的技术大不如前……开锁工具显然也生锈了。帮我个忙，别让任知道你在这里找到我了，行吗？', `MaleText_loc5`='我的開鎖工具生鏽了...我的功夫也不靈光了。幫個忙，別讓倫知道你是在這裡找到我的，好嗎?', `MaleText_loc7`='Estoy un poco oxidado... al igual que mis ganzúas, por lo que parece. Hazme un favor y no le digas a Ren que me has encontrado aquí.' WHERE `ID`=67048;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러니까 운이 하나도 안 따라줬다는 거죠?', `FemaleText_loc4`='看来你又是空手而归？', `FemaleText_loc5`='看來你是沒什麼收穫?', `FemaleText_loc7`='¿Deduzco que no estás teniendo suerte?' WHERE `ID`=67049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘 뭐라도 건졌나요? 아직 제게 가져온 게 하나도 없어요.', `FemaleText_loc4`='今天有收获吗？你还是什么都没带回来呢。', `FemaleText_loc5`='今天成果如何?你一直沒有帶東西回來。', `FemaleText_loc7`='¿Hay suerte? Todavía no has traído ningún pez.' WHERE `ID`=67050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또... 낚시를 하시네요. 어제보다는 많이 낚으셨나요?', `FemaleText_loc4`='我见你又在钓鱼了……运气有没有比昨天好一点？', `FemaleText_loc5`='我看見你...又在釣魚了。運氣有比昨天好嗎?', `FemaleText_loc7`='Veo que estás pescando... Otra vez. ¿Te va mejor que ayer?' WHERE `ID`=67051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 행운의 키스를 해드릴게요. 필요할 것 같아서요.', `FemaleText_loc4`='这是一个好运之吻，相信会对你有所帮助。', `FemaleText_loc5`='給你個幸運之吻，我想你需要它。', `FemaleText_loc7`='Toma, un beso de buena suerte. Creo que te hace falta.' WHERE `ID`=67052;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고기만 몇 마리라도 더 잡았더라면, 날마다 허탕을 쳐도 상관 안 했을 거예요.', `FemaleText_loc4`='要是你能多抓几条鱼回来，我也不会怪你终日虚度光阴。', `FemaleText_loc5`='只要你能抓多點魚，我不介意你浪費幾天時間。', `FemaleText_loc7`='No me importaría que perdieras el tiempo todo el día si al menos pescaras algún pez.' WHERE `ID`=67053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낚시 솜씨만 보고 결혼 안 했기를 천만 다행이네요...', `FemaleText_loc4`='还好我当初不是因为你的钓鱼技术才嫁给你的……', `FemaleText_loc5`='幸好我不是嫁給你的釣魚技巧...', `FemaleText_loc7`='Alégrate de que no me casara contigo por tus dotes como pescador...' WHERE `ID`=67054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 우리에 갇혀서 오랫동안 모구를 관찰했는데, 여자 모구는 한 번도 못 본 것 같네. 어떻게 그럴 수가 있지?', `MaleText_loc4`='你知道，我一直被困在这笼子里，看着魔古的一举一动，可我相当肯定，自己从没见过魔古女孩。那是为什么？', `MaleText_loc5`='你知道嗎，我已經被關在這些牢籠裡看著魔古很多次了，但我很確定我從來沒看到一個魔古女孩。那是怎麼回事?', `MaleText_loc7`='¿Sabes una cosa? Llevo un buen rato en esa jaula, observando a los mogu, pero creo que no he visto a ninguna mujer mogu. ¿Y eso?' WHERE `ID`=67055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구한테 잡혔을 때, 나는 황금 연못에다 실례를 하고 있었지. 업보라고 할 수 있으려나?', `MaleText_loc4`='我被他们抓住时，正在其中一个金色池塘边解决内急问题。我想这就叫因果报应吧。', `MaleText_loc5`='他們抓到我的時候我正在一個黃金池子裡放鬆自己。我猜你可以說這是報應。', `MaleText_loc7`='Estaba respondiendo a la llamada de la naturaleza en una de esas pozas doradas cuando me pillaron. Supongo que fue una captura kármica.' WHERE `ID`=67056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='런이 내가 모구 대포를 하나도 못 훔친다는 데 돈을 걸었다네. 나라고 그게 그렇게 무거울 줄 알았겠나!', `MaleText_loc4`='任说我肯定连一个魔古炮弹都偷不到。我怎么知道它们竟然这么重！', `MaleText_loc5`='倫賭我沒辦法偷到一座魔古火砲。我沒想到它們會那麼重!', `MaleText_loc7`='Ren se apostó que yo no podría robar un cañón mogu. ¡No pensé que fueran tan pesados!' WHERE `ID`=67057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 맹세하는데, 다시는 잡히지 않을 걸세.', `MaleText_loc4`='那是我最后一次被他们抓住了，我保证。', `MaleText_loc5`='那會是我最後一次讓他們抓到我了，我保證。', `MaleText_loc7`='Te prometo que es la última vez que me dejo atrapar.' WHERE `ID`=67058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 오래 걸렸나? 이번에는 날 구할 사람을 안 보내려는 줄 알았지 뭔가... 심장이 조금 쪼그라들었다네.', `MaleText_loc4`='你怎么耽搁了这么久？我差点以为他们这次不会派人来救我了……有点心灰意冷。', `MaleText_loc5`='你怎麼那麼慢?我還以為他們這次不會派人來救我了...害我的心臟都快嚇停了。', `MaleText_loc7`='¿Por qué has tardado tanto? Esta vez casi pensé que ya no iban a mandar a nadie a por mí... El corazón me dio un vuelco.' WHERE `ID`=67059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 알아낸 게 있는데 말야, 모구 놈들은 잠이 얕더군. 다른 사람한테도 전하게나.', `MaleText_loc4`='我总结出来一条规律，魔古都睡得不沉。去转告别人吧。', `MaleText_loc5`='我在心裡記住了一點，魔古很少睡覺。記得要告訴別人。', `MaleText_loc7`='Me apunté una nota mental: los mogu tienen el sueño ligero. Pásalo.' WHERE `ID`=67060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사지를 펴니 기분이 참 좋군! 우리 안이 너무 좁았다네. 모구 녀석들, 좀 널찍한 우리에 투자를 해야겠어!', `MaleText_loc4`='终于能伸展筋骨了！在里面只能缩着。他们真该花钱造些大点的笼子！', `MaleText_loc5`='能舒展筋骨感覺真好!裡面實在有夠擠。他們真的應該花點錢打造更寬敞的牢籠。', `MaleText_loc7`='¡Es un placer poder estirarse! Estaba de lo más agarrotado. ¡Deberían invertir en jaulas más espaciosas!' WHERE `ID`=67061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네!', `MaleText_loc4`='谢谢！', `MaleText_loc5`='謝啦!', `MaleText_loc7`='¡Gracias!' WHERE `ID`=67062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 저 애들은 지치지도 않네!', `FemaleText_loc4`='啊，这些孩子永远是精力旺盛！', `FemaleText_loc5`='唉，這些孩子的精力永遠用不完!', `FemaleText_loc7`='¡Ah, estos niños no se cansan nunca!' WHERE `ID`=67063;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='떨어져서 무릎 깨져도 나한테 와서 울지 마!', `FemaleText_loc4`='要是摔倒了，擦破膝盖，可别跑来对着我哭鼻子！', `FemaleText_loc5`='摔倒膝蓋擦破皮了可別來跟我哭!', `FemaleText_loc7`='¡No vengan llorando cuando se caigan y se raspen las rodillas!' WHERE `ID`=67064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하루 종일 저러고 논답니다. 보는 것만으로도 지치겠어요.', `FemaleText_loc4`='他们整天如此。照看他们真是让我精疲力尽。', `FemaleText_loc5`='他們整天都這樣，我光看就累了。', `FemaleText_loc7`='Se pasan todo el día así. Me canso solo de verlos.' WHERE `ID`=67065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직까지는 그리 많지 않아. 하지만 아직 시간은 많으니까.', `MaleText_loc4`='目前还没钓到什么，可时间还早。', `MaleText_loc5`='還沒什麼收穫，不過今天時間還早就是。', `MaleText_loc7`='No mucho, de momento, pero el día es joven.' WHERE `ID`=67066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물속에서 꼬물거리는 게 보이는데, 입질을 안 하는구먼!', `MaleText_loc4`='我看见它们在水里游来游去，可就是不咬线！', `MaleText_loc5`='我看到有魚在水裡游來游去，偏偏就是不肯咬餌!', `MaleText_loc7`='Los veo nadar por el agua, ¡pero no pican!' WHERE `ID`=67067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 정말 없군. 내 미끼 말이야.', `MaleText_loc4`='还是运气不佳。我想是鱼饵的问题。', `MaleText_loc5`='沒釣到什麼東西，我想可能是我的釣餌有問題。', `MaleText_loc7`='No he tenido mucha suerte. Creo que es por el cebo.' WHERE `ID`=67068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 비상 부표가 필요합니다, 아리에.', `MaleText_loc4`='请再给我一个应急浮标，阿林。', `MaleText_loc5`='我還需要一個緊急浮標，艾利。', `MaleText_loc7`='Me vendría bien otra boya de emergencia, Arie.', `FemaleText_loc1`='또 다른 비상 부표가 필요해요, 아리에.', `FemaleText_loc4`='请再给我一个应急浮标，阿林。', `FemaleText_loc5`='我還需要一個緊急浮標，艾利。', `FemaleText_loc7`='Me vendría bien otra boya de emergencia, Arie.' WHERE `ID`=67069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억하세요. 통과 지점 10곳을 지나간 후, 결승선 밑을 통과해야 해요.', `FemaleText_loc4`='记住——飞过10个检查点旗帜，然后从下方穿过终点线。', `FemaleText_loc5`='記好，先穿過10個檢查點旗幟，然後從終點線下方飛過。', `FemaleText_loc7`='Recuerda: atraviesa 10 banderas de punto de control y luego vuela bajo la línea de meta.' WHERE `ID`=67070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 삼각형 깃발들이 경주 경로를 표시하고 있지만, 다른 경로를 지나가도 불이익을 받지는 않아요.', `FemaleText_loc4`='我们用三角旗围出了赛道，但如果你选择其它飞行路线，也不会受到惩罚。', `FemaleText_loc5`='賽道由錦旗標示，不過你要是有本事找出別的捷徑也不會受罰。', `FemaleText_loc7`='Las grímpolas marcan el recorrido de la carrera, pero no se te penalizará por encontrar otras rutas.' WHERE `ID`=67071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오히려 다른 길이 더 빠를 수도 있죠.', `FemaleText_loc4`='你也许会发现其它捷径。', `FemaleText_loc5`='其他的路線說不定反而還會更快。', `FemaleText_loc7`='A lo mejor hay rutas más rápidas.' WHERE `ID`=67072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 경주로의 일부만 보여드린 거예요. 이제 결승선을 보시죠. 절 따라오세요!', `FemaleText_loc4`='我已经带你看过了部分赛道。现在让我们去瞧瞧终点线吧。跟我来！', `FemaleText_loc5`='我已經帶你參觀過比賽場地了，接著我們再去看看終點線吧。跟著我走!', `FemaleText_loc7`='Te he enseñado una parte de la carrera. Ahora veamos la línea de meta. ¡Sígueme!' WHERE `ID`=67073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억하세요. 실제 경주에서는 운룡단의 다른 수련생들과 경쟁해야 해요.', `FemaleText_loc4`='记住，在真实比赛中，你要与骑士团的其它受训者同场竞技。', `FemaleText_loc5`='記著，在正式比賽中，你將會與其他雲蛟衛的受訓弟子比賽。', `FemaleText_loc7`='Recuerda: en la carrera de verdad, competirás contra los demás alumnos de la Orden.' WHERE `ID`=67074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기가 결승선이에요. 통과 지점 10곳을 지나간 후, 결승선 밑을 통과하면 순위가 결정되죠.', `FemaleText_loc4`='这就是终点线。在你飞过所有10个检查点之后，从下方穿过终点线，以锁定排名。', `FemaleText_loc5`='這裡就是終點線。在你飛過10個檢查點之後，從終點線下方飛過來決定你的排名。', `FemaleText_loc7`='Esta es la línea de meta. Cuando hayas atravesado los 10 puntos de control, vuela bajo la línea de meta para confirmar tu posición.' WHERE `ID`=67075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기억하세요. 결승선 밑을 통과해야 해요!', `FemaleText_loc4`='切记，要从下方飞过终点线！', `FemaleText_loc5`='記住，要從終點線「下方」飛過去!', `FemaleText_loc7`='Recuerda: ¡vuela POR DEBAJO de la línea de meta!' WHERE `ID`=67076;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸로 이번 훈련을 마칠게요.', `FemaleText_loc4`='我们的课程结束了。', `FemaleText_loc5`='我們的課程就到此為止。', `FemaleText_loc7`='Así termina nuestra lección.' WHERE `ID`=67077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약초학을 배우고 싶으시다면 네 바람의 계곡, 언덕골 시장에 있는 한 플라워블룸과 이야기해 보십시오.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='如果你想对草药学有更深的了解，我建议你去四风谷的半山市集找韩·繁花谈谈。$B$B我会为你在地图上标出位置。', `MaleText_loc5`='如果想了解更多關於草藥學的事，我建議你去找四風峽裡，半丘市集的漢·花綻。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Si deseas aprender más sobre el arte de la herboristería, te sugiero que hables con Han Brote Florido en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='약초학을 배우고 싶으시다면 네 바람의 계곡, 언덕골 시장에 있는 한 플라워블룸과 이야기해 보십시오.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='如果你想对草药学有更深的了解，我建议你去四风谷的半山市集找韩·繁花谈谈。$B$B我会为你在地图上标出位置。', `FemaleText_loc5`='如果想了解更多關於草藥學的事，我建議你去找四風峽裡，半丘市集的漢·花綻。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Si deseas aprender más sobre el arte de la herboristería, te sugiero que hables con Han Brote Florido en el Mercado del Alcor, en el Valle de los Cuatro Vientos.$b$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 빅터 피어스는 대가의 방에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你正在寻找药剂师。他能配出真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……维克多·皮尔斯在师匠大厅出售他的商品。我会在你的地图上标记这个位置。', `MaleText_loc5`='你在找藥劑師對嗎。他能製作真的很神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...維特·皮爾斯在師匠之間裡販賣貨物。$B$B我會替你在地圖上標出位置。', `MaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... Victor Pearce vende sus productos en la Cámara de los Maestros. Te marcaré su ubicación en el mapa.', `FemaleText_loc1`='연금술사를 찾으시는군요. 정말 강력한 물약을 조제하는 연금술사가 있지요. 저도 온몸에 두드러기가 나서 찾아갔는데, 순식간에 나았지 뭡니까!$B$B에헴... 빅터 피어스는 대가의 방에서 장사를 합니다. 위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你正在寻找药剂师。他能配出真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……维克多·皮尔斯在师匠大厅出售他的商品。我会在你的地图上标记这个位置。', `FemaleText_loc5`='你在找藥劑師對嗎。他能製作真的很神奇的藥水和酊劑。我的疹子一下就消了!$B$B咳...維特·皮爾斯在師匠之間裡販賣貨物。$B$B我會替你在地圖上標出位置。', `FemaleText_loc7`='Estás buscando al boticario. Elabora unas pociones y tinturas verdaderamente increíbles. ¡Me quitó una erupción en un santiamén!$B$BEjem... Victor Pearce vende sus productos en la Cámara de los Maestros. Te marcaré su ubicación en el mapa.' WHERE `ID`=67079;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상품이 아주 푸짐할 거예요.', `FemaleText_loc4`='奖励丰厚。', `FemaleText_loc5`='獎金將會很高。', `FemaleText_loc7`='Habrá mucho en juego.' WHERE `ID`=67080;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경주를 빨리 마칠수록 더 좋은 상품을 받죠.', `FemaleText_loc4`='速度越快，奖励就越丰厚。', `FemaleText_loc5`='你越快完成比賽，得到的獎賞就越好。', `FemaleText_loc7`='Cuanto más rápido vayas, mejor será el premio.' WHERE `ID`=67081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필요한 것이 보이지 않습니까?$B$B뭘 찾으시나요? 제가 도와드리겠습니다.', `MaleText_loc4`='你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。', `MaleText_loc5`='沒在城市裡找到你需要的東西?$B$B你在找什麼?或許我能幫你。', `MaleText_loc7`='¿No has encontrado lo que buscas en la ciudad?$b$b¿Qué necesitas? A lo mejor puedo ayudarte.', `FemaleText_loc1`='필요한 것이 보이지 않습니까?$B$B뭘 찾으시나요? 제가 도와드리겠습니다.', `FemaleText_loc4`='你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。', `FemaleText_loc5`='沒在城市裡找到你需要的東西?$B$B你在找什麼?或許我能幫你。', `FemaleText_loc7`='¿No has encontrado lo que buscas en la ciudad?$b$b¿Qué necesitas? A lo mejor puedo ayudarte.' WHERE `ID`=67082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기에는 전투모병관이 없습니다.$B$B전장이나 투기장 대기열에 등록하려면 대도시로 돌아가야 합니다.', `MaleText_loc4`='在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。', `MaleText_loc5`='山谷這裡沒有戰場軍官。$B$B你必須回到主城來加入戰場或競技場的佇列。', `MaleText_loc7`='No hay maestros de batalla en el valle.$b$bSi quieres ponerte a la cola de los campos de batalla o las arenas de guerra, tendrás que volver a tu capital.', `FemaleText_loc1`='영원꽃 골짜기에는 전투모병관이 없습니다.$B$B전장이나 투기장 대기열에 등록하려면 대도시로 돌아가야 합니다.', `FemaleText_loc4`='在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。', `FemaleText_loc5`='山谷這裡沒有戰場軍官。$B$B你必須回到主城來加入戰場或競技場的佇列。', `FemaleText_loc7`='No hay maestros de batalla en el valle.$b$bSi quieres ponerte a la cola de los campos de batalla o las arenas de guerra, tendrás que volver a tu capital.' WHERE `ID`=67083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 직업 상급자를 찾으신다고요? 불행히도 영원꽃 골짜기까지 온 직업 상급자는 한 명도 없습니다.$B$B대도시에서 찾아 보시기 바랍니다.', `MaleText_loc4`='噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。', `MaleText_loc5`='喔，在找你的職業訓練師嗎?很可惜，他們沒有來到恆春谷這裡。$B$B你可以回到你的主城找他們。', `MaleText_loc7`='Ah, ¿buscas a tu instructor de clase? Por desgracia, no ha venido ninguno al Valle de la Flor Eterna.$b$bTendrás que volver a tu capital para ver a uno.', `FemaleText_loc1`='아, 직업 상급자를 찾으신다고요? 불행히도 영원꽃 골짜기까지 온 직업 상급자는 한 명도 없습니다.$B$B대도시에서 찾아 보시기 바랍니다.', `FemaleText_loc4`='噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。', `FemaleText_loc5`='喔，在找你的職業訓練師嗎?很可惜，他們沒有來到恆春谷這裡。$B$B你可以回到你的主城找他們。', `FemaleText_loc7`='Ah, ¿buscas a tu instructor de clase? Por desgracia, no ha venido ninguno al Valle de la Flor Eterna.$b$bTendrás que volver a tu capital para ver a uno.' WHERE `ID`=67084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오고, 불의 단지가 하나 더 필요합니다.', `MaleText_loc4`='傲古，再给我一个火罐。', `MaleText_loc5`='奧苟，我需要另一個火罐。', `MaleText_loc7`='Ogo, necesito otra olla de fuego.', `FemaleText_loc1`='오고, 불의 단지가 하나 더 필요해요.', `FemaleText_loc4`='傲古，再给我一个火罐。', `FemaleText_loc5`='奧苟，我需要另一個火罐。', `FemaleText_loc7`='Ogo, necesito otra olla de fuego.' WHERE `ID`=67085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형상변환이나 공허 보관소를 이용하시려면 대도시에 가셔야 합니다.', `MaleText_loc4`='你可以在自己的主城使用幻化和虚空仓库服务。', `MaleText_loc5`='你可以在你的主城裡找到塑形和虛空倉庫的服務。', `MaleText_loc7`='Los servicios de transfiguración y depósito del vacío están disponibles en tu capital.', `FemaleText_loc1`='형상변환이나 공허 보관소를 이용하시려면 대도시에 가셔야 합니다.', `FemaleText_loc4`='你可以在自己的主城使用幻化和虚空仓库服务。', `FemaleText_loc5`='你可以在你的主城裡找到塑形和虛空倉庫的服務。', `FemaleText_loc7`='Los servicios de transfiguración y depósito del vacío están disponibles en tu capital.' WHERE `ID`=67086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어느 병참장교를 찾으십니까? 제가 도움을 드릴 수 있을지도요.', `MaleText_loc4`='啊，你在找什么军需官？也许我能帮你找到他们。', `MaleText_loc5`='啊，你在找軍需官?也許我可以幫你找到他們。', `MaleText_loc7`='¿Qué intendente estás buscando? A lo mejor te puedo ayudar a encontrarlo.', `FemaleText_loc1`='아, 어느 병참장교를 찾으십니까? 제가 도움을 드릴 수 있을지도요.', `FemaleText_loc4`='啊，你在找什么军需官？也许我能帮你找到他们。', `FemaleText_loc5`='啊，你在找軍需官?也許我可以幫你找到他們。', `FemaleText_loc7`='¿Qué intendente estás buscando? A lo mejor te puedo ayudar a encontrarlo.' WHERE `ID`=67087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몸조심해요, 친구!', `FemaleText_loc4`='多加小心，朋友！', `FemaleText_loc5`='保重，朋友!', `FemaleText_loc7`='¡Cuídate, colega!' WHERE `ID`=67088;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가는 곳마다 순풍이 불기를!', `FemaleText_loc4`='愿你得到清风的眷顾！', `FemaleText_loc5`='祝你順風!', `FemaleText_loc7`='¡Que los vientos te traten bien!' WHERE `ID`=67089;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 찾아 주세요!', `FemaleText_loc4`='常回来看看！', `FemaleText_loc5`='千萬要再來!', `FemaleText_loc7`='¡No te olvides de volver pronto!' WHERE `ID`=67090;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안전한 여로 되길!', `FemaleText_loc4`='一路平安，旅行者！', `FemaleText_loc5`='一路平安，旅人!', `FemaleText_loc7`='¡Que tengas un buen viaje!' WHERE `ID`=67091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정복 병참장교와 영광의 정복 병참장교는 서쪽에 있는 용의 척추에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以在西边的蟠龙脊上找到征服军需官和精锐征服军需官。$B$B我会在你的地图上标出他们的位置。', `MaleText_loc5`='你可以在西邊的蟠龍脊找到征服點數軍需官和光榮征服點數軍需官。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Tanto el intendente de conquista como el intendente de conquista gloriosa se encuentran en el Espinazo del Dragón, al oeste.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='정복 병참장교와 영광의 정복 병참장교는 서쪽에 있는 용의 척추에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以在西边的蟠龙脊上找到征服军需官和精锐征服军需官。$B$B我会在你的地图上标出他们的位置。', `FemaleText_loc5`='你可以在西邊的蟠龍脊找到征服點數軍需官和光榮征服點數軍需官。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Tanto el intendente de conquista como el intendente de conquista gloriosa se encuentran en el Espinazo del Dragón, al oeste.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예 병참장교는 서쪽에 있는 용의 척추 장벽에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以在西边那道名为蟠龙脊的雄伟长城上找到荣誉军需官。$B$B我会为你在地图上标出位置。', `MaleText_loc5`='榮譽點數軍需官就在蟠龍脊，也就是西方那座長城。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente de honor se encuentra en el Espinazo del Dragón, la gran muralla que hay al oeste.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='명예 병참장교는 서쪽에 있는 용의 척추 장벽에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以在西边那道名为蟠龙脊的雄伟长城上找到荣誉军需官。$B$B我会为你在地图上标出位置。', `FemaleText_loc5`='榮譽點數軍需官就在蟠龍脊，也就是西方那座長城。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente de honor se encuentra en el Espinazo del Dragón, la gran muralla que hay al oeste.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탕랑 평원의 니우짜오 사원에 있는 사령관 로 핑을 찾아가면 정의의 징표로 거래를 할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='指揮官駱平可以和你交易正義印記，他就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Puedes intercambiar tus marcas de justicia con el comandante Lo Ping. Está en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='탕랑 평원의 니우짜오 사원에 있는 사령관 로 핑을 찾아가면 정의의 징표로 거래를 할 수 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='指揮官駱平可以和你交易正義印記，他就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Puedes intercambiar tus marcas de justicia con el comandante Lo Ping. Está en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹 병참장교인 사령관 옥스하트는 탕랑 평원의 니우짜오 사원에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='勇氣點數軍需官指揮官牛心就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente de valor, el comandante Corazón de Buey, se encuentra en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='용맹 병참장교인 사령관 옥스하트는 탕랑 평원의 니우짜오 사원에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='勇氣點數軍需官指揮官牛心就在螳螂荒原的怒兆寺。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente de valor, el comandante Corazón de Buey, se encuentra en el Templo de Niuzao, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더밍 아저씨가 제 생일 선물로 금붕어를 주셨어요. 이름이 스시래요.', `MaleText_loc4`='德明大叔送了我条金鱼当生日礼物。他管它叫苏石。', `MaleText_loc5`='典明大叔在生日給了我一條金魚。他叫牠壽司。', `MaleText_loc7`='El tío Deming me ha regalado un pez de colores por mi cumpleaños. Lo llama Su-Shi.' WHERE `ID`=67096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아빠가 그러는데, 제가 스시한테 먹이를 너무 많이 줘서 스시가 뚱뚱해졌대요.', `MaleText_loc4`='可爸爸说我把它喂得太饱了，于是它越长越胖。', `MaleText_loc5`='但爸爸說我給他餵太多了，讓他變得很胖。', `MaleText_loc7`='Pero papá dice que le di tanto de comer que engordó demasiado.' WHERE `ID`=67097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 어항보다 더 커져서 이 연못에다 키운답니다!', `MaleText_loc4`='胖得连碗都装不下了，所以我们只好把它养在这池塘里！', `MaleText_loc5`='他長得比魚缸還大了，所以我們現在把牠養在這池塘裡!', `MaleText_loc7`='Se volvió más grande que su pecera, ¡así que ahora lo tenemos en este estanque!' WHERE `ID`=67098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괜찮아요. 스시도 연못을 좋아하는 것 같아요.', `MaleText_loc4`='还算好。我想它喜欢这里。', `MaleText_loc5`='沒關係的。我想牠喜歡這裡。', `MaleText_loc7`='Está bien. Creo que le gusta.' WHERE `ID`=67099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스시야, 너도 여기가 좋지?', `MaleText_loc4`='你喜欢待在这儿，对吧苏石？', `MaleText_loc5`='你喜歡這裡，對不對啊，壽司?', `MaleText_loc7`='¿A que te gusta, Su-Shi?' WHERE `ID`=67100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강태공 연합 병참장교를 찾으십니까? 내트 페이글 말씀이군요. 크라사랑 밀림의 강태공 부두에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='在找釣手隊軍需官?那就是納特·帕格了。你可以在喀撒朗蠻荒的釣手泊船處找到他。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='¿Buscas al intendente de los Pescadores? Es Nat Pagle. Lo encontrarás en el Muelle de los Pescadores, en la Espesura Krasarang.$b$bTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='강태공 연합 병참장교를 찾으십니까? 내트 페이글 말씀이군요. 크라사랑 밀림의 강태공 부두에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='在找釣手隊軍需官?那就是納特·帕格了。你可以在喀撒朗蠻荒的釣手泊船處找到他。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='¿Buscas al intendente de los Pescadores? Es Nat Pagle. Lo encontrarás en el Muelle de los Pescadores, en la Espesura Krasarang.$b$bTe marcaré su ubicación en el mapa.' WHERE `ID`=67101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇지, 스시. 넌 최고의 친구야!', `MaleText_loc4`='给，苏石。你是我最好的朋友！', `MaleText_loc5`='沒錯，壽司。你是我最好的朋友!', `MaleText_loc7`='Toma, Su-Shi. ¡Eres mi mejor amigo!' WHERE `ID`=67102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 천신회 병참장교인 현자 로터스블룸은 이곳 영원꽃 골짜기에 있습니다. 황금 정원 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在金色平台的下层。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者蓮綻和其他的議員都在金輝臺的低窪地區。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente de los Augustos Celestiales está aquí, en el valle. La sabia Flor de Loto acompaña a los demás representantes de facción en la sección inferior de La Terraza Áurea.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='위대한 천신회 병참장교인 현자 로터스블룸은 이곳 영원꽃 골짜기에 있습니다. 황금 정원 아래층에 다른 병참장교와 함께 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='至尊天神军需官就在山谷里。莲蕊贤者与其他阵营的代表都在金色平台的下层。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='聖獸天尊軍需官就在這座山谷裡。賢者蓮綻和其他的議員都在金輝臺的低窪地區。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente de los Augustos Celestiales está aquí, en el valle. La sabia Flor de Loto acompaña a los demás representantes de facción en la sección inferior de La Terraza Áurea.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='텅 썬더몰트와 이야기하시면 됩니다! 그는 네 바람의 계곡, 스톰스타우트 양조장에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你应该跟邓·雷酒谈谈！他就在四风谷的风暴烈酒酿造厂。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='你得去找譚格·雷麥!你可以在四風峽的風暴烈酒酒坊找到他。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='¡Tienes que hablar con Teng Malta Tronadora! Se encuentra en la Cervecería del Trueno, en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='텅 썬더몰트와 이야기하시면 됩니다! 그는 네 바람의 계곡, 스톰스타우트 양조장에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你应该跟邓·雷酒谈谈！他就在四风谷的风暴烈酒酿造厂。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='你得去找譚格·雷麥!你可以在四風峽的風暴烈酒酒坊找到他。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='¡Tienes que hablar con Teng Malta Tronadora! Se encuentra en la Cervecería del Trueno, en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 너그러운 잘루를 찾으시는군요! 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 계단 근처를 배회하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='啊，你要找宽仁的贾鲁！他就在锦绣谷魔古山宫殿的台阶上徘徊。$B$B我会为你在地图上标出他的位置。', `MaleText_loc5`='啊，你該去找『慷慨使』賈廬!他就在這座恆春谷裡的魔古山宮的階梯上附近遊盪。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='¡Ah, buscas a Jaluu el Generoso! Suele pasear por las escaleras del Palacio Mogu''shan, aquí en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='아, 너그러운 잘루를 찾으시는군요! 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 계단 근처를 배회하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='啊，你要找宽仁的贾鲁！他就在锦绣谷魔古山宫殿的台阶上徘徊。$B$B我会为你在地图上标出他的位置。', `FemaleText_loc5`='啊，你該去找『慷慨使』賈廬!他就在這座恆春谷裡的魔古山宮的階梯上附近遊盪。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='¡Ah, buscas a Jaluu el Generoso! Suele pasear por las escaleras del Palacio Mogu''shan, aquí en el Valle de los Cuatro Vientos.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 죄송하지만 클락시에 대해서는 잘 모릅니다. 하지만 그들의 도시, 클락시베스가 공포의 황무지 서쪽 끝에 있다는 풍문은 들은 적이 있습니다. 거기 클락시 병참장교가 있을지도 모르겠네요.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='嗯，恐怕我對卡拉西所知甚少，但我曾聽說過他們的城市叫卡拉西斐斯，就坐落在遙遠西方的悚然荒野裡。也許你可以在那裡找到卡拉西軍需官。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Mmm... Me temo que no sé gran cosa sobre los Klaxxi, pero he oído rumores de que tienen una ciudad, Klaxxi''vess, muy al oeste, en el Desierto del Pavor. A lo mejor allí encontrarás al intendente de los Klaxxi.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='흠... 죄송하지만 클락시에 대해서는 잘 모릅니다. 하지만 그들의 도시, 클락시베스가 공포의 황무지 서쪽 끝에 있다는 풍문은 들은 적이 있습니다. 거기 클락시 병참장교가 있을지도 모르겠네요.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='嗯，恐怕我對卡拉西所知甚少，但我曾聽說過他們的城市叫卡拉西斐斯，就坐落在遙遠西方的悚然荒野裡。也許你可以在那裡找到卡拉西軍需官。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Mmm... Me temo que no sé gran cosa sobre los Klaxxi, pero he oído rumores de que tienen una ciudad, Klaxxi''vess, muy al oeste, en el Desierto del Pavor. A lo mejor allí encontrarás al intendente de los Klaxxi.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄 신 탸오를 찾으시는군요. 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 위, 지식의 연단에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。', `MaleText_loc5`='你該去找譚杏桃。她人在知識之座，就這座恆春谷裡的魔古山宮上。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='Buscas a Tan Shin Tiao. La encontrarás en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='탄 신 탸오를 찾으시는군요. 이곳 영원꽃 골짜기에 있는 모구샨 궁전의 위, 지식의 연단에 있습니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。', `FemaleText_loc5`='你該去找譚杏桃。她人在知識之座，就這座恆春谷裡的魔古山宮上。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='Buscas a Tan Shin Tiao. La encontrarás en el Trono del Saber, sobre el Palacio Mogu''shan, aquí en el Valle de la Flor Eterna.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡단 병참장교는 싼 레드스케일입니다.$B$B비취 숲의 도원에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='飒安·红鳞是云端翔龙骑士团的军需官。$B$B他就在翡翠林的百木园。$B$B我会在你的地图上标出他的位置。', `MaleText_loc5`='桑·紅鱗是雲蛟衛的軍需官。$B$B你可以在翠玉林的落英園找到他。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='San Escama Roja es el intendente de la Orden del Dragón Nimbo.$b$bLo encontrarás en El Arboretum, en el Bosque de Jade.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='운룡단 병참장교는 싼 레드스케일입니다.$B$B비취 숲의 도원에서 만날 수 있지요.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='飒安·红鳞是云端翔龙骑士团的军需官。$B$B他就在翡翠林的百木园。$B$B我会在你的地图上标出他的位置。', `FemaleText_loc5`='桑·紅鱗是雲蛟衛的軍需官。$B$B你可以在翠玉林的落英園找到他。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='San Escama Roja es el intendente de la Orden del Dragón Nimbo.$b$bLo encontrarás en El Arboretum, en el Bosque de Jade.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 병참장교는 탕랑 평원의 음영파 주둔지에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `MaleText_loc4`='影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。', `MaleText_loc5`='影潘軍需官就在螳螂荒原的影潘要塞。$B$B我會替你在地圖上標記出位置。', `MaleText_loc7`='El intendente del Shadopan está en el Cuartel del Shadopan, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='음영파 병참장교는 탕랑 평원의 음영파 주둔지에 있습니다.$B$B위치를 지도에 표시해 드리겠습니다.', `FemaleText_loc4`='影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。', `FemaleText_loc5`='影潘軍需官就在螳螂荒原的影潘要塞。$B$B我會替你在地圖上標記出位置。', `FemaleText_loc7`='El intendente del Shadopan está en el Cuartel del Shadopan, en las Estepas de Tong Long.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼 연합 병참장교는 지나 머드클로입니다. 언덕골에서 시장을 운영하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `MaleText_loc4`='如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。', `MaleText_loc5`='如果你在找耕者軍需官，吉娜·泥爪就是你所要找的女孩。她在半丘市集開店。$B$B讓我替你在地圖上標記出位置。', `MaleText_loc7`='Si buscas a la intendente de los Labradores, entonces Gina Zarpa Fangosa es tu chica. Estará encargándose del mercado en El Alcor.$B$BTe marcaré su ubicación en el mapa.', `FemaleText_loc1`='농사꾼 연합 병참장교는 지나 머드클로입니다. 언덕골에서 시장을 운영하고 있을 겁니다.$B$B위치를 지도에 표시해 드리지요.', `FemaleText_loc4`='如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。', `FemaleText_loc5`='如果你在找耕者軍需官，吉娜·泥爪就是你所要找的女孩。她在半丘市集開店。$B$B讓我替你在地圖上標記出位置。', `FemaleText_loc7`='Si buscas a la intendente de los Labradores, entonces Gina Zarpa Fangosa es tu chica. Estará encargándose del mercado en El Alcor.$B$BTe marcaré su ubicación en el mapa.' WHERE `ID`=67110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 제국에 맞서는 모든 이들에게 죽음을!', `FemaleText_loc4`='胆敢挑战我帝国的人都只有死路一条！', `FemaleText_loc5`='殺死所有膽敢挑戰我帝國的人!', `FemaleText_loc7`='¡Muerte a todo aquel que desafíe a mi imperio!' WHERE `ID`=67111;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자이로콥터 공격!', `FemaleText_loc4`='旋翼机出击！', `FemaleText_loc5`='旋翼機攻擊!', `FemaleText_loc7`='¡Ataque de girocóptero!' WHERE `ID`=67112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 도전합니다!', `MaleText_loc4`='我要挑战你！', `MaleText_loc5`='我挑戰你!', `MaleText_loc7`='¡Te desafío!', `FemaleText_loc1`='당신에게 도전하겠어요!', `FemaleText_loc4`='我要挑战你！', `FemaleText_loc5`='我挑戰你!', `FemaleText_loc7`='¡Te desafío!' WHERE `ID`=67113;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 자이로콥터 공격을 다시 해봐요!', `FemaleText_loc4`='让我们再试试旋翼机之击！', `FemaleText_loc5`='再試一次旋翼機攻擊!', `FemaleText_loc7`='¡Vamos a volver a probar el ataque de girocóptero!' WHERE `ID`=67114;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 생각이 나지 않네요. 자이로콥터 공격은 어때요?', `FemaleText_loc4`='我真是毫无头绪。旋翼机之击？', `FemaleText_loc5`='我沒主意了。旋翼機攻擊?', `FemaleText_loc7`='Se me han acabado las ideas. ¿Ataque de girocóptero?' WHERE `ID`=67115;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜... 어째서 그 사람을...? 우린 그저 농부일 뿐이에요... 우리가 무슨 짓을 했기에 이런 일을 겪는 걸까요?', `FemaleText_loc4`='为什么……为什么是他？我们只是淳朴的农民……怎么竟然这么倒霉？', `FemaleText_loc5`='為什麼...為什麼是他?我們只是普通的農夫...我們做了什麼要遇到這種事?', `FemaleText_loc7`='¿Por qué? ¿Por qué él? No somos más que granjeros... ¿Qué hemos hecho para merecer esto?' WHERE `ID`=67116;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자이... 로... 콥...', `FemaleText_loc4`='旋……翼……', `FemaleText_loc5`='旋...翼...', `FemaleText_loc7`='Gi... ro... cóp...' WHERE `ID`=67117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 잘못됐습니까?', `MaleText_loc4`='怎么了？', `MaleText_loc5`='發生什麼事了?', `MaleText_loc7`='¿Qué pasa?', `FemaleText_loc1`='뭐가 잘못됐나요?', `FemaleText_loc4`='怎么了？', `FemaleText_loc5`='發生什麼事了?', `FemaleText_loc7`='¿Qué pasa?' WHERE `ID`=67118;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남편이 저기 물가에 무슨 일이 일어났는지 확인하러 갔는데, 그때... 그때 그만...$B$B<걷잡을 수 없이 울음을 터뜨리는 장로 윤 수>', `FemaleText_loc4`='我丈夫想去看看水边发生了什么事。就在那时……那时……$B$B<苏云长老泣不成声。>', `FemaleText_loc5`='我丈夫想調查水邊發生了什麼事。後來就...就...就...$b$b<雲舒長者開始無法控制地啜泣起來。>', `FemaleText_loc7`='Mi marido quería ver qué pasaba en la orilla. Fue entonces cuando... cuando...$b$b<La ancestro Yoon Su se echa a llorar desconsoladamente.>' WHERE `ID`=67119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 터...', `FemaleText_loc4`='……机……', `FemaleText_loc5`='...機...', `FemaleText_loc7`='... te... ro...' WHERE `ID`=67120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저런, 울지 마십시오. 그때 무슨 일이 일어났습니까?', `MaleText_loc4`='先别哭。然后呢？', `MaleText_loc5`='拜託，別哭。後來發生了什麼事?', `MaleText_loc7`='No llores. ¿Qué pasó entonces?', `FemaleText_loc1`='저런, 울지 마세요. 그때 무슨 일이 일어났지요?', `FemaleText_loc4`='先别哭。然后呢？', `FemaleText_loc5`='拜託，別哭。後來發生了什麼事?', `FemaleText_loc7`='No llores. ¿Qué pasó entonces?' WHERE `ID`=67121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전장에서 오발된 폭탄이 우리쪽으로 날아왔어요. 저는 살아남았지만... 남편은...', `FemaleText_loc4`='一枚该死的炸弹朝我们袭来。我没死，可……我丈夫……', `FemaleText_loc5`='一顆打歪的炸彈從戰場上飛向我們。我活下來了，但...我丈夫...', `FemaleText_loc7`='Una bomba perdida de la batalla cayó sobre nosotros. Yo sobreviví, pero... mi marido...' WHERE `ID`=67122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 도망칠 겁니다.', `MaleText_loc4`='我要跑走了。', `MaleText_loc5`='我要開溜了。', `MaleText_loc7`='Me las piro.' WHERE `ID`=67123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 프란, 제가 어쩌다 보니 물뿌리개를 잃어버린 것 같습니다. 또 얻을 수 있겠습니까?', `MaleText_loc4`='呃，老方，我好像把你的洒水壶给弄丢了。能再给我一个吗？', `MaleText_loc5`='呃，弗蘭，我好像不小心弄丟了你的灑水壺。我能再跟你拿一個嗎，拜託?', `MaleText_loc7`='Eh, Fran, parece que me las he arreglado para perder tu regadera. ¿Me das otra, por favor?', `FemaleText_loc1`='아... 프란, 제가 어쩌다 보니 물뿌리개를 잃어버린 것 같아요. 또 얻을 수 있을까요?', `FemaleText_loc4`='呃，老方，我好像把你的洒水壶给弄丢了。能再给我一个吗？', `FemaleText_loc5`='呃，弗蘭，我好像不小心弄丟了你的灑水壺。我能再跟你拿一個嗎，拜託?', `FemaleText_loc7`='Eh, Fran, parece que me las he arreglado para perder tu regadera. ¿Me das otra, por favor?' WHERE `ID`=67124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 복판에 있는 웬 오두막에서 이 벌레 병을 발견했어. 대수롭지 않게 생각했는데, 이 글자가 눈에 들어왔지...', `MaleText_loc4`='我是在昆莱山上的棚屋里找到这罐虫子的。起初我也没多想，直到看见了这些字……', `MaleText_loc5`='我在崑萊當中的一間小屋找到這個蟲罐子。我原本不以為意，直到我看見那些字...', `MaleText_loc7`='He encontrado este tarro de bichos en una cabaña en pleno Kun-Lai. No me pareció importante hasta que vi las letras...' WHERE `ID`=67125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전언이 틀림없어! 뭔가 중요한 일에 대한 실마리일지도 모른다고!', `MaleText_loc4`='这一定是条信息！搞不好还是什么重大线索！', `MaleText_loc5`='那肯定是某種訊息!也許是某種重要東西的線索!', `MaleText_loc7`='¡Tiene que ser un mensaje! ¡Quizás incluso sea una pista de algo importante!' WHERE `ID`=67126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 정말 이해를 못 하는군! 종말의 예고일지도 모른다고!', `MaleText_loc4`='你不明白！这可能是末日来临的预兆！', `MaleText_loc5`='你就是不懂!這可能是末日的先兆!', `MaleText_loc7`='¡No lo pillas! ¡Podría ser el anuncio del final de los tiempos!' WHERE `ID`=67127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 글자? 아, 뚜껑에 있는 거? 누군가의 머리글자겠지, 뭐. 아무 뜻도 없을 거야.', `FemaleText_loc4`='什么字？噢，你是说盖子上的那些？可能只是别人随手乱写的。没什么深层含义。', `FemaleText_loc5`='什麼字?喔蓋子上的那些?那可能只是某個人的名字縮寫。沒什麼特殊意義。', `FemaleText_loc7`='¿Qué letras? Ah, ¿las de la tapa? No serán más que las iniciales del dueño. No significan nada.' WHERE `ID`=67128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와아우우우!!', `FemaleText_loc4`='呜哇！！', `FemaleText_loc5`='哇啊啊嘎!!', `FemaleText_loc7`='¡Aaaahh!' WHERE `ID`=67129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='웃기지 마. 벌레가 든 병일 뿐이야. 솔직히 말하면 정말 징그러워.', `FemaleText_loc4`='别搞笑了。那只是一罐虫子。对我来说简直不堪入目。', `FemaleText_loc5`='別傻了。這只是個裝滿蟲的罐子。說真的它很噁心。', `FemaleText_loc7`='No seas ridículo. Es solo un tarro lleno de bichos. Bastante asqueroso, en mi opinión.' WHERE `ID`=67130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='허튼소리! 이것 봐. 이러니 우리가 마을을 떠나면 안 된다는 거야!', `FemaleText_loc4`='胡说！看，这就是我们不该离开村子的原因！', `FemaleText_loc5`='那真是瘋話!看，這就是我們不該離開村子的原因!', `FemaleText_loc7`='¡Estás loco! ¿Ves? ¡Por eso no deberíamos salir de la aldea!' WHERE `ID`=67131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 생각!', `MaleText_loc4`='好主意！', `MaleText_loc5`='好主意!', `MaleText_loc7`='¡Buena idea!' WHERE `ID`=67132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그러시든지. 아마 계속 뱅뱅 돌기만 하고 절대 답은 못 찾을걸!', `FemaleText_loc4`='随便你。我敢说，它会带你绕上一个大圈子，然后害你一无所获！', `FemaleText_loc5`='你就做吧。我敢說那只會讓你原地繞大圈，而你永遠都不會找到答案!', `FemaleText_loc7`='Por mí, adelante. ¡Seguro que te conduce en círculos y nunca encontrarás una respuesta!' WHERE `ID`=67133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 난 이 실마리가 어디로 이어지는지 따라가겠어!', `MaleText_loc4`='好，我就跟着线索走，看看它会带我去哪儿！', `MaleText_loc5`='總之，我要跟著線索，看看會發現什麼東西。', `MaleText_loc7`='¡Pues voy a seguir la pista y ver adónde me conduce!' WHERE `ID`=67134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조심하렴, 쥔쥔! 강한 바람만 한 번 불면 바다로 끌려갈 수도 있어!', `FemaleText_loc4`='小心那东西，军军！一阵狂风就能把你卷到海里去！', `FemaleText_loc5`='小心那個東西，君君!一陣強風就可以把你颳進海裡!', `FemaleText_loc7`='¡Ten cuidado con esa cosa, Jun-Jun! ¡Un soplo de viento podría llevarte hasta el mar!' WHERE `ID`=67135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에, 두이. 물고기한테 뭘 먹인 거니?', `FemaleText_loc4`='天哪，杜宇。你喂那东西吃了什么？', `FemaleText_loc5`='我的老天啊，杜易。你都拿什麼餵那東西?', `FemaleText_loc7`='Madre mía, Duyi. ¿Qué le has dado de comer a esa cosa?' WHERE `ID`=67137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너를 먹이로 줘야겠구나!', `FemaleText_loc4`='也许我们该把你喂给那条鱼！', `FemaleText_loc5`='或許我們該拿「你」去餵那條魚!', `FemaleText_loc7`='¡A lo mejor deberíamos darte a ti de comer al pez!' WHERE `ID`=67138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물고기 밥 두이! 하하!', `FemaleText_loc4`='杜宇是鱼食！哈哈！', `FemaleText_loc5`='魚飼料杜易!哈!', `FemaleText_loc7`='¡Duyi el Aperitivo para Peces! ¡Ja!' WHERE `ID`=67139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='평화를 원한다고 주장하는 것 치고는 거 대단히 거창한 무기를 들고 있군요, 이방인.', `FemaleText_loc4`='对于心怀和平的人来说，那可真是永生难忘的武器，陌生人。', `FemaleText_loc5`='以前來求和的人而言，那真是超級令人印象深刻的武器，陌生人。', `FemaleText_loc7`='Es un arma muy imponente para alguien que viene en son de paz, $gforastero:forastera;.' WHERE `ID`=67141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 치유할 겁니다.', `MaleText_loc4`='我要治疗。', `MaleText_loc5`='我要來治療了。', `MaleText_loc7`='Me sano.' WHERE `ID`=67142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우와, 두이! 저게 뭐니?', `MaleText_loc4`='哇哦，杜宇。你拿的是什么啊？', `MaleText_loc5`='哇，杜易。你拿的是什麼?', `MaleText_loc7`='Guau, Duyi. ¿Qué tienes ahí?', `FemaleText_loc1`='우와, 두이! 저게 뭐니?', `FemaleText_loc4`='哇哦，杜宇。你拿的是什么啊？', `FemaleText_loc5`='哇，杜易。你拿的是什麼?', `FemaleText_loc7`='Guau, Duyi. ¿Qué tienes ahí?' WHERE `ID`=67143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.', `MaleText_loc4`='对我鞠躬，我们就开始。', `MaleText_loc5`='向我鞠躬，我們就可以開始。', `MaleText_loc7`='Hazme una reverencia y empezaremos.' WHERE `ID`=67144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<두이가 자랑스레 웃으며 당신을 쳐다봅니다.>', `MaleText_loc4`='<杜宇看着你，颇感自豪。>', `MaleText_loc5`='<杜易帶著驕傲的神色看著你。>', `MaleText_loc7`='<Duyi te mira con una sonrisa orgullosa.>' WHERE `ID`=67145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 오셨어요, $r님. 편안히 지내세요. 먹을 것도 마실 것도 많고, 휴식이 필요하다면 위층에 침대도 있답니다.

<마오린이 따뜻한 미소를 짓습니다.>', `FemaleText_loc4`='欢迎你，$r。不必拘束，就像在自己家里一样。这里有好酒好饭，楼上还有卧床供你休息。

<茂林热情地对你微笑。>', `FemaleText_loc5`='這裡歡迎你，$r。請盡管把這裡當家。食物和酒都很充分，樓上有可以讓你休息的床舖。

<毛琳溫暖地對你微笑。>', `FemaleText_loc7`='Te damos la bienvenida, $r. Siéntete como en casa. Hay comida y bebida de sobra, y en el piso de arriba hay una cama por si necesitas descansar.

<Maolin te sonríe con calidez.>' WHERE `ID`=67146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 마오린.', `MaleText_loc4`='谢谢你，茂林。', `MaleText_loc5`='謝謝你，毛琳。', `MaleText_loc7`='Gracias, Maolin.', `FemaleText_loc1`='고마워요, 마오린.', `FemaleText_loc4`='谢谢你，茂林。', `FemaleText_loc5`='謝謝你，毛琳。', `FemaleText_loc7`='Gracias, Maolin.' WHERE `ID`=67147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 아가씨들, 내 실력 좀 보라고!', `MaleText_loc4`='好吧，女士们！看好了！', `MaleText_loc5`='好了，女士們!看看這個!', `MaleText_loc7`='¡Muy bien, señoritas! ¡Observad!' WHERE `ID`=67149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제법인데요! 앞으로 당신을 눈여겨봐야겠습니다.', `MaleText_loc4`='真了不起！看来我得提防你了。', `MaleText_loc5`='真出色!我得多小心你了。', `MaleText_loc7`='¡Impresionante! Voy a tener que andarme con cuidado contigo.' WHERE `ID`=67150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번은 제 승리입니다, 초보 기수님!', `MaleText_loc4`='这回合我赢了，菜鸟！', `MaleText_loc5`='我贏了這一輪，菜鳥!', `MaleText_loc7`='¡Yo gano esta ronda, $gnovato:novata;!' WHERE `ID`=67151;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단한 힘을 지녔군요. 패배를 인정합니다.', `FemaleText_loc4`='你可真了不起。我认输。', `FemaleText_loc5`='你的力量十分出色。我承認失敗。', `FemaleText_loc7`='Tu poder es impresionante. Admito la derrota.' WHERE `ID`=67152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리가 당신과 거래해야 하지? 깃발 색깔을 빼면, 당신이 저 호드라는 녀석들과 다른 점이 뭐야?', `MaleText_loc4`='我们为什么要跟你做生意？除了旗帜颜色以外，你和你那些部落同伴还有什么区别？', `MaleText_loc5`='我們為什麼要跟你交易?除了旗幟的顏色，你和你的部落朋友有什麼不一樣?', `MaleText_loc7`='¿Por qué deberíamos comerciar contigo? ¿Qué te diferencia de tus amigos de la Horda, aparte del color de tu estandarte?' WHERE `ID`=67153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 이 마을의 유일한 수호자네. 이름은 추트 스리 누라고 하지.$B$B환영하네. 하지만 명상을 하던 중, 자네가 이 땅에 큰 변화를 일으키는 모습을 봤네. 걱정은 되지만, 자네가 판다리아에서 많은 것을 얻고 떠날 수 있었으면 좋겠군.', `MaleText_loc4`='我是这村庄唯一的保护者。我叫楚瑟农。$B$B我对你的到来表示欢迎，但我从冥想中得知，你此行会给这片土地带来巨大改变。希望当你离开潘达利亚时，这里会变得比从前更加美好。', `MaleText_loc5`='我是這村子的唯一保護者。我的名字是恰特·瑟里怒。$B$B歡迎你，但我的冥想已經讓我看見，你的到來會為這片土地帶來重大的改變。讓我們一起希望你會讓潘達利亞變得比你遇到它時更好。', `MaleText_loc7`='Soy el único protector de esta aldea. Me llamo Chut Sri Nu.$b$bTe doy la bienvenida, pero te advierto de que mi meditación me ha desvelado que tus viajes traerán grandes cambios a esta tierra. Esperemos que cuando te vayas Pandaria esté mejor que cuando llegaste.' WHERE `ID`=67154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조르 조르는 수호자가 아닙니까? 시장님을 보호하는 것 같습니다만.', `MaleText_loc4`='皎皎人呢？他应该保护村长。', `MaleText_loc5`='裘裘怎麼樣?他似乎在保護村長。', `MaleText_loc7`='¿Qué hay de Jor Jor? Parece que protege al alcalde.', `FemaleText_loc1`='조르 조르는 수호자가 아닌가요? 시장님을 보호하는 것 같던데.', `FemaleText_loc4`='皎皎人呢？他应该保护村长。', `FemaleText_loc5`='裘裘怎麼樣?他似乎在保護村長。', `FemaleText_loc7`='¿Qué hay de Jor Jor? Parece que protege al alcalde.' WHERE `ID`=67155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조르 조르는 네 바람의 계곡 출신이야. 농부의 아들로 태어난 그는, 자네가 온다는 말을 듣고 고향을 떠나 이곳에 왔지. 그는 자신이 전사라고 생각하지만, 그냥 거만한 꼬마일 뿐이네. 전투의 공포와 마주해본 적도 없으면서, 그 흥분된 기분만 갈망하는 녀석이라고.', `MaleText_loc4`='皎皎来自四风谷。他是个农民的孩子，一听说你到来的消息就立即从家里赶来。他觉得自己是个战士，可我敢说，他只是个自大的年轻人，渴望战斗的刺激，却不曾感受过战争带来的恐惧。', `MaleText_loc5`='裘裘來自四風峽。他是農夫的孩子，自從聽說你的事之後，就離家來到這裡。他相信自己是個戰士，但我可以跟你保證，他只是個傲慢的年輕人。渴望戰鬥的刺激卻從未體驗過其中恐怖。', `MaleText_loc7`='Jor Jor procede del Valle de los Cuatro Vientos. Es un hijo de granjero que abandonó su hogar para venir aquí cuando se enteró de que habías llegado. Se cree un guerrero, pero te aseguro que no es más que un joven arrogante. Ansía la emoción del combate porque nunca ha experimentado sus horrores.' WHERE `ID`=67156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 바람이 마을에 새로운 이가 찾아올 것임을 알려 주더군. 우리가 모두 마음을 열고 순수한 정신을 지켜내는 한, 서로에게서 많은 것을 배울 수 있을 것 같은 느낌이 드네.$B$B자네들이라면 저 호드가 그랬던 것보다는 우릴 존중해 줄 것 같군.', `MaleText_loc4`='啊，清风传达了贵客来访的消息。只要我们能保持开放的心胸，纯净的灵魂，就一定能从彼此身上获益良多。$B$B跟部落比起来，也许你的族人能给予我们更大的尊重。', `MaleText_loc5`='啊，風提到了新訪客來到村莊的消息。我感覺我們能從彼此身上學到許多，只要我們心胸保持開闊，我們的精神保持純淨。$B$B也許你的人民會比部落更加尊重我們的人。', `MaleText_loc7`='Ah, los vientos nos hablaron de los recién llegados a nuestra aldea. Creo que aprenderemos mucho los unos de los otros, siempre y cuando mantengamos la mente abierta y el espíritu puro.$b$bA lo mejor tu gente respetará a la mía más que la Horda.' WHERE `ID`=67157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아를 탐험하게. 하지만 조심하게. 이 땅은 부주의한 자에게는 엄청난 선물과 함께 엄청난 위험을 선사하니까.', `MaleText_loc4`='在探索潘达利亚时一定要心存戒备。对冒失的旅者来说，这是一片机遇与危险并存的土地。', `MaleText_loc5`='探索潘達利亞，但要提高警覺。對不經心的人來說，這片土地同時蘊藏著極大的寶藏和危險。', `MaleText_loc7`='Explora Pandaria, pero ten cuidado. Esta tierra oculta tesoros y peligros por igual para los incautos.' WHERE `ID`=67158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 발 아래의 대지는 살아 숨쉬네. 지금 당장은 자네를 잘 보듬고 있을지도 모르지만, 전쟁과 고난을 이곳에 몰고오면 자네도 똑같은 사태를 겪게 될 거야. 이게 바로 자연의 흐름이네.', `MaleText_loc4`='你脚下的大地富有生命力。别看它现在让你站得稳稳的，要是你胆敢将战祸和痛苦引来这里，它就会以牙还牙。这就是自然之道。', `MaleText_loc5`='你腳下的土地是活生生、會呼吸的。它此刻或許牢牢承載著你，但若將戰爭和苦痛帶來此處，它將會以牙還牙。這就是大自然的定律。', `MaleText_loc7`='El suelo que pisas está vivo y respira. Es posible que ahora te sostenga, pero si traes la guerra y el sufrimiento te responderá en consecuencia. Así es como funciona la naturaleza.' WHERE `ID`=67159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우우, 당신이 이길 줄 알았습니다! 전 연습을 더 해야겠어요...', `MaleText_loc4`='噢，我就知道你会赢！我还得多加练习……', `MaleText_loc5`='啊啊，我就知道你會勝利!我最好多練習一下...', `MaleText_loc7`='¡Vaya, sabía que ganarías! Será mejor que siga entrenándome...' WHERE `ID`=67160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서로 봐주기 없습니다!', `MaleText_loc4`='让我们都全力以赴！', `MaleText_loc5`='各自盡全力吧!', `MaleText_loc7`='¡Esforcémonos al máximo!' WHERE `ID`=67161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<포효 소리>', `MaleText_loc4`='<咆哮声。>', `MaleText_loc5`='<低吼。>', `MaleText_loc7`='<Ruge.>' WHERE `ID`=67162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 중에서 누가 더 뛰어난 수련생인지 겨뤄 봅시다. 결투를 신청합니다!', `MaleText_loc4`='让我们看看谁才是更出色的弟子。我要跟你决斗！', `MaleText_loc5`='看看我們之中誰才是更好的學生。我向你提出單挑!', `MaleText_loc7`='A ver cuál de los dos es el mejor estudiante. ¡Te reto a un duelo!', `FemaleText_loc1`='우리 중에서 누가 더 뛰어난 수련생인지 겨뤄 볼까요? 결투를 신청할게요!', `FemaleText_loc4`='让我们看看谁才是更出色的弟子。我要跟你决斗！', `FemaleText_loc5`='看看我們之中誰才是更好的學生。我向你提出單挑!', `FemaleText_loc7`='A ver cuál de los dos es el mejor estudiante. ¡Te reto a un duelo!' WHERE `ID`=67163;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여긴 작은 마을이에요. 하지만 우리 가족은 이 언덕 꼭대기에서 판다리아 최고의 탄산주를 만들어내고 있답니다.$B$B제가 바라는 건, 평화로운 시절이 돌아와서 곡식을 수확하고, 아이들과 다시 만나는 것 뿐이에요.', `FemaleText_loc4`='我们的村庄不大，但我家世代都在这片山上酿造潘达利亚最优质的苹果酒。$B$B我现在只想平安回去，好收割庄稼，与孩子们团聚。', `FemaleText_loc5`='我們的村子很小，但我的家族好幾代以來一直在這山間製造潘達利亞最好的蘋卉酒。$B$B我只希望和平能夠回來，讓我們可以採收作物，和我們的孩子重聚。', `FemaleText_loc7`='Nuestra aldea es pequeña, pero mi familia lleva generaciones produciendo la sidra más refinada de Pandaria sobre estas colinas.$b$bSolo deseo que vuelva la paz, para que podamos recoger la cosecha y volver a ver a nuestros hijos.' WHERE `ID`=67164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요, 친구! 제가 지금 좀 바쁩니다. 이 초보 수련생을 혼내주고 난 후에 다시 말을 걸어 주십시오!', `MaleText_loc4`='嘿，伙计！我现在有点忙。等我教训完这个菜鸟再来跟我说话！', `MaleText_loc5`='嘿兄弟!我目前有點忙。等我料理完這個菜鳥再跟我說話!', `MaleText_loc7`='¡Hola, colega! Ahora mismo estoy un poco ocupado. Hablemos cuando le haya dado una paliza a este novato.' WHERE `ID`=67165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 공격도 강력하지만, 나의 방어도 만만찮습니다!', `FemaleText_loc4`='你的攻击力很强，可我的防守更强！', `FemaleText_loc5`='你的攻擊很強，但我的防禦更強!', `FemaleText_loc7`='¡Tus ataques son fuertes, pero mis defensas lo son más!' WHERE `ID`=67166;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 집중해야 합니다. 다시 해 보십시오!', `FemaleText_loc4`='你得集中精神。再来一次！', `FemaleText_loc5`='你得更加專注。再試一次!', `FemaleText_loc7`='Te falta concentración. ¡Inténtalo de nuevo!' WHERE `ID`=67167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고기잡이는 영혼에 좋지만, 게잡이는 배에 좋지요!', `MaleText_loc4`='钓鱼能磨砺灵魂，但捕蟹能犒劳肠胃！', `MaleText_loc5`='釣魚對心靈很好，而釣螃蟹對肚皮很好!', `MaleText_loc7`='Pescar es bueno para el alma, ¡pero atrapar cangrejos es bueno para el estómago!' WHERE `ID`=67168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 예쁘지 않아요? 하늘에서 춤추는 모습이 너무 우아해요. 저도 언젠가 학처럼 우아해질 거예요.', `FemaleText_loc4`='难道不美么？如此优雅地在空中起舞。希望有一天，我也能拥有鹤般的美好气韵。', `FemaleText_loc5`='很美吧?當他在空中起舞時是這麼的優雅。有一天，我也希望擁有和鶴一樣的優雅。', `FemaleText_loc7`='¿No es precioso? Qué gracia tiene cuando baila por el cielo. Algún día me gustaría ser tan grácil como la grulla.' WHERE `ID`=67169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 보복을 유발했습니다.', `MaleText_loc4`='$n引发了反击风暴。', `MaleText_loc5`='$n造成了反擊。', `MaleText_loc7`='$n provocó Represalias.' WHERE `ID`=67170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안해요. 제가 지금은 좀 바빠서요. 아가씨들에게 멋지게 보일 수 있는 좋은 기회거든요. 이 시합에서 제가 승리하거든 다시 말을 걸어 주세요.', `MaleText_loc4`='抱歉，我现在可没空理你。这是我向那些小姐们炫耀身手的大好机会。等我打赢再来找我！', `MaleText_loc5`='抱歉，我有點心不在焉。這是我在女士們面前表現的機會。等我打贏這一場再跟我說話!', `MaleText_loc7`='Perdona, ahora mismo estoy un poco preocupado. Es mi oportunidad para fardar delante de las chicas. Hablemos cuando haya ganado el combate.' WHERE `ID`=67171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌써 포기하려는 겁니까? 당신은 제 상대가 되지 못한다는 걸 알고 있었습니다!', `MaleText_loc4`='这么快就认输了？我早知道你不是我的对手！', `MaleText_loc5`='這麼快就退出了?我就知道你沒有面對挑戰的本事!', `MaleText_loc7`='¿Ya te retiras? ¡Sabía que no estabas a la altura del desafío!' WHERE `ID`=67172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사부 키스테인이 근처의 옥룡 조각상으로 도망쳐 치유를 하려고 합니다. 치유하기 전에 감속시킨 후 패배시키십시오!', `FemaleText_loc4`='吉斯坦大师跑去附近的青龙雕像处寻求治疗。拖住她，在她伤愈前将她击败！', `FemaleText_loc5`='金士坦大師跑去附近一座玉蛟雕像進行治療了。減緩她的速度，並在她痊癒前擊敗她!', `FemaleText_loc7`='La maestra Kistane huye para sanarse en una estatua del Dragón de Jade cercana. ¡Ralentízala y derrótala antes de que pueda sanarse!' WHERE `ID`=67173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 지다니! 훈련을 더 해야겠습니다.', `MaleText_loc4`='我又输了！我得多加训练才行。', `MaleText_loc5`='我又輸了!最好繼續訓練。', `MaleText_loc7`='¡He vuelto a perder! Tengo que seguir entrenando.' WHERE `ID`=67174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 제가 이겼습니다. 훈련이 필요한 건 당신인 것 같네요.', `MaleText_loc4`='这次我赢了。看来需要多加训练的是你才对。', `MaleText_loc5`='這次我贏了。看來你才需要更多訓練。', `MaleText_loc7`='Esta vez gano yo. Parece que te toca a ti seguir entrenando.' WHERE `ID`=67175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 도전을 받고 도망치는 법은 몰라요.', `MaleText_loc4`='从决斗中逃跑可不像话。', `MaleText_loc5`='你無法逃避挑戰。', `MaleText_loc7`='No se puede huir de un desafío.' WHERE `ID`=67176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조상님들이 우리를 외부인들의 거친 손아귀에서 보호해 주시길...', `FemaleText_loc4`='愿先祖保佑我们免受这些外来者和他们暴力行径的侵扰。', `FemaleText_loc5`='願我們的祖先保佑我們不受這些外來人和他們的殘暴傷害。', `FemaleText_loc7`='Que los ancestros nos protejan de estos forasteros y sus costumbres violentas.' WHERE `ID`=67177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는 대체 뭐라는 생물인가? 아주 이상하군...', `MaleText_loc4`='你是种什么生物？真奇怪……', `MaleText_loc5`='你到底是什麼生物?真奇怪...', `MaleText_loc7`='¿Qué clase de criatura eres? Qué raro...' WHERE `ID`=67178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번에 나타났던 이방인들은 우리 아이들을 훔쳐갔네. 자네들은 뭘 훔치러 여기 온 건가? 우리 집사람인가? 아니면 우리 양조주인가?', `MaleText_loc4`='在你之前到来的陌生人偷走了我们的孩子。你又想偷什么？我们的妻子？还是美酒？', `MaleText_loc5`='上次那些新來的偷走了我們的孩子。你來這裡做什麼?為了奪取我們的妻子?我們的酒?', `MaleText_loc7`='Los últimos forasteros secuestraron a nuestros hijos. ¿Tú qué buscas? ¿Nuestras mujeres? ¿Nuestra cerveza?' WHERE `ID`=67179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 슈가 장창으로 강타를 할 준비를 합니다. 기술을 완성하기 전에 무장을 해제하십시오!', `MaleText_loc4`='许大师准备用手中的长矛发起一记重击！在他得手前将他缴械！', `MaleText_loc5`='徐大師準備要以他的長矛使出一招重擊。在他能完成前將他繳械!', `MaleText_loc7`='El maestro Hsu se prepara para golpear con fuerza con su arma de asta. ¡Desármalo antes de que termine de prepararse!' WHERE `ID`=67180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전 이곳은 평화로운 양조 마을이었네. 이제, 전쟁의 공포가 순수했던 우리 아이들마저 앗아가 버렸지.$B$B자네들의 전쟁은 다른 곳으로 가져가게, $r.', `MaleText_loc4`='这里原本是个宁静的酿酒村。可现在，恐怖的战争已经让我们的孩子失去了天真。$B$B去别处打仗吧，$r。', `MaleText_loc5`='這裡原本是個和平的釀酒村。現在，戰爭的恐怖奪走了我們孩子的天真。$B$B帶著你的戰爭到其他地方去，$r。', `MaleText_loc7`='Esta solía ser una aldea cervecera pacífica. Ahora los horrores de la guerra les han arrebatado la inocencia a nuestros hijos.$b$bLleva tu guerra a otra parte, $r.' WHERE `ID`=67181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이봐요, $n 님. 제가 지금 뭘 좀 하는 중이거든요. 방해하지 마세요!', `FemaleText_loc4`='嘿，$n，我现在正忙着呢。我得集中精神！', `FemaleText_loc5`='嘿，$n，我正忙著。我需要專心!', `FemaleText_loc7`='Hola, $n. Ahora mismo tengo un asunto entre manos. ¡Tengo que concentrarme!' WHERE `ID`=67182;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힘이 넘치네요. 한번 붙어보자고요!', `FemaleText_loc4`='我感到浑身充满了力量。来吧！', `FemaleText_loc5`='我感覺到渾身湧起一股力量。我們上吧!', `FemaleText_loc7`='Siento un subidón de energía. ¡Vamos allá!' WHERE `ID`=67183;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젠장, 내가 지다니! 으으... 너무 피곤하네요...', `FemaleText_loc4`='该死，我输了！哎呦……真累啊……', `FemaleText_loc5`='可惡，我輸了!喔...我感覺好累...', `FemaleText_loc7`='¡Maldita sea! ¡He perdido! Uf... Qué cansancio...' WHERE `ID`=67184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망치는 건가요? 제가 꽤 무섭긴 하죠!', `FemaleText_loc4`='想跑？看来我可真是够吓人的！', `FemaleText_loc5`='要跑了?看來我還是相當可怕的!', `FemaleText_loc7`='¿Huyes? ¡Supongo que doy mucho miedo!' WHERE `ID`=67185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하! 이번엔 쑤츠가 이겼네요.', `FemaleText_loc4`='哈！这回合苏琪赢了。', `FemaleText_loc5`='哈!這回合是舒琦贏了。', `FemaleText_loc7`='¡Ja! Suchi gana esta ronda.' WHERE `ID`=67186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 이 신입에게 제 주먹 맛을 보여주느라고 바빠요!', `FemaleText_loc4`='我正忙着让这菜鸟尝尝我拳头的滋味！', `FemaleText_loc5`='我正忙著給這菜鳥看我拳頭的樣子!', `FemaleText_loc7`='¡Estoy ocupada enseñándole a este novato la forma de mi puño!' WHERE `ID`=67187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누가 더 강한 운룡 기수인지 보자고요.', `FemaleText_loc4`='让我们瞧瞧谁才是更强的翔龙骑士。', `FemaleText_loc5`='看看誰才是更強的蛟龍騎士吧。', `FemaleText_loc7`='A ver quién es el jinete de dragones más rápido.' WHERE `ID`=67188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망치는 건가요? 용기가 나거든 다시 겨뤄 보시죠.', `FemaleText_loc4`='跑了？等你鼓起勇气时再来面对我吧。', `FemaleText_loc5`='要跑了?等你找回勇氣再過來面對我。', `FemaleText_loc7`='¿Huyes? Enfréntate a mí cuando hayas encontrado tu valor.' WHERE `ID`=67189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐지? 내... 내가 졌다고? 아우우우우! 당신을 이길 수 있게 더 열심히 노력하겠어요!', `FemaleText_loc4`='什么？我……我输了？啊！我得多加努力，一定要打败你！', `FemaleText_loc5`='什麼?我...我輸了?啊!我得更加努力來打敗你!', `FemaleText_loc7`='¿Qué? ¿He... perdido? ¡Aaaah! ¡Tendré que esforzarme más para vencerte!' WHERE `ID`=67190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예상했던 대로군요. 당신은 너무 약해서 절 이길 수 없어요!', `FemaleText_loc4`='不出所料。你根本不是我的对手！', `FemaleText_loc5`='跟我預期的一樣。你弱得無法打敗我!', `FemaleText_loc7`='Justo lo que esperaba. ¡Eres demasiado débil para vencerme!' WHERE `ID`=67191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 잠깐 다른 문제를 생각하고 있습니다. 잠시 후에 찾아오십시오.', `MaleText_loc4`='我有其它事情要忙。过会儿再来找我。', `MaleText_loc5`='我目前在注意其他事情。請晚點再來跟我說話。', `MaleText_loc7`='Tengo asuntos que atender. Habla conmigo dentro de un rato.' WHERE `ID`=67192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작합시다. 행운을 빕니다.', `MaleText_loc4`='开始吧。祝你好运。', `MaleText_loc5`='讓我們開始吧。祝好運。', `MaleText_loc7`='Comencemos. Buena suerte.' WHERE `ID`=67193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전을 받았을 때, 도망치기보다는 정면으로 맞서는 게 좋습니다.', `MaleText_loc4`='应该直面挑战，而不是消极逃避。', `MaleText_loc5`='面對挑戰比逃避它來得好。', `MaleText_loc7`='Es mejor enfrentarse a los retos que huir de ellos.' WHERE `ID`=67194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저보다 크게 앞서셨군요. 잘하셨습니다.', `MaleText_loc4`='你堂堂正正地打败了我。干得好。', `MaleText_loc5`='你光明正大地打敗了我。做得好。', `MaleText_loc7`='Me has vencido limpiamente. Bien hecho.' WHERE `ID`=67195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 시합은 제가 이겼습니다. 다음에는 당신에게 행운이 따르길...', `MaleText_loc4`='这回是我赢了。祝你下次好运。', `MaleText_loc5`='這次是我贏了。祝你下次好運。', `MaleText_loc7`='He ganado esta ronda. Buena suerte la próxima vez.' WHERE `ID`=67196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인에게 이런 부탁을 하기가 쉽지는 않지만, 당신이 굳이 도와주겠다고 하니...', `MaleText_loc4`='我不想麻烦外人帮忙。但要是你乐意……', `MaleText_loc5`='尋求外來人的幫忙讓我有點遲疑。但，如果你願意...', `MaleText_loc7`='Normalmente no pediría ayuda a forasteros, pero si te ofreces...' WHERE `ID`=67197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 도움을 주다니, 정말 고맙소, $n. 우리 아이들이 무사히 돌아왔고, 당신 적들도 모두 도망쳤군.$b$b이곳 판다리아에서, 적어도 나 하나는 당신과 호드를 언제든 환영할 것이오.', `MaleText_loc4`='再次感谢你的帮助，$n。我们的孩子都已安全返回，敌人也已经四散而逃。$b$b对我来说，随时欢迎你和你的部落造访潘达利亚。', `MaleText_loc5`='再次謝謝你的幫忙，$n。我們的孩子平安回來了，你的敵人也夾著尾巴逃走。$b$b以我來說，你和你的部落在潘達利亞永遠受到歡迎。', `MaleText_loc7`='Gracias por tu ayuda, $n. Nuestros hijos han vuelto sanos y salvos y nuestros enemigos han huido.$b$bPor lo que a mí respecta, tu Horda y tú siempre seréis bienvenidos en Pandaria.' WHERE `ID`=67198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 외부인을 만나는 일이 별로 없소. 게다가 하늘을 나는 죽음의 배를 타고 오는 외부인은 더욱 만나기가 쉽지 않지.', `MaleText_loc4`='这里很少有外来者。乘死亡浮船而来的外来者更是少之又少。', `MaleText_loc5`='這裡很少有外來人。乘著死亡飛船而來的就更少了。', `MaleText_loc7`='No se suelen ver forasteros por aquí. Y los forasteros que llegan en una nave voladora de la muerte, menos.' WHERE `ID`=67199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인이여, 잘 왔소.$b$b<경계하는 눈길로 당신을 바라보는 진>', `MaleText_loc4`='你好啊，外来者。$b$b<金警惕地打量着你。>', `MaleText_loc5`='歡迎，外來人。$b$b<辛小心地看著你。>', `MaleText_loc7`='Hola, $gforastero:forastera;.$b$b<Zin te observa con recelo.>' WHERE `ID`=67200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, $g용사님:아줌마;! 저 아저씨는 냄새가 지독해요.', `MaleText_loc4`='谢谢你，$g先生:女士;！那家伙可真难闻。', `MaleText_loc5`='謝謝，$g先生:女士;!那傢伙好臭。', `MaleText_loc7`='¡Gracias, $gseñor:señorita;! Ese tipo olía mal.', `FemaleText_loc1`='고마워요, $g용사님:언니;! 저 아저씨는 냄새가 끔찍해요.', `FemaleText_loc4`='谢谢你，$g先生:女士;！那家伙可真难闻。', `FemaleText_loc5`='謝謝，$g先生:女士;!那傢伙好臭。', `FemaleText_loc7`='¡Gracias, $gseñor:señorita;! Ese tipo olía mal.' WHERE `ID`=67201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가도 돼요?', `MaleText_loc4`='我可以走了吗？', `MaleText_loc5`='我可以離開了?', `MaleText_loc7`='¿Ya me puedo ir?', `FemaleText_loc1`='이제 가도 되나요?', `FemaleText_loc4`='我可以走了吗？', `FemaleText_loc5`='我可以離開了?', `FemaleText_loc7`='¿Ya me puedo ir?' WHERE `ID`=67202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 집에 가도 되겠죠?', `MaleText_loc4`='我……我能回家么？', `MaleText_loc5`='我...我可以回家了?', `MaleText_loc7`='¿Puedo... puedo irme a casa?', `FemaleText_loc1`='이제... 집에 가도 될까요?', `FemaleText_loc4`='我……我能回家么？', `FemaleText_loc5`='我...我可以回家了?', `FemaleText_loc7`='¿Puedo... puedo irme a casa?' WHERE `ID`=67203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치질은 꽤 재밌었지만, 이제 집에 가야 할 것 같아요.', `MaleText_loc4`='用锤子是挺有趣，可我现在准备回家了。', `MaleText_loc5`='使用鎚子是很有趣，但我想我準備好回家了。', `MaleText_loc7`='Ha sido divertido usar el martillo, pero ahora quiero irme a casa.', `FemaleText_loc1`='망치질은 꽤 재밌었지만, 이제 집에 가야 할 것 같네요.', `FemaleText_loc4`='用锤子是挺有趣，可我现在准备回家了。', `FemaleText_loc5`='使用鎚子是很有趣，但我想我準備好回家了。', `FemaleText_loc7`='Ha sido divertido usar el martillo, pero ahora quiero irme a casa.' WHERE `ID`=67204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 내보내 주세요!', `MaleText_loc4`='让我离开这儿！', `MaleText_loc5`='放我出去!', `MaleText_loc7`='¡Sácame de aquí!', `FemaleText_loc1`='집에 보내 주세요!', `FemaleText_loc4`='让我离开这儿！', `FemaleText_loc5`='放我出去!', `FemaleText_loc7`='¡Sácame de aquí!' WHERE `ID`=67205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄마! 저 이제 집에 가요, 엄마!', `MaleText_loc4`='妈妈！我要回家，妈妈！', `MaleText_loc5`='媽媽!我要回家了，媽媽!', `MaleText_loc7`='¡Mamá! ¡Vuelvo a casa, mamá!', `FemaleText_loc1`='엄마! 나 이제 집에 가요, 엄마!', `FemaleText_loc4`='妈妈！我要回家，妈妈！', `FemaleText_loc5`='媽媽!我要回家了，媽媽!', `FemaleText_loc7`='¡Mamá! ¡Vuelvo a casa, mamá!' WHERE `ID`=67206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집에 가고 싶어요!', `MaleText_loc4`='我想家！', `MaleText_loc5`='我想念我的家!', `MaleText_loc7`='¡Echo de menos mi casa!', `FemaleText_loc1`='집에 가고 싶어요!', `FemaleText_loc4`='我想家！', `FemaleText_loc5`='我想念我的家!', `FemaleText_loc7`='¡Echo de menos mi casa!' WHERE `ID`=67207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다! 저는 얼라이언스가 싫어요!', `MaleText_loc4`='谢谢！我不喜欢联盟。', `MaleText_loc5`='謝謝!我不喜歡聯盟。', `MaleText_loc7`='¡Gracias! No me gusta la Alianza.', `FemaleText_loc1`='고마워요! 저는 얼라이언스가 싫어요!', `FemaleText_loc4`='谢谢！我不喜欢联盟。', `FemaleText_loc5`='謝謝!我不喜歡聯盟。', `FemaleText_loc7`='¡Gracias! No me gusta la Alianza.' WHERE `ID`=67208;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 이런... 정말 너무 말랐네요! 식사를 더 하셔야 해요!', `FemaleText_loc4`='瞧瞧你，简直瘦得皮包骨头！你得多吃点！', `FemaleText_loc5`='看看你，你好瘦!你得多吃點東西!', `FemaleText_loc7`='¡Mírate! ¡Estás en los huesos! Tienes que comer más.' WHERE `ID`=67209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 믿을 수 있을지 없을지는 제가 결정할 문제가 아니에요. 시장님께서 결정을 내리시기 전까지는, 전 당신을 친구라고 생각할래요.', `FemaleText_loc4`='你是否值得我们信赖，不是我说了算。在村长作出相反的判定以前，我都当你是朋友。', `FemaleText_loc5`='我的人民能否信任你不是我來決定的。不過除非我們的村長認為你是敵人，不然在那之前我都將你視為朋友。', `FemaleText_loc7`='Si mi gente confía en ti o no no es decisión mía. A no ser que el alcalde diga lo contrario, yo te considero $gamigo nuestro:amiga nuestra;.' WHERE `ID`=67210;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼마 전까지만 해도, 저는 좋은 탄산주를 빚어내는 법 외에는 아무것도 몰랐어요. 짧은 시간 동안 너무 많은 것이 변했네요.', `FemaleText_loc4`='就在不久前，我们还过着只知道酿造可口苹果酒的简单生活。在这么短的时间内，一切都变了。', `FemaleText_loc5`='不久之前，我們只知道釀造好酒的簡單生活。這麼短的時間，一切都變了。', `FemaleText_loc7`='No hace mucho, solo conocíamos la vida sencilla de la elaboración de la buena sidra. Han cambiado muchas cosas en muy poco tiempo.' WHERE `ID`=67211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 경주를 시작할 준비가 됐습니다.', `MaleText_loc4`='我准备好开始飞行竞技赛了。', `MaleText_loc5`='我準備好開始天際競賽。', `MaleText_loc7`='Estoy listo para dar comienzo a la carrera de los cielos.', `FemaleText_loc1`='하늘 경주를 시작할 준비가 됐어요.', `FemaleText_loc4`='我准备好开始飞行竞技赛了。', `FemaleText_loc5`='我準備好開始天際競賽。', `FemaleText_loc7`='Estoy listo para dar comienzo a la carrera de los cielos.' WHERE `ID`=67212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘 경주에 함께 참가할 탈것이 또 필요합니다.', `MaleText_loc4`='我需要另一只坐骑，参加飞行竞技赛。', `MaleText_loc5`='我需要另一匹坐騎來參加天際競賽。', `MaleText_loc7`='Necesito otra montura para la carrera de los cielos.', `FemaleText_loc1`='하늘 경주에 함께 참가할 탈것이 또 필요합니다.', `FemaleText_loc4`='我需要另一只坐骑，参加飞行竞技赛。', `FemaleText_loc5`='我需要另一匹坐騎來參加天際競賽。', `FemaleText_loc7`='Necesito otra montura para la carrera de los cielos.' WHERE `ID`=67213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='변화의 바람은 끔찍한 폭풍에서부터 풍요로운 수확까지, 무슨 일이라도 일으킬 수 있어요. 이번에는 그 바람이 당신을 이끌어 온 것 같군요.$B$B자, 알려주세요. 당신은 폭풍의 전령인가요, 아니면 풍요의 전령인가요?', `FemaleText_loc4`='谁也不知道变幻之风会带来什么，也许是可怕的风暴，也许是盛大的丰收。看来这次带来的是你。$B$B现在，我想问问，你究竟是风暴还是丰收？', `FemaleText_loc5`='改變的風可以帶來任何東西，從可怕的風暴到歡愉的豐收。這一次，它帶來的似乎是你。$B$B現在，我懷疑，你是風暴還是豐收?', `FemaleText_loc7`='Los vientos del cambio pueden traer cualquier cosa, desde una terrible tormenta hasta una cosecha generosa. Parece que esta vez te han traído a ti.$b$bY yo me pregunto: ¿eres una tormenta o una cosecha?' WHERE `ID`=67214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니, 우리도 어떻게든 조치를 해야 해! 아무것도 하지 않으면, 우리와 관계도 없는 전쟁 때문에 수확물을 모두 잃게 될 거야!', `FemaleText_loc4`='妹妹，我们必须行动起来！否则，我们所有的收成都会赔在这场自己无份参与的战斗中！', `FemaleText_loc5`='姊妹，我們必須行動!否則我們會為了一場和我們無關的戰爭失去整批收成!', `FemaleText_loc7`='Hermana, ¡debemos actuar! Si no hacemos nada, perderemos toda nuestra cosecha en una guerra que no nos incumbe.' WHERE `ID`=67215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우선은 할 수 있는 일을 하자. 우린 전사가 아니니까, 외부인들을 무작정 몰아낼 수도 없잖아.', `FemaleText_loc4`='我们只能尽力而为，亲爱的妹妹。我们不是战士，无法赶走外来者。', `FemaleText_loc5`='我們會做我們該做的事，親愛的姊妹。我們不是戰士，我們不能就這樣把外來人趕走。', `FemaleText_loc7`='Haremos lo que podamos, querida hermana. No somos guerreras, no podemos echar a los forasteros sin más.' WHERE `ID`=67216;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='추트는 뭐하고 있어? 왜 매일 도장에서 훈련만 계속하는 거야? 우릴 지키는 게 일이잖아!', `FemaleText_loc4`='楚在干嘛？他怎么还在道场里训练？他应该保护我们！', `FemaleText_loc5`='恰特怎麼樣呢?他為什麼還在他的道場裡繼續訓練?他應該要保護我們!', `FemaleText_loc7`='¿Qué hay de Chut? ¿Por qué sigue entrenándose en su dojo? ¡Debería estar protegiéndonos!' WHERE `ID`=67217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 더 심각한 위험에 처하면, 추트가 구해줄 거야. 항상 그렇잖아.', `FemaleText_loc4`='要是我们陷入更大的危机，楚一定会挺身而出。他向来如此。', `FemaleText_loc5`='恰特會保護我們的，如果我們進一步遭遇危險的話。他總是會的。', `FemaleText_loc7`='Chut nos protegerá cuando estemos en peligro. Siempre nos ha protegido.' WHERE `ID`=67218;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 말이 맞았으면 좋겠네. 정말로.', `FemaleText_loc4`='我真心希望你是对的。', `FemaleText_loc5`='我希望你是對的。真的希望。', `FemaleText_loc7`='Espero que tengas razón. De verdad.' WHERE `ID`=67219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포우돈 마을에 잘 오셨습니다, 이방인이여. 왜 여길 찾아오셨는지는 모르지만, 휴식이 필요할 것 같은 모습이군요.$B$B잠깐 여기 앉아서 훌륭한 탄산주 한 잔 마시고 가시는 게 어때요? 근심 걱정이 사라질 겁니다.', `FemaleText_loc4`='欢迎来到坡东村，异乡人。我不知你是为何而来，但你看起来需要休息。$B$B不如坐下喝杯可口的苹果酒，将烦恼丢到一边，怎么样？', `FemaleText_loc5`='外地人，歡迎來到坡東村。我不知道你為什麼來，但你顯然需要休息。$B$B何不坐下來喝一杯好喝的水果酒，將你的煩惱暫時拋開?', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la Aldea Zarpa''don, $gforastero:forastera;. No sé por qué has venido, pero desde luego parece que te vendría bien descansar un rato.$b$b¿Por qué no te sientas con un buen tazón de sidra y dejas que tus preocupaciones se desvanezcan?' WHERE `ID`=67220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마을에는 왜 왔습니까, 이방인?', `MaleText_loc4`='你为什么会到我们村子里来，外来者？', `MaleText_loc5`='外地人，你為什麼來到我們的村子?', `MaleText_loc7`='¿Por qué habéis venido a nuestra aldea, forasteros?' WHERE `ID`=67221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 구출 임무를 수행하는 중입니다.', `MaleText_loc4`='我们是来执行救援任务的。', `MaleText_loc5`='我們來這裡是為了一項搜救任務。', `MaleText_loc7`='Hemos venido en una misión de rescate.' WHERE `ID`=67222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 전쟁을 벌이러 여기 왔습니다! 다른 이방인들을 어떻게 학살했는지, 보지 못했습니까?', `MaleText_loc4`='他们是为战争而来！你没看见他们是怎么杀死其他外来者的吗？', `MaleText_loc5`='他們是來這裡打仗的!難道你沒看到他們是怎麼屠殺其他外來者的嗎?', `MaleText_loc7`='¡Han venido por la guerra! ¿No has visto cómo han masacrado a los otros forasteros?' WHERE `ID`=67224;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이해하지 못하는군요. 호드는 괴물입니다! 우린 놈들과 달라요.', `FemaleText_loc4`='你不明白。部落都是怪物！我们跟他们可不一样。', `FemaleText_loc5`='你不了解。部落的人是一群怪物!我們和他們完全不一樣。', `FemaleText_loc7`='No lo entendéis. ¡Los de la Horda son monstruos! No somos como ellos.' WHERE `ID`=67225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 모두 그만하십시오! 당신은 우리 아이들을 훔쳐간 자들과 싸웠습니다. 그것만으로도 당신에게 기회를 줄 수 있을 것 같군요. 어디, 우리가 당신을 신뢰해도 된다는 걸 증명해 보십시오.', `MaleText_loc4`='够了，全都闭嘴！你们击败了那些偷走我们孩子的人。光凭这个，我就该给你们一次机会，让你们证明自己值得我们信赖。', `MaleText_loc5`='你們，都夠了!你和偷走我們孩子的人作戰。這就足夠讓我給你們一個機會，證明你們值得我們的信任。', `MaleText_loc7`='¡Ya es suficiente! Habéis combatido a los secuestradores de nuestros hijos. Eso basta para que os dé una oportunidad de demostrar que sois gente digna de confianza.' WHERE `ID`=67226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄금!', `MaleText_loc4`='够了！', `MaleText_loc5`='再也不打了!', `MaleText_loc7`='¡Nunca más!' WHERE `ID`=67227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 황무지를 벗어나서 코보크 제어력이 약해졌습니다! 어서 돌아가십시오!', `MaleText_loc4`='当你渐渐离开恐惧废土，你对科沃克的控制力也越来越弱！赶快回去！', `MaleText_loc5`='你對科沃克的控制力隨著你遠離悚然荒野而減弱!快回去!', `MaleText_loc7`='¡Tu control sobre Kovok se debilita a medida que abandonas el Desierto del Pavor! ¡Vuelve!', `FemaleText_loc1`='공포의 황무지를 벗어나서 코보크 제어력이 약해졌습니다! 어서 돌아가십시오!', `FemaleText_loc4`='当你渐渐离开恐惧废土，你对科沃克的控制力也越来越弱！赶快回去！', `FemaleText_loc5`='你對科沃克的控制力隨著你遠離悚然荒野而減弱!快回去!', `FemaleText_loc7`='¡Tu control sobre Kovok se debilita a medida que abandonas el Desierto del Pavor! ¡Vuelve!' WHERE `ID`=67228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다!', `MaleText_loc4`='恭喜！', `MaleText_loc5`='恭喜!', `MaleText_loc7`='¡Felicidades!' WHERE `ID`=67229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 위해 건배하겠어요!', `MaleText_loc4`='这值得干一杯！', `MaleText_loc5`='我要為那乾杯!', `MaleText_loc7`='¡Brindaré por ti!' WHERE `ID`=67230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 해낼 수 있을 줄 알았어요!', `FemaleText_loc4`='我就知道你能做到！', `FemaleText_loc5`='我一直知道你可以做到的!', `FemaleText_loc7`='¡Siempre supe que lo conseguirías!' WHERE `ID`=67231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우릴 구하러 온 사람이 있다고? 희망이 아예 없는 건 아니로군...', `MaleText_loc4`='有人来救我们了？也许还有希望……', `MaleText_loc5`='有人來拯救我們了?也許並不是全都絕望...', `MaleText_loc7`='¿Han venido a salvarnos? A lo mejor no todo está perdido...' WHERE `ID`=67232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 묘한 표정으로 당신을 바라봅니다.>', `MaleText_loc4`='<你的翔龙好奇地看着你。>', `MaleText_loc5`='<你的蛟龍用好奇的表情看著你。>', `MaleText_loc7`='<Tu dragón te mira con curiosidad.>' WHERE `ID`=67233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"얼라이언스"에 대해서 잘은 모르지만, 당신은 믿음직해 보여요. 사람을 모아둘 테니, 재건을 시작할 준비가 되면 만나요!', `MaleText_loc4`='我不了解这个所谓的“联盟”，但你看起来值得信任。我会集结所有人，做好重建的准备后，就来与你会面！', `MaleText_loc5`='我不知道這個「聯盟」怎樣，但你看起來值得信任。等我們準備好重建，我會聚集所有人和你見面!', `MaleText_loc7`='No sé qué pensar de esa "Alianza", pero tú me transmites confianza. ¡Voy a reunir a todo el mundo! ¡Nos vemos cuando estemos listos para la reconstrucción!' WHERE `ID`=67234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 당신을 보고 웃습니다.>', `MaleText_loc4`='<你的翔龙对你微微一笑。>', `MaleText_loc5`='<你的蛟龍對你微笑。>', `MaleText_loc7`='<Tu dragón te sonríe.>' WHERE `ID`=67235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"호드"에 대해서 잘은 모르지만, 당신은 믿음직해 보여요. 사람을 모아둘 테니, 재건을 시작할 준비가 되면 만나요!', `MaleText_loc4`='我不了解这个所谓的“部落”，但你看起来值得信任。我会集结所有人，做好重建的准备后，就来与你会面！', `MaleText_loc5`='我不知道這個「聯盟」怎樣，但你看起來值得信任。等我們準備好重建，我會聚集所有人和你見面!', `MaleText_loc7`='No sé qué pensar de esa "Horda", pero tú me transmites confianza. ¡Voy a reunir a todo el mundo! ¡Nos vemos cuando estemos listos para la reconstrucción!' WHERE `ID`=67236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 당신을 향해 으르렁댑니다.>', `MaleText_loc4`='<你的翔龙对你咕噜了两声。>', `MaleText_loc5`='<你的蛟龍對你發出咕嚕聲。>', `MaleText_loc7`='<Tu dragón te gruñe.>' WHERE `ID`=67237;
