UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 지루한 표정으로 당신을 봅니다.>', `MaleText_loc4`='<你的翔龙百无聊赖地看着你。>', `MaleText_loc5`='<你的蛟龍用無聊的表情看著你。>', `MaleText_loc7`='<Tu dragón te mira con expresión aburrida.>' WHERE `ID`=67239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 우아하게 주위를 날아다닙니다.>', `MaleText_loc4`='<你的翔龙优雅地四处翱翔。>', `MaleText_loc5`='<你的蛟龍優雅地飛來飛去。>', `MaleText_loc7`='<Tu dragón vuela en círculos grácilmente.>' WHERE `ID`=67240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 당신의 팔에 비늘을 살며시 문지릅니다.>', `MaleText_loc4`='<你的翔龙在你的手臂上蹭着鳞片。>', `MaleText_loc5`='<你的蛟龍用鱗片摩擦你的手臂。>', `MaleText_loc7`='<Tu dragón restriega sus escamas por tu brazo.>' WHERE `ID`=67241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신의 운룡이 당신을 쿡 찌릅니다. 하마터면 넘어질 뻔했습니다.>', `MaleText_loc4`='<你的翔龙撞了你一下，差点把你撞倒。>', `MaleText_loc5`='<你的蛟龍頂了頂你，幾乎把你撞倒。>', `MaleText_loc7`='<Tu dragón te da un empujón que casi te tumba.>' WHERE `ID`=67242;
