UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물들아, 포기할 줄도 모르냐?', `MaleText_loc4`='你们这群畜生不懂放弃吗？', `MaleText_loc5`='你們不知道什麼時候該放棄嗎?', `MaleText_loc7`='¿No saben cuándo rendirse, verdad, bestias?' WHERE `ID`=67251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 짐승들! 냄새나는 몸뚱이를 치워라!', `MaleText_loc4`='龌龊的畜生！我不允许你们玷污这片土地！', `MaleText_loc5`='骯髒的動物!不要把臭味帶到這片土地上!', `MaleText_loc7`='¡Animales asquerosos! ¡No contaminarán esta tierra con su hedor!' WHERE `ID`=67252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼... 국왕님을 실망시킬 수는... 으... 으아악!', `MaleText_loc4`='不…我不能让国王失望…我…我…', `MaleText_loc5`='我...我讓我的國王失望了。我...我...', `MaleText_loc7`='No... Le he fallado a mi rey.' WHERE `ID`=67253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 힘은 이곳에 미치지 못해.', `MaleText_loc4`='你们部落在这里毫无力量。', `MaleText_loc5`='你們部落在這裡沒有力量。', `MaleText_loc7`='Su Horda no tiene poder aquí.' WHERE `ID`=67254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저한테 지더라도 너무 고깝게 생각하지는 마세요!', `FemaleText_loc4`='要是你输了，别说酸话！', `FemaleText_loc5`='輸給我的時候可別酸!', `FemaleText_loc7`='¡No te enfades cuando te gane!' WHERE `ID`=67256;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 혹시 지게 되면 제 어깨에 기대 울어도 돼요.', `FemaleText_loc4`='别担心。如果你输了，我可以把肩膀借给你哭。', `FemaleText_loc5`='別擔心，你打輸時可以靠我的肩膀。', `FemaleText_loc7`='No te preocupes. Si pierdes, puedes llorar sobre mi hombro.' WHERE `ID`=67257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 예쁘다고 만만하게 보지 마세요. 1등상은 제 차지니까요!', `FemaleText_loc4`='我也许看上去温和可人，可我也是冲着头等奖来的！', `FemaleText_loc5`='我看起來或許很甜，但我還是以冠軍為目標!', `FemaleText_loc7`='Te pareceré mona, ¡pero tengo el primer premio en el punto de mira!' WHERE `ID`=67258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='승리의 맛은 정말 달콤할 거예요.', `FemaleText_loc4`='我会品尝到甜美的胜利。', `FemaleText_loc5`='我的勝利將無比甜美。', `FemaleText_loc7`='Mi victoria será muy dulce.' WHERE `ID`=67259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 멋지게 승리할게요. 약속해요!', `FemaleText_loc4`='我会是个有风度的赢家，我保证！', `FemaleText_loc5`='我會是個高尚的贏家，我保證!', `FemaleText_loc7`='¡Te prometo que seré una ganadora humilde!' WHERE `ID`=67260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 주 내내 열심히 훈련했으니, 그 노력의 결실로 승리할 수 있을 겁니다.', `MaleText_loc4`='我刻苦训练了一个星期。胜利将是我努力付出换来的回报。', `MaleText_loc5`='我這整個禮拜都訓練得很辛苦。我的辛苦會有勝利作為報酬。', `MaleText_loc7`='Llevo toda la semana entrenándome al máximo. El resultado de tanto esfuerzo será la victoria.' WHERE `ID`=67261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정하지 마십시오. 저는 당당하게 시합해서 승리할 겁니다.', `MaleText_loc4`='别担心。我会光荣取胜。', `MaleText_loc5`='別擔心。我會光明正大地取得勝利。', `MaleText_loc7`='No te preocupes. Ganaré con honor.' WHERE `ID`=67262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1등으로 결승선을 통과하는 것에만 집중하겠습니다.', `MaleText_loc4`='我会全力以赴，拔得头筹。', `MaleText_loc5`='我會專注在贏得第一名。', `MaleText_loc7`='Me concentraré en acabar el primero.' WHERE `ID`=67263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필승 전략이 있으니, 전 패배할 수 없습니다.', `MaleText_loc4`='以我的必胜战略，我不可能失败。', `MaleText_loc5`='我的必勝策略讓我不可能輸。', `MaleText_loc7`='Con mi estrategia ganadora, perder es imposible.' WHERE `ID`=67264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 윤이 상처를 치유하고 있습니다. 차단하십시오!', `MaleText_loc4`='尹大师正在治疗，快打断他！', `MaleText_loc5`='尹大師正在治療，中斷他!', `MaleText_loc7`='El maestro Yoon se está sanando. ¡Interrúmpelo!' WHERE `ID`=67265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아!!', `MaleText_loc4`='啊啊啊！！', `MaleText_loc5`='啊啊啊啊!!', `MaleText_loc7`='¡¡AAAHHHHH!!' WHERE `ID`=67266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡단에 잘 오셨습니다. 우리 운룡단과 확고한 동맹이 된 분들만이 운룡을 소유할 수 있습니다.', `MaleText_loc4`='欢迎来到云端翔龙骑士团。只有在我们骑士团里达到崇拜的人才能获得我们的云端翔龙。', `MaleText_loc5`='歡迎來到雲蛟衛。只有聲望達到崇拜的人可以取得我們的雲蛟。', `MaleText_loc7`='Te doy la bienvenida a la Orden del Dragón Nimbo. Solo los exaltados con nuestra Orden pueden adquirir dragones nimbo.' WHERE `ID`=67267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용 기수님, 어서 오세요! 편한 시간에 골라보실 수 있게 아름다운 운룡들을 준비해 두었습니다.', `MaleText_loc4`='欢迎你，翔龙骑士！我这里有美丽的云端翔龙，欢迎随意挑选。', `MaleText_loc5`='歡迎，蛟騎士!我有許多漂亮的雲蛟可以供你瀏覽。', `MaleText_loc7`='¡Hola, jinete de dragones! Echa un vistazo tranquilamente a los preciosos dragones nimbo que tengo a la venta.' WHERE `ID`=67268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했네, $n. 지금까지 자네가 기른 운룡은 이제 자네의 것이 되었네. 둘이 함께하는 여행이... 이제 막 시작된 것이네.', `FemaleText_loc4`='干得好，$n。你驯养的云端翔龙现在是你的了。你们共同的旅程……才刚刚开始。', `FemaleText_loc5`='做得好，$n。你所扶養的雲蛟已經是你的了。你們一起共患難的旅途...才正要開始。', `FemaleText_loc7`='Bien hecho, $n. El dragón nimbo que has criado ya es tuyo. Su viaje... acaba de comenzar.' WHERE `ID`=67269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헤엄이라도 치고 있었던 겁니까? 아직 사지가 멀쩡하니, 별 문제 없겠지요?', `MaleText_loc4`='决定去游泳了，是吧？嗯，看你毫发无伤的样子，我就知道你一切平安。', `MaleText_loc5`='決定去游個泳了，是嗎?好吧，你還是好端端，我想不會有什麼傷害。', `MaleText_loc7`='¿Qué, te apetecía darte un baño? Bueno, sigues de una pieza, así que supongo que no hay problema.' WHERE `ID`=67270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐... 숨 좀 고르고요...', `FemaleText_loc4`='再等……一会儿。', `FemaleText_loc5`='需要...一點時間。', `FemaleText_loc7`='Solo... necesito... un segundo.' WHERE `ID`=67271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해안에서 있었던 사건에 대해서는, 조심스러운 대응이 필요하네. 포우돈은 작은 양조 마을이지, 전쟁을 위한 요새가 아니야.$B$B자네 지도자들에게도, 우리 주민들을 대할 때 이 점을 기억하라고 전해 주게. 우리는 전투를 즐기지는 않지만, 어쩔 수 없는 상황이라면 지원하겠네.$B$B우선 이 일에 대해 명상을 해야겠군.', `MaleText_loc4`='我们必须小心应对近来在海岸上发生的事。坡东村是个酿酒小镇，不是战斗要塞。$B$B你也应该提醒你的首领，在评判我族人时也应该持有同样谨慎的态度。我们不主动寻衅，但也决不是缩头乌龟。$B$B我得好好想想。', `MaleText_loc5`='我們必須小心應對最近在岸邊發生的事件。坡東是個釀酒小鎮，不是個戰爭要塞。$B$B你最好勸你們的領袖也同樣小心地評斷我們。我們不好戰，但在必要時我們也會應戰。$B$B我必須深思熟慮這件事。', `MaleText_loc7`='Debemos ser cautos al reaccionar ante los últimos acontecimientos de nuestras costas. Zarpa''don es una aldea cervecera, no una fortaleza de guerra.$b$bHarías bien en rogar a tus líderes que ejercieran la misma precaución al juzgar a mi pueblo. No deseamos luchar, pero lo haremos si es necesario.$b$bDebo meditar sobre este asunto.' WHERE `ID`=67272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리들은 많은 위기를 겪었지만... 이렇게까지 심각한 사태는 처음이에요.', `FemaleText_loc4`='我的族人面对过许多考验……可却从没遇到过这样的事。', `FemaleText_loc5`='我的人民面臨過許多試煉...但從來沒遇到過這樣的事情。', `FemaleText_loc7`='Mi gente ha superado muchas pruebas... Pero nunca habíamos visto nada parecido.' WHERE `ID`=67273;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 전쟁이 이곳을 전례 없이 파괴했어요. 당신네들의 비행 장치와 폭탄에 비하면, 저 사마귀들도 그다지 위험하지 않게 보이네요.', `FemaleText_loc4`='你们的战争让这里遭遇了前所未有的灾难。与你们那些飞艇和炸弹比起来，就连螳螂妖的威胁都显得稍逊一筹。', `FemaleText_loc5`='你的戰爭為這裡帶來空前的毀滅。就連螳螂人的威脅都小於你們的飛行機器和炸彈。', `FemaleText_loc7`='Su guerra nos ha traído una destrucción sin precedentes. Ni los mántides son tan peligrosos como sus máquinas voladoras y sus bombas.' WHERE `ID`=67274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이미 음영파에 이곳에서 일어난 일에 대해 알렸어요. 그들이 뭐라도 할 수 있으면 좋겠는데...$B$B앞으로 일어날 사태에 대해 우리 모두 준비가 전혀 안 되어 있는 것 같아요.', `FemaleText_loc4`='我已经把这里发生的一切报告给了影踪派。希望他们能采取行动。$B$B尽管我们都对即将到来的考验毫无准备，但也必须面对。', `FemaleText_loc5`='我已經警告過影潘這裡發生的事情。幸運的話他們會做點什麼。$B$B但我感覺我們全都對即將到來的試煉毫無準備。', `FemaleText_loc7`='Ya he alertado al Shadopan de lo que está sucediendo aquí. Espero que puedan hacer algo.$b$bTengo la sensación de que no estamos preparados para lo que nos espera.' WHERE `ID`=67275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 운룡도 당신을 사랑합니다!', `MaleText_loc4`='雏龙也爱你！', `MaleText_loc5`='蛟寶寶也愛你!', `MaleText_loc7`='¡La prole también te quiere!' WHERE `ID`=67276;
