UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새끼 운룡이 당신이 토닥여 주는 것을 좋아합니다!', `MaleText_loc4`='雏龙喜欢你的爱抚！', `MaleText_loc5`='蛟寶寶喜歡拍拍!', `MaleText_loc7`='¡A la prole le gusta que la acaricies!' WHERE `ID`=67278;
