UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 하늘 경주가 열리기까지 시간이 많이 남았으니, 지금까지 배운 것에 대해 명상해 보시는 게 좋겠습니다. 경주가 열리는 날에는 제게 말을 거시면 시합에 참가할 수 있어요.', `FemaleText_loc4`='在下一场飞行竞技赛开始前，你有充足的时间思考自己学到了什么。在比赛日，与我交谈即可参与竞赛。', `FemaleText_loc5`='在下一次天際競賽前，你有很多時間可以冥想你所學到的東西。比賽當天，和我說話來加入競賽。', `FemaleText_loc7`='Tienes tiempo de sobra para meditar sobre lo que has aprendido antes de la siguiente carrera de los cielos. En los días que haya carrera, habla conmigo para participar.' WHERE `ID`=67310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 쳉이 당신을 산 채로 태웁니다! 이동하십시오!', `MaleText_loc4`='程大师要把你活活烧死！快走开！', `MaleText_loc5`='程大師要把你活活燒死了!快移動!', `MaleText_loc7`='¡Cheng te está quemando! ¡Muévete!' WHERE `ID`=67311;
