UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이 섬의 운룡들을 위해 할 수 있는 일은 다 했군. 내일 다시 돌아와서 훈련을 계속하게.', `MaleText_loc4`='你今天已经为岛上的翔龙尽了全力。明天再回来继续训练吧。', `MaleText_loc5`='你今天已經盡力幫助了島上的蛟龍。明天回來繼續你的訓練吧。', `MaleText_loc7`='Hoy ya has hecho todo lo posible para ayudar a los dragones de la isla. Vuelve mañana para continuar con tu entrenamiento.', `FemaleText_loc1`='오늘 이 섬의 운룡들을 위해 할 수 있는 일은 다 했군. 내일 다시 돌아와서 훈련을 계속하게.', `FemaleText_loc4`='你今天已经为岛上的翔龙尽了全力。明天再回来继续训练吧。', `FemaleText_loc5`='你今天已經盡力幫助了島上的蛟龍。明天回來繼續你的訓練吧。', `FemaleText_loc7`='Hoy ya has hecho todo lo posible para ayudar a los dragones de la isla. Vuelve mañana para continuar con tu entrenamiento.' WHERE `ID`=67322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 이 섬의 운룡들을 위해 할 수 있는 일은 다 했군. 내일 다시 돌아와서 훈련을 계속하게.', `MaleText_loc4`='你今天已经为岛上的翔龙尽了全力。明天再回来继续训练吧。', `MaleText_loc5`='你今天已經盡力幫助了島上的蛟龍。明天回來繼續你的訓練吧。', `MaleText_loc7`='Hoy ya has hecho todo lo posible para ayudar a los dragones de la isla. Vuelve mañana para continuar con tu entrenamiento.', `FemaleText_loc1`='오늘 이 섬의 운룡들을 위해 할 수 있는 일은 다 했군. 내일 다시 돌아와서 훈련을 계속하게.', `FemaleText_loc4`='你今天已经为岛上的翔龙尽了全力。明天再回来继续训练吧。', `FemaleText_loc5`='你今天已經盡力幫助了島上的蛟龍。明天回來繼續你的訓練吧。', `FemaleText_loc7`='Hoy ya has hecho todo lo posible para ayudar a los dragones de la isla. Vuelve mañana para continuar con tu entrenamiento.' WHERE `ID`=67323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 자네의 새끼 운룡을 위해 해줄 수 있는 일은 다 했군. 내가 잘 보살필 테니, 꼭 내일 다시 돌아와서 새끼 운룡이 얼마나 자랐는지 확인하게.', `MaleText_loc4`='你今天已经为你的雏龙尽了全力。我会照顾好它，但记得明天要回来查看进展。', `MaleText_loc5`='你今天已經為你的蛟寶寶做了一切。我會保護牠平安的，明天別忘了回來確認牠的進度。', `MaleText_loc7`='Hoy ya has hecho todo lo posible para cuidar de tu prole. Yo la mantendré a salvo, pero no te olvides de volver mañana para ver qué tal le va.', `FemaleText_loc1`='오늘 자네의 새끼 운룡을 위해 해줄 수 있는 일은 다 했군. 내가 잘 보살필 테니, 꼭 내일 다시 돌아와서 새끼 운룡이 얼마나 자랐는지 확인하게.', `FemaleText_loc4`='你今天已经为你的雏龙尽了全力。我会照顾好它，但记得明天要回来查看进展。', `FemaleText_loc5`='你今天已經為你的蛟寶寶做了一切。我會保護牠平安的，明天別忘了回來確認牠的進度。', `FemaleText_loc7`='Hoy ya has hecho todo lo posible para cuidar de tu prole. Yo la mantendré a salvo, pero no te olvides de volver mañana para ver qué tal le va.' WHERE `ID`=67324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤와의 전투는 내일도 계속될 걸세. 지금은 우선 휴식을 취하게.', `MaleText_loc4`='我们明天再继续对抗邪煞。现在，好好休息吧。', `MaleText_loc5`='我們和煞之間的戰鬥可以明天繼續。先休息吧。', `MaleText_loc7`='Nuestra lucha contra los sha puede seguir mañana. Ahora descansa.', `FemaleText_loc1`='샤와의 전투는 내일도 계속될 걸세. 지금은 우선 휴식을 취하게.', `FemaleText_loc4`='我们明天再继续对抗邪煞。现在，好好休息吧。', `FemaleText_loc5`='我們和煞之間的戰鬥可以明天繼續。先休息吧。', `FemaleText_loc7`='Nuestra lucha contra los sha puede seguir mañana. Ahora descansa.' WHERE `ID`=67326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 정말 많은 일을 했군, $n. 훈련을 내일 계속하세.', `MaleText_loc4`='你今天做了许多工作，$n。我们明天再继续训练。', `MaleText_loc5`='你今天進度不錯，$n。我們明天再繼續你的訓練。', `MaleText_loc7`='Hoy has trabajado mucho, $n. Mañana proseguiremos con tu entrenamiento.', `FemaleText_loc1`='오늘 정말 많은 일을 했군, $n. 훈련을 내일 계속하세.', `FemaleText_loc4`='你今天做了许多工作，$n。我们明天再继续训练。', `FemaleText_loc5`='你今天進度不錯，$n。我們明天再繼續你的訓練。', `FemaleText_loc7`='Hoy has trabajado mucho, $n. Mañana proseguiremos con tu entrenamiento.' WHERE `ID`=67327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기운이 흐트러진다 싶더니만, 조교들을 물리쳤군요. 이제 직접 상대해 드리지요.', `MaleText_loc4`='我想我感觉到了干扰，看来你已经打败了我的助手们。现在可以来挑战我了。', `MaleText_loc5`='我感覺到不小的騷動，看來你打敗了我的助手們。現在你必須面對我。', `MaleText_loc7`='Creí haber notado algo. Veo que has derrotado a mis ayudantes. Ahora puedes enfrentarte a mí.' WHERE `ID`=67328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $n! 하늘 경주에 참여했으니 오늘은 무척 피곤할 테지. 이제 가서 쉬게. 내일이 되면 또 할 일이 무척 많을 테니까.', `MaleText_loc4`='干得好，$n！参加完比赛，想必你一定累坏了。去好好休息吧。明天还有很多任务等你完成呢。', `MaleText_loc5`='做得好，$n!參賽後你一定累了。去休息一下吧。明天還有很多任務等著你。', `MaleText_loc7`='¡Bien hecho, $n! Debes de estar $gcansado:cansada; después de haber participado en la carrera. Ve y descansa un rato. Mañana habrá tareas de sobra esperándote.', `FemaleText_loc1`='잘했네, $n! 하늘 경주에 참여했으니 오늘은 무척 피곤할 테지. 이제 가서 쉬게. 내일이 되면 또 할 일이 무척 많을 테니까.', `FemaleText_loc4`='干得好，$n！参加完比赛，想必你一定累坏了。去好好休息吧。明天还有很多任务等你完成呢。', `FemaleText_loc5`='做得好，$n!參賽後你一定累了。去休息一下吧。明天還有很多任務等著你。', `FemaleText_loc7`='¡Bien hecho, $n! Debes de estar $gcansado:cansada; después de haber participado en la carrera. Ve y descansa un rato. Mañana habrá tareas de sobra esperándote.' WHERE `ID`=67329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 준타와 더 싸우고 싶다는 거군요?', `MaleText_loc4`='你想让祖塔再为你做点什么，嗯？', `MaleText_loc5`='你想要多嚐嚐祖塔的厲害，是吧?', `MaleText_loc7`='¿Quieres más de Zunta, eh?' WHERE `ID`=67330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호, $n 님! 정말 큰 골칫거리들을 해결해 주셨군요! 자, 당신이 오늘 해야 할 "임무"는 다 완수했다고 봐도 되겠습니다. 가서 좀 쉬십시오. 내일도 할 일은 많을 테니까요!', `MaleText_loc4`='嚯，$n！你今天收拾了好大一个烂摊子！嗯，你今天的“任务”已经完成了。去好好休息吧。明天还有很多事情要做！', `MaleText_loc5`='唷，$n!你真是清除了很大一個爛攤子!好吧，我得說你已經完成了今天的「任務」。去休息一下吧。明天還有好多事要做!', `MaleText_loc7`='¡Hola, $n! ¡Menudo asunto que acabas de solucionar! Si quieres mi opinión, por hoy ya has cumplido con tu "deber". Ve a descansar un rato. ¡Mañana habrá trabajo de sobra!', `FemaleText_loc1`='호, $n 님! 정말 큰 골칫거리들을 해결해 주셨군요! 자, 당신이 오늘 해야 할 "임무"는 다 완수했다고 봐도 되겠습니다. 가서 좀 쉬십시오. 내일도 할 일은 많을 테니까요!', `FemaleText_loc4`='嚯，$n！你今天收拾了好大一个烂摊子！嗯，你今天的“任务”已经完成了。去好好休息吧。明天还有很多事情要做！', `FemaleText_loc5`='唷，$n!你真是清除了很大一個爛攤子!好吧，我得說你已經完成了今天的「任務」。去休息一下吧。明天還有好多事要做!', `FemaleText_loc7`='¡Hola, $n! ¡Menudo asunto que acabas de solucionar! Si quieres mi opinión, por hoy ya has cumplido con tu "deber". Ve a descansar un rato. ¡Mañana habrá trabajo de sobra!' WHERE `ID`=67331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 맥주를 되찾아 줘서 얼마나 다행인지 모릅니다, $n 님! 오늘 우리 할 일은 끝났으니, 이제 맥주나 한 잔 하러 가시죠!', `MaleText_loc4`='谢天谢地，你终于把酒找回来了，$n！既然今天的任务已经完成，是时候开怀畅饮了！', `MaleText_loc5`='謝天謝地，你把酒找回來了，$n!既然我們今天的工作已經完成，我說現在該是暢飲一番的時候了!', `MaleText_loc7`='¡Menos mal que has recuperado la cerveza, $n! Ya que hemos terminado nuestro trabajo de hoy, ¡yo digo que empecemos a beber!', `FemaleText_loc1`='당신이 맥주를 되찾아 줘서 얼마나 다행인지 모릅니다, $n 님! 오늘 우리 할 일은 끝났으니, 이제 맥주나 한 잔 하러 가시죠!', `FemaleText_loc4`='谢天谢地，你终于把酒找回来了，$n！既然今天的任务已经完成，是时候开怀畅饮了！', `FemaleText_loc5`='謝天謝地，你把酒找回來了，$n!既然我們今天的工作已經完成，我說現在該是暢飲一番的時候了!', `FemaleText_loc7`='¡Menos mal que has recuperado la cerveza, $n! Ya que hemos terminado nuestro trabajo de hoy, ¡yo digo que empecemos a beber!' WHERE `ID`=67332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운룡을 잘 돌보고 있군요, $n 님. 당신이 오늘 할 수 있는 일은 다 한 것 같습니다. 내일 다시 와서 운룡을 보살펴 주십시오.', `MaleText_loc4`='你把你的雏龙照料得很好，$n。你今天已经竭尽所能了。明天一定要再来看望翔龙哦！', `MaleText_loc5`='你把你的蛟龍照顧得很好，$n。你今天能做的事都已經做完了。記得明天要再回來看看你的蛟龍。', `MaleText_loc7`='Estás cuidando bien de tu dragón, $n. Hoy ya has hecho todo lo posible. No te olvides de volver a visitar a tu dragón mañana.', `FemaleText_loc1`='운룡을 잘 돌보고 있군요, $n 님. 당신이 오늘 할 수 있는 일은 다 한 것 같습니다. 내일 다시 와서 운룡을 보살펴 주십시오.', `FemaleText_loc4`='你把你的雏龙照料得很好，$n。你今天已经竭尽所能了。明天一定要再来看望翔龙哦！', `FemaleText_loc5`='你把你的蛟龍照顧得很好，$n。你今天能做的事都已經做完了。記得明天要再回來看看你的蛟龍。', `FemaleText_loc7`='Estás cuidando bien de tu dragón, $n. Hoy ya has hecho todo lo posible. No te olvides de volver a visitar a tu dragón mañana.' WHERE `ID`=67333;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불모의 땅에 또 다른 이름 모를 제물이 생기겠군. 바로 자네 말이네.', `FemaleText_loc4`='你只会成为这片贫瘠土地上的又一位无名牺牲者。', `FemaleText_loc5`='你將只會是這片荒蕪土地上的另一個無名受害者。', `FemaleText_loc7`='No serás más que otra víctima anónima en estas tierras yermas.' WHERE `ID`=67334;
