UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워보자!', `MaleText_loc4`='来打我呀！', `MaleText_loc5`='來打我啊!', `MaleText_loc7`='¡Ven a por mí!', `FemaleText_loc1`='덤벼요!', `FemaleText_loc4`='来打我呀！', `FemaleText_loc5`='來打我啊!', `FemaleText_loc7`='¡Ven a por mí!' WHERE `ID`=67336;
