UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비되셨습니까?', `MaleText_loc4`='做好准备！', `MaleText_loc5`='準備好!', `MaleText_loc7`='¡Prepárate!', `FemaleText_loc1`='준비되셨습니까?', `FemaleText_loc4`='做好准备！', `FemaleText_loc5`='準備好!', `FemaleText_loc7`='¡Prepárate!' WHERE `ID`=67338;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경주를 시작할 준비가 되면 제게 말씀하세요, $n 님.', `FemaleText_loc4`='等你做好参赛准备，就来与我交谈，$n。', `FemaleText_loc5`='當你準備好要比賽時來找我，$n。', `FemaleText_loc7`='Habla conmigo cuando estés $glisto:lista; para competir, $n.' WHERE `ID`=67339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사마귀 물건들! 저리 꺼져!', `MaleText_loc4`='该死的螳螂妖！走开！', `MaleText_loc5`='螳螂人的東西是我的!走開!', `MaleText_loc7`='¡Mis cosas mántides! ¡Vete!' WHERE `ID`=67340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성 밖, 드워프 지구 북쪽의 호숫가 오두막 근처에서 오드리 번헵을 찾으십시오.', `MaleText_loc4`='去城外找奥黛丽·伯恩赫普，就在矮人区北部，湖畔小屋附近。', `MaleText_loc5`='到城外不遠處，在矮人區北邊靠近湖畔小屋的地方找奧德雷·燃憂。', `MaleText_loc7`='Busca a Audrey Burnhep justo al límite de la ciudad, al norte del Distrito de los Enanos, cerca de la cabaña a orillas del lago.', `FemaleText_loc1`='성 밖, 드워프 지구 북쪽의 호숫가 오두막 근처에서 오드리 번헵을 찾으십시오.', `FemaleText_loc4`='去城外找奥黛丽·伯恩赫普，就在矮人区北部，湖畔小屋附近。', `FemaleText_loc5`='到城外不遠處，在矮人區北邊靠近湖畔小屋的地方找奧德雷·燃憂。', `FemaleText_loc7`='Busca a Audrey Burnhep justo al límite de la ciudad, al norte del Distrito de los Enanos, cerca de la cabaña a orillas del lago.' WHERE `ID`=67341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF0008E8신규|r: 전투 애완동물 조련사', `MaleText_loc4`='|cFF0008E8新功能|r：战斗宠物训练师', `MaleText_loc5`='|cFF0008E8新功能|r:戰寵訓練師', `MaleText_loc7`='|cFF0008E8NUEVO|r: Instructor de mascotas de duelo', `FemaleText_loc1`='|cFF0008E8신규|r: 전투 애완동물 조련사', `FemaleText_loc4`='|cFF0008E8新功能|r：战斗宠物训练师', `FemaleText_loc5`='|cFF0008E8新功能|r:戰寵訓練師', `FemaleText_loc7`='|cFF0008E8NUEVO|r: Instructor de mascotas de duelo' WHERE `ID`=67342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도시의 중앙 고원에서 오크 바르조크를 찾아보게. 비행 조련사 바로 동쪽에 있을 걸세.', `MaleText_loc4`='去城中台地的顶上找名叫瓦佐克的兽人，就在飞行管理员东边。', `MaleText_loc5`='到城市中央高地上，離飛行管理員東邊不遠的地方找獸人伐索克。', `MaleText_loc7`='Busca al orco Varzok en la meseta central de la ciudad, justo al este del maestro de vuelo.', `FemaleText_loc1`='도시의 중앙 고원에서 오크 바르조크를 찾아보게. 비행 조련사 바로 동쪽에 있을 걸세.', `FemaleText_loc4`='去城中台地的顶上找名叫瓦佐克的兽人，就在飞行管理员东边。', `FemaleText_loc5`='到城市中央高地上，離飛行管理員東邊不遠的地方找獸人伐索克。', `FemaleText_loc7`='Busca al orco Varzok en la meseta central de la ciudad, justo al este del maestro de vuelo.' WHERE `ID`=67343;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사부 쳉이 회전합니다! 마비시키십시오!', `FemaleText_loc4`='程大师正在旋转！使她瘫痪！', `FemaleText_loc5`='程大師正在施展鶴旋踢!打昏她!', `FemaleText_loc7`='¡La maestra Cheng está girando! ¡Paralízala!' WHERE `ID`=67344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워, 위키!', `MaleText_loc4`='谢谢，光板儿！', `MaleText_loc5`='謝謝，威奇!', `MaleText_loc7`='¡Gracias, Wikky!', `FemaleText_loc1`='고마워, 위키!', `FemaleText_loc4`='谢谢，光板儿！', `FemaleText_loc5`='謝謝，威奇!', `FemaleText_loc7`='¡Gracias, Wikky!' WHERE `ID`=67345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위키가 뭐 찾았는지 봐라!', `MaleText_loc4`='看看光板儿找到什么了！', `MaleText_loc5`='看看威奇找到了什麼!', `MaleText_loc7`='¡Mira lo ke Wikky enkuentra!', `FemaleText_loc1`='위키가 뭐 찾았는지 봐라!', `FemaleText_loc4`='看看光板儿找到什么了！', `FemaleText_loc5`='看看威奇找到了什麼!', `FemaleText_loc7`='¡Mira lo ke Wikky enkuentra!' WHERE `ID`=67346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것이 내 권위에 도전한 자의 운명이다.', `FemaleText_loc4`='质疑权威的人就是这个下场。', `FemaleText_loc5`='這就是挑戰權威的下場。', `FemaleText_loc7`='Tal es el destino de aquellos que cuestionan la autoridad.' WHERE `ID`=67347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 절망의 분노에 휩싸입니다!', `MaleText_loc4`='%s变得愤怒异常！', `MaleText_loc5`='%s絕望地暴怒了起來!', `MaleText_loc7`='¡%s se entrega a una ira desesperada!', `FemaleText_loc1`='%s|1이;가; 절망의 분노에 휩싸입니다!', `FemaleText_loc4`='%s变得愤怒异常！', `FemaleText_loc5`='%s絕望地暴怒了起來!', `FemaleText_loc7`='¡%s se entrega a una ira desesperada!' WHERE `ID`=67348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''짜릿한 비취 번개''가 타우렌어로 뭔지 아십니까? 하이 엘프어로는요? 나즈자어로는요?', `MaleText_loc4`='你知道“碎玉闪电”用牛头人语怎么说吗？萨拉斯语呢？纳迦语呢？', `MaleText_loc5`='你知道如何用牛頭人語說「碎玉轟雷掌」嗎?或是用薩拉斯語?', `MaleText_loc7`='¿Sabes cómo se dice "Relámpago crepitante de jade" en taurahe? ¿Y en thalassiano? ¿Y en nazja?' WHERE `ID`=67349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하고 싶습니다.', `MaleText_loc4`='我想挑战你。', `MaleText_loc5`='我想要挑戰你。', `MaleText_loc7`='Te desafío.', `FemaleText_loc1`='도전하고 싶어요.', `FemaleText_loc4`='我想挑战你。', `FemaleText_loc5`='我想要挑戰你。', `FemaleText_loc7`='Te desafío.' WHERE `ID`=67350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 바로 그겁니다! 우리 탄산주는 전 비취 숲에서 사랑받습니다. 제가 다 들고 갈 수 있으면 좋겠네요.', `MaleText_loc4`='对，就是那个！我们的果酒享誉翡翠林。真希望我能把它们都带在身上。', `MaleText_loc5`='沒錯，就是那些東西!我們的蘋卉酒在翠玉林可是極受重視的。我希望我有辦法能拿走全部。', `MaleText_loc7`='¡Sí, eso es! Nuestra sidra es valorada por todo el Bosque de Jade. Espero poder cargar con todo.' WHERE `ID`=67351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아가 안개로 덮인 후에는 전쟁이라고 할 만한 분쟁이 없었습니다. 그리고 그 밖의 문제들은 대부분 음영파에서 해결했고요.', `MaleText_loc4`='潘达利亚自从被迷雾笼罩之后，就再也没经历过全面战争。影踪派总能应对在这片土地上滋生的任何麻烦。', `MaleText_loc5`='潘達利亞在迷霧壟罩後就已經沒有發生過大規模的戰爭了。影潘通常會處理這座大陸上任何突發的麻煩。', `MaleText_loc7`='Pandaria no ha experimentado una guerra a gran escala desde que surgió la niebla. Normalmente el Shadopan se encarga de todos los problemas del continente.' WHERE `ID`=67352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들을 어떻게 받아들여야 할지 모르겠습니다. 당신들의 전쟁을 우리 땅에서까지 이어가는 이유가 뭡니까? 이... 호드와 싸우는 이유는 뭡니까?', `MaleText_loc4`='哎……我不知道该怎么说你们。为什么要把战争引到我们的海岸上来？为什么要跟这……部落作战？', `MaleText_loc5`='呃哼...我不知道該怎麼看你們族人。你們為什麼要將你們的戰爭帶到我們的岸邊來?你們為什麼要和這個...部落戰鬥?', `MaleText_loc7`='No sé qué pensar de tu gente. ¿Por qué han traído la guerra a nuestras costas? ¿Por qué luchan contra esa... Horda?' WHERE `ID`=67353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 시장님이 걱정이 많습니다. 당신들 문제를 해결하기 위해 음영파까지 부르셨습니다! 타란 주 님이 이곳에 오셨다는 게 정말 믿기지 않습니다!', `MaleText_loc4`='康村长担心不已，他请求影踪派帮忙应对你们的到来。我至今还不敢相信祝踏岚来了！', `MaleText_loc5`='康村長非常擔心，他甚至找影潘來處理你們的出現!我還是無法相信塔蘭·祝大人到這裡來了。', `MaleText_loc7`='¡El alcalde Khang está tan preocupado que hasta llamó a un Shadopan para encargarse de ustedes! Todavía no me puedo creer que lord Taran Zhu esté aquí.' WHERE `ID`=67354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들의 다툼에 끼어들고 싶지는 않지만, 전쟁의 날이 밝은 것 같군요. 평화를 선택할 수 없는 상황이라고 생각되네요.', `MaleText_loc4`='我们不愿卷入你们的争端。可我担心的是，一旦燃起战火，我们将再难独善其身。', `MaleText_loc5`='我們並不希望捲入你們的紛爭。但我很悲觀的覺得，當戰爭出現在地平線時，和平已不是選項了。', `MaleText_loc7`='No queremos formar parte de su conflicto, pero me temo que cuando la guerra está en el horizonte, la paz no es una opción.' WHERE `ID`=67355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 머리가 너무 복잡하네요. 마지막 황제께서는 공포의 그림자 아래에서 살지 말라고 하셨습니다. 이제 우리가 술잔을 기울이며 축제를 벌이기를 좋아하는 이유를 아시겠어요?', `MaleText_loc4`='啊，这想法真令人不安。我们的末代皇帝建议我们不要活在恐惧的阴影里。现在你明白为什么我们喜欢喝酒和欢庆了吗？', `MaleText_loc5`='啊，這些想法真是惱人。我們的最後一任皇帝囑咐我們不要生活在恐懼的陰影之下。你現在能明白為什麼我們喜歡飲酒和歡慶了嗎?', `MaleText_loc7`='Ah, qué pensamientos tan preocupantes. Nuestro último emperador nos aconsejó que no viviéramos bajo la sombra del miedo. ¿Entiendes ahora por qué nos encanta beber y festejar?' WHERE `ID`=67356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 침략자들! 모두 꺼져라!', `MaleText_loc4`='你们这些入侵者！出去！', `MaleText_loc5`='入侵者!統統滾出去!', `MaleText_loc7`='¡Invasores, todos ustedes! ¡Fuera!' WHERE `ID`=67357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 전사가 아니다. 하지만 온 힘을 다해 포우돈 마을을 지키겠다!', `MaleText_loc4`='我不是战士，可我也会帮忙守卫坡东村！', `MaleText_loc5`='我並不是名戰士，但我也會幫忙防守坡東村!', `MaleText_loc7`='No soy ningún guerrero, ¡pero yo también defenderé la Aldea Zarpa''don!' WHERE `ID`=67358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 꺼져라, 침입자들아!', `MaleText_loc4`='离开这里，闯入者！', `MaleText_loc5`='給我統統消失，入侵者!', `MaleText_loc7`='¡Marchaos, intrusos!' WHERE `ID`=67359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아아아아!', `MaleText_loc4`='咿呀！', `MaleText_loc5`='耶啊啊啊啊啊啊啊!', `MaleText_loc7`='¡Aaaarrrgghhh!' WHERE `ID`=67360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리... 과수원에서... 꺼져!', `MaleText_loc4`='离……开……我的……果园！', `MaleText_loc5`='滾...出...我...的...果園', `MaleText_loc7`='¡Fuera... de... mi... huerto!' WHERE `ID`=67361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탄산주를 보호해야 합니다!', `MaleText_loc4`='我们必须保护美酒！', `MaleText_loc5`='我們必須保護酒!', `MaleText_loc7`='¡Debemos proteger la cerveza!' WHERE `ID`=67362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 전사는 아니지만, 내 집과 가족을 지키고 싶다!', `MaleText_loc4`='我也许不是一名战士，可我会保护我的家园和家人！', `MaleText_loc5`='我或許不是一個戰士，但我會保護我的家園和家人!', `MaleText_loc7`='Es posible que no sea un guerrero, ¡pero protegeré mi hogar y a mi familia!' WHERE `ID`=67363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용기를 내, 텅. 애플블룸 가문의 탄산주가 위험에 처했어!', `MaleText_loc4`='拿出勇气来，邓！苹花家的甜酒危在旦夕！', `MaleText_loc5`='勇敢一點，騰。蘋卉家的酒正危在旦夕!', `MaleText_loc7`='Sé valiente, Teng. ¡La sidra de la familia Manzana Jugosa está en juego!' WHERE `ID`=67364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다! 술통은 과수원에 있어요.', `MaleText_loc4`='我们走吧！酒桶在果园里。', `MaleText_loc5`='我們走!桶子就在果園中。', `MaleText_loc7`='Vámonos. Los barriles están en el huerto.' WHERE `ID`=67365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멋진 의식이야.', `MaleText_loc4`='那是个非常奇特的仪式。', `MaleText_loc5`='這是個很花俏的儀式。', `MaleText_loc7`='Es un ritual muy elaborado.' WHERE `ID`=67366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멋진 의식을 방해하지 않는 게 좋을 거야.', `MaleText_loc4`='你要尽量避免打断这个奇特的仪式。', `MaleText_loc5`='你最好不要打攪這個花俏的高超儀式。', `MaleText_loc7`='No es buena idea interrumpir este ritual tan formal.' WHERE `ID`=67367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수상한 눈더미에서 짓궂은 눈 요마가 튀어나옵니다.', `MaleText_loc4`='从可疑的雪堆里钻出了一只淘气的雪妖。', `MaleText_loc5`='一個搗蛋雪妖精從可疑的雪堆中冒了出來。', `MaleText_loc7`='Un duende de nieve travieso sale del montón de nieve sospechoso.' WHERE `ID`=67368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있으면 저게 우릴 공격하진 않을 겁니다!', `MaleText_loc4`='别动，相信它不会攻击我们的！', `MaleText_loc5`='站住不要動，我想這樣它就不會攻擊我們了!', `MaleText_loc7`='Si no te mueves, ¡creo que no nos atacará!' WHERE `ID`=67369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 하든 당근 같아 보이면 안 됩니다!', `MaleText_loc4`='不管你做什么，别让自己看上去像根胡萝卜！', `MaleText_loc5`='不管你做什麼，千萬不要讓自己看起來像根胡蘿蔔!', `MaleText_loc7`='Pase lo que pase, ¡no pongas cara de zanahoria!' WHERE `ID`=67370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 다리를 건너려고 하면 공격하십시오!', `MaleText_loc4`='要是它想过桥，就发起攻击！', `MaleText_loc5`='如果它想越過這座橋就攻擊!', `MaleText_loc7`='Si intenta cruzar el puente, ¡ataca!' WHERE `ID`=67371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 놈들을 물리치는 덴 익숙하지요...', `MaleText_loc4`='我习惯击退小不点……', `MaleText_loc5`='我習慣擊退比較小隻的...', `MaleText_loc7`='No estoy acostumbrado a luchar contra los grandes...' WHERE `ID`=67372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 이게 뭡니까? 처음으로 되찾은 맥주통이로군요! 이건 제가 갖겠습니다.', `MaleText_loc4`='看看我们找到了什么。第一桶失而复得的美酒！这桶归我了，各位。', `MaleText_loc5`='看看我們找到了什麼。我們取回的第一桶酒!這桶是我的了，兄弟們。', `MaleText_loc7`='Vaya, vaya. ¿Qué tenemos aquí? ¡Nuestro primer barril de brebaje recuperado! Ya me lo quedo yo.' WHERE `ID`=67373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 해일의 힘에서 신성한 힘에 이르기까지 여러 가지 치유 마법에 손을 댔지만, 본디는 우아한 안개의 힘을 다루는 데 가장 소질이 있습니다.', `MaleText_loc4`='我对各种形式的恢复魔法都有所涉猎，从潮汐之能到神圣之力，但我真正擅长驾驭的始终是雾之优雅。', `MaleText_loc5`='我對於各式各樣的回復魔法都有涉略，從潮汐的能量到神聖的力量都小有研究，不過真正讓我想要深入研究的莫過於是迷霧的優雅了。', `MaleText_loc7`='He probado varias formas de magia restauradora, desde el poder de las mareas hasta la fuerza de la divinidad, pero mi auténtica vocación siempre será la gracia de la niebla.' WHERE `ID`=67374;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 계속 모구의 활동을 주시할 거예요, $n 님. 하지만 이 앞의 적을 상대하려면 지금보다는 더 큰 힘이 필요해요. 경험을 더 쌓은 후에 돌아오세요.', `FemaleText_loc4`='我们会继续监视魔古族的动态，$n。但是，恐怕要具备更大的力量才能应对前方的危险，你目前还没做好准备。等你累积更多经验后，再回来找我们吧。', `FemaleText_loc5`='我們會繼續監視魔古的行動，$n。然而，我害怕接下來的挑戰會需要你擁有比現在更強大的力量。在你得到更多經驗後再回來找我們。', `FemaleText_loc7`='Seguiremos controlando la actividad de los mogu, $n, pero me temo que lo que nos espera exige una fuerza de la que aún careces. Vuelve a vernos cuando tengas más experiencia.' WHERE `ID`=67375;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 대련 상대에게 맛있는 먹거리를 주는 걸 좋아한답니다. 그 다음엔 뭉개 버리죠.', `FemaleText_loc4`='在粉碎我的对手前，我总是喜欢让他们美餐一顿。', `FemaleText_loc5`='我喜歡在徹底摧毀我的競爭對手前，先讓他們吃點好料的。', `FemaleText_loc7`='Me gusta ofrecer algún plato delicioso a mis oponentes... antes de aplastarlos.' WHERE `ID`=67376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때는 사제가 너무 강하다고 생각한 적이 있었습니다. 지금은 도적이 강하다고 생각하지만요.', `MaleText_loc4`='我曾经以为过于强大的是牧师。现在看来，是潜行者才对。', `MaleText_loc5`='以前我覺得是牧師過強。現在我認為是盜賊。', `MaleText_loc7`='Antes pensaba que los sacerdotes eran demasiado poderosos. Ahora creo que son los pícaros.' WHERE `ID`=67377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='같은 수도사가 고통을 받는 모습은 보기 괴롭지만, 차차 적응이 되겠지요.', `MaleText_loc4`='我不忍心看武僧同伴们受苦。可我能撑过去。', `MaleText_loc5`='我不喜歡看到武僧同伴受傷。不過我會習慣的。', `MaleText_loc7`='No me gusta ver sufrir a otros monjes. Pero se me pasa.' WHERE `ID`=67378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하고 싶습니다.', `MaleText_loc4`='我想要挑战你。', `MaleText_loc5`='我想要挑戰你。', `MaleText_loc7`='Te desafío.', `FemaleText_loc1`='도전하고 싶어요.', `FemaleText_loc4`='我想要挑战你。', `FemaleText_loc5`='我想要挑戰你。', `FemaleText_loc7`='Te desafío.' WHERE `ID`=67379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하이트 사부님은 늘 할 일이 많아 ''죽겠다고'' 엄살이시지요. 사부님 입에서 그 말이 나오게 만들어 봐요. 내기를 해도 재밌다니까요.', `MaleText_loc4`='海特总会对我们没完没了的工作发牢骚。看看你能不能让他打开话匣子。绝对是滔滔不绝。', `MaleText_loc5`='高大師總是對我們「數不清」的工作有發不完的牢騷。你可以去試試看是否能讓他說出來，保證滔滔不絕。', `MaleText_loc7`='Cenit siempre habla de los "montones y montones" de trabajo que tenemos que hacer. Intenta hacérselo decir. Se le traba la lengua.' WHERE `ID`=67380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전하고 싶습니다.', `MaleText_loc4`='我想要挑战你。', `MaleText_loc5`='我想要挑戰你。', `MaleText_loc7`='Te desafío.', `FemaleText_loc1`='도전하고 싶어요.', `FemaleText_loc4`='我想要挑战你。', `FemaleText_loc5`='我想要挑戰你。', `FemaleText_loc7`='Te desafío.' WHERE `ID`=67381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까. 저도 쳉입니다. 다른 쳉과는 아무 관계가 없지요.

예, 저는 수도사입니다. 한때는 악마사냥꾼이 되고 싶었던 적도 있지만 말이지요.', `MaleText_loc4`='不，我不是那个程。没任何关系。 

是的，我是一位武僧，尽管我总梦想着有一天能成为猎魔人。', `MaleText_loc5`='不是，我是另外一個程。跟那個程沒有血緣關係。

對，我是個武僧，不過我一直都想當個惡魔獵人。', `MaleText_loc7`='No, yo soy el otro Cheng. No hay parentesco.

Sí, soy un monje, aunque siempre he soñado con ser un cazademonios.' WHERE `ID`=67382;
