UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다. 지금처럼 몸과 정신을 빠르게 움직이면 살아남을 수 있을 겁니다.', `MaleText_loc4`='干得好。记住，只有身心矫捷，才能活得长久。', `MaleText_loc5`='做得好。記住，心智和身體的靈敏能讓你保命。', `MaleText_loc7`='Bien hecho. Recuerda que la agilidad física y mental te mantendrá con vida.' WHERE `ID`=67386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단히 강하군요. 패배를 인정할게요.', `FemaleText_loc4`='你的力量令人叹为观止。我认输。', `FemaleText_loc5`='你的實力令人欽佩。我承認落敗。', `FemaleText_loc7`='Tu poder es impresionante. Admito la derrota.' WHERE `ID`=67387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='졌습니다.', `MaleText_loc4`='我败了。', `MaleText_loc5`='我打輸了。', `MaleText_loc7`='Me has derrotado.' WHERE `ID`=67388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단히 강하군요. 패배를 인정합니다.', `MaleText_loc4`='你的力量令人叹为观止。我认输。', `MaleText_loc5`='你的力量令人印象深刻。我承認落敗。', `MaleText_loc7`='Tu poder es impresionante. Admito la derrota.' WHERE `ID`=67389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대단히 강하군요. 패배를 인정합니다.', `MaleText_loc4`='你的力量令人叹为观止。我认输。', `MaleText_loc5`='你的力量令人印象深刻。我承認落敗。', `MaleText_loc7`='Tu poder es impresionante. Admito la derrota.' WHERE `ID`=67390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠의 마지막 함대가 공격하러 오고 있습니다!', `MaleText_loc4`='最后一波猢狲舰船来袭了！', `MaleText_loc5`='最後一波猴人船隻已經開始攻擊了!', `MaleText_loc7`='¡La última oleada de barcos hozen ataca!' WHERE `ID`=67391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 물리친 다음에는, 동료와 함께 보를 위해 밀림 맥주를 모으십시오!', `MaleText_loc4`='等你打败他们之后，跟同伴一起为珀收集丛林酒！', `MaleText_loc5`='在你擊敗他們之後，幫助你的盟友收集叢林啤酒給阿波。', `MaleText_loc7`='Cuando hayas acabado con ellos, ¡ayuda a tus aliados a reunir brebaje de jungla para Bo!' WHERE `ID`=67392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 포위해라! 한 놈도 놓치지 마라!', `MaleText_loc4`='包围他们！一个也别放走！', `MaleText_loc5`='包圍他們!別讓任何人逃走!', `MaleText_loc7`='¡Rodéenlos! ¡Que no eh''cape nadie!' WHERE `ID`=67395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 뼈에서 살을 분리해라!', `MaleText_loc4`='把他们的肉从骨头上扯下来！', `MaleText_loc5`='將他們的肉從骨頭上撕下來!', `MaleText_loc7`='¡Arránquenles la carne de los huesos!' WHERE `ID`=67396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤의 힘을 보여 줘라!', `MaleText_loc4`='让他们见识巨魔的力量！', `MaleText_loc5`='讓他們見識食人妖的力量!', `MaleText_loc7`='¡Enséñenles el poder de los trols!' WHERE `ID`=67397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 죽여라! 할 일이 많다!', `MaleText_loc4`='迅速干掉他们！还有很多事情要做！', `MaleText_loc5`='讓他們死得痛快!我們還有很多事要做!', `MaleText_loc7`='¡Que mueran rápido! Tenemos cosas que hacer.' WHERE `ID`=67398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰난 님, 희망의 날개를 또 받을 수 있을까요?', `MaleText_loc4`='思南，请再给我一次希望之翼好吗？', `MaleText_loc5`='你能再給我一次希望之翼嗎，司南?', `MaleText_loc7`='Sinan, ¿me puedes volver a dar las alas de esperanza?', `FemaleText_loc1`='쓰난 님, 희망의 날개를 또 받을 수 있을까요?', `FemaleText_loc4`='思南，请再给我一次希望之翼好吗？', `FemaleText_loc5`='你能再給我一次希望之翼嗎，司南?', `FemaleText_loc7`='Sinan, ¿me puedes volver a dar las alas de esperanza?' WHERE `ID`=67399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 남아 있는 우리 물건을 사고 싶은 생각은 없니? 이제 우리가 살아남으려면, 다른 마을에서 음식과 물을 사야 할 것 같으니 말이다.', `FemaleText_loc4`='也许我们可以把剩下的货物卖给你，换些金币？要想活命，我们就必须从其它村子采购食物和饮水。', `FemaleText_loc5`='也許我們可以將我們一些剩下的貨物賣給你交換黃金?如果我們想存活下去，我們得要向其他村莊購買食物和水。', `FemaleText_loc7`='¿Podríamos preparar la venta de algunos de nuestros bienes restantes a cambio de tu oro? Si queremos sobrevivir, tendremos que comprar comida y agua de otras aldeas.' WHERE `ID`=67400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고생을 많이 했구나. 앞으로 여행하는 동안 필요한 물건이 있으면 꼭 내게 알려주렴.', `FemaleText_loc4`='你看起来似乎饱经风霜。要是你想买什么旅途用品，一定要告诉我。', `FemaleText_loc5`='你看起來似乎經歷了許多風雨。別客氣，如果你想要購買任何對你旅途有幫助的東西，來跟我說。', `FemaleText_loc7`='Tienes aspecto de haber sufrido mucho. No dudes en venir a verme si quieres comprar algo para tus viajes.' WHERE `ID`=67401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 걸고 우리 집을 지키겠습니다!', `MaleText_loc4`='我会用生命保护我的家园！', `MaleText_loc5`='我會以我的性命保衛我的家園!', `MaleText_loc7`='¡Defenderé mi hogar con mi vida!' WHERE `ID`=67402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 아이들은 전쟁을 모르고 자랄 수 있게 하겠습니다!', `MaleText_loc4`='只要我守口如瓶，就能让孩子们对战争一无所知！', `MaleText_loc5`='如果我有選擇的話，我的孩子們不會知道戰爭是什麼!', `MaleText_loc7`='¡Mis hijos no conocerán la guerra si puedo evitarlo!' WHERE `ID`=67403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 발만 더 다가오면... 제... 제가... 공격하겠습니다! 정말입니다!', `MaleText_loc4`='再敢靠近一步，我就……我就攻击了！我发誓！', `MaleText_loc5`='你只要在靠近一步，我就...我就...會攻擊!我發誓!', `MaleText_loc7`='Si das un paso más... ¡Atacaré! ¡Lo juro!' WHERE `ID`=67404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신들과는 싸우지 않겠어요. 우리 물건 좀 보실래요?', `FemaleText_loc4`='我们跟你们无冤无仇。愿意挑选些货物吗？', `FemaleText_loc5`='我們和你們族人沒有爭端。你想要看看我們的貨物嗎?', `FemaleText_loc7`='No le deseamos ningún mal a tu gente. ¿Deseas probar nuestra mercancía?' WHERE `ID`=67405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 마을은 전쟁이 아니라 교역으로 유명하죠. 제 물건을 보시겠어요?', `FemaleText_loc4`='我们是生意人，不是战士。要不要看看我的商品？', `FemaleText_loc5`='我們以貿易聞名，而不是戰爭。你想要看看我有賣些甚麼東西嗎?', `FemaleText_loc7`='Nos hemos labrado una reputación con el comercio, no con la guerra. ¿Quieres ver lo que tengo a la venta?' WHERE `ID`=67406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교전 중에 빗나간 포탄이 저희 농장을 날려버렸습니다. 이제 어떻게 살아야 합니까?', `MaleText_loc4`='一颗不长眼的炸弹击毁了我的农场。我该怎么生活下去？', `MaleText_loc5`='在火拼中一顆滾出來的炸彈摧毀了我的農場。我該要如何像這樣繼續活下去?', `MaleText_loc7`='Una bomba perdida de la batalla destruyó mi granja. ¿Cómo voy a vivir ahora?' WHERE `ID`=67407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 곳에서 다시 농장을 가꾸면 어떻겠습니까? 다른 마을 주민들도 분명히 도와줄 겁니다.', `MaleText_loc4`='为什么不去其它地方重新开垦农田？相信其他村民会帮助你的。', `MaleText_loc5`='為何不在其他地方重建你的農場呢?我很確定其他村民會幫助你的。', `MaleText_loc7`='¿Por qué no construyes otra granja en otro lado? Seguro que los demás aldeanos te ayudan.', `FemaleText_loc1`='다른 곳에서 다시 농장을 가꾸면 어떨까요? 다른 마을 주민들도 분명히 도와줄 거예요.', `FemaleText_loc4`='为什么不去其它地方重新开垦农田？相信其他村民会帮助你的。', `FemaleText_loc5`='為何不在其他地方重建你的農場呢?我很確定其他村民會幫助你的。', `FemaleText_loc7`='¿Por qué no construyes otra granja en otro lado? Seguro que los demás aldeanos te ayudan.' WHERE `ID`=67408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러고 보니 이곳 남쪽에 있는 절벽 주변 땅이 좋아 보이긴 하더군요. 협곡을 내려다보는 장소지요. 당신 말이 맞을지도 모르겠습니다, 이방인.', `MaleText_loc4`='在南边有一处断崖，在那种田应该不错。站在崖边还能俯瞰峡谷。你也许是对的，陌生人。', `MaleText_loc5`='在這裡南邊有一個山崖俯瞰著一座峽谷，很適合建造一座農場。也許你是對的，陌生人。', `MaleText_loc7`='Hay un promontorio al sur de aquí que sería perfecto para una granja. Se alza sobre una garganta. A lo mejor tienes razón, $gforastero:forastera;.' WHERE `ID`=67409;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을이 지긋지긋해요. 저도 여행을 하고 세계를 볼 수 있으면 좋겠어요. 돈을 충분히 저축하면, 저도 저만의 장대한 모험을 떠날 수 있을지 모르죠.', `FemaleText_loc4`='我在这村里住腻了。真希望能到处旅行，看看这个世界啊。也许等我存够了钱，我就能开始自己的史诗冒险了！', `FemaleText_loc5`='我對這個村莊感到厭煩。我好希望我能出去旅遊，看看這個世界。也許在我存到足夠的黃金後，我會展開屬於我自己史詩般的冒險!', `FemaleText_loc7`='Me estoy cansando de esta aldea. Me gustaría viajar y ver mundo. ¡A lo mejor cuando haya ahorrado lo suficiente podré vivir aventuras épicas!' WHERE `ID`=67410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 전사가 아닙니다. 저는 사냥에 쓰는 간단한 무기와 도구만을 제작합니다.', `MaleText_loc4`='我们不是战士。我只负责制作工具和狩猎用的轻型武器。', `MaleText_loc5`='我們不是戰士。我只會製造狩獵用的工具和輕型武器。', `MaleText_loc7`='No somos guerreros. Solo fabrico herramientas y armas ligeras para cazar.' WHERE `ID`=67411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀이슬 마을은 전투를 치를 준비가 되지 않았습니다. 이 전쟁이 곧 끝나기만을 바랍니다.', `MaleText_loc4`='蜜露村根本没做好战斗的准备。希望这场争斗能尽早结束！', `MaleText_loc5`='甘露村對戰爭根本毫無準備。我希望這場爭鬥能快快結束。', `MaleText_loc7`='El Poblado Almíbar no está preparado para la guerra. ¡Espero que la batalla termine pronto!' WHERE `ID`=67412;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에... 그거 정말 멋진 무기군요.', `FemaleText_loc4`='哦天哪……那武器真不一般。', `FemaleText_loc5`='喔，我的天...那真是個驚人的武器。', `FemaleText_loc7`='Vaya... Qué arma más impresionante.' WHERE `ID`=67413;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐 푹 쉬고 싶지 않으세요? 물론 전투보다는 휴식이 낫겠죠?', `FemaleText_loc4`='想不想躺下歇会儿？那听起来当然比战斗要好。', `FemaleText_loc5`='想要躺下來休息一下嗎?聽起來比繼續戰鬥要好多了。', `FemaleText_loc7`='¿No te apetece echarte un rato y descansar? Seguro que es mejor que luchar.' WHERE `ID`=67414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇게 섬세한 방어구를 어디서 구하셨나요? 제가... 좀 만져 봐도 될까요?', `FemaleText_loc4`='你是从哪儿找到那么精美的护甲的？能让我……摸一下吗？', `FemaleText_loc5`='你是在哪裡得到如此精美的裝甲?我能...摸一下嗎?', `FemaleText_loc7`='¿Dónde has encontrado una armadura tan exquisita? ¿Puedo... tocarla?' WHERE `ID`=67415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음식은 삶의 핵심이네. 자네처럼 용감한 $c|1이라도;라도; 잠깐 여기 앉아서 그 핵심을 맛봐야 하네!', `MaleText_loc4`='美食是生活中必不可少的。即便是像你这么勇敢的$c，也应该花时间坐下来享受人生的精华！', `MaleText_loc5`='食物是生命的必需品。即使是像你一樣英勇的$c也能找到時間坐下來，並好好享受生命的精華!', `MaleText_loc7`='El alimento es indispensable para la vida. Hasta $gun:una; $c como tú puede sentarse un rato para disfrutar de la esencia de la vida.' WHERE `ID`=67416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 술은 마시기가 좋지만, 요리에도 쓸모가 많다는 사실까지는 모르는 이가 많더군! 이 판다리아에 내 달콤한 꿀이슬 생선구이보다 더 맛있는 음식은 없지!', `MaleText_loc4`='许多人都忘了，美酒不仅可以用来喝，还能用来烹饪美食！在全潘达利亚，没什么能跟我大名鼎鼎的蜜露烤鱼相提并论！', `MaleText_loc5`='許多人忘記美酒不只能拿來喝，還可以用來烹調!整個潘達利亞沒有任何東西能比得上我有名的甘露糖汁魚!', `MaleText_loc7`='Mucha gente se olvida de que la buena cerveza también sirve para cocinar, no solo para beber. ¡Mi famoso pescado caramelizado Almíbar no tiene rival en toda Pandaria!' WHERE `ID`=67417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 커다란 위협이 닥쳐온 순간에도, 음식은 없어서는 안 될 소중한 존재라네. 내가 요리를 하는 데 들이는 시간도 충분히 가치가 있다고.', `MaleText_loc4`='即使是在眼下这种战乱时期，人们也仍然需要并享受着美食。我花再长时间烹饪也是值得的。', `MaleText_loc5`='就算在像這樣動亂的時候，食物還是會為人們所需要與喜愛。這讓我花幾小時烹煮也非常值得。', `MaleText_loc7`='Hasta en épocas de grandes conflictos, como esta, la comida es necesaria y agradecida. Hace que las horas que me paso cocinando merezcan la pena.' WHERE `ID`=67418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 맥주를 안전한 곳으로 가져가야 합니다. 제 맥주는 이 마을 전체의 생명줄이니까요!', `MaleText_loc4`='我们得把酒送到安全的地方。我的佳酿简直是全村的命脉！', `MaleText_loc5`='我們必須把酒運到安全的地方。我的酒是整個村子的生命泉源!', `MaleText_loc7`='Debemos llevar la cerveza a un lugar seguro. ¡Mi cerveza es la esencia de toda esta aldea!' WHERE `ID`=67419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길을 비우세요! 맥주 배달부가 갑니다!', `MaleText_loc4`='让开，送酒员来了！', `MaleText_loc5`='清空道路，運酒者快到了!', `MaleText_loc7`='¡Despejen el camino! ¡Viene el corredor de cerveza!' WHERE `ID`=67420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들여보내십시오! 건장하고 젊은 판다렌이 꿀술 통을 되찾아 왔습니다!', `MaleText_loc4`='让他过来！那个魁梧的年轻熊猫人救了一桶蜜酒！', `MaleText_loc5`='讓他過去!那個魁梧的年輕熊貓人正在拯救一桶甘露酒!', `MaleText_loc7`='¡Dejadle pasar! ¡Ese valiente joven pandaren está salvando un barril de birramiel!' WHERE `ID`=67421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주가 지나갑니다!', `MaleText_loc4`='美酒来了！', `MaleText_loc5`='酒桶運過來了!', `MaleText_loc7`='¡Viene la cerveza!' WHERE `ID`=67422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 날 준비가 안 됐어요!', `FemaleText_loc4`='它还没准备好起飞呢，姐妹！', `FemaleText_loc5`='它還沒準備好升空，姊妺!', `FemaleText_loc7`='Hermana, ¡todavía no está listo para volar!' WHERE `ID`=67423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쩔 수 없어요! 여기서 무슨 일이 벌어지고 있는지, 다른 주민들에게 알려야 해요!', `FemaleText_loc4`='我们别无选择！必须通知其他村民，让他们知道这里发生的一切！', `FemaleText_loc5`='我們沒有選擇餘地!我們必須警告其他村子這裡發生了什麼事!', `FemaleText_loc7`='¡No tenemos alternativa! ¡Hay que alertar a las demás aldeas de lo que está pasando!' WHERE `ID`=67424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서둘러 주세요. 어서 가고 싶어요.', `FemaleText_loc4`='请抓紧时间。我想出发了。', `FemaleText_loc5`='拜託快點。我想要啟程了。', `FemaleText_loc7`='Date prisa. Quiero irme.' WHERE `ID`=67425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.', `FemaleText_loc4`='对我鞠躬，我们就开始。', `FemaleText_loc5`='向我鞠躬，我們就可以開始了。', `FemaleText_loc7`='Hazme una reverencia y podremos empezar.' WHERE `ID`=67426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐만 기다려 주세요. 제가 고칠 수 있어요. 정말로요.', `FemaleText_loc4`='再给我点时间，我能弄好。真的。', `FemaleText_loc5`='再給我一點點時間，我可以修好它的。我知道我可以。', `FemaleText_loc7`='Si me das un poco más de tiempo, puedo arreglarlo. Sé que puedo.' WHERE `ID`=67427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘불꽃호가 데스윙과의 전투 이후 전면 개조를 거쳐 새롭게 태어났네! 이제 고정익 비행기, 자이로 비행기 편대와 더불어 구경 45센티미터의 해안 활강포를 여러 문 갖춘 완벽한 공격함으로 거듭났지.$b$b우리 사거리 내에서 호드가 숨을 수 있는 곳은 없네. 땅에서도, 바다에서도, 공중에서도 적을 전멸시킬 수 있으니까.', `FemaleText_loc4`='在遭遇死亡之翼后，我们已经对天火号进行了全面改装！我们现在不但有了舰载固定翼战机和旋翼机，还给它装上了18英寸口径的滑膛式海岸轰击炮组。$b$b密集的炮火一定会让部落无处遁形，随便他们上天入地，翻山过海，都会被我们给炸出来。', `FemaleText_loc5`='在我們那場與死亡之翼的戰鬥之後，天火號進行過一場完整的大翻修!我們現在載有完整的固定機翼與旋翼戰機，及一組18吋的滑膛岸轟大砲。$B$B部落將沒有辦法逃離她的攻擊範圍。在地上不行，海上不行，在空中也不行。', `FemaleText_loc7`='¡Hemos renovado el Abrasacielos por completo desde nuestro encuentro con Alamuerte! Ahora llevamos un destacamento completo de aviones y girocópteros, así como una batería de cañones aire-tierra de ánima lisa de dieciocho pulgadas.$b$bLa Horda no puede huir de esta nave. Ni en la tierra, ni en el mar, ni en el aire.' WHERE `ID`=67428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발할 준비가 됐습니다.', `MaleText_loc4`='我准备好出发了。', `MaleText_loc5`='我準備好要離開了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='출발할 준비가 됐어요.', `FemaleText_loc4`='我准备好出发了。', `FemaleText_loc5`='我準備好要離開了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=67429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥! 너는 여기에서 환영받지 못한다!', `MaleText_loc4`='呸！这里不欢迎你！', `MaleText_loc5`='呸!你在這裡不受歡迎!', `MaleText_loc7`='¡Buu! ¡No os queremos aquí!' WHERE `ID`=67430;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간을 잘 재서 적의 경혈에 힘을 가하면, 적이 뭘 하고 있었든 중단시킬 수 있습니다. 이 점을 잘 활용해 위험한 공격을 피하세요.', `FemaleText_loc4`='不论敌人使出何种招数，若能逮准时机命中要害，就会使其动弹不得。利用这一要诀，避开致命攻击。', `FemaleText_loc5`='抓準時機對一個壓力點施力能讓對手停下來，不管他們在做什麼都一樣。好好利用這點來閃避危險的攻擊。', `FemaleText_loc7`='Una aplicación de fuerza bien sincronizada sobre un punto de presión puede detener a un oponente al instante, sin importar lo que estén haciendo. Aprovecha este conocimiento para evitar los ataques peligrosos.' WHERE `ID`=67431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹으로 모든 문제를 해결할 수 있는 건 아닙니다. 때로는 정신을 집중하고 멀리 있는 목표물을 향해 기운을 보내야 하지요.', `MaleText_loc4`='不是所有问题都能用拳头解决。有时你必须以自己为中心点，朝远处的目标引导你的能量。', `MaleText_loc5`='你的拳頭不能解決所有問題。有時你必須集中並將你的能量引導向一個在遠處的目標。', `MaleText_loc7`='No todos los problemas se pueden solucionar con los puños. A veces debes centrarte y canalizar tu energía hacia un objetivo distante.' WHERE `ID`=67432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.', `MaleText_loc4`='对我鞠躬，我们就开始。', `MaleText_loc5`='向我鞠躬，我們就可以開始了。', `MaleText_loc7`='Hazme una reverencia y podremos empezar.' WHERE `ID`=67433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사인 당신에게는, 반사 신경이 아주 큰 재산입니다. 빠르게 생각하고 움직일 수 있는 능력이 목숨을 구해 주기도 하니까요.', `MaleText_loc4`='作为武僧，反应力就是你最可宝贵的资源之一。迅速思考和行动的能力，常常能助你转危为安。', `MaleText_loc5`='作為一名武僧，你的反應能力是你最有力的資產之一。能迅速思考與行動的能力經常能救你一命。', `MaleText_loc7`='Como monje que eres, tus reflejos son uno de tus recursos más valiosos. La capacidad de pensar y actuar con rapidez puede salvarte la vida muchas veces.' WHERE `ID`=67434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 좋은 방어는, 상대의 움직임을 차단하는 것입니다.', `MaleText_loc4`='有时，最好的防御就是在敌人采取行动前，先发制人。', `MaleText_loc5`='有時最好的防禦就是阻止你的對手對你進行攻擊。', `MaleText_loc7`='A veces la mejor defensa es impedir que tu enemigo te ataque.' WHERE `ID`=67435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들고 있는 무기에서 힘을 얻는 적이 있습니다. 그럴 때는 무기를 빼앗으면 적의 힘이 줄어들지요.', `MaleText_loc4`='对某些敌人来说，大部分力量都是来自于手中挥持的武器。把武器夺走，他们就无计可施了。', `MaleText_loc5`='有些敵人大部分的力量來自於他們手中的武器。把武器奪走，他們對你的優勢就跟著消失。', `MaleText_loc7`='Algunos enemigos basan su poder en el arma que empuñan. Si se la arrebatas, el poder que tienen sobre ti desaparecerá.' WHERE `ID`=67436;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적시에 정확한 공격을 가하면, 아무리 강한 적도 일격으로 꺾을 수 있지요.', `FemaleText_loc4`='有时候，时机和精准都把握得恰到好处的攻击，足以击败最难对付的敌人。', `FemaleText_loc5`='有時一次抓準時機的精準攻擊就足以讓你擊敗最頑強的對手。', `FemaleText_loc7`='A veces un golpe preciso asestado en el momento adecuado es lo único que necesitas para derribar hasta al enemigo más resistente.' WHERE `ID`=67437;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자기 움직임을 통제하는 법을 배운 다음에는, 적을 통제해서 우위를 점하는 법을 배워야 합니다. 적의 속도를 느리게 하면 자기가 공격할 시간이 늘어나고, 그것이 승패를 가르기도 합니다.', `FemaleText_loc4`='等你学会控制自己的动作后，就必须学会控制敌人以占取先机。要是敌人动作迟缓，就能使你有更多时间发起攻击，往往能让胜败立显。', `FemaleText_loc5`='在你學會控制你自己的行動之後，你必須學著控制你的對手以取得上風。一個緩慢的對手讓你有更多時間能進行攻擊，這可能就是勝敗的關鍵。', `FemaleText_loc7`='Cuando hayas aprendido a controlar tus propios actos, tendrás que aprender a controlar los de tu oponente para tener ventaja. Un oponente ralentizado te da más tiempo para atacar, lo que puede suponer la diferencia entre la victoria y la derrota.' WHERE `ID`=67438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 재미있는 친구로군, $c. 그 마음 속의 어떤 열망이 자네를 판다리아로 이끌었나? 모험을 향한 목마름인가? 전투의 두근거림인가? 아니, 혹시 더 큰 무언가를 따라 왔나?', `MaleText_loc4`='你可真是耐人寻味啊，$c。是什么动力驱使你来到了潘达利亚？渴望冒险？期待战斗？也许还有别的？', `MaleText_loc5`='你是個非常有趣的人，$c。你心中在渴求什麼東西而使你來到潘達利亞?是對冒險的渴望?戰鬥的刺激?或許是更遠大的目標?', `MaleText_loc7`='Eres un personaje de lo más curioso, $c. ¿Qué deseo de tu corazón te ha traído a Pandaria? ¿Es la sed de aventuras? ¿La intensidad de la batalla? ¿O algo distinto?' WHERE `ID`=67439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 암흑의 시간을 견뎌내는 것은 이번이 처음이 아니네. 어둠의 끝에는 언제나 빛이 기다리고 있지.', `MaleText_loc4`='我们不是第一次经历黑暗时期了。在黑暗中总会有一抹曙光。', `MaleText_loc5`='這不是我們所忍受過的第一個黑暗時代。在陰影的邊緣永遠都會有一絲絲的光。', `MaleText_loc7`='No es la primera vez que vivimos tiempos oscuros. Siempre hay una luz al borde de la sombra.' WHERE `ID`=67440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서는 오랫동안 전쟁을 모르고 살았네. 우리 모두를 위해 어서 평화로운 시간이 찾아왔으면 좋겠군.', `MaleText_loc4`='我们已经许久没有经历过战事了。为了所有人的幸福，真希望和平能尽快到来。', `MaleText_loc5`='我們這裡已經很久沒有戰爭了。為了我們所有人好，我希望我們能快點找到和平。', `MaleText_loc7`='Hace mucho tiempo que no vivimos una guerra. Espero por el bien de todos nosotros que pronto encontremos la paz.' WHERE `ID`=67441;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 제게 예를 갖추어 인사하면 시작하도록 하지요.', `FemaleText_loc4`='对我鞠躬，我们就开始。', `FemaleText_loc5`='向我鞠躬，我們就可以開始了。', `FemaleText_loc7`='Hazme una reverencia y podremos empezar.' WHERE `ID`=67442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 상황이 어떠냐고요? 모든 걸 잃게 생겼습니다!', `MaleText_loc4`='我们怎么办？已经一败涂地了！', `MaleText_loc5`='我們該怎麼辦?我們正在失去一切!', `MaleText_loc7`='¿Qué hacemos? ¡Lo estamos perdiendo todo!', `FemaleText_loc1`='지금 상황이 어떠냐고요? 모든 걸 잃게 생겼다고요!', `FemaleText_loc4`='我们怎么办？已经一败涂地了！', `FemaleText_loc5`='我們該怎麼辦?我們正在失去一切!', `FemaleText_loc7`='¿Qué hacemos? ¡Lo estamos perdiendo todo!' WHERE `ID`=67443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작물이 없으면, 맥주도 만들 수 없습니다!', `MaleText_loc4`='要是没有了庄稼，我们就要失去美酒了！', `MaleText_loc5`='如果我們失去我們的農作物，我們就會失去我們的酒!', `MaleText_loc7`='Si perdemos nuestros cultivos, ¡perderemos la cerveza!', `FemaleText_loc1`='작물이 없으면, 맥주도 만들 수 없어요!', `FemaleText_loc4`='要是没有了庄稼，我们就要失去美酒了！', `FemaleText_loc5`='如果我們失去我們的農作物，我們就會失去我們的酒!', `FemaleText_loc7`='Si perdemos nuestros cultivos, ¡perderemos la cerveza!' WHERE `ID`=67444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 이곳에서까지 전쟁을 시작하지 마십시오. 우리와는 관계가 없습니다!', `MaleText_loc4`='拜托，别把战火引到这里来。这跟我们毫无干系！', `MaleText_loc5`='求求你，不要將你們的戰鬥帶來此地。我們不想涉入其中!', `MaleText_loc7`='Por favor, no traigáis la guerra hasta aquí. ¡No tiene nada que ver con nosotros!', `FemaleText_loc1`='제발, 이곳에서까지 전쟁을 시작하지 마세요. 우리와는 관계가 없다고요!', `FemaleText_loc4`='拜托，别把战火引到这里来。这跟我们毫无干系！', `FemaleText_loc5`='求求你，不要將你們的戰鬥帶來此地。我們不想涉入其中!', `FemaleText_loc7`='Por favor, no traigáis la guerra hasta aquí. ¡No tiene nada que ver con nosotros!' WHERE `ID`=67445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불이야! 불이야!', `MaleText_loc4`='火！火！', `MaleText_loc5`='開火!開火!', `MaleText_loc7`='¡Fuego! ¡Fuego!', `FemaleText_loc1`='불이야! 불!', `FemaleText_loc4`='火！火！', `FemaleText_loc5`='開火!開火!', `FemaleText_loc7`='¡Fuego! ¡Fuego!' WHERE `ID`=67446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 가족은 벌써 여러 세대 동안 이 마을을 지켰네. 나도 그 전통을 이어가고 싶네.', `MaleText_loc4`='我的家人世代守卫着这座村庄。我祈求自己能继承祖业。', `MaleText_loc5`='我的家族世代以來一直守衛著這個村子。我祈禱我能延續這項先祖流傳下來的傳統。', `MaleText_loc7`='Mi familia lleva generaciones protegiendo esta aldea. Rezo para estar a la altura de su legado.' WHERE `ID`=67447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀이슬 마을의 안전을 위해서라면, 기꺼이 내 목숨을 바치겠네. 이 마을의 역사는 내 인생과 마찬가지니까.', `MaleText_loc4`='我愿意献出自己的生命，以确保蜜露村安全无虞。这是祖业的传承。', `MaleText_loc5`='我很樂意為了確保甘露村的安全而獻出自己的生命。我將與它同在一起延續下去。', `MaleText_loc7`='Daría mi vida sin dudarlo para garantizar la seguridad del Poblado Almíbar. Su legado es el mío.' WHERE `ID`=67448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사 훈련은 끝나는 법이 없네. 항상 육신과 정신을 더 높은 곳으로 이끌어야 한다네.', `MaleText_loc4`='武僧的训练永无竭日。总有身心合一的更高境界等待追寻。', `MaleText_loc5`='一名武僧的訓練沒有停止的一天。身體和心智總是能向更高的境界邁進。', `MaleText_loc7`='Un monje nunca termina de entrenarse. Siempre hay un paso más, tanto para la mente como para el cuerpo.' WHERE `ID`=67449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리 땅에 전쟁과 피를 불러오는 건가요? 판다리아는 평화의 땅이라고요.', `MaleText_loc4`='你们为什么要让这片土地遭受战争和杀戮？潘达利亚是和平之地。', `MaleText_loc5`='你為什麼將戰爭和血鬥帶來我們的土地?潘達利亞是個和平的地方。', `MaleText_loc7`='¿Por qué traes la guerra y el derramamiento de sangre a nuestra tierra? Pandaria es un lugar pacífico.', `FemaleText_loc1`='왜 우리 땅에 전쟁과 피를 불러오는 건가요? 판다리아는 평화의 땅이라고요.', `FemaleText_loc4`='你们为什么要让这片土地遭受战争和杀戮？潘达利亚是和平之地。', `FemaleText_loc5`='你為什麼將戰爭和血鬥帶來我們的土地?潘達利亞是個和平的地方。', `FemaleText_loc7`='¿Por qué traes la guerra y el derramamiento de sangre a nuestra tierra? Pandaria es un lugar pacífico.' WHERE `ID`=67450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 타고난 전사는 아니에요. 하지만 우리 고향과 이 땅을 지켜내기 위해 무엇이든 하겠어요.', `MaleText_loc4`='我们也许不是正牌的战士，可我们会不惜一切代价守护自己的家园和土地。', `MaleText_loc5`='我們的職業也許不是戰士，但我們會為了拯救我們的家園與土地做任何事。', `MaleText_loc7`='Es posible que no seamos guerreros, pero haremos lo que haga falta para defender nuestros hogares y nuestra tierra.', `FemaleText_loc1`='우리는 타고난 전사는 아니에요. 하지만 우리 고향과 이 땅을 지켜내기 위해 무엇이든 하겠어요.', `FemaleText_loc4`='我们也许不是正牌的战士，可我们会不惜一切代价守护自己的家园和土地。', `FemaleText_loc5`='我們的職業也許不是戰士，但我們會為了拯救我們的家園與土地做任何事。', `FemaleText_loc7`='Es posible que no seamos guerreros, pero haremos lo que haga falta para defender nuestros hogares y nuestra tierra.' WHERE `ID`=67451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 나타나면서 이 땅의 미묘한 균형이 깨어진 것 같아요.', `MaleText_loc4`='我担心，你们的到来会打破这片土地微妙的平衡。', `MaleText_loc5`='我擔心你來到這裡會打亂這片土地纖弱的平衡。', `MaleText_loc7`='Me temo que su llegada alterará el delicado equilibrio de la tierra.', `FemaleText_loc1`='당신이 나타나면서 이 땅의 미묘한 균형이 깨어진 것 같아요.', `FemaleText_loc4`='我担心，你们的到来会打破这片土地微妙的平衡。', `FemaleText_loc5`='我擔心你來到這裡會打亂這片土地纖弱的平衡。', `FemaleText_loc7`='Me temo que su llegada alterará el delicado equilibrio de la tierra.' WHERE `ID`=67452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쳇, 이건 언제 터질지 모르는 폭탄 같잖아!', `MaleText_loc4`='呀，那东西是个致命陷阱！', `MaleText_loc5`='嘎，這東西是個死亡陷阱!', `MaleText_loc7`='¡Bah! ¡Este trasto es una trampa mortal!' WHERE `ID`=67453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신들이 타고 온 죽음의 비행기는 종말의 서막이에요.', `FemaleText_loc4`='你们的飞行死亡机器是末日来临的预兆。', `FemaleText_loc5`='你的飛行死亡機器是末日的徵兆。', `FemaleText_loc7`='Tu máquina voladora de la muerte es una señal del final de los tiempos.' WHERE `ID`=67454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신네 이방인들은 왜 그렇게 서로 싫어하시나요? 이해할 수가 없어요.', `FemaleText_loc4`='你们怎么如此仇恨其他外乡人？我不明白。', `FemaleText_loc5`='為什麼你們這麼痛恨其他外來者?我無法理解。', `FemaleText_loc7`='¿Por qué odiáis tanto a los otros forasteros? No lo entiendo.' WHERE `ID`=67455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보자... 여기 연료 공급 장치를 좀 풀어 주면...', `MaleText_loc4`='让我们瞧瞧……要是我把这个燃料阀门给卸下来的话……', `MaleText_loc5`='讓我瞧瞧...如果我把這裡的出油孔給鬆開...', `MaleText_loc7`='A ver... Si destornillo el tragacombustible...' WHERE `ID`=67456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳엔 왜 왔나?', `MaleText_loc4`='你为什么会来这里？', `MaleText_loc5`='你為什麼來到這裡?', `MaleText_loc7`='¿Para qué has venido aquí?' WHERE `ID`=67457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 "밸브"는 아무래도 뭔가의 발톱으로 만든 것 같은데. 고블린들이란 정말...', `MaleText_loc4`='我很确定，这个“阀门”其实是个脚趾甲。地精……', `MaleText_loc5`='我很確定這個「氣閥」是個腳指甲。哥布林喔...', `MaleText_loc7`='Creo que esta "válvula" es una uña del pie. Estos goblins...' WHERE `ID`=67458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌목기를 만지작거리며 %s|1이;가; 중얼거립니다.', `MaleText_loc4`='%s一边摆弄着伐木机，一边自言自语。', `MaleText_loc5`='%s在整修伐木機時咕噥地自言自語。', `MaleText_loc7`='%s murmura algo mientras trastea con la trituradora.' WHERE `ID`=67459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 오랫동안 평화를 누렸네. 이 땅에 전쟁을 불러오다니... 자네들은 어떻게 그런 생각을 할 수 있었는지 모르겠군.', `MaleText_loc4`='长久以来，我们已经过惯了和平的日子，真不知道大家要怎么应对这突然降临海岸的战事。', `MaleText_loc5`='我們長久以來只知道和平，我不知道人們要怎麼應對外來的人給我們帶來的戰爭。', `MaleText_loc7`='Hace tanto tiempo que vivimos en paz que no sé cómo vamos a reaccionar ante la llegada de la guerra a nuestras costas.' WHERE `ID`=67460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 전쟁 무기를 가지고 이곳에 왔습니까? 대체 이곳에서 전쟁과 피바다를 일으키면서, 뭘 얻어내려고 하는 겁니까?', `MaleText_loc4`='你们为什么要剑拔弩张地来到这里？你们在这里展开激战与杀戮，究竟有什么目的？', `MaleText_loc5`='你為什麼全副武裝地來到這裡?你來了戰爭和血鬥前來此處到底有什麼目的?', `MaleText_loc7`='¿Por qué venís con armas de guerra? ¿En qué os beneficia traer la guerra y el derramamiento de sangre a esta tierra?' WHERE `ID`=67461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인들이 언젠가는 우리 해안을 침투해 들어올 거라고 생각해 왔는데, 이렇게 당신네들이 나타났군요.', `MaleText_loc4`='我一直想知道，外乡人何时会闯上我们的海岸，然后你们就来了。', `MaleText_loc5`='我總是在想什麼時候會有外來者突破岸邊，而如今你來到了此地。', `MaleText_loc7`='Siempre me había preguntado cuándo veríamos forasteros en nuestras costas. Y aquí estáis.' WHERE `ID`=67462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 봐. 완전히 초보자의 솜씨라고! 2단계 터빈 날개도 준비해 놓지 않았다니...', `MaleText_loc4`='瞧瞧这个——简直太业余了！甚至连二级涡轮叶片都没有。', `MaleText_loc5`='看看這個，完全是業餘的程度!連一片第二階的渦輪葉片都沒有。', `MaleText_loc7`='¡Mira esto! ¡Menuda chapuza! Ni siquiera tiene una hoja de turbina de segunda fase.' WHERE `ID`=67463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이잇! 우리 할머니도 이것보다는 더 안정적인 가열기를 만들 수 있을 걸세. 아니, 정말로 만드셨었지!', `MaleText_loc4`='对！我奶奶能造出比这个可靠复杂十倍的东西。而且她做到了！', `MaleText_loc5`='耶!連我的老祖母都可以做出一個比這還要可靠的歧管。而她確實做過!', `MaleText_loc7`='¡Pero bueno! Hasta mi abuela podría fabricar un colector más decente que este. ¡Y los fabrica, de hecho!' WHERE `ID`=67464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려 보게. 곧 끝내주는 파괴 기계를 완성할 테니까.', `MaleText_loc4`='等着瞧吧，伙计们。我们马上就能拥有一台完美的杀人机器了。', `MaleText_loc5`='等著瞧吧，姑娘們。我們很快就會有一台很棒的殺人機器了。', `MaleText_loc7`='Ya veran, muchachos. Tendremos una máquina de matar pronto.' WHERE `ID`=67465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저거 혹시... 나무 막대기로 구동축을 만들어 넣은 거야? 대체 누가 이딴 짓을 한대?!', `MaleText_loc4`='那是……樱桃木传动轴吗？是谁做的？！', `MaleText_loc5`='那是...一根櫻桃木的驅動軸嗎?有誰會這麼做啊?!', `MaleText_loc7`='Eso... ¿eso es una palanca de cambios de madera de cerezo? ¡¿A quién se le ocurre?!' WHERE `ID`=67466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2단계 갈퀴 고정은 끝났고... 이제 3단계를 고정해 볼까...', `MaleText_loc4`='二层已固定。现在加固第三层……', `MaleText_loc5`='第二層抓鉤完成。現在得把第三層的鎖緊...', `MaleText_loc7`='Acoplamiento de nivel dos terminado. Ahora a por el nivel tres...' WHERE `ID`=67467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 저희 아버지가 관리하시던 소박한 마을이었습니다. 어떤 이들은 농작물을 키우고, 다른 이들은 맥주를 빚었지요. 1년에 한 번씩, 우리는 다른 마을로 장사를 하러 갔습니다. 우리 모두 즐겁게 살았습니다.$B$B이제 주위에는 온통 전쟁의 북소리만 울리고 있습니다. 이 험난한 세월을 조심스럽게 헤쳐가야 합니다. 어서 빨리 해결책을 찾았으면 하는 생각뿐입니다.', `MaleText_loc4`='这原本是一座由我爸爸负责治理的小村庄。我们农时耕种，闲时酿酒。我们每年都会造访其它村子一次，与那里的村民们互通有无。这种生活让我们感到怡然自得。$B$B现在，战斗的回音响彻四野，我们必须小心谨慎地度过眼下这个混乱时期。我只希望问题能尽快得到解决。', `MaleText_loc5`='這村子對我父親來說很容易管理。我們的生活除了種植作物，就是釀酒。我們一年會到其他村子進行交易一次。我們都很喜歡那樣的生活。$B$B如今，戰鼓的聲音迴盪在我們四周，而我們必須小心謹慎地度過這困難的時期。我只希望我們能快點找到解決的方法。', `MaleText_loc7`='Para mi padre, supervisar esta aldea era muy sencillo. Unos días cultivábamos, otros días fabricábamos cerveza... Una vez al año, viajábamos a otras aldeas para comerciar. Todos disfrutábamos de esa vida.$b$bPero ahora, los ecos de la guerra nos rodean y debemos vivir este conflicto con precaución. Espero que se resuelva pronto.' WHERE `ID`=67468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 자네를 믿지 않네, $r.', `MaleText_loc4`='我不信任你，$r。', `MaleText_loc5`='我不信任你，$r。', `MaleText_loc7`='No confío en ti, $r.' WHERE `ID`=67469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 참 많은 걸 봤지만, 자네처럼 이상한 생물은 이번이 처음이군.', `MaleText_loc4`='我这一生见多识广，可从没遇见过像你这么奇怪的生物。', `MaleText_loc5`='我一輩子裡看過許多事物，但我從來沒見過像你一樣奇怪的生物。', `MaleText_loc7`='He visto muchas cosas a lo largo de mi vida, pero nunca había visto una criatura tan extraña como tú.' WHERE `ID`=67470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들은 다른 이들의 고향을 찾아왔을 때도 예의라는 걸 차릴 줄을 모르는군.', `MaleText_loc4`='你们这些人总是喜欢不请自来。', `MaleText_loc5`='你的族人到別人家中做的事還真有趣。', `MaleText_loc7`='Tu gente tiene una forma muy peculiar de entrar en las casas de otras personas.' WHERE `ID`=67471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 제 조교들과 겨루어 실력을 증명하십시오. 그들을 꺾으면 직접 상대해 드리지요.', `MaleText_loc4`='你必须先跟我的助手过招来证明自己。只有打败他们，你才能面对我。', `MaleText_loc5`='首先你必須先對抗我的助手以證明你自己。打敗他們，然後你就能面對我。', `MaleText_loc7`='Primero debes ponerte a prueba contra mis ayudantes. Luego podrás enfrentarte a mí.' WHERE `ID`=67472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안전하다. 계속 가자.', `FemaleText_loc4`='好了。继续前进。', `FemaleText_loc5`='我們安全了。讓我們繼續趕路吧。', `FemaleText_loc7`='Ya está. Sigamos avanzando.' WHERE `ID`=67473;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 가까이 갈 수가 없어. 여기서 조사를 해 봐!', `FemaleText_loc4`='最多只能走到这里了。看看你能找到什么！', `FemaleText_loc5`='我們無法再更靠近了。看看你們能找到些什麼!', `FemaleText_loc7`='No vamos a poder acercarnos más. ¡A ver qué puedes averiguar!' WHERE `ID`=67474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 놈이 호박을 쳐다보는 게 마음에 안 드는군...', `MaleText_loc4`='我不喜欢它看南瓜的眼神……', `MaleText_loc5`='我不喜歡牠看著南瓜的眼神...', `MaleText_loc7`='No me gusta su forma de mirar las calabazas...' WHERE `ID`=67475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 화가 잔뜩 난 토끼 같잖아... 덩치랑 이빨이 더 큰 걸 빼면.', `MaleText_loc4`='它就像是一只愤怒的兔子……体型更大……更咬牙切齿。', `MaleText_loc5`='牠就像隻生氣的兔子...只不過大了點...牙齒尖了點。', `MaleText_loc7`='Es como un conejo enfadado... solo que más grande... y con más dientes.' WHERE `ID`=67476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 왕자님을 위해 중요한 임무를 수행 중이에요.$b$b"반드시 숙지해야 하는" 임무죠. 하지만 당신은 알 필요 없어요!', `MaleText_loc4`='我在为陛下执行重要任务。$b$b“探听消息”的重要任务。而这与你无关！', `MaleText_loc5`='我正在執行大人的重要命令。$B$B只有「相關人等」才有權過問。而你不是相關人等!', `MaleText_loc7`='Estoy al servicio de su majestad.$b$bSolo lo sabe gente importante. ¡Y tú no eres importante!' WHERE `ID`=67477;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='애완동물이 제게 말을 걸었어요. 늦은 밤이면 제게 이야기를 해준답니다.', `FemaleText_loc4`='我的宠物们会跟我说话。还会在夜晚给我讲故事。', `FemaleText_loc5`='我的寵物會和我說話。牠們在深夜會對我說故事。', `FemaleText_loc7`='Mis mascotas me hablan. Me cuentan historias por la noche.' WHERE `ID`=67478;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말도 안 되잖아. 다시 확인해 봐.', `FemaleText_loc4`='那说不通。再好好检查一下。', `FemaleText_loc5`='那一點都說不通。再檢查一次你的工作結果。', `FemaleText_loc7`='Eso no tiene sentido. Vuelve a revisar tu trabajo.' WHERE `ID`=67479;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저랑 싸우면 좀 많이 다칠 겁니다.', `FemaleText_loc4`='你将长久牢记这场战斗。', `FemaleText_loc5`='這場戰鬥會讓你痛很久。', `FemaleText_loc7`='Eh''te combate te va a doler mucho tiempo.' WHERE `ID`=67480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 이상하군. 물에 마법이 걸렸다고는 못 하겠는데, 희미한 기운이 남아 있어.', `MaleText_loc4`='真是太诡异了。我不认为这水流被施了某种魔法，可却存在着一股微弱的残余能量。', `MaleText_loc5`='還真是奇怪。我不認為這些水被施過法術，但一股不明顯的能量遺留下來。', `MaleText_loc7`='Qué curioso. No diría que estas aguas estén encantadas, pero hay una ligera energía residual.' WHERE `ID`=67481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숄라자르 분지에서 느꼈던 것과 비슷한데.', `MaleText_loc4`='我在索拉查盆地见过类似的东西。', `MaleText_loc5`='這種形態和我曾經在休拉薩盆地記錄過的很類似。', `MaleText_loc7`='Es un patrón similar a uno que descubrí en la Cuenca de Sholazar.' WHERE `ID`=67482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...확실히 여긴 뭔가 있어. 돌아가기 전에 이 지역에서 자라는 거대 채소를 몇 개 모으는 게 어때?', `MaleText_loc4`='……这里肯定有些不对劲。在我们回去之前，也许应该采集一些他们在这里种植的大个蔬菜？', `MaleText_loc5`='...這裡絕對有古怪。在我們回去之前，或許我們應該收集一些他們在這地區種植的巨大蔬菜。', `MaleText_loc7`='... Aquí pasa algo. Antes de volver, a lo mejor deberíamos reunir algunas de las verduras enormes que crecen por aquí...' WHERE `ID`=67483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!!', `MaleText_loc7`='¡¡POR LA HORDA!!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落!!', `FemaleText_loc7`='¡¡POR LA HORDA!!' WHERE `ID`=67484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 아니면 죽음을!', `MaleText_loc4`='非胜即死！', `MaleText_loc5`='不勝則亡!', `MaleText_loc7`='¡Victoria o muerte!', `FemaleText_loc1`='승리가 아니면 죽음을!', `FemaleText_loc4`='非胜即死！', `FemaleText_loc5`='不勝則亡!', `FemaleText_loc7`='¡Victoria o muerte!' WHERE `ID`=67485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님을 위하여!', `MaleText_loc4`='为了酋长！', `MaleText_loc5`='為了大酋長!', `MaleText_loc7`='¡Por el Jefe de Guerra!', `FemaleText_loc1`='대족장님을 위하여!', `FemaleText_loc4`='为了酋长！', `FemaleText_loc5`='為了大酋長!', `FemaleText_loc7`='¡Por el Jefe de Guerra!' WHERE `ID`=67486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악!', `MaleText_loc4`='嗷！', `MaleText_loc5`='噢!', `MaleText_loc7`='¡AY!' WHERE `ID`=67487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미쳤구나! 너, 미쳤어!', `MaleText_loc4`='你疯了！女孩，你疯了！', `MaleText_loc5`='你瘋了!女孩，你瘋了!', `MaleText_loc7`='¡Estás loca! Tía, ¡ESTÁS LOCA!' WHERE `ID`=67488;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분께선 새 세상을 만드시려는 거지, 샐러드를 만드시려는 게 아니야.', `FemaleText_loc4`='他在为我们创造一个新世界。他不是在……拌色拉！', `FemaleText_loc5`='他正在為了我們創造一個新世界。他不是...在做沙拉!', `FemaleText_loc7`='Está creando un mundo nuevo para nosotros. No está... ¡haciendo una ensalada!' WHERE `ID`=67489;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수련할 때는 집중해야 합니다! 다시 해 보십시오!', `FemaleText_loc4`='你必须把精神集中在训练上！再试一次！', `FemaleText_loc5`='你必須專注在你的訓練上!再試一次!', `FemaleText_loc7`='¡Concéntrate en tu entrenamiento! ¡Vuelve a intentarlo!' WHERE `ID`=67490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 조사하고 저 생물들을 처리하는 모습을 봤어요. 솜씨가 아주 좋으시던데요? 그래, 뭐 찾아낸 게 있나요?', `MaleText_loc4`='我看见你在底下调查船只，对付那些生物。干得好。有什么发现吗？', `MaleText_loc5`='我看著你調查那艘船和處理那邊的生物。做得很好。你有發現任何蛛絲馬跡嗎?', `MaleText_loc7`='Te he visto investigar el barco y encargarte de esas criaturas. Buen trabajo. ¿Has encontrado algo?' WHERE `ID`=67491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니요.', `MaleText_loc4`='不。', `MaleText_loc5`='不。', `MaleText_loc7`='No.', `FemaleText_loc1`='아니요.', `FemaleText_loc4`='不。', `FemaleText_loc5`='不。', `FemaleText_loc7`='No.' WHERE `ID`=67492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문은 할 겁니까?', `MaleText_loc4`='你们俩要不要来点儿什么？', `MaleText_loc5`='你們兩個有要點什麼東西嗎?', `MaleText_loc7`='¿Vais a pedir algo?', `FemaleText_loc1`='주문은 할 건가요?', `FemaleText_loc4`='你们俩要不要来点儿什么？', `FemaleText_loc5`='你們兩個有要點什麼東西嗎?', `FemaleText_loc7`='¿Vais a pedir algo?' WHERE `ID`=67493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 "영웅" 나리군. 비행포격선 없이 어떻게 싸우는지 한번 볼까!', `MaleText_loc4`='联盟的“英雄”。我倒要看看没有飞艇掩护，你还怎么战斗！', `MaleText_loc5`='聯盟的「英雄」。我們來看看沒有飛行戰艦保護你，你還能怎麼打!', `MaleText_loc7`='"Orgullo" de la Alianza. ¡A ver cómo luchas sin una nave que te cubra las espaldas!' WHERE `ID`=67494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 뭔가 다르다... 넌 이해하지 못해...', `MaleText_loc4`='这片土地蕴藏着——你不了解的玄机——', `MaleText_loc5`='這片土地有些東西...你無法了解...', `MaleText_loc7`='Esta tierra tiene algo... que no comprendes...' WHERE `ID`=67495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 우리 뜻을 거역했다. 헬스크림 님의 호드를... 마을 전체를 처형했어야 하는데!', `MaleText_loc4`='他们竟敢违抗我们——违抗地狱咆哮的部落——我当时真应该赶尽杀绝！', `MaleText_loc5`='他們拒絕我們...拒絕地獄吼的部落...我該把整座小鎮都殺光才對!', `MaleText_loc7`='Nos desafiaron... Desafiaron a la Horda de Grito Infernal... ¡Debería haber ejecutado a toda la aldea!' WHERE `ID`=67496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 쓰레기! 불타 버려라!', `MaleText_loc4`='燃烧吧，联盟渣滓！燃烧！', `MaleText_loc5`='燒吧，聯盟的混帳，燒吧!', `MaleText_loc7`='¡Arde, escoria de la Alianza! ¡ARDE!' WHERE `ID`=67497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅이 네 무덤이 될 것이다.', `MaleText_loc4`='这片土地将是你葬身之地。', `MaleText_loc5`='你將葬身在這片土地上。', `MaleText_loc7`='Esta tierra será tu tumba.' WHERE `ID`=67498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니 후려치라고! 후려치라고 했잖아!', `MaleText_loc4`='不！猛砸！我说猛砸！', `MaleText_loc5`='不!打扁!我說了打扁!', `MaleText_loc7`='¡No! ¡Machaca! ¡He dicho "Machaca"!' WHERE `ID`=67499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선생님은 제가 제일 좋아하는 선생님이에요!', `MaleText_loc4`='你是我最好的老师！', `MaleText_loc5`='你是我最喜歡的老師了!', `MaleText_loc7`='¡Eres mi profesor favorito!', `FemaleText_loc1`='선생님은 제가 제일 좋아하는 선생님이에요!', `FemaleText_loc4`='你是我最好的老师！', `FemaleText_loc5`='你是我最喜歡的老師了!', `FemaleText_loc7`='¡Eres mi profesor favorito!' WHERE `ID`=67500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 술이 있습니까?', `MaleText_loc4`='你这里有什么美酒？', `MaleText_loc5`='你有賣些什麼酒?', `MaleText_loc7`='¿Qué bebidas tienes a la venta?', `FemaleText_loc1`='어떤 술이 있나요?', `FemaleText_loc4`='你这里有什么美酒？', `FemaleText_loc5`='你有賣些什麼酒?', `FemaleText_loc7`='¿Qué bebidas tienes a la venta?' WHERE `ID`=67501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 저는 좋은 술을 팔고 있습니다. 관심만 있다면 직접 만드는 법을 가르쳐 드릴 수도 있지요.', `MaleText_loc4`='你好啊，$n。我为你精心挑选了几种美酒。要是你有兴趣，我还愿意把酿造的本领传授给你。', `MaleText_loc5`='你好，$n。我有許多精選過的酒。如果你有興趣，我也可以教你如何自己釀造。', `MaleText_loc7`='Hola, $n. Tengo una amplia selección de bebidas a tu disposición. Si te interesa, también puedo enseñarte a prepararlas por tu cuenta.' WHERE `ID`=67502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제독! 괜찮아 보이니 다행이군.', `FemaleText_loc4`='上将！看见你平安真是太好了。', `FemaleText_loc5`='上將!很高興看到你沒事。', `FemaleText_loc7`='¡Almirante! Me alegra ver que estés bien.' WHERE `ID`=67503;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안하지만 우리 부대는 돌아가야 하오.', `FemaleText_loc4`='恐怕你得独自向前推进了。', `FemaleText_loc5`='恐怕你得自己單獨往前推進了。', `FemaleText_loc7`='Me temo que tendrán que avanzar sin nosotros.' WHERE `ID`=67504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='본진으로 돌아와 호위 임무를 맡으라는 지시를 받았소. 해군 본대가 두 달 뒤엔 도착할 것이오.', `FemaleText_loc4`='我要奉命返回主战队，执行母舰护航任务。联盟海军的全部兵力将在两个月后抵达。', `FemaleText_loc5`='我收到回去主艦群提供護送運輸艦的命令。聯盟海軍的完整戰力會在兩個月內抵達南邊的海岸。', `FemaleText_loc7`='Tengo órdenes de volver a la formación de batalla principal para proporcionar apoyo. Toda la marina de la Alianza llegará en dos meses.' WHERE `ID`=67505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='약한 소리 하지 마시오, 제독. 첩보 요원들을 남겨두겠소. 정찰 임무부터 시작하시오.', `FemaleText_loc4`='别耍小孩子脾气，泰勒。军情七处的军官们会留下帮你。我建议先做一番侦查。', `FemaleText_loc5`='別耍小孩子脾氣了，泰勒。我會把軍情七處的軍官留下來。我建議先進行偵查任務。', `FemaleText_loc7`='Hora de fajarse los pantalones, Taylor. Te dejaré a los agentes del IV:7. Sugiero una misión de exploración.' WHERE `ID`=67506;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원주민들과 연합하는 것도 좋겠지. 이곳은 당신에게 맡기겠소.', `FemaleText_loc4`='你或许可以招募些当地人。你很能干，这里就交给你了。', `FemaleText_loc5`='也許你可以招募一些當地人。你有這個能力視情況決定。', `FemaleText_loc7`='Quizás puedas reclutar a algún nativo. Dejaré la situación en tus eficientes manos.' WHERE `ID`=67507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다. 와주셔서 다행입니다. 포격선의 지원을 받는다면, 북쪽으로의 진격이...', `MaleText_loc4`='谢谢，凯瑟琳。你来得正好，在母舰的全力支持下我们就能向北推进——', `MaleText_loc5`='謝謝你，凱薩琳。很高興妳來了。有了完全的運輸艦支援我們可以往北...', `MaleText_loc7`='Gracias, Catherine. Me alegro de que estés aquí. Con tu apoyo podremos avanzar hacia el norte...' WHERE `ID`=67508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐요?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=67509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그때까지 뭘 하라는 겁니까? 병사도 없습니다! 호드가 어디 있는지도, 그 숫자도 모르잖습니까!', `MaleText_loc4`='那我怎么办？我没有人手！我们不知道部落在哪儿，也不知道要对付多少敌人！', `MaleText_loc5`='在那之前要我幹嘛?我沒有手下!我們不知道部落在哪裡，甚至不知道他們有多少人!', `MaleText_loc7`='¿Y qué quieren que haga hasta entonces? ¡No tengo soldados! ¡No sabemos dónde está la Horda, ni cuántos efectivos tiene!' WHERE `ID`=67510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 제독님.', `MaleText_loc4`='遵命，上将。', `MaleText_loc5`='遵命，上將。', `MaleText_loc7`='Sí, Almirante.' WHERE `ID`=67511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무운을 빕니다.', `MaleText_loc4`='祝你成功。', `MaleText_loc5`='一路順風。', `MaleText_loc7`='Buen viaje.' WHERE `ID`=67512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"임기응변"이라고. 흥.', `MaleText_loc4`='“大展拳脚。”哼。', `MaleText_loc5`='「隨機應變」。哼。', `MaleText_loc7`='Improvisa. hmm...' WHERE `ID`=67513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='렐, 병사들과 함께 정찰을 떠나시오. 호드 세력을 확인하고, 안두인 왕자님을 찾아내시오!', `MaleText_loc4`='夜风，带着你的人往内陆地区搜查。探测部落的踪迹，找到安度因王子。', `MaleText_loc5`='夜風，帶你的人偵查內部。可能有部落的人。順便找安度因王子!', `MaleText_loc7`='Brisa Nocturna, toma a tus hombres y explora el interior. Busca a la Horda. ¡Y encuentra al príncipe Anduin!' WHERE `ID`=67514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 뱀 같으니! 불을 쏘라고 했잖아!', `MaleText_loc4`='蠢蛇。我说开火！', `MaleText_loc5`='蠢蛇。我說了噴火!', `MaleText_loc7`='Estúpida serpiente. ¡Yo decir disparar fuego!' WHERE `ID`=67515;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 대지는 인내심이 정말 많습니다. 그리고 세계파괴자의 깨어남 속에서도 인내심이 계속 자나라고 있지요. 제 애완동물에서도 그것과 비슷한 인내심을 보게 될 것입니다.', `FemaleText_loc4`='这片土地饱经风霜，灭世者败亡后，它再次焕发了生机。你会发现，我的宠物们也具备类似的坚毅品格。', `FemaleText_loc5`='這片土地承受過許多風霜，但它在碎界者的影響之下依然生氣蓬勃，而我的寵物們也擁有同樣的韌性。', `FemaleText_loc7`='Esta tierra ha sufrido mucho, pero sigue adelante tras la irrupción del Rompemundos. Verás que mis mascotas son igual de resistentes.' WHERE `ID`=67516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단단히 준비하게, $n.$b$b머지않아 적과 마주하게 될 테니까.', `MaleText_loc4`='做好准备，$n。$b$b我们即将进入危机四伏的环境！', `MaleText_loc5`='準備好，$n。$b$b我們很快就會進入一個滿是目標的地方了。', `MaleText_loc7`='Prepárate, $n.$b$b¡Vamos a entrar en un campo lleno de objetivos!' WHERE `ID`=67517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출발할 준비가 됐습니다, 장군님.', `MaleText_loc4`='我准备好出发了，将军。', `MaleText_loc5`='我準備好出發了，將軍。', `MaleText_loc7`='Estoy listo, General.', `FemaleText_loc1`='출발할 준비가 됐어요, 장군님.', `FemaleText_loc4`='我准备好出发了，将军。', `FemaleText_loc5`='我準備好出發了，將軍。', `FemaleText_loc7`='Estoy lista, General.' WHERE `ID`=67518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우, 진짜 아프잖아. 농담이지롱.', `MaleText_loc4`='哎呦。那可真疼。才没有呢。', `MaleText_loc5`='噢。那很痛耶。才怪。', `MaleText_loc7`='¿Y se supone que eso me iba a hacer daño?', `FemaleText_loc1`='아우, 진짜 아프잖아. 농담이지롱.', `FemaleText_loc4`='哎呦。那可真疼。才没有呢。', `FemaleText_loc5`='噢。那很痛耶。才怪。', `FemaleText_loc7`='¿Y se supone que eso me iba a hacer daño?' WHERE `ID`=67519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 커다랗고 나쁜 모구 님. 너무 무서워요.', `MaleText_loc4`='噢。邪恶的大魔古。我好怕呦。', `MaleText_loc5`='喔喔。大壞蛋魔古先生。我好怕喔。', `MaleText_loc7`='Ooooh, un mogu grande y malo, qué miedo me das.', `FemaleText_loc1`='아아, 커다랗고 나쁜 모구 님. 너무 무서워요.', `FemaleText_loc4`='噢。邪恶的大魔古。我好怕呦。', `FemaleText_loc5`='喔喔。大壞蛋魔古先生。我好怕喔。', `FemaleText_loc7`='Ooooh, un mogu grande y malo, qué miedo me das.' WHERE `ID`=67520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 한번 덤벼 봐.', `MaleText_loc4`='来吧，蠢货。', `MaleText_loc5`='放馬過來，渾蛋。', `MaleText_loc7`='Haz lo que puedas, feo.', `FemaleText_loc1`='어디 한번 덤벼 봐.', `FemaleText_loc4`='来吧，蠢货。', `FemaleText_loc5`='放馬過來，渾蛋。', `FemaleText_loc7`='Haz lo que puedas, feo.' WHERE `ID`=67521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한판 붙어 볼래?', `MaleText_loc4`='你想干掉我？', `MaleText_loc5`='你想要和我打一場嗎?', `MaleText_loc7`='¿Te estás metiendo conmigo?', `FemaleText_loc1`='한판 붙어 볼래?', `FemaleText_loc4`='你想干掉我？', `FemaleText_loc5`='你想要和我打一場嗎?', `FemaleText_loc7`='¿Te estás metiendo conmigo?' WHERE `ID`=67522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 여기 있어서 천만다행이네요, $n 님. 뭔가 단단히 잘못됐어요. 그리고 우리의 지도자가 모두를 닥치는 대로 죽이고 있어요!', `FemaleText_loc4`='感谢圣光，你终于来了，$n。这里出了大问题，我们的头领正在大肆屠杀！', `FemaleText_loc5`='感謝聖光你在這，$n。不知出了什麼大差錯，我們的首領正在屠殺所有人!', `FemaleText_loc7`='Gracias a la Luz que has venido, $n. Ha pasado algo terrible. ¡Nuestro líder está matando a todo el mundo!' WHERE `ID`=67523;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 서둘러주세요! 저는 여기 남아서 부상자를 돌봐야 해요.', `FemaleText_loc4`='请抓紧时间！我必须留下照顾伤患。', `FemaleText_loc5`='拜託快點!我必須留下來照顧傷者。', `FemaleText_loc7`='¡Date prisa! Yo tengo que quedarme a cuidar de los heridos.' WHERE `ID`=67524;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 고마워요!$B$B이 지역의 대지 정령인 후이는 자기가 부리는 말썽꾸러기 요마를 쫓아내려고 우리가 모험가를 고용했더니 화가 잔뜩 났어요.$B$B화가 난 건 이해할 수 있지만, 이런 공격은 정말 너무한 거잖아요!', `FemaleText_loc4`='非常感谢！$B$B由于我们雇用冒险者帮忙驱赶那些淘气的精灵，土灵仇灰为此大发雷霆。$B$B我能理解他的烦乱，可这攻击也太过分了！', `FemaleText_loc5`='非常感謝!$B$B這裡的土靈穢對我們雇來冒險者趕走他淘氣的妖精們感到非常憤怒。$B$B我可以理解他的不滿，但這樣的攻擊實在太過分了!', `FemaleText_loc7`='¡Muchas gracias!$b$bEl espíritu de la tierra de esta región, Hui, se ha enfadado porque contratamos a aventureros para que echaran a sus duendes traviesos.$b$bEntiendo que esté molesto, ¡pero este ataque se pasa de la raya!' WHERE `ID`=67526;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 고마워요!', `FemaleText_loc4`='非常感谢！', `FemaleText_loc5`='非常感謝!', `FemaleText_loc7`='¡Muchas gracias!' WHERE `ID`=67527;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 지역의 대지 정령인 후이는 자기가 부리는 말썽꾸러기 요마를 쫓아내려고 우리가 모험가를 고용했더니 화가 잔뜩 났어요.', `FemaleText_loc4`='由于我们雇用冒险者帮忙驱赶那些淘气的精灵，土灵仇灰为此大发雷霆。', `FemaleText_loc5`='這裡的土靈穢對我們雇來冒險者趕走他淘氣的妖精們感到非常憤怒。', `FemaleText_loc7`='El espíritu de la tierra de esta región, Hui, se ha enfadado porque contratamos a aventureros para que echaran a sus duendes traviesos.' WHERE `ID`=67528;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='화가 난 건 이해할 수 있지만, 이런 공격은 정말 너무한 거잖아요!', `FemaleText_loc4`='我能理解他的烦乱，可这攻击也太过分了！', `FemaleText_loc5`='我可以理解他的不滿，但這樣的攻擊實在太過分了!', `FemaleText_loc7`='Entiendo que esté molesto, ¡pero este ataque se pasa de la raya!' WHERE `ID`=67529;
