UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐든지 서투른 이 친구와 지내다 보니, 부상 치료에 대해서는 좀 알게 됐습니다. 당신에게 기술을 전수해 드릴까요?', `MaleText_loc4`='我跟那个笨手笨脚的家伙共处过很长时间了，也学会了一两招疗伤的本领。也许我能把它们传授给你？', `MaleText_loc5`='我已經花夠多的時間在這笨拙的XX身上，且對治療傷勢略知一二。也許我能教給你些什麼?', `MaleText_loc7`='Llevo tanto tiempo al lado de XX que he aprendido un par de trucos sobre el tratamiento de las heridas. Igual puedo enseñarte alguno.' WHERE `ID`=67577;
