UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 큰 놈인 것 같아...', `MaleText_loc4`='哇，我想我逮到了一条大鱼……', `MaleText_loc5`='嘩，我想我抓到一條大的了...', `MaleText_loc7`='¡Ah! Creo que me ha tocado uno grande...' WHERE `ID`=67600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 생각보다 더 큰 놈이었던 모양이군...', `MaleText_loc4`='哎呦！看来那家伙比我想的还要大……', `MaleText_loc5`='噢!那大概比我想的還要大了一點點...', `MaleText_loc7`='Vaya... Creo que ese era un poco más grande de lo que esperaba.' WHERE `ID`=67601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 나와 한잔할 시간이 되나?', `MaleText_loc4`='你有时间吗？', `MaleText_loc5`='你有一些空閒的時間嗎?', `MaleText_loc7`='¿Tienes un momento?' WHERE `ID`=67602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 괜찮습니다.', `MaleText_loc4`='我已经准备好了。', `MaleText_loc5`='我已經準備好陪你喝杯酒了。', `MaleText_loc7`='Ya estoy listo para ese trago.', `FemaleText_loc1`='네, 괜찮아요.', `FemaleText_loc4`='我已经准备好了。', `FemaleText_loc5`='我已經準備好陪你喝杯酒了。', `FemaleText_loc7`='Ya estoy lista para ese trago.' WHERE `ID`=67603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 음영파와 동행하며 장벽 너머에서 그들이 세우는 공을 기록한다네. 쉬운 일은 아니지. 난전 와중에 내 일지를 잃어버리고 싶진 않거든!$b$b전에도 일지를 잃어버린 전승지기가 많네. 전승지기는 오랜 세월 동안 판다렌 역사를 기록해 왔다네. 그들의 기록이 판다리아 전역에 흩어져 있지. 자네가 그 기록을 모아 준다면 전승지기들이 매우 고마워할 걸세!', `MaleText_loc4`='我跟随影踪派，将他们在长城另一侧的诸多事迹如实记录下来——我可不想在这混战中弄丢任何宝贵的手札！$b$b这并非没有先例。游学者们世代以来始终在编纂着熊猫人的历史。在潘达利亚各地都散落着他们的笔记。要是你能收集到这些史料，一定能得到游学者们的赏识！', `MaleText_loc5`='我伴隨著影潘記錄他們在長城外的許多事蹟。那不是件易事，我可不想要在戰鬥的混亂中遺失任何一篇日誌!$b$b以前就發生過這種事。博學行者們長久以來一直記錄著熊貓人的歷史。他們的筆記散落在整個潘達利亞。我確信如果你能將它們匯集起來，博學行者們一定會非常感激你。', `MaleText_loc7`='Acompaño al Shadopan para registrar sus muchas hazañas al otro lado de la muralla. No es fácil; ¡no quiero perder ninguno de mis diarios en el caos de la batalla!$b$bNo sería la primera vez. Los eremitas llevan siglos catalogando la historia de los pandaren. Sus notas estás desperdigadas por toda Pandaria. Estoy seguro de que los eremitas te lo agradecerían si las recopilaras.' WHERE `ID`=67604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와, 큰 놈이군요! 아파 보였어요!', `MaleText_loc4`='哇哦，那是个大家伙，看起来很难对付！', `MaleText_loc5`='哇喔，那還真大，看起來很痛的!', `MaleText_loc7`='¡Guau, ese era grande! ¡Tiene que haber dolido!' WHERE `ID`=67605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이의 길은 춥고 위험하고 혹독하다오. 하지만 쉽게 이루어지는 거래는 보람도 없고 돈도 안 되지.', `MaleText_loc4`='通往昆莱山的道路寒冷险峻，危机四伏。可不入虎穴，焉得虎子——轻易达成的交易哪有什么油水可捞！', `MaleText_loc5`='崑萊的道路寒冷且危險，一失足就可能沒命。但你還是可以從中得到一點滿足感-或是利潤!因為交易很容易談定。', `MaleText_loc7`='Los caminos de Kun-Lai son fríos, peligrosos y despiadados. Pero los tratos fáciles de cumplir ofrecen poca satisfacción... ¡y poco beneficio!' WHERE `ID`=67606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날개는 우리에게 날아오를 수 있는 자유를 준답니다.', `FemaleText_loc4`='翅膀给了我们高飞的自由。', `FemaleText_loc5`='翅膀讓我們可以自由地翱翔。', `FemaleText_loc7`='Las alas nos dan la libertad de volar.' WHERE `ID`=67608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도대체 누가 기계는 자연스럽지 못하다고 그래요? 제 애완동물들은 그래도 50% 정도는 자연스럽다고요!', `FemaleText_loc4`='谁说机器不是天然的？！我的宠物至少是50%纯天然！', `FemaleText_loc5`='誰說機器就不自然?我的寵物們至少有50%是自然的!', `FemaleText_loc7`='¿Quién dice que las máquinas no son naturales? ¡Mis mascotas son naturales al menos al 50%!' WHERE `ID`=67609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 지금 정신을 집중하고 있네... 가서 다른 사람이나 괴롭히지 그러나?', `MaleText_loc4`='我正在集中精神……你能不能去烦别人？', `MaleText_loc5`='我想要專心...你可以去煩別人嗎?', `MaleText_loc7`='Me estoy concentrando... ¿Te importa molestar a otra persona?' WHERE `ID`=67610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오닉시아가 자기 알을 낳던 곳에 이것들을 그냥 놓아뒀다는 게 믿겨져? 나는 부자가 될 거야!', `MaleText_loc4`='你能相信吗，奥妮克希亚竟然任由这些留在她的巢穴里？我要发大财了！', `MaleText_loc5`='你能相信奧妮克希亞把這些東西就這樣留在她的蛋坑中嗎?我要發大財了!', `MaleText_loc7`='¿Te puedes creer que Onyxia dejó estos huevos tirados en su guarida? ¡Me voy a hacer rico!' WHERE `ID`=67611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오닉시아의 알둥지에서 혼쭐이 나보지 않았다면 진짜 모험을 한 게 아니지!', `MaleText_loc4`='要是你没到过奥妮克希亚的巢穴，就不算是真正冒险过！', `MaleText_loc5`='你得從奧妮克希亞的幼龍坑上跳過，才算是真正的冒險過。', `MaleText_loc7`='¡No has conocido la aventura de verdad hasta que has atravesado la guarida de las crías de Onyxia!' WHERE `ID`=67612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 습지대에서 나는 냄새는 오닉시아의 입냄새 만큼이나 지독하군!', `MaleText_loc4`='外边的沼泽散发着一股奥妮克希亚的口臭味！', `MaleText_loc5`='這裡的沼澤聞起來幾乎和奧妮克希亞的吐息一樣糟!', `MaleText_loc7`='Esta zona de la marisma apesta casi tanto como el aliento de Onyxia.' WHERE `ID`=67613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 천천히... 천천히 이겨주지.', `MaleText_loc4`='我会慢慢、慢慢地打你。', `MaleText_loc5`='我要很慢，很慢地揍扁你。', `MaleText_loc7`='Te voy a vencer muy, muy lentamente.' WHERE `ID`=67614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님께서 아제로스에 지옥불의 비를 내리시면, 마침내 우리는 이 비참한 세상에서 빛을 정화할 수 있을 것이오!', `MaleText_loc4`='主人会在艾泽拉斯降下地狱烈焰，然后我们就能让圣光从这恼人的世界上彻底消散！', `MaleText_loc5`='主人會在艾澤拉斯降下地獄之火，而我們終於可以淨化這可悲世界上的聖光。', `MaleText_loc7`='El Maestro provocará una lluvia de fuego infernal en Azeroth. ¡Por fin purgaremos la Luz de este mundo infecto!' WHERE `ID`=67615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대들 모두 주인님이 위대한 모습으로 되돌아오시도록 도와야 하오. 그분만이 궁극적으로 영원한 평화를 가져오실 수 있소!', `MaleText_loc4`='你们所有人都必须帮主人实现伟大的复活。只有凭借他的力量，我们才能迎来永久的安宁！', `MaleText_loc5`='你們所有人都必須工作，以協助我們的主人復活。唯有透過他，我們才能為所有人迎來永恆的和平!', `MaleText_loc7`='Todos deben colaborar en el gran renacimiento del Maestro. ¡Solo a través de Él podremos conseguir la paz eterna y universal!' WHERE `ID`=67616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 생의 보호자이신 우리 주인님께서는 곧 이단자들의 눈을 모두 멀게 하고, 우리에게 끝을 알 수 없는 힘을 주실 것이오!', `MaleText_loc4`='我们的主人——万物守护者，他的光芒将刺瞎异教徒的双眼，赋予我们无限的力量！', `MaleText_loc5`='我們的主人是所有生命的保護者，很快地他就會讓所有的異教徒盲目，並賦予我們不可計量的力量!', `MaleText_loc7`='Pronto nuestro Maestro, protector de toda vida, cegará a todos los herejes y nos otorgará un poder inconmensurable.' WHERE `ID`=67617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주인님의 선물을 받을 준비가 됐소? 그분의 정감 넘치는 분노의 축복을 받을 거요? 아니면 다른 이들과 같이 삼켜질 거요?', `MaleText_loc4`='你准备好接受主人的馈赠了吗？你将被他慈爱的怒火庇佑，还是会像其他人那样被吞噬殆尽？', `MaleText_loc5`='你準備好要接受主人的恩賜了嗎?你會被他慈愛的憤怒所祝福，還是像其他所有人一樣被吞噬呢?', `MaleText_loc7`='¿Están listos para aceptar el don del Maestro? ¿Su cólera bondadosa los bendecirá, o los consumirá como a todos los demás?' WHERE `ID`=67618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살게라스 님은 또다시 살아나시리라!', `MaleText_loc4`='萨格拉斯必将重生！', `MaleText_loc5`='薩格拉斯會再次重生!', `MaleText_loc7`='¡Sargeras volverá a la vida!' WHERE `ID`=67619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마는 이 세상의 미래라오. 이 사실을 빨리 인정할수록 그대도 승리자의 세상에 들어오는 것이오.', `MaleText_loc4`='恶魔是这个世界的未来。你越早接受这一点，就能越早加入胜利方。', `MaleText_loc5`='惡魔是這個世界的未來。你越快接受這個事實，你就能越快加入勝利的一方。', `MaleText_loc7`='Los demonios son el futuro de este mundo. Cuanto antes lo acepten, antes se incorporarán al equipo ganador.' WHERE `ID`=67620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼림도어는 그림토템의 것이랍니다. 아무도 우리를 막을 순 없어요.$B$B우리는 만물의 영장이에요. 제가 당신의 하찮은 애완동물들을 박살내는 것을 보게 될 거예요.', `MaleText_loc4`='卡利姆多属于恐怖图腾。没人能妨碍我们。$B$B我们是至高无上的，你马上就会亲眼看着我粉碎你那悲惨的队伍。', `MaleText_loc5`='卡林多是屬於恐怖圖騰的。沒有人可以妨礙我們。$B$B我們在各方面都是最卓越的，我現在就粉碎你可悲的隊伍讓你了解這一點。', `MaleText_loc7`='Kalimdor pertenece a los Tótem Siniestro. Nadie puede detenernos.$b$bPrevalecemos en todas las cosas, como comprobarás cuando aplaste a tu patético equipo.' WHERE `ID`=67621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 전투 애완동물 조련사인 것 같군요. 그림토템의 강대함에 맞서 당신의 능력을 시험해 보는 게 어떠세요?', `FemaleText_loc4`='我知道你是一位战斗宠物训练师，$r。不如施展本领，跟恐怖图腾较量一下？', `FemaleText_loc5`='我知道你是一個戰寵訓練師，$r。和一個恐怖圖騰對抗來測試你的技巧，你認為如何?', `FemaleText_loc7`='Veo que eres $gun entrenador:una entrenadora; de mascotas, $r. ¿Qué te parece poner a prueba tus habilidades contra el poder de una Tótem Siniestro?' WHERE `ID`=67622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 뱀 정말 예쁘죠? 안 그래요?', `FemaleText_loc4`='我的蛇很漂亮对吧？……对吧？', `FemaleText_loc5`='我的蛇很漂亮對吧?...對吧?', `FemaleText_loc7`='Mis serpientes son preciosas, ¿verdad? ¿VERDAD?' WHERE `ID`=67623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저랑 이 예쁜 뱀을 절대 이길 순 없을 거예요!', `FemaleText_loc4`='在我和我可爱的毒蛇面前，你毫无半点儿机会！', `FemaleText_loc5`='你根本就贏不了我和我可愛的蛇!', `FemaleText_loc7`='¡No tenías ninguna posibilidad contra mis hermosas serpientes y yo!' WHERE `ID`=67624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 다음 번에는 제가 이길 거예요!', `FemaleText_loc4`='不可能！你下次输定了！', `FemaleText_loc5`='不可能!我下次一定會贏你!', `FemaleText_loc7`='¡No puede ser! ¡La próxima vez te aplastaré!' WHERE `ID`=67625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 어떤가요!', `FemaleText_loc4`='换这家伙试试！', `FemaleText_loc5`='用這個傢伙來量量尺寸!', `FemaleText_loc7`='¡A ver qué tal te va con este!' WHERE `ID`=67626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 어때요!', `FemaleText_loc4`='受死吧！', `FemaleText_loc5`='看招!', `FemaleText_loc7`='¡Toma ya!' WHERE `ID`=67627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 내 소중한 뱀이!', `FemaleText_loc4`='不！我的宝贝蛇！', `FemaleText_loc5`='不!我寶貴的蛇啊!', `FemaleText_loc7`='¡Noooo! ¡Mis queridas serpientes!' WHERE `ID`=67628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='졌습니다.', `MaleText_loc4`='我败了。', `MaleText_loc5`='我打輸了。', `MaleText_loc7`='He perdido.' WHERE `ID`=67630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신을 못 차리게 해줄게요!', `FemaleText_loc4`='我要让你冷晕过去！', `FemaleText_loc5`='我會把你打得體無完膚!', `FemaleText_loc7`='¡Te voy a dar una paliza!' WHERE `ID`=67631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 뭐랬어요. 상대가 안 된다니까요?', `FemaleText_loc4`='我提醒过你了，宝贝儿。就你那点热量，还不足以对付我！', `FemaleText_loc5`='我告訴你，蜜糖。你對我來說還不夠嗆!', `FemaleText_loc7`='Ya te lo he dicho, cielo. ¡Te falta un hervor!' WHERE `ID`=67632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아야! 뭔가에 데였어!', `FemaleText_loc4`='哎呦！我被烧伤了！', `FemaleText_loc5`='噢!我剛剛被燒到了!', `FemaleText_loc7`='¡Ay! ¡Me he quemado!' WHERE `ID`=67633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 귀염둥이 잠깐 쉬렴. 곧 다시 네 차례가 올 거야.', `FemaleText_loc4`='歇会，降降温吧，宝贝儿。很快就又轮到你了。', `FemaleText_loc5`='休息冷靜一下，甜心。很快就會輪到你的。', `FemaleText_loc7`='No te acalores, cariño. Ya llegará tu turno.' WHERE `ID`=67634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='통제할 수 없는 상황이 점점 커지고 있다고요! 이젠 우릴 절대 못 이겨요!', `FemaleText_loc4`='雪球失控碾压！你现在没机会了！', `FemaleText_loc5`='我們丟雪球所向披靡!你一點機會都沒有!', `FemaleText_loc7`='¡Nos estamos enfadando! ¡Te vamos a dejar $ghelado:helada;!' WHERE `ID`=67635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='박살났네!', `FemaleText_loc4`='支离破碎！', `FemaleText_loc5`='粉碎!', `FemaleText_loc7`='¡Congelado!' WHERE `ID`=67636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 생각했던 것보다 더 차가운 분이시군요.', `FemaleText_loc4`='没想到你那么不怕冷。', `FemaleText_loc5`='你比我想的還耐寒。', `FemaleText_loc7`='Toleras el frío mejor de lo que esperaba.' WHERE `ID`=67637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 애완동물은 아주 냉정하고, 무자비하네요!', `FemaleText_loc4`='你的宠物是个冰冷无情的杀手！', `FemaleText_loc5`='你的寵物是個冷酷的殘忍殺手!', `FemaleText_loc7`='¡Tienes una mascota asesina, fría y despiadada!' WHERE `ID`=67638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 맘대로 다 하게 내버려두진 않을 거예요!', `FemaleText_loc4`='这事决不会就这么算了！', `FemaleText_loc5`='我不會讓你像那樣跑掉的!', `FemaleText_loc7`='¡No dejaré que te salgas con la tuya!' WHERE `ID`=67639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 제 상대가 못 돼요!', `FemaleText_loc4`='就凭你的热度还对付不了我！', `FemaleText_loc5`='你對我來說還不夠嗆!', `FemaleText_loc7`='¡Te falta un hervor!' WHERE `ID`=67640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 자기?', `FemaleText_loc4`='你好吗，宝贝儿？', `FemaleText_loc5`='你還好嗎，蜜糖?', `FemaleText_loc7`='¿Qué tal, cariño?' WHERE `ID`=67641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<츠지의 목소리가 마음속에 울립니다.>$b$b단상 위에 올라가는 데 도움이 필요한가, $n?', `MaleText_loc4`='<赤精的声音在你脑内回响。>$b$b你需要我帮你抵达台顶吗，$n？', `MaleText_loc5`='<赤吉的聲音在你的腦海中響起。>$b$b需要人幫忙送你到石臺上面去嗎，$n?', `MaleText_loc7`='<La voz de Chi-Ji ocupa tu mente.>$b$b¿Necesitas ayuda para subir al pedestal, $n?' WHERE `ID`=67642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부탁드리겠습니다, 츠지 님.', `MaleText_loc4`='是的，赤精。', `MaleText_loc5`='是的，拜託你，赤吉。', `MaleText_loc7`='Sí, Chi-Ji, por favor.', `FemaleText_loc1`='부탁드릴게요, 츠지 님.', `FemaleText_loc4`='是的，赤精。', `FemaleText_loc5`='是的，拜託你，赤吉。', `FemaleText_loc7`='Sí, Chi-Ji, por favor.' WHERE `ID`=67643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘을 향해!', `MaleText_loc4`='飞上高空！', `MaleText_loc5`='飛上天吧!', `MaleText_loc7`='¡Hasta el cielo!' WHERE `ID`=67644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<츠지의 목소리가 마음속에 울립니다.>$b$b전당 꼭대기에 올라가는 데 내 도움이 필요할 것 같구나.', `MaleText_loc4`='<赤精的声音在你脑内回响。>$b$b我感觉到你需要我帮你抵达台顶。', `MaleText_loc5`='<你能聽到赤吉的聲音在你的思緒中迴盪。>$b$b我查覺到你需要我的幫助到圓頂上面去。', `MaleText_loc7`='<Escuchas la voz de Chi-Ji resonar en tu mente.>$b$bPercibo que necesitas mi ayuda para subir a lo alto de la cúpula.' WHERE `ID`=67645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다, 츠지 님.', `MaleText_loc4`='是的，赤精。', `MaleText_loc5`='是的，赤吉。', `MaleText_loc7`='Así es, Chi-Ji.', `FemaleText_loc1`='맞아요, 츠지 님.', `FemaleText_loc4`='是的，赤精。', `FemaleText_loc5`='是的，赤吉。', `FemaleText_loc7`='Así es, Chi-Ji.' WHERE `ID`=67646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<츠지의 목소리가 마음속에 울립니다.>$b$b내가 정자 위로 올라가도록 도와주지, 친구.', `MaleText_loc4`='<赤精的声音在你脑内回响。>$b$b让我帮你登上台顶吧，朋友。', `MaleText_loc5`='<赤吉的聲音在你的心中響起。>$b$b讓我協助你到亭閣上面去，我的朋友。', `MaleText_loc7`='<Oyes cómo Chi-Ji habla en tu mente.>$b$bDeja que te ayude a subir a lo alto del pabellón.' WHERE `ID`=67647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다, 츠지 님.', `MaleText_loc4`='我很愿意接受你的帮助，赤精。', `MaleText_loc5`='我非常需要，赤吉。', `MaleText_loc7`='Me vendría muy bien, Chi-Ji.', `FemaleText_loc1`='정말 감사합니다, 츠지 님.', `FemaleText_loc4`='我很愿意接受你的帮助，赤精。', `FemaleText_loc5`='我非常需要，赤吉。', `FemaleText_loc7`='Me vendría muy bien, Chi-Ji.' WHERE `ID`=67648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁인도자가 다가온다! 후퇴하라!', `MaleText_loc4`='战争使者来了！退后！', `MaleText_loc5`='一個戰爭使者接近了!快撤退!', `MaleText_loc7`='¡Se acerca un belisario! ¡Retirada!' WHERE `ID`=67649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 이곳의 생물을 조사하고 있다네... 연구 목적으로 말이지.', `MaleText_loc4`='我在调查这里的生态情况，为了……研究。', `MaleText_loc5`='我正在為了...研究而調查這個區域的生物。', `MaleText_loc7`='Estudio la vida de esta zona para... una investigación.' WHERE `ID`=67650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 대신에 놈들에게 지옥을 보여주시오, $n! 저놈들이 무엇인지도 모르겠지만...', `MaleText_loc4`='送他们下地狱吧，$n！不管那些是什么……', `MaleText_loc5`='為了我們給他們好看，$n!不管那些是什麼東西...', `MaleText_loc7`='¡Dales una paliza de nuestra parte, $n! Sean lo que sean...', `FemaleText_loc1`='우리 대신에 놈들에게 지옥을 보여주세요, $n 님! 저놈들이 무엇인지도 모르겠지만...', `FemaleText_loc4`='送他们下地狱吧，$n！不管那些是什么……', `FemaleText_loc5`='為了我們給他們好看，$n!不管那些是什麼東西...', `FemaleText_loc7`='¡Dales una paliza de nuestra parte, $n! Sean lo que sean...' WHERE `ID`=67651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삶이란 불사가 되는 과정일 뿐입니다. 제 애완동물들은 그걸 알고 있지요.', `FemaleText_loc4`='生命是通往不死的必经之路。我的宠物们深知这个道理。', `FemaleText_loc5`='生命只不過是邁向不死的途徑。我的寵物們明瞭這一點。', `FemaleText_loc7`='La vida no es más que la antesala de la no-muerte. Mis mascotas lo entienden.' WHERE `ID`=67652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 절대 이길 수 없다!', `MaleText_loc4`='你毫无机会！', `MaleText_loc5`='你根本沒有勝算!', `MaleText_loc7`='¡No tienes ninguna posibilidad!', `FemaleText_loc1`='넌 절대 이길 수 없어!', `FemaleText_loc4`='你毫无机会！', `FemaleText_loc5`='你根本沒有勝算!', `FemaleText_loc7`='¡No tienes ninguna posibilidad!' WHERE `ID`=67653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 용을 키우고 있다네.$B$B이 예쁜이들이 다 크면, 우리 바보 형은 내게 상대도 안 될 걸세!', `MaleText_loc4`='啊，驯龙。$B$B等这些美丽的家伙长大后，就能把我那蠢哥哥比下去了！', `MaleText_loc5`='啊，培養龍族。$B$B只要這些小可愛能長大，我那愚蠢的兄弟就拿我沒轍了!', `MaleText_loc7`='Ah, el cuidado de dragones.$b$bCuando estas bellezas crezcan, ¡el tonto de mi hermano no podrá conmigo!' WHERE `ID`=67654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 설리 님을 믿으라고 했지! 하, 하하하!', `MaleText_loc4`='我就说相信老苏利没错吧！哈哈哈！', `MaleText_loc5`='我早就跟你們這群小夥子說要相信老蘇利!哈哈哈!', `MaleText_loc7`='¡Os dije que confiarais en el viejo Sully! ¡Ja, ja!' WHERE `ID`=67655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거나 먹어라, 괴물아!', `MaleText_loc4`='吸下去，怪物！！', `MaleText_loc5`='吸光它吧，怪人們!!', `MaleText_loc7`='¡Chupaos esa, bichos!' WHERE `ID`=67656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으엑! 이건 대체 뭐지?!', `MaleText_loc4`='呀！这些是什么？！', `MaleText_loc5`='噁!這些是什麼東西?!', `MaleText_loc7`='¡Puaj! ¡¿Qué son esas cosas?!' WHERE `ID`=67657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쳇, 내 탈것에서 손 떼!', `MaleText_loc4`='呸，离开我的新座驾！', `MaleText_loc5`='哼，從我的新坐騎上滾下去!', `MaleText_loc7`='¡Eh! ¡Bájate de mi nuevo juguete!' WHERE `ID`=67658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 레버가 뭘 하나 볼까... 그래! 네 볼기짝을 네 쪽으로 쪼개줄 거다!', `MaleText_loc4`='让我们瞧瞧这个控制杆是干嘛用的……哦，对了！它能让你屁股开花！', `MaleText_loc5`='讓我們試試看這個控制桿是做什麼用的...喔，沒錯!它是用來讓你屁股開花的!', `MaleText_loc7`='A ver qué hace esta palanca... ¡Ah, sí! ¡TE DA UNA PALIZA!' WHERE `ID`=67659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 남아서 "몽땅없애기" 단추까지 설치했는데!', `MaleText_loc4`='我甚至还忙里偷闲，装了个I.W.I.N.按钮！', `MaleText_loc5`='我甚至有時間裝一個I.W.I.N.按鈕!', `MaleText_loc7`='¡Me ha dado tiempo a instalar hasta un botón Y.O.G.A.N.O.!' WHERE `ID`=67660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, $n! 이제 다리 건너 마을로 가게. 난 해병들이 빠져나오는 동안 엄호를 할 테니까.', `MaleText_loc4`='干得好啊，$n！过桥就能抵达村子了。我正在替那些陆战队员收拾烂摊子。', `MaleText_loc5`='你在那裡面做得很好，$n!越過橋到村子去。我在掩護陸戰隊員們撤離。', `MaleText_loc7`='¡Buen trabajo, $n! Cruza el puente y ve a la aldea. Yo cubriré la extracción de los soldados.' WHERE `ID`=67661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 꽤 마음에 드는 걸. 어때, 친구들? 이거 가져가도 될까?', `MaleText_loc4`='我有点喜欢这玩意儿。你们觉得呢？我们能留下它吗？', `MaleText_loc5`='我有點喜歡這東西。你們認為如何，姑娘們?我們能留下它嗎?', `MaleText_loc7`='Me gusta este trasto. ¿Qué decís, muchachos? ¿Nos lo quedamos?' WHERE `ID`=67662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도무지 조용하게 처리할 수는 없구만!', `MaleText_loc4`='我们就是不能安静地搞定它！', `MaleText_loc5`='我們就是沒辦法安靜地做這件事!', `MaleText_loc7`='¡No podíamos hacerlo en silencio!' WHERE `ID`=67663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...너희들은 그저 농부의 자식들이잖나.', `MaleText_loc4`='……你们只是农民的孩子。', `MaleText_loc5`='...你們不過是農夫的孩子。', `MaleText_loc7`='... No son más que hijos de granjeros.' WHERE `ID`=67664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 우리를 위해 정말 많은 일을 해주었네, $n. 물론 싸움은 앞으로도 계속되겠지만, 작은 승리를 거뒀다고 할까...', `MaleText_loc4`='你今天为我们做了太多事，$n。我们的工作还将继续，但好歹已经取得了小小的胜利。', `MaleText_loc5`='你今天為了我們做了許多事，$n。我們的工作會持續下去，但我們得到了一場小小的勝利。', `MaleText_loc7`='Hoy has hecho mucho por nosotros, $n. Nuestro trabajo continúa, pero hemos conseguido una pequeña victoria.' WHERE `ID`=67665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네, $r! 이제 전세가 우리 쪽으로 기우는 것 같군. 자네가 우리에게 잠시 쉴 틈을 마련해 주었네, $n.', `MaleText_loc4`='谢谢你，$r！我感到战局正在朝有利于我们的方向发展。你为我们赢得了喘息之机，$n！', `MaleText_loc5`='謝謝你，$r!我感覺戰鬥的優勢已經偏向我們這邊了。你讓我們有了稍微喘息的機會，$n。', `MaleText_loc7`='¡Gracias, $r! Siento que la balanza de la batalla se equilibra en nuestro favor. Nos has dado un respiro, $n.' WHERE `ID`=67666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='두려워하지 마십시오, 타이펑 님. 위론 님은 강하십니다. 샤의 타락도 이겨내실 거라고 믿습니다.', `FemaleText_loc4`='别担心，泰峰。玉珑很强大。我相信，她一定能摆脱煞的腐化。', `FemaleText_loc5`='不要害怕，泰豐。玉龍很強大。她會掙脫煞的腐化，我很確定。', `FemaleText_loc7`='No temas, Tai-Feng. Yu''lon es fuerte. Sé que se liberará de la corrupción del sha.' WHERE `ID`=67667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤가 고대의 감옥에서 어떻게 풀려났는가는 중요하지 않습니다. 앞으로 나아갈 계획을 세워야 합니다. 어떻게 하면 이 땅에서 샤를 다시 내쫓을 수 있을까요?', `FemaleText_loc4`='煞是如何冲破了古老的囚牢，已经不重要了。我们必须制定行动方案，想想怎样才能再次将其逐出我们的土地？', `FemaleText_loc5`='煞是如何逃脫他們古老的監牢一點都不重要。我們必須為接下來的行動擬定計畫。我們要如何將他們從我們的土地上再次驅散。', `FemaleText_loc7`='No importa cómo huyeron los sha de sus antiguas prisiones. Debemos prepararnos para el futuro. ¿Cómo podemos volver a expulsarlos de nuestra tierra?' WHERE `ID`=67668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 이 말을 하는 와중에도, 타란 주와 음영파는 서쪽으로 향했습니다. 샤를 발견하면, 정의를 실천할 겁니다.', `FemaleText_loc4`='眼下，祝踏岚和影踪派正在向西行进。等他们找到煞之后，正义必将得伸。', `FemaleText_loc5`='就在我們談話的同時，塔蘭·祝和影潘正向西行軍。當他們發現煞時，正義將得以伸張。', `FemaleText_loc7`='Taran Zhu y el Shadopan están avanzando hacia el oeste ahora mismo. Cuando encuentren al sha, se hará justicia.' WHERE `ID`=67669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사원의 경비병 수는 많지 않지만, 모두 강인한 정신력을 유지하고 있습니다. 우리도 샤를 무찌르고 우리 사원에서 쫓아낼 수 있을 거라고 믿습니다만, 아무래도 길고 힘겨운 전투가 될 것 같네요.', `FemaleText_loc4`='寺院的守卫人数寥寥，可他们意志坚强。我相信，我们一定能击败煞，将其逐出寺院，但那将会是一场艰苦卓绝的持久战。', `FemaleText_loc5`='神廟的守護者並不多，但他們仍士氣高昂。我相信我們能擊敗煞，並將他們從我們的神廟中驅離，但這會是一場漫長的艱苦戰鬥。', `FemaleText_loc7`='Los guardianes del templo no son numerosos, pero su espíritu es fuerte. Creo que podemos derrotar a los sha y expulsarlos de nuestro templo, pero será una batalla larga y ardua.' WHERE `ID`=67670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 슬픔의 늪에서 큰 전투가 많이 일어났습니다. 아직도 그 전투의 여파가 느껴지는군요.', `FemaleText_loc4`='在这片沼泽里发生过许多重大冲突。我仍然能感觉到那久未散尽的能量。', `FemaleText_loc5`='這些沼澤中發生過許多猛烈的衝突。我還能感受到殘餘下來的能量。', `FemaleText_loc7`='Han tenido lugar muchos conflictos en estos pantanos. Aún percibo la energía residual.' WHERE `ID`=67671;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무척 힘겨운 전투가 될 겁니다, 타이펑. 의심의 샤는 교묘하고 집요하지요. 의심의 검은 씨앗이 뿌리내리면, 정신과 마음이 강한 자만이 이겨낼 수 있습니다.', `FemaleText_loc4`='我们的战斗极其艰苦，泰峰。疑之煞狡诈阴险。怀疑的黑暗种子一经种下，只有心神无比强大的人才能将其荡除。', `FemaleText_loc5`='我們的戰鬥是最艱辛的，泰豐。疑惑之煞狡猾且陰險。一但疑惑的黑暗種子被種下，只有擁有強大心智的人才能將它移除。', `FemaleText_loc7`='La nuestra es una batalla complicada, Tai-Feng. El Sha de la duda es sutil y taimado. Cuando planta la semilla oscura de la duda, solo un corazón y una mente fuertes pueden extirparla.' WHERE `ID`=67672;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사원의 수호자들이 대지를 굳게 지키고, 운룡단은 하늘에서 싸움을 계속합니다. 우리가 함께 싸우면, 우리 고향에서 샤를 몰아낼 수 있습니다.', `FemaleText_loc4`='寺院的守卫者在陆地上死守，而云端翔龙骑士团则在空中作战。只要齐心协力，就一定能将煞赶离我们的家园。', `FemaleText_loc5`='神廟的防衛者在地面上堅守著，而雲蛟衛在空中作戰。只要團結合作，我們就能將煞從我們的家園中驅散。', `FemaleText_loc7`='Los defensores del templo resisten en tierra firme mientras la Orden del Dragón Nimbo lucha en los cielos. Juntos expulsaremos a los sha de nuestro hogar.' WHERE `ID`=67673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 밖에 나가서 샤하고 싸울까?', `MaleText_loc4`='我也能出去对抗邪煞吗？', `MaleText_loc5`='我也可以出去和煞作戰嗎?', `MaleText_loc7`='¿Yo también puedo salir a luchar contra los sha?' WHERE `ID`=67674;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='멍청한 소리 하지 마! 샤는 위험하다고!', `FemaleText_loc4`='别犯傻！煞魔危险得很！', `FemaleText_loc5`='別傻了!煞很危險!', `FemaleText_loc7`='¡No seas tonto! ¡Los sha son peligrosos!' WHERE `ID`=67675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무서워요!', `MaleText_loc4`='我好害怕！', `MaleText_loc5`='我好怕!', `MaleText_loc7`='¡Tengo miedo!' WHERE `ID`=67676;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤가 여기도 들어 올까요?', `FemaleText_loc4`='煞魔会冲进来吗？', `FemaleText_loc5`='煞會進來這裡嗎?', `FemaleText_loc7`='¿Los sha pueden entrar aquí?' WHERE `ID`=67677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 자, 너무 걱정하지 말렴. 용감한 영웅들이 지금 샤와 싸우고 있으니까. 내가 여기 있는 한, 무엇도 너희를 다치게 하진 않을 거란다.', `FemaleText_loc4`='好了，好了。别害怕。勇敢的英雄们正在和煞交战。只要我在这，就没人能伤害你。', `FemaleText_loc5`='好了好了。不要害怕。現在有許多許多的勇敢英雄們正在和煞作戰。只要我在這裡，就沒有東西能傷害你們。', `FemaleText_loc7`='Tranquilos, tranquilos. No os asustéis. Ahora mismo hay héroes valientes luchando contra los sha. Además, mientras yo esté aquí, nada puede haceros daño.' WHERE `ID`=67678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 이들 대부분은 늪을 싫어하지만, 저는 이 늪의 탁한 수면 아래에 거대한 비밀이 있다는 걸 알고 있습니다.', `FemaleText_loc4`='大多数人都讨厌沼泽，可我知道在沼泽地阴湿的表面之下，隐藏着不为人知的重大秘密。', `FemaleText_loc5`='大部分的人都討厭沼澤，但我知道在它們黝黑的表面下隱藏著許多偉大的秘密。', `FemaleText_loc7`='La mayoría de la gente odia los pantanos, pero yo sé que ocultan muchos secretos bajo su superficie turbia.' WHERE `ID`=67679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리 위에 설퍼라스를 얹고 몇 년을 지내다 보면, 용암 딱정벌레가 가진 탄력성의 진가를 알게 될 걸세.', `MaleText_loc4`='让萨弗拉斯在你头顶上方挂个几年，你就能学会欣赏熔火甲虫的适应力了。', `MaleText_loc5`='你只要在薩弗拉斯底下過個幾年，你就能學會欣賞熔岩甲蟲的韌性。', `MaleText_loc7`='Pasa unos cuantos años con Sulfuras pendiendo sobre tu cabeza y aprenderás a valorar la resistencia del alfazaque de lava.' WHERE `ID`=67680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 여기서 얻을 건 패배뿐이랍니다.', `FemaleText_loc4`='你在这里只会一败涂地。', `FemaleText_loc5`='你在這裡只會找到失敗。', `FemaleText_loc7`='Aquí solo encontrarás la derrota.' WHERE `ID`=67681;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 애완동물 팀을 이길 순 없을 거예요. 제 실력은 끝이 없거든요!', `FemaleText_loc4`='你休想击败我的队伍。我是永生不灭的！', `FemaleText_loc5`='你毫無機會打敗我的隊伍，我是永恆的!', `FemaleText_loc7`='No tienes ninguna posibilidad de derrotar a mi equipo. ¡Soy eterna!' WHERE `ID`=67682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 하십시오, 코르벤.', `MaleText_loc4`='柯尔凡，我们继续吧。', `MaleText_loc5`='柯爾文，我們繼續吧。', `MaleText_loc7`='Prosigamos, Korven.', `FemaleText_loc1`='계속하세요, 코르벤.', `FemaleText_loc4`='柯尔凡，我们继续吧。', `FemaleText_loc5`='柯爾文，我們繼續吧。', `FemaleText_loc7`='Prosigamos, Korven.' WHERE `ID`=67683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_shieldmastery.blp:20|t%s|1이;가; |cFFFF0000|Hspell:117961|h[뚫리지 않는 방패]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_shieldmastery.blp:20|t%s施放|cFFFF0000|Hspell:117961|h[密封之盾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_shieldmastery.blp:20|t%s施放|cFFFF0000|Hspell:117961|h[不動護盾]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warrior_shieldmastery.blp:20|t¡%s lanza |cFFFF0000|Hspell:117961|h[Escudo impenetrable]|h|r!' WHERE `ID`=67684;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 축소 모형이 실물과 조금이라도 비슷하다면 당신에겐 승산이 없어요!', `FemaleText_loc4`='要是这些小东西与它们的原型有半点相像，你就毫无机会！', `FemaleText_loc5`='如果這些縮小版能有原版的一點點能力的話，你根本一點機會都沒有。', `FemaleText_loc7`='Si estas miniaturas se parecen en algo a los modelos originales, ¡no tienes ninguna posibilidad!' WHERE `ID`=67685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 세상을 여행해보고 싶군. 자넨 스톰윈드에 가본 적 있나?', `MaleText_loc4`='真希望有一天能环游世界。你见过暴风城吗？', `MaleText_loc5`='我希望有一天能去世界旅行。你有看過暴風城嗎?', `MaleText_loc7`='Quiero ver mundo algún día. ¿Has estado alguna vez en Ventormenta?' WHERE `ID`=67686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아웃랜드의 바람이 고요와 평화를 이야기하는군요.', `MaleText_loc4`='外域的微风中夹杂着平静与安宁的气息。', `MaleText_loc5`='外域之風訴說著平靜與和平。', `MaleText_loc7`='Los vientos de Terrallende hablan de paz y tranquilidad.' WHERE `ID`=67687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='목표물 포착. 불태워!', `FemaleText_loc4`='已获取目标。开火！', `FemaleText_loc5`='取得目標。炸下去。', `FemaleText_loc7`='Objetivo fijado. ¡Fuego!' WHERE `ID`=67688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나그란드에 남아 있는 생물들을 보존하려면 함께 힘을 보태야 하오.', `MaleText_loc4`='我们必须精诚合作，保护纳格兰的本土生态。', `MaleText_loc5`='我們必須合作以保存納葛蘭所剩下的特有生物。', `MaleText_loc7`='Debemos colaborar para preservar la fauna nativa de Nagrand.' WHERE `ID`=67689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잿더미로 만들어!', `FemaleText_loc4`='将它烧成平地！', `FemaleText_loc5`='把它燒成灰燼。', `FemaleText_loc7`='¡Redúcelo a cenizas!' WHERE `ID`=67690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알았다. 본때를 보여주지!', `FemaleText_loc4`='收到。让他们尝尝厉害！', `FemaleText_loc5`='收到。給他們好看。', `FemaleText_loc7`='Recibido. ¡Tendrán su merecido!' WHERE `ID`=67691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 조용히 해주겠소?', `MaleText_loc4`='你介意吗？', `MaleText_loc5`='你介意嗎?', `MaleText_loc7`='¿Te importa?' WHERE `ID`=67692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신호 확인. 곧 간다.', `FemaleText_loc4`='收到。马上行动。', `FemaleText_loc5`='我們聽到了。準備交戰。', `FemaleText_loc7`='Afirmativo. Vamos allá.' WHERE `ID`=67693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='포격선이 도착했다!', `FemaleText_loc4`='轰炸机已抵达。', `FemaleText_loc5`='運輸艦到了。', `FemaleText_loc7`='El portanaves ha llegado.' WHERE `ID`=67694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프는 우주의 주인입니다. 그것에 의문을 가질 이유는 없습니다.', `MaleText_loc4`='血精灵是宇宙的主宰。这毋庸置疑。', `MaleText_loc5`='血精靈是全世界的主人。這點是毫無疑問的。', `MaleText_loc7`='Los elfos de sangre son los amos del universo. Es incuestionable.' WHERE `ID`=67695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내기를 하는 게 어떻겠나? 내가 이기면 자네가 천골드를 주게.', `MaleText_loc4`='来做个交易如何？要是我赢了，你就给我一万个金币？', `MaleText_loc5`='我們作個交易如何?如果我贏了，你給我一萬黃金?', `MaleText_loc7`='¿Hacemos un trato? Si gano, ¿me das diez mil de oro?' WHERE `ID`=67696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='회전식 불안정화 장치 13개... 있고. 공기역학 테두리잡이 10개... 있고. 근데 내가 제일 좋아하는 스패너가 어디 있지?', `MaleText_loc4`='十三个螺旋分离器？没错。十个电动轴节钳？没错。我那把专用扳手上哪儿去了？', `MaleText_loc5`='13個旋軸反穩定器?確認。10個合金握柄?確認。我把我最愛的扳手放哪去了?', `MaleText_loc7`='¿13 desestabilizadores girománticos? Sí. ¿10 agarrativos gnumáticos? Sí. Ya solo me falta encontrar mi llave inglesa favorita...' WHERE `ID`=67697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 임무에 폭발물 고작 2톤이라고? 제 생각엔 좀 모자랄 것 같은데요. 이런 임무엔 폭발물이 그보단 훨씬 많이 필요하거든요. 고블린 방화광 폭탄 같은 걸로요.', `MaleText_loc4`='呃。执行这任务才有两吨炸药？分量不够啊。完成这种使命光靠这么点儿炸药怎么行。起码得请……地精纵火型炸药出马。', `MaleText_loc5`='嗯嗯。這任務只有配給2噸的炸藥?我覺得似乎不太夠。這任務所需的炸藥應該要多更多。像是...哥布林縱火狂炸藥。', `MaleText_loc7`='Mmm. ¿Solo dos toneladas de explosivos para esta misión? Es poco para mi gusto. Me da que esta misión es del tipo que exige muchos más explosivos... Estoy hablando del nivel de un goblin pirómano.' WHERE `ID`=67698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자이로콥터가 고작 30대라고요? 이번 임무를 제대로 마치려면 그보다는 훨씬 많이 있어야 할 텐데.', `MaleText_loc4`='才三十台旋翼机？要想顺利完成任务，还需要许多许多台。', `MaleText_loc5`='只有三十架旋翼機?我們在這場戰鬥結束前還需要比這還多上許多的旋翼機。', `MaleText_loc7`='¿Solo treinta girocópteros? Nos van a hacer falta muchos más.' WHERE `ID`=67699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 키가 아무리 작아도, 이 상자들이 상대적으로 아무리 크고 무거워도 상관없어. 갑판 아래로 가져다 둬.', `MaleText_loc4`='我不管你有多矮，也不管这些箱子对你来说有多大多重，把它们弄到甲板下面去。', `MaleText_loc5`='我不在乎你有多矮，或是這些箱子在比例上來說對你有多大或多重，把它們搬到甲板下面去。', `MaleText_loc7`='Me da igual tu estatura o que en comparación contigo esos cajones sean grandes y pesados. Bájalos a la bodega.' WHERE `ID`=67700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼬꼬댁!', `MaleText_loc4`='咯咯！', `MaleText_loc5`='咯咯嗒!', `MaleText_loc7`='¡CLUC!' WHERE `ID`=67701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='캉 시장님, 어서 움직여야 합니다! 마을 경비대를 소집하기라도 하십시오!', `MaleText_loc4`='康村长，我们必须赶快行动！至少，把村里的卫兵召集起来！', `MaleText_loc5`='康村長，我們必須迅速行動!至少要召集村子的守衛。', `MaleText_loc7`='Alcalde Khang, ¡debemos actuar de inmediato! ¡Al menos convoca a los guardias de la ciudad!' WHERE `ID`=67702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐 기다리게, 텅. 여기... 손님이 오셨군.', `MaleText_loc4`='等等，邓。我们……有访客了。', `MaleText_loc5`='等一下，騰。我們有個...訪客。', `MaleText_loc7`='Espera un momento, Teng. Tenemos... visita.' WHERE `ID`=67703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네! 이 기지를 모두 점령했군.', `MaleText_loc4`='干得好！我们守住了基地其它区域。', `MaleText_loc5`='做得好!我們已經徹底佔領營地。', `MaleText_loc7`='¡Un trabajo excelente! El resto de la base es nuestro.' WHERE `ID`=67704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 맙소사... 무슨 일이 있었던 거지? 방금 그건 뭐였소?', `MaleText_loc4`='国王在上——这里怎么了？那玩意是什么？', `MaleText_loc5`='我的天啊...這裡發生了什麼事?那是什麼東西啊?', `MaleText_loc7`='En el nombre del Rey... ¿qué pasó aquí? ¿Qué era esa cosa?' WHERE `ID`=67705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 적은 "샤"에 사로잡힌 거요. 이들은 의심과 같은 부정적인 감정을 먹고 자라지.', `MaleText_loc4`='你的敌人被名叫“煞”的黑暗能量控制了。煞能依靠疑惑等负面情绪滋长。', `MaleText_loc5`='你們的敵人是被一股叫做「煞」的黑暗能量壓倒。它會因負面情緒成長，例如懷疑。', `MaleText_loc7`='Tu enemigo estaba poseído por una energía oscura que llamamos "sha". Se alimenta de las emociones negativas, como la duda.' WHERE `ID`=67706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍지 않군. 호드는 괴물이니까!', `MaleText_loc4`='我并不惊讶。部落都是怪物！', `MaleText_loc5`='我不覺得驚訝。部落都是怪物!', `MaleText_loc7`='No me sorprende. ¡Los de la Horda son monstruos!' WHERE `ID`=67707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네들의 하늘 요새를 봤소. "평화"에 대한 정의가 우리와는 다른 것 같군.', `MaleText_loc4`='我见过你们的空中堡垒。你们对“和平”的定义很是有趣。', `MaleText_loc5`='我看到你們的天空堡壘了。你們的人對於「和平」的看法還真有趣。', `MaleText_loc7`='Ya he visto tu fortaleza voladora. Tu gente tiene un concepto interesante de la paz.' WHERE `ID`=67708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 날뛰게 내버려 두면, 이 땅을 빼앗기고 말 거요. 우리와 함께 싸우겠소?', `MaleText_loc4`='如果任其作恶，部落会吞噬你们的土地。你不打算帮忙对抗他们？', `MaleText_loc5`='只要部落保有那些工具，他們就會淹沒你們的土地。你們不想幫我們一起戰鬥嗎?', `MaleText_loc7`='Si no lo impedimos, la Horda invadirá tu tierra. ¿No nos ayudarás a luchar contra ellos?' WHERE `ID`=67709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움은 두렵지 않소. 우린 수가 적지만, 실력이 뛰어나거든.', `MaleText_loc4`='我们不怕战斗。我们的战士尽管人数稀少，却个个身手不凡。', `MaleText_loc5`='我們不怕戰鬥。我們的戰士雖然數量不多，卻具有非常強的戰技。', `MaleText_loc7`='No nos da miedo luchar. Nuestros guerreros, aunque son pocos, son extremadamente hábiles.' WHERE `ID`=67710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑게 맞아줘서 정말 고맙소. 지금 옳은 일을 하고 있는 거요.', `FemaleText_loc4`='感谢你的盛情款待，村长。我向你保证，你做得很对。', `FemaleText_loc5`='感謝你的招待，村長。我保證:你是在做正確的事。', `FemaleText_loc7`='Muchas gracias por tu hospitalidad alcalde. Te aseguro que están haciendo lo correcto.' WHERE `ID`=67711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='병사들을 쉬게 해도 좋소. 하지만 어느 쪽 편을 드는 것은 아니오.', `MaleText_loc4`='如何处置这些士兵是你的事情，我们不会选择立场。', `MaleText_loc5`='你們可以隨意讓士兵在這裡佇留，但是我們不會選邊站。', `MaleText_loc7`='Son libres de alojar a estos soldados, pero NO elegiremos bando.' WHERE `ID`=67712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 단순히 종족 간의 분쟁일 뿐, 그 증오는 이 땅을 집어삼킬 거요. 우린 함께하지 않겠소.', `MaleText_loc4`='这不是一场种族战争这么简单。他们的仇恨会吞噬这片土地——我们绝不会介入。', `MaleText_loc5`='這個衝突不僅僅是種族戰爭。他們的仇恨會吞沒這片土地...我們不會攪和進去。', `MaleText_loc7`='Su conflicto es poco más que una guerra de razas. Su odio consumiría esta tierra. No tomaremos parte en eso.' WHERE `ID`=67713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가야겠소. 북쪽 해안에 다른 자들이 나타났으니까.', `MaleText_loc4`='我必须离开了——还有其他人登上了我们北方的海岸。', `MaleText_loc5`='我必須走了-還有其他人在我們的北邊海岸登陸。', `MaleText_loc7`='Debo irme. Hay más forasteros en la costa norte.' WHERE `ID`=67714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지나갈게요!', `FemaleText_loc4`='来了！', `FemaleText_loc5`='借過!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=67715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기, 분수 옆에! 천천히 내려놓으세요.', `FemaleText_loc4`='喷泉那边！把他们轻轻放下。', `FemaleText_loc5`='在那裡，噴泉旁邊!現在溫和地把他們放下。', `FemaleText_loc7`='¡Allí, al lado de la fuente! Déjalos con suavidad.' WHERE `ID`=67716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다니엘, 그 환자는 쇼크 상태에요. 곁에서 머물면서 심박수를 지켜보세요. 상태가 달라지면 제게 알려주세요.', `FemaleText_loc4`='丹尼尔，那位病人休克了。待在旁边观察他的心率，要是有异常，马上通知我。', `FemaleText_loc5`='丹尼爾，那個病人休克了。待在他旁邊並監控他的心跳頻率，如果有什麼變化就讓我知道。', `FemaleText_loc7`='Daniel, ese paciente está en estado de shock. Quédate con él y vigila su ritmo cardíaco. Avísame si cambia.' WHERE `ID`=67717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다.', `MaleText_loc4`='明白。', `MaleText_loc5`='了解。', `MaleText_loc7`='Entendido.' WHERE `ID`=67718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스탠턴, 저 사람 이마에 얼음을 좀 올리세요. 우선 붓기를 가라앉혀야 해요.', `FemaleText_loc4`='斯坦顿，把冰块敷在那人的头上。我们得帮他消肿。', `FemaleText_loc5`='斯坦頓，把一些冰塊放在那個人的頭上。我們必須讓他消腫。', `FemaleText_loc7`='Stanton, ponle hielo en la cabeza a ese hombre. Hay que bajar la inflamación.' WHERE `ID`=67719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네.', `FemaleText_loc4`='敷好了。', `FemaleText_loc5`='我馬上做。', `FemaleText_loc7`='Ahora mismo.' WHERE `ID`=67720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 숲은 어떻게 하실 겁니까?', `MaleText_loc4`='我们要对林地采取什么行动？', `MaleText_loc5`='對於林地我們該怎麼做?', `MaleText_loc7`='¿Qué vamos a hacer con el claro?' WHERE `ID`=67721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병들은 이곳에 있어야 하네. 숲에서의 일을 복수하려면, 텅, 여기 우리 손님들과 이야기하는 게 좋겠어.', `MaleText_loc4`='这里需要守卫。要是你想去林地复仇，邓，你可以跟这位客人谈谈。', `MaleText_loc5`='這裡需要守衛。騰，如果你想要去林地報仇，我建議你和我們的客人談談。', `MaleText_loc7`='Los guardias hacen falta aquí. Si quieres vengarte por el claro, Teng, te sugiero que hables con los visitantes.' WHERE `ID`=67722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='커다란 당근을 기르라고 했습니다. 재미있을 거라고도 했지요.', `MaleText_loc4`='他们说，要种下巨大的胡萝卜。他们说，会其乐无穷。', `MaleText_loc5`='他們說要種巨大的胡蘿蔔。他們還說那會很有趣。', `MaleText_loc7`='Cultiva zanahorias gigantes, decían. Será divertido, decían.' WHERE `ID`=67723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 큰 당근은 쓸모가 없을 뿐입니다.', `MaleText_loc4`='这么大个的胡萝卜显得真不实际。', `MaleText_loc5`='這麼大的胡蘿蔔根本不切實際。', `MaleText_loc7`='Las zanahorias tan grandes no son prácticas y punto.' WHERE `ID`=67724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 괭이에 또 잔돌이 걸려나왔잖아!', `MaleText_loc4`='呸，我锄头又崩掉了一个角！', `MaleText_loc5`='啊，又被我鋤頭的小刺扎到了。', `MaleText_loc7`='¡Bah! ¡Otra astilla en mi azada!' WHERE `ID`=67725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 되간다는 느낌이 하나도 들지 않는군요...', `MaleText_loc4`='看起来简直毫无进展……', `MaleText_loc5`='感覺起來我根本沒有任何進展...', `MaleText_loc7`='No parece que avance...' WHERE `ID`=67726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 커다란 당근이 필요한 겁니까?', `MaleText_loc4`='我们干嘛要种这么大个的胡萝卜？', `MaleText_loc5`='我們為什麼需要這麼大的胡蘿蔔?', `MaleText_loc7`='¿Para qué queremos zanahorias de semejante tamaño?' WHERE `ID`=67727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='렐, 보고하라! 아래 상황은 어떤가?', `FemaleText_loc4`='夜风，报告！下面发生了什么事？', `FemaleText_loc5`='夜風，回報!下面是什麼狀況?', `FemaleText_loc7`='¡Brisa Nocturna, informa! ¿Qué ocurre ahí abajo?' WHERE `ID`=67728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 병력이 그쪽으로 헤엄쳐 간다. 사격을 개시하라.', `FemaleText_loc4`='部落士兵从船骸游向你所在的位置。立即开火。', `FemaleText_loc5`='部落軍隊正在從殘骸游到你的位置。立刻開火。', `FemaleText_loc7`='Las tropas de la Horda se dirigen a nado hasta su posición desde los naufragios. Abran fuego.' WHERE `ID`=67729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들은 맨손으로라도 네 목을 조를 것이다. 어서 쏴버려!', `FemaleText_loc4`='你难道不知道，他们现在恨不得徒手掐死你？击毙他们！', `FemaleText_loc5`='你以為他們會因為要赤手把你勒死而遲疑嗎?立刻開火!', `FemaleText_loc7`='¿Crees que dudarán en estrangularlos con las manos desnudas? ¡MÁTENLOS A TODOS!' WHERE `ID`=67730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 초토화는 피할 수 있었어요, $c님. 테라모어가 평화의 상징일 때도 있었는 걸요...', `FemaleText_loc4`='这场毁灭本可避免，$c。曾几何时，塞拉摩是和平的象征……', `FemaleText_loc5`='這場破壞原本是可以避免的，$c。塞拉摩曾經是和平的象徵...', `FemaleText_loc7`='Esta devastación se podría haber evitado, $c. Hubo una época en la que Theramore era un símbolo de paz...' WHERE `ID`=67731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황폐화되기 전의 테라모어를 보여주십시오.', `MaleText_loc4`='让我看看塞拉摩被毁前的样子。', `MaleText_loc5`='讓我看看被破壞之前的塞拉摩。', `MaleText_loc7`='Muéstrame cómo era Theramore antes de la destrucción.', `FemaleText_loc1`='황폐화되기 전의 테라모어를 보여주세요.', `FemaleText_loc4`='让我看看塞拉摩被毁前的样子。', `FemaleText_loc5`='讓我看看被破壞之前的塞拉摩。', `FemaleText_loc7`='Muéstrame cómo era Theramore antes de la destrucción.' WHERE `ID`=67732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기함의 흔적은 없다. 테일러 제독이나 안두인 왕자님도 마찬가지다.', `MaleText_loc4`='没有旗舰的线索，也没有上将泰勒或安度因王子的踪迹。', `MaleText_loc5`='沒發現旗艦，也沒發現泰勒上將或安杜因王子。', `MaleText_loc7`='No hay rastro del buque insignia y tampoco del almirante Taylor ni del príncipe Anduin.' WHERE `ID`=67733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제독, 저들은 항복할 생각이다. 비무장 상태다. 빠져 죽지 않으려는 것뿐이다!', `MaleText_loc4`='上将——我想他们是要投降。他们手无寸铁——只是不想淹死！', `MaleText_loc5`='上將...我想他們要投降。他們沒有武器...他們只是不想溺死!', `MaleText_loc7`='Almirante... Creo que quieren rendirse. No están armados. ¡Solo intentan salvarse!' WHERE `ID`=67734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴 순 없어... 이건 학살이야... 비무장 상태인 적을... 우욱! 몸이... 이상하군...', `MaleText_loc4`='不……这简直是屠杀……他们手无寸铁——呃！我不太……不太舒服……', `MaleText_loc5`='這樣不對...這是屠殺...他們手無寸鐵...!我...我不太舒服...', `MaleText_loc7`='Esto no está bien... Es una masacre... Estaban desarmados… No... No me siento bien…' WHERE `ID`=67735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어야 할 놈들이었지.', `MaleText_loc4`='也许他们确实该死。', `MaleText_loc5`='也許他們就是該死。', `MaleText_loc7`='Quizás merecían morir.' WHERE `ID`=67736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 참혹할 수가...', `FemaleText_loc4`='真可惜……', `FemaleText_loc5`='真浪費...', `FemaleText_loc7`='Qué desperdicio...' WHERE `ID`=67737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어떤 결정은 참으로 끔찍한 대가가 따르는군요.', `FemaleText_loc4`='某些决定会引发可怕的后果。', `FemaleText_loc5`='有些決定會導致悲慘的結果。', `FemaleText_loc7`='Algunas decisiones tienen consecuencias nefastas.' WHERE `ID`=67738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물들 같으니! 이게 무슨 짓이냐?', `MaleText_loc4`='你们这群畜生！你们疯了吗？', `MaleText_loc5`='你們!這是什麼鬼?', `MaleText_loc7`='¡Salvajes! ¿Qué locura es esta?' WHERE `ID`=67739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사격 중지. 원주민 중 하나다.', `MaleText_loc4`='弟兄们，放下武器——这是个当地人。', `MaleText_loc5`='大夥兒退下。這是原住民。', `MaleText_loc7`='Alto, soldados. Se trata de un nativo.' WHERE `ID`=67740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 얼라이언스요. 해칠 의도는 없소. 말하시오. 내게서 쫓아낸 어둠이 뭐였소?', `MaleText_loc4`='我们来自联盟，没有恶意。告诉我，你刚才从我体内逐出的黑影是什么？', `MaleText_loc5`='我們屬於聯盟，對你們沒有惡意。告訴我，你從我身上抽出的暗影是什麼?', `MaleText_loc7`='Somos de la Alianza y no pretendemos hacerte daño. Pero dime, ¿qué era esa sombra que me extrajiste?' WHERE `ID`=67741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기선 설명할 수 없소. 간단히 말하면, 당신 행동에 의해, 자신의 의심이 실체화된 것이오.', `MaleText_loc4`='这儿不是作详细解释的地方。简单说吧，由于你的所作所为，源自你自身的疑惑现形了。', `MaleText_loc5`='這裡不是解釋的好地方。簡單說，你們自己的懷疑會成真，變為你們動作的結果。', `MaleText_loc7`='Este no es lugar para explicaciones. En resumen, tus propias dudas se han manifestado como consecuencia de tus actos.' WHERE `ID`=67742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이해를 못 하는군. 이곳은 전쟁터요.', `MaleText_loc4`='你不明白——我们是在这里打仗——', `MaleText_loc5`='你不了解，我們正處於戰爭之中...', `MaleText_loc7`='No lo entiendes. Estamos librando una guerra...' WHERE `ID`=67743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 이해하고 있소. 나도 눈이 있으니까. 판다리아는 당신의 고향과는 전혀 다른, 살아 숨쉬는 땅이오. 이곳에 어떤 힘을 가져올지 곰곰이 생각해야 하오. 어서 무기를 거두시오!', `MaleText_loc4`='噢，我明白得很。我有眼睛。可潘达利亚跟其它地方不一样，它有生命，会呼吸。你应该小心控制自己带来的能量。现在，丢掉那些武器！', `MaleText_loc5`='噢，我完全明白。我有眼睛。但是潘達利亞和你們來的地方完全不同:它活著，有著呼吸。你們最好小心處理你們帶來的能量。還不把武器放下!', `MaleText_loc7`='Lo entiendo perfectamente. Tengo ojos. Pero Pandaria no es como la tierra de la que proceden: está viva y respira. Deberían tener cuidado con la energía que traen aquí. Y ahora, ¡dejen las armas!' WHERE `ID`=67744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍멍이의 호루라기를 잃어버린 것 같습니다.', `MaleText_loc4`='我好像把狗哨放错地方了。', `MaleText_loc5`='我似乎把馴犬口哨放錯地方了。', `MaleText_loc7`='Creo que he perdido el silbato para perros.', `FemaleText_loc1`='멍멍이의 호루라기를 잃어버린 것 같아요.', `FemaleText_loc4`='我好像把狗哨放错地方了。', `FemaleText_loc5`='我似乎把馴犬口哨放錯地方了。', `FemaleText_loc7`='Creo que he perdido el silbato para perros.' WHERE `ID`=67745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 지금까지 벌인 일을 수습하려는 것 같군요, 이방인. 어쩌면 우린 서로를 도울 수 있을지도 모릅니다.', `MaleText_loc4`='你似乎愿意收拾自己的烂摊子，外来者。也许我们能互相帮助。', `MaleText_loc5`='你似乎願意清理你造成的亂象，外來者。也許我們能互相幫忙。', `MaleText_loc7`='Pareces $gdispuesto:dispuesta; a enmendar tus errores, $gforastero:forastera;. A lo mejor podemos ayudarnos mutuamente.' WHERE `ID`=67746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 보여주지!', `MaleText_loc4`='见识一下我的力量！', `MaleText_loc5`='瞧瞧我的力量!', `MaleText_loc7`='¡CONTEMPLEN MI PODER!' WHERE `ID`=67747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연금술사님, 호랑이 연고를 좀 더 주실 수 있으십니까?', `MaleText_loc4`='药剂师，能再给我来点跌打酒吗？', `MaleText_loc5`='藥劑師，你能再給我一些你的跌打酒嗎?', `MaleText_loc7`='Boticario, ¿me das un poco más de Dit Da Jow?', `FemaleText_loc1`='연금술사님, 호랑이 연고를 좀 더 주실 수 있으신가요?', `FemaleText_loc4`='药剂师，能再给我来点跌打酒吗？', `FemaleText_loc5`='藥劑師，你能再給我一些你的跌打酒嗎?', `FemaleText_loc7`='Boticario, ¿me das un poco más de Dit Da Jow?' WHERE `ID`=67748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='까악!', `MaleText_loc4`='嘎！', `MaleText_loc5`='嘎!', `MaleText_loc7`='¡Aak!', `FemaleText_loc1`='까악!', `FemaleText_loc4`='嘎！', `FemaleText_loc5`='嘎!', `FemaleText_loc7`='¡Aak!' WHERE `ID`=67749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들의 지도자가 아직 숨어 있다. 찾아라!', `MaleText_loc4`='他们领头的还躲着呢。把他找出来！', `MaleText_loc5`='他們的指揮官還在躲藏。找到他!', `MaleText_loc7`='Su líder aún se esconde. Mira a ver si lo encuentras. Busca en la cueva cercana.' WHERE `ID`=67750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처치했군. 잘했다!', `MaleText_loc4`='你干掉他了——好样的！', `MaleText_loc5`='你殺掉他了。做得好!', `MaleText_loc7`='Acabaste con él. ¡Bien hecho!' WHERE `ID`=67751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어둠은 뭐지? 얼라이언스의 장난인가?', `MaleText_loc4`='那黑影是什么？联盟在玩什么把戏？', `MaleText_loc5`='這個暗影是什麼?聯盟在玩什麼把戲?', `MaleText_loc7`='¿Qué es esa sombra? ¿A qué juega la Alianza?' WHERE `ID`=67752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 적은 "샤"에 사로잡힌 거요. 이들은 의심과 같은 부정적인 감정을 먹고 자라지.', `MaleText_loc4`='你的敌人被名叫“煞”的黑暗能量控制了。煞能依靠疑惑等负面情绪滋长。', `MaleText_loc5`='你們的敵人是被一股叫做「煞」的黑暗能量壓倒。它會因負面情緒成長，例如懷疑。', `MaleText_loc7`='Tu enemigo estaba poseído por una energía oscura que llamamos "sha". Se alimenta de las emociones negativas, como la duda.' WHERE `ID`=67753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 너군. 이제 알겠나? 얼라이언스의 교만을!', `MaleText_loc4`='又是你。现在你见识到联盟的傲慢了吧！', `MaleText_loc5`='又是你。你知道這就是聯盟的傲慢所致嗎?', `MaleText_loc7`='Tú otra vez. ¿Ahora lo entiendes? ¡La arrogancia de la Alianza!' WHERE `ID`=67754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네들 없이도 우리는 수천 년을 견뎌 왔소.', `MaleText_loc4`='没有你们，我们也挺着胸膛在这里生活了几千年。', `MaleText_loc5`='沒有你們，我的人民也已經驕傲地過了好幾千年了。', `MaleText_loc7`='Mi gente ha vivido con orgullo sin ustedes desde hace miles de años.' WHERE `ID`=67755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움이 겁나나?', `MaleText_loc4`='你们是害怕战斗吧？', `MaleText_loc5`='你們不敢戰鬥?', `MaleText_loc7`='¿Les da miedo luchar?' WHERE `ID`=67756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움은 두렵지 않소. 우린 수가 적지만, 실력이 뛰어나거든.', `MaleText_loc4`='我们不怕战斗。我们的战士尽管人数稀少，却个个身手不凡。', `MaleText_loc5`='我們不怕戰鬥。我們的戰士雖然數量不多，卻具有非常強的戰技。', `MaleText_loc7`='No nos da miedo luchar. Nuestros guerreros, aunque son pocos, son extremadamente hábiles.' WHERE `ID`=67757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 적대적 지역이고, 지원군도 없다. 임기응변이 필요할 것이다, 용사여.', `MaleText_loc4`='这里是敌方领地，我们又孤立无援。看我们临场发挥了，勇士。', `MaleText_loc5`='這是險惡的地域，而我們沒有援軍。我們必須隨機應變，勇士。', `MaleText_loc7`='Esta es una tierra hostil y no tenemos refuerzos. Vamos a tener que improvisar, campeón.' WHERE `ID`=67758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 임무는 계속된다. 이곳엔 헬스크림 님의 전초기지가 들어선다. 얼라이언스 나부랭이가 이 신대륙을 차지하게 하지는 않겠다!', `MaleText_loc4`='但我发誓——地狱咆哮一定会在这里站稳脚跟。我们决不允许联盟霸占这片新大陆！', `MaleText_loc5`='但任務依舊不變:地獄吼會在此取得立足點。我們絕不允許聯盟佔領這塊新大陸!', `MaleText_loc7`='Pero te aseguro una cosa: Grito Infernal tendrá su base aquí. ¡No permitiremos que la Alianza se haga con este nuevo mundo!' WHERE `ID`=67759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 아직 날개가 없지만, 제 애완동물들도 마찬가지예요!', `MaleText_loc4`='我还没能证明我可以飞呢！我的宠物们也没有！', `MaleText_loc5`='我還沒贏得我的翅膀，但我的寵物也還沒有!', `MaleText_loc7`='Todavía no me he ganado las alas, ¡y mis mascotas tampoco!' WHERE `ID`=67760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲 속을 혼자 돌아다니는 건 안전하지 않다네. 안 그런가?', `MaleText_loc4`='孤身一人在树林里游荡不太安全，你觉得呢？', `MaleText_loc5`='單獨地穿過叢林很不安全，你不覺得嗎?', `MaleText_loc7`='¿No crees que es peligroso recorrer el bosque sin protección?' WHERE `ID`=67761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개굴', `MaleText_loc4`='呱呱', `MaleText_loc5`='呱呱', `MaleText_loc7`='Croac.', `FemaleText_loc1`='개굴', `FemaleText_loc4`='呱呱', `FemaleText_loc5`='呱呱', `FemaleText_loc7`='Croac.' WHERE `ID`=67762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 사람들 말에 속지 마라. 용은 전쟁에 쓰이는 무기다. 단지 그것뿐이야.', `MaleText_loc4`='不要相信别人的鬼话。龙只是战争的武器，别无它用。', `MaleText_loc5`='別讓其他人愚弄你。龍是戰爭的武器;僅此而已。', `MaleText_loc7`='No te dejes engañar. Los dragones son armas de guerra, nada más.' WHERE `ID`=67763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 얼라이언스 쓰레기들은 호드가 분노하면 어떤 일이 일어나는지 배우게 될 것이다!', `MaleText_loc4`='那些联盟渣滓会明白，激怒部落是什么下场！', `MaleText_loc5`='那些聯盟的雜碎將學到激怒部落會有什麼下場!', `MaleText_loc7`='¡Esa escoria de la Alianza descubrirá las consecuencias de desafiar a la Horda!' WHERE `ID`=67764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 이름으로 우리가 이 땅을 차지한다! 목숨을 걸어라!', `MaleText_loc4`='我们将以部落之名夺取这片土地，至死方休！', `MaleText_loc5`='我們將以部落之名取得這片土地，或誓死爭取!', `MaleText_loc7`='¡Tomaremos esta tierra en nombre de la Horda o moriremos en el intento!' WHERE `ID`=67765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 아직 호드의 분노가 어떤 건지 제대로 맛보지도 못했다!', `MaleText_loc4`='他们甚至都还没见识到部落的怒火！', `MaleText_loc5`='他們還沒真正見識到部落之怒!', `MaleText_loc7`='¡No saben lo que es la furia de la Horda!' WHERE `ID`=67766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기 일을 끝낼 쯤이면, 얼라이언스는 이 땅에 발을 들인 것을 후회하게 될 것이다.', `MaleText_loc4`='等我们完成这里的事之后，联盟一定会后悔踏上这片土地。', `MaleText_loc5`='等到我們把一切搞定之時，聯盟將會希望他們根本沒來過這個地方。', `MaleText_loc7`='Cuando hayamos acabado aquí, la Alianza deseará no haber puesto un pie en esta tierra.' WHERE `ID`=67767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=67768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약삭빠른 수였으나, 제게 정말 무기가 하나밖에 없다고 생각하십니까? 독을 바른 검을 사용할 만큼 강한 상대를 기다리고 있었습니다.', `MaleText_loc4`='真是高明的把戏，可你真以为我就带一套武器来与你交手吗？我等了这么久，终于迎来了旗鼓相当的对手，总算能试试我这浸毒的利剑了。', `MaleText_loc5`='聰明的技倆，但你真的認為我會只有一組武器能和你作戰嗎?我已經等待值得讓我拿出塗過毒藥的雙劍的對手很久了。', `MaleText_loc7`='Unos trucos ingeniosos, ¿pero de verdad crees que solo tengo un conjunto de armas? Estaba deseando probar mis espadas embadurnadas de veneno con un oponente digno.' WHERE `ID`=67769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 몸 안에서 이거 기어다니는 거 찾았다.', `MaleText_loc4`='我总是觉得心神不宁。', `MaleText_loc5`='我發現這些東西在我體內鑽來鑽去。', `MaleText_loc7`='Yo encontrar estas cosas dentro de mí.' WHERE `ID`=67770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 반대편에서 공격할 거네, $c. 얼라이언스 놈들, 이렇게 빨리 지상 공격을 시작할 줄은 예상도 못하겠지. 학살이 끝나면 다시 이야기하세.', `MaleText_loc4`='我们会从另一侧进攻，$c。联盟不会料到，我们这么快就发起地面攻击。等屠杀结束后再来找我。', `MaleText_loc5`='我們將會從反側進攻，$c。聯盟不會預料到地面攻擊來得這麼快。屠殺結束後來找我。', `MaleText_loc7`='Atacaremos por el lado opuesto, $c. La Alianza no se esperará un asalto terrestre tan pronto. Ven a verme cuando haya terminado la masacre.' WHERE `ID`=67771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 어서 힘을 내세요. 우린 할 수 있다고요. 나는 것 말이에요!', `MaleText_loc4`='来吧，伙计们。我们能行。起飞！', `MaleText_loc5`='加油啊，大夥。我們辦得到的。飛啊!', `MaleText_loc7`='Venga, chicos, ¡podemos hacerlo! ¡Volad!' WHERE `ID`=67772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언젠가는 온 세상을 여행할 걸세. 내 애완동물들도 함께 말이야!', `MaleText_loc4`='总有一天，我将探索整个世界，而我的宠物们也会与我同行！', `MaleText_loc5`='有一天我將會探索整個世界，而我的寵物們會跟著我去!', `MaleText_loc7`='Algún día exploraré todo el mundo, ¡y mis mascotas se vendrán conmigo!' WHERE `ID`=67773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이 모룰루에게 왔군요...', `MaleText_loc4`='有人来找莫勒鲁了……', `MaleText_loc5`='有人接近莫魯魯...', `MaleText_loc7`='Alguien se acerca a Morulu...' WHERE `ID`=67774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 참으십시오. 곧 괜찮아질 겁니다.', `MaleText_loc4`='坚持住，伙计。你会没事的。', `MaleText_loc5`='支持住啊，夥伴。你不會有事的。', `MaleText_loc7`='Aguanta, colega. Te pondrás bien.' WHERE `ID`=67775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥박이 안정되었어요, 미시카. 하지만 너무 약합니다.', `MaleText_loc4`='他的脉搏平稳，米希卡。但很虚弱。', `MaleText_loc5`='他的脈搏穩定，密西卡。但很微弱。', `MaleText_loc7`='El pulso es débil pero estable, Mishka.' WHERE `ID`=67776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='붕대가 너무 더럽네요. 제가 갈아 드릴게요.', `FemaleText_loc4`='这些绷带脏兮兮的。我们帮你清理一下吧。', `FemaleText_loc5`='這些繃帶髒死了。讓我們幫你清理乾淨。', `FemaleText_loc7`='Estas vendas están hechas un desastre. Vamos a cambiarlas.' WHERE `ID`=67777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 이해하려면, 이 주민들 곁에 머물러야 하네.', `MaleText_loc4`='要想真正了解这片土地，我们就必须公平地对待这些人。', `MaleText_loc5`='如果我們想要有機會能了解這片土地，我們就必須為了這些人著想。', `MaleText_loc7`='Si queremos comprender esta tierra, debemos tratar bien a esta gente.' WHERE `ID`=67778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미시카가 당신을 치료할 겁니다. 제 말 들리세요?', `MaleText_loc4`='米希卡会好好照顾你的，能听见我说话吗？', `MaleText_loc5`='密西卡會好好照顧你的，你聽到我說的話了嗎?', `MaleText_loc7`='Mishka cuidará de ti, ¿me oyes?' WHERE `ID`=67779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 위해 오크 열 마리를 처치할게요, 친구.', `MaleText_loc4`='我接下来要杀死的十个兽人是献给你的，朋友。', `MaleText_loc5`='我接下來殺的十個獸人將是為了你，朋友。', `MaleText_loc7`='La próxima vez que mate orcos será en tu honor, colega.' WHERE `ID`=67780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들이 전쟁의 길에서 벗어나지 않으면, 끔찍한 일이 일어날 것이네.', `MaleText_loc4`='如果你继续在战争的路上越走越远，你的行为一定会引发严重的后果。', `MaleText_loc5`='如果你不捨棄你的戰爭之道，你的行動將會有很嚴重的下場。', `MaleText_loc7`='Tus actos tendrán graves consecuencias si no te desvías del camino de la guerra.' WHERE `ID`=67781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 행동에는 반작용이 따르지. 여기서의 자네 행동에 어떤 반작용이 따를지 알겠나?', `MaleText_loc4`='任何行为都会引发后果。你知道自己的行为已经酿成什么后果了吗？', `MaleText_loc5`='每個行為都會有一個反作用。你知道你的行為會有什麼反作用嗎?', `MaleText_loc7`='Toda acción desencadena una reacción. ¿Ves lo que han creado tus actos?' WHERE `ID`=67782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 시작에 불과한 것은 아닐까 두렵네.', `MaleText_loc4`='我担心，这仅仅是个开始。', `MaleText_loc5`='我很擔心這才剛開始而已。', `MaleText_loc7`='Me temo que esto es solo el principio.' WHERE `ID`=67783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전쟁을 계속하겠다니... 눈이 멀었나?', `MaleText_loc4`='你眼瞎了吗，竟然要延续这场战斗？', `MaleText_loc5`='你難道盲目到想繼續這場戰爭嗎?', `MaleText_loc7`='¿El odio te ciega tanto que quieres prolongar esta guerra?' WHERE `ID`=67784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀술이 모두... 사라졌습니다...', `MaleText_loc4`='所有的酒……都没了……', `MaleText_loc5`='所有的酒...都沒了...', `MaleText_loc7`='Se han llevado toda la cerveza...' WHERE `ID`=67785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 멋진 일이 일어날 겁니다! 우르릉 쾅쾅 대폭발!', `MaleText_loc4`='好戏即将上演！爆炸！', `MaleText_loc5`='這裡將發生很酷的事!爆炸!', `MaleText_loc7`='¡Aquí pasarán cosas chulas! ¡Explosiones!' WHERE `ID`=67786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결투를 시작합시다!', `MaleText_loc4`='该你了！', `MaleText_loc5`='你自找的!', `MaleText_loc7`='¡Vamos allá!', `FemaleText_loc1`='결투를 시작하시죠!', `FemaleText_loc4`='该你了！', `FemaleText_loc5`='你自找的!', `FemaleText_loc7`='¡Vamos allá!' WHERE `ID`=67787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 영광을 위해 명예롭게, 그리고 용맹하게 싸울 것이네!', `MaleText_loc4`='我会为了联盟的荣耀，勇敢光荣地战斗！', `MaleText_loc5`='我將帶著榮譽與勇氣，為了聯盟的榮耀而戰!', `MaleText_loc7`='¡Lucharé con honor y valor por la gloria de la Alianza!' WHERE `ID`=67788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보게 $r, 얼라이언스의 영광을 만끽해보게나. 오늘은 무슨 일이 있어도 나를 이기지 못할 걸세!', `MaleText_loc4`='沐浴在联盟的荣光下吧，$r。今天你应该明白，你根本不可能打败我！', `MaleText_loc5`='沐浴在聯盟的榮耀中吧，$r。你今天根本沒機會擊敗我!', `MaleText_loc7`='Contempla la gloria de la Alianza, $r. Acepta que no tienes ninguna posibilidad de vencerme.' WHERE `ID`=67789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 애완동물 있잖아. 우리 싸울까?', `MaleText_loc4`='你也有宠物。我们打一场吧？', `MaleText_loc5`='你也有寵物。我們來戰鬥吧?', `MaleText_loc7`='Tú también tener mascotas. ¿Nosotros luchar?' WHERE `ID`=67790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀술 통 모으는 중', `MaleText_loc4`='收集蜜露酒桶', `MaleText_loc5`='收集甘露酒桶中', `MaleText_loc7`='Recoger barrica de birramiel' WHERE `ID`=67791;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이거 참, 멋진 난장판 아닌가요?', `FemaleText_loc4`='这里乱糟糟的，是吧？', `FemaleText_loc5`='這不是一團亂嗎?', `FemaleText_loc7`='Vaya desastre.' WHERE `ID`=67792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에는 당신의 도움이 필요합니다.', `MaleText_loc4`='部落需要你的帮助。', `MaleText_loc5`='部落需要你的協助。', `MaleText_loc7`='La Horda necesita tu ayuda.', `FemaleText_loc1`='호드에는 당신의 도움이 필요해요.', `FemaleText_loc4`='部落需要你的帮助。', `FemaleText_loc5`='部落需要你的協助。', `FemaleText_loc7`='La Horda necesita tu ayuda.' WHERE `ID`=67793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 도움?! 내 도움이 필요하다고요?! 보잘것없는 이 전쟁에 힘을 보탤 생각은 없어요.', `FemaleText_loc4`='我的帮助？！你们需要我的帮助？！我才不要介入你们那琐碎的战斗。', `FemaleText_loc5`='我的協助?!你想要我的協助?!我才不會參與你們微不足道的爭鬥。', `FemaleText_loc7`='¿Mi ayuda? ¿Quieren mi ayuda? No participaré en sus peleas sin sentido.' WHERE `ID`=67794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 도움이 필요하다고요? 당신네들이 박살내 버린 평화를 복구하느라 제가 좀 바빠서요.', `FemaleText_loc4`='你需要我的帮助？我正忙着帮你们收拾残局，恢复这里的和平。', `FemaleText_loc5`='你想要我的幫助?我正忙著要試圖恢復你們所搗亂的平靜。', `FemaleText_loc7`='¿Queréis mi ayuda? Estoy algo ocupada restaurando la paz que habéis destruido.' WHERE `ID`=67795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 오늘 하고 싶었던 건 저희 작물을 수확하는 것뿐이었어요. 그런데 지금은 짐승들과 싸움이나 하고 있네요!', `FemaleText_loc4`='我今天原本只想收割庄稼。结果却跟小偷纠缠不休！', `FemaleText_loc5`='原本我今天只想要收割我的農作物。然而現在，我卻被迫跟這些徘徊者瞎鬧。', `FemaleText_loc7`='Yo solo quería cosechar mis cultivos. ¡Pero tengo que atrapar merodeadores!' WHERE `ID`=67796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니나 저나, 꿀이슬 마을이 이렇게 북적거리는 건 정말 오랫만에 보는 것 같네요. 아니, 처음인 것도 같아요!', `FemaleText_loc4`='我跟妹妹从来都没在蜜露村里见过这种阵势，从来没有！', `FemaleText_loc5`='我姊妹和我從來沒有看過甘露村有這麼多事!', `FemaleText_loc7`='Mi hermana y yo no hemos visto tanta actividad en Poblado Almíbar desde... nunca, de hecho.' WHERE `ID`=67797;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 비행선 때문에 우리 기구가 박살 날 뻔했어요!', `FemaleText_loc4`='你们的飞艇差点把我们的气球弄爆了！', `FemaleText_loc5`='你的飛艇差點就毀了我們的氣球!', `FemaleText_loc7`='¡Tu nave casi se lleva nuestro globo por delante!' WHERE `ID`=67798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이방인이여, 우린 당신의 전쟁에 관심이 없어요. 이곳은 평화로운 마을이에요.', `FemaleText_loc4`='我们对你们的战争不感兴趣，外乡人。这是个平静的村庄。', `FemaleText_loc5`='我們對你們的戰爭不感興趣，外來者。這是個平靜的村莊。', `FemaleText_loc7`='No nos interesa su guerra. Esta es una aldea pacífica.' WHERE `ID`=67799;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 당신이 이곳에 오기 전까지는 평화로웠지요.', `FemaleText_loc4`='在你们到来之前，平静得很。', `FemaleText_loc5`='直到你們來之前都很平靜。', `FemaleText_loc7`='Bueno, era pacífica hasta que llegaron ustedes.' WHERE `ID`=67800;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희들의 전쟁 한복판에 붙들려 있는 시간이 길어지지 않기만을 바랄 뿐이다. 여기 머물면서 부상자들을 보살펴도 좋다. 하지만 그게 우리가 허락할 수 있는 전부니라.', `FemaleText_loc4`='我们决不会让自己卷入你们的战斗。你可以留在这里，照料伤员，但休想拖我们下水。', `FemaleText_loc5`='我們不會涉入你們的戰爭之中太久的。你們可以待在這裡照顧你們的傷者，但我們受到的牽連也僅此而已。', `FemaleText_loc7`='Haremos todo lo posible para no vernos atrapados en medio de su guerra. Pueden quedarse aquí y cuidar de sus heridos, pero no nos involucraremos más.' WHERE `ID`=67801;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사원이 함락되면 안 돼요!', `FemaleText_loc4`='寺院绝不能沦陷！', `FemaleText_loc5`='寺廟絕不能失守!', `FemaleText_loc7`='¡El templo no debe caer!' WHERE `ID`=67802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"지혜가 길을 밝힌다"라는 말이 있지.$b$b하지만 지혜가 있어도 밤에 발이 자꾸 어딘가 걸려.', `MaleText_loc4`='据说，“智慧能照亮前路。”$b$b……可光有智慧，我在夜晚照样会撞到脚趾头。', `MaleText_loc5`='俗話說『智慧能照亮道路』。$b$b...但是智慧從來沒有讓我晚上不踢傷我的腳趾過。', `MaleText_loc7`='Se dice que "La sabiduría ilumina el camino".$b$b... Pues la sabiduría nunca me ha ayudado a no darme golpes en el pie por las noches.' WHERE `ID`=67803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 약했으나 저는 강합니다!', `MaleText_loc4`='很弱，但我比他强！', `MaleText_loc5`='他很弱，但我比較強!', `MaleText_loc7`='¡Era débil, pero yo soy fuerte!' WHERE `ID`=67804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 수습생에 지나지 않았습니다. 사부의 의지는 수준이 다르지요!', `MaleText_loc4`='他只是个受训者。大师的意志要强大得多！', `MaleText_loc5`='他只不過是個受訓弟子。一個大師的意志更強大!', `MaleText_loc7`='No era más que un alumno. ¡La voluntad de un maestro es más fuerte!' WHERE `ID`=67805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다. 진짜 도전에 한 발자국 가까워지셨군요.', `MaleText_loc4`='干得好，你距离真正的挑战又近了一步。', `MaleText_loc5`='做得好，你向真正的挑戰又邁進了一步。', `MaleText_loc7`='¡Bien hecho! Estás un paso más cerca del auténtico desafío.' WHERE `ID`=67806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들을 쓰러뜨리십시오. 그러면 나는 당신이 상상할 수도 없을 만큼 강해집니다.', `MaleText_loc4`='击倒他们，我变得更为强大，超乎你的想象。', `MaleText_loc5`='打倒他們，而我會變得比你所能想像的還要更加強大。', `MaleText_loc7`='Derrótalos y me volveré más poderoso de lo que puedas imaginar.' WHERE `ID`=67807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까, $n 님. 이 땅의 각종 금속을 채집하고 다루는 법을 배우고자 하십니까?', `MaleText_loc4`='你好，$n，你愿意学习如何在我们的土地上找到各种各样的金属，并加以冶炼吗？', `MaleText_loc5`='哈囉，$n，你想要學習如何取得和加工在我們土地上所能找到各種金屬嗎?', `MaleText_loc7`='Hola, $n. ¿Quieres aprender a adquirir y trabajar los distintos metales de nuestra tierra?' WHERE `ID`=67808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 이 밧줄을 묶게! 이 용을 어서 구해야 하네.', `MaleText_loc4`='把绳子绑紧了，兄弟们！我们要立刻捕到这只幼龙。', `MaleText_loc5`='把那些繩索綁緊，隊友們!我們得馬上抓住這頭龍。', `MaleText_loc7`='¡Atad esas cuerdas, equipo! Hay que asegurar a ese draco de inmediato.' WHERE `ID`=67809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 열심히 일해라, 더러운 놈들아! 안 그러면 산 채로 구워 버릴 테다!', `MaleText_loc4`='加把劲儿，你们这群懒虫，不然我就把你们活活烤熟！', `MaleText_loc5`='你們這群懶惰的雜種給我努力點，否則我會活活烤死你!', `MaleText_loc7`='¡Trabajad más rápido, chuchos perezosos, u os asaré vivos!' WHERE `ID`=67810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품을 하나라도 망가뜨리면, 네놈들 머리를 망가뜨려 주겠다!', `MaleText_loc4`='要是敢弄破一件货物，我就打碎你的脑袋！', `MaleText_loc5`='把任何的補給品弄壞，我就會敲碎你的腦袋!', `MaleText_loc7`='Si rompéis un suministro, ¡yo os romperé el cráneo!' WHERE `ID`=67811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목숨을 바쳐 보급품을 지켜라, 더러운 강아지들아!', `MaleText_loc4`='用生命守卫这些货物，你们这群垃圾杂碎！', `MaleText_loc5`='用你們的性命看守這些補給品，你們這群卑劣的傢伙!', `MaleText_loc7`='¡Protegan los suministros con sus vidas, perros asquerosos!' WHERE `ID`=67812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 벼룩투성이 앞발로 식량을 건드리면 가만두지 않겠다, 지저분한 동물들아!', `MaleText_loc4`='别用你们那长满跳蚤的脏爪子碰食物，肮脏的畜生们！', `MaleText_loc5`='你們滿是跳蚤的腳爪最好離食物遠點，你們這群骯髒的野獸!', `MaleText_loc7`='¡Alejad esas zarpas pulgosas de la comida, bestias repugnantes!' WHERE `ID`=67813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용병들을 잘 감시해라, 형제들이여!', `MaleText_loc4`='密切注意这些雇佣兵，兄弟们！', `MaleText_loc5`='好好看著這些傭兵，兄弟們!', `MaleText_loc7`='¡Vigilad a los mercenarios de cerca, hermanos!' WHERE `ID`=67814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징 소리가 울려 퍼지며 아래의 사마귀 군단을 자극하자, 군단의 공격 속도가 빨라집니다.', `MaleText_loc4`='锣朝下方的螳螂妖大军发出了一声嘲讽般的巨响，加快了它们攻击的节奏。', `MaleText_loc5`='鑼對下面的螳螂人軍隊發出嘲弄般的聲響，加速他們進攻的腳步。', `MaleText_loc7`='El gong transmite una nota provocadora a los ejércitos mántides de abajo y acelera el ritmo de su asalto.' WHERE `ID`=67815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 수련은 끝났네. 내일 다시 오면 계속하지.', `MaleText_loc4`='你今天的训练已经完成了。明天再回来继续训练。', `MaleText_loc5`='你今天的訓練完成了。明天回來我們繼續。', `MaleText_loc7`='Tu entrenamiento ha terminado por hoy. Vuelve mañana y seguiremos.' WHERE `ID`=67816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 이 종족 전쟁이나 유혈 사태에 동참하지는 않겠소.', `MaleText_loc4`='但我们不想卷入这场生灵涂炭……血流成河的屠杀。', `MaleText_loc5`='但是我們不會加入你們這些...滅族式的血戰。', `MaleText_loc7`='Pero no participaremos en este... baño de sangre genocida.' WHERE `ID`=67817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들의 갈등이 무시무시한 결과를 불러올 거요. 이 땅에 전쟁을 불러오지 마시오!', `MaleText_loc4`='你们的冲突会让这里饱受摧残。别把战火引到这片海岸！', `MaleText_loc5`='你們的矛盾在這裡會產生深遠的影響。不要把你們的戰爭帶來這裡!', `MaleText_loc7`='Su conflicto tendrá consecuencias inmensas aquí. ¡No traigan su guerra a estas costas!' WHERE `ID`=67818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 이 종족 전쟁이나 유혈 사태에 동참하지는 않겠소.', `MaleText_loc4`='但我们不想卷入这场……血流成河的种族纷争。', `MaleText_loc5`='但是我們不會加入你們這些...滅族式的血戰。', `MaleText_loc7`='Pero no participaremos en este... baño de sangre genocida.' WHERE `ID`=67819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들의 갈등이 무시무시한 결과를 불러올 거요. 이 땅에 전쟁을 불러오지 마시오!', `MaleText_loc4`='你们的冲突会让这里饱受摧残。别把战火引到这片海岸！', `MaleText_loc5`='你們的矛盾在這裡會產生深遠的影響。不要把你們的戰爭帶來這裡!', `MaleText_loc7`='Su conflicto tendrá consecuencias inmensas aquí. ¡No traigan su guerra a estas costas!' WHERE `ID`=67820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨겨진 힘이 이곳에 있다! 찾아내야만 한다!', `MaleText_loc4`='这里隐藏着力量，我们必须让它显现！', `MaleText_loc5`='這裡隱藏著力量，而我們必須找到它!', `MaleText_loc7`='¡Aquí se oculta un poder secreto y debemos descubrirlo!' WHERE `ID`=67821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='느껴진다! 오래전 죽은 모구의 영혼들이!', `MaleText_loc4`='我能感觉到它们，逝去已久的魔古魂灵！', `MaleText_loc5`='我能感覺到他們，死去已久的魔古之魂!', `MaleText_loc7`='¡Puedo sentir los espíritus de los mogu muertos!' WHERE `ID`=67822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 있어도 폐허를 지켜야 한다!', `MaleText_loc4`='不惜一切代价，守住这片遗迹！', `MaleText_loc5`='不計代價守住這些廢墟!', `MaleText_loc7`='¡Asegurad estas ruinas a toda costa!' WHERE `ID`=67823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샅샅이 뒤져라!', `MaleText_loc4`='每个角落都仔仔细细的搜查！', `MaleText_loc5`='不要漏掉一磚一瓦的好好搜索!', `MaleText_loc7`='¡No dejéis piedra por mover!' WHERE `ID`=67824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔들리지 마라! 곧 고대의 모구 동맹군을 만나게 될 테니!', `MaleText_loc4`='不要动摇！我们很快就能和古老的魔古同伴们团结在一起了！', `MaleText_loc5`='別灰心!我們很快就能和我們古老的魔古盟友重聚!', `MaleText_loc7`='¡No flaqueéis! ¡Pronto nos reuniremos con nuestros antiguos aliados mogu!' WHERE `ID`=67825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음 드리는 씨앗 봉투는 무료입니다! 씨앗을 더 사려면 언제든지 다시 들러주십시오.', `MaleText_loc4`='第一包种子是免费的！要是想买更多种子，随时可以回来找我，明白了吗？', `MaleText_loc5`='第一包種子就當送你的!只要你想買更多種子就回來找我，聽到了嗎?', `MaleText_loc7`='El primer paquete de semillas es gratis. Ven a verme siempre que quieras comprar semillas, ¿me oyes?' WHERE `ID`=67826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하셔야 할 게 한 가지 있는데, 채소가 다 자라려먼 하루가 걸립니다. 그러니 땅을 갈아엎고 씨앗을 심은 뒤 다음 날에 다시 와서 수확하십시오!', `MaleText_loc4`='记住一点，真正的庄稼需要一整天的生长周期，所以在你完成耕种和照料后，第二天再回去收获果实吧！', `MaleText_loc5`='要記住，真正的農作物需要一天的時間成長，所以你種下並照料你的農作物後，要在隔天回來採收你的成果!', `MaleText_loc7`='No olvides que los cultivos de verdad tardan un día en crecer, así que cuando hayas labrado y cuidado de tus plantas, ¡vuelve al día siguiente para cosechar tu recompensa!' WHERE `ID`=67827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이젠 이 농장에서 혼자 일할 준비가 다 된 것 같군요. 원하신다면 매일 여기로 돌아와서 채소를 심고 수확할 수 있습니다. 열심히 일하면 이 농장을 더 크게 확장할 수도 있습니다!', `MaleText_loc4`='好吧伙计，看来你已经能独立打理这个农场了。要是愿意的话，可以每天回来种植和收割蔬菜。如果我们努力劳作，也许还能把这地方升级！', `MaleText_loc5`='夥伴，看來你已經準備好自己管理這個農場了。你想要的話可以每天回來種植並採收蔬菜。如果我們努力點，我們甚至可以為這個地方升級!', `MaleText_loc7`='Bueno, colega, parece que ya puedes llevar la granja sin ayuda. Vuelve todos los días para plantar y cosechar verduras, si quieres. Si nos esforzamos, ¡a lo mejor hasta podemos mejorar este sitio!' WHERE `ID`=67828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 좋지 않은 소식이 있습니다. 당신은 매일 이곳으로 돌아와서 채소를 심고 수확할 수 있지만, 제가 농사꾼 연합에 가입하는 일을 도와주기에 앞서 당신은 경험을 더 쌓아야 할 겁니다. 하지만 잊지 마십시오. 농장에는 언제 오시던 대환영입니다!', `MaleText_loc4`='好吧伙计，我这有些坏消息。你每天都可以回来种植和收割蔬菜，但你得积累更多经验，才能帮我加入阡陌客。不过别忘了——随时欢迎你到农场上来！', `MaleText_loc5`='夥伴，我有些壞消息得和你說。你可以每天回來種植並採收你的蔬菜，但在你能幫助我加入耕者工會前你還需要更多的經驗。但別忘記 - 這裡隨時都歡迎你來!', `MaleText_loc7`='Me temo que tengo una mala noticia. Puedes volver todos los días para plantar y cosechar verduras, pero te hace falta más experiencia para ayudarme a unirme al gremio de labradores. Pero no lo olvides: ¡siempre serás $gbienvenido:bienvenida; en mi granja!' WHERE `ID`=67829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 주민들의 제단과 사원을 보호하기 위해 무엇이든 해야 해요.', `FemaleText_loc4`='我们必须竭尽全力保护我族人的圣地和寺院。', `FemaleText_loc5`='我們必須盡我們所能保護我們族人的祠堂和寺廟。', `FemaleText_loc7`='Debemos hacer todo lo posible para proteger los santuarios y los templos de mi pueblo.' WHERE `ID`=67830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모루크가 너 이긴다!', `MaleText_loc4`='莫鲁克要打扁你！', `MaleText_loc5`='摩洛卡將會擊敗你!', `MaleText_loc7`='¡Mo''ruk te va a dar una paliza!' WHERE `ID`=67831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올해 수확으로 얻는 건 농작물뿐만이 아닐 거예요!', `FemaleText_loc4`='今年的收成不仅包括庄稼！', `FemaleText_loc5`='今年的收成可不是只有農作物而已!', `FemaleText_loc7`='¡La cosecha de este año nos ha proporcionado algo más que cultivos!' WHERE `ID`=67832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투를 위해 수많은 시간을 준비해왔소.', `MaleText_loc4`='我为这场战斗做了无数小时的准备。', `MaleText_loc5`='我花了數不清的時間準備這場戰鬥。', `MaleText_loc7`='Me he pasado muchas horas preparándome para esta batalla.' WHERE `ID`=67833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 황무지에서의 용감한 삶은 제 애완동물을 천하무적으로 만들어줬습니다.', `MaleText_loc4`='勇闯这片荒野，已经让我的宠物变得战无不胜。', `MaleText_loc5`='勇敢地面對這些荒原讓我的寵物能夠所向無敵。', `MaleText_loc7`='Sobrevivir en el desierto ha vuelto invencibles a mis mascotas.' WHERE `ID`=67834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다리아에서 가장 신성한 곳에서, 가장 어려운 난관에 직면하게 되었군요.', `FemaleText_loc4`='你将在潘达利亚最神圣的区域内面对最困难的挑战。', `FemaleText_loc5`='如今你會在潘達利亞最神聖的領域中面對你最艱辛的挑戰。', `FemaleText_loc7`='Es en el reino más sagrado de Pandaria donde te enfrentarás a tu desafío más duro.' WHERE `ID`=67835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 끝장이야!', `MaleText_loc4`='你输定了！', `MaleText_loc5`='你完蛋了!', `MaleText_loc7`='¡Tienes los días contados!', `FemaleText_loc1`='넌 끝장이야!', `FemaleText_loc4`='你输定了！', `FemaleText_loc5`='你完蛋了!', `FemaleText_loc7`='¡Tienes los días contados!' WHERE `ID`=67836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 무리를 움직이는 자가 누구냐? 클락시의 물음에 답하라.', `MaleText_loc4`='是谁控制着这个虫群！出来！ 回应卡拉克西的召唤。', `MaleText_loc5`='誰掌管這批蟲群?現身吧!回答卡拉西的問題。', `MaleText_loc7`='¿Quién lidera este enjambre? ¡Muéstrate! Responde ante los Klaxxi.' WHERE `ID`=67837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반역의 무리 클락시... 너희에 대한 폐하의 말씀이 옳았군.', `MaleText_loc4`='叛徒卡拉克西……女皇陛下说得一点不错。', `MaleText_loc5`='叛黨卡拉西...女皇對你們的判斷是正確的。', `MaleText_loc7`='Klaxxi traidores... Su magnificencia tenía razón sobre ustedes.' WHERE `ID`=67838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이름을 말해라. 우리가 나눌 얘기는 그것뿐이다.', `MaleText_loc4`='报上名来，傀儡，让我们的历史记载更完整些。', `MaleText_loc5`='傀儡，說出你的名字，完成我們的歷史。', `MaleText_loc7`='Revela tu nombre, insecto, para que nuestros anales estén completos.' WHERE `ID`=67839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여제 폐하의 목소리, 황실 장로 조르로크다.', `MaleText_loc4`='大宰相佐尔洛克，女皇的代言人。', `MaleText_loc5`='女皇大臣索拉格，女皇之聲。', `MaleText_loc7`='Visir imperial Zor''lok, voz de la Emperatriz.' WHERE `ID`=67840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 "폐하"는 이제 끝이야. 당장 물러서라. 아니면 죽음을 맞는 수밖에.', `MaleText_loc4`='你的“女皇”已经倒下了。卡拉克西做出了判决。让开，否则就死。', `MaleText_loc5`='你的「女皇」已經一敗塗地。卡拉西做出了裁決，退下，或被消滅。', `MaleText_loc7`='Tu "Emperatriz" ha caído. Los Klaxxi han pronunciado sentencia. Apártate o te destruiremos.' WHERE `ID`=67841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시는 해체될 것이다. 그것이 여제 폐하의 뜻이다.', `MaleText_loc4`='遵照女皇的旨意，卡拉克西将被遣散。', `MaleText_loc5`='依女皇之命，卡拉西就此解散。', `MaleText_loc7`='Los Klaxxi deben ser disueltos por orden de la Emperatriz.' WHERE `ID`=67842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 그런 소릴!', `MaleText_loc4`='亵渎！', `MaleText_loc5`='褻瀆者!', `MaleText_loc7`='¡Blasfemia!' WHERE `ID`=67843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 클락시 놈들... 궁지에 몰리니 화석까지 파냈군. 좋다. 이제 끝내 주마.', `MaleText_loc4`='我看到绝望的卡拉克西已经沦落到去挖化石了。好极了，让我们做个了结吧。', `MaleText_loc5`='卡拉西絕望到挖起化石來了。很好，我們了結這件事吧。', `MaleText_loc7`='Los Klaxxi están tan desesperados que se rebajan a excavar fósiles. Muy bien, acabemos con esto.' WHERE `ID`=67844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크캬캬캬캭!', `MaleText_loc4`='Kl-kl-kl-kl-klagh！', `MaleText_loc5`='喀-喀-喀-喀-喀啦!', `MaleText_loc7`='¡Kl-kl-kl-kl-klagh!' WHERE `ID`=67845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, "다치지 않는"다더니.', `MaleText_loc4`='“毫发未伤”，确实如此。', `MaleText_loc5`='的確是『毫髮無傷』。', `MaleText_loc7`='"Indemne"... ya.' WHERE `ID`=67846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전진! 클락시는 반역자 도당이었다. 씨를 말려라. 단 한 놈도 살려 두지 마라.', `MaleText_loc4`='前进！卡拉克西已经公然显露叛徒的身份。消灭他们，一个不留。', `MaleText_loc5`='前進!卡拉西現出了叛徒的本性。消滅他們，什麼都不留。', `MaleText_loc7`='¡Adelante! Los Klaxxi han resultado ser unos traidores. ¡Exterminadlos y que no quede nada!' WHERE `ID`=67847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨우는 자여, 너는 그간의 행동으로 클락시의 믿음을 얻어냈다.', `MaleText_loc4`='唤醒者，你的功劳为你赢得了我们的信任。', `MaleText_loc5`='喚醒者，你的行為贏得了卡拉西的信任。', `MaleText_loc7`='Heraldo, tus hazañas te han granjeado la confianza de los Klaxxi.' WHERE `ID`=67848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그 보상을 얻으리라. 잠시 걷지.', `MaleText_loc4`='你将受到嘉奖。随我来。', `MaleText_loc5`='跟我來，領取你的獎賞。', `MaleText_loc7`='Te recompensaremos. Acompáñame.' WHERE `ID`=67849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 사마귀족은 고대 종족이다. 너희와 손잡은 판다렌은 아이에 불과해. 물론 그들에게도 역할이 있지.', `MaleText_loc4`='我们螳螂妖是个古老的种族。你结识的熊猫人——不过是孩童。他们有自己要扮演的角色。', `MaleText_loc5`='我們螳螂人是古老的種族，與你來往的熊貓人一族跟我們相比...就像孩子罷了。他們有他們的使命。', `MaleText_loc7`='Los mántides somos una raza antigua. Los pandaren con los que tratas no son más que niños. Tienen su propia misión.' WHERE `ID`=67850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순환의 때마다, 우리 어린것들이 판다렌의 장벽을 덮친다. 약자는 죽고, 강자만 돌아오지.', `MaleText_loc4`='每次轮回，我们年轻的虫群涌上长城。熊猫人杀光弱者。而强者得以返回。', `MaleText_loc5`='每次循環，新生的螳螂人朝長城進攻，弱的被殺了，強的存活回來。', `MaleText_loc7`='Cada ciclo, nuestros jóvenes arrasan sus murallas. Los pandaren matan a los débiles. Los fuertes regresan.' WHERE `ID`=67851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 세대를 거듭하며, 우리는 더욱 강해진다.', `MaleText_loc4`='代代繁衍，我们变得越发强大。', `MaleText_loc5`='因此每過一個世代，我們就變得更加強壯。', `MaleText_loc7`='Cada generación nos volvemos más fuertes.' WHERE `ID`=67852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 문명이 시작되기 전, 우리 제국은 광활했다. 형제 왕국인 안퀴라즈, 아졸네룹과 함께 세상을 호령했지.', `MaleText_loc4`='在你们之前，我们的帝国早已广大无边。我们与姐妹王国安其拉和艾卓-尼鲁布平分这个世界。', `MaleText_loc5`='在你們的歷史開始前，我們的帝國雄霸一方，與姊妹王朝安其拉與阿茲歐-奈幽，三分天下。', `MaleText_loc7`='Antes de que comenzara nuestra historia, el imperio era extenso. Compartíamos el mundo con nuestros reinos gemelos, Ahn''Qiraj y Azjol-Nerub.' WHERE `ID`=67853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 신은 수가 많고 강력했어. 우린 이샤라즈의 일곱 머리를 섬겼지.', `MaleText_loc4`='我们的神祗众多而强大。我们螳螂妖崇拜的是七首亚煞极。', `MaleText_loc5`='我們有許多神，個個力量強大。我們螳螂人侍奉的是七頭的亞煞拉懼。', `MaleText_loc7`='Nuestros dioses eran muchos y poderosos. Adorábamos a las sietes cabezas de Y''Shaarj.' WHERE `ID`=67854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신은 위대했고, 그 분노는 끔찍했다. 이샤라즈는 희망을 삼키고 절망을 불렀다. 용기를 들이마시고 공포를 내뿜었지.', `MaleText_loc4`='上古尊者很伟大，可发起怒来令人胆寒。他吞噬希冀，招引绝望；他吸进勇气，呼出恐惧。', `MaleText_loc5`='祂是偉大的上古之神，祂的兇猛最是駭人。祂吞噬希望，招致絕望;祂吸入勇氣，呼出畏懼。', `MaleText_loc7`='El Antiguo era magnífico, y su ira, terrible. Consumía la esperanza y sembraba el desaliento. Respiraba valor y exhalaba miedo.' WHERE `ID`=67855;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강탈자들... 너희가 티탄이라 부르는 자들이 왔을 때, 이샤라즈는 파멸했다.', `MaleText_loc4`='被你们称为“泰坦”的篡位者到来时，亚煞极遭到了毁灭。', `MaleText_loc5`='後來篡位者出現，你們稱呼他們為「泰坦」。結果亞煞拉懼被殺了。', `MaleText_loc7`='Cuando llegaron los usurpadores, aquellos a los que llamas "titanes", destruyeron a Y''Shaarj.' WHERE `ID`=67856;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 끔찍한 마지막 숨결이 이 땅을 물들였지만, 지금 남은 어둠은 과거의 영광에 비하면 그림자에 불과해.', `MaleText_loc4`='他最后的恐怖呼吸变成挥之不散的阴影，可跟他先前的荣耀相比不值一提。', `MaleText_loc5`='祂最後的恐怖之息至今還侵擾著這片大地，但此陰影比起祂過往榮耀來說根本就微不足道。', `MaleText_loc7`='Su último aliento maldice esta tierra desde entonces, pero las sombras que dejó son meros susurros de su antigua gloria.' WHERE `ID`=67857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라. 네가 자격이 있기에 말해주는 것이다.', `MaleText_loc4`='我们信任你，所以给你这个警告。', `MaleText_loc5`='現在我告訴你這些，是因為你贏得這個警訊。', `MaleText_loc7`='Te lo cuento porque te has ganado esta advertencia.' WHERE `ID`=67858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 신은 우리의 신이 아니다, 이방인이여.', `MaleText_loc4`='你的神将不再是神，外来者。', `MaleText_loc5`='你的神不是正統的神，外來者。', `MaleText_loc7`='Tus dioses no son los nuestros, forastero.' WHERE `ID`=67859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신들이 돌아오면, 우리 사마귀족은 다시 한 번 그 옆에 설 것이다.', `MaleText_loc4`='一旦上古尊者归来，螳螂妖将再一次追随他们。', `MaleText_loc5`='若上古之神回來，我們螳螂人會再次侍奉祂們。', `MaleText_loc7`='Si los Antiguos vuelven algún día, los mántides volveremos a servirlos.' WHERE `ID`=67860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 너희 중 현명한 자들도 그리하겠지.', `MaleText_loc4`='你们当中的智者也会如此。', `MaleText_loc5`='你們之中的聰明人也會這麼做。', `MaleText_loc7`='Los más sabios de entre ustedes harán lo mismo.' WHERE `ID`=67861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얘기할 건 여기까지다. 자, 보상을 받아라. 그리고 오늘 얻은 가르침을 기억해라.', `MaleText_loc4`='要说的就这么多。来吧，拿上你的奖赏。记住你今天学到的一切。', `MaleText_loc5`='我的話就說到這裡。來吧，拿走你的獎賞，記住你今天學到的東西。', `MaleText_loc7`='Eso es todo lo que debes saber. Ven, toma tu recompensa. Y recuerda lo que has aprendido hoy.' WHERE `ID`=67862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 당신도 역시 코타 봉우리에 가봤구려. 나와 싸울만한 상대라는 걸 증명한 거요.', `MaleText_loc4`='我看见你也排除万难，登上了寇塔峰。你已经证明了自己的能力，有资格与我交战。', `MaleText_loc5`='看來你也爬到了柯沓峰的山巔。你已經證明你有資格和我對戰。', `MaleText_loc7`='Veo que tú también has superado los peligros de la Cumbre Kota. Has demostrado ser $gdigno:digna; de enfrentarte a mí en combate.' WHERE `ID`=67863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 아가씨! 거 좀 조심하라고!', `MaleText_loc4`='嘿女士！小心点好吗！', `MaleText_loc5`='嘿小姐!小心點好嗎!', `MaleText_loc7`='¡Eh, señora! ¡Un poco de cuidado!' WHERE `ID`=67864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만 좀 찔러!', `MaleText_loc4`='别再摆弄那根棍子了！', `MaleText_loc5`='你戳夠了沒!', `MaleText_loc7`='¡Ya vale con el palo!' WHERE `ID`=67865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해!', `MaleText_loc4`='当心点！', `MaleText_loc5`='小心點!', `MaleText_loc7`='¡Ojo!' WHERE `ID`=67866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아야! 왜 막대기를 갖고 그러는 거야?!', `MaleText_loc4`='哎呦！怎么老用棍子戳人？！', `MaleText_loc5`='噢!那棍子是怎麼回事?!', `MaleText_loc7`='¡Ay! ¡¿Pero qué pasa con ese palo?!' WHERE `ID`=67867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하라고, 이 아가씨야! 난 무척 연약한 고블린이거든!', `MaleText_loc4`='轻点女士！我可娇嫩得很！', `MaleText_loc5`='小心點小姐!我很脆弱的!', `MaleText_loc7`='¡Cuidado, señora! ¡Soy muy frágil!' WHERE `ID`=67868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자꾸 찌르지 말라고!', `MaleText_loc4`='别再用那玩意儿戳我！', `MaleText_loc5`='別再用那東西戳我了!', `MaleText_loc7`='¡Deja de atosigarme con esa cosa!' WHERE `ID`=67869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네. 이제 훈련은 끝이 났네. 흑우의 제단으로 오면 보상을 주겠네.', `MaleText_loc4`='干得好。你已经完成训练了。与我在玄牛神龛会面，领取奖励。', `MaleText_loc5`='做得好!你的訓練已經完成了。到玄牛神殿來見我領取你的獎賞。', `MaleText_loc7`='Bien hecho. Tu entrenamiento ha terminado. Ven a verme en el Santuario del Buey para obtener tu recompensa.' WHERE `ID`=67870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨... 아니, 안 돼! 어딘가에 공군 기지가 있었다니... 내 함선이... 내... 헬스크림 님이 날 가만두지...', `MaleText_loc4`='怎么——不——不！他们有空军基地，秘密空军基地……我的船——我的——地狱咆哮会要了我的脑袋的！', `MaleText_loc5`='這是...不...不!他們有空軍基地，秘密空軍基地...我的船...我的...地獄吼會砍了我的頭...', `MaleText_loc7`='¿Qué...? No... ¡NO! Tenían una base aérea, una base aérea escondida... Mi barco... Ahhhhh!... Grito Infernal tendrá mi cabeza...' WHERE `ID`=67871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 죽여버려.', `MaleText_loc4`='他们都得死。', `MaleText_loc5`='他們全都要死。', `MaleText_loc7`='Todos deben morir.' WHERE `ID`=67872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 곰 같은 녀석, 이게 무슨 마법이었나?', `MaleText_loc4`='你！熊——什么的。这是什么巫术？', `MaleText_loc5`='你!熊怪物。這是什麼巫術?', `MaleText_loc7`='¡Tú! Especie de oso, ¿qué clase de brujería es esta?' WHERE `ID`=67873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 적을 박살낼 욕망과 명예뿐이다. 너희는 지금까지 얼라이언스를 돕고 있었나?', `MaleText_loc4`='我们只是渴望胜利的荣耀，渴望粉碎敌人。你们一直在帮助联盟吗？', `MaleText_loc5`='我們只帶來我們的榮耀，跟毀滅敵人的慾望。你們種族在幫聯盟嗎?', `MaleText_loc7`='Solo traemos honor y el deseo de aplastar a nuestros enemigos. ¿Tu especie ha estado ayudando a la Alianza?' WHERE `ID`=67874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 당신 자신의 의심이 실체가 된 것이오. 판다리아는 당신의 고향 땅과는 다른, 살아 숨쉬는 대지요. 이곳에 어떤 힘을 가져올 땐, 신중해야 하오.', `MaleText_loc4`='陌生人——你自身的疑惑现形了。潘达利亚跟其它地方有所不同，它有生命，会呼吸。你应该小心控制自己带来的能量。', `MaleText_loc5`='陌生人...你自己的懷疑已經被化為實體。潘達利亞和你們來的地方完全不同:它活著，有著呼吸。你們最好小心處理你們帶來的能量。', `MaleText_loc7`='Forastero, tus propias dudas se han manifestado. Pandaria no es como la tierra de la que provienes: está viva y respira. Deberías tener cuidado con la energía que traes aquí.' WHERE `ID`=67875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신네들의 피바다에 우리 피를 섞을 생각은 없소. 이제 무기를 거두시오. 그렇지 않으면, 당신의 적은 둘이 될 것이오.', `MaleText_loc4`='我们才不想卷入这场血腥杀戮。现在，请让你的人放下武器，否则你在这里就要面对两拨敌人了。', `MaleText_loc5`='我們沒有意願要被扯進你們的廝殺。現在你們最好放下武器，不然你們在這片大陸上會有兩群敵人。', `MaleText_loc7`='No deseamos involucrarnos en su baño de sangre. Ahora ordena a tus hombres que bajen las armas o tendrán DOS enemigos en este continente.' WHERE `ID`=67876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네의 의심과 증오가 이 폐허 전체를 난장판으로 만들었네. 몸을 추스리고 아래에 있는 마을로 날 찾아오게. 할 수 있는 데까지 설명해 줄 테니.', `MaleText_loc4`='你们的疑惑和仇恨在这片遗迹间引发了浩劫。自己收拾残局吧，然后到下方的村里来——我会尽力解释给你们听。', `MaleText_loc5`='你們的懷疑和仇恨引發了這些廢墟中的動盪。清理一下然後跟我在下面的村莊碰面...我會盡量做出解釋。', `MaleText_loc7`='Sus dudas y su odio han sembrado el caos por todas estas ruinas. Arreglen lo que hicieron y reúnanse conmigo en la aldea. Intentaré explicarles todo.' WHERE `ID`=67877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아콜론이 전장에 등장했습니다!', `MaleText_loc4`='阿卡隆已经进入了战场！', `MaleText_loc5`='阿寇隆已經進入了戰場!', `MaleText_loc7`='¡Akkolon ha entrado en el campo de batalla!' WHERE `ID`=67878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쇽스티크가 전장에 등장했습니다!', `MaleText_loc4`='夏克提克已经进入了战场！', `MaleText_loc5`='休斯席克已經進入了戰場!', `MaleText_loc7`='¡Shox''tik ha entrado en el campo de batalla!' WHERE `ID`=67879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움의 집중물이 전장에 등장했습니다!', `MaleText_loc4`='惊怖具象已经出现在战场上了！', `MaleText_loc5`='實體化的恐懼之煞已經出現在戰場上!', `MaleText_loc7`='¡La manifestación del terror ha aparecido en el campo de batalla!' WHERE `ID`=67880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n 님, 이제 우리는 약간 친해졌으니 제가 하나 알려 드릴게요. 이곳에 있는 주민들은 당신 농장을 멋지게 가꿔줄 수 있답니다. 하지만 그러려면 먼저 그들과 친구가 돼야 해요. 불행히도 당신은 이웃들을 돕거나 선물을 주기엔 경험이 너무 부족하답니다. 그러니 일단 강해지세요!', `FemaleText_loc4`='既然我们已经是熟人了，$n，那我就给你点提示吧。这附近的村民能帮你装扮农场，但你得先跟他们成为朋友才行。遗憾的是，你现在还无力帮助他们或赠送礼物，先把自己变强吧！', `FemaleText_loc5`='如今我們是熟識了，$n，讓我給你個小提示。這裡的人們能幫忙你將農場打理得很好，但你必須先成為朋友。不幸地，你還太嫩不能幫助他們或送禮，所以你得先變得更強壯!', `FemaleText_loc7`='Ahora que nos conocemos un poco mejor, $n, deja que te dé un consejo. La gente de los alrededores puede ayudarte a mejorar tu granja, pero antes tienen que hacerse amigos. Por desgracia, estás demasiado verde para ayudarles o hacerles regalos, ¡así que empieza por hacerte más fuerte!' WHERE `ID`=67881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n 님... 지나는 농사꾼 연합의 투표위원입니다... 그러니까 좋은 인상을 줘야겠지요. 안 그렇습니까?', `MaleText_loc4`='噢你好，$n……吉娜是阡陌客的表决成员，所以……试着给她留个好印象，好吗？', `MaleText_loc5`='喔嘿，$n...吉娜是一個有投票權的耕者成員，所以...讓她留下個好印象，好嗎?', `MaleText_loc7`='Ah, una cosa, $n... Gina es un miembro de los Labradores con derecho a voto, así que trata de causar buena impresión, ¿está bien?' WHERE `ID`=67882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 슈의 맹독에 중독되었습니다. 해독하십시오!', `MaleText_loc4`='你受到了许大师致命毒药的折磨。快帮自己解毒！', `MaleText_loc5`='你已經中了徐大師的致命毒藥。快為自己解毒!', `MaleText_loc7`='Te aflige el Veneno mortal del maestro Hsu. ¡Depúrate para eliminarlo!' WHERE `ID`=67883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 뭉뭉은 감동했다. 넌 아무런 대가도 바라지 않고 나를 도와줬거든. 그런 게 바로 진정한 농사꾼이 돼간다는 거야. 농장에서 나와 다시 만나자. 내가 표 줄게.', `MaleText_loc4`='蒙蒙对你印象深刻，$n。你不求回报地帮助我。那正是阡陌客的意义所在。我会去你的农场上找你。蒙蒙决定投你一票。', `MaleText_loc5`='芒芒很感動，$n。你幫了我卻不要求任何回報。那是身為一名耕者最重要的一點。我會回到你的農場和你碰面。芒芒會投你一票。', `MaleText_loc7`='Mung-Mung está impresionado, $n. Tú me ha ayudado sin pedir nada a kambio. Eso es lo ke es ser un Labrador. Yo te verá en tu granja. Mung-Mung ha decidido darte su voto.' WHERE `ID`=67884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 칼림도어처럼 망쳐 놓지는 못할 거다!', `MaleText_loc4`='渣滓们，休想像玷污卡利姆多那样毁掉这片土地！', `MaleText_loc5`='我不會讓你們這些敗類像在卡林多一樣污染這塊大陸!', `MaleText_loc7`='¡Tu escoria no destruirá esta tierra como profanó Kalimdor!' WHERE `ID`=67885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 이 양배추 덕분에 납득이 됐습니다. 양배추를 이 정도로 길러낼 수 있는 이라면 그게 누구든 농사꾼 연합으로 와야 합니다. 저는 윤에게 한 표를 주고 싶군요. 잠시 뒤에 당신 농장에서 저와 다시 만납시다.', `MaleText_loc4`='这些卷心菜说服了我，$n。能种出这种作物的人，理应是阡陌客的一员。我会为你和农夫老愚投上一票。待会儿在你农场上见。', `MaleText_loc5`='這些捲心菜說服我了，$n。任何可以種出這樣農作物的人都屬於耕者的一份子。我會投你和農夫尹一票。等等在你的農場見。', `MaleText_loc7`='Estas coles me han convencido, $n. Alguien que cultive productos como estos debe formar parte de los Labradores. Votaré por ti y por el grajero Yoon. Te veré en tu granja dentro de un rato.' WHERE `ID`=67886;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='툴툴대지 말고 어서 막대기를 잡아요!', `FemaleText_loc4`='噢，别再抱怨了，抓住棍子！', `FemaleText_loc5`='喔別再抱怨了，快抓住棍子!', `FemaleText_loc7`='¡Deja de quejarte y agarra el palo!' WHERE `ID`=67887;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='징징거리지 말아요! 내가 당신을 죽이기라도 하겠어요?!', `FemaleText_loc4`='这么多抱怨！你以为我要杀了你吗！', `FemaleText_loc5`='真愛發牢騷!你不會以為我想要殺了你吧!', `FemaleText_loc7`='¡Cuántos lloros! ¡Ni que estuviera intentando matarte!' WHERE `ID`=67888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남은 도와주려고 이러는 건데 불평만 하기예요?!', `FemaleText_loc4`='你没资格抱怨别人对你提供的帮助！', `FemaleText_loc5`='你沒資格抱怨你正得到的協助!', `FemaleText_loc7`='¡No estás en posición de quejarte de la ayuda que recibes!' WHERE `ID`=67889;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 나무에 계속 걸려 있고 싶으세요?!', `FemaleText_loc4`='你愿意继续卡在树上吗？！', `FemaleText_loc5`='你想要繼續困在樹上嗎?!', `FemaleText_loc7`='¡¿Prefieres quedarte atascado en el árbol?!' WHERE `ID`=67890;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 걸린 건 당신이 자초한 일이잖아요! 난 도와주려는 것뿐이라고요!', `FemaleText_loc4`='嘿，是你把自己卡在那的！我只是想帮你！', `FemaleText_loc5`='嘿，是你害你自己困在那裡的!我只是想要幫忙!', `FemaleText_loc7`='Oye, ¡te has quedado atascado tú solo! ¡Yo solo intento ayudar!' WHERE `ID`=67891;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자꾸 그러면 그냥 내버려두는 수가 있어요!', `FemaleText_loc4`='知道么，我其实可以让你自生自灭！', `FemaleText_loc5`='你知道，我大可以把你留在那上面!', `FemaleText_loc7`='¿Sabes que podría dejarte ahí arriba?' WHERE `ID`=67892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위와 돌에 대해 전문가인 이가 있다면, 그건 바로 드워프일 거요!', `MaleText_loc4`='在这世上要是存在岩石和石料专家，那就一定是矮人！', `MaleText_loc5`='如果說有誰是岩石和石頭的專家，那就是個矮人!', `MaleText_loc7`='Si hay expertos en rocas y piedras, ¡son los enanos!' WHERE `ID`=67893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라그나로스가 하이잘의 작은 생물들에게 영향을 미친 방식을 이해한다면, 그것들을 치유할 방식을 더 잘 이해하게 될 걸세.', `MaleText_loc4`='如果我们能弄清拉格纳罗斯是如何影响了海加尔的低等住民，也许就能想出更好的补救措施。', `MaleText_loc5`='如果我們能了解拉格納羅斯是如何影響了海加爾山較次等的居民，我們就可能更能了解如何修補它。', `MaleText_loc7`='Si comprendemos cómo ha afectado Ragnaros a los habitantes menores de Hyjal, comprenderemos mejor cómo repararlo.' WHERE `ID`=67894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 세상... 그리고 온 세상이 불타오를 것이오!', `MaleText_loc4`='你的世界……所有世界……都将燃烧！', `MaleText_loc5`='你們的世界...所有世界...將會燃燒!', `MaleText_loc7`='Tu mundo... todos los mundos... ¡arderán!' WHERE `ID`=67895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='채소를 재배하는 능력이 탁월하다면 그게 누구든 농사꾼 연합의 일원이 되어야 해. 맹해 빠진 내 손자가 뭐라고 하든 난 상관하지 않는단다! 하오한은 농부 윤에 대해 잘못 생각하고 있어. $n, 나는 윤에게 투표해야겠구나.', `FemaleText_loc4`='任何在园艺方面显示出如此高超天赋的人，都理应成为阡陌客的成员。我才不在乎我那浮躁的孙子说什么！郝瀚对农夫老愚的看法是错的。我投你一票，$n。', `FemaleText_loc5`='任何擁有如此園藝天賦之人都應該成為一名耕者。我才不在乎我那如野兔般愚蠢的孫子怎麼說!好漢對農夫尹的看法是錯的。你得到了我這一票，$n。', `FemaleText_loc7`='Alguien con semejante talento para las plantas tiene que ser un Labrador. ¡Me da igual lo que diga el cabeza de chorlito de mi nieto! Haohan se equivoca respecto al granjero Yoon. Tenéis mi voto, $n.' WHERE `ID`=67896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들의 시간으로 계산했을 때 수 세대에 걸쳐 이날을 준비해왔다오.', `MaleText_loc4`='我为了迎接这一天的到来，已经做了世世代代的准备。', `MaleText_loc5`='我為了這天的到來，已經準備了相當於你族人好幾世代的時間。', `MaleText_loc7`='Han pasado generaciones de tu especie mientras me preparaba para este día.' WHERE `ID`=67897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숲 속의 아름다운 꽃들조차 우리의 적이 됐어요...', `FemaleText_loc4`='就连林中可爱的花朵都与我们作对了……', `FemaleText_loc5`='就連森林中可愛的花朵也被轉而與我們對抗...', `FemaleText_loc7`='Hasta las preciosas flores del bosque se vuelven en nuestra contra...' WHERE `ID`=67898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보셨습니까?

후이가 녹옥 채석장의 비취에게 저주를 내려 저 괴물들로 변신시켰습니다.', `MaleText_loc4`='你看见没有？

仇灰诅咒了绿石采掘场的玉石，并把它变成了怪物。', `MaleText_loc5`='你看到了嗎?

穢詛咒了綠石採石場中的翠玉並將它變成了那些怪物。', `MaleText_loc7`='¿Viste eso?

Hui ha maldecido el jade de la Cantera Verdemar y lo ha transformado en esos monstruos.' WHERE `ID`=67899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 마을은 후이의 승낙 하에 건설되었지만, 그건 수 세대 전의 일이랍니다.', `FemaleText_loc4`='这座村庄是经仇灰同意后建造的，那是在很久以前了。', `FemaleText_loc5`='這座村子是在穢的同意下建城的，但那已經是好幾代以前的事了。', `FemaleText_loc7`='Esta aldea se construyó con el permiso de Hui, pero de eso hace muchas generaciones.' WHERE `ID`=67900;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='후이의 저주는 우리의 유명한 녹옥 맥주조차도 우리에게서 등을 돌리게 했어요!

그의 부하들이 저주의 영향을 받지 않은 아주 소량의 맥주마저도 훔쳐갔답니다.', `FemaleText_loc4`='就连著名的绿石佳酿，都被仇灰诅咒得跟我们作对！

他的仆从把未受影响的佳酿都偷走了。', `FemaleText_loc5`='穢的詛咒甚至讓一些我們有名的綠石酒對抗我們!

他的爪牙偷走了沒被影響的那一小部分。', `FemaleText_loc7`='¡La maldición de Hui ha vuelto hasta nuestro famoso brebaje de Verdemar en nuestra contra!

Sus esbirros han robado el poco brebaje que no se había visto afectado.' WHERE `ID`=67901;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더는 버틸 수 없다고 생각했답니다.

정말 감사해요!', `FemaleText_loc4`='我觉得自己已经无力对抗它们了。

真是太感谢你了！', `FemaleText_loc5`='我不認為我能再擋住他們多久。

我很感激你!', `FemaleText_loc7`='No creo que hubiera podido aguantar mucho más tiempo.

¡Se los agradezco!' WHERE `ID`=67902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후이가 쓴 땅의 마법이 키리의 비취 사자 조각상까지 살아 움직이게 만들었습니다!

그 사자 조각상은 아무도 모르는 곳으로 도망가버렸지요...', `MaleText_loc4`='仇灰的大地魔法甚至让齐理的玉狮雕像活了过来！

谁知道它跑到哪儿去了……', `MaleText_loc5`='穢的大地魔法甚至讓綺麗的翠玉獅雕像有了生命!

它不知道跑到哪裡去了...', `MaleText_loc7`='La magia de la tierra de Hui ha dado vida a la estatua del león de jade de Kiri.

Se ha marchado quién sabe adónde...' WHERE `ID`=67903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음. 쿤젠 호젠 놈들이 하오한 씨의 밭에서 말썽깨나 피우는 것 같군요. 우리가 도움을 줄 수 있을 겁니다.', `MaleText_loc4`='嗯，听起来昆森猢狲给泥爪先生添了不少麻烦。也许我们能帮得上忙。', `MaleText_loc5`='嗯嗯，聽起來崑真猴人對泥爪先生製造了許多麻煩。也許我們能幫得上忙。', `MaleText_loc7`='Mmm, parece que los hozen Kunzen están causando muchos problemas al señor Zarpa Fangosa. A lo mejor podemos echarle una mano.' WHERE `ID`=67904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신을 도울 |cFF298A08스라티크 일꾼|r을 소환합니다!', `MaleText_loc4`='%s召唤|cFF298A08瑟拉提克工虫|r前来帮忙！', `MaleText_loc5`='%s召喚|cFF298A08斯拉席克工人|r來協助他!', `MaleText_loc7`='¡%s invoca |cFF298A08trabajadores Sra''thik|r en su ayuda!' WHERE `ID`=67905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에서 다시 만나자고.', `MaleText_loc4`='我会在村里与你会面。', `MaleText_loc5`='我會回到村子和你碰面。', `MaleText_loc7`='Te veré en la aldea.' WHERE `ID`=67906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 독을 만들려면 시간이 더 필요합니다. 준비가 다 되면 알려 드리겠습니다.', `MaleText_loc4`='我需要更多时间准备混合，$n。好了会通知你的。', `MaleText_loc5`='我需要更多時間來調製混合物，$n。完成時我會讓你知道。', `MaleText_loc7`='Necesito más tiempo para preparar la mezcla, $n. Te avisaré cuando esté lista.' WHERE `ID`=67907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와준다는 게 뭔지 다시 한 번 생각해 봐! 그렇게 막대기를 휘두르면 위험하기만 하다고!', `MaleText_loc4`='你应该慎重考虑自己对帮助的定义，女士！你拿着那根棍子危险得很！', `MaleText_loc5`='你必須審慎地重新思考你對於幫助人的定義，小姐!你拿著那根棍子很危險!', `MaleText_loc7`='¡Tienes que replantearte el concepto de "ayudar", señora! ¡Eres un peligro con ese palo!' WHERE `ID`=67908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 보여주시고 싶은 겁니까, 킬루크?', `MaleText_loc4`='你想给我看什么，克尔鲁克？', `MaleText_loc5`='你想讓我看什麼，基爾魯克?', `MaleText_loc7`='¿Qué quieres enseñarme, Kil''ruk?', `FemaleText_loc1`='무엇을 보여주시고 싶은 건가요, 킬루크?', `FemaleText_loc4`='你想给我看什么，克尔鲁克？', `FemaleText_loc5`='你想讓我看什麼，基爾魯克?', `FemaleText_loc7`='¿Qué quieres enseñarme, Kil''ruk?' WHERE `ID`=67909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시베스 밑에 있는 방을 다시 보여주시겠습니까?', `MaleText_loc4`='你能再给我看看卡拉克西维斯下方的内室吗？', `MaleText_loc5`='你可以再讓我看一次卡拉西斐斯底下的密室嗎?', `MaleText_loc7`='¿Te importa volver a enseñarme la cámara bajo Klaxxi''vess?', `FemaleText_loc1`='클락시베스 밑에 있는 방을 다시 보여주시겠어요?', `FemaleText_loc4`='你能再给我看看卡拉克西维斯下方的内室吗？', `FemaleText_loc5`='你可以再讓我看一次卡拉西斐斯底下的密室嗎?', `FemaleText_loc7`='¿Te importa volver a enseñarme la cámara bajo Klaxxi''vess?' WHERE `ID`=67910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='킬루크와 함께 걸으시겠습니까?', `MaleText_loc4`='你确定要与克尔鲁克同行么？', `MaleText_loc5`='你確定你想和基爾魯克一起走走嗎?', `MaleText_loc7`='¿Seguro que quieres caminar con Kil''ruk?', `FemaleText_loc1`='킬루크와 함께 걸으시겠습니까?', `FemaleText_loc4`='你确定要与克尔鲁克同行么？', `FemaleText_loc5`='你確定你想和基爾魯克一起走走嗎?', `FemaleText_loc7`='¿Seguro que quieres caminar con Kil''ruk?' WHERE `ID`=67911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉우리는 안전하지만, 그 주변의 지역은 그렇지가 못합니다. 이제부터는 더 조심하십시오!', `MaleText_loc4`='虽然山峰很安全，但附近那些地方可不一定。多加小心！', `MaleText_loc5`='雖然山頂安全了，周圍的區域還是不安全。小心點!', `MaleText_loc7`='Aunque el pico es seguro, las zonas circundantes no lo son. ¡Ten más cuidado!' WHERE `ID`=67912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t %s|1이;가; 숨은 채로 |cFFFF0000|Hspell:131271|h[어둠 급습]|h|r을 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t %s躲了起来，准备|cFFFF0000|Hspell:131271|h[跃出暗影]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s躲藏起來並準備|cFFFF0000|Hspell:131271|h[暗影跳躍]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_druid_tigersroar.blp:20|t ¡%s se oculta y se prepara para ejecutar |cFFFF0000|Hspell:131271|h[Salto desde las Sombras]|h|r!' WHERE `ID`=67913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 목표물을 보지 못했습니다!', `MaleText_loc4`='%s看不见他的猎物！', `MaleText_loc5`='%s無法看見他的獵物!', `MaleText_loc7`='¡%s no ha podido ver a su presa!' WHERE `ID`=67914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우 카오 보급품 자루를 꼭 가져가십시오!', `MaleText_loc4`='记得拿上一袋悟道者补给品！', `MaleText_loc5`='記得要拿著你的武豪補給品!', `MaleText_loc7`='¡No te olvides la bolsa de suministros Wu Kao!', `FemaleText_loc1`='우 카오 보급품 자루를 꼭 가져가세요!', `FemaleText_loc4`='记得拿上一袋悟道者补给品！', `FemaleText_loc5`='記得要拿著你的武豪補給品!', `FemaleText_loc7`='¡No te olvides la bolsa de suministros Wu Kao!' WHERE `ID`=67915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지나! 이렇게 들러주실 줄은 몰랐습니다.', `MaleText_loc4`='嘿，吉娜！真是稀客啊。', `MaleText_loc5`='嘿，吉娜!我沒想到你會來。', `MaleText_loc7`='¡Hola, Gina! No te esperaba.' WHERE `ID`=67916;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저랑 같이 가요, $n 님. 농부 윤에게 가보고 싶어요.', `FemaleText_loc4`='随我走走吧，$n。我想去看看农夫老愚。', `FemaleText_loc5`='和我一起走走，$n。我想要去拜訪一下農夫尹。', `FemaleText_loc7`='Acompáñame, $n. Me gustaría hacerle una visita al granjero Yoon.' WHERE `ID`=67917;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 파를 구해주신 덕분에 제가 살았어요.', `FemaleText_loc4`='知道吗，真是多亏了你的那些葱。', `FemaleText_loc5`='你知道，你的那些青蔥幫了我一個大忙。', `FemaleText_loc7`='Me has salvado el pellejo con esas cebolletas, ¿sabes?' WHERE `ID`=67918;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요리사는 항상 신선한 채소를 찾는답니다. 당신 밭에서 자라나는 어떤 채소라도 요리 재료로 사용하거나 다른 요리사에게 팔 수 있어요.', `FemaleText_loc4`='厨师总在寻觅新鲜的蔬菜。不管你在农场上种了什么，都能用于烹饪，或是出售给其他厨师。', `FemaleText_loc5`='廚師們總是在找新鮮的蔬菜。任何你在農場種植的作物都可以用來烹飪，或賣給其他的廚師。', `FemaleText_loc7`='Los cocineros siempre buscan verduras frescas. Cualquier cosa que cultives en tu granja se puede cocinar o vender a otros cocineros.' WHERE `ID`=67919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='윤, 반가워요!', `FemaleText_loc4`='你好，农夫老愚！', `FemaleText_loc5`='嘿，農夫尹!', `FemaleText_loc7`='¡Hola, granjero Yoon!' WHERE `ID`=67920;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 이야기 들어보세요. 두 분께서 저를 많이 도와주셨으니까, 윤이 농사꾼 연합에 가입할 수 있도록 윤에게 투표할게요.', `FemaleText_loc4`='听着，鉴于你们俩帮了我这么大一个忙，我会投出第一票，帮你们加入阡陌客。', `FemaleText_loc5`='聽著，因為你們兩個人幫助了我。我會投下第一票來幫助你們加入耕者。', `FemaleText_loc7`='Mira, ya que se han portado tan bien al ayudarme, voy a ser la primera en votar a favor de su incorporación a los Labradores.' WHERE `ID`=67921;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='4개의 표를 더 얻어야 하지만, 금방 얻을 수 있을 거예요.', `FemaleText_loc4`='你们还得争取到另外四张选票才行，但迟早会有的。', `FemaleText_loc5`='你們還需要得到另外四票，但那得慢慢來。', `FemaleText_loc7`='Tendrán que conseguir otros cuatro votos, pero tiempo al tiempo.' WHERE `ID`=67922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자리를 잡고 난 뒤에 일을 하고 싶다면 언제든지 언덕골 시장에 들러주세요.', `FemaleText_loc4`='安顿下来吧，要是你想找工作，可以随时到市场上来。', `FemaleText_loc5`='讓你們自己適應一下，只要想找工作，隨時到市集這來。', `FemaleText_loc7`='Asiéntense y pasen por el mercado cuando busquen trabajo.' WHERE `ID`=67923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='일단 자리부터 잡으세요. 자신의 농장 일을 할 수는 있겠지만, 언덕골 시장에 있는 주민들을 돕기에는 경험이 너무 부족해 보이는 것 같아요. 판다리아를 더 둘러보고 난뒤, 더 강해졌을 때 제게 꼭 다시 들러주세요.', `FemaleText_loc4`='先安顿下来吧。你可以在自己的农场上耕种，但由于经验不足，你能做的恐怕也仅限于此。等你见识了潘达利亚更多的风土人情后，一定要再来找我。', `FemaleText_loc5`='首先讓你們自己適應一下。你們將能夠栽植你們的農地，但我擔心你的經驗還是不足以幫助市集裡的人們。等到見識過潘達利亞的其他部分，別忘了到這來。', `FemaleText_loc7`='Asentaos antes. Podrás cultivar los campos, pero me temo que todavía te falta experiencia para hacer más cosas. Ven a vernos cuando conozcas mejor las tierras de Pandaria.' WHERE `ID`=67924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='심장지에 오신 것을 환영해요!', `FemaleText_loc4`='欢迎来到汇风岭！', `FemaleText_loc5`='歡迎來到中央平原!', `FemaleText_loc7`='¡Te doy la bienvenida a Los Cultivos Florecientes!' WHERE `ID`=67925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이!', `MaleText_loc4`='懦夫！', `MaleText_loc5`='懦夫!', `MaleText_loc7`='¡Cobarde!' WHERE `ID`=67926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 예전에 들었던 그 조련사겠군. 말해보시오. 지는 게 두렵소?', `MaleText_loc4`='你一定就是我听说的那位训练师了。说说，你害怕失败吗？', `MaleText_loc5`='你一定就是我聽說的訓練師了。告訴我，你害怕被打敗嗎?', `MaleText_loc7`='Debes de ser $gese entrenador del:esa entrenadora de la; que tanto he oído hablar. Dime, ¿temes la derrota?' WHERE `ID`=67927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용감한 시도였지만, 그 정도로는 부족합니다. 다시 도전할 준비가 되면 말씀하십시오.', `MaleText_loc4`='一次勇敢的尝试，可还远远不够。等你准备好重试之后，再来与我交谈。', `MaleText_loc5`='很英勇的成就，但那還不夠。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Un intento digno, pero no es suficiente. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=67928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='클락시가 말했다. 여제는 패망해야 한다.', `MaleText_loc4`='卡拉克西说话了。女皇必亡。', `MaleText_loc5`='卡拉西已經宣布了。女皇必須死。', `MaleText_loc7`='Los Klaxxi han hablado. La Emperatriz debe caer.' WHERE `ID`=67929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작합시다.', `MaleText_loc4`='我们开始吧。', `MaleText_loc5`='我們開始吧。', `MaleText_loc7`='Empecemos.', `FemaleText_loc1`='시작하시죠.', `FemaleText_loc4`='我们开始吧。', `FemaleText_loc5`='我們開始吧。', `FemaleText_loc7`='Empecemos.' WHERE `ID`=67930;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='온갖 기이한 생물들이... 하늘에서 떨어지고 있어요!', `FemaleText_loc4`='各种各样的诡异生物……从天而降！', `FemaleText_loc5`='各種各樣的奇怪生物就這樣...從天上掉下來!', `FemaleText_loc7`='¡Todo tipo de criaturas extrañas caen del cielo!' WHERE `ID`=67931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까 뭉뭉. 하오한 씨의 밭일은 어떻게 돼가고 있습니까?', `MaleText_loc4`='你好，蒙蒙。泥爪先生的农场上一切都好吗？', `MaleText_loc5`='哈囉，芒芒。泥爪先生的農場情況如何啊?', `MaleText_loc7`='Hola, Mung-Mung. ¿Qué tal va todo en la granja del señor Zarpa Fangosa?' WHERE `ID`=67932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, 윤! 나야. 뭉뭉!', `MaleText_loc4`='嘿，小愚！是我啊，蒙蒙！', `MaleText_loc5`='嘿，小尹!是我啊，芒芒!', `MaleText_loc7`='¡Hola, Yoonie! ¡Es yo, Mung-Mung!' WHERE `ID`=67933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 저기 길을 따라오는 호젠이 뭉뭉 아닙니까?', `MaleText_loc4`='嘿，沿路走来的不是蒙蒙吗？', `MaleText_loc5`='嘿，在路上走過來的那不是芒芒嗎?', `MaleText_loc7`='Oye, ¿no es Mung-Mung ese que sube por el camino?' WHERE `ID`=67934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끔찍한데. 하오한 씨한테 내가 이렇게 말했다고 하진 마. 사방에 토깽 놈들 천지야. 채소들이 자라지를 못하고 있어. 그리고 뭔가가 수확물을 계속 먹어치운다.', `MaleText_loc4`='太可怕了，但别告诉他我说过这样的话。兔妖到处肆虐。庄稼也长不出来。还有东西在不断地吞吃着收成。', `MaleText_loc5`='很糟糕，但別告訴他我這麼說。兔妖到處跑來跑去。農作物長不出來。然後有東西一直把收成給吃掉。', `MaleText_loc7`='Fatal, pero tú no le dice que yo te ha dicho. Mures por todas partes. Los cultivos no krecen. Y hay algo que no deja de komer la kosecha.' WHERE `ID`=67935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 네 농장은 꽤 괜찮아 보인다. 마을 주민들과 친구가 되면 더 멋진 농장을 꾸밀 수 있는 선물을 줄 거야.', `MaleText_loc4`='但你的农场看起来还不错。知道吗，要是你能跟这里的人交上朋友，他们也许会给你些好东西，更让农场增色。', `MaleText_loc5`='但是你的農場看來挺不錯的。你知道如果你能和附近的人們交朋友，他們也許能給你東西讓你的農場更棒。', `MaleText_loc7`='Pero tu granja tiene buena pinta. Si tú te hace amigos por aquí, a lo mejor te ayudan a mejorarla aún más.' WHERE `ID`=67936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 여기 좀 봐! 네 농장 정말 멋지다. 마을에서 친구를 좀 사귄 것 같은데!', `MaleText_loc4`='天哪，看看这地方！你的农场太漂亮了。看来你可没少交朋友！', `MaleText_loc5`='壞廢渣，看看這地方!你有個很棒的農場啊。看來你在這附近交了不少朋友!', `MaleText_loc7`='¡Jurungo! ¡Mira este sitio! Tú tiene una granja estupenda. Parece que ke tú ha hecho amigos.' WHERE `ID`=67937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 그 당근 때문에 고맙다고 하러 잠깐 들렀다.', `MaleText_loc4`='不管怎样，我只是来为那些胡萝卜向你道谢。', `MaleText_loc5`='總之，我來拜訪是為了那些胡蘿蔔向你道謝。', `MaleText_loc7`='Venía a darte las gracias por las zanahorias.' WHERE `ID`=67938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당근이 정말 츄릅아삭해서 하오한 씨는 당근 농사가 정말 잘됐다고 생각하고 있다! 하하하!', `MaleText_loc4`='它们真是脆爽，郝瀚觉得那简直是他最棒的作物！哈哈！', `MaleText_loc5`='它們真的很脆嫩，好漢還覺得它們是他有史以來最棒的農作物!哈哈!', `MaleText_loc7`='Eran muy crujientes. ¡Haohan se pensó ke eran su mejor kosecha! ¡Ja, ja!' WHERE `ID`=67939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윤, 이제 보니 나쁜 판다렌 아니구나. 여기 내 표를 줄게.', `MaleText_loc4`='你干得不错嘛，小愚。这是我的选票。', `MaleText_loc5`='你還不賴，小尹。這是我的一票。', `MaleText_loc7`='Tú lo vale, Yoonie. Te doy mi voto.' WHERE `ID`=67940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만나!', `MaleText_loc4`='回头见！', `MaleText_loc5`='等會見!', `MaleText_loc7`='¡Hasta luego!' WHERE `ID`=67941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두들 와 주셔서 감사해요!', `FemaleText_loc4`='谢谢大家能来！', `FemaleText_loc5`='謝謝你們大家的參與!', `FemaleText_loc7`='¡Gracias a todos por venir!' WHERE `ID`=67942;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모든 세대에는 리우 랑과 같은 공상가들이 태어나지요.', `FemaleText_loc4`='梦想家代代不绝——如刘浪一般的梦想家。', `FemaleText_loc5`='每一代都會有些夢旅者誕生 - 像劉浪一樣的夢旅者。', `FemaleText_loc7`='En cada generación nacen soñadores... soñadores como Liu Lang.' WHERE `ID`=67943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 꿈은 뭔가요? 절대로 빼앗기지 마세요!', `FemaleText_loc4`='你的梦想又是什么？别让任何人夺走它！', `FemaleText_loc5`='你的夢想是什麼?別讓任何人奪走它!', `FemaleText_loc7`='¿Cuál es tu sueño? ¡No dejes que nadie te lo arrebate!' WHERE `ID`=67944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음에 품는 일은 일어납니다. 공상가가 세상을 변화시키지요.', `FemaleText_loc4`='珍藏于心，努力实现。梦想家有着改变世界的力量。', `FemaleText_loc5`='將它牢牢記在心中，並讓它實現。夢旅者能改變世界。', `FemaleText_loc7`='Guárdalo en tu corazón y hazlo realidad. Los soñadores pueden cambiar el mundo.' WHERE `ID`=67945;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분 모두에게 주학 님의 축복이 있기를. 좋은 밤 보내세요!', `FemaleText_loc4`='朱鹤会保佑你们所有人。晚安！', `FemaleText_loc5`='紅鶴祝福你們所有人。晚安!', `FemaleText_loc7`='Que la Grulla Roja os bendiga. ¡Buenas noches!' WHERE `ID`=67946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 저기 보십시오. 누가 길을 따라 오고 있군요. 안녕하십니까아, 펑! 만나서 반갑습니다!', `MaleText_loc4`='快看，有人走过来了。你好呀，农夫老方！很高兴见到你！', `MaleText_loc5`='嘿，看啊，路上有人走過來了。哈囉，農夫老豐!很高興見到你!', `MaleText_loc7`='Mira, alguien sube por el camino. ¡Buenas, granjero Fung! ¡Me alegro de verte!' WHERE `ID`=67947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 만났군, 윤. 내가 직접 와서 자네 농장을 보고 싶었다네.', `MaleText_loc4`='你好，农夫老愚。我得亲自前来看看你的农场。', `MaleText_loc5`='你好啊，農夫尹。我得親自來拜訪並看看你的農場。', `MaleText_loc7`='Hola, granjero Yoon. Quería ver tu granja con mis propios ojos.' WHERE `ID`=67948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_polearm_2h_mantid_01.blp:20|t%s|1이;가; |cFFFF0000|Hspell:131320|h[칼날 강화]|h|r를 시전합니다. 도망치십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_polearm_2h_mantid_01.blp:20|t%s施放了|cFFFF0000|Hspell:131320|h[利刃灌能]|h|r，快跑！', `MaleText_loc5`='|TInterface\\Icons\\inv_polearm_2h_mantid_01.blp:20|t%s施放|cFFFF0000|Hspell:131320|h[強化刀刃]|h|r，快跑!', `MaleText_loc7`='|TInterfaceIconsinv_polearm_2h_mantid_01.blp:20|t%s lanza |cFFFF0000|Hspell:131320|h[Potenciar filos]|h|r. ¡Corre!' WHERE `ID`=67949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 허름하지는 않군. 저쪽에도 밭으로 만들 땅이 더 있어 보이는걸.', `MaleText_loc4`='不算太糟。看来你在那边还能多耕出几块地来。', `MaleText_loc5`='還不錯。看來你那邊還有空間能開拓更多農地。', `MaleText_loc7`='No está mal. Y hasta parece que tienes sitio para más campos.' WHERE `ID`=67950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼으로서 알려줄 게 하나 있네. 언덕골 시장에서는 농사를 더 잘 짓게 해줄 물품들을 많이 판다네. 지나 머드클로는 농기구를 팔고, 상인 그린필드는 씨앗을 팔지.', `MaleText_loc4`='让同是农夫的我给你个建议。在半山市集里可以买到各种各样的升级用品。吉娜·泥爪出售工具，商人绿野贩卖种子。', `MaleText_loc5`='給你個農夫之間的小秘訣。你能在半丘市集買到許多升級。吉娜·泥爪有賣工具，而商人青田有賣種子。', `MaleText_loc7`='Te voy a dar un consejo, de granjero a granjero. En el Mercado del Alcor hay un montón de mejoras a la venta. Fina Zarpa Fangosa vende herramientas y el mercader Campo Fértil vende semillas.' WHERE `ID`=67951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐 어쨌든, 양배추 때문에 고맙다고 말하러 왔다네. 나는 그것보다 더 잘 키우지는 못하겠더라고!', `MaleText_loc4`='不论如何，我只是来为那些卷心菜向你致谢。比我种的还要好！', `MaleText_loc5`='總之，我來拜訪是為了那些捲心菜向你道謝。我自己也種不出更棒的了!', `MaleText_loc7`='Pero bueno, he venido para agradecerte las coles. ¡Yo mismo no las habría cultivado mejores!' WHERE `ID`=67952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실, 채소를 이 정도로 완벽하게 길러낼 수 있는 이라면 누구든 농사꾼 연합에 들어와야 하네. 그래서 내가 자네에게 표를 주는 걸세.', `MaleText_loc4`='事实上，任何能种出这种完美蔬菜的人都应该成为阡陌客，这正是我要投票支持你的原因。', `MaleText_loc5`='事實上，任何能種出這麼完美蔬菜的人都應該成為耕者，這也是我會投票贊成你加入的原因。', `MaleText_loc7`='De hecho, cualquiera que cultive verduras tan perfectas debe ser un Labrador, así que votaré a tu favor.' WHERE `ID`=67953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 보아 하니 이젠 두 표만 더 얻으면 되겠는데!', `MaleText_loc4`='嘿，看来你只要再争取到两张赞成票就行了！', `MaleText_loc5`='嘿，看來你只需要再2多兩票就行了!', `MaleText_loc7`='Oye, ¡parece que solo te quedan dos votos!' WHERE `ID`=67954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나나 머드클로와 하오한 머드클로에게 자네의 실력을 증명해 보여야만 하네. 그 둘을 설득하기가 쉽지는 않을 테지만, 자네라면 할 수 있을 걸세.', `MaleText_loc4`='你得向娜娜·泥爪和郝瀚·泥爪证明自己。这两位泥爪家族的成员可不好说话，但我相信你能办到。', `MaleText_loc5`='你必須向娜娜和好漢·泥爪證明你自己。那兩個泥爪可不太好說服，但我覺得你能辦到。', `MaleText_loc7`='Tendrás que convencer a Nana y Haohan Zarpa Fangosa. Serán duros de ablandar, pero creo que tú puedes hacerlo.' WHERE `ID`=67955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 또 만나세나.', `MaleText_loc4`='回头见。', `MaleText_loc5`='再見啦。', `MaleText_loc7`='Nos vemos.' WHERE `ID`=67956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 동안 마음껏 즐기십시오. 평온의 봉우리에서 보는 쿤라이 봉우리는 정말 장관이랍니다.', `MaleText_loc4`='趁你在这里，别忘了四处看看。在晴日峰上能饱览昆莱山的美景。', `MaleText_loc5`='當你在這裡時別忘了到處看看。在寂靜峰能看到崑萊峰的美麗景色。', `MaleText_loc7`='No olvides disfrutar del paisaje mientras estás aquí. El Pico de la Serenidad tiene unas vistas preciosas de la Cima Kun-Lai.' WHERE `ID`=67957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에는 여러 가지 공예의 대가들이 있습니다. 여행 중에 쓸 보급품이 필요하다면 그들이 도와줄 수 있을 겁니다.', `MaleText_loc4`='你在这里可以找到几位精通各类手艺的匠师。要是你在旅途中需要任何补给品，可以去他们那里采购。', `MaleText_loc5`='在這裡，你能找到我們幾個專精於許多不同工藝的人。如果在你旅途上需要任何補給品，他們也許幫得上忙。', `MaleText_loc7`='Aquí encontrarás a varios monjes que han dominado el arte de distintas técnicas. Si necesitas suministros para tu viaje, seguramente podrán ayudarte.' WHERE `ID`=67958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 박살내려면 어서 재집결해야 하네.', `MaleText_loc4`='要是我们希望消灭联盟，就得尽快重整部队了。', `MaleText_loc5`='如果我們希望能摧毀聯盟，我們就得快點重整隊伍。', `MaleText_loc7`='Tendremos que reagruparnos rápidamente para acabar con la Alianza.' WHERE `ID`=67959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 훈련장입니다. 훈련은 대부분 여기서 진행되지요. 오시지요. 당신을 가르칠 사부님들을 소개해 드리겠습니다.', `MaleText_loc4`='这里是训练场，你大部分训练都将在这里进行。来吧，让我为你引荐几位大师，他们将对你传授本领。', `MaleText_loc5`='這裡是訓練場，你們大部分的人都會在這裡受訓。跟我來，我會為你介紹負責指導你的大師們。', `MaleText_loc7`='Este es el Campo de Entrenamiento, donde tendrá lugar el grueso de tu instrucción. Ven, quiero presentarte a los maestros con los que te entrenarás.' WHERE `ID`=67960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 키스테인 사부님이십니다. 안개의 힘을 써서 아군을 돕는 데 능하시지요.', `MaleText_loc4`='这位是吉斯坦大师，她是引导迷雾的专家，能为自己和盟友提供帮助。', `MaleText_loc5`='這位是金士坦大師，她是引導迷霧來協助她與她盟友之技藝的大師。', `MaleText_loc7`='Esta es la maestra Kistane, una experta en la canalización de la niebla para ayudar a sus aliados.' WHERE `ID`=67961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 우 사부님이십니다. 집요한 공격을 막아내는 데 특히 능하시지요.', `MaleText_loc4`='这位是吴大师。她精通防御，能化解持久的攻击。', `MaleText_loc5`='這位是吳大師。她專精於抵禦持續的攻擊。', `MaleText_loc7`='Esta es la maestra Woo. Se especializa en la defensa contra ataques persistentes.' WHERE `ID`=67962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 윤 사부님이십니다. 전투 중에 강력하고 집중적인 치유 주문을 사용해 체력을 관리하는 데 능하시지요.', `MaleText_loc4`='这位是尹大师。他善于使用强大专注的治疗技能，令自己在战斗中免于殒命。', `MaleText_loc5`='這位是尹大師。他對於在戰鬥中使用強力，且集中的治療來讓他自己在戰場上屹立不倒。', `MaleText_loc7`='Este es el maestro Yoon. Está versado en el uso de sanación centrada y poderosa para mantenerse en el combate.' WHERE `ID`=67963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 쳉 사부님이십니다. 움직이면서 싸우는 데 도가 트셨지요.', `MaleText_loc4`='这位是程大师。她掌握着行间战的高超战技。', `MaleText_loc5`='這位是程大師。她精通在戰鬥時的移動技巧。', `MaleText_loc7`='Esta es la maestra Cheng. Ha dominado el arte de luchar en movimiento.' WHERE `ID`=67964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 아이고... 나나 머드클로 할머님 아시닙니까! 이렇게 직접 와주실 줄은 정말 몰랐습니다!', `MaleText_loc4`='你——你——你是——娜娜·泥爪！我从——从没想过女——女——女族长会大驾光临！', `MaleText_loc5`='妳-妳-妳是娜-娜-娜娜·泥爪!我從-從來沒想到女-女-女總管會親自來拜訪我!', `MaleText_loc7`='¡E-eres N-N-Nana Zarpa Fangosa! ¡N-nunca pensé que me visitaría la matrona en persona!' WHERE `ID`=67965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 창 사부님이십니다. 명상의 달인으로서, 주위에서 무슨 일이 일어나는지 감지하는 능력이 있으시지요.', `MaleText_loc4`='这位是曾大师。他精通冥想，并对发生在身边的一切有着敏锐的感知力。', `MaleText_loc5`='這位是曾大師。他是位冥想大師，也是一位能夠感知他周遭環境變化的大師。', `MaleText_loc7`='Este es el maestro Tsang. Es un experto en la meditación y la percepción de todo lo que le rodea.' WHERE `ID`=67966;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 직접 와서 내 눈으로 늙은 윤의 손자를 보고 싶었단다.', `FemaleText_loc4`='我得亲自前来看看老老愚的孙儿。', `FemaleText_loc5`='我必須以我自己的雙眼來看看老尹的孩子。', `FemaleText_loc7`='Quería conocer personalmente al cachorro del viejo Yoon.' WHERE `ID`=67967;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 늙은 윤과 아주 친했거든. 그가 저세상으로 갔을 땐 정말 슬펐단다.', `FemaleText_loc4`='我跟你祖父是老相识了。他过世时，我悲伤不已。', `FemaleText_loc5`='我和你的爺爺很熟。我很遺憾他過世了。', `FemaleText_loc7`='Conocía muy bien a tu abuelo. Siento mucho su pérdida.' WHERE `ID`=67968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있는 둘을 보니 늙은 윤 생각이 나네...', `FemaleText_loc4`='知道吗，你们两个又让我想起他来了。', `FemaleText_loc5`='你知道，你們兩個人讓我回想起他。', `FemaleText_loc7`='Los dos me recordáis a él, ¿lo sabéis?' WHERE `ID`=67969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희는 농사 경험이 별로 없는데도 이 땅을 계속 갈 정도로 완고하더구나.', `FemaleText_loc4`='在没有太多经验的情况下，你却还在坚持犁地，真是固执。', `FemaleText_loc5`='你們頑固到就算經驗不足，也還是一直在這片土壤上耕作。', `FemaleText_loc7`='Han sido lo bastante testarudos como para seguir labrando a pesar de su falta de experiencia.' WHERE `ID`=67970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 내 손자인 하오한과도 맞설 정도로 용감했지.', `FemaleText_loc4`='敢于对抗我的孙子郝瀚，真是勇敢。', `FemaleText_loc5`='你們勇敢到能面對我的孫子，好漢。', `FemaleText_loc7`='Habéis sido lo bastante valientes para plantarle cara a mi nieto, Haohan.' WHERE `ID`=67971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 너희는 맛 좋은 채소와 과일을 기르는 데 꽤 훌륭한 재능을 보여줬단다.', `FemaleText_loc4`='而且你们两个还种出了美味的水果和蔬菜，展现出了过人的天赋。', `FemaleText_loc5`='而且你們兩個人也展現了種出美味水果與蔬菜的本領。', `FemaleText_loc7`='Y habéis demostrado una gran habilidad a la hora de cultivar frutas y verduras suculentas.' WHERE `ID`=67972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이분은 슈 사부님이십니다. 태양 아래 거의 모든 무기를 능히 다루시지요.', `MaleText_loc4`='这位是许大师。他十八般兵器样样精通，普天之下几乎没有任何武器能难得倒他。', `MaleText_loc5`='這位是徐大師。他專精於使用所有種類的武器，且對於使用幾乎世上任何武器都非常熟練。', `MaleText_loc7`='Este es el maestro Hsu. Se especializa en el uso de todo tipo de armamento; sabe utilizar prácticamente todas las armas del mundo con gran pericia.' WHERE `ID`=67973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 이유로 너희는 내 존중과 감사, 그리고 표를 얻은 거란다. 정말 훌륭하구나.', `FemaleText_loc4`='因此，你赢得了我的尊重，我的感谢，还有我的选票。干得好。', `FemaleText_loc5`='正因如此，你們贏得了我的尊敬，我的感激，和我的一票。做得好。', `FemaleText_loc7`='Por todo ello, os habéis ganado mi respeto, mi gratitud, y mi voto. Felicidades.' WHERE `ID`=67974;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그리고 농부 윤.', `FemaleText_loc4`='噢，还有农夫老愚。', `FemaleText_loc5`='喔，還有一點，農夫尹。', `FemaleText_loc7`='Ah, una cosa más, granjero Yoon.' WHERE `ID`=67975;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늙은 윤이 너를 아주 자랑스러워할 거야.', `FemaleText_loc4`='相信你爷爷一定会为你感到无比骄傲。', `FemaleText_loc5`='我相信你的爺爺會以你為榮。', `FemaleText_loc7`='Creo que tu abuelo estaría muy orgulloso de ti.' WHERE `ID`=67976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막으로, 이분은 쳉 사부님이십니다. 빠른 반응과 움직임이 특기로, 당신이 훈련을 시작하도록 도와주실 것입니다.', `MaleText_loc4`='最后要介绍的是程大师。程大师专攻反应和速度，会帮你开始你的训练。', `MaleText_loc5`='最後這位是程大師。程大師專研反應能力與迅捷的動作，並且會幫助你開始你的訓練。', `MaleText_loc7`='Y este, por último, es el maestro Cheng. El maestro Cheng se centra en los reflejos y en los movimientos ágiles, y será quien dé comienzo a tu entrenamiento.' WHERE `ID`=67977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼, 전 이만 가야겠군요. 훈련에 행운이 따르길 빕니다.', `MaleText_loc4`='那么，我得走了。祝你训练顺利。', `MaleText_loc5`='就這樣，我必須離開了。祝你訓練順利。', `MaleText_loc7`='Ahora debo marcharme. Buena suerte con tu entrenamiento.' WHERE `ID`=67978;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 너무 오랫동안 머물러서는 안 돼요, $c님.', `FemaleText_loc4`='我们只该在需要时才继续留在这里，$c。', `FemaleText_loc5`='我們應該只在必要時才待在這裡，$c。', `FemaleText_loc7`='No deberíamos quedarnos aquí más tiempo de lo necesario, $c.' WHERE `ID`=67979;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 그래도 꿀술은 계속 마실 수 있을 테니까요!', `FemaleText_loc4`='那个，至少蜜酒是不缺啦！', `FemaleText_loc5`='嗯，至少總是會有更多甘露酒!', `FemaleText_loc7`='¡Bueno, siempre nos quedará la birramiel!' WHERE `ID`=67980;
