UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영합니다. 시작할 준비가 되면 제게 말씀하십시오.', `MaleText_loc4`='欢迎。等你准备好开始时，就来与我交谈。', `MaleText_loc5`='歡迎。當你準備好開始時來跟我說。', `MaleText_loc7`='Hola. Habla conmigo cuando quieras empezar.' WHERE `ID`=67991;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 분은 온 몸에 성한 곳이 없어요... 상처가 너무 끔찍해요! 아무래도 가망이 없을 것 같아요.', `FemaleText_loc4`='她狠狠摔了一跤。伤势严重！我一直都叫不醒她。', `FemaleText_loc5`='她摔得相當嚴重，造成的傷害很嚇人!我一直沒辦法喚醒她。', `FemaleText_loc7`='Se ha dado un buen golpe. ¡Los daños son terribles! No he sido capaz de despertarla.' WHERE `ID`=67992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 추락 전에도 이런 모습이었다는 말인가요?!', `FemaleText_loc4`='噢！你是说，她在意外发生前就是这个样子的？！', `FemaleText_loc5`='喔!你的意思是她在墜落前就已經是這樣了?!', `FemaleText_loc7`='¿Qué? ¡¿Me estás diciendo que ya tenía ese aspecto antes del accidente?!' WHERE `ID`=67993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='평온의 봉우리에 잘 오셨습니다, $n 님. 제가 도와드릴 일이라도?', `MaleText_loc4`='欢迎来到晴日峰，$n。需要什么帮助？', `MaleText_loc5`='歡迎來到寂靜峰，$n。我能幫你什麼忙嗎?', `MaleText_loc7`='Te doy la bienvenida al Pico de la Serenidad. ¿En qué puedo ayudarte?' WHERE `ID`=67994;
