UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 됐어요! 새로 태어난 듯한 기분일 거예요... 아마도요...', `FemaleText_loc4`='好了！就像是没受过伤一样……吧……', `FemaleText_loc5`='就讓我們看看吧!跟新的一樣...我想啦...', `FemaleText_loc7`='¡Ya está! Como nueva. Bueno... es un decir.' WHERE `ID`=67997;
