UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 조수가 자네를 쳉 사부에게 데려다줄 걸세. 행운을 비네!', `MaleText_loc4`='我的助手会带你去见程大师。祝你好运！', `MaleText_loc5`='我的助手會帶你去找程大師。祝你好運!', `MaleText_loc7`='Mi ayudante te llevará hasta el maestro Cheng. ¡Buena suerte!' WHERE `ID`=68001;
