UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 안 될거야! 지금 만나러 가요, 아빠!', `MaleText_loc4`='我们肯定搞不定的！我马上就来见你了，老爹！', `MaleText_loc5`='我們撐不下去了!我馬上就要去找你了，老爸!', `MaleText_loc7`='¡Vamos a morir! ¡Pronto me reuniré contigo, papá!' WHERE `ID`=68018;
