UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 됐다. 전 비행기는 복귀하라. 지상 전투 준비!', `MaleText_loc4`='够了——全军回报。准备地面进攻。', `MaleText_loc5`='這樣夠了-全體空軍，返航。準備地面突襲。', `MaleText_loc7`='Es suficiente. Que vuelvan todas las unidades. Prepárense para el asalto terrestre.', `FemaleText_loc1`='이제 됐다. 전 비행기는 복귀하라. 지상 전투 준비!', `FemaleText_loc4`='够了——全军回报。准备地面进攻。', `FemaleText_loc5`='這樣夠了-全體空軍，返航。準備地面突襲。', `FemaleText_loc7`='Es suficiente. Que vuelvan todas las unidades. Prepárense para el asalto terrestre.' WHERE `ID`=68020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통을 들고 가는 걸 도와드리겠습니다. 혹시 마법처럼 당신 가방 속에 쏙 들어갈 거라고 생각했습니까?', `MaleText_loc4`='我会帮你搬桶。还是说，你觉得那些桶会魔法般地钻进你的背包里？', `MaleText_loc5`='我會幫你拿桶子。還是你認為它們能神奇地放入你的背包中?', `MaleText_loc7`='Te ayudaré a llevar los barriles. ¿Acaso esperabas que cupieran en tus bolsas por arte de magia?' WHERE `ID`=68021;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기함과의 통신이 여기서 끊어졌다. 뭔가 보이나?', `FemaleText_loc4`='旗舰最后报告的位置就在下方。你能看见什么吗？', `FemaleText_loc5`='旗艦最後回報的地點在這下面。有看到什麼嗎?', `FemaleText_loc7`='La última posición conocida del buque insignia estaba ahí abajo. ¿Pueden ver algo?' WHERE `ID`=68022;
