UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀술을 더 찾아낼 수 있기를 바랐습니다만, 그냥 저 혼자서 찾아봐야 할 것 같군요. 도움이 더 필요하면 말씀하십시오!', `MaleText_loc4`='我真希望能找到更多蜜酒。我想我会试着自己去找。如果你需要更多帮助，就告诉我一声！', `MaleText_loc5`='我真的很希望能找到更多甘露酒。我猜我只能靠自己去找了。如果你還需幫忙就來找我!', `MaleText_loc7`='Esperaba encontrar más birramiel. Voy a tener que arreglármelas solo. ¡Avísame si necesitas más ayuda!' WHERE `ID`=68084;
