UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너를 무서워할 것 같아? 나는 오닉시아하고도 싸웠다고!', `MaleText_loc4`='你以为我会怕你？我面对过奥妮克希亚！', `MaleText_loc5`='你認為我會怕你嗎?我面對過奧妮克希亞!', `MaleText_loc7`='¿Crees que me das miedo? ¡Me he enfrentado a Onyxia!' WHERE `ID`=68104;
