UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오닉시아의 알둥지에 들어오면 이렇게 되는 거야!', `MaleText_loc4`='进入巢穴就会遇到那样的事情！', `MaleText_loc5`='這就是你進入幼龍坑的下場!', `MaleText_loc7`='¡Eso es lo que pasa cuando entras en la guarida de crías!' WHERE `ID`=68108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 통쯤이야! 저는 키가 당신 무릎만큼도 안 되는 어린 꼬마였을 때부터 술 한 통을 쉽게 들고 다녔습니다!', `MaleText_loc4`='一桶？！我牙牙学语时就能轻而易举地搬起一桶，那时我才跟你膝盖一样高！', `MaleText_loc5`='一桶酒?在我還小的時候就能輕鬆地扛著一桶酒，那時候我還只比你的膝蓋高一點點而已!', `MaleText_loc7`='¡¿Un barril?! Ya llevaba un barril sin problemas cuando era un cachorro que apenas te llegaría a la rodilla.' WHERE `ID`=68109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무겁지만 더 들 수 있습니다! 계속 갑시다!', `MaleText_loc4`='好重，可我还能扛得动更多！再来！', `MaleText_loc5`='很重，但我還能扛更多!繼續!', `MaleText_loc7`='Pesa, ¡pero puedo sostener más! ¡Sigue!' WHERE `ID`=68110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 제 힘을 과대평가한 모양입니다...', `MaleText_loc4`='我也许高估了自己的力量……', `MaleText_loc5`='我可能高估了我自己的力量...', `MaleText_loc7`='Es posible que haya sobrevalorado mi fuerza...' WHERE `ID`=68111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 그만, 여기까지가 제 한계입니다! 정말 힘든 일이군요!', `MaleText_loc4`='够了，这是我的极限了！这可真累人！', `MaleText_loc5`='好了，這是我的極限了!這搬起來還真吃力!', `MaleText_loc7`='¡Ya está! ¡He llegado al límite! ¡Menuda carga!' WHERE `ID`=68112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 끝장나다니!', `MaleText_loc4`='我精疲力尽了！', `MaleText_loc5`='我被徹底打敗了!', `MaleText_loc7`='¡Me has aplastado!' WHERE `ID`=68113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움은 시간 낭비입니다. 어떻게 그렇게 내내 싸우기만 합니까? 작은 일에 기뻐하고 즐길 시간이 있기나 합니까?', `MaleText_loc4`='战斗简直是浪费生命。你们这些人怎么整天打打杀杀的？什么时候才能让自己享受简简单单的快意人生？', `MaleText_loc5`='這所有的戰鬥真是浪費。你們是怎麼一直戰鬥下去的?你們什麼時候有空能慶祝和享受簡單的事物?', `MaleText_loc7`='Todas estas batallas son un desperdicio. ¿Cómo podéis hacerlo a todas horas? ¿Cuándo encontráis tiempo para festejar y disfrutar de las cosas?' WHERE `ID`=68114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드, 얼라이언스... 차이가 뭡니까?! 모두 좋은 술을 좋아하지 않습니까? 친구와 가족들을 똑같이 소중하게 생각하지 않습니까?', `MaleText_loc4`='部落，联盟……有什么分别？！你们不都爱喝美酒？你们不都珍惜自己的朋友和家人？', `MaleText_loc5`='部落，聯盟...到底有什麼差別?你們雙方難道不喜歡美酒嗎?你們雙方難道不同樣地重視你們的朋友和家人嗎?', `MaleText_loc7`='La Horda, la Alianza... ¿qué diferencia hay? ¿Acaso no disfrutan de la cerveza en ambos bandos? ¿Acaso no valoran a sus parientes y amigos por igual?' WHERE `ID`=68115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서로의 차이점을 그냥 얘기로 풀어버릴 수 없는 이유가 뭡니까? 즐겁고 긴 대화로 풀 수 없는 문제는 제 평생 만나본 적이 없습니다!', `MaleText_loc4`='你们怎么就不能开诚布公地讨论下彼此的分歧？我还没遇见过什么难题是长谈解决不了的！', `MaleText_loc5`='你們為什麼就是沒辦法為你們的差異好好談談呢?我還沒碰過有什麼問題是坐下來長談沒辦法解決的!', `MaleText_loc7`='¿Por qué no pueden solucionar sus diferencias mediante el diálogo? ¡Nunca me he encontrado con un problema que no se pudiera solucionar con una buena charla!' WHERE `ID`=68116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 적대적인 세력이 있다는 걸 이해하지 못하는 것 같군.', `MaleText_loc4`='你根本无法理解自己面对的是什么力量。', `MaleText_loc5`='你不可能有辦法理解你所對抗的是多麼龐大的軍力。', `MaleText_loc7`='No comprendes las fuerzas que se manifiestan contra ti.' WHERE `ID`=68117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내 시각이 이해되지 않소?', `MaleText_loc4`='也许你现在准备按我的方式看待事物了？', `MaleText_loc5`='也許現在你能站在我的角度看事情?', `MaleText_loc7`='¿Accedes ahora a ver las cosas a mi manera?' WHERE `ID`=68118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꿀이슬 마을은 허니듀 가문이 운영합니다만, 마을의 진짜 중심은 바로 양조장입니다! 양조장은 우리 가문, 허니포우 가문의 소유입니다. 세계 최고의 꿀술을 빚어내지요!', `MaleText_loc4`='蜜露村是由蜜露家族管理的，但村子的支柱产业是酿酒！说到酿酒，那可是我蜜掌家族的拿手好戏！你在别处绝对喝不到这么好的蜜酒！', `MaleText_loc5`='甘露村是由甘露家掌管，但村子的真正中心是酒坊。酒坊是屬於我的家族，蜜爪家的。這是你到任何地方都找不到的頂級甘露酒!', `MaleText_loc7`='Los Almíbar dirigen el Poblado Almíbar, pero el verdadero corazón de la aldea es la cervecería. Pertenece a mi familia, los Zarpa Melosa. ¡Es la mejor birramiel que existe!' WHERE `ID`=68119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 우리를 더디게 만들 뿐이오. 우리는 멈출 수가 없소.', `MaleText_loc4`='你只会拖慢我们，但无法阻止我们。', `MaleText_loc5`='你只是在拖延我們。我們是無法阻擋的。', `MaleText_loc7`='Solo conseguirás retrasarnos. No puedes detenernos.' WHERE `ID`=68120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들이 오기 전에 축제를 하러 새벽의 꽃에 가던 중이었습니다! 오늘 밤에 불꽃놀이가 있을 거라고 생각은 했지만, 이렇게 난리가 날 줄은 몰랐습니다!', `MaleText_loc4`='我们正赶去晨芳园过节，然后你就出现了！当我想象今夜的绚烂焰火时，我可没想到会是这样的！', `MaleText_loc5`='在你們到達之前，我們原本是在前往晨綻參加節慶的途中!當時我還在想像今晚的煙火，根本沒料想到會是這個樣子!', `MaleText_loc7`='¡Íbamos de camino al festival de Floralba cuando llegaron! Pensaba ver fuegos artificiales esta noche, ¡pero no me esperaba esto!' WHERE `ID`=68121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 장엄한 존재를 본 적 있소?', `MaleText_loc4`='你见过这么壮观的东西吗？', `MaleText_loc5`='你以前有看過這麼動人的生物嗎?', `MaleText_loc7`='¿Alguna vez has visto a un ser tan magnífico?' WHERE `ID`=68122;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 선박이다... 전투 준비! 비행기를 출동시켜라. 갑판을 비워라! 전쟁을 시작한다!', `FemaleText_loc4`='那是部落的船。全船战备部署！各就各位，准备战斗。打起精神来，弟兄们。大战一场！', `FemaleText_loc5`='那些是部落的船隻。就戰鬥崗位!把空軍準備好。清理甲板。所有人就位。咱們開戰了!', `FemaleText_loc7`='Son barcos de la Horda. ¡Zafarrancho de combate! Que despeguen los aviones. Despejen las cubiertas. A las armas, soldados. ¡A la guerra!' WHERE `ID`=68123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 기회가 있을 때 포기하시오!', `MaleText_loc4`='放弃吧，趁你还有机会！', `MaleText_loc5`='趁現在你還有機會，快放棄吧!', `MaleText_loc7`='¡Ríndete ahora que todavía puedes!' WHERE `ID`=68124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 사소한 불편함일 뿐이오.', `MaleText_loc4`='一个小麻烦。', `MaleText_loc5`='小麻煩罷了。', `MaleText_loc7`='Una simple molestia.' WHERE `ID`=68125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리 땅에서까지 전쟁을 이어가려 하는 겁니까? 당신들 고향은 어쩌고요? 그곳에는 싸울 가치가 있는 게 없습니까?', `MaleText_loc4`='为什么要把战争引到我们的土地上来？你们的家乡呢？在那里已经没什么好争的了吗？', `MaleText_loc5`='你們為什麼把你們的戰爭帶來我們的土地上?你們的家園呢?難道那裡已經沒有值得一戰的事物了嗎?', `MaleText_loc7`='¿Por qué han traído su guerra a nuestra tierra? ¿Qué hay de sus hogares? ¿Allí no hay nada por lo que merezca la pena luchar?' WHERE `ID`=68126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 행동이 틀림없이 음영파의 주의를 끌 겁니다. 어쩌면 저도 음영파를 만나볼 수 있겠군요!', `MaleText_loc4`='你们的行为必定会引起影踪派的注意。说不定我能见到他们！', `MaleText_loc5`='你們的行為無疑地會吸引影潘的注意。我甚至有機會能見到一個!', `MaleText_loc7`='Sus actos acabarán por llamar la atención del Shadopan. ¡A lo mejor conozco a uno de sus miembros!' WHERE `ID`=68127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 마을은 당신의 전쟁에 참여하지 않을 겁니다. 하지만, 당신들이 나타나면서 우리의 평화로운 삶이 영원히 바뀌어버렸을지 모른다는 걱정이 드는군요.', `MaleText_loc4`='我的村庄不会卷入你们的冲突。尽管你们的到来也许已经彻底打乱了我们平静的生活。', `MaleText_loc5`='我的村子不會介入你們的衝突。不過我很擔心你們的到來已經永遠地改變了我們所擁有的平靜。', `MaleText_loc7`='Mi aldea no formará parte de su conflicto, aunque temo que su llegada haya cambiado nuestra existencia pacífica para siempre.' WHERE `ID`=68128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 꿀술은 이 마을의 생명줄입니다. 그렇게 생각하면 싸울 만한 가치가 있겠죠!', `MaleText_loc4`='这蜜酒是整个村子的命脉。现在也成了值得你争我抢的东西！', `MaleText_loc5`='甘露酒是這個村子的生命泉源。值得為它而戰!', `MaleText_loc7`='La birramiel es la sangre vital de esta aldea. ¡Por eso sí que merece la pena luchar!' WHERE `ID`=68129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요, 이쪽입니다! 포격 때문에 안마당으로 통하는 길이 생겼습니다!', `MaleText_loc4`='赶快，这边！炮弹击穿了院墙！', `MaleText_loc5`='快點，走這裡!砲火打開了一條通往庭院的路!', `MaleText_loc7`='¡Por aquí, rápido! El disparo del cañón ha abierto un pasaje al patio.' WHERE `ID`=68130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직여야 합니다. 꿀술이 제 발로 나타날 리는 없으니까요!', `MaleText_loc4`='我们得走了。那蜜酒不会自己跑出来！', `MaleText_loc5`='我們應該繼續前進。甘露酒可不會自己跑出來!', `MaleText_loc7`='Deberíamos darnos prisa. ¡La birramiel no se va a encontrar sola!' WHERE `ID`=68131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죄송하지만 이제 유물을 팔지 않아요. 유물의 마법이 사라진 것 같아요! 이제 전업 무희가 될까 해요. 좋은 변화가 될 것 같아서요.', `FemaleText_loc4`='很抱歉，可我没有古物可以出售给你了。它们的魔法力量似乎已经消失了！也许我该改行当全职舞蹈家，那会是个不错的改变。', `FemaleText_loc5`='我非常抱歉，但我已經沒有聖物能賣給你了。它們的魔法似乎消失了!也許現在我能當個全職舞者了，這會是我生活步調很好的改變。', `FemaleText_loc7`='Lo siento, pero ya no tengo reliquias que venderte. ¡Su magia parece haberse disipado! A lo mejor ahora me dedico al baile a tiempo completo. Sería un buen cambio de aires.' WHERE `ID`=68132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다. 이 꿀술은 꼭 마을까지 가져가겠습니다. 또 뭘 날려버리거나 하진 마십시오!', `MaleText_loc4`='多谢你的帮助。我一定会把这蜜酒送回村里。尽量别惹其它麻烦了！', `MaleText_loc5`='謝謝你的幫助。我會確保這些甘露酒能回到村子裡。試著別炸壞其他東西!', `MaleText_loc7`='Gracias por tu ayuda. Me aseguraré de que la birramiel vuelve a la aldea. ¡Intenta no volar nada más!' WHERE `ID`=68133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔서 감사합니다. 또 뭘 날려버리거나 하진 마십시오!', `MaleText_loc4`='多谢你的帮助。尽量别惹其它麻烦了！', `MaleText_loc5`='謝謝你的幫助。試著別炸壞其他東西!', `MaleText_loc7`='Gracias por tu ayuda. ¡Intenta no volar nada más!' WHERE `ID`=68134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 머물게 해도 될까? 부상자들을 치료해야 할 것 같은데.', `MaleText_loc4`='我们不该让他们留在这儿吗？他们有伤员需要照料。', `MaleText_loc5`='我們應該讓他們待在這裡嗎?他們有傷者需要照顧。', `MaleText_loc7`='¿Deberíamos dejar que se queden? Tienen heridos de los que cuidar.' WHERE `ID`=68135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신네들의 비행포격선에서 발사한 포탄이 우리 농장에 떨어진 건 어떻게 생각합니까?!', `FemaleText_loc4`='那些从你们的战船上掉到我们农场里的炸弹又怎么说！', `FemaleText_loc5`='我們田裡那些從你們戰船扔下來的炸彈又怎麼說!', `FemaleText_loc7`='¿Y qué hay de las explosiones de tu nave de guerra que destrozaron nuestras granjas?' WHERE `ID`=68136;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들이 우리 마을을 더 파괴하고 말 걸세!', `FemaleText_loc4`='他们会给我们的村庄带来更多灾难！', `FemaleText_loc5`='他們會把更多破壞帶到我們村子來!', `FemaleText_loc7`='¡Traerán más destrucción a nuestra aldea!' WHERE `ID`=68137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네들이 오기 전에는 없었던 전쟁 말이야!', `FemaleText_loc4`='在你们来之前，我们根本与世无争！', `FemaleText_loc5`='在你們來之前，我們根本沒有戰爭!', `FemaleText_loc7`='¡Una guerra que no teníamos hasta que llegaron!' WHERE `ID`=68138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 공중에서 우리가 탄 비행선을 날려버리는 걸 보고도 어떻게 중립을 유지할 수 있소?!', `MaleText_loc4`='在亲眼看着他们把我们从天上击落后，你们怎么还能继续保持中立？！', `MaleText_loc5`='你怎能在目睹他們將我們從天上轟下來之後還保持中立?!', `MaleText_loc7`='¡¿Cómo pueden ser neutrales después de que nos hayan derribado?!' WHERE `ID`=68139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁에는 사상자가 있게 마련이오!', `MaleText_loc4`='那是战争的代价！', `MaleText_loc5`='那些是戰爭造成的意外傷害!', `MaleText_loc7`='¡Son las consecuencias de la guerra!' WHERE `ID`=68140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 곧 이동한다. 이 생물들이 우리 배에서 남은 물자를 대부분 파괴해 버렸다.', `MaleText_loc4`='够了！我们很快就转移。这些家伙把我们的舰船摧毁得面目全非了。', `MaleText_loc5`='夠了!我們很快就會找到新的駐紮地點。戰艦剩下來的東西，大部份都被這些生物給毀了。', `MaleText_loc7`='¡Basta! Nos trasladaremos en breve. Esas criaturas han destruido casi todo lo que quedaba de la nave.' WHERE `ID`=68141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을 주민들이 파는 물건을 최대한 확보해라. 다른 녀석들에게도 출발 준비를 시키고.', `MaleText_loc4`='把村民们愿意卖给我们的东西收集起来，准备安排其他人撤离。', `MaleText_loc5`='收集村民們願意賣給我們的東西，並要其他人準備離開。', `MaleText_loc7`='Reúne lo que los aldeanos estén dispuestos a vendernos y avisa a los demás de que nos marchamos.' WHERE `ID`=68142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 어른이 되고 싶어요!', `MaleText_loc4`='我真想马上长大！', `MaleText_loc5`='我等不及要長大了!', `MaleText_loc7`='¡Quiero ser mayor!' WHERE `ID`=68143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 형 보신 분?', `MaleText_loc4`='有人看见我哥哥了吗？', `MaleText_loc5`='有沒有人看到我兄弟?', `MaleText_loc7`='¿Alguien ha visto a mi hermano?' WHERE `ID`=68144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과자 먹고 싶어요. 전 과자가 정말 좋아요!', `MaleText_loc4`='要是有甜饼吃就好了。我喜欢甜饼！', `MaleText_loc5`='我好希望我有塊餅乾。我愛死餅乾了!', `MaleText_loc7`='Ojalá tuviera una galleta. ¡Me encantan las galletas!' WHERE `ID`=68145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 방어가 더 강했던 것 같군요. 다시 도전할 준비가 되면 제게 말씀하세요.', `FemaleText_loc4`='看来我的防御更胜一筹。等你准备好重试时，再来与我交谈。', `FemaleText_loc5`='看來我的防禦佔了上風。當你準備好再試一次時來跟我說。', `FemaleText_loc7`='Parece que mis defensas han prevalecido. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허그갈론은 여러분을 사랑해요!', `MaleText_loc4`='胡戈伦爱你！', `MaleText_loc5`='夏佳隆愛你!', `MaleText_loc7`='¡EMPALAGÓN TE QUIERE!' WHERE `ID`=68147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 싸우셨지만, 아직은 갈 길이 머네요. 다시 도전할 준비가 되면 말씀하세요.', `FemaleText_loc4`='打得不错，可你还得多加努力才行。准备好重试时再来与我交谈。', `FemaleText_loc5`='打得很好，但你還有些地方需要努力。當你準備好再試一次時來跟我說。', `FemaleText_loc7`='Has luchado bien, pero aún queda trabajo por hacer. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68148;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='결국 절 막지 못했군요. 다시 도전할 준비가 되면 말씀하세요.', `FemaleText_loc4`='看来你还奈何不了我啊。等你准备好重试时，再来与我交谈。', `FemaleText_loc5`='看來你沒辦法把我逼退。當你準備好再試一次時來跟我說。', `FemaleText_loc7`='Parece que no has sido capaz de mantenerme a raya. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 상대하기엔 제가 너무 강했던 모양이군요. 다시 도전할 준비가 되면 말씀하십시오.', `MaleText_loc4`='对你来说，我的力量似乎过于强大了。等你准备好重试时，再来与我交谈。', `MaleText_loc5`='看來我的力量對你來說太強大了。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Parece que mi fuerza te ha superado. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 꺾으려는 시도가 실패한 것 같군요. 다시 도전할 준비가 되면 말씀하십시오.', `MaleText_loc4`='看来你没能击败我。等你准备好重试时，再来与我交谈。', `MaleText_loc5`='看來你是徒勞無功了。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Parece que tus esfuerzos por derrotarme han fracasado. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 해안에 전쟁을 가져온다면, 이 땅 그 자체가 자네 열정과 폭력에 반응할 걸세.', `MaleText_loc4`='如果你想将战火引到我们的海岸，那么这片土地会对你的冲动和暴力作出回应。', `MaleText_loc5`='如果你想要把戰爭帶來我們的海岸，土地本身就會回應你們的激情和暴力。我不知道最終的後果是什麼...沒有人知道。', `MaleText_loc7`='Si pretenden traer la guerra a nuestra costa, la tierra misma responderá a sus pasiones y a su violencia.' WHERE `ID`=68152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 결과가 나타날지는 나도 모르네. 아무도 모르지.', `MaleText_loc4`='我不知道最终会造成什么后果——没人知道。', `MaleText_loc5`='我不知道最終的結果會是什麼。沒有人知道。', `MaleText_loc7`='No sé cuáles serán las consecuencias definitivas... Nadie lo sabe.' WHERE `ID`=68153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 의지도 강하지만, 제 의지가 더 강했던 모양입니다. 다시 도전할 준비가 되면 말씀하십시오.', `MaleText_loc4`='你的意志十分强大，但与我相比还是稍逊一筹。等你准备好重试时，再来与我交谈。', `MaleText_loc5`='你的意志很堅強，但看來我的意志還要更加堅強。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Tu voluntad es fuerte, pero parece que la mía lo es más. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 조교들이 당신에게는 버거웠던 모양입니다. 다시 도전할 준비가 되면 말씀하십시오.', `MaleText_loc4`='看来我的助手们对你而言太难应对了。等你准备好重试时，再来与我交谈。', `MaleText_loc5`='看來我的助手們對你來說太強大了。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Parece que mis ayudantes te han superado. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 시험을 치를 준비는 되었나, $n?', `MaleText_loc4`='你准备好面对最后的考验了吗，$n？', `MaleText_loc5`='你準備好要接受最後的測驗了嗎，$n?', `MaleText_loc7`='¿Estás $glisto:lista; para la prueba final, $n?' WHERE `ID`=68156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我准备好了。', `MaleText_loc5`='我準備好了。', `MaleText_loc7`='Estoy listo.', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我准备好了。', `FemaleText_loc5`='我準備好了。', `FemaleText_loc7`='Estoy lista.' WHERE `ID`=68157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 내게 예를 갖추어 인사하면 시작하도록 하지.', `MaleText_loc4`='对我鞠躬，我们就开始。', `MaleText_loc5`='向我鞠躬，我們就可以開始了。', `MaleText_loc7`='Hazme una reverencia y podremos empezar.' WHERE `ID`=68158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 꺾으려면, 다른 사부들에게서 배운 것을 모두 활용해야 할 걸세. 그럴 수 있다면 훈련은 끝난 것이지.', `MaleText_loc4`='要想击败我，你必须使出自己从其他大师那里学到的所有招数。要是你能做到，你的训练就完成了。', `MaleText_loc5`='想要打倒我，你得用上你從其他大師身上學到的所有技巧。如果你能辦得到，你的訓練就算完成了。', `MaleText_loc7`='Para derrotarme, tendrás que poner en práctica todo lo que has aprendido de los demás maestros. Si lo consigues, tu entrenamiento habrá concluido.' WHERE `ID`=68159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 가르친 것을 모두 소화하지 못한 것 같군. 다시 도전할 준비가 되면 내게 말하게.', `MaleText_loc4`='你似乎还没能将我们传授给你的技能融会贯通。等你准备好重试时，再来与我交谈。', `MaleText_loc5`='看來你還沒精通我們教給你的所有技巧。當你準備好再試一次時來跟我說。', `MaleText_loc7`='Parece que no has terminado de dominar todo lo que te hemos enseñado. Habla conmigo cuando quieras volver a intentarlo.' WHERE `ID`=68160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 하이트가 당신을 산 채로 태웁니다! 이동하십시오!', `MaleText_loc4`='海特大师要把你活活烧死。快走开！', `MaleText_loc5`='高大師要活生生地燒死你。快移動!', `MaleText_loc7`='El maestro Cenit te está quemando. ¡Muévete!' WHERE `ID`=68161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 하이트가 상처를 치유하고 있습니다. 차단하십시오!', `MaleText_loc4`='海特大师正在治疗。打断他！', `MaleText_loc5`='高大師正在治療。中斷他!', `MaleText_loc7`='El maestro Cenit se está sanando. ¡Interrúmpelo!' WHERE `ID`=68162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 하이트가 회전합니다! 마비시키십시오!', `MaleText_loc4`='海特大师正在旋转。使他瘫痪！', `MaleText_loc5`='高大師正在旋轉。癱瘓他!', `MaleText_loc7`='El maestro Cenit está girando. ¡Paralízalo!' WHERE `ID`=68163;
