UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(감쇠장이 활성화된 상태로 영웅 난이도에서 우두머리를 처치했습니다. 이제 감쇠장을 비활성화할 수 없습니다.)', `MaleText_loc4`='（已通过启用抑制力场，在英雄难度下击败了某位首领。该效果不能被取消。）', `MaleText_loc5`='(一個首領已經在抑制力場啟動的情況下在英雄難度中被擊敗。抑制力場已經無法被關閉。)', `MaleText_loc7`='(Se ha derrotado a un jefe en dificultad heroica con el campo de atenuación activado. Ya no se puede desactivar.)' WHERE `ID`=68257;
