UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 차를 잘못 마신 것 아닙니까? 네, 그게 틀림없을 겁니다. 제가 차를 잘못 마셨군요. 사과드리겠습니다.', `MaleText_loc4`='也许是我泡错了茶？对，肯定是这样。抱歉，我泡错茶了。', `MaleText_loc5`='可能我泡茶的方法錯了?對，一定是這樣，我泡茶的方法不對。我的錯。', `MaleText_loc7`='¿Preparé mal el té? Sí, tiene que ser eso. Debí preparar mal el té. Lo siento.' WHERE `ID`=68260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 어쩌다 오셨습니까?', `MaleText_loc4`='你最后怎么会在这儿？', `MaleText_loc5`='你是怎麼來到這裡的?', `MaleText_loc7`='¿Cómo has acabado aquí?', `FemaleText_loc1`='여기엔 어쩌다 오셨나요?', `FemaleText_loc4`='你最后怎么会在这儿？', `FemaleText_loc5`='你是怎麼來到這裡的?', `FemaleText_loc7`='¿Cómo has acabado aquí?' WHERE `ID`=68261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7은 저를 발견하자 왕궁으로 데리고 가려고 했습니다. 전 도망쳤지요.$B$B얼마 지나지 않아 호드가 절 찾았습니다.$B$B용의 심장에서 전투가 벌어졌을 때, 저는 혼란을 틈타 슬쩍 빠져나올 수 있었어요. 가족을 데리고 서쪽에 있는 쥬의 감시초소로 도망치던 상인이 저를 태워 주었지요.$B$B그곳에서 메이 배럴보톰을 만났어요.$B$B메이가 주학의 교단에 대해 이야기해 주었고, 그녀의 조언에 따라 급사와 함께 주학사로 가서 주학 츠지 님을 뵙기를 청했지요.$B$B그곳의 문하생들과 함께 공부를 하고 있었는데 샤가 나타났습니다.', `MaleText_loc4`='当军情七处的特工人员找到我时，他们想带我回家。可我却跑掉了。$B$B过了没多久，部落发现了我。$B$B在神龙之心的战斗中，我趁乱逃了出来。有位商人正携家眷逃往西边的朱家堡，他愿意载我一程。$B$B我就是在那里遇见梅·残酒的。$B$B她向我介绍了这个名为鹤翼的组织，并建议我陪同信使前往寺院，与朱鹤赤精会面。$B$B当邪煞出现时，我正在和其他门徒一起修炼。', `MaleText_loc5`='當軍情七處找到我時，他們想要帶我回家。我跑掉了。$B$B不久之後部落就找到了我。$B$B在蟠龍之心的戰鬥中，我成功地在混亂中溜走。一個商人讓我跟著他的家人一起逃往到西邊，到了祝家守望站。$B$B就在那裡我遇見了小美·桶底。$B$B她告訴我關於鶴翼之令的事，而我也在她的建議之下陪著一名信差來到神廟求見紅鶴赤吉。$B$B當煞到來時我正在那裡和門徒一起學習。', `MaleText_loc7`='Cuando me encontró el IV:7, quisieron llevarme a casa. Me escapé.$b$bLa Horda no tardó en encontrarme.$b$bDurante la batalla del Corazón del Dragón, conseguí escabullirme en medio del caos. Un mercader me dejó viajar con su familia hacia el oeste, a la Atalaya de Zhu.$b$bAllí conocí a Mei Barril Vacío.$b$bMe habló de la orden Ala de Grulla. Siguiendo su consejo, acompañé a un mensajero hasta el templo para pedirle audiencia a Chi-Ji, la Grulla Roja.$b$bEstaba estudiando con los discípulos cuando llegaron los sha.' WHERE `ID`=68262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서 얼라이언스가 피를 흘리고 있는데 스톰윈드 왕궁에 앉아 있을 수는 없습니다!$B$B판다리아에는 배울 점이 아주 많아요. 이곳엔 큰 힘이 잠들어 있어요. 수천 명의 목숨을 구할 수 있는 힘이요.$B$B전 그 힘을 찾으려 합니다.', `MaleText_loc4`='我无法眼睁睁的看着自己的人民在这里抛洒热血，自己却端坐在暴风要塞里！$B$B潘达利亚能教会我们许多事。这里蕴藏着巨大的力量。足以拯救万千苍生的力量。$B$B而我要做的，就是令这力量得见天日。', `MaleText_loc5`='我沒辦法忍受我的子民們在此灑濺熱血的同時，我卻呆坐在暴風要塞中!$B$B潘達利亞有許多我們可以學習的東西。這裡有強大的力量。足以拯救成千上萬生命的力量。$B$B而我想要找到它。', `MaleText_loc7`='¡No puedo quedarme sentado en el Castillo de Ventormenta mientras mi gente derrama su sangre aquí!$b$bPandaria tiene mucho que enseñarnos. Aquí habita un gran poder, un poder que podría salvar miles de vidas.$b$bY yo pretendo descubrirlo.' WHERE `ID`=68263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 SI:7과 함께 스톰윈드로 돌아가지 않았습니까?', `MaleText_loc4`='你为什么不跟军情七处的特工们返回暴风城？', `MaleText_loc5`='你為什麼不和軍情七處一起回到暴風城?', `MaleText_loc7`='¿Por qué no volviste a Ventormenta con el IV:7?', `FemaleText_loc1`='왜 SI:7과 함께 스톰윈드로 돌아가지 않았나요?', `FemaleText_loc4`='你为什么不跟军情七处的特工们返回暴风城？', `FemaleText_loc5`='你為什麼不和軍情七處一起回到暴風城?', `FemaleText_loc7`='¿Por qué no volviste a Ventormenta con el IV:7?' WHERE `ID`=68264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝거리는 농기구 내 거야! 맛좋은 당근도 내 거야! 모두 다 쿤젠 거라고. 모두 주방장 입입 거야!', `MaleText_loc4`='闪亮的工具是我的！可口的胡萝卜也是我的！一切都属于昆森。一切都属于酋长伊普伊普！', `MaleText_loc5`='閃亮的工具是我的!好吃的胡蘿蔔也是我的!人人為崑真。人人為葉葉酋長!', `MaleText_loc7`='¡Kosas brillantes para mí! ¡Zanahorias rikas para mí! Todo para Kunzen. ¡Todo para jefe Yip-Yip!' WHERE `ID`=68265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, 이방인님. 농장 일은 잘 돼가나요?', `FemaleText_loc4`='你好啊，陌生人。农场上一切还好吗？', `FemaleText_loc5`='嘿，陌生人。你在農場中過得還好嗎?', `FemaleText_loc7`='¡Hola! ¿Va todo bien en la granja?' WHERE `ID`=68266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$r님, 조금 약해 보이시네요. 여기 있는 이웃들을 도와줄 수 있을 정도로 강해지려면 이곳 주변을 더 여행해보셔야겠어요.', `FemaleText_loc4`='你看起来弱了点儿，$r。你得在这片土地上多加游历，才能让自己变得强大起来，帮助这里的住民。', `FemaleText_loc5`='你看起來有點弱，$r。在你夠強壯能幫助這裡的人們之前，你必須到更多地方旅行。', `FemaleText_loc7`='Pareces un poco débil, $r. Tienes que viajar más por Pandaria antes de volverte lo bastante fuerte para ayudar a nuestros vecinos.' WHERE `ID`=68267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에 사는 주민들은 이방인을 조금 경계하지만, 얼굴을 익히면 금세 다정하게 대해준답니다.$B$B경험을 더 쌓고 나면, 주민들을 도와주며 친해질 수 있을 거예요.', `FemaleText_loc4`='这附近的住民对陌生人心怀警惕，可一旦熟识之后，他们就会令你如沐春风。$B$B等你积累更多经验后，你就能向他们提供帮助，与他们建立友谊。', `FemaleText_loc5`='這附近的人們有點提防陌生人，但只要你能認識他們就能感到他們溫暖的人情味。$B$B當你有更多經驗時，你就能藉由幫助他們來認識他們。', `FemaleText_loc7`='La gente de los alrededores recela de los forasteros, pero se ablandan cuando se les conoce.$b$bCuando tengas más experiencia, podrás echarles una mano para conocerlos mejor.' WHERE `ID`=68268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 있는 주민들을 언제나 당신의 도움이 필요하답니다. 하지만 당신은 아직 그들을 도울 정도로 강하지가 않네요. 이곳 주변을 더 여행하며 경험을 더 쌓고 다시 돌아오시면 주민들이 당신에게 도움을 청할 거예요.', `FemaleText_loc4`='这附近的住民常常需要帮助，可你还不够强大。你需要在这片土地上多加游历，等你回来时，他们就会求你帮忙了。', `FemaleText_loc5`='這附近的人們總是需要一個幫手，但你還不夠強壯。等到你走過這片土地的更多地方，回到這裡來他們就會懇求你的協助。', `FemaleText_loc7`='A todo el mundo le viene bien que le echen una mano, pero todavía no eres lo bastante fuerte. Cuando hayas recorrido Pandaria lo suficiente, vuelve y verás que te pedirán ayuda.' WHERE `ID`=68269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상인 그린필드가 주는 씨앗 본 적 있나요? 그린필드는 약간 이상하지만 훌륭한 씨앗들을 많이 가지고 있답니다. 그 씨앗을 당신 농장에 심어서 키울 수 있어요.', `FemaleText_loc4`='你见过商人绿野出售的种子了吗？你在自己的农场上可以种植各种各样新鲜又奇妙的作物。', `FemaleText_loc5`='你有看過商人青田的種子嗎?他有各式各樣你可以種在農場中古怪與奇妙的東西。', `FemaleText_loc7`='¿Has visto los suministros de semillas del mercader Campo Fértil? Tiene todo tipo de cosas extrañar y maravillosas que cultivar en la granja.' WHERE `ID`=68270;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 농장에 동물들을 들일 생각해 보신 적 없나요?', `FemaleText_loc4`='你有没有考虑过在自己的农场上养几只动物？', `FemaleText_loc5`='你有想過要在你的農場中添加一些動物嗎?', `FemaleText_loc7`='¿Alguna vez te has planteado criar animales en la granja?' WHERE `ID`=68271;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 농부 윤이 사는 집은 정말 못 봐주겠어요! 윤은 티나와 이야기를 좀 해봐야 해요. 집을 새로 꾸미는 솜씨가 정말 좋거든요.', `FemaleText_loc4`='知道吗，农夫老愚住的房子简直就是个垃圾场！他应该跟迪娜谈谈。听说她很擅长重新装修。', `FemaleText_loc5`='你知道，農夫尹住的那個房子根本是個垃圾堆!他應該和蒂娜談談。我聽說她對重新裝潢很在行。', `FemaleText_loc7`='¡Esa casa en la que vive el granjero Yoon es una vergüenza! Debería hablar con Tina. Dicen que se le da muy bien la decoración.' WHERE `ID`=68272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 파는 물건들 다 보셨나요? 제게 물건을 사려면 농사꾼 연합에게 좋은 평판을 얻어야 하고, 그러려면 이곳을 좀 더 여행하며 경험을 쌓아야 한답니다.', `FemaleText_loc4`='你看过我出售的所有商品了吗？你得先赢得阡陌客的青睐，才能从我这里买东西，要想做到这一点，你需要在这片土地上多加游历，积累更多经验。', `FemaleText_loc5`='你有看過我所出售的所有貨品嗎?你必須先贏得耕者的認同我才會賣給你，但要達到那個目標，你得先在這片土地上旅行，獲得更多的經驗才行。', `FemaleText_loc7`='¿Has visto la de cosas que vendo? Para comprarlas tendrás que ganarte el favor de los Labradores, y para eso te hace falta ganar más experiencia en tus viajes por Pandaria.' WHERE `ID`=68273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 구니는 우리 선원 몇 명과 비취 숲에 있는 스리라 마을로 떠내려왔네. 진흙탕 물을 몇 달이나 걸어 다녔더니 발이 말도 못 하게 간지럽더군. 이곳으로 왔더니 천국을 발견했다네.', `MaleText_loc4`='冈尼和我，我们与其它几名船员一起，被冲到了翡翠林的香里拉村附近。在海上颠簸了几个月后，我们的双脚早已疼得走不动路。我们来到了这里，找到了天堂。', `MaleText_loc5`='我和甘尼，還有一些我們的船員一起被沖到翠玉林中的斯里拉村附近。我們在海上飄搖幾個月後都迫不及待地想要踏上陸地。我們來到了此地並找到了天堂。', `MaleText_loc7`='Pih''tolero y yo acabamos cerca de la Aldea Sri-La, en el Bosque de Jade, junto con algunos miembros de la tripulación. Tras meses en alta mar, teníamos ganas de pisar tierra firme. Llegamos aquí y encontramos el paraíso.' WHERE `ID`=68274;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='라즈쿠와 전 며칠 동안 계속해서 여행 중이었어요. 우리가 저 장벽을 다 봤다고 생각했을 때, 다시 한 번 놀랐죠.', `FemaleText_loc4`='我和拉古旅行了好多天。可就在我们认为自己已经饱览一切时，我们再次感到了惊奇。', `FemaleText_loc5`='拉庫和我已經跋涉了許多時日。就在我們以為我們什麼都看過的時候，我們又大吃了一驚。', `FemaleText_loc7`='Raj''ku y yo llevamos días enteros viajando. Justo cuando pensamos que ya lo hemos visto todo... algo nos sorprende.' WHERE `ID`=68275;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 서쪽에 있는 저 장벽 끝에 뭐가 있는지 보일 때까지 계속 가보고 싶었지만, 라주크는 여기 있는 거대한 채소들만 마냥 바라봤어요. 속마음은 농부가 되고 싶어서 근질거리는 거죠!', `FemaleText_loc4`='我想继续前进，直到抵达西边那道雄伟长城，看见另一侧的景象为止，可拉古的眼睛却总盯着附近那些巨大的蔬菜。也许在内心深处，他渴望成为一名农夫！', `FemaleText_loc5`='我想要繼續走，直到我們看到西邊那道大牆後面有什麼東西，但是拉庫只是一直盯著這附近的巨大蔬菜。也許在他內心深處，他想要成為一名農夫!', `FemaleText_loc7`='Quiero seguir hasta que veamos qué hay al otro lado de esa gran muralla del oeste, pero Raj''ku no deja de mirar las verduras enormes de los alrededores. ¡A lo mejor es un granjero de corazón!' WHERE `ID`=68276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 부른 게 누구냐?', `MaleText_loc4`='谁在召——召——召唤？', `MaleText_loc5`='是誰在呼-呼-呼-呼-呼喚?', `MaleText_loc7`='¿Q-q-q-quién llama?' WHERE `ID`=68278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겁쟁이들...', `MaleText_loc4`='懦——懦——懦夫……', `MaleText_loc5`='懦-懦-懦-懦-懦夫...', `MaleText_loc7`='C-c-c-cobardes...' WHERE `ID`=68279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 무엇을 팔고 계십니까?', `MaleText_loc4`='你现在有什么商品出售？', `MaleText_loc5`='你現在有什麼東西出售?', `MaleText_loc7`='¿Qué tienes a la venta?', `FemaleText_loc1`='지금 무엇을 팔고 계세요?', `FemaleText_loc4`='你现在有什么商品出售？', `FemaleText_loc5`='你現在有什麼東西出售?', `FemaleText_loc7`='¿Qué tienes a la venta?' WHERE `ID`=68280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마을에 대해 뭔가 알려주실 게 있습니까?', `MaleText_loc4`='你能告诉我一些关于你村子的事吗？', `MaleText_loc5`='你能告訴我關於你們村子的任何事嗎?', `MaleText_loc7`='¿Puedes contarme algo sobre tu aldea?', `FemaleText_loc1`='마을에 대해 뭔가 알려주실 게 있나요?', `FemaleText_loc4`='你能告诉我一些关于你村子的事吗？', `FemaleText_loc5`='你能告訴我關於你們村子的任何事嗎?', `FemaleText_loc7`='¿Puedes contarme algo sobre tu aldea?' WHERE `ID`=68281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 양조사와 농부들의 마을입니다. 필요할 때만 가끔씩 사냥을 하지요.$B$B그때 바로 제가 필요한 겁니다. 적당한 활 없이 사냥을 하는 게 얼마나 힘든지 아십니까?!', `MaleText_loc4`='村里人都是酿酒师和农夫。我们偶尔也会在需要时外出狩猎。$B$B这正是我想说的。如果缺少一把好弓，狩猎可真是难得要命啊！', `MaleText_loc5`='我們是個釀酒人和農夫的村子。我們在需要時偶爾會出外打獵。$B$B那就是我發揮長才的時候啦。沒有一把高品質的弓，打起獵來可是很吃力的!', `MaleText_loc7`='Somos un pueblo de cerveceros y granjeros. A veces cazamos, si nos hace falta.$b$bAhí entro yo. ¡Es muy difícil cazar sin un arco de calidad!' WHERE `ID`=68282;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시장에 오기 좋은 날을 고르셨네요.', `FemaleText_loc4`='今天可真是逛集市的好日子啊，邻居。', `FemaleText_loc5`='你挑了個好日子到市集裡來，鄰居。', `FemaleText_loc7`='Has elegido un buen día para venir al mercado.' WHERE `ID`=68283;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언덕골 시장에 오신 것을 환영해요!', `FemaleText_loc4`='欢迎来到半山市集！', `FemaleText_loc5`='歡迎來到半丘市集!', `FemaleText_loc7`='¡Te doy la bienvenida al Mercado del Alcor!' WHERE `ID`=68284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 계십니까?', `MaleText_loc4`='你这有什么商品？', `MaleText_loc5`='你有什麼貨品出售?', `MaleText_loc7`='¿Qué vendes?', `FemaleText_loc1`='어떤 물건을 팔고 계신가요?', `FemaleText_loc4`='你这有什么商品？', `FemaleText_loc5`='你有什麼貨品出售?', `FemaleText_loc7`='¿Qué vendes?' WHERE `ID`=68285;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐 사고팔려고 오신 건가요? 마음껏 둘러보세요.', `FemaleText_loc4`='你是要买还是要卖？欢迎随意看看。', `FemaleText_loc5`='你來這是想買還是賣?隨便看看啊。', `FemaleText_loc7`='¿Has venido para comprar o para vender? Mira sin reparos.' WHERE `ID`=68286;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 잘 찾아오신 거예요. 언덕골 시장에는 없는 물건이 없답니다.', `FemaleText_loc4`='你可真是来对地方了！你在半山市集里能找到任何你需要的东西。', `FemaleText_loc5`='你來對地方了!半丘市集有你需要的所有東西。', `FemaleText_loc7`='¡Has venido al lugar adecuado! El Mercado del Alcor tiene todo lo que necesitas.' WHERE `ID`=68287;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요. 요리법을 배우고 싶으신가요?', `FemaleText_loc4`='你好啊旅行者，想要学习烹饪吗？', `FemaleText_loc5`='你好啊旅人，你想要學習如何烹飪嗎?', `FemaleText_loc7`='¡Hola! ¿Te gustaría aprender a cocinar?' WHERE `ID`=68288;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요리하는 걸 좋아하시나요? 그렇다면 정말 운이 좋으시네요. 저는 포부가 큰 요리사를 도와주는 걸 좋아하거든요.', `FemaleText_loc4`='你喜欢烹饪？那你可走运了，因为我愿意帮助志向远大的厨师。', `FemaleText_loc5`='你喜歡烹飪嗎?你很幸運，因為我喜歡幫助有潛力的大廚們。', `FemaleText_loc7`='¿Te gusta cocinar? Pues estás de enhorabuena, porque a mí me gusta ayudar a aspirantes a cocinero.' WHERE `ID`=68289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p! 도착했군! 저들의 지도자를 공격하게. 우리가 지원할 테니.', `MaleText_loc4`='$p！你在这儿！攻击他们的首领，我们会在后方支援你。', `MaleText_loc5`='$p!你來了!攻擊他們的首領，我們會支援你。', `MaleText_loc7`='$p, ¡has venido! Ataca a su líder y te cubriremos.' WHERE `ID`=68290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마을이 교역으로 그렇게 유명하다면, 왜 다른 마을에서 온 판다렌이 없습니까?', `MaleText_loc4`='如果你因贸易而出名，其它村的熊猫人都去哪儿了？', `MaleText_loc5`='如果你是以交易聞名，那其他村子的熊貓人到哪去了?', `MaleText_loc7`='Si se os conoce por el comercio, ¿dónde están los pandaren de los demás pueblos?', `FemaleText_loc1`='이 마을이 교역으로 그렇게 유명하다면, 왜 다른 마을에서 온 판다렌이 없죠?', `FemaleText_loc4`='如果你因贸易而出名，其它村的熊猫人都去哪儿了？', `FemaleText_loc5`='如果你是以交易聞名，那其他村子的熊貓人到哪去了?', `FemaleText_loc7`='Si se os conoce por el comercio, ¿dónde están los pandaren de los demás pueblos?' WHERE `ID`=68291;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무기는 다른 곳에 두시고 식칼을 드세요. 아이언포우 가문에서 구이와 양조, 국, 찜, 직화요리를 가르쳐드립니다!', `FemaleText_loc4`='放下武器，拿起切肉刀吧，旅行者。铁掌家族的人能把烘焙、酿造、炖煮、蒸烧、烧烤等各类烹饪手艺传授给你！', `FemaleText_loc5`='把你的武器放到旁邊去，然後拿起一把切肉刀，旅人。鐵爪家能教你烘、煮、燉、蒸和烤的所有方法!', `FemaleText_loc7`='Aparta el arma y empuña el cuchillo de carnicero, $gviajero:viajera;. ¡Los Zarpa Férrea podemos enseñarte a asar, a fermentar, a guisar, a hervir y a saltear!' WHERE `ID`=68292;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 요리 실력을 기르고 싶으세요? 저도 당신께 알려드리고 싶은 요리가 무척 많아요.', `FemaleText_loc4`='如果你想提升自己的烹饪技能，我正好有些知识要与你分享。', `FemaleText_loc5`='如果你想要讓你的廚藝更進步，我有知識能與你分享。', `FemaleText_loc7`='Si deseas mejorar tu habilidad en cocina, poseo conocimientos que estoy dispuesta a compartir contigo.' WHERE `ID`=68293;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 생각에는 저 거대한 비행 요새 때문에 요즘은 여행하려는 이가 별로 없는 것 같아요.', `FemaleText_loc4`='我只能说，那个巨大的漂浮堡垒近来让许多旅行者却步难行。', `FemaleText_loc5`='我猜測那座巨大的漂浮要塞把最近可能來這的旅人都嚇跑了。', `FemaleText_loc7`='Mi teoría es que la fortaleza flotante gigante está disuadiendo a los posibles viajeros.' WHERE `ID`=68294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 물건을 팔고 계신지 보고 싶습니다.', `MaleText_loc4`='我想看看你这里有什么商品出售。', `MaleText_loc5`='我想要看看你所賣的貨品。', `MaleText_loc7`='Me gustaría ver qué tienes a la venta.', `FemaleText_loc1`='어떤 물건을 팔고 계신지 보고 싶어요.', `FemaleText_loc4`='我想看看你这里有什么商品出售。', `FemaleText_loc5`='我想要看看你所賣的貨品。', `FemaleText_loc7`='Me gustaría ver qué tienes a la venta.' WHERE `ID`=68295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴 여정이었지만, 드디어 골짜기를 찾았군요. 지금은 파수대와 함께 웅덩이의 신비를 연구하고 있답니다.', `MaleText_loc4`='那是漫长的旅程，可我最终还是找到了山谷。现在我正与哨兵部队一起努力，破解水池之谜。', `MaleText_loc5`='這是趟很長的旅途，但我終於找到了恆春谷。現在我和哨兵們合作，想要了解這些池子的神秘之處。', `MaleText_loc7`='Ha sido un largo viaje, pero por fin he encontrado el valle. Ahora colaboro con las Centinelas para desvelar los misterios de las pozas.' WHERE `ID`=68296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신의 신뢰를 얻어 골짜기 문을 여는 데는 성공했지만, 앞으로도 계속 우리가 평화의 임무를 띠고 왔다는 걸 보여야 해요.', `MaleText_loc4`='我们设法赢得了天神的信任，打开了山谷的大门，可我们必须继续向他们表明，我们肩负着和平的使命。', `MaleText_loc5`='我們成功地獲得天尊們的信任並打開了恆春谷，但我們得繼續讓祂們看到我們是為了和平的任務而來。', `MaleText_loc7`='Hemos conseguido granjearnos la confianza de los Celestiales y abrir el valle, pero debemos seguir demostrándoles que la nuestra es una misión de paz.' WHERE `ID`=68297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이토록 많은 사람들이 고향인 쿤라이를 떠나야 했다니 가슴 아픈 일이에요. 보호가 필요한 이들이 머물 수 있는 안식처를 찾아서 다행이에요.', `MaleText_loc4`='看见那么多人被迫离开昆莱山的家园，这令我倍感煎熬。幸好我们为那些寻求庇护的人们找到了避风港。', `MaleText_loc5`='看到這麼多人因戰亂而逃離他們在崑萊的家園讓我十分心痛。我很高興我們為那些需要受到保護的人們找到了一個安全的避風港。', `MaleText_loc7`='Me duele ver a tantos refugiados alejados de sus hogares de Kun-Lai, pero me alegro de que hayamos podido acoger a aquellos que necesitan protección.' WHERE `ID`=68298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수대와 크라사랑 밀림에서 지내던 때 이야기를 했어요. 제가 츠지 사원에서의 모험담을 들려줬지요.', `MaleText_loc4`='哨兵部队与我交换了在卡桑琅丛林经历的故事。我把自己在赤精寺院里的冒险奇遇告诉了他们。', `MaleText_loc5`='哨兵和我交換了我們在喀撒朗蠻荒中的故事。我把關於我在赤吉神廟的探險過程全部告訴了他們。', `MaleText_loc7`='Las Centinelas y yo nos hemos contado historias del tiempo que hemos pasado en la Espesura Krasarang. Les he contado todas mis aventuras en el Templo de Chi-Ji.' WHERE `ID`=68299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 다니면 다닐수록, 판다렌이란 종족이 맘에 듭니다. 맛있는 음식과 술도 한몫 했겠지요.', `MaleText_loc4`='我在这片土地上游历得越久，就越喜欢这群熊猫人。唯爱佳肴美酒，平生与世无争。', `MaleText_loc5`='我越是在這片土地上旅行，我就越喜歡熊貓人。更別說這麼美好的食物和酒啦。', `MaleText_loc7`='Cuanto más viajo por esta tierra, más aprecio a los pandaren. La deliciosa comida y la bebida también ayuda.' WHERE `ID`=68300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅을 여행하며 정말 많은 것을 보았습니다. 더 성숙하고 더... 현명해진 것 같은 기분이에요.', `MaleText_loc4`='我在这片土地上旅行时，目睹了许多见闻。我感觉自己长大了一些……也许还略微……睿智了点儿。', `MaleText_loc5`='我在這片土地上的旅途中看過許多事物。我感覺老了些，也許還...更有智慧了點。', `MaleText_loc7`='He visto muchas cosas durante mis viajes por esta tierra. Me siento mayor, y quizá hasta un poco más... sabio.' WHERE `ID`=68301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 얼라이언스의 미래가 판다리아의 미래와 직결되어 있다고 생각합니다.$B$B우리는 여기 착륙한 후로 몇 가지 사건을 일으켰습니다. 용의 심장이 함락되었을 때 현장에 있었고, 전승지기 초의 미래상이 실현되는 걸 도왔다고 할 수도 있지요.$B$B그렇기 때문에 모든 일을 바로잡기 전에는 스톰윈드로 돌아갈 수 없다는 겁니다.', `MaleText_loc4`='我相信联盟的未来与潘达利亚息息相关。$B$B在我们抵达这里后，就开始按部就班地采取行动。当神龙之心陷落时，我们就在那里。从某种意义上说，我们也参与促成了游学者周卓预见的实现。$B$B正因如此，在一切重回正途之前，我无法返回暴风城。', `MaleText_loc5`='我相信聯盟的未來和潘達利亞的未來息息相關。$B$B我們在此登陸後，推動了一些事情的發生與進展。蟠龍之心陷落時我們也在場。從某方面來說，我們幫助實現了博學行者阿洲所預見的未來。$B$B因此，在我幫忙將事物導正之前，我沒辦法回到暴風城去。', `MaleText_loc7`='Creo que el futuro de la Alianza está unido al de Pandaria.$b$bCuando desembarcamos aquí, dimos comienzo a ciertos acontecimientos. Estábamos presentes cuando cayó el Corazón del Dragón. En cierto modo, contribuimos a que se cumpliera la visión de futuro del eremita Cho.$b$bEs por eso que no puedo volver a Ventormenta hasta que hayamos arreglado las cosas.' WHERE `ID`=68302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병사들이여, 우린 정예병이다. 하늘불꽃호의 선원들이다. 이건 우리의 임무다!', `FemaleText_loc4`='兄弟们，你们都是受过严格训练的。你们都是精英，天火号的精英！', `FemaleText_loc5`='你們都受過嚴苛的訓練。你們是精英中的精英。你們隸屬於天火號!', `FemaleText_loc7`='Soldados, están entrenados para esto. Son la élite. ¡Son los soldados de El Abrasacielos!' WHERE `ID`=68303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 배는 데스윙을 쓰러뜨렸다. 보잘것없는 호드 따위가 자랑스러운 얼라이언스 함선을 막아낼 수 있을까? 그럴 수는 없다!', `FemaleText_loc4`='这艘船曾经击败过死亡之翼。你们觉得那又小又破的部落前哨能跟联盟舰队的骄傲抗衡吗？不可能！', `FemaleText_loc5`='這是擊落死亡之翼的船。你們覺得破爛的部落哨站能跟聯盟艦隊的驕傲匹敵嗎?絕不!', `FemaleText_loc7`='Esta es la nave que abatió a Alamuerte. ¿Creen que una burda avanzadilla de la Horda tiene la más mínima posibilidad contra el orgullo de la flota de la Alianza? ¡NI HABLAR!' WHERE `ID`=68304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파수대와 크라사랑 밀림에서 지내던 때 이야기를 했어요. 제가 츠지 사원에서의 모험담을 들려줬지요.', `MaleText_loc4`='哨兵部队与我交换了在卡桑琅丛林经历的故事。我把我们在赤精寺院里的冒险奇遇告诉了他们。', `MaleText_loc5`='哨兵和我交換了我們在喀撒朗蠻荒中的故事。我把關於我在赤吉神廟的探險過程全部告訴了他們。', `MaleText_loc7`='Las Centinelas y yo nos hemos contado historias del tiempo que hemos pasado en la Espesura Krasarang. Les he contado todas nuestras aventuras en el Templo de Chi-Ji.' WHERE `ID`=68305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 초록색 괴물들이 남녘해안의 우리 보금자리를 약탈했다. 붉은마루 산맥의 아이들을 공격했다. 테라모어의 남녀노소를 학살했다.', `FemaleText_loc4`='下面那些绿皮渣滓摧毁了你们在南海镇的家园，封锁了孩子们在赤脊山玩耍的乐土，还把塞拉摩的妇孺屠杀殆尽。', `FemaleText_loc5`='下面那些綠綠的臭傢伙在你們南海鎮的家園肆虐，攻打你們赤脊山的孩子，還屠殺了塞拉摩島上的每一個人。', `FemaleText_loc7`='Esa escoria verde de ahí abajo infectó sus hogares en Costasur, asedió a sus hijos en Crestagrana y masacró a todo hombre, mujer y niño en Theramore.' WHERE `ID`=68306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제, 복수의 시간이다!', `FemaleText_loc4`='报仇的时刻到了！', `FemaleText_loc5`='報仇的時候到了!', `FemaleText_loc7`='Es... la hora... ¡DE LA VENGANZA!' WHERE `ID`=68307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 싸워선 안 됩니다. 이렇겐 안 돼요!', `MaleText_loc4`='我们不该在这里战斗。不该这样！', `MaleText_loc5`='我們不應該在這裡戰鬥。不能如此!', `MaleText_loc7`='No deberíamos luchar aquí. ¡No así!' WHERE `ID`=68308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 우리에게 많은 것을 베풉니다. 우리는 그저 옳은 방법으로 받아들이기만 하면 되지요. 원하신다면, 제가 그 방법을 알려드리겠습니다.', `MaleText_loc4`='只要我们学会如何适当地索取，大地就会给予我们许多馈赠。如果你愿意的话，我会教你如何做。', `MaleText_loc5`='大地能提供我們許多東西，只要我們能夠學習如何適度地去汲取。只要你想，我能教導你如何辦到。', `MaleText_loc7`='La tierra tiene mucho que ofrecernos siempre y cuando aprendamos a tomarlo con prudencia. Yo puedo enseñarte, si quieres.' WHERE `ID`=68312;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 분이 아니시군요. 판다리아의 토종 식물들에 대해 알아보고 싶지 않으세요?', `FemaleText_loc4`='你不是本地人。有兴趣了解下潘达利亚的原生植物吗？', `FemaleText_loc5`='你不是這附近的人。你有興趣學習潘達利亞土生土長的植物知識嗎?', `FemaleText_loc7`='No eres de por aquí. ¿Te interesa estudiar las plantas nativas de Pandaria?' WHERE `ID`=68314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅의 짐승들은 자네 고향의 녀석들과는 많이 다르네. 나와 함께 훈련을 하면, 여기서 가죽을 벗기는 새로운 방식을 배울 수 있을 걸세.', `MaleText_loc4`='这片土地上的野兽与你家乡那些截然不同。随我训练，你也许就能学会给它们剥皮的技巧。', `MaleText_loc5`='這片土地上的野獸不像你家鄉的任何野獸。接受我的訓練，你才能知道如何正確地剝取牠們的毛皮。', `MaleText_loc7`='Las bestias de esta tierra no se parecen a las de tu hogar. Yo te puedo enseñar a desollarlas como es debido.' WHERE `ID`=68315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피를 부르는 자오진이 문을 돌파하려 하고 있어요! 그가 궁전 금고로 들어가지 못하게 막아야 해요!', `FemaleText_loc4`='放血者兆金在冲击大门！我们必须阻止他进入宫殿内室！', `FemaleText_loc5`='『放血者』趙進衝向城門了!我們必須阻止他進入宮殿的寶庫。', `FemaleText_loc7`='¡Zhao-Jin el Sajador asalta las puertas! ¡Debemos detenerlo antes de entrar en las cámaras del palacio!' WHERE `ID`=68316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 샤오티엔을 무찌르지 못하면 가망이 없어요!', `FemaleText_loc4`='要是我们现在不击败韶天，就要满盘皆输了！', `FemaleText_loc5`='如果我們現在不擊敗嘯天，那一切都完了!', `FemaleText_loc7`='Si no derrotamos al Shao-Tien ahora, ¡todo estará perdido!' WHERE `ID`=68318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 다른 모구가 궁전 계단에 오르지 못하게 막고 있습니다. 서두르세요!', `MaleText_loc4`='我正在阻止其他魔古族接近宫殿阶梯。赶快！', `MaleText_loc5`='我正在阻擋其他魔古進入宮殿的階梯。趕快!', `MaleText_loc7`='Yo impido que los demás mogu entren en las escaleras del palacio. ¡Date prisa!' WHERE `ID`=68320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀려선... 안... 돼!', `MaleText_loc4`='我……必须……坚持住！', `MaleText_loc5`='我...必須...撐住!', `MaleText_loc7`='Tengo... que... aguantar...' WHERE `ID`=68321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 방어벽을 유지하는 데는 한계가 있습니다! 얼른, 궁전 계단에 있는 장군을 처치해 주세요!', `MaleText_loc4`='我不可能永远守住这道障碍。赶快，你必须去宫殿阶梯上解决督军！', `MaleText_loc5`='我無法永遠地支持住這道屏障。快點，你必須料理掉宮殿階梯上的督軍!', `MaleText_loc7`='No puedo sostener la barrera eternamente. ¡Tienes que encargarte del señor de la guerra en las escaleras del palacio!' WHERE `ID`=68322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리요, $r님! 우리 진영은 서로 적대하고 있지만, 지금은 더 큰 우환이 있습니다!', `MaleText_loc4`='赶快，$r！我们双方也许正在交战，可眼下正面临着更大的威胁！', `MaleText_loc5`='趕快，$r!我們的陣營也許在交戰，但此刻我們有更大的隱憂!', `MaleText_loc7`='¡Date prisa, $r! Es posible que nuestras facciones estén en guerra, ¡pero ahora mismo tenemos problemas más acuciantes!' WHERE `ID`=68323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움에 힘을 보태러 왔네. 내가 도울 일이 있는가?', `MaleText_loc4`='我是来帮忙作战的。我能做些什么吗？', `MaleText_loc5`='我是來此協助戰鬥的。有什麼事是我幫得上忙的嗎?', `MaleText_loc7`='He venido para prestar mi ayuda en la lucha. ¿Hay algo que pueda hacer?' WHERE `ID`=68324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFE9A2E불길잡이 정령|r을 소환하기 시작합니다! 불꽃의 벽을 막으려면 정령을 처치하십시오!', `MaleText_loc4`='%s开始召唤|cFFFE9A2E伪焰之灵|r！击败它们，阻止火墙！', `MaleText_loc5`='%s開始召喚|cFFFE9A2E誘火之靈|r!擊敗他們以阻止烈焰之牆!', `MaleText_loc7`='¡%s empieza a invocar |cFFFE9A2Eespíritus persuadellamas|r! ¡Derrótalos para detener el muro de llamas!' WHERE `ID`=68325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님? 여기서 뭐하고 계십니까? 어서 하늘불꽃호에 올라타십시오! 어서요! 차원문을 사용하십시오!', `MaleText_loc4`='$n？你在这里做什么？天火号上需要你！赶快，使用传送门！', `MaleText_loc5`='$n?你在這裡做什麼?我們需要你到天火號上面去!快點，進入傳送門中!', `MaleText_loc7`='¿$n? ¿Qué haces aquí? ¡Te necesitamos en el Abrasacielos! ¡Usa el portal, rápido!' WHERE `ID`=68326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도렌 대장님이 시간이 더 필요하다. 적을 막아!', `MaleText_loc4`='再给多伦一点时间。坚持住！', `MaleText_loc5`='多倫只需要再多一點點的時間。守住防線!', `MaleText_loc7`='Doren solo necesita un poco de tiempo. ¡Mantengan posiciones!', `FemaleText_loc1`='저 호드 악당 녀석이 지나가게 하지 마!', `FemaleText_loc4`='别让部落渣滓通过！', `FemaleText_loc5`='別讓部落的雜碎通過!', `FemaleText_loc7`='¡No dejen entrar a la escoria de la Horda!' WHERE `ID`=68327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 번째 방벽이 폭파되고 적이 침입했습니다! 맞서 싸우십시오!', `MaleText_loc4`='他们已经突破第二道障碍了！击退他们！', `MaleText_loc5`='他們已經突破了第二道封鎖線了!擊退他們!', `MaleText_loc7`='¡Ya han destrozado la segunda barricada! ¡Contraataquen!', `FemaleText_loc1`='두 번째 방벽이 폭파되고 적이 침입했습니다! 맞서 싸우십시오!', `FemaleText_loc4`='他们已经突破第二道障碍了！击退他们！', `FemaleText_loc5`='他們已經突破了第二道封鎖線了!擊退他們!', `FemaleText_loc7`='¡Ya han destrozado la segunda barricada! ¡Contraataquen!' WHERE `ID`=68328;
