UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 우리가 도박을 했던 일은 잊고, 바쁜 일상을 계속 살아가는 게 어떻겠나?', `MaleText_loc4`='那么……不如我们先别打赌了，继续过我们忙碌的生活吧？', `MaleText_loc5`='嗯...讓我們忘記我們的小賭注，然後繼續各忙各的，你覺得如何?', `MaleText_loc7`='Esto... ¿qué tal si nos olvidamos de esa pequeña apuesta y seguimos con nuestras vidas?' WHERE `ID`=68332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 사기 치려는 거 아닌가? 어림도 없네!', `MaleText_loc4`='想骗我是吧？没那么容易！', `MaleText_loc5`='想要這麼快就打發我，是吧?別想!', `MaleText_loc7`='¿Crees que puedes conmigo? ¡No tan rápido!' WHERE `ID`=68333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께 이 땅에서 놈들을 몰아내자. 그러면 너희는 호드와 함께 당당히 일어설 수 있다!', `MaleText_loc4`='帮我们铲除他们，你的族人就能挺起胸膛傲然屹立在部落身边！', `MaleText_loc5`='幫我們，從你們的土地趕走他們，你們就能驕傲地跟部落站在一起!', `MaleText_loc7`='Ayúdanos a echarlos de tu tierra y tu gente podrá unirse con orgullo a la Horda.' WHERE `ID`=68334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 극적으로 나타나는 건 보지 못했는데...', `MaleText_loc4`='我已经好多年没见到它显现得如此强烈了。', `MaleText_loc5`='我已經好幾年沒看到它如此戲劇化的現身。', `MaleText_loc7`='Hacía muchos años que no la veía manifestarse de forma tan siniestra.' WHERE `ID`=68335;
