UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $n 덕분에 샤오티엔의 지도자, 자오진이 죽었다네!', `MaleText_loc4`='是的，多亏了$n。韶天领袖兆金已经被杀死了！', `MaleText_loc5`='是的，多虧了$n。嘯天的首領趙進已經被殺死了。', `MaleText_loc7`='Sí. Gracias a $n Zhao-Jin, el líder del Shao-Tien, ¡está muerto!' WHERE `ID`=68346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천신들의 도움으로 모구의 진군을 막아냈어요. 우리 병사들이 잔당을 처치하고 골짜기에서 모구를 몰아냈죠.', `FemaleText_loc4`='在天神的帮助下，我们粉碎了魔古族的进攻。我们的士兵们得以清理残余，将他们赶出山谷。', `FemaleText_loc5`='有了天尊們的協助，我們把魔古的進攻打得潰不成軍。我們的士兵解決了剩下的殘黨，並將他們趕出了峽谷。', `FemaleText_loc7`='Hemos destrozado el avance de los mogu con ayuda de los celestiales. Nuestros soldados han podido encargarse del resto y echarlos del valle.' WHERE `ID`=68347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레벤! 살아 있었군! 그렇다면...', `MaleText_loc4`='莱文！你还活着！那意味着……', `MaleText_loc5`='利文!你還活著!那表示...', `MaleText_loc7`='¡Leven! ¡Estás vivo! Eso significa...' WHERE `ID`=68348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구와의 전쟁은 아직 끝나지 않았네. 그러나 오늘만큼은 쉬면서 승리를 자축해야지.', `MaleText_loc4`='我们对抗魔古的战争还远未结束。但今天我们可以稍作休息，欢庆胜利。', `MaleText_loc5`='我們對抗魔古的戰爭還沒結束。但今天我們能休息一下，並稱頌我們的勝利。', `MaleText_loc7`='Nuestra guerra contra los mogu no ha terminado, pero hoy podemos descansar y cantar victoria.' WHERE `ID`=68349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 $n|1을;를; 위해 만세를 불러라! 샤오티엔의 정복자, 민중의 수호자여! 별들이 그대의 이름을 노래하기를!', `MaleText_loc4`='向你致敬，$n！你是山谷的救星，韶天征服者，人民的卫士！愿星辰吟诵你的大名！', `MaleText_loc5`='為$n歡呼，恆春谷的救星!嘯天的征服者，人們的防衛者!願天上星辰歌頌你的名字!', `MaleText_loc7`='¡Tres hurras por $n, $gsalvador:salvadora; del valle, $gconquistador:conquistadora; del Shao-Tien y $gdefensor:defensora; del pueblo! ¡Que las estrellas canten tu nombre!' WHERE `ID`=68350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에 꽂힌 안개주술사의 횃불을 뽑으십시오!', `MaleText_loc4`='把迷雾萨满的火把从地里拔出来！', `MaleText_loc5`='把迷霧薩滿的火炬從地上拔起來!', `MaleText_loc7`='¡Saca la antorcha del chamán de la niebla del suelo!' WHERE `ID`=68351;
