UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가야겠소. 남쪽 해안에 다른 자들이 나타났으니까.', `MaleText_loc4`='我必须离开了——还有其他人登上了我们南方的海岸。', `MaleText_loc5`='我必須走了.還有其他人在我們的南邊海岸登陸。', `MaleText_loc7`='Debo irme. Hay más forasteros en la costa sur.' WHERE `ID`=68383;
