UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 두려움이 뭔지 보여주겠소.', `MaleText_loc4`='让他们瞧瞧痛苦的真正含义。', `MaleText_loc5`='讓他們見識痛苦的真正意義。', `MaleText_loc7`='Demuéstrales lo que significa el dolor verdadero.' WHERE `ID`=68430;
