UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 승리가 확실하다고 생각했소. 창조자들은 분명히 다른 계획을 가지고 있구려.', `MaleText_loc4`='我以为自己赢定了。可造物主显然另有安排。', `MaleText_loc5`='我還以為我的勝利已經到手了。顯然造物之神有其他計畫。', `MaleText_loc7`='Creía que mi victoria estaba asegurada. Es evidente que los Creadores tenían otros planes.' WHERE `ID`=68438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직은 네가 죽을 때가 아니다.', `MaleText_loc4`='你的时间还未到。', `MaleText_loc5`='你的時候還未到。', `MaleText_loc7`='Tu hora no ha llegado aún.' WHERE `ID`=68439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조자의 눈으로 볼 땐 그저 하찮은 일일 뿐이오.', `MaleText_loc4`='只是造物主眼中的微小尘埃。', `MaleText_loc5`='在造物之神眼中根本微不足道。', `MaleText_loc7`='Nada más que un destello a ojos de los Creadores.' WHERE `ID`=68440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 생각했던 것보다 강하군.', `MaleText_loc4`='你比我想象中强大。', `MaleText_loc5`='你比我想的還要強大。', `MaleText_loc7`='Eres más fuerte de lo que pensaba.' WHERE `ID`=68441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 언제 싸울 수 있을지 궁금했습니다.', `MaleText_loc4`='我一直在想，什么时候才能与你对决。', `MaleText_loc5`='我一直在想我什麼時候會對上你。', `MaleText_loc7`='Me preguntaba cuándo podría luchar contigo.' WHERE `ID`=68442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강이 제게 이렇게 될 것이라고 말했습니다!', `MaleText_loc4`='湖水告诉我会是这样！', `MaleText_loc5`='湖告訴我會是這樣!', `MaleText_loc7`='¡El lago me dijo que sucedería así!' WHERE `ID`=68443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물의 지혜를 제가 잘못 이해한 게 틀림 없습니다.', `MaleText_loc4`='我一定是误解了水流的智慧。', `MaleText_loc5`='我一定是誤解了水的智慧。', `MaleText_loc7`='Debo de haber malinterpretado la sabiduría del agua.' WHERE `ID`=68444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물밑에는 많은 것들이 숨어 있지요.', `MaleText_loc4`='表面之下，暗流汹涌。', `MaleText_loc5`='有很多事不能只看表面。', `MaleText_loc7`='Se ocultan muchas cosas bajo la superficie.' WHERE `ID`=68445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝이 없는 물결이 또 다른 희생자를 만들어냈군요.', `MaleText_loc4`='被无尽潮水夺去的又一条生命。', `MaleText_loc5`='另一個被無盡浪潮吞沒的受害者。', `MaleText_loc7`='Otra víctima de la marea sin fin.' WHERE `ID`=68446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물속 깊은 곳에 무덤 하나를 더 만들어야겠군요.', `MaleText_loc4`='深渊中的又一座坟墓。', `MaleText_loc5`='水底又多了一個墳墓。', `MaleText_loc7`='Una tumba más en las profundidades.' WHERE `ID`=68447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 하면 위대한 천신회를 도울 수 있습니까?', `MaleText_loc4`='我现在如何帮助至尊天神？', `MaleText_loc5`='我要如何幫助聖獸天尊?', `MaleText_loc7`='¿Cómo puedo ayudar a los Augustos Celestiales?', `FemaleText_loc1`='어떻게 하면 위대한 천신회를 도울 수 있나요?', `FemaleText_loc4`='我现在如何帮助至尊天神？', `FemaleText_loc5`='我要如何幫助聖獸天尊?', `FemaleText_loc7`='¿Cómo puedo ayudar a los Augustos Celestiales?' WHERE `ID`=68448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황금 연꽃과 매우 우호적 평판을 달성하면, 위대한 천신회를 도울 수 있습니다.$B$B동쪽으로는 위론 님의 사원이 의심의 샤에게 공격받고 있습니다.$B$B남쪽으로는, 츠지 님의 수련생들이 공격으로 무너진 사원을 재건하며 수련하고 있습니다.$B$B북쪽으로는 쉬엔 님께서 투기장에 찾아오는 용사들의 힘을 시험하고 계시지요.$B$B마지막으로 서쪽으로는, 니우짜오 님께서 판다리아에서 가장 위험한 적을 상대로 버티고 계십니다.', `FemaleText_loc4`='等你与金莲教的关系达到崇敬后，你就能帮助至尊天神了。$B$B在东面，玉珑的寺院正在遭受疑之煞的攻击。$B$B在南面，赤精的学徒正在寺院遭到攻击后，进行重建与复训。$B$B在北面，雪怒正在考验那些竞技勇士的力量。$B$B在西面，砮皂正警惕地注视着潘达利亚大陆上最危险的敌人。', `FemaleText_loc5`='在你得到金蓮的崇敬地位後，你就能幫助聖獸天尊。$B$B在東方，玉龍的神廟正遭受疑惑之煞的攻擊。$B$B在南方，赤吉的門徒們在神廟被攻擊後正進行著重建和重新訓練。$B$B在北方，雪怒考驗著進入他競技場中夠資格的戰士們的力量。$B$B而在西方，怒兆警戒地對抗著一些潘達利亞中最危險的敵人。', `FemaleText_loc7`='Cuando hayas alcanzado el estado de $gvenerado:venerada; con el Loto Dorado, podrás ayudar a los Augustos Celestiales.$b$bAl este, el Sha de la duda ataca el templo de Yu''lon.$b$bAl sur, los aprendices de Chi-Ji están reconstruyendo y entrenándose después del ataque a su templo.$b$bAl norte, Xuen pone a prueba la fuerza de los valientes combatientes que entran en su dominio.$b$bAl oeste, Niuzao se alza firme contra algunos de los enemigos más peligrosos de Pandaria.' WHERE `ID`=68449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 연꽃과 매우 우호적 평판을 달성하면, 위대한 천신회를 도울 수 있습니다.$B$B동쪽으로는 위론 님의 사원이 의심의 샤에게 공격받고 있습니다.$B$B남쪽으로는, 츠지 님의 수련생들이 공격으로 무너진 사원을 재건하며 수련하고 있습니다.$B$B북쪽으로는 쉬엔 님께서 투기장에 찾아오는 용사들의 힘을 시험하고 계시지요.$B$B마지막으로 서쪽으로는, 니우짜오 님께서 판다리아에서 가장 위험한 적을 상대로 버티고 계십니다.', `MaleText_loc4`='等你与金莲教的关系达到崇敬后，你就能帮助至尊天神了。$B$B在东面，玉珑的寺院正在遭受疑之煞的攻击。$B$B在南面，赤精的学徒正在寺院遭到攻击后，进行重建与复训。$B$B在北面，雪怒正在考验那些竞技勇士的力量。$B$B在西面，砮皂正警惕地注视着潘达利亚大陆上最危险的敌人。', `MaleText_loc5`='在你得到金蓮的崇敬地位後，你就能幫助聖獸天尊。$B$B在東方，玉龍的神廟正遭受疑惑之煞的攻擊。$B$B在南方，赤吉的門徒們在神廟被攻擊後正進行著重建和重新訓練。$B$B在北方，雪怒考驗著進入他競技場中夠資格的戰士們的力量。$B$B而在西方，怒兆警戒地對抗著一些潘達利亞中最危險的敵人。', `MaleText_loc7`='Cuando hayas alcanzado el estado de $gvenerado:venerada; con el Loto Dorado, podrás ayudar a los Augustos Celestiales.$b$bAl este, el Sha de la duda ataca el templo de Yu''lon.$b$bAl sur, los aprendices de Chi-Ji están reconstruyendo y entrenándose después del ataque a su templo.$b$bAl norte, Xuen pone a prueba la fuerza de los valientes combatientes que entran en su dominio.$b$bAl oeste, Niuzao se alza firme contra algunos de los enemigos más peligrosos de Pandaria.' WHERE `ID`=68450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경매장을 이용하시려면 대도시에 가셔야 합니다.', `MaleText_loc4`='你可以在自己的主城里使用拍卖行服务。', `MaleText_loc5`='你可以在你的主城裡找到拍賣場的服務。', `MaleText_loc7`='Los servicios de la casa de subastas están disponibles en tu capital.', `FemaleText_loc1`='경매장을 이용하시려면 대도시에 가셔야 합니다.', `FemaleText_loc4`='你可以在自己的主城里使用拍卖行服务。', `FemaleText_loc5`='你可以在你的主城裡找到拍賣場的服務。', `FemaleText_loc7`='Los servicios de la casa de subastas están disponibles en tu capital.' WHERE `ID`=68451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이지! 마음껏 타렴.', `FemaleText_loc4`='当然！别客气。', `FemaleText_loc5`='當然!你請自便。', `FemaleText_loc7`='¡Claro! Ustedes mismos.' WHERE `ID`=68452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와아아아아아!', `MaleText_loc4`='咦！', `MaleText_loc5`='呀呼呼呼!', `MaleText_loc7`='¡Ueeeeee!' WHERE `ID`=68453;
