UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연 아줌마 고마워요!', `MaleText_loc4`='感谢风筝女士！', `MaleText_loc5`='謝啦風箏小姐!', `MaleText_loc7`='¡Gracias, señorita de la cometa!' WHERE `ID`=68455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 지도자가 이 방벽 뒤에 숨어 있네. 겁쟁이 같으니. 돌입할 준비가 되면 알려주게.', `MaleText_loc4`='他们怯懦的首领就躲在这道屏障后面。你准备好了就告诉我。', `MaleText_loc5`='他們的領袖躲在防禦工事後面，懦夫。你準備好進攻時跟我說。', `MaleText_loc7`='Su líder es tan cobarde que se ha atrincherado detrás de la barricada. Avísame cuando quieras que avancemos.' WHERE `ID`=68456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 내가 좋아하는 곡이라오!', `MaleText_loc4`='耶！我喜欢这首歌！', `MaleText_loc5`='耶!我愛死這首曲子了!', `MaleText_loc7`='¡Sí! ¡Me encanta esta canción!' WHERE `ID`=68457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='메뚜기 귀엽죠? 한 마리 갖고 싶으세요?', `FemaleText_loc4`='那是只很酷的蚱蜢对吧？想要一只属于你自己的吗？', `FemaleText_loc5`='那是隻很酷的蚱蜢對吧?想要一隻嗎?', `FemaleText_loc7`='Es un saltamontes de lo más chulo, ¿verdad? ¿Quieres uno?' WHERE `ID`=68458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 애완동물 조련사가 되려면 어떻게 해야 합니까?', `MaleText_loc4`='我怎样才能成为一名战斗宠物训练师？', `MaleText_loc5`='我要如何成為一名戰寵訓練師?', `MaleText_loc7`='¿Cómo me convierto en entrenador de mascotas de duelo?', `FemaleText_loc1`='전투 애완동물 조련사가 되려면 어떻게 해야 하나요?', `FemaleText_loc4`='我怎样才能成为一名战斗宠物训练师？', `FemaleText_loc5`='我要如何成為一名戰寵訓練師?', `FemaleText_loc7`='¿Cómo me convierto en entrenadora de mascotas de duelo?' WHERE `ID`=68459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드에 있는 오드리 번헵에게 이야기하시면 돼요! 가서 경비병에게 물어보면 길을 알려줄 거예요.$b$b제단 안에 스톰윈드로 통하는 차원문이 있답니다. 행운을 빌게요!', `FemaleText_loc4`='你得去暴风城，找奥黛丽·伯恩赫普聊聊！城里的任何一名守卫都能为你指路。$b$b在寺院里有传送门，可以将你传送过去。祝你好运！', `FemaleText_loc5`='你必須和暴風城中的奧德雷·燃憂談談!任何那裡的守衛應該都能給你指引找到她。$b$b你能在神廟中找到一個通往暴風城的傳送門。祝你好運!', `FemaleText_loc7`='¡Tienes que hablar con Audrey Burnhep en Ventormenta! Todos los guardias de la ciudad sabrán decirte dónde está.$b$bHay un portal a Ventormenta dentro del templo. ¡Buena suerte!' WHERE `ID`=68460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='특이한 애완둥물을 이렇게 많이 본 적이 있나요? 직접 잡고 싶으세요?', `FemaleText_loc4`='你见过这么多独特的宠物吗？想不想给自己抓几只？', `FemaleText_loc5`='你有看過這麼多獨特的寵物嗎?有興趣為你自己抓幾隻嗎?', `FemaleText_loc7`='¿Alguna vez habías visto tantas mascotas únicas? ¿Te interesa atrapar algunas?' WHERE `ID`=68461;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사부 우의 방어가 최대치에 근접하고 있습니다. 절명의 손길을 써서 마무리해야 합니다!', `FemaleText_loc4`='吴大师的防御力已经接近极限。使用轮回之触来终结她！', `FemaleText_loc5`='吳大師的防禦已經接近其最大潛能。使用幽冥掌來了結她!', `FemaleText_loc7`='Las defensas de la maestra Woo se acercan al potencial máximo. ¡Utiliza Toque de la muerte para acabar con ella!' WHERE `ID`=68462;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 애완 원숭이 어때요? 귀엽죠?', `FemaleText_loc4`='你觉得我的宠物猴怎么样？很酷对吧？', `FemaleText_loc5`='你覺得我的寵物猴子如何?很酷對吧?', `FemaleText_loc7`='¿Qué te parece mi mono mascota? Es chulo, ¿verdad?' WHERE `ID`=68463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='혹시 희귀한 애완동물에 관심이 있지 않으세요?', `FemaleText_loc4`='你看起来似乎会对某些稀有宠物感兴趣？', `FemaleText_loc5`='你看起來像是會對稀有寵物有興趣的人?', `FemaleText_loc7`='Tienes pinta de estar $ginteresado:interesada; en las mascotas poco comunes.' WHERE `ID`=68464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 음료를 팔고 계십니까?', `MaleText_loc4`='你这有什么美酒出售吗？', `MaleText_loc5`='你有賣什麼酒?', `MaleText_loc7`='¿Qué bebidas tienes a la venta?', `FemaleText_loc1`='어떤 음료를 팔고 계세요?', `FemaleText_loc4`='你这有什么美酒出售吗？', `FemaleText_loc5`='你有賣什麼酒?', `FemaleText_loc7`='¿Qué bebidas tienes a la venta?' WHERE `ID`=68465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불필요한 폭력을 그냥 참고 있지는 않겠습니다!', `MaleText_loc4`='我不会容忍毫无必要的暴力！', `MaleText_loc5`='我不會容忍如此不必要的暴力行為!', `MaleText_loc7`='¡No toleraré la violencia innecesaria!' WHERE `ID`=68466;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 비행포격선의 진정한 힘을 적에게 보여줄 때만 기다리고 있었지. 자, 이제 포탄을 마구 퍼부어 줄까?!', `FemaleText_loc4`='我一直期待能用这战机歼灭强大的目标。让我们开火吧！', `FemaleText_loc5`='我一直在等著要用這砲艇對抗夠資格的目標。讓我們消耗一些彈藥吧!', `FemaleText_loc7`='Tengo ganas de probar esta nave de guerra contra un objetivo digno. ¡Vamos a gastar munición!' WHERE `ID`=68467;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오그리마에 있는 바르조크에게 이야기하시면 돼요! 가서 경비병에게 물어보면 길을 알려줄 거예요.$b$b제단 안에 오그리마로 통하는 차원문이 있답니다. 행운을 빌게요!', `FemaleText_loc4`='你应该去奥格瑞玛找瓦佐克聊聊！城里的任何卫兵都能为你指路。$b$b寺院里有通往奥格瑞玛的传送门，可以把你传送过去。祝你好运！', `FemaleText_loc5`='你必須和奧格瑪中的伐索克談談!任何那裡的守衛應該都能給你指引找到他。$b$b你能在神廟中找到一個通往奧格瑪的傳送門。祝你好運!', `FemaleText_loc7`='¡Tienes que hablar con Varzok en Orgrimmar! Todos los guardias de la ciudad sabrán decirte dónde está.$b$bHay un portal a Orgrimmar dentro del templo. ¡Buena suerte!' WHERE `ID`=68468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 정말 싫어하시는군요. 안 그렇습니까?', `MaleText_loc4`='你对部落真是深恶痛绝，对吧？', `MaleText_loc5`='你就真的得和部落過不去，是嗎?', `MaleText_loc7`='Realmente odias a la Horda, ¿no?', `FemaleText_loc1`='호드를 정말 싫어하시는군요. 안 그런가요?', `FemaleText_loc4`='你对部落真是深恶痛绝，对吧？', `FemaleText_loc5`='你就真的得和部落過不去，是嗎?', `FemaleText_loc7`='Realmente odias a la Horda, ¿no?' WHERE `ID`=68469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 팔고 계신 물건을 보고 싶습니다.', `MaleText_loc4`='让我看看你的货物。', `MaleText_loc5`='讓我看看你的貨品。', `MaleText_loc7`='Déjame ver tus mercancías.', `FemaleText_loc1`='당신이 팔고 계신 물건을 보고 싶어요.', `FemaleText_loc4`='让我看看你的货物。', `FemaleText_loc5`='讓我看看你的貨品。', `FemaleText_loc7`='Déjame ver tus mercancías.' WHERE `ID`=68470;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<얼굴이 딱딱하게 굳는 하늘 제독>$b$b나는 남녘해안에서 자랐네. 우리 부모님은 그곳에 묻히셨지. 부모님의 남은 부분 말이야.', `FemaleText_loc4`='<空军上将变得面色凝重。>$b$b我从小在南海镇长大。我的双亲……的遗骸……都被埋在那里。', `FemaleText_loc5`='<空軍上將的表情變得僵硬。>$b$b我是在南海鎮長大的，而我的父母 – 他們的殘骸就被葬在那。', `FemaleText_loc7`='<El rostro de la almirante se endurece.>$B$BCrecí en Costasur. Mis padres están enterrados allí... lo que quedó de ellos.' WHERE `ID`=68471;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이들 판다렌은 선량한 주민들인 것 같네.$b$b이 전쟁에 함께 엮이고 싶지는 않은 것 같지만, 몇 주 정도 호드를 상대하다 보면, 틀림없이 우리 편이 될 걸세.', `FemaleText_loc4`='这些熊猫人看起来都是好人。$b$b他们不愿意卷入我们的战争，可在与部落纠缠几个星期之后，相信他们一定会站到我们这边来。', `FemaleText_loc5`='這些熊貓人看起來是群好人。$b$b他們並不想被捲入我們的戰爭，但在和部落周旋幾星期後，我相信他們全都會到我們這一方來。', `FemaleText_loc7`='Estos pandaren parecen buena gente.$b$bSon reacios a verse inmiscuidos en nuestra guerra, pero dales unas semanas con la Horda y verás que acabarán pasándose a nuestro bando.' WHERE `ID`=68472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 준비가 끝났습니다! 카즈티크에 집중하도록 도와주십시오.', `MaleText_loc4`='我做好战斗准备了！帮我集中精神，卡兹提克。', `MaleText_loc5`='我準備好戰鬥了!幫助我專注，卡茲提克。', `MaleText_loc7`='¡Estoy listo para la batalla! Ayúdame a concentrarme, Kaz''tik.', `FemaleText_loc1`='전투 준비가 끝났어요! 카즈티크에 집중하도록 도와주세요.', `FemaleText_loc4`='我做好战斗准备了！帮我集中精神，卡兹提克。', `FemaleText_loc5`='我準備好戰鬥了!幫助我專注，卡茲提克。', `FemaleText_loc7`='¡Estoy lista para la batalla! Ayúdame a concentrarme, Kaz''tik.' WHERE `ID`=68473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저건 뭐지?!', `MaleText_loc4`='那……那是什么？！', `MaleText_loc5`='那...那是什麼?!', `MaleText_loc7`='¡¿Qué... qué es eso?!' WHERE `ID`=68474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌 풍선에 비해 너무 큰데... 이방인들 것인가?', `MaleText_loc4`='熊猫人可没有那么大的气球……是外乡人的吗？', `MaleText_loc5`='那比任何熊貓人氣球都還要大上許多...那是外來者的嗎?', `MaleText_loc7`='Es mucho más grande que los globos pandaren... ¿Será propiedad de los forasteros?' WHERE `ID`=68475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저... 저건 무슨 날아다니는 고래 같은 건가?', `MaleText_loc4`='那是……那是什么巨型飞鲸吗？', `MaleText_loc5`='那...那是某種巨大的飛天鯨嗎?', `MaleText_loc7`='¿Es... es una ballena voladora gigante?' WHERE `ID`=68476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함포 장전 완료!', `MaleText_loc4`='炮弹已装填！', `MaleText_loc5`='火砲裝填完成!', `MaleText_loc7`='¡Cañón cargado!', `FemaleText_loc1`='함포 장전 완료!', `FemaleText_loc4`='炮弹已装填！', `FemaleText_loc5`='火砲裝填完成!', `FemaleText_loc7`='¡Cañón cargado!' WHERE `ID`=68477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 해주십시오. 힘을 올리고 싶습니다. <10,000 골드를 지불합니다.>', `MaleText_loc4`='物有所值。我希望提升自己的力量。<付10,000金币。>', `MaleText_loc5`='很值得。我想要強化我的力量。<付10,000金。>', `MaleText_loc7`='Merece la pena. Deseo aumentar mi fuerza. <Paga 10000 de oro.>', `FemaleText_loc1`='그래도 해주세요. 힘을 올리고 싶어요. <10,000 골드를 지불합니다.>', `FemaleText_loc4`='物有所值。我希望提升自己的力量。<付10,000金币。>', `FemaleText_loc5`='很值得。我想要強化我的力量。<付10,000金。>', `FemaleText_loc7`='Merece la pena. Deseo aumentar mi fuerza. <Paga 10000 de oro.>' WHERE `ID`=68478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 해주십시오. 지능을 올리고 싶습니다. <10,000 골드를 지불합니다.>', `MaleText_loc4`='物有所值。我希望提升自己的智力。<付10,000金币。>', `MaleText_loc5`='很值得。我想要強化我的智力。<付10,000金。>', `MaleText_loc7`='Merece la pena. Deseo aumentar mi intelecto. <Paga 10000 de oro.>', `FemaleText_loc1`='그래도 해주세요. 지능을 올리고 싶어요. <10,000 골드를 지불합니다.>', `FemaleText_loc4`='物有所值。我希望提升自己的智力。<付10,000金币。>', `FemaleText_loc5`='很值得。我想要強化我的智力。<付10,000金。>', `FemaleText_loc7`='Merece la pena. Deseo aumentar mi intelecto. <Paga 10000 de oro.>' WHERE `ID`=68479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람군주 멜자라크가 동료가 넷 이상 행동 불가 상태가 된 것을 감지하고 풀어 줍니다!', `MaleText_loc4`='风领主梅尔加拉克察觉到3个以上的盟友丧失了能力，并释放了他们！', `MaleText_loc5`='風領主瑪爾加拉克查覺到他有3個以上的盟友被癱瘓而釋放了他們。', `MaleText_loc7`='¡El señor del viento Mel''jarak nota que más de 3 de sus aliados están incapacitados y los libera!' WHERE `ID`=68480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이여, 필요한 만큼 우리 마을에 머물러도 됩니다. 단지... 무기만 거둬 주십시오.', `MaleText_loc4`='你可以留在我们的村子里，随便待多久都没问题，陌生人。但……请不要亮出武器。', `MaleText_loc5`='只要你們需要，待在我們村子裡多久都沒關係，陌生人。只是...拜託試著把你們的武器收在劍鞘裡。', `MaleText_loc7`='Puedes quedarte en nuestra aldea todo el tiempo que necesites, $gforastero:forastera;, pero... intenta no desenvainar tus armas.' WHERE `ID`=68481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손님이 이렇게 많다니... 우리 마을이 어떻게 되려는 걸까요?', `MaleText_loc4`='这么多客人……我们的村子出什么事了？', `MaleText_loc5`='好多新的訪客...我們的村子現在是什麼情況?', `MaleText_loc7`='Cuántos visitantes... ¿Qué será de nuestra aldea?' WHERE `ID`=68482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 얼라이언스는 포우돈 마을에서 언제든 환영입니다.', `MaleText_loc4`='坡东村欢迎你，还有你的联盟。', `MaleText_loc5`='歡迎你，和你的聯盟，來到坡東。', `MaleText_loc7`='Tu Alianza y tú sois bienvenidos en Zarpa''don.' WHERE `ID`=68483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 도와드리면 되겠습니까?', `MaleText_loc4`='我能为你做些什么？', `MaleText_loc5`='我有什麼可以效勞的嗎?', `MaleText_loc7`='¿En qué te puedo ayudar?' WHERE `ID`=68484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 평화적인 구출 임무로 이곳에 왔소. 우릴 도와주겠소?', `MaleText_loc4`='我们是来执行和平救援任务——你会帮我们吗？', `MaleText_loc5`='我們是為了和平的救援任務而來。你願意幫我們嗎?', `MaleText_loc7`='Venimos en una misión pacífica de rescate. ¿Nos ayudarás?' WHERE `ID`=68485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 극적으로 나타나는 건 보지 못했는데...', `MaleText_loc4`='我已经好多年没见到它显现得如此强烈了。', `MaleText_loc5`='我已經好幾年沒看到它如此戲劇化的現身。', `MaleText_loc7`='Hacía muchos años que no la veía manifestarse de forma tan siniestra.' WHERE `ID`=68486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누구를? ... 어쨌다고요? 아! 우끼를 처치했다고요? 대단하군요! 잘하셨습니다, 영웅들이여.', `MaleText_loc4`='谁？……什么？噢！乌克死了？真是太棒了！干得好英雄们。', `MaleText_loc5`='誰?...什麼?喔!烏克掛了?太棒了!做得好，英雄們。', `MaleText_loc7`='¿Quién? ¿Qué? ¿Han acabado al Ook? ¡Es genial! Bien hecho, héroes.' WHERE `ID`=68487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 제가 사지요!', `MaleText_loc4`='这杯我请！', `MaleText_loc5`='這一杯是店家請客!', `MaleText_loc7`='¡A esa invita la casa!' WHERE `ID`=68488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아우! 아우! 아우!', `MaleText_loc4`='噢！噢！噢！', `MaleText_loc5`='噢!噢!噢!', `MaleText_loc7`='¡Ay! ¡Ay! ¡Ay!' WHERE `ID`=68489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 작업해라! 장군님은 실패를 용납하지 않으시니까.', `MaleText_loc4`='继续干活！上将决不容许失败。', `MaleText_loc5`='繼續工作!將軍不會容忍失敗。', `MaleText_loc7`='¡Seguid trabajando! El general no tolera el fracaso.' WHERE `ID`=68490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엔진을 작동시켜! 당장!', `MaleText_loc4`='把那些引擎发动起来！马上！', `MaleText_loc5`='快啟動那些引擎!現在!', `MaleText_loc7`='¡Encended esos motores ahora mismo!' WHERE `ID`=68491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좀 제대로 해보란 말이다! 이런, 지금까지 본 중에서 가장 멍청한 고블린들이군!', `MaleText_loc4`='再加把劲儿！你们是我所见过最没用的地精！', `MaleText_loc5`='給我努力點!你們是我所看過最可悲的一群哥布林了!', `MaleText_loc7`='¡Haced un esfuerzo! ¡Sois el grupo de goblins más patético que he visto jamás!' WHERE `ID`=68492;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와, 당신은 안개 너머에서 온 $r 종족이죠? 우린 정말 흥미로운 시대를 살고 있군요!$b$b전 그냥 잠시 숨 좀 돌리는 중이에요. 이놈의 계단을 걷다 보면 정말 진이 다 빠진다니까요. 올라가든 내려가든 마찬가지예요.', `FemaleText_loc4`='哇哦——你是位来自迷雾之外的$r？这是一个多么疯狂的时代啊！$b$b我只需要在这歇息片刻。长途跋涉真能让你筋疲力尽——上下坡都一样。', `FemaleText_loc5`='哇喔-你是從迷霧彼端來的$r嗎?這真是一個瘋狂的時代!$b$b我需要在這裡休息一下。這些階梯真的會讓你精疲力竭-不管是往上還是往下。', `FemaleText_loc7`='Guau... ¿Eres $gun:una; $r de más allá de la niebla? ¡Vivimos en tiempos extraños!$b$bSolo necesito un momento para descansar. Esta escalera acaba con cualquiera, ya sea a la subida o a la bajada.' WHERE `ID`=68493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 빨리! 대족장님이 우릴 지켜보고 계신다.', `MaleText_loc4`='快点儿！酋长的眼睛在盯着你们呢。', `MaleText_loc5`='快點!大酋長的雙眼在盯著你。', `MaleText_loc7`='¡Más rápido! El Jefe de Guerra os observa.' WHERE `ID`=68494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 끔찍하군.', `MaleText_loc4`='噢，可恶。', `MaleText_loc5`='喔，真噁。', `MaleText_loc7`='Ay.' WHERE `ID`=68495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 위에, 괜찮은 겁니까?', `MaleText_loc4`='你还好吧？', `MaleText_loc5`='你在上面還好嗎?', `MaleText_loc7`='¿Estás bien ahí arriba?' WHERE `ID`=68496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 대포알을 깨끗이 닦아라. 내 얼굴이 비칠 정도가 되어야 한다!', `MaleText_loc4`='继续擦亮那些炮弹。我要它们亮得能照出人影来！', `MaleText_loc5`='繼續擦亮那些砲彈。我想要用它們當鏡子!', `MaleText_loc7`='Sigan puliendo las bolas de cañón. Quiero verme reflejado en ellas.' WHERE `ID`=68497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거의 다 왔네!$b$b안개 속의 주점에서 시원한 맥주가 날 기다리고 있겠군. 벌써 그 맛이 느껴져...', `MaleText_loc4`='就快了！$b$b在迷雾酒肆里有冰镇美酒等着我呢。我仿佛已经尝到了……', `MaleText_loc5`='快好了!$b$b在霧隱客棧有杯冰涼的酒在等著我。我感覺幾乎已經嚐到它了...', `MaleText_loc7`='¡Ya casi estamos!$b$bMe espera una jarra de alivio fresquito en la Taberna en la Niebla. Casi siento su sabor...', `FemaleText_loc1`='조금만 더 가세요. 거의 도착했다고요!$b$b제가 이 길을 가는 건 이번이 세 번째랍니다. 여러 번 오니 저길 올라가는 것도 점점 쉬워진다고 말할 수 있으면 좋으련만!$b$b꼭대기까지 올라가면 근사한 여관이 있어요. "안개 속의 주점"이라는 곳이죠. 하지만 무기는 손 닿는 곳에 두시는 게 좋을 거예요. 거기 오는 사람들이 워낙 다양해서 말이죠.', `FemaleText_loc4`='继续走，就快到了！$b$b这是我第三次经过隘口了。真希望能用上熟能生巧这个词！$b$b等你抵达顶部之后，你会找到一家很棒的旅店，叫做“迷雾酒肆”。不过你可得把武器贴身放好。那可是个藏龙卧虎的地方。', `FemaleText_loc5`='加油，你快到了!$b$b這已經是我第三次來到這裡了。我真希望能告訴你這會變得越來越容易!$b$b等你爬到頂端的時候，你會看到一間很棒的旅店叫做「霧隱客棧」。但別掉以輕心，你會遇見各種不同的江湖中人。', `FemaleText_loc7`='Sigue andando, ¡casi has llegado!$b$bEste es mi tercer viaje por este pase. ¡Ojalá pudiera decir que se hace más fácil con el tiempo!$b$bCuando llegues arriba, hay una posada estupenda llamada "la Taberna en la Niebla". Pero no pierdas de vista tus armas, allí hay todo tipo de personajes.' WHERE `ID`=68498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑판에 떨어진 음식을 주워 먹을 수 있을 만큼 깨끗이 청소해라!', `MaleText_loc4`='我要这甲板干净到足以入口！', `MaleText_loc5`='我要這甲板乾淨到我能在上面吃東西!', `MaleText_loc7`='¡Quiero que esta cubierta esté tan limpia que se pueda comer en ella!' WHERE `ID`=68499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해서 다뤄라! 내 배에 생채기라도 났다가는, 네 목으로 갚아야 할 거다!', `MaleText_loc4`='小心点！要是我在新船上发现一道划痕，就等着掉脑袋吧！', `MaleText_loc5`='拿那個東西小心一點!如果我看到我的新船有任何刮傷的話，我就砍了你的腦袋!', `MaleText_loc7`='¡Cuidado con eso! Si veo una sola raya en mi nueva nave, ¡te cortaré la cabeza!' WHERE `ID`=68500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 서둘러라. 곧 이륙할 것이다!', `MaleText_loc4`='加快节奏，伙计们。我们就快出发了！', `MaleText_loc5`='加快步調。我們就快要準備好出航了!', `MaleText_loc7`='Más rápido, hombres. Estamos a punto de partir.' WHERE `ID`=68501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다, $n 님! 자이로콥터를 준비해 뒀어요!', `MaleText_loc4`='过来，$n！你的旋翼机可以使用了！', `MaleText_loc5`='在這裡，$n!你的旋翼機準備好可以出發了!', `MaleText_loc7`='¡Por aquí, $n! ¡Tu girocóptero ya está listo!' WHERE `ID`=68502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여깁니다, $n 님!', `MaleText_loc4`='过来，$n！', `MaleText_loc5`='在這裡，$n!', `MaleText_loc7`='¡Por aquí, $n!', `FemaleText_loc1`='여깁니다, $n 님!', `FemaleText_loc4`='过来，$n！', `FemaleText_loc5`='在這裡，$n!', `FemaleText_loc7`='¡Por aquí, $n!' WHERE `ID`=68503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 그럼 부두에서 만나세나!', `MaleText_loc4`='好吧，我们回海岸上去。', `MaleText_loc5`='好了，讓我們回到岸邊吧。', `MaleText_loc7`='Muy bien, volvamos a la orilla.' WHERE `ID`=68504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; $n|1을;를; 보고 매애애 웁니다.', `MaleText_loc4`='%s朝$n叫着。', `MaleText_loc5`='%s向$n咩咩叫。', `MaleText_loc7`='%s bala mirando a $n.' WHERE `ID`=68505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하! 이곳에는 손님이 그다지 많지 않다네. 스튜 좀 사지 그러나?', `FemaleText_loc4`='哈！这地方从来没接待过这么多访客。你想买些炖菜吗，邻居？', `FemaleText_loc5`='哈!這附近的訪客並不多。你想要購買一些燉菜嗎，鄰居?', `FemaleText_loc7`='¡Ah! No recibimos muchas visitas por aquí. ¿Quieres comprar un estofado, $gvecino:vecina;?' WHERE `ID`=68506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 멋진 전투였어! 하지만 이제 청소할 시간이네.', `MaleText_loc4`='真是炮火连天啊！现在该收拾残局了。', `MaleText_loc5`='那還真是場猛烈的火拼!現在是時候清理一下了。', `MaleText_loc7`='¡Menudo tiroteo! Ahora toca limpiar.' WHERE `ID`=68507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘불꽃호를 타고 온 선원들은 모두 얼라이언스의 최정예 요원들이네. 그래도 SI:7만이 해낼 수 있는 일이 있는 법이지.', `MaleText_loc4`='天火号上的那些人都是联盟精英。但有些事情，仍然只有军情七处可以办到。', `MaleText_loc5`='在天火號上的那些人是聯盟最優秀的精英。但有些事情還是只有軍情七處能辦得到。', `MaleText_loc7`='Los que venían en el Abrasacielos son la élite de la Alianza, pero hay cosas que solo puede conseguir el IV:7.' WHERE `ID`=68508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='북쪽에서 수십 대의 비행기가 격추되고, 조종사들은 부상을 당했네. 우리 SI:7 요원도 한 명 포함되었고.$B$B그들을 도와야 하네. 하지만 먼저 호드를 상대해야 하겠지.', `MaleText_loc4`='有许多飞行员都被击落在北方，其中一位是我们军情七处的特工。$B$B我们必须帮助他们，但首先得解决这些部落。', `MaleText_loc5`='許多駕駛員被擊落在更遠的北邊，包括一名我們的軍情七處探員。$B$B我們必須救助他們所有人，但我們得先對付部落。', `MaleText_loc7`='Derribaron a docenas de pilotos al norte, y entre ellos se encuentra una de nuestras agentes del IV:7.$b$bDebemos ayudarles, pero antes tenemos que encargarnos de la Horda.' WHERE `ID`=68509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제법 활기가 넘치는 행사로군요!

아마 내년에는 우리 양조사들도 와서 대회에 참가할 겁니다.', `MaleText_loc4`='真是太热闹了！

相信我们的酿酒师明年也会到场竞技吧。', `MaleText_loc5`='相當令人愉快的活動!

我猜明年我們自己的釀酒大師們也會到場和參賽。', `MaleText_loc7`='¡Un festejo de lo más alegre!

Creo que el año que viene nuestros maestros cerveceros también asistirán para competir.', `FemaleText_loc1`='제법 활기가 넘치는 행사네요!

아마 내년에는 우리 양조사들도 와서 대회에 참가할 거예요.', `FemaleText_loc4`='真是太热闹了！

相信我们的酿酒师明年也会到场竞技吧。', `FemaleText_loc5`='相當令人愉快的活動!

我猜明年我們自己的釀酒大師們也會到場和參賽。', `FemaleText_loc7`='¡Un festejo de lo más alegre!

Creo que el año que viene nuestros maestros cerveceros también asistirán para competir.' WHERE `ID`=68510;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='렐 사령관님과 다른 요원들이 앰버를 찾았다고 들었어요. 정말 좋은 소식이에요.', `FemaleText_loc4`='我听说指挥官利尔他们找到了安玻！真是个好消息。', `FemaleText_loc5`='我聽說瑞爾指揮官和其他人找到琥珀了!那真是個好消息。', `FemaleText_loc7`='¡He oído que el comandante Rell y los demás han encontrado a Amber! Es una noticia fantástica.' WHERE `ID`=68511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사부 창의 조교들을 짜릿한 비취 번개로 넘어뜨리십시오.', `MaleText_loc4`='用碎玉闪电击倒曾大师的助手们。', `MaleText_loc5`='用碎玉轟雷掌將曾大師的助手們擊倒。', `MaleText_loc7`='Derriba a los ayudantes del maestro Tsang con Relámpago crepitante de jade.' WHERE `ID`=68512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이보세요, 거기 $g멋진 총각:멋진 아가씨;, 이쪽은 예열도 다 되고 전투 준비 끝났다고요!', `FemaleText_loc4`='你好，宝贝儿！我已经迫不及待，想要迎接战斗了！', `FemaleText_loc5`='嘿，你好啊，$G帥哥:小姑娘;，我已經躍躍欲試想要對戰了!', `FemaleText_loc7`='Buenas, $gmozo:guapa;. ¡Estoy lista para la batalla!' WHERE `ID`=68513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피난민들이 평원 전역에서 빈안으로 몰려들고 있다네. 야운골이 장벽을 돌파한 게 아닌가 걱정이야.', `MaleText_loc4`='难民从高原各地涌向滨岸村。我担心野牛人已经攻破了长城！', `MaleText_loc5`='難民們從荒原四處湧入濱南村，我擔心揚古已經突破長城了!', `MaleText_loc7`='Llegan refugiados a Binan de todas partes. Es posible que los yaungol hayan atravesado la muralla.' WHERE `ID`=68514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탄이의 퓨즈가 탄 건가? 7페이지에 얼룩이 너무 심하다 싶더니...', `FemaleText_loc4`='是不是应该点燃斯普洛德的引线？在第七页上有个污点……', `FemaleText_loc5`='我們應該要點燃史鮑德的引信嗎?第七頁上有個髒汙...', `FemaleText_loc7`='¿La mecha de Explosionador tiene que estar encendida o no? Hay una mancha en la página 7...' WHERE `ID`=68515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕은 살아난다! 두 제국은 다시 하나가 되리라...', `MaleText_loc4`='雷电之王复活了！我们的帝国再次团结在一起……', `MaleText_loc5`='雷王是不滅的，我們的王國將會再度統一。', `MaleText_loc7`='¡El Rey del Trueno vive! Nueh''tros imperios eh''tán unidos una vez más...' WHERE `ID`=68516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에겐 이 땅이 필요해! 대격변이 우리 고향을 파괴했어!', `MaleText_loc4`='我们需要这片土地！大灾变毁了我们的家园！', `MaleText_loc5`='我們需要這片土地!大災變摧毀了我們的家園!', `MaleText_loc7`='¡Necesitamos eh''ta tierra! ¡El Cataclismo deh''truyó nueh''tro hogar!' WHERE `ID`=68517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부숴라...', `MaleText_loc4`='毁灭……', `MaleText_loc5`='摧毀...', `MaleText_loc7`='DESTRUIR...' WHERE `ID`=68518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주달 축제 본 적 있나? 진짜 대단하지. 난 그 축제를 위해 쿤라이 뻥뻥주를 잔뜩 준비하고 있다네.$b$b나와 함께 빈안 마을에서 축제에 참가하겠나?', `MaleText_loc4`='你欢庆过酿月祭吗？那真是个大饱口福的好机会。我正在为这佳节准备一大批昆莱劲酒。$b$b想来滨岸村加入我吗？', `MaleText_loc5`='你有來過酒月節嗎?這真是一場樂事。我正在準備一大堆我的崑萊好勁道 要用來慶祝之用。$b$b你想要到濱南村來加入我們嗎?', `MaleText_loc7`='¿Alguna vez has estado en el Festival de la Cerveza Lunar? Es una delicia. Estoy preparando una gran tanda de mi Pateadora Kun-Lai para la celebración.$b$b¿Nos vemos en la Aldea Binan?' WHERE `ID`=68519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 약해 빠진 공격은 아무렇지도 않다!', `MaleText_loc4`='你们的软弱攻击不值一提！', `MaleText_loc5`='你渺小的攻擊一點意義都沒有!', `MaleText_loc7`='¡SUS PATÉTICOS ATAQUES NO SON MÁS QUE COSQUILLAS!' WHERE `ID`=68520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 증오가 나를 짓누른다!', `MaleText_loc4`='啊！仇恨将我吞噬！', `MaleText_loc5`='啊!仇恨讓我受不了啦!', `MaleText_loc7`='¡ARGH! ¡EL ODIO ME CONSUME!' WHERE `ID`=68521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조련사 친구! 전투 준비해!', `MaleText_loc4`='你好，驯宠师！准备战斗！', `MaleText_loc5`='馴獸師們!準備對戰!', `MaleText_loc7`='¡Arr! ¡Prepárate para la batalla!' WHERE `ID`=68522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 전투가 끝나면 넌 멀록들과 헤엄치게 될 거다!', `MaleText_loc4`='等这一切结束之后，你就要跟鱼人一起游泳了！', `MaleText_loc5`='我解決你後會讓你去和魚人們一起游泳!', `MaleText_loc7`='¡Acabalás nadando con losh múl-locs!' WHERE `ID`=68523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕의 짐은 무겁다. 아버지의 짐도 마찬가지다. 내 아들을 찾아내기 전까지는 무슨 일이 있어도 멈추지 않겠다.', `MaleText_loc4`='国王肩上的担子很重，可身为父亲，也是肩负重责。我会不惜一切代价寻找儿子。', `MaleText_loc5`='身為父親的擔子就和一個國王身上重擔一樣沉重。我不會被任何事妨礙我找到我的兒子。', `MaleText_loc7`='La carga de un rey es pesada, pero la de un padre no lo es menos. Haré lo que haga falta para encontrar a mi hijo.' WHERE `ID`=68524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 우리와 전쟁을 벌이고 싶다면, 얼마든지 그렇게 해 주지.$B$B빛이여, 도와주소서. 나는 내 왕국과 내 백성들을 위해 싸우겠다.$B$B얼라이언스에 영광을!', `MaleText_loc4`='如果部落非要把我们逼到战争的边缘，那就来吧。$B$B在圣光的庇佑下，我会为自己的王国和人民而战。$B$B荣耀属于联盟！', `MaleText_loc5`='如果部落想要將我們推向戰爭一途，那就這樣吧。$B$B聖光幫助我，我會為了我的王國與我的子民而戰。$B$B榮耀歸於聯盟!', `MaleText_loc7`='Si la Horda quiere empujarnos a la guerra, que así sea.$b$bA la Luz pongo por testigo que lucharé por mi reino y por mi pueblo.$b$b¡Gloria a la Alianza!' WHERE `ID`=68525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음번에는 운이 더 좋을 거야, 애송아!', `MaleText_loc4`='祝你下次好运，旱鸭子！', `MaleText_loc5`='祝你下次好運，旱鴨子!', `MaleText_loc7`='¡Que tengas más suerte la próxima vez, $gmarinero:marinera; de agua dulce!' WHERE `ID`=68526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 선장 일지에 또 승리했다고 써야겠군!', `MaleText_loc4`='在我船长的日记里又增添了新的胜利篇章！', `MaleText_loc5`='船長日誌裡再記上一筆我的勝利!', `MaleText_loc7`='¡Otra victoria pa’l cuadelno de bitácora!' WHERE `ID`=68527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애송이치고는 나쁘지 않은데.', `MaleText_loc4`='对于旱鸭子来说，算是不错了。', `MaleText_loc5`='對旱鴨子來說還不錯。', `MaleText_loc7`='No eshtá mal pa'' $gun marinero:una marinera; d’agua ¡hic! dulse.' WHERE `ID`=68528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 대단한 전투였어! 전투를 그만두기로 결정하면 내 선원이 될 수도 있겠는데!', `MaleText_loc4`='打得漂亮！要是你什么时候决定不再玩战斗游戏了，也许可以加入我的队伍！', `MaleText_loc5`='真是場好戰鬥!如果哪天你厭倦了對戰遊戲，也許你能加入我的船員!', `MaleText_loc7`='¡Menuda lucha! Si alguna vez te cansas de los duelos, ¡puedes unirte a mi tripulación!' WHERE `ID`=68529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 어떤 존재인지 보여줘라!... *딸꾹!*', `MaleText_loc4`='让他们见识下我们的厉害！……嗝儿！', `MaleText_loc5`='讓他們瞧瞧我們的實力!...嗝!', `MaleText_loc7`='¡Enséñales lo que vales... hic!' WHERE `ID`=68530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르지 말라고, 친구. 여긴 내 구역이니까!', `MaleText_loc4`='没这么快，伙计。这是我的地盘！', `MaleText_loc5`='想都別想，夥計。你在我的地盤上!', `MaleText_loc7`='No tan rápido, $gchaval:chavala;. ¡Este es mi territorio!' WHERE `ID`=68531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무 판자 위를 걸을 준비 됐어?', `MaleText_loc4`='准备好受死了？', `MaleText_loc5`='準備好上木板了嗎?', `MaleText_loc7`='¿$gListo:Lista; para que te pase por la quilla?' WHERE `ID`=68532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 해라 애들아. 아주 신나게 날뛰라고!', `MaleText_loc4`='再接再厉，伙计们。他们四散奔逃了！', `MaleText_loc5`='持續進攻，夥計們。他們在逃跑啦!', `MaleText_loc7`='Dale p’alante, compay. ¡Eshtamos ganando!' WHERE `ID`=68533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 집합! 아군을 너무 빨리 잃고 있어!', `MaleText_loc4`='全员都到甲板上集合！我们正迅速损兵折将！', `MaleText_loc5`='所有人手到甲板上!我們死傷慘重!', `MaleText_loc7`='¡Todosh a cubielta! ¡Eshtamos peldiendo!' WHERE `ID`=68534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 내 애완동물이 죽은 거지?', `MaleText_loc4`='我的宠物怎么不见了？', `MaleText_loc5`='我的寵物怎麼不見了?', `MaleText_loc7`='¿Adónde she fue mi mashcota?' WHERE `ID`=68535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 벌레같이 뭉개준다!', `MaleText_loc4`='你会像虫子一样被我碾死！', `MaleText_loc5`='我把你像蟲子一樣捏扁!', `MaleText_loc7`='¡Yo aplastarte como a bicho!' WHERE `ID`=68536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글루크 엄청 센 조련사 된다! 그다음 고르독 왕 된다!', `MaleText_loc4`='我先成为强大的驯宠师，然后就会成为戈多克大王！', `MaleText_loc5`='我會成為強大的馴獸師，然後我會成為戈多克大王!', `MaleText_loc7`='Yo convertirme en domador poderoso, ¡y luego en rey Gordok!' WHERE `ID`=68537;
