UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글루크가 최고야!', `MaleText_loc4`='格鲁克是最棒的！', `MaleText_loc5`='格魯克是最棒的!', `MaleText_loc7`='¡Gluk ser el mejor!' WHERE `ID`=68539;
