UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 판다렌이 우리에겐 그저 이방인에 불과하지만, 시간이 흐른 후에는 소중한 동맹이 될 거라고 생각한다.', `MaleText_loc4`='熊猫人现在或许还是陌生人，可总有一天，他们会成为最可宝贵的盟友。', `MaleText_loc5`='熊貓人現在也許還是陌生人，但隨時間過去，我相信他們會是重要的盟友。', `MaleText_loc7`='Ahora los pandaren solo son unos desconocidos, pero creo que con el tiempo se convertirán en aliados valiosos.' WHERE `ID`=68557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발하는 증오가 죽으면 방어막이 파괴될 겁니다! 빨리요!', `MaleText_loc4`='迸发之恨的死应该摧毁了他的护盾！赶快！', `MaleText_loc5`='炸裂憎恨獸的死亡應該能摧毀他的護盾!趕快!', `MaleText_loc7`='La muerte de un odio explosivo debería destruir su escudo. ¡Rápido!' WHERE `ID`=68558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<다치지 않는 말릭이 남긴 것이라고는 무기 선반에 아무렇게나 걸려 있는 창뿐입니다.>', `MaleText_loc4`='<作为无伤者玛里克仅存的遗留物，他的长矛突兀地挂在武器架上。>', `MaleText_loc5`=' <『毫髮無傷』的瑪力克所留下的，只有倒在武器架上的這把矛戟。>', `MaleText_loc7`='<El arma de asta de Malik el Indemne, todo lo que queda de él, está colocada sin remilgos en un expositor de armas.>' WHERE `ID`=68559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<말릭이 준 교훈을 곰곰이 생각해봅니다.> [클락시 강화 효과]', `MaleText_loc4`='<思考玛里克的教诲。>', `MaleText_loc5`='<回想著瑪力克的教誨。>[卡拉西強化效果]', `MaleText_loc7`='<Reflexiona sobre las lecciones de Malik.> [Mejora Klaxxi]', `FemaleText_loc1`='<말릭이 준 교훈을 곰곰이 생각해봅니다.> [클락시 강화 효과]', `FemaleText_loc4`='<思考玛里克的教诲。>', `FemaleText_loc5`='<回想著瑪力克的教誨。>[卡拉西強化效果]', `FemaleText_loc7`='<Reflexiona sobre las lecciones de Malik.> [Mejora Klaxxi]' WHERE `ID`=68560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이방인이 또 한 명 마을에 나타났군... 겉모습을 보니 $c 같은데, 이리 오게. 하지만 호드가 그랬던 것처럼 무기를 든다면 가만히 있지는 않겠네.', `MaleText_loc4`='又有个陌生人来到村里了……看样子还是个$c。进来吧，但别像那些部落一样，对我们拔剑相向。', `MaleText_loc5`='又一個陌生人來到了我們的村子...看來是一個$c。進來，但不要像部落一樣拔出你的武器指著我們。', `MaleText_loc7`='Se acerca $gotro forastero:otra forastera; a nuestra aldea... $gun:una; $c, por lo que parece. Entra, pero no desenvaines tus armas como hizo la Horda.', `FemaleText_loc1`='이방인이 또 한 명 마을에 나타났군요... 겉모습을 보니 $c 같은데, 이리 오세요. 하지만 호드가 그랬던 것처럼 무기를 든다면 가만히 있지는 않겠어요.', `FemaleText_loc4`='又有个陌生人来到村里了……看样子还是个$c。进来吧，但别像那些部落一样，对我们拔剑相向。', `FemaleText_loc5`='又一個陌生人來到了我們的村子...看來是一個$c。進來，但不要像部落一樣拔出你的武器指著我們。', `FemaleText_loc7`='Se acerca $gotro forastero:otra forastera; a nuestra aldea... $gun:una; $c, por lo que parece. Entra, pero no desenvaines tus armas como hizo la Horda.' WHERE `ID`=68561;
