UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 근무 조건이 너무 끔찍합니다! 몇 시간째 맥주 마실 시간도 없었다니까요!', `MaleText_loc4`='这里的工作条件太糟糕了！我们已经几个小时没有坐下来喝喝酒了！', `MaleText_loc5`='這種工作環境真是糟透了!我們已經有好幾個小時沒有啤酒休息時間了!', `MaleText_loc7`='¡Estas condiciones de trabajo son una vergüenza! ¡Hace HORAS que no tenemos un descanso para beber cerveza!', `FemaleText_loc1`='여긴 근무 조건이 너무 끔찍해요! 몇 시간째 맥주 마실 시간도 없었다니까요!', `FemaleText_loc4`='这里的工作条件太糟糕了！我们已经几个小时没有坐下来喝喝酒了！', `FemaleText_loc5`='這種工作環境真是糟透了!我們已經有好幾個小時沒有啤酒休息時間了!', `FemaleText_loc7`='¡Estas condiciones de trabajo son una vergüenza! ¡Hace HORAS que no tenemos un descanso para beber cerveza!' WHERE `ID`=68567;
