UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴식시간이 됐다고 알려주러 오신 겁니까? 쉬어본 적이 없는 것 같습니다!', `MaleText_loc4`='你是来让我休息的吗？我好像已经连续工作几辈子了！', `MaleText_loc5`='你是來這裡頂替我的嗎?我感覺好像工作了一輩子一樣!', `MaleText_loc7`='¿Has venido para relevarme? ¡Tengo la sensación de llevar siglos trabajando!', `FemaleText_loc1`='휴식시간이 됐다고 알려주러 오신 건가요? 쉬어본 적이 없는 것 같아요!', `FemaleText_loc4`='你是来让我休息的吗？我好像已经连续工作几辈子了！', `FemaleText_loc5`='你是來這裡頂替我的嗎?我感覺好像工作了一輩子一樣!', `FemaleText_loc7`='¿Has venido para relevarme? ¡Tengo la sensación de llevar siglos trabajando!' WHERE `ID`=68572;
