UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저를 이기려면 그것보다는 더 잘해야 할 거예요.', `FemaleText_loc4`='你得再加把劲才能打败我。', `FemaleText_loc5`='想要打敗我你還要做得更好才行。', `FemaleText_loc7`='Vas a tener que hacerlo mejor si quieres derrotarme.' WHERE `ID`=68652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 집에 가야겠습니다.', `MaleText_loc4`='我想我该回家了。', `MaleText_loc5`='我想該是我回家的時候了。', `MaleText_loc7`='Creo que ya es hora de volver a casa.', `FemaleText_loc1`='드디어 집에 갈 수 있겠어요.', `FemaleText_loc4`='我想我该回家了。', `FemaleText_loc5`='我想該是我回家的時候了。', `FemaleText_loc7`='Creo que ya es hora de volver a casa.' WHERE `ID`=68653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맞습니다. 저는 전쟁 기지를 지으려고 온 게 아니었습니다.', `MaleText_loc4`='你是对的。我可没签过什么建造战争基地的合约。', `MaleText_loc5`='你是對的。我可沒報名要建造一座戰爭基地。', `MaleText_loc7`='Tienes razón, no me apunté para construir una base militar.', `FemaleText_loc1`='맞아요. 저는 전쟁 기지를 지으려고 온 게 아니었어요.', `FemaleText_loc4`='你是对的。我可没签过什么建造战争基地的合约。', `FemaleText_loc5`='你是對的。我可沒報名要建造一座戰爭基地。', `FemaleText_loc7`='Tienes razón, no me apunté para construir una base militar.' WHERE `ID`=68654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, $r님.', `MaleText_loc4`='谢谢你，$r。', `MaleText_loc5`='謝謝你，$r。', `MaleText_loc7`='Gracias, $r.', `FemaleText_loc1`='고마워요, $r님.', `FemaleText_loc4`='谢谢你，$r。', `FemaleText_loc5`='謝謝你，$r。', `FemaleText_loc7`='Gracias, $r.' WHERE `ID`=68655;
