UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 정말 감사합니다!', `MaleText_loc4`='谢天谢地！', `MaleText_loc5`='感謝老天爺!', `MaleText_loc7`='¡Menos mal!', `FemaleText_loc1`='아, 정말 고마워요!', `FemaleText_loc4`='谢天谢地！', `FemaleText_loc5`='感謝老天爺!', `FemaleText_loc7`='¡Menos mal!' WHERE `ID`=68657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 당장 떠나야겠습니다!', `MaleText_loc4`='谢谢！我要离开了！', `MaleText_loc5`='謝啦!我要離開這了!', `MaleText_loc7`='¡Gracias! ¡Me largo!', `FemaleText_loc1`='고맙습니다! 당장 떠나야겠어요!', `FemaleText_loc4`='谢谢！我要离开了！', `FemaleText_loc5`='謝啦!我要離開這了!', `FemaleText_loc7`='¡Gracias! ¡Me largo!' WHERE `ID`=68658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 당신은 얼라이언스가 아니군요? 다행입니다.', `MaleText_loc4`='你……你不是联盟的成员？很好。', `MaleText_loc5`='你...你不是聯盟的人?很好。', `MaleText_loc7`='¿No... no eres de la Alianza? Qué bien.', `FemaleText_loc1`='당신... 당신은 얼라이언스가 아니네요? 다행이에요.', `FemaleText_loc4`='你……你不是联盟的成员？很好。', `FemaleText_loc5`='你...你不是聯盟的人?很好。', `FemaleText_loc7`='¿No... no eres de la Alianza? Qué bien.' WHERE `ID`=68659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 집에 돌아가고 싶습니다.', `MaleText_loc4`='我想马上回家去。', `MaleText_loc5`='我等不及要回到家了。', `MaleText_loc7`='No veo el momento de volver a casa.', `FemaleText_loc1`='어서 집에 돌아가고 싶어요.', `FemaleText_loc4`='我想马上回家去。', `FemaleText_loc5`='我等不及要回到家了。', `FemaleText_loc7`='No veo el momento de volver a casa.' WHERE `ID`=68660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사합니다.', `MaleText_loc4`='非常感谢。', `MaleText_loc5`='非常感激。', `MaleText_loc7`='Muchísimas gracias.', `FemaleText_loc1`='정말 고마워요.', `FemaleText_loc4`='非常感谢。', `FemaleText_loc5`='非常感激。', `FemaleText_loc7`='Muchísimas gracias.' WHERE `ID`=68661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 이기려고 작정했네요. 그렇죠?', `FemaleText_loc4`='你真是志在必得啊，对吧？', `FemaleText_loc5`='你真的是為了得勝而來的，嗯?', `FemaleText_loc7`='Juegas a ganar, ¿eh?' WHERE `ID`=68662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 샤의 오염 때문에 납골당을 조사하고 있었어요... 그런데 모든 게 끔찍하게 잘못됐어요. 우리 지휘관이었던 진 아이언피스트가 샤에 현혹돼 모두를 죽이기 시작했어요. 지금 이 순간에도 그는 제물을 찾아 돌아다니고 있답니다.', `FemaleText_loc4`='我们当时正在地穴里调查邪煞的腐化情况……然后一切都变得很不对劲。我们的领袖金·铁拳被邪煞控制了，开始大开杀戒。即便是现在，他还在那里加害无辜。', `FemaleText_loc5`='我們那時在調查墓穴中煞的腐化...然後所有事都變得一團亂。我們的領袖鐵拳阿金被附身，然後開始屠殺每個人。直到現在他也還在那裡尋找新的受害者。', `FemaleText_loc7`='Estábamos investigando la cripta en busca de corrupción sha... y sucedió el desastre. Nuestro líder, Jin Puñoferro, se vio poseído y empezó a matar a todo el mundo. Aún sigue ahí dentro, en busca de víctimas.' WHERE `ID`=68663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='각오하시오, 조련사여. 승리는 내가 차지하겠소.', `MaleText_loc4`='做好准备，驯宠师。我是为胜利而来。', `MaleText_loc5`='備戰吧，馴獸師。我是為了勝利而來。', `MaleText_loc7`='Prepárate. Busco la victoria.' WHERE `ID`=68664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 당신이 하나도 안 무섭소.', `MaleText_loc4`='你吓不倒我的，驯宠师。', `MaleText_loc5`='你嚇不到我的，馴獸師。', `MaleText_loc7`='No me intimidas.' WHERE `ID`=68665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='샤가 진의 생명을 훔쳤어요. 그를 죽인 것에 대해 스스로 자책하진 마세요. 당신은 제가 하지 못했던 일을 한 거니까요.', `FemaleText_loc4`='是邪煞夺去了金的生命——不要为他的死而责怪自己。你的努力令我望尘莫及。', `FemaleText_loc5`='阿金的生命已經被煞偷走了-不要因他的死亡而責怪你自己。你做了一件我做不到的事。', `FemaleText_loc7`='Fue el sha el que robó la vida de Jin; no te culpo por su muerte. Hiciste lo que yo no pude.' WHERE `ID`=68666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련을 더 한 뒤에 오시오.', `MaleText_loc4`='等你准备充分再回来吧。', `MaleText_loc5`='當你準備更完善時再回來吧。', `MaleText_loc7`='Vuelve cuando te hayas preparado mejor.' WHERE `ID`=68667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음에 싸울 때는 당신 운이 더 좋을지도 모르겠군.', `MaleText_loc4`='也许我们下一次交手时，你会交好运。', `MaleText_loc5`='也許你在下次戰鬥時會更好運。', `MaleText_loc7`='A lo mejor tendrás más suerte en nuestro próximo encuentro.' WHERE `ID`=68668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 조련사의 은총과 함께 싸웠군. 정말 훌륭하오.', `MaleText_loc4`='你的一招一式犹如大师级驯宠师。干得好。', `MaleText_loc5`='你帶著馴獸大師的優雅戰鬥。做得好。', `MaleText_loc7`='Luchas con la gracia de $gun domador maestro:una domadora maestra;. Bien hecho.' WHERE `ID`=68669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 너희 집으로 돌아가렴.', `MaleText_loc4`='你现在可以回去与家人团聚了。', `MaleText_loc5`='你現在可以回家去找你的家人了。', `MaleText_loc7`='Ya puedes volver con tu familia.', `FemaleText_loc1`='이제 너희 집으로 돌아가렴.', `FemaleText_loc4`='你现在可以回去与家人团聚了。', `FemaleText_loc5`='你現在可以回家去找你的家人了。', `FemaleText_loc7`='Ya puedes volver con tu familia.' WHERE `ID`=68670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 인상적인 전투였소.', `MaleText_loc4`='很了不起，驯宠师。', `MaleText_loc5`='非常令人印象深刻，馴獸師。', `MaleText_loc7`='Impresionante.' WHERE `ID`=68671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 승리하게 둘 순 없소.', `MaleText_loc4`='我不会让你得逞。', `MaleText_loc5`='我不會讓你有這樣的滿足感的。', `MaleText_loc7`='No te daré ese placer.' WHERE `ID`=68672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 만만하게 당하진 않을 거요.', `MaleText_loc4`='你休想轻易打败我。', `MaleText_loc5`='你不會那麼輕易地打敗我。', `MaleText_loc7`='No me derrotarás tan fácilmente.' WHERE `ID`=68673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투에서 적을 이기려면 적절한 전략을 사용해야 하오.', `MaleText_loc4`='在战斗中击败对手，是对战术最好的检验。', `MaleText_loc5`='在對戰中擊敗對手，就是證明你的戰略可行。', `MaleText_loc7`='Derrotar a un oponente en combate es validar tu estrategia.' WHERE `ID`=68674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 전략이 더 앞서는 것 같군.', `MaleText_loc4`='看来我的战略无人能及。', `MaleText_loc5`='看來我的戰略比較好。', `MaleText_loc7`='Parece que mi estrategia es superior.' WHERE `ID`=68675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 전쟁에서 승리하려면 작은 전쟁에서 지는 것을 두려워하지 말아야 하는 법.', `MaleText_loc4`='如果胜局已定，就不必惧怕区区一场战斗的失败。', `MaleText_loc5`='只要能贏得戰爭，不要怕打輸一場戰鬥。', `MaleText_loc7`='No temas perder una batalla si ganas la guerra.' WHERE `ID`=68676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 당신은 내가 생각했던 것보다 훨씬 강력하구려.', `MaleText_loc4`='我明白了。你我想象中要强大得多。', `MaleText_loc5`='我明白了。你是個比我所想還可畏的對手。', `MaleText_loc7`='Ya veo. Eres más formidable de lo que esperaba.' WHERE `ID`=68677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신이 이해조차 할 수도 없는 공포를 견뎌냈습니다. 당신을 꺾는 건 간단한 일이지요.', `MaleText_loc4`='我经历过你们无法想象的恐惧。击败你们就是小菜一碟。', `MaleText_loc5`='我承受過你所無法理解的恐怖事物。打敗你將是一件簡單的事。', `MaleText_loc7`='He padecido horrores que no puedes imaginar. Derrotarte será muy sencillo.' WHERE `ID`=68678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 끝내야겠군요.', `MaleText_loc4`='我会速战速决。', `MaleText_loc5`='我會很快了結的。', `MaleText_loc7`='No tardaré.' WHERE `ID`=68679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 승리하리라는 것에 잠시라도 의문을 품지 않았습니다.', `MaleText_loc4`='我片刻也没怀疑过自己的胜利。', `MaleText_loc5`='我一刻也沒懷疑過我的勝利。', `MaleText_loc7`='Jamás dudé de mi victoria.' WHERE `ID`=68680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실력이 이것밖에 안 됩니까?', `MaleText_loc4`='你就只有那点本事吗？', `MaleText_loc5`='你就這麼點斤兩嗎?', `MaleText_loc7`='¿Eso es todo?' WHERE `ID`=68681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 지다니 못 참겠군요!', `MaleText_loc4`='我不会容忍这个！', `MaleText_loc5`='我不會忍受這樣的事!', `MaleText_loc7`='¡No lo permitiré!' WHERE `ID`=68682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 당신의 실력은 정말 많이 깔봤군요.', `MaleText_loc4`='我严重低估了你的实力。', `MaleText_loc5`='我嚴重地低估了你的戰力。', `MaleText_loc7`='He subestimado gravemente tu pericia.' WHERE `ID`=68683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 꺾으려면 지금보다 더 노력해야 할 겁니다.', `MaleText_loc4`='你得再加把劲，才能击败我。', `MaleText_loc5`='你得更努力點才能打敗我。', `MaleText_loc7`='Tendrás que esforzarte más para vencerme.' WHERE `ID`=68684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저를 이기진 못할 겁니다! 제가 꺾어드리지요!', `MaleText_loc4`='你半点机会都没有。我会打败你！', `MaleText_loc5`='你沒有勝算。我會擊敗你!', `MaleText_loc7`='No tienes ninguna posibilidad. ¡Te derrotaré!' WHERE `ID`=68685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 된 것 같은데요?', `MaleText_loc4`='够了吗？', `MaleText_loc5`='被打夠了嗎?', `MaleText_loc7`='¿Has tenido suficiente?' WHERE `ID`=68686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 제 상대가 못 됩니다.', `MaleText_loc4`='你根本不是我的对手。', `MaleText_loc5`='你不是我的對手。', `MaleText_loc7`='No estás a mi altura.' WHERE `ID`=68687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운이 좋군요.', `MaleText_loc4`='你真走运。', `MaleText_loc5`='算你走運。', `MaleText_loc7`='Has tenido suerte.' WHERE `ID`=68688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장난은 여기까지 해야겠군요. 박살 내드리겠습니다!', `MaleText_loc4`='不胡闹了。我要粉碎你！', `MaleText_loc5`='不跟你鬧了。我將會粉碎你!', `MaleText_loc7`='Ya vale de juegos. ¡Te aplastaré!' WHERE `ID`=68689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 승기는 여기서 그치는군요.', `FemaleText_loc4`='你的胜利到此为止，驯宠师。', `FemaleText_loc5`='你的勝利在此終止，馴獸師。', `FemaleText_loc7`='Tus victorias han terminado.' WHERE `ID`=68690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 이들은 대부분 저와 싸울 땐 균형을 잃는답니다. 당신이 그들과 다른지 한번 봐야겠네요.', `FemaleText_loc4`='很少有人能在与我交战时维持平衡。让我们瞧瞧你是否与众不同。', `FemaleText_loc5`='很少人能夠在和我對戰時保持平衡。讓我們看看你是否有所不同吧。', `FemaleText_loc7`='Pocas personas son capaces de mantener el equilibrio mientras luchan conmigo. Veamos si tú eres diferente.' WHERE `ID`=68691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 예상했던 대로군요. 아직은 저를 꺾을 수 있을 만큼 실력이 좋지 않네요.', `FemaleText_loc4`='如我所料。你还没本事打败我。', `FemaleText_loc5`='如同我所預期的。你的技巧還不足以擊敗我。', `FemaleText_loc7`='Es lo que esperaba. No eres lo bastante hábil como para vencerme.' WHERE `ID`=68692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='절대 기분 나빠하지 마세요. 다른 조련사들도 제게 많이 진답니다.', `FemaleText_loc4`='别担心。你只是我的手下败将之一。', `FemaleText_loc5`='不要苦惱。你是我許多手下敗將之一。', `FemaleText_loc7`='No te preocupes. He derrotado a mucha gente.' WHERE `ID`=68693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 대단한 기술을 보여주셨어요!', `FemaleText_loc4`='真是战技卓绝啊！', `FemaleText_loc5`='真是高超的技巧展示!', `FemaleText_loc7`='¡Qué técnica tan maravillosa!' WHERE `ID`=68694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 승리한 건 당연한 결과였어요.', `FemaleText_loc4`='你的胜利受之无愧，驯宠师。', `FemaleText_loc5`='你的勝利是應得的，馴獸師。', `FemaleText_loc7`='Tu victoria es bien merecida.' WHERE `ID`=68695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직 끝나려면 한참 멀었답니다.', `FemaleText_loc4`='离结束还早着呢。', `FemaleText_loc5`='我們離結束還差得遠哩。', `FemaleText_loc7`='Aún no hemos terminado.' WHERE `ID`=68696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='골짜기가 제게 힘을 주네요.', `FemaleText_loc4`='山谷赋予我力量。', `FemaleText_loc5`='恆春谷給我力量。', `FemaleText_loc7`='El valle me da poder.' WHERE `ID`=68697;
