UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아르카누스, 놈들에게 우리의 끝없는 힘을 보여줘라!', `MaleText_loc4`='阿卡努斯，让他们见识下我们无尽的力量！', `MaleText_loc5`='阿坎努斯，讓他們看看我們無盡的力量!', `MaleText_loc7`='Arcanus, ¡enséñales nuestro poder inagotable!' WHERE `ID`=68756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸륵이, 너만 믿는다!', `MaleText_loc4`='我看好你，哥培尔！', `MaleText_loc5`='我相信你，咯咯!', `MaleText_loc7`='¡Creo en ti, Gluber!' WHERE `ID`=68757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말라깽이, 저 조련사에게 우리가 어떻게 싸우는지 보여주지 않겠어?', `MaleText_loc4`='斯蒂奇，你愿不愿意让我们这位准驯宠师瞧瞧，我们是如何战斗的？', `MaleText_loc5`='縫合怪，你可以讓我們這位訓練師看看我們怎麼戰鬥的嗎?', `MaleText_loc7`='Costuras, ¿te importa enseñarle cómo nos gusta luchar?' WHERE `ID`=68758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드로가르, 놈들을 부숴버려라!', `MaleText_loc4`='卓戈，消灭他们！', `MaleText_loc5`='紫金雛龍，毀滅他們!', `MaleText_loc7`='¡Acaba con ellos, Drogar!' WHERE `ID`=68759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살점아귀가 너 없앤다.', `MaleText_loc4`='撕肉者现在要将你杀死。', `MaleText_loc5`='血肉撕裂者當場宰了你。', `MaleText_loc7`='Chupacarnes matarte.' WHERE `ID`=68760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이언포지의 긍지, 그리즐! 전투 개시!', `MaleText_loc4`='灰毛，铁炉堡的骄傲，前来应战吧！', `MaleText_loc5`='格里茲爾，鐵爐堡的驕傲，來到場上!', `MaleText_loc7`='Grisez, orgullo de Forjaz, ¡ven al campo de batalla!' WHERE `ID`=68761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방벽의 도르, 우리와 함께 싸워주렴.', `FemaleText_loc4`='铁壁龟，请来战场上加入我们。', `FemaleText_loc5`='多爾矮牆龜，請來到場上加入我們。', `FemaleText_loc7`='Dori la Tapia, acompáñanos en el campo de batalla.' WHERE `ID`=68762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시등이 너 박살 낸다!', `MaleText_loc4`='针背龟要打扁你！', `MaleText_loc5`='刺背龜會打敗你的!', `MaleText_loc7`='¡Conchaguja podrá contigo!' WHERE `ID`=68763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이빨파괴자, 누구도 널 이길 순 없지!', `FemaleText_loc4`='没人能击败你，崩牙者！', `FemaleText_loc5`='斷齒菜頭妖，沒有人能打敗你!', `FemaleText_loc7`='¡Nadie puede contigo, Rompedientes!' WHERE `ID`=68764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매애애, 나와서 적과 싸우거라.', `MaleText_loc4`='咩咩，来面对这位敌人吧。', `MaleText_loc5`='羊咩咩，過來面對這個敵人。', `MaleText_loc7`='Baladín' WHERE `ID`=68765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덜컥이, 나와서 싸워라.', `MaleText_loc4`='来战斗吧，碎石蟹。', `MaleText_loc5`='來戰鬥吧，尖刺硬殼蟹。', `MaleText_loc7`='Ven y lucha, Estrujos.' WHERE `ID`=68766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭풍채찍, 놈들을 박살 내버려라.', `FemaleText_loc4`='鞭风者，击溃这些敌人。', `FemaleText_loc5`='風暴雲蛟，消滅這些敵人。', `FemaleText_loc7`='Colatifón, aplasta a nuestros enemigos.' WHERE `ID`=68767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조각이, 놈들을 산산조각 내버려라!', `MaleText_loc4`='将他们撕成碎片，脆脆！', `MaleText_loc5`='把他們撕碎，裂面晶簇!', `MaleText_loc7`='¡Hazlos pedazos, Fisura!' WHERE `ID`=68768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칼리, 이리 나오거라.', `MaleText_loc4`='我召唤你，卡利。', `MaleText_loc5`='我召喚你，卡利。', `MaleText_loc7`='Yo te invoco, Kali.' WHERE `ID`=68769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아미델, 놈들의 흔적조차 남기지 마라. 없애버려!', `MaleText_loc4`='让他们灰飞烟灭，阿米瑟尔。消灭他们！', `MaleText_loc5`='別讓他們留下一點渣渣，混種獸。摧毀他們!', `MaleText_loc7`='No dejes ni los restos, Amythel. ¡Acaba con ellos!' WHERE `ID`=68770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배암의 강력함을 이겨낼 순 없을 거요.', `MaleText_loc4`='你在匹兹的力量面前毫无机会。', `MaleText_loc5`='在派斯蟒蛇的力量之前你一點機會也沒有。', `MaleText_loc7`='No tienes ninguna posibilidad contra Ofidia.' WHERE `ID`=68771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 오랜 친구, 슉슉이. 이제 네가 싸울 차례구나.', `MaleText_loc4`='掠影者，我的老朋友，该你出战了。', `MaleText_loc5`='浮杓水黽，老朋友，輪到你上場了。', `MaleText_loc7`='Flotador, viejo amigo, es hora de luchar.' WHERE `ID`=68772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가거라, 낯선 아이야. 다시 만나면 너를 ''친구''라고 부르고 싶구나.', `FemaleText_loc4`='后会有期。希望我们下次碰面时能成为“朋友”。', `FemaleText_loc5`='再見，陌生人。下次遇到，希望能稱你為朋友。', `FemaleText_loc7`='Adiós. La próxima vez que nos veamos, espero que ya no seamos extraños, sino amigos.' WHERE `ID`=68773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 흐려집니다.', `MaleText_loc4`='%s消退了。', `MaleText_loc5`='%s消失了。', `MaleText_loc7`='%s se desvanece.' WHERE `ID`=68774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 고갈됩니다.', `MaleText_loc4`='%s被耗竭了。', `MaleText_loc5`='%s耗盡了。', `MaleText_loc7`='%s se agota.' WHERE `ID`=68775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 다시 해 보세요!', `FemaleText_loc4`='来吧，再试一次！', `FemaleText_loc5`='快點，再試一次!', `FemaleText_loc7`='¡Inténtalo de nuevo!' WHERE `ID`=68777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신 앞에 칼날이 공중에 떠 있습니다.>', `MaleText_loc4`='<刀刃在你前方的空中盘旋。>', `MaleText_loc5`='<劍在你面前的空中盤旋著。>', `MaleText_loc7`='<La espada flota frente a ti.>' WHERE `ID`=68779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 사냥꾼이냐? 내가 네 야수 금방 고쳐줄 수 있다!', `MaleText_loc4`='你是一位猎人？我能快速帮你解决野兽的难题！', `MaleText_loc5`='你是個獵人?我可以立刻治好你的小野獸!', `MaleText_loc7`='¿Tú $gkazador:kazadora;? ¡Yo kuro a tus bestias muy rápido!' WHERE `ID`=68780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌봐줘야 하는 애완동물이 있나? 내가 잡아먹지 않는다고 약속하지.', `MaleText_loc4`='你需要别人帮你照看宠物？我保证会多加考虑，争取别吃掉它们。', `MaleText_loc5`='你的寵物需要診斷嗎?我保證我不會吃掉他們。', `MaleText_loc7`='¿Necesitas que alguien cuide de tus mascotas? Te prometo que me plantearé no comérmelas.' WHERE `ID`=68781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 어떻게 지내?', `MaleText_loc4`='嗨，头儿，情况如何？', `MaleText_loc5`='是的老闆，狀況如何?', `MaleText_loc7`='¡Hola, $gjefe:jefa;! ¿Ké tal?' WHERE `ID`=68783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 시작일 뿐이다... 우리가 그냥 쉽게 죽을 거라 생각 마...', `MaleText_loc4`='这只是个开始……我们可不会接二连三地倒下……', `MaleText_loc5`='這才剛剛開始...我們不會坐以待斃的...', `MaleText_loc7`='Eh''to acaba de empezar... No nos dejaremos matar sin más...' WHERE `ID`=68784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날... 풀어 다오. 클락시가 나를 부른다.', `FemaleText_loc4`='放、开、我。卡拉克西在召唤。', `FemaleText_loc5`='放我走...卡拉西在呼喚...', `FemaleText_loc7`='LIBÉRAME... LOS KLAXXI LLAMAN...' WHERE `ID`=68785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부화의 때가 다가왔다. 무리의 부름에 답해야 한다.', `FemaleText_loc4`='孵化的时间快到了。我必须回应虫群的召唤。', `FemaleText_loc5`='孵化時間到了...我必須回應蟲群...', `FemaleText_loc7`='LA HORA DE LA ECLOSIÓN SE ACERCA... DEBO RESPONDER ANTE EL ENJAMBRE...' WHERE `ID`=68786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 되지. 날 이 끔찍한 감옥에 가두어 둘 순 없다.', `FemaleText_loc4`='不。你休想把我关进这该死的牢笼。', `FemaleText_loc5`='不...你不能把我關在這個可惡的牢籠裡...', `FemaleText_loc7`='NO. NO ME ENCERRARÁS EN ESTA HORRIBLE PRISIÓN.' WHERE `ID`=68787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='큰엄마 스톰스타우트는 이제 이 세상에 없다!', `FemaleText_loc4`='她再也不是风暴烈酒大妈了！', `FemaleText_loc5`='風暴烈酒大娘已經不在了...', `FemaleText_loc7`='¡MAMÁ CERVEZA DE TRUENO YA NO ESTÁ AQUÍ!' WHERE `ID`=68788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_weapon_shortblade_37.blp:32|t 강한 공격$b$b|TInterface\\Icons\\inv_weapon_shortblade_92.blp:32|t 더 강한 공격$b$b|TInterface\\Icons\\ability_rogue_shadowstrikes.blp:32|t 가장 강한 공격', `MaleText_loc4`='|TInterface\\Icons\\inv_weapon_shortblade_37.blp:32|t猛攻$b$b|TInterface\\Icons\\inv_weapon_shortblade_92.blp:32|t强攻$b$b|TInterface\\Icons\\ability_rogue_shadowstrikes.blp:32|t狂攻', `MaleText_loc5`='|TInterface\\Icons\\inv_weapon_shortblade_37.blp:32|t  強攻擊$b$b|TInterface\\Icons\\inv_weapon_shortblade_92.blp:32|t更強攻擊$b$b|TInterface\\Icons\\ability_rogue_shadowstrikes.blp:32|t最強攻擊', `MaleText_loc7`='|TInterfaceIconsinv_weapon_shortblade_37.blp:32|t Ataque fuerte$b$b|TInterfaceIconsinv_weapon_shortblade_92.blp:32|t Ataque más fuerte$b$b|TInterfaceIconsability_rogue_shadowstrikes.blp:32|t Ataque fortísimo' WHERE `ID`=68789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 해안에 전쟁을 가져온다면, 이 땅 그 자체가 자네 열정과 폭력에 반응할 걸세. 어떤 결과가 나타날지는 나도 모르네. 아무도 모르지.', `MaleText_loc4`='如果你想将战火引到我们的海岸，那么这片土地会对你的冲动和暴力作出回应。我不知道最终会造成什么后果——没人知道。', `MaleText_loc5`='如果你想要把戰爭帶來我們的海岸，土地本身就會回應你們的激情和暴力。我不知道最終的後果是什麼...沒有人知道。', `MaleText_loc7`='Si pretenden traer la guerra a nuestra costa, la tierra misma responderá a sus pasiones y a su violencia. No sé cuáles serán las consecuencias definitivas... Nadie lo sabe.' WHERE `ID`=68790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대포를 장전하라!', `MaleText_loc4`='装填炮弹！', `MaleText_loc5`='裝填那些大砲!', `MaleText_loc7`='¡Carguen los cañones!', `FemaleText_loc1`='대포를 장전하라!', `FemaleText_loc4`='装填炮弹！', `FemaleText_loc5`='裝填那些大砲!', `FemaleText_loc7`='¡Carguen los cañones!' WHERE `ID`=68791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 지옥을 보여줘라!', `MaleText_loc4`='送他们下地狱！', `MaleText_loc5`='給他們死!', `MaleText_loc7`='¡Envíenlos al infierno!', `FemaleText_loc1`='놈들에게 지옥을 보여줘라!', `FemaleText_loc4`='送他们下地狱！', `FemaleText_loc5`='給他們死!', `FemaleText_loc7`='¡Envíenlos al infierno!' WHERE `ID`=68792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 끔찍한 괴물을 하늘에서 날려버려!', `MaleText_loc4`='把那怪物从天上炸下来！', `MaleText_loc5`='把那怪物轟上天去!', `MaleText_loc7`='¡Derriben a esa abominación!', `FemaleText_loc1`='저 끔찍한 괴물을 하늘에서 날려버려!', `FemaleText_loc4`='把那怪物从天上炸下来！', `FemaleText_loc5`='把那怪物轟上天去!', `FemaleText_loc7`='¡Derriben a esa abominación!' WHERE `ID`=68793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길을 진압하라!', `MaleText_loc4`='控制住火势！', `MaleText_loc5`='控制火勢!', `MaleText_loc7`='¡Que alguien controle los incendios!', `FemaleText_loc1`='불길을 진압하라!', `FemaleText_loc4`='控制住火势！', `FemaleText_loc5`='控制火勢!', `FemaleText_loc7`='¡Que alguien controle los incendios!' WHERE `ID`=68794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 배고픈 사람들을 위해 잔반으로 상을 차립니다.', `MaleText_loc4`='$n给饥肠辘辘的人们准备了一些剩菜剩饭。', `MaleText_loc5`='$n準備了一些剩飯給飢餓的人們。', `MaleText_loc7`='$n prepara unas sobras para la gente con hambre.', `FemaleText_loc1`='$n|1이;가; 배고픈 사람들을 위해 잔반으로 상을 차립니다.', `FemaleText_loc4`='$n给饥肠辘辘的人们准备了一些剩菜剩饭。', `FemaleText_loc5`='$n準備了一些剩飯給飢餓的人們。', `FemaleText_loc7`='$n prepara unas sobras para la gente con hambre.' WHERE `ID`=68795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\trade_archaeology_delicatemusicbox.blp:20|t황실 장로 조르로크가 |cFFFF0000|Hspell:123791|h[여제의 노래]|h|r를 부릅니다!', `MaleText_loc4`='|Tinterface/Icons/trade_archaeology_delicatemusicbox.blp:20|t皇家宰相佐尔洛克吟唱了|cFFFF0000|Hspell:123791|h[女皇赞歌]|h|r！', `MaleText_loc5`='|Tinterface/Icons/trade_archaeology_delicatemusicbox.blp:20|t女皇大臣索拉格唱著|cFFFF0000|Hspell:123791|h[女皇之歌]|h|r!', `MaleText_loc7`='|TInterfaceIcons	rade_archaeology_delicatemusicbox.blp:20|t¡El visir imperial Zor''lok canta la |cFFFF0000|Hspell:123791|h[Canción de la Emperatriz]|h|r!' WHERE `ID`=68797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 피해를 확인하라. 이건 뭐지? 얼라이언스 요새군. 이 땅이 자기네 거라고, 응? 절대 안 돼!', `MaleText_loc4`='够了！清点伤亡。那是什么……联盟的据点！他们认为已经占领这片土地了？有我在，休想！', `MaleText_loc5`='夠了!檢查受損程度。前面...有聯盟營地。他們以為可以就這樣佔領這片大陸?有我在就不可能!', `MaleText_loc7`='¡Basta! Control de daños. Ahí adelante... una base de la Alianza. ¿Creen que ya pueden adueñarse de esta tierra? No mientras yo viva.' WHERE `ID`=68798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 죽기 싫으면 당장 엔진을 수리해. 그리고 전력으로 기지를 공격해라!', `MaleText_loc4`='快把引擎修好，否则我们就死在天上了。全力攻击那个联盟基地！', `MaleText_loc5`='修好那些引擎，不然我們就會死在這裡。然後對那個聯盟營地火力全開!', `MaleText_loc7`='Reparen los motores si es que quieren volver a pisar tierra. ¡Y láncenle todo lo que tengamos a esa base de la Alianza!' WHERE `ID`=68799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 그래. 헬스크림의 분노를 보여줘라!', `MaleText_loc4`='对极了。让他们尝尝地狱咆哮的怒火！', `MaleText_loc5`='哈哈!沒錯。讓他們看看地獄吼之怒!', `MaleText_loc7`='Eso es. ¡Que prueben la furia de Grito Infernal!' WHERE `ID`=68800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우라조에 대한 복수다! 아하하하!', `MaleText_loc4`='那一下是为陶拉祖报仇！', `MaleText_loc5`='這一發是為了陶拉祖!', `MaleText_loc7`='¡Esa es nuestra venganza por Taurajo!' WHERE `ID`=68801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 움직이는 건 모두 죽여!', `MaleText_loc4`='哈哈哈！杀死一切喘气儿的东西！', `MaleText_loc5`='哈!殺死所有會動的東西!', `MaleText_loc7`='¡Maten todo lo que se mueva!' WHERE `ID`=68802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 개들이 여기에 정착할 일은 없다.', `MaleText_loc4`='联盟狗在这片土地上没有立足之地。', `MaleText_loc5`='聯盟的走狗在這片土地無處藏身!', `MaleText_loc7`='¡Los perros de la Alianza no hallarán refugio en esta tierra!' WHERE `ID`=68803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 정확히 조준해라! 놈들을 스톰윈드까지 날려버려!', `MaleText_loc4`='瞄准射击！把他们赶回暴风城！', `MaleText_loc5`='射準點!讓他們用爬的回去暴風城。', `MaleText_loc7`='¡Apunten bien! ¡Que vuelvan a Ventormenta cojeando!' WHERE `ID`=68804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼쭐을 내줬군. 호드의 힘 앞에 쥐새끼처럼 도망치고 숨어라. 자비는 없다!', `MaleText_loc4`='我们已经挫了他们的锐气。在部落的力量面前，他们抱头鼠窜。绝不留情！', `MaleText_loc5`='我們削弱他們了。他們在部落的力量下像老鼠一樣東躲西藏。不留活口!', `MaleText_loc7`='Los hemos asustado. Corren y se esconden como ratas ante el poder de la Horda. ¡SIN CUARTEL!' WHERE `ID`=68805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 겁쟁이 지도자가 이 방벽 뒤에 숨었다. 공병은 어디 있나?', `MaleText_loc4`='他们懦弱的领袖就藏在这道屏障后面。我的工兵去哪儿了？', `MaleText_loc5`='他們膽小的指揮官躲在防禦工事後面。我們工兵去哪了?', `MaleText_loc7`='Su líder se atrincheró detrás de la barricada, el muy cobarde. Avísame cuando quieras que avancemos.' WHERE `ID`=68806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!' WHERE `ID`=68807;
