UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수도사들을 클릭해서 넘어뜨리십시오.', `FemaleText_loc4`='点击武僧以击退他们。', `FemaleText_loc5`='點擊武僧來擊退他們。', `FemaleText_loc7`='Haz clic en los monjes para repelerlos.' WHERE `ID`=68809;
