UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"살핌"을 잃어버렸습니다.', `MaleText_loc4`='我把“探路棍”弄丢了。', `MaleText_loc5`='我失去了「監控」。', `MaleText_loc7`='He perdido el "Escrutinio".', `FemaleText_loc1`='"살핌"을 잃어버렸어요.', `FemaleText_loc4`='我把“探路棍”弄丢了。', `FemaleText_loc5`='我失去了「監控」。', `FemaleText_loc7`='He perdido el "Escrutinio".' WHERE `ID`=68811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 이방인이여. 그런 기분은... 처음이었소.', `MaleText_loc4`='谢谢你，陌生人。我……从没有过那样的感觉。', `MaleText_loc5`='謝謝你，陌生人。我...從沒有過那種感覺。', `MaleText_loc7`='Gracias, $gforastero:forastera;. Nunca había sentido nada parecido.' WHERE `ID`=68812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑자기 삶이 훨씬 밝아 보여요.$B$B잠자는 건 아직 좋지만요.', `MaleText_loc4`='人生突然变得充满光明。$B$B虽然我还是喜欢睡觉。', `MaleText_loc5`='生命突然間變得比較有希望了。$B$B不過我還是很愛睡覺。', `MaleText_loc7`='De repente la vida parece más alegre.$b$bPero me sigue gustando dormir.', `FemaleText_loc1`='갑자기 삶이 훨씬 밝아 보여요.$B$B잠자는 건 아직 좋지만요.', `FemaleText_loc4`='人生突然变得充满光明。$B$B虽然我还是喜欢睡觉。', `FemaleText_loc5`='生命突然間變得比較有希望了。$B$B不過我還是很愛睡覺。', `FemaleText_loc7`='De repente la vida parece más alegre.$b$bPero me sigue gustando dormir.' WHERE `ID`=68813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 한 번 감사드립니다. 전 잠시 여기 머물면서 부상자 치료를 도우려 합니다.$B$B그런 다음엔 북쪽으로 가야지요...', `MaleText_loc4`='再次感谢你的帮助。我会暂时留在这里，帮忙照料伤患。$B$B然后我会向北行进……', `MaleText_loc5`='再次感謝你的幫助。我會留在這裡一小段時間，幫助照料傷患。$B$B然後我會往北方去...', `MaleText_loc7`='Gracias de nuevo por tu ayuda. Me quedaré un rato más para atender a los heridos.$b$bLuego me marcharé al norte...' WHERE `ID`=68814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현재로 돌아가고 싶습니다.', `MaleText_loc4`='送我回到现在。', `MaleText_loc5`='把我帶回現在。', `MaleText_loc7`='Llévame de vuelta al presente.', `FemaleText_loc1`='현재로 돌아가고 싶어요.', `FemaleText_loc4`='送我回到现在。', `FemaleText_loc5`='把我帶回現在。', `FemaleText_loc7`='Llévame de vuelta al presente.' WHERE `ID`=68815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='현재로 돌아가고 싶다면 언제든지 말씀하세요.', `FemaleText_loc4`='当你准备好回到现在时，再开口发问。', `FemaleText_loc5`='準備好回到現在時，講一聲就好。', `FemaleText_loc7`='Si quieres volver al presente, solo tienes que decirlo.' WHERE `ID`=68816;
