UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가면을 잃어버렸습니다. 새 가면이 필요해요.', `MaleText_loc4`='我……我弄丢了面具。需要一个新的。', `MaleText_loc5`='我... 搞丟了我的面具。我需要再拿個新的。', `MaleText_loc7`='He... perdido la máscara. Necesito otra.', `FemaleText_loc1`='가면을 잃어버렸어요. 새 가면이 필요해요.', `FemaleText_loc4`='我……我弄丢了面具。需要一个新的。', `FemaleText_loc5`='我... 搞丟了我的面具。我需要再拿個新的。', `FemaleText_loc7`='He... perdido la máscara. Necesito otra.' WHERE `ID`=68819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 바람 폭탄을 터트렸습니다!', `MaleText_loc4`='$n引爆了风爆弹！', `MaleText_loc5`='$n引爆了一顆風之炸彈!', `MaleText_loc7`='¡$n ha detonado una bomba de viento!' WHERE `ID`=68820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린이 은둔 고수를 찾았다는 얘기 들으셨습니까? 그분은 지금 파오취앤 대나무숲에 있습니다.', `MaleText_loc4`='你听说林找到隐秘大师了吗？他在抱拳林。', `MaleText_loc5`='你知道林已經找到隱居的宗師了嗎?他就在泡泉谷。', `MaleText_loc7`='¿Sabes que Lin encontró al maestro oculto? Está en la Espesura Paoquan.', `FemaleText_loc1`='린이 은둔 고수를 찾았다는 얘기 들으셨나요? 그분은 지금 파오취앤 대나무숲에 있답니다.', `FemaleText_loc4`='你听说林找到隐秘大师了吗？他在抱拳林。', `FemaleText_loc5`='你知道林已經找到隱居的宗師了嗎?他就在泡泉谷。', `FemaleText_loc7`='¿Sabes que Lin encontró al maestro oculto? Está en la Espesura Paoquan.' WHERE `ID`=68821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 린이 찾았답니까? 은둔 고수가 파오취앤 대나무숲에 있단 말이지요?$b$b그러면 저도 좀 가봐야겠군요. 그... 밥 좀 몇 그릇 더 먹고 나서 말입니다.', `MaleText_loc4`='她找到了？他在抱拳林？$b$b看来我得走一趟了。也许……等我再吃几口……', `MaleText_loc5`='真的?$b$b那我大概也得趕去那裡了...好吧，先吃幾口東西再說。', `MaleText_loc7`='¿De verdad que lo encontró? ¿De verdad que está en la Espesura Paoquan?$b$bVoy a tener que acercarme. A lo mejor después de comer un poco más...' WHERE `ID`=68822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린이 은둔 고수를 찾았다고? 그러면 이제 훈련을 계속할 수 있겠다!$b$b그런데 할 일이 하나 있다. 컨 컨 슬픈 주민들 먼저 도와줘야 한다. 여기엔 슬픈 이들이 너무 많다.', `MaleText_loc4`='林找到隐秘大师了？那我们的训练可以继续了！$b$b现在就还剩下一件事。肯肯得先帮助那些悲伤的家伙。这里有太多哀苦的人了。', `MaleText_loc5`='林找到隱居的大師了?那我們的修練可以繼續進行了!$b$b但是還有件事情，肯·肯必須先幫助那些需要幫助的人。有太多人需要幫助了。', `MaleText_loc7`='¿Lin enkuentra al maestro okulto? ¡Entonces nosotros pueden seguir entrenando!$b$bSolo una kosa. Antes Ken-Ken debe ayudar a los tristes. Akí hay demasiados tristes.' WHERE `ID`=68823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿을 수가 없군요! 전 그 은둔 고수라는 분이 여기 크라사랑 밀림에 있는 줄로만 알았거든요.$b$b파오취앤 대나무숲이라고 하셨나요? 저도 곧 그리로 갈게요. 지금 당장은 좀 힘들어요. 이미 모험거리를 찾았거든요.', `MaleText_loc4`='真令人难以置信！我以为隐秘大师一定会在荒野里。$b$b你说在抱拳林？我很快就会去找林，然后我们就能继续训练了。至于目前嘛，我已经找到属于自己的冒险了。', `MaleText_loc5`='真不敢相信!我很確定他人會在喀撒朗蠻荒的說。$b$b什麼，在泡泉谷?我會盡快去找她的，然後我們就可以繼續進行訓練。至於現在，我已經找到了屬於我自己的冒險。', `MaleText_loc7`='¡No me lo puedo creer! Sabía que estaría aquí.$b$b¿La Espesura Paoquan, dices? Iré a verla enseguida para continuar con nuestro entrenamiento, pero de momento he encontrado una aventura propia.' WHERE `ID`=68824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 저는 린이 은둔 고수를 찾아낼 줄 알았습니다. 부끄럼을 타기는 하지만 강한 친구니까요.$b$b일단 여기서 제 일을 좀 끝낸 뒤에 린에게 가겠습니다.', `MaleText_loc4`='果然，我就知道她能办到。她尽管羞涩，但却强大得很。$b$b我得先干完这里的事。然后就去找她。', `MaleText_loc5`='嗯，我知道她一定辦得到。她雖然害羞，其實內心很堅強。$b$b我會趕緊把這裡的事情做個了結，然後去找她。', `MaleText_loc7`='Sí. Sabía que lo conseguiría. Es tímida, pero fuerte.$b$bTerminaré con mis asuntos pendientes aquí y me reuniré con ella.' WHERE `ID`=68825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(클락시 공명이 활성화된 상태로 영웅 난이도에서 우두머리를 처치했습니다. 이제 클락시 공명을 비활성화할 수 없습니다.)', `MaleText_loc4`='（已通过启用卡拉克西共鸣，在英雄难度下击败了某位首领。该效果不能被取消。）', `MaleText_loc5`='(一個首領已經在卡拉西共鳴作用的情況下在英雄難度中被擊敗。卡拉西共鳴已經無法被停止了。)', `MaleText_loc7`='(Se ha derrotado a un jefe en dificultad heroica con Resonancia Klaxxi habilitada. Ya no se puede deshabilitar.)' WHERE `ID`=68832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='(정화의 의식이 활성화된 상태로 영웅 난이도에서 우두머리를 처치했습니다. 이제 정화의 의식을 비활성화할 수 없습니다.)', `MaleText_loc4`='（已通过启用净化仪式，在英雄难度下击败了某位首领。该效果不能被取消。）', `MaleText_loc5`='(一個首領已經在淨化儀式作用的情況下在英雄難度中被擊敗。淨化儀式已經無法被停止了。)', `MaleText_loc7`='(Se ha derrotado a un jefe en dificultad heroica con Ritual de purificación activado. Ya no se puede desactivar.)' WHERE `ID`=68833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 허드렛일을 할 준비가 됐습니다.', `MaleText_loc4`='我准备好帮你处理那些杂事了。', `MaleText_loc5`='我可以跟你一起去辦那些事情了。', `MaleText_loc7`='Puedo echarte una mano cuando quieras.', `FemaleText_loc1`='당신과 함께 허드렛일을 할 준비가 됐어요.', `FemaleText_loc4`='我准备好帮你处理那些杂事了。', `FemaleText_loc5`='我可以跟你一起去辦那些事情了。', `FemaleText_loc7`='Puedo echarte una mano cuando quieras.' WHERE `ID`=68834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 벌어질 일은 이 땅을 영영 바꾸어 놓을 거예요.', `FemaleText_loc4`='在这里发生的事情将永远改变这片土地。', `FemaleText_loc5`='這些個變化會徹底改變這塊土地。', `FemaleText_loc7`='Los acontecimientos que han tenido lugar cambiarán esta tierra para siempre.' WHERE `ID`=68835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 사는 게 익숙해질 것도 같은데...', `MaleText_loc4`='我可以适应这种生活的。', `MaleText_loc5`='住這樣倒也還不壞。', `MaleText_loc7`='Me podría acostumbrar a este tipo de vida.' WHERE `ID`=68836;
