UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.', `MaleText_loc4`='哎哟……抱歉，$n。请回去重新排队，再试一次。', `MaleText_loc5`='噢...抱歉，$n。回去排好隊再來試一次。', `MaleText_loc7`='Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.', `FemaleText_loc1`='아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.', `FemaleText_loc4`='哎哟……抱歉，$n。请回去重新排队，再试一次。', `FemaleText_loc5`='噢...抱歉，$n。回去排好隊再來試一次。', `FemaleText_loc7`='Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.' WHERE `ID`=68841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!', `MaleText_loc4`='现在上场的是——1级$r$c，$n！$n是一位新人，所以请不要紧张！', `MaleText_loc5`='現在進入競技場的是:第1階的$r$c，$n!$n還是個新人，所以手下留情啊!', `MaleText_loc7`='Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tengan paciencia!', `FemaleText_loc1`='투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!', `FemaleText_loc4`='现在上场的是——1级$r$c，$n！$n是一位新人，所以请不要紧张！', `FemaleText_loc5`='現在進入競技場的是:第1階的$r$c，$n!$n還是個新人，所以手下留情啊!', `FemaleText_loc7`='Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tengan paciencia!' WHERE `ID`=68842;
