UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.', `MaleText_loc4`='很好很好！$n获胜！看来我要欠某人一些钱了。', `MaleText_loc5`='非常好!$n獲勝!看來我欠別人的賭債變多了。', `MaleText_loc7`='¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.', `FemaleText_loc1`='이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.', `FemaleText_loc4`='很好很好！$n获胜！看来我要欠某人一些钱了。', `FemaleText_loc5`='非常好!$n獲勝!看來我欠別人的賭債變多了。', `FemaleText_loc7`='¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.' WHERE `ID`=68844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.', `MaleText_loc4`='祝贺你，$n！请不要在场外留下血脚印。', `MaleText_loc5`='恭喜，$n!請不要把沾了血跡的腳印留在競技場外。', `MaleText_loc7`='¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.', `FemaleText_loc1`='축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.', `FemaleText_loc4`='祝贺你，$n！请不要在场外留下血脚印。', `FemaleText_loc5`='恭喜，$n!請不要把沾了血跡的腳印留在競技場外。', `FemaleText_loc7`='¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.' WHERE `ID`=68845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!', `MaleText_loc4`='官方消息！$n活下来了。能活下来就不容易啊，$n！', `MaleText_loc5`='動真格了!$n竟然還活著。活著就很了不起，$n!', `MaleText_loc7`='¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!', `FemaleText_loc1`='끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!', `FemaleText_loc4`='官方消息！$n活下来了。能活下来就不容易啊，$n！', `FemaleText_loc5`='動真格了!$n竟然還活著。活著就很了不起，$n!', `FemaleText_loc7`='¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!' WHERE `ID`=68846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!', `MaleText_loc4`='呃……真是一团糟。找个牧师之类的来好吗？！', `MaleText_loc5`='噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!', `MaleText_loc7`='Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!', `FemaleText_loc1`='우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!', `FemaleText_loc4`='呃……真是一团糟。找个牧师之类的来好吗？！', `FemaleText_loc5`='噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!', `FemaleText_loc7`='Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!' WHERE `ID`=68847;
