UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 심은 채소를 다른 채소로 바꿀 수도 있습니까?', `MaleText_loc4`='我可以替换已经种下去的作物吗？', `MaleText_loc5`='我可以把已經種下的作物換掉嗎?', `MaleText_loc7`='¿Es posible sustituir algo que ya he plantado?', `FemaleText_loc1`='이미 심은 채소를 다른 채소로 바꿀 수도 있나요?', `FemaleText_loc4`='我可以替换已经种下去的作物吗？', `FemaleText_loc5`='我可以把已經種下的作物換掉嗎?', `FemaleText_loc7`='¿Es posible sustituir algo que ya he plantado?' WHERE `ID`=68850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 제가 할아버지의 삽을 다른 농기구들과 함께 놓아두었습니다.$B$B이 삽으로 자라는 채소를 파낸 뒤 땅을 고르고 나면 다른 채소를 심을 수 있습니다.', `MaleText_loc4`='当然可以！我从一大堆农具里找到了我爷爷的铲子。$B$B你可以用它来挖掉生长中的作物，清理出田地来种别的东西。', `MaleText_loc5`='當然可以!我把爺爺的鏟子跟其他的工具放在一起了。$B$B你可以用鏟子來挖掘成長中的作物，記得把土地清理乾淨以便種植其他的東西。', `MaleText_loc7`='¡Pues claro! Dejé la pala del abuelo con las demás herramientas.$b$bPuedes utilizarla para sacar una planta creciente y así despejar la tierra para plantar otra cosa.' WHERE `ID`=68851;
