UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 바쁘군. 최소 10명 정도가 자네 앞에 대기 중이네. 열 명보다 엄청 많진 않아 다행이야.', `MaleText_loc4`='今天人很多。你前面至少还有十个人。不过你应该不用等很久。', `MaleText_loc5`='今天挺忙的。至少有十個人排在你前面。至少應該不會超過這個數字啦。', `MaleText_loc7`='Es un día ajetreado. Hay al menos diez personas en la cola antes que tú, pero no mucho más.', `FemaleText_loc1`='오늘 바쁘군. 최소 10명 정도가 자네 앞에 대기 중이네. 열 명보다 엄청 많진 않아 다행이야.', `FemaleText_loc4`='今天人很多。你前面至少还有十个人。不过你应该不用等很久。', `FemaleText_loc5`='今天很忙。至少有十個人排在你前面。至少應該不會超過這個數字啦。', `FemaleText_loc7`='Es un día ajetreado. Hay al menos diez personas en la cola antes que tú, pero no mucho más.' WHERE `ID`=68880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 앞에 최소 15명이 기다리고 있네. 흠, 오늘 좀 바쁜 것 같아.', `MaleText_loc4`='你前面至少还有十五个人。这很难说——现在人有点儿多。', `MaleText_loc5`='你前面至少排了十五個人。很難說 - 這裡現在還滿忙的。', `MaleText_loc7`='Hay al menos quince personas esperando antes que tú, pero es difícil de decir... Ahora mismo estamos muy ocupados.', `FemaleText_loc1`='자네 앞에 최소 15명이 기다리고 있네. 흠, 오늘 좀 바쁜 것 같아.', `FemaleText_loc4`='你前面至少还有十五个人。这很难说——现在人有点儿多。', `FemaleText_loc5`='你前面至少排了十五個人。很難說 - 這裡現在還滿忙的。', `FemaleText_loc7`='Hay al menos quince personas esperando antes que tú, pero es difícil de decir... Ahora mismo estamos muy ocupados.' WHERE `ID`=68881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 기다리게, 최소 스무 명이 자네보다 먼저 왔어. 잠깐, 스무 명하고 몇 명 더 있을지도...', `MaleText_loc4`='等着吧——你前面至少还有二十个人。没准还不止。', `MaleText_loc5`='繼續等吧 - 至少有二十個人比你還早到。可能還不只。', `MaleText_loc7`='Espera $gsentado:sentada;. Hay al menos veinte personas que han llegado antes que tú. A lo mejor son más.', `FemaleText_loc1`='계속 기다리게, 최소 스무 명이 자네보다 먼저 왔어. 잠깐, 스무 명하고 몇 명 더 있을지도...', `FemaleText_loc4`='等着吧——你前面至少还有二十个人。没准还不止。', `FemaleText_loc5`='繼續等吧 - 至少有二十個人比你還早到。可能還不只。', `FemaleText_loc7`='Espera $gsentado:sentada;. Hay al menos veinte personas que han llegado antes que tú. A lo mejor son más.' WHERE `ID`=68882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아하니 자네는 30번째? 40번째? 이런, 몇 명이었더라.', `MaleText_loc4`='我想你应该是第三十个？也许是第四十个？我刚才数糊涂了。', `MaleText_loc5`='我猜你是隊伍裡第三十個?還是第四十個?我已經有點記不清楚了。', `MaleText_loc7`='Creo que eres $gel:la; número... ¿treinta? ¿Cuarenta? Hace un rato que he perdido la cuenta.', `FemaleText_loc1`='보아하니 자네는 30번째? 40번째? 이런, 몇 명이었더라.', `FemaleText_loc4`='我想你应该是第三十个？也许是第四十个？我刚才数糊涂了。', `FemaleText_loc5`='我猜你是隊伍裡第三十個?還是四十?我已經有點記不清楚了。', `FemaleText_loc7`='Creo que eres $gel:la; número... ¿treinta? ¿Cuarenta? Hace un rato que he perdido la cuenta.' WHERE `ID`=68883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 앞에 최소 50명이 기다리고 있네. 꽉 찼어. 앞으로 1시간이나 2시간 안에 꼭 싸우고 싶다면 잠시 열기가 가라앉길 기다린 다음 오는 게 좋을 걸세.', `MaleText_loc4`='你前面至少还有五十个人。这儿人太多了。如果你想在接下来的一到两个小时内打上的话，最好还是先等大家的热情稍微冷却一点后再来。', `MaleText_loc5`='你前面還排了至少五十個人。這邊已經擠滿了。我要是你的話會等一兩個小時等沒這麼忙了再回來打。', `MaleText_loc7`='Hay como mínimo cincuenta personas en la cola antes que tú. Esto está hasta la bandera. Si quieres luchar en una hora o dos, yo esperaría a que la cosa se calmase un poco.', `FemaleText_loc1`='자네 앞에 최소 50명이 기다리고 있네. 꽉 찼어. 앞으로 1시간이나 2시간 안에 꼭 싸우고 싶다면 잠시 열기가 가라앉길 기다린 다음 오는 게 좋을 걸세.', `FemaleText_loc4`='你前面至少还有五十个人。这儿人太多了。如果你想在接下来的一到两个小时内打上的话，最好还是先等大家的热情稍微冷却一点后再来。', `FemaleText_loc5`='你前面還排了至少五十個人。這邊已經擠滿了。我要是你的話會等一兩個小時等沒這麼忙了再回來打。', `FemaleText_loc7`='Hay como mínimo cincuenta personas en la cola antes que tú. Esto está hasta la bandera. Si quieres luchar en una hora o dos, yo esperaría a que la cosa se calmase un poco.' WHERE `ID`=68884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 앞에 몇 명이 싸움을 기다리고 있습니까?', `MaleText_loc4`='我前面还有多少人？', `MaleText_loc5`='我前面還排了多少人?', `MaleText_loc7`='¿Cuánta gente hay en la cola antes que yo?', `FemaleText_loc1`='제 앞에 몇 명이 싸움을 기다리고 있나요?', `FemaleText_loc4`='我前面还有多少人？', `FemaleText_loc5`='我前面還排了多少人?', `FemaleText_loc7`='¿Cuánta gente hay en la cola antes que yo?' WHERE `ID`=68887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요새 한창 잘나가는 2계급 $c, $n|1이;가; 싸움장에 들어섭니다!', `MaleText_loc4`='现在进场的是一位后起之秀——2级$c，$n！', `MaleText_loc5`='現在進入競技場的是:初嶄頭角第2階的$c，$n!', `MaleText_loc7`='Y ahora: $gun prometedor:una prometedora; $c de rango 2... ¡$n!', `FemaleText_loc1`='요새 한창 잘나가는 2계급 $c, $n|1이;가; 싸움장에 들어섭니다!', `FemaleText_loc4`='现在进场的是一位后起之秀——2级$c，$n！', `FemaleText_loc5`='現在進入競技場的是:初嶄頭角第2階的$c，$n!', `FemaleText_loc7`='Y ahora: $gun prometedor:una prometedora; $c de rango 2... ¡$n!' WHERE `ID`=68888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n에게 박수를 부탁드립니다! $n|1은;는; 3계급 $c입니다.', `MaleText_loc4`='请大家鼓掌欢迎——$n！$n是一位3级$c。', `MaleText_loc5`='掌聲鼓勵歡迎$n!$n現在是第3階的$c。', `MaleText_loc7`='¡Un aplauso para $n! $n es $gun:una; $c de rango 3.', `FemaleText_loc1`='$n에게 박수를 부탁드립니다! $n|1은;는; 3계급 $c입니다.', `FemaleText_loc4`='请大家鼓掌欢迎——$n！$n是一位3级$c。', `FemaleText_loc5`='掌聲鼓勵歡迎$n!$n現在是第3階的$c。', `FemaleText_loc7`='¡Un aplauso para $n! $n es $gun:una; $c de rango 3.' WHERE `ID`=68889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전자가 나타났습니다. 4계급 $r $c, $n|1을;를; 환영해 주십시오!', `MaleText_loc4`='下面是我们的挑战者。今天，我们迎来了一位4级$r$c，$n！', `MaleText_loc5`='這位就是今天的挑戰者。歡迎第4階的$r$c，$n!', `MaleText_loc7`='$gNuestro:Nuestra; combatiente de hoy es $gun:una; $r $c de rango 4... ¡$n!', `FemaleText_loc1`='도전자가 나타났습니다. 4계급 $r $c, $n|1을;를; 환영해 주십시오!', `FemaleText_loc4`='下面是我们的挑战者。今天，我们迎来了一位4级$r$c，$n！', `FemaleText_loc5`='這位就是今天的挑戰者。歡迎第4階的$r$c，$n!', `FemaleText_loc7`='$gNuestro:Nuestra; combatiente de hoy es $gun:una; $r $c de rango 4... ¡$n!' WHERE `ID`=68890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 싸움장에 주먹이 매콤한 $c|1이;가; 등장했습니다. 5계급 싸움꾼, $n에게 인사하세요!', `MaleText_loc4`='现在进场的是一位非常有天分的$c。大家一起欢迎5级拳手$n！', `MaleText_loc5`='現在進入競技場，我們歡迎天賦異秉的$c。跟第5階的鬥士$n打個招呼吧!', `MaleText_loc7`='Y ahora entra en la arena $gun:una; $c de gran talento. ¡Saluden a $n, $gun luchador:una luchadora; de rango 5!', `FemaleText_loc1`='지금 싸움장에 주먹이 매콤한 $c|1이;가; 등장했습니다. 5계급 싸움꾼, $n에게 인사하세요!', `FemaleText_loc4`='现在进场的是一位非常有天分的$c。大家一起欢迎5级拳手$n！', `FemaleText_loc5`='現在進入競技場，我們歡迎天賦異秉的$c。跟第5階的鬥士$n打個招呼吧!', `FemaleText_loc7`='Y ahora entra en la arena $gun:una; $c de gran talento. ¡Saluden a $n, $gun luchador:una luchadora; de rango 5!' WHERE `ID`=68891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오... 무시무시한 6계급 $r, $n|1이;가; 등장합니다!', `MaleText_loc4`='看呐……现在走来的是极度危险的6级$r，$n！', `MaleText_loc5`='當心了...現在出場的第6階，令人畏懼的$r，$n!', `MaleText_loc7`='¡Cuidado! Aquí viene $gel:la; $r letal de rango 6, ¡$n!', `FemaleText_loc1`='조심하십시오... 무시무시한 6계급 $r, $n|1이;가; 등장합니다!', `FemaleText_loc4`='看呐……现在走来的是极度危险的6级$r，$n！', `FemaleText_loc5`='當心了...現在出場的第6階，令人畏懼的$r，$n!', `FemaleText_loc7`='¡Cuidado! Aquí viene $gel:la; $r letal de rango 6, ¡$n!' WHERE `ID`=68892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 싸움장에 들어서는 건... 돌아온 최고의 싸움꾼, 7계급 $c $n입니다!', `MaleText_loc4`='现在进场的是一位归来的勇士。我们的7级$c，$n！', `MaleText_loc5`='現在進入競技場的是回歸的勇士，第7階的$c，$n!', `MaleText_loc7`='Y ahora vuelve a la arena $gun gran campeón:una gran campeona;: ¡$n, $gnuestro:nuestra; $c de rango 7!', `FemaleText_loc1`='지금 싸움장에 들어서는 건... 돌아온 최고의 싸움꾼, 7계급 $c $n입니다!', `FemaleText_loc4`='现在上场的是一位归来的勇士。我们的7级$c，$n！', `FemaleText_loc5`='現在進入競技場的是回歸的勇士，第7階的$c，$n!', `FemaleText_loc7`='Y ahora vuelve a la arena $gun gran campeón:una gran campeona;: ¡$n, $gnuestro:nuestra; $c de rango 7!' WHERE `ID`=68893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!', `MaleText_loc4`='现在进场的这位可谓是声名远扬，人见人爱。大家鼓掌欢迎我们的8级拳手，$N！！', `MaleText_loc5`='現在進入競技場的，你們都認識$g他:她;，你們都愛$g他:她;。掌聲歡迎第8階的鬥士$N!!', `MaleText_loc7`='Y $gel:la; siguiente combatiente... $gLo:La; conocen. $gLo:La; aman. ¡Un fuerte aplauso para $gnuestro luchador:nuestra luchadora; de nivel 8, $N!', `FemaleText_loc1`='드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!', `FemaleText_loc4`='现在上场的这位可谓是声名远扬，人见人爱。大家鼓掌欢迎我们的8级拳手，$N！！', `FemaleText_loc5`='現在進入競技場的，你們都認識$g他:她;，你們都愛$g他:她;。掌聲歡迎第8階的鬥士$N!!', `FemaleText_loc7`='Y $gel:la; siguiente combatiente... $gLo:La; conocen. $gLo:La; aman. ¡Un fuerte aplauso para $gnuestro luchador:nuestra luchadora; de nivel 8, $N!' WHERE `ID`=68894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 영광의 투기장에서 애완동물 대전이 벌어집니다!', `MaleText_loc4`='宠物对战！尽在荣耀斗兽场！', `MaleText_loc5`='寵物對戰!就在這，榮譽之環裡!', `MaleText_loc7`='¡Duelos de mascotas! ¡Aquí, en el Círculo de la Gloria!' WHERE `ID`=68897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조련사 여러분! 여러분의 애완동물이 다크문 축제에서 가장 강력한 애완동물 팀과 싸워 이길 수 있을까요?', `MaleText_loc4`='驯宠师们！你们的宠物能击败马戏团的顶尖高手吗？', `MaleText_loc5`='馴獸師!你的寵物能夠戰勝我們馬戲團裡面最厲害的寵物嗎?', `MaleText_loc7`='¡Domadores! ¿Creen que SUS mascotas pueden vencer al mejor equipo de la feria?' WHERE `ID`=68898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덩치가 작든 크든, 조련사에게 도전해보십시오! 제 애완동물과 싸워서 전부 이길 수 있겠습니까?', `MaleText_loc4`='所有驯宠师们的挑战！你敢来我的宠物对战吗？你能把它们全部打败吗？', `MaleText_loc5`='馴獸師的挑戰，難度自由選擇!你敢挑戰我的寵物並打贏它們嗎?', `MaleText_loc7`='¡Reto a todos los domadores, grandes o pequeños! ¿Sois capaces de vencer a todas mis mascotas?' WHERE `ID`=68899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물의 실력을 시험해보고, 최고의 조련사에게도 도전해보십시오!', `MaleText_loc4`='考验你的宠物，挑战顶尖高手！', `MaleText_loc5`='來測試一下你的寵物吧，來挑戰最強的那隻!', `MaleText_loc7`='¡Reten al mejor domador! ¡Pongan a prueba a sus mascotas!' WHERE `ID`=68900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최고의 조련사에게 도전해보겠나?$B$B너도 다른 이들처럼 패배하지 않을까?$B$B알 수 있는 방법은 한 가지뿐이지. 마음 대차게 먹고 덤벼 봐.$B$B다크문 게임 동전 한 닢만 있으면 돼...', `MaleText_loc4`='想要挑战顶尖高手吗？$B$B你会像别人一样铩羽而归吗？$B$B验证的办法只有一个。你敢来试试吗，$g先生:女士;？$B$B一个代币就能玩一局……', `MaleText_loc5`='你願意挑戰最厲害的那個嗎?$B$B還是你會跟其他人一樣就這麼輸了?$B$B只有一種方法才能知道答案。你敢的話就來試試看，$g先生:女士;?$B$B只需要一枚代幣...', `MaleText_loc7`='¿Quieres retar al mejor?$b$b¿Perderás como todos los demás?$b$bSolo hay una forma de averiguarlo. ¿Te atreves, $gseñor:señora;?$b$bSolo cuesta una ficha intentarlo...' WHERE `ID`=68901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이제 시작하자.', `MaleText_loc4`='那就开始吧。', `MaleText_loc5`='然後開始啦。', `MaleText_loc7`='Allá vamos.' WHERE `ID`=68902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 시간 동안 다크문 축제에서 즐겁게 보내시게나. 아니면 다시 한번 싸워보고 싶었던 건가...?', `MaleText_loc4`='祝你在马戏团玩得愉快。或者你还想再来一局……？', `MaleText_loc5`='請盡情享受在馬戲團裡的時間。還是你想要再來一次...?', `MaleText_loc7`='Disfruta del resto de tu estancia en la feria. ¿O acaso quieres otra ronda...?' WHERE `ID`=68903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해. 실력이 뛰어나군.', `MaleText_loc4`='干得好，干得好。', `MaleText_loc5`='非常好，非常好。', `MaleText_loc7`='Bien hecho, bien hecho.' WHERE `ID`=68904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 애완동물과 싸워보는 건...?', `MaleText_loc4`='我们不如试试别的……？', `MaleText_loc5`='要不要再試另外一個...?', `MaleText_loc7`='¿Probamos otra vez...?' WHERE `ID`=68905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든 이 애완동물들은 다크문 축제에서 가장 강력한 놈들이야.', `MaleText_loc4`='它们毕竟是马戏团的精英嘛。', `MaleText_loc5`='畢竟它們是馬戲團裡面最好的。', `MaleText_loc7`='Ya te dije que era el mejor de la feria.' WHERE `ID`=68906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이런! 이렇게 빨리 지다니.', `MaleText_loc4`='唉！真没意思。', `MaleText_loc5`='哎呀!太快了。', `MaleText_loc7`='¡Ay! Pobre...' WHERE `ID`=68907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신의 애완동물과 싸우겠습니다! |cFF0008E8(다크문 게임 동전)|r', `MaleText_loc4`='我想和你进行宠物对战！|cFF0008E8(暗月游戏代币)|r', `MaleText_loc5`='我向你挑戰一場寵物對戰!|cFF0008E8(暗月遊戲代幣)|r', `MaleText_loc7`='¡Te reto a un duelo de mascotas! |cFF0008E8(Ficha de la Feria de la Luna Negra)|r', `FemaleText_loc1`='당신의 애완동물과 싸울게요! |cFF0008E8(다크문 게임 동전)|r', `FemaleText_loc4`='我想和你进行宠物对战！|cFF0008E8(暗月游戏代币)|r', `FemaleText_loc5`='我向你挑戰一場寵物對戰!|cFF0008E8(暗月遊戲代幣)|r', `FemaleText_loc7`='¡Te reto a un duelo de mascotas! |cFF0008E8(Ficha de la Feria de la Luna Negra)|r' WHERE `ID`=68908;
