UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$c, 이 밀림은 생명력이 넘쳐난다네. 새들은 숲지붕에서 지저귀지. 야수들은 그 아래에 어두운 은신처에서 으르렁거린다네.$b$b그리고 우리 사냥꾼들은 이 생물들을 계속 감시하지. 이곳은 우리의 영역인데 당연히 그래야 하지 않겠나.', `MaleText_loc4`='这是一片生机盎然的丛林，$c。鸟儿在树冠间啁啾，野兽在树下的阴影中咆哮。$b$b而我们这些猎手，则要控制它们的数量。这是我们使命——我们的责任。', `MaleText_loc5`='這片叢林充滿了生氣，$c。鳥兒在天際歌唱，野獸在地面咆嘯。$b$b我們獵人的任務就是管制牠們的數量。這是我們的天職，也是我們的義務。', `MaleText_loc7`='Esta selva rebosa vida, $c. Los pájaros cantan desde los árboles. Las bestias rugen desde escondites oscuros.$b$bY nosotros, los cazadores, las mantenemos a raya. Es nuestro lugar... nuestra obligación.' WHERE `ID`=68920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 고대 피의 왕관 학과 싸우고 싶습니다.', `MaleText_loc4`='我们想与远古血冠鹤战斗。', `MaleText_loc5`='我們想要跟遠古血頂鶴對戰。', `MaleText_loc7`='Nos gustaría luchar contra la grulla Tiarasangre anciana.', `FemaleText_loc1`='우리는 고대 피의 왕관 학과 싸우고 싶어요.', `FemaleText_loc4`='我们想与远古血冠鹤战斗。', `FemaleText_loc5`='我們想要跟遠古血頂鶴對戰。', `FemaleText_loc7`='Nos gustaría luchar contra la grulla Tiarasangre anciana.' WHERE `ID`=68921;
