UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조언을 하나 해주자면, 호랑이에게 바싹 붙어 있어야 하네.', `MaleText_loc4`='我只有一个忠告：跟紧她。', `MaleText_loc5`='良心的建議:跟緊她。', `MaleText_loc7`='Te daré un consejo: no te alejes.' WHERE `ID`=68943;
