UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게가 가만히 서 있게 하지 말게. 게딱지는 오랜 세월 덕분에 단단하지만, 게관절은 약하다네.', `MaleText_loc4`='千万别让螃蟹静立不动。它的甲壳历久弥坚，但它的关节却很脆弱。', `MaleText_loc5`='別讓螃蟹站在那裡不動。雖然牠的殼早就因歲月而硬化，但是關節還是非常脆弱的。', `MaleText_loc7`='No dejes que el cangrejo se quede quieto. El caparazón se le ha endurecido con la edad, pero las articulaciones son débiles.' WHERE `ID`=68945;
