UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야수를 보면 혼자 싸울 생각이 싹 사라질 걸세. 동료를 모으게나. 자네가 준비됐다는 생각이 들면, 내가 야수 우리를 열겠네.', `MaleText_loc4`='你孤身一人是无法战胜这头野兽的，$n。去召集一些盟友来吧。等你确信自己做好准备后，我就打开兽笼。', `MaleText_loc5`='這不是你會想要單獨對戰的野獸，$n。召集盟友。等你準備好了以後我就會把牠的籠子打開。', `MaleText_loc7`='Contra esa bestia no se lucha solo, $n. Busca aliados. Abriré la jaula de la bestia cuando creas que estás $glisto:lista;.' WHERE `ID`=68949;
