UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 사냥하기 아주 좋은 곳이야. 새들은 숲지붕에서 지저귀지. 야수들은 그 아래에 어두운 은신처에서 으르렁거리고 말이야.$b$b그리고 우리 사냥꾼들은 이 생물들을 계속 감시하지.$b$b그건 사냥꾼의 의무거든. 사냥감이 많이 잡히기도 하고 말이야.', `MaleText_loc4`='在这里狩猎可带劲儿了。鸟儿在树冠间啁啾，野兽在树下的阴影中咆哮。$b$b而我们则要控制它们的数量。$b$b这是我们身为猎手使命——而且也是一项很棒的运动。', `MaleText_loc5`='這片叢林是狩獵的好地方。鳥兒在天際歌唱，野獸在地面咆嘯。$b$b我們則管制牠們的數量。這是我們獵人的天職，而且也是很好的運動。', `MaleText_loc7`='Aquí se caza bien. Los pájaros cantan desde los árboles. Las bestias rugen desde escondites oscuros.$b$bY nosotros las mantenemos a raya.$b$bEs nuestra obligación como cazadores... y además es un deporte estupendo.' WHERE `ID`=68963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보, 네 죽음의 광선이 광고했던 것과 달라!', `MaleText_loc4`='波尔，你的死亡射线可没广告上吹的那么好用！', `MaleText_loc5`='老波，你的死亡射線沒有宣傳上的那麼有效!', `MaleText_loc7`='¡Bo, tu rayo de la muerte no cumple con mis expectativas!' WHERE `ID`=68964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에 살아남으면 꼭 제대로된 파트너를 찾으라고 말해줘!', `MaleText_loc4`='如果我们能活下来，记得提醒我找个靠得住的搭档！', `MaleText_loc5`='如果我們存活下來，記得提醒我要找個稱職的夥伴!', `MaleText_loc7`='Si sobrevivimos a esto, ¡recuérdame que me busque un compañero competente!' WHERE `ID`=68965;
