UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게가 계속해서 움직이도록 몰아붙여. 게딱지는 오랜 세월 덕분에 단단하지만, 게관절은 약하거든.', `MaleText_loc4`='让那只螃蟹动起来，伙计。它的甲壳虽然久经风霜，可它的关节是很脆弱的。', `MaleText_loc5`='別讓螃蟹站在那裡不動。雖然牠的殼早就因歲月而硬化，但是關節還是非常脆弱的。', `MaleText_loc7`='Obliga a ese cangrejo a moverse, colega. El caparazón se le ha endurecido con la edad, pero las articulaciones son débiles.' WHERE `ID`=68976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼자 이 야수를 상대하고 싶진 않을 거야. 동료를 모아와. 네가 준비됐다는 생각이 들면, 내가 야수 우리를 열어주지.', `MaleText_loc4`='你可不能和这只野兽单打独斗，$n。去召集些朋友来。等你确信自己准备好之后，我就打开兽笼。', `MaleText_loc5`='你最好不要獨自對付這隻猛獸，$n。去召集一些盟友。等你覺得準備好了我就會幫你打開猛獸的牢籠。', `MaleText_loc7`='Contra esa bestia no se lucha solo, $n. Busca aliados. Abriré la jaula de la bestia cuando creas que estás $glisto:lista;.' WHERE `ID`=68977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는 내 신경이 너무 날카로워지는 때도 있다. 하지만 시간을 빨리 가게 할 수는 없으니...', `MaleText_loc4`='有时我是如此紧张，但我不能加速时间……', `MaleText_loc5`='我有時候會緊繃得恨不得時間能夠加速...', `MaleText_loc7`='TEMP' WHERE `ID`=68978;
