UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저들이 음식을 무료로 준다는 게 믿어지십니까? 여긴 정말 끝내주는 곳이군요!', `MaleText_loc4`='你相信吗？这儿的人居然免费发放食物！这地方真是太棒了！', `MaleText_loc5`='你敢相信這些人竟然送出免費的食物嗎?這個地方超棒的!', `MaleText_loc7`='¿Te puedes creer que esta gente ha servido comida gratis? ¡Este sitio es increíble!' WHERE `ID`=68987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일인가, $r?', `MaleText_loc4`='怎么了，$r？', `MaleText_loc5`='是的，$r?', `MaleText_loc7`='¿Sí, $r?' WHERE `ID`=68988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 부대는 준비를 마쳤네, $r.$b$b호드 적군을 효과적으로 막아낼 수 있는 전통적인 방어 수단이 있지.', `MaleText_loc4`='我的小队已经准备就绪，$r。$b$b我们已经开发出了一种可以有效打击你的部落敌人的武器。', `MaleText_loc5`='我的小隊準備好了，$r。$b$b我們有種祖傳的陷阱應該能夠有效地對付你的部落敵人。', `MaleText_loc7`='Mi escuadrón está listo, $r.$b$bContamos con una defensa tradicional que debería ser bastante efectiva contra tus enemigos de la Horda.' WHERE `ID`=68989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안 린 국왕님의 명에 따라, 방어선을 구축해야 합니다, 장로님.', `MaleText_loc4`='锦鱼人，瓦里安·乌瑞恩国王有令，我们必须准备好防御工事。', `MaleText_loc5`='瓦里安·烏瑞恩國王命令我們來幫你加強防守錦魚人的攻勢。', `MaleText_loc7`='Por orden del rey Varian Wrynn, jinyu, debemos preparar tus defensas.', `FemaleText_loc1`='바리안 린 국왕님의 명에 따라, 방어선을 구축해야 해요, 장로님.', `FemaleText_loc4`='锦鱼人，瓦里安·乌瑞恩国王有令，我们必须准备好防御工事。', `FemaleText_loc5`='瓦里安·烏瑞恩國王命令我們來幫你加強防守錦魚人的攻勢。', `FemaleText_loc7`='Por orden del rey Varian Wrynn, jinyu, debemos preparar tus defensas.' WHERE `ID`=68990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 이번엔 공중 지원이 좀 필요하겠는데요.', `MaleText_loc4`='好吧！看来我们得呼叫空中支援了。', `MaleText_loc5`='很好!我想我們需要呼叫空援火力來對付這個傢伙。', `MaleText_loc7`='¡Vale! Me parece que para esto nos va a hacer falta apoyo aéreo.' WHERE `ID`=68991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴전차? 노움의 기술력을 얕보면 안되지. 자이로콥터들을 투입시켜!', `MaleText_loc4`='歼灭者？没有侏儒技术搞不定的东西。呼叫直升机！', `MaleText_loc5`='石毀車?只要用一點地精科技就可以解決啦。派出旋翼機!', `MaleText_loc7`='¿Demoledores? No son nada que un poco de ingenio gnómico no pueda superar. ¡Envíen los girocópteros!' WHERE `ID`=68992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 이 파괴전차들은 로켓 공격에 약한 것 같군요. 자이로콥터들을 투입시켜!', `MaleText_loc4`='唔。这些歼灭者在火箭弹面前有着致命的弱点。呼叫直升机！', `MaleText_loc5`='嗯。看來這些石毀車的弱點是火箭。派出旋翼機!', `MaleText_loc7`='Mmm. Parece que los demoledores son vulnerables a los cohetes. ¡Envíen los girocópteros!' WHERE `ID`=68993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들은 위험하지만 늑대를 탄 오크들은 더 무섭단말이죠. 사냥개들을 내보내!', `MaleText_loc4`='兽人很危险，而上了坐骑的兽人更危险。放狗！', `MaleText_loc5`='獸人本就危險，騎乘坐騎的獸人更危險。放獵犬出來!', `MaleText_loc7`='Los orcos son peligrosos, pero los orcos montados lo son aún más. ¡Soltad a los perros!' WHERE `ID`=68994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대들이 붙잡혀있다고요? 이 불쌍한 동물들을 "방생"해줘야겠군요.', `MaleText_loc4`='被囚禁的狼？我们要“解救”这些可怜的动物。', `MaleText_loc5`='被捉住的狼群?我們應該要拯救那些可憐的動物。', `MaleText_loc7`='¿Lobos en cautividad? Deberíamos "rescatar" a esos pobres animales.' WHERE `ID`=68995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 아세요? 저는 언제나 로봇 강아지를 만들고 싶어했어요. 이 늑대들을 잘 조사해야겠군요.', `MaleText_loc4`='你瞧，我一直想造一条机械狗。我们应该好好研究下这些狼。', `MaleText_loc5`='你知道嗎，我一直都想創造一隻機械小狗。我們應該更近距離地觀察那些狼。', `MaleText_loc7`='¿Sabes qué? Siempre he querido hacer un mecano-perrito. Deberíamos estudiar esos lobos con más detenimiento.' WHERE `ID`=68996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 내 땅굴로봇 마크 5를 시험해볼 기회군요! 꼭 붙잡아요!', `MaleText_loc4`='啊！我正好可以趁机测试一下我的Mk V型掘地机器人！抓紧了！', `MaleText_loc5`='啊!這是我測試我遁地金剛Mk V的機會了!抓緊了!', `MaleText_loc7`='¡Ah! ¡Esta es mi oportunidad para poner a prueba mi Tunelatrón 5.0! ¡Agárrate!' WHERE `ID`=68997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신을 요새 안쪽으로 보내줘야겠군요. 잘 붙들어요!', `MaleText_loc4`='该把你送进要塞去了。抓紧了！', `MaleText_loc5`='該把你帶進堡壘了。抓緊了!', `MaleText_loc7`='Hora de meterte en la fortaleza. ¡Agárrate fuerte!' WHERE `ID`=68998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 기회에 향상된 제 "비행용 푸드득 날개"를 써봐야겠군요. 자, 갑니다!', `MaleText_loc4`='该测试一下我最新的“飞速掘地翼”升级版了！抓紧！', `MaleText_loc5`='是時候測試我的全新「翔空挖掘飛翼」裝備了!抓緊!', `MaleText_loc7`='¡Hora de poner a prueba mi mejora del "ala voladora excavadora"! ¡Agárrate!' WHERE `ID`=68999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 탈것에 올라라! 해야 할 일이 있다!', `MaleText_loc4`='全体上坐骑！我们有任务了！', `MaleText_loc5`='上坐騎!我們有工作要做!', `MaleText_loc7`='¡Montad! ¡Hay trabajo pendiente!' WHERE `ID`=69000;
