UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 원격 측정 장치가 안 먹히는군요.', `MaleText_loc4`='唔。遥测功能好像关闭了。', `MaleText_loc5`='嗯嗯。看來遙測系統有點誤差。', `MaleText_loc7`='Mmm. Creo que la telemetría no está bien ajustada.' WHERE `ID`=69002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억해둬야겠어요. 망원경 장착할 것.', `MaleText_loc4`='提醒自己：造一个示波器。', `MaleText_loc5`='給自己的提醒:要建造潛望鏡。', `MaleText_loc7`='Nota mental: montar un periscopio.' WHERE `ID`=69003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그거 벽이었어요? 그렇게 들렸는데.', `MaleText_loc4`='那是不是一堵墙？听上去像。', `MaleText_loc5`='那是座牆嗎?聽起來像是座牆。', `MaleText_loc7`='¿Eso ha sido una pared? Ha sonado como si fuera una pared.' WHERE `ID`=69004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거 제가 제대로 볼 수만 있어도 훨씬 쉬울 텐데 말이죠.', `MaleText_loc4`='如果我能看见就好了。', `MaleText_loc5`='要是我能看得見就簡單多了。', `MaleText_loc7`='Esto sería mucho más fácil si pudiera ver algo.' WHERE `ID`=69005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 졌네. 가치 있는 싸움이었어. 고맙네, 친구여.', `MaleText_loc4`='我投降。这是一场光荣的战斗，朋友。', `MaleText_loc5`='我投降。真是一場精采的戰鬥。謝謝你，朋友。', `MaleText_loc7`='Me rindo. Ha sido una batalla digna. Te lo agradezco.' WHERE `ID`=69007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 검은 항상 날카롭지. 불타는 군단의 위협은 지금도 계속되고 있으니.', `MaleText_loc4`='我的武器必须保持锋利——燃烧军团的威胁时刻存在。', `MaleText_loc5`='我必須時時保持刀刃鋒利，因為軍團的詛咒無所不在。', `MaleText_loc7`='Debo mantener las hojas afiladas. La amenaza de la Legión es constante.' WHERE `ID`=69008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 치어 친구들. 뭐 문제라도 있나? 비늘이라도 떨어졌어? 어서 움직여!', `MaleText_loc4`='怎么了，小鱼苗？你的鳞片折断了？继续前进！', `MaleText_loc5`='怎麼了，小魚們?累的鱗片都掉了嗎?繼續前進!', `MaleText_loc7`='¿Qué pasa, renacuajos? ¿Se os ha roto una escama? ¡En marcha!' WHERE `ID`=69009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 여기 일이 일찍 끝나면 함께 시원한 물에서 수영이라도 하지. 어때?', `MaleText_loc4`='你们这些小鱼快点干完，然后就能去畅游一番了。听起来不错吧？', `MaleText_loc5`='你們這些小魚提前完成的話就可以去游泳。聽起來怎樣?', `MaleText_loc7`='¡Renacuajos! Si termináis pronto, podéis ir a nadar. ¿Qué os parece?' WHERE `ID`=69010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프란이 죽자 %s|1이;가; 격분합니다.', `MaleText_loc4`='法兰的死激怒了%s。', `MaleText_loc5`='%s由於弗蘭死亡被激怒了。', `MaleText_loc7`='La muerte de Fran enfurece a %s.' WHERE `ID`=69011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 조심해. 너무 일찍 폭발하면 안 되니까...', `MaleText_loc4`='放松点。这些东西可不能扔得太早……', `MaleText_loc5`='小心點。我們可不希望時機沒到就引爆這些傢伙...', `MaleText_loc7`='Cuidado. No queremos que se activen antes de tiempo...' WHERE `ID`=69012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 초밥 만들 녀석들 같으니! 다들 망치를 휘둘러!', `MaleText_loc4`='把锤子挥起来，你们这些没骨头的家伙！', `MaleText_loc5`='用力揮舞你們的鎚子，小姐們!', `MaleText_loc7`='¡Usad esos martillos, blandengues!' WHERE `ID`=69013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서두르는 게 좋아! 전투가 시작될 때는 여기 남아 있으면 안 돼.', `MaleText_loc4`='最好能快点！我们可不想等战斗开始后还呆在这儿。', `MaleText_loc5`='最好加快速度!我們可不想在開打的時候還留在這裡。', `MaleText_loc7`='¡Daos prisa! No nos conviene seguir aquí cuando empiece el combate.' WHERE `ID`=69014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 차원문 조각에서 힘을 찾은 일은 제가 지하 하수도에서 빠져나와 인간답게 살 용기를 줬습니다.$B$B아, 그리고 시궁창에서 쫓겨나기도 한 거지만요.', `MaleText_loc4`='发现这些碎片中能量使我看到了走出困境，重获新生的希望。$B$B噢，而且我也被开除了。', `MaleText_loc5`='發現這些碎片的力量讓我有了脫離這個泥沼重新挑整我的人生的力量。$B$B喔，被開除也是原因之一啦。', `MaleText_loc7`='Descubrir el poder de estos fragmentos me dio la voluntad necesaria para salir de las cloacas y rehacer mi vida.$b$bBueno, y además me echaron.' WHERE `ID`=69015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넉 달 동안 마법 없이 살았더니 정말 기분이 끝내주는군요.$B$B이렇게 신선한 과일과 뜨끈한 차가 있으면 끝도 없는 마법의 신비는 필요 없지 않겠습니까?', `MaleText_loc4`='远离魔法的这四个月感觉好极了。$B$B有了这些新鲜水果和热气腾腾的茶，谁还在乎魔法的无穷奥秘呢？', `MaleText_loc5`='四個月沒用魔法，感覺好極了。$B$B有了新鮮水果與熱茶，誰還需要無盡的秘法奧妙呢?', `MaleText_loc7`='Llevo cuatro meses sin tocar la magia y me siento estupendamente.$b$b¿Quién necesita el infinito misterio de lo arcano cuando se tiene fruta fresca y té caliente?' WHERE `ID`=69016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 있는 판다렌들이 만드는 술은 맛이 꽤 훌륭하지만, 제가 가장 좋아하는 술은 모르더군요.$B$B언제 시간 내서 좀 가르쳐줘야겠습니다...', `MaleText_loc4`='这些熊猫人酿的烈酒棒极了，可他们都没听说过我最喜欢的那种饮料。$B$B或许我以后可以教教他们……', `MaleText_loc5`='這些熊貓人釀的酒不錯，不過他們都沒有見識過我最愛的酒。$B$B說不定哪天我會教他們怎麼釀...', `MaleText_loc7`='Estos pandaren preparan bebidas muy buenas, pero ninguno ha oído hablar de mi copa favorita.$b$bA lo mejor se la enseño algún día de estos...' WHERE `ID`=69017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*킁킁* 오호! 오래된 속옷에서 냄새가 좀 나기 시작하는군요.$B$B오늘밤 그 연못으로 몰래 가서 목욕할 수 있으려나...', `MaleText_loc4`='-嗅- 哇！这件旧长袍都有点发臭了。$B$B或许我今晚可以溜到那个池塘里洗个澡……', `MaleText_loc5`='-聞聞-嗚!這件舊袍子有點發臭了。$B$B或許我今天晚上溜到那座池塘洗個澡...', `MaleText_loc7`='<Olisqueo> ¡Uf! La toga empieza a oler.$b$bA lo mejor puedo darme un baño en el estanque esta noche...' WHERE `ID`=69018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 조각을 사용하면 어떤 차원문을 열 수 있습니까?', `MaleText_loc4`='我能用这些碎片打开什么样的传送门呢？', `MaleText_loc5`='這些碎片可以打開哪種傳送門?', `MaleText_loc7`='¿Qué tipo de portales puedo abrir con los fragmentos?', `FemaleText_loc1`='차원문 조각을 사용하면 어떤 차원문을 열 수 있나요?', `FemaleText_loc4`='我能用这些碎片打开什么样的传送门呢？', `FemaleText_loc5`='這些碎片可以打開哪種傳送門?', `FemaleText_loc7`='¿Qué tipo de portales puedo abrir con los fragmentos?' WHERE `ID`=69019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 시험중, 하나, 둘, 일곱. 거기 내 말 들려요, $p? 여기 있는 자동공성로봇에 정보를 전송하기 위해 정찰로봇들을 내보냈어요. 아마 이러면 내 자동공성로봇이 정상적이게, 그리고 사용자에게 피해가 가지 않을 수도 있게 작동할 거예요.', `MaleText_loc4`='开始测试，开始测试，1，2，7。你能听见吗，$p？我已经在这里布置了探查器以帮助自动攻城器收集数据。这将帮助我的自动攻城器完成一次充分且通常不致命的测试。', `MaleText_loc5`='測試，測試，1，2，7。$p你可以聽到我說話嗎?我已經投入偵查兔到戰場上去收集攻城旋翼用的資料。這些資料可以用來讓我的攻城旋翼做測試。', `MaleText_loc7`='Probando, probando, 1, 2, 7. ¿Me oyes, $p? He desplegado explorómetros por el campo para reunir datos para la Asediomática. Me ayudarán a realizar una prueba seria y generalmente no letal de mi Asediomática.' WHERE `ID`=69020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 폭탄이라. 저건 한 가지 약점이 있죠. 다른 폭탄들이요. 잠시만 기다려요.', `MaleText_loc4`='地精炸弹。它们有一个最大的弱点：其他炸弹。我稍后回来。', `MaleText_loc5`='哥布林炸彈有一個嚴重的弱點就是:其他的炸彈。我馬上回來。', `MaleText_loc7`='Bombas goblin. Tienen un gran punto débil: otras bombas. Ahora vuelvo.' WHERE `ID`=69021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린 폭탄이 또 있다고요? 어제만해도 저거 한 무더기 다 날려버린 것 같은데. 잠시만 있어봐요.', `MaleText_loc4`='又是地精炸弹？我昨天好像才搞定一堆地精炸弹。在这儿等我一会儿。', `MaleText_loc5`='更多哥布林炸彈?我昨天好像才解決一堆哥布林炸彈不是嗎。等我一下。', `MaleText_loc7`='¿Más bombas goblin? ¿No me deshice de otro montón de bombas goblin ayer mismo? Espera aquí un segundo.' WHERE `ID`=69022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린들은 폭탄을 정말 좋아하는군요. 어서 가서 노움식 폭탄이 어떤지 보여주죠. 바로 올게요.', `MaleText_loc4`='地精显然很爱炸弹。我们继续前进，让他们看看侏儒是怎么造炸弹的吧。我稍后回来。', `MaleText_loc5`='哥布林真的很喜歡他們的炸彈。我們讓他們瞧瞧地精炸彈的威力吧。我馬上回來。', `MaleText_loc7`='Está claro que a los goblins les encantan las bombas. Vamos a enseñarles cómo hacen bombas los gnomos. Vuelvo enseguida.' WHERE `ID`=69023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작고, 한 번만 사용할 수 있는 차원문이죠. 호드나 얼라이언스의 대도시로 갈 수 있습니다.$B$B차원문 조각을 지하 하수도에서 한꺼번에 씻어버려서 어떤 조각이 어떤 곳으로 가는 차원문을 열어줄지 저도 알 방법이 없군요. 알 수 있는 거라곤 그 조각들이 은빛 서약단이나 선리버 차원문에서 왔다는 것 정도입니다. 두 곳 다 차원문 마법에 작은 표시를 하는 것을 좋아하거든요. 일반적인 엘프들의 기질이죠.$B$B제가 당신 진영에 맞게 조각을 팔 테니 그게 안정화되면 어디로 가는 차원문이 열릴지 알게 될 겁니다.', `MaleText_loc4`='一座通往部落或联盟主城的一次性小型传送门。$B$B它们都是一起被冲下来的，所以我也不知道哪个碎片能够通向哪里。我最多只能分辨出它们是来自于夺日者的传送门，还是银色盟约的传送门。这两边都喜欢在自己的传送门魔法中加入一点自己的特色——典型的恶趣味。$B$B我可以卖给你相应阵营的碎片，而你得在它们稳定下来之后自己分辨它们通向哪里。', `MaleText_loc5`='通往部落或聯盟主要城市的小型一次性傳送門。$B$B這些裂片全都一起沖下水管了，所以我不知道哪片裂片會通往哪個城市。我只能分辨裂片是奪日者傳送門還是白銀誓盟傳送門。這兩個聯盟喜歡在他們的傳送法術上加點特別的變化－精靈喜歡幹這種事。$B$B我會賣你與你的陣營相符的傳送門裂片，你應該能夠在它們穩定之後找出它們到底是通往哪裡的。', `MaleText_loc7`='Portales pequeños y de un sentido a una ciudad capital de la Horda o la Alianza.$b$bLos fragmentos se fueron todos por el desagüe, así que no sé adónde lleva cada fragmento. Lo único que puedo hacer es distinguir si vinieron de portales de los Atracasol o de portales del Pacto de Plata. Les gusta añadir una pequeña firma a su magia de portales... típica elegancia elfa.$b$bTe venderé los fragmentos de tu facción, y tú descubrirás adónde van cuando los hayas estabilizado.' WHERE `ID`=69024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 생각 같군요.', `MaleText_loc4`='听起来不错。', `MaleText_loc5`='聽起來不錯。', `MaleText_loc7`='Me parece bien.', `FemaleText_loc1`='좋은 생각 같네요.', `FemaleText_loc4`='听起来不错。', `FemaleText_loc5`='聽起來不錯。', `FemaleText_loc7`='Me parece bien.' WHERE `ID`=69025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발사!', `MaleText_loc4`='开火！', `MaleText_loc5`='開火!', `MaleText_loc7`='¡Fuego!' WHERE `ID`=69027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문 조각을 사고 싶습니다.', `MaleText_loc4`='我想买一些传送门碎片。', `MaleText_loc5`='我要買傳送門裂片。', `MaleText_loc7`='Quiero comprar fragmentos de portal.', `FemaleText_loc1`='차원문 조각을 사고 싶어요.', `FemaleText_loc4`='我想买一些传送门碎片。', `FemaleText_loc5`='我要買傳送門裂片。', `FemaleText_loc7`='Quiero comprar fragmentos de portal.' WHERE `ID`=69028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 영웅이여. 제게 삶을 주셨군요.', `MaleText_loc4`='谢谢你，英雄。你给了第二次生命。', `MaleText_loc5`='謝謝你，英雄。你給了我繼續活下去的機會。', `MaleText_loc7`='Gracias. Me has concedido una segunda oportunidad para vivir.', `FemaleText_loc1`='감사합니다, 영웅이여. 제게 삶을 주셨군요.', `FemaleText_loc4`='谢谢你，英雄。你给了第二次生命。', `FemaleText_loc5`='謝謝你，英雄。你給了我繼續活下去的機會。', `FemaleText_loc7`='Gracias. Me has concedido una segunda oportunidad para vivir.' WHERE `ID`=69029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구의 힘은 정말 어마어마합니다.', `MaleText_loc4`='魔古族的力量真是令人震惊。', `MaleText_loc5`='魔古的力量太驚人了。', `MaleText_loc7`='La fuerza de los mogu es impresionante.', `FemaleText_loc1`='모구의 힘은 정말 어마어마합니다.', `FemaleText_loc4`='魔古族的力量真是令人震惊。', `FemaleText_loc5`='魔古的力量太驚人了。', `FemaleText_loc7`='La fuerza de los mogu es impresionante.' WHERE `ID`=69030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 도착했더라면 상황이 좀 나았을 텐데...', `MaleText_loc4`='如果援军早点赶来，我们或许还有胜利的希望。', `MaleText_loc5`='要是支援部隊早點來的話，我們應該還有機會的...', `MaleText_loc7`='Si hubieran llegado los refuerzos, igual habríamos tenido alguna posibilidad.', `FemaleText_loc1`='지원군이 도착했더라면 상황이 좀 나았을 텐데...', `FemaleText_loc4`='如果援军早点赶来，我们或许还有胜利的希望。', `FemaleText_loc5`='要是支援部隊早點來的話，我們應該還有機會的...', `FemaleText_loc7`='Si hubieran llegado los refuerzos, igual habríamos tenido alguna posibilidad.' WHERE `ID`=69031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구의 마법은 우리가 지금까지 본 그 어떤 것과도 다릅니다.', `MaleText_loc4`='魔古族的巫术和我们之前所见过的完全不同。', `MaleText_loc5`='魔古的魔法是我們不曾見識過的。', `MaleText_loc7`='La hechicería de los mogu no se parece a nada que haya visto antes.', `FemaleText_loc1`='모구의 마법은 우리가 지금까지 본 그 어떤 것과도 다릅니다.', `FemaleText_loc4`='魔古族的巫术和我们之前所见过的完全不同。', `FemaleText_loc5`='魔古的魔法是我們不曾見識過的。', `FemaleText_loc7`='La hechicería de los mogu no se parece a nada que haya visto antes.' WHERE `ID`=69032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 동료들을 고문하는 걸 봤습니다. 당신 덕분에 저는 목숨을 건졌군요. 정말 감사합니다.', `MaleText_loc4`='我亲眼看着魔古族如何折磨我的朋友。多亏了你，我才逃过一劫。', `MaleText_loc5`='我親眼見到魔古在折磨我朋友，謝謝你，還好我沒有遭到同樣的下場。', `MaleText_loc7`='Vi cómo los mogu torturaban a mis amigos. Gracias a ti, yo no correré la misma suerte.', `FemaleText_loc1`='모구가 동료들을 고문하는 걸 봤습니다. 당신 덕분에 저는 목숨을 건졌군요. 정말 감사합니다.', `FemaleText_loc4`='我亲眼看着魔古族如何折磨我的朋友。多亏了你，我才逃过一劫。', `FemaleText_loc5`='我親眼見到魔古在折磨我朋友，謝謝你，還好我沒有遭到同樣的下場。', `FemaleText_loc7`='Vi cómo los mogu torturaban a mis amigos. Gracias a ti, yo no correré la misma suerte.' WHERE `ID`=69033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 우리가 마치 개미라도 되는 양 짓밟았습니다. 어찌나 괴물 같은 힘인지!', `MaleText_loc4`='他们就像我们碾死蚂蚁一样横扫了我们。这些魔古族的力量简直恐怖！', `MaleText_loc5`='我們就像螻蟻一樣被碾碎擊潰了，這些魔古的力量實在太強大了!', `MaleText_loc7`='Nos aplastaron como a insectos. ¡Qué poder tan monstruoso el de los mogu!', `FemaleText_loc1`='놈들은 우리가 마치 개미라도 되는 양 짓밟았습니다. 어찌나 괴물 같은 힘인지!', `FemaleText_loc4`='他们就像我们碾死蚂蚁一样横扫了我们。这些魔古族的力量简直恐怖！', `FemaleText_loc5`='我們就像螻蟻一樣被碾碎擊潰了，這些魔古的力量實在太強大了!', `FemaleText_loc7`='Nos aplastaron como a insectos. ¡Qué poder tan monstruoso el de los mogu!' WHERE `ID`=69034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저는 수석땜장이 오버스파크에요. 현대 노움 기계공학의 선구자라 할 수 있죠.$b$b우리 개발자들은 당신이 칼에 찔리거나 베이거나 폭탄에 맞아 터져 죽거나 이 세계에서 추방 당해 존재 자체가 지워지지 않도록 온갖 천재적인 기계들을 만들고 있답니다.$b$b걱정 마세요. 이런 부작용들이 매번 발생하는 건 아니에요.', `MaleText_loc4`='欢迎欢迎！我是工匠大师欧沃斯巴克，当代侏儒工程学的总工程师。$b$b我们的装配工段正在努力组装各种神奇机械，保护你免遭刀戳、剑劈、爆炸或被放逐出物质领域之害。$b$b好吧，就算出故障，至少不是敌人干的。', `MaleText_loc5`='你好!我是技工大師歐沃斯巴克，現代地精工程學的首席設計師。$b$b我們的工廠正在努力製造各式各樣的機械經典，來保護你不受各種刺傷，砍殺，爆炸的威脅。同時也保護你不會被放逐出我們的位元之外。$b$b至少不被我們的敵人所放逐。', `MaleText_loc7`='¡Saludos! Soy el maestro manitas Sobrechispa, el arquitecto jefe de la ingeniería gnómica moderna.$b$bNuestra bahía de ensamblaje está produciendo todo tipo de maravillas de la mecánica para ayudarte a que no te apuñalen, rajen, exploten o eliminen de este plano de la existencia de otras formas.$b$bNo a manos del enemigo, al menos.' WHERE `ID`=69035;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 성채는 가로쉬아르보다 더 견고하군. 하지만 언젠가는 함락될걸세. 호드는 필연적으로 무너지게 되어있으니.', `FemaleText_loc4`='这座堡垒会比加尔鲁什尔前哨站更难攻破。但它们迟早会被攻破的。部落必将败落。', `FemaleText_loc5`='這座堡壘將會比卡爾洛夏還難拿下。不過這也是遲早的事情罷了。世上沒有打不敗的部落。', `FemaleText_loc7`='Esta fortaleza será más difícil de tomar que Garrosh''ar, pero tarde o temprano caerá. La Horda siempre cae.' WHERE `ID`=69036;
