UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴을 지키는 사우록이 몇 마리 있군. 우선 저놈들부터 처리하세.', `MaleText_loc4`='[PH] It seems dere be some Saurok guardin da cave.  Let''s take care of ''em.', `MaleText_loc5`='[PH]那些薩烏洛克在守護洞穴。我們來對付它們。', `MaleText_loc7`='TEMP' WHERE `ID`=69057;
