UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이 귀찮은 일을 시작할 준비가 됐나?', `MaleText_loc4`='准备好开始了吗？', `MaleText_loc5`='準備好開始了嗎?', `MaleText_loc7`='¿$gLih''to:Lih''ta; p''a empezar?' WHERE `ID`=69059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 가시지요.', `MaleText_loc4`='我准备好了。出发。', `MaleText_loc5`='我準備好了。出發吧。', `MaleText_loc7`='Estoy listo. Vamos.', `FemaleText_loc1`='준비됐어요. 가시죠.', `FemaleText_loc4`='我准备好了。出发。', `FemaleText_loc5`='我準備好了。出發吧。', `FemaleText_loc7`='Estoy lista. Vamos.' WHERE `ID`=69060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도착했군. 좋소. 나는 이만 가보겠소. 이제 이 고블린놈을 바다에 내던질 필요는 없겠군.', `MaleText_loc4`='很好，你来了。在把这个地精扔进海里前，我总算能离开这儿了。', `MaleText_loc5`='很好，你來了。現在我只要把這隻哥布林丟到海裡就可以離開這裡了。', `MaleText_loc7`='Me alegro de que hayas venido. Ya puedo irme antes de tirar a este goblin al mar.' WHERE `ID`=69061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 당신 탈출 장치입니다.', `MaleText_loc4`='这是你的逃生设备。', `MaleText_loc5`='這是你的逃脫裝置。', `MaleText_loc7`='Aquí tienes tu dispositivo de escape.', `FemaleText_loc1`='여기 당신 탈출 장치입니다.', `FemaleText_loc4`='这是你的逃生设备。', `FemaleText_loc5`='這是你的逃脫裝置。', `FemaleText_loc7`='Aquí tienes tu dispositivo de escape.' WHERE `ID`=69062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전투가 끝난 후 제 상처를 치료해 준 판다렌 운무사가 아니었다면, 전 비취 숲에서 죽었을 거예요.$b$b판다렌은 좋은 이들입니다. 얼라이언스의 압제에 시달리지 않도록 우리가 지켜 줘야 해요.', `FemaleText_loc4`='要不是一位熊猫人织雾者在战后为我疗伤，我早就死在翡翠林了。$b$b这些熊猫人都是好人，我们应该保护他们免遭联盟奴役。', `FemaleText_loc5`='要不是有一個熊貓人織霧者在戰鬥後幫我治傷，我可能就會死在翠玉林裡了。$b$b這些熊貓人很好，值得我們保護他們不受聯盟的統治。', `FemaleText_loc7`='Si no fuera por una tejedora de niebla pandaren que sanó mis heridas tras la batalla, yo habría muerto en el Bosque de Jade.$b$bLos pandaren son buena gente y se merecen que los protejamos de la opresión de la Alianza.' WHERE `ID`=69063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁터에 온걸 환영해, 꼬맹이.', `MaleText_loc4`='欢迎参战，孩子。', `MaleText_loc5`='歡迎來到戰場，孩子。', `MaleText_loc7`='$gBienvenido:Bienvenida; a la guerra, $gchaval:chica;.' WHERE `ID`=69064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요. 바로 고쳐드릴게요!', `FemaleText_loc4`='别担心，我马上就治好你！', `FemaleText_loc5`='別擔心，我會把你的傷處理好的!', `FemaleText_loc7`='No te preocupes, ¡te voy a curar enseguida!' WHERE `ID`=69071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 뼈 몇 개 부러지고 내장 출혈이 조금 있는 정도예요. 얼음찜질이면 충분하죠!', `FemaleText_loc4`='只是断了几根骨头外加内出血而已。没有冰袋治不好的伤！', `FemaleText_loc5`='只是斷了骨頭跟內出血而已，冰敷一下就好了!', `FemaleText_loc7`='Solo tienes unos huesos rotos y un par de hemorragias internas. ¡Nada que no se arregle con un poco de hielo!' WHERE `ID`=69072;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉿, 이 환자는 쉬어야 한다고요.', `FemaleText_loc4`='嘘，这个伤员需要休息。', `FemaleText_loc5`='噓，這個傷患需要休息。', `FemaleText_loc7`='Shhh, este paciente debe descansar.' WHERE `ID`=69073;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 사람은 상태가 꽤 나빠요.', `FemaleText_loc4`='这个伤员的情况很糟糕。', `FemaleText_loc5`='這傢伙傷得蠻重的。', `FemaleText_loc7`='Este tiene mal aspecto.' WHERE `ID`=69074;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 바람양모 붕대를 어디다 뒀더라?', `FemaleText_loc4`='我的风绒绷带哪儿去了？', `FemaleText_loc5`='我的風絨繃帶擺哪兒去了?', `FemaleText_loc7`='¿Dónde habré puesto las vendas de lanaviento?' WHERE `ID`=69075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 괴물 크기 좀 보십시오. 이놈 하나를 제압하려고 여섯 명이나 달려들어야 했습니다.', `MaleText_loc4`='你看到这畜生的体格了吗？我们要将近六个人才能制得住他。', `MaleText_loc5`='你有看到那東西的體型嗎?我們六個人齊上才制服了他。', `MaleText_loc7`='¿Has visto el tamaño de esa bestia? Hemos hecho falta seis para reducirla.' WHERE `ID`=69076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 짐승 같은 모구들은 엄청난 힘을 소유하고 있습니다.', `MaleText_loc4`='这些魔古族的野人力气大得惊人。', `MaleText_loc5`='這些魔古的力量大得驚人。', `MaleText_loc7`='Esos brutos mogu cuentan con una fuerza increíble.' WHERE `ID`=69077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 명령에 따라, 우리는 모구의 비밀을 낱낱이 밝혀낼 것입니다.', `MaleText_loc4`='按照酋长的指示，我们得揭开魔古族的所有秘密。', `MaleText_loc5`='奉大酋長命令，我們一定要揭開魔古的所有秘密。', `MaleText_loc7`='Por orden del Jefe de Guerra, revelaremos todos los secretos de los mogu.' WHERE `ID`=69078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 휘두르는 힘의 근원이 무엇인지, 가능한 모든 수단을 사용해서 밝혀내고 말겠습니다.', `MaleText_loc4`='我会运用手里的一些资源来找出魔古族的力量之源。', `MaleText_loc5`='我一定想盡辦法，揭開魔古的力量來源。', `MaleText_loc7`='Utilizaré todos los recursos de los que dispongo para revelar el origen del poder de los mogu.' WHERE `ID`=69079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 가로쉬의 요청에 따라 내 사람들을 여기 데려왔소. 하지만 우리가 장기판의 졸로 희생될 줄은 몰랐지.', `MaleText_loc4`='我按照加尔鲁什的要求，带着我的人来到这里。我完全没意识到，我们是被当做弃子利用了。', `MaleText_loc5`='我應卡爾洛斯的要求把我們族人帶來此地，只是我萬萬沒有想到，我們會像棋局裡小卒一樣被犧牲掉。', `MaleText_loc7`='Traje a mi gente porque Garrosh me lo ordenó. No sabía que pretendía sacrificarnos como peones en una partida de ajedrez.' WHERE `ID`=69080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='능력을 시험하는 것과, 아무것도 모른 채 위험 속으로 걸어들어가게 하는 것은 분명히 다르오. 가로쉬가 우리에게 한 짓은 후자요. 그리고 난 이런 일을 그냥 받아들일 수 없소.', `MaleText_loc4`='证明实力和盲目涉险完全是两码事。而加尔鲁什给我们的任务就属于后者，对此我无法接受。', `MaleText_loc5`='考驗力量與盲目闖入險境是不能相提並論的兩回事，而卡爾洛斯派我們去做的卻是後者，這點我絕對無法接受。', `MaleText_loc7`='Hay una diferencia entre poner a prueba la fuerza de uno y lanzarse ciegamente al peligro. Garrosh nos envió a hacer lo segundo, y eso no puedo aceptarlo.' WHERE `ID`=69081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 충성심은 이미 여러 번 시험받고 증명되지 않았소? 하지만 내가 우리 대족장의 입에서 듣는 거라곤 온통 거짓과 변명뿐이오.', `MaleText_loc4`='难道我们的忠诚还不算久经考验？我们的酋长口中，全是谎言和借口。', `MaleText_loc5`='我們對部落的忠誠不是已經受過一次又一次的考驗，而且一次又一次的證明了嗎?我從大酋長口裡聽到的，只有假話和藉口。', `MaleText_loc7`='¿Acaso no hemos demostrado nuestra lealtad una y otra vez? Lo único que oigo de labios del Jefe de Guerra son excusas y falsedades.' WHERE `ID`=69082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 항상 힘과 명예에 대해 떠들지만, 사실 우리 지도자는 오로지 두 개의 결과만을 보지. 싸우고 살아남는 것, 혹은 패배하고 잊히는 것 말이오.', `MaleText_loc4`='加尔鲁什总把荣耀和力量挂在嘴上，可实际上我们的领袖眼里只有胜王败寇那一套。', `MaleText_loc5`='卡爾洛斯開口閉口盡是榮耀與力量，但事實上，我們部落的領導人只看到兩種結果:奮戰活下來，或是戰敗而被遺忘。', `MaleText_loc7`='Garrosh habla del honor y la fuerza, pero en realidad nuestro líder solo ve dos resultados: o luchamos y sobrevivimos, o nos derrotan y nos olvidan.' WHERE `ID`=69083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 군대에 겁쟁이는 필요없다. 최근 블러드 엘프의 용기와 충성심에 의구심이 드는군.', `MaleText_loc4`='我的部队不需要懦夫。最近，我一直在质疑血精灵的勇气，和忠诚。', `MaleText_loc5`='我的部隊容不下懦夫。但是最近，我開始懷疑血精靈的勇氣和忠誠。', `MaleText_loc7`='No quiero tener cobardes en mi ejército. De un tiempo a esta parte tengo dudas sobre el coraje y la lealtad de los elfos de sangre.' WHERE `ID`=69084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 판다리아에서, 나는 호드가 가져 마땅한 땅을 본다. 우리는 그 땅을 차지할 것이다. 모구든 얼라이언스든, 우릴 방해하는 놈은 모조리 파묻어 버리고 말이다.', `MaleText_loc4`='潘达利亚，是属于部落的应许之地。我们必须得到它，要是谁想螳臂当车，无论是魔古族还是联盟，都将被我们踩在脚下。', `MaleText_loc5`='在潘達利亞這裡，我看到的是一個值得部落佔領的新大陸。要是有人膽敢阻止我們，不管是魔古還是聯盟，我們都會徹底擊垮他們。', `MaleText_loc7`='Aquí, en Pandaria, veo la tierra que la Horda se merece. Nos haremos con ella, y si alguien se opone, sean los mogu o la Alianza, los exterminaremos de la faz de Azeroth.' WHERE `ID`=69085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도는 너희 블러드 엘프가 충분히 처리할 수 있으리라 생각했다만?', `MaleText_loc4`='我本以为你的血精灵们能够自己搞定的，看来我想错了。', `MaleText_loc5`='我還以為血精靈都有本事顧好自己，難道我錯了嗎?', `MaleText_loc7`='¿Me equivoqué al pensar que tus elfos de sangre serían capaces de defenderse?' WHERE `ID`=69086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 약한 건 내 탓이 아니다, 섭정. 나의 호드에서는, 다른 구성원들과 어깨를 나란히 할 만큼 강한 자들만이 설 자리가 있다.', `MaleText_loc4`='你们的软弱可不是我的错，摄政王。在我的部落里，只有强者才能立足。', `MaleText_loc5`='攝政王，你們的軟弱不是我的過錯。我的部落只容得下最強壯的人。', `MaleText_loc7`='Tu debilidad no es culpa mía, regente. En mi Horda solo hay sitio para aquellos que son lo bastante fuertes para estar a nuestro lado.' WHERE `ID`=69087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 그리고 너희의 도움 덕에 우리는 이 땅의 비밀을 캐낼 것이다. 호드의 영광을 위해!', `MaleText_loc4`='没错，有了你们的帮助，我们将解开这片土地的秘密。为了部落的荣耀！', `MaleText_loc5`='沒錯，而且在你們的協助之下，我們必定可以挖開這塊大陸的秘密。為了部落的榮耀!', `MaleText_loc7`='Sí, y con tu ayuda, desvelaremos los secretos de esta tierra. ¡Por la gloria de la Horda!' WHERE `ID`=69088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미래를 위해 엘프의 피가 좀 흘러야만 한다면, 흘리는 수밖에.', `MaleText_loc4`='如果我必须为此付出一些精灵的鲜血，那也未尝不可。', `MaleText_loc5`='就算必須犧牲幾個精靈的鮮血，我也在所不惜。', `MaleText_loc7`='Si debo pagar con sangre elfa, que así sea.' WHERE `ID`=69089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 너무 소심하구나, 섭정. 우리의 피는 이 세상에 우리 자리를 만들기 위해 치르는 대가에 불과하다.', `MaleText_loc4`='你太胆小了，摄政王。要在这乱世中立足，我们就必须付出鲜血的代价。', `MaleText_loc5`='你太軟弱了，攝政王。鮮血是打下江山的必要代價。', `MaleText_loc7`='Eres demasiado temeroso, regente. La sangre es el precio que pagamos para reclamar nuestro lugar en la historia.' WHERE `ID`=69090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님, 모구에 대한 경고는 해주셨어야죠. 이 석상들은 살아 움직입니다!', `MaleText_loc4`='你完全没有提醒我们魔古族的存在，酋长。这些雕像突然变活了！', `MaleText_loc5`='你沒有事先警告我們魔古的事情，大酋長，那些雕像全都活了過來!', `MaleText_loc7`='No nos advertiste de los mogu, Jefe de Guerra. ¡Las estatuas cobraron vida!' WHERE `ID`=69091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 미리 경고를 받았다면요. 대족장님은 제 백성을 늑대에게 던져주신 겁니다.', `MaleText_loc4`='如果事先得到消息，我们就能有所准备。你这是送羊入虎口。', `MaleText_loc5`='本來是絕對可以的，只要有人先給我們個警訊。你簡直是故意把我的人趕入狼群。', `MaleText_loc7`='Habríamos podido, si nos hubieran avisado. Arrojaste a mi gente a los leones.' WHERE `ID`=69092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저의 충성심을 의심하지는 마십시오, 대족장님. 저희는 당신을 위해 싸우려고 대해를 건너왔습니다.', `MaleText_loc4`='不要质疑我的忠诚，酋长。我们可是远渡重洋来为你作战。', `MaleText_loc5`='不要質疑我們的忠誠，大酋長。我們可是遠渡汪洋來為你作戰。', `MaleText_loc7`='No pongas en duda mi lealtad, Jefe de Guerra. Hemos cruzado un océano para luchar en tu nombre.' WHERE `ID`=69093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하십시오, 가로쉬 님. 대족장님이 그리는 완벽한 미래를 만드느라 호드가 붕괴될지도 모릅니다.', `MaleText_loc4`='小心，加尔鲁什。你的“美好未来”恐怕会摧毁部落。', `MaleText_loc5`='當心點，卡爾洛斯。別為了創造你那個完美的未來而把部落給毀了。', `MaleText_loc7`='Ten cuidado, Garrosh. Podrías destruir la Horda en tu intento de crear un futuro perfecto.' WHERE `ID`=69094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 백성들이 더는 무의미하게 피를 흘리게 하지 않겠습니다. 원하신다면 대족장님의 부하들을 사지에 보내십시오. 제 사람들은 안 됩니다.', `MaleText_loc4`='我绝不会再坐视我的人民白白流血。如果你愿意的话，就让你的人去送死好了，但你别想拿我的人当炮灰。', `MaleText_loc5`='我不會再坐視族人的鮮血無謂地犧牲了。你可以視你的手下如糞土，大酋長，但你不能動我的人一根汗毛。', `MaleText_loc7`='No toleraré que se vierta la sangre de mi pueblo sin sentido. Sacrifica a tus hombres si lo deseas, Jefe de Guerra, pero no sacrificarás a los míos.' WHERE `ID`=69095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 모두 언덕 위로 올라가라. 우리는 다른 입구가 있는지 찾아보겠다.', `MaleText_loc4`='你们都上山，我们检查一下其他入口。', `MaleText_loc5`='你們先去山丘上，我們去找另一個入口。', `MaleText_loc7`='Ustedes suban por la colina. Nosotros buscaremos otra entrada.' WHERE `ID`=69096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 위대한 반역의 화신, 파괴광이다! 그래, 네 비밀 계획도 모두 알아냈다!', `MaleText_loc4`='我，就是伟大的篡夺者——位元毁灭者！如你所见，我已经发现了你们的秘密计划！', `MaleText_loc5`='我是壞滅位元，是個偉大的篡位者!告訴你，我已經找到了你們的機密藍圖了!', `MaleText_loc7`='¡Soy Destructobyte, el gran usurpador! Como puedes ver, ¡he encontrado sus esquemas secretos!' WHERE `ID`=69098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석기는! 비밀이 울둠의 사막 아래에 잘 숨겨져 있다고 믿었겠지...', `MaleText_loc4`='蠢货！你们却还以为它们深藏在奥丹姆的沙砾之下……', `MaleText_loc5`='一幫白癡，你還以為這個機密藍圖依舊安然無恙的被藏在奧丹姆的沙漠深處嗎?', `MaleText_loc7`='¡Estúpidos! Se creían que estaban enterrados bajo las arenas de Uldum...' WHERE `ID`=69099;
