UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호자의 빛을 사용하여 암흑소환사의 하수인을 막아내십시오!', `FemaleText_loc4`='使用守护之光阻止黑暗召唤师的爪牙！', `FemaleText_loc5`='使用守護者之光來抵擋黑暗召喚師的爪牙!', `FemaleText_loc7`='¡Utiliza la luz del guardián para detener a los esbirros del invocador oscuro!' WHERE `ID`=69121;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 암흑소환사의 하수인을 처치해야만 놈의 보호 마법을 약하게 만들 수 있다. 그 전까진 그에게 피해를 입힐 수 없다.', `FemaleText_loc4`='英雄，你必须击败黑暗召唤师的爪牙才能削弱他的防护魔法。在此之前，他是免疫伤害的。', `FemaleText_loc5`='英雄，你必須擊敗黑暗召喚師的爪牙來使他的防護魔法弱化。破除防護魔法之前他不會受到任何傷害。', `FemaleText_loc7`='Aquí deberás derrotar a los esbirros del invocador oscuro para debilitar su magia protectora. Hasta entonces, será invulnerable.' WHERE `ID`=69122;
