UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모은 휘장들을 쓰고 싶소? 내가 그걸 받아주지.$b$b뭘 원하시오?', `MaleText_loc4`='你手上有多余的委任状？我可以帮你出手。$b$b你想买点什么？', `MaleText_loc5`='你還有沒用完的委任徽章嗎?我也收他們的貨幣。$b$b你想買些什麼?', `MaleText_loc7`='¿Tienes comisiones de sobra y te gustaría gastártelas? Yo te las quito de las manos.$b$b¿Qué quieres comprar?' WHERE `ID`=69130;
