UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 지배령 거점에서 스파크로켓 전초기지로 통하는 차원문에 동력을 공급했습니다!', `MaleText_loc4`='%s为连通统御岗哨和火箭岗哨的传送门添加了燃料！', `MaleText_loc5`='%s建立了一個從制霸岬到閃亮火箭哨站的傳送門!', `MaleText_loc7`='%s ha activado un portal desde el Punto de Dominio hasta la Avanzada de Chispamisil.', `FemaleText_loc1`='%s|1이;가; 지배령 거점에서 스파크로켓 전초기지로 통하는 차원문에 동력을 공급했습니다!', `FemaleText_loc4`='%s为连通统御岗哨和火箭岗哨的传送门添加了燃料！', `FemaleText_loc5`='%s建立了一個從制霸岬到閃亮火箭哨站的傳送門!', `FemaleText_loc7`='%s ha activado un portal desde el Punto de Dominio hasta la Avanzada de Chispamisil.' WHERE `ID`=69138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 사실 몇 가지 있네...$b$b자네가 국왕의 명령을 전달했을 때, 우리는 마침 식사를 하려던 참이었거든. 영양분을 더 섭취하면 기운이 날 거라고 생각하네.$b$b아, 생각해 보니, 덫을 설치할 때 필요한 나무도 더 있으면 좋겠군. 괜찮으면 나무를 모아 주지 않겠나?$b$b그리고... 음... 아니, 신경 쓰지 말게.', `MaleText_loc4`='唔，我们或许可以想想办法……$b$b你把国王的指令送来时，我们正要开饭。我想，一些食物或许能让大家多些动力。$b$b还有，我想起来了，我们的尖刺还需要一些木头。你能帮我们去收集一些吗？$b$b然后……嗯……哦，还是算了吧。', `MaleText_loc5`='嗯，看來我真的有事可以讓你做...$b$b在你送達國王命令之前我們剛好想吃飯。我想吃點東西增加點額外的能量。$b$b而且，我剛剛想到，我們需要一些木材來製作尖刺。你可以幫我們收集一些嗎?$b$b還有就是...嗯嘛...算了先不管。', `MaleText_loc7`='Bueno, igual hay alguna cosa...$b$bEstábamos a punto de cenar cuando trajiste las órdenes del Rey. Creo que un poco de sustento nos daría energía extra.$b$bAdemás, ahora que lo pienso, nos vendría bien un poco más de madera para las estacas. ¿Podrías reunirla?$b$bY luego... bueno... bah, da igual.' WHERE `ID`=69139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 두 달의 제단으로 통하는 차원문에 동력을 공급했습니다!', `MaleText_loc4`='%s为通往双月殿的传送门添加了燃料！', `MaleText_loc5`='%s建立了一個前往雙月廟的傳送門!', `MaleText_loc7`='%s ha activado un portal al Santuario de las Dos Lunas.', `FemaleText_loc1`='%s|1이;가; 두 달의 제단으로 통하는 차원문에 동력을 공급했습니다!', `FemaleText_loc4`='%s为通往双月殿的传送门添加了燃料！', `FemaleText_loc5`='%s建立了一個前往雙月廟的傳送門!', `FemaleText_loc7`='%s ha activado un portal al Santuario de las Dos Lunas.' WHERE `ID`=69140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 오그리마로 통하는 차원문에 동력을 공급했습니다!', `MaleText_loc4`='%s为通往奥格瑞玛的传送门添加了燃料！', `MaleText_loc5`='%s建立了一個前往奧格瑪的傳送門!', `MaleText_loc7`='%s ha activado un portal a Orgrimmar.', `FemaleText_loc1`='%s|1이;가; 오그리마로 통하는 차원문에 동력을 공급했습니다!', `FemaleText_loc4`='%s为通往奥格瑞玛的传送门添加了燃料！', `FemaleText_loc5`='%s建立了一個前往奧格瑪的傳送門!', `FemaleText_loc7`='%s ha activado un portal a Orgrimmar.' WHERE `ID`=69141;
