UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술사의 계약서를 연장합니다.', `MaleText_loc4`='延长我们的萨满祭司合同。', `MaleText_loc5`='延長了薩滿的合約!', `MaleText_loc7`='Extend our shaman''s contract.', `FemaleText_loc1`='주술사의 계약서를 연장합니다.', `FemaleText_loc4`='延长我们的萨满祭司合同。', `FemaleText_loc5`='延長了薩滿的合約!', `FemaleText_loc7`='Extend our shaman''s contract.' WHERE `ID`=69153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 알았네. 굳이 원한다면 얘기해 주지.$b$b혹시 알고 있는지 모르지만, $r, 이 지역에 고대 모구 유물이 남아 있다는 전설이 있네. 화려하게 장식된 홀이지. 이 보물을 손에 쥐는 이는 자신이 지휘하는 이들의 사랑과 헌신을 받을 수 있다는 이야기가 전해지네. 아니... 공포와 존경이었던가? 잊어버렸군.$b$b어느 쪽이든 도움이 될 것만은 확실하네. 그렇지 않은가?', `MaleText_loc4`='呃，好吧，如果你坚持的话。$b$b你瞧，$r，传说这一地区埋藏着一件古代魔古神器——一根装饰精美的权杖。传说拥有这件宝物的人将得到部属的衷心爱戴。也可能是敬畏，具体的我忘了。$b$b总之呢，这也不会有什么坏处。你说呢？', `MaleText_loc5`='喔，好吧，如果你堅持的話。$b$b你看，$r，傳說中這個地方有一個遠古魔古神器，一把華麗豪奢的權杖。傳說這個寶藏能讓它的持有者受到手下的愛戴。我有點忘了是基於尊敬還是畏懼。$b$b不論如何，有了總是不壞。對吧?', `MaleText_loc7`='Muy bien, si insistes...$b$bVerás, $r, cuenta la leyenda que existe un antiguo artefacto mogu en esta región: un cetro con ricos adornos. Se dice que el que lo posea tendrá el amor y la devoción de aquellos que le sirven. Era eso o el miedo y el respeto, no me acuerdo de cuál.$b$bEn cualquier caso, no está mal, ¿eh?' WHERE `ID`=69154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 소중한 홀을 찾았습니다. 자, 여기 있습니다!', `MaleText_loc4`='我找到你的宝贝权杖了。快拿上它！', `MaleText_loc5`='我找你寶貴的權杖了。趕快，給你!', `MaleText_loc7`='Ya he encontrado tu dichoso cetro. Corre, ¡cógelo!', `FemaleText_loc1`='그 소중한 홀을 찾았어요. 자, 여기 있어요!', `FemaleText_loc4`='我找到你的宝贝权杖了。快拿上它！', `FemaleText_loc5`='我找你寶貴的權杖了。趕快，給你!', `FemaleText_loc7`='Ya he encontrado tu dichoso cetro. Corre, ¡cógelo!' WHERE `ID`=69155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 스파크로켓 전초기지로 통하는 쌍방향 차원문과, 오그리마와 두 달의 제단으로 통하는 단방향 차원문을 유지할 수 있습니다.$b$b어느 차원문에 동력을 공급하고 싶으십니까?', `MaleText_loc4`='我们可以供养一座通往火箭岗哨的双向传送门，以及通往奥格瑞玛和双月殿的单向传送门。$b$b你想要为哪座传送门添加燃料呢？', `MaleText_loc5`='我們能夠維持一個從這裡通往閃亮火箭哨站的雙向傳送門，以及通往奧格瑪與雙月廟的單向傳送門。$b$b你想要哪裡的傭兵?', `MaleText_loc7`='We can maintain a two-way portal to Sparkrocket Outpost, as well as one-way portals to the Orgrimmar and the Shrine of Two Moons.$b$bWhat kind of mercenary would you like to fuel?' WHERE `ID`=69156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스파크로켓 전초기지로 통하는 차원문을 고르겠습니다.', `MaleText_loc4`='通往火箭岗哨的传送门。', `MaleText_loc5`='通往閃亮火箭哨站的傳送門。', `MaleText_loc7`='The portal to Sparkrocket Outpost.', `FemaleText_loc1`='스파크로켓 전초기지로 통하는 차원문을 고르겠습니다.', `FemaleText_loc4`='通往火箭岗哨的传送门。', `FemaleText_loc5`='通往閃亮火箭哨站的傳送門。', `FemaleText_loc7`='The portal to Sparkrocket Outpost.' WHERE `ID`=69157;
