UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 코룬을 방해하느냐? 이 오만함에 대한 대가를 치러라!', `MaleText_loc4`='是谁竟敢打扰寇茹？你将为自己的傲慢付出代价！', `MaleText_loc5`='是誰如此大膽闖入考倫領地?為你們的僭越付出代價吧!', `MaleText_loc7`='¿Quién osa interrumpir a un Korune? ¡Pagarás por tu insolencia!' WHERE `ID`=69161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 물 위를 걸을 수 있으면 좋겠습니다.', `MaleText_loc4`='我想在水上行走。', `MaleText_loc5`='我想要在水上行走。', `MaleText_loc7`='Me encantaría caminar sobre el agua.', `FemaleText_loc1`='제가 물 위를 걸을 수 있으면 좋겠어요.', `FemaleText_loc4`='我想在水上行走。', `FemaleText_loc5`='我想要在水上行走。', `FemaleText_loc7`='Me encantaría caminar sobre el agua.' WHERE `ID`=69162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 석상의 주인공은 고대의 모구 황제인 것 같습니다.', `MaleText_loc4`='这似乎是某位古代魔古皇帝的雕像。', `MaleText_loc5`='看起來是遠古魔古帝王的雕像。', `MaleText_loc7`='La estatua parece ser la representación de un antiguo emperador mogu.' WHERE `ID`=69163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동굴에는 강력한 모구의 마법이 담겨 있었던 것 같습니다.', `MaleText_loc4`='这个洞穴中似乎有强大魔古法术的痕迹。', `MaleText_loc5`='看起來這座洞穴曾經藏有強大的魔古魔法。', `MaleText_loc7`='Parece que la cueva albergaba una poderosa magia mogu.' WHERE `ID`=69164;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네 꼴을 좀 보렴! 하하!', `FemaleText_loc4`='看看你！哈！', `FemaleText_loc5`='看看你!哈哈!', `FemaleText_loc7`='¡Mírate! ¡JA!' WHERE `ID`=69165;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 보기보다는 똘똘한 녀석이구나. 알았어.', `FemaleText_loc4`='啊……你比看上去要聪明多了，我明白了。', `FemaleText_loc5`='啊...我知道了，你比外表看起來還聰明。', `FemaleText_loc7`='Ah... Eres más inteligente de lo que pareces.' WHERE `ID`=69166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 이곳이군. 주변을 둘러보게. 그리고 눈에 띄는 게 있으면 내게 알려주고.', `MaleText_loc4`='[PH] This is da place, mon. Look around, tell me what chu find...', `MaleText_loc5`='[PH] This is da place, mon. Look around, tell me what chu find...', `MaleText_loc7`='TEMP' WHERE `ID`=69167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이건 흑마법이네... 이렇게 남용되다니... 이건 호드의 방식이 아냐. 어서 떠나세.', `MaleText_loc4`='[PH] Ohh... this be black magic, mon... this kind of abuse... tis not da way of the Horde. Let''s leave, quickly.', `MaleText_loc5`='[PH] Ohh... this be black magic, mon... this kind of abuse... tis not da way of the Horde. Let''s leave, quickly.', `MaleText_loc7`='TEMP' WHERE `ID`=69168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 서둘러... 여기서 도망치게. 대족장에게 이 볼진이... 죽었다고 전해주게.', `MaleText_loc4`='[PH] *weakly* Hurry, flee from here. Tell da Warchief that ol'' Vol''jin is... dead.', `MaleText_loc5`='[PH] *weakly* Hurry, flee from here. Tell da Warchief that ol'' Vol''jin is... dead.', `MaleText_loc7`='TEMP' WHERE `ID`=69169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법의 근원을 찾은 것 같군. 주변을 둘러봐라. 그리고 우리가 이곳에 온 목적을 찾을 수 있는지 조사해라.', `MaleText_loc4`='[PH] It looks like we''ve found the source!  Look around and see if you can find what we came here for.', `MaleText_loc5`='[PH] It looks like we''ve found the source!  Look around and see if you can find what we came here for.', `MaleText_loc7`='TEMP' WHERE `ID`=69170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님께서 네놈은 믿을 수 없다고 하셨다.', `MaleText_loc4`='[PH] Garrosh told us you couldn''t be trusted.', `MaleText_loc5`='[PH] Garrosh told us you couldn''t be trusted.', `MaleText_loc7`='TEMP' WHERE `ID`=69171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이지... 마라...', `MaleText_loc4`='别……动……', `MaleText_loc5`='別...動...', `MaleText_loc7`='No... te muevas...' WHERE `ID`=69172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위를 보지 마!', `MaleText_loc4`='别抬头！', `MaleText_loc5`='別往上看!', `MaleText_loc7`='¡No mires arriba!' WHERE `ID`=69173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부하들은 처치했지만, 나는 막지 못할 것이다, 이 쇠약한 트롤 녀석아!', `MaleText_loc4`='[PH] You may have slain my men, but you won''t stop me, old troll!', `MaleText_loc5`='[PH] You may have slain my men, but you won''t stop me, old troll!', `MaleText_loc7`='TEMP' WHERE `ID`=69174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 볼진의 목을 찌릅니다.', `MaleText_loc4`='%s刺向沃金的脖子。', `MaleText_loc5`='%s刺向沃金的脖子。', `MaleText_loc7`='%s apuñala a Vol''jin en el cuello.' WHERE `ID`=69175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 힘을 남용할 수 없네. 이따위 힘을 이용하는 건 내가 몸을 담은 호드가 아니야.', `MaleText_loc4`='[PH] We can''t abuse this power.  A Horde dat would use this isn''t da Horde I signed up for.', `MaleText_loc5`='[PH] We can''t abuse this power.  A Horde dat would use this isn''t da Horde I signed up for.', `MaleText_loc7`='TEMP' WHERE `ID`=69176;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오! 브란, 이 발톱 좀 봐! 이 모구들이 암흑의 마법에 손을 대고 있다는 끔찍한 생각이 드는데.', `FemaleText_loc4`='噢！布莱恩，看看这个爪子！我有种不好的感觉：魔古族似乎在研究某种黑暗魔法。', `FemaleText_loc5`='喔!布萊恩，看看這隻爪子!我有一個不好的預感，這些魔古在研究黑暗魔法。', `FemaleText_loc7`='¡Ah! Brann, ¡mira esta garra! Sospecho que esos mogu están manejando magia oscura...' WHERE `ID`=69177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이 책에 따르면 코룬 모구는 바로 샤의 힘을 이용하려는 시도를 하고 있군요. 이 지도에 놈들의 위치가 나옵니다! 잘하셨습니다, $n. 오늘 충분히 우리를 도와줬습니다.', `MaleText_loc4`='嗯……根据这份抄本所说，寇茹魔古试图掌握煞魔的力量。这张地图就标出了他们的位置！干得好，$n。你今天可帮了我们大忙了。', `MaleText_loc5`='嗯嗯...根據這個聖典，考倫魔古試著要擷取煞的能量。這張地圖上有他們的位置! 幹得好，$n。你今天幫了我們一個大忙。', `MaleText_loc7`='Mmm... Según este códice, los mogu Korune intentan controlar el poder de los sha. ¡Este mapa señala su ubicación! Bien hecho, $n. Nos has ayudado bastante por hoy.' WHERE `ID`=69178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러게 말이야, 힐다. 모구가 샤 에너지를 이용한다? 영 마음에 안 드는 생각이군! 이 증거를 폐하께 가져가야겠어. $n 님, 오늘 도와주셔서 감사해요. 여기서부턴 저희가 맡죠!', `MaleText_loc4`='我明白你的意思，希尔达。魔古族和煞魔搅和到了一块儿？我一点儿也不喜欢这消息！我们最好将我们的发现上报给国王陛下。$n，非常感谢你今天的帮助，接下来的事就交给我们吧！', `MaleText_loc5`='我聽到了，希爾達。魔古跟煞搞在一起?我可不喜歡這樣!我們最好趕快把證據帶回去給國王。$n，謝謝你今天的幫助，我們從這裡開始接手!', `MaleText_loc7`='Yo también, Hilda. ¿Los mogu, mezclándose con los sha? ¡No me gusta ni un pelo! Será mejor que informemos al Rey de lo que hemos descubierto. Gracias por tu ayuda, $n, pero a partir de ahora nos encargamos nosotros.' WHERE `ID`=69179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아. 기회의 땅. 한 몫 챙기거나 빈털터리가 되거나.', `MaleText_loc4`='潘达利亚。机遇之地。不能一夜暴富，就得倾家荡产。', `MaleText_loc5`='潘達利亞。機會之地。不是大富就是大敗。', `MaleText_loc7`='Pandaria: la tierra de las oportunidades. Hora de hacerse rico o arruinarse.' WHERE `ID`=69180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 이게 누구신가. $p. 역시 직접 그곳에 안 가길 잘했어. 괜히 자네가 날 걸고 넘어질지 모르니 말이지.', `MaleText_loc4`='很好，很好。$p。我想我还是不要亲自前来了，免得你的野心又蠢蠢欲动。', `MaleText_loc5`='這個嘛，$p。我想我還是不要在這裡現出真身。我可不想讓你打什麼不好的主意。', `MaleText_loc7`='Vaya, vaya, vaya. $p. Sabía que era buena idea no venir en persona. No quería darle ideas a tu ambición.' WHERE `ID`=69181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희는 발굴 및 조사 작업 차 여기 왔습니다. 문제 생길 일은 전혀 없어요. 제가 약속하죠!', `MaleText_loc4`='我们是来搞科研和发掘工作的，不是来惹麻烦的，我保证！', `MaleText_loc5`='我們是來這裡進行研究與挖掘的。我保證不會惹麻煩的!', `MaleText_loc7`='Hemos venido en una misión de investigación y excavación. ¡Nada de meterse en líos! ¡Lo prometo!' WHERE `ID`=69183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 성물회 블러드 엘프들이 여기서 우리보다 잘 나가고 있다는 게 믿어지십니까? 녀석들이 우리 유물을 파내게 놔둘 수는 없어요!', `MaleText_loc4`='你相信吗？那些神圣遗物学会的血精灵居然在这儿击败了我们？我们不能让他们继续挖掘属于我们的遗物！', `MaleText_loc5`='你能相信那些聖匣守護者血精靈會在這裡搶先我們嗎?我們不能讓他們繼續挖掘我們的文物!', `MaleText_loc7`='¿Te puedes creer que los elfos de sangre del Relicario han llegado antes que nosotros? ¡No podemos permitir que se lleven nuestros artefactos!' WHERE `ID`=69184;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구 문명은 수천 년도 더 되었어요. 어쩌면 그들에게서 뭔가 배울 수 있을지도 모르죠!', `FemaleText_loc4`='魔古族的文明十分古老，可以追溯到上千年前。或许我们能从他们那里学到点什么！', `FemaleText_loc5`='魔古是個延續千年的古代文明。或許我們可以從他們身上學到什麼東西!', `FemaleText_loc7`='Los mogu son una civilización antigua que existe desde hace miles de años. ¡A lo mejor podemos aprender algo de ellos!' WHERE `ID`=69185;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 브란의 친구분이신가요? 고고학 학교에서 공부하던 시절에 브란이 종종 제 필기를 베꼈던 거 모르시죠?!', `FemaleText_loc4`='噢，你是布莱恩的朋友吗？我敢打赌，你肯定不知道，在考古学院的时候，他还老抄我的笔记呢！', `FemaleText_loc5`='喔，你是布萊恩的朋友嗎?我打賭你不知道他以前在上考古學的時候都抄我的筆記!', `FemaleText_loc7`='Ah, ¿eres $gamigo:amiga; de Brann? ¿A que no sabías que en la escuela de arqueología me copiaba los apuntes?' WHERE `ID`=69186;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탐험가 연맹의 수많은 구성원이 도서관에 머물며, 연맹에서 발견한 물건들을 조사하고, 목록을 만든답니다.$B$B저도 지난 5년간 그 일을 했죠. 그동안 브란은 흥미로운 여러 발굴지를 분주히 돌아다녔고요.$B$B이제 이 힐다가 현장으로 돌아왔습니다. 뭔가 엄청난 걸 찾아낼 거라고요!', `FemaleText_loc4`='探险者联盟的许多成员都得窝在图书馆里整理和分析我们的发现。$B$B我就曾这样度过了整整5年，而布莱恩却能周游世界，探索各种神奇的古迹。$B$B现在，希尔达终于重返野外了，我一定能搞出些大发现！', `FemaleText_loc5`='探險者協會裡的很多人都待在圖書館裡，為我們的發現做分類與分析。$B$B我在過去的五年間，在此同時布萊恩在外面的世界，一個接一個地探索著無數有趣的考古地點。$B$B嗯至少現在希爾達終於回到考古探勘的行列了，我終於可以找到什麼大發現了!', `FemaleText_loc7`='En la Liga de Expedicionarios somos muchos los que nos quedamos en la biblioteca, catalogando y analizando todos los descubrimientos.$b$bA eso he dedicado los últimos cinco años mientras Brann daba la vuelta al mundo, yendo de una excavación interesante a otra.$b$bPues bien, Hilda ha vuelto al trabajo de campo, ¡y ya va siendo hora de que encuentre algo GRANDE!' WHERE `ID`=69187;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사자의 상륙지에서 온 소식이 있나요, $c님?', `FemaleText_loc4`='雄狮港有什么消息吗，$c？', `FemaleText_loc5`='雄獅灘有來任何消息嗎，$c?', `FemaleText_loc7`='¿Algún informe del Desembarco del León, $c?' WHERE `ID`=69188;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번 임무는 편할 줄 알았는데, 블러드 엘프 때문에 모두 군기가 바짝 들었어요.', `FemaleText_loc4`='我原本并不觉得这次的任务有什么了不起的，可血精灵的出现令我们警惕性大增。', `FemaleText_loc5`='我之前認為這個任務不會發生什麼大事，不過血精靈的出現讓我們全體都進入了警戒狀態。', `FemaleText_loc7`='No creía que la misión fuera gran cosa, pero la presencia de los elfos de sangre nos tiene a todos en alerta.' WHERE `ID`=69189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 고대 유물에 매력을 느껴본 적이 없습니다. 어쨌든 이번 임무는 생각했던 것보다 위험하군요.', `FemaleText_loc4`='我向来不痴迷古代神器，可这次的任务确实比我想象中更加危险。', `FemaleText_loc5`='我一直都對遠古神器沒什麼興趣，不過這個任務比我原本想的還刺激許多。', `FemaleText_loc7`='Los artefactos antiguos nunca me han fascinado, pero esta misión ha demostrado ser más peligrosa de lo que pensaba.' WHERE `ID`=69190;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구라는 것들에 대해 불길한 기분이 드는군요.$B$B호드가 모구 유물을 발굴할 이유는 하나뿐입니다. 그냥 지식을 넓히려고 하는 짓은 물론 아니겠지요.$B$B모구의 힘을 휘두를 수 있는 실마리를 찾고 있는 겁니다.', `FemaleText_loc4`='魔古族的出现令我感觉非常不好。$B$B他们挖掘魔古神器的原因只有一个，而且那绝不是为了追求知识。$B$B他们在追寻魔古族的力量之谜。', `FemaleText_loc5`='魔古在這裡出現讓我有不好的感覺。$B$B他們在這裡挖掘魔古神器不可能是為了學術研究。$B$B他們一定是在找魔古力量的線索。', `FemaleText_loc7`='La presencia de los elfos de sangre me da mala espina.$b$bSolo puede haber una razón por la que excavan estos artefactos, y no es el conocimiento.$b$bBuscan pistas sobre el poder de los mogu.' WHERE `ID`=69191;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='병영에서 이 "샤"라는 것들에 대한 소문을 들었습니다.$B$B당신도 그 어처구니 없는 이야길 들으셨겠죠? 샤가 우리의 가장 강력한 병사들에게 빙의한다는 이야기요. 어린애들 겁주기에 딱 좋은 이야기죠.$B$B샤 따위는 저나 제 자매들이 충분히 처리할 수 있습니다.', `FemaleText_loc4`='在兵营的时候，我听到过有关这种“煞魔”的传言。$B$B你真该听听那些疯狂的故事——煞魔控制了我们的王牌部队？那不过是吓唬小孩子的鬼话而已。$B$B煞魔没什么了不起的，我和我的姐妹们完全能对付它们。', `FemaleText_loc5`='我在軍營聽見關於這個「煞」的事情。$B$B你應該聽聽外面流傳的瘋狂故事，說煞已經附身我們最強的部隊了?根本是嚇小孩的故事。$B$B煞對我跟我的姊妹來說是小菜一碟。', `FemaleText_loc7`='En el barracón, oí hablar de los "sha".$b$bNo sabes qué locuras... ¿sha que poseen a nuestros soldados más fuertes? No son más que cuentos para asustar a los niños.$b$bLos sha no son nada que mis hermanas y yo no podamos manejar.' WHERE `ID`=69192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직까진 잠잠하군요. 우리는 블러드 엘프의 주의를 끌지 않으려고 노력하고 있습니다.', `MaleText_loc4`='目前为止，一切平静。我们一直躲着那些血精灵。', `MaleText_loc5`='目前沒什麼動靜。我們埋伏在那些血精靈附近。', `MaleText_loc7`='De momento todo está tranquilo. No queremos que los elfos de sangre nos descubran.' WHERE `ID`=69193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아까 폐허를 정찰했습니다. 블러드 엘프는 아주 작정하고 엄청난 수를 여기 보냈더군요.', `MaleText_loc4`='我侦察了这片废墟。这里的血精灵已经是倾巢而出了。', `MaleText_loc5`='我去偵查了那遺跡。很多全副武裝的血精靈部隊。', `MaleText_loc7`='He explorado las ruinas. Los elfos de sangre están por todas partes.' WHERE `ID`=69194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 기억도 나지 않을 만큼 오랫동안 사란나의 옆을 지켰습니다. 그녀는 전장에서 맹렬한 전사죠. 그리고 저는 그녀의 뒤를 지키고요.', `MaleText_loc4`='我和萨拉哈并肩作战多年。她在战斗中总是勇往直前，而我则总是掩护她。', `MaleText_loc5`='我有生以來一直跟在莎蕾娜身邊作戰。她在戰鬥中所向披彌，我負責顧好她的後方。', `MaleText_loc7`='Llevo luchando junto a Sarannha desde hace mucho tiempo. Es una fiera en la batalla. Yo le cubro las espaldas.' WHERE `ID`=69195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이죠?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=69196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 다들 이 동굴을 빠져나가는 데 도움이 좀 필요한 것 같네. 마침 내가 이 배에 몇 가지 장비를 추가하던 중이었어...', `MaleText_loc4`='[PH] It looks like you all could use some help getting through this cave.  I''ve been working on some modifications to my boat here...', `MaleText_loc5`='[PH] It looks like you all could use some help getting through this cave.  I''ve been working on some modifications to my boat here...', `MaleText_loc7`='TEMP' WHERE `ID`=69197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 좀 도와줘! 프로펠러에 뭔가 감긴 것 같아!', `MaleText_loc4`='快来帮帮我！螺旋桨里卷到东西了！', `MaleText_loc5`='幫個忙啊!有東西捲進螺旋槳了!', `MaleText_loc7`='¡Que alguien me eche una mano! ¡Se ha enredado algo en la hélice!' WHERE `ID`=69198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅에서 네놈을 정화하겠다.', `MaleText_loc4`='你们必须滚出这片土地。', `MaleText_loc5`='我要將你逐出這片土地。', `MaleText_loc7`='Os borraremos del mapa.', `FemaleText_loc1`='이 땅에서 네놈을 정화하겠다.', `FemaleText_loc4`='你们必须滚出这片土地。', `FemaleText_loc5`='我要將你逐出這片土地。', `FemaleText_loc7`='Os borraremos del mapa.' WHERE `ID`=69199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 얼라이언스는 이곳에서 없어져야 한다.', `MaleText_loc4`='这里不欢迎联盟。', `MaleText_loc5`='我們不歡迎聯盟。', `MaleText_loc7`='Tu Alianza no es bienvenida aquí.', `FemaleText_loc1`='너희 얼라이언스는 이곳에서 없어져야 한다.', `FemaleText_loc4`='这里不欢迎联盟。', `FemaleText_loc5`='我們不歡迎聯盟。', `FemaleText_loc7`='Tu Alianza no es bienvenida aquí.' WHERE `ID`=69200;
