UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 박살내주마!', `MaleText_loc4`='我要碾碎你！', `MaleText_loc5`='你將被摧毀!', `MaleText_loc7`='¡Te aplastaré!', `FemaleText_loc1`='널 박살내주마!', `FemaleText_loc4`='我要碾碎你！', `FemaleText_loc5`='你將被摧毀!', `FemaleText_loc7`='¡Te aplastaré!' WHERE `ID`=69202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아는 우리 것이다!', `MaleText_loc4`='潘达利亚属于部落！', `MaleText_loc5`='潘達利亞是我們的!', `MaleText_loc7`='¡Pandaria es nuestra!', `FemaleText_loc1`='판다리아는 우리 것이다!', `FemaleText_loc4`='潘达利亚属于部落！', `FemaleText_loc5`='潘達利亞是我們的!', `FemaleText_loc7`='¡Pandaria es nuestra!' WHERE `ID`=69203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내... 배에서... 당장... 사라져!', `FemaleText_loc4`='滚……下……我的……船！', `FemaleText_loc5`='滾下...我的...船!', `FemaleText_loc7`='¡Fuera... de... mi... BARCO!' WHERE `ID`=69204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감히 호드가 내 함선에 있다니!', `FemaleText_loc4`='我的船上没有部落的位置！', `FemaleText_loc5`='部落不准上我的船!', `FemaleText_loc7`='¡La Horda NO pisará mi barco!' WHERE `ID`=69205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무법자호는 나의 것이다! 도망치거나 죽어라!', `FemaleText_loc4`='挑战号是我的！不滚就死！', `FemaleText_loc5`='不屈號是我的!退下，不然就受死吧!', `FemaleText_loc7`='¡El Desafiante es mío! ¡Apártate o muere!' WHERE `ID`=69206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 동굴은 위험해 보이는군. 셋 모두 흩어져야겠네. 한 명은 여기 함포를 맡고, 나머지 둘은 각각 동굴 양쪽으로 나뉘게.', `MaleText_loc4`='[PH] Dis cave be lookin dangerous. You three split up, one of you man dis cannon here and de rest of you split up in de caves.', `MaleText_loc5`='[PH] Dis cave be lookin dangerous. You three split up, one of you man dis cannon here and de rest of you split up in de caves.', `MaleText_loc7`='TEMP' WHERE `ID`=69207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어! 직접 대면했군!', `MaleText_loc4`='总算来了！一场势均力敌的战斗！', `MaleText_loc5`='終於!有場像樣的戰鬥!', `MaleText_loc7`='¡Por fin! ¡Un combate cuerpo a cuerpo!' WHERE `ID`=69208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음을 맞이하라!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='面對你的死亡吧!', `MaleText_loc7`='¡Enfrentaos a la muerte!' WHERE `ID`=69209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 따위가 흉포함을 아느냐?!', `MaleText_loc4`='你自以为很勇敢？！', `MaleText_loc5`='你以為只有你懂得野蠻?', `MaleText_loc7`='¿Creéis que sabéis lo que es el salvajismo?' WHERE `ID`=69210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 쓰레기! 죽어라!', `MaleText_loc4`='死吧，联盟的人渣！', `MaleText_loc5`='死吧，聯盟廢物!', `MaleText_loc7`='¡Muere, escoria de la Alianza!', `FemaleText_loc1`='얼라이언스 쓰레기! 죽어라!', `FemaleText_loc4`='死吧，联盟的人渣！', `FemaleText_loc5`='死吧，聯盟廢物!', `FemaleText_loc7`='¡Muere, escoria de la Alianza!' WHERE `ID`=69211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조사를 방해하고도 무사할 것 같으냐!', `MaleText_loc4`='你休想妨碍我们的研究！', `MaleText_loc5`='不准插手干預我們的研究!', `MaleText_loc7`='¡No te entrometerás en nuestra investigación!', `FemaleText_loc1`='우리 조사를 방해하고도 무사할 것 같으냐!', `FemaleText_loc4`='你休想妨碍我们的研究！', `FemaleText_loc5`='不准插手干預我們的研究!', `FemaleText_loc7`='¡No te entrometerás en nuestra investigación!' WHERE `ID`=69212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순식간에 저세상으로 보내주지, $r!', `MaleText_loc4`='我随手就能干掉你，$r！', `MaleText_loc5`='我會給你個痛快，$r!', `MaleText_loc7`='¡Te mataré en cuestión de segundos, $r!', `FemaleText_loc1`='순식간에 저세상으로 보내주지, $r!', `FemaleText_loc4`='我随手就能干掉你，$r！', `FemaleText_loc5`='我會給你個痛快，$r!', `FemaleText_loc7`='¡Te mataré en cuestión de segundos, $r!' WHERE `ID`=69213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것들을 사용해서 상처를 치유하게!', `MaleText_loc4`='[PH] Use dese to heal yourself, mon!', `MaleText_loc5`='[PH] Use dese to heal yourself, mon!', `MaleText_loc7`='TEMP' WHERE `ID`=69214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 사용해서 상처를 치유하게!', `MaleText_loc4`='[PH] Use dis to heal yourself, mon!', `MaleText_loc5`='[PH] Use dis to heal yourself, mon!', `MaleText_loc7`='TEMP' WHERE `ID`=69215;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나쁘지 않군요, $c님. 당장 오늘은 우리 할일이 끝났습니다만, 너무 느슨해지진 마세요. 사자의 상륙지에서 얼마 안 있어 당신에게 다음 임무를 줄 법도 하니까요.', `FemaleText_loc4`='不错嘛，$c。我们今天的工作暂时完成了，但你要保持警惕。过几天，给你的下一道指令说不定就是从雄狮港发出的了，这是完全有可能的。', `FemaleText_loc5`='不錯，$c。今天的工作完成了，可是別因此鬆懈下來。幾天後雄獅灘應該就會有下一道指令。', `FemaleText_loc7`='No está mal, $c. Hemos terminado por hoy, pero no te descuides. No me sorprendería que recibiéramos nuevas órdenes del Desembarco del León en unos días.' WHERE `ID`=69217;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨습니다, $c님. 이 블러드 엘프들이 본격적으로 모구를 조사하고 있군요. 가로쉬가 뭔가 힘이 담긴 유물을 찾고 있는 게 분명합니다. 놈이 원하는 걸 손에 넣게 둘 수는 없죠.', `FemaleText_loc4`='还不错，$c。血精灵在积极地研究魔古族。很明显，加尔鲁什在搜寻强大的神器，但我们不会让他们得逞。', `FemaleText_loc5`='幹得好，$c。這些血精靈正積極地調查魔古。顯然卡爾洛斯正在尋找有力量的神器，我們不會讓他得逞。', `FemaleText_loc7`='Buen trabajo, $c. Los elfos de sangre están investigando a los mogu. Está claro que Garrosh busca artefactos de poder, pero no se lo permitiremos.' WHERE `ID`=69218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 이 책에 따르면 코룬 모구는 바로 샤의 힘을 이용하려는 시도를 하고 있군요. 그리고 이제 우리는 그 작업이 정확히 어디서 진행되고 있는지 알게 되었습니다. 잘하셨습니다, $n.', `MaleText_loc4`='嗯……根据这份抄本所说，寇茹魔古试图掌握煞魔的力量。而且，我们还知道了他们确切的活动地点。干得好，$n。', `MaleText_loc5`='嗯... 根據這典籍的記載，考倫魔古是在嘗試駕馭煞的力量。現在我們曉得他們是在哪裡進行的了。做得好，$n。', `MaleText_loc7`='Mmm... Según este códice, los mogu Korune intentan controlar el poder de los sha. Y ahora sabemos exactamente dónde. Buen trabajo, $n.' WHERE `ID`=69219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모구 문제는 더 조사해볼 필요가 있습니다. 오늘 할일은 이걸로 끝입니다, $n. 또 부탁할 일이 생기면 지배령 거점에서 당신을 찾겠습니다.', `MaleText_loc4`='显然，这些魔古族值得我们进一步研究。今天我们这里的工作已经结束了，$n。如果我们还需要你，会到统御岗哨跟你联络的。', `MaleText_loc5`='我們顯然需要對這些魔古進行更詳細的研究和調查。但今天的任務暫且算是結束了，$n。若是還有需要你的地方，我們會到制霸岬跟你聯絡的。', `MaleText_loc7`='No me cabe duda de que los mogu merecen una investigación más profunda. Hemos terminado por hoy, $n. Si te necesitamos, nos pondremos en contacto contigo en el Punto de Dominio.' WHERE `ID`=69220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n. 오늘은 충분히 나를 도와주었소. 도움이 더 필요하다면, 지배령 거점에서 그대를 찾겠소.', `MaleText_loc4`='感谢你的协助，$n。你今天已经帮了我们不少忙了。如果我还需要你的帮助，会去统御岗哨找你的。', `MaleText_loc5`='$n，感謝你的協助，今天你真是幫了我一個大忙。將來若是還有事要找你，我會到制霸岬找你的。', `MaleText_loc7`='Gracias por tu ayuda, $n. Ya me has ayudado bastante por hoy. Si vuelvo a necesitarte, te buscaré en el Punto de Dominio.' WHERE `ID`=69221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, $n. 블러드 엘프의 지도자로서, 내게는 백성들을 보호할 책임이 있소. 이는 가볍게 여길 의무가 아니라오.', `MaleText_loc4`='感谢你的协助，$n。作为血精灵的领袖，保护人民是我的职责。这份责任不容轻忽。', `MaleText_loc5`='$n，感謝你的鼎力相助。身為血精靈的領導人，保護他們就是我的職責，而且這是個不容輕忽的職責。', `MaleText_loc7`='Gracias por tu ayuda, $n. Como líder de los elfos de sangre, es mi deber proteger a mi pueblo. Tamaña responsabilidad no se toma a la ligera.' WHERE `ID`=69222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p, 어서 보고하게!', `FemaleText_loc4`='$p，立刻过来报到！', `FemaleText_loc5`='$p，立刻彙報工作!', `FemaleText_loc7`='¡$p! ¡Preséntate al servicio de inmediato!' WHERE `ID`=69223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 경기였습니다. 얼라이언스 승리!', `MaleText_loc4`='GG，联盟获胜！', `MaleText_loc5`='GG!聯盟獲勝!', `MaleText_loc7`='¡Bien jugado, gana la Alianza!' WHERE `ID`=69224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋은 경기였습니다. 호드 승리!', `MaleText_loc4`='GG，部落获胜！', `MaleText_loc5`='GG!部落獲勝!', `MaleText_loc7`='¡Bien jugado, gana la Horda!' WHERE `ID`=69225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 봐라, 말코록. 이것이야말로 우리 백성이 누려야 할 풍요로운 모습이다.', `MaleText_loc4`='看看这里吧，马尔考罗克。只有我们的人民才配得上这样繁荣昌盛的国土。', `MaleText_loc5`='看看這個地方，馬可羅克。這才是我們應該要過的繁榮生活!', `MaleText_loc7`='Observa este lugar, Malkorok. ¡ESTA es la prosperidad que se merece nuestro pueblo!' WHERE `ID`=69228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 왕국을 건설한 자들의 이름을 다시 말해 봐라.', `MaleText_loc4`='是谁建造了这个王国？再告诉我一次他们的名字。', `MaleText_loc5`='再跟我說一次，建造這個王國的人叫什麼來著。', `MaleText_loc7`='Recuérdame el nombre de quienes levantaron este reino.' WHERE `ID`=69229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말인가? 이 "모구"라는 자들에게 배워야 할 게 많군.', `MaleText_loc4`='是吗？看来我得向这些“魔古族”好好学习学习。', `MaleText_loc5`='是嗎?看來我還有很多東西得跟這些「魔古」好好學習。', `MaleText_loc7`='¿Ah, sí? Parece que tengo mucho que aprender de esos "mogu".' WHERE `ID`=69230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구입니다, 대족장님. 판다렌의 역사가 담긴 고서를 보면, 그들은 잔인하고 냉혹한 지도자였다고 합니다. 애정의 대상이 아닌, 공포의 대상이었습니다.', `MaleText_loc4`='是魔古族，酋长。根据熊猫人的历史记载，魔古族是生性残暴的统治者。他们靠强权震慑人民，而非仁政。', `MaleText_loc5`='大酋長，是「魔古」。根據熊貓人的史書記載，他們是殘忍無情的統治者。沒有人敬愛他們，但是大家都害怕他們。', `MaleText_loc7`='Eran los mogu, Jefe de Guerra. El libro de historia pandaren los describe como líderes crueles y despiadados. Eran temidos, no amados.' WHERE `ID`=69231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가, $c?', `MaleText_loc4`='这是什么，$c？', `MaleText_loc5`='什麼事，$c?', `MaleText_loc7`='¿Qué quieres, $c?' WHERE `ID`=69232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 따뜻하고 질퍽거리고 불운이 가득하네요.', `MaleText_loc4`='这地方又热又黏糊，还有股闻起来要倒霉的味道。', `MaleText_loc5`='這個地方溫暖而且散發出厄運的臭味。', `MaleText_loc7`='Este lugar es caluroso y pegajoso y huele a mala fortuna.' WHERE `ID`=69234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수은 수호자가 살아납니다!', `MaleText_loc4`='水银守护者活了过来！', `MaleText_loc5`='幻變守衛醒來了!', `MaleText_loc7`='¡El guardián mercúrico cobra vida!' WHERE `ID`=69235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어... 어떻게 된 거지? 저게 살아나고 있다!', `MaleText_loc4`='发……发生了什么？它活了过来！', `MaleText_loc5`='發生什麼事?它醒過來了!', `MaleText_loc7`='¿Q-qué está pasando? ¡Está cobrando vida!', `FemaleText_loc1`='어... 어떻게 된 거죠? 저게 살아나고 있어요!', `FemaleText_loc4`='发…………发生了什么？它活了过来！', `FemaleText_loc5`='發生什麼事?它醒過來了!', `FemaleText_loc7`='¿Q-qué está pasando? ¡Está cobrando vida!' WHERE `ID`=69236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 할 일이 많다고, $c. 숲에서 나무가 저절로 쓰러지는 게 아니란 말이야!', `MaleText_loc4`='我们有活儿干了，$c。这片树林可不会自己倒下！', `MaleText_loc5`='我們還有活要幹，$c。這片森林不會自己倒下!', `MaleText_loc7`='Tenemos trabajo pendiente, $c. ¡Este bosque no se va a talar solo!' WHERE `ID`=69237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"벌채"라는 건 참 어감이 나쁜 말이야. 난 개인적으로 나무를 베는 건 전망을 좋게 하는 작업이라고 생각하지!$b$b저렇게 나무가 많으면 어떻게 바다를 보겠어?', `MaleText_loc4`='“伐木”这个词听上去不合适，我更喜欢“美化景观”这个说法！$b$b这么多树在这儿挡着，我们怎么看得到海景？', `MaleText_loc5`='伐林多難聽啊，請說是開拓景觀!$b$b不砍掉這些樹，哪能看得到海呢?!', `MaleText_loc7`='"Deforestación" es una palabra muy fea. Yo prefiero pensar que lo que hacemos es "despejar la vista".$b$b¡Nadie podía ver el océano con tanto árbol!' WHERE `ID`=69238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 목재 창고를 짓는 걸 고려 중이야.$b$b이 주변에는 베기만 하면 되는 나무가 널려 있다고. 바보가 아니고서야 이런 기회를 놓칠 순 없지!', `MaleText_loc4`='我正考虑在这里建造一个伐木场。$b$b这里有这么多可以砍伐的树木，要是错过这个大好机会，那我就是傻子了！', `MaleText_loc5`='我打算在這裡開一個木材儲藏所。$b$b這些樹木就在這裡乖乖地等著被人砍掉，傻瓜才會讓這個大好機會白白溜走!', `MaleText_loc7`='Estoy pensando en abrir una serrería aquí.$b$bTantos árboles, esperando a que los talen... ¡Sería de tontos dejar pasar semejante oportunidad!' WHERE `ID`=69239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무에 대해선 걱정하지 말라고! 다 자연의 순환이니까! 나무는 자라고, 우린 나무를 베고, 그 나무로 건물을 짓지!$b$b아, 이건 자연의 순환이 아니라 작업 공정에 가까운가...', `MaleText_loc4`='别为这些树木担心。这就叫生命循环！它们长，我们砍，然后再用它们建造东西！$b$b好像这不叫循环，这叫流水线……', `MaleText_loc5`='別擔心這些樹木，生命的循環就是如此!樹木生長，然後我們砍伐樹木，作為建材!$b$b這個過程與其說是循環，不如說是必然的發展...', `MaleText_loc7`='No te preocupes por los árboles. ¡Es el círculo de la vida! Crecen, los talamos, y luego los utilizamos para construir cosas.$b$bBueno, igual se parece más a una línea que a un círculo...' WHERE `ID`=69240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 기술을 처음 시험 사용해본 건데, 결과가 기대 이상이야! 이걸 가져가. 적들이 떼를 지어 달려들 때 유용할 거야.', `MaleText_loc4`='这项技术的首次实地测试效果超过预期！带着这个，就算遇到再多虫群，你也能搞定它们。', `MaleText_loc5`='這項科技的實地試驗結果超乎預期的好!帶著它，不管有多少蟲群都很管用。', `MaleText_loc7`='¡Mi primera prueba de campo de esta tecnología ha ido mejor de lo que esperaba! Llévate esto, te vendrá bien si te encuentras con más enjambres.' WHERE `ID`=69242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나무의 제일 좋은 점은 다시 자라난다는 거지. 딱 우리가 지속적인 수익 모델이라고 부르는 종류라니까!', `MaleText_loc4`='利用树木挣钱的好处就是，它们还会长出来。这就叫可持续发展！', `MaleText_loc5`='樹的好處就是隨時都長得回來，就像是一筆永續的收入!', `MaleText_loc7`='Lo bueno de los árboles es que vuelven a crecer. ¡Eso sí que son ingresos fijos!' WHERE `ID`=69243;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들은 부수고, 저는 고치죠! 공생하는 관계라고 할 수 있어요.', `FemaleText_loc4`='他们在前头破坏，我就跟在后头修理！这是一种共生关系。', `FemaleText_loc5`='人家破壞我修理，我們維持著互利共生的關係。', `FemaleText_loc7`='¡Ellos lo rompen y yo lo arreglo! Es una relación muy estrecha.' WHERE `ID`=69244;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 불로 못 고칠 건 아무것도 없다는 지론을 갖고 있죠!', `FemaleText_loc4`='我的理论就是，没有啥是用火修不好的！', `FemaleText_loc5`='我的理論就是，沒有火焰修理不好的東西!', `FemaleText_loc7`='Tengo la teoría de que no hay nada que no se pueda arreglar con fuego.' WHERE `ID`=69245;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 바쁜 거 안 보이세요?', `FemaleText_loc4`='你没看见我正忙着吗！', `FemaleText_loc5`='你沒看見我在忙嗎!', `FemaleText_loc7`='¿No ves que estoy ocupada?' WHERE `ID`=69246;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두 할 일이 있죠, $c님. 그리고 어떤 이는 다른 사람들보다 일을 잘하고요!', `FemaleText_loc4`='我们都有要完成的使命，$c。只是，有些人会比别人做得更好！', `FemaleText_loc5`='我們都有工作，$c。差別只在於，有的人做得比較好!', `FemaleText_loc7`='Todos tenemos un trabajo que hacer, $c. Es solo que algunos trabajamos mejor que otros.' WHERE `ID`=69247;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 원유 굴착 장치는 상당히 잘 만들어졌어요. 사실 전 이 장치에 꽤 애착을 가지게 됐답니다. 심지어 브루스라는 별명도 붙여 줬어요!$b$b하지만 이 장치가 항상 문제없이 작동하는 건 아니에요. 기름이 조금 새는데, 구멍에서 10미터 반경 안에 있는 사람은 상당히 위험할 걸요.', `FemaleText_loc4`='这是台好机器。实际上，我跟它已经有感情了。我甚至还给它起了个昵称叫“布鲁斯”！$b$b它只是没法正常运转而已，有点渗漏，而且还可能对周围10英里范围内的人造成威胁。', `FemaleText_loc5`='這個船具做得相當精巧，我對它愛不釋手，甚至給它取了一個小名叫「布魯斯」!$b$b不過它有時不太靈光，有點會漏水，而且可能對10哩內的人造成危害。', `FemaleText_loc7`='Este trasto es una maravilla de la maquinaria. Le he cogido cariño. ¡Hasta lo he llamado Bruce!$b$bLo único malo es que no siempre funciona bien, tiene fugas y probablemente es un peligro para todos los seres vivos en 10 kilómetros a la redonda.' WHERE `ID`=69248;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 이 장치를 발명한 고블린으로 이름이 역사에 길이 남을 걸요.$b$b물론 부작용이 좀 있긴 하지만, 전에 거미를 퇴치하던 방식에 비하면 훨씬 나은 해결 방법이라고요.$b$b거미 잡으려고 집을 홀랑 불태우는 건 몇 번 해보니 영 아니더라고요!', `FemaleText_loc4`='这些机器人一定能让我载入发明史册。$b$b它们当然有一些副作用，但肯定比我们以前处理蜘蛛的方法要好用得多。$b$b毕竟为此把你自己的房子都给烧了是不实际的！', `FemaleText_loc5`='我下一個劃時代的發明便是要對付這些蟲子。$b$b雖然有些副作用，但至少這是目前處理蜘蛛最有效的方法。$b$b比起每隔一段時間便得放火燒了房子，這個方式實際多了!', `FemaleText_loc7`='Pasaré a la historia por inventar estos robots.$b$bSí, tienen algunos efectos secundarios, pero al menos es mejor que nuestra solución anterior para las arañas.$b$bCon el tiempo quemar la casa acaba por resultar poco práctico.' WHERE `ID`=69249;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='옛날 벌목기는 훨씬 다루기 쉬웠죠. 이젠 벌목기에 새로운 관리 시스템이 탑재돼서, 5분마다 먹통이 되곤 한다니까요!', `FemaleText_loc4`='伐木机原本的工作原理很简单。但它们现在有了新的操作系统。现在它们每过5分钟就得趴窝一次！', `FemaleText_loc5`='伐木機曾經非常簡易，如今有了新的操作系統，五分鐘就能解決完畢!', `FemaleText_loc7`='Antes era sencillísimo trabajar con trituradoras, pero ahora tienen un sistema operativo nuevo... ¡Se cuelga cada cinco minutos!' WHERE `ID`=69250;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이렇게 고상하기도 쉬운 일이 아니지만, 누군가는 해야 하는 일이죠!', `FemaleText_loc4`='保持仪态可不容易，可总得有人这么做！', `FemaleText_loc5`='要保持優雅並不容易，但總有人得做這件事!', `FemaleText_loc7`='No es fácil tener tanta clase, ¡pero alguien tiene que hacerlo!' WHERE `ID`=69251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들에게 제 옆에 있으려거든 돈 내라고 해야겠어요.', `FemaleText_loc4`='我一定能够惊艳全场。', `FemaleText_loc5`='我應該要跟所有沐浴在我風采中的人收觀賞費。', `FemaleText_loc7`='Debería empezar a cobrar a la gente solo por estar en mi presencia.' WHERE `ID`=69252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아시겠지만, 아무나 감독관이 될 수 있는 건 아니라고요! 능력도 필요하고, 머리도 좋아야 하고, 물론 외모도 받쳐 줘야죠!', `FemaleText_loc4`='工头可不是人人都能当的！它需要技巧、头脑，当然还有仪表！', `FemaleText_loc5`='不是每個人都能當頭頭!那需要技巧、頭腦還有臉蛋!', `FemaleText_loc7`='¡La jefa no puede ser una cualquiera! Hacen falta habilidad, cerebro, ¡y buen aspecto, por supuesto!' WHERE `ID`=69253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들은 제가 집안 연줄을 이용해 승진한다고 흉보곤 하죠. 저 스스로는 그냥 제가 가진 자원을 현명하게 사용하고 있다고 봐요.$b$b더군다나, 그게 아니라면 가족을 어디에 써먹겠어요?', `FemaleText_loc4`='人们总是指责我任人唯亲。可我把这看做合理使用资源。$b$b再说了，不然我的家人还能做什么？', `FemaleText_loc5`='人們指責我利用家族關係獲得工作上的晉升，在我看來我不過是善用資源罷了。$b$b不然，家人還可以用來做什麼?', `FemaleText_loc7`='La gente siempre me acusa de utilizar mis contactos familiares para ascender. Yo creo que es hacer un uso inteligente de mis recursos.$b$bAdemás, ¿para qué se usa a la familia si no?' WHERE `ID`=69254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남는 휘장을 쓰고 싶소? 내가 받아 드리지.$b$b뭘 사고 싶소?', `MaleText_loc4`='你想用掉多余的委任状？都交给我吧。$b$b你想买点什么？', `MaleText_loc5`='你的佣金花不完嗎?我來幫幫你吧。$b$b你想買點什麼?', `MaleText_loc7`='¿Tienes comisiones de sobra y te gustaría gastártelas? Yo te las quito de las manos.$b$b¿Qué quieres comprar?' WHERE `ID`=69255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위에서 사마귀 무리가 등장하여 공격합니다!', `MaleText_loc4`='一大群螳螂妖在附近出现，并开始发动攻击！', `MaleText_loc5`='附近出現了一群螳螂人朝我們發動攻擊!', `MaleText_loc7`='¡Un enjambre de mántides aparece y ataca!' WHERE `ID`=69256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트릭셀 님의 심부름을 하는 건 행운이라는 걸 알라고!', `MaleText_loc4`='能为女工头干活，你应该感到荣幸！', `MaleText_loc5`='能執行女頭目交代的任務，你應該覺得榮幸!', `MaleText_loc7`='¡Tienes suerte de encargarte de las tareas de la dama jefa!' WHERE `ID`=69257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 도와드릴까요, $g잘생긴 오빠:예쁜 언니;?', `FemaleText_loc4`='我能帮你什么忙吗，$g帅哥:美女;？', `FemaleText_loc5`='我能為你做點什麼，$g 帥哥:美女;?', `FemaleText_loc7`='¿Qué puedo hacer por ti, $ghermoso:hermosa;?' WHERE `ID`=69258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 도망치게 할 수는 없습니다. 좋은 생각이 있습니까?', `MaleText_loc4`='我们不能让任何部落成员逃离这个地方。有什么好主意吗？', `MaleText_loc5`='別讓任何一個部落的成員逃出這裡。有什麼好點子嗎?', `MaleText_loc7`='No podemos permitir que ningún soldado de la Horda salga de este lugar. ¿Alguna idea?', `FemaleText_loc1`='호드를 도망치게 할 수는 없어요. 좋은 생각이 있나요?', `FemaleText_loc4`='我们不能让任何部落成员逃离这个地方。有什么好主意吗？', `FemaleText_loc5`='別讓任何一個部落的成員逃出這裡。有什麼好點子嗎?', `FemaleText_loc7`='No podemos permitir que ningún soldado de la Horda salga de este lugar. ¿Alguna idea?' WHERE `ID`=69259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수은 수호자의 피부가 은 갑옷을 입은 듯 단단해집니다!', `MaleText_loc4`='水银守护者的皮肤变得和白银一样坚硬。', `MaleText_loc5`='幻變守衛的皮膚變得跟白銀一樣堅硬!', `MaleText_loc7`='¡La piel del guardián mercúrico se vuelve tan dura como la plata!' WHERE `ID`=69260;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 딱 좋은 게 있죠...', `FemaleText_loc4`='噢，我们知道现在需要什么……', `FemaleText_loc5`='喔，我們正好有個主意...', `FemaleText_loc7`='Ah, tenemos la solución perfecta...' WHERE `ID`=69261;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 부대원 집합! 꼬꼬알 작전 시작이야!', `FemaleText_loc4`='小队注意！失心果作战行动开始！', `FemaleText_loc5`='小隊!展開行動:咯咯莓!', `FemaleText_loc7`='¡Escuadrón! ¡Dad comienzo a la Operación: Bayarrisa!' WHERE `ID`=69262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 이제 종말을 맞을 시간이다, 침입자들아!', `MaleText_loc4`='够了！你的死期到了，入侵者！', `MaleText_loc5`='夠了!今天就是你的末日，入侵者!', `MaleText_loc7`='¡Ya basta! ¡Hora de morir, invasores!' WHERE `ID`=69263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생각이 맞다면, $n 님, 이... 천상의 종이야말로 가로쉬 님이 찾고 계신 그런 무기가 확실합니다. 우선은 당신을 필요로 하는 다른 곳으로 돌아가십시오. 이 정보는 제가 가로쉬 님께 직접 보고하겠습니다.', `MaleText_loc4`='如果我没弄错的话，$n，这口……圣钟……正是加尔鲁什正在寻觅的武器。你先回去忙其他事情吧，我会亲自把这个消息告诉酋长的。', `MaleText_loc5`='要是我沒弄錯的話，$n，那麼這個...這個「聖鐘」...正是卡爾洛斯要找的武器。你先去辦點其他的任務，我得親自把這個消息告訴大酋長。', `MaleText_loc7`='Si tengo razón, $n, esta Campana divina sería exactamente el tipo de arma que Garrosh está buscando. Por ahora, vuelve al trabajo. Yo informaré al Jefe de Guerra en persona.' WHERE `ID`=69264;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기름이 조금 부족한 것 같아요. 눈을 크게 뜨고 뱀을 찾아보세요. 몇 마리 잡아 놓으면 괜찮을 거예요.', `FemaleText_loc4`='看来我们的油料有点不够了。睁大你的眼睛，小心那些蛇，我们会没事的。', `FemaleText_loc5`='我們沒什麼油了。眼睛睜大點，捉一些蛇回來，應該就能度過難關。', `FemaleText_loc7`='Parece que andamos cortos de aceite. Tú busca culebras y todo irá bien.' WHERE `ID`=69265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 대원들의 힘을 북돋울 게 필요해요. 혹시 뭐 먹을 건 없나요?', `FemaleText_loc4`='队员们都在盯着那个没油的喷火器。这附近有可以吃的东西吗？', `FemaleText_loc5`='我們缺少燃料，這裡有什麼東西是可以吃下肚子的嗎?', `FemaleText_loc7`='Creo que el equipo anda algo falto de energía... ¿hay algo comestible por estos lares?' WHERE `ID`=69266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='강철이 더 있으면 작업이 빨라질 거예요... 이 주변에서 찾을 수 있을 텐데...', `FemaleText_loc4`='如果铁矿供应充足的话，进展还能再快些……这附近或许会有一些矿点。', `FemaleText_loc5`='有鐵的話事情會進行得更加順利...也許這附近有些礦床。', `FemaleText_loc7`='La cosa iría más rápido con más hierro... A lo mejor hay depósitos por aquí.' WHERE `ID`=69267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='특별한 설계 도면을 일지에 기록해 뒀었는데, 일지가 사라져 버렸네요. 어쩔 수 없죠.', `FemaleText_loc4`='我在日记里记了一些特殊的图表，可我把日记弄丢了。我们就凑合着用吧。', `FemaleText_loc5`='我在日誌中記下一些結構圖，可是日誌弄丟了，只能湊合著做了。', `FemaleText_loc7`='Apunté algunos esquemas especiales en mi diario, pero lo perdí. Tendremos que arreglárnoslas.' WHERE `ID`=69268;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='게으름뱅이 친구들! 좀 서둘러야 겠어!', `FemaleText_loc4`='来啊，你们这些懒骨头！加快脚步！', `FemaleText_loc5`='拜託，你這個懶蟲!動作快點!', `FemaleText_loc7`='¡Venga, panda de desgarramantas! ¡Id más deprisa!' WHERE `ID`=69269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠가 지금 제 모습을 보셨으면 얼마나 좋아하셨을까요... 대원들을 지휘해서 국왕 폐하께 봉사하는 모습을요... 무척 뿌듯해 하셨겠죠.', `FemaleText_loc4`='如果让老爸看到我现在的样子……带着自己的队员为国王效力。他一定会骄傲地流泪的。', `FemaleText_loc5`='假如老爸還在...看到我帶領自己的部隊為國王效命，他一定會非常驕傲。', `FemaleText_loc7`='Si papá me viera ahora mismo... Llevando mi propio equipo, en servicio del Rey... Estaría henchido de orgullo.' WHERE `ID`=69270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 사자의 상륙지에서 하늘불꽃호로 통하는 차원문을 열었습니다!', `MaleText_loc4`='%s召唤了一座连通雄师港和天火号的传送门！', `MaleText_loc5`='%s開啟了一道由雄獅灘通往天火號的傳送門!', `MaleText_loc7`='%s ha creado un portal del Desembarco del León a El Abrasacielos.', `FemaleText_loc1`='%s|1이;가; 사자의 상륙지에서 하늘불꽃호로 통하는 차원문을 열었습니다!', `FemaleText_loc4`='%s召唤了一座连通雄师港和天火号的传送门！', `FemaleText_loc5`='%s開啟了一道由雄獅灘通往天火號的傳送門!', `FemaleText_loc7`='%s ha creado un portal del Desembarco del León a El Abrasacielos.' WHERE `ID`=69271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 일곱 별의 제단으로 통하는 차원문을 열었습니다!', `MaleText_loc4`='%s召唤了一座通往七星殿的传送门！', `MaleText_loc5`='%s開啟了一道通往七星廟的傳送門!', `MaleText_loc7`='%s ha creado un portal al Santuario de las Siete Estrellas.', `FemaleText_loc1`='%s|1이;가; 일곱 별의 제단으로 통하는 차원문을 열었습니다!', `FemaleText_loc4`='%s召唤了一座通往七星殿的传送门！', `FemaleText_loc5`='%s開啟了一道通往七星廟的傳送門!', `FemaleText_loc7`='%s ha creado un portal al Santuario de las Siete Estrellas.' WHERE `ID`=69272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 스톰윈드로 통하는 차원문을 열었습니다!', `MaleText_loc4`='%s召唤了一座通往暴风城的传送门！', `MaleText_loc5`='%s開啟了一道通往暴風城的傳送門!', `MaleText_loc7`='%s ha creado un portal a Ventormenta.', `FemaleText_loc1`='%s|1이;가; 스톰윈드로 통하는 차원문을 열었습니다!', `FemaleText_loc4`='%s召唤了一座通往暴风城的传送门！', `FemaleText_loc5`='%s開啟了一道通往暴風城的傳送門!', `FemaleText_loc7`='%s ha creado un portal a Ventormenta.' WHERE `ID`=69273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 뭘 원하는가?', `MaleText_loc4`='……你想要什么？', `MaleText_loc5`='... 你要做什麼?', `MaleText_loc7`='¿Qué quieres?' WHERE `ID`=69274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 책에 대해 아는 게 있나?', `MaleText_loc4`='有关这本法典，你有什么能告诉我的吗？', `MaleText_loc5`='你知道這本是什麼書嗎?', `MaleText_loc7`='¿Qué puedes contarme acerca de este escrito?', `FemaleText_loc1`='이 책에 대해 아는 게 있니?', `FemaleText_loc4`='有关这本法典，你有什么能告诉我的吗？', `FemaleText_loc5`='你知道這本是什麼書嗎?', `FemaleText_loc7`='¿Qué puedes contarme acerca de este escrito?' WHERE `ID`=69275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 나스레짐의 고향에서 이런 문자를 본 기억이 나는군. 나도 읽을 수는 없다. 너희 중에도 그럴 수 있는 자는 없을 테고.', `MaleText_loc4`='嗯……我曾在纳斯雷兹姆的家乡见过这些文字。我无法读懂这些文字，你的族人应该也不行。', `MaleText_loc5`='嗯...我在納斯雷茲姆的家鄉見過這種文字。我不知道怎麼讀它，而且我想你們應該也沒有人看得懂。', `MaleText_loc7`='Mmm... Recuerdo haber visto estos símbolos en el mundo natal de los Nathrezim. No sé leerlos, y dudo mucho que algún miembro de tu especie sepa.' WHERE `ID`=69276;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕, 주인님? 오늘은 또 어떻게 해드릴까요...?', `FemaleText_loc4`='你好，主人……我今天能为你做点什么呢……？', `FemaleText_loc5`='嗨，主人... 今天要我為你提供什麼... 服務呢?', `FemaleText_loc7`='Hola, $gamo:ama;. ¿Qué tipo de servicio podría ofrecerte hoy?' WHERE `ID`=69277;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐? 나한테 더러운 옛날 책을 읽어달라고요? 어휴, 정말 실망이야.$B$B이건 나스레짐의 책이라고요. 당신네들은 공포의 군주라고도 하죠? 그들 고향 밖에서는 본 적이 없는데...', `FemaleText_loc4`='什么？你就想让我看这些又脏又旧的书？噢，真扫兴。$B$B这是纳斯雷兹姆，也就是你们所说的恐惧魔王的语言。他们很少在家乡之外的地方使用这种文字。', `FemaleText_loc5`='什麼?你只是要我看看這本又破又舊的書?唉， 好失望。$B$B這是「納斯雷茲姆」，也就是你們稱為驚懼領主的文字，他們很少在家鄉之外使用這種文字。', `FemaleText_loc7`='¿Qué? ¿Solo quieres que mire un libro vetusto y polvoriento? Bah, qué decepción.$b$bEs la escritura de los Nathrezim, los que tú llamas Señores del Terror. No suelen utilizarlo fuera de su mundo.' WHERE `ID`=69278;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 뭘 원하냐, 이 불쌍한 $r 종자야?', `FemaleText_loc4`='你想要什么，你这$r可怜虫？', `FemaleText_loc5`='該死的$r，你到底要幹嘛?', `FemaleText_loc7`='¿Y TÚ qué quieres, $gpatético:patética; $r miserable?' WHERE `ID`=69279;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니. 난 너희 종족이 고대 나스레짐 문서를 읽는 걸 도와주는 일 따위는 하지 않겠다. 자, 어서 나를 돌려보내!', `FemaleText_loc4`='不。我才不帮你解读古代纳斯雷兹姆文献呢。立刻放了我！！', `FemaleText_loc5`='不，我才不會幫你們解讀古老的納斯雷茲姆文字。趕快放了我!!', `FemaleText_loc7`='No. No pienso ayudar a alguien de tu calaña a leer un texto antiguo de los Nathrezim. ¡Ahora libérame!' WHERE `ID`=69280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 네? 무슨 일이죠, 주인님?', `MaleText_loc4`='……嗯？开饭了吗，老板？', `MaleText_loc5`='... 啊?幹啥，主人?', `MaleText_loc7`='¿Sí? ¿Qué pasa, $gjefe:jefa;?' WHERE `ID`=69281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 전혀 모르겠네요.', `MaleText_loc4`='嗯……我不清楚。', `MaleText_loc5`='嗯... 我不知道。', `MaleText_loc7`='Hmm... No tengo ni idea.' WHERE `ID`=69282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 돌려보내라... 공허로 돌아가고 싶다.', `MaleText_loc4`='放我走吧……我想回到虚空中去。', `MaleText_loc5`='放我走... 我想回到虛無。', `MaleText_loc7`='Libérame... Deseo volver al vacío.' WHERE `ID`=69283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='글이란 것은 공허의 것이 아니다. 나는 모른다... 그저... 두 개의 별을 연결하는 것으로 보인다...', `MaleText_loc4`='虚空之中不需要文字。我不知道……它似乎能连通……两颗星辰……', `MaleText_loc5`='言語無用於虛... 我不知道... 它好像，把兩個... 星星連在一起...', `MaleText_loc7`='Las palabras no abundan en el vacío. No lo sé... Parece que conecta dos... estrellas...' WHERE `ID`=69284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 이야기하고 싶다고...? 이상한 일이군...', `MaleText_loc4`='你想和我谈谈……？真少见……', `MaleText_loc5`='你有話要跟我說...? 真是不尋常...', `MaleText_loc7`='¿Deseas hablar conmigo...? Qué... inaudito...' WHERE `ID`=69285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 글은 읽을 수 없다... 하지만 그 마법은 이제 존재하지 않는 세계를 가리키는군. 불타는 군단이 파괴해 버린 세계다.', `MaleText_loc4`='我无法读懂这些文字……但这股魔法指向了另一个已不复存在的世界。它是被燃烧军团摧毁的。', `MaleText_loc5`='我看不懂這些字... 但是上面的魔法指向一個已經不存在的世界，被軍團摧毀的世界。', `MaleText_loc7`='No sé leer esas palabras... pero la magia señala a un mundo que ya no existe. La Legión lo destruyó.' WHERE `ID`=69286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥사냥개가 당신을 멍하니 바라봅니다.', `MaleText_loc4`='它茫然地看着你。', `MaleText_loc5`='它面無表情地看著你。', `MaleText_loc7`='Te mira inexpresivo.' WHERE `ID`=69287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥사냥개가 고개를 갸웃하며 당신을 이상한 눈초리로 바라봅니다.', `MaleText_loc4`='地狱犬歪着头，奇怪地看着你。', `MaleText_loc5`='惡魔獵犬只是歪著頭，詭異地看著你。', `MaleText_loc7`='El manáfago ladea la cabeza y se limita a mirarte de forma extraña.' WHERE `ID`=69288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $g주인:여왕;님... 제가 뭘 도와드릴까요?', `MaleText_loc4`='啊，$n主人，我能帮您什么忙吗？', `MaleText_loc5`='啊，$n$g主人:女主人;，我能為您效勞什麼嗎?', `MaleText_loc7`='Ah, mi $gseñor:señora; $n. ¿En qué puedo ayudarte?' WHERE `ID`=69289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다! 이 고서는 고대 나스레짐의 언어로 쓰여 있습니다. 필멸자들이 공포의 군주라고도 부르는 나스레짐은 한때 현명하고 강력한 존재였습니다. 그들의 소환술과 관문을 여는 마법은 끝없는 어둠 너머의 그 어떤 존재보다도 뛰어났습니다.$B$B이 고서에는 다른 세계로 통하는 관문을 여는 방법이 담겨 있습니다. 아쉽지만, 그 세계는 이제 존재하지 않습니다. 소로스가 힘을 얻는 과정에서 파괴해 버렸거든요.$b$b안타깝게도 이 고서는 이제 쓸모가 없습니다. 어떤 $r $c도 혼자서는 이런 관문을 열 수 없으니까요.', `MaleText_loc4`='当然！这本法典是由古代纳斯雷兹姆语写成的。纳斯雷兹姆，也就是你们所说的恐惧魔王，曾是睿智而强大的种族。在无尽的黑暗虚空之中，没有哪个种族的召唤和传送法术造诣能超越他们。$B$B这本法典记载着如何开启通向另一个世界的传送门。可惜的是，那个世界已经不复存在了。在克索诺斯统治期间，为了展示力量，它把这个世界毁了。$B$B这本法典恐怕已经没用了。没有哪个$r$c能够光凭自己的力量打开这道传送门。', `MaleText_loc5`='當然! 這本書是以古老的納斯雷茲姆文字寫成的。納斯雷茲姆，也就是你們所稱的驚懼領主，曾經是文明強大的一族。他們的召喚與傳送魔法的技巧全混沌黑暗無人能比。$B$B這本特別的書裡記載通往另一個世界的方法。可惜，只怕那個世界已經不存在了，在奴役克索諾斯時為了展現軍團的力量而被徹底毀掉了。$B$B恐怕這本書一點用處也沒有，因為沒有任何$r$c能獨自打開那樣的通道。', `MaleText_loc7`='¡Por supuesto! Este códice está escrito en la antigua lengua de los Nathrezim. Los Nathrezim, o Señores del Terror, como los conoces, antes eran una raza ilustrada y poderosa. Su habilidad con la magia de portales e invocaciones no tenía parangón en toda la Gran Oscuridad del Más Allá.$b$bEste escrito en concreto explica cómo abrir un portal a otro mundo. Por desgracia, me temo que ese mundo ya no existe. Lo destruyeron como demostración de poder durante la esclavitud de Xoroth.$b$bLo siento, pero el escrito no tiene valor. $gUn:Una; $r $c sería incapaz de abrir semejante portal $gsolo:sola;.' WHERE `ID`=69290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 그렇게 똑똑한 줄은 몰랐는데.', `MaleText_loc4`='想不到你知道的还挺多。', `MaleText_loc5`='原來你的見識這麼廣博。', `MaleText_loc7`='No tenía ni idea de que estuvieras tan bien $ginformado:informada;.', `FemaleText_loc1`='네가 그렇게 똑똑한 줄은 몰랐는걸.', `FemaleText_loc4`='想不到你知道的还挺多。', `FemaleText_loc5`='原來你的見識這麼廣博。', `FemaleText_loc7`='No tenía ni idea de que estuvieras tan bien $ginformado:informada;.' WHERE `ID`=69291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 세계에 일어나는 모든 일을 목격하는 것이 감시자의 숙명입니다. 당신 곁에서는 정말 맛있는 마법들을 여럿 맛보았지요, $g주인:여왕;님.', `MaleText_loc4`='我们眼魔就是为了见证万物的兴衰而生的。而我在您身边已经品尝到许多美味的魔法，主人。', `MaleText_loc5`='這是「觀察者」體驗事物的方式。我為你品嚐過許多美味的魔法，$g主人:女主人;。', `MaleText_loc7`='El deber del observador es ser testigo de todo lo que sucede. He probado muchísimos tipos deliciosos de magia a tu lado, mi $gseñor:señora;.' WHERE `ID`=69292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재미있군...', `MaleText_loc4`='真有意思……', `MaleText_loc5`='真有意思...', `MaleText_loc7`='Fascinante...', `FemaleText_loc1`='재미있는걸...', `FemaleText_loc4`='真有意思……', `FemaleText_loc5`='真有意思...', `FemaleText_loc7`='Fascinante...' WHERE `ID`=69293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구브, 돕는다!', `MaleText_loc4`='古布来帮忙了！', `MaleText_loc5`='戈伯幫你!', `MaleText_loc7`='¡Goob ayuda!' WHERE `ID`=69294;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠는 늘 저를 ''착한 아이''라고 부르셨어요. 하지만 여기 호드 벌레들을 위해 우리가 준비하는 건 그다지 착하지 않아요!', `FemaleText_loc4`='‘乖孩子’，老爸总这么叫我。呃，可我们给这些部落混蛋准备的东西可就不那么美妙了！', `FemaleText_loc5`='爸爸總是叫我「甜心寶貝」，嘿嘿，就讓我來弄點「甜頭」給部落的敗類嚐嚐吧!', `FemaleText_loc7`='"Mi dulce niña", me llamaba papá. Pues bien, ¡lo que estamos preparando para esas alimañas de la Horda no es muy dulce que digamos!' WHERE `ID`=69295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구브 도움, 필요 없나?', `MaleText_loc4`='不要古布帮忙了？', `MaleText_loc5`='不需要戈伯的幫助嗎?', `MaleText_loc7`='¿No quieres ayuda de Goob?' WHERE `ID`=69296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알았다. 구브, 지노한테 돌아간다.', `MaleText_loc4`='好吧，古布回兹诺那儿了。', `MaleText_loc5`='沒問題，戈伯回到席諾。', `MaleText_loc7`='Vale. Goob vuelve con Zino.' WHERE `ID`=69297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구브랑 친구가 일 잘했다!', `MaleText_loc4`='古布和伙计们干得好！', `MaleText_loc5`='戈伯是你們的好朋友!', `MaleText_loc7`='¡Goob y colega trabajan bien!' WHERE `ID`=69298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 목숨은 호드의 것이오.', `MaleText_loc4`='誓死效忠部落。', `MaleText_loc5`='我的生命獻給部落!', `MaleText_loc7`='Mi vida por la Horda.' WHERE `ID`=69299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제때 끝내지 못할 것 같습니다! 더 빨리 할 수는 없습니까?', `MaleText_loc4`='我们要赶不上工期了！就不能让他们干快点儿？', `MaleText_loc5`='我們來不及了!不能要他們走快一點嗎?', `MaleText_loc7`='¡No acabaremos nunca! ¿No hay forma de que vayan más rápido?', `FemaleText_loc1`='제때 끝내지 못할 것 같아요! 더 빨리 할 수는 없나요?', `FemaleText_loc4`='我们要赶不上工期了！就不能让他们干快点儿？', `FemaleText_loc5`='我們來不及了!不能要他們走快一點嗎?', `FemaleText_loc7`='¡No acabaremos nunca! ¿No hay forma de que vayan más rápido?' WHERE `ID`=69300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록을 모구가 만들었다고?', `MaleText_loc4`='[PH] De Saurok been created by da Mogu?', `MaleText_loc5`='[PH] De Saurok been created by da Mogu?', `MaleText_loc7`='TEMP' WHERE `ID`=69301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 그래도 언제 그 얘기를 하시려나 궁금해 하던 중이었어요!$b$b우리 힘만으로도 어떻게든 할 수 있겠지만, 당신이 도와줄 수 있는 일도 많아요.$b$b우리 노움은 신진대사가 활발해요. 열심히 일할 때는 더욱 그렇고요. 언제든 음식을 가져오시면 좋겠어요.$b$b그리고 기름이 필요해요. 이 덫은 구조가 무척 복잡해서 톱니바퀴가 엉겨 붙기라도 하면 큰일이에요. 근처에서 기름을 발견하면 여기로 가져다 주세요.$b$b그리고 우리가 안전하게 지켜 주시고요!$b$b<잠시 멍한 표정을 지은 후, 귓속말을 하는 로지>$b$b또... 한 가지가...', `FemaleText_loc4`='我还以为你就不问了呢！$b$b我们迟早会完成的，可现在也有很多你帮得上忙的地方。$b$b我们侏儒的新陈代谢很快——在我们努力工作时尤其如此。所以食物总是很受欢迎的。$b$b然后是油。这些陷阱非常精巧，不用担心齿轮会被卡住。把你能找到的油都带回来给我们。$b$b除此之外，还要保障我们的安全！$b$b<罗塞向四周看了看，又压低声音说道。>$b$b还——可能还有一件事……', `FemaleText_loc5`='我還以為你永遠都不會問!$b$b我們會完成交代，但是有許多事情需要你的協助。$b$b我們地精的新陳代謝很快 - 認真工作時餓得更快。我們永遠需要食物。$b$b帶油回來。這些陷阱非常靈光，不需要擔心任何故障。帶回你在那兒找到的任何油。$b$b人在外頭凡事小心!$b$b<玫瑰把頭轉向一邊，然後輕聲說道。>$b$b還有一件事...', `FemaleText_loc7`='¡Pensaba que nunca me lo preguntarías!$b$bTarde o temprano acabaremos el trabajo, pero hay muchas cosas que puedes hacer para ayudar.$b$bLos gnomos tenemos un metabolismo rápido, y cuando trabajamos se vuelve aún más rápido. La comida siempre viene bien.$b$bLuego está el aceite. Esas trampas ya son bastante complicadas como para preocuparse de que se atasquen los engranajes. Tráenos todo el aceite que encuentres.$b$bAparte de eso, ¡protégenos!$b$b<Rosey mira a su alrededor y susurra.>$b$bY puede que haya algo más...' WHERE `ID`=69302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 잡아!', `MaleText_loc4`='[PH] Get them!', `MaleText_loc5`='[PH] Get them!', `MaleText_loc7`='TEMP' WHERE `ID`=69303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 뭐가 필요하십니까?', `MaleText_loc4`='好吧，那是什么？', `MaleText_loc5`='嗯?什麼?', `MaleText_loc7`='¿Y bien? ¿De qué se trata?', `FemaleText_loc1`='네, 뭐가 필요하세요?', `FemaleText_loc4`='好吧，那是什么？', `FemaleText_loc5`='嗯?什麼?', `FemaleText_loc7`='¿Y bien? ¿De qué se trata?' WHERE `ID`=69304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무시무시한 부두교 주술 안으로 들어가게! 놈의 힘으로부터 보호받을 수 있게!', `MaleText_loc4`='[PH] Get into da big bad voodoo zones mon''! It''ll shield you from his powa!', `MaleText_loc5`='[PH] Get into da big bad voodoo zones mon''! It''ll shield you from his powa!', `MaleText_loc7`='TEMP' WHERE `ID`=69305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<눈물을 참으며 말하는 로지>$b$b제가 갖고 있던... 일지가... 없어졌어요.$b$b우리 아빠에 대한 기억이 가득 담긴 일지에요. 천국 같은 도시를 건설하기에 꼭 알맞은 장소를 찾아 끝없이 돌아다녔던 얘기가 적혀 있어요. 노움 기계공학의 정점을 찍을 기반이었는데!$b$b사실, 아빠가 남긴 설계 도면이 여기 일에 실질적으로 도움이 될 것 같아요. 저기 수풀 사이에서 일지를 발견하면 제게 말씀해 주세요.', `FemaleText_loc4`='<罗塞强忍着眼泪，说道。>$b$b我的……我的日记。它不见了。$b$b里面充满了我老爸的回忆，还有他的大量有关建造天堂都市的完美地点的研究。那可是侏儒工程学的巅峰之作！$b$b总之，里面有一副他的旧图纸或许能在这里派上用处。如果你在这附近的草丛里发现了它，请一定要告诉我。', `FemaleText_loc5`='<玫瑰邊忍住淚水邊說。>$b$b我的... 我的日誌...不見了。$b$b裡頭有好多我爸爸的回憶，還有他不斷在尋找適當的地點、建造他的完美城市的記錄。如果蓋起來了，那將是地精科技的完美結晶。!$b$b對了，其中有張他舊的結構圖，說不定還能在這兒派上用場。要是你在這附近的草叢裡找到了，麻煩請你告訴我。', `FemaleText_loc7`='<Rosey trata de contener las lágrimas.>$b$bMi... mi diario. Ha desaparecido.$b$bEstá lleno de recuerdos de mi papá, y de su búsqueda incesante del lugar perfecto para construir su ciudad ideal. ¡Iba a ser la cúspide de la ingeniería gnómica!$b$bEn cualquier caso, uno de sus antiguos esquemas podría venirnos bien. Avísame si lo encuentras entre toda esta hierba verde.' WHERE `ID`=69306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 당신이 잃어버린 일지입니까, 로지?', `MaleText_loc4`='这是你的日记吗，罗塞？', `MaleText_loc5`='這是你的日誌嗎，玫瑰?', `MaleText_loc7`='¿Es este tu diario, Rosey?', `FemaleText_loc1`='이게 당신이 잃어버린 일지인가요, 로지?', `FemaleText_loc4`='这是你的日记吗，罗塞？', `FemaleText_loc5`='這是你的日誌嗎，玫瑰?', `FemaleText_loc7`='¿Es este tu diario, Rosey?' WHERE `ID`=69307;
