UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네? 일지를 찾으셨다고요!? 야호! 당장 작업을 시작할게요!', `FemaleText_loc4`='什么？你找到了！哇！我马上就开工！', `FemaleText_loc5`='什麼?你真的找到了!哇呼!我立刻開始動工!', `FemaleText_loc7`='¿Qué? ¡Lo has encontrado! ¡Yuju! ¡Me pondré manos a la obra!' WHERE `ID`=69309;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그거 아세요? 성공했다고요!', `FemaleText_loc4`='哇，你知道吗？它起作用了！', `FemaleText_loc5`='嘿，真的有用耶!', `FemaleText_loc7`='¿Quién lo iba a decir? ¡Ha funcionado!' WHERE `ID`=69310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 건설 현장이 공격받고 있습니다!', `MaleText_loc4`='侏儒建筑营地遭到攻击！', `MaleText_loc5`='地精建築工地遭到攻擊!', `MaleText_loc7`='¡Están atacando la zona de construcción gnómica!', `FemaleText_loc1`='노움 건설 현장이 공격받고 있습니다!', `FemaleText_loc4`='侏儒建筑营地遭到攻击！', `FemaleText_loc5`='地精建築工地遭到攻擊!', `FemaleText_loc7`='¡Están atacando la zona de construcción gnómica!' WHERE `ID`=69311;
