UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하! 양극 협력 변환기를 바꾸는걸 깜빡 했군요!', `MaleText_loc4`='啊！我忘记反转两极协同转换器了。', `MaleText_loc5`='啊!我忘了去反轉那個雙極共能變流器。', `MaleText_loc7`='¡Ah! Se me olvidó desactivar el inversor de colaboración bipolar.' WHERE `ID`=69313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t당신은 |cFFFF0000|Hspell:133925|h[폭탄]|h|r의 대상입니다! 도망치세요!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t你成为了|cFFFF0000|Hspell:133925|h[狂轰滥炸]|h|r的目标！快跑！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t你現在是|cFFFF0000|Hspell:133925|h[轟炸]|h|r的目標!快跑!', `MaleText_loc7`='|TInterfaceIconsinv_misc_bomb_01.blp:20|t¡Eres el objetivo de |cFFFF0000|Hspell:133925|h[¡Bomba!]|h|r! ¡Corre!' WHERE `ID`=69314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"헬로 월드" 프로그램 인식 중. 첫 단계: 상대방의 코앞에서 폭발.', `MaleText_loc4`='正在解读“你好，世界”程序。第一行：把敌人的脸打扁。', `MaleText_loc5`='編譯「Hello World」程式。第1行: 炸花敵人的臉。', `MaleText_loc7`='Interpretando programa "Hola, mundo". Primera línea: explotar en la cara del enemigo.' WHERE `ID`=69315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오류 발생: 보호된 메모리에 쓰기 시도. 해결책: 상대방에게 다가가 자폭.', `MaleText_loc4`='出错：试图在写保护内存上存储信息。解决方案：向敌人移动并自爆。', `MaleText_loc5`='錯誤:嘗試寫入受保護的記憶體。解析:朝敵人移動並自我毀滅。', `MaleText_loc7`='Error: intentando guardar en memoria protegida. Solución: acercarse al enemigo y explotar.' WHERE `ID`=69316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 포인터 예외. 자폭 프로토콜 가동.', `MaleText_loc4`='空指针异常。启动自爆协议。', `MaleText_loc5`='Null Pointer Exception，啟動自我毀滅協定。', `MaleText_loc7`='Excepción de seguridad. Protocolo de autodestrucción iniciado.' WHERE `ID`=69317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오류 발생: 값을 0으로 나눔. 해결책: 자폭 시스템 가동', `MaleText_loc4`='出错：除数为零。解决方案：启动自爆程序。', `MaleText_loc5`='錯誤:除以零。解析:啟動自毀程式。', `MaleText_loc7`='Error: dividiendo por cero. Solución: AUTODESTRUCCIÓN INICIADA.' WHERE `ID`=69318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해시 테이블 충돌 감지. 해결책: 자폭.', `MaleText_loc4`='检测到哈希数据表冲突。解决方案：自爆。', `MaleText_loc5`='雜湊表碰撞測試。解析:自我毀滅。', `MaleText_loc7`='Colisión de tablas de cálculo detectada. Solución: EXPLOTAR.' WHERE `ID`=69319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오! 명령이 도착했어! 어디보자... 자폭하라고?!', `MaleText_loc4`='喔！有指令！让我们看看……自爆？！', `MaleText_loc5`='喔!指令!讓我瞧瞧...自我毀滅?!', `MaleText_loc7`='¡Oh! ¡Órdenes! A ver... ¡¿Autodestruirme?!' WHERE `ID`=69320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 내가 프로그래밍된 목적은... <하아> 자폭.', `MaleText_loc4`='嗯，看起来我的程序是用来……自爆。', `MaleText_loc5`='嗯，看來我被設定成...<嘆氣>自我毀滅的程式。', `MaleText_loc7`='Mmm, parece que me han programado para... <suspiro> autodestruirme.' WHERE `ID`=69321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호! 새로운 프로그램이야! 어디 보자... 알아서 터지라고?!', `MaleText_loc4`='天呐！一个新程序！让我们看看……自爆？！', `MaleText_loc5`='噢老天!新的程式!讓我瞧瞧...自行爆炸?!', `MaleText_loc7`='¡Toma! ¡Un programa nuevo! A ver... ¡¿HACERME ESTALLAR?!' WHERE `ID`=69322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그럼 예전 프로그램을 살펴 봐야겠군... 또 자폭하라고?!', `MaleText_loc4`='好吧，让我们看看这些程序……自爆？！', `MaleText_loc5`='算了，來瞧瞧舊有程式...自我毀滅?!', `MaleText_loc7`='Muy bien, a ver qué dice la programación... ¡¿AUTODESTRUIRME?!' WHERE `ID`=69323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 만나서 반가웠어.', `MaleText_loc4`='好吧，很高兴认识你。', `MaleText_loc5`='很高興認識你。', `MaleText_loc7`='Bueno, me alegro de haberte conocido.' WHERE `ID`=69324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에... 다음에 봐!', `MaleText_loc4`='呃……以后再说！', `MaleText_loc5`='啊...晚一點!', `MaleText_loc7`='Eh... ¡hasta luego!' WHERE `ID`=69325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발할 때 기분이 어떨까?', `MaleText_loc4`='我想知道自爆感觉如何？', `MaleText_loc5`='不知道爆炸是什麼感覺?', `MaleText_loc7`='¿Me pregunto qué se siente al explotar?' WHERE `ID`=69326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼... 난 여기서 빠져나가야겠어!', `MaleText_loc4`='我……得走了！', `MaleText_loc5`='...我先閃了!', `MaleText_loc7`='¡Yo me las piro!' WHERE `ID`=69327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자폭은 정말 끝내줘!', `MaleText_loc4`='自爆的感觉太棒了。', `MaleText_loc5`='自我毀滅，太酷了。', `MaleText_loc7`='Autodestruirse es LO MÁS.' WHERE `ID`=69328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네? 여기서요? 지금? 우린 지금 전쟁 중이라고요!$b$b당신이 노움 기계공학을 배우기 위해 안달이 나있는 건 알지만 이런 이야기는 땜장이 마을로 돌아가서 하는 게 더 안전하지 않을까요?', `MaleText_loc4`='什么？在这儿？现在？我们可是在打仗！$b$b尽管你对侏儒工程学的热情让我非常欣慰，但还是等我们回到铁炉堡的工匠镇再来谈这件事情吧。', `MaleText_loc5`='什麼?這裡?現在?我們正在打仗耶!$b$b你對地精工程學的熱愛我很感動，但是我們最好等回到鐵爐堡的地精區再來談這個話題。', `MaleText_loc7`='¿Qué? ¿Aquí? ¿Ahora? ¡Estamos en combate!$b$bAunque me encanta tu entusiasmo por aprender los misterios de la ingeniería gnómica, esa conversación es mejor reservarla para cuando volvamos a estar a salvo en Ciudad Manitas, en Forjaz.' WHERE `ID`=69329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 다른 이야기를 하고 싶어요.', `MaleText_loc4`='很好，我希望谈点别的。', `MaleText_loc5`='很好，我們能不能談談別的。', `MaleText_loc7`='Muy bien. Me gustaría hablar de otra cosa.', `FemaleText_loc1`='알겠습니다. 다른 이야기를 하고 싶어요.', `FemaleText_loc4`='很好，我希望谈点别的。', `FemaleText_loc5`='很好，我們能不能談談別的。', `FemaleText_loc7`='Muy bien. Me gustaría hablar de otra cosa.' WHERE `ID`=69330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자유다! 만 년 동안 갇혀있다가 드디어 풀려났어! 오늘은 즐거운 날이야! 정말 정말 즐거운 날! 잔치를 열어야겠어! 마실 거랑! 먹을 거랑! 취할 거랑! 그리고 밀림 호젠! 그리고 산악 호젠! 그리고 하늘 호젠!', `MaleText_loc4`='自由啦！一万年以后，我终于自由啦！今天是个好日子！很好很好的好日子！要搞个大派对！要有好吃的！要有好玩的！要有好喝的！叫上丛林猢狲！叫上山地猢狲！叫上天空猢狲！', `MaleText_loc5`='自由了!一萬年之後終於自由了!今天是個大日子!歡天喜地的一天!應該來舉辦一場空前的盛會!有吃，有玩，又有喝的!邀請叢林猴人!山地猴人!還有天空猴人!', `MaleText_loc7`='¡Libre! ¡Libre después de diez mil años! ¡Hoy es un gran día! ¡Gran, gran día! ¡Yo va a montar mayor fiesta de la historia! ¡Con wakus! ¡Y krakus! ¡Y birra! ¡Y hozen de la selva! ¡Y hozen de las montañas! ¡Y hozen del cielo!' WHERE `ID`=69331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 저리... 저리가!', `MaleText_loc4`='不！走……走开！', `MaleText_loc5`='不!...走開!', `MaleText_loc7`='¡No! Aléjate...', `FemaleText_loc1`='안돼! 저리... 저리가!', `FemaleText_loc4`='不！走……走开！', `FemaleText_loc5`='不!...走開!', `FemaleText_loc7`='¡No! Aléjate...' WHERE `ID`=69332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더... 더 이상 다가오지 마!', `MaleText_loc4`='别过来！', `MaleText_loc5`='不准再靠近一步!', `MaleText_loc7`='¡N-no te acerques!', `FemaleText_loc1`='더... 더 이상 다가오지 마!', `FemaleText_loc4`='别过来！', `FemaleText_loc5`='不准再靠近一步!', `FemaleText_loc7`='¡N-no te acerques!' WHERE `ID`=69333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 안 좋아...', `MaleText_loc4`='我感觉不太好……', `MaleText_loc5`='我覺得不太舒服....', `MaleText_loc7`='No me siento bien...', `FemaleText_loc1`='속이 안 좋아...', `FemaleText_loc4`='我感觉不太好……', `FemaleText_loc5`='我覺得不太舒服....', `FemaleText_loc7`='No me siento bien...' WHERE `ID`=69334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='윽... 내 머리... 깨질것같아!', `MaleText_loc4`='啊……我的头……好疼！', `MaleText_loc5`='喔...我的頭...好痛!', `MaleText_loc7`='Agh... me duele... ¡la cabeza!', `FemaleText_loc1`='윽... 내 머리... 깨질것같아!', `FemaleText_loc4`='啊……我的头……好疼！', `FemaleText_loc5`='喔...我的頭...好痛!', `FemaleText_loc7`='Agh... me duele... ¡la cabeza!' WHERE `ID`=69335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐... 뭐였죠? 제 몸을 통제할 수 없었습니다.', `MaleText_loc4`='发……发生了什么？我控制不了自己的身体了。', `MaleText_loc5`='怎麼會?我沒辦法控制身體。', `MaleText_loc7`='¿Q-qué ha pasado? No podía controlar mi propio cuerpo.', `FemaleText_loc1`='뭐... 뭐였죠? 제 몸을 통제할 수 없었어요.', `FemaleText_loc4`='发……发生了什么？我控制不了自己的身体了。', `FemaleText_loc5`='怎麼會?我沒辦法控制身體。', `FemaleText_loc7`='¿Q-qué ha pasado? No podía controlar mi propio cuerpo.' WHERE `ID`=69336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 괴물로 변하는 꿈을 꾸었습니다. 깨워 주셔서 고맙습니다.', `MaleText_loc4`='我梦到我变成了一个怪物。还好你把我弄醒了。', `MaleText_loc5`='我夢到自己變成一隻怪物。幸好你叫醒了我。', `MaleText_loc7`='Soñé que me convertía en un monstruo. Menos mal que me has despertado.', `FemaleText_loc1`='제가 괴물로 변하는 꿈을 꾸었어요. 깨워 주셔서 고마워요.', `FemaleText_loc4`='我梦到我变成了一个怪物。还好你把我弄醒了。', `FemaleText_loc5`='我夢到自己變成一隻怪物。幸好你叫醒了我。', `FemaleText_loc7`='Soñé que me convertía en un monstruo. Menos mal que me has despertado.' WHERE `ID`=69337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악몽에서 구해줘서 감사합니다. 주위의 모든걸 찢어버리고 싶었어요!', `MaleText_loc4`='谢谢你把我从那个噩梦中救出来。当时我真想把一切都毁了！', `MaleText_loc5`='謝謝你讓我從惡夢中醒來。我在夢中獸性大發。', `MaleText_loc7`='Gracias por salvarme de esa pesadilla. ¡Quería reducirlo todo a cenizas!', `FemaleText_loc1`='악몽에서 구해줘서 감사해요. 주위의 모든걸 찢어버리고 싶었어요!', `FemaleText_loc4`='谢谢你把我从那个噩梦中救出来。当时我真想把一切都毁了！', `FemaleText_loc5`='謝謝你讓我從惡夢中醒來。我在夢中獸性大發。', `FemaleText_loc7`='Gracias por salvarme de esa pesadilla. ¡Quería reducirlo todo a cenizas!' WHERE `ID`=69338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 왜 그랬는지 모르겠군요. 정신을 차리게 해줘서 고맙습니다.', `MaleText_loc4`='我不知道我刚才怎么了。谢谢你让我变得清醒。', `MaleText_loc5`='我不知道自己為什麼會這樣。謝謝你讓我清醒過來。', `MaleText_loc7`='No sé qué me ha pasado. Gracias por despejarme la cabeza.', `FemaleText_loc1`='제가 왜 그랬는지 모르겠어요. 정신을 차리게 해줘서 고마워요.', `FemaleText_loc4`='我不知道我刚才怎么了。谢谢你让我变得清醒。', `FemaleText_loc5`='我不知道自己為什麼會這樣。謝謝你讓我清醒過來。', `FemaleText_loc7`='No sé qué me ha pasado. Gracias por despejarme la cabeza.' WHERE `ID`=69339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 감사합니다. 왕자님께도 빚을 졌군요.', `MaleText_loc4`='感谢你救了我，士兵。也谢谢你，年轻的王子。', `MaleText_loc5`='謝謝你拯救我，勇士。還有你，年輕的王子。', `MaleText_loc7`='Gracias por salvarme, soldado. Y a ti, joven príncipe.', `FemaleText_loc1`='구해주셔서 감사합니다. 왕자님께도 빚을 졌네요.', `FemaleText_loc4`='感谢你救了我，士兵。也谢谢你，年轻的王子。', `FemaleText_loc5`='謝謝你拯救我，勇士。還有你，年輕的王子。', `FemaleText_loc7`='Gracias por salvarme, soldado. Y a ti, joven príncipe.' WHERE `ID`=69340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노를 억누르려 했지만 오히려 제가 굴복했습니다. 고맙습니다.', `MaleText_loc4`='我极力对抗愤怒，但我无法战胜它。太感谢你了。', `MaleText_loc5`='我與憤怒作戰，結果被憤怒吞噬。真的很謝謝你。', `MaleText_loc7`='Luché contra la ira, pero me superó. Te lo agradezco.', `FemaleText_loc1`='분노를 억누르려 했지만 오히려 제가 굴복했어요. 고마워요.', `FemaleText_loc4`='我极力对抗愤怒，但我无法战胜它。太感谢你了。', `FemaleText_loc5`='我與憤怒作戰，結果被憤怒吞噬。真的很謝謝你。', `FemaleText_loc7`='Luché contra la ira, pero me superó. Te lo agradezco.' WHERE `ID`=69341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피아귀가 나타났습니다!', `MaleText_loc4`='血喉来了！', `MaleText_loc5`='破喉來了!', `MaleText_loc7`='¡Ha llegado Buchegore!', `FemaleText_loc1`='피아귀가 나타났습니다!', `FemaleText_loc4`='血喉来了！', `FemaleText_loc5`='破喉來了!', `FemaleText_loc7`='¡Ha llegado Buchegore!' WHERE `ID`=69342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탐사원 모리안이 나타났습니다!', `MaleText_loc4`='研究员莫里安来了！', `MaleText_loc5`='研究員莫里安來了!', `MaleText_loc7`='¡Ha llegado el investigador Morian!', `FemaleText_loc1`='탐사원 모리안이 나타났습니다!', `FemaleText_loc4`='研究员莫里安来了！', `FemaleText_loc5`='研究員莫里安來了!', `FemaleText_loc7`='¡Ha llegado el investigador Morian!' WHERE `ID`=69343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t%s|1이;가; |cFFFF0000검을 장착합니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t%s装备上了他的|cFFFF0000剑|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t%s裝備他的|cFFFF0000劍|r!', `MaleText_loc7`='|TInterfaceIconsinv_sword_2h_mantid_01.blp:20|t¡%s equipa su |cFFFF0000espada|r!' WHERE `ID`=69344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t%s|1이;가; |cFFFF0000폭탄을 거머쥡니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t%s装备上了他的|cFFFF0000炸弹|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_bomb_01.blp:20|t%s裝備他的|cFFFF0000炸彈|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_bomb_01.blp:20|t¡%s equipa sus |cFFFF0000bombas|r!' WHERE `ID`=69345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_knife_1h_mantid_02.blp:20|t%s|1이;가; |cFFFF0000단검을 꺼내듭니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_knife_1h_mantid_02.blp:20|t%s装备上了他的|cFFFF0000匕首|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_knife_1h_mantid_02.blp:20|t%s裝備他的|cFFFF0000匕首|r!', `MaleText_loc7`='|TInterfaceIconsinv_knife_1h_mantid_02.blp:20|t¡%s equipa sus |cFFFF0000dagas|r!' WHERE `ID`=69346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 바쁘다는 걸 모르겠나?', `FemaleText_loc4`='你没看见我正忙着吗？', `FemaleText_loc5`='沒看到我在忙嗎?', `FemaleText_loc7`='¿No ves que estoy ocupada?' WHERE `ID`=69347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는... 너따위를 상대할 시간이 없다. 꺼져라, 이 쓰레기야.', `MaleText_loc4`='我们……还有更重要的事情要做，没空来应付你。滚开，废物。', `MaleText_loc5`='我們有...更重要的事情要辦。走開，廢物。', `MaleText_loc7`='Tenemos asuntos más importantes que atender. Vete, escoria.' WHERE `ID`=69348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일이 벌어질지 모르니 단단히 준비하세요, $n 님. 아군을 무력으로 제압해야 할 수도 있어요.', `MaleText_loc4`='做好心理准备，$n。也许我们不得不把矛头指向我们自己人。', `MaleText_loc5`='做好萬全準備，$n。我們也許得用武力對付自己的同胞。', `MaleText_loc7`='Prepárate para cualquier cosa, $n. Es posible que tengamos que recurrir a la fuerza contra nuestros propios hombres.' WHERE `ID`=69349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기엔 검은 황금이 어마어마하게 묻혀 있었다고! 우리가 할 일이라곤 그저 쓸모없는 나무 좀 베고 성가신 동물들 좀 없애는 것뿐이었지!', `MaleText_loc4`='我们在这地方发现好东西啦，$c！我们只需要把这些没用的树全都砍掉，再赶走那些烦人的动物就可以了！', `MaleText_loc5`='我們找到了此地蘊藏的原油，$c!我們需要做的就是剷除一些沒有用的樹，並殺掉一些討人厭的動物!', `MaleText_loc7`='¡Hemos encontrado oro líquido en este lugar, $c! ¡Y solo hemos tenido que talar unos cuantos árboles inútiles y echar a unos animales molestos!' WHERE `ID`=69350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 네 눈에서 공포를 봤다, 주베카.', `MaleText_loc4`='…… 我在你眼里看到了恐惧，裘碧卡。', `MaleText_loc5`='... 我看出了你眼中的恐懼，裘貝卡。', `MaleText_loc7`='He visto el miedo en tus ojos, Jubeka.' WHERE `ID`=69351;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내게 보여 주려고 했던 게 뭐지...?', `FemaleText_loc4`='你想让我看什么……？', `FemaleText_loc5`='你要給我看的東西是什麼...?', `FemaleText_loc7`='¿Qué querías enseñarme?' WHERE `ID`=69352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굴단은 힘을 차지하려던 과정에서 이 세계를 파괴해 버렸다... 너는 내가 아제로스에 같은 짓을 저지르려는 것은 아닌지 우려하고 있었겠지.', `MaleText_loc4`='古尔丹为了追求力量毁了这个世界……你担心我会对艾泽拉斯做出同样的事情。', `MaleText_loc5`='古爾丹為了追求力量而摧毀了這個世界... 你擔心我會對艾澤拉斯做出同樣的事情。', `MaleText_loc7`='Gul''dan destruyó este mundo con su ansia de poder... Temes que yo haga lo mismo en Azeroth.' WHERE `ID`=69353;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨...? 아냐! 나, 나는... 몰랐어...', `FemaleText_loc4`='什么……？不！我……我不……知道……', `FemaleText_loc5`='啊...?怎麼可能!!我...我不知道...', `FemaleText_loc7`='¿Qué? ¡No! Yo... no tengo... No tengo ni idea...' WHERE `ID`=69354;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아냐! 가까이 오지 마! 넌... 위험해... 난 악마를 소환하는 것만으로 만족하지만, 너는...', `FemaleText_loc4`='不！别过来……！你……你太危险了。我只要召唤召唤恶魔就满足了，可你……', `FemaleText_loc5`='不!不要過來...!你... 你太危險。我只要能召喚惡魔就滿足了，可是你...', `FemaleText_loc7`='¡No! ¡No te acerques! Eres... eres peligroso. Yo me contento con invocar demonios, pero tú...' WHERE `ID`=69355;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 스스로 악마가 되려고 하고 있어!', `FemaleText_loc4`='……你竟然想把自己变成恶魔！', `FemaleText_loc5`='...你竟然想要變成惡魔!', `FemaleText_loc7`='¡Tú pretendes convertirte en uno!' WHERE `ID`=69356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...', `MaleText_loc4`='……', `MaleText_loc5`='...', `MaleText_loc7`='...' WHERE `ID`=69357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마술은 양날의 검이야...', `MaleText_loc4`='恶魔学识就是一把双刃剑……', `MaleText_loc5`='惡魔學識是一把雙刃劍...', `MaleText_loc7`='La demonología es una espada de doble filo...' WHERE `ID`=69358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 외부로부터 우릴 둘러싼 위협과...', `MaleText_loc4`='…… 我们既要面对外部威胁……', `MaleText_loc5`='...我們不僅得面對外在的威脅...', `MaleText_loc7`='... el de las amenazas que nos asaltan desde fuera...' WHERE `ID`=69359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 우리 내부에 도사린 위협.', `MaleText_loc4`='…… 也要克服内心的软弱。', `MaleText_loc5`='...還有來自內在的威脅。', `MaleText_loc7`='... y el de las que nos asaltan desde dentro.' WHERE `ID`=69360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 널 선택한 건 이유가 있어서였다.', `MaleText_loc4`='我选你做我的同伴并非无的放矢。', `MaleText_loc5`='我選擇你當我的夥伴是有原因的。', `MaleText_loc7`='Te elegí como compañera por una razón.' WHERE `ID`=69361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 내가 만약 실패하면, 네가 나를 영원히 소멸시켜 줘.', `MaleText_loc4`='…… 一旦我失败了，我要你把我永远放逐。', `MaleText_loc5`='...萬一我失敗了，我需要你將我永遠放逐。', `MaleText_loc7`='... Si fracaso, debes desterrarme para siempre.' WHERE `ID`=69362;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 그 더러운 이유가 뭐지...?', `FemaleText_loc4`='你究竟有什么邪恶的目的……？', `FemaleText_loc5`='又是基於什麼邪惡的原因才選我呢...?', `FemaleText_loc7`='¿Y qué razón depravada es esa?' WHERE `ID`=69363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸의 수호병, 빙빙 돌려서 헛소리만 늘어놓는 꼴이 정말 지겹구나. 너와 네 동족이 희생의 마법에 이끌리는 이유를 내게 설명해라.', `MaleText_loc4`='我厌倦了你的喋喋不休，末日守卫。告诉我你和你的同类为何如此执迷于献祭法术。', `MaleText_loc5`='末日守衛，我已經受夠了你的胡言亂語和閃爍其辭。給我解釋清楚，為什麼你們會被獻祭魔法吸引。', `MaleText_loc7`='Me canso de tus evasivas, guardia apocalíptico. Explícame por qué los de tu especie se sienten atraídos por la magia de los sacrificios.' WHERE `ID`=69364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 맺은 계약은 너를 위해 싸워 주는 것이지, 군단의 비밀을 알려주는 것이 아니다, 필멸자여.', `MaleText_loc4`='我的契约只让我为你而战，而非向你透漏军团的秘密，凡人。', `MaleText_loc5`='凡人，我的契約是為你作戰，不是為你揭露燃燒軍團的秘密。', `MaleText_loc7`='Mi contrato me obliga a luchar por ti, mortal, no a revelarte los secretos de la Legión.' WHERE `ID`=69365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 장난칠 생각은 하지 마라, 악마!', `MaleText_loc4`='别想欺骗我，恶魔！', `MaleText_loc5`='別想要欺矇我，惡魔!', `MaleText_loc7`='¡No intentes engañarme, demonio!' WHERE `ID`=69366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 동족은 살게라스의 배신보다 훨씬 이전부터 존재했다. 너희는 대체 "무엇"이었나?', `MaleText_loc4`='早在萨格拉斯背叛之前你们就已经存在了。你们究竟是什么？', `MaleText_loc5`='你們這族早在薩格拉斯的背叛之前就已經存在了。你們原來到底是什麼?', `MaleText_loc7`='Tu especie es mucho más antigua que la traición de Sargeras. ¿Qué eran?' WHERE `ID`=69367;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무의미한 질문이야... 그걸 알아서 뭘 하려는 거지, 칸레타드?', `FemaleText_loc4`='这种知识毫无用处……你究竟想要什么，坎雷萨德？', `FemaleText_loc5`='問這個根本沒有用...你到底想幹嘛，坎瑞薩德?', `FemaleText_loc7`='Esa información es inútil... ¿Qué intentas conseguir, Kanrethad?' WHERE `ID`=69368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 빠져 있어! 이 악마는 대답을 할 거다. 지금 당장!', `MaleText_loc4`='这不关你的事！这个恶魔必须回答我，马上！', `MaleText_loc5`='不要吵! ...惡魔，快點回答我!', `MaleText_loc7`='¡NO TE METAS EN ESTO! El demonio me contestará, ¡AHORA!' WHERE `ID`=69369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 질문이군. 내 동족들조차 우리의 기원에 대해서는 관심이 없다. 너는 왜 그런 질문을 하는 거지?', `MaleText_loc4`='多么奇怪的要求。即使是我的同类都很少关心我们的起源。你为什么想知道？', `MaleText_loc5`='真是奇怪的要求。連我們自己都不在乎我們是怎麼來的，你為什麼想知道?', `MaleText_loc7`='Qué petición más extraña. Nuestros orígenes no nos interesan ni a nosotros mismos. ¿Por qué te interesan a ti?' WHERE `ID`=69370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 관심이 없다면 내게 말해 줘도 상관이 없겠지.', `MaleText_loc4`='既然你不关心，那告诉我又有什么关系？', `MaleText_loc5`='既然你都不在乎了，那麼就告訴我又何妨。', `MaleText_loc7`='Si no te interesan, entonces no pasa nada por contármelo.' WHERE `ID`=69371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 살게라스가 우리를 해방시키기 전, 우리는 티탄의 사냥개였다. 비전 마력의 사용을 감시하기 위해 영원히 속박된 노예였지.', `MaleText_loc4`='……在萨格拉斯释放我们之前，我们只是泰坦的走狗，被永远奴役着，监督奥术能量的使用。', `MaleText_loc5`='...在薩格拉斯解放我們之前，我們是泰坦的獵犬，永遠受他們的奴役，負責規範秘法能量的使用。', `MaleText_loc7`='Antes de que Sargeras nos liberara, éramos los sabuesos de los titanes. Éramos esclavos eternos para controlar el uso de la magia Arcana.' WHERE `ID`=69372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희생의 마법은 절대적인 금기였기 때문에, 우리는 그런... 달콤한 주문에 빠져든 자를 즉시 처단하도록 만들어졌다.', `MaleText_loc4`='献祭法术在当时被视作是对生命最严重的亵渎，任何想要深入研究这种……美妙的法术的生物，都会立即受到惩罚。', `MaleText_loc5`='獻祭魔法是違逆生命倫理最嚴重的罪，我們能立刻感應到，然後嚴懲擅用這類...甜美魔法的人。', `MaleText_loc7`='La magia de los sacrificios se consideraba la mayor violación de la vida, así que nos armonizaron para castigar inmediatamente a todos aquellos que practicaran una hechicería tan... deliciosa.' WHERE `ID`=69373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 네가 그렇게 궁금해 하던 비밀이다, 칸레타드. 자, 이제는 내가 네게 묻겠다... 왜 거기에 관심이 있는가?', `MaleText_loc4`='你也有你的小秘密，坎雷萨德。现在，我必须要问你……你为什么在意这些？', `MaleText_loc5`='我已經把這個小秘密告訴你了，坎瑞薩德。好，換我來問你...你知道這個要幹嘛?', `MaleText_loc7`='Ya tienes tu estúpido secreto, Kanrethad. Ahora yo te pido información a ti... ¿Por qué te interesa?' WHERE `ID`=69374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 질문에 답하는 건 우리가 맺은 계약의 조항이 아니다. 이 대화는 끝났다.', `MaleText_loc4`='我想我们的契约里不包括这个。到此为止吧。', `MaleText_loc5`='這不在我們的契約規範裡。好，事情辦完了。', `MaleText_loc7`='Creo que eso no forma parte de nuestro contrato. Hemos terminado.' WHERE `ID`=69375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주베카, 의식을 끝내.', `MaleText_loc4`='裘碧卡，结束仪式吧。', `MaleText_loc5`='裘貝卡，結束儀式。', `MaleText_loc7`='Jubeka, completa el ritual.' WHERE `ID`=69376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명령을 내려 주십시오, 폐하.', `MaleText_loc4`='有何吩咐，国王陛下？', `MaleText_loc5`='有何吩咐，陛下?', `MaleText_loc7`='¿Qué ordenas, Majestad?', `FemaleText_loc1`='명령을 내려 주세요, 폐하.', `FemaleText_loc4`='有何吩咐，国王陛下？', `FemaleText_loc5`='有何吩咐，陛下?', `FemaleText_loc7`='¿Qué ordenas, Majestad?' WHERE `ID`=69377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나게 되어 반갑다, $n.$b$b즉시 이곳 야영지와 인근에서 일꾼들을 동원하라. 그들과 함께 방어선을 구축하고 덫을 설치해서, 그 어떤 호드도 우리 손아귀에서 벗어나지 못하게 하라.$b$b한 가지 더. 이곳의 작업자들은 전투 훈련을 받지 않았으니, 이번 작전이 성공하려면 이들을 보호하는 것이 최우선 과제다.$b$b이제 가라. 서둘러야 한다. 시간이 없다!', `MaleText_loc4`='很高兴再见到你，$n。$b$b带上这些劳工，召集你在这片区域能找到的所有人手，帮助他们建立防御工事，确保没有任何部落人员能够逃脱我们的复仇。$b$b另外，这些劳工没有受过作战训练，你要保护他们抵达。$b$b现在，快点动身吧。时间不多了！', `MaleText_loc5`='很高興又見到你，$n。$b$b帶領營地的勞工，以及這個地區所能找到的每個人。協助他們建造防禦工事，確保將部落一網打盡。$b$b還有一件事。這些部隊沒有經過戰事訓練，必須保護他們不受傷害才能成功。$b$b去吧，動作快。時間緊迫!', `MaleText_loc7`='Me alegro de volver a verte, $n.$b$bLlévate a los obreros de este campamento y a todos los que encuentres en los alrededores. Ayúdales a construir defensas para que la Horda no huya de nuestra venganza.$b$bUna cosa más. No están entrenados para el combate, así que tendrás que protegerlos para que tengan éxito.$b$bAhora ve y date prisa. ¡Se nos acaba el tiempo!' WHERE `ID`=69378;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='꽤나 기이한 생물이군. 불타는 군단은 이미 떠났는데 왜 아직까지 남아 있는 거지?', `FemaleText_loc4`='多么奇怪的生物。燃烧军团都离开了，它们为什么还一直留在这里？', `FemaleText_loc5`='真是奇特的生物。燃燒軍團早已離開了，他們為何還久留於此呢?', `FemaleText_loc7`='Qué criaturas más extrañas. ¿Por qué se quedan tanto tiempo después de que haya partido la Legión?' WHERE `ID`=69379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그 말의 전제에는 약간 오류가 있군.', `MaleText_loc4`='……那种说法有个小漏洞。', `MaleText_loc5`='...這個推論有個小瑕疵。', `MaleText_loc7`='Hay un ligero error en esa suposición.' WHERE `ID`=69380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감시자들은 일리단을 섬겼다... 불타는 군단이 아니라.', `MaleText_loc4`='眼魔曾是伊利丹的仆从……而非燃烧军团。', `MaleText_loc5`='「觀察者」服侍的是伊利丹... 而非燃燒軍團。', `MaleText_loc7`='Los observadores estaban al servicio de Illidan, no de la Legión.' WHERE `ID`=69381;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래?', `FemaleText_loc4`='哦？', `FemaleText_loc5`='哦?', `FemaleText_loc7`='Ah.' WHERE `ID`=69382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 일리단도 사라졌잖아... 이들은 왜 아직까지 남아 있는 거지?', `FemaleText_loc4`='好吧，可他也死了……它们为什么还留在这里？', `FemaleText_loc5`='好吧，但是他也已經死了...  它們為什麼還在?', `FemaleText_loc7`='Bueno, él también ha desaparecido... ¿por qué siguen aquí?' WHERE `ID`=69383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 어떻게 알겠어?', `MaleText_loc4`='我怎么知道？', `MaleText_loc5`='你問我，我問誰?', `MaleText_loc7`='¿Y yo qué sé?' WHERE `ID`=69384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='글쎄, 난 몇 주 동안이나 저것들을 소환하는 방법을 알아내느라고 고생했어. 혹시 내가 모르는 뭔가를 알고 있다면, 이 "열등한" 필멸자에게도 가르쳐 줬으면 좋겠는데.', `FemaleText_loc4`='好吧，我花了几个星期的时间，想要弄明白怎么召唤这些家伙。如果你知道什么诀窍又愿意跟我们这些“下等”凡人分享的话，我会十分感激的。', `FemaleText_loc5`='我已經實驗了好幾個禮拜，苦思該如何召喚一隻這個東西出來。要是你曉得什麼我不知道的東西，麻煩請跟我們這些「次等」的凡人分享，我會很感謝你。', `FemaleText_loc7`='Bueno, llevo semanas intentando aprender a invocar uno de esos bichos. Si sabes algo que yo no sé, te agradecería que lo compartieras con los meros mortales.' WHERE `ID`=69385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐가 문제지? 지옥 임프와 공허군주를 구속시키는 것은 그렇게 능숙하게 해냈으면서?', `MaleText_loc4`='怎么了？你束缚邪能小鬼和虚空领主时可是游刃有余啊。', `MaleText_loc5`='問題出在哪裡?我看你輕而易舉就制服了魔化小鬼和虛無領主。', `MaleText_loc7`='¿Cuál es problema? Has podido subyugar a los diablillos viles y a los señores del vacío sin esfuerzo.' WHERE `ID`=69386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 녀석에 비교하면 그것들은 식은 죽 먹기였어! 이건 도무지 한 곳에 가만히 있지 않더라고.', `FemaleText_loc4`='相比之下，它们根本不算什么！它们根本就不是一个档次的。', `FemaleText_loc5`='它們根本不能比啊!完全是不同層次的東西。', `FemaleText_loc7`='¡Esos no eran nada en comparación! Estos nunca están en el mismo sitio.' WHERE `ID`=69387;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것들은... 뭔가 이상해... 어딘가 어울리지 않는 점이 있어...', `FemaleText_loc4`='它们有点……奇怪……有些不对劲……', `FemaleText_loc5`='等等，它們有點...有點奇怪...有點不太對勁...', `FemaleText_loc7`='Tienen algo... raro... Algo fuera de lugar...' WHERE `ID`=69388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 이런...', `FemaleText_loc4`='噢，天呐……', `FemaleText_loc5`='哦，糟了...', `FemaleText_loc7`='Oh, no...' WHERE `ID`=69389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 엘프 놈들이 몰려온다!', `MaleText_loc4`='又有精灵来送死了！', `MaleText_loc5`='有更多精靈可以屠殺!', `MaleText_loc7`='¡Más elfos que asesinar!' WHERE `ID`=69390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 목숨은 호드의 것이오!', `MaleText_loc4`='誓死效忠部落！', `MaleText_loc5`='我的生命獻給部落!', `MaleText_loc7`='¡Mi vida por la Horda!' WHERE `ID`=69391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 차리라고. 양철 갑옷 병사들이 더 온다!', `MaleText_loc4`='当心，伙计们。又有铁皮人过来了！', `MaleText_loc5`='嘿，注意，有人過來了!', `MaleText_loc7`='Alerta, muchachos. ¡Vienen más hombres de hojalata!' WHERE `ID`=69392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 여기 기름이 있어. 그리고 우린 기름이 필요하다고!', `MaleText_loc4`='这儿有不少油，好吧，我们会用到的！', `MaleText_loc5`='這裡有充足的油，而且我們會需要用到!', `MaleText_loc7`='Aquí hay combustible, ¡y lo vamos a necesitar!' WHERE `ID`=69393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아그라, 오래는 안 걸릴 거요. 검은창 부족은 강하오. 내 도움이 그렇게 절실하지는 않을 거요.', `MaleText_loc4`='阿格娜，我不会离开很久的。暗矛氏族的人民都很坚强，也许他们并不需要我太多的帮助。', `MaleText_loc5`='阿格拉，我不會離開太久的。暗矛食人妖都很堅強，說不定根本不需要我伸出援手。', `MaleText_loc7`='Aggra, no tardaré. Los Lanza Negra son gente fuerte, y no creo que mi presencia les haga mucha falta.' WHERE `ID`=69394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙소, 내 사랑. 어서 가세, 친구여. 검은창 부족의 도시로 향해야 하네.', `MaleText_loc4`='好吧，亲爱的。来吧，朋友，我们一同前往暗矛部族的家园。', `MaleText_loc5`='知道了，親愛的。走吧，朋友，跨上坐騎一同前往暗矛部族的家園吧。', `MaleText_loc7`='Muy bien, mi amor. Vamos, $gamigo:amiga;, dirijámonos hasta el hogar de los Lanza Negra.' WHERE `ID`=69396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $g젊은이:아가씨;. 우리가 뭘 해주면 되겠나?', `MaleText_loc4`='嘿，$g小伙子:小姑娘;。有什么能为你效劳的？', `MaleText_loc5`='喂，$g小夥子:姑娘;。有什麼地方能為你效勞?', `MaleText_loc7`='Hola, $gmozo:moza;. ¿Qué puedo hacer por ti?' WHERE `ID`=69397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞장서십시오, 친구. 방어선을 구축할 시간입니다!', `MaleText_loc4`='带头干吧，朋友。该建造你们的防御工事了！', `MaleText_loc5`='出發吧，朋友。著手建造防禦工事!', `MaleText_loc7`='Muestra el camino, colega. ¡Es hora de levantar las defensas!', `FemaleText_loc1`='앞장서세요, 친구. 방어선을 구축할 시간이에요!', `FemaleText_loc4`='带头干吧，朋友。该建造你们的防御工事了！', `FemaleText_loc5`='出發吧，朋友。著手建造防禦工事!', `FemaleText_loc7`='Muestra el camino, colega. ¡Es hora de levantar las defensas!' WHERE `ID`=69398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 탈것에 올라타! 맥주 값을 벌 시간이다!', `MaleText_loc4`='上坐骑，伙计们！不干活可挣不到啤酒。', `MaleText_loc5`='上坐騎!該出發去賺點酒了。', `MaleText_loc7`='¡Montad, chavales! Hora de ganarnos la cerveza.' WHERE `ID`=69399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 이게 매복이냐! 얼라이언스는 싸우는 것도 멍청하군.', `MaleText_loc4`='一场可笑的小冲突！联盟毫无战斗意志。', `MaleText_loc5`='哈!可悲的戰鬥!聯盟自己都不抱信心了。', `MaleText_loc7`='¡Una escaramuza patética! La Alianza lucha sin convicción.' WHERE `ID`=69400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳을 사수해라, 혈투사. 우리 요새를 세울 장소다. 일꾼들이 곧 도착할 테니, 제대로 일을 시킬 준비를 해라.', `MaleText_loc4`='守住这里，血卫士。我们将在这里建造要塞。劳工将在一小时内到达，注意激励士气。', `MaleText_loc5`='守住，血衛士。這是我們的要塞預定地。苦工將在一小時內抵達，準備督促他們開工。', `MaleText_loc7`='Defiende esta posición, guardia de sangre, aquí construiremos nuestra fortaleza. En una hora llegarán los peones: prepárate para motivarlos.' WHERE `ID`=69401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 네놈을 구하러 온 건 아니다, 고블린. 그래, 연료는 찾았나?', `MaleText_loc4`='我来这里可不是为了救你，地精。发现燃料了没有？', `MaleText_loc5`='我不是來救你的臭皮囊的，哥布林。你到底找到燃料沒?', `MaleText_loc7`='No vine a salvar tu despreciable pellejo, goblin. ¿Encontraste combustible o no?' WHERE `ID`=69402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론? 여기에? 가로쉬가 무슨 생각을 하는거지?', `MaleText_loc4`='库卡隆？在这里？加尔鲁什在搞什么鬼？', `MaleText_loc5`='柯爾克隆?出現在這裡?卡爾洛斯是在想什麼?', `MaleText_loc7`='¿Kor''kron? ¿Aquí? ¿Qué ha estado haciendo Garrosh?' WHERE `ID`=69403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 오래 전에 떠났다고 나를 기억 못하는 건가?', `MaleText_loc4`='我有离开这么久吗？你都把我给忘了？', `MaleText_loc5`='我有離開那麼久了嗎?久到連你們都不認識我?', `MaleText_loc7`='¿Tanto tiempo llevo fuera que ya no se acuerdan de mí?' WHERE `ID`=69404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암, 그래야지. 병력을 즉시 보내겠다.', `MaleText_loc4`='你一定会的。我会派步兵来监督。', `MaleText_loc5`='我知道。我會派蠻兵來確認這一點。', `MaleText_loc7`='Sé que la tendremos. Mandaré brutos para que se aseguren de ello.' WHERE `ID`=69405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 직접 절 구하러 오실 줄이야!', `MaleText_loc4`='真没想到，酋长亲自来救我了！', `MaleText_loc5`='我從來沒想到大酋長本人會來救我脫困!', `MaleText_loc7`='¡Jamás pensé que el Jefe de Guerra en persona vendría a rescatarme!' WHERE `ID`=69406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예-옙! 제대로 찾았지요. 해안이 온통 원유 천지예요! 바로 작업에 착수하겠습니다, 대족장님!', `MaleText_loc4`='有，有！发现了很多。海滩上到处都是。我们会立刻着手开采的，酋长大人！', `MaleText_loc5`='有...有有!我們中大獎了。海邊沿岸到處都有原油。我們馬上會派出工作人員開工，大人!', `MaleText_loc7`='¡S-sí, señor! Ha sido un éxito. Hay crudo por toda la costa. ¡Tendremos una operación en marcha en seguida, su enormidad!' WHERE `ID`=69407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이들은 우리 형제들이다! 마치 위험하다는 듯이 경계하는군. 왜지? 대답하라!', `MaleText_loc4`='这些是我们的盟友！你竟然将他们视作威胁？你要给我一个交代！', `MaleText_loc5`='他們都是我們的盟友!而你竟然用這種強橫的手段來威脅他們?為什麼?把話給我說清楚!', `MaleText_loc7`='¡Son nuestros aliados! ¿Por qué los vigilas como si fueran una amenaza? ¡Responderás ante mí!' WHERE `ID`=69408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 출발!', `MaleText_loc4`='我们要出发了！', `MaleText_loc5`='出發了!', `MaleText_loc7`='¡Allá vamos!' WHERE `ID`=69409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<바닥에 누워있는 볼진은 의식을 잃은 채 힘들게 숨을 쉬고 있습니다.>', `MaleText_loc4`='<沃金毫无知觉地躺在地上，奄奄一息。>', `MaleText_loc5`='<沃金躺在地上昏迷不醒，呼吸十分微弱。>', `MaleText_loc7`='<Vol''jin yace en el suelo; está inconsciente y apenas respira.>' WHERE `ID`=69410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동을 할 때 조심해야 하오. 절대로 제이나가 우리를 알아채면 안되오.$b$b준비는 되었소?', `MaleText_loc4`='我们在传送进出的时候一定要小心，绝不能让吉安娜发现。$b$b你做好潜入的准备了吗？', `MaleText_loc5`='傳送進出的人很多，我們一定要非常小心，絕對不能讓珍娜發現。$b$b你準備好了嗎?', `MaleText_loc7`='Tendremos que andar con cuidado con tanto teletransporte. No podemos arriesgarnos a que Jaina nos descubra.$b$b¿Estás $glisto:lista; para entrar?' WHERE `ID`=69411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네.', `MaleText_loc4`='是的。', `MaleText_loc5`='準備好了。', `MaleText_loc7`='Sí.', `FemaleText_loc1`='네.', `FemaleText_loc4`='是的。', `FemaleText_loc5`='準備好了。', `FemaleText_loc7`='Sí.' WHERE `ID`=69412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병들에게서 떨어지시오! 이 주문이 나이트 엘프들의 시야로부터 당신을 가려주겠지만 어느 정도 거리를 두어야 안전하오. 만약 위험에 처하면 이곳으로 도망치시오.', `MaleText_loc4`='远离那些守卫！这个法术可以让你躲过暗夜精灵的视线，可你还是得保持距离。如果你遇到麻烦，就撤回来。', `MaleText_loc5`='離守衛遠一點!這個法術能讓你躲開夜精靈的視線，可是你還是得跟他們保持距離。如果惹上麻煩，便趕緊回到這裡。', `MaleText_loc7`='¡Aléjate de las guardias! Este hechizo te ocultará de ojos de los elfos de la noche, pero aun así deberás mantener las distancias. Si te metes en líos, aquí podrás ponerte a salvo.' WHERE `ID`=69413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 빨리 온 거 아니오?', `MaleText_loc4`='这么快就回来了？', `MaleText_loc5`='這麼快就回來了?', `MaleText_loc7`='¿Ya vuelves?' WHERE `ID`=69414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하시오, $n. 절대 붙잡혀선 안되오.', `MaleText_loc4`='小心点，$n。我们绝对不能被抓住。', `MaleText_loc5`='小心點，$n。我們千萬不能被抓到。', `MaleText_loc7`='Ten cuidado, $n. No podemos permitir que nos descubran.' WHERE `ID`=69415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스로부터 거리를 두시오, $n. 이렇게 적 기지와 가까운 곳에서 붙잡히면 큰일이오.', `MaleText_loc4`='离联盟的家伙远点儿，$n。我们可不能让你在敌境腹地被抓住。', `MaleText_loc5`='離聯盟遠一點，$n。你不能在深入敵境時被抓走。', `MaleText_loc7`='No te acerques a la Alianza, $n. No podemos permitirnos que te capturen en pleno corazón del territorio enemigo.' WHERE `ID`=69416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 이렇게 순간이동을 해대면 제이나가 우리를 곧 찾아낼 거요. 제발 다음 시도에는 조심하길 바라오.', `MaleText_loc4`='如果你胡乱传送，吉安娜会抓住我们的。拜托你，下次再小心点。', `MaleText_loc5`='如果你在這裡傳送，珍娜會發現我們的蹤跡。下次拜託小心一點。', `MaleText_loc7`='Si no dejas de teletransportarte, Jaina nos descubrirá. Ten más cuidado la próxima vez.' WHERE `ID`=69417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종! 역시 당신은 대단하오, $n.', `MaleText_loc4`='圣钟！我就知道你靠得住，$n。', `MaleText_loc5`='聖鐘!我就知道可以信得過你，$n。', `MaleText_loc7`='¡La Campana divina! Sabía que podía contar contigo, $n.' WHERE `ID`=69418;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무슨 소리지?', `FemaleText_loc4`='那是什么声音？', `FemaleText_loc5`='那是什麼聲音?', `FemaleText_loc7`='¿Qué ha sido ese ruido?' WHERE `ID`=69419;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기 누구냐?', `FemaleText_loc4`='外面有人吗？', `FemaleText_loc5`='有人嗎?', `FemaleText_loc7`='¿Hay alguien ahí?' WHERE `ID`=69420;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모습을 보여라!', `FemaleText_loc4`='出来！', `FemaleText_loc5`='出來!', `FemaleText_loc7`='¡Muéstrate!' WHERE `ID`=69421;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음? 방금 뭐였지?', `FemaleText_loc4`='嗯？那是什么？', `FemaleText_loc5`='嗯?那是什麼?', `FemaleText_loc7`='¿Eh? ¿Qué ha sido eso?' WHERE `ID`=69422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진은 먼 옛날 나의 친구였다네. 마지막에 만나고서 오랜 시간이 지났군.', `MaleText_loc4`='沃金是我的朋友，那是很久之前的事了。我们已经认识了很多年了。', `MaleText_loc5`='沃金是我以前認識的朋友，只是我們已經很多年沒有見面了。', `MaleText_loc7`='Vol''jin fue amigo mío, hace mucho tiempo. Han pasado muchos años desde nuestro último encuentro.' WHERE `ID`=69423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님께 무슨 일이 일어난건가요?', `MaleText_loc4`='沃金出什么事了？', `MaleText_loc5`='沃金怎麼了?', `MaleText_loc7`='¿Qué le ha pasado a Vol''jin?', `FemaleText_loc1`='볼진 님께 무슨 일이 일어난건가요?', `FemaleText_loc4`='沃金出什么事了？', `FemaleText_loc5`='沃金怎麼了?', `FemaleText_loc7`='¿Qué le ha pasado a Vol''jin?' WHERE `ID`=69424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 전에 볼진이 해안가에 쓰러져있던걸 보았네.$b$b강한 맹독이 그가 재생하는걸 방해하고 있어. 이건 분명 트롤을 처치하기 위해 제작한 독이네.$b$b내가 짐작하건대 이건 전문적인 암살자의 솜씨네. 그것도 판다리아 출신이 아닌.', `MaleText_loc4`='几天前，沃金被冲上了海滩。$b$b他的血液中有一种毒素阻碍了他的再生机能。这种毒素一定是专门用来对付巨魔的。$b$b要我说的话，这个伤口一定出自刺客之手。而且是来自潘达利亚之外的刺客。', `MaleText_loc5`='幾天前，有人在一口井裡發現了沃金。$b$b他的血液裡有一種毒素，阻斷了他的再生能力。這是專門用來殺食人妖的毒。$b$b我大膽猜測，這應該是被刺客暗殺造成的，而且下手的人絕非來自潘達利亞。', `MaleText_loc7`='El cuerpo de Vol''jin apareció en un pozo hace unos días.$b$bPor sus venas corre un veneno que le impide regenerarse. Es un veneno diseñado para matar a un trol.$b$bSi quieres mi opinión, diría que su herida fue asestada por un asesino. Un asesino que no proviene de Pandaria.' WHERE `ID`=69425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정지! 이곳에는 계엄령이 선포되었다. 신분을 밝혀라.', `MaleText_loc4`='站住！这座城市已经戒严。表明你们的身份。', `MaleText_loc5`='站住!這裡已經戒嚴了。說!你們是誰!', `MaleText_loc7`='¡Alto! En esta ciudad gobierna la ley marcial. Identifíquense.' WHERE `ID`=69426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다! 배를 멈춰라.', `MaleText_loc4`='这里！把船停下。', `MaleText_loc5`='停!把船停在這。', `MaleText_loc7`='¡Aquí! ¡Que los barcos atraquen aquí!' WHERE `ID`=69427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬은 요새를 건설하기에 최적의 환경이군. 로클라! 일꾼들이 도착하면 나무를 다 베어버리고 항구를 건설해라.', `MaleText_loc4`='这个岛很适合充当海防要塞。罗克拉！等劳工一到，就把这些树砍了，开始建造码头。', `MaleText_loc5`='這座小島是完美的沿海據點。羅可菈!等那些苦工來了以後，把這些樹清乾淨然後開始碼頭的建築工程。', `MaleText_loc7`='Esta isla será un baluarte costero perfecto. ¡Rokla! Cuando lleguen los peones, talen esos árboles y empiecen a construir los muelles.' WHERE `ID`=69428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사, 넌 한동안 여기 있었으니, 이 땅에 대해 잘 알겠지. 따라와라.', `MaleText_loc4`='勇士，你已经来了很久，很了解这里。跟我来。', `MaleText_loc5`='勇士，你來了這麼多個星期了，對這片土地應該很熟悉。跟我來。', `MaleText_loc7`='Tú, llevas muchas semanas aquí y conoces bien esta tierra. Ven conmigo.' WHERE `ID`=69429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주위의 경비병에게 도움을 요청합니다!', `MaleText_loc4`='%s呼唤附近守卫的帮助！', `MaleText_loc5`='%s呼叫附近守衛的援助!', `MaleText_loc7`='¡%s pide ayuda a un guardia cercano!' WHERE `ID`=69430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무엇을 보았는가, 형제여?', `MaleText_loc4`='你看见什么了，兄弟？', `MaleText_loc5`='你看到什麼，兄弟?', `MaleText_loc7`='¿Qué has visto, hermano?' WHERE `ID`=69431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 너희를 환영하지 않는다, 흑마법사.', `MaleText_loc4`='这里不欢迎你们，术士。', `MaleText_loc5`='這裡不歡迎你們，術士。', `MaleText_loc7`='Tu especie no es bienvenida aquí, $gbrujo:bruja;.' WHERE `ID`=69432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사원은 잿빛혓바닥 결사단의 영토다. 떠나줘야겠어, 지금 당장.', `MaleText_loc4`='这座神殿属于灰舌兄弟会。我要求你立刻离开。', `MaleText_loc5`='這座神廟是灰舌誓言者的地方，請你「立刻」離開。', `MaleText_loc7`='Este templo es el dominio de la Hermandad Lengua de Ceniza. Debo pedirte que te vayas... inmediatamente.' WHERE `ID`=69433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 흑마법사인가? 지난번에 있었던 일을 생각하면, 지금 당장 널 죽여버리지 않는 걸 고맙게 여겨야 할 거다.', `MaleText_loc4`='又是一个术士？自从上次那件事之后，你真该庆幸我没有立刻杀你。', `MaleText_loc5`='又來了個術士?自從上次的事件之後，你應該很高興我們沒有立刻殺掉你。', `MaleText_loc7`='¿$gOtro brujo:Otra bruja;? Después de lo sucedido la última vez, deberías alegrarte de que no te matemos al instante.' WHERE `ID`=69434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 건설 현장이 공격받고 있습니다!', `MaleText_loc4`='矮人建筑营地遭到攻击！', `MaleText_loc5`='矮人建築工地遭受攻擊!', `MaleText_loc7`='¡Están atacando la zona de construcción enana!', `FemaleText_loc1`='드워프 건설 현장이 공격받고 있습니다!', `FemaleText_loc4`='矮人建筑营地遭到攻击！', `FemaleText_loc5`='矮人建築工地遭受攻擊!', `FemaleText_loc7`='¡Están atacando la zona de construcción enana!' WHERE `ID`=69435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 잠시 이야기 나눌 시간이 있나? 단둘이...?', `MaleText_loc4`='这位勇士，我能和你…… 私下谈谈吗？', `MaleText_loc5`='勇士，我能私底下跟你說句話嗎...?', `MaleText_loc7`='¿Puedo hablar contigo... en privado?' WHERE `ID`=69436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 호드의 영웅이오. 노스렌드에서, 그리고 대격변의 시기에 그대가 보여준 공적은 전설 그 자체요. 난 그래서 그대의 생각을 믿소.', `MaleText_loc4`='你是部落的英雄。你在诺森德和大灾变中的事迹堪称传奇。因此，我相信你的判断力。', `MaleText_loc5`='你是部落的英雄，你在北裂境和大災變期間的事跡已成傳奇。就因為這樣，我相信你的決定。', `MaleText_loc7`='Eres un héroe de la Horda. Tus hazañas en Rasganorte y durante el Cataclismo son legendarias. Por ese motivo confío en tu discreción.' WHERE `ID`=69437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 순찰자지, 정치가가 아니오. 하지만 내가 좋든 싫든 지도자가 됐다오.', `MaleText_loc4`='我是个游侠，而非政客。可无论如何，领袖的重担已落在我的肩头。', `MaleText_loc5`='我是遊俠，不是政客。但無論喜不喜歡，帶領人民的重責大任最後還是落在我的肩膀上。', `MaleText_loc7`='Soy un forestal, no un político. Pero me guste o no, el manto del liderazgo ha recaído sobre mis hombros.' WHERE `ID`=69438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숱한 난관과 배신으로 고통받아온 내 백성들은, 내가 그들의 미래를 지켜주기를 바란다오.', `MaleText_loc4`='我的人民，经历了太多的挑战与背叛，希望我能保证他们的未来。', `MaleText_loc5`='我的人民已經受過太多苦難的折磨與背叛，期盼我幫他們尋求一個穩定的未來。', `MaleText_loc7`='Mi gente, que ha sufrido tantas traiciones y se ha enfrentado a tantos desafíos, confía en mí para asegurar su futuro.' WHERE `ID`=69439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 신도레이는 얼라이언스의 불신에 밀려 어쩔 수 없이 호드 편이 됐소.', `MaleText_loc4`='我们辛多雷是被联盟的偏见与猜忌逼入部落的。', `MaleText_loc5`='我們辛多雷因為聯盟的偏見和懷疑被迫加入部落。', `MaleText_loc7`='La intolerancia y los recelos de la Alianza condujeron a los Sin''dorei a la Horda.' WHERE `ID`=69440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 가로쉬를 보니 그들과 다른 점이 하나도 없어 보이더군. 그는 자신의 목적을 위해 우리를 기꺼이 희생시킬 것이오.', `MaleText_loc4`='而现在，我在部落的酋长身上，看到了同样的歧视。他随意将我们当做炮灰。', `MaleText_loc5`='現在，我只要看到大酋長，就能看到當初相同的歧視。他可以為了自己的目的犧牲我們的生命。', `MaleText_loc7`='Ahora miro a nuestro Jefe de Guerra y empiezo a ver el mismo racismo. No le importa sacrificar nuestras vidas para alcanzar sus fines.' WHERE `ID`=69441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명심하시오. 호드와 내 백성들 간에 이해가 상충하면 내가 가만히 있지 않겠소. 다시 얼라이언스 편에 서는 걸 고려하겠지.', `MaleText_loc4`='记住：我不会坐视部落与血精灵之间的利益冲突。我或许会重新考虑与联盟的关系。', `MaleText_loc5`='你要明白:要是部落的利益會影響到我的人民，我絕不會坐視不管。我也許會考慮回聯盟。', `MaleText_loc7`='Ten claro que no me quedaré de brazos cruzados si los intereses de la Horda se oponen a los de mi pueblo. Podría replantearme viejas alianzas.' WHERE `ID`=69442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 똑바로 뜨고 있으시오. 우린 모두 한 배를 탔으니... 지금은 말이오.', `MaleText_loc4`='睁大眼睛，勇士。我们是同一阵线的……目前是。', `MaleText_loc5`='時刻警惕，勇士。我們暫時...是同一邊的。', `MaleText_loc7`='Mantén los ojos abiertos. Estamos juntos en esto... por ahora.' WHERE `ID`=69443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지는 키린 토를 얼라이언스에 합류시켜달라는 게 아니에요.', `MaleText_loc4`='我父亲并不是要求你带领肯瑞托加入联盟——', `MaleText_loc5`='我父親不是要你叫祈倫托宣誓效忠聯盟 -', `MaleText_loc7`='Mi padre no te pide que el Kirin Tor jure lealtad a la Alianza...' WHERE `ID`=69444;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 폐하가 뭘 바라시는지 잘 알아요. 오, 저기 누가 왔는지 보세요.', `FemaleText_loc4`='安度因，我知道他想要什么。噢，看看谁来了。', `FemaleText_loc5`='安杜因，我完全明白他的指示是什麼。噢 - 看看誰來了。', `FemaleText_loc7`='Anduin, sé exactamente lo que me pide. Oh, mira quién llegó.' WHERE `ID`=69445;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='누구도 저보다 가로쉬를 증오하진 않을 거예요. 전 매일 그 증오와 싸워요.', `FemaleText_loc4`='没人比我更恨加尔鲁什。愤怒每天都折磨着我。', `FemaleText_loc5`='沒人比我更不喜歡卡爾洛斯，我每天都得努力壓抑自己的怒火。', `FemaleText_loc7`='Nadia aborrece a Garrosh tanto como yo. Lucho con mi rabia cada día.' WHERE `ID`=69446;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='함께 가요. 잠시 이 주변을 보시죠.', `FemaleText_loc4`='跟我来——四处看看吧。', `FemaleText_loc5`='跟我來 - 看看這四周。', `FemaleText_loc7`='Ven conmigo, mira a tu alrededor.' WHERE `ID`=69447;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='테라모어 참사 후에 가장 먼저 든 생각은, 오그리마를 궤멸시키는 것이었어요. 어른 아이 안 가리고 모두 죽일 생각이었죠.', `FemaleText_loc4`='塞拉摩陷落以后，我的第一反应就是要血洗奥格瑞玛——把城里的男女老幼全都杀光。', `FemaleText_loc5`='塞拉摩遭到戰火荼毒後，我本能的第一反應是要毀滅奧格瑪 - 殺死所有城裡的老弱婦孺。', `FemaleText_loc7`='Después de lo que pasó en Theramore, mi primer instinto fue arrasar Orgrimmar: matar a todo hombre, mujer y niño de la ciudad.' WHERE `ID`=69448;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부끄럽네요. 그 뒤론 칼렉고스와 권력을 어떻게 사용하느냐에 대해 오랫동안 의논했죠.', `FemaleText_loc4`='我很惭愧。后来，我和卡雷苟斯就力量的使用进行了一次长谈。', `FemaleText_loc5`='我並不引以為榮。從此之後，卡雷苟斯與我討論很多力量，以及該如何使用它的話題。', `FemaleText_loc7`='No me siento orgullosa. Desde entonces, Kalecgos y yo hemos hablado largo y tendido sobre el poder y su uso.' WHERE `ID`=69449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...제이나 이모!', `MaleText_loc4`='……吉安娜！', `MaleText_loc5`='...珍娜!', `MaleText_loc7`='... ¡Jaina!' WHERE `ID`=69450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토엔 그 힘을 악용했던 역사가 있어요. 켈투자드는 비전 마법 지식으로 강령술을 연구했죠.', `FemaleText_loc4`='肯瑞托向来不乏滥用力量之徒。克尔苏加德把魔法知识用在了死灵法术上。', `FemaleText_loc5`='祈倫托素有濫用魔法的惡習。科爾蘇加德利用他的魔法知識去鑽研邪惡的死靈法術。', `FemaleText_loc7`='El Kirin Tor tiene un historial de abuso. Kel''thuzad utilizó su conocimiento de lo arcano para la nigromancia.' WHERE `ID`=69451;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='켈타스도 우리 키린 토 출신이었지만, 우리를 배신했어요.', `FemaleText_loc4`='另一个背叛我们的人，凯尔萨斯·逐日者也曾在这里学习。', `FemaleText_loc5`='凱爾薩斯·逐日者以前也是這裡的學生，而這又是一個自己人背叛我們的例子。', `FemaleText_loc7`='Kael''thas Caminante del Sol también estudió aquí; otro de los nuestros que nos traicionó.' WHERE `ID`=69452;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저하, 호드와 그 주민들은 따로 생각하는 게 중요하다는 걸 누구보다 잘 아실 테죠.', `FemaleText_loc4`='安度因，你比别人更清楚，应该将部落及其人民区别开来。', `FemaleText_loc5`='安杜因，你比任何人都還要了解我，切勿將部落和它的人民混為一談。', `FemaleText_loc7`='Anduin, tú sabes mejor que nadie que no hay que confundir la Horda con su gente.' WHERE `ID`=69453;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항상 저 자신에게 묻곤 해요. "무엇이 옳은 일인가?"', `FemaleText_loc4`='我每天都自问：“什么才是对的？”', `FemaleText_loc5`='我每天都問自己:「到底應該怎麼做才對?」', `FemaleText_loc7`='Me pregunto cada día: "¿Cuál es la acción correcta?"' WHERE `ID`=69454;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버는 아직 이 도시를 움직여요. 얼라이언스와 호드가 달라란에 동참하고 있죠.', `FemaleText_loc4`='夺日者也在这里活动。联盟和部落相互合作。', `FemaleText_loc5`='奪日者仍在這座城裡運作，聯盟和部落繼續通力合作。', `FemaleText_loc7`='Los Atracasol siguen actuando en esta ciudad. La Alianza y la Horda trabajan juntas.' WHERE `ID`=69455;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 전쟁의 물결에 초연한 이상, 희망은 사라지지 않을 거예요.', `FemaleText_loc4`='如果我们穷兵黩武，整个世界的希望就将破灭。', `FemaleText_loc5`='只要我們不直接涉入爭戰，那麼就還有希望拯救世界。', `FemaleText_loc7`='Mientras nos mantengamos por encima de la guerra, habrá esperanza para el mundo entero.' WHERE `ID`=69456;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 우리 도시를 길을 밝히는 불빛으로 본답니다.', `FemaleText_loc4`='我将这座城市视为一盏指路的明灯。', `FemaleText_loc5`='我們這座城就像是黑夜的燈塔，指引著道路。', `FemaleText_loc7`='Veo nuestra ciudad como un faro de luz que muestra el camino.' WHERE `ID`=69457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란에서 호드와 얼라이언스가 서로 믿는다면, 이 세상에도 희망이 있어요.', `FemaleText_loc4`='只有对彼此充满信任，这份希望才能留存。', `FemaleText_loc5`='只要我們能互相信任彼此，那麼世界就還有希望。', `FemaleText_loc7`='Si aquí logramos confiar unos de otros, hay esperanza para el resto del mundo.' WHERE `ID`=69458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 우리 도시를 길을 밝히는 불빛으로 본답니다.', `FemaleText_loc4`='我将这座城市视为一盏指路的明灯。', `FemaleText_loc5`='我們這座城就像是黑夜的燈塔，指引著道路。', `FemaleText_loc7`='Veo nuestra ciudad como un faro de luz que muestra el camino.' WHERE `ID`=69459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란에서 호드와 얼라이언스가 서로 믿는다면, 이 세상에도 희망이 있어요.', `FemaleText_loc4`='只有对彼此充满信任，这份希望才能留存。', `FemaleText_loc5`='只要我們能互相信任彼此，那麼世界就還有希望。', `FemaleText_loc7`='Si aquí logramos confiar unos de otros, hay esperanza para el resto del mundo.' WHERE `ID`=69460;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요, 저하.', `FemaleText_loc4`='谢谢你，安度因。', `FemaleText_loc5`='謝謝你，安杜因。', `FemaleText_loc7`='Gracias, Anduin.' WHERE `ID`=69461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠어요. 아버지와 얘기해 보죠.', `MaleText_loc4`='我明白。我会跟父亲谈的。', `MaleText_loc5`='我明白了。我會跟我父親說的。', `MaleText_loc7`='Lo entiendo. Hablaré con mi padre.' WHERE `ID`=69462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 자신의 운명을 깨닫습니다!', `MaleText_loc4`='%s察觉了它的命运！', `MaleText_loc5`='%s感受到它的命運!', `MaleText_loc7`='¡%s percibe su destino!' WHERE `ID`=69463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 즐거운듯이 달각거리고 위잉거립니다.', `MaleText_loc4`='%s高兴地一边转圈，一边咔嚓作响。', `MaleText_loc5`='%s快樂地大聲運轉著。', `MaleText_loc7`='%s vibra y tintinea feliz.' WHERE `ID`=69464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기쁜 듯 땅에 발을 구릅니다.', `MaleText_loc4`='%s开心地拍打着地面。', `MaleText_loc5`='%s歡欣地咚的一聲到地上。', `MaleText_loc7`='%s cae alegremente al suelo.' WHERE `ID`=69465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 주위를 둘러보며 놀라워합니다.', `MaleText_loc4`='%s以机械式的敬畏好奇地打量着四周。', `MaleText_loc5`='%s對周圍的環境感到非常驚訝。', `MaleText_loc7`='%s admira su entorno con un entusiasmo robótico.' WHERE `ID`=69466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 들뜬 모습으로 철컹거립니다.', `MaleText_loc4`='%s精力充沛地咔咔作响。', `MaleText_loc5`='%s精力充沛地噹啷作響。', `MaleText_loc7`='%s tintinea sugestivamente.' WHERE `ID`=69467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 깃발 상자를 놓았습니다!', `MaleText_loc4`='%s购买了一箱旗帜！', `MaleText_loc5`='%s買了一盒旗幟!', `MaleText_loc7`='%s ha comprado una caja de estandartes.', `FemaleText_loc1`='%s|1이;가; 깃발 상자를 놓았습니다!', `FemaleText_loc4`='%s购买了一箱旗帜！', `FemaleText_loc5`='%s買了一盒旗幟!', `FemaleText_loc7`='%s ha comprado una caja de estandartes.' WHERE `ID`=69468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 비버 상자를 놓았습니다!', `MaleText_loc4`='%s购买了一个土拨鼠笼子！', `MaleText_loc5`='%s買了一箱水貍!', `MaleText_loc7`='%s ha comprado un cajón de roedores.', `FemaleText_loc1`='%s|1이;가; 비버 상자를 놓았습니다!', `FemaleText_loc4`='%s购买了一个土拨鼠笼子！', `FemaleText_loc5`='%s買了一箱水貍!', `FemaleText_loc7`='%s ha comprado un cajón de roedores.' WHERE `ID`=69469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 교란의 돌기둥을 놓았습니다!', `MaleText_loc4`='%s购买了一个欺诈之碑！', `MaleText_loc5`='%s買了一個欺詐尖碑!', `MaleText_loc7`='%s ha comprado un obelisco de engaño.', `FemaleText_loc1`='%s|1이;가; 교란의 돌기둥을 놓았습니다!', `FemaleText_loc4`='%s购买了一个欺诈之碑！', `FemaleText_loc5`='%s買了一個欺詐尖碑!', `FemaleText_loc7`='%s ha comprado un obelisco de engaño.' WHERE `ID`=69470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 마음의 눈 제단을 놓았습니다!', `MaleText_loc4`='%s购买了一个灵视祭坛！', `MaleText_loc5`='%s買了一個心靈幻象祭壇!', `MaleText_loc7`='%s ha comprado un altar de visión mental.', `FemaleText_loc1`='%s|1이;가; 마음의 눈 제단을 놓았습니다!', `FemaleText_loc4`='%s购买了一个灵视祭坛！', `FemaleText_loc5`='%s買了一個心靈幻象祭壇!', `FemaleText_loc7`='%s ha comprado un altar de visión mental.' WHERE `ID`=69471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 조종된 발파로봇 상자를 놓았습니다!', `MaleText_loc4`='%s购买了一盒改写程序的挖掘机器人！', `MaleText_loc5`='%s買了一箱手動操作的挖掘機器人!', `MaleText_loc7`='%s ha comprado una caja de excavabots anulados.', `FemaleText_loc1`='%s|1이;가; 조종된 발파로봇 상자를 놓았습니다!', `FemaleText_loc4`='%s购买了一盒改写程序的挖掘机器人！', `FemaleText_loc5`='%s買了一箱手動操作的挖掘機器人!', `FemaleText_loc7`='%s ha comprado una caja de excavabots anulados.' WHERE `ID`=69472;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늦었네, $n.

본론으로 들어가지. 우리의 마지막 정찰대가 말하길 셰크지르의 군대가 섬의 중심부에 틀어박혀있다고 하네. 현재 그들은 가로쉬 님께서 우리보고 찾아오라고 하신 무기들을 지키고 있어. 문제는 저들이 섬의 방어 시스템을 가동시켰고, 돌파할 수 없는 보호막이 잔베스 전역을 덮고 있다는 거야.

여기서 자네가 필요해. 이 비행포격선에 올라타서 음파 제어탑들을 파괴하게. 저것들이 활성화 되어있는 한 우리의 병력들은 무기고에 한발도 다가서지 못해.', `FemaleText_loc4`='你来晚了，$n。

我们就直奔主题吧。我们最近的侦查表明夏柯希尔的残余部队就躲在这座岛屿的中心。他们守护着一座加尔鲁什下令夺取的大型武器库。问题是他们激活了岛上的防御工事，一座覆盖整个扎尼维斯的大型护盾。

这就是你的任务了。我要你去乘坐一艘炮艇并击毁护盾发生器。只要它们还在运转，我们的部队就无法到达武器库。', `FemaleText_loc5`='你來晚了，$n。

我們直接討論重點吧。最近一次偵查顯示，杉齊爾的最後一批武力躲藏在這座島的中心，看守著一個大型的武器貯藏所，也就是卡爾洛斯下令要我們收回的地方。問題是他們已經啟動這座島的防禦措施，一面巨大的防護盾籠罩著整個贊斐斯。

這就是你派上用場的地方，我要你駕駛一台砲艇，摧毀護盾產生器。要到達武器貯藏所，就務必得摧毀護盾。', `FemaleText_loc7`='Llegas tarde, $n.

Vamos al grano. Nuestros últimos informes indican que las tropas de Shek''zeer que quedan se han atrincherado en el centro de la isla. Protegen un gran alijo de armas que Garrosh nos ha ordenado recuperar. El problema es que han activado las defensas de la isla, un escudo gigantesco e impenetrable que envuelve todo Zan''vess.

Ahí es donde entras tú. Quiero que subas a una de esas naves y dispares a los generadores de escudos. Mientras estén activos, nuestras tropas no podrán alcanzar el alijo de armas.' WHERE `ID`=69473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네, 영웅이여! 자네의 힘에 굴복하겠네.', `MaleText_loc4`='干得好，英雄！我得承认你比我强。', `MaleText_loc5`='做得好，英雄!你的能力讓我萬分佩服。', `MaleText_loc7`='¡Bien hecho! Me rindo ante tu poderío.' WHERE `ID`=69474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자랑스럽게 얻어낸 이 양조주를 맛보게. 이 양조법은 만 년도 넘는 시간 동안 우리 가문에 전해 내려왔지. 원숭이 왕이 무척 즐기던 술이라고 하더군.', `MaleText_loc4`='享受这来之不易的佳酿吧。它的配方在我的家族珍藏了上万年。据说，这酒还特别受到美猴王本人的亲睐。', `MaleText_loc5`='嚐嚐你應得的美酒。這秘方在我的家族流傳了萬年，過去只有美猴王才能享用。', `MaleText_loc7`='Disfruta de este brebaje; te lo has ganado. La receta lleva más de diez mil años en mi familia. Dicen que la disfrutó el mismísimo Rey Mono.' WHERE `ID`=69475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 공격당하고 있다!', `MaleText_loc4`='救命！我被攻击了！', `MaleText_loc5`='幫幫我!我受到攻擊了!', `MaleText_loc7`='¡Socorro! ¡Me atacan!' WHERE `ID`=69476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 정말 중요한 일을 맡은 거야, $p.', `MaleText_loc4`='我们得到一个很适合我们的任务，$p。', `MaleText_loc5`='我們的行動中斷了，$p。', `MaleText_loc7`='Nuestro objetivo está claro, $p.', `FemaleText_loc1`='우리가 정말 중요한 일을 맡은 거예요, $p.', `FemaleText_loc4`='我们得到一个很适合我们的任务，$p。', `FemaleText_loc5`='我們的行動中斷了，$p。', `FemaleText_loc7`='Nuestro objetivo está claro, $p.' WHERE `ID`=69477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬 전체에 있는 음파 제어탑들이 잔베스 중심부를 보호하고 있어. 저걸 파괴하지 못하면 무기고로 가기 어려울거라고.', `MaleText_loc4`='覆盖整个岛屿的护盾生成器保护着扎尼维斯之心，使我们无法抵达武器库。', `MaleText_loc5`='島上的護盾產生器保護著贊斐斯之心，阻擋我們到達武器貯藏所。', `MaleText_loc7`='Unos generadores de escudo situados por toda la isla protegen el centro de Zan''vess, lo que nos impide llegar hasta el alijo de armas.', `FemaleText_loc1`='섬 전체에 있는 음파 제어탑들이 잔베스 중심부를 보호하고 있어요. 저걸 파괴하지 못하면 무기고로 가기 어렵겠네요.', `FemaleText_loc4`='覆盖整个岛屿的护盾生成器保护着扎尼维斯之心，使我们无法抵达武器库。', `FemaleText_loc5`='島上的護盾產生器保護著贊斐斯之心，阻擋我們到達武器貯藏所。', `FemaleText_loc7`='Unos generadores de escudo situados por toda la isla protegen el centro de Zan''vess, lo que nos impide llegar hasta el alijo de armas.' WHERE `ID`=69478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보호막을 깨뜨리지 못하면 우리는 압도당할 거야.', `MaleText_loc4`='如果不能尽快消除这个护盾，我们就会被打垮。', `MaleText_loc5`='如果不趕快摧毀護盾，我們就要完蛋了。', `MaleText_loc7`='Si no desactivamos el escudo pronto, nos superarán.', `FemaleText_loc1`='이 보호막을 깨뜨리지 못하면 우리는 압도당할 거예요.', `FemaleText_loc4`='如果不能尽快消除这个护盾，我们就会被打垮。', `FemaleText_loc5`='如果不趕快摧毀護盾，我們就要完蛋了。', `FemaleText_loc7`='Si no desactivamos el escudo pronto, nos superarán.' WHERE `ID`=69479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함장님, 저들이 이상한 마법진을 가동한 것 같습니다. 섬 전체에서 제어탑들이 빛을 발하기 시작합니다.', `MaleText_loc4`='将军，他们激活了某种力场，岛上的控制塔楼都亮起来了。', `MaleText_loc5`='上將他們已經啟動一種力量力場，島上的控制塔都亮起來了。', `MaleText_loc7`='Almirante, han activado una especie de campo de fuerza. Se acaban de encender las torres de control de toda la isla.', `FemaleText_loc1`='함장님, 저들이 이상한 마법진을 가동한 것 같아요. 섬 전체에서 제어탑들이 빛을 발하기 시작해요.', `FemaleText_loc4`='将军，他们激活了某种力场，岛上的控制塔楼都亮起来了。', `FemaleText_loc5`='上將他們已經啟動一種力量力場，島上的控制塔都亮起來了。', `FemaleText_loc7`='Almirante, han activado una especie de campo de fuerza. Se acaban de encender las torres de control de toda la isla.' WHERE `ID`=69480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빌어먹을 사마귀놈들! 모든 공중 병력은 탑으로 이동하라. 놈들을 쓸어버려!', `MaleText_loc4`='这些该死的螳螂妖！所有空中作战单位，摧毁那些塔楼！', `MaleText_loc5`='那些該死的螳螂人!所有的空中部隊，前往高塔去消滅他們!', `MaleText_loc7`='¡Malditos mántides! A todas las unidades aéreas, ¡derribad esas torres!', `FemaleText_loc1`='빌어먹을 사마귀놈들! 모든 공중 병력은 탑으로 이동하라. 놈들을 쓸어버려!', `FemaleText_loc4`='这些该死的螳螂妖！所有空中作战单位，摧毁那些塔楼！', `FemaleText_loc5`='那些該死的螳螂人!所有的空中部隊，前往高塔去消滅他們!', `FemaleText_loc7`='¡Malditos mántides! A todas las unidades aéreas, ¡derribad esas torres!' WHERE `ID`=69481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작전 개시! 탑들을 파괴하라고!', `MaleText_loc4`='进入作战区域！拿下那些塔楼！', `MaleText_loc5`='我們快要到了!攻下那些高塔!', `MaleText_loc7`='¡Vamos allá! ¡Destruye las torres!', `FemaleText_loc1`='작전 개시! 탑들을 파괴하세요!', `FemaleText_loc4`='进入作战区域！拿下那些塔楼！', `FemaleText_loc5`='我們快要到了!攻下那些高塔!', `FemaleText_loc7`='¡Vamos allá! ¡Destruye las torres!' WHERE `ID`=69482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호박석 폭탄을 조준해. 하나만 제대로 맞춰도 큰 폭발이 일어날 거야!', `MaleText_loc4`='瞄准那些琥珀炸弹。只要点着一个，它们就会产生大爆炸！', `MaleText_loc5`='瞄準那些琥珀炸彈，只要引爆一個便能造成巨大的爆破!', `MaleText_loc7`='Apunta a las bombas de ámbar. Si las detonamos, provocarán una gran explosión.', `FemaleText_loc1`='호박석 폭탄을 조준하세요. 하나만 제대로 맞춰도 큰 폭발이 일어날 거예요!', `FemaleText_loc4`='瞄准那些琥珀炸弹。只要点着一个，它们就会产生大爆炸！', `FemaleText_loc5`='瞄準那些琥珀炸彈，只要引爆一個便能造成巨大的爆破!', `FemaleText_loc7`='Apunta a las bombas de ámbar. Si las detonamos, provocarán una gran explosión.' WHERE `ID`=69483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 쐈어, $p! 계속 폭탄들을 노리라고.', `MaleText_loc4`='打得好，$p！继续瞄准那些炸弹！', `MaleText_loc5`='射得好，$p! 繼續瞄準那些炸彈。', `MaleText_loc7`='¡Buen tiro, $p! Sigue apuntando a las bombas.', `FemaleText_loc1`='잘 쐈어요, $p! 계속 폭탄들을 노리세요.', `FemaleText_loc4`='打得好，$p！继续瞄准那些炸弹！', `FemaleText_loc5`='射得好，$p! 繼續瞄準那些炸彈。', `FemaleText_loc7`='¡Buen tiro, $p! Sigue apuntando a las bombas.' WHERE `ID`=69484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 보호막이 점차 약해지고 있군.', `MaleText_loc4`='干得漂亮！护盾似乎正在削弱。', `MaleText_loc5`='漂亮!護盾似乎變弱了。', `MaleText_loc7`='¡Buen trabajo! Parece que el escudo se está debilitando.', `FemaleText_loc1`='좋았어요! 보호막이 점차 약해지고 있어요.', `FemaleText_loc4`='干得漂亮！护盾似乎正在削弱。', `FemaleText_loc5`='漂亮!護盾似乎變弱了。', `FemaleText_loc7`='¡Buen trabajo! Parece que el escudo se está debilitando.' WHERE `ID`=69485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사마귀들이 탑을 지키고 있군, $p. 저들을 처리하지 못하면 탑에는 흠집도 못 낼 걸세.', `MaleText_loc4`='那些螳螂妖想要保护塔楼，$p。消灭它们，否则我们无法进攻。', `MaleText_loc5`='螳螂人守著這些高塔，$p。趕走他們，否則我們無法開火。', `MaleText_loc7`='Esos mántides protegen las torres, $p. Elimínalos o no podremos disparar a nada.', `FemaleText_loc1`='저 사마귀들이 탑을 지키고 있군, $p. 저들을 처리하지 못하면 탑에는 흠집도 못 낼 걸세.', `FemaleText_loc4`='那些螳螂妖想要保护塔楼，$p。消灭它们，否则我们无法进攻。', `FemaleText_loc5`='螳螂人守著這些高塔，$p。趕走他們，否則我們無法開火。', `FemaleText_loc7`='Esos mántides protegen las torres, $p. Elimínalos o no podremos disparar a nada.' WHERE `ID`=69486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석은 흑마법사들 같으니. 네놈들이 다시 우리 사원에 침입할 줄 알고 있었다...!', `MaleText_loc4`='愚蠢的术士，我就知道你们还在打我们神殿的主意……！', `MaleText_loc5`='愚蠢的術士，我就知道你們一定又會再來掠奪我們的神廟...!', `MaleText_loc7`='¡Estúpidos brujos! Sabía que volverían a intentar saquear nuestro templo...' WHERE `ID`=69487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 자네는 전에 이곳에 몰래 들어왔던 그 흑마법사들 중 하나가 아니군. 그렇다면 여긴 왜 온 건가?', `MaleText_loc4`='等等……你不是上次那些偷偷潜入的术士之一。那你来干什么？', `MaleText_loc5`='等等... 你不是先前偷溜進來的那幾個術士。你們是來幹嘛的?', `MaleText_loc7`='Espera... Tú no eres como los brujos que vinieron aquí antes. ¿Por qué has venido entonces?' WHERE `ID`=69488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... $n이라... 이름이 귀에 익은데.$B$B검은 사원에서 뭘 찾고 있나? 도적처럼 살금살금 돌아다니지 말고, 잠시 이곳에 머물면서 내게 이야기를 하게.', `MaleText_loc4`='嗯……你的名字很耳熟，$n。$B$B你想在黑暗神殿里找到什么？留下跟我谈谈吧，别像个小贼那样鬼鬼祟祟的乱闯。', `MaleText_loc5`='嗯... 你的名字有點耳熟，$n。 $B$B你來黑暗神廟做什麼?好好跟我談一談吧，不要像個偷偷摸摸的盜賊一樣。', `MaleText_loc7`='Hmmm... Tu nombre me suena, $n.$b$b¿Qué quieres del Templo Oscuro? Quédate y habla conmigo, en lugar de escabullirte por ahí como un pícaro.' WHERE `ID`=69489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 대족장님이 최근 이곳에 왔었던 암흑의 수확 의회를 찾고 있습니다.', `MaleText_loc4`='部落酋长加尔鲁什正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。', `MaleText_loc5`='大酋長卡爾洛斯在尋找不久前才闖入此處的黑穫議會成員。', `MaleText_loc7`='El Jefe de Guerra Garrosh busca a los miembros de la Cosecha Oscura que se infiltraron aquí hace poco.', `FemaleText_loc1`='가로쉬 대족장님이 최근 이곳에 왔었던 암흑의 수확 의회를 찾고 있어요.', `FemaleText_loc4`='部落酋长加尔鲁什正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。', `FemaleText_loc5`='大酋長卡爾洛斯在尋找不久前才闖入此處的黑穫議會成員。', `FemaleText_loc7`='El Jefe de Guerra Garrosh busca a los miembros de la Cosecha Oscura que se infiltraron aquí hace poco.' WHERE `ID`=69490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린 국왕님이 최근 이곳에 왔었던 암흑의 수확 의회를 찾고 있습니다.', `MaleText_loc4`='乌瑞恩国王正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。', `MaleText_loc5`='烏瑞恩國王在尋找不久前才闖入此處的黑穫議會成員。', `MaleText_loc7`='El rey Wrynn busca a los miembros de la Cosecha Oscura que se infiltraron aquí hace poco.', `FemaleText_loc1`='린 국왕님이 최근 이곳에 왔었던 암흑의 수확 의회를 찾고 있어요.', `FemaleText_loc4`='乌瑞恩国王正在寻找那些最近擅闯黑暗神殿的黑暗收割议会成员。', `FemaleText_loc5`='烏瑞恩國王在尋找不久前才闖入此處的黑穫議會成員。', `FemaleText_loc7`='El rey Wrynn busca a los miembros de la Cosecha Oscura que se infiltraron aquí hace poco.' WHERE `ID`=69491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스는 내 백성들을 도와 검은 사원을 일리단의 손아귀에서 해방시키는 데 큰 역할을 했었지.$B$B서로를 신뢰하고 있음을 보여주기 위해, 나도 자네를 돕겠네.', `MaleText_loc4`='联盟曾鼎力协助我们从伊利丹手中夺回黑暗神殿。$B$B我愿意帮助你，因为我们彼此信任。', `MaleText_loc5`='聯盟曾經鼎力相助，幫我們把黑暗神廟從伊利丹的手中奪回來。 $B$B為了展現我們共同的信任，我願意幫助你。', `MaleText_loc7`='La Alianza ayudó a mi gente a liberar el Templo Oscuro de las garras de Illidan.$b$bTe ayudaré como gesto de confianza mutua.' WHERE `ID`=69492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네와 얼라이언스는 내 백성들을 도와 검은 사원을 일리단의 손아귀에서 해방시키는 데 큰 역할을 했었지.$B$B서로를 신뢰하고 있음을 보여주기 위해, 그리고 자네에게 진 빚을 갚기 위해 나도 자네를 돕겠네.', `MaleText_loc4`='$n，若非你和其他联盟成员的鼎力相助，我的族人是无法从伊利丹手中夺回黑暗神殿的。$B$B我愿意帮助你，因为我们彼此信任，也因为你帮助过我。', `MaleText_loc5`='$n，你們聯盟曾經鼎力相助，幫我們把黑暗神廟從伊利丹的手中奪回來。 $B$B為了展現我們共同的信任，我願意幫助你。', `MaleText_loc7`='$n, tu Alianza y tú fueron de gran ayuda para mi gente cuando liberamos el Templo Oscuro de garras de Illidan.$b$bTe ayudaré como gesto de confianza mutua y pago de la deuda que tengo pendiente.' WHERE `ID`=69493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 어디로 갔는지 알려주십시오.', `MaleText_loc4`='告诉我他们的去向。', `MaleText_loc5`='告訴我他們去了哪裡。', `MaleText_loc7`='Dime adónde han ido.', `FemaleText_loc1`='그들이 어디로 갔는지 알려주세요.', `FemaleText_loc4`='告诉我他们的去向。', `FemaleText_loc5`='告訴我他們去了哪裡。', `FemaleText_loc7`='Dime adónde han ido.' WHERE `ID`=69494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아카마 님, 앞장서십시오!', `MaleText_loc4`='带路吧，阿卡玛！', `MaleText_loc5`='阿卡瑪，帶路吧!', `MaleText_loc7`='¡Tú primero, Akama!', `FemaleText_loc1`='아카마 님, 앞장서세요!', `FemaleText_loc4`='带路吧，阿卡玛！', `FemaleText_loc5`='阿卡瑪，帶路吧!', `FemaleText_loc7`='¡Tú primero, Akama!' WHERE `ID`=69495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 내 백성들을 도와 검은 사원을 일리단의 손아귀에서 해방시키는 데 큰 역할을 했었지.$B$B서로를 신뢰하고 있음을 보여주기 위해, 나도 자네를 돕겠네.', `MaleText_loc4`='部落曾鼎力协助我们从伊利丹手中夺回黑暗神殿。$B$B我愿意帮助你，因为我们彼此信任。', `MaleText_loc5`='部落曾經大力協助我們把黑暗神廟從伊利丹的手中奪回來。 $B$B為了展現我們共同的信任，我願意幫助你。', `MaleText_loc7`='La Horda ayudó a mi gente a liberar el Templo Oscuro de las garras de Illidan.$b$bTe ayudaré como gesto de confianza mutua.' WHERE `ID`=69496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 자네와 호드는 내 백성들을 도와 검은 사원을 일리단의 손아귀에서 해방시키는 데 큰 역할을 했었지.$B$B서로를 신뢰하고 있음을 보여주기 위해, 그리고 자네에게 진 빚을 갚기 위해 나도 자네를 돕겠네.', `MaleText_loc4`='$n，若非你和其他部落成员的鼎力相助，我的族人是无法从伊利丹手中夺回黑暗神殿的。$B$B我愿意帮助你，因为我们彼此信任，也因为你帮助过我。', `MaleText_loc5`='$n，你們部落曾經大力協助我們把黑暗神廟從伊利丹的手中奪回來。 $B$B為了展現我們共同的信任，我願意幫助你。', `MaleText_loc7`='$n, tu Horda y tú fueron de gran ayuda para mi gente cuando liberamos el Templo Oscuro de garras de Illidan.$b$bTe ayudaré como gesto de confianza mutua y pago de la deuda que tengo pendiente.' WHERE `ID`=69497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 흑마법사 두 명이 사원에 침입한 지도 벌써 여러 달이 지났네... 하지만 아직도 그들이 무엇을 찾고 있었는지 모르겠어.', `MaleText_loc4`='那两个术士是在几个月前闯入神殿的……但我依然无法确定他们到底在找什么。', `MaleText_loc5`='那兩個術士闖入神廟已經是好幾個月前的事情了... 但我還是不清楚他們的目的究竟是什麼。', `MaleText_loc7`='Hace muchos meses que esos dos brujos entraron en el templo... pero aún no sé qué buscaban.' WHERE `ID`=69498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 따라오게. 그들은 길 잃은 영혼의 제단과 사원 정상을 찾아갔었네.', `MaleText_loc4`='跟着我。他们光顾了失落灵魂神殿和神殿之巅。', `MaleText_loc5`='跟我走。他們去了失落靈魂神殿和神廟頂層。', `MaleText_loc7`='Sígueme. Visitaron el Santuario de las Almas Perdidas y la cima del templo.' WHERE `ID`=69499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 일단 이 흑마법사를 믿기로 했다. 사원을 자유롭게 돌아다닐 수 있게 해 줘라.', `MaleText_loc4`='我决定暂时相信这位术士。$g他:她;可以自由出入神殿。', `MaleText_loc5`='我決定暫且相信這位術士，讓$g他:她;在神廟裡自由行動。', `MaleText_loc7`='Por ahora he decidido confiar en $geste brujo:esta bruja;. Dejen que recorra el templo libremente.' WHERE `ID`=69500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마그테리돈과 일리단, 타락한 오크가 이 신성한 장소에 저지른 만행에서 회복하려면 아직도 오랜 시간이 필요하네.', `MaleText_loc4`='要消除玛瑟里顿、伊利丹以及邪兽人对这片圣地所造成的破坏，我们还需要很多年的时间。', `MaleText_loc5`='我們還得花上許多年才能修復瑪瑟里頓、伊利丹，還有那些魔獄獸人對這座神聖的廟宇所造成的傷害。', `MaleText_loc7`='Nos llevará muchos años reparar el daño que Magtheridon, Illidan y los orcos viles causaron en este lugar sagrado.' WHERE `ID`=69501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 안에 길 잃은 영혼의 제단이 있네. 쓰러진 내 형제 수천의 영혼이 이곳에 남아 있지.', `MaleText_loc4`='里面就是失落灵魂神殿。无数死去兄弟们的灵魂还在这里徘徊。', `MaleText_loc5`='這裡是失落靈魂神殿，上千陣亡弟兄們的靈魂都在此處。', `MaleText_loc7`='El Santuario de las Almas Perdidas está en el interior. En esta zona habitan las almas de miles de mis hermanos caídos.' WHERE `ID`=69502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주의하게. 이 안에는 아직도 수많은 함정이 작동하고 있네. 앞으로 나아가기 전에, 자네가 지닌 악마의 주문 중 하나를 사용해서 이 앞을 정찰해 보는 게 좋겠어.', `MaleText_loc4`='当心点，这里仍藏有很多陷阱。也许你的某个恶魔法术能够使你拥有探测前路的能力。', `MaleText_loc5`='請小心，神廟裡依然有許多陷阱尚未解除。在你親自動身之前，或許有什麼惡魔法術可以幫助你先進行偵察。', `MaleText_loc7`='Ten cuidado, ahí dentro aún hay muchas trampas activas. A lo mejor uno de tus demonios tiene un hechizo que pueda permitirte explorar antes de adentrarte.' WHERE `ID`=69503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오랜 세월 동안 이곳에 머물러 있으면서, 조금씩 강해졌군...', `MaleText_loc4`='多年来，它饱受煎熬，慢慢积蓄力量。', `MaleText_loc5`='多年來它被棄置於此，然後力量慢慢增長...', `MaleText_loc7`='Lleva años languideciendo, aumentando lentamente su poder...' WHERE `ID`=69504;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건... 놀랍군... 아무도 손대지 않은 생생한 비전의 힘이라니...', `FemaleText_loc4`='这……太神奇了……一种未被开发原始奥术能量。', `FemaleText_loc5`='這... 太驚人了... 沒有被人汲取過的原始秘法能量泉源。', `FemaleText_loc7`='Es... increíble. ¡Una fuente inexplorada de energía arcana pura!' WHERE `ID`=69505;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 힘을 티끌만큼이라도 사용하면 뭘 소환할 수 있을지 상상해 봐!', `FemaleText_loc4`='想想吧，只要有一小部分这种力量，我们能召唤出什么样的恶魔来啊！', `FemaleText_loc5`='想想看，光是憑藉它一絲絲的力量，我們就能召喚出什麼!', `FemaleText_loc7`='¡Imagina lo que podríamos invocar con solo una parte de este poder!' WHERE `ID`=69506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소환이라고... 하, 이렇게 강한 힘과 융합되면 우리가 무엇이 될 수 있을지를 상상해 보라고...', `MaleText_loc4`='召唤……呵呵，应该想象一下有了这样的力量，我们能够变成什么……', `MaleText_loc5`='召喚... 哈，想想看，如果獲得了如此規模的能量，我們會變成什麼...', `MaleText_loc7`='Invocar... ¡ja! Imagina en lo que nos podríamos convertir si nos fusionáramos con un poder de tal magnitud.' WHERE `ID`=69507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 힘은 아제로스에 있던 예전 영원의 샘과 다르지 않아.', `MaleText_loc4`='这股力量和艾泽拉斯永恒之井最初的那股力量并无二致。', `MaleText_loc5`='這裡蘊含的力量，簡直就像艾澤拉斯原有的永恆之井。', `MaleText_loc7`='El poder de esta sala se parece al primer Pozo de la Eternidad de Azeroth.' WHERE `ID`=69508;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸 이용해서 일리단이 그렇게 많은 악마들을 굴복시킬 수 있었군...', `FemaleText_loc4`='所以，伊利丹就是靠这种办法役使了大量的恶魔……', `FemaleText_loc5`='所以，這就是為什麼伊利丹能夠號令那麼多的惡魔...', `FemaleText_loc7`='Entonces fue así como Illidan vinculó a tantos demonios a su voluntad...' WHERE `ID`=69509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래. 그에게 봉사한 대가로 악마들은 이곳의 힘을 들이켰겠지.', `MaleText_loc4`='是的。作为酬劳，这些恶魔能够啜饮这个地方的能量。', `MaleText_loc5`='是的，而服從於他的惡魔所換得的就是能夠暢飲此處的能量。', `MaleText_loc7`='Sí. El pago por los servicios de los demonios era poder beber de la energía de este lugar.' WHERE `ID`=69510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 힘을 섭취함으로써 악마들은 불타는 군단의 마법에 대한 중독에서 벗어날 수 있었고.', `MaleText_loc4`='在这股能量的滋养下，它们能够摆脱对燃烧军团魔法的依赖。', `MaleText_loc5`='藉由餵食這裡的能量，戒除對軍團魔法的成癮倚賴。', `MaleText_loc7`='Al alimentarse de este poder, pudieron liberarse de su adicción a la magia de la Legión.' WHERE `ID`=69511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단이 블러드 엘프를 태양샘에 대한 중독에서 구하려고 할 때도, 이것을 염두에 뒀을 것 같군... 하지만 어째서인지 블러드 엘프에게는 이 힘을 건네주지 않았어...', `MaleText_loc4`='依我所见，他之所以追寻这股原始能量，是想要利用它来帮助血精灵们摆脱对太阳井的依赖……但由于某些原因，他没有让血精灵接触它……', `MaleText_loc5`='我相信，這正是伊利丹當初打算要供應給血精靈的能量來源，以協助戒除他們對太陽之井的成癮倚賴... 但不知道為什麼，後來他並沒有讓他們靠近它...', `MaleText_loc7`='Creo que esta es la fuente de poder que pretendía ofrecer a los elfos de sangre, para liberarlos de su adicción a La Fuente del Sol, pero por alguna razón no dejaba que se acercaran...' WHERE `ID`=69512;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고?! 아무 증거도 없는 얘기잖아.', `FemaleText_loc4`='什么？？你这种说法毫无根据。', `FemaleText_loc5`='什麼??你這個推論毫無證據可言。', `FemaleText_loc7`='¡¿Qué?! No tienes pruebas de eso.' WHERE `ID`=69513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몰랐나? 일리단의 명령을 따르던 악마들에게는 불타는 군단을 뒤덮었던 타락과 혼돈의 초록색 불길이 보이지 않았지.', `MaleText_loc4`='你难道没有发现吗？伊利丹手下的恶魔并不像燃烧军团那样被熵化，被绿色的魔能腐蚀。', `MaleText_loc5`='你沒注意到嗎?伊利丹旗下的惡魔毫無受到軍團惡魔那種綠色的、不穩定的魔化能量的感染。', `MaleText_loc7`='¿No te habías fijado? Los demonios bajo el dominio de Illidan carecían de la corrupción verde propia de la Legión.' WHERE `ID`=69514;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 왜 갑자기 이렇게 말을 많이 하는 거지, 칸레타드?', `FemaleText_loc4`='……你为什么要说这么多，坎雷萨德？', `FemaleText_loc5`='... 你怎麼話這麼多，坎瑞薩德?', `FemaleText_loc7`='¿Por qué hablas tanto, Kanrethad?' WHERE `ID`=69515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 거기 있었어... 마지막에...', `MaleText_loc4`='在那时……我亲眼目睹了这一切……', `MaleText_loc5`='在伊利丹斃命的那天...我也在場...', `MaleText_loc7`='Yo estaba allí... al final...' WHERE `ID`=69516;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 아, 이런. 또 시시껄렁한 얘기로 날 웃겨 주려는 건 아니겠지?', `FemaleText_loc4`='……噢，拜托，你该不是又要跟我讲你那些恐怖故事了吧？', `FemaleText_loc5`='... 天啊，你不會是又要講你的恐怖故事給我聽了吧?', `FemaleText_loc7`='Oh, no. ¿Me vas a deleitar los oídos con otra de tus horribles historias?' WHERE `ID`=69519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 닥쳐.', `MaleText_loc4`='……闭嘴。', `MaleText_loc5`='...閉嘴。', `MaleText_loc7`='... calla.' WHERE `ID`=69520;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='...', `FemaleText_loc4`='……', `FemaleText_loc5`='...', `FemaleText_loc7`='...' WHERE `ID`=69521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 아래턱이 없을 때가 더 매력적이었던 것 같군.', `MaleText_loc4`='我想我更喜欢变成哑巴的你。', `MaleText_loc5`='我比較喜歡你沒有下巴的時候。', `MaleText_loc7`='Creo que me caías mejor cuando te faltaba la mandíbula.' WHERE `ID`=69522;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 소리 들었어?! 잿빛혓바닥 놈들이 오고 있어. 서둘러 의식을 시작하자고!', `FemaleText_loc4`='你听到了吗？！那些灰舌恶狗要过来了。我们快点开始仪式吧！', `FemaleText_loc5`='你聽見了嗎?!那些灰舌雜碎過來了。動作快，開始進行儀式吧!', `FemaleText_loc7`='¡¿Has oído eso?! Vienen esos perros Lengua de Ceniza. ¡Empecemos el ritual, rápido!' WHERE `ID`=69523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 우리는 수정이 완전히 충전되면 다시 와야겠군.', `MaleText_loc4`='很好。等水晶完全充能完毕，我们再回来。', `MaleText_loc5`='好吧，我們等水晶完全充能後再過來。', `MaleText_loc7`='Muy bien. Volveremos más tarde, cuando el cristal esté totalmente cargado.' WHERE `ID`=69524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 조사에 따르면, 판다렌은 오랜 옛날 천상의 종에 연관된 특별한 망치를 만들었다고해요.', `MaleText_loc4`='根据我的研究，在很久以前，熊猫人专门为这口圣钟制作了一把特别的钟杵。', `MaleText_loc5`='根據我的研究，很久以前熊貓人曾製造出一把聖槌，用來對付聖鐘。', `MaleText_loc7`='Según mi investigación, hace mucho los pandaren crearon una marra especial para usarla con la Campana divina.' WHERE `ID`=69525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종에 그 망치를 사용하면 판다렌 수도사들은 순수한 조화로움을 일깨울 수 있다고 했죠.', `MaleText_loc4`='当熊猫人武僧使用这把钟杵敲响圣钟，就能产生纯净的祥和之力。', `MaleText_loc5`='熊貓人武僧用這把聖槌將聖鐘的魔音化為完美的和絃。', `MaleText_loc7`='Al golpear la Campana divina con la marra, los monjes pandaren eran capaces de crear armonía pura.' WHERE `ID`=69526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 원숭이 왕은 장난 삼아 그 망치를 훔쳐서 어딘가에 숨겼죠. 그 후로 망치에 대한 기록은 어디에도 없어요.', `MaleText_loc4`='不过，有一天美猴王决定偷走这把钟杵，并把它藏了起来。这个恶作剧令钟杵彻底失传了。', `MaleText_loc5`='後來有一天，美猴王惡作劇，偷走這把聖槌將它藏了起來。聖槌從此失去下落。', `MaleText_loc7`='Pero entonces el Rey Mono decidió robar la marra y esconderla, a modo de travesura. Desde entonces no se ha vuelto a saber de ella.' WHERE `ID`=69527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대신 악명높은 "원숭이 왕"이 잠들었다고 여겨지는 곳에 관한 기록은 찾을 수 있었어요.', `MaleText_loc4`='而我发现的，正是这个声名在外的“美猴王”最后的安息之地。', `MaleText_loc5`='不過，我卻發現了美猴王最後的安息之處。', `MaleText_loc7`='Lo que sí encontramos fue el lugar de reposo del conocido "Rey Mono".' WHERE `ID`=69528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 힘은 너 따위의 것이 아니다, 흑마법사!', `MaleText_loc4`='这个地方的力量不容你们亵渎，术士！', `MaleText_loc5`='這裡的能量「不是」給你們用的，術士!', `MaleText_loc7`='¡El poder de este lugar no está destinado a los tuyos, $gbrujo:bruja;!' WHERE `ID`=69529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 곤란한건, 원숭이 왕이 역사가들이 말하는 "비취 전쟁군주"라는 자와 싸우다가 옥으로 변해버렸다고 하는군요.', `MaleText_loc4`='棘手之处在于，他是在和一名史称“青玉战神”的魔古族决斗的时候被困在玉石中的。', `MaleText_loc5`='這件事蹊蹺的地方在於，他是在與歷史上名稱「翠玉督軍」的魔古對鬥時，被封在玉裡頭。', `MaleText_loc7`='El problema era que fue atrapado en jade, en pleno combate contra un mogu que conocemos como "el señor de la guerra de jade".' WHERE `ID`=69530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='死吧！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡MUERE!' WHERE `ID`=69531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 그 둘을 해방시킬 수 있는 주문을 발견했어요. 하지만 아마 둘이 한꺼번에 풀려날 거예요. 제가 이 주문을 시전하면 당신은 비취 전쟁군주가 날뛰기 전에 그를 물리쳐야 해요.', `MaleText_loc4`='我发现了能够释放这两人的法术，注意，是他们两个。一旦我施放法术，你必须在青玉战神回过神来之前击败他。', `MaleText_loc5`='我找到了能將他們從玉中釋放的咒語，可是這樣的話，就連那位魔古也會被放出來。在我施法之後，趁翠玉督軍恢復狀況之前擊敗他。', `MaleText_loc7`='Encontré un encantamiento capaz de liberarlos de su prisión. Pero los liberará a los dos. Cuando lo lance, derrota al señor de la guerra de jade antes de que se recupere.' WHERE `ID`=69532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 천상의 종을 사용해 이 땅에 파괴를 일삼을 거예요. 그를 막을 수 있는 방법을 찾아야 해요.', `MaleText_loc4`='加尔鲁什妄想利用圣钟来霸占这片土地。我们必须想个办法阻止他。', `MaleText_loc5`='卡爾洛斯準備敲響聖鐘，摧毀這片土地。我們得阻止他才行。', `MaleText_loc7`='Garrosh intentará utilizar la Campana divina para sembrar el caos en la tierra. Debemos encontrar la forma de detenerlo.' WHERE `ID`=69533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인, 여기 온 이유가 뭐죠?', `MaleText_loc4`='安度因，我们来这里干什么？', `MaleText_loc5`='安杜因，我們怎麼會在這裡?', `MaleText_loc7`='Anduin, ¿por qué estamos aquí?', `FemaleText_loc1`='안두인, 여기 온 이유가 뭐죠?', `FemaleText_loc4`='安度因，我们来这里干什么？', `FemaleText_loc5`='安杜因，我們怎麼會在這裡?', `FemaleText_loc7`='Anduin, ¿por qué estamos aquí?' WHERE `ID`=69534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 종족 때문에 파멸한 자들의 영혼을 만나 봐라, 흑마법사!', `MaleText_loc4`='无数人因你们这种人的野心而丧命，面对他们的灵魂吧，术士！', `MaleText_loc5`='面對注定滅亡的同儕靈魂，術士!', `MaleText_loc7`='¡Enfréntate a las almas condenadas por los de tu calaña!' WHERE `ID`=69535;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:113134|h[대규모 부활]|h|r을 시전하기 시작합니다!', `FemaleText_loc4`='%s开始施放|cFFFF0000|Hspell:113134|h[群体复活]|h|r！', `FemaleText_loc5`='%s開始施展|cFFFF0000|Hspell:113134|h[群體復活]|h|r!', `FemaleText_loc7`='¡%s empieza a lanzar |cFFFF0000|Hspell:113134|h[Resurrección en masa]|h|r!' WHERE `ID`=69536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 그렇게 악마를 좋아한다면... 마음껏 갖게 해 주마!', `MaleText_loc4`='既然你这么喜欢恶魔……那就尝尝它们的厉害！', `MaleText_loc5`='既然你們這麼愛惡魔... 那就送幾個給你們吧!', `MaleText_loc7`='Si tanto te gustan los demonios... ¡los tendrás todos!' WHERE `ID`=69537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n! 내 부하들이 지하실에 갇혔네. 시간이 없어. 나와 함께 그들을 구출하세!', `MaleText_loc4`='$n！我手下不少人被困在了地下室。时间不多了，帮帮我救出他们吧！', `MaleText_loc5`='$n!我有一些手下被困在地下室 - 沒時間了，幫我去救他們!!', `MaleText_loc7`='¡$n! Algunos de mis hombres están atrapados en el sótano. Queda poco tiempo. ¡Ayúdame a salvarlos!' WHERE `ID`=69538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 강철의 양조주가 얼마나 대단한지 맛보고 싶어서 왔나?', `MaleText_loc4`='啊，有人想知道金铁酒有多带劲儿？', `MaleText_loc5`='喔，看來有人想嚐嚐金屬佳釀的威力?', `MaleText_loc7`='¡Ah, alguien quiere probar la fuerza del brebaje del metal!' WHERE `ID`=69539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸 알아 두게. 이 양조법은 먼 옛날 위대한 원숭이 왕이 직접 우리 가족에게 가르친 것으로, 그 이후 대를 이어 전해 내려왔지.', `MaleText_loc4`='你可得小心了，这配方可是由美猴王传授给我们家族，然后代代相传，流传至今的。', `MaleText_loc5`='注意，這是由美猴王親手傳授給我的祖先，代代相傳的秘方。', `MaleText_loc7`='Te advierto que esta receta se ha transmitido de generación en generación. El mismo Rey Mono se la enseñó a mi familia.' WHERE `ID`=69540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이 술은 친구끼리 격투를 벌인 후에 나눌 용도로 만들어졌다네. 자... 오게, 친구여... 그럴 용기가 있다면 나와 한번 붙어 보지.', `MaleText_loc4`='这种酒的真谛就是要在大战后与好友一起分享。来吧……朋友……如果你敢和我干一架的话。', `MaleText_loc5`='這款酒的滋味是特意要讓朋友們在戰鬥完後一起飲用的。來吧...朋友...有膽的話就跟我打一場。', `MaleText_loc7`='Su sabor está dirigido a los amigos que comparten una jarra tras una batalla. Ven... $gamigo:amiga;... y lucha conmigo si te atreves.' WHERE `ID`=69541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼! 날쌔고 힘세고 위협적이다. 좋아, 너는 한방 먹이는 방법을 잘 알고 있어. 네가 허약한 우낏이라는 생각은 버려도 되겠어.', `MaleText_loc4`='咿！你的招式真是快准狠。很好很好，看来你不是个一无是处的无毛怪。', `MaleText_loc5`='呃!好快、好強、好危險。你知道怎樣戳它，我不怕你可惡怪怪人。', `MaleText_loc7`='¡Aaah! Rapidez, fuerza, peligro. Bien, bien. Tú sabe dar palizas. Yo ya no teme ke tú sea makaku cualkiera.' WHERE `ID`=69542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남은 수수께끼들도 풀어봐, 꼭 그래야 해! 그 후엔 남쪽의 사자의 상륙지에서 봐, 나와 만나야 해.', `MaleText_loc4`='按我的要求解开其他的谜语！然后到南边的雄狮港来找我。', `MaleText_loc5`='解開其他的謎題，我很嚴格的!完成後到雄獅灘南方跟我碰面。', `MaleText_loc7`='Resuelve los acertijos, con tesón, ¡y luego va a verme al Desembarko del León!' WHERE `ID`=69543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='획득 중', `MaleText_loc4`='拾取中', `MaleText_loc5`='撿拾', `MaleText_loc7`='Despojando', `FemaleText_loc1`='획득 중', `FemaleText_loc4`='拾取中', `FemaleText_loc5`='撿拾', `FemaleText_loc7`='Despojando' WHERE `ID`=69544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 야호, $n 님! 저 기억나요? 아, 그래, 좋아요... 저기, 제 얘길 좀 들어보세요... 저 친구를 도와줄 필요는 없어요...', `MaleText_loc4`='……哟，$n！还记得我吗？好的，好的……嘿，听着……我们没必要帮这个家伙……', `MaleText_loc5`='...唷，$n!還記得我嗎?很好，很好... 嘿，聽著... 我們沒必要幫助這個傢伙...', `MaleText_loc7`='¡Buenas, $n! ¿Te acuerdas de mí? Bien, bien... Oye, escucha... No tenemos por qué ayudar a ese tipo.' WHERE `ID`=69547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근처에도 값진 물건이 많을 거예요... 에이, 그러지 마시고... 주인님도 원하고 있잖아요...', `MaleText_loc4`='这地方肯定有不少财宝……得了吧老板，你肯定是想……', `MaleText_loc5`='這裡肯定有些值錢的好料...來吧，你也想這麼做的...', `MaleText_loc7`='Tiene que haber tesoros por este lugar... Vamos, $gjefe:jefa;, sé que te apetece...' WHERE `ID`=69548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 함정 설치가 완료되었습니다!', `MaleText_loc4`='矮人建筑建造完毕！', `MaleText_loc5`='矮人建築完成!', `MaleText_loc7`='¡Construcción enana completada!', `FemaleText_loc1`='드워프 함정 설치가 완료되었습니다!', `FemaleText_loc4`='矮人建筑建造完毕！', `FemaleText_loc5`='矮人建築完成!', `FemaleText_loc7`='¡Construcción enana completada!' WHERE `ID`=69553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 때문에 훌륭한 전사가 죽어버렸다, 애송이 왕자야. 네 목숨으로 갚아라.', `MaleText_loc4`='你害我损失了一个好战士，小王子。你将为此付出代价。', `MaleText_loc5`='你的好管閒事害我損失了一名大將，小王子。用你的性命來償還吧。', `MaleText_loc7`='Tu intromisión me ha costado un gran guerrero, joven Príncipe. Lo pagarás con tu vida.' WHERE `ID`=69558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게는 안 될 걸, 가로쉬.', `MaleText_loc4`='你错了，加尔鲁什。', `MaleText_loc5`='關於這點是你搞錯了，卡爾洛斯。', `MaleText_loc7`='Ahí es donde te equivocas, Garrosh.' WHERE `ID`=69559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 꼬맹아!', `MaleText_loc4`='死吧，小崽子！！', `MaleText_loc5`='去死吧，小鬼!!', `MaleText_loc7`='¡¡Muere, cachorro!!' WHERE `ID`=69560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 천상의 종을 만들어 혼란을 빚으려 했지만, 판다렌은 그 혼란의 메아리를 완벽한 조화로 바꾸는 망치를 만들었지. 그 망치는 수천 년간 숨겨져 있었지만 이젠 아니야!', `MaleText_loc4`='魔古族用圣钟制造混乱，而熊猫人制作了一个特殊的钟杵，能化混乱为祥和。它被埋藏了数千年，直到今天。', `MaleText_loc5`='魔古創造聖鐘是為了要製造混亂，但熊貓人也做出一把特殊的聖槌將聖鐘的魔音化為完美的和絃。那把聖槌千年來都被藏著，直到現在。', `MaleText_loc7`='Los mogu hicieron la Campana divina para provocar el caos, pero los pandaren crearon un mazo especial para transformar los ecos de ese caos en ecos de perfecta armonía. Ese mazo permaneció oculto durante milenios, hasta ahora.' WHERE `ID`=69561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇겐 안 돼, 가로쉬.', `MaleText_loc4`='你休想得逞，加尔鲁什。', `MaleText_loc5`='我不會讓你得逞的，卡爾洛斯。', `MaleText_loc7`='NO te permitiré hacerlo, Garrosh. ¡Rápido, tírame el mazo!' WHERE `ID`=69562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스도 이제 끝물인가 보군, 이런 꼬마를 내게 보내는 걸 보니.', `MaleText_loc4`='你们联盟山穷水尽了吗，居然派孩子来对付我。', `MaleText_loc5`='你們聯盟一定是走投無路了才會派小孩出來對抗我。', `MaleText_loc7`='La Alianza tiene que estar desesperada si ahora envía a niños contra mí.' WHERE `ID`=69563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 살려줄 테니, 계속 저항하면 어떤 대가를 치러야 하는지 국왕에게 전해라!', `MaleText_loc4`='我不杀你，去告诉你的国王，他的挑衅付出了什么代价！', `MaleText_loc5`='我會饒你一命，回去跟你的國王說這就是他不斷挑釁我的代價!', `MaleText_loc7`='¡Te dejaré vivir para que le digas a tu Rey cuál es el precio por desafiarme!' WHERE `ID`=69564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 호드다. 누구도, 그 무엇도 우릴 지배할 수 없다!', `MaleText_loc4`='我们是强大的部落！我们绝不接受奴役！', `MaleText_loc5`='我們就是部落。我們不是任何東西、不是任何人的奴隸!', `MaleText_loc7`='Somos la HORDA. ¡No somos esclavos de nada ni de nadie!' WHERE `ID`=69565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종이 있으면 약한 정신의 찌꺼기를 모두 태워버릴 수 있다. 공포도... 절망도... 증오도... 의심도. 열등한 종족은 감정의 무게에 짓눌리겠지만, 우린 그 힘을 통제할 것이다.', `MaleText_loc4`='有了圣钟，就能根除我们内心的软弱：恐惧……绝望……仇恨……怀疑。低等种族才会被它们压垮。而我们，要掌控它们的力量。', `MaleText_loc5`='有了聖鐘，便可以消除我們所剩的弱點。恐懼...絕望...仇恨...疑惑，只有次等種族會被這些情緒控制，但我們必定可以駕馭它們的力量。', `MaleText_loc7`='Con la Campana divina quemaré cualquier resquicio de miedo que quede en nosotros. Miedo... Desesperación... Odio... Duda. Las razas inferiores quedan aplastadas bajo su peso. Pero NOSOTROS controlaremos su poder.' WHERE `ID`=69566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 함께 얼라이언스를 파괴하고 우리의 정당한 소유물을 차지하자. 승리의 노래가 이제 시작된다.', `MaleText_loc4`='我们将携手摧毁联盟，夺取我们应得的一切。奏响这胜利的战歌吧。', `MaleText_loc5`='讓我們一起消滅聯盟，奪下本該屬於我們的東西。讓我們高唱勝利之歌。', `MaleText_loc7`='Juntos destruiremos a la Alianza y reclamaremos lo que nos pertenece por derecho. Que comience nuestro canto victorioso.' WHERE `ID`=69567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리는 이미 완성됐다. 종이 우리 손에 있으니, 무엇도 우릴 막을 수 없다.', `MaleText_loc4`='我们必将赢得胜利。有了圣钟的力量，我们将无人能挡。', `MaleText_loc5`='勝利近在眉梢。只要有聖鐘的力量支持我們，我們將所向披靡。', `MaleText_loc7`='Nuestra victoria es segura. Con el poder de la Campana de nuestro lado seremos imparables.' WHERE `ID`=69568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 감히 덤빈다면, 모두 땅 속에 파묻어 버려라!', `MaleText_loc4`='如果有人想螳臂当车，我们就碾过他们！', `MaleText_loc5`='若敵人膽敢動手，那我們絕對會送他歸西。', `MaleText_loc7`='¡Si nuestros enemigos oponen resistencia, los aplastaremos!' WHERE `ID`=69569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 네 안의 힘을 느껴라. 공포와 싸워라. 증오를 정복해라!', `MaleText_loc4`='是的！感受这力量吧。战胜恐惧。征服仇恨！', `MaleText_loc5`='沒錯!感受體內的力量。抗拒你的恐懼。征服你的仇恨!', `MaleText_loc7`='¡Sí! Sientan el poder en su interior. Enfréntense a sus miedos. Conquisten su rabia.' WHERE `ID`=69570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 힘의 시험일 뿐이다. 우린 이겨낼 것이다. 지금까지 항상 그랬듯이!', `MaleText_loc4`='这只是考验我们的力量。我们将一如既往地通过这个试炼！', `MaleText_loc5`='這不過是對我們力量的一個考驗。我們將挺過難關，就像以前一樣!', `MaleText_loc7`='Esto no es más que una prueba de fuerza. La superaremos, ¡como lo hemos hecho en el pasado!' WHERE `ID`=69571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰! 가로쉬! 넌 그 종의 힘을 전혀 모르고 있어!', `MaleText_loc4`='住手，加尔鲁什！你不明白那个钟的力量！', `MaleText_loc5`='住手，卡爾洛斯!你不知道聖鐘的威力!', `MaleText_loc7`='¡Detente, Garrosh! ¡No sabes lo que la Campana es capaz de hacer!' WHERE `ID`=69572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하하하... 결국 바리안이 아니라 그 아들놈이 내게 맞선다는 건가. 제 발로 죽음을 향해 달려드는구나, 애송이.', `MaleText_loc4`='啊哈哈……最后来的居然不是瓦里安，而是他的小崽子。你这是送死，小鬼。', `MaleText_loc5`='啊哈哈哈哈...到頭來，面對我的竟然不是瓦里安，而是他的小鬼。勇敢的受死吧，小子。', `MaleText_loc7`='Ajajajaja... Así que al final no es Varian, sino su cachorro el que viene a afrontarme. Te precipitas con coraje hacia tu muerte, joven.' WHERE `ID`=69573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 모든 걸 걸고... 막아주지.', `MaleText_loc4`='我不会让你得逞的。我发誓。', `MaleText_loc5`='我不會讓你這麼做的。我發誓。', `MaleText_loc7`='No te lo permitiré. Lo juro.' WHERE `ID`=69574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 막아 보시지, 인간.', `MaleText_loc4`='那就试试看啊，人类。', `MaleText_loc5`='阻止我啊，人類。', `MaleText_loc7`='Pues detenme, humano.' WHERE `ID`=69575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아악... 아아아아악! 고통이! 샤를 통제할 수 없습니다!', `MaleText_loc4`='啊……啊啊啊！好痛苦！我控制不了了！', `MaleText_loc5`='哦...喔啊啊啊啊啊! 這種痛楚!我無法控制它!', `MaleText_loc7`='¡Aaaaaagh...! ¡Aaaaaaaaaagh! ¡Este dolor! ¡No puedo controlarlo!' WHERE `ID`=69576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤에 저항해라. 극복하고 이용해라!', `MaleText_loc4`='战胜煞魔——控制它！利用它！', `MaleText_loc5`='抗拒煞 - 控制它!利用它!', `MaleText_loc7`='¡Ishi, atacas a los nuestros! ¡Lucha contra el sha! ¡Domínalo! ¡Úsalo!' WHERE `ID`=69577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말입니까, 가로쉬 님? 호드가 전쟁을 또 한 번 견뎌낼 수 있겠습니까?', `MaleText_loc4`='真的吗，加尔鲁什？部落能撑过这场战争吗？', `MaleText_loc5`='你說得是真的嗎，卡爾洛斯?部落真的還能再捱過一場戰爭嗎?', `MaleText_loc7`='¿Es cierto eso, Garrosh? ¿Puede la Horda sobrevivir a otra guerra?' WHERE `ID`=69578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의심은 약한 짓이다! 네 힘을 의심하지 마라. 우리는 반드시 살아남는다! 호드는 영원하다!', `MaleText_loc4`='弱者的猜忌！不要怀疑你的力量，伊什。我们必须撑过去！部落必胜！', `MaleText_loc5`='疑惑是弱者的行為!不要懷疑自己的力量，伊什。我們必須活下去!部落將會獲勝!', `MaleText_loc7`='¡Las dudas son para los débiles! No cuestiones tu fuerza, Ishi. ¡Sobreviviremos porque debemos! ¡La Horda prevalecerá!' WHERE `ID`=69579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 많은 것을 잃었습니다. 가족이 죽고, 친구가 쓰러졌습니다. 고향이 사라졌습니다. 얼마나 더 이런 고통을 견뎌야 합니까?', `MaleText_loc4`='我们失去太多了，酋长。亲人死去，朋友离散，家园破碎。我们还要承受多少苦难？', `MaleText_loc5`='我們已經失去太多了，大酋長。我們流離失所、親人逝去、摯友失散。到底人民還需要受多少罪?', `MaleText_loc7`='Hemos perdido tanto, Jefe de Guerra. Nuestras familias, muertas. Nuestros amigos, perdidos. Nuestro hogar, destruido. ¿Cuánto más tendremos que sufrir?' WHERE `ID`=69580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통도 이제 끝이다. 이 전쟁에서 이기면, 모두가 번영을 누릴 것이다.', `MaleText_loc4`='苦难结束了。战争胜利后，部落将迎来繁荣兴盛。', `MaleText_loc5`='這些折磨痛楚馬上就要結束了。等到打贏這場戰爭，我們的人民終將光耀萬世。', `MaleText_loc7`='Nuestro sufrimiento llegará a su fin. Cuando ganemos esta guerra, nuestra gente por fin conocerá la prosperidad.' WHERE `ID`=69581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 명예의 노예가 되어야 합니까? 적이 잠자는 틈에 아이들을 모조리 없애버리면 됩니다. 제 칼은 얼라이언스의 피에 굶주렸습니다!', `MaleText_loc4`='既然可以趁敌人沉睡的时候杀死他们的孩子，为何还要顾及荣誉？我的剑在渴望联盟的鲜血！', `MaleText_loc5`='當我們可以趁敵人熟睡時屠殺他們的孩子，為什麼還要成為榮譽的俘虜?我的刀刃渴望嚐到聯盟的鮮血!', `MaleText_loc7`='¿Por qué tenemos que ser esclavos del honor, cuando podríamos masacrar a los hijos de nuestros enemigos mientras duermen? ¡Mi espada ansía sangre de la Alianza!' WHERE `ID`=69582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='증오를 통제해라. 전투와 학살은 다르다. 네 분노를 적에게 돌려라.', `MaleText_loc4`='控制你的仇恨，伊什。杀戮不是谋杀。将你的怒火对准敌人。', `MaleText_loc5`='控制你的仇恨，伊什。殺戮生命是無可避免的，所以把憤怒轉到我們的敵人身上。', `MaleText_loc7`='Controla tu odio, Ishi. Una cosa es matar y otra, asesinar. Dirige tu rabia hacia nuestros enemigos.' WHERE `ID`=69583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밤이 되면, 제가 처치한 모두의 얼굴이 보입니다. 우리 몸이 차갑게 식어 쓰러지면 영혼은 어디로 갑니까? 저는... 죽음이 두렵습니다.', `MaleText_loc4`='每晚，我都梦见手下的亡魂。当我们的身躯变冷，灵魂将去向何方？我…… 我怕死。', `MaleText_loc5`='到了晚上，我看見一張張被我殺害的面孔。在屍體冷硬之後，我們的靈魂又會飄到哪裡去?我害怕...死亡。', `MaleText_loc7`='Por las noches veo las caras de los que he matado. ¿Adónde van nuestros espíritus cuando nuestros cuerpos yacen fríos? Le temo a... la muerte.' WHERE `ID`=69584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포를 이용해라! 적에게 돌려라. 죽음이 찾아오면, 당당히 맞서겠느냐, 패배하고 무릎을 꿇겠느냐?', `MaleText_loc4`='利用这恐惧，伊什！将它留给敌人。当死亡降临，你是想站着面对还是跪着失败？', `MaleText_loc5`='利用你的恐懼，伊什!把它用在你的對手身上。當死亡來臨時，你會勇敢面對它還是屈膝認輸?', `MaleText_loc7`='¡Usa tu miedo, Ishi! Úsalo contra tus enemigos. ¿Cuando llegue la muerte te mantendrás firme o caerás derrotado?' WHERE `ID`=69585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님! 소인은... 실패했습니다.', `MaleText_loc4`='酋长！我……我让你失望了。', `MaleText_loc5`='大酋長!我...我讓你失望了。', `MaleText_loc7`='¡Jefe de Guerra! Te... Te he fallado.' WHERE `ID`=69586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이시. 실망이다.', `MaleText_loc4`='是的，伊什。的确如此。', `MaleText_loc5`='沒錯，伊什。你讓我失望了。', `MaleText_loc7`='Sí, Ishi. Así es.' WHERE `ID`=69587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 유물에 대해 나도 모르는 점이 많다. 의지가 약하면 샤의 힘을 통제할 수 없지만, 나는 극복할 것이다.', `MaleText_loc4`='我对这个神器所知不多。意志薄弱的人才控制不了煞能，但是我一定可以。', `MaleText_loc5`='這件神器還有很多我不知道的秘密。信念薄弱的人無法控制這股煞能，但我將成為它的主宰。', `MaleText_loc7`='Desconozco muchas cosas de este artefacto. Los de voluntad débil no pueden controlar esta energía sha, pero yo SÍ la dominaré.' WHERE `ID`=69589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적어도 인간 왕자는 죽었다. 린 국왕도 이제 저항의 대가를 알게 되었을 거다.', `MaleText_loc4`='至少人类王子死了。这下，瓦里安为他的挑衅付出了代价。', `MaleText_loc5`='至少人類的王子已經死了。烏瑞恩王現在知道這就是他不斷挑釁我的代價。', `MaleText_loc7`='Al menos el Príncipe humano ha muerto. Ahora el rey Wrynn sabrá cuál es el precio por desafiarme.' WHERE `ID`=69590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사라져라. 생각할 게 많다.', `MaleText_loc4`='你走吧。我要好好想想。', `MaleText_loc5`='讓我靜一靜。我還有很多事情要想。', `MaleText_loc7`='Déjame, tengo mucho en que pensar.' WHERE `ID`=69591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상륙 지점을 확보했다. 모든 준비가 끝났어.', `MaleText_loc4`='登陆场安全了。我们可以开始行动了。', `MaleText_loc5`='登陸地點已經安全了。我們已經準備好開始工作。', `MaleText_loc7`='El lugar del desembarco es seguro. Los trabajos pueden comenzar.' WHERE `ID`=69592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사, 이 명예는 네 것이다. 함대에 신호를 보내라.', `MaleText_loc4`='勇士，这份殊荣该归你。给舰队发信号吧。', `MaleText_loc5`='勇士，這份榮耀你當之無愧。向艦隊打出信號。', `MaleText_loc7`='Te has ganado el honor. Da la señal a la flota.' WHERE `ID`=69593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 전초기지를 방어할 경비병을 고용했습니다!', `MaleText_loc4`='%s雇用了保卫岗哨的守卫！', `MaleText_loc5`='%s雇用了守衛來保護哨站!', `MaleText_loc7`='%s ha contratado guardias para proteger la avanzada.', `FemaleText_loc1`='%s|1이;가; 전초기지를 방어할 경비병을 고용했습니다!', `FemaleText_loc4`='%s雇用了保卫岗哨的守卫！', `FemaleText_loc5`='%s雇用了守衛來保護哨站!', `FemaleText_loc7`='%s ha contratado guardias para proteger la avanzada.' WHERE `ID`=69594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 호드의 힘이 이 초라한 땅을 지배령 거점으로 변화시키는 걸 잘 봐라!', `MaleText_loc4`='让我们在实战中看看部落的实力吧，我们要将这里建成统御岗哨！', `MaleText_loc5`='看看部落如何大展身手把這片廢土改造成制霸岬!', `MaleText_loc7`='¡Contempla el poder de la Horda! Mira cómo convertimos este pedazo de tierra en el PUNTO DE DOMINIO!' WHERE `ID`=69595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 알겠나? 내 호드가 하지 못하는 것 따위는 없다. 이건 뭐야?', `MaleText_loc4`='你看到了吗，勇士。我的部落无所不能。这是谁啊？', `MaleText_loc5`='你看到了嗎，勇士?沒有部落做不到的事情。這是怎麼回事?', `MaleText_loc7`='¿Lo ves? Hay pocas cosas que mi Horda no pueda lograr. ¿Qué significa esto?' WHERE `ID`=69596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진. 여기는 왜 왔나? 네 섬에서 개구리하고 입이나 맞출 것이지?', `MaleText_loc4`='沃金。你来干什么？你不是该躲在岛上和青蛙亲嘴吗？', `MaleText_loc5`='沃金。你到這裡幹什麼?你不是應該在你的島上吻青蛙的嗎?', `MaleText_loc7`='Vol’jin. ¿Qué haces aquí? ¿No deberías estar en tu isla besando ranas?' WHERE `ID`=69597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 시야가 좁으니 너희가 아직 그 꼴인 거다. 네 충성심이 부족해서 내가 검은창 부족을 동원하지 않은 거고.', `MaleText_loc4`='正是你的短视令你的人民始终落后。也正是你的不忠令我决定不召唤暗矛部族参战。', `MaleText_loc5`='你們食人妖之所以那麼落後就是因為你缺乏遠見，而我沒召集暗矛參與這場戰役則是因為你不夠忠誠。', `MaleText_loc7`='Tu falta de visión es la razón por la que siguen siendo tan primitivos y tu falta de lealtad es el motivo por el que no convoqué a los Lanza Negra para esta campaña.' WHERE `ID`=69598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그보다, 호드는 여기 왜 온 건가? 여기서까지 전쟁을 일으키다니, 대체 왜지?', `MaleText_loc4`='问题是，我们来干什么？你将战火烧到了别处，我要知道是什么原因。', `MaleText_loc5`='更該問的是，我們在這裡幹嘛?你把戰爭帶到艾澤拉斯的另一個角落，而我想知道為什麼。', `MaleText_loc7`='La pregunta es "¿Qué HACEMOS aquí?" Tú has traído la guerra hasta otro rincón más de Azeroth y quiero saber por qué.' WHERE `ID`=69599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 봐라, 볼진. 이 땅은 자원이 풍부하다. 나무, 돌, 철, 연료에... 노동력까지.', `MaleText_loc4`='看看吧，沃金。这里资源丰富：木材、石料、铁矿、原油。还有人口。', `MaleText_loc5`='沃金，看看你的四周。這片土地的資源豐富:木頭、石材、鐵礦、燃料。還有人材。', `MaleText_loc7`='Mira a tu alrededor, Vol''jin. Esta tierra es rica en recursos: madera, piedra, hierro, combustibles. Y gente.' WHERE `ID`=69600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 우리 힘을 보여주면, 판다렌도 섣불리 얼라이언스와 손을 잡진 못할 거다.', `MaleText_loc4`='在这里展示一下力量，就能让熊猫人对加入联盟产生疑虑。', `MaleText_loc5`='等熊貓人看過部落在這片海岸的實力後，他們就會考慮清楚該不該加入聯盟了。', `MaleText_loc7`='Una demostración de fuerza en estas costas hará que los pandaren lo piensen antes de unirse a la Alianza.' WHERE `ID`=69601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 학살을 해서는 아무도 호드와 손을 잡으려 하지 않을 텐데.', `MaleText_loc4`='这些杀戮只会让别人对加入部落产生疑虑。', `MaleText_loc5`='沒錯，這麼多的鮮血，會讓所有想加入部落的人都考慮清楚。', `MaleText_loc7`='Todo este derramamiento de sangre hará que lo piensen dos veces antes de unirse a la Horda.' WHERE `ID`=69602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 너와 나의 차이다, 볼진. 난 백성들이 굶어 죽는 꼴을 보지는 않겠다. 그 무엇도 나를 막을 수는 없다. 오크와 함께 일어설 용감한 자들에게 미래를 선사하겠다. 여기서 기다려라.', `MaleText_loc4`='这就是我们之间的差别，沃金。我可不会让我的人民在沙漠中饿死。为了让兽人和任何勇于站在我们一边的人拥有辉煌的未来，我会不惜一切——一切！在这儿等着。', `MaleText_loc5`='這就是你跟我的不同之處，沃金。我不會坐視我的人民在沙漠裡餓死。我會不計一切代價 - 任何代價 - 讓獸人和有勇氣站在我身旁的人過上驕傲又光輝的日子。在這裡等著。', `MaleText_loc7`='Esa es la diferencia entre tú y yo, Vol''jin. Yo no dejaré que MI gente se muera de hambre en el desierto. No me detendré ante nada, NADA, para asegurar un futuro digno y glorioso para los orcos y cualquiera que tenga el valor de luchar a nuestro lado. Espera aquí.' WHERE `ID`=69603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에게 너의 가치를 증명해 보여라, 트롤. 이 대륙의 심장부에서 할 일이 있다.', `MaleText_loc4`='你还有点用，巨魔，证明一下你对部落的价值吧。去这片大陆的中心执行个任务。', `MaleText_loc5`='有件事倒是可以交給你去辦，食人妖，來證明你對部落的用處。在這大陸中心地帶的一個任務。', `MaleText_loc7`='Hay algo que puedes hacer para demostrarle a la Horda tu valía, trol. Una misión en el corazón del continente.' WHERE `ID`=69604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 안 돼! 종이!', `FemaleText_loc4`='不，不，不！圣钟！', `FemaleText_loc5`='不、不!聖鐘!', `FemaleText_loc7`='¡No, no, no! ¡La Campana!' WHERE `ID`=69605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내가 다르나서스를 봉쇄했는데! 어설프게 안으로 숨어들려던 도적은 다 잡아들였고! 내 함정을 통해 순간이동하려던 하찮은 놈들도 모조리 잡았단 말이야!', `FemaleText_loc4`='我已经彻底封锁了整个达纳苏斯！我抓住了所有那些试图潜入城市的笨贼和想要靠传送法术躲过陷阱的半吊子法师！', `FemaleText_loc5`='我已經將達納蘇斯封鎖了!企圖偷溜進這座城市的彆腳盜賊通通被我抓住了!妄想傳送逃過陷阱的不入流騙子也都被我一網打盡了!', `FemaleText_loc7`='¡Darnassus estaba completamente SELLADO! ¡A cada pícaro inepto que intentaba colarse en esta ciudad, lo ATRAPABA! ¡Cacé a cada charlatán de dos centavos que intentó superar mis trampas teletransportándose!' WHERE `ID`=69606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 이곳을 통과했을 리가 없어... 이건 내부의 소행이야. 도시 안에 누군가가 종을 가진 거야. 아니면... 설마...', `FemaleText_loc4`='他们不可能通过……这可是内部机密。某个在城里的人带着圣钟，除非……不……', `FemaleText_loc5`='他們絕對不可能通過的...這是內賊幹的好事。城裡有人拿到聖鐘了，除非是...不...', `FemaleText_loc7`='Es imposible que pudieran pasar... Esto viene de adentro. Alguien de esta ciudad tiene la Campana, a menos que... No…' WHERE `ID`=69607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='UNUSED', `FemaleText_loc4`='UNUSED', `FemaleText_loc5`='UNUSED', `FemaleText_loc7`='UNUSED' WHERE `ID`=69608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나와 함께 가자.', `FemaleText_loc4`='跟我来。', `FemaleText_loc5`='跟我來。', `FemaleText_loc7`='Ven conmigo.' WHERE `ID`=69609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문이 달라란으로 이어지는군. 그건 호드가 이런 짓을 하는 걸... 키린 토... 나의 키린 토가... 도와줬다는 뜻이야.', `FemaleText_loc4`='这些传送门通往达拉然。就是说肯瑞托……我的肯瑞托里……有人在助纣为虐。', `FemaleText_loc5`='這些傳送門通往達拉然。這代表祈倫托...我的祈倫托竟然...幫助部落犯下這等暴行。', `FemaleText_loc7`='Estos portales conectan con Dalaran. Eso significa que el Kirin Tor... MI PROPIO Kirin Tor... ayudó a la Horda a cometer esta atrocidad.' WHERE `ID`=69610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='난 또 배신당하진 않겠어! 이 일을 저지른 놈들은 벌을 받을 거야!', `FemaleText_loc4`='我绝不容忍又一次背叛！那些罪人必将受到惩罚！', `FemaleText_loc5`='不!我不會再被背叛了!我一定要嚴懲幕後的主使者!', `FemaleText_loc7`='¡No! ¡No volverán a traicionarme! ¡Los responsables serán castigados!' WHERE `ID`=69611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에이타스 선리버!', `FemaleText_loc4`='艾萨斯·夺日者！', `FemaleText_loc5`='埃薩·奪日者!', `FemaleText_loc7`='¡Aethas Atracasol!' WHERE `ID`=69612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버, 넌 키린 토를 배신했다. 가로쉬가 병력을 움직여 내 도시 안으로 들어오게 내버려뒀지.', `FemaleText_loc4`='你背叛了肯瑞托，夺日者。是你让加尔鲁什的军队进入我的城市。', `FemaleText_loc5`='你背叛了祈倫托，奪日者。你讓卡爾洛斯調動他的部隊穿過我的城市。', `FemaleText_loc7`='Has traicionado al Kirin Tor, Atracasol. Has permitido que Garrosh mueva sus fuerzas por MI ciudad.' WHERE `ID`=69613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 눈감아준 거야. 너와 네 불경한 족속들은 이 도시에서 더는 환영받지 못해.', `FemaleText_loc4`='你都不敢看我。我的城市不再欢迎你和你那些不服管束的同党。', `FemaleText_loc5`='這就是默許。你和你們血精靈已經不受這座城市的歡迎了。', `FemaleText_loc7`='Miraste hacia otro lado. Tú y tu insubordinada especie ya no son bienvenidos en mi ciudad.' WHERE `ID`=69614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주님, 오해이십니다. 제가 그런 게 아닙니다.', `MaleText_loc4`='你搞错了，吉安娜。我没有。', `MaleText_loc5`='你搞錯了，珍娜。我什麼也沒做。', `MaleText_loc7`='Te equivocas, Jaina. No hice nada.' WHERE `ID`=69615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 도시이기도 합니다, 여군주님.', `MaleText_loc4`='它同样属于我们，普罗德摩尔。', `MaleText_loc5`='這也是我們的城市，普勞德摩爾。', `MaleText_loc7`='Esta también es nuestra ciudad, Valiente.' WHERE `ID`=69616;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하! 알겠다. 그렇다면 힘으로 선리버를 제거해 주지.', `FemaleText_loc4`='哈！我明白了。那我就用武力驱逐夺日者。', `FemaleText_loc5`='哈!我懂了。那麼我會強行攆走奪日者。', `FemaleText_loc7`='¡Ah! Ya veo. Entonces tendré que deshacerme de los Atracasol a la fuerza.' WHERE `ID`=69617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에이타스, 넌 나와 함께 가게 될 거야.', `FemaleText_loc4`='你，艾萨斯，跟我走一趟吧。', `FemaleText_loc5`='至於你，埃薩，你得跟我走。', `FemaleText_loc7`='Tú, Aethas, vendrás conmigo.' WHERE `ID`=69618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나! 달라란이 어떻게 된 거요? 공격이 있었소?', `MaleText_loc4`='吉安娜！达拉然出什么事了？被袭击了吗？', `MaleText_loc5`='珍娜!達拉然發生什麼事了?受到攻擊了嗎?', `MaleText_loc7`='¡Jaina! ¿Qué está pasando en Dalaran? ¿Ha habido un ataque?' WHERE `ID`=69619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토 내부에서 배신행위가 있었어요. 제가 알아서 처리했죠.', `FemaleText_loc4`='肯瑞托内部出了叛徒。我已经控制了局势。', `FemaleText_loc5`='祈倫托出了內賊，但是我已經處理好這個問題了。', `FemaleText_loc7`='Al Kirin Tor lo traicionaron desde dentro. Me he ocupado de la situación.' WHERE `ID`=69620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게?', `MaleText_loc4`='怎么会？', `MaleText_loc5`='怎麼處理?', `MaleText_loc7`='¿Cómo?' WHERE `ID`=69621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란에서 호드를 추방했어요. 키린 토가 얼라이언스에 귀속되었으니 이젠 폐하는 원하던 걸 가지셨어요.', `FemaleText_loc4`='我将部落逐出了达拉然。你的目的达到了，陛下：肯瑞托将属于联盟。', `FemaleText_loc5`='我把部落全數趕出達拉然了。您已經達到您的目的，國王陛下:祈倫托是屬於聯盟的。', `FemaleText_loc7`='He expulsado a la Horda de Dalaran. Tiene lo que quería, su Majestad: el Kirin Tor pertenece a la Alianza.' WHERE `ID`=69622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 무슨 말 했는지 알아요. 제 믿음이 잘못된 거였어요.', `FemaleText_loc4`='我记得我说的话。可我信错了人。', `FemaleText_loc5`='我知道我說了什麼。我不該相信他們的。', `FemaleText_loc7`='Sé lo que dije. Hice mal en confiar.' WHERE `ID`=69623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 전엔...', `MaleText_loc4`='可你说——', `MaleText_loc5`='但是你說 -', `MaleText_loc7`='Pero dijiste que...' WHERE `ID`=69624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신도레이, 선리버는 어떻게 된 거요?', `MaleText_loc4`='那些辛多雷——夺日者呢？', `MaleText_loc5`='那麼那些辛多雷 - 奪日者呢?', `MaleText_loc7`='¿Y qué hay de los sin''dorei, de los Atracasol?' WHERE `ID`=69625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='항복한 이들은 보랏빛 요새로 보냈어요. 저항하기로 한 이들의 목숨은 보장할 수 없군요.', `FemaleText_loc4`='投降的人将被送去紫罗兰监狱。而选择对抗的人，我不保证他们的性命。', `FemaleText_loc5`='投降的人會被帶到紫羅蘭堡監獄，至於那些選擇反抗的，下場就很難說了。', `FemaleText_loc7`='A los que se rindieron, nos los llevamos al Bastión Violeta. No me hago responsable de los que eligieron resistirse.' WHERE `ID`=69626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 먼저 얘기를 했어야지.', `MaleText_loc4`='你在行动前应该和我谈谈——', `MaleText_loc5`='珍娜你得在行動前先知會我 -', `MaleText_loc7`='Jaina, deberías hablar conmigo antes de actuar.' WHERE `ID`=69627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토 지휘는 제 소관입니다.', `FemaleText_loc4`='怎么管理肯瑞托是我的事。', `FemaleText_loc5`='該怎麼管理祈倫托是我的事情。', `FemaleText_loc7`='Cómo gobierno el Kirin Tor es asunto mío.' WHERE `ID`=69628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 신도레이와 협상하려던 차였소. 얼라이언스로 끌어들일 생각이었지. 당신의 공격 때문에 그들은 악수를 둘 수밖에 없게 됐소...', `MaleText_loc4`='我一直在与辛多雷谈判。我们正在商讨辛多雷重返联盟的可能性！你在这种时候攻击他们的人，这只会——', `MaleText_loc5`='我本來想要跟辛多雷談判的。我原想透過協商的方式讓他們重回聯盟!但你攻擊他們的人民，這等於是逼他們 -', `MaleText_loc7`='Estaba intentando pactar con los sin''dorei. ¡Estábamos negociando para que se unieran a la Alianza! Al atacar a su gente, no les diste elección.' WHERE `ID`=69629;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들 스스로 선택한 거죠.', `FemaleText_loc4`='那是他们自己选的路。', `FemaleText_loc5`='他們的命運是自己選的。', `FemaleText_loc7`='Eligieron su propio camino.' WHERE `ID`=69630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 다시 호드로 내몬 거요.', `MaleText_loc4`='你把他们又推向了部落。', `MaleText_loc5`='你把他們逼回部落裡去了。', `MaleText_loc7`='Los hiciste retroceder hacia la Horda.' WHERE `ID`=69631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자신을 기만하시는군요. 한 번 호드는 영원한 호드예요. 이제 깨달았죠. 키린 토를 집결시킬 거예요.', `FemaleText_loc4`='这是自欺欺人。一入部落，再难回头。我现在明白了。我正在动员肯瑞托。', `FemaleText_loc5`='別自欺欺人了。一日為部落，終身為部落。我總算看清楚了。我會開始動員祈倫托。', `FemaleText_loc7`='Te estás engañando. El que nace Horda, muere Horda. Ahora lo veo. Voy a movilizar el Kirin Tor.' WHERE `ID`=69632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 뜻을 함께해야 하오. 얼라이언스가 하나가 돼야 하오.', `MaleText_loc4`='吉安娜。我们得合作。联盟必须团结一致。', `MaleText_loc5`='珍娜。我們必須對此達成共識。聯盟得齊心協力團結一致。', `MaleText_loc7`='Jaina. Tenemos que trabajar juntos en esto. La Alianza debe permanecer unida.' WHERE `ID`=69633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안, 약하게 굴지 마세요.', `FemaleText_loc4`='不要劝我了，瓦里安。', `FemaleText_loc5`='瓦里安，別這麼窩囊。', `FemaleText_loc7`='No te me ablandes ahora, Varian.' WHERE `ID`=69634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판도가 바뀌었군.', `MaleText_loc4`='情况有变。', `MaleText_loc5`='局勢已經改變了。', `MaleText_loc7`='Las reglas cambiaron.' WHERE `ID`=69635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 영웅이여. 할 말이 있습니다!', `MaleText_loc4`='勇士，请别走——我们谈谈！', `MaleText_loc5`='勇士，請別走 - 我們得聊聊!', `MaleText_loc7`='Espera, no te vayas... tenemos que hablar.' WHERE `ID`=69636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 안두인을 공격했다고...? 어디 있지?', `MaleText_loc4`='加尔鲁什袭击了我的儿子……？他人呢？', `MaleText_loc5`='卡爾洛斯攻擊我的兒子...?他在哪裡?', `MaleText_loc7`='¿Garrosh atacó a mi hijo…? ¿Dónde está?' WHERE `ID`=69637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안두인!', `FemaleText_loc4`='安度因！', `FemaleText_loc5`='安杜因!', `FemaleText_loc7`='¡Anduin!' WHERE `ID`=69638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인, 무슨 생각이었던 거냐? 널 스톰윈드로 보냈어야 했어!', `MaleText_loc4`='安度因，你到底在想什么？我真该把你送回暴风城！', `MaleText_loc5`='安杜因，你在想什麼?我當初應該把你送回暴風城!', `MaleText_loc7`='Anduin, ¿qué has hecho? ¡Debí enviarlo de vuelta a Ventormenta!' WHERE `ID`=69639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨은 쉬고 있지만, 뼈가 산산조각 났어요.', `MaleText_loc4`='他还活着，可全身的骨头都碎了。', `MaleText_loc5`='他還活著，但是他的骨頭碎了。', `MaleText_loc7`='Sigue vivo, pero sus huesos están destrozados.' WHERE `ID`=69640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벨렌을 불러 와라. 당장!', `MaleText_loc4`='去找维伦，马上带他来！', `MaleText_loc5`='召集費倫!叫他馬上過來!', `MaleText_loc7`='Avísenle a Velen. ¡Que venga de inmediato!' WHERE `ID`=69641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스! 살아 있군.', `MaleText_loc4`='艾萨斯！你还活着。', `MaleText_loc5`='埃薩!你還活著。', `MaleText_loc7`='¡Aethas! Estás vivo.' WHERE `ID`=69642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 영웅 덕분에 몇 명이나마 이곳으로 도망칠 수 있었습니다. 대부분은 보랏빛 요새로 호송되었습니다.', `MaleText_loc4`='多亏这位英雄，我们逃了出来。还有许多人被送去了紫罗兰监狱。', `MaleText_loc5`='多謝這位英雄，我們之中有些人能逃到這裡。但有很多人已經被送到紫羅蘭堡了。', `MaleText_loc7`='Gracias a mi acompañante, algunos de los nuestros lograron escapar. Han enviado a muchos más al Bastión Violeta.' WHERE `ID`=69643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아날라쉬 데날! 달라란이 대체 어떻게 된 건지 누가 좀 말해주겠나?', `MaleText_loc4`='Anar’alash denal！谁来告诉我达拉然怎么了？', `MaleText_loc5`='Anar’alash denal!誰來告訴我達拉然到底發生什麼事?', `MaleText_loc7`='¡Anar''alash denal! ¿Va a explicarme alguien QUÉ está pasando en Dalaran?' WHERE `ID`=69644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나가...! 무모함에 빠져 도시에서 선리버를 축출했습니다! 그녀가 키린 토에서 호드를 추방하고 있습니다!', `MaleText_loc4`='普罗德摩尔！她将夺日者逐出了城市。她要将部落赶出肯瑞托！', `MaleText_loc5`='是普勞德摩爾!她竟然把城內的奪日者都驅逐了，她要把部落從祈倫托趕出去!', `MaleText_loc7`='¡Valiente! Expulsó a los Atracasol de la ciudad. ¡Y Está desterrando a la Horda del Kirin Tor!' WHERE `ID`=69645;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 무모하군. 얼라이언스는 전쟁마법사들을 언제든지 도시 안으로 움직일 수 있는 게 확실하다. 추잡한... 마녀 같으니라고!', `MaleText_loc4`='她太过分了。联盟的战斗法师肯定横行达拉然了。那个人类……巫婆！', `MaleText_loc5`='她太過份了。我很確定聯盟的戰爭法師也可以在城裡自由穿梭。那個可惡的...妖女。', `MaleText_loc7`='Ha ido demasiado lejos. Seguro que la Alianza puede mover a sus magos de guerra por la ciudad como le plazca. ¡Esa... bruja humana!' WHERE `ID`=69646;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 대체 언제 정신을 차릴 건가? 호드가 얼라이언스 때문에, 그리고 그 편견과 증오 때문에 존재한다는 걸 언제쯤 깨달을 거란 말인가!? 점점 헬스크림 쪽에 서도록 하는군.', `MaleText_loc4`='他们何时才能明白，才能看清？正是联盟的偏见与猜忌促成了部落！？他们把我们推向了地狱咆哮的部落。', `MaleText_loc5`='他們什麼時候才會學乖?什麼時候才會明白部落是因為聯盟而存在的?就是因為他們的固執和偏見!?是他們逼我們和地獄吼的部落靠攏。', `MaleText_loc7`='¿Cuándo aprenderán? ¿Cuándo se darán cuenta de que la Horda existe A CAUSA de la Alianza? ¿¡Por sus prejuicios e intolerancia!? Nos empujan cada vez más hacia la Horda.' WHERE `ID`=69647;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 주군이시여...', `MaleText_loc4`='大人……', `MaleText_loc5`='大人...', `MaleText_loc7`='Mi señor...' WHERE `ID`=69648;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='할두론, 순찰자를 소환하게. 롬매스, 혈법사를 소집하도록. 그리고 그대들도 선리버의 힘으로 무장하게나.', `MaleText_loc4`='哈杜伦，召集游侠。罗曼斯，集结血法师，让夺日者也加入你们。', `MaleText_loc5`='赫杜倫，召集遊俠。洛摩斯，集合血法師，然後把奪日者的兵力納入你的麾下。', `MaleText_loc7`='Halduron, convoca a los forestales. Rommath, reúne a los magi sangrientos y suma las fuerzas de los Atracasol a las tuyas.' WHERE `ID`=69649;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 신도레이의 미래는 스스로 지켜내겠네.', `MaleText_loc4`='我们辛多雷要亲手掌握自己的未来。', `MaleText_loc5`='我們辛多雷將會掌握自己的未來。', `MaleText_loc7`='Los Sin''dorei nos haremos cargo de nuestro propio futuro.' WHERE `ID`=69650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이건 내 눈앞에서 치워버리게! 헬스크림이 내 백성의 피를 대가로 이 보물을 가져왔잖나. 이게 그놈을 망쳐놨으면 좋겠군.', `MaleText_loc4`='把这该死的玩意拿走！地狱咆哮用血精灵的鲜血换取他的宝物。真希望这钟把他毁了。', `MaleText_loc5`='還有把這該死的東西拿走!地獄吼為了奪寶而潑灑我人民的鮮血，我希望這會摧毀他。', `MaleText_loc7`='¡Y quiten esta cosa nefasta de mi vista! Grito Infernal compró su tesoro con la sangre de mi gente. Espero que esto acabe con él.' WHERE `ID`=69651;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주님이야말로 훌륭한 대족장 재목이십니다.', `MaleText_loc4`='大人。你会是个好酋长的。', `MaleText_loc5`='大人。您會是稱職的大酋長。', `MaleText_loc7`='Mi señor, USTED sería un Jefe de Guerra magnífico.' WHERE `ID`=69652;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주님이야말로 훌륭한 대족장 재목이십니다.', `MaleText_loc4`='大人。你会是个好酋长的。', `MaleText_loc5`='大人。您會是稱職的大酋長。', `MaleText_loc7`='Mi señor, USTED sería un Jefe de Guerra magnífico.' WHERE `ID`=69653;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴지도 모르겠군. 내 칼을 가져오게. 이젠 내가 움직일 차례다.', `MaleText_loc4`='或许如此。把我的剑拿来。该我行动了。', `MaleText_loc5`='可能真有這一天。把我的劍拿過來。換我出招了。', `MaleText_loc7`='Tal vez esa termine siendo la solución. Tráeme mis espadas. La próxima jugada es mía.' WHERE `ID`=69654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='젊음의 물을 마셔보실 겁니까?', `MaleText_loc4`='你想尝尝青春之水吗？', `MaleText_loc5`='你要嚐一口回春水裡的水嗎?', `MaleText_loc7`='¿Vas a probar un sorbo del agua de la juventud?', `FemaleText_loc1`='젊음의 물을 마셔보실 건가요?', `FemaleText_loc4`='你想尝尝青春之水吗？', `FemaleText_loc5`='你要嚐一口回春水裡的水嗎?', `FemaleText_loc7`='¿Vas a probar un sorbo del agua de la juventud?' WHERE `ID`=69655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나가 미쳐버렸소. 그녀는 선리버를 가두고 저항하는 자들을 공격하고 있소. 더 큰 문제는 은빛 서약단도 이 틈을 타 살육에 동참하고 있다는 거요.', `MaleText_loc4`='吉安娜太过分了。她囚禁了夺日者，攻击任何抵抗的人。更糟糕的是，银色盟约也趁机加入了屠杀。', `MaleText_loc5`='珍娜已經失去理智。她囚禁奪日者成員，並且攻擊反抗的人。更糟糕的是，白銀誓盟也利用機會加入這場血腥衝突。', `MaleText_loc7`='Jaina se ha extralimitado. Encarcela a los Atracasol y ataca a todo el que se resiste. Y lo que es peor, El Pacto de Plata ha aprovechado esta oportunidad para unirse a la matanza.' WHERE `ID`=69656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온통 혼란 속이오. 최대한 많은 이들을 구출하고 빠르게 움직여야 하오.', `MaleText_loc4`='上面一片混乱。我们得尽力救人，而且要快。', `MaleText_loc5`='那裡一片混亂。我們得盡力搶救還有救的人，而且我們動作得加快。', `MaleText_loc7`='Ahí arriba reina el caos. Debemos salvar a cuantos podamos, y hay que actuar deprisa.' WHERE `ID`=69657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 명령을 기다리시오...', `MaleText_loc4`='等我的命令……', `MaleText_loc5`='等我的命令...', `MaleText_loc7`='Esperen a mi orden...' WHERE `ID`=69658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금이오! 서두르시오! 도시 중앙으로! 이쪽이오!', `MaleText_loc4`='上上上！去城市中心！这边走！', `MaleText_loc5`='衝衝衝衝!前往市中心!這一邊!', `MaleText_loc7`='¡Vamos, vamos! ¡Al centro de la ciudad! ¡Por aquí!' WHERE `ID`=69659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스가 없군... 놈들이 옮겼나보오. 일단 그 없이 가야겠소.', `MaleText_loc4`='艾萨斯不在……肯定被转移了。没有他我们也得继续。', `MaleText_loc5`='埃薩不在那裡...他們一定把他帶到其他地方去了。我們可以靠自己繼續。', `MaleText_loc7`='Aethas no está aquí... Se lo habrán llevado. Podemos seguir sin él.' WHERE `ID`=69660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기에서 손을 떼고 물러서시오. 그렇게 나오시겠다.', `MaleText_loc4`='住手，让开。很好。', `MaleText_loc5`='住手然後站到一邊去。好吧。', `MaleText_loc7`='Ríndete y apártate. Muy bien.' WHERE `ID`=69661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스! 이쪽이오! 차원문으로!', `MaleText_loc4`='艾萨斯，这边！进传送门！', `MaleText_loc5`='埃薩，這邊!進去傳送門!', `MaleText_loc7`='¡Aethas, por aquí! ¡Al portal!' WHERE `ID`=69662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꼭 붙으시오! 터널 밖으로 나갈 거요!', `MaleText_loc4`='跟紧我！我们要出隧道了！', `MaleText_loc5`='跟著我!我們馬上離開隧道!', `MaleText_loc7`='¡Síganme! ¡Saldremos por el túnel!' WHERE `ID`=69663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바짝 붙으시오!', `MaleText_loc4`='跟着我！', `MaleText_loc5`='跟著我!', `MaleText_loc7`='¡Permanezcan a mi lado!' WHERE `ID`=69664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 온 것 같군. 빨리 해치우세.', `MaleText_loc4`='大家到齐了。我们开始吧。', `MaleText_loc5`='大家都到了。我們趕緊把事情辦好吧。', `MaleText_loc7`='Vengan todos ahora mismo. Acabemos con esto.' WHERE `ID`=69665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='육로로 가라. 우리는 주위를 둘러보며 다른 입구를 찾겠다.', `MaleText_loc4`='徒步前进。我们到四周找找其他入口。', `MaleText_loc5`='步行前進。我們繞過去找找有沒有其他入口。', `MaleText_loc7`='Sigan a pie.  Nosotros daremos unas vueltas y buscaremos otra entrada. ' WHERE `ID`=69666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 명령이라면...', `MaleText_loc4`='如酋长所愿……', `MaleText_loc5`='承大酋長之令...', `MaleText_loc7`='Como ordene el Jefe de Guerra.' WHERE `ID`=69667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 있어 안심이군. 가로쉬의 깡패들은 느낌이 안 좋아.', `MaleText_loc4`='很高兴有你掩护我。我讨厌加尔鲁什的恶棍。', `MaleText_loc5`='很高興有你罩我，我不喜歡卡爾洛斯手下的眼神。', `MaleText_loc7`='Me alegra que estén aquí para vigilarme las espaldas. No me gusta la facha de los matones de Garrosh.' WHERE `ID`=69668;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 올라타 출발하세!', `MaleText_loc4`='我们上马，出发！', `MaleText_loc5`='整裝上坐騎，準備出發!', `MaleText_loc7`='¡Montemos y salgamos de aquí!' WHERE `ID`=69669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 나도 깡패는 싫다고.', `MaleText_loc4`='嘿——等等我！我也讨厌那些恶棍。', `MaleText_loc5`='嘿 - 等我!我也不喜歡那群白癡。', `MaleText_loc7`='¡Ey, espérame! A mí tampoco me gustan los matones.' WHERE `ID`=69670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정찰대가 이 동굴 안에 고대의 마법이 있다더군. 대족장이 확인하라고 했네.', `MaleText_loc4`='斥候说洞穴里有古代魔法。酋长让他们来调查。', `MaleText_loc5`='斥候回報說在這洞穴裡有古老的法術。大酋長想要調查一下。', `MaleText_loc7`='Los exploradores dicen que hay magia antigua en estas cuevas. El Jefe de Guerra quiere investigarlas.' WHERE `ID`=69671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도마뱀 괴물이군. 함께 싸우세, 형제여!', `MaleText_loc4`='该死的蜥蜴人。随我战斗，兄弟们！', `MaleText_loc5`='是一隻蜥蜴怪物，上啊，兄弟們!', `MaleText_loc7`='Uno de eso'' bicho'' lagah''to. ¡Luchad, he''manos!' WHERE `ID`=69672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들과 싸워 본 적 있나?', `MaleText_loc4`='你以前和这些家伙战斗过吗？', `MaleText_loc5`='你以前對付過這種傢伙?', `MaleText_loc7`='¿Ya se han enfrentado a estas bestias antes?' WHERE `ID`=69673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기는 있어도 뇌는 없는 모양이야.', `MaleText_loc4`='看来他们空有武器，却没有脑子。', `MaleText_loc5`='他們空有武力，卻沒什麼腦袋。', `MaleText_loc7`='Es como si tuvieran armas, pero no cerebro.' WHERE `ID`=69674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배를 타고 들어가면 돼. 잠시 몇 군데 손만 좀 보고...', `MaleText_loc4`='我们可以把船开进去。只要做一点改装……', `MaleText_loc5`='我們能把這台船開進去。只要讓我做一些調整...', `MaleText_loc7`='Podemos utilizar este barco. Déjenme hacerle un par de modificaciones…' WHERE `ID`=69675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 됐다! 사우록 척살 자주포야.', `MaleText_loc4`='啊……完成了！自行式蜥蜴人宰杀机。', `MaleText_loc5`='然後...大功告成!一台自動推進的薩烏洛克屠殺機器。', `MaleText_loc7`='¡Y listo! Una máquina machaca-saurok autopropulsada.' WHERE `ID`=69676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 명이 총을 맡게. 나머지는 걸어가지.', `MaleText_loc4`='一人操作机枪，其他人步行。', `MaleText_loc5`='一個去顧砲台，其他人站好預備。', `MaleText_loc7`='Que uno de ustedes controle las armas, el resto quédese alerta.' WHERE `ID`=69677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이는 건 모조리 죽이게!', `MaleText_loc4`='杀光那些爬虫！', `MaleText_loc5`='殺死所有會動的東西!', `MaleText_loc7`='¡Maten todo lo que se mueva!' WHERE `ID`=69678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악, 어떻게 좀 해 봐!', `MaleText_loc4`='哎呀，甩掉它！', `MaleText_loc5`='啊啊，把這鬼東西弄掉!', `MaleText_loc7`='¡Agh, quítennos esa cosa de encima!' WHERE `ID`=69679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 망가뜨리고 있잖아!', `MaleText_loc4`='他们在破坏我们的船！', `MaleText_loc5`='它們要把我們的船弄壞了!', `MaleText_loc7`='¡Se están cargando nuestro barco!' WHERE `ID`=69680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길세! 여기 배를 세우게.', `MaleText_loc4`='到了！在这儿停船。', `MaleText_loc5`='停!把船停在這。', `MaleText_loc7`='¡Aquí! Paren el barco aquí.' WHERE `ID`=69681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리즈, 배를 지켜라. 나머지는 날 따라오고.', `MaleText_loc4`='格里兹尔看着船。其他人跟我走。', `MaleText_loc5`='格里斯，在這裡守住船。其他人跟我走。', `MaleText_loc7`='Griz, tú vigila el barco. Los demás, vengan conmigo.' WHERE `ID`=69682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이거 받아! 무리를 상대하는 데 도움이 될 거라고.', `MaleText_loc4`='给！它能帮你对付虫子。', `MaleText_loc5`='拿著這個!這可以幫你對抗大批敵人。', `MaleText_loc7`='¡Tomen esto! Les ayudará contra cualquier plaga.' WHERE `ID`=69684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 나는 그냥 여기 있을게. 날 잊지 마!', `MaleText_loc4`='那我就……留下吧。别忘了我！', `MaleText_loc5`='我...我哪也不去。好嗎?別忘了我!', `MaleText_loc7`='Yo... aquí me quedo. ¡No se olviden de mí!' WHERE `ID`=69685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비는 모두 끝났는가?', `MaleText_loc4`='准备工作完成了吗？', `MaleText_loc5`='準備工作完成了嗎?', `MaleText_loc7`='¿Terminaron los preparativos?' WHERE `ID`=69686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 장군님. 함정은 모두 설치했습니다. 천상의 종은 천둥왕께서 돌아오실 때까지 이 납골당에 안전하게 보관될 것입니다.', `MaleText_loc4`='是的，大人。陷阱已经设下。圣钟将安全地留在墓穴里，等待雷电之王的归来。', `MaleText_loc5`='是的，督軍。所有的陷阱都已經安置妥當。聖鐘在這座地穴裡絕對安全，靜候雷王回歸的那一天。', `MaleText_loc7`='Sí, señor de la guerra. Las trampas están puestas. La Campana divina estará a salvo en la cripta lista para el día en que regrese el Rey del Trueno.' WHERE `ID`=69687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일꾼들과 전사들을 대피시키는 것만 남았습니다.', `MaleText_loc4`='我们只需撤走工人和剩余的战士即可。', `MaleText_loc5`='我們只需要疏散那些工人和剩下的戰士了。', `MaleText_loc7`='Solo queda evacuar a los trabajadores y al resto de nuestros guerreros.' WHERE `ID`=69688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 형제들의 영혼이 영원토록 이곳을 수호하기를.', `MaleText_loc4`='那好吧。愿兄弟们的鬼魂永远庇佑此地。', `MaleText_loc5`='好吧。願我們兄弟的鬼魂永遠守護這片土地。', `MaleText_loc7`='De acuerdo. Que los fantasmas de nuestros hermanos guarden este lugar eternamente.' WHERE `ID`=69689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없다. 음영파 추적자들이 가까이에 있어. 놈들에게 종의 위치를 노출시킬 순 없지.', `MaleText_loc4`='没有时间了。影踪派追过来了。不能让他们发现圣钟的下落。', `MaleText_loc5`='沒時間了。影潘追蹤者已經靠的太近。不能讓他們知道聖鐘的位置。', `MaleText_loc7`='No hay tiempo. Los rastreadores del Shadopan están demasiado cerca. No deben saber dónde está la Campana.' WHERE `ID`=69690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 희생은 헛되지 않을 것이다.', `MaleText_loc4`='他们不会就这样白白牺牲的。', `MaleText_loc5`='他們不會白白犧牲。', `MaleText_loc7`='Su sacrificio no será en vano.' WHERE `ID`=69691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아바르투, 너의 희생 또한 말이지.', `MaleText_loc4`='你也不会白死的，阿瓦图。', `MaleText_loc5`='你的犧牲也是如此，阿法圖。', `MaleText_loc7`='Ni el tuyo tampoco, Avartu.' WHERE `ID`=69692;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이... 빛이 보인다... 드디어, 수백 년 동안의 침묵 끝에 누군가 왔구나.', `MaleText_loc4`='光……我看到了光……经历了几百年的沉寂，终于有人来了。', `MaleText_loc5`='光明...我看見光明了...在沉靜了數個世紀後，終於有人來了。', `MaleText_loc7`='Luz... Veo la luz... Por fin, tras siglos de silencio, alguien vino.' WHERE `ID`=69693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분부하신대로 종을 지켜냈습니다, 나의 군주시여.', `MaleText_loc4`='主人，我一直谨守誓言，守护着圣钟。', `MaleText_loc5`='我確保了聖鐘的安全，主人。', `MaleText_loc7`='He protegido la Campana como prometí, maestro.' WHERE `ID`=69694;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 너희는 모구가 아니잖아! 침입자다!', `MaleText_loc4`='等等……你不是魔古！入侵者！', `MaleText_loc5`='等等...你不是魔古!入侵者!', `MaleText_loc7`='Un momento... ¡No son mogu! ¡Intrusos!' WHERE `ID`=69695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자들이여, 일어나라! 천둥왕의 보물을 훔치려는 자들에게 죽음을 선사하라!', `MaleText_loc4`='醒来吧，守护者们！消灭这些妄想窃取雷电之王宝藏的家伙。', `MaleText_loc5`='守護者，醒來吧!摧毀那些想要竊取雷王寶物的人。', `MaleText_loc7`='¡Guardianes, despierten! Destruyan a los que pretendan robar el tesoro del Rey del Trueno.' WHERE `ID`=69696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠에 휩싸여라!', `MaleText_loc4`='堕入黑暗吧！', `MaleText_loc5`='驅逐至黑暗之中!', `MaleText_loc7`='¡Perezcan en las sombras!' WHERE `ID`=69697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳이 네 무덤이 될 것이다!', `MaleText_loc4`='这座墓穴就是你的葬身之地！', `MaleText_loc5`='這地穴就是你的葬身之地!', `MaleText_loc7`='¡Esta cripta será su tumba!' WHERE `ID`=69698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 또한 침묵하리라!', `MaleText_loc4`='你们也将随之沉寂。', `MaleText_loc5`='你也一樣，將學會保持沈默。', `MaleText_loc7`='Ustedes también conocerán el silencio.' WHERE `ID`=69699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포를 느껴라... 공허를 느껴라!', `MaleText_loc4`='如此恐怖……如此空虚。', `MaleText_loc5`='多麼可怕...多麼空虛。', `MaleText_loc7`='Cuánto horror... Cuánto vacío.' WHERE `ID`=69700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음만이 널 기다린다!', `MaleText_loc4`='等待你们的只有死亡！', `MaleText_loc5`='只剩死亡等待著你!', `MaleText_loc7`='¡Solo les espera la muerte!' WHERE `ID`=69701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안돼! 종을...!', `MaleText_loc4`='不！圣钟！', `MaleText_loc5`='不!聖鐘!', `MaleText_loc7`='¡No! ¡La Campana!' WHERE `ID`=69702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기까지다, 침입자들아! 내가 상대해주겠다. 빠른 죽음을 안겨주지.', `MaleText_loc4`='站住！现在该我了。我会给你们一个痛快的。', `MaleText_loc5`='別想再往前走!準備接招吧，我會讓你死的痛快。', `MaleText_loc7`='¡No iréis más lejos! Enfrentaos a mí. Os daré una muerte rápida.' WHERE `ID`=69703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조사단이로군. 상륙한다.', `MaleText_loc4`='那是我的勘察组。带我们过去。', `MaleText_loc5`='我的調查小組就在那。帶我們過去。', `MaleText_loc7`='Ahí está mi equipo de investigación. Llévanos allí.' WHERE `ID`=69704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황은?', `MaleText_loc4`='情况如何？', `MaleText_loc5`='情況如何?', `MaleText_loc7`='¿Cuál es la situación?' WHERE `ID`=69705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하! 여기엔 없는 게 없습니다. 나무에 돌에...', `FemaleText_loc4`='陛下！这里有我们需要的一切：木材、石料和……', `FemaleText_loc5`='國王陛下!此地有我們需要的所有東西:木頭、石材、還有...', `FemaleText_loc7`='¡Majestad! Este lugar tiene todo lo necesario: madera, piedra y...' WHERE `ID`=69706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는?', `MaleText_loc4`='还有部落？', `MaleText_loc5`='那部落呢?', `MaleText_loc7`='¿Y la Horda?' WHERE `ID`=69707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트로트먼 사령관님이 정찰대와 함께 해안을 따라 호드 부대를 쫓아가, 돌아오지 않았습니다.', `FemaleText_loc4`='托德曼元帅和几个斥候追击一支部落小队去了海滩，至今还没回来。', `FemaleText_loc5`='卓特曼元帥和一些斥候追捕部落的戰隊到海灘那。他們還沒回來。', `FemaleText_loc7`='El mariscal Troteman y algunos exploradores persiguieron a una legión de la Horda por la playa. No han regresado.' WHERE `ID`=69708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 트로트먼이 일을 당했을지도 모른다. 갈라지지.', `MaleText_loc4`='托德曼恐怕已经自顾不暇了。我们得分兵。', `MaleText_loc5`='嗯...卓特曼可能太掉以輕心了。我們分開行動。', `MaleText_loc7`='Quizás Troteman se metió en algo demasiado grande para él. Nos separaremos.' WHERE `ID`=69709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='린나, 여기 있으면서 야영지를 건설해라. 의무 막사와 숙소가 최우선이다. 인부들이 도착하면 부두 건설을 시작해라.', `MaleText_loc4`='琳娜，你留下来建营地。医疗帐篷和掩体一定要优先建造。等农夫到达后，就安排他们开始建港口。', `MaleText_loc5`='琳娜，留在這裡設立一個營地。你首要工作是準備醫療帳棚跟休息室。等那些農民來了以後，監督他們開始碼頭的建築工程。', `MaleText_loc7`='Lynna, quédate y arma un campamento. La prioridad son las tiendas médicas y los refugios. Cuando lleguen los campesinos encárgate de que empiecen a construir los muelles.' WHERE `ID`=69710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼스웨글, 조사단에 알려라. 함대가 오는 대로 채석과 채광을 시작하도록.', `MaleText_loc4`='盘角，通知勘察组的其他人，等舰队一到，就把采石场和矿场搞起来。', `MaleText_loc5`='角旋，通知剩下的調查團隊。等到艦隊抵達以後馬上開始採石跟採礦的作業。', `MaleText_loc7`='Hilda, avísale al resto del equipo de investigación. Empezarán con la cantera y las operaciones mineras en cuanto llegue la flota.' WHERE `ID`=69711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='예, 폐하!', `FemaleText_loc4`='遵命，陛下！', `FemaleText_loc5`='是的，陛下!', `FemaleText_loc7`='¡Sí, su Majestad!' WHERE `ID`=69712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 그대는 이 땅을 누구보다도 잘 안다. 나와 함께 가서 트로트먼을 찾자.', `MaleText_loc4`='勇士，你对这片土地最为了解。跟我来，我们去找托德曼。', `MaleText_loc5`='勇士，你比任何人都熟悉這片土地。你跟我來。我們去找卓特曼。', `MaleText_loc7`='Tú conoces esta tierra mejor que nadie, vendrás conmigo. Vamos a encontrar a Troteman.' WHERE `ID`=69713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트로트먼 이 친구, 역시 말썽을 피우고 있었군.', `MaleText_loc4`='托德曼你这老狗，我就知道你又惹麻烦了。', `MaleText_loc5`='卓特曼你這老傢伙，我就知道你會給我製造麻煩。', `MaleText_loc7`='Troteman, perro viejo, sabía que estarías metido en un lío.' WHERE `ID`=69714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사단이 잘해주었다. 항구 건설에 이상적인 곳이야.', `MaleText_loc4`='勘察组干得不错。这是一处深水良港。', `MaleText_loc5`='調查隊做得非常好。這是一塊理想的深水港。', `MaleText_loc7`='El equipo de investigación ha hecho un buen trabajo. Es un fondeadero estupendo. Pero habrá que defenderlo.' WHERE `ID`=69715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 탑을 건설하는 게 좋겠군.', `MaleText_loc4`='这里要建一座塔楼。', `MaleText_loc5`='去那裡建一座防衛塔。', `MaleText_loc7`='Quiero que se construya una torre justo aquí.' WHERE `ID`=69716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관, 건설이 끝날 때까지 위치를 사수하도록.', `MaleText_loc4`='元帅，你一定要守住这地方，直到建设完成。', `MaleText_loc5`='元帥，守在這裡監督直到建築工作完成為止。', `MaleText_loc7`='Mariscal, encárgate de defender esta posición hasta que terminen las construcciones.' WHERE `ID`=69717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 보급 쪽을 볼까...', `MaleText_loc4`='现在，来看看补给……', `MaleText_loc5`='那麼，讓我們來看看後勤的補給...', `MaleText_loc7`='Ahora ocupémonos de los suministros...' WHERE `ID`=69718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탐험가 연맹에서 보고 드립니다!', `FemaleText_loc4`='探险者协会前来报到，陛下！', `FemaleText_loc5`='探險者協會向您回報，陛下!', `FemaleText_loc7`='¡Liga de Expedicionarios a la orden, su Majestad!' WHERE `ID`=69719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참전해 주어 고맙군. 하지만 보급품이 필요하다. 상황은?', `MaleText_loc4`='你对战争的积极令人欣慰。但我需要补给。你有什么？', `MaleText_loc5`='我很高興看到你在戰場上的貢獻。但我需要的後勤補給，有什麼進展嗎?', `MaleText_loc7`='Me alegra ver que contribuyen con la campaña bélica. Pero necesito suministros. ¿Qué tenemos?' WHERE `ID`=69720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='석재는 풍족합니다. 하지만 주변에 굵직한 광맥은 없습니다.', `FemaleText_loc4`='大量的石头。但这里没有发现大型铁矿。', `FemaleText_loc5`='有豐富的石材，沒錯。但是這整片區域沒有值得一提的礦脈。', `FemaleText_loc7`='Hay piedra de sobra. Pero ni una veta de mena importante en toda la zona.' WHERE `ID`=69721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇군. 다른 건?', `MaleText_loc4`='石头我要了。别的呢？', `MaleText_loc5`='可以接受，還有什麼?', `MaleText_loc7`='Es algo. ¿Alguna otra cosa?' WHERE `ID`=69722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 좋은 게 있지요. 사적입니다! 막강한 고대 종족이 남긴 유물이지요!', `FemaleText_loc4`='还有更好的东西。史无前例！一个强大的远古遗物！', `FemaleText_loc5`='還有更好的東西。歷史文物!從古老而強大的種族所留下來的神器!', `FemaleText_loc7`='Algo mucho MEJOR: ¡historia! ¡Artefactos de una raza antigua y poderosa!' WHERE `ID`=69723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거래를 하나 하지. 내 부하들이 채석을 시작할 수 있게 도와준다면, 발굴 현장을 보호해 주겠다.', `MaleText_loc4`='我们做个交易吧，盘角。帮我的人把采石场开起来，而我们保护你搞考古挖掘。', `MaleText_loc5`='我來跟你做個交易，角旋。幫助我的人讓採石場開始運作，我就保護你的考古挖掘場。', `MaleText_loc7`='Haremos un trato, Hilda. Ayuda a mis hombres a tener una cantera en funcionamiento y protegeremos tu excavación arqueológica.' WHERE `ID`=69724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말이요?! 아, 폐하께 직접 발굴을 허가받았다고 하면 브란이 어떤 얼굴을 할지! 다음 해가 지기 전까지 채석장이 준비될 겁니다!', `FemaleText_loc4`='真的？！噢，我得到了国王陛下批准！真想看看布莱恩知道后的表情！我保证在下次日落前搞定采石场！', `FemaleText_loc5`='您說的是真的嗎?!噢，我想看看布萊恩要知道我有陛下欽賜的挖掘特許臉上會有什麼表情!您的礦石場在明天日落前就會準備好!', `FemaleText_loc7`='¡¿En serio?! ¡Oh, me muero por ver la cara que pondrá Brann cuando se entere que el Rey en persona me ha dado luz verde para una excavación! Tendrá su cantera antes de la próxima puesta de sol!' WHERE `ID`=69725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에는 힘이 곧 통솔이라 생각했지. 하지만 이제 알겠다. 통솔이란 조금씩 주고받는 것이며, 사람을 단결시키는 것이야. 잔가지도 한데 묶으면 쉽게 부러지지 않거든.', `MaleText_loc4`='我曾经以为领导力就是力量。现在我明白多了——付出才有回报。领导者要将人民团结起来。正所谓独木不成林。', `MaleText_loc5`='我以前老認為必須靠力量來領導。現在我了解更深的意義了 - 其實關鍵在於施與得之間的微妙關係。領導在於如何團結人民。兄弟同心，齊力斷金。', `MaleText_loc7`='Solía pensar que el liderazgo era cuestión de fuerza. Ahora lo veo más claro: por una parte hay que dar y por otra recibir. Se trata de unir a la gente. La unión hace la fuerza.' WHERE `ID`=69726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 준비됐다. 해안의 자원을 이용해 이 반도에 마을을 건설할 것이다.', `MaleText_loc4`='万事俱备。我们要利用海岸上的资源在这座半岛中央建一座城镇。', `MaleText_loc5`='一切準備就緒。我們將利用沿岸的資源，在這座半島上建立一個城鎮中心。', `MaleText_loc7`='Ya está todo listo. Construiremos una ciudad en esta península y usaremos los recursos que haya en la costa.' WHERE `ID`=69727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에서라면 원주민과 협력하여 호드의 공세를 막을 수 있다.', `MaleText_loc4`='现在我们要与当地人接触，并遏制部落的侵略行动。', `MaleText_loc5`='這樣我們就能跟當地的居民接觸，並隨時注意部落的動向。', `MaleText_loc7`='Desde aquí podremos comunicarnos con los nativos y tener a la Horda controlada.' WHERE `ID`=69728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여! 그대가 판다리아를 개척해주지 않았다면, 이런 기반을 다지지 못했을 것이다.', `MaleText_loc4`='勇士！没有你对潘达利亚的开拓，这座要塞是不可能建成的。', `MaleText_loc5`='勇士!還好有你在潘達利亞身先士卒的貢獻，否則不可能建設好這塊據點。', `MaleText_loc7`='Sin tus esfuerzos pioneros en Pandaria, este asentamiento no habría sido posible.' WHERE `ID`=69729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 직접 함대에 신호해라.', `MaleText_loc4`='这份殊荣属于你。给舰队发信号吧。', `MaleText_loc5`='這份榮耀屬於你。向軍艦打出信號。', `MaleText_loc7`='Puedes hacer los honores. Dale la señal a la flota.' WHERE `ID`=69730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관, 덕분에 항만의 방비는 완성되었다. 다음은...', `MaleText_loc4`='元帅，干得好。港口防御得到了巩固。接下来——', `MaleText_loc5`='元帥，打造港口的任務真是傑作。我們下個行動是 -', `MaleText_loc7`='Mariscal, has hecho un buen trabajo con la fortificación del puerto. La siguiente prioridad es…' WHERE `ID`=69731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지!', `MaleText_loc4`='父亲！', `MaleText_loc5`='父親!', `MaleText_loc7`='¡Padre!' WHERE `ID`=69732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼-?', `MaleText_loc7`='¿Qué...?' WHERE `ID`=69733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지!', `MaleText_loc4`='父亲！', `MaleText_loc5`='父親!', `MaleText_loc7`='¡Padre!' WHERE `ID`=69734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안두인! 무사했구나!', `MaleText_loc4`='安度因！你还活着！', `MaleText_loc5`='安杜因!你安然無恙!', `MaleText_loc7`='¡Anduin! ¡Estás a salvo!' WHERE `ID`=69735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지, 이래선 안 돼요. 우리 전쟁이 불러온 증오와 분노가 이 땅을 죽여가고 있어요.', `MaleText_loc4`='父亲，不能这样。我们的仇恨和愤怒——会腐蚀这片土地。', `MaleText_loc5`='父親!你不能這麼做。我們的戰爭所帶來的憎恨與憤怒 - 會毒害這片土地。', `MaleText_loc7`='Padre, no puedes hacer esto. Todo el odio y la rabia que nuestra guerra trae a este lugar... lo envenena.' WHERE `ID`=69736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라. 이번 전쟁은 다르단다. 호드가 미워서 싸우는 게 아니라, 정의를 위해 싸우는 거란다. 도리를 다하기 위해서지.', `MaleText_loc4`='放心。这场战争不同，孩子。它并非出于对部落的仇恨，而是出于对正义的热爱，源于有所必为的信念。', `MaleText_loc5`='別緊張。兒子，我們並非在此激起仇恨之戰。這無關對部落的仇恨，而是對我們珍惜事物的守護之戰，這是必要的。', `MaleText_loc7`='Tranquilo. Esta guerra es diferente, hijo. Esto no es por odio a la Horda, sino por amor a hacer lo correcto. A hacer lo que es necesario.' WHERE `ID`=69737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 땅은 우리 땅과는 달라요. 보물 같다고요.', `MaleText_loc4`='这里——与众不同。它是块珍宝。', `MaleText_loc5`='這片土地 - 跟我們的家鄉不同。這是一塊瑰寶。', `MaleText_loc7`='Esta tierra es... diferente a la nuestra. Es un tesoro.' WHERE `ID`=69738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 목숨을 걸고 지켜야지. 아들아! 이 일에는 네 도움이 필요하다. 함께해줬으면 좋겠다.', `MaleText_loc4`=' 那更要用生命来保护它。孩子！你要帮我。我们一起上阵？', `MaleText_loc5`='那我們應該竭盡我們的生命守護它。兒子!我需要你站在我這邊。我們的立場一致嗎?', `MaleText_loc7`='Entonces la protegeremos con nuestras vidas. ¡Hijo! Necesito tu apoyo. Estamos juntos en esto.' WHERE `ID`=69739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함께라...', `MaleText_loc4`='一起……', `MaleText_loc5`='一致...', `MaleText_loc7`='Juntos...' WHERE `ID`=69740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하! 호드가 서쪽의 사원 안에 틀어박혀 있습니다. 나이트 엘프 순찰대가 사원을 포위해 봉쇄했습니다...', `FemaleText_loc4`='陛下！部落躲在西边的一座寺院里。许多暗夜精灵游侠已经包围封锁了那里……', `FemaleText_loc5`='陛下!部落佔領了西方的一座寺廟。夜精靈的遊俠們已經包圍並封鎖了寺廟...', `FemaleText_loc7`='¡Majestad! La Horda se ha atrincherado en un templo al oeste de aquí. Forestales elfos de la noche lo tienen rodeado y bloqueado...' WHERE `ID`=69741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대라?... 티란데로군.', `MaleText_loc4`='游侠？……泰兰德。', `MaleText_loc5`='遊俠?...是泰蘭妲。', `MaleText_loc7`='¿Forestales?... Tyrande.' WHERE `ID`=69742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지! 주학사를 전쟁터로 만들 순 없어요. 이곳은 아직 샤 감염에서 회복하는 중이라고요...', `MaleText_loc4`='父亲！不能让朱鹤寺变成战场！它还没能从煞魔入侵中恢复元气……', `MaleText_loc5`='父親!你不能讓他們將紅鶴寺變成戰場!這塊地方還在從煞的污染中恢復...', `MaleText_loc7`='¡Padre! No puedes permitir que conviertan el Templo de la Grulla en una zona de guerra! Aún se está recuperando de la infestación del sha...' WHERE `ID`=69743;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='역사의 보고이기도 하고요.', `FemaleText_loc4`='那可是历史的瑰宝。', `FemaleText_loc5`='那是個珍貴的歷史寶庫。', `FemaleText_loc7`='Es un tesoro escondido histórico.' WHERE `ID`=69744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 진정해라. 가로쉬의 함정이다. 우리를 해변에서 꾀어낼 심산이야. 트로트먼? 인부와 박격포 부대를 모아주겠나? 방비를 단단히 하고.', `MaleText_loc4`='大家冷静。这恐怕是加尔鲁什的陷阱。他想把我们引出海滩。托德曼？去组织农夫和迫击炮小队，不要放松守卫。', `MaleText_loc5`='大家，冷靜點。這看起來又像是卡爾洛斯的一個陷阱。他想要誘騙我們離開海灘處。卓特曼，幫我召集農民還有迫擊砲小隊，別掉以輕心。', `MaleText_loc7`='Cálmense todos. Esto parece una de las trampas de Garrosh. Intenta alejarnos de la playa. ¡Troteman! Reúne a algunos campesinos y unos morteros, no bajes la guardia.' WHERE `ID`=69745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만...', `MaleText_loc4`='可父亲——', `MaleText_loc5`='但父親-', `MaleText_loc7`='Pero padre...' WHERE `ID`=69746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사 몇을 데리고 티란데와 이야기하러 가겠다. 안두인, 난 해낼 거다. 내가 옳은 일을 할 거라 믿어 다오.', `MaleText_loc4`='我会亲自带领一小队勇士去跟泰兰德谈谈。安度因，我能应付。相信我，我不会犯错的。', `MaleText_loc5`='我會帶一隊勇士去找泰蘭妲並親自討論這件事。安杜因，我能處理這個狀況。我要你相信我現在做的是正確的決定。', `MaleText_loc7`='Llevaré a un pequeño grupo de valientes conmigo y hablaré con Tyrande personalmente. Anduin, yo puedo con esto. Necesito que confíes en que haré lo correcto.' WHERE `ID`=69747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...믿을게요, 아버지.', `MaleText_loc4`='……我相信你，父亲。', `MaleText_loc5`='...我相信你，父親。', `MaleText_loc7`='Yo confío en ti, padre.' WHERE `ID`=69748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='길니아스의 국왕, 겐 그레이메인 님께 경례!', `MaleText_loc4`='向吉尔尼斯国王，吉恩·格雷迈恩致敬！', `MaleText_loc5`='恭迎吉爾尼斯之王，吉恩·葛雷邁恩!', `MaleText_loc7`='¡Damos la bienvenida al rey de Gilneas, Genn Cringris!', `FemaleText_loc1`='길니아스의 국왕, 겐 그레이메인 님께 경례!', `FemaleText_loc4`='向吉尔尼斯国王，吉恩·格雷迈恩致敬！', `FemaleText_loc5`='恭迎吉爾尼斯之王，吉恩·葛雷邁恩!', `FemaleText_loc7`='¡Damos la bienvenida al rey de Gilneas, Genn Cringris!' WHERE `ID`=69749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 멀리 고요한 다르나서스의 가지 위로부터, 대여사제 티란데 위스퍼윈드 님이 찾아오셨습니다!', `MaleText_loc4`='高阶祭司泰兰德·语风从遥远而宁静的达纳苏斯来到了这里！', `MaleText_loc5`='歡迎來自寧靜而遙遠的達納蘇斯枝幹之上的高階祭司泰蘭妲·語風，抵達現場!', `MaleText_loc7`='Desde los lejanos bosques de la pacífica Darnassus, ¡llega la suma sacerdotisa Tyrande Susurravientos!', `FemaleText_loc1`='저 멀리 고요한 다르나서스의 가지 위로부터, 대여사제 티란데 위스퍼윈드 님이 찾아오셨습니다!', `FemaleText_loc4`='高阶祭司泰兰德·语风从遥远而宁静的达纳苏斯来到了这里！', `FemaleText_loc5`='來自寧靜而遙遠的達納蘇斯枝幹之上的高階祭司泰蘭妲·語風，抵達現場!', `FemaleText_loc7`='Desde los lejanos bosques de la pacífica Darnassus, ¡llega la suma sacerdotisa Tyrande Susurravientos!' WHERE `ID`=69750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레나이의 대표자, 현명하고 고귀한 선견자 노분도 님이 엑소다르에서 먼 길을 오셨습니다!', `MaleText_loc4`='德莱尼人的代表，睿智而高贵的预言者，来自埃索达的努波顿！', `MaleText_loc5`='德萊尼的代表，來自艾克索達、睿智高貴的先知諾柏多!', `MaleText_loc7`='En representación de los draenei, ¡el sabio y noble clarividente Nobundo, de El Exodar!', `FemaleText_loc1`='드레나이의 대표자, 현명하고 고귀한 선견자 노분도 님이 엑소다르에서 먼 길을 오셨습니다!', `FemaleText_loc4`='德莱尼人的代表，睿智而高贵的预言者，来自埃索达的努波顿！', `FemaleText_loc5`='德萊尼的代表，來自艾克索達、睿智高貴的先知諾柏多!', `FemaleText_loc7`='En representación de los draenei, ¡el sabio y noble clarividente Nobundo, de El Exodar!' WHERE `ID`=69751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이... 샤... 라는 것 때문에 우리 병사들이 폭력적인 행동을 하게 됐다는 말이냐?', `MaleText_loc4`='我明白了。所以是这些……煞魔……引发了我们部队中的暴力行为？', `MaleText_loc5`='我明白了。所以是這個...煞...害我們的部隊變得如此暴躁殘酷?', `MaleText_loc7`='Entiendo. Así que fueron los... sha... los que provocaron ese comportamiento violento en nuestras tropas.' WHERE `ID`=69752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 아버지. 저도 여행을 하던 중에 샤의 힘을 목격했어요. 그 힘이 최고조에 달한 샤는, 바라볼 수도 없을 만큼 끔찍하게 강력해요.', `MaleText_loc4`='是的，父亲。我在旅途中也遇到过煞魔。不受约束的煞魔是令人惧怕的对手。', `MaleText_loc5`='是的，父親，我在旅途中見識過煞的能量，它完全釋放的力量十分恐怖。', `MaleText_loc7`='Sí, padre. He visto la energía sha durante mi viaje. Su poder completo es abrumador.' WHERE `ID`=69753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 얼라이언스는 지금껏 힘을 합쳐 수많은 적을 무찔러 왔다. 샤도 다른 녀석들과 마찬가지로 우리 앞에 쓰러질 것이다.', `MaleText_loc4`='我们联盟曾齐心协力打败过许多敌人，我的孩子。煞魔也将倒在我们面前，和其他敌人一样。', `MaleText_loc5`='我們聯盟團結打敗了許多的敵人，孩子，這個煞也一樣。', `MaleText_loc7`='La Alianza se ha unido muchas veces para hacer frente a enemigos, hijo. Los sha caerán ante nosotros como todos los demás.' WHERE `ID`=69754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 달라요, 아버지. 샤는 단순히 쓰러뜨리면 되는 존재가 아니에요. 그건 우리 내면 가장 깊은 곳의 약점을 먹고, 우리 생각을 뒤틀어요. 과소평가해서는 안 된다고요!', `MaleText_loc4`='这不一样，父亲。煞魔是不会被轻易击败的。它们会汲取我们内心的弱点，扭曲我们的心智。不要低估它们！', `MaleText_loc5`='父親，這回的狀況不一樣。煞無法被「打敗」，它以我們心中最脆弱的情緒為食，它會扭曲我們的思緒。千萬不要低估它!', `MaleText_loc7`='No es lo mismo, padre. A los sha no se los puede derrotar sin más. Se alimentan de nuestras debilidades. Manipulan nuestros pensamientos. ¡No los subestimes!' WHERE `ID`=69755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕님! 보세요!', `MaleText_loc4`='没错，陛下！请看！', `MaleText_loc5`='陛下!請看!', `MaleText_loc7`='¡Majestad! ¡Mira!' WHERE `ID`=69756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이여, 저게 샤인가?', `MaleText_loc4`='圣光在上，那就是煞魔？', `MaleText_loc5`='聖光啊，那是煞嗎?', `MaleText_loc7`='¡Por la Luz! ¿Eso es un sha?' WHERE `ID`=69757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 가까이 가지 마세요!', `MaleText_loc4`='是的。别靠近它！', `MaleText_loc5`='是的，請不要靠近!', `MaleText_loc7`='Sí. ¡No se acerquen!' WHERE `ID`=69758;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이... 것에서 거대한 암흑이 스며나오는 것이 느껴져요. 파괴해야 해요. 지금 당장!', `FemaleText_loc4`='我能感到这个……东西散发着强大的黑暗力量。消灭它，马上！', `FemaleText_loc5`='我感覺到有強大的黑暗力量從這個...這個東西散發出來... 立刻毀了它!', `FemaleText_loc7`='Percibo una gran oscuridad que emana de esa... cosa. ¡Destrúyanla ahora mismo!' WHERE `ID`=69759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동의합니다. 이런 생물로부터 초래되는 건 고통뿐입니다.', `MaleText_loc4`='我同意。只有深重的苦难才能造就这种生物。', `MaleText_loc5`='我同意，這個東西只會帶來苦難而已。', `MaleText_loc7`='Estoy de acuerdo. De una criatura así solo puede surgir sufrimiento.' WHERE `ID`=69760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 비취 숲에서 샤가 제 병사들을 어떻게 만드는지 두 눈으로 직접 목격했습니다. 가장 강한 병사도 의심의 손아귀에 붙들려 무력해지더군요.', `MaleText_loc4`='我在翡翠林亲眼见过煞魔对我的士兵所做的一切。严重的猜疑令我手下最坚强的士兵都深感无助，自暴自弃。', `MaleText_loc5`='我在翠玉林親眼見到煞對我們士兵的影響，連最傑出堅強的人也會因為強烈的疑惑而失去所有的行動力。', `MaleText_loc7`='En el Bosque de Jade vi de primera mano lo que los sha hicieron con mis soldados. Hasta mis hombres más fuertes sucumbieron ante la duda.' WHERE `ID`=69761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='황제 폐하, 우리는 샤를 연구해야 합니다. 무기로 변형시켜야 합니다! 호드는 이미 판다리아에서 숫적으로 우위를 점하고 있습니다. 우리는 사용할 수 있는 수단은 모두 동원해야 합니다.', `FemaleText_loc4`='陛下，我们应该好好研究它。把它变成我们的武器。部落在潘达利亚的军力已经超过了我们。我们需要利用一切可能的条件。', `FemaleText_loc5`='殿下，我們該好好研究它，利用它當武器!部落在潘達利亞的兵力已經勝過我們，我們不該放過任何機會。', `FemaleText_loc7`='Alteza, deberíamos estudiarlo. ¡Convertirlo en un arma! La Horda ya nos supera en número en Pandaria. Necesitamos todas las ventajas que podamos aprovechar.' WHERE `ID`=69762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연구를 해서 손해볼 일은 없을 거예요. 저게 절 쳐다보는 눈초리는 마음에 들지 않긴 하지만.', `MaleText_loc4`='只是研究的话不会出事的。不过我很不喜欢它看我的眼神。', `MaleText_loc5`='研究研究不會有壞處，我只是不喜歡它盯著我的那種樣子。', `MaleText_loc7`='No estaría mal estudiarlo, pero la verdad, no me hace gracia cómo me está mirando.' WHERE `ID`=69763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네! 네! 정말 재미있겠어요! 저걸 증류해서 새로운 동력원을 만들 수 있지 않을까요?', `MaleText_loc4`='太棒了！嗯，非常有趣！也许我可以用它提炼出一种新能源？', `MaleText_loc5`='好啊好啊!太有趣了!說不定我能把它提煉成什麼新的能量來源?', `MaleText_loc7`='¡Sí, sí! ¡Muy interesante! A lo mejor podría destilarlo y transformarlo en una fuente de energía...' WHERE `ID`=69764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬는 손에 넣는 것은 무엇이든 무기로 사용하고 있습니다. 우리도 동등한 조건에서 싸울 수 있게 준비해야 하지 않겠습니까?', `FemaleText_loc4`='加尔鲁什会利用手头的一切武器。难道我们不应该争取公平竞争的机会吗？', `FemaleText_loc5`='卡爾洛斯是個什麼武器都會拿出來的人，難道我們不該提高我方的競爭條件嗎?', `FemaleText_loc7`='Garrosh utiliza todas las armas que tiene a su alcance. ¿No deberíamos equilibrar la balanza?' WHERE `ID`=69766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 생각하니, 안두인?', `MaleText_loc4`='安度因，你怎么看？', `MaleText_loc5`='你有什麼看法，安度因?', `MaleText_loc7`='¿Tú qué piensas, Anduin?' WHERE `ID`=69767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬의 선례라면 그다지 따르고 싶지 않은데요. 얼라이언스는 우리 나름의 결정을 내려야 해요. ''옳은'' 결정이요.', `MaleText_loc4`='我可不想以加尔鲁什为榜样。联盟应该有自己的决断。正确的决断。', `MaleText_loc5`='我絲毫不想步上卡爾洛斯的後路，聯盟該有自己的決定 - 「正確」的決定。', `MaleText_loc7`='El ejemplo de Garrosh no me parece el más recomendable. La Alianza debería tomar sus propias decisiones. Decisiones correctas.' WHERE `ID`=69768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 말이 맞다, 아들아.', `MaleText_loc4`='说得好，我的孩子。', `MaleText_loc5`='說得好，孩子。', `MaleText_loc7`='Bien dicho, hijo.' WHERE `ID`=69769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 힘은 너무 위험하다. 난 여기에 손을 대지 않겠다!', `MaleText_loc4`='这种力量太危险了。我不同意！', `MaleText_loc5`='這種力量太危險了，我一點也不想要!', `MaleText_loc7`='Es un poder demasiado peligroso. ¡No lo quiero!' WHERE `ID`=69770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 오늘 이렇게 절 도와주셔서 정말 고마워요. 우리가 아버지를 옳은 길로 이끌 수 있을 것임을 알고 있었어요. 자, 이제 다른 일을 하러 가셔도 돼요.', `MaleText_loc4`='$n，感谢你今天的帮助。我就知道，我们一定可以说服我父亲选择正确的道路。现在，请回到你的岗位上去吧。', `MaleText_loc5`='$n，謝謝你今日的協助，我就知道我們一定能說服我父王做出正確的決定。那麼，暫且就請你先回去執行其他的任務吧。', `MaleText_loc7`='$n, gracias por ayudarme hoy. Sabía que podríamos convencer a mi padre de hacer lo correcto. Ve, por ahora puedes volver a tus otras ocupaciones.' WHERE `ID`=69771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘에 있는 달라란으로부터 오신, 키린 토의 지도자 제이나 프라우드무어 여군주님입니다!', `MaleText_loc4`='肯瑞托之首，来自浮空之城达拉然的吉安娜·普罗德摩尔女士！', `MaleText_loc5`='來自飛天城市達拉然，祈倫托的領導人，珍娜·普勞德摩爾女士!', `MaleText_loc7`='Desde la ciudad voladora de Dalaran, la líder del Kirin Tor: ¡Lady Jaina Valiente!', `FemaleText_loc1`='하늘에 있는 달라란으로부터 오신, 키린 토의 지도자 제이나 프라우드무어 여군주님입니다!', `FemaleText_loc4`='肯瑞托之首，来自浮空之城达拉然的吉安娜·普罗德摩尔女士！', `FemaleText_loc5`='來自飛天城市達拉然，祈倫托的領導人，珍娜·普勞德摩爾女士!', `FemaleText_loc7`='Desde la ciudad voladora de Dalaran, la líder del Kirin Tor: ¡Lady Jaina Valiente!' WHERE `ID`=69772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 준비되었습니다. 원숭이 왕을 풀어주세요.', `MaleText_loc4`='我准备好了。请释放美猴王吧。', `MaleText_loc5`='我準備好了。釋放美猴王。', `MaleText_loc7`='Estoy listo. Libera al Rey Mono.', `FemaleText_loc1`='저는 준비되었습니다. 원숭이 왕을 풀어주세요.', `FemaleText_loc4`='我准备好了。请释放美猴王吧。', `FemaleText_loc5`='我準備好了。釋放美猴王。', `FemaleText_loc7`='Estoy lista. Libera al Rey Mono.' WHERE `ID`=69773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 언젠가 샤를 길들여 무기로 만들 수 있을지도 몰라요. 하지만 그 대가로 우리 백성들을 모두 파괴해 버릴지도 모르는 위험을 감수해야 해요. 그런 대가라면 저는 치르지 않겠어요.', `MaleText_loc4`='没错，或许有一天，我们真的可以驱使煞魔作为武器。但在这个过程中，我们得冒着让人民遭遇灭顶之灾的威胁。我可不愿意付出这样的代价。', `MaleText_loc5`='的確，我們或許有機會利用煞做為武器，但我們卻得冒著毀滅自己人的風險。我無法接受這樣的代價。', `MaleText_loc7`='Sí, es posible que algún día se pueda convertir a los sha en un arma. Pero nos arriesgamos a exterminar a nuestro propio pueblo. Se trata de un precio que no estoy dispuesto a pagar.' WHERE `ID`=69774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<크게 코를 고는 판다렌>', `MaleText_loc4`='<熊猫人响亮地打着呼噜。>', `MaleText_loc5`='<這個熊貓人大聲打呼。>', `MaleText_loc7`='<El pandaren ronca sonoramente.>' WHERE `ID`=69775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나십시오! 호드가 접근하고 있습니다. 방어선을 구축해야 합니다!', `MaleText_loc4`='醒醒！部落过来了——我们得组织好防线！', `MaleText_loc5`='醒醒!部落來了 - 我們得準備防禦!', `MaleText_loc7`='¡Despierta! La Horda está cerca. ¡Hay que preparar las defensas!', `FemaleText_loc1`='일어나세요! 호드가 접근하고 있어요. 방어선을 구축해야 해요!', `FemaleText_loc4`='醒醒！部落过来了——我们得组织好防线！', `FemaleText_loc5`='醒醒!部落來了 - 我們得準備防禦!', `FemaleText_loc7`='¡Despierta! La Horda está cerca. ¡Hay que preparar las defensas!' WHERE `ID`=69776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이고. 아무래도 지금은 방어선을 구축하기에 좋지 않은 때 같네, 친구.', `MaleText_loc4`='噢。你恐怕选错了建造工事的时机，朋友。', `MaleText_loc5`='喔嗚，朋友，現在恐怕不是構建防禦工事的好時機。', `MaleText_loc7`='Ah, me temo que has elegido un mal momento para levantar defensas, colega.' WHERE `ID`=69777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보다시피 어제의 저녁 노을 축제가 조금 늦게 끝나서 말이야. 우리가 아무래도... 명상을 과하게 한 것 같네.', `MaleText_loc4`='你瞧，昨天傍晚的庆祝时间有点长。我们都有点……喝过头了。', `MaleText_loc5`='呃，昨天夜裡的慶祝會弄得晚了一些，我們有點... 茫過頭了。', `MaleText_loc7`='La fiesta del anochecer de ayer se alargó un poco. Es posible que... meditáramos demasiado.' WHERE `ID`=69778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 이 일에 적임자라는 사실을 처음부터 알고 있었어요, $c님. 여기 일을 마치시면 위층으로 절 찾아 오세요.', `MaleText_loc4`='我就知道你合适这任务，$c。等这里的事完成后，到楼上来找我。', `MaleText_loc5`='我知道你是最適合執行此任務的人選，$c。等這邊的事情結束了，就到樓上的來見我。', `MaleText_loc7`='Sabía que eras la persona indicada para esta tarea, $c. Reúnete conmigo arriba cuando hayas terminado.' WHERE `ID`=69779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주베카의 표식을 보면 그녀가 여기 검은 사원에 들어간 것이 분명합니다.', `MaleText_loc4`='裘碧卡留下的记号清楚地表明她进入了黑暗神殿。', `MaleText_loc5`='裘貝卡的印記清楚證明了她有進入此處的黑暗神廟。', `MaleText_loc7`='La marca de Jubeka indica claramente que entró en el Templo Oscuro por aquí.', `FemaleText_loc1`='주베카의 표식을 보면 그녀가 여기 검은 사원에 들어간 것이 분명합니다.', `FemaleText_loc4`='裘碧卡留下的记号清楚地表明她进入了黑暗神殿。', `FemaleText_loc5`='裘貝卡的印記清楚證明了她有進入此處的黑暗神廟。', `FemaleText_loc7`='La marca de Jubeka indica claramente que entró en el Templo Oscuro por aquí.' WHERE `ID`=69780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원에 들어갑니다.', `MaleText_loc4`='进入神殿。', `MaleText_loc5`='進入神廟。', `MaleText_loc7`='Entra en el templo.', `FemaleText_loc1`='사원에 들어갑니다.', `FemaleText_loc4`='进入神殿。', `FemaleText_loc5`='進入神廟。', `FemaleText_loc7`='Entra en el templo.' WHERE `ID`=69781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 일어나! 술 빚을 시간이다.', `MaleText_loc4`='放松点，伙计们。现在是畅饮时间。', `MaleText_loc5`='醒醒，兄弟們，釀酒的時候到了。', `MaleText_loc7`='Espabilad, hermanos. Es hora de fermentar.' WHERE `ID`=69782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌리는 중', `MaleText_loc4`='转动', `MaleText_loc5`='旋轉', `MaleText_loc7`='Rotando', `FemaleText_loc1`='돌리는 중', `FemaleText_loc4`='转动', `FemaleText_loc5`='旋轉', `FemaleText_loc7`='Rotando' WHERE `ID`=69783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 해변 요새를 확실하게 확보해야 합니다. 호드가 이곳에서 기반을 다지게 두었다간, 온 판다리아가 테라모어 꼴이 될 것입니다.', `MaleText_loc4`='我们要守住这座滩头堡垒。我们要给部落建立一处据点，全潘达利亚都将成为下一个塞拉摩。', `MaleText_loc5`='我們一定要守住這座灘頭堡。要是讓部落在這裡取得落腳之處，全潘達利亞都會變得跟塞拉摩一樣。', `MaleText_loc7`='Tenemos que asegurar esta playa. Si dejamos que la Horda se establezca aquí, toda Pandaria acabará como Theramore.' WHERE `ID`=69784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 판다리아를 손에 넣지 못하게 해야 합니다... 하지만 우리의 희생은 최대한 줄이면서 그 결과를 얻어내야 하지요.', `FemaleText_loc4`='我们必须防止部落侵占潘达利亚……可我们同时还要尽力减少我们造成的伤害。', `FemaleText_loc5`='我們一定要阻止部落佔領潘達利亞... 但是我們也得努力降低我方的損失。', `FemaleText_loc7`='Debemos evitar que la Horda se haga con Pandaria... pero también debemos esforzarnos para reducir al máximo el sufrimiento que causamos.' WHERE `ID`=69785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 다들 날 "다태워"라고 부르냐고?

그걸 꼭 말해줘야 알겠어? 이것 봐, 화학 약품이 그렇게 반응한걸 나보고 어쩌라고! 과학을 탓해, 과학을!', `MaleText_loc4`='他们为什么叫我“烤鸡”？

你真的想知道？你瞧，化学试剂会起那种反应并不是我的错！都怪该死的“科学”！', `MaleText_loc5`='大家為什麼叫我「暖烘烘」? 

你真的要問我?好吧，化學物質要這麼反應又不是「我」的錯!要怪就去怪「科學」啊!', `MaleText_loc7`='¿Que por qué me llaman "Caldeado"?

¿Me lo estás preguntando en serio? Mira, no fue culpa mía que los compuestos químicos reaccionaran así. ¡Fue culpa de la CIENCIA!' WHERE `ID`=69786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시나 탐험가 연맹은 속수무책인 상황에 봉착했군요.

그럼 우리는 당연히 이걸 이용해야겠죠.', `MaleText_loc4`='探险者协会又理所当然地陷入了窘境并把自己闹了个手忙脚乱。

而我们也就理所当然地要利用这一点。', `MaleText_loc5`='探險者協會當然會陷入無法收拾的愚蠢狀況。

然後我們「當然」要好好利用這點。', `MaleText_loc7`='Como siempre, la Liga de Expedicionarios se ha metido en camisa de once varas.

Y como siempre, nosotros nos aprovecharemos de la situación.' WHERE `ID`=69787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쳇!

유령으로도 모자라서 성물회까지 상대해야 하는 건가요? 뭐가 더 나쁜 소식인지 모르겠네요.', `FemaleText_loc4`='哎哟！

我们要在这里同时对付幽灵和神圣遗物学会？！我再也想不出比这更糟的了！', `FemaleText_loc5`='啥!

除了有鬼魂，還有聖匣守護者的傢伙?!真不曉得哪個比較糟糕!', `FemaleText_loc7`='¡Ay!

¿Tenemos que enfrentarnos a fantasmas y al Relicario a la vez? ¡No sé qué es peor!' WHERE `ID`=69788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='욱... 어제 너무 놀았어...', `MaleText_loc4`='呃，我搞砸了……', `MaleText_loc5`='呃，小賈的歌聽太多了...', `MaleText_loc7`='TEMP' WHERE `ID`=69789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계 태세를 취해라. 봉인이 깨진다.', `MaleText_loc4`='大家小心。封印正在崩溃。', `MaleText_loc5`='當心點，封印要解除了。', `MaleText_loc7`='Tened cuidado. Los sellos se están rompiendo.' WHERE `ID`=69790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님, 정말 샤를 통제할 수 있다고 생각하십니까? 그게 우리 병사들에게 한 짓을 보지 못하셨습니까?', `MaleText_loc4`='加尔鲁什，你真的相信煞魔可以被控制？你看到它对我们的人都做了什么吗？', `MaleText_loc5`='卡爾洛斯，你真的相信煞是可以控制的?你有沒有看到它對我們的人做了什麼?', `MaleText_loc7`='Garrosh, ¿de verdad crees que es posible controlar a los sha? ¿Has visto lo que han hecho con nuestros hombres?' WHERE `ID`=69791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근위병! 저 괴물을 없애라!', `MaleText_loc4`='卫兵！干掉那个怪物。', `MaleText_loc5`='衛兵!消滅那個怪物。', `MaleText_loc7`='¡Guardias! Acabad con esa abominación.' WHERE `ID`=69792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤는 강력한 무기가 될 수 있다. 모구는 한때 그 힘을 구속하여 천상의 종에 불어 넣었다. 그 과정에서 만들어진 이 찬란한 제국을 봐라.', `MaleText_loc4`='煞能可以被利用，成为强有力的武器。魔古族可能已经将煞的力量封入圣钟。看看他们依靠它缔造起了多么辉煌的帝国吧。', `MaleText_loc5`='煞可以當成強而有力的工具，魔古就是把煞的力量灌入了聖鐘，然後你看，他們建造的帝國有多輝煌。', `MaleText_loc7`='Los sha pueden ser una herramienta poderosa. Los mogu contuvieron su poder en la Campana divina, y mira el glorioso imperio que levantaron con ella.' WHERE `ID`=69793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 그 왕국은 몰락했습니다. 샤 때문일 수도, 판다렌 때문일 수도 있지만, 어쩌면... 그들 자신의 오만 때문일지도 모릅니다.', `MaleText_loc4`='可他们的帝国最终衰亡了。也许是由于煞魔，也许是由于熊猫人，或者是……由于他们自身的傲慢。', `MaleText_loc5`='但他們帝國終究還是垮了。也許是因為煞，也許是因為熊貓人，也許是因為...他們太過自傲。', `MaleText_loc7`='Pero su imperio cayó. Quizás por culpa de los sha, quizás por culpa de los pandaren, o quizás... por culpa de su propio orgullo.' WHERE `ID`=69794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체 무슨 일이지?!', `MaleText_loc4`='这是怎样疯狂的愚行？', `MaleText_loc5`='這是怎麼回事?', `MaleText_loc7`='¿Qué locura es esta?' WHERE `ID`=69795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스컬지가 너희 블러드 엘프에게서 용기라는 걸 모두 앗아간 거냐? 우리는 호드다! 힘이 담긴 것이라면, 우리는 그게 무엇이든 붙잡는다. 나의 호드에는 약자가 낄 곳이 없다!', `MaleText_loc4`='天灾军团把你们族人的勇气都吸干了吗，血精灵！我们是部落。只要有机会能获得力量，我们就要抓住它。在我的部落里，弱者没有发言权！', `MaleText_loc5`='血精靈，你們的勇氣是被天譴軍團給全部打散了嗎?我們是部落，哪裡有力量，我們就搶來用。我的部落容不下弱者!', `MaleText_loc7`='¿Acaso la Plaga se llevó todo el valor de tu gente, elfo de sangre? Somos la HORDA. Allá donde hay poder, nosotros LO TOMAMOS. ¡En mi Horda no hay sitio para los débiles!' WHERE `ID`=69796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다... 대족장님.', `MaleText_loc4`='如你所说……酋长。', `MaleText_loc5`='是...大酋長。', `MaleText_loc7`='Lo que tú digas... Jefe de Guerra.' WHERE `ID`=69797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 일입니까, 내 소중한 $g형제:자매;여? 당신네 종족에게 매력적으로 보이는 외형을 갖고 싶으십니까?', `MaleText_loc4`='怎么了，我的$g兄弟:姐妹;？你准备好给你的同胞做个榜样了吗？', `MaleText_loc5`='怎麼了，$g兄弟:姊妹;?準備好要變成更吸引你族類的外貌了嗎?', `MaleText_loc7`='¿Qué tal, pariente $gmasculino:femenino; primario? ¿Estás $glisto:lista; para mejorar tu atractivo visual ante otros miembros de tu especie?' WHERE `ID`=69798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당연한 말씀!', `MaleText_loc4`='我们开始吧！', `MaleText_loc5`='派對啦!', `MaleText_loc7`='¡Fiesta!', `FemaleText_loc1`='당연한 말씀!', `FemaleText_loc4`='我们开始吧！', `FemaleText_loc5`='派對啦!', `FemaleText_loc7`='¡Fiesta!' WHERE `ID`=69799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장치가 당신이 이상 물체에 아주 가까이 다가갔음을 알리고 있습니다.', `MaleText_loc4`='仪器表明你已经非常接近异常位置了。', `MaleText_loc5`='裝置顯示你已經非常靠近出現異象的地點。', `MaleText_loc7`='El dispositivo indica que estás muy cerca de la anomalía.', `FemaleText_loc1`='이 장치가 당신이 이상 물체에 아주 가까이 다가갔음을 알리고 있습니다.', `FemaleText_loc4`='仪器表明你已经非常接近异常位置了。', `FemaleText_loc5`='裝置顯示你已經非常靠近出現異象的地點。', `FemaleText_loc7`='El dispositivo indica que estás muy cerca de la anomalía.' WHERE `ID`=69800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 키린 토가 마치 우리의 구원자이기라도 한 것처럼 그들에게 머리를 숙이는군. 얼라이언스의 배신을 잊지 마시오, 에이타스.', `MaleText_loc4`='你一味对肯瑞托卑躬屈膝，好像他们才是我们的救世主。别忘了他们的背叛，艾萨斯。', `MaleText_loc5`='你繼續臣服於祈倫托，視他們為我們的救星。但是千萬別忘了他們的陰謀，埃薩。', `MaleText_loc7`='Sigues arrodillándote ante el Kirin Tor como si fueran nuestros salvadores. No olvides su traición, Aethas.' WHERE `ID`=69801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 신도레이요! 누구에게도 머리를 숙일 필요가 없소. 키린 토에게도, 얼라이언스에게도, 그리고 물론 호드에게도.', `MaleText_loc4`='我们是辛多雷！我们不应向任何人低头，无论是肯瑞托，还是联盟，更不用说部落了。', `MaleText_loc5`='我們是辛多雷!我們不應向任何人屈服，包括祈倫托、聯盟、當然也包括部落。', `MaleText_loc7`='¡Somos los sin''dorei! No deberíamos arrodillarnos ante nadie. Ni ante el Kirin Tor, ni ante la Alianza, ni mucho menos ante la Horda.' WHERE `ID`=69802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='언제나 성급하군, 젊은이. 힘이 되지 않는 지식은 없소. 이 유물은 천상의 종과 비슷한 시기까지 거슬러 올라가는 물건이오. 이 유물의 비밀을 밝혀내면 우리는 가로쉬의 목표물에 더 가깝게 다가갈 수 있을 거요.', `MaleText_loc4`='你总是这么毛躁，年轻人。没有什么知识是无用的。这件神器的历史能与圣钟相媲美。只要解开它的秘密，我们就能一进步了解加尔鲁什的战利品。', `MaleText_loc5`='年輕人，你們太沒有耐性了。知識就是力量。這個神器跟聖鐘一樣古老，而且瞭解它的秘密還有助於找到卡爾洛斯要的東西。', `MaleText_loc7`='Siempre tan impaciente... No existe conocimiento que no sea poder. Este artefacto data de la misma época que la Campana divina. Conocer sus secretos nos acerca al tesoro de Garrosh.' WHERE `ID`=69803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 위험하긴 하지. 그렇지 않다면 이 유물에 무슨 쓸모가 있겠소?', `MaleText_loc4`='当然，它还是很危险的。否则，这件神器的秘密对我们就毫无价值了。', `MaleText_loc5`='沒錯，它當然很危險。要是不危險，它的秘密對我們又有何用處?', `MaleText_loc7`='Por supuesto que es peligroso. Si no lo fuera, sus secretos no nos harían falta.' WHERE `ID`=69804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장에게 머리를 숙이는 건 좀 낫습니까? 가로쉬는 이 모구 유물에 엄청나게 집착하고 있어요. 이런 집착은 캘타스가 우리 일원이었을 때 이후로 본 적이 없습니다.', `MaleText_loc4`='可向酋长低头就对了吗？加尔鲁什对这些魔古神器的痴迷程度简直让我想起了凯尔萨斯。', `MaleText_loc5`='難道臣服於大酋長就比較好嗎?卡爾洛斯對這些魔古法器的著迷程度，簡直就跟當年的凱爾薩斯一樣。', `MaleText_loc7`='¿Y arrodillarse ante el Jefe de Guerra es mejor? No he visto obsesión como la que tiene Garrosh por esos artefactos mogu desde que Kael''thas estaba con nosotros.' WHERE `ID`=69805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롬매스, 동맹이 없다면 우린 이 전쟁의 물결에 휩쓸려 만신창이가 되고 말 겁니다. 가로쉬에겐 중도라는 게 없어요. 그를 따르든가, 아니면 맞설 수밖에 없습니다.', `MaleText_loc4`='罗曼斯，要是没有盟友支持，我们只会在这场战争中粉身碎骨。对加尔鲁什，我们没有保持中立的余地。我们要么追随他，要么就得反抗他。', `MaleText_loc5`='洛摩斯，沒有盟友，我們必定會被這場戰爭的浪潮淹沒。你無法跟卡爾洛斯虛與委蛇，要嘛就是支持他，要嘛就是徹底反抗他。', `MaleText_loc7`='Rommath, si no tenemos aliados, las mareas de esta guerra nos arrasarán. Con Garrosh no existe término medio. O estamos con él o estamos contra él.' WHERE `ID`=69806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 이미 모구가 살아 있는 에너지를 장치 안에 가두는 데 능하다는 걸 압니다. 이건 더 밝혀내야 할 마법이 아닙니다.', `MaleText_loc4`='我们已经知道，魔古族拥有将生命能量禁锢在仪器中的能力。我们对这种法术所知不多。', `MaleText_loc5`='我們已經知道，魔古精通於將生命能量囚封在各種法器裡，但是我們沒必要再繼續鑽研這類題材。', `MaleText_loc7`='Ya sabemos que los mogu dominaban el arte de apresar energía vital en artefactos. No nos hace falta saber más sobre esa magia.' WHERE `ID`=69807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬의 목표이지, 우리 목표가 아닙니다. 제 말 잘 들으세요. 이 장치는 위험하다고요.', `MaleText_loc4`='那是加尔鲁什的战利品，不是我们的。记住我的话，这个想法很危险。', `MaleText_loc5`='那是卡爾洛斯要的，不是我們要的。記住我的話，這個東西太危險了。', `MaleText_loc7`='El tesoro de Garrosh, no el nuestro. Recuerda mi advertencia: ese ensamblaje es peligroso.' WHERE `ID`=69808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 추적자... 악마의 소환사... 어둠의 주인...', `MaleText_loc4`='混沌的追随者……恶魔的召唤者……暗影的掌控者……', `MaleText_loc5`='混沌的追尋者... 惡魔的召喚師... 影之力的使用者...', `MaleText_loc7`='Buscador del caos... Invocador de demonios... Maestro de las sombras...' WHERE `ID`=69809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시... 그 귀하고 찾기 힘든 아뮬렛이 하나 더 있으신가요?', `MaleText_loc4`='你那里还有那种超级稀有、很难找到的护符吗？', `MaleText_loc5`='你會不會碰巧還有個超級難找、超級稀有的護身符呢?', `MaleText_loc7`='¿No tendrás por casualidad otro de esos amuletos ultra raros casi imposibles de encontrar?', `FemaleText_loc1`='혹시... 그 귀하고 찾기 힘든 아뮬렛이 하나 더 있으신가요?', `FemaleText_loc4`='你那里还有那种超级稀有、很难找到的护符吗？', `FemaleText_loc5`='你會不會碰巧還有個超級難找、超級稀有的護身符呢?', `FemaleText_loc7`='¿No tendrás por casualidad otro de esos amuletos ultra raros casi imposibles de encontrar?' WHERE `ID`=69810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 부류는 우리 시선에서 벗어나지 못했다, $c.', `MaleText_loc4`='你们的存在逃不出我们的注意，$c。', `MaleText_loc5`='你們的存在，並沒有被我等忽視，$c。', `MaleText_loc7`='La existencia de tu gente no ha pasado inadvertida, $c.' WHERE `ID`=69811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단과 마찬가지로, 너희는 모든 것을 집어삼키는 혼돈을 자신의 의지로 휘두르려고 끊임없이 노력한다.', `MaleText_loc4`='就像伊利丹，你总是努力想要掌控那消磨心志的混沌之力。', `MaleText_loc5`='如同伊利丹，你不斷努力駕馭能吞食一切的混沌，使其屈服於你的意志。', `MaleText_loc7`='Al igual que Illidan, te esfuerzas constantemente por doblegar el caos que todo lo devora bajo tu voluntad.' WHERE `ID`=69812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 궁극의 힘과 완전한 타락 사이를 걷는다.', `MaleText_loc4`='你是在绝对的强权和彻底的堕落间走钢丝。', `MaleText_loc5`='你走在絕對的力量，與絕對的毀滅之間。', `MaleText_loc7`='Recorres el límite entre el poder absoluto y la corrupción total.' WHERE `ID`=69813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문은 2천 년도 넘는 시간 동안 달라란의 동맹이었소. 우리의 그 ''존경받는 대족장님'' 가로쉬의 변덕 따위 때문에 가볍게 던져 버릴, 그런 우정이 아니란 말이오.$b$b아... 유물에 볼일이 있어서 온 거요?', `MaleText_loc4`='银月城与达拉然的盟约长达2000余年。这段友谊决不能因为我们“可敬”的加尔鲁什酋长一时兴起而被轻易抛弃。$b$b哦……你是为神器而来的？', `MaleText_loc5`='銀月城和達拉然已經維繫了超過2000年的同盟關係。不該只為了我們「敬愛的」大酋長卡爾洛斯任性的幾句話就拋棄如此珍貴的友誼。$b$b哦...你來是為了那件神器的事情?', `MaleText_loc7`='Lunargenta es aliada de Dalaran desde hace más de 2000 años. No se trata de una amistad que se pueda olvidar por capricho de nuestro "estimado" Jefe de Guerra Garrosh.$b$bAh, ¿has venido por el artefacto?' WHERE `ID`=69814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스가 불타는 군단과 싸워 살아남았듯이, 너도 네 안의 어둠을 이겨내고 통제할 수 있게 되었다.', `MaleText_loc4`='艾泽拉斯击退了燃烧军团，你也战胜了你内心的黑暗并控制了它。', `MaleText_loc5`='正如艾澤拉斯成功抵抗了軍團的入侵，你也面對並且戰勝了自己心中的黑暗。', `MaleText_loc7`='Al igual que Azeroth ha luchado contra la Legión y ha sobrevivido, tú te has enfrentado a la oscuridad de tu interior y la has controlado.' WHERE `ID`=69815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일리단은 실패했지만 너는 성공할 수 있을지 모른다... 너는 우주의 부조화를 받아들일 수 있으리라.', `MaleText_loc4`='或许你能做到伊利丹没能做到的事……或许你能接受这个宇宙的无序。', `MaleText_loc5`='或許，你可以辦到伊利丹失敗的事情... 或許，你能接受這宇宙的無序。', `MaleText_loc7`='A lo mejor tú triunfarás donde Illidan fracasó... A lo mejor tú eres capaz de aceptar el desorden de este universo.' WHERE `ID`=69816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제이나 프라우드무어가 키린 토의 수장으로서 달라란을 지배하고 있소.$b$b그건 보랏빛 성채를 얼라이언스의 손에 넘겨준 거나 다름없소. 에이타스가 아무리 키린 토의 중립성에 대해 떠들어 봤자 말이오.$b$b이 젊은이는 잊었나 본데, 얼라이언스는 3차 대전쟁 중에 우리 민족을 가두고 학살하려 했었소.$b$b에이타스가 믿는 키린 토의 그... "중립성"을 내가 믿지 않는다 해서 나무라지 마시오.', `MaleText_loc4`='现在，吉安娜·普罗德摩尔成了肯瑞托的领袖和达拉然的统治者。$b$b无论艾萨斯如何鼓吹所谓的中立，这都无异于将这座城市交于联盟之手。$b$b这位年轻的新贵或许已经忘了，可联盟曾在第三次大战时试图囚禁并屠杀我们的人民。$b$b很抱歉我无法认同他所谓的……“中立”观念。', `MaleText_loc5`='珍娜·普勞德摩爾如今已是統治達拉然的祈倫托領袖。$b$b不論埃薩如何吹噓，紫羅蘭城塞實質上已經落入了聯盟的手中。$b$b這個年輕人或許忘了，但是在第三次大戰的時候，聯盟確實曾企圖囚禁和屠殺我們的同胞。$b$b所以請你見諒，我一點也不相信他所深信的...「中立」立場。', `MaleText_loc7`='Jaina Valiente es la nueva líder del Kirin Tor y gobierna Dalaran.$b$bEso deja la ciudadela en manos de la Alianza, por mucho que a Aethas le guste presumir de neutralidad.$b$bA lo mejor a este joven se le ha olvidado, pero la Alianza intentó encerrarnos y masacrarnos durante la Tercera Guerra.$b$bPerdona si no comparto su fe en su "neutralidad".' WHERE `ID`=69817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 우리가 거닐 수 없는 곳을 디딘다. 너희는 다른 이들이 소멸하는 곳에서도 살아남는다.', `MaleText_loc4`='你们可以达到我们无法企及的领域。你们可以在九死一生的恶劣环境下顽强生存。', `MaleText_loc5`='你們能到達我們到達不了的地方，你們能在他人活不下的地方活下。', `MaleText_loc7`='Tu gente puede pisar suelo que nos está vedado. Tu gente puede sobrevivir donde otros morirían.' WHERE `ID`=69818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칸레타드가 생성하려고 했던 유물은 완전하지 않다.', `MaleText_loc4`='坎雷萨德试图制造的神器并不完整。', `MaleText_loc5`='坎瑞薩德企圖創造的神器仍未完成。', `MaleText_loc7`='El artefacto que Kanrethad ansiaba completar aún no está terminado.' WHERE `ID`=69819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물은 보다 광범위하게 마법을 구현할 수 있는 능력을 주지만... 사용자는 곧 통제력을 잃어버리고 만다.', `MaleText_loc4`='它能赋予凡人大规模施法的能力……可他们很快就会无法控制那股力量。', `MaleText_loc5`='它具有施展大規模魔法的能力... 但他們很快就控制不住那股力量。', `MaleText_loc7`='Otorga la capacidad de realizar magia a gran escala... pero se pierde el control de ese poder muy rápidamente.' WHERE `ID`=69820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 섭정님의 연구 결과를 요구하십니다.', `MaleText_loc4`='酋长要看你们的研究成果。', `MaleText_loc5`='大酋長要你們交出研究的成果。', `MaleText_loc7`='El Jefe de Guerra exige resultados en tu investigación.', `FemaleText_loc1`='대족장님께서 섭정님의 연구 결과를 요구하십니다.', `FemaleText_loc4`='酋长要看你们的研究成果。', `FemaleText_loc5`='大酋長要你們交出研究的成果。', `FemaleText_loc7`='El Jefe de Guerra exige resultados en tu investigación.' WHERE `ID`=69821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 수정의 힘을 해방시키겠다. 하지만 오직 너만이 그 힘을 어떻게 사용할 것인지 결정할 수 있다.', `MaleText_loc4`='我可以解开水晶的力量，可只有你才能决定如何使用它。', `MaleText_loc5`='我會解開水晶的力量，但是只有你能決定該如何使用它的力量。', `MaleText_loc7`='Desataré el poder del cristal, pero solo tú puedes decidir cómo usarlo.' WHERE `ID`=69822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명하게 선택해라, $n.', `MaleText_loc4`='你一定要谨慎选择，$n。', `MaleText_loc5`='請做出明智的抉擇，$n。', `MaleText_loc7`='Elige con prudencia, $n.' WHERE `ID`=69823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 그런 문제를 논하기에 적합한 장소가 아니오. 원정순찰대 광장 지하에 있는 방에서 봅시다.$b$b아, 무장하고 오시오. 그대의 실력이 필요할 것 같으니.', `MaleText_loc4`='这里不是讨论这种事的地方。请到远行者广场下的大厅来找我。$b$b哦，记得带上武器。我想我们会用到你的力量。', `MaleText_loc5`='這裡不是談這件事情的好地方。到遠行者廣場底下來找我。$b$b哦對了，帶好武器，我有預感我們會需要用到你的本事。', `MaleText_loc7`='Este no es lugar para hablar. Ven a verme a la cámara bajo la Plaza del Errante.$b$bAh, y trae tus armas. Creo que nos harán falta tus habilidades.' WHERE `ID`=69824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마들의 공격이 멈췄네... 무슨 일이 일어난 거지?!', `MaleText_loc4`='恶魔停止攻击了……这里出什么事了？！', `MaleText_loc5`='惡魔停止攻擊了...這是怎麼回事?!', `MaleText_loc7`='Los demonios ya no atacan... ¡¿qué ha pasado aquí?!' WHERE `ID`=69825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍의 눈... 그 유물을 찾아내기 위해서만도 수많은 전투가 벌어졌네. 지리가 그것을 왜 자네에게 맡겼는지는 모르겠지만, $c|1이여;여;... 조심하게... 그 힘을 손에 넣은 자는 모두 크나큰 대가를 치렀네.', `MaleText_loc4`='风暴之眼……为了寻找那件神器，曾爆发过无数惨烈的大战。我不知道为什么克希利会把它交给你，$c……可你一定要小心……掌握它的人无一不付出了惨重的代价。', `MaleText_loc5`='暴風之眼...為了找到這件神器，不知引起了多少紛爭與戰鬥。我不清楚為什麼希瑞要把它交給你保管，$c...但是我得警告你...凡是施放它力量的人，全都付出了極大的代價。', `MaleText_loc7`='El Ojo de la Tormenta... Se han librado innumerables batallas solo para encontrar ese artefacto. No sé por qué te lo confió Xi''ri, $c, pero te lo advierto: nadie ha controlado su poder sin pagar un precio mayor.' WHERE `ID`=69826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예로운 만남이군, $c. 이곳 판다리아에서의 내 형제들에 대한 소문을 들었네. 불화에 대한 걱정스럽고 암울한 소식이었지.$B$B내가 직접 여기 온 것은 호드의 활동을 돕기 위해서기도 하지만... 일이 모두의 손을 지나치게 벗어나지는 않게 하기 위함이기도 하네.', `MaleText_loc4`='幸会，$c。我从在潘达利亚的兄弟们那里听到了一些传言。一些负面的抱怨和忧虑。$B$B我本人很支持部落的事业，可同时……也不希望事态过于失控。', `MaleText_loc5`='很榮幸見到你，$c。我從派駐在潘達利亞的弟兄聽到了些消息...不安與不合的消息。$B$B雖然我是來支援部落的行動，但同時也是為了確保事情不會... 失控得太嚴重。', `MaleText_loc7`='Es un honor reunirme contigo, $c. Mis hermanos en Pandaria me han contado historias preocupantes, rumores oscuros de disensión y nerviosismo.$b$bHe venido en persona para apoyar la causa de la Horda... y para asegurarme de que la situación no se vuelve insostenible.' WHERE `ID`=69828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 우리 바리안 폐하께서 키린 토의 도움을 구하려고 당신도 보내셨나 보군요?', `FemaleText_loc4`='你也是亲爱的瓦里安国王派来请求协助的吗？', `FemaleText_loc5`='瓦里安國王也派了你來尋求我們的協助嗎?', `FemaleText_loc7`='¿El bueno del rey Varian te ha enviado a pedirnos ayuda?' WHERE `ID`=69829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 승리를 위해 나서라는 명령을 내릴 겁니다!', `MaleText_loc4`='我会带领肯瑞托加入联盟，并取得胜利！', `MaleText_loc5`='我會致力於讓聯盟勝利!', `MaleText_loc7`='¡Querría que nuestra orden apoyara la victoria de la Alianza!', `FemaleText_loc1`='얼라이언스의 승리를 위해 나서라는 명령을 내릴 거예요!', `FemaleText_loc4`='我会带领肯瑞托加入联盟，并取得胜利！', `FemaleText_loc5`='我會致力於讓聯盟勝利!', `FemaleText_loc7`='¡Querría que nuestra orden apoyara la victoria de la Alianza!' WHERE `ID`=69830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p 님, 우리는 크라사랑으로 돌아가서 이 문제를 의논해봐야 해요. 지금 일은 도와주셔서 감사해요. 원하실 때 언제라도 사자의 상륙지로 돌아갈 수 있는 차원문이 있어요.', `MaleText_loc4`='$p，我们得讨论一下卡桑琅的情况。多亏了你的帮助，现在我们开通了一座通往雄狮港的传送门。你可以随时用它返回雄狮港。', `MaleText_loc5`='$p，謝謝你的協助，但我們還是得回喀撒朗蠻荒做進一步的討論。等你準備好的時候，那座傳送門可以送你回雄獅灘。', `MaleText_loc7`='$p, deberíamos hablar en Krasarang. Por ahora, te agradezco tu ayuda. Hay un portal que te devolverá al Desembarco del León cuando lo desees.' WHERE `ID`=69831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뚫린 입이라고 마음대로 지껄이지 마라, 블러드 엘프! 네가 감히 대족장님의 뜻에 의문을 던지는 거냐?', `MaleText_loc4`='管好你的舌头，血精灵！你竟敢质疑酋长的决定？', `MaleText_loc5`='住口，血精靈!你膽敢質疑大酋長的判斷?', `MaleText_loc7`='¡Cuida esa lengua, elfo de sangre! ¿Te atreves a cuestionar el juicio del Jefe de Guerra?' WHERE `ID`=69832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정해라, 이시. 여기 섭정도 자신의 생각을 털어놓을 수 있어야지.', `MaleText_loc4`='冷静点，伊什。让摄政王说出他的想法。', `MaleText_loc5`='冷靜點，伊什。就讓攝政王把話講明白。', `MaleText_loc7`='Tranquilo, Ishi. Deja que el señor regente diga lo que piensa.' WHERE `ID`=69833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두 발로 땅을 딛고 서 있다니.$b$b어릴 때 유랑도에서 듣던 대로 정말 아름다운 곳입니다. 물고기가 조금만 더 크면 좋았겠지만요.', `MaleText_loc4`='我们已经踏上了南方大陆的土地。$b$b这里就跟我小时候在迷踪岛上听过故事里一样美丽。只是这里的鱼个头更大。', `MaleText_loc5`='我們總算來到下方這塊大陸了。$b$b這裡就跟我小時候在漂流島上聽到的故事一樣漂亮。只是，魚沒那麼大而已。', `MaleText_loc7`='Aquí estamos, en las tierras del sur.$b$bEs tan hermoso como decían las historias que me contaban en La Isla Errante, cuando era un cachorro. Aunque los peces podrían ser más grandes.' WHERE `ID`=69834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 행운의 상징을 망가뜨리다니! 널 부숴버리겠다!', `MaleText_loc4`='你敢破坏我的好运气？那我就打破你的头！', `MaleText_loc5`='打壞我的好運?我要打壞你!', `MaleText_loc7`='¿TÚ MACHACAS MI BUENA SUERTE? ¡PUES YO TE MACHACO A TI!' WHERE `ID`=69835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린은 딱히 행운을 가져오지 않더구나!', `MaleText_loc4`='地精都是倒霉蛋！', `MaleText_loc5`='哥布林根本沒好運!', `MaleText_loc7`='¡EL GOBLIN NO TENÍA NADA DE SUERTE!' WHERE `ID`=69836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 널 짓밟은 다음, 다른 녀석을 찾아봐야겠다!', `MaleText_loc4`='等我踩扁你之后，我会再弄一个幸运符的！', `MaleText_loc5`='踩扁你以後我再弄一個!', `MaleText_loc7`='¡DESPUÉS DE MACHACARTE IRÉ A POR OTRO!' WHERE `ID`=69837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린은 네게 아무 짓도 하지 않았다, 이 나쁜 녀석아!', `MaleText_loc4`='地精都比你强。你这蠢货！', `MaleText_loc5`='哥布林沒對你怎樣。你是壞壞!', `MaleText_loc7`='EL GOBLIN NO TE HA HECHO NADA. ¡ERES $gMALO:MALA;!' WHERE `ID`=69838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 어깨가... 너무 무거워...', `MaleText_loc4`='这副肩甲……太重了……', `MaleText_loc5`='肩膀... 好重...', `MaleText_loc7`='CUÁNTO PESAN... LAS HOMBRERAS...' WHERE `ID`=69839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 부수고, 너는 죽는다. 받아들여라!', `MaleText_loc4`='我一挥手，你就死了。接招吧！', `MaleText_loc5`='我打打。你死死。我打打!', `MaleText_loc7`='YO MACHACO. TÚ MUERES. ¡RESÍGNATE!' WHERE `ID`=69840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 부서졌다!', `MaleText_loc4`='你死定了！', `MaleText_loc5`='我要打打你!', `MaleText_loc7`='¡TE HE MACHACADO!' WHERE `ID`=69841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한쪽 편을 들어선 안 된다고 확신하십니까?', `MaleText_loc4`='你真的没法选择其中一方吗？', `MaleText_loc5`='你真的沒辦法選一邊嗎?', `MaleText_loc7`='¿Seguro que no pueden elegir un bando?', `FemaleText_loc1`='한쪽 편을 들어선 안 된다고 확신하시나요?', `FemaleText_loc4`='你真的没法选择其中一方吗？', `FemaleText_loc5`='你真的沒辦法選一邊嗎?', `FemaleText_loc7`='¿Seguro que no pueden elegir un bando?' WHERE `ID`=69842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔은 이런 곳에서 시간을 보내는 것도 괜찮다네. 우리가 왜 싸우는지를 똑똑히 알 수 있으니 말일세.', `MaleText_loc4`='时不时来这种地方消遣一下是不错的选择，它能让我们回想起自己努力奋战究竟是为了守护什么。', `MaleText_loc5`='能到這地方來走走是件很好的事情，我們不能忘記，我們辛辛苦苦保護的東西究竟是什麼。', `MaleText_loc7`='Viene bien pasar un tiempo en un sitio así para recordarnos qué es lo que tanto nos esforzamos por proteger.' WHERE `ID`=69843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='准备好了。', `MaleText_loc5`='準備好了。', `MaleText_loc7`='Listo.', `FemaleText_loc1`='준비됐습니다.', `FemaleText_loc4`='准备好了。', `FemaleText_loc5`='準備好了。', `FemaleText_loc7`='Lista.' WHERE `ID`=69844;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 걱정은 말아요, 고엘. 볼진이 그렇게 생각한다면 당신은 최대한 그의 형제들을 도와야죠.', `FemaleText_loc4`='不用着急，古伊尔。如果沃金相信他的人民正处在危险之中，那你最好尽力帮助他们。', `FemaleText_loc5`='需要待多久就待多久，高爾。既然沃金相信他的族人有危險，你一定得盡全力幫助他們。', `FemaleText_loc7`='Tómate todo el tiempo que haga falta, Go''el. Si Vol''jin cree que su pueblo está en peligro, deberías ayudarles en todo lo posible.' WHERE `ID`=69845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄, 우리는 더 이상 당신을 따르지 않는다. 우리는 새로운 대족장을 섬긴다. 그리고 그분께서는 말씀하셨다. 우리는 강하다고!', `MaleText_loc4`='萨尔，我们不再听命与你了。我们有了一位新酋长。是他提醒我们要坚强！', `MaleText_loc5`='索爾，我們已經不再聽你指揮。現在我們有新的大酋長了，而且他讓我們知道，其實我們有多強!', `MaleText_loc7`='Thrall, ya no respondemos ante ti. Ahora tenemos un nuevo Jefe de Guerra, ¡uno que nos ha recordado que somos FUERTES!' WHERE `ID`=69846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 내가 예상했던 것보다 훨씬 심각하군.', `MaleText_loc4`='这比我想的还要糟糕。', `MaleText_loc5`='情況比我原先料想的還糟。', `MaleText_loc7`='Esto es peor de lo que pensaba.' WHERE `ID`=69847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이에 맞설 상대는... 천둥왕의 추종자, 일촉즉발의 비안입니다!', `FemaleText_loc4`='我们的另一边，则是雷电之王的狂热追随者，瓦安！', `FemaleText_loc5`='另一邊角落的是雷王麾下的火焰使者，『暴烈』維安!', `FemaleText_loc7`='¡En la otra esquina está Vian, el flamígero seguidor del Rey del Trueno!' WHERE `ID`=69848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='투기장에 피머리가 등장합니다! 당신을 피투성이로 만들 겁니다. 저 머리로요!', `FemaleText_loc4`='另一位进入竞技场的是：血角！他会用你的鲜血染红他的角！', `FemaleText_loc5`='同時進入競技場的是: 牴角!這名字正是因為牠會用頂角去牴刺你。', `FemaleText_loc7`='También entra en la arena... ¡Cocosangre! Famoso por intentar hacerte sangrar con su coco.' WHERE `ID`=69849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뜨거운 고통을 좋아하는 여러분의 친구, 던전 인도자 비샤스입니다!', `FemaleText_loc4`='我们还要欢迎广受痛苦爱好者追捧的：地下城主韦沙斯！', `FemaleText_loc5`='此外，我們還要歡迎，幸災樂禍的觀眾們的最愛: 刑求大師韋沙斯!', `FemaleText_loc7`='También damos la bienvenida a uno de los combatientes favoritos del público: ¡el amo del calabozo Vishas!' WHERE `ID`=69850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이야! 오늘 누가 나타났나 보세요... 브랏입니다!', `FemaleText_loc4`='嘿嘿！请看我们今日为大家带来的……布拉特！', `FemaleText_loc5`='嘿嘿嘿!看看今天我們為大家準備了什麼... 吞齧怪!', `FemaleText_loc7`='¡Oye! Mira lo que hemos atrapado para ti: ¡Blat!' WHERE `ID`=69851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='5대 1은 불공평한 것 같지만... 반쯤 죽은 노움이니까 봐줍시다. 오염된 노움 5인조입니다!', `FemaleText_loc4`='五对一看来似乎不太公平，可拜托……那只是一群半死不活的侏儒而已。欢迎我们的麻风侏儒五人组！', `FemaleText_loc5`='五打一好像很不公平... 可是拜託，他們不過是半死半活的地精而已!歡迎痲瘋地精五人組!', `FemaleText_loc7`='Cinco contra uno no suena justo, pero vaya, son gnomos medio muertos. ¡Es el quinteto de gnomos parias!' WHERE `ID`=69852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이어서, 배틀트론이 투기장에 나타났습니다! 네, 뭐, 고블린 기계공학으로 만들어진 건 아니지만... 그래도 무시무시합니다!', `FemaleText_loc4`='同时进场的还有——巴特隆！当然，他不是由地精制造的……可他依然有着致命的威胁！', `FemaleText_loc5`='同時進入競技場的是: 戰魔像!雖然，不是哥布林的工程產品...還是會把你給宰了!', `FemaleText_loc7`='También entra en la arena... ¡el Batallatrón! Es posible que no sea ingeniería goblin, ¡pero puede matarte igualmente!' WHERE `ID`=69853;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상대편에는... 아, 저거 보세요! 제 친구 프란입니다! 탈것을 새로 장만한 모양이네요!', `FemaleText_loc4`='另一边进场的是……嘿，看呐！那是我的好兄弟，法兰！他还带来了他的坐骑！', `FemaleText_loc5`='另一邊的角落... 嘿，大家看!是我的好兄弟弗蘭!而且還把他的坐騎給帶來了!', `FemaleText_loc7`='En la otra esquina... ¡Miren! ¡Es mi colega Fran! ¡Y se ha traído a su montura!' WHERE `ID`=69854;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두가 좋아하는 얼음 날개 친구, 디피에게 환영의 박수를 보내주세요!', `FemaleText_loc4`='我们还要欢迎人见人爱的白色小伙伴：帝皮！', `FemaleText_loc5`='我們也要歡迎，大家最喜歡的、冰涼涼的企鵝朋友: 呆呆!', `FemaleText_loc7`='También damos la bienvenida al amiguito emplumado y helado al que todo el mundo quiere: ¡Chapuzón!' WHERE `ID`=69855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='실리더스에서 빙빙 돌며 방황하고 있던 녀석을 이번에 발견했습니다. 보아하니 누군가에게 공격을 받아 죽을 뻔한 모양이네요. 익스입니다!', `FemaleText_loc4`='我们在希利苏斯的法阵里发现了这个钻洞的家伙。当时他已经被人打得半死。他就是，伊克西！', `FemaleText_loc5`='我們在希利蘇斯看到這傢伙繞圈圈爬來爬去，而且好像已經被人給宰掉了。歡迎伊克斯!', `FemaleText_loc7`='A este lo encontramos vagando en círculos por Silithus. Parece que alguien ya casi lo mató. ¡Es Ixx!' WHERE `ID`=69856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상대는... 파괴광입니다! 우스꽝스러운 노움 홀로그램 영사기도 함께요!', `FemaleText_loc4`='同时进场的还有——位元毁灭者……以及他那滑稽的侏儒全息投影仪！', `FemaleText_loc5`='同時進入競技場的是: 壞滅位元... 以及他荒謬的地精全像投影機!', `FemaleText_loc7`='También entra en la arena... ¡Destructobyte y su ridícula maquinaria holográfica gnómica!' WHERE `ID`=69857;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 상대는... 항상 분노하고, 항상 무시무시하지만, 또 어딘가 사랑스러운 구석이 있는... 네베레스트 출신, 쾅쾅이입니다!', `FemaleText_loc4`='再看这边！他怒气冲冲。他所向披靡。他还有点小可爱。他就是来自不息山的压路者！', `FemaleText_loc5`='另外這邊的角落!是憤怒的、致命的、又有點可愛的、來自奈佛勒斯的 - 碾大力!', `FemaleText_loc7`='Y en esta esquina... Está enfadado... Es letal... Es un poco adorable... Recién salido del Nieverest... ¡es Amasijo!' WHERE `ID`=69858;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 아가씨는 우아한 드레스를 입고 무릎이 반대로 꺾여 있긴 하지만, 언제든 당신을 짓밟을 수 있습니다. 도미니카를 박수로 맞아 주십시오!', `FemaleText_loc4`='没错，她穿着裙子，她的脚关节还是反着长的，可她照样能痛扁你一顿。她就是多米尼卡！', `FemaleText_loc5`='嘿，雖然她穿著漂亮的洋裝，雖然她的膝蓋彎的角度不太一樣，不過她還是可以把你踩扁在地上爬不起來。歡迎多明妮卡!', `FemaleText_loc7`='Sí, lleva un vestido y sus rodillas se doblan en ambos sentidos, pero eso no le impedirá machacarte. ¡Es Dominika!' WHERE `ID`=69859;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다음 상대는 제가 지금껏 본 중에서 가장 약하고, 못생기고, 덜떨어진 싸움꾼이군요. 멍청하고 악취가 나는 노움, 밀리 와트입니다! 모두들 야유를 보내세요!', `FemaleText_loc4`='下面这位，或许是我见过的最无能、最丑陋、最没天分的拳手。它就是又笨又臭的侏儒，米莉·沃特！大家来点嘘声吧！', `FemaleText_loc5`='下一個，八成是我看過最弱的、最醜的、最不聰明的參賽者。歡迎傻不啷噹、臭不隆咚的米莉耶·瓦特!大家一起噓吧!', `FemaleText_loc7`='Y ahora toca la combatiente más débil, más fea y menos lista que he visto jamás. Es la gnoma estúpida y apestosa... ¡Millie Vatio! ¡Abuchéenla todos!' WHERE `ID`=69860;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숄라자르 분지에서 저 친구를 찾느라고 며칠이 걸렸습니다. 밀림에 오신 것을 환영합니다! 마즈하린!', `FemaleText_loc4`='我们在索拉查盆地花了数天功夫才找到这家伙。欢迎来到丛林！他就是，玛扎伦！', `FemaleText_loc5`='我們花了好幾天的時間才在休拉薩盆地找到這傢伙。歡迎來到叢林!歡迎梅颯靈!', `FemaleText_loc7`='Nos pasamos días buscando a esta en la Cuenca de Sholazar. ¡Bienvenidos a la selva! ¡Es Mazhareen!' WHERE `ID`=69861;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노장 분들은 이 친구를 기억하실지도 모르겠네요. 네, 뒤틀린 친구이긴 하지만, 오늘만은 상대를 뒤틀어 버리려고 합니다! 아카마!', `FemaleText_loc4`='你们中的一些老兵或许还记得这家伙。没错，他是有点支离破碎的，可他也能砸扁你！他就是，阿卡玛！', `FemaleText_loc5`='資深人士應該還記得這傢伙。是啊是啊，他是個破碎者，但是他今天卻是要來把你弄破!!!把你弄碎!!!歡迎阿卡瑪!!!!', `FemaleText_loc7`='Es posible que algunos de los veteranos se acuerden de este tipo. Sí, es un tábido, ¡pero al final del combate también lo serás tú! ¡Es Akama!' WHERE `ID`=69862;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸울 상대는... 모두의 사랑을 한몸에 받는... 키가 3.5미터에 이르는 마법 시체! 피올입니다! 음... 발음이 이게 맞나요?', `FemaleText_loc4`='同时进场的还有——大家最喜爱的、12英尺高的神奇僵尸，弗琼！我没读错吧？', `FemaleText_loc5`='此外進場的是，大家最愛的12呎高魔法屍體，菲歐!!!! ...我有沒有念錯名字?', `FemaleText_loc7`='También entra en la arena... ¡su cadáver de cuatro metros mágico favorito, Fjoll! ¿Lo he pronunciado bien?' WHERE `ID`=69863;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우엑! 또 노움인가요? 저 녀석은 자기 이름이 밀하우스 마나스톰이랍니다. 어서 없애버리세요!', `FemaleText_loc4`='呃！又是侏儒？这一位似乎是自称米尔豪斯·法力风暴。快来干掉他吧！', `FemaleText_loc5`='呃啊!又是地精?看來，這傢伙自稱是米歐浩斯·曼納斯頓。快快出場把他給宰了!', `FemaleText_loc7`='¡Ugh! ¿Otro gnomo? Parece que este se hace llamar Molino Tormenta de Maná. ¡Sal ahí y mátalo!' WHERE `ID`=69864;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아킨둔에서 이 친구가 까악까악 울면서 폭풍을 일으키는 걸 발견했습니다. 이칸 이주에게 박수를 보내주세요!', `FemaleText_loc4`='我们在奥金顿找到了这位在风暴中嚎叫的家伙。大家鼓掌欢迎——伊坎·伊祖！', `FemaleText_loc5`='我們看到這傢伙在奧齊頓嘎嘎叫個不停。向伊坎·易祖臣服吧!', `FemaleText_loc7`='A este nos lo encontramos graznando como una tormenta en Auchindoun. ¡Aplaudan a Yikkan Izu!' WHERE `ID`=69865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두들 춤 출 준비를 하세요! 디켄이 나타났습니다!', `FemaleText_loc4`='大家一起来跳舞吧！迪肯来啦！', `FemaleText_loc5`='準備跳舞!歡迎迪肯出場!', `FemaleText_loc7`='¡Prepárense para bailar! ¡Aquí está Deeken!' WHERE `ID`=69866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='썬더 블러프에서 온 저 끔찍한 타우렌도 환영해 주세요! 스매시 후프스톰프입니다!', `FemaleText_loc4`='我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！', `FemaleText_loc5`='我們也歡迎潰擊·蹄踏，來自雷霆崖的恐怖牛頭人!', `FemaleText_loc7`='También damos la bienvenida a Machaque Hollapezuña, ¡el terrible tauren de Cima del Trueno!' WHERE `ID`=69867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상대는 젠샤르의 눈입니다! 다음은 뭐가 나타날까요? 커다란 코가 나타나려나요?!', `FemaleText_loc4`='另一边进场的是，长着无数眼睛的兹恩沙尔！下次还会有什么呢，一个会打架的鼻子吗？', `FemaleText_loc5`='另外一邊的角落是，很多很多眼睛的贊夏!! ...是怎樣，接著要換鼻子出場打架嗎?', `FemaleText_loc7`='¡En la otra esquina tenemos los muchos ojos de Zen''shar! ¿Qué será lo siguiente? ¿Una nariz guerrera?' WHERE `ID`=69868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참 안 어울리는 한 쌍입니다. 구역질이 나려고 하네요. GG 기계공학단이 나타났습니다!', `FemaleText_loc4`='他们的搭档完全是一个意外。事实上我对此颇为厌恶。他们就是，GG工程公司组合！', `FemaleText_loc5`='他們實在不該合夥的。事實上，還害我覺得有點噁心呢。接著入場的就是GG工程公司!', `FemaleText_loc7`='Esta colaboración es antinatural. De hecho, me pone enferma. ¡Aquí viene Ingeniería GG!' WHERE `ID`=69869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상대는... 암흑소환사입니다. 우와, 진짜 이름이 따로 없군요. 으스스합니다!', `FemaleText_loc4`='同时进场的还有：黑暗召唤师。哇，他连真名都没有。真恐怖！', `FemaleText_loc5`='另外進場的是: 黑暗召喚師!! 哇，他連名字都沒有，好可怕呦～～～～', `FemaleText_loc7`='También entra en la arena... el invocador oscuro. Guau, ni siquiera tiene nombre. ¡Qué miedo!' WHERE `ID`=69870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 바로 제가 원하는 겁니다! 공룡이 더 필요해요! 공룡왕 쿨라카!', `FemaleText_loc4`='接下来，正是我们最喜闻乐见的场面！拜托，再多来几条恐龙吧！有请，库拉卡大王！', `FemaleText_loc5`='對嘛，這才像樣!!拜託請給我們多來幾隻恐龍!!庫拉卡王!!', `FemaleText_loc7`='¡Ahora sí que sí! ¡Más dinosaurios, por favor! ¡Es el rey Kulaka!' WHERE `ID`=69871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='흐음... 기계공학 측면에서도 꽤 멋진 전투가 벌어지겠네요. 분열로봇이 나타났습니다!', `FemaleText_loc4`='嗯。接下来这位是名符其实的工程学杰作。下面是，干涉者时间！', `FemaleText_loc5`='嗯，這回的工程水準看起來相當高啊。歡迎裂衝登場!', `FemaleText_loc7`='Mmm. La verdad es que esa es ingeniería de la buena. ¡Es la hora del Disruptrón!' WHERE `ID`=69872;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 정말 운이 없군요! 프로보스쿠스입니다! 아하하하! 당신이 불길 속에서 죽는다에 25골드를 걸었어요!', `FemaleText_loc4`='哈哈哈！你可真够倒霉的！是普罗波库斯！啊哈哈哈！我敢出25个金币打赌，你肯定会被烧死的！', `FemaleText_loc5`='哈哈哈!你的運氣真的有夠背的!是普羅伯斯庫!哈哈哈哈，我出二十五金賭你會被火燒死!', `FemaleText_loc7`='¡Ja, ja, ja! ¡Qué mala suerte tienes! ¡Es Proboskus! ¡Ja, ja, ja, ja! Me apuesto veinticinco monedas de oro a que mueres en el fuego.' WHERE `ID`=69873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 조용히 하세요... 저 친구를 화나게 하면 안 됩니다. 조용히 감상하십시오. 살인기린 운구록스입니다!', `FemaleText_loc4`='各位，请安静……我们可不想激怒它。请屏息静气地欢迎我们的杀人鹿，乌古洛克斯！', `FemaleText_loc5`='大家安靜... 千萬別惹牠生氣。只要默默的、敬畏地看著昂格洛斯...殺人長頸鹿!!!', `FemaleText_loc7`='Que todo el mundo guarde silencio... No queremos que se enfade. Limítense a observar a Unguloxx, ¡la Asesinarafa!' WHERE `ID`=69874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 스톰윈드 대표입니다!', `MaleText_loc4`='$n代表暴风城出战！', `MaleText_loc5`='暴風城的代表是$n!', `MaleText_loc7`='¡$n representa a Ventormenta!' WHERE `ID`=69875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 아이언포지 대표입니다!', `MaleText_loc4`='$n代表铁炉堡出战！', `MaleText_loc5`='鐵爐堡的代表是$n!', `MaleText_loc7`='¡$n representa a Forjaz!' WHERE `ID`=69876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 놈리건 대표입니다!', `MaleText_loc4`='$n代表诺莫瑞根出战！', `MaleText_loc5`='諾姆瑞根的代表是$n!', `MaleText_loc7`='¡$n representa a Gnomeregan!' WHERE `ID`=69877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 다르나서스 대표입니다!', `MaleText_loc4`='$n代表达纳苏斯出战！', `MaleText_loc5`='達納蘇斯的代表是$n!', `MaleText_loc7`='¡$n representa a Darnassus!' WHERE `ID`=69878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 엑소다르 대표입니다!', `MaleText_loc4`='$n代表埃索达出战！', `MaleText_loc5`='艾克索達的代表是$n!', `MaleText_loc7`='¡$n representa a El Exodar!' WHERE `ID`=69879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 길니아스 대표입니다!', `MaleText_loc4`='$n代表吉尔尼斯出战！', `MaleText_loc5`='吉爾尼斯的代表是$n!', `MaleText_loc7`='¡$n representa a Gilneas!' WHERE `ID`=69880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1은;는; 투슈이 판다렌 대표입니다!', `MaleText_loc4`='$n代表土水派熊猫人出战！', `MaleText_loc5`='土水熊貓人的代表是$n!', `MaleText_loc7`='¡$n representa a los pandaren tushui!' WHERE `ID`=69881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 파릇파릇한 친구! 싸움 한 번 하실래요?', `MaleText_loc4`='嘿，小家伙！你想来打一场吧。', `MaleText_loc5`='嘿，廢材!有興趣打一場嗎?', `MaleText_loc7`='¡Oye, $gnovato:novata;! ¿Te interesa luchar?' WHERE `ID`=69882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다리게. 이 싸움은 끝까지 보고 싶으니까.', `MaleText_loc4`='请等我一分钟，我想看完这场比赛。', `MaleText_loc5`='等我一下，我先看完這場比賽。', `MaleText_loc7`='Dame un minuto, quiero terminar de ver este combate.', `FemaleText_loc1`='잠깐만 기다리게. 이 싸움은 끝까지 보고 싶으니까.', `FemaleText_loc4`='请等我一分钟，我想看完这场比赛。', `FemaleText_loc5`='等我一下，我先看完這場比賽。', `FemaleText_loc7`='Dame un minuto, quiero terminar de ver este combate.' WHERE `ID`=69883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐가 문제죠, $n? 싸움이 겁나요? 저기요, 투기장도 먹고 살아야죠!', `FemaleText_loc4`='怎么了，$n？不敢动手了吗？来吧，让竞技场沸腾起来吧！', `FemaleText_loc5`='怎麼回事$n?不敢打嗎?拜託，讓競技場熱鬧熱鬧嘛!', `FemaleText_loc7`='¿Qué pasa, $n? ¿Te da miedo luchar? ¡Venga, que no se enfríe el suelo de la arena!' WHERE `ID`=69884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금까지 $n|1이었;였;습니다.', `MaleText_loc4`='$g他:她;的名字是$n。', `MaleText_loc5`='$g他的:她的;名字叫做$n。', `MaleText_loc7`='Se llamaba $n.', `FemaleText_loc1`='지금까지 $n|1이었;였;습니다.', `FemaleText_loc4`='$g他:她;的名字是$n。', `FemaleText_loc5`='$g他的:她的;名字叫做$n。', `FemaleText_loc7`='Se llamaba $n.' WHERE `ID`=69889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멋진 승리였습니다, $n! 이제 다시 줄을 서세요.', `MaleText_loc4`='辉煌的胜利，$n！现在请回去排队。', `MaleText_loc5`='贏得漂亮，$n!好，給我回去排隊。', `MaleText_loc7`='¡Una victoria brillante, $n! Ahora vuelve a la cola.', `FemaleText_loc1`='멋진 승리였습니다, $n! 이제 다시 줄을 서세요.', `FemaleText_loc4`='辉煌的胜利，$n！现在请回去排队。', `FemaleText_loc5`='贏得漂亮，$n!好，給我回去排隊。', `FemaleText_loc7`='¡Una victoria brillante, $n! Ahora vuelve a la cola.' WHERE `ID`=69890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안됐네요, $n. 이제 그 시체 좀 치워 주실래요? 다음 싸움꾼들이 기다리고 있어서요.', `MaleText_loc4`='很抱歉，$n。现在，可以请你把自己的尸体弄走，好让下面的人继续比赛吗？', `MaleText_loc5`='抱歉，$n。麻煩請你把自己的屍體搬走，好讓別人可以趕緊開打?', `MaleText_loc7`='Lo siento, $n. ¿Te importa apartar tu cadáver para que prueben los demás?', `FemaleText_loc1`='안됐네요, $n. 이제 그 시체 좀 치워 주실래요? 다음 싸움꾼들이 기다리고 있어서요.', `FemaleText_loc4`='很抱歉，$n。现在，可以请你把自己的尸体弄走，好让下面的人继续比赛吗？', `FemaleText_loc5`='抱歉，$n。麻煩請你把自己的屍體搬走，好讓別人可以趕緊開打?', `FemaleText_loc7`='Lo siento, $n. ¿Te importa apartar tu cadáver para que prueben los demás?' WHERE `ID`=69891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솔직히 말할게요, $n... 대체 지금 뭘 하시는 건가요?', `MaleText_loc4`='说实话，$n……你到底出力了吗？', `MaleText_loc5`='坦白說，$n... 你到底有沒有在打?', `MaleText_loc7`='En serio, $n, ¿te has esforzado siquiera?', `FemaleText_loc1`='솔직히 말할게요, $n... 대체 지금 뭘 하시는 건가요?', `FemaleText_loc4`='说实话，$n……你到底出力了吗？', `FemaleText_loc5`='坦白說，$n... 你到底有沒有在打?', `FemaleText_loc7`='En serio, $n, ¿te has esforzado siquiera?' WHERE `ID`=69892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아이구... 그렇게 아팠으니 많이 성숙해지겠어요.', `MaleText_loc4`='要想收获，你就得先付出。', `MaleText_loc5`='要做煎蛋，你就得先打幾個蛋。', `MaleText_loc7`='Para hacer una tortilla hay que romper unos huevos.', `FemaleText_loc1`='아이구... 그렇게 아팠으니 많이 성숙해지겠어요.', `FemaleText_loc4`='要想收获，你就得先付出。', `FemaleText_loc5`='要做煎蛋，你就得先打幾個蛋。', `FemaleText_loc7`='Para hacer una tortilla hay que romper unos huevos.' WHERE `ID`=69893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하하! 피가 줄줄 흐르네요! 아주 좋아요.', `MaleText_loc4`='啊哈哈哈！太厉害了！很好。', `MaleText_loc5`='啊哈哈哈哈!血真多啊!好耶!', `MaleText_loc7`='¡Ja, ja, ja! ¡Cuánta sangre! Me encanta.', `FemaleText_loc1`='아하하하! 피가 줄줄 흐르네요! 아주 좋아요.', `FemaleText_loc4`='啊哈哈哈！太厉害了！很好。', `FemaleText_loc5`='啊哈哈哈哈!血真多啊!好耶!', `FemaleText_loc7`='¡Ja, ja, ja! ¡Cuánta sangre! Me encanta.' WHERE `ID`=69894;
