UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자들을 색출하는 중이다. 마침 한 놈 더 찾았군...', `MaleText_loc4`='我们正在肃清叛徒。似乎我们又找到了一个……', `MaleText_loc5`='我們是來消滅叛徒的，但看來我們又發現了新的叛徒....', `MaleText_loc7`='Estamos identificando a los traidores. Parece que hemos encontrado a otro...', `FemaleText_loc1`='배신자들을 색출하는 중이다. 마침 한 놈 더 찾았군...', `FemaleText_loc4`='我们正在肃清叛徒。似乎我们又找到了一个……', `FemaleText_loc5`='我們是來消滅叛徒的，但看來我們又發現了新的叛徒....', `FemaleText_loc7`='Estamos identificando a los traidores. Parece que hemos encontrado a otro...' WHERE `ID`=69899;
