UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트롤들은 자신의 처지를 제대로 알아야 할 것이다.', `MaleText_loc4`='这些巨魔必须知道自己的地位。', `MaleText_loc5`='這些食人妖必須知道自己扮演的角色。', `MaleText_loc7`='Los trols tienen que aprender cuál es su sitio.', `FemaleText_loc1`='이 트롤들은 자신의 처지를 제대로 알아야 할 것이다.', `FemaleText_loc4`='这些巨魔必须知道自己的地位。', `FemaleText_loc5`='這些食人妖必須知道自己扮演的角色。', `FemaleText_loc7`='Los trols tienen que aprender cuál es su sitio.' WHERE `ID`=69901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드에 나약한 놈들 따위는 필요없다.', `MaleText_loc4`='部落没有弱者的空间。', `MaleText_loc5`='部落容不下這種軟弱的廢物。', `MaleText_loc7`='No hay lugar para la debilidad en la Horda.' WHERE `ID`=69902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 막지는 못한다!', `MaleText_loc4`='你休想阻挡我们！', `MaleText_loc5`='不准你妨礙我們!', `MaleText_loc7`='¡No te interpondrás en nuestro camino!' WHERE `ID`=69903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 더 이상 ''너의'' 호드가 아니다!', `MaleText_loc4`='这是“我们”的部落！', `MaleText_loc5`='這是「我們」的部落!', `MaleText_loc7`='¡Esta es NUESTRA Horda!' WHERE `ID`=69904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원한 것은 없습니다, $p.', `FemaleText_loc4`='没有什么是永恒的，$p。', `FemaleText_loc5`='萬物終歸一死，$p。', `FemaleText_loc7`='Nada dura eternamente, $p.' WHERE `ID`=69905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 공격하고 있습니다, 노브!', `MaleText_loc4`='部落进攻了，诺弗！', `MaleText_loc5`='部落發動攻擊了，諾芙!', `MaleText_loc7`='¡La Horda está atacando, Nove!', `FemaleText_loc1`='호드가 공격하고 있어요, 노브!', `FemaleText_loc4`='部落进攻了，诺弗！', `FemaleText_loc5`='部落發動攻擊了，諾芙!', `FemaleText_loc7`='¡La Horda está atacando, Nove!' WHERE `ID`=69906;
