UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와주셔야 합니다, 노브!', `MaleText_loc4`='你必须帮助我们，诺弗！', `MaleText_loc5`='諾芙!你一定要幫幫我們!', `MaleText_loc7`='¡Tienes que ayudarnos, Nove!', `FemaleText_loc1`='도와주셔야 해요, 노브!', `FemaleText_loc4`='你必须帮助我们，诺弗！', `FemaleText_loc5`='諾芙!你一定要幫幫我們!', `FemaleText_loc7`='¡Tienes que ayudarnos, Nove!' WHERE `ID`=69908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋습니다, $p. 먼저 당신의 힘을 증명하시면 저도 당신을 돕겠습니다.', `FemaleText_loc4`='很好，$p。向我证明你自己，然后我才会帮你作战。', `FemaleText_loc5`='好吧，$p。向我證明你的價值，我就會協助你們作戰。', `FemaleText_loc7`='Muy bien, $p. Demuéstrame tu valor y te ayudaré en tu lucha.' WHERE `ID`=69909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금은 이럴 때가 아닙니다, $p. 절 내버려 두십시오.', `FemaleText_loc4`='我现在没空管这些，$p。别来打扰我。', `FemaleText_loc5`='時候未到，$p。請別來吵我。', `FemaleText_loc7`='No es el momento, $p. Déjame en paz.' WHERE `ID`=69911;
