UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐? 어? 아, 그래. 방어선이라고...', `MaleText_loc4`='啥？哈？哦，对，防御工事……', `MaleText_loc5`='啥?呃?哦，對，防禦工事...', `MaleText_loc7`='¿Qué? ¿Eh? Ah, sí, las defensas...' WHERE `ID`=69913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 정말 고맙네, 친구. 그게 필요했어...', `MaleText_loc4`='啊，非常感谢你，朋友。我正需要那个。', `MaleText_loc5`='啊，謝啦，朋友。我非常需要。', `MaleText_loc7`='Ah, muchas gracias. Lo necesitaba.' WHERE `ID`=69914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이쿠, 나는... 땅에 귀를 대고 소리를 듣고 있었네. 왜 그 있잖나, 적이 다가오는 소리라든가... 일단... 우리는 안전한 것 같네.', `MaleText_loc4`='噢，我只是……躺在地上……探听远方敌人的动向。嗯……我们暂时还是安全的。', `MaleText_loc5`='嗯，啊，我只是... 趴在地上聽聲音... 你知道的，聽聽看有沒有敵人接近的腳步聲。目前看起來，呃，聽起來，我們還挺安全的。', `MaleText_loc7`='Ay, solo estaba... escuchando el suelo, ya sabes, para oír el avance del enemigo. Parece que estamos a salvo... por ahora.' WHERE `ID`=69915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 야크는 숫놈입니다! 성난 야크가 당신을 공격합니다!', `MaleText_loc4`='这头牦牛是公的！愤怒的公牛朝你冲过来了！', `MaleText_loc5`='這頭犛牛是公的!生氣的犛牛攻擊你了!', `MaleText_loc7`='¡Este yak era macho! ¡El yak furioso se vuelve contra ti!', `FemaleText_loc1`='이 야크는 숫놈입니다! 성난 야크가 당신을 공격합니다!', `FemaleText_loc4`='这头牦牛是公的！愤怒的公牛朝你冲过来了！', `FemaleText_loc5`='這頭犛牛是公的!生氣的犛牛攻擊你了!', `FemaleText_loc7`='¡Este yak era macho! ¡El yak furioso se vuelve contra ti!' WHERE `ID`=69916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 잠깐 쉰 거네. 이제 일할 준비가 다 됐어!', `MaleText_loc4`='哦，我只是打了个小盹，养精蓄锐。现在，整装待发！', `MaleText_loc5`='哦，只是打個盹而已。我現在精神好多了!', `MaleText_loc7`='Ah, solo era una siesta. ¡Ya estoy listo!' WHERE `ID`=69917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으악! 내 털에 무슨 짓을 한 건가!', `MaleText_loc4`='嗷！看看你都对我的毛做了什么！', `MaleText_loc5`='呃啊!看看你把我的毛皮弄成什麼樣子!', `MaleText_loc7`='¡Ay! ¡Mira lo que has hecho con mi pelaje!' WHERE `ID`=69918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 대체 왜?! 정말 좋은 꿈을 꾸던 중이었는데...', `MaleText_loc4`='噢，为什么？你打扰了我的好梦……', `MaleText_loc5`='什麼?哦，你打斷了我剛剛的美夢...', `MaleText_loc7`='¿Por qué? ¡Has interrumpido un sueño estupendo!' WHERE `ID`=69919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성공했습니다! 암야크가 당신을 보며 한가로이 매애 웁니다.', `MaleText_loc4`='成功了！母牦牛轻轻地对你哞叫着。', `MaleText_loc5`='成功!母犛牛對著你哞哞地叫。', `MaleText_loc7`='¡Éxito! La yak muge tranquilamente.', `FemaleText_loc1`='성공했습니다! 암야크가 당신을 보며 한가로이 매애 웁니다.', `FemaleText_loc4`='成功了！母牦牛轻轻地对你哞叫着。', `FemaleText_loc5`='成功!母犛牛對著你哞哞地叫。', `FemaleText_loc7`='¡Éxito! La yak muge tranquilamente.' WHERE `ID`=69920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했네. 이제 내가 포로인 샨 키엔의 머리카락을 넣고 재료를 섞겠네.', `MaleText_loc4`='干得好。现在只需要把单简的头发加到酒剂中。', `MaleText_loc5`='太棒了。現在我只需要一根衫·基恩的頭髮，再加上其他的材料就可以製成了。', `MaleText_loc7`='Bien hecho. Ahora solo queda añadir un cabello de nuestro prisionero, Shan Kien, y combinar los ingredientes.' WHERE `ID`=69921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달인 브라운스톤과 작업자들이 잠들었습니다!', `MaleText_loc4`='褐石大师和他的小队睡着了！', `MaleText_loc5`='褐石大師和他的手下都睡著了!', `MaleText_loc7`='¡El maestro Piedra Cobriza y su equipo se han quedado dormidos!', `FemaleText_loc1`='달인 브라운스톤과 작업자들이 잠들었습니다!', `FemaleText_loc4`='褐石大师和他的小队睡着了！', `FemaleText_loc5`='褐石大師和他的手下都睡著了!', `FemaleText_loc7`='¡El maestro Piedra Cobriza y su equipo se han quedado dormidos!' WHERE `ID`=69922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 참을성이 별로 없다, 샨 키엔. 천상의 종이 어디 있는지 당장 말해!', `MaleText_loc4`='我快失去耐心了，单简。告诉我，圣钟在哪里！', `MaleText_loc5`='我要失去耐性了，衫·基恩。說!!聖鐘到底在哪裡!!', `MaleText_loc7`='Estoy perdiendo la paciencia, Shan Kien. ¡Dime dónde está la Campana divina!' WHERE `ID`=69923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽이고 싶거든 죽여라. 내겐 너희 호드를 도울 이유가 없다. 난 오로지 천둥왕에게만 복종한다.', `MaleText_loc4`='要杀就杀，我不会听命于你，或者你的部落。我只效忠雷电之王。', `MaleText_loc5`='你還是殺了我吧，我可沒效忠你或你的部落。我只服從雷王的命令。', `MaleText_loc7`='Mátame si quieres, pero no les debo lealtad ni a ti ni a tu Horda. El único maestro al que sirvo es el Rey del Trueno.' WHERE `ID`=69924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이시, 칼을 뽑아라. 손발을 좀 잃고 나면 놈도 마음이 바뀔 것이다.', `MaleText_loc4`='伊什，去拿你的剑，他会改主意的。小心点，别要了他的命。', `MaleText_loc5`='伊什，拔出你的刀來。在他最脆弱的部位來個幾刀，他就會改變主意的。', `MaleText_loc7`='Ishi, desenvaina. Unos cortes bien dados le harán cambiar de opinión.' WHERE `ID`=69925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 잠깐만. 다른 방법이 있을 것이오. 피를 흘릴 필요는 없소.', `MaleText_loc4`='加尔鲁什，请等等。也许有还有另外一个办法，无需流血的办法。', `MaleText_loc5`='慢著，卡爾洛斯。除了流血之外，一定還有別的方法。', `MaleText_loc7`='Garrosh, espera. Puede que haya otra forma, una que no requiera derramamiento de sangre.' WHERE `ID`=69926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 말해 봐라!', `MaleText_loc4`='那就快说！', `MaleText_loc5`='快說!', `MaleText_loc7`='¡Pues dila!' WHERE `ID`=69927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 샨 키엔의 과거를 들여다볼 수 있게 해주는 고대 판다렌 음료를 만드는 방법을 알아냈소. 그저 몇 가지 재료만 구하면 되오.', `MaleText_loc4`='我知道如何调制一种古代熊猫人酒剂，借助这种酒剂，我们能看到单简的过去。所以我们只需要收集调酒需要的原料。', `MaleText_loc5`='我知道怎麼釀造一種古老的熊貓人酒，能夠讓我們看到衫·基恩的過去。', `MaleText_loc7`='He aprendido a elaborar una antigua tintura pandaren que nos permitirá contemplar el pasado de Shan Kien. Solo tenemos que reunir los ingredientes.' WHERE `ID`=69928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바위심장부에서 한 발 물러난 것은 추진력을 얻기 위해서였다!', `MaleText_loc4`='巨石之核不过是个小小的挫折！', `MaleText_loc5`='石岩之心只是一時的小失敗而已!', `MaleText_loc7`='¡El Núcleo Pétreo fue un mero contratiempo!' WHERE `ID`=69929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나에 대한 소문과 농담을 모두 들었다...', `MaleText_loc4`='我听过那些谣言和笑话……', `MaleText_loc5`='我聽到了一些謠言跟笑話...', `MaleText_loc7`='He oído los rumores y los chistes...' WHERE `ID`=69930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 밀하우스 마나스톰 님을 비웃고도 살아남을 수 있는 자는 없다!', `MaleText_loc4`='没人能在背后嘲笑伟大的米尔豪斯·法力风暴之后还能活着去向他人讲述这个故事！', `MaleText_loc5`='凡是在背後偷笑米歐浩斯·曼納斯頓的人都得死!', `MaleText_loc7`='¡Nadie se ríe a espaldas del gran Molino Tormenta de maná y vive para contarlo!' WHERE `ID`=69931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 아주 좋아할 만한 걸 주지...', `MaleText_loc4`='我这里有些你会喜欢的东西……', `MaleText_loc5`='看我弄點你肯定會愛的東西...', `MaleText_loc7`='Tengo un regalito para ti que te va a encantar...' WHERE `ID`=69932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노력은 가상하구나, 솜털이 보송한 애송아.', `MaleText_loc4`='值得表扬，甜心。', `MaleText_loc5`='不錯的把戲啊。', `MaleText_loc7`='Buen intento, encanto.' WHERE `ID`=69933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음엔 운이 좋길 바라거라! 므와하하하하하!', `MaleText_loc4`='祝你下次好运！挖哈哈哈哈哈！', `MaleText_loc5`='祝你下次好運!哇哈哈哈哈哈哈!', `MaleText_loc7`='¡Que tengas más suerte la próxima vez! ¡JA, JA, JA, JA, JA!' WHERE `ID`=69934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 변호사가 네게 연락할 거다!', `MaleText_loc4`='等着收我的律师函吧！', `MaleText_loc5`='等著接我律師的存證信函吧你!', `MaleText_loc7`='¡Tendrás noticias de mi abogado!' WHERE `ID`=69935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이어서 어딘가에서 발견된 악어 브루스가 투기장에 등장합니다!', `MaleText_loc4`='同时进场的还有布鲁斯，它是我们特意找来的一条巨鳄！', `MaleText_loc5`='同時進場的是，我們不小心在路邊找到的鱷魚 - 布魯斯!!!!', `MaleText_loc7`='También entra en la arena... ¡Bruce, un crocolisco que nos encontramos!' WHERE `ID`=69936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이에 맞설 상대는... 천둥왕의 추종자, 일촉즉발의 비안입니다!', `MaleText_loc4`='我们的另一边，则是雷电之王的狂热追随者，瓦安！', `MaleText_loc5`='另一邊角落的是雷王麾下的火焰使者，『暴烈』維安!', `MaleText_loc7`='¡En la otra esquina está Vian, el flamígero seguidor del Rey del Trueno!' WHERE `ID`=69937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장에 피머리가 등장합니다! 언제 상대를 피투성이로 만들지 모르는, 저 머리를 조심하세요!', `MaleText_loc4`='另一位进入竞技场的是：血角！他会用你的鲜血染红他的角！', `MaleText_loc5`='同時進入競技場的是: 牴角!牠可會試著用頂角去牴刺你哦。', `MaleText_loc7`='También entra en la arena... ¡Cocosangre! Intentará hacerte sangrar con su coco.' WHERE `ID`=69938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 제가 애완동물이 돼서라도 섬기고 싶은... 던전 인도자 비샤스입니다!', `MaleText_loc4`='是地下城主韦沙斯！给我穿上皮衣，然后用你的鞭子狠狠抽我吧！', `MaleText_loc5`='喔，皮鞭!頸圈!繩子!歡迎刑求大師韋沙斯!', `MaleText_loc7`='¡Vaya! Envuélveme en cuero y tira de la correa: ¡es el amo del calabozo Vishas!' WHERE `ID`=69939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야! 누가 나타났는지 보세요... 브랏입니다!', `MaleText_loc4`='嘿嘿！请看我们今日为大家带来的……布拉特！', `MaleText_loc5`='嘿嘿嘿!看看今天我們為大家撈到了什麼... 吞齧怪!', `MaleText_loc7`='¡Ahí va! Mirad lo que hemos pescado para hoy... ¡Blat!' WHERE `ID`=69940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대는 놈리건 최고의 용사들입니다... 지금은 그다지 돋보이지 않지만요. 오염된 노움 5인조!', `MaleText_loc4`='另一边是诺莫瑞根的精英小队……至少他们曾经是。麻疯侏儒五重奏！', `MaleText_loc5`='接下來出場的是諾姆瑞根的精英... 顛峰等級爆表到瘋癲的... 痲瘋地精五人組!', `MaleText_loc7`='Los contrincantes son la élite de Gnomeregan... aunque han visto días mejores. ¡Es el quinteto de gnomos parias!' WHERE `ID`=69941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이어서, 배틀트론이 투기장에 나타났습니다! 이 고철 덩어리가 상대를 폭발시켜 버릴 겁니다!', `MaleText_loc4`='另一位进入竞技场的是：巴特隆！这块破铜烂铁会把你们全炸飞！', `MaleText_loc5`='同時進入競技場的是: 戰魔像!這坨廢鐵已經等不及要把你炸到天外天啦!', `MaleText_loc7`='También entra en la arena... ¡el Batallatrón! ¡Ese montón de chatarra está esperando el momento de explotarte en la cara!' WHERE `ID`=69942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대편에는... 역겨운 녹색 쓰레기 고블린이 나타났습니다! 멍청하고 느려 터진 짐승을 타고 있네요. 프란과 리도입니다! 모두 야유를 보내세요!', `MaleText_loc4`='在竞技场的另一侧……一坨恶心的蠢地精骑在一头可笑的伐木畜生身上。是法兰和里东！大家一起嘘他们！', `MaleText_loc5`='另一邊的角落... 綠不隆咚的蠢蛋哥布林，騎著傻不隆咚的笨蛋坐騎... 弗蘭與瑞多!大家一起噓啊!', `MaleText_loc7`='En la otra esquina... un asqueroso bulto verde de estupidez goblin a lomos de una monstruosidad vergonzosa. ¡Son Fran y Riddoh! ¡Abucheadlos!' WHERE `ID`=69943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회만 생기면 언제든 여러분의 눈을 공격할... 디피입니다!', `MaleText_loc4`='别让他逮到机会，他会啄你的眼睛！帝皮出场！', `MaleText_loc5`='一個不小心就會啄瞎你眼睛的呆呆!', `MaleText_loc7`='Te sacará los ojos a la primera de cambio. ¡Es Chapuzón!' WHERE `ID`=69944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은바위 산의 음침한 어둠으로부터 나타난... 화염의 대가 사노리악입니다!', `MaleText_loc4`='来自黑石山深处的火焰大师，萨诺里亚克！', `MaleText_loc5`='來自黑石山深處的火焰大師，薩諾里亞克!', `MaleText_loc7`='Desde lo más profundo de la Montaña Roca Negra... ¡Sanoriak, maestro de la llama!' WHERE `ID`=69945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실리더스에서 빙빙 돌며 방황하고 있던 녀석을 이번에 발견했습니다. 보아하니 누군가에게 공격을 받아 죽을 뻔한 모양이네요. 익스를 소개합니다!', `MaleText_loc4`='我们在希利苏斯发现了他。他身受重创已经命悬一线。他就是伊克西！', `MaleText_loc5`='我們在希利蘇斯看到這傢伙繞圈圈爬來爬去，而且好像已經被人給宰掉了。歡迎伊克斯!', `MaleText_loc7`='A este lo encontramos vagando en círculos por Silithus. Se ve como de que alguien lo haya matado ya. ¡Es Ixx!' WHERE `ID`=69946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='투기장에 파괴광이 등장했습니다... 깜짝 손님도 함께요!', `MaleText_loc4`='另一位进入竞技场的是：位元毁灭者……和他的特别惊喜！', `MaleText_loc5`='同時進入競技場的是... 壞滅位元! ... 以及他的特殊驚喜!', `MaleText_loc7`='También entra en la arena... ¡Destructobyte y su sorpresa especial!' WHERE `ID`=69947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 상대는... 항상 화를 내고, 항상 무시무시하지만, 또 어딘가 사랑스러운 구석이 있는... 네베레스트 출신 쾅쾅이입니다!', `MaleText_loc4`='再看这边！他怒气冲冲。他所向披靡。他还有点小可爱。他就是来自不息山的压路者！', `MaleText_loc5`='另外這邊的角落!是憤怒的、致命的、又有點可愛的、來自奈佛勒斯的 - 碾大力!', `MaleText_loc7`='Y en esta esquina... Está enfadado, es mortal, es un poco adorable... Recién salido del Nieverest, ¡es Amasijo!' WHERE `ID`=69948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대는... 바람을 휘두르는 테로카르 숲의 아라코아, 키로크입니다!', `MaleText_loc4`='同时进场的还有来自泰罗卡森林的驭风鸦人，奇拉瓦克！', `MaleText_loc5`='另外進入競技場的是:科羅克，泰洛卡森林的舞風阿拉卡!', `MaleText_loc7`='También entra en la arena... ¡Kirrawk, arakkoa maestro del viento del Bosque de Terokkar!' WHERE `ID`=69949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀가 웃는 모습은 저도 웃게 합니다. 그녀가 주문을 시전하는 모습은 저를 마법에 걸리게 합니다. 그녀의 뿔은 저를... 묘한 기분에 사로잡히게 합니다. 도미니카입니다!', `MaleText_loc4`='她的微笑令我神往，她的法术令我倾心，她的角……令我醉心。她就是多米尼卡！', `MaleText_loc5`='看她美麗的嘴角一笑、我就跟著笑了。看她魅惑的法術一放，我就被迷倒了。看她頭上的角兒一晃，我就被觸動了... 歡迎多明妮卡!', `MaleText_loc7`='Cuando ella sonríe, yo sonrío. Cuando ella lanza un hechizo, yo me quedo hechizado. Cuando veo sus cuernos, yo me siento... intrigado. ¡Es Dominika!' WHERE `ID`=69950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음 상대는 밀리 와트입니다! 기계공학부에 다니던 시절에 제가 잠깐 사귀었던 아가씨죠!', `MaleText_loc4`='哦，下一位选手是米莉·沃特！上工程学院的时候我和她约过会！', `MaleText_loc5`='下一個，米莉耶·瓦特!我以前在工程學校常跟她出去約會!', `MaleText_loc7`='¡Ahora viene Millie Vatio! ¡Salí con ella en la escuela de ingeniería!' WHERE `ID`=69951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숄라자르 분지에서 저 친구를 찾느라고 며칠이 걸렸습니다. 밀림에 오신 것을 환영합니다! 마즈하린!', `MaleText_loc4`='我们在索拉查盆地花了数天功夫才找到这家伙。欢迎来到丛林！他就是，玛扎伦！', `MaleText_loc5`='我們花了好幾天的時間才在休拉薩盆地找到這傢伙。歡迎來到叢林!歡迎梅颯靈!', `MaleText_loc7`='Nos pasamos días buscando a esta en la Cuenca de Sholazar. ¡Bienvenidos a la selva! ¡Es Mazhareen!' WHERE `ID`=69952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노장 분들은 이 친구를 기억하실지도 모르겠네요. 뒤틀린 친구이긴 하지만, 오늘만은 상대를 뒤틀어 버릴 겁니다! 아카마를 소개합니다!', `MaleText_loc4`='也许有些老兵还记得这个人。他是个破碎者，但今天他会打碎你的骨头！是阿卡玛！', `MaleText_loc5`='資深人士應該還記得這傢伙。是啊是啊，他是個破碎者，但是他今天就是要來把你弄破!!!把你弄碎!!!把你徹底破碎!!!歡迎阿卡瑪!!!!', `MaleText_loc7`='Es posible que algunos de los veteranos se acuerden de este tipo. Sí, es un tábido, ¡pero al final del combate también lo serás tú! ¡Es Akama!' WHERE `ID`=69953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 상대는... 모두의 사랑을 한몸에 받는... 키가 3.5미터에 이르는 마법 시체! 피올입니다! 음... 발음이 이게 맞나요?', `MaleText_loc4`='同时进场的还有——大家最喜爱的、12英尺高的神奇僵尸，弗琼！我没读错吧？', `MaleText_loc5`='此外進場的是，大家最愛的12呎高魔法屍體，菲歐!!!! ...我有沒有念錯名字?', `MaleText_loc7`='También entra en la arena... ¡su cadáver de cuatro metros mágico favorito, Fjoll! ¿Lo he pronunciado bien?' WHERE `ID`=69954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 특별 손님을 모셨습니다. 애교 만점에 아무리 쓰러져도 다시 일어나는 오뚝이, 밀하우스 마나스톰입니다! 행운을 빌어요, 밀 친구!', `MaleText_loc4`='今天我们将迎来一位特别的客人：最迷人，最坚强的侏儒：米尔豪斯·法力风暴！祝你好运，米尔豪猛男！', `MaleText_loc5`='今天有位特別來賓: 最貼心的、最耐打的，米歐浩斯·曼納斯頓!!祝好運啊，小米米!', `MaleText_loc7`='Hoy tenemos un invitado especial: el adorable, el resistente... ¡Molino Tormenta de Maná! ¡Buena suerte!' WHERE `ID`=69955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아킨둔에서 이 친구가 까악까악 울면서 폭풍을 일으키는 걸 발견했습니다. 이칸 이주에게 박수를 보내주세요!', `MaleText_loc4`='我们在奥金顿找到了这位在风暴中嚎叫的家伙。大家鼓掌欢迎——伊坎·伊祖！', `MaleText_loc5`='我們看到這傢伙在奧齊頓嘎嘎叫個不停。向伊坎·易祖臣服吧!', `MaleText_loc7`='A este nos lo encontramos venga a graznar en Auchindoun. ¡Aplaudan a Yikkan Izu!' WHERE `ID`=69956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들 춤 출 준비를 하세요! 디켄이 나타났습니다!', `MaleText_loc4`='大家一起来跳舞吧！迪肯来啦！', `MaleText_loc5`='準備跳舞!歡迎迪肯出場!', `MaleText_loc7`='¡Prepárense para bailar! ¡Aquí está Deeken!' WHERE `ID`=69957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='썬더 블러프에서 온 끔찍한 타우렌도 환영해 주세요! 스매시 후프스톰프입니다! 저 커다란 어깨보호구 좀 보세요!', `MaleText_loc4`='我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！看看他那华丽到掉渣的肩铠！', `MaleText_loc5`='我們也歡迎潰擊·蹄踏，來自雷霆崖的恐怖牛頭人!', `MaleText_loc7`='También damos la bienvenida a Machaque Hollapezuña, ¡el tauren más terrible de Cima del Trueno! ¡Mirad qué hombreras!' WHERE `ID`=69958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대는... 어... 하늘을 나는 커다란 눈동자네요? 아, 이거 느낌이 좋지 않습니다.', `MaleText_loc4`='在竞技场的另一侧……什么？一只漂浮的巨眼？这可不妙。', `MaleText_loc5`='另外一邊的角落是... 一大團飄在半空中的眼珠子?!看起來真不妙啊～～', `MaleText_loc7`='Y en la otra esquina tenemos... ¿una gran nube de ojos flotantes terroríficos? No pinta bien.' WHERE `ID`=69959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참 잘 어울리지 않는 한 쌍입니다. 구역질이 나려고 하네요. GG 기계공학단이 나타났습니다!', `MaleText_loc4`='他们的搭档完全是一个意外。事实上我对此颇为厌恶。他们就是，GG工程公司组合！', `MaleText_loc5`='他們實在不該合夥的。事實上，還害我覺得有點噁心呢。接著入場的就是GG工程公司!', `MaleText_loc7`='Su colaboración es antinatural. De hecho, me pone enfermo. ¡Aquí viene Ingeniería GG!' WHERE `ID`=69960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상대는... 암흑소환사입니다. 우와, 진짜 이름도 따로 없군요. 으스스합니다!', `MaleText_loc4`='另一位进入竞技场的是：黑暗召唤师。喔，他甚至没有真正的名字。好可怕！', `MaleText_loc5`='另外進場的是: 黑暗召喚師!! 哇，他連名字都沒有，好可怕呦～～～～', `MaleText_loc7`='También entra en la arena... el invocador oscuro. Guau, ni siquiera tiene nombre. ¡Qué miedo!' WHERE `ID`=69961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 바로 제가 원하는 겁니다! 공룡이 더 필요해요! 공룡왕 쿨라카!', `MaleText_loc4`='接下来，正是我们最喜闻乐见的场面！拜托，再多来几条恐龙吧！有请，库拉卡大王！', `MaleText_loc5`='對嘛，這才像樣!!拜託請給我們多來幾隻恐龍!!庫拉卡王!!', `MaleText_loc7`='¡Ahora sí que sí! ¡Más dinosaurios, por favor! ¡Es el rey Kulaka!' WHERE `ID`=69962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음... 기계공학 측면에서도 꽤 멋진 전투가 벌어지겠네요. 분열로봇이 나타났습니다!', `MaleText_loc4`='嗯。接下来这位是名符其实的工程学杰作。下面是，干涉者时间！', `MaleText_loc5`='嗯，這回的工程水準看起來相當高啊。歡迎裂衝登場!', `MaleText_loc7`='Mmm. La verdad es que esa es ingeniería de la buena. ¡Es la hora del Disruptrón!' WHERE `ID`=69963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 이런... 미안합니다. 상대가 프로보스쿠스네요!', `MaleText_loc4`='哦，天哪……对不起，你的对手好像是普罗波库斯。', `MaleText_loc5`='嗚，真不妙... 抱歉啦，看來要跟你打的就是普羅伯斯庫!', `MaleText_loc7`='Oh, no... Lo siento, pero parece que te va a tocar luchar contra Proboskus.' WHERE `ID`=69964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 조용히 하세요... 저 친구를 화나게 하면 안 됩니다. 조용히 감상하십시오. 살인기린 운구록스입니다!', `MaleText_loc4`='各位，请安静……我们可不想激怒它。请屏息静气地欢迎我们的杀人鹿，乌古洛克斯！', `MaleText_loc5`='大家安靜... 千萬別惹牠生氣。只要默默的、敬畏地看著昂格洛斯...殺人長頸鹿!!!', `MaleText_loc7`='Que todo el mundo guarde silencio... No queremos que se enfade. Limítense a observar a Unguloxx, ¡la Asesinarafa!' WHERE `ID`=69965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이번 시합의 승자가 누구일지 내기를 걸어도 좋습니다.', `MaleText_loc4`='我现在接受你对本场比赛胜负的预测。', `MaleText_loc5`='現在開放對你預測的獲勝者下注。', `MaleText_loc7`='Ahora aceptaré sus apuestas respecto al ganador del combate.' WHERE `ID`=69966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 내기 접수를 마감합니다! 이제 결과를 지켜봅시다!', `MaleText_loc4`='好了！停止竞猜！我们看比赛吧！', `MaleText_loc5`='好啦!買定離手!到底誰會獲勝呢!', `MaleText_loc7`='¡Ya está! ¡No más apuestas! ¡A ver qué pasa!' WHERE `ID`=69967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 싸움에서는 누가 이길 것 같습니까, $c님?', `MaleText_loc4`='$c，你觉得这一场比试谁会赢？', `MaleText_loc5`='你覺得誰會贏得這場比賽呢，$c?', `MaleText_loc7`='¿Quién crees que va a ganar este combate, $c?' WHERE `ID`=69968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅입니다.', `MaleText_loc4`='英雄。', `MaleText_loc5`='英雄。', `MaleText_loc7`='El héroe.', `FemaleText_loc1`='영웅이요.', `FemaleText_loc4`='英雄。', `FemaleText_loc5`='英雄。', `FemaleText_loc7`='El héroe.' WHERE `ID`=69969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물입니다.', `MaleText_loc4`='怪物。', `MaleText_loc5`='怪物。', `MaleText_loc7`='El monstruo.', `FemaleText_loc1`='괴물이요.', `FemaleText_loc4`='怪物。', `FemaleText_loc5`='怪物。', `FemaleText_loc7`='El monstruo.' WHERE `ID`=69970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신도 직접 싸움에 참여하지 않으면, 당신의 내기를 받지 않겠습니다. 당신도 뭔가 거는 게 있어야지요.

가서 경비원에게 말을 걸고 싸움 대기열에 등록하십시오. 그 후에 내기를 합시다.', `MaleText_loc4`='除非你亲自参加过搏击竞技，否则我不会接受你的竞猜。想参加竞猜，你需要“入股经营”才行。

去和那些守卫谈谈并且排队参加搏击，然后我们再来玩竞猜。', `MaleText_loc5`='如果你不親自下場比賽的話，我不會接受你的賭注。想加入的話，你就必須跟大家一起「鬥陣」才行。

去跟守衛報名參賽，接著好戲就可以上場了。', `MaleText_loc7`='Me niego a aceptar tus apuestas si no vas a participar en un combate. Tienes que tener "carne en el asador", por así decir.

Ve a hablar con uno de los guardias y únete a la cola para combatir. Entonces podrás jugar.' WHERE `ID`=69971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 게임을 하고 싶다고 하셨습니까?

싸움판에 뛰어들어 자신의 솜씨를 보여주십시오. 3계급 싸움꾼이 되거든 제게 다시 말을 거십시오.', `MaleText_loc4`='你想要玩我的竞猜游戏？

那就去竞技场去证明你的实力吧。当你达到等级3之后再回来和我谈谈。', `MaleText_loc5`='你想加入我的俱樂部嗎?

到競技場裡證明你的實力。等你達到第3階的時候再來找我。', `MaleText_loc7`='¿Quieres jugar?

Ve a la arena y prueba tu valía. Llega al rango 3 y luego ven a hablar conmigo.' WHERE `ID`=69972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 오만하고, 거만하고, 강력하오... 모두 가로쉬의 화를 돋울 특징들이지. 그는 여기 도착하자마자 분노에 눈이 멀 거요.

그러니 반드시 가로쉬가 도착하기 전에 모구 지도자를 생포해서 심문해야 하오.', `MaleText_loc4`='魔古族既傲慢专横又力量强大——加尔鲁什见了他们肯定会头脑发热怒不可遏。

所以我们要赶在这种事情发生之前抓住魔古族的首领，并且从他的嘴里挖出我们需要的情报。', `MaleText_loc5`='魔古是專制、狂傲，強大的種族 - 通通都是會惹卡爾洛斯火冒三丈的特性。

這就是為什麼，我們一定要在情勢失控前逮捕並且好好拷問些魔古的首領。', `MaleText_loc7`='Los mogu son imperiosos, arrogantes y poderosos, características todas que enfurecerán a Garrosh en cuanto llegue.

Por eso es vital que capturemos e interroguemos a su líder antes de que eso pase.' WHERE `ID`=69973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 여기서 내보내줘!', `MaleText_loc4`='快放我们出来！', `MaleText_loc5`='立刻放開我們!', `MaleText_loc7`='¡Déjanos salir ahora mih''mo!', `FemaleText_loc1`='우리를 여기서 내보내줘!', `FemaleText_loc4`='快放我们出来！', `FemaleText_loc5`='立刻放開我們!', `FemaleText_loc7`='¡Déjanos salir ahora mih''mo!' WHERE `ID`=69974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 우리 고향이다. 우리가 고분고분 따를 거라 생각하면 큰 오산이야.', `MaleText_loc4`='这里是我们的家园。如果你认为我们会默默忍受，你就大错特错了。', `MaleText_loc5`='這裡是我們的家。要是你以為我們會乖乖離開，你就錯了。', `MaleText_loc7`='Eh''te es nueh''tro hogar, colega. Si crees que nos iremos sin rechih''tar, te equivocas.', `FemaleText_loc1`='여긴 우리 고향이다. 우리가 고분고분 따를 거라 생각하면 큰 오산이야.', `FemaleText_loc4`='这里是我们的家园。如果你认为我们会默默忍受，你就大错特错了。', `FemaleText_loc5`='這裡是我們的家。要是你以為我們會乖乖離開，你就錯了。', `FemaleText_loc7`='Eh''te es nueh''tro hogar, colega. Si crees que nos iremos sin rechih''tar, te equivocas.' WHERE `ID`=69975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리에게 이런 짓을 하지? 우리는 호드에 충성을 다했다!', `MaleText_loc4`='你为什么要做这种事情？我们忠诚于部落！', `MaleText_loc5`='為什麼要這樣?我們對部落是忠心的!', `MaleText_loc7`='¿Por qué hacéis eh''to? ¡Somos leales a la Horda!', `FemaleText_loc1`='왜 우리에게 이런 짓을 하지? 우리는 호드에 충성을 다했다!', `FemaleText_loc4`='你为什么要做这种事情？我们忠诚于部落！', `FemaleText_loc5`='為什麼要這樣?我們對部落是忠心的!', `FemaleText_loc7`='¿Por qué hacéis eh''to? ¡Somos leales a la Horda!' WHERE `ID`=69976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 승자를 맞추고 싶어?$b$b빨리빨리! 이번에는 누가 이길 것 같아, 친구?', `MaleText_loc4`='好吧，你也想参加？$b$b快点，快点，你觉得谁会赢，菜鸟？', `MaleText_loc5`='你想試試手氣嗎?$b$b快快快，你覺得誰會贏呢，老闆?', `MaleText_loc7`='Venga, ¿te apuntas?$b$bRápido, rápido, ¿quién crees que va a ganar esta ronda?' WHERE `ID`=69977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 뭐야? 너도 참가하고 싶다고?

가서 싸움판에서 네 실력을 증명해 봐. 3계급 싸움꾼이 되거든 다시 얘기해 보자고.', `MaleText_loc4`='你是谁？你想参加竞猜？

那就去竞技场去证明你的实力吧。当你达到等级3之后再回来和我谈谈。', `MaleText_loc5`='你是誰?你想加入嗎?

到競技場證明你的實力。等你到了第3階再來找我吧。', `MaleText_loc7`='¿Y tú quién eres? ¿Quieres sacar tajada?

Entra en la arena y prueba tu valía. Alcanza el rango 3 y ya hablaremos.' WHERE `ID`=69978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 직접 싸움판에 뛰어들기 전까지는 나도 널 도울 수 없다고. 너도 이 판에 한 발 정도는 담가야지. 안 그래?

가서 경비병들에게 너도 싸우고 싶다고 얘기해 봐. 그 다음에 우리 볼 일을 보자고.', `MaleText_loc4`='除非你亲自参加过搏击竞技，否则我不会让你参加竞猜。你得“亲自参股”，老大。

去和那些守卫谈谈并且排队参加搏击，然后我们再来玩竞猜。', `MaleText_loc5`='如果你不親自下場比賽的話，我可不會接受你的賭注。你得先跟大家一塊「鬥陣」才行，老闆。

去跟守衛報名參賽，不然你就沒得玩囉。', `MaleText_loc7`='No te voy a apoyar si no vas a participar en un combate. Tienes que tener "carne en el asador", por así decir.

Ve a hablar con uno de los guardias y únete a la cola para combatir. Entonces podrás jugar.' WHERE `ID`=69979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 돈 걸 사람?', `MaleText_loc4`='好，还有谁参加？', `MaleText_loc5`='好啦，誰想下注?', `MaleText_loc7`='¡Venga! ¿Quién se apunta?' WHERE `ID`=69980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 끝! 싸움이 시작됐으니, 이제 접수도 끝이라고!', `MaleText_loc4`='好了！搏击开始，停止竞猜！', `MaleText_loc5`='好啦!比賽已經開始，停止下注!', `MaleText_loc7`='¡Ya está! El combate está en marcha, ¡no se aceptan apuestas!' WHERE `ID`=69981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 명을 받들어 이 "도시"에는 계엄령이 선포되었다. 그분의 뜻을 거스르는 자는 배신자로 간주하겠다!', `MaleText_loc4`='根据酋长的命令，这座“城市”现在受军队管辖。违背酋长意志者将被当作叛徒处置！', `MaleText_loc5`='奉大酋長之命，這座「城市」已經戒嚴。凡是違抗大酋長命令者都將視為叛徒!', `MaleText_loc7`='Por orden del Jefe de Guerra, esta "ciudad" se encuentra bajo la ley marcial. ¡Todos los que desafíen la voluntad del Jefe de Guerra serán declarados traidores!' WHERE `ID`=69982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 무슨 권리로 우리를 가두는거냐!', `MaleText_loc4`='你无权关押我们！', `MaleText_loc5`='你沒有權力把我們當俘虜!', `MaleText_loc7`='¡No tienes derecho a encerrah''nos!', `FemaleText_loc1`='너희가 무슨 권리로 우리를 가두는거냐!', `FemaleText_loc4`='你无权关押我们！', `FemaleText_loc5`='你沒有權力把我們當俘虜!', `FemaleText_loc7`='¡No tienes derecho a encerrah''nos!' WHERE `ID`=69983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여긴 우리 땅이다! 너희 코르크론은 여기에서 환영받지 못해.', `MaleText_loc4`='这是我们的家园！库卡隆，你们在这里不受欢迎！', `MaleText_loc5`='這裡是我們家!柯爾克隆，這裡不歡迎你們。', `MaleText_loc7`='¡Eh''te es nueh''tro hogar! No son bienvenidos, Kor''kron.', `FemaleText_loc1`='여긴 우리 땅이다! 너희 코르크론은 여기에서 환영받지 못해.', `FemaleText_loc4`='这是我们的家园！库卡隆，你们在这里不受欢迎！', `FemaleText_loc5`='這裡是我們家!柯爾克隆，這裡不歡迎你們。', `FemaleText_loc7`='¡Eh''te es nueh''tro hogar! No son bienvenidos, Kor''kron.' WHERE `ID`=69984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 우리에게 이런 짓을 하지? 우리도 호드의 일부이다.', `MaleText_loc4`='你为什么要做这种事情？我们都是部落成员！', `MaleText_loc5`='為什麼這樣做?我們都是部落的人。', `MaleText_loc7`='¿Por qué hacéis eh''to? Todos foh''mamos pah''te de la Horda.', `FemaleText_loc1`='왜 우리에게 이런 짓을 하지? 우리도 호드의 일부이다.', `FemaleText_loc4`='你为什么要做这种事情？我们都是部落成员！', `FemaleText_loc5`='為什麼這樣做?我們都是部落的人。', `FemaleText_loc7`='¿Por qué hacéis eh''to? Todos foh''mamos pah''te de la Horda.' WHERE `ID`=69985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님은 어디 계신 거지?', `MaleText_loc4`='沃金在哪里？', `MaleText_loc5`='沃金在哪裡?', `MaleText_loc7`='¿Dónde eh''tá Vol''jin?', `FemaleText_loc1`='볼진 님은 어디 계신 거죠?', `FemaleText_loc4`='沃金在哪里？', `FemaleText_loc5`='沃金在哪裡?', `FemaleText_loc7`='¿Dónde eh''tá Vol''jin?' WHERE `ID`=69986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은 여기서 환영받지 못해!', `MaleText_loc4`='这里不欢迎你们！', `MaleText_loc5`='這裡不歡迎你們!', `MaleText_loc7`='¡No sois bienvenidos!', `FemaleText_loc1`='네놈들은 여기서 환영받지 못해!', `FemaleText_loc4`='这里不欢迎你们！', `FemaleText_loc5`='這裡不歡迎你們!', `FemaleText_loc7`='¡No sois bienvenidos!' WHERE `ID`=69987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이 정신이 나간 게 분명해.', `MaleText_loc4`='酋长肯定是疯了。', `MaleText_loc5`='大酋長腦袋不正常了。', `MaleText_loc7`='El Jefe de Guerra ha peh''dido el juicio.', `FemaleText_loc1`='대족장이 정신이 나간 게 분명하군요.', `FemaleText_loc4`='酋长肯定是疯了。', `FemaleText_loc5`='大酋長腦袋不正常了。', `FemaleText_loc7`='El Jefe de Guerra ha peh''dido el juicio.' WHERE `ID`=69988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 충성심을 시험하려 드는 건가?', `MaleText_loc4`='你是谁？凭什么质疑我们的忠诚？', `MaleText_loc5`='你有什麼資格懷疑我們的忠心?', `MaleText_loc7`='¿Quiénes sois para dudar de nueh''tra lealtad?', `FemaleText_loc1`='우리 충성심을 시험하려 드는 건가요?', `FemaleText_loc4`='你是谁？凭什么质疑我们的忠诚？', `FemaleText_loc5`='你有什麼資格懷疑我們的忠心?', `FemaleText_loc7`='¿Quiénes sois para dudar de nueh''tra lealtad?' WHERE `ID`=69989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 오크처럼 우리도 호드를 위해 피를 흘렸다!', `MaleText_loc4`='为部落流血的可不只是你们这些兽人！', `MaleText_loc5`='為部落流血賣命的可不只有獸人啊!', `MaleText_loc7`='¡Los oh''cos no sois los únicos que sangráis por la Horda!', `FemaleText_loc1`='너희 오크처럼 우리도 호드를 위해 피를 흘렸다!', `FemaleText_loc4`='为部落流血的可不只是你们这些兽人！', `FemaleText_loc5`='為部落流血賣命的可不只有獸人啊!', `FemaleText_loc7`='¡Los oh''cos no sois los únicos que sangráis por la Horda!' WHERE `ID`=69990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무력을 쓸 게 아니라 설득을 하면 좋겠소. 여기 판다렌의 기억주가 한 통 있소. 이걸 사용하면 우리가 샨 키엔의 과거를 볼 수 있을 것이오.', `MaleText_loc4`='不必使用武力，让我们说服他。我这里有一桶熊猫人溯源酒。酒的力量可以让我们看到单简的过去。', `MaleText_loc5`='讓我們用說服的方式，而非武力。我這有一壺熊貓人的回憶之酒。它能讓我們看到衫·基恩的過去。', `MaleText_loc7`='Utilicemos la persuasión, no la fuerza. Tengo un barril de vino evocador pandaren. Nos permitirá contemplar el pasado de Shan Kien.' WHERE `ID`=69991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마나... 더... 네 형제를 죽여야... "너의" 호드를 되찾을 수 있다고 생각하나?', `MaleText_loc4`='你到底……要杀多少自己人……才能夺回“你的”部落。', `MaleText_loc5`='為了...「你的」部落...你到底要殺害多少自己的同胞...?', `MaleText_loc7`='¿A cuántos... miembros de tu propia gente... debes matar... para recuperar "tu" Horda?' WHERE `ID`=69994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 변하고 있다! 볼진은 이를 받아들이지 않았고 트롤들은 나태해졌지.', `MaleText_loc4`='部落正在改变！沃金不愿意与时俱进，而且他正在荼毒他的人民。', `MaleText_loc5`='部落正在蛻變!沃金拒絕改變，他是在毒害他的人民。', `MaleText_loc7`='¡La Horda está cambiando! Vol''jin se negaba a cambiar con ella, así que envenenó a su gente.' WHERE `ID`=69995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 호드의 아들딸들을 해치는걸 놔두지는 않겠다. 너희의 명분은 옳지 못하다.', `MaleText_loc4`='你再也不能荼毒部落的儿女了。你的意志已经堕落了。', `MaleText_loc5`='你再也傷害不了部落的子民了。你們已經誤入歧途。', `MaleText_loc7`='Ya no volverás a dañar a ningún hijo o hija de la Horda. Tu propósito está corrupto.' WHERE `ID`=69997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 얼라이언스를 위해서 어떤 일까지 하는지...', `MaleText_loc4`='我是为了联盟才做的……', `MaleText_loc5`='我為了聯盟所做的一切...', `MaleText_loc7`='Las cosas que hago por la Alianza...' WHERE `ID`=70001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 전투석을 거래하고 싶습니까?', `MaleText_loc4`='你有兴趣交易宠物战斗石吗？', `MaleText_loc5`='有興趣做點寵物戰鬥石的交易嗎?', `MaleText_loc7`='¿Te interesa intercambiar piedras de duelo de mascotas?', `FemaleText_loc1`='애완동물 전투석을 거래하고 싶으세요?', `FemaleText_loc4`='你有兴趣交易宠物战斗石吗？', `FemaleText_loc5`='有興趣做點寵物戰鬥石的交易嗎?', `FemaleText_loc7`='¿Te interesa intercambiar piedras de duelo de mascotas?' WHERE `ID`=70002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오레스테스! 에이니아! $p|1과;와; 함께 임무를 수행하라.', `MaleText_loc4`='俄瑞斯忒斯！埃涅亚！你们和$p一起去执行任务。', `MaleText_loc5`='歐瑞斯提!依妮雅!去陪$p執行這個任務。', `MaleText_loc7`='¡Orestes! ¡Aenea! Acompañen a $p en su misión.' WHERE `ID`=70003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 에이니아와 같이 하는 임무입니까? 명령이라면 할 수 없죠.', `MaleText_loc4`='又和埃涅亚一起执行任务？好吧，除非我别无选择。', `MaleText_loc5`='又要跟依妮雅一起出任務?好吧。', `MaleText_loc7`='¿Otra misión con Aenea? Si no queda más remedio...' WHERE `ID`=70004;
