UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이 무기는 필요가 없겠지. 안그래?', `MaleText_loc4`='你不再需要这把武器了，对吗？', `MaleText_loc5`='這個武器你不需要了吧?', `MaleText_loc7`='Ya no te hace falta eh''ta arma, ¿verdad?', `FemaleText_loc1`='이제 이 무기는 필요가 없겠지. 안그래?', `FemaleText_loc4`='你不再需要这把武器了，对吗？', `FemaleText_loc5`='這個武器你不需要了吧?', `FemaleText_loc7`='Ya no te hace falta eh''ta arma, ¿verdad?' WHERE `ID`=70006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기는 이렇게 쓰는거지.', `MaleText_loc4`='让我来教你该如何使用你自己的武器，兄弟。', `MaleText_loc5`='老兄，我來教你，你自己的武器要怎樣用。', `MaleText_loc7`='Te voy a enseñar a usar tu propia arma, colega.', `FemaleText_loc1`='무기는 이렇게 쓰는거지.', `FemaleText_loc4`='让我来教你该如何使用你自己的武器，兄弟。', `FemaleText_loc5`='老兄，我來教你，你自己的武器要怎樣用。', `FemaleText_loc7`='Te voy a enseñar a usar tu propia arma, colega.' WHERE `ID`=70007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어서도 한번 설쳐보시지?', `MaleText_loc4`='你死了之后就不会这么顽固了，对吧？', `MaleText_loc5`='有多厲害啊?還不是死了啊?', `MaleText_loc7`='Cuando eh''tás mueh''to ya no eres tan duro, ¿a que no?', `FemaleText_loc1`='죽어서도 한번 설쳐보시지?', `FemaleText_loc4`='你死了之后就不会这么顽固了，对吧？', `FemaleText_loc5`='有多厲害啊?還不是死了啊?', `FemaleText_loc7`='Cuando eh''tás mueh''to ya no eres tan duro, ¿a que no?' WHERE `ID`=70008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 수 있을 때 떠났어야지.', `MaleText_loc4`='你应该趁着能跑的时候赶紧跑。', `MaleText_loc5`='誰叫你可以走的時候不走。', `MaleText_loc7`='Deberías habeh''te ido cuando pudih''te.', `FemaleText_loc1`='떠날 수 있을 때 떠났어야지.', `FemaleText_loc4`='你应该趁着能跑的时候赶紧跑。', `FemaleText_loc5`='誰叫你可以走的時候不走。', `FemaleText_loc7`='Deberías habeh''te ido cuando pudih''te.' WHERE `ID`=70009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 땅을 원하나? 기꺼이 여기에 묻어주지.', `MaleText_loc4`='你想要夺走我们的土地？我们会把你埋在这里。', `MaleText_loc5`='喜歡我們這裡?喜歡我們就把你埋在這裡。', `MaleText_loc7`='¿Querías nueh''tra tierra? Ahora te enterraremos en ella.', `FemaleText_loc1`='우리 땅을 원하나? 기꺼이 여기에 묻어주지.', `FemaleText_loc4`='你想要夺走我们的土地？我们会把你埋在这里。', `FemaleText_loc5`='喜歡我們這裡?喜歡我們就把你埋在這裡。', `FemaleText_loc7`='¿Querías nueh''tra tierra? Ahora te enterraremos en ella.' WHERE `ID`=70010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것만 약속해주게, $p. 오늘 일어난 일을 가로쉬한테 말하지는 말게. 그와 직접 대면할 수도 있겠지만, 모든 오크들이 내 뜻을 따르지는 않는다는 걸 알았네. $b$b내가 그들을 바로잡기 위해 또 다른 폭군이 되어야 한다면 그게 무슨 소용이겠는가?$b$b내가 할 수 있는 것은 검은창 부족을 도와서 이곳을 방어하고 저들의 영웅들이 전쟁에 나갈 때까지 기다리는 것이네. 볼진이 돌아오면 그 후의 움직임을 계획하세.', `MaleText_loc4`='请帮我个小忙，$p，不要让加尔鲁什知道今天在这里发生的事。我不是不能直接挑战他，但我发现如今并不是所有的兽人都和我的想法一致。$b$b如果我需要成为另一个暴君才能赢得他们的忠诚，那我和加尔鲁什有什么区别？$b$b我能做的只有帮助暗矛部族防御他们的家园，直到他们的英雄归来。当沃金回来之后，我们再进行下一步计划。', `MaleText_loc5`='幫我一個忙，$p，別把今天這裡發生的事情告訴卡爾洛斯。雖然我可以親自去質疑他，但如今並非每個獸人對部落的看法都跟我一致。$b$b如果我非得變成另一個獨裁者才能獲得他們的擁護，那又有何意義呢?$b$b所以我現在能做的，就是在暗矛部族的勇士都外出作戰時，待在這裡協助捍衛他們的家園。等沃金回來之後，我們再計畫下一步的行動。', `MaleText_loc7`='Hazme un favor, $p: no le digas a Garrosh lo que ha pasado aquí hoy. Podría enfrentarme a él directamente, pero ahora entiendo que no todos los orcos comparten mi visión de la Horda.$b$b¿Quién soy yo para exigirles lealtad si para ello debo convertirme en otro dictador?$b$bLo que sí puedo hacer es ayudar a los Lanza Negra a fortificar sus hogares mientras sus héroes luchan en el extranjero. Cuando Vol''jin vuelva, planearemos nuestro siguiente movimiento.' WHERE `ID`=70011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은부화 마술사가 배를 정지장에 가뒀습니다! 마술사를 처치하여 주문을 해제하십시오.', `MaleText_loc4`='暗生巫师使船陷入了停滞！杀了它以打断法术。', `MaleText_loc5`='有個暗孵巫士施法讓船停住了!殺了它才能中斷法術!', `MaleText_loc7`='¡Un hechicero Incubasombras ha puesto el barco en Estasis! Mátalo para interrumpir el hechizo.' WHERE `ID`=70012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은부화 알 무리가 부화하기 시작합니다!', `MaleText_loc4`='附近有一组暗生之卵开始孵化了！', `MaleText_loc5`='附近有堆暗孵蛋要孵化了!', `MaleText_loc7`='¡Un grupo cercano de huevos de Incubasombras empieza a eclosionar!' WHERE `ID`=70013;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리즐에게 휴대용 화염방사기를 받았습니다! 주변의 사우록 알에 사용하십시오.', `MaleText_loc4`='格里兹尔给了你一把便携式火焰喷射器！用它来对付附近的蜥蜴卵。', `MaleText_loc5`='格里茲爾給了你一個火焰噴射器!用它來燒掉附近的蛋。', `MaleText_loc7`='¡Llorica te ha dado un lanzallamas portátil! Úsalo con los huevos de saurok cercanos.' WHERE `ID`=70014;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흔들 기구를 타려면 다크문 놀이기구 탑승권이 있어야 합니다.', `MaleText_loc4`='你需要暗月木马门票才能乘坐旋转木马。', `MaleText_loc5`='要有暗月騎乘券才能坐旋轉木馬!', `MaleText_loc7`='Te hace falta un vale de tiovivo de la Luna Negra para montar en el carrusel.', `FemaleText_loc1`='흔들 기구를 타려면 다크문 놀이기구 탑승권이 있어야 해요.', `FemaleText_loc4`='你需要暗月木马门票才能乘坐旋转木马。', `FemaleText_loc5`='要有暗月騎乘券才能坐旋轉木馬!', `FemaleText_loc7`='Te hace falta un vale de tiovivo de la Luna Negra para montar en el carrusel.' WHERE `ID`=70015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배신자. 너는 너희 종족의 수치다.', `MaleText_loc4`='叛徒。你给你的种族蒙羞了。', `MaleText_loc5`='叛徒，你是你們種族的恥辱。', `MaleText_loc7`='Traidor. Eres una vergüenza para tu raza.', `FemaleText_loc1`='배신자. 너는 너희 종족의 수치다.', `FemaleText_loc4`='叛徒。你给你的种族蒙羞了。', `FemaleText_loc5`='叛徒，你是你們種族的恥辱。', `FemaleText_loc7`='Traidor. Eres una vergüenza para tu raza.' WHERE `ID`=70016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 트롤들이 계속해서 대족장님께 반항하게 둘 수는 없다! 저들은 필히 응징해야 해.', `MaleText_loc4`='不能让那些巨魔继续忤逆酋长了！我们得收拾他们！', `MaleText_loc5`='這些食人妖不能再繼續違背大酋長了!一定要解決他們。', `MaleText_loc7`='¡Los trols no pueden seguir desafiando al Jefe de Guerra! Debemos castigarlos.', `FemaleText_loc1`='이 트롤들이 계속해서 대족장님께 반항하게 둘 수는 없다! 저들은 필히 응징해야 해.', `FemaleText_loc4`='不能让那些巨魔继续忤逆酋长了！我们得收拾他们！', `FemaleText_loc5`='這些食人妖不能再繼續違背大酋長了!一定要解決他們。', `FemaleText_loc7`='¡Los trols no pueden seguir desafiando al Jefe de Guerra! Debemos castigarlos.' WHERE `ID`=70017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크로서의 자부심조차 잃어버린 거냐?! 우리야말로 호드의 진정한 혈통이다! 이런 외딴 섬의 거지들 따위가 아니라.', `MaleText_loc4`='难道你忘了生为兽人的意义？！我们是部落之血！我们和那些岛上的乞丐是不一样的。', `MaleText_loc5`='你忘記身為獸人的意義了嗎?!我們才是部落的血脈!不是這些窮島的乞丐。', `MaleText_loc7`='¡¿Has olvidado lo que significa ser un orco?! ¡Nosotros somos la sangre de la Horda, no esos vagabundos isleños!', `FemaleText_loc1`='오크로서의 자부심조차 잃어버린 거냐?! 우리야말로 호드의 진정한 혈통이다! 이런 외딴 섬의 거지들 따위가 아니라.', `FemaleText_loc4`='难道你忘了生为兽人的意义？！我们是部落之血！我们和那些岛上的乞丐是不一样的。', `FemaleText_loc5`='你忘記身為獸人的意義了嗎?!我們才是部落的血脈!不是這些窮島的乞丐。', `FemaleText_loc7`='¡¿Has olvidado lo que significa ser un orco?! ¡Nosotros somos la sangre de la Horda, no esos vagabundos isleños!' WHERE `ID`=70019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 널 가만두지 않으실 것이다!', `MaleText_loc4`='地狱咆哮会得知此事！', `MaleText_loc5`='地獄吼會發現真相的!', `MaleText_loc7`='¡Esto llegará a oídos de Grito Infernal!', `FemaleText_loc1`='헬스크림 님께서 널 가만두지 않으실 것이다!', `FemaleText_loc4`='地狱咆哮会得知此事！', `FemaleText_loc5`='地獄吼會發現真相的!', `FemaleText_loc7`='¡Esto llegará a oídos de Grito Infernal!' WHERE `ID`=70022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 세뇌당한 야만인 따위가 아니다. 헬스크림 님께 반기를 드는 것은 호드의 가장 위대한 오크를 거부하는 것이다!', `MaleText_loc4`='我们不是什么被洗脑的野蛮人。违抗地狱咆哮就是和部落最伟大兽人作对！', `MaleText_loc5`='我們可不是什麼被心控的狂徒。違背地獄吼就是違背部落最偉大的獸人!', `MaleText_loc7`='No somos unos salvajes manipulados. Desafiar a Grito Infernal es desafiar a los orcos más grandiosos de la Horda.' WHERE `ID`=70023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 다음이 자네 차례네. 누가 끼어들지 않는다면 말이지만.', `MaleText_loc4`='下一个就是你了！除非有人插队。', `MaleText_loc5`='嗯，下個就是你...除非，有人插隊。', `MaleText_loc7`='¡Tú eres $gel:la; siguiente! A no ser que se te cuele alguien, claro está.' WHERE `ID`=70024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 자넨 두 번째 순서네. 조금만 기다리게.', `MaleText_loc4`='让我看看……你排在第二个。很快就轮到你了。', `MaleText_loc5`='嗯... 你是排第二的，很快就輪到你了。', `MaleText_loc7`='A ver... eres $gel segundo:la segunda; en la cola. No queda mucho.' WHERE `ID`=70025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명단을 보니 자네는 세 번째군, $c.', `MaleText_loc4`='看来你排在第三，$c。', `MaleText_loc5`='登記表上說你是排第三的，$c。', `MaleText_loc7`='Parece que eres $gel tercero:la tercera;, $c.' WHERE `ID`=70026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명단을 보니 자네는 네 번째군, $r.', `MaleText_loc4`='你现在是第四位，$r。', `MaleText_loc5`='你是登記表上排第四的，$r。', `MaleText_loc7`='Eres $gel cuarto:la cuarta;, $r.' WHERE `ID`=70027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대기열에서 다섯 번째군. 조금만 기다리면 될 걸세.', `MaleText_loc4`='你排在第五个。应该很快就会轮到你的。', `MaleText_loc5`='你是排第五的，應該再等一會兒就行。', `MaleText_loc7`='Estás en quinto puesto. No tendrás que esperar mucho.' WHERE `ID`=70028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네는... 여섯 번째 순서네.', `MaleText_loc4`='你排在……第六个。', `MaleText_loc5`='你是... 排第六的。', `MaleText_loc7`='Eres $gel sexto:la sexta;.' WHERE `ID`=70029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 명단에는 자네가 일곱 번째라고 나와 있는데.', `MaleText_loc4`='你排在第七个。', `MaleText_loc5`='在我的表上你是排第七的。', `MaleText_loc7`='Eres $gel séptimo:la séptima; en la lista.' WHERE `ID`=70030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 여덟 번째네, $r.', `MaleText_loc4`='你是第八个，$r。', `MaleText_loc5`='你是排第八的，$r。', `MaleText_loc7`='Eres $gel octavo:la octava; en la cola, $r.' WHERE `ID`=70031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 명단에 보면 자네는 아홉 번째네.', `MaleText_loc4`='你是第九个。', `MaleText_loc5`='目前你排第九。', `MaleText_loc7`='Eres $gel noveno:la novena;.' WHERE `ID`=70032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열 번째 순서군, 친구.', `MaleText_loc4`='你是第十个，孩子。', `MaleText_loc5`='嘿，你是排第十的。', `MaleText_loc7`='Eres $gel décimo:la décima;, $gchaval:chavala;.' WHERE `ID`=70033;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 싸웠습니다, $p. 자신의 힘을 증명해 보이셨군요.', `FemaleText_loc4`='精彩的战斗，$p，你证明了你的力量。', `FemaleText_loc5`='$p，你打得很好，你證明了自己的能耐。', `FemaleText_loc7`='Has luchado bien, $p, y has demostrado tu fuerza.' WHERE `ID`=70034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 바쁜 날이군. 자네 앞에 열 명 정도가 기다리고 있네. 그렇게 많이 기다려야 하지는 않을 거야.', `MaleText_loc4`='今天人很多。你前面至少还有十个人。不过应该不会更多了。', `MaleText_loc5`='今天真忙碌，你前面至少還有十個人在排隊，不過人數不會超過太多就是。', `MaleText_loc7`='Es un día ajetreado. Hay al menos diez personas en la cola antes que tú, pero no mucho más.' WHERE `ID`=70035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 앞에 적어도 열다섯 명 정도가 있는 것 같네. 정확히 알기는 어려운데... 오늘 너무 바빠서 말이야.', `MaleText_loc4`='你前面至少还有十五个人。这很难说——现在人有点儿多。', `MaleText_loc5`='你前面至少還有十五個人在排隊，現在這裡有點忙，所以也說不準。', `MaleText_loc7`='Hay al menos quince personas esperando antes que tú, pero es difícil de decir... Ahora mismo estamos muy ocupados.' WHERE `ID`=70036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조금만 더 기다리게. 자네가 오기 전에 스무 명 쯤 되는 사람들이 싸움을 신청해서 말야. 그보다 더 될지도 모르고.', `MaleText_loc4`='等着吧——你前面至少还有二十个人。没准还不止。', `MaleText_loc5`='繼續等。前面至少有二十個人比你先來，可能還不止。', `MaleText_loc7`='Espera $gsentado:sentada;. Hay al menos veinte personas que han llegado antes que tú. A lo mejor son más.' WHERE `ID`=70037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 모르겠군. 서른 번째인가? 어쩌면 마흔 번째일지도? 사람이 너무 많아서 아까부터는 숫자도 세지 않고 있네.', `MaleText_loc4`='说不准，我想你应该是第三十个？也许是第四十个？我刚才数糊涂了。', `MaleText_loc5`='很難說，我想你排到第三十號了吧?也許是四十號?我剛才就忘了數到哪了。', `MaleText_loc7`='Creo que eres el número... ¿treinta? ¿Cuarenta? Hace un rato que he perdido la cuenta.' WHERE `ID`=70038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사장님이 자네 앞에 적어도 오십 명의 싸움꾼들이 기다리고 있다고 하시더군.$b$b오늘 정말 꽤나 붐비는 날인걸.', `MaleText_loc4`='老板说你前面至少还有五十个人。$b$b我们就排到这里为止了。', `MaleText_loc5`='老闆說你前面至少有五十個人在排隊。$b$b這裡人滿為患。', `MaleText_loc7`='El jefe dice que hay como mínimo cincuenta personas en la cola antes que tú. Esto está hasta la bandera.' WHERE `ID`=70039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다리게, 친구.', `MaleText_loc4`='我马上就来，$g先生:女士;。', `MaleText_loc5`='這位$g先生:女士;，我馬上就過來招呼你。', `MaleText_loc7`='Ahora mismo te atiendo.' WHERE `ID`=70040;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='브라운스톤과 그의 게으름뱅이 작업자들은 건설 현장에서 잠들어 버리는 것으로 악명이 높습니다.', `FemaleText_loc4`='褐石大师和他的那些手下因为时常在工作中偷懒睡觉而臭名昭著。', `FemaleText_loc5`='褐石大師跟他的手下是出了名的拖拖拉拉。', `FemaleText_loc7`='Todo el mundo sabe que el maestro Piedra Cobriza y sus esbirros duermen en el trabajo.' WHERE `ID`=70041;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 느림보들의 엉덩이를 걷어차서, 방어선이 제때 구축될 수 있게 하겠습니다.', `FemaleText_loc4`='我得确保那些懒鬼有在好好干活儿并且把那段防御工事给造起来。', `FemaleText_loc5`='我會盯著這些懶惰鬼好好工作，完成防禦工事。', `FemaleText_loc7`='Me aseguraré de que esos vagos no se distraen y construyen las defensas.' WHERE `ID`=70042;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대재앙의 부두술 안으로 뛰어드십시오!', `MaleText_loc4`='快进入终极巫毒术的效果范围内！', `MaleText_loc5`='快進入巫毒護罩!', `MaleText_loc7`='¡Entra en el gran vudú malvado!' WHERE `ID`=70043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들에게 단 한 뼘의 땅도 내주지 않을 겁니다. 제 눈에 흙이 들어가기 전에는 말이지요.', `MaleText_loc4`='只要我还活着，我就不会让那些蛮子的阵线向前推进一寸。', `MaleText_loc5`='只要我還活著，就不會讓那些野蠻人侵犯我們一分一毫的土地。', `MaleText_loc7`='No vamos a cederles ni un centímetro de terreno a esos salvajes. No mientras yo siga con vida.' WHERE `ID`=70045;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='초목이 굶주렸다...', `FemaleText_loc4`='植物饿了……', `FemaleText_loc5`='植物感到飢餓...', `FemaleText_loc7`='Las plantas tienen hambre...' WHERE `ID`=70046;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 게 바로 진짜 발견이죠!', `FemaleText_loc4`='这可是个重大发现！', `FemaleText_loc5`='這可讓我大開眼界!', `FemaleText_loc7`='¡Qué descubrimiento!' WHERE `ID`=70047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퀘스트 하나만 선택할 수 있습니다.', `MaleText_loc4`='你只能选择一个任务。', `MaleText_loc5`='你只能選擇一個任務。', `MaleText_loc7`='Solo puedes seleccionar una misión.' WHERE `ID`=70048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처의 생명체 여러분, 안녕히! 다른 차원에서 저를 호출하고 있습니다.', `MaleText_loc4`='再见，附近的活体生物！独一无二的我即将被召唤到另一个位面。', `MaleText_loc5`='附近的生物，再會了!別的次元需要我獨特的存在。', `MaleText_loc7`='¡Adiós, seres vivos cercanos! Solicitan mi presencia inimitable en otra dimensión.' WHERE `ID`=70049;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내 육신이 대지로 돌아간다...', `FemaleText_loc4`='我的身体归于大地……', `FemaleText_loc5`='我的軀體歸於塵土...', `FemaleText_loc7`='Mi cuerpo vuelve a la tierra...' WHERE `ID`=70050;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='따끔한 가시가 돋힌 나무를 만났었다고 전해라!', `FemaleText_loc4`='去告诉其他人，林木有刺！', `FemaleText_loc5`='把話傳出去，植物可不是好惹的!', `FemaleText_loc7`='¡Corre la voz de que esta rosa tiene espinas!' WHERE `ID`=70051;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네가 양분이 되거라.', `FemaleText_loc4`='帮我喂饱它们吧。', `FemaleText_loc5`='幫我餵養它們。', `FemaleText_loc7`='Ayúdame a alimentarlas.' WHERE `ID`=70052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 놓은 침만큼 좋은 치료방법은 없지.', `MaleText_loc4`='没有什么东西能比针灸的疗效更好啦。', `MaleText_loc5`='針灸治百病啊。', `MaleText_loc7`='No hay nada más curativo que un puñado de agujas.' WHERE `ID`=70053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 전투 준비! 놈들이 또 몰려온다!', `MaleText_loc4`='坚持住，他们又回来了！', `MaleText_loc5`='各就各位，他們又來了!', `MaleText_loc7`='¡Prepárense! ¡Ya vuelven!' WHERE `ID`=70054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정신차려! 또 호드다!', `FemaleText_loc4`='小心，部落又来了！', `FemaleText_loc5`='當心，更多的部落來了!', `FemaleText_loc7`='¡Atención! ¡Vuelve la Horda!' WHERE `ID`=70055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 날이 올 줄이야! 다르나서스의 여인입니다! 다들 레오나 어스윈드의 승리에 판돈을 거세요!', `FemaleText_loc4`='我从没想过这一天会真的到来！竟然是达纳苏斯的女勇士！快用力拍你的手，把最热烈的掌声献给莉安娜·地风！', `FemaleText_loc5`='我從來沒想過能見到這一幕!來自達納蘇斯的少女!大夥用力鼓掌，歡迎雷歐娜·土風!', `FemaleText_loc7`='¡Jamás pensé que viviría para ver este día! ¡La damisela de Darnassus! ¡Un fuerte aplauso para Leona Terraviento!' WHERE `ID`=70056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고... 미트볼입니다.', `FemaleText_loc4`='另一位是……肉弹！', `FemaleText_loc5`='還有...肉糰。', `FemaleText_loc7`='Y... Albóndiga.' WHERE `ID`=70057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 날이 올 줄이야! 은퇴했던 최우수 싸움꾼이 돌아왔습니다! 다들 레오나 어스윈드의 승리에 판돈을 거세요!', `MaleText_loc4`='我从没想过这一天会真的到来！我们曾经的冠军，退役归来的勇士！快用力拍你的手，把最热烈的掌声献给莉安娜·地风！', `MaleText_loc5`='我從來沒想過能見到這一幕!我們的前任冠軍重出江湖了!大夥用力鼓掌，歡迎雷歐娜·土風!', `MaleText_loc7`='¡Jamás pensé que viviría para ver este día! ¡Nuestra antigua campeona vuelve a la lucha! ¡Un fuerte aplauso para Leona Terraviento!' WHERE `ID`=70058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고... 미트볼입니다.', `MaleText_loc4`='另一位是……肉弹！', `MaleText_loc5`='還有...肉糰。', `MaleText_loc7`='Y... Albóndiga.' WHERE `ID`=70059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 아들딸들이여! 오늘 그대들의 영웅들과 여기 있는 용사, $p|1이;가; 이 섬을 지켜냈다. 코르크론은 곧 닥칠 호드의 암흑기를 예고한다.', `MaleText_loc4`='部落的儿女们！今日你们之所以还能自由地站在这块土地上，全归功于这位英雄，$p！库卡隆的暴行宣告着部落进入了一个黑暗的时代。', `MaleText_loc5`='部落的兒女啊!今天你們的自由都得歸功於你們的英雄，以及這位勇士，$p!柯爾克隆出現在此，象徵了我們部落的黑暗時刻即將來臨。', `MaleText_loc7`='¡Hijos e hijas de la Horda! Hoy son libres gracias a la fuerza de sus héroes y a las hazañas de $p. La llegada de los Kor''kron vaticina tiempos oscuros para la Horda.' WHERE `ID`=70060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='--이쪽을 봐 주십시오, $P. 제 뒤쪽 방에 있는 인물들이 당신의 출석을 기다리고 있습니다.--', `MaleText_loc4`='——$P，请注意。你需要进入本单位身后的房间。——', `MaleText_loc5`='--請注意，$P。您必須進入本單元後方的密室。--', `MaleText_loc7`='--ATENCIÓN, $P. SE REQUIERE TU PRESENCIA EN LA CÁMARA SITUADA DETRÁS DE ESTA UNIDAD.--' WHERE `ID`=70061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아, 브라운스톤. 일할 시간이다!', `FemaleText_loc4`='好了，褐石，该干活儿了！', `FemaleText_loc5`='好了，褐石，該工作了!', `FemaleText_loc7`='¡Venga, Piedra Cobriza! ¡Hora de trabajar!' WHERE `ID`=70062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르 님께서 상황 보고를 요청하셨습니다.', `MaleText_loc4`='洛瑟玛想要知道实验的最新进展。', `MaleText_loc5`='洛索瑪想知道實驗進行得如何了。', `MaleText_loc7`='Lor''themar quiere un informe sobre el estado del experimento.', `FemaleText_loc1`='로르테마르 님께서 상황 보고를 요청하셨습니다.', `FemaleText_loc4`='洛瑟玛想要知道实验的最新进展。', `FemaleText_loc5`='洛索瑪想知道實驗進行得如何了。', `FemaleText_loc7`='Lor''themar quiere un informe sobre el estado del experimento.' WHERE `ID`=70063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 코룬 장치는 한때 우리가 악마의 힘을 취하려 했을 때 사용했던 지옥 수정과 비슷하오. 악마든, 성난 영혼이든, 추악한 감정의 물질적 발현이든, 원리는 상당히 비슷하지.$b$b우리는 이 유물 안에 든 존재가 얼마나 온전한지 확인해야 하오. 그대는 모구를 비롯해 판다리아의 여러 위험 요소를 이미 겪어 보았으니, 친절을 발휘해 이 역할을 맡아주지 않겠소?$b$b방어 수호물은 이미 대부분 비활성화시켰으니, 유물에 달린 강화 원반만 조작해 주면 되오. 안에서 뭐가 튀어나올지 모르니 조심하시오.', `MaleText_loc4`='这些寇茹设备和以前我们用来使驭恶魔能量的邪能水晶有些相似。无论是恶魔还是愤怒之魂还是某种情绪的元素具象产物，驾驭它们的原理都是相同的。$b$b我们需要调查一下存储在这件神器里的东西是否还保存完好。既然你已经在潘达利亚大陆上经历了这么多冒险，也和魔古族打过这么多交道，不知你是否有兴趣亲自动手？$b$b我们已经关闭了大部分的保护结界。你只需要手动调节一下这件神器的增强圆盘，然后准备好对付可能会蹦出来的东西就行。', `MaleText_loc5`='這個考倫裝置有點類似我們用來駕馭惡魔能量的魔化水晶。無論惡魔、憤怒的怨魂、還是情緒力量的具象化實體，基本原理都是差不多的。$b$b但是，我們必須知道封存在裡頭的東西完整度究竟如何。既然你是對魔古還有潘達利亞的其他危險生物最有經驗的人，我們是否有此榮幸能請你幫個忙呢?$b$b我們已經解除了絕大多數的防護結界，只要調整一下強化過的保護盤，然後準備應付跑出來的東西就行了。', `MaleText_loc7`='Este dispositivo Korune es similar a los cristales viles que antaño utilizábamos para esclavizar energías demoníacas. Ya se trate de un demonio, de un espíritu furioso o de la manifestación elemental de una emoción, el principio es más o menos el mismo.$b$bPero antes debemos comprobar cuán intacta permanece la entidad que contiene el artefacto. Dado que tienes experiencia con los mogu y demás peligros de Pandaria, ¿serías tan amable de hacer los honores?$b$bYa hemos desactivado casi todos los resguardos protectores. Solo tienes que ajustar el disco intensificador del dispositivo y prepararte para lo que salga.' WHERE `ID`=70064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황 보고를 원하는 게 로르테마르 님이오, 아니면 그분이 복종하는 가로쉬요?$b$b둘 다에게 전하시오. 이 실험은 시간 낭비라고. 모구는 살아 있는 다른 생명체의 정수를 힘의 근원으로 이용하오. 그게 우리 대족장이라는 자가 손대고 싶어할 만한 힘이요?$b$b이건 캘타스 선스트라이더가 걸었던 길과 같은 길이요. 그리고 캘타스는 우리 블러드 엘프를 거의 파멸시킬 뻔했지. 다시 우리에게 그 길을 걸으라고 하는 자에게서 우리가 왜 명령을 받고 있는 거요?', `MaleText_loc4`='洛瑟玛想知道最新的进展？我猜是他的主子加尔鲁什想知道吧？$b$b没关系，反正你可以告诉他们俩，这实验完全是浪费时间。魔古族的力量来自于剥夺其他生物的生命精华。难道我们的酋长会涉足这种邪恶的勾当？$b$b这是凯尔萨斯·逐日者曾经走过的邪道，而这段历史几乎毁掉了我们的人民。我们为什么要听命于某个想要令我们重蹈覆辙的人？', `MaleText_loc5`='是洛索瑪想知道?還是他的主人卡爾洛斯?$b$b你應該告訴他們兩個，這個實驗根本是浪費時間。魔古的力量來自於奴役其他生物的生命能量。這是我們大酋長應該做的嗎?$b$b這根本是當年凱爾薩斯·逐日者所走的路，而且它差點就毀了我們全族。我們為什麼要重蹈覆轍，為什麼要聽命於這樣的人?', `MaleText_loc7`='¿Lor''themar quiere un informe? ¿O es su amo Garrosh el que lo pide?$b$bDiles a los dos que este experimento es una pérdida de tiempo. Los mogu obtenían su poder esclavizando la esencia vital de otras criaturas. ¿Es eso algo en lo que deba meterse nuestro Jefe de Guerra?$b$bEs el mismo camino que ya recorrió Kael''thas Caminante del Sol, y casi fue el fin de nuestro pueblo. ¿Por qué aceptamos órdenes de alguien que quiere hacernos pasar por lo mismo?' WHERE `ID`=70065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종이 어디에 숨겨져 있는지 봤다고? 좋아. 가로쉬 대족장이 기뻐하겠군. 우선은 자네가 설명한 장소를 찾아내야 하네. 발견되는 즉시 자네에게 다시 연락하겠네.', `MaleText_loc4`='你知道圣钟被藏在哪里了？很好。加尔鲁什会很满意的。我们会试着找出你所描述的位置，一旦我们成功就会立即与你联系。', `MaleText_loc5`='你看到聖鐘被藏在哪裡了?太好了，卡爾洛斯一定會很滿意。我們會努力找出你所描述的那個地點，而且一找到它就會跟你聯絡。', `MaleText_loc7`='¿Has visto dónde se esconde la Campana divina? Muy bien. Garrosh se alegrará. Intentaremos localizar el lugar que has descrito y nos pondremos en contacto contigo en cuanto lo encontremos.' WHERE `ID`=70067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네도 오늘 싸움에 참여하나, $c?', `MaleText_loc4`='你今天要参加搏击吗，$c？', `MaleText_loc5`='$c，你今天要上場嗎?', `MaleText_loc7`='¿Hoy luchas, $c?' WHERE `ID`=70069;
