UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 싶으면 내게 말하게, $r.', `MaleText_loc4`='如果你想要打上两场，就来和我聊聊，$r。', `MaleText_loc5`='$r，想上場的話跟我說一聲。', `MaleText_loc7`='Avísame si quieres luchar, $r.' WHERE `ID`=70071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움판에 들어가고 싶으면 내게 말만 하게.', `MaleText_loc4`='如果你想要参加搏击，尽管告诉我就行。', `MaleText_loc5`='如果你想上場鬥陣，跟我說一聲就行。', `MaleText_loc7`='Si quieres unirte al combate, no tienes más que decirlo.' WHERE `ID`=70072;
