UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 놀이기구를 타려면 이용권을 내야 합니다! 이리 오셔서 이용권을 사십시오!', `MaleText_loc4`='先付钱才能玩，朋友！快来买木马门票了！', `MaleText_loc5`='你得花錢才能玩唷!快來換你的票喔!', `MaleText_loc7`='¡Para montar hay que pagar, colegas! ¡Venid y comprad vales de tiovivo!', `FemaleText_loc1`='다크문 놀이기구를 타려면 이용권을 내야 해요! 이리 오셔서 이용권을 사세요!', `FemaleText_loc4`='先付钱才能玩，朋友！快来买木马门票了！', `FemaleText_loc5`='你得花錢才能玩唷!快來換你的票喔!', `FemaleText_loc7`='¡Para montar hay que pagar, colegas! ¡Venid y comprad vales de tiovivo!' WHERE `ID`=70076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 놀이기구 탑승권 팝니다! 오셔서 탑승권을 사가십시오!', `MaleText_loc4`='木马门票大特价！快来买门票了！', `MaleText_loc5`='賣票喔!來這裡買旋轉木馬的票喔!', `MaleText_loc7`='¡Vales de tiovivo a la venta! ¡Venid y comprad vales de tiovivo!', `FemaleText_loc1`='다크문 놀이기구 탑승권 팔아요! 오셔서 탑승권을 사가세요!', `FemaleText_loc4`='木马门票大特价！快来买门票了！', `FemaleText_loc5`='賣票喔!來這裡買旋轉木馬的票喔!', `FemaleText_loc7`='¡Vales de tiovivo a la venta! ¡Venid y comprad vales de tiovivo!' WHERE `ID`=70077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 흔들 기구를 타려면 탑승권이 있어야 합니다! 이리 오셔서 이용권을 사십시오!', `MaleText_loc4`='你要先买木马门票才能玩旋转木马。快来买票了！', `MaleText_loc5`='你要有騎乘券才能玩，快來買吧!', `MaleText_loc7`='Para montar en el tiovivo os harán falta vales. ¡Venid y comprad vales de tiovivo!', `FemaleText_loc1`='다크문 흔들 기구를 타려면 탑승권이 있어야 해요! 이리 오셔서 이용권을 사세요!', `FemaleText_loc4`='你要先买木马门票才能玩旋转木马。快来买票了！', `FemaleText_loc5`='你要有騎乘券才能玩，快來買吧!', `FemaleText_loc7`='Para montar en el tiovivo os harán falta vales. ¡Venid y comprad vales de tiovivo!' WHERE `ID`=70078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자자, 어서 서두르십시오! 이리 오셔서 다크문 놀이기구 탑승권을 사가십시오!', `MaleText_loc4`='快来看快来买！旋转木马门票这边就有卖！', `MaleText_loc5`='快來，快來唷!來這裡買你的票喔!', `MaleText_loc7`='¡Venga, daos prisa! ¡Corred a comprar vales de tiovivo!', `FemaleText_loc1`='자자, 어서 서두르세요! 이리 오셔서 다크문 놀이기구 탑승권을 사가세요!', `FemaleText_loc4`='快来看快来买！旋转木马门票这边就有卖！', `FemaleText_loc5`='快來，快來唷!來這裡買你的票喔!', `FemaleText_loc7`='¡Venga, daos prisa! ¡Corred a comprar vales de tiovivo!' WHERE `ID`=70079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 놀이기구 탑승권입니다! 놀이기구 탑승권 묶음 사가십시오!', `MaleText_loc4`='木马门票！这边能买到一整套木马联票！', `MaleText_loc5`='騎乘券!來買一本騎乘券喔!', `MaleText_loc7`='¡Vales de tiovivo! ¡Venid a comprar un libro de vales de tiovivo!', `FemaleText_loc1`='다크문 놀이기구 탑승권이에요! 놀이기구 탑승권 묶음 사가세요!', `FemaleText_loc4`='木马门票！这边能买到一整套木马联票！', `FemaleText_loc5`='騎乘券!來買一本騎乘券喔!', `FemaleText_loc7`='¡Vales de tiovivo! ¡Venid a comprar un libro de vales de tiovivo!' WHERE `ID`=70080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만, 롬매스! 신도레이는 호드의 멍에를 벗어던져야 해!', `MaleText_loc4`='够了，罗曼斯！辛多雷必须从部落的桎梏中解脱出来！', `MaleText_loc5`='夠了，洛摩斯!辛多雷必須要掙脫部落的桎梏!', `MaleText_loc7`='¡Ya basta, Rommath! Los sin''dorei debemos liberarnos del yugo de la Horda.' WHERE `ID`=70081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 위장복을 사용한 후, 가로쉬아르 진군지 중앙에서 정보를 찾아야 합니다.', `MaleText_loc4`='使用库卡隆伪装，然后在加尔鲁什尔先锋营中寻找情报。', `MaleText_loc5`='利用柯爾克隆偽裝，然後在卡爾洛夏先遣營地裡收集情報。', `MaleText_loc7`='Ponte el disfraz Kor''kron y luego busca información en medio del Avance Garrosh''ar.', `FemaleText_loc1`='코르크론 위장복을 사용한 후, 가로쉬아르 진군지 중앙에서 정보를 찾아야 합니다.', `FemaleText_loc4`='使用库卡隆伪装，然后在加尔鲁什尔先锋营中寻找情报。', `FemaleText_loc5`='利用柯爾克隆偽裝，然後在卡爾洛夏先遣營地裡收集情報。', `FemaleText_loc7`='Ponte el disfraz Kor''kron y luego busca información en medio del Avance Garrosh''ar.' WHERE `ID`=70082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고?! 모구가 천상의 종을 어디에 숨겼는지 봤다고? 난 지금 당장 사자의 상륙지에 이 소식을 전하겠네. 가로쉬보다 먼저 그 종을 찾아내야 하네! 그걸 발견하면 즉시 자네에게 연락하겠네!', `MaleText_loc4`='什么？！你知道魔古族把圣钟藏在哪里了？我必须立刻警告雄师港。我们必须赶在加尔鲁什之前拿到圣钟！一旦我们找到它就会马上通知你！', `MaleText_loc5`='什麼?!你看到魔古藏匿聖鐘的地點了嗎?我得馬上通知雄獅灘。我們必須早卡爾洛斯一步取得聖鐘才行。等找到之後我們會馬上通知你的。', `MaleText_loc7`='¡¿QUÉ?! ¿Viste dónde escondieron los mogu la Campana divina? Alertaré al Desembarco del León de inmediato. ¡Debemos encontrarla antes que Garrosh! Nos pondremos en contacto contigo en cuanto la localicemos.' WHERE `ID`=70083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자! 벌레 같은 놈! 도망가라! 내가 짓밟아 줄 테니!', `MaleText_loc4`='闯入者！渣滓！臭虫！我会把你打烂！', `MaleText_loc5`='闖入者!臭蟲!跳蚤!我要掃光你們!', `MaleText_loc7`='¡INTRUSO! ¡Insecto! ¡Microbio! ¡Te aplastaré!' WHERE `ID`=70084;
