UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 슬슬 지겹네요. 다들 그렇죠?', `FemaleText_loc4`='我觉得吧，这场无聊的闷战我们已经看够了。对吧？', `FemaleText_loc5`='我們應該已經看夠了，你說是吧?', `FemaleText_loc7`='Creo que ya hemos visto bastante. ¿Estáis de acuerdo?' WHERE `ID`=70137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열기가 점점 뜨거워지나요? 저만 그렇게 느끼는 건가요?', `MaleText_loc4`='这儿是不是热起来了？是我的错觉吗？', `MaleText_loc5`='是不是有點熱了?還是只有我這麼覺得?', `MaleText_loc7`='¿Es cosa mía o está subiendo la temperatura?' WHERE `ID`=70138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움을 밤새 계속할 수는 없습니다. 서두르세요!', `MaleText_loc4`='我们可不能让你们打上一整晚。抓紧时间了！', `MaleText_loc5`='動作快啊，我們可不想陪你消磨一整晚!', `MaleText_loc7`='No tenemos toda la noche. ¡Daos prisa!' WHERE `ID`=70139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 슬슬 끝내야 할 시간입니다.', `MaleText_loc4`='我觉得你们差不多该动真格的了。', `MaleText_loc5`='差不多該取消這場比賽了。', `MaleText_loc7`='Creo que es hora de poner fin al combate.' WHERE `ID`=70140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 얼마 없어요!', `MaleText_loc4`='时间就要到了！', `MaleText_loc5`='時間快到了!', `MaleText_loc7`='¡Casi se ha acabado el tiempo!' WHERE `ID`=70141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='연기 냄새가 나지요?', `MaleText_loc4`='你闻到烟味了吗？', `MaleText_loc5`='你有聞到煙味嗎?', `MaleText_loc7`='¿Alguien más huele humo?' WHERE `ID`=70142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불길이 다가옵니다!', `MaleText_loc4`='火要烧起来了！', `MaleText_loc5`='火燒過來了!', `MaleText_loc7`='¡Es la hora del fuego!' WHERE `ID`=70143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아시겠지만, 싸우겠다는 사람들이 줄을 서 있다고요.', `MaleText_loc4`='好吧，好吧，后面还有一堆人等着要打呢，你懂的。', `MaleText_loc5`='你知道的，我們一大票的人在排隊等著要參加。', `MaleText_loc7`='Tenemos una lista llena de gente que quiere luchar, ¿sabes?' WHERE `ID`=70144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 슬슬 지겹네요. 다들 그렇죠?', `MaleText_loc4`='我觉得吧，这场无聊的闷战我们已经看够了。对吧？', `MaleText_loc5`='我想我們應該見夠了吧?', `MaleText_loc7`='Creo que ya hemos visto bastante. ¿Estáis de acuerdo?' WHERE `ID`=70145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까! 놀이기구를 타시겠다고요? 저 타조 위에 올라타십시오!', `MaleText_loc4`='嘿！想要搭一程吗？骑我们的陆行鸟吧！', `MaleText_loc5`='嗨，要載你一程嗎?跳上陸行鳥吧!', `MaleText_loc7`='¡Hola! ¿Necesitas transporte? ¡Sube a un zancaalta!' WHERE `ID`=70146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀이 기구를 타시려면 여기 있는 것들 중 하나 골라 타십시오!', `MaleText_loc4`='如果你需要坐骑，别客气，骑上这些小可爱吧！', `MaleText_loc5`='要人接送的話，就挑隻寶貝騎上去吧!', `MaleText_loc7`='Si quieres bajar, ¡coge una de estas bellezas!' WHERE `ID`=70147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다크문 섬에 오신 것을 환영합니다! 다크문 축제에 있는 이 사랑스러운 야수 중 자유롭게 골라서 타보십시오!', `MaleText_loc4`='欢迎来到暗月岛！你可以骑着这些可爱的动物前往马戏团。', `MaleText_loc5`='歡迎來到暗月島!請隨意挑隻喜歡的坐騎前往馬戲團!', `MaleText_loc7`='¡$gBienvenido:Bienvenida; a la Isla Luna Negra! Monta en una de estas bestias adorables y baja a la feria.' WHERE `ID`=70148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='웅장한 숲타조들입니다! 다크문 축제에서 공짜로 타보십시오!', `MaleText_loc4`='巨型森林陆行鸟！前往暗月马戏团的免费坐骑！', `MaleText_loc5`='來騎森林陸行鳥喔!免費送你到暗月馬戲團!', `MaleText_loc7`='¡Majestuosos zancudos del bosque! ¡Transporte gratis a la Feria de la Luna Negra!' WHERE `ID`=70149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청이들! 너희가 싸움을 벌이게 하는 모든 감정이 바로 내가 지배하는 것들이다... 공포, 분노, 의심... 이것들이 나의 무기다!', `MaleText_loc4`='蠢货！我能控制那些驱动你战斗的情绪……恐惧，愤怒，疑惑……这些是我的武器！', `MaleText_loc5`='蠢貨!我操控的正是驅使你們作戰的力量...恐懼、憤怒、疑惑，通通是我的武器!', `MaleText_loc7`='¡Estúpidos! Yo controlo lo que los impulsa a luchar... ¡El miedo, la ira y la duda son mis armas!' WHERE `ID`=70150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포... 분노... 의심... 이것들은 무기다. 나의 무기이지. 그리고 이 무기들이 너희를 파멸시킬 것이다!', `MaleText_loc4`='恐惧，愤怒，疑惑……这些情绪都是武器。我的武器。它们会让你死无葬身之地！', `MaleText_loc5`='恐懼、憤怒，疑惑，通通是武器!我的武器!消滅你們的武器!', `MaleText_loc7`='El miedo... la ira... la duda... son armas. MIS armas. ¡Y serán su perdición!' WHERE `ID`=70151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 지저분한 짐승들을 제대로 묶어 놔라!', `MaleText_loc4`='让那些肮脏的野兽老实点！', `MaleText_loc5`='制伏那些骯髒的野獸!', `MaleText_loc7`='¡Controlad a esas bestias apestosas!' WHERE `ID`=70152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 역겨운 얼라이언스 스파이 냄새가 나는군!', `MaleText_loc4`='我闻到了联盟间谍渣滓的味道！', `MaleText_loc5`='我就知道有聯盟的臭間諜!', `MaleText_loc7`='¡Sabía que olía a sucios espías de la Alianza!' WHERE `ID`=70153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아!', `MaleText_loc4`='啊！', `MaleText_loc5`='呃啊!', `MaleText_loc7`='¡ARGH!' WHERE `ID`=70154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 통치가 170년째 되던 해, 코룬 주문술사들이 레이 션에게 자신들의 가장 위대한 창조물을 가지고 왔다.', `MaleText_loc4`='[PLACEHOLDER CINEMATIC!!!!!!] In the one-hundred-and-seventieth year of the Thunder King''s reign, the Korune spellweavers came to Lei Shen with their greatest creation.', `MaleText_loc5`='在雷王統治的第一百七十年，考倫織法者們帶著他們最偉大的創造品來到雷神面前。', `MaleText_loc7`='En el año ciento setenta del reinado del Rey del Trueno, los tejehechizos Korune acudieron a Lei Shen con su mejor creación.' WHERE `ID`=70155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조자들의 살점으로 주조되고, 별의 불꽃으로 조형되었으며, 칠흑 같은 그늘의 숨결로 결속된 종이었다.', `MaleText_loc4`='一口以血肉为坯，以星辰之火锻造，以大地之血熔接而成的大钟。', `MaleText_loc5`='那是一個用造物者的血肉、用星星之火，以及最黑暗的陰影束縛所雕刻出來的鐘。', `MaleText_loc7`='Una campana fundida con carne del creador, forjada con fuego estelar y unida con aliento de sombra tenebrosa.' WHERE `ID`=70156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 종이 울리면, 세상이 흔들리고 하늘이 울렸다.', `MaleText_loc4`='这口钟响起时，足以震动世界，上达天听。', `MaleText_loc5`='被敲響時，這座鐘的聲音能震撼大地並傳至天堂。', `MaleText_loc7`='El sonido de la campana sacudía la tierra y clamaba a los cielos.' WHERE `ID`=70157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종은 전장에서, 귀에 거슬리는 소리로 레이 션의 전사들의 마음을 뒤흔들었다.', `MaleText_loc4`='在战场上，那钟声能让雷神的战士们热血沸腾。', `MaleText_loc5`='在戰場上，震懾人心的音調會翻攪雷神戰士的心智。', `MaleText_loc7`='En la guerra, sus discordantes ecos enardecían los corazones de los guerreros de Lei Shen.' WHERE `ID`=70158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 소리는 그들의 증오와 분노에 불을 지펴, 싸울 힘을 이끌어냈다.', `MaleText_loc4`='它能催化恨意和怒火，让战士们在战场上获得力量。', `MaleText_loc5`='激起他們的仇恨與憤怒，在戰場上賦予他們力量。', `MaleText_loc7`='Alimentaba su odio y su rabia, les daba fuerzas en el campo de batalla.' WHERE `ID`=70159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비명을 지르는 듯한 종소리는 황제의 적에게 공포와 의심을 불어넣어, 뿔뿔이 도망치게 만들었다.', `MaleText_loc4`='圣钟的尖啸还能在皇帝的敌人心中植入恐惧和猜忌，让他们望风而逃。', `MaleText_loc5`='鐘的尖銳聲響將恐懼和疑惑烙入帝王敵人的心中，驅使他們逃離戰場。', `MaleText_loc7`='La estridente voz de la campana inundaba de miedo y duda a los enemigos del Emperador, y los hacía huir despavoridos.' WHERE `ID`=70160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 힘을 외경한 천둥왕은 그 종소리를 가리켜 "신의 목소리"라 하였고, 종을 "천상의 종"이라 칭했다.', `MaleText_loc4`='雷电之王对它的力量敬畏不已，称它为“众神之声”，并将它命名为圣钟。', `MaleText_loc5`='敬其神力，雷王稱此兵器為『眾神之音』，並將它命名為『聖鐘』神擎。', `MaleText_loc7`='Maravillado por su poder, el Rey del Trueno la describió como "la voz de los dioses" y le dio el nombre de Campana divina.' WHERE `ID`=70161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕이 몰락하자, 종은 다른 손에 들어갔다. 많은 이들이 종의 힘을 이용하려 했고, 어떤 이들은 종소리를 멈추려 했다. 하나 모두 실패했다.', `MaleText_loc4`='后来，雷电之王陨落，圣钟几易其手。许多人觊觎它的力量。也有人想让它永远沉寂。可他们都失败了。', `MaleText_loc5`='直到雷王隕逝後，聖鐘輾轉經過多人之手。許多人肖想要利用它的力量，有些人則想要讓它從此沉默。但全部都失敗了。', `MaleText_loc7`='Con el tiempo, el Rey del Trueno cayó y la Campana cambió de manos. Muchos intentaron usar su poder. Algunos intentaron silenciarla. Todos fracasaron.' WHERE `ID`=70162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국 코룬 주문술사들이 종을 되찾아 숨겼다. 그 후 천상의 종은 전설로 남게 되었다.', `MaleText_loc4`='最终，寇茹织法者夺回了圣钟，把它藏了起来。从此，圣钟就失落在了历史的长河之中。', `MaleText_loc5`='最後，考倫織法者取回了他們所創造的神器並將其藏匿起來。自此之後，聖鐘就從歷史上消失了。', `MaleText_loc7`='Al final, los tejehechizos Korune reclamaron su Campana y la escondieron. Desde entonces, ha permanecido oculta.' WHERE `ID`=70163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈! 너와 너의 모구 부하들은 강대한 호드와는 상대가 되지 않는다!', `MaleText_loc4`='可怜虫！你和你那些魔古族根本无法和部落的力量匹敌。', `MaleText_loc5`='笑話!在強大的部落面前你們魔古根本不算什麼!', `MaleText_loc7`='Patético. ¡Tus mogu y tú no son nada ante el poderío de la Horda!' WHERE `ID`=70164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 이 쓰레기야, 목숨이 아깝거든 내가 원하는 정보를 내놓아라.', `MaleText_loc4`='现在……如果你还想要活命，废物，就好好回答我的问题。', `MaleText_loc5`='好了，廢物...想活命的話，就把我想知道的都告訴我。', `MaleText_loc7`='Ahora... si valoras tu vida, escoria, me dirás lo que quiero saber.' WHERE `ID`=70165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관 스카가쉬가 맹렬한 분노에 사로잡혔습니다! 스카가쉬의 근접 공격을 피하십시오!', `MaleText_loc4`='指挥官斯卡格尔变得狂怒无比！避开他的近战攻击！', `MaleText_loc5`='指揮官疤口怒不可抑!避開他的近戰攻擊!', `MaleText_loc7`='¡El comandante Sangrescara está lleno de ira! ¡Evita sus ataques cuerpo a cuerpo!' WHERE `ID`=70166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피를 뒤집어써 주마!', `MaleText_loc4`='我会让你血流成河！', `MaleText_loc5`='我要用你的血來泡澡!', `MaleText_loc7`='¡Me bañaré en su sangre!' WHERE `ID`=70167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종은 어디 있나?!', `MaleText_loc4`='圣钟在哪里？！', `MaleText_loc5`='聖鐘在哪裡?!', `MaleText_loc7`='¡¿Dónde está la Campana divina?!' WHERE `ID`=70168;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안 폐하가 당신도 보냈군요? 내 도시에서 수적으로 불리한 입장이 되다니!$b$b<짓궂게 눈을 반짝이는 제이나>$b$b좀 다른 방식으로 접근해 보죠. 당신이 제 입장이 되어 보는 거예요. 바로 당신이 키린 토의 지도자라고 상상해 보세요. $p 님! 아제로스 전역에서 가장 영향력 있는 대마법사 말이죠!$b$b당신이라면 어떻게 하시겠어요?', `FemaleText_loc4`='瓦里安把你也派来了？好吧，我都快在自己的城市里被你们包围了！$b$b<吉安娜佯装生气地眨了眨眼睛。>$b$b让我们换个方法来讨论这件事。假设你正处于我的立场，想象一下，你就是肯瑞托的领袖。$p！艾泽拉斯最有影响力的大法师！$b$b你会怎么做？', `FemaleText_loc5`='瓦里安也派你來了?我竟然在我自己的城市被團團包圍!$b$b<珍娜的眼睛調皮地眨了眨。>$b$b讓我們換個角度來說這件事。站在我的立場想一想。如果你是祈倫托的領袖，$p!全艾澤拉斯最有影響力的大法師!$b$b你會怎麼做?', `FemaleText_loc7`='¿Varian también te ha enviado a ti? ¡Estoy en desventaja en mi propia ciudad!$b$b<Jaina entrecierra los ojos con suspicacia.>$b$bHagamos algo distinto. Ponte en mi lugar. Imagínate que TÚ lideras el Kirin Tor. ¡$p, $gel archimago:la archimaga; más influyente de todo Azeroth!$b$b¿Qué harías en mi lugar?' WHERE `ID`=70169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... <콜록>... 어린 종족들은... 참을성이 없다. 어린애처럼 성급하지. 오크... 넌 자기 자신도 통제하지 못해... 자신의 분노를, 자신의 공포를.', `MaleText_loc4`='哈……<咳嗽>……你们这些年轻的种族……总是易怒而缺乏耐心。兽人……你甚至不能控制自己的愤怒……和恐惧。', `MaleText_loc5`='哈...<咳嗽>...你們這些稚嫩無知的東西...既任性又缺乏耐性。你們獸人...甚至連自己都控制不了...控制不了你們的憤怒，控制不了你們的恐懼。', `MaleText_loc7`='Ja... <tos> Las razas jóvenes... tan impacientes, tan engreídas. Orcos… no pueden controlarse ni a ustedes mismos... su propia ira, su propio miedo...' WHERE `ID`=70170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 네놈에게... 할 말이 없다.', `MaleText_loc4`='我……什么都不会……告诉你们。', `MaleText_loc5`='我... 什麼也不會... 告訴你。', `MaleText_loc7`='No... te diré... nada.' WHERE `ID`=70171;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='충직한 얼라이언스 $c다운 대답이군요! 저도 그 마음 이해해요. 정말로요.$b$b자, 그럼, 키린 토의 지도자이자 얼라이언스에게 충성을 바치는 개인으로서, 선리버를 어떻게 하시겠어요? 네, 그들은 공개적으로 호드를 지지하죠. 하지만 선리버는 2천 년도 넘는 오랜 시간 동안 키린 토의 동맹이자, 생산적인 구성원이었어요. 이 도시는 그들의 고향이기도 하죠.$b$B선리버를 내쫓으시겠어요?', `FemaleText_loc4`='哈，不愧是忠实可靠的联盟$c！相信我，我理解这种情绪。$b$b接下来，作为肯瑞托的领袖，与此同时还是忠实的联盟成员，你会如何处置夺日者？诚然，他们是部落的支持者，但在过去的两千年中，他们也是肯瑞托的重要成员。这座城市也是他们的家园。$b$b你会驱逐他们吗？', `FemaleText_loc5`='這真是英勇的聯盟$c會說出的話!相信我，我能夠理解你的想法。$b$b那麼，如果你身為祈倫托的領袖，以及效忠聯盟的一員，你要怎麼對付奪日者呢?沒錯，他們是部落的擁護者。不過他們已經跟祈倫托結盟並做出貢獻有2000年之久。這座城市是他們的家鄉。$b$B你會驅逐他們嗎?', `FemaleText_loc7`='¡Hablas como $gun auténtico:una auténtica; $c de la Alianza! Créeme, sé cómo te sientes.$b$bBien, como líder del Kirin Tor y fiel $gsúbdito:súbdita; de la Alianza, ¿qué haces con los Atracasol? Es cierto que son leales a la Horda, pero han sido aliados y miembros productivos del Kirin Tor desde hace más de 2000 años. Esta ciudad es su hogar.$b$b¿Los expulsarías?' WHERE `ID`=70172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 호드는 호드죠.', `MaleText_loc4`='是，他们归根到底还是部落。', `MaleText_loc5`='我會的。部落就是部落，沒什麼好說的。', `MaleText_loc7`='Sí. La Horda es la Horda.', `FemaleText_loc1`='네. 호드는 호드죠.', `FemaleText_loc4`='是，他们归根到底还是部落。', `FemaleText_loc5`='我會的。部落就是部落，沒什麼好說的。', `FemaleText_loc7`='Sí. La Horda es la Horda.' WHERE `ID`=70173;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<슬픈 눈빛이 되는 제이나>$b$b그럼... 당신은 도시를 정화하겠군요? 선리버를 고향에서 축출하시겠네요? 최초에 인간에게 마법을 알려준 게 바로 그 선리버인데도요?$b$b당신과 나는 참으로 다르군요. 저는 제 역할과... 키린 토의 임무를 당신과는 조금 다르게 보고 있는 것 같아요. 전 마음을 정했어요. 제 생각을 듣고 싶으신가요?', `FemaleText_loc4`='<吉安娜的眼神有些悲伤。>$b$b所以说……你要肃清这座城市？你要把夺日者，那些曾经帮助人类洞悉魔法奥秘的人，赶出他们自己的家园？$b$b显然，你我持有不同的观点。我很明白我应该扮演的角色——以及肯瑞托的任务——和你的希望有所不同。我的心意已决。你想听听我的想法吗？', `FemaleText_loc5`='<珍娜的眼神陷入悲傷。>$b$b所以...你會整肅這城市?把奪日者們從他們的家鄉驅逐出去?驅逐這些幫助人類發現魔法的奪日者?$b$b看來我們之間的觀點非常不同。我想我對我的角色，以及祈倫托的任務，與你的看法不太一樣。我的心意已定。你想知道我是怎麼想的嗎?', `FemaleText_loc7`='<La mirada de Jaina se vuelve triste.>$b$bEntonces... ¿tú purgarías la ciudad? ¿Expulsarías a los Atracasol de sus hogares? ¿Los mismos Atracasol que ayudaron a los humanos a descubrir la magia?$b$bEstá claro que tú y yo somos muy diferentes. Creo que yo veo mi papel, y la misión del Kirin Tor, de forma un poco distinta. Me he decidido. ¿Quieres saber lo que pienso?' WHERE `ID`=70174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확신하십니까?', `MaleText_loc4`='你确定吗？', `MaleText_loc5`='你確定嗎?', `MaleText_loc7`='¿Estás segura?', `FemaleText_loc1`='확신하시나요?', `FemaleText_loc4`='你确定吗？', `FemaleText_loc5`='你確定嗎?', `FemaleText_loc7`='¿Estás segura?' WHERE `ID`=70175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해라. 말하지 않으면 숨통을 짓밟아 버릴 테니!', `MaleText_loc4`='不是你死就是我活！', `MaleText_loc5`='你一定會的，否則我一定會把我的靴子塞進你喉嚨!', `MaleText_loc7`='¡HABLARÁS, o te haré tragar mi bota!' WHERE `ID`=70176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버가 호드를 포기한다면, 그러지 않을 겁니다.', `MaleText_loc4`='除非他们放弃与部落的盟约。', `MaleText_loc5`='如果他們放棄支持部落就不會。', `MaleText_loc7`='No, siempre y cuando renuncien a la Horda.', `FemaleText_loc1`='선리버가 호드를 포기한다면, 그러지 않을 거예요.', `FemaleText_loc4`='除非他们放弃与部落的盟约。', `FemaleText_loc5`='如果他們放棄支持部落就不會。', `FemaleText_loc7`='No, siempre y cuando renuncien a la Horda.' WHERE `ID`=70177;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<생각에 잠겨 머리를 쓸어올리는 제이나>$b$b당신은 얼라이언스의 대의에 열정적이고, 확신에 차 있군요. 선리버도 당신과 마찬가지랍니다. 호드는 그들의 가족이에요.$b$b그들 모두가 가로쉬를 지지하는 건 아닙니다. 하지만 선리버는 형제들을 버리지 않을 거예요... 키린 토를 갈라놓을 각오를 하지 않고는, 선리버에게 호드를 버리라고 요구할 수 없어요.$b$b키린 토가 저를 의지하고 있습니다. 우리는 뭉쳐야 해요.', `FemaleText_loc4`='<吉安娜轻轻拨弄着眼前的一缕金发，陷入了沉思。>$b$b你对你们的事业无比热忱，并且意志坚定。但相信我，夺日者和你是一样的。部落是他们的家人。$b$b并不是所有的部落都支持加尔鲁什，但他们不会抛弃自己的人民……我不能驱逐他们，这样会让肯瑞托分裂。$b$b对我来说，肯瑞托是一个神圣的词。我们必须团结一致。', `FemaleText_loc5`='<珍娜撥開她眼前的髮絲，深深地思考著。>$b$b你對你所認定的意念是如此的堅定。相信我，奪日者也是一樣的。部落是他們的家人。$b$b雖然他們之中不是所有人都支持卡爾洛斯。不過這些人是不會拋棄他們的族人的...如果我要求他們這麼做只會讓祈倫托四分五裂。$b$b祈倫托在我心中有著神聖的地位。我們必須團結一心。', `FemaleText_loc7`='<Jaina se aparta el pelo de los ojos, pensativa.>$b$bSientes mucha pasión por tu causa y tus principios son muy claros. Créeme, los Atracasol son iguales. La Horda es su familia.$b$bNo todos apoyan a Garrosh, pero no abandonarán a su propia gente... No podría pedirles que lo hicieran sin dividir a todo el Kirin Tor.$b$bEl Kirin Tor es sagrado para mí. Debemos permanecer unidos.' WHERE `ID`=70178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='중립으로 남으려고 애쓸 겁니다.', `MaleText_loc4`='我会挣扎着保持中立。', `MaleText_loc5`='我會努力維持我們的中立。', `MaleText_loc7`='Me esforzaría por mantener la neutralidad.', `FemaleText_loc1`='중립으로 남으려고 애쓸 거예요.', `FemaleText_loc4`='我会挣扎着保持中立。', `FemaleText_loc5`='我會努力維持我們的中立。', `FemaleText_loc7`='Me esforzaría por mantener la neutralidad.' WHERE `ID`=70179;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<웃음 짓는 제이나>$b$b우리 모두 당신처럼 의지력과 신념이 강하다면 얼마나 좋을까요! 솔직히 말씀드리면, 전 매일 번뇌해요. 하루도 빠짐없이.$b$b하지만 당신이 맞아요. 키린 토는 당신이나 저, 얼라이언스나 호드보다 더 큰 무엇이에요. 제게는 키린 토를 유지하고, 그 힘을 현명하게 사용할 의무가 있어요.$b$b당신과 나는 의견의 일치를 이룬 것 같군요. 폐하께서 동의하실지는 의문이에요. 하지만... 어쩌면 안두인은 설득할 수 있지 않을까요?', `FemaleText_loc4`='<吉安娜露出了微笑。>$b$b要是我们能够分享你的力量和信念就好了！老实说。我每一天都在挣扎。每一天。$b$b但你说的没错，肯瑞托高于你我，高于联盟。我有责任去维持肯瑞托的舷窗，并且明智地使用它的力量。$b$b看上去，你我能达成共识，但我怀疑暴风城国王是否也能认同这一点。不过……你觉得我们能说服安度因吗？', `FemaleText_loc5`='<珍娜微笑。>$b$b如果我們都有你的力量與信念就好了!老實說，我很糾結，每一天都是如此。$b$b不過你說的對，祈倫托比你，我，聯盟或部落都更重要。我的肩上擔著維護它的責任，我必須睿智地使用它的力量。$b$b看來我們兩個的意見一致。我不認為國王想的會跟我們一樣。不過...你覺得我們能夠說服安杜因嗎?', `FemaleText_loc7`='<Jaina sonríe.>$b$b¡Ojalá todo el mundo tuviera tu fuerza y tu convicción! Para serte sincera, yo me esfuerzo todos los días.$b$bPero tienes razón, el Kirin Tor es más grande que tú, yo, la Alianza y la Horda. Tengo la responsabilidad de protegerlo y utilizar su poder con prudencia.$b$bParece que tú y yo estamos de acuerdo, pero no creo que el Rey lo vea de la misma forma. ¿Crees que podremos convencer a Anduin?' WHERE `ID`=70180;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 이런 시기에 입 밖에 내기엔 참으로 용감한 결정이로군요. 당신의 솔직함이 마음에 들어요!$b$b자, 키린 토의 지도자님, 그럼 말씀해 보세요. 호드가 당신의 친구들을, 당신의 가족들을 죽였다면 어쩌시겠어요? 당신이 가진 모든 것을 파괴했다면요? 그래도 지금 같은 결정을 내리실 건가요, 대마법사 $p 님?', `FemaleText_loc4`='啊！真是个勇敢的决定，特别是在现在这样的时代。你的诚实令人耳目一新！$b$b告诉我，肯瑞托的领袖，如果部落杀死了你的朋友，夺走了你的家庭，摧毁了你拥有的一切，请问，你是否还能保持你的信念，大法师$p？', `FemaleText_loc5`='啊!在這種情況下真是一個大膽的決定。你的誠實實在出乎意料!$b$b告訴我，祈倫托的領袖，如果部落殺害了你的朋友呢?你的家人?摧毀了你所有擁有的東西。你還是能夠堅定維持你的信念嗎，大法師$p?', `FemaleText_loc7`='¡Ah! Una decisión audaz en estos tiempos que corren. ¡Tu sinceridad es un soplo de aire fresco!$b$bDime, líder del Kirin Tor, ¿y si la Horda asesinara a tus amigos, a tu familia? ¿Y si destruyera todo lo que posees? ¿Mantendrías tu convicción entonces, $garchimago:archimaga; $p?' WHERE `ID`=70181;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<따뜻한 눈길을 보내는 제이나>$b$b아, 저와 마음이 맞는군요! 고마워요, $p 님. 솔직하게 대답해 줘서요. 당신은 제 고뇌를 이해하시는 것 같군요. 전 날마다, 어려운 결정을 내려요. 그리고 매일 밤... 악몽을 꾸지요.$b$b하지만 제겐 키린 토를 지킬 의무가 있어요. 저와 생각을 같이해 주셔서 기뻐요. 폐하께선 절대로 이런 식으로 생각하지 않으실 거예요. 하지만, 안두인에게는 설명할 수도 있지 않을까요?', `FemaleText_loc4`='<吉安娜的语气立马变得热情起来。>$b$b你我有同样的灵魂！感谢你，$p，感谢你的诚实。你似乎能理解我的挣扎。没错，我每一天都在挣扎，这是艰难的决定。每个夜晚都是梦魇……$b$b但我有责任维持肯瑞托的现状。我很高兴，你和我持有同样的观点。但暴风城国王一定不会这样想。你觉得我们能和安度因解释吗？', `FemaleText_loc5`='<珍娜對你熱絡了起來。>$b$b我們的看法一致!謝謝你誠實的說出來，$p。你看來能夠了解我所糾結的地方。每個早晨，我都要做出困難的決定。每個晚上...都要面對隨之而來的惡夢。$b$b不過我的肩上擔負著維護祈倫托的重任。我很高興你在這件事上跟我站在一起。國王是不可能同意我們的想法的。你覺得我們能夠說服安杜因嗎?', `FemaleText_loc7`='<Jaina te muestra su simpatía.>$b$b¡No soy la única! Gracias, $p, por tu sinceridad. Parece que entiendes mi conflicto. Todos los días hay decisiones difíciles. Todas las noches hay... pesadillas.$b$bPero tengo la responsabilidad de proteger el Kirin Tor. Me alegro de que estés de acuerdo. El Rey nunca lo verá de esta forma. ¿Crees que podremos convencer a Anduin?' WHERE `ID`=70182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*에헴* 안녕하세요, 여행자님!', `MaleText_loc4`='*嗯哼*你好啊，旅行者！', `MaleText_loc5`='*嗯哼* 你好啊，旅行者!', `MaleText_loc7`='Ejem... ¡Saludos, $gviajero:viajera;!' WHERE `ID`=70183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 돌아왔다, 우낏들아아아아아!', `MaleText_loc4`='无毛怪，我回来了！', `MaleText_loc5`='怪怪人，我回～～～～來了!', `MaleText_loc7`='¡Yo haaaaaaaaaaaa vuelto, makakus!' WHERE `ID`=70184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하... <기침>... 천상의 종이라... 그걸로 뭘 하고 싶은 게냐?', `MaleText_loc4`='哈……<咳嗽>……圣钟……你们竟然想要利用它？', `MaleText_loc5`='哈...<咳嗽>...聖鐘...你以為能拿它做什麼?', `MaleText_loc7`='Ja... <tos> La Campana divina... ¿qué esperáis hacer con ella?' WHERE `ID`=70185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 종은... 신의 목소리로 울린다...', `MaleText_loc4`='圣钟的声音……是神之声……', `MaleText_loc5`='聖鐘...發出的是眾神之音...', `MaleText_loc7`='La campana... habla con la voz de los dioses...' WHERE `ID`=70186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<콜록>... 너는 버릇없고, 성급해. 어린애처럼 말이다. 너는... 자기 자신도 통제하지 못해... 자신의 공포를... 자신의 분노를.', `MaleText_loc4`='<咳嗽>……你们易怒而天真，又缺乏耐心。你们甚至不能……控制自己的恐惧……和愤怒。', `MaleText_loc5`='<咳嗽>...你們這些稚嫩無知的東西...既任性又缺乏耐性。你們連自己都控制不了...控制不了你們的憤怒，控制不了你們的恐懼。', `MaleText_loc7`='<tos> Son insolentes, impacientes e inmaduros. Ni siquiera pueden... controlarse a ustedes mismos, su propio miedo... su propia ira.' WHERE `ID`=70187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 따위가 어떻게... <기침> ... 종을 통제하겠느냐?', `MaleText_loc4`='你们还想要……<咳嗽>……控制圣钟？', `MaleText_loc5`='竟然還妄想...<咳嗽>...要操控聖鐘?', `MaleText_loc7`='¿Cómo pretenden... <tos> controlar la campana?' WHERE `ID`=70188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아아아!', `MaleText_loc4`='嘎啊啊啊！', `MaleText_loc5`='喔啊啊啊!', `MaleText_loc7`='¡Graaagh!' WHERE `ID`=70189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 네놈이 선택한 결과다, 모구. 이제, 죽어라...', `MaleText_loc4`='很好。这是你自己的选择，魔古。现在，去死吧……', `MaleText_loc5`='好，這是你自找的，魔古。給我去死吧...', `MaleText_loc7`='De acuerdo. Tú lo has querido, mogu. Ahora, muere...' WHERE `ID`=70190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님! 손을 멈추십시오!', `MaleText_loc4`='加尔鲁什！斧下留人！', `MaleText_loc5`='卡爾洛斯!且慢!', `MaleText_loc7`='¡Garrosh! ¡Detente!' WHERE `ID`=70191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프! 감히 이런 무엄한 짓을!', `MaleText_loc4`='精灵！你想要忤逆我吗？！', `MaleText_loc5`='混帳精靈!你要作亂嗎?!', `MaleText_loc7`='¡Elfo! ¡¿Qué traición es esta?!' WHERE `ID`=70192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 대족장님은 그 종을 찾을 유일한 희망을 짓밟아 버리려는 겁니다! 제 동족은 이런 결과를 위해 모구지아에서 죽어나간 게 아닙니다!', `MaleText_loc4`='我不能眼睁睁看着你毁掉我们寻找圣钟的唯一线索，这可是我的族人在魔古岬拼死战斗才换来的。', `MaleText_loc5`='我在魔古岬眼睜睜看著同胞喪命，可不是為了讓你奪走我們取得聖鐘的僅存機會。', `MaleText_loc7`='Mi gente no murió en Mogujia para que tú ahora destruyas nuestra única oportunidad de conseguir la campana.' WHERE `ID`=70193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 좋다. 놈을 데려가라, 블러드 엘프.', `MaleText_loc4`='……很好。他是你的了，血精灵。', `MaleText_loc5`='...好，他是你的了，血精靈。', `MaleText_loc7`='... Muy bien. Todo tuyo, elfo de sangre.' WHERE `ID`=70194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 입을 열든 말든, 난 이 대륙을 가루로 만들어서라도 내가 원하는 걸 찾아내고 말 것이다... 그것이 호드를 영광으로 이끄는 길이라면.', `MaleText_loc4`='无论他是否开口，即使把这块大陆撕成碎片我也会找到我想要的东西……只要那东西能给部落带来荣耀。', `MaleText_loc5`='不管他肯不肯開口，為了部落的榮耀，為了拿到我要找的東西，就算要把這塊大陸撕成碎片我也在所不惜。', `MaleText_loc7`='Tanto si habla como si no, haré pedazos este continente para encontrar lo que busco... si eso aporta gloria a la Horda.' WHERE `ID`=70195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 엘프...', `MaleText_loc4`='但是，精灵……', `MaleText_loc5`='但是給我聽清楚了，精靈...', `MaleText_loc7`='Una cosa más, elfo...' WHERE `ID`=70196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번만 더 내게 이런 무례한 태도를 보이면, 네놈의 머리를 창에 꽂아서 오그리마 문 밖에 전시할 테다.', `MaleText_loc4`='如果你再敢对我不敬，我会把你的脑袋砍下来，插在奥格瑞玛的城门外。', `MaleText_loc5`='敢再對我不敬，我就會把你的人頭釘在奧格瑪的城門外面。', `MaleText_loc7`='Vuelve a faltarme al respeto y clavaré tu cabeza en una estaca frente a las puertas de Orgrimmar.' WHERE `ID`=70197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심문이 잘 되길 빈다.', `MaleText_loc4`='希望你的审问能有个好结果。', `MaleText_loc5`='祝你拷問順利。', `MaleText_loc7`='Buena suerte con el interrogatorio.' WHERE `ID`=70198;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='쉬이잇! 당신 때문에 제 정체가 들통나게 생겼다고요!', `FemaleText_loc4`='嘘！你会让我的伪装暴露的！', `FemaleText_loc5`='小聲點!別人會聽見的!', `FemaleText_loc7`='¡Shhhh! ¡Vas a hacer que me descubran!' WHERE `ID`=70199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 코넬리 님을 추적하는 요원입니까?', `MaleText_loc4`='你就是那个跟着康奈利的探子？', `MaleText_loc5`='你就是跟蹤康奈利的情報員嗎?', `MaleText_loc7`='¿Eres la agente que sigue a Connelly?', `FemaleText_loc1`='당신이 코넬리 님을 추적하는 요원인가요?', `FemaleText_loc4`='你就是那个跟着康奈利的探子？', `FemaleText_loc5`='你就是跟蹤康奈利的情報員嗎?', `FemaleText_loc7`='¿Eres la agente que sigue a Connelly?' WHERE `ID`=70200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 모구는 천상의 종을 찾을 유일한 단서입니다. 저희가 반드시 입을 열게 만들겠습니다. 시간을 좀 주십시오.', `MaleText_loc4`='他是我们找到圣钟的唯一线索。我们会让他说实话的。只需要给我们一些时间。', `MaleText_loc5`='他是我們找到聖鐘的唯一管道。我們「一定」會問出來的，多給我們一點時間。', `MaleText_loc7`='Es la única forma de encontrar la campana. Nosotros le haremos hablar. Danos tiempo.' WHERE `ID`=70201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='휴... 흥미진진했소. 바깥에 계신 로르테마르 님을 뵈러 갑시다.', `MaleText_loc4`='好吧……真有趣。我们去外面见洛瑟玛吧。', `MaleText_loc5`='嗯...倒是挺有趣的。我們到外頭見洛索瑪吧。', `MaleText_loc7`='Bueno, ha sido interesante... Vamos a reunirnos con Lor''themar fuera.' WHERE `ID`=70202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 충동적이요. 우린 결과를 얻어낼 것이오. 그도 우리 방식이 옳다는 걸 알게 되겠지.', `MaleText_loc4`='他很冲动，但我们会取得好结果的。他最终也会认同我们。', `MaleText_loc5`='他是個衝動的人，可是我們會拿出成果。他會明白我們才是對的。', `MaleText_loc7`='Es impulsivo, pero obtendremos resultados. Verá que tenemos razón.' WHERE `ID`=70203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='디버그 오류: 스펠 실패. 버그 올리세요!', `MaleText_loc4`='纠错信息：法术失败。快报BUG！', `MaleText_loc5`='偵測錯誤: 超出範圍。記錄錯誤。', `MaleText_loc7`='Debug Error: Spell Failed. Bug This!' WHERE `ID`=70204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 모두 들어라. 포로를 영원꽃 골짜기로 호송할 채비를 해라. 헬스크림이 좀 진정되면 그에게 포로를 넘겨줄 것이다.', `MaleText_loc4`='好了，所有人听好。准备把这名囚犯带回锦绣谷。当地狱咆哮冷静下来之后，我们再将他移送过去。', `MaleText_loc5`='好，大家注意。準備把這個囚犯押回恆春谷。等地獄吼冷靜下來，我們再把囚犯交給他。', `MaleText_loc7`='Muy bien, escúchenme. Prepárense para trasladar al prisionero al valle. Se lo entregaremos a Grito Infernal cuando haya tenido tiempo de calmarse.' WHERE `ID`=70205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 좀 지나 헬스크림이 좀 진정되면 그에게 포로를 넘겨줄 거요. 우리 전리품을 그가 부숴 버리게 둘 수는 없잖소?', `MaleText_loc4`='当地狱咆哮冷静下来之后，我们再将他移送过去。我们不能让他毁掉我们的奖品，对吧？', `MaleText_loc5`='等他花點時間冷靜下來以後，我們會把他交給地獄吼。我們可不能讓他毀了我們的寶物，對吧?', `MaleText_loc7`='Se lo entregaremos a Grito Infernal cuando haya tenido tiempo de calmarse. No queremos que rompa nuestro premio, ¿verdad?' WHERE `ID`=70206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 정말 잘해줬소. 그대의 도움이 없었다면, 이 작전은 몹시 지저분하게 끝났을 거요.', `MaleText_loc4`='$p——干得好。要是没有你的帮助，我们怕是没办法收场。', `MaleText_loc5`='$p - 做得好。若不是有你的協助，這件事恐怕會收場得很難看。', `MaleText_loc7`='Buen trabajo, $p. Sin tu ayuda, todo este asunto habría tenido un final muy amargo.' WHERE `ID`=70207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 도전자가 나일 줄은 몰랐지? 원숭이 왕은 결투를 남한테 맡기지 않아! 자, 너는 영웅이야? 아니면 우낏이야?', `MaleText_loc4`='哈！没想到会在这里碰到我，对吧？美猴王从不错过决斗！现在，你是要当英雄呢，还是当个笨蛋无毛怪？', `MaleText_loc5`='哈!沒想到會在這裡碰到我吧?美猴王打架一向親自上場!你是個英雄，還是個怪怪人呢?', `MaleText_loc7`='¡Ja! ¿A ke tú no espera verme akí? ¡El Rey Mono no delega los duelos! ¿Y bien? ¿Tú es $ghéroe:heroína; o makaku?' WHERE `ID`=70208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 어디 실력 좀 볼까!', `MaleText_loc4`='明白了！让我瞧瞧你的本事。', `MaleText_loc5`='好，來看看你有什麼。', `MaleText_loc7`='¡Chachi! A ver ké tú sabe hacer.' WHERE `ID`=70210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치를 만드려면 세 가지가 필요해. 손잡이, 망치 머리, 그리고 연고가 있어야지. 망치 없이 종을 울린다고? 얼굴이랑 귀가 아주 얼얼할 거야!', `MaleText_loc4`='钟杵由三部分组成：杵柄，杵头和药膏。没有杵你想怎么敲这口钟？现在认真听我说话，然后准备好对付那些邪恶的坏蛋吧。', `MaleText_loc5`='聖槌已經裂為三，握把鎚頭和油膏。若是敲鐘無聖槌，妖音邪力滿面襲。', `MaleText_loc7`='La marra está dividida en tres partes: cabeza, mango y ungüento. Si tañes la kampana sin la marra, te estallará toda la maldad en la kara.' WHERE `ID`=70211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 멍청한 우낏은 엄청 센 호젠 지팡이 못 가져가!', `MaleText_loc4`='不！笨蛋无毛怪不能拿走猢狲的宝贝棍子！', `MaleText_loc5`='不!笨笨怪怪人不能拿走猴子的大棒棒!', `MaleText_loc7`='¡No! ¡Makaku $gtonto:tonta; no se lleva gran vara de los hozen!' WHERE `ID`=70212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 안 돼! 파티 그만 해! 여긴 아직 잉구 잉구 마을이야!', `MaleText_loc4`='不！不不！不开聚会了！这是盎迦盎迦的村子！', `MaleText_loc5`='不!不不不!不准派對了!這裡還是印古的村子!', `MaleText_loc7`='¡No! ¡No, no, no! ¡No más fiesta! ¡Esta sigue siendo aldea de Ingoo Ingoo!' WHERE `ID`=70213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 파티 그만 해! 이건 진짜 원숭이 왕 아니다! 원숭이 왕은 아주 오오오오오오오래에에에에 전에 죽었다!', `MaleText_loc4`='停！别闹了！这不是真的美猴王！美猴王很多很多很多很多很多年前就死了！', `MaleText_loc5`='停!停停停!這不是真的美猴王!美猴王很久很久很久很久以前就死了!', `MaleText_loc7`='¡Para! ¡Ustedes paren la fiesta! ¡No es el Rey Mono de verdad! ¡El Rey Mono murió hace mucho mucho mucho mucho mucho tiempo!' WHERE `ID`=70214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 노래하지 마!', `MaleText_loc4`='不！别唱了！', `MaleText_loc5`='不行!不要再唱了!', `MaleText_loc7`='¡No! ¡Ustedes no kanten!' WHERE `ID`=70215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이 왕은 없어! 족장 잉구 잉구가 왕이야! 족장 말 들어!', `MaleText_loc4`='美猴王说话不算！盎迦盎迦酋长说了算！听酋长的话！', `MaleText_loc5`='美猴王不是老大!印古才是老大!要聽印古的!', `MaleText_loc7`='¡El Rey Mono no manda! ¡Jefe Ingoo Ingoo manda! ¡Ustedes eskuchen al jefe!' WHERE `ID`=70216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맥주 그만 마셔! 지난 번 우끼 선장 때문에 생긴 일 잊었어? 그런 일 또 생기고 싶어?', `MaleText_loc4`='别喝酒了！记得乌克头领的下场吗？想要和他一样吗？', `MaleText_loc5`='不要再喝了!還記得烏克船長上次的事情嗎?還要再發生一次嗎?', `MaleText_loc7`='¡No más cerveza! ¿Ustedes rekuerdan lo ke pasó kon el kapitán Ook? ¡Kieren que pasa otra vez!' WHERE `ID`=70217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 노는 거 그만 해! 그만! 그만 하라고! 그만!', `MaleText_loc4`='不！停下来！停！停！停！', `MaleText_loc5`='不!快點住手!住手!', `MaleText_loc7`='¡No! ¡Ustedes paren de jugar! ¡Paren! ¡Paren! ¡Paren!' WHERE `ID`=70218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 왕 아니야! 족장 잉구 잉구 너 안 뽑았다!', `MaleText_loc4`='你不是猴王！盎迦盎迦酋长不会承认你！', `MaleText_loc5`='你不是猴人王!印古沒有投給你!', `MaleText_loc7`='¡Tú no es rey! ¡Jefe Ingoo Ingoo no votó por ti!' WHERE `ID`=70219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이 왕은 되게 큰 우낏이야!', `MaleText_loc4`='美猴王是个大坏蛋无毛怪！', `MaleText_loc5`='美猴王是大大大的怪怪人!', `MaleText_loc7`='¡El Rey Mono es un makaku de kampeonato!' WHERE `ID`=70220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반짝이는 내 거야!', `MaleText_loc4`='看我的金闪闪！', `MaleText_loc5`='我的亮晶晶!', `MaleText_loc7`='¡Mi brillante!' WHERE `ID`=70221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 음식을 준비해 주는 이에게는 미움을 받지 않는 게 좋다는 말이 있죠. 그런데, 이 손님은 미워하지 않는 이가 있는지도 잘 모르겠어요...', `FemaleText_loc4`='最好不要把坏的一面暴露给那些帮你准备食物的人。但这位老主顾似乎完全没有好的一面……', `FemaleText_loc5`='最好別惹幫你準備食物的人。不過，這位顧客似乎不是那麼好相處...', `FemaleText_loc7`='No es buena idea llevarse mal con la gente que te prepara la comida, pero no creo que este cliente se lleve bien con nadie...' WHERE `ID`=70222;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='눈은 영혼의 창이라고들 하죠. 그 말이 사실이라면, 이 손님의 영혼에는 뭔가 감출 게 있는 것 같아요.', `FemaleText_loc4`='都说眼睛是灵魂的窗口。如果这是真的，那我猜这位客人还有他的灵魂都藏起来了。', `FemaleText_loc5`='人們說眼睛是靈魂之窗。如果事實真是如此，我懷疑這位客人的靈魂有不可告人之處。', `FemaleText_loc7`='Dicen que los ojos son el espejo del alma. Si es verdad, creo que este invitado y su alma ocultan algo.' WHERE `ID`=70223;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 손님은 끝나버린 사랑을 기리기 위한 기념품을 몸에 걸치고 있어요. 사람들의 말이 맞나 봐요. 모든 사랑 이야기에는 가시가 돋아 있죠. 모든 밤의 뒤에는 새벽이 따라오는 것처럼요.', `FemaleText_loc4`='这位客人穿戴有爱人的遗物。看来人们说的没错：每一段爱情都有荆棘，正如每个夜晚都会迎来黎明。', `FemaleText_loc5`='這位客人將前段戀情的紀念品戴在身上。我相信這段話:每段感情都會傷人，就如每個黑夜都有黎明。', `FemaleText_loc7`='Este invitado lleva consigo el recuerdo de un amor perdido. Debe de ser verdad lo que dicen: toda historia de amor tiene sus espinas, igual que toda noche tiene su amanecer.' WHERE `ID`=70224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='첫 번째 단서를 알려주십시오.', `MaleText_loc4`='我准备好听第一条线索了。', `MaleText_loc5`='我準備好聽第一條線索。', `MaleText_loc7`='Estoy listo para escuchar la primera pista.', `FemaleText_loc1`='첫 번째 단서를 알려주세요.', `FemaleText_loc4`='我准备好听第一条线索了。', `FemaleText_loc5`='我準備好聽第一條線索。', `FemaleText_loc7`='Estoy lista para escuchar la primera pista.' WHERE `ID`=70225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐습니다. 다음 단서를 알려주십시오!', `MaleText_loc4`='好吧，再告诉我一条线索！', `MaleText_loc5`='好吧，告訴我下一條線索', `MaleText_loc7`='Venga, ¡dame otra pista!', `FemaleText_loc1`='됐어요. 다음 단서를 알려주세요!', `FemaleText_loc4`='好吧，再告诉我一条线索！', `FemaleText_loc5`='好吧，告訴我下一條線索', `FemaleText_loc7`='Venga, ¡dame otra pista!' WHERE `ID`=70226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉽군요! 다음 단서를 추적할 준비가 됐습니다.', `MaleText_loc4`='这很简单！我准备好听下一条线索了。', `MaleText_loc5`='這太簡單了!我準備好迎接新線索了。', `MaleText_loc7`='¡Qué fácil! Dame la siguiente pista.', `FemaleText_loc1`='쉽네요! 다음 단서를 추적할 준비가 됐어요.', `FemaleText_loc4`='这很简单！我准备好听下一条线索了。', `FemaleText_loc5`='這太簡單了!我準備好迎接新線索了。', `FemaleText_loc7`='¡Qué fácil! Dame la siguiente pista.' WHERE `ID`=70227;
