UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람들이 목숨을 걸고 싸우는 모습을 지켜보고 있노라면, 왠지 모르게 마음이 따뜻해져요!', `FemaleText_loc4`='有时候看着其他人以命相搏真是令我感动！', `FemaleText_loc5`='看人毆鬥至死讓我熱血沸騰!', `FemaleText_loc7`='Ver a gente luchar a muerte tiene algo que me alegra el corazón.' WHERE `ID`=70253;
