UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마실 것은 뭘로 드릴까요?', `FemaleText_loc4`='我能要点喝的吗？', `FemaleText_loc5`='要喝點什麼嗎?', `FemaleText_loc7`='¿Quieres algo de beber?' WHERE `ID`=70255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 내게 얼라이언스의 최전선에 다시 뛰어들라는 말이군... 어디라고? 판다리아...? 응?', `MaleText_loc4`='所以说你想让我去这个什么……熊猫……利亚……的联盟前线？', `MaleText_loc5`='所以，你希望我加入潘達利亞的...聯盟前線...嗎?', `MaleText_loc7`='Así que quieres que vaya al frente de la Alianza en... ¿cómo se llama? ¿Pandaria?' WHERE `ID`=70256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='털북숭이 우낏이 망치 머리 훔쳐갔다! 쿤젠 호젠은 그걸 옛날옛날에 잃어버렸어. 이젠 털북숭이 우낏이 망치 머리를 소굴 안에 숨겨 놓고 뭔가 대단한 주술이 깃든 당근 같이 숭배하고 있다.$b$b조심해. 그 털북숭이 우낏 깨물면 진짜 아프다.', `MaleText_loc4`='长毛的蠢蛋偷走了杵头！昆森猢狲在很多年之前遗失了杵头。现在那些长毛的蠢蛋把杵头藏在他们的巢穴里，把它当作某种宝贝胡萝卜供奉了起来。$b$b小心点，那些长毛蠢蛋咬人可疼了。', `MaleText_loc5`='毛茸茸的怪怪人把槌頭偷走了!許多年前崑真猴人的槌頭被偷了。現在毛茸茸的怪怪人躲在巢穴裡，把槌頭當成漂漂的胡蘿蔔在拜。$b$b小心，那些毛茸茸的怪怪人咬起來很痛。', `MaleText_loc7`='¡Makakus pelakos robaron la cabeza de la marra! Hozen Kunzen perdieron hace muchos años. Ahora los makakus pelakos la okultan en su guarida y la adoran komo si fuera una zanahoria gigante.$b$bTú tiene kuidado, makakus pelakos muerden mucho.' WHERE `ID`=70257;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토엔 그 힘을 악용했던 역사가 있어요. 켈투자드는 비전 마법 지식으로 강령술을 연구했죠.', `FemaleText_loc4`='肯瑞托向来不乏滥用力量之徒。克尔苏加德把魔法知识用在了死灵法术上。', `FemaleText_loc5`='祈倫托素有濫用魔法的惡習。科爾蘇加德利用他的魔法知識去鑽研邪惡的死靈法術。', `FemaleText_loc7`='El Kirin Tor tiene un historial de abuso. Kel''thuzad utilizó su conocimiento de lo arcano para la nigromancia.' WHERE `ID`=70258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보이는 게 다가 아니오. 게다가 안두인 말로는 이곳은 신성한 곳이라 하오.', `MaleText_loc4`='事情不能只看表面，泰兰德。而且我儿子说这是个圣地。', `MaleText_loc5`='通常事情沒有表面那麼簡單，泰蘭妲。我的兒子跟我說過這是一個神聖的場所。', `MaleText_loc7`='Las cosas no son siempre lo que parecen, Tyrande. Y mi hijo dice que este es un lugar sagrado.' WHERE `ID`=70261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 한곳에 틀어박혀 방어를 한다면 승산이 없소. 끌어내야 하오.', `MaleText_loc4`='对方早有准备。不能被他们牵着走，得把他们引出来。', `MaleText_loc5`='他們守在以逸待勞之處。我才不會上他們的當。我們要引他們出來。', `MaleText_loc7`='Defienden un punto fijo. No pienso caer en su juego. Los haremos salir.' WHERE `ID`=70262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 셋이 내 눈이고 귀다. 흩어져서 방어를 준비해라!', `MaleText_loc4`='你们三个就是我的耳目。散开！准备防御！', `MaleText_loc5`='你們三個就是我的耳目。散開!準備好防禦據點。', `MaleText_loc7`='Ustedes tres son mis ojos y oídos. ¡Despliéguense! ¡Preparen las defensas!' WHERE `ID`=70263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라! 들어가선 안 된다.', `MaleText_loc4`='后退！不要孤军深入。', `MaleText_loc5`='退後!別中了誘敵之計。', `MaleText_loc7`='¡Atrás! No caigan en su trampa.' WHERE `ID`=70264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문에 접근하지 마라. 놈들이 노리는 바다.', `MaleText_loc4`='别靠近大门，那正中他们的下怀。', `MaleText_loc5`='離寺廟大門遠一點，否則你會陷入他們的詭計裡。', `MaleText_loc7`='Aléjense de las puertas del templo, están jugando con nosotros.' WHERE `ID`=70265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어를 준비해라. 언젠가 나올 수밖에 없을 것이다.', `MaleText_loc4`='建好防御工事。他们迟早会出来的。', `MaleText_loc5`='準備好防禦據點。他們遲早要出來。', `MaleText_loc7`='Preparen nuestras defensas. En algún momento tendrán que salir.' WHERE `ID`=70266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위치를 지켜라! 끝까지 기다려라.', `MaleText_loc4`='坚守阵地！等他们出来。', `MaleText_loc5`='堅守崗位!等他們出來。', `MaleText_loc7`='¡Mantengan sus posiciones! Los esperaremos.' WHERE `ID`=70267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어를 준비해라.', `MaleText_loc4`='把工事准备好。', `MaleText_loc5`='準備好防禦據點。', `MaleText_loc7`='Tengan listas las defensas.' WHERE `ID`=70268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지형을 잘 활용해라.', `MaleText_loc4`='要利用有利地形。', `MaleText_loc5`='利用地形成為我們的優勢。', `MaleText_loc7`='Utilicemos el terreno a nuestro favor.' WHERE `ID`=70269;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 허점을 노릴 것이니, 서로 지원해야 한다.', `MaleText_loc4`='我们得互相支援。任何弱点都会成为目标。', `MaleText_loc5`='我們必須互相照應。他們將會專攻我們的弱點。', `MaleText_loc7`='Tenemos que cuidarnos las espaldas. Buscarán cualquier debilidad.' WHERE `ID`=70270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비가 거의 끝났다. 계속해라!', `MaleText_loc4`='就要完成了。再接再厉！', `MaleText_loc5`='差不多準備好了。繼續努力!', `MaleText_loc7`='Ya casi estamos listos. ¡Sigan trabajando!' WHERE `ID`=70271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 병목으로 몰아넣어라. 승리의 환상을 심어줘라...', `MaleText_loc4`='将他们逼入瓶颈。让他们自以为能赢……', `MaleText_loc5`='迫使他們卡在瓶頸處。讓他們以為還有贏的機會...', `MaleText_loc7`='Llévenlos a los cuellos de botella. Que crean que pueden ganar…' WHERE `ID`=70272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성급하게 뛰어들지 마라. 놈들이 실수하게 만들어라.', `MaleText_loc4`='不要进攻。让他们犯错误。', `MaleText_loc5`='別冒進，等他們先失手犯錯。', `MaleText_loc7`='No carguen. Dejen que cometan el primer error.' WHERE `ID`=70273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 우리 땅이다. 한 치도 내주지 마라.', `MaleText_loc4`='这里是我们的。他们每进一步都得付出代价。', `MaleText_loc5`='這塊領地是我們的。讓他們為每一吋都付出代價。', `MaleText_loc7`='Este terreno es nuestro. Háganlos pagar cada centímetro.' WHERE `ID`=70274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해라! 우리 방식대로 이겨야 한다.', `MaleText_loc4`='再接再厉！我们会赢的。', `MaleText_loc5`='繼續加油!我們會用我們的方式贏得勝利。', `MaleText_loc7`='¡Sigan trabajando! Ganaremos a nuestra manera.' WHERE `ID`=70275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가능한 한 모든 걸 활용해라! 적을 궁지에 몰아!', `MaleText_loc4`='利用每一点资源！让他们无路可逃！', `MaleText_loc5`='把所有能用的都用上!讓他們無處可逃!', `MaleText_loc7`='¡Aprovechen cada recurso! ¡No permitan que escapen!' WHERE `ID`=70276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으시오, 티란데.', `MaleText_loc4`='耐心点，泰兰德。', `MaleText_loc5`='有點耐心，泰蘭妲。', `MaleText_loc7`='Paciencia, Tyrande.' WHERE `ID`=70277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참으시오, 티란데. 우리가 이기겠지만, 무방비하게 들어가선 안 되오.', `MaleText_loc4`='耐心点，泰兰德。我们必将取胜，但得做好准备。', `MaleText_loc5`='有點耐心，泰蘭妲。我們會勝利的，但不會在做好準備前就冒進。', `MaleText_loc7`='Paciencia, Tyrande. La victoria será nuestra, pero tenemos que prepararnos antes de entrar.' WHERE `ID`=70278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 생명을 내버릴 순 없소. 압승이 아니면 취하지 않을 거요.', `MaleText_loc4`='我不会让联盟白白流血。我只想要一场彻底的胜利。', `MaleText_loc5`='我不會隨便犧牲聯盟人民的性命，用鮮血換來的必定要全面勝利。', `MaleText_loc7`='No sacrificaré vidas de la Alianza. No aceptaré nada que no sea una victoria absoluta.' WHERE `ID`=70279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘됐군. 그럴수록 빨리 무너질 테니.', `MaleText_loc4`='很好。这说明他们就要突围了。', `MaleText_loc5`='很好。這就代表他們就要沉不住氣了。', `MaleText_loc7`='Bien. Eso significa que se están impacientando.' WHERE `ID`=70280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아. 계획이 착착 진행되고 있군.', `MaleText_loc4`='很好。计划奏效了。', `MaleText_loc5`='很好。一切按照計畫進行。', `MaleText_loc7`='Bien. El plan empieza a tomar forma.' WHERE `ID`=70281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드워프 작품답게 튼튼하군. 꽤 아프겠어.', `MaleText_loc4`='非常结实的矮人建筑。它一定能大发神威。', `MaleText_loc5`='非常堅固的矮人工事，能對敵人造成不小傷害。', `MaleText_loc7`='Robusta y maciza construcción enana. Esto debería causar algún daño.' WHERE `ID`=70282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위는 준비됐군. 나머지는 어떻게 되고 있지?', `MaleText_loc4`='看来锦鱼人盟友准备好了。剩下的事怎么样？', `MaleText_loc5`='我們錦魚人的盟軍已經準備好了。剩下的準備工作如何?', `MaleText_loc7`='Veo que nuestros aliados jinyu están listos. ¿Cómo va el resto de los preparativos?' WHERE `ID`=70283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 노움이야! 호드는 뭐에 당했는지도 모르겠지.', `MaleText_loc4`='啊，侏儒科技！肯定能让部落死得不明不白。', `MaleText_loc5`='啊啊，地精的奇謀妙計!部落肯定會措手不及。', `MaleText_loc7`='¡Ah, el ingenio gnómico! La Horda no sabrá de dónde vienen los golpes.' WHERE `ID`=70284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 판다렌 민족의 능력이 기대되는군.', `MaleText_loc4`='了不起！让我们看看这些熊猫人农夫的本事吧。', `MaleText_loc5`='幹得好!讓我們來看看這些熊貓開墾農有什麼本事?', `MaleText_loc7`='¡Un trabajo excelente! A ver de qué son capaces estos pandaren nativos.' WHERE `ID`=70285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다. 방어선 뒤로 물러나라!', `MaleText_loc4`='他们过来了。到工事后面去！', `MaleText_loc5`='他們來了。躲在防禦工事後面!', `MaleText_loc7`='Ya vienen. ¡Colóquense detrás de las defensas!' WHERE `ID`=70286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와라, 겁쟁이! 보여줄 테니!', `MaleText_loc4`='自己出来数数啊，懦夫！', `MaleText_loc5`='過來數一數啊，懦夫!', `MaleText_loc7`='¡Ven a contarlos, cobarde!' WHERE `ID`=70287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 군대는 여기 없다. 영웅 몇 명만 쓰러뜨리면 스톰윈드 왕을 노릴 수 있다. 두려운가?', `MaleText_loc4`='这里可没有什么大军，只有暴风城国王和几名英雄而已。难道你怕了吗？', `MaleText_loc5`='這裡又沒有軍隊。只有一些英雄擋在你跟暴風城國王中間。你怕了嗎?', `MaleText_loc7`='Aquí no hay ningún ejército. Solo hay un puñado de héroes entre ustedes y el Rey de Ventormenta. ¿Tienen miedo?' WHERE `ID`=70288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 그렇지. 뒤로 물러나 놈들을 맞아라!', `MaleText_loc4`='如我所料。退回防线——让他们过来！', `MaleText_loc5`='果然不出所料。退到防禦線後方 - 讓他們來吧!', `MaleText_loc7`='Predecible. Retírense detrás de nuestras líneas. ¡Que avancen ellos!' WHERE `ID`=70289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리의 대가는 컸지만, 최악의 상황은 피했다. 상을 받아 다오.', `MaleText_loc4`='这是一场惨胜，但原本可能更惨。你赢得了这份奖励。', `MaleText_loc5`='勝利的代價很高，但至少沒有變得更慘烈。你贏得了這份獎勵。', `MaleText_loc7`='Fue una victoria muy costosa, pero pudo ser mucho peor. Se han ganado esta recompensa.' WHERE `ID`=70290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사자는 애도해야겠지만, 그대가 아니었다면 더 많은 목숨을 잃었을 것이다. 감사의 표시를 받아 다오.', `MaleText_loc4`='逝者已矣，但要不是你，牺牲者可能更多。为表谢意，请接受这份礼物。', `MaleText_loc5`='我們哀悼陣亡的烈士，但要不是你的努力，更多人會犧牲。請收下這份聯盟的心意。', `MaleText_loc7`='Aunque lloramos a los caídos, se habrían perdido más vidas de no ser por su esfuerzo. Acepten esta muestra de gratitud de la Alianza.' WHERE `ID`=70291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 많은 사상자 없이 방어선을 지켜냈군. 그 노고를 인정해 상을 내리니 받아 다오.', `MaleText_loc4`='干得好！我们将伤亡降到了最低。为了表彰你的贡献，请接受这份奖励。', `MaleText_loc5`='做得很好!我們的人馬只受到輕微的損傷。請收下你傑出表現應得的獎勵。', `MaleText_loc7`='¡Excelente trabajo! Nuestras defensas sufrieron pocas bajas. Acepten esta recompensa por su excepcional esfuerzo.' WHERE `ID`=70292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='압승이다! 그대의 기지와 실력 덕분에 아무도 목숨을 잃지 않았다. 내 심심한 감사의 뜻과 함께 이 상을 받아 다오.', `MaleText_loc4`='完胜！多亏了你的机智和高效，我方无一伤亡。接受这份奖励，以及我诚挚的谢意。', `MaleText_loc5`='這是一場全面勝利!多虧了你的策略跟才能，我們才無人傷亡。請接受這份獎勵跟我誠摯的感激。', `MaleText_loc7`='¡Victoria total! Gracias a su habilidad y eficacia, no perdimos a nadie. Acepten esta recompensa y mi gratitud.' WHERE `ID`=70293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리했다! 게다가 신성한 땅에 피를 흘리지도 않았다.', `MaleText_loc4`='我们胜利了！而且没让这片圣地溅上一滴鲜血。', `MaleText_loc5`='我們的勝利之日!而且沒有流下一滴血到這片神聖之地。', `MaleText_loc7`='¡La victoria es nuestra! Y no se derramó ni una gota de sangre en suelo sagrado.' WHERE `ID`=70294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전의 나라면 그랬을 거요. 하지만 그 동안 많은 걸 배웠지. 가로쉬에게 한두 번 당한 게 아니니.', `MaleText_loc4`='我曾经也和你一样。但这么多年来我学会了许多，我也已经尝够了加尔鲁什的诡计。', `MaleText_loc5`='以前的我也會這麼做，但這麼多年來我終於學乖了。我已經中過太多次卡爾洛斯的詭計了。', `MaleText_loc7`='Hubo un tiempo en el que yo habría hecho lo mismo. Pero he aprendido mucho con los años. He caído en demasiadas trampas de Garrosh.' WHERE `ID`=70295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금부터는 우리가 이 전쟁을 주도하오.', `MaleText_loc4`='从今天起，我们赋予了战争新的含义。', `MaleText_loc5`='從今天起，戰況將由我們來主導。', `MaleText_loc7`='A partir de ahora, jugaremos según nuestras reglas.' WHERE `ID`=70296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티란데, 나는 정치는 못할지 몰라도 싸움은 잘하오. 우린 이 전쟁에서 이길 수 있소.', `MaleText_loc4`='泰兰德，我并非政客，我是个战士。我知道我们能赢。', `MaleText_loc5`='泰蘭妲，可能我不是個政治家。但是我是個戰士。我知道我們能在這場戰爭中獲勝。', `MaleText_loc7`='Tyrande, no seré un político, pero sí soy un luchador. Sé que podemos ganar esta guerra.' WHERE `ID`=70297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단결해야 하오. 나를 믿어 주시오. 내가 옳은 선택을 할 거라고 말이오. 우리가 하나가 되면 절대 실패하지 않소.', `MaleText_loc4`='我们必须团结一致。你要相信我，并且认同我。只要我们齐心协力，就一定会赢。', `MaleText_loc5`='我們必須要團結努力。你得相信我，相信我一定會做出正確的決定。只要同心協力，我們絕不可能落敗。', `MaleText_loc7`='Solo tenemos que permanecer juntos. Debes confiar en mí. Saber que haré lo correcto. Si actuamos unidos, no podemos fracasar.' WHERE `ID`=70298;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들을 사원 안으로 몰았어요. 지금 공격해야 합니다!', `FemaleText_loc4`='我们把他们堵在了寺院里。应该立刻进攻！', `FemaleText_loc5`='我們已經把他們困在寺廟裡了。我們應該現在出擊!', `FemaleText_loc7`='Los tenemos acorralados dentro del templo. ¡Debemos atacar ya!' WHERE `ID`=70299;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더더욱 정화시켜야겠군요.', `FemaleText_loc4`='那就更该净化它了。', `FemaleText_loc5`='那我們更有理由除掉他們!', `FemaleText_loc7`='Razón de más para purificarlo.' WHERE `ID`=70300;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낭비할 시간이 없어요.', `FemaleText_loc4`='你在浪费宝贵的时间。', `FemaleText_loc5`='你在浪費寶貴的時間。', `FemaleText_loc7`='Estás desperdiciando tiempo valioso.' WHERE `ID`=70301;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 시간 낭비예요. 들어가서 놈들을 처치합시다!', `FemaleText_loc4`='这是浪费时间，应该冲进去厮杀！', `FemaleText_loc5`='我們在浪費時間。我們應該前進殺敵!', `FemaleText_loc7`='Estamos perdiendo el tiempo. ¡Deberíamos entrar a matar!' WHERE `ID`=70302;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우유부단하시군요. 얼라이언스를 이끌고자 한다면 결단력을 보여주세요.', `FemaleText_loc4`='你太犹豫了，瓦里安。如果你想领导联盟，就得果断点。', `FemaleText_loc5`='瓦里安，你太猜疑多慮了。如果想帶領聯盟就必須要當機立斷。', `FemaleText_loc7`='Se te nota indeciso, Varian. Debes ser firme si quieres liderar a la Alianza.' WHERE `ID`=70303;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 정면 공격하면 안 된다는 거죠?', `FemaleText_loc4`='我们为什么不直接进攻？', `FemaleText_loc5`='哎...我們為什麼不一擁而上?', `FemaleText_loc7`='¿Por qué no los atacamos de una vez?' WHERE `ID`=70304;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금 우릴 조롱하고 있다고요.', `FemaleText_loc4`='他们在寺院里嘲弄我们。', `FemaleText_loc5`='他們在寺廟裡嘲笑我們。', `FemaleText_loc7`='Se burlan de nosotros desde el templo.' WHERE `ID`=70305;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어 시설이 구축되었습니다.', `FemaleText_loc4`='我们的工事完成了。', `FemaleText_loc5`='防禦工事已經準備就緒。', `FemaleText_loc7`='Nuestras fortificaciones están listas.' WHERE `ID`=70306;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저라면 무작정 돌격해 들어갔을 거예요. 아마 수많은 목숨을 잃었겠죠.', `FemaleText_loc4`='换了我会直接进攻，而我那样冒进的话可能会牺牲更多人。', `FemaleText_loc5`='若是按照當初我躁進求勝的方式迎敵，許多人會因而喪失生命。', `FemaleText_loc7`='Yo habría atacado a ciegas. Hubiésemos perdido muchas más vidas en mi ansia de victoria.' WHERE `ID`=70307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 이제 우리 힘을 당신께 맡깁니다, 왕이시여. 이번 승리가 앞으로 이어질 우리 승리의 초석이 되길...', `FemaleText_loc4`='我明白了。请领导我们，陛下。愿它成为一个好的开端。', `FemaleText_loc5`='我現在了解了。我們的軍力由您來發號施令，陛下。願此為打響未來勝利的第一戰。', `FemaleText_loc7`='Ahora lo entiendo. Nuestras fuerzas están a su disposición, Majestad. Que esta sea la primera de muchas victorias.' WHERE `ID`=70308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='참을성의 시험이로다! 늑대가 전사로 처신할 것인가... 왕으로 처신할 것인가?', `MaleText_loc4`='这是一场耐心的试炼。狼群之首究竟是野兽，还是国王？', `MaleText_loc5`='一項考驗!對耐心的試煉。那頭狼的表現會像個魯莽的戰士，還是明智之君呢?', `MaleText_loc7`='¡Una prueba! Un examen de paciencia. ¿Se comportará el lobo como un guerrero... o como un rey?' WHERE `ID`=70309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전사의 무기는 검이나, 왕의 무기는 참을성이다.', `MaleText_loc4`='战士的武器是利剑，而国王的武器则是耐心。', `MaleText_loc5`='劍是戰士殺敵的武器，但國王真正的武器是耐心。', `MaleText_loc7`='La espada es el arma de los guerreros, pero la paciencia es el arma de los reyes.' WHERE `ID`=70310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 승리를 거두었으나, 시험은 계속될 것이다...', `MaleText_loc4`='今日之战已胜，可前方还有更多险阻……', `MaleText_loc5`='今日已勝，但更多艱困的試煉在前方等著...', `MaleText_loc7`='Este día termina en victoria, pero el futuro depara pruebas más arduas…' WHERE `ID`=70311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 개들아! 이빨은 어딨느냐?!', `MaleText_loc4`='联盟狗！你的爪牙呢？', `MaleText_loc5`='聯盟的走狗!牙都被拔光了嗎?', `MaleText_loc7`='¡Perros de la Alianza! ¿Dónde están sus dientes?' WHERE `ID`=70312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전군, 진격하라!', `MaleText_loc4`='让步兵上。进攻！', `MaleText_loc5`='把蠻兵們都帶上來。攻擊!', `MaleText_loc7`='Que vengan los brutos. ¡Ataquen!' WHERE `ID`=70313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님을 위해!', `MaleText_loc4`='为了酋长！', `MaleText_loc5`='為了大酋長!', `MaleText_loc7`='¡Por el Jefe de Guerra!' WHERE `ID`=70314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 솜씨가 이것 뿐인가?', `MaleText_loc4`='你们就是这么打仗的？', `MaleText_loc5`='你都是這樣打仗的嗎?', `MaleText_loc7`='¿Es así como luchan sus batallas?' WHERE `ID`=70315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 얼라이언스는 약해 빠졌어!', `MaleText_loc4`='你们联盟太弱了！', `MaleText_loc5`='你們這些聯盟太弱了!', `MaleText_loc7`='¡Su Alianza es DÉBIL!' WHERE `ID`=70316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 끝이다!', `MaleText_loc4`='我要干掉你！', `MaleText_loc5`='我受夠你了!', `MaleText_loc7`='¡Me tienen harto!' WHERE `ID`=70317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비겁한 겁쟁이들!', `MaleText_loc4`='胆小鬼！', `MaleText_loc5`='懦夫!', `MaleText_loc7`='¡Malditos cobardes!' WHERE `ID`=70318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='형편없군.', `MaleText_loc4`='可怜虫。', `MaleText_loc5`='可悲的傢伙。', `MaleText_loc7`='Patético.' WHERE `ID`=70319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하, 그게 전부냐?', `MaleText_loc4`='你就这点本事？', `MaleText_loc5`='哈!就這麼點能耐嗎?', `MaleText_loc7`='¡Ja! ¿Eso es todo?' WHERE `ID`=70320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠밖에 볼 수 없었는데... 감사합니다.', `MaleText_loc4`='我的眼中……曾经满是黑暗……感谢你。', `MaleText_loc5`='我...只能見到黑暗...謝謝你。', `MaleText_loc7`='Solo... solo veía oscuridad... Gracias.' WHERE `ID`=70321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이... 이 빛은 뭡니까? 당신께 축복을...', `MaleText_loc4`='光……哪里来的亮光？愿天神保佑你……', `MaleText_loc5`='光明...這是什麼光?祝福你...', `MaleText_loc7`='Luz... ¿Qué es esta luz? Que los ancestros te bendigan...' WHERE `ID`=70322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 이 고통이 끝났군요...', `MaleText_loc4`='终于，苦难终结了……', `MaleText_loc5`='折磨終於結束了...', `MaleText_loc7`='Por fin se acaba el sufrimiento...' WHERE `ID`=70323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳에 영원히... 갇혔었는데... 이젠 자유인 겁니까?...', `MaleText_loc4`='本以为……我会被永远囚禁于此……最终我还是重获自由了吗？', `MaleText_loc5`='永遠...被困在這...我...終於自由了?', `MaleText_loc7`='Atrapado... para siempre... por fin... ¿soy libre?' WHERE `ID`=70324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 제 영혼이 이 저주받은 곳을 떠나는군요...', `MaleText_loc4`='终于我的灵魂可以离开这被诅咒的地方……', `MaleText_loc5`='我的靈魂終於可以離開這塊被詛咒的地方...', `MaleText_loc7`='Mi espíritu abandona este lugar maldito al fin...' WHERE `ID`=70325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어... 이 공포도 끝이 났군요...', `MaleText_loc4`='终于，灵魂不再惶恐……', `MaleText_loc5`='終於，無需恐懼了...', `MaleText_loc7`='Por fin acaba el horror...' WHERE `ID`=70326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종은 호드에게 매우 소중한 것이오.$b$b대족장님께서 우리에게 많은 기대를 걸고 있소.', `MaleText_loc4`='圣钟对于部落而言意义重大。$b$b酋长对我们寄予厚望。', `MaleText_loc5`='聖鐘對部落來說意義十分重大。$b$b大酋長只能靠我們了。', `MaleText_loc7`='La Campana divina es muy importante para la Horda.$b$bEl Jefe de Guerra cuenta con nosotros.' WHERE `ID`=70327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s|1이;가; |cFFFF0000|Hspell:135096|h[천둥충격]|h|r을 시전합니다! 떨어지십시오!', `MaleText_loc4`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s开始施放|cFFFF0000|Hspell:135096|h[雷霆打击]|h|r！快跑！', `MaleText_loc5`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s開始施展|cFFFF0000|Hspell:135096|h[雷擊]|h|r!快跑!', `MaleText_loc7`='|TInterfaceIconsability_thunderking_thunderstruck.blp:20|t%s comienza a lanzar |cFFFF0000|Hspell:135096|h[Atronado]|h|r. ¡Corre!' WHERE `ID`=70328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통! 먹을 걸 가져와라.', `MaleText_loc4`='童福！来点吃的。', `MaleText_loc5`='老童!請上點吃的來吧。', `MaleText_loc7`='¡Tong! Algo de comida, por favor.' WHERE `ID`=70329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕 바리안 린. 얼라이언스의 지도자.', `MaleText_loc4`='联盟的领袖——国王瓦里安·乌瑞恩。', `MaleText_loc5`='大君主瓦里安·烏瑞恩 - 聯盟的領袖。', `MaleText_loc7`='Su Majestad. Varian Wrynn: líder de la Alianza.' WHERE `ID`=70330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 한때 검투사였던 건 아나? 그래, 나도 나름대로 조사를 했지.', `MaleText_loc4`='你知道吗？他曾做过角斗士。没错，我调查过。', `MaleText_loc5`='你知道嗎，他曾經是競技場鬥士?是的，我研究過他的過去。', `MaleText_loc7`='¿Sabías que una vez fue gladiador? Ah, sí, he estado investigando.' WHERE `ID`=70331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바리안은 기억을 잃고 호드 투기장에서 목숨을 걸고 싸웠었다.', `MaleText_loc4`='当时失忆的他，在部落竞技场里厮杀求生。', `MaleText_loc5`='雖然失憶症纏身，但他仍然在部落競技場的殺戮中生存下來。', `MaleText_loc7`='Sufría amnesia y luchó por su vida en las arenas de la Horda.' WHERE `ID`=70332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기서 "로고쉬", "늑대 정령"이라는 별명을 얻었지.', `MaleText_loc4`='在那里，他叫“洛戈什”，外号“幽灵狼”。', `MaleText_loc5`='他在那裡贏得自己的頭銜「洛戈許」別名「鬼魂之狼」。', `MaleText_loc7`='Allí se ganó el apodo de "Lo''Gosh", o "Lobo fantasmal".' WHERE `ID`=70333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 훌륭한 투사지만... 훌륭한 지도자인가?', `MaleText_loc4`='他战技超群。可他…能当领袖吗？', `MaleText_loc5`='他是個戰士沒錯。但...他是個領袖嗎?', `MaleText_loc7`='ES un luchador. Pero... ¿es un líder?' WHERE `ID`=70334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생각해 봐라! 그의 적은 내 아버지의 대격변을 기회로 삼았지.', `MaleText_loc4`='想想吧！他的敌人利用了我父亲引发的大灾变。', `MaleText_loc5`='你想想!他的敵人利用我父親引發的大災變來進攻。', `MaleText_loc7`='¡Piensa en ello! Sus enemigos se aprovecharon del Cataclismo de mi padre.' WHERE `ID`=70335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 병사들은 그 파괴를 틈타 왕국을 짓밟았다.', `MaleText_loc4`='部落的军队在浩劫之后席卷大地。', `MaleText_loc5`='在毀滅中，部落的戰鼓響遍了整個世界。', `MaleText_loc7`='Soldados de la Horda atacaron por todo el reino tras la devastación.' WHERE `ID`=70336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 바리안 린은 재난을 전쟁에 이용하지 않았지.', `MaleText_loc4`='瓦里安·乌瑞恩却没有利用灾难赢得军事优势。', `MaleText_loc5`='但瓦里安·烏瑞恩沒有利用這次災難去取得戰略上的優勢。', `MaleText_loc7`='Varian Wrynn no usó el desastre para ganar ventaja militar.' WHERE `ID`=70337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 약해서일까... 아니면 고결해서일까?', `MaleText_loc4`='这是因为他软弱……？还是因为太讲原则？', `MaleText_loc5`='是因為他軟弱...?還是因為他有自己的原則?', `MaleText_loc7`='¿Fue porque es débil...? ¿O porque tiene principios?' WHERE `ID`=70338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 중요한 질문은, 고결함으로 전쟁에서 이길 수 있을까?', `MaleText_loc4`='更大的问题是：原则能赢得战争吗？', `MaleText_loc5`='最重要的問題是:原則能讓你贏得戰爭嗎?', `MaleText_loc7`='Y la gran pregunta: ¿pueden los principios ganar una guerra?' WHERE `ID`=70339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 들어라. 판다리아는 너의 왕을 시험할 것이다.', `MaleText_loc4`='潘达利亚对你们的国王无疑将是个挑战。', `MaleText_loc5`='不要懷疑。潘達利亞必定會挑戰你的國王。', `MaleText_loc7`='No te equivoques. Pandaria pondrá a tu Rey a prueba.' WHERE `ID`=70340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 진정 어떤 인물인지 보자.', `MaleText_loc4`='让我们看看他的能力。', `MaleText_loc5`='讓我們瞧瞧他有多少能耐。', `MaleText_loc7`='Veamos de qué está hecho realmente.' WHERE `ID`=70341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 얼라이언스가 아제로스를 지배할 실력이 되는지 보겠다.', `MaleText_loc4`='让我们看看联盟是否能够统治艾泽拉斯。', `MaleText_loc5`='讓我們瞧瞧聯盟是否真的有這本事來統治艾澤拉斯。', `MaleText_loc7`='Veamos si tu Alianza tiene lo que hace falta para gobernar Azeroth.' WHERE `ID`=70342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 헬스크림! 호드의 대족장.', `MaleText_loc4`='加尔鲁什·地狱咆哮！部落酋长。', `MaleText_loc5`='卡爾洛斯·地獄吼!部落的大酋長。', `MaleText_loc7`='¡Garrosh Grito Infernal! Jefe de Guerra de la Horda.' WHERE `ID`=70343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늘 지금처럼 강력했던 건 아니지.', `MaleText_loc4`='他并非一直如此强硬。', `MaleText_loc5`='他並非一直統御如此的權力。', `MaleText_loc7`='No siempre ostentó semejante poder.' WHERE `ID`=70344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드레노어에서 그는 비참하고 초라한 존재였다. 그 아버지의 행위가 가로쉬를 무겁게 짓눌렀지.', `MaleText_loc4`='在德拉诺，他就是个可怜虫。他父亲的过去总是纠缠着他。', `MaleText_loc5`='在德拉諾，他只是個卑微的可憐蟲。他背負著父親罪孽所留下的枷鎖。', `MaleText_loc7`='En Draenor no era más que un pobre diablo. Las acciones de su padre pesaban en su corazón.' WHERE `ID`=70345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 이해한다, 가로쉬. 아버지의 죄를 지고 살아가는 게 어떤 것인지 나는 안다.', `MaleText_loc4`='我明白，加尔鲁什。我知道背负父亲的罪孽是什么感觉。', `MaleText_loc5`='我能體會卡爾洛斯的感受。我知道背負這種沉重壓力的滋味。', `MaleText_loc7`='Te entiendo, Garrosh. Sé lo que es cargar con el peso de las acciones de tu padre.' WHERE `ID`=70346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 같은 전사가 권력을 잡았을 땐 뭔가를 증명해야 하지.', `MaleText_loc4`='让加尔鲁什这样的战士上台本身就说明了——', `MaleText_loc5`='像卡爾洛斯這樣的戰士在取得權力時必定會想做一番大事。', `MaleText_loc7`='Un guerrero como Garrosh llega al poder con algo que demostrar.' WHERE `ID`=70347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드는 기로에 서 있다. 이 전쟁이, 너희를 규정할 것이다.', `MaleText_loc4`='部落正面临转折。这场战争将定义你们。', `MaleText_loc5`='你們部落驚覺自己來到一個轉折點。這場戰爭將會決定你們的定位。', `MaleText_loc7`='Tu Horda se encuentra en un punto clave. Esta guerra nos definirá.' WHERE `ID`=70348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드란 무엇인가?', `MaleText_loc4`='什么才是部落？', `MaleText_loc5`='部落到底是什麼?', `MaleText_loc7`='¿Qué ES la Horda?' WHERE `ID`=70349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자신들의 미래를 쟁취하고자 맹렬히 달려나가는, 복수의 화신인가?', `MaleText_loc4`='它究竟是为了人民的未来而拼搏的复仇工具？', `MaleText_loc5`='是一個復仇的道具，不顧一切後果的為人民打拼未來?', `MaleText_loc7`='¿Un instrumento de venganza, decidido a forjar un futuro para su pueblo?' WHERE `ID`=70350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹은 쉴 곳이 필요한 자들의 피난처, 탄압받는 자들이 서로를 지탱하고자 만들어낸 연합인가?', `MaleText_loc4`='还是为了团结互助而建立起来的，庇护受压迫者的牢固同盟？', `MaleText_loc5`='或是一個難民的避難所、受人欺壓的可憐蟲為了互助才組成的同盟?', `MaleText_loc7`='¿Un refugio para aquellos que necesitan cobijo, una comunidad de oprimidos construida para el apoyo mutuo?' WHERE `ID`=70351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니면 서로 어울리지 않는 여러 집단이, 필요에 의해 손을 잡고 자유롭게 각자의 길을 추구하는 동맹인가?', `MaleText_loc4`='或者说，仅仅是一个权宜之计，由一群各怀目标的盟友临时拼凑而成？', `MaleText_loc5`='抑或是一群臨時組建的狐群狗黨，只懂得各自圖謀私利的烏合之眾?', `MaleText_loc7`='¿O es una unión de conveniencia, una confederación de compañeros insólitos, libres para satisfacer sus motivos personales?' WHERE `ID`=70352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 묻고 싶은 건 이것이다. 호드의 혼은 무엇인가?', `MaleText_loc4`='所以我想问你：部落的灵魂是什么？', `MaleText_loc5`='我要給你的考題是:部落的靈魂是什麼?', `MaleText_loc7`='Esta es la pregunta que te hago: ¿cuál es el ALMA de la Horda?' WHERE `ID`=70353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 판다리아에서 그 대답을 찾을 것이다.', `MaleText_loc4`='我们将在潘达利亚寻找答案。', `MaleText_loc5`='我們會在潘達利亞這裡找到答案。', `MaleText_loc7`='Encontraremos las respuestas aquí, en Pandaria.' WHERE `ID`=70354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 실력을 보여다오, 용사여!', `MaleText_loc4`='让我看看部落的实力吧，勇士！', `MaleText_loc5`='讓我看看你的部落到底有多強，勇士!', `MaleText_loc7`='¡Muéstrame de qué está hecha tu Horda!' WHERE `ID`=70355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 호드가 아제로스를 지배할 자격이 된다는 것을 증명해라.', `MaleText_loc4`='向我证明，部落有资格统治艾泽拉斯。', `MaleText_loc5`='向我證明你的部落有能耐能統治艾澤拉斯。', `MaleText_loc7`='Demuéstrame que tu Horda es digna de gobernar Azeroth.' WHERE `ID`=70356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 실로 영웅의 본보기다. 대의를 이루기에 부족함이 없군.', `MaleText_loc4`='你的确是一个英雄楷模。是联盟事业的勇士。', `MaleText_loc5`='你已經證明自己是個超卓非凡的英雄。掌握命運的勇士。', `MaleText_loc7`='Has demostrado una valentía ejemplar. Eres un adalid para tu causa.' WHERE `ID`=70357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 나눈 이야기를 기억하나?', `MaleText_loc4`='还记得我们之前的谈话吗？', `MaleText_loc5`='你還記得我們先前的談話內容嗎?', `MaleText_loc7`='¿Recuerdas nuestra conversación anterior?' WHERE `ID`=70358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 왕의 강점에 대해 이야기했지. 그간 그를 주의 깊게 지켜봤다.', `MaleText_loc4`='我们分析了你的国王。我一直在密切关注他。', `MaleText_loc5`='我們曾經談過你們國王的優點，而我一直在仔細觀察他。', `MaleText_loc7`='Discutíamos los méritos de tu Rey. Lo he estado observando de cerca.' WHERE `ID`=70359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사실이다. 바리안은 늑대의 영혼을 가졌고, 늑대처럼 싸우지.', `MaleText_loc4`='他的确有着狼的灵魂。他能像狼一样战斗。', `MaleText_loc5`='那些都是事實:他擁有狼的精神。而且他善戰如狼。', `MaleText_loc7`='Es cierto: tiene el espíritu de un lobo. Y lucha como un lobo.' WHERE `ID`=70360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그의 행동을 보니, 그게 무슨 뜻인지 알겠더군.', `MaleText_loc4`='看了他的作为，我明白了一件事。', `MaleText_loc5`='在看過他本人實戰後，我終於知道這是什麼意思。', `MaleText_loc7`='Ahora que lo he visto en acción sé lo que significa.' WHERE `ID`=70361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑대는 무리를 짓는다.', `MaleText_loc4`='狼是群居动物。', `MaleText_loc5`='狼是成群結黨的動物。', `MaleText_loc7`='Los lobos cazan en manada.' WHERE `ID`=70362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 왕은 무리를 자기 곁으로 불러들여, 얼라이언스를 진정한 동맹으로 다시 만들고 있지.', `MaleText_loc4`='你的国王召唤狼群，组成了“联盟”，赋予这个词真正的涵义。', `MaleText_loc5`='你的國王在召集狼群回到身邊，結成一個真正名符其實的聯盟。', `MaleText_loc7`='Tu Rey está llamando a su manada; reúne una Alianza en el sentido más puro de la palabra.' WHERE `ID`=70363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 갈 길이 멀다. 이제 겨우 한 발짝 뗐을 뿐이야.', `MaleText_loc4`='他的路还很长。他刚迈出第一步。', `MaleText_loc5`='他未來的旅程還很長。這只是跨出了第一步。', `MaleText_loc7`='Será una larga travesía. Solo ha dado los primeros pasos.' WHERE `ID`=70364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 너 같은 영웅이 그의 무리에 있으니, 얼라이언스가 하지 못할 일은 거의 없겠지.', `MaleText_loc4`='然而，有你这样的英雄在，联盟就没有什么做不成的事。', `MaleText_loc5`='但是如果有像你這樣的英雄常伴他左右，那聯盟幾乎已經所向披靡。', `MaleText_loc7`='Pero con héroes como tú en su manada, hay poco que tu Alianza no pueda lograr.' WHERE `ID`=70365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통, 물건을 가져와라!', `MaleText_loc4`='童福：把东西拿来！', `MaleText_loc5`='老童:把我的東西拿來!', `MaleText_loc7`='Tong, ¡trae mis cosas!' WHERE `ID`=70366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대의를 위한 너의 헌신은 보상받아 마땅하다.', `MaleText_loc4`='你对这份事业的贡献配得上这份奖励。', `MaleText_loc5`='你堅持理念所做出的貢獻值得獎勵。', `MaleText_loc7`='Tu dedicación a tu causa merece recompensa.' WHERE `ID`=70367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너처럼 나도 판다리아에서 내 능력을 갈고닦았지. 너도 그 결과에 만족하리라 믿는다.', `MaleText_loc4`='和你一样，我也在潘达利亚锻炼自己。相信结果会让你满意的。', `MaleText_loc5`='我會繼續在潘達利亞磨練我的能耐，就像你一樣。我認為你會對最終成果感到滿意。', `MaleText_loc7`='Al igual que tú, sigo perfeccionando mis habilidades en Pandaria. Creo que apreciarás el resultado.' WHERE `ID`=70368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보상을 선택해라!', `MaleText_loc4`='挑选奖励吧！', `MaleText_loc5`='選擇你的獎勵吧!', `MaleText_loc7`='¡Elige tu recompensa!' WHERE `ID`=70369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경계를 늦추지 마라, 영웅이여. 천둥왕의 귀환은 위협이자... 기회이기도 하지!', `MaleText_loc4`='小心，英雄。雷电之王的回归既是威胁……也是机遇！', `MaleText_loc5`='保持警戒，英雄。雷王的回歸是個威脅...同時也是個機會。', `MaleText_loc7`='Mantente alerta. ¡El regreso del Rey del Trueno es tanto una amenaza... como una oportunidad!' WHERE `ID`=70370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 실로 영웅의 본보기다. 대의를 이루기에 부족함이 없군.', `MaleText_loc4`='你的确是一个英雄楷模。是部落事业的勇士。', `MaleText_loc5`='你已經證明自己是個超卓非凡的英雄。掌握命運的勇士。', `MaleText_loc7`='Has demostrado una valentía ejemplar. Eres un adalid para tu causa.' WHERE `ID`=70371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 나눈 이야기를 기억하나?', `MaleText_loc4`='还记得我们之前的谈话吗？', `MaleText_loc5`='你還記得我們先前的談話內容嗎?', `MaleText_loc7`='¿Recuerdas nuestra conversación anterior?' WHERE `ID`=70372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 대족장의 내적인 갈등과, 외적인 정복성에 대해 얘기했지.', `MaleText_loc4`='我们谈了你的酋长。他内心的矛盾和外在的征服欲。', `MaleText_loc5`='我們談到過你的大酋長。他內心的掙扎和在外的征戰。', `MaleText_loc7`='Hablamos de tu Jefe de Guerra. De sus conflictos interiores y de sus conquistas.' WHERE `ID`=70373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 물었었다. 호드의 혼은 무엇인가?', `MaleText_loc4`='我问过你：部落的灵魂是什么？', `MaleText_loc5`='我還問你:部落的靈魂是什麼?', `MaleText_loc7`='Te pregunté: ¿cuál es el alma de la Horda?' WHERE `ID`=70374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아 남쪽 해안가와 다른 여러 곳에서 너의 활약을 보며 답을 얻었다.', `MaleText_loc4`='你在潘达利亚南岸和其他地方的努力已经给了我答案。', `MaleText_loc5`='你在潘達利亞南方海岸和其他各處的努力已經清楚的回答我了。', `MaleText_loc7`='Tus esfuerzos en las costas meridionales de Pandaria y en otros lugares me han dado la respuesta.' WHERE `ID`=70375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 바로 호드의 혼이다.', `MaleText_loc4`='你就是部落的灵魂。', `MaleText_loc5`='你就是部落的靈魂。', `MaleText_loc7`='TÚ eres el alma de la Horda.' WHERE `ID`=70376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 몇 주간의 네 행동이, 너의 사람들을 정의할 것이다.', `MaleText_loc4`='你在不久的未来定义你的人民。', `MaleText_loc5`='未來這幾個星期裡，你的行動將代表你的部落。', `MaleText_loc7`='Tus acciones en las semanas venideras definirán a tu gente.' WHERE `ID`=70377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다가오는 시련에 맞서려면 적절히 무장해야겠지.', `MaleText_loc4`='我想让你为未来的试炼做好准备。', `MaleText_loc5`='我要確保你已經做好萬全準備以面對接下來的挑戰。', `MaleText_loc7`='Quiero asegurarme de que tienes el equipo necesario para las pruebas que te esperan.' WHERE `ID`=70378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 얼라이언스의 영웅이여! 해변에서의 전쟁은 어떻게 되어 가지?', `MaleText_loc4`='欢迎回来，联盟的英雄！沿海的战斗进行得如何？', `MaleText_loc5`='歡迎回來，聯盟的英雄!在海岸沿岸的戰爭進行的如何?', `MaleText_loc7`='¡Te doy la bienvenida, valiente de la Alianza! ¿Cómo va la batalla en la costa?' WHERE `ID`=70379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그를 없앴나? 블러드힐트는 남부 불모의 땅에서 호드 군대를 이끌었지. 네가 오늘 많은 이들의 원수를 갚았구나.', `MaleText_loc4`='你杀掉他了吗？血柄曾在南贫瘠之地为部落效命。你为许多人报了仇，勇士。', `MaleText_loc5`='你殺死他了嗎?血柄曾在南貧瘠之地的部落大軍服役。你今日為許多人民報仇雪恥，勇士。', `MaleText_loc7`='¿Lo mataste? Sangrastil sirvió a la Horda en Los Baldíos del Sur. Hoy has vengado un gran número de vidas.' WHERE `ID`=70380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반갑다, 호드의 용사여! 해변에서의 전쟁은 어떻게 되어 가지?', `MaleText_loc4`='欢迎回来，部落的英雄！沿海的战斗进行得如何？', `MaleText_loc5`='歡迎回來，部落的英雄!在海岸沿岸的戰爭進行的如何?', `MaleText_loc7`='¡Te doy la bienvenida, valiente de la Horda! ¿Cómo va la batalla en la costa?' WHERE `ID`=70381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 트윈브레이드 장군이 죽었다고? 남부 불모의 땅을 압박하는 얼라이언스 군대에서 핵심적인 인물이었지. 훌륭하구나.', `MaleText_loc4`='那么，双辫将军死了吗？他是联盟在南贫瘠之地行动的关键人物。你干得很好。', `MaleText_loc5`='塔文布萊德將軍死了嗎?他是聯盟向南貧瘠之地推進的主將。非常了不起。', `MaleText_loc7`='¿Así que el general Trenzado está muerto? Era una figura clave en el avance de la Alianza por Los Baldíos del Sur. Impresionante.' WHERE `ID`=70382;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경계를 늦추지 마세요. 이곳은 몇 세기 동안 봉인되어 있었습니다. 뭐가 있을지 어찌 알겠어요?', `FemaleText_loc4`='保持警惕，英雄。这地方封闭了数百年。天知道里面会有什么东西。', `FemaleText_loc5`='保持警戒，英雄。這個地方已經被封印了好幾個世紀。誰知道我們會在裡面碰到什麼。', `FemaleText_loc7`='Mantente alerta. Este lugar lleva siglos sellado. Quién sabe qué encontraremos adentro.' WHERE `ID`=70383;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기 있습니다! 천상의 종이에요!', `FemaleText_loc4`='就是它，英雄！圣钟！', `FemaleText_loc5`='就是這個，英雄!『聖鐘』神擎! ', `FemaleText_loc7`='¡Ahí está! ¡La Campana divina!' WHERE `ID`=70384;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐였죠? 하긴, 상관없어요. 방해가 되는 건 모조리 쓰러뜨릴 테니까요.', `FemaleText_loc4`='那是什么？不管了。谁敢来妨碍我们就打倒他。', `FemaleText_loc5`='那是什麼東西?不管了。我們會把所有擋路的絆腳石幹掉。', `FemaleText_loc7`='¿Qué fue eso? No importa. Destruiremos a cualquiera que se interponga en nuestro camino.' WHERE `ID`=70385;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안전한 곳으로 가져가야 해요. 파수대! 시작하자.', `FemaleText_loc4`='我们必须把它送到安全的地方。哨兵，我们动手吧。', `FemaleText_loc5`='我們得把它帶到安全的地方。哨兵!趕快開始動作。', `FemaleText_loc7`='Debemos ponerla a salvo. ¡Centinelas! Manos a la obra.' WHERE `ID`=70386;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드. 이제서야 나타나다니 부끄러운 줄 알아라. 천상의 종은 이미 우리 것이다. 순찰대여! 공격하라!', `FemaleText_loc4`='部落。真可惜，你们来晚了。圣钟归我们了。游侠们！出击！', `FemaleText_loc5`='部落的傢伙。很遺憾你們這麼久才到，聖鐘已經是我們的。遊俠們!攻擊!', `FemaleText_loc7`='La Horda... Qué lástima que tardaron tanto en llegar. La Campana divina ya es nuestra. ¡Forestales, ataquen!' WHERE `ID`=70387;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아악! 내 궁수들을 돌파하다니! 파수대! 지금이다!', `FemaleText_loc4`='啊！我的弓箭手应该阻止你的！哨兵！进攻！', `FemaleText_loc5`='呃!我的弓箭手應該能阻止你們才對!哨兵!上!', `FemaleText_loc7`='¡Agh! Mis arqueros debieron detenerlos. ¡Centinelas, ahora!' WHERE `ID`=70388;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아. 내가 직접 상대해주지. 얼라이언스를 위하여!', `FemaleText_loc4`='很好。我将亲自对付你。为了联盟！', `FemaleText_loc5`='非常好。讓我來親自對付你。這是為了聯盟!', `FemaleText_loc7`='Muy bien, lucharé yo misma. ¡Por la Alianza!' WHERE `ID`=70389;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으으... 내 죽음은... 아무런 의미도 없다. 천상의 종은 이미 다르나서스에 있다. 너희 더러운 호드는... 절대 손에 넣지 못한다!', `FemaleText_loc4`='呃……我的死……不算什么。圣钟已经被送到了达纳苏斯。肮脏的部落……永远得不到它！', `FemaleText_loc5`='呃呃呃...我的死亡...並不代表什麼。聖鐘已經在達納蘇斯了。你這卑鄙的部落...永遠都拿不到它!', `FemaleText_loc7`='Agh... Mi muerte... no cambia nada. La Campana divina ya está en Darnassus. Horda asquerosa... ¡nunca la conseguirán!' WHERE `ID`=70390;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하늘의 주인들이여, 공격하라!', `FemaleText_loc4`='天空之子，进攻！', `FemaleText_loc5`='天之民，攻擊!', `FemaleText_loc7`='¡Moradoras del cielo, ataquen!' WHERE `ID`=70391;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너는 여기서 내 칼에 죽을 것이다!', `FemaleText_loc4`='你必将死在我的剑下！', `FemaleText_loc5`='你將斃命於此，死在我的劍下!', `FemaleText_loc7`='¡Morirás aquí, al filo de mi cuchilla!' WHERE `ID`=70392;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나는 어둠 속에서 공격한다!', `FemaleText_loc4`='我从阴影中出击！', `FemaleText_loc5`='我從暗影之中出擊!', `FemaleText_loc7`='¡Ataco desde las sombras!' WHERE `ID`=70393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 이야기 줄거리가 어떻게 됐던가요?', `MaleText_loc4`='再后来发生了什么？', `MaleText_loc5`='再講一下故事是怎麼說的?', `MaleText_loc7`='¿Me puedes volver a contar la historia?', `FemaleText_loc1`='그 이야기 줄거리가 어떻게 됐죠?', `FemaleText_loc4`='再后来发生了什么？', `FemaleText_loc5`='再講一下故事是怎麼說的?', `FemaleText_loc7`='¿Me puedes volver a contar la historia?' WHERE `ID`=70394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시끄러워!', `MaleText_loc4`='来点儿噪音！', `MaleText_loc5`='好大的聲音啊!', `MaleText_loc7`='¡RUIDOS MOLESTOS!' WHERE `ID`=70395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 원숭이 왕 지팡이 못 가져간다! 그리고 저건 진짜 원숭이 왕도 아니다.$b$b족장 잉구 잉구는 아버지 잉구 잉구한테서 지팡이 받는다. 그리고 그 아버지의 아버지에게서, 또 그 아버지의 아버지에게서 받는다.$b$b원숭이 왕은 아주 오래오래 전에 우리 가족에게 지팡이 줬다. 우리 가족은 족장이 됐지.$b$b그렇게 오래 사는 호젠은 없어! 아무도!', `MaleText_loc4`='不！美猴王不能拿走棍子！你也不能拿走棍子！这个是冒牌美猴王。$b$b酋长盎迦盎迦从他爸爸盎迦盎迦那里拿到棍子，他爸爸从他爸爸的爸爸那里拿到棍子，他爸爸的爸爸从他爸爸的爸爸的爸爸那里棍子。$b$b很久很久以前美猴王就把棍子给了我们家，我们家就都是酋长了。$b$b没有猢狲可以活这么久！没有！', `MaleText_loc5`='不行!美猴王不能拿走棒子!你不准拿走棒子!這個根本不是真的美猴王。$b$b印古大王從印古爸爸拿到棒子，爸爸從他爸爸拿到，爸爸他爸爸從爸爸他爸爸的爸爸拿到。美猴王很久很久以前把棒子給我們家。我們家變成首領。$b$b沒有猴人能活那麼久!沒有!', `MaleText_loc7`='¡No! ¡Rey Mono no se lleva vara! ¡Tú no lleva vara! Ese ni sikiera es Rey Mono de verdad.$b$bPapá Ingoo Ingoo dio vara a jefe Ingoo Ingoo, y a él se la dio su papá.$b$bEl Rey Mono dio la vara a mi familia hace mucho mucho tiempo. Mi familia se konvierte en jefe.$b$b¡Ningún hozen vive tanto tiempo! ¡Ninguno!' WHERE `ID`=70396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 저건 진짜 원숭이 왕입니다.', `MaleText_loc4`='但那确实是真的美猴王啊。', `MaleText_loc5`='但這真的是美猴王。', `MaleText_loc7`='Pero es el Rey Mono de verdad.', `FemaleText_loc1`='하지만 저건 진짜 원숭이 왕이에요.', `FemaleText_loc4`='但那确实是真的美猴王啊。', `FemaleText_loc5`='但這真的是美猴王。', `FemaleText_loc7`='Pero es el Rey Mono de verdad.' WHERE `ID`=70397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 얼마 없습니다, $n 님. 관리자 그랜틀리가 당신을 스톰윈드까지 모셔다 드릴 겁니다. 물론, 세상에 공짜는 없습니다.', `MaleText_loc4`='时间宝贵，$n。普凡迪特·格兰特利也许能够帮助你返回暴风城。当然，你得付点钱。', `MaleText_loc5`='時間非常重要，$n。供應商格蘭特雷可以帶你回暴風城。當然，他會收點小費。', `MaleText_loc7`='El tiempo apremia, $n. Es posible que el proveditor Grantley pueda ayudarte a volver a Ventormenta, pero claro, todo tiene un precio.' WHERE `ID`=70398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 잉구 잉구 족장. 가족들이 지팡이를 뭐에 쓰는지 까먹었다. 정신이 아주 나가버렸어.$b$b계속 그러다간 주민들까지 타락시킬 거야. 정말 슬프다.', `MaleText_loc4`='可怜的酋长盎迦盎迦。他的家族忘记了那棍子的用途。太疯狂。$b$b要是让他继续疯下去，他的人民会堕落。太不幸。', `MaleText_loc5`='可憐的印古首領，他們家忘記這棒子是幹嘛的，他已經瘋狂了。$b$b要是不除掉他，他會帶壞所有的猴人。太悲傷了。', `MaleText_loc7`='Pobre jefe Ingoo Ingoo. Su familia olvidó para ké servía la vara. Está muy enfadado.$b$bSi sigue así, korromperá a su gente. Ké triste.' WHERE `ID`=70399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='침묵해라, 선리버!', `FemaleText_loc4`='安静受死吧，夺日者！', `FemaleText_loc5`='奪日者，肅靜!', `FemaleText_loc7`='¡Se acabó, Atracasol!' WHERE `ID`=70400;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토는 반란을 용서치 않을 것이다.', `FemaleText_loc4`='肯瑞托绝不容忍叛乱。', `FemaleText_loc5`='祈倫托絕不會容忍叛變的行為。', `FemaleText_loc7`='El Kirin Tor no tolerará la insurrección.' WHERE `ID`=70401;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버여, 이건 너희가 자초한 일이다.', `FemaleText_loc4`='这是你们自找的，夺日者。', `FemaleText_loc5`='這是你們自找的，奪日者。', `FemaleText_loc7`='Ustedes se lo buscaron, Atracasol.' WHERE `ID`=70402;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도망칠 기회를 놓쳤구나.', `FemaleText_loc4`='你放弃了逃跑的机会。', `FemaleText_loc5`='該跑的時候不跑。', `FemaleText_loc7`='Pudieron escapar.' WHERE `ID`=70403;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 족속들이 없으면 달라란이 더 좋은 곳이 된다.', `FemaleText_loc4`='没有你们，达拉然会更好。', `FemaleText_loc5`='達拉然少了你們會變得更好。', `FemaleText_loc7`='Dalaran será un lugar mejor sin ustedes.' WHERE `ID`=70404;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈들이 한 짓에 후환이 없을 거라고 생각했나?', `FemaleText_loc4`='你们以为自己不用付出代价吗？', `FemaleText_loc5`='你以為你的行為不會有任何後果嗎?', `FemaleText_loc7`='¿Creyeron que sus actos no tendrían consecuencias?' WHERE `ID`=70405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네놈들은 키린 토가 아닌 가로쉬를 선택한 거야.', `FemaleText_loc4`='肯瑞托在你们心中还不如那个酋长。', `FemaleText_loc5`='你選擇效忠大酋長而非祈倫托。', `FemaleText_loc7`='Prefirieron a su Jefe de Guerra antes que al Kirin Tor.' WHERE `ID`=70406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 이제 죽어줘야겠구나!', `MaleText_loc4`='现在……你去死吧！', `MaleText_loc5`='現在... 你一定得死!', `MaleText_loc7`='Y hoy... ¡TÚ debes morir!' WHERE `ID`=70407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='차원문으로 들어가십시오!', `MaleText_loc4`='快进传送门！', `MaleText_loc5`='進入傳送門!', `MaleText_loc7`='¡Entra en el portal!' WHERE `ID`=70408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛날에 진짜 번쩍번쩍하고 신성한 망치 있었다.', `MaleText_loc4`='那把细细的钟杵曾经闪亮而神圣。', `MaleText_loc5`='從前有把好神槌，閃亮神聖惹人惜。', `MaleText_loc7`='Había una vez una hermosa marra divina,' WHERE `ID`=70409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 우낏 종은 내가 가지지 못할 운명을 타고 났다.', `MaleText_loc4`='但它只是用来敲钟的，我才不想要呢。', `MaleText_loc5`='有個大鐘給它敲，可惜不在我這邊。', `MaleText_loc7`='pero a enkontrar la kampana yo nunca atina.' WHERE `ID`=70410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 종 훔쳐갔는데, 호젠이 뭘 어떻게 할 수 있었겠어.', `MaleText_loc4`='可是魔古族偷走了那口钟，我一个猢狲应该怎么办？', `MaleText_loc5`='大鐘卻被魔古盜，猴人應該怎麼辦?', `MaleText_loc7`='La robaron los mogu, ¿ké tú kiere ke yo hace?' WHERE `ID`=70411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 응가쟁이들이 망치도 훔쳐가면 일어날 공포를 생각했지.', `MaleText_loc4`='我想那些混蛋肯定还要偷钟杵。', `MaleText_loc5`='槌子要是也被偷，大家應該怎麼辦?', `MaleText_loc7`='Si makakus roban marra, es muy mal desenlace.' WHERE `ID`=70412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 똑똑한 종족이 아니다. 망치의 본질을 알아내는 데 실패했지.', `MaleText_loc4`='魔古族不聪明，他们看不清事物存在的原因。', `MaleText_loc5`='終究魔古不聰明，東西本相看不透。', `MaleText_loc7`='Los mogu son tontos, solo saben dar tortazos,' WHERE `ID`=70413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원숭이 왕은 망치를 부숴서 조각낸 다음, 따로따로 멀리 보내버렸어.', `MaleText_loc4`='美猴王折断了钟杵，把碎片藏得远远的。', `MaleText_loc5`='猴王只好拆槌子，拆成三塊分開放。', `MaleText_loc7`='así ke el Rey Mono rompe la marra en pedazos.' WHERE `ID`=70414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 호젠 친구들이 조각들을 판다리아 전역에 퍼뜨렸지.', `MaleText_loc4`='我的猢狲们带着这些碎片，去往大陆各地。', `MaleText_loc5`='叫來猴人接過手，分散四處嚴收藏。', `MaleText_loc7`='Mis hozen llevan los trozos a puntos lejanos,' WHERE `ID`=70415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"펜촉"으로 위장시켰기 때문에 다시는 모구의 손에 들어가지 않았어.', `MaleText_loc4`='它们被伪装成“漂亮的小东西”，从未落入魔古族之手。', `MaleText_loc5`='裝神弄鬼瞎攪和，故意不給魔古知。', `MaleText_loc7`='digo ke son "rukos", así están en buenas manos.' WHERE `ID`=70416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치 머리와 손잡이, 이거 두 개는 반드시 하나로 합쳐져야 해.', `MaleText_loc4`='只要把钟杵的头和柄合起来，它就又完整了。', `MaleText_loc5`='槌柄槌頭拼一起，還要油膏塗上去。', `MaleText_loc7`='Kabeza y mango, ambas kosas tú debe reunir,' WHERE `ID`=70417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악마의 연고와 결합하면, 신성한 종의 악마를 물리칠 수 있어.', `MaleText_loc4`='再配上一点药膏，就能驱除这口钟的邪恶。', `MaleText_loc5`='等到聖槌拼一起，大鐘魔力不可怕。', `MaleText_loc7`='para así el mal de la kampana redimir.' WHERE `ID`=70418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 종을 가졌다면 이제 할 일은 하나 뿐이야.', `MaleText_loc4`='如果“加尔鲁什”拥有了这口钟，那我们只能做一件事情了。', `MaleText_loc5`='卡爾洛斯得大鐘，我們只能這樣做:', `MaleText_loc7`='Si ese "Garrosh" ha dado la kampana a sus chikos,' WHERE `ID`=70419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 호젠 친구를 부를 거야. 망치는 반드시 새로 만들어져야 해.', `MaleText_loc4`='我会召集我的猢狲朋友们，重铸这把钟杵。', `MaleText_loc5`='猴人朋友呼喚來，快快拼起這聖槌。', `MaleText_loc7`='ke hay ke montar la marra diré a todos mis mikos.' WHERE `ID`=70420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 머저리 같은 얼라이언스가 감히 가로쉬 님께 저항하려 하느냐!', `MaleText_loc4`='[PH] Some insult about how the Alliance is weak and boast about how Garrosh is awesome.', `MaleText_loc5`='[PH] Some insult about how the Alliance is weak and boast about how Garrosh is awesome.', `MaleText_loc7`='TEMP' WHERE `ID`=70421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 사원의 터에서 폭력을 일으키지 말거라, $p. 참을성을 키워라.', `MaleText_loc4`='不要把暴力带到我的寺庙和土地上来，$p。耐心点。', `MaleText_loc5`='別在我的神廟使用暴力，$P，要有耐心。', `MaleText_loc7`='No incites a la violencia en mi templo, $p. Ten paciencia.', `FemaleText_loc1`='내 사원의 터에서 폭력을 일으키지 말거라, $p. 참을성을 키워라.', `FemaleText_loc4`='不要把暴力带到我的寺庙和土地上来，$p。耐心点。', `FemaleText_loc5`='別在我的神廟使用暴力，$P，要有耐心。', `FemaleText_loc7`='No incites a la violencia en mi templo, $p. Ten paciencia.' WHERE `ID`=70422;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='국왕님께서 당신이 방어선을 구축하는 동안 사원을 감시하라고 절 보내셨어요.

참을성을 갖고 국왕님이 명령을 내리시기 전까지는 사원에 접근하지 마세요.', `FemaleText_loc4`='瓦里安派我在你建造防御工事的时候留意寺庙附近的情况。

耐心一点，除非瓦里安下达命令，否则不要靠近寺庙。', `FemaleText_loc5`='在你完成防禦工事的同時，瓦里安派我留意紅鶴寺的動靜。

保持耐心，在瓦里安下令前不要接近紅鶴寺。', `FemaleText_loc7`='Varian me ha enviado para vigilar el templo mientras tú te encargas de terminar la construcción de las defensas.

Ten paciencia y no te acerques al templo hasta que Varian dé la orden.' WHERE `ID`=70423;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반가워요, 친구.', `FemaleText_loc4`='你好，朋友。', `FemaleText_loc5`='你好啊，朋友。', `FemaleText_loc7`='Hola, $gamigo:amiga;.' WHERE `ID`=70424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사원 주위에 방어선을 구축하려고 합니다. 드루이드 여러분도 협력해 주시겠습니까?', `MaleText_loc4`='我们将在寺庙周围建造防御工事。你的德鲁伊们能帮忙吗？', `MaleText_loc5`='我們要用防禦工事包圍紅鶴寺，你的德魯伊能幫忙嗎?', `MaleText_loc7`='Tenemos que colocar defensas alrededor del templo. ¿Pueden ayudarnos tus druidas?', `FemaleText_loc1`='사원 주위에 방어선을 구축하려고 해요. 드루이드 여러분도 도와 주시겠어요?', `FemaleText_loc4`='我们将在寺庙周围建造防御工事。你的德鲁伊们能帮忙吗？', `FemaleText_loc5`='我們要用防禦工事包圍紅鶴寺，你的德魯伊能幫忙嗎?', `FemaleText_loc7`='Tenemos que colocar defensas alrededor del templo. ¿Pueden ayudarnos tus druidas?' WHERE `ID`=70425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여러분, 움직입시다. 엘룬께서 오늘 우리 발걸음을 이끄시길.', `FemaleText_loc4`='来吧孩子们。愿艾露恩指引我们今日的行动。', `FemaleText_loc5`='來吧，孩子，願伊露恩引導我們今日的作為。', `FemaleText_loc7`='Vengan, jóvenes. Que Elune guíe nuestras hazañas de hoy.' WHERE `ID`=70427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함정 같은 냄새가 나는군. 하지만 시간이 없네. 움직여!', `MaleText_loc4`='我感觉这像个陷阱，但是我们不能浪费时间了。我们走！', `MaleText_loc5`='肯定有陷阱，但是我們已經沒有時間可浪費了。走!', `MaleText_loc7`='Parece una trampa, pero no tenemos tiempo que perder. ¡Vamos!' WHERE `ID`=70428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사원 서쪽에서 뵈어요, $rt님. 그대의 도움이 필요할 거예요.', `FemaleText_loc4`='在寺庙西边和我们碰头，$rt。我们需要你的帮助。', `FemaleText_loc5`='在寺廟西邊跟我們碰面，$rt。我們會需要你的幫助。', `FemaleText_loc7`='Reúnete con nosotros al oeste del templo, $rt. Nos hará falta tu ayuda.' WHERE `ID`=70429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 미스가 내게 되돌려주었다네. 좀 조심하게! 이 유물은 귀하고도 귀한 물건이란 말일세.', `MaleText_loc4`='正好米师回到了我身边。你可得万分小心！这是件独一无二的稀有神器。', `MaleText_loc5`='剛好米什把這個拿回來給我，你應該要更小心點的!這個罕見的神器可是獨一無二的。', `MaleText_loc7`='Resulta que Mishi me lo ha devuelto. ¡Deberías tener más cuidado! Este artefacto es único.' WHERE `ID`=70431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 저를 꺾을 수 있다고 생각하시는 겁니까?', `MaleText_loc4`='你真以为你能打败我？', `MaleText_loc5`='你真的以為你能贏過我嗎?', `MaleText_loc7`='¿De verdad crees que puedes derrotarme?', `FemaleText_loc1`='정말 저를 꺾을 수 있다고 생각하시는 건가요?', `FemaleText_loc4`='你真以为你能打败我？', `FemaleText_loc5`='你真的以為你能贏過我嗎?', `FemaleText_loc7`='¿De verdad crees que puedes derrotarme?' WHERE `ID`=70432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸워봅시다!', `MaleText_loc4`='又有人来挑战了？', `MaleText_loc5`='又有挑戰者?', `MaleText_loc7`='¿Otro desafío?', `FemaleText_loc1`='싸워봐요!', `FemaleText_loc4`='又有人来挑战了？', `FemaleText_loc5`='又有挑戰者?', `FemaleText_loc7`='¿Otro desafío?' WHERE `ID`=70433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승자가 나왔습니다! $n|1이;가; 이번 주 낚시왕 선발대회에서 2등상을 받았습니다!', `MaleText_loc4`='胜利者诞生了！$n赢得了此次锦标赛的第二名！', `MaleText_loc5`='第二名出現了!恭喜$n!', `MaleText_loc7`='¡Ya tenemos $gganador:ganadora;! ¡$n ha quedado $gSEGUNDO:SEGUNDA; en el torneo!' WHERE `ID`=70435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승자가 나왔습니다! $n|1이;가; 이번 주 낚시왕 선발대회에서 3등상을 받았습니다!', `MaleText_loc4`='胜利者诞生了！$n赢得了此次锦标赛的第三名！', `MaleText_loc5`='第三名出現了!恭喜$n!', `MaleText_loc7`='¡Ya tenemos $gganador:ganadora;! ¡$n ha quedado $gTERCERO:TERCERA; en el torneo!' WHERE `ID`=70436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[소멸]|h|r에 의해 목숨을 잃었습니다. 에너지 소용돌이가 비활성화되기 전에 빠져나오십시오.', `MaleText_loc4`='|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[湮灭]|h|r杀死了你。在它失效之前离开能量漩涡。', `MaleText_loc5`='你被|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[肉體毀滅]|h|r殺死了。在能量漩渦結束前避開它。', `MaleText_loc7`='|TInterfaceIconsspell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[Desintegración]|h|r te ha matado. Sal del vórtice de energía antes de que se desactive.', `FemaleText_loc1`='당신은 |TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[소멸]|h|r에 의해 목숨을 잃었습니다. 에너지 소용돌이가 비활성화되기 전에 빠져나오십시오.', `FemaleText_loc4`='|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[湮灭]|h|r杀死了你。在它失效之前离开能量漩涡。', `FemaleText_loc5`='你被|TInterface\\Icons\\spell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[肉體毀滅]|h|r殺死了。在能量漩渦結束前避開它。', `FemaleText_loc7`='|TInterfaceIconsspell_arcane_massdispel.blp:20|t |cFFFF0000|Hspell:132275|h[Desintegración]|h|r te ha matado. Sal del vórtice de energía antes de que se desactive.' WHERE `ID`=70437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 날도 다 있군요. 안 그래요?

