Pobres grifos...' WHERE `ID`=70439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(대긴이 당신과 합류합니다.)|r', `MaleText_loc4`='一起行动吧。|cFF0008E8（达金会跟着你。）|r', `MaleText_loc5`='和我們一起戰鬥。|cFF0008E8(達金會跟隨你。)|r', `MaleText_loc7`='Lucha con nosotros. |cFF0008E8(Daggin te seguirá.)|r', `FemaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(대긴이 당신과 합류합니다.)|r', `FemaleText_loc4`='一起行动吧。|cFF0008E8（达金会跟着你。）|r', `FemaleText_loc5`='和我們一起戰鬥。|cFF0008E8(達金會跟隨你。)|r', `FemaleText_loc7`='Lucha con nosotros. |cFF0008E8(Daggin te seguirá.)|r' WHERE `ID`=70440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한번 날뛰어볼까요!', `MaleText_loc4`='我们走！', `MaleText_loc5`='我們動手吧!', `MaleText_loc7`='¡Vamos allá!' WHERE `ID`=70441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저리 가라. 네가 상관할 일이 아니다.', `MaleText_loc4`='继续前进，你不必担心这个。', `MaleText_loc5`='走開，不關你的事。', `MaleText_loc7`='Sigue a lo tuyo. Esto no te concierne.', `FemaleText_loc1`='저리 가. 네가 상관할 일이 아니야.', `FemaleText_loc4`='继续前进，你不必担心这个。', `FemaleText_loc5`='走開，不關你的事。', `FemaleText_loc7`='Sigue a lo tuyo. Esto no te concierne.' WHERE `ID`=70448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 일에 신경 끄는 게 좋다는 것 정도는 아실 텐데.', `MaleText_loc4`='你要是识时务，就不要插手这事。', `MaleText_loc5`='想活命的話就別插手。', `MaleText_loc7`='Si sabes lo que te conviene, te mantendrás al margen de esto.', `FemaleText_loc1`='이 일에 신경 끄는 게 좋다는 것 정도는 알지 않아?', `FemaleText_loc4`='你要是识时务，就不要插手这事。', `FemaleText_loc5`='想活命的話就別插手。', `FemaleText_loc7`='Si sabes lo que te conviene, te mantendrás al margen de esto.' WHERE `ID`=70449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='믿어지십니까? 이 은빛 서약단 놈들이 우리를 강탈하려고 합니다.', `MaleText_loc4`='这些银色盟约的家伙们想要打垮我们，你能相信吗？', `MaleText_loc5`='你相信嗎?這些白銀誓盟的混帳竟然在威脅我們。', `MaleText_loc7`='¿Te lo puedes creer? Estos matones del Pacto de Plata están intentando echarnos.', `FemaleText_loc1`='믿어지세요? 이 은빛 서약단 놈들이 우리를 강탈하려고 해요.', `FemaleText_loc4`='这些银色盟约的家伙们想要打垮我们，你能相信吗？', `FemaleText_loc5`='你相信嗎?這些白銀誓盟的混帳竟然在威脅我們。', `FemaleText_loc7`='¿Te lo puedes creer? Estos matones del Pacto de Plata están intentando echarnos.' WHERE `ID`=70450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하수도를 통해 나는 비명을 들었습니다. 무슨 일입니까?', `MaleText_loc4`='我从管道里听到了呼叫声，发生了什么事情？', `MaleText_loc5`='我聽到好多吼叫聲 - 發生了什麼事情?', `MaleText_loc7`='He oído gritos... ¿qué está pasando?', `FemaleText_loc1`='하수도를 통해 나는 비명을 들었어요. 무슨 일인가요?', `FemaleText_loc4`='我听到了呼叫声，发生了什么事情？', `FemaleText_loc5`='我聽到好多吼叫聲 - 發生了什麼事情?', `FemaleText_loc7`='He oído gritos... ¿qué está pasando?' WHERE `ID`=70451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 "축출"하다니? 도대체 이게 무슨 말도 안 되는 소립니까?', `MaleText_loc4`='到底是怎么回事？“肃清”是什么意思？', `MaleText_loc5`='說要「淨化」整座城是怎麼回事?', `MaleText_loc7`='¿Qué locura es esa de una "purga"?', `FemaleText_loc1`='우리를 "축출"하다니? 도대체 이게 무슨 말도 안 되는 소린가요?', `FemaleText_loc4`='到底是怎么回事？“肃清”是什么意思？', `FemaleText_loc5`='說要「淨化」整座城是怎麼回事?', `FemaleText_loc7`='¿Qué locura es esa de una "purga"?' WHERE `ID`=70452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕! 난 탁탁이야. 이제 골짜기로 데려다 줄게. 저기 커다란 풀색 덩치가 그러라고 했으니까.', `MaleText_loc4`='嘿，你好！我是泰克泰克。我现在就把你带到谷地去，就像那个绿皮大个子告诉我的那样。', `MaleText_loc5`='嗨!我是塔克-塔克。我會照著那個綠色大傢伙的吩咐，帶你到恆春谷。', `MaleText_loc7`='¡Hola! Yo es Tak-Tak. Yo te lleva al valle, komo ordena el makaku grande verde de ahí.' WHERE `ID`=70453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼끼 잠깐만 기다려봐! 혹시 너가 바닷가에서 끈적끈적 구리구리 얼라이언스 꾸르륵을 없애버린 그 우낏이야?', `MaleText_loc4`='等等！你就是那个把海滩上的联盟蠢蛋打得满地找牙的无毛怪？', `MaleText_loc5`='給我等一下下!你是那個把岸邊的賊兮兮聯盟壞壞趕走的怪怪人嗎?', `MaleText_loc7`='¡Espera un waku! ¿Tú es makaku ke limpia la playa de manduka aliada kon Alianza?' WHERE `ID`=70454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 아무 짓도 안 했습니다. 그냥 즐겁게 카드 게임을 하고 있었는데... 이 은빛 서약단 놈들이 와서 우리에게 가진 걸 다 내놓으라고 하더군요. 대체 왜 그러는 겁니까?', `MaleText_loc4`='当时我正自得其乐地玩着牌，那可是副好牌啊……忽然这些银色盟约的流氓就闯进来叫我们收拾东西走人。凭什么？', `MaleText_loc5`='我什麼壞事也沒做，只是跟幾個人在打牌，然後這些白銀誓盟的... 混帳就跑來勒索我們交出所有的東西。這是怎麼回事?', `MaleText_loc7`='Estaba echando una partida de cartas, sin molestar a nadie, cuando de repente llegaron unos... cafres del Pacto de Plata y nos dijeron que les entregáramos nuestras pertenencias. ¿Pero qué pasa?', `FemaleText_loc1`='전 아무 짓도 안 했어요. 그냥 즐겁게 카드 게임을 하고 있었는데... 그때 이 은빛 서약단 놈들이 와서 우리에게 가진 걸 다 내놓으라고 하더라고요. 대체 왜 그러는 거죠?', `FemaleText_loc4`='当时我正自得其乐地玩着牌，那可是副好牌啊……忽然这些银色盟约的流氓就闯进来叫我们收拾东西走人。凭什么？', `FemaleText_loc5`='我什麼壞事也沒做，只是跟幾個人在打牌，然後這些白銀誓盟的... 混帳就跑來勒索我們交出所有的東西。這是怎麼回事?', `FemaleText_loc7`='Estaba echando una partida de cartas, sin molestar a nadie, cuando de repente llegaron unos... cafres del Pacto de Plata y nos dijeron que les entregáramos nuestras pertenencias. ¿Pero qué pasa?' WHERE `ID`=70455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 서약단은 정신이 어떻게 된 것 아닙니까? 키린 토가 분명히 가만 있지 않을 겁니다!', `MaleText_loc4`='银色盟约的人全疯了吗？肯瑞托肯定不会容忍这种事情发生的！', `MaleText_loc5`='白銀誓盟是發瘋了嗎?祈倫托絕對不會容許這種事情!', `MaleText_loc7`='¿Acaso el Pacto de Plata ha perdido el juicio? ¡El Kirin Tor no permitirá algo así!', `FemaleText_loc1`='은빛 서약단은 정신이 어떻게 된 것 아닌가요? 키린 토가 분명히 가만있지 않을 거예요!', `FemaleText_loc4`='银色盟约的人全疯了吗？肯瑞托肯定不会容忍这种事情发生的！', `FemaleText_loc5`='白銀誓盟是發瘋了嗎?祈倫托絕對不會容許這種事情!', `FemaleText_loc7`='¿Acaso el Pacto de Plata ha perdido el juicio? ¡El Kirin Tor no permitirá algo así!' WHERE `ID`=70456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주 프라우드무어 님께서 우리가 떠나길 바라신다는군요. 이... 이해할 수가 없습니다.', `MaleText_loc4`='他们说普罗德摩尔女士要我们离开。我……我不明白啊。', `MaleText_loc5`='聽說普勞德摩爾女士要把我們趕走。我... 我不明白。', `MaleText_loc7`='Dijeron que Lady Valiente quiere expulsarnos. Yo... no lo entiendo.', `FemaleText_loc1`='여군주 프라우드무어 님께서 우리가 떠나길 바라신데요. 이... 이해할 수가 없네요.', `FemaleText_loc4`='他们说普罗德摩尔女士要我们离开。我……我不明白啊。', `FemaleText_loc5`='聽說普勞德摩爾女士要把我們趕走。我... 我不明白。', `FemaleText_loc7`='Dijeron que Lady Valiente quiere expulsarnos. Yo... no lo entiendo.' WHERE `ID`=70457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 여긴 안전하지 않습니다. 달라란에서 대피하셔야 합니다.', `MaleText_loc4`='这里已经不安全了。你必须马上逃离达拉然。', `MaleText_loc5`='這裡已經不安全了，你得立刻離開達拉然。', `MaleText_loc7`='Aquí ya no estamos a salvo. Debemos evacuar Dalaran.', `FemaleText_loc1`='이제 여긴 안전하지 않아요. 달라란에서 대피하셔야 해요.', `FemaleText_loc4`='这里已经不安全了。你必须马上逃离达拉然。', `FemaleText_loc5`='這裡已經不安全了，你得立刻離開達拉然。', `FemaleText_loc7`='Aquí ya no estamos a salvo. Debemos evacuar Dalaran.' WHERE `ID`=70458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 네가 한 일이야? 대단한데!', `MaleText_loc4`='这些都是你干的？你真能干！', `MaleText_loc5`='這都是你一個人做的?你好讚!', `MaleText_loc7`='¿Tú hace todo eso? Tú mola.' WHERE `ID`=70459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아, 전에 커다란 흙색 친구가 북쪽으로 데려다달라고 하더라고. 가로드... 어... 가노쉬... 어... 아, 이름을 알아듣지 못했네.', `MaleText_loc4`='你知道吗，那个棕色皮肤的大家伙去北边儿了。那个加鲁德……呃……加诺什……呃，反正他名字我记不住。', `MaleText_loc5`='你知道，那個棕色的大傢伙之前想往北邊走一趟。他叫卡偶洛...呃...卡爾漏...呃...總之，我沒記他的名字。', `MaleText_loc7`='Antes un makaku grandote marrón pide viaje al norte. Se llama Garrote... no... Garrulo... Eh... Yo no rekuerda.' WHERE `ID`=70460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 중요한 녀석처럼 보이던데. 탁탁은 같이 얘기라도 좀 하려고 했는데, 그냥 멀뚱히 날 쳐다보기만 해서, 나도 그냥 입을 확 닫아버렸어.', `MaleText_loc4`='他看上去有很重要的事情。泰克泰克想要和他聊聊，但是他一瞪我，我就只能闭嘴了。', `MaleText_loc5`='他看起來很有地位。塔克-塔克想找他哈拉一下，可是他瞪著我，所以我馬上就閉嘴了。', `MaleText_loc7`='Parecía importante. Tak-Tak intenta darle palike, pero él me mira sin decir nada, así ke yo kalla enseguida.' WHERE `ID`=70461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 그렇게 말씀하시니 어쩔 수 없군요.', `MaleText_loc4`='好吧，如果你这么说的话。', `MaleText_loc5`='好吧，如果你這麼說的話。', `MaleText_loc7`='Si crees que es lo mejor...', `FemaleText_loc1`='당신이 저를 지켜주신다면... 그렇게 할게요.', `FemaleText_loc4`='只要有你在背后支援……', `FemaleText_loc5`='只要你能掩護我就行...', `FemaleText_loc7`='Mientras cuente contigo...' WHERE `ID`=70462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 다 온 것 같네.', `MaleText_loc4`='哦，看起来我们到了！', `MaleText_loc5`='喔，看來我們到了!', `MaleText_loc7`='¡Nosotros ya ha llegado!' WHERE `ID`=70463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌어.', `MaleText_loc4`='运气真不错。', `MaleText_loc5`='祝你好運。', `MaleText_loc7`='Buena suerte.' WHERE `ID`=70464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 만났네. 잘 지냈어?', `MaleText_loc4`='我们又见面了。你今天过得好吗？', `MaleText_loc5`='我們又見面了。今天過得好嗎?', `MaleText_loc7`='Hola de nuevo. ¿Tú está pasando bien?' WHERE `ID`=70465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 탁탁이 듣기로 여기 많은 일들이 일어나고 있어. 너희 대족장 가로쉬가 영원꽃 골짜기에서 뭔가 살펴보고 있나봐.', `MaleText_loc4`='不管怎样，泰克泰克在营地里听到了许多信息。我听说你的酋长加尔鲁什正在调查锦绣谷。', `MaleText_loc5`='總之呢，塔克-塔克在營地裡聽說了很多事情。據說你的大酋長卡爾洛斯在恆春谷附近打探。', `MaleText_loc7`='Tak-Tak oye muchas cosas en el campamento. Yo oye que tu Jefe de Guerra Garrosh se pasea por el Valle de la Flor Eterna.' WHERE `ID`=70466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쁜 엘프들이랑 거기에서 무언가 찾았어?', `MaleText_loc4`='你和你的漂亮精灵们在那儿的时候有什么发现吗？', `MaleText_loc5`='你跟那些漂亮的精靈在那邊有找到些什麼嗎?', `MaleText_loc7`='¿Tú y los elfos guapos enkuentra algo allí?' WHERE `ID`=70467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종인가 뭔가에 대해서 들었어. 그 이상한 모구들이 만든 거 말이야... 수천 년 전에 만들었대. 예끼할 우낏들 같으니!', `MaleText_loc4`='我听说了关于一口钟的事情，由那些疯狂的魔古族……在几千年前制造的。太可怕了！', `MaleText_loc5`='我聽說有個什麼鐘的，是數千年前...由那些瘋狂魔古打造的。那些怪怪人!', `MaleText_loc7`='Yo oye algo sobre una kampana ke fabrikan los mogu lokos hace miles de años. ¡Dingues makakus!' WHERE `ID`=70468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 실버문으로 다시 돌아갈 수 있을 것 같습니다...', `MaleText_loc4`='我想我能回银月城了……', `MaleText_loc5`='我只能回銀月城了...', `MaleText_loc7`='Supongo que podría volver a Lunargenta...', `FemaleText_loc1`='달라란을 떠나라고요? 도대체 어디로 가야 하는 건지..', `FemaleText_loc4`='离开达拉然？那我应该去哪里……', `FemaleText_loc5`='離開達拉然?那我能去哪裡...', `FemaleText_loc7`='¿Irme de Dalaran? ¿Adónde iría?' WHERE `ID`=70469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 대족장이 그 종을 찾아오래? 모구가 만든 건 다 위험해... 그리고 다 엄청 세고.', `MaleText_loc4`='你的酋长现在想要找那口钟？任何魔古族制造的东西都很危险……也很厉害。', `MaleText_loc5`='你的大酋長要去找那座鐘了嗎?魔古的東西都很危險...也很強大。', `MaleText_loc7`='¿Tu Jefe de Guerra va a buskar la kampana? Todas las kosas mogu son peligrosas... y poderosas.' WHERE `ID`=70470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 빈안 마을에 거의 다 온 것 같아. 너 정말 우끼할정도로 중요한 사람인가봐.', `MaleText_loc4`='不管怎样，我们就快到滨岸村了。我想你一定是在做一件非常重要的事情。', `MaleText_loc5`='總之呢，我們快到濱南村了。你一定有什麼很重要很重要的事情要做。', `MaleText_loc7`='Kasi hemos llegado a la Aldea Binan. Tú debe de estar haciendo algo muy importante.' WHERE `ID`=70471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 판다렌이 널 그곳으로 데려다주랬어.', `MaleText_loc4`='是一个大块头熊猫人叫我把你带去那里的。', `MaleText_loc5`='有個大塊頭熊貓人叫我帶你過去。', `MaleText_loc7`='Un pandaren grande viene y me pide ke te traiga akí.' WHERE `ID`=70472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁이 어디로 가는지 아무한테도 말하지마! 라고 했어.', `MaleText_loc4`='他说别把你的行踪告诉任何人！', `MaleText_loc5`='他說，別告訴任何人你要去哪!', `MaleText_loc7`='¡Dice ke no le diga a nadie adónde tú va!' WHERE `ID`=70473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁 약속은 지켜. 탁탁 정말 아무 말도 안 했어. 나 엄청 도움되지!', `MaleText_loc4`='泰克泰克很守信用。泰克泰克口风很紧。我能帮忙！', `MaleText_loc5`='塔克-塔克說話有信用。塔克-塔克一直沒多嘴。我很有用!', `MaleText_loc7`='Tak-Tak kumple su palabra. Tak-Tak ha estado kallado. ¡Siempre ayuda!' WHERE `ID`=70474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 다 왔다. 어서 내려!', `MaleText_loc4`='好了，我们到了。下去吧！', `MaleText_loc5`='好啦，我們到了。下去!', `MaleText_loc7`='Bueno, nosotros ya llegar. ¡Fuera!' WHERE `ID`=70475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏, 다시 쿤라이 봉우리로 가는 거야?', `MaleText_loc4`='想要飞回昆莱山吗，无毛怪？', `MaleText_loc5`='怪怪人，你要回崑萊峰嗎?', `MaleText_loc7`='¿Makaku vuelve a la Cima Kun-Lai?' WHERE `ID`=70476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번에 봤을 땐 너 판다렌 친구 본다고 빈안 마을로 간다 그랬다.', `MaleText_loc4`='我们上次见面的时候，你正要去滨岸村找你的熊猫人朋友。', `MaleText_loc5`='上次我們見面的時候，你正往濱南村去找熊貓人朋友。', `MaleText_loc7`='La última vez, tú iba a la Aldea Binan a ver a tu kolega pandaren.' WHERE `ID`=70477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼일은 잘 끝났어?', `MaleText_loc4`='你把该干的事干完了吗？', `MaleText_loc5`='你的事情搞定了嗎?', `MaleText_loc7`='¿Tú ha terminado tu trabajo?' WHERE `ID`=70478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데, 아까 이쁘장한 엘프들이 북쪽으로 향하는 걸 봤다. 엘프 많이.', `MaleText_loc4`='不管怎样，我又看到许多漂亮的精灵往北边儿去了。很多很多精灵。', `MaleText_loc5`='對了，我剛剛看到更多的漂亮精靈往北走了，很多的精靈。', `MaleText_loc7`='Yo ha visto a más elfos guapos yendo al norte. Muchos elfos.' WHERE `ID`=70479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 종을 찾는 거야. 크고, 강한 종! 우낏, 너도 그거 찾아?', `MaleText_loc4`='他们正在找那口钟。又大又厉害的钟！无毛怪，你也在找那钟吗？', `MaleText_loc5`='他們在找那個鐘。又大又強的鐘。你也在找這個鐘對嗎，怪怪人?', `MaleText_loc7`='Buskan la kampana. ¡Kampana grande y poderosa! ¿Makaku también buska?' WHERE `ID`=70480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 말도 안 됩니다. 에이타스 님께 말씀드려야겠군요!', `MaleText_loc4`='这太过分了！艾萨斯会知道这一切的！', `MaleText_loc5`='這實在太過份了!埃薩遲早會知道這件事的!', `MaleText_loc7`='¡Esto es un ultraje! ¡Aethas lo sabrá!', `FemaleText_loc1`='좋아요. 하지만 이 일을 곧바로 대마법사님께 알려드릴 거예요.', `FemaleText_loc4`='好吧，但是我会直接向大法师汇报此事。', `FemaleText_loc5`='好，但我一定要告訴埃薩。', `FemaleText_loc7`='Muy bien, pero pienso ir directa a contárselo al archimago.' WHERE `ID`=70481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 왔어. 잘 가!', `MaleText_loc4`='我们到了。再见！', `MaleText_loc5`='我們到了。再會!', `MaleText_loc7`='Nosotros han llegado. ¡Adiós!' WHERE `ID`=70482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우끼, 뭔가 큰일이 벌어진다.', `MaleText_loc4`='哦，那个大东西晃起来了。', `MaleText_loc5`='喔，大傢伙抖個不停。', `MaleText_loc7`='Oooh, pasa algo gordo.' WHERE `ID`=70483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이쁘장한 엘프들이 모구지아에서 얻어맞았단 소리 들었어.', `MaleText_loc4`='我听说不少漂亮的精灵在魔古岬被打翻了。', `MaleText_loc5`='我聽說漂亮精靈在魔古岬那邊被修理了一頓。', `MaleText_loc7`='Yo ha oído ke han jeringado a elfos guapos en Mogujia.' WHERE `ID`=70484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 거기 있지 않았어? 엘프들이 맞는 거 봤어?', `MaleText_loc4`='那个，当时你在吗？你看见了吗？', `MaleText_loc5`='嘿，你不是在場嗎?你看見了嗎?', `MaleText_loc7`='¿Tú ha estado allí? ¿Ha visto algo?' WHERE `ID`=70485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하여튼, 로르테 어쩌고 하는 엘프 족장... 진짜로 화났다!', `MaleText_loc4`='不管怎样，高个子精灵首领，那个洛瑟姆……什么的，他简直气疯了！', `MaleText_loc5`='總之，那個大精靈頭頭，洛索瑪...什麼來著的...他氣瘋了!', `MaleText_loc7`='Y ahora el gran jefe elfo, Lor... Lor''the... ¡está muy enfadado!' WHERE `ID`=70486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프는 코룬 모구랑 싸울 준비 안 되어 있었어. 블러드 엘프 많이 죽었다. 하지만 네가 살아남은 엘프 많이 구했다고 들었어.', `MaleText_loc4`='血精灵并未做好与寇茹魔古战斗的准备。许多血精灵牺牲了，可我听说你救下了不少幸存者。', `MaleText_loc5`='那些血精靈沒想到會遇上考倫魔古，結果很多血精靈都死了，但是我聽說你救了不少生還者。', `MaleText_loc7`='Los elfos de sangre no estaban preparados para luchar kontra los mogu Korune. Murieron muchos elfos, pero yo oye ke tú salva a muchos sobrevivientes.' WHERE `ID`=70487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론입니다. 이 하수도가 지겨웠거든요.', `MaleText_loc4`='好吧，我早就厌烦这下水道了。', `MaleText_loc5`='好啊，反正我早就想離開這個下水道了。', `MaleText_loc7`='Claro. De todas formas ya me estaba cansando de este agujero.', `FemaleText_loc1`='두말할 필요도 없죠. 저는 이 도시에 놓아두고 가고 싶은 빚이 있거든요.', `FemaleText_loc4`='你不用告诉我两次。在这城里我欠了许多债，我不想还了。', `FemaleText_loc5`='不用一直提醒我，我在這座城市裡欠了很多錢，早就想離開了。', `FemaleText_loc7`='No me lo digas dos veces. Tengo deudas en esta ciudad que no me importaría dejar atrás.' WHERE `ID`=70488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 다음엔 무슨 일 벌어졌는지 궁금하지?', `MaleText_loc4`='你可能想问，然后发生了什么？', `MaleText_loc5`='你一定想問，後來怎麼啦?', `MaleText_loc7`='Seguro ke tú pregunta: ¿y entonces ké pasa?' WHERE `ID`=70489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래서 어떻게 됐냐 하면, 엘프들 완전히 구리구리 응가 당했다! 어이쿠!', `MaleText_loc4`='然后精灵游侠的手下都被干掉了！噢！', `MaleText_loc5`='那好吧，後來遊俠精靈那夥人的蛋蛋差點被打爆了!嗚!', `MaleText_loc7`='¡Pues lo ke pasa es ke a la gente del forestal elfo le hacen kraku en los wakus! ¡Ay!' WHERE `ID`=70490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘프 족장 화났다! 진짜 화났다!', `MaleText_loc4`='他气疯了，兄弟，真的疯了！', `MaleText_loc5`='他生氣了，兄弟，真的生氣了!', `MaleText_loc7`='Está enfadado. Muy enfadado.' WHERE `ID`=70491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 너네 대족장한테 충성하지만, 뭔가 다르게 일하고 싶어해.', `MaleText_loc4`='他仍然效忠部落酋长，但是他想干点与众不同的事情。', `MaleText_loc5`='他雖然忠於你們的大酋長，但是他想用自己的方法來做事。', `MaleText_loc7`='Todavía es leal al Jefe de Guerra, pero kiere hacer kosas de forma distinta.' WHERE `ID`=70492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 힘밖에 몰라! 로르테마르는 전략가고.', `MaleText_loc4`='加尔鲁什只注重力量！而洛瑟玛更在乎战略。', `MaleText_loc5`='卡爾洛斯喜歡靠力量!洛索瑪喜歡靠戰術。', `MaleText_loc7`='¡Garrosh valora la fuerza! Lor''themar valora la estrategia.' WHERE `ID`=70493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁처럼 단순한 호젠 눈에도 다 보여!', `MaleText_loc4`='就连泰克泰克这样单纯的猢狲都看出来了！', `MaleText_loc5`='就連塔克-塔克這樣的猴人都看得出來!', `MaleText_loc7`='¡Hasta un hozen komo Tak-Tak se da cuenta!' WHERE `ID`=70494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 봐라. 다 왔다. 나중에 봐!', `MaleText_loc4`='哦，看呀，我们到了。回头见！', `MaleText_loc5`='你看，我們到了。再見!', `MaleText_loc7`='Ah, mira, nosotros ya han llegado. ¡Hasta luego!' WHERE `ID`=70495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 황제의 골짜기는 어땠어, 우낏?', `MaleText_loc4`='你的皇帝谷之旅如何呀，无毛怪？', `MaleText_loc5`='你的帝王谷之行還順利嗎，怪怪人?', `MaleText_loc7`='¿Ké tal le ha ido a makaku en el Valle de los Emperadores?' WHERE `ID`=70496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 위는 추워. 위험하기도 하고!', `MaleText_loc4`='那儿可真冷，而且很危险！', `MaleText_loc5`='那裡好冷。而且好危險!', `MaleText_loc7`='Allá hace frío. ¡Y es peligroso!' WHERE `ID`=70497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 너무 많아. 멍청한 우리 산 호젠 사촌들만 거기 산다고.', `MaleText_loc4`='还有好多魔古族。只有那些笨蛋高山猢狲亲戚们才会住在那里。', `MaleText_loc5`='那裡太多魔古了。只有笨蛋山地猴人才會住在上面。', `MaleText_loc7`='Demasiados mogu. Allá solo viven primos tontos de los hozen.' WHERE `ID`=70498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 우끼끼하게 멍청하다니까!', `MaleText_loc4`='他们真是蠢死了！', `MaleText_loc5`='他們真是蠢爆了!', `MaleText_loc7`='¡Son mikos estúpidos!' WHERE `ID`=70499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너가 그 뭔가... 누군가를 찾았다고 하던데. 그 모구 중 하나를 잡은 거지?', `MaleText_loc4`='我听说你找到了什么东西……还是什么人来着？你抓到了个魔古族，是不是？', `MaleText_loc5`='我聽說你找到某樣東西...還是某個人。你抓到一個魔古，對嗎?', `MaleText_loc7`='Yo oye ke tú encuentra algo... o a alguien. Tú atrapa a un mogu, ¿a que sí?' WHERE `ID`=70500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 모구가 그 종을 어디서 찾을 수 있는지 알려줄지도 몰라.', `MaleText_loc4`='也许坏蛋魔古族会告诉你那口钟在哪儿。', `MaleText_loc5`='那個壞魔古說不定可以告訴你鐘藏在哪。', `MaleText_loc7`='A lo mejor mogu malo te kuenta dónde está la kampana.' WHERE `ID`=70501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알려줘서 고맙습니다. 몸조심하십시오.', `MaleText_loc4`='谢谢你的警告。一路平安。', `MaleText_loc5`='謝謝你的警告。請保重。', `MaleText_loc7`='Gracias por el aviso. Cuídate.', `FemaleText_loc1`='이제 갈게요. 쇼렐러란.', `FemaleText_loc4`='我走了。Shorel''aran.', `FemaleText_loc5`='好，我會離開。再見。', `FemaleText_loc7`='Partiré. Shorel''aran.' WHERE `ID`=70502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁은 모구가 어둠의 마법을 쓴다는 얘기도 들었어.', `MaleText_loc4`='泰克泰克还听说魔古族会使用黑暗魔法。', `MaleText_loc5`='塔克-塔克聽說魔古會用黑暗魔法。', `MaleText_loc7`='Tak-Tak también oye que mogu usan magia oskura.' WHERE `ID`=70503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호젠은 그걸... 익크라고 불러! 너희는 샤라고 하는데, 익크가 훨씬 좋은 이름이야!', `MaleText_loc4`='我们猢狲叫它……伊克！你们叫它煞，但是伊克这个名字要好得多！', `MaleText_loc5`='猴人把它叫做...黑嘎嘎!你們叫做煞，但是黑嘎嘎好聽多了!', `MaleText_loc7`='Los hozen la llaman... ¡ikk! Ustedes llaman sha, pero ikk mola MUCHO más.' WHERE `ID`=70504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 그 미친 모구가 익크 으쌰를 쓰고 있어.', `MaleText_loc4`='不管怎样，那些疯狂的魔古族会使用伊克魂能。', `MaleText_loc5`='反正那些瘋狂魔古會用黑嘎嘎魔法。', `MaleText_loc7`='En fin, ke mogu lokos usan yuyu ikk.' WHERE `ID`=70505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 호젠도 익크가 정말 나쁘다는 거 알아. "응가는 먹지 말 것. 익크는 건드리지 말 것."', `MaleText_loc4`='即使是最笨的猢狲都知道伊克比什么东西都坏。别吃烂东西，也别碰伊克！', `MaleText_loc5`='就連最蠢的猴人也知道黑嘎嘎是最糟糕的東西。別吃便便，別碰黑嘎嘎!', `MaleText_loc7`='Hasta los hozen tontos saben ke ikk es lo peor. No se kome kaka, y no se toka ikk.' WHERE `ID`=70506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할이 나쁜 말이라고 생각해? 그건 정말 익크같이 멍청한 소리야.', `MaleText_loc4`='你觉得“该死的”是脏话？你伊克的什么都不知道。', `MaleText_loc5`='你覺得便便很噁心嗎?等你碰到黑嘎嘎就知道了。', `MaleText_loc7`='¿Tú kree ke kraku es una palabrota? Tú no sabe un waku.' WHERE `ID`=70507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문까지 연을 타고 갈 수는 없어! 너 바보야?', `MaleText_loc4`='我可不想乘一只风筝飞到银月城！你疯了吗？', `MaleText_loc5`='我才不要飛到銀月城!你瘋了嗎?', `MaleText_loc7`='¡Yo no manda kometa a Lunargenta! ¡Makaku $gloko:loka;!' WHERE `ID`=70508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여.', `MaleText_loc4`='哟。', `MaleText_loc5`='喲。', `MaleText_loc7`='Buenas.' WHERE `ID`=70509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한참 동안 못봤네. 어떻게 지냈어?', `MaleText_loc4`='很久没见了，无毛怪。最近好吗？', `MaleText_loc5`='粉久沒看到你了，怪怪人。你還好嗎?', `MaleText_loc7`='Hace tiempo ke tú no viene. ¿Ké tal?' WHERE `ID`=70510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁은 얘기 듣고 있었어. 다들 "아, 탁탁은 바보 호젠이니까 아무것도 모를거야"라고 하더라고.', `MaleText_loc4`='泰克泰克听到了很多。每个人都想，哦，泰克泰克是个笨猢狲，他啥都不懂。', `MaleText_loc5`='塔克-塔克會收集很多消息。大家都認為塔克-塔克是笨猴人，什麼都不懂。', `MaleText_loc7`='Tak-Tak escucha. Todo el mundo piensa ke Tak-Tak es hozen tonto y no sabe nada.' WHERE `ID`=70511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근데 탁탁 아는 거 많아!', `MaleText_loc4`='但是泰克泰克知道的可不少！', `MaleText_loc5`='其實塔克-塔克知道很多事情!', `MaleText_loc7`='¡Pues Tak-Tak sabe muchas kosas!' WHERE `ID`=70512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 커다란 오크 장군 나즈그림도 알아! 시끄러운 녀석이야! 탁탁도 모든 얘기 잘 들어!', `MaleText_loc4`='还有那个大个子兽人将军，纳兹戈林！', `MaleText_loc5`='就像那個獸人大塊頭將軍納茲格寧姆!他講話真大聲!塔克-塔克什麼都聽得到!', `MaleText_loc7`='¡Ese gran general orko, Nazgrim! ¡Habla muy alto! ¡Tak-Tak oye todo!' WHERE `ID`=70513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탁탁 또 아는 거 있어...', `MaleText_loc4`='泰克泰克还知道……', `MaleText_loc5`='至少塔克-塔克知道...', `MaleText_loc7`='Tak-Tak sabe una kosa...' WHERE `ID`=70514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 로르테마르 엘프가 호드를 떠나려고 해!', `MaleText_loc4`='精灵游侠洛瑟玛正在考虑脱离部落！', `MaleText_loc5`='精靈遊俠洛索瑪想離開部落!', `MaleText_loc7`='¡El forestal elfo, Lor''themar, igual kiere irse de la Horda!' WHERE `ID`=70515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바인은 가로쉬가 대족장에 어울리지 않는 것 같다고 생각해.', `MaleText_loc4`='贝恩则怀疑加尔鲁什是否合适当酋长。', `MaleText_loc5`='貝恩擔心卡爾洛斯不適合當大酋長。', `MaleText_loc7`='Jefe Baine kree ke igual Garrosh no es buen jefe.' WHERE `ID`=70516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 가로쉬는 그 망할 종이 빨리 나타나지 않아서 짜증이 났어. 모구가 잘 숨겼나봐!', `MaleText_loc4`='加尔鲁什找不到那口该死的钟，他已经快没耐心了。魔古族可真会藏东西！', `MaleText_loc5`='還有卡爾洛斯找那個該死的鐘已經找到失去耐心了。魔古還真會藏鐘!', `MaleText_loc7`='Y Garrosh pierde la paciencia porke no enkuentra la kampana de los wakus. ¡Los mogu la eskonden bien!' WHERE `ID`=70517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 내가 들은 게, 가로쉬는 그 모구 포로가 입을 열 때까지 고문하겠다고 했어.', `MaleText_loc4`='我听说，加尔鲁什要折磨那个魔古囚犯，除非他开口。', `MaleText_loc5`='我聽說，卡爾洛斯要拷問抓回來的那個魔古，直到他開口為止。', `MaleText_loc7`='Yo oye ke Garrosh va a torturar al prisionero mogu hasta ke hable.' WHERE `ID`=70518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 어쨌든, 저기로 가야해.', `MaleText_loc4`='不管怎样，你得做你该做的。', `MaleText_loc5`='反正，你走那邊。', `MaleText_loc7`='Tú va para allá.' WHERE `ID`=70519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 간섭할 일이 아니야!', `MaleText_loc4`='你不应该插手的。', `MaleText_loc5`='你不該插手干預的!', `MaleText_loc7`='¡No deberías haber interferido!', `FemaleText_loc1`='여긴 네가 있을 곳이 아니야!', `FemaleText_loc4`='你不属于这里！', `FemaleText_loc5`='你不屬於這裡!', `FemaleText_loc7`='¡No tienes nada que hacer aquí!' WHERE `ID`=70520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라도 찾아내면 나한테도 얘기해 줘, 친구!', `MaleText_loc4`='要是你找到什么东西，一定要告诉我，伙计！', `MaleText_loc5`='你要是發現什麼，記得告訴我，老兄。', `MaleText_loc7`='¡Tú avisa si enkuentra algo!' WHERE `ID`=70521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있잖아, 야영지 여기저기서 네 이름을 얘기하고 있어!', `MaleText_loc4`='你知道吗，营地里的人都在谈论你。', `MaleText_loc5`='你知道嗎，你的名字已經傳遍了整個營地!', `MaleText_loc7`='¿Tú sabe? ¡Dicen tu nombre por todo el kampamento!' WHERE `ID`=70522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 나, 탁탁은 네 친구라고! 으햐!', `MaleText_loc4`='还有我，泰克泰克，我是你的好朋友！赞！', `MaleText_loc5`='而我，塔克-塔克是你的朋友!讚啦!', `MaleText_loc7`='¡Y Tak-Tak es tu amigo! ¡Guau!' WHERE `ID`=70523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 야영지는 시끌시끌해. 다들 일해.', `MaleText_loc4`='部落营地热火朝天，每个人都在干活。', `MaleText_loc5`='部落很忙!大家都在幹活。', `MaleText_loc7`='La Horda del kampamento no para. Todo el mundo kurra.' WHERE `ID`=70524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 샨 키엔의 기억을 봤을 때부터 지금까지 정찰대를 수도 없이 내보냈대.', `MaleText_loc4`='既然你阅读了单简的记忆，他们一定会派出侦察队。', `MaleText_loc5`='從你看到衫·基恩的記憶開始，他們派出了許多搜查隊。', `MaleText_loc7`='Desde ke tú vio rekuerdo de Shan Kien, han estado enviando exploradores.' WHERE `ID`=70525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 드디어 모구가 그 종을 숨긴 곳을 발견했나봐.', `MaleText_loc4`='好像他们现在已经知道魔古族把那口钟藏在哪里了。', `MaleText_loc5`='看來，他們已經找到魔古藏鐘的地點了。', `MaleText_loc7`='Parece ke han encontrado el eskondite de la kampana.' WHERE `ID`=70526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='행운을 빌어. 네가 그 종을 찾으면 좋겠어.', `MaleText_loc4`='祝你好运。我希望你能够找到那口钟。', `MaleText_loc5`='祝你好運，希望你找到那個鐘。', `MaleText_loc7`='Buena suerte. Ojalá tú enkuentre esa kampana.' WHERE `ID`=70527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 다르나서스까지는 연을 타고 못 가, 우낏. 나 거기가 어딘지도 몰라! 저기 차원문인가 뭔가를 이용해.', `MaleText_loc4`='我可不会乘着风筝去达纳苏斯，无毛怪。我都不知道那地方在哪儿！用那儿的传送门吧。', `MaleText_loc5`='我才不要飛去達納蘇斯，怪怪人。我根本不知道它在哪!去用那邊的傳送門。', `MaleText_loc7`='Yo no manda kometa a Darnassus, makaku. ¡Yo no sabe dónde está eso! ¡Koge ese portal de ahí!' WHERE `ID`=70528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 달라란이 어디 있는지 아는 것 같아? 내 꼬리가 어디 있는지도 모르는 걸! 어떨 때 보면 있고, 또 어떨 때 보면 없거든.$B$B$n, 그런데 내가 무슨 이야기 들었는지 알아?$B$B응가쟁이들이 지난 일 이후로 정말 장난이 아니더라고.$B$B네가 다르나서스로 가서 신성한 종을 얻었다는 이야기는 들었어.$B$B그런데 어떤 인간 여자... 자나라던가 제이나라던가가 완전히 정신이 나갔어!$B$B호드가 자기 믿음인가 뭔가를 배신했다고 하더라고... 그리고 네 동족들을 모두 달라란에서 내쫓고 있어!$B$B오크 장군 나즈그림이 그러던데, 우리가 걔네들을 대접... 아니 대... 아, 뭐더라? 에잇... 하여튼 우낏 꺼내와야 한대!', `MaleText_loc4`='你觉得我知道达拉然在哪，$G伙计:姑娘;？我连自己的尾巴都不知道在哪儿！有时候找得到它，有时候找不到。$B$B但是你知道我听说了什么吗，$n？$B$B我听到的都是真的。$B$B我听说你去了趟达纳苏斯，拿到了那口圣钟。$B$B但是那个人类女人……吉娜什么的……她被气疯了！$B$B她说部落背叛了她的信任，还说什么要把你们的人民赶出她的城市！$B$B兽人将军纳兹戈林说，我们必须帮助他们撤……撤走……撤退……撤离……呃……反正就是带他们离开！', `MaleText_loc5`='你以為我知道達納蘇斯在哪嗎，$G老兄:小姐;?我連自己的尾巴在哪都搞不清楚!有時候它在這，有時候它又不在這。$B$B你聽說了嗎，$n?$B$B這次事情大條了。$B$B我聽說你跑去達納蘇斯拿到了聖鐘。$B$B但是有個女人...叫什麼珍娜來著的...她竟然抓狂了!$B$B她說因為部落背叛了她還是怎樣的...所以她要把你們的人全都趕出她的城市!$B$B獸人將軍納茲格寧姆叫我們幫忙車退...退車...呃...倒車...呃...把人都撤出來就對了!', `MaleText_loc7`='¿Tú kree que yo sabe dónde está Dalaran, makaku? ¡Yo no enkuentra mi propia kola! A veces está ahí, otras veces no.$b$b¿Tú sabe lo ke yo ha oído, $n?$b$b¡Ké fuerte lo ke ha pasado!$b$bYo oye ke tú va a Darnassus y koge la kampana divina.$b$bPero una humana, Jana o algo así, ¡se enfada mucho!$b$bDice que la Horda la traiciona, o algo así... ¡y ha echado a tu gente de su ciudad!$b$bGeneral orko Nazgrim dice ke nosotros tiene ke ayudarles a abogar... evokar... evaluar... eh... ¡salir korriendo!' WHERE `ID`=70529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='응가쟁이들이 지난 일 이후로 정말 장난이 아니더라고.', `MaleText_loc4`='我听到的都是真的。', `MaleText_loc5`='這次事情大條了。', `MaleText_loc7`='¡Ké fuerte lo ke ha pasado!' WHERE `ID`=70530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 다르나서스로 가서 천상의 종을 얻었다는 얘기는 들었어.', `MaleText_loc4`='我听说你去了趟达纳苏斯，拿到了那口圣钟。', `MaleText_loc5`='我聽說你跑去達納蘇斯拿到了聖鐘。', `MaleText_loc7`='Yo oye ke tú va a Darnassus y koge la kampana divina.' WHERE `ID`=70531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 어떤 인간 여자... 자나라던가 제이나라던가가 완전히 정신이 나갔어!', `MaleText_loc4`='但是那个人类女人……吉娜什么的……她被气疯了！', `MaleText_loc5`='但是有個女人...叫什麼珍娜來著的...她竟然抓狂了!', `MaleText_loc7`='Pero una humana, Jana o algo así, ¡se enfada mucho!' WHERE `ID`=70532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 어떤 인간 여자... 자나라던가 제이나라던가가 완전히 정신이 나갔어!', `MaleText_loc4`='但是那个人类女人……吉娜什么的……她被气疯了！', `MaleText_loc5`='但是有個女人...叫什麼珍娜來著的...她竟然抓狂了!', `MaleText_loc7`='Pero una humana, Jana o algo así, ¡se enfada mucho!' WHERE `ID`=70533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크 장군 나즈그림이 그러던데, 우리가 걔네들을 대접... 아니 대... 아, 뭐더라? 에잇... 하여튼 우낏 꺼내와야 한대!', `MaleText_loc4`='兽人将军纳兹戈林说，我们必须帮助他们撤……撤走……撤退……撤离……呃……反正就是带他们走！', `MaleText_loc5`='獸人將軍納茲格寧姆叫我們幫忙車退...退車...呃...倒車...呃...把人都撤出來就對了!', `MaleText_loc7`='General orko Nazgrim dice ke nosotros tiene ke ayudarles a abogar... evokar... evaluar... eh... ¡salir korriendo!' WHERE `ID`=70534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지 않은 느낌이 들어.', `MaleText_loc4`='我对这事儿感觉很不好。', `MaleText_loc5`='這次我有不好的預感。', `MaleText_loc7`='Yo tiene un mal presentimiento sobre esto.' WHERE `ID`=70535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 대족장이 그 종 가져갔어. 그걸로 호드를 강하게 만들겠대.', `MaleText_loc4`='你们的酋长得到了那口钟，然后用它来使得部落变得更加强大。', `MaleText_loc5`='你們的大酋長拿到了聖鐘，他會用它來讓部落變得更強大。', `MaleText_loc7`='Tu Jefe de Guerra tiene la kampana y la va a usar para hacer más fuerte a la Horda.' WHERE `ID`=70536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 난 그 종이 너무 강력하다고 생각해... 그리고 뭔가 기분 나빠.', `MaleText_loc4`='但我觉得那口钟有股力量……不好的力量。', `MaleText_loc5`='但是我覺得那個鐘有某種力量...不好的力量。', `MaleText_loc7`='Pero yo kree ke la kampana tiene poder... poder malo.' WHERE `ID`=70537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 응가에서 궁둥이가 우낏할 정도라니까!', `MaleText_loc4`='它让我有种说不出的难受！', `MaleText_loc5`='它讓我想挫便便!', `MaleText_loc7`='¡Me da eskalofríos!' WHERE `ID`=70538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도, 호젠이든 인간이든 오크든... 샤를 사용하면 안 돼.', `MaleText_loc4`='没有人，没有猢狲，没有人类，没有兽人……可以利用煞能。', `MaleText_loc5`='不管是猴人、人類或者獸人，還是任何人...都不應該使用煞的力量。', `MaleText_loc7`='Nadie debe usar sha: ni hozen, ni humano, ni orko.' WHERE `ID`=70539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='익크가 이 땅에 올거야.', `MaleText_loc4`='伊克会把这片土地弄坏的。', `MaleText_loc5`='我們快到了。', `MaleText_loc7`='Va a venir ikk.' WHERE `ID`=70540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해.', `MaleText_loc4`='小心点。', `MaleText_loc5`='小心點。', `MaleText_loc7`='Ten kuidado.' WHERE `ID`=70541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무사히 살아서 다시 만나, 친구.', `MaleText_loc4`='我希望能再见到你，朋友。', `MaleText_loc5`='希望我們還能再見面，朋友。', `MaleText_loc7`='Yo espera volver a verte, kolega.' WHERE `ID`=70542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 바다 밑에서 우리 배들을 공격했습니다. 머지않아 요새에까지 들이닥칠지도 몰라요!

하지만 우리는 수가 너무 적습니다...', `MaleText_loc4`='他们从下方攻击我们的舰船，随时都有可能抢先占据要塞！

我们没有足够的兵力去阻止他们……', `MaleText_loc5`='他們從下方攻擊我們的船，而且隨時都會向我們的要塞展開進攻!

光憑我們的人力是無法阻止他們的...', `MaleText_loc7`='Atacaron nuestros barcos desde abajo. ¡Avanzarán hacia el fuerte en cualquier momento!

No somos suficientes para detenerlos.' WHERE `ID`=70543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(제독 테일러가 당신과 합류합니다.)|r', `MaleText_loc4`='加入我们吧。|cFF0008E8（泰勒上将会跟随你。）|r', `MaleText_loc5`='跟我們並肩作戰。|cFF0008E8(泰勒上將會跟隨你)|r', `MaleText_loc7`='Lucha con nosotros. |cFF0008E8(El almirante Taylor te seguirá.)|r', `FemaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(제독 테일러가 당신과 합류합니다.)|r', `FemaleText_loc4`='加入我们吧。|cFF0008E8（泰勒上将会跟随你。）|r', `FemaleText_loc5`='跟我們並肩作戰。|cFF0008E8(泰勒上將會跟隨你)|r', `FemaleText_loc7`='Lucha con nosotros. |cFF0008E8(El almirante Taylor te seguirá.)|r' WHERE `ID`=70544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 죽는 한이 있더라도 사자의 상륙지를 사수할 겁니다!', `MaleText_loc4`='我们将誓死守卫雄师港！', `MaleText_loc5`='就算要死，我們也要守住雄獅灘!', `MaleText_loc7`='¡Defenderemos el Desembarco del León o moriremos en el intento!' WHERE `ID`=70545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 짓이냐?', `MaleText_loc4`='你知道自己在干什么吗？', `MaleText_loc5`='你在做什麼?', `MaleText_loc7`='¿Qué te crees que estás haciendo?', `FemaleText_loc1`='거기 꼼짝 마라!', `FemaleText_loc4`='住手！', `FemaleText_loc5`='給我站住!', `FemaleText_loc7`='¡No des un paso más!' WHERE `ID`=70546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라!', `MaleText_loc4`='站住！', `MaleText_loc5`='站住!', `MaleText_loc7`='¡Alto!', `FemaleText_loc1`='쓸데없이 참견하지 마!', `FemaleText_loc4`='你太多管闲事了！', `FemaleText_loc5`='別再多管閒事了!', `FemaleText_loc7`='¡Ya has interferido bastante!' WHERE `ID`=70547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라!', `MaleText_loc4`='安静受死吧！', `MaleText_loc5`='安靜!', `MaleText_loc7`='¡Silencio!', `FemaleText_loc1`='넌 빠져 있어!', `FemaleText_loc4`='别插手这事！', `FemaleText_loc5`='不干你的事!', `FemaleText_loc7`='¡No te metas en esto!' WHERE `ID`=70548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주제를 모르는 건가?', `MaleText_loc4`='你以为自己是谁？', `MaleText_loc5`='你以為你是誰?', `MaleText_loc7`='¿Quién te crees que eres TÚ?', `FemaleText_loc1`='아주 친절하구나... 이젠 죽어라!', `FemaleText_loc4`='干得不错啊——受死吧！', `FemaleText_loc5`='太貼心了 - 受死吧你!', `FemaleText_loc7`='Muy gracioso. ¡Ahora MUERE!' WHERE `ID`=70549;
