UPDATE `locales_broadcast_text` SET `MaleText_loc1`='간섭하는 자는 용서치 않을 것이다!', `MaleText_loc4`='我们绝不容许你横加干预！', `MaleText_loc5`='絕不容許插手干預!', `MaleText_loc7`='¡No toleraremos ninguna interferencia!', `FemaleText_loc1`='너도 당하고 싶어? 좋아!', `FemaleText_loc4`='你也想来尝尝苦头？很好！', `FemaleText_loc5`='你也想試試厲害嗎?好!', `FemaleText_loc7`='¿Tú también quieres? ¡Muy bien!' WHERE `ID`=70551;
