UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n, 신속히 움직이시오. 하지만 신중해야 하오. 아무리 급해도 그대가 죽으면 이 임무는 끝장이오.', `MaleText_loc4`='抓紧时间，$n，但你仍要万分小心。虽然时间紧迫，但是如果你死了，这个任务也就失败了。', `MaleText_loc5`='動作快，但是請小心，$n。雖然我們時間不多，但你一死我們的任務也就失敗了。', `MaleText_loc7`='Date prisa, pero con cuidado, $n. No tenemos mucho tiempo, pero si tú mueres, toda la misión muere contigo.' WHERE `ID`=70555;
