UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제의 세력지로 데려다 주세요.', `MaleText_loc4`='带我去帝皇之域。', `MaleText_loc5`='帶我去帝王之境。', `MaleText_loc7`='Llévame al Tramo del Emperador.', `FemaleText_loc1`='황제의 세력지로 데려다 주세요.', `FemaleText_loc4`='带我去帝皇之域。', `FemaleText_loc5`='帶我去帝王之境。', `FemaleText_loc7`='Llévame al Tramo del Emperador.' WHERE `ID`=70574;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='엄마야! 아, 제가 오늘 좀 정신이 없어서요. 지금 손대고 있는 일이 너무 많거든요!', `FemaleText_loc4`='哎呦！今天我真是激动死了。就刚才我从那堆火里炼了八块铁。', `FemaleText_loc5`='噢!我今天的狀況真是太棒了。一下子就搞定了八十份鐵礦!', `FemaleText_loc7`='¡Uf! Hoy estamos que no paramos. ¡Debo de tener unos ochenta hierros en el fuego!' WHERE `ID`=70575;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='힐다 언니가 문서 작업을 전부 저한테 맡겨 놓고 떠났어요. 누가 유물 하나를 찾으면 제가 서류를 여섯 개나 만들어야 한답니다! 전 "대체 이 서류들이 왜 필요한 거야?!"라고 외치곤 하죠.', `FemaleText_loc4`='希尔达把所有的文件都给我了。你知道吗，我们每找到一个神器，我就要填六份表格！我想知道，这些该死的文件到底有什么用！？', `FemaleText_loc5`='希爾達把建檔的工作全都丟給了我。你知道每挖到一件文物，我就得填寫六份表格嗎?我們到底要這麼多表格做什麼!?', `FemaleText_loc7`='Hilda me ha dejado a cargo de toda la documentación. ¿Sabías que por cada artefacto que encontramos tengo que rellenar seis formularios? ¡¿Pero para qué hacen falta tantos formularios?!' WHERE `ID`=70576;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 그래도 바빠 죽겠는데, 저기 광산에서 일하는 드워프들이 카파라는 새 음료에 미쳐서 어찌나 절 귀찮게 하는지 몰라요.$B$B글쎄 저더러 아침마다 신선한 카파 음료를 달라지 뭐예요!$B$B그 카파를 조달하느라 제가 어떤 일을 해야 하는지 알기나 하는 걸까요? 아유, 정말!', `FemaleText_loc4`='好像嫌我手头的麻烦事儿还不够多似的，那帮矿洞里的矮人最近迷上了一种叫咔啡的新饮料。$B$B他们一定要让我每天早上给他们带去新鲜的咔啡！$B$B他们知道我应该上哪儿去弄那些咔啡豆吗？行行好吧！', `FemaleText_loc5`='我的事情都快忙不過來了，誰知道那些挖礦的矮人最近迷上了一種叫做卡法的飲料。$B$B他們堅持要我每天早上幫他們準備新鮮的卡法!$B$B他們知道卡法豆究竟是怎麼弄出來的嗎?我是說真的!', `FemaleText_loc7`='Como si no tuviera suficiente trabajo, esos enanos de la minas se han vuelto locos por una especie de bebida nueva que llaman kafa.$b$b¡Insisten en que les lleve tazas de kafa recién hecho todas las mañanas!$b$b¿Tienen idea de lo que tengo que hacer para reunir granos de kafa? En serio...' WHERE `ID`=70577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='네, 산더미 같은 행정 업무에 빠져서 허덕이고 있죠. 당신은 뭐 새 소식 있나요?', `FemaleText_loc4`='我在执行行政管理的时候得穿上漂亮的短裤，但是其他的呢？能来点儿有新意的吗？', `FemaleText_loc5`='我的新管理職務搞得我焦頭爛額。有什麼新消息嗎?', `FemaleText_loc7`='Estoy hasta las cejas de trabajo ad-mina-istrativo, pero eso no es ninguna novedad.' WHERE `ID`=70578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오, 맙소사. 당신이 바로 모두가 이야기하는 그 영웅인 것 같군요.', `FemaleText_loc4`='哦天呐，是你吗？你一定就是那个每个人都在谈论的英雄。', `FemaleText_loc5`='老天，你一定就是大家口中的那位英雄。', `FemaleText_loc7`='¡Vaya, vaya! Tú debes de ser $gel héroe del:la heroína de la; que habla todo el mundo.' WHERE `ID`=70579;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에, 이거 어떻게 써먹는 거지? 에잇, 빛의 이름으로! 날아가라고, 이 망할 잡동사니 같으니!', `FemaleText_loc4`='喔，在这种东西上飞行，你们是怎么做到的？圣光在上！你们这小手艺可太拉风了！', `FemaleText_loc5`='哎哎，你怎麼能駕駛這種鬼東西?聖光在上!你這個破爛玩意兒，發動!', `FemaleText_loc7`='¡Ay! ¿Cómo se vuelan estos trastos? ¡Por la Luz! ¡FUNCIONA, pedazo de chatarra!' WHERE `ID`=70580;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요. 아직 적응을 더 해야겠네요.', `FemaleText_loc4`='抱歉，我在这儿还有点事情要做。', `FemaleText_loc5`='不好意思，我還在熟悉這裡的一切。', `FemaleText_loc7`='Perdona, todavía le estoy cogiendo el tranquillo a esto.' WHERE `ID`=70581;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 언니인 힐다가 당신이 올거라했죠.', `FemaleText_loc4`='我姐姐希尔达告诉我你会来。', `FemaleText_loc5`='我姐姐希爾達要我在這裡等你。', `FemaleText_loc7`='Mi hermana mayor, Hilda, me dijo que vendrías.' WHERE `ID`=70582;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언니는 제가 땅을 파는걸 원치 않았어요. 그래서 전 지원이나 운송 등을 담당하고 있죠.', `FemaleText_loc4`='她不让我下挖掘场，所以我就成了私人助理和司机。', `FemaleText_loc5`='她絕不會讓我進入挖掘場，因此我只好擔任私人助理與司機的工作。', `FemaleText_loc7`='No me deja bajar a la excavación, así que ahora mismo soy una especie de asistente personal y chófer.' WHERE `ID`=70583;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든, 당신이 데리고 온 그 은퇴했다가 재임한 SI:7 요원이랑 만났어요.', `FemaleText_loc4`='不管怎样，我遇到了那个退役的军情七处特工。', `FemaleText_loc5`='總之，我見過那個退休的軍情七處情報員。', `FemaleText_loc7`='En fin. Encontré a ese agente del IV:7 que sacaste de la jubilación.' WHERE `ID`=70584;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='요원 코넬리였던가요? 그 남자 참 매력이 넘치더군요... 거기다가 말도 잘해요! 그 사람이 한마디 할 때마다 얼마나 설레던지 아이언포지 밖으로 날아갈 뻔 했어요!', `FemaleText_loc4`='特工康奈利，对不？那个男的很有魅力……还很有胆量！他的甜言蜜语让我的脸羞得比铁炉堡的铁砧还红！', `FemaleText_loc5`='情報員康奈利，對吧?那個男人很有幾分魅力...與膽識!即使離開鐵爐堡後，每次想起他的甜言蜜語我還是常常會感到害臊!', `FemaleText_loc7`='Se llama agente Connelly, ¿no? Es un hombre con encanto... ¡y con descaro! ¡Al oír las cosas que me decía me puse más roja que las barbas de un Barbabronce!' WHERE `ID`=70585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제는 전장에 투입됐죠. 당신을 기다리고 있어요.', `FemaleText_loc4`='他现在正在任务现场等着你。', `FemaleText_loc5`='他已經去挖掘場了，而且正在等著你。', `FemaleText_loc7`='Ahora está en el campo, esperándote.' WHERE `ID`=70586;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 야영지 주변에 당신을 내려줄 거예요. 정신 바짝 차리세요.', `FemaleText_loc4`='不过我们的目的地离一个部落营地很近，所以你一定要多加小心。', `FemaleText_loc5`='我會把你載到部落的營地附近，所以最好先做好準備。', `FemaleText_loc7`='Pero te estoy acercando al campamento de la Horda, así que mejor ten cuidado.' WHERE `ID`=70587;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코넬리에게 페니가 안부 물었다고 전해주세요!', `FemaleText_loc4`='代范妮向康奈利问好！', `FemaleText_loc5`='幫我跟康奈利說芬妮很想他!', `FemaleText_loc7`='¡Dile a Connelly que Fennie ha preguntado por él!' WHERE `ID`=70588;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란에 가려고요? 여군주 제이나 프라우드무어 님께서 당신을 기다리고 계시다는군요! 길을 따라 내려가면 나오는 차원문을 이용하세요.', `FemaleText_loc4`='你想要去达拉然？我听说吉安娜·普罗德摩尔正想见你！这条路直走，穿过那个法师传送门吧。', `FemaleText_loc5`='你想去達拉然嗎?聽說珍娜·普勞德摩爾女士正在等著你!順著路走下去，從那裡的法師傳送門過去吧。', `FemaleText_loc7`='¿Quieres ir a Dalaran? ¡He oído que Lady Jaina Valiente en persona te espera! Coge el portal de mago que hay siguiendo el camino.' WHERE `ID`=70589;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만났군요.', `FemaleText_loc4`='好吧，我们又见面了。', `FemaleText_loc5`='哎呀，我們又見面了。', `FemaleText_loc7`='Nos volvemos a encontrar.' WHERE `ID`=70590;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 지내고 계셨겠죠?', `FemaleText_loc4`='我想你过得还不错？', `FemaleText_loc5`='我想你過的不錯吧?', `FemaleText_loc7`='¡Espero que todo te vaya bien!' WHERE `ID`=70591;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사자의 상륙지에 파다하게 퍼진 이야기 들으셨나요?', `FemaleText_loc4`='你听说雄师港最近闹得沸沸扬扬的传闻了吗？', `FemaleText_loc5`='你有聽說雄獅灘附近發生的事情了嗎?', `FemaleText_loc7`='¿Has oído los rumores que circulan por el Desembarco del León?' WHERE `ID`=70592;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 어떤 모구 유물에 대해서 알아냈대요... 천상의 종이라는 유물이요.', `FemaleText_loc4`='听说部落掌握某种远古魔古族神器的信息……一个名叫圣钟的东西。', `FemaleText_loc5`='我聽說部落獲知了一個遠古魔古神器...一個叫做聖鐘的東西。', `FemaleText_loc7`='He oído que la Horda está buscando un antiguo artefacto mogu, la Campana divina.' WHERE `ID`=70593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 글쎄, 평범한 군대를 피에 굶주린 살인 기계로 바꾸는 유물이라던데요!', `FemaleText_loc4`='那口钟能够把普通的军队变成杀戮机器！', `FemaleText_loc5`='那個鐘能夠讓普通的軍隊變身成殺戮機器!', `FemaleText_loc7`='¡Esa campana tiene el poder de convertir un ejército normal en una máquina de matar!' WHERE `ID`=70594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 유물이 어디 숨겨져 있는진 몰라도, 호드는 그걸 손에 넣으려고 안간힘을 쓰고 있다더군요.', `FemaleText_loc4`='没人知道那个神器被藏在哪里，但是部落正在动用一切力量，想要先下手为强。', `FemaleText_loc5`='沒有人知道那個神器被藏在哪裡，部落現在正傾盡全力想要最先找到它。', `FemaleText_loc7`='Nadie sabe dónde escondieron el artefacto, pero la Horda hace todo lo posible para ser la primera en encontrarlo.' WHERE `ID`=70595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성물회가 모구지아에서 그 종을 찾을 단서를 발견하고 추적 중이래요.', `FemaleText_loc4`='神圣遗物学会正在魔古岬努力搜寻这口钟的下落。', `FemaleText_loc5`='聖匣守護者正在魔古岬找尋那座鐘。', `FemaleText_loc7`='El Relicario está buscando la campana en Mogujia.' WHERE `ID`=70596;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 우리가 먼저 종을 손에 넣는다는 데 제 목을 걸겠어요!', `FemaleText_loc4`='我们可不是没用的笨蛋，一定要打败他们！', `FemaleText_loc5`='我們要是沒能搶先一步找到，臉就丟光囉!', `FemaleText_loc7`='¡Que me aspen si vamos a dejar que se nos adelanten!' WHERE `ID`=70597;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 힐다 언니의 조수일 뿐이니 나설 수가 없지만, 당신은 다르죠. 성물회 놈들이 뭘 조사하고 있는지 알아내 주실 거죠?', `FemaleText_loc4`='我只是希尔达的助理，能力有限。但是你能做的有很多。希望你能发现他们的动向。', `FemaleText_loc5`='因為我只是希爾達的助手，所以我幫不上忙。不過你可以幫上忙。我希望你能找出他們的企圖是什麼。', `FemaleText_loc7`='Yo no puedo hacer mucho, porque solo soy la ayudante de Hilda, pero tú sí puedes. Espero que descubras qué están tramando.' WHERE `ID`=70598;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 왔군요.', `FemaleText_loc4`='我们到了。', `FemaleText_loc5`='我們到了。', `FemaleText_loc7`='Aquí estamos.' WHERE `ID`=70599;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드 놈들을 혼쭐내 주세요!', `FemaleText_loc4`='好好教训那些部落！', `FemaleText_loc5`='去殺爆那些部落傢伙!', `FemaleText_loc7`='¡Dale una paliza a la Horda!' WHERE `ID`=70600;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신을 일곱 별의 제단으로 모셔다 드려야 해요.', `FemaleText_loc4`='我将要把你送往七星殿。', `FemaleText_loc5`='我要帶你去七星廟。', `FemaleText_loc7`='Me han dicho que te lleve al Santuario de las Siete Estrellas.' WHERE `ID`=70601;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 귀여운 안두인 왕자님께서 당신 소식을 물으시던데요.', `FemaleText_loc4`='年轻的安度因王子正在等你。', `FemaleText_loc5`='安杜因王子一直在打聽你的消息。', `FemaleText_loc7`='El joven príncipe Anduin ha preguntado por ti.' WHERE `ID`=70602;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구지아에서 발굴 작업을 마친 탐험가 연맹이 그곳에서 발견한 것을 영원꽃 골짜기의 우리 요새로 가져왔더라고요.', `FemaleText_loc4`='探险者协会在魔古岬完成勘探任务之后，他们把发掘出来的东西都带回了锦绣谷的城市里。', `FemaleText_loc5`='魔古岬的挖掘工作結束之後，探險者協會把挖到的東西帶回了我們位於恆春谷的城市裡。', `FemaleText_loc7`='Después del viaje a la excavación de Mogujia, la Liga de Expedicionarios trajo sus descubrimientos a nuestra ciudad en el Valle de la Flor Eterna.' WHERE `ID`=70603;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연맹은 블러드 엘프들이 훔쳐내고 있던 유물을 지금 연구하고 있어요.', `FemaleText_loc4`='他们正在研究那些被血精灵偷走的古物。', `FemaleText_loc5`='之後他們便一直研究那些血精靈想偷走的聖物。', `FemaleText_loc7`='Han estado estudiando las reliquias que robaron los elfos de sangre.' WHERE `ID`=70604;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='원래 이번 일에 대해 당신에게 아무 말도 해서는 안 되지만... 그렇게 화끈한 드워프제 스타우트 맥주가 필요한 얼굴을 하고 계시니, 저도 당신을 믿고 말씀드린 거예요.', `FemaleText_loc4`='本来这事儿我不应该告诉任何人的，但是你的脸长得就像矮人酒桶这么可爱，一定是个好人，所以我相信你！', `FemaleText_loc5`='我本來不該告訴你的，但是你有張寫著「我是好矮人」的臉，所以我相信你!', `FemaleText_loc7`='No debería contarte nada de esto, pero tienes cara de que te gusta la cerveza negra enana, ¡así que confío en ti!' WHERE `ID`=70605;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 모구들은 코룬이라 불리는 부족의 일원이라고 하더라고요.', `FemaleText_loc4`='那些魔古族属于一个叫做寇茹的部族。', `FemaleText_loc5`='那些魔古是屬於一支叫做「考倫」的部族。', `FemaleText_loc7`='Los mogu pertenecen a una tribu llamada Korune.' WHERE `ID`=70606;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금까지의 일을 보면, 코룬은 천둥왕에 충성을 맹세했었나 봐요. 수천 년 전... 판다렌이 이 땅을 지배하기 전에요.', `FemaleText_loc4`='寇茹部族好像在数千年以前就效忠于雷电之王……比熊猫人统治这片土地更早。', `FemaleText_loc5`='根據研究，考倫部族在數千年前就效忠於雷王...遠在熊貓人統治這片大陸之前。', `FemaleText_loc7`='Parece que los Korune eran leales al Rey del Trueno, hace miles de años, antes incluso de que los pandaren gobernaran el continente.' WHERE `ID`=70607;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 음지에서 일했는데, 어떻게 해서인가... 샤를 지배하는 데 성공했대요.', `FemaleText_loc4`='他们钻研暗影法术，然后……通过某种方法，他们开始能够控制煞能。', `FemaleText_loc5`='他們運用黑暗的力量，而完成了...總之，他們找到操控煞的方法。', `FemaleText_loc7`='Trabajaban desde las sombras, y no te lo pierdas: consiguieron dominar a los sha.' WHERE `ID`=70608;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코룬이 그런 일을 할 수 있었다면, 가로쉬가 그들의 지식을 뒤쫓고 있다는 것도 놀랄 일이 아니죠!', `FemaleText_loc4`='如果寇茹部族真的拥有这种能力，那就不难设想加尔鲁什为何要获得他们的知识了！', `FemaleText_loc5`='如果考倫部族真的辦到了，那卡爾洛斯想獲得他們的知識就一點都不令人意外了。', `FemaleText_loc7`='Si los Korune son capaces de algo así, ¡no me extraña que Garrosh ansíe sus conocimientos!' WHERE `ID`=70609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머리 모양도 우스꽝스러운 그 도끼 깡패가 샤를 굴복시킬 수 있다면 무슨 일이 벌어질지 생각해 보세요.', `FemaleText_loc4`='想象一下，那个凶狠难缠的加尔鲁什在挥动他的大斧子的时候还能运用煞能，接下来会发生什么。', `FemaleText_loc5`='要是那個狡猾好戰的卡爾洛斯可以號令煞的話，誰知道會發生什麼事。', `FemaleText_loc7`='Imagínate lo que pasaría si ese mastodonte sediento de sangre de Garrosh pudiera manipular los sha a su antojo.' WHERE `ID`=70610;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='생각만 해도 온몸이 덜덜 떨리네요.', `FemaleText_loc4`='我想到就会发抖。', `FemaleText_loc5`='想到這就讓我不寒而慄。', `FemaleText_loc7`='Siento escalofríos solo de pensarlo.' WHERE `ID`=70611;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 왔네요. 행운을 빌어요!', `FemaleText_loc4`='你已经到了。祝你好运！', `FemaleText_loc5`='好了。祝你好運!', `FemaleText_loc7`='Ya está. ¡Buena suerte!' WHERE `ID`=70612;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래, 오늘은 기분이 어떠세요?', `FemaleText_loc4`='你好，今天过得怎样？', `FemaleText_loc5`='嗨。你好嗎?', `FemaleText_loc7`='Buenas. ¿Qué tal te va?' WHERE `ID`=70613;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지난번에 모셔다 드리고 나서 들은 얘긴데, 일곱 별의 제단에서 우리 병사들이 샤에 감염됐었다면서요?', `FemaleText_loc4`='自从上次我把你送到之后，我听说一些在七星殿的士兵们被煞能感染了。', `FemaleText_loc5`='自從上次一別之後，我聽說我們在七星廟的士兵受到了煞的影響。', `FemaleText_loc7`='Después de dejarte la última vez, oí que un tipo de sha había infectado a nuestros soldados en el Santuario de las Siete Estrellas.' WHERE `ID`=70614;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신과 안두인 왕자님이 없었다면 우리 모두 서로에게 칼을 들이대고, 자신의 공포 앞에 무릎 꿇었겠죠!', `FemaleText_loc4`='如果你和安度因王子不在那儿的话，他们可能就会自相残杀，我们最好的战士们可能就会被他们自己的愤怒击败！', `FemaleText_loc5`='要不是你跟安杜因王子，我們很可能會起內鬨，讓憤怒蒙蔽了我們的理智。', `FemaleText_loc7`='Si el príncipe Anduin y tú no hubieseis estado allí, podríamos haber acabado luchando unos contra otros, ¡dejando que la ira nos controlara!' WHERE `ID`=70615;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 바리안 폐하께서 이 샤라는 걸 어떤 목적으로든 이용하지 않겠다고 맹세하셨단 얘기도 들었어요.', `FemaleText_loc4`='我还听说，瓦里安国王发誓不会利用煞能做不光彩的事。', `FemaleText_loc5`='我也聽說了瓦里安·烏瑞恩國王發誓絕不會濫用煞的力量。', `FemaleText_loc7`='También he oído que el rey Varian juró que jamás usaría el poder de los sha.' WHERE `ID`=70616;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바리안 폐하가 생각처럼 오기만 잔뜩 있는 분은 아니었던 거죠! 우리 왕이 선한 마음을 갖고 있다는 걸 아니 기분이 좋군요.', `FemaleText_loc4`='但愿他不是因为没吃到葡萄就说葡萄是酸的！我们的国王能有这样的表态就很不错啦。', `FemaleText_loc5`='看來瓦里安的心胸一點都不狹隘!我們的國王還真是個好人。', `FemaleText_loc7`='¡A lo mejor Varian no es tan agresivo como dicen! Me alegro de que nuestro Rey muestre carácter.' WHERE `ID`=70617;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그건 그렇고, 코넬리 요원이 당신을 쿤라이 봉우리로 데려다 달라고 전갈을 보냈어요.', `FemaleText_loc4`='不管怎样，特工康奈利托口信让我送你到昆莱山去见他。', `FemaleText_loc5`='對了，情報員康奈利叫我帶你去崑萊峰找他。', `FemaleText_loc7`='Pero a lo que iba, el agente Connelly me ha pedido que te lleve a la Cima Kun-Lai, donde está él.' WHERE `ID`=70618;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천상의 종이 어디 있는지 호드가 곧 찾아낼 것 같은가 봐요. 물론 그런 일이 생겨선 안 되죠.', `FemaleText_loc4`='听上去部落就快要找到那口圣钟的地点了，那可不是什么好事。', `FemaleText_loc5`='聽說部落就快找到聖鐘的所在地點了，情況似乎不妙。', `FemaleText_loc7`='Parece que la Horda está a punto de descubrir la ubicación de la Campana divina, y eso no puede ser bueno.' WHERE `ID`=70619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그를 만나서 가로쉬가 무슨 일을 꾸미고 있는지 알아내시는 게 좋겠어요.', `FemaleText_loc4`='你最好在任务现场和他碰面，看看加尔鲁什在干什么。', `FemaleText_loc5`='你最好快去找他，看看卡爾洛斯採取了什麼行動。', `FemaleText_loc7`='Será mejor que te reúnas con él en el campo y averigüéis qué trama Garrosh.' WHERE `ID`=70620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌어요!', `FemaleText_loc4`='祝你好运！', `FemaleText_loc5`='祝你好運!', `FemaleText_loc7`='¡Buena suerte!' WHERE `ID`=70621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 연에 올라타세요!', `FemaleText_loc4`='快上风筝！', `FemaleText_loc5`='快跳上風箏!', `FemaleText_loc7`='¡Sube a la cometa, rápido!' WHERE `ID`=70622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 없어요.', `FemaleText_loc4`='我们没时间可以浪费了。', `FemaleText_loc5`='我們沒有時間了。', `FemaleText_loc7`='No hay tiempo que perder.' WHERE `ID`=70623;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 모구의 기억 속에서 본 것과 일치하는 장소를 찾아 쿤라이 봉우리 전체를 뒤졌어요. 그리고 마침내, 코룬의 은신처를 찾아냈죠.', `FemaleText_loc4`='为了找到你在那个魔古族记忆里看到的场景，我们找遍了昆莱山，最终，我们发现了那个隐蔽的寇茹部族处所。', `FemaleText_loc5`='為了尋找你在魔古記憶中看到的那個場所，我們找遍了整座崑萊峰，最後終於找到了考倫的藏匿地點。', `FemaleText_loc7`='Hemos peinado toda la Cima Kun-Lai en busca de un lugar que se parezca al que viste en el recuerdo de aquel mogu, y por fin hemos encontrado el escondite del Korune.' WHERE `ID`=70624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 천상의 종을 먼저 손에 넣지 않으면, 그 도마뱀 대가리 가로쉬가 차지할 거예요. 저 망할 샤의 힘을 마음대로 부리는 호드와는 별로 싸우고 싶지 않네요.', `FemaleText_loc4`='如果我们不能抢先得到那口圣钟，那个坏心眼的疯子加尔鲁什就会把它占为己有。我无法想象控制邪恶煞能的部落打起架来有多厉害。', `FemaleText_loc5`='要是我們不先找到聖鐘，那個殘暴瘋狂的卡爾洛斯就會搶走它。我可不想跟操控煞的部落交戰。', `FemaleText_loc7`='Si no conseguimos la Campana divina, ese cerebro de mosquito de Garrosh lo hará. Y no me apetece luchar contra una Horda que domina el poder de los sha.' WHERE `ID`=70625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스카이글레이브 사령관님은 이미 탐험가 연맹 고고학자들과 함께 발굴 지점에 도착하셨어요.', `FemaleText_loc4`='指挥官天剑已经在挖掘场和一小队探险者协会的考古学家开展工作了。', `FemaleText_loc5`='天刃指揮官已經跟一群探險者協會的考古學家在該地點開始挖掘了。', `FemaleText_loc7`='La comandante Gujaceleste ya está colaborando con un equipo de arqueólogos de la Liga de Expedicionarios en la excavación.' WHERE `ID`=70626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 최고의 요원이 거기로 가는 중이죠. 네, 당신 말이에요.', `FemaleText_loc4`='我们将派出精英部队，那也包括你。', `FemaleText_loc5`='我們要派出我們的菁英，也就是你。', `FemaleText_loc7`='Estamos enviando a nuestros mejores efectivos. Ahí entras tú.' WHERE `ID`=70627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 왔어요. 어서 가세요. 시간이 없다니까요.', `FemaleText_loc4`='我们到了。没时间可以浪费了。', `FemaleText_loc5`='我們到了，沒有時間耽擱了。', `FemaleText_loc7`='Ya estamos. No hay tiempo que perder.' WHERE `ID`=70628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌게요!', `FemaleText_loc4`='祝你好运！', `FemaleText_loc5`='祝你好運!', `FemaleText_loc7`='¡Buena suerte!' WHERE `ID`=70629;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='달라란까지 연을 타고 날아갈 수는 없어요! 게다가 제이나 님이 달라란을 어디로 옮기셨는지도 모른다고요! 저기 차원문을 이용하세요.', `FemaleText_loc4`='我可不会乘着风筝去达拉然！我都不知道吉安娜把那城市飘到哪儿了！你最好使用那边那个传送门。', `FemaleText_loc5`='我才不要飛去達拉然!我根本不知道珍娜把城市移到哪了!你只能使用那邊的傳送門。', `FemaleText_loc7`='¡No pienso volar una cometa hasta Dalaran! ¡Ni siquiera sé dónde ha aparcado Jaina la ciudad! Será mejor que cojas ese portal de ahí.' WHERE `ID`=70630;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다르나서스까지 연을 운전할 수는 없죠! 여기 산맥에서 비행하는 것도 힘겨운데, 대해를 건너갈 수 있으리라고 생각하는 건 아니시겠죠? 저기 셰이머스 골든킥스와 대화해 보시는 게 좋을 거예요.', `FemaleText_loc4`='我可不会乘着风筝去达纳苏斯！那东西要飞过山脉都很难，你还指望它飞过整片海域？你最好使用那边那个传送门。', `FemaleText_loc5`='我才不要飛去達納蘇斯!我的風箏連在山裡都飛不穩了，你覺得我們可以飛越大海嗎?你最好還是去問問那邊的西蒙斯·金躂。', `FemaleText_loc7`='¡Yo no voy a volar una cometa a Darnassus! Bastante me cuesta manejar ese trasto en las montañas. ¿Cuánto crees que duraríamos intentando atravesar un océano? Será mejor que hables con Seamus Marchafulgente, ahí al lado.' WHERE `ID`=70631;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어이. 테일러 제독께서 당신을 황제의 골짜기까지 데려다 주라고 하시더군요.', `FemaleText_loc4`='嘿，泰勒上将让我载你一程，把你送到帝皇谷。', `FemaleText_loc5`='嗨，泰勒上將叫我順道載你去帝王谷。', `FemaleText_loc7`='Oye, el almirante Taylor me ha pedido que te lleve al Valle de los Emperadores.' WHERE `ID`=70632;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다행히도, 전 안두인 왕자님의 총애를 받는 사람이에요. 아, 물론 친구 이상의 관계는 아니지만 코넬리 요원에겐 그 사실을 말하지 마세요.', `FemaleText_loc4`='你真幸运，我是安度因王子手下最能干的姑娘。我们是好朋友，但是可别把这告诉特工康奈利。', `FemaleText_loc5`='你的運氣真好，我可是安杜因王子的好夥伴。我們是好朋友，但是千萬別告訴情報員康奈利。', `FemaleText_loc7`='Por suerte para ti, soy la mano derecha del príncipe Anduin. Somos amigos, pero no se lo cuentes al agente Connelly.' WHERE `ID`=70633;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='질투가 나서 고귀한 자녀분께 폐를 끼치면 안되잖아요. 그렇죠?', `FemaleText_loc4`='那个男人肯定会非常嫉妒，而我可不想他为了我和王子闹矛盾。', `FemaleText_loc5`='他會吃醋的，我可不想他對咱們的王子開槍。', `FemaleText_loc7`='Seguro que se pone celoso, y no quiero que le pegue un tiro al heredero de la corona.' WHERE `ID`=70634;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어쨌든, 왕자님께서 어디 숨어 계신지 알고 있으니 거기로 데려다 드릴게요.', `FemaleText_loc4`='不管怎样，我知道王子躲藏在哪里，我会把你送到他那儿去的。', `FemaleText_loc5`='言歸正傳，我知道王子躲在哪，我就直接帶你過去吧。', `FemaleText_loc7`='En fin, sé dónde se oculta el príncipe, así que te llevaré a verlo.' WHERE `ID`=70635;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왕자님께서 혼자 돌아다니는걸 동의하는 건 아니지만 그분의 생각은 어느 정도 이해할 것 같아요.', `FemaleText_loc4`='虽然我不赞成让那个男孩子到处自个儿乱跑，但我能理解他的想法。', `FemaleText_loc5`='我雖然不贊同他自己一個人在外遊蕩，但是我想我能理解他的想法。', `FemaleText_loc7`='Debo decir que no me parece bien que el chico se pasee por ahí solo, pero entiendo sus razones.' WHERE `ID`=70636;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아직도 호드가 천상의 종을 훔쳐갔다는 게 믿기지가 않는군요. 그걸 다르나서스에 보관하기 위해 얼마나 많은 공을 들였는데.', `FemaleText_loc4`='我还是无法相信，我们在达纳苏斯做好了完全的准备，部落竟然还是偷走了圣钟。', `FemaleText_loc5`='我還是不敢相信我們在達納蘇斯設下了重重防護，部落竟然還是把聖鐘給偷走了。', `FemaleText_loc7`='Todavía no me puedo creer que la Horda robara la Campana divina, después de todo lo que nos esforzamos en protegerla en Darnassus.' WHERE `ID`=70637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 듣기로는 그 제이나 여군주님도 상당히 충격을 받으셨나 봐요.', `FemaleText_loc4`='听说吉安娜女士到现在还在对这事儿震惊不已。', `FemaleText_loc5`='我聽說珍娜女士至今還是對這件事震驚不已。', `FemaleText_loc7`='He oído que Lady Jaina aún está en estado de shock por lo ocurrido.' WHERE `ID`=70638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 님께서는 호드가 테라모어에 벌인 참사를 용서하려 하셨죠.', `FemaleText_loc4`='她已经准备好原谅部落在塞拉摩的所作所为。', `FemaleText_loc5`='她原本已經準備要原諒摧毀塞拉摩的部落。', `FemaleText_loc7`='Estaba a punto de perdonar a la Horda por la destrucción de Theramore.' WHERE `ID`=70639;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토를 위한 새로운 미래를 꿈꾸고 계셨어요. 호드의 편인 선리버와 얼라이언스의 동맹인 은빛 서약단을 아울러서 평화를 이끌어내려 하셨죠.', `FemaleText_loc4`='她已经准备好为肯瑞托创造一个崭新的未来，让部落的夺日者和联盟的银色盟约能够在一起和平共处。', `FemaleText_loc5`='她打算為祈倫托打造一個嶄新的未來，讓部落的奪日者和聯盟的白銀誓盟能夠和平共處。', `FemaleText_loc7`='Se preparaba para forjar un nuevo futuro para el Kirin Tor, un futuro en el que los Atracasol, aliados de la Horda, y el Pacto de Plata, aliados de la Alianza, colaborarían en paz.' WHERE `ID`=70640;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그분의 말씀을 직접 들었어요. 달라란은 호드와 얼라이언스의 평화를 상징하는 첫 이정표가 될 거라고 하셨죠.', `FemaleText_loc4`='我亲耳听到她说，达拉然将向世界展示一个部落与联盟和平共处的典范。', `FemaleText_loc5`='我親耳聽她說過，達拉然會成為世上聯盟與部落之間和平相處的一個亮眼範例。', `FemaleText_loc7`='Se lo oí decir yo misma: que Dalaran sería un gran ejemplo de paz entre Alianza y Horda para el resto del mundo.' WHERE `ID`=70641;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데 선리버가 그녀의 믿음을 져버리고는 그녀의 도시에서 종으로 향하는 차원문을 열었지 뭐에요!', `FemaleText_loc4`='然后夺日者竟然背叛了她的信任，在她的城市里直接开启传送门，通往安放那口圣钟的地方！', `FemaleText_loc5`='可是奪日者背叛了她的信任，在她的城裡開啟傳送門、直達聖鐘!', `FemaleText_loc7`='¡Y van los Atracasol y traicionan su confianza abriendo portales a la campana! ¡Desde su propia ciudad!' WHERE `ID`=70642;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당연히 기분이 상하셨겠죠. 달라란에서 선리버를 쫓아내신 것도 이해가 가요.', `FemaleText_loc4`='她当然会感到气愤啦。她当然有权利把那些卑鄙的夺日者赶出达拉然。', `FemaleText_loc5`='她當然會生氣。她當然有權利把那些討厭的奪日者趕出達拉然。', `FemaleText_loc7`='Claro que está enfadada. Claro que tiene derecho a echar a esos insufribles Atracasol de Dalaran.' WHERE `ID`=70643;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래도 전 아직 뭔가 불안해요. 호드가 이걸 순순히 보고만 있지는 않을 테니까요.', `FemaleText_loc4`='然而我仍然不由地觉得部落不会就此善罢甘休。', `FemaleText_loc5`='不過，我一直有種不好的預感，部落嚥不下這口氣的。', `FemaleText_loc7`='Pero no puedo evitar sospechar que la Horda no se va a quedar de brazos cruzados...' WHERE `ID`=70644;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가로쉬가 천상의 종을 가지고 있어요. 우리를 언제 공격할지 모른다고요!', `FemaleText_loc4`='现在加尔鲁什已经得到了圣钟。他随时就会对我们发动攻击！', `FemaleText_loc5`='現在，聖鐘在卡爾洛斯的手裡。他隨時都可能攻擊我們!', `FemaleText_loc7`='Y ahora Garrosh tiene la Campana divina. ¡Podría atacarnos cualquier día de estos!' WHERE `ID`=70645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안두인 왕자님께서 뭔가 계획하신 게 있기를 바라요.', `FemaleText_loc4`='希望安度因心中已有打算。', `FemaleText_loc5`='我希望安杜因自有盤算。', `FemaleText_loc7`='Espero que Anduin tenga un as en la manga.' WHERE `ID`=70646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='행운을 빌어요.', `FemaleText_loc4`='祝你好运。', `FemaleText_loc5`='祝好運。', `FemaleText_loc7`='Buena suerte.' WHERE `ID`=70647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오실 때가 됐다고 생각했어요. 종말의 날이 다가오는군요.', `FemaleText_loc4`='是你该登场的时候了。末日正在逼近。', `FemaleText_loc5`='你總算現身了，世界末日快到了。', `FemaleText_loc7`='Ya era hora de que vinieras. Se acerca el apocalipsis.' WHERE `ID`=70648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬가 쿤라이 봉우리 북쪽에 병력들을 모으고 있어요.', `FemaleText_loc4`='加尔鲁什正在昆莱山的北侧扩充他的军队。', `FemaleText_loc5`='卡爾洛斯在崑萊峰的北邊集結部隊。', `FemaleText_loc7`='Garrosh está reuniendo a su ejército en el lado norte de la Cima Kun-Lai.' WHERE `ID`=70649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천상의 종을 사용하려나 봐요. 제때 못 막는다면 빛이 우리를 돌봐주길.', `FemaleText_loc4`='他将会使用圣钟的力量，如果我们不能及时阻止他，那只能祈求圣光保佑我们了。', `FemaleText_loc5`='他要使用聖鐘了，要是我們沒能及時阻止他們，那就完了。', `FemaleText_loc7`='Va a usar la Campana divina. Que la Luz nos ampare si no lo detenemos a tiempo.' WHERE `ID`=70650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안두인 왕자님께서 먼저 가셨어요. 자기가 빛의 현신인줄 아는 건방진 바보같으니!', `FemaleText_loc4`='安度因已经先走一步了。那个冒冒失失、莽撞性急的小笨蛋！', `FemaleText_loc5`='安杜因自己先走了。那個厚臉皮又滿口聖光的豆腐腦傻小子!', `FemaleText_loc7`='Anduin se ha adelantado. ¡Ese ingenuo atolondrado!' WHERE `ID`=70651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드를 바꾸고 세상을 구할 수 있다고 생각하나 봐요.... 하지만... 그는 아직 어리잖아요.', `FemaleText_loc4`='这孩子天真的以为他可以说服部落，拯救世界……可是……他只是个孩子。', `FemaleText_loc5`='那小子天真地以為他可以改變部落、拯救世界...可是...他只是個孩子。', `FemaleText_loc7`='El chico es tan inocente que se cree que puede cambiar a la Horda y salvar al mundo... pero no es más que un niño.' WHERE `ID`=70652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왕자님을 말리든가 도와주셔야 해요. 다른 방법은 없어요!', `FemaleText_loc4`='你要么阻止那孩子，要么就帮帮他……二选一！', `FemaleText_loc5`='你得阻止他，或者幫他一把...兩者擇一!', `FemaleText_loc7`='Tienes que pararle los pies al chico o ayudarlo... ¡una de dos!' WHERE `ID`=70653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리도 병력을 모아 가로쉬에 대항하려 하지만, 시간이 필요해요. 그리고 왕자님께서 벌서 위험에 처해있을지도 모르고요.', `FemaleText_loc4`='我们正在集结军队来对抗加尔鲁什，但是那需要时间，而王子可能已经身处险境。', `FemaleText_loc5`='我們在集結部隊準備攻擊卡爾洛斯，可是這得花時間，王子可能已經有危險了。', `FemaleText_loc7`='Estamos formando un ejército para enfrentarnos a Garrosh, pero eso lleva tiempo y el príncipe podría estar en peligro ahora mismo.' WHERE `ID`=70654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에이, 이 연은 왜 속도를 더 못내지?', `FemaleText_loc4`='哦，为什么这风筝不能飞快点儿呢？', `FemaleText_loc5`='啊，這個該死的風箏為什麼不能飛快點?', `FemaleText_loc7`='Ah, ¿no podría ir más rápido esta cometa?' WHERE `ID`=70655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리요. 아직 우리를 못 봤나봐요.', `FemaleText_loc4`='快，他们还没发现我们。', `FemaleText_loc5`='動作快，他們還沒發現我們。', `FemaleText_loc7`='Date prisa. Aún no nos han visto.' WHERE `ID`=70656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 지원군을 데리고 오겠어요.', `FemaleText_loc4`='我回去呼叫援军。', `FemaleText_loc5`='我會帶著增援回來。', `FemaleText_loc7`='Iré a buscar refuerzos.' WHERE `ID`=70657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 무슨 일을 하든. 당신은 얼라이언스의 자랑거리가 될 거예요.', `FemaleText_loc4`='无论今天你成功与否，英雄，你做得一切都是为了联盟。', `FemaleText_loc5`='英雄，不管你今天做了什麼，你都是為了全聯盟而努力。', `FemaleText_loc7`='Hagas lo que hagas, lo harás por la Alianza.' WHERE `ID`=70658;
