UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 졌다고? 말도 안 돼!', `MaleText_loc4`='我输了？不，你才输了！', `MaleText_loc5`='我會輸?不，你才會輸!', `MaleText_loc7`='¡YO NO PIERDO! ¡PIERDES TÚ!', `FemaleText_loc1`='내가 졌다고? 말도 안 돼!', `FemaleText_loc4`='我输了？不，你才输了！', `FemaleText_loc5`='我會輸?不，你才會輸!', `FemaleText_loc7`='¡YO NO PIERDO! ¡PIERDES TÚ!' WHERE `ID`=70661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실하게 이길 내기였는데! 전 재산을 다 걸었다고!', `MaleText_loc4`='那可是板上钉钉的事儿啊！我全都押上了！', `MaleText_loc5`='這應該要萬無一失的!我把一切都押在上面了!', `MaleText_loc7`='¡Se suponía que estaba asegurado! ¡LO APOSTÉ TODO!', `FemaleText_loc1`='확실하게 이길 내기였는데! 전 재산을 다 걸었는데!', `FemaleText_loc4`='那可是板上钉钉的事儿啊！我全都押上了！', `FemaleText_loc5`='這應該要萬無一失的!我把一切都押在上面了!', `FemaleText_loc7`='¡Se suponía que estaba asegurado! ¡LO APOSTÉ TODO!' WHERE `ID`=70662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게... 이런... 젠장!', `MaleText_loc4`='怎么……搞什么啊……该死！', `MaleText_loc5`='怎麼會...怎麼可能...可惡!', `MaleText_loc7`='¿QUÉ...? ¿CÓMO...? ¡MALDITA SEA!', `FemaleText_loc1`='이런... 어떻게... 제길!', `FemaleText_loc4`='怎么……搞什么啊……该死！', `FemaleText_loc5`='怎麼會...怎麼可能...可惡!', `FemaleText_loc7`='¿QUÉ...? ¿CÓMO...? ¡MALDITA SEA!' WHERE `ID`=70663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 싸움을 밖에서 계속하면 어떨까요? 가서 스톰윈드를 박살냅시다!', `FemaleText_loc4`='该我们登场发挥了，把暴风城踩烂吧！', `FemaleText_loc5`='讓我們上路去，一路直搗暴風城!', `FemaleText_loc7`='¡Vamos a ponernos en marcha y destrozar Ventormenta!' WHERE `ID`=70664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸움꾼이 바글바글 모였군요! 모두 힘을 합쳐 바리안의 예쁘장한 얼굴을 뭉개버립시다!', `FemaleText_loc4`='这地方已经挤满了！我们应该组起队伍，往瓦里安漂亮的小脸蛋儿上来上几脚！', `FemaleText_loc5`='這裡好擠!我們應該同心協力，好好修理瓦里恩一頓!', `FemaleText_loc7`='¡Este sitio está lleno hasta la bandera! ¡Deberíamos agruparnos e ir a darle a Varian una patada en toda la cara!' WHERE `ID`=70665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='피에 굶주렸습니까? 다 같이 스톰윈드를 박살내면 어떨까요?', `FemaleText_loc4`='如果你如此渴望鲜血，为什么不组起队伍，把暴风城砸烂？', `FemaleText_loc5`='如果你這麼渴望鮮血，為什麼不團結起來拆了暴風城?', `FemaleText_loc7`='Si estáis tan sedientos de sangre, ¿por qué no os agrupáis y vais a arrasar Ventormenta?' WHERE `ID`=70666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문이 열렸습니다! 가서 호드가 어떻게 싸우는지 보여줍시다!', `FemaleText_loc4`='传送门就在这儿！穿过这门，告诉他们部落是怎么打架的！', `FemaleText_loc5`='傳送門開啟了!給我進門去，讓他們瞧瞧部落的能耐!', `FemaleText_loc7`='¡El portal está abierto! ¡Entren y enséñenles cómo se las gasta la Horda!' WHERE `ID`=70667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 스톰윈드로 가는 차원문을 열었습니다. 가서 꼬맹이들 볼기짝 좀 걷어차 주세요!', `FemaleText_loc4`='我开启了一道通往暴风城的传送门。穿过它，猛踹联盟的屁股！', `FemaleText_loc5`='我開啟了一個通往暴風城的傳送門。過去大展身手吧!', `FemaleText_loc7`='He abierto un portal a Ventormenta. ¡Entrad y dadles una paliza!' WHERE `ID`=70668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='스톰윈드행 차원문이 열렸습니다! 모두 들어가세요!', `FemaleText_loc4`='传送门准备好了！快进去！', `FemaleText_loc5`='通往暴風城的傳送門已經打開了!進去!', `FemaleText_loc7`='¡El portal a Ventormenta ya funciona! ¡Atravesadlo!' WHERE `ID`=70669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움굴에 얼라이언스 최고의 싸움꾼들이 꽉꽉 들어찼습니다! 다 함께 오그리마를 박살냅시다!', `MaleText_loc4`='联盟全明星，人气爆棚！让我们把奥格瑞玛踩平吧！', `MaleText_loc5`='這個地方水洩不通，全是聯盟的精英!讓我們去拆了奧格瑪!', `MaleText_loc7`='¡Este sitio rebosa de estrellas de la Alianza! ¡Vamos a arrasar Orgrimmar!' WHERE `ID`=70670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭력과 피바다를 원하십니까? 가서 호드를 공격합시다!', `MaleText_loc4`='你们想来点儿带劲儿的？让我们去部落的地盘找点儿乐子！', `MaleText_loc5`='你們想要暴力與鮮血?我們找部落動手吧!', `MaleText_loc7`='¿Queréis violencia y derramamiento de sangre? ¡Vamos a por la Horda!' WHERE `ID`=70671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 싸움 연습을 하는 것도 좋지만, 오그리마가 제풀에 쓰러질 날만 기다릴 수는 없습니다!', `MaleText_loc4`='别再保持优雅的风度了，奥格瑞玛等着我们去踩平呢！', `MaleText_loc5`='這場演練是很不錯，但是奧格瑪可不會自己垮台!', `MaleText_loc7`='Todo este entrenamiento está muy bien, ¡pero Orgrimmar no se va a destrozar sola!' WHERE `ID`=70672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가는 차원문을 열었습니다. 호드 볼기짝 걷어차 주고 싶으신 분?', `MaleText_loc4`='我开启了一道通往奥格瑞玛的传送门。谁想要猛踹部落的屁股？', `MaleText_loc5`='我開了一道通往奧格瑪的傳送門，有誰想去修理部落的?', `MaleText_loc7`='He abierto un portal a Orgrimmar. ¿Quién quiere darle una paliza a la Horda?' WHERE `ID`=70673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움굴 팬 여러분, 오그리마행 차원문이 열렸습니다! 가서 "거품" 씨가 보냈다고 전해 주세요.', `MaleText_loc4`='奥格瑞玛传送门已经开启，搏击粉丝们！告诉他们是“泡泡”送你们来的。', `MaleText_loc5`='各位鬥陣粉絲，奧格瑪的傳送門打開了!跟他們說，是『泡泡』派你過去的。', `MaleText_loc7`='¡El portal a Orgrimmar ya está abierto, luchadores! ¡Díganles que Burbujas los envía!' WHERE `ID`=70674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가는 차원문 시키신 분? 없다고요? 거 참 아깝네요!', `MaleText_loc4`='有人预定了通往奥格瑞玛的传送门吗？没有？怎么可能！', `MaleText_loc5`='有人點了一道通往奧格瑪的傳送門嗎?沒有?太可惜了!', `MaleText_loc7`='¿Alguien había pedido un portal a Orgrimmar? ¿No? ¡DA IGUAL!' WHERE `ID`=70675;
