UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장군 블러드힐트가 피에 굶주린 일격을 준비합니다!', `MaleText_loc4`='血柄督军准备施放嗜血打击！', `MaleText_loc5`='督軍血柄準備施展嗜血攻擊!', `MaleText_loc7`='¡El señor de la guerra Sangrastil prepara un Golpe sanguinario!' WHERE `ID`=70700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, $c, 스톰윈드에 가려고 하시오? 내 차원문을 타는 게 빠를 거요! 권한이 없다면 어쩔 수 없지만.', `MaleText_loc4`='嘿$c，你想要去暴风城？我的传送门最便捷！但如果你没有委任状的话，你就只能自己去那儿了。', `MaleText_loc5`='嘿$c，你想去暴風城嗎?我的傳送門可以馬上送你過去喔!但是如果沒有委任徽章的話，你只好自己想辦法了。', `MaleText_loc7`='¡Oye, $c! ¿Quieres ir a Ventormenta? ¡Viaja rápido con uno de mis portales! Si no tienes comisiones, tendrás que arreglártelas por tu cuenta.' WHERE `ID`=70701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실버문으로 데려다 주세요.', `MaleText_loc4`='带我去银月城。', `MaleText_loc5`='帶我去銀月城。', `MaleText_loc7`='Llévame a la Ciudad de Lunargenta.', `FemaleText_loc1`='실버문으로 데려다 주세요.', `FemaleText_loc4`='带我去银月城。', `FemaleText_loc5`='帶我去銀月城。', `FemaleText_loc7`='Llévame a la Ciudad de Lunargenta.' WHERE `ID`=70702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다르나서스로 데려다 주세요.', `MaleText_loc4`='带我去达纳苏斯。', `MaleText_loc5`='帶我去達納蘇斯。', `MaleText_loc7`='Llévame a Darnassus.', `FemaleText_loc1`='다르나서스로 데려다 주세요.', `FemaleText_loc4`='带我去达纳苏斯。', `FemaleText_loc5`='帶我去達納蘇斯。', `FemaleText_loc7`='Llévame a Darnassus.' WHERE `ID`=70703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버 일당을 처리할 날을 오랫동안 기다려 왔어요. 세상을 떠난 남편에게도 이 도시에서 그들을 몰아내야 한다고 얘기했었지만, 그는 키린 토가 중립임을 지나칠 만큼 굳건하게 믿고 있었죠.$b$b그는 현명했지만, 먼 훗날을 내다보지는 못했어요. 키린 토의 운명은 언제나 하나였어요. 바로 얼라이언스에 봉사하는 것이었죠.', `FemaleText_loc4`='我早就想和夺日者划清界限了，只是一直在等待这样的机会。我曾向我过世的丈夫提过将他们赶出达拉然，但是他决意要把肯瑞托放在绝对中立的位置。$b$b他是个睿智的人，但是远见不足。肯瑞托的命运就应当如此：效忠联盟。', `FemaleText_loc5`='我一直都在等待驅逐奪日者的機會。我曾要求我已死去的丈夫，將他們逐出這座城市，但是他一直堅守著祈倫托的中立立場。$b$b他是個有智慧的人，但眼光卻不夠長遠。祈倫托的命運一直都是為了:服侍聯盟。', `FemaleText_loc7`='Llevo mucho tiempo esperando la oportunidad de encargarme de los Atracasol. Le pedí a mi difunto marido que los expulsara de la ciudad, pero él creía en la neutralidad del Kirin Tor con demasiada firmeza.$b$bEra sabio, pero no pensaba a largo plazo. El destino del Kirin Tor siempre ha sido servir a la Alianza.' WHERE `ID`=70704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아로 돌아갈 준비가 됐습니다.', `MaleText_loc4`='我准备好前往潘达利亚了。', `MaleText_loc5`='我準備回到潘達利亞了。', `MaleText_loc7`='Estoy listo para volver a Pandaria.', `FemaleText_loc1`='판다리아로 돌아갈 준비가 됐어요.', `FemaleText_loc4`='我准备好前往潘达利亚了。', `FemaleText_loc5`='我準備回到潘達利亞了。', `FemaleText_loc7`='Estoy lista para volver a Pandaria.' WHERE `ID`=70705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프 건설 현장이 공격받고 있습니다!', `MaleText_loc4`='暗夜精灵建筑营地遭到攻击！', `MaleText_loc5`='夜精靈建築工地受到攻擊!', `MaleText_loc7`='¡Están atacando la zona de construcción de los elfos de la noche!', `FemaleText_loc1`='나이트 엘프 건설 현장이 공격받고 있습니다!', `FemaleText_loc4`='暗夜精灵建筑营地遭到攻击！', `FemaleText_loc5`='夜精靈建築工地受到攻擊!', `FemaleText_loc7`='¡Están atacando la zona de construcción de los elfos de la noche!' WHERE `ID`=70706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 배들이! 도대체 무슨 일이 일어난거죠?!', `MaleText_loc4`='我们的船只！这到底是怎么回事？！', `MaleText_loc5`='我們的船!我的鬍子呀，到底發生了什麼事?!', `MaleText_loc7`='¡Nuestros barcos! Por mis barbas, ¿qué ha pasado aquí?' WHERE `ID`=70707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 풀려났다! 이제 너희들을 쓸어버려야겠군. 역겨운 호젠 반역자 놈들!', `MaleText_loc4`='我终于自由了！反叛的臭猴子们，我终于摆脱你们了。', `MaleText_loc5`='終於自由了!現在你們這些造反的臭猴人給我去死吧。', `MaleText_loc7`='¡Al fin libre! Y ahora me desharé de ustedes, asquerosos hozen rebeldes.' WHERE `ID`=70708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음이 당신 차례입니다!', `MaleText_loc4`='你就排在下一位！', `MaleText_loc5`='下一個就輪到你了!', `MaleText_loc7`='¡Luego te toca a ti!', `FemaleText_loc1`='다음이 당신 차례입니다!', `FemaleText_loc4`='你就排在下一位！', `FemaleText_loc5`='下一個就輪到你了!', `FemaleText_loc7`='¡Luego te toca a ti!' WHERE `ID`=70709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제... 국은... 다시 번창할 것이다...', `MaleText_loc4`='帝国……必将……再度崛起。', `MaleText_loc5`='魔古...帝國...將再度崛起。', `MaleText_loc7`='El... imperio... se alzará de nuevo.' WHERE `ID`=70710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 짓뭉개주마!', `MaleText_loc4`='我要把你从生死簿上除名！', `MaleText_loc5`='我要抹除你的存在!', `MaleText_loc7`='¡Te borraré del mapa!' WHERE `ID`=70711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 여기서 비틀어 떼어내야 할 거다!', `MaleText_loc4`='有本事就把我从这里赶出去！', `MaleText_loc5`='我可是不好對付的!', `MaleText_loc7`='¡Yo de aquí no me muevo!' WHERE `ID`=70712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버를 위하여!', `FemaleText_loc4`='为了夺日者！', `FemaleText_loc5`='為了奪日者!', `FemaleText_loc7`='¡Por los Atracasol!' WHERE `ID`=70713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='결국 이렇게 됐군, 그렇지?', `FemaleText_loc4`='所以必须做个了断了，对吧？', `FemaleText_loc5`='最終還是這樣的結局，是吧?', `FemaleText_loc7`='A esto hemos llegado, ¿eh?' WHERE `ID`=70714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제길... 은빛 서약단이 쫓아왔군.', `MaleText_loc4`='该死……银色盟约的人也来了。', `MaleText_loc5`='該死...白銀誓盟的人在這。', `MaleText_loc7`='Maldición... Es el Pacto de Plata.' WHERE `ID`=70715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하는 데까지 해봐요. 제가 조사해본 결과 이 비취 전쟁군주에 대해 좋은 점은 없네요. 싸울 준비 하세요.', `MaleText_loc4`='但愿能成功。根据我的调查，这个青玉战神不是什么好东西。准备好战斗吧。', `MaleText_loc5`='不管那麼多了。我的研究結果對這位翠玉督軍沒有什麼好評價。準備戰鬥。', `MaleText_loc7`='Ha llegado el momento. Mi investigación no me ha dado muy buena impresión de este señor de la guerra de jade, así que prepárate para la batalla.' WHERE `ID`=70716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 이 굴이 지금 빙빙 돌고 있나?', `MaleText_loc4`='这个屋子在旋转？', `MaleText_loc5`='這間房子在打轉嗎?', `MaleText_loc7`='¿Eshta habitación da vueltash?' WHERE `ID`=70717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... *끄억*', `MaleText_loc4`='……*嗝*', `MaleText_loc5`='...*打嗝*', `MaleText_loc7`='... *eructo*' WHERE `ID`=70718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 술 흘렸다!', `MaleText_loc4`='我的酒洒啦！', `MaleText_loc5`='酒灑出來了!', `MaleText_loc7`='¡He derramado la copa!' WHERE `ID`=70719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='술이나 한 잔 사 주실래요?', `FemaleText_loc4`='能请我喝一杯吗？', `FemaleText_loc5`='幫我買杯什麼喝的吧?', `FemaleText_loc7`='¿Me invitash a una copa?' WHERE `ID`=70720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래요, 여기 브롬은 제 끝사랑이에요. 이 친구가 경량급이긴 하지만, 그래도 우린 완두콩 한 쌍처럼 서로 꼭 닮은 짝꿍이죠!', `FemaleText_loc4`='没错，布鲁姆就是我的爱人，我们俩就像是一个豆荚里的两颗豆子，即使他是轻量级选手，我也一样爱他！', `FemaleText_loc5`='沒錯，布隆就是我一生的摯愛。我們倆簡直是一個模子刻出來的，儘管他的體型這麼袖珍!', `FemaleText_loc7`='Shí, Brom esh el amor de mi vida. Shomosh almash gemelash, ¡aunque él shea pesho pluma!' WHERE `ID`=70721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나한테 뭐 할 말이라도 있어요? 좋아요, 당신은 말을 하고, 저는 술을 마시죠!', `FemaleText_loc4`='你有话和我说？没问题，你负责说，我负责喝！', `FemaleText_loc5`='你有話要跟我說?那你一邊說我一邊喝吧!', `FemaleText_loc7`='¿Tienesh algo que decirme? ¡Tú hablash, yo bebo!' WHERE `ID`=70722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 하는 말은 아무것도 믿지 마세요. 아, 이 말도 무시하세요.', `FemaleText_loc4`='你最好别相信我说的任何话。算了，当我没说过。', `FemaleText_loc5`='你最好還是不要相信我說過的話。事實上，還是忘了我剛才說的話吧。', `FemaleText_loc7`='Será mejor que no confíes en nada que te diga yo. De hecho, no me hagas caso.' WHERE `ID`=70723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 그래요. 저에 대해 잘못된 소문이 돌고 있어요. 다크문 축제장의 놀이기구에서 자라났다거나, 다섯 살 생일에 숟가락만으로 악마 여섯을 처치했다거나, 심지어는... 아, 이건 제가 가장 좋아하는 얘긴데요, 제가 원래 금발이라고까지 하더라고요. 사람들은 아무 말이나 믿는다니까요.', `FemaleText_loc4`='啊，没错，那些关于我的谣言满天飞，可惜都是假的。什么我小时候是暗月马戏团的吉祥物，五岁生日那天杀了六个恶魔——用的还是一把勺子——我最喜欢这段了。但事实上，我只是个普通的金发姑娘。人们就喜欢相信那些有的没的。', `FemaleText_loc5`='噢，對了。這一帶有很多關於我的不實謠言。比如說我從小就是暗月馬戲團裡吸引遊客的亮點，或者是在我五歲的時候用湯匙殺死六隻惡魔，還有...這條是我最喜歡的...其實我的金色頭髮是天生的。什麼鬼話都有人相信。', `FemaleText_loc7`='Sí, circulan muchos rumores falsos sobre mí. Dicen que crecí siendo una atracción de la Feria de la Luna Negra... que maté a seis demonios en mi quinto cumpleaños usando solo una cuchara... Mi rumor favorito es que soy rubia natural. Hay gente que se cree cualquier cosa.' WHERE `ID`=70724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 정말 멋져요. 다른 데서는 사람들이 저를 폭력적인 반사회적 인격 장애자라고 부르는데... 아, 물론 여기서도 다들 그렇게 얘기하지만, 적어도 웃으면서 절 마주보고 그렇게 얘기하더라고요.', `FemaleText_loc4`='我喜欢这个地方。在别的地方，那些人总是叫我“暴力孤僻女”。好吧，其实在这儿他们也这么叫我，不过至少他们是当着我的面，并且面带着微笑地叫这个名字。', `FemaleText_loc5`='這裡太好了。要是到了其他地方我一定會被他們說成是暴力的反社會主義者。好吧，雖然他們在這裡也是這樣叫我，但至少他們會帶著微笑當面跟我說。', `FemaleText_loc7`='Este sitio es genial. En cualquier otra parte dirían que soy una sociópata violenta. Bueno, aquí también me lo dicen, pero al menos me lo dicen a la cara con una sonrisa.' WHERE `ID`=70725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 베이컨 냄새가 나지 않습니까?', `MaleText_loc4`='我闻起来像不像火腿？', `MaleText_loc5`='我聞到培根的味道了嗎?', `MaleText_loc7`='¿Huelo panceta?' WHERE `ID`=70726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알레르기 때문에 약을 좀 먹어야겠습니다.', `MaleText_loc4`='我过敏了，得吃点药。', `MaleText_loc5`='我得找點藥來治治我的過敏。', `MaleText_loc7`='Tengo que comprar medicación para mis alergias.' WHERE `ID`=70727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='며칠 전에, 한 남자가 공을 던지면서 저한테 물어 오라고 했습니다. 그래서 시키는 대로 했지요. 공이 아니라 그 녀석 머리로요. 뭐, 어차피 그렇게 똑똑한 머리도 아니었습니다.', `MaleText_loc4`='前几天的一个晚上，有人扔了个球过来，还叫我去捡。我照他说的做了，只不过把球和他脑袋一起扔回去了。不用说，他没接着那个球。', `MaleText_loc5`='前幾天晚上前有個傢伙扔一顆球然後叫我去撿。我也說了相同的話來回應他，只不過我扔的那顆球就是他的頭。當然他再也無法什麼打趣的笑話來回應我。', `MaleText_loc7`='Hace un par de noches un tipo me tiró una pelota y me dijo que fuera a buscarla. Como respuesta, yo hice otro tanto, pero con su cabeza. Huelga decir que no soltó ningún comentario gracioso.' WHERE `ID`=70728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 항상 피머리를 응원해요. 그 까칠한 뾰족엄니 녀석은 느리고 뚱뚱한 상대를 순식간에 없애버리더라고요.', `FemaleText_loc4`='我总是为血角欢呼。那头愤怒的铲齿鹿看似娇小，却总是能让那些大块头吃尽苦头。', `FemaleText_loc5`='每次牴角起床我都得好好安撫牠。這個脾氣不好的小鍬牙工作起來比那些又胖又懶的還要快。', `FemaleText_loc7`='Siempre animo a Cocosangre cuando combate. Ese colmipala furioso acaba con los lentos en un pispás.' WHERE `ID`=70729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='도시에서의 생활은 드루이드도 바꿔 놓지요. 지난 주에는 처음으로 비행 조련사에게 부탁해서 옆 동네로 날아갔었는데... 아, 정말 편하더라고요.', `FemaleText_loc4`='城市生活会改变一名德鲁伊。上周我生平第一次使用了公共飞行路线……感觉真是不错啊。', `FemaleText_loc5`='都市的生活會改變一個德魯伊。我上個禮拜才第一次使用飛行路線...結果好極了。', `FemaleText_loc7`='La vida en la ciudad cambia a los druidas. El otro día utilicé un punto de vuelo por primera vez... y fue genial.' WHERE `ID`=70730;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='드루이드는 다들 너무 진지해요. 하지만 저는 파티에만 가면 짐승이 된답니다. 네, 말장난 맞아요. 웃으세요. 지금 당장.', `FemaleText_loc4`='大多数德鲁伊都很古板，不过我是个例外，我是个真正的聚会动物。我的笑话说完了。你该笑了。', `FemaleText_loc5`='德魯伊有的時候很嚴肅，但我可是個派對狂。沒錯，我剛剛講的是笑話。你現在就應該給我笑起來。', `FemaleText_loc7`='A veces los druidas somos demasiado serios, pero a mí también me gusta hacer animaladas. Sí, eso era una broma. Estaría bien que te rieras.' WHERE `ID`=70731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 이마만 가지고 송판 네 장은 부러뜨릴 수 있습니다. 한번 보여드릴까요?', `MaleText_loc4`='我能轻松打断四层强化松木板，只是要借用一下你的脑袋。要我给你做个示范吗？', `MaleText_loc5`='我光用你的額頭就可以打穿四塊硬松木板。要我來示範一下嗎?', `MaleText_loc7`='Puedo atravesar cuatro tablas de madera de pino usando solo tu cabeza. ¿Quieres que te lo demuestre?' WHERE `ID`=70732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수도사들이 왜들 그렇게 술통을 집어던지는지 도저히 모르겠습니다. 너무 아깝지 않습니까.', `MaleText_loc4`='我不知道为啥这么多武僧都把酒桶乱扔。真浪费。', `MaleText_loc5`='我不明白為什麼這麼多武僧拿著酒桶扔來扔去的。真浪費。', `MaleText_loc7`='No entiendo por qué los demás monjes van por ahí tirando barriles. Qué desperdicio.' WHERE `ID`=70733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지요. 저도 싸움판에 들어설 겁니다. 이 술통 두 개만 비우고요.', `MaleText_loc4`='当然，我会上场的，等我把这两桶酒喝完。', `MaleText_loc5`='沒問題，我會到競技場裡去。先讓我喝完這兩杯。', `MaleText_loc7`='Claro que entraré en el ring. Solo tengo que acabar estos dos barriles.' WHERE `ID`=70734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 미안해요. 지금은 술도 한 잔 사드릴 수가 없네요. 돈이 하나도 없거든요. 그래도 곧 형편이 괜찮아질 거예요.', `FemaleText_loc4`='啊，对不起，我不能请你喝酒了。我最近有点小穷，但我相信我会时来运转的。', `FemaleText_loc5`='噢，抱歉，我沒辦法請你喝東西。我現在沒錢，但情況馬上就會好轉了。', `FemaleText_loc7`='Lo siento, no puedo invitarte a una copa. Ahora mismo ando sin blanca, pero eso está a punto de cambiar.' WHERE `ID`=70735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳은 꽤나 거칠고 난폭해 보이지만, 여기 있는 모두는 내면이 솜사탕처럼 부드러워요.', `FemaleText_loc4`='这地方看起来很硬派，但这里的人其实内心里都是软蛋。', `FemaleText_loc5`='這地方看起來又破又糟，但是裡面的每個人心地都十分善良。', `FemaleText_loc7`='Este sitio parece muy duro, pero por dentro todo el mundo es un pedazo de pan.' WHERE `ID`=70736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 네. 오그리마에 처음 왔어요. 그렇게 티 많이 나나요?', `FemaleText_loc4`='哦，没错，我刚到奥格瑞玛不久。这不明摆着的吗？', `FemaleText_loc5`='噢，是的，我是新到奧格瑪的。有這麼明顯嗎?', `FemaleText_loc7`='Sí, soy nueva en Orgrimmar. ¿Tanto se nota?' WHERE `ID`=70737;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자네도 싸움판 대기열에 등록하게. 웃을거리가 좀 필요하군.', `FemaleText_loc4`='你应该排队参加搏击——这样我就能笑上好一阵了。', `FemaleText_loc5`='你應該去排隊來打一場。可以讓我好好笑一笑。', `FemaleText_loc7`='Deberías ponerte a la cola para pelear. Me apetece echarme unas risas.' WHERE `ID`=70738;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속 노려보게. 난 어색한 침묵을 무척 좋아하니까.', `FemaleText_loc4`='继续瞪着我。我喜欢尴尬的沉默。', `FemaleText_loc5`='繼續盯著看呀。我最喜歡尷尬的沈默了。', `FemaleText_loc7`='Sigue mirando. Disfruto de los silencios incómodos.' WHERE `ID`=70739;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신발은 약자나 신는 것이네.', `FemaleText_loc4`='弱者才穿鞋。', `FemaleText_loc5`='弱者才要穿鞋子。', `FemaleText_loc7`='Los zapatos son para los débiles.' WHERE `ID`=70740;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지난번에 제가 싸움판에 들어서자, 상대가 울면서 도망치더군요. 도망치는 건 놀랍지 않았지만, 악어가 눈물을 흘리는 건 그때 처음 봤어요.', `FemaleText_loc4`='上一回我在竞技场里把对手打到边哭边逃。按说对手打架打到一半就逃这不算什么稀奇事儿，但这可是我头一回看到鳄鱼流眼泪。', `FemaleText_loc5`='上次我來鬥陣俱樂部的時候，我的對手哭著回去找媽媽了。它們逃跑並不稀奇，但那是我第一次看到鱷魚的眼淚。', `FemaleText_loc7`='La última vez que entré en un combate mi oponente salió llorando. No me sorprendió que huyera, pero era la primera vez que veía llorar a un crocolisco.' WHERE `ID`=70741;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 항상 "나이리, 이것 좀 들어봐!"라고 소리를 쳐요. "나이리, 춤 좀 춰봐!"라고는 왜들 안 할까요? 전 춤도 아주 잘 추는데...', `FemaleText_loc4`='“娜丽，把这东西举起来！”，他们总是这么冲我嚷嚷。为什么不能说“娜丽，能跳支舞吗？”我可是个伟大的舞者。', `FemaleText_loc5`='『奈莉，把它抬起來!』他們總是這麼對我喊。為什麼他們從不對我說『奈莉，來跳支舞吧!』?我是多麼出色的舞者。', `FemaleText_loc7`='Siempre me están diciendo "¡Nairi, levanta eso!". ¿Por qué nunca me dicen "¡Nairi, enséñanos tus bailes!"? Soy una bailarina estupenda.' WHERE `ID`=70742;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 스터들링튼 공작은 얼간이에요. 잘난 듯이 얘기하지만, 칼도 들 줄 모르는 바보죠. 아, 네, 당신도 짐작하셨듯이, 그 이름도 가짜랍니다.', `FemaleText_loc4`='斯特林顿公爵就是个渣渣。他吹牛吹得厉害，但连自己的剑都拿不起来。啊，没错，他的名字也是瞎编的，我相信你肯定猜到了。', `FemaleText_loc5`='斯達林頓公爵是個混蛋。老是只會用嘴巴說，但從來沒拔出自己的劍。噢，還有那個也不是他的真名，當然我想你也猜到了。', `FemaleText_loc7`='Ese Duke Guapington es un imbécil. Se las da de figura, pero apenas puede levantar su propia espada. Ah, y ese nombre no es auténtico, por si te lo estabas preguntando.' WHERE `ID`=70743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주먹 맛 좀 보시겠습니까, 얼간이 양반?', `MaleText_loc4`='你想吃拳头了，笨蛋？', `MaleText_loc5`='你想要嚐嚐砂鍋大拳頭的滋味嗎，蠢蛋?', `MaleText_loc7`='¿Quieres que te parta la cara?' WHERE `ID`=70744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어제 밤에는 오크 셋과 타우렌 하나를 때려눕혔습니다. 저는 손톱도 하나 안 부러졌지요.', `MaleText_loc4`='昨晚我教训了三个兽人和一个牛头人，连一根指甲都没刮花。', `MaleText_loc5`='我昨天晚上痛宰了三個獸人跟一個牛頭人，還沒弄斷一根指甲。', `MaleText_loc7`='Anoche pateé a tres orcos y a un tauren sin inmutarme.' WHERE `ID`=70745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 운동이라도 좀 하지 그러십니까, 친구?', `MaleText_loc4`='你搬过东西吗，兄弟？', `MaleText_loc5`='你有練舉重嗎，老兄?', `MaleText_loc7`='¿Haces pesas?' WHERE `ID`=70746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 그건 내 대퇴골이네. 그래도 만나서 반갑군.', `MaleText_loc4`='不，那是我的大腿骨，但是我见到你很高兴。', `MaleText_loc5`='不對，那是我的股骨，但是我還是很高興看到你。', `MaleText_loc7`='No, eso es mi fémur, pero me alegro de verte.' WHERE `ID`=70747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여자들은 상처를 좋아하네. 내가 왜 여자들에게 이렇게 인기가 좋은지 알겠지?', `MaleText_loc4`='小鸡就喜欢啄伤疤，所以你知道为啥我这么受女士们欢迎了吧。', `MaleText_loc5`='小妞們都特別鍾情疤痕，所以你看為什麼我這麼受女性歡迎。', `MaleText_loc7`='A las chicas les gustan las cicatrices. ¿Entiendes por qué tengo tanto éxito con las mujeres?' WHERE `ID`=70748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 모습이 마음에 드나? 당연히 그렇겠지.', `MaleText_loc4`='你喜欢眼前这一切吗？你当然喜欢了。', `MaleText_loc5`='喜歡你看到的東西嗎?你當然喜歡。', `MaleText_loc7`='¿Te gusta lo que ves? Claro que sí.' WHERE `ID`=70749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 다들 내 이름을 알고 있는 거지?', `MaleText_loc4`='为什么每个人都知道我的名字？', `MaleText_loc5`='為什麼大家都知道我叫什麼名字?', `MaleText_loc7`='¿Cómo es que todo el mundo sabe cómo me llamo?' WHERE `ID`=70750;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안아주게.', `MaleText_loc4`='我很想抱抱你。', `MaleText_loc5`='抱一下安慰我。', `MaleText_loc7`='Me vendría bien un abrazo.' WHERE `ID`=70751;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뒤를 봐 주게, 친구.', `MaleText_loc4`='掩护我，伙计。', `MaleText_loc5`='掩護我，老兄。', `MaleText_loc7`='Cúbreme, amigo.' WHERE `ID`=70752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정신 똑바로 차리게.', `MaleText_loc4`='睁大你的眼睛。', `MaleText_loc5`='罩子放亮點。', `MaleText_loc7`='Manten los ojos abiertos.' WHERE `ID`=70753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리 가지 말게.', `MaleText_loc4`='跟紧我。', `MaleText_loc5`='跟緊。', `MaleText_loc7`='No te alejes.' WHERE `ID`=70754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 뭔가 있네.', `MaleText_loc4`='小心——那里有东西。', `MaleText_loc5`='等等 - 這裡有什麼東西。', `MaleText_loc7`='Alto, ahí hay algo.' WHERE `ID`=70755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 가게.', `MaleText_loc4`='再见。', `MaleText_loc5`='再見。', `MaleText_loc7`='Adió''.' WHERE `ID`=70756;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 원숭이 황제님?', `MaleText_loc4`='啊……陛下？', `MaleText_loc5`='噢...您是?', `MaleText_loc7`='Eh... ¿alteza?' WHERE `ID`=70757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도마뱀 괴물이군. 함께 싸우세, 형제여!', `MaleText_loc4`='该死的蜥蜴人。随我战斗，兄弟们！', `MaleText_loc5`='是一隻蜥蜴怪物，上啊，兄弟們!', `MaleText_loc7`='Uno de esos bichos lagarto. ¡Luchen, hermanos!' WHERE `ID`=70758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죄송해요. 제 이름은 안두인 린이라고 해요. 폐하께서 저와 이 용사를 도와주셨으면 좋겠어요.', `MaleText_loc4`='抱歉。我的名字叫安度因·乌瑞恩。我和这位勇士需要你的帮助。', `MaleText_loc5`='請容我致歉。我的名字叫做安杜因·烏瑞恩。這位勇士和我需要你的幫助。', `MaleText_loc7`='Lo siento. Me llamo Anduin Wrynn. $gEste campeón:Esta campeona; y yo necesitamos tu ayuda.' WHERE `ID`=70759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다만, 지금은 연회를 열 때가 아니에요. 가로쉬라는 흉악한 호드의 대장이 천상의 종을 찾았으니까요. 우리가 맞서려면 조화의 망치가 필요해요.', `MaleText_loc4`='谢谢你。但现在可不是开派对的时候。一个穷凶极恶的军阀已经找到了圣钟，他的名字叫加尔鲁什。我们需要祥和钟杵来对抗他。', `MaleText_loc5`='謝謝你，但這不是慶祝的時候。一個叫做卡爾洛斯，可怕的戰場梟雄發現了聖鐘。我們需要用和諧之槌來對抗他。', `MaleText_loc7`='Gracias, pero no es momento para fiestas. Un peligroso líder guerrero llamado Garrosh ha encontrado la Campana divina. Necesitamos la marra armónica para contrarrestarla.' WHERE `ID`=70760;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음, 제가 조사한 바에 따르면 폐하께서 마지막으로...', `MaleText_loc4`='而且，调查显示你是最后一个——', `MaleText_loc5`='可是，我的研究報告說你是最後一個 -', `MaleText_loc7`='Según mi investigación, tú fuiste el último en...' WHERE `ID`=70761;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 도움이 될 걸세.', `MaleText_loc4`='这会有所帮助。', `MaleText_loc5`='這可以幫的上忙。', `MaleText_loc7`='Esto ayudará.' WHERE `ID`=70762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸우게!', `MaleText_loc4`='继续战斗。', `MaleText_loc5`='繼續戰鬥!', `MaleText_loc7`='¡Sigue luchando!' WHERE `ID`=70763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령의 가호가 따르길.', `MaleText_loc4`='万灵与你同在。', `MaleText_loc5`='靈魂與你永在。', `MaleText_loc7`='Que los espíritus te guíen.' WHERE `ID`=70764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 상처를 치유하게!', `MaleText_loc4`='用这个治疗你！', `MaleText_loc5`='用這個來治療你自己!', `MaleText_loc7`='¡Usa esto para sanarte!' WHERE `ID`=70765;
