UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 함정을 설치했네.', `MaleText_loc4`='我设了个陷阱。', `MaleText_loc5`='我來設個陷阱!', `MaleText_loc7`='Puse una trampa.' WHERE `ID`=70768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='함정으로 데려오게!', `MaleText_loc4`='把他引到陷阱里来！', `MaleText_loc5`='把他帶進陷阱裡!', `MaleText_loc7`='¡Condúzcanlo a esa trampa!' WHERE `ID`=70769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들 좀 떼어 주게!', `MaleText_loc4`='别让这些野兽靠近我！', `MaleText_loc5`='把這些野獸弄走!', `MaleText_loc7`='¡Quítenme a estas bestias de encima!' WHERE `ID`=70770;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기 또 있네.', `MaleText_loc4`='又来了。', `MaleText_loc5`='還有其他的。', `MaleText_loc7`='Hay más.' WHERE `ID`=70771;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들과 싸워 본 적 있나?', `MaleText_loc4`='你以前和这些家伙战斗过吗？', `MaleText_loc5`='你以前對付過這種傢伙?', `MaleText_loc7`='¿Ya se han enfrentado a estas bestias antes?' WHERE `ID`=70772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기는 있어도 뇌는 없는 모양이야.', `MaleText_loc4`='看来他们空有武器，却没有脑子。', `MaleText_loc5`='他們空有武力，卻沒什麼腦袋。', `MaleText_loc7`='Es como si tuvieran armas, pero no cerebro.' WHERE `ID`=70773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배를 타고 들어가면 돼. 잠시 몇 군데 손만 좀 보고...', `MaleText_loc4`='我们可以把船开进去。只要做一点改装……', `MaleText_loc5`='我們能把這台船開進去。只要讓我做一些調整...', `MaleText_loc7`='Podemos utilizar este barco. Voy a hacerle un par de apaños...' WHERE `ID`=70774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자... 됐다! 사우록 척살 자주포야.', `MaleText_loc4`='啊……完成了！自行式蜥蜴人宰杀机。', `MaleText_loc5`='然後...大功告成!一台自動推進的薩烏洛克屠殺機器。', `MaleText_loc7`='¡Listo! Una máquina de matar saurok autopropulsada.' WHERE `ID`=70775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 명이 총을 맡게. 나머지는 걸어가지.', `MaleText_loc4`='一人操作机枪，其他人步行。', `MaleText_loc5`='一個去顧砲台，其他人步行。', `MaleText_loc7`='Que uno de ustedes controle las armas, el resto quédese alerta.' WHERE `ID`=70776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이는 건 모조리 죽이게!', `MaleText_loc4`='杀光那些爬虫！', `MaleText_loc5`='殺死所有會動的東西!', `MaleText_loc7`='¡Maten todo lo que se mueva!' WHERE `ID`=70777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악, 어떻게 좀 해 봐!', `MaleText_loc4`='哎呀，甩掉它！', `MaleText_loc5`='啊啊，把這鬼東西弄掉!', `MaleText_loc7`='¡Agh, quítennos esa cosa de encima!' WHERE `ID`=70778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배를 망가뜨리고 있잖아!', `MaleText_loc4`='他们在破坏我们的船！', `MaleText_loc5`='它們要把我們的船弄壞了!', `MaleText_loc7`='¡Están acabando con nuestro barco!' WHERE `ID`=70779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마술사를 처치해!', `MaleText_loc4`='干掉那个巫师！', `MaleText_loc5`='殺了那隻巫士!', `MaleText_loc7`='¡A por el hechicero!' WHERE `ID`=70780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈들을 배에서 떼어내게.', `MaleText_loc4`='让那些畜生离船远点！', `MaleText_loc5`='別讓那些野獸靠近船!', `MaleText_loc7`='Saquen a esas bestias del barco.' WHERE `ID`=70781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여길세! 여기 배를 세우게.', `MaleText_loc4`='到了！在这儿停船。', `MaleText_loc5`='停!把船停在這。', `MaleText_loc7`='¡Aquí! Pararemos aquí.' WHERE `ID`=70782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리즈, 배를 지켜라. 나머지는 날 따라오고.', `MaleText_loc4`='格里兹尔看着船。其他人跟我走。', `MaleText_loc5`='格里斯，在這裡守住船。其他人跟我走。', `MaleText_loc7`='Griz, tú vigila el barco. Los demás, vengan conmigo.' WHERE `ID`=70783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이거 받아! 무리를 상대하는 데 도움이 될 거라고.', `MaleText_loc4`='给！它能帮你对付虫子。', `MaleText_loc5`='拿著這個!這可以幫你對抗大批敵人。', `MaleText_loc7`='¡Tomen esto! Les ayudará contra cualquier plaga.' WHERE `ID`=70784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 나는 그냥 여기 있을게. 날 잊지 마!', `MaleText_loc4`='那我就……留下吧。好吧…别忘了我！', `MaleText_loc5`='我...我哪也不去。別忘了我!', `MaleText_loc7`='Yo... aquí me quedo. ¡No se olviden de mí!' WHERE `ID`=70785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우후후! 우낏의 아들! 찌릿찌릿해, 찌릿찌릿해. 다리도 저리고, 손도 저려. 꾸낏도 저려.', `MaleText_loc4`='喔吼！一个大王的儿子！手脚发麻。手脚发麻。腿没睡醒。手没睡醒。脑袋也没睡醒。', `MaleText_loc5`='哦呼!烏克媽媽耶!酸的要死啦，痛的要死啦。腳麻了。手也麻了。全身都麻了。', `MaleText_loc7`='¡Ayyy! ¡Hijo de Ook! ¡Qué daño! Se me han dormido las piernas. Se me han dormido las manos. Se me han dormido los mikos.' WHERE `ID`=70786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기는 일종의 부화실인 것 같군...', `MaleText_loc4`='这似乎是某种孵化室……', `MaleText_loc5`='這裡像是個孵化室...', `MaleText_loc7`='Esto es una especie de cámara de engendración.' WHERE `ID`=70787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게! 동굴이 무너지네!', `MaleText_loc4`='小心！洞顶塌了！', `MaleText_loc5`='小心!穴頂要坍塌了!', `MaleText_loc7`='¡Cuidado! ¡El techo se viene abajo!' WHERE `ID`=70788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으응? 황제라고? 나 황제 아니다, 작은 친구. 네 앞에 있는 건 원숭이 왕이야!', `MaleText_loc4`='喔？陛下？我可不是什么皇帝，小家伙。我是美猴王！', `MaleText_loc5`='哦哦?您?我才不是什麼帝王，小傢伙。你面前是美猴王!', `MaleText_loc7`='¿Uh? ¿Alteza? Yo no es emperador, pekeño. ¡Yo es el Rey Mono!' WHERE `ID`=70789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 생물들... 어딘가 부자연스러워.', `MaleText_loc4`='这些生物不太正常。', `MaleText_loc5`='這些東西有點不太對勁。', `MaleText_loc7`='Estas criaturas tienen algo antinatural.' WHERE `ID`=70790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와달라고? 넌 내가 옥 속에 영원히 갇히는 거 구해준 거야! 내가 지금껏 열렸던 연회 중 가장 큰 연회가 열리는 곳으로 보내준다!', `MaleText_loc4`='帮助？你把我从玉石里救出来了，不用一直被关着了！我要为你开一个最最大的派对！', `MaleText_loc5`='幫忙?你幫我從無窮無盡的翠玉牢裡解放出來!我要幫你辦個全世界最大的派對!', `MaleText_loc7`='¿Ayuda? ¡Tú me salva de una eternidad atrapado en jade! ¡Yo te va a montar la mayor fiesta de la historia!' WHERE `ID`=70791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 여기가 우리가 찾던 곳이다.', `MaleText_loc4`='这就是我们要找的地方。', `MaleText_loc5`='這就是我們要找的地方。', `MaleText_loc7`='Esta es la cámara que buscamos.' WHERE `ID`=70792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 모구와 이... 생물들이 관련돼 있다는 걸 알아내셨다.', `MaleText_loc4`='酋长发现魔古族与这些生物密切相关。', `MaleText_loc5`='大酋長發現魔古跟這些生物有某種程度上的關連。', `MaleText_loc7`='El Jefe de Guerra ha descubierto que existe una conexión entre los mogu y estas criaturas.' WHERE `ID`=70793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤! 부둔지 뭔지 좀 알지? 뭔가 알아내 보지그래?', `MaleText_loc4`='巨魔！你最了解这……巫毒玩意儿了。有何发现？', `MaleText_loc5`='食人妖!你應該懂這些巫毒術的玩意。看看能發現什麼?', `MaleText_loc7`='¡Trol! Tú eres el experto en esta cosa del vudú. ¿Qué puedes hacer?' WHERE `ID`=70794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그 없어진 조화의 망치 말하는 거야, 응? 이름이 참 바보같지. 그러니까 너 왕을 탓하려고 찾아온 거잖아?', `MaleText_loc4`='哦……那个丢失的祥和钟杵，是吗？真是个傻名字。那么你来找到美猴王，是要问罪于他？', `MaleText_loc5`='噢...那個失落的和諧之槌，是吧?真是個蠢名字。所以你找美猴王是來怪罪他把槌子搞丟了是吧?', `MaleText_loc7`='Ah... la marra armónika desaparecida. Ké nombre más tonto. ¿Tú viene a ver al Rey Mono porke es kulpa suya?' WHERE `ID`=70795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"부둔지 뭔지"라.', `MaleText_loc4`='“巫毒玩意儿”', `MaleText_loc5`='「巫毒術」', `MaleText_loc7`='"Esta cosa del vudú".' WHERE `ID`=70796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하하! 걱정하지 마. 제대로 온 거 맞아. 그런데 일단 너 얼굴에서 튀어나오는 걸 내가 좋아할지부터 좀 보자.', `MaleText_loc4`='啊哈哈哈！别担心，你来对地方了。但是先让我看看你的面相是不是讨喜。', `MaleText_loc5`='唉呦喂呀!別擔心，你來對地方了。但讓我先來瞧瞧我喜不喜歡你臉長得模樣。', `MaleText_loc7`='¡Ah, ja, ja! Tú no preokupa, ha venido al sitio korrekto. Pero antes, a ver si me gusta lo ke sale de tu kara.' WHERE `ID`=70797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조사할 동안 날 지켜 주게...', `MaleText_loc4`='掩护我，我要调查一下……', `MaleText_loc5`='調查的時候掩護我...', `MaleText_loc7`='Cúbranme mientras investigo…' WHERE `ID`=70798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 "모구"라는 놈들이 여기서 사악한 흑마법을 썼네.', `MaleText_loc4`='这些“魔古族”，在这里施了邪法。', `MaleText_loc5`='這些「魔古」在這裡進行邪惡的黑暗魔法。', `MaleText_loc7`='Esos "mogu" tiene una magia oscura y maligna aquí.' WHERE `ID`=70799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록은 태어난 게 아니라 창조되었네. 누군가 그 육신을 빚은 거야.', `MaleText_loc4`='蜥蜴人不是天生的——而是创造出来的。是扭曲成形的血肉。', `MaleText_loc5`='那些薩烏洛克，可不是自然生物 - 它們是被製造出來的。用血肉雕塑出來的。', `MaleText_loc7`='Los saurok no nacieron... fueron creados. Carne formada y moldeada.' WHERE `ID`=70800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 마법 중에서도 가장 악한 마법이야!', `MaleText_loc4`='这是最黑暗的魔法，伙计！', `MaleText_loc5`='這一定是最黑暗的魔法了，老兄!', `MaleText_loc7`='¡Es la más oscura de las magias, colega!' WHERE `ID`=70801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='과연! 육신을 빚어 전사를 만들어내는 힘. 바로 대족장님께서 원하시는 것이다!', `MaleText_loc4`='没错！能制造战士的血肉塑形之力。这……正合酋长之意！', `MaleText_loc5`='就是這個!塑造血肉、創造戰士的力量。這就是大酋長要的!', `MaleText_loc7`='¡Sí! El poder para moldear la carne y crear guerreros. ¡Esto es lo que quiere el Jefe de Guerra!' WHERE `ID`=70802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 신의 흉내를 내서 괴물을 만든다고? 그런 건 호드가 아니야!', `MaleText_loc4`='加尔鲁什想成为神？制造怪物？这有违部落精神！', `MaleText_loc5`='卡爾洛斯想要當神?創造怪物?這可不是部落的宗旨!', `MaleText_loc7`='¿Garrosh jugando a ser dios? ¿Creando monstruos? ¡Esto no es propio de la Horda!' WHERE `ID`=70803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역시 반역자였군.', `MaleText_loc4`='他早知道你是个叛徒。', `MaleText_loc5`='他知道你是叛徒。', `MaleText_loc7`='Él sabía que eras un traidor.' WHERE `ID`=70804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도- 도와줘-', `MaleText_loc4`='救——救命——', `MaleText_loc5`='救 - 命 -', `MaleText_loc7`='A-ayuda...' WHERE `ID`=70805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서는 적을 멸하신다!', `MaleText_loc4`='酋长之敌必亡！', `MaleText_loc5`='大酋長會消滅他所有的敵人!', `MaleText_loc7`='¡El Jefe de Guerra aniquilará a sus enemigos!' WHERE `ID`=70806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이... 자기 패를... 보였군.', `MaleText_loc4`='酋长……亮出了底牌。', `MaleText_loc5`='大...大酋長...終於露出真面目。', `MaleText_loc7`='El... Jefe de Guerra muestra... sus cartas.' WHERE `ID`=70807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밸브 부수는 중', `MaleText_loc4`='破坏阀门。', `MaleText_loc5`='破壞閥門。', `MaleText_loc7`='Romper la válvula.', `FemaleText_loc1`='밸브 부수는 중', `FemaleText_loc4`='破坏阀门。', `FemaleText_loc5`='破壞閥門。', `FemaleText_loc7`='Romper la válvula.' WHERE `ID`=70808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 어쩌다 이 지경에 이른 건가? 같은 호드를 죽이다니. 막아야 하네.', `MaleText_loc4`='这就是部落的现状？自相残杀？我们不能坐视不理。', `MaleText_loc5`='這就是部落選擇的路?殘殺同胞?我們不能讓這種事情發生。', `MaleText_loc7`='¿En esto se ha convertido la Horda? ¿Matar a los suyos? No podemos permitirlo.' WHERE `ID`=70809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들이 필요하네.', `MaleText_loc4`='勇士，我需要你。', `MaleText_loc5`='勇士，我需要你幫忙。', `MaleText_loc7`='Campeones, los necesito.' WHERE `ID`=70810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장에게 돌아가게. 내가 죽었다 전하고 곁에서 그를 감시하게.', `MaleText_loc4`='回去找酋长。告诉他我死了。跟紧他。看着他。', `MaleText_loc5`='回去找大酋長。告訴他我已經死了。待在他身邊。監視他。', `MaleText_loc7`='Vuelvan con el Jefe de Guerra. Díganle que he muerto. Quédense cerca de él. Vigílenlo.' WHERE `ID`=70811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들과 내가, 때가 되면 움직여 놈을 없애버려야 하네.', `MaleText_loc4`='你和我，我们将在适当的时机推翻他。', `MaleText_loc5`='你跟我聯手，等時機成熟了再一起幹掉他。', `MaleText_loc7`='Ustedes y yo actuaremos para acabar con él cuando llegue el momento.' WHERE `ID`=70812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 같은 이들이 또 있을 테니, 찾아 주게.', `MaleText_loc4`='还有和我一样的人。去找他们。', `MaleText_loc5`='其他像我這樣的人。你得找到他們。', `MaleText_loc7`='Hay otros como yo. Deben encontrarlos.' WHERE `ID`=70813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나와 피로 맹세하세.', `MaleText_loc4`='跟我发下血誓。', `MaleText_loc5`='發誓...跟我一起立下血誓。', `MaleText_loc7`='Hagan un juramento de sangre conmigo.' WHERE `ID`=70814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐네. 우리는 이제 형제일세. 죽을 때까지.', `MaleText_loc4`='好。你我结成兄弟。直到末日。', `MaleText_loc5`='啊啊...這樣就行了。我們兄弟齊心。直到最後一刻。', `MaleText_loc7`='Así será. Somos hermanos en esto. Hasta el final.' WHERE `ID`=70815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 잠시 몸을 숨겨야겠네. 날 잊지 말게.', `MaleText_loc4`='我得消失一段时间了。别忘了我。', `MaleText_loc5`='我會離開一陣子。[咳嗽]別忘了我說的話。', `MaleText_loc7`='Desapareceré por un tiempo. No me olviden.' WHERE `ID`=70816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 "왕"을 사자의 상륙지까지 데려가고, 우리에게 필요한 정보를 달라고 설득해 볼게요. 그러는 동안 당신은 원숭이 왕의 수수께끼를 풀어 보세요. 사자의 상륙지에서 다시 만나요.', `MaleText_loc4`='我会试着带这个“美猴王”回到雄师港，看看能不能说服他告诉我们所需要的信息。同时，我也会尽力解答他的谜题，在那儿和我们碰头吧。', `MaleText_loc5`='我會想辦法把這隻「王」帶回雄獅灘，試試看能不能說服他自願提供我們需要的資訊。同時，我也建議想想辦法去解開他的謎題然後在那裡碰頭。', `MaleText_loc7`='Intentaré llevar al "Rey" de vuelta al Desembarco del León para ver si lo convenzo de darnos la información que necesitamos. Entretanto, supongo que puedes intentar resolver sus acertijos y reunirte con nosotros más tarde.' WHERE `ID`=70817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 돼지들! 네놈들이 내 외아들을 죽였어!', `MaleText_loc4`='部落的畜生！你们杀了我唯一的儿子！！', `MaleText_loc5`='部落的豬玀!你殺死我唯一的兒子!!', `MaleText_loc7`='¡Cerdos de la Horda! ¡¡Matasteis a mi único hijo!!' WHERE `ID`=70818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='테라모어를 위해!', `MaleText_loc4`='为了塞拉摩！', `MaleText_loc5`='為了塞拉摩!', `MaleText_loc7`='¡Por Theramore!' WHERE `ID`=70819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바엘 모단을 위해!', `MaleText_loc4`='为了巴尔莫丹！', `MaleText_loc5`='為了巴爾莫丹!', `MaleText_loc7`='¡Por Bael Modan!' WHERE `ID`=70820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이 더러운 놈들! 너희 호드는 천치 같은 놈들이야. 방금 당한 게 그 증거고!', `MaleText_loc4`='这就对了，你们这些乌合之众！我这就证明给大家看，你们部落就是一堆羊屎！', `MaleText_loc5`='沒錯，你們這些混球!你們部落只是一堆羊糞而已，我剛剛已經證明過了!', `MaleText_loc7`='¡Ahí tenéis, chuchos! ¡La Horda no es más que una boñiga de oveja, y os lo acabo de demostrar!' WHERE `ID`=70821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포탄을 받아라!', `MaleText_loc4`='炮弹！！', `MaleText_loc5`='砲彈!!', `MaleText_loc7`='¡¡BOLA DE CAÑÓN!!' WHERE `ID`=70822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들은... 전부... 괴물이야...', `MaleText_loc4`='你们这些……畜生……*呸*', `MaleText_loc5`='你們全部...都是怪物...*噴口水*', `MaleText_loc7`='Monstruos... sois todos... monstruos.' WHERE `ID`=70823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 이제 시작하겠습니다.', `MaleText_loc4`='让我们开始吧。', `MaleText_loc5`='我們開始吧，', `MaleText_loc7`='Empecemos.' WHERE `ID`=70824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이길 생각은 하지도 마십시오.', `MaleText_loc4`='你毫无机会。', `MaleText_loc5`='你一點勝算也沒有。', `MaleText_loc7`='No tenías la más mínima posibilidad.' WHERE `ID`=70825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니? 어떻게 이럴 수 있는 거지!', `MaleText_loc4`='什么？这怎么可能！', `MaleText_loc5`='什麼?那怎麼可能!', `MaleText_loc7`='¿Qué? ¿Cómo es posible?' WHERE `ID`=70826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 애완동물에게도 싸워볼 기회를 좀 줘볼까요!', `MaleText_loc4`='让我们给其他人一点机会，让他们也搞点破坏！', `MaleText_loc5`='我們給別人點機會好搞點破壞吧!', `MaleText_loc7`='¡Tú también tendrás ocasión de hacer daño!' WHERE `ID`=70827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물들이 전부 살아남을 줄 알았습니까?', `MaleText_loc4`='你真以为你所有的宠物都能活下来？', `MaleText_loc5`='你真的以為你所有的寵物可以倖存?', `MaleText_loc7`='¿De verdad pensabas que sobrevivirían todas tus mascotas?' WHERE `ID`=70828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 제일 좋아하는 애완동물이었는데!', `MaleText_loc4`='不！那可是我最喜爱的宠物！', `MaleText_loc5`='不!那是我最喜歡的寵物!', `MaleText_loc7`='¡No! ¡Esa era mi mascota favorita!' WHERE `ID`=70829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 가로쉬가 천상의 종이라는 물건을 찾고 있단 말이지? 그게 뭔진 몰라도, 좋은 물건은 아닐 테지. 본부에 이 소식을 전하겠네.', `MaleText_loc4`='这就是说加尔鲁什也在寻找那个叫做圣钟的东西？不管那是什么，一定不是个好东西。我会让总部知道这个消息的。', `MaleText_loc5`='卡爾洛斯正在尋找一個叫做聖鐘的玩意?不管那是什麼，肯定不是好東西。我會把這個消息傳回給總部。', `MaleText_loc7`='Así que Garrosh busca algo llamado Campana divina... Sea lo que sea, no puede ser bueno. Llevaré esta información a la base.' WHERE `ID`=70830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하게 해냈군! 내 곧 다시 연락하지.', `MaleText_loc4`='干得好！我很快会再联系你。', `MaleText_loc5`='幹得好!我很快就會再跟你聯絡。', `MaleText_loc7`='¡Un trabajo excelente! Me pondré en contacto dentro de poco.' WHERE `ID`=70831;
