UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야, 잉구. 너네 애들 지키라고 지팡이 준 거지, 우낏 난동 피우라고 준 게 아니야!', `MaleText_loc4`='盎迦，我把这根棍子给你们是为了保护你们，不是给你用来该死的耍流氓的！', `MaleText_loc5`='印古，給你們魔棒是用來保護人民。不是給你拿來亂搞的!', `MaleText_loc7`='Ingoo, yo te da la vara para tu protección. ¡No para la dingue vandalismización!' WHERE `ID`=70836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야, 잉구. 지팡이 네 거 아니다. 그 지팡이가 너도 죽이기 전에 포기해.', `MaleText_loc4`='盎迦，棍子不是给你玩的，把它给我，不然它会把你也毁了。', `MaleText_loc5`='印古，魔棒不是給你一個人濫用的。在它摧毀你之前趕緊放棄吧!', `MaleText_loc7`='Ingoo, la vara no es tuya. Tú me la da antes de que te destruya a ti también.' WHERE `ID`=70837;
