UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 왔답시고 블러드힐트가 사자의 상륙지를 함락시킬 수 있다고 생각하나 보군요. 큰 오산이에요!', `MaleText_loc4`='如果血柄认为一点点援军就足够攻下雄师港，那他就大错特错了！', `MaleText_loc5`='如果血柄以為光靠一些後援就能佔領雄獅灘的話，他可就大錯特錯了!', `MaleText_loc7`='Si Sangrastil cree que basta con unos pocos refuerzos para tomar el Desembarco del León, ¡no tiene ni idea!' WHERE `ID`=70935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도우러 왔습니다.', `MaleText_loc4`='我们是来这儿帮忙的。', `MaleText_loc5`='我們趕來支援。', `MaleText_loc7`='Hemos venido a ayudar.', `FemaleText_loc1`='도우러 왔습니다.', `FemaleText_loc4`='我们是来这儿帮忙的。', `FemaleText_loc5`='我們趕來支援。', `FemaleText_loc7`='Hemos venido a ayudar.' WHERE `ID`=70936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 맞춰 오셨군요. 저기에 부대의 지휘관이 옵니다!', `MaleText_loc4`='来得也正好。这位就是进攻指挥官！', `MaleText_loc5`='來得真是即時。那個就是負責攻擊的指揮官!', `MaleText_loc7`='Justo a tiempo. ¡Aquí viene el comandante del asalto!' WHERE `ID`=70937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부대, 전투 준비!', `MaleText_loc4`='做好准备，小伙子们！', `MaleText_loc5`='準備好，兄弟們!', `MaleText_loc7`='¡Prepárense, muchachos!' WHERE `ID`=70938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노드와 님은 호드가 공격했을 때 잠수정을 이끌고 나갔다네.

그래도 그들의 장비랑 폭발물은 아직 여기 있지. 내가 잘 써야겠군.

여기서 방어선을 구축할 수 있을 걸세.', `MaleText_loc4`='诺德和尼姆在部落进攻时进了潜水艇。

但我依然能够合理利用他们的装备和炸药。

我们可以在前线阵地建立防线。', `MaleText_loc5`='諾德與妮姆在戰鬥潛艦裡受到部落的攻擊。

不過我還是想辦法收集到他們所有的裝置和炸藥來好好利用。

我們可以在前面設立一個防禦據點。', `MaleText_loc7`='Nodd y Nimm estaban en el sumergible cuando atacó la Horda.

Al menos hemos dado buen uso a todo su equipo y a sus explosivos.

Podemos establecer una posición defensiva en el frente.' WHERE `ID`=70939;
