UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모두 준비됐습니다.', `MaleText_loc4`='我们都准备好了。', `MaleText_loc5`='我們全部都準備好了。', `MaleText_loc7`='Estamos listos.', `FemaleText_loc1`='우리는 모두 준비됐습니다.', `FemaleText_loc4`='我们都准备好了。', `FemaleText_loc5`='我們全部都準備好了。', `FemaleText_loc7`='Estamos listos.' WHERE `ID`=70943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부관들은 다 죽거나 행방불명됐어요.', `MaleText_loc4`='我的指挥官们不是死了就是失踪了。', `MaleText_loc5`='我的指揮官不是死了，就是行蹤不明。', `MaleText_loc7`='Todos mis superiores están muertos o desaparecidos.' WHERE `ID`=70944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SI:7 팀에서 무슨 보고가 들어왔는지 확인해주세요. 호드가 얼마나 남았는지, 우리 병력은 얼마나 있는지 말이에요. 그리고 설리를 도와서 방어선을 구축해주세요.', `MaleText_loc4`='从军情七处那里给我报告——部落还剩下多少人，我们还剩下多少人——然后帮助苏利建立防线。', `MaleText_loc5`='拿份軍情七處的報告給我 - 還剩下多少部落，還有我們還剩下多少人 - 另外去幫忙蘇利設立幾個防禦據點。', `MaleText_loc7`='Ordena al equipo del IV:7 que informe de cuántos efectivos tiene la Horda y cuántos nos quedan a nosotros, y ayuda a Sully a preparar la defensa.' WHERE `ID`=70945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하세요! 호드가 곧 몰아칠겁니다.', `MaleText_loc4`='准备好！他们随时都有可能发起进攻。', `MaleText_loc5`='準備好!他們隨時都會衝過來。', `MaleText_loc7`='¡Atentos! Cargarán en cualquier momento.' WHERE `ID`=70946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 옵니다. 준비하세요!', `MaleText_loc4`='他们攻过来了！坚守阵地！', `MaleText_loc5`='他們來了!守好!', `MaleText_loc7`='¡Aquí vienen! ¡AGUANTEN!' WHERE `ID`=70947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 하고 있습니다! 저기 더 오는군요!', `MaleText_loc4`='就这么打，小伙子们！他们又来了！', `MaleText_loc5`='這就對了，兄弟們!馬上又要來了!', `MaleText_loc7`='¡Así se hace, muchachos! ¡Vienen más!' WHERE `ID`=70948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 부대, 조금만 더 버텨라! 절대 포기하지 마라!', `MaleText_loc4`='战斗到底，小伙子们！决不放弃！', `MaleText_loc5`='繼續加油，兄弟們!不要放棄!', `MaleText_loc7`='¡Sigan luchando, chicos! ¡NO SE RINDAN!' WHERE `ID`=70949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저게 마지막 공격입니다! 사자의 상륙지를 위하여!', `MaleText_loc4`='打得好！这是他们最后一波攻势！为了雄师港！', `MaleText_loc5`='這樣就對了!這是他們最後一波的攻勢!為了雄獅灘!', `MaleText_loc7`='¡Allá vamos! ¡El asalto final! ¡POR EL DESEMBARCO DEL LEÓN!' WHERE `ID`=70950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈습니다! 우리가 해냈다고요!', `MaleText_loc4`='我们守住了！我们做到了！', `MaleText_loc5`='我們成功了!我們成功了!', `MaleText_loc7`='¡Lo conseguimos! ¡LO CONSEGUIMOS!' WHERE `ID`=70951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속하십시오!$b$b두 지점에 덫 설치가 완료되면 공격이 시작됩니다.', `MaleText_loc4`='继续建造！$b$b一旦两座防御工事完成，进攻就将开始。', `MaleText_loc5`='繼續加油!$b$b一旦設立好兩個防禦據點以後他們就會進行攻擊。', `MaleText_loc7`='¡Seguid!$b$bEl ataque dará comienzo cuando hayamos construido dos defensas.', `FemaleText_loc1`='계속하십시오!$b$b두 지점에 덫 설치가 완료되면 공격이 시작됩니다.', `FemaleText_loc4`='继续建造！$b$b一旦两座防御工事完成，进攻就将开始。', `FemaleText_loc5`='繼續加油!$b$b一旦設立好兩個防禦據點以後他們就會進行攻擊。', `FemaleText_loc7`='¡Seguid!$b$bEl ataque dará comienzo cuando hayamos construido dos defensas.' WHERE `ID`=70952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF00ff00덫 설치 상황 +25|r', `MaleText_loc4`='|cFF00ff00+25建造进度|r', `MaleText_loc5`='|cFF00ff00+25建造進度|r', `MaleText_loc7`='|cFF00ff00+25 p. de progreso de construcción|r', `FemaleText_loc1`='|cFF00ff00덫 설치 상황 +25|r', `FemaleText_loc4`='|cFF00ff00+25建造进度|r', `FemaleText_loc5`='|cFF00ff00+25建造進度|r', `FemaleText_loc7`='|cFF00ff00+25 p. de progreso de construcción|r' WHERE `ID`=70953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 가고 싶어?', `MaleText_loc4`='你想去哪里？', `MaleText_loc5`='你想要去哪裡啊?', `MaleText_loc7`='¿Adónde kiere tú ir?' WHERE `ID`=70954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갈 곳이 너무 많아. 시간 없다. 어디 가?', `MaleText_loc4`='地方这么多，时间这么少。去哪儿呢，$G兄弟:姐妹;?', `MaleText_loc5`='有這麼多地方要去，但卻沒有時間。我們要去哪裡啊$G老兄:小姐;?', `MaleText_loc7`='¡Tantos sitios ke ver! ¿Adónde va makaku?' WHERE `ID`=70955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 이상한 냄새 난다.', `MaleText_loc4`='有股怪味儿。', `MaleText_loc5`='什麼東西味道怪怪的。', `MaleText_loc7`='Algo huele mal.' WHERE `ID`=70956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF00ff00덫 설치 상황: 속도가 빨라졌습니다!|r', `MaleText_loc4`='|cFF00ff00建造进度：速率提升！|r', `MaleText_loc5`='|cFF00ff00+25建造進度:速度提高|r', `MaleText_loc7`='|cFF00ff00¡Ritmo de progreso de construcción aumentado!|r', `FemaleText_loc1`='|cFF00ff00덫 설치 상황: 속도가 빨라졌습니다!|r', `FemaleText_loc4`='|cFF00ff00建造进度：速率提升！|r', `FemaleText_loc5`='|cFF00ff00+25建造進度:速度提高|r', `FemaleText_loc7`='|cFF00ff00¡Ritmo de progreso de construcción aumentado!|r' WHERE `ID`=70957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올 때가 됐는데 왜 안 오나 하고 있었죠, $n. 이 전투는 가만히 있어도 이길 수 있는 그런 전투가 아닙니다!', `FemaleText_loc4`='你终于来了，$n。什么都不做可赢不了这场战斗！', `FemaleText_loc5`='你終於到了，$n。沒你可是打不贏這場戰爭!', `FemaleText_loc7`='Ya era hora de que llegaras, $n. Esta batalla no se va a ganar sola.' WHERE `ID`=70958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF00ff00덫 설치 상황 +5|r', `MaleText_loc4`='|cFF00ff00+5建造进度|r', `MaleText_loc5`='|cFF00ff00+5建造進度|r', `MaleText_loc7`='|cFF00ff00+5 p. de progreso de construcción|r', `FemaleText_loc1`='|cFF00ff00덫 설치 상황 +5|r', `FemaleText_loc4`='|cFF00ff00+5建造进度|r', `FemaleText_loc5`='|cFF00ff00+5建造進度|r', `FemaleText_loc7`='|cFF00ff00+5 p. de progreso de construcción|r' WHERE `ID`=70959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 배신하는 자들은 모두 궤멸시키겠다!', `MaleText_loc4`='部落必须肃清所有叛徒！', `MaleText_loc5`='把所有的叛徒通通趕出部落!', `MaleText_loc7`='¡Identificaremos a todos los traidores de la Horda!', `FemaleText_loc1`='호드를 배신하는 자들은 모두 궤멸시키겠다!', `FemaleText_loc4`='部落必须肃清所有叛徒！', `FemaleText_loc5`='把所有的叛徒通通趕出部落!', `FemaleText_loc7`='¡Identificaremos a todos los traidores de la Horda!' WHERE `ID`=70960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불화의 근원인 이 잡종들을 없애버리겠다!', `MaleText_loc4`='我们要把所有异端从这群杂种中找出来，清除出去！', `MaleText_loc5`='給我打!看這些廢物還敢有什麼意見!', `MaleText_loc7`='¡Extirparemos la disensión de estos animales!', `FemaleText_loc1`='불화의 근원인 이 잡종들을 없애버리겠다!', `FemaleText_loc4`='我们要把所有异端从这群杂种中找出来，清除出去！', `FemaleText_loc5`='給我打!看這些廢物還敢有什麼意見!', `FemaleText_loc7`='¡Extirparemos la disensión de estos animales!' WHERE `ID`=70961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 코르크론의 문제다! 더는 관여하지 마라.', `MaleText_loc4`='库卡隆办事！没什么好看的。', `MaleText_loc5`='柯爾克隆在執行公務!沒什麼好看的。', `MaleText_loc7`='Esto es un asunto Kor''kron. Circula.', `FemaleText_loc1`='이건 코르크론의 문제다! 더는 관여하지 마라.', `FemaleText_loc4`='库卡隆办事！没什么好看的。', `FemaleText_loc5`='柯爾克隆在執行公務!沒什麼好看的。', `FemaleText_loc7`='Esto es un asunto Kor''kron. Circula.' WHERE `ID`=70962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인부의 공구를 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `MaleText_loc4`='在任何防御工事使用劳工的工具来提升建造进度！$B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `MaleText_loc5`='在任意一個建築工地使用苦力的工具以提高建造進度! $B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `MaleText_loc7`='¡Utiliza la herramienta de obrero en cualquier zona de construcción para aumentar su progreso! $B$B|TInterfaceIconsINV_HAMMER_17.blp:64|t', `FemaleText_loc1`='인부의 공구를 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `FemaleText_loc4`='在任何防御工事使用劳工的工具来提升建造进度！$B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `FemaleText_loc5`='在任意一個建築工地使用苦力的工具以提高建造進度! $B$B|TInterface\\Icons\\INV_HAMMER_17.blp:64|t', `FemaleText_loc7`='¡Utiliza la herramienta de obrero en cualquier zona de construcción para aumentar su progreso! $B$B|TInterfaceIconsINV_HAMMER_17.blp:64|t' WHERE `ID`=70963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때로는 일단 밀고 나가는 게 필요하다네. 그 때문에 이것저것 좀 부서지는 한이 있더라도 말이야!', `MaleText_loc4`='有些事情必须做好，哪怕它意味着要损失一些其他的东西！', `MaleText_loc5`='有些事情非做不可，就算得打破一些玩意兒也在所不惜!', `MaleText_loc7`='A veces hay que hacer lo que hay que hacer... ¡aunque eso implique romper un par de cosas!' WHERE `ID`=70964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투 식량을 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `MaleText_loc4`='在任何防御工事使用作战给养来提升建造进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `MaleText_loc5`='在任何一個建築工地使用軍糧以加快該處的進展速度!$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `MaleText_loc7`='¡Utiliza las raciones de batalla en cualquier zona de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_MISC_FOOD_WHEAT_02.blp:64|t', `FemaleText_loc1`='전투 식량을 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `FemaleText_loc4`='在任何防御工事使用作战给养来提升建造进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `FemaleText_loc5`='在任何一個建築工地使用軍糧以加快該處的進展速度!$B$B|TInterface\\Icons\\INV_MISC_FOOD_WHEAT_02.blp:64|t', `FemaleText_loc7`='¡Utiliza las raciones de batalla en cualquier zona de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_MISC_FOOD_WHEAT_02.blp:64|t' WHERE `ID`=70965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진과 함께 이 땅에 처음 왔던 때가 기억나는군. 그땐 호드를 만든다는 건 그냥 생각뿐이었지. 희망이었고. 우리는 다른 누군가가 필요했다네.', `MaleText_loc4`='我还记得我和沃金第一次踏上这片土地的时候。那时的部落还只是一个想法。一个憧憬。那时的我们需要彼此。', `MaleText_loc5`='我記得沃金和我第一次來到這片土地的時候。那時，部落只是個概念，是個理想。各個種族需要彼此。', `MaleText_loc7`='Me acuerdo de cuando Vol''jin y yo llegamos a esta tierra por primera vez. Por aquel entonces la Horda solo era una idea. Una esperanza. Nos necesitábamos mutuamente.' WHERE `ID`=70966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 이 사막에 집을 짓고, 서리늑대 부족의 족장이셨던 내 아버지의 이름을 그대로 붙여 듀로탄이라고 이름지었네.', `MaleText_loc4`='我们在这片沙漠上建起了自己的家园，用我父亲霜狼氏族酋长杜隆坦的名字命名了它。', `MaleText_loc5`='我們以這片沙漠為家，以我父親，霜狼氏族的大酋長，杜洛坦的名字為它命名。', `MaleText_loc7`='Establecimos nuestro hogar en este desierto, y lo nombramos en honor a mi padre, Durotan, jefe del clan Lobo Gélido.' WHERE `ID`=70967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사막은 살기가 하주 혹독한 땅이었지. 몇 번이고 호드의 생존을 책임지고, 굶주림을 해소시켜주거나, 우리가 공격당했을 때 무기를 들고 맞섰던 건 바로 볼진과 그 백성들이었네.', `MaleText_loc4`='这并非是一片慷慨的土地。一次又一次，是沃金和他的人民用食物拯救我们于饥饿，用武器保护我们于战乱，从而保全了部落。', `MaleText_loc5`='這是一片嚴酷的大地。那時，是沃金和他的族人讓部落得以生存下去，讓我們免於飢餓，在我們遭受攻擊的時候保衛了大家。', `MaleText_loc7`='Era una tierra dura. Una y otra vez, Vol''jin y su gente garantizaron la supervivencia de la Horda: nos salvaban de la hambruna o tomaban las armas cuando nos atacaban.' WHERE `ID`=70968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤과 오크는 하나가 되어 싸워왔고, 하나가 되어 목숨을 잃었네. 우리는 가족일세. 그러니 가족이 그 구성원을 돌봐야지.', `MaleText_loc4`='巨魔和兽人曾经并肩作战，生死与共。我们是一家人，家人就该彼此照料。', `MaleText_loc5`='食人妖和獸人一直並肩作戰，一同戰死沙場。我們是一家人，家人會彼此照料。', `MaleText_loc7`='Los trols y los orcos hemos luchado juntos y muerto juntos. Somos una familia. Y las familias se protegen.' WHERE `ID`=70969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부러질 듯한 뿌리를 특정 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `MaleText_loc4`='在特定的建筑营地使用脆弱的根茎来加快他们的进度！$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `MaleText_loc5`='在選定的建築工地用脆弱的樹根以加快他們的進展速度!$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `MaleText_loc7`='¡Utiliza raíces frágiles en ciertas zonas de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_WEAPON_SHORTBLADE_09.blp:64|t', `FemaleText_loc1`='부러질 듯한 뿌리를 특정 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `FemaleText_loc4`='在特定的建筑营地使用脆弱的根茎来加快他们的进度！$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `FemaleText_loc5`='在選定的建築工地用脆弱的樹根以加快他們的進展速度!$B$B|TInterface\\Icons\\INV_WEAPON_SHORTBLADE_09.blp:64|t', `FemaleText_loc7`='¡Utiliza raíces frágiles en ciertas zonas de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_WEAPON_SHORTBLADE_09.blp:64|t' WHERE `ID`=70970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀림 홉을 판다렌 건설 현장에 있는 펑맥주 가마솥에 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `MaleText_loc4`='在熊猫人建筑营地的爆烈酒大锅处使用丛林啤酒花来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `MaleText_loc5`='在熊貓人工地對著疾釀大釜使用叢林啤酒花以加快進展速度!$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `MaleText_loc7`='¡Utiliza los lúpulos de la selva en la caldera de bombabirra de la zona de construcción pandaren para aumentar el progreso! $B$B|TInterfaceIconsINV_MISC_HERB_08.blp:64|t', `FemaleText_loc1`='밀림 홉을 판다렌 건설 현장에 있는 펑맥주 가마솥에 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `FemaleText_loc4`='在熊猫人建筑营地的爆烈酒大锅处使用丛林啤酒花来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `FemaleText_loc5`='在熊貓人工地對著疾釀大釜使用叢林啤酒花以加快進展速度!$B$B|TInterface\\Icons\\INV_MISC_HERB_08.blp:64|t', `FemaleText_loc7`='¡Utiliza los lúpulos de la selva en la caldera de bombabirra de la zona de construcción pandaren para aumentar el progreso! $B$B|TInterfaceIconsINV_MISC_HERB_08.blp:64|t' WHERE `ID`=70971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사리 철을 드워프나 노움 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `MaleText_loc4`='在矮人或侏儒建造营地使用卡桑利生铁来加快他们的进度！$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `MaleText_loc5`='在矮人或地精建築工地使用喀撒利鐵礦以加快他們的進展速度!$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `MaleText_loc7`='¡Utiliza el hierro Krasari en las zonas de construcción enanas o gnómicas para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_ORE_PLATINUM_01.blp:64|t', `FemaleText_loc1`='크라사리 철을 드워프나 노움 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `FemaleText_loc4`='在矮人或侏儒建造营地使用卡桑利生铁来加快他们的进度！$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `FemaleText_loc5`='在矮人或地精建築工地使用喀撒利鐵礦以加快他們的進展速度!$B$B|TInterface\\Icons\\INV_ORE_PLATINUM_01.blp:64|t', `FemaleText_loc7`='¡Utiliza el hierro Krasari en las zonas de construcción enanas o gnómicas para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_ORE_PLATINUM_01.blp:64|t' WHERE `ID`=70972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='액화 불길을 판다렌 건설 현장에 있는 펑맥주 가마솥에 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `MaleText_loc4`='在熊猫人建筑营地的爆烈酒大锅处使用燃烧剂来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `MaleText_loc5`='在熊貓人工地對著疾釀大釜使用液態火焰以加快進展速度!$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `MaleText_loc7`='¡Utiliza el fuego líquido en la caldera de bombabirra de la zona de construcción pandaren para aumentar el progreso! $B$B|TInterfaceIconsABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `FemaleText_loc1`='액화 불길을 판다렌 건설 현장에 있는 펑맥주 가마솥에 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `FemaleText_loc4`='在熊猫人建筑营地的爆烈酒大锅处使用燃烧剂来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `FemaleText_loc5`='在熊貓人工地對著疾釀大釜使用液態火焰以加快進展速度!$B$B|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERS.blp:64|t', `FemaleText_loc7`='¡Utiliza el fuego líquido en la caldera de bombabirra de la zona de construcción pandaren para aumentar el progreso! $B$B|TInterfaceIconsABILITY_WARLOCK_BURNINGEMBERS.blp:64|t' WHERE `ID`=70973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살이 많은 볼깃살을 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `MaleText_loc4`='在任何一个建筑营地使用肥厚腰肉来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `MaleText_loc5`='在任何一個建築工地使用肥嫩肉塊以加快該處的進展速度!$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `MaleText_loc7`='¡Utiliza el anca carnosa en cualquier zona de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_MISC_FOOD_50.blp:64|t', `FemaleText_loc1`='살이 많은 볼깃살을 아무 건설 현장에서나 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `FemaleText_loc4`='在任何一个建筑营地使用肥厚腰肉来加快他们的进度！$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `FemaleText_loc5`='在任何一個建築工地使用肥嫩肉塊以加快該處的進展速度!$B$B|TInterface\\Icons\\INV_MISC_FOOD_50.blp:64|t', `FemaleText_loc7`='¡Utiliza el anca carnosa en cualquier zona de construcción para aumentar su ritmo de progreso! $B$B|TInterfaceIconsINV_MISC_FOOD_50.blp:64|t' WHERE `ID`=70974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엉뚱한 곳에 놓인 맥주통을 판다렌 건설 현장에서 사용하면 덫 설치 속도가 영구적으로 증가합니다!$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `MaleText_loc4`='在熊猫人建筑营地使用失踪的酒桶来永久提高他们的进度！$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `MaleText_loc5`='在熊貓人工地使用不該出現的酒桶以永久加快該處的進展速度!$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `MaleText_loc7`='¡Utiliza el barril extraviado en la zona de construcción pandaren para aumentar permanentemente su ritmo de progreso! $B$B|TInterfaceIconsINV_CASK_04.blp:64|t', `FemaleText_loc1`='엉뚱한 곳에 놓인 맥주통을 판다렌 건설 현장에서 사용하면 덫 설치 속도가 영구적으로 증가합니다!$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `FemaleText_loc4`='在熊猫人建筑营地使用失踪的酒桶来加快他们的进度！$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `FemaleText_loc5`='在熊貓人工地使用不該出現的酒桶以永久加快該處的進展速度!$B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t', `FemaleText_loc7`='¡Utiliza el barril extraviado en la zona de construcción pandaren para aumentar permanentemente su ritmo de progreso! $B$B|TInterfaceIconsINV_CASK_04.blp:64|t' WHERE `ID`=70975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 이것만은 기억하라. 비록 여러 수장들이 잊고 있어도 호드는 한 가족이라는 것을. 이를 증명하기 위해 나는 볼진이 돌아올 때까지 자네들이 선출한 지도자를 도와주겠다.', `MaleText_loc4`='但记住这一点，部落是所有部落人民的家，这个事实不会因为某些部落领袖忘记了它而改变。为了证明这一点，我会留在你们身边，并将我的力量借给你们挑选的领袖，直至沃金回归。', `MaleText_loc5`='但是請大家記住，部落是個大家庭...即使某些領導人已經忘記了。為了證明這一點，我會留在這裡盡全力幫助大家，直到沃金回來。', `MaleText_loc7`='Sepan que la Horda es una familia, aunque algunos de sus líderes lo hayan olvidado. Para demostrarlo, me quedaré con ustedes y prestaré toda la ayuda que pueda a sus líderes electos hasta el regreso de Vol''jin.' WHERE `ID`=70976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뱀 기름을 나이트 엘프나 노움 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `MaleText_loc4`='在暗夜精灵或侏儒建筑营地使用蛇油来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `MaleText_loc5`='在夜精靈或地精建築工地使用蛇油以加快他們的進展速度!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `MaleText_loc7`='¡Utiliza el aceite de culebra en las zonas de construcción gnómicas o de los elfos de la noche para aumentar su ritmo de progreso! $B$B|TInterfaceIconsABILITY_VEHICLE_OILJETS.blp:64|t', `FemaleText_loc1`='뱀 기름을 나이트 엘프나 노움 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `FemaleText_loc4`='在暗夜精灵或侏儒建筑营地使用蛇油来加快他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `FemaleText_loc5`='在夜精靈或地精建築工地使用蛇油以加快他們的進展速度!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_OILJETS.blp:64|t', `FemaleText_loc7`='¡Utiliza el aceite de culebra en las zonas de construcción gnómicas o de los elfos de la noche para aumentar su ritmo de progreso! $B$B|TInterfaceIconsABILITY_VEHICLE_OILJETS.blp:64|t' WHERE `ID`=70977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$p, 오늘 일어난 일은 부디 가로쉬에게 말하지 말게. 내가 그를 대면하기 전에 내려야 할 결정이 많다네.', `MaleText_loc4`='$p，请不要让加尔鲁什知道今天发生在这里的一切。在和他直接对抗之前，我还有一些非常重要的事情需要思考。', `MaleText_loc5`='$p，請別告訴卡爾洛斯我們今天在這裡做了什麼。在我直接面對他之前，還有些重要的決定得做。', `MaleText_loc7`='Hazme un favor, $p: no le digas a Garrosh lo que ha pasado aquí hoy. Debo tomar decisiones muy importantes antes de enfrentarme a él directamente.' WHERE `ID`=70978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 깃든 물로 달인 브라운스톤을 깨우세요. 정령 깃든 물을 판다렌이나 나이트 엘프 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `MaleText_loc4`='灵吻之水能唤醒褐石大师，或者用来加快熊猫人或者暗夜精灵建筑营地的进度！$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `MaleText_loc5`='魂靈親吻之水可以喚醒褐石大師、加快熊貓人建築工地的進展、或者提高夜精靈建築工地的進展速度!$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `MaleText_loc7`='¡El agua besada por los espíritus despertará al maestro Piedra Cobriza, aumentará el progreso de una zona de construcción pandaren, o aumentara el ritmo de progreso de una zona de construcción de los elfos de la noche! $B$B|TInterfaceIconsINV_MISC_VOLATILEWATER.blp:64|t', `FemaleText_loc1`='정령 깃든 물로 달인 브라운스톤을 깨우세요. 정령 깃든 물을 판다렌이나 나이트 엘프 건설 현장에서 사용하면 덫 설치 속도가 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `FemaleText_loc4`='灵吻之水能唤醒褐石大师，或者用来加快熊猫人或者暗夜精灵建筑营地的进度！$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `FemaleText_loc5`='魂靈親吻之水可以喚醒褐石大師、加快熊貓人建築工地的進展、或者提高夜精靈建築工地的進展速度!$B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t', `FemaleText_loc7`='¡El agua besada por los espíritus despertará al maestro Piedra Cobriza, aumentará el progreso de una zona de construcción pandaren, o aumentara el ritmo de progreso de una zona de construcción de los elfos de la noche! $B$B|TInterfaceIconsINV_MISC_VOLATILEWATER.blp:64|t' WHERE `ID`=70979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불발 포탄을 드워프 건설 현장에서 사용하면 덫 설치 속도가 영구적으로 증가합니다!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `MaleText_loc4`='在矮人建筑营地使用哑火炮弹来永久提高他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `MaleText_loc5`='在矮人建築工地使用未爆炸的砲彈以永久加快該處的進展速度!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `MaleText_loc7`='¡Utiliza la bola de cañón sin explotar en la zona de construcción enana para aumentar permanentemente su ritmo de progreso! $B$B|TInterfaceIconsABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `FemaleText_loc1`='불발 포탄을 드워프 건설 현장에서 사용하면 덫 설치 속도가 영구적으로 증가합니다!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `FemaleText_loc4`='在矮人建筑营地使用哑火炮弹来永久提高他们的进度！$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `FemaleText_loc5`='在矮人建築工地使用未爆炸的砲彈以永久加快該處的進展速度!$B$B|TInterface\\Icons\\ABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t', `FemaleText_loc7`='¡Utiliza la bola de cañón sin explotar en la zona de construcción enana para aumentar permanentemente su ritmo de progreso! $B$B|TInterfaceIconsABILITY_VEHICLE_SIEGEENGINECANNON.blp:64|t' WHERE `ID`=70980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진위 작업반장 장로 애들러와 대화하세요. 애들러가 장식된 홀을 사용하면 진위 건설 현장의 덫 설치 속도가 영구적으로 크게 증가합니다!$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `MaleText_loc4`='和锦鱼人长老阿德勒交谈，他会使用缀饰权杖来显著提高锦鱼人营地的进度！$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `MaleText_loc5`='去找錦魚人的工頭長者埃德勒談談，他會用敬飾權杖大幅度地永久提高錦魚人的進展速度!$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `MaleText_loc7`='Habla con el supervisor jinyu, el ancestro Adler, quien utilizará el cetro adornado para aumentar de forma considerable y permanente el ritmo de progreso jinyu. $B$B|TInterfaceIconsINV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `FemaleText_loc1`='진위 작업반장 장로 애들러와 대화하세요. 애들러가 장식된 홀을 사용하면 진위 건설 현장의 덫 설치 속도가 영구적으로 크게 증가합니다!$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `FemaleText_loc4`='和锦鱼人长老阿德勒交谈，他会使用缀饰权杖来显著提高锦鱼人营地的进度！$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `FemaleText_loc5`='去找錦魚人的工頭長者埃德勒談談，他會用敬飾權杖大幅度地永久提高錦魚人的進展速度!$B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t', `FemaleText_loc7`='Habla con el supervisor jinyu, el ancestro Adler, quien utilizará el cetro adornado para aumentar de forma considerable y permanente el ritmo de progreso jinyu. $B$B|TInterfaceIconsINV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t' WHERE `ID`=70981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노움 작업반장 로지 액슬로드와 대화하세요. 로지가 젖은 일지를 사용하면 노움 건설 현장의 덫 설치 속도가 영구적으로 크게 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `MaleText_loc4`='和侏儒工头罗塞·轮轴交谈，她会使用浸水的日记来显著提高侏儒营地的进度！ $B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `MaleText_loc5`='去找地精的工頭玫瑰·愛瑟羅德談談，她會用濕透的日記大幅度地永久提高地精的進展速度!$B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `MaleText_loc7`='Habla con la supervisora gnoma, Rosey Barraeje, quien utilizará el diario empapado para aumentar de forma considerable y permanente el ritmo de progreso gnómico. $B$B|TInterfaceIconsINV_MISC_BOOK_11.blp:64|t', `FemaleText_loc1`='노움 작업반장 로지 액슬로드와 대화하세요. 로지가 젖은 일지를 사용하면 노움 건설 현장의 덫 설치 속도가 영구적으로 크게 증가합니다!$B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `FemaleText_loc4`='和侏儒工头罗塞·轮轴交谈，她会使用浸水的日记来显著提高侏儒营地的进度！ $B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `FemaleText_loc5`='去找地精的工頭玫瑰·愛瑟羅德談談，她會用濕透的日記大幅度地永久提高地精的進展速度!$B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t', `FemaleText_loc7`='Habla con la supervisora gnoma, Rosey Barraeje, quien utilizará el diario empapado para aumentar de forma considerable y permanente el ritmo de progreso gnómico. $B$B|TInterfaceIconsINV_MISC_BOOK_11.blp:64|t' WHERE `ID`=70982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 키엔의 손이 샤 발톱으로 변합니다!', `MaleText_loc4`='单简的手畸变成了煞之爪！', `MaleText_loc5`='衫·基恩的手變形成煞的利爪!', `MaleText_loc7`='¡La mano de Shan Kien se convierte en una garra de sha!' WHERE `ID`=70983;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 키엔의 눈이 샤 마법으로 빛납니다!', `MaleText_loc4`='单简的眼睛闪耀着煞能的光芒！', `MaleText_loc5`='衫·基恩的眼睛發出煞魔法的光芒!', `MaleText_loc7`='¡Los ojos de Shan Kien brillan con magia de sha!' WHERE `ID`=70984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 영웅이 우리 랩터들을 풀어줬다!', `MaleText_loc4`='哟，朋友！有位英雄在释放我们的迅猛龙！', `MaleText_loc5`='嘿，老兄!有個英雄救出了我們的迅猛龍!', `MaleText_loc7`='¡Colega! ¡$gUn héroe:Una heroína; ha liberado a nueh''tros raptores!', `FemaleText_loc1`='좋았어! 영웅이 우리 랩터들을 풀어줬다!', `FemaleText_loc4`='哟，朋友！有位英雄在释放我们的迅猛龙！', `FemaleText_loc5`='嘿，老兄!有個英雄救出了我們的迅猛龍!', `FemaleText_loc7`='¡Colega! ¡$gUn héroe:Una heroína; ha liberado a nueh''tros raptores!' WHERE `ID`=70985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 배신자가 아니야! 다시는 날 가두지 못한다.', `MaleText_loc4`='别当叛徒，朋友！你休想再把我锁起来。', `MaleText_loc5`='老兄，我可不是叛徒!你不能再把我銬起來了。', `MaleText_loc7`='¡Yo no soy un traidor, colega! A mí no me vuelves a esposar.', `FemaleText_loc1`='난 배신자가 아니야! 다시는 날 가두지 못한다.', `FemaleText_loc4`='别当叛徒，朋友！你休想再把我锁起来。', `FemaleText_loc5`='老兄，我可不是叛徒!你不能再把我銬起來了。', `FemaleText_loc7`='¡Yo no soy un traidor, colega! A mí no me vuelves a esposar.' WHERE `ID`=70986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 검은창 부족은 쇠사슬이랑은 안 어울리지. 왜 그런지는 곧 알게 될거야...', `MaleText_loc4`='我们暗矛巨魔不能被链子拴起来。你马上就会明白这一点了……', `MaleText_loc5`='老兄，我們暗矛部族可不喜歡被鎖鍊束縛。你會嚐到苦果的...很快就會。', `MaleText_loc7`='A los Lanza Negra no nos guh''ta llevar cadenas, colega. Pronto lo deh''cubrirás... por las malas.', `FemaleText_loc1`='우리 검은창 부족은 쇠사슬이랑은 안 어울리지. 왜 그런지는 곧 알게 될거야...', `FemaleText_loc4`='我们暗矛巨魔不能被链子拴起来。你马上就会明白这一点了……', `FemaleText_loc5`='老兄，我們暗矛部族可不喜歡被鎖鍊束縛。你會嚐到苦果的...很快就會。', `FemaleText_loc7`='A los Lanza Negra no nos guh''ta llevar cadenas, colega. Pronto lo deh''cubrirás... por las malas.' WHERE `ID`=70987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님께서는 우리를 심문하는걸 원치 않으셨을텐데.', `MaleText_loc4`='沃金不会允许你这样质疑我们。', `MaleText_loc5`='沃金可沒有同意你這樣質問我們。', `MaleText_loc7`='Vol''jin no te ha dado permiso p''a interrogarnos así.', `FemaleText_loc1`='볼진 님께서는 우리를 심문하는걸 원치 않으셨을텐데.', `FemaleText_loc4`='沃金不会允许你这样质疑我们。', `FemaleText_loc5`='沃金可沒有同意你這樣質問我們。', `FemaleText_loc7`='Vol''jin no te ha dado permiso p''a interrogarnos así.' WHERE `ID`=70988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 너희에게 놀아나지 않는다, 덜 떨어진 코르크론 놈들!', `MaleText_loc4`='休想这样对待我们，没脑子的库卡隆！', `MaleText_loc5`='你這個低能的柯爾克隆，你不會再先我們一步了!', `MaleText_loc7`='¡No volverás a meteh''te con nosotros, Kor''kron eh''túpido!', `FemaleText_loc1`='더는 너희에게 놀아나지 않는다, 덜 떨어진 코르크론 놈들!', `FemaleText_loc4`='休想这样对待我们，没脑子的库卡隆！', `FemaleText_loc5`='你這個低能的柯爾克隆，你不會再先我們一步了!', `FemaleText_loc7`='¡No volverás a meteh''te con nosotros, Kor''kron eh''túpido!' WHERE `ID`=70989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='--반갑습니다, $P. 제 뒤의 길을 따라 내려가십시오. 강력한 마법사이자 고귀한 혈통의 귀족이신 롬매스 님이 당신의 도착을 기다리고 계십니다.--', `MaleText_loc4`='——你好，$P。请进入本单位后方的通道。尊敬而强大的大法师罗曼斯希望你马上去见他。——', `MaleText_loc5`='$P，你好。請朝本單位後方的隧道繼續前進。崇高而強大的大博學者洛摩斯等待你的到來。', `MaleText_loc7`='--SALUDOS, $P. AVANZA POR EL TÚNEL QUE HAY DETRÁS DE ESTA UNIDAD. SU ALTEZA Y DESTREZA, EL GRAN MAGISTER ROMMATH, ESPERA TU LLEGADA.--' WHERE `ID`=70990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 이제 어떻게 될지, 넌 아무것도 모른다!', `MaleText_loc4`='你对即将降临的厄运一无所知！', `MaleText_loc5`='你不明白前面有什麼在等著你!', `MaleText_loc7`='¡No tienes ni idea de lo que te espera!', `FemaleText_loc1`='네가 이제 어떻게 될지, 넌 아무것도 몰라!', `FemaleText_loc4`='你对即将降临的厄运一无所知！', `FemaleText_loc5`='你不明白前面有什麼在等著你!', `FemaleText_loc7`='¡No tienes ni idea de lo que te espera!' WHERE `ID`=70991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스카가쉬 님이 얼라이언스는 한 놈도 이 밀림에서 빠져나가지 못하게 하실 거다!', `MaleText_loc4`='斯卡戈什不会放任何联盟逃出这片丛林！', `MaleText_loc5`='疤口不會讓任何聯盟份子逃出叢林的!', `MaleText_loc7`='¡Sangrescara no permitirá que ningún miembro de la Alianza huya de la selva!', `FemaleText_loc1`='스카가쉬 님이 얼라이언스는 한 놈도 이 밀림에서 빠져나가지 못하게 하실 거야!', `FemaleText_loc4`='斯卡戈什不会放任何联盟逃出这片丛林！', `FemaleText_loc5`='疤口不會讓任何聯盟份子逃出叢林的!', `FemaleText_loc7`='¡Sangrescara no permitirá que ningún miembro de la Alianza huya de la selva!' WHERE `ID`=70992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사령관님이 얼라이언스 국왕을 없애 주실 거다!', `MaleText_loc4`='指挥官会把联盟国王的脑袋刺在长矛上！', `MaleText_loc5`='指揮官會拿下聯盟國王的首級!', `MaleText_loc7`='¡El comandante se llevará la cabeza del rey de la Alianza clavada en una estaca!', `FemaleText_loc1`='사령관님이 얼라이언스 국왕을 없애 주실 것이다!', `FemaleText_loc4`='指挥官会把联盟国王的脑袋刺在长矛上！', `FemaleText_loc5`='指揮官會拿下聯盟國王的首級!', `FemaleText_loc7`='¡El comandante se llevará la cabeza del rey de la Alianza clavada en una estaca!' WHERE `ID`=70993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕을 불러라, $r! 놈을 끌어내!', `MaleText_loc4`='向你们的国王求救吧，$r！把他拖进来！', `MaleText_loc5`='$rt，呼叫你的國王!讓他過來!', `MaleText_loc7`='¡Llama a tu rey, $rt! ¡Tráelo aquí!', `FemaleText_loc1`='국왕을 불러, $r! 놈을 끌어내라고!', `FemaleText_loc4`='向你们的国王求救吧，$r！把他拖进来！', `FemaleText_loc5`='$rt，呼叫你的國王!讓他過來!', `FemaleText_loc7`='¡Llama a tu rey, $rt! ¡Tráelo aquí!' WHERE `ID`=70994;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영원한 태양의 빛이 그대를 치유하길!', `FemaleText_loc4`='愿永恒的太阳之光治愈你，$p！', `FemaleText_loc5`='$p，願永恆太陽的光芒療癒你!', `FemaleText_loc7`='¡Que la luz del sol eterno te sane, $p!' WHERE `ID`=70995;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정하지 마세요, $p 님. 제가 치유해 드리죠!', `FemaleText_loc4`='别担心，$p，我会治疗你的！', `FemaleText_loc5`='$p，別擔心，我會治療你!', `FemaleText_loc7`='¡No te preocupes, $p! ¡Yo te sanaré!' WHERE `ID`=70996;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 쓰러지게 그냥 두진 않겠습니다, $p 님!', `FemaleText_loc4`='我不会让你倒下的，$p！', `FemaleText_loc5`='$p，我不會讓你失望的!', `FemaleText_loc7`='¡No permitiré que caigas, $p!' WHERE `ID`=70997;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 상처가 아물기를.', `FemaleText_loc4`='汝之伤必将痊愈，$p！', `FemaleText_loc5`='$p，願你癒傷止痛。', `FemaleText_loc7`='Que tus heridas se curen, $p.' WHERE `ID`=70998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 사랑하는 국왕이 미끼를 물었다! 놈은 이 밀림에서 죽게 될 거다!', `MaleText_loc4`='你们敬爱的国王中了圈套！他会死在这片丛林里！', `MaleText_loc5`='你敬愛的國王上鉤了!他會死在這座叢林裡!', `MaleText_loc7`='¡Tu querido rey ha mordido el anzuelo! ¡Morirá en esta selva!', `FemaleText_loc1`='네가 그렇게 아끼는 국왕이 미끼를 물었다! 놈은 이 밀림에서 죽게 될 거야!', `FemaleText_loc4`='你们敬爱的国王中了圈套！他会死在这片丛林里！', `FemaleText_loc5`='你敬愛的國王上鉤了!他會死在這座叢林裡!', `FemaleText_loc7`='¡Tu querido rey ha mordido el anzuelo! ¡Morirá en esta selva!' WHERE `ID`=70999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강산이 바뀔 만큼 오래, 아니 어쩌면 그보다도 오랫동안, 이런 강렬한 감정은 느껴보지 못했는데.', `MaleText_loc4`='我已经有太长的时间没有感受过情绪的波动了。', `MaleText_loc5`='我從來沒有感受過如此強烈的情緒反應...從來沒有。', `MaleText_loc7`='Ha transcurrido al menos una edad de este mundo desde que sentí una emoción comparable a esta.' WHERE `ID`=71000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 내 칼은 너 말고도 많은 놈들의 피를 맛볼 것이다, $c!', `MaleText_loc4`='我的利刃会拿你的鲜血当作今天的开胃点心，$c！', `MaleText_loc5`='$c，我的刀刃光是嚐了你的鮮血還不夠哪!', `MaleText_loc7`='¡Tu sangre no será la última que probará mi acero hoy, $c!', `FemaleText_loc1`='오늘 내 칼은 너 말고도 많은 놈들의 피를 맛볼 것이다, $c!', `FemaleText_loc4`='我的利刃会拿你的鲜血当作今天的开胃点心，$c！', `FemaleText_loc5`='$c，我的刀刃光是嚐了你的鮮血還不夠哪!', `FemaleText_loc7`='¡Tu sangre no será la última que probará mi acero hoy, $c!' WHERE `ID`=71001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀림에 잘 왔다, $r. 여기가 네 무덤이다!', `MaleText_loc4`='欢迎来到丛林，$r。你们会死在这里！', `MaleText_loc5`='$rt，歡迎來到叢林，你要沒命了!', `MaleText_loc7`='$gBienvenido:Bienvenida; a la selva, $rt. ¡Morirás aquí!', `FemaleText_loc1`='밀림에 잘 왔다, $r. 여기가 네 무덤이다!', `FemaleText_loc4`='欢迎来到丛林，$r。你们会死在这里！', `FemaleText_loc5`='$rt，歡迎來到叢林，你要沒命了!', `FemaleText_loc7`='$gBienvenido:Bienvenida; a la selva, $rt. ¡Morirás aquí!' WHERE `ID`=71002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 "샤 에너지"라는 게 내가 생각했던 것보다 훨씬 강력한가 보오.', `MaleText_loc4`='“煞”的能量似乎比我想的要强不少。', `MaleText_loc5`='看來這個「煞」的能量遠比我想像的還要強大。', `MaleText_loc7`='Parece que esa energía "sha" es mucho más poderosa de lo que pensábamos.' WHERE `ID`=71003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금... 그게 뭐였지?', `MaleText_loc4`='那……那是什么？', `MaleText_loc5`='那...那是甚麼東西?', `MaleText_loc7`='¿Qué... qué ha sido eso?' WHERE `ID`=71004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롬매스... 난... 내가 왜 그렇게 됐는지 모르겠어요.', `MaleText_loc4`='罗曼斯……我……我不知道我身上发生了什么事。', `MaleText_loc5`='洛摩斯...我...我不知道我是怎麼了。', `MaleText_loc7`='Rommath... No... no sé qué me ha pasado.' WHERE `ID`=71005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈은 곧 죽을 거요, $p.', `MaleText_loc4`='这一个活不了多久了，$p。', `MaleText_loc5`='$p，這傢伙很快就要沒命了。', `MaleText_loc7`='Este morirá en breve, $p.' WHERE `ID`=71006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='화력을 집중하시오, $p!', `MaleText_loc4`='集中火力，$p。', `MaleText_loc5`='集中火力，$p!', `MaleText_loc7`='¡Centra tus ataques, $p!' WHERE `ID`=71007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 절호의 기회를 잡은 것 같소, $p.', `MaleText_loc4`='哈！我喜欢咱们的配合，$p。', `MaleText_loc5`='哈!我們的贏面很大，$p。', `MaleText_loc7`='¡Ja! Creo que llevamos ventaja.' WHERE `ID`=71008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미간을 정확히 맞춰주마...', `MaleText_loc4`='正中眉心……', `MaleText_loc5`='兩眼之間的眉心...', `MaleText_loc7`='Entre ceja y ceja...' WHERE `ID`=71009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, $p, 이놈을 없애버립시다!', `MaleText_loc4`='好，$p，让我们来干掉这个！', `MaleText_loc5`='來吧，$p，我們幹掉這個傢伙!', `MaleText_loc7`='¡Muy bien, $p, acabemos con ese!' WHERE `ID`=71010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저놈은 어떻게 피를 흘리나 봅시다...', `MaleText_loc4`='让我们瞧瞧这个家伙流血的样子……', `MaleText_loc5`='我們來看看這傢伙有多少血可流...', `MaleText_loc7`='A ver cómo sangra este...' WHERE `ID`=71011;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='블러드 엘프에게 맞서는 모든 이들에게 죽음을!', `MaleText_loc4`='对抗血精灵的都得死！', `MaleText_loc5`='反抗血精靈者，死!', `MaleText_loc7`='¡Muerte a todos los enemigos de los elfos de sangre!' WHERE `ID`=71012;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폐하, 제가 약속드립니다. 키린 토가 가로쉬를 그의 조상까지도 슬퍼하도록 엄하게 다스릴 거예요. 피에는 피로 복수하겠어요!', `FemaleText_loc4`='国王，我保证。肯瑞托一定会让加尔鲁什受到最严厉的惩罚。血债必须血偿！', `FemaleText_loc5`='陛下，我向您保證。祈倫托一定會把卡爾洛斯打到連他祖宗都不認識。我要他血債血償!', `FemaleText_loc7`='Mi Rey, te lo prometo, el Kirin Tor caerá sobre Garrosh de tal modo que lo sentirán sus ancestros. ¡Ojo por ojo!' WHERE `ID`=71016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나...', `MaleText_loc4`='吉安娜……', `MaleText_loc5`='珍娜 -', `MaleText_loc7`='Jaina...' WHERE `ID`=71017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 가로쉬를 끝장내겠다. 호드도 이미 허물어지고 있어. 우리가 결정타를 날릴 것이다.', `MaleText_loc4`='我会亲自跟加尔鲁什做个了断。他的部落业已分崩离析。我们将作出致命一击。', `MaleText_loc5`='我會了結卡爾洛斯。他帶領的部落早就已經四分五裂，我們將會給他致命一擊。', `MaleText_loc7`='Garrosh pagará por esto. La Horda se derrumba bajo sus pies. Y nosotros le daremos el golpe de gracia.' WHERE `ID`=71018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 그대와 안두인이 오늘 대족장을 막고 얼라이언스의 승리를 이끌어냈다.', `MaleText_loc4`='勇士，今天你和安度因挫败了部落酋长，为联盟赢得了关键的胜利。', `MaleText_loc5`='勇士，你跟安杜因今天使大酋長受到重挫，並替聯盟取得關鍵性的勝利。', `MaleText_loc7`='Anduin y tú frustraron los planes del Jefe de Guerra y obtuvieron una gran victoria para la Alianza.' WHERE `ID`=71019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 가 다오, 영웅이여. 아들을 돌보고... 다음 전투를 준비해야 하니.', `MaleText_loc4`='现在请你走吧，英雄。我要照顾我儿子……并准备下一场战斗了。', `MaleText_loc5`='讓我靜一靜，英雄。我要去照顧我的兒子...並準備下一場的戰鬥。', `MaleText_loc7`='Ahora déjame. Debo cuidar a mi hijo... y prepararme para la próxima batalla.' WHERE `ID`=71020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소년의 얼굴은 창백하고, 숨결도 가까스로 느껴질 정도입니다.', `MaleText_loc4`='这孩子的脸变得煞白。他几乎没有呼吸了。', `MaleText_loc5`='這孩子的臉色灰白，幾乎沒了氣息。', `MaleText_loc7`='El rostro del chico tiene un aspecto ceniciento. Apenas respira.' WHERE `ID`=71021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 도우려고 |cFFFF0000|Hspell:135759|h[수호자의 구원]|h|r을 시전합니다!', `MaleText_loc4`='%s施放了|cFFFF0000|Hspell:135759|h[庇护之罩]|h|r来协助你！', `MaleText_loc5`='%s施展|cFFFF0000|Hspell:135759|h[保衛者救助]|h|r幫助了你!', `MaleText_loc7`='¡%s lanza |cFFFF0000|Hspell:135759|h[Salvación del Protector]|h|r para ayudarte!' WHERE `ID`=71022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 듣고 싶습니다.', `MaleText_loc4`='你怎么想？', `MaleText_loc5`='你怎麼想?', `MaleText_loc7`='¿Qué te parece?', `FemaleText_loc1`='네. 듣고 싶어요.', `FemaleText_loc4`='你怎么想？', `FemaleText_loc5`='你怎麼想?', `FemaleText_loc7`='¿Qué te parece?' WHERE `ID`=71023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저하와 이야기해 봅시다.', `MaleText_loc4`='我们去和他谈谈。', `MaleText_loc5`='我們去跟他談談吧。', `MaleText_loc7`='Hablemos con él.', `FemaleText_loc1`='저하와 이야기해 보죠.', `FemaleText_loc4`='我们去和他谈谈。', `FemaleText_loc5`='我們去跟他談談吧。', `FemaleText_loc7`='Hablemos con él.' WHERE `ID`=71024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네. 키린 토는 진영 간의 분쟁 같은 건 초월해야 합니다.', `MaleText_loc4`='是的——肯瑞托不能卷入阵营的纷争中。', `MaleText_loc5`='是的 - 祈倫托必須超越陣營之間的爭端。', `MaleText_loc7`='Sí. El Kirin Tor debe mantenerse al margen de las riñas de facción.', `FemaleText_loc1`='네. 키린 토는 진영 간의 분쟁 같은 건 초월해야 합니다.', `FemaleText_loc4`='是的——肯瑞托不能卷入阵营的纷争中。', `FemaleText_loc5`='是的 - 祈倫托必須超越陣營之間的爭端。', `FemaleText_loc7`='Sí. El Kirin Tor debe mantenerse al margen de las riñas de facción.' WHERE `ID`=71025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럴 수 있을지 모르겠군요.', `MaleText_loc4`='我不确定。', `MaleText_loc5`='我不確定。', `MaleText_loc7`='No sé si podría.', `FemaleText_loc1`='그럴 수 있을지 모르겠군요.', `FemaleText_loc4`='我不确定。', `FemaleText_loc5`='我不確定。', `FemaleText_loc7`='No sé si podría.' WHERE `ID`=71026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아. 이제야 제대로 된 전장의 냄새가 나는군. 너무 오랫동안 우리끼리 있었어. 이제는 호드의 전 병력이 여기 있네! 그리고 우리 역할은 다음 공격이 어디로 향해야 하는지 알려 주는 것이지.', `MaleText_loc4`='啊。这才是真正的战场的味道。我们孤军奋战的时间太长了。现在，部落将释放出全部的力量，而我们，将指引部落之力进攻的方向！', `MaleText_loc5`='啊，這才是戰場的氣息。我們已經獨力支撐太久了，如今，部落終於展現了完全的力量!下一波攻擊要往哪裡是由我們來主導。', `MaleText_loc7`='Ah, el olor de un verdadero campo de batalla. Llevamos demasiado tiempo solos. ¡Todo el poderío de la Horda se ha desatado! Y nos corresponde a nosotros dirigir el próximo golpe.' WHERE `ID`=71027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심한 얼라이언스 녀석들. 고작 이딴 약골을 내게 보낸 거냐? 하!', `MaleText_loc4`='你们这群可悲的联盟就这点能耐？呸！', `MaleText_loc5`='你們可悲的聯盟就這麼一點兵力?哈!', `MaleText_loc7`='¿ESTO es lo mejor que tiene tu patética Alianza? ¡BAH!' WHERE `ID`=71028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 얼라이언스 녀석들은 남부 불모의 땅에서도 우리에게 짓밟혔지. 여기에서 또 한 번 짓밟아 주마. 온 판다리아가 우리 앞에 벌벌 떨 것이다!', `MaleText_loc4`='我们在南贫瘠之地摧毁了你们的军队。我们也将在这里取得胜利。整个潘达利亚都将颤抖！', `MaleText_loc5`='我們在南貧瘠之地粉碎了你的聯盟，我們也會在這裡粉碎你。潘達利亞會為之戰慄!', `MaleText_loc7`='Aplastamos a tu Alianza en Los Baldíos del Sur y la aplastaremos aquí. ¡Pandaria temblará!' WHERE `ID`=71029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 네놈들을 해변에서 몰아낼 것이다. 온 판다리아가 호드의 강대함 앞에 무릎 꿇을 것이야!', `MaleText_loc4`='我们会把你们从这片海滩上赶回去。在那之后，所有熊猫人都会屈服于我们的力量！', `MaleText_loc5`='我們會把你們逐出海灘，熊貓人會震懾於我們的力量!', `MaleText_loc7`='Os echaremos de la playa. ¡Los pandaren temblarán ante nuestra fuerza!' WHERE `ID`=71030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해 봐라. 내가 피 흘리게 하란 말이다. 진정한 오크는 전투를 위해 산다!', `MaleText_loc4`='哈，你让我流血了。这不算什么。真正的兽人为战斗而生！', `MaleText_loc5`='來啊，放馬過來。真正的獸人是為戰鬥而生的!', `MaleText_loc7`='Adelante. Hazme sangrar. ¡Los orcos de verdad viven para el combate!' WHERE `ID`=71031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님... 실망을 안겨 드려... 죄송합니다...', `MaleText_loc4`='酋长大人……我辜负了你……', `MaleText_loc5`='大酋長...我讓你失望了...', `MaleText_loc7`='Jefe de Guerra... te he fallado...' WHERE `ID`=71032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무언가 새겨져 있습니다. "내 피 같은 맥주"', `MaleText_loc4`='上面刻有一行字：“邪思难溢！”', `MaleText_loc5`='一段刻文寫著:「滴酒不漏!」', `MaleText_loc7`='Tiene un grabado que reza: "¡No derramarás!".', `FemaleText_loc1`='무언가 새겨져 있습니다. "내 피 같은 맥주"', `FemaleText_loc4`='上面刻有一行字：“邪思难溢！”', `FemaleText_loc5`='一段刻文寫著:「滴酒不漏!」', `FemaleText_loc7`='Tiene un grabado que reza: "¡No derramarás!".' WHERE `ID`=71033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 고통은 아무것도 아니라네!', `MaleText_loc4`='哈！不痛不痒！', `MaleText_loc5`='哼!一點都不痛!', `MaleText_loc7`='¡Bah! ¡El dolor no duele!' WHERE `ID`=71034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용맹한 자에게 영광을!', `MaleText_loc4`='勇者无敌！', `MaleText_loc5`='榮耀歸於勇士!', `MaleText_loc7`='¡Gloria a los valientes!' WHERE `ID`=71035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개 맛 좀 보시지!', `MaleText_loc4`='雷霆天降！', `MaleText_loc5`='雷霆降臨!', `MaleText_loc7`='¡Aquí viene el TRUENO!' WHERE `ID`=71036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 정도가 나와 맞설 수 있을 것 같은가?', `MaleText_loc4`='站在我面前的这是什么？', `MaleText_loc5`='是誰膽敢站在我的面前?', `MaleText_loc7`='¿Qué ven mis ojos?' WHERE `ID`=71037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 폐하께서 요청하셨던 대로 이제 손잡이랑 망치, 그리고 연고도 가져왔어요. 망치를 다시 조립해주실 수 있나요?', `MaleText_loc4`='好了，我们现在拿到了你要的杵柄，杵头和药膏。你能帮我们将钟杵组合起来吗？', `MaleText_loc5`='好啦，我們照你要求的取得了槌柄、槌首跟油膏。你可以重組和諧之槌嗎?', `MaleText_loc7`='Muy bien, ya tenemos el mango, la cabeza y el ungüento, como pediste. ¿Puedes volver a montar la marra?' WHERE `ID`=71043;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지! 멍청한 어린 친구. 지팡이를 구멍에 집어넣기만 해. 그러면 망치가 다시 하나로 될 거야.', `MaleText_loc4`='没错！笨小子，杵柄入杵头，钟杵重现世。', `MaleText_loc5`='啊呀!小子你別費心，把槌柄接上去，槌子就完整如新。', `MaleText_loc7`='¡Sí! Makaku joven pone vara en agujero, y ya tiene instrumento entero.' WHERE `ID`=71044;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우낏 새것 같은데! 하지만 원숭이 왕 말 잘 들어. 연고는 망치를 한 번만 휘두를 수 있을 만큼밖에 없어.', `MaleText_loc4`='就和新的一样！听好美猴王说的话。你的药膏只够敲一次钟。', `MaleText_loc5`='完整如新!不過聽美猴王一句，這些油膏只夠你使出一擊。', `MaleText_loc7`='¡Marra komo nueva! Pero tú eskucha al Rey Mono. Tú solo tiene ungüento suficiente para un golpe.' WHERE `ID`=71045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번 밖에요? 한 번도 못 휘두르는 건 아니겠죠? 연고를 더 얻을 방법은 없어요?', `MaleText_loc4`='只能敲一次？一次真的就够了吗？我们有办法多找到一些药膏吗？', `MaleText_loc5`='只能使出一擊?這真的管用嗎?我們能不能多找點油膏?', `MaleText_loc7`='¿Solo un golpe? ¿Seguro que esto va a funcionar? ¿No hay forma de conseguir más ungüento?' WHERE `ID`=71046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예전에 이 망치가 종을 제대로 때렸을 때, 원숭이 왕 거기 있었다. 눈물이 핑 돌았고, 조화가 계속 맴도는 게 느껴졌어. 하지만 연고는 더 만들어지지 않았다. 모구가 공격하러 왔었거든. 지금 가진 거 써. 그것도 고마운 줄 알아. 천상의 종은 정말 위험한 무기야. 그러니까 조심해서 써.', `MaleText_loc4`='上一次钟杵敲响圣钟的时候，美猴王就在旁边。美猴王热泪盈眶，但内心无比平静。在那之后，圣钟被魔古人夺走，再也没有人做过药膏了。心存感激，你手上的药膏就是最后的药膏。圣钟是危险的武器，一定要小心处理。', `MaleText_loc5`='槌子一擊正中，猴王曾親眼目睹。和諧震撼全身，淚水奪眶擋不住。然而油膏再也不製造，因為魔古突然殺到。有油膏可用要心懷感謝，請小心謹慎防聖鐘凶險。', `MaleText_loc7`='El Rey Mono estaba presente la última vez ke se usó la marra. Se le llenaron los ojos de lágrimas y la armonía se extendió por todas partes. Pero no se kreó más ungüento, porke llegaron los mogu. Usa lo ke tú tiene y no te keja. La kampana es muy peligrosa, hay ke usarla kon kuidado.' WHERE `ID`=71047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 어둠의 마법은 뭘까요?', `MaleText_loc4`='这是什么黑暗魔法？', `MaleText_loc5`='這是什麼黑暗的魔法?', `MaleText_loc7`='¿Qué magia oscura es esta?', `FemaleText_loc1`='이 어둠의 마법은 뭘까요?', `FemaleText_loc4`='这是什么黑暗魔法？', `FemaleText_loc5`='這是什麼黑暗的魔法?', `FemaleText_loc7`='¿Qué magia oscura es esta?' WHERE `ID`=71048;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 닿으면 안 됩니다!', `MaleText_loc4`='别让它碰到你！', `MaleText_loc5`='別讓它碰到你!', `MaleText_loc7`='¡No dejes que te toque!', `FemaleText_loc1`='거기 닿으면 안 돼요!', `FemaleText_loc4`='别让它碰到你！', `FemaleText_loc5`='別讓它碰到你!', `FemaleText_loc7`='¡No dejes que te toque!' WHERE `ID`=71049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 예쁜 전차가 이리저리 움직이진 못하지만, 장착된 무기는 일반적인 공정을 벗어난 획기적인 작품이지.', `MaleText_loc4`='她的传动设备还不能传动，但她的武器设备刚在流水线上组装完毕。', `MaleText_loc5`='它的運動元件不能運作，但是武器都是剛出廠的。', `MaleText_loc7`='Sus dispositivos motrices no "motrizan", pero las armas están recién salidas de la cadena de montaje.' WHERE `ID`=71050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아름다운 나의 전차여, 일어나서 빛나라!', `MaleText_loc4`='宝贝，闪亮登场吧！', `MaleText_loc5`='美人，起床囉!', `MaleText_loc7`='¡Despierta, preciosa!' WHERE `ID`=71051;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용히 일 좀 하게 놔두면 안 돼?', `MaleText_loc4`='我们就不能安静地工作吗？', `MaleText_loc5`='就不能讓我們好好工作嗎?', `MaleText_loc7`='¿No puede uno trabajar en paz?' WHERE `ID`=71052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 장소는 느낌이 영 안 좋습니다.', `MaleText_loc4`='这地方让我感觉很不好。', `MaleText_loc5`='這個地方給我一種不好的預感。', `MaleText_loc7`='Este sitio me da mala espina.', `FemaleText_loc1`='이 장소는 느낌이 영 안 좋습니다.', `FemaleText_loc4`='这地方让我感觉很不好。', `FemaleText_loc5`='這個地方給我一種不好的預感。', `FemaleText_loc7`='Este sitio me da mala espina.' WHERE `ID`=71053;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군은 어디 있는 겁니까?', `MaleText_loc4`='我们的援军呢？', `MaleText_loc5`='我們的援軍在哪裡?', `MaleText_loc7`='¿Dónde están los refuerzos?', `FemaleText_loc1`='지원군은 어디 있는 거지요?', `FemaleText_loc4`='我们的援军呢？', `FemaleText_loc5`='我們的援軍在哪裡?', `FemaleText_loc7`='¿Dónde están los refuerzos?' WHERE `ID`=71054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리끼리 얼마나 더 버틸 수 있을까요?', `MaleText_loc4`='我们还能坚持多久？', `MaleText_loc5`='只靠我們，還能撐得了多久?', `MaleText_loc7`='¿Cuánto tiempo podemos resistir solos?', `FemaleText_loc1`='우리끼리 얼마나 더 버틸 수 있을까요?', `FemaleText_loc4`='我们还能坚持多久？', `FemaleText_loc5`='只靠我們，還能撐得了多久?', `FemaleText_loc7`='¿Cuánto tiempo podemos resistir solos?' WHERE `ID`=71055;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마법은 뭔가 느낌이 좋지 않습니다.', `MaleText_loc4`='我不喜欢这种魔法的味道。', `MaleText_loc5`='我不喜歡這種魔法嚐起來的味道。', `MaleText_loc7`='No me gusta el sabor de esta magia.', `FemaleText_loc1`='이 마법은 뭔가 느낌이 좋지 않아요.', `FemaleText_loc4`='我不喜欢这种魔法的味道。', `FemaleText_loc5`='我不喜歡這種魔法嚐起來的味道。', `FemaleText_loc7`='No me gusta el sabor de esta magia.' WHERE `ID`=71056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 대체 무슨 마법일까요?', `MaleText_loc4`='这是什么魔法？', `MaleText_loc5`='這是什麼魔法?', `MaleText_loc7`='¿Qué clase de magia es esta?', `FemaleText_loc1`='이게 대체 무슨 마법일까요?', `FemaleText_loc4`='这是什么魔法？', `FemaleText_loc5`='這是什麼魔法?', `FemaleText_loc7`='¿Qué clase de magia es esta?' WHERE `ID`=71057;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여! 치료가 필요하면 이 향을 맡으세요!', `MaleText_loc4`='朋友！如果你需要治疗，就来吸一口我的熏香！', `MaleText_loc5`='朋友!需要治療的話就過來聞一點薰香!', `MaleText_loc7`='¡$gAmigo:Amiga;! ¡Respira mi incienso si necesitas sanación!' WHERE `ID`=71060;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워요, 그루멀의 친구!', `MaleText_loc4`='谢谢你，土地精的朋友！', `MaleText_loc5`='謝謝你，咕嚕摩的朋友!', `MaleText_loc7`='¡Gracias, $gamigo:amiga; de los grúmel!' WHERE `ID`=71061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='작은 코그렌치, 당신이 보고 싶습니다.', `MaleText_loc4`='轮钳，你可真小，我很想你。', `MaleText_loc5`='榫扳，我會懷念你這個小傢伙的。', `MaleText_loc7`='LLAVEPIÑÓN, ERAS PEQUEÑO Y TE ECHO DE MENOS.' WHERE `ID`=71062;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여행자님! 더 빠른 속도로 싸우고 싶으면 이걸 맡아요!', `MaleText_loc4`='云游者！如果你想快点结束战斗，就吸一口这熏香！', `MaleText_loc5`='漫遊者，你如果想讓自己戰鬥得更快速，就來聞聞薰香!', `MaleText_loc7`='¡$gViajero:Viajera;! ¡Huele esto si quieres luchar más rápido!' WHERE `ID`=71063;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 고마워요! 장벽 서쪽으로 여행하는 건 이번이 마지막이에요!', `MaleText_loc4`='感谢你！这是我最后一次在城墙的西边旅行。', `MaleText_loc5`='太感謝了!這是我們最後一次踏進長城的西邊。', `MaleText_loc7`='¡Muchas gracias! Es la última vez que viajamos al oeste de la muralla.' WHERE `ID`=71064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 열심히 하게, $p. 자네만 도와준다면, 일은 금방 끝날 거야!', `MaleText_loc4`='保持这股干劲，$p。有了你的帮助，我们很快就能完成了！', `MaleText_loc5`='$p，繼續努力。有了你的幫忙，我們很快就能完成任務!', `MaleText_loc7`='Sigue así, $p. Con tu ayuda, ¡acabaremos en un periquete!' WHERE `ID`=71065;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘서 고맙네, 친구. 이 속도라면 곧 쉴 수 있을 걸세!', `MaleText_loc4`='感谢你的帮助，朋友。按现在的速度，我们不久之后就能休息了！', `MaleText_loc5`='朋友，謝謝你的幫忙。以這個速度，我們很快就能休息了!', `MaleText_loc7`='Agradecemos tu ayuda. A este ritmo, podremos descansar enseguida.' WHERE `ID`=71066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 애써준 덕분에 작업 속도가 많이 빨라졌네, $p. 혹시 아예 우리와 함께 일할 생각은 없나?', `MaleText_loc4`='有了你的帮忙，我们的进度真的提高了不少，$p。你要不要考虑下加入我们的队伍？', `MaleText_loc5`='$p，你的努力讓我們的進度加快不少。你想不想在我們這邊擔任永久職?', `MaleText_loc7`='Tus esfuerzos aceleran considerablemente nuestro progreso, $p. ¿No te interesa un puesto fijo en nuestro equipo?' WHERE `ID`=71067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 배가 가득 찼을 때 가장 일을 잘 하네, $p. 우리 식탁을 가득 채워 놓게!', `MaleText_loc4`='熊猫人在吃饱之后效率最高，$p。确保我们的餐桌上不缺食物吧！', `MaleText_loc5`='$p，我們熊貓人要酒足飯飽，工作起來才最有效率。別讓桌上的食物少了!', `MaleText_loc7`='Los pandaren trabajamos mejor con el estómago lleno, $p. ¡Asegúrate de que la mesa está repleta!' WHERE `ID`=71068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하게, $p. 야생 동물에게서 얻는 고기나 적에게서 얻는 전투 식량만 있으면, 우리 작업자들이 배불리 먹을 수 있어!', `MaleText_loc4`='记住了，$p，无论是你从野生动物身上取得的肉还是从敌人身上取得的军粮都能喂饱我的队伍！', `MaleText_loc5`='$p，記好了，野生的獸肉跟敵人身上搶來的乾糧可以把我的組員餵得飽飽的!', `MaleText_loc7`='Recuerda, $p: la carne de la fauna local o las raciones de tus enemigos alimentarán bien a mi equipo.' WHERE `ID`=71069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼마 전에 우리 술통이 몇 개 없어졌네. 마지막으로 본 건 여기서 동쪽이었는데...', `MaleText_loc4`='最近我们丢了一些酒。它们本来就在东边不远的地方……', `MaleText_loc5`='最近我們弄丟了幾桶酒，最後一次看到它們是在這裡的東邊...', `MaleText_loc7`='Hace poco perdimos unos cuantos barriles. Los vimos por última vez al este de aquí...' WHERE `ID`=71070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 사우록은 약탈자네. 놈들이 무엇을 가지고 다니는지는 아무도 모르지.', `MaleText_loc4`='蜥蜴人喜欢收集战场上的破烂。他们身上带着什么东西都不奇怪。', `MaleText_loc5`='這裡的薩烏洛克是拾荒者，天知道牠們身上帶了什麼東西。', `MaleText_loc7`='Los saurok son saqueadores. A saber qué podrían llevar encima...' WHERE `ID`=71071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부서질 듯한 뿌리가 없는지 항상 유심히 살피게, $p. 그 나무는 방어선 구축에 잘 쓰일 수 있으니까 말이야.', `MaleText_loc4`='别错过那些脆弱的根茎，$p。我们可以利用这些木料来建造防御工事。', `MaleText_loc5`='$p，留意脆弱的樹根。我們可以利用裡面的材料來建造防禦工事。', `MaleText_loc7`='Si encuentras raíces frágiles, $p, podemos utilizarlas para construir defensas.' WHERE `ID`=71072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령 깃든 물은 무척 불안정하네. 한 번에 하나씩만 들고 다닐 수 있어.', `MaleText_loc4`='灵吻之水非常不稳定。每次只能携带一瓶。', `MaleText_loc5`='魂靈親吻之水很不穩定，一次只能攜帶一瓶。', `MaleText_loc7`='El agua besada por los espíritus es muy inestable. Solo se puede llevar una unidad encima.' WHERE `ID`=71073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃 반딧불이를 찾게, $p! 이 특별한 양조주를 만드는 데 꼭 필요하니까.', `MaleText_loc4`='仔细寻找那些暴躁萤火虫，$p！它们可以用来调制这种特殊的啤酒。', `MaleText_loc5`='$p，去找暴躁螢火蟲!要作出這種特調可少不了牠們。', `MaleText_loc7`='¡Busca luciérnagas volátiles, $p! Son cruciales para la elaboración de este brebaje especial.' WHERE `ID`=71074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀림 홉은 가마솥에 바로 집어넣게, $p. 홉은 많으면 많을수록 좋아!', `MaleText_loc4`='把丛林啤酒花直接丢进大锅里，$p。啤酒花永远不嫌多！', `MaleText_loc5`='$p，把叢林啤酒花丟進鍋子裡，啤酒花可是多多益善!', `MaleText_loc7`='Mete los lúpulos de la selva directamente en el caldero, $p. ¡Nunca se tienen demasiados lúpulos!' WHERE `ID`=71075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항상 정령 깃든 물을 가지고 다녀야 하네, 친구. 그게 없으면 우리는... 음... 잠이 들고 말 거야.', `MaleText_loc4`='你应该总是随身携带一瓶灵吻之水，朋友。否则，我们……就会……打瞌睡。', `MaleText_loc5`='朋友，你應該隨身攜帶魂靈親吻之水。少了它，我們很容易...打瞌睡。', `MaleText_loc7`='Siempre deberías llevar agua besada por los espíritus encima, colega. Sin ella, tendemos a... echarnos una siesta.' WHERE `ID`=71076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 고릴라들은 화가 많이 난 것 같군, 친구. 놈들과 싸워 보면 뭔가를 얻을 수 있을지도 몰라!', `MaleText_loc4`='那些大猩猩看起来又愤怒又危险，朋友，但挑战他们总是能获得不错的回报！', `MaleText_loc5`='朋友，這些猩猩看起來很兇，但是向牠們挑戰可能會很值得!', `MaleText_loc7`='Los gorilas tienen pinta de estar enfadados, ¡pero retarlos puede merecer la pena!' WHERE `ID`=71077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... $p, 내가 항상 깨어 있게 도와주게! 내가 잠들면 모든 작업이 중단되고 만다네.', `MaleText_loc4`='拜托你，朋友，请让我保持清醒！如果我睡着了，所有的生产都会停滞。', `MaleText_loc5`='拜託，$p，讓我保持清醒!要是我們睡著了，產能會中斷的。', `MaleText_loc7`='¡Mantenme despierto, $n! Si nos dormimos, la productividad cae en picado.' WHERE `ID`=71078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자원이 고갈되기 전에 보충해 주는 게 좋을 걸세.', `MaleText_loc4`='及时补充资源，别让它们耗尽了！', `MaleText_loc5`='在資源用完之前事先補充，是明智之舉!', `MaleText_loc7`='¡Restablecer los recursos antes de que se agoten es de sabios!' WHERE `ID`=71079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 1박 2일로 가는 여행이 좋아. 그중에서도 야외 취침이 특히 신나지!', `MaleText_loc4`='过夜旅行什么的，最喜欢了！露营是我的最爱！', `MaleText_loc5`='我喜歡在外面過夜，我最愛的就是露營了!', `MaleText_loc7`='Me encantan las escapadas. ¡Acampar es mi actividad favorita!' WHERE `ID`=71080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 한때 춤을 좀 췄지. 볼래?', `MaleText_loc4`='我是个舞者。想要看看我跳舞吗？', `MaleText_loc5`='我很會跳舞的，想瞧瞧嗎?', `MaleText_loc7`='Bailo muy bien. ¿Quieres que te lo enseñe?' WHERE `ID`=71081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사람들이 왜 나보고 어린애라고 하는지 모르겠어!', `MaleText_loc4`='我不明白为什么其他人总是把我当小孩子对待！', `MaleText_loc5`='我不知道為什麼大家都把我當小孩子看!', `MaleText_loc7`='¡No sé por qué la gente me trata como a un crío!' WHERE `ID`=71082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말 시키지 마! 내 기상 시간은 오후 2시라고!', `MaleText_loc4`='别烦我了！我一般要下午才起床。', `MaleText_loc5`='別煩我!我一向都睡到下午很晚才起床的。', `MaleText_loc7`='¡Deja de dar la lata! Normalmente me despierto por la tarde.' WHERE `ID`=71083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크면 가수가 돼야지!', `MaleText_loc4`='当我长大之后，我要当个歌手！', `MaleText_loc5`='我長大以後想當歌星!', `MaleText_loc7`='¡Cuando sea mayor quiero ser cantante!' WHERE `ID`=71084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딴 생각은 말아라라 라라라라!$B$B내 노래 어때?', `MaleText_loc4`='哟哟哟切克闹！动次打次动次打次！$B$B你喜欢我的歌吗？', `MaleText_loc5`='啊哈啊哈啊哈，哦哦!啊哈啊哈啊哈，耶耶耶耶!$B$B你喜歡我的歌嗎?', `MaleText_loc7`='¡A ja ja uh-uh! ¡A ja ja sí sí sí!$b$b¿Te gusta mi canción?' WHERE `ID`=71085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감당할 수 없는 슬픈 기억 제거 중...', `MaleText_loc4`='正在清除会导致无法承受的悲伤情感的记忆数据……', `MaleText_loc5`='刪除難以承受的悲傷回憶...', `MaleText_loc7`='BORRANDO RECUERDOS TRISTES DE LA MEMORIA...' WHERE `ID`=71087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출고 시 설정 복원...', `MaleText_loc4`='正在恢复出厂设定……', `MaleText_loc5`='載入出廠設定...', `MaleText_loc7`='AJUSTES DE FÁBRICA CARGADOS...' WHERE `ID`=71088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실행하겠습니다, 사랑스러운 분.', `MaleText_loc4`='遵命，小轮。', `MaleText_loc5`='確認，小甜心。', `MaleText_loc7`='AFIRMATIVO, CORAZÓN.' WHERE `ID`=71089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쩌면 통제할 수 있을 수 있소. 우리 백성들은 내면의 분노를 다스리는 훈련이 잘 되어 있으니...', `MaleText_loc4`='也许这股能量可以被驾驭。我的人民……长久以来一直在控制内心的愤怒……', `MaleText_loc5`='也許它是可以駕馭的。我們的族人熟練於控制內心的憤怒...', `MaleText_loc7`='A lo mejor se podría controlar. Mi pueblo está versado en el arte de controlar la ira...' WHERE `ID`=71090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, $g친구:아가씨;, 자재를 잘 모으고 있더군. 열심히 계속하게!', `MaleText_loc4`='干得好，$g小伙子:妹子;，你找到了些不错的东西。加油！', `MaleText_loc5`='喲，$g小夥子:姑娘;，你的表現很好，繼續努力!', `MaleText_loc7`='Vaya, $gmozo:moza;, sí que te has esforzado. ¡Sigue recolectando!' WHERE `ID`=71091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 덕분에 우리가 땀 뻘뻘 흘리며 빠른 속도로 일하고 있네, $p. 곧 방어선이 구축될 거야!', `MaleText_loc4`='你帮了我们的大忙，$p！我们马上就会把防御工事建起来！', `MaleText_loc5`='$p，你讓我們拚了老命的幹活啊。防衛工事馬上大功告成!', `MaleText_loc7`='Nos haces trabajar que da gusto, $p. ¡Terminaremos las defensas en un periquete!' WHERE `ID`=71092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 전속력으로 달려가고 있네, $p. 이대로만 계속하면 돼.', `MaleText_loc4`='我们正在全力工作，马力全开，$p。你只需要帮我们保持效率就好。', `MaleText_loc5`='$p，我們正在全力加速，你只要專心讓我們保持下去就好。', `MaleText_loc7`='Vamos a toda máquina, $p. Tú solo preocúpate de que no bajemos el ritmo.' WHERE `ID`=71093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $p. 가만히 있으면 저기 화로 위에 음식이 저절로 생겨나는 줄 아나? 여기 친구들을 배고프게 하면 안 되네!', `MaleText_loc4`='听着，$p，那个烤肉架不会自己变出吃的来。别让我的伙计们饿着了！', `MaleText_loc5`='聽著，$p，那個烤肉架可不會自己把食物放上去，別讓大夥兒餓著了!', `MaleText_loc7`='Escucha, $p, la comida no se va a poner en esa parrilla ella sola. ¡No dejes que mis compañeros pasen hambre!' WHERE `ID`=71094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중하게, $p! 야생 동물의 고기나 오크 병사들의 전투 식량만 있으면 우리 작업자들이 배불리 먹을 수 있다고!', `MaleText_loc4`='注意听，$p！你在野生动物身上找到的肉或者从兽人士兵身上找到的军粮都能填饱伙计们的肚子。', `MaleText_loc5`='$p，專心點! 野生的獸肉跟獸人部隊身上搶來的乾糧可以把我的組員餵得飽飽的!', `MaleText_loc7`='¡Céntrate, $p! La carne de la fauna local y las raciones de los soldados orcos alimentarán bien a mi equipo.' WHERE `ID`=71095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 부근에 불발 포탄이 굴러다닐지도 모르네. 최근 해안가에서 전투가 많이 있었으니까...', `MaleText_loc4`='这附近也许能找到一些哑火的炮弹。最近这片海滩上打了不少炮战……', `MaleText_loc5`='這附近可能還有一些未爆炸的砲彈。最近岸邊發生很多戰鬥...', `MaleText_loc7`='A lo mejor hay bolas de cañón sin explotar por los alrededores. Con tanto combate náutico...' WHERE `ID`=71096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 도마뱀 녀석들이 뭔가를 지니고 있을지 모르네. 놈들을 잘 살펴보게!', `MaleText_loc4`='那些长得像蜥蜴一样的怪物身上总是带有一些稀奇古怪的东西。看到了就别错过！', `MaleText_loc5`='這些蜥蜴人身上可能帶著任何東西，多留意點!', `MaleText_loc7`='Esos hombres lagarto podrían llevar cualquier cosa encima. ¡No los pierdas de vista!' WHERE `ID`=71097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='땅에서 솟아나온 부러질 듯한 나무를 찾게. 아주 쓸 만한 목재니까!', `MaleText_loc4`='脆弱的根茎有时会暴露在土外。那些可是上好的木材。', `MaleText_loc5`='留意從土裡伸出來的脆弱的樹根，裡面的纖維品質很好!', `MaleText_loc7`='Busca raíces frágiles que sobresalgan del suelo. ¡Dan buena madera!' WHERE `ID`=71098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 근방에는 독특한 강철이 있네. 혹시 발견하면 모두 가져오게, $p. 아제로스에서 우리 드워프가 제련할 수 없는 강철 따위는 없어.', `MaleText_loc4`='这里有一些特殊的铁矿。给我找一些回来，$p。在艾泽拉斯没有矮人熔不了的金属。', `MaleText_loc5`='這一帶有種獨特的鐵礦，$p，找到多少都帶回來給我。艾澤拉斯上沒有什麼鐵礦是我們矮人沒辦法鍛造的。', `MaleText_loc7`='Hay un tipo de hierro que solo se encuentra en esta zona. Tráenos todo el que encuentres, $p. ¡No existe hierro en Azeroth que los enanos no podamos forjar!' WHERE `ID`=71099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $p! 이 일을 마치려면 손에 넣을 수 있는 자원은 모두 활용해야 하네! 식량, 나무, 강철... 뭐든 찾아오라고!', `MaleText_loc4`='嘿，$p！如果我们想要快点完工，各种资源可少不了！食物，木材，铁矿……把你能找到的东西都给我带来！', `MaleText_loc5`='$p，來吧!我們需要資源才能完成這個任務!食物、木材、鐵礦...什麼都可以!', `MaleText_loc7`='¡Venga, $p! Si queremos terminar el trabajo, nos harán falta recursos. Comida, madera, hierro... ¡Todo lo que encuentres!' WHERE `ID`=71100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='악어 고기는 무척 맛이 좋다네, $p. 그런데 내가 제일 좋아하는 건, 호랑이 볼깃살이라고!', `MaleText_loc4`='那些鳄鱼的肉质相当不错，$p，但老虎腰肉是我的个人最爱！', `MaleText_loc5`='$p，那些鱷魚的肉很美味，可是虎臀肉才是我的最愛!', `MaleText_loc7`='Los crocoliscos sueltan una carne muy sabrosa, $p, ¡pero mi favorita es la de los tigres!' WHERE `ID`=71101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 오크가 돌아다니고 있네, $p. 냄새가 나. 놈들의 보급품이라면 우리도 잘 쓸 수 있겠지.', `MaleText_loc4`='外面有不少兽人，$p。我能闻到他们身上的味道。他们身上携带的补给能够派上用场。', `MaleText_loc5`='$p，外頭有獸人，我聞得到他們的味道。他們應該有我們能利用的補給。', `MaleText_loc7`='Ahí fuera hay orcos, $p. Los huelo. Seguro que llevan suministros que podemos aprovechar.' WHERE `ID`=71102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 현장에서 너무 멀리 가지는 말게, $p. 자네 같은 친구가 없으면 우린 어떤 공격도 막아낼 수가 없거든.', `MaleText_loc4`='别离开太远，$p。没有你的帮助，我们这里和不设防也没什么区别了。', `MaleText_loc5`='$p，別走太遠，要是少了你們這樣的人，我們簡直是毫無防備能力。', `MaleText_loc7`='No te alejes demasiado, $p. Sin gente como tú estamos prácticamente indefensos.' WHERE `ID`=71103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 공격을 받게 되면 모든 작업이 중단된다네. 우릴 위해 두 눈을 크게 뜨라고!', `MaleText_loc4`='如果遭到进攻，生产就会停止。记得帮我们防守基地！', `MaleText_loc5`='如果我們遭到攻擊的話，生產就會中斷。保護好我們!', `MaleText_loc7`='La productividad se para si nos atacan. ¡No nos quites el ojo de encima!' WHERE `ID`=71104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 말 잘 듣게, $p. 자원을 최대한 채워 놓는 게 좋아!', `MaleText_loc4`='记住我的建议，$p。多存点资源总是没坏处的！', `MaleText_loc5`='$p，聽我的建議，最好把資源囤積得充裕點!', `MaleText_loc7`='Te daré un consejo, $p: es mejor guardar suministros de sobra.' WHERE `ID`=71105;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='신호탄을 보고 바로 날아왔어요!', `FemaleText_loc4`='看到你的信号弹我就第一时间赶来了！', `FemaleText_loc5`='看到你的信號我就盡快趕來了!', `FemaleText_loc7`='¡He venido nada más ver tu bengala!' WHERE `ID`=71106;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼! 안두인 왕자님!', `FemaleText_loc4`='哦，不！安度因王子！', `FemaleText_loc5`='喔，不!安杜因王子!', `FemaleText_loc7`='¡Oh, no! ¡Príncipe Anduin!' WHERE `ID`=71107;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='걱정 마세요. 제가 그를 안전하게 사자의 상륙지로 데리고 갈게요. 거기서 다시 만나요.', `FemaleText_loc4`='别担心。我会把安度因平安送回雄狮港。我们回雄狮港见。', `FemaleText_loc5`='別擔心，我會把安杜因平安送回雄獅灘。我們那裡見。', `FemaleText_loc7`='No te preocupes. Llevaré a Anduin al Desembarco del León inmediatamente. Te veremos allí.' WHERE `ID`=71108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록이 동굴을 지키고 있네. 처치하세.', `MaleText_loc4`='那些蜥蜴人守着洞穴。我们得先对付他们。', `MaleText_loc5`='那些薩烏洛克在守護洞穴，我們來對付他們。', `MaleText_loc7`='Esos saurok vigilan la cueva. Ocupémonos de ellos.' WHERE `ID`=71109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너 같은 얼간이나 상대하려고 벌목감독관이 된 줄 알아?!', `MaleText_loc4`='我可不是为了砍倒你这样的木桩子才成为伐木大师的！', `MaleText_loc5`='我當上碎木大師可不是為了忍受你們這種傢伙!', `MaleText_loc7`='¡No sería maestro triturador si tolerase a chusma como tú!' WHERE `ID`=71110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 녹슬었군...', `MaleText_loc4`='我的手艺……生锈了……', `MaleText_loc5`='我生鏽了...', `MaleText_loc7`='Estaba oxidado...' WHERE `ID`=71111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 해줬네, $rt. 우리 작업자들이 아주 효율적으로 일하고 있어.', `MaleText_loc4`='你做得很好，$rt。你提高了我的工人们的效率。', `MaleText_loc5`='$rt，你做得很好。我的工人很有進展。', `MaleText_loc7`='Has trabajado bien, $rt. Mis obreros avanzan de forma eficiente.' WHERE `ID`=71112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 드릴까요?', `MaleText_loc4`='我能帮你什么忙吗？', `MaleText_loc5`='要來點什麼嗎?', `MaleText_loc7`='¿Quieres algo?' WHERE `ID`=71113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 덕분에 우린 무척 효율적으로 일하고 있네, $rt. 이 속도라면 작업이 빨리 끝날 것 같군.', `MaleText_loc4`='你让我们的工作效率提高了，$rt。按这个速度，我们的任务很快就会完成了。', `MaleText_loc5`='$rt，你讓我們工作起來有效率得多。依這個步調，我們的工作很快就完成了。', `MaleText_loc7`='Gracias a ti nuestro trabajo es de lo más eficiente, $rt. A este ritmo completaremos nuestra tarea en muy poco tiempo.' WHERE `ID`=71114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설치가 헤엄치듯 원활하게 이루어지고 있네, 친구. 지금처럼 계속 하기만 하면 되네.', `MaleText_loc4`='我们的进度迅如激流，朋友。你现在应该专注于让我们保持这样的速度。', `MaleText_loc5`='朋友，目前進度很順暢。你應該專心繼續目前的工作。', `MaleText_loc7`='Progresamos estupendamente, $gamigo:amiga;. Céntrate en seguir así.' WHERE `ID`=71115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역의 야생 동물들에게서 먹을 수 있는 음식을 구할 수 있네, $rt. 최선을 다해 우리 작업자들의 배를 채워 주게.', `MaleText_loc4`='附近野兽身上的肉都可食用，$rt。去找些肉来喂饱那些工人吧。', `MaleText_loc5`='$rt，這個區域的獸類，牠們的肉都是可食的。盡你所能地餵飽我們的工人。', `MaleText_loc7`='Todas las bestias de la región aportan carne comestible, $rt. Haz lo posible para alimentar a los obreros.' WHERE `ID`=71116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 모은 음식은 모두 여기 탁자에 올려놓게. 우리가 알아서 먹을 테니까.', `MaleText_loc4`='把你找到的食物都放到那边的桌子上吧，我们会自行取用。', `MaleText_loc5`='把你收集到的食物放在桌上就好，接下來交給我們。', `MaleText_loc7`='Solo tienes que depositar la comida que encuentres en esta mesa de aquí. Nosotros nos encargamos del resto.' WHERE `ID`=71117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 우리에게 가장 필요한 건 음식과 나무네. 그 외에도 우릴 더 돕고 싶다면 내게 다시 말하게.', `MaleText_loc4`='我们最主要的需求是食物和木材。如果你想要帮我们更多的忙，就和我谈谈吧。', `MaleText_loc5`='我們最需要的是食物和木材。如果你想進一步幫忙的話，再來找我。', `MaleText_loc7`='Nuestras necesidades primarias son la comida y la madera. Habla conmigo si quieres ayudarnos aún más.' WHERE `ID`=71118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 늪지에서도 쓸 만한 나무를 구할 수 있네. 땅에서 튀어나온 부러질 듯한 뿌리를 찾아보게.', `MaleText_loc4`='即使是在这片沼泽里也能找到可用的木材。去寻找那些暴露在土壤外的脆弱根茎吧。', `MaleText_loc5`='就算在這些沼澤裡，也有可供利用的木材。留意土裡伸出來的脆弱的樹根。', `MaleText_loc7`='Hasta en estos pantanos hay madera aprovechable. Busca raíces frágiles que sobresalgan de la tierra.' WHERE `ID`=71119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 여자가 옵니다!', `MaleText_loc4`='她来了！', `MaleText_loc5`='她來了!', `MaleText_loc7`='¡Aquí viene!', `FemaleText_loc1`='그 여자가 와요!', `FemaleText_loc4`='她来了！', `FemaleText_loc5`='她來了!', `FemaleText_loc7`='¡Aquí viene!' WHERE `ID`=71120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 작업자들은 모두 솜씨가 좋지. 하지만 전투라고는 해본 적도 없어. 너무 멀리 가지는 말게.', `MaleText_loc4`='我的工人有着高超的建筑技艺，却并不擅长战斗。别跑得太远了。', `MaleText_loc5`='我手下都是優秀的工人，可是他們遇到戰鬥就派不上用場了。你別離開太遠。', `MaleText_loc7`='Mis obreros son muy habilidosos, pero no están capacitados para el combate. No te alejes demasiado.' WHERE `ID`=71121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보급품을 한 번 가져다 준다고 해서 자네 일이 끝나는 건 아니네. 최선을 다해 물자가 풍족하게 유지될 수 있게 하게.', `MaleText_loc4`='把补给物资送达之后，你的工作还没有结束。你需要保持我们的资源存量。', `MaleText_loc5`='等你運送完補給，還有工作要做。盡量讓我們的資源不虞匱乏。', `MaleText_loc7`='No basta con entregar suministros. Esfuérzate en mantener una reserva de recursos.' WHERE `ID`=71122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 작업자를 공격한다면, 그런 위협이 사라질 때까지 덫 설치는 중단될 수밖에 없네.', `MaleText_loc4`='如果敌人骚扰到了工人的工作，生产就会陷入停滞，直到你击退敌人的进攻。', `MaleText_loc5`='如果你的敵人妨礙工人的作業，生產就會終止，直到威脅解除為止。', `MaleText_loc7`='Si tus enemigos atacan a un obrero, la productividad cesará hasta que se haya eliminado la amenaza.' WHERE `ID`=71123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제이나 님! 그만 두십시오!', `MaleText_loc4`='吉安娜！停下！', `MaleText_loc5`='珍娜!住手!', `MaleText_loc7`='¡Jaina! ¡Para!', `FemaleText_loc1`='제이나 님! 그만 두세요!', `FemaleText_loc4`='吉安娜！停下！', `FemaleText_loc5`='珍娜!住手!', `FemaleText_loc7`='¡Jaina! ¡Para!' WHERE `ID`=71124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 절대 굴하지...', `MaleText_loc4`='我不会屈服于——', `MaleText_loc5`='我不會屈服於...', `MaleText_loc7`='No me someteré a los...', `FemaleText_loc1`='나는 절대 굴하지...', `FemaleText_loc4`='我不会屈服于——', `FemaleText_loc5`='我不會屈服於...', `FemaleText_loc7`='No me someteré a los...' WHERE `ID`=71125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 하나도 몰랐는...', `MaleText_loc4`='我们不知道——', `MaleText_loc5`='我們不知道...', `MaleText_loc7`='No sabíam...', `FemaleText_loc1`='우리는 하나도 몰랐는...', `FemaleText_loc4`='我们不知道——', `FemaleText_loc5`='我們不知道...', `FemaleText_loc7`='No sabíam...' WHERE `ID`=71126;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우와아! 당신 덕분에 우리 작업 효율이 최고점을 찍었어요, $p 님!', `FemaleText_loc4`='哟！就是你让我们效率满满，$p！', `FemaleText_loc5`='耶!$p，你讓我們的工作效率達到頂點!', `FemaleText_loc7`='¡Yuju! ¡Nos tienes trabajando con una eficiencia óptima, $p!' WHERE `ID`=71127;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 대원들이 이렇게 빨리 일하는 건 처음 봤어요! 계속 뛰세요, $p 님!', `FemaleText_loc4`='这可是团队工作效率最高的一次！加油，$p！', `FemaleText_loc5`='我從來沒看過這個團隊的工作速度這麼快!$p，保持下去!', `FemaleText_loc7`='¡Nunca había visto a este equipo trabajar tan rápido! ¡Sigue así, $p!' WHERE `ID`=71128;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 잘 하고 계세요, $p 님! 이 속도라면, 덫도 곧 설치가 끝날 거예요!', `FemaleText_loc4`='干得好，$p！按这个速度，我们很快就能造好防御工事了！', `FemaleText_loc5`='$p，你做得很好!依這個速度，我們馬上就會完成防禦工事了!', `FemaleText_loc7`='¡Lo estás haciendo genial, $p! A este ritmo, acabaremos las defensas en un periquete.' WHERE `ID`=71129;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 노움은 신진대사가 무척 활발해요, $p 님. 식량이 떨어지지 않게 해 주세요!', `FemaleText_loc4`='我们侏儒的新陈代谢很快，$p。别让我们的食物存量见底了！', `FemaleText_loc5`='$p，我們地精的新陳代謝很快。別讓我們沒東西可吃!', `FemaleText_loc7`='Los gnomos tenemos el metabolismo rápido, $p. ¡No dejes que nos quedemos sin comida!' WHERE `ID`=71130;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주위의 야생 동물에게서 고기를 얻거나, 오크들에게서 전투 식량을 빼앗아 오세요. 우린 입맛이 까다롭지 않아요.', `FemaleText_loc4`='你可以从野生动物身上找到肉，或者从兽人身上找到军粮。我们从不挑剔食物。', `FemaleText_loc5`='從本地的野生動物身上收集獸肉，或者從獸人身上收集乾糧。我們吃東西很不挑的。', `FemaleText_loc7`='Reúne carne de la fauna local o raciones de los orcos. Nosotros comemos de todo.' WHERE `ID`=71131;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기요, $p 님. 철재가 많으면 일이 더 빨리 끝날 것 같아요. 주위의 크라사리 철 광석이면 충분하겠네요.', `FemaleText_loc4`='嘿$p，如果能帮我们找到足够的金属，我们的工作效率能提高不少。这附近的卡桑利铁矿石就不错。', `FemaleText_loc5`='嘿，$p，如果我們有很多金屬可以運用的話，工作起來會更快。本地的喀撒利鐵礦石就可以了。', `FemaleText_loc7`='Oye, $p, trabajaríamos más rápido si tuviéramos metal de sobra. Las menas de hierro Krasari que hay por aquí servirán.' WHERE `ID`=71132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기름기가 줄줄 흐르는 뱀을 찾아 보세요, $p 님. 쉽게 잡을 수 있을 거예요. 그 기름을 가마솥에 넣으면, 작업 속도가 올라갈 거고요.', `FemaleText_loc4`='注意寻找那些油腻的蛇，$p。它们很容易捕捉。把那些蛇油放进大锅里能让我们的工作速度变快。', `FemaleText_loc5`='$p，留意滑膩的蛇，牠們很好抓。把牠們身上的油放進鍋裡，我們工作起來會更快。', `FemaleText_loc7`='Mira a ver si encuentras alguna serpiente aceitosa, $p. Son fáciles de atrapar. Pon su aceite en el caldero y trabajaremos aún más rápido.' WHERE `ID`=71133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주위를 돌아다니는 도마뱀 녀석들이 아마 쓸 만한 걸 지니고 있을 거예요. 눈을 부릅뜨고 찾아보세요!', `FemaleText_loc4`='那些蜥蜴怪身上可能带有各种各样的东西。别放过他们！', `FemaleText_loc5`='這附近的蜥蜴人身上可能帶了任何東西，留意他們!', `FemaleText_loc7`='Los hombres lagarto de por aquí podrían llevar cualquier cosa encima. ¡Mantén los ojos abiertos!' WHERE `ID`=71134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='작업 효율을 극대화하려면, 보급품을 충분히 가져오세요.', `FemaleText_loc4`='为我们提供充分补给能让我们以最高效率工作。', `FemaleText_loc5`='保持我們的補給充足，就能獲得最大的產能。', `FemaleText_loc7`='Para que la producción siga al máximo, mantén una reserva de suministros.' WHERE `ID`=71135;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우릴 잘 지켜보셔야 해요, $p 님! 우린 기술자예요. 전사가 아니라고요. 맹수라도 나타나면, 당신의 도움이 필요해요!', `FemaleText_loc4`='注意我们这边的情况，$p！我们是建造师，不是战士。如果有敌人攻击，我们需要你帮我们防守！', `FemaleText_loc5`='$p，顧著我們一點!我們是工人，不是戰士。有野獸來的時候，需要你保護我們!', `FemaleText_loc7`='¡No nos quites el ojo de encima, $p! Somos obreros, no luchadores. Si viene alguna bestia, ¡necesitaremos que nos protejas!' WHERE `ID`=71136;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뱀 기름, 크라사리 철, 음식... 우리에게 도움이 될 수 있는 거라면 뭐든 찾아보세요!', `FemaleText_loc4`='蛇油，卡桑利生铁，还有食物……记得帮我们小组寻找这些有用的物资！', `FemaleText_loc5`='蛇油，喀撒利鐵礦，食物...留意任何可以幫助我們團隊的東西!', `FemaleText_loc7`='Aceite de culebra, hierro Krasari, comida... ¡Busca cualquier cosa que ayude al equipo!' WHERE `ID`=71137;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 가지 보급품을 여러 개 가져오시면 작업 효율도 더 높아질 거예요. 우릴 이롭게 하는 효과가 사라지지 않게 해 주세요.', `FemaleText_loc4`='你可以为我们提供相同的道具补给来获得额外的特效。尽量保持这些特效，别让它们过期了。', `FemaleText_loc5`='你可以一次提供我們好幾個同一種的物品，以獲得額外的效果。試著別讓效果消退。', `FemaleText_loc7`='A menudo puedes darnos varios objetos iguales para aumentar su efecto, pero procura que los beneficios no desaparezcan.' WHERE `ID`=71138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보급품을 충분히 가져오셔야 해요, $p 님. 효과가 사라지기라도 하면, 우리 작업 속도는 처음처럼 느린 속도로 돌아갈 거예요!', `FemaleText_loc4`='保证我们随时都有足够的补给，$p。别让这些效果过期，否则你又要从头开始了！', `FemaleText_loc5`='$p，讓補給保持充沛。別讓效果中斷，不然你就得從頭來過了!', `FemaleText_loc7`='Debes mantenernos bien suministrados, $p. ¡No dejes que los efectos expiren o tendrás que empezar de cero!' WHERE `ID`=71139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='최대한 효율적으로 일하는 연습을 하세요, $p 님! 언젠가 시간 싸움을 하게 될 날이 있을 테니까요...', `FemaleText_loc4`='进你可能提高你的效率，$p！总有一天，时间会成为决定性的因素……', `FemaleText_loc5`='$p，練習讓自己更有效率!有朝一日，你可能得分秒必爭...', `FemaleText_loc7`='Intenta ser lo más eficiente posible, $p. Algún día el tiempo podría ser un factor decisivo...' WHERE `ID`=71140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='<지지직> 응답하게, $p, 여긴 하늘 제독 로저스라네.', `FemaleText_loc4`='<静电噪音>请回答，$p，我是空军上将罗杰斯。', `FemaleText_loc5`='<雜音>$p，這裡是空軍上將羅傑斯，聽到請回答。', `FemaleText_loc7`='<Estática> $p, responde. Aquí la almirante del cielo Rogers.' WHERE `ID`=71141;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='더 바랄 게 없네요, 친구. 도와주셔서 정말 감사해요.', `FemaleText_loc4`='情况非常顺利，朋友。感谢你的援助。', `FemaleText_loc5`='朋友，情況再好不過了。謝謝你的幫忙。', `FemaleText_loc7`='La cosa no podría ir mejor, $gamigo:amiga;. Gracias por tu ayuda.' WHERE `ID`=71142;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 저희를 잘 도와주셨어요, $p 님. 완성이 머지 않았으니, 지금처럼만 계속해 주세요.', `FemaleText_loc4`='你的帮助非常重要，$p。我们已经接近完工了，请继续帮助我们。', `FemaleText_loc5`='$p，你幫了我們大忙。在我們即將完工的同時請繼續協助我們。', `FemaleText_loc7`='Nos has ayudado mucho, $p. No flaquees ahora que nos acercamos al final.' WHERE `ID`=71143;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자원이 충분히 확보되었어요. 모두 당신 덕분이죠. 계속 이렇게 해 주세요.', `FemaleText_loc4`='我们的资源储量充足，感谢你的帮助。请继续保持如此良好的势态。', `FemaleText_loc5`='多虧了你，我們的資源庫存很充足。請努力保持下去。', `FemaleText_loc7`='Tenemos suministros de sobra gracias a ti. Procura que no falten.' WHERE `ID`=71144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 우리 고향이기도 합니다! 이럴 수는 없습니다!', `MaleText_loc4`='这里也是我们的家！你不能这样做！', `MaleText_loc5`='這裡也是我們的家園!你不能這麼做!', `MaleText_loc7`='¡Este también es nuestro hogar! ¡No podéis hacer esto!', `FemaleText_loc1`='이곳은 우리 고향이기도 해요! 이럴 수는 없어요!', `FemaleText_loc4`='这里也是我们的家！你不能这样做！', `FemaleText_loc5`='這裡也是我們的家園!你不能這麼做!', `FemaleText_loc7`='¡Este también es nuestro hogar! ¡No podéis hacer esto!' WHERE `ID`=71145;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위습에게 일을 시키는 것에 익숙해져 있다보니, 배고픔이 낯서네요. 음식을 가져다 주세요.', `FemaleText_loc4`='我们已经习惯于使用小精灵来进行体力劳动了。请带一些食物来帮助我们保持动力。', `FemaleText_loc5`='我們習慣讓幽光進行勞動工作。請帶食物回來讓我們有東西吃。', `FemaleText_loc7`='Estamos acostumbrados a que los fuegos fatuos nos hagan el trabajo duro. Por favor, tráenos sustento.' WHERE `ID`=71146;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 일반적으로 야수의 육신을 직접 먹지 않아요. 하지만 지금의 상황을 고려해 보면, 아무래도 예외를 인정해야 할 것 같네요.', `FemaleText_loc4`='我们特别不适应把野兽的肉当作食物，但在如今的特殊情形下，我们也只能勉为其难了。', `FemaleText_loc5`='我們通常是不吃獸肉的，但局面使然，我們只能打破慣例。', `FemaleText_loc7`='Normalmente evitamos alimentarnos de la carne de las bestias, pero en esta situación tendremos que hacer una excepción.' WHERE `ID`=71147;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 묘목에 접붙일 나무를 가져다 주세요, $p 님. 인근에 있는 뿌리를 사용해야 할 것 같아요.', `FemaleText_loc4`='请为我们带一些木材回来，我们可以用来强化基地里的树苗，$p。这片区域里的根茎能够派上用场。', `FemaleText_loc5`='$p，帶木材回來嫁接在我們的樹苗上。我們得利用這片區域的樹根。', `FemaleText_loc7`='Tráenos madera para que podamos poner esquejes a nuestros árboles jóvenes, $p. Las raíces de la región tendrán que valer.' WHERE `ID`=71148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 마녀 같으니라고!', `MaleText_loc4`='联盟女巫！', `MaleText_loc5`='聯盟的女巫!', `MaleText_loc7`='¡Bruja de la Alianza!', `FemaleText_loc1`='얼라이언스의 마녀 같으니!', `FemaleText_loc4`='联盟女巫！', `FemaleText_loc5`='聯盟的女巫!', `FemaleText_loc7`='¡Bruja de la Alianza!' WHERE `ID`=71149;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳의 정령들에게서 얻을 수 있는 정령 깃든 물은 묘목들에 충분한 영양을 공급해 줄 거예요. 그 물로 통을 채워 놓으면, 다시 보충할 필요도 없지요.', `FemaleText_loc4`='附近的精怪身上携带有灵吻之水，这些水能够滋养我们的树苗。装满一次之后，你就不再需要去补充它们了。', `FemaleText_loc5`='本地妖精的魂靈親吻之水也能滋養我們的樹苗。而且桶子裝滿之後，你就不需要再補充它了。', `FemaleText_loc7`='El agua besada por los espíritus de los duendes locales alimentará a nuestros árboles jóvenes. Una vez llenado el cubo, no tendrás que volverlo a llenar.' WHERE `ID`=71150;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자신의 일을 태만히 하지 마세요. 보급품이 충분히 공급되어야 이 일도 빨리 끝나니까요.', `FemaleText_loc4`='不要灰心，朋友。帮我们寻找补给，我们的工作很快就能完成。', `FemaleText_loc5`='朋友，別偷懶。讓我們保持充足的補給，我們就能更快完工。', `FemaleText_loc7`='No flaquees, $gamigo:amiga;. Mantén nuestro nivel de suministros y terminaremos el trabajo antes.' WHERE `ID`=71151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 내 집이기도 합니다!', `MaleText_loc4`='这里也是我的家！', `MaleText_loc5`='這裡也是我的家!', `MaleText_loc7`='¡Este también es mi hogar!', `FemaleText_loc1`='이곳은 내 집이기도 하다고요!', `FemaleText_loc4`='这里也是我的家！', `FemaleText_loc5`='這裡也是我的家!', `FemaleText_loc7`='¡Este también es mi hogar!' WHERE `ID`=71152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 굴복하지 않겠다!', `MaleText_loc4`='我不会屈服的！', `MaleText_loc5`='我不會屈服的!', `MaleText_loc7`='¡No me someteré!', `FemaleText_loc1`='난 굴복하지 않아!', `FemaleText_loc4`='我不会屈服的！', `FemaleText_loc5`='我不會屈服的!', `FemaleText_loc7`='¡No me someteré!' WHERE `ID`=71153;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부디 저희를 지켜 주세요, $p 님. 여기 작업자들은 전투에 익숙하지 않아요. 공격이라도 받게 되면, 그대의 도움이 필요할 거예요.', `FemaleText_loc4`='帮助我们，$p。我们并不擅长战斗。一旦遭遇攻击，我们需要你来保护我们。', `FemaleText_loc5`='$p，保護我們。我們不習慣作戰，如果我們遭受攻擊，得靠你來保護我們。', `FemaleText_loc7`='Protégenos, $p. No estamos acostumbrados a luchar. Si nos atacan, nos hará falta tu protección.' WHERE `ID`=71154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='항복은 없다!', `MaleText_loc4`='绝不投降！', `MaleText_loc5`='絕不投降!', `MaleText_loc7`='¡No me rendiré!', `FemaleText_loc1`='항복은 없어!', `FemaleText_loc4`='绝不投降！', `FemaleText_loc5`='絕不投降!', `FemaleText_loc7`='¡No me rendiré!' WHERE `ID`=71155;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나무, 뱀 기름, 식량, 물... 이런 것들이 있으면 덫을 더 빨리 설치할 수 있어요. 부디, 어떻게든 저희에게 보급품을 가져다 주세요.', `FemaleText_loc4`='木材，蛇油，食物还有水能够加快我们的进度，$p。请尽你所能帮助我们。', `FemaleText_loc5`='$p，蛇油、喀撒利鐵礦、食物和水可以加快我們的進度。麻煩你盡量讓我們保持充足的補給。', `FemaleText_loc7`='La madera, el aceite de culebra, la comida y el agua acelerarán nuestro progreso, $p. Haz lo que puedas para proporcionarnos suministros.' WHERE `ID`=71156;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보급품을 계속 가져오시면서, 작업 효율이 떨어지지 않게 관리해 주세요.', `FemaleText_loc4`='为我们的营地提供补给之后，请保持补给品的存量，不要让特效消失。', `FemaleText_loc5`='補給我們營地的同時，盡量別讓效果消退。', `FemaleText_loc7`='Cuando nos traigas suministros, intenta que los beneficios no desaparezcan.' WHERE `ID`=71157;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳에서의 경험으로부터 많은 것을 배우시기를 바랄게요, $p 님. 언젠가 이번 일에 대한 보답을 받게 되실 거예요.', `FemaleText_loc4`='记得你在这里学得的经验，$p。在未来，你的高效会带给你丰厚的回报。', `FemaleText_loc5`='$p，從經驗中學習。你的努力會在將來開花結果。', `FemaleText_loc7`='Aprende mucho de tu experiencia en este lugar, $p. Es posible que en el futuro tu esfuerzo y tu eficiencia se vean recompensados.' WHERE `ID`=71158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 보낸 게... 겨우 너냐?', `MaleText_loc4`='所以……是联盟派你来的？', `MaleText_loc5`='所以聯盟...派了你過來?', `MaleText_loc7`='¿Así que la Alianza te ha enviado... a ti?' WHERE `ID`=71159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신참치곤 나쁘지 않았어...', `MaleText_loc4`='以新手而言算是不错了。', `MaleText_loc5`='對新手來說還不錯。', `MaleText_loc7`='No está mal para $gun novato:una novata;.' WHERE `ID`=71160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움 실력이 형편없군. 부끄러운 줄 알라고.', `MaleText_loc4`='你的战斗技巧真心差劲，你应该感到羞耻。', `MaleText_loc5`='你的戰鬥技巧很糟，你也該為此感到難過。', `MaleText_loc7`='Luchas mal y deberías sentirte mal.' WHERE `ID`=71161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 친 거냐? 우리 할머니가 너보단 주먹이 셌는데, 그래도 돌아가셨지!', `MaleText_loc4`='这就是你的攻击？我的奶奶都比你能打，她都已经过世了！', `MaleText_loc5`='你這樣也算是攻擊嗎?我死掉的祖母出手都比你還重!', `MaleText_loc7`='¿A eso le llamas pegar? Mi abuela podría pegar mejor, ¡y está muerta!' WHERE `ID`=71162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 그냥 멍청이처럼 가만히 서 있으라고. 너한테 딱 어울리네.', `MaleText_loc4`='就像个傻瓜一样站在那里吧，你最适合了。', `MaleText_loc5`='就站在旁邊耍笨吧，很適合你的。', `MaleText_loc7`='Quédate ahí con cara de $gtonto:tonta;, es lo mejor que sabes hacer.' WHERE `ID`=71163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 더러운 야크가 가득한 유황 광산보다 더 지독한 냄새가 난다고.', `MaleText_loc4`='你比沾满了硫磺矿没洗的牦牛还要难闻。', `MaleText_loc5`='你聞起來比一座塞滿了沒洗澡犛牛的硫磺礦坑還糟。', `MaleText_loc7`='Hueles peor que una mina de azufre llena de yaks sucios.' WHERE `ID`=71164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 우리 둘 다 놀랄 만한 똑똑한 짓을 해보는 게 어때? 이를테면 도망간다든가.', `MaleText_loc4`='你可以做点让我们都吃惊的聪明举动，比如夹起尾巴逃走。', `MaleText_loc5`='讓我們開開眼界、做點聰明事吧，比如說夾著尾巴逃跑。', `MaleText_loc7`='Sorpréndenos a los dos y haz algo inteligente, como salir corriendo.' WHERE `ID`=71165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달라란으로 가는 차원문이 필요합니다.', `MaleText_loc4`='我需要一个前往达拉然的传送门。', `MaleText_loc5`='我需要一個通往達納蘇斯的傳送門。', `MaleText_loc7`='Necesito un portal a Dalaran.', `FemaleText_loc1`='달라란으로 가는 차원문이 필요합니다.', `FemaleText_loc4`='我需要一个前往达拉然的传送门。', `FemaleText_loc5`='我需要一個通往達納蘇斯的傳送門。', `FemaleText_loc7`='Necesito un portal a Dalaran.' WHERE `ID`=71166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 블러드 엘프와 마찬가지로, 호드는 언제나 움직이고 변화하오. 하지만 이건 알아 두시오. 우리는, 견뎌낼 것이오.', `MaleText_loc4`='和我们的人民一样，部落也一直在改变，一直在变革。但不用怀疑，我们会度过这黑暗的时代。', `MaleText_loc5`='部落，也跟我們一樣，隨時都在變。但是我可以告訴你，我們一定會堅持下去的。', `MaleText_loc7`='La Horda, como nuestro pueblo, siempre está en movimiento, siempre cambiante. Pero no te equivoques: prevaleceremos.' WHERE `ID`=71167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 도둑놈들을 쫓아가죠!', `MaleText_loc4`='让我们找到那些小偷！', `MaleText_loc5`='我們去找出那些小偷吧!', `MaleText_loc7`='¡Vamos en busca de esos ladrones!', `FemaleText_loc1`='저 도둑놈들을 쫓아가죠!', `FemaleText_loc4`='让我们找到那些小偷！', `FemaleText_loc5`='我們去找出那些小偷吧!', `FemaleText_loc7`='¡Vamos en busca de esos ladrones!' WHERE `ID`=71168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 조사해라, 성물회. 반드시 찾아야 한다. 종은 호드에게 승리를 가져다 줄 것이다. 내 본능이 그렇게 말하는군.', `MaleText_loc4`='别停下，神圣遗物协会。我们会找到圣钟的。它会确保部落获得最终的胜利。我从骨子里相信这一点。', `MaleText_loc5`='聖匣守護者，繼續搜索，我們會找到的。聖鐘可以為部落帶來勝利，我從骨子裡就感覺得到。', `MaleText_loc7`='Seguid buscando, Relicario. La encontraremos. La campana es la clave de la victoria de la Horda. Lo siento en los huesos.' WHERE `ID`=71169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 내가 그걸 차지한 다음에 어떻게 쓰는지 알아내겠다, 블러드 엘프.', `MaleText_loc4`='当我拥有它之后，我自会考虑如何使用它，血精灵。', `MaleText_loc5`='血精靈，等我得到它以後，我再來思考要怎麼運作這個東西。', `MaleText_loc7`='Ya me preocuparé de cómo funciona cuando la tenga en mis manos, elfo de sangre.' WHERE `ID`=71170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종은 무한한 힘을 가진 무기다. 그것은 호드의 것이다. 나의 것이다!', `MaleText_loc4`='圣钟是武器，它的力量无可置疑。它属于部落，属于我！', `MaleText_loc5`='聖鐘是個擁有絕大力量的武器。它是部落的東西，是我的東西!', `MaleText_loc7`='La Campana divina es un arma de poder incuestionable. Debe estar en manos de la Horda. ¡Debe estar en mis manos!' WHERE `ID`=71171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실하다! 이 문서들이 온통 종과 쿤라이 봉우리를 언급하고 있다. 분명 종은 그곳에 있을 것이다.', `MaleText_loc4`='我们接近了！所有文献都表明圣钟就在昆莱山。它肯定在这里。', `MaleText_loc5`='我們很接近了!這些文件全都提到了聖鐘和崑萊峰，它一定就在這裡。', `MaleText_loc7`='¡Estamos cerca! Todos estos documentos mencionan la campana y la Cima Kun-Lai. Debe de estar aquí.' WHERE `ID`=71172;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='몇 날 동안 땅을 팠지만 찾은 거라곤 먼지투성이인 두루마리랑 깨진 석상들뿐입니다.', `FemaleText_loc4`='我们已经找了好几天，却只找到一些尘封的卷轴和破损的雕像。', `FemaleText_loc5`='我們搜索了好幾天，只找到陳舊的卷軸和破舊的雕像。', `FemaleText_loc7`='Llevamos días buscando. Solo hemos encontrado pergaminos polvorientos y estatuas rotas.' WHERE `ID`=71173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천상의 종도 이렇게 파손돼있으면 어찌합니까? 그걸 발굴해내도 사용할 수 있으시겠습니까?', `MaleText_loc4`='万一圣钟也年久失修了怎么办？就算我们能找到它，你确定它还能用吗？', `MaleText_loc5`='如果聖鐘也荒廢了怎麼辦?你確定我們找到它以後就有辦法利用它嗎?', `MaleText_loc7`='¿Y si la Campana divina también está en mal estado? Incluso si la encontramos, ¿seguro que la podrás utilizar?', `FemaleText_loc1`='천상의 종도 이렇게 파손돼있으면 어찌합니까? 그걸 발굴해내도 사용할 수 있으시겠습니까?', `FemaleText_loc4`='万一圣钟也年久失修了怎么办？就算我们能找到它，你确定它还能用吗？', `FemaleText_loc5`='如果聖鐘也荒廢了怎麼辦?你確定我們找到它以後就有辦法利用它嗎?', `FemaleText_loc7`='¿Y si la Campana divina también está en mal estado? Incluso si la encontramos, ¿seguro que la podrás utilizar?' WHERE `ID`=71174;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구들이 종을 숨겼을 때 무언가 이유가 있었을겁니다, 대족장님.', `FemaleText_loc4`='或许魔古族出于某些原因将圣钟藏了起来，酋长。', `FemaleText_loc5`='大酋長，也許魔古把聖鐘藏起來是有理由的。', `FemaleText_loc7`='A lo mejor los mogu escondieron la campana por algo, Jefe de Guerra.' WHERE `ID`=71175;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐!', `MaleText_loc4`='嘿！', `MaleText_loc5`='嘿!', `MaleText_loc7`='¡Oye!', `FemaleText_loc1`='거기서 손 떼!', `FemaleText_loc4`='把你的手拿开！', `FemaleText_loc5`='把你的手拿開!', `FemaleText_loc7`='¡Quita las manos de ahí!' WHERE `ID`=71176;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 구린 냄새가 났는데!', `MaleText_loc4`='我好像闻到了什么味道！', `MaleText_loc5`='我以為我聞到了什麼味道!', `MaleText_loc7`='¡Ya me parecía haber olido algo!', `FemaleText_loc1`='이봐!', `FemaleText_loc4`='嘿！', `FemaleText_loc5`='嘿!', `FemaleText_loc7`='¡Oye!' WHERE `ID`=71177;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여!', `MaleText_loc4`='为了部落！', `MaleText_loc5`='為了部落!', `MaleText_loc7`='¡Por la Horda!', `FemaleText_loc1`='얼라이언스에게 죽음을!', `FemaleText_loc4`='联盟统统去死！', `FemaleText_loc5`='聯盟去死吧!', `FemaleText_loc7`='¡Muerte a la Alianza!' WHERE `ID`=71178;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아는 우리 거야!', `MaleText_loc4`='潘达利亚是我们的！', `MaleText_loc5`='潘達利亞是我們的!', `MaleText_loc7`='¡Pandaria nos pertenece!', `FemaleText_loc1`='침입자다!', `FemaleText_loc4`='你侵入了我们的地盘！', `FemaleText_loc5`='你闖入了我們的地盤!', `FemaleText_loc7`='¡Esto es propiedad privada!' WHERE `ID`=71179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 네놈들한테 이 땅을 내줄 줄 알아?!', `MaleText_loc4`='你休想从我们手上夺走这片土地！', `MaleText_loc5`='你永遠沒辦法從我們手中奪走這片土地!', `MaleText_loc7`='¡Nunca nos arrebatarán esta tierra!', `FemaleText_loc1`='가로쉬 님께 네 머리를 가져다 드려야겠군!', `FemaleText_loc4`='加尔鲁什会砍掉你的脑袋！', `FemaleText_loc5`='卡爾洛斯會拿下你的人頭!', `FemaleText_loc7`='¡Garrosh te cortará la cabeza!' WHERE `ID`=71180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기서 손 떼!', `MaleText_loc4`='把你的手拿开！', `MaleText_loc5`='把你的手拿開!', `MaleText_loc7`='¡Quita las manos de ahí!', `FemaleText_loc1`='이봐! 거기 너!', `FemaleText_loc4`='嘿，你！', `FemaleText_loc5`='嘿，你!', `FemaleText_loc7`='¡Oye! ¡Tú!' WHERE `ID`=71181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 나가라고!', `MaleText_loc4`='滚出去！', `MaleText_loc5`='滾出去!', `MaleText_loc7`='¡Fuera de aquí!', `FemaleText_loc1`='뭔가 구린 냄새가 나더라니!', `FemaleText_loc4`='我好像闻到了什么味道！', `FemaleText_loc5`='我以為我聞到了什麼味道!', `FemaleText_loc7`='¡Ya me parecía haber olido algo!' WHERE `ID`=71182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닥쳐라, 겁쟁이. 확실하게 대답해야 할것이다. 너는 어느 쪽에 충성을 다하겠느냐? 키린 토인가, 호드인가?', `MaleText_loc4`='闭嘴，懦夫。你最好扪心自问一下自己效忠的是谁：是肯瑞托？还是部落？', `MaleText_loc5`='安靜，懦夫。你最好想清楚自己對誰效忠:是祈倫托，還是部落?', `MaleText_loc7`='Silencio, cobarde. Pregúntate a quién le debes lealtad: ¿al Kirin Tor o a la Horda?' WHERE `ID`=71183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스에 죽음을!', `MaleText_loc4`='联盟统统去死！', `MaleText_loc5`='聯盟去死吧!', `MaleText_loc7`='¡Muerte a la Alianza!', `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！', `FemaleText_loc5`='為了部落', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=71184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허, 감히 여길 침입해!', `MaleText_loc4`='嗯？！入侵者！', `MaleText_loc5`='你敢擅闖進來?!', `MaleText_loc7`='¡Allanamiento!', `FemaleText_loc1`='도둑이야!', `FemaleText_loc4`='小偷！', `FemaleText_loc5`='小偷!', `FemaleText_loc7`='¡$gLadrón:Ladrona;!' WHERE `ID`=71185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 가로쉬 님께 그렇게 말씀 드려도 괜찮은건가? 그 키린 토의 계집에게 고개를 숙이라 했다고?', `MaleText_loc4`='够了！你想让我去报告加尔鲁什，说你让我们向那个肯瑞托丫头低头吗？！', `MaleText_loc5`='夠了!你要我向卡爾洛斯回報說，你要我們向祈倫托的那個女人俯首稱臣?!', `MaleText_loc7`='¡Ya basta! ¿Quieres que informe a Garrosh de que nos has pedido que nos sometamos a esa bruja del Kirin Tor?' WHERE `ID`=71186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 어찌 감히 여기에!', `MaleText_loc4`='你不属于这里！', `MaleText_loc5`='你不屬於這裡!', `MaleText_loc7`='¡No tienes nada que hacer aquí!', `FemaleText_loc1`='얼라이언스를 위하여!', `FemaleText_loc4`='为了联盟！', `FemaleText_loc5`='為了聯盟!', `FemaleText_loc7`='¡Por la Alianza!' WHERE `ID`=71187;
