UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나이트 엘프들은 달라란의 차원문을 너무 방치했소. 지맥을 바꾸는 건 식은죽 먹기였지...', `MaleText_loc4`='暗夜精灵没有认真守好他们在达拉然的传送门。要利用那条魔法轨迹很容易……', `MaleText_loc5`='夜精靈沒有好好地管制他們在達拉然的傳送門。只要利用那裡的地脈...', `MaleText_loc7`='Los elfos de la noche no aseguraron los portales de Dalaran correctamente. Aprovechar las líneas Ley ha sido coser y cantar...' WHERE `ID`=71195;
