UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠소이다. 못 본 걸로 해주지. 하지만 경고하겠소. 더는 키린 토와 우리의 관계를 이용하려고 하지 마시오.', `MaleText_loc4`='好吧。我什么也没看见。可下次，你休想再利用我们与肯瑞托的关系。', `MaleText_loc5`='很好，我什麼都沒看到。不過，以後你不准再利用我們和祈倫托的關係。', `MaleText_loc7`='Muy bien. No he visto nada. Pero nunca más volverás a aprovecharte de nuestra relación con el Kirin Tor.' WHERE `ID`=71223;
