UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 판다렌은 평화로운 종족이에요. 하지만 가끔은 화끈한 싸움질도 무척 좋아하죠!', `FemaleText_loc4`='我们熊猫人是热爱和平的种族，但我们也喜欢偶尔看看精彩的拳赛！', `FemaleText_loc5`='我們熊貓人愛好和平，有時也喜歡好好打上一架!', `FemaleText_loc7`='Los pandaren somos una raza pacífica, pero de vez en cuando nos gusta una buena pelea.' WHERE `ID`=71225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다렌들은 보물 더미 위에 앉아 있다고. 여기엔 심지어 브리쿨에 대한 책도 있다니까. 브리쿨 말이야! 어이가 없어서! 판다렌들은 브리쿨을 만나본 적도 없을 텐데!', `MaleText_loc4`='这些熊猫人真是坐拥宝山而不自知。他们甚至有关于维库人的记载。我说的可是维库人！天呐！他们是怎么遇上的？', `MaleText_loc5`='這些熊貓人坐擁寶山卻不自知。這裡甚至有關於維酷人的文獻。維酷人!拜託!他們怎麼可能會碰到維酷人?', `MaleText_loc7`='Estos pandaren poseen auténticos tesoros. Tienen libros hasta sobre los vrykuls. ¡Los vrykuls! ¡En serio! ¿Cómo es posible que sepan de su existencia?' WHERE `ID`=71226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대가를 치를 때가 왔다!', `MaleText_loc4`='该付过路费啦！', `MaleText_loc5`='付出代價的時候到了!', `MaleText_loc7`='¡Hora de pagar peaje!' WHERE `ID`=71227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정하십시오, 에이타스. 이 공격은 절대 감지 당하지 않을 것이오. 내가 장담하지.', `MaleText_loc4`='放松点，艾萨斯。他们追查不到这次袭击的。我保证。', `MaleText_loc5`='放輕鬆點，埃薩。沒有人能追蹤這次的行動，我保證。', `MaleText_loc7`='Tranquilo, Aethas. No es posible rastrear este ataque. Estoy seguro.' WHERE `ID`=71228;
