UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 노움들! 갑자기 하늘 어딘가에서 나타나서 우리 기지를 몽땅 불태웠네.

정제소 전체에 불이 붙었고 얼라이언스 본대는 요새로 곧 진군해올 걸세!

놈들을 막기엔 우리가 숫적으로 열세야...', `MaleText_loc4`='卑鄙的侏儒！他们从天上冲下来，把一切都点着了。

现在整个炼油厂都着火了，联盟的主力部队随时都会杀到要塞外面！

我们的人手不足以挡住他们……', `MaleText_loc5`='可惡的地精!他們從天而降，四處開火。

現在精煉廠著火了，聯盟的主要部隊隨時會朝要塞進攻!

我們沒有足夠的兵力阻止他們...', `MaleText_loc7`='¡Malditos gnomos! Cayeron del cielo y le prendieron fuego a TODO.

Ahora toda la refinería está ardiendo y el ejército principal de la Alianza atacará el fuerte en cualquier momento.

No somos suficientes para detenerlos...' WHERE `ID`=71253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽는 한이 있더라도 지배령 거점을 지키겠다!', `MaleText_loc4`='我们要誓死保卫统御岗哨！', `MaleText_loc5`='我們會死守制霸岬!', `MaleText_loc7`='¡Defenderemos el Punto de Dominio o moriremos en el intento!' WHERE `ID`=71254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(장군 나즈그림이 당신과 합류합니다.)|r', `MaleText_loc4`='一起行动吧。|cFF0008E8（纳兹戈林将军会跟着你。）|r', `MaleText_loc5`='與我們一同作戰。|cFF0008E8(納茲格寧姆將軍會跟隨你。)|r', `MaleText_loc7`='Lucha con nosotros. |cFF0008E8(El general Nazgrim te seguirá.)|r', `FemaleText_loc1`='우리와 함께 싸우시죠. |cFF0008E8(장군 나즈그림이 당신과 합류합니다.)|r', `FemaleText_loc4`='一起行动吧。|cFF0008E8（纳兹戈林将军会跟着你。）|r', `FemaleText_loc5`='與我們一同作戰。|cFF0008E8(納茲格寧姆將軍會跟隨你。)|r', `FemaleText_loc7`='Lucha con nosotros. |cFF0008E8(El general Nazgrim te seguirá.)|r' WHERE `ID`=71255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지원군이 왔다고 감히 얼라이언스 놈들이 호드의 땅을 넘봐? 그것도 내 요새를? 본때를 보여주지!', `MaleText_loc4`='如果联盟以为靠一点点援军就能攻破我的堡垒，那他们就大错特错了！', `MaleText_loc5`='如果聯盟以為增加一些兵力就能攻下我的堡壘，那他們有得瞧了!', `MaleText_loc7`='Si la Alianza se cree que unos pocos refuerzos bastan para conquistar MI fortaleza, ¡se equivocan!' WHERE `ID`=71256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부관들은 다들 죽거나 행방불명됐소.', `MaleText_loc4`='我的指挥官们不是死了就是失踪了。', `MaleText_loc5`='我的指揮官不是死了，就是行蹤不明。', `MaleText_loc7`='Todos mis superiores están muertos o desaparecidos.' WHERE `ID`=71257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정보가 필요하오. 지금 당장 말이오. 얼라이언스가 얼마나 남아있고 싸울 수 있는 오크들은 몇인지. 그리고 그 클러치팝인가 뭔가 하는 정신 나간 고블린을 도와 방어선을 구축하시오.', `MaleText_loc4`='我需要情报，立刻就要！联盟还有多少人，我们还有多少兽人——还有，去帮那个地精疯子急刹建几个防御阵地。', `MaleText_loc5`='給我數字，快。聯盟還有多少兵力，我們還有多少獸人?還有，去幫助那個瘋狂的哥布林窩爆設立防禦措施。', `MaleText_loc7`='Necesito información YA. ¿Cuántos efectivos le quedan a la Alianza? ¿Cuántos orcos tenemos? Y ayuda a ese goblin loco de Rompemarchas a preparar las defensas.' WHERE `ID`=71258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔소. 놈들이 또 오는군!', `MaleText_loc4`='你们来得真及时。他们又过来了！', `MaleText_loc5`='好時機，他們又來了!', `MaleText_loc7`='Justo a tiempo. ¡Ya vuelven!' WHERE `ID`=71259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런트 전원, 전투 준비!', `MaleText_loc4`='准备好，你们这些肮脏的蛮兵！', `MaleText_loc5`='做好準備，你們這群蠻兵!', `MaleText_loc7`='¡Prepárense, brutos!' WHERE `ID`=71260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도우러 왔습니다.', `MaleText_loc4`='我们是来帮忙的。', `MaleText_loc5`='任憑差遣。', `MaleText_loc7`='Hemos venido a ayudar.', `FemaleText_loc1`='도우러 왔습니다.', `FemaleText_loc4`='我们是来帮忙的。', `FemaleText_loc5`='任憑差遣。', `FemaleText_loc7`='Hemos venido a ayudar.' WHERE `ID`=71261;
