UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리했다! 호드를 위하여!', `MaleText_loc4`='胜利！胜利属于部落！', `MaleText_loc5`='勝利!部落的勝利!', `MaleText_loc7`='¡Victoria! ¡VICTORIA PARA LA HORDA!' WHERE `ID`=71263;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다! 전원, 전투 준비!', `MaleText_loc4`='他们来了！顶住！', `MaleText_loc5`='他們來了!堅持到底!', `MaleText_loc7`='¡Aquí vienen! ¡AGUANTEN!' WHERE `ID`=71264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 헬스크림 님께서 자랑스러워하실 것이다! 도축할 고깃덩어리들이 더 오는군...', `MaleText_loc4`='哈！地狱咆哮会为我们骄傲的！敌人又上来送死了……', `MaleText_loc5`='哈!地獄吼以你們為榮!更多的聯盟肥肉自動送上口...', `MaleText_loc7`='¡JA! ¡Grito Infernal estará orgulloso! Aquí vienen más corderos al matadero...' WHERE `ID`=71265;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸워라! 헬스크림 님께서 우릴 지켜보신다!', `MaleText_loc4`='继续战斗，蛮兵！地狱咆哮之眼在注视着我们！', `MaleText_loc5`='蠻兵們，奮勇殺敵!地獄吼的雙眼在盯著你!', `MaleText_loc7`='¡Sigan luchando, brutos! ¡GRITO INFERNAL NOS OBSERVA!' WHERE `ID`=71266;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들의 마지막 공격이다! 지배령 거점을 위해! 모두 도륙을 내버려라!', `MaleText_loc4`='这是最后一波攻击了。为了统御岗哨！把他们全杀光！', `MaleText_loc5`='展開最後一波襲擊。為了制霸岬!將他們趕盡殺絕!', `MaleText_loc7`='Aquí viene el último asalto. ¡Por el Punto de Dominio! ¡MASÁCRENLOS A TODOS!' WHERE `ID`=71267;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두들, 무기를 들어라! 저들이 곧 공격할것이다.', `MaleText_loc4`='拿起武器，你们这些大怪物！他们要冲锋了。', `MaleText_loc5`='部落的勇猛怪物們，舉起武器!他們就要衝過來了。', `MaleText_loc7`='¡Alcen las armas, magníficos monstruos! Están a punto de cargar.' WHERE `ID`=71268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Don''t forget to set your worldstate area!', `MaleText_loc4`='Don''t forget to set your worldstate area!', `MaleText_loc5`='別忘了設定你的世界狀態地區!', `MaleText_loc7`='¡No olvides establecer tu zona del estado del mundo!', `FemaleText_loc1`='Don''t forget to set your worldstate area!', `FemaleText_loc4`='Don''t forget to set your worldstate area!', `FemaleText_loc5`='別忘了設定你的世界狀態地區!', `FemaleText_loc7`='¡No olvides establecer tu zona del estado del mundo!' WHERE `ID`=71271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='This is the Thunder King Raid!', `MaleText_loc4`='This is the Thunder King Raid!', `MaleText_loc5`='這就是雷王的副本!', `MaleText_loc7`='¡Esta es la banda del Rey del Trueno!', `FemaleText_loc1`='This is the Thunder King Raid!', `FemaleText_loc4`='This is the Thunder King Raid!', `FemaleText_loc5`='這就是雷王的副本!', `FemaleText_loc7`='¡Esta es la banda del Rey del Trueno!' WHERE `ID`=71272;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='Thunder begins with a shock wave in the air due to the sudden thermal expansion of the plasma in the lightning channel!', `MaleText_loc4`='由于闪电通道中的离子突然发生热膨胀，空气中出现一道震动波，雷声开始鸣响！', `MaleText_loc5`='雷聲是來自於空氣中的衝擊波，因為閃電路徑上等離子受到突然的熱膨脹所造成的。', `MaleText_loc7`='¡El trueno comienza con una onda expansiva en el aire debida a la expansión térmica del plasma en el canalizador de relámpagos!', `FemaleText_loc1`='Thunder begins with a shock wave in the air due to the sudden thermal expansion of the plasma in the lightning channel!', `FemaleText_loc4`='由于闪电通道中的离子突然发生热膨胀，空气中出现一道震动波，雷声开始鸣响！', `FemaleText_loc5`='雷聲是來自於空氣中的衝擊波，因為閃電路徑上等離子受到突然的熱膨脹所造成的。', `FemaleText_loc7`='¡El trueno comienza con una onda expansiva en el aire debida a la expansión térmica del plasma en el canalizador de relámpagos!' WHERE `ID`=71273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='The speed of sound in dry air is approximately 343 m/s!', `MaleText_loc4`='在干燥的空气中，声波的传递速度约为343米/秒！', `MaleText_loc5`='乾燥空氣下的音速約為每秒343公尺!', `MaleText_loc7`='¡La velocidad del sonido en el aire seco es de aproximadamente 343 m/s!', `FemaleText_loc1`='The speed of sound in dry air is approximately 343 m/s!', `FemaleText_loc4`='在干燥的空气中，声波的传递速度约为343米/秒！', `FemaleText_loc5`='乾燥空氣下的音速約為每秒343公尺!', `FemaleText_loc7`='¡La velocidad del sonido en el aire seco es de aproximadamente 343 m/s!' WHERE `ID`=71274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가기는 할 것이나, 우리 일족을 대표하는 증인으로서다. 누군가는 널 주시해야 하니까, 가로쉬.', `MaleText_loc4`='我可以去，以证明巨魔的清白。会有人来收拾你的，加尔鲁什。', `MaleText_loc5`='好，我接受。但只是做為我族人的見證而已。總得有人管管你，卡爾洛斯。', `MaleText_loc7`='Iré, pero solo como testigo para mi gente. Alguien tiene que tenerte vigilado, Garrosh.' WHERE `ID`=71275;
