UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1과;와; 라크고르 블러드레이저가 조용히 비밀스러운 얘기를 주고받습니다.', `MaleText_loc4`='%s和拉克戈尔·血刃轻声交流了几句。', `MaleText_loc5`='%s與瑞茍爾·血剃刃私下密議。', `MaleText_loc7`='%s y Rak''gor Hojasangre hablan entre susurros.' WHERE `ID`=71278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 사마귀들이 탑을 지키고 있어, $p. 놈들을 처리하지 못하면 탑에는 흠집도 못 낼 거야.', `MaleText_loc4`='那些螳螂妖想要保护塔楼，$p。消灭它们，否则我们无法进攻。', `MaleText_loc5`='螳螂人保護著這些控制塔，$p。解決他們，否則我們無法命中目標。', `MaleText_loc7`='Esos mántides protegen las torres, $p. Elimínalos o no podremos disparar a nada.', `FemaleText_loc1`='저 사마귀들이 탑을 지키고 있어요, $p. 놈들을 처리하지 못하면 탑에는 흠집도 못 낼 거예요.', `FemaleText_loc4`='那些螳螂妖想要保护塔楼，$p。消灭它们，否则我们无法进攻。', `FemaleText_loc5`='螳螂人保護著這些控制塔，$p。解決他們，否則我們無法命中目標。', `FemaleText_loc7`='Esos mántides protegen las torres, $p. Elimínalos o no podremos disparar a nada.' WHERE `ID`=71280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 전갈들이 탑을 움직이고 있어! 처치하라고!', `MaleText_loc4`='那些蝎子在移动塔楼！消灭它们！', `MaleText_loc5`='那些蠍子正在移動音波控制塔!把牠們先幹掉!', `MaleText_loc7`='¡Los escórpidos trasladan las torres! ¡Elimínalos!', `FemaleText_loc1`='저 전갈들이 탑을 움직이고 있어요! 처치하세요!', `FemaleText_loc4`='那些蝎子在移动塔楼！消灭它们！', `FemaleText_loc5`='那些蠍子正在移動音波控制塔!把牠們先幹掉!', `FemaleText_loc7`='¡Los escórpidos trasladan las torres! ¡Elimínalos!' WHERE `ID`=71281;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘하셨습니다! 어서 이 폭탄들을 제독님께 가져가야겠군요.', `MaleText_loc4`='干得好，$p！我们马上就把这些炸弹送回上将那儿去。', `MaleText_loc5`='做得好，$p!我們得趕緊將這些炸彈拿回去給上將。', `MaleText_loc7`='¡Buen trabajo, $p! Llevaremos las bombas al almirante de inmediato.', `FemaleText_loc1`='잘하셨습니다! 어서 이 폭탄들을 제독님께 가져가야겠군요.', `FemaleText_loc4`='干得好，$p！我们马上就把这些炸弹送回上将那儿去。', `FemaleText_loc5`='做得好，$p!我們得趕緊將這些炸彈拿回去給上將。', `FemaleText_loc7`='¡Buen trabajo, $p! Llevaremos las bombas al almirante de inmediato.' WHERE `ID`=71282;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우웩! 음식이 왜 이따위야?!', `MaleText_loc4`='呃，真恶心！这些食物太恐怖了！', `MaleText_loc5`='噁，呸!真難吃!', `MaleText_loc7`='¡Puaj! ¡Esta comida es horrorosa!', `FemaleText_loc1`='어째서 뷔페엔 항상 먹을 만한 게 없는 거지?', `FemaleText_loc4`='自助餐为什么总是没有好东西呢？', `FemaleText_loc5`='為什麼自助餐都沒什麼好吃的?', `FemaleText_loc7`='¿Por qué en los bufés nunca hay nada bueno?' WHERE `ID`=71283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 이런 걸 먹는다는 거지?', `MaleText_loc4`='谁会吃这种东西啊？', `MaleText_loc5`='這東西誰會想吃啊?', `MaleText_loc7`='¿Pero quién se come esto?', `FemaleText_loc1`='세직은 이딴 걸 요리라고 부르는 거야?!', `FemaleText_loc4`='塞兹克管这叫食物？！', `FemaleText_loc5`='瑟席克居然敢端出這種食物?!', `FemaleText_loc7`='¡¿Sezik llama comida a esto?!' WHERE `ID`=71284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이딴 음식을 먹을 거라고 생각했다면, 감독관은 단단히 착각한 거야!', `MaleText_loc4`='要是女工头以为我会吃这种垃圾，那她就是个白痴！', `MaleText_loc5`='如果女頭目以為我會吃下這條蛆，她肯定是瘋了!', `MaleText_loc7`='¡La dama jefa está loca si cree que me comeré esta bazofia!', `FemaleText_loc1`='이렇게 끔찍한 음식을 내놓다니, 나 정말 상처 받았다고!', `FemaleText_loc4`='这些玩意儿伤害了我的感情！', `FemaleText_loc5`='這樣的食物對我的感官是種侮辱!', `FemaleText_loc7`='¡Este desastre ofende mi sensibilidad!' WHERE `ID`=71285;
