UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허술사는 비밀의 전당에 있습니다. 건물에 들어가서 계단을 올라간 후 오른쪽으로 가시면 됩니다.', `MaleText_loc4`='你可以在秘语大厅中找到虚空契约者，进门后上楼右转就是。', `MaleText_loc5`='虛空編織師就在秘密大廳裡，進去以後樓上右手邊。', `MaleText_loc7`='El vinculador del vacío se encuentra en la Sala de los Secretos, subiendo las escaleras a la derecha según entras en el edificio.', `FemaleText_loc1`='공허술사는 비밀의 전당에 있습니다. 건물에 들어가서 계단을 올라간 후 오른쪽으로 가시면 됩니다.', `FemaleText_loc4`='你可以在秘语大厅中找到虚空契约者，进门后上楼右转就是。', `FemaleText_loc5`='虛空編織師就在秘密大廳裡，進去以後樓上右手邊。', `FemaleText_loc7`='El vinculador del vacío se encuentra en la Sala de los Secretos, subiendo las escaleras a la derecha según entras en el edificio.' WHERE `ID`=71296;
