UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Without these throwing axes, their axe throwers will certainly be less effective.', `FemaleText_loc4`='没有了这些飞斧，他们的掷斧者就起不了什么作用了。', `FemaleText_loc5`='沒了這些斧頭，他們的擲斧兵可就無法發揮全力了。', `FemaleText_loc7`='Sin estas hachas arrojadizas, sus lanzahachas serán, sin duda, menos eficientes.' WHERE `ID`=71304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 싶다고? 더 강해지면 다시 찾아오게.$b$b그래도 관람은 언제든 할 수 있지.', `MaleText_loc4`='你想要参加搏击？等你变得更强壮之后再回来吧。$b$b当然，欢迎你留下来观看比赛。', `MaleText_loc5`='你想上場打?等你更強一點再來吧。$b$b不過歡迎你當觀眾就是。', `MaleText_loc7`='¿Quieres luchar? Vuelve cuando seas un poco más fuerte.$b$bPero puedes quedarte a mirar.', `FemaleText_loc1`='싸우고 싶다고? 더 강해지면 다시 찾아오게.$b$b그래도 관람은 언제든 할 수 있지.', `FemaleText_loc4`='你想要参加搏击？等你变得更强壮之后再回来吧。$b$b当然，欢迎你留下来观看比赛。', `FemaleText_loc5`='你想上場打?等你更強一點再來吧。$b$b不過歡迎你當觀眾就是。', `FemaleText_loc7`='¿Quieres luchar? Vuelve cuando seas un poco más fuerte.$b$bPero puedes quedarte a mirar.' WHERE `ID`=71305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 싶다고? 초대장이 필요하다네.$b$b그래도 관람은 마음대로 할 수 있지.', `MaleText_loc4`='你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。', `MaleText_loc5`='你想上場打?你要有邀請函才行。$b$b不過歡迎你當觀眾就是。', `MaleText_loc7`='¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.', `FemaleText_loc1`='싸우고 싶다고? 초대장이 필요하다네.$b$b그래도 관람은 마음대로 할 수 있지.', `FemaleText_loc4`='你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。', `FemaleText_loc5`='你想上場打?你要有邀請函才行。$b$b不過歡迎你當觀眾就是。', `FemaleText_loc7`='¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.' WHERE `ID`=71306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $n, 너의 심장은 아주 적합한 제물이 될 것이다!', `MaleText_loc4`='啊，$n，你的心脏会是一件出色的祭品！', `MaleText_loc5`='啊，$n，你的心臟可是上等的祭品!', `MaleText_loc7`='¡Ah, $n, tu corazón servirá de sacrificio!', `FemaleText_loc1`='아, $n, 너의 심장은 아주 적합한 제물이 될 것이다!', `FemaleText_loc4`='啊，$n，你的心脏会是一件出色的祭品！', `FemaleText_loc5`='啊，$n，你的心臟可是上等的祭品!', `FemaleText_loc7`='¡Ah, $n, tu corazón servirá de sacrificio!' WHERE `ID`=71307;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='That''s fewer accursed Zandalari Priests we have to deal with.', `FemaleText_loc4`='我们要对付的赞达拉祭司又少了一些。', `FemaleText_loc5`='要對付的贊達拉祭司又少幾個了。', `FemaleText_loc7`='Menos sacerdotes Zandalari de los que preocuparnos; estupendo.' WHERE `ID`=71314;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Those innocent pterodactyl hatchlings now have a chance at a real life.', `FemaleText_loc4`='现在，那些无辜的翼手龙雏龙终于有机会过上真正的生活了。', `FemaleText_loc5`='那些無辜的小翼手龍總算有機會過正常的生活了。', `FemaleText_loc7`='Esas inocentes proles de pterodáctilos tendrán ahora alguna posibilidad de conocer lo que es la vida real.' WHERE `ID`=71315;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Hopefully taking these offerings will slow their sacrificial rituals down.', `FemaleText_loc4`='但愿夺走这些祭品能推迟他们的献祭仪式。', `FemaleText_loc5`='希望拿走這些祭品可以拖延他們的獻祭儀式。', `FemaleText_loc7`='Esperemos que al coger estas ofrendas retrasemos sus rituales de sacrificio.' WHERE `ID`=71316;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='These Zandalari are proving to be a greater threat than I expected.', `FemaleText_loc4`='这些赞达拉巨魔的威胁比我预料地更大。', `FemaleText_loc5`='這些贊達拉食人妖的威脅遠大於我的估算。', `FemaleText_loc7`='Parece que estos Zandalari son una amenaza mayor de lo que había previsto.' WHERE `ID`=71317;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='I can''t believe the Zandalari actually make living sacrifices!', `FemaleText_loc4`='难以置信，赞达拉居然真的在搞活体献祭！', `FemaleText_loc5`='真不敢相信，贊達拉食人妖竟然在獻祭活人!', `FemaleText_loc7`='¡No me puedo creer que los Zandalari hagan sacrificios de criaturas vivas!' WHERE `ID`=71318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='When did you arrive on this island?', `MaleText_loc4`='你是什么时候抵达这座岛的？', `MaleText_loc5`='你是什麼時候來到這座島的?', `MaleText_loc7`='¿Cuándo llegaste a esta isla?', `FemaleText_loc1`='When did you arrive on this island?', `FemaleText_loc4`='你是什么时候抵达这座岛的？', `FemaleText_loc5`='你是什麼時候來到這座島的?', `FemaleText_loc7`='¿Cuándo llegaste a esta isla?' WHERE `ID`=71319;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='Not long ago, but I''ve already seen terrible suffering in this place!', `FemaleText_loc4`='不久前，我就在这个地方亲眼见证了一场恐怖的灾难！', `FemaleText_loc5`='不久前才到的，但是我已經見識過這裡的恐怖了!', `FemaleText_loc7`='No hace mucho, ¡pero ya he presenciado sufrimientos terribles en este lugar!' WHERE `ID`=71320;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거대한 요동치는 운룡이 레이 션의 근거지로 들어가는 길을 막고 있습니다.', `FemaleText_loc4`='一头巨型雷霆云端翔龙挡在了雷神领域的入口。', `FemaleText_loc5`='一頭巨大的雷霆雲蛟擋住了通往雷神宮殿的入口。', `FemaleText_loc7`='Un enorme dragón nimbo tronador nos impide el paso a los dominios de Lei Shen.' WHERE `ID`=71339;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에는 이제 요동치는 운룡이 많이 남아 있지 않답니다.', `FemaleText_loc4`='这个世界上的雷霆云端翔龙已经很稀少了。', `FemaleText_loc5`='我們這兒的雷霆雲蛟已經剩沒幾隻。', `FemaleText_loc7`='Quedan pocos dragones nimbo tronadores en nuestro mundo.' WHERE `ID`=71340;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저희는 혹시 성채로 들어가는 다른 길이 있을까 해서 하수도를 조사하고 있습니다.', `FemaleText_loc4`='我们正在调查下水道系统——或许还有其他进入城堡的方法。', `FemaleText_loc5`='我們正在調查下水道，說不定會有地方可以潛入。', `FemaleText_loc7`='Estamos investigando el sistema de cloacas: tal vez haya otro modo de entrar a la ciudadela.' WHERE `ID`=71341;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 말인가요? 저는 비취 번개 기술을 씁니다. 제 주먹은 너무 빨라서, 아마 보이지도 않을걸요!', `FemaleText_loc4`='我？我掌握着碎玉闪电的技巧。我的出拳速度非常快，你甚至都看不清我的拳影！', `FemaleText_loc5`='我?我練的功夫叫碎玉轟雷掌，我的拳掌快到你根本看不見!', `FemaleText_loc7`='¿Yo? Practico el arte del relámpago de jade. ¡Mis puños son tan rápidos que ni siquiera los verás!' WHERE `ID`=71342;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $p 님! 제가 찾던 $c|1이;가; 바로 당신이군요.$B$B얼라이언스가 어떻게 판다리아에 왔는지 기억하시나요? 그때 같이 오셨죠, 그렇죠? 하지만 당신이 판다리아에 도착했을 때의 시간의 길은... 완전히 끝나지 않았습니다. 당신은 그때 일어난 사건들을 모두 경험하지는 못했어요.$B$B아마도 전쟁의 혼돈을 피해 이 땅의 평화로운 골짜기로 발길을 돌리셨었나 봐요. 아니면 하얀 싹을 찾으라는 왕의 부름보다, 던전에 숨겨진 이국적인 고대 보물의 부름에 더 끌리셨거나요.$B$B어쨌든, 전 잘잘못을 따지려고 여기 있는 게 아니랍니다. 그저 당신에게 두 번째 기회를 드리려고 온 거죠.$B$B원하신다면 그때로 데려가 드리겠어요. 사자의 상륙지라는 곳이 아직 존재하지 않았고, 하늘불꽃호가 비취 숲 위를 떠다니던 시절이요.', `FemaleText_loc4`='啊，$p！你就是我要找的$c。$B$B你还记得联盟是怎么来到潘达利亚的吗？没错，你和他们一起过来的，对吧？但是，你在潘达利亚时间线中的存在……是不完整的。你只见证了当天发生的部分历史。$B$B也许你那天从纷乱的战火中逃了出去，选择前往和平宁静的四风谷。抑或对你而言，地下城中的珍奇异宝要比国王寻找白卒的命令更有吸引力。$B$B无论如何，我今天来不是要评判你的选择。我只想给你提供第二次机会。$B$B只要你开口，我就能让你回到那一天。此时雄狮港尚未建成，而天火号则游弋在翡翠林的天空中。', `FemaleText_loc5`='啊，$p!你正好就是我要找的那位$c。$B$B你還記得聯盟是怎麼來到潘達利亞的嗎?你當時也在場，對吧?但是你在那段時間線的旅行還...尚未結束。你只有經歷那段時間線的部分事件而已。$B$B或許你是因為想要在這片大陸和平寧靜的峽谷漫步而逃離了混亂的戰場;或是說不定許多放置在地城的稀有古老寶藏對你來說，比執行大君主的命令去拯救白棋還更有吸引力。$B$B不管如何，我不是來這裡評斷你的抉擇，我只是來提供你第二次機會。$B$B只要你開口，我就會帶你回到雄獅灘還沒建造完成、天火號還在緩緩駛過翠玉林天空的那一天。', `FemaleText_loc7`='¡Pero si es $p! Justo $gel:la; $c que andaba buscando.$b$bSeguro que recuerdas la llegada de la Alianza a Pandaria... Pero tu presencia en esa sección de la historia de Pandaria está... incompleta. Solo viste parte de los acontecimientos de aquel día.$b$bEs posible que te alejaras del caos de la guerra para recorrer los pacíficos valles de este continente. O quizás los tesoros de mazmorras antiguas y exóticas te atrajeron más que la orden de tu rey de buscar al peón blanco.$b$bSolo quiero ofrecerte una segunda oportunidad.$b$bSi lo deseas, te transportaré de vuelta a aquel día. El Desembarco del León aún no se habrá construido y El Abrasacielos estará sobrevolando el Bosque de Jade.' WHERE `ID`=71343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비취 숲에 있는 하늘불꽃호를 보고 싶습니다. 과거로 데려가 주세요.', `MaleText_loc4`='我想要看看飞翔在翡翠林天空中的天火号。带我回去。', `MaleText_loc5`='我想要看到天火號還飛在翠玉林天空的那天，帶我回去那段時間線吧。', `MaleText_loc7`='Quiero ver El Abrasacielos en el Bosque de Jade. Llévame de vuelta.', `FemaleText_loc1`='비취 숲에 있는 하늘불꽃호를 보고 싶습니다. 과거로 데려가 주세요.', `FemaleText_loc4`='我想要看看飞翔在翡翠林天空中的天火号。带我回去。', `FemaleText_loc5`='我想要看到天火號還飛在翠玉林天空的那天，帶我回去那段時間線吧。', `FemaleText_loc7`='Quiero ver El Abrasacielos en el Bosque de Jade. Llévame de vuelta.' WHERE `ID`=71344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말로 위상을 바꾸시겠습니까?', `MaleText_loc4`='你确定想要改变你所处的相位吗？', `MaleText_loc5`='你確定要更改你目前所處的相位嗎?', `MaleText_loc7`='¿Seguro que quieres cambiar de fase?', `FemaleText_loc1`='정말로 위상을 바꾸시겠습니까?', `FemaleText_loc4`='你确定想要改变你所处的相位吗？', `FemaleText_loc5`='你確定要更改你目前所處的相位嗎?', `FemaleText_loc7`='¿Seguro que quieres cambiar de fase?' WHERE `ID`=71345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 크게 울어 주위의 거북들을 부릅니다.', `MaleText_loc4`='%s发出隆隆的召唤声，吸引着附近的旋龟。', `MaleText_loc5`='%s發出一聲低沈的吼叫，吸引附近的龍龜。', `MaleText_loc7`='%s lanza una llamada atronadora que atrae a las tortugas de las inmediaciones.' WHERE `ID`=71346;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, $p 님! 제가 찾던 $c|1이;가;이 바로 당신이군요.$B$B얼라이언스가 어떻게 판다리아에 왔는지 기억하시나요? 그때 같이 오셨죠, 그렇죠? 하지만 당신이 판다리아에 도착했을 때의 시간의 길은... 완전히 끝나지 않았습니다. 당신은 그때 일어난 사건들을 모두 경험하지는 못했어요.$B$B아마도 전쟁의 혼돈을 피해 이 땅의 평화로운 골짜기로 발길을 돌리셨었나 봐요. 아니면 하얀 싹을 찾으라는 왕의 부름보다, 던전에 숨겨진 이국적인 고대 보물의 부름에 더 끌리셨거나요.$B$B어쨌든, 전 잘잘못을 따지려고 여기 있는 게 아니랍니다. 그저 당신에게 두 번째 기회를 드리려고 온 거죠.$B$B원하신다면 그때로 데려가 드리겠어요. 사자의 상륙지라는 곳이 아직 존재하지 않았고, 하늘불꽃호가 비취 숲 위를 떠다니던 시절이요.', `FemaleText_loc4`='啊，$p！你就是我要找的$c。$B$B你还记得联盟是怎么来到潘达利亚的吗？没错，你和他们一起过来的，对吧？但是，你在潘达利亚时间线中的存在……是不完整的。你只见证了当天发生的部分历史。$B$B也许你那天从纷乱的战火中逃了出去，选择前往和平宁静的四风谷。抑或对你而言，地下城中的珍奇异宝要比国王寻找白卒的命令更有吸引力。$B$B无论如何，我今天来不是要评判你的选择。我只想给你提供第二次机会。$B$B只要你开口，我就能让你回到那一天。此时雄狮港尚未建成，而天火号则游弋在翡翠林的天空中。', `FemaleText_loc5`='啊，$p!你正好就是我要找的那位$c。$B$B你還記得聯盟是怎麼來到潘達利亞的嗎?你當時也在場，對吧?但是你在那段時間線的旅行還...尚未結束。你只有經歷那段時間線的部分事件而已。$B$B或許你是因為想要在這片大陸和平寧靜的峽谷漫步而逃離了混亂的戰場;或是說不定許多放置在地城的稀有古老寶藏對你來說，比執行大君主的命令去拯救白棋還更有吸引力。$B$B不管如何，我不是來這裡評斷你的抉擇，我只是來提供你第二次機會。$B$B只要你開口，我就會帶你回到雄獅灘還沒建造完成、天火號還在緩緩駛過翠玉林天空的那一天。', `FemaleText_loc7`='¡Pero si es $p! Justo $gel:la; $c que andaba buscando.$b$bSeguro que recuerdas la llegada de la Alianza a Pandaria... Pero tu presencia en esa sección de la historia de Pandaria está... incompleta. Solo viste parte de los acontecimientos de aquel día.$b$bEs posible que te alejaras del caos de la guerra para recorrer los pacíficos valles de este continente. O quizás los tesoros de mazmorras antiguas y exóticas te atrajeron más que la orden de tu rey de buscar al peón blanco.$b$bSolo quiero ofrecerte una segunda oportunidad.$b$bSi lo deseas, te transportaré de vuelta a aquel día. El Desembarco del León aún no se habrá construido y El Abrasacielos estará sobrevolando el Bosque de Jade.' WHERE `ID`=71347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤트라스 북동쪽, 실미르 호숫가에 있는 노인 발로를 찾아가십시오.', `MaleText_loc4`='去沙塔斯城东北边的希尔米耶湖畔找老渔夫巴尔洛吧。', `MaleText_loc5`='到撒塔斯城東北方的泥濘湖去找老人巴洛。', `MaleText_loc7`='Busca al Viejo Barlo cerca del Lago Silmyr, al noreste de la Ciudad de Shattrath.', `FemaleText_loc1`='샤트라스 북동쪽, 실미르 호숫가에 있는 노인 발로를 찾아가십시오.', `FemaleText_loc4`='去沙塔斯城东北边的希尔米耶湖畔找老渔夫巴尔洛吧。', `FemaleText_loc5`='到撒塔斯城東北方的泥濘湖去找老人巴洛。', `FemaleText_loc7`='Busca al Viejo Barlo cerca del Lago Silmyr, al noreste de la Ciudad de Shattrath.' WHERE `ID`=71348;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='또 만나는군요, $p 님! 두 번째 기회는 잘 즐기고 계신가요?$B$B하늘불꽃호가 떠나는 시점까지 여기서 모험을 계속한다면, 당신은 사자의 상륙지가 완성된 현재의 시간에 저절로 합류하게 될 거예요.$B$B만약 지금 당장 그 시간대로 돌아가고 싶으면, 아니, 음... 떠난다고 해야 하나요? 하여튼, 사자의 상륙지로 지금 바로 가고 싶다면, 알려만 주세요!', `FemaleText_loc4`='又见面了，$p！是否对你的第二次机会感到满意？$B$B如果你在这裡继续冒险直到天火号离去时，你将自动汇入雄狮港已建好的正常时间线。$B$B如果你想要，你也可以选择立刻回到……呃……前去雄狮港。告诉我即可。', `FemaleText_loc5`='又見面了，$p!還享受擁有重來一次經驗的感覺嗎?$B$B如果你繼續按照歷史冒險下去直到天火號離開潘達利亞，你就會自動回到目前的時間線，雄獅灘也會回到原來建造好的樣子。$B$B或是，你想要現在就回去原來的時間線，呃...就是前去雄獅灘，請跟我說!', `FemaleText_loc7`='¡Hola otra vez, $p! ¿Estás disfrutando de tu segunda oportunidad?$B$BSi te quedas aquí y continúas con tu aventura hasta que El Abrasacielos parta, te incorporarás automáticamente a la línea temporal normal y volverás a ver cómo se funda el Desembarco del León.$B$BSi, por el contrario, prefieres retroceder... digo... avanzar al Desembarco del León, ¡no tienes más que decirlo!' WHERE `ID`=71349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사자의 상륙지로 돌아가고 싶습니다.', `MaleText_loc4`='我想要回到雄狮港。', `MaleText_loc5`='我想回到雄獅灘。', `MaleText_loc7`='Quiero regresar al Desembarco del León.', `FemaleText_loc1`='사자의 상륙지로 돌아가고 싶습니다.', `FemaleText_loc4`='我想要回到雄狮港。', `FemaleText_loc5`='我想回到雄獅灘。', `FemaleText_loc7`='Quiero regresar al Desembarco del León.' WHERE `ID`=71350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥으로 태어났노라!', `MaleText_loc4`='我是雷电之子！', `MaleText_loc5`='我自雷中而生!', `MaleText_loc7`='¡Yo nací del trueno!', `FemaleText_loc1`='천둥으로 태어났노라!', `FemaleText_loc4`='我是雷电之子！', `FemaleText_loc5`='我自雷中而生!', `FemaleText_loc7`='¡Yo nací del trueno!' WHERE `ID`=71355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한기어린 바람이 느껴지느냐? 곧 폭풍이 몰아칠 것이다...', `MaleText_loc4`='你感觉到劲吹的寒风了吗？风暴将至……', `MaleText_loc5`='你感覺到冷風吹過了嗎?風暴要來了...', `MaleText_loc7`='¿Sienten un viento frío? Se avecina la tormenta…', `FemaleText_loc1`='한기어린 바람이 느껴지느냐? 곧 폭풍이 몰아칠 것이다...', `FemaleText_loc4`='你感觉到劲吹的寒风了吗？风暴将至……', `FemaleText_loc5`='你感覺到冷風吹過了嗎?風暴要來了...', `FemaleText_loc7`='¿Sienten un viento frío? Se avecina la tormenta…' WHERE `ID`=71356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원한에 찬 요동치는 구름이여!', `MaleText_loc4`='复仇云层正在汇聚！', `MaleText_loc5`='霹靂雲中竄!', `MaleText_loc7`='¡Las nubes se arremolinan para la venganza!', `FemaleText_loc1`='원한에 찬 요동치는 구름이여!', `FemaleText_loc4`='复仇云层正在汇聚！', `FemaleText_loc5`='霹靂雲中竄!', `FemaleText_loc7`='¡Las nubes se arremolinan para la venganza!' WHERE `ID`=71357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노에 찬 울부짖는 바람이여!', `MaleText_loc4`='愤怒的空气正在爆鸣！', `MaleText_loc5`='怒雷風中響!', `MaleText_loc7`='¡El aire crepita por la ira!', `FemaleText_loc1`='분노에 찬 울부짖는 바람이여!', `FemaleText_loc4`='愤怒的空气正在爆鸣！', `FemaleText_loc5`='怒雷風中響!', `FemaleText_loc7`='¡El aire crepita por la ira!' WHERE `ID`=71358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘이 네 죽음을 애도하는구나!', `MaleText_loc4`='天空将为你的败亡而哭泣！', `MaleText_loc5`='爾喪蒼天泣!', `MaleText_loc7`='¡El cielo llora por tu muerte!', `FemaleText_loc1`='하늘이 네 죽음을 애도하는구나!', `FemaleText_loc4`='天空将为你的败亡而哭泣！', `FemaleText_loc5`='爾喪蒼天泣!', `FemaleText_loc7`='¡El cielo llora por tu muerte!' WHERE `ID`=71359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그저... 암흑 속... 폭풍의 전조일 뿐...', `MaleText_loc4`='我不过是……风暴之前的……黑暗……', `MaleText_loc5`='我只是...風暴前的...黑暗...', `MaleText_loc7`='Solo soy... la oscuridad... antes de la tormenta...', `FemaleText_loc1`='나는 그저... 암흑 속... 폭풍의 전조일 뿐...', `FemaleText_loc4`='我不过是……风暴之前的……黑暗……', `FemaleText_loc5`='我只是...風暴前的...黑暗...', `FemaleText_loc7`='Solo soy... la oscuridad... antes de la tormenta...' WHERE `ID`=71360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너희에게 선물을 주지!', `MaleText_loc4`='与我分享这份恩赐吧！', `MaleText_loc5`='讓我跟你分享這個禮物吧!', `MaleText_loc7`='¡Tengo un regalo para ustedes!' WHERE `ID`=71361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 또 배에 올라온다. 막아라!', `MaleText_loc4`='又有人上来了。拖住他们！', `MaleText_loc5`='更多敵人登上來了，阻止他們!', `MaleText_loc7`='Llegan más a bordo. ¡Hay que detenerlos!' WHERE `ID`=71362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 바다에서 승선 부대를 보내고 있다. 한 명이 포를 맡아서 놈들을 침몰시켜라!', `MaleText_loc4`='他们从海上派出了夺船小队。派你的人到船尾去开炮，击沉他们！', `MaleText_loc5`='他們是從海上送人上來的，派個人去操作艦尾的砲台，打掉他們!', `MaleText_loc7`='Están enviando partidas de abordaje desde el mar. ¡Que uno de ustedes vaya al cañón de popa y acabe con ellas!' WHERE `ID`=71363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기괴한 고서', `MaleText_loc4`='拉风魔典', `MaleText_loc5`='狂風魔典', `MaleText_loc7`='Grimorio de Ráfaga', `FemaleText_loc1`='기괴한 고서', `FemaleText_loc4`='拉风魔典', `FemaleText_loc5`='狂風魔典', `FemaleText_loc7`='Grimorio de Ráfaga' WHERE `ID`=71364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠의 문 귀환석', `MaleText_loc4`='黑暗之门炉石', `MaleText_loc5`='黑暗之門心石', `MaleText_loc7`='Piedra corazón de El Portal Oscuro', `FemaleText_loc1`='어둠의 문 귀환석', `FemaleText_loc4`='黑暗之门炉石', `FemaleText_loc5`='黑暗之門心石', `FemaleText_loc7`='Piedra corazón de El Portal Oscuro' WHERE `ID`=71365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='섬뜩한 군마', `MaleText_loc4`='幽灵军马', `MaleText_loc5`='恐怖戰騎', `MaleText_loc7`='Destrero espantoso', `FemaleText_loc1`='섬뜩한 군마', `FemaleText_loc4`='幽灵军马', `FemaleText_loc5`='恐怖戰騎', `FemaleText_loc7`='Destrero espantoso' WHERE `ID`=71366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자의 배신', `MaleText_loc4`='守护者的背叛', `MaleText_loc5`='守護者的背叛', `MaleText_loc7`='La traición del guardián', `FemaleText_loc1`='수호자의 배신', `FemaleText_loc4`='守护者的背叛', `FemaleText_loc5`='守護者的背叛', `FemaleText_loc7`='La traición del guardián' WHERE `ID`=71367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단은 막아 냈군. 이제 대포를 타고 다른 함선을 도와라!', `MaleText_loc4`='我们暂时拖住了他们。快去左舷操作火炮，帮助其他船只！', `MaleText_loc5`='暫且擋住他們的攻勢了，趕緊跳進左舷那邊的大砲，去幫助我方其他船隻!', `MaleText_loc7`='Los hemos retenido por el momento. ¡Con el cañón de babor se puede ir a nuestras otras naves! ¡Necesitan toda la ayuda posible!' WHERE `ID`=71368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 적함까지 밀어붙였군. 뱃머리를 돌리고 놈들의 폭탄을 써서 적함을 산산조각 내라!', `MaleText_loc4`='我们已经把他们赶回了自己的船上。在上空盘旋一圈，用他们自己的炸药炸飞他们！', `MaleText_loc5`='成功把敵人趕回他們的船上了。調轉方向，利用他們的炸藥來轟碎他們!', `MaleText_loc7`='Hemos conseguido que regresen a su nave. ¡Podemos usar algunos de sus explosivos para volarlos por los aires!' WHERE `ID`=71369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_dust.blp:20|t두루무가 |cFFFF0000|Hspell:134169|h[분해]|h|r를 시전하려고 자기 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_dust.blp:20|t杜鲁姆开始为自己的眼球充能，以施放|cFFFF0000|Hspell:134169|h[衰变光束]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_dust.blp:20|t獨顱目的眼睛開始充能，準備發射|cFFFF0000|Hspell:134169|h[毀滅光束]|h|r!', `MaleText_loc7`='|TInterface/Iconsinv_misc_dust.blp:20|t¡Durumu comienza a cargar su ojo para lanzar |cFFFF0000|Hspell:134169|h[Desintegración]|h|r!' WHERE `ID`=71371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=71372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='축전기가 10초 후에 방전됩니다! 천공기로 가십시오!', `MaleText_loc4`='你的电容器将在10秒后进行电能释放！快靠近闪电钻！', `MaleText_loc5`='你的電容10秒後就要放電了!趕緊去找鑽頭!', `MaleText_loc7`='¡Tu condensador se descargará en 10 segundos! Ve a una plataforma.', `FemaleText_loc1`='축전기가 10초 후에 방전됩니다! 천공기로 가십시오!', `FemaleText_loc4`='你的电容器将在10秒后进行电能释放！快靠近闪电钻！', `FemaleText_loc5`='你的電容10秒後就要放電了!趕緊去找鑽頭!', `FemaleText_loc7`='¡Tu condensador se descargará en 10 segundos! Ve a una plataforma.' WHERE `ID`=71373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에서는 큰 위험을 각오해야 할 거요. 그대의 충성과 신뢰에 감사하오, $n.', `MaleText_loc4`='在这座岛上，我不得不让你面对更大的危险。你的忠诚和信任令人赞赏，$n。', `MaleText_loc5`='我得要求你面對這座島上的眾多凶險。$n，感謝你的忠誠與信任。', `MaleText_loc7`='En esta isla necesito que te enfrentes a grandes peligros. Tu lealtad y tu confianza son muy importantes para mí, $n.' WHERE `ID`=71374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 블러드 엘프는 많은 폭풍을 이겨내 왔소. 천둥왕이 우리에게 무슨 짓을 하든, 우리는 그에게 더욱 큰 타격을 입힐 거요!', `MaleText_loc4`='我们血精灵历经风雨。无论雷电之王有什么花招，我们必将百倍奉还！', `MaleText_loc5`='我們血精靈已度過了無數的狂風暴雨，不管雷王使出什麼招式，我們都會加倍奉還給他!', `MaleText_loc7`='Nosotros, los elfos de sangre, hemos sobrevivido a muchas tormentas. ¡No importa lo potente que sea el ataque que el Rey del Trueno lance contra nosotros; nuestra respuesta lo será aún más!' WHERE `ID`=71375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 목표를 위해서는 모구을 절멸시켜야 하지만, 측방 경계를 게을리해서는 안 됩니다.$b$b지금은 얼라이언스와 사우록이 우리와 함께 모구를 공격하지만, 둘 다 언제든지 우리에게 칼을 돌릴 수 있습니다.', `MaleText_loc4`='虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然联盟和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。', `MaleText_loc5`='我們的主要目標是消滅魔古，但我們也不能忽視我們的側翼。$b$b雖然聯盟和薩烏洛克與我們一同攻擊魔古，但雙方隨時都有可能回頭襲擊我們。', `MaleText_loc7`='Nuestro objetivo es erradicar a los mogu, pero no podemos ignorar nuestros flancos.$b$bAunque tanto la Alianza como los saurok atacan a los mogu a nuestro lado, se podrían volver contra nosotros en cualquier momento.' WHERE `ID`=71376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 힘을 빼앗을 방법을 찾아야만 하오. 그럴 수만 있다면 의지만으로 쉽게 적을 압도할 수 있을 거요.', `MaleText_loc4`='我们必须设法剥夺敌人的力量，没有了力量，我们就能随心所欲地轻松战胜他们了。', `MaleText_loc5`='我們必須想辦法奪去敵人的力量。削弱他們之後，我們就能隨心所欲擊倒他們。', `MaleText_loc7`='Tenemos que encontrar la manera de arrebatar su poder a nuestros enemigos. Sin su fortaleza, podremos someterlos fácilmente con nuestra fuerza de voluntad.' WHERE `ID`=71377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물 훔치기', `MaleText_loc4`='窃取神器', `MaleText_loc5`='竊取文物', `MaleText_loc7`='Robando artefacto', `FemaleText_loc1`='유물 훔치기', `FemaleText_loc4`='窃取神器', `FemaleText_loc5`='竊取文物', `FemaleText_loc7`='Robando artefacto' WHERE `ID`=71378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훔치는 중', `MaleText_loc4`='正在移除', `MaleText_loc5`='移除', `MaleText_loc7`='Eliminando', `FemaleText_loc1`='훔치는 중', `FemaleText_loc4`='正在移除', `FemaleText_loc5`='移除', `FemaleText_loc7`='Eliminando' WHERE `ID`=71379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 녀석 화나게 하지 마!', `MaleText_loc4`='别惹恼了大块头，伙计！', `MaleText_loc5`='老兄，不要惹大塊頭生氣!', `MaleText_loc7`='¡No enfades al mandamás, colega!' WHERE `ID`=71380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 큰 녀석한테 먹인다!', `MaleText_loc4`='我们要拿你去喂大块头！', `MaleText_loc5`='把你餵給大塊頭!', `MaleText_loc7`='¡Serás comida pa'' el mandamás!' WHERE `ID`=71381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 도망쳐 봐야 늦었다!', `MaleText_loc4`='现在逃跑可来不及了，伙计！', `MaleText_loc5`='現在要跑已經來不及了，老兄!', `MaleText_loc7`='¡Ya es tarde pa'' que salgas corriendo, colega!' WHERE `ID`=71382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='큰 녀석한테는 한 입 거리도 안 되겠군.', `MaleText_loc4`='你都不够大块头塞牙缝的。', `MaleText_loc5`='你勉強可以拿來餵大塊頭。', `MaleText_loc7`='Solo servirás pa'' alimentar al mandamás... y se quedará con hambre.' WHERE `ID`=71383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 오면 안 되는 곳에 왔어.', `MaleText_loc4`='你来错地方了。', `MaleText_loc5`='你來錯地方了。', `MaleText_loc7`='Has venido al lugar equivocado, colega.' WHERE `ID`=71384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 내 애완동물이 배고파하는 참이었는데.', `MaleText_loc4`='来得好！我的宠物正好饿了，伙计。', `MaleText_loc5`='好!我的寵物肚子餓了。', `MaleText_loc7`='¡Bien! Mi mah''cota empieza a tener hambre, colega.' WHERE `ID`=71385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 먹을 것이 왔구나.', `MaleText_loc4`='啊，食物自己送上门了。', `MaleText_loc5`='啊，食物來了。', `MaleText_loc7`='Ah, ya llega la comida.' WHERE `ID`=71386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제대로 찾아왔구나... 먹이가 될 곳에 말이지!', `MaleText_loc4`='你来对地方了……准备被吃掉吧！', `MaleText_loc5`='你來對地方了...來這裡乖乖當飼料就對了!', `MaleText_loc7`='Has venido al lugar adecuado... ¡pa'' que te coman!' WHERE `ID`=71387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 앞에 고개 숙여라!', `MaleText_loc4`='臣服于赞达拉吧！', `MaleText_loc5`='向贊達拉臣服!', `MaleText_loc7`='¡Inclínate ante los Zandalari!' WHERE `ID`=71388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='식사 시간이다!', `MaleText_loc4`='喂食时间到啦！', `MaleText_loc5`='餵東西的時候到了!', `MaleText_loc7`='¡Es hora de comer!' WHERE `ID`=71389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽으러 온 거라면 잘 찾아왔구나.', `MaleText_loc4`='要想找死的话，你就来对地方了。', `MaleText_loc5`='你來對地方了...來這裡乖乖受死吧。', `MaleText_loc7`='Has venido al sitio adecuado pa'' morir.' WHERE `ID`=71390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 야수들에게 먹일 테다.', `MaleText_loc4`='我要拿你的灵魂去喂野兽。', `MaleText_loc5`='我要把你靈魂餵給野獸。', `MaleText_loc7`='Daré tu alma de merienda a las bestias.' WHERE `ID`=71391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 넌 도구일 뿐이야.', `MaleText_loc4`='你这废物，只能给我补充能量。', `MaleText_loc5`='你只是我的養分。', `MaleText_loc7`='No serás más que combuh''tible pa'' mí.' WHERE `ID`=71392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로아가 널 먹어 치울 거다.', `MaleText_loc4`='神灵会将你吞噬殆尽。', `MaleText_loc5`='羅亞會把你吃掉。', `MaleText_loc7`='Los loa se te van a zampar.' WHERE `ID`=71393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라, 침입자!', `MaleText_loc4`='去死吧，入侵者。', `MaleText_loc5`='死吧，闖入者。', `MaleText_loc7`='Muere, intruso.' WHERE `ID`=71394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 마법의 맛을 봐라!', `MaleText_loc4`='尝尝赞达拉的魔法吧！', `MaleText_loc5`='嚐嚐贊達拉魔法的厲害!', `MaleText_loc7`='¡Prueba un poco de la magia Zandalari!' WHERE `ID`=71395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼은 약하다.', `MaleText_loc4`='你的灵魂太弱小了。', `MaleText_loc5`='你的靈魂太弱了。', `MaleText_loc7`='Tu alma es débil.' WHERE `ID`=71396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 와라. 조금 째기만 할 테니. 약속하지!', `MaleText_loc4`='靠近点。我只轻轻割一刀，我保证！', `MaleText_loc5`='靠近一點。只割小小一下，我保證!', `MaleText_loc7`='Acércate. ¡Solo será un cortecito, te lo prometo!' WHERE `ID`=71397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절개를 하고 나면 피가 빠르게 흐를 것이다.', `MaleText_loc4`='一旦割开创口，鲜血就会迅速外流。', `MaleText_loc5`='刀子一劃開，血水自然流。', `MaleText_loc7`='Una vez realizada la incisión, la sangre fluye rápidamente.' WHERE `ID`=71398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발버둥칠수록 더 아플 거다!', `MaleText_loc4`='你越挣扎就越痛！', `MaleText_loc5`='越掙扎就越痛!', `MaleText_loc7`='¡Cuánto más te resistas, más te va a doler!' WHERE `ID`=71399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빨리 죽이진 않겠다. 그건 약속하지!', `MaleText_loc4`='你不会马上死掉的。我保证！', `MaleText_loc5`='我向你保證，你一定不會死得太痛快!', `MaleText_loc7`='No morirás rápidamente. ¡Eso te lo garantizo!' WHERE `ID`=71400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 새로운 실험 대상인가? 분해해 주마... 조각조각!', `MaleText_loc4`='啊，一个新标本？我要把你撕成……碎片！', `MaleText_loc5`='啊，新的樣本?我會把你...一塊一塊支解剖開!', `MaleText_loc7`='Ah, ¿un nuevo sujeto? Te haré pedazos... poquito a poco.' WHERE `ID`=71401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 가까이 와라. 내 칼이 네 피에 굶주렸구나!', `MaleText_loc4`='对，靠近点，小家伙。我的手术刀在渴望你的鲜血！', `MaleText_loc5`='對，靠近一點，小傢伙。我的解剖刀等不及要品嚐你的鮮血!', `MaleText_loc7`='Sí, acércate, $gpequeño:pequeña;. Mi escalpelo tiene sed de sangre.' WHERE `ID`=71402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호리돈이 시선을 $n에게 고정하고 꼬리를 바닥에 쿵쿵 내려칩니다!', `MaleText_loc4`='赫利东注视着$n并开始拍打他的尾巴！', `MaleText_loc5`='哈里登雙眼盯著$n，用力拍動尾巴!', `MaleText_loc7`='¡Horridonte fija la vista en $n y golpea con su cola!', `FemaleText_loc1`='호리돈이 시선을 $n에게 고정하고 꼬리를 바닥에 쿵쿵 내려칩니다!', `FemaleText_loc4`='赫利东注视着$n并开始拍打他的尾巴！', `FemaleText_loc5`='哈里登雙眼盯著$n，用力拍動尾巴!', `FemaleText_loc7`='¡Horridonte fija la vista en $n y golpea con su cola!' WHERE `ID`=71403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 야수의 소굴이군요. 잔달라는 야수를 부리는 솜씨도 놀랍지만, 이 역겨운 냄새를 참는 능력이 더 놀랍군요.$b$b바람이 데빌사우루스 쪽에서 불어오는 한, 절대 기습당할 일은 없을 겁니다.', `MaleText_loc4`='啊，兽栏。虽然我很欣赏赞达拉的驯兽技巧，但我更佩服他们忍受恶臭的本事。$b$b只要让魔暴龙处在你的逆风方向，它就休想偷袭到你。', `MaleText_loc5`='啊，野獸的巢穴。我很佩服贊達拉食人妖馴獸的本事，但是我更佩服他們忍受這種臭味的能耐。$b$b你只要待在魔暴龍的下風處就不會被意外偷襲了。', `MaleText_loc7`='Ah, la guarida de las bestias. A pesar de que admiro mucho la habilidad de los Zandalari para dominar bestias, admiro aún más su capacidad para soportar este terrible olor.$b$bProcura que el demosaurio esté delante cuando tengas el viento a favor y así nunca te cogerá desprevenido.' WHERE `ID`=71404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t 전쟁신 잘라크가 쓰러지는 모습을 본 호리돈이 |cFFFF0000|Hspell:136821|h[광란]|h|r 상태가 됩니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t目睹了战神贾拉克的倒下后，赫利东进入了|cFFFF0000|Hspell:136821|h[狂暴]|h|r状态！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t 見到戰神加拉克倒下，哈里登陷入了|cFFFF0000|Hspell:136821|h[暴怒]|h|r狀態!', `MaleText_loc7`='|TInterface/Iconsability_warrior_focusedrage.blp:20|t Horridonte entra en |cFFFF0000|Hspell:136821|h[Desenfreno]|h|r al ver caer al dios de la guerra Jalak.', `FemaleText_loc1`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t 전쟁신 잘라크가 쓰러지는 모습을 본 호리돈이 |cFFFF0000|Hspell:136821|h[광란]|h|r 상태가 됩니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t目睹了战神贾拉克的倒下后，赫利东进入了|cFFFF0000|Hspell:136821|h[狂暴]|h|r状态！', `FemaleText_loc5`='|TInterface\\Icons\\ability_warrior_focusedrage.blp:20|t 見到戰神加拉克倒下，哈里登陷入了|cFFFF0000|Hspell:136821|h[暴怒]|h|r狀態!', `FemaleText_loc7`='|TInterface/Iconsability_warrior_focusedrage.blp:20|t Horridonte entra en |cFFFF0000|Hspell:136821|h[Desenfreno]|h|r al ver caer al dios de la guerra Jalak.' WHERE `ID`=71405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리로 돌아와!', `MaleText_loc4`='你给我回来！', `MaleText_loc5`='給我回來!', `MaleText_loc7`='¡Vuelve aquí!' WHERE `ID`=71406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아오지 못해, 멍청한 짐승 같으니!', `MaleText_loc4`='回来，笨蛋恶棍！', `MaleText_loc5`='混蛋，回來!', `MaleText_loc7`='¡Vuelve, gusano!' WHERE `ID`=71407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또?!', `MaleText_loc4`='别再来了！', `MaleText_loc5`='別又來了!', `MaleText_loc7`='¡Otro no!' WHERE `ID`=71408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍의 분노에 죽어라!', `MaleText_loc4`='死在风暴的怒火之下吧！', `MaleText_loc5`='死於風暴之怒吧!', `MaleText_loc7`='¡Muere por la furia de la tormenta!' WHERE `ID`=71409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s|1이;가; |cFFFF0000|Hspell:136850|h[번개 채찍]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s开始施放|cFFFF0000|Hspell:136850|h[闪电之鞭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s開始施展|cFFFF0000|Hspell:136850|h[閃電鞭]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_thunderking_lightningwhip.blp:20|t%s comienza a lanzar |cFFFF0000|Hspell:136850|h[Látigo de relámpagos]|h|r.' WHERE `ID`=71412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 처음부터 짧은니는 아니었어. 예전엔 강했다고.', `MaleText_loc4`='我并非天生的短牙种。我原本很强壮。', `MaleText_loc5`='我不是一直都是個短牙齒。我以前也很強壯。', `MaleText_loc7`='No siempre he sido un colmillochico. Antes era fuerte.' WHERE `ID`=71413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 아버지는 투사였고 어머니는 공룡사제였지. 난 아무것도 아냐.$b$b난 부랑칼날의 수치야. 난 오물 속에서 죽어갈 테고, 아무도 내 살점을 먹으려 하지 않겠지.', `MaleText_loc4`='我父亲是个蛮兵，我母亲是蜥蜴人祭司。而我一无是处。$b$b我是邪刃部族的耻辱。我会死在垃圾堆里，谁也不会来吃我的肉。', `MaleText_loc5`='我爸爸是個蠻卒，我媽媽是魔龍祭司，我什麼都不是。$b$b我是污刃族之恥。我會死在穢物堆裡，然後沒有人要吃我的肉。', `MaleText_loc7`='Mi padre era un tosco y mi madre era una sacerdotisa saurio. Yo no soy nada.$b$bSoy una vergüenza para los Hojaescoria. Moriré en la basura, y no comerán mi carne.' WHERE `ID`=71414;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 절대로 크로스의 힘을 알 수 없을 거야. 크로스의 사냥터에서 사냥할 일도 없겠지.$b$b난 사냥꾼이 아니라 사냥감이니까.', `MaleText_loc4`='我无法体会克洛斯的力量。我无法在他的猎场中狩猎。$b$b我当不了猎人，我只是个猎物。', `MaleText_loc5`='我永遠無法知道克羅斯的力量，永遠無法在他的獵場狩獵。$b$b我不是獵食者，只是獵物。', `MaleText_loc7`='Nunca conoceré la fortaleza de Kros. Nunca cazaré en sus campos.$b$bNo soy el depredador. Soy la presa.' WHERE `ID`=71415;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수치를 씻을 수 있는 방법이 있다고는 하더군. 딱 한 가지만 하면 짧은니 신세를 면할 수 있어.$b$b하지만 차마 할 수가 없어. 파로스의 힘을 내가 차지할 순 없다고. 그가 날 위해 그렇게까지 했는데...', `MaleText_loc4`='他们说我能洗刷自己的耻辱。我只要做一件事，然后我就能摆脱短牙种的称谓。$b$b可我做不到。我不能将法洛斯的力量据为己有。尤其是想到他为我所做的一切……', `MaleText_loc5`='他們說，我可以擺脫我的恥辱。我只要做一件事情，就不再是短牙齒了。$b$b可是我不能做，我不能把法洛斯的力量佔為己有。他幫了我很大忙...', `MaleText_loc7`='Me dicen que puedo librarme de mi vergüenza. Solo tengo que hacer una cosa para dejar de ser un colmillochico.$b$BPero no puedo hacerlo. No puedo quedarme con la fuerza de Farros... Después de lo que ha hecho por mí.' WHERE `ID`=71416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짧은니인 난, 더 강한 사우록들이 고기를 실컷 먹을 때까지 기다려야 해.', `MaleText_loc4`='作为一个短牙种，我必须等更强壮的蜥蜴人先享用完他们的肉食。', `MaleText_loc5`='我是短牙齒，我要等其他強壯的薩烏洛克先吃完肉了才能吃。', `MaleText_loc7`='Como colmillochico, tengo que esperar hasta que los saurok más fuertes se hayan repartido la carne.' WHERE `ID`=71417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='외부인 냄새가 난다. 우리 일족이 아니구나.$b$b왜 우리 마을에 숨어든 거지? 왜 우리 일족의 가죽을 걸치고 있는 거지? 알 수가 없군.', `MaleText_loc4`='我闻出了你，外来者。我知道你不是我们的人。$b$b你为什么溜进我们的村子？你为什么披着我们族人的皮？我不明白。', `MaleText_loc5`='我聞到你了，外地人。我知道你不是我們的人。$b$b為什麼你要溜進我們村子?為什麼你要穿著我們族人的皮?我不明白。', `MaleText_loc7`='Puedo olerte, $gforastero:forastera;. Sé que no eres uno de los nuestros.$b$b¿Por qué te cuelas en nuestra aldea? ¿Por qué llevas la piel de nuestro pueblo? No lo entiendo.' WHERE `ID`=71418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 우리 일족 아닌 거 안다. 남의 일족이지.$b$b내가 너 따라다닐 거다. 감시할 거다. 넌 우리 일족도 죽이지만 모구도 죽인다. 등 꼿꼿한 트롤도 죽이지.$b$b네가 누굴 죽이든 상관없다. 난 고기만 주워 먹으면 돼. 그래서 고기 아주 아주 많다.', `MaleText_loc4`='我知道你不是我们的人。你是他们的人。$b$b我跟踪了你。我监视着你。你杀了我们的人，可你也杀魔古族。你还杀直背的巨魔。$b$b我不关心你杀了什么人。我就跟在后面拣肉吃。好多好多肉。', `MaleText_loc5`='我知道你不是我們的人，你是他們的人。$b$b我跟蹤你、看著你。你殺了我們的人，但是你也有殺魔古，也有殺背挺直的食人妖。$b$b我不在乎你殺誰，我跟在你後面撿肉。好多、好多的肉。', `MaleText_loc7`='Sé que no eres uno de los nuestros. Eres uno de ellos.$b$bTe sigo. Te observo. Matas a nuestro pueblo, pero también matas a los mogu. Matas a los trols erguidos.$b$bMe da igual a quien mates. Yo recojo la carne después. Mucha, mucha carne.' WHERE `ID`=71419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너 마법 쓰는 거 봤다. 너 사우록 아닌 거 안다. 넌 남이다.$b$b너 마법 때문에 약하다. 용감하지도 않고. 적의 가죽을 쓰고 숨어 있는 겁쟁이지. 넌 강하지 않아!$b$b<당신의 발치에 침을 뱉는 고크카르>', `MaleText_loc4`='我看到了你的魔法。我知道你不是蜥蜴人。你是其他人。$b$b魔法让你变得软弱。你不勇敢。你是披着敌人外皮的懦夫。你一点也不强！$b$b<高卡尔向你脚下吐了一口唾沫。>', `MaleText_loc5`='我看過你的魔法，我知道你不是薩烏洛克，你是別的人。$b$b你的魔法讓你變弱，你不勇敢，你是躲在敵人的皮裡頭的膽小鬼。你不強壯!$b$b<哥卡爾在你腳邊吐口水。>', `MaleText_loc7`='He visto tu magia. Sé que no eres un saurok. Eres otra cosa.$b$bTu magia te hace débil. No eres valiente. Eres $gun:una; cobarde que se esconde tras la piel del enemigo. ¡NO ERES FUERTE!$b$b<Gokkar escupe a tus pies.>' WHERE `ID`=71420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 네 비밀을 안다. 네가 적인 것도 안다. 가짜 가죽을 쓰고 있어도 냄새로 알 수 있지.$b$b난 네가 무섭지 않아. 두려움은 나약한 놈들한테나 어울리지. 난 나약하지 않아.', `MaleText_loc4`='我知道你的秘密，外来者。我知道你是敌人。我嗅出了你的伪装。$b$b我不怕你。弱者才害怕。我不是弱者。', `MaleText_loc5`='我知道你的秘密，外地人。我知道你是敵人，我可以從你假的皮底下聞出來。$b$b但是我不害怕你。弱者才會害怕，我不是弱者。', `MaleText_loc7`='Conozco tu secreto, $gforastero:forastera;. Sé que eres el enemigo. Puedo oler a través de tu piel falsa.$b$bNo te tengo miedo. El miedo es para los cobardes. Yo no soy cobarde.' WHERE `ID`=71421;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 아무리 변장을 잘해도 난 냄새로 알 수 있다. 이렇게 신성한 의식에 오다니 간이 크구나.$b$b여기서 뭘 하려는 거지? 크로쉬크의 살점을 먹을 건가?', `MaleText_loc4`='我嗅出了你的伪装，陌生人。你竟敢闯入如此神圣的仪式。$b$b你想干什么？你想吃考什克的肉吗？', `MaleText_loc5`='我聞出了你假冒的外皮，陌生人。你很大膽，敢跑來這麼神聖的儀式。$b$b你來這裡幹嘛?是要吃克羅西克的肉嗎?', `MaleText_loc7`='Huelo más allá de tu disfraz, $gforastero:forastera;. Tienes agallas para venir a un ritual tan sagrado.$b$b¿Qué pretendes? ¿Comerás la carne de Kroshik?' WHERE `ID`=71422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 크로스의 살에서 태어났다네. 그분의 고기와 뼈로부터 빚어졌지. 그분이 우리의 창조주시라네.$b$b크로쉬크는 크로스의 핏줄로서, 우리를 보살피고 크로스와 우리를 연결해 주지. 그는 크로스의 힘을 지녔지만, 우리 세상을 걷는다네.$b$b때가 오면 크로쉬크는 죽을 것이고, 우리가 그의 힘을 취할 걸세. 그러면 순환이 다시금 시작되겠지.', `MaleText_loc4`='我们从克洛斯的血肉中诞生。我们由他的骨肉塑造而成。他是我们的造物主。$b$b考什克是克洛斯的血脉。他关注着我们。他是我们与克洛斯之间的纽带。他拥有克洛斯的力量，却行于我们的世界。$b$b当时机来临，考什克将会死去，而我们将获得他的力量。然后，轮回将重新开始。', `MaleText_loc5`='我們是從克羅斯的血肉誕生的。他是我們的創造者，我們是由他的肌肉、他的骨骼塑造的。$b$b克羅西克就是克羅斯的血脈。他看顧我們，他是我們跟克羅斯的連結。他擁有克羅斯的力量，但是卻行走在我們的世界。$b$b等時候一到，克羅西克會死去，而我們將接掌他的力量。然後，重新開始新的輪迴。', `MaleText_loc7`='Hemos nacido de la piel de Kros. Estamos creados a partir de su carne y de sus huesos. Él es nuestro creador.$b$bKroshik es la sangre de Kros. Él nos guarda. Es nuestra conexión con Kros. Tiene la fuerza de Kros, pero vive en nuestro mundo.$b$bCuando llegue el momento, Kroshik morirá, y nosotros recibiremos su fortaleza. Entonces el ciclo volverá a comenzar.' WHERE `ID`=71423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크의 육신은 살과 뼈로 이루어져 있지만, 크로스의 영혼과 함께한다네.$b$b크로쉬크의 사냥은 언젠가 끝나겠지만, 크로스의 사냥은 영원히 계속되지.', `MaleText_loc4`='考什克是血肉之躯，可他拥有克洛斯的灵魂。$b$b总有一天，考什克的狩猎将会终结。但克洛斯的狩猎将永无止尽。', `MaleText_loc5`='雖然克羅西克的身軀是骨頭和血肉，但是他體內擁有克羅斯的魂靈。$b$b有一天，克羅西克的狩獵會結束，但是克羅斯的狩獵永遠不會結束。', `MaleText_loc7`='Kroshik tiene un cuerpo de carne y hueso, pero alberga el espíritu de Kros en su interior.$b$bUn día, la caza de Kroshik terminará. Pero la caza de Kros no tiene fin.' WHERE `ID`=71424;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 우리 일족에게 거짓말을 한다네. 우리가 자기들의 피조물이고, 자기들이 우리의 살을 지금의 모습으로 빚었다고 말일세. 우리가 존재하는 것이 자기들 덕분이라고 하지.$b$b나는 모구를 거부한다네! 모구에겐 우리를 좌지우지할 권리가 없어! 우리가 무엇을 보고, 어떻게 살고, 무엇을 느끼는지 모구는 모른다네! 모구는 우리 영혼을 들여다보지 못해!$b$b오직 위대하신 창조주, 크로스께서만 영혼을 꿰뚫어 보실 수 있다네. 크로스 님께서는 아시고, 이해하신다네. 크로스께서 자네에게 힘을 주신다네, 사우록. 자네는 모구의 소유물이 아니야.', `MaleText_loc4`='魔古族对我们撒了谎。他们说我们是他们的造物，他们将我们的血肉扭曲成了现在的形态。他们声称我们的存在全靠了他们。$b$b我蔑视魔古族的说法！他们无权统治我们！他们不理解我们的想法，不懂我们的生活方式和我们的感受！他们看不透我们的灵魂！$b$b只有伟大的造物主克洛斯，才能看透你的灵魂。克洛斯无所不知，通晓万物。克洛斯赐予你们力量，蜥蜴人。你们不属于魔古族。', `MaleText_loc5`='魔古說謊欺騙我們，說是他們創造了我們、說是他們把我們的形體塑造成這樣。說我們之所以存在，都是因為他們。$b$b我才不相信他們魔古!他們沒有權力支配我們!他們不明白我們看見的東西、不明白我們的生活，不明白我們的感受!他們沒看見我們的靈魂!$b$b只有克羅斯，偉大的創造者，知道你的靈魂裡有什麼。克羅斯都知道，克羅斯明白。薩烏洛克，是克羅斯給了你們力量。你們不是魔古的玩物。', `MaleText_loc7`='Los mogu mienten a nuestro pueblo. Nos dicen que somos su creación, que ellos dieron forma a nuestra carne. Aseguran que les debemos nuestra existencia.$b$b¡Yo DESAFÍO a los mogu! ¡No tienen ningún poder sobre nosotros! ¡Ellos no saben lo que vemos, cómo vivimos, lo que sentimos! ¡No comprenden el interior de nuestras almas!$b$bSolo Kros, el gran creador, conoce tu alma. Kros conoce y Kros comprende. Kros te otorgó tu fuerza, saurok. Ningún mogu es tu dueño.' WHERE `ID`=71425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 창조주이신 크로스께서는 약한 자를 구원하지 않으신다네. 약한 자의 영혼은, 크로스와 그 추종자들의 이빨과 발톱으로부터 도망다니며 영원한 두려움 속에 살게 되지.$b$b강한 자는 크로스의 허락을 받아 사냥을 할 수 있다네. 영원히 약한 자를 쫓으며 그들의 살점을 먹고 더욱더 강해지지.$b$b강해지게나, 사우록.$b$b힘이 늘 부랑칼날과 함께하길. 힘이 늘 자네와 함께하길, 사우록.', `MaleText_loc4`='克洛斯，我们的造物主，不会拯救弱者。弱者的灵魂将活在永恒的恐惧之中，逃避着克洛斯和他追随者们的尖牙与利爪。$b$b如果你够强大，那么克洛斯将允许你狩猎。你们将永远追逐弱者，享用他们的血肉，变得更加强大。$b$b坚强起来，蜥蜴人们。$b$b力量与邪刃部族同在。力量与你们同在，蜥蜴人们。', `MaleText_loc5`='我們的創造者，克羅斯，不會拯救弱者。弱者的靈魂會困在永恆的恐懼裡，永遠被克羅斯的牙齒和爪子、還有他的跟隨者，追殺逃亡。$b$b但是只要你夠強壯，克羅斯會讓你參加狩獵。你永恆的來生就可以追逐弱者，吃他們的血肉，然後變得更加強壯。$b$b要勇敢、要堅強啊，薩烏洛克!$b$b力量與污刃族同在，力量與你同在，薩烏洛克。', `MaleText_loc7`='Kros, nuestro creador, no salvará a los débiles. Las almas de los débiles vivirán en el temor eterno; siempre huyendo de las garras y los colmillos de Kros y de sus seguidores.$b$bSi eres fuerte, Kros te permitirá cazar. Pasarás la eternidad cazando a los débiles, comiendo su carne y fortaleciéndote cada vez más.$b$bSé fuerte, saurok.$b$bLa fuerza para los Hojaescoria siempre. La fuerza para ti siempre, saurok.' WHERE `ID`=71426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크의 살점을 먹고 나약함을 씻어 버리게! 크로스의 영혼이 자네의 육신을 통과하도록 하게!', `MaleText_loc4`='享用考什克的血肉，净化你们的懦弱！让克洛斯的灵魂穿过你们的躯壳！', `MaleText_loc5`='吃下克羅西克的血肉，洗掉你的軟弱!讓克羅斯的魂靈進入你的身體!', `MaleText_loc7`='¡Come la carne de Kroshik, y libérate de la debilidad! ¡Que el espíritu de Kros atraviese tu carne!' WHERE `ID`=71427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 생각을 말해 줄까? <뒤를 재빨리 둘러보는 톰마>$b$b공룡사제들도 구리긴 이 마을이나 마찬가지야.$b$b크로쉬크 숭배 때문에 약해졌지. 입으로는 힘을 설파하지만, 직접 사냥을 하길 해, 적을 죽이길 해, 쓰러진 형제들의 썩어가는 시체에서 뒹굴길 해?$b$b그러긴커녕 동굴 속에 숨어서 말만 하고 있어. 녀석들이 정말 강했다면 여기 나와서 함께 싸우고 있었겠지.', `MaleText_loc4`='你知道我怎么想吗？<托犸飞快地向身后看了一眼。>$b$b蜥蜴人祭司就跟这个村子本身一样肮脏。$b$b他们的考什克崇拜令自己变得软弱。他们鼓吹力量，可他们敢出去狩猎吗？他们敢杀人吗？他们敢在阵亡的兄弟们腐败的残躯上打滚吗？$b$b不敢。他们只会躲在山洞里夸夸其谈。如果他们真的够强壮，就应该出来与我们战斗。', `MaleText_loc5`='你知道我在想什麼嗎? <托瑪緊張地看了一下後面。>$b$b魔龍祭司就跟這座村子一樣髒。$b$b他們那套克羅西克的信仰害他們變弱。他們宣揚力量的重要，但是他們有去打獵嗎?有親自動手殺獵物嗎?他們有在陣亡弟兄腐化的屍體上打滾嗎?$b$b沒有。他們只是躲在山洞裡講大話而已。他們要是真的有那麼強，他們早就該出來跟我們一起戰鬥了。', `MaleText_loc7`='¿Sabes lo que creo? <Tomma mira un instante detrás de él.>$b$bLos sacerdotes saurios están tan llenos de basura como el propio pueblo.$b$bSu adoración a Kroshik les hace débiles. Dan sermones sobre la fortaleza, pero ¿acaso cazan? ¿Matan? ¿Se revuelcan en los cadáveres en descomposición de sus hermanos caídos?$b$bNo. Se esconden en las cuevas y hablan. Si realmente fueran fuertes, estarían ahí fuera luchando con nosotros.' WHERE `ID`=71428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공룡사제들은 우리 힘이 크로쉬크에게서 나온다고 하지. 녀석들의 종교 얘긴 듣지 마.$b$b우리 힘은 우리 발톱, 우리 이빨, 우리 무기에서 나오는 거야. 오물장이들이 모아서 배양하는 오물에서 나오는 거라고.$b$b우리 힘은 우리한테서 나오는 거야.$b$b우리가 하늘에 사는 데빌사우루스의 후손이든 모구의 손으로 창조되었든 난 관심 없어. 난 이 땅을 적에게서 지키는 데 관심이 있을 뿐이야.', `MaleText_loc4`='蜥蜴人祭司会告诉你说我们的力量来自考什克。别听他们那一套。$b$b我们的力量来自我们的爪子，我们的牙齿。它来自那些污秽污染者收集并培养的污秽。$b$b它来自我们本身。$b$b我不在乎我们究竟是源自某种魔暴龙，还是魔古族的造物。我只关心怎样保护这片土地不受敌人的侵扰。', `MaleText_loc5`='魔龍祭司會跟你說，我們的力量來自克羅西克。別聽他們傳教的鬼話。$b$b我們的力量來自我們的爪子、我們牙齒，我們的武器。來自穢物處理者收集回來和培養出來的髒東西。$b$b我們的力量來自我們自己。$b$b我不在乎我們究竟是來自天上的魔暴龍，還是被魔古創造出來的。我在乎的，只有保護這塊土地不受敵人的侵略。', `MaleText_loc7`='Los sacerdotes saurios te dirán que nuestra fuerza proviene de Kroshik. No escuches sus sermones.$b$bNuestra fuerza proviene de nuestras garras, de nuestras armas. Proviene de la basura que los urderroñas reúnen y cultivan.$b$bProviene de nosotros mismos.$b$bMe da igual si descendemos de un demosaurio del cielo o si nos crearon los mogu. Lo único que me importa es proteger esta tierra de nuestros enemigos.' WHERE `ID`=71429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모구의 손으로 창조됐어. 안 믿을 이유가 없다고. 그걸 부인하는 녀석들은 무식하거나 환상에 젖어 있는 거야.$b$b나는 데빌사우루스인 척하지 않겠어. 난 내가 누군지 알아. 내 힘이 어디서 오는지도 알고.', `MaleText_loc4`='我们是由魔古族创造出来的。我们没道理拒绝相信这一点。任何否认它的人要么是无知，要么就是活在幻想之中。$b$b我可不想假装自己是一头魔暴龙。我知道我是什么。我知道我的力量从何而来。', `MaleText_loc5`='我們是魔古創造出來的，沒什麼理由好懷疑。所有拒絕承認這個事實的人都只是無知，或者只是活在幻想裡。$b$b我拒絕假裝我是一頭魔暴龍，我知道自己是什麼，我知道我的力量來自何處。', `MaleText_loc7`='Nos crearon los mogu. No hay motivo para no creerlo. Cualquiera que lo niegue es un ignorante o vive en un mundo de fantasía.$b$bMe niego a fingir que soy un demosaurio. Sé lo que soy. Sé de dónde proviene mi fuerza.' WHERE `ID`=71430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크를 숭배하는 사우록들은 겁이 나서 그러는 것뿐이야.$b$b우리 모두가 작은 데빌사우루스라고 믿으면서, 하늘에 사는 눈에 보이지 않고 막강한 데빌사우루스에게 "힘"을 증명해서 환심을 사려 하지.$b$b그치들은 정말 그렇게 믿고 있어.$b$b우리는 데빌사우루스가 아냐. 사우록이지. 죽은 후에는, 영원한 사냥도, 약속된 천국도, 약자에 대한 벌도, 크로스도 없어. 누군가 우리 고기를 먹고 남은 것을 오물 웅덩이에 버리겠지. 그게 다야. 내 눈으로 봤다고.', `MaleText_loc4`='“只有那些吓破胆的蜥蜴人才会去崇拜考什克。$b$b他们假装我们都是一群直立行走的小魔暴龙，想靠证明我们的‘力量’来获取天上的某一头无形无影、全知全能的魔暴龙的垂青。$b$b他们真的这么想。$b$b我们不是魔暴龙。我们是蜥蜴人。当我们死后，也没有什么永恒的狩猎，没有许诺的天堂，没有对弱者的惩罚，更没有克洛斯。我们会被吃掉，而我们的残躯将被抛入污水池。就是这样。我亲眼看见了。”', `MaleText_loc5`='薩烏洛克崇拜克羅西克，是因為他們害怕。$b$b他們假裝我們全都是小小的魔暴龍，然後要向天上一隻無形的、全能的魔暴龍證明我們的「力量」。$b$b那就是他們深信不疑的東西。$b$b我們不是魔暴龍，我們是薩烏洛克。死了以後沒有永恆的狩獵，沒有來生的樂土，沒有對弱者的懲罰，更沒有什麼克羅斯。我們會被吃掉、然後吃剩的屍體被扔進穢物池。就是這樣而已，我已經看透了。', `MaleText_loc7`='Los saurok que adoran a Kroshik solo lo hacen porque tienen miedo.$b$bCreen que somos pequeños demosaurios que deben demostrar su "fuerza" para ganar el favor de un demosaurio invisible y todopoderoso que vive en el cielo.$b$bLo creen de veras.$b$bNo somos demosaurios. Somos saurok. Y cuando muramos no habrá caza eterna, paraíso prometido ni castigo para los débiles. Kros no existe. Nos comerán y lanzarán nuestros restos a la poza de basura. Eso es todo. Lo he visto con mis propios ojos.' WHERE `ID`=71431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그들의 거짓된 의식에 동참하지 않을 거야. 크로쉬크나 놈의 고기나 특별할 것이 전혀 없어. 고기는 고기일 뿐이지.', `MaleText_loc4`='我才不参加他们那个虚伪的仪式呢。考什克没什么特别的，他的肉也是。肉就是肉。', `MaleText_loc5`='我不會參加他們虛假的儀式，克羅西克根本沒什麼特別的。他的肉也一樣，肉就是肉。', `MaleText_loc7`='No participaré en su falso ritual. No hay nada especial en Kroshik ni en su carne. La carne es la carne.' WHERE `ID`=71432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 고기 좀 먹었어?$b$b난 요전에 노움을 한 마리 먹었는데, 이빨에 낀 분홍색 털을 빼 가면서까지 먹을 정도는 아닌 것 같아.', `MaleText_loc4`='最近有找到什么好肉吗？$b$b我前几天吃了一个侏儒。太难吃了，我花了好多工夫才把牙缝里的粉色头发剔干净。', `MaleText_loc5`='最近有找到什麼好肉嗎?$b$b那天我吃了一個地精，連塞牙縫都不夠。', `MaleText_loc7`='¿Has encontrado carne buena últimamente?$b$bYo me comí un gnomo el otro día. No merece la pena, luego hay que quitarse todos esos pelos rosas de entre los dientes.' WHERE `ID`=71433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발밑에 바퀴벌레 있어, $g형제:자매;.$b$B발 조심하라고. 바퀴벌레는 질병을 퍼뜨리는 데 도움이 된단 말이야.', `MaleText_loc4`='你脚上有蟑螂，$g兄弟:姐妹;。$b$b小心走路。蟑螂能帮我们传播疾病。', `MaleText_loc5`='這位$g兄弟:姊妹;，你踩到蟑螂了。$b$b當心點，蟑螂可是幫我們散佈疾病的幫手。', `MaleText_loc7`='Hay cucarachas a tus pies, $ghermano:hermana;.$b$bTen cuidado de dónde pisas. Las cucarachas nos ayudan a extender la enfermedad.' WHERE `ID`=71434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 늪에 나갔다가 좋은 오물을 발견했어. 오물장이들이 날 자랑스러워할 거야.', `MaleText_loc4`='我今天在外面的沼泽里找到一些很好的污物。污染者会为我骄傲的。', `MaleText_loc5`='今天我在沼澤裡找到了不少髒東西，穢物收集者一定會以我為榮。', `MaleText_loc7`='He encontrado una basura estupenda en los marjales hoy. Los urderroñas estarán orgullosos de mí.' WHERE `ID`=71435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨끗한 고기는 먹지 마. 부랑칼날은 겉만큼 안도 강하거든.', `MaleText_loc4`='不要吃干净的肉。邪刃蜥蜴人的强壮必须表里如一。', `MaleText_loc5`='不要吃乾淨的肉。我們污刃族不論體內體外都一樣強壯。', `MaleText_loc7`='No comas carne limpia. Los Hojaescoria son tan fuertes en el interior como en el exterior.' WHERE `ID`=71436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 새로 나타난 적을 주시하고 있어.$b$b등 꼿꼿한 트롤은 모구랑 손을 잡았고, 나머지 침입자들이 그에 맞서 싸우고 있지.$b$b하! 맘대로 하라지. 녀석들이 싸우는 바람에 주울 시체가 많아졌으니까. 부랑칼날은 어느 때보다도 강해.', `MaleText_loc4`='我看到了我们的新敌人。$b$b直背的巨魔与魔古族结了盟，但其他入侵者却在与他们交战。$b$b呸！我才不在乎。他们的战斗给我们留下了许多尸体。邪刃部族前所未有地强大。', `MaleText_loc5`='我有在觀察我們的新敵人。$b$b背挺直的食人妖和魔古聯手了，但是其他的入侵者卻和他們打了起來。$b$b哼，我不在乎誰輸誰贏，他們的戰鬥留下了很多的屍體給我們，污刃族從來沒有這麼飽食強壯過。', `MaleText_loc7`='Observo a nuestros nuevos enemigos.$b$bLos trols erguidos se han aliado con los mogu, pero los otros invasores se enfrentan a ellos.$b$b¡Bah! Me da igual. Sus enfrentamientos nos han proporcionado un montón de carroña. Los Hojaescoria nunca han sido tan fuertes.' WHERE `ID`=71437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 고기 좀 먹었어?$b$b난 요전에 블러드 엘프를 한 마리 먹었는데, 꽃밭에 구른 것 같은 맛이 나더라고.', `MaleText_loc4`='最近有找到什么好肉吗？$b$b我前几天吃了一个血精灵，那味道就好像他在花丛里滚过一样。', `MaleText_loc5`='最近有找到什麼好肉嗎?$b$b那天我吃了一個血精靈，味道好像一大把的花。', `MaleText_loc7`='¿Has encontrado carne rica últimamente?$b$bYo el otro día me comí un elfo de sangre. Sabía como si se hubiera revolcado en flores.' WHERE `ID`=71438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 오물 남는 거 있으면 오물 웅덩이에 좀 부어 주면 고맙겠어.', `MaleText_loc4`='帮我个忙：把你多余的污物丢到污水池里。', `MaleText_loc5`='幫我一個忙:把你多的穢物丟進穢物池。', `MaleText_loc7`='Hazme un favor: deposita la basura que te sobre en la poza de basura.' WHERE `ID`=71439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이갈룩이 변하고 있어. 사우록들이 서로 등을 돌리고 있어. 우리 사이에 침입자가 있다고 생각하는 자들도 있더군.', `MaleText_loc4`='伊瓜鲁克正在改变。蜥蜴人们正在互相争斗。有人认为我们中间出现了入侵者。', `MaleText_loc5`='改變降臨了伊加路克。薩烏洛克開始自相殘殺，有人認為我們中間已經有入侵者。', `MaleText_loc7`='Soplan vientos de cambio en Ihgaluk. Los saurok se vuelven unos contra otros. Algunos creen que hay intrusos entre nosotros.' WHERE `ID`=71440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 괜찮은 사냥감 좀 잡았어?$b$b난 어제 타우렌을 잡았는데, 그 몸뚱이를 오물 웅덩이로 가져오는 데 청소부가 셋이나 있어야 했어!', `MaleText_loc4`='最近有没有大开杀戒？$b$b我昨天杀了一个牛头人。我们出动了三个食腐者才把他运回污水池！', `MaleText_loc5`='最近有殺到什麼東西嗎?$b$b昨天我殺了個牛頭人，要三個拾荒者才把他的屍塊全部抬回穢物池!', `MaleText_loc7`='¿Has matado algo interesante últimamente?$b$bYo maté un tauren ayer. ¡Hicieron falta tres carroñeros para llevar sus restos a la poza de basura!' WHERE `ID`=71441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구가 우릴 없애려고 해. 모구는 우리 적이야. 우리 마을에 가까이 오기만 하면 모조리 죽여 버릴 거야.$b$b도와줄 거지?', `MaleText_loc4`='魔古族想消灭我们。魔古族是我们敌人。我要杀光靠近我们家园的魔古族。$b$b你愿意来帮忙吗？', `MaleText_loc5`='魔古想要消滅我們，魔古是我們的敵人。$b$b我要殺光靠近我們家園的每一個魔古$b$b你願意幫幫我們嗎?', `MaleText_loc7`='Los mogu quieren destruirnos. Los mogu son nuestro enemigo. Asesinaré a todo mogu que se acerque a nuestro hogar.$b$b¿Me ayudarás?' WHERE `ID`=71442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에 괜찮은 사냥감 좀 잡았어?$b$b난 어제 드레나이를 잡았는데, 아직도 오물 웅덩이 옆에 있어... 파란 내장을 찾아 보라고.', `MaleText_loc4`='最近有没有大开杀戒？$b$b我昨天杀了一个德莱尼。你可以在污水池附近找到她……有蓝色内脏的就是。', `MaleText_loc5`='最近有殺到什麼東西嗎?$b$b昨天我殺了個德萊尼，屍體已經扔到穢物池旁邊...藍色的那堆就是了!', `MaleText_loc7`='¿Has matado algo interesante últimamente?$b$bYo maté a una draenei ayer. Puedes verla en la poza de basura... busca las entrañas azules.' WHERE `ID`=71443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발톱을 항상 날카롭게 다듬어 둬. 언제 고깃덩이가 지나갈지 모르니 말이야.', `MaleText_loc4`='磨利你的爪子。你永远不知道何时会有一块好肉经过。', `MaleText_loc5`='保持爪子尖利，你無法預料什麼時候會有肉走過來。', `MaleText_loc7`='Mantén afiladas tus garras. Nunca se sabe cuándo aparecerá un buen trozo de carne.' WHERE `ID`=71444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸우고 죽이고 먹고, 그렇게 사는 거야.$b$b죽을 때는 형제자매들이 널 먹을 수 있는 데서 죽도록 해. 적의 먹이가 되어 줘선 안 되지.', `MaleText_loc4`='战斗、杀戮、进食，好好活过每一天。$b$b如果你死了，记得死在方便你的兄弟姐妹吃掉你的地方。没必要去给敌人送菜。', `MaleText_loc5`='打、殺、吃，再活一天。$b$b就算要死，也要死在兄弟姊妹吃得到你的地方。可別餵了敵人。', `MaleText_loc7`='Lucha, mata, come, sobrevive.$b$bSi mueres, hazlo donde tus hermanos puedan comerte. No tiene sentido alimentar a tus enemigos.' WHERE `ID`=71445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구를 죽이자.$b$b모구를 죽이자.$b$b모구를 죽이자.', `MaleText_loc4`='杀魔古族。$b$b杀魔古族。$b$b杀杀杀！', `MaleText_loc5`='殺光魔古。$b$b殺光魔古。$b$b殺光魔古。', `MaleText_loc7`='Mata a los mogu.$b$bMata a los mogu.$b$bMata a los mogu.' WHERE `ID`=71446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부랑칼날에 언제나 힘을. 적에게 언제나 죽음과 파멸을.', `MaleText_loc4`='力量与邪刃部族同在。杀死我们敌人，割碎他们。', `MaleText_loc5`='污刃族永遠強壯。我們的敵人會死無全屍。', `MaleText_loc7`='La fuerza siempre para los Hojaescoria. Muerte y desmembramiento para nuestros enemigos.' WHERE `ID`=71447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 적을 어떻게 죽이는 게 좋아? 이빨로? 칼로? 뒤에서? 어두운 데서 덮쳐서?', `MaleText_loc4`='你喜欢怎么杀人？用牙齿？用武器？从背后偷袭？还是从暗处偷袭？', `MaleText_loc5`='你喜歡怎麼殺?用牙齒?用刀?從後面?從暗處?', `MaleText_loc7`='¿Cómo prefieres matar? ¿Con los dientes? ¿Con la espada? ¿Por la espalda? ¿En la oscuridad?' WHERE `ID`=71448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, 깨끗한 비늘. 모구한테 당하고 싶어? 아니면 모구의 애완동물이라도 되고 싶은 거야?$b$b자기 몸은 자기가 지켜야지, $g형제:자매;. 오물 좀 묻히라고.', `MaleText_loc4`='瞧瞧你这副干净的皮囊。你想让魔古族攻击你吗？你想做他们的宠物？$b$b保护好你自己，$g兄弟:姐妹;。快把污物涂在身上吧。', `MaleText_loc5`='看看你，鱗片乾乾淨淨的。你想要魔古攻擊你們嗎?想要當他們的寵物嗎?$b$b保護好自己，$g兄弟:姊妹;，把穢物弄到身上。', `MaleText_loc7`='Mírate, escama-limpia. ¿Quieres que te ataquen los mogu? ¿Quieres que te conviertan en su mascota?$b$bProtégete, $ghermano:hermana;. Revuélcate en basura.' WHERE `ID`=71449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쓰레기 더미를 신선하게 유지하는 게 우리 임무야. 오물이 우릴 지켜 주고 적을 쫓아 주거든.', `MaleText_loc4`='我们的责任就是保持污泥的新鲜。污秽保护了我们的安全。它们能赶走敌人。', `MaleText_loc5`='收集髒東西是大家的責任，髒東西保護我們的安全，髒東西讓敵人無法接近。', `MaleText_loc7`='Es nuestra responsabilidad mantener el fango fresco. La basura nos mantiene a salvo. Mantiene alejados a nuestros enemigos.' WHERE `ID`=71450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배고픔을 잘 관리하도록 해, $g형제:자매;. 항상 고기를 조금씩 남겨서 썩혀 두도록 해.$b$b지나치게 굶주린 사우록이 있으면 우리 모두 파멸할지도 몰라.', `MaleText_loc4`='管好你的胃，$g兄弟:姐妹;。记得留一点肉让它烂掉。$b$b暴饮暴食的蜥蜴人会害死我们大家的。', `MaleText_loc5`='克制你的飢餓，$g兄弟:姊妹;，記得要留點肉放給它爛。$b$b吃太多的薩烏洛克會害我們滅亡。', `MaleText_loc7`='Sacia tu apetito, $ghermano:hermana;, pero deja siempre algo de carne para que se pudra.$b$bLos saurok famélicos nos traerán la ruina.' WHERE `ID`=71451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앗! 몸에 깨끗한 부분이 있잖아, $g형제:자매;. 내가 손을 봐 줄게...', `MaleText_loc4`='啊！你身上有一块干净的地方，$g兄弟:姐妹;。让我帮你弄脏……', `MaleText_loc5`='啊!你有塊地方太乾淨了，$g兄弟:姊妹;。我來幫你弄髒一點...', `MaleText_loc7`='¡Ah! Tienes una parte limpia, $ghermano:hermana;. Deja que lo arregle...' WHERE `ID`=71452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 누가 우리 오물 구덩이에 무슨 짓을 하는 게 보이면 알려줘. 침입자가 있다는 얘길 들었거든.', `MaleText_loc4`='如果你抓到破坏污水池的人，记得通知我。我听说了入侵者的事。', `MaleText_loc5`='逮到有人干擾穢物池就來告訴我，我聽說已經有入侵者。', `MaleText_loc7`='Avísame si cazas a alguien entrometiéndose en nuestra poza de basura. He oído rumores acerca de intrusos.' WHERE `ID`=71453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 바퀴벌레 밟지 않게 조심해, $g형제:자매;.', `MaleText_loc4`='别踩到我的蟑螂，$g兄弟:姐妹;。', `MaleText_loc5`='小心別踩到我的蟑螂，$g兄弟:姊妹;。', `MaleText_loc7`='Intenta no pisar mis cucarachas, $ghermano:hermana;.' WHERE `ID`=71454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 오물이 필요하면 나한테 이야기해. 도와줄 테니까.', `MaleText_loc4`='如果你需要污物，可以来找我。我能帮你。', `MaleText_loc5`='需要髒東西就來找我。我可以幫你。', `MaleText_loc7`='Si en algún momento necesitas un poco de basura, ven a hablar conmigo. Puedo ayudarte.' WHERE `ID`=71455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다에 가까이 가지 마. 너무 깨끗하거든.$b$b공룡사제들이 그러잖아. 냄새를 풍기는 게 신께 가까이 가는 거라고.', `MaleText_loc4`='远离大海。它太干净了。$b$b蜥蜴人祭司会告诉你：污秽是仅次于虔诚的美德。', `MaleText_loc5`='離大海遠一點，太乾淨了。$b$b魔龍祭司會告訴你:乾淨就是不敬。', `MaleText_loc7`='No te acerques al mar. Está demasiado limpio.$b$bLos sacerdotes saurios te lo dirán: la suciedad te acerca a la divinidad.' WHERE `ID`=71456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 그들이 우리를 만들었다고 주장한다네... 우릴 지금 모습으로 비틀어 놓았다고 말이지. 난 그런 거짓말은 믿지 않네.$b$b우리는 위대한 창조주, 크로스로부터 진화한 독립적인 종족일세!', `MaleText_loc4`='魔古族自称创造了我们……并将我们扭曲成现在的形态。不要相信他们的谎言。$b$b我们是独立的人民，源自于伟大的造物主克洛斯！', `MaleText_loc5`='魔古宣稱是我們是他們創造的...我們的形體是他們塑造的。千萬不要相信他們的謊話。$b$b我們跟他們無關，我們是從偉大的造物主克羅斯進化來的!', `MaleText_loc7`='Los mogu aseguran que nos han creado... que han dado forma a nuestra carne. No te creas sus mentiras.$b$bNosotros hemos evolucionado a partir del gran creador, el mismísimo Kros.' WHERE `ID`=71457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크는 창조주신 크로스께서 주신 선물일세. 그를 보며 우리는 혈통의 힘, 전통의 힘을 되새길 수 있지. 그를 통해 우리는 영예로운 미래를 볼 수 있네.', `MaleText_loc4`='考什克是来自我们的造物主克洛斯的礼物。他让我们记住自己的力量，传承与遗产。他让我们看到了辉煌的未来。', `MaleText_loc5`='克羅西克是我們的造物主克羅斯所賜的禮物，提醒我們要記住我們的力量、記住我們的根源、記住我們的傳承，而且還讓我們看見光榮美好的未來。', `MaleText_loc7`='Kroshik es un don de nuestro creador, Kros. Nos recuerda su fortaleza, su herencia, nuestro legado. Nos informa de nuestro glorioso futuro.' WHERE `ID`=71458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 우리 적일세. 이 세상에서 우릴 없애 버리려 하지. 왜 그런 놈들이 지어낸 창세 신화를 믿어야 하나?', `MaleText_loc4`='魔古族是我们的敌人。他们想将我们从这个世界上抹去。我们为什么要相信他们灌输给我们的造物神话？', `MaleText_loc5`='魔古是我們的敵人，他們要把我們從世界剷除。我們怎麼可以相信他們宣稱的那套謊話?', `MaleText_loc7`='Los mogu son el enemigo. Pretenden eliminarnos de su mundo. ¿Por qué nos vamos a creer los mitos de creación que nos cuentan?' WHERE `ID`=71459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강해져야 하네.$b$b악해져야 하고.$b$b먹을 수 있는 것보다 더 많이 죽이게.$b$b친구도 사귀지 말고, 애완동물도 기르지 말게.$b$b싸우다 죽게.$b$b우리는 크로쉬크로부터 이를 비롯해 많은 교훈을 배울 수 있지.', `MaleText_loc4`='保持强壮。$b$b保持邪恶。$b$b屠杀吃不完的猎物。$b$b不要交朋友，不要养宠物。$b$b战斗到死。$b$b这些，以及其他许多真理，都是考什克的教诲。', `MaleText_loc5`='要強壯，$b$b要兇狠，$b$b要殺得比你能吃的還多。$b$b不交友、不養寵。$b$b要死就得戰死。$b$b這些，還有很多很多，都是我們能從克羅西克學到的教訓。', `MaleText_loc7`='Sé fuerte.$b$bSé cruel.$b$bMata más de lo que puedas comer.$b$bNo hagas amigos y no tengas mascotas.$b$bMuere luchando.$b$bEstas y otras lecciones las podemos aprender de Kroshik.' WHERE `ID`=71460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크 앞에서는 겸손하게 행동하게, 사우록. 그는 이 세상에서 크로스께 가장 가까운 존재라네.$b$b그의 존재를 음미하게. 크로쉬크가 영원히 살지는 못할 테니까.', `MaleText_loc4`='在考什克面前保持恭谨，蜥蜴人。在这个世界上，他是最接近克洛斯的存在。$b$b享用他的存在。他不会一直活下去。', `MaleText_loc5`='薩烏洛克，要敬畏克羅西克。因為在這個世界上，他是最接近克羅斯的存在。$b$b享受他的眷顧，他不會永遠都存在。', `MaleText_loc7`='Arrodíllate ante Kroshik, saurok. Es lo más cercano a Kros que presenciarás en este mundo.$b$bDisfruta de su presencia. No vivirá para siempre.' WHERE `ID`=71461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크는 우리에게 육신과 뼈와 힘과 영혼을 준다네. 우리가 존재할 수 있는 건 그 덕택이지.', `MaleText_loc4`='考什克将自己的血骨、力量和灵魂给了我们。我们要为自己的存在而感谢他。', `MaleText_loc5`='克羅西克給了我們他的身體、他的骨骼、他的力量，以及他的精魂。我們的存在全都歸因於他。', `MaleText_loc7`='Kroshik nos entrega su cuerpo, sus huesos, su fuerza y su espíritu. Le debemos la existencia.' WHERE `ID`=71462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크는 우리의 창조주, 크로스의 핏줄이라네. 우리는 크로스께 선택받은 종족이지.$b$b그분의 힘이 우리를 돌보시니, 우리는 절대 죽지 않네.', `MaleText_loc4`='考什克是我们的造物主克洛斯的血脉。我们是克洛斯的选民。$b$b依靠它的力量，我们将得到永生。', `MaleText_loc5`='克羅西克就是造物主克羅斯的血。我們是克羅斯的選民。$b$b有他的力量在，我們絕不會死。', `MaleText_loc7`='Kroshik es la sangre de Kros, nuestro creador. Somos el pueblo elegido de Kros.$b$bMientras su fuerza nos sustente, nunca moriremos.' WHERE `ID`=71463;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로스의 이상에 몸 바치는 삶을 살게. 끊임없이 싸우고, 끊임없이 성장하게. 매일 조금씩 강해지게.$b$b고통을 참고 싸우게. 오물을 뒤집어 써도 참게. 모두가 적일세.$b$b죽더라도 손에 무기를 들고 죽게. 그리고 육신을 이갈룩에 내어 주게.', `MaleText_loc4`='为克洛斯的理想而活。战斗不息，成长不止。每一天都要更加强壮。$b$b战胜痛苦，忍受污秽。所有人都是你的敌人。$b$b握着你的武器死去，将你的躯体献给伊瓜鲁克。', `MaleText_loc5`='誠心敬拜克羅斯，不要放棄戰鬥、不要放棄成長。今天要比昨天更強、明天要比今天更壯$b$b在痛苦中奮戰，在髒污中掙扎，所有人都是敵人。$b$b死要手裡握著武器，死要身軀獻給伊加路克。', `MaleText_loc7`='Entrega tu vida a los ideales de Kros. Nunca dejes de luchar, no dejes de crecer. Cada día más fuerte que el anterior.$b$bLucha contra el dolor. Sufre en la basura. Todos son tus enemigos.$b$bMuere con el arma en la mano. Entrega tu cuerpo a Ihgaluk.' WHERE `ID`=71464;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구 죽이자.', `MaleText_loc4`='杀魔古族。', `MaleText_loc5`='殺光魔古。', `MaleText_loc7`='Mata a los mogu.' WHERE `ID`=71465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적은 걸어다니는 고깃덩이야.', `MaleText_loc4`='敌人就是会走路的肉。', `MaleText_loc5`='敵人只是會走的肉。', `MaleText_loc7`='El enemigo es carne andante.' WHERE `ID`=71466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에게 죽음을.', `MaleText_loc4`='去死吧，魔古族。', `MaleText_loc5`='魔古必死。', `MaleText_loc7`='Muerte a los mogu.' WHERE `ID`=71467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽이자. 먹자. 죽이자.', `MaleText_loc4`='杀戮、进食、杀戮。', `MaleText_loc5`='殺。吃。殺。', `MaleText_loc7`='Mata. Come. Mata.' WHERE `ID`=71468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이빨을 날카롭게, 발톱도 날카롭게.', `MaleText_loc4`='尖牙与利爪。', `MaleText_loc5`='牙齒要利，爪子要尖。', `MaleText_loc7`='Colmillos afilados, garras afiladas.' WHERE `ID`=71469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두려움도 연민도 없다. 침입자를 죽이자.', `MaleText_loc4`='拒绝恐惧。拒绝同情。杀光入侵者。', `MaleText_loc5`='沒有恐懼，沒有後悔。殺光入侵者。', `MaleText_loc7`='Sin temor. Sin remordimiento. Mata al invasor.' WHERE `ID`=71470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 자에게 자비는 없다.', `MaleText_loc4`='不要同情弱者。', `MaleText_loc5`='對弱者絕不留情。', `MaleText_loc7`='No hay piedad para los débiles.' WHERE `ID`=71471;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절대로 약해지지 마라. 언제나 강해라.', `MaleText_loc4`='不要软弱，保持强壮。', `MaleText_loc5`='不要軟弱，只要強壯。', `MaleText_loc7`='Nunca débil. Siempre fuerte.' WHERE `ID`=71472;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다를 주시해, $g형제:자매;. 모구가 어디서 공격해 올지 모르니까.', `MaleText_loc4`='注意海面，$g兄弟:姐妹;。魔古族可能从任何方向发起攻击。', `MaleText_loc5`='注意大海的方向，$g兄弟:姊妹;。魔古可能從任何地方進攻。', `MaleText_loc7`='No pierdas de vista el mar, $ghermano:hermana;. Los mogu pueden atacar desde cualquier parte.' WHERE `ID`=71473;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로스께서는 바다도마뱀을 높이 사시지. 바다에서는 좋은 식량과 오물이 나거든.', `MaleText_loc4`='克洛斯更看重海龙战士。大海是美食和污秽的发源地。', `MaleText_loc5`='海龍在克羅斯的眼中地位頗高，而且大海也是好食物和髒東西的家。', `MaleText_loc7`='Kros aprecia especialmente a los dragones marinos. El mar alberga buena comida y buena basura.' WHERE `ID`=71474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로스의 제단은 성스러운 곳이야, $g형제:자매;. 이쪽 해변에 있을 때는 조심하라고.', `MaleText_loc4`='克洛斯祭坛是神圣的地方，$g兄弟:姐妹;。在我的海滩上，你要小心行走。', `MaleText_loc5`='克羅斯的祭壇是神聖的，$g兄弟:姊妹;，在我海灘行走時要注意自己走到了哪裡。', `MaleText_loc7`='El altar de Kros es un lugar sagrado, $ghermano:hermana;. Cuidado con lo que haces en mi playa.' WHERE `ID`=71475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이상한 배가 보여. 모구 배는 아닌데 말이지.$b$b저 침입자들은 누굴까? 뭘 원하는 걸까? 무슨 맛일까?', `MaleText_loc4`='我们最近常常见到奇怪的船只，不是魔古族的船。$b$b这些入侵者是谁？他们想要什么？他们都什么味儿？', `MaleText_loc5`='我們看到很多奇怪的船，而且不是魔古的船。$b$b這些入侵者是誰?他們有什麼目的?他們吃起來的味道怎樣?', `MaleText_loc7`='Vemos naves extrañas. No son naves mogu.$b$b¿Quiénes son estos invasores? ¿Qué quieren? ¿A qué saben?' WHERE `ID`=71476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바다에 시체가 많아. 평소보다 더.$b$b가까운 데서 전쟁이 났나 봐.$b$b사우록한테는 좋지. 시체가 많으면 먹을 것도 많으니까. 오물도 많고.', `MaleText_loc4`='海里有很多尸体。比平时更多。$b$b附近发生了战争。$b$b这对蜥蜴人是好事。更多的尸体意味着更多的食物，更多的污物。', `MaleText_loc5`='海裡有很多屍體，比平常多很多。$b$b附近發生了戰爭。$b$b對薩烏洛克是好事，因為更多的屍體就是更多的食物、更多的髒東西。', `MaleText_loc7`='Hay muchos cadáveres en el mar. Más de lo habitual.$b$bHay una guerra cerca.$b$bEso es bueno para los saurok. Más cuerpos significan más comida y más basura.' WHERE `ID`=71477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자 냄새가 난다. 놈들이 가까이 있어.$b$b<당신을 수상쩍다는 듯 쳐다보는 바다도마뱀>', `MaleText_loc4`='我闻到了入侵者的味道。他们就在附近。$b$b<海龙战士狐疑地看着你。>', `MaleText_loc5`='我聞到了入侵者的味道，他們就在附近。$b$b<海龍用可疑的目光看著你。>', `MaleText_loc7`='Huelo intrusos. Están cerca.$b$b<El dragón marino te lanza una mirada de sospecha.>' WHERE `ID`=71478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 배반자라고 부르는 공룡사제들도 있어. "크로쉬크는 바다에서 사냥하지 않는다"라나 뭐라나.$b$b나는 크로스의 길을 따르지만 사제들 말은 안 믿어. 크로쉬크는 어디에서나 사냥하고, 나도 그렇거든.$b$b사제들은 크로쉬크에 대해 고집스럽고 닫힌 생각을 갖고 있지만, 그런 건 지금의 부랑칼날에는 맞지 않아.', `MaleText_loc4`='“某些蜥蜴人祭司称我为叛徒。‘考什克不会在海里狩猎，’”他们如是说。$b$b我信仰克洛斯之道，可我并不赞同这些祭司。考什克会在力所能及的范围内狩猎，我也是。$b$b在今天的邪刃部族里，这些祭司和他们对考什克顽固僵化的理解已经没有市场了。', `MaleText_loc5`='有些魔龍祭司說我是叛徒，他們說「克羅西克不會在海裡狩獵。」$b$b我追隨也是克羅斯，但是我不同意那些祭司的看法。克羅西克在哪裡都能狩獵，所以我也一樣。$b$b那些祭司對克羅西克的說法太保守、太頑固了，對現在的污刃族沒有幫助。', `MaleText_loc7`='Algunos sacerdotes saurios me llaman traidor. "Kroshik no caza en el mar", dicen.$b$bYo sigo el camino de Kros, pero no estoy de acuerdo con esos sacerdotes. Kroshik caza DONDE PUEDE, igual que yo.$b$bLa visión obstinada y cerrada de esos sacerdotes no tiene sentido para los Hojaescoria de hoy en día.' WHERE `ID`=71479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오물은 우리를 보호해 줘. 적들은 이갈룩의 냄새를 견디질 못하지.$b$b하지만 오물을 해변에 모아 두긴 힘들어. 아무리 열심히 오물을 쌓아도 바다가 금방 삼켜 버리거든. 달리 해변을 지킬 방법이 있을 거야.$b$b<날카로운 이빨을 드러내며 웃는 바다도마뱀> 내가 그래서 있는 거 아니겠어, $g형제:자매;.', `MaleText_loc4`='污秽保护着我们。我们敌人忍受不了伊瓜鲁克的臭味。$b$b可是，在海滩上保持肮脏是很难的。海滩消耗污物的速度比我们制造的速度更快。我们得想其他办法来保护我们的海滩。$b$b<海龙战士微微一笑，露出了锋利的牙齿。>这就是我的任务，$g兄弟:姐妹;。', `MaleText_loc5`='髒東西保護我們，敵人受不了伊加路克的味道。$b$b但是，要讓髒東西留在海灘上很困難，大海喝掉髒東西的速度快過我們弄髒它的速度。不過...還是有其他的辦法來保護我們的海岸。$b$b<海龍咧嘴微笑，露出剃刀般銳利的牙齒。>那個辦法就是我，$g兄弟:姊妹;。', `MaleText_loc7`='La basura nos protege. Nuestros enemigos no pueden soportar el olor de Ihgaluk.$b$bPero es complicado mantener la basura en la playa. El océano se bebe nuestra basura más rápidamente de lo que somos capaces de generarla. Tiene que haber otros modos de proteger nuestras costas.$b$b<El dragón marino te lanza una sonrisa llena de dientes afilados.> Y ahí es donde entras tú, $ghermano:hermana;.' WHERE `ID`=71480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<애완동물 뒤에 숨는 사우록>', `MaleText_loc4`='<这个蜥蜴人躲到了宠物身后。>', `MaleText_loc5`='<這個薩烏洛克畏縮地躲到他的寵物後面。>', `MaleText_loc7`='<El saurok se esconde tras su mascota.>' WHERE `ID`=71481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가까이 오지 마세요, 강한 자. 싸우고 싶지 않아요.', `MaleText_loc4`='求你，退后，强者。我不想打仗。', `MaleText_loc5`='請後退，陌生人，我不想跟你打。', `MaleText_loc7`='No te acerques, por favor, fuerte. No busco pelea.' WHERE `ID`=71482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공룡사제들이 내가 약한 걸 알았어요. 투사들이 날 때리고 짧은니라고 놀려요. 날 지켜주는 바실리스크마저 없었다면 난 외톨이였을 거예요.$b$b아마 벌써 죽었겠죠.', `MaleText_loc4`='蜥蜴人祭司看穿了我的软弱。那些暴徒殴打我，骂我是“短牙种”。要不是有我的蛇蜥保护我，我会很孤单的。$b$b生不如死。', `MaleText_loc5`='魔龍祭司看出了我的弱點，大塊頭毆打我、侮辱我是短牙。我沒有石化蜥蜴保護我，我只有自己...$b$b...很容易死。', `MaleText_loc7`='Los sacerdotes saurios han visto mi debilidad. Los toscos me golpean y me llaman colmillochico. Si no tuviese a mi basilisco para que me protegiese, estaría solo.$b$bY probablemente muerto.' WHERE `ID`=71483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='굳이 몸을 숙여서 나랑 이야기해 주는 거예요? 애완동물이나 키우는 짧은니랑?$b$b나는 내 주제를 알아요, 강한 자. 나는 혼자 싸울 만큼 강하지 않아서 애완동물을 키워요. 다들 나더러 약하다고 하고, 날 마을 변두리로 밀어내죠.$b$b누가 보기 전에 가는 게 좋을 거예요.', `MaleText_loc4`='你竟然屈尊跟我说话？跟一个带宠者？一个短牙种？$b$b我知道自己在这个世界上的位置，强者。我不够强壮，不能单打独斗，所以我养了一头宠物来保护我。我被叫做弱者，被赶到村子的边缘来。$b$b你该离我远点儿，别被他们看见了。', `MaleText_loc5`='你願意跟我講話?跟有養寵物的我講話?跟短牙的我講話?$b$b我知道我的地位，強者。我不夠強壯、沒辦法自己作戰，所以我要養寵物。大家罵我弱，把我趕到村莊的邊邊。$b$b最好離我遠一點，別讓他們看見。', `MaleText_loc7`='¿Te rebajas a hablar conmigo? ¿Con un cuidador de mascotas? ¿Con un colmillochico?$b$bConozco mi lugar en el mundo, fuerte. No soy lo bastante fuerte para luchar solo, así que tengo una mascota. Me llaman débil y me echan a las afueras de la aldea.$b$bNo deberías acercarte a mí, debes evitar que te vean conmigo.' WHERE `ID`=71484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐죠, 강한 자?', `MaleText_loc4`='你好，强者。', `MaleText_loc5`='更強壯的，有事?', `MaleText_loc7`='¿Sí, fuerte?' WHERE `ID`=71485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 아무것도 아니에요. 난 보잘것없어요. 난 약해요.$b$b난 아무것도 아니에요. 난 보잘것없어요. 난 약해요.$b$b난 아무것도 아니에요...', `MaleText_loc4`='我一无是处，我是废物，我是弱者。$b$b我一无是处，我是废物，我是弱者……$b$b我是弱者……', `MaleText_loc5`='我沒有名字沒有身份，我是弱者。$b$b我沒有名字沒有身份，我是弱者。$b$b我沒有名字...', `MaleText_loc7`='No soy nada. Estoy solo. Soy débil.$b$bNo soy nada. No soy nadie. Soy débil.$b$bNo soy nada...' WHERE `ID`=71486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짧은니도 강해질 수는 있어요. 원한다면 부족에게 멸시 당하는 신세를 벗어날 수도 있죠.$b$b방법은 있어요... 하지만 무서워요. 난 너무 겁이 많고 너무 약해요.$b$b남들은 몰라요. 난 평생 짧은니일 거예요.', `MaleText_loc4`='短牙种也是可以变强的。如果我愿意，我也可以摆脱族人对我的嘲笑。$b$b办法是有的……可我害怕。我太害怕，太软弱了。$b$b他们不理解我。我要当一辈子的短牙种。', `MaleText_loc5`='有幾個方法可以讓短牙齒變強壯，我真的想的話，還是可以脫離族人的恥笑。$b$b雖然有幾個辦法... 但是我太害怕，太膽小，太弱了。$b$b他們不瞭解我...我一輩子都只能當短牙齒的。', `MaleText_loc7`='Existen formas de que un colmillochico se vuelva más fuerte. Si quisiera, podría librarme del desprecio de mi tribu.$b$bExisten formas... pero tengo miedo. Soy demasiado cobarde y demasiado débil.$b$bEllos no me entienden. Seré un colmillochico toda mi vida.' WHERE `ID`=71487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<겁에 질려 움찔하는 짧은니>', `MaleText_loc4`='<这个短牙种恐惧地瑟缩着。>', `MaleText_loc5`='<短牙齒害怕的縮成一團。>', `MaleText_loc7`='<El colmillochico retrocede asustado.>' WHERE `ID`=71488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조용해라, 멍청한 것! 크로쉬크가 온다!', `MaleText_loc4`='闭嘴，蠢货！考什克过来了！', `MaleText_loc5`='笨蛋，快安靜!克羅西克來了!', `MaleText_loc7`='¡Silencio, torpe! ¡Kroshik se acerca!' WHERE `ID`=71489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<말 없이 경외감에 무릎을 꿇는 사우록>', `MaleText_loc4`='<蜥蜴人沉默而敬畏地跪下了。>', `MaleText_loc5`='<薩烏洛克默默而崇拜地下跪。>', `MaleText_loc7`='<El saurok se arrodilla mostrando una veneración silenciosa.>' WHERE `ID`=71490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='존경심을 보여라, 사우록. 크로쉬크가 안 보이나?', `MaleText_loc4`='放尊重点，蜥蜴人。你没看见考什克吗？', `MaleText_loc5`='展現出你的敬意，薩烏洛克。難道你沒看見克羅西克嗎?', `MaleText_loc7`='Muestra respeto, saurok. ¿No ves a Kroshik?' WHERE `ID`=71491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 닥치고 무릎 꿇어라, 멍청한 것. 크로쉬크가 가까이 있다.', `MaleText_loc4`='闭上你的嘴，立刻跪下，蠢货。考什克就在附近。', `MaleText_loc5`='閉嘴跪下，你這笨蛋。克羅西克就在附近。', `MaleText_loc7`='Cierra la boca y arrodíllate, torpe. Kroshik está cerca.' WHERE `ID`=71492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크의 살점을 먹고, 나약함을 씻어 버려라.', `MaleText_loc4`='享用考什克的血肉，净化你的软弱。', `MaleText_loc5`='吃下克羅西克的肉，除掉你的軟弱。', `MaleText_loc7`='Come la carne de Kroshik, y purifícate de tu debilidad.' WHERE `ID`=71493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크의 살점이 우리의 양식이 되고, 우리에게 힘을 줄 것이다. 그의 썩어가는 내장은 오물 구덩이에 던져져, 침입자에게서 우리를 지킬 것이다. 그의 뼈는 우리의 보금자리가 될 것이다. 그의 씨앗은 순환을 끝없이 계속할 것이다.$b$b크로쉬크에 언제나 힘을. 부랑칼날에 언제나 힘을.', `MaleText_loc4`='他的血肉滋养了我们，赐予我们力量。他腐烂的内脏将被扔进污水池，保护我们不受入侵者袭扰。他的骨骼将被建成我们的房屋。他的种子将延续永恒的轮回。$b$b力量与考什克同在。力量与邪刃部族同在。', `MaleText_loc5`='他的血肉餵養我們，給我們力量。他腐爛的內臟會被扔進穢物池，保護我們不受入侵者的攻擊。他的骨頭會建造我們的家，他的種子會無限循環輪迴。$b$b克羅西克的力量是永恆的，污刃族的力量是永恆的。', `MaleText_loc7`='Su carne nos alimentará y nos dará fortaleza. Lanzaremos sus entrañas en descomposición a la poza de basura y nos protegerán de los intrusos. Sus huesos servirán para construir nuestras casas. Su semilla continuará el ciclo indefinidamente.$b$bFuerza para Kroshik siempre. Fuerza para los Hojaescoria siempre.' WHERE `ID`=71494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크다!', `MaleText_loc4`='考什克！', `MaleText_loc5`='克羅西克!', `MaleText_loc7`='¡Kroshik!' WHERE `ID`=71495;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부랑칼날에 언제나 힘을!', `MaleText_loc4`='力量与邪刃部族同在！', `MaleText_loc5`='污刃族永遠強壯!', `MaleText_loc7`='¡Fuerza siempre para los Hojaescoria!' WHERE `ID`=71496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000북서쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000西北部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000西北|r方的風口已打開，引起了|cFFFF0000|Hspell:136889|h[劇烈強風]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_nature_lightningoverload.blp:20|t Las puertas del |cFFFF0000noroeste|r comienzan a abrirse, lo que provoca |cFFFF0000|Hspell:136889|h[Vendavales violentos]|h|r.' WHERE `ID`=71497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무쇠군주 모노한이 회전 공격을 준비합니다!', `MaleText_loc4`='金铁领主莫诺汗正在准备回旋击！', `MaleText_loc5`='冶煉統領魔諾汗準備施展旋風攻擊!', `MaleText_loc7`='¡El señor del metal Mono-Han prepara un Ataque de torbellino!', `FemaleText_loc1`='무쇠군주 모노한이 회전 공격을 준비합니다!', `FemaleText_loc4`='金铁领主莫诺汗正在准备回旋击！', `FemaleText_loc5`='冶煉統領魔諾汗準備施展旋風攻擊!', `FemaleText_loc7`='¡El señor del metal Mono-Han prepara un Ataque de torbellino!' WHERE `ID`=71498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='군주 구라는 손가락 끝으로 엄청난 힘을 가진 폭풍을 휘둘렀습니다. 그는 말 한마디만으로도 대지를 강력한 전류로 뒤덮을 수 있었습니다. 그의 폭풍 안에 갇힌 이는 끔찍하게 몸이 타들어가는 고통 속에 목숨을 잃었습니다.', `MaleText_loc4`='军阀古拉能将风暴的力量玩弄于股掌之间。只要一个指令，他就能让劈啪作响的电流笼罩大地。那些被他卷入风暴中的人都会浑身焦黑地凄惨死去。', `MaleText_loc5`='古拉領主擅長操縱暴風雨的狂暴威力。只要一句咒語，雷霆便以萬鈞之勢，籠罩大地。為雷電擊中的人們，全身焚灼致死，形狀極為悽慘。', `MaleText_loc7`='Lord Gura dominaba el poder de la tormenta. Con una sola palabra suya, podía abrasar la tierra con descargas eléctricas. Todos los que se vieran atrapados en su tormenta morían terriblemente calcinados.', `FemaleText_loc1`='군주 구라는 손가락 끝으로 엄청난 힘을 가진 폭풍을 휘둘렀습니다. 그는 말 한마디만으로도 대지를 강력한 전류로 뒤덮을 수 있었습니다. 그의 폭풍 안에 갇힌 이는 끔찍하게 몸이 타들어가는 고통 속에 목숨을 잃었습니다.', `FemaleText_loc4`='军阀古拉能将风暴的力量玩弄于股掌之间。只要一个指令，他就能让劈啪作响的电流笼罩大地。那些被他卷入风暴中的人都会浑身焦黑地凄惨死去。', `FemaleText_loc5`='古拉領主擅長操縱暴風雨的狂暴威力。只要一句咒語，雷霆便以萬鈞之勢，籠罩大地。為雷電擊中的人們，全身焚灼致死，形狀極為悽慘。', `FemaleText_loc7`='Lord Gura dominaba el poder de la tormenta. Con una sola palabra suya, podía abrasar la tierra con descargas eléctricas. Todos los que se vieran atrapados en su tormenta morían terriblemente calcinados.' WHERE `ID`=71500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 놈 같으니!', `MaleText_loc4`='蠢东西！', `MaleText_loc5`='笨東西!', `MaleText_loc7`='¡Bicho eh''túpido!' WHERE `ID`=71501;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽음과 위험, 그리고 잔달라의 귀환과 그들의 마법이라... 정말 흥미롭네요.', `FemaleText_loc4`='死亡，危机，赞达拉携带他们的魔法再次归来。真刺激！', `FemaleText_loc5`='死亡、危機，贊達拉的歸來，還有他們的魔法...真是太刺激了!', `FemaleText_loc7`='Muerte, peligro, el regreso de los Zandalari y su magia. ¡Qué emocionante!' WHERE `ID`=71502;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토가 달라란을 차치해도 전 별로 상관 안 한답니다. 바로 이곳이 가장 저의 고향 같이 느껴지는 곳이니까요. 싸움이 한참 격렬한 바로 그때 말이죠!', `FemaleText_loc4`='肯瑞托可以留着他们的达拉然，我才不在乎。这才是最合适我的地方，在白热化的战斗中深入敌后！', `FemaleText_loc5`='祈倫托拿走達拉然就拿吧。這裡才是我最自在的地方－在敵陣後方、在戰火最熾烈的地方!', `FemaleText_loc7`='El Kirin Tor puede quedarse con Dalaran; me importa un bledo. Aquí me siento en casa, tras las líneas enemigas, ¡en medio de los acontecimientos!' WHERE `ID`=71504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수은 수액이 무쇠군주 모노한의 칼에서 떨어졌습니다! 처치해서 힘을 흡수하십시오!', `MaleText_loc4`='水银污泥怪从他的刀刃上滴落下来！快杀死污泥怪以吸收它们的力量！', `MaleText_loc5`='水銀從他的刀刃上滴下來了!殺掉水銀怪，吸收他們的力量!', `MaleText_loc7`='¡El mercurio cae de sus hojas! ¡Acaba con las masas para absorber su poder!', `FemaleText_loc1`='수은 수액이 무쇠군주 모노한의 칼에서 떨어졌습니다! 처치해서 힘을 흡수하십시오!', `FemaleText_loc4`='水银污泥怪从他的刀刃上滴落下来！快杀死污泥怪以吸收它们的力量！', `FemaleText_loc5`='水銀從他的刀刃上滴下來了!殺掉水銀怪，吸收他們的力量!', `FemaleText_loc7`='¡El mercurio cae de sus hojas! ¡Acaba con las masas para absorber su poder!' WHERE `ID`=71506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 친구. 덕분에 끔찍한 최후를 맞지 않았습니다.', `MaleText_loc4`='谢谢你，朋友。你将我从可怕的命运中救了出来。', `MaleText_loc5`='謝謝你，朋友。你救了我免於可怕的下場。', `MaleText_loc7`='Gracias. Me has salvado de un destino terrible.', `FemaleText_loc1`='고마워요, 친구. 덕분에 끔찍한 최후를 맞지 않았네요.', `FemaleText_loc4`='谢谢你，朋友。你将我从可怕的命运中救了出来。', `FemaleText_loc5`='謝謝你，朋友。你救了我免於可怕的下場。', `FemaleText_loc7`='Gracias. Me has salvado de un destino terrible.' WHERE `ID`=71507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버가 보냈습니까? 늦기 전에 구해 주셔서 고맙습니다.', `MaleText_loc4`='是夺日者派你来的吗？感谢你的及时搭救。', `MaleText_loc5`='你是奪日者派來的?感謝你的及時營救。', `MaleText_loc7`='¿Te envían los Atracasol? Gracias por rescatarme tan a tiempo.', `FemaleText_loc1`='선리버가 보냈나요? 늦기 전에 구해 주셔서 고마워요.', `FemaleText_loc4`='是夺日者派你来的吗？感谢你的及时搭救。', `FemaleText_loc5`='你是奪日者派來的?感謝你的及時營救。', `FemaleText_loc7`='¿Te envían los Atracasol? Gracias por rescatarme tan a tiempo.' WHERE `ID`=71508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 야영지까지는 혼자 갈 수 있습니다.', `MaleText_loc4`='谢谢你。现在我可以自己回营地去了。', `MaleText_loc5`='謝謝你，接下來我能自己回去營地了。', `MaleText_loc7`='Gracias. Puedo encontrar el camino de vuelta al campamento solo desde aquí.', `FemaleText_loc1`='고마워요. 야영지까지는 혼자 갈 수 있어요.', `FemaleText_loc4`='谢谢你。现在我可以自己回营地去了。', `FemaleText_loc5`='謝謝你，接下來我能自己回去營地了。', `FemaleText_loc7`='Gracias. Puedo encontrar el camino de vuelta al campamento sola desde aquí.' WHERE `ID`=71509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 용사님. 부디 다른 이들도 구해 주십시오!', `MaleText_loc4`='谢谢你，勇士。请你也救救其他人吧！', `MaleText_loc5`='謝謝你，勇士。請你也去救救其他人!', `MaleText_loc7`='Muchas gracias. ¡Por favor, libera también a los demás!', `FemaleText_loc1`='고마워요, 용사님. 부디 다른 이들도 구해 주세요!', `FemaleText_loc4`='谢谢你，勇士。请你也救救其他人吧！', `FemaleText_loc5`='謝謝你，勇士。請你也去救救其他人!', `FemaleText_loc7`='Muchas gracias. ¡Por favor, libera también a los demás!' WHERE `ID`=71510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 어찌 이리도 극악무도한 걸까요? 지금 와 주셨기에 천만다행이지요.', `MaleText_loc4`='魔古族怎能如此残暴？多亏你及时赶到。', `MaleText_loc5`='魔古竟然這麼殘酷無情?謝謝你及時來救我們。', `MaleText_loc7`='¿Cómo es posible que los mogu llevasen a cabo tal atrocidad? Menos mal que llegaste a tiempo.', `FemaleText_loc1`='모구는 어찌 이리도 극악무도한 걸까요? 지금 와 주셨기에 천만다행이지요.', `FemaleText_loc4`='魔古族怎能如此残暴？多亏你及时赶到。', `FemaleText_loc5`='魔古竟然這麼殘酷無情?謝謝你及時來救我們。', `FemaleText_loc7`='¿Cómo es posible que los mogu llevasen a cabo tal atrocidad? Menos mal que llegaste a tiempo.' WHERE `ID`=71511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜 잊지 않겠습니다, 영웅님.', `MaleText_loc4`='我真是感激不尽，英雄。', `MaleText_loc5`='我對你感激不盡，英雄。', `MaleText_loc7`='Cuentas con mi gratitud eterna.', `FemaleText_loc1`='이 은혜 잊지 않을게요, 영웅님.', `FemaleText_loc4`='我真是感激不尽，英雄。', `FemaleText_loc5`='我對你感激不盡，英雄。', `FemaleText_loc7`='Cuentas con mi gratitud eterna.' WHERE `ID`=71512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생명의 은인이십니다, 용사님. 큰 빚을 졌군요.', `MaleText_loc4`='你救了我的命，勇士。我欠你一份人情。', `MaleText_loc5`='勇士，謝謝你救我一命，我一定會報答你的。', `MaleText_loc7`='Me has salvado la vida. Estoy en deuda contigo.', `FemaleText_loc1`='제 생명의 은인이세요, 용사님. 큰 빚을 졌네요.', `FemaleText_loc4`='你救了我的命，勇士。我欠你一份人情。', `FemaleText_loc5`='勇士，謝謝你救我一命，我一定會報答你的。', `FemaleText_loc7`='Me has salvado la vida. Estoy en deuda contigo.' WHERE `ID`=71513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 서약단이 보냈습니까? 늦기 전에 구해 주셔서 고맙습니다.', `MaleText_loc4`='是银色盟约派你来的吗？感谢你的及时搭救。', `MaleText_loc5`='是白銀誓盟派你來的?感謝你的及時相救。', `MaleText_loc7`='¿Te envía El Pacto de Plata? Muchas gracias por el oportuno rescate.', `FemaleText_loc1`='은빛 서약단이 보냈나요? 늦기 전에 구해 주셔서 고마워요.', `FemaleText_loc4`='是银色盟约派你来的吗？感谢你的及时搭救。', `FemaleText_loc5`='是白銀誓盟派你來的?感謝你的及時相救。', `FemaleText_loc7`='¿Te envía El Pacto de Plata? Muchas gracias por el oportuno rescate.' WHERE `ID`=71514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은빛 서약단이 절 저버리지 않을 줄 알았습니다. 감사합니다, 용사님.', `MaleText_loc4`='我就知道银色盟约不会抛弃我的。谢谢你，勇士。', `MaleText_loc5`='我就知道白銀誓盟不會捨棄我們。謝謝你，勇士。', `MaleText_loc7`='Sabía que El Pacto de Plata no me abandonaría. Muchas gracias.', `FemaleText_loc1`='은빛 서약단이 절 저버리지 않을 줄 알았어요. 감사해요, 용사님.', `FemaleText_loc4`='我就知道银色盟约不会抛弃我的。谢谢你，勇士。', `FemaleText_loc5`='我就知道白銀誓盟不會捨棄我們。謝謝你，勇士。', `FemaleText_loc7`='Sabía que El Pacto de Plata no me abandonaría. Muchas gracias.' WHERE `ID`=71515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버가 절 저버리지 않을 줄 알았습니다. 감사합니다, 용사님.', `MaleText_loc4`='我就知道夺日者不会抛弃我的。谢谢你，勇士。', `MaleText_loc5`='我就知道奪日者不會捨棄我們。謝謝你，勇士。', `MaleText_loc7`='Sabía que los Atracasol no me abandonarían. Muchas gracias.', `FemaleText_loc1`='선리버가 절 저버리지 않을 줄 알았어요. 감사해요, 용사님.', `FemaleText_loc4`='我就知道夺日者不会抛弃我的。谢谢你，勇士。', `FemaleText_loc5`='我就知道奪日者不會捨棄我們。謝謝你，勇士。', `FemaleText_loc7`='Sabía que los Atracasol no me abandonarían. Muchas gracias.' WHERE `ID`=71516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼라이언스 쓰레기! 널 찢어 버리고 싶지만 이번에만 참겠다.', `MaleText_loc4`='我真该把你撕成碎片，联盟的人渣！这次我就饶你一命。', `MaleText_loc5`='我應該要把你撕成碎片的，聯盟的廢物!但這回我姑且饒你一次。', `MaleText_loc7`='¡Debería hacerte pedazos, escoria de la Alianza! Pero me controlaré por esta vez.', `FemaleText_loc1`='이 얼라이언스 쓰레기! 널 찢어 버리고 싶지만 이번에만 참겠다.', `FemaleText_loc4`='我真该把你撕成碎片，联盟的人渣！这次我就饶你一命。', `FemaleText_loc5`='我應該要把你撕成碎片的，聯盟的廢物!但這回我姑且饒你一次。', `FemaleText_loc7`='¡Debería hacerte pedazos, escoria de la Alianza! Pero me controlaré por esta vez.' WHERE `ID`=71517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 참도록 하지, 얼라이언스 영웅. 선리버가 고마움을 모른다고는 하지 말기를.', `MaleText_loc4`='我就饶你一次，联盟的英雄。免得让人说夺日者不懂得感恩。', `MaleText_loc5`='這回我就不動手了，聯盟的英雄。別說奪日者的人都不知道感恩。', `MaleText_loc7`='Me controlaré por esta vez, miembro de la Alianza. Que no se diga que los Atracasol no muestran gratitud.', `FemaleText_loc1`='이번에는 참도록 하지, 얼라이언스 영웅. 선리버가 고마움을 모른다고는 하지 말기를.', `FemaleText_loc4`='我就饶你一次，联盟的英雄。免得让人说夺日者不懂得感恩。', `FemaleText_loc5`='這回我就不動手了，聯盟的英雄。別說奪日者的人都不知道感恩。', `FemaleText_loc7`='Me controlaré por esta vez, miembro de la Alianza. Que no se diga que los Atracasol no muestran gratitud.' WHERE `ID`=71518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 방금 날 죽음으로부터 구하지 않았다면, 서 있는 자리에서 바로 죽였을 것이다. 다음에 만나면 그냥 두지 않겠다.', `MaleText_loc4`='要不是你救了我一命，我一定立刻杀了你。下次再见时，我可不会手下留情。', `MaleText_loc5`='要不是你救了我一命，我肯定要當場殺了你。下回再相見的時候，我可不會有所保留。', `MaleText_loc7`='Si no me acabases de salvar de una muerte segura, te mataría ahora mismo. La próxima vez que nos veamos no seré tan generoso.', `FemaleText_loc1`='네가 방금 날 죽음으로부터 구하지 않았다면, 서 있는 자리에서 바로 죽였을 거야. 다음에 만나면 그냥 두지 않겠어.', `FemaleText_loc4`='要不是你救了我一命，我一定立刻杀了你。下次再见时，我可不会手下留情。', `FemaleText_loc5`='要不是你救了我一命，我肯定要當場殺了你。下回再相見的時候，我可不會有所保留。', `FemaleText_loc7`='Si no me acabases de salvar de una muerte segura, te mataría ahora mismo. La próxima vez que nos veamos no seré tan generosa.' WHERE `ID`=71519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 적이지만, 이번만큼은 감사를 표하지.', `MaleText_loc4`='虽然我们是敌人，但我还是要谢谢你。只此一次，下不为例。', `MaleText_loc5`='雖然我們是敵人，但我還是要謝謝你。僅此一次、下不為例。', `MaleText_loc7`='Te lo agradezco, a pesar de que seas de la facción enemiga. Pero solo por esta vez.', `FemaleText_loc1`='우리는 적이지만, 이번만큼은 감사를 표하죠.', `FemaleText_loc4`='虽然我们是敌人，但我还是要谢谢你。只此一次，下不为例。', `FemaleText_loc5`='雖然我們是敵人，但我還是要謝謝你。僅此一次、下不為例。', `FemaleText_loc7`='Te lo agradezco, a pesar de que seas de la facción enemiga. Pero solo por esta vez.' WHERE `ID`=71520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군, 얼라이언스 영웅. 하지만 다음에 만나면 자비는 없다.', `MaleText_loc4`='谢谢你，联盟的英雄。但下次见面时，我还是不会对你手软的。', `MaleText_loc5`='謝謝你，聯盟的英雄。但下次再見的時候，可就無法手下留情了。', `MaleText_loc7`='Gracias, miembro de la Alianza, pero la próxima vez no mostraré piedad.', `FemaleText_loc1`='고맙군요, 얼라이언스 영웅. 하지만 다음에 만나면 자비는 없어요.', `FemaleText_loc4`='谢谢你，联盟的英雄。但下次见面时，我还是不会对你手软的。', `FemaleText_loc5`='謝謝你，聯盟的英雄。但下次再見的時候，可就無法手下留情了。', `FemaleText_loc7`='Gracias, miembro de la Alianza, pero la próxima vez no mostraré piedad.' WHERE `ID`=71521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙군, 호드 영웅. 하지만 다음에 만나면 자비는 없다.', `MaleText_loc4`='谢谢你，部落的英雄。但下次见面时，我还是不会对你手软的。', `MaleText_loc5`='謝謝你，部落的英雄。但下次再見的時候，我可不會手下留情。', `MaleText_loc7`='Gracias, miembro de la Horda, pero si nos volvemos a ver, no mostraré piedad.', `FemaleText_loc1`='고맙군요, 호드 영웅. 하지만 다음에 만나면 자비는 없어요.', `FemaleText_loc4`='谢谢你，部落的英雄。但下次见面时，我还是不会对你手软的。', `FemaleText_loc5`='謝謝你，部落的英雄。但下次再見的時候，我可不會手下留情。', `FemaleText_loc7`='Gracias, miembro de la Horda, pero si nos volvemos a ver, no mostraré piedad.' WHERE `ID`=71522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번에는 참도록 하지, 호드 영웅. 은빛 서약단이 고마움을 모른다고는 하지 말기를.', `MaleText_loc4`='我就饶你一次，部落的英雄。免得让人说银色盟约不懂得感恩。', `MaleText_loc5`='這回我就不動手了，部落的英雄。別說白銀誓盟的人都不知道感恩。', `MaleText_loc7`='Me controlaré por esta vez, miembro de la Horda. Que no se diga que el Pacto de la Plata no muestra gratitud.', `FemaleText_loc1`='이번에는 참도록 하지, 호드 영웅. 은빛 서약단이 고마움을 모른다고는 하지 말기를.', `FemaleText_loc4`='我就饶你一次，部落的英雄。免得让人说银色盟约不懂得感恩。', `FemaleText_loc5`='這回我就不動手了，部落的英雄。別說白銀誓盟的人都不知道感恩。', `FemaleText_loc7`='Me controlaré por esta vez, miembro de la Horda. Que no se diga que el Pacto de la Plata no muestra gratitud.' WHERE `ID`=71523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호드 쓰레기! 널 찢어 버리고 싶지만 이번에만 참겠다.', `MaleText_loc4`='我真该把你撕成碎片，部落的人渣！这次我就饶你一命。', `MaleText_loc5`='我應該要把你剁成肉醬的，部落的垃圾!這次我姑且饒你一命。', `MaleText_loc7`='¡Debería hacerte pedazos, escoria de la Horda! Pero me controlaré por esta vez.', `FemaleText_loc1`='이 호드 쓰레기! 널 찢어 버리고 싶지만 이번에만 참겠다.', `FemaleText_loc4`='我真该把你撕成碎片，部落的人渣！这次我就饶你一命。', `FemaleText_loc5`='我應該要把你剁成肉醬的，部落的垃圾!這次我姑且饒你一命。', `FemaleText_loc7`='¡Debería hacerte pedazos, escoria de la Horda! Pero me controlaré por esta vez.' WHERE `ID`=71524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 방금 날 죽음으로부터 구하지 않았다면, 서 있는 자리에서 바로 죽였을 것이다. 다음에 만나면 그냥 두지 않겠다.', `MaleText_loc4`='要不是你救了我一命，我一定立刻杀了你。下次再见时，我可不会手下留情。', `MaleText_loc5`='要不是你救了我一命，我肯定要當場殺了你。但下回再相見的時候，我可不會有所保留。', `MaleText_loc7`='Si no me acabases de salvar de una muerte segura, te mataría ahora mismo. La próxima vez que nos veamos no seré tan generoso.', `FemaleText_loc1`='네가 방금 날 죽음으로부터 구하지 않았다면, 서 있는 자리에서 바로 죽였을 거야. 다음에 만나면 그냥 두지 않겠어.', `FemaleText_loc4`='要不是你救了我一命，我一定立刻杀了你。下次再见时，我可不会手下留情。', `FemaleText_loc5`='要不是你救了我一命，我肯定要當場殺了你。但下回再相見的時候，我可不會有所保留。', `FemaleText_loc7`='Si no me acabases de salvar de una muerte segura, te mataría ahora mismo. La próxima vez que nos veamos no seré tan generosa.' WHERE `ID`=71525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 적이지만, 이번만큼은 감사를 표하지.', `MaleText_loc4`='虽然我们是敌人，但我还是要谢谢你。只此一次，下不为例。', `MaleText_loc5`='雖然我們是敵人，但我還是要謝謝你。僅此一次、下不為例。', `MaleText_loc7`='Te lo agradezco, a pesar de que seas de la facción enemiga. Pero solo por esta vez.', `FemaleText_loc1`='우리는 적이지만, 이번만큼은 감사를 표하죠.', `FemaleText_loc4`='虽然我们是敌人，但我还是要谢谢你。只此一次，下不为例。', `FemaleText_loc5`='雖然我們是敵人，但我還是要謝謝你。僅此一次、下不為例。', `FemaleText_loc7`='Te lo agradezco, a pesar de que seas de la facción enemiga. Pero solo por esta vez.' WHERE `ID`=71526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다. 야영지까지는 혼자 갈 수 있습니다.', `MaleText_loc4`='谢谢你。现在我可以自己回营地去了。', `MaleText_loc5`='謝謝你，接下來我能自己回營地。', `MaleText_loc7`='Gracias. Puedo encontrar el camino de vuelta al campamento solo desde aquí.', `FemaleText_loc1`='고마워요. 야영지까지는 혼자 갈 수 있어요.', `FemaleText_loc4`='谢谢你。现在我可以自己回营地去了。', `FemaleText_loc5`='謝謝你，接下來我能自己回營地。', `FemaleText_loc7`='Gracias. Puedo encontrar el camino de vuelta al campamento sola desde aquí.' WHERE `ID`=71527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙습니다, 용사님. 부디 다른 이들도 구해 주십시오!', `MaleText_loc4`='谢谢你，勇士。请你也救救其他人吧！', `MaleText_loc5`='謝謝你，勇士。請你也去救救其他人!', `MaleText_loc7`='Muchas gracias. ¡Por favor, libera también a los demás!', `FemaleText_loc1`='고마워요, 용사님. 부디 다른 이들도 구해 주세요!', `FemaleText_loc4`='谢谢你，勇士。请你也救救其他人吧！', `FemaleText_loc5`='謝謝你，勇士。請你也去救救其他人!', `FemaleText_loc7`='Muchas gracias. ¡Por favor, libera también a los demás!' WHERE `ID`=71528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 어찌 이리도 극악무도한 걸까요? 지금 와 주셨기에 천만다행이지요.', `MaleText_loc4`='魔古族怎能如此残暴？多亏你及时赶到。', `MaleText_loc5`='魔古竟然這麼殘酷無情?謝謝你及時來救我們。', `MaleText_loc7`='¿Cómo es posible que los mogu llevasen a cabo tal atrocidad? Menos mal que llegaste a tiempo.', `FemaleText_loc1`='모구는 어찌 이리도 극악무도한 걸까요? 지금 와 주셨기에 천만다행이지요.', `FemaleText_loc4`='魔古族怎能如此残暴？多亏你及时赶到。', `FemaleText_loc5`='魔古竟然這麼殘酷無情?謝謝你及時來救我們。', `FemaleText_loc7`='¿Cómo es posible que los mogu llevasen a cabo tal atrocidad? Menos mal que llegaste a tiempo.' WHERE `ID`=71529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 은혜 잊지 않겠습니다, 영웅님.', `MaleText_loc4`='我真是感激不尽，英雄。', `MaleText_loc5`='我對你感激不盡，英雄。', `MaleText_loc7`='Cuentas con mi gratitud eterna.', `FemaleText_loc1`='이 은혜 잊지 않겠어요, 영웅님.', `FemaleText_loc4`='我真是感激不尽，英雄。', `FemaleText_loc5`='我對你感激不盡，英雄。', `FemaleText_loc7`='Cuentas con mi gratitud eterna.' WHERE `ID`=71530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다, 친구. 덕분에 끔찍한 최후를 맞지 않았습니다.', `MaleText_loc4`='谢谢你，朋友。你将我从可怕的命运中救了出来。', `MaleText_loc5`='謝謝你，朋友。你救了我免於可怕的下場。', `MaleText_loc7`='Muchas gracias. Me has salvado de un destino terrible.', `FemaleText_loc1`='고마워요, 친구. 덕분에 끔찍한 최후를 맞지 않았네요.', `FemaleText_loc4`='谢谢你，朋友。你将我从可怕的命运中救了出来。', `FemaleText_loc5`='謝謝你，朋友。你救了我免於可怕的下場。', `FemaleText_loc7`='Muchas gracias. Me has salvado de un destino terrible.' WHERE `ID`=71531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 생명의 은인이십니다, 용사님. 큰 빚을 졌군요.', `MaleText_loc4`='你救了我的命，勇士。我欠你一份人情。', `MaleText_loc5`='勇士，謝謝你救我一命，我一定會報答你的。', `MaleText_loc7`='Me has salvado la vida. Estoy en deuda contigo.', `FemaleText_loc1`='제 생명의 은인이세요, 용사님. 큰 빚을 졌네요.', `FemaleText_loc4`='你救了我的命，勇士。我欠你一份人情。', `FemaleText_loc5`='勇士，謝謝你救我一命，我一定會報答你的。', `FemaleText_loc7`='Me has salvado la vida. Estoy en deuda contigo.' WHERE `ID`=71532;
