UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부랑칼날에 언제나 힘을!', `MaleText_loc4`='力量与邪刃部族同在！', `MaleText_loc5`='力量與污刃族同在!', `MaleText_loc7`='¡Fuerza para los Hojaescoria siempre!' WHERE `ID`=71534;
