UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오물 훔치러 왔냐?', `MaleText_loc4`='你想偷我们的污物吗？', `MaleText_loc5`='你跑來偷我們的髒東西?', `MaleText_loc7`='¿Vienes a robar nuestra basura?' WHERE `ID`=71539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 시체를 오물 웅덩이에 던질 거다!', `MaleText_loc4`='我要把你的尸体扔进污水池！', `MaleText_loc5`='我要把你的屍體丟進穢物池!', `MaleText_loc7`='¡Lanzaré tu cadáver a nuestra poza de basura!' WHERE `ID`=71540;
