UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 바라는 게 뭐야?', `MaleText_loc4`='你想对我做什么？', `MaleText_loc5`='找我有什麼事?', `MaleText_loc7`='¿Qué quieres de mí?' WHERE `ID`=71543;
