UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로쉬크시여! 여기 대체 어떻게 온 거냐?!', `MaleText_loc4`='考什克之牙在上，你怎么进来的？！', `MaleText_loc5`='克羅西克的牙齒啊，你是怎麼進來這裡的?!', `MaleText_loc7`='¡Por los colmillos de Kroshik! ¿Cómo has llegado hasta aquí?' WHERE `ID`=71548;
