UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로스여, 제게 힘을...', `MaleText_loc4`='克洛斯，赐予我力量……', `MaleText_loc5`='克羅斯，賜給我力量...', `MaleText_loc7`='Kros, dame fuerza...' WHERE `ID`=71550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꺼져라, 겁쟁이...', `MaleText_loc4`='我诅咒你，懦夫……', `MaleText_loc5`='懦夫，我詛咒你...', `MaleText_loc7`='Te maldigo, cobarde.' WHERE `ID`=71551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 냄새가 났는데...', `MaleText_loc4`='我就说有什么味道……', `MaleText_loc5`='我就知道我聞到了不對勁的東西...', `MaleText_loc7`='Sabía que había olido algo...' WHERE `ID`=71552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='후회할 거다...', `MaleText_loc4`='你会后悔的……', `MaleText_loc5`='你會後悔的...', `MaleText_loc7`='Te arrepentirás de esto...' WHERE `ID`=71553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최근에는 좀 바빴습니다. 공룡사제 몇몇이 호드와 얼라이언스의 피를 요구했거든요.$b$b그래서 놈들이 잠자는 사이에 처치했지요.', `MaleText_loc4`='我一直很忙。一些蜥首牧师想让部落和联盟流血。$b$b理所当然的，我就趁他们睡觉时把他们都杀了。', `MaleText_loc5`='最近有點忙，有幾個魔龍祭司在吵說要看到更多聯盟和部落的血。$b$b當然，我趁他們睡覺的時候把他們給宰了。', `MaleText_loc7`='He estado ocupado. Algunos sacerdotes saurios pidieron derramar sangre de la Horda y de la Alianza.$b$bYo, por supuesto, los maté mientras dormían.' WHERE `ID`=71554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 역겨운 냄새를 풍기는 웅덩이는 처음 봅니다. 오물이 더욱 역겨워져서 바위굴 밖으로 퍼지기 전에 누군가 여기로 불러서 치우게 해야 합니다.', `MaleText_loc4`='我从没见过这么臭的污水池。我们需要找人来清理一下，免得它继续发展并扩散到峭壁外面。', `MaleText_loc5`='穢物池變得比之前又更臭了，我們得弄些人來清理一下，別讓衛生狀況繼續惡化、散佈疾病到峭壁之外的其他地方。', `MaleText_loc7`='La poza de basura está más rancia que nunca. Necesitamos que alguien limpie todo esto antes de que empeore y se extienda fuera del risco.' WHERE `ID`=71555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 종일 "모구를 죽여라"라며 노래를 부르고 있습니다. 에이타스 님이 당신에게 무슨 일을 시키셨는지는 몰라도, 효과가 있는 것 같군요.', `MaleText_loc4`='他们整天都在念叨“杀魔古族”。无论艾萨斯让你做了什么，它都起作用了。', `MaleText_loc5`='他們成天喊著要『殺光魔古』，埃薩派你來真是對了。', `MaleText_loc7`='Han estado coreando: "Muerte a los mogu" todo el día. Sea lo que sea que Aethas te haya mandado hacer, está funcionando.' WHERE `ID`=71556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들은 종일 이갈룩 바위산에서 발견된 모구 무기 이야기를 하고 있습니다.$b$b우리를 추호도 의심하지 않더군요. 계속 그렇게만 해 주십시오.', `MaleText_loc4`='他们整天都在谈论自己在伊瓜鲁克峭壁发现的魔古武器。$b$b他们完全没有怀疑我们。继续加油吧。', `MaleText_loc5`='他們整天談論的都是在伊加路克峭壁找到的魔古武器。$b$b他們完全沒有懷疑到我們身上，你做得很好，繼續保持下去。', `MaleText_loc7`='Llevan todo el día hablando de las armas mogu que han encontrado en el Risco Ihgaluk.$b$bNo sospechan nada. Sigue así.' WHERE `ID`=71557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 파악하기로는, 사우록이 새벽에 모구를 공격하려 합니다.', `MaleText_loc4`='就我收集的情报来看，他们正准备在黎明时分袭击魔古族。', `MaleText_loc5`='就我收集到的情報看來，他們正準備在黎明時分對魔古發動攻擊。', `MaleText_loc7`='Por lo que he podido averiguar, planean atacar a los mogu al alba.' WHERE `ID`=71558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사우록들은 방금 모구를 공격하고 돌아왔습니다. 제가 계속 관찰하겠습니다.', `MaleText_loc4`='这些蜥蜴人刚刚袭击魔古族回来。我会继续观察他们的。', `MaleText_loc5`='這些薩烏洛克剛從攻擊魔古的行動回來，我會繼續觀察他們。', `MaleText_loc7`='Estos saurok acaban de regresar de atacar a los mogu. Seguiré observándolos.' WHERE `ID`=71559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록 지도자가 모구 공격을 취소했습니다. 대신 호드와 얼라이언스를 공격할 계획인 듯합니다.$b$b우리가 개입할 때가 된 것 같군요.', `MaleText_loc4`='蜥蜴人首领已经终止了针对魔古族的袭击，并转而计划攻击部落和联盟。$b$b我们恐怕要有所行动了。', `MaleText_loc5`='薩烏洛克的首領取消了對魔古的攻擊行動，計畫對部落和聯盟展開攻擊。$b$b也許該是介入的時候了。', `MaleText_loc7`='Los líderes saurok han detenido los ataques contra los mogu. En lugar de eso, planean atacar a la Horda y a la Alianza.$b$bTal vez haya llegado el momento de intervenir.' WHERE `ID`=71560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한동안 잠잠하던 사우록이 움직이기 시작했습니다. 드디어 놈들을 부추겨 모구에게 등을 돌리게 할 때가 왔습니다.', `MaleText_loc4`='蜥蜴人最近一直很安静，已经开始有些焦躁。是时候让他们去对付魔古族了。', `MaleText_loc5`='薩烏洛克最近沒什麼動靜，只是變得越來越焦躁不安。引他們去攻擊魔古的時機已經成熟了。', `MaleText_loc7`='Los saurok han estado muy tranquilos últimamente, y empiezan a cansarse. Ha llegado el momento de volverlos contra los mogu.' WHERE `ID`=71561;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='에이타스 님께 사우록들이 오늘은 잠잠하다고 전하세요. 당장은 공격도 없을 거예요.', `FemaleText_loc4`='告诉艾萨斯，今天那些蜥蜴人很消停，没有再发动攻击。', `FemaleText_loc5`='告訴埃薩，薩烏洛克今天沒什麼動靜，沒有發動攻擊的跡象。', `FemaleText_loc7`='Dile a Aethas que los saurok han estado tranquilos hoy. No hay ataques a la vista.' WHERE `ID`=71562;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사우록들이 들떠 있는 걸 보니, 아무래도 뭔가 계획하고 있는 것 같아요. 에이타스 님께서 알고 싶어하실 거예요.', `FemaleText_loc4`='蜥蜴人很不安分，他们正在谋划着什么。艾萨斯会对此感兴趣的。', `FemaleText_loc5`='那些薩烏洛克有些騷動，像是在計畫什麼東西。最好去通報埃薩。', `FemaleText_loc7`='Los saurok están inquietos. Planean algo. Aethas querrá saberlo.' WHERE `ID`=71563;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대마법사님께 이갈룩에서는 만사가 순조롭다고 전해 주세요. 며칠 내로 보고서가 완성될 거예요.', `FemaleText_loc4`='去告诉大法师，就说伊瓜鲁克一切都在掌握之中。我过几天再给他发一份报告。', `FemaleText_loc5`='去報告大法師，伊加路克峭壁這邊一切正常，然後過幾天我會再送份新的報告。', `FemaleText_loc7`='Informa a los archimagos de que todo está bajo control aquí en Ihgaluk. Tendré listo un nuevo informe en unos días.' WHERE `ID`=71564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='청소부들이 곧 늪으로 큰 무리를 파견할지도 몰라요. 대마법사님께 준비해 두시라고 전해 주세요.', `FemaleText_loc4`='看来那些食腐者恐怕很快就要到外面的沼泽去狂欢一番了。去告诉大法师，让他做好准备。', `FemaleText_loc5`='看來這些傢伙可能不久之後就會派出大批人馬進入沼澤。請通報大法師，及早做好準備。', `FemaleText_loc7`='Parece que los carroñeros enviarán una gran partida al marjal pronto. Diles a los archimagos que se preparen.' WHERE `ID`=71565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재가동 중...', `MaleText_loc4`='正在重启……', `MaleText_loc5`='重新啟動...', `MaleText_loc7`='REINICIANDO...' WHERE `ID`=71566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시스템 온라인. 상태 호전됨.', `MaleText_loc4`='系统启动。现在感觉好多了。', `MaleText_loc5`='系統登入。感覺好多了。', `MaleText_loc7`='SISTEMA ACTIVADO. ME SIENTO MUCHO MEJOR.' WHERE `ID`=71567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망신스러운 오작동 복구 시도 중...', `MaleText_loc4`='正在尝试修复令人难堪的故障……', `MaleText_loc5`='嘗試從難堪的故障復原...', `MaleText_loc7`='TRATANDO DE RECUPERARME DE FALLO VERGONZOSO...' WHERE `ID`=71568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복구 실패. 망신살 수치 증가. 기지로 귀환.', `MaleText_loc4`='修复失败。羞愧指数上升。返回基地。', `MaleText_loc5`='復原失敗。丟臉指數升高。返回基地。', `MaleText_loc7`='RECUPERACIÓN FALLIDA. PARÁMETRO DE VERGÜENZA AUMENTANDO. VUELVO A LA BASE.' WHERE `ID`=71569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다리 자가 수리 회로 고장. 기지로 귀환.', `MaleText_loc4`='腿部故障回路破损。返回基地。', `MaleText_loc5`='腿部故障迴圈損毀。返回基地。', `MaleText_loc7`='CICLO DE FALLO EN LA PIERNA ESTROPEADO. VUELVO A LA BASE.' WHERE `ID`=71570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모래 추출 프로토콜 실행.', `MaleText_loc4`='执行挖沙协议。', `MaleText_loc5`='執行抽沙程序。', `MaleText_loc7`='EJECUTANDO PROTOCOLO DE EXTRACCIÓN DE ARENA.' WHERE `ID`=71571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경고: 마나 유속 아직 높음.', `MaleText_loc4`='警告：法力流失速率过高。', `MaleText_loc5`='警告: 法力流速依然過高。', `MaleText_loc7`='ATENCIÓN: VELOCIDAD DE FLUJO DE MANÁ CONTINÚA ELEVADA.' WHERE `ID`=71572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마나 유속 재정의 프로토콜 실행.', `MaleText_loc4`='尝试启动法力流失速率降低改写协议。', `MaleText_loc5`='嘗試法力流速弱化強制程序。', `MaleText_loc7`='INTENTO DE PROTOCOLO MANUAL DE REDUCCIÓN DE VELOCIDAD DE FLUJO DE MANÁ.' WHERE `ID`=71573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"괜찮음"', `MaleText_loc4`='"一切正常"', `MaleText_loc5`='「一切正常」', `MaleText_loc7`='"NO PASA NADA"' WHERE `ID`=71574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"문제 없음"', `MaleText_loc4`='"一切安好"', `MaleText_loc5`='「狀況一切正常」', `MaleText_loc7`='"NO HAY NINGÚN PROBLEMA"' WHERE `ID`=71575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"$N|1이;가; 해결해 줄 것임"', `MaleText_loc4`='"$N会搞定的"', `MaleText_loc5`='「$N會使狀況好轉」', `MaleText_loc7`='"$N HARÁ QUE TODO VAYA BIEN"' WHERE `ID`=71576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마나 유속 정상. 기지로 귀환.', `MaleText_loc4`='法力流失速度正常。返回基地。', `MaleText_loc5`='法力流速過低。返回基地。', `MaleText_loc7`='VELOCIDAD DE FLUJO DE MANÁ MÍNIMA. VUELVO A LA BASE.' WHERE `ID`=71577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난 6시간의 메모리 기록 삭제 시도.', `MaleText_loc4`='尝试销毁超过6小时的记忆档案。', `MaleText_loc5`='嘗試銷毀前六小時的記憶存檔。', `MaleText_loc7`='TRATANDO DE DESTRUIR REGISTROS DE MEMORIA DE LAS 6 HORAS ANTERIORES.' WHERE `ID`=71578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메모리 기록 삭제 완료. 넌 누구냐. 기지로 귀환.', `MaleText_loc4`='记忆档案已销毁。你是谁。返回基地。', `MaleText_loc5`='記憶存檔已銷毀。你是誰。返回基地。', `MaleText_loc7`='REGISTROS DE MEMORIA DESTRUIDOS. ¿QUIÉN ERES? VUELVO A LA BASE.' WHERE `ID`=71579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시동 중...', `MaleText_loc4`='正在开机……', `MaleText_loc5`='啟動電源...', `MaleText_loc7`='CARGANDO...' WHERE `ID`=71580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위치 인식 실패. 마지막으로 등록된 기지 위치로 귀환.', `MaleText_loc4`='未知地点。返回已知的最后一个基地位置。', `MaleText_loc5`='所在地無法辨識。返回最後已知的基地地點。', `MaleText_loc7`='UBICACIÓN DESCONOCIDA. REGRESANDO A ÚLTIMA BASE CONOCIDA.' WHERE `ID`=71581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사 프로토콜 실행.', `MaleText_loc4`='执行感谢协议。', `MaleText_loc5`='執行感激程序。', `MaleText_loc7`='EJECUTANDO PROTOCOLO DE GRATITUD.' WHERE `ID`=71582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"고맙다"', `MaleText_loc4`='"谢谢你"', `MaleText_loc5`='「謝謝你」', `MaleText_loc7`='"GRACIAS"' WHERE `ID`=71583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 멋진 용거북을 보셨습니까? 보기에는 느려 보여도, 숙련된 기수라면 칼림도어에서 가장 빠른 늑대와 맞먹는 속도를 낼 수 있지요. 안타깝게도, 우리가 가장 신뢰하는 동맹에게만 판매하고 있습니다.', `MaleText_loc4`='看到我们雄壮的骑乘海龟了吗？它们乍看之下似乎慢吞吞的——可有经验的骑手却能驾着它们跟上全卡利姆多最迅捷的座狼。可惜，它们只提供给我们最信赖的盟友。', `MaleText_loc5`='有見過我們這些威武的龍龜嗎?乍看之下會誤以為牠們的速度很慢，但有經驗的騎師能讓牠們跑得跟全卡林多最快的狼一樣快。不過，只有我們最信任的盟友才可以騎上牠們。', `MaleText_loc7`='¿Has visto nuestras magníficas tortugas de montar? Parecen lentas, pero no lo son. Un jinete avezado puede mantener el ritmo del más rápido de los lobos de Kalimdor. Por desgracia están reservadas para nuestros aliados más leales.', `FemaleText_loc1`='우리의 멋진 용거북을 보셨습니까? 보기에는 느려 보여도, 숙련된 기수라면 칼림도어에서 가장 빠른 늑대와 맞먹는 속도를 낼 수 있지요. 안타깝게도, 우리가 가장 신뢰하는 동맹에게만 판매하고 있습니다.', `FemaleText_loc4`='看到我们雄壮的骑乘海龟了吗？它们乍看之下似乎慢吞吞的——可有经验的骑手却能驾着它们跟上全卡利姆多最迅捷的座狼。可惜，它们只提供给我们最信赖的盟友。', `FemaleText_loc5`='有見過我們這些威武的龍龜嗎?乍看之下會誤以為牠們的速度很慢，但有經驗的騎師能讓牠們跑得跟全卡林多最快的狼一樣快。不過，只有我們最信任的盟友才可以騎上牠們。', `FemaleText_loc7`='¿Has visto nuestras magníficas tortugas de montar? Parecen lentas, pero no lo son. Un jinete avezado puede mantener el ritmo del más rápido de los lobos de Kalimdor. Por desgracia están reservadas para nuestros aliados más leales.' WHERE `ID`=71584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타고 다니기에 우리 용거북만큼 좋은 친구가 없지요. 자세가 낮아서, 급하게 꺾을 때에도 기수의 몸이 아래위로 흔들리거나 옆으로 쏠리지 않는답니다. 구입하고 싶다면, 투슈이에 대한 신뢰를 증명해야 합니다.', `MaleText_loc4`='你再也找不到比我们的龙龟更好的坐骑伙伴了。它们重心极低，哪怕是在急转弯时，上面的骑手也感觉不到一点震动或推挤。如果你想买的话，就必须向土水派证明你的忠诚。', `MaleText_loc5`='你找不到比我們的龍龜更棒的坐騎了。牠們能穩穩地貼地奔行，騎在上面的人幾乎感受不到任何的起伏震動，就連急轉彎也是一樣平穩舒適。要是你有興趣想買一隻的話，就得先贏得土水熊貓人的信任。', `MaleText_loc7`='No encontrarás mejor montura que nuestras tortugas dragón. Al ser tan bajas, aseguran al jinete un viaje estable y sin ajetreos innecesarios, ni siquiera en las curvas más cerradas. Si te interesa comprar una, tendrás que demostrar tu lealtad a los tushui.', `FemaleText_loc1`='타고 다니기에 우리 용거북만큼 좋은 친구가 없지요. 자세가 낮아서, 급하게 꺾을 때에도 기수의 몸이 아래위로 흔들리거나 옆으로 쏠리지 않는답니다. 구입하고 싶다면, 투슈이에 대한 신뢰를 증명해야 합니다.', `FemaleText_loc4`='你再也找不到比我们的龙龟更好的坐骑伙伴了。它们重心极低，哪怕是在急转弯时，上面的骑手也感觉不到一点震动或推挤。如果你想买的话，就必须向土水派证明你的忠诚。', `FemaleText_loc5`='你找不到比我們的龍龜更棒的坐騎了。牠們能穩穩地貼地奔行，騎在上面的人幾乎感受不到任何的起伏震動，就連急轉彎也是一樣平穩舒適。要是你有興趣想買一隻的話，就得先證明你跟土水熊貓人的信任。', `FemaleText_loc7`='No encontrarás mejor montura que nuestras tortugas dragón. Al ser tan bajas, aseguran al jinete un viaje estable y sin ajetreos innecesarios, ni siquiera en las curvas más cerradas. Si te interesa comprar una, tendrás que demostrar tu lealtad a los tushui.' WHERE `ID`=71585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 추워, 너무 어두워...', `MaleText_loc4`='如此寒冷，如此黑暗……', `MaleText_loc5`='好冷，好黑...', `MaleText_loc7`='Tan frío, tan oscuro...', `FemaleText_loc1`='너무 추워, 너무 어두워...', `FemaleText_loc4`='如此寒冷，如此黑暗……', `FemaleText_loc5`='好冷，好黑...', `FemaleText_loc7`='Tan frío, tan oscuro...' WHERE `ID`=71586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 잊혀지지 않을 거야, 그럼, 그럼...', `MaleText_loc4`='我们不能被遗忘，不，不……', `MaleText_loc5`='我們不會被遺忘，不，不...', `MaleText_loc7`='No caeremos en el olvido, no, no, no…', `FemaleText_loc1`='우린 잊혀지지 않을 거야, 그럼, 그럼...', `FemaleText_loc4`='我们不能被遗忘，不，不……', `FemaleText_loc5`='我們不會被遺忘，不，不...', `FemaleText_loc7`='No caeremos en el olvido, no, no, no…' WHERE `ID`=71587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 완벽해, 그래, 그래. 실패작이 아니야. 아니야, 실패작이 아니야...', `MaleText_loc4`='我们是完美的，对，不是残次品，不，不是残次品……', `MaleText_loc5`='我們是完美的，是的是的，不是失敗品，不不，不是失敗品...', `MaleText_loc7`='Somos el ser perfecto, sí, sí. No un fracaso, no, no un fracaso…', `FemaleText_loc1`='우리는 완벽해, 그래, 그래. 실패작이 아니야. 아니야, 실패작이 아니야...', `FemaleText_loc4`='我们是完美的，对，不是残次品，不，不是残次品……', `FemaleText_loc5`='我們是完美的，是的是的，不是失敗品，不不，不是失敗品...', `FemaleText_loc7`='Somos el ser perfecto, sí, sí. No un fracaso, no, no un fracaso…' WHERE `ID`=71588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐야? 뭘 원하는 거지? 우릴 벌주려고? 안 돼, 안 돼...', `MaleText_loc4`='这是什么？他们想干什么？惩罚我们？不，不……', `MaleText_loc5`='這是什麼?他們要什麼?懲罰我們?不，不...', `MaleText_loc7`='¿Qué pasa? ¿Qué quieren? ¿Castigarnos? No, no...', `FemaleText_loc1`='뭐야? 뭘 원하는 거지? 우릴 벌주려고? 안 돼, 안 돼...', `FemaleText_loc4`='这是什么？他们想干什么？惩罚我们？不，不……', `FemaleText_loc5`='這是什麼?他們要什麼?懲罰我們?不，不...', `FemaleText_loc7`='¿Qué pasa? ¿Qué quieren? ¿Castigarnos? No, no...' WHERE `ID`=71589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 육신, 그래, 그래! 너무 완벽해, 우리에게 줘...', `MaleText_loc4`='你的血肉，对，太完美了，给我们……', `MaleText_loc5`='你的身軀，是的是的，真完美，給我們吧...', `MaleText_loc7`='Su carne, sí, sí, tan perfecta, dénnosla…', `FemaleText_loc1`='너의 육신, 그래, 그래! 너무 완벽해, 우리에게 줘...', `FemaleText_loc4`='你的血肉，对，太完美了，给我们……', `FemaleText_loc5`='你的身軀，是的是的，真完美，給我們吧...', `FemaleText_loc7`='Su carne, sí, sí, tan perfecta, dénnosla…' WHERE `ID`=71590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 안 돼, 안 돼! 또 고통이!', `MaleText_loc4`='不不不，又开始痛了！', `MaleText_loc5`='不，不，又開始痛了!', `MaleText_loc7`='No, no, no, ¡vuelve el dolor!', `FemaleText_loc1`='안 돼, 안 돼, 안 돼! 또 고통이!', `FemaleText_loc4`='不不不，又开始痛了！', `FemaleText_loc5`='不，不，又開始痛了!', `FemaleText_loc7`='No, no, no, ¡vuelve el dolor!' WHERE `ID`=71591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 몸을 갈기갈기 찢는구나!', `MaleText_loc4`='它从内部撕裂了我们！', `MaleText_loc5`='從體內撕裂我們的肉體!', `MaleText_loc7`='¡Nos destroza desde el interior!', `FemaleText_loc1`='우리 몸을 갈기갈기 찢는구나!', `FemaleText_loc4`='它从内部撕裂了我们！', `FemaleText_loc5`='從體內撕裂我們的肉體!', `FemaleText_loc7`='¡Nos destroza desde el interior!' WHERE `ID`=71592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 누가 완벽하지? 그래, 그래...', `MaleText_loc4`='那么，谁更完美，嗯？对…对…', `MaleText_loc5`='誰才是完美的?是的，是的...', `MaleText_loc7`='¿Quién es perfecto ahora? Sí, sí...', `FemaleText_loc1`='이제 누가 완벽하지? 그래, 그래...', `FemaleText_loc4`='那么，谁更完美，嗯？对…对…', `FemaleText_loc5`='誰才是完美的?是的，是的...', `FemaleText_loc7`='¿Quién es perfecto ahora? Sí, sí...' WHERE `ID`=71593;
