UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 좋은 데 써 주마, 침입자.', `MaleText_loc4`='我会好好利用你的，入侵者。', `MaleText_loc5`='我會善加利用你的靈魂的，闖入者。', `MaleText_loc7`='Me serás muy útil, $gintruso:intrusa;.' WHERE `ID`=71599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 죽음을 음미해 주마!', `MaleText_loc4`='我会好好享受你的死亡的，闯入者！', `MaleText_loc5`='闖入者，我會好好享受你的死亡!', `MaleText_loc7`='¡Disfrutaré con tu muerte!' WHERE `ID`=71600;
