UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처의 웅덩이에서 살아있는 점액이 생겨나기 시작합니다!', `MaleText_loc4`='附近的池塘中开始形成活化液体！', `MaleText_loc5`='活體液化物開始在附近的池子裡成形!', `MaleText_loc7`='¡Empiezan a formarse fluidos vivos en un charco cercano!', `FemaleText_loc1`='근처의 웅덩이에서 살아있는 점액이 생겨나기 시작합니다!', `FemaleText_loc4`='附近的池塘中开始形成活化液体！', `FemaleText_loc5`='活體液化物開始在附近的池子裡成形!', `FemaleText_loc7`='¡Empiezan a formarse fluidos vivos en un charco cercano!' WHERE `ID`=71602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136210|h[비늘막 주머니]|h|r 능력을 습득합니다!', `MaleText_loc4`='普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136210|h[腹部毒囊]|h|r！', `MaleText_loc5`='普莫迪斯開始|cFFFF0000|Hspell:136209|h[進化]|h|r，並且獲得了|cFFFF0000|Hspell:136210|h[腹囊]|h|r!', `MaleText_loc7`='¡Primordius |cFFFF0000|Hspell:136209|h[Evoluciona]|h|r y obtiene |cFFFF0000|Hspell:136210|h[Glándulas ventrales]|h|r!', `FemaleText_loc1`='프리모디우스가 |cFFFF0000|Hspell:136209|h[진화]|h|r하고 |cFFFF0000|Hspell:136210|h[비늘막 주머니]|h|r 능력을 습득합니다!', `FemaleText_loc4`='普利莫修斯发生|cFFFF0000|Hspell:136209|h[进化]|h|r并获得了|cFFFF0000|Hspell:136210|h[腹部毒囊]|h|r！', `FemaleText_loc5`='普莫迪斯開始|cFFFF0000|Hspell:136209|h[進化]|h|r，並且獲得了|cFFFF0000|Hspell:136210|h[腹囊]|h|r!', `FemaleText_loc7`='¡Primordius |cFFFF0000|Hspell:136209|h[Evoluciona]|h|r y obtiene |cFFFF0000|Hspell:136210|h[Glándulas ventrales]|h|r!' WHERE `ID`=71603;
