UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 좀 아플거야!', `MaleText_loc4`='这可是很疼的。', `MaleText_loc5`='這會很痛的。', `MaleText_loc7`='¡Esto les va a doler!' WHERE `ID`=71609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프리모디우스가 통제할 수 없을 만큼 변형됩니다!', `MaleText_loc4`='普利莫修斯失控并发生了变异！', `MaleText_loc5`='普莫迪斯的突變失去控制了!', `MaleText_loc7`='¡Primordius muta descontroladamente!', `FemaleText_loc1`='프리모디우스가 통제할 수 없을 만큼 변형됩니다!', `FemaleText_loc4`='普利莫修斯失控并发生了变异！', `FemaleText_loc5`='普莫迪斯的突變失去控制了!', `FemaleText_loc7`='¡Primordius muta descontroladamente!' WHERE `ID`=71610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호쿠가 당신의 피를 오염시킵니다...', `MaleText_loc4`='霍古开始侵蚀你的血液……', `MaleText_loc5`='郝古開始腐化你的鮮血...', `MaleText_loc7`='Hoku empieza a corromperte la sangre...', `FemaleText_loc1`='호쿠가 당신의 피를 오염시킵니다...', `FemaleText_loc4`='霍古开始侵蚀你的血液……', `FemaleText_loc5`='郝古開始腐化你的鮮血...', `FemaleText_loc7`='Hoku empieza a corromperte la sangre...' WHERE `ID`=71611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다! [개인 인스턴스 대기열에 등록합니다.]', `MaleText_loc4`='我准备好了！[排队等待单人副本。]', `MaleText_loc5`='我準備好了! [加入單人副本的佇列。]', `MaleText_loc7`='¡Adelante! [Únete a la cola para hacer la estancia en solitario.]', `FemaleText_loc1`='준비됐어요! [개인 인스턴스 대기열에 등록합니다.]', `FemaleText_loc4`='我准备好了！[排队等待单人副本。]', `FemaleText_loc5`='我準備好了! [加入單人副本的佇列。]', `FemaleText_loc7`='¡Adelante! [Únete a la cola para hacer la estancia en solitario.]' WHERE `ID`=71612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔다, 벌레들아. 잔달라 제국이 여기서 부활한다!', `MaleText_loc4`='爬虫们，欢迎来见证赞达拉帝国的重生！', `MaleText_loc5`='弱者們，歡迎來見證贊達拉帝國的重生!', `MaleText_loc7`='¡Bienvenidos al renacimiento del imperio Zandalari, debiluchos!', `FemaleText_loc1`='잘 왔다, 벌레들아. 잔달라 제국이 여기서 부활한다!', `FemaleText_loc4`='爬虫们，欢迎来见证赞达拉帝国的重生！', `FemaleText_loc5`='弱者們，歡迎來見證贊達拉帝國的重生!', `FemaleText_loc7`='¡Bienvenidos al renacimiento del imperio Zandalari, debiluchos!' WHERE `ID`=71613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='많은 부족이 결집했다. 너희는 한 부족이 아니라, 트롤 제국 전체를 상대해야 한다! 줄의 손아귀가 다시 아제로스를 뒤덮고, 너희 열등한 종족은 고통이 뭔지 알게 될 거다!', `MaleText_loc4`='各部族已团结起来——你们面对的不是单一势力，而是整个巨魔帝国！祖尔之手将重新掌握艾泽拉斯！你们这些下等种族大难临头了！', `MaleText_loc5`='所有部族已經齊聚，你們不只面對一支軍隊，而是整個食人妖帝國結合的大軍!祖爾之手將會再次橫掃艾澤拉斯!你們次等種族將體驗苦痛!', `MaleText_loc7`='Las tribus se han reunido. ¡No se enfrentan a un simple ejército, sino al poder de todo el imperio trol! ¡La mano de Zul se extenderá de nuevo por todo Azeroth! ¡Y las razas inferiores conocerán el dolor!', `FemaleText_loc1`='많은 부족이 결집했다. 너희는 한 부족이 아니라, 트롤 제국 전체를 상대해야 한다! 줄의 손아귀가 다시 아제로스를 뒤덮고, 너희 열등한 종족은 고통이 뭔지 알게 될 거다!', `FemaleText_loc4`='各部族已团结起来——你们面对的不是单一势力，而是整个巨魔帝国！祖尔之手将重新掌握艾泽拉斯！你们这些下等种族大难临头了！', `FemaleText_loc5`='所有部族已經齊聚，你們不只面對一支軍隊，而是整個食人妖帝國結合的大軍!祖爾之手將會再次橫掃艾澤拉斯!你們次等種族將體驗苦痛!', `FemaleText_loc7`='Las tribus se han reunido. ¡No se enfrentan a un simple ejército, sino al poder de todo el imperio trol! ¡La mano de Zul se extenderá de nuevo por todo Azeroth! ¡Y las razas inferiores conocerán el dolor!' WHERE `ID`=71614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제, 야수훈련소의 진짜 힘을 보여주마. 다칼라 디추카 호리돈! 칼리마스테!', `MaleText_loc4`='看看神兽真正的力量吧。D''akala di''chuka，赫利东！Kalimaste！', `MaleText_loc5`='見證野獸守衛的真正力量。哈里登，D''akala di''chuka! Kalimaste!', `MaleText_loc7`='Van a presenciar el poder de la Guardia de las Bestias. ¡D''akala di''chuka Horridonte! ¡Kalimaste!', `FemaleText_loc1`='이제, 야수훈련소의 진짜 힘을 보여주마. 다칼라 디추카 호리돈! 칼리마스테!', `FemaleText_loc4`='看看神兽真正的力量吧。D''akala di''chuka，赫利东！Kalimaste！', `FemaleText_loc5`='見證野獸守衛的真正力量。哈里登，D''akala di''chuka! Kalimaste!', `FemaleText_loc7`='Van a presenciar el poder de la Guardia de las Bestias. ¡D''akala di''chuka Horridonte! ¡Kalimaste!' WHERE `ID`=71615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리, 얼어붙은 북부의 힘을 보여줘라!', `MaleText_loc4`='达卡莱部族，让他们看看北地的冰封之力！', `MaleText_loc5`='德拉克瑞部族，讓他們見識北方冰凍的力量!', `MaleText_loc7`='Tribu Drakkari, ¡muéstrenles el poder del gélido norte!', `FemaleText_loc1`='드라카리, 얼어붙은 북부의 힘을 보여줘라!', `FemaleText_loc4`='达卡莱部族，让他们看看北地的冰封之力！', `FemaleText_loc5`='德拉克瑞部族，讓他們見識北方冰凍的力量!', `FemaleText_loc7`='Tribu Drakkari, ¡muéstrenles el poder del gélido norte!' WHERE `ID`=71616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구루바시, 밀림의 독으로 적을 시체로 만들어 강에 띄워 보내라.', `MaleText_loc4`='古拉巴什部族，让丛林的毒液带走他们浮肿的尸身。', `MaleText_loc5`='古拉巴什部族，準備把死於叢林毒藥的這些弱者棄屍到河流去。', `MaleText_loc7`='Tribu Gurubashi, envíen sus cadáveres inflados río abajo con los venenos de la selva.', `FemaleText_loc1`='구루바시, 밀림의 독으로 적을 시체로 만들어 강에 띄워 보내라.', `FemaleText_loc4`='古拉巴什部族，让丛林的毒液带走他们浮肿的尸身。', `FemaleText_loc5`='古拉巴什部族，準備把死於叢林毒藥的這些弱者棄屍到河流去。', `FemaleText_loc7`='Tribu Gurubashi, envíen sus cadáveres inflados río abajo con los venenos de la selva.' WHERE `ID`=71617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파락키, 모래의 분노로 적의 껍질을 벗겨라!', `MaleText_loc4`='法拉基部族，用沙漠的怒火撕裂他们！', `MaleText_loc5`='法拉奇部族，用沙的怒火燒灼他們的軀體!', `MaleText_loc7`='Tribu Farraki, ¡despelléjenlos con la furia de las arenas!', `FemaleText_loc1`='파락키, 모래의 분노로 적의 껍질을 벗겨라!', `FemaleText_loc4`='法拉基部族，用沙漠的怒火撕裂他们！', `FemaleText_loc5`='法拉奇部族，用沙的怒火燒灼他們的軀體!', `FemaleText_loc7`='Tribu Farraki, ¡despelléjenlos con la furia de las arenas!' WHERE `ID`=71618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니, 줄진의 이름으로, 죽은 전쟁 군주들의 복수를 하자!', `MaleText_loc4`='阿曼尼部族，以祖尔金之名，为陨落的领主复仇吧！', `MaleText_loc5`='阿曼尼部族，以祖爾金之名，替死去的督軍們復仇吧!', `MaleText_loc7`='Tribu Amani, ¡venguen a sus señores caídos en nombre de Zul''jin!', `FemaleText_loc1`='아마니, 줄진의 이름으로, 죽은 전쟁 군주들의 복수를 하자!', `FemaleText_loc4`='阿曼尼部族，以祖尔金之名，为陨落的领主复仇吧！', `FemaleText_loc5`='阿曼尼部族，以祖爾金之名，替死去的督軍們復仇吧!', `FemaleText_loc7`='Tribu Amani, ¡venguen a sus señores caídos en nombre de Zul''jin!' WHERE `ID`=71619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 이제 내 차례다! 전쟁신의 진짜 힘을 보여 주마!', `MaleText_loc4`='哈哈哈！现在轮到我了！见识一下战神的实力吧！', `MaleText_loc5`='哈哈哈，該我了!讓你們見識見識何謂戰神!', `MaleText_loc7`='¡Jajaja! ¡Es mi turno! ¡Vas a saber lo que es un dios de la guerra!', `FemaleText_loc1`='하하하! 이제 내 차례다! 전쟁신의 진짜 힘을 보여 주마!', `FemaleText_loc4`='哈哈哈！现在轮到我了！见识一下战神的实力吧！', `FemaleText_loc5`='哈哈哈，該我了!讓你們見識見識何謂戰神!', `FemaleText_loc7`='¡Jajaja! ¡Es mi turno! ¡Vas a saber lo que es un dios de la guerra!' WHERE `ID`=71620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 두개골은 내 엄니에 예쁘게 장식해 주마.', `MaleText_loc4`='你的颅骨将成为我獠牙上的小装饰。', `MaleText_loc5`='你的頭骨很適合做我獠牙的裝飾品。', `MaleText_loc7`='Tu cráneo será un bonito adorno para mis colmillos.', `FemaleText_loc1`='너희 두개골은 내 엄니에 예쁘게 장식해 주마.', `FemaleText_loc4`='你的颅骨将成为我獠牙上的小装饰。', `FemaleText_loc5`='你的頭骨很適合做我獠牙的裝飾品。', `FemaleText_loc7`='Tu cráneo será un bonito adorno para mis colmillos.' WHERE `ID`=71621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다칼라 코라스테... 호리돈... 죽여라...', `MaleText_loc4`='Da''kala koraste……赫利东……消灭他们……', `MaleText_loc5`='Da''kala koraste...哈里登...消滅他們...', `MaleText_loc7`='Da''kala koraste… Horridonte… acaba con ellos…', `FemaleText_loc1`='다칼라 코라스테... 호리돈... 죽여라...', `FemaleText_loc4`='Da''kala koraste……赫利东……消灭他们……', `FemaleText_loc5`='Da''kala koraste...哈里登...消滅他們...', `FemaleText_loc7`='Da''kala koraste… Horridonte… acaba con ellos…' WHERE `ID`=71622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안냥.', `MaleText_loc4`='你好啊。', `MaleText_loc5`='欸。', `MaleText_loc7`='A las muy buenas.' WHERE `ID`=71623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 "안녕"이라고 한 겁니까?', `MaleText_loc4`='你刚才是不是说了“你好”？', `MaleText_loc5`='你剛剛是在說『嗨』嗎?', `MaleText_loc7`='¿Acabas de decir "Muy buenas"?', `FemaleText_loc1`='방금 "안녕"이라고 한 건가요?', `FemaleText_loc4`='你刚才是不是说了“你好”？', `FemaleText_loc5`='你剛剛是在說『嗨』嗎?', `FemaleText_loc7`='¿Acabas de decir "Muy buenas"?' WHERE `ID`=71624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, "안냥"이라고 했어. 그 정도면 비슷하잖아.$b$b그럼 이만.', `MaleText_loc4`='“不。我说的是‘你好啊’。不过也差不多了。$b$b再见了。”', `MaleText_loc5`='沒，我說的是『欸』。但也差不多啦。$b$b再見。', `MaleText_loc7`='No, he dicho "A las muy buenas", pero se le parece mucho.$b$bHasta luego.' WHERE `ID`=71625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불쌍한 섬 주민들을 학살할 시간은 있으면서 내 아름다운 육신을 찾을 시간은 없단 말이냐?', `MaleText_loc4`='你有时间去屠杀岛上无助的居民，却没有时间帮忙收集我伟大的身躯？', `MaleText_loc5`='你有時間殺這島上的東西、卻沒時間組合我的身軀?', `MaleText_loc7`='¿Tienes tiempo para matar pobres isleños pero no para reconstruir mi glorioso cuerpo?' WHERE `ID`=71626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늑장은 그만 부려라, 노예! 내 육신을 한데 모을 것을 명하노라.', `MaleText_loc4`='别再拖拖拉拉了，乞求者！我要你去收集我的躯体！', `MaleText_loc5`='別再囉唆了!我命令你重組我的身軀。', `MaleText_loc7`='¡Ya basta de excusas, suplicante! ¡Te ordeno que reconstruyas mi cuerpo!' WHERE `ID`=71627;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그게 적을 처치한다고 한 것이냐? 불이라든지 번개 같은 게 있을 줄 알았는데 말이지.', `MaleText_loc4`='你管那叫击杀对手？我还以为会……火光冲天，或者来几道闪电呢。', `MaleText_loc5`='那樣就把對手殺了?我還以為會多用點...火啊，還是閃電啊什麼的。', `MaleText_loc7`='¿A eso le llamas matar a un enemigo? Yo esperaba... más fuego. O rayos, quizás.' WHERE `ID`=71628;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금의 너보다 훨씬 더 세련되게 싸우는 사우록도 보았다.', `MaleText_loc4`='我见过的蜥蜴人都比你刚才打得更像样。', `MaleText_loc5`='我看薩烏洛克他們都比你剛剛的表現要來得有看頭。', `MaleText_loc7`='He visto saurok con mejor estilo de lucha que lo que acabo de ver.' WHERE `ID`=71629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 이번엔 제대로 한 방 먹였구나. 아직 희망이 있어.', `MaleText_loc4`='啊！刚才那一下很漂亮。看来你还有点希望。', `MaleText_loc5`='啊!這樣才對嘛，看來你還是有希望的。', `MaleText_loc7`='¡Ah! Eso sí que ha sido una paliza como es debido. Igual se puede hacer algo contigo después de todo.' WHERE `ID`=71630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='솜씨가 제법이구나. 언젠가 훌륭한 노예가 되겠어.', `MaleText_loc4`='你的能力挺让人印象深刻的。总有一天，你会成为出色的奴隶。', `MaleText_loc5`='你的本領相當不錯。你總有一天會成為出色的奴隸。', `MaleText_loc7`='Tus habilidades no están nada mal. Algún día serás $gun esclavo:una esclava; excelente.' WHERE `ID`=71631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 천둥왕 치세 하에 수백 년을 살아남았다. 비결이 뭔지 아느냐? 주인님을 기다리게 하지 않은 것이지!', `MaleText_loc4`='在雷电之王统治期间，我都能活好几百年。你知道为什么吗？因为我从不让主人久等！', `MaleText_loc5`='我在雷王的統治下活了數百年之久。你知道我是怎麼辦到的嗎?那就是別讓主人等太久!', `MaleText_loc7`='Sobreviví cientos de años durante el reinado del Rey del Trueno. ¿Sabes cómo? ¡No hacía esperar a mis amos!' WHERE `ID`=71632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱한 것. 너한테 방금 죽은 녀석은 더 딱하고 말이다.', `MaleText_loc4`='多么可悲的生物。直接消灭掉算了。', `MaleText_loc5`='真可悲的生物。你剛才殺死的那個玩意也一樣。', `MaleText_loc7`='Qué criatura tan patética. Y esa cosa que acabas de matar también.' WHERE `ID`=71633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 수호자들을 깨우십시오!', `MaleText_loc4`='我准备好了。唤醒守卫吧！', `MaleText_loc5`='我已經準備好了。喚醒守護者!', `MaleText_loc7`='Estoy listo. ¡Despierta a los guardianes!', `FemaleText_loc1`='준비됐습니다. 수호자들을 깨우십시오!', `FemaleText_loc4`='我准备好了。唤醒守卫吧！', `FemaleText_loc5`='我已經準備好了。喚醒守護者!', `FemaleText_loc7`='Estoy lista. ¡Despierta a los guardianes!' WHERE `ID`=71634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부는 몰락할 걸세! 갈 준비는 되었나?', `MaleText_loc4`='我们必须打倒山怖！你做好继续前进的准备了吗？', `MaleText_loc5`='衫布必定無疑!你已經準備好了嗎?', `MaleText_loc7`='¡Shan Bu caerá! ¿Estás $glisto:lista; para continuar?' WHERE `ID`=71635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부를 상대할 준비가 됐습니다!', `MaleText_loc4`='我准备好对付山怖了！', `MaleText_loc5`='我已經準備好對付衫布!', `MaleText_loc7`='¡Estoy listo para enfrentarme a Shan Bu!', `FemaleText_loc1`='샨 부를 상대할 준비가 됐어요!', `FemaleText_loc4`='我准备好对付山怖了！', `FemaleText_loc5`='我已經準備好對付衫布!', `FemaleText_loc7`='¡Estoy lista para enfrentarme a Shan Bu!' WHERE `ID`=71636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 너무 늦었네! 샨 부가 폭풍 군주 나락크의 부활 의식을 거의 마쳤다네. 하지만 그건 부수적인 문제야. 우리의 진짜 목표는 샨 부를 쓰러뜨리는 걸세!', `MaleText_loc4`='我们来迟了！暴风领主纳拉克就快被山怖复活了。但这只是个偶发事件。我们真正的目标是要击败山怖！', `MaleText_loc5`='我們來遲一步!衫布就快要復活風暴龍王納拉卡了。但這只是意外的插曲，我們真正的目標還是要擊敗衫布!', `MaleText_loc7`='¡Llegamos demasiado tarde! Shan Bu casi ha terminado de resucitar a Nalak, el Señor de la Tormenta. Pero no importa. Nuestro verdadero objetivo es derrotar a Shan Bu.' WHERE `ID`=71637;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 밖은 엉망진창입니다! 공성전이 시작됐지만, 폭탄이 장벽에 접근하지 못했어요.', `FemaleText_loc4`='现在外面一片混乱，$p！攻击已经开始，可是重型炸药还没有到位。', `FemaleText_loc5`='外面一團混亂!攻城已經開始，但我們的強力炸藥一直都沒有運到城牆。', `FemaleText_loc7`='¡Ahí fuera reina el caos! El asedio ha empezado, pero los explosivos nunca llegaron a la muralla.' WHERE `ID`=71638;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 측면을 지키겠습니다. 폭탄을 모아서 장벽으로 가져가세요. 서둘러요!', `FemaleText_loc4`='我来掩护侧翼。你去收集炸药并把它们送到指定地点。快！', `FemaleText_loc5`='我會防守側翼。收集我們的炸藥並帶到城牆。快!', `FemaleText_loc7`='Cubriré los flancos. Reúne los explosivos y llévalos a la muralla. ¡Corre!' WHERE `ID`=71639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제브툴라 야수소환사가 자신을 도울 랩터를 소환합니다!', `MaleText_loc4`='赞布图拉驭兽师召唤迅猛龙前来助战！', `MaleText_loc5`='札布圖拉喚獸者召喚了迅猛龍來助陣!', `MaleText_loc7`='¡El clamabestias de Zeb''tula invoca raptores para que le ayuden!', `FemaleText_loc1`='제브툴라 야수소환사가 자신을 도울 랩터를 소환합니다!', `FemaleText_loc4`='赞布图拉驭兽师召唤迅猛龙前来助战！', `FemaleText_loc5`='札布圖拉喚獸者召喚了迅猛龍來助陣!', `FemaleText_loc7`='¡El clamabestias de Zeb''tula invoca raptores para que le ayuden!' WHERE `ID`=71640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 병력이 상륙할 지점을 선택했소. 방어에 유리한 동쪽의 작은 반도지.', `MaleText_loc4`='我已经选好了登陆点：就是我们东边那座易守难攻的半岛。', `MaleText_loc5`='我替我們的部隊選了一個登陸點。是在我們東方的一個小半島，易守難攻。', `MaleText_loc7`='He seleccionado un punto de desembarco para las tropas: una península al este, fácil de defender.' WHERE `ID`=71641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 잔달라 트롤이 이미 그곳에 요새를 구축했소.', `MaleText_loc4`='可惜，赞达拉巨魔已经占据了那里。', `MaleText_loc5`='可惜的是，贊達拉食人妖已經佔領了它，並強化了防禦。', `MaleText_loc7`='Pero los trols Zandalari ya la tomaron y fortificaron.' WHERE `ID`=71642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 방어막이 요새를 보호하오. 함선이 상륙하려면, 우선 그걸 없애야겠소.', `MaleText_loc4`='他们用一个强大的灵魂屏障守卫着它。得先解除它，才能让船只靠岸。', `MaleText_loc5`='他們用一個強大的靈魂屏障保護它。我們必須解除它才能讓我們的船艦登陸。', `MaleText_loc7`='La protegen con una poderosa barrera espiritual. Habrá que desactivarla para poder desembarcar.' WHERE `ID`=71643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 지상 타격대를 이끌고 내부에서 그 방어막을 제거하시오!', `MaleText_loc4`='勇士，我要你带领一支突击小队，从内部瓦解这个屏障！', `MaleText_loc5`='勇士，我需要你來領導一場地面攻擊，從內部把屏障解除!', `MaleText_loc7`='Quiero que tú lideres un asalto terrestre y desactives la barrera desde adentro.' WHERE `ID`=71644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='탈것을 타고 정찰대장 엘시아를 찾아가시오. 지금 정예 순찰대를 조직하고 있소. 태양의 빛이 그대를 비추기를.', `MaleText_loc4`='找一匹坐骑，去和斥候队长艾尔希娅会合吧。她会召集一队精锐游侠配合你行动。愿阳光照耀着你。', `MaleText_loc5`='上坐騎，去和斥候隊長艾爾西雅會合。她正在調度跟你一起進攻的精英遊俠。願陽光照耀你。', `MaleText_loc7`='Monta y reúnete con la capitana de exploradores Elsia. Está organizando un grupo de forestales de élite para acompañarte. Que la luz del sol ilumine tu camino.' WHERE `ID`=71645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여깁니다, 용사님!', `FemaleText_loc4`='我在上面，勇士！', `FemaleText_loc5`='在這上面，勇士!', `FemaleText_loc7`='¡Aquí arriba!' WHERE `ID`=71646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='선리버 마법사들이 번개를 막아 주는 수호물을 만들었습니다. 그래도 혹시 모르니 산개하는 게 좋겠어요.', `FemaleText_loc4`='夺日者找到了保护坐骑不受闪电伤害的方法。可为了以防万一，还是分散飞行吧。', `FemaleText_loc5`='奪日者想出了讓飛行坐騎不受閃電影響的方法。但安全起見，我們還是以散開的隊形飛行。', `FemaleText_loc7`='Los Atracasol han averiguado cómo proteger a nuestras monturas de los rayos, pero guarda distancia por si acaso.' WHERE `ID`=71647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아래를 보세요! 마을과 지하 묘지를 계속 공격한 덕분에, 적이 혼란에 빠졌습니다. 모구와 잔달라 트롤은 이미 호드의 힘을 두려워하고 있어요.', `FemaleText_loc4`='看下面！我们对城镇和墓穴的持续攻击已经令敌人陷入了混乱。魔古族和赞达拉开始害怕部落了。', `FemaleText_loc5`='看下面!我們對於下方墓地和城鎮的持續進攻使敵人陷入了混亂。魔古或贊達拉已經在害怕部落的力量。', `FemaleText_loc7`='¡Allí abajo! Los continuos asaltos a la ciudad y las criptas han confundido al enemigo. Los mogu y los Zandalari ya temen el poder de la Horda.' WHERE `ID`=71648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='번개가 중앙의 탑을 내리치는 게 보이세요? 에이타스 님은 궁전 중심부에서 폭풍이 만들어진다고 생각하십니다.', `FemaleText_loc4`='你看到中央那座塔了吗？闪电一直在击打它。艾萨斯怀疑这场风暴就是源自于宫殿的中心。', `FemaleText_loc5`='看到中間的塔沒有?閃電持續打在上面。埃薩懷疑風暴就是從宮殿的中心所產生。', `FemaleText_loc7`='Ahí esta la torre central. Los truenos la golpean sin cesar. Aethas sospecha que las tormentas se originan en el centro del palacio.' WHERE `ID`=71649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 순찰대도 기다리고 있어요. 지금 최우선 과제는- 앗! 조심해요!', `FemaleText_loc4`='其他游侠就在前面等我们。我们的首要目标是——小心！', `FemaleText_loc5`='其他的遊俠在前面等著我們。我們的優先任務是 - 小心!', `FemaleText_loc7`='Los demás forestales nos esperan más adelante. Nuestra prioridad es… ¡Cuidado!' WHERE `ID`=71650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='태양샘이여! 하늘이 우릴 저버리는군요. 여긴 안전하지 않아요!', `FemaleText_loc4`='太阳之井在上！天空背叛了我们——这里不安全了！', `FemaleText_loc5`='太陽之井啊!空中的狀況不妙 - 我們在這裡很危險!', `FemaleText_loc7`='¡Por la Fuente del Sol! Los cielos nos traicionan. ¡Aquí corremos peligro!' WHERE `ID`=71651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아래로! 전원 하강!', `FemaleText_loc4`='降落！全体降落！', `FemaleText_loc5`='下去!所有人下去!', `FemaleText_loc7`='¡Abajo! ¡Todo el mundo abajo!' WHERE `ID`=71652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사님, 괜찮으십니까?', `FemaleText_loc4`='勇士，你还好吧？', `FemaleText_loc5`='勇士，你還好嗎?', `FemaleText_loc7`='¿Te encuentras bien?' WHERE `ID`=71653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='위험했습니다. 적이 우릴 기다리고 있었군요. 병사들은 늪 전체로 흩어졌고, 우리도 이제 적진에 고립됐어요!', `FemaleText_loc4`='我们还不安全。他们早就等着我们了。部队散落在沼泽各处，而我们却孤军深入敌后！', `FemaleText_loc5`='我們陷入了危險。他們早就準備要對付我們。我們的人四散在沼澤裡，孤軍深入了敵境!', `FemaleText_loc7`='No estamos a salvo. Nos estaban esperando. Nuestras fuerzas están esparcidas por el pantano, ¡y estamos solos tras las líneas enemigas!' WHERE `ID`=71654;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런, 좋지 않네요.', `FemaleText_loc4`='哦，不好。', `FemaleText_loc5`='糟糕。不妙。', `FemaleText_loc7`='No. No está bien.' WHERE `ID`=71655;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 후퇴합니다만, 아직 멈춰서는 안 돼요.', `FemaleText_loc4`='他们撤退了，但还不能放松。', `FemaleText_loc5`='他們在撤退，但是我們不能鬆懈下來。', `FemaleText_loc7`='Están retrocediendo, pero no podemos parar ahora.' WHERE `ID`=71656;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 여기서 살아남으려면 어서 마을로 가야 해요.', `FemaleText_loc4`='我们逃出升天的唯一希望就是占领城镇。', `FemaleText_loc5`='我們唯一活著離開的希望是把城鎮打下來。', `FemaleText_loc7`='Nuestra única esperanza de salir con vida es tomar la ciudad.' WHERE `ID`=71657;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입구가 막혔어요. 부숴버리세요!', `FemaleText_loc4`='入口被挡住了。把它砸开！', `FemaleText_loc5`='入口被擋住了。把它打下來!', `FemaleText_loc7`='La entrada está cerrada. ¡Rompe la barricada!' WHERE `ID`=71658;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 트롤이 마음에 안 듭니다. 조심하세요!', `FemaleText_loc4`='我讨厌那个巨魔的样子。小心！', `FemaleText_loc5`='我不喜歡那個食人妖的模樣。小心點!', `FemaleText_loc7`='No me gusta ese trol. ¡Ten cuidado!' WHERE `ID`=71659;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 생물을 처치하세요! 우리가 풀려나야 해요!', `FemaleText_loc4`='快击败那个家伙，我们才能获得自由！', `FemaleText_loc5`='打倒那個怪物，釋放我們的人!', `FemaleText_loc7`='¡Derrota a la criatura para que podamos liberar a los nuestros!' WHERE `ID`=71660;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 지키는 저 가면이 방어막을 생성하는 게 분명해요. 파괴하세요!', `FemaleText_loc4`='他们在保护那个面具。那一定是屏障的源头。摧毁它！', `FemaleText_loc5`='他們正在保護那個面具。那一定是屏障的能量來源。摧毀它!', `FemaleText_loc7`='Están protegiendo esa máscara. Debe ser el origen de la barrera. ¡Destrúyela!' WHERE `ID`=71661;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼 가면을 파괴해서 방어막을 없애요!', `FemaleText_loc4`='快摧毁灵魂面具，解除屏障！', `FemaleText_loc5`='摧毀那個靈魂面具，解除屏障!', `FemaleText_loc7`='¡Destruye la máscara de espíritu para anular la barrera!' WHERE `ID`=71662;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈이 가면을 지키고 있습니다. 처치해요!', `FemaleText_loc4`='他在保护面具。杀了他！', `FemaleText_loc5`='他在保護面具。殺了他!', `FemaleText_loc7`='Está protegiendo la máscara. ¡Mátalo!' WHERE `ID`=71663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서지 마십시오. 이기고 있습니다!', `FemaleText_loc4`='别放弃。我们就要胜利了！', `FemaleText_loc5`='不要鬆懈。我們快贏了!', `FemaleText_loc7`='No te rindas. ¡Lo vamos a conseguir!' WHERE `ID`=71664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어막이... 사라졌어요! 해냈습니다!', `FemaleText_loc4`='护盾——消失了！我们成功了！', `FemaleText_loc5`='屏障 - 消失了!我們成功了!', `FemaleText_loc7`='¡El escudo ha caído! ¡Lo logramos!' WHERE `ID`=71665;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 그대 도움이 없었다면 저는 저 늪에서 죽었을 겁니다. 제 생명의 은인이세요.', `FemaleText_loc4`='勇士，要不是你，我已经死在沼泽里了。我欠你一条命。', `FemaleText_loc5`='勇士，要不是你的幫忙我就會死在那片沼澤裡了。我欠你一條命。', `FemaleText_loc7`='Sin tu ayuda habría muerto en este pantano sin duda alguna. Te debo la vida.' WHERE `ID`=71666;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘했어요. 계속 가지요.', `FemaleText_loc4`='干得好，英雄。我们前进吧。', `FemaleText_loc5`='做得好，英雄。咱們走吧。', `FemaleText_loc7`='Buen trabajo. Sigamos adelante.' WHERE `ID`=71667;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제게 영감을 주시는군요.', `FemaleText_loc4`='你真是鼓舞人心。', `FemaleText_loc5`='你很令人驚訝。', `FemaleText_loc7`='Eres un ejemplo a seguir.' WHERE `ID`=71668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 쉽게 하시는데요.', `FemaleText_loc4`='你让一切都变简单了。', `FemaleText_loc5`='你讓這一切看來很容易。', `FemaleText_loc7`='Haces que parezca sencillo.' WHERE `ID`=71669;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마음에 드는 움직임이에요.', `FemaleText_loc4`='我喜欢你这种风格，英雄。', `FemaleText_loc5`='我喜歡你的風格，英雄。', `FemaleText_loc7`='Me gusta tu estilo.' WHERE `ID`=71670;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀랍네요!', `FemaleText_loc4`='真了不起！', `FemaleText_loc5`='真不賴!', `FemaleText_loc7`='¡Impresionante!' WHERE `ID`=71671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신도레이의 승리요! 호드가 또 한 번 이겼소!', `MaleText_loc4`='胜利属于辛多雷！部落又胜利了。', `MaleText_loc5`='辛多雷的勝利!這也是部落的勝利。', `MaleText_loc7`='¡Victoria para los sin''dorei! Y otro triunfo para la Horda.' WHERE `ID`=71672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='롬매스, 방어선을 구축하시오. 에이타스는 감시의 수호물을 설치하고, 케시엘은 보급품을 내려 놓으시오.', `MaleText_loc4`='罗曼斯，去建防线。艾萨斯，设下真视之眼。克希尔，把帐篷和补给卸下来。', `MaleText_loc5`='洛摩斯，建好陣地。埃薩，放置哨衛結界。凱希爾，開始傳送帳棚和補給品過來。', `MaleText_loc7`='Rommath, establece un perímetro. Aethas, empieza a colocar resguardos. Kethiel, descarga los refugios y los suministros.' WHERE `ID`=71673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 형제 자매여! 적이 사방을 포위하고 있소! 앞으로 몇 주 간, 그대들의 용기가 승패를 결정지을 것이오.', `MaleText_loc4`='部落的兄弟姐妹们！我们如今群敌环伺！你们的勇气将是未来几周内决定胜败的关键。', `MaleText_loc5`='部落的兄弟姊妹們!敵人從四面八方包圍我們!你們接下來幾週的勇氣將會決定我們會勝利還是失敗。', `MaleText_loc7`='¡Hermanos y hermanas de la Horda! ¡El enemigo nos rodea por doquier! Su valor en las próximas semanas marcará la diferencia entre la victoria y la derrota.' WHERE `ID`=71674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 그대가 호드의 영광을 되찾아 주었소. 그 흔들리지 않는 의지 덕에 거점을 확보했소. 이제 진짜 일을 시작하지.', `MaleText_loc4`='勇士，部落以你为荣。你坚定的意志是我们立足的关键。现在，真正的任务即将开始。', `MaleText_loc5`='勇士，你替部落帶來了榮耀。你不屈不撓的精神讓我們穩住了這裡的形勢。現在，真正的工作正要開始。', `MaleText_loc7`='Has honrado a la Horda. Fue tu voluntad inquebrantable la que aseguró nuestra posición. Ahora empieza el verdadero trabajo.' WHERE `ID`=71675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이다! 형제여, 무기를 들어라! 놈들을 몰아내!', `MaleText_loc4`='他们来了！兄弟们，拿起武器——把他们扔回海里去！', `MaleText_loc5`='他們來了!準備戰鬥兄弟們，把他們丟回海裡!', `MaleText_loc7`='¡Ya vienen! A las armas, hermanos. ¡Envíenlos de vuelta al mar!' WHERE `ID`=71676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐허를 지켜라. 적을 베어 버려!', `MaleText_loc4`='守住废墟！杀了他们！', `MaleText_loc5`='守住廢墟。讓他們死在原地!', `MaleText_loc7`='Protejan las ruinas. ¡Mátenlos ahora mismo!' WHERE `ID`=71677;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자를 박살내라. 방어막을 지켜야 한다.', `MaleText_loc4`='碾碎入侵者。别让屏障关闭。', `MaleText_loc5`='消滅入侵者。屏障絕不能陷落。', `MaleText_loc7`='Aplasten a los intrusos. La barrera no debe caer.' WHERE `ID`=71678;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 상대해라! 내 의지는 강철이요, 우리는 무적이다!', `MaleText_loc4`='面对我吧！我的意志坚如精钢。我的人民坚不可摧！', `MaleText_loc5`='跟我作戰吧!我的意志如鐵，我的人民永不屈服!', `MaleText_loc7`='¡Ven aquí! Mi voluntad es férrea y mi gente indomable.' WHERE `ID`=71679;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레같은 놈! 너흰 내 야수들의 먹이다!', `MaleText_loc4`='废物！你们都要变成兽粮！', `MaleText_loc5`='你們是垃圾!是我寵物的食物!', `MaleText_loc7`='¡No eres nada! ¡Servirás de alimento a mis bestias!' WHERE `ID`=71680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼들이 네 피를 마실 것이다!', `MaleText_loc4`='万灵将啜饮你的鲜血！', `MaleText_loc5`='靈魂會以你的血為食!', `MaleText_loc7`='¡Los espíritus se darán un festín con tu sangre!' WHERE `ID`=71681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이여, 적의 의지를 파괴할 힘을 주소서...', `MaleText_loc4`='万灵赐予我力量。粉碎他们的意志……', `MaleText_loc5`='靈魂給我力量。摧毀他們的意志...', `MaleText_loc7`='Espíritus, denme fuerza. Quiebren su voluntad…' WHERE `ID`=71682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라가...', `MaleText_loc4`='赞达拉……', `MaleText_loc5`='贊達拉...', `MaleText_loc7`='Zandalar...' WHERE `ID`=71683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나거라, 고양이들아. 놀 시간이다...', `MaleText_loc4`='醒醒，小猫咪们。游戏时间到了……', `MaleText_loc5`='醒醒，遊戲時間到了...', `MaleText_loc7`='Wake up, kitties. It''s time to play...' WHERE `ID`=71684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문지기들을 쓰러뜨리게! 그러면 문이 열릴 걸세!', `MaleText_loc4`='打倒守门人！这样才能打开大门！', `MaleText_loc5`='解決守門者，門鎖就會打開!', `MaleText_loc7`='Take down the gatekeepers! It will unlock the gates!' WHERE `ID`=71685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다 되었군. 이제 문을 열어도 되겠는가?', `MaleText_loc4`='这就够他们受的了。你准备好了吗？我要开门了。', `MaleText_loc5`='總算解決他們了。你準備好要我開門了嗎?', `MaleText_loc7`='That takes care of them. Are you ready for me to open the gates?' WHERE `ID`=71686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나락크의 부활을 막기엔 늦었으나, 샨 부와 놈의 군대를 꺾기엔 늦지 않았네! 공격!', `MaleText_loc4`='我们来不及阻止纳拉克的复活仪式了，但还有机会打败山怖及其大军！进攻！', `MaleText_loc5`='我們來不及阻止納拉卡的復活，但我們還有機會打敗衫布和他的手下!攻擊!', `MaleText_loc7`='We were too late to stop the resurrection of Nalak, but not to defeat Shan Bu and his forces! Attack!' WHERE `ID`=71687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부, 때가 됐다! 그렇게 마법 뒤에 숨어 있지 말고 나와서 싸워라!', `MaleText_loc4`='山怖，是时候了！别躲在你那些魔法背后了，出来与我一战！', `MaleText_loc5`='衫布，別再靠魔法躲躲藏藏，出來決一死戰吧!', `MaleText_loc7`='Shan Bu, it is time! Stop hiding behind that magic of yours and fight!' WHERE `ID`=71688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게! 잔달라가 벽을 뛰어넘고 있네! 저 야수소환사들을 탈것에서 떨어뜨리게!', `MaleText_loc4`='小心！赞达拉巨魔跳过了围墙！把那些驭兽师从坐骑上打下去！', `MaleText_loc5`='當心!贊達拉翻過牆了!把那些喚獸者從坐騎打下來!', `MaleText_loc7`='Look out! Zandalari are jumping over the walls! Knock those Beastcallers off their mounts!' WHERE `ID`=71689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈은 우리를 과소평가했다, 샨 부. 이제 네놈이 사라질 테고 판다리아는 더 살기 좋은 곳이 될 것이다.', `MaleText_loc4`='你低估了我们，山怖。我们从你的魔掌中救出了这个地方，潘达利亚也将因此变得更美好。', `MaleText_loc5`='你太低估我們了，衫布。我們成功打敗了你，潘達利亞也因而變得更好。', `MaleText_loc7`='You underestimated us, Shan Bu. We have rid this place of you, and Pandaria is better for it.' WHERE `ID`=71690;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드는 중', `MaleText_loc4`='抬起', `MaleText_loc5`='舉起', `MaleText_loc7`='Acarrear', `FemaleText_loc1`='드는 중', `FemaleText_loc4`='抬起', `FemaleText_loc5`='舉起', `FemaleText_loc7`='Acarrear' WHERE `ID`=71691;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨어나라, 나락크. 주인님의 처소를 더럽히려는 것들에게 네 격노를 보여주거라.', `MaleText_loc4`='起来吧，纳拉克。用你的怒火席卷那些胆敢亵渎我们主人宫殿的不速之客！', `MaleText_loc5`='起來!納拉卡!用你的憤怒殺光玷污你主人宮殿的入侵者!', `MaleText_loc7`='Rise, Nalak. Bring forth your wrath upon those who would sully our master''s palace!' WHERE `ID`=71692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭탄이군요!$b$b잘 하셨습니다, $n 님. 아주 딱 맞춰 오셨어요.', `FemaleText_loc4`='炸药！$b$b干得好，$n。你来得正是时候。', `FemaleText_loc5`='炸藥!$b$b辦得好，$n。來得正是時候。', `FemaleText_loc7`='¡Los explosivos!$B$BBuen trabajo, $n. Justo a tiempo.' WHERE `ID`=71693;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄 여기 있습니다, 엘시아.', `MaleText_loc4`='炸药来了，艾尔希娅。', `MaleText_loc5`='炸藥拿來了，艾爾西雅。', `MaleText_loc7`='Aquí están los explosivos, Elsia.', `FemaleText_loc1`='폭탄 여기 있어요, 엘시아.', `FemaleText_loc4`='炸药来了，艾尔希娅。', `FemaleText_loc5`='炸藥拿來了，艾爾西雅。', `FemaleText_loc7`='Aquí están los explosivos, Elsia.' WHERE `ID`=71694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르십시오, $n 님!$b$b폭탄이 없으면 이 성벽을 뚫을 수 없어요!', `FemaleText_loc4`='快，$n！$b$b没有炸药我们就攻不破这道城墙！', `FemaleText_loc5`='動作快，$n!$b$b沒炸藥根本無法攻破這道牆!', `FemaleText_loc7`='¡Rápido, $n!$B$B¡No podemos destruir estos muros sin esos explosivos!' WHERE `ID`=71695;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='악! 꽉 잡아요!', `FemaleText_loc4`='啊！坚持住！', `FemaleText_loc5`='呃，等一下!', `FemaleText_loc7`='¡Agh! ¡Espera!' WHERE `ID`=71696;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섬에 상륙지점을 정했어요. 수비하기 쉬운 고지대죠.', `FemaleText_loc4`='我已经选好了登陆点：一片易守难攻的高地。', `FemaleText_loc5`='我已經在島上選了登陸地點了:一塊容易防守的高地。', `FemaleText_loc7`='He seleccionado un punto de desembarco para las tropas: terreno elevado, fácil de defender.' WHERE `ID`=71697;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 잔달라 트롤이 이미 그곳에 요새를 세웠어요.', `FemaleText_loc4`='不幸的是，赞达拉巨魔已占据并守卫着那里。', `FemaleText_loc5`='很不幸地，贊達拉的食人妖已經佔領那裡，並建立防禦了。', `FemaleText_loc7`='Por desgracia, los trols Zandalari ya lo tomaron y fortificaron.' WHERE `ID`=71698;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='강력한 영혼 보호막이 요새를 보호하고 있죠. 병력을 소환하려면 그걸 파괴해야 해요.', `FemaleText_loc4`='他们用一道强大的灵魂屏障守卫着它。我们得先解除它，才能让部队过来。', `FemaleText_loc5`='他們用一個強大的靈魂屏障保護它。我們必須先攻下那裡才能把士兵傳送進來。', `FemaleText_loc7`='Lo protegen con una gran barrera espiritual. Habrá que desactivarla para abrir los portales a las tropas.' WHERE `ID`=71699;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 지상 타격대를 이끌고 내부에서 그 방어막을 파괴해 주세요!', `FemaleText_loc4`='勇士，你要率领一支突击小队，从内部瓦解这道屏障！', `FemaleText_loc5`='勇士，我們需要你率領一次地面攻擊，從內部粉碎那個屏障!', `FemaleText_loc7`='Quiero que lideres un asalto terrestre y desactives la barrera desde adentro.' WHERE `ID`=71700;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈것을 타고 베리사 윈드러너를 찾아가세요. 지금 병력을 조직하고 있어요.', `FemaleText_loc4`='找一匹坐骑，去和温蕾萨·风行者会合吧。她正在召集一队精锐游侠来配合你。', `FemaleText_loc5`='騎上你的坐騎，去和凡蕾莎·風行者會合。她正在調度跟你一起進攻的部隊。', `FemaleText_loc7`='Sube y reúnete con Vereesa Brisaveloz. Está organizando el equipo que te acompañará.' WHERE `ID`=71701;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 위예요!', `FemaleText_loc4`='我在上面，勇士！', `FemaleText_loc5`='在這上面，勇士!', `FemaleText_loc7`='¡Aquí arriba!' WHERE `ID`=71702;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='번개를 피하는 방법을 찾아냈어요. 하지만 혹시 모르니 산개해서 날죠.', `FemaleText_loc4`='我们已经有了保护坐骑免受闪电干扰的方法。但为防万一，还是得分散飞行。', `FemaleText_loc5`='我想我們找到飛行坐騎不受閃電影響的方法了。但安全起見，還是以散開的隊形飛行。', `FemaleText_loc7`='Creo que hemos dado con la forma de proteger a nuestras monturas voladoras de los rayos, pero mantén la distancia por si acaso.' WHERE `ID`=71703;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 아래의 무덤과 마을을 꾸준히 습격한 보람이 있네요. 모구도 잔달라도 반격할 여력이 없을 거예요.', `FemaleText_loc4`='我们对下方墓地和城镇的持续进攻取得了成效。无论是魔古族还是赞达拉巨魔都已无力反攻了。', `FemaleText_loc5`='我們對於下方墓地和城鎮的入侵已經取得成果。魔古或贊達拉應該都無法進行反攻了。', `FemaleText_loc7`='Nuestras incursiones en el cementerio y en el poblado están dando resultado. Ni los mogu ni los Zandalari podrán organizar un contraataque.' WHERE `ID`=71704;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='중앙 탑이 보이세요? 계속 벼락이 내리치고 있어요. 폭풍이 궁전 중앙에서 생성되는 모양이에요.', `FemaleText_loc4`='看到中央那座塔了吗？闪电一直在击打它。我们怀疑这场风暴就源自于宫殿内部。', `FemaleText_loc5`='看到中間的塔沒有?閃電持續打在上面。我們懷疑風暴就是從宮殿的中心所產生。', `FemaleText_loc7`='¿Ves la torre central? Los rayos la azotan constantemente. Sospechamos que la tormenta se origina dentro del palacio.' WHERE `ID`=71705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='집결지가 바로 앞이에요. 정예 기동대를 소집해 뒀죠. 앗, 뭐죠?', `FemaleText_loc4`='集合点就在前面。我们已经召集了一支精锐部队——什么？', `FemaleText_loc5`='會合點就在前面。我們已經編組了一支精英小隊 - 什麼?', `FemaleText_loc7`='Nos acercamos al punto de encuentro. Hemos reunido a un grupo de... ¿Qué?' WHERE `ID`=71706;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아나랄라! 하늘이 우릴 저버리는군요. 여긴 위험해요!', `FemaleText_loc4`='Anar’alah！天空背弃了我们——这里不安全了！', `FemaleText_loc5`='該死!空中的狀況不妙 - 我們在上面這裡不安全!', `FemaleText_loc7`='¡Anar''alah! Los cielos nos traicionan. ¡Aquí corremos peligro!' WHERE `ID`=71707;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아래로! 모두 하강해라!', `FemaleText_loc4`='降落！全体降落！', `FemaleText_loc5`='下去!所有人下去!', `FemaleText_loc7`='¡Abajo! ¡Todo el mundo abajo!' WHERE `ID`=71708;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사님, 괜찮으세요?', `FemaleText_loc4`='勇士，你还好吧？', `FemaleText_loc5`='勇士，你還好嗎?', `FemaleText_loc7`='¿Te encuentras bien?' WHERE `ID`=71709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리를 기다리고 있었던 거예요. 병사들은 흩어졌고, 이제 우리뿐이에요.', `FemaleText_loc4`='他们一直在等着我们。部队被打散了，我们得靠自己了。', `FemaleText_loc5`='他們早就準備好要對付我們。我們的人四散各地，只能靠自己了。', `FemaleText_loc7`='Nos esperaban desde el principio. Nuestras tropas se han dispersado y estamos solos.' WHERE `ID`=71710;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기습은 물 건너 갔군요.', `FemaleText_loc4`='这还真是惊喜不断。', `FemaleText_loc5`='哼!還說什麼要偷襲呢。', `FemaleText_loc7`='Adiós al factor sorpresa...' WHERE `ID`=71711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='적이 물러나는군요. 재집결하기 전에 밀어붙여야 해요. 따라오세요!', `FemaleText_loc4`='他们退回去了。我们得在他们重整队伍前压上去。跟我来！', `FemaleText_loc5`='他們在撤退了。我們必須在他們集結之前繼續進攻。跟我來!', `FemaleText_loc7`='Se retiran. Debemos presionar antes de que se reagrupen. ¡Sígueme!' WHERE `ID`=71712;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='늘 하는 말이지만, 대담한 자가 승리하죠!', `FemaleText_loc4`='正如我所说——勇者无敌！', `FemaleText_loc5`='這就是我的信念 - 有膽量才能勝利!', `FemaleText_loc7`='Como suelo decir: ¡la victoria es de los valientes!' WHERE `ID`=71713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='입구가 막혔어요. 방벽을 파괴하세요!', `FemaleText_loc4`='入口被挡住了。破开它！', `FemaleText_loc5`='入口被擋住了。把它打下來!', `FemaleText_loc7`='La entrada está cerrada. ¡Rompe la barricada!' WHERE `ID`=71714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='빨리 움직여요! 보통 잔달라 트롤이 아니에요!', `FemaleText_loc4`='快行动——那可不是普通的赞达拉巨魔！', `FemaleText_loc5`='手腳快一點 - 這不是普通的贊達拉食人妖!', `FemaleText_loc7`='No bajes la guardia. Ese no es un Zandalari cualquiera.' WHERE `ID`=71715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 지키고 있는 저 가면이 방어막의 원천일 거예요! 파괴해요!', `FemaleText_loc4`='他们在保护那个面具。那一定是屏障的源头。摧毁它！', `FemaleText_loc5`='他們正在保護那個面具。那一定是屏障的能量來源。摧毀它!', `FemaleText_loc7`='Protegen aquella máscara. Debe de ser el origen de la barrera. ¡Destrúyela!' WHERE `ID`=71716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영혼 가면을 파괴해 방어막을 제거하세요!', `FemaleText_loc4`='快摧毁灵魂面具，解除屏障！', `FemaleText_loc5`='摧毀那個靈魂面具，解除屏障!', `FemaleText_loc7`='¡Destruye la máscara de espíritu para anular la barrera!' WHERE `ID`=71717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈이 가면을 지키고 있어요. 처치해요!', `FemaleText_loc4`='他守护着面具。杀了他！', `FemaleText_loc5`='他在保護面具。殺了他!', `FemaleText_loc7`='Está protegiendo la máscara. ¡Mátalo!' WHERE `ID`=71718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계속 밀어붙여요! 적이 혼란에 빠졌어요!', `FemaleText_loc4`='加油，他们开始溃散了！', `FemaleText_loc5`='加把勁，他們在潰敗了!', `FemaleText_loc7`='¡Sigue así! ¡Se están dispersando!' WHERE `ID`=71719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어막이 사라졌어요! 해냈어요!', `FemaleText_loc4`='护盾——消失了！我们成功了！', `FemaleText_loc5`='屏障 - 消失了!我們成功了!', `FemaleText_loc7`='¡El escudo ha caído! ¡Lo conseguimos!' WHERE `ID`=71720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 님이 괜히 추천한 게 아니군요. 덕분에 실패를 면했어요... 저도 살았고요.', `FemaleText_loc4`='吉安娜选对了人。你挽救了这个任务……还有我的生命。', `FemaleText_loc5`='難怪珍娜會推薦你。你讓這次的任務反敗為勝...還救了我的命。', `FemaleText_loc7`='Jaina tenía razón al recomendarte. Has salvado esta misión del desastre... y a mí de la muerte.' WHERE `ID`=71721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그게 바로 불굴의 얼라이언스 정신이죠!', `FemaleText_loc4`='这就是联盟的精神——勇往直前！', `FemaleText_loc5`='這就是聯盟該有的精神 - 無人能擋!', `FemaleText_loc7`='Así es el espíritu de la Alianza: ¡imparable!' WHERE `ID`=71722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베리사, 방어선을 구축하세요. 모데라는 감시의 수호물을 설치하고, 나라시는 보급품을 옮겨.', `FemaleText_loc4`='温蕾萨，去建防线。茉德拉，设下真视之眼。纳莱丝，把帐篷和补给运过来。', `FemaleText_loc5`='凡蕾莎，建好陣地。莫德菈，放置哨衛結界。娜拉希，開始傳送帳棚和補給品過來。', `FemaleText_loc7`='Vereesa, establece un perímetro. Modera, coloca los resguardos avizores. Narasi, teletransporta tiendas y suministros.' WHERE `ID`=71723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 각자 위치로! 적군이 사방에서 우릴 포위 중이다. 시간이 없다.', `FemaleText_loc4`='所有人，各就各位！我们周围都是敌人！千万不能够浪费时间了。', `FemaleText_loc5`='所有人堅守崗位!敵人從四面環繞我們!不能浪費時間!', `FemaleText_loc7`='¡Todo el mundo a sus puestos! ¡El enemigo nos rodea! No hay tiempo que perder.' WHERE `ID`=71724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 기대를 뛰어넘었군요. 당신의 용기와 의지 덕분에 우리가 이 섬에 자리를 잡을 수 있었어요. 자, 이제 시작이에요.', `FemaleText_loc4`='勇士，你的成就已经超出了我的预期。你所表现出的勇气与决心巩固了我们的根基。现在，真正的工作开始了。', `FemaleText_loc5`='勇士，你表現的比我期望的還更棒。我們在島上的位置已經安全，這要感謝你的勇氣和意志力。現在，真正的工作才要開始。', `FemaleText_loc7`='Superaste todas mis expectativas. Nuestra base en la isla es segura gracias a tu valor y tu determinación. Ahora empieza el verdadero trabajo.' WHERE `ID`=71725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘하셨어요. 이제 가죠.', `FemaleText_loc4`='干得好，英雄。我们前进吧。', `FemaleText_loc5`='做得好，英雄。我們繼續吧。', `FemaleText_loc7`='Buen trabajo. Sigamos adelante.' WHERE `ID`=71726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='트롤이 그렇죠, 뭐.', `FemaleText_loc4`='不出我所料。', `FemaleText_loc5`='食人妖就是食人妖。', `FemaleText_loc7`='No esperaba más de un trol.' WHERE `ID`=71727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='키린 토의 이름으로!', `FemaleText_loc4`='以肯瑞托之名！', `FemaleText_loc5`='以祈倫托之名!', `FemaleText_loc7`='¡En el nombre del Kirin Tor!' WHERE `ID`=71728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 방식이 마음에 들어요.', `FemaleText_loc4`='我喜欢你的风格，英雄。', `FemaleText_loc5`='我喜歡你的風格，英雄。', `FemaleText_loc7`='Me gusta tu estilo.' WHERE `ID`=71729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단한걸요!', `FemaleText_loc4`='令人印象深刻！', `FemaleText_loc5`='真不賴!', `FemaleText_loc7`='¡Impresionante!' WHERE `ID`=71730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라의 진짜 힘은 아직이다!', `MaleText_loc4`='呸！你们还没见识到赞达拉的全部力量呢！', `MaleText_loc5`='你還沒見識到贊達拉全部的力量!', `MaleText_loc7`='¡Bah! ¡Aún no han visto el poder de los Zandalari!' WHERE `ID`=71731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호리돈을 파락키 문에 돌진하게 합니다!', `MaleText_loc4`='$n驱使赫利东冲向法拉基之门！', `MaleText_loc5`='$n強迫哈里登衝向法拉奇的門!', `MaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Farraki!', `FemaleText_loc1`='$n|1이;가; 호리돈을 파락키 문에 돌진하게 합니다!', `FemaleText_loc4`='$n驱使赫利东冲向法拉基之门！', `FemaleText_loc5`='$n強迫哈里登衝向法拉奇的門!', `FemaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Farraki!' WHERE `ID`=71732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호리돈을 구루바시 문에 돌진하게 합니다!', `MaleText_loc4`='$n驱使赫利东冲向古拉巴什之门！', `MaleText_loc5`='$n強迫哈里登衝向古拉巴什的門!', `MaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Gurubashi!', `FemaleText_loc1`='$n|1이;가; 호리돈을 구루바시 문에 돌진하게 합니다!', `FemaleText_loc4`='$n驱使赫利东冲向古拉巴什之门！', `FemaleText_loc5`='$n強迫哈里登衝向古拉巴什的門!', `FemaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Gurubashi!' WHERE `ID`=71733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호리돈을 드라카리 문에 돌진하게 합니다!', `MaleText_loc4`='$n驱使赫利东冲向达卡莱之门！', `MaleText_loc5`='$n強迫哈里登衝向德拉克瑞的門!', `MaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Drakkari!', `FemaleText_loc1`='$n|1이;가; 호리돈을 드라카리 문에 돌진하게 합니다!', `FemaleText_loc4`='$n驱使赫利东冲向达卡莱之门！', `FemaleText_loc5`='$n強迫哈里登衝向德拉克瑞的門!', `FemaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Drakkari!' WHERE `ID`=71734;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호리돈을 아마니 문에 돌진하게 합니다!', `MaleText_loc4`='$n驱使赫利东冲向阿曼尼之门！', `MaleText_loc5`='$n強迫哈里登衝向阿曼尼的門!', `MaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Amani!', `FemaleText_loc1`='$n|1이;가; 호리돈을 아마니 문에 돌진하게 합니다!', `FemaleText_loc4`='$n驱使赫利东冲向阿曼尼之门！', `FemaleText_loc5`='$n強迫哈里登衝向阿曼尼的門!', `FemaleText_loc7`='¡$n obliga a Horridonte a cargar contra la puerta Amani!' WHERE `ID`=71735;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 공룡술사가 조종의 구슬을 떨어뜨립니다!', `MaleText_loc4`='赞达拉恐龙统领掉落了控制宝珠！', `MaleText_loc5`='贊達拉馭龍師掉下了一顆控獸寶珠!', `MaleText_loc7`='¡El dinomántico Zandalari suelta un orbe de control!', `FemaleText_loc1`='잔달라 공룡술사가 조종의 구슬을 떨어뜨립니다!', `FemaleText_loc4`='赞达拉恐龙统领掉落了控制宝珠！', `FemaleText_loc5`='贊達拉馭龍師掉下了一顆控獸寶珠!', `FemaleText_loc7`='¡El dinomántico Zandalari suelta un orbe de control!' WHERE `ID`=71736;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭탄을 설치했습니다. 영웅이여, 이 영광은 그대 것입니다.', `FemaleText_loc4`='起爆器到位了。英雄——这份殊荣属于你。', `FemaleText_loc5`='炸藥已經放好了 - 由你親手引爆吧。', `FemaleText_loc7`='Las cargas están en su sitio. Haz los honores.' WHERE `ID`=71737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위로 날아간다고 모를 줄 알았냐?!', `MaleText_loc4`='你以为自己能神不知鬼不觉的从我们头上飞过去？！', `MaleText_loc5`='你以為這樣子飛進來就沒有人會知道嗎?!', `MaleText_loc7`='¿Crees que puedes volar por aquí sin que nos demos cuenta?' WHERE `ID`=71738;
