UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135681|h[동쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135681|h[东部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135681|h[東側導雷管]|h|r燒毀，造成|cFFFF0000|Hspell:137176|h[迴路超載]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_unrelentingstorm.blp:20|t ¡El |cFFFF0000|Hspell:135681|h[conducto del este]|h|r se ha quemado y ha provocado |cFFFF0000|Hspell:137176|h[Circuitos sobrecargados]|h|r!' WHERE `ID`=71762;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135682|h[남쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135682|h[南部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135682|h[南側導雷管]|h|r燒毀，造成|cFFFF0000|Hspell:137176|h[迴路超載]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_unrelentingstorm.blp:20|t ¡El |cFFFF0000|Hspell:135682|h[conducto del sur]|h|r se ha quemado y ha provocado |cFFFF0000|Hspell:137176|h[Circuitos sobrecargados]|h|r!' WHERE `ID`=71763;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135683|h[서쪽 도관]|h|r이 소진되어 |cFFFF0000|Hspell:137176|h[과부하된 회로]|h|r 효과가 발생했습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t|cFFFF0000|Hspell:135683|h[西部导管]|h|r烧毁并引发了|cFFFF0000|Hspell:137176|h[导管短路]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135683|h[西側導雷管]|h|r燒毀，造成|cFFFF0000|Hspell:137176|h[迴路超載]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_unrelentingstorm.blp:20|t ¡El |cFFFF0000|Hspell:135683|h[conducto del oeste]|h|r se ha quemado y ha provocado |cFFFF0000|Hspell:137176|h[Circuitos sobrecargados]|h|r!' WHERE `ID`=71764;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 번에 하나씩 해결하자. 잔달라 트롤에 집중하라!', `MaleText_loc4`='一个个来，将士们。先集中解决赞达拉！', `MaleText_loc5`='一次解決一件事。專注攻擊贊達拉!', `MaleText_loc7`='Vamos paso a paso. ¡Primero los Zandalari!' WHERE `ID`=71765;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이야말로 내 앞에 무릎꿇고 자비를 구걸할 것이다.', `MaleText_loc4`='你会跪着求我饶命的，怪物。', `MaleText_loc5`='等你乞求饒命時，你就會跪下來。', `MaleText_loc7`='Serás TÚ quien se arrodille para pedir clemencia, monstruo.' WHERE `ID`=71766;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주! 천둥왕 폐하께 맞서려고 아무리 대군을 동원한들 소용없다. 곧 모두 그분 앞에 무릎을 꿇게 될 테니.', `MaleText_loc4`='祝踏岚！不管你召集多少帮手都没用。很快，所有人都将向陛下俯首称臣。', `MaleText_loc5`='塔蘭·祝!不管你們有多少人聯合對付雷王。很快，所有人都會跪在他面前。', `MaleText_loc7`='¡Taran Zhu! Da igual a cuántos envíes contra el Rey del Trueno. Pronto todos se arrodillarán ante él.' WHERE `ID`=71767;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 입상들이 초대 황제의 힘을 지니고 있네. 파괴하게!', `MaleText_loc4`='那些雕像掌握着始皇帝的力量。摧毁他们！', `MaleText_loc5`='這些雕像擁有始皇帝的力量。摧毀它們!', `MaleText_loc7`='Esas estatuas poseen el poder del primer emperador. ¡Destrúyelas!' WHERE `ID`=71768;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스, 문을 열게.', `MaleText_loc4`='陶矢，打开那些门。', `MaleText_loc5`='陶氏，把門打開。', `MaleText_loc7`='Taoshi, abre esas puertas.' WHERE `ID`=71769;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 함께 가세. 전우들이 후방을 지키는 동안 앞으로 나아가야 하네.', `MaleText_loc4`='勇士，跟我来。我们得继续前进，让你的同伴殿后。', `MaleText_loc5`='勇士，跟我來。我們必須在你同伴斷後的時候向前推進。', `MaleText_loc7`='Sígueme. Debemos avanzar mientras tus compañeros cubren la retaguardia.' WHERE `ID`=71770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕의 궁전이 저 앞에 있습니다. 이 섬에 먼저 거점을 구축해야 그의 요새를 공격할 수 있을 겁니다.', `FemaleText_loc4`='雷电之王的宫殿就在前面。在发动进攻前，我们必须在岛上建立一个据点。', `FemaleText_loc5`='雷王的宮殿就在前面。我們必須先搶下一個立足點才能突擊他的堡壘。', `FemaleText_loc7`='El palacio del Rey del Trueno se encuentra ante nosotros. Debemos establecer una posición en la isla antes de asaltar la fortaleza.' WHERE `ID`=71771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정님! 광산에서 잔달라 트롤이 접근합니다!', `FemaleText_loc4`='摄政王——矿洞那边的赞达拉又冲过来了！', `FemaleText_loc5`='攝政王 - 有更多贊達拉從礦坑殺過來了!', `FemaleText_loc7`='¡Señor regente, vienen más Zandalari de las minas!' WHERE `ID`=71772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망할 녀석들. 순찰대! 전장을 사수하라!', `MaleText_loc4`='该死的家伙。游侠们！守住这里！', `MaleText_loc5`='真該死。遊俠們，守住這裡!', `MaleText_loc7`='Malditos sean. ¡Forestales! ¡Mantengan la posición!' WHERE `ID`=71773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신이 무슨 필요가 있나? 우리에겐 천둥왕이 계시다!', `MaleText_loc4`='谁还需要神？我们有雷电之王！', `MaleText_loc5`='誰需要神了?我們已經有雷王!', `MaleText_loc7`='¿Quién necesita un dios? ¡Tenemos al Rey del Trueno!' WHERE `ID`=71774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤들아! 꾸물거리지 마라. 여긴 거의 다 끝냈다.', `MaleText_loc4`='巨魔——都行动起来。我就快完成了。', `MaleText_loc5`='食人妖 - 有點用好嗎?我儀式都快完成了。', `MaleText_loc7`='Trols, hagan algo útil. Ya casi termino lo mío.' WHERE `ID`=71775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부! 또 신을 만들려 하는구나. 언제 정신을 차리겠느냐?', `MaleText_loc4`='山怖！你又妄想造神了。你何时才能吸取教训？', `MaleText_loc5`='衫布!你又想要創造神了。你什麼時候才會學乖?', `MaleText_loc7`='¡Shan Bu! ¿Otra vez intentas crear un dios? ¿Cuándo aprenderás?' WHERE `ID`=71776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 트롤 지원군이 오고 있네.', `MaleText_loc4`='赞达拉的援军就要来了。', `MaleText_loc5`='贊達拉的援軍要來了。', `MaleText_loc7`='¡Llegan refuerzos Zandalari!' WHERE `ID`=71777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야리아, 치유를 부탁하네! 타오스, 후방을 맡게!', `MaleText_loc4`='雅丽亚——我们需要治疗！陶矢——掩护后方！', `MaleText_loc5`='雅里亞 - 我們需要更多治療!陶氏，掩護後方!', `MaleText_loc7`='¡Yalia, más sanación! ¡Taoshi, cubre la retaguardia!' WHERE `ID`=71778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='덤벼라, 샨 부! 천둥왕의 궁정은 겁쟁이 소굴이었더냐?', `MaleText_loc4`='冲我来，山怖！难道雷电之王的朝堂上全是懦夫吗？', `MaleText_loc5`='面對我，衫布!難道雷王的宮殿裡全是懦夫?', `MaleText_loc7`='¡Ven, Shan Bu! ¿O es que la corte del Rey del Trueno es un nido de cobardes?' WHERE `ID`=71779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 나락크! 존귀하신 천둥왕 폐하를 보호하라.', `MaleText_loc4`='来吧，纳拉克！保护陛下！', `MaleText_loc5`='蘇醒吧，納拉卡!保護我們摯愛的皇帝。', `MaleText_loc7`='¡Levántate, Nalak! Protege a nuestro emperador.' WHERE `ID`=71780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파 놈아, 네 머리를 천둥왕께 가져가면 정말 기뻐하실 거다.', `MaleText_loc4`='等我将你们的脑袋呈上去，陛下一定会很满意的，影踪派。', `MaleText_loc5`='等我把你的頭帶到皇帝面前，他會很滿意的，影潘。', `MaleText_loc7`='El emperador estará muy satisfecho cuando le entregue tu cabeza, Shadopan.' WHERE `ID`=71781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하찮은 것들이 아직 내 힘을 알지 못하는구나.', `MaleText_loc4`='那些废物还没见识过我的力量。', `MaleText_loc5`='卑微的人們還不明白我的力量。', `MaleText_loc7`='Los indignos aún no conocen mi poder.' WHERE `ID`=71782;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁신 알축라, 내 힘을 받아들여라.', `MaleText_loc4`='战神阿尔图克拉，接纳我的力量。', `MaleText_loc5`='戰神阿裘卡拉，讓我的力量與你結合。', `MaleText_loc7`='Dios de la guerra Al''chukla, une mi fuerza a la tuya.' WHERE `ID`=71783;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사제들이 수호자에게 로아를 주입하고 있어요! 반드시 막아야 해요!', `FemaleText_loc4`='那些祭司正在对那些侍卫灌注神灵之力！必须阻止他们！', `FemaleText_loc5`='祭司在用他們羅亞的力量強化守護者!一定要阻止他們!', `FemaleText_loc7`='¡Los sacerdotes infunden sus loa al guardián! ¡Hay que detenerlos!' WHERE `ID`=71784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요!', `FemaleText_loc4`='赶快行动！', `FemaleText_loc5`='動作要快啊!', `FemaleText_loc7`='¡Date prisa!' WHERE `ID`=71785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호자의 힘이 커지고 있어요! 늦기 전에 어서 처치하세요!', `FemaleText_loc4`='守卫的力量正在增长！快阻止他们！', `FemaleText_loc5`='守護者的力量越來越強了!快點殺掉他們，否則就來不及了!', `FemaleText_loc7`='¡El poder del guardián aumenta! ¡Mátalo antes de que sea demasiado tarde!' WHERE `ID`=71786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호자가 깨어났어요! 어서 쓰러뜨리세요!', `FemaleText_loc4`='守卫醒过来了！快摧毁它！', `FemaleText_loc5`='守護者醒來了!毀掉它!', `FemaleText_loc7`='¡El guardián ha despertado! ¡Acaba con él!' WHERE `ID`=71787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 놈의 힘을 뺏었어요. 이제 목숨을 뺏을 차례예요!', `FemaleText_loc4`='你剥夺了它的力量。现在，取走它的性命吧！', `FemaleText_loc5`='你已經奪走它的力量了，現在趕緊奪走它的生命!', `FemaleText_loc7`='Le has robado su fuerza. ¡Ahora róbale la vida!' WHERE `ID`=71788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='2분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在2分钟后开始！', `MaleText_loc5`='戰鬥在2分鐘內開始!', `MaleText_loc7`='¡La batalla comienza en 2 minutos!' WHERE `ID`=71789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1분 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在1分钟后开始！', `MaleText_loc5`='戰鬥在1分鐘內開始!', `MaleText_loc7`='¡La batalla comienza en 1 minuto!' WHERE `ID`=71790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='30초 후 전투가 시작됩니다!', `MaleText_loc4`='战斗将在30秒后开始！', `MaleText_loc5`='戰鬥在30秒內開始!', `MaleText_loc7`='¡La batalla comienza en 30 segundos!' WHERE `ID`=71791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 시작되었습니다!', `MaleText_loc4`='战斗开始了！', `MaleText_loc5`='戰鬥開始了!', `MaleText_loc7`='¡La batalla ha comenzado!' WHERE `ID`=71792;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사제들이 수호자에게 로아를 주입하고 있어요! 반드시 막아야 해요!', `FemaleText_loc4`='那些祭司正在对那些侍卫灌注神灵之力！必须阻止他们！', `FemaleText_loc5`='祭司在用他們羅亞的力量強化守護者!一定要阻止他們!', `FemaleText_loc7`='¡Los sacerdotes infunden sus loa al guardián! ¡Hay que detenerlos!' WHERE `ID`=71793;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호자의 힘이 커지고 있어요! 늦기 전에 어서 처치하세요!', `FemaleText_loc4`='守卫的力量正在增长！快阻止他们！', `FemaleText_loc5`='守護者的力量越來越強了!快點殺掉他們，否則就來不及了!', `FemaleText_loc7`='¡El poder del guardián aumenta! ¡Mátalo antes de que sea demasiado tarde!' WHERE `ID`=71794;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='서두르세요!', `FemaleText_loc4`='你必须尽快行动！', `FemaleText_loc5`='動作要快啊!', `FemaleText_loc7`='¡Date prisa!' WHERE `ID`=71795;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='수호자가 깨어났어요! 어서 쓰러뜨리세요!', `FemaleText_loc4`='守卫醒过来了！快摧毁它！', `FemaleText_loc5`='守護者醒來了!毀掉它!', `FemaleText_loc7`='¡El guardián ha despertado! ¡Acaba con él!' WHERE `ID`=71796;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신은 놈의 힘을 뺏었어요. 이제 목숨을 뺏을 차례예요!', `FemaleText_loc4`='你剥夺了它的力量。现在，取走它的性命吧！', `FemaleText_loc5`='你已經奪走它的力量了，現在趕緊奪走它的生命!', `FemaleText_loc7`='Le has robado su fuerza. ¡Ahora róbale la vida!' WHERE `ID`=71797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 침입자들에게 본때를 보여줘라. 온 세계가 내 앞에서 전율하도록.', `MaleText_loc4`='让这些入侵者看看我的厉害，让万民在我面前颤栗。', `MaleText_loc5`='拿這些入侵者殺雞儆猴，讓所有王國都在我面前顫抖。', `MaleText_loc7`='Usa a estos invasores de ejemplo, de manera que todas las naciones tiemblen ante mí.' WHERE `ID`=71798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두를 쓰러트리겠습니다!', `MaleText_loc4`='万物都将臣服于我们！！', `MaleText_loc5`='敵人全都會倒下!', `MaleText_loc7`='¡Todos caerán ante nosotros!' WHERE `ID`=71799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부, 안마당을 지켜라. 내 작품을 본 자는 살아남을 수 없다.', `MaleText_loc4`='山怖，守住内庭。绝不能让活人见到我的造物。', `MaleText_loc5`='衫布，守好內庭。看見我這傑作的人一個都不能活著。', `MaleText_loc7`='Shan Bu, asegura el patio interior. Nadie contempla mi obra y vive para contarlo.' WHERE `ID`=71800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하의 뜻에 따르겠습니다!', `MaleText_loc4`='谨遵陛下旨意！', `MaleText_loc5`='如吾皇所願!', `MaleText_loc7`='¡Como ordene mi emperador!' WHERE `ID`=71801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에는 매우 강력한 마법이 깃들어 있습니다. 그 힘을 이용할 수만 있다면, 누구도 우리를 막지 못할 겁니다.', `MaleText_loc4`='这座岛屿蕴藏着极其强大的魔力。如果我们能驾驭它，就必将所向无敌。', `MaleText_loc5`='這座島蘊含十分強大的魔力，只要能掌控它，就沒有人能夠阻止我們。', `MaleText_loc7`='Esta isla alberga una magia muy poderosa. Si conseguimos dominarla, nadie se interpondrá en nuestro camino.' WHERE `ID`=71802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳의 잔달라 부족은 제가 잘 알지 못하는 마법을 사용합니다. 바로 비전 마력을 어둠의 힘과 합치는 것이죠. 끔찍하고도 위험한 조합입니다.', `MaleText_loc4`='这里的赞达拉巨魔在使用一种我不了解的黑暗魔法。他们将奥术力量与暗影力量混合，这种做法非常恐怖，而且危险。', `MaleText_loc5`='這兒的贊達拉食人妖使用的黑暗魔法，是我不熟悉的。他們將秘法能量與暗影能量混在一起，創造出危險而恐怖的組合。', `MaleText_loc7`='Estos Zandalari practican una magia oscura que no conozco. Mezclan el poder Arcano con el de las Sombras; es una combinación temible y peligrosa.' WHERE `ID`=71803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 지역에서 발산되는 마법은 경이롭습니다, $c님. 한시라도 빨리 그들의 유물을 연구하고 싶군요. 정말 배울 게 많을 겁니다.', `MaleText_loc4`='这个地区散发出来的魔力太神奇了，$c。我已经迫不及待地要研究他们的神器了。我们有太多东西要学了。', `MaleText_loc5`='這裡散發的魔法能量實在太驚人了，$c，我等不及想研究他們的法器，一定能學到很多的東西。', `MaleText_loc7`='La magia que emana de esta zona es fascinante, $c. Estoy ansioso por estudiar sus artefactos. Tenemos mucho que aprender.' WHERE `ID`=71804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 길을 돌아다니는 골렘을 보신 적 있습니까, $c님? 영혼이 잔달라 부족의 노예가 되어 골렘 안에 구속되어 있습니다.$b$b모구와 잔달라 부족은 우리 생각보다 훨씬 더 닮아 있는 지도 모릅니다.', `MaleText_loc4`='你看到那些在路上游荡的魔像了吗，$c？那些被束缚的灵魂将永世侍奉赞达拉。$b$b或许，魔古族和赞达拉比我们想象中更加相似。', `MaleText_loc5`='你有看見在這邊的路上巡邏的魔象嗎，$c?被封印的靈魂，永遠被贊達拉奴役、不得超脫。$b$b魔古和贊達拉的相似程度，或許其實遠超乎我們的預期啊。', `MaleText_loc7`='¿Has visto alguna vez los gólems que recorren estos caminos, $c? Son espíritus forzados a servir a los Zandalari por toda la eternidad.$b$bA lo mejor los mogu y los Zandalari se parecen más de lo que pensábamos.' WHERE `ID`=71805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠 못 드는 영혼이 당신의 영혼을 쫓습니다. 잡히면 안 됩니다!', `MaleText_loc4`='一个躁动之魂正在追逐你的灵魂。别让它碰到你！', `MaleText_loc5`='有個受擾的靈魂正在追你的靈魂。別讓他碰到你!', `MaleText_loc7`='Un espíritu inquieto persigue tu alma. ¡No dejes que te alcance!' WHERE `ID`=71806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흡수하는 영혼이 당신의 영혼을 쫓습니다. 주문을 중지시키려면 숨으십시오!', `MaleText_loc4`='一个枯竭之魂正在吸取你的灵魂。躲开他，破坏他的法术！', `MaleText_loc5`='有個吞噬之靈正在吸取你的靈魂，快點躲開它以中斷法術!', `MaleText_loc7`='Un espíritu drenador te está drenando el alma. ¡Escóndete de él para romper el hechizo!' WHERE `ID`=71807;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 지금 당신 얘기를 하던 중이었어요.', `FemaleText_loc4`='啊！英雄，我们正谈到你呢。', `FemaleText_loc5`='啊!英雄，我們正談到你。', `FemaleText_loc7`='¡Ah! Justo estábamos hablando de ti.' WHERE `ID`=71808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기하시오. 타오스의 제안은 너무 위험하오.', `MaleText_loc4`='算了吧。陶矢的提议太危险了。', `MaleText_loc5`='這不重要，陶氏的提案太危險了。', `MaleText_loc7`='No importa. La propuesta de Taoshi es muy peligrosa.' WHERE `ID`=71809;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕을 물리치려면 항만에 침입해야 해요. 지금은 대담한 계획이 필요할 때라고요!', `FemaleText_loc4`='如果想要打倒雷电之王，我们就必须先攻破船坞。现在应该采取行动了！', `FemaleText_loc5`='如果我們要擊敗雷王，我們必須偷襲船塢。現在正是大膽計畫的好時候!', `FemaleText_loc7`='Si queremos derrocar al Rey del Trueno, es necesario apoderarnos del astillero. ¡Es momento de pensar en ideas audaces!' WHERE `ID`=71810;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 잘 들으세요. 우린 밤에 항만을 공격할거예요. 당신이 길들인 이 놀라운 야수를 이용해서 말이죠.', `FemaleText_loc4`='勇士，听我说：我们将在夜里，利用你驯服的这头神奇的野兽袭击船坞。', `FemaleText_loc5`='勇士，聽我說: 我們將用你所馴服的那頭野獸，在夜晚攻擊船塢。', `FemaleText_loc7`='Escúchame bien: asaltaremos el astillero de noche utilizando la magnífica bestia que domaste.' WHERE `ID`=71811;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='내부에 침입하면 잔달라 함선을 파괴할거예요. 그리고 혼란을 틈타 안마당으로 잠입해서 관문을 열도록 하죠.', `FemaleText_loc4`='进去之后，我们要破坏赞达拉的船只，并趁着混乱溜进庭院，从内侧打开大门。', `FemaleText_loc5`='等進去以後，我們把贊達拉的船弄沉。在混亂中，我們潛進中庭，從裡面把門打開。', `FemaleText_loc7`='Una vez dentro, sabotearemos el barco Zandalari. En medio del caos, nos infiltraremos en el patio y abriremos las puertas.' WHERE `ID`=71812;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아요! 힘보다는 머리싸움이죠.', `FemaleText_loc4`='好主意！头脑总能胜过蛮力。', `FemaleText_loc5`='我喜歡這點子!以智取勝。', `FemaleText_loc7`='¡Me encanta! Ingenio antes que fuerza bruta.' WHERE `ID`=71813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 타오스. 이 용사가 찬성한다면 임무를 진행해도 좋아.', `MaleText_loc4`='好吧，陶矢。如果这位勇士同意，任务就可以进行。', `MaleText_loc5`='好吧，陶氏。如果我們這位勇士同意，你們就那樣去進行吧。', `MaleText_loc7`='Muy bien, Taoshi. Si todos estamos de acuerdo, seguiremos con la misión.' WHERE `ID`=71814;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감사합니다, 맹주님. 반드시 해내겠습니다.', `FemaleText_loc4`='谢谢你，祝掌门。我不会让你失望的。', `FemaleText_loc5`='謝謝你，祝宗主。我不會讓你失望。', `FemaleText_loc7`='Gracias, Lord Zhu. No te decepcionaré.' WHERE `ID`=71815;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비가 끝나면 알려주세요.', `FemaleText_loc4`='准备好就告诉我一声！', `FemaleText_loc5`='等你準備好，跟我說!', `FemaleText_loc7`='Habla conmigo cuando quieras empezar.' WHERE `ID`=71816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 영웅이여, 지금 그대 이야기를 하던 중이오.', `MaleText_loc4`='啊！英雄，我们正谈到你呢。', `MaleText_loc5`='啊，勇士。我們正提到你。', `MaleText_loc7`='¡Ah! Justo estábamos hablando de ti.' WHERE `ID`=71817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 대담한 면이 마음에 드는 것이오. 만약 우리가 항만을 파괴한다면, 잔달라 트롤의 추가 지원군을 막아낼 수 있소.', `MaleText_loc4`='这正是这个计划吸引我的地方。如果我们攻破船坞，就能防止魔古族获得更多的赞达拉援军。', `MaleText_loc5`='這個計畫的大膽正是讓我覺得有趣之處。如果我們攻進船塢，我們就能截斷增援魔古的贊達拉軍隊。', `MaleText_loc7`='La temeridad del plan es precisamente lo que me intriga. Si nos apoderamos de su astillero, los mogu se quedarán sin refuerzos Zandalari.' WHERE `ID`=71818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼의 격노에 당했습니다. 도망치십시오!', `MaleText_loc4`='你受到了灵魂之怒的影响。快跑开！', `MaleText_loc5`='你已經受到了亡魂之怒的影響。趕緊跑開!', `MaleText_loc7`='Te han afligido con Ira de los espíritus. ¡Corre!' WHERE `ID`=71819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='맹주여, 전쟁에서 승리하려면 단호한 행동이 필요하오.', `MaleText_loc4`='你也明白，只有果断行动才能赢得战争，祝掌门。', `MaleText_loc5`='你一定也同意果斷的行動才能贏得戰爭，祝宗主。', `MaleText_loc7`='Estarás de acuerdo con que los actos firmes ganan guerras, Lord Zhu.' WHERE `ID`=71820;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='경비병 여섯... 아니, 일곱이 공중에서 순찰을 도는군요.', `FemaleText_loc4`='我看到六……不，七个守卫在天上巡逻。', `FemaleText_loc5`='我看得到六個...不，七個警衛在空中巡邏。', `FemaleText_loc7`='Cuento seis... no, siete guardias que nos sobrevuelan.' WHERE `ID`=71821;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 명은 유난히 하늘 높이 날고 있어요. 홀로 먼 바다 위까지 순찰을 도는군요. 조심성이 없어 보이네요. 놈을 이용하죠.', `FemaleText_loc4`='有一个比其他人飞得都高……他一直独自在海面上盘旋。他脱队了。这是个机会。', `FemaleText_loc5`='其中一個飛得比較高...他獨自在水上繞得比較遠。他的路線延伸太遠了。我們可以利用這點。', `FemaleText_loc7`='Uno de ellos vuela más alto y se aleja sobre el agua, solo. Extiende demasiado su ronda. Esa será nuestra oportunidad.' WHERE `ID`=71822;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그를 제압하고 놈의 경로로 이동해요. 어서 가죠!', `FemaleText_loc4`='我们得干掉他，并利用他的航线。动手！', `FemaleText_loc5`='讓我們搞定他取代他潛入敵陣。走吧!', `FemaleText_loc7`='Lo neutralizaremos y tomaremos su ruta. ¡Vamos!' WHERE `ID`=71823;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조금만 더...', `FemaleText_loc4`='再靠近一点……', `FemaleText_loc5`='再近一點點...', `FemaleText_loc7`='Un poco más cerca...' WHERE `ID`=71824;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하앗!', `FemaleText_loc4`='呀！', `FemaleText_loc5`='耶!', `FemaleText_loc7`='¡Sí!' WHERE `ID`=71825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔달라 놈들이 생각보다 신중하군요. 보세요. 순찰병들이 우글거려요.', `FemaleText_loc4`='赞达拉比我预想得还要警觉。看下面——全是巡逻兵。', `FemaleText_loc5`='贊達拉比我想像中還要小心。看看下面 - 到處都是守衛。', `FemaleText_loc7`='Los Zandalari son más precavidos de lo que esperaba. Mira ahí abajo. Hay patrullas por todas partes.' WHERE `ID`=71826;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 궁수들이 선착장을 지키고 있군요.', `FemaleText_loc4`='那些弓箭手密切监视着港区。', `FemaleText_loc5`='那些弓箭手很小心地警戒著船塢。', `FemaleText_loc7`='Los arqueros vigilan atentamente la zona de carga.' WHERE `ID`=71827;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그리고 주술사들이 사방에 감시의 수호물을 배치했어요.', `FemaleText_loc4`='他们的萨满用岗哨图腾拉起了一张警戒网。', `FemaleText_loc5`='而他們的薩滿放置了一整批的崗哨圖騰。', `FemaleText_loc7`='Y los chamanes han desplegado una red de tótems centinela.' WHERE `ID`=71828;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기, 이 독침으로 궁수들을 최대한 많이 쓰러뜨리세요.', `FemaleText_loc4`='给，用这些飞镖尽量多打倒一些弓箭手。', `FemaleText_loc5`='來，用這些飛鏢盡可能地解決弓箭手。', `FemaleText_loc7`='Toma. Incapacita con estos dardos a todos los arqueros que puedas.' WHERE `ID`=71829;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='연막탄으로 감시의 수호물들의 시야를 가리세요.', `FemaleText_loc4`='这些烟雾弹可以蒙蔽岗哨图腾。', `FemaleText_loc5`='這些煙霧彈能使崗哨圖騰失去作用。', `FemaleText_loc7`='Estas bombas de humo cegarán a los tótems centinela.' WHERE `ID`=71830;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기서 계속 맴돌고 있을 시간이 없어요. 제가 다음 계획을 짜는 동안 뭐든 해보세요.', `FemaleText_loc4`='我们不能一直这样转圈。行动起来，我来想想下一步的计划。', `FemaleText_loc5`='我們不能在這裡繞太久。在我思考下一步計畫時看看你能做些什麼。', `FemaleText_loc7`='No podemos sobrevolar mucho tiempo. Haz lo que puedas mientras planeo el siguiente paso.' WHERE `ID`=71831;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='방어망을 더 무력화시켜야 들어갈 수 있어요! 한 바퀴 더 돌아야겠군요.', `FemaleText_loc4`='得多消灭一些防御部队，否则我们永远也进不去！再转一圈。', `FemaleText_loc5`='我們必須解除更多的防禦，否則我們永遠都進不去!再試試看吧。', `FemaleText_loc7`='¡Debemos deshabilitar más defensas o no conseguiremos entrar nunca! Vuelve a dar la vuelta.' WHERE `ID`=71832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깨어나라, 후썽! 부두를 맡기겠다. 아무도 폐하의 관문을 지나지 못하게 하라.', `MaleText_loc4`='醒来吧，虎申！你来负责码头。不要让任何人通过陛下的大门。', `MaleText_loc5`='起身吧，胡聖!守住碼頭是你的職責。別讓任何人穿過皇上的大門。', `MaleText_loc7`='¡Despierta, Hu''seng! Los muelles son responsabilidad tuya. Que nadie atraviese las puertas.' WHERE `ID`=71833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 뜻을 받들어, 명을 이행하겠습니다.', `MaleText_loc4`='雷电之王的旨意必将实现。', `MaleText_loc5`='這是雷王的意志;我會完成它。', `MaleText_loc7`='Es la voluntad del Rey del Trueno; así se hará.' WHERE `ID`=71834;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간이 없어요. 저 배에 올라타야 해요.', `FemaleText_loc4`='时间到了。我们得登上那条船。', `FemaleText_loc5`='我們沒時間了。我們需要上那條船。', `FemaleText_loc7`='Se nos acaba el tiempo. Hay que subir a ese barco.' WHERE `ID`=71835;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뱃머리에 있는 공성 무기들도 파괴하죠. 그리고 갑판 밑으로 가서 선장을 찾아봐요.', `FemaleText_loc4`='我们得破坏对着船头的攻城武器，然后到甲板下面去找船长。', `FemaleText_loc5`='我們先把船頭的攻城武器弄壞。然後去下面的船艙找船長。', `FemaleText_loc7`='Deberíamos sabotear las armas de asedio de proa. Luego bajaremos a la bodega y buscaremos al capitán.' WHERE `ID`=71836;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='숨을 고르시고... 다가가서 저들을 무력화시키세요.', `FemaleText_loc4`='放松点……靠过去，放倒他们。', `FemaleText_loc5`='放輕鬆...靠近，然後解決他們。', `FemaleText_loc7`='Ten mucho cuidado... Acércate e incapacítalos.' WHERE `ID`=71837;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 못생긴 놈을 맡죠.', `FemaleText_loc4`='我来对付那个丑八怪。', `FemaleText_loc5`='我來解決比較醜的那個。', `FemaleText_loc7`='Yo me encargo del feo.' WHERE `ID`=71838;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 방식처럼 조용하지는 않았지만, 성공했네요.', `FemaleText_loc4`='没我想得那么安静，但还是成功了。', `FemaleText_loc5`='我原本希望騷動再小一點的，不過能搞定就好。', `FemaleText_loc7`='No fue tan silencioso como me gustaría, pero funcionó.' WHERE `ID`=71839;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이걸 처음 발견하는 트롤은 아마 깜짝 놀라게 될 거예요. 어서 움직이죠.', `FemaleText_loc4`='巨魔一旦触发它们，就会得到一个意想不到的惊喜。我们继续。', `FemaleText_loc5`='下一個來碰這些東西的食人妖會倒大楣。我們走吧。', `FemaleText_loc7`='El siguiente trol que se acerque se llevará una sorpresa muy desagradable. Sigamos adelante.' WHERE `ID`=71840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 느긋하게 코를 곱니다.', `MaleText_loc4`='%s安详地打着鼾。', `MaleText_loc5`='%s安詳地打著呼。', `MaleText_loc7`='%s ronca tranquilamente.' WHERE `ID`=71841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음- 뭐지? 밀항자다!', `MaleText_loc4`='嗯——什么？入侵者！', `MaleText_loc5`='嗯...嗯?有潛入者!', `MaleText_loc7`='¿Qué? ¡Polizones!' WHERE `ID`=71842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌의 저항이 이 정도라면, 이 땅은 곧 우리 것이 될 거다!', `MaleText_loc4`='如果熊猫人就这点水平，那这片土地很快就得归我们了！', `MaleText_loc5`='如果抵抗我們的熊貓人只有這種程度，整塊大陸很快就是我們的了!', `MaleText_loc7`='Si la resistencia pandaren es de este calibre, ¡nos apoderaremos de esta tierra en poco tiempo!' WHERE `ID`=71843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아하, 간지럽군. 이제 장난은 끝이다.', `MaleText_loc4`='哦呵呵，你是在给我挠痒痒。我已经玩够了。', `MaleText_loc5`='噢，呵，你在替我抓癢。我跟你玩夠啦。', `MaleText_loc7`='Oh, jo, jo, me haces cosquillas. Pero basta de juegos.' WHERE `ID`=71844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 침몰하지 않아!', `MaleText_loc4`='我是永不沉没的！', `MaleText_loc5`='我永不會倒下!', `MaleText_loc7`='¡Nada me HUNDE!' WHERE `ID`=71845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌... 살아서 나갈 수... 없다.', `MaleText_loc4`='你们……休想活着……逃出这里……', `MaleText_loc5`='你不會活著...離開這裡。', `MaleText_loc7`='Nadie saldrá... con vida.' WHERE `ID`=71846;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='앞마당으로 향하는 관문은 저 언덕 위에 있어요.', `FemaleText_loc4`='庭院的大门就在那座山上。', `FemaleText_loc5`='中庭的門就在那山丘上。', `FemaleText_loc7`='Por esa colina se llega a la puerta del patio.' WHERE `ID`=71847;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='감시의 수호물 곁에는 가지 마세요.', `FemaleText_loc4`='记住，躲开那些岗哨图腾。', `FemaleText_loc5`='記得躲開那些崗哨圖騰。', `FemaleText_loc7`='Recuerda: no te acerques a los tótems centinela.' WHERE `ID`=71848;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 가요.', `FemaleText_loc4`='我们走。', `FemaleText_loc5`='我們走吧。', `FemaleText_loc7`='Vamos.' WHERE `ID`=71849;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠시만요...', `FemaleText_loc4`='等等……', `FemaleText_loc5`='等一下...', `FemaleText_loc7`='Espera…' WHERE `ID`=71850;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가세요!', `FemaleText_loc4`='走！', `FemaleText_loc5`='走!', `FemaleText_loc7`='¡Ahora!' WHERE `ID`=71851;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저들이 우리 선물을 찾은 것 같네요.', `FemaleText_loc4`='他们好像发现那个小礼物了。', `FemaleText_loc5`='聽起來他們找到我們的小禮物了。', `FemaleText_loc7`='Parece que ya encontraron nuestro regalito.' WHERE `ID`=71852;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기, 연막 안으로 오세요!', `FemaleText_loc4`='过来！到烟雾里来！', `FemaleText_loc5`='這裡!來煙霧裡面!', `FemaleText_loc7`='¡Aquí! ¡En el humo!' WHERE `ID`=71853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모습을 드러내라, 꼬맹이들아!', `MaleText_loc4`='躲够了没，小鬼们！', `MaleText_loc5`='別再藏了，小傢伙們!', `MaleText_loc7`='¡Dejen de esconderse, pequeñitos!' WHERE `ID`=71854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망갈 곳은 없다. 빠져 나가고 싶다면 나를 상대해라!', `MaleText_loc4`='你们无路可逃了。唯一的出路就是穿过我！', `MaleText_loc5`='你們逃不掉了。除非踏過我的屍體離開這裡!', `MaleText_loc7`='No escaparán. ¡Tendrán que pasar por mí si quieren salir!' WHERE `ID`=71855;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='널 상대하라고? 못 할것 없지.', `FemaleText_loc4`='穿过你是吗？这应该没问题。', `FemaleText_loc5`='踏過你的屍體?我想我們可以做到。', `FemaleText_loc7`='¿Pasarte? No creo que haya problema.' WHERE `ID`=71856;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='배를 걷어차줄까, 아니면 갈비뼈를 부숴줄까?', `FemaleText_loc4`='你想要我怎么穿过你呢？', `FemaleText_loc5`='你希望我們踏過肚子，還是胸口?', `FemaleText_loc7`='¿Prefieres que pasemos a través de tu estómago o tu tórax?' WHERE `ID`=71857;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 관문은 왕가의 칙령에 의해 봉인되었다.', `MaleText_loc4`='这些大门已经奉旨关闭了。', `MaleText_loc5`='聖旨下令這些門已封閉。', `MaleText_loc7`='Las puertas están selladas por decreto imperial.' WHERE `ID`=71858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너, 판다렌! 다시 쇠사슬에 묶여있게 해주마!', `MaleText_loc4`='你，熊猫人！你很快就会重新戴上镣铐。', `MaleText_loc5`='你，熊貓人!你會回到你該待的籠子裡!', `MaleText_loc7`='¡Pandaren! Volverás a las cadenas a las que perteneces.' WHERE `ID`=71859;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 작은 친구는 쓸모가 없군.', `MaleText_loc4`='你的小伙伴就任我处置了。', `MaleText_loc5`='你的小小朋友派不上用場。', `MaleText_loc7`='Tu camarada es prescindible.' WHERE `ID`=71860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자들은 처형당할지어다!', `MaleText_loc4`='入侵者必将伏诛！', `MaleText_loc5`='入侵者將被處決!', `MaleText_loc7`='¡Los intrusos serán ejecutados!' WHERE `ID`=71861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='출입, 금지다!', `MaleText_loc4`='滚、开！', `MaleText_loc5`='出去!', `MaleText_loc7`='¡FUERA!' WHERE `ID`=71862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 모두 끝장이야!', `MaleText_loc4`='你们死定了！', `MaleText_loc5`='你完蛋了!', `MaleText_loc7`='¡Están acabados!' WHERE `ID`=71863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 해하는 것은 곧 폐하를 해하는 것이다! 그분께선 이런 모욕을 용납하지 않으리라!', `MaleText_loc4`='攻击我就等于攻击陛下！他是不会接受这种侮辱的！', `MaleText_loc5`='攻擊我就像攻擊聖上!他不會忍受這樣的褻瀆!', `MaleText_loc7`='¡Atacarme es atacar a su Majestad! ¡Él no tolerará esta ofensa!' WHERE `ID`=71864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도... 지나가지...', `MaleText_loc4`='谁也……休想……', `MaleText_loc5`='沒人...能...', `MaleText_loc7`='Ninguno... debe...' WHERE `ID`=71865;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='승리했군요! 이제 관문으로 가요. 천둥왕의 모든 병력이 우리를 덮치기 전에요!', `FemaleText_loc4`='干得好！现在——去门口。趁雷电之王的大军还没过来！', `FemaleText_loc5`='打得好!現在 - 去大門那裡。再拖下去，雷王整個軍隊就會包圍我們了!', `FemaleText_loc7`='¡Buen combate! Ahora, a las puertas. Antes de que se nos venga encima todo el ejército del Rey del Trueno.' WHERE `ID`=71866;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순찰대! 경첩을 부수고 문을 고정해라!', `FemaleText_loc4`='游侠们——破坏铰链。把门打开！', `FemaleText_loc5`='遊俠們 - 粉碎鉸鏈。頂著門口!', `FemaleText_loc7`='Forestales, rompan las bisagras. ¡Que las puertas se queden abiertas!' WHERE `ID`=71867;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계획이 성공했어요! 둘이서 한 군단 몫의 일을 해냈군요.', `FemaleText_loc4`='计划成功了！你们俩简直抵得上一整支军队。', `FemaleText_loc5`='你們的計畫成功了!你們兩個人達成了一整支軍隊才能做到的事。', `FemaleText_loc7`='¡Tu plan funcionó! Entre los dos realizaron el trabajo de todo un ejército.' WHERE `ID`=71868;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 친구 솜씨는 이제 음영파 내에서도 전설적인 수준이에요.', `FemaleText_loc4`='我同伴出色的战斗技巧已经迅速在影踪派中传开了。', `FemaleText_loc5`='我這位夥伴的戰技已經在影潘中成為傳說了。', `FemaleText_loc7`='Tu técnica de combate se está convirtiendo en una leyenda entre los Shadopan.' WHERE `ID`=71869;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그럼 이제 당신들을 안전한 곳으로 보내야겠군요. 덕분에 천둥왕을 완전히 포위했어요.', `FemaleText_loc4`='确实如此。我们送你们回去吧。多亏你们，雷神现在已经四面楚歌了。', `FemaleText_loc5`='沒錯。我們先讓你們回到安全的地方吧。多虧你們，雷王現在受到了全面的攻擊。', `FemaleText_loc7`='Cierto. Vamos a ponerlos a salvo. Gracias a ustedes, el Rey del Trueno ya está totalmente acorralado.' WHERE `ID`=71870;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순찰대! 경첩을 부수고 쐐기를 괴어 문을 고정해라!', `FemaleText_loc4`='游侠们——破坏铰链。把门打开！', `FemaleText_loc5`='遊俠們 - 粉碎鉸鏈。讓門開著!', `FemaleText_loc7`='Forestales, rompan las bisagras. ¡Que las puertas se queden abiertas!' WHERE `ID`=71871;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='계획이 성공했습니다! 그대 둘이 일당백의 활약을 보여줬어요.', `FemaleText_loc4`='计划成功了！你们俩简直抵得上一整支军队。', `FemaleText_loc5`='你們的計畫成功了!你們兩個人達成了一整支軍隊才能做到的事。', `FemaleText_loc7`='¡Su plan funcionó! Entre los dos realizaron el trabajo de todo un ejército.' WHERE `ID`=71872;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정님께 자세히 보고해야겠습니다. 야영지로 돌아가시지요. 휴식을 취하셔야 합니다.', `FemaleText_loc4`='摄政王一定想听听完整的报告。我们送你回去吧——你该休息了。', `FemaleText_loc5`='攝政王會要一份完整的報告。我們先帶你們回到安全的地方休息吧。這是你應得的。 ', `FemaleText_loc7`='El Señor Regente querrá un informe completo. Volvamos al campamento, te ganaste un descanso.' WHERE `ID`=71873;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사람의 냄새를 숨길 수 있는 마법을 연구하기 시작했을 때 다들 저를 비웃었다는 거 아세요? 대마법사들께서 비현실적이고 시간 낭비라고 생각하셨죠.$b$b하지만 데빌사우루스 쪽으로 바람이 부는데도 웃고 있는 게 누굴까요?', `FemaleText_loc4`='你相信吗？当我着手研究掩盖体味的魔法时，还受过嘲笑。大法师们都觉得我的研究不切实际，而且浪费时间。$b$b看看，现在站在魔暴龙的上风口笑的人又是谁？哈！', `FemaleText_loc5`='你知道，我剛開始研究能夠隱藏氣味的魔法時，有多少人在嘲笑我嗎?所有的大法師都認為我的研究毫不實際、只是浪費時間。$b$b哼，看看現在是誰站在魔暴龍的上風處還笑得出來的啊?哈!', `FemaleText_loc7`='¿Te puedes creer que se rieron de mí cuando empecé a investigar sobre magia que eliminase el olor corporal? Los archimagos consideraban que era inútil y una pérdida de tiempo.$b$bBueno, ¿quién está detrás de un demosaurio y riéndose ahora? ¡Ja!' WHERE `ID`=71874;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 냄새만 가릴 수 있다는 게 안타깝네요. 잔달라와 놈들이 기르는 야수들이 풍기는 악취는 가릴 수가 없으니 말이에요.', `FemaleText_loc4`='真可惜，我只能掩盖我们自己的气味，却没办法驱散赞达拉巨魔和他们那些畜生身上的恶臭。', `FemaleText_loc5`='可惜啊，我只有辦法隱藏我們自己的氣味，沒辦法消掉贊達拉食人妖和他們那些畜生的臭味。', `FemaleText_loc7`='Es una pena que solo sea capaz de eliminar nuestros propios olores y no el terrible hedor de los Zandalari y de sus bestias.' WHERE `ID`=71875;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 현장 작업을 별로 좋아하지 않아요. 특히 어마어마한 수의 트롤이 관련된 일이라면요.', `FemaleText_loc4`='我向来不喜欢野外工作，尤其是牵涉到一大群巨魔的工作。', `FemaleText_loc5`='我最討厭出來外頭做田野調查了，尤其是跟大量食人妖有關的。', `FemaleText_loc7`='Nunca me ha gustado el trabajo de campo... Especialmente si tiene que ver con grandes cantidades de trols.' WHERE `ID`=71876;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 움직이게! 폭풍군주의 번개를 피해!', `MaleText_loc4`='别停下！躲开暴风领主的闪电！', `MaleText_loc5`='繼續前進!避開風暴龍王的閃電!', `MaleText_loc7`='¡Muévete! ¡Esquiva los rayos del Señor de la tormenta!' WHERE `ID`=71877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야리아 곁에 있게, 용사여!', `MaleText_loc4`='靠近雅丽亚，接受她的治疗，勇士！', `MaleText_loc5`='靠近雅里亞的治療範圍，勇士!', `MaleText_loc7`='¡Acércate a la sanación de Yalia!' WHERE `ID`=71878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부의 공격을 피하게. 우리가 더 빠르고 더 영리하네!', `MaleText_loc4`='躲开山怖的攻击。我们比他更快，更聪明！', `MaleText_loc5`='閃躲衫布的攻擊!我們的速度更快!更聰明!', `MaleText_loc7`='Esquiva los ataques de Shan Bu. ¡Somos más rápidos y más listos!' WHERE `ID`=71879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야리아 근처에서 치유를 받게!', `MaleText_loc4`='靠近雅丽亚，让她治疗你！', `MaleText_loc5`='靠近雅里亞，讓她治療你!', `MaleText_loc7`='¡Permanece cerca de Yalia para que te sane!' WHERE `ID`=71880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들의 비명은 폐하의 기쁨이다!', `MaleText_loc4`='你们的哀嚎将取悦陛下！', `MaleText_loc5`='你們的慘叫聲會讓皇上很高興的!', `MaleText_loc7`='¡Sus gritos de agonía deleitan a su majestad!' WHERE `ID`=71881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 지배한다. 네놈들은 복종해라!', `MaleText_loc4`='我们是主，你们是仆！', `MaleText_loc5`='我們為統治而生。你們為服侍而生。', `MaleText_loc7`='Nuestro destino es gobernar. El suyo servir.' WHERE `ID`=71882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해 빠졌군. 음영파 놈들은 벌레처럼 그림자 속에서 허둥대지.', `MaleText_loc4`='懦夫。你们影踪派只敢像蟑螂一样在阴影里活动。', `MaleText_loc5`='你太弱了。你們影潘只是在暗處竄逃的蟑螂。', `MaleText_loc7`='Eres débil. Tus Shadopan se arrastran en la oscuridad como cucarachas.' WHERE `ID`=71883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; 자매를 치유하기 시작합니다!', `FemaleText_loc4`='%s开始治疗她的姐妹！', `FemaleText_loc5`='%s開始治療她的姊妹!', `FemaleText_loc7`='¡%s comienza a sanar a su hermana!' WHERE `ID`=71884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈의 무례함도 이젠 진력난다! 생명을 쥐어짜 주마, 이 버릇 없는 노예 놈아!', `MaleText_loc4`='我受够你的无礼了！我要掐死你，放肆的奴隶！', `MaleText_loc5`='你的傲慢讓我不耐煩了!我要把你的生命榨光，無恥的奴隸!', `MaleText_loc7`='¡Ya me cansé de tu insolencia! ¡Te asfixiaré hasta la muerte, esclavo!' WHERE `ID`=71885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아악. 놈을 죽여. 빨리!', `MaleText_loc4`='啊——杀了他。快！', `MaleText_loc5`='呃 - 殺死他，快!', `MaleText_loc7`='Aaag. ¡Mátalo! ¡Rápido!' WHERE `ID`=71886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끝장내!', `MaleText_loc4`='干掉他！', `MaleText_loc5`='解決他!', `MaleText_loc7`='¡Acaba con él!' WHERE `ID`=71887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍의 정수가 창에서 뿜어져 나와 당신을 주시합니다!', `MaleText_loc4`='刺入的长矛上生成了一个暴风精华并锁定了你！', `MaleText_loc5`='風暴精華從插著的長槍出現，開始追逐你!', `MaleText_loc7`='¡Una esencia de la tormenta brota de la lanza incrustada y se fija en ti!', `FemaleText_loc1`='폭풍의 정수가 창에서 뿜어져 나와 당신을 주시합니다!', `FemaleText_loc4`='刺入的长矛上生成了一个暴风精华并锁定了你！', `FemaleText_loc5`='風暴精華從插著的長槍出現，開始追逐你!', `FemaleText_loc7`='¡Una esencia de la tormenta brota de la lanza incrustada y se fija en ti!' WHERE `ID`=71888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 안 돼... 폐하... 폐하! 제가 실망을 안겨 드렸습니다!', `MaleText_loc4`='我……不……陛下！陛下，我辜负了您！', `MaleText_loc5`='我...不...皇上!我...讓你失望了!', `MaleText_loc7`='Yo... no... ¡Emperador! ¡Te fallé, mi emperador!' WHERE `ID`=71889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥이 널 집어삼킬 것이다!', `MaleText_loc4`='让风暴吞噬你！', `MaleText_loc5`='風暴會吞噬你!', `MaleText_loc7`='¡La tormenta te consumirá!' WHERE `ID`=71890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕이시여, 저를 지켜주소서!', `MaleText_loc4`='雷霆之主……保护我！', `MaleText_loc5`='雷霆之王...保護我!', `MaleText_loc7`='¡Señor del trueno... protégeme!' WHERE `ID`=71891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s가 |cFFF00000|Hspell:137891|h[뒤틀린 운명]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s开始施放|cFFF00000|Hspell:137891|h[扭曲命运]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s開始施展|cFFF00000|Hspell:137891|h[命運扭曲]|h|r!', `MaleText_loc7`='|TInterface/Iconsability_warlock_jinx:20|t%s comienza a lanzar |cFFF00000|Hspell:137891|h[Destino retorcido]|h|r.', `FemaleText_loc1`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s가 |cFFF00000|Hspell:137891|h[뒤틀린 운명]|h|r을 시전합니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s开始施放|cFFF00000|Hspell:137891|h[扭曲命运]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\ability_warlock_jinx:20|t%s開始施展|cFFF00000|Hspell:137891|h[命運扭曲]|h|r!', `FemaleText_loc7`='|TInterface/Iconsability_warlock_jinx:20|t%s comienza a lanzar |cFFF00000|Hspell:137891|h[Destino retorcido]|h|r.' WHERE `ID`=71892;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어둠이 우리를 도와줄겁니다.', `FemaleText_loc4`='阴影将成为我们的盟友。', `FemaleText_loc5`='陰影將是我們的盟友。', `FemaleText_loc7`='Las sombras serán nuestras aliadas.' WHERE `ID`=71893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속의 비수 대기열에 등록합니다.', `MaleText_loc4`='排队等待黑暗中的匕首场景战役。', `MaleText_loc5`='加入「暗箭難防」的佇列。', `MaleText_loc7`='Haz cola para Una Daga en la Oscuridad.', `FemaleText_loc1`='어둠 속의 비수 대기열에 등록합니다.', `FemaleText_loc4`='排队等待黑暗中的匕首场景战役。', `FemaleText_loc5`='加入「暗箭難防」的佇列。', `FemaleText_loc7`='Haz cola para Una Daga en la Oscuridad.' WHERE `ID`=71894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족은 자긍심 강한 자들입니다. 하지만 결국 그 자긍심이 파멸의 씨앗이 될 겁니다.$b$b가장 강력한 적에게도 약점은 있는 법이죠. 그 약점을 찾는 건 우리 몫이지만요.', `MaleText_loc4`='赞达拉是个骄傲的种族。他们的骄傲迟早会毁了他们。$b$b就算是最强大的敌人也会有弱点，我们只需要找出这个弱点就行了。', `MaleText_loc5`='贊達拉食人妖十分驕傲自豪，而他們的驕傲必將成為他們敗亡的主因。$b$b再強大的敵人也會有弱點，我們只需要把它找出來。', `MaleText_loc7`='Los Zandalari son una raza orgullosa. Al final su orgullo acabará con ellos.$b$bHasta los enemigos más poderosos tienen un punto débil; solo tenemos que encontrarlo.' WHERE `ID`=71895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게... 내 생명의 불이 사그라지다니...', `MaleText_loc4`='生命之火……就此……熄灭了……', `MaleText_loc5`='生命的火光...就此...熄滅...', `MaleText_loc7`='Y así... la chispa de la vida... se desvanece.' WHERE `ID`=71896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피! 맛있겟군! 넌 내 밥이다!', `MaleText_loc4`='鲜血！可口的鲜血！你将成为我的美餐！', `MaleText_loc5`='血!甜美的鮮血!來讓我飽餐一頓吧!', `MaleText_loc7`='¡SANGRE! ¡DELICIOSA! Me alimentarás.' WHERE `ID`=71897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피조차도 노예가 되야 해!', `MaleText_loc4`='就连你自己的鲜血都能派上用处！', `MaleText_loc5`='連你自己的血也會變成我的僕人!', `MaleText_loc7`='¡Incluso tu propia sangre puede servir!' WHERE `ID`=71898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 내 피가... 뿜어져 나오잖아...', `MaleText_loc4`='不！我……流血了……', `MaleText_loc5`='不!我的血...灑出來了...', `MaleText_loc7`='¡No! Mi sangre... se derrama...' WHERE `ID`=71899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여! 이제 우리의 대장정이 절정에 이르렀소. 천둥왕의 궁전 입구에 도착했으니까. 대문을 때려 부술 시간이오.', `MaleText_loc4`='勇士！战局已经处于白热化状态：我们推进到了雷电之王的宫殿门口。现在该去打破他的前门了。', `MaleText_loc5`='勇士!我們的戰役到了高潮:我們到了雷王的宮殿前。是時候攻下他的大門了。', `MaleText_loc7`='Nuestra campaña se acerca a su fin: nos encontramos en el umbral del palacio del Rey del Trueno. Es hora de tocar la puerta.' WHERE `ID`=71900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격할 준비가 되면 내게 말하시오!', `MaleText_loc4`='做好出击的准备后，请告诉我一声！', `MaleText_loc5`='等你準備好進行突襲，跟我說一聲。', `MaleText_loc7`='Habla conmigo cuando quieras empezar el asalto.' WHERE `ID`=71901;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='언제나처럼 제때에 와주셨군요. 천둥왕의 대문을 박살낼 때가 됐어요.', `FemaleText_loc4`='你总在我们最需要的时候出现，英雄。该去踢开雷电之王的前门了。', `FemaleText_loc5`='你的時間抓得正好。現在是時候把雷王的大門一腳踹開了。', `FemaleText_loc7`='Vuelves a llegar en el momento oportuno. Es hora de tumbar la puerta del Rey del Trueno.' WHERE `ID`=71902;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격할 준비가 되면 제게 말씀하세요!', `FemaleText_loc4`='做好出击的准备后，请告诉我一声！', `FemaleText_loc5`='等你準備好發動攻擊時跟我說。', `FemaleText_loc7`='Habla conmigo cuando quieras empezar el asalto.' WHERE `ID`=71903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 오셨어요.', `FemaleText_loc4`='很好，你来了。', `FemaleText_loc5`='很好，你來了。', `FemaleText_loc7`='Me alegro de que hayas llegado.' WHERE `ID`=71904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 님! 모두 제 위치에 있고, 음영파는 안에 있습니다만...', `FemaleText_loc4`='普罗德摩尔女士！人员已经就位，影踪派也进去了，但是……', `FemaleText_loc5`='普勞德摩爾女士!所有人都就定位了，影潘也在裡面，不過...', `FemaleText_loc7`='¡Lady Valiente! Estamos todos en posición y el Shadopan está dentro, pero...' WHERE `ID`=71905;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그런데요?', `FemaleText_loc4`='可是什么？', `FemaleText_loc5`='不過什麼?', `FemaleText_loc7`='¿Pero qué?' WHERE `ID`=71906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 안마당 저편에 있습니다.', `FemaleText_loc4`='部落就在庭院的对面。', `FemaleText_loc5`='部落就在中庭的另一頭。', `FemaleText_loc7`='La Horda está al otro lado del patio.' WHERE `ID`=71907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐, 어련하겠어요. 베리사, 하나씩 해결해요.', `FemaleText_loc4`='他们当然会来。一个个来，温蕾萨。', `FemaleText_loc5`='想也知道。一次解決一個問題，凡蕾莎。', `FemaleText_loc7`='Cómo no... Vamos paso a paso, Vereesa.' WHERE `ID`=71908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부대! 전진!', `FemaleText_loc4`='全体前进！', `FemaleText_loc5`='所有人!前進!', `FemaleText_loc7`='¡Atención! ¡Avancen!' WHERE `ID`=71909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='... 그리고 배신자 에이타스 선리버는... 날 위해 남겨둬라...', `FemaleText_loc4`='……如果有谁遇到艾萨斯·夺日者这个叛徒，记得把他留给我……', `FemaleText_loc5`='...還有，要是誰看到了埃薩·奪日者那個叛徒，把他留給我...', `FemaleText_loc7`='Y si alguien ve a ese traidor de Aethas Atracasol, que me lo deje a mí...' WHERE `ID`=71910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드는 무시하고, 문을 방어하는 잔달라를 공격해!', `FemaleText_loc4`='别管部落——我们先对付守门的赞达拉！', `FemaleText_loc5`='別管部落，把注意力集中在守門的贊達拉身上!', `FemaleText_loc7`='¡Ignoren a la Horda! ¡Concéntrense en los Zandalari de la puerta!' WHERE `ID`=71911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 님. 부두에서 또 잔달라 트롤이 다가옵니다.', `FemaleText_loc4`='普罗德摩尔女士——码头上的赞达拉巨魔又冲过来了。', `FemaleText_loc5`='普勞德摩爾女士-更多贊達拉從碼頭過來了。', `FemaleText_loc7`='¡Lady Valiente! Vienen más Zandalari desde el muelle.' WHERE `ID`=71912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 측면을 노리는군. 현 위치를 사수하라!', `FemaleText_loc4`='他们想袭击我们的侧翼。守住这里！', `FemaleText_loc5`='他們想要從側翼攻擊。守住這個位置!', `FemaleText_loc7`='Intentan flanquearnos. ¡Mantengan la posición!' WHERE `ID`=71913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게! 자네를 노리네!', `MaleText_loc4`='小心，他冲你去了！', `MaleText_loc5`='小心，他往你的方向去了!', `MaleText_loc7`='¡Prepárate! ¡Va hacia ti!' WHERE `ID`=71914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈과 거리를 유지하게!', `MaleText_loc4`='别让他靠近你！', `MaleText_loc5`='別讓他靠近你!', `MaleText_loc7`='¡No dejes que se te acerque!' WHERE `ID`=71915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈이 자네를 덮치려 하네!', `MaleText_loc4`='小心——他朝你去了！', `MaleText_loc5`='小心，他去找你了!', `MaleText_loc7`='¡Cuidado! ¡Va a atacarte!' WHERE `ID`=71916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 얼라이언스 놈들은 모두 허깨비야. 힘이 하나도 없어.', `MaleText_loc4`='你们“联盟”空有速度，毫无力量可言。', `MaleText_loc5`='你們「聯盟」只是曇花一現，沒什麼真正的力量。', `MaleText_loc7`='Su "Alianza" no es más que una fantasía; sin fuerza alguna.' WHERE `ID`=71917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 호드 놈들은 역겨운 짐승 떼야. 포로로 삼기도 아깝다.', `MaleText_loc4`='你们“部落”就是一群恶心的畜生，连奴隶都不如。', `MaleText_loc5`='你們「部落」只是群噁心的畜生，連被奴役的資格都沒有。', `MaleText_loc7`='Su "Horda" es una manada de animales que ni siquiera vale la pena esclavizar.' WHERE `ID`=71918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠는가? 세상의 어떤 힘으로도 순수한 영혼을 짓밟을 수는 없다네.', `MaleText_loc4`='你看到了？这世上没有力量能践踏纯洁的灵魂。', `MaleText_loc5`='看到了嗎?世界上沒有力量能踐踏靈魂的純淨。', `MaleText_loc7`='¿Ves? No hay poder en el mundo que pueda con un espíritu puro.' WHERE `ID`=71919;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맹주님! 얼라이언스와 호드, 양 진영이 이성을 잃고 폭주하기 시작했습니다!', `FemaleText_loc4`='祝掌门！联盟——部落——这里马上就要乱作一团了！', `FemaleText_loc5`='祝宗主!聯盟 - 還有部落 - 這裡的情勢快失控了!', `FemaleText_loc7`='¡Lord Zhu! La Alianza... La Horda... ¡Está a punto de desencadenarse el caos absoluto!' WHERE `ID`=71920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어린애들 같이.', `MaleText_loc4`='真幼稚。', `MaleText_loc5`='真是幼稚。', `MaleText_loc7`='Son como niños.' WHERE `ID`=71921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타오스! 내 무기를 다오!', `MaleText_loc4`='陶矢！把武器给我。', `MaleText_loc5`='陶氏!把武器給我。', `MaleText_loc7`='¡Taoshi! Pásame mi arma.' WHERE `ID`=71922;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 맹주님... 상처가 너무 심합니다!', `FemaleText_loc4`='掌门……你伤得很重！', `FemaleText_loc5`='宗主...你的傷勢很重!', `FemaleText_loc7`='Mi señor... ¡Está gravemente herido!' WHERE `ID`=71923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 무기를! 용사여, 함께 가세. 보여줄 것이 있네.', `MaleText_loc4`='我的武器！勇士，跟我来。我要你见证这一切。', `MaleText_loc5`='我的武器!勇士，跟我來。我要你看看這個。', `MaleText_loc7`='¡Mi arma! Ven conmigo. Quiero que veas esto.' WHERE `ID`=71924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='로르테마르, 대마법사를 내게 넘기면 너는 살려 보내주마.', `FemaleText_loc4`='交出大法师，这样，我或许还能放你一条生路，洛瑟玛。', `FemaleText_loc5`='如果把大法師交出來，我也許還能讓你活著離開，洛索瑪。', `FemaleText_loc7`='Entrégame al archimago y a lo mejor te dejo salir entero, Lor''themar.' WHERE `ID`=71925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프라우드무어! 내 백성들을 보랏빛 요새에서 풀어줘라. 아니면 내가 직접 널 베겠다!', `MaleText_loc4`='普罗德摩尔！放了我在紫罗兰监狱的同胞，否则我就亲手杀了你！', `MaleText_loc5`='普勞德摩爾!把我的子民從紫羅蘭堡放出來，不然我就親手把你劈成兩半!', `MaleText_loc7`='¡Valiente! ¡Libera a mi gente del Bastión Violeta o juro que te atravesaré yo mismo!' WHERE `ID`=71926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 명백한 전쟁 포로다. 다르나서스를 공격했으니까! 그것도 내 도시에서!', `FemaleText_loc4`='你所谓的同胞都是些战俘。他们居然敢在我的城市里策划袭击了达纳苏斯——', `FemaleText_loc5`='你的子民是戰爭中的俘虜。他們從「我的」城市對達納蘇斯組織了一場進攻...', `FemaleText_loc7`='Tu gente son prisioneros de guerra. Dirigieron un ataque contra Darnassus desde mi ciudad…' WHERE `ID`=71927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='선리버는 가로쉬의 만행을 전혀 몰랐다!', `MaleText_loc4`='夺日者根本不知道加尔鲁什袭击达纳苏斯的事！', `MaleText_loc5`='奪日者完全不知道卡爾洛斯對達納蘇斯的攻擊行動!', `MaleText_loc7`='¡Los Atracasol no sabían nada sobre el asalto de Garrosh en Darnassus!' WHERE `ID`=71928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스의 심기가 불편해 보입니다.', `MaleText_loc4`='艾萨斯·夺日者不安地动了动。', `MaleText_loc5`='埃薩·奪日者不安地動了幾下。', `MaleText_loc7`='Aethas Atracasol se agita incómodo.' WHERE `ID`=71929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 오늘의 싸움은 여기까지요.', `MaleText_loc4`='够了！！今天已经流了太多的血。', `MaleText_loc5`='夠了!今天不會再有人流血了。', `MaleText_loc7`='¡BASTA! Hoy no se derramará más sangre.' WHERE `ID`=71930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 호드가 싸움을 멈추지 못하는 이유를 알겠소.', `MaleText_loc4`='我现在明白你们联盟和部落为何总是争斗不休了。', `MaleText_loc5`='我現在知道為什麼你們聯盟和部落會不停爭鬥。', `MaleText_loc7`='Ahora entiendo por qué la Horda y la Alianza no dejan de pelearse.' WHERE `ID`=71931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보복은 그 자체가 공격 행위이고, 공격 행위는 즉각적인 보복을 낳기 때문이지.', `MaleText_loc4`='每一次报复本身就是一次侵略，而每一次侵略又会立刻引来报复。', `MaleText_loc5`='報復生侵略、侵略生報復。冤冤相報何時了。', `MaleText_loc7`='Cada represalia es un acto de agresión, y cada acto de agresión desencadena una represalia.' WHERE `ID`=71932;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들은 평화를 위한 노력을 모두 짓밟았어!', `FemaleText_loc4`='他们破坏了我们每一次的和平努力！', `FemaleText_loc5`='他們破壞了每一次嘗試和平的舉動!', `FemaleText_loc7`='¡Han saboteado todos los intentos de dialogar!' WHERE `ID`=71933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 내 백성을 보호해야 한다.', `MaleText_loc4`='我必须保护我的人民。', `MaleText_loc5`='我必須保護我轄下的子民。', `MaleText_loc7`='Debo proteger la soberanía de mi pueblo.' WHERE `ID`=71934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='입 다무시오! 그대들이 그 순환을 깨야 하오.', `MaleText_loc4`='闭嘴！你们必须打破这个循环。', `MaleText_loc5`='安靜!你們必須終結這個輪迴。', `MaleText_loc7`='¡SILENCIO! USTEDES tienen que romper el ciclo.' WHERE `ID`=71935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순환은 오늘, 여기서 끝날 거요. 그대, 섭정과 그대, 여군주의 손으로. 이제 돌아서서, 가시오.', `MaleText_loc4`='这循环要在今日，此地结束。当你，摄政王，和你，普罗德摩尔女士，放过彼此，并各自回头。', `MaleText_loc5`='今天，一定要打破仇恨的輪迴。只要你，攝政王，還有你，普勞德摩爾女士，兩個人能不再針鋒相對，轉身離開。', `MaleText_loc7`='Se acaba aquí y ahora. El ciclo terminará cuando tú, Señor regente, y tú, Lady Jaina, dejen de enfrentarse y sigan su camino.' WHERE `ID`=71936;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나가 깊은 숨을 들이마십니다.', `FemaleText_loc4`='吉安娜深吸了一口气。', `FemaleText_loc5`='珍娜深深吸了一口氣。', `FemaleText_loc7`='Jaina respira profundamente.' WHERE `ID`=71937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로르테마르 테론이 눈을 가늘게 뜹니다.', `MaleText_loc4`='洛瑟玛眯起了眼睛。', `MaleText_loc5`='洛索瑪皺起了眉頭。', `MaleText_loc7`='Lor''themar entorna los ojos.' WHERE `ID`=71938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대, 무기를 내려라.', `MaleText_loc4`='游侠们。放下武器。', `MaleText_loc5`='遊俠們，放下武器。', `MaleText_loc7`='Forestales. Bajen las armas.' WHERE `ID`=71939;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정님!', `FemaleText_loc4`='阁下！', `FemaleText_loc5`='大人!', `FemaleText_loc7`='¡Mi señor!' WHERE `ID`=71940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서.', `MaleText_loc4`='按我说的做。', `MaleText_loc5`='放下!', `MaleText_loc7`='Háganlo.' WHERE `ID`=71941;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠다. 이만 물러나지.', `FemaleText_loc4`='很好。我们可以撤退。', `FemaleText_loc5`='好吧。我們會退開。', `FemaleText_loc7`='Muy bien. Bajaremos las armas.' WHERE `ID`=71942;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 남편을 죽인 놈들이에요!', `FemaleText_loc4`='他们杀了我丈夫！', `FemaleText_loc5`='但他們殺了我的丈夫!', `FemaleText_loc7`='¡Mataron a mi marido!' WHERE `ID`=71943;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런다고 되살아나진 않아요.', `FemaleText_loc4`='这也不能让他活过来。', `FemaleText_loc5`='這也無法將他帶回來。', `FemaleText_loc7`='Esto no lo traerá de vuelta.' WHERE `ID`=71944;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이건 알아둬라, "피의" 엘프여. 가로쉬가 호드의 대족장으로 있는 한, 평화는 없다.', `FemaleText_loc4`='但记住，“血”精灵：只要地狱咆哮还是部落酋长，我们就谈不上和平。', `FemaleText_loc5`='但聽好了，「血」精靈:只要地獄吼擔任部落的大酋長，就不可能有和平。', `FemaleText_loc7`='Pero has de saber, elfo "de sangre", que no habrá paz mientras Grito Infernal sea Jefe de Guerra de la Horda.' WHERE `ID`=71945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 바로 내가 오늘 힘을 아끼려는 이유다.', `MaleText_loc4`='这正是我今天决定保存实力的原因。', `MaleText_loc5`='這正是我今天要保留實力的原因。', `MaleText_loc7`='Por eso precisamente quiero conservar nuestras fuerzas.' WHERE `ID`=71946;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나의 표정이 누그러집니다.', `FemaleText_loc4`='吉安娜的表情柔和了下来。', `FemaleText_loc5`='珍娜的神情放鬆了一些。', `FemaleText_loc7`='La expresión de Jaina se suaviza.' WHERE `ID`=71947;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정이여.', `FemaleText_loc4`='阁下。', `FemaleText_loc5`='閣下。', `FemaleText_loc7`='Mi señor.' WHERE `ID`=71948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여군주여.', `MaleText_loc4`='女士。', `MaleText_loc5`='女士。', `MaleText_loc7`='Mi señora.' WHERE `ID`=71949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부상병들을 수습해라. 항구로 철수한다.', `MaleText_loc4`='快收拢伤员，撤回港口去。', `MaleText_loc5`='把傷者聚集在一起。撤回營地。', `MaleText_loc7`='Reúnan a los heridos. Retírense al puerto.' WHERE `ID`=71950;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모두 야영지에서 집합한다. 이곳에서 할 일은 끝났어.', `FemaleText_loc4`='大家回营地休整。我们的任务完成了。', `FemaleText_loc5`='所有人，回營地集合。我們在這裡的任務結束了。', `FemaleText_loc7`='Reagrupémonos en el campamento. Nuestro trabajo ha terminado aquí.' WHERE `ID`=71951;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='맹주님!', `FemaleText_loc4`='祝掌门！', `FemaleText_loc5`='祝宗主!', `FemaleText_loc7`='¡Lord Zhu!' WHERE `ID`=71952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 이 휴전은 오래가지 않을지 모르나, 오늘 본 것을 기억하게.', `MaleText_loc4`='勇士，这次停战也许持续不了多久，但请记住这一切。', `MaleText_loc5`='勇士，這個停火協議不一定會長久，但別忘記你今天所見的一切。', `MaleText_loc7`='Tal vez el alto al fuego no perdure, pero recuerda lo que has presenciado hoy.' WHERE `ID`=71953;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='곧바로 수도원으로 모시겠습니다.', `FemaleText_loc4`='我们得送你回禅院。', `FemaleText_loc5`='我們必須把你帶回僧院裡。', `FemaleText_loc7`='Debemos llevarte de vuelta al monasterio.' WHERE `ID`=71954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부의 괴물이 아직 궁전 입구에 있네. 놈이 판다리아 전역을 파괴하기 전에 막아야 하네.', `MaleText_loc4`='山怖的怪物还在宫殿之下。我们必须在它肆虐潘达利亚之前阻止它。', `MaleText_loc5`='衫布弄出的怪物仍然在宮殿前。必須在牠在潘達利亞掀起災難前阻止牠。', `MaleText_loc7`='La monstruosidad de Shan Bu sigue en el palacio. Hay que detenerla antes de que siembre el caos en Pandaria.' WHERE `ID`=71955;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야리아, 맹주님을 안전한 곳으로!', `FemaleText_loc4`='雅丽亚，保护祝掌门。', `FemaleText_loc5`='雅里亞，把祝宗主帶去安全之處。', `FemaleText_loc7`='Yalia, pon a salvo a Lord Zhu.' WHERE `ID`=71956;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='영웅이여, 당신은 폭풍군주 나락크를 상대해야 합니다. 아마 웬만한 군대 없이는 힘들 거예요!', `FemaleText_loc4`='英雄，击败暴风领主纳拉克就靠你了。你得集结一支小部队。', `FemaleText_loc5`='英雄，『風暴龍王』納拉卡要靠你來擊敗了。你必須帶領一小支部隊進行!', `FemaleText_loc7`='Te corresponderá a ti derrotar al señor de la tormenta Nalak. Dirigirás un pequeño ejército.' WHERE `ID`=71957;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 오늘 당신이 이룬 일들을 보니 믿음이 가네요.', `FemaleText_loc4`='但以我今天的所见所闻，我对你有信心。', `FemaleText_loc5`='據我今日所見，我對你有信心。', `FemaleText_loc7`='Pero después de lo que he visto hoy, confío en ti.' WHERE `ID`=71958;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신 곁에서 싸울 수 있어서 영광이었어요. 감사해요.', `FemaleText_loc4`='与你并肩作战是莫大的荣幸。谢谢你。', `FemaleText_loc5`='能在你身邊作戰十分榮幸。謝謝你。', `FemaleText_loc7`='Ha sido un gran honor luchar a tu lado. Muchas gracias.' WHERE `ID`=71959;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 당신을 믿어요. 내 지팡이를 천둥왕의 단상에 올려놓기만 하세요. 이 임무를 맡아 주시다니, 정말 용감하군요. 행운을 빌게요!', `FemaleText_loc4`='我相信你，英雄。将我的法杖放到雷电之王的平台上，它会搞定一切。敢接受这个任务的都是勇士。祝你好运！', `FemaleText_loc5`='你獲得了我的信任，英雄。把我的法杖放在雷王的平台上，它就會自動進行並完成儀式。你的勇氣十足，才敢進行這個任務。祝你好運!', `FemaleText_loc7`='Te ganaste mi confianza. Coloca mi bastón en el estrado del Rey del Trueno y él hará el resto. Demuestras un gran valor al aceptar esta misión. ¡Buena suerte!' WHERE `ID`=71960;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 놀라워요! 전승지기들이 수백 년 동안 당신 얘기를 할 거예요!', `FemaleText_loc4`='你成功了！不可思议！熊猫人游学者会传颂你的事迹的！', `FemaleText_loc5`='你成功了!真不可思議!熊貓人的博學行者會一代代把你的事蹟傳頌下去的!', `FemaleText_loc7`='¡Lo has conseguido! ¡Los eremitas pandaren contarán tu historia durante generaciones!' WHERE `ID`=71961;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='느낄 수 있어요... 천둥왕의 힘이 내 지팡이에 흐르고 있어요.', `FemaleText_loc4`='我感觉……雷电之王的力量在我的法杖中流过。', `FemaleText_loc5`='我感覺得到...雷王的力量布滿我的法杖。', `FemaleText_loc7`='Puedo sentirlo... El poder del Rey del Trueno recorre mi bastón...' WHERE `ID`=71962;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='무엇보다도, 당신은 천둥왕의 흉악한 기계를 망가뜨려 호드가 아무것도 차지하지 못하게 했죠.', `FemaleText_loc4`='尤其是，你彻底破坏了雷电之王的恐怖机器，没有让部落将它们据为己有。', `FemaleText_loc5`='更棒的是，你徹底關閉了他的邪惡裝置，沒讓它落入部落的手中。', `FemaleText_loc7`='Y lo que es mejor, has desactivado su máquina infernal para siempre. La Horda ya no puede quedarse con nada de esto.' WHERE `ID`=71963;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='때가 되면, 이 지팡이의 힘을 이용해 오그리마를 무너뜨리고 가로쉬 헬스크림을 묻어 버릴 거예요.', `FemaleText_loc4`='如果有机会的话，我会用这根法杖炸毁奥格瑞玛的城墙，让它砸到加尔鲁什·地狱咆哮的头上。', `FemaleText_loc5`='等時機成熟，我會用這把法杖讓奧格瑪的城牆全砸在卡爾洛斯·地獄吼的頭上。', `FemaleText_loc7`='Cuando llegue el momento, usaré este bastón para derribar los muros de Orgrimmar sobre Garrosh Grito Infernal.' WHERE `ID`=71964;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고마워요. 얼라이언스에 당신이 있어서 다행이에요.', `FemaleText_loc4`='谢谢你，朋友。联盟幸亏有你。', `FemaleText_loc5`='謝謝你，朋友。聯盟能有你真是幸運。', `FemaleText_loc7`='Muchas gracias. La Alianza tiene suerte de contar contigo.' WHERE `ID`=71965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대를 굳게 믿고 있지만, 이번이 가장 위험한 임무일 것이오. 천둥왕의 소굴 한가운데에서 그의 비밀을 훔쳐내시오. 행운을 빌겠소.', `MaleText_loc4`='你赢得了我的信任，英雄。但这将是你最危险的一次任务：从雷电之王的巢穴中偷出他的秘密。祝你好运。', `MaleText_loc5`='你贏得了我的信任，英雄。這會是你最危險的一次任務:從雷王大本營的最深處偷取他的秘密。祝你好運。', `MaleText_loc7`='Te has ganado mi confianza. Esta será tu misión más peligrosa hasta el momento: robar los secretos del Rey del Trueno de su propia guarida. Te deseo mucha suerte.' WHERE `ID`=71966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 가져왔소? 아! 흥미롭군.', `MaleText_loc4`='你带来了什么？啊！好极了。', `MaleText_loc5`='你帶回了什麼?啊，真有趣。', `MaleText_loc7`='¿Qué traes contigo? ¡Ah! Fascinante.' WHERE `ID`=71967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가 힘의 근원이라니, 강력한 형태의 생명 마법이군. 혹시 티탄의 작품인가? 어떻게 작동하는 거지?', `MaleText_loc4`='以鲜血为源——这种魔法很强大。或许是泰坦的杰作？它是怎么运转的？', `MaleText_loc5`='用鮮血當能量來源 - 很強大的生命魔法。也許這是泰坦的傑作?這要怎麼弄?', `MaleText_loc7`='La sangre como fuente de poder... una forma muy poderosa de magia vital. ¿Será obra de los titanes? ¿Cómo funcionará?' WHERE `ID`=71968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스, 최고의 대마법사들이 이 장치를 분석하게 하시오. 배워야 할 게 많소.', `MaleText_loc4`='艾萨斯，让我们最好的法师来研究它。我们有很多东西要学。', `MaleText_loc5`='埃薩，我要我們最強的大法師立刻開始研究這個裝置。我們有很多要學習的。', `MaleText_loc7`='Aethas, quiero que nuestros mejores archimagos estudien este artefacto a la brevedad. Tenemos tanto que aprender.' WHERE `ID`=71969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 고맙소! 호드가 위기에 처해 있지만, 지금까지의 그대 활약 덕분에, 앞으로 무슨 일이 있더라도 우리는 생존하고 번영할 수 있을 거요.', `MaleText_loc4`='谢谢你，勇士！部落或许正处在危机边缘，但无论如何，你在这片海滩上的行动已经确保了我们的生存与发展。', `MaleText_loc5`='感謝你，勇士!部落也許正在面臨危機，但不管接下來要面對什麼，你在這片海岸的行動都保障了我們接下來的生存。', `MaleText_loc7`='Te lo agradezco. Puede que la Horda esté al borde de la crisis, pero tus hazañas en estas tierras han garantizado nuestra supervivencia y prosperidad, pase lo que pase.' WHERE `ID`=71970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대에게 진심으로 감사하오. 알 디엘 샬라.', `MaleText_loc4`='你赢得了我们最深的谢意。Al diel shala，英雄。', `MaleText_loc5`='你有著我最深的謝意。Al diel shala，英雄。', `MaleText_loc7`='Tienes nuestro más profundo agradecimiento. Al diel shala.' WHERE `ID`=71971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해.', `MaleText_loc4`='弱者。', `MaleText_loc5`='好弱。', `MaleText_loc7`='Débil.' WHERE `ID`=71972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 쉽게 부숴지네.', `MaleText_loc4`='这么快就死了。', `MaleText_loc5`='太容易壞了。', `MaleText_loc7`='Tan fácil de romper.' WHERE `ID`=71973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 이기다니..', `MaleText_loc4`='你们是怎么打败我的？', `MaleText_loc5`='你怎麼打贏我...?', `MaleText_loc7`='¿Cómo me derrotaron?' WHERE `ID`=71974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지루해. 당장 죽어.', `MaleText_loc4`='无聊。你该死了。', `MaleText_loc5`='無聊。你們快點死吧。', `MaleText_loc7`='Aburrido. A morir ya.' WHERE `ID`=71975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕이 내게 힘을 주셨다! 봐라!', `MaleText_loc4`='雷电之王赐予我力量！来吧，我会让你们看到的！', `MaleText_loc5`='雷王給我力量!來，我給你看看!', `MaleText_loc7`='¡El Rey del Trueno me da poder! ¡Vengan, les enseñaré!' WHERE `ID`=71976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 부숴 주마.', `MaleText_loc4`='我必须消灭你们。', `MaleText_loc5`='我要打壞你們。', `MaleText_loc7`='Debo destrozarlos.' WHERE `ID`=71977;
