UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구름 돌바닥을 이용해 천둥왕의 장막을 제거하십시오!', `MaleText_loc4`='快使用云雾地砖驱散雷电之王的斗篷！', `MaleText_loc5`='使用雷雲地磚來解除雷王披肩!', `MaleText_loc7`='¡Usa Baldosa de nubes para disipar Manto del Rey del Trueno!' WHERE `ID`=71999;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 세상의 사악한 무리에게 장악당한 신대륙이라. 또 구할 곳이 생겼군요.', `FemaleText_loc4`='一片全新的土地正在遭受邪恶恐怖的侵蚀。一片全新的土地在等着我们去拯救。', `FemaleText_loc5`='被恐怖邪惡勢力籠罩的新土地，需要我們拯救的新地方。', `FemaleText_loc7`='Otro lugar infestado de los horrores de este mundo. Otra tierra que salvar.' WHERE `ID`=72000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몇몇은 제게 한낱 짐승들을 왜 그렇게 돌보냐고 놀리더군요. 자비심도 없는 사람들 같으니라고.', `MaleText_loc4`='有人嘲笑我对野兽的关注。而我要嘲笑他们的冷漠。', `MaleText_loc5`='有人笑我對野獸太過關心，我反笑他們太過冷漠。', `MaleText_loc7`='Algunos se ríen de mi preocupación por las bestias. Yo desprecio su falta de compasión.' WHERE `ID`=72001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잔달라 트롤에 관해선 배울 것이 많군요. 저들이 하지 않는 일들만 골라서 해도 바람직한 결과가 나오니까요.', `MaleText_loc4`='我们可以从这些赞达拉巨魔身上学到很多东西，尤其是去做他们不做的那些事。', `MaleText_loc5`='我們能從贊達拉食人妖學到很多東西，尤其是千萬別步上他們的後路。', `MaleText_loc7`='Podemos aprender mucho de estos Zandalari: debemos hacer siempre lo contrario que ellos hacen.' WHERE `ID`=72002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 아마니 제국을 막을 순 없다!', `MaleText_loc4`='阿曼尼帝国所向披靡！', `MaleText_loc5`='阿曼尼帝國無法被阻止!', `MaleText_loc7`='¡No pueden detener al imperio Amani!' WHERE `ID`=72003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕께서... 약속하셨는데...', `MaleText_loc4`='雷电……之王……承诺过……', `MaleText_loc5`='雷王...明明答應了...', `MaleText_loc7`='El... Rey del... Trueno... lo prometió...' WHERE `ID`=72004;
