UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희의 영혼은 내 것이다!', `MaleText_loc4`='你的灵魂归我了！', `MaleText_loc5`='你的靈魂是我的!', `MaleText_loc7`='¡Sus espíritus son míos!' WHERE `ID`=72012;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흴 쓰러뜨리면 천둥왕이 상을 내리실 거야!', `MaleText_loc4`='雷电之王会因此奖赏我们的！', `MaleText_loc5`='阻止你們就能得到雷王的獎賞!', `MaleText_loc7`='¡El Rey del Trueno nos recompensará por detenerlos!' WHERE `ID`=72013;
