UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽을 시간이다!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='去死吧!', `MaleText_loc7`='¡Hora de morir!' WHERE `ID`=72015;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 부족을 막을 순 없다!', `MaleText_loc4`='赞达拉所向无敌。', `MaleText_loc5`='贊達拉勢不可擋。', `MaleText_loc7`='No podrán detener a los Zandalari.' WHERE `ID`=72016;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 힘으로 잔달라 부족은 부활할 것이다.', `MaleText_loc4`='雷电之王的力量将使赞达拉重生。', `MaleText_loc5`='贊達拉將在雷王的力量下重生。', `MaleText_loc7`='¡Con el poder del Rey del Trueno, los Zandalari renacerán!' WHERE `ID`=72017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 션의 힘이 우릴 더 강하게 한다!', `MaleText_loc4`='雷神之力令我们更加强大！', `MaleText_loc5`='雷神的力量會強化我們!', `MaleText_loc7`='¡El poder de Lei Shen nos hace más fuertes!' WHERE `ID`=72018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼으로 값을 치뤄라!', `MaleText_loc4`='你将付出灵魂的代价！', `MaleText_loc5`='你的靈魂會付出代價!', `MaleText_loc7`='¡Sus almas pagarán el precio!' WHERE `ID`=72019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 멍청이들은 전에 날 처치했다고 생각했겠지만, 덕분에 난 더 강해졌다. 이제 잔달라 부족의 진짜 힘을 보여주자!', `MaleText_loc4`='这些蠢货自以为曾击败过我。这只会让我更加强大。现在，看看赞达拉真正的力量吧！', `MaleText_loc5`='這些蠢貨以為他們擊敗過我。他們只是讓我變得更強。現在讓他們看看贊達拉的真正力量吧!', `MaleText_loc7`='Esos idiotas creyeron derrotarme una vez. Solo consiguieron hacerme más fuerte. ¡Ahora verán el verdadero poder de los Zandalari!' WHERE `ID`=72020;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 션이시여. 잔달라 부족의 힘을 보여드리겠습니다. 놈들을 이 자리에서 처치하겠습니다!', `MaleText_loc4`='雷神要我们证明赞达拉的力量。我们将碾碎这些入侵者！', `MaleText_loc5`='雷神讓我們向你證明贊達拉的力量。我們會徹底碾碎這些入侵者!', `MaleText_loc7`='Lei Shen, permítenos mostrarte el poder de los Zandalari. ¡Aplastaremos a los intrusos dondequiera que se encuentren!' WHERE `ID`=72021;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='실망시키지 않겠습니다!', `MaleText_loc4`='我们绝不会辜负他！', `MaleText_loc5`='我們絕不會讓你失望!', `MaleText_loc7`='¡Nunca te fallaremos!' WHERE `ID`=72022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드라카리가 고작 네놈들에게 쓰러질 줄 아느냐!', `MaleText_loc4`='达卡莱部族绝对不会输给你们这种人！', `MaleText_loc5`='德拉克瑞才不會輸給你們這種貨色!', `MaleText_loc7`='¡Los Drakkari nunca caerán ante sus semejantes!' WHERE `ID`=72023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 상대해주마, 이 바보들아!', `MaleText_loc4`='你们遇到对手了，蠢货！', `MaleText_loc5`='你們碰到剋星了，蠢貨!', `MaleText_loc7`='¡Te acabas de topar con pared, escoria!' WHERE `ID`=72024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제국은... 결코... 무너지지... 않아...', `MaleText_loc4`='帝国……绝不会……陷落……', `MaleText_loc5`='帝國...不能...滅亡...', `MaleText_loc7`='El... imperio... no puede... caer...' WHERE `ID`=72025;
