UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들이 여기가 어딘지도 모르는구나. 가라잘, 이런 미천한 녀석들에게 네 "힘"을 보여주고 싶다면, 마음대로 해라.', `MaleText_loc4`='这些不自量力的爬虫。戈拉亚，要是你想用这些废物来证明“实力”，那我也无所谓。', `MaleText_loc5`='卡拉賈，你若是想靠欺凌這些不知天高地厚的雜碎弱者來證明己身之「力」...那就隨你吧...', `MaleText_loc7`='Estos insectos no conocen su lugar, Gara''jal. Si quieres poner a prueba tu "poder" contra esos debiluchos, adelante.' WHERE `ID`=72049;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구슬의 표면이 불길한 곡선을 그립니다...', `MaleText_loc4`='宝珠邪恶地旋转起来……', `MaleText_loc5`='血靈球體越轉越快...', `MaleText_loc7`='El orbe gira malévolamente...' WHERE `ID`=72050;
