UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 섭정님.', `MaleText_loc4`='大人。', `MaleText_loc5`='大人...', `MaleText_loc7`='Sí, mi señor.' WHERE `ID`=72052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='회수 중', `MaleText_loc4`='正在回收', `MaleText_loc5`='復原中', `MaleText_loc7`='Recuperación', `FemaleText_loc1`='회수 중', `FemaleText_loc4`='正在回收', `FemaleText_loc5`='復原中', `FemaleText_loc7`='Recuperación' WHERE `ID`=72053;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대단하군요. 등장부터 아주 멋지네요.', `FemaleText_loc4`='好啊。你的出场还真拉风。', `FemaleText_loc5`='嗯。你的登場風格還真獨特。', `FemaleText_loc7`='Vaya. A eso llamo yo llegar con estilo.' WHERE `ID`=72054;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오세요. 관문들은 안에서만 열 수 있어요.', `FemaleText_loc4`='这边。这些门只能从内侧开启。', `FemaleText_loc5`='走這裡。門只能從裡面開啟。', `FemaleText_loc7`='Por aquí. Las puertas solo se abren desde adentro.' WHERE `ID`=72055;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='조용히 잠입할 수도, 싸우면서 전진할 수도 있어요. 선택하세요.', `FemaleText_loc4`='我们可以悄悄溜过去，或者直接杀进去。你决定吧。', `FemaleText_loc5`='我們可以安靜地穿過這裡，或一路打過去。你來決定。', `FemaleText_loc7`='Podemos infiltrarnos sigilosamente o luchar para abrirnos paso. Tú decides.' WHERE `ID`=72056;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구들은 피와 강철로 제련된 무기를 다뤄요. 저들의 칼은 죽음을 탐닉하죠.', `FemaleText_loc4`='魔古族用鲜血和钢铁锻造武器。他们的利刃必须啜饮死亡。', `FemaleText_loc5`='魔古的武器是由鮮血與鋼鐵所鑄造。他們的刀刃帶來死亡。', `FemaleText_loc7`='Los mogu forjan armas de sangre y acero. Sus espadas se alimentan de la muerte.' WHERE `ID`=72057;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노예... 전부 노예들이에요. 우리의 상대가 누구인지 아시겠죠.', `FemaleText_loc4`='奴隶——到处都是奴隶。你明白我们为何要抗争了吧。', `FemaleText_loc5`='奴隸 - 到處都是奴隸。你能了解我們就是要對抗暴權下的奴役。', `FemaleText_loc7`='Esclavos... por todas partes. ¿Ves? Esto es contra lo que luchamos.' WHERE `ID`=72058;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파는 어둠 속에서 공격해요. 그래서 적들은 암흑을 두려워하죠.', `FemaleText_loc4`='影踪派总是从阴影中出击，让我们的敌人惧怕黑暗。', `FemaleText_loc5`='影潘從陰影中襲擊，如此才能讓我們的敵人畏懼黑暗。', `FemaleText_loc7`='El Shadopan ataca desde las sombras para que nuestros enemigos teman a la oscuridad.' WHERE `ID`=72059;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='산전수전 다 겪어봤지만 모구의 잔혹함에는 아직도 치가 떨리네요.', `FemaleText_loc4`='我也算见过些场面。可魔古族的残暴还是令我的血液为之凝固。', `FemaleText_loc5`='我見識過許多東西。但魔古的殘酷仍然讓我感到毛骨悚然。', `FemaleText_loc7`='He visto muchas cosas, pero la crueldad de los mogu aún me hiela la sangre.' WHERE `ID`=72060;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구 전쟁 기계의 심장부에 도착했군요.', `FemaleText_loc4`='我们进入了魔古战争机器的核心。', `FemaleText_loc5`='我們已經來到魔古戰爭機器的中心地帶。', `FemaleText_loc7`='Estamos en el corazón de la maquinaria de guerra mogu.' WHERE `ID`=72061;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 오직 이 순간을 위해 평생을 수련했어요.', `FemaleText_loc4`='我为此苦练了一辈子。', `FemaleText_loc5`='我一生都為了此刻而鍛鍊。', `FemaleText_loc7`='Me he preparado toda la vida para esto.' WHERE `ID`=72062;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파에게선 도망칠 수 없다는 걸 가르쳐주겠어요.', `FemaleText_loc4`='他们会明白，在影踪派面前，没有安全的地方。', `FemaleText_loc5`='他們會學到永遠逃不出影潘的手掌心。', `FemaleText_loc7`='Aprenderán que no pueden esconderse del Shadopan.' WHERE `ID`=72063;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 빠르고 조용히 처리하는 걸 좋아하지만, 당신 방법도 나쁘진 않네요.', `FemaleText_loc4`='我喜欢迅捷而安静的杀戮。但你的方式也有好处。', `FemaleText_loc5`='我偏好快速而安靜的擊殺。但你的方式也有優點。', `FemaleText_loc7`='Yo prefiero matar con sigilo, pero tus métodos tienen sus ventajas.' WHERE `ID`=72064;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신의 기량은 정말 놀랍군요.', `FemaleText_loc4`='你的战斗技巧很惊人。', `FemaleText_loc5`='你的戰鬥技巧令人佩服。', `FemaleText_loc7`='Tu pericia en combate es impresionante.' WHERE `ID`=72065;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파는 절대 멈추지 않아요.', `FemaleText_loc4`='影踪派永不停歇。', `FemaleText_loc5`='影潘將奮戰到底。', `FemaleText_loc7`='El Shadopan no descansa nunca.' WHERE `ID`=72066;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오세요! 관문에 거의 다 왔어요.', `FemaleText_loc4`='放轻脚步！我们就快到门边上了。', `FemaleText_loc5`='腳步放輕點!我們快到門口了。', `FemaleText_loc7`='¡Cuidado! Ya casi llegamos a la puerta.' WHERE `ID`=72067;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='노예감독이 저깄군요! 놈의 주의를 끌면 제가 자물쇠를 풀어보죠.', `FemaleText_loc4`='看——奴隶主！你去引开他，我来开锁。', `FemaleText_loc5`='奴隸主在那裡!引開他的注意力，我趁機開鎖。', `FemaleText_loc7`='¡Ahí está el maestro de esclavos! Distráelo mientras fuerzo la cerradura.' WHERE `ID`=72068;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 자물쇠는... 생각보다 훨씬 복잡하네요.', `FemaleText_loc4`='这锁……比我预想的还要复杂……', `FemaleText_loc5`='這個鎖...比我想像中複雜...', `FemaleText_loc7`='La cerradura es más complicada de lo que pensaba...' WHERE `ID`=72069;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈을 막으세요! 거의 다 돼가요.', `FemaleText_loc4`='缠住他！我就快成功了！', `FemaleText_loc5`='纏住他!我快搞定了!', `FemaleText_loc7`='¡Mantenlo ocupado! ¡Ya casi está!' WHERE `ID`=72070;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈어요! 관문이 열렸어요!', `FemaleText_loc4`='成功了！门打开了！', `FemaleText_loc5`='成功了!鎖已經打開了!', `FemaleText_loc7`='¡Lo logré! ¡Las puertas se abren!' WHERE `ID`=72071;
