UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아마니 부족 문에서 아마니 병력들이 쏟아져 나옵니다!', `MaleText_loc4`='阿曼尼大军从阿曼尼部族之门中涌出！', `MaleText_loc5`='阿曼尼部隊從阿曼尼部族的門蜂擁而出!', `MaleText_loc7`='¡Las fuerzas Amani salen en tropel desde la puerta tribal Amani!', `FemaleText_loc1`='아마니 부족 문에서 아마니 병력들이 쏟아져 나옵니다!', `FemaleText_loc4`='阿曼尼大军从阿曼尼部族之门中涌出！', `FemaleText_loc5`='阿曼尼部隊從阿曼尼部族的門蜂擁而出!', `FemaleText_loc7`='¡Las fuerzas Amani salen en tropel desde la puerta tribal Amani!' WHERE `ID`=72075;
