UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 주인처럼 보인 후에 다시 와라.', `MaleText_loc4`='归来吧，我的主人。', `MaleText_loc5`='回歸為我的主人。', `MaleText_loc7`='Vuelve como mi señor.' WHERE `ID`=72077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 너의 주인이다.', `MaleText_loc4`='我就是你的主人。', `MaleText_loc5`='我是你的主人。', `MaleText_loc7`='Soy tu señor.', `FemaleText_loc1`='내가 너의 주인이다.', `FemaleText_loc4`='我就是你的主人。', `FemaleText_loc5`='我是你的主人。', `FemaleText_loc7`='Soy tu señora.' WHERE `ID`=72078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 정도면... 봐주지.', `MaleText_loc4`='别……过来。', `MaleText_loc5`='差...不多啦。', `MaleText_loc7`='Más o menos...' WHERE `ID`=72079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전혀 그와 닮아보이지 않군.', `MaleText_loc4`='你看起来不太像他。', `MaleText_loc5`='你一點也不像他。', `MaleText_loc7`='No te pareces en nada a él.' WHERE `ID`=72080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 그게 아니라고! 얼른 내려놔!', `MaleText_loc4`='不！不不！放下它。', `MaleText_loc5`='不!不不不!把他們放下來。', `MaleText_loc7`='¡No! No, no, no. Suéltalo.' WHERE `ID`=72081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 아직도 거기 서 있는 거야? 상자를 나르라니까!', `MaleText_loc4`='你们还站在那里做什么？把那些箱子运走！', `MaleText_loc5`='還站在那兒發呆幹什麼?把箱子送過去!', `MaleText_loc7`='¿Qué haces ahí? ¡Entrega esas cajas!' WHERE `ID`=72082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피조물이 쉬라고 있는 시간이 아니야. 일하라고.', `MaleText_loc4`='这不是结构性的损坏。回去干活儿。', `MaleText_loc5`='傀儡休息時間還沒到，回去工作!', `MaleText_loc7`='No es la hora de descanso para los ensamblajes. Vuelve al trabajo.' WHERE `ID`=72083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걷는 법을 알기나 하는 거냐? 이 쓸모없는 금색 고철 덩어리야, 다리를 움직이란 말이다!', `MaleText_loc4`='你是不是连走路都不会了？赶紧动动腿，你这一无是处的废物！', `MaleText_loc5`='你是連走路都不會嗎?把你那雙沒用的廢腿給我動起來!', `MaleText_loc7`='¿Acaso sabes andar? ¡Mueve esas piernas, inútil montón de chatarra dorada!' WHERE `ID`=72084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통은 어딨어? 통을 잃어버린 거냐? 통이 더 필요하다!', `MaleText_loc4`='那些桶呢？被你弄丢了？我们需要更多的桶！', `MaleText_loc5`='桶子咧?你是不是把桶子全搞丟了?我們需要更多桶子!', `MaleText_loc7`='¿Dónde están los barriles? ¿Los has perdido? ¡Necesitamos más!' WHERE `ID`=72085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상자를 한 번만 더 떨어뜨리면 마력을 추출해 버릴 테다.', `MaleText_loc4`='如果你再敢弄丢一个箱子，我发誓我一定要把你拆了。', `MaleText_loc5`='要是你再摔掉一個箱子，我發誓我一定會把你送去拆解掉。', `MaleText_loc7`='Si dejas caer una caja más, te juro que te mando directo a que te desencanten.' WHERE `ID`=72086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 또 잃어버릴 수가 있지? 내 신발에 달린 보석도 너보다는 똑똑하겠다.', `MaleText_loc4`='你怎么又把货物弄丢了？我发誓，我鞋子里的宝石都比你聪明。', `MaleText_loc5`='你怎麼又搞丟一個了?天啊，我鞋子上的寶石都比你還聰明。', `MaleText_loc7`='¿Cómo has podido perder otro? Te juro que las gemas de mis zapatos tienen más intelecto que tú.' WHERE `ID`=72087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='짐꾼 도착.', `MaleText_loc4`='货物已经抵达。', `MaleText_loc5`='載運艦已經到了。', `MaleText_loc7`='EL PORTACAJAS HA LLEGADO.' WHERE `ID`=72088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이론적으로, 이 결정은 천연 절연체입니다. 이 지역에 내리치는 번개를 대부분 흡수할 것입니다.', `MaleText_loc4`='理论上说，这些水晶都是天然的绝缘体。它们可以吸收这个地区的大部分闪电打击。', `MaleText_loc5`='理論上，這些水晶是天然的絕緣體，應該能吸收掉絕大多數的雷擊。', `MaleText_loc7`='En teoría estos cristales son aislantes naturales. Deberían absorber la mayoría de los relámpagos que caigan en la zona.', `FemaleText_loc1`='이론적으로, 이 결정은 천연 절연체예요. 이 지역에 내리치는 번개를 대부분 흡수할 거예요.', `FemaleText_loc4`='理论上说，这些水晶都是天然的绝缘体。它们可以吸收这个地区的大部分闪电打击。', `FemaleText_loc5`='理論上，這些水晶是天然的絕緣體，應該能吸收掉絕大多數的雷擊。', `FemaleText_loc7`='En teoría estos cristales son aislantes naturales. Deberían absorber la mayoría de los relámpagos que caigan en la zona.' WHERE `ID`=72089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결정이 마나를 얼마나 소모하는지 설명서에 나와 있습니까? 이걸 쓰다가 버림받은 자가 되고 싶진 않습니다.', `MaleText_loc4`='说明书上写明这些水晶需要多少法力了吗？我可不想在用了它之后就变成任人宰割的可怜虫。', `MaleText_loc5`='說明有講清楚這些水晶要耗用多少法力嗎?我可不想用了之後就被榨乾啊。', `MaleText_loc7`='¿Especificaban las instrucciones cuánto maná necesitan estos cristales? No quiero acabar destrozado por usar esta cosa.', `FemaleText_loc1`='결정이 마나를 얼마나 소모하는지 설명서에 나와 있나요? 이걸 쓰다가 버림받은 자가 되고 싶진 않아요.', `FemaleText_loc4`='说明书上写明这些水晶需要多少法力了吗？我可不想在用了它之后就变成任人宰割的可怜虫。', `FemaleText_loc5`='說明有講清楚這些水晶要耗用多少法力嗎?我可不想用了之後就被榨乾啊。', `FemaleText_loc7`='¿Especificaban las instrucciones cuánto maná necesitan estos cristales? No quiero acabar destrozado por usar esta cosa.' WHERE `ID`=72090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왼쪽에 있는 결정에 하자가 있는 것 같습니다. 급하게 만든 게 잘못이지요. 사고란 이렇게 생기는 법이지요.', `MaleText_loc4`='我觉得左边那块水晶有瑕疵。我们不该赶工的。事故就是这么来的。', `MaleText_loc5`='左邊的那個水晶好像有瑕疵，我們不該草草趕工，意外往往就是這樣發生的。', `MaleText_loc7`='Creo que el cristal de la izquierda es defectuoso. No deberíamos habernos precipitado en su construcción. Así es como ocurren los accidentes.', `FemaleText_loc1`='왼쪽에 있는 결정에 하자가 있는 것 같아요. 급하게 만든 게 잘못이죠. 사고란 이렇게 생기는 법이지요.', `FemaleText_loc4`='我觉得左边那块水晶有瑕疵。我们不该赶工的。事故就是这么来的。', `FemaleText_loc5`='左邊的那個水晶好像有瑕疵，我們不該草草趕工，意外往往就是這樣發生的。', `FemaleText_loc7`='Creo que el cristal de la izquierda es defectuoso. No deberíamos habernos precipitado en su construcción. Así es como ocurren los accidentes.' WHERE `ID`=72091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이 섬에서는 어딜 가든 머리끝이 쭈뼛한 느낌이 들까요?', `MaleText_loc4`='这座岛是怎么回事？为什么不管我走到哪里，我的头发总是会竖起来？', `MaleText_loc5`='為什麼這座島不論我走到哪裡，總感覺身上的毛髮好像都豎起來了?', `MaleText_loc7`='¿Por qué se me ponen los pelos de punta dondequiera que vaya en esta isla?', `FemaleText_loc1`='왜 이 섬에서는 어딜 가든 머리끝이 쭈뼛한 느낌이 들까요?', `FemaleText_loc4`='这座岛是怎么回事？为什么不管我走到哪里，我的头发总是会竖起来？', `FemaleText_loc5`='為什麼這座島不論我走到哪裡，總感覺身上的毛髮好像都豎起來了?', `FemaleText_loc7`='¿Por qué se me ponen los pelos de punta dondequiera que vaya en esta isla?' WHERE `ID`=72092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 날이면 타락한 마법을 쓰고 싶어집니다. 마법은 사악하긴 했지만, 일 처리하는 데는 확실히 도움이 됐으니까요.', `MaleText_loc4`='每当这种时候，我都会怀念以前使用邪法的光景。它虽然很邪恶，但很管用。', `MaleText_loc5`='這種時候尤其讓人懷念魔化魔法，雖然邪惡，但是很管用啊。', `MaleText_loc7`='En días como este, echo de menos usar la magia. Era maligna, es verdad, pero hacía el trabajo.', `FemaleText_loc1`='이런 날이면 타락한 마법을 쓰고 싶어져요. 마법은 사악하긴 했지만, 일 처리하는 데는 확실히 도움이 됐으니까요.', `FemaleText_loc4`='每当这种时候，我都会怀念以前使用邪法的光景。它虽然很邪恶，但很管用。', `FemaleText_loc5`='這種時候尤其讓人懷念魔化魔法，雖然邪惡，但是很管用啊。', `FemaleText_loc7`='En días como este, echo de menos usar la magia. Era maligna, es verdad, pero hacía el trabajo.' WHERE `ID`=72093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 저 테러윙들을 처치할 수 있을까요?', `MaleText_loc4`='这些足够消灭那些飞翼龙了吗？', `MaleText_loc5`='這樣夠打掉那些翼手龍嗎?', `MaleText_loc7`='¿Serán suficientes para derribar a esos pterroralas?', `FemaleText_loc1`='이 정도면 저 테러윙들을 처치할 수 있을까요?', `FemaleText_loc4`='这些足够消灭那些飞翼龙了吗？', `FemaleText_loc5`='這樣夠打掉那些翼手龍嗎?', `FemaleText_loc7`='¿Serán suficientes para derribar a esos pterroralas?' WHERE `ID`=72094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 결정은 자연 상태에서 푸른색이라는 이야기를 들었습니다. 누군지 몰라도 미적인 측면에 공을 들여 주어 고맙군요.', `MaleText_loc4`='有人告诉我，这些水晶在天然状态下是蓝色的。我很高兴有人花时间做了点适当的美化。', `MaleText_loc5`='有人跟我說，這些水晶原本都是藍色的。我很高興有人願意花時間把它弄漂亮一點。', `MaleText_loc7`='He oído que estos cristales en estado natural son azules. Me encanta que alguien se haya tomado la molestia de preocuparse de la estética.', `FemaleText_loc1`='이 결정은 자연 상태에서 푸른색이라는 이야기를 들었어요. 누군지 몰라도 미적인 측면에 공을 들여 주어 고맙네요.', `FemaleText_loc4`='有人告诉我，这些水晶在天然状态下是蓝色的。我很高兴有人花时间做了点适当的美化。', `FemaleText_loc5`='有人跟我說，這些水晶原本都是藍色的。我很高興有人願意花時間把它弄漂亮一點。', `FemaleText_loc7`='He oído que estos cristales en estado natural son azules. Me encanta que alguien se haya tomado la molestia de preocuparse de la estética.' WHERE `ID`=72095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 트롤의 지배자인 라스타칸 신왕은 순금을 깎아 만든 왕좌에서 강대한 왕국을 지배했다고 하네.', `MaleText_loc4`='据说赞达拉的统治者，神王拉斯塔哈在黄金宝座上统治着自己强大的帝国。', `MaleText_loc5`='據說神王拉斯塔哈，贊達拉的統治者，從一個完全由黃金打造的寶座上統領著他強大的王國。', `MaleText_loc7`='Se dice que el rey divino Rastakhan, líder de los Zandalari, gobierna su poderoso reino desde un trono de oro macizo.' WHERE `ID`=72096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 전, 그 호화로운 권좌에 앉아 있던 그에게 어둠의 예언자 줄이 찾아왔네.', `MaleText_loc4`='多年前，他就在这个辉煌的宝座上，接见了黑暗先知：祖尔。', `MaleText_loc5`='在多年前，他坐在這個閃亮的寶座上，接待他最信任的先知:祖爾。', `MaleText_loc7`='Hace años, mientras permanecía sentado en su opulento trono, lo visitó el profeta oscuro: Zul.' WHERE `ID`=72097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='줄은 끔찍한 대격변이 일어날 거라고 라스타칸에게 경고했네. 거대한 철갑의 용이 그 주둥이로 세계를 물어 뜯는 환영을 봤거든.', `MaleText_loc4`='祖尔向拉斯塔哈警告了可怕的大灾变。因为祖尔预见到一头装甲巨龙用可怕的巨颚撕裂了世界。', `MaleText_loc5`='祖爾警告拉斯塔哈王未來會發生可怕的大災變。因為，祖爾在看到的幻象中，有條巨大的鐵甲巨龍用可怕的巨顎咬住了整個世界。', `MaleText_loc7`='Zul previno al rey Rastakhan de un terrible Cataclismo, pues había tenido una visión sobre un gran dragón blindado que aplastaba el mundo con sus mandíbulas.' WHERE `ID`=72098;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕은 아무 것도 하지 않았네.', `MaleText_loc4`='拉斯塔哈无动于衷。', `MaleText_loc5`='拉斯塔哈王什麼都沒做。', `MaleText_loc7`='El rey Rastakhan no reaccionó.' WHERE `ID`=72099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여러 달 후에, 줄이 더 끔찍한 예언과 함께 돌아왔네. 대양의 바닥이 갈라진 틈에서 뱀들이 쏟아져 나오는 모습을 봤다고 했지.', `MaleText_loc4`='几个月之后，祖尔又带回了更可怕的预言。他看见大群蛟龙从张开的裂隙中汹涌而出，撕裂了海床。', `MaleText_loc5`='過了幾個月祖爾回來了，帶來更多關於預言的可怕消息。他看到無數的毒蛇從海底的裂口中竄出。', `MaleText_loc7`='Meses después, Zul volvió a traer malas noticias. Había visto una legión de serpientes que manaba de una enorme grieta en el fondo del océano.' WHERE `ID`=72100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도, 국왕은 아무 것도 하지 않았네.', `MaleText_loc4`='拉斯塔哈还是无动于衷。', `MaleText_loc5`='拉斯塔哈王還是什麼都沒做。', `MaleText_loc7`='El rey Rastakhan siguió impasible.' WHERE `ID`=72101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마침내, 대격변을 몇 달 남겨두고, 줄은 돌아와 자신의 옷을 찢고 지팡이를 집어 던지며, 지진과 해일이 닥쳐올 거라고 말했네.', `MaleText_loc4`='最后，在大灾变发生的几个月前，祖尔又回来了。他撕碎衣裳，扔掉法杖，预言了地震与海啸的到来。', `MaleText_loc5`='最後，在大災變的數個月前，祖爾回來了。他把衣服撕開，把法杖丟在地上，述說他看到的地震和海嘯。', `MaleText_loc7`='Al final, unos meses antes del Cataclismo, Zul regresó. Zul habló de terremotos y maremotos tras desgarrarse la ropa y tirar el bastón al suelo.' WHERE `ID`=72102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대격변의 여파로 인해 잔달라의 황금 도시가 서서히 파도 아래로 가라앉을 거라고 설명했지. 강대한 백성들도 모두 수장되고, 경이로운 문명 역시 바다 속으로 사라질 거라고.', `MaleText_loc4`='他描述了赞达拉的黄金都城将在大灾变后慢慢沉入海底，昔日伟大的人民随着自己的杰作永远葬身海底。', `MaleText_loc5`='他敘述著贊達拉的黃金城市在大災變造成的海嘯中慢慢沉沒，當中的人們隨著他們雄偉的建築一起永遠地沉入了海中。', `MaleText_loc7`='Describió cómo la capital dorada de Zandalar se hundía lentamente bajo las olas como secuela del Cataclismo, cómo su otrora grandioso pueblo se ahogaba junto con sus obras para siempre.' WHERE `ID`=72103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='라스타칸은 줄의 악몽이 지겨웠네. 그래서 줄에게 커다란 함선들을 주고 멀리 떠나 보냈어. 예언이 실현될 때를 대비해, 그에게 새로운 땅을 찾아내라고 명령했지.', `MaleText_loc4`='拉斯塔哈厌烦了祖尔和他的噩梦。为了摆脱先知，他让祖尔乘上自己最大的船只，好让他和他的追随者在预言实现时去寻找新大陆。', `MaleText_loc5`='拉斯塔哈王對祖爾和他討厭的夢魘感到了厭煩。為了趕走這位先知，他讓祖爾使用他最大的那些船艦，若他的預言屬實，祖爾和他的追隨者就能乘船找到新的土地居住。', `MaleText_loc7`='El rey Rastakhan se cansó de Zul y sus profecías perturbadoras. Para deshacerse del profeta, le permitió usar sus naves más grandes para que buscara una tierra nueva en caso de que se cumplieran sus visiones.' WHERE `ID`=72104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 그 예언은 정말로 실현되었네.', `MaleText_loc4`='他的预言真的实现了。', `MaleText_loc5`='而他的預言的確成真了。', `MaleText_loc7`='Y, en efecto, se cumplieron.' WHERE `ID`=72105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 소용돌이에서 데스윙이 날아오를 때, 검은 분노의 해일이 잔달라의 수도를 덥쳤네. 대지는 두 개로 쪼개졌고, 결국 그 찬란했던 도시는 바다 아래로 가라앉았지.', `MaleText_loc4`='当死亡之翼冲出大漩涡，黑暗的怒涛涌入赞达拉的都城。大地之脊一分为二，很快，这座城市和它所有的财富一同沉入大海。', `MaleText_loc5`='當死亡之翼從大漩渦中飛出時，黑暗、憤怒的浪潮將贊達拉的首都摧毀了。大地一分為二，很快的，城市和它所有的寶藏都開始滑入飢餓的海洋中。', `MaleText_loc7`='Cuando Alamuerte emergió de La Vorágine, sombrías y furiosas olas rompieron en la capital Zandalari. La tierra se partió en dos y pronto el hambriento mar empezó a engullir la ciudad y todas sus riquezas.' WHERE `ID`=72106;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 백성들은 국왕의 도움을 구했지만, 그들을 도울 준비가 된 자는 단 하나, 예언자 줄 뿐이었네. 예언자는 국왕이 아무 것도 하지 않는 사이에 커다란 함대를 꾸려 놓았거든.', `MaleText_loc4`='赞达拉人向他们的君王求助，可只有一个人能帮他们：先知祖尔。这位先知在他的国王麻木不仁时，已经召集了一支强大的舰队。', `MaleText_loc5`='贊達拉的人民轉向國王求救，但只有一個人有足夠的準備拯救他們:先知祖爾。在他們的國王沒有作為時，這位先知組成了一支強大的艦隊。', `MaleText_loc7`='Los Zandalari acudieron a su Rey pidiendo ayuda, pero solo había un Zandalari capaz de ayudarlos: el profeta Zul. Él y la poderosa flota de guerra que había reunido mientras el Rey los ignoraba.' WHERE `ID`=72107;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠나? 왕과 황제의 진정한 힘은, 백성을 돕는 것으로부터 나오는 것이네.', `MaleText_loc4`='现在你该明白了，君王们真正的力量源于帮助自己的人民。', `MaleText_loc5`='看出來了嗎，國王和皇帝真正的力量來自於擁有幫助自己人民的力量。', `MaleText_loc7`='El VERDADERO poder de los reyes y emperadores yace en la capacidad de ayudar a su pueblo.' WHERE `ID`=72108;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러지 못하는 순간, 그 힘은 백성을 위하는 이에게 돌아가지.', `MaleText_loc4`='当他们玩忽职守时，就将权利让给了有能力的人。', `MaleText_loc5`='若他們沒有做到這點，他們只是把力量轉讓給了可以做到的人。', `MaleText_loc7`='Cuando fracasan, ceden su poder al que sí puede ayudar.' WHERE `ID`=72109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에게는 천둥왕 레이 션에 대한 전설이 있네.', `MaleText_loc4`='魔古族中流传着雷电之王雷神的传说。', `MaleText_loc5`='魔古的傳說中提到了雷神，又叫雷霆之王。', `MaleText_loc7`='Los mogu cuentan la leyenda de Lei Shen, el Rey del Trueno.' WHERE `ID`=72110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='추종자들이 그 앞에 무릎을 꿇고 말했네. "당신을 번개왕으로 모시겠나이다."라고.', `MaleText_loc4`='他的追随者向他跪下，并说：“我们将称您为‘闪电之王’。”', `MaleText_loc5`='他的追隨者全都跪倒在他面前。他們說:「我們會稱呼您為閃電之王」。', `MaleText_loc7`='Sus seguidores se arrodillaron ante él. "Te llamaremos ''Rey del Rayo''", dijeron.' WHERE `ID`=72111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 모구의 신에게서 심장을 뜯어냈다고 하네. 그리고 그 끔찍한 행동을 통해, 바람과 폭풍을 지배하는 힘을 얻었지.', `MaleText_loc4`='据说他挖出了魔古之神的心脏。这骇人听闻的暴行令野心勃勃的雷神获得了风暴的力量。', `MaleText_loc5`='據說他把魔古之神的心臟挖了出來，並且藉由這樣的殘酷暴行獲得了控制風暴的能力。', `MaleText_loc7`='Se dice que le arrancó el corazón al mismísimo dios mogu. Y con ese despreciable acto se apoderó del viento y la tormenta.' WHERE `ID`=72112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나, 레이 션은 생각이 달랐네.', `MaleText_loc4`='但雷神并不满意。', `MaleText_loc5`='但是雷神並不同意。', `MaleText_loc7`='Pero Lei Shen no estaba de acuerdo.' WHERE `ID`=72113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 말했지. "번개는 단 한 순간의 번쩍임에 불과하다."', `MaleText_loc4`='“闪电的力量转瞬即逝，”他说道。', `MaleText_loc5`='他說:「閃電在瞬間出現，也在瞬間結束。」', `MaleText_loc7`='"El rayo cae al instante y se desvanece con un destello", dijo.' WHERE `ID`=72114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"그러나 천둥! 천둥은 폭풍이 올 것임을 선고한다."', `MaleText_loc4`='“可雷电。雷电！它预示着风暴的来临。”', `MaleText_loc5`='「但是雷就不一樣了。雷霆啊雷霆!它宣告了風暴的來臨。」', `MaleText_loc7`='"Pero el trueno... ¡El trueno anuncia que se avecina la tormenta!"' WHERE `ID`=72115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"천둥은 번개가 떨어지기 오래 전부터 온 하늘을 뒤흔들고, 번개의 세력이 사그라든 후에도 오랫동안 골짜기에 메아리친다."', `MaleText_loc4`='“在闪电到来之前，雷电已经撼动苍穹；当闪电消散之后，雷电依然振动群山。”', `MaleText_loc5`='「在閃電出現之前，雷霆早已震動整片天空。在閃電的力量消逝後，雷霆仍在山丘之間迴盪不休。」', `MaleText_loc7`='"El trueno agita los cielos antes de que caiga el rayo y resuena en las montañas mucho después de que se agota la energía del rayo".' WHERE `ID`=72116;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"동물들이 겁을 집어먹게 하고, 천민의 가슴에 공포를 불어넣는 것은 천둥이다. 천둥이 내 전령이 되게 하라. 모든 곳에서 내 힘을 느낄 수 있게."', `MaleText_loc4`='“是雷电令百兽瑟缩，是雷电令农夫恐惧。就让雷电成为我的先驱，让我的力量传遍大地。”', `MaleText_loc5`='「只有雷霆能使動物逃竄，使農民的心中充滿恐懼。雷霆就是我的傳令使，讓整個大地都感受到我的力量。」', `MaleText_loc7`='"El trueno acobarda a los animales e inunda los corazones de los aldeanos de temor. Hagan del trueno mi heraldo para que mi poder resuene por toda la tierra".' WHERE `ID`=72117;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"나는... 천둥왕이 되겠다."', `MaleText_loc4`='“我将成为……雷电之王。”', `MaleText_loc5`='「我就是...雷霆之王。」', `MaleText_loc7`='"Yo seré... el Rey del Trueno".' WHERE `ID`=72118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 친구여. 끔찍한 소리였네. 천둥은 오랜 세월에 걸쳐 우르릉거리며, 판다렌의 가슴을 공포로 채웠네.', `MaleText_loc4`='噢，我的朋友——那可怕的声音。数百年来，雷电可怕的巨响一直在熊猫人心中回荡。', `MaleText_loc5`='噢我的朋友，那個恐怖的聲音。數百代以來，雷霆的聲音使熊貓人的心中充滿了恐懼。', `MaleText_loc7`='Ah, qué sonido tan espantoso. Durante cientos de generaciones el fragor del trueno aterrorizó a los pandaren.' WHERE `ID`=72119;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전설에 따르면 혁명 이후에 희망의 상징인 주학께서 하늘에 무지개를 세우셨다고 하네. 판다렌들이 폭풍의 두려움을 잊어버리게 하려고.', `MaleText_loc4`='据说在熊猫人发动起义之后，希望的化身朱鹤在天空挂上了彩虹，好让熊猫人不再害怕风暴。', `MaleText_loc5`='聽說在革命成功後，象徵希望的紅鶴在空中放了一條彩虹，讓熊貓人知道不需要再畏懼風暴。', `MaleText_loc7`='Cuenta la leyenda que, tras la revolución, la Grulla Roja de la Esperanza creó el arcoíris para que los pandaren dejaran de temer a la tormenta.' WHERE `ID`=72120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 무지개를 못 봤는데. 자넨 어떤가?', `MaleText_loc4`='我今天却没看见彩虹。你呢？', `MaleText_loc5`='但我今天沒有看到彩虹，你有嗎?', `MaleText_loc7`='Hoy no veo ningún arcoiris. ¿Y tú?' WHERE `ID`=72121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아버지와 아들, 어머니와 딸. 부모로서, 우리는 아이들에게 유산을 물려주네.', `MaleText_loc4`='父传子，母教女。作为父母，我们会将自己的遗产传给孩子。', `MaleText_loc5`='由父到子，由母到女。身為父母，我們把自己的遺產傳給孩子。', `MaleText_loc7`='Padres e hijos. Madres e hijas. Como padres le entregamos un legado a nuestros hijos.' WHERE `ID`=72122;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 자식들에게 어떤 가치를 심어줘야 할까?', `MaleText_loc4`='我们该给后代灌输怎样的价值观呢？', `MaleText_loc5`='我們會灌輸什麼價值觀給後代呢?', `MaleText_loc7`='¿Qué valores elegimos inculcar a nuestra progenie?' WHERE `ID`=72123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 실수로부터 아이들은 무엇을 배울까?', `MaleText_loc4`='孩子会从我们的错误中学到什么？', `MaleText_loc5`='我們的子孫是否會從我們的錯誤中學習?', `MaleText_loc7`='¿Aprenderán los hijos de nuestros errores?' WHERE `ID`=72124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 과연 어떤 세상을 만들어서 아들딸에게 물려줘야 할까?', `MaleText_loc4`='我们该给子孙后代创造并留下一个怎样的世界？', `MaleText_loc5`='我們會創造並留下什麼樣的世界給我們的子女?', `MaleText_loc7`='¿Qué clase de mundo crearemos y dejaremos para nuestras hijas e hijos?' WHERE `ID`=72125;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부모는 아이들에게 걸음마를 가르쳐 주지만, 그 걸음이 아이들을 어디로 이끌지는 모른다네.', `MaleText_loc4`='父母将孩子送上人生的道路，却不知道他们会走向何方。', `MaleText_loc5`='父母會替子女指出道路，但他們不一定知道那條路會通往何處。', `MaleText_loc7`='Los padres muestran el camino a sus hijos, pero no siempre saben adónde los conducirá.' WHERE `ID`=72126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구도 마찬가지였어. 그들은 티탄의 자식들이었네. 바위를 품어 만들어진, 차갑고 순종적인 존재였지.', `MaleText_loc4`='魔古族也是孩子。泰坦的孩子。他们曾是一支岩石大军，没有思想，只懂服从。', `MaleText_loc5`='魔古也是孩子。泰坦的孩子。他們原本只是一群石頭，沒有思想，非常聽話。', `MaleText_loc7`='Los mogu también fueron hijos. Los hijos de los titanes. Una vez fueron una legión de piedra sumisa e insensible.' WHERE `ID`=72127;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄의 명령에 따라, 그들은 고대신의 끔찍한 하수인들과 싸웠네. 흙을 쌓아 산을 만들고 땅을 파서 강을 만들었지.', `MaleText_loc4`='他们按泰坦的指令与古神的可怕仆从战斗。他们垒起高山，挖开河流。', `MaleText_loc5`='在泰坦的命令下，他們與上古之神的恐怖僕從們作戰。他們改變了山脈，挖出了大地上的河流。', `MaleText_loc7`='Por orden de los titanes, lucharon contra los crueles sirvientes de los dioses antiguos. Esculpieron las montañas y formaron los ríos.' WHERE `ID`=72128;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 숨겨진 계곡에 신비한 생명의 요람을 만들었네. 우리가 영원꽃 골짜기라 부르는 곳에.', `MaleText_loc4`='他们在今天被我们称为锦绣谷的隐秘山谷建立了生命的魔法摇篮。', `MaleText_loc5`='他們在我們如今稱為恆春谷的秘密山谷中創造了一個魔法的生命搖籃。', `MaleText_loc7`='Y crearon una cuna de vida mágica en un valle oculto que hemos bautizado como el Valle de la Flor Eterna.' WHERE `ID`=72129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='결국에는 티탄도 침묵하게 되었고, 그들의 피조물은 육신의 저주를 받았지.', `MaleText_loc4`='可是，泰坦逐渐沉寂，他们的造物受到血肉的诅咒。', `MaleText_loc5`='但最終泰坦沉默了。而他們的造物受到了血肉詛咒。', `MaleText_loc7`='Pero los titanes se sumieron en el silencio y sus creaciones sufrieron la maldición de la carne.' WHERE `ID`=72130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 안절부절못했네. 그리고 여러 세대가 지나, 천둥왕은 모구를 통일하고, 티탄의 유산을 차지했지.', `MaleText_loc4`='魔古族变得残暴。多年之后，雷电之王统一了他们，他们获得了自己的遗产！', `MaleText_loc5`='魔古因此感到不安。許多代之後，當雷王統一他們時，他們抓住了屬於他們的遺產!', `MaleText_loc7`='Los mogu se inquietaron. Muchas generaciones más tarde, cuando el Rey del Trueno los unificó, ¡aceptaron su legado!' WHERE `ID`=72131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 모구가 티탄이 못다한 일을 계속하고자 했다고 믿네. 그들은 사마귀와 싸우고 골짜기의 힘을 이용해서 새로운 생명체를 만들었어.', `MaleText_loc4`='我现在真的相信魔古族以为自己在完成泰坦的工作。他们与螳螂妖斗争，并使用锦绣谷的力量创造新生命。', `MaleText_loc5`='我現在真的相信魔古認為他們在進行泰坦的工作。他們與螳螂人作戰，並使用恆春谷的力量創造新生命。', `MaleText_loc7`='Creo que los mogu pensaron que cumplían la voluntad de los titanes. Lucharon contra los mántides y crearon nueva vida con los poderes del valle.' WHERE `ID`=72132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 그렇게 끔찍한 결과가 되다니!', `MaleText_loc4`='啊，多么可怕的工作！', `MaleText_loc5`='啊，但是他們的作品真可怕!', `MaleText_loc7`='Ah, ¡pero qué obra tan terrible!' WHERE `ID`=72133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부모는 자신들의 유산이 어떻게 쓰일지 확신할 수 없는 법이네.', `MaleText_loc4`='父母并不能确保自己总能留下好的遗产。', `MaleText_loc5`='父母們不一定能保證他們留下什麼樣的遺產。', `MaleText_loc7`='Los padres no siempre pueden estar seguros de la herencia que dejan.' WHERE `ID`=72134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 경우엔 더욱 그랬겠지. 부모는 신이었는데, 자식들은 괴물이었으니...', `MaleText_loc4`='尤其是，当父母本身是神，而他们的孩子却是怪物时。', `MaleText_loc5`='當這些父母是神。而孩子是 - 怪物的時候，這句話特別的真實。', `MaleText_loc7`='Y esto se cumple especialmente cuando los padres son dioses. Y sus hijos, monstruos.' WHERE `ID`=72135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딴건 필요 없어. 네 심장만 있으면 돼.', `MaleText_loc4`='我只需要你的心脏。', `MaleText_loc5`='我只要你的心臟而已。', `MaleText_loc7`='Solo necesito tu corazón.' WHERE `ID`=72136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='포기해. 빠르게 끝내 줄테니.', `MaleText_loc4`='投降吧，我会给你个痛快的。', `MaleText_loc5`='早早投降，我可以給你個痛快。', `MaleText_loc7`='Ríndete y me encargaré de que sea rápido.' WHERE `ID`=72137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또 다른 제물이다, 형제들이여!', `MaleText_loc4`='兄弟们，又来了一个祭品！', `MaleText_loc5`='弟兄們，又有祭品了!', `MaleText_loc7`='¡Otro sacrificio, hermanos!' WHERE `ID`=72138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피는 어떤 색깔일지 궁금하군.', `MaleText_loc4`='我就喜欢让敌人流血。', `MaleText_loc5`='我想看這傢伙血濺當場。', `MaleText_loc7`='Me encantará derramar su sangre.' WHERE `ID`=72139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 피가 고동치는 소리가 들린다.', `MaleText_loc4`='我听到你的鲜血在流淌。', `MaleText_loc5`='我聽見你血液流動的聲音。', `MaleText_loc7`='Puedo oír cómo fluye tu sangre.' WHERE `ID`=72140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나를 도와라, 야수들이여.', `MaleText_loc4`='快来帮忙，我宠物们。', `MaleText_loc5`='所有寵物，過來幫我啊。', `MaleText_loc7`='Vengan a ayudarme, mascotas mías.' WHERE `ID`=72141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저녁 시간이다!', `MaleText_loc4`='美餐送上门了！', `MaleText_loc5`='晚餐來了!', `MaleText_loc7`='Ha llegado la cena.' WHERE `ID`=72142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 동물들이 배불리 먹겠군.', `MaleText_loc4`='你将变成宠物们的美餐！', `MaleText_loc5`='我的寵物會覺得你很美味。', `MaleText_loc7`='Serás una comida eh''tupenda para mis mascotas.' WHERE `ID`=72143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽기 전에 잡아먹히는 기분을 느껴보겠나?', `MaleText_loc4`='有时他们不得不直接吞了你。', `MaleText_loc5`='只是有時候，牠們等不及你死就先開動了。', `MaleText_loc7`='A veces empiezan a comerse a la víctima antes de matah''la.' WHERE `ID`=72144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 동물들은 식성이 대단하다고, 친구들.', `MaleText_loc4`='兄弟们，我的宠物得到了一顿大餐。', `MaleText_loc5`='弟兄們，我的寵物有大餐了。', `MaleText_loc7`='Mis mascotas se darán un feh''tín.' WHERE `ID`=72145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌, 약하다.', `MaleText_loc4`='你是个弱者，朋友。', `MaleText_loc5`='朋友，你很弱啊。', `MaleText_loc7`='Eres débil, colega.' WHERE `ID`=72146;
