UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽으러 온 바보가 또 있군.', `MaleText_loc4`='又一个送死的蠢货。', `MaleText_loc5`='又有蠢蛋來送死了。', `MaleText_loc7`='$gOtro necio:Otra necia; que viene a morir.' WHERE `ID`=72148;
