UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지?! 방금 그건 뭐야?', `MaleText_loc4`='什么？！那是什么？', `MaleText_loc5`='什麼?!那是怎麼回事?', `MaleText_loc7`='¡¿Qué?! ¿Qué ha sido eso?' WHERE `ID`=72156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무도 없는 건가. 하! 멍청한 트롤들은 굴 하나도 제대로 폭파할 줄 모르는군.', `MaleText_loc4`='我什么也没看见。哈。那些愚蠢的巨魔连弄垮隧道都做不好。', `MaleText_loc5`='我什麼人也沒看到。哈，蠢蛋食人妖，連弄塌隧道都搞不定。', `MaleText_loc7`='No veo a nadie. Je. Los estúpidos trols no saben ni derrumbar un túnel como es debido.' WHERE `ID`=72157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니야... 누군가 숨어 있을 수도 있지. 사우록 노예들을 데려와라! 놈들의 냄새를 쫓아야겠다...', `MaleText_loc4`='不对……也许有人正隐藏在暗处。把蜥蜴人奴隶找来！让他们嗅出那些入侵者……', `MaleText_loc5`='不...也許有人躲了起來。叫薩烏洛克奴隸過來!藏得了一時藏不了味道...', `MaleText_loc7`='No... Tal vez alguien esté escondido. ¡Ve a buscar a los esclavos saurok! Ellos los olisquearán...' WHERE `ID`=72158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑 원령이 광폭해집니다!', `MaleText_loc4`='黑暗意志狂暴了！', `MaleText_loc5`='黑暗憎惡魔像開始狂暴了!', `MaleText_loc7`='¡El Animus oscuro se vuelve rabioso!' WHERE `ID`=72159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 주인님! 목숨 걸고 싸우겠습니다!', `MaleText_loc4`='遵命，主人！我将血战到底！', `MaleText_loc5`='是，大人!我定會拼上性命!', `MaleText_loc7`='¡Sí, maestro! ¡Lucharé hasta la muerte!' WHERE `ID`=72160;
