UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 힘과 대면하라!', `MaleText_loc4`='直面真正的力量吧！', `MaleText_loc5`='看看什麼叫做真正的力量吧!', `MaleText_loc7`='¡Contemplen el rostro del verdadero poder!' WHERE `ID`=72162;
