UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흥, 단순무식한 놈. 큰 손실은 아니야.', `MaleText_loc4`='没脑子的废物。这点损失不算什么。', `MaleText_loc5`='頭腦簡單，四肢發達。可以承受的損失。', `MaleText_loc7`='Todo músculo. Sin cerebro. Es una pérdida reemplazable.' WHERE `ID`=72170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중해라, 웨이셩. 진정한 고통을 보여줘!', `MaleText_loc4`='集中精神，魏尚。让你的敌人尝尝痛苦的滋味！', `MaleText_loc5`='專注，威勝。讓你的敵人嘗嘗痛苦!', `MaleText_loc7`='Concéntrate, Weisheng. ¡Que tu enemigo sepa lo que es el dolor!' WHERE `ID`=72171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녀석은 명예롭게 싸웠다. 그게 처음이자 마지막 실수지.', `MaleText_loc4`='他曾为荣誉而战。这是他最大的错误。', `MaleText_loc5`='他太墨守成規了。不僅大錯特錯，還賠上性命。', `MaleText_loc7`='Luchó con honor. Su primer y último error.' WHERE `ID`=72172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='칫! 쓸모 없는 잡종들! 내 직접 죽여주마!', `MaleText_loc4`='啊！没用的杂种！我要亲手杀了你们！', `MaleText_loc5`='啊啊!沒用的傢伙!我會親自殺死你們!', `MaleText_loc7`='¡Argh! ¡Perros miserables! ¡Los mataré yo mismo!' WHERE `ID`=72173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더는 못 참아! 이리 와라, 벌레들아. 상을 주마. 나 강철의 퀀과 직접 겨뤄봐라!', `MaleText_loc4`='够了！过来，爬虫。你们已经得到了奖赏。现在，你们将面对铁穹。', `MaleText_loc5`='夠了!來吧，弱者們。你們贏得獎勵了。現在准許你們與我鐵穹一戰。', `MaleText_loc7`='¡Ya basta! Vengan, debiluchos. Se han ganado su recompensa. Se enfrentarán a Qon el Tenaz.' WHERE `ID`=72174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물러서라, 이방인들아! 내 군대와 맞서기 싫다면!', `MaleText_loc4`='回头吧，陌生人！你们将面对铁穹的大军！', `MaleText_loc5`='回頭吧，陌生人們!這可是鐵穹的軍隊!', `MaleText_loc7`='¡Huyan, extraños! ¡Se enfrentan al ejército de Qon el Tenaz!' WHERE `ID`=72175;
