UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳을 폭파하면 뒤에서부터 숨어 들어갈 수 있을 겁니다. 준비가 됐으면 알려주세요.', `FemaleText_loc4`='我来解决这里的塌方，然后我们就从后面溜进去。你准备好就告诉我一声。', `FemaleText_loc5`='我會弄掉崩塌的落石，然後我們就能從後方溜進去。等你準備好了就跟我說一聲。', `FemaleText_loc7`='Destruiré esta cueva para que podamos colarnos por la parte trasera. Avísame cuando quieras empezar.' WHERE `ID`=72197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_monk_forcesphere.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:136932|h[의지의 힘]|h|r을 시전하려고 마음의 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_monk_forcesphere.blp:20|t杜鲁姆开始为自己的心灵之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:136932|h[意志之力]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_monk_forcesphere.blp:20|t獨顱目的心靈之眼開始充能，準備對|cFFFF0000$n|r施展|cFFFF0000|Hspell:136932|h[意志之力]|h|r!', `MaleText_loc7`='|TInterface/Iconsability_monk_forcesphere.blp:20|tDurumu comienza a cargar su ojo de la mente para lanzar |cFFFF0000|Hspell:136932|h[Fuerza de voluntad]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_eye_02.blp:20|t두루무가 |cFFFF0000|Hspell:133792|h[머무는 눈길]|h|r을 시전하려고 평가하는 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_eye_02.blp:20|t杜鲁姆开始为自己的权衡之眼充能，以施放|cFFFF0000|Hspell:133792|h[纠缠凝视]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_eye_02.blp:20|t獨顱目的鑑定之眼開始充能，準備施展|cFFFF0000|Hspell:133792|h[注目凝視]|h|r!', `MaleText_loc7`='|TInterface/Iconsinv_misc_eye_02.blp:20|tDurumu comienza a cargar su ojo evaluador para lanzar |cFFFF0000|Hspell:133792|h[Mirada persistente]|h|r.' WHERE `ID`=72199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_lifedrain02.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:133795|h[생명력 흡수]|h|r를 시전하려고 배고픈 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_lifedrain02.blp:20|t杜鲁姆开始为自己的饥饿之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:133795|h[生命吸取]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_lifedrain02.blp:20|t獨顱目的飢餓之眼開始充能，準備對|cFFFF0000$n|r施展|cFFFF0000|Hspell:133795|h[生命吸取]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_shadow_lifedrain02.blp:20|tDurumu comienza a cargar su ojo hambriento para lanzar |cFFFF0000|Hspell:133795|h[Drenaje de vida]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:133597|h[암흑의 기생충]|h|r을 시전하려고 사악한 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t杜鲁姆开始为自己的邪恶之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:133597|h[黑暗寄生]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t獨顱目的邪惡之眼開始充能，準備對|cFFFF0000$n|r施放|cFFFF0000|Hspell:133597|h[黑暗寄生蟲]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_shadow_curseofmannoroth.blp:20|tDurumu comienza a cargar su ojo maligno para lanzar |cFFFF0000|Hspell:133597|h[Parásito oscuro]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\priest_icon_chakra_blue.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:134122|h[청색 광선]|h|r을 시전하려고 파란 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\priest_icon_chakra_blue.blp:20|t杜鲁姆开始为自己的蓝色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134122|h[蓝光]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\priest_icon_chakra_blue.blp:20|t獨顱目的藍色魔眼開始充能，準備對|cFFFF0000$n|r發射|cFFFF0000|Hspell:134122|h[藍光射線]|h|r!', `MaleText_loc7`='|TInterfaceIconspriest_icon_chakra_blue.blp:20|tDurumu comienza a cargar su ojo azul para lanzar |cFFFF0000|Hspell:134122|h[Rayos azules]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\priest_icon_chakra_red.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:134123|h[적외선]|h|r을 시전하려고 빨간 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\priest_icon_chakra_red.blp:20|t杜鲁姆开始为自己的红色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134123|h[红光]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\priest_icon_chakra_red.blp:20|t獨顱目的紅色魔眼開始充能，準備對|cFFFF0000$n|r發射|cFFFF0000|Hspell:134123|h[紅光射線]|h|r!', `MaleText_loc7`='|TInterfaceIconspriest_icon_chakra_red.blp:20|tDurumu comienza a cargar su ojo rojo para lanzar |cFFFF0000|Hspell:134123|h[Luz infrarroja]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\priest_icon_chakra.blp:20|t두루무가 |cFFFF0000$n|r에게 |cFFFF0000|Hspell:134124|h[직사광선]|h|r을 시전하려고 노란 눈을 충전하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\priest_icon_chakra.blp:20|t杜鲁姆开始为自己的黄色之眼充能，对|cFFFF0000$n|r施放|cFFFF0000|Hspell:134124|h[强光]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\priest_icon_chakra.blp:20|t獨顱目的黃色魔眼開始充能，準備對|cFFFF0000$n|r發射|cFFFF0000|Hspell:134124|h[強光射線]|h|r!', `MaleText_loc7`='|TInterfaceIconspriest_icon_chakra.blp:20|tDurumu comienza a cargar su ojo amarillo para lanzar |cFFFF0000|Hspell:134124|h[Luz brillante]|h|r contra |cFFFF0000$n|r.' WHERE `ID`=72204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적외선에 의해 진홍빛 안개도깨비가 드러납니다!', `MaleText_loc4`='红光照出了一只猩红雾行兽！', `MaleText_loc5`='紅光射線照出了緋紅霧獸!', `MaleText_loc7`='¡La Luz infrarroja revela una niebla carmesí!' WHERE `ID`=72205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직사광선에 의해 호박색 안개도깨비가 드러납니다!', `MaleText_loc4`='强光照出了一只琥珀雾行兽！', `MaleText_loc5`='強光射線照出了琥珀霧獸!', `MaleText_loc7`='¡La Luz brillante revela una niebla ámbar!' WHERE `ID`=72206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청색 광선에 의해 하늘빛 안개도깨비가 드러납니다!', `MaleText_loc4`='蓝光照出了一只碧蓝雾行兽！', `MaleText_loc5`='藍光射線照出了蔚藍霧獸!', `MaleText_loc7`='¡Los Rayos azules revelan una niebla azur!' WHERE `ID`=72207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강렬한 광선에 의해 창백한 안개도깨비가 드러납니다!', `MaleText_loc4`='刺眼强光照出了一只苍白雾行兽！', `MaleText_loc5`='烈光射線照出了蒼白霧獸!', `MaleText_loc7`='¡La Luz abrasadora revela una niebla pálida!' WHERE `ID`=72208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠습니다. 어서 가죠.', `MaleText_loc4`='好了。我们走。', `MaleText_loc5`='好，我們走吧。', `MaleText_loc7`='De acuerdo. Vamos.', `FemaleText_loc1`='알겠습니다. 어서 가죠.', `FemaleText_loc4`='好了。我们走。', `FemaleText_loc5`='好，我們走吧。', `FemaleText_loc7`='De acuerdo. Vamos.' WHERE `ID`=72212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일 더 있습니까?', `MaleText_loc4`='又有活儿干了？', `MaleText_loc5`='還有工作要做?', `MaleText_loc7`='¿Más trabajo?' WHERE `ID`=72213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 모구의 역사를 제대로 알아야만 합니다. 적을 잘 알수록 우리 작전이 성공할 확률이 높아지니까요.', `FemaleText_loc4`='我们必须要了解魔古族的历史。知己知彼，才能百战不殆。', `FemaleText_loc5`='我們務必充分瞭解魔古的歷史，唯有知己知彼，才能提高我們的勝算。', `FemaleText_loc7`='Necesitamos comprender la historia de los mogu. Conocer a nuestro enemigo es la clave para la victoria.' WHERE `ID`=72214;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구의 역사는 야만적인 정복과 힘의 시험으로 점철되어 있습니다. 수천 년이 지난 후에는, 종족 중에 가장 강한 자만이 살아남았지요.', `FemaleText_loc4`='魔古族的历史中充斥着野蛮的征服和力量的试炼。数千年来，这个种族中只有最强者才能生存下来。', `FemaleText_loc5`='魔古的歷史寫滿了一頁頁殘酷的征服與鬥爭，如此歷經千年，只有最傑出的強者才能存活下來。', `FemaleText_loc7`='La historia de los mogu está plagada de conquistas salvajes y de pruebas de fuerza. Tras miles de años, solo los miembros más fuertes de la raza han sobrevivido.' WHERE `ID`=72215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='야수훈련소가 패배했다! 목숨을 걸고 의회를 지켜라, 형제들이여!', `MaleText_loc4`='兽神倒下了！兄弟们，誓死保卫议会！', `MaleText_loc5`='猛獸區淪陷了!兄弟們，誓死保護議會!', `MaleText_loc7`='¡La Guardia de las Bestias ha caído! ¡Defended el consejo con vueh''tras vidas, hermanos!' WHERE `ID`=72216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<이 블러드 엘프는 심하게 동요하고 있습니다.>$B$B정말이지 끔찍했어요! 우리가 잡힌 후에, 모구 하나가 제 목을 잡았습니다. 저는 그대로 죽는 줄만 알았는데, 그 모구는 주먹을 움켜쥐더니 당겼습니다. 순식간에 폐에서 공기가 빠져나가는 기분이었지요.$B$B심하게 뒤틀리고 찢어지는 아픔이 느껴졌습니다. 피부와 뼈는 불타는 듯했지요. 그러다 보니, 제가 제 몸 밖으로 빠져 나와 있더군요.$B$B모구가 제 얼굴을 보고 웃었습니다. 그때, 제 영혼이 영원히 고통받을 거라는 걸 알았지요.$B$B완전하고 순수한 공포를 느낀 적이 있으십니까, $c님? 전 있습니다.$B$B<블러드 엘프는 진저리를 치더니 조용해집니다.>', `MaleText_loc4`='<这个血精灵显然还在发抖。>$B$B太可怕了，太可怕了！我们被俘之后，一个魔古族捏着我的脖子。我以为自己死定了，可是那个魔古只是一捏然后一拉，我就觉得肺里的空气好像全被挤了出来。$B$B一阵可怕的扭曲和撕裂之痛向我袭来。我的皮肤和骨头就像火烧一样撕心裂肺。突然，我就从自己的身体里飘了出来。$B$B那个魔古对着我哈哈大笑，我就知道自己的灵魂将永远在痛苦中煎熬。$B$B你有没有品尝过纯粹的恐惧，$c？我就试过。$B$B<血精灵又颤抖了一下，便开始沉默了。>', `MaleText_loc5`='<血精靈渾身發抖。>$B$B太可怕了，太可怕了!我們被抓到以後，有個魔古抓住了我的脖子。我以為我會被一把掐死，可是，那個魔古伸手就這麼一「拉」。突然間，我肺裡的空氣好像全部被抽乾了。$B$B渾身彷彿被撕裂了，皮膚和骨頭全都燒了起來。然後，我就飄在我的身體之外了。$B$B魔古在我面前大笑，我知道我的靈魂恐怕得永永遠遠遭受折磨。$B$B你有過這種徹底而絕對的恐懼嗎，$c?我有。$B$B<血精靈打了幾個冷顫，就此沈默不語。>', `MaleText_loc7`='<El elfo de sangre está visiblemente afectado.>$B$BFue terrible, ¡sencillamente terrible! Después de que nos cazasen, un mogu me agarró del cuello. Pensé que me mataría en ese preciso instante; pero, en vez de eso, el mogu hizo un movimiento brusco: agarró y TIRÓ. Fue como si extrajera todo el aire de mis pulmones.$B$BSentí que me retorcía, que me resquebrajaba. La piel y los huesos me ardían. De pronto, me vi flotando sobre mi propio cuerpo.$B$BEl mogu se rió en mi cara, y supe que mi alma sufriría eternamente.$B$B¿Alguna vez has sentido un terror absoluto, $c? Yo sí.$B$B<El elfo de sangre se estremece y guarda silencio.>' WHERE `ID`=72217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인부가 일이 없는 인생이 무슨 의미가 있을까 생각합니다.', `MaleText_loc4`='农夫思考着如果没有工作，那生命还有什么意义。', `MaleText_loc5`='農民思索著沒有工作的人生還有什麼意義。', `MaleText_loc7`='El campesino pondera el significado de una vida sin trabajo.' WHERE `ID`=72218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 단단히 먹으시오, $c. 모구는 얌전히 무기를 내려놓지 않을 거요. 이 버림받은 섬에서는 싸우지 않고는 한 치의 땅도 차지할 수 없소.', `MaleText_loc4`='坚强点，$c。魔古族是不会轻易放下屠刀的。在这个被遗忘的岛上，我们必须为每一寸土地而奋斗。', `MaleText_loc5`='$c，要堅強。魔古不會乖乖束手就縛。我們得用武力奪回這座遺世島嶼上的每一吋土地。', `MaleText_loc7`='Mantente fuerte, $c. Los mogu no entregarán las armas pacíficamente. Tendremos que luchar por cada milímetro de tierra en esta maldita isla.' WHERE `ID`=72219;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 모구의 문화와 역사에 관심이 생겼어요. 그저 일시적인 취미보다는 더 깊다고 해 두죠.', `FemaleText_loc4`='我对魔古族的文化和历史相当感兴趣。我这可不是一时心血来潮。', `FemaleText_loc5`='我對魔古的文化與歷史越來越感興趣。這對我來說不僅是打發時間而已。', `FemaleText_loc7`='Me interesa mucho la cultura y la historia de los mogu. Se ha convertido en algo más que en una afición para mí.' WHERE `ID`=72220;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대마법사 모데라 님께서는 단순한 전략을 취하고 계세요. 모구를 힘으로 꺾는다는 전략이죠. 저는 조금만 연구를 하면 모구의 약점을 발견할 수 있을 거라 믿어요.', `FemaleText_loc4`='大法师茉德拉采用了一种直截了当的策略——武力击败魔古族。我相信随着进一步的研究，我们或许就能发现魔古族的弱点。', `FemaleText_loc5`='大法師莫德菈打算正面迎戰，以武力擊潰魔古。我認為如果能進一步研究，我們也許能發現魔古的弱點。', `FemaleText_loc7`='La archimaga Modera ha optado por una estrategia directa: derrotar a los mogu por la fuerza. Yo creo que si seguimos investigando, podemos descubrir los puntos débiles de los mogu.' WHERE `ID`=72221;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='책을 쓰기로 했어요. "모구 마법의 수수께끼"라는 책이요. 그럴싸하지 않은가요?', `FemaleText_loc4`='我决定要写一本书，就叫《魔古族魔法之谜》。听上去很厉害吧？', `FemaleText_loc5`='「我決定寫一本書。『魔古法術的奧秘』。名字聽起來不錯，對吧?」', `FemaleText_loc7`='He decidido escribir un libro: "Los misterios de la magia mogu". Suena bien, ¿verdad?' WHERE `ID`=72222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐죠?', `MaleText_loc4`='这是什么？', `MaleText_loc5`='怎麼了?', `MaleText_loc7`='¿Qué es eso?' WHERE `ID`=72223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔데요?', `MaleText_loc4`='什么？', `MaleText_loc5`='什麼?', `MaleText_loc7`='¿Qué?' WHERE `ID`=72224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인부가 할 일이 더 있었으면 좋겠다고 생각합니다.', `MaleText_loc4`='农夫希望能有更多的工作。', `MaleText_loc5`='農民希望有更多工作可做。', `MaleText_loc7`='Al campesino le gustaría que hubiese más trabajo.' WHERE `ID`=72225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 수적으로 매우 불리하지만, 빈틈없는 전략이 있으면 성공할 수 있을 거예요.', `FemaleText_loc4`='我们在这里的人数远逊于敌人，但只要切实贯彻预定的战术，我相信我们是可以成功的。', `FemaleText_loc5`='我們以寡敵眾，可是只要策略運用得當，我認為我們可以成功。', `FemaleText_loc7`='Nos superan en número ampliamente. Pero, con una estrategia bien calculada, creo que podemos vencer.' WHERE `ID`=72226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 전략은 완벽합니다. 여기서 실패하기엔 아깝죠.', `FemaleText_loc4`='我们的战术很有效。胜利的果实正在向我们招手，我们决不能在这个时候动摇。', `FemaleText_loc5`='我們的策略很穩當。現在絕不能畏縮，還有許多收穫等著我們。', `FemaleText_loc7`='Nuestra estrategia es sólida. No debemos flaquear ahora; todavía nos queda mucho por hacer.' WHERE `ID`=72227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000북동쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000东北部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000東北|r方的風口已打開，引起了|cFFFF0000|Hspell:136889|h[劇烈強風]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_nature_lightningoverload.blp:20|t Las puertas del |cFFFF0000noreste|r comienzan a abrirse, lo que provoca |cFFFF0000|Hspell:136889|h[Vendavales violentos]|h|r.' WHERE `ID`=72228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000남동쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000东南部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000東南|r方的風口已打開，引起了|cFFFF0000|Hspell:136889|h[劇烈強風]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_nature_lightningoverload.blp:20|t Las puertas del |cFFFF0000sureste|r comienzan a abrirse, lo que provoca |cFFFF0000|Hspell:136889|h[Vendavales violentos]|h|r.' WHERE `ID`=72229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000남서쪽|r 문이 열리면서 |cFFFF0000|Hspell:136889|h[맹렬한 강풍]|h|r이 몰아칩니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t|cFFFF0000西南部|r的大门敞开，引发了|cFFFF0000|Hspell:136889|h[暴乱狂风]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_lightningoverload.blp:20|t |cFFFF0000西南|r方的風口已打開，引起了|cFFFF0000|Hspell:136889|h[劇烈強風]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_nature_lightningoverload.blp:20|t Las puertas del |cFFFF0000suroeste|r comienzan a abrirse, lo que provoca |cFFFF0000|Hspell:136889|h[Vendavales violentos]|h|r.' WHERE `ID`=72230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말씀만 하세요.', `MaleText_loc4`='准备工作。', `MaleText_loc5`='準備工作。', `MaleText_loc7`='A trabajar.' WHERE `ID`=72232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘의 맛보기일 뿐이다.', `MaleText_loc4`='尝尝我的力量吧。', `MaleText_loc5`='這只是牛刀小試。', `MaleText_loc7`='Esto es solo una muestra de mi poder.' WHERE `ID`=72233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 이렇게 인부들이 주눅들어 있죠?', `MaleText_loc4`='这些农夫为什么显得这么沮丧？', `MaleText_loc5`='為什麼農民們看起來那麼消沉?', `MaleText_loc7`='¿Por qué tienen un aire triste los campesinos?', `FemaleText_loc1`='왜 이렇게 인부들이 주눅들어 있죠?', `FemaleText_loc4`='这些农夫为什么显得这么沮丧？', `FemaleText_loc5`='為什麼農民們看起來那麼消沉?', `FemaleText_loc7`='¿Por qué tienen un aire triste los campesinos?' WHERE `ID`=72234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 폭풍이 날 감싸는구나...', `MaleText_loc4`='啊，久违的风暴之拥……', `MaleText_loc5`='啊，風暴那令人熟悉的擁抱。', `MaleText_loc7`='Ah, el inolvidable abrazo de la tormenta...' WHERE `ID`=72235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='창조와... 파괴의 손길.', `MaleText_loc4`='创造……与毁灭之触。', `MaleText_loc5`='創造...與破壞的輕撫。', `MaleText_loc7`='El toque de la creación... y la destrucción.' WHERE `ID`=72236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어둠 속에서 난 수천 년을 기다렸다. 고통받는 자들의 비명만이 적막을 깨뜨리는... 깰 수 없는 악몽 속에서.', `MaleText_loc4`='我在黑暗中等待了上千年，在死寂中只有受难者的尖叫，这是一个活生生的噩梦。', `MaleText_loc5`='數萬年來我在黑暗中等待，在只會被受折磨的慘叫打破的寂靜中等待，我的夢境如場清醒的夢魘。', `MaleText_loc7`='Durante siglos he esperado en las sombras, en un silencio solo interrumpido por los gritos de los atormentados. Mis sueños eran pesadillas vivientes.' WHERE `ID`=72237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈에 순진한 희망이 어려 있구나. 고작 너희가 내 구원자라고? 가슴 속의 건방진 동정 따위는 버리고 내면의 소리를 들어라. 너희도 곧 내 고통을 알게 될 지니.', `MaleText_loc4`='我看到你们眼中天真的希望。你们……想来拯救我？丢掉那可笑的怜悯，打起精神吧，你们即将品尝我的痛苦。', `MaleText_loc5`='我在你眼中看到天真的希望。你...你以為你是來救我的?把你們心中可笑的同情轉向自己的內心吧，因為你們很快就會嘗到我的苦痛。', `MaleText_loc7`='Veo una esperanza ingenua en sus ojos. ¿Se creen... mis salvadores? Devuelvan esa ridícula piedad hacia ustedes mismos, pues pronto verán mi agonía.' WHERE `ID`=72238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 뒤틀린 세상은 구제할 수 없다. 착각에 빠진 영웅들이 손을 쓰기엔 너무 늦었지. 타락의 해법은 파괴 뿐이니, 여기서 시작되리라... 바로 지금.', `MaleText_loc4`='这扭曲的世界完了，被蒙蔽的英雄救不了它。清除堕落的唯一方法就是毁灭。就从现在……开始。', `MaleText_loc5`='這個扭曲的世界已經無法救贖，天真的英雄們也無能為力。腐化的唯一解答就是毀滅。而這...現在就會開始。', `MaleText_loc7`='Este maltrecho mundo está más allá de la redención, fuera del alcance de héroes crédulos. La única respuesta a la corrupción es la destrucción. Y eso empieza... ahora.' WHERE `ID`=72239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희를 처리하고 나면... 이 세상이 정화되기 전엔 멈추지 않겠다. 이제 소멸해라!', `MaleText_loc4`='我就先解决你们，再去净化这个世界。现在，去死吧！', `MaleText_loc5`='解決你們之後，我不會休息，直到這個世界被淨化。現在，死吧!', `MaleText_loc7`='Cuando termine con ustedes, no descansaré hasta haber purificado el mundo. ¡Mueran!' WHERE `ID`=72240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 생명이 널 배신할 것이다.', `MaleText_loc4`='感受灵魂的背叛吧。', `MaleText_loc5`='感受你們自己生命精華的背叛。', `MaleText_loc7`='Sientan cómo su propia esencia vital los traiciona.' WHERE `ID`=72241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='운명을 받아들여라.', `MaleText_loc4`='顺应天命吧。', `MaleText_loc5`='接受必然的命運。', `MaleText_loc7`='Acepta lo inevitable.' WHERE `ID`=72242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀엽군. 나를 이길 생각을 했다니.', `MaleText_loc4`='有意思。你们真以为自己能赢。', `MaleText_loc5`='真有趣。你真的以為有機會贏。', `MaleText_loc7`='Qué divertido. Realmente creíste que podías ganar.' WHERE `ID`=72243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직도 승리할 수 있을 것 같나? 하하하, 어리석군!', `MaleText_loc4`='你们觉得还有胜利的希望？愚蠢！', `MaleText_loc5`='你們還以為有可能獲勝?一幫蠢才!', `MaleText_loc7`='¿Aún piensan que la victoria es posible? ¡Idiotas!' WHERE `ID`=72244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 이 세상 최고의 실력자들인가? 하하, 왜 이 꼴이 됐는지 알 것 같군.', `MaleText_loc4`='你们已经算是这个世界的精英了吗？哈，难怪它会沦为废墟。', `MaleText_loc5`='你們就是這個世界的最強者?哈，難怪它一副快毀滅的樣子。', `MaleText_loc7`='¿Son lo mejor que puede ofrecer este mundo? Ja, no me extraña que esté condenado.' WHERE `ID`=72245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 난... 난 적이 아니다. 너희는 예전의 그보다도 강하구나. 어쩌면 너희가 옳을지도 모른다, 정말 희망이 있을지도.', `MaleText_loc4`='等等！我……我不是你们的敌人。你们很强。甚至，比他更强……或许你们是对的。或许还有希望。', `MaleText_loc5`='慢著!我不是你們的敵人。你們很強大。甚至比他當時還強大...也許你們是對的。也許還有希望。', `MaleText_loc7`='¡Esperen! No soy... no soy su enemigo. Son poderosos. Incluso más que él... Tal vez tengan razón. Tal vez aún haya esperanza.' WHERE `ID`=72246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일이 없어서 주눅들어 있다고요?', `MaleText_loc4`='他们在为没有工作而沮丧？', `MaleText_loc5`='他們消沉的原因是因為沒有工作可做?', `MaleText_loc7`='¿Están deprimidos porque no tienen trabajo?', `FemaleText_loc1`='일이 없어서 주눅들어 있다고요?', `FemaleText_loc4`='他们在为没有工作而沮丧？', `FemaleText_loc5`='他們消沉的原因是因為沒有工作可做?', `FemaleText_loc7`='¿Están deprimidos porque no tienen trabajo?' WHERE `ID`=72247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옙.', `MaleText_loc4`='没错。', `MaleText_loc5`='馬上馬上。', `MaleText_loc7`='De acuerdo.' WHERE `ID`=72248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요.', `MaleText_loc4`='你好。', `MaleText_loc5`='哈囉。', `MaleText_loc7`='Hola.' WHERE `ID`=72249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 필멸자여, 지금 모든 것을 삼키는 어둠의 균열이 너희 발 밑에서 아귀를 벌리기 시작했다. 너희가 파멸의 순리를 거스를 순 없을 것이다.', `MaleText_loc4`='可你们脚下就是黑暗的深渊，凡人。巨大的，无止尽的，吞噬一切的深渊。我不信你们能改变毁灭的结局。', `MaleText_loc5`='但是你們下方還有一道黑暗的裂口，凡人們。巨大、無邊無盡、吞噬一切。我不相信你們能阻止這場必然的毀滅。', `MaleText_loc7`='Pero hay un profundo abismo de oscuridad debajo de ustedes, mortales. Vasto e interminable que lo consume todo. No creo que puedan corregir su rumbo condenado.' WHERE `ID`=72250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 적어도 도전할 권리는 얻어냈구나. 이제 작별이다.', `MaleText_loc4`='可……你们赢得了尝试的权利。再见。', `MaleText_loc5`='但...你們贏得了嘗試的機會。再見了。', `MaleText_loc7`='Pero se han ganado el derecho a intentarlo. Adiós.' WHERE `ID`=72251;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공성전이 진행 중인데 폭탄을 성벽까지 나를 수가 없어요!', `FemaleText_loc4`='攻势已经发动，但重磅炸药还没有到位！', `FemaleText_loc5`='攻擊已經開始，但我們的強力炸藥一直無法運到牆邊!', `FemaleText_loc7`='El asedio ha comenzado, pero nuestros explosivos no llegaron a la muralla.' WHERE `ID`=72252;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제가 지원군을 규합하는 동안 폭탄을 모아 성벽으로 가져가세요.', `FemaleText_loc4`='在我召集援军时收集炸药，运到城墙下面。', `FemaleText_loc5`='趁我集結援軍時，收集炸藥帶到城牆這邊來。', `FemaleText_loc7`='Reúne los explosivos y llévalos a la muralla mientras reúno refuerzos.' WHERE `ID`=72253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warrior_throwdown:20|t%s|1이;가; $n|1을;를; 붙잡고 |cFFFF0000|Hspell:137175|h[천둥 던지기]|h|r를 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warrior_throwdown:20|t%s抓住了$n并准备施放|cFFFF0000|Hspell:137175|h[雷霆投掷]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warrior_throwdown:20|t%s抓住了$n而且準備施展他的|cFFFF0000|Hspell:137175|h[雷霆投擲]|h|r!', `MaleText_loc7`='|TInterface/Iconsability_warrior_throwdown:20|t%s agarra a $n y prepara su |cFFFF0000|Hspell:137175|h[Lanzamiento atronador]|h|r.' WHERE `ID`=72254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shaman_thunderstorm:20|t%s|1이;가; 강렬한 |cFFFF0000|Hspell:137313|h[번개 폭풍]|h|r을 집중하기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shaman_thunderstorm:20|t%s开始引导一场剧烈的|cFFFF0000|Hspell:137313|h[闪电风暴]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shaman_thunderstorm:20|t%s開始引導一個強力的|cFFFF0000|Hspell:137313|h[閃電風暴]|h|r!', `MaleText_loc7`='|TInterface/Iconsspell_shaman_thunderstorm:20|t%s comienza a canalizar una intensa |cFFFF0000|Hspell:137313|h[Tormenta de relámpagos]|h|r.' WHERE `ID`=72255;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 죽으며 주위의 아군에게 휘어진 번개를 전달합니다!', `MaleText_loc4`='%s死亡并向附近一名盟友发射弧形闪电！', `MaleText_loc5`='%s死了，朝附近的一名盟友發出弧光閃電!', `MaleText_loc7`='%s muere, y le lanza Arco de relámpagos a un aliado cercano.', `FemaleText_loc1`='%s|1이;가; 죽으며 주위의 아군에게 휘어진 번개를 전달합니다!', `FemaleText_loc4`='%s死亡并向附近一名盟友发射弧形闪电！', `FemaleText_loc5`='%s死了，朝附近的一名盟友發出弧光閃電!', `FemaleText_loc7`='%s muere, y le lanza Arco de relámpagos a un aliado cercano.' WHERE `ID`=72256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 이갈룩 바위산으로 가세요. 그곳에 도착하면 환영 마법을 완성해 드리지요.', `MaleText_loc4`='现在，去伊瓜鲁克峭壁。等你一到那里，我就给你施加另一半幻术。', `MaleText_loc5`='出發吧，前往伊加路克峭壁。我會在你抵達的時候，為你施放後續的幻象法術。', `MaleText_loc7`='Ahora ve al Risco Ihgaluk. Aplicaré la segunda mitad de tu ilusión cuando llegues.', `FemaleText_loc1`='이제 이갈룩 바위산으로 가세요. 그곳에 도착하면 환영 마법을 완성해 드리지요.', `FemaleText_loc4`='现在，去伊瓜鲁克峭壁。等你一到那里，我就给你施加另一半幻术。', `FemaleText_loc5`='出發吧，前往伊加路克峭壁。我會在你抵達的時候，為你施放後續的幻象法術。', `FemaleText_loc7`='Ahora ve al Risco Ihgaluk. Aplicaré la segunda mitad de tu ilusión cuando llegues.' WHERE `ID`=72257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신을 추적합니다!', `MaleText_loc4`='%s正在追踪你！', `MaleText_loc5`='%s正在追著你!', `MaleText_loc7`='¡%s te persigue!' WHERE `ID`=72258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFFF00000|Hspell:136192|h[번개 폭풍]|h|r에 휩싸입니다!', `MaleText_loc4`='$n受到了|cFFF00000|Hspell:136192|h[闪电风暴]|h|r的影响！', `MaleText_loc5`='$n受到了|cFFF00000|Hspell:136192|h[閃電風暴]|h|r的影響!', `MaleText_loc7`='¡|cFFF00000|Hspell:136192|h[Tormenta de relámpagos]|h|r afecta a $n!', `FemaleText_loc1`='$n|1이;가; |cFFF00000|Hspell:136192|h[번개 폭풍]|h|r에 휩싸입니다!', `FemaleText_loc4`='$n受到了|cFFF00000|Hspell:136192|h[闪电风暴]|h|r的影响！', `FemaleText_loc5`='$n受到了|cFFF00000|Hspell:136192|h[閃電風暴]|h|r的影響!', `FemaleText_loc7`='¡|cFFF00000|Hspell:136192|h[Tormenta de relámpagos]|h|r afecta a $n!' WHERE `ID`=72259;
