UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이미 멸종된 생태계를 어떻게 알 수 있겠어요? 식물조차도 독성을 띠고 있다고요!', `FemaleText_loc4`='我们该怎么了解一个已经绝种的生态系统呢？连这里的植物都是有毒的！', `FemaleText_loc5`='我們怎麼可能對滅絕的生態系統有什麼認識?就連植物都是有毒的!', `FemaleText_loc7`='¿Cómo vamos a saber algo de un ecosistema extinto? ¡Hasta las plantas son venenosas!' WHERE `ID`=72287;
