UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이유는 모르겠는데 이 지팡이를 계속 쳐다보게 되네요. 흠...', `MaleText_loc4`='由于某些奇怪的原因，我很喜欢盯着这根手杖看。唔……', `MaleText_loc5`='不知道為什麼，我喜歡盯著這個拐杖看。嗯...', `MaleText_loc7`='Por algún motivo, me encanta mirar este bastón. Mmm...' WHERE `ID`=72290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리에게 필요한 건 공룡의 개체 수를 제한할 수 있는 단백질 유전자 조작법이에요. 여기 오기 이전에 준비해왔으면 더 좋았겠지만요.', `MaleText_loc4`='我们需要某种蛋白质的种群控制药物。或许我们应该在来这里之前就考虑好这个问题。', `MaleText_loc5`='我們需要的是某種基於蛋白質素材的人口控制方式。也許我們在來這裡之前就該想到這點了。', `MaleText_loc7`='Lo que necesitamos es algún tipo de control de la población basado en proteínas. Tal vez deberíamos haberlo pensado antes de venir.' WHERE `ID`=72291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 이 원정대가 실패할 수 있죠? 제가 여기에 얼마나 많은 돈을 투자했는데!', `MaleText_loc4`='探险队怎么会失败呢？我可是下了大本钱的！', `MaleText_loc5`='探險行動怎麼可能會失敗?我不惜血本耶!', `MaleText_loc7`='¿Cómo ha podido fallar la expedición? ¡No reparé en gastos!' WHERE `ID`=72292;
