UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 어, 저거 들리시는 분 계십니까? 음, 그러니까, 뭔가 쿵쿵거리는 소리 같군요.', `MaleText_loc4`='有人，呃，听到了吗？那个，那个，那个震动。', `MaleText_loc5`='有人，呃，聽到嗎?那是，嗯...那是...撞擊的震動。', `MaleText_loc7`='¿Habéis, eh, oído eso? Es, eh, el temblor de un impacto.' WHERE `ID`=72294;
