UPDATE `locales_broadcast_text` SET `MaleText_loc1`='햄록에게 즐거운 주말을 보내게 해줘서 고맙다는 인사를 해야겠군요.', `MaleText_loc4`='记得提醒我谢谢汉姆洛克，他让我度过了一个愉快的周末。', `MaleText_loc5`='提醒我感謝漢洛克，給了我這麼一個美好的周末。', `MaleText_loc7`='Recuérdame que le agradezca a Baladrel el maravilloso fin de semana.' WHERE `ID`=72296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건, 어, 삶의 순환이죠, 네. 빛이 트롤을 만들고, 트롤이 공룡을 만들고, 공룡이 인간을 먹어치우고, 트롤이 아제로스를 지배하고.', `MaleText_loc4`='这是，呃，生命的轮回，唔。圣光创造了巨魔，巨魔创造了恐龙，恐龙吃人类，巨魔继承艾泽拉斯。', `MaleText_loc5`='這是，嗯，生命的循環，對。聖光創造了食人妖，食人妖創造了恐龍，恐龍吃人類，食人妖繼承艾澤拉斯。', `MaleText_loc7`='Es, eh, el ciclo de la vida. La Luz crea a los trols, los trols crean a los dinosaurios, los dinosaurios se comen a los humanos, y los trols heredan Azeroth.' WHERE `ID`=72297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 생각에 이것도, 음, 그 관광 요소에 포함될 것 같나요?', `MaleText_loc4`='你说他们会在，呃，旅途中带上这个吗？嗯？', `MaleText_loc5`='你覺得他們會把這個加入，嗯，巡迴展出的項目裡嗎?嗯?', `MaleText_loc7`='¿Crees que lo tendrán en el, eh, plan? ¿Mm?' WHERE `ID`=72298;
