UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저기, 지금 저 혼자 말하고 있나요? 그렇다고요? 봐요, 내가 또 맞았지.', `MaleText_loc4`='我是不是，唔，在自言自语？是吗？你看，我又说中了。', `MaleText_loc5`='我在，嗯，自言自語嗎?我是嗎?你看，我又說對了。', `MaleText_loc7`='¿Estoy, eh, hablando solo? ¿Sí? Ves, vuelvo a tener razón.' WHERE `ID`=72300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서로 엄호하라! 위치를 사수하라!', `MaleText_loc4`='互相掩护！坚守阵地！', `MaleText_loc5`='互相掩護!絕不後退!', `MaleText_loc7`='¡Cúbranse mutuamente! ¡No cedan terreno!' WHERE `ID`=72301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 진짜 나다. 서류와 정치를 떠나, 마법과 검의 뜨거운 분노를 보여주마!', `MaleText_loc4`='这才像我。丢掉文件，抛开政治——只有魔法与钢铁的炽烈怒火！', `MaleText_loc5`='這才是真正的我。沒有公文，沒有政治 - 純粹展現魔法與武器的憤怒!', `MaleText_loc7`='¡Esta es mi vida! No el papeleo ni la política. ¡Solo la furia ardiente de la magia y el acero!' WHERE `ID`=72302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀어 붙여라! 우린 오늘 운명을 새로 쓴다!', `MaleText_loc4`='前进！今天，我们将决定自己的命运！', `MaleText_loc5`='往前推進!我們今天要掌握自己的命運!', `MaleText_loc7`='¡Avancen! ¡Hoy construiremos nuestro destino!' WHERE `ID`=72303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 호드다. 포기 따위는 모른다.', `MaleText_loc4`='我们是部落。我们绝不后退。', `MaleText_loc5`='我們是部落。我們絕不會退縮。', `MaleText_loc7`='Somos la Horda. No nos rendimos.' WHERE `ID`=72304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 없애 버려. 우리 힘을 보여줘!', `MaleText_loc4`='消灭他们。让他们看看我们的力量！', `MaleText_loc5`='砍翻他們。展現我們的力量!', `MaleText_loc7`='Acaben con ellos. ¡Demuéstrenles nuestra fuerza!' WHERE `ID`=72305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 파괴해라, 형제여!', `MaleText_loc4`='兄弟们，消灭他们！', `MaleText_loc5`='摧毀他們，兄弟們!', `MaleText_loc7`='¡Destrúyanlos, hermanos!' WHERE `ID`=72306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 힘을 더해 주신다!', `MaleText_loc4`='万灵赐予你们力量！', `MaleText_loc5`='靈魂會給我們力量!', `MaleText_loc7`='¡Los espíritus nos dan fuerza!' WHERE `ID`=72307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 베어라! 신들께서 그 피를 들이키신다!', `MaleText_loc4`='剐了他们！众神将畅饮他们的鲜血！', `MaleText_loc5`='撕開他們的肉體!我們的神會暢飲他們的鮮血!', `MaleText_loc7`='¡Destrípalos! ¡Nuestros dioses se beberán su sangre!' WHERE `ID`=72308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='박살내라! 피를 보여!', `MaleText_loc4`='碾碎他们！撕裂他们！', `MaleText_loc5`='碾碎他們!讓他們流血!', `MaleText_loc7`='¡Aplástenlos! ¡Desángrenlos!' WHERE `ID`=72309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부숴 버려!', `MaleText_loc4`='干掉他们！', `MaleText_loc5`='殺死他們!', `MaleText_loc7`='¡Quiébrenlos!' WHERE `ID`=72310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕! 실로 대단한 자로군.', `MaleText_loc4`='雷电之王！多么强大的存在！', `MaleText_loc5`='雷王!真是有趣的傢伙。', `MaleText_loc7`='¡El Rey del Trueno! Qué individuo tan magnífico.' WHERE `ID`=72311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌이 그의 제국을 전복시키고 이 땅을 숨기지 않았다면 지금 어떻게 되었을지 상상이 되느냐?', `MaleText_loc4`='要不是被熊猫人推翻并掩盖起来，他的帝国到今天会变成什么样子呢？', `MaleText_loc5`='你能想像如果熊貓人沒有推翻他的帝國然後把它藏起來，今天會成長到什麼地步嗎?', `MaleText_loc7`='¿Te imaginas cómo sería su imperio hoy en día si los pandaren no lo hubieran derrocado y ocultado?' WHERE `ID`=72312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈보다 더한 폭군은 상상이 안 돼요. 한 대륙의 모두를 노예로 만들다니...', `MaleText_loc4`='我想不出比他更残暴的君主了。他奴役了整个大陆。', `MaleText_loc5`='我無法想像比他更殘酷的暴君。他奴役了整塊大陸的人。', `MaleText_loc7`='No puedo imaginar un tirano más cruel. Esclavizó a todo el continente.' WHERE `ID`=72313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강한 자에게 자비란 사치지, 젊은 왕자여. 위대한 제국이 온정으로 이룩된 적은 없었다.', `MaleText_loc4`='对强者而言，仁慈是种奢望。没有哪个伟大的帝国是靠仁慈建立的。', `MaleText_loc5`='慈悲是強者才能給予的恩典，年輕的王子。但是慈悲卻成就不了宏大的帝國。', `MaleText_loc7`='La benevolencia es un lujo para los fuertes, joven príncipe. Nunca se construyó un imperio con amabilidad.' WHERE `ID`=72314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 그건... 글쎄요. 하지만 그 어떤 나라도 자신의 백성을 짓밟고 오래가진 못했습니다.', `MaleText_loc4`='……我不知道。但我得说：没有哪个压榨人民的“伟大帝国”能经得起时间的考验。', `MaleText_loc5`='...我可不敢這麼說。但是我可以告訴你: 若只是一昧壓榨子民，再宏大的帝國也度不過時間的考驗。', `MaleText_loc7`='Yo no estoy tan seguro, pero lo que sí sé es que ningún imperio ha perdurado a costa de oprimir a sus propios ciudadanos.' WHERE `ID`=72315;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 백성들의 혁명으로 무너졌어요! 그게 천둥왕의 교훈입니다. 그나저나 당신 차례군요.', `MaleText_loc4`='记住，魔古族被推翻了！雷电之王应该吸取教训。现在轮到你了。', `MaleText_loc5`='別忘了，魔古被推翻了!那就是雷王給我們的教訓。對了，輪到你了。', `MaleText_loc7`='¡Recuerda que los mogu fueron derrocados! Eso es lo que olvida el Rey del Trueno. Te toca tirar, por cierto.' WHERE `ID`=72316;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일국의 왕관을 쓰기에 네가 너무 무른 것은 아닌지 걱정이구나. 너희 아버지의 드센 면을 좀 배우는 게 좋겠다.', `MaleText_loc4`='我很担心你太过软弱，不足以接过那个王冠，安度因王子。你该好好学学你父亲的强硬。', `MaleText_loc5`='我擔心你的軟弱還不足成為一個王國的繼承人，安杜因王子。你最好還是學一下你父親的魄力。', `MaleText_loc7`='Me preocupa que seas demasiado blando para llevar la corona de tu reino, príncipe Anduin. No te caería mal aprender de la frialdad de tu padre.' WHERE `ID`=72317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 설교하시는 겁니까? 두 살 주제에?', `MaleText_loc4`='你是在对我说教吗？你才多大——两岁？', `MaleText_loc5`='你在對我說教嗎?你才多大，兩歲?', `MaleText_loc7`='¿Me estás sermoneando? Si solo tienes... dos años.' WHERE `ID`=72318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용의 나이로 두 살이다. 네 차례구나.', `MaleText_loc4`='龙族的两岁。该你了。', `MaleText_loc5`='是「龍族」的兩歲。該你了。', `MaleText_loc7`='Dos años de dragón. Tu turno.' WHERE `ID`=72319;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흐음...', `MaleText_loc4`='唔……', `MaleText_loc5`='嗯...', `MaleText_loc7`='Mmm.' WHERE `ID`=72320;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 방금 왜 그 말을 옮긴 거지?', `MaleText_loc4`='……你怎么还在玩那个东西？', `MaleText_loc5`='...你為何要下這一著?', `MaleText_loc7`='¿Por qué moviste esa pieza?' WHERE `ID`=72321;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 판다렌식 놀이잖아요. 우리가 둘 다 이기는 게 목표라고요.', `MaleText_loc4`='这是一种熊猫人的棋盘游戏。目标是双赢。', `MaleText_loc5`='我們在下的可是熊貓人棋，棋局的規則就是雙方同時勝利。', `MaleText_loc7`='Es un juego de mesa pandaren. El objetivo es que ganen ambos jugadores.' WHERE `ID`=72322;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이가 없구나! 그럴 거면 이걸 뭐하러 하지?', `MaleText_loc4`='简直荒唐！那有什么好玩的！？', `MaleText_loc5`='太莫名其妙了!你怎麼會想下這種棋!?', `MaleText_loc7`='¡Eso es ridículo! ¿Entonces para qué jugar?' WHERE `ID`=72323;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 이제 천둥의 섬으로 돌아가라. 그곳의 제련소에서 만나서 함께 전설적인 힘을 지닌 도구를 만들어 보자꾸나.', `MaleText_loc4`='勇士，我们现在快回雷神岛去吧。我在熔炉那里等你，我们将共同制作一件传奇武器。', `MaleText_loc5`='勇士，回到雷王島吧。我會在熔爐跟你碰面，我們會在那裡一起製造一個有傳奇力量的工具。', `MaleText_loc7`='Ahora debes volver a la Isla del Rey del Trueno. Te veré en la forja, donde juntos crearemos un instrumento de poder legendario.' WHERE `ID`=72324;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어째서요? 두 분이 원하는 건 대체 뭡니까?', `MaleText_loc4`='为什么？你们俩有什么目的？', `MaleText_loc5`='為了什麼目的?你們兩個的目標是什麼?', `MaleText_loc7`='¿Con qué fin? ¿Qué quieren lograr ustedes dos?' WHERE `ID`=72325;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 세계 평화지!', `MaleText_loc4`='……为了世界和平！', `MaleText_loc5`='...世界和平!', `MaleText_loc7`='¡La paz mundial!' WHERE `ID`=72326;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알지도 못하는 모구 무기 제련소를 이용해서요?', `MaleText_loc4`='就靠一座你们根本不了解的魔古武器熔炉？', `MaleText_loc5`='用一個你們幾乎不了解來歷作用的魔古熔爐?', `MaleText_loc7`='¿Mediante una forja de armas mogu cuyos poderes apenas comprenden?' WHERE `ID`=72327;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자여, 너와 나의 목표는 같다. 행함의 크기가 다를 뿐.', `MaleText_loc4`='我亲爱的王子，我们的目标是一致的，只是投入程度不同。', `MaleText_loc5`='親愛的王子，我們的目標一致。我們僅僅在投入的程度上有所不同。', `MaleText_loc7`='Mi querido príncipe, nuestro objetivo es el mismo. Solo difiere nuestro grado de compromiso.' WHERE `ID`=72328;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가자, 영웅이여! 함께 새로운 아제로스를 만들어 보자!', `MaleText_loc4`='来吧，英雄！我们将打造全新的艾泽拉斯！', `MaleText_loc5`='來吧，英雄!讓我們一起塑造全新的艾澤拉斯!', `MaleText_loc7`='¡Ven! ¡Juntos forjaremos un nuevo Azeroth!' WHERE `ID`=72329;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이시여, 우리는 서로 적이지만, 힘을 쫓아 이 검은용을 무턱대고 따른다면 당신도 대족장과 다를 바 있겠습니까? 부탁이니 신중하십시오.', `MaleText_loc4`='勇士，我知道我们正在交战，可如果你盲目信任这头追逐力量的黑龙，那你又能比你的酋长强多少呢？请你三思。', `MaleText_loc5`='勇士，我知道我們雙方正在交戰，但如果你盲目信任這隻黑龍追求力量，不就跟你的大酋長一樣糟糕嗎?請你盡量...小心行事。', `MaleText_loc7`='Sé que nuestros pueblos están en guerra, pero si confías ciegamente en este dragón negro y en su ansia de poder, ¿acaso eres mejor que tu Jefe de Guerra? Por favor, ten cuidado.' WHERE `ID`=72330;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 힘을 쫓아 이 검은용을 무턱대고 따른다면, 우리가 가로쉬 헬스크림과 다를 바 있겠습니까? 부탁이니 신중하십시오.', `MaleText_loc4`='我的朋友，如果你盲目信任这头追逐力量的黑龙，那你又能比加尔鲁什强多少呢？请你三思。', `MaleText_loc5`='我的朋友，如果你盲目地信任一頭黑龍追求強大的力量，你和卡爾洛斯·地獄吼不就一樣糟糕嗎?請你盡量...小心行事。', `MaleText_loc7`='Te lo digo como amigo: si confías ciegamente en un dragón negro y en su ansia de poder, ¿acaso eres mejor que Garrosh Grito Infernal? Por favor, ten cuidado.' WHERE `ID`=72331;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통, 우리 친구인가?', `MaleText_loc4`='童福，有朋友来了？', `MaleText_loc5`='老童，是我們那位朋友嗎?', `MaleText_loc7`='Tong, ¿tengo una visita? ¡Dile que suba!' WHERE `ID`=72332;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아 계시다니 믿기지가 않군요.', `MaleText_loc4`='难以置信，你居然还活着。', `MaleText_loc5`='我不敢相信你還活著。', `MaleText_loc7`='No puedo creer que sigas con vida.' WHERE `ID`=72333;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 혹시 이 친구와 함께 라벤홀트에서 어떤 활약을 했는지 말한 적이 있던가? 좋은 시절이었지!', `MaleText_loc4`='记得提醒我以后告诉你我们在拉文霍德庄园的事迹。那可真是一段好时光！', `MaleText_loc5`='我應該告訴你的，當初我和這位朋友在拉文霍德轟轟烈烈的幹了一場。真懷念啊!', `MaleText_loc7`='Recuérdame que te cuente la historia de todo lo que conseguimos en Ravenholdt. ¡Qué tiempos aquellos!' WHERE `ID`=72334;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 뭐라 했더냐? 이런 용기와 끈기를 지닌 필멸자는 거의 없다.', `MaleText_loc4`='我怎么说的来着？如此勇敢而坚毅的凡人实属罕见。', `MaleText_loc5`='我是怎麼跟你說的?很少有凡人有他這樣的勇氣和韌性。', `MaleText_loc7`='¿Qué les dije? Hay pocos mortales con tanto valor y tenacidad.' WHERE `ID`=72335;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지난번처럼 석공의 우둔함으로 오거라!', `MaleText_loc4`='老规矩，到石匠之愚上来见我！', `MaleText_loc5`='在我們之前去過的巧匠之愚上面跟我碰面!', `MaleText_loc7`='Nos vemos en la Locura del Albañil. Donde nos reunimos antes.' WHERE `ID`=72336;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='둘이 무슨 꿍꿍이죠?', `MaleText_loc4`='你们有什么阴谋？', `MaleText_loc5`='你們在搞什麼花樣?', `MaleText_loc7`='¿Qué se traen entre manos?' WHERE `ID`=72337;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 숨기는 것이 없다! 안두인 린, 함께 와도 좋다. 몸이 허락한다면.', `MaleText_loc4`='我向来坦荡！如果伤势允许，你可以一起来，安度因·乌瑞恩。', `MaleText_loc5`='我很光明磊落!如果你的傷勢沒問題的話，歡迎你跟我們一起來，安杜因·烏瑞恩。', `MaleText_loc7`='¡Yo no tengo secretos! Puedes acompañarnos, Anduin Wrynn, si tu herida lo permite.' WHERE `ID`=72338;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호드 친구에게 너를 밀어버리지 말라고 당부해야겠구나.', `MaleText_loc4`='但我得请求我的部落朋友别把你推下悬崖。', `MaleText_loc5`='我會求這位部落的朋友別把你推下懸崖。', `MaleText_loc7`='Le rogaré a mi camarada de la Horda que no te empuje al vacío.' WHERE `ID`=72339;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장관이로구나! 왕자, 이런 경관을 본 적이 있는가?', `MaleText_loc4`='真壮观！你见过这样的景色吗，安度因王子？', `MaleText_loc5`='真是壯觀!你有見過這樣的景色嗎，安杜因王子?', `MaleText_loc7`='¡Qué esplendor! ¿Alguna vez habías visto un paisaje comparable, príncipe Anduin?' WHERE `ID`=72340;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨 막히게 아름답군요.', `MaleText_loc4`='真是震撼人心。', `MaleText_loc5`='相當雄偉。', `MaleText_loc7`='Es imponente.' WHERE `ID`=72341;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 더욱 기가 막힌 걸 보게 될 것이다.', `MaleText_loc4`='它甚至令人心生敬畏。', `MaleText_loc5`='接下來還會更令人讚嘆。', `MaleText_loc7`='Está a punto de serlo aún más.' WHERE `ID`=72342;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 용사여! 네 노력의 결실을 보아라!', `MaleText_loc4`='勇士！看看你的劳动成果吧！', `MaleText_loc5`='勇士!看好你努力的成果!', `MaleText_loc7`='¡Contempla el fruto de tu trabajo!' WHERE `ID`=72343;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상의 여명기, 필멸의 종족들이 아직 어렸던 그때, 그들은 불의 비밀을 알지 못했다.', `MaleText_loc4`='在世界破晓之初，凡人种族还很年轻，他们尚未掌握火的秘密。', `MaleText_loc5`='在世界黎明之初，當凡人種族還很年輕時，他們並不知道火焰的秘密。', `MaleText_loc7`='En el albor del mundo, cuando las razas mortales eran jóvenes, no conocían el secreto del fuego.' WHERE `ID`=72344;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들이 추위와 비로 떨고 있을 때, 번개가 한 순간 번쩍하고 하늘을 갈랐지!', `MaleText_loc4`='他们在凄风冷雨中颤栗，突然——闪电撕裂了天空！', `MaleText_loc5`='他們在冬天和雨天中顫抖，直到有天 - 閃電劃破了天空!', `MaleText_loc7`='Temblaban de frío, bajo la lluvia, hasta que en un instante... ¡el rayo rasgó el cielo!' WHERE `ID`=72345;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개를 맞은 나무는 활활 타올랐다.', `MaleText_loc4`='它劈倒了一棵树并将它点燃。', `MaleText_loc5`='它劈開了一棵樹，使它燃燒起來。', `MaleText_loc7`='Derribó un árbol y le prendió fuego.' WHERE `ID`=72346;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='필멸자들은 경외하며 불 주위에 모여 들었지. 불은 음식을 익혀 주고 보금자리를 덥혀 주었다. 그들은 불씨를 수습해서 보호했지!', `MaleText_loc4`='凡人敬畏而惊奇地聚拢到火堆周围，用它烹煮、取暖。他们获取了它！小心呵护！', `MaleText_loc5`='凡人們在敬畏及驚奇中聚在火焰旁邊。它可以煮熟他們的食物，使他們的家居溫暖。他們取得了火焰!並保護它!', `MaleText_loc7`='Los mortales se reunieron alrededor del fuego, fascinados. Podían cocinar su comida y calentar sus casas. ¡Lo tomaron! ¡Y lo protegieron!' WHERE `ID`=72347;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들은 쉴 새 없이 땔감으로 불을 살렸다. 그리고 이웃의 터전으로 불씨를 날랐지. 알겠느냐? 번갯불 하나로 인해 문명이 탄생한 것이다.', `MaleText_loc4`='火焰日以继夜地燃烧。红热的炭火在营地间传递。你明白了吗？只是一道闪电，文明由此诞生。', `MaleText_loc5`='火焰每天的每個小時都受到餵食。煤塊從一個原始聚落送到另一個聚落。看到了嗎?在一剎那的光芒中，文明就誕生了。', `MaleText_loc7`='El fuego se alimentaba cada hora, cada día. Las brasas se llevaban de un campamento primitivo a otro. ¿Lo entiendes? De un solo relámpago surgió la civilización.' WHERE `ID`=72348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개는 실로 신들의 선물이다.', `MaleText_loc4`='闪电无疑是诸神赐下的礼物。', `MaleText_loc5`='是的，閃電是諸神的禮物。', `MaleText_loc7`='El rayo, es un verdadero regalo de los dioses.' WHERE `ID`=72349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구, 아, 모구여! 그들은 너무나 소견이 좁았다! 주인을 섬기기 위해 빚어진 그들은, 주인을 잃자 스스로를 섬겼다.', `MaleText_loc4`='魔古族，啊！魔古族！这些蠢货天生就是下人！当失去了主人，他们就转而侍奉自己。', `MaleText_loc5`='魔古啊，魔古!他們的眼界太小了!他們為了服侍而生，在失去主人之後，他們只為自己而生。', `MaleText_loc7`='¡Ah, los mogu! Sus mentes son tan pequeñas... Los construyeron para servir, y cuando perdieron a sus amos, se sirvieron a sí mismos.' WHERE `ID`=72350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 더욱더 크게 될 수도 있었을 터.', `MaleText_loc4`='可他们原本可以更加伟大。', `MaleText_loc5`='他們原本能做更多偉大的事情。', `MaleText_loc7`='Pero podrían haber llegado más lejos.' WHERE `ID`=72351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새 세상을 건설할 수도 있었던 힘으로 그저 제국을 건설한 것이다.', `MaleText_loc4`='他们本可以创造新世界，然而只建立起一个帝国。', `MaleText_loc5`='他們明明有能耐創建新世界，但卻只建立了一個帝國。', `MaleText_loc7`='Construyeron un imperio cuando podían haber construido un mundo.' WHERE `ID`=72352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 그러지 않을 것이다. 용사여, 보아라! 천공의 정점이다! 내 선물이다.', `MaleText_loc4`='我们能做得更好。看！苍穹之冠！这是我的礼物。', `MaleText_loc5`='我們一定能做得更好，勇士。看好了:天堂之冠，是我的贈禮。', `MaleText_loc7`='Nosotros los superaremos. ¡Contempla! La corona del cielo. Para ti, de mi parte.' WHERE `ID`=72353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 태초의 불씨이며, 태초의 불똥이다! 너는 온 세상에 퍼질 불꽃이야. 네가 아제로스의 잠든 힘을 깨울 것이다!', `MaleText_loc4`='你就是那余烬！你就是那火星！你将成为燎原的烈焰。你将唤醒艾泽拉斯的潜力！', `MaleText_loc5`='你就是灰燼，你就是火花!你就是席捲世界的火焰。你將喚醒艾澤拉斯的潛力。', `MaleText_loc7`='Tú eres el ascua. Tú eres la chispa. Tú eres la llama que recorrerá el mundo. ¡Tú despertarás el potencial de Azeroth!' WHERE `ID`=72354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오거라.', `MaleText_loc4`='过来。', `MaleText_loc5`='來我這裡。', `MaleText_loc7`='Ven a mí.' WHERE `ID`=72355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 모구와 티탄의 뿌리가 같음을 안다. 그러나 아직도 수수께끼가 많아. 티탄은 왜 이곳 판다리아에 있었을까?', `MaleText_loc4`='我们已经知道魔古族源自泰坦。可还有许多谜团。他们为何来此？为何来到潘达利亚？', `MaleText_loc5`='我們知道魔古和泰坦有著同樣的根源。但還有許多秘密沒有解開。他們為什麼在這裡?為什麼在潘達利亞上?', `MaleText_loc7`='Ahora sabemos que las raíces de los mogu se remontan a los titanes. Pero quedan muchos misterios. ¿Por qué estaban aquí en Pandaria?' WHERE `ID`=72356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 대체 무엇을 지키러, 혹은 파괴하러 이곳에 온 것인가? 네 도움으로 마지막 퍼즐 조각을 찾을 것이다!', `MaleText_loc4`='魔古族被派来守护什么？或是摧毁什么？我们还缺少关键线索，你得帮我找到它！', `MaleText_loc5`='魔古被派來這裡守護什麼?還是來毀滅?我們缺乏最後幾塊拼圖，而你將協助我找出它們!', `MaleText_loc7`='¿Qué tenían que custodiar los mogu? ¿O destruir? Nos faltan las últimas piezas del rompecabezas y tú me ayudarás a buscarlas.' WHERE `ID`=72357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 준 보석이 너의 세 번째 눈이 될 것이다. 그것을 통해, 네가 보는 것이 내게 전달될 것이다. 우리는 함께 티탄의 비밀을 속속들이 밝힐 것이야.', `MaleText_loc4`='这顶冠冕将成为你的第三只眼。它将我们连为一体。你将成为我的耳目。我们要一起揭开泰坦之谜。', `MaleText_loc5`='我給你的頭冠將會是你的第三隻眼。它能讓我們合而為一。我能見你所見。我們可以一起解開泰坦的秘密。', `MaleText_loc7`='La corona que te he dado será tu tercer ojo. Nos unirá. Veré lo que tú ves. Juntos revelaremos los secretos de los titanes.' WHERE `ID`=72358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 계속 지켜 보겠다, 영웅이여!', `MaleText_loc4`='我会密切关注你的，英雄！', `MaleText_loc5`='我會密切地關注你，英雄!', `MaleText_loc7`='¡Te observaré de cerca!' WHERE `ID`=72359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이시여... 저라면 좀 더 신중히 결정할 것 같습니다.', `MaleText_loc4`='勇士……如果我是你，一定会三思而行。', `MaleText_loc5`='勇士...若是我，會把這東西放在頭上前先考慮清楚。', `MaleText_loc7`='Yo que tú lo pensaría dos veces antes de ponerme esa cosa en la cabeza.' WHERE `ID`=72360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마법석에 따르면, 모구는 티탄의 피조물이었다고 한다. 돌로 만든 영혼이 없는 존재였지. 예상대로구나.', `MaleText_loc4`='根据这块符文石，魔古是泰坦创造的，没有灵魂的岩石生物。我猜也是。', `MaleText_loc5`='根據這塊符石所言，魔古是泰坦的造物，是沒有靈魂的石製生物。和我們所猜的一樣。', `MaleText_loc7`='Según esta piedra rúnica, los mogu eran ensamblajes de los titanes, criaturas de roca sin alma. Como sospechábamos.' WHERE `ID`=72361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법석을 또 찾았구나! 어디 보자. "육신의 저주"로 모구는 필멸의 존재가 되었다. 아, 그런데 나중에 그 과정을 되돌리는 법을 알아냈다는군. 영리한 족속이야.', `MaleText_loc4`='你又找到一块石头！上面写了什么？“血肉诅咒”将魔古变成凡人。啊——可他们找到了逆转诅咒的方法。聪明。', `MaleText_loc5`='你又找到符石了!這塊有什麼訊息?「血肉詛咒」使魔古成為凡人之軀。啊 - 但是後來他們找到辦法反轉這個過程。真是聰明的種族。', `MaleText_loc7`='¡Has encontrado otra piedra! A ver qué dice. La "maldición de la carne" volvió mortales a los mogu. Ah, pero más tarde consiguieron revertirla. Una raza inteligente.' WHERE `ID`=72362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 티탄 수호자를 섬겼다. "라"라는 자였지. 모구 언어로 "라덴"은 "라 주인님"을 뜻한다. 흥미롭구나! 더 알아야겠다!', `MaleText_loc4`='魔古族侍奉一位名叫“莱”的泰坦守护者。在魔古语中，“莱登”即意为“主人莱”。太神奇了！我需要更多信息！', `MaleText_loc5`='魔古對一個泰坦看守者效忠。他的名字是「萊」。用魔古語言來說，「萊公」就是「萊大人」。真有趣!我還要知道更多!', `MaleText_loc7`='Los mogu servían a un guardián de los titanes. Se llamaba "Ra". En el idioma mogu, "Ra den" significa "Maestro Ra". ¡Fascinante! ¡He de saber más!' WHERE `ID`=72363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 주인과 함께 판다리아에 파견되었다는구나. 그들은 커다란 어둠을 찾고 있었다... 아, 조각이 불완전하구나. 더 찾아야 한다.', `MaleText_loc4`='这里提到，魔古族和他们的主人被派来潘达利亚追踪巨大的黑暗——啊，这块碎片不完整。我们得找到剩余部分。', `MaleText_loc5`='根據這塊符石，魔古和他們的主人被派到潘達利亞。他們在尋找一股強大的黑暗 - 啊，碎片並不完整。我們得找出其他的。', `MaleText_loc7`='Según esto, enviaron a los mogu y a su maestro a Pandaria. Perseguían una gran oscuridad... Ah, el fragmento está incompleto. Busquemos más.' WHERE `ID`=72364;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것은 고대 신, "이샤라즈"에 관한 내용이다. 머리 일곱 달린 괴물로, 어둠을 들이마셨다고 하지. 그것이 오늘날까지 판다리아를 괴롭히는 샤의 근원이었던 듯하다.', `MaleText_loc4`='这里提到了一位古神，“亚煞极”。这头野兽有七个头颅，能够吞吐黑暗。我怀疑如今困扰潘达利亚的煞魔就是这个家伙的手笔。', `MaleText_loc5`='這顆，上面提到了上古之神:「亞煞拉懼」，有七顆頭的怪獸，噴出黑暗的氣息。我懷疑今天在潘達利亞作祟的煞就是從這傢伙來的。', `MaleText_loc7`='Aquí se habla de un dios antiguo, "Y''shaarj". Una bestia de siete cabezas que exhalaba oscuridad. Creo que es el origen del sha que sigue asolando Pandaria en nuestro tiempo.' WHERE `ID`=72365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마법석은 "생명의 요람"에 대해 이야기한다. 티탄이 새로운 존재를 만들어낸 곳이지. 옳지. 바로 영원꽃 골짜기다! 그곳은 숄라자르 분지의 운고로 분화구처럼, 살아 있는 실험실이었지.', `MaleText_loc4`='这里提到了“生命的摇篮”。那是泰坦创造新物种的地方。噢，那一定是锦绣谷！它是一座生物实验室，就像安戈洛环形山或索拉查盆地。', `MaleText_loc5`='這顆符石提到了「生命的搖籃」。泰坦可以在這裡創造新生命。噢，當然了，恆春谷!那裡整區是個活實驗室，就像安戈洛環形山或休拉薩盆地。', `MaleText_loc7`='Esta piedra habla de una "Cuna de la Vida". Un lugar en el que los titanes creaban nuevos seres. Ah, claro... ¡es el Valle de la Flor Eterna! Era un laboratorio viviente, como el Cráter de Un''Goro o la Cuenca de Sholazar.' WHERE `ID`=72366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 큰 그림이 보이는구나. 모구는 주인인 티탄을 대신해 골짜기를 지키기 위해 창조되고 이곳에 파견되었다. 하지만 무엇으로부터? 고대 신으로부터?', `MaleText_loc4`='我们正在拼凑线索，勇士。魔古族是由泰坦创造并被派来守卫锦绣谷的。他们要守卫什么呢？古神是否仍是一个威胁呢？', `MaleText_loc5`='我們開始把拼圖湊在一起了，勇士。魔古是被創造並派來這裡替泰坦守護恆春谷的。守護什麼?上古之神仍然是威脅嗎?', `MaleText_loc7`='Vamos completando el rompecabezas. A los mogu se les creó y se les envió aquí para proteger el valle en nombre de sus maestros titanes. ¿Protegerlo de qué? ¿Los dioses antiguos aún eran una amenaza?' WHERE `ID`=72367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 조각에는 "이샤라즈의 날개 달린 군단"에 대한 이야기가 나온다. 고대 신의 종이라... 혹시 사마귀 말인가?', `MaleText_loc4`='嘿，这块碎片提到了“亚煞极的飞翼军团。”那是古神的仆人吗？会不会是螳螂妖呢？', `MaleText_loc5`='這裡，這塊碎片提到了「亞煞拉懼的飛行軍團」。上古之神的僕從?是指螳螂人嗎?', `MaleText_loc7`='Este fragmento habla de "las legiones aladas de Y''Shaarj". ¿Sirvientes de un dios antiguo? ¿Se referirá a los mántides?' WHERE `ID`=72368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 마법석은 비교적 후대의 것이다. "잠자는 수호자"에 대한 내용이지. 아마 라덴을 가리키는 것일 터. 하지만 왜 잠이 든 것일까?', `MaleText_loc4`='这块符文石比较新。它提到了“沉睡的守护者”。我猜这是指莱登。可他为何会沉睡呢？', `MaleText_loc5`='這塊符石比其他的還新。提到了「沈睡的看守者」。我想這指的是萊公。但為什麼他會沈睡?', `MaleText_loc7`='Esta piedra es más reciente que las demás. Dice algo de un "guardián durmiente". Creo que se refiere a Ra Den, pero... ¿por qué dormía?' WHERE `ID`=72369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='퍼즐 조각을 하나 더 찾았구나! 이것은 모구가 만든 것이다. 천 년이나 주인에게서 아무런 지시가 없고 몸이 살로 변해 버리자, 모구는 혼란에 빠졌다. 결국 내분을 일으키기 시작했지.', `MaleText_loc4`='你又找到了这个谜题的新线索！它是魔古族所刻。他们很沮丧——主人已经一千年没有下达指令了，他们的身体也变成了血肉之躯。他们发生了内讧。', `MaleText_loc5`='你又找到謎團的一塊拼圖!這是由魔古所刻的。他們十分沮喪 - 千年來主人毫無任何命令，而他們的身體又血肉化。於是魔古之間開始內鬥。', `MaleText_loc7`='¡Tienes otra pieza! Esta la grabaron los mogu. Estaban frustrados... Llevaban mil años sin órdenes de su maestro y sus cuerpos se habían convertido en carne. Empezaron a pelearse entre ellos.' WHERE `ID`=72370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 모구의 만행에 대한 내용이로구나. 그들은 뿔뿔이 흩어져 각기 군주를 중심으로 족벌을 이루었다. 그중 유난히 야망이 컸던 왕이 있었지. 천둥왕 레이 션이다. 티탄 수호자가 입을 다물자, 그가 대신 입을 열기로 했지.', `MaleText_loc4`='嗯。这里记录了魔古族早期的历史。他们分裂成数个部落。可有一位王者特别野心勃勃——雷电之王，雷神。泰坦守护者沉寂之后，雷神决心代他发号施令。', `MaleText_loc5`='嗯...這塊符石提到了魔古的凶殘。他們分裂成不同的戰士氏族。但是其中一個首領比其他要來得有野心 - 雷神，「雷霆之王」。當泰坦看守者陷入沉默，雷神決定要替他發言。', `MaleText_loc7`='Mmm. Esta piedra rúnica habla del salvajismo de los mogu. Se dividieron en clanes guerreros. Pero un rey era más ambicioso que los demás: Lei Shen. El Rey del Trueno. Cuando el guardián de los titanes dejó de hablar, fue Lei Shen el que tomó la palabra.' WHERE `ID`=72371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 퍼즐의 마지막 조각이구나! 천둥왕은 라덴의 힘, 즉 티탄의 정수를 손에 넣었다. 그는 모구를 통일해 제국을 세우고 티탄의 과업을 계속하려 했다. 자기가 신이라 여긴 것이지!', `MaleText_loc4`='啊！最后一块拼图也齐了。雷电之王窃取了莱登的力量，那是泰坦的精华。他统一魔古帝国，并试图继续泰坦的工作。显然他将自己看成了神！', `MaleText_loc5`='啊!拼圖的最後一塊。雷王取走了萊公的力量，也就是泰坦的能量精華。他將魔古統一為一個帝國並嘗試繼續泰坦的工作。當然了，他把自己當成神了!', `MaleText_loc7`='¡Ah! La última pieza del rompecabezas. El Rey del Trueno adoptó los poderes de Ra den, la esencia misma de un titán. Unificó a los mogu bajo un imperio y trató de continuar la obra de los titanes. Por supuesto, se veía a sí mismo como un dios.' WHERE `ID`=72372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 어서 장막의 계단으로 오거라. 얼굴을 보고 이야기해야겠다.', `MaleText_loc4`='快，回雾纱栈道来找我。我们得当面谈谈。', `MaleText_loc5`='快，回到朦朧天梯。我們必須當面談談。', `MaleText_loc7`='Rápido, ven a verme a la Escalera Velada. Hablaremos cara a cara.' WHERE `ID`=72373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 돌아오길 기다렸다, 용사여.', `MaleText_loc4`='我一直在等待你的归来，勇士。', `MaleText_loc5`='我一直等著你回來，勇士。', `MaleText_loc7`='Esperaba tu regreso con impaciencia.' WHERE `ID`=72374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕은 티탄 수호자의 힘을 지니고 있었다. 그 힘을 되찾아야 한다!', `MaleText_loc4`='雷电之王窃取了泰坦守护者的力量。我们得将它夺回来！', `MaleText_loc5`='雷王自己佔有了泰坦看守者的力量。我們必須把它拿回來!', `MaleText_loc7`='El Rey del Trueno absorbió los poderes de un guardián titánico. ¡Debemos recuperarlos!' WHERE `ID`=72375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 그의 잔혹하고 검은 심장을 가져와라. 이것은 판다렌을 위한 것이다. 우리가 해방시키는 힘은 다시 아제로스를 위해 사용될 것이다.', `MaleText_loc4`='将他的黑暗之核带给我。这不仅能帮熊猫人一把，解放出的力量也将再次造福艾泽拉斯。', `MaleText_loc5`='把他殘酷的黑心帶回來。我們在幫助熊貓人，而我們解放的力量將能用來為艾澤拉斯做出貢獻。', `MaleText_loc7`='Tráeme su corazón negro y cruel. Les haremos un favor a los pandaren y los poderes que liberemos velarán de nuevo por el bien de Azeroth.' WHERE `ID`=72376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등골이 오싹하군요!', `MaleText_loc4`='它让我毛骨悚然！', `MaleText_loc5`='我感到一股寒意升起!', `MaleText_loc7`='Acabo de sentir un escalofrío.' WHERE `ID`=72377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 친구가 승리를 거두고 돌아온 것 같구나.', `MaleText_loc4`='我猜我们的朋友已经凯旋而归了。', `MaleText_loc5`='我敢說我們的朋友凱旋而歸了。', `MaleText_loc7`='Algo me dice que regresas triunfante.' WHERE `ID`=72378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아! 왕의 심장, 신의 힘이다.', `MaleText_loc4`='啊——君王之核。神明之力。', `MaleText_loc5`='嗯!王者的心臟。神祇的力量。', `MaleText_loc7`='Ah, el corazón de un rey. El poder de un dios.' WHERE `ID`=72379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐하시는 겁니까? 설마 그걸 먹지는...', `MaleText_loc4`='你在干什么？你不会真的想吃它——', `MaleText_loc5`='你在做什麼?你不會真的想要把那個吃下吧-', `MaleText_loc7`='¿Qué haces? No estarás pensando en comértelo…' WHERE `ID`=72380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='티탄의 마법으로, 그 창조의 언어로 가득 차 있다.', `MaleText_loc4`='它充满了泰坦的魔力，那是创造的语言——', `MaleText_loc5`='它充滿了泰坦魔法，造物的母語 -', `MaleText_loc7`='Rebosa de magia titánica, el lenguaje de la creación...' WHERE `ID`=72381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 보인다... 수많은 세상이... 완벽한 모습으로 빛나는구나... 아, 무엇보다도 하나가... 아...', `MaleText_loc4`='噢——我看见了——数百万个世界——闪烁着完美的光芒——其中一颗特别璀璨——噢——', `MaleText_loc5`='噢，我看到了 - 數以百萬計的世界 - 完美地閃耀 - 但有一個特別突出 - 噢 -', `MaleText_loc7`='Ah... Los veo... Millones y millones de mundos... brillando, perfectos... Pero uno... por encima de todos los demás... oh...' WHERE `ID`=72382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 우리는 몰락했다. 마지막 티탄을 재건해야 한다. 잊지 말아라.', `MaleText_loc4`='噢——我等已经陨落。我们必须挽救最后的泰坦。牢记这一点。', `MaleText_loc5`='噢 - 我們失敗了。我們必須重建最終的泰坦。不要忘記。', `MaleText_loc7`='OH. HEMOS CAÍDO. DEBEMOS RECONSTRUIR EL ÚLTIMO TITÁN. NO LO OLVIDAREMOS.' WHERE `ID`=72383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 수작이십니까?', `MaleText_loc4`='你又想耍什么花招？', `MaleText_loc5`='你到底想要幹嘛?', `MaleText_loc7`='¿Qué esperas conseguir?' WHERE `ID`=72384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 사라졌다. 아무것도 기억이 안 나는구나. 아! 아무도 기억을 못하다니. 얄궂구나!', `MaleText_loc4`='结束了。我全都忘了。噢！他们也不记得了。真讽刺！', `MaleText_loc5`='影像消失了。我完全無法想起來。噢!沒有人能想起來。真是諷刺!', `MaleText_loc7`='Se ha ido. Ya no recuerdo nada. ¡Oh! Nadie se acuerda. ¡Qué ironía!' WHERE `ID`=72385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 무슨 말이죠? 당신, 못 믿겠군요.', `MaleText_loc4`='你在说什么？我不相信你。', `MaleText_loc5`='你在說什麼?我不信任你。', `MaleText_loc7`='¿De qué estás hablando? No confío en ti.' WHERE `ID`=72386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 편이 나을 것이다.', `MaleText_loc4`='那就对了。', `MaleText_loc5`='明智的抉擇。', `MaleText_loc7`='Y haces bien.' WHERE `ID`=72387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 나는 알아낸 것을 "소화할" 시간이 필요하다. 하지만 곧 움직일 것이다.', `MaleText_loc4`='勇士，我需要时间来……“消化”这些信息。但我们很快就会行动的。', `MaleText_loc5`='勇士，我需要時間來...「消化」我得到的資訊。但我們很快就要採取行動。', `MaleText_loc7`='Necesito tiempo para... "digerir" lo que aprendí. Pero pronto pasaremos a la acción.' WHERE `ID`=72388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문 시전을 멈추십시오! %s|1이;가; |cFFFF0000|Hspell:138763|h[방해의 충격]|h|r을 시전합니다!', `MaleText_loc4`='快停止施法！%s正在酝酿|cFFFF0000|Hspell:138763|h[震荡干涉]|h|r。', `MaleText_loc5`='停止施法!%s正準備使出|cFFFF0000|Hspell:138763|h[斷法震擊]|h|r。', `MaleText_loc7`='¡Deja de lanzar hechizos! %s está generando una |cFFFF0000|Hspell:138763|h[Sacudida interruptora]|h|r.' WHERE `ID`=72389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성스러운 빛을 위해!', `MaleText_loc4`='为了圣光而战！', `MaleText_loc5`='為了聖光!', `MaleText_loc7`='¡Por la Luz!' WHERE `ID`=72390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='직업 재사용 대기시간이 초기화되었습니다!', `MaleText_loc4`='你的职业冷却已经重置了！', `MaleText_loc5`='技能冷卻時間已經重置!', `MaleText_loc7`='¡Los tiempos de reutilización de tu clase se han reiniciado!', `FemaleText_loc1`='직업 재사용 대기시간이 초기화되었습니다!', `FemaleText_loc4`='你的职业冷却已经重置了！', `FemaleText_loc5`='技能冷卻時間已經重置!', `FemaleText_loc7`='¡Los tiempos de reutilización de tu clase se han reiniciado!' WHERE `ID`=72391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 우릴 막겠다고? 잔달라 부족을 막을 순 없다! 이번엔 안 돼!', `MaleText_loc4`='你们竟敢打断我的筹备工作！这一次，赞达拉不可阻挡！', `MaleText_loc5`='你們竟敢打擾我們的準備工作!贊達拉這次不會再被阻止了!', `MaleText_loc7`='¡Cómo osan interrumpir nuestros preparativos! ¡Nadie detendrá a los Zandalari! ¡Esta vez no!', `FemaleText_loc1`='감히 우릴 막겠다고? 잔달라 부족을 막을 순 없다! 이번엔 안 돼!', `FemaleText_loc4`='你们竟敢打断我的筹备工作！这一次，赞达拉不可阻挡！', `FemaleText_loc5`='你們竟敢打擾我們的準備工作!贊達拉這次不會再被阻止了!', `FemaleText_loc7`='¡Cómo osan interrumpir nuestros preparativos! ¡Nadie detendrá a los Zandalari! ¡Esta vez no!' WHERE `ID`=72392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치해라, 명령이다! 잠깐, 멈춰! 멈춰!', `MaleText_loc4`='我命令你，消灭他们！不，住手！住手！', `MaleText_loc5`='消滅他們，我命令你!不，停，停!', `MaleText_loc7`='¡Destrúyanlos, se los ordeno! ¡No, basta! ¡Basta!', `FemaleText_loc1`='놈들을 처치해라, 명령이다! 잠깐, 멈춰! 멈춰!', `FemaleText_loc4`='我命令你，消灭他们！不，住手！住手！', `FemaleText_loc5`='消滅他們，我命令你!不，停，停!', `FemaleText_loc7`='¡Destrúyanlos, se los ordeno! ¡No, basta! ¡Basta!' WHERE `ID`=72393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 감히 나를 깨우는가?', `MaleText_loc4`='是谁竟敢来打扰我？', `MaleText_loc5`='誰膽敢騷擾我?', `MaleText_loc7`='¿Quién se atreve a molestarme?' WHERE `ID`=72394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영혼이 너를 삼킬 것이다!', `MaleText_loc4`='让万灵吞没你！', `MaleText_loc5`='靈魂會吞噬你!', `MaleText_loc7`='¡Los espíritus te consumirán!' WHERE `ID`=72395;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물러서지 마라. 한 치도 내주지 마!', `FemaleText_loc4`='不要后退，我们寸步不让！', `FemaleText_loc5`='不要退縮。連一寸都不能退!', `FemaleText_loc7`='No cedan terreno. ¡No les den ni un centímetro!' WHERE `ID`=72396;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잔달라는 그저 애완동물일 뿐이야. 알겠어? 네놈들은 모구의 노리개라고!', `FemaleText_loc4`='赞达拉就是一群走狗。听懂了没？你们就是魔古族的狗！', `FemaleText_loc5`='贊達拉只是一群看門狗而已。聽到沒有?你們只是魔古的寵物!', `FemaleText_loc7`='Los Zandalari no son más que perros falderos. ¿Me oyen? ¡Solo son mascotas de los mogu!' WHERE `ID`=72397;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다들 흩어지지 말고, 정신 차려.', `FemaleText_loc4`='所有人，相互靠拢，集中精力。', `FemaleText_loc5`='所有人，不要分開。保持警戒。', `FemaleText_loc7`='Oigan todos: no se separen. Concéntrense.' WHERE `ID`=72398;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격! 우리의 지혜는 적의 힘보다 강하다!', `FemaleText_loc4`='继续进攻！我们要打得更聪明！', `FemaleText_loc5`='繼續進攻!我們的腦袋比他們的蠻力強多了!', `FemaleText_loc7`='¡Avancen! ¡Nuestra astucia es superior a su fuerza!' WHERE `ID`=72399;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공격하라!', `FemaleText_loc4`='保持进攻！', `FemaleText_loc5`='繼續進攻!', `FemaleText_loc7`='¡Sigan adelante!' WHERE `ID`=72400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구해주셔서 정말 감사합니다. 이제 성벽을 함락시킵시다!', `MaleText_loc4`='谢谢你。现在，让我们攻破那道城墙吧！', `MaleText_loc5`='謝謝你。好，我們繼續努力，攻下這面牆!', `MaleText_loc7`='Gracias. ¡Ahora a derribar esa muralla!', `FemaleText_loc1`='구해주셔서 정말 감사해요. 이제 성벽을 함락시키자고요!', `FemaleText_loc4`='谢谢你。现在，让我们攻破那道城墙吧！', `FemaleText_loc5`='謝謝你。好，我們繼續努力，攻下這面牆!', `FemaleText_loc7`='Gracias. ¡Ahora a derribar esa muralla!' WHERE `ID`=72401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 감사드립니다.', `MaleText_loc4`='我要谢谢你。', `MaleText_loc5`='由衷感謝。', `MaleText_loc7`='Tienes mi gratitud.', `FemaleText_loc1`='정말 감사해요.', `FemaleText_loc4`='我要谢谢你。', `FemaleText_loc5`='由衷感謝。', `FemaleText_loc7`='Tienes mi gratitud.' WHERE `ID`=72402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 천둥왕과 싸웁시다!', `MaleText_loc4`='让我们与雷电之王决一死战吧！', `MaleText_loc5`='給雷王好看!', `MaleText_loc7`='¡Vamos a enfrentarnos al Rey del Trueno!', `FemaleText_loc1`='이제 천둥왕과 싸워요!', `FemaleText_loc4`='让我们与雷电之王决一死战吧！', `FemaleText_loc5`='給雷王好看!', `FemaleText_loc7`='¡Vamos a enfrentarnos al Rey del Trueno!' WHERE `ID`=72403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서요! 계속 갑시다!', `MaleText_loc4`='来吧！让我们继续前进！', `MaleText_loc5`='來吧!繼續前進!', `MaleText_loc7`='¡Vamos! ¡Sigamos avanzando!', `FemaleText_loc1`='어서요! 계속 가요!', `FemaleText_loc4`='来吧！让我们继续前进！', `FemaleText_loc5`='來吧!繼續前進!', `FemaleText_loc7`='¡Vamos! ¡Sigamos avanzando!' WHERE `ID`=72404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라에게 패배를!', `MaleText_loc4`='去死吧，赞达拉巨魔！', `MaleText_loc5`='贊達拉必死無疑!', `MaleText_loc7`='¡Muerte a los Zandalari!', `FemaleText_loc1`='잔달라에게 패배를!', `FemaleText_loc4`='去死吧，赞达拉巨魔！', `FemaleText_loc5`='贊達拉必死無疑!', `FemaleText_loc7`='¡Muerte a los Zandalari!' WHERE `ID`=72405;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='함선에서 관문까지 길을 터야 해요. 육지로 움직여야 할 것 같거든요.', `FemaleText_loc4`='在船只和上层大门间清出一条路来——我们得步行通过。', `FemaleText_loc5`='我們得從船隻到上面的門之間清出一條路 - 我們得步行前往。', `FemaleText_loc7`='Despeja un camino desde el barco hasta la puerta del nivel superior. Cruzaremos a pie.' WHERE `ID`=72406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시누 아마노레, 용사여.', `MaleText_loc4`='Sinu a''manore，勇士。', `MaleText_loc5`='Sinu a’manore，勇士。', `MaleText_loc7`='Sinu a''manore, valiente.' WHERE `ID`=72407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 찾아 온 이 괴수와 음영파만 있으면, 천둥왕의 무기고에 침투해서 무력화시킬 수 있소.', `MaleText_loc4`='在影踪派和这头野兽的帮助下，我想我们能够潜入并摧毁雷电之王的武器库。', `MaleText_loc5`='在影潘和你找到的這隻野獸幫助之下，我相信我們能潛入並佔領雷王的軍械庫。', `MaleText_loc7`='Con la ayuda del Shadopan y de esta bestia que has recuperado, creo que podremos infiltrarnos e inutilizar el arsenal del Rey del Trueno.' WHERE `ID`=72408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비 되면 내게 말하시오.', `MaleText_loc4`='你准备好就告诉我一声。', `MaleText_loc5`='等你準備好，跟我說。', `MaleText_loc7`='Habla conmigo cuando quieras empezar.' WHERE `ID`=72409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엘시아가 기다리고 있소.', `MaleText_loc4`='艾尔希娅在等着你，勇士。', `MaleText_loc5`='艾爾西雅正在等你，勇士。', `MaleText_loc7`='Elsia te está esperando.' WHERE `ID`=72410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대! 제련소를 확보하라. 문을 닫을 수 없게 부숴버려!', `MaleText_loc4`='游侠们！保卫熔炉。打破大门，别让它关上了！', `MaleText_loc5`='遊俠們!守好熔爐。攻破大門，讓它再也關不了!', `MaleText_loc7`='¡Forestales! Aseguren la forja. Destrocen la puerta para que no se pueda cerrar.' WHERE `ID`=72411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 성과군. 음영파가 훌륭한 동맹이 될 줄 알았소.', `MaleText_loc4`='难以置信。我就知道影踪派会是出色的盟友。', `MaleText_loc5`='做得好。我就知道影潘是很好的盟友。', `MaleText_loc7`='Un trabajo increíble. Sabía que el Shadopan sería un aliado formidable.' WHERE `ID`=72412;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어쨌든, 우린 천둥왕에게 큰 피해를 줬소. 호드의 금속 장인들이 모구의 제작 기술을 연구할 것이오.', `MaleText_loc4`='无论如何，我们今天重创了雷电之王。部落的铁匠会立即开始研究魔古族的锻造技术。', `MaleText_loc5`='不管如何，我們都重創了雷王。部落的鐵匠會立刻開始研究魔古的工藝技術。', `MaleText_loc7`='En cualquier caso, hemos asestado un gran golpe al Rey del Trueno. Los herreros de la Horda empezarán a estudiar las técnicas de los mogu inmediatamente.' WHERE `ID`=72413;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='때가 되면 그럴 거요, 친구. 때가 된다면.', `MaleText_loc4`='看情况，熊猫人朋友。这得看情况。', `MaleText_loc5`='時候到就會了，熊貓人朋友，時候到就會了。', `MaleText_loc7`='A su debido tiempo, amiga. A su debido tiempo.' WHERE `ID`=72414;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 단지 적이 같을 뿐입니다, 섭정이시여.', `FemaleText_loc4`='我们有着共同的敌人，摄政王阁下。仅此而已。', `FemaleText_loc5`='我們有共同的敵人，攝政王。如此而已。', `FemaleText_loc7`='Tenemos un enemigo común, Señor regente. Nada más.' WHERE `ID`=72415;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 죄송하지만, 이 끔찍한 무기들을 없애버려야 합니다!', `FemaleText_loc4`='恕我直言——这些畸形的武器应该被销毁！', `FemaleText_loc5`='恕我直言 - 這些可怕的工具應該要摧毀掉!', `FemaleText_loc7`='Con el debido respeto, ¡hay que destruir esas herramientas abominables!' WHERE `ID`=72416;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 만나니 반갑군, 모험가. 시작할 준비가 되었느냐?', `MaleText_loc4`='很高兴再次见到你，冒险者。你做好出发的准备了吗？', `MaleText_loc5`='很高興見到你，冒險者。你準備好要開始了嗎?', `MaleText_loc7`='Me alegro de volver a verte. ¿Quieres comenzar?' WHERE `ID`=72417;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갑시다!', `MaleText_loc4`='我们走！', `MaleText_loc5`='開始吧!', `MaleText_loc7`='¡Vamos!', `FemaleText_loc1`='갑시다!', `FemaleText_loc4`='我们走！', `FemaleText_loc5`='開始吧!', `FemaleText_loc7`='¡Vamos!' WHERE `ID`=72418;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도움 감사합니다, 모험가님. 최선을 다해 모구를 물리치는 것을 돕겠습니다.', `MaleText_loc4`='感谢你的帮助，冒险者。我们会尽力帮你挡住魔古族的。', `MaleText_loc5`='感謝你的援助，冒險者。我們會盡全力抵抗這些魔古。', `MaleText_loc7`='Gracias por tu ayuda. Te asistiremos lo mejor que podamos para repeler a los mogu.' WHERE `ID`=72419;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 시작할 준비가 되었습니다.', `MaleText_loc4`='我准备好了，可以开始完成任务了。', `MaleText_loc5`='我已經準備好開始執行任務。', `MaleText_loc7`='Estoy preparado para comenzar mi misión.', `FemaleText_loc1`='임무를 시작할 준비가 되었어요.', `FemaleText_loc4`='我准备好了，可以开始完成任务了。', `FemaleText_loc5`='我已經準備好開始執行任務。', `FemaleText_loc7`='Estoy preparada para comenzar mi misión.' WHERE `ID`=72420;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 전장에서 실력을 증명한 분에게만 물건을 판매합니다. 전장에서 얼라이언스 쓰레기들을 싹쓸이한 다음에 찾아오십시오.', `MaleText_loc4`='我的货物只卖给那些在战场上证明过自己的人。等你扫清了战场上的联盟渣滓再来找我吧。', `MaleText_loc5`='我的軍需品只保留給那些在戰場上證明過自己的人。等你把戰場上的聯盟廢物掃蕩乾淨以後再來找我。', `MaleText_loc7`='Mis mercancías están reservadas para los que han demostrado su valía en la batalla. Ven a verme cuando hayas limpiado los campos de escoria de la Alianza.', `FemaleText_loc1`='저는 전장에서 실력을 증명한 분에게만 물건을 판매합니다. 전장에서 얼라이언스 쓰레기들을 싹쓸이한 다음에 찾아오십시오.', `FemaleText_loc4`='我的货物只卖给那些在战场上证明过自己的人。等你扫清了战场上的联盟渣滓再来找我吧。', `FemaleText_loc5`='我的軍需品只保留給那些在戰場上證明過自己的人。等你把戰場上的聯盟廢物掃蕩乾淨以後再來找我。', `FemaleText_loc7`='Mis mercancías están reservadas para los que han demostrado su valía en la batalla. Ven a verme cuando hayas limpiado los campos de escoria de la Alianza.' WHERE `ID`=72422;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 전장에서 실력을 증명한 분에게만 물건을 판매합니다. 호드 쓰레기보다 우월하다는 것을 증명해야만 당신에게 제 물건을 믿고 맡길 수 있습니다.', `MaleText_loc4`='我的货物只卖给那些在战场上证明过自己的人。在我把它们托付给你之前，你得先证明自己比那些部落渣滓强。', `MaleText_loc5`='我的軍需品只保留給那些在戰場上證明過自己的人。等你證明自己比部落的廢物強，我才會把東西交給你。', `MaleText_loc7`='Mis mercancías están reservadas para los que han demostrado su valía en la batalla. Tendrás que demostrar tu dominio sobre la escoria de la Horda para que te las entregue.', `FemaleText_loc1`='저는 전장에서 실력을 증명한 분에게만 물건을 판매하죠. 호드 쓰레기보다 우월하다는 것을 증명해야만 당신에게 제 물건을 믿고 맡길 수 있어요.', `FemaleText_loc4`='我的货物只卖给那些在战场上证明过自己的人。在我把它们托付给你之前，你得先证明自己比那些部落渣滓强。', `FemaleText_loc5`='我的軍需品只保留給那些在戰場上證明過自己的人。等你證明自己比部落的廢物強，我才會把東西交給你。', `FemaleText_loc7`='Mis mercancías están reservadas para los que han demostrado su valía en la batalla. Tendrás que demostrar tu dominio sobre la escoria de la Horda para que te las entregue.' WHERE `ID`=72423;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크로스의 환영이 부랑칼날 의식술사를 먹어치우기 전에 의식술사를 처치하십시오!', `MaleText_loc4`='在邪刃祭司被克洛斯的回响吞噬之前，快去杀了他！', `MaleText_loc5`='殺掉那個污刃祭儀師，別讓克羅斯的回音吃掉它!', `MaleText_loc7`='¡Mata al ritualista Hojaescoria antes de que el eco de Kros se lo coma!' WHERE `ID`=72424;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대가 찾아낸 생물은 섬을 보호하는 번개의 영향을 받지 않더군요.', `FemaleText_loc4`='你发现的这个生物能够免疫岛上的防御闪电。', `FemaleText_loc5`='你找到的這隻生物對保護島嶼的雷電攻擊免疫。', `FemaleText_loc7`='La criatura que has recogido es inmune a los relámpagos que protegen la isla.' WHERE `ID`=72425;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈 수 있겠습니까?', `FemaleText_loc4`='你能试着骑上它吗？', `FemaleText_loc5`='你覺得你能駕馭牠嗎?', `FemaleText_loc7`='¿Te crees capaz de domarla?' WHERE `ID`=72426;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋습니다! 하늘로 날아 오르면, 잔달라 트롤이 막으려 할 겁니다.', `FemaleText_loc4`='很好！只要你飞上天空，赞达拉一定会来阻止你。', `FemaleText_loc5`='太棒了!等你飛上空中，贊達拉會嘗試阻止你。', `FemaleText_loc7`='¡Muy bien! Cuando subas a los cielos, los Zandalari intentarán detenerte.' WHERE `ID`=72427;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공중전을 벌일 준비를 하세요. 필요하면 다른 생물로 옮겨가야 합니다!', `FemaleText_loc4`='做好空战的准备。必要时，你可以跳上别的坐骑！', `FemaleText_loc5`='準備好進行空戰。有必要的話，跳到別的坐騎上!', `FemaleText_loc7`='Prepárate para el combate aéreo. ¡Salta a otra montura si es necesario!' WHERE `ID`=72428;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파 연락책이 광산 뒤에서 기다리고 있을 겁니다. 행운을 빌어요!', `FemaleText_loc4`='影踪派的密探会在矿洞后等你。别让她久等。祝你好运！！', `FemaleText_loc5`='一位影潘的密探會在礦坑後面跟你碰面。祝好運!', `FemaleText_loc7`='Un contacto del Shadopan te estará esperando detrás de las minas. ¡Buena suerte!' WHERE `ID`=72429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 또 폭동인가?', `MaleText_loc4`='怎么了？又暴动了？', `MaleText_loc5`='這是什麼?又有暴動了?', `MaleText_loc7`='¿Cómo? ¿Otra sublevación?' WHERE `ID`=72430;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주제넘은 네놈을 밟아주겠다.', `MaleText_loc4`='我这就让你们滚回去。', `MaleText_loc5`='我會讓你回到該去的地方。', `MaleText_loc7`='Pronto te pondré en tu sitio.' WHERE `ID`=72431;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 노예가 아니잖아. 어떻게 여기에 왔지?', `MaleText_loc4`='你不是奴隶。你在这里干什么？', `MaleText_loc5`='你不是奴隸。你怎麼來這裡的?', `MaleText_loc7`='No eres uno de los esclavos. ¿Cómo llegaste aquí?' WHERE `ID`=72432;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 발에 족쇄를 채워주겠다! 죽여달라고 애원하게 해주마!', `MaleText_loc4`='你马上就会被栓起来！到时候你会只求一死！！', `MaleText_loc5`='我會把你們鎖起來!你們會求死不能!', `MaleText_loc7`='¡Os voy a encadenar antes de eliminaros y suplicaréis la muerte!' WHERE `ID`=72433;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고개를 숙이지 못할까!', `MaleText_loc4`='屈服于我！', `MaleText_loc5`='給我跪下!', `MaleText_loc7`='¡Inclínate ante mí!' WHERE `ID`=72434;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 주인 앞에 무릎 꿇어라!', `MaleText_loc4`='跪下吧！', `MaleText_loc5`='在主人面前跪下!', `MaleText_loc7`='¡Arrodíllate ante tu amo!' WHERE `ID`=72435;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는... 벌을 받으리라...', `MaleText_loc4`='你会被……严惩的……', `MaleText_loc5`='你們會...受到懲罰...', `MaleText_loc7`='Lo... pagarás...' WHERE `ID`=72436;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿불지기 틴조의 생명력이 거의 다 차 갑니다!', `MaleText_loc4`='余烬守护者提佐的生命值快要回满了！', `MaleText_loc5`='『餘燼護法』丁佐的生命值接近全滿了!', `MaleText_loc7`='¡Tinzo el Guardalumbres tiene la salud casi al máximo!' WHERE `ID`=72437;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잿불지기 틴조가 치유 효과를 모두 빼앗고 있습니다!', `MaleText_loc4`='余烬守护者提佐正在偷取你所有的治疗！', `MaleText_loc5`='『餘燼護法』丁佐在竊取你所有的治療!', `MaleText_loc7`='¡Tinzo el Guardalumbres te está robando todas tus sanaciones!' WHERE `ID`=72438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르독이 방패로 강타할 준비를 합니다.', `MaleText_loc4`='寇多克发动了一次强力盾牌猛击。', `MaleText_loc5`='柯爾多克使出一記強力的盾牌猛擊。', `MaleText_loc7`='Kor''dok lanza un buen golpe de escudo.' WHERE `ID`=72439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아싸! 드디어! 싸움꾼 조합 초대장이다! 이제 날 막을 자는 없어!', `MaleText_loc4`='耶！终于来了！我赢得了搏击俱乐部的邀请函！现在谁也别想拦着我！', `MaleText_loc5`='太棒了!我終於拿到鬥陣俱樂部的邀請!沒有人能阻止我了!', `MaleText_loc7`='¡Sí! ¡Por fin he ganado una invitación para el Gremio de luchadores! ¡Ahora nadie podrá detenerme!' WHERE `ID`=72440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움꾼이 되기엔 부족했던 모양이야.', `MaleText_loc4`='我想我还没有做好成为拳手的准备。', `MaleText_loc5`='我大概還不夠格當鬥士吧。', `MaleText_loc7`='Supongo que no estaba preparado para ser un luchador.' WHERE `ID`=72441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 이것 좀 봐요! 싸움꾼 조합 초대장을 받았어요! 어서 가 보고 싶네요!', `MaleText_loc4`='大家快看！我赢得了搏击俱乐部的邀请函！我已经等不及要去试试身手了！', `MaleText_loc5`='大家看啊!我贏到鬥陣俱樂部的邀請了!我等不及要拿來用啊!', `MaleText_loc7`='¡Miren todos! ¡He ganado una invitación para el Gremio de luchadores! ¡Estoy deseando usarla!' WHERE `ID`=72442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 싸움꾼 조합 초대장을 받았어! 분명 오늘 밤이면 8계급이 될 거야! 도착하기 전에 초대장을 잃어버리지 않아야 하는데.', `MaleText_loc4`='我刚刚赢得了一张搏击俱乐部的邀请函！我今晚肯定就能到8级！但愿在抵达那里之前，我不会把票弄丢了。', `MaleText_loc5`='我剛剛贏到鬥陣俱樂部的邀請了!今晚我一定會衝到第8階的!希望不要人還沒到就把票搞丟了...', `MaleText_loc7`='¡Acabo de ganar una invitación para el Gremio de luchadores! ¡Seguro que esta noche ya tendré rango 8! Espero no perder la invitación antes de llegar.' WHERE `ID`=72443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위에서 내려다보는 광경은 정말이지... 끝내준다고!', `MaleText_loc4`='这上面的景色真是……激动人心！', `MaleText_loc5`='上頭的視野...太棒了!', `MaleText_loc7`='¡La vih''ta desde arriba es... impresionante!' WHERE `ID`=72444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아가들아, 놈들을 잡아라!', `MaleText_loc4`='我的宠物，抓住他们！', `MaleText_loc5`='我的寵物，抓住他們!', `MaleText_loc7`='¡A por ellos, mascotas!' WHERE `ID`=72445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=72446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낙법 쓰는 거 잊어버리지 말라고, 도적.', `MaleText_loc4`='祝你安全降落，潜行者。', `MaleText_loc5`='祝你安全降落，盜賊。', `MaleText_loc7`='Te deseo una buena caída, $gpícaro:pícara;.' WHERE `ID`=72447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날아볼텐가?', `MaleText_loc4`='正在……上升？', `MaleText_loc5`='起...飛嗎?', `MaleText_loc7`='¿Subes...?' WHERE `ID`=72448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가벼운 깃털 몇 개는 가지고 있겠지, 사제? 뭐? 이제 필요없다고?', `MaleText_loc4`='但愿你在包里塞了羽毛，牧师。', `MaleText_loc5`='希望你的天使翅膀能派上用場，牧師。', `MaleText_loc7`='Espero que lleves unas cuantas plumas, $gsacerdote:sacerdotisa;.' WHERE `ID`=72449;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걱정 마. 돈 받고 하는 일은 아니니까 말이야.', `MaleText_loc4`='没有钱？那这次飞行就算我的好了。', `MaleText_loc5`='沒錢了?這趟算我的。', `MaleText_loc7`='¿No tienes pasta? Yo invito a este vuelo.' WHERE `ID`=72450;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안 돼!', `FemaleText_loc4`='不！', `FemaleText_loc5`='不!', `FemaleText_loc7`='¡NO!' WHERE `ID`=72451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 난 이 세상에 존재하는 마의 에너지에 진정으로 통달했다! 내가 가진 악마의 힘은... 형언할 수 없고, 무한하며, 전능하다!', `MaleText_loc4`='看呐！我真的掌握了这个世界的魔能！现在，我掌握着恶魔之力……它难以名状，无穷无尽，无所不能！', `MaleText_loc5`='看哪!我徹底掌握了這片土地的魔化能量!如今任我掌控的這股惡魔之力...是無以言喻，無窮無盡，無所不能的!', `MaleText_loc7`='¡OBSERVA! Domino completamente las energías viles de este mundo. Ahora dirijo el poder demoníaco... es indescriptible, ilimitado, ¡OMNIPOTENTE!' WHERE `ID`=72452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 선을 넘었다고 생각하나? 내게 한계 따위는 없다. 암흑의 수확 의회는 가장 강력한 악마를 노예로 삼고, 그들의 힘을 이용해 이 세상과 아제로스에서 우리에 맞서는 자들을 처단할 것이다! 그런데 네놈 따위가 날 막겠다고? 너 따위 애송이가?', `MaleText_loc4`='你觉得我走火入魔了？没有这回事。黑暗收割议会将奴役最强大的恶魔，抽取他们的力量，并摧毁一切反抗者，无论是在这个世界，还是在艾泽拉斯！你真的想阻止我吗，小家伙？', `MaleText_loc5`='你認為我做得太過了?不可能的。黑穫議會將奴役那些最強大的惡魔，汲取它們的力量，消滅所有對抗我們的人，無論是在這片大地還是艾澤拉斯!小傢伙，難道你想阻止我嗎?', `MaleText_loc7`='¿Crees que he ido demasiado lejos? Nunca es demasiado. La Cosecha Oscura esclavizará a los demonios más poderosos, les arrebatará su poder, y acabará con todo el que se oponga a nosotros, en este mundo y en Azeroth. ¿PRETENDES detenerme, renacuajo?' WHERE `ID`=72453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘은 네 상상을 뛰어넘는다!', `MaleText_loc4`='我的力量超出你的想象！', `MaleText_loc5`='我的力量超乎想像!', `MaleText_loc7`='¡Mi poder es inimaginable!' WHERE `ID`=72455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하. 약해빠진 네 공격이 귀엽군. 이제 내 새로운 소환수를 보여주지.', `MaleText_loc4`='哈。你虚弱无力的攻击简直令我发笑。想看看我的新宠物吗？', `MaleText_loc5`='哈，你那無用的攻擊還真有意思。想瞧瞧我的新寵物嗎?', `MaleText_loc7`='Ja. Tus débiles ataques son muy entretenidos. ¿Quieres conocer a una de mis nuevas mascotas?' WHERE `ID`=72456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 실력을 보여봐라.', `MaleText_loc4`='我喜欢看你徒劳的挣扎。', `MaleText_loc5`='你就試試吧。', `MaleText_loc7`='Me gustaría verte intentarlo.' WHERE `ID`=72457;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나이힐란은 매우 파괴적인 종족이지. 이들의 순수한 힘과 기운은 독보적이다.', `MaleText_loc4`='安尼赫兰是极具毁灭性的生物。他们那排山倒海般的力量无人能挡。', `MaleText_loc5`='安尼希蘭是極具破壞力的生物。他們的蠻力與強大無可匹敵。', `MaleText_loc7`='Los annihilan son criaturas increíblemente destructivas. Su fuerza y su poder no tienen rival.' WHERE `ID`=72458;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이럴수가?! 감히 날 화나게 했겠다.', `MaleText_loc4`='什么？！这下你可惹怒我了。', `MaleText_loc5`='什麼?!你把我惹火了。', `MaleText_loc7`='¡¿Qué?! Ya me has enfadado.' WHERE `ID`=72459;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 영혼을 조각내주마!', `MaleText_loc4`='我要撕碎你的灵魂！', `MaleText_loc5`='我要粉碎你的靈魂!', `MaleText_loc7`='Te destrozaré el alma.' WHERE `ID`=72460;
