UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙은 어마어마한 힘을 갖고 있었지. 그리고 이제, 그 힘은 내것이다!', `MaleText_loc4`='死亡之翼曾拥有无可匹敌的力量。现在，它属于我了。', `MaleText_loc5`='死亡之翼曾經擁有強大無比的力量。如今，這股力量是我的了。', `MaleText_loc7`='Alamuerte tenía un poder ilimitado. Y ese poder es mío ahora.' WHERE `ID`=72462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 최후의 대격변을 막을 순 없다!', `MaleText_loc4`='你休想抗拒末日的降临！', `MaleText_loc5`='你阻止不了最後的浩劫!', `MaleText_loc7`='¡No podrás evitar tu Cataclismo final!' WHERE `ID`=72463;
