UPDATE `locales_broadcast_text` SET `MaleText_loc1`='처음에는 별 거 아니겠지. 하지만 조금 있으면 곧 참을 수 없는 고통에 휩싸일 거다.', `MaleText_loc4`='这刚开始可能不算什么，但只要等一段时间，疼痛就会变得难以忍受。', `MaleText_loc5`='這起初看來似乎微不足道，但等一會吧。很快，你就會痛不欲生。', `MaleText_loc7`='Puede no parecer gran cosa al principio, pero dale tiempo. Pronto el dolor será insoportable.' WHERE `ID`=72477;
