UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포에 젖어 도망쳐라, 겁쟁아.', `MaleText_loc4`='害怕地逃跑吧，懦夫。', `MaleText_loc5`='懦夫，夾著尾巴跑吧。', `MaleText_loc7`='Corre, cobarde.' WHERE `ID`=72483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파괴의 힘이 네 안을 부패시킬 것이다.', `MaleText_loc4`='毁灭之力将从内部侵蚀你。', `MaleText_loc5`='破滅之力從體內腐化你。', `MaleText_loc7`='Las fuerzas destructivas te corrompen desde dentro.' WHERE `ID`=72484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씨앗을 심었으니 크는 걸 봐야겠지...', `MaleText_loc4`='埋下一颗种子，然后看着它成长……', `MaleText_loc5`='播下種子，看著它成長...', `MaleText_loc7`='Planta una semilla y observa cómo crece...' WHERE `ID`=72485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씨앗이 커서 무엇이 될까?', `MaleText_loc4`='我很好奇这颗种子会长成什么？', `MaleText_loc5`='不知道這種子會長成什麼樣子?', `MaleText_loc7`='Me pregunto en qué se convertirá esta semilla.' WHERE `ID`=72486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 파괴의 축복을 선사하마!', `MaleText_loc4`='我将赐予你毁灭的礼物！', `MaleText_loc5`='我賜與你毀滅之贈!', `MaleText_loc7`='¡Te otorgo el don de la destrucción!' WHERE `ID`=72487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='씨앗이 싹을 틔우는 순간, 끔찍한 파멸이 널 기다리고 있을 것이다.', `MaleText_loc4`='当这颗种子发芽时，可怕的毁灭将等着你。', `MaleText_loc5`='種子萌發時，恐怖的破滅將等待著你。', `MaleText_loc7`='Una terrible destrucción te espera cuando esta semilla dé fruto.' WHERE `ID`=72488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혼돈의 마법은 늘 예측 밖의 결과를 불러오지.', `MaleText_loc4`='混乱魔法总是有可能导致出人意料的后果。', `MaleText_loc5`='混沌魔法總是可能導致意料之外的結果。', `MaleText_loc7`='La magia caótica tiene el potencial de proporcionar resultados inesperados.' WHERE `ID`=72489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에레드루인을 활용해야겠다는 아키몬드의 생각은 천재적이었다. 암흑 에너지를 다루는 그들의 솜씨는 그 누구보다도 뛰어나니까.', `MaleText_loc4`='阿克蒙德聪明地利用了埃雷杜因。他们对黑暗能量的掌控无人能及。', `MaleText_loc5`='阿克蒙德利用安瑞德魯的方式很高明。他們對黑暗能量的掌握無與倫比。', `MaleText_loc7`='Archimonde utilizó a los ered''ruin de forma brillante. Su dominio de las energías oscuras no tiene igual.' WHERE `ID`=72490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에레드루인은 아키몬드가 죽은 뒤 오랫동안 주인이 없었지. 이제 내가 그들의 새 주인이 되겠다.', `MaleText_loc4`='自从阿克蒙德死后，埃雷杜因就失去了主人。现在，我将成为他们的新主人。', `MaleText_loc5`='安瑞德魯在阿克蒙德死後就失去了主人。如今我要成為他們的主人。', `MaleText_loc7`='Los ered''ruin no tienen amo desde que Archimonde murió. Ahora yo seré su amo.' WHERE `ID`=72491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥사냥개 무리는 강력한 투사는 아니지만 여러모로 활용도가 높다.', `MaleText_loc4`='虽然不是最强大的战士，但一群地狱猎犬还是很有用的。', `MaleText_loc5`='一群惡魔獵犬雖然稱不上頂尖的戰力，仍有許多用處。', `MaleText_loc7`='Es verdad que no son los combatientes más poderosos, pero una manada de canes manáfagos siempre es útil.' WHERE `ID`=72492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지옥사냥개들은 항상 마법에 굶주려 있다.', `MaleText_loc4`='地狱猎犬总是渴望能吞噬更多的魔法。', `MaleText_loc5`='惡魔獵犬總是渴望著吞噬魔力。', `MaleText_loc7`='Los canes manáfagos siempre tienen hambre de magia.' WHERE `ID`=72493;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만약 임프 두 마리가 한 마리보다 낫다면. 두 마리 임프보다 나은 건 뭘까? 바로 60마리의 임프지.', `MaleText_loc4`='如果说两个小鬼就是比一个要强，那什么能比两个小鬼更强呢？那就是六个小鬼。', `MaleText_loc5`='如果兩隻小鬼比一隻小鬼好，那什麼比兩隻小鬼好?答案是六十隻小鬼。', `MaleText_loc7`='Si dos diablillos son mejor que un diablillo, ¿qué es mejor que dos diablillos? SESENTA DIABLILLOS.' WHERE `ID`=72494;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가장 작은 악마도 충분한 수가 모이면 매우 강력해진다.', `MaleText_loc4`='哪怕是最小的恶魔，只要数量够多，也是非常宝贵的助力。', `MaleText_loc5`='只要數量夠多，就連最不起眼的惡魔都有用處。', `MaleText_loc7`='Incluso el demonio más pequeño es valioso, si tienes una cantidad lo suficientemente grande.' WHERE `ID`=72495;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칸레타드, 이런 상황이 오면 자신을 막아달라며 내게 부탁했던 일이야. 결국 네가 자초한 일이지.', `FemaleText_loc4`='我只是按照你之前的要求罢了，坎雷萨德。事情发展到这一步都是你自找的。', `FemaleText_loc5`='坎瑞薩德，這正是你先前囑咐我的，萬一事情演變到如此地步的時候，我就得這麼做。這是你自找的。', `FemaleText_loc7`='Es lo que me pediste que hiciera si llegábamos a esto, Kanrethad. Tú te lo has buscado.' WHERE `ID`=72496;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$n. 도와줘서 고마워. 비록 세상 사람들은 알지 못하겠지만, 너는 수많은 이들을 위협에서 구한 거야. 칸레타드는 반드시 막아야 했어. 그가 계속 추방에서 돌아오지 못하도록 내가 감시하지.', `FemaleText_loc4`='$n，感谢你的帮助。虽然全世界或许都不会知道，但你又默默地拯救了他们一次。我们必须阻止坎雷萨德。我会确保他被放逐后无法再回来。', `FemaleText_loc5`='$n，感謝你的協助。即使全世界都不知情，但其實你已拯救了大家的性命。絕不能讓坎瑞薩德得逞，我會確保將他永遠封印放逐的。', `FemaleText_loc7`='$n, gracias por tu ayuda. A pesar de que el mundo no lo sepa, tu papel en su salvación es más importante de lo que creen. Había que detener a Kanrethad. Yo me encargaré de que permanezca en el destierro.' WHERE `ID`=72497;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='칸레타드는 마의 에너지에 뒤덮힌 탓에 완전히 타락해 버렸어. 그의 힘을 조금만 쓴다면 너에게 크게 해롭지는 않을 거야. 흡수해보라고.', `FemaleText_loc4`='坎雷萨德周围的邪能太过充沛，他已经被彻底腐蚀了。但稍微尝试一下他的力量并无大碍。去吧。', `FemaleText_loc5`='坎瑞薩德汲取了過多的魔化能量，結果遭到反噬，害他被徹底腐化了。但如果只吸取他一小部分的法力應該不會有問題，動手吧。', `FemaleText_loc7`='Kanrethad se rodeó de tal cantidad de energía vil que acabó completamente corrompido. Pero probar un poco de su poder no tiene nada de malo. Adelante.' WHERE `ID`=72498;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 가. 그리고 여기서 네가 배운 걸 활용해. 만약 마의 에너지를 제거하고 싶거나 칸레타드에게서 다시 흡수하고 싶다면 내게 말하고. 나는 어둠달 골짜기에 있는 저주의 제단에서 그를 감시하고 있겠어.', `FemaleText_loc4`='去吧，好好利用你所学到的一切。如果你想净化体内的邪能，或者重新吸收坎雷萨德的力量，就跟我谈谈。我会待在影月谷的诅咒祭坛，确保他被放逐。', `FemaleText_loc5`='走吧，好好利用你學到的東西。如果你想淨化身上的魔化能量，或是再重新吸收一些坎瑞薩德的法力，隨時可以來找我。我會待在影月谷的詛咒祭壇，確保他的封印。', `FemaleText_loc7`='Ahora ve y utiliza lo que has aprendido. Si en algún momento quieres deshacerte de la energía vil o si quieres reabsorber un poco de la de Kanrethad, ven a hablar conmigo. Estaré en El Altar de Condenación en el Valle Sombraluna, asegurándome de que permanece en el destierro.' WHERE `ID`=72499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하... 날 쓰러뜨렸다고 생각했나? 아무도 날 죽일 수 없다, 하찮은 필멸자여!', `MaleText_loc4`='哈哈哈……你以为自己能击败我？现在，没有什么能杀死我了，卑微的凡人！', `MaleText_loc5`='哈哈哈...你以為你能打敗我?渺小的凡人，如今誰也殺不了我的!', `MaleText_loc7`='Ja, ja, ja... ¿Creías que podías derrotarme? NADA puede matarme ahora, pobre mortal.' WHERE `ID`=72500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 이제, 네 슬픈 이야기의 종지부를 찍어주마.', `MaleText_loc4`='现在，你的可悲传说即将落幕。', `MaleText_loc5`='現在，你悲傷的故事要畫下句點了。', `MaleText_loc7`='Y ahora, tu triste historia llega a su final.' WHERE `ID`=72501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주베카?! 지금 뭐하는...?!', `MaleText_loc4`='裘碧卡？！你在干什么……？！', `MaleText_loc5`='裘貝卡?!你在做什麼...?!', `MaleText_loc7`='¡¿Jubeka?! ¡¿Qué eres...?!' WHERE `ID`=72502;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='...으아아아아아아아!!!', `MaleText_loc4`='……啊啊啊啊！！！', `MaleText_loc5`='...啊啊啊啊啊啊!!!', `MaleText_loc7`='... ¡¡¡AAAAAAAGH!!!' WHERE `ID`=72503;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수많은 임프! 한 번 상대해 봐라!', `MaleText_loc4`='好多小鬼！快解决他们！', `MaleText_loc5`='好多小鬼!給我處理掉!', `MaleText_loc7`='¡Muchos diablillos! ¡Encárgate!' WHERE `ID`=72504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신의 악마 지배를 삼킵니다!', `MaleText_loc4`='%s吞噬你的奴役恶魔！', `MaleText_loc5`='%s吞噬了你的奴役惡魔!', `MaleText_loc7`='¡%s devora tu Esclavizar demonio!' WHERE `ID`=72505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벌레들이 여기가 어딘지도 모르는구나. 가라잘, 이런 미천한 녀석들에게 네 "힘"을 보여주고 싶다면, 마음대로 해라.', `MaleText_loc4`='这些不自量力的爬虫。戈拉亚，要是你想用这些废物来证明“实力”，那我也无所谓。', `MaleText_loc5`='卡拉賈，你若是想靠欺凌這些不知天高地厚的雜碎弱者來證明己身之「力」...那就隨你吧...', `MaleText_loc7`='Estos insectos no saben cuál es su lugar, Gara''jal. Si quieres poner a prueba tu "poder" con débiles como estos, a mí no me importa.' WHERE `ID`=72506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 내 어전에서 쓰레기를 치웠구나. 지켜볼 만한 가치가 있겠어.', `MaleText_loc4`='这么说，你们帮我处理了门口的垃圾。我想我还得说声谢谢。', `MaleText_loc5`='所以你把我門口的垃圾清掉了。看來值得我正眼瞧瞧。', `MaleText_loc7`='Así que se deshicieron de esa escoria. Quizás merezcan mi atención.' WHERE `ID`=72507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 건방진 짓거리도 여기서 끝이다. 내 요새에는 누구도 들어갈 수 없다. 네놈들의 뼈로 이 다리를 다시 짓겠다.', `MaleText_loc4`='但也只能到此为止了。你们以为我会让你们长驱直入吗？这座桥还可以重建，可你们的骨头…哼…', `MaleText_loc5`='但你們的犯上之行就此為止，莫想我會容忍你們長驅直入。我會拆了你們骨頭來重建這座橋!', `MaleText_loc7`='Pero su allanamiento termina aquí. Nadie entrará a mi fortaleza prohibida. Reconstruiré este puente con sus huesos.' WHERE `ID`=72508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너! 네놈들이 내 분노를 샀다. 너희를 본보기로 삼아, 내 힘을 겁내는 자들이 전율하며 복종하게 만들어 주마.', `MaleText_loc4`='你们！你们激怒我了。我要拿你们做个榜样，让所有仰望我力量的人颤抖臣服。', `MaleText_loc5`='你!你們讓我發怒了。我會拿你們來做榜樣，讓其他人一看到我的力量就在顫抖中投降。', `MaleText_loc7`='¡Ustedes! Acaban de provocar mi ira. Servirán de ejemplo para que todos los que contemplen mi poder tiemblen y se sometan.' WHERE `ID`=72509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 레이 션, 왕과 신을 살해한 자다. 너희는 지금 크게 실수하는 거다.', `MaleText_loc4`='吾乃雷神，弑君之君，诛神之神。你们犯了一个可悲的错误。', `MaleText_loc5`='我是雷神，諸神與諸王的殺戮者。你們犯下了大錯。', `MaleText_loc7`='Soy Lei Shen, asesino de reyes y dioses. Han cometido un grave error.' WHERE `ID`=72510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무릎 꿇어라!', `MaleText_loc4`='跪下！', `MaleText_loc5`='跪下!', `MaleText_loc7`='¡Arrodíllense!' WHERE `ID`=72511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽어라!', `MaleText_loc4`='去死吧！', `MaleText_loc5`='死吧!', `MaleText_loc7`='¡Mueran!' WHERE `ID`=72512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복종하라!', `MaleText_loc4`='屈服吧！', `MaleText_loc5`='快投降!', `MaleText_loc7`='¡Sométanse!' WHERE `ID`=72513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개여, 내 적을 쫓아라!', `MaleText_loc4`='闪电，找到我的敌人！', `MaleText_loc5`='雷電，尋找我的敵人!', `MaleText_loc7`='¡Relámpago, busca a mis enemigos!' WHERE `ID`=72514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바람이여, 내 부름에 응하라!', `MaleText_loc4`='狂风，响应我的召唤！', `MaleText_loc5`='風啊，傾聽我的呼喚!', `MaleText_loc7`='¡Viento, acude a mi llamada!' WHERE `ID`=72515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 힘을 막을 수 있겠느냐!', `MaleText_loc4`='我的力量无可匹敌！', `MaleText_loc5`='別想抑制我的力量!', `MaleText_loc7`='¡Mi poder no se puede contener!' WHERE `ID`=72516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 파멸은 결정되었다!', `MaleText_loc4`='你们这是自掘坟墓！', `MaleText_loc5`='哈，你們的末日已定!', `MaleText_loc7`='¡Acaban de firmar su sentencia!' WHERE `ID`=72517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 성소에서 내게 도전하려는 거냐? 어리석기 짝이 없구나!', `MaleText_loc4`='你们想在我的圣殿内挑战我？认清你们的愚蠢吧！', `MaleText_loc5`='你們想在我的聖所中挑戰我?見證自己的愚蠢吧!', `MaleText_loc7`='¿Me están desafiando en mi propio sagrario? ¡Paguen por su estupidez!' WHERE `ID`=72518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 내가 직접 널 부숴주마. 번개를 어떻게 상대하는지 보자.', `MaleText_loc4`='呸！我要亲自动手。看看你们要怎么抗衡闪电吧。', `MaleText_loc5`='哼!我還是自己來吧。讓我們看看你怎麼應付雷電。', `MaleText_loc7`='¡Bah! Los aplastaré yo mismo. A ver cómo se las arreglan contra el trueno.' WHERE `ID`=72519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 미물들아! 나는 창공의 힘을 부린다!', `MaleText_loc4`='你们一无是处！我掌握着苍穹的力量！', `MaleText_loc5`='米粒之珠，也敢與日月爭輝!', `MaleText_loc7`='¡No son NADA! ¡Yo controlo el poder de los cielos!' WHERE `ID`=72520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼! 넌 가치 없는 존재다! 나... 나는... 천둥왕이다!', `MaleText_loc4`='不！你们这些废物！我……是……雷电之王！', `MaleText_loc5`='不!你們只是螻蟻!我可...是雷霆之王...!', `MaleText_loc7`='¡NO! ¡Son INDIGNOS! ¡YO... SOY... EL REY DEL TRUENO!' WHERE `ID`=72521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그저... 신들의 일을 마무리하려 했는...', `MaleText_loc4`='我只想完成……诸神的任务……', `MaleText_loc5`='我只是想要完成...眾神的...旨意...', `MaleText_loc7`='Solo quería terminar... la obra de los dioses...' WHERE `ID`=72522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지긋지긋하군!', `MaleText_loc4`='够了！', `MaleText_loc5`='夠了!', `MaleText_loc7`='¡Ya basta!' WHERE `ID`=72523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보잘것없군.', `MaleText_loc4`='不值一提。', `MaleText_loc5`='微不足道。', `MaleText_loc7`='Insignificante.' WHERE `ID`=72524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가치 없는 것.', `MaleText_loc4`='废物。', `MaleText_loc5`='廢材一個。', `MaleText_loc7`='Indigno.' WHERE `ID`=72525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최후의 심판이다.', `MaleText_loc4`='这就是我的判决。', `MaleText_loc5`='我的裁決已定!', `MaleText_loc7`='Mi juicio es final.' WHERE `ID`=72526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개를 맞이하라.', `MaleText_loc4`='闪电一击。', `MaleText_loc5`='疾電索命!', `MaleText_loc7`='El relámpago impacta.' WHERE `ID`=72527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 앞에 무릎을 꿇어라!', `MaleText_loc4`='跪下吧！', `MaleText_loc5`='屈膝求饒吧!', `MaleText_loc7`='¡Arrodíllense ante mí!' WHERE `ID`=72528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:135096|h[천둥충격]|h|r에 의해 목숨을 잃었습니다. 천둥이 떨어지는 지점에서 멀어지면, 받는 피해가 줄어듭니다.', `MaleText_loc4`='你被|cFFFF0000|Hspell:135096|h[雷霆打击]|h|r杀死了。远离冲击点可降低所受伤害。', `MaleText_loc5`='你被|cFFFF0000|Hspell:135096|h[雷擊]|h|r殺死了。遠離命中點以減少所受的傷害。', `MaleText_loc7`='|cFFFF0000|Hspell:135096|h[Atronado]|h|r te ha matado. Aléjate del punto de impacto para reducir el daño sufrido.' WHERE `ID`=72529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 색다른 곳입니다. 이곳에는 분명 다양한 동물들과 야수들이 살고 있겠지요. 게다가 모두 재미있게도 몸에서 전기가 튈 테고요.', `MaleText_loc4`='多么奇特的地方。我敢肯定，我们一定能在这里发现许多珍禽猛兽，而且每一只都浑身带电。真可爱！', `MaleText_loc5`='真是個奇特的大地。我肯定這裡可以一定充滿各式各樣的動物與野獸。還有牠們身上傳來的悅耳電擊聲。', `MaleText_loc7`='Qué tierra tan exótica. Estoy seguro de que debe de haber una colección de animales y bestias por descubrir aquí. Y todos con esas maravillosas descargas eléctricas emanando de sus cuerpos.' WHERE `ID`=72530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 사로잡은 표본은 정말 흥미롭습니다. 지금은 우리 하인들을 감전시키지 않도록 훈련시키고 있지요. 아직 새끼라서 그런 행동을 하는 것도 당연하지만 말입니다.$b$b고맙게도 저기 있는 태양길잡이가 녀석의 장난 때문에 다친 이들을 치유하는 데 기꺼이 도움을 주었습니다.$b$b참, 또 실례를 무릅쓰고 당신의 작은 생물에게 제가 이름을 붙였지요.', `MaleText_loc4`='你捕捉到了一个非常可喜的标本。我一直在教它不要电击我们的雇员。但它还是个小宝宝，这种行为在幼年期是无法避免的。$b$b多亏了那边的烈日行者帮忙，恶作剧的受害者们都得到了妥善的治疗。$b$b噢，我还冒昧地给你的小家伙起了一个名字。', `MaleText_loc5`='你抓到的樣本真是好。我一直在教牠不要電擊我們的僕人。雖然牠年紀還小，小時候有這種行為是可以預料的。', `MaleText_loc7`='Qué espécimen tan maravilloso has capturado. Le he estado enseñando a no electrocutar a nuestros sirvientes. Pero no es más que una cría, y este comportamiento es normal para su edad.$b$bPor suerte, el caminasol de ahí ha ayudado mucho a la hora de curar a los heridos por estas travesuras.$b$bAh, y me he tomado la libertad de ponerle un nombre.' WHERE `ID`=72531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 생물이 자라는 속도는 정말 놀라울 따름입니다. 처음에는 치즈를 먹여 보았는데 짜증만 내더군요.$b$b그런데 동네의 염소를 먹였더니 덩치가 급격히 커지기 시작했어요.$b$b식탐이 많은 생물인 건 확실합니다.', `MaleText_loc4`='这家伙的生长速度叫我震惊。我们一开始想喂它吃奶酪，结果却惹恼了它。$b$b但当我们改喂当地的山羊后，它就开始疯长。$b$b真是一个贪吃的家伙。', `MaleText_loc5`='這個生物長得這麼快，讓我很驚訝。起初餵牠吃起司只會讓牠很不高興。$b$b可是後來我們餵牠吃本地的山羊，牠就越長越大。$b$b可以確定的是，牠的食量很大。', `MaleText_loc7`='Estoy asombrado con la velocidad a la que crece esta criatura. Al principio, la dieta a base de queso irritaba al animal.$b$bEntonces comenzamos a darle cabras locales para comer, y desde entonces no hace más que crecer.$b$bEs una criatura de lo más voraz.' WHERE `ID`=72532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하늘에서 떨어지고 있는 온갖 괴물들의 송장 중 하나에서 안장과 고삐를 발견했습니다.$b$b광을 조금 내고 마법을 살짝 곁들이면... 짠, 새것 같지요!', `MaleText_loc4`='我们从被击落的各种野兽尸体上找到了一副鞍座和笼头。$b$b只要好好擦一擦，再加上一点小魔法，然后“嗖”的一声……它就跟新的一样了！', `MaleText_loc5`='我們從天空射下來的各種動物屍體身上找到了一組鞍具。$b$b只要施點魔法、修理打點一下...就跟新的一樣!', `MaleText_loc7`='Hemos encontrado una silla y un arnés en uno de los cadáveres de las bestias aniquiladas en el cielo.$b$bUn poco de limpieza, un poco de magia, y listo... ¡Como nuevos!' WHERE `ID`=72533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천공의 대장장이가 죽어갑니다!', `MaleText_loc4`='天界工匠已经濒临死亡！', `MaleText_loc5`='星穹鐵匠快死了!', `MaleText_loc7`='El herrero celestial está a punto de morir.' WHERE `ID`=72534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천공의 수호병이 죽어갑니다!', `MaleText_loc4`='天界防御者已经濒临死亡！', `MaleText_loc5`='星穹防禦者快死了!', `MaleText_loc7`='El defensor celestial está a punto de morir.' WHERE `ID`=72535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천공의 수호병이 |cFFFF2222|Hspell:140068|h[치유의 힘]|h|r의 영역을 생성합니다!', `MaleText_loc4`='天界防御者为一片区域注入了|cFFFF2222|Hspell:140068|h[治疗能量]|h|r！', `MaleText_loc5`='星穹防禦者釋放出範圍性的|cFFFF2222|Hspell:140068|h[治療能量]|h|r!', `MaleText_loc7`='¡El defensor celestial crea un área de |cFFFF2222|Hspell:140068|h[energía sanadora]|h|r!' WHERE `ID`=72536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으하하, 여기 좀 보게, 친구!$b$b그립타가 다시 돌아왔다고! 새 상점에 새 상품을 쫙 깔고 장사할 준비를 마쳤지!$b$b산에 올라간다고? 그 냄새 지독한 "복덩이"를 살텐가? 그루멀들은 무시하고 내게 오게. 자네의 오랜 친구 그립타를 믿어 보시게나.$b$b이 신비한 물건들을 반값도 안 되는 가격에 주도록 하지!', `MaleText_loc4`='“啊哈哈，快来看呐，伙计们！$b$b格里伏塔又回来啦！新的摊位，崭新的商品，已经做好开张营业的准备啦！$b$b想在山里更加走运吗？想要购买最好闻的“幸运符”吗？那就快过来看看吧，别跟土地精们磨叽了。只要来找你的老朋友格里伏塔就对了。$b$b这些神奇的小玩意绝对物超所值！”', `MaleText_loc5`='啊哈，照過來照過來，老兄!$b$b格利夫塔又回來啦!嶄新的攤位，全新的貨品，任君選購!$b$b要買比山高的好運嗎?要買你聞過最棒的「幸運星」嗎?來喔來喔，別理那些咕嚕摩囉，來找老朋友格利夫塔就對了$b$b快靠過來看看唷!絕對物超所值!', `MaleText_loc7`='¡Ja, ja, ja, aquí me tienes todo pa'' ti, colega!$b$b¡Griftah ha vuelto! Nuevo pueh''to, mercancía totalmente novedosa y dih''pueh''to a ofreceh''te las mejores ofeh''tas!$b$b¿Quieres tener más sueh''te en las montañas? ¿Quieres comprar el mejor "grisgrís" que has olido en tu vida? Pues entra ya, y no se te ocurra hablar con los grúmel. Tu viejo amigo Griftah se ocupará de ti.$b$b¡Eh''tos amuletos milagrosos seguirían siendo baratos incluso si triplico el precio!' WHERE `ID`=72537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 약초나 향료 따위가 산에서 행운을 가져다 준다고? 하하! 자네는 제대로 된 사람이랑 거래를 해야 할걸세, 친구. 이리 와서 행운의 부적 하나 장만하지 않겠나?', `MaleText_loc4`='你觉得这些草药和昂贵的熏香能在山里给你带来好运气？哈哈！那你可找错人了，伙计。快来买一把货真价值的幸运锁吧！', `MaleText_loc5`='你已為這些藥草和燻香可以在山裡給你帶來好運?哈哈!你找錯人做買賣啦，老兄。來跟我買個真正的幸運鎖!', `MaleText_loc7`='¿Crees que esas hierbas y esos inciensos te van a dar sueh''te en la montaña? ¡Ja, ja! Has estado haciendo negocios con el colega equivocado, colega. ¡Ven, te proporcionaré un verdadero amuleto!' WHERE `ID`=72538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그립타, 그것들이 복덩이라고 생각하세요? 오히려 안복덩이에 가까운 냄새군요.', `MaleText_loc4`='格里伏塔，你说那些是幸运符？它们闻上去更像倒霉符。', `MaleText_loc5`='格利夫塔，你覺得這些是幸運星?它們聞起來像厄運星。', `MaleText_loc7`='¿Griftah, crees que esos son grisgrís? A mí me huelen más a lo contrario.' WHERE `ID`=72539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그립타, 당신은 코가 너무 뾰족해서 복 냄새를 못 맡을 것 같아요. 게다가 당신한테선 안 씻은 야크 같은 냄새가 난다고요.', `MaleText_loc4`='格里伏塔，你的鼻子太尖了，根本闻不到好运的味道。而且你自己闻上去就像一头没有洗过的牦牛。', `MaleText_loc5`='格利夫塔，你的鼻子太尖了，聞不出好運。而且你聞起來像隻沒洗澡的犛牛。', `MaleText_loc7`='Griftah, tienes la nariz demasiado puntiaguda para oler la buena fortuna. Y hueles a yak desaseado.' WHERE `ID`=72540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌들한테는 당신 같은 트롤에 대한 전설이 많아요, 그립타. 정말 많아요.', `MaleText_loc4`='熊猫人有很多关于你这种巨魔的传说，格里伏塔。真的有很多。', `MaleText_loc5`='格利夫塔，熊貓人有許多關於你這種食人妖的傳說。許許多多的傳說。', `MaleText_loc7`='Los pandaren tienen muchas leyendas sobre los trols como tú, Griftah. Muchas.' WHERE `ID`=72541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐요! 그립타! 그건 내 복덩이잖아요! 어디서 났어요?', `MaleText_loc4`='嘿！格里伏塔！那个幸运符是我的！你从哪里弄来的？', `MaleText_loc5`='嘿，格利夫塔!那是我的幸運星!你從哪裡拿到的?', `MaleText_loc7`='¡Eh! ¡Griftah! ¡Ese es uno de mis grisgrís! ¿De dónde lo has sacado?' WHERE `ID`=72542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런데 내 친구들은 나더러 냄새가 너무 지독하대요. 친구들한테 당신을 소개시켜 줘야겠어요, 그립타.', `MaleText_loc4`='“想想吧，我的朋友们总说我太爱‘说大话’。我真该把你介绍给他们，格里伏塔。”', `MaleText_loc5`='嘿，格利夫塔，那天我朋友跟我說，有十個人妖組了個新樂團，團名就叫「十人妖」。', `MaleText_loc7`='Y pensar que mis amigos dicen que hago demasiado el "trol". Tengo que presentártelos, Griftah.' WHERE `ID`=72543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 무슨 냄새죠? 이게 무슨 냄새냐고요?! 혹시 당신한테서 나는 냄샌가요, 그립타? 어떻게 그런 냄새를 풍길 수 있죠? 정말 역겹네요. 정말 역겨워요.', `MaleText_loc4`='那是什么味道？那是什么味道？！是你吗，格里伏塔？你怎么搞得那么臭？这真是太讨厌了。没错，最讨厌了。', `MaleText_loc5`='那是什麼味道?那是什麼味道?格利夫塔，是你的味道嗎?你怎麼有辦法臭成這副德性?這難聞到極點了。沒錯，難聞到極點了。', `MaleText_loc7`='¿A qué huele? ¡¿A qué huele?! ¿Eres tú, Griftah? ¿Cómo puedes oler así? Esto es una ofensa. Una gran ofensa, ya lo creo.' WHERE `ID`=72544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 그루멀들은 아주 마음에 드는군. 풍채도 괜찮고 말이야.$b$b그런고로 내가 특별하게 이 물건을 팔아주겠네. 이름하야 "복덩이 피리"! 행운이 깃든 선율을 연주한다는 바로 그 악기일세.', `MaleText_loc4`='“你们土地精都是输得起的人。我喜欢这样。$b$b所以，我愿意把这支‘幸运卡祖笛’卖给你，它能吹奏出最幸运的乐曲。”', `MaleText_loc5`='你們咕嚕摩真有趣，講的話還挺逗我開心的。$b$b所以呢，我願意忍痛讓出這個「幸運卡祖笛」，能吹出超幸運的音樂!', `MaleText_loc7`='Ustedes los grúmel sois simpáticos. Me guh''ta vueh''tro rollo.$b$bPor eso eh''toy dih''pueh''to a dah''te eh''te "chiflato grisgrís" que creará música muy afoh''tunada.' WHERE `ID`=72545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고급형 "복고삐" 없이는 야크를 타고 산에 가선 안 돼. 미친 짓이나 다름없지! 내가 아주 싸게 팔아 줄게.', `MaleText_loc4`='“你可不能连骨质‘幸运缰绳’都不用，就这么骑着牦牛进山！这根本就是在发疯！让我便宜卖给你几根吧。”', `MaleText_loc5`='沒有戴這個「幸運鍊」就騎髦牛上山是不行的!太瘋狂了!我可以算你便宜一點。', `MaleText_loc7`='No puedes montar en yak en las montañas sin un "chiripotra" bonificado. ¡Es una locura! Yo te vendo uno barato.' WHERE `ID`=72546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈 냄새를 찾고 있어? 나랑 빌지워터에 가서 노름판에서 돈 좀 벌어 보는 게 어때?', `MaleText_loc4`='这么说你正在寻找发财的机会？跟我去锈水港怎么样，我们可以在赌桌上好好赚一笔。', `MaleText_loc5`='你聞到幸運的味道了嗎?要不要跟我去污水哥布林的賭桌去大贏幾把。', `MaleText_loc7`='Así que hueles la buena foh''tuna, ¿eh? ¿Qué te parece si vamos a Pantoque y probamos fortuna en las mesas de apueh''tas?' WHERE `ID`=72547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이, 왜 그러는가! 분명 내가 밑지는 장사라네, 이 킁킁대는 녀석들 같으니.', `MaleText_loc4`='啊，来吧！这绝对是笔好买卖，你只要一闻就知道。', `MaleText_loc5`='啊，拜託!這個買賣是真的，你知道的。', `MaleText_loc7`='¡Oh, vamos! ¡Es un buen trato y lo sabes, olisqueador!' WHERE `ID`=72548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 성급하게 판단하지 말고, 응? 이 장신구가 바로 자네가 찾던 물건이란 말이야.', `MaleText_loc4`='别那么快下结论，好吗？这个小玩意儿绝对就是你在找的东西，伙计。', `MaleText_loc5`='別太快下結論好嗎?這個小東西正是你要找的。', `MaleText_loc7`='No te equivoques, ¿vale? Eh''te amuleto es juh''to lo que buh''cas, oledor.' WHERE `ID`=72549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 왔구나. 준비되면 말해라.', `MaleText_loc4`='很好！你来了。准备好就告诉我一声。', `MaleText_loc5`='很好，你來了。等你準備好開始就跟我說。', `MaleText_loc7`='¡Muy bien! Ya llegaste. Habla conmigo cuando quieras comenzar.' WHERE `ID`=72550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우선 네가 가져온 트릴리움을 정제해야 한다.', `MaleText_loc4`='先把你带来的延极矿精炼一下。', `MaleText_loc5`='你帶給我的延齡石必須先煉過之後才能發揮作用。', `MaleText_loc7`='Hay que refinar el trillium que me trajiste para poder utilizarlo.' WHERE `ID`=72551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가열로면 될 것이다. 거푸집 조작을 도와 다오.', `MaleText_loc4`='这个铸造机应该能用。帮我操作模具吧。', `MaleText_loc5`='這個鑄造廠應該堪用。協助我操縱模子。', `MaleText_loc7`='Esta fundición bastará. Ayúdame a preparar los moldes.' WHERE `ID`=72552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 주의를 끌면, 싸울 각오도 해야 한다.', `MaleText_loc4`='万一引发骚动，你要做好战斗准备。', `MaleText_loc5`='如果引來注意，要準備好進行戰鬥。', `MaleText_loc7`='Prepárate para luchar si llamamos la atención.' WHERE `ID`=72553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='귀찮은 놈들을 없애 주겠나?', `MaleText_loc4`='解决那些乌合之众吧。', `MaleText_loc5`='清掉那些烏合之眾好嗎?', `MaleText_loc7`='Encárgate de los intrusos, ¿quieres?' WHERE `ID`=72554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='집중해야 한다. 가열로를 지켜 다오!', `MaleText_loc4`='我得集中精神。不能受到打扰！', `MaleText_loc5`='我不能分心。淨空鑄造廠!', `MaleText_loc7`='Tengo que concentrarme. ¡Despeja la fundición!' WHERE `ID`=72555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하구나! 재료는 준비됐다. 따라 오거라.', `MaleText_loc4`='好！材料准备好了。跟我来。', `MaleText_loc5`='很好!材料準備好了。跟我來。', `MaleText_loc7`='¡Excelente! Los materiales están listos. Sígueme.' WHERE `ID`=72556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매우 흥미롭군! 이 제련소는 고대의 티탄 기계 위에 건설되었다. 레이 션, 그대는 실로 영리한 폭군이었구나!', `MaleText_loc4`='有意思！这个熔炉建在了远古泰坦仪器上。雷神，你真是个聪明的暴君！', `MaleText_loc5`='真有趣!這個熔爐是建造在泰坦機械上的。雷神你啊，還真是個聰明的暴君呢!', `MaleText_loc7`='¡Qué interesante! Esta forja se levantó sobre maquinaria titánica. Lei Shen, ¡eres un tirano muy listo!' WHERE `ID`=72557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 드워프였다면 아무 단추나 막 눌렀겠지. 하지만 우리는 목적이 있어서 온 것이다.', `MaleText_loc4`='现在，我可不会像个矮人那样乱搞一气。我们是有备而来的。', `MaleText_loc5`='如果我是矮人的話，現在就會毫無來由的亂按按鈕。但我們今天可是有個明確的目標。', `MaleText_loc7`='Si fuera un enano, ahora estaría pulsando botones a lo loco. Pero nosotros tenemos un propósito.' WHERE `ID`=72558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 제련소를 작동시킬 테니 뒤를 봐 다오. 용들은 날 때부터 티탄어를 이해할 수 있다는 걸 아느냐? 물론 그들의 "위대한 계획"의 일부겠지.', `MaleText_loc4`='我要激活熔炉了，掩护我。知道吗？巨龙天生就懂得泰坦语。这无疑也是他们“绝佳设计”的一部分。', `MaleText_loc5`='在我啟動熔爐的時候保護我。你知道龍一出生就能懂泰坦的語言嗎?這一定是他們「偉大設計」的一部分。', `MaleText_loc7`='Cúbreme mientras activo la forja. ¿Sabías que todos los dragones nacemos sabiendo el idioma de los titanes? Seguro que formaba parte de su "gran plan".' WHERE `ID`=72559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이것 좀 봐라. 세상을 창조할 힘을 지녔으니, 제국을 건설하는 것쯤은 레이 션에게 일도 아니었겠지.', `MaleText_loc4`='快看。难怪雷神这么轻易就建立起了一个帝国，他掌握了创世之力。', `MaleText_loc5`='看啊。雷神建立帝國的過程一定很簡單，他手上的力量足以創造好幾個世界。', `MaleText_loc7`='Ya está. Qué fácil debió de resultarle a Lei Shen levantar un imperio; dominaba un poder capaz de crear mundos.' WHERE `ID`=72560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방해되는 것을 없애 다오. 난 지금 집중해야 한다.', `MaleText_loc4`='别让我分心。我得集中精神。', `MaleText_loc5`='麻煩你把小嘍囉處理一下。我需要專心弄這個。', `MaleText_loc7`='Hazme el favor de alejar las distracciones. Necesito concentrarme.' WHERE `ID`=72561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련소를 지켜라!', `MaleText_loc4`='保护熔炉！', `MaleText_loc5`='保護熔爐!', `MaleText_loc7`='¡Protege la forja!' WHERE `ID`=72562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"보안 체계"라? 우습군. 티탄은 왜 이 멋진 장난감들을 숨기지 못해 안달이었지?', `MaleText_loc4`='“安全协议”？荒唐。泰坦为何总是热衷于把好东西藏起来？', `MaleText_loc5`='「安全協定」?真荒謬。泰坦為什麼這麼拼命要把他們奇妙的玩具藏起來呢?', `MaleText_loc7`='¿"Protocolo de seguridad"? Es absurdo. ¿Por qué ponían los titanes tanto empeño en ocultar sus juguetes?' WHERE `ID`=72563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신들 티탄 때문에 분통이 터지는군. 나는 더 큰 선을 위해 움직이는 거란 말이다.', `MaleText_loc4`='你们泰坦激怒我了。我这么做是为了更重要的目的。', `MaleText_loc5`='你們這些泰坦讓我真火大。我是為了正義而行動的。', `MaleText_loc7`='Titanes, me sacan de mis casillas. Estoy haciendo esto en nombre del bien común.' WHERE `ID`=72564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것들을 조용히 시켜라. 나는 할 일이 있다.', `MaleText_loc4`='帮我个忙，让他们闭嘴。我还有别的事要做。', `MaleText_loc5`='幫個忙，讓那些東西安靜點。不然我很難專心。', `MaleText_loc7`='¿Te importaría callar a esas cosas? Estoy un poco ocupado.' WHERE `ID`=72565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다행히 나는 보안을 해제할 수 있지. 내가 없으면 어쩌겠느냐, 응?', `MaleText_loc4`='幸好我解除了警报。要没有我的话你该怎么办，嗯？', `MaleText_loc5`='幸運的是我可以解除安全系統。要是沒有我你怎麼辦呢，嗯?', `MaleText_loc7`='Menos mal que puedo desactivar la seguridad. ¿Qué harías tú sin mí?' WHERE `ID`=72566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분명 쉬운 길이 있을 텐데… 엇. 하하, 그럼 그렇지!', `MaleText_loc4`='肯定有更简单的办法——噢。哈！好了！', `MaleText_loc5`='一定還有更簡單的方法 - 喔。啊，就是這樣!', `MaleText_loc7`='Tiene que haber una forma más fácil... ¡Ah! ¡Eso es!' WHERE `ID`=72567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오오, 봐라!', `MaleText_loc4`='噢，快看！', `MaleText_loc5`='噢，看看這個!', `MaleText_loc7`='¡Uh! ¡Mira eso!' WHERE `ID`=72568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구는 자원을 조금밖에 활용하지 못했다. 천둥왕처럼 꾀가 있었던 자는 거의 없었던 모양이야.', `MaleText_loc4`='魔古族只使用了一小部分可调动的资源。很少有人能像雷电之王那么狡猾。', `MaleText_loc5`='魔古只用了他們手上資源的一小部分。他們當中很少有像雷王這麼聰明的人。', `MaleText_loc7`='Los mogu solo utilizaron una parte de los recursos de los que disponían. Solo unos cuantos fueron tan astutos como el Rey del Trueno.' WHERE `ID`=72569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐지... "이상 물체 발견"이라. 이상 물체?', `MaleText_loc4`='什么——“发现异常。”异常？', `MaleText_loc5`='這是什麼...「偵測到異常活動」。異常?', `MaleText_loc7`='¿Qué es esto? "Anomalía detectada". ¿Anomalía?' WHERE `ID`=72570;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봐라. 고대의 티탄 기술이 마치 자석같이 샤를 끌어들이는구나.', `MaleText_loc4`='看。这种古代泰坦技术会像磁石一样吸引煞魔。', `MaleText_loc5`='你看看，這個古老的泰坦科技就像吸引煞的磁鐵一樣。', `MaleText_loc7`='Mira. Esta tecnología titánica antigua atrae a los sha como un imán.' WHERE `ID`=72571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 샤 처치에는 전문가겠지. 말끔히 처리해라!', `MaleText_loc4`='你可是对付煞魔的专家。快去解决它们！', `MaleText_loc5`='你現在可以說是消滅煞的專家了。把他們清一清吧!', `MaleText_loc7`='Ya eres toda una autoridad en esto de matar sha. ¡Limpia este desastre!' WHERE `ID`=72572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 제련소는 주위의 땅에서 동력을 끌어온다. 놀랍구나! 한때는 이 섬 전체가 영원꽃 골짜기 같았던 게 아닐까?', `MaleText_loc4`='熔炉从周围的土地中抽取力量。太神奇了！我怀疑这座岛曾经也像锦绣谷一样繁华似锦。', `MaleText_loc5`='熔爐會從附近的土地抽取能量。太驚人了!我懷疑這整座島本來跟恆春谷一樣。', `MaleText_loc7`='La forja extrae su poder de la tierra circundante. ¡Fascinante! Sospecho que antaño toda esta isla era tan hermosa como el Valle de la Flor Eterna.' WHERE `ID`=72573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 싸워라. 나는 기적을 행하고 있으니까.', `MaleText_loc4`='加把劲。我正在创造奇迹。', `MaleText_loc5`='繼續加油。我就快創造出奇蹟了。', `MaleText_loc7`='Tú sigue así. Yo estoy haciendo milagros.' WHERE `ID`=72574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭해! 가열로를 지켜라. 거의 다 됐다.', `MaleText_loc4`='干得好！保护熔炉——我就快完成了。', `MaleText_loc5`='做得好!保護熔爐 - 我快要完成了。', `MaleText_loc7`='¡Un trabajo excelente! Protege la forja. Ya casi termino.' WHERE `ID`=72575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아무래도 너무 위험해. 나중에 다시 해야겠다!', `MaleText_loc4`='糟糕——好险呐。我们稍后再试一次！', `MaleText_loc5`='這樣不行 - 太危險了。我們待會再試一次!', `MaleText_loc7`='Esto no se ve bien. ¡Demasiado peligroso! Volveremos más tarde.' WHERE `ID`=72576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련소가 장악당했다! 여길 떠야 한다!', `MaleText_loc4`='熔炉被占领了！我们离开这儿！', `MaleText_loc5`='整個熔爐快被淹沒了!我們必須離開!', `MaleText_loc7`='¡Tomaron la forja! ¡Tenemos que irnos!' WHERE `ID`=72577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼, 안 돼, 안 돼! 이렇게는 안 된다. 어서 여기를 벗어나자.', `MaleText_loc4`='不不不——这完全不对。我们快离开这儿。', `MaleText_loc5`='不，不，不 - 這樣不行。我們離開這裡吧。', `MaleText_loc7`='No, no, no. Esto no va nada bien. ¡Salgamos de aquí!' WHERE `ID`=72578;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 완성이다. 우리가 걸작을 벼려 냈다!', `MaleText_loc4`='好！完成了——我们铸造了一件杰作！', `MaleText_loc5`='搞定!我們的工作完成了。我們打造出一個無比的傑作!', `MaleText_loc7`='¡Ya está! Nuestro trabajo ha terminado. Hemos forjado una obra maestra.' WHERE `ID`=72579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기서 할 일은 끝났지만, 이제 무기를 담금질해야겠다.', `MaleText_loc4`='这里的任务完成了，可武器还没有淬火。', `MaleText_loc5`='我們完成了，但是這把武器還沒有經過淬鍊。', `MaleText_loc7`='Ya terminamos aquí, pero aún hay que templar el arma.' WHERE `ID`=72580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭풍 군주가 살아 있는 동안 창을 그의 심장에 찔러 넣어야 한다.', `MaleText_loc4`='你得在暴风领主活着时，将长矛刺入他的心脏。', `MaleText_loc5`='你必須在風暴龍王還活著的時候把矛刺進他的心臟。', `MaleText_loc7`='Debes clavar la lanza en el corazón del Señor de la Tormenta mientras esté vivo.' WHERE `ID`=72581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해라! 창이 놈의 살갗을 뚫는 순간, 놈의 힘이 너를 덮칠 테니.', `MaleText_loc4`='注意！当长矛刺穿他的外皮时，你会受到他的反击。', `MaleText_loc5`='但請小心!在刺穿他的鱗片那瞬間，你會被他體內的力量反噬。', `MaleText_loc7`='¡Ten cuidado! En cuanto atravieses su piel, se irá sobre ti con todo su poder.' WHERE `ID`=72582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='괴물을 쓰러뜨리기 직전에 창을 던져야만 한다. 그보다 빨라서도 늦어서도 안 된다!', `MaleText_loc4`='你得在杀死那头野兽前掷出长矛，这很重要。不能太早，也不能太晚！', `MaleText_loc5`='重點在於殺死他的那一瞬間把矛丟出去。不能太早!也不能太晚!', `MaleText_loc7`='Es importante arrojar la lanza justo antes de matar a la bestia. ¡Ni un momento antes! ¡Ni un momento después!' WHERE `ID`=72583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 본토에서 준비할 게 있다. 내게 필요한 것을 가지고 장막의 계단으로 오거라.', `MaleText_loc4`='我得返回大陆了。等你拿到我需要的东西，再来雾纱栈道找我吧。', `MaleText_loc5`='我必須回到大陸上進行準備。等你有了我需要的東西時，回到朦朧天梯找我。', `MaleText_loc7`='Tengo preparativos que atender en el continente. Ve a verme a la Escalera Velada cuando tengas lo que necesito.' WHERE `ID`=72584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아 참, 죽지 말고.', `MaleText_loc4`='噢，你可别死了。', `MaleText_loc5`='噢還有，你可別死啊。', `MaleText_loc7`='Ah, y... no mueras.' WHERE `ID`=72585;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='업무와 관련된 불편사항이 있나요? 좋아요! 수사 비용으로 500 마카롱, 그리고 관계자들에게 보낼 뇌물로 300 마카롱을 지불하세요.', `FemaleText_loc4`='要登记工作投诉？很好！请先交纳五百杏仁币的调查费和三百杏仁币的杂费。', `FemaleText_loc5`='要提出跟工作相關的訴願嗎?太好了!調查費只要五百張大鈔、疏通費只要三百張大鈔。', `FemaleText_loc7`='¿Quiere registrar una queja relacionada con el trabajo? ¡Estupendo! Serán quinientos macarrones en tasas de investigación y trescientos macarrones para sobornos varios.' WHERE `ID`=72586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFF00000메가이라|r가 안개 속에서 나타납니다!', `MaleText_loc4`='|cFFF00000墨格瑞拉|r从迷雾中现身了！', `MaleText_loc5`='|cFFF00000梅賈拉|r從霧氣中現身了!', `MaleText_loc7`='|cFFF00000Megaera|r surge de la bruma.', `FemaleText_loc1`='|cFFF00000메가이라|r가 안개 속에서 나타납니다!', `FemaleText_loc4`='|cFFF00000墨格瑞拉|r从迷雾中现身了！', `FemaleText_loc5`='|cFFF00000梅賈拉|r從霧氣中現身了!', `FemaleText_loc7`='|cFFF00000Megaera|r surge de la bruma.' WHERE `ID`=72587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 조직은 오래 전부터 이 땅을 방랑하며, 도움이 필요한 이들에게 손길을 내밀었습니다. 레이 션의 시절부터, 우리 다섯 마술사들은 한 세대에서 다음 세대로 조직의 비밀을 전했습니다.', `MaleText_loc4`='我的组织在这片土地上游历多年，尽力帮助他人。自从雷神的时代至今，我们的成员一直保持在五人，将组织的秘密代代相传。', `MaleText_loc5`='長久以來，我的組織在這片大地上漫遊，盡可能提供協助。遠從雷神統治的年代，我們就有五個成員，將組織的秘密代代相傳。', `MaleText_loc7`='Mi orden lleva mucho tiempo recorriendo este lugar, proporcionando ayuda al que la necesita. Desde los tiempos de Lei Shen siempre ha habido cinco miembros que transmiten los secretos de nuestra orden de generación en generación.' WHERE `ID`=72588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 비밀 말씀이십니까?', `MaleText_loc4`='什么秘密？', `MaleText_loc5`='什麼秘密?', `MaleText_loc7`='¿Qué secretos?', `FemaleText_loc1`='어떤 비밀 말씀이세요?', `FemaleText_loc4`='什么秘密？', `FemaleText_loc5`='什麼秘密?', `FemaleText_loc7`='¿Qué secretos?' WHERE `ID`=72589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 말씀드리면... 비밀이라고 할 수가 없지 않겠습니까?', `MaleText_loc4`='如果我告诉了你……那它就不能称之为秘密了，明白吗？', `MaleText_loc5`='我如果告訴你...那就不是秘密了，對嗎?', `MaleText_loc7`='Si te lo dijese... dejarían de ser secretos, ¿no te parece?' WHERE `ID`=72590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다섯 마술사라고 하셨습니까?', `MaleText_loc4`='五名巫师？', `MaleText_loc5`='五位巫士?', `MaleText_loc7`='¿Cinco hechiceros?', `FemaleText_loc1`='다섯 마술사라고 하셨나요?', `FemaleText_loc4`='五名巫师？', `FemaleText_loc5`='五位巫士?', `FemaleText_loc7`='¿Cinco hechiceros?' WHERE `ID`=72591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제는 다른 마술사들이 어디에 있는지도 모르겠습니다. 마지막으로 서로를 본 것도 벌써 너무 오래전의 일입니다. 다른 이들은 모두 죽었는지도, 아니면 제자들이 그 자리를 차지했는지도 모릅니다. 여전히 다섯 마술사가 존재할 것이라고 믿을 수 밖에요...', `MaleText_loc4`='我不记得其他人去哪里了。我们真的已经很久没有见面了，其他人很可能已经死了，或者被他们的弟子取代了。我只能确信，我们还有五个人。', `MaleText_loc5`='我已經不記得其他人在哪裡了。距離我們上次會面已經過了太久，其他人很可能已經死了，或是被學徒繼承了他們的位子。我只能希望我們還有五個人健在。', `MaleText_loc7`='Ya no recuerdo dónde están los otros. De hecho, hace tanto tiempo que no nos vemos que los otros podrían perfectamente estar muertos, o podrían haberlos sustituido ya sus estudiantes. Pero tengo fe en que aún seamos cinco.' WHERE `ID`=72592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 것들! 내가 직접 보여 주지!', `MaleText_loc4`='蠢货！让我来给你们示范一下吧！', `MaleText_loc5`='蠢貨!讓我來示範給你看!', `MaleText_loc7`='¡NECIOS! ¡Yo les enseñaré cómo se hace!' WHERE `ID`=72593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴이 격렬하게 흔들립니다!', `MaleText_loc4`='洞穴剧烈地震动起来！', `MaleText_loc5`='洞穴劇烈地震動!', `MaleText_loc7`='¡La caverna se sacude violentamente!', `FemaleText_loc1`='동굴이 격렬하게 흔들립니다!', `FemaleText_loc4`='洞穴剧烈地震动起来！', `FemaleText_loc5`='洞穴劇烈地震動!', `FemaleText_loc7`='¡La caverna se sacude violentamente!' WHERE `ID`=72594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 속에서 고대 야수가 꿈틀댑니다!', `MaleText_loc4`='迷雾中出现了一头远古巨兽！', `MaleText_loc5`='有隻古老的巨獸在霧中騷動!', `MaleText_loc7`='¡Una bestia antigua se agita entre la bruma!', `FemaleText_loc1`='안개 속에서 고대 야수가 꿈틀댑니다!', `FemaleText_loc4`='迷雾中出现了一头远古巨兽！', `FemaleText_loc5`='有隻古老的巨獸在霧中騷動!', `FemaleText_loc7`='¡Una bestia antigua se agita entre la bruma!' WHERE `ID`=72595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 부모님께서는 세계의 분리 이전, 우리 고향의 머나먼 남쪽에서는 털이 북실북실한 종족이 산다고 말씀하셨습니다. 저는 그들을 단지 지능이 뛰어난 펄볼그 정도로 알았죠.$b$b하지만 제가 완전히 틀렸었군요. 그 분들이 이 광경을 볼 수 있었으면 좋았을 텐데.', `MaleText_loc4`='我的父母曾说过，在大分裂之前，在离我们家乡很遥远的南方居住着一个毛茸茸的奇怪种族。我一直以为他们说的是一种比较聪明的熊怪。$b$b现在我知道自己错得有多离谱了。真希望他们能活到今天，亲眼看看这一切。', `MaleText_loc5`='我的父母曾經提過一群在大爆炸之前，住在我們家鄉遙遠南方的毛茸茸奇怪生物。我一直以為他們說的是比較聰明的熊怪。$b$b我現在知道自己以前錯得有多離譜。真希望他們還在世上，能親眼目睹這個景象。', `MaleText_loc7`='Mis padres me hablaron una vez de una gente extraña y peluda que vivía al sur de nuestro hogar antes del Gran Cataclismo. Siempre creí que se trataba de una especie de fúrbolg más inteligente.$b$bAhora comprendo lo equivocado que estaba. Ojalá siguieran con vida y pudieran ver esto...' WHERE `ID`=72596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 |cFFFF0000|Hspell:134916|h[일격]|h|r에 의해 목숨을 잃었습니다. 레이 션에게서 멀리 떨어질수록 일격으로 받는 피해도 줄어듭니다. 보조 방어 전담 플레이어에게 도발을 부탁하세요!', `MaleText_loc4`='你被|cFFFF0000|Hspell:134916|h[斩首]|h|r杀死了。距离雷神越远，斩首对你的伤害就越低。让副坦克去嘲讽他！ ', `MaleText_loc5`='你被|cFFFF0000|Hspell:134916|h[斬首]|h|r殺掉了。離雷神越遠，受到的斬首傷害越低。叫副坦使用嘲諷!', `MaleText_loc7`='|cFFFF0000|Hspell:134916|h[Decapitar]|h|r te ha matado. Cuanto más lejos estés de Lei Shen, menor será el daño de Decapitar. ¡Que el tanque secundario lo provoque!' WHERE `ID`=72597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 징을 먼저 칠 거라고 했잖아.', `MaleText_loc4`='你说过你要第一个敲锣的。', `MaleText_loc5`='你說你會先敲鑼的。', `MaleText_loc7`='Dijiste que harías sonar el gong primero.' WHERE `ID`=72598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨! 아, 그리고 저건 징이 아냐! 종이라고. 난 종을 칠 거라고는 안 했어.', `MaleText_loc4`='我才不要！而且，那不是锣！那是一口钟。我可没说过我要敲钟。', `MaleText_loc5`='不要!而且，那個不是鑼!那是個鐘。我可沒說過我會敲鐘的。', `MaleText_loc7`='De eso nada. Además, eso no es un gong. ¡Es una campana! Nunca dije que golpearía una campana.' WHERE `ID`=72599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바보야!', `MaleText_loc4`='我看你是不敢吧！', `MaleText_loc5`='我賭你不敢!', `MaleText_loc7`='¡Te desafío!' WHERE `ID`=72600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용 없어. 저 종은 우리 아빠 배보다 더 크잖아!', `MaleText_loc4`='没门。那口钟比我爸爸的肚子还大呢！', `MaleText_loc5`='不可能。那個鐘比我老爹的肚皮還大!', `MaleText_loc7`='Ni hablar. ¡Esa campana es más grande que la barriga de mi papá!' WHERE `ID`=72601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 겁쟁이야!', `MaleText_loc4`='你明明就是胆小！', `MaleText_loc5`='我加倍賭你不敢!', `MaleText_loc7`='¡Te vuelvo a desafiar!' WHERE `ID`=72602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='종지기님이 저기 계시잖아. 저 분이 아이들을 종으로 바꿔 버리신대!', `MaleText_loc4`='敲钟人就在那边。我听说他会把小孩子塞进钟里！', `MaleText_loc5`='鐘大師就在那邊。我聽說他會把小孩子變成鐘!', `MaleText_loc7`='El maestro campanero está ahí mismo. He oído que convierte a los niños en campanas.' WHERE `ID`=72603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 네 누나한테 들었지? 누난 상관 없어. 우릴 괴롭히기만 하잖아. 저 종을 안 치면, 넌 왕겁쟁이야!', `MaleText_loc4`='那是你姐姐说的，根本不能算数。她是个小气鬼。你一定要去敲钟，否则我就把你的丑事都说出去！', `MaleText_loc5`='你是從你姐姐那邊聽來的，她說的不算。她超壞心的。我加倍猴人賭你不敢敲鐘!', `MaleText_loc7`='Eso te lo ha dicho tu hermana, y ella no cuenta. Es muy mala. Te desafío doblemente a que toques la campana.' WHERE `ID`=72604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='*꿀꺽* 와... 와... 왕겁쟁이라고?', `MaleText_loc4`='*咕噜* 都……都说出去？', `MaleText_loc5`='加...加倍...加倍猴人打賭?', `MaleText_loc7`='¿Eh? ¿Do... Doble reto hozen?' WHERE `ID`=72605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼! 이걸 안 하면, 새벽의 꽃에 있는 모두에게 네가 맥주 대신 포도주만 마시는 엄청난 겁보라고 말해 버릴 거야!', `MaleText_loc4`='没错！你要是不敲的话，我就告诉晨芳园里所有人，你就是个喜欢红酒而不喜欢啤酒的大懦夫！', `MaleText_loc5`='對!你不敢的話，我就跟晨綻的每個人說你是個超級膽小鬼，而且喜歡紅酒、不喜歡啤酒!', `MaleText_loc7`='¡Sí! Como no lo hagas, iré a Floralba y le diré a todo el mundo que eres un gallina que prefiere el vino a la cerveza.' WHERE `ID`=72606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐! 아빠가 난 너무 어려서 술 마시면 안 된다고 했어.', `MaleText_loc4`='可我爸爸说我太小了，不能喝酒。', `MaleText_loc5`='可是我爸說我還太小，不能喝酒。', `MaleText_loc7`='Pero mi papá dice que soy muy pequeño para beber.' WHERE `ID`=72607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 그러니까 아빠한테도 혼나겠지! 당장 저 종을 울려, 이 꼬맹아!', `MaleText_loc4`='没错！那一样会让你丢脸！现在快去敲钟，你这个大笨蛋。', `MaleText_loc5`='對!而且你敢喝酒的話麻煩就大了!去敲鐘啦，你這個小小孩。', `MaleText_loc7`='¡Es verdad! Así que también te meterás en líos por eso. Y ahora toca la campana, bebé.' WHERE `ID`=72608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하... 날 쓰러뜨렸다고 생각했나? 아무도 날 죽일 수 없다, 하찮은 필멸자여!', `MaleText_loc4`='哈哈哈……你以为自己能击败我？现在，没有什么能杀死我了，卑微的凡人！', `MaleText_loc5`='哈哈哈...你以為你能打敗我?渺小的凡人，如今誰也殺不了我的!', `MaleText_loc7`='Ja, ja, ja... ¿Creías que podías derrotarme? NADA puede matarme ahora, pobre mortal.' WHERE `ID`=72609;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 한때 키린 토에 충성을 맹세했습니다. 신뢰와 협력을 바탕으로 한 관계였죠. 그리고 그들은 저를 배신했습니다. 이제 저들에게 블러드 엘프들은 배신을 가볍게 여기지 않는다는 것을 가르쳐주겠습니다.', `FemaleText_loc4`='我曾向肯瑞托发过誓。那是一个互信互谅的誓约。后来，他们背弃了这个誓言。是时候让他们知道，血精灵是不会轻易放过背叛者的。', `FemaleText_loc5`='我曾經向祈倫托宣示效忠。那是建立在互信互諒基礎上的誓言，但是他們卻違背那樣的基礎。是時候提醒他們，血精靈絕不輕饒背叛者。', `FemaleText_loc7`='Presté juramento al Kirin Tor. Fue un enlace de confianza y entendimiento. Y entonces, traicionaron ese compromiso. Ha llegado la hora de recordarles que los elfos de sangre no toleran la traición.' WHERE `ID`=72610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막아라! 의식이 중단되어서는 안 돼!', `MaleText_loc4`='阻止他们！别让他们干扰黑暗意志！', `MaleText_loc5`='阻止他們!聚惡體不能受到干擾!', `MaleText_loc7`='¡Deténganlos! ¡Nada debe perturbar al ánimus!' WHERE `ID`=72611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 힘을... 이렇게 쓸 순 없다! 이해하지 못할 힘은 넘보지 마라!', `MaleText_loc4`='这力量……不能这么使用！你们在运用无法驾驭的力量！', `MaleText_loc5`='這股力量...不能這樣用!你們在亂用你們不懂的力量!', `MaleText_loc7`='¡El poder... no se puede manejar de este modo! ¡Están jugando con fuerzas que no comprenden!' WHERE `ID`=72612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희가 파멸을 초래했다. 그것이... 풀려났다...', `MaleText_loc4`='你们是在找死。它……被……释放了。', `MaleText_loc5`='你們是自取滅亡。它...被放出來了。', `MaleText_loc7`='Se han condenado. Se… ha... Desatado.' WHERE `ID`=72613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C, 검은 왕자님을 찾아왔다면 위층으로 가게나.', `MaleText_loc4`='$C，如果你是来找黑王子的，那他就在楼上。', `MaleText_loc5`='$C，如果你要找黑龍王子，他就在樓上。', `MaleText_loc7`='$C, si buscas al Príncipe Negro, lo encontrarás en el piso de arriba.' WHERE `ID`=72614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 대륙은 비밀을 쉽사리 드러내지 않는구나.', `MaleText_loc4`='这片大陆是不会轻易交出自己的秘密的。', `MaleText_loc5`='這塊大陸不會輕易透露它的秘密。', `MaleText_loc7`='Este continente no desvela sus secretos con facilidad.' WHERE `ID`=72615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 아직 알아야 할 것이 많다.', `MaleText_loc4`='我们还有很多东西要学。', `MaleText_loc5`='我們要學的還有很多。', `MaleText_loc7`='Todavía tenemos tanto que aprender.' WHERE `ID`=72616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌은 삶을 사랑한다. 우리 주변에 이토록 싸움이 만연한데, 우리가 무엇을 위해 싸우는지를 알면 기운이 나지.', `MaleText_loc4`='熊猫人热爱生活。在这个战火纷飞的年代，了解我们为何而战更能振奋人心。', `MaleText_loc5`='熊貓人擁抱生命的一切。在這爭戰不休的世界中，能知道自己為何而戰是非常振奮人心的。', `MaleText_loc7`='Los pandaren disfrutan de la vida. Con tanto combate a nuestro alrededor, no deja de ser agradable saber por qué luchamos.' WHERE `ID`=72617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 와서 한잔해라. 여기 왕자에게 토착 놀이를 하는 법을 배우던 참이다.', `MaleText_loc4`='来喝一杯吧。这位王子正在教我玩一种当地的游戏。', `MaleText_loc5`='來，喝一杯。王子正在教我玩一種本地的遊戲。', `MaleText_loc7`='Ven a tomar algo. El Príncipe me está enseñando a jugar a uno de los juegos locales.' WHERE `ID`=72618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구, 사마귀, 사우록... 이들은 그저 꺾어야 하는 적이 아니다. 풀어야 하는 수수께끼다!', `MaleText_loc4`='魔古族、螳螂妖、蜥蜴人……他们不仅是需要我们击败的敌人，更是有待解开的谜团！', `MaleText_loc5`='魔古，螳螂人，薩烏洛克...他們不只是需要擊倒的敵人。他們是待解的謎團!', `MaleText_loc7`='Los mogu, los mántides, los saurok... no son solo enemigos a los que derrotar. ¡Son misterios que resolver!' WHERE `ID`=72619;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑군요.', `FemaleText_loc4`='你好，朋友！', `FemaleText_loc5`='你好啊，朋友!', `FemaleText_loc7`='¡Hola de nuevo!' WHERE `ID`=72620;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕의 무기고에 침투할 방법이 있어요. 당신이 찾아 온 생물과 음영파의 도움이 있으면 가능할 거예요.', `FemaleText_loc4`='我有一个潜入雷电之王武器库的计划。但是这需要你找到的那个生物，以及影踪派的帮助。', `FemaleText_loc5`='我想出了一個潛入雷王軍械庫的方法。我們會用你找到那隻生物，請影潘幫點小忙。', `FemaleText_loc7`='Creo que sé cómo infiltrarnos en el arsenal del Rey del Trueno. Utilizaremos a la criatura que recuperaste, con ayuda del Shadopan.' WHERE `ID`=72621;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비가 끝나면 말씀하세요.', `FemaleText_loc4`='你准备好就告诉我一声。', `FemaleText_loc5`='等你準備好以後跟我說。', `FemaleText_loc7`='Habla conmigo cuando quieras empezar.' WHERE `ID`=72622;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베리사가 기다리고 있어요.', `FemaleText_loc4`='温蕾萨在等着你，勇士。', `FemaleText_loc5`='凡蕾莎正在等你，勇士。', `FemaleText_loc7`='Vereesa te está esperando.' WHERE `ID`=72623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샨 부의 몰락 시나리오에 입장합니다.', `MaleText_loc4`='进入山怖之死场景战役。', `MaleText_loc5`='加入衫布敗亡事件。', `MaleText_loc7`='Entra en la gesta de La Caída de Shan Bu.', `FemaleText_loc1`='샨 부의 몰락 시나리오에 입장합니다.', `FemaleText_loc4`='进入山怖之死场景战役。', `FemaleText_loc5`='加入衫布敗亡事件。', `FemaleText_loc7`='Entra en la gesta de La Caída de Shan Bu.' WHERE `ID`=72624;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신이 구한 이 아름다운 생물은 섬을 보호하는 벼락에 면역력이 있어요.', `FemaleText_loc4`='你救下的这个美丽生物能免疫岛上的闪电攻击。', `FemaleText_loc5`='你救的這隻生物不怕保護這座島的雷電攻擊。', `FemaleText_loc7`='Esa belleza que rescataste es inmune a los relámpagos que protegen la isla.' WHERE `ID`=72625;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='탈 수 있을까요?', `FemaleText_loc4`='你能试着骑上它吗？', `FemaleText_loc5`='你駕馭得了牠嗎?', `FemaleText_loc7`='¿Te crees capaz de domarla?' WHERE `ID`=72626;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='훌륭해요! 하늘로 날아오르면, 잔달라가 당신을 노릴지도 몰라요.', `FemaleText_loc4`='太棒了！一旦你飞上天空，赞达拉就会追上来的。', `FemaleText_loc5`='太棒了!等你飛上空中，贊達拉可能會來追殺你。', `FemaleText_loc7`='¡Espléndido! Cuando alces el vuelo, seguramente los Zandalari irán por ti.' WHERE `ID`=72627;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공중전을 각오하세요. 필요하면 탈것을 갈아타고요.', `FemaleText_loc4`='做好空战的准备。必要时，你可以跳上别的坐骑！', `FemaleText_loc5`='準備好進行空戰。有必要的話，跳到別的坐騎上!', `FemaleText_loc7`='Prepárate para luchar en pleno vuelo. ¡Salta a otra montura si es necesario!' WHERE `ID`=72628;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='음영파 요원이 광산 너머에서 기다려요. 행운을 빌어요!', `FemaleText_loc4`='影踪派的密探就在矿洞后等你。祝你好运！！', `FemaleText_loc5`='一位影潘的密探會在礦坑後面跟你碰面。祝好運!', `FemaleText_loc7`='Una agente del Shadopan se reunirá contigo detrás de las minas. ¡Buena suerte!' WHERE `ID`=72629;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 여러 평판 진영을 만나고 나면 주문이 쏟아져 들어올 겁니다.', `MaleText_loc4`='一旦你结识了潘达利亚的各个阵营，大量产品订单就会蜂拥而至。', `MaleText_loc5`='一旦你跟潘達利亞的各方陣營建立關係之後，就有接不完的工作令了。', `MaleText_loc7`='Una vez que hayas conocido a las facciones de Pandaria, empezarán a llegar pedidos de trabajo.' WHERE `ID`=72630;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수천 년 동안이나... 새 노리개가 없었는데... 아... 이 어찌나 기쁜 일인지.', `MaleText_loc4`='几千年没见过新玩具了……我会好好享受的。', `MaleText_loc5`='幾千年沒有新玩具了...我會好好享受一番。', `MaleText_loc7`='Miles de años sin juguetes nuevos... Me voy a divertir.' WHERE `ID`=72631;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공허의 힘을 똑똑히 보아라.', `MaleText_loc4`='看看虚空的力量吧！', `MaleText_loc5`='見識虛空之力吧!', `MaleText_loc7`='¡Contemplen el poder del Vacío!' WHERE `ID`=72632;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이보단 재미있을 줄 알았거늘. 참으로 실망이다.', `MaleText_loc4`='我还以为会更有趣呢。真让人失望。', `MaleText_loc5`='我的期望太高了。真令人失望。', `MaleText_loc7`='Me esperaba mucho más... Qué decepción.' WHERE `ID`=72633;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이... 공허의 품에... 들겠노라...', `MaleText_loc4`='我欢迎虚空的拥抱……', `MaleText_loc5`='我欣然接受虛空的擁抱...', `MaleText_loc7`='El abrazo del Vacío es bienvenido...' WHERE `ID`=72634;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 무슨 일이 있었는지 보았느냐?', `MaleText_loc4`='你看到我干了什么吗？', `MaleText_loc5`='看到我怎麼做的了嗎?', `MaleText_loc7`='¿Viste lo que acabo de hacer?' WHERE `ID`=72635;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오... 너한텐 버거웠나 보군. 애석하구나.', `MaleText_loc4`='看来你坚持不下去了。真遗憾。', `MaleText_loc5`='看來你跟不上。可惜啊。', `MaleText_loc7`='Parece que no pudiste estar a la altura. Qué pena.' WHERE `ID`=72636;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='걸음 조심해야지... 으하하하하!', `MaleText_loc4`='注意脚下……唔哈哈哈！', `MaleText_loc5`='小心你的腳下...', `MaleText_loc7`='Caminen con cuidado…' WHERE `ID`=72637;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 속의 수많은 비밀. 어딜 찾아봐야 할지 알겠느냐...?', `MaleText_loc4`='迷雾里有许多秘密，如果你知道往哪儿看的话……', `MaleText_loc5`='霧裡面有很多秘密...不過你們知道在哪嗎...', `MaleText_loc7`='La niebla oculta muchos secretos si saben dónde buscar…' WHERE `ID`=72638;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 내가 너를 지켜본다...', `MaleText_loc4`='我盯着你呢……', `MaleText_loc5`='我的眼睛會盯著你們的...', `MaleText_loc7`='Les estaré echando un ojo…' WHERE `ID`=72639;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸을... 맞이해라.', `MaleText_loc4`='见证你的末日吧。', `MaleText_loc5`='看著自己的滅亡吧。', `MaleText_loc7`='Observen su fin.' WHERE `ID`=72640;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"어둠 속의 비수"라고 알려진 이야기로군!$B$B검은창 트롤의 지도자인 볼진이 암살당할 위기에 처한 사건이었으나, 다행히 세 명의 용감한 모험가들이 그를 구해냈다고 하네.', `MaleText_loc4`='这就是“黑暗中的匕首”的故事！$B$B正是在这里，三位勇敢的冒险者阻止了一场精心策划的暗杀，救了部落的暗矛巨魔首领沃金一命。', `MaleText_loc5`='這是「暗箭難防」的故事!$B$B當時在這裡有三名勇敢的冒險者救了部落的黑矛食人妖領袖，沃金，免於暗殺之難。', `MaleText_loc7`='¡Esta es la historia de Una Daga en la Oscuridad!$B$BEn este lugar los valientes aventureros salvaron a Vol''jin, líder de los trols Lanza Negra de la Horda, de un asesinato seguro.' WHERE `ID`=72641;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 제가 트롤 모습을 하고 있지요?', `MaleText_loc4`='我为什么是巨魔的样子？', `MaleText_loc5`='我為什麼看起來像個食人妖?', `MaleText_loc7`='¿Por qué tengo aspecto de trol?', `FemaleText_loc1`='왜 제가 트롤 모습을 하고 있죠?', `FemaleText_loc4`='我为什么是巨魔的样子？', `FemaleText_loc5`='我為什麼看起來像個食人妖?', `FemaleText_loc7`='¿Por qué tengo aspecto de trol?' WHERE `ID`=72642;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 자네가 이번 이야기의 주연이기 때문이지!$B$B케케묵은 두루마리에서 옛날 역사를 단순히 읽는 것 보다는 훨씬 낫지 않겠나?$B$B자, 이제 역사를 배워 보게!', `MaleText_loc4`='啊，因为你将是这个故事中的一名演员！$B$B比起从落满灰尘的卷轴上阅读历史，这样会更有趣，你说呢？$B$B现在，快出发吧，好好学习！', `MaleText_loc5`='啊，因為你是故事裡的一名角色!$B$B這比單純閱讀陳舊卷軸上的歷史來得有意思多了，不是嗎?$B$B現在去吧，好好學習!', `MaleText_loc7`='Ah, porque vas a actuar en la representación de la historia.$B$BEs mucho mejor que leerla en un pergamino lleno de polvo, ¿no te parece?$B$B¡Ahora avanza, y aprende!' WHERE `ID`=72643;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, "약간의 참을성"이라는 이야기로군!$B$B나이트 엘프 달의 여사제이자 종족의 지도자인 티란데 위스퍼윈드에게 인간의 국왕인 바리안 린이 참을성을 가르쳐줬다고 하네.$B$B린 국왕은 세 명의 용감한 모험가들과 함께 스카가쉬 사령관의 호드 병력에 맞서, 수적 열세를 극복하고 주학사에서 대승을 거뒀다고 하지.', `MaleText_loc4`='这个故事叫做“王者的耐心”！$B$B正是在这里，人类国王瓦里安·乌瑞恩建议暗夜精灵的首领、月亮女神的高阶女祭司泰兰德·语风保持耐心。$B$B凭借瓦里安国王的运筹帷幄，以及三位勇敢冒险者的努力，寡不敌众的联盟军队竟在朱鹤寺击败了由指挥官斯卡戈什统领的部落大军，取得了大捷。', `MaleText_loc5`='這是「耐心試煉」的故事!$B$B人王瓦里安·烏瑞恩當時在這裡請夜精靈月女神的祭司，同時也是她們族人領袖的泰蘭妲·語風保持耐心。$B$B雖然部落指揮官疤口的兵力遠勝於聯盟，但瓦里安的計畫以及三名英勇冒險者的努力，仍讓聯盟在紅鶴寺取得了勝利。', `MaleText_loc7`='Esta es la historia de Templanza.$B$BEn este lugar, el rey de los humanos, Varian Wrynn, aconsejó paciencia a Tyrande Susurravientos, suma sacerdotisa de la diosa de la luna de los elfos de la noche y líder de su pueblo.$B$BEl plan del rey Varian, y el trabajo de tres valientes aventureros, otorgaron la victoria a la Alianza en el Templo de la Grulla Roja, a pesar de la tremenda inferioridad numérica respecto a las fuerzas de la Horda capitaneadas por el comandante Sangrescara.' WHERE `ID`=72644;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 제가 인간 모습을 하고 있습니까?', `MaleText_loc4`='我为什么是人类的样子？', `MaleText_loc5`='我為什麼看起來像個人類?', `MaleText_loc7`='¿Por qué tengo aspecto de humano?', `FemaleText_loc1`='왜 제가 인간 모습을 하고 있지요?', `FemaleText_loc4`='我为什么是人类的样子？', `FemaleText_loc5`='我為什麼看起來像個人類?', `FemaleText_loc7`='¿Por qué tengo aspecto de humana?' WHERE `ID`=72645;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 님, 이제 들어가셔도 됩니다.', `FemaleText_loc4`='普罗德摩尔女士，请进吧。', `FemaleText_loc5`='普勞德摩爾女士，您可以安全進來了。', `FemaleText_loc7`='Lady Valiente, puedes entrar a salvo.' WHERE `ID`=72646;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='순찰대! 제련소를 확보해라. 문을 닫지 못하게 부숴 버려!', `FemaleText_loc4`='游侠们！守住熔炉。打破大门，别让它关上了！', `FemaleText_loc5`='遊俠們!守好熔爐。攻破大門，讓它再也關不了!', `FemaleText_loc7`='¡Forestales! Aseguren la forja. Destrocen la puerta para que no se pueda cerrar.' WHERE `ID`=72647;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='해냈군요! 음영파가 훌륭한 동맹이 될 줄 알았어요.', `FemaleText_loc4`='你们成功了！我就知道影踪派会是出色的盟友。', `FemaleText_loc5`='你們兩個人成功了!我就知道影潘會成為好盟友。', `FemaleText_loc7`='¡Lo consiguieron! Sabía que el Shadopan sería un aliado formidable.' WHERE `ID`=72648;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우린 단지 적이 같을 뿐입니다, 프라우드무어 여군주님.', `FemaleText_loc4`='我们有着共同的敌人，普罗德摩尔女士。仅此而已。', `FemaleText_loc5`='我們有共同的敵人，普勞德摩爾女士。如此而已。', `FemaleText_loc7`='Tenemos un enemigo común, Lady Jaina. Nada más.' WHERE `ID`=72649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여군주님, 천둥왕의 무기들은 매우 위험합니다. 반드시 파괴해야 합니다.', `FemaleText_loc4`='女士，雷电之王的武器都是畸形的怪胎。我们应该销毁它们。', `FemaleText_loc5`='女士，雷王的武器是不祥的。應該要摧毀它們。', `FemaleText_loc7`='Mi señora, las armas del Rey del Trueno son una abominación. Deberían destruirlas.' WHERE `ID`=72650;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 우린 함께 천둥왕에게 본때를 보여줬죠!', `FemaleText_loc4`='但是至少，我们一起重创了雷电之王！', `FemaleText_loc5`='但我們可是一起對雷王造成了重大的打擊!', `FemaleText_loc7`='Pero juntos hemos asestado un duro golpe al Rey del Trueno.' WHERE `ID`=72651;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베리사, 모구가 돌아오기 전에 무기를 모두 모아 두세요. 호드에겐 아무것도 남겨주지 말고요.', `FemaleText_loc4`='温蕾萨，抢在魔古族回来之前多收集点东西。什么都别留给部落。', `FemaleText_loc5`='凡蕾莎，在魔古回來之前把我們能找到的一切都收集起來。別留下任何東西給部落。', `FemaleText_loc7`='Vereesa, reúne todo lo que encuentres antes de que vuelvan los mogu. Que no quede nada para la Horda.' WHERE `ID`=72652;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알아요. 하지만 아는 것이 힘이라고, 새로운 것을 배울 기회를 마다해서는 안 돼요. 고마워요, 타오스.', `FemaleText_loc4`='噢，我们会的。但知识就是力量，我从不放弃学习新知识的机会。谢谢你，陶矢。', `FemaleText_loc5`='噢，我晚點就會。但是知識就是力量，我不會錯過研究新事物的機會。謝謝你，陶氏。', `FemaleText_loc7`='Y las destruiremos. Pero el conocimiento es poder, y nunca dejo pasar una oportunidad de estudiar algo nuevo. Gracias, Taoshi.' WHERE `ID`=72653;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당신께도 감사드려요. 제련소를 지키기는 쉽지 않겠지만, 많은 걸 배울 수 있을 거예요!', `FemaleText_loc4`='还有你，英雄。要守住熔炉很困难，但是想想我们能学到的东西吧！', `FemaleText_loc5`='還要謝謝你，英雄。要守住熔爐並不容易，但想像我們能在這裡學到多少東西!', `FemaleText_loc7`='Y gracias a ti también. No será fácil defender la forja, pero piensa en todo lo que descubriremos...' WHERE `ID`=72654;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t메가이라가 |cFFF00000|Hspell:139458|h[광란]|h|r 상태에 빠집니다!', `MaleText_loc4`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t墨格瑞拉开始|cFFF00000|Hspell:139458|h[狂暴]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t梅賈拉開始|cFFF00000|Hspell:139458|h[暴怒]|h|r了!', `MaleText_loc7`='|TInterfaceIcons	rade_archaeology_whitehydrafigurine:20|t¡Megaera entra en |cFFF00000|Hspell:139458|h[Desenfreno]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t메가이라가 |cFFF00000|Hspell:139458|h[광란]|h|r 상태에 빠집니다!', `FemaleText_loc4`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t墨格瑞拉开始|cFFF00000|Hspell:139458|h[狂暴]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\trade_archaeology_whitehydrafigurine:20|t梅賈拉開始|cFFF00000|Hspell:139458|h[暴怒]|h|r了!', `FemaleText_loc7`='|TInterfaceIcons	rade_archaeology_whitehydrafigurine:20|t¡Megaera entra en |cFFF00000|Hspell:139458|h[Desenfreno]|h|r!' WHERE `ID`=72655;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파가 여기 있다! 쓸모가 있을지도 모르니 도와줘야겠다.', `MaleText_loc4`='影踪派也来了！他们或许对我们有用。快帮忙。', `MaleText_loc5`='影潘來了!他們應該能派上用場。我們最好幫幫他們。', `MaleText_loc7`='¡Los Shadopan están aquí! Podrían sernos de utilidad. ¡Vamos a ayudarles!' WHERE `ID`=72656;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 가열로면 될 것이다. 금속을 전류로 강화시킬 것이다.', `MaleText_loc4`='这个铸造机应该能用。我们得用电荷给金属充能。', `MaleText_loc5`='這個鑄造廠應該堪用。我們用電力來強化這把武器。', `MaleText_loc7`='Esta fundición debería bastar. Potenciaremos el metal con una carga eléctrica.' WHERE `ID`=72657;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가열로를 과충전하면 샤가 불안정해지지 않을까? 한번 해보자꾸나.', `MaleText_loc4`='如果让熔炉过载的话，或许就能消灭这该死的煞魔。试试看。', `MaleText_loc5`='如果我把熔爐超載，會讓這個煩人的煞變得不穩定嗎?咱們試試看。', `MaleText_loc7`='A lo mejor si sobrecargo la forja se desestabilizará el sha. Vamos a intentarlo.' WHERE `ID`=72658;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='됐다. 문제 해결.', `MaleText_loc4`='瞧。搞定了。', `MaleText_loc5`='看吧。問題解決了。', `MaleText_loc7`='Listo. Problema resuelto.' WHERE `ID`=72659;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 내가 너무 속단했나. 샤가 강해지고 있다! 없애 버려!', `MaleText_loc4`='噢——我好像言之过早了。煞魔变强了！消灭它！', `MaleText_loc5`='呃...我可能判斷錯了。煞的力量變強了!摧毀它!', `MaleText_loc7`='Ups, creo que me adelanté. ¡El sha gana fuerza! ¡Destrúyelo!' WHERE `ID`=72660;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 생각을 하고 있는 건 아니겠지?', `MaleText_loc4`='你们没有恶意的，对吧？', `MaleText_loc5`='你沒有...在肚子裡罵什麼吧，你?', `MaleText_loc7`='No estarás teniendo pensamientos oscuros, ¿no?' WHERE `ID`=72661;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 모루를 과충전했다. 샤에게는 아주 효과적일 것이나, 하나당 한 번씩만 더 사용할 수 있다!', `MaleText_loc4`='我让铁砧超载了。它们对付煞魔很有效，但每个只能使用一次！', `MaleText_loc5`='我把鐵砧超載了。用它們對付煞的效果非常好，不過每一個只能再使用一次!', `MaleText_loc7`='He sobrecargado los yunques. Serán MUY efectivos contra el sha, ¡pero solo se podrán usar una vez cada uno!' WHERE `ID`=72662;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 창이 완성됐다. 어서, 샤에게 던져!', `MaleText_loc4`='完成了。快，用它扔那个煞魔！', `MaleText_loc5`='長槍已經完成。快，對煞扔出去!', `MaleText_loc7`='La lanza está terminada. Rápido, ¡arrójala contra el sha!' WHERE `ID`=72663;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='타오스가 우측에 있는 선원을 바라보며 고개를 끄덕입니다. 숨어서 선원의 뒤로 가 기절시키세요!', `FemaleText_loc4`='陶矢冲右边的船员点点头。潜行到他背后并将他打晕了！', `FemaleText_loc5`='陶氏朝右側的船員點了個頭。從背後溜過去將他打昏!', `FemaleText_loc7`='Taoshi hace un gesto con la cabeza en dirección al tripulante de la derecha. ¡Escabúllete detrás de él para derribarlo!' WHERE `ID`=72664;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='준비됐나요, $n 님?', `FemaleText_loc4`='你准备好了吗，$n？', `FemaleText_loc5`='你準備好了嗎，$n?', `FemaleText_loc7`='¿Ya estás, $n?' WHERE `ID`=72665;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 몰살할 것이다!', `MaleText_loc4`='你们将被消灭！', `MaleText_loc5`='你會屍骨無存!', `MaleText_loc7`='¡Os exterminaremos!' WHERE `ID`=72666;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빈 상자에 내용물을 채우고 배송 준비를 하면 됩니다.', `MaleText_loc4`='等待装货与递送的空箱子。', `MaleText_loc5`='有個空箱子正等著被裝滿然後寄送出去。', `MaleText_loc7`='Un cajón vacío espera a que lo llenen y lo preparen para el envío.' WHERE `ID`=72667;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개가 당신을 쫓아옵니다!', `MaleText_loc4`='你正在被闪电追逐！', `MaleText_loc5`='有道閃電在追你!', `MaleText_loc7`='¡Te persigue un relámpago!' WHERE `ID`=72668;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='반갑군, $n. 

칸레타드의 힘은 너무 강력해 절대 풀어둘 수 없어. 내가 살아 있는 한, 그가 계속 추방 상태로 있게 확실히 감시하겠어.

그래도 그가 흡수한 마의 에너지가 큰 해가 되진 않을 거야. 필요하다면 그 힘을 조금은 자신을 위해 사용해. 그 효과가 싫증난다면 내가 약간의 사례금으로 그 마의 에너지를 해제해주지.', `FemaleText_loc4`='你好，$n。

坎雷萨德的力量太过强大，反而无法获得自由。只要我还活着，他就会一直被放逐下去。

不过，稍微尝试一下他那充沛的力量并无大碍。你可以随意抽取一些给自己用。如果你厌倦了它的效果，也可以支付一定的代价让我帮你净化这些邪能。', `FemaleText_loc5`='你好，$n。

坎瑞薩德的力量太強大了，絕對不能放他自由。只要我還活著，我會全力確保他被封印放逐。

不過，如果只汲取他一小部分的魔化能量應該是無害的，你隨時可以吸取一些來作為己用。而要是你厭倦了它的影響和效果，我也可以幫忙淨化你身上的魔化能量--當然，要酌收一些費用。', `FemaleText_loc7`='Hola, $n.

El poder de Kanrethad es demasiado grande como para dejar que siga libre. Él seguirá desterrado mientras yo siga con vida.

Aun así, probar la energía vil que rebosa no debería causar ningún mal. Drena un poco para tus propósitos. Si te cansas de sus efectos, puedo purgar la energía vil de tu organismo, por un módico precio.' WHERE `ID`=72669;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주베카 님. 더는 이 마의 에너지에 물들어 있고 싶지 않습니다.', `MaleText_loc4`='裘碧卡，我不想再被这种邪能污染了。', `MaleText_loc5`='裘貝卡，我不想再受到這股魔化能量的影響。', `MaleText_loc7`='Jubeka, ya no quiero estar contaminado con esta energía vil.', `FemaleText_loc1`='주베카 님. 더는 이 마의 에너지에 물들어 있고 싶지 않아요.', `FemaleText_loc4`='裘碧卡，我不想再被这种邪能污染了。', `FemaleText_loc5`='裘貝卡，我不想再受到這股魔化能量的影響。', `FemaleText_loc7`='Jubeka, ya no quiero estar contaminada con esta energía vil.' WHERE `ID`=72670;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 정말로 제라스의 고서를 원하지 않는 건가?', `MaleText_loc4`='你确定不再想要克萨雷斯魔典了吗？', `MaleText_loc5`='你確定不想要瑟拉斯的寶典了嗎?', `MaleText_loc7`='¿Seguro que ya no quieres el códice de Xerrath?', `FemaleText_loc1`='이제 정말로 제라스의 고서를 원하지 않는 건가?', `FemaleText_loc4`='你确定不再想要克萨雷斯魔典了吗？', `FemaleText_loc5`='你確定不想要瑟拉斯的寶典了嗎?', `FemaleText_loc7`='¿Seguro que ya no quieres el códice de Xerrath?' WHERE `ID`=72671;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''잔달라의 예언''을 듣고 싶습니다.', `MaleText_loc4`='赞达拉预言书。', `MaleText_loc5`='贊達拉預言。', `MaleText_loc7`='La profecía Zandalari.', `FemaleText_loc1`='''잔달라의 예언''을 듣고 싶어요.', `FemaleText_loc4`='赞达拉预言书。', `FemaleText_loc5`='贊達拉預言。', `FemaleText_loc7`='La profecía Zandalari.' WHERE `ID`=72672;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''우르릉거리는 천둥''을 듣고 싶습니다.', `MaleText_loc4`='雷电轰鸣。', `MaleText_loc5`='雷聲迴盪。', `MaleText_loc7`='Rumores de tormenta.', `FemaleText_loc1`='''우르릉거리는 천둥''을 듣고 싶어요.', `FemaleText_loc4`='雷电轰鸣。', `FemaleText_loc5`='雷聲迴盪。', `FemaleText_loc7`='Rumores de tormenta.' WHERE `ID`=72673;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='''신과 괴물''을 듣고 싶습니다.', `MaleText_loc4`='神祗与妖魔。', `MaleText_loc5`='神與魔。', `MaleText_loc7`='Dioses y monstruos.', `FemaleText_loc1`='''신과 괴물''을 듣고 싶어요.', `FemaleText_loc4`='神祗与妖魔。', `FemaleText_loc5`='神與魔。', `FemaleText_loc7`='Dioses y monstruos.' WHERE `ID`=72674;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성벽을 무너뜨릴 준비가 됐습니다! [개인 인스턴스 대기열에 등록합니다.]', `MaleText_loc4`='我做好攻打城墙的准备了！[排队等待单人副本。]', `MaleText_loc5`='我已經準備好加入突破城牆的行動! [加入單人副本的佇列。]', `MaleText_loc7`='¡Hora de derribar la muralla! [Únete a la cola para hacer la estancia en solitario.]', `FemaleText_loc1`='성벽을 무너뜨릴 준비가 됐어요! [개인 인스턴스 대기열에 등록합니다.]', `FemaleText_loc4`='我做好攻打城墙的准备了！[排队等待单人副本。]', `FemaleText_loc5`='我已經準備好加入突破城牆的行動! [加入單人副本的佇列。]', `FemaleText_loc7`='¡Hora de derribar la muralla! [Únete a la cola para hacer la estancia en solitario.]' WHERE `ID`=72675;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 융합체가 |cFFFF2222|Hspell:139382|h[정신 이상]|h|r을 시전하기 시작합니다! 모루의 힘을 방출해 막으십시오!', `MaleText_loc4`='融合之煞开始施放|cFFFF2222|Hspell:139382|h[疯狂]|h|r！快释放铁砧中的能量来阻止它！', `MaleText_loc5`='煞的融合體開始施展|cFFFF2222|Hspell:139382|h[瘋狂]|h|r!用鐵砧的放電來阻止它!', `MaleText_loc7`='¡La amalgama de sha empieza a lanzar |cFFFF2222|Hspell:139382|h[Demencia]|h|r! ¡Descarga uno de los yunques para detenerla!' WHERE `ID`=72676;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 멋지군! 지금이다. 계속 전진해! 자비는 필요 없다!', `MaleText_loc4`='好极了！前进——压上去。不要给他们喘息之机！', `MaleText_loc5`='做得好!前進，繼續前進。不留活口!', `MaleText_loc7`='¡Espléndido! No se detengan. Avancen. ¡No tengan piedad!' WHERE `ID`=72677;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽입니다. 잔달라 트롤이 후퇴해요!', `FemaleText_loc4`='这边——赞达拉撤退了！', `FemaleText_loc5`='這裡 - 贊達拉正在撤退!', `FemaleText_loc7`='¡Por aquí! ¡Los Zandalari se retiran!' WHERE `ID`=72678;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 틈으로 들어가세요! 부상자를 공격해요!', `FemaleText_loc4`='快通过缺口！瞄准伤员！', `FemaleText_loc5`='穿過去!攻擊受傷的目標!', `FemaleText_loc7`='¡Atraviesa la brecha! ¡Ataca a los heridos!' WHERE `ID`=72679;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이... 저 트롤에게 무슨 짓을 한 거죠?!', `FemaleText_loc4`='什么……他们对那个巨魔做了什么？', `FemaleText_loc5`='什麼 - 他們對那個食人妖做了什麼啊?', `FemaleText_loc7`='¿Pero qué le hicieron a ese trol?' WHERE `ID`=72680;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정님, 적 전선에 이렇게 가까이 계셔선 안 됩니다.', `FemaleText_loc4`='摄政王阁下——你不该到前线来。', `FemaleText_loc5`='攝政王 - 你不該如此靠近前線。', `FemaleText_loc7`='Señor regente, no deberías permanecer tan cerca de la primera línea.' WHERE `ID`=72681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대는 이리로! 방어선을 돌파했다!', `MaleText_loc4`='游侠们——跟我来！我们击穿了他们的防线！', `MaleText_loc5`='遊俠們 - 集合!我們突破他們的防線了!', `MaleText_loc7`='¡Forestales, a mí! ¡Hemos quebrado sus filas!' WHERE `ID`=72682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 내가 있을 곳은 여기요.', `MaleText_loc4`='胡说。这里才是我的舞台。', `MaleText_loc5`='胡說。我就是屬於這裡的。', `MaleText_loc7`='Tonterías. Este es mi lugar.' WHERE `ID`=72683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여! 그대는 또 한 번 호드의 승리를 이끌었소. 나도 큰 빚을 졌군.', `MaleText_loc4`='勇士！你又冲在了为部落夺取胜利的最前线。我又欠你一份人情。', `MaleText_loc5`='勇士!你又再次身處部落勝利的第一線。我也再一次地欠你良多。', `MaleText_loc7`='¡Tú! De nuevo te encuentro al frente de un triunfo de la Horda. Una vez más, estoy en deuda contigo.' WHERE `ID`=72684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 수호물 뒤에서 집결하시오. 적이 반격하겠지만... 우린 준비를 마칠 것이오.', `MaleText_loc4`='快去掩体后面重整队伍。他们会反攻……但我们会做好准备的。', `MaleText_loc5`='所有人，在結界後面集結。他們會反擊...但我們會有所準備。', `MaleText_loc7`='Reagrúpense detrás de los resguardos. Contraatacarán... pero estaremos preparados.' WHERE `ID`=72685;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽이에요. 잔달라가 물러나고 있어요!', `FemaleText_loc4`='这边——赞达拉撤退了！', `FemaleText_loc5`='這裡 - 贊達拉正在撤退!', `FemaleText_loc7`='¡Por aquí! ¡Los Zandalari se retiran!' WHERE `ID`=72686;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='틈으로 들어가세요! 사제부터 처치해요. 병사들을 강화하고 있어요!', `FemaleText_loc4`='快进去！注意那些牧师——他们正在强化其他人！', `FemaleText_loc5`='穿過去!攻擊他們的牧師 - 他們牧師在強化其他人!', `FemaleText_loc7`='¡Entra por la brecha! Concéntrate en los sacerdotes, ¡les dan poder a los demás!' WHERE `ID`=72687;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에. 저놈한테 무슨 짓을 한 거야?', `FemaleText_loc4`='圣光在上——他们做了什么？', `FemaleText_loc5`='聖光啊 - 他們對那個東西做了什麼事啊?', `FemaleText_loc7`='Por la Luz... ¿Qué le hicieron a esa cosa?' WHERE `ID`=72688;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 괜찮아요. 물러서지 마세요.', `FemaleText_loc4`='我受伤了——别后退。', `FemaleText_loc5`='我受傷了 - 不，別停手。', `FemaleText_loc7`='Estoy herida... No retrocedas.' WHERE `ID`=72689;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저걸 처치해요!', `FemaleText_loc4`='杀了那家伙！', `FemaleText_loc5`='殺了那玩意!', `FemaleText_loc7`='¡Mata a esa cosa!' WHERE `ID`=72690;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별거 아니에요. 괜찮습니다.', `FemaleText_loc4`='没什么。我很好。', `FemaleText_loc5`='小傷而已，我沒事。', `FemaleText_loc7`='No es nada. Estoy bien.' WHERE `ID`=72691;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아! 돌파했다. 모두 집중해. 지금이 기회야!', `FemaleText_loc4`='干得好！我们过来了——大家继续努力。保持优势！', `FemaleText_loc5`='做得好!我們可以通過了。大家不要走散。保住我們的優勢!', `FemaleText_loc7`='¡Bien hecho! Ya estamos adentro. ¡Trabajen en equipo! ¡Aprovechemos la ventaja!' WHERE `ID`=72692;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='베리사, 다쳤나요?', `FemaleText_loc4`='温蕾萨，你受伤了？', `FemaleText_loc5`='凡蕾莎，你受傷了嗎?', `FemaleText_loc7`='Vereesa, ¿estás herida?' WHERE `ID`=72693;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='야영지로 돌아가세요. 당신을 잃을 순 없어요.', `FemaleText_loc4`='你得回营地去。我不能失去你。', `FemaleText_loc5`='妳得回營地。我不能失去妳。', `FemaleText_loc7`='Debes volver al campamento. No puedo perderte.' WHERE `ID`=72694;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='부상자들을 보살펴라! 우린 큰 성과를 올렸다. 이제 다음 작전을 펼칠 차례야.', `FemaleText_loc4`='去搜寻伤员！今天我们做出了致命一击——战役进入了新阶段。', `FemaleText_loc5`='把傷者聚在一起!我們今天給了敵人一記重創 - 我們的下一步即將開始。', `FemaleText_loc7`='¡Reúnan a los heridos! Hoy hemos asestado un gran golpe. Ahora comienza la siguiente fase de la campaña.' WHERE `ID`=72695;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 나와! 천둥왕의 선물을 봐라!', `MaleText_loc4`='站出来！见证雷电之王的恩赐吧！', `MaleText_loc5`='向前來!見證雷王的禮物吧!', `MaleText_loc7`='¡Adelante! ¡Presencien la bendición del Rey del Trueno!' WHERE `ID`=72696;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 선택받았다. 내 피가 그분의 힘으로 불탄다!', `MaleText_loc4`='我是他的选民。我的鲜血中燃烧着他的力量！', `MaleText_loc5`='我是被選中的。我的血燃燒著他的力量!', `MaleText_loc7`='Soy el elegido. ¡Su poder fluye por mis venas!' WHERE `ID`=72697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 커... 영혼이 그분의 힘을 담을 수 없어...', `MaleText_loc4`='太强了……万灵控制不了他的力量……', `MaleText_loc5`='太多了...靈魂無法承受他的力量...', `MaleText_loc7`='Es demasiado... Los espíritus no pueden contener el poder…' WHERE `ID`=72698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 처벌하겠다! 네 인생이 얼마나 무의미한지 깨달아라!', `MaleText_loc4`='你将受到严惩！你的生命将成为徒劳的教训！', `MaleText_loc5`='你們會被懲罰!你們的生命是無用的見證!', `MaleText_loc7`='¡Serán castigados! ¡Su vida no habrá servido para nada!' WHERE `ID`=72699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라를 위하여!', `MaleText_loc4`='为了赞达拉！！', `MaleText_loc5`='為了贊達拉!!', `MaleText_loc7`='¡Por Zandalar!' WHERE `ID`=72700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관문을 봉쇄해라. 잔달라가 성벽 수비에 실패했다.', `MaleText_loc4`='堵上大门。赞达拉守不住城墙了。', `MaleText_loc5`='把門堵住。贊達拉沒有守住城牆。', `MaleText_loc7`='Cierren las puertas. Los Zandalari no han podido defender la muralla.' WHERE `ID`=72701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이 션이 힘을 모으도록 두어서는 안 되네.$b$b정문을 바로 공격하려면 시간이 걸릴 테고, 얼라이언스와 호드의 도움이 필요하다네. 그러나 우리 음영파가 아는 한 가지가 있다면, 벽이 있는 곳에는 돌아갈 길도 있다는 것이지.$b$b이 굴 뒤편의 하수도가 요새의 입구까지 이어진다네. 입구를 지켜야 하네.', `MaleText_loc4`='绝不能让雷神恢复鼎盛时期的力量。$b$b直接攻打前门需要时间，以及你们联盟和部落的协助。但我们影踪派最相信一件事，那就是车到山前必有路。$b$b这条隧道深处的下水道可以通向堡垒的入口。我们必须守住这个入口。', `MaleText_loc5`='絕不能讓雷神恢復全部的戰力。$b$b朝正門展開直接攻擊不僅耗時，而且也需要部落和聯盟的協助。但我們影潘很清楚一件事情:再高的牆，也有繞過去的門路。$b$b這條通道後方的下水道可以通到要塞的入口，我們一定要守住這個入口。', `MaleText_loc7`='No podemos permitir que Lei Shen reúna todas sus fuerzas.$b$bUn asalto directo a las puertas frontales llevará tiempo y requerirá la ayuda de su Alianza y Horda. Pero si hay algo que sabemos los Shadopan mejor que nadie, es que donde hay una muralla hay una forma de sortearla.$b$bLas cloacas al final de este túnel conducen a la entrada de la fortaleza. Debemos defender esta entrada.' WHERE `ID`=72705;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 여기 있는 천둥날개가 레이 션에게 큰 타격을 입힐 수 있는 기회라고 생각해요.', `FemaleText_loc4`='我相信，我们一定可以利用这里的雷霆翼龙狠狠打击雷神。', `FemaleText_loc5`='我相信這兒的雷翅翼手龍正是我們重創雷神的大好良機。', `FemaleText_loc7`='Creo que Alatrueno es nuestra oportunidad para asestarle un golpe devastador a Lei Shen.' WHERE `ID`=72706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 함께 가겠습니다. 부두로 같이 갑시다! [개인 인스턴스 대기열에 등록합니다.]', `MaleText_loc4`='我跟你去。让我们一起攻破那个船坞吧！ [排队等待单人副本。]', `MaleText_loc5`='走，一起攻入船塢! [加入單人副本的佇列。]', `MaleText_loc7`='Estoy contigo. ¡Entremos en el astillero! [Únete a la cola para hacer la estancia en solitario.]', `FemaleText_loc1`='당신과 함께 갈게요. 부두로 같이 가요! [개인 인스턴스 대기열에 등록합니다.]', `FemaleText_loc4`='我跟你去。让我们一起攻破那个船坞吧！ [排队等待单人副本。]', `FemaleText_loc5`='走，一起攻入船塢! [加入單人副本的佇列。]', `FemaleText_loc7`='Estoy contigo. ¡Entremos en el astillero! [Únete a la cola para hacer la estancia en solitario.]' WHERE `ID`=72707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤올마라 야수소환사가 자신을 도울 랩터를 소환합니다!', `MaleText_loc4`='绍尔马拉驭兽师召唤迅猛龙前来助战！', `MaleText_loc5`='韶嘛喇喚獸者召喚了迅猛龍來助陣!', `MaleText_loc7`='¡El clamabestias de Shaol''mara invoca raptores para que lo ayuden!', `FemaleText_loc1`='샤올마라 야수소환사가 자신을 도울 랩터를 소환합니다!', `FemaleText_loc4`='绍尔马拉驭兽师召唤迅猛龙前来助战！', `FemaleText_loc5`='韶嘛喇喚獸者召喚了迅猛龍來助陣!', `FemaleText_loc7`='¡El clamabestias de Shaol''mara invoca raptores para que lo ayuden!' WHERE `ID`=72708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕, $p!$b$b우리에겐 천둥왕이 예전의 힘을 되찾기 전에 막을 수 있는 기회가 있어.$b$b유랑도 사람들조차 그 혐오스러운 이름을 기억하고, 판다렌 아이들은 천둥 소리를 무서워해.', `MaleText_loc4`='欢迎，$p！$b$b我们将有机会在雷电之王恢复力量前阻止他。$b$b即使在迷踪岛，此人也是臭名昭著。他的名号甚至可以止小儿夜啼。', `MaleText_loc5`='你好，$p!$b$b我們有機會在雷神恢復力量前將他擊敗。$b$b即使在漂流島，大家依然沒有忘記他可怕的名字，而且打雷的聲音也還是會嚇到熊貓人孩子。', `MaleText_loc7`='¡Hola, $p!$b$bTenemos la oportunidad de detener al mismísimo Rey del Trueno antes de que pueda recuperar su antiguo poder.$b$bHasta en La Isla Errante recordamos su odioso nombre, y los niños pandaren temen el sonido del trueno.' WHERE `ID`=72709;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='$p 님, 이렇게 보니 반갑네요. 레이 션을 상대하다니 영예로운 일이군요.$b$b유랑도의 전승지기들이 무시무시한 천둥왕에 대해 많은 이야기를 들려줬어요. 조심스럽게 움직여야 해요. 전설이 사실이라면, 그는 잔인한 만큼 교활하다고 하니까요.', `FemaleText_loc4`='$p很高兴见到你。挑战雷神是一个莫大的荣誉。$b$b迷踪岛上的游学者跟我们说过很多有关雷电之王的可怕故事。我们必须小心前行。如果传说是真的，此人的狡诈不在其残暴之下。', `FemaleText_loc5`='$p，很高興見到你。能夠當面挑戰面對雷神是種莫大的榮幸。$b$b漂流島的博學行者告訴過我們許多雷王的恐怖故事，我們一定得加倍小心。假如那些傳說都是真的，他可是既殘暴又聰明的啊。', `FemaleText_loc7`='Me alegro de verte, $p. Será un honor enfrentarnos a Lei Shen.$b$bLos eremitas de La Isla Errante nos contaron muchas cosas sobre el temido Rey del Trueno. Debemos ser precavidos. Si las leyendas son ciertas, era tan astuto como brutal.' WHERE `ID`=72710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님! 저를 도와주십시오!', `MaleText_loc4`='$C！快来帮帮我！', `MaleText_loc5`='$C!過來幫助我!', `MaleText_loc7`='¡$C! ¡Ayúdame!', `FemaleText_loc1`='$C님! 저를 도와주십시오!', `FemaleText_loc4`='$C！快来帮帮我！', `FemaleText_loc5`='$C!過來幫助我!', `FemaleText_loc7`='¡$C! ¡Ayúdame!' WHERE `ID`=72711;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구와 잔달라는 천둥왕의 성벽 뒤에 숨어 있어요. 제이나 님께서 돌파할 작전을 세우셨죠. 준비되면 말씀하세요!', `FemaleText_loc4`='魔古族和赞达拉就躲在这些高墙后面。吉安娜制定了一个突击计划。你准备好了就跟我谈谈吧！', `FemaleText_loc5`='魔古和贊達拉躲在雷王的城牆後面。珍娜女士有一個轟炸計畫。等你準備好就跟我說!', `FemaleText_loc7`='Los mogu y los Zandalari se esconden detrás de los muros del Rey del Trueno, pero Lady Jaina tiene un plan para atravesarlos. Habla conmigo cuando puedas.' WHERE `ID`=72712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌아가라, 벌레들아. 이곳은 천둥왕의 땅이다!', `MaleText_loc4`='滚开，爬虫。这里是雷电之王的疆域。', `MaleText_loc5`='回頭吧，弱者們。這是雷王的領域!', `MaleText_loc7`='Márchense, débiles. ¡Este es el reino del Rey del Trueno!' WHERE `ID`=72713;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='어서 폭탄을 가져와!', `FemaleText_loc4`='快拿炸药来！', `FemaleText_loc5`='快準備好炸藥!', `FemaleText_loc7`='¡Daos prisa con los explosivos!' WHERE `ID`=72714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='돌파해야 한다. 폭탄은 어디 있는 거야?!', `FemaleText_loc4`='我们必须冲破这里——我的炸药呢？', `FemaleText_loc5`='我們必須突破這裡 - 我的炸藥在哪?', `FemaleText_loc7`='¡Debemos continuar! ¿Dónde están los explosivos?' WHERE `ID`=72715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='성벽을 폭파할 준비가 끝났어요. 당신이 직접 해주세요.', `FemaleText_loc4`='炸药已经全部到位——这份殊荣属于你！', `FemaleText_loc5`='引線已經設置完成 - 就由你來親手引爆吧!', `FemaleText_loc7`='La muralla está lista para estallar. Adelante, ¡Te cedo el honor!' WHERE `ID`=72716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='좋아! 돌파했다. 모두 집중해. 지금이 기회야!', `FemaleText_loc4`='干得好！我们过来了——大家继续努力。保持优势！退，我们寸步不让！', `FemaleText_loc5`='做得好!我們可以通過了。大家不要走散。保住我們的優勢!', `FemaleText_loc7`='¡Bien hecho! Ya estamos adentro. ¡Trabajen en equipo! ¡Aprovechemos la ventaja!' WHERE `ID`=72717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이쪽이에요. 잔달라가 물러나고 있어요!', `FemaleText_loc4`='这边——赞达拉撤退了！', `FemaleText_loc5`='這裡 - 贊達拉正在撤退!', `FemaleText_loc7`='¡Por aquí! ¡Los Zandalari se retiran!' WHERE `ID`=72718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='틈으로 들어가세요! 사제부터 처치해요. 병사들을 강화하고 있어요!', `FemaleText_loc4`='快进去！注意那些牧师——他们正在强化其他人！', `FemaleText_loc5`='穿過去!攻擊他們的牧師 - 他們牧師在強化其他人!', `FemaleText_loc7`='¡Entra por la brecha! Concéntrate en los sacerdotes, ¡les dan poder a los demás!' WHERE `ID`=72719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세상에. 저놈한테 무슨 짓을 한 거야?', `FemaleText_loc4`='圣光在上——他们做了什么？', `FemaleText_loc5`='聖光啊 - 他們對那個東西做了什麼事啊?', `FemaleText_loc7`='Por la Luz... ¿Qué le hicieron a esa cosa?' WHERE `ID`=72720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 괜찮아요. 물러서지 마세요.', `FemaleText_loc4`='我受伤了——别后退。', `FemaleText_loc5`='我受傷了 - 不，別停手。', `FemaleText_loc7`='Estoy herida... No flaquees.' WHERE `ID`=72721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저걸 처치해요!', `FemaleText_loc4`='杀了那家伙！', `FemaleText_loc5`='殺死那玩意!', `FemaleText_loc7`='¡Mata a esa cosa!' WHERE `ID`=72722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='앞으로 나와! 천둥왕의 선물을 봐라!', `MaleText_loc4`='站出来！见证雷电之王的恩赐吧！', `MaleText_loc5`='向前來!見證雷王的禮物吧!', `MaleText_loc7`='¡Adelante! ¡Presencien la bendición del Rey del Trueno!' WHERE `ID`=72723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 선택받았다. 내 피가 그분의 힘으로 불탄다!', `MaleText_loc4`='我是他的选民。我的鲜血中燃烧着他的力量！', `MaleText_loc5`='我是被選中的。我的血燃燒著他的力量!', `MaleText_loc7`='Soy el elegido. ¡Su poder fluye por mis venas!' WHERE `ID`=72724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 커... 영혼이 그분의 힘을 담을 수 없어...', `MaleText_loc4`='太强了……万灵控制不了他的力量……', `MaleText_loc5`='太多了...靈魂無法承受他的力量...', `MaleText_loc7`='Es demasiado... Los espíritus no pueden contener el poder…' WHERE `ID`=72725;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 처벌하겠다! 네 인생이 얼마나 무의미한지 깨달아라!', `MaleText_loc4`='你将受到严惩！你的生命将成为徒劳的教训！', `MaleText_loc5`='你們會被懲罰!你們的生命是無用的見證!', `MaleText_loc7`='¡Serán castigados! ¡Su vida no habrá servido para nada!' WHERE `ID`=72726;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라를 위하여!', `MaleText_loc4`='为了赞达拉！！', `MaleText_loc5`='為了贊達拉!!', `MaleText_loc7`='¡Por Zandalar!' WHERE `ID`=72727;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관문을 걸어 잠그라. 잔달라 놈들이 장벽을 사수하는 데 실패했다.', `MaleText_loc4`='堵上大门。赞达拉守不住城墙了。', `MaleText_loc5`='把門堵住。贊達拉沒有守住城牆。', `MaleText_loc7`='Cierren las puertas. Los Zandalari no han podido defender la muralla.' WHERE `ID`=72728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='죽었어요! 키린 토도 당신을 본받아야 하는데!', `FemaleText_loc4`='它死了！你激励了我们的士气！', `FemaleText_loc5`='他死了!你真是祈倫托的秘密武器!', `FemaleText_loc7`='¡Murió! ¡Eres una inspiración para el Kirin Tor!' WHERE `ID`=72729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='별거 아니에요. 괜찮습니다.', `FemaleText_loc4`='没什么。我很好。', `FemaleText_loc5`='小傷而已，我沒事的。', `FemaleText_loc7`='No es nada. Estoy bien.' WHERE `ID`=72732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='서둘러. 폭탄을 가져와!', `MaleText_loc4`='快——把那些炸药给我！', `MaleText_loc5`='快 - 把炸藥拿給我!', `MaleText_loc7`='¡Rápido! ¡Traiganme esos explosivos!' WHERE `ID`=72733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭탄을 모아라!', `MaleText_loc4`='快把那些炸药收集起来！', `MaleText_loc5`='收集那些炸藥!', `MaleText_loc7`='¡Reúnan esos explosivos!' WHERE `ID`=72734;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드를 위하여!', `FemaleText_loc4`='为了部落！！', `FemaleText_loc5`='為了部落!', `FemaleText_loc7`='¡Por la Horda!' WHERE `ID`=72735;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='당했어요! 전 내버려 두세요. 적을 없애요!', `FemaleText_loc4`='我受伤了！别管我——去干掉它！', `FemaleText_loc5`='我被擊中了!別管我 - 解決那個東西!', `FemaleText_loc7`='¡Me dieron! Déjame, ¡acaba con esa cosa!' WHERE `ID`=72736;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순찰대는 이리로! 방어선을 돌파했다!', `MaleText_loc4`='游侠们——跟我来！我们击穿了他们的防线！', `MaleText_loc5`='遊俠們 - 集合!我們突破他們的防線了!', `MaleText_loc7`='¡Forestales, a mí! ¡Hemos roto sus filas!' WHERE `ID`=72737;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 내가 있을 곳은 여기요.', `MaleText_loc4`='胡说。这里才是我的舞台。', `MaleText_loc5`='胡說。我就是屬於這裡的。', `MaleText_loc7`='Tonterías. Este es mi sitio.' WHERE `ID`=72738;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여! 그대는 또 한 번 호드의 승리를 이끌었소. 나도 큰 빚을 졌군.', `MaleText_loc4`='勇士！你又冲在了为部落夺取胜利的最前线。我又欠你一份人情。', `MaleText_loc5`='勇士!你又再次身處部落勝利的第一線。我也再一次地欠你良多。', `MaleText_loc7`='¡Tú! De nuevo te encuentro al frente de un triunfo de la Horda. Una vez más, estoy en deuda contigo.' WHERE `ID`=72739;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 수호물 뒤에서 집결하시오. 적이 반격하겠지만... 우린 준비를 마칠 것이오.', `MaleText_loc4`='快去掩体后面重整队伍。他们会反攻……但我们会做好准备的。', `MaleText_loc5`='所有人，在結界後面集結。他們會反擊...但我們會有所準備。', `MaleText_loc7`='Reagrupaos detrás de los resguardos. Contraatacarán... pero estamos preparados.' WHERE `ID`=72740;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥 가열로가 근처의 지역을 충전하기 시작했습니다. 그 안에 들어가 |cFFFF2222|Hspell:139397|h[과충전]|h|r 효과를 받으십시오!', `MaleText_loc4`='雷霆熔炉开始为附近的一块区域充能。跑进这个区域将使你|cFFFF2222|Hspell:139397|h[过载]|h|r！', `MaleText_loc5`='雷霆熔爐開始對旁邊的一塊區域放電，快跑進去讓你自己獲得|cFFFF2222|Hspell:139397|h[超載]|h|r!', `MaleText_loc7`='La Forja del Trueno ha empezado a cargar un área cercana. ¡Entra en ella para |cFFFF2222|Hspell:139397|h[recargarte]|h|r!' WHERE `ID`=72741;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='책 빼돌리는 중', `MaleText_loc4`='正在移除书籍。', `MaleText_loc5`='移除寶典。', `MaleText_loc7`='Eliminando el códice.', `FemaleText_loc1`='책 빼돌리는 중', `FemaleText_loc4`='正在移除书籍。', `FemaleText_loc5`='移除寶典。', `FemaleText_loc7`='Eliminando el códice.' WHERE `ID`=72742;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구에게 죽음을!', `MaleText_loc4`='去死吧，魔古！', `MaleText_loc5`='殺光魔古!', `MaleText_loc7`='¡Muerte a los mogu!' WHERE `ID`=72743;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이갈룩을 위하여!', `MaleText_loc4`='为了伊瓜鲁克！', `MaleText_loc5`='伊加路克萬歲!', `MaleText_loc7`='¡Por Ihgaluk!' WHERE `ID`=72744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통 속에 죽어라, 모구!', `MaleText_loc4`='痛苦地死去吧，魔古！', `MaleText_loc5`='魔古不得好死!', `MaleText_loc7`='¡Muere de agonía, mogu!' WHERE `ID`=72745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모구를 갈가리 찢어라!', `MaleText_loc4`='把魔古撕成碎片！', `MaleText_loc5`='把魔古剁成肉醬!', `MaleText_loc7`='¡Despedacemos a los mogu!' WHERE `ID`=72746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈 시체를 오물 웅덩이로 끌고 갈 테다!', `MaleText_loc4`='我要把你的尸体拖进污水池！', `MaleText_loc5`='把你的屍體拖到穢物坑!', `MaleText_loc7`='¡Tiraré tu cadáver a un pozo!' WHERE `ID`=72747;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='메가이라의 분노가 가라앉습니다.', `MaleText_loc4`='墨格瑞拉的怒火平息了。', `MaleText_loc5`='梅賈拉的怒氣平息了。', `MaleText_loc7`='La ira de Megaera amaina.', `FemaleText_loc1`='메가이라의 분노가 가라앉습니다.', `FemaleText_loc4`='墨格瑞拉的怒火平息了。', `FemaleText_loc5`='梅賈拉的怒氣平息了。', `FemaleText_loc7`='La ira de Megaera amaina.' WHERE `ID`=72748;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t두루무가 적들을 |cFFFF0000|Hspell:133597|h[암흑의 기생충]|h|r에 감염시킵니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t杜鲁姆用|cFFFF0000|Hspell:133597|h[黑暗寄生]|h|r感染他的敌人！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_curseofmannoroth.blp:20|t獨顱目放出了|cFFFF0000|Hspell:133597|h[黑暗寄生蟲]|h|r來感染他的敵人!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_curseofmannoroth.blp:20|t¡Durumu infecta a sus enemigos con |cFFFF0000|Hspell:133597|h[Parásitos oscuros]|h|r!' WHERE `ID`=72749;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록들은 혐오스럽지만 우리가 유용하게 사용할 수는 있을 겁니다.$b$b그들을 선동하여 모구에게 반기를 들게 만들면 놈들의 주의가 분산되겠지요.', `MaleText_loc4`='蜥蜴人很卑劣，但他们或许还有用处。$b$b如果我们能煽动他们反抗魔古族，或许就能把他们的注意力从我们的人身上移开。', `MaleText_loc5`='薩烏洛克雖然是可鄙的東西，但還是能發揮點作用。$b$b只要我們能煽動他們去攻擊魔古，就可以成功轉移敵人的注意力。', `MaleText_loc7`='Los saurok son despreciables, pero podrían sernos de utilidad.$b$bSi los animamos a que ataquen a los mogu, pueden desviar su atención de nuestros hombres.' WHERE `ID`=72750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사우록은 정말 흥미로운 존재예요.$b$b자기들보다 우월한 적의 그늘에서 어떻게 그토록 오래 살아남았을까요?', `FemaleText_loc4`='蜥蜴人让我很感兴趣。$b$b他们是怎么在明显占优的敌人的阴影下存活了那么长时间的？', `FemaleText_loc5`='我對薩烏洛克很好奇。$b$b他們的敵人顯然比他們優越，他們怎麼有辦法存活這麼久呢?', `FemaleText_loc7`='Los saurok me intrigan.$b$b¿Cómo han podido sobrevivir tanto tiempo a la sombra de un enemigo claramente superior?' WHERE `ID`=72751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 부랑칼날 사우록에게서 비롯되는 질병과 전염병에 대처하려고 여기 온 거예요.$b$b제가 익히 아는 전염병과는 다른 종류지만, 비슷한 점도 몇 가지 있긴 하죠.', `FemaleText_loc4`='我是来处理邪刃蜥蜴人造成的疾病和瘟疫的。$b$b虽然我从没见过这种瘟疫，但它们肯定有一些相似之处。', `FemaleText_loc5`='我來這兒處理污刃薩烏洛克所引發的瘟疫和疾病問題。$b$b雖然跟我熟悉的瘟疫種類不同，但還是有許多類似之處。', `FemaleText_loc7`='He venido a acabar con la enfermedad y la peste que propagan los saurok Hojaescoria.$b$bAunque su peste es de un tipo distinto al que estoy acostumbrada, desde luego guardan ciertas similitudes.' WHERE `ID`=72752;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원뿔형 색깔 광선을 이용해, 숨어 있는 안개도깨비 세 마리를 찾아서 처치하십시오.', `MaleText_loc4`='使用彩色锥形光束照出并杀死三只隐身的雾行兽。', `MaleText_loc5`='利用不同的顏色來揭露和殺死隱藏的霧獸。', `MaleText_loc7`='Utiliza los conos de color para revelar y matar a las tres bestias de niebla ocultas.' WHERE `ID`=72753;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁의 진정한 대가가 무엇인지 잊지 마십시오.', `MaleText_loc4`='一定要记住战争真正的代价。', `MaleText_loc5`='當心別忘了戰爭真正的代價。', `MaleText_loc7`='Nunca olvides el verdadero precio de la guerra.' WHERE `ID`=72754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 함께하기를, 용감한 $r|1이여;여;.', `MaleText_loc4`='愿圣光与你同在，勇敢的$r。', `MaleText_loc5`='願聖光與你同在，勇敢的$r。', `MaleText_loc7`='Que la Luz te acompañe, valiente $r.' WHERE `ID`=72755;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 목표를 위해서는 모구을 절멸시켜야 하지만, 측방 경계를 게을리해서는 안 됩니다.$b$b지금은 호드와 사우록이 우리와 함께 모구를 공격하지만, 둘 다 언제든지 우리에게 칼을 돌릴 수 있어요.', `FemaleText_loc4`='虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然部落和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。', `FemaleText_loc5`='我們的主要任務是消滅魔古，但不能因此而忽視戰線側翼的威脅。$b$b雖然部落和薩烏洛克也在對魔古展開攻擊，卻可能隨時把矛頭轉向我們。', `FemaleText_loc7`='Aunque nuestro objetivo exige erradicar a los mogu, no podemos descuidar nuestros flancos.$b$bTanto la Horda como los saurok atacan a los mogu a nuestro lado, pero cualquiera de los dos podría traicionarnos en cualquier momento.' WHERE `ID`=72756;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사우록은 야비한 족속이지만 쓸모가 있을지도 몰라요.$b$b사우록을 선동해서 모구에게 대적하게 할 수만 있다면, 우리 군사로부터 주의를 돌릴 수 있어요.', `FemaleText_loc4`='蜥蜴人很卑劣，但他们或许还有用处。$b$b如果我们能煽动他们反抗魔古族，或许就能把他们的注意力从我们的人身上移开。', `FemaleText_loc5`='薩烏洛克雖然是可鄙的東西，但還是能發揮點作用。$b$b只要我們能煽動他們去攻擊魔古，就可以成功轉移敵人的注意力。', `FemaleText_loc7`='Los saurok son despreciables, pero podrían sernos de utilidad.$b$bSi los animamos a que ataquen a los mogu, pueden desviar su atención de nuestros hombres.' WHERE `ID`=72758;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사우록은 정말 흥미로운 존재입니다.$b$B어찌나 흥미로운지, 저는 사우록에 홀딱 빠져서 "부랑칼날 스티브"라는 별명을 얻었지요.', `MaleText_loc4`='“蜥蜴人引起了我的兴趣。$b$b事实上，由于我太过热衷，某些人甚至开始称我为‘邪刃’斯蒂芬。”', `MaleText_loc5`='我對薩烏洛克非常好奇。$b$b事實上，好像有點好奇過頭了，已經開始有人在背地裡叫我「污刃史蒂芬」。', `MaleText_loc7`='Los saurok me intrigan.$b$bTanto es así que hay quien ya me llama "Steve Hojaescoria".' WHERE `ID`=72759;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 부랑칼날 사우록에게서 비롯되는 쓰레기를 청소하려고 왔습니다.$b$b제가 익히 아는 쓰레기와는 다른 종류지만, 비슷한 점도 몇 가지 있긴 하지요.', `MaleText_loc4`='我是来清理邪刃蜥蜴人留下的烂摊子的。$b$b虽然我从未见过它们这样的烂摊子，但其中肯定有相似之处。', `MaleText_loc5`='我負責清理污刃薩烏洛克所引起的環境問題。$b$b雖然他們造成的污染跟過去我處理的東西不太一樣，但還是有一些相似之處。', `MaleText_loc7`='He venido a limpiar el desastre que dejan los saurok tras de sí.$b$bAunque el suyo es algo distinto al que estoy acostumbrado, desde luego hay ciertas similitudes.' WHERE `ID`=72760;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리 모두 고향으로 돌아갈 수 있도록, 빨리 해결하죠.', `FemaleText_loc4`='让我们快点搞定这件事，好早点回家去。', `FemaleText_loc5`='趕緊把這邊的事情辦完，我們才能夠早點回家。', `FemaleText_loc7`='Acabemos con esto para que podamos volver a casa.' WHERE `ID`=72761;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 싸우세요, $r님.', `FemaleText_loc4`='打得好，$r。', `FemaleText_loc5`='努力戰鬥啊，$r。', `FemaleText_loc7`='Lucha bien, $r.' WHERE `ID`=72762;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='와 주셨군요! 제이나 님을 최대한 지원해 드려야 해요. 준비됐나요?', `FemaleText_loc4`='很高兴你能来！普罗德摩尔急需援军。你准备好出发了吗？', `FemaleText_loc5`='很高興你來了!普勞德摩爾需要所有能用上的援軍。你準備好了嗎?', `FemaleText_loc7`='¡Me alegro de que hayas venido! Valiente necesita todos los refuerzos posibles. Nos vamos cuando quieras.' WHERE `ID`=72763;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌은 "천둥왕"의 귀환을 매우 걱정하고 있어요. 하지만 저는 호드가 더 걱정이네요. 비행하면서 이야기하죠.', `FemaleText_loc4`='熊猫人对“雷电之王”的归来深感不安。可我更担心部落的威胁。我们飞行途中再谈。', `FemaleText_loc5`='熊貓人非常擔心這個「雷王」的回歸。但是我更擔心的是部落。我們可以在飛行中談這件事。', `FemaleText_loc7`='A los pandaren les preocupa enormemente el regreso del "Rey del Trueno". A mí me preocupa más la Horda. Hablaremos durante el vuelo.' WHERE `ID`=72764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지금으로부터 만 이천 년도 더 전에, "천둥왕" 레이 션이 모구 제국을 세웠어요.', `FemaleText_loc4`='一万两千多年前，“雷电之王”雷神建立了古老的魔古帝国。', `FemaleText_loc5`='在12,000年前，號稱「雷霆之王」的雷神創立了魔古帝國。', `FemaleText_loc7`='Hace 12,000 años, el imperio mogu fue fundado por Lei Shen, "el Rey del Trueno".' WHERE `ID`=72765;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가 모구 민족을 통일하고 판다리아의 다른 민족을 정복해 세운 제국은 수천 년 동안 지속됐죠.', `FemaleText_loc4`='他统一魔古族，征服了其他熊猫人种族，并建立起了延续数千年的帝国。', `FemaleText_loc5`='他統一了魔古，征服了熊貓人，並建立了數千年的帝國。', `FemaleText_loc7`='Unificó a los mogu, conquistó a las otras razas de Pandaria y levantó un imperio que habría de durar miles de años.' WHERE `ID`=72766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전설에 따르면 천둥왕은 막강한 힘을 지녔고, 요새와도 같은 궁전을 건설했다고 해요. 아마 곧 보일 거예요...', `FemaleText_loc4`='传说雷神拥有强大的力量，他为自己建造了一座宏伟的堡垒。我们应该很快就能看见了……', `FemaleText_loc5`='傳說中雷王有著無比的力量，給自己造了一座宏偉的堡壘。我們應該很快就能看到...', `FemaleText_loc7`='Cuenta la leyenda que el Rey del Trueno era muy poderoso y se construyó una fortaleza palaciega. Pronto veremos si es cierto...' WHERE `ID`=72767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기예요! 천둥의 섬이에요. 호드가 벌써 굶주린 독수리처럼 주위를 맴돌고 있군요.', `FemaleText_loc4`='就是那里！传说中的雷神岛。部落已经像饥饿的猛禽一样包围了它。', `FemaleText_loc5`='就在這!雷王島。部落已經像飢餓的禿鷹一樣繞著它轉了。', `FemaleText_loc7`='¡Ahí está! La Isla del Rey del Trueno. La Horda ya la sobrevuela, como una bandada de buitres.' WHERE `ID`=72768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕을 쓰러뜨리지 않으면 판다리아가 고통받을 거예요. 하지만 호드가 그 힘의 원천을 손에 넣으면, 온 세상이 대가를 치르게 되겠죠.', `FemaleText_loc4`='如果不能打败雷电之王，潘达利亚就会遭殃。可是如果让部落得到他的力量，那全世界都得付出代价。', `FemaleText_loc5`='如果不擊敗雷王，潘達利亞就有難了。更糟的是，如果部落取得他力量的泉源，整個世界都得付出慘痛的代價。', `FemaleText_loc7`='Si no derrotamos al Rey del Trueno, Pandaria sufrirá. Peor aún: si la Horda consigue la fuente de su poder, el mundo entero pagará el precio.' WHERE `ID`=72769;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='워, 조심해요! 착륙해야겠어요. 여기선 날 수가 없군요.', `FemaleText_loc4`='哇——小心！我们要着陆了。这里简直没法飞行！', `FemaleText_loc5`='嗚喔...小心!我們得著陸。這裡簡直沒辦法飛行!', `FemaleText_loc7`='¡Ah! ¡Cuidado! Tenemos que aterrizar. ¡Es casi imposible volar por aquí!' WHERE `ID`=72770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제이나 프라우드무어 님께서 바로 뵙고자 하세요.', `FemaleText_loc4`='吉安娜·普罗德摩尔女士希望尽快见到你。', `FemaleText_loc5`='珍娜·普勞德摩爾女士想要第一時間跟你碰面。', `FemaleText_loc7`='A Lady Jaina Valiente le gustaría verte lo antes posible.' WHERE `ID`=72771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='올해는 정말 끔찍한 한 해였어요. 테라모어가 파괴되고, 키린 토의 배신자가 나타나고...', `FemaleText_loc4`='这真是我这辈子最糟糕的一年：塞拉摩被摧毁了。肯瑞托又出了叛徒。', `FemaleText_loc5`='這是我生命中最糟的一年:塞拉摩被摧毀了。還有來自祈倫托內部的背叛。', `FemaleText_loc7`='Ha sido el peor año de mi vida: la destrucción de Theramore... La traición en el seno del Kirin Tor...' WHERE `ID`=72772;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='분명히 깨달았어요. 이제부터는 제가 직접 나서겠어요.', `FemaleText_loc4`='多么深刻的教训。以后，我要先发制人。', `FemaleText_loc5`='我得到了教訓。從現在開始，我要取得主動權。', `FemaleText_loc7`='Ya aprendí la lección. A partir de ahora, yo tomo la iniciativa.' WHERE `ID`=72773;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드가 해안가에서 병력을 상륙시킬 곳을 찾고 있어요.', `FemaleText_loc4`='在下面的海岸上，部落正在寻找驻扎地点。', `FemaleText_loc5`='就在海邊，部落正在尋找適合部隊登陸的地方。', `FemaleText_loc7`='Más adelante en la costa, la Horda busca un lugar para desembarcar sus tropas.' WHERE `ID`=72774;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 천둥왕을 처치하려는 건, 판다리아를 지키려는 게 아니라, 그 힘을 차지하려는 거예요.', `FemaleText_loc4`='他们也想打败雷电之王，但不是为了保护潘达利亚，而是想攫取他的力量。', `FemaleText_loc5`='他們計劃打敗雷王，但卻不是為了保護潘達利亞，而是想奪取他的力量為己用。', `FemaleText_loc7`='Quieren derrotar al Rey del Trueno; no para proteger Pandaria, sino para quedarse con su poder.' WHERE `ID`=72775;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이번에는, 우리가 앞섰어요.', `FemaleText_loc4`='可这次，我们领先了一步。', `FemaleText_loc5`='但這一次，我們快了一步。', `FemaleText_loc7`='Pero esta vez nos hemos adelantado.' WHERE `ID`=72776;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='호드는 여기에 발을 붙이지 못할 거예요. 그리고 천둥왕이 쓰러지면, 판다렌들은 얼라이언스의 영웅들이 든든한 아군이라는 걸 알게 되겠죠.', `FemaleText_loc4`='部落休想在这片海滩上占得便宜。等雷神被击败后，熊猫人就会明白，在紧急关头，是联盟的英雄与他们并肩作战。', `FemaleText_loc5`='部落在這一帶海岸將一無所獲。等雷王被擊敗時，熊貓人們會看到，在他們亟需幫助的時刻，是聯盟的英雄挺身而出。', `FemaleText_loc7`='La Horda no se asentará en estas costas. Y cuando el Rey del Trueno sea derrotado, los pandaren verán que fueron los héroes de la Alianza los que permanecieron a su lado cuando lo necesitaron.' WHERE `ID`=72777;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 전투에 온 힘을 쏟아야 해요. 각오를 다지세요.', `FemaleText_loc4`='这场战斗需要倾力而为。但愿你做好了准备。', `FemaleText_loc5`='這場戰鬥必須全力以赴。希望你們已經做好準備。', `FemaleText_loc7`='En esta batalla lo daremos todo. Espero que hayas podido prepararte.' WHERE `ID`=72778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다! [개인 인스턴스 대기열에 등록합니다.]', `MaleText_loc4`='我准备好了！[排队等待单人副本。]', `MaleText_loc5`='我準備好了! [加入單人副本的佇列。]', `MaleText_loc7`='¡Adelante! [Únete a la cola para hacer la estancia en solitario.]', `FemaleText_loc1`='준비됐어요! [개인 인스턴스 대기열에 등록합니다.]', `FemaleText_loc4`='我准备好了！[排队等待单人副本。]', `FemaleText_loc5`='我準備好了! [加入單人副本的佇列。]', `FemaleText_loc7`='¡Adelante! [Únete a la cola para hacer la estancia en solitario.]' WHERE `ID`=72779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오셨군요! 섭정께서 찾으셨습니다. 떠날 준비 되셨나요?', `FemaleText_loc4`='你来了！摄政王特地问起了你。你准备好出发了吗？', `FemaleText_loc5`='你來了!攝政王特別問到你。準備好要走了嗎?', `FemaleText_loc7`='¡Ya llegaste! El Señor Regente preguntó por ti específicamente. ¿Nos vamos?' WHERE `ID`=72780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌 전설에는 "천둥왕" 레이 션에 대한 이야기가 있습니다. 12,000년 전에 모구 제국을 세운 잔인한 황제지요.', `FemaleText_loc4`='熊猫人的传说中提到过“雷电之王”雷神。他是一万两千多年前魔古帝国的野蛮创立者。', `FemaleText_loc5`='熊貓人的傳說提到了雷神，又稱雷霆之王。他在12,000年更早前創立了殘酷的魔古帝國。', `FemaleText_loc7`='Las leyendas pandaren hablan de Lei Shen, "el Rey del Trueno". Es un déspota que fundó el imperio mogu hace más de 12.000 años.' WHERE `ID`=72781;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 모구를 통일하고, 판다렌 종족을 정복한 후, 그렇게 얻은 노예들을 부려 거대한 제국을 세웠습니다.', `FemaleText_loc4`='他统一魔古族，击败了其他熊猫人种族，并靠他征服的奴隶建立起了辉煌的帝国。', `FemaleText_loc5`='他統一了魔古，征服了熊貓人，並建立一個強盛的帝國奴役他征服的種族。', `FemaleText_loc7`='Unió a los mogu, derrotó a las otras razas de Pandaria y fundó una gloriosa nación utilizando como esclavos a los que conquistaba.' WHERE `ID`=72782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕은 제국의 가장자리에 으리으리한 요새를 지었습니다. 곧 보일 겁니다...', `FemaleText_loc4`='他在帝国边境上建立了一座宏伟的要塞。我们很快就能看见了……', `FemaleText_loc5`='雷王在帝國的邊境造了一座宏偉的堡壘。我們應該很快就能看到它...', `FemaleText_loc7`='El Rey del Trueno construyó una fortaleza palaciega en la frontera de su imperio. Pronto la veremos...' WHERE `ID`=72783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭합니다! 이 수정의 힘이 느껴지십니까? 전 머리털이 쭈뼛쭈뼛해지는 느낌이 들 정도입니다.', `MaleText_loc4`='好极了！你能感觉到这块水晶中的能量吗？我感觉我的头发都要竖起来了。', `MaleText_loc5`='太好了!你感覺到水晶的力量了嗎?我渾身的毛髮好像都豎起來了。', `MaleText_loc7`='¡Excelente! ¿Sientes el poder de este cristal? Noto cómo se me ponen los pelos de punta.' WHERE `ID`=72784;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저기! 앞쪽입니다. 천둥의 섬.', `FemaleText_loc4`='看！就在前面：雷神岛。', `FemaleText_loc5`='到了!就在前面:雷王島。', `FemaleText_loc7`='¡Ahí está! La Isla del Rey del Trueno.' WHERE `ID`=72785;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='판다렌은 과거의 황제가 제국을 차지하고, 자신들을 다시 노예로 삼을까봐 겁에 질렸습니다.', `FemaleText_loc4`='熊猫人害怕这位前皇帝会试图重建他的帝国，并再次奴役他们。', `FemaleText_loc5`='熊貓人很怕這位前任的皇帝想要重建他的帝國，並再次奴役他們。', `FemaleText_loc7`='A los pandaren les aterra que el emperador regrese para reclamar su imperio y los esclavice de nuevo.' WHERE `ID`=72786;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론 우리도 그들을 도울 이유가 있어요. 로르테마르 님이 설명하실 겁니다.', `FemaleText_loc4`='而我们自有协助他们的理由。还是让洛瑟玛来解释吧。', `FemaleText_loc5`='但是我們自己有協助他們的理由。我會讓洛索瑪來解釋。', `FemaleText_loc7`='Pero tenemos nuestras razones para ayudarlos. Dejaremos que Lor''themar te las explique.' WHERE `ID`=72787;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아! 조심하세요. 이 섬 근방에서는 비행이 거의 불가능합니다!', `FemaleText_loc4`='啊！小心——我们简直没法飞近这座岛！', `FemaleText_loc5`='哇!小心 - 在島嶼的附近幾乎沒辦法飛行了!', `FemaleText_loc7`='¡Eh! Cuidado. Es prácticamente imposible volar cerca de la isla.' WHERE `ID`=72788;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='섭정님을 만나보세요. 뱃머리에서 당신을 기다리십니다.', `FemaleText_loc4`='记得去跟摄政王谈谈。他就在船头等你。', `FemaleText_loc5`='記得跟攝政王談談。他在船頭等著你。', `FemaleText_loc7`='No olvides hablar con el Señor regente. Te espera en la proa.' WHERE `ID`=72789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='에이타스, 자리를 비켜 주시오.', `MaleText_loc4`='艾萨斯，请你回避一下。', `MaleText_loc5`='埃薩，讓我們獨處一下。', `MaleText_loc7`='Aethas, déjanos a solas un momento.' WHERE `ID`=72790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대는 지금껏 고귀하게 호드를 섬겼소. 비밀도 지킬 수 있겠지.', `MaleText_loc4`='英雄，你历经战火，对部落忠心耿耿。我想我可以信任你。', `MaleText_loc5`='英雄，你在許多戰役中英勇地為部落作戰。我覺得我可以信任你。', `MaleText_loc7`='Has servido a la Horda con nobleza en muchas campañas. Creo que puedo confiar en ti.' WHERE `ID`=72791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이 칼림도어와 판다리아에서 벌인 작전 때문에 호드가 분열하고 있소.', `MaleText_loc4`='酋长在卡利姆多和潘达利亚的战役已令部落濒临分裂。', `MaleText_loc5`='我們大酋長在卡林多和潘達利亞上的戰爭正在使部落四分五裂。', `MaleText_loc7`='La campaña de nuestro Jefe de Guerra por Kalimdor y Pandaria está desgastando a la Horda.' WHERE `ID`=72792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 천둥왕과 싸우러 왔소. 정의를 위해. 하지만 헬스크림은 지배령 거점에 사로잡혀 여기에는 신경도 쓰지 않소.', `MaleText_loc4`='我们来此对抗雷神。这是出于正义，而且地狱咆哮被统御岗哨所牵绊，无暇顾及这里。', `MaleText_loc5`='我們來這裡是為了跟雷王作戰。這是為了正義，但地獄吼眼中只有制霸岬，不會注意這裡的事。', `MaleText_loc7`='Hemos venido a enfrentarnos al Rey del Trueno. La justicia lo exige, pero Grito Infernal está demasiado ocupado en el Punto de Dominio para poner atención aquí.' WHERE `ID`=72793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕을 쓰러뜨리면서, 우리는 그 힘의 근원을 찾아내야 하오. 그걸 우리가 차지해야, 우리 "대족장"에게 저항할 수 있소.', `MaleText_loc4`='但击败他之后，我们必须找到他的力量之源。我们必须得到它，并借此对付我们的“酋长”。', `MaleText_loc5`='但是，要擊敗他，我們必須找出他強大力量的來源。我們必須要取得它，作為對抗我們「大酋長」的利器。', `MaleText_loc7`='Al tiempo que lo derrotamos, debemos encontrar la fuente de su gran poder. Tenemos que apoderarnos de ella y usarla contra nuestro "Jefe de Guerra".' WHERE `ID`=72794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그날을 대비하려면, 미리 준비해야 하오.', `MaleText_loc4`='在举兵之前，我们得做好准备。', `MaleText_loc5`='起義推翻他的那一刻時，我們必須準備周全。', `MaleText_loc7`='Si se desata la insurrección, debemos estar preparados.' WHERE `ID`=72795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심해!', `MaleText_loc4`='小心！', `MaleText_loc5`='小心上面!', `MaleText_loc7`='¡Cuidado!' WHERE `ID`=72796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 다시 피를 보려니 기분이 좋군. 얼라이언스든 모구든, 난 가리지 않소.', `MaleText_loc4`='哈！挽弓杀敌的感觉真不错。对手是联盟还是魔古族对我来说都一样。', `MaleText_loc5`='哈哈，能再讓我的刀刃染血感覺相當不錯。不管是對聯盟還是魔古，對我來說沒有差別。', `MaleText_loc7`='¡Ja! Será un placer volver a ensangrentar mi hoja. Alianza o mogu, da igual.' WHERE `ID`=72797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 우리가 어떤 위기에 처했는지 알 거라 믿소. 얼라이언스와 천둥왕 사이에서, 그대와 같은 영웅의 도움이 필요하오.', `MaleText_loc4`='闲话少说。你也明白我们的处境很危险。在联盟和雷神的夹击下，只有像你这样的英雄才能帮我们获胜。', `MaleText_loc5`='先別說了。你知道我們的情況有多危險。在聯盟和雷王的夾擊下，只有像你這樣的英雄才能讓我們有機會成功。', `MaleText_loc7`='Basta de charlas. Ya sabes lo precaria que es nuestra posición. Entre la Alianza y el Rey del Trueno, los héroes como tú son nuestra única esperanza de éxito.' WHERE `ID`=72798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아나랄라 벨로레, 행운을 빌겠소.', `MaleText_loc4`='Anar''alah belore，英雄。祝你好运。', `MaleText_loc5`='Anar''alah belore。英雄。祝你好運。', `MaleText_loc7`='Anar''alah belore. Buena suerte.' WHERE `ID`=72799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 제련소가 안전하니 저희는 가야겠습니다. 행운을 빕니다, 모험가여.', `MaleText_loc4`='熔炉已经安全了，我们得走了。祝你好运，冒险者。', `MaleText_loc5`='熔爐已經安全，我們得先走了。祝你任務順利，冒險者。', `MaleText_loc7`='La forja está a salvo, así que nos marchamos. Buena suerte con tu misión.' WHERE `ID`=72800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두루무의 분해 광선을 피하면서 짓무른 눈의 미로를 통과하십시오.', `MaleText_loc4`='在躲避杜鲁姆的衰变光束的同时走出炙眼灼光的迷宫。', `MaleText_loc5`='通過眼傷迷陣，並避開獨顱目的毀滅光束。', `MaleText_loc7`='Atraviesa el laberinto de dolores de ojo mientras evitas el Haz de desintegración de Durumu.' WHERE `ID`=72801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의지의 힘 시전이 끝나기 전에 빛나는 지역을 벗어나 넘어지는 걸 피하십시오.', `MaleText_loc4`='在意志之力施放完毕前走出发光区域以避免被击倒。', `MaleText_loc5`='在意志之力施放結束之前離開發亮的區域，以避免遭到擊倒。', `MaleText_loc7`='Sal de la zona iluminada antes de que Fuerza de voluntad termine de lanzarse para evitar que te derriben.' WHERE `ID`=72802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='키린 토는 이 섬에 깃든 엄청난 힘에 대해 모르는 것 같군. 단지 우리를 막기 위해 충동적으로 이곳에 온 것 같네. 저 풋내기 마법사들에게 한 수 가르쳐줘야겠군.', `MaleText_loc4`='显然肯瑞托对这座岛的力量一无所知。他们纯粹是为了报复才来这里阻挠我们的。我们一定要好好教训这些傲慢无礼的法师一顿。', `MaleText_loc5`='祈倫托顯然不明白這個島嶼的力量。他們只是出於怨恨而阻撓我們。一定要給這些無知的外行法師一個教訓。', `MaleText_loc7`='Es evidente que el Kirin Tor no tiene ni idea del poder que alberga esta isla. Solo han venido a detenernos por rencor. Esos ignorantes aprendices de mago merecen recibir un escarmiento.' WHERE `ID`=72803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음... 좋은 수정이군. 정말 훌륭하네, $p.', `MaleText_loc4`='唔。这是块好水晶。你做得很好，$p。', `MaleText_loc5`='嗯，這是上等水晶。$p，你做得很好。', `MaleText_loc7`='Mmm. Es un buen cristal. Lo has hecho bien, $p.' WHERE `ID`=72804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 태어난 새끼가 먹고 성장하기 전에 처치하십시오.', `MaleText_loc4`='在雏鸟进食并成长前杀死它们。', `MaleText_loc5`='在初生幼雛有機會進食長大之前殺死牠們。', `MaleText_loc7`='Mata a las crías antes de que puedan comer y madurar.' WHERE `ID`=72805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='갓 태어난 새끼를 처치하면 깃털을 떨어뜨립니다. 깃털을 사용하면 짧은 시간 날 수 있습니다.', `MaleText_loc4`='被击杀的雏鸟会掉落羽毛，使用羽毛可以短暂飞行一段时间。', `MaleText_loc5`='殺死初生幼雛會掉落羽毛，使用羽毛以飛行一小段時間。', `MaleText_loc7`='Las crías muertas sueltan plumas que puedes utilizar para volar durante un breve período de tiempo.' WHERE `ID`=72806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강력한 보석이군.', `MaleText_loc4`='一颗强大的宝石。', `MaleText_loc5`='一顆強力的寶石。', `MaleText_loc7`='Una gema poderosa.' WHERE `ID`=72807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훌륭하네, $p. 이 섬에 있는 수정은 키린 토보다는 우리 수중에 있는 게 더 낫다네.', `MaleText_loc4`='干得好，$p。我们最好还是将这座岛上的水晶掌握在自己手里，不能让肯瑞托夺去。', `MaleText_loc5`='$p，做得好。與其讓祈倫托奪走這座島嶼的水晶，不如由我們取得。', `MaleText_loc7`='Bien hecho, $p. Los cristales de esta isla estarán mejor en nuestras manos que en las del Kirin Tor.' WHERE `ID`=72808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위쪽 둥지로 날아올라 다 자란 새끼가 알을 낳지 못하게 하십시오.', `MaleText_loc4`='飞上巢穴以阻止幼年凤凰孵化。', `MaleText_loc5`='飛向上方的巢，阻止雛鳥孵化。', `MaleText_loc7`='Vuela a los nidos superiores para impedir que los jóvenes eclosionen.' WHERE `ID`=72809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_druid_galewinds.blp:20|t지쿤이 날개를 퍼덕이며 |cFFFF0000|Hspell:134370|h[하강]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_druid_galewinds.blp:20|t季鹍拍打双翼，制造出一股巨大的|cFFFF0000|Hspell:134370|h[下冲气流]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_druid_galewinds.blp:20|t稷坤用她的翅膀發出了巨大的|cFFFF0000|Hspell:134370|h[下降氣流]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_druid_galewinds.blp:20|t¡Ji Kun bate las alas para crear una gran |cFFFF0000|Hspell:134370|h[Corriente inferior]|h|r!' WHERE `ID`=72810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t지쿤이 자신의 |cFFFF0000|Hspell:134380|h[깃털]|h|r을 모든 방향으로 날립니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t季鹍施放|cFFFF0000|Hspell:134380|h[飞羽满天]|h|r，向四面八方发射翎羽！', `MaleText_loc5`='|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|t稷坤發出她的|cFFFF0000|Hspell:134380|h[羽刺]|h|r朝四面八方飛射!', `MaleText_loc7`='|TInterfaceIconsability_hunter_pet_dragonhawk.blp:20|t¡Ji Kun lanza sus |cFFFF0000|Hspell:134380|h[Plumas]|h|r en todas direcciones!' WHERE `ID`=72811;
