UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_removecurse.blp:20|t암흑의 기생충이 |cFFFF0000|Hspell:133598|h[암흑의 역병]|h|r으로 변합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_removecurse.blp:20|t黑暗寄生变异成了|cFFFF0000|Hspell:133598|h[黑暗天灾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_removecurse.blp:20|t黑暗寄生蟲變化成|cFFFF0000|Hspell:133598|h[黑暗瘟疫]|h|r了!', `MaleText_loc7`='|TInterfaceIconsspell_nature_removecurse.blp:20|t¡Los Parásitos oscuros se transforman en una |cFFFF0000|Hspell:133598|h[Peste oscura]|h|r!' WHERE `ID`=72814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복족이가 |cFFFF0000$n|r|1을;를; 추적하기 시작합니다!', `MaleText_loc4`='巨型蜗牛开始追逐|cFFFF0000$n|r！', `MaleText_loc5`='巨蝸開始追逐|cFFFF0000$n|r!', `MaleText_loc7`='¡El gasterópodo empieza a perseguir a |cFFFF0000$n|r!' WHERE `ID`=72815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위쪽의 거미줄에서 자고 있던 시체 거미가 깨어납니다!', `MaleText_loc4`='一只骸骨蜘蛛从上方的蛛网中苏醒过来了！', `MaleText_loc5`='一隻屍蛛從它上方的網子裡醒來了!', `MaleText_loc7`='¡Una araña cadáver se despierta en las telarañas superiores!' WHERE `ID`=72816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='근처에 살아 있는 육신을 감지한 구멍 벌레들이 모습을 드러내기 시작합니다!', `MaleText_loc4`='附近活动的血肉令钻地蠕虫骚动了起来！', `MaleText_loc5`='活人的氣味和騷動讓一些鑽孔蟲也開始激動起來了!', `MaleText_loc7`='¡La actividad cercana de la carne viviente atrae a gusanos perforadores!' WHERE `ID`=72817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숨은 눈이 죽어가며 뿜어내는 빛에 주위에 있던 창백한 안개도깨비들이 그 모습을 드러냅니다.', `MaleText_loc4`='在死亡时，隐藏雾行兽的强光迸发会照出该区域所有的苍白雾行兽。', `MaleText_loc5`='隱蔽霧獸死亡時發出的烈光爆發揭露出此處所有的蒼白霧獸。', `MaleText_loc7`='Al morir, la Ráfaga de luz de la niebla oculta revela todas las nieblas pálidas de la zona.' WHERE `ID`=72818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 감시자가 주위의 적들을 불행의 장에 집어 넣습니다. 놈을 처치하여 벗어나십시오!', `MaleText_loc4`='眼魔哨兵将附近的敌人拉入自己的痛苦领域，击败它才能获得自由！', `MaleText_loc5`='哨衛之眼把周遭的敵人拉入了它的悲慘力場，趕緊擊敗它才能掙脫!', `MaleText_loc7`='El ojo avizor atrae a los enemigos cercanos a su campo de miseria. ¡Derrótalo para liberarte!' WHERE `ID`=72819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_creature_disease_02.blp:20|t눈 하수인이 |cFFFF0000$n|r|1을;를; 들어 올리고 |cFFFF0000|Hspell:134668|h[물어뜯기]|h|r 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_creature_disease_02.blp:20|t眼魔仆从选中|cFFFF0000$n|r并对其施放|cFFFF0000|Hspell:134668|h[痛咬]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_creature_disease_02.blp:20|t魔眼奴僕抓起了|cFFFF0000$n|r，然後開始|cFFFF0000|Hspell:134668|h[囓咬]|h|r他們!', `MaleText_loc7`='|TInterfaceIconsability_creature_disease_02.blp:20|t¡El sirviente del ojo coge a |cFFFF0000$n|r y |cFFFF0000|Hspell:134668|h[Roe]|h|r!' WHERE `ID`=72820;
