UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, $c|1이라니;라니; 반갑군요. 이 일을 하려면 당신 같은 사람들이 필요하지요.', `MaleText_loc4`='啊，好极了，一位$c。我们正需要你这样的人来完成某些任务。', `MaleText_loc5`='啊，很好，來了個$c。這些任務正需要你們來做呢。', `MaleText_loc7`='Ah, qué bien, $gun:una; $c. Nos vendrá bien alguien como tú para algunas tareas.' WHERE `ID`=72823;
