UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낭비할 시간이 없어요. 우리가 이야기하는 지금도 얼라이언스는 천둥의 섬에서 전진하고 있어요!', `FemaleText_loc4`='不能再浪费时间了。在我们说话的时候，联盟正在雷神岛上不停推进呢！', `FemaleText_loc5`='不能再浪費時間了。就在我們交談的當下，聯盟正朝雷王島前進!', `FemaleText_loc7`='No hay tiempo que perder. La Alianza está avanzando hacia la Isla del Trueno ahora mismo.' WHERE `ID`=72832;
