UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='낭비할 시간이 없어요. 우리가 이야기하는 지금도 호드는 천둥의 섬에서 전진하고 있어요!', `FemaleText_loc4`='不能再浪费时间了。在我们说话的时候，部落正在雷神岛上不停推进呢！', `FemaleText_loc5`='不能再浪費時間了。就在我們交談的當下，部落正朝雷王島前進!', `FemaleText_loc7`='No hay tiempo que perder. La Horda está avanzando hacia la Isla del Trueno ahora mismo.' WHERE `ID`=72834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='누가 내 창을 시험하려 드느냐?', `MaleText_loc4`='谁想来试试我的长枪？', `MaleText_loc5`='誰想試試我的長矛?', `MaleText_loc7`='¿Quién quiere probar mis lanzas?' WHERE `ID`=72835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 망치는 절대로 빗나가지 않는다! 불꽃이여, 다시 타올라라!', `MaleText_loc4`='我的大锤总能克敌先机！让大火烧得更猛烈些吧！', `MaleText_loc5`='我的錘子從來不會失誤!燃燒吧，火焰!', `MaleText_loc7`='¡Mi martillo siempre da en el clavo! ¡Que las llamas se alcen de nuevo!' WHERE `ID`=72836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃술사 부는 말없이 당신을 바라봅니다. 그러고는 미늘창을 힘껏 휘두르며 공격해 옵니다.', `MaleText_loc4`='电卜师乌古沉默地凝视着你，狠狠一挥手中的战戟，发动了进攻！', `MaleText_loc5`='風暴領主伏氏默默地看著你，然後揮舞戰戟朝你攻了過來!', `MaleText_loc7`='El truenomante Vu te observa en silencio. ¡Entonces ataca con un poderoso golpe de su alabarda!' WHERE `ID`=72838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='활성화 절차: 시작', `MaleText_loc4`='激活序列：初始化', `MaleText_loc5`='啟動程序:開始', `MaleText_loc7`='Secuencia de activación: INICIADA' WHERE `ID`=72839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 얼마나 많은 지식을 나눌 수 있을지 생각해 보십시오. 우리가 얼마나 많은 곡물을 재배할 수 있을지도요!', `MaleText_loc4`='只要想想我能分享多少知识，我们能种出怎样的食材吧！', `MaleText_loc5`='想想看，我能跟大家分享的知識!我們能一起耕種的食物!', `MaleText_loc7`='Piensa en toda la información que podría compartir. ¡Piensa en todos los alimentos que podríamos cultivar!' WHERE `ID`=72840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나나 머드클로 할머니께서 저더러 농사꾼 연합 의회에 들어오라고 했단 말입니까?', `MaleText_loc4`='娜娜·泥爪邀请我加入阡陌客？', `MaleText_loc5`='娜娜·泥爪要「我」加入耕者議會?', `MaleText_loc7`='¿Nana Zarpa Fangosa me ha pedido A MÍ que me una al gremio de labradores?' WHERE `ID`=72841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만... 전 태양노래 농장을 운영하면서 농사꾼 연합 의회 일까지 할 시간은 없습니다.', `MaleText_loc4`='可是……我恐怕无法在承担议会工作的同时管理日歌农场了。', `MaleText_loc5`='可是...我擔心我沒有時間幫議會做事情，同時兼顧好日歌農莊。', `MaleText_loc7`='Pero... No tendré tiempo de trabajar en el consejo y llevar el Rancho Cantosol al mismo tiempo.' WHERE `ID`=72842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 농장은 대대로 우리 가문의 것이었습니다. 어떻게 포기할 수가 있겠습니까? 그런데 제게 더 큰 책임이 맡겨졌군요.', `MaleText_loc4`='这个农场是我祖传的财产。我怎么能放弃它呢？可是，又有更重大的责任落到了我的肩上。', `MaleText_loc5`='我們家在這塊農田耕種好幾代了，我怎麼放得了手呢?但是，我又不能袖手旁觀。', `MaleText_loc7`='Esta granja lleva generaciones en la familia. ¿Cómo puedo renunciar a ella? Pero me llama una responsabilidad mayor...' WHERE `ID`=72843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n 님, 태양노래 농장을 당신에게 선물하겠습니다. 맡아 주십시오!', `MaleText_loc4`='$n，我决定把日歌农场送给你。现在，这里归你管了！', `MaleText_loc5`='$n，我決定把日歌農莊交給你。從現在開始，就由你負責了!', `MaleText_loc7`='$n, te voy a regalar el Rancho Cantosol a ti. ¡Ahora tú estás al mando!' WHERE `ID`=72844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 가서 나나 할머니와 이야기를 해 봐야겠군요. 농장은 이제 당신 것입니다, $n 님. 잘 관리해 주실 거라 믿습니다.', `MaleText_loc4`='我最好去和娜娜谈谈。现在农场已经归你了，$n。我知道你会好好照料它的。', `MaleText_loc5`='我該去跟娜娜談一談。這塊田是你的了，$n，我相信你一定會顧好它。', `MaleText_loc7`='Será mejor que vaya a hablar con Nana. Ahora la granja te pertenece, $n. Sé que la cuidarás bien.' WHERE `ID`=72846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농사꾼 연합 일이 이렇게 힘들지는 몰랐습니다.', `MaleText_loc4`='我从没想过加入阡陌客后会有这么多工作。', `MaleText_loc5`='我從來不知道幫助耕者工會有這麼多事情要忙。', `MaleText_loc7`='Nunca imaginé que ayudar al gremio de labradores diera tanto trabajo.' WHERE `ID`=72847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양노래 농장은 어떻습니까, $n 님?', `MaleText_loc4`='日歌农场最近怎么样，$n？', `MaleText_loc5`='$n，日歌農莊怎麼樣啦?', `MaleText_loc7`='¿Qué tal va el Rancho Cantosol, $n?' WHERE `ID`=72848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 눈코 뜰 사이 없이 바쁩니다. 그래도 심장지가 번영하고 있지요.', `MaleText_loc4`='我已经快要忙死了，但汇风岭正日益繁荣。', `MaleText_loc5`='雖然我快忙不過來了，但中央平原也變得更繁榮興盛了。', `MaleText_loc7`='Por aquí estamos muy ocupados, pero Los Cultivos Florecientes prosperan.' WHERE `ID`=72849;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기가 문을 연 후부터, 채소를 끊임없이 북쪽으로 보내고 있습니다.', `MaleText_loc4`='自从锦绣谷的大门开启，我们就在源源不断地向北方供应蔬菜。', `MaleText_loc5`='自從恆春谷打開大門以後，我們就開始將蔬菜一批一批地往北方送。', `MaleText_loc7`='Desde que el valle abrió sus puertas enviamos un cargamento de verduras tras otro al norte.' WHERE `ID`=72850;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑 밀림의 당신 친구들은 식욕이 정말 왕성한 모양입니다. 신선한 농산물을 끝도 없이 찾지요.', `MaleText_loc4`='你在卡桑琅丛林的那群朋友胃口可真好，总是不断地向我们采购新鲜农产品。', `MaleText_loc5`='你在喀撒朗蠻荒那兒的朋友胃口很好，對新鮮蔬果的要求源源不絕。', `MaleText_loc7`='Tus amigos de la Espesura Krasarang tienen buen apetito. Hay una demanda constante de productos frescos.' WHERE `ID`=72851;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음영파가 북서쪽에 있는 천둥의 섬을 공격할 준비를 하고 있다고 들었습니다. 식량이 많이 필요할 텐데, 그걸 공급하는 건 우리지요!', `MaleText_loc4`='我听说影踪派正准备突袭西北方的雷神岛。他们肯定会需要大量食物，而我们就是那个供应商！', `MaleText_loc5`='我聽說影潘準備突襲西北方的雷王島。他們會需要許多食物，供給這些食物就由我們負責了!', `MaleText_loc7`='He oído que el Shadopan se prepara para asaltar la Isla del Trueno, al noroeste. Necesitarán un montón de comida, ¡y se la suministraremos nosotros!' WHERE `ID`=72852;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 씨앗관리인 슁 싱과 함께 보다 효율적인 경작, 수확, 저장 방법을 개발하고 있습니다. 맛있고 신선하고 품질 좋은 농산물을 생산하는 것이 농사꾼 연합의 목표지요!', `MaleText_loc4`='我正在和种子保管人辛辛一起研究更高效的耕作、采集和储存方案。阡陌客的目标就是提供美味、新鲜、高品质的农产品！', `MaleText_loc5`='我正在和種子看守者辛興開發更有效的耕作、採收與儲藏的方法。提供美味、新鮮又高品質的農產品，就是耕者工會的目標!', `MaleText_loc7`='Estoy trabajando con la cuidasemillas Shing Sin para desarrollar métodos más eficientes de cultivo, cosecha y almacenamiento. ¡Los Labradores queremos proporcionar productos deliciosos, frescos y de calidad!' WHERE `ID`=72853;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='농부 윤, 농사꾼 연합 의회에 들어가시겠습니까?', `MaleText_loc4`='农夫老愚，你愿意加入阡陌客议会吗？', `MaleText_loc5`='農夫尹，你願意加入耕者工會的議會嗎?', `MaleText_loc7`='Granjero Yoon, ¿te unirías al consejo del gremio de labradores?', `FemaleText_loc1`='농부 윤, 농사꾼 연합 의회에 들어가시겠어요?', `FemaleText_loc4`='农夫老愚，你愿意加入阡陌客议会吗？', `FemaleText_loc5`='農夫尹，你願意加入耕者工會的議會嗎?', `FemaleText_loc7`='Granjero Yoon, ¿te unirías al consejo del gremio de labradores?' WHERE `ID`=72854;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 주문한 붉은꽃 부추를 찾으러 왔소.', `MaleText_loc4`='我是来拿订好的红韭花的。', `MaleText_loc5`='我來這裡拿預訂的紅花蔥的。', `MaleText_loc7`='He venido por el pedido de puerros Rojaflor.', `FemaleText_loc1`='우리가 주문한 붉은꽃 부추를 찾으러 왔어요.', `FemaleText_loc4`='我是来拿订好的红韭花的。', `FemaleText_loc5`='我來這裡拿預訂的紅花蔥的。', `FemaleText_loc7`='He venido por el pedido de puerros Rojaflor.' WHERE `ID`=72855;
