UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 여기 있군! 사자의 상륙지 대표로 감사를 드리지요.', `MaleText_loc4`='噢，他们在这儿呢！雄狮港感谢你！', `MaleText_loc5`='啊，他們來了!雄獅灘感謝你!', `MaleText_loc7`='¡Ah, aquí están! ¡El Desembarco del León te lo agradece!' WHERE `ID`=72858;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순무가 정말 급하게 필요합니다!', `MaleText_loc4`='我们急需一些芜菁！', `MaleText_loc5`='我們非常需要那些菜頭!', `MaleText_loc7`='¡Nos hacen falta nabas desesperadamente!', `FemaleText_loc1`='순무가 정말 급하게 필요해요!', `FemaleText_loc4`='我们急需一些芜菁！', `FemaleText_loc5`='我們非常需要那些菜頭!', `FemaleText_loc7`='¡Nos hacen falta nabas desesperadamente!' WHERE `ID`=72860;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감사합니다! 황금 연꽃이 당신에게 빚을 졌군요.', `MaleText_loc4`='太感谢了！金莲教欠你一份人情！', `MaleText_loc5`='太感謝你了!金蓮會欠你們一份人情。', `MaleText_loc7`='¡Muchas gracias! El Loto Dorado está en deuda contigo.', `FemaleText_loc1`='고마워요! 황금 연꽃이 당신에게 빚을 졌네요.', `FemaleText_loc4`='太感谢了！金莲教欠你一份人情！', `FemaleText_loc5`='太感謝你了!金蓮會欠你們一份人情。', `FemaleText_loc7`='¡Muchas gracias! El Loto Dorado está en deuda contigo.' WHERE `ID`=72861;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 예쁜 줄무늬 멜론이 더 있으면 좋겠군요!', `MaleText_loc4`='我们还需要一些漂亮的菜瓜！', `MaleText_loc5`='我們想要更多那種漂亮的條紋甜瓜!', `MaleText_loc7`='¡Nos vendrían bien más melones a rayas de esos tan estupendos!', `FemaleText_loc1`='이 예쁜 줄무늬 멜론이 더 있으면 좋겠네요!', `FemaleText_loc4`='我们还需要一些漂亮的菜瓜！', `FemaleText_loc5`='我們想要更多那種漂亮的條紋甜瓜!', `FemaleText_loc7`='¡Nos vendrían bien más melones a rayas de esos tan estupendos!' WHERE `ID`=72862;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 멜론이 터지면서 나는 소리가 정말 좋습니다!', `MaleText_loc4`='我最喜欢它们爆炸时发出的声音了！', `MaleText_loc5`='我超愛它們爆炸的聲音!', `MaleText_loc7`='¡Me encanta el sonido que hacen al explotar!', `FemaleText_loc1`='전 멜론이 터지면서 나는 소리가 정말 좋아요!', `FemaleText_loc4`='我最喜欢它们爆炸时发出的声音了！', `FemaleText_loc5`='我超愛它們爆炸的聲音!', `FemaleText_loc7`='¡Me encanta el sonido que hacen al explotar!' WHERE `ID`=72863;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저희가 주문한 녹색 양배추는 준비되었습니까?', `MaleText_loc4`='我们预定的绿色卷心菜准备好了吗？', `MaleText_loc5`='我們訂的綠色捲心菜準備好了嗎?', `MaleText_loc7`='¿Está listo nuestro pedido de repollos verdes?' WHERE `ID`=72864;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음! 전 녹색 양배추 수프가 정말 좋습니다!', `MaleText_loc4`='唔！！！我最喜欢绿色卷心菜汤了！', `MaleText_loc5`='嗯!我就愛綠色捲心菜湯!', `MaleText_loc7`='¡Mmmm! ¡Me encanta la sopa de repollo verde!' WHERE `ID`=72865;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주문한 호박은 준비되었나?', `MaleText_loc4`='预订的南瓜到了吗？', `MaleText_loc5`='你有需要的南瓜嗎?', `MaleText_loc7`='¿Tienes las calabazas que pedimos?' WHERE `ID`=72866;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 수행할 준비가 되었습니다.', `MaleText_loc4`='我准备好了执行任务了。', `MaleText_loc5`='我準備好進行任務了。', `MaleText_loc7`='Estoy listo para mi misión.', `FemaleText_loc1`='임무를 수행할 준비가 되었어요.', `FemaleText_loc4`='我准备好了执行任务了。', `FemaleText_loc5`='我準備好進行任務了。', `FemaleText_loc7`='Estoy lista para mi misión.' WHERE `ID`=72867;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도로 만족해야겠군. 클락시에서 고맙다고 전하라더군. 이유는 모르겠지만 말이야.', `MaleText_loc4`='呃，这些应该足够了。卡拉克西表达了他们的谢意，虽然我也不知道是为了什么。', `MaleText_loc5`='嗯，這些就夠了。卡拉西瓦要我代為致謝，不過我不清楚為什麼。', `MaleText_loc7`='Bueno, esto tendrá que bastar. Los Klaxxi''va te transmiten su agradecimiento, aunque no sé por qué.' WHERE `ID`=72868;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 정수가 소멸되며 흩뿌려진 별가루의 흔적을 남깁니다.', `MaleText_loc4`='赤精的精魂消散了，只留下漫天的星尘。', `MaleText_loc5`='赤吉的精華消散了，留下一抹飄逝的星塵。', `MaleText_loc7`='La esencia de Chi-Ji se disipa, dejando solo un rastro de polvo de estrellas.' WHERE `ID`=72869;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위론의 정수가 당신을 향해 따뜻하게 미소지으며 하늘로 서서히 사라집니다.', `MaleText_loc4`='玉珑的精魂温和地对你笑了笑，慢慢消失在天空中。', `MaleText_loc5`='玉龍的精華對你露出溫暖的微笑，消逝在空中。', `MaleText_loc7`='La esencia de Yu''lon te sonríe con amabilidad y desaparece en el cielo.' WHERE `ID`=72870;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니우짜오의 정수가 당신의 도움을 받아들이며 우르릉거립니다.', `MaleText_loc4`='砮皂的精魂低声感谢了你的帮助。', `MaleText_loc5`='怒兆的精華轟隆作響，認可你的協助。', `MaleText_loc7`='La esencia de Niuzao muge cuando acepta tu ayuda.' WHERE `ID`=72871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자에게 균열이 생기며 먼지가 일어납니다!', `MaleText_loc4`='守护者开始碎裂，大量灰尘簌簌而落。', `MaleText_loc5`='守護者開始龜裂的同時，塵土從它身上落下。', `MaleText_loc7`='Se desprende polvo del guardián a medida que empieza a resquebrajarse.' WHERE `ID`=72872;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자가 땅을 울리며 움직이기 시작합니다.', `MaleText_loc4`='守护者开始活动，并发出“隆隆”的响声。', `MaleText_loc5`='守護者轟然作響，動了起來。', `MaleText_loc7`='El guardián empieza a moverse con un tremor.' WHERE `ID`=72873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자에게서 돌이 떨어지기 시작합니다. 의식이 거의 끝나갑니다!', `MaleText_loc4`='碎石开始从守护者身上滚落。仪式就要完成了！', `MaleText_loc5`='守護者身上的石塊開始落下。儀式快完成了!', `MaleText_loc7`='La piedra empieza a desprenderse del guardián. ¡El ritual casi ha terminado!' WHERE `ID`=72874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수호자 탁쿠가 깨어났습니다!', `MaleText_loc4`='守护者塔克乌苏醒了！', `MaleText_loc5`='守護者大庫甦醒了!', `MaleText_loc7`='¡El guardián Tak''u se ha despertado!' WHERE `ID`=72875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔의 정수가 의기양양하게 울부짖고는 천공의 먼지가 되어 흩어집니다.', `MaleText_loc4`='雪怒的精魂发出胜利的咆哮，爆散成一天星尘。', `MaleText_loc5`='雪怒的精華發出勝利的吼聲，消散成天界之塵。', `MaleText_loc7`='La esencia de Xuen ruge triunfalmente mientras se dispersa en polvo celestial.' WHERE `ID`=72876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='모구와 잔달라 부족이 레이 션의 왕릉에 있는 보물을 배로 실어 나르는 중이에요. 아마 천둥왕의 왕좌가 있는 곳으로 가지고 가겠죠. 레이 션의 군대가 오기 전에 신속하게 습격해서 최대한 많은 보물을 확보해야 해요. 시간이 별로 없으니 효율적으로 행동하세요, $n.

기회는 단 한 번 뿐이니 긴장하시고요.

준비가 끝나면 제게 열쇠를 주세요. 문을 열게요.', `FemaleText_loc4`='魔古族和赞达拉正在将新一批的宝藏从雷神的陵寝运往他的王座。我们必须在他的部队抵达前快速出击，尽力多抢一些宝藏。你的时间有限，我们会准时把你拉出来，所以你得注意效率，$n。

我们只有一次机会，所以好好珍惜吧。

你准备好之后，就把钥匙给我，我来打开大门。', `FemaleText_loc5`='魔古和贊達拉正在將另一批寶藏從雷神之墓搬進他的王座廳。我們要迅速出擊，在他的部隊抵達前拿走多少算多少。$n，在我們撤離你之前只有一段有限的時間，所以要有效率。

我們只有一次機會，好好把握。

等你準備好開始，就把鑰匙給我，我來開門。', `FemaleText_loc7`='Los mogu y los Zandalari están a punto de trasladar otro cargamento de tesoros de la tumba de Lei Shen a su sala del trono. Atacaremos rápidamente y nos llevaremos todo lo que podamos antes de que lleguen refuerzos. Solo tendrás un momento antes de que tengamos que retirarnos, $n, así que sé eficiente.

Solo tendremos una oportunidad, así que aprovéchala.

Cuando quieras comenzar, dame la llave y abriré la puerta.' WHERE `ID`=72877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 받으세요. 어서 갑시다.', `MaleText_loc4`='钥匙在这儿。我们走。', `MaleText_loc5`='鑰匙給妳，我們走吧。', `MaleText_loc7`='Aquí está la llave. Vamos.', `FemaleText_loc1`='열쇠를 받으세요. 어서 갑시다.', `FemaleText_loc4`='钥匙在这儿。我们走。', `FemaleText_loc5`='鑰匙給妳，我們走吧。', `FemaleText_loc7`='Aquí está la llave. Vamos.' WHERE `ID`=72878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='1초라도 허비하면 안 돼요.

준비가 끝나면 제가 말해주세요. 여기서 빠져나가게 해드리죠.', `MaleText_loc4`='我们必须争分夺秒。

你准备好之后，就告诉我一声。我会带你出去。', `MaleText_loc5`='分秒必爭。

等你準備好出發就跟我說一聲，我帶你離開這裡。', `MaleText_loc7`='Que cada segundo cuente.

Cuando quieras partir, avísame y te sacaremos de aquí.' WHERE `ID`=72879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다. 어서 여길 나가죠.', `MaleText_loc4`='我准备好了。我们离开这里吧。', `MaleText_loc5`='我準備好離開了。我們走吧。', `MaleText_loc7`='Esto listo para irme. Sácame de aquí.', `FemaleText_loc1`='준비됐습니다. 어서 여길 나가죠.', `FemaleText_loc4`='我准备好了。我们离开这里吧。', `FemaleText_loc5`='我準備好離開了。我們走吧。', `FemaleText_loc7`='Esto lista para irme. Sácame de aquí.' WHERE `ID`=72880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='보물은 많이 확보하셨나요?', `FemaleText_loc4`='在里面找到什么好东西了吗？', `FemaleText_loc5`='你帶了什麼好東西回來嗎?', `FemaleText_loc7`='¿Has conseguido algo interesante?' WHERE `ID`=72881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기꺼이 짐을 덜어드리죠. 값도 제대로 쳐드리고요.', `MaleText_loc4`='我很乐意帮你清空那个包裹。', `MaleText_loc5`='我很樂意幫忙把你的背包清空。', `MaleText_loc7`='Si quieres, te ayudo a aligerar esa mochila.' WHERE `ID`=72882;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='레이 션의 부활 이후 이렇게나 빨리 천둥왕이 우방을 모을 수 있을 것이라고는 생각하지 못했어요. 그가 없었을 때 놈들을 미리 제거해둘걸 그랬군요.', `FemaleText_loc4`='雷神归来才没多久，就在麾下聚集起了这么多盟友，这可真叫人沮丧。我们得趁他不在时多消灭一些。', `FemaleText_loc5`='雷神回歸不久就有許多盟友向他的勢力簇擁，令人氣餒。我們早該趁雷神不在的時候消滅他們的。', `FemaleText_loc7`='Es descorazonador que Lei Shen haya encontrado tantos aliados que acuden a su lado cuando acaba de regresar. Deberíamos haberlos eliminado durante su ausencia.' WHERE `ID`=72883;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오래된 적과 새로운 적이 이 섬에 득시글거려요. 피를 흘리지 않고는 한 발자국도 전진하지 못할 거예요.', `FemaleText_loc4`='这座岛上到处都是敌人，新老都有。如果没有流血牺牲的觉悟，我们是无法在这里立足的。', `FemaleText_loc5`='宿敵、新仇，遍布整座島。要在這裡立足，犧牲恐怕難以避免。', `FemaleText_loc7`='Esta isla está llena de enemigos nuevos y antiguos por igual. Cada centímetro que ganemos lo tendremos que pagar con sangre.' WHERE `ID`=72884;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='제 배는 이 해안에 상륙하느라 만신창이가 되었어요. 적이 배에 낸 흠집 하나하나마다 대가를 치르게 해 주겠어요.', `FemaleText_loc4`='我的船经过一番斗争才得以靠上这片海岸。我一定会让他们为她船体上的每一条伤疤付出代价的。', `FemaleText_loc5`='為了在這片海岸上登陸，我的船受了損傷。我一定要讓他們為了船上的每個傷痕付出代價。', `FemaleText_loc7`='Mi barco se llevó una buena tunda cuando desembarcó en esta costa. Me aseguraré de que paguen por cada arañazo de su casco.' WHERE `ID`=72885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 섬에서는 강력한 비전 마력이 느껴집니다. 그것이 천둥왕의 손아귀에 있는지, 옛 동지인 선리버의 손에 있는지는 아직 모르겠습니다.$B$B조만간 알게 되겠지요.', `MaleText_loc4`='这座岛蕴藏着巨大的魔力。我还不清楚它是掌握在雷电之王，还是我们的夺日者老朋友手里。$B$B但我们迟早会找到答案的。', `MaleText_loc5`='這座島上有強大的秘法能量。我還無法判斷這股能量是雷王所有，還是在我們的奪日者老盟友手上。$B$B以後就會知道了。', `MaleText_loc7`='En esta isla existe un gran poder Arcano. Todavía no sé si se encuentra en manos del Rey del Trueno o de nuestros antiguos aliados Atracasol.$b$bYa lo averiguaremos.' WHERE `ID`=72886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='비밀 하나 알고 싶소? 오늘 어디서 낚시하면 좋은지 말이오.', `MaleText_loc4`='想听个小秘密吗？关于今天该去哪儿钓鱼的…….', `MaleText_loc5`='想不想知道個小秘密?今天適合在哪裡釣魚的秘密...', `MaleText_loc7`='¿Te cuento un secreto? Sé dónde hay que pescar hoy...' WHERE `ID`=72887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디서 고기가 잘 낚이는지 비밀을 알고 싶소?', `MaleText_loc4`='想听听关于该去哪儿钓鱼的秘密吗？', `MaleText_loc5`='你是想聽聽該上哪釣魚的秘密嗎?', `MaleText_loc7`='¿Quieres que te cuente un secreto sobre dónde pescar?' WHERE `ID`=72888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 황무지에 있는 고크로크 여울에 밀물이 지나간 후에, 물고기들이 활발히 움직이면서 해안의 물풀을 헤쳐 놓는다오. $b $b 새우니 문어니 온갖 것들이 물풀에 얽히지. 거기서 잠깐만 낚시를 해도 사마귀 새우를 잔뜩 잡을 수 있을 거요.$b$b위치를 찾는 데 도움이 필요하면 이야기하시오.', `MaleText_loc4`='恐惧废土的古克罗克浅滩在迎来大渔汛之后，日益频繁的鱼类活动有时会搅松沿岸的海藻。$b $b大虾、八爪鱼之类的东西就会被这些海藻缠住。我敢打赌，如果你去那里钓钓鱼，肯定能收获许多螳螂虾。 $b $b如果你需要我帮忙寻找渔点，就告诉我一声。', `MaleText_loc5`='有時候，悚然荒野的苟克拉克淺灘在潮水高湧之後，魚群活動的增加會鬆動沿岸的海草。$b$b蝦子、章魚、還有各式各樣的東西都會纏在裡面。我敢說你如果在那兒釣上一會，可以釣到不少螳螂蝦。$b$b要是找不到地方的話跟我說一聲。', `MaleText_loc7`='Después de la marea alta, en los Arrecifes Gokk''lok del Desierto del Pavor, a veces el aumento de peces suelta las algas de la costa.$b$bEn ellas se enredan gambas, pulpos y todo tipo de peces. Seguro que te harías de oro si pescaras por allí un rato.$b$bAvísame si quieres que te ayude a localizar el sitio.' WHERE `ID`=72889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지, 친구. 사마귀 새우를 찾을 수 있는 곳을 지도에 표시해 주겠소. 공포의 황무지 북서쪽 끝에 있는 고크로크 여울이라는 곳이오.', `MaleText_loc4`='当然了，朋友。我可以帮你把螳螂虾的位置标在地图上。去恐惧废土的西北角看看吧，那个地方叫古克罗克浅滩。', `MaleText_loc5`='朋友，沒問題。我會在地圖上標出哪裡可以找到螳螂蝦。到悚然荒野的西北角看看，那裡有個叫做苟克拉克淺灘的地方。', `MaleText_loc7`='¡Faltaría más! Marcaré en el mapa el mejor sitio para encontrar gambas mantis. Mira en la esquina noroeste del Desierto del Pavor: es un lugar que se llama Arrecifes Gokk''lok.' WHERE `ID`=72890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스리라 마을 강태공들 얘기로는, 마을 근처의 암초문어 수가 부쩍 늘었다더군. 내 생각에는 산란철이라 그런 것 같은데, 누가 알겠소? $b $b 문제는, 문어가 늘어나면서 조개 수가 줄고 있다는 거요... 그리고 조개야말로 진짜 돈이 된다는 걸 다들 알고 있지. $b $b 거기서 잠깐만 찌를 담그고 있으면 문어를 잔뜩 잡아 올 수 있을 거요.', `MaleText_loc4`='香里拉村的垂钓翁报告说那里的八爪鱼数量异乎寻常的多。我敢打赌，肯定是它们的繁殖期到了，但谁知道呢？$b $b问题是，日益增多的八爪鱼危害到了那里的贝类生物数量……大家都知道，贝类才是最值钱的。$b $b快去那里挥舞你的钓竿吧，肯定能钓到不少八爪鱼。', `MaleText_loc5`='斯里拉村的釣手隊回報說村子裡有出奇多的暗礁章魚。我認為是繁殖季到了，可是誰知道呢?$b$b麻煩的是，暴增的章魚數量對貝類的數量造成打擊...大家都知道真正賣錢的是貝類。$b$b去那裡釣個一會兒，我保證你能滿載章魚而歸。', `MaleText_loc7`='Los Pescadores de la Aldea Sri-la informan de una cantidad anormalmente alta de pulpos de arrecife en su aldea. Yo diría que es su época de cría, pero ¿quién sabe?$b$bEl problema es que el aumento de pulpos está dañando a la población de gambas... y todo el mundo sabe que las gambas son lo que da dinero.$b$bPesca un rato por aquellos lares y ya verás que consigues montones de pulpos.' WHERE `ID`=72891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암초문어는 비취 숲, 스리라 마을의 이 근처에 있을 거요. $b$b<당신의 지도 위, 비취 숲의 북동쪽 해안에 핀을 꽂는 벤>', `MaleText_loc4`='我想八爪鱼应该就在翡翠林的香里拉村一带。$b$b<班宏拿过你的地图，在翡翠林的东北海滩上按下了一根别针。>$b$b', `MaleText_loc5`='我認為暗礁章魚出現在翠玉林的斯里拉村一帶。$b$b<班在你的地圖上沿著翠玉林的東北岸插了個大頭針。>$b$b', `MaleText_loc7`='Creo que los pulpos de arrecife están más o menos por aquí en la Aldea Sri-La, en el Bosque de Jade.$b$b<Ben clava un alfiler en tu mapa, a la altura de la costa noreste del Bosque de Jade.>' WHERE `ID`=72892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보름달이 뜨면, 비취 숲에 있는 길 잃은 자의 숲에 사는 화살요정용이 비늘 갈이를 한다고 하오. 한밤중에 비늘 갈이를 하는데, 꽤나 아름다운 광경이라고 하더군. $b $b 요정용의 비늘은 밝은 비취색으로 빛나는데, 가끔은 물속에도 떨어지지. 그 비늘에 비취 폐어가 말도 못하게 꼬인다오! 불에 꼬이는 나방처럼 말이지! $b $b 하지만 모구의 신경을 거스르지 않게 조심하시오... 상냥하다고 하긴 어렵거든.', `MaleText_loc4`='在满月期间，翡翠林的失落林地里的小精龙就会蜕鳞。这一般都发生在夜间，那个景象非常美丽。$b $b它们的鳞片会闪着明亮的翠绿光芒撒入水中。这会吸引到大量的翠绿肺鱼，数量之多绝对超乎你的想象！就像扑火的飞蛾一样！$b $b但你要小心别惊动了那里的魔古族……他们可不太友好。', `MaleText_loc5`='滿月的時候，翠玉林裡迷失者之林的妖精會褪下身上的鱗片。牠們會在深夜的時候褪鱗，景象相當美麗。$b$b牠們的鱗片散發著翡翠般的亮光，點點光輝落入水中。這會引來多得你想不到的翠玉龍魚!就像飛蛾趨火一樣!$b$b不過，小心別惹到那些魔古...他們可不怎麼友善。', `MaleText_loc7`='Durante la luna llena, los duendes dardo del Bosque de los Perdidos, en el Bosque de Jade, sueltan sus escamas. Lo hacen de noche; es muy bonito de ver.$b$bLas escamas emiten un brillo de luz de jade y caen al agua. ¡No veas cómo atraen a los peces alveolares de jade! ¡Como polillas a una llama!$b$bPero cuídate de molestar a los mogu... No son muy amistosos que digamos.' WHERE `ID`=72893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론이지. 비취 폐어는 이 근처에서 잡힌다오. 비취 숲에 있는 길 잃은 자의 숲이지. 웅덩이의 크기로는 판다리아 최고라고는 할 수 없지만, 정말 아름다운 곳이라오.', `MaleText_loc4`='当然可以。翠绿肺鱼就集中在这一带，翡翠林的失落林地里。那里不算是潘达利亚最大的鱼塘，但别具一格。', `MaleText_loc5`='是啊，沒錯。這一帶有翠玉龍魚，就在你地圖上翠玉林的迷失者之林那裡。那兒算不上潘達利亞最大的池子，但它的景觀還是很壯麗。', `MaleText_loc7`='Claro. Los peces alveolares de jade se encuentran por aquí, en el Bosque Encantado de los Perdidos del Bosque de Jade. No es el mayor banco de Pandaria, pero es majestuoso.' WHERE `ID`=72894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘 물자를 모으다가, 이색적인 물약과 기름을 파는 유랑 그루멀을 만났다오. 그중에 특히 재미있는 것이 있었는데, 물고기를 위한 "사랑의 물약"이었다오. $b $b 어떻게 만든 건지는 몰라도 진짜 효과가 있다오! 자기 연못에 사는 붉은배 쏘가리 수가 두 배가 됐다지 뭐요! $b $b 그는 니우짜오 사원 북쪽의 호수에 있었다오. 그곳의 물고기 수를 좀 줄여 주는 게 좋을 거요.', `MaleText_loc4`='我今天在进货时，遇到了一个贩卖稀有药水和油膏的行脚商。他那里最奇怪的一种油膏就是针对鱼群的“爱情药水”。$b $b别管他是怎么做出来的了，你只要知道，这玩意儿真的有用！它让水塘里的红腹鳜鱼数量整整翻了一倍！$b $b我是在砮皂寺北方的湖边遇到他的。如果你能去让那里的鳜鱼数量恢复正常，没准还是做了件好事呢。', `MaleText_loc5`='「今天我在收集補給品的時候，我遇到了一個販賣珍奇藥水和精油的流浪商人。他有一種名叫『愛情靈藥』的魚用怪油。$b$b先別管這油是怎麼做出來的，只要知道這玩意真的管用就對了!它讓他池子裡的紅肚桂花魚數量多了一倍!$b$b我在怒兆寺北邊的湖遇到了他，你如果幫忙減少那兒魚的數量，也算是好事一樁。', `MaleText_loc7`='Hoy estaba recogiendo suministros cuando me he cruzado con un grúmel ambulante que vendía pociones y ungüentos exóticos. Uno de los más extraños era un "filtro de amor" para peces.$b$bDa igual cómo lo creara: ¡lo que importa es que funciona de verdad! ¡Ha DUPLICADO la población de mandarines panzarroja de este estanque!$b$bLo encontré en el lago que hay al norte del Templo de Niuzao. Estaría bien que ayudaras a reequilibrar la fauna de los alrededores.' WHERE `ID`=72895;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<머리를 긁적이는 벤>$b$b 길을 설명하는 데는 별로 소질이 없지만, 아마도 붉은배 쏘가리 떼는 탕랑 평원에 있는 니우짜오 들판의 여기쯤 있을 거요.$b$B<지도의 일부 지역에 원으로 표시를 하는 벤>$b$b', `MaleText_loc4`='<班宏抓了抓脑袋。>$b$b我的方向感不算太强，但我觉得红腹鳜鱼应该就在这一带，螳螂高原的砮皂旷野。$b$b<班宏在你的地图上划了一个大概的范围。>$b$b', `MaleText_loc5`='<班搔了搔頭。>$b$b幫人指路我算不上最在行，可是我想紅肚桂花魚大概在這裡，螳螂荒原的怒兆原野那邊。$b$b<班在你的地圖上圈出了大概的區域。>$b$b', `MaleText_loc7`='<Ben se rasca la cabeza.>$b$bNo se me da muy bien dar direcciones, pero creo que los mandarines panzarroja están por aquí, en los Campos de Niuzao de las Estepas de Tong Long.$b$b<Ben señala una zona aproximada en tu mapa.>' WHERE `ID`=72896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 네 바람의 계곡에는 널리 알려진 스톰스타우트 양조장이 있소. 이미 알고 있겠지만 꽤 난폭한 호젠 몇몇이 그곳을 점령했더군. 이 술 취한 방탕아들이 점점 걷잡을 수 없게 행동한다오.$b $b가끔 새로운 술을 만들면 이들은 맥주를 가지고 싸움판을 벌이지. 그렇소. 수백 통의 맥주가 옌저 강에 그냥 버려지는 것이지.$b $b 맥주는 황제 연어를 끌어들인다오. 그것도 아주 많이. 잡기도 쉬운 놈들이니 별 문제는 없을 거요.', `MaleText_loc4`='在四风谷，我们有着著名的风暴烈酒酿造厂。你或许已经注意到了，一群极具破坏力的猢狲想要强占那里。他们都是出了名的酒鬼，向来不懂节制。$b $b有时，当一批新酒酿好后，他们还会搞啤酒大战。没错，大量的美酒就这么浪费掉了，白白流进了炎子江。 $b $b这些美酒引来了帝王鲑鱼。我从没见过那么多帝王鲑鱼挤在一起的景象。而且这些鲑鱼还会变得更好抓……看来它们也喝高了。', `MaleText_loc5`='知名的風暴烈酒酒坊就在我們在四風峽這裡。不過你或許注意到了，那個地方已經被一群相當會搞破壞的猴人給霸佔了。他們經常會喝得太多、喝得失控。$b$b有時候，特別是在新釀好一批酒的時候，他們還會打起架來。沒錯，一桶又一桶的美酒就這麼被浪費、被沖到延哲河裡去了。$b$b然後酒水會吸引帝王鮭魚成群地集結過來，那場面保證你沒見過。它們也會變得比較容易上鉤，你知道的，因為它們也跟著...喝多了。', `MaleText_loc7`='En el Valle de los Cuatro Vientos tenemos la famosa Cervecería del Trueno. Habrás visto que un grupo más bien problemático de hozen han decidido adueñarse del lugar. Sus peleas de borrachos siempre se salen de madre.$b$bA veces, cuando se elabora una nueva tanda de cerveza, se lían a tortas. Sí, se malgastan litros de cerveza que acaban en el río Yan-Zhe.$b$bLa cerveza atrae a los salmones emperador y vienen a cientos. Y además son más fáciles de pescar... ya sabes, porque se han tomado un trago.' WHERE `ID`=72897;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황제 연어를 낚기 가장 적절한 창소는 네 바람의 계곡에 있는 스톰스타우트 양조장이오. 내가 지도에 표시해주지.', `MaleText_loc4`='捕捉帝王鲑鱼的最佳地点或许就是四风谷的酒厂外面。我来帮你标在地图上。', `MaleText_loc5`='釣帝王鮭魚最好的地方，大概就在四風峽的酒坊外頭那裡。來，我幫你標在地圖上。', `MaleText_loc7`='El mejor sitio para pescar salmones emperador es justo al lado de la cervecería, en el Valle de los Cuatro Vientos. Lo marcaré en tu mapa.' WHERE `ID`=72898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 화나 보인다고? 물론이지. 화난 게 맞으니까!$b $b나의 영원한 라이벌, 위자크 블라스트베이트가 내 구역을 침범할 생각을 하고 있소. 놈은 영악하고 조그만 고블린인데... 독특한 방법으로 낚시를 하지.$b $b 최근에 그가 크라사리 폭포에 있던 걸 보았다오. 크라사랑 주걱철갑상어를 낚으려면 그곳에 가야 될 거요. 물론 그 고블린이 여기저기서 물고기들을 몰고 있겠지만, 거기서 다른 사람이 낚시를 하고 있다는 걸 알면 알아서 다른 곳으로 갈 것이오. $b $b 아, 그리고 가능하면 그에게 모욕적인 몸짓을 한 번 보여주시오. 친애하는 벤이 보냈다고 하고 말이오. $b$b<벤이 씨익 웃습니다.>$b$b', `MaleText_loc4`='我看上去很生气？没错，我就是很生气！$b $b我的死对头维扎克·爆饵正在逐渐蚕食我的地盘。他是个卑鄙的小个子地精，专用……非常规手段来捕鱼。$b $b我上次遇见他是在卡桑利瀑布。如果你想要卡桑琅白鲟，就去那里钓吧。我敢打赌，它们肯定已经被他吓得六神无主了。如果让他看到别人在那里钓鱼，他或许就会觉得那里太挤而离开。$b $b噢，如果可以的话，请你好好唾弃他一番，就说是班宏让你去的。$b$b<班宏得意地笑了笑。>$b$b', `MaleText_loc5`='我看起來很生氣?好吧，那是因為我真的很生氣!$b$b我的死對頭，威扎克·炸餌，跑到我的地盤這邊來了。他是個討人厭的哥布林，專門用...非傳統的方式抓魚。$b$b我上回在喀撒利瀑布有看到他，然後如果你想抓喀撒朗匙吻鱘的話，你今天也該到那裡去。我敢打賭，他一定會在那邊把魚群嚇得東跑西竄。但如果他看見有其他人在那邊釣魚的話，說不定他會覺得地方太擠、然後就此離開。$b$b喔，還有。對他比個「侮辱」的手勢，然後告訴他是老班叫你這麼做的。$b$b<班笑了起來。>$b$b', `MaleText_loc7`='¿Parezco enfadado? ¡Porque LO ESTOY!$b$bMi archienemigo, Wizak Bombacebo, está allanando mi terreno. Es un horrible goblin que utiliza métodos... poco convencionales para pescar.$b$bLa última vez que lo vi estaba en las Cataratas Krasari. Si quieres poliodóntidos de Krasarang, deberías pescar allí; seguro que Wizak los está asustando. A lo mejor si ve a más gente pescando en la zona se cree que hay demasiada competencia y se va.$b$bAh, si puedes, hazle un gesto grosero. Dile que te envía el bueno de Ben.$b$b<Ben sonríe para sus adentros.>' WHERE `ID`=72899;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='크라사랑 주걱철갑상어와 그 망할 고블린은 크라사리 강의 가장 넓은 호수에 있을 거요. 바로 여기지.$b$b<벤이 손톱으로 당신의 지도에 구멍을 냅니다.>$b$b', `MaleText_loc4`='你可以在卡桑琅河最大的池塘找到卡桑琅白鲟和那个混蛋地精。就在卡桑琅丛林的中央。就是这儿。$b$b<班宏用爪子在你的地图上戳了一个洞。>$b$b', `MaleText_loc5`='你可以在喀撒朗河最大的那個池子找到喀撒朗匙吻鱘，以及那個混帳哥布林。就在這裡，喀撒朗蠻荒的正中央。$b$b<班的爪子在你的地圖戳破了個洞。>$b$b', `MaleText_loc7`='Encontrarás poliodóntidos de Krasarang y a ese mequetrefe goblin en el estanque más grande del río Krasari. Están justo en el centro de la Espesura Krasarang, justo aquí.$b$b<Ben hace un agujero en tu mapa con su garra.>' WHERE `ID`=72900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 봉우리에 있는 빈안 마을의 진위들이 오늘 물과 이야기를 나누었다 하오. 그리고 샤의 기운이 넘쳐나는 광경을 목격했다는군.$b $b이미 알고 있겠지만 가시고기는 상당히 난폭한 물고기라오. 샤의 기운을 맡은 놈들이 근처로 모여드는 건 시간문제겠지!$b $b그 말썽쟁이들을 잡아서 예민한 생태계를 보존하고 한 그물 가득 물고기도 낚아보시오.', `MaleText_loc4`='今天，昆莱山滨岸村的锦鱼人和水流沟通了一番，发现水中充满了煞能。$b $b你或许已经知道了，刺皮鱼是一种极具攻击性的鱼类。如果再给它们加点煞能，那你就能见识到什么叫疯狂了！ $b $b如果你能抓住那些愤怒的野兽，或许就能帮忙恢复当地脆弱的生态平衡……更不用说你还能抓到大量刺皮鱼。', `MaleText_loc5`='崑萊峰濱南村的錦魚人今天跟水談過了，而且它充斥著煞的能量。$b$b或許你已經知道，棘魚本來就相當凶猛，再加上煞的負面波動，那可就更加驚險刺激了!$b$b要是你能抓幾條憤怒的壞魚上來，說不定可以幫脆弱的生態系統恢復平衡...更別說還能抓到夢幻的大棘魚。', `MaleText_loc7`='Los jinyu de la Aldea Binan, en la Cima Kun-Lai, han hablado con el agua esta mañana y está a rebosar de sha.$b$bA lo mejor ya lo sabes, pero los peces espinosos son bastante agresivos. Y ya si lo mezclas con los sha, ¡te encuentras con un desastre completo!$b$bSi cazas unas cuantas bestias de esas, ayudarás a equilibrar el frágil ecosistema del lugar... Y además conseguirás un montón de peces espinosos.' WHERE `ID`=72901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가시고기는 정확히 이곳에 있소. 쿤라이 봉우리의 빈안 마을 바깥에 있는 해안에서 말이지. 어두컴컴하고 공기가 무거운 곳에는 어디든지 있을 거요.', `MaleText_loc4`='刺皮鱼就在地图的这个位置。昆莱山滨岸村的海滩上。你找天色最阴沉黑暗的地方就对了。', `MaleText_loc5`='棘魚出沒的地方就在地圖這裡，崑萊峰濱南村的岸邊，任何天色又陰又重的地方。', `MaleText_loc7`='Los peces espinosos están justo aquí; lo señalaré en tu mapa. Están en la costa de la Aldea Binan, en la Cima Kun-Lai. En cualquier sitio en el que el cielo esté oscuro y amenazador.' WHERE `ID`=72902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어젯밤, 사부 스노우드리프트께서 음영파의 일원들에게 수련을 가르치고 계셨소. 냉기 주먹을 전수하시는 중이었다는군. $b $b 좋은 소식은 수련생들 모두가 기술을 잘 익혔다는 것이오. 나쁜 소식은 그들이 물가에서 연습했던 까닭에 호랑이 구라미들이 살고 있던 호수가 꽁꽁 얼었다는 것이지!$b $b만약 오늘 호랑이 구라미를 낚을 생각이라면 그곳이 최적의 장소일 것이오.', `MaleText_loc4`='昨晚，雪流大师在昆莱山的影踪禅院授课。他教了弟子们如何施展冰霜之拳。$b $b好消息是，那些弟子们都做得很好。坏消息是，数百道冰霜拳劲被打入水中，冻住了周围湖泊中的虎皮丝足鱼！ $b $b如果你今天想抓一些虎皮丝足鱼，这或许就是最好的机会。', `MaleText_loc5`='昨晚，雪迅大師在崑萊峰的影潘僧院講課，教導弟子如何打出冰霜之拳。$b$b好消息是，弟子們的表現都很好。壞消息是，河裡多了幾百團的冰球，把旁邊湖裡頭的虎斑絲足魚都給凍住了!$b$b你要是想抓虎斑絲足魚的話，今天正是最好的機會。', `MaleText_loc7`='Anoche el maestro Ventisca Algente dio clases en el Monasterio del Shadopan, en la Cima Kun-Lai. Enseñó a sus alumnos a utilizar Puños de Escarcha.$b$bLa buena noticia es que a los alumnos les salió genial. ¡La mala es que cientos de bolas de hielo diminutas cayeron al agua y congelaron a los guramis tigre del lago de al lado!$b$bSi quieres pescar unos cuantos guramis tigre hoy, ese será el mejor lugar.' WHERE `ID`=72903;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쿤라이 봉우리의 음영파 수도원에 있는 탑 근처에서 호랑이 구라미를 본 적이 있다고. 바로... 여기지. $b$b<벤이 당신의 지도에 표시를 해줍니다.>$b$b', `MaleText_loc4`='虎皮丝足鱼可以在影踪派的宝塔附近找到……就是这里，在昆莱山。$b$b<班宏在你的地图上做了一个标记。>$b$b', `MaleText_loc5`='虎斑絲足魚就在崑萊峰影潘僧院的...這裡。$b$b<班在你的地圖上標出地點。>$b$b', `MaleText_loc7`='Los guramis tigre se hallan cerca de la pagoda del Monasterio del Shadopan... aquí, en la Cima Kun-Lai.$b$b<Ben marca un punto en tu mapa.>' WHERE `ID`=72904;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치광이 콰오파오에게 악의는 없다오. 정말이오. 그는 모구샨 궁전 앞에 있는 연못이 소원을 이루어준다고 믿었소. 동전을 던지면 염원을 실현케 해주는 그런 것 말이오.$b $b 그런데 이 양반이... 돈은 많은데 지성이 좀 떨어지나 보오. 내가 듣기로는 그가 세계의 왕이 되려고 연못에다 금화를 쏟아 붓고 있다고 하더군.$b $b안타깝게도, 보석 열대어가 가장 좋아하는 먹이는 물위로 낮게 날아다니는 반딧불이라오. 그런데 연못에서 일렁이는 금화를 반딧불로 착각하고 먹으려 한다는 것이지. $b $b 녀석들이 동전을 많이 삼키지 않았기를 바라오. 오늘은 보석 열대어를 낚기 적절하겠군. 덤으로 금화도 몇 닢 낚을 수 있을지도 모르오.', `MaleText_loc4`='疯狂的乔宝没有任何恶意的。真的。他听说魔古山宫殿前的池塘能够实现你的愿望，你懂的……就像许愿井什么的。$b $b而且……呃……这个可怜的家伙有钱却没有脑子。据我得到的最新消息，他还在往水里扔金币呢……希望自己能成为世界之王！ $b $b遗憾的是，珍宝斑马鱼最喜欢的食物就是在水面上飞舞的萤火虫。那些闪闪发光的金币将它们成群结队地吸引了出来。$b $b但愿那些可怜的小家伙不要吞食太多的金币。但如果你有需要的话，今天就是钓珍宝斑马鱼的好日子。你甚至还能从里面发现一些金币。', `MaleText_loc5`='瘋子樵寶其實是個沒什麼壞心眼的好人，他聽人家說魔古山宮前面的池塘可以實現願望，就像是...許願池一樣。$b$b嗯...然後...簡單來講，那傢伙的金子比腦子多。我聽說啊，他不知扔了多少金幣到水裡...希望能變成世界之王!$b$b遺憾的是，珠寶斑馬魚最愛吃飛在水面上方的螢火蟲，一閃一閃的金幣把它們從躲藏的地方都吸引出來了。$b$b希望那些可憐的魚兒沒有吞下太多枚金幣。想抓魚的話，今天就去抓珠寶斑馬魚吧，說不定還得找到幾枚金幣呢。', `MaleText_loc7`='Qao Pao el Excéntrico no lo hace con mala intención. En serio. Verás, le dijeron que el estanque enfrente del Palacio Mogu''shan otorgaba deseos, como si fuera un pozo de los deseos.$b$bY... bueno... El pobre tiene más oro que cerebro. Que yo sepa sigue tirando oro al agua, esperando convertirse en el rey del mundo.$b$bPor desgracia, la comida favorita de los danios enjoyados son las luciérnagas que vuelan bajo sobre el agua, así que el brillo de las monedas los atrae a montones.$b$bEspero que los pobrecitos no se estén tragando muchas monedas. Eso sí, si quieres pescar danios enjoyados, hoy es el día. A lo mejor hasta te sacas un par de monedas.' WHERE `ID`=72905;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미치광이 콰오파오와 보석 열대어들은 영원꽃 골짜기의 여름벌에 있다오. 이곳 주변이겠군. $b$b<벤이 지도에서 한 곳을 표시합니다.>$b$b', `MaleText_loc4`='疯狂的乔宝和他的珍宝斑马鱼就在锦绣谷的仲夏原上。大概就在这里。$b$b<班宏在你的地图上做了一个标记。>$b$b', `MaleText_loc5`='瘋子樵寶和那些珠寶斑馬魚應該就在恆春谷的夏之原，大概在這附近。$b$b<班在你的地圖上標出地點。>$b$b', `MaleText_loc7`='La última vez que vimos a Qao Pao el Excéntrico y sus danios enjoyados estaban en Los Campos Estivales, en el Valle de la Flor Eterna. Probablemente estarán por esta zona.$b$b<Ben marca un punto en tu mapa.>' WHERE `ID`=72906;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋군요. 비밀은 언제나 재밌는 법이죠.', `MaleText_loc4`='当然，我最喜欢听秘密了。', `MaleText_loc5`='好啊，我很想聽聽看秘密。', `MaleText_loc7`='Claro que quiero oír un secreto.', `FemaleText_loc1`='좋군요. 비밀은 언제나 재밌는 법이죠.', `FemaleText_loc4`='当然，我最喜欢听秘密了。', `FemaleText_loc5`='好啊，我很想聽聽看秘密。', `FemaleText_loc7`='Claro que quiero oír un secreto.' WHERE `ID`=72907;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔지 알 것 같군요. 그냥 제 지도에 표시해주겠습니까?', `MaleText_loc4`='太好了，你能帮我在地图上标出来吗？', `MaleText_loc5`='太好了，能不能幫我在地圖上標示出來?', `MaleText_loc7`='Mejor aún: ¿por qué no me lo señalas en el mapa sin más?', `FemaleText_loc1`='뭔지 알 것 같군요. 그냥 제 지도에 표시해주겠어요?', `FemaleText_loc4`='太好了，你能帮我在地图上标出来吗？', `FemaleText_loc5`='太好了，能不能幫我在地圖上標示出來?', `FemaleText_loc7`='Mejor aún: ¿por qué no me lo señalas en el mapa sin más?' WHERE `ID`=72908;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 물고기들은 통통 튀는 복덩이처럼 뛰어올라요!', `MaleText_loc4`='这些鱼上蹿下跳的，就像弹跳幸运符！', `MaleText_loc5`='魚兒跳上跳下的，就像彈跳不停的幸運星!', `MaleText_loc7`='¡Esos peces saltan más que un grisgrís saltarín!' WHERE `ID`=72909;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 낚시하는 법을 모릅니다. 가르쳐 주시겠습니까?', `MaleText_loc4`='我根本不会钓鱼！你能教我吗？', `MaleText_loc5`='我連怎樣釣魚都不會!可以教教我嗎?', `MaleText_loc7`='¡Ni siquiera sé pescar! ¿Me puedes enseñar?', `FemaleText_loc1`='저는 낚시하는 법을 몰라요. 가르쳐 주시겠어요?', `FemaleText_loc4`='我都不会钓鱼！你能教我吗？', `FemaleText_loc5`='我連怎樣釣魚都不會!可以教教我嗎?', `FemaleText_loc7`='¡Ni siquiera sé pescar! ¿Me puedes enseñar?' WHERE `ID`=72910;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혹시 낚시용품 있습니까?', `MaleText_loc4`='你这里有钓鱼用品吗？', `MaleText_loc5`='你有什麼釣魚的工具和補給品嗎?', `MaleText_loc7`='¿Tienes suministros de pesca, por un casual?', `FemaleText_loc1`='혹시 낚시용품 있나요?', `FemaleText_loc4`='你这里有钓鱼用品吗？', `FemaleText_loc5`='你有什麼釣魚的工具和補給品嗎?', `FemaleText_loc7`='¿Tienes suministros de pesca, por un casual?' WHERE `ID`=72911;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 호수에서는 행운의 냄새가 나요... 혹시, 물고기 입 냄새는 아니겠죠?', `MaleText_loc4`='这片湖上有好运的味道……还是鱼泡泡的味道？', `MaleText_loc5`='湖上飄著好運的味道...還是那是魚口氣散發的呢?', `MaleText_loc7`='Este lago huele a buena fortuna... Aunque a lo mejor solo huele a pescado.' WHERE `ID`=72912;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산을 오를 수 없다니, 물고기는 참 안됐어요. 내가 물고기 친구를 더 데려오면 기뻐할까요?', `MaleText_loc4`='真可惜，鱼都不能走路或爬山。如果我给它们多找一些鱼朋友回来，它们会高兴吗？', `MaleText_loc5`='真可惜，魚兒沒有步道也沒有山可以爬。要是我帶更多魚朋友過來，它們會開心嗎?', `MaleText_loc7`='Es una pena que los peces no tengan caminos que seguir ni montañas que escalar. Si les traigo más amigos peces, ¿serán felices?' WHERE `ID`=72913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개가 천둥보다 좋은 거겠지? 그렇담 나는 판다리아의 번개왕이 되고 싶어!', `MaleText_loc4`='闪电总比打雷好，对吧？嗯，那我希望能加冕为潘达利亚的闪电之王！', `MaleText_loc5`='閃電比雷霆要來得好，對吧?好，那我希望登基成為潘達利亞的雷電之王!', `MaleText_loc7`='El rayo es mejor que el trueno, ¿verdad? ¡Pues entonces quiero ser el Rey del Rayo de Pandaria!' WHERE `ID`=72914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='백만 골드를 갖고 싶어. 잠깐, 그러고 보니 벌써 백만 골드가 있구나... 그럼 백백만 골드를 갖고 싶어!', `MaleText_loc4`='我想要一百万金币……等等，我已经有一百万金币了……我想要十亿金币！', `MaleText_loc5`='我希望擁有一百萬金幣...等等，我已經有一百萬了...我要一百萬個一百萬金幣!!', `MaleText_loc7`='Deseo un millón de oro... Espera, ya tengo un millón de oro... ¡Deseo un billón de oro!' WHERE `ID`=72915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 생각났다! 스톰스타우트 양조장 안에 있는 맥주를 몽땅 갖고 싶어!', `MaleText_loc4`='噢，我知道了！我想要风暴烈酒酿造厂里所有的啤酒！', `MaleText_loc5`='喔!我知道了!我想要全風暴烈酒酒坊的啤酒!', `MaleText_loc7`='¡Ah, ya sé! ¡Deseo toda la cerveza de la Cervecería del Trueno!' WHERE `ID`=72916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 세상 최고의 보석으로 덮인 표범을 갖고 싶어! 참... 벌써 그걸 갖고 있는 친구가 있었던가?', `MaleText_loc4`='我想要一头镶满了全世界最珍贵珠宝的猎豹！等等，我有个朋友不是已经有一头了吗？', `MaleText_loc5`='我想要一頭用世上最好的寶石雕成的豹!等等，我有個朋友好像已經有這玩意了?', `MaleText_loc7`='¡Quiero una pantera con incrustaciones de las mejores joyas del mundo! Espera, ¿un amigo mío no tenía ya una de esas?' WHERE `ID`=72917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아냐, 아냐. 그거 말고.', `MaleText_loc4`='不不不，这不是我想要的。', `MaleText_loc5`='不不不，我要的不是這個。', `MaleText_loc7`='No, no, no, eso no es lo que quiero.' WHERE `ID`=72918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠, 다시 생각해 보니...', `MaleText_loc4`='唔，再好好想想……', `MaleText_loc5`='嗯，等等，我再想一下...', `MaleText_loc7`='Mmm... Pensándolo mejor...' WHERE `ID`=72919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 더 좋은 소원이 생각났어!', `MaleText_loc4`='噢，等等，我有了一个更好的主意！', `MaleText_loc5`='慢著，我有更好的主意了!', `MaleText_loc7`='¡Ah! ¡Ya lo tengo!' WHERE `ID`=72920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하! 어떠냐, 물에 사는 것들아! 이럴 줄은 몰랐지!', `MaleText_loc4`='哈哈！吃吧，你们这些笨鱼！', `MaleText_loc5`='哈哈，傻呼呼的臭魚!接招!', `MaleText_loc7`='¡Ja! ¡Chupaos esa, habitantes del agua!' WHERE `ID`=72921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 낚싯대 쓰는 게 항상 서툴렀지... 하지만 상관없어!', `MaleText_loc4`='我向来用不好鱼竿……但没关系！', `MaleText_loc5`='我老是拿不好釣魚竿...啊，無所謂啦!', `MaleText_loc7`='Nunca se me dio bien la caña de pescar... ¡Da igual!' WHERE `ID`=72922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뜨거운 폭탄 맛 좀 봐라, 생선 마귀들아!', `MaleText_loc4`='尝尝热乎乎的TNT炸药把，坏鱼！', `MaleText_loc5`='臭魚，來吃炸藥吧!', `MaleText_loc7`='¡Comeos el TNT, pescaditos!' WHERE `ID`=72923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희에게 불비가 내릴지니 육지의 군주 앞에 절해라!', `MaleText_loc4`='当火雨从天而降，臣服于你们陆上的霸主吧！', `MaleText_loc5`='拜倒在陸地王者的跟前!火雨，下吧!', `MaleText_loc7`='¡Arrodíllense ante su amo terrestre mientras el fuego llueve sobre ustedes!' WHERE `ID`=72924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우렁찬 음성이란 놈한테 놈은 허풍일 뿐이라고 전해!', `MaleText_loc4`='你要明白，那个大嗓门就会吹牛而已！', `MaleText_loc5`='告訴那個大聲公，他就只有聲音大而已!', `MaleText_loc7`='¡Puedes decirle a esa voz retumbante que perro ladrador, poco mordedor!' WHERE `ID`=72925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나 진짜 화났다고!', `MaleText_loc4`='这下我真的生气了！', `MaleText_loc5`='哼，我真的生氣了!', `MaleText_loc7`='¡Ahora sí que estoy enfadada!' WHERE `ID`=72926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나한테 이렇게 무례하게 구는 사람은 처음이라고!', `MaleText_loc4`='这是我见过的最粗鲁的行为！', `MaleText_loc5`='我這輩子從來沒有被人這樣羞辱過!', `MaleText_loc7`='¡Es lo más maleducado que he visto jamás!' WHERE `ID`=72927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아까는 물고기더니!... 이제는 너냐?', `MaleText_loc4`='先是鱼！……现在轮到你了？', `MaleText_loc5`='先是這些臭魚!...然後連你也來羞辱我!', `MaleText_loc7`='Primero los peces... ¿y ahora tú?' WHERE `ID`=72928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 미끈고기 먹으면 배 아프다.', `MaleText_loc4`='敢捞这些光板儿你就要倒霉了。', `MaleText_loc5`='吃滑滑魚有刺刺害肚肚痛痛。', `MaleText_loc7`='¡Si makaku manga la manduka, yo le hace kraku en los wakus!' WHERE `ID`=72929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끈고기 왕 많다... 호젠 미끈고기 너무 좋다!', `MaleText_loc4`='好多光板儿……猢狲就爱光板儿！', `MaleText_loc5`='好多滑滑魚...猴人愛吃滑滑魚!', `MaleText_loc7`='Kuánta manduka... ¡A los hozen nos enkanta la manduka!' WHERE `ID`=72930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁜 미끈고기 내 주둥이 때렸다!', `MaleText_loc4`='该死的光板儿，就会给我惹麻烦！', `MaleText_loc5`='臭滑滑魚咬我!', `MaleText_loc7`='¡La manduka me ha hecho kraku en el kuku!' WHERE `ID`=72931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미끈고기 우낏 후루룩 좋아한다... 호젠도 우낏 후루룩 좋아한다!', `MaleText_loc4`='光板儿喜欢蠢蛋的去死……猢狲也喜欢蠢蛋去死！', `MaleText_loc5`='滑滑魚愛怪怪人的餌...猴人也愛怪怪人的餌!', `MaleText_loc7`='A la manduka le enkanta el ruko de makaku... ¡A los hozen les enkanta más!' WHERE `ID`=72932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 불행한 잔달라 트롤은 피범벅이고 짓밟힌 흔적이 가득합니다. 이미 죽은 그의 표정에는 공포가 아닌 굳은 결의가 보입니다.$b$b아직 감지 못한 눈은 미동도 하지 않은 채 하늘만 바라보고 있지만 엄청난 열광에 가득 차있습니다. 아직 촉촉한 피부 위로 파리 하나가 기어 다닙니다.', `MaleText_loc4`='这个不幸的赞达拉巨魔已经被刺死被踩烂了。他脸上的表情并不是恐惧，而是一种视死如归的决心。$b$b他睁大的眼睛一眨不眨地瞪着天空，里面燃烧着狂热和兴奋。一只苍蝇在依然湿润的眼球上爬行着。', `MaleText_loc5`='這個不幸的贊達拉食人妖慘遭開膛破肚、踐踏而死。雖然他已經死了，但他臉上的表情不僅毫無懼色，而且還十分堅定。$b$b睜開的雙眼彷彿還洋溢著熱情的火光，直挺挺地盯著天空。然後，有隻蒼蠅在他依然濕潤的臉上爬來爬去。', `MaleText_loc7`='Este desafortunado Zandalari ha sido corneado y aplastado. La expresión de su rostro no transmite miedo, sino una determinación férrea, hasta en la muerte.$b$bSus ojos abiertos parecen arder con una pasión intensa, a pesar de estar fijos en el cielo. Una mosca recorre la superficie de los mismos, aún húmeda.' WHERE `ID`=72933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폐하께서는 안두인 왕자님께서 회복되실 때까지 영원꽃 골짜기에 계시길 바라셨습니다. 하지만 왕자님께서는 계속 돌아다니면서 사람들과 이야기를 하려고 하십니다. 왕자님이 폐하의 말씀을 따르지 않을 때 저희는 어떻게 해야 합니까?$B$B바싹 붙어서 왕자님께서 이상한 일에 휘말리지 않도록 하는 수밖에요.', `MaleText_loc4`='国王希望安度因王子留在锦绣谷直至康复。但王子坚持要四处走走，并与人们多聊聊。当王子想要违抗国王时，我们又能怎么办呢？$b$b最好还是跟紧他，免得他惹上什么麻烦。', `MaleText_loc5`='國王希望安杜因王子能待在恆春谷好好養傷，但王子殿下堅持要四處走走、與人交談。王子執意要違背國王，我們這些護衛又能怎麼辦?$b$b也只能跟緊一點、別讓他惹上麻煩。', `MaleText_loc7`='El Rey quería que el príncipe Anduin se quedara en el valle hasta que se recuperase, pero el príncipe insiste en pasearse por ahí y hablar con la gente. ¿Qué podemos hacer cuando un príncipe desobedece a su rey?$b$bLo mejor es seguirlo e impedir que se meta en líos.' WHERE `ID`=72934;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<손으로 검을 붙든 채 당신을 노려보는 경호원>$b$b왕자님께서 조용히 이야기하고자 하신다, $c. 만에 하나 말썽을 피우면 똑같이 갚아 주겠다.', `MaleText_loc4`='<卫士怒视着你，紧紧抓住腰间的佩剑。>$b$b王子只想安静地聊聊，$c。如果你敢惹麻烦，我们一定会加倍奉还。', `MaleText_loc5`='<侍衛怒目瞪視著你，手牢牢握住他的劍柄。>$b$b王子殿下希望能靜靜地談一談，$c。要是你膽敢惹出任何麻煩，我們絕對不會客氣。', `MaleText_loc7`='<El guardaespaldas te lanza una mirada amenazadora mientras su puño se cierra alrededor de la empuñadura de su espada.>$b$bEl príncipe quiere hablar tranquilamente, $c. Si causas alboroto, nosotros haremos lo mismo.' WHERE `ID`=72935;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<심중을 꿰뚫어 보려는 듯 당신을 아래위로 훑어보는 타우렌 성기사>$b$b당신을 적으로 생각하지는 않소, $c. 나는 백호사에서 이 인간 왕자를 만난 적이 있소. 또 가끔은 그가 우리 대부족장님이신 바인 님에 대해 이야기하거나 전쟁과 평화에 대해 논하려고 나를 찾기도 하지.$b$b<성기사와 왕자의 경호원들은 문득문득 의심에 찬 눈길을 교환합니다.>', `MaleText_loc4`='<牛头人圣骑士上下打量着你，好像在猜测你的意图。>$b$b我无意与你为敌，$c。人类王子和我在白虎寺见过，他常常来找我聊我们的大酋长贝恩，并讨论战争与和平那些事。$b$b<圣骑士和王子的卫士不断用疑虑的眼神互相打量着。>', `MaleText_loc5`='<牛頭人上下打量著你，彷彿在評估你的意圖。>$b$b我無意與你為敵，$c。人類王子是在白虎寺遇見我的，而且他經常找我談談我的酋長貝恩，還有討論戰爭與和平的事情。$b$b<這位聖騎士和王子的侍衛不時會以互不信任的眼光看著對方。>', `MaleText_loc7`='<El tauren paladín te observa como si quisiera adivinar tus intenciones.>$b$bNo albergo hostilidad alguna, $c. El príncipe humano y yo nos conocimos en el Templo del Tigre Blanco, y a veces me pregunta por mi gran jefe, Baine, o hablamos de temas de guerra y paz.$b$b<El paladín y los guardaespaldas del príncipe intercambian miradas de desconfianza de vez en cuando.>' WHERE `ID`=72936;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하시오, $c!$b$b바인 블러드후프 대부족장님께서는 가로쉬가 이 인간 왕자를 무자비하게 공격한 것을 알고 괴로워하셨소. 얼라이언스의 소행 중에는 통탄할 일이 많지만, 그 중 어느 것도 이 작은 인간 탓은 아니오.$b$b나는 백호사에서 왕자를 만난 적이 있소. 나는 내 명예를 걸고 그의 신변을 지켜 주겠노라 약조했지.$b$b<그의 말과 왕자의 따뜻한 태도에도 불구하고, 타우렌 성기사는 방 구석에 있는 충직한 왕실 경호원들의 의심에 찬 눈길을 받고 있습니다.>', `MaleText_loc4`='欢迎你，$c！$b$b大酋长贝恩·血蹄得知加尔鲁什野蛮地袭击了人类王子后，一直非常忧虑。我们有许多仇视联盟的原因，但那都不是这个小家伙的错。$b$b王子和我在白虎寺见过。我用自己的荣誉发誓，一定会保证他的安全。$b$b<尽管这样说了，又有王子的热情介绍，但房间角落里的皇家卫士依然狐疑地打量着这位牛头人圣骑士。>', `MaleText_loc5`='你好，$c!$b$b貝恩·血蹄酋長對卡爾洛斯竟然無情地攻擊人類王子這件事，感到非常不開心。我們跟聯盟之間的衝突很多，但帳不該算在那個小傢伙的頭上。$b$b王子跟我在白虎寺見過，我以我的榮耀起誓，我一定會全力保護他的安全。$b$b<儘管王子對他很友善、儘管他已做出了承諾，待在角落的王家侍衛依然對他投以懷疑的目光。>', `MaleText_loc7`='¡Hola, $c!$b$bEl gran jefe Baine Pezuña de Sangre se quedó horrorizado al enterarse de que Garrosh atacó salvajemente al príncipe humano. Tenemos muchas razones para estar en guerra con la Alianza, pero este joven no tiene la culpa de nada.$b$bEl príncipe y yo nos conocimos en el Templo del Tigre Blanco. He jurado por mi honor que haré lo posible por mantenerlo a salvo.$b$b<A pesar de sus palabras y la amabilidad con la que se tratan el príncipe y él, los guardaespaldas reales de la esquina le lanzan miradas de desconfianza.>' WHERE `ID`=72937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안 돼요. 그만해요. 당장 그만하세요!', `MaleText_loc4`='不——住手。立刻住手！', `MaleText_loc5`='不 - 住手。立刻住手!', `MaleText_loc7`='¡No! ¡Alto! ¡Parad inmediatamente!' WHERE `ID`=72938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만두시오! 지금 여기서만은!', `MaleText_loc4`='快住手！此时此地，你们不能这么做！', `MaleText_loc5`='住手!別在這裡-停!', `MaleText_loc7`='¡Bajad las armas! ¡No es ni el momento ni el lugar!' WHERE `ID`=72939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='래시온은 살아 있는 마지막 검은용이라고 주장해요. 그게 정말일까요?$b$b그가 세상을 보는 관점은 정말 알 수가 없어요. 사람 목숨을 귀하게 여기는지, 소모품으로 여기는지도 모르겠고요. 그래도 좋은 대화 상대긴 해요.', `MaleText_loc4`='拉希奥自称是最后一条活着的黑龙。你相信吗？$b$b他对世界的看法非常古怪。我不知道他是否珍视人类的生命，还是把它看做消耗品！但我真的很喜欢跟他聊天。', `MaleText_loc5`='怒西昂說他是碩果僅存、最後的黑龍，你覺得是真的嗎?$b$b他的世界觀和對事情的看法真的很不一樣，只是有時候我實在分不清楚，在他心中人類的性命到底是寶貴、還是低賤!不過，我還是蠻喜歡跟他聊聊的。', `MaleText_loc7`='Wrathion afirma ser el último dragón Negro con vida. ¿Crees que es verdad?$b$bTiene una visión del mundo de lo más curiosa. No sé si la vida humana le parece valiosa o prescindible, pero desde luego disfruto hablando con él.' WHERE `ID`=72940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<당신이 왕자에게 말을 거는 순간 경호원들이 다가섭니다.>$b$b괜찮아요. 그냥 친구하고 이야기하고 싶은 것뿐이에요. 여긴 전선에서 멀잖아요. 문명인답게 대화를 할 수 있는 안전한 곳이 세상에 조금은 있어야 하지 않겠어요?$b$b이리 오세요! 앉아서 함께 이야기해요!', `MaleText_loc4`='<当你对王子说话时，安度因的卫士靠了过来。>$b$b没关系。我只想跟我的朋友聊聊。我们在这里远离战场。这世界上还有地方能容得下一场文明的对话吗？$b$b来，坐吧！跟我们聊聊！', `MaleText_loc5`='<在你向安杜因開口的同時，他的侍衛立刻靠了過來。>$b$b沒事，我只是跟朋友講講話而已。離戰場前線那麼遠，總有地方可以安全地說說話吧?$b$b來，請坐!一起聊聊!', `MaleText_loc7`='<Los guardaespaldas de Anduin se acercan en cuanto le diriges la palabra.>$b$bNo pasa nada, solo quiero hablar con mi $gamigo:amiga;. Aquí estamos muy lejos del frente. ¿No queda ningún sitio en el mundo en el que se pueda mantener una conversación civilizada?$b$b¡Ven, siéntate! ¡Charla con nosotros!' WHERE `ID`=72941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이것 말씀이세요? <목발을 가리키는 안두인>$b$b가로쉬 헬스크림이 고대 모구 유물을 이용해서 샤의 힘을 불러내 조종하려 했어요. 제가 그를 막을 방법을 찾긴 했지만, 직접 상대하겠다고 나선 건 잘못이었던 것 같아요. 그는 제가 죽은 줄 알고, 실패한 계획의 잔해 밑에 저를 묻고는 가 버렸죠. 온몸의 뼈란 뼈는 다 부러졌던 게 분명해요.$b$b판다렌 운무사들 덕분에 몸을 일으킬 수 있게 됐지만, 혼자 힘으로 걸으려면 시간이 좀 걸릴 거예요.', `MaleText_loc4`='噢，这个？<安度因指了指他的拐杖。>$b$b加尔鲁什·地狱咆哮试图用一件古老的魔古神器召唤并控制煞能。我设法阻止了他，但我好像不该亲自去对付他。他以为我死了，让我就那么埋在那个失败计划的废墟下。我发誓，他把我全身所有的骨头都打碎了。$b$b熊猫人织雾者让我重新站了起来，但我恐怕还需要一些时间才能独立行走。', `MaleText_loc5`='哦，這個啊? <安杜因指指他的柺杖。>$b$b卡爾洛斯·地獄吼企圖用一件古老的魔古神器來召喚和控制煞，我發現了阻止他的方法，但或許我不該強出頭自己出馬的。雖然我阻止了他，但是我也被崩毀的神器活埋，所以他大概以為我已經死了。我發誓，我全身的骨頭好像都被他給打碎了。$b$b熊貓人織霧者把我救了出來，並且治好了我的傷，不過我可能得再修養一陣子才能不靠柺杖自由行動。', `MaleText_loc7`='Ah, ¿esto?$b$B<Anduin señala su muleta.>$b$bGarrosh Grito Infernal intentó utilizar un antiguo artefacto mogu para invocar y controlar la energía del sha. Encontré la forma de detenerlo, pero no debería haberme enfrentado a él solo. Me dio por muerto y me dejó sepultado entre los restos de su plan fallido. Te juro que me rompió todos los huesos del cuerpo.$b$bLos tejedores de niebla pandaren me curaron, pero todavía tardaré un tiempo en poder andar sin ayuda.' WHERE `ID`=72942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리와 검은용군단의 관계는 잘 아시죠? 전 여군주 프레스톨, 오닉시아가 우리 가족에게 한 짓을 쉽게 잊지 못할 거예요. 그게 래시온을 찾아낸 이유인지도 모르고요.$b$b<탁자 너머에 있는 특이한 동료를 흘끗 쳐다보는 안두인>$b$b그런데... 그는 다른 검은용과는 달라요. 안 그런가요? 아주 솔직하면서도 항상 뭔가 숨기고 있죠. 제 생각과는 전혀 달라요.', `MaleText_loc4`='你知道我们和黑龙军团的往事，对吧？我不会那么快忘记普瑞斯托女士——奥妮克希亚——对我的家族所做的一切。或许这就是我来找拉希奥的原因。$b$b<安度因看了看桌子对面那位不同寻常的同伴。>$b$b可是……他和其他黑龙不一样，不是吗？他非常坦诚，却又总在隐瞒着什么。和我预想中完全不同。', `MaleText_loc5`='你知道我們跟黑龍之間的歷史吧?我永遠忘不了普瑞斯托女士，也就是奧妮克希亞對我的家人所做的事情。也許，那正是我要來找怒西昂的原因。$b$b<安度因望向桌子對面那位不尋常的夥伴。>$b$b只不過...他跟其他的黑龍都不一樣，對吧?他異常地誠實坦率，但同時又有所隱瞞，跟我原本的想像實在落差很大。', `MaleText_loc7`='Ya conoces nuestra historia con el Vuelo Negro, ¿verdad? Nunca olvidaré lo que Lady Prestor, Onyxia, le hizo a mi familia. A lo mejor es por eso por lo que busqué a Wrathion.$b$b<Anduin mira de reojo a su curioso compañero.>$b$bPero... no se parece a los demás dragones Negros, ¿a que no? Es totalmente sincero y al mismo tiempo siempre está ocultando algo. No es lo que me esperaba.' WHERE `ID`=72943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='래시온은 살아 있는 마지막 검은용이라고 주장해요. 그게 정말일까요? 아웃랜드 어디엔가는 아직 있지 않았던가요?$b$b어쨌든 래시온은 흥미로운 인물이에요. 제가 만나 본 용들과는 아주 다르죠. 정말, 아주 극도로 솔직해요. 그가 필멸자의 생명을 귀하게 여기는지, 소모품으로 여기는지 저는 파악할 수가 없어요.', `MaleText_loc4`='拉希奥自称是最后一条活着的黑龙。你相信吗？会不会还有其他黑龙躲在外域的某个地方呢？$b$b无论如何，我发现他很特别。他和我见过的任何一条龙都不一样。他很坦诚，简直坦诚得过分了。我不知道他是否珍视人类的生命，还是把它看做消耗品。', `MaleText_loc5`='怒西昂說他是碩果僅存、最後的黑龍，你覺得是真的嗎?外域不是還有別的黑龍嗎?$b$b不過，我覺得他真的很妙，跟我遇過的其他龍族都不一樣。他很誠實，甚至太過實話實說、太過直接了。有時候我實在分不清楚，在他心中凡人的性命到底是寶貴、還是低賤。', `MaleText_loc7`='Wrathion afirma ser el último dragón Negro con vida. ¿Crees que es verdad? ¿No había más en alguna parte de Terrallende?$b$bEn cualquier caso, me parece fascinante. No se parece a ningún otro dragón que haya conocido. Es sincero, a veces demasiado. No sé si las vidas mortales le parecen lo más valioso del mundo o totalmente prescindibles.' WHERE `ID`=72944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게 된 겁니까? 다쳤습니까?', `MaleText_loc4`='你的腿怎么了？你受伤了？', `MaleText_loc5`='你的腿怎麼了?你受傷了嗎?', `MaleText_loc7`='¿Qué te ha pasado en la pierna? ¿Estás herido?', `FemaleText_loc1`='어떻게 된 거죠? 다쳤나요?', `FemaleText_loc4`='你的腿怎么了？你受伤了？', `FemaleText_loc5`='你的腿怎麼了?你受傷了嗎?', `FemaleText_loc7`='¿Qué te ha pasado en la pierna? ¿Estás herido?' WHERE `ID`=72945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 가족이 검은용군단에게 그런 일을 당했는데, 어떻게 검은용을 믿을 수가 있습니까?', `MaleText_loc4`='你怎么能相信一条黑龙呢？尤其是在他们对你的家族做了那些事之后？', `MaleText_loc5`='黑龍害慘了你們家，你怎麼還能相信黑龍?', `MaleText_loc7`='¿Cómo puedes confiar en un dragón Negro después de lo que sufrió tu familia en sus manos?', `FemaleText_loc1`='당신 가족이 검은용군단에게 그런 일을 당했는데, 어떻게 검은용을 믿을 수가 있죠?', `FemaleText_loc4`='你怎么能相信一条黑龙呢？尤其是在他们对你的家族做了那些事之后？', `FemaleText_loc5`='黑龍害慘了你們家，你怎麼還能相信黑龍?', `FemaleText_loc7`='¿Cómo puedes confiar en un dragón Negro después de lo que sufrió tu familia en sus manos?' WHERE `ID`=72946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='래시온을 어떻게 생각하십니까?', `MaleText_loc4`='你对拉希奥怎么看？', `MaleText_loc5`='你對怒西昂有什麼看法?', `MaleText_loc7`='¿Qué piensas de Wrathion?', `FemaleText_loc1`='래시온을 어떻게 생각하세요?', `FemaleText_loc4`='你对拉希奥怎么看？', `FemaleText_loc5`='你對怒西昂有什麼看法?', `FemaleText_loc7`='¿Qué piensas de Wrathion?' WHERE `ID`=72947;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 왕자 폐하께 인정받는다면 나도 자네를 인정하겠네. 왕자 폐하가 시키시는 일을 더 하게.$b$b그때까지는 오지 말게. 자네에겐 팔 게 없으니.', `MaleText_loc4`='只要你赢得了黑王子殿下的尊重，那你也就赢得了我的尊重。再去完成一些他给你的任务吧。$b$b在此之前，请你先走开。我没有什么可卖给你的。', `MaleText_loc5`='要等你贏得黑龍王子的尊敬，我才會開始尊敬你。$b$b在還沒贏得殿下的認可之前，快滾吧，我不會賣你東西的。', `MaleText_loc7`='Te ganarás mi respeto cuando te hayas ganado el de su majestad, el Príncipe Negro. Cumple los encargos que te asigna.$b$bHasta entonces, vete. No tengo nada que venderte.' WHERE `ID`=72948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔네. 나는 검은 왕자 폐하께 받은 보상을 교체해 줄 수 있다네. 물론 대가는 치러야 하지.', `MaleText_loc4`='欢迎。我可以帮你找回从黑王子那里得到的奖励……只需要一点点代价。', `MaleText_loc5`='歡迎。我能幫你換掉黑龍王子給你的任何獎勵...當然，要酌收點費用。', `MaleText_loc7`='Te doy la bienvenida. Puedo reponer todas las recompensas que te haya dado el Príncipe Negro... por un módico precio.' WHERE `ID`=72949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보상으로 받은 물건을 교체하려면 어떻게 해야 합니까?', `MaleText_loc4`='我该怎么找回以前从你那里得到的奖励？', `MaleText_loc5`='我要怎樣換掉你先前送給我的獎勵?', `MaleText_loc7`='¿Cómo puedo reponer los objetos que me diste en otra ocasión?', `FemaleText_loc1`='보상으로 받은 물건을 교체하려면 어떻게 해야 하죠?', `FemaleText_loc4`='我该怎么找回以前从你那里得到的奖励？', `FemaleText_loc5`='我要怎樣換掉你先前送給我的獎勵?', `FemaleText_loc7`='¿Cómo puedo reponer los objetos que me diste en otra ocasión?' WHERE `ID`=72950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 주점에서 검은갈퀴 병참장교를 찾아라. 내가 보상으로 준 적이 있는 물건을 새로 받을 수 있다... 물론 대가는 치러야지. 알고 있겠지만, 내가 사용하는 재료는 싸지가 않거든.', `MaleText_loc4`='在酒肆里找到我的黑爪军需官。他可以帮你找回我先前给你的任何奖励……当然是收费的。显然你已经注意到了，我用的材料可是一点儿也不便宜。', `MaleText_loc5`='到客棧去找我的黑爪軍需官，他可以重新供應我先前送過你的任何獎勵...當然，要酌收點費用。相信你一定能明白，我用的材料可是一點都不便宜。', `MaleText_loc7`='Mi intendente Garranegra está aquí, en la taberna. Puede reponerte todas las recompensas que te he dado hasta ahora... por un módico precio, claro está. Como habrás tenido ocasión de comprobar, los materiales con los que trabajo están muy lejos de ser baratos.' WHERE `ID`=72951;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈구나! 훌륭하다. 이제 시작할 수 있겠구나.', `MaleText_loc4`='你成功了！太好了。现在我们可以开始了。', `MaleText_loc5`='你辦到了!太好了，我們可以開始了。', `MaleText_loc7`='¡Has llegado! Genial. Ya podemos empezar.' WHERE `ID`=72952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다!', `MaleText_loc4`='我准备好了！', `MaleText_loc5`='我準備好了!', `MaleText_loc7`='¡Estoy listo!', `FemaleText_loc1`='준비됐어요!', `FemaleText_loc4`='我准备好了！', `FemaleText_loc5`='我準備好了!', `FemaleText_loc7`='¡Estoy lista!' WHERE `ID`=72953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:136898|h[화염방사기]|h|r로 여기저기를 마구 태웁니다!', `MaleText_loc4`='%s用|cFFFF0000|Hspell:136898|h[火焰喷射器]|h|r横扫整片区域！', `MaleText_loc5`='%s正在用|cFFFF0000|Hspell:136898|h[火焰噴射]|h|r橫掃攻擊整塊地方!', `MaleText_loc7`='¡%s barre la zona con su |cFFFF0000|Hspell:136898|h[Lanzallamas]|h|r!' WHERE `ID`=72954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 근접 공격 범위 안에서 적을 찾을 수 없어 |cFFFF0000|Hspell:136854|h[죽음의 응시]|h|r를 사용합니다!', `MaleText_loc4`='%s在近战范围内找不到敌人，因此转而使用|cFFFF0000|Hspell:136854|h[死亡凝视]|h|r了！', `MaleText_loc5`='%s找不到近戰目標，轉而開始使用它的|cFFFF0000|Hspell:136854|h[死亡凝視]|h|r!', `MaleText_loc7`='¡%s no encuentra ningún objetivo cuerpo a cuerpo, así que recurre a |cFFFF0000|Hspell:136854|h[Mirada de la muerte]|h|r!' WHERE `ID`=72955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:137074|h[땅 울리기]|h|r로 주위의 적을 공격하려고 합니다!', `MaleText_loc4`='%s准备使用|cFFFF0000|Hspell:137074|h[裂地猛击]|h|r来打击附近的敌人！', `MaleText_loc5`='%s準備使用|cFFFF0000|Hspell:137074|h[地面猛擊]|h|r攻擊附近的目標!', `MaleText_loc7`='¡%s se prepara para machacar a los objetivos cercanos con |cFFFF0000|Hspell:137074|h[Embate en el suelo]|h|r!' WHERE `ID`=72956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 강력한 |cFFFF0000|Hspell:136847|h[충격파]|h|r를 준비합니다!', `MaleText_loc4`='%s施放出了剧烈的|cFFFF0000|Hspell:136847|h[震荡波]|h|r！', `MaleText_loc5`='%s準備釋放出一道強大的|cFFFF0000|Hspell:136847|h[震懾波]|h|r!', `MaleText_loc7`='¡%s prepara una enorme |cFFFF0000|Hspell:136847|h[Ola de choque]|h|r!' WHERE `ID`=72957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:138019|h[번개 조련봉]|h|r을 사용합니다! 사우록에게서 떨어지십시오!', `MaleText_loc4`='%s引导了|cFFFF0000|Hspell:138019|h[闪电之刺]|h|r！快远离那头蜥蜴人！', `MaleText_loc5`='%s開始施放|cFFFF0000|Hspell:138019|h[閃電刺擊]|h|r!遠離那個薩烏洛克!', `MaleText_loc7`='¡%s usa |cFFFF0000|Hspell:138019|h[Punzada de relámpagos]|h|r! ¡Aléjate del saurok!' WHERE `ID`=72958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르독이 쓰러진 아군을 되살려 전투에서 자신을 돕게 합니다!', `MaleText_loc4`='寇多克复活一名阵亡的盟友来协助他战斗！', `MaleText_loc5`='柯爾多克復活了一位倒地的夥伴來協助他戰鬥!', `MaleText_loc7`='¡Kor''dok resucita a un aliado caído para que le ayude en combate!' WHERE `ID`=72959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방출된 전류가 정령의 몸으로 실체화됩니다!', `MaleText_loc4`='避雷针施放的电能形成了一个元素生物！', `MaleText_loc5`='釋放出來的電流實體化成閃電元素了!', `MaleText_loc7`='¡La electricidad descargada se manifiesta en forma de elemental!', `FemaleText_loc1`='방출된 전류가 정령의 몸으로 실체화됩니다!', `FemaleText_loc4`='避雷针施放的电能形成了一个元素生物！', `FemaleText_loc5`='釋放出來的電流實體化成閃電元素了!', `FemaleText_loc7`='¡La electricidad descargada se manifiesta en forma de elemental!' WHERE `ID`=72960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222[감전]|r되었습니다. 주위에 있는 번개 막대에 전류를 방출할 수 있습니다.', `MaleText_loc4`='你被|cFFFF2222[电击]|r了。你可以对附近的一根避雷针释放电能。', `MaleText_loc5`='你受到了|cFFFF2222[蓄電]|r的影響，可以到閃電之柱的旁邊釋放身上的電流。', `MaleText_loc7`='|cFFFF2222[Electrificado]|r Puedes descargar la electricidad en una vara de relámpagos cercana.', `FemaleText_loc1`='|cFFFF2222[감전]|r되었습니다. 주위에 있는 번개 막대에 전류를 방출할 수 있습니다.', `FemaleText_loc4`='你被|cFFFF2222[电击]|r了。你可以对附近的一根避雷针释放电能。', `FemaleText_loc5`='你受到了|cFFFF2222[蓄電]|r的影響，可以到閃電之柱的旁邊釋放身上的電流。', `FemaleText_loc7`='|cFFFF2222[Electrificado]|r Puedes descargar la electricidad en una vara de relámpagos cercana.' WHERE `ID`=72961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 명령이야말로 내 무기의 날이 향해야 하는 방향이오.', `MaleText_loc4`='我的剑永远指向酋长所指的方向。', `MaleText_loc5`='大酋長指誰我就砍誰。', `MaleText_loc7`='Mi espada seguirá al Jefe de Guerra a donde él ordene.' WHERE `ID`=72962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방법은 하나밖에 없습니다. 의회에는 들어가야겠어요. 농장은...', `MaleText_loc4`='现在只有一个办法了。我一定要加入议会。至于农场……', `MaleText_loc5`='只有一個辦法，我必須加入議會。至於農莊...', `MaleText_loc7`='Solo hay una solución. Debo incorporarme al consejo. En cuanto a la granja...' WHERE `ID`=72963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 때문에 난리가 났구나, $n. 그래도 보람이 있었다.', `MaleText_loc4`='我们惹上了大麻烦，$n。但一切都是值得的。', `MaleText_loc5`='我們還真是惹出了不少麻煩啊，$n，但這一切都是值得的。', `MaleText_loc7`='Nos hemos metido en muchos líos, $n, pero ha merecido la pena.' WHERE `ID`=72964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_frost_piercing chill:20|t당신은 |cFFF00000|Hspell:139866|h[얼음 격류]|h|r의 대상이 되었습니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_frost_piercing chill:20|t你成为了|cFFF00000|Hspell:139866|h[寒冰洪流]|h|r的目标！', `MaleText_loc5`='|TInterface\\Icons\\spell_frost_piercing chill:20|t你變成|cFFF00000|Hspell:139866|h[寒冰洪流]|h|r的目標了!', `MaleText_loc7`='|TInterfaceIconsspell_frost_piercing chill:20|t¡Eres el objetivo de un |cFFF00000|Hspell:139866|h[Torrente de hielo]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_frost_piercing chill:20|t당신은 |cFFF00000|Hspell:139866|h[얼음 격류]|h|r의 대상이 되었습니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_frost_piercing chill:20|t你成为了|cFFF00000|Hspell:139866|h[寒冰洪流]|h|r的目标！', `FemaleText_loc5`='|TInterface\\Icons\\spell_frost_piercing chill:20|t你變成|cFFF00000|Hspell:139866|h[寒冰洪流]|h|r的目標了!', `FemaleText_loc7`='|TInterfaceIconsspell_frost_piercing chill:20|t¡Eres el objetivo de un |cFFF00000|Hspell:139866|h[Torrente de hielo]|h|r!' WHERE `ID`=72965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_volatilefire:20|t당신은 |cFFF00000|Hspell:139822|h[잿불]|h|r에 걸렸습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_volatilefire:20|t你受到了|cFFF00000|Hspell:139822|h[燃烬]|h|r的影响！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_volatilefire:20|t你受到了|cFFF00000|Hspell:139822|h[燼火]|h|r的影響!', `MaleText_loc7`='|TInterfaceIconsinv_misc_volatilefire:20|t¡Te ha afectado |cFFF00000|Hspell:139822|h[Cenizas]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_volatilefire:20|t당신은 |cFFF00000|Hspell:139822|h[잿불]|h|r에 걸렸습니다!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_volatilefire:20|t你受到了|cFFF00000|Hspell:139822|h[燃烬]|h|r的影响！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_volatilefire:20|t你受到了|cFFF00000|Hspell:139822|h[燼火]|h|r的影響!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_volatilefire:20|t¡Te ha afectado |cFFF00000|Hspell:139822|h[Cenizas]|h|r!' WHERE `ID`=72966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재연마, 형상변환, 공허 보관소', `MaleText_loc4`='重铸，幻化，虚空仓库', `MaleText_loc5`='重鑄，塑形，虛空倉庫。', `MaleText_loc7`='Reforjar, transfiguración, depósito del vacío', `FemaleText_loc1`='재연마, 형상변환, 공허 보관소', `FemaleText_loc4`='重铸，幻化，虚空仓库', `FemaleText_loc5`='重鑄，塑形，虛空倉庫。', `FemaleText_loc7`='Reforjar, transfiguración, depósito del vacío' WHERE `ID`=72967;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠를 가지고 있습니다. 한바탕 해보죠. [개인 인스턴스 대기열에 등록합니다.]', `MaleText_loc4`='我拿到钥匙了，我们开始突击吧。[排队等待单人副本。]', `MaleText_loc5`='我拿到鑰匙，可以出發了。 [加入單人副本的佇列。]', `MaleText_loc7`='Tengo la llave. Empecemos el asalto. [Únete a la cola para hacer la estancia en solitario.]', `FemaleText_loc1`='열쇠를 가지고 있습니다. 한바탕 해보죠. [개인 인스턴스 대기열에 등록합니다.]', `FemaleText_loc4`='我拿到钥匙了，我们开始突击吧。[排队等待单人副本。]', `FemaleText_loc5`='我拿到鑰匙，可以出發了。 [加入單人副本的佇列。]', `FemaleText_loc7`='Tengo la llave. Empecemos el asalto. [Únete a la cola para hacer la estancia en solitario.]' WHERE `ID`=72968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저도 돕고 있어요!', `FemaleText_loc4`='我很乐意帮忙！', `FemaleText_loc5`='我已經在幫忙啦!', `FemaleText_loc7`='¡Estoy ayudando!' WHERE `ID`=72969;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아빠가 모르는 사람하고 이야기하지 말랬어요.', `FemaleText_loc4`='爸爸说，不要跟陌生人说话。', `FemaleText_loc5`='爸爸說不可以隨便跟陌生人說話。', `FemaleText_loc7`='Zarpapá me dice que no hable con desconocidos.' WHERE `ID`=72970;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저는 "아홉열"까지 다아 셀 수 있어요. 들어 봐요!$B$B<손가락과 발가락으로 셈을 하는 밀리>$B$B하나, 둘, 셋, 다섯, 여섯, 음... 일곱, 여덟, 아홉열!$B$B어, 하나 빠뜨렸네...', `FemaleText_loc4`='我可以一直数到“九——十”哦。听好了！$B$B<米莉开始掰手指头和脚趾头。>$B$B一，二，三，五，六，嗯……七，八，九——十！$B$B等等，我漏了一个……', `FemaleText_loc5`='我可以一路數到「九十」了。我數給你聽!$B$B<米莉開始數起手指和腳指。>$B$B一、二、三、五、六、嗯...七、八、九，十!$B$B等等，我漏了一個...', `FemaleText_loc7`='¡Sé contar hasta "nuevediez"! ¡Escucha!$b$b<Milly cuenta con los dedos de las manos y los pies.>$b$bUno, dos, tres, cuatro, cinco, seis... Eh... siete, ocho, "nuevediez".$b$bEspera, me he saltado uno...' WHERE `ID`=72971;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코에 씨앗 넣지 마요. 아빠가 화내거든요!', `FemaleText_loc4`='别把种子塞进鼻子了。爸爸会很生气的！', `FemaleText_loc5`='不可以把種子塞進鼻子。爸爸會很生氣!', `FemaleText_loc7`='No te metas las semillas por la nariz. ¡Zarpapá se enfada muchísimo!' WHERE `ID`=72972;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 거북이가 좋아요.', `FemaleText_loc4`='我喜欢海龟。', `FemaleText_loc5`='我喜歡烏龜。', `FemaleText_loc7`='Me gustan las tortugas.' WHERE `ID`=72973;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='셈하는 건 재밌어요!', `FemaleText_loc4`='数数最好玩了！', `FemaleText_loc5`='數數真好玩!', `FemaleText_loc7`='¡Contar es divertido!' WHERE `ID`=72974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='밀리, 씨앗을 좀 담아 주겠니?', `MaleText_loc4`='米莉，请帮我包一些种子。', `MaleText_loc5`='米莉，我需要你幫我裝些種子。', `MaleText_loc7`='Milly, me gustaría que me envasaras algunas semillas.', `FemaleText_loc1`='밀리, 씨앗을 좀 담아 주겠니?', `FemaleText_loc4`='米莉，请帮我包一些种子。', `FemaleText_loc5`='米莉，我需要你幫我裝些種子。', `FemaleText_loc7`='Milly, me gustaría que me envasaras algunas semillas.' WHERE `ID`=72975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='열쇠만 있으면 곧 습격을 시작할 수 있을 것 같네요. 찾으셨나요?', `MaleText_loc4`='我们随时都能发动突击，只是需要一把钥匙。你找到钥匙了吗？', `MaleText_loc5`='我們隨時可以發動攻擊，現在缺的就只有鑰匙。你有找到鑰匙嗎?', `MaleText_loc7`='Estamos a punto de comenzar el asalto. Solo nos hace falta la llave. ¿La has encontrado?', `FemaleText_loc1`='열쇠만 있으면 곧 습격을 시작할 수 있을 것 같네요. 찾으셨나요?', `FemaleText_loc4`='我们随时都能发动突击，只是需要一把钥匙。你找到钥匙了吗？', `FemaleText_loc5`='我們隨時可以發動攻擊，現在缺的就只有鑰匙。你有找到鑰匙嗎?', `FemaleText_loc7`='Estamos a punto de comenzar el asalto. Solo nos hace falta la llave. ¿La has encontrado?' WHERE `ID`=72976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_nature_callstorm:20|t%s가 적을 |cFFFF0000|Hspell:138732|h[이온화]|h|r합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_nature_callstorm:20|t%s使用|cFFFF0000|Hspell:138732|h[电离反应]|h|r影响他的敌人！', `MaleText_loc5`='|TInterface\\Icons\\spell_nature_callstorm:20|t%s對他的敵人使出了|cFFFF0000|Hspell:138732|h[電離子化]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_nature_callstorm:20|t¡%s aplica |cFFFF0000|Hspell:138732|h[Ionización]|h|r a sus enemigos!' WHERE `ID`=72977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꾸준한 수련은 언제나 좋은 결과를 불러오죠.', `MaleText_loc4`='坚持训练，必有所获。', `MaleText_loc5`='持之以恒，必有收穫。', `MaleText_loc7`='El entrenamiento persistente siempre da resultado.' WHERE `ID`=72978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='떠날 준비가 됐습니다.', `MaleText_loc4`='我做好离开的准备了。', `MaleText_loc5`='我準備好離開了。', `MaleText_loc7`='Estoy listo para partir.', `FemaleText_loc1`='떠날 준비가 됐어요.', `FemaleText_loc4`='我做好离开的准备了。', `FemaleText_loc5`='我準備好離開了。', `FemaleText_loc7`='Estoy lista para partir.' WHERE `ID`=72979;
