UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예, 트릴리움을 충전합시다!', `MaleText_loc4`='是的，我们来给延极矿充能吧！', `MaleText_loc5`='好，我們開始精鍊這些延齡吧!', `MaleText_loc7`='¡Sí! ¡Vamos a cargar ese trillium!', `FemaleText_loc1`='네, 트릴리움을 충전하죠!', `FemaleText_loc4`='是的，我们来给延极矿充能吧！', `FemaleText_loc5`='好，我們開始精鍊這些延齡吧!', `FemaleText_loc7`='¡Sí! ¡Vamos a cargar ese trillium!' WHERE `ID`=72981;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시간에 맞춰 잘 빠져 나왔군요. 이 금고 중 하나에 맞을 열쇠도 구했습니다. 마음에 드시는 것을 고르세요. 당신 것이니까요.', `FemaleText_loc4`='干得好，时间刚刚好。我们发现了一把钥匙，应该能打开其中一个箱子。现在它归你了。', `FemaleText_loc5`='能及時離開真是太好了。我們拿到了一把鑰匙，應該可以用在其中一個珍寶。好，全部都是你的了。', `FemaleText_loc7`='Buen trabajo. Has conseguido salir a tiempo. Hemos recuperado una llave que debería abrir una de esas cámaras de tesoros.' WHERE `ID`=72982;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가까스로 구출해냈군요. 당신, 하마터면 죽을 뻔 했다고요.', `FemaleText_loc4`='我们差点就没法把你拉出来了。你真是走运，居然还活着。', `FemaleText_loc5`='差點就來不及救你出來了，你還活著真是幸運。', `FemaleText_loc7`='Te hemos sacado de ahí de milagro. Tienes suerte de seguir con vida.' WHERE `ID`=72983;
