UPDATE `locales_broadcast_text` SET `MaleText_loc1`='임무를 포기할 수는 없습니다! 가장 가까운 무덤으로 이동하기 전에 돌아가야 합니다!', `MaleText_loc4`='你即将放弃任务！在被传送到最近的墓地前，你必须返回原地。', `MaleText_loc5`='這麼做會放棄任務!你必須立刻返回，否則將被傳送至最近的墓地。', `MaleText_loc7`='¡Estás abandonando la misión! Debes volver antes de que se te teletransporte al cementerio más cercano.', `FemaleText_loc1`='임무를 포기할 수는 없습니다! 가장 가까운 무덤으로 이동하기 전에 돌아가야 합니다!', `FemaleText_loc4`='你即将放弃任务！在被传送到最近的墓地前，你必须返回原地。', `FemaleText_loc5`='這麼做會放棄任務!你必須立刻返回，否則將被傳送至最近的墓地。', `FemaleText_loc7`='¡Estás abandonando la misión! Debes volver antes de que se te teletransporte al cementerio más cercano.' WHERE `ID`=72990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s|1이;가; 어마어마한 |cFFFF0000|Hspell:138564|h[대격변]|h|r을 불러오기 시작합니다!', `MaleText_loc4`='|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s开始引导一个大型|cFFFF0000|Hspell:138564|h[灾变]|h|r法术！', `MaleText_loc5`='|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s開始引導強大的|cFFFF0000|Hspell:138564|h[毀天滅地]|h|r!', `MaleText_loc7`='|TInterfaceIconsachievement_zone_cataclysm.blp:20|t¡%s empieza a canalizar un inmenso |cFFFF0000|Hspell:138564|h[Cataclismo]|h|r!' WHERE `ID`=72991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s|1이;가; 거대한 |cFFFF0000|Hspell:138559|h[혼돈의 화살]|h|r을 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s开始施放一支大型|cFFFF0000|Hspell:138559|h[混乱之箭]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s開始引導一道強大的|cFFFF0000|Hspell:138559|h[混沌箭]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_warlock_chaosbolt.blp:20|t¡%s empieza a lanzar una inmensa |cFFFF0000|Hspell:138559|h[Descarga de Caos]|h|r!' WHERE `ID`=72992;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='천둥왕의 궁전이 바로 앞이에요. 요새를 공격하려면 우선 섬에 거점을 확보해야 해요.', `FemaleText_loc4`='雷电之王的宫殿就在前面。在发动进攻前，我们必须在岛上建立一个据点。', `FemaleText_loc5`='雷王的宮殿就在前面。我們必須先搶下一個立足點才能突擊他的堡壘。', `FemaleText_loc7`='El palacio del Rey del Trueno se encuentra ante nosotros. Debemos establecer una posición en la isla antes de asaltar la fortaleza.' WHERE `ID`=72993;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='으! 버텨요!', `FemaleText_loc4`='啊！坚持住！', `FemaleText_loc5`='呃!撐住!', `FemaleText_loc7`='¡Agh! ¡Espera!' WHERE `ID`=72994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인 불콘이 지팡이를 장비하더니 번개의 힘을 끌어모으기 시작합니다.', `MaleText_loc4`='掌炉者沃空装备上他的法杖并开始引导闪电之力！', `MaleText_loc5`='鍛造大師沃鋼裝備起他的法杖，開始引導閃電的力量!', `MaleText_loc7`='¡El maestro de forja Vul''kon equipa su bastón y empieza a canalizar el poder del relámpago!' WHERE `ID`=72995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제련장인 불콘이 망치를 장비하더니 엄청난 힘으로 휘두르기 시작합니다.', `MaleText_loc4`='掌炉者沃空装备上他的战锤并开始用力挥舞！', `MaleText_loc5`='鍛造大師沃鋼裝備起他的戰錘，開始揮擊猛攻!', `MaleText_loc7`='¡El maestro de forja Vul''kon equipa su martillo y empieza a golpear con gran fuerza!' WHERE `ID`=72996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 융합체가 |cFFFF2222|Hspell:139375|h[어둠의 파열]|h|r을 시전하고 있습니다! 도망치십시오!', `MaleText_loc4`='融合之煞开始施放 |cFFFF2222|Hspell:139375|h[暗影爆裂]|h|r！快跑！', `MaleText_loc5`='煞的融合體正在施展|cFFFF2222|Hspell:139375|h[暗影衝擊]|h|r!快點跑開!', `MaleText_loc7`='¡La amalgama de sha empieza a lanzar |cFFFF2222|Hspell:139375|h[Ráfaga de las Sombras]|h|r! ¡Corre!' WHERE `ID`=72997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 융합체가 악해졌습니다! |cFFFF2222[번개 창]|r을 던지십시오!', `MaleText_loc4`='融合之煞被削弱了！快用|cFFFF2222[闪电长枪]|r丢它！', `MaleText_loc5`='煞的融合體現出了弱點!用|cFFFF2222[閃電長槍]|r擲向它!', `MaleText_loc7`='¡La amalgama de sha es vulnerable! ¡Arrójale la |cFFFF2222[Lanza del relámpago]|r!' WHERE `ID`=72998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 융합체가 |cFFFF2222|Hspell:139443|h[유성 폭풍]|h|r을 시전합니다!', `MaleText_loc4`='融合之煞开始施放|cFFFF2222|Hspell:139443|h[流星风暴]|h|r！', `MaleText_loc5`='煞的融合體施展了|cFFFF2222|Hspell:139443|h[隕石雨]|h|r!', `MaleText_loc7`='¡La amalgama de sha lanza |cFFFF2222|Hspell:139443|h[Tormenta de meteoritos]|h|r!' WHERE `ID`=72999;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='샤 융합체가 천공의 수호병을 추방합니다. 조심하십시오!', `MaleText_loc4`='融合之煞放逐了天界防御者！快保护你自己！', `MaleText_loc5`='煞的融合體放逐了星穹防禦者。保護好你自己!', `MaleText_loc7`='La amalgama de sha destierra al defensor celestial. ¡Defiéndete!' WHERE `ID`=73000;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천공의 수호병이 심한 부상을 입어 싸우지 못하게 되었습니다!', `MaleText_loc4`='天界防御者遭到重创，无法继续战斗了！', `MaleText_loc5`='星穹防禦者受到了致命重傷，無法再進行戰鬥了!', `MaleText_loc7`='¡El defensor celestial está gravemente herido y ya no puede luchar!' WHERE `ID`=73001;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제한 시간을 초과했습니다.', `MaleText_loc4`='你没时间了。', `MaleText_loc5`='你沒有時間了。', `MaleText_loc7`='Se te ha acabado el tiempo.', `FemaleText_loc1`='제한 시간을 초과했습니다.', `FemaleText_loc4`='你没时间了。', `FemaleText_loc5`='你沒有時間了。', `FemaleText_loc7`='Se te ha acabado el tiempo.' WHERE `ID`=73002;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222[요동치는 모루]|r가 과충전되었습니다! 모루를 클릭해 |cFFFF2222|Hspell:138834|h[천둥 쇄도]|h|r를 일으키십시오!', `MaleText_loc4`='一座|cFFFF2222[雷霆铁砧]|r过载了！快点击它以施放|cFFFF2222|Hspell:138834|h[雷霆涌动]|h|r！', `MaleText_loc5`='有一座|cFFFF2222[雷霆鐵砧]|r超載了!快使用那座鐵砧，釋放|cFFFF2222|Hspell:138834|h[雷霆奔流]|h|r!', `MaleText_loc7`='¡Un |cFFFF2222[yunque atronador]|r se ha sobrecargado! Haz clic en él para provocar una |cFFFF2222|Hspell:138834|h[Oleada de trueno]|h|r!' WHERE `ID`=73003;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 배는 새로운 선장이 다스린다! 제대로 일을 하지 않는 놈은 영혼을 끄집어내어 골렘에게 먹이로 주겠다.', `MaleText_loc4`='这艘船得有个新规矩了！所有不卖力干活儿的人，他们的灵魂将被注入魔像。', `MaleText_loc5`='這艘船的老闆換人了!沒有好好幹活的，靈魂就準備弄給魔像吧。', `MaleText_loc7`='¡Eh''te barco tiene nueva adminih''tración! A todo aquel que no haga su trabajo se le transferirá el eh''píritu a un gólem.' WHERE `ID`=73004;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 명령을 따르는 이 함선을 모두가 두려워할 것이다! 맞지, 리피?', `MaleText_loc4`='在我的指挥下，这艘船将成为所有人的噩梦！对不对啊，利皮？', `MaleText_loc5`='在我的指揮之下，這艘船一定會惡名昭彰!你說對不對，銳匕?', `MaleText_loc7`='Bajo mi mando, ¡todo el mundo temerá eh''te barco! ¿A que sí, Ripi?' WHERE `ID`=73005;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 잔달라 부족을 과소평가하지 마십시오. 놈들은 제가 여태껏 만난 트롤들과는 사뭇 다른 존재들입니다.', `MaleText_loc4`='这些赞达拉巨魔不可小觑。他们和我见过的任何巨魔都不一样。', `MaleText_loc5`='不能低估這些贊達拉，他們跟以前我碰過的食人妖都不一樣。', `MaleText_loc7`='No debemos subestimar a los Zandalari. No se parecen a ningún otro trol que haya conocido.' WHERE `ID`=73006;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 순찰대가 자투알로부터 신경 쓰이는 보고서를 보내왔소. 어쩌면 놈들의 코 앞에서 싸움을 벌여야 할 수도 있겠군.', `MaleText_loc4`='我的游侠从赞图尔发回的报告相当令人不安。我想，该是我们打上门去的时候了。', `MaleText_loc5`='我的遊俠從札突爾送回了令人不安的報告，我相信，該是直搗黃龍的時候了。', `MaleText_loc7`='Mis forestales me envían informes inquietantes de Za''Tual. Creo que ha llegado el momento de llevar la lucha allí.' WHERE `ID`=73007;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈는 영혼의 편이다!', `MaleText_loc4`='枯骨与万灵同在！', `MaleText_loc5`='擲出來的結果是靈魂!', `MaleText_loc7`='¡Los huesos amparan a los eh''píritus!' WHERE `ID`=73008;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈는 죽음의 편이야!', `MaleText_loc4`='枯骨与死神同在！', `MaleText_loc5`='擲出來的結果是死亡!', `MaleText_loc7`='¡Los huesos amparan a la mueh''te!' WHERE `ID`=73009;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈는 내 편이다!', `MaleText_loc4`='枯骨与我同在！', `MaleText_loc5`='擲出來的結果對我有利!', `MaleText_loc7`='¡Los huesos eh''tán de mi pah''te!' WHERE `ID`=73010;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈는 네 편이구나!', `MaleText_loc4`='枯骨与你同在，伙计！', `MaleText_loc5`='擲出來的結果對你有利，老兄!', `MaleText_loc7`='¡Los huesos eh''tán de tu pah''te, colega!' WHERE `ID`=73011;
