UPDATE `locales_broadcast_text` SET `MaleText_loc1`='베리사, 폭탄을 드립니다.', `MaleText_loc4`='炸药来了，温蕾萨。', `MaleText_loc5`='炸藥拿來了，凡蕾莎。', `MaleText_loc7`='Aquí están los explosivos, Vereesa.', `FemaleText_loc1`='베리사, 폭탄을 드릴게요.', `FemaleText_loc4`='炸药来了，温蕾萨。', `FemaleText_loc5`='炸藥拿來了，凡蕾莎。', `FemaleText_loc7`='Aquí están los explosivos, Vereesa.' WHERE `ID`=73014;
