UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥 제련소를 작동시켜도 되겠느냐? 아슬아슬한 상황이 될지도 모른다.', `MaleText_loc4`='你做好帮我开启雷霆熔炉的准备了吗？这可能有点危险。', `MaleText_loc5`='準備好要我啟動雷霆熔爐了嗎?待會兒可能會很危險。', `MaleText_loc7`='¿Seguro que quieres que inicie la Forja del Trueno? La cosa podría ponerse fea.' WHERE `ID`=73016;
