UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222[요동치는 모루]|r가 과충전되었습니다. 모루를 활성화해 에너지를 |cFFFF2222|Hspell:138834|h[방출]|h|r하십시오.', `MaleText_loc4`='一座|cFFFF2222[雷霆铁砧]|r过载了！快激活它以进行|cFFFF2222|Hspell:138834|h[释能]|h|r。', `MaleText_loc5`='有一座|cFFFF2222[雷霆鐵砧]|r超載了!啟動它來為能量|cFFFF2222|Hspell:138834|h[放電]|h|r。', `MaleText_loc7`='¡Un |cFFFF2222[yunque atronador]|r se ha sobrecargado! Actívalo para |cFFFF2222|Hspell:138834|h[Descargar]|h|r su energía.' WHERE `ID`=73026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF2222[번개 창]|r이 충전되었습니다. 창으로 샤 융합체를 처치하십시오!', `MaleText_loc4`='|cFFFF2222[闪电长枪]|r充能完毕。快用它消灭融合之煞！', `MaleText_loc5`='|cFFFF2222[閃電長槍]|r充能完成，用它解決掉煞的融合體!', `MaleText_loc7`='La |cFFFF2222[Lanza del relámpago]|r se ha cargado. ¡Utilízala para acabar con la amalgama de sha!' WHERE `ID`=73027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t %s|1이;가; 끔찍한 |cFFFF0000|Hspell:140432|h[숙취]|h|r에서 깨어납니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t %s醒了过来，但依然遭受着可怕的|cFFFF0000|Hspell:140432|h[宿醉]|h|r折磨！', `MaleText_loc5`='|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|t %s嚴重|cFFFF0000|Hspell:140432|h[宿醉]|h|r地醒來了!', `MaleText_loc7`='|TInterfaceIconsspell_arcane_mindmastery.blp:20|t ¡%s se despierta con una |cFFFF0000|Hspell:140432|h[resaca]|h|r terrible!' WHERE `ID`=73028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='배에서 난 소리야! 빨리 가보자!', `MaleText_loc4`='它从船上过来了！我们走！', `MaleText_loc5`='從船那邊來的!我們走!', `MaleText_loc7`='¡Eso ha venido del barco! ¡Vamos!' WHERE `ID`=73029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='번개 기둥 근처에서 폭풍이 일고 있습니다. 조심하십시오!', `MaleText_loc4`='闪电之柱附近正在酝酿一场风暴。小心！', `MaleText_loc5`='風暴在閃電之柱旁邊開始醞釀。當心!', `MaleText_loc7`='Se está cargando un relámpago cerca del pilar de relámpagos. ¡Cuidado!' WHERE `ID`=73032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='족쇄로부터 거리를 벌려 사슬을 끊으십시오!', `MaleText_loc4`='快远离镣铐以打破链接！', `MaleText_loc5`='遠離鐐銬，打斷鎖鍊!', `MaleText_loc7`='¡Aléjate de los grilletes para romper las cadenas!', `FemaleText_loc1`='족쇄로부터 거리를 벌려 사슬을 끊으십시오!', `FemaleText_loc4`='快远离镣铐以打破链接！', `FemaleText_loc5`='遠離鐐銬，打斷鎖鍊!', `FemaleText_loc7`='¡Aléjate de los grilletes para romper las cadenas!' WHERE `ID`=73033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t레이 션이 격노해 |cFFFF0000|Hspell:140549|h[번개 폭풍]|h|r을 불러냅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t雷神被激怒了，开始召唤|cFFFF0000|Hspell:140549|h[闪电风暴]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t雷神被激怒了!他開始呼喚|cFFFF0000|Hspell:140549|h[閃電風暴]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_thunderking_thunderstruck.blp:20|t¡Lei Shen se enfada e invoca una |cFFFF0000|Hspell:140549|h[Tormenta de relámpagos]|h|r!' WHERE `ID`=73034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s|1이;가; |cFFFF0000|Hspell:140543|h[강화된 도끼]|h|r를 시전합니다! 도망치십시오!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s施放了|cFFFF0000|Hspell:140543|h[灌能之斧]|h|r！快跑开！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_destructivesoul.blp:20|t%s施放了 |cFFFF0000|Hspell:140543|h[強化之斧]|h|r!快跑開!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_destructivesoul.blp:20|t¡%s lanza |cFFFF0000|Hspell:140543|h[Potenciar hacha]|h|r! ¡Corre!' WHERE `ID`=73035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s|1이;가; |cFFFF0000|Hspell:140531|h[멈추기]|h|r를 시전하기 시작합니다! 풀려나려면 |cFFFF0000족쇄|r를 파괴하십시오!', `MaleText_loc4`='|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s开始施放|cFFFF0000|Hspell:140531|h[绝杀]|h|r！快打破|cFFFF0000锁链|r以获取自由！', `MaleText_loc5`='|TInterface\\Icons\\warrior_talent_icon_bloodandthunder.blp:20|t%s開始施展|cFFFF0000|Hspell:140531|h[迫止]|h|r!摧毀|cFFFF0000鎖鍊|r來逃走!', `MaleText_loc7`='|TInterfaceIconswarrior_talent_icon_bloodandthunder.blp:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:140531|h[Desistir]|h|r! ¡Destruye las |cFFFF0000Cadenas|r para liberarte!' WHERE `ID`=73036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설정 완료', `MaleText_loc4`='设置', `MaleText_loc5`='設定', `MaleText_loc7`='Establecer', `FemaleText_loc1`='설정 완료', `FemaleText_loc4`='设置', `FemaleText_loc5`='設定', `FemaleText_loc7`='Establecer' WHERE `ID`=73037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양노래 농장을 귀환 장소로 사용합니다.', `MaleText_loc4`='将日歌农场设置为你的家。', `MaleText_loc5`='將日歌農莊設為你的家。', `MaleText_loc7`='Fija tu hogar en el Rancho Cantosol.', `FemaleText_loc1`='태양노래 농장을 귀환 장소로 사용합니다.', `FemaleText_loc4`='将日歌农场设置为你的家。', `FemaleText_loc5`='將日歌農莊設為你的家。', `FemaleText_loc7`='Fija tu hogar en el Rancho Cantosol.' WHERE `ID`=73038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<표지가 너덜너덜하고 책을 묶은 끈에는 흙이 끼어 있는 무거운 책입니다. 윤이 전통을 따라 일지에 태양노래 농장의 역사를 기록해 두었던 듯합니다. 책은 윤의 마지막 글이 보이도록 펼쳐져 있습니다. 다름 아닌 당신에게 쓴 편지로군요!>$B$B"우리 가문의 땅에 예전의 영광을 되찾아 주셔서 감사합니다. 저는 더 큰 일을 해야 합니다. 이제 이 책장을 채우는 것은 당신 몫입니다."', `MaleText_loc4`='<一本厚重的书籍，封面非常陈旧，夹缝中还有灰尘。看来老愚延续了传统，一直在这本日志上记录日歌农场的历史。日志翻到他的最后一条记录上：这是一条写给你的信息！>$B$B“感谢你让我祖传的土地恢复了昔日的荣光。我又更重要的事情要做了；现在轮到你来书写这些书页了。”', `MaleText_loc5`='<一本厚厚的書，封面十分陳舊，上面布滿了灰塵。看來尹遵循了傳統並在這本書上面記錄了日歌農莊的歷史。它最後一頁的記載是寫給你的!>$B$B「感謝你幫我家族的土地恢復到以往的繁榮。我要去做更偉大的事情，現在輪到你來記錄這本書了。」', `MaleText_loc7`='<Un pesado libro con una portada gastada por el uso y rastros de tierra en la encuadernación. Parece que Yoon ha seguido con la tradición de registrar la historia del Rancho Cantosol en este diario. Está abierto por la última entrada: ¡una nota dirigida a ti!>$b$b"Gracias por devolver la tierra de mi familia a su antigua gloria. Ahora que ha recaído sobre mí una responsabilidad mayor, te toca a ti llenar estas páginas".' WHERE `ID`=73039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴 땅무지가 근처의 추적자 혈암거미들을 불러 자기를 돕게 합니다.', `MaleText_loc4`='洞穴钻地者开始召唤附近的页岩追猎者来协助作战。', `MaleText_loc5`='洞窟鑽地怪開始呼喚附近的頁岩潛行者來協助牠。', `MaleText_loc7`='El perforador de cavernas empieza a llamar a acechadores de esquisto para que le ayuden.' WHERE `ID`=73040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동굴 땅무지가 |cFFF00000|Hspell:140600|h[음파 경보]|h|r로 근처의 추적자 혈암거미들에게 당신의 존재를 알립니다!', `MaleText_loc4`='洞穴钻地者用|cFFF00000|Hspell:140600|h[声波警告]|h|r向附近的页岩追猎者警告了你的到来！', `MaleText_loc5`='洞窟鑽地怪以|cFFF00000|Hspell:140600|h[音波叫喚]|h|r警告附近的頁岩潛行者!', `MaleText_loc7`='¡El perforador de cavernas ha alertado a los acechadores de esquisto cercanos con |cFFF00000|Hspell:140600|h[Llamada sónica]|h|r!' WHERE `ID`=73041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 침묵의 찬가를 시전하기 시작합니다! 방벽 안으로 들어가십시오!', `MaleText_loc4`='%s开始施放沉默赞歌！快躲到屏障里去！', `MaleText_loc5`='%s開始施放寂靜禮頌!躲進屏障中!', `MaleText_loc7`='¡La %s empieza a lanzar Himno de silencio! ¡Escóndete tras una barrera! ', `FemaleText_loc1`='%s|1이;가; 침묵의 찬가를 시전하기 시작합니다! 방벽 안으로 들어가십시오!', `FemaleText_loc4`='%s开始施放沉默赞歌！快躲到屏障里去！', `FemaleText_loc5`='%s開始施放寂靜禮頌!躲進屏障中!', `FemaleText_loc7`='¡La %s empieza a lanzar Himno de silencio! ¡Escóndete tras una barrera! ' WHERE `ID`=73044;
