UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에게 북풍의 차디찬 원한을 허락하마!', `MaleText_loc4`='我赐予你北风的冷酷复仇之力！', `MaleText_loc5`='我將北風冰冷的復仇借給你!', `MaleText_loc7`='¡Te ofrezco la fría venganza de los vientos del norte!' WHERE `ID`=73071;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='공정하고, 정의롭고, 또 여러분과는 별로 상관 없는 여러 미덕을 상징하는... 드레나이 성기사, 아후루입니다!', `FemaleText_loc4`='他代表着一切正直、正义以及其他的无聊品质。他就是德莱尼圣骑士，阿霍鲁！', `FemaleText_loc5`='他是正義與公正的代表、集天地正氣於一身的使者，讓我們歡迎德萊尼聖騎士，阿胡魯!', `FemaleText_loc7`='Representa todo lo justo y recto y muchas más tonterías aburridas. ¡Es el paladín draenei, Ahoo''ru!' WHERE `ID`=73075;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='삽을 드세요, 여러분! 밍구스 디그스가 고고학이 뭔지 가르쳐 준답니다!', `FemaleText_loc4`='各位，快拿出你们的铲子吧！明格斯·迪格斯将给我们上一堂考古课！', `FemaleText_loc5`='快拿出你們的鏟子來!明格斯·迪格司的考古挖掘課即將開始!', `FemaleText_loc7`='¡Que todo el mundo coja su pala! Mingus Cavaré está a punto de darnos una lección de arqueología.' WHERE `ID`=73076;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 이런... 누가 뒤뚱거리며 등장했는지 보십시오. 바로 멍든 부리가 눈에 띄는 통통 튀는 새, 디피입니다! 게다가 이번엔 혼자가 아니네요!', `FemaleText_loc4`='喔哟哟……看看是谁大摇大摆地回来了。它就是肿着嘴的大鸟，帝皮！这次，它不是一只鸟在战斗！', `FemaleText_loc5`='大家快看...是誰再度搖搖晃晃地走進了競技場。現在上場的是嘴角瘀青、活蹦亂跳的呆呆!但這一次，他可不是孤軍奮戰!', `FemaleText_loc7`='Vaya, vaya... mira quién ha vuelto. Es el pájaro con el pico amoratado, ¡Chapuzón! ¡Y esta vez no está solo!' WHERE `ID`=73077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공정하고, 정의롭고, 또 여러분과는 별로 상관 없는 여러 미덕을 상징하는... 드레나이 성기사, 아후루입니다!', `MaleText_loc4`='他代表了一切正直、正义与其他为大多数人所不屑的美德。他就是德莱尼圣骑士，阿霍鲁！', `MaleText_loc5`='他是正義與公正的代表，他的善良美德多到讓人聽不下去，讓我們歡迎德萊尼聖騎士，阿胡魯!', `MaleText_loc7`='Es la representación viva de todo lo justo y lo honesto, además de otras muchas virtudes que a la mayoría de ustedes no les interesa. ¡Es el paladín draenei, Ahoo''ru!' WHERE `ID`=73078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='삽을 드세요, 여러분! 밍구스 디그스가 고고학이 뭔지 가르쳐 준답니다!', `MaleText_loc4`='各位，快拿出你们的铲子吧！明格斯·迪格斯将给我们上一堂考古课！', `MaleText_loc5`='快拿出你們的鏟子來!明格斯·迪格司的考古挖掘課即將開始!', `MaleText_loc7`='¡Que todo el mundo coja su pala! Mingus Cavaré está a punto de darnos una lección de arqueología.' WHERE `ID`=73079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옛 도전자가 다시 돌아왔습니다! 싸움굴에 돌아온 걸 환영해요, 디피!', `MaleText_loc4`='这位挑战者可是我们的老朋友了！欢迎回到竞技场，帝皮！', `MaleText_loc5`='看來有個挑戰者再度回到場上啦!讓我們歡迎，呆呆!', `MaleText_loc7`='Parece que tenemos un contendiente que repite. ¡Bienvenido de nuevo a la arena, Chapuzón!' WHERE `ID`=73080;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뉴트, 저 문을 열어.', `MaleText_loc4`='蝾螈，去打开那道门。', `MaleText_loc5`='紐特，打開那道門。', `MaleText_loc7`='Salamandra, abre esa puerta.' WHERE `ID`=73081;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 신병 $p! 넌 날 따라와.', `MaleText_loc4`='新兵$p，你跟我走。', `MaleText_loc5`='新來的$p，你跟緊我。', `MaleText_loc7`='Recluta $p, estás conmigo.' WHERE `ID`=73082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 듀로타에서 최근 발생한 납치 사건의 단서를 쫓다가, 여기 성난불길의 구석진 곳까지 오게 된 거라고.', `MaleText_loc4`='我们追查着最近发生在杜隆塔尔的失踪事件，最终来到了怒焰裂谷中的这片废弃地带。', `MaleText_loc5`='根據我們追蹤的結果指出，最近在杜洛塔失蹤的人都跟怒焰裂谷的這個廢棄區域有關。', `MaleText_loc7`='Hemos seguido el rastro de las recientes desapariciones en Durotar hasta esta zona abandonada de Sima Ígnea.' WHERE `ID`=73083;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='알겠어요!', `FemaleText_loc4`='遵命，长官！', `FemaleText_loc5`='遵命!', `FemaleText_loc7`='¡Enseguida!' WHERE `ID`=73084;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하십니까!', `MaleText_loc4`='日安，长官！', `MaleText_loc5`='你好，長官!', `MaleText_loc7`='¡Buenos días!' WHERE `ID`=73085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사건의 배후가 누군지 알아내서 막는 게 우리 임무야.', `MaleText_loc4`='我们的任务就是挖出这一系列绑架事件的幕后黑手并加以阻止。', `MaleText_loc5`='我們的職責就是找出這些綁架事件幕後的主使者，並且阻止他們。', `MaleText_loc7`='Es nuestro deber averiguar quién está detrás de estas desapariciones y ponerles fin.' WHERE `ID`=73086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그릿, 티커, 볼트. 너희 셋은 뉴트를 지원해줘.', `MaleText_loc4`='沙砾、钟摆和伏特，你们三个去支援她。', `MaleText_loc5`='葛利特、提克爾還有伏特，你們三個負責支援她。', `MaleText_loc7`='Agallas, Tictac y Volt,ustedes tres, cúbranle las espaldas.' WHERE `ID`=73087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 붙어 있으라고.', `MaleText_loc4`='跟紧我。', `MaleText_loc5`='跟緊點。', `MaleText_loc7`='Manténganse cerca.' WHERE `ID`=73088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뉴트, 지금 당장 이 문을 열어야 해!', `MaleText_loc4`='蝾螈，我们得立刻打开这道门。', `MaleText_loc5`='紐特，我們現在就得打開那道門。', `MaleText_loc7`='Salamandra, necesitamos esa puerta abierta ya.' WHERE `ID`=73089;
