UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='폭탄이 모두 설치됐어요. 준비가 끝나는 대로 기폭장치를 작동하세요!', `FemaleText_loc4`='炸药装填完毕，你们准备好之后，就赶紧按下引爆装置吧！', `FemaleText_loc5`='炸藥都裝好了，一準備好就快點按下引爆器!', `FemaleText_loc7`='Las cargas están listas; ¡activa el detonador en cuanto estés $glisto:lista;!' WHERE `ID`=73091;
