UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 얼라이언스 금광 수레를 놓쳤습니다!', `MaleText_loc4`='部落丢弃了联盟运金车！', `MaleText_loc5`='部落棄置聯盟的黃金礦車了!', `MaleText_loc7`='¡La Horda ha volcado el carro de oro de la Alianza!' WHERE `ID`=73094;
