UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원뿔형 색깔 광선을 이용해, 숨어 있는 진홍빛 안개도깨비를 찾아서 처치하십시오!', `MaleText_loc4`='利用锥形光束发现并击败隐藏的猩红雾行兽！', `MaleText_loc5`='使用射線找出並消滅隱藏的緋紅霧獸!', `MaleText_loc7`='¡Usa los conos de luz para encontrar y derrotar a las nieblas carmesíes!' WHERE `ID`=73101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원뿔형 색깔 광선을 이용해, 숨어 있는 안개도깨비를 색깔별로 한 마리씩 찾아서 처치하십시오!', `MaleText_loc4`='利用锥形光束发现并击败每种颜色的雾行兽各一只！', `MaleText_loc5`='使用射線找出並消滅所有顏色對應的霧獸!', `MaleText_loc7`='¡Usa los conos de luz para encontrar y derrotar a una bestia de niebla de cada color!' WHERE `ID`=73102;
