UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 적외선의 대상이 되었습니다! 동료들과 함께 단상을 돌아다니며 진홍빛 안개도깨비를 찾아서 처치하십시오.', `MaleText_loc4`='你成为了红光的目标！快绕着战场移动，让你的队友找出并击败猩红雾行兽。', `MaleText_loc5`='你是紅光射線的照射目標!與隊友在照射範圍內四處移動，找出並消滅緋紅霧獸。', `MaleText_loc7`='¡Eres el objetivo de la Luz infrarroja! Muévete por la arena con tus compañeros de equipo para encontrar y derrotar a una niebla carmesí.', `FemaleText_loc1`='당신은 적외선의 대상이 되었습니다! 동료들과 함께 단상을 돌아다니며 진홍빛 안개도깨비를 찾아서 처치하십시오.', `FemaleText_loc4`='你成为了红光的目标！快绕着战场移动，让你的队友找出并击败猩红雾行兽。', `FemaleText_loc5`='你是紅光射線的照射目標!與隊友在照射範圍內四處移動，找出並消滅緋紅霧獸。', `FemaleText_loc7`='¡Eres el objetivo de la Luz infrarroja! Muévete por la arena con tus compañeros de equipo para encontrar y derrotar a una niebla carmesí.' WHERE `ID`=73105;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 청색 광선의 대상이 되었습니다! 동료들과 함께 단상을 돌아다니며 하늘빛 안개도깨비를 찾아서 처치하십시오.', `MaleText_loc4`='你成为了蓝光的目标！快绕着战场移动，让你的队友找出并击败碧蓝雾行兽。', `MaleText_loc5`='你是藍光射線的照射目標!與隊友在照射範圍內四處移動，找出並消滅蔚藍霧獸。', `MaleText_loc7`='¡Eres el objetivo de los Rayos azules! Muévete por la arena con tus compañeros de equipo para encontrar y derrotar a una niebla azur.', `FemaleText_loc1`='당신은 청색 광선의 대상이 되었습니다! 동료들과 함께 단상을 돌아다니며 하늘빛 안개도깨비를 찾아서 처치하십시오.', `FemaleText_loc4`='你成为了蓝光的目标！快绕着战场移动，让你的队友找出并击败碧蓝雾行兽。', `FemaleText_loc5`='你是藍光射線的照射目標!與隊友在照射範圍內四處移動，找出並消滅蔚藍霧獸。', `FemaleText_loc7`='¡Eres el objetivo de los Rayos azules! Muévete por la arena con tus compañeros de equipo para encontrar y derrotar a una niebla azur.' WHERE `ID`=73106;
