UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복덩이 플루트!', `MaleText_loc4`='幸运之笛！', `MaleText_loc5`='看我的幸運笛!', `MaleText_loc7`='¡Flauta grisgrís!' WHERE `ID`=73110;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='상대는... 다이너마이트를 투척하는 원숭이 수도사이자. 적에게 관대하기로 유명한 사부 뻥 뻥입니다!', `FemaleText_loc4`='同时进场的还有：豪爽的布姆布姆大师！就是那位扔炸药的猢狲武僧！', `FemaleText_loc5`='從另一邊入場的是:品行高尚的砰砰大師，這個猴人武僧丟炸彈的功力無人能及!', `FemaleText_loc7`='También está entrando en la arena el magnánimo Maestro Bum Bum: ¡el mono monje lanzador de dinamita!' WHERE `ID`=73111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 투기장에 들어서는 건, 폭탄 상자를 든 호젠입니다! 다이너마이트를 투척하는 원숭이 수도사, 사부 뻥 뻥을 소개합니다!', `MaleText_loc4`='同时进场的还有：带着大箱炸弹的猢狲！他就是扔炸药的猢狲武僧，布姆布姆大师！', `MaleText_loc5`='另一邊踏入競技場的是:帶著一箱炸彈的猴人!讓我們歡迎丟炸彈功力無人能及的位猴人武僧，砰砰大師!', `MaleText_loc7`='¡También está entrando en la arena el hozen con la caja de explosivos! Es el maestro Bum Bum, ¡el monje mono lanzador de dinamita!' WHERE `ID`=73112;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신에게 불운이 왕창 닥치길 빌어요!', `MaleText_loc4`='祝你倒大霉！', `MaleText_loc5`='你要倒大楣啦!', `MaleText_loc7`='¡Te deseo lo peor!' WHERE `ID`=73113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신... 복덩이가 강력한 모양이네요.', `MaleText_loc4`='你肯定带了强力幸运符。', `MaleText_loc5`='你一定擁有好幸運星。', `MaleText_loc7`='Debes de tener un buen grisgrís.' WHERE `ID`=73114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청한 그루멀짐 같으니!', `MaleText_loc4`='笨蛋土地精包裹！', `MaleText_loc5`='笨咕嚕摩包!', `MaleText_loc7`='¡Estúpido paquete grúmel!' WHERE `ID`=73115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 뭔가 찾아냈어. 아주 커다란 거야. 그런데 갑자기 바위가 우릴 공격하고, 다들 정신이 나가버렸어. 손해가 엄청나!', `MaleText_loc4`='我们在下面有了重大发现！可后来，岩石突然就开始反击，所有人都疯了。真是亏本的买卖！', `MaleText_loc5`='我們在下面找到超大的東西，忽然岩石開始起身反擊，讓大家都抓狂了。真是虧本。', `MaleText_loc7`='Encontramos algo allí abajo, algo enorme, y de pronto las rocas comenzaron a dar pelea y todo se convirtió en una locura. ¡Mal negocio!' WHERE `ID`=73118;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발, 어떻게 좀 해 줘!', `MaleText_loc4`='拜托了，快阻止这一切吧！', `MaleText_loc5`='拜託，阻止這一切!', `MaleText_loc7`='¡Por favor, haz que pare!' WHERE `ID`=73119;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭘 쳐다보고만 있는 거야? 해야 할 일이 있다고!', `FemaleText_loc4`='你在看什么呢，小鬼？该干活儿了！', `FemaleText_loc5`='有什麼好看的，小鬼?還有工作要做呢!', `FemaleText_loc7`='¿Qué estás mirando? Hay trabajo que hacer.' WHERE `ID`=73120;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적대적 대상 확인.', `MaleText_loc4`='需要敌对目标！', `MaleText_loc5`='鎖定敵對目標。', `MaleText_loc7`='Objetivo hostil fijado.' WHERE `ID`=73121;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수직 안정기 작동 중단. 전원 종료.', `MaleText_loc4`='垂直尾翼离线。动力下降。', `MaleText_loc5`='直立式安定裝置連線中斷，系統關閉中。', `MaleText_loc7`='Estabilizadores verticales desactivados. Apagando motores.' WHERE `ID`=73122;
