UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 잡아 드시겠다? 귀 커다란 눈귀신 놈들!', `FemaleText_loc4`='休想煮了我，你这愚蠢的巨魔！', `FemaleText_loc5`='你別想把我煮來吃，長耳朵的雪怪!', `FemaleText_loc7`='¡No me cocinarán a MÍ, orejudos chupanieve!' WHERE `ID`=73124;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하하! 이거나 먹어라, 얼굴 퍼런 할망구야!', `FemaleText_loc4`='尝尝这个，你这蓝皮巫婆！', `FemaleText_loc5`='嘗嘗這招，藍皮的妖孽!', `FemaleText_loc7`='¡Toma ESTO, bruja azulada!' WHERE `ID`=73125;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 구워 먹겠다고? 뻐드렁니 식인종 주제에! 이거나 먹어라!', `FemaleText_loc4`='想烤了我吗，你这暴牙狗？！我会好好教训你的！', `FemaleText_loc5`='你這個暴牙鬼想把我烤來吃?給我看好了!', `FemaleText_loc7`='¿Intentas asarme a MÍ, mascahuesos de dientes chuecos? ¡Te daré una lección!' WHERE `ID`=73126;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='달걀 센서 비활성화. 작동 종료.', `MaleText_loc4`='鸡蛋感应器离线。正在关闭。', `MaleText_loc5`='雞蛋感應器連線中斷，系統關閉中。', `MaleText_loc7`='Sensor ovoide desactivado. Desconectando.' WHERE `ID`=73127;
