UPDATE `locales_broadcast_text` SET `MaleText_loc1`='부리 장치 과부화. 유닛 가동 중지.', `MaleText_loc4`='喙部设备过载。正在关闭装置。', `MaleText_loc5`='喙嘴裝置超載，組件停止運作中。', `MaleText_loc7`='Sobrecarga en el dispositivo de pico. Desactivando unidad.' WHERE `ID`=73129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 무엇을 도와드릴까요? 아니, 귀찮으니 그만두지요.', `MaleText_loc4`='你引起了我的注意。呃，没事了。', `MaleText_loc5`='你引起我的注意了，好吧，現在又沒有了。', `MaleText_loc7`='Tienes toda mi atención. Vale, ya la has perdido.' WHERE `ID`=73130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남의 얼굴을 제대로 때릴 줄 알면, 이런 양복을 살 수 있습니다.', `MaleText_loc4`='我这身行头全是靠揍人换回来的。', `MaleText_loc5`='我這套西裝可是靠揍人賺來的。', `MaleText_loc7`='Me compré este traje gracias a aporrear caras.' WHERE `ID`=73131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래요. 제가 싸움을 하던 시기는 지났습니다. 요즘은 그냥 멋진 술, 그리고 별로 멋지지 않은 아가씨들과 함께할 뿐이지요.', `MaleText_loc4`='没错，我打拳的日子已经过去了。现在，我全靠美酒和三流美女打发日子了。', `MaleText_loc5`='沒錯，我的鬥陣日子已經結束了。如今我的時間都花在高級美酒和沒那麼高級的美女上。', `MaleText_loc7`='Sí, mis días de refriegas terminaron. Ahora ocupo mi tiempo con cervezas elegantes y chicas no tan elegantes.' WHERE `ID`=73132;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 위에서 보는 광경이 훨씬 멋져요. 물론, 피가 덜 튀는 건 말할 필요도 없고요.', `FemaleText_loc4`='这上面的视线确实更好，而且还不会被血溅到。', `FemaleText_loc5`='上頭的視野確實棒多了，而且更棒的是，血根本不會噴到這裡來。', `FemaleText_loc7`='La vista desde aquí es mucho mejor. Y eso sin mencionar la ausencia de manchas de sangre.' WHERE `ID`=73133;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전 항상 로봇을 응원한답니다.', `FemaleText_loc4`='我总会为机器人们欢呼。', `FemaleText_loc5`='我一向都幫機器人加油。', `FemaleText_loc7`='Yo siempre apoyo a los robots.' WHERE `ID`=73134;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뭐라고 하셨나요? 죄송해요. 전 뭔가 죽어가는 즐거운 장면이 펼쳐질 땐, 남의 말을 잘 듣지 못하거든요.', `FemaleText_loc4`='你刚才说话了吗？抱歉，每次有人被干掉时，我总会兴奋过头，从而忘了听别人说话。', `FemaleText_loc5`='你在跟我說話嗎?真抱歉，當我正在享受殺戮樂趣的時候，通常不會注意別人說了什麼。', `FemaleText_loc7`='¿Has dicho algo? Perdona, tiendo a no prestar atención cuando se matan cosas para divertirme.' WHERE `ID`=73135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 전 싸우러 온 게 아닙니다. 그저 브루스를 응원하러 왔을 뿐입니다.', `MaleText_loc4`='不，不，我不是来打拳的。我主要是来给布鲁斯捧场的。', `MaleText_loc5`='喔不，我可不會上場打鬥，我來這主要是為了幫布魯斯加油的。', `MaleText_loc7`='No, no, yo no participo en las refriegas. Solo he venido a animar a Bruce.' WHERE `ID`=73136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아, 그래, 암흑소환사와 처음 싸우던 때가 생각나는군요... 두 번째 싸우던 때도... 세 번째도...', `MaleText_loc4`='啊，没错，我还记得我第一次跟黑暗召唤师战斗的情况。然后是第二次……第三次……', `MaleText_loc5`='喔對，我還記得我第一次對上黑暗召喚師的戰鬥，還有第二次...還有第三次...', `MaleText_loc7`='Sí, recuerdo la primera vez que me enfrenté al invocador oscuro. Y la segunda... y la tercera...' WHERE `ID`=73137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조언을 해달라고요? 절대로 적을 얕보지 마십시오. 아무리 키가 작고, 비틀거리고, 심장을 녹일 만큼 귀엽다고 해도, 만만하게 보면 안 됩니다.', `MaleText_loc4`='你问我有什么建议？永远不要低估你的对手，无论他们有多瘦小，多笨拙，或是多可爱。', `MaleText_loc5`='需要建議嗎?千萬別低估你的對手，不管他們有多矮、多可愛，走起路來有多不穩，你都得格外小心才行。', `MaleText_loc7`='¿Te doy un consejo? No infravalores nunca a tu enemigo. Por muy bajo, patoso o descorazonadoramente entrañable que sea.' WHERE `ID`=73138;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왜 그래? 가끔은 죽음의 기사도 좀 예쁘게 차려 입을 수 있잖아?', `FemaleText_loc4`='什么？死亡骑士就不能偶尔打扮一下吗？', `FemaleText_loc5`='什麼?難道死亡騎士就不能偶爾打扮一下嗎?', `FemaleText_loc7`='¿Qué? ¿Acaso no puede emperifollarse un poco un caballero de la Muerte de vez en cuando?' WHERE `ID`=73139;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 여자가 나랑 똑같은 옷을 입었다니. 자존심 상해!', `FemaleText_loc4`='真不敢相信，我居然跟她撞衫了。真是太尴尬了。', `FemaleText_loc5`='我不敢相信她竟然跟我穿同樣的衣服，這真是太尷尬了。', `FemaleText_loc7`='No me puedo creer que llevase el mismo vestido que YO. ¡Qué vergüenza!' WHERE `ID`=73140;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='한 번만 더 내게 그런 눈길을 보내면 배 밖으로 던져버리겠어.', `FemaleText_loc4`='你要敢再那么看我一眼，我就把你从船上推下去。', `FemaleText_loc5`='要是你像這樣再多看我一眼，我就把你推下去。', `FemaleText_loc7`='Vuelve a quedarte mirándome de ese modo otra vez y te tiro del barco de un empujón.' WHERE `ID`=73141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구가는 여기 있으면 안 된다. 그런데 구가는 여기서 어떻게 내려갈지 모르겠다.', `MaleText_loc4`='古嘎其实不想呆在这儿的。古嘎只是不知道该怎么下去。', `MaleText_loc5`='古嘎不該來這裡，古嘎只是不知道該怎麼下去。', `MaleText_loc7`='En realidad Guga no debería estar akí. Pero Guga no sabe kómo bajar.' WHERE `ID`=73142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='구가가 한 번 싸웠는데 악어에게 조금물어 뜯겼다.$b$b아무도 구가를 응원하지 않는다.$b$b구가 슬프다.', `MaleText_loc4`='古嘎打过一次，结果被鳄鱼咬了一口。$b$b人人都讨厌古嘎。$b$b古嘎伤心了。', `MaleText_loc5`='古嘎打過一次，但是差點被鱷魚給吃掉。$b$b大家都噓我。$b$b古嘎好傷心。', `MaleText_loc7`='Guga luchó una vez, pero le komió un poko un krokolisko.$b$bTodos animaban al krokolisko, no a Guga.$b$bGuga se sintió triste por ello.' WHERE `ID`=73143;
