UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바젤플랜지 대표님은 사람들이 투기장에서 더 많이 싸우길 원하셔. 그리고 더 잘 싸우길 바라시고.

"장려책!"이라고 강조하셨지. "싸움에 안달이 나도록 만드는 더욱 매력적인 장려책이 필요해!"

그래서 이 비행선을 만들라고 하시더라고. 여기서 보면 경치도 좋고, 비싸 보이는 술도 많고, 무엇보다 친구들에게 자랑할 수 있지. 너희들은 갈 수 없는 곳에 내가 가보았다고. 대표님께서 8계급 이상의 싸움꾼들만 출입을 허락했거든.

비행선에 올라가고 싶어? 그럼 계속 싸우라고, 친구.', `MaleText_loc4`='巴泽法兰老板希望能有更多人加入拳手的行列，并希望他们能打出更高水平的比赛。

“奖励！”她说，“我们需要给他们一个更诱人的理由去战斗！”

于是，她让我们造了这艘飞艇。你瞧，这里能提供更好的观赛角度，各种顶级美酒，还有向朋友们吹嘘的资本。你瞧——只有8级或8级以上的拳手才能上去。

你想上飞艇吗？那就多赢几场拳赛吧，伙计。', `MaleText_loc5`='老闆貝索弗蘭吉要找更多人來加入鬥陣的行列，而且還要提升打鬥的水準。

「刺激市場!」她說，「我們得給大家更強烈的鬥陣動機才行!」

所以她叫我們打造了這艘飛艇，你看。它擁有一流的觀戰視野，上頭可以買到各式各樣的精選好酒，而且還可以跟你的同伴們炫耀這個他們上不去的地方，因為她只允許第8階以上的打鬥者上去。

你想上這艘飛艇嗎?再多贏個幾場吧，老兄。', `MaleText_loc7`='La jefa Zumbarriel quiere a más gente luchando, y quiere que lo hagan mejor.

"¡Incentivos!", dice ella. "¡Tenemos que darles mejores razones para pelear!"

Así que nos ha hecho construir este zepelín, ¿ves? Con vistas maravillosas de la pelea, todo el alcohol fino que puedas comprar y la satisfacción de fanfarronear con tus amigos sobre que puedes ir a un sitio al que ellos no pueden ir. Porque solo te deja subir si tienes rango 8 o superior.

¿Quieres subir al zepelín? Pues sigue ganando tus peleas.' WHERE `ID`=73179;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동기에 올라가, $n! 아마 죽지는 않을 거야!

뭐, 죽을 수도 있겠지만 내 알 바 아니지.', `MaleText_loc4`='快跳上传送器，$n！它没准是安全的！

当然，它也有可能要了你的命。', `MaleText_loc5`='跳上傳送器吧，$n!傳一下應該不至於殺死你!

但還是有這個可能啦。', `MaleText_loc7`='¡Sube al teletrasportador, $n! ¡Probablemente no te mate!

Aunque puede que sí te mate, claro.' WHERE `ID`=73180;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대장님, 이 코르크론 놈들은 그리 친절해 보이진 않는데요!', `MaleText_loc4`='长官，这些库卡隆看起来不是很友善啊！', `MaleText_loc5`='長官，這些柯爾克隆看起來並不友善!', `MaleText_loc7`='¡Estos Kor''kron no parecen muy amistosos!' WHERE `ID`=73181;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물 보너스 +15!', `MaleText_loc4`='+15点遗物奖励！', `MaleText_loc5`='+15點文物獎勵!', `MaleText_loc7`='¡15 artefactos extra!', `FemaleText_loc1`='유물 보너스 +15!', `FemaleText_loc4`='+15点遗物奖励！', `FemaleText_loc5`='+15點文物獎勵!', `FemaleText_loc7`='¡15 artefactos extra!' WHERE `ID`=73182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유물 보너스 +30!', `MaleText_loc4`='+30点遗物奖励！', `MaleText_loc5`='+30點文物獎勵!', `MaleText_loc7`='¡30 artefactos extra!', `FemaleText_loc1`='유물 보너스 +30!', `FemaleText_loc4`='+30点遗物奖励！', `FemaleText_loc5`='+30點文物獎勵!', `FemaleText_loc7`='¡30 artefactos extra!' WHERE `ID`=73183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 호드 금광 수레를 놓쳤습니다!', `MaleText_loc4`='联盟丢弃了部落运金车！', `MaleText_loc5`='聯盟棄置部落的黃金礦車了!', `MaleText_loc7`='¡La Alianza ha volcado el carro de oro de la Horda!' WHERE `ID`=73184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 호드의 황금을 가로챘습니다!', `MaleText_loc4`='联盟偷走了部落的黄金！', `MaleText_loc5`='聯盟偷走了部落的黃金!', `MaleText_loc7`='¡La Alianza ha robado el oro de la Horda!' WHERE `ID`=73185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 결투를 원하는가? 그렇다면 들어주지!', `MaleText_loc4`='啊，这么说你想决斗？那就如你所愿！', `MaleText_loc5`='喔，你想跟我對決嗎?那就放馬過來吧!', `MaleText_loc7`='Ah, así que esto va a ser un duelo. Muy bien.' WHERE `ID`=73186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s|1이;가; |cFFFF0000바위|r를 냅니다! 당신이 |cFF00FF00이겼습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你|cFF00FF00赢|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_stone_10.blp:20|t%s出|cFFFF0000石頭|r!你|cFF00FF00贏|r了!', `MaleText_loc7`='|TInterfaceIconsinv_stone_10.blp:20|t ¡%s elige |cFFFF0000piedra|r! ¡Tú |cFF00FF00ganas|r!' WHERE `ID`=73187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s|1이;가; |cFFFF0000바위|r를 냅니다! 당신이 |cFFFF0000졌습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你|cFFFF0000输|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_stone_10.blp:20|t%s出|cFFFF0000石頭|r!你|cFFFF0000輸|r了!', `MaleText_loc7`='|TInterfaceIconsinv_stone_10.blp:20|t ¡%s elige |cFFFF0000piedra|r! ¡Tú |cFFFF0000pierdes|r!' WHERE `ID`=73188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s|1이;가; |cFFFF0000바위|r를 냅니다! 비겼습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_stone_10.blp:20|t %s选择了|cFFFF0000石头|r！你们打平了！', `MaleText_loc5`='|TInterface\\Icons\\inv_stone_10.blp:20|t%s出|cFFFF0000石頭|r!雙方平手!', `MaleText_loc7`='|TInterfaceIconsinv_stone_10.blp:20|t ¡%s elige |cFFFF0000piedra|r! ¡Empate!' WHERE `ID`=73189;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요 $p 종족 $pr 직업 $pc', `FemaleText_loc4`='你好啊，$pr$pc$p', `FemaleText_loc5`='你好，$p種族$pr職業$pc', `FemaleText_loc7`='Hola, $p, raza $pr, clase $pc' WHERE `ID`=73190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='닭에게... 지다니!', `MaleText_loc4`='输给了……一只小鸡！', `MaleText_loc5`='你輸給了...一隻雞!', `MaleText_loc7`='¡Perder contra una... gallina!' WHERE `ID`=73191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 요원들이 잔달라를 여기까지 추적했소.', `MaleText_loc4`='我的密探追踪赞达拉到了这里。', `MaleText_loc5`='我的密探就是跟蹤贊達拉到這裡。', `MaleText_loc7`='Mis agentes rastrearon a los Zandalari hasta este lugar.' WHERE `ID`=73193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라가 놈들과 어떤 사악한 계획을 세우고 있을지...', `MaleText_loc4`='我真不敢想象赞达拉在跟他们搞什么邪恶阴谋……', `MaleText_loc5`='我不太想知道贊達拉跟他們之間有什麼陰謀...', `MaleText_loc7`='No quiero ni pensar en lo que estarán tramando hacer con ellos los Zandalari…' WHERE `ID`=73194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='확실히... 자연스러운 날씨가 아니오.', `MaleText_loc4`='是啊，这天气确实不正常。', `MaleText_loc5`='沒錯。這樣的天氣不自然。', `MaleText_loc7`='Sí. Este clima no es natural.' WHERE `ID`=73195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 용사들이 갈 것이오. 할 수 있는 일을 하고, 구출할 수 있는 이들을 구출할 거요.', `MaleText_loc4`='我让勇士们先上。他们会竭尽所能把我们的人救出来的。', `MaleText_loc5`='我的勇士會去。他們會看能做些什麼，並盡量進行救援。', `MaleText_loc7`='Mis campeones irán. Verán lo que se puede hacer y rescatarán a los que puedan.' WHERE `ID`=73196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그대가 여기 있어 힘이 나는구려, 모이라. 감사하오.', `MaleText_loc4`='你的到来真令人振奋，茉艾拉。谢谢你。', `MaleText_loc5`='在這裡看到你十分令人振奮，茉艾拉。我要向你致謝。', `MaleText_loc7`='Verte aquí es alentador, Moira. Te lo agradezco.' WHERE `ID`=73197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그래서 다른 부족의 지원 없이도 근위병들을 이끌고 온 거요?', `MaleText_loc4`='……所以你才会不顾其他部族的反对，率领着私人卫队来到这里？', `MaleText_loc5`='...所以儘管沒有其他氏族的支持，你還是派出了你的護衛?', `MaleText_loc7`='¿Movilizaste a tu guardia personal incluso sin contar con el apoyo de los demás clanes?' WHERE `ID`=73198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 잘 가시오, 섭정 여왕.', `MaleText_loc4`='嗯，保重，执政女王。', `MaleText_loc5`='嗯，再見了，攝政女王。', `MaleText_loc7`='Mmm. Adiós, reina regente.' WHERE `ID`=73199;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아지랑이 마루. 익히 아는 곳이오. 서리갈기 트롤들이 저 눈 덮인 언덕에서 새끼를 낳고, 음모를 꾸미지.', `FemaleText_loc4`='闪光岭。我知道霜鬃巨魔就窝在那片白雪皑皑的山头上。', `FemaleText_loc5`='閃光嶺。我知道那裡。霜鬃食人妖在那個冰天雪地的台地上密謀及繁衍。', `FemaleText_loc7`='Monte Luz. Lo conozco bien. Los Trols Peloescarcha se reproducen y conspiran en la cima de esa meseta nevada.' WHERE `ID`=73200;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='많은 산악경비대가 당했소. 이 기이한 폭풍과, 그 안에 숨은 트롤에게.', `FemaleText_loc4`='这场风暴害我们损失了许多巡山人，这可能是巨魔在搞鬼。', `FemaleText_loc5`='我們已經因為這場古怪的風暴和混在其中的食人妖失去許多巡山人了。', `FemaleText_loc7`='Perdimos a muchos alpinistas por culpa de esa tormenta extraña o de los trols que acechaban en ella.' WHERE `ID`=73201;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그렇소. 내 사람들을 저기 보내고 싶진 않소. 매복과, 피비린내 나는 재앙이 느껴지오.', `FemaleText_loc4`='没错。我真不想派人过去，那儿净是埋伏和腐臭。', `FemaleText_loc5`='是的。所以我不想派我的人出去。一定有埋伏跟災難等著我們。', `FemaleText_loc7`='Cierto. Aborrezco mandar a mis hombres a su merced. Apesta a emboscada y a desastre violento.' WHERE `ID`=73202;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그들이 폭풍을 멈춘다면, 내 직접 제련소경비병들을 이끌고 올라가겠소.', `FemaleText_loc4`='如果他们能阻止风暴，我就亲自率领熔炉卫士上去。', `FemaleText_loc5`='如果他們可以遏止這個風暴，我會親自率領鐵爐衛登頂。', `FemaleText_loc7`='Si son capaces de detener esa tormenta, yo personalmente guiaré al Guardaforjado a la cima.' WHERE `ID`=73203;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나도 그대에게 감사하오, 바리안. 왕실에서 그대가 한 말이 맞소.', `FemaleText_loc4`='我也要多谢你，瓦里安。你在大厅上的话很有道理……', `FemaleText_loc5`='我也一樣，瓦里安。你在王座廳說得沒錯...', `FemaleText_loc7`='Y yo te agradezco a ti, Varian. Tus palabras en la sala del trono resonaron la verdad: la disensión dentro del Consejo de los Tres Martillos tiene que terminarse.' WHERE `ID`=73204;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그대의 용사들이 도와준다면, 검은무쇠 부족이 던 모로에서 잔달라를 끝장낼 수 있을 거요.', `FemaleText_loc4`='没错。有了这些勇士的协助，黑铁矮人就能终结赞达拉对丹莫罗的威胁。', `FemaleText_loc5`='沒錯。有了你的勇士們幫忙，黑鐵氏族會終結丹莫洛的贊達拉威脅。', `FemaleText_loc7`='Así es. Con la ayuda de tus campeones, Los Hierro Negro acabarán con la amenaza Zandalari en Dun Morogh.' WHERE `ID`=73205;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다 끝나면 봅시다, 스톰윈드의 왕이여.', `FemaleText_loc4`='我们回头见，暴风城国王。', `FemaleText_loc5`='等這一切都搞定再見吧，暴風之王。', `FemaleText_loc7`='Nos veremos cuando esto se termine, Rey de Ventormenta. ' WHERE `ID`=73206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다... 판다리아의 지혜가 거하는 고대의 보금자리지.$b$b시작할까?', `MaleText_loc4`='我们到了——古老的熊猫人智慧宝库。$b$b我们开始吧？', `MaleText_loc5`='到了，就是這裡，熊貓人悠遠的智慧就在此處。$b$b可以開始了嗎?', `MaleText_loc7`='Aquí estamos... en la antigua cuna de la sabiduría pandaren.$b$b¿Comenzamos?' WHERE `ID`=73207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네, 위론 님께 갑시다.', `MaleText_loc4`='那么，就去觐见玉珑吧。', `MaleText_loc5`='那就去找玉龍吧。', `MaleText_loc7`='Por Yu''lon, pues.' WHERE `ID`=73208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위론 님이 기다리고 계십니다!', `MaleText_loc4`='玉珑在等着呢！', `MaleText_loc5`='玉龍正等著我們。', `MaleText_loc7`='¡Yu''lon espera!', `FemaleText_loc1`='위론 님이 기다리고 계세요!', `FemaleText_loc4`='玉珑在等着呢！', `FemaleText_loc5`='玉龍正等著我們。', `FemaleText_loc7`='¡Yu''lon espera!' WHERE `ID`=73209;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리의 충성을 증명하겠소... 의회에, 아이언포지에, 얼라이언스에. 오늘 여기서, 우리의 피로.', `FemaleText_loc4`='此时此地，我们将用自己的鲜血向议会、铁炉堡和联盟证明自己的忠诚。', `FemaleText_loc5`='我們會向議會、鐵爐堡及聯盟證明自己的忠誠。就在此時、此刻，以鮮血證明。', `FemaleText_loc7`='Nosotros probaremos nuestra lealtad al Consejo, a Forjaz y a la Alianza; aquí, hoy, y con nuestra propia sangre.' WHERE `ID`=73211;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='세 망치 의회의 불화는, 끝나야 하오.', `FemaleText_loc4`='三锤议会的内讧必须终止。', `FemaleText_loc5`='三錘議會之間的意見不和必須結束。', `FemaleText_loc7`='Debemos poner fin a la discordia en el Consejo de los Tres Martillos.' WHERE `ID`=73212;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저 폭풍을 만들어내는 사악한 것을 멈춰라. 그러면 제련소경비병들이 아지랑이 마루를 공격해, 서리갈기와 잔달라 놈들을 모두 쓸어버릴 테니.$B$B내 산악경비대 대원들과, 트롤이 잡아간 포로들에게서 정보를 얻도록.', `FemaleText_loc4`='不管是什么邪恶力量引来了这场风暴，快去阻止它吧。这样，熔炉卫士就能攻上山头，并扫清那里的霜鬃和赞达拉巨魔。$B$B去找我的巡山人，或者任何被巨魔俘虏的人，他们能为你指路。', `FemaleText_loc5`='不管那個風暴是由什麼邪惡事物所召喚的，我們都必須阻止它，而鐵爐衛則負責攻擊那座山脊，消滅霜鬃和贊達拉食人妖的部隊。$B$B我的巡山人和那些被食人妖抓走的俘虜會為你指引方向。', `FemaleText_loc7`='Detén la maldad que está conjurando esta tormenta, y los guardaforjados asaltarán la cima y eliminarán a los Peloescarcha y a los Zandalari.$B$BUsa a mis montaraces y a los prisioneros de los trols para guiarte.' WHERE `ID`=73213;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 누군가 만들어낸 저 폭풍을 멈출 방법을 찾아라. 포로를 최대한 많이 구출하고.$B$B몸 조심해라.', `MaleText_loc4`='请想办法阻止这场人为的风暴，勇士，并尽力拯救俘虏。$B$B祝你好运。', `MaleText_loc5`='想辦法阻止那個魔法風暴，勇士，並且盡力拯救那些被抓走的俘虜。$B$B再會了。', `MaleText_loc7`='Encuentra el modo de detener esa tormenta conjurada, y rescata a todos los prisioneros que puedas.$B$BAdiós.' WHERE `ID`=73214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 왔군. 간단히 설명해 주지. 왕의 비밀요원들은 다 죽었어. 드워프 정찰병만 몇 명 살아 있지.', `MaleText_loc4`='你们可来了。听我说：国王的密探都死光了。只有少数矮人斥候活了下来。', `MaleText_loc5`='你來了。現在的狀況是這樣:國王的密探都被殺了。只剩下一些矮人斥候還活著。', `MaleText_loc7`='Aquí estás. Esto es lo que está pasando: los espías del rey fueron asesinados. Solamente queda un puñado de enanos exploradores.' WHERE `ID`=73218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제일 가까운 정찰병은 바로 저기 있네. 그를 구해주면 뭔가 알려줄지도 모르지.', `MaleText_loc4`='前面就有一个。要是能救下他，也许就能了解些情况。', `MaleText_loc5`='最接近的就在前面。如果你能救他下來，也許他知道些情報。', `MaleText_loc7`='El más cercano está allí adelante. Si puedes salvarlo, tal vez tenga información para ti.' WHERE `ID`=73219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오래 전, 아니, 사실은 조금 전이네만, 위대한 왕이 강인한 드워프 세 명에게 도움을 청했네. 그래, 세 망치단 의회였어.', `MaleText_loc4`='从前——其实也没过多久——有位伟大的国王向三位强大的矮人，也就是三锤议会求助。', `MaleText_loc5`='曾經，事實上就在不久前，有位偉大的國王尋求三群強大的矮人幫忙: 他們叫三錘議會。', `MaleText_loc7`='Hace un tiempo (de hecho hace unos minutos) un gran rey buscó la ayuda de tres enanos poderosos: el Consejo de los Tres Martillos.' WHERE `ID`=73220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잔달라 트롤이 드워프의 수도를 공격한다는 사실을 알아낸 참이었지.', `MaleText_loc4`='国王的密探发现，赞达拉巨魔正威胁着矮人的主城。', `MaleText_loc5`='國王的斥候發現矮人的首都正面臨贊達拉食人妖的威脅。', `MaleText_loc7`='Los exploradores del rey descubrieron que los Zandalari amenazaban la capital enana. ' WHERE `ID`=73221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕은 생각했네. ''그래, 트롤 문제를 해결해 주면, 호드와 맞설 때 드워프가 더 많은 병력을 동원해 주겠지?''', `MaleText_loc4`='国王想当然地认为，只要帮他们化解巨魔危机，他们就会派出军队帮他对抗部落。', `MaleText_loc5`='國王心想，若他幫矮人解決食人妖的麻煩，就能爭取到更多軍隊加入對抗部落的戰役。', `MaleText_loc7`='El rey pensó que si ayudaba a los enanos a lidiar con el problema que tenían, ellos le darían más tropas para su campaña contra la Horda. ' WHERE `ID`=73222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 국왕이 몰랐던 것은, 드워프들이 서로를 믿지 않는다는 점이었네!', `MaleText_loc4`='可国王没有想到，矮人们竟然对彼此毫不信任！', `MaleText_loc5`='但是國王並沒想到，矮人之間也存在著信任問題!', `MaleText_loc7`='¡Pero lo que el rey no tuvo en cuenta es que ningún enano confiaba en los otros de su especie!' WHERE `ID`=73223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='브론즈비어드가 말했지. "우린 도와줄 수 없소. 검은무쇠에게 등을 보였다가는, 그들이 와일드해머를 무너뜨리고 아이언포지를 차지할 테니까!"', `MaleText_loc4`='“我们帮不了你，”铜须矮人说，“如果我们不盯紧黑铁矮人，他们就会击败蛮锤矮人并占据铁炉堡！”', `MaleText_loc5`='銅鬚矮人說，「我們不能幫你。如果我們不注意黑鐵矮人，他們會擊敗蠻錘然後接收鐵爐堡!」', `MaleText_loc7`='"No podemos ayudarte" dijo el enano Barbabronce "¡Debido a que, si no vigilamos a los Hierro Negro, derrotarán a Martillo Salvaje y se apoderarán de Forjaz!"' WHERE `ID`=73224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='와일드해머가 말했지. "우린 도와줄 수 없소. 검은무쇠에게 등을 보였다가는, 그들이 브론즈비어드를 무너뜨리고 아이언포지를 차지할 테니까!"', `MaleText_loc4`='“我们帮不了你，”蛮锤矮人说，“如果我们不盯紧黑铁矮人，他们就会击败铜须矮人并占据铁炉堡！”', `MaleText_loc5`='蠻錘矮人說，「我們不能幫你。如果我們不注意黑鐵矮人，他們會擊敗銅鬚然後接收鐵爐堡!」', `MaleText_loc7`='"No podemos ayudarte" dijo el enano Martillo Salvaje. "¡Si no vigilamos a los Hierro Negro, derrotarán a Barbabronce y se apoderarán de Forjaz!"' WHERE `ID`=73225;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕은 분노했네. "아무도 돕지 않으면, 아이언포지는 짓밟히고 무너질 것이오!"', `MaleText_loc4`='国王很生气，”如果你们都不帮忙，铁炉堡就会被攻陷！”', `MaleText_loc5`='國王氣壞了。他說:「如果你們都不幫忙，鐵爐堡會被攻陷!」', `MaleText_loc7`='El rey estaba furioso."Si ninguno de ustedes ayuda, ¡entonces Forjaz será asediada!"' WHERE `ID`=73226;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오직 한 명의 드워프만이 앞으로 나섰네. "우리 힘을 빌려주겠소." 바로 검은무쇠 부족의 모이라였지. "우리가 드워프 형제들에게 신뢰가 무엇인지 직접 보여주겠소!"', `MaleText_loc4`='只有一位矮人愿意帮忙：“我们愿意出力，”黑铁矮人茉艾拉说，“我们信任其他矮人兄弟，还要让他们看看什么叫忠诚！”', `MaleText_loc5`='只有一個矮人願意幫助國王。黑鐵氏族的茉艾拉說，「我們願意出兵。我們會信任其他族的矮人兄弟，並讓他們看看什麼叫做忠誠!」', `MaleText_loc7`='Solo alguien se ofreció al Rey."Nosotros te prestaremos nuestras fuerzas" dijo Moira del Hierro Negro. "¡Confiaremos en nuestros hermanos y les mostraremos el significado de la lealtad!"' WHERE `ID`=73227;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇게 모이라와 국왕은 그 도시를 구하기 위해 설원으로 나섰네. 다른 이들은 자신의 행동을 돌이켜봐야 했지.', `MaleText_loc4`='于是茉艾拉和国王深入雪山去拯救铁炉堡，留下其他人反思自己的行为。', `MaleText_loc5`='所以大君主跟茉艾拉在冰雪連天中出發拯救城市，讓其他人好好去想想他們的作為。', `MaleText_loc7`='Y así fue que Moira y el Alto Rey se adentraron en la nieve para salvar la ciudad y dejaron a los otros para que pensaran en sus acciones.' WHERE `ID`=73228;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 어떻게 될까? 정말 궁금하군!', `MaleText_loc4`='后来怎么样了？我必须知道！', `MaleText_loc5`='接下來會怎樣呢?我一定要知道!', `MaleText_loc7`='¿Y qué pasó después? ¡Necesito saber más! ' WHERE `ID`=73229;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='국왕과 그의 용사들, 그리고 검은무쇠 부족 드워프는 힘을 합쳐 아이언포지를 지켜냈네.', `MaleText_loc4`='国王率领他的勇士，和黑铁矮人齐心协力拯救了铁炉堡。', `MaleText_loc5`='大君主、他的勇士跟黑鐵矮人一起努力拯救了鐵爐堡。', `MaleText_loc7`='El Alto Rey, sus campeones y los enanos de Hierro Negro trabajaron juntos para salvar Forjaz. ' WHERE `ID`=73230;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 드워프 지도자들은 자신의 행동이 부끄러워, 다시는 공포나 불신이 판단을 흐리게 하지 않겠다고 맹세했네.', `MaleText_loc4`='其他矮人首领为自己的行为感到羞愧，发誓再也不让恐惧或猜忌影响自己的判断。', `MaleText_loc5`='其他的矮人領袖們對自己的行為感到羞恥，並發誓絕不再讓恐懼或懷疑影響他們的判斷。', `MaleText_loc7`='Los otros líderes enanos se sintieron avergonzados por su comportamiento y juraron nunca volver a permitir que el miedo y la desconfianza nublaran su juicio.' WHERE `ID`=73231;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이렇게 오랫동안 분열되어 있던 드워프를 하나로 합친 건 바로 인간 국왕이었네.', `MaleText_loc4`='就这样，一位人类国王将分裂已久的矮人部族团结了起来。', `MaleText_loc5`='所以，是一位人類國王促成長期以來分裂的矮人部族再度統一。', `MaleText_loc7`='Y así fue que un rey humano ayudó a unir a los clanes de enanos que hacía tanto tiempo estaban divididos.' WHERE `ID`=73232;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 서로를 믿게 된 세 드워프 지도자들은 온 힘을 다해 얼라이언스를 지원하러 나섰네.', `MaleText_loc4`='彼此信赖的三位矮人首领承诺，要为联盟大业献出全部力量。', `MaleText_loc5`='在彼此信任的前提下，三位矮人領袖們宣示他們將全心全力為聯盟效忠。', `MaleText_loc7`='Con la posibilidad de confiar en los demás, los tres líderes enanos prometieron dar toda su fuerza a la causa de la Alianza.' WHERE `ID`=73233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그동안 오그리마에서는 가로쉬 헬스크림 대족장이 고블린 발굴단을 꾸려 판다리아 대륙 이곳저곳으로 보냈네.', `MaleText_loc4`='而此时，在奥格瑞玛，酋长加尔鲁什·地狱咆哮向潘达利亚各地派出了大量地精挖掘队。', `MaleText_loc5`='同時，在奧格瑪，大酋長卡爾洛斯·地獄吼派出了許多哥布林挖掘隊伍到潘達利亞大陸上。', `MaleText_loc7`='Mientras tanto, en la ciudad de Orgrimmar, el Jefe de Guerra Garrosh Grito Infernal envió equipos de excavación goblin por todo el continente de Pandaria.' WHERE `ID`=73234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아를 강력한 어둠의 힘으로 채우는, 그 비밀의 근원을 발견하는 자에게는 막대한 금화와 보물을 선사하겠다고 약속하면서.', `MaleText_loc4`='他许诺，谁能为他解开这片土地中那股强大的黑暗力量背后的秘密，就能得到黄金和财富。', `MaleText_loc5`='他答應只要能找到使潘達利亞充滿如此黑暗強大能量的秘密，他便會賜予大量的金銀財寶', `MaleText_loc7`='Prometió oro y riquezas para aquel que descubriera para él los secretos ocultos de esta tierra que llenan a Pandaria con semejante energía oscura y poderosa. ' WHERE `ID`=73235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍게도, 그들이 뭔가 발견한 모양이네! 바로 여기, 이 신성한 골짜기에서! 이제 무슨 일이 일어날까?', `MaleText_loc4`='令我惊讶的是，他的人真有了发现！就在这圣谷之中！那后来呢？', `MaleText_loc5`='令我驚訝的是，他派的人真的找到東西了!就在這個神聖的谷中!接下來會如何呢?', `MaleText_loc7`='Sorprendentemente, ¡su gente encontró algo! ¡Aquí mismo, en el valle sagrado! ¿Qué ocurrirá ahora?' WHERE `ID`=73236;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 이 이야기는 지금도 쓰여지고 있다네...', `MaleText_loc4`='故事仍在继续……', `MaleText_loc5`='故事，正在展開中...', `MaleText_loc7`='La historia todavía se está escribiendo…' WHERE `ID`=73237;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 얼라이언스가 그 어느 때보다 강하게 결집하는 사이, 호드는 내부에서부터 조각나고 있네.', `MaleText_loc4`='所以，当联盟前所未有地团结一致时，部落却正在分崩离析。', `MaleText_loc5`='所以，就在聯盟更緊密結合的時候，部落呢，卻正在四分五裂。', `MaleText_loc7`='¡Ajá! Así que, mientras que la Alianza se une cada vez más, la Horda se está haciendo trizas. ' WHERE `ID`=73238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 아무래도 뭔가 일이 터질 것만 같군. 나도 이제부터 일어날 이야기를 경험하고 싶네만... 허허, 이런. 나는 그저 이야기꾼에 불과해.', `MaleText_loc4`='朋友，大事将要发生。我很想亲身体验接下来的故事，但是，很可惜，我只是个说故事的人。', `MaleText_loc5`='朋友，有大事要發生了。我希望能親身體驗接下來的故事章節，但可惜了，我只是個說故事的人。', `MaleText_loc7`='Algo está por ceder. Quisiera poder vivir el próximo capítulo de la historia, pero no soy más que un narrador de cuentos. ' WHERE `ID`=73239;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네와 같은 용감한 영웅만이 지금 펼쳐지는 사건의 중심에 뛰어들 힘이 있네.', `MaleText_loc4`='而你，勇敢的英雄——你很强大，足以搅动时代的狂澜。', `MaleText_loc5`='你，勇敢的英雄，你有足夠的能力在這些事情展開的同時參與其中。', `MaleText_loc7`='Tú, solo tú: tú tienes la fuerza para saltar al centro de los sucesos en plena ocurrencia. ' WHERE `ID`=73240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 가게! 듀로타로 가게! 역사의 현장에 자네의 발자국을 남기게!', `MaleText_loc4`='快去吧！去杜隆塔尔！在历史上留下你的印记！', `MaleText_loc5`='去吧!前往杜洛塔!在歷史被寫下的同時為你自己留下一筆!', `MaleText_loc7`='¡Ve ahora mismo! ¡Ve a Durotar! ¡Deja tu huella en la historia que se desarrolla a tu alrededor!' WHERE `ID`=73241;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물리학의 법칙이여 감사합니다! 어서 와!', `MaleText_loc4`='感谢物理法则，你可来了！', `MaleText_loc5`='感謝物理定律，你終於來了!', `MaleText_loc7`='¡Gracias a las leyes de la física que están aquí!' WHERE `ID`=73242;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s|1이;가; |cFFFF0000보|r를 냅니다! 당신이 |cFFFF0000졌습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你|cFFFF0000输|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t%s出|cFFFF0000布|r!你|cFFFF0000輸|r了!', `MaleText_loc7`='|TInterfaceIconsinv_inscription_scroll.blp:20|t ¡%s elige |cFFFF0000papel|r! ¡Tú |cFFFF0000pierdes|r!' WHERE `ID`=73243;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s|1이;가; |cFFFF0000보|r를 냅니다! 비겼습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你们打平了！', `MaleText_loc5`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t%s出|cFFFF0000布|r!雙方平手!', `MaleText_loc7`='|TInterfaceIconsinv_inscription_scroll.blp:20|t ¡%s elige |cFFFF0000papel|r! ¡Empate!' WHERE `ID`=73244;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s|1이;가; |cFFFF0000보|r를 냅니다! 당신이 |cFF00FF00이겼습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t %s选择了|cFFFF0000布|r！你|cFF00FF00赢|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_inscription_scroll.blp:20|t%s出|cFFFF0000布|r!你|cFF00FF00贏|r了!', `MaleText_loc7`='|TInterfaceIconsinv_inscription_scroll.blp:20|t ¡%s elige |cFFFF0000papel|r! ¡Tú |cFF00FF00ganas|r!' WHERE `ID`=73245;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s|1이;가; |cFFFF0000가위|r를 냅니다! 당신이 |cFFFF0000졌습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你|cFFFF0000输|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_sword_102.blp:20|t%s出|cFFFF0000剪刀|r!你|cFFFF0000輸|r了!', `MaleText_loc7`='|TInterfaceIconsinv_sword_102.blp:20|t ¡%s elige |cFFFF0000tijera|r! ¡Tú |cFFFF0000pierdes|r!' WHERE `ID`=73246;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s|1이;가; |cFFFF0000가위|r를 냅니다! 비겼습니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你们打平了！', `MaleText_loc5`='|TInterface\\Icons\\inv_sword_102.blp:20|t%s出|cFFFF0000剪刀|r!雙方平手!', `MaleText_loc7`='|TInterfaceIconsinv_sword_102.blp:20|t ¡%s elige |cFFFF0000tijera|r! ¡Empate!' WHERE `ID`=73247;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s|1이;가; |cFFFF0000가위|r를 냅니다! 당신이 |cFF00FF00이겼습니다|r!', `MaleText_loc4`='|TInterface\\Icons\\inv_sword_102.blp:20|t %s选择了|cFFFF0000剪刀|r！你|cFF00FF00赢|r了！', `MaleText_loc5`='|TInterface\\Icons\\inv_sword_102.blp:20|t%s出|cFFFF0000剪刀|r!你|cFF00FF00贏|r了!', `MaleText_loc7`='|TInterfaceIconsinv_sword_102.blp:20|t ¡%s elige |cFFFF0000tijera|r! ¡Tú |cFF00FF00ganas|r!' WHERE `ID`=73248;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오호호호호, 내 수염에 걸고 이번엔 끝장인 줄 알았는데. 아이고 고맙습니다. 고마워요!', `MaleText_loc4`='噢，以我胡须的名义，我还以为死定了呢！谢谢你们！谢谢你们！', `MaleText_loc5`='噢，我的鬍子啊，我還以為我完蛋了!噢，謝謝你，謝謝你!', `MaleText_loc7`='Ay, por mis barbas, ¡pensé que estaba acabado! ¡Ay! ¡Te agradezco, te agradezco!' WHERE `ID`=73249;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 맞아요. 그게... 인간 왕이 당신을 보냈습니까? 그의 비밀요원은 다 죽었습니다. 우리도 거의 다 당했고요.', `MaleText_loc4`='那么……是人类国王派你们来的？他的密探都死了……我们的人也牺牲了大半。', `MaleText_loc5`='噢，對了，現在...是那個人類國王派你來的?噢，他的密探都死了...我們大部分的人也都死了。', `MaleText_loc7`='Ah, bien, veamos... ¿te envió el rey humano? Ah, sus espías están todos muertos... y la mayoría de nosotros también.' WHERE `ID`=73250;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼드브루가 막 물고 차면서 남쪽 오두막으로 끌려가는 걸 봤습니다. 서두르시면 그녀를 구할 수 있을 겁니다. 저보단 아는 게 많을걸요.', `MaleText_loc4`='我看见他们拖着粗酿往南边的小屋去了。如果你们动作快，或许能救下她，她可能知道更多的情况。', `MaleText_loc5`='我看到他們拖著勇釀到南邊的小屋那裡。現在，如果你快一點，還來得及救她，她也許知道更多消息。', `MaleText_loc7`='Los vi llevarse a Birraudaz a rastras, pataleando, hacia una choza al sur de aquí. Si te apresuras, podrás ayudarla y tal vez sepas más.' WHERE `ID`=73251;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 오두막이 여러 개 있는 곳은 피하십시오! 잔뜩 흥분한 얼음 트롤이 득시글거리니까요. 으... 잔달라 사제가 놈들이 아주 미쳐 돌아가게 만들었어요.', `MaleText_loc4`='但别靠近那座大村子！那里全是发疯的冰巨魔！唉……那个赞达拉祭司让他们都发了疯！', `MaleText_loc5`='但是別進去那個大村子!那裡有一堆瘋狂的寒冰食人妖!噢，那個贊達拉牧師把他們搞得瘋瘋癲癲的。', `MaleText_loc7`='¡Pero NO TE ACERQUES A LA ALDEA GRANDE! ¡Allí hay decenas de esos trols de hielo desquiciados! Uuh... ese sacerdote zandalari los flageló hasta ponerlos furiosos.' WHERE `ID`=73252;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 음료에서 퍼져 나오는 향기를 맡다 보니, 입에 침이 고이고 마치 최면에 걸릴 것만 같습니다.', `MaleText_loc4`='这种令人口水直流的美酒散发着一股令人迷醉的香气。', `MaleText_loc5`='這個令人垂涎三尺的美酒散發出的香味，擁有近乎催眠人心的魔力。', `MaleText_loc7`='Este brebaje tan apetecible desprende un aroma casi hipnótico.' WHERE `ID`=73253;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하아, 꽤 위험했는데. 고마워요!', `FemaleText_loc4`='噢，刚才好险呐，多谢了！', `FemaleText_loc5`='噢，只差那麼一點，謝謝你!', `FemaleText_loc7`='Uy, ¡qué CERCA estuvo eso! ¡Te agradezco!' WHERE `ID`=73254;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='남은 동료가 얼마 없어요. 놈들한테 잡아먹히지 않은 드워프는 제물이 되고 있지요.', `FemaleText_loc4`='幸存者很少；没被吃掉的人都被杀死在西北边的祭坛上。', `FemaleText_loc5`='我們只剩下幾個人，沒被他們吃掉的人，都被帶到一個大祭壇上殺害。', `FemaleText_loc7`='Solo quedamos algunos de nosotros; a los que no se comieron, los destripan en algún altar grande.' WHERE `ID`=73255;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바로 북서쪽 제단에서요. 빨리 가면 몇 명 더 구할 수 있을 거예요! 이것밖에 몰라서 죄송하네요...', `FemaleText_loc4`='如果你们动作快，或许能救下几个！抱歉，我就知道这么多……', `FemaleText_loc5`='就在這裡的西北方，如果你動作快，也許還能拯救他們!很遺憾，我只知道這麼多了...', `FemaleText_loc7`='Está al noroeste de aquí; si te apresuras, ¡tal vez salves a algunos! Lamento no saber más…' WHERE `ID`=73256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 안 됩니다, $c님. 오늘은 훈련시켜드릴 수 없어요.$b$b<목소리를 낮춰 속삭이는 직업 상급자>$b$b코르크론이 우리 행동을 주시하고 있습니다. 가로쉬가 정기의 골짜기를 꽉 잡고 있거든요.$b$b도움이 필요하신가요? 그럼 볼진을 찾으십시오. 그라면 뭘 해야할지 알 겁니다.', `MaleText_loc4`='现在不行，$c。我今天没法训练你。$b$b<你的训练师压低嗓门，悄声说道。>$b$b库卡隆正盯着我们的一举一动。加尔鲁什已经控制了精神谷。$b$b你想帮忙？那就去找沃金吧。他知道该怎么办。', `MaleText_loc5`='現在不行，$c。今天我不能訓練你。$b$b<訓練師低聲地說。>$b$b柯爾克隆正嚴密地監視我們，精神谷的每個角落都在卡爾洛斯的掌控之中。$b$b要是你想幫忙的話，去找沃金，他知道該怎麼做。', `MaleText_loc7`='Ahora no, $c. Hoy no puedo entrenarte.$b$b<Tu instructor baja la voz y susurra.>$b$bLos Kor''kron observan cada uno de nuestros movimientos. Garrosh tiene el Valle de los Espíritus sometido.$b$b¿Quieres ayudar? Encuentra a Vol''jin. Él sabrá qué hacer.', `FemaleText_loc1`='지금은 안 됩니다, $c님. 오늘은 훈련시켜드릴 수 없어요.$b$b<목소리를 낮춰 속삭이는 직업 상급자>$b$b코르크론이 우리 행동을 주시하고 있습니다. 가로쉬가 정기의 골짜기를 꽉 잡고 있거든요.$b$b도움이 필요하신가요? 그럼 볼진을 찾으십시오. 그라면 뭘 해야할지 알 겁니다.', `FemaleText_loc4`='现在不行，$c。我今天没法训练你。$b$b<你的训练师压低嗓门，悄声说道。>$b$b库卡隆正盯着我们的一举一动。加尔鲁什已经控制了精神谷。$b$b你想帮忙？那就去找沃金吧。他知道该怎么办。', `FemaleText_loc5`='現在不行，$c。今天我不能訓練你。$b$b<訓練師低聲地說。>$b$b柯爾克隆正嚴密地監視我們。精神谷的每個角落都在卡爾洛斯的掌控之中。$b$b要是你想幫忙的話，去找沃金，他知道該怎麼做。', `FemaleText_loc7`='Ahora no, $c. Hoy no puedo entrenarte.$b$b<Tu instructora baja la voz y susurra.>$b$bLos Kor''kron observan cada uno de nuestros movimientos. Garrosh tiene el Valle de los Espíritus sometido.$b$b¿Quieres ayudar? Encuentra a Vol''jin. Él sabrá qué hacer.' WHERE `ID`=73257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='훈련이 필요한가? 지금은 정기의 골짜기를 들쑤시고 다니기엔 좋지 않은 시기야.$b$b<목소리를 낮춰 속삭이는 쿠난지>$b$b코르크론이 우리 행동을 주시하고 있어. 가로쉬가 정기의 골짜기를 꽉 잡고 있거든. 자네에게 말하는 모습이 발각되면 난 살해당할지도 몰라.$b$b운도 좋군. 놈들은 날 보지 못하니까. 고개를 더 숙이게, $n. 내 말은 비밀로 하고.', `MaleText_loc4`='你需要训练？你真是来错时候了，这会儿精神谷可不太平。$b$b<你的训练师压低嗓门，悄声说道。>$b$b库卡隆正盯着我们的一举一动。加尔鲁什已经控制了精神谷。如果他们看见我跟你说话，可能会杀了我的。$b$b幸运的是，他们永远都休想看见我。靠近点，$n。我们得低调行事。', `MaleText_loc5`='需要訓練嗎?你挑錯日子了，現在的精神谷可不是個閒晃的好地方。$b$b<訓練師低聲地說。>$b$b柯爾克隆正嚴密地監視我們，精神谷的每個角落都在卡爾洛斯的掌控之中。要是他們看見我跟你說話，我可是會沒命的。$b$b幸好，他們看不見我。靠近點，$n，別被他們給發現了。', `MaleText_loc7`='¿Necesitas entrenamiento? Has escogido un momento malísimo para meter las narices en el Valle de los Espíritus.$b$b<Tu instructor baja la voz y susurra.>$b$bLos Kor''kron observan cada uno de nuestros movimientos. Garrosh tiene el Valle de los Espíritus sometido. Podrían matarme si me vieran hablar contigo.$b$bPor suerte para ti, nunca me ven. Acércate, $n. Tenemos que mantener esto muy oculto.' WHERE `ID`=73258;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='전문기술 관련 업무를 일시적으로 중단합니다. 요리하는 법을 배우고 싶으세요? 다른 곳에서 알아보십시오.', `FemaleText_loc4`='训练服务已经暂停。你想学习烹饪？去别处学吧。', `FemaleText_loc5`='訓練服務暫時終止了。要是你想學烹飪的話，只好去別的地方問問。', `FemaleText_loc7`='Los servicios de formación se han suspendido temporalmente. ¿Quieres aprender a cocinar? Pues tendrás que buscar en otro lado.' WHERE `ID`=73259;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아니요. 지금은 안 됩니다.', `FemaleText_loc4`='不，现在不行。', `FemaleText_loc5`='抱歉，現在沒空。', `FemaleText_loc7`='No. Ahora no.' WHERE `ID`=73260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하네, $c. 여기 잉크가 다 말랐어.', `MaleText_loc4`='抱歉，$c。我的墨水都干了。', `MaleText_loc5`='抱歉，$c，店裡的墨水用光了。', `MaleText_loc7`='Lo siento, $c. La tinta eh''tá seca por aquí.' WHERE `ID`=73261;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오늘은 낚시 안 하네. 코르크론의 명령이야.', `MaleText_loc4`='库卡隆有令，今天不准钓鱼。', `MaleText_loc5`='今天不准釣魚，這是柯爾克隆下的命令。', `MaleText_loc7`='Hoy no se pesca. Órdenes Kor''kron.' WHERE `ID`=73262;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금은 안 되네, $n. 은행을 당분간 못 쓰게 됐어.$b$b코르크론 지도자들의 말로는 "허가받지 않은 출금"은 모두 금지한다는군. 그래도... 한 번 확인은 해보는 게 좋을 거야.', `MaleText_loc4`='今天不开业，$n。银行被暂时接管了。$b$b库卡隆首领说了，他们要杜绝任何“未经授权的提款行为”。但……你也许该去确认一下。', `MaleText_loc5`='現在不行，$n，在這段非常時期裡，銀行被接管了。$b$b柯爾克隆的領導者說他們不會讓任何人提領「未經核准」的款項，但...你還是可以再跟他們確認一下。', `MaleText_loc7`='Ahora no, $n. El banco ha sido absorbido.$b$bEl líder Kor''kron dijo que no permitiría ninguna "retirada no autorizada", pero... pero puede que quieras asegurah''te y confirmarlo.' WHERE `ID`=73263;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='여기 자네에게 줄 방은 없네, $n. 코르크론이 내 여관을 임시 병영으로 쓰고 있거든.', `FemaleText_loc4`='我这里没有房间了，$n。我的旅馆已经被库卡隆征用，成为临时兵营了。', `FemaleText_loc5`='這裡已經客滿了，$n。柯爾克隆徵收我的旅店，把它當成臨時的兵營了。', `FemaleText_loc7`='No tengo sitio para ti aquí, $n. Los Kor''kron se han hecho con mi taberna y la han convertido en su cuartel temporal.' WHERE `ID`=73264;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<초조하게 그의 어깨 너머를 살피는 손차> 야수를 얻고 싶으면 다른 곳으로 가십시오, $c님. 여긴 코르크론이 지켜보고 있습니다.', `MaleText_loc4`='<克苏卡紧张地看了看身后。>如果你想要你的宠物，最好去别处取，$c。库卡隆盯着呢。', `MaleText_loc5`='<克蘇卡緊張地環顧四周。>要是你想領取寵物的話，請到別處去吧，$c，柯爾克隆正盯著我們。', `MaleText_loc7`='<Xon''cha te mira por encima del hombro con aire nervioso.> Tendrás que irte a otra pah''te si quieres llegar hah''ta tus mascotas, $c. Los Kor''kron observan.' WHERE `ID`=73265;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 경매 안 합니다, $r님. 돌아가는 모양새를 보니 한동안 없을 겁니다.', `FemaleText_loc4`='今天不举行拍卖，$r。以目前的局势看，拍卖恐怕要暂停一阵了。', `FemaleText_loc5`='今天停止拍賣，$r。照情況看來，拍賣行要歇業好一陣子了。', `FemaleText_loc7`='Hoy no hay subastas, $r. Y tampoco las habrá durante un tiempo, por lo que parece.' WHERE `ID`=73266;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다른 곳에서 사 주시겠어요, $r님? 의심을 사고 싶진 않아요.', `FemaleText_loc4`='你最好去别处做生意吧，$r。我可不想惹麻烦。', `FemaleText_loc5`='你最好去問問別的商人，$r。我可不想被盯上。', `FemaleText_loc7`='Será mejor que hagas tus negocios en otro lado, $r. No quiero parecer soh''pechosa.' WHERE `ID`=73267;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 안 팔아요. 너무 위험하거든요.', `FemaleText_loc4`='今天不卖东西。太危险了。', `FemaleText_loc5`='今天不賣東西，太危險了。', `FemaleText_loc7`='Hoy no hay venta. Es demasiado peligroso.' WHERE `ID`=73268;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 뱀! 저들이 내 뱀들을 가져갔습니다!', `MaleText_loc4`='我的蛇，伙计。他们抢走了我的蛇！', `MaleText_loc5`='我的蛇，老兄，他們搶走了我的蛇!', `MaleText_loc7`='Mis seh''pientes, colega. ¡Se llevaron mis seh''pientes!' WHERE `ID`=73269;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='오늘은 안 팝니다!', `FemaleText_loc4`='我今天不卖东西。', `FemaleText_loc5`='今天我沒東西可賣。', `FemaleText_loc7`='No tengo nada que venderte hoy.' WHERE `ID`=73270;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<어깨 너머로 경계하듯 바라보는 후주> 지금은 안 됩니다. 최근 이곳 분위기가 심상치 않거든요.', `MaleText_loc4`='<胡祖警惕地看了看身后。>现在不行。最近这里的局势非常紧张。', `MaleText_loc5`='<胡鳩謹慎地環顧四周。>現在還不行，這陣子他們管得很嚴。', `MaleText_loc7`='<Huju te mira por encima del hombro con aire fatigado.> Ahora no. Las cosas eh''tán que arden últimamente por aquí.' WHERE `ID`=73271;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 거리를 두시는 게 좋을 겁니다. $c님. 여기에 꽤 엄격한 코르크론의 제재가 가해졌거든요. 앞으로 무슨 일이 일어날지 아무도 모르는 상황입니다.', `MaleText_loc4`='你最好保持距离，$c。最近库卡隆的戒严非常严格。谁都不知道究竟发生了什么事。', `MaleText_loc5`='你最好離我遠一點，$c。柯爾克隆對這一帶下了戒嚴令，誰都不知道違反規定會發生什麼事。', `MaleText_loc7`='Será mejor que no te acerques demasiado, $c. Estamos bajo un estricto bloqueo Kor''kron por aquí. Es imposible saber lo que pasará.' WHERE `ID`=73272;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='미안해요, $c님. 오늘은 안 팔아요.', `FemaleText_loc4`='抱歉，$c。我这里没有你要的东西。', `FemaleText_loc5`='抱歉，$c，我沒東西賣了。', `FemaleText_loc7`='Lo siento, $c. No tengo nada pa'' ti.' WHERE `ID`=73273;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더러운 괴물 같으니! 살려주셔서 감사합니다.', `MaleText_loc4`='肮脏的怪物！我欠你一条命。', `MaleText_loc5`='臭怪物!我欠你一條命。', `MaleText_loc7`='¡Monstruos sucios! Te debo mi vida.' WHERE `ID`=73274;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그거 말입니다. 폭풍이요. 어떻게 만들어낸 건지 알아냈어요. 저 교활한 잔달라 놈이 얼음 트롤들을 시켜서 원소 정령한테 제물을 바치고 있습니다.', `MaleText_loc4`='听着：我们发现了风暴的源头。卑鄙的赞达拉巨魔让冰巨魔用鲜血祭祀元素。', `MaleText_loc5`='聽好了，我們發現是什麼造成這場風暴的。那個陰險的贊達拉讓這些寒冰食人妖獻祭鮮血給元素之靈。', `MaleText_loc7`='Escucha: la tormenta. Descubrimos lo que la está causando. Ese Zandalari tramposo está haciendo que esos trols de hielo hagan sacrificios de sangre para los espíritus elementales.' WHERE `ID`=73275;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 북쪽, 다리 건너에 동굴이 있어요. 그 안의 정령을 처치하면, 이 폭풍이 멎을 겁니다.', `MaleText_loc4`='在北边，桥的另一头有个山洞。如果能杀死里面的元素，风暴就会停止。', `MaleText_loc5`='這裡的北邊有個洞穴，就在橋的另一頭。如果你可以殺死裡面的元素，風暴應該會停止。', `MaleText_loc7`='Hay una cueva, al norte de aquí, del otro lado de un puente. Si pudieras matar al elemental que está allí dentro, la tormenta parará.' WHERE `ID`=73276;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약간의 참을성 대기열에 등록합니다.', `MaleText_loc4`='排队等待王者的耐心场景战役。', `MaleText_loc5`='加入耐心試煉佇列。', `MaleText_loc7`='Haz cola para Templanza.', `FemaleText_loc1`='약간의 참을성 대기열에 등록합니다.', `FemaleText_loc4`='排队等待王者的耐心场景战役。', `FemaleText_loc5`='加入耐心試煉佇列。', `FemaleText_loc7`='Haz cola para Templanza.' WHERE `ID`=73277;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공해 상에서의 전투 대기열에 등록합니다.', `MaleText_loc4`='排队等待公海激战场景战役。', `MaleText_loc5`='加入怒海之戰佇列。', `MaleText_loc7`='Haz cola para Batalla en Alta Mar.', `FemaleText_loc1`='공해 상에서의 전투 대기열에 등록합니다.', `FemaleText_loc4`='排队等待公海激战场景战役。', `FemaleText_loc5`='加入怒海之戰佇列。', `FemaleText_loc7`='Haz cola para Batalla en Alta Mar.' WHERE `ID`=73278;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피로 얼룩진 설원 대기열에 등록합니다.', `MaleText_loc4`='排队等待雪山血战场景战役。', `MaleText_loc5`='加入血染滄雪佇列。', `MaleText_loc7`='Haz cola para Sangre en la Nieve.', `FemaleText_loc1`='피로 얼룩진 설원 대기열에 등록합니다.', `FemaleText_loc4`='排队等待雪山血战场景战役。', `FemaleText_loc5`='加入血染滄雪佇列。', `FemaleText_loc7`='Haz cola para Sangre en la Nieve.' WHERE `ID`=73279;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='성난불길의 비밀 대기열에 등록합니다.', `MaleText_loc4`='排队等待怒焰之谜场景战役。', `MaleText_loc5`='加入怒焰之秘佇列。', `MaleText_loc7`='Haz cola para Los Secretos de Sima Ígnea.', `FemaleText_loc1`='성난불길의 비밀 대기열에 등록합니다.', `FemaleText_loc4`='排队等待怒焰之谜场景战役。', `FemaleText_loc5`='加入怒焰之秘佇列。', `FemaleText_loc7`='Haz cola para Los Secretos de Sima Ígnea.' WHERE `ID`=73280;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 검은 심장 대기열에 등록합니다.', `MaleText_loc4`='排队等待潘达利亚的黑暗之心场景战役。', `MaleText_loc5`='加入潘達利亞的黑暗之心佇列。', `MaleText_loc7`='Haz cola para el Corazón Oscuro de Pandaria.', `FemaleText_loc1`='판다리아의 검은 심장 대기열에 등록합니다.', `FemaleText_loc4`='排队等待潘达利亚的黑暗之心场景战役。', `FemaleText_loc5`='加入潘達利亞的黑暗之心佇列。', `FemaleText_loc7`='Haz cola para el Corazón Oscuro de Pandaria.' WHERE `ID`=73281;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차원문들이 차단되었습니다. 듣기론 오크들이 저주받은 땅으로 가는 차원문은 열어두었다던데... 차원문은 아래 어둠의 틈에 있습니다.', `FemaleText_loc4`='传送门都关闭了。我听说兽人在暗影裂口下还保留了一座通往诅咒之地的传送门。', `FemaleText_loc5`='傳送門全都關閉了。我聽說獸人還開著一座通往詛咒之地的傳送門，就在暗影裂口那。', `FemaleText_loc7`='Los portales están cerrados. He oído que los orcos aún tienen un portal abierto a Las Tierras Devastadas, en el Circo de las Sombras.' WHERE `ID`=73283;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님이 살아 계시다!', `MaleText_loc4`='沃金还活着！', `MaleText_loc5`='沃金沒有死!', `MaleText_loc7`='¡VOL''JIN VIVE!' WHERE `ID`=73284;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님이 살아 계시다! 형제들이여!', `MaleText_loc4`='沃金还活着，兄弟！', `MaleText_loc5`='沃金還活著，兄弟們!', `MaleText_loc7`='¡Vol''jin vive, hermanos míos!' WHERE `ID`=73285;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='억압에 맞서 싸우자!', `MaleText_loc4`='反对压迫！', `MaleText_loc5`='推翻暴政!', `MaleText_loc7`='¡Enfrentaos a la opresión!' WHERE `ID`=73286;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 헬스크림에 맞서 일어나라! 오늘, 호드의 새로운 새벽이 밝으리라!', `MaleText_loc4`='站出来反抗加尔鲁什·地狱咆哮！部落将在今天迎来新生的曙光！', `MaleText_loc5`='起身對抗卡爾洛斯·地獄吼!今天是部落迎向嶄新黎明的一天!', `MaleText_loc7`='¡Levantaos contra Garrosh Grito Infernal! ¡Hoy es el nuevo amanecer de la Horda!' WHERE `ID`=73287;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야아!', `MaleText_loc4`='嗷！', `MaleText_loc5`='啊!', `MaleText_loc7`='¡Argh!' WHERE `ID`=73288;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; |cFFFF0000|Hspell:141407|h[꽁꽁 얼어붙었습니다]|h|r. 구출하십시오!', `MaleText_loc4`='$n被|cFFFF0000|Hspell:141407|h[冰霜凝结]|h|r了。快释放$g他:她;！', `MaleText_loc5`='$n被|cFFFF0000|Hspell:141407|h[牢牢凍住]|h|r了。破除$g他:她;的冰凍狀態!', `MaleText_loc7`='$n ha sido |cFFFF0000|Hspell:141407|h[$gCongelado:Congelada;]|h|r. ¡$gLibéralo:Libérala;!' WHERE `ID`=73289;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주술의 힘을 보여주지.', `MaleText_loc4`='妖术真带劲。', `MaleText_loc5`='看我的妖術。', `MaleText_loc7`='Embrújalos bien.' WHERE `ID`=73290;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 봄베이가 의술사가 되는 데 도움이 될 거야.', `MaleText_loc4`='这有助于提高波贝的巫医水平。', `MaleText_loc5`='這對波貝的巫醫訓練很有幫助。', `MaleText_loc7`='Eh''to le vendrá muy bien a Bom''bay a hacer su medicina bruja.' WHERE `ID`=73291;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봄베이가 지원자를 구했네!', `MaleText_loc4`='波贝找到了一个志愿者！', `MaleText_loc5`='波貝找到自願者了!', `MaleText_loc7`='¡Bom''bay ha encontrado un voluntario!' WHERE `ID`=73292;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거면 되겠군.', `MaleText_loc4`='这会治好他们的。', `MaleText_loc5`='這下可以搞定他們。', `MaleText_loc7`='Eso los enseñará.' WHERE `ID`=73293;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤! 내 마을에서 뭘 하고 있나?', `MaleText_loc4`='巨魔！你还在我的镇上做什么？', `MaleText_loc5`='食人妖!你還在我的村裡做什麼?', `MaleText_loc7`='¡Trol! ¿Qué haces todavía en mi ciudad?' WHERE `ID`=73294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마법사들을 훈련시키고 있네.', `MaleText_loc4`='训练法师啊。', `MaleText_loc5`='訓練法師。', `MaleText_loc7`='Inh''truir a los magos.' WHERE `ID`=73295;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님의 호드에는 부두 잔재주나 부리는 네놈들 따위 필요없다, 트롤. 이제 내 눈 앞에서 꺼져라!', `MaleText_loc4`='地狱咆哮的部落不需要你那些巫毒把戏，巨魔。现在，滚出我的视线！', `MaleText_loc5`='地獄吼的部落不需要你的巫毒技倆，食人妖。快滾出我的視線外!', `MaleText_loc7`='La Horda de Grito Infernal no necesita sus trucos de vudú, trol. ¡Sal de mi vista!' WHERE `ID`=73296;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위론의 시험을 받아들이려면 징을 울리십시오. 네 천신의 시험 중 하나를 통과해야 합니다.', `MaleText_loc4`='敲响挑战之锣以接受玉珑的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。', `MaleText_loc5`='敲響銅鑼來接受玉龍的挑戰。你只需要克服聖獸天尊四個挑戰中的其中一個。', `MaleText_loc7`='Haz sonar el gong para aceptar el desafío de Yu''lon. Solo tendrás que superar uno de los cuatro desafíos de los Celestiales.' WHERE `ID`=73297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징 울리기 [원거리 공격자용 시험]', `MaleText_loc4`='敲响挑战之锣[远程输出挑战]', `MaleText_loc5`='敲響銅鑼[遠程傷害挑戰]', `MaleText_loc7`='Haz sonar el gong [desafío de DPS a distancia]', `FemaleText_loc1`='징 울리기 [원거리 공격자용 시험]', `FemaleText_loc4`='敲响挑战之锣[远程输出挑战]', `FemaleText_loc5`='敲響銅鑼[遠程傷害挑戰]', `FemaleText_loc7`='Haz sonar el gong [desafío de DPS a distancia]' WHERE `ID`=73298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 드디어 도착했군. 으으으... 늙은 뼈마디가 어찌나 쑤시는지. 자넨 모를 거야.', `MaleText_loc4`='啊，到了。唉，我这把老骨头可累惨了，绝对超出你的想象。', `MaleText_loc5`='啊，我們到了。噢，我的老骨頭累了。你無法想像的累。', `MaleText_loc7`='Ah, aquí estamos. Au... Au, estos huesos viejos están cansados. Más de lo que te imaginas. ' WHERE `ID`=73299;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 놀랐네. 자네 같은 영웅은, 늙은이가 산을 오르는 걸 도와주는 이런 하찮은 일은 싫어할 줄 알았는데. 영웅은 보통 교만하지.', `MaleText_loc4`='你令我吃惊。我以为你这样的英雄会对扶老人上山的任务不屑一顾。他们就是太骄傲。', `MaleText_loc5`='你讓我感到驚訝。我以為像你這樣的英雄會不願意把一個老人帶上山。英雄大多都太過驕傲了。', `MaleText_loc7`='Me sorprendiste. Esperaba que alguien como tú se rehusaría a cargar con un viejo montaña arriba. Algunos son demasiado orgullosos.' WHERE `ID`=73300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네에게 가르침을 줄 작정이었는데, 오히려 내가 자네에게 가르침을 받았군. 아는가? 내가 젊었을 때... 내가 젊었을 때... 내가 젊었을 때...', `MaleText_loc4`='我本想给你上一课，结果却是你给我上了一课。你知道，在我年轻那会儿……在我年轻那会儿……在我年轻那会儿……', `MaleText_loc5`='我原本想教你一些事情，但反過來，是你在教我。因為當我年輕時...當我年輕時...當我年輕時...', `MaleText_loc7`='Yo iba a enseñarte una lección pero, en cambio, tú me la enseñaste a mí. Verás, de joven... De joven…' WHERE `ID`=73301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 황제였지.', `MaleText_loc4`='我曾经是……皇帝。', `MaleText_loc5`='我是皇帝。', `MaleText_loc7`='Fui... EMPERADOR.' WHERE `ID`=73302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네 눈에 보이는 이 모든 땅은 나의 다스림을 받았네.', `MaleText_loc4`='你目光所及之处皆为我的领土。', `MaleText_loc5`='你所能見到的一切都歸我統御。', `MaleText_loc7`='El reino que ves a tu alrededor estaba a mis órdenes.' WHERE `ID`=73303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 나의 의심을, 공포를, 분노를 정복했지... 그리고 이 땅에 묻어 버렸어.', `MaleText_loc4`='我征服了自己的疑虑、恐惧和愤怒……将它们埋入地底。', `MaleText_loc5`='我戰勝了自己的懷疑，我的恐懼，我的憤怒...我把它們全埋在土裡面了。', `MaleText_loc7`='Conquisté mis dudas, mis miedos, mi ira... Enterré todo eso en esta tierra.' WHERE `ID`=73304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 하나의 악덕은 버리지 못했지. 내가 정복하지 못한 샤는... 교만일세.', `MaleText_loc4`='但我仍有一个缺点，而且从未能征服它。那就是骄傲。', `MaleText_loc5`='但是我保留了一宗罪。我從沒戰勝的煞，就是驕傲。', `MaleText_loc7`='Pero conservé un vicio. El único sha que nunca conquisté. El ORGULLO.' WHERE `ID`=73305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 교만이 이 땅을 안개로 가렸지! 난 우리가 세상 누구보다 우월하다고 생각했어.', `MaleText_loc4`='骄傲令这片土地陷入迷雾！我们自以为比外面的世界更优越。', `MaleText_loc5`='我的驕傲使迷霧籠罩了這片土地。我以為我們比世界的其他種族都好。', `MaleText_loc7`='¡Mi orgullo cubrió esta tierra de tinieblas! Pensé que éramos mejor que el resto del mundo.' WHERE `ID`=73306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 문제는 스스로 해결할 수 있다고 믿었지. 하지만 만 년 동안, 우리는 그냥 고여서 썩어 갔네. 땅에 묻힌 의심과 공포는 우리가 허락할 때마다 고개를 쳐들었지.', `MaleText_loc4`='我觉得我们能解决自己的问题。但一万年过去了，我们停滞不前，地下的疑虑和恐惧一有机会，就会出来作祟。', `MaleText_loc5`='我以為我們能解決自己的問題。但是一萬年來，我們失去了活力，讓懷疑和恐懼埋在土中，而它們卻在暗中化膿流血。', `MaleText_loc7`='Pensé que podríamos resolver nuestros propios problemas. Pero en diez mil años nos estancamos; nuestras dudas, enterradas en la tierra, eructaban y supuraban siempre que lo permitíamos.' WHERE `ID`=73307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교만. 그건 가장 음험한 샤라네. 긍지일 때는 미덕이지만, 교만이 되면 다른 모든 악덕이 합쳐진 것보다 더 위험하지.', `MaleText_loc4`='骄傲，它是最阴险的。所谓成也骄傲，败也骄傲，它比其他所有煞魔加起来还要危险。', `MaleText_loc5`='驕傲。這是煞當中最陰險的。它看來是好的，但遲早會變味。而它比其他加起來都還要危險。', `MaleText_loc7`='El orgullo. Es el sha más traicionero. Es bueno hasta que es malo. Y entonces es más peligroso que todos los otros combinados.' WHERE `ID`=73308;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='교만을 경계하게! 겸손해지게! 세상이 혼돈 속에 빠져들고 있어. 오랜 적이 뭉쳐야 하네. 긍지 높은 종족들도 도움이 필요하다는 걸 인정해야 해.', `MaleText_loc4`='警惕骄傲，保持谦卑！世界日渐混乱，宿敌当前必须同心协力。骄傲的种族要承认自己需要帮助。', `MaleText_loc5`='當心驕傲!要謙遜!整個世界正陷入混亂。宿敵必須聯手。驕傲的種族也必須承認他們需要幫助。', `MaleText_loc7`='¡Cuídate del orgullo! ¡Sé humilde! El mundo se sumerge en el caos. Los viejos enemigos deben trabajar juntos. Las razas orgullosas deben admitir que necesitan ayuda.' WHERE `ID`=73309;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='상황이 점점 나빠질 걸세. 시련이 다가오고 있어. 힘을 합쳐야만, 어둠을 극복할 수 있을 것이야.', `MaleText_loc4`='黎明前的天空总是格外黑暗。只有精诚团结，我们才能战胜这黑暗。', `MaleText_loc5`='萬物必先亂而後治。只有合作，我們才能擊敗黑暗。', `MaleText_loc7`='Las cosas se van a poner peor antes de mejorar. Solo si trabajamos juntos podremos superar la oscuridad.' WHERE `ID`=73310;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 가로막는 건 단 하나... 교만일세.', `MaleText_loc4`='而最大的阻碍……就是骄傲。', `MaleText_loc5`='而唯一擋在路上的...正是驕傲。', `MaleText_loc7`='Lo único que se interpone en nuestro camino... es el orgullo.' WHERE `ID`=73311;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목재는 다 챙겼나? 좋다. 오그리마로 보내라.', `MaleText_loc4`='全是木材？很好。把它们送去奥格瑞玛。', `MaleText_loc5`='裝滿木材了嗎?很好，運去奧格瑪吧。', `MaleText_loc7`='¿Hasta arriba de madera? Perfecto. Envíala a Orgrimmar.' WHERE `ID`=73312;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마의 벽은 더욱 높이, 더욱 견고하게 세워져야 한다!', `MaleText_loc4`='奥格瑞玛的城墙还不够高，不够厚！', `MaleText_loc5`='奧格瑪的城牆要蓋得更高、更厚實!', `MaleText_loc7`='¡Las murallas de Orgrimmar tienen que ser más altas! ¡Más gruesas!' WHERE `ID`=73313;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 헬스크림 님의 호드에 맞서지 못하리라!', `MaleText_loc4`='谁也不能质疑地狱咆哮领导下的部落的实力！', `MaleText_loc5`='沒有人敢質疑地獄吼部落的力量!', `MaleText_loc7`='¡Nadie pondrá en duda el poder de la Horda de Grito Infernal!' WHERE `ID`=73314;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 뭐지? 기름?', `MaleText_loc4`='看看我们找到了什么？原油？', `MaleText_loc5`='這是什麼?燃油嗎?', `MaleText_loc7`='¿Qué tenemos aquí? ¿Aceite?' WHERE `ID`=73315;
