UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신선한 고기! 방금 도살장에서 나온 것이군. 좋아.', `MaleText_loc4`='新鲜的肉！直接从屠宰场运出来的。很好。', `MaleText_loc5`='新鮮的肉!從屠宰場直接送來的，很好。', `MaleText_loc7`='¡Carne fresca! Directamente desde el matadero. Perfecto.' WHERE `ID`=73317;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='남쪽에 있는 시험의 골짜기로 보내라. 젊은 오크들이 굶주려 있으니.', `MaleText_loc4`='把它们送去南边的试炼谷。我们的小兽人正嗷嗷待哺呢。', `MaleText_loc5`='送到南邊的試煉谷去，那裡的年輕獸人都快餓壞了。', `MaleText_loc7`='Dirígete al sur, al Valle de los Retos. Allí hay orcos jóvenes hambrientos que alimentar.' WHERE `ID`=73318;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아, 석재로군. 오그리마로 보내!', `MaleText_loc4`='好极了，一车石料。快送到奥格瑞玛去！', `MaleText_loc5`='很好，是石材。快送去奧格瑪!', `MaleText_loc7`='Excelente, un cargamento de piedra. ¡Envíalo a Orgrimmar!' WHERE `ID`=73319;
