UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게서 숨을 수는 없다!', `MaleText_loc4`='你休想躲过我的眼睛！', `MaleText_loc5`='休想從我面前逃掉!', `MaleText_loc7`='¡No puedes esconderte de mí!', `FemaleText_loc1`='내게서 숨을 수는 없다!', `FemaleText_loc4`='你休想躲过我的眼睛！', `FemaleText_loc5`='休想從我面前逃掉!', `FemaleText_loc7`='¡No puedes esconderte de mí!' WHERE `ID`=73348;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈을 내 늑대에게 먹이겠다.', `MaleText_loc4`='我要拿你去喂我的狼。', `MaleText_loc5`='我要把你抓去餵狼。', `MaleText_loc7`='Servirás de comida para mis lobos.', `FemaleText_loc1`='네놈을 내 늑대에게 먹이겠다.', `FemaleText_loc4`='我要拿你去喂我的狼。', `FemaleText_loc5`='我要把你抓去餵狼。', `FemaleText_loc7`='Servirás de comida para mis lobos.' WHERE `ID`=73349;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님을 위하여!', `MaleText_loc4`='为了酋长！', `MaleText_loc5`='為了大酋長而戰!', `MaleText_loc7`='¡Por el Jefe de Guerra!', `FemaleText_loc1`='대족장님을 위하여!', `FemaleText_loc4`='为了酋长！', `FemaleText_loc5`='為了大酋長而戰!', `FemaleText_loc7`='¡Por el Jefe de Guerra!' WHERE `ID`=73350;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈이 보인다!', `MaleText_loc4`='我看见你了！', `MaleText_loc5`='我看到你了!', `MaleText_loc7`='¡Te estoy viendo!', `FemaleText_loc1`='네놈이 보인다!', `FemaleText_loc4`='我看见你了！', `FemaleText_loc5`='我看到你了!', `FemaleText_loc7`='¡Te estoy viendo!' WHERE `ID`=73351;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타우렌! 네 족속들이 도대체 무슨 짓을 한 건가? 이 신성한 골짜기에 심각한 상처를 냈지 않나!', `MaleText_loc4`='牛头人！你们的人都干了些什么？你们在我们神圣的山谷中挖出了一条丑陋的疤痕！', `MaleText_loc5`='牛頭人!看看你們做了什麼好事?居然在我們神聖的山谷開了一道創口!', `MaleText_loc7`='¡Tauren! ¿Qué han hecho? ¡Han abierto una herida en nuestro valle sagrado!' WHERE `ID`=73352;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주 님, 부디 이해해 주십시오. 이 명령을 내린 오크의 "대족장"은 이제 호드 전체를 대변하지 못합니다. 그자에게 반대하는 목소리가 점점 커지고 있습니다.', `MaleText_loc4`='祝掌门，请你理解——下达这个命令的兽人“酋长”已经不能再代表整个部落。许多人已经起来反对他了。', `MaleText_loc5`='祝宗主，請您諒解。下令這麼做的那位獸人「大酋長」並不能代表整個部落，反對他的聲浪已經越來越高。', `MaleText_loc7`='Lord Zhu, compréndelo, por favor. El "Jefe de Guerra" orco que ordenó tal acción ya no habla en nombre de toda la Horda. Hay muchas voces que se elevan ya contra él.' WHERE `ID`=73353;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그쪽의 정치적인 문제는 내가 상관할 일이 아닐세. 자네가 속한 호드는 이 곳의 존엄함을 무시했네. 이젠 더는 여기서 환대해줄 수 없으니 썩 떠나버리게!', `MaleText_loc4`='我不关心你们的内政。你们部落亵渎了这片圣地。这里不再欢迎你们了——给我立刻离开这里！', `MaleText_loc5`='我不想管你們的家務事。你們部落褻瀆了這塊神聖之地。我們不歡迎你們。快走!', `MaleText_loc7`='Sus asuntos políticos no son cosa mía. La Horda ha faltado al respeto a la santidad de este lugar. Ya no son bienvenidos aquí. ¡Márchense de inmediato!' WHERE `ID`=73354;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간을 조금 주십시오, 타란 주 님. 우리가 가로쉬에게 정의의 심판을 내릴 기회를 주십시오.', `MaleText_loc4`='请给我们一点时间，祝掌门。请给我们一个将地狱咆哮绳之以法的机会。', `MaleText_loc5`='再給我們一點時間，祝宗主。請給我們機會讓地獄吼接受制裁。', `MaleText_loc7`='Danos tiempo, lord Zhu. Danos tiempo para hacer justicia con Grito Infernal.' WHERE `ID`=73355;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='태양길잡이여, 나는 자네의 동료를 존중하네. 샤와 천둥왕 공격 작전에서 우리를 도와줬으니 말일세. 그렇지 않았다면 내가 벌써 음영파에게 이 제단 전체에서 몰아내 버리라고 명령했을 걸세. 하지만 내 인내심도 이제 여기까지라네. 호드는 떠나야만 해.', `MaleText_loc4`='烈日行者，我很尊重你们的人民。你们在我们与煞魔和雷电之王的战役中出力甚多。否则，我已经直接命令影踪派肃清整座双月殿了。但我的耐心是有限的。部落必须离开这里。', `MaleText_loc5`='日行者，我尊重你的人民。要不是你們在我族對抗煞與雷王的戰役中提供幫助，我早就命令影潘將你們趕出雙月廟。然而我的耐心已經到了極限。部落必須離開。', `MaleText_loc7`='Caminasol, yo respeto a tu pueblo. Nos han ayudado en la campaña contra el sha y contra el Rey del Trueno. De otro modo, habría ordenado ya al Shadopan que limpiase este santuario. Pero se me agota la paciencia. La Horda debe irse.' WHERE `ID`=73356;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발 부탁드리겠습니다. 우리가 바로잡을 시간을 주십시오.', `MaleText_loc4`='拜托，请给我们一点时间来纠正错误。', `MaleText_loc5`='拜託，請再給我們一點時間來完成這件事。', `MaleText_loc7`='Por favor. Danos tiempo para solucionarlo.' WHERE `ID`=73357;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주가 단호한 눈빛으로 먼 곳을 응시합니다.', `MaleText_loc4`='祝踏岚冷酷地看向远处。', `MaleText_loc5`='塔蘭·祝表情嚴肅地凝視遠方。', `MaleText_loc7`='La mirada de Taran Zhu se pierde en lontananza con aire sombrío.' WHERE `ID`=73358;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네. 이 계절이 끝날 때까지만일세. 그 이상은 안 돼.', `MaleText_loc4`='很好。你们的时间就到这一季结束前为止。不能再久了。', `MaleText_loc5`='好吧。你們可以待到這個季節結束。之後一刻也不可再留。', `MaleText_loc7`='De acuerdo. Tienes hasta el final de la estación. Nada más.' WHERE `ID`=73359;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 판다렌도 폭군을 겪어보지 않은 건 아니라네. 다가오는 전투는 자네의 영혼을 시험하게 될 걸세. 그대의 앞길에 천신의 수호가 깃들기를 바라지.', `MaleText_loc4`='我们熊猫人对于推翻暴君并不陌生。即将到来的战争将考验你们的灵魂。愿至尊天神指引你们的道路。', `MaleText_loc5`='對付暴君對我們熊貓人來說一點都不陌生。即將到來的戰鬥會考驗你的靈魂。願天尊指引你的行動。', `MaleText_loc7`='Los pandaren sabemos lo que es enfrentarnos a tiranos. La batalla que se avecina pondrá a prueba sus almas. Que los Celestiales los guíen.' WHERE `ID`=73360;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서 이 해안을 확보하라고 명하셨다! 얼라이언스가 움직이기 시작할 때, 이곳의 파도는 놈들의 피로 붉게 물들 것이다!', `MaleText_loc4`='酋长下令严守这片海滩！一旦联盟采取行动，他们的鲜血将染红海水！', `MaleText_loc5`='大酋長下令死守這片海岸!當聯盟有所行動時，他們的鮮血將染紅潮水!', `MaleText_loc7`='El Jefe de Guerra ha ordenado que aseguremos esta costa. ¡Cuando la Alianza mueva ficha, las olas se teñirán de rojo con su sangre!' WHERE `ID`=73361;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='들으셨습니까? 트롤 반란군이 칼바위 언덕을 공격했다고 합니다.', `MaleText_loc4`='你听说了吗？叛乱的巨魔对剃刀岭发动了攻击。', `MaleText_loc5`='你聽說了嗎?叛變的食人妖朝剃刀嶺發動攻擊。', `MaleText_loc7`='¿Te has enterado? Los trols traidores han lanzado un ataque contra Cerrotajo.' WHERE `ID`=73362;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리코가 이 해안을 꽉 잡았어!', `MaleText_loc4`='里克保证守住这片海滩！', `MaleText_loc5`='瑞可要封鎖這片海灘!', `MaleText_loc7`='¡Riko tiene eh''ta playa bloqueada!' WHERE `ID`=73363;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 믿을 수는 없지만, 호드를 되찾으려면 그들의 도움이 필요합니다.', `MaleText_loc4`='我们或许不该相信联盟，但要想夺回部落，我们就需要他们的帮助。', `MaleText_loc5`='雖然聯盟這群傢伙不能信任，但是如果我們想擊退部落，就得靠他們幫忙才行。', `MaleText_loc7`='Puede que la Alianza no sea de fiar, pero necesitamos su ayuda si queremos recuperar el control de la Horda.' WHERE `ID`=73365;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠... 좋네. 자네는 내 신뢰를 얻었네. 얼라이언스가 옳은 일을 하리라 믿겠네.', `MaleText_loc4`='很好。你值得信赖，相信联盟也会做出正确的选择。', `MaleText_loc5`='很好。你贏得我的信任了。我相信聯盟會做出正確的事情。', `MaleText_loc7`='Muy bien. Te ganaste mi confianza. Pondré mi fe en que la Alianza hará lo correcto.' WHERE `ID`=73366;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 동료들과 육지에서 오그리마를 공격할 걸세. 자네들은 바다로 오게. 그게 유일한 길이니.', `MaleText_loc4`='暗矛部族会和盟友从地面进攻奥格瑞玛，以便你们从海上进攻。只有这个办法。', `MaleText_loc5`='暗矛食人妖和盟友會從陸地攻擊奧格瑪，讓你們從海上進攻。這是唯一的辦法。', `MaleText_loc7`='Los Lanza Negra y sus aliados atacarán Orgrimmar por tierra para que tú puedas atacarla por mar. Es la única forma. ' WHERE `ID`=73367;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 살아남는다면, 내 언젠가 자네를... 친구라 부를지도 모르겠군.', `MaleText_loc4`='如果我们能活下来，那么有一天，我或许能称你为……“朋友”。', `MaleText_loc5`='如果我們能活下來，也許有天我會稱呼你為...朋友。', `MaleText_loc7`='Si sobrevivimos a esto, tal vez algún día pueda reconocer nuestra... amistad.' WHERE `ID`=73368;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 셋을 보게. 이렇게 듀로타의 모래를 다시 밟다니! 옛날 생각 나는군.', `MaleText_loc4`='看看我们三个。又回到了杜隆塔尔的沙滩！就像从前一样。', `MaleText_loc5`='看看我們三個。回到杜洛塔的沙丘上。就像以前一樣。', `MaleText_loc7`='Mírennos a nosotros tres. ¡De vuelta en las arenas del viejo Durotar! Como en los viejos tiempos.' WHERE `ID`=73369;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 옛날과는 다르네. 시대가 변했어. 친구와 적의 구분이 전처럼 뚜렷하지 않군.', `MaleText_loc4`='不一样了，老朋友。时代不同了。敌友间的界限已不再清晰。', `MaleText_loc5`='不完全是，老朋友。時代變了。朋友與敵人之間的界線已不再明顯。', `MaleText_loc7`='No tanto. Los tiempos cambiaron. La línea que divide a amigos y enemigos ya no es tan clara.' WHERE `ID`=73370;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 온다! 헬스크림은 부하들이 여길 짓밟을 거라 생각하겠지.', `MaleText_loc4`='他们来了！地狱咆哮以为他的人能横扫一切。', `MaleText_loc5`='他們來了!地獄吼以為他的人可以把我們輾過去。', `MaleText_loc7`='¡Ahí vienen! Grito Infernal piensa que su propia gente se dejará pisotear.' WHERE `ID`=73371;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장 나으리에게 검은창 부족의 분노를 보여줄 시간이다!', `MaleText_loc4`='就让酋长看看暗矛部族的怒火吧！', `MaleText_loc5`='是時候讓大酋長見識暗矛的憤怒了!', `MaleText_loc7`='¡Hora de mostrarle a este Jefe de Guerra la furia de los Lanza Negra!' WHERE `ID`=73372;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰! 놈들이 달아나게 둬라. 헬스크림은 놈들이 돌아오면 비겁자라고 처형할 게야. 센진 마을은 안전하네!', `MaleText_loc4`='住手！别追了。如果他们敢回去，地狱咆哮会把他们当作懦夫处死的。森金村安全了！', `MaleText_loc5`='別追!讓他們逃走。如果他們回去，地獄吼會以逃兵之名處決他們。森金村安全了!', `MaleText_loc7`='¡Alto! Déjenlos escapar. Grito Infernal los ejecutará por cobardes si regresan. ¡El Poblado Sen''jin está a salvo!' WHERE `ID`=73373;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='재집결! 이 기세로 전진한다. 대족장이 칼바위 언덕의 방어를 강화하기 전에, 우리 혁명군이 그곳을 점령하고, 불모의 땅으로 통하는 길을 봉쇄한다.', `MaleText_loc4`='集合！我们得先发制人，抢在酋长增兵剃刀岭之前先占领它，并阻断通往贫瘠之地的交通！', `MaleText_loc5`='重新集結!我們繼續壓制。在大酋長在剃刀嶺設防之前，我們為這場革命攻下那裡，切斷貧瘠之地的路線。', `MaleText_loc7`='¡Reagrúpense! Forcemos la ventaja. Antes de que el Jefe de Guerra fortifique Cerrotajo, nos apoderaremos de él por la revolución y cerraremos los caminos a los Baldíos.' WHERE `ID`=73374;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 싸울 수 있는 자는 모두 나를 따르라!', `MaleText_loc4`='还能继续战斗的人，跟我来！', `MaleText_loc5`='任何還能戰鬥的人，跟我來!', `MaleText_loc7`='¡Los que todavía puedan pelear, síganme!' WHERE `ID`=73375;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 볼진. 호드가 호드의 피를 쏟고 있네. 가슴이 찢어질 것 같군.', `MaleText_loc4`='等等，沃金。部落正在自相残杀。这简直让我崩溃。', `MaleText_loc5`='等等，沃金。部落在自相殘殺。我心痛如絞。', `MaleText_loc7`='Espera, Vol''jin. La Horda está derramando sangre de la Horda. Me parte el alma.' WHERE `ID`=73376;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 자네가 필요해.', `MaleText_loc4`='我们需要你，伙计。', `MaleText_loc5`='我們需要你，老兄。', `MaleText_loc7`='Te necesitamos, hombre.' WHERE `ID`=73377;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아네. 자네가 공격을 이끌어 주게. 난 할 일이 따로 있네.', `MaleText_loc4`='我知道。你负责指挥进攻。我有其他的事要做。', `MaleText_loc5`='我知道。我相信你能領導進攻。別的地方需要我。', `MaleText_loc7`='Lo sé. Confío en que tú liderarás el asedio. A mí me necesitan en otro lugar.' WHERE `ID`=73378;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 동족이 모두 가로쉬를 지지한다고 믿진 않네.', `MaleText_loc4`='我不信所有的兽人都支持加尔鲁什。', `MaleText_loc5`='我不相信我的弟兄們都支持卡爾洛斯。', `MaleText_loc7`='Me niego a creer que todos mis hermanos apoyan a Garrosh.' WHERE `ID`=73379;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네가 오그리마에 발을 들이는 순간, 헬스크림이 자네 목에 비수를 꽂을 거야!', `MaleText_loc4`='只要你一踏进奥格瑞玛，地狱咆哮就会割断你的脖子！', `MaleText_loc5`='你只要踏進奧格瑪，地獄吼就會把刀插進你的胸口!', `MaleText_loc7`='¡Si pones un pie en Orgrimmar, Grito Infernal te meterá un cuchillo en el cuello!' WHERE `ID`=73380;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오그리마로 가겠네. 나 혼자서. 아이트리그, 사울팽... 이런 이들은 가로쉬에게 반대하고 있을 거야. 다른 이들을 찾아보겠네.', `MaleText_loc4`='我要独自前往奥格瑞玛，伊崔格，萨鲁法尔肯定都反对加尔鲁什。我还得去找其他人。', `MaleText_loc5`='我要去奧格瑪。獨自去。伊崔格、薩魯法爾...他們一定也會反抗卡爾洛斯。我必須找其他人。', `MaleText_loc7`='Voy a ir a Orgrimmar. Solo. Eitrigg, Saurfang: seguro que se opondrán a Garrosh. Tengo que encontrar a otros.' WHERE `ID`=73381;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 말은 듣고 싶지 않네.', `MaleText_loc4`='不要说这种丧气话。', `MaleText_loc5`='我不想聽你說這種話。', `MaleText_loc7`='No digas esas cosas.' WHERE `ID`=73382;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래도 해야 하는 말이야, 볼진. 우리가 살아남지 못한다면... 알아 줬으면 하네. 자네는 언제나 내 친구, 내 형제였어.', `MaleText_loc4`='我一定要说。万一我们失败了——我希望你明白：你始终是我的朋友，我的兄弟。', `MaleText_loc5`='我不能不說。沃金，如果我們沒法活下來，我要你知道。你一直是我的好朋友。我的兄弟。', `MaleText_loc7`='Tienen que ser dichas. Vol’jin. Si no sobrevivimos a esto... quiero que sepas esto. Siempre fuiste mi amigo. Mi hermano.' WHERE `ID`=73383;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여.', `MaleText_loc4`='为了部落。', `MaleText_loc5`='為了部落。', `MaleText_loc7`='Por la Horda.' WHERE `ID`=73384;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드를 위하여.', `MaleText_loc4`='为了部落。', `MaleText_loc5`='為了部落。', `MaleText_loc7`='Por la Horda.' WHERE `ID`=73385;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창이여, 나를 따르라! 오그리마까지 휴식은 없다!', `MaleText_loc4`='暗矛巨魔，跟我来！日夜兼程赶往奥格瑞玛！', `MaleText_loc5`='暗矛部族，跟我來!我們行進!不眠不休攻進奧格瑪!', `MaleText_loc7`='¡Lanza Negra, conmigo! ¡Cabalguemos! ¡¡No dormiremos hasta llegar a Orgrimmar!!' WHERE `ID`=73386;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님도 검은창 부족을 건드리지 말았어야 했네. 그 때문에 지금 호드가 분열하고 있어.', `MaleText_loc4`='酋长真不该去惹暗矛部族。他害得部落四分五裂了。', `MaleText_loc5`='大酋長真不該去招惹暗矛氏族。部落的分裂都是他造成的。', `MaleText_loc7`='El Jefe de Guerra no debería haber enfadado a los Lanza Negra. Ha dividido a la Horda.' WHERE `ID`=73387;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 수 백 명의 젊은 전사들을 훈련시켰네. 하지만 대족장은 아무 거리낌 없이 그들에게 피를 흘릴 것을 명령했지. 나는 이제 그를 대족장으로 여기지 않겠네.', `MaleText_loc4`='我训练了数百名年轻战士。酋长却在让他们白白流血。他不再是“我的酋长”了。', `MaleText_loc5`='我辛辛苦苦調教出那些年輕的戰士們，大酋長卻隨手便將他們送上戰場。我再也不承認這位大酋長。', `MaleText_loc7`='He entrenado a cientos de jóvenes guerreros. El Jefe de Guerra derrama su sangre de forma temeraria. Ya no es MI Jefe de Guerra.' WHERE `ID`=73388;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 우리를 해치지 말게! 볼진의 저항군에게 주둔할 장소를 기꺼이 제공하겠네.', `MaleText_loc4`='拜托——别伤害我们！我们完全欢迎沃金把起义军驻扎在这里。', `MaleText_loc5`='拜託，別傷害我們!歡迎沃金的各位義士駐紮在這裡。', `MaleText_loc7`='¡Por favor, no nos hagan daño! Los revolucionarios de Vol''jin pueden asentarse aquí.' WHERE `ID`=73389;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날을 "대족장"에게 들이미는 것은 상관없네. 하지만 타락한 그의 일당만을 공격하겠네. 민간인들이 피를 흘리는 일은 없어야 하네!', `MaleText_loc4`='你可以让我对“酋长”拔刀相向，但我只对付他手下那些堕落的战士——不要伤害平民！', `MaleText_loc5`='我願意討伐那位「大酋長」，但是我只對付他那群腐化的士兵。別傷害無辜的老百姓!', `MaleText_loc7`='Podrás hacer que mi acero se vuelva contra el "Jefe de Guerra", pero tan solo contra sus soldados corruptos. ¡Deja a los civiles al margen de este derramamiento de sangre!' WHERE `ID`=73390;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 진짜 호드다!', `MaleText_loc4`='我们才是真正的部落！', `MaleText_loc5`='我們才是正統部落!', `MaleText_loc7`='¡La auténtica Horda es nuestra!' WHERE `ID`=73391;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희는 모두 반역자다!', `MaleText_loc4`='你们都是叛徒！', `MaleText_loc5`='你們全是一群叛徒!', `MaleText_loc7`='¡USTEDES son los traidores aquí!' WHERE `ID`=73392;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진과 너희 짐승들은 모두 돼지우리로 돌아가게 될 것이다!', `MaleText_loc4`='沃金和他手下的畜生将卑贱地死去！', `MaleText_loc5`='沃金和他的畜生們會像廢物般被我們宰殺殆盡!', `MaleText_loc7`='¡Vol''jin y sus animales serán ajusticiados como la escoria que son!' WHERE `ID`=73393;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='해냈다! 칼바위 언덕은 우리 것이다! 그롬마쉬 요새에서 대족장이 이 불길을 보고 있을 것이야...', `MaleText_loc4`='成功了！剃刀岭归我们了！酋长或许已经从格罗玛什要塞上看到火光了……', `MaleText_loc5`='成功了!剃刀嶺是我們的了!大酋長大概可以直接從葛羅瑪許堡看到這邊的火焰...', `MaleText_loc7`='¡Hecho está! ¡Cerrotajo es nuestro! ¡El Jefe de Guerra seguro puede ver los fuegos desde Fuerte Grommash…' WHERE `ID`=73394;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 피리는 복덩이에요! 당신한테 못 줘요!', `MaleText_loc4`='你的笛子是个很好的幸运符！你不配拥有它！', `MaleText_loc5`='我的笛子是最好的幸運星!你不能拿去!', `MaleText_loc7`='¡Mi flauta es un buen grisgrís! No te la doy.' WHERE `ID`=73395;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진! 살아 계셨군요! 그럼 사실인가 봅니다. 대족장에게 반기를 드셨단 소문이요...', `MaleText_loc4`='沃金——你还活着！看来是真的了——一场反对酋长的起义。', `MaleText_loc5`='沃金，你還活著!果然是真的，一場對大酋長的公開兵變。', `MaleText_loc7`='Vol''jin... ¡estás vivo! Entonces es verdad: hay una rebelión total contra el Jefe de Guerra.' WHERE `ID`=73396;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바인, 자네의 도움이 필요하네. 칼바위 언덕은 전초기지일 뿐이야... 대격변 이래 오그리마의 벽은 한층 두꺼워졌네.', `MaleText_loc4`='贝恩。我们需要你。剃刀岭只是一处前哨——大灾变之后，奥格瑞玛的城墙更加坚固了。', `MaleText_loc5`='貝恩。我們需要你的支持。剃刀嶺只是個哨站。奧格瑪則從大災變以來一直在強化防禦工事。', `MaleText_loc7`='Baine. Necesitamos tu apoyo. Cerrotajo es un puesto de avanzada nomás... Las paredes de Orgrimmar están fortificadas desde el Cataclismo. ' WHERE `ID`=73397;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 행동을 조심해야 합니다. 아직 오그리마에 있는 타우렌이 많으니까요.', `MaleText_loc4`='我必须谨慎。我有许多族人还留在奥格瑞玛。', `MaleText_loc5`='我必須小心行事。我們還有許多人在奧格瑪裡。', `MaleText_loc7`='Tengo que actuar con cuidado. Gran parte de mi gente sigue dentro de Orgrimmar. ' WHERE `ID`=73398;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 피리 소리에 맞춰 춤을 추세요!', `MaleText_loc4`='跟着我的笛声跳起来吧！', `MaleText_loc5`='隨著我的笛聲跳支舞吧!', `MaleText_loc7`='¡Deberías bailar al ritmo de mi flauta!' WHERE `ID`=73399;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피리는 아무나 부는 게 아니죠.', `MaleText_loc4`='笛子可不是笨蛋玩的。', `MaleText_loc5`='我才不想浪費我的笛聲。', `MaleText_loc7`='La flauta no es para bobos.' WHERE `ID`=73400;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복덩이? 아니면 안복덩이?', `MaleText_loc4`='幸运符，还是厄运符？', `MaleText_loc5`='是幸運星，還是厄運星?', `MaleText_loc7`='¿Grisgrís o no?' WHERE `ID`=73401;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바보들만 나쁜 복덩이를 원하죠.', `MaleText_loc4`='只有笨蛋才想遇见扫把星。', `MaleText_loc5`='只有傻瓜才會想見霉運星。', `MaleText_loc7`='Solo los bobos quieren encontrar grisgrís malos.' WHERE `ID`=73402;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥의 섬에서 일을 마치면 로르테마르도 공격할 걸세. 밴시 여왕은 말할 것도 없고. 하지만 그 둘은 바다 건너에 있지. 자네의 도움이 없다면, 도시에 침입할 수 없네. 타우렌의 힘이 필요해.', `MaleText_loc4`='等雷神岛事毕，洛瑟玛就会立即起兵，而女妖之王也责无旁贷，可他们都远隔重洋。没有你的力量，我们无法突破城防。我需要牛头人部队。', `MaleText_loc5`='洛索瑪要等他搞定雷王島的事情，而女妖之王則義不容辭，但是他們都必須渡海。沒有你的力量，我們攻不下來。我們需要牛頭人的支持。', `MaleText_loc7`='Lor’themar estará listo para atacar una vez que acabe con la Isla del Trueno y la Reina alma en pena no necesita excusas, pero ambos están del otro lado del mar. Sin tu fuerza, no podemos llegar a la ciudad. Necesitamos armas tauren.' WHERE `ID`=73403;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비하고 있습니다. 하지만 우리 동족의 안전을 확보하려면 시간이 좀 필요합니다. 그런데... 볼진?', `MaleText_loc4`='我们正在准备。但我需要时间来确保族人的安全。可是，沃金……', `MaleText_loc5`='我們正在準備。我只是需要時間來保障我們人民的安全。但是沃金...', `MaleText_loc7`='Nos estamos preparando. Necesito tiempo para garantizar la seguridad de mi gente. Pero Vol''jin…' WHERE `ID`=73404;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음?', `MaleText_loc4`='嗯？', `MaleText_loc5`='嗯?', `MaleText_loc7`='¿Mmm?' WHERE `ID`=73405;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬는 오그리마를 견고한 요새로 바꿨습니다. 동료가 필요할 겁니다... 호드 밖에서요.', `MaleText_loc4`='如今的奥格瑞玛固若金汤。你恐怕还需要……部落之外的盟友。', `MaleText_loc5`='卡爾洛斯把奧格瑪弄成一座堡壘。你必須找更多盟友...不只是部落。', `MaleText_loc7`='Garrosh convirtió Orgrimmar en una fortaleza. Tendrás que buscar aliados... fuera de la Horda. ' WHERE `ID`=73406;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호오, 자네는 강하군! 젊었을 때의 나라면 우리가 이걸 해낼 수 있을까 의심했을 텐데, 지금은 아무런 의심도 없다네.', `MaleText_loc4`='啊，你真强壮！我年轻时，准会怀疑我们能否做到。可现在我不再怀疑了。', `MaleText_loc5`='噢，你很強大!當我還年輕時，我也許會懷疑我們能不能做到。現在呢，我已經沒有一絲懷疑。', `MaleText_loc7`='¡Pero qué fuerte eres! En mi juventud, pude haber dudado de que seríamos capaces de hacer esto. Pero ahora no tengo ninguna duda.' WHERE `ID`=73407;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 바람이 세군! 어찌나 추운지! 옛날이었다면 내 늙은 뼈마디에 절망이 가득찼을 게야. 하지만 오늘 난 희망으로 충만하네.', `MaleText_loc4`='这风真冷啊！过去，它曾让我这把老骨头感到绝望。但是今天，我却满怀希望。', `MaleText_loc5`='好大的風!好冷的天!過去，這會讓我的老骨頭充滿絕望。但在這一天，我卻充滿了希望。', `MaleText_loc7`='¡Tanto viento! ¡Tanto frío! En otros tiempos, habría llenado estos huesos viejos de desesperación. Pero hoy estoy lleno de esperanza.' WHERE `ID`=73408;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하, 자연에 성을 내지 말게나. 폭력은 그냥 자연의 일부분일세. 난 나 자신의 분노를 아주 오래전에 정복했지.', `MaleText_loc4`='呵呵，别对元素发怒。狂暴是它们的天性。我早已征服了自己的愤怒。', `MaleText_loc5`='呵，不要對元素生氣。它們天性暴戾。我很久很久以前就戰勝了自己的憤怒。', `MaleText_loc7`='Je, no te enojes con los elementos. La violencia es su naturaleza. Yo conquisté mi propia ira hace mucho, mucho tiempo.' WHERE `ID`=73409;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자넨 참으로 인내심이 많구먼! 젊었을 때의 나라면 이런 임무 따위는 증오했을 텐데. 요즘에 난 사랑으로 충만하네.', `MaleText_loc4`='你很有耐心！年轻的时候，我最恨这种事。而现在，我感到了满满的关爱。', `MaleText_loc5`='真是有耐心!當我年輕時，我會很討厭做這種事。現在，我卻充滿了愛。', `MaleText_loc7`='¡Tanta paciencia! De joven, habría odiado esta tarea. Hoy en día, estoy lleno de amor.' WHERE `ID`=73410;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='높은 곳을 두려워 말게. 젊었을 때 난 높은 곳을 무서워했지. 공포는 우리가 끔찍한 일을 하게 내몬다네. 아, 하지만 지금 보니, 자넨 나처럼 이미 용기를 배웠구먼!', `MaleText_loc4`='别像我年轻时那样恐高。恐惧会驱使我们做出可怕的事情。啊，但我看得出来，你和我一样，都学会了勇敢！', `MaleText_loc5`='不要像我年輕時一樣怕高。恐懼會促使我們做出可怕的事情。啊，但我看出你跟我一樣，已經學會了勇敢!', `MaleText_loc7`='No le temas a las alturas como yo cuando era joven. El miedo nos puede llevar a cometer actos terribles. Ah, pero veo que, como yo, aprendiste las lecciones del coraje.' WHERE `ID`=73411;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 저는 축축이 로봇 두 번째 모델입니다. 줄여서 H2-0라고 하지요.', `MaleText_loc4`='你好啊！我就是水解型二杠零，简称H2-0。', `MaleText_loc5`='嗨!我是水解二號，一條橫槓後面加個0，或者簡稱H2-0。', `MaleText_loc7`='¡Hola! Soy Hidrolizador modelo 2 guión cero: H2-0, abreviado.' WHERE `ID`=73425;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 당신의 무연탄 정령 진압을 도와드리러 왔습니다.', `MaleText_loc4`='我是来帮你对付硬煤的。', `MaleText_loc5`='我被派來這裡，是為了幫你控制無煙煤。', `MaleText_loc7`='Me han enviado aquí para ayudarte a mantener a Antracita bajo control.' WHERE `ID`=73426;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저에겐 기본적으로 물이 좀 있습니다만, 저의 분사 기능을 여러번 쓰려면 물을 직접 구하셔야 합니다.', `MaleText_loc4`='我已经预存了足够使用一次的水，这是免费赠送的，如果你想反复使用我的水解功能，就需要找到更多的水。', `MaleText_loc5`='我只隨身附帶一次水解用的儲備水，要是你想多用幾次我的水解功能的話，你就必須找到更多的水源。', `MaleText_loc7`='Tengo una carga adicional de agua de serie. Tendrás que buscar más si quieres aprovechar mi función de hidrolización más de una vez.' WHERE `ID`=73427;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF0000호드|r가 중앙 광산을 점령했습니다!', `MaleText_loc4`='|cFFFF0000部落|r取得了对中央矿坑的控制！', `MaleText_loc5`='|cFFFF0000部落|r獲得了中央礦坑的控制權!', `MaleText_loc7`='¡La |cFFFF0000Horda|r controla la Mina Central!' WHERE `ID`=73428;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='문을 봉쇄하고 즉시 감독관에게 알려라.', `MaleText_loc4`='封闭大门，马上去通知监视者。', `MaleText_loc5`='封鎖大門，並且立刻通知監督者。', `MaleText_loc7`='Hay que sellar la puerta y avisar al supervisor inmediatamente.' WHERE `ID`=73429;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하등한 종족들은 모두 진정한 호드의 적이다!', `MaleText_loc4`='所有下等种族都是正统部落的敌人！', `MaleText_loc5`='所有低等種族都是正統部落的敵人。', `MaleText_loc7`='¡Todas las razas inferiores son enemigas de la verdadera Horda!' WHERE `ID`=73430;
