UPDATE `locales_broadcast_text` SET `MaleText_loc1`='봉급도 쥐꼬리만 한데 이런 일까지 해야 해?', `MaleText_loc4`='我没拿到足额的薪水。', `MaleText_loc5`='這不是我的工作內容。', `MaleText_loc7`='No me pagan suficiente para esto.', `FemaleText_loc1`='봉급도 쥐꼬리만 한데 이런 일까지 해야 해?', `FemaleText_loc4`='我没拿到足额的薪水。', `FemaleText_loc5`='這不是我的工作內容。', `FemaleText_loc7`='No me pagan suficiente para esto.' WHERE `ID`=73438;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 부수려고 온 거냐, 엉? 내 앞에서는 어림도 없지!', `MaleText_loc4`='嗯，破坏者？这不归我管！', `MaleText_loc5`='破壞者，嗯?這不關我的事!', `MaleText_loc7`='¿Sabotaje, eh? Durante mi vigilancia no.', `FemaleText_loc1`='뭘 부수려고 온 거냐, 엉? 내 앞에서는 어림도 없지!', `FemaleText_loc4`='嗯，破坏者？这不归我管！', `FemaleText_loc5`='破壞者，嗯?這不關我的事!', `FemaleText_loc7`='¿Sabotaje, eh? Durante mi vigilancia no.' WHERE `ID`=73439;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분대장님, 이놈들은 가로쉬의 부하들입니다.', `MaleText_loc4`='长官，那是加尔鲁什的人。', `MaleText_loc5`='長官，這是卡爾洛斯的手下。', `MaleText_loc7`='Estos son los hombres de Garrosh.' WHERE `ID`=73440;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 월급을 더 깎을 셈이야?', `MaleText_loc4`='你想让我难堪？！', `MaleText_loc5`='你故意讓我出糗?!', `MaleText_loc7`='¡¿Pretendes dejarme mal?!', `FemaleText_loc1`='내 월급을 더 깎을 셈이야?', `FemaleText_loc4`='你想让我难堪？！', `FemaleText_loc5`='你故意讓我出糗?!', `FemaleText_loc7`='¡¿Pretendes dejarme mal?!' WHERE `ID`=73441;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 여기 있다!', `MaleText_loc4`='联盟来了！', `MaleText_loc5`='聯盟的傢伙也在這兒!', `MaleText_loc7`='¡La Alianza está aquí!', `FemaleText_loc1`='얼라이언스가 여기 있다!', `FemaleText_loc4`='联盟来了！', `FemaleText_loc5`='聯盟的傢伙也在這兒!', `FemaleText_loc7`='¡La Alianza está aquí!' WHERE `ID`=73442;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 거기! 어떻게 여기 온 거지?!', `MaleText_loc4`='嘿！你怎么进来的？！', `MaleText_loc5`='嘿!你怎麼會在這裡?!', `MaleText_loc7`='¡Eh! ¡¿Cómo habéis llegado hasta aquí?!', `FemaleText_loc1`='어이, 거기! 어떻게 여기 온 거지?!', `FemaleText_loc4`='嘿！你怎么进来的？！', `FemaleText_loc5`='嘿!你怎麼會在這裡?!', `FemaleText_loc7`='¡Eh! ¡¿Cómo habéis llegado hasta aquí?!' WHERE `ID`=73443;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경비병! 얼라이언스가 있다!', `MaleText_loc4`='卫兵！这里有联盟！', `MaleText_loc5`='守衛!這裡有聯盟的人!', `MaleText_loc7`='¡Guardias! ¡La Alianza está aquí!', `FemaleText_loc1`='경비병! 얼라이언스가 있다!', `FemaleText_loc4`='卫兵！这里有联盟！', `FemaleText_loc5`='守衛!這裡有聯盟的人!', `FemaleText_loc7`='¡Guardias! ¡La Alianza está aquí!' WHERE `ID`=73444;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋지 않은데.', `MaleText_loc4`='这可糟了。', `MaleText_loc5`='這太糟糕了。', `MaleText_loc7`='Esto no es nada bueno.' WHERE `ID`=73445;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 흩어져서 저장실을 수색하도록. 이 일을 가로쉬가 꾸민 거라면, 뭔가 증거가 필요해.', `MaleText_loc4`='全体散开，搜索这座大厅。如果幕后黑手是加尔鲁什，那我们就需要证据。', `MaleText_loc5`='大家分頭搜查這個房間。如果是卡爾洛斯在背後操縱，我們就得找出證據才行。', `MaleText_loc7`='Vamos, todos, sepárense y regístren la cámara. Si Garrosh está detrás de todo esto, necesitaremos pruebas.' WHERE `ID`=73446;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소렌스! 우린 네 적이 아니야!', `MaleText_loc4`='我们不是你的敌人，克索伦斯！', `MaleText_loc5`='我們不是你的敵人，索倫斯!', `MaleText_loc7`='¡No somos el enemigo, Xorenth!' WHERE `ID`=73447;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 보급품 상자는 오그리마에서 온 거잖아. 가로쉬가 이렇게 많은 전쟁 물자로 무슨 일을 꾸미는 거지?', `MaleText_loc4`='这些补给箱来自奥格瑞玛。加尔鲁什要这么多战略物资做什么？', `MaleText_loc5`='這些是從奧格瑪運來的補給箱。卡爾洛斯需要這麼多戰爭補給品做什麼?', `MaleText_loc7`='Los carros de suministros llegaron de Orgrimmar. ¿Qué pretende hacer Garrosh con tantos suministros bélicos?' WHERE `ID`=73448;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원시비룡 알이잖아... 가로쉬가 용아귀 부족과 손을 잡은 건가? 원시비룡을 탄 오크라... 느낌이 안 좋아, $p. 아주 안 좋다고.', `MaleText_loc4`='始祖龙蛋……加尔鲁什跟龙喉氏族合作了吗？骑着始祖龙的兽人，听起来很糟糕，$p，非常糟糕。', `MaleText_loc5`='元龍蛋...卡爾洛斯與龍喉氏族連成一氣了嗎?要對付騎著元龍的獸人可難了，$p，非常難。', `MaleText_loc7`='Huevos de protodraco... ¿Garrosh está trabajando con los Faucedraco? Orcos y protodracos me suena a mala combinación, $p, muy mala.' WHERE `ID`=73449;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이것들은 영원꽃 골짜기에 있는 발굴지에서 온 거예요. 가로쉬는 거기서 뭘 찾으려고 했던 걸까요?', `FemaleText_loc4`='这些都是从锦绣谷的挖掘场运来的。加尔鲁什到底想在那里找什么？', `FemaleText_loc5`='這些是從恆春谷的挖掘場拿來的。卡爾洛斯想找什麼東西?', `FemaleText_loc7`='Son de la excavación en el Valle de la Flor Eterna. ¿Qué trata de encontrar Garrosh allí?' WHERE `ID`=73450;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐, $p! 빨리 이리 좀 와 봐!', `MaleText_loc4`='快一点，$p，我们这里需要你！', `MaleText_loc5`='動作快$p，我們這兒需要你!', `MaleText_loc7`='¡Rápido, $p, te necesitamos aquí!' WHERE `ID`=73451;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이 폭풍을 꺾었을진 몰라도, 잔달라의 의지를 꺾을 수는 없다! 너흰 여기서 죽을 거야.. 하나도 남김없이!', `MaleText_loc4`='就算你们阻止了风暴，也休想阻止赞达拉的意志！你们死定了……一个也跑不了！', `MaleText_loc5`='你們也許阻止了風暴，但你們阻止不了贊達拉的意志!你們會死在這裡，所有的人!', `MaleText_loc7`='¡Habrán detenido la tormenta pero no podrán detener la voluntad de Zandalar! Aquí es donde MORIRÁN... ¡TODOS Y CADA UNO!' WHERE `ID`=73452;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='설원을 붉게 물들여라!', `MaleText_loc4`='让鲜血染红雪地吧！', `MaleText_loc5`='血染滄雪!', `MaleText_loc7`='¡Sangra en la nieve!' WHERE `ID`=73453;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모든 트롤이 너희에 맞서 손잡을 것이다!', `MaleText_loc4`='所有的巨魔都将联手对付你们！', `MaleText_loc5`='全世界的食人妖會群起而攻!', `MaleText_loc7`='¡Los trols del mundo se unirán en su contra!' WHERE `ID`=73454;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 모래를, 바다를, 바람을 지배한다...', `MaleText_loc4`='我们掌握着沙漠、海洋和飓风……', `MaleText_loc5`='我們控制著沙，海，和風...', `MaleText_loc7`='Nosotros controlamos la arena, los mares y los vientos...' WHERE `ID`=73455;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는... 네놈들을 이 산에 묻어버릴 것이다!', `MaleText_loc4`='我们会……让你们葬身山腹！', `MaleText_loc5`='我們會...把你們埋在山裡!', `MaleText_loc7`='Los... ¡enterraremos en su montaña!' WHERE `ID`=73456;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가... 끝이 아니다! 잔달라는... 절대로 쓰러지지 않아...', `MaleText_loc4`='还……没完呢！赞达拉……永垂不朽……', `MaleText_loc5`='還會有更多人!贊達拉...永不倒下...', `MaleText_loc7`='Habrá... ¡otros más! Zandalar... nunca caerá…' WHERE `ID`=73457;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='왕의 용사들이 해냈다. 폭풍이 멈췄다! 전진하라, 검은무쇠 부족이여! 전장을 향해 행군하라!', `FemaleText_loc4`='国王的勇士们成功了：风暴停止了！前进，黑铁矮人！向着战场前进！', `FemaleText_loc5`='國王的勇士成功了，風暴停止了!前進，黑鐵矮人們!前往戰場!', `FemaleText_loc7`='Los campeones del rey lo lograron: ¡se acabó la tormenta! ¡Avancen, Hierro Negro! ¡A LA BATALLA!' WHERE `ID`=73458;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아이언포지를 위해! 얼라이언스를 위해!', `FemaleText_loc4`='为了铁炉堡！为了联盟！', `FemaleText_loc5`='為了鐵爐堡!為了聯盟!', `FemaleText_loc7`='¡Por Forjaz! ¡POR LA ALIANZA!' WHERE `ID`=73459;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='불의 심장이여, 강철의 의지여! 다시 한 번 일어나라! 적을 먼지로 만들어라!', `FemaleText_loc4`='以烈焰为心，钢铁为志！站起来吧！消灭他们！', `FemaleText_loc5`='烈火之心、鋼鐵之志!起身吧!碾碎他們!', `FemaleText_loc7`='Corazones de fuego, voluntades de hierro! ¡De pie! ¡HÁGANLOS POLVO!' WHERE `ID`=73460;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 싸웠소. 검은무쇠 부족은 여전히 용맹하군.', `MaleText_loc4`='干得好。黑铁矮人还是一如既往的强大。', `MaleText_loc5`='打得好。看得出黑鐵矮人還是像以前一樣厲害。', `MaleText_loc7`='Bien peleado. Veo que los Hierro Negro siguen tan formidables como siempre.' WHERE `ID`=73461;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하하하! 그래서 기쁘오. 브론즈비어드와 와일드해머는 여기서 승리를 나누지 못한 걸 후회할 거요.', `MaleText_loc4`='哈！很高兴你能这么说。铜须和蛮锤矮人会后悔未能在此与你分享荣耀的。', `MaleText_loc5`='哈!我很感謝這一點。銅鬚跟蠻錘會後悔沒有來跟你分享榮耀。', `MaleText_loc7`='¡Ja! Me alegro por eso. Los Barbabronces y los Martillos Salvajes lamentarán no haber estado aquí para compartir tu gloria.' WHERE `ID`=73462;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 훌륭히 해냈지. 자, 갑시다. 아이언포지로 돌아가, 의회에 그대의 승리를 알립시다.', `MaleText_loc4`='你已经做到了。来吧，让我们回铁炉堡去，向三锤议会宣告你的胜利。', `MaleText_loc5`='你已經做到這一點了。走吧，我們回去鐵爐堡向議會宣布你的勝利。', `MaleText_loc7`='Bueno, eso es exactamente lo que hicieron. Vamos; volvamos a Forjaz y anunciemos su victoria al Consejo.' WHERE `ID`=73463;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='물론이요, 바리안. 그리고 얼라이언스를 위해서 그 용맹을 발휘했지.', `FemaleText_loc4`='确实如此，瓦里安国王。我还想说，愿为联盟效劳。', `FemaleText_loc5`='這還用說，瓦里安國王。別忘了，這是為聯盟服務。', `FemaleText_loc7`='Muy cierto, Rey Varian. Y al servicio de la Alianza, cabe aclarar.' WHERE `ID`=73464;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그보다는, 이 언덕에서 부족원을 잃지 않은 데 고마워하면 좋겠소. 창피를 주려던 게 아니오. 지키고, 증명하고자 했을 뿐.', `FemaleText_loc4`='还是庆幸他们不用派族人来这里送死吧。我们只想守护家园，表达忠诚而已。', `FemaleText_loc5`='他們最好感謝族人不用死在這個該死的小山丘上。我們為保護家園及展現實力而來，不是羞辱他們。', `FemaleText_loc7`='Más les vale estar agradecidos de que los hombres del clan no quisieron traer la muerte a esta lomita miserable. Nosotros buscamos proteger e impresionar.' WHERE `ID`=73465;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 눈을 믿지 마라!', `MaleText_loc4`='你的眼睛欺骗了你！', `MaleText_loc5`='你無法看穿我!', `MaleText_loc7`='¡Tus ojos te siguen fallando!' WHERE `ID`=73466;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나쁘지 않군!', `MaleText_loc4`='干得好！', `MaleText_loc5`='做得好!', `MaleText_loc7`='¡Bien hecho!' WHERE `ID`=73467;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 기분 나쁘게 킬킬 웃습니다.', `MaleText_loc4`='%s阴险地笑着。', `MaleText_loc5`='%s發出不祥的咯咯笑聲。', `MaleText_loc7`='%s suelta una carcajada inquietante.' WHERE `ID`=73468;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 다시 찾을 수 있겠나?', `MaleText_loc4`='你还能找到我吗？', `MaleText_loc5`='現在你還能找到我嗎?', `MaleText_loc7`='¿Pero podrás encontrarme otra vez?' WHERE `ID`=73469;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제부터 벌어질 일이 참으로 기대되는구나. 백호는 판다리아가 품은 힘의 화신이지!', `MaleText_loc4`='我一直期待着这一天：白虎可是潘达利亚的力量化身！', `MaleText_loc5`='我對此十分期待:白虎是潘達利亞的力量象徵!', `MaleText_loc7`='Esperaba con ansias este momento: ¡el Tigre Blanco personifica la fuerza de Pandaria!' WHERE `ID`=73470;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 판다렌 광산을 공격했습니다!', `MaleText_loc4`='$n突袭了熊猫人矿洞！', `MaleText_loc5`='$n突襲了熊貓人礦坑!', `MaleText_loc7`='¡$n ha asaltado la Mina Pandaren!' WHERE `ID`=73471;
