UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 백호여! 저희의 간청을 들어주소서.', `MaleText_loc4`='白虎！请聆听我们的祈求。', `MaleText_loc5`='偉大的白虎!傾聽我們的請求。', `MaleText_loc7`='¡Gran Tigre Blanco! Escucha nuestras súplicas.' WHERE `ID`=73477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 젊은 검은용이 고맙게도 내 사원에 발걸음을 했군. 너와 네 용사가 한 일은 이미 판다렌의 전설이 되고 있다.', `MaleText_loc4`='啊，年轻的黑龙光临了我的寺院。你们俩的事迹已成了广为流传的潘达利亚传奇了。', `MaleText_loc5`='啊，年輕的黑龍令我感到蓬蓽生輝。你和你的勇士正在快速地變成熊貓人的傳說。', `MaleText_loc7`='Ah, el joven dragón negro agracia mi templo. Sus hazañas se están convirtiendo rápidamente en una leyenda pandaren.' WHERE `ID`=73478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 저의 용사에게 힘의 축복을 내려 주소서.', `MaleText_loc4`='我和我的勇士希望得到力量的祝福。', `MaleText_loc5`='我和我的勇士來尋求您力量的祝福。', `MaleText_loc7`='Buscamos la bendición de tu fuerza.' WHERE `ID`=73479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 선택한 동료를 자랑스럽게 생각합니다.', `MaleText_loc4`='我为我的同伴感到骄傲。', `MaleText_loc5`='我為我的同伴感到驕傲。', `MaleText_loc7`='Me enorgullezco de quien me acompaña.' WHERE `ID`=73480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 봐라, 젊은 왕자여. 힘의 본질이 무엇이냐?', `MaleText_loc4`='告诉我，年轻的王子：什么是力量？', `MaleText_loc5`='告訴我，年輕的王子，什麼是力量?', `MaleText_loc7`='Dime, joven príncipe: ¿cuál es la naturaleza de la fuerza?' WHERE `ID`=73481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 무찌르는 능력입니다. 그것이 바로 힘입니다.', `MaleText_loc4`='毁灭敌人的能力。这就是力量。', `MaleText_loc5`='摧毀敵人的能力。這就是力量。', `MaleText_loc7`='El poder de aplastar a los enemigos. Eso es la fuerza.' WHERE `ID`=73482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='단순히 적에 대해서만 생각하고 대답하는구나.', `MaleText_loc4`='这只是对于敌人一方而言。', `MaleText_loc5`='你說的只有針對敵人。', `MaleText_loc7`='Hablas nada más en términos de enemigos.' WHERE `ID`=73483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론, 힘으로 친구를 도울 수도 있지요.', `MaleText_loc4`='当然，力量也能帮助盟友。', `MaleText_loc5`='當然了，力量也能幫助盟友。', `MaleText_loc7`='Pero lo cierto es que la fuerza puede beneficiar a los aliados.' WHERE `ID`=73484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떻게?', `MaleText_loc4`='怎么帮？', `MaleText_loc5`='怎麼說呢?', `MaleText_loc7`='¿En qué forma?' WHERE `ID`=73485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 힘으로 친구의 적을 무찌르는 겁니다!', `MaleText_loc4`='……当然是摧毁共同的敌人！', `MaleText_loc5`='...幫盟友擊潰敵人!', `MaleText_loc7`='¡Usándola para aplastar a sus enemigos!' WHERE `ID`=73486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이거야 원, 뼛속까지 검은용이로군. 좋다. 내 축복을 내려 주지. 작은 충고도 함께.', `MaleText_loc4`='真不愧是黑龙。很好，我会给你们祝福，但我也有些建议：', `MaleText_loc5`='徹頭徹尾的一頭黑龍。好吧，我會給你我的祝福，但也有些建議:', `MaleText_loc7`='Un dragón negro, de patas a cabeza. Muy bien, les daré mi bendición, pero también un consejo:' WHERE `ID`=73487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='힘이란 다른 이를 위해 사용할 때가, 자신의 적을 무찌르려고 사용할 때보다 두 배는 강한 법이다.', `MaleText_loc4`='用力量去帮助别人，会比用它来对付敌人更加强大。', `MaleText_loc5`='用來服務他人的力量會比用在敵人身上的力量還要強上兩倍。', `MaleText_loc7`='la fuerza, usada al servicio de otros, es el doble de poderosa que la fuerza que usamos contra nuestros enemigos.' WHERE `ID`=73488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 나의 시험을 받겠느냐? 어떤 위험이라도 당당히 마주하고, 끝까지 꿋꿋하게 싸워갈 수 있는지 보는 시험이다.', `MaleText_loc4`='那么，我的挑战，如果你们接受的话，将测试你们正确应对危险的能力与毅力。', `MaleText_loc5`='現在。如果你們接受我的挑戰，將會測試你們在面對危險時是否能不屈不撓。', `MaleText_loc7`='Bien. Mi desafío, si lo aceptan, pondrá a prueba su habilidad para no flaquear frente al peligro y perseverar.' WHERE `ID`=73489;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFE1CF7|Hspell:139267|h[성물회 곡괭이]|h|r 15초 동안 획득하는 유물의 수가 2배로 증가합니다!', `MaleText_loc4`='|cFFFE1CF7|Hspell:139267|h[文物镐]|h|r可使你获得双倍的遗物，持续15秒！', `MaleText_loc5`='|cFFFE1CF7|Hspell:139267|h[聖匣十字鎬]|h|r使你找到文物的數量提高一倍，持續15秒!', `MaleText_loc7`='|cFFFE1CF7|Hspell:139267|h[Recolección de reliquias]|h|r duplica los artefactos durante 15 segundos.', `FemaleText_loc1`='|cFFFE1CF7|Hspell:139267|h[성물회 곡괭이]|h|r 15초 동안 획득하는 유물의 수가 2배로 증가합니다!', `FemaleText_loc4`='|cFFFE1CF7|Hspell:139267|h[文物镐]|h|r可使你获得双倍的遗物，持续15秒！', `FemaleText_loc5`='|cFFFE1CF7|Hspell:139267|h[聖匣十字鎬]|h|r使你找到文物的數量提高一倍，持續15秒!', `FemaleText_loc7`='|cFFFE1CF7|Hspell:139267|h[Recolección de reliquias]|h|r duplica los artefactos durante 15 segundos.' WHERE `ID`=73490;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[레이피어 무기 막기] 능력을 사용해 수직 베기를 막으십시오!', `MaleText_loc4`='使用[细剑招架]技能来避免竖劈！', `MaleText_loc5`='使用[細劍招架]架開垂直斬擊!', `MaleText_loc7`='¡Usa la facultad [Parada de estoque] para evitar Tajo vertical!' WHERE `ID`=73491;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF2222|Hspell:141327|h[휘발성 혼합물]|h|r을 마시기 시작합니다!', `MaleText_loc4`='%s开始饮用|cFFFF2222|Hspell:141327|h[不稳定的混合物]|h|r。', `MaleText_loc5`='%s開始服用|cFFFF2222|Hspell:141327|h[爆炸性混合物]|h|r。', `MaleText_loc7`='%s empieza a beber un |cFFFF2222|Hspell:141327|h[brebaje volátil]|h|r.' WHERE `ID`=73492;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쉬엔의 시험을 받아들이려면 징을 울리십시오. 네 천신의 시험 중 하나를 통과해야 합니다.', `MaleText_loc4`='敲响挑战之锣以接受雪怒的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。', `MaleText_loc5`='敲響銅鑼接受雪怒的挑戰。你只需要戰勝四位天尊其中一位的挑戰。', `MaleText_loc7`='Haz sonar el gong para aceptar el desafío de Xuen. Solo tendrás que superar uno de los cuatro desafíos de los Celestiales.' WHERE `ID`=73493;
