UPDATE `locales_broadcast_text` SET `MaleText_loc1`='특별한 경우에 쓰려고 아껴놨던 겁니다.', `MaleText_loc4`='我专门为这种特殊情况留了一手。', `MaleText_loc5`='我留著它就是為了用來應付這種特殊情況。', `MaleText_loc7`='Estaba reservando esto para una ocasión especial.' WHERE `ID`=73496;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='딱 맞는 게 있죠!', `MaleText_loc4`='这玩意儿刚好能派上用场！', `MaleText_loc5`='我有這個!', `MaleText_loc7`='¡Tengo justo lo que necesitamos!' WHERE `ID`=73497;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀 폭탄이잖아?! 그게 동굴을 홀랑 무너뜨리진 않겠지?', `MaleText_loc4`='螳螂妖炸弹？！你确定这不会炸塌整座洞穴吗？', `MaleText_loc5`='螳螂人炸彈?!你確定不會炸掉整個洞穴嗎?', `MaleText_loc7`='¡¿Una bomba mántide?! ¿No correremos el riego de echar abajo toda la caverna?' WHERE `ID`=73498;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='개조를 좀 해야겠지만, 문은 확실히 날려버릴 수 있을 겁니다.', `MaleText_loc4`='我们需要做一点改装，但它会起作用的。', `MaleText_loc5`='我們需要做些調整，不過它會搞定這扇門的。', `MaleText_loc7`='Tendremos que hacer una serie de modificaciones, pero servirá.' WHERE `ID`=73499;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신참, 저 물놀이용 조랑말이랑 대포알 세 개, 전지 두 개, 그리고 원시비룡 알 노른자 좀 가져오라고.', `MaleText_loc4`='新兵，把那个池塘小马拿给我，还有三枚炮弹，两个电池以及那个始祖龙蛋黄。', `MaleText_loc5`='新兵，帶那個小馬泳圈、三顆砲彈、兩顆電池和一些元龍蛋的蛋黃給我。', `MaleText_loc7`='Recluta, tráeme ese poni flotador, tres balas de cañón, dos baterías y un poco de yema de huevo de protodraco.' WHERE `ID`=73500;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 말 들었지, $p. 빨랑 가서 가져와!', `MaleText_loc4`='你听到地精的话了，$p，快去干活！', `MaleText_loc5`='你聽見那個哥布林說的了，$p，快去幹活!', `MaleText_loc7`='Ya has oído al goblin, $p. ¡Manos a la obra!' WHERE `ID`=73501;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 이걸 여기 단 거야? 대체 누가 이걸 여기에 달아? 누군지 몰라도 부끄러운 줄 알아야지.', `MaleText_loc4`='等等？他们怎么把这玩意儿放在这儿？谁会把这种东西放在这里？不管是谁，他都应该为此感到抱歉。', `MaleText_loc5`='等等?他們把這個東西放在這裡?是誰會做這種事情?不管是誰，他們會後悔的。', `MaleText_loc7`='Espera. ¿Han puesto esto aquí? ¿Quién ha puesto esto aquí? Quien haya sido debe de sentirse mal.', `FemaleText_loc1`='잠깐, 이걸 여기 단 거야? 대체 누가 이걸 여기에 달아? 누군지 몰라도 부끄러운 줄 알아야지.', `FemaleText_loc4`='等等？他们怎么把这玩意儿放在这儿？谁会把这种东西放在这里？不管是谁，他都应该为此感到抱歉。', `FemaleText_loc5`='等等?他們把這個東西放在這裡?是誰會做這種事情?不管是誰，他們會後悔的。', `FemaleText_loc7`='Espera. ¿Han puesto esto aquí? ¿Quién ha puesto esto aquí? Quien haya sido debe de sentirse mal.' WHERE `ID`=73504;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"좀 제대로 만들어 봐."라니. 어이가 없어서, 원. "우리가 안 죽게끔 말이야."? 하.', `MaleText_loc4`='“要用真螺栓，”他说，“不会害死我们的那种，”他说。我呸。', `MaleText_loc5`='「放真的箭進去。」他說。「不會連我們也殺了的那種箭。」他呸了一口說。', `MaleText_loc7`='"Pon las tuercas adecuadas", dice. "Las que no nos maten a todos", dice. Bah.', `FemaleText_loc1`='"좀 제대로 만들어 봐."라니. 어이가 없어서, 원. "우리가 안 죽게끔 말이야."? 하.', `FemaleText_loc4`='“要用真螺栓，”他说，“不会害死我们的那种，”他说。我呸。', `FemaleText_loc5`='「放真的箭進去。」他說。「不會連我們也殺了的那種箭。」他呸了一口說。', `FemaleText_loc7`='"Pon las tuercas adecuadas", dice. "Las que no nos maten a todos", dice. Bah.' WHERE `ID`=73505;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='흠. 이거 어떻게 움직이게 하는지 누가 알려줬으면 좋겠군.', `MaleText_loc4`='嗯，天知道该怎么让这玩意儿动起来。', `MaleText_loc5`='嗯，希望有人找出讓這個東西移動的方法。', `MaleText_loc7`='Ay, espero que alguien haya descubierto cómo hacer que este trasto se mueva.', `FemaleText_loc1`='흠. 이거 어떻게 움직이게 하는지 누가 알려줬으면 좋겠군.', `FemaleText_loc4`='嗯，天知道该怎么让这玩意儿动起来。', `FemaleText_loc5`='嗯，希望有人找出讓這個東西移動的方法。', `FemaleText_loc7`='Ay, espero que alguien haya descubierto cómo hacer que este trasto se mueva.' WHERE `ID`=73506;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오크들이 설계한 것도 나쁘진 않군. 폭탄이 좀 더 들어가야 한다는 것만 빼면.', `MaleText_loc4`='这些兽人的设计还不错。他们只需要多加一些炸弹。', `MaleText_loc5`='獸人的設計沒問題。他們只是需要更多的炸彈。', `MaleText_loc7`='Los diseños de los orcos no están mal. Solo les hacen falta unas cuantas bombas más.', `FemaleText_loc1`='오크들이 설계한 것도 나쁘진 않군. 폭탄이 좀 더 들어가야 한다는 것만 빼면.', `FemaleText_loc4`='这些兽人的设计还不错。他们只需要多加一些炸弹。', `FemaleText_loc5`='獸人的設計沒問題。他們只是需要更多的炸彈。', `FemaleText_loc7`='Los diseños de los orcos no están mal. Solo les hacen falta unas cuantas bombas más.' WHERE `ID`=73507;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 시험을 시작하자! 영웅이여, 넌 이제 근접 전투에서 검은 왕자에게 승리해야 한다.', `MaleText_loc4`='现在开始挑战吧！英雄，你必须要在近战中击败黑王子。', `MaleText_loc5`='讓挑戰開始吧!英雄，你必須在近身戰鬥中擊敗黑龍王子。', `MaleText_loc7`='¡Que comience el desafío! Deberás derrotar al Príncipe Negro en combate cuerpo a cuerpo.' WHERE `ID`=73508;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='래시온, 너는 눈을 가릴 것이다.', `MaleText_loc4`='你，拉希奥，将被蒙上眼睛。', `MaleText_loc5`='你，怒西昂，必須矇上眼睛。', `MaleText_loc7`='Tú, Wrathion, tendrás los ojos vendados.' WHERE `ID`=73509;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 왕자여, 물론 넌 매우 강하지. 하지만 이끌어줄 눈이 없다면 힘이 무슨 소용이겠느냐?', `MaleText_loc4`='黑王子，你很强大。可是失去指引的力量又有什么用呢？', `MaleText_loc5`='黑龍王子，你十分強大。但是力量若是盲目的，又能派上什麼用場呢?', `MaleText_loc7`='Eres muy fuerte, Príncipe Negro. ¿Pero de qué sirve la fuerza sin la visión que la guía?' WHERE `ID`=73510;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작해라!', `MaleText_loc4`='开始！', `MaleText_loc5`='開始!', `MaleText_loc7`='¡Comiencen!' WHERE `ID`=73511;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐, 말도 안 됩니다. 저의 용사를 제 손으로 죽이라고요?', `MaleText_loc4`='等等——这太荒唐了。我会杀死我的勇士的！', `MaleText_loc5`='等等 - 這太荒謬了。我會把自己的勇士殺死!', `MaleText_loc7`='Espera... Eso es absurdo. ¡Aniquilaría a mi propio campeón!' WHERE `ID`=73512;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 흥미롭군요. 하지만 결과는 다르지 않을 겁니다.', `MaleText_loc4`='……有意思。但结果不会改变。', `MaleText_loc5`='...有意思。但是結果不太可能改變。', `MaleText_loc7`='Interesante. Pero lo más probable es que el resultado sea el mismo.' WHERE `ID`=73513;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다. 미안하구나, 용사여. 하지만 오늘 교훈을 얻을 사람은 내가 아니다.', `MaleText_loc4`='好吧。抱歉了，勇士——但今天被教训的人肯定不会是我。', `MaleText_loc5`='好吧。很抱歉，勇士。不過今天得到教訓的絕對不會是我。', `MaleText_loc7`='Muy bien. Lo siento, pero no seré yo el que aprenda una lección el día de hoy.' WHERE `ID`=73514;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기름이 더 필요해! 얼마나 더 말해줘야 알아듣겠어?!', `MaleText_loc4`='我跟你们这些苦工说过多少次了！我们需要更多的原油！', `MaleText_loc5`='我們需要更多的油!到底要我說幾次才行!', `MaleText_loc7`='¡Necesitamos más aceite! ¿Cuántas veces os lo tengo que decir, peones?', `FemaleText_loc1`='기름이 더 필요해! 얼마나 더 말해줘야 알아듣겠어?!', `FemaleText_loc4`='我跟你们这些苦工说过多少次了！我们需要更多的原油！', `FemaleText_loc5`='我們需要更多的油!到底要我說幾次才行!', `FemaleText_loc7`='¡Necesitamos más aceite! ¿Cuántas veces os lo tengo que decir, peones?' WHERE `ID`=73515;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈을 가리며 %s|1이;가; 투덜거립니다.', `MaleText_loc4`='%s嘟囔着戴上了眼罩。', `MaleText_loc5`='%s綁上蒙眼布時喃喃自語。', `MaleText_loc7`='%s habla solo entre dientes mientras se ata la venda.' WHERE `ID`=73516;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='눈 먼 용이라니. 어이가 없어서!', `MaleText_loc4`='一头瞎眼的龙。真可笑！', `MaleText_loc5`='要我扮瞎眼的龍。真荒謬!', `MaleText_loc7`='Un dragón ciego. ¡Qué ridículo!' WHERE `ID`=73517;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 적을 찾아야 한다! 가짜 모습에 속지 마라!', `MaleText_loc4`='找出真正的敌人！别被假象迷惑了！', `MaleText_loc5`='尋找你真正的敵人!別被他虛假的影像影響!', `MaleText_loc7`='¡Busca a tu verdadero enemigo! ¡Que no te engañen las imágenes falsas!' WHERE `ID`=73518;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 용은 너보다 강하다, 영웅이여! 그가 공격을 마무리하게 두지 마라!', `MaleText_loc4`='巨龙比你更强大，英雄！别让他完成攻击！', `MaleText_loc5`='黑龍比你強大，英雄!別讓他完成攻擊!', `MaleText_loc7`='¡El dragón es más fuerte que tú! ¡No permitas que acabe sus ataques!' WHERE `ID`=73519;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 사람들아! 자네들은 노동자라고! 노동을 하란 말이야!', `MaleText_loc4`='得了吧！你们就是工人！你们就该干活！', `MaleText_loc5`='拜託!你們是苦力!本來就該要勞動!', `MaleText_loc7`='¡Vamos! ¡Sois trabajadores! ¡Deberíais estar trabajando!', `FemaleText_loc1`='이 사람들아! 자네들은 노동자라고! 노동을 하란 말이야!', `FemaleText_loc4`='得了吧！你们就是工人！你们就该干活！', `FemaleText_loc5`='拜託!你們是苦力!本來就該要勞動!', `FemaleText_loc7`='¡Vamos! ¡Sois trabajadores! ¡Deberíais estar trabajando!' WHERE `ID`=73520;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='폭발물이 고작 이것밖에 없다고? 내 신발에도 이것보단 폭발물이 많이 들어가있어.', `MaleText_loc4`='我们就这点炸药了吗？我靴子上用的炸药都比它多。', `MaleText_loc5`='就只有這麼點炸彈嗎?拿來給我做靴子都不夠。', `MaleText_loc7`='¿Esos son todos los explosivos que tenemos? He fabricado botas con más explosivos que esos.', `FemaleText_loc1`='폭발물이 고작 이것밖에 없다고? 내 신발에도 이것보단 폭발물이 많이 들어가있어.', `FemaleText_loc4`='我们就这点炸药了吗？我靴子上用的炸药都比它多。', `FemaleText_loc5`='就只有這麼點炸彈嗎?拿來給我做靴子都不夠。', `FemaleText_loc7`='¿Esos son todos los explosivos que tenemos? He fabricado botas con más explosivos que esos.' WHERE `ID`=73521;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가능하면 그를 무장해제시켜라. 가진 모든 기술을 사용해.', `MaleText_loc4`='多使用缴械，利用每一点优势。', `MaleText_loc5`='盡量卸除他的武裝。使用每個優勢。', `MaleText_loc7`='Desármalo si puedes. Usa todas las ventajas.' WHERE `ID`=73522;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 뒤를 잡아라. 그는 널 볼 수 없어! 빠르게 움직여라!', `MaleText_loc4`='绕到敌人背后去。他看不见你！动起来！', `MaleText_loc5`='躲在他的背後。他看不到你!快移動!', `MaleText_loc7`='Quédate detrás de tu enemigo. ¡Que no te vea! ¡Muévete rápidamente!' WHERE `ID`=73523;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기다. 위대한 흑우 니우짜오의 보금자리. 그는 판다렌의 인내를 상징하는 존재지. 유일하게 벽 너머에 머물기를 선택한 천신이고.', `MaleText_loc4`='我们到了，玄牛砮皂的家园。他象征着潘达利亚的坚忍精神，是唯一住在长城之外的至尊天神。', `MaleText_loc5`='我們到了，這裡便是玄牛怒兆的家。他是代表熊貓人剛毅的守護神，也是唯一選擇常駐長城外的天尊。', `MaleText_loc7`='Aquí estamos: el hogar de Niuzao, el Buey Negro. Es el espíritu patrono de la fortaleza pandaren. El único celestial que elige vivir del otro lado del muro.' WHERE `ID`=73524;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강대한 흑우여! 저희의 간청을 들어주소서.', `MaleText_loc4`='玄牛！请聆听我们的祈求！', `MaleText_loc5`='偉大的玄牛!傾聽我們的請求!', `MaleText_loc7`='¡Poderoso Buey Negro! Escucha nuestras súplicas.' WHERE `ID`=73525;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 저의 용사에게 인내의 축복을 내려 주소서.', `MaleText_loc4`='我和我的勇士希望得到坚忍的祝福。', `MaleText_loc5`='我和我的勇士來尋求您剛毅的祝福。', `MaleText_loc7`='Buscamos la bendición de tu fortaleza.' WHERE `ID`=73526;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 역경도 이겨내는 힘입니다! 그것이 바로 인내입니다.', `MaleText_loc4`='克服一切困难的力量！这就是坚忍。', `MaleText_loc5`='克服任何困境的力量!這就是剛毅。', `MaleText_loc7`='¡La fuerza para superar cualquier adversidad! Eso es la fortaleza.' WHERE `ID`=73527;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하시고 싶은 말씀이... 육체적 강인함은 외적인 조건일 뿐, 인내는 내면에서 나온다는 겁니까?', `MaleText_loc4`='你是想说——力量是外在的表现，而坚忍来自于内心？', `MaleText_loc5`='你想說的是，身體之力是表面，但剛毅是來自內心?', `MaleText_loc7`='Quieres decir que... la fuerza física se desarrolla por fuera... ¿y la fortaleza viene del interior?' WHERE `ID`=73528;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그렇죠. 알고 있었습니다.', `MaleText_loc4`='……当然。我早就知道了。', `MaleText_loc5`='...當然啦。我早就知道了。', `MaleText_loc7`='Claro. Lo sabía.' WHERE `ID`=73529;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호오, 용과 그의 필멸의 용사가 날 찾아왔군. 내 너희를 환영하노라.', `MaleText_loc4`='小龙和他的凡人勇士来了。欢迎你们。', `MaleText_loc5`='黑龍和他的凡人勇士來了。歡迎你們。', `MaleText_loc7`='Llegó el dragón y su campeón mortal. Sean bienvenidos.' WHERE `ID`=73530;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보아라, 검은 왕자여. 인내의 본질이 무엇이냐?', `MaleText_loc4`='告诉我，黑王子：什么才是坚忍？', `MaleText_loc5`='告訴我，黑龍王子，什麼是剛毅?', `MaleText_loc7`='Dime, Príncipe Negro: ¿cuál es la naturaleza de la fortaleza?' WHERE `ID`=73531;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 힘과 인내를 착각하고 있구나, 젊은 용이여. 힘이란 강인한 정신 없이는 무용지물이지!', `MaleText_loc4`='你把力量和坚忍搞混了，小龙。没有精神的力量一无是处！', `MaleText_loc5`='你把力量和剛毅混淆了，年輕的黑龍。沒有靈魂的力量，什麼都不是!', `MaleText_loc7`='Confundes fuerza con fortaleza, joven dragón. ¡Pero el poder no vale nada sin el espíritu!' WHERE `ID`=73532;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 초라한 노예들이 상상도 할 수 없는 끔찍한 고문을 견뎌내고, 마침내 봉기하여 그 주인을 타도하는 것을 보았다.', `MaleText_loc4`='我见过卑微的奴隶忍受着难以想象的折磨，只为推翻他们的主人。', `MaleText_loc5`='我見過卑微的奴隸熬過難以想像的酷刑，然後起身推翻他們的主人。', `MaleText_loc7`='He visto a esclavos humildes resistir torturas inimaginables para luego levantarse y derrocar a sus amos.' WHERE `ID`=73533;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='또한 가장 강력한 황제들이, 하잘것없는 적들이 가진 불굴의 인내에 꺾이는 모습도 보았지.', `MaleText_loc4`='我还见过最强大的皇帝被渺小而坚忍不拔的敌人打倒。', `MaleText_loc5`='我也見過最強大的帝王在敗於最微不足道，卻堅韌不拔的對手之下。', `MaleText_loc7`='Y he visto a los emperadores más poderosos caer bajo la perseverancia de los enemigos más pequeños.' WHERE `ID`=73534;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바로 그거다!', `MaleText_loc4`='没错！', `MaleText_loc5`='說得沒錯!', `MaleText_loc7`='¡Precisamente!' WHERE `ID`=73535;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물론 알고 있었겠지. 잘 이해하고 있는지 시험해 보는 건 어떤가?', `MaleText_loc4`='是啊……你知道。但或许我们该考验一下你的理解。', `MaleText_loc5`='你當然知道。也許我們能把你的理解拿來考驗一番。', `MaleText_loc7`='Por supuesto. Tal vez podamos poner a prueba tu entendimiento.' WHERE `ID`=73536;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 시험을 받겠느냐? 너의 용사가 끔찍한 역경을 견뎌내며 다른 이를 지키고 보호할 수 있는지 알아보는 시험이다.', `MaleText_loc4`='如果你们能够接受我的挑战的话，它将测试这位勇士在艰苦条件下的防卫能力。', `MaleText_loc5`='我的挑戰，是要考驗你的勇士在身處磨難之際是否有能力防禦和保護他人。', `MaleText_loc7`='Mi desafío, si lo aceptan, pondrá a prueba la habilidad de tu campeón para defender y proteger mientras se enfrentan a una adversidad terrible.' WHERE `ID`=73537;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격을 피해라. 그가 자기 힘에 당하게 해!', `MaleText_loc4`='躲开攻击。利用他的力量对付他！', `MaleText_loc5`='閃躲他的攻擊。用他的力量對付他!', `MaleText_loc7`='Esquiva sus ataques. ¡Usa su fuerza contra él!' WHERE `ID`=73538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령은 다시 일어날 것이다. 그때까지 남은 시간을 현명하게 사용해라!', `MaleText_loc4`='元素是不灭的！在它们复活前，利用好你的时间！', `MaleText_loc5`='元素是不滅的!在它們再度起身前好好利用你的時間!', `MaleText_loc7`='¡Los elementos no morirán! ¡Aprovecha bien el tiempo antes de que vuelvan a levantarse!' WHERE `ID`=73539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 금광 수레가 가득 찼고 이제 기지에서 빼앗을 수 있습니다!', `MaleText_loc4`='联盟运金车已满，现在可以潜入他们的基地去偷走它了！', `MaleText_loc5`='聯盟的礦車已經裝滿黃金了。去他們的營地把礦車偷回來!', `MaleText_loc7`='El carro de oro de la Alianza ya está lleno y se puede robar de su base.' WHERE `ID`=73540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 금광 수레가 가득 찼고 이제 기지에서 빼앗을 수 있습니다!', `MaleText_loc4`='部落运金车已满，现在可以潜入他们的基地去偷走它了！', `MaleText_loc5`='部落的礦車已經裝滿黃金了。去他們的營地把礦車偷回來!', `MaleText_loc7`='El carro de oro de la Horda ya está lleno y se puede robar de su base.' WHERE `ID`=73541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 뭐지?', `MaleText_loc4`='那是什么？', `MaleText_loc5`='那是什麼?', `MaleText_loc7`='¿Qué ha sido eso?', `FemaleText_loc1`='방금 뭐지?', `FemaleText_loc4`='那是什么？', `FemaleText_loc5`='那是什麼?', `FemaleText_loc7`='¿Qué ha sido eso?' WHERE `ID`=73542;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공격 받고 있다!', `MaleText_loc4`='我们被攻击了！', `MaleText_loc5`='我們遭受攻擊了!', `MaleText_loc7`='¡Nos están atacando!', `FemaleText_loc1`='공격 받고 있다!', `FemaleText_loc4`='我们被攻击了！', `FemaleText_loc5`='我們遭受攻擊了!', `FemaleText_loc7`='¡Nos están atacando!' WHERE `ID`=73543;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='니우짜오의 시험을 받아들이려면 징을 울리십시오. 네 천신의 시험 중 하나를 통과해야 합니다.', `MaleText_loc4`='敲响挑战之锣以接受砮皂的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。', `MaleText_loc5`='敲響銅鑼接受怒兆的挑戰。你只需要戰勝四位天尊其中一位的挑戰。', `MaleText_loc7`='Haz sonar el gong para aceptar el desafío de Niuzao. Solo tendrás que superar uno de los cuatro desafíos de los Celestiales.' WHERE `ID`=73544;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징 울리기 [방어 담당자용 시험]', `MaleText_loc4`='敲响挑战之锣[防御挑战]', `MaleText_loc5`='敲響銅鑼[防禦挑戰]', `MaleText_loc7`='Haz sonar el gong [desafío de defensa]', `FemaleText_loc1`='징 울리기 [방어 담당자용 시험]', `FemaleText_loc4`='敲响挑战之锣[防御挑战]', `FemaleText_loc5`='敲響銅鑼[防禦挑戰]', `FemaleText_loc7`='Haz sonar el gong [desafío de defensa]' WHERE `ID`=73545;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스를 믿을 수는 없지만, 호드를 되찾으려면 그들의 도움이 필요합니다.', `MaleText_loc4`='我们或许不该相信联盟，但要想夺回部落，我们就需要他们的帮助。', `MaleText_loc5`='雖然聯盟這群傢伙不能信任，但是如果我們想擊退部落，就得靠他們幫忙才行。', `MaleText_loc7`='Puede que la Alianza no sea de fiar, pero necesitamos su ayuda si queremos recuperar el control de la Horda.' WHERE `ID`=73546;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 그의 |cFFFF2222|Hspell:141381|h[산탄총]|h|r을 장전하기 위해 뜁니다.', `MaleText_loc4`='%s跑去为|cFFFF2222|Hspell:141381|h[霰弹射击]|h|r装填弹药了。', `MaleText_loc5`='%s為|cFFFF2222|Hspell:141381|h[獵槍]|h|r填充彈藥。', `MaleText_loc7`='%s corre para recargar su |cFFFF2222|Hspell:141381|h[escopeta]|h|r.' WHERE `ID`=73547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 얼라이언스의 금광 수레를 빼앗았습니다!', `MaleText_loc4`='$n夺取了联盟运金车！', `MaleText_loc5`='$n奪走了聯盟的黃金礦車!', `MaleText_loc7`='¡$n ha tomado el carro de oro de la Alianza!' WHERE `ID`=73548;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드의 금광 수레를 빼앗았습니다!', `MaleText_loc4`='$n夺取了部落运金车！', `MaleText_loc5`='$n奪走了部落的黃金礦車!', `MaleText_loc7`='¡$n ha tomado el carro de oro de la Horda!' WHERE `ID`=73549;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망의 화신 주학은 역사의 여명기부터 판다리아의 주민들에게 힘을 주는 존재였지. 그와 얘기하는 게 기대되는구나.', `MaleText_loc4`='朱鹤带来的希望曾在历史上最黑暗的时刻鼓舞过潘达利亚的人民。我很想跟他谈谈。', `MaleText_loc5`='象徵希望的紅鶴從歷史的起源就鼓舞著潘達利亞的人民。我很希望能跟祂說話。', `MaleText_loc7`='La Grulla Roja de la Esperanza ha inspirado a los ciudadanos de Pandaria desde los albores de la historia. Tengo muchos deseos de hablar con él.' WHERE `ID`=73550;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 주학이여! 저희의 간청을 들어주소서.', `MaleText_loc4`='朱鹤！请聆听我们的祈求。', `MaleText_loc5`='偉大的紅鶴!傾聽我們的請求。', `MaleText_loc7`='¡Gran Grulla Roja! Escucha nuestras súplicas.' WHERE `ID`=73551;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 저의 용사에게 희망의 축복을 내려 주소서.', `MaleText_loc4`='我和我的勇士想要得到希望的祝福。', `MaleText_loc5`='我和我的勇士來尋求您希望的祝福。', `MaleText_loc7`='Buscamos la bendición de tu esperanza.' WHERE `ID`=73552;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이란... 그건... 더 나은 내일에 대한 믿음입니다.', `MaleText_loc4`='希望就是……就是相信明天会更好。', `MaleText_loc5`='希望是...相信明天會更好。', `MaleText_loc7`='La esperanza es... creer en un mañana mejor.' WHERE `ID`=73553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 학이여, 당신은 제가 본 것을 못 보셨습니다.', `MaleText_loc4`='……朱鹤。你未曾见过我眼中所见。', `MaleText_loc5`='...偉大的紅鶴，你沒見過我所見到的。', `MaleText_loc7`='Gran Grulla. No has visto las cosas que yo he visto.' WHERE `ID`=73554;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='... 그 옛날 하늘을 불태웠던 불길이 돌아올 겁니다. 막을 수가 없습니다. 불타는 군단이 아제로스를 찾을 겁니다.', `MaleText_loc4`='……燃烧天空的烈火即将归来，无可避免。燃烧军团会找到艾泽拉斯。', `MaleText_loc5`='...曾經燃燒天空的火焰會回歸。這無可避免，燃燒軍團會回到艾澤拉斯。', `MaleText_loc7`='Los fuegos que alguna vez quemaron el cielo volverán. Es inevitable. La Legión Ardiente encontrará a Azeroth.' WHERE `ID`=73555;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피가 바다를 이루고, 도시는 폐허가 되겠죠! 우리가, 이렇게 분열된 채로... 어떻게 군단에 맞서겠습니까?', `MaleText_loc4`='血海翻波，城邦倾覆！而我们呢——分裂的世界——怎能对抗大军？', `MaleText_loc5`='血海，廢墟!像我們這樣一個分裂的世界是要如何對抗那樣的軍團?', `MaleText_loc7`='¡Mares de sangre, ciudades en ruinas! ¿Quiénes somos nosotros, un mundo dividido, para enfrentar a una legión?' WHERE `ID`=73556;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망을 말씀하셨죠. 알아 주세요. 다가오는 이 파멸에서 우리가 어떻게든 살아남을 수 있을 거라는 그 한 조각 믿음이, 저를 지탱하는 전부입니다.', `MaleText_loc4`='你就是希望的化身。相信我，正是那一点点熬过灭顶之灾的微小希望在支撑着我。', `MaleText_loc5`='您在談希望。相信我，唯一讓我撐下去的力量就是我們能因某種原因而從即將來臨的毀滅下生存的信念。', `MaleText_loc7`='Tú hablas de esperanza. Créeme, la más mínima creencia de que de alguna forma sobreviviremos a la devastación que se avecina es todo lo que me sostiene.' WHERE `ID`=73557;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전... 감사합니다, 위대한 학이여.', `MaleText_loc4`='我……谢谢你，朱鹤。', `MaleText_loc5`='我...謝謝您，偉大的紅鶴。', `MaleText_loc7`='Yo... te agradezco, Gran Grulla.' WHERE `ID`=73558;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런, 이런, 세계파괴자의 아이로구나. 누구나 구원받을 수 있다는 증거지. 날 찾아와 주어 영광이다.', `MaleText_loc4`='哦，灭世者之子，你证明了众生皆可得到救赎。你的光临令我深感荣幸。', `MaleText_loc5`='哦，是碎界者之子。你的存在證明了沒有無可救贖之人。很榮幸你來拜訪我。', `MaleText_loc7`='Qué sorpresa, el hijo del Rompemundos, la prueba de que nadie está ajeno a la redención. Me honra tu visita.' WHERE `ID`=73559;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말해 보아라, 대지의 수호자의 아들아. 희망의 본질이 무엇이냐?', `MaleText_loc4`='告诉我，大地守护者之子：什么是希望？', `MaleText_loc5`='告訴我，大地守護者之子，什麼是希望?', `MaleText_loc7`='Dime, hijo del Guardián de la Tierra: ¿cuál es la naturaleza de la esperanza? ' WHERE `ID`=73560;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='말뿐이군. 네 말에 의심이 서려 있다.', `MaleText_loc4`='这句话连你自己都不相信。', `MaleText_loc5`='你雖然這麼說，卻懷疑自己的言語。', `MaleText_loc7`='Hablas pero dudas de tus propias palabras. ' WHERE `ID`=73561;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 과소평가하는구나.', `MaleText_loc4`='你太低估我了。', `MaleText_loc5`='你低估我了。', `MaleText_loc7`='Me subestimas.' WHERE `ID`=73562;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일어나라, 데스윙의 아들아. 내 축복을 내려 주겠다. 너는 누구보다도 그 축복이 필요한 자이니.', `MaleText_loc4`='起来吧，死亡之翼之子。我会给你我的祝福，你是我见过的最需要它的人。', `MaleText_loc5`='起來吧，死亡之翼的孩子。我會給你祝福，因為你比我見過的任何人都需要。', `MaleText_loc7`='Levántate, hijo de Alamuerte. Les daré mi bendición; la necesitan más que cualquier otro que haya conocido.' WHERE `ID`=73563;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='희망이란 것을, 모호하고 불투명한 어떤 것으로 생각해선 안 된다.', `MaleText_loc4`='我不赞同你把“希望”看做模糊而且无法想象的未来。', `MaleText_loc5`='我要你別把「希望」想成模糊而難以想像的未來。', `MaleText_loc7`='Los desafío a que no piensen en la esperanza como un futuro vago e inimaginable.' WHERE `ID`=73564;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='매일매일 가슴속에 희망을 품고 살아라. 그럼으로써, 네가 꿈꾸는 미래를 만들어갈 것이니.', `MaleText_loc4`='要怀着希望渡过每一天。如此，方能创造梦想中的未来。', `MaleText_loc5`='每一天都帶著希望活著。這麼做，你才能創造你夢想的未來。', `MaleText_loc7`='Vivan TODOS LOS DÍAS con esperanza en el corazón. Al hacerlo, estarán CREANDO el futuro con el que sueñan. ' WHERE `ID`=73565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 시험을 받겠느냐? 무엇과도 비교할 수 없는 깊은 상처를 치유하는 시험이다.', `MaleText_loc4`='如果你们接受我的挑战的话，就要治愈最惨痛的创伤。', `MaleText_loc5`='我的挑戰，是要考驗你們去治療最嚴重的創傷。', `MaleText_loc7`='Mi desafío, si lo aceptan, será sanar las heridas más severas.  ' WHERE `ID`=73566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='츠지의 시험을 받아들이려면 징을 울리십시오. 네 천신의 시험 중 하나를 통과해야 합니다.', `MaleText_loc4`='敲响挑战之锣以接受赤精的挑战。你只需要从四位至尊天神的挑战中选择一项完成即可。', `MaleText_loc5`='敲響銅鑼接受赤吉的挑戰。你只需要戰勝四位天尊其中一位的挑戰。', `MaleText_loc7`='Haz sonar el gong para aceptar el desafío de Chi-Ji. Solo tienes que superar uno de los cuatro desafíos de los Celestiales.' WHERE `ID`=73567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='징 울리기 [치유 담당자용 시험]', `MaleText_loc4`='敲响挑战之锣[治疗挑战]', `MaleText_loc5`='敲響銅鑼[治療挑戰]', `MaleText_loc7`='Haz sonar el gong [desafío de sanación]', `FemaleText_loc1`='징 울리기 [치유 담당자용 시험]', `FemaleText_loc4`='敲响挑战之锣[治疗挑战]', `FemaleText_loc5`='敲響銅鑼[治療挑戰]', `FemaleText_loc7`='Haz sonar el gong [desafío de sanación]' WHERE `ID`=73568;
