UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 짐마차가 파괴되었습니다.', `MaleText_loc4`='一辆部落货车已被摧毁。', `MaleText_loc5`='部落車隊已被摧毀。', `MaleText_loc7`='Una caravana de la Horda ha sido destruida.' WHERE `ID`=73577;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간 없어!', `MaleText_loc4`='没时间啦！', `MaleText_loc5`='快沒時間了!', `MaleText_loc7`='¡Se acaba el tiempo!' WHERE `ID`=73579;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 유물 좀 빨리 모아 봐!', `MaleText_loc4`='快拿上那些遗物！', `MaleText_loc5`='快搞定那些文物!', `MaleText_loc7`='¡Apresúrense con esos artefactos!' WHERE `ID`=73580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어서 움직여! 여긴 뭔가 좀 이상해.', `MaleText_loc4`='不要停——这地方有点不对劲。', `MaleText_loc5`='快點，這地方有些不對勁。', `MaleText_loc7`='Muévanse... Hay algo raro en este lugar.' WHERE `ID`=73581;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손 대지 마! 그게 뭔지도 모르잖아.', `MaleText_loc4`='别碰它——天知道那是什么东西！', `MaleText_loc5`='別碰，你不知道那是什麼東西!', `MaleText_loc7`='No lo toques... ¡No sabes qué puede ser esa cosa!' WHERE `ID`=73582;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방금 그 괴상망측한 게 대체 뭐였지?', `MaleText_loc4`='那到底是什么邪恶的玩意儿？', `MaleText_loc5`='那個玩意兒到底是什麼鬼東西啊?', `MaleText_loc7`='En el nombre de todo lo que es profano... ¿Qué era ESA COSA?' WHERE `ID`=73583;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허허, 걱정은 하지 마시라니까. 저런 걸 건드리고 싶은 놈이 어디 있겠어? 돈만 받으면 바로 사라져 줄게.', `MaleText_loc4`='别紧张，我想没人愿意再碰那玩意儿了。只要拿到钱，我们马上就离开这儿。', `MaleText_loc5`='噢你不用擔心，我想沒有人會想要再碰那個東西。我只要收到錢就會趕快離開這裡了。', `MaleText_loc7`='Nada de que preocuparse, no creo que alguien quiera volver a tocar esa cosa.  Voy a cobrar nuestro dinero y nos largaremos de aquí.' WHERE `ID`=73584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 어이, 이게 뭐야, 어?! 약속했던 돈의 5분의 1도 안 되잖아!', `MaleText_loc4`='嘿，嘿，怎么回事？这点钱只有说好的一半！', `MaleText_loc5`='喂喂，這是啥?這只有一開始說好的五分之一!', `MaleText_loc7`='Ey, ey, ¿qué es esto? ¡Esto es apenas un quinto del pago prometido!' WHERE `ID`=73585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아냐, 아냐, 계약을 했잖아. 전액 지급하기로...', `MaleText_loc4`='不不，合同上写了，必须全额付清——', `MaleText_loc5`='不對不對，我們有簽合約。全額付款-', `MaleText_loc7`='No, no, tenemos un contrato. El pago completo…' WHERE `ID`=73586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 어디 때가 되면 가로쉬가 어떻게 되나 한번 보자고.', `MaleText_loc4`='是啊，我倒要看看，到时谁还会支持他。', `MaleText_loc5`='對啦，看關鍵時刻是誰會挺卡爾洛斯吧。', `MaleText_loc7`='Sí, ya veremos quién apoya a Garrosh cuando haga falta.' WHERE `ID`=73587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어, 아니, 거 아무것도 아냐. 호드를 위하여! 뭐 그런 거 있잖아. 어, 그러니까... 안녕!', `MaleText_loc4`='噢，呃，没什么，大人。为了部落，就这样。再见！', `MaleText_loc5`='噢沒什麼事，大人。為了部落嘛。掰啦!', `MaleText_loc7`='Ah, sí, no, nada, su enormidad. Por la Horda y todo eso. ¡Adiós! ' WHERE `ID`=73588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='통제 실패. 자체 방어 장치 가동.', `MaleText_loc4`='拦截失败。启动主动防御矩阵。', `MaleText_loc5`='隔離失敗。主動防禦矩陣已開啟。', `MaleText_loc7`='Falla de contención. Matriz de defensa funcional activada.' WHERE `ID`=73589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='침입자 발견. 모든 안전 장치 해제.', `MaleText_loc4`='安全漏洞。禁用所有安全协议。', `MaleText_loc5`='保全系統被突破。所有安全機制已關閉。', `MaleText_loc7`='Violación de seguridad.  Todos los protocolos de seguridad desactivados.' WHERE `ID`=73590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='동력부 가동.', `MaleText_loc4`='激活动力装置。', `MaleText_loc5`='動力組件已啟動。', `MaleText_loc7`='Unidades de potencia activadas.' WHERE `ID`=73591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최대 동력 도달.', `MaleText_loc4`='达到最大功率。', `MaleText_loc5`='已達到最大動力。', `MaleText_loc7`='Potencia máxima alcanzada.' WHERE `ID`=73592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강탈자가 남긴 장난감이여... 너도 먼지와 다름없다.', `MaleText_loc4`='不过是篡位者留下的小玩意儿……你们，也就是一小撮尘埃。', `MaleText_loc5`='篡位者留下的玩物。你，也只是塵埃。', `MaleText_loc7`='Un simple juguete dejado por el usurpador... Tú... también... eres polvo.' WHERE `ID`=73593;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 피가 굶주렸다.', `MaleText_loc4`='我的鲜血饥渴难耐了。', `MaleText_loc5`='我的血十分飢渴。', `MaleText_loc7`='Mi sangre ansía.' WHERE `ID`=73594;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통은 내 먹이다.', `MaleText_loc4`='我将畅享苦难。', `MaleText_loc5`='我以苦難為食。', `MaleText_loc7`='Me hago un festín del sufrimiento.' WHERE `ID`=73595;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 고통이 내게 힘을 준다.', `MaleText_loc4`='你的挣扎只会让我精神百倍。', `MaleText_loc5`='你們的痛苦使我清醒。', `MaleText_loc7`='Tu agonía me rejuvenece.' WHERE `ID`=73596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 날 풀어줘라...', `MaleText_loc4`='释放……我……', `MaleText_loc5`='釋放...我...', `MaleText_loc7`='Libéra... me…' WHERE `ID`=73597;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 증오가 날 강하게 한다!', `MaleText_loc4`='仇恨让我更加强大！', `MaleText_loc5`='你們的仇恨使我強大!', `MaleText_loc7`='¡Tu odio me da fuerzas!' WHERE `ID`=73598;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 이렇게 아름다운 고통이라니!', `MaleText_loc4`='噢，如此……强烈的……痛苦！', `MaleText_loc5`='噢...如此劇烈...的痛苦!', `MaleText_loc7`='Ah, ¡qué... dolor... tan exquisito!' WHERE `ID`=73599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 잠을 잘 뿐이다.', `MaleText_loc4`='我只是再次沉睡。', `MaleText_loc5`='我只是沈睡。', `MaleText_loc7`=' Duermo, nada más.' WHERE `ID`=73600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='손대지 마라, 고블린. 대족장님께서 여기서 찾아오라고 하신 유물이다. 코르크론이 직접 보호하겠다.', `MaleText_loc4`='让开，地精。这个遗物正是酋长要找的东西。从现在起，它受库卡隆的保护。', `MaleText_loc5`='走開，哥布林。這個神器正是大酋長想找的東西。現在開始它受到柯爾克隆的保護了。', `MaleText_loc7`='A un lado, goblin. Este artefacto es exactamente lo que el Jefe de Guerra esperaba encontrar aquí. Lo pondré bajo la protección de Kor''kron. ' WHERE `ID`=73601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돈은 남아 있는 놈들만 받는 거다. 대족장님께서는 죽은 것들 따위는 인정하지 않으신다.', `MaleText_loc4`='这是按出勤的工人算的，工头。酋长可不会付钱给死人。', `MaleText_loc5`='貨款只付給活著的工人，工頭。大酋長不會付錢給死者。', `MaleText_loc7`='Se te paga por todos los trabajadores presentes, Supervisor. El Jefe de Guerra no compensa a los muertos.' WHERE `ID`=73602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 이런 것들이 우리 호드의 본질을 흐려 놓은 거다.', `MaleText_loc4`='你！就是你这种人让我们高贵的部落死气沉沉！', `MaleText_loc5`='這個。這就是我們珍愛的部落活力喪失的原因。', `MaleText_loc7`='ESTO. Esto es lo que ha diluido la vitalidad de nuestra preciosa Horda. ' WHERE `ID`=73603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님께서는 죽은 자들의 가족도 너그러이 받아 주신다. 호드를 섬기다 죽는 건 커다란 영광이거늘, 너희 족속들은 그 더러운 주머니를 채우려고만 하고 있구나!', `MaleText_loc4`='酋长都慷慨允许死者家属住进他的城市了。为部落而死本就是无上的荣誉，可是你却只想趁机再捞一笔！', `MaleText_loc5`='大酋長仁慈地允許死者的家屬住在他的城裡。為了部落而死應該是莫大的榮譽，但你只把它當成填滿你骯髒口袋的機會!', `MaleText_loc7`='El Jefe de Guerra permite gentilmente que las familias de los muertos vivan en su ciudad. Morir al servicio de la Horda debería ser un gran honor, ¡pero TÚ lo ves como otra oportunidad de llenar tus bolsillos sucios!' WHERE `ID`=73604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 네놈들이 역겹다. 작고, 약하고, 도둑놈들처럼 명예라고는 모르지. 대족장님이 너희를 내버려 두시는 걸 다행으로 생각해라.', `MaleText_loc4`='你们让我恶心。瘦小，懦弱，像小偷一样不知廉耻，感谢酋长容忍你们存在吧！', `MaleText_loc5`='你們的種族讓我噁心。瘦小。虛弱。跟小偷一樣不要臉。大酋長還容忍你們在這裡，你們就該心存感謝。', `MaleText_loc7`='Tu especie me da asco. Pequeña. Débil. Sin honor, como los ladrones. Agradece que el Jefe de Guerra siquiera tolera su presencia.' WHERE `ID`=73605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐라고 했나, 고블린?!', `MaleText_loc4`='你在说什么，地精！？', `MaleText_loc5`='你說什麼，哥布林!?', `MaleText_loc7`='¡¿Qué dijiste, goblin?!' WHERE `ID`=73606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 어마어마한 |cFFFF2222|Hspell:141187|h[수직 베기]|h|r를 준비합니다.', `MaleText_loc4`='%s正准备发出一招强力的|cFFFF2222|Hspell:141187|h[竖劈]|h|r。', `MaleText_loc5`='%s準備發動一記強力的|cFFFF2222|Hspell:141187|h[垂直斬擊]|h|r。', `MaleText_loc7`='%s prepara un brutal |cFFFF2222|Hspell:141187|h[golpe vertical]|h|r.' WHERE `ID`=73607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리야말로 진정한 호드다!', `MaleText_loc4`='我们才是真正的部落！', `MaleText_loc5`='我們才是正統部落!', `MaleText_loc7`='¡La nuestra es la verdadera Horda!', `FemaleText_loc1`='우리야말로 진정한 호드다!', `FemaleText_loc4`='我们才是真正的部落！', `FemaleText_loc5`='我們才是正統部落!', `FemaleText_loc7`='¡La nuestra es la verdadera Horda!' WHERE `ID`=73608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들이야말로 반역자다!', `MaleText_loc4`='你们都是叛徒！', `MaleText_loc5`='你們全是一群叛徒!', `MaleText_loc7`='¡USTEDES son los traidores!', `FemaleText_loc1`='네놈들이야말로 반역자다!', `FemaleText_loc4`='你们都是叛徒！', `FemaleText_loc5`='你們全是一群叛徒!', `FemaleText_loc7`='¡USTEDES son los traidores!' WHERE `ID`=73609;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족의 짐승들은 마땅히 진압해야 한다!', `MaleText_loc4`='暗矛部族的畜生都将卑贱地死去！', `MaleText_loc5`='這些暗矛畜生會被我們宰殺殆盡!', `MaleText_loc7`='¡Las bestias Lanza Negra serán ajusticiadas como la escoria que son!', `FemaleText_loc1`='검은창 부족의 짐승들은 마땅히 진압해야 한다!', `FemaleText_loc4`='暗矛部族的畜生都将卑贱地死去！', `FemaleText_loc5`='這些暗矛畜生會被我們宰殺殆盡!', `FemaleText_loc7`='¡Las bestias Lanza Negra serán ajusticiadas como la escoria que son!' WHERE `ID`=73610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님을 위하여!', `MaleText_loc4`='为了地狱咆哮！', `MaleText_loc5`='為了地獄吼!', `MaleText_loc7`='¡Por Grito Infernal!', `FemaleText_loc1`='헬스크림 님을 위하여!', `FemaleText_loc4`='为了地狱咆哮！', `FemaleText_loc5`='為了地獄吼!', `FemaleText_loc7`='¡Por Grito Infernal!' WHERE `ID`=73611;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애초부터 검은창 부족은 호드의 일원이 될 자격이 없었다!', `MaleText_loc4`='暗矛部族根本不配加入部落！', `MaleText_loc5`='暗矛氏族從來不配為部落的一份子!', `MaleText_loc7`='¡Los Lanza Negra nunca fueron dignos de pertenecer a la Horda!', `FemaleText_loc1`='애초부터 검은창 부족은 호드의 일원이 될 자격이 없었다!', `FemaleText_loc4`='暗矛部族根本不配加入部落！', `FemaleText_loc5`='暗矛氏族從來不配為部落的一份子!', `FemaleText_loc7`='¡Los Lanza Negra nunca fueron dignos de pertenecer a la Horda!' WHERE `ID`=73612;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님께 네놈의 머리를 가져가겠다!', `MaleText_loc4`='我要将你的脑袋献给加尔鲁什！', `MaleText_loc5`='我要拿你的頭獻給卡爾洛斯!', `MaleText_loc7`='¡Le llevaré tu cabeza a Garrosh!', `FemaleText_loc1`='가로쉬 님께 네놈의 머리를 가져가겠다!', `FemaleText_loc4`='我要将你的脑袋献给加尔鲁什！', `FemaleText_loc5`='我要拿你的頭獻給卡爾洛斯!', `FemaleText_loc7`='¡Le llevaré tu cabeza a Garrosh!' WHERE `ID`=73613;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='감히 대족장님을 배신하다니!', `MaleText_loc4`='你背叛了酋长！', `MaleText_loc5`='你背叛了大酋長!', `MaleText_loc7`='¡Has traicionado al Jefe de Guerra!', `FemaleText_loc1`='감히 대족장님을 배신하다니!', `FemaleText_loc4`='你背叛了酋长！', `FemaleText_loc5`='你背叛了大酋長!', `FemaleText_loc7`='¡Has traicionado al Jefe de Guerra!' WHERE `ID`=73614;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족과 내통하는 모든 자들에게 죽음을!', `MaleText_loc4`='暗矛部族的同谋犯都将被处死！', `MaleText_loc5`='暗矛部族的同黨全都得死!', `MaleText_loc7`='¡Todo el que conspire con los Lanza Negra lo pagará con su vida!', `FemaleText_loc1`='검은창 부족과 내통하는 모든 자들에게 죽음을!', `FemaleText_loc4`='暗矛部族的同谋犯都将被处死！', `FemaleText_loc5`='暗矛部族的同黨全都得死!', `FemaleText_loc7`='¡Todo el que conspire con los Lanza Negra lo pagará con su vida!' WHERE `ID`=73615;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='레이피어가 바닥에 떨어졌습니다. 레이피어를 들고 제독 해그먼과 싸우십시오!', `MaleText_loc4`='细剑掉在了地上。快将它捡起来以对付海军上将哈格曼！', `MaleText_loc5`='細劍掉到地上。拾起它與海格曼上將並肩作戰!', `MaleText_loc7`='El estoque se ha caído al suelo. ¡Hay que recogerlo para enfrentarse al almirante Hagman!', `FemaleText_loc1`='레이피어가 바닥에 떨어졌습니다. 레이피어를 들고 제독 해그먼과 싸우십시오!', `FemaleText_loc4`='细剑掉在了地上。快将它捡起来以对付海军上将哈格曼！', `FemaleText_loc5`='細劍掉到地上。拾起它與海格曼上將並肩作戰!', `FemaleText_loc7`='El estoque se ha caído al suelo. ¡Hay que recogerlo para enfrentarse al almirante Hagman!' WHERE `ID`=73616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장이 검은창 부족을 배신한 것은 큰 실수였네. 그는 호드를 갈가리 찢어 놓았어.', `MaleText_loc4`='酋长真不该去惹暗矛部族。他害得部落四分五裂了。', `MaleText_loc5`='大酋長真不該去招惹暗矛氏族。部落的分裂都是他造成的。', `MaleText_loc7`='El Jefe de Guerra no debería haber enfadado a los Lanza Negra. Ha dividido a la Horda.' WHERE `ID`=73617;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 우리를 해치지 말게! 볼진의 저항군에게 주둔할 장소를 기꺼이 제공하겠네.', `MaleText_loc4`='拜托——别伤害我们！我们完全欢迎沃金把起义军驻扎在这里。', `MaleText_loc5`='拜託，別傷害我們!歡迎沃金的起義兵們駐紮在這裡。', `MaleText_loc7`='¡Por favor, no nos hagan daño! Los revolucionarios de Vol''jin pueden asentarse aquí.' WHERE `ID`=73618;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 랩터들의 원수를 갚아주마!', `MaleText_loc4`='你要为自己对我的迅猛龙所做的一切付出代价！', `MaleText_loc5`='你要為我的迅猛龍付出代價!', `MaleText_loc7`='¡Vais a pagar por lo que les habéis hecho a mis raptores!' WHERE `ID`=73619;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 수 백 명의 젊은 전사들을 훈련시켰네. 하지만 대족장은 아무 거리낌 없이 그들에게 피를 흘릴 것을 명령했지. 나는 이제 그를 대족장으로 여기지 않겠네.', `MaleText_loc4`='我训练了数百名年轻战士。酋长却在让他们白白流血。他不再是“我的酋长”了。', `MaleText_loc5`='我辛辛苦苦調教出那些年輕的戰士們，大酋長卻隨手便將他們送上戰場。我再也不承認這位大酋長。', `MaleText_loc7`='He entrenado a cientos de jóvenes guerreros. El Jefe de Guerra derrama su sangre de forma temeraria. Ya no es MI Jefe de Guerra.' WHERE `ID`=73620;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 칼날을 "대족장"에게 들이미는 것은 상관없네. 하지만 타락한 그의 일당만을 공격하겠네. 민간인들이 피를 흘리는 일은 없어야 하네!', `MaleText_loc4`='你可以让我对“酋长”拔刀相向，但我只对付他手下那些堕落的战士——不要伤害平民！', `MaleText_loc5`='我願意討伐那位「大酋長」，但是我只對付他那群腐化的士兵。別傷害無辜的老百姓!', `MaleText_loc7`='Podrás hacer que mi acero se vuelva contra el "Jefe de Guerra", pero tan solo contra sus soldados corruptos. ¡Deja a los civiles al margen de este derramamiento de sangre!' WHERE `ID`=73621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 봄베이를 믿게나! 그가 길을 안다네!', `MaleText_loc4`='跟老波贝来！他认识路！', `MaleText_loc5`='跟著波貝!波貝知道路!', `MaleText_loc7`='¡Sigue al viejo Bom''bay! ¡Él conoce el camino!' WHERE `ID`=73622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 목재 더미가 무너져 내렸습니다!', `MaleText_loc4`='一辆满载木材的库卡隆货车倾覆了！', `MaleText_loc5`='載運柯爾克隆木材物資的運輸車翻覆了!', `MaleText_loc7`='¡Un cargamento de madera Kor''kron ha volcado!' WHERE `ID`=73623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 석유통이 무너져 내렸습니다!', `MaleText_loc4`='一辆满载原油的库卡隆货车倾覆了！', `MaleText_loc5`='載運柯爾克隆之油物資的運輸車翻覆了!', `MaleText_loc7`='¡Un cargamento de aceite Kor''kron ha volcado!' WHERE `ID`=73624;
