UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 여기서 계속 이렇게 죽치고 서 있으면 얼마 안 가서 가로쉬의 부하들이 우릴 찾아낼 거라고.', `MaleText_loc4`='我们在这里停留的越久，加尔鲁什的人就越有可能发现我们。', `MaleText_loc5`='我們在這裡耗越久，卡爾洛斯的手下就越可能找到我們。', `MaleText_loc7`='Cuanto más tiempo nos pasemos aquí parados, antes nos encontrarán los hombres de Garrosh.' WHERE `ID`=73648;
