UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='대족장님이 언짢아하실 것이다. 그분은 지금 소중한 병력을 동원해서 이 보잘것없는 반란을 막아내고 계시니까.', `FemaleText_loc4`='酋长会生气的。他把宝贵的军队都拿来抵御那些可悲的起义军了。', `FemaleText_loc5`='大酋長會不高興的。他的珍貴部隊正浪費在對付那些可悲的叛軍上。', `FemaleText_loc7`='El Jefe de Guerra se va a disgustar. Está desperdiciando valiosas tropas en frenar su patética rebelión.' WHERE `ID`=73652;
