UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 이번 일로 눈먼 힘에는 한계가 있다는 걸 깨달았으면 좋겠구나. 세상을 바꾸는 것과 옳은 일을 하는 것이 같다고 생각해선 안 된다.', `MaleText_loc4`='我希望你能明白，缺乏指引的力量是狭隘的。改变世界是一回事，但做正确的事就是另一回事了。', `MaleText_loc5`='我相信你現在懂得盲目力量的極限所在。想改變世界是一回事，但是做正確的事則不同。', `MaleText_loc7`='Espero que ahora entiendas los límites de la fuerza sin la visión. Una cosa es cambiar el mundo pero otra muy distinta es hacer lo correcto.' WHERE `ID`=73658;
