UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 적의 힘과 자신감을 너의 무기로 이용해야 한다. 너를 믿는다.', `MaleText_loc4`='勇士，你应该利用敌人的力量和自信来对付他。我相信你。', `MaleText_loc5`='勇士，使用你敵人的力量和信心對付他。我相信你做得到。', `MaleText_loc7`='Usa la fuerza y la confianza de tu enemigo en su contra. Yo creo en ti.' WHERE `ID`=73664;
