UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드, 순수한 호드를 막을 순 없다!', `MaleText_loc4`='真正的部落，纯粹的部落，是不可阻挡的！', `MaleText_loc5`='沒有人能抵擋正統的部落、真正的部落!', `MaleText_loc7`='¡Nadie puede detener a la verdadera Horda, la Horda pura!' WHERE `ID`=73680;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아제로스 전체가 열등한 종족의 피로 붉게 물들 것이다.', `MaleText_loc4`='下等种族的鲜血将染红整个艾泽拉斯。', `MaleText_loc5`='下等種族的鮮血將染紅整片艾澤拉斯。', `MaleText_loc7`='Todo Azeroth se teñirá de rojo con la sangre de las razas inferiores.' WHERE `ID`=73681;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들을 처치하라! 호드를 위하여!', `MaleText_loc4`='消灭他们！为了部落！', `MaleText_loc5`='消滅他們!為了部落!', `MaleText_loc7`='¡Acaben con ellos! ¡POR LA HORDA!' WHERE `ID`=73682;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='신병들, 너희가 유일하게 싸울 수 있는 병력이라고!', `MaleText_loc4`='新兵，现在只有你还能战斗了！', `MaleText_loc5`='各位新兵，現在只剩你們能作戰了!', `MaleText_loc7`='¡Reclutas, son los únicos que quedan que pueden luchar!' WHERE `ID`=73683;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동기가 준비될 때까지 우리를 지켜줘!', `MaleText_loc4`='在传送器准备就绪前，保护好我们！', `MaleText_loc5`='在傳送門準備好之前保護我們!', `MaleText_loc7`='¡Hay que mantenerlos a raya hasta que el teletransportador esté listo!' WHERE `ID`=73684;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF0000|Hspell:141387|h[울타지스의 방패]|h|r가 파괴되었습니다!', `MaleText_loc4`='|cFFFF0000|Hspell:141387|h[乌萨吉之盾]|h|r被击破了！', `MaleText_loc5`='|cFFFF0000|Hspell:141387|h[厄薩寂的護盾]|h|r破了!', `MaleText_loc7`='¡|cFFFF0000|Hspell:141387|h[Escudo de Urtharges]|h|r se ha roto!' WHERE `ID`=73685;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 상자에는 코르크론의 표식이 있습니다. 여러 종류의 무기와 전쟁 물자가 동굴 여기저기에 흩어져 있습니다. 주변 상황을 고려해볼 때, 가로쉬는 전쟁을 준비하는 듯합니다.', `MaleText_loc4`='这些箱子上有库卡隆的印记。山洞里摆满了各种武器和其他战略物资。从这些东西来看，加尔鲁什正在策划一场入侵。', `MaleText_loc5`='這些木箱上頭有柯爾克隆的標誌。各式各樣的武器與戰爭補給品散落在洞穴裡。從這些東西看來，卡爾洛斯正策劃發動一場侵略行動。', `MaleText_loc7`='Estos cajones llevan la marca de los Kor''kron. Varias armas y otros suministros de guerra están desperdigados por la cueva. Por lo que parece, Garrosh está planeando una invasión.' WHERE `ID`=73686;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 |cFFFF2222|Hspell:132998|h[점착 폭탄]|h|r을 붙였습니다!', `MaleText_loc4`='%s在你身上放置了|cFFFF2222|Hspell:132998|h[黏性炸弹]|h|r！', `MaleText_loc5`='%s在你身上放了一個|cFFFF2222|Hspell:132998|h[黏性炸彈]|h|r!', `MaleText_loc7`='¡%s te ha puesto una |cFFFF2222|Hspell:132998|h[Bomba pegajosa]|h|r!' WHERE `ID`=73687;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='원시비룡 알들이 동굴 바닥에 늘어서 있습니다. 주변에는 최근 원시비룡이 부화한 것처럼 보이는 알이 잔뜩 있습니다. 이렇게 많은 원시비룡과 함께라면 가로쉬가 침략할 때 안전한 곳은 하나도 없을 것입니다.', `MaleText_loc4`='山洞里整齐地码放着始祖龙蛋。周围散落着许多刚刚孵化的蛋。有了这么多始祖龙，加尔鲁什的入侵足以威胁到任何地方。', `MaleText_loc5`='洞穴的地面上排滿了新生的元龍蛋，周圍遍布著剛孵化完的蛋殼。在這麼多元龍的幫助之下，沒有任何地方能夠抵抗卡爾洛斯的侵略。', `MaleText_loc7`='El suelo de la cueva está plagado de huevos de protodraco. Hay muchos huevos eclosionados recientemente en la zona. Con todos estos protodracos, no habrá lugar seguro ante la invasión de Garrosh.' WHERE `ID`=73688;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버려진 것 같은 유물들이 많이 놓여 있습니다. 유물 대부분은 영원꽃 골짜기에 있는 가로쉬의 발굴현장에서 가져온 것으로 보입니다. 가로쉬가 발굴지에서 무엇을 찾으려는 것인지는 모르겠지만, 이 버려진 유물 중에는 없었던 것 같습니다', `MaleText_loc4`='这里放着许多遗物，似乎都已经被丢弃了。大部分好像都是来自加尔鲁什在锦绣谷的挖掘场。无论他想在那里找到什么，看来都不包括这些被遗忘的文物。', `MaleText_loc5`='這裡有許多古文物，似乎是被人遺棄在這裡的，而其中絕大部分來自卡爾洛斯在恆春谷的挖掘場。無論他在找的是什麼，至少不是這些被丟棄的古老文物。', `MaleText_loc7`='Hay muchos artefactos tirados, parecen abandonados. Todos parecen provenir de la excavación de Garrosh en el Valle de la Flor Eterna. Sea lo que sea que está buscando, no parece que se encuentre entre estas reliquias olvidadas.' WHERE `ID`=73689;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진이 아무 말 없이 자신의 창을 땅에 꽂습니다.', `MaleText_loc4`='沃金将长矛插入地下，沉默不语。', `MaleText_loc5`='沃金把長矛插在地上，什麼話也沒說。', `MaleText_loc7`='Vol''jin clava su lanza en el suelo sin mencionar palabra.' WHERE `ID`=73690;
