UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='희귀한 도전장을 찾았나요? 제게 가져오면 수집품에 추가해 드리죠.', `FemaleText_loc4`='你最近有找到什么稀有卡牌吗？把它们带给我，我可以把它们加入我的藏品里去。', `FemaleText_loc5`='最近有拿到任何稀有的挑戰卡嗎?要是你帶來給我的話，我可以把它們加到收藏區裡。', `FemaleText_loc7`='¿Has encontrado alguna carta rara últimamente? Tráemelas y las añadiré a la colección.' WHERE `ID`=73713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도전장을 사고 싶습니다.', `MaleText_loc4`='我想买一张挑战卡牌。', `MaleText_loc5`='我想買一張挑戰卡。', `MaleText_loc7`='Me gustaría comprar una carta de desafío.', `FemaleText_loc1`='도전장을 사고 싶어요.', `FemaleText_loc4`='我想买一张挑战卡牌。', `FemaleText_loc5`='我想買一張挑戰卡。', `FemaleText_loc7`='Me gustaría comprar una carta de desafío.' WHERE `ID`=73714;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가 적을 쓰러뜨릴 때 검이나 마법 따윈 필요하지 않습니다. 다음 도전자, 헥소스는 끝내주는 기하학의 힘으로 적을 제압하니까요!', `FemaleText_loc4`='接下来这位，他无需刀剑与魔法就能打败敌人。我们的下一个挑战者，海克索斯，使用强大的几何之力克敌制胜的战士！', `FemaleText_loc5`='他不需要靠劍或魔法來打敗敵人。下一位挑戰者大眼怪會用驚奇的幾何學進行戰鬥!', `FemaleText_loc7`='No le hacen falta armas ni magia para derrotar a sus enemigos. ¡Nuestro siguiente contendiente, Hexos, se enfrenta a sus enemigos con los alucinantes poderes de la GEOMETRÍA!' WHERE `ID`=73715;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='새가슴이라고 만만히 보지 마십시오. 사실 싸움 좀 하는 친구거든요. 타이슨 샌더스를 소개합니다!', `FemaleText_loc4`='虽然他就像是一只大公鸡，但他仍然要奋勇战斗。他就是，泰森·山德士！', `FemaleText_loc5`='雖然他就像是一隻雞，一隻巨大的雞，但是他打起架可毫不馬虎。歡迎泰森·桑德斯上場!', `FemaleText_loc7`='Puede que no sea más que una enorme gallina, pero no dará la batalla por perdida. ¡Es Tyson Sanders!' WHERE `ID`=73716;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그에겐 두 가지 모드 밖에 없습니다. 그런데 두 모드 다 "살인"용이라죠? T440을 위해 우리 모두 박수!', `FemaleText_loc4`='他有两种模式，每一种都被贴上了“屠夫”的标签。让我们欢迎，T440！', `FemaleText_loc5`='「是誰具有兩種『殺殺殺』模式可供切換?沒錯，現在歡迎T440登場!」', `FemaleText_loc7`='Tiene dos modos. Y en ambos modos el objetivo es "MATAR". ¡Un aplauso para T440!' WHERE `ID`=73717;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='바싹 구워진 싸움꾼들이 마음에 드실지 모르겠네요! 무연탄 정령을 소개합니다!!', `FemaleText_loc4`='但愿大家都喜欢自己的拳手特脆饼干！现在进场的是，硬煤！！', `FemaleText_loc5`='大家喜不喜歡香脆可口的鬥陣香酥脆?現在無煙煤要登場啦!!', `FemaleText_loc7`='¡Espero que les gusten sus contendientes bien crujientes! ¡¡Aquí viene Antracita!!' WHERE `ID`=73718;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그냥 폭탄보다 좋은 건 뭘까요? 당연히 더 큰 폭탄이겠죠! 이번 상대는 두두둥 쾅입니다!!', `FemaleText_loc4`='还有什么能比一场大爆炸更刺激呢？那当然是，很多很多大爆炸！这边进场的是，大型雷震天！！', `FemaleText_loc5`='有什麼東西比爆炸更讚?沒錯，那就是超多超多的爆炸!在這個角落登場的，正是大轟噠彈!!', `FemaleText_loc7`='¿Qué hay mejor que una explosión? Un montón de explosiones! ¡¡En esta esquina, Gran Badabum!!' WHERE `ID`=73719;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아... 이 작고 깜찍한 뱀 좀 보십시오. 야금뱀입니다! 요놈이 당신 발가락을 야금야금 깨물게 놔둬 보세요. 그냥 무슨 일이 일어나는지 한 번 보자고요.', `FemaleText_loc4`='噢……看看这条可爱的小蛇，噬人蛇！上啊，让它咬一口你的脚趾。让我们看看会发生什么事。', `FemaleText_loc5`='啊...看看這條小可愛，囓屍大蛇來啦!上吧，讓牠一點一點咬掉你的腳趾頭。咱們來看看事情接下來會如何發展。', `FemaleText_loc7`='Oh, miren a esta asombrosa serpiente: ¡Níbilis! Vamos, deja que se te acerque. A ver qué pasa.' WHERE `ID`=73720;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 의사는 아닙니다. 하지만 적의 얼굴을 예쁘게 손봐주시겠다는군요! 다음 상대를 소개합니다! 의사 갈퀴손!', `FemaleText_loc4`='他不是真正的医生，但他将要给他的下一个对手做点整容手术。让我们欢迎，铁拳医师！', `FemaleText_loc5`='雖然他不是真正的醫生，不過他要來動些面部重建手術。當然是幫他的對手動手術啦。讓我們歡迎拳頭醫師!', `FemaleText_loc7`='No es doctor de verdad, pero va a intentar llevar a cabo cirugía de reconstrucción facial... en su próximo adversario. ¡Bienvenido, Doctor Zarpas!' WHERE `ID`=73721;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='복덩이의 먼지를 터십시오. 이번엔 복이 필요할테니까요. 이번 상대는 할아범 투덜피리입니다!', `FemaleText_loc4`='擦亮你的幸运符吧，你会用得上它的。接下来进场的是，老爹土笛子！', `FemaleText_loc5`='拍拍幸運星，因為你接下來真的需要點運氣。歡迎寶笛爺爺!', `FemaleText_loc7`='Sácale brillo al grisgrís, porque te va a hacer falta. ¡Es el abuelo Chiriflauta!' WHERE `ID`=73722;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놀라운 우리 도전자의 모습, 감히 말로 형언할 수 없군요. 곰과 달곰한 아가씨를 보고 마음껏 즐겨 주십시오!', `FemaleText_loc4`='接下来这对挑战者难以用语言来形容。就请大家自己好好欣赏吧，巨熊与淑女！', `FemaleText_loc5`='沒有任何開場白能為我們挑戰者辯駁，睜大雙眼，熊與夫人出場啦!', `FemaleText_loc7`='No hay presentación posible que haga justicia a nuestros próximos contendientes. ¡Disfrutad del Oso y la Doncella!' WHERE `ID`=73723;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠시 무기는 내려놓고 장갑을 끼세요. 간만에 권투 시합이 벌어질 예정입니다. 타이타르에게 한 방 맞을 준비를 하십시오!', `FemaleText_loc4`='扔掉你的武器，拿起拳套吧。接下来将有一场精彩的传统拳击赛。做好被泰塔尔击倒的准备吧！', `FemaleText_loc5`='放下手上的武器，戴上拳擊手套，來場老派的拳擊比賽!準備感受泰薩爾帶來的震撼!', `FemaleText_loc7`='Tira el arma y ponte unos guantes. Ha llegado el momento de disfrutar de un poco de boxeo clásico. ¡Prepárate a besar el suelo ante Ty''thar!' WHERE `ID`=73724;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이곳 싸울가르 투기장에서 모셨던 싸움꾼 중 가장 무시무시한 자가 아닐까 싶습니다. 불행하게도, 여긴 그가 놀던 물이 아니라는군요. 여러분, 모두 서슬아귀를 위해 건배!', `FemaleText_loc4`='他可能是我们搏击俱乐部有史以来最危险的拳手。遗憾的是，他的元素好像有点不够用了。请大家举杯欢迎，锋齿！', `FemaleText_loc5`='他可說是鬥陣俱樂部有史以來最危險的對手。不幸的是，就是腦袋少根筋。大家舉杯，敬獰齒鯊!', `FemaleText_loc7`='Puede que se trate del luchador más mortífero que hemos tenido en el Club de Lucha. Por desgracia, no está en su elemento. ¡Levanten sus jarras por Muecafilada!' WHERE `ID`=73725;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='싸울가르 투기장의 역전용사분들은 자가복제 수액괴물 브랏을 기억하실 겁니다. 오늘! 여러분께 그보다 훨씬 가혹하고, 못 생긴 누나, 스플랏을 소개합니다!', `FemaleText_loc4`='搏击俱乐部的老手们可能还记得那个能自我复制的软泥怪，布拉特。今天，我们将迎来他这位更卑鄙、更丑陋的姐姐：斯普拉特！', `FemaleText_loc5`='在鬥陣競技場待過一段時間的老手應該還記得會自我複製的吞齧怪吧?今天來到現場的，是他那更醜更老更難纏的姊姊:血泥怪!', `FemaleText_loc7`='Los veteranos de Liza''gar recordarán a Blat, el moco replicante. Hoy nos enfrentamos con su hermana mayor, más mala y más fea: ¡Splat!' WHERE `ID`=73726;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이게 누구야? 브루스가 돌아왔습니다! 더 힘세고 강해져서 돌아온 브루스! 기계브루스입니다!', `FemaleText_loc4`='这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！！', `FemaleText_loc5`='咦，怎麼回事?布魯斯回來了!更強、更壯、更快!機械布魯斯!!喔耶!!', `FemaleText_loc7`='¿Pero qué es esto? ¡Bruce ha vuelto! ¡Un Bruce mejor, más rápido y más fuerte! ¡Es MECA-BRUCE! ¡¡Yujuuuu!!' WHERE `ID`=73727;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='머리가 없습니다. 팔꿈치도 없습니다. 하지만 누가 뭐래도 그는 뛰어난 전술가입니다! 여러분, 묵치파를 소개합니다! 박수!', `FemaleText_loc4`='他是一位战略大师，他甚至都没有脑袋，也没有肘子。他就是，猜拳手！让我们为他拍拍手吧！', `FemaleText_loc5`='這是名戰略專家，雖然連顆腦袋或根眉毛都沒有。讓我們為剪刀石頭布歡呼!', `FemaleText_loc7`='Es un genio de la estrategia, y ni siquiera tiene cerebro. Claro que tampoco tiene codos. ¡Es Ro Shambo! ¡Un aplauso!' WHERE `ID`=73728;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리가 한물 간 로봇들로 뭘 하냐고요? 당연히 유혈이 난무하는 검투사 투기장으로 보내 죽을 때까지 싸우게 하죠! 여러분, 블링트론 3000입니다!', `FemaleText_loc4`='想知道我们是怎么处理报废机器人的吗？当然是把他们送到血腥的竞技场来送死了！现在进场的是，布林顿3000！', `FemaleText_loc5`='你是否想過，要怎麼處理不要的機器人?當然是派它們到血腥的競技場送死呀!歡迎布靈登3000型登場!', `FemaleText_loc7`='¿Se han preguntado alguna vez qué se hace con los robots obsoletos? Los mandamos a morir a sangrientas arenas de gladiadores, por supuesto. ¡Aquí está Joyatrón 3000!' WHERE `ID`=73729;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그는 자신이 이기지 못할 상대는 본 적이 없습니다. 아, 정정하겠습니다. 그는 상대를 본 적이 없습니다. 눈먼 영웅을 소개합니다!', `FemaleText_loc4`='他从未见过战胜不了的对手。啊，小小地纠正一下：应该说，他从未见过对手。他就是，盲眼英雄！', `FemaleText_loc5`='他從未見過打不過的對手。啊，稍微更正一下，他從未見過任何對手，因為他是盲大俠!', `FemaleText_loc7`='Oponente que ve, oponente que machaca. Bueno, técnicamente, nunca ha visto a un oponente. ¡Es el héroe ciego!' WHERE `ID`=73730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅이여, 다시 만나니 반갑군. 지금 너무도 많은 일들이 벌어지고 있어서, 전승지기인 나조차도 모두 기억할 수가 없네. 나도 꿈결 맥주를 통해 많은 것을 보았지만, 자네와 같은 강인한 용사가 역사의 다음 장을 써내려가는 일을 도와줘야 하네.', `MaleText_loc4`='很高兴见到你，我的朋友。最近发生了太多事情，让我这样的游学者都觉得目不暇接了。我已经通过洄梦仙酒看到了许多事件，但我们还需要像你这样的英雄来帮忙书写新的历史篇章。', `MaleText_loc5`='很高興見到你，朋友。即使是我們這些博學行者，也難以掌握瞬息萬變的歷史。雖然我能夠借助夢幻之釀來窺探各地發生的事物，但我們仍然需要像你這樣的英雄來幫歷史寫下全新的章節。', `MaleText_loc7`='Me alegro de verte. Están sucediendo tantas cosas que a un eremita como yo le cuesta seguir el ritmo. He visto muchas cosas mediante mi brebaje de ensueño, pero necesitaremos a $gun héroe:una heroína; como tú para escribir el siguiente capítulo de nuestra historia.' WHERE `ID`=73731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 음료에서 퍼져 나오는 향기를 맡다 보니, 입에 침이 고이고 마치 최면에 걸릴 것만 같습니다.$b$b(아이템 레벨이 425 또는 그 이상인 플레이어만 이 시나리오를 수행할 수 있습니다.)', `MaleText_loc4`='这种令人口水直流的美酒散发着一股令人迷醉的香气。$b$b（下列场景战役要求物品等级不低于425级）', `MaleText_loc5`='這個令人垂涎三尺的美酒散發出的香味，擁有近乎催眠人心的魔力。$b$b(事件需要425以上的物品等級。)', `MaleText_loc7`='Este brebaje tan apetecible desprende un aroma casi hipnótico.$b$b(Las gestas requieren nivel de objeto 425 o superior).' WHERE `ID`=73732;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='위대한 옥룡이여! 저희의 간청을 들어주소서.', `MaleText_loc4`='青龙！请聆听我们的祈求。', `MaleText_loc5`='偉大的玉蛟!傾聽我們的請求。', `MaleText_loc7`='¡Gran Dragón de Jade! Escucha nuestras súplicas. ' WHERE `ID`=73733;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저와 저의 용사에게 지혜의 축복을 내려 주소서.', `MaleText_loc4`='我和我的勇士希望得到智慧的祝福。', `MaleText_loc5`='我和我的勇士來尋求您智慧的祝福。', `MaleText_loc7`='Buscamos la bendición de tu sabiduría.' WHERE `ID`=73734;
