UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움굴의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!', `MaleText_loc4`='$g他:她;可是我们搏击竞技场最精锐的9级拳手之一：$n！', `MaleText_loc5`='$g他:她;正是位居鬥陣俱樂部的第9階老手，$n!', `MaleText_loc7`='Reciban a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!', `FemaleText_loc1`='투기장의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!', `FemaleText_loc4`='$g他:她;可是我们搏击竞技场最精锐的9级拳手之一：$n！', `FemaleText_loc5`='$g他:她;正是位居鬥陣俱樂部第9階的老手，$n!', `FemaleText_loc7`='Reciban a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!' WHERE `ID`=73744;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 우리 최고의 10계급 싸움꾼, $N|1을;를; 막을 순 없습니다!', `MaleText_loc4`='欢迎我们所向披靡的10级冠军拳手，$N！', `MaleText_loc5`='歡迎無人能擋的第10階鬥陣高手，$N!', `MaleText_loc7`='¡Nadie puede detener a $gnuestro:nuestra; contendiente de rango 10, $N!', `FemaleText_loc1`='그 누구도 우리 최고의 10계급 싸움꾼, $N|1을;를; 막을 순 없습니다!', `FemaleText_loc4`='欢迎我们所向披靡的10级冠军拳手，$N！', `FemaleText_loc5`='歡迎無人能擋的第10階猛者，$N!', `FemaleText_loc7`='¡Nadie puede detener a $gnuestro:nuestra; contendiente de rango 10, $N!' WHERE `ID`=73745;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 대가가 따르든 옳은 일을 하는 것, 그것이 바로 지혜입니다.', `MaleText_loc4`='为了大义而不惜代价。这就是智慧。', `MaleText_loc5`='不計代價，去做正確的事。這就是智慧。', `MaleText_loc7`='Hacer lo correcto, sin importar el costo. Eso es sabiduría.' WHERE `ID`=73746;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정의를 위해 행동하지 않는 것이 어떻게 지혜입니까?', `MaleText_loc4`='面对大义而无所作为，何时成了智慧？', `MaleText_loc5`='難道為善還有明智地袖手旁觀的時候?', `MaleText_loc7`='¿Cuándo es más sabio no actuar por el bien común?' WHERE `ID`=73747;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아, 용의 아이와 영웅이구나. 너희는 함께 위대한 일들을 해낼 것이다.', `FemaleText_loc4`='啊，巨龙之子和他的英雄。你们俩必将成就伟大的事业。', `FemaleText_loc5`='啊，龍之子和英雄。你們能一起做出一番大事。', `FemaleText_loc7`='Ah, el niño dragón y el héroe. Juntos, lograrán grandes cosas.' WHERE `ID`=73748;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='말해다오, 용의 아이야. 지혜의 본질이 무엇이냐?', `FemaleText_loc4`='告诉我，巨龙之子：什么是智慧？', `FemaleText_loc5`='告訴我，龍之子:什麼是智慧?', `FemaleText_loc7`='Dime, niño dragón: ¿cuál es la naturaleza de la sabiduría?' WHERE `ID`=73749;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='참으로 위상의 아이다운 대답이로구나. 언제나 세상을 바꾸고자 하지.', `FemaleText_loc4`='这口气真像巨龙的后裔。总想着改变世界。', `FemaleText_loc5`='果然是守護巨龍的孩子。總是想要改變世界。', `FemaleText_loc7`='Dicho como un verdadero niño de los aspectos. Siempre buscando cambiar el mundo.' WHERE `ID`=73750;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='하지만 진정한 지혜는 무엇이 옳은지 "아는" 것에서, 때로는 아무것도 하지 않는 것에서 나온단다.', `FemaleText_loc4`='但真正的智慧源于了解何为大义。有时，无为也是种智慧。', `FemaleText_loc5`='但是真正的智慧來自分辨是非的能力。有時候，還必須順其自然。', `FemaleText_loc7`='Pero la verdadera sabiduría viene de SABER lo que es correcto. Y, a veces, NO hacer nada.' WHERE `ID`=73751;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그걸 깨닫는 게, 진정한 지혜에 이르는 길이지.', `FemaleText_loc4`='当你领悟真正的智慧之时。', `FemaleText_loc5`='能明白這一點才是真智慧。', `FemaleText_loc7`='Aprender ESO es aprender la verdadera sabiduría.' WHERE `ID`=73752;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이리 오렴! 내 축복을 줄 터이니.', `FemaleText_loc4`='来吧！我将给你们我的祝福。', `FemaleText_loc5`='上前來!我會賜予你祝福。', `FemaleText_loc7`='¡Acérquense! Les daré mi bendición.' WHERE `ID`=73753;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 시험을 받겠느냐? 목숨이 위협받는 상황에서도 영리하게 생각하고 빠르게 움직일 수 있는지 보는 시험이다.', `FemaleText_loc4`='我的挑战，如果你们接受的话，将测试你们在遭到生命危险时的机智和手段。', `FemaleText_loc5`='如果你接受我的挑戰，它將測試你在性命攸關時是否能保持機靈和敏捷。', `FemaleText_loc7`='Mi desafío, si lo aceptan, pondrá a prueba su astucia y su destreza aun frente a un peligro mortal.' WHERE `ID`=73754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 3입니다. |cFFFF2222|Hspell:141962|h[괴혈병]|h|r 효과가 발동됩니다.', `MaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了三点，使其受到|cFFFF2222|Hspell:141962|h[坏血病]|h|r的影响。', `MaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了3點，對他造成|cFFFF2222|Hspell:141962|h[壞血病]|h|r效果。', `MaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 3, lo que le causa |cFFFF2222|Hspell:141962|h[Escorbuto]|h|r.', `FemaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 3입니다. |cFFFF2222|Hspell:141962|h[괴혈병]|h|r 효과가 발동됩니다.', `FemaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了三点，使其受到|cFFFF2222|Hspell:141962|h[坏血病]|h|r的影响。', `FemaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了3點，對他造成|cFFFF2222|Hspell:141962|h[壞血病]|h|r效果。', `FemaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 3, lo que le causa |cFFFF2222|Hspell:141962|h[Escorbuto]|h|r.' WHERE `ID`=73755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 4입니다. 해골 무리가 나타나 공격합니다!', `MaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了四点，一队骷髅海盗伏击了他！', `MaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了4點，突然出現一群骷髏海盜攻擊他。', `MaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 4, y un grupo de piratas esqueleto le tienden una emboscada.', `FemaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 4입니다. 해골 무리가 나타나 공격합니다!', `FemaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了四点，一队骷髅海盗伏击了她！', `FemaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了4點，突然出現一群骷髏海盜攻擊他。', `FemaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 4, y un grupo de piratas esqueleto le tienden una emboscada.' WHERE `ID`=73756;
