UPDATE `locales_broadcast_text` SET `MaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 12입니다. 선원 전원에게 |cFF3366FF|Hspell:142140|h[해적의 삶]|h|r 효과가 발동됩니다.', `MaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了十二点，使其所有船员获得了|cFF3366FF|Hspell:142140|h[海盗传说]|h|r效果。', `MaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了12點，使他獲得|cFF3366FF|Hspell:142140|h[海盜之命]|h|r效果。', `MaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 12, lo que otorga a toda su tripulación |cFF3366FF|Hspell:142140|h[Vida de pirata]|h|r.', `FemaleText_loc1`='낡은 해적 주사위를 조심스럽게 굴립니다. 데굴데굴 굴러간 주사위의 결과는 12입니다. 선원 전원에게 |cFF3366FF|Hspell:142140|h[해적의 삶]|h|r 효과가 발동됩니다.', `FemaleText_loc4`='小心地摇动陈旧的海盗骰子。骰子滚出了十二点，使其所有船员获得了|cFF3366FF|Hspell:142140|h[海盗传说]|h|r效果。', `FemaleText_loc5`='謹慎地擲出老舊的海盜骰子，滾動的骰子最後擲出了12點，使他獲得|cFF3366FF|Hspell:142140|h[海盜之命]|h|r效果。', `FemaleText_loc7`='lanza con cuidado los dados de pirata. Los dados rebotan y finalmente muestran un 12, lo que otorga a toda su tripulación |cFF3366FF|Hspell:142140|h[Vida de pirata]|h|r.' WHERE `ID`=73764;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='자, 시험을 시작하자! 영웅이여, 넌 검은 왕자와 싸우고 승리해야 한다.', `FemaleText_loc4`='开始挑战吧！英雄，你要在战斗中击败黑王子。', `FemaleText_loc5`='讓挑戰開始吧!英雄，你必須在戰鬥中擊敗黑龍王子。', `FemaleText_loc7`='¡Que comience el desafío! Deberás derrotar al Príncipe Negro en combate.' WHERE `ID`=73765;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='나의 검은 왕자여, 너는 눈을 가릴 것이다.', `FemaleText_loc4`='你，黑王子，将被蒙上眼睛。', `FemaleText_loc5`='你，黑龍王子，必須矇上眼睛。', `FemaleText_loc7`='Tú, mi príncipe oscuro, tendrás los ojos vendados.' WHERE `ID`=73766;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이끌어줄 눈이 없다면 힘이 얼마나 제한되는지 알게 될 것이야.', `FemaleText_loc4`='我们将会看到，失去指引的力量会有怎样的局限。', `FemaleText_loc5`='我們將會展示盲目的力量有何侷限。', `FemaleText_loc7`='Demostraremos los límites del poder sin la visión que los guíe.' WHERE `ID`=73767;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='시작해라!', `FemaleText_loc4`='开始！', `FemaleText_loc5`='開始!', `FemaleText_loc7`='¡Comiencen!' WHERE `ID`=73768;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='움직임이 가장 중요하다. 용의 아이가 너에게 가까이 오지 못하게 하렴.', `FemaleText_loc4`='利用你的移动优势。别让巨龙之子靠近。', `FemaleText_loc5`='利用你能移動的優勢。別讓龍之子靠太近。', `FemaleText_loc7`='Usa el movimiento a tu favor. No permitas que el niño dragón se te acerque.' WHERE `ID`=73770;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주변을 잘 살펴야 한다.', `FemaleText_loc4`='注意周围的环境。', `FemaleText_loc5`='注意你的四周。', `FemaleText_loc7`='Sé consciente de tu entorno.' WHERE `ID`=73771;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령에게 붙잡혀선 안 된다!', `FemaleText_loc4`='别让元素缠住你！', `FemaleText_loc5`='別讓元素攻擊到你!', `FemaleText_loc7`='¡No permitas que los elementos hagan contacto contigo!' WHERE `ID`=73772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 티탄의 전설적인 힘을 마음대로 휘두르지!', `MaleText_loc4`='我掌握着泰坦的传奇力量！', `MaleText_loc5`='我掌握著泰坦傳說中的力量!', `MaleText_loc7`='¡El poder legendario de los Titanes está bajo mi control!' WHERE `ID`=73773;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가만히 있어! 얌전히 죽으란 말이다!', `MaleText_loc4`='站住！我正要杀了你呢！', `MaleText_loc5`='別亂動!我正試著要殺死你!', `MaleText_loc7`='¡Quédate quieto que estoy tratando de matarte!' WHERE `ID`=73774;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디로 간 거지? 이리 와라!', `MaleText_loc4`='你去哪儿？回来。', `MaleText_loc5`='你跑去哪了?快回來。', `MaleText_loc7`='¿Adónde fuiste? Regresa.' WHERE `ID`=73775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 하!', `MaleText_loc4`='啊……哈！', `MaleText_loc5`='啊...哈!', `MaleText_loc7`='Aaah... ¡Ja!' WHERE `ID`=73776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='녹색용은 눈을 감아도 세상을 볼 수 있지. 내가 녹색용이 아니라는 데 감사해라.', `MaleText_loc4`='你该庆幸我不是绿龙，他们闭着眼睛都能看见东西。', `MaleText_loc5`='你很幸運，我不是那些閉著眼睛都能看到你的綠龍。', `MaleText_loc7`='Tienes suerte de que no soy uno de esos dragones verdes que ven con los ojos cerrados.' WHERE `ID`=73777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예상대로군. 한 번 더 해보고 싶나?', `MaleText_loc4`='不出我所料。你还想再来一次吗？', `MaleText_loc5`='如我所料。你還想要再試試看嗎?', `MaleText_loc7`='Como lo esperaba. ¿Querrías volver a intentarlo?' WHERE `ID`=73778;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='거기까지!', `FemaleText_loc4`='停手！', `FemaleText_loc5`='這樣夠了!', `FemaleText_loc7`='¡Suficiente!' WHERE `ID`=73779;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='용사여, 적의 움직임을 예측하고 언제나 한 발짝 먼저 움직여라. 넌 승리할 수 있다.', `FemaleText_loc4`='勇士，你要预判敌人的动作，并始终抢先一步。胜利就在你手中！', `FemaleText_loc5`='勇士，預料你敵人的行動，並總是搶先一步，勝利就是你的!', `FemaleText_loc7`='Predice los movimientos de tu enemigo y siempre mantente un paso adelante. ¡La victoria está en ti!' WHERE `ID`=73780;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='아주 좋아. 그 정도면 됐다!', `FemaleText_loc4`='很好——停手！', `FemaleText_loc5`='很好...這樣就夠了!', `FemaleText_loc7`='Muy bien. ¡Suficiente!' WHERE `ID`=73781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 저쪽이 너무 유리했어요.', `MaleText_loc4`='呸！这场挑战不公平。', `MaleText_loc5`='嘖!真是不公平的挑戰。', `MaleText_loc7`='¡Bah! Un desafío disparejo.' WHERE `ID`=73782;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 알겠느냐? 눈먼 힘은 마구잡이 혼돈과 파괴만을 부를 뿐이란다.', `FemaleText_loc4`='看到了吗？缺乏指引的力量只会带来混乱和毁灭。', `FemaleText_loc5`='看到了嗎?盲目的力量只會造成失控的混亂和毀滅。', `FemaleText_loc7`='¿Ves? El poder, sin la visión, causa caos y destrucción.' WHERE `ID`=73783;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭐, 우리의 영웅이 아직 살아 있어 기쁘군요. 축복을 내려 주셔서 감사합니다.', `MaleText_loc4`='我很高兴我们的英雄还活着。谢谢你的祝福，伟大的青龙。', `MaleText_loc5`='很高興我們的英雄還活著。感謝您的祝福，偉大的玉蛟。', `MaleText_loc7`='Me alegra que nuestro héroe siga con vida. Gracias por tu bendición, gran dragón.' WHERE `ID`=73784;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시험을 시작하자! 영웅이여, 네가 치유사의 능력을 발휘해 검은 왕자를 살려내야 한다.', `MaleText_loc4`='开始挑战吧！英雄，你要用治疗技能保证黑王子的生命。', `MaleText_loc5`='讓挑戰開始吧!英雄，你必須以治療者的技能使黑龍王子活下來。', `MaleText_loc7`='¡Que comience el desafío! Tendrás que mantener con vida al Príncipe Negro con tus habilidades de sanación. ' WHERE `ID`=73785;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그럴까? 넌 의심과 공포에 사로잡혀 있다, 젊은 왕자여.', `MaleText_loc4`='是吗？你心中充满了疑虑和恐惧，年轻的王子。', `MaleText_loc5`='你確定嗎?你充滿了懷疑和恐懼，年輕的王子。', `MaleText_loc7`='¿Estás seguro? Estás lleno de dudas y miedos, joven Príncipe. ' WHERE `ID`=73786;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 아직도 과거를 완전히 받아들이지 못했지. 지금이 그걸 극복할 때다.', `MaleText_loc4`='你从未真正接受你的过去。现在是时候了。', `MaleText_loc5`='你還沒完全放下你的過去。現在是時候了。', `MaleText_loc7`='No te has reconciliado totalmente con tu pasado. Llegó el momento.' WHERE `ID`=73787;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 용사가 너를 살릴 것이다. 시작해라!', `MaleText_loc4`='你的勇士会保证你的生命。开始！', `MaleText_loc5`='你的勇士會讓你活下來。開始吧!', `MaleText_loc7`='Tu campeón te mantendrá con vida. ¡Comiencen!' WHERE `ID`=73788;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 검은용입니다. 도움 따위 필요없습니다.', `MaleText_loc4`='我可是黑龙。我不需要帮助。', `MaleText_loc5`='我可是黑龍。我不需要幫助。', `MaleText_loc7`='Soy un dragón negro. No necesitaré ninguna ayuda.' WHERE `ID`=73789;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 이건... 아버지?!', `MaleText_loc4`='什么——等等——父亲！？', `MaleText_loc5`='什麼...等等...父親?!!', `MaleText_loc7`='¿Qué? Espera... ¿¡Padre!?' WHERE `ID`=73790;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 이 시험은 거두어 주세요!', `MaleText_loc4`='不——不要逼我。', `MaleText_loc5`='噢...請別逼我這麼做。', `MaleText_loc7`='Por favor... No me obligues a hacer esto.' WHERE `ID`=73791;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 이 세상을 갈기갈기 찢어주마!', `MaleText_loc4`='我要将这世界撕成碎片！', `MaleText_loc5`='我會將這個世界撕裂!', `MaleText_loc7`='Devastaré este mundo.' WHERE `ID`=73792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자를 치유해라. 하지만, 네 몸을 챙기는 것도 잊지 마라!', `MaleText_loc4`='治疗王子，但也别忘了保护自己的安全！', `MaleText_loc5`='治療王子，但別忘記讓自己活著!', `MaleText_loc7`='Sana al príncipe, ¡pero no olvides cuidar tu propia vida!' WHERE `ID`=73793;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기회가 있을 때마다 검은 왕자를 치유해야 한다.', `MaleText_loc4`='不要错过任何治疗黑王子的机会。', `MaleText_loc5`='別錯過治療黑龍王子的機會。', `MaleText_loc7`='No desperdicies ninguna oportunidad para sanar al Príncipe Negro. ' WHERE `ID`=73794;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='암흑의 장막이 걷혔다!', `MaleText_loc4`='阴影散开了！', `MaleText_loc5`='暗影帷幕已經解除了!', `MaleText_loc7`='¡El velo de las sombras ha sido levantado!' WHERE `ID`=73795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속 움직여라. 적은 무시무시하지만, 네가 더 영리하다.', `MaleText_loc4`='保持移动。敌人很危险，但你更聪明。', `MaleText_loc5`='繼續移動。你的敵人很危險，但你比他聰明。', `MaleText_loc7`='Sigue moviéndote. Tu enemigo es peligroso pero tú eres más inteligente. ' WHERE `ID`=73796;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주변의 피를 이용해 너 자신을 회복시켜라. 넌 할 수 있어.', `MaleText_loc4`='使用世界之血治疗你自己。你能做到。', `MaleText_loc5`='使用世界之血回復自己的傷勢。你可以辦得到。', `MaleText_loc7`='Usa la sangre del mundo para regenerarte. Tú puedes hacerlo.' WHERE `ID`=73797;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령은 다시 일어날 것이다. 그때까지 남은 시간을 현명하게 사용해라!', `MaleText_loc4`='元素是不灭的！在它们复活前，利用好你的时间！', `MaleText_loc5`='元素是不滅的!在它們再度起身前好好利用你的時間!', `MaleText_loc7`='Los elementos abandonan la muerte. ¡Aprovecha bien el tiempo antes de que vuelvan a levantarse!' WHERE `ID`=73798;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용사여, 적의 덫을 두려워하지 마라. 그의 마법보다 너의 치유가 더 강하다!', `MaleText_loc4`='不要害怕陷阱。你的治疗比他的法术更强大！', `MaleText_loc5`='別害怕他的陷阱，勇士。你的治療比他的魔法強大!', `MaleText_loc7`='No temas a sus trampas. ¡Tu sanación es más poderosa que su magia!' WHERE `ID`=73799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='끈기 하나는 인정해 줘야겠군. 하지만 무의미하다!', `MaleText_loc4`='你们的顽强令我赞叹，但毫无价值。', `MaleText_loc5`='你們的固執令人讚嘆，但是毫無意義。', `MaleText_loc7`='Su tesón es admirable, pero inútil.' WHERE `ID`=73800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='버둥거리는 꼴이 가소롭군!', `MaleText_loc4`='你们的努力是徒劳的！', `MaleText_loc5`='你們的努力毫無意義!', `MaleText_loc7`='Sus esfuerzos son inútiles.' WHERE `ID`=73801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 분노에서 탈출할 곳은 없다!', `MaleText_loc4`='谁都逃不过我的怒火！', `MaleText_loc5`='沒有地方能逃過我的怒火!', `MaleText_loc7`='Es imposible resguardarse de mi furia.' WHERE `ID`=73802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='방어구 따윈 아무 소용없다. 믿음은 더더욱 그렇지!', `MaleText_loc4`='你的护甲毫无作用，你的信仰一文不值！', `MaleText_loc5`='你們的護甲毫無意義，你們的信念更是垃圾!', `MaleText_loc7`='Su armadura no es nada. Su fe, menos aún.' WHERE `ID`=73803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그만! 그만해 주세요!', `MaleText_loc4`='够了！快停下！', `MaleText_loc5`='夠了，趕快停下來!', `MaleText_loc7`='¡Basta! ¡Haz que pare!' WHERE `ID`=73804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 시험은 끝났다.', `MaleText_loc4`='很好。试炼结束。', `MaleText_loc5`='好吧。考驗結束了。', `MaleText_loc7`='Muy bien. La prueba se acabó.' WHERE `ID`=73805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만, 절망에 빠지지 마라. 넌 충분히 이걸 극복할 수 있어. 다시 도전해라... 너를 믿는다!', `MaleText_loc4`='但是，不要绝望。你有克服它的能力。再试一次——我相信你！', `MaleText_loc5`='但，不要感到絕望。你有戰勝的精神。再試一次，我相信你!', `MaleText_loc7`='Pero no desesperes. Tienes el espíritu para superar esto. Vuelve a intentarlo... ¡Yo creo en ti!' WHERE `ID`=73806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아주 좋아! 마침내 해냈구나!', `MaleText_loc4`='很好！你成功了！', `MaleText_loc5`='很好，你成功了!', `MaleText_loc7`='¡Muy bien! ¡Lo lograste!' WHERE `ID`=73807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절망하지 마라, 젊은 왕자여. 너는 네 아버지가 아니다.', `MaleText_loc4`='不要绝望，年轻的王子。你不是你父亲。', `MaleText_loc5`='不要絕望，年輕的王子。你不是你的父親。', `MaleText_loc7`='No desesperes, joven príncipe. No eres tu padre.' WHERE `ID`=73808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='게다가, 너의 용사가 네가 무너지지 않게 도울 것이다. 알겠느냐? 친구의 도움이 있다면 불가능한 일이 없지.', `MaleText_loc4`='更重要的是，你的勇士不会让你倒下。明白吗？在朋友的支持下，一切皆有可能。', `MaleText_loc5`='更重要的是，你的勇士不會讓你倒下。看到了嗎?有了朋友的支援，一切都有可能。', `MaleText_loc7`='Y lo que es más importante: tu campeón no te dejará caer. ¿Acaso no lo ves? Con el apoyo de tus amigos, nada es imposible. ' WHERE `ID`=73809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런... 광기라니...', `MaleText_loc4`='太……疯狂了……', `MaleText_loc5`='何等的...瘋狂...', `MaleText_loc7`='Tanta... locura…' WHERE `ID`=73810;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다. 감사합니다, 위대한 학이여.', `MaleText_loc4`='我明白了。谢谢你，朱鹤。', `MaleText_loc5`='我懂了。謝謝您，偉大的紅鶴。', `MaleText_loc7`='Entiendo. Gracias, Gran Grulla.' WHERE `ID`=73811;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제 시험을 시작하자! 영웅이여, 검은 왕자가 내면의 혼란과 맞서는 동안 네가 그를 보호해야 한다.', `MaleText_loc4`='开始挑战吧！英雄，你必须在黑王子面对心魔的时候保护他。', `MaleText_loc5`='讓挑戰開始吧!英雄，你必須在黑龍王子面對他內心的掙扎時保護他。', `MaleText_loc7`='¡Que comience el desafío! Deberás defender al Príncipe Negro mientras se enfrenta a su conflicto interior.' WHERE `ID`=73812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정말 그럴까? 넌 의심과 공포에 사로잡혀 있다, 젊은 왕자여.', `MaleText_loc4`='是吗？你心中充满了疑虑和恐惧，年轻的王子。', `MaleText_loc5`='是這樣嗎?你充滿了懷疑和恐懼，年輕的王子。', `MaleText_loc7`='¿Eso crees? Estás lleno de dudas y miedo, joven príncipe. ' WHERE `ID`=73813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 내면의 악마와 마주해라. 바로 지금 말이다.', `MaleText_loc4`='面对你的心魔吧，现在是时候了。', `MaleText_loc5`='面對你的心魔吧。是時候了。', `MaleText_loc7`='Enfrenta a tus demonios internos. Llegó el momento.  ' WHERE `ID`=73814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너의 용사가 널 보호할 것이다. 시작해라!', `MaleText_loc4`='你的勇士会保护你的。开始！', `MaleText_loc5`='你的勇士會保護你。開始吧!', `MaleText_loc7`='Tu campeón te defenderá. ¡Comiencen!' WHERE `ID`=73815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 검은용입니다. 도움 따위 필요없습니다.', `MaleText_loc4`='我可是黑龙。我不需要帮助。', `MaleText_loc5`='我可是黑龍。我不需要幫助。', `MaleText_loc7`='Soy un dragón negro. No necesitaré ninguna ayuda.' WHERE `ID`=73816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 이건... 아버지?!', `MaleText_loc4`='什么——等等——父亲！？', `MaleText_loc5`='什麼...等等...父親?!!', `MaleText_loc7`='¿Qué? Espera... ¿¡Padre!?' WHERE `ID`=73817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제발... 이 시험은 거두어 주세요!', `MaleText_loc4`='不——不要逼我。', `MaleText_loc5`='噢...請別逼我這麼做。', `MaleText_loc7`='Por favor... No me obligues a hacer esto.' WHERE `ID`=73818;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령은 다시 일어날 것이다. 그때까지 남은 시간을 현명하게 사용해라!', `MaleText_loc4`='元素是不灭的！在它们复活前，利用好你的时间！', `MaleText_loc5`='元素是不滅的!在它們再度起身前好好利用你的時間!', `MaleText_loc7`='¡Los elementos abandonan la muerte! ¡Aprovecha el tiempo antes de que regresen! ' WHERE `ID`=73819;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장의 지배자가 되어라. 모든 적에게 주의를 기울여라.', `MaleText_loc4`='控制战斗。注意你所有的敌人。', `MaleText_loc5`='控制場面。注意全部的敵人。', `MaleText_loc7`='Controla el combate. Presta atención a TODOS tus enemigos.' WHERE `ID`=73820;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전장을 잘 활용해 자신을 회복시켜라.', `MaleText_loc4`='利用战场对自己进行恢复。', `MaleText_loc5`='使用戰場來恢復力量。', `MaleText_loc7`='Usa el campo de batalla para regenerarte.' WHERE `ID`=73821;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은 왕자를 보호해라! 적의 주의를 끌어!', `MaleText_loc4`='保护黑王子！引开他的敌人！', `MaleText_loc5`='保護黑龍王子!引開他的敵人!', `MaleText_loc7`='¡Protege al Príncipe Negro! ¡Distrae a sus enemigos!' WHERE `ID`=73822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적이 공격을 마치게 두지 마라.', `MaleText_loc4`='不要让你的敌人完成攻击。', `MaleText_loc5`='別讓你的敵人完成攻擊。', `MaleText_loc7`='No permitas que tu enemigo complete su ataque.' WHERE `ID`=73823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕자를 지키려면 너 자신을 희생해야 한다는 걸 잊지 마라!', `MaleText_loc4`='为了不让王子倒下，你必须牺牲自己！', `MaleText_loc5`='你必須犧牲自己來保護黑龍王子!', `MaleText_loc7`='¡Deberás sacrificarte para impedir que el príncipe caiga!' WHERE `ID`=73824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리하지. 시험은, 이제 끝났다.', `MaleText_loc4`='好吧，试炼结束了。', `MaleText_loc5`='如你所願。考驗結束了。', `MaleText_loc7`='Que así sea. La prueba terminó. ' WHERE `ID`=73825;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억해라. 패배를 받아들이고 굴복하기 전까지는 아직 패배한 게 아니다. 진정한 인내를 가진 이들은 넘어져도 언제나 다시 일어서지.', `MaleText_loc4`='记住：除非甘心放弃，否则没有人能够击败你。真正坚忍的人总能在跌倒后爬起来。', `MaleText_loc5`='記住，在你決定放棄前你永遠不算失敗。真正堅忍的人在倒下後還是會站起來。', `MaleText_loc7`='Recuerda: nunca estarás derrotado hasta que decidas que lo estás. Aquellos con verdadera fortaleza siempre se levantan después de caer.' WHERE `ID`=73826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다시 도전해라... 네가 이 시험을 통과할 수 있다는 걸 안다!', `MaleText_loc4`='再来——我知道你们是可以的！', `MaleText_loc5`='再試一次。我知道你能通過這個考驗!', `MaleText_loc7`='Vuelve a intentarlo... ¡yo sé que puedes superar este desafío!' WHERE `ID`=73827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너에겐 친구들이 있다. 너의 용사는 네가 무너지게 내버려 두지 않았어. 이 교훈을 가슴에 새겨라.', `MaleText_loc4`='你有朋友。你的勇士不会让你倒下。牢牢记住这一课吧。', `MaleText_loc5`='你有著朋友。你的勇士沒有讓你倒下。請記取這個教訓。', `MaleText_loc7`='Tienes amigos. Tu campeón no te permitió caer. Guarda esta lección en tu corazón. ' WHERE `ID`=73828;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 네 아버지보다 강하다, 젊은 왕자여.', `MaleText_loc4`='你比你的父亲更强大，年轻的王子。', `MaleText_loc5`='你比你的父親強大，年輕的王子。', `MaleText_loc7`='Eres más fuerte que tu padre, joven príncipe. ' WHERE `ID`=73829;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘했다! 너는 승리했다!', `MaleText_loc4`='干得好！你们胜利了！', `MaleText_loc5`='做得好!你勝利了!', `MaleText_loc7`='¡Bien hecho! ¡Han triunfado!' WHERE `ID`=73830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 알겠습니다. 감사합니다, 강대한 흑우여.', `MaleText_loc4`='我明白了。谢谢你，玄牛。', `MaleText_loc5`='我懂了。感謝您，偉大的玄牛。', `MaleText_loc7`='Comprendo. Gracias, poderoso Buey.' WHERE `ID`=73831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 얼라이언스 금광 수레를 기지로 돌려보냈습니다!', `MaleText_loc4`='$n将联盟运金车送回了基地！', `MaleText_loc5`='$n讓聯盟的黃金礦車返回它的營地了!', `MaleText_loc7`='¡$n ha llevado el carro de oro de la Alianza de nuevo a su base!' WHERE `ID`=73832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스의 금광 수레가 기지로 돌아왔습니다!', `MaleText_loc4`='联盟运金车被送回了基地！', `MaleText_loc5`='聯盟的黃金礦車返回它的營地了!', `MaleText_loc7`='¡Han vuelto a llevar a su base el carro de oro de la Alianza!' WHERE `ID`=73833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$n|1이;가; 호드 금광 수레를 기지로 돌려보냈습니다!', `MaleText_loc4`='$n将部落运金车送回了基地！', `MaleText_loc5`='$n讓部落的黃金礦車返回它的營地了!', `MaleText_loc7`='¡$n ha llevado el carro de oro de la Horda de nuevo a su base!' WHERE `ID`=73834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:142111|h[훼방의 함성]|h|r을 준비합니다!', `MaleText_loc4`='%s正准备施放|cFFFF0000|Hspell:142111|h[瓦解咆哮]|h|r！', `MaleText_loc5`='%s準備施展|cFFFF0000|Hspell:142111|h[干擾怒吼]|h|r!', `MaleText_loc7`='¡%s prepara un |cFFFF0000|Hspell:142111|h[Bramido perturbador]|h|r!', `FemaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:142111|h[훼방의 함성]|h|r을 준비합니다!', `FemaleText_loc4`='%s正准备施放|cFFFF0000|Hspell:142111|h[瓦解咆哮]|h|r！', `FemaleText_loc5`='%s準備施展|cFFFF0000|Hspell:142111|h[干擾怒吼]|h|r!', `FemaleText_loc7`='¡%s prepara un |cFFFF0000|Hspell:142111|h[Bramido perturbador]|h|r!' WHERE `ID`=73835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 금광 수레가 기지로 돌아왔습니다!', `MaleText_loc4`='联盟运金车被送回了基地！', `MaleText_loc5`='聯盟的黃金礦車返回它的營地了!', `MaleText_loc7`='¡Han vuelto a llevar a su base el carro de oro de la Alianza!' WHERE `ID`=73836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 금광 수레가 기지로 돌아왔습니다!', `MaleText_loc4`='部落运金车被送回了基地！', `MaleText_loc5`='部落的黃金礦車返回它的營地了!', `MaleText_loc7`='¡Han vuelto a llevar a su base el carro de oro de la Horda!' WHERE `ID`=73837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어리석구나! 너희 따위가 진정한 호드를 막아낼 순 없다!', `MaleText_loc4`='蠢货！你们这些人在正统部落面前不堪一击。', `MaleText_loc5`='蠢貨!像你這種廢物無法阻止正統的部落!', `MaleText_loc7`='¡Estúpidos! ¡Los de su especie no pueden detener a la auténtica Horda!' WHERE `ID`=73838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순간이동기가 준비됐어! 어서 여기를 뜨자고!', `MaleText_loc4`='传送器准备就绪！让我们离开这儿！', `MaleText_loc5`='傳送器已經準備就緒!我們快離開這吧!', `MaleText_loc7`='¡El teletransportador está listo! ¡Salgamos de aquí!' WHERE `ID`=73839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 놈들이 모여들고 있습니다.', `MaleText_loc4`='那些库卡隆正在集结。', `MaleText_loc5`='柯爾克隆正在集結。', `MaleText_loc7`='Los Kor''kron se eh''tán reuniendo.', `FemaleText_loc1`='코르크론 놈들이 모여들고 있군요.', `FemaleText_loc4`='那些库卡隆正在集结。', `FemaleText_loc5`='柯爾克隆正在集結。', `FemaleText_loc7`='Los Kor''kron se eh''tán reuniendo.' WHERE `ID`=73840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머지않아 코르크론이 언덕을 올라오겠군요.', `MaleText_loc4`='很快，那些库卡隆就会像潮水一样涌上山头。', `MaleText_loc5`='很快我們就會見到滿山遍野的柯爾克隆了。', `MaleText_loc7`='Pronto veremos a esos Kor''kron subir por las colinas.', `FemaleText_loc1`='머지않아 코르크론이 언덕을 올라오겠군요.', `FemaleText_loc4`='很快，那些库卡隆就会像潮水一样涌上山头。', `FemaleText_loc5`='很快我們就會見到滿山遍野的柯爾克隆了。', `FemaleText_loc7`='Pronto veremos a esos Kor''kron subir por las colinas.' WHERE `ID`=73841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리를 도와주실 겁니까, $c 님?', `MaleText_loc4`='你会帮我们的，对吧？$c？', `MaleText_loc5`='你會幫助我們嗎，$c?', `MaleText_loc7`='¿Nos vas a ayudar, $c?', `FemaleText_loc1`='우리를 도와줄 건가요, $c 님?', `FemaleText_loc4`='你会帮我们的，对吧？$c？', `FemaleText_loc5`='你會幫助我們嗎，$c?', `FemaleText_loc7`='¿Nos vas a ayudar, $c?' WHERE `ID`=73842;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='혁명에 동참하러 왔습니까, 친구여?', `MaleText_loc4`='你是来参加起义的吗，伙计？', `MaleText_loc5`='你是來加入反抗軍的嗎，老兄?', `MaleText_loc7`='¿Has venido a unirte a la revolución, colega?', `FemaleText_loc1`='혁명에 동참하러 오셨나요, 친구여?', `FemaleText_loc4`='你是来参加起义的吗，伙计？', `FemaleText_loc5`='你是來加入反抗軍的嗎，老兄?', `FemaleText_loc7`='¿Has venido a unirte a la revolución, colega?' WHERE `ID`=73843;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저항군에 들어온 걸 환영합니다.', `MaleText_loc4`='欢迎加入起义军。', `MaleText_loc5`='歡迎加入反抗軍。', `MaleText_loc7`='Te damos la bienvenida a nueh''tra revolución.', `FemaleText_loc1`='저항군에 들어온 걸 환영해요.', `FemaleText_loc4`='欢迎加入起义军。', `FemaleText_loc5`='歡迎加入反抗軍。', `FemaleText_loc7`='Te damos la bienvenida a nueh''tra revolución.' WHERE `ID`=73844;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물자가 갖추어졌으니 코르크론 놈들도 우릴 기습하지 못할 겁니다.', `MaleText_loc4`='这次，那些库卡隆休想再偷袭我们了。', `MaleText_loc5`='這次柯爾克隆可沒辦法偷襲我們。', `MaleText_loc7`='Esos Kor''kron no nos van a pillar deh''prevenidos eh''ta vez.', `FemaleText_loc1`='물자가 갖추어졌으니 코르크론 놈들도 우릴 기습하지 못할 거예요.', `FemaleText_loc4`='这次，那些库卡隆休想再偷袭我们了。', `FemaleText_loc5`='這次柯爾克隆可沒辦法偷襲我們。', `FemaleText_loc7`='Esos Kor''kron no nos van a pillar deh''prevenidos eh''ta vez.' WHERE `ID`=73845;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친한 친구들 중에 오크도 있는데 말입니다. 안타깝군요.', `MaleText_loc4`='我也有一些很好的兽人朋友。这世道太糟糕了。', `MaleText_loc5`='我有些好朋友是獸人，這場面會很難看。', `MaleText_loc7`='Muchos de mis mejores amigos son orcos. Es una época dura.', `FemaleText_loc1`='친한 친구들 중에 오크도 있는데 말이죠. 안타깝군요.', `FemaleText_loc4`='我也有一些很好的兽人朋友。这世道太糟糕了。', `FemaleText_loc5`='我有些好朋友是獸人，這場面會很難看。', `FemaleText_loc7`='Muchos de mis mejores amigos son orcos. Es una época dura.' WHERE `ID`=73846;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검은창 부족은 곧 준비를 마칠 겁니다.', `MaleText_loc4`='我们暗矛部族会做好准备的。', `MaleText_loc5`='暗矛部族會做好準備的。', `MaleText_loc7`='Los Lanza Negra eh''taremos lih''tos.', `FemaleText_loc1`='검은창 부족은 곧 준비를 마칠 거예요.', `FemaleText_loc4`='我们暗矛部族会做好准备的。', `FemaleText_loc5`='暗矛部族會做好準備的。', `FemaleText_loc7`='Los Lanza Negra eh''taremos lih''tos.' WHERE `ID`=73847;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신은 우리의 혁명에 큰 도움을 주었습니다, 친구. 우린 이제 무장할 수 있습니다.', `MaleText_loc4`='你真是起义军的宝贵财富。现在，我们已经武装起来了。', `MaleText_loc5`='你是反抗軍中不可或缺的戰力，老兄。我們該為開戰做準備了。', `MaleText_loc7`='Has sido de gran ayuda pa'' la revolución, colega. Ahora tenemos que armarnos.', `FemaleText_loc1`='당신은 우리의 혁명에 큰 도움을 주었습니다, 친구여. 우린 이제 무장할 수 있어요.', `FemaleText_loc4`='你真是起义军的宝贵财富。现在，我们已经武装起来了。', `FemaleText_loc5`='你是反抗軍中不可或缺的戰力，老兄。我們該為開戰做準備了。', `FemaleText_loc7`='Has sido de gran ayuda pa'' la revolución, colega. Ahora tenemos que armarnos.' WHERE `ID`=73848;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무기를 손에 제대로 쥔 건가? 제대로 훈련받은 코르크론이라면 눈 깜짝할 새에 자네의 무기를 튕겨낼걸세.', `MaleText_loc4`='你们就是这么拿武器的？任何一个合格的库卡隆都能轻而易举地把你们缴械了。', `MaleText_loc5`='你知道武器該怎麼握嗎?任何一個會戰鬥的柯爾克隆士兵都可以輕易地卸除你的武裝。', `MaleText_loc7`='¿A eso es a lo que tú llamas agarre de un arma? Cualquier Kor''kron que se precie te desarmaría en un segundo.' WHERE `ID`=73871;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 코르크론에게 대적해야 하네. 오크들 중에서도 가장 거칠고 악랄한 놈들이지. 훈련 중에 졸거나 하지는 않겠지?', `MaleText_loc4`='我们将要面对库卡隆。他们是全部落最卑鄙、最混账的兽人。你们最好别在训练中打瞌睡。', `MaleText_loc5`='我們要面對的敵人是柯爾克隆，他們可是部落裡最兇狠、殘暴的獸人，你最好在這場訓練裡給我打起精神來。', `MaleText_loc7`='Nos enfrentaremos a los Kor''kron. Son los orcos más deteh''tables y deshoneh''tos de toda la Horda. ¡Más vale que no te deh''pistes ni un segundo del entrenamiento!' WHERE `ID`=73873;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억하게! 코르크론이 휘두르는 도끼는 칼날이 있는 부분만 위험하지. 하지만 자네들의 철퇴에는 그런 제한이 없다네.', `MaleText_loc4`='记住！库卡隆必须用战斧开刃的那一面来攻击你。而你们的钉锤却没有这种限制。', `MaleText_loc5`='記著!柯爾克隆的斧頭只能用鋒利的斧刃來砍你們，但是你們的錘子可沒有那種限制。', `MaleText_loc7`='¡Recuerda! Las hachas de los Kor''kron tienen que golpearte con el filo. Las mazas no tienen esa limitación.' WHERE `ID`=73874;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='SPAWN ACTION', `MaleText_loc4`='SPAWN ACTION', `MaleText_loc5`='SPAWN ACTION', `MaleText_loc7`='APARICIÓN' WHERE `ID`=73875;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그게 함성이라고? 우리는 저항군이네. 상대방이 이미 패배했다고 착각할 만큼 우렁차게 내지르란 말일세.', `MaleText_loc4`='你们管这叫战吼？我们即将发动起义。你们要像胜利者那样咆哮，让另一方摸不着头脑。', `MaleText_loc5`='這算哪門子的戰吼?像你這般吼法，吼到起義結束了，另一頭的弟兄們都還聽不清楚你在吼什麼呢。', `MaleText_loc7`='¿A eso es a lo que tú llamas un grito de guerra? Eh''to es una revolución. Ruge como si ya hubiéramos ganado y la facción contraria aún no lo supiera.' WHERE `ID`=73877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 더 나타나기 전에 모두 나가자!', `MaleText_loc4`='趁现在敌人还不多，大家快离开这儿！', `MaleText_loc5`='大家快在更多敵人殺過來之前撤退!', `MaleText_loc7`='¡Todo el mundo fuera, antes de que lleguen más!' WHERE `ID`=73878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 고블린이 빠져나갈 때까지 내가 방어하지! 모두 집결지점에서 만나자!', `MaleText_loc4`='我会一直守到最后一个地精离开为止！我们在集合点见！', `MaleText_loc5`='我會守到最後一個哥布林撤出為止!咱們會合點見!', `MaleText_loc7`='¡Yo defenderé hasta que salga el último goblin! Nos vemos en el punto de encuentro.' WHERE `ID`=73879;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='진짜 적을 찾아야 한다! 가짜 모습에 속아선 안 돼!', `FemaleText_loc4`='找出真正的敌人！别被假象迷惑了！', `FemaleText_loc5`='尋找你真正的敵人!別讓他虛假的影像影響!', `FemaleText_loc7`='¡Busca a tu verdadero enemigo! ¡Que no te engañen las imágenes falsas!' WHERE `ID`=73880;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정령은 다시 일어날 것이다! 그때까지 남은 시간을 현명하게 사용하렴.', `FemaleText_loc4`='元素是不灭的！在它们复活前，利用好你的时间！', `FemaleText_loc5`='元素是不滅的!在它們再度起身前好好利用你的時間!', `FemaleText_loc7`='¡Los elementos abandonan la muerte! ¡Aprovecha bien el tiempo antes de que vuelvan a levantarse!' WHERE `ID`=73881;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='젊은 왕자여, 부디 이 교훈을 가슴에 새겨라.', `FemaleText_loc4`='年轻的王子，请记住这一课。', `FemaleText_loc5`='年輕的王子，請記取這個教訓。', `FemaleText_loc7`='Por favor, joven príncipe. Guarda esta lección en tu corazón.' WHERE `ID`=73882;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 놈들이 우리 배에 침입했다. 모두 쓸어버려!', `MaleText_loc4`='停下，这些联盟恶棍爬到我们船上来了。去解决他们！', `MaleText_loc5`='注意，這些聯盟雜碎已經登上我們的船了，殺光他們!', `MaleText_loc7`='Arrr, esos marineros de agua dulce de la Alianza han conseguido subir al barco. ¡Encargaos de ellos!' WHERE `ID`=73883;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 당신에게 등산용 밧줄을 건넵니다.', `MaleText_loc4`='%s交给你一条爬绳。', `MaleText_loc5`='%s給了你一條登山繩。', `MaleText_loc7`='%s te da una cuerda de escalar.' WHERE `ID`=73884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='절 따라오십시오, $c님. 볼진 님께서 당신을 찾으시더군요.', `MaleText_loc4`='跟我走，$c。沃金一会儿要见你。', `MaleText_loc5`='跟我來，$c，沃金待會就會接見你。', `MaleText_loc7`='Ven conmigo, $c. Vol''jin te recibirá en un momento.' WHERE `ID`=73885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='"대족장"은 볼진 님이 쿤라이 봉우리에서 죽은 걸로 알고 있습니다. 자신이 보낸 코르크론 암살자에게 살해당했다고 말이죠.', `MaleText_loc4`='那位“酋长”还以为沃金死了，被他的库卡隆刺客暗杀于昆莱山。', `MaleText_loc5`='這位『大酋長』還以為沃金被他派去崑萊峰的柯爾克隆刺客殺死了。', `MaleText_loc7`='El "Jefe de Guerra" todavía cree que Vol''jin eh''tá muerto; asesinado a manos de su asesino Kor''kron en la Cima Kun-Lai.' WHERE `ID`=73886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 볼진 님은 살아 계십니다. 그리고 헬스크림의 배신을 똑똑히 기억하시죠. 검은창 부족은 절대 무너지지 않습니다.', `MaleText_loc4`='沃金侥幸逃过一死，但他不会忘记地狱咆哮的背叛所带来的伤痛。暗矛不死。', `MaleText_loc5`='沃金活下來了，但他卻忘不了地獄吼的背叛舉動所留下的痛楚。暗矛部族不會這樣滅亡的。', `MaleText_loc7`='Vol''jin sobrevivió, pero aún recuerda la traición de Grito Infernal. Los Lanza Negra nunca mueren.' WHERE `ID`=73887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님이 돌아오셨을 때, 전 그분이 바뀌었다는 걸 깨달았습니다. 그분의 눈에는 혁명의 불꽃이 일렁이고 있었지요!', `MaleText_loc4`='在他回归之后，我发现他变了。他的眼中燃烧着变革的光辉！', `MaleText_loc5`='當沃金回到我們身邊時，我感覺他已徹底地改變了，他的雙眼如今散發出推翻暴政的熾熱光芒!', `MaleText_loc7`='Cuando Vol''jin regresó, había cambiado. ¡El brillo de la revolución brillaba en sus ojos!' WHERE `ID`=73888;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주위를 둘러보십시오. 검은창 부족은 혁명을 준비하고 있습니다. 헬스크림에게 잊지 못할 악몽을 선사하기 위해서죠.', `MaleText_loc4`='现在，看看你的周围吧。暗矛起义军正在壮大。它将成为地狱咆哮的噩梦。', `MaleText_loc5`='現在看看你的四周，暗矛部族已經起身反抗。這會成為地獄吼最深邃的夢魘。', `MaleText_loc7`='Y ahora mira a tu alrededor. La rebelión de los Lanza Negra ha comenzado. La peor pesadilla de Grito Infernal.' WHERE `ID`=73889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='불꽃은 곧 불길이 되고, 불길은 화염이 될 것입니다. 그리고 그 화염은 더욱 격렬하게 타오르겠지요. 우리는 이글거리는 화염이 되어 오그리마의 정문을 향해 진격할 겁니다.', `MaleText_loc4`='星星之火可以燎原。我们将一路延烧至奥格瑞玛的大门前。', `MaleText_loc5`='暗矛部族燃起的微小火光蔓延成烈焰，然後化為...無情的獄火，我們要燒穿奧格瑪的大門。', `MaleText_loc7`='La chih''pa se convierte en llama. La llama se convierte en fuego. Y el fuego... en infierno. Vamos a reducir a cenizas las pueh''tas de Orgrimmar.' WHERE `ID`=73890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러기 위해서는 전쟁 물자를 확보해야 합니다. 석재, 목재, 석유, 그리고 고기. 이런 군수품이 많이 필요하지요.', `MaleText_loc4`='但我们必须为这架战争机器提供补给。石料、木材、原油和肉食——我们需要大量物资。', `MaleText_loc5`='但我們要打這場戰爭，會需要消耗大量的石材、木頭、燃油和肉，所以我們必須事先囤積大量的補給品。', `MaleText_loc7`='Pero tenemos que alimentar eh''ta máquina de guerra. Piedra, madera, aceite, carne: vamos a necesitar mucho de todo eso.' WHERE `ID`=73891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 활약해야 할 차례입니다, $G형제여:자매여;.', `MaleText_loc4`='这就是我们要用到你的地方了，$G兄弟:姐妹;。', `MaleText_loc5`='這正是我們需要你幫忙的地方，$G兄弟:姊妹;。', `MaleText_loc7`='Ahí es donde te necesitamos, colega.' WHERE `ID`=73892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진 님과 이야기하십시오. 마음을 단단히 먹는 게 좋을 겁니다. 보통 임무가 아닐테니까요.', `MaleText_loc4`='去吧，去跟沃金谈谈。你要做好准备。从现在起，我们对你的要求会比过去更高。', `MaleText_loc5`='去找沃金吧。你得做好準備，因為我們接著想請你協助的事務要比以往都困難的多。', `MaleText_loc7`='Ve, habla con Vol''jin. Prepárate. De ahora en adelante te pediremos más de lo que te hemos pedido hah''ta ahora.' WHERE `ID`=73893;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 배에 올라타고 있다! 갑판으로 가서 놈들을 쫓아내!', `MaleText_loc4`='部落快要爬上来了！快去甲板上帮忙御敌！', `MaleText_loc5`='部落登上船了!快去甲板支援，擊退他們!', `MaleText_loc7`='¡La Horda nos está abordando! ¡A cubierta! ¡Nuestro honor está en juego!' WHERE `ID`=73894;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그런 위험은 감수해야지. 하지만 만약 내가 죽거든... 아그라와 내 아들을 잘 부탁하네.', `MaleText_loc4`='我必须这么做。但是，如果我死了，请照顾好阿格娜和我儿子。', `MaleText_loc5`='這是我必須冒的風險。如果我被殺了，請照顧阿格拉和我的孩子。', `MaleText_loc7`='Es un riesgo que tendré que correr. Pero, si me matan, por favor, cuiden a Agra y a mi niño.' WHERE `ID`=73895;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잘 하셨습니다, $n. 호드에서 내분의 조짐이 보입니다. 가로쉬가 대규모의 트롤 저항군을 상대해야 할 처지에 놓였군요.', `FemaleText_loc4`='你做的很好，$n。看来部落内部已经矛盾重重了。加尔鲁什有一整支巨魔起义军要对付了。', `FemaleText_loc5`='做得好，$n。看來部落起了內亂，這下卡爾洛斯得要忙著面對食人妖反抗軍的全面襲擊了。', `FemaleText_loc7`='Lo has hecho bien, $n. Parece que se avecinan problemas en la Horda. Garrosh tiene toda una rebelión trol entre manos.' WHERE `ID`=73896;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 소문이 진짜란 말인가? 볼진이 살아 있고 가로쉬의 피를 원한다는 게?', `MaleText_loc4`='这么说传言是真的？沃金还活着，并回来向加尔鲁什复仇了？', `MaleText_loc5`='這麼說來謠言是真的囉?沃金不但沒死，而且還準備對付卡爾洛斯?', `MaleText_loc7`='¿Entonces los rumores son ciertos? ¿Vol''jin está vivo y sediento de la sangre de Garrosh?' WHERE `ID`=73897;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그래. 이건 얼라이언스에게 절호의 기회야. 트롤들이 가로쉬의 주의를 끌 동안 얼라이언스 주 함대는 전투 태세를 갖추면 될 거야. 무슨 말인지 알겠어, 설리?', `FemaleText_loc4`='没错。这正是联盟的大好机会。我们要利用巨魔为联盟主舰队的集结打掩护。你明白我的意思吧，苏利？', `FemaleText_loc5`='沒錯，這正是千載難逢的好機會。我們可以利用食人妖來分散他們的注意力，好讓我們集結聯盟的主力艦隊。你知道我在說什麼吧，蘇利?', `FemaleText_loc7`='Sí. Es justo la oportunidad que necesitaba la Alianza. Usaremos a los trols como distracción mientras la flota principal de la Alianza se reúne. ¿Entiendes lo que digo, Sully?' WHERE `ID`=73898;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐! 그렇다면 볼진을 돕자는 건가?', `MaleText_loc4`='等等！你是想让我们去帮助沃金吗？', `MaleText_loc5`='等等!你是說，我們要幫助沃金?', `MaleText_loc7`='¡Espera un segundo! ¿Estás sugiriendo que ayudemos a Vol''jin?' WHERE `ID`=73899;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진은 이제 막다른 곳에 몰렸어. 우리의 도움을 받아 그는 헬스크림의 요새를 뚫는 창이 되겠지. 적들이 서로 싸우기를 기다리는 거야. 결정적인 일격을 선사할 수 있을 때를 살펴보면서 말이야.', `FemaleText_loc4`='沃金已经没有退路了。有了我们的帮助，他就能成为破开地狱咆哮堡垒的那把“暗矛”。就让我们的敌人去自相残杀吧，我们只需在一边等待出击的机会即可。', `FemaleText_loc5`='沃金退回角落。有我們助他一臂之力，他就能化為利矛在地獄吼的要塞上面打開缺口。讓敵人自相殘殺，我們坐享其成，靜候攻擊時機。', `FemaleText_loc7`='Vol''jin está acorralado en una esquina. Con nuestra ayuda, se convertirá en la lanza que abra la fortaleza de Grito Infernal. Deja que nuestros enemigos se debiliten entre ellos, mientras nosotros esperamos nuestra oportunidad para atacar.' WHERE `ID`=73900;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 불난 집에 부채질! 마음에 들어. 그럼, 검은창 부족을 방문할 넉살 좋은 사람이 한 명 필요한데 말이지?', `MaleText_loc4`='多聪明的姑娘！煽风点火！我喜欢这主意。那么，我们中有哪个勇士敢去拜访一下暗矛部族呢？', `MaleText_loc5`='我喜歡這主意，煽風點火!那麼哪位勇士要去拜訪拜訪暗矛部族?', `MaleText_loc7`='Esa es mi chica, avivando el fuego. Me gusta. ¿Pero quién de nosotros es lo bastante valiente para hacerle una visita a los Lanza Negra?' WHERE `ID`=73901;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일단 난 빼고!', `MaleText_loc4`='不会吧！', `MaleText_loc5`='不准派我的寵物去就是!', `MaleText_loc7`='¡Eso no!' WHERE `ID`=73902;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것 좀 보게. 테라모어에서 온 얼라이언스 놈이군. 죽여 버려!', `MaleText_loc4`='看呐，伙计，又是从塞拉摩来的联盟渣滓。干掉它！', `MaleText_loc5`='你們看，有個塞拉摩的聯盟雜碎被沖上岸了，快殺了它!', `MaleText_loc7`='Mira, colega. La escoria de la Alianza ha salido de Theramore. ¡Mátalos!' WHERE `ID`=73903;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='잠깐! 무기를 내리게. 이... 침입자를 본 적이 있네.', `FemaleText_loc4`='等等！放下你们的武器。我认识这个家伙。', `FemaleText_loc5`='等等!放下你們的武器。我認得這個人。', `FemaleText_loc7`='¡Esperen! ¡Bajen las armas! $gLo:La; conozco.' WHERE `ID`=73904;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='볼진 님께 얼라이언스 사절 하나를 데리고 간다고 전하게.', `FemaleText_loc4`='去告诉沃金，我带来了一位来自联盟的特使。', `FemaleText_loc5`='去告訴沃金，我帶了一個聯盟的使者來見他。', `FemaleText_loc7`='Dile a Vol''jin que traigo a un embajador de la Alianza.' WHERE `ID`=73905;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='날 따라오게, $r.', `FemaleText_loc4`='跟我走，$r。', `FemaleText_loc5`='$r，跟我來。', `FemaleText_loc7`='Ven conmigo, $r.' WHERE `ID`=73906;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='허튼 짓은 안 하는 게 좋을 걸세. 우리가 좀... 신경이 곤두서 있거든. 전쟁 중이라서 말이야. 대족장과의 전쟁 말이지.', `FemaleText_loc4`='别让你的手离开我们的视线。最近大家都有些神经质。我们正在进行一场战争，一场与酋长本人的战争。', `FemaleText_loc5`='把手放在我們看得到的地方，大家因為戰事的關係都很緊張，我們在打一場對抗大酋長的仗。', `FemaleText_loc7`='Mantén las manos a la vih''ta. Todo el mundo eh''tá inquieto. Eh''tamos en guerra, una guerra contra el mismísimo Jefe de Guerra.' WHERE `ID`=73907;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림은 이전에 볼진 님을 죽이려고 했지. 하지만 트롤은 그렇게 쉽게 죽지 않아.', `FemaleText_loc4`='地狱咆哮已经派人来刺杀过沃金了。呵呵，巨魔可不是那么容易杀死的。', `FemaleText_loc5`='地獄吼那傢伙派人刺殺沃金，不過想殺死食人妖可沒有那麼簡單。', `FemaleText_loc7`='Grito Infernal ya trató de matar a Vol''jin. Je. No es tan fácil matar a un trol.' WHERE `ID`=73908;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그가 한 짓은 검은창 부족 전체를 적으로 돌렸을 뿐이야.', `FemaleText_loc4`='你问他干了什么？他激起了整个暗矛部族的怒火。', `FemaleText_loc5`='他幹了什麼好事?他讓整個暗矛部族怒火中燒。', `FemaleText_loc7`='¿Qué ha hecho? Ha deh''pertado la furia de la tribu Lanza Negra.' WHERE `ID`=73909;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='헬스크림은 볼진 님이 죽은 줄 알고 있었지. 그러다가 볼진 님이 센진 마을에 나타나자, 저항군을 짓밟으려 했네. 하지만 우리는 준비가 되어 있었지. 센진에서 코르크론 놈들을 격퇴하고 칼바위 언덕을 탈환했네. 하! 대족장의 코앞에서 말이야!', `FemaleText_loc4`='地狱咆哮本以为沃金已经死了，结果他却出现在森金村。然后酋长又试图绞杀起义军，但我们早有准备。我们已经在森金村击退了库卡隆，然后又攻占了剃刀岭。哈，就在酋长的鼻子底下打了个大胜仗！', `FemaleText_loc5`='沃金在森金村現身之前，地獄吼還以為沃金死了，接著大酋長想要出兵擊潰叛軍，不過我們已經嚴陣以待。我們擊退了森金村的柯爾克隆部隊，而且還在大酋長的面前奪下剃刀嶺。', `FemaleText_loc7`='Grito Infernal creía que Vol''jin eh''taba mueh''to, hah''ta que Vol''jin aparece en el Poblado Sen''jin. Entonces el Jefe de Guerra trata de aplastar la rebelión, pero eso lo eh''perábamos. Nos enfrentamos a los Kor''kron en Sen''jin, y deh''pués nos hicimos con Cerrotajo, ja, ¡delante de las narices del Jefe de Guerra!' WHERE `ID`=73910;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='마지막 목표만이 남아 있네. 오그리마.', `FemaleText_loc4`='现在，我们已经将目光投向了最终的战场——奥格瑞玛。', `FemaleText_loc5`='我們現在已轉向最終目標，那就是奧格瑪。', `FemaleText_loc7`='Ahora volvemos la vih''ta al premio final: Orgrimmar.' WHERE `ID`=73911;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스도 혁명에 동참하고 싶다고? 불가능한 건 아니지. 자네가 돕게. 우리는 전쟁 물자가 필요하다네. 석재, 목재, 석유, 그리고 고기. 군수품을 넉넉히 확보한 다음에 공격을 감행할 수 있겠지.', `FemaleText_loc4`='联盟想在奥格瑞玛开辟第二战线？可以。你们需要帮助，而我们需要物资：石料、木材、原油和肉食。只有这样，我们才有可能去攻打那座坚城。', `FemaleText_loc5`='聯盟想在奧格瑪開闢第二條戰線?我們有辦法，但是你要幫忙才行。我們需要補充一些資源:石材、木頭、燃油和肉。等到資源充足之後，我們才能朝敵人的大本營發動攻擊。', `FemaleText_loc7`='¿La Alianza un segundo frente en Orgrimmar? Podría ser. Tú puedes ayudarnos. Necesitaremos suminih''tros: piedra, madera, aceite, carne. Solo así podremos avanzar a la ciudad.' WHERE `ID`=73912;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 임무는 절대 만만한 게 아니라네, 이방인. 하지만 우리를 돕는다면, 볼진 님의 신뢰를 얻을 수 있겠지. 우리는 대족장의 땅에서 그에게 정면으로 맞설 것이네. 나약한 너희 얼라이언스도 그럴 수 있겠나? 아하하하하하!', `FemaleText_loc4`='这个任务可不适合胆小鬼，陌生人。但如果你帮助我们，沃金或许会慢慢信任你们。无论如何，你们总能削弱酋长对他自己领土的控制力。软趴趴的联盟能做到这一点吗？啊哈哈哈哈！', `FemaleText_loc5`='這項任務不適合膽小的傢伙，陌生人。不過要是你為我們出一份力，說不定可以漸漸贏得沃金的信任。不管怎樣，去破壞大酋長對領地的控制力。你覺得軟巴巴的聯盟辦得到嗎?哈哈哈哈哈哈哈!', `FemaleText_loc7`='Eh''ta no es tarea para flojos. Pero si nos ayudas, puede que Vol''jin empiece a confiar en ti. Sea como sea, conseguirías debilitar al Jefe de Guerra en sus propias tierras. ¿Crees que un blando de la Alianza podría hacerlo? ¡Ja, ja, ja!' WHERE `ID`=73913;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s|1이;가; |cFFF00000|Hspell:142320|h[빙하 얼리기 토템]|h|r을 소환합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s召唤了一个|cFFF00000|Hspell:142320|h[冰川冻气图腾]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s召喚了一個|cFFF00000|Hspell:142320|h[冰川凍結圖騰]|h|r!', `MaleText_loc7`='¡|TInterfaceIconsability_deathknight_remorselesswinters:20|t%s invoca un |cFFF00000|Hspell:142320|h[Tótem de Congelación glacial]|h|r!' WHERE `ID`=73914;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s|1이;가; |cFFF00000|Hspell:142306|h[분쇄된 대지]|h|r를 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s开始施放|cFFF00000|Hspell:142306|h[毁弃之土]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_fire_windsofwoe:20|t%s開始施展|cFFF00000|Hspell:142306|h[廢墟燼土]|h|r!', `MaleText_loc7`='¡|TInterfaceIconsspell_fire_windsofwoe:20|t%s comienza a lanzar |cFFF00000|Hspell:142306|h[Tierra en ruinas]|h|r!' WHERE `ID`=73915;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈다, 영웅이여! 천신들의 축복을 얻어내고, 그들이 제시한 시험도 통과했어.', `MaleText_loc4`='成功了，英雄！我们得到了至尊天神的祝福，完成了他们的挑战。', `MaleText_loc5`='我們成功了，英雄!我們得到聖獸的祝福，而且完成了祂們的挑戰。', `MaleText_loc7`='¡Lo logramos! Tenemos las bendiciones de los Celestiales y completamos sus desafíos.' WHERE `ID`=73916;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다음엔 뭘 해야 할지 알고 있다. 석공의 우둔함 꼭대기에서 만나자. 내가 준비해 둔 걸 보면 넌 무척 기뻐할 거야!', `MaleText_loc4`='我知道接下来该怎么做。回石匠之愚来找我——我为你准备了一个惊喜！', `MaleText_loc5`='我知道下一步該怎麼做。回巧匠之愚跟我碰面。看到我為你準備的東西你會很驚喜的!', `MaleText_loc7`='Sé cuál es nuestro próximo paso. Nos vemos en la cima de Locura del Albañil... ¡Tengo una sorpresa para ti que te va a encantar!' WHERE `ID`=73917;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하세요! 불모의 땅으로 빨리 가고 싶으신가요?', `MaleText_loc4`='嘿嘿嘿！你想快速前往贫瘠之地吗？', `MaleText_loc5`='嘿嘿嘿!你想找快速前往貧瘠之地的方法嗎?', `MaleText_loc7`='Eh, oye. ¿Estás buscando una forma rápida de viajar a los Baldíos?' WHERE `ID`=73918;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어디 가실 일이 있나요? 톱니항으로 가시는 길이라면 바로 여기서 쉽게 가실 수 있어요!', `MaleText_loc4`='你要去其他地方吗？如果那个“其他地方”是棘齿城，那我马上就能给你开辟一条快速通道！', `MaleText_loc5`='你想去哪呢?要是你想去的地方剛好是棘齒城的話，那我正好有辦法把你快速地送過去!', `MaleText_loc7`='¿Necesitas ir a algún lado? Si algún lado es Trinquete, ¡aquí mismo tengo la solución para ti!' WHERE `ID`=73919;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='만족하지 않으셨던 고객님은 한 분도 없었답니다! 오늘 채터스위치 여행사를 이용해 보세요!', `MaleText_loc4`='顾客满意度百分之百！今天就来试试跳闸旅行社的服务吧！', `MaleText_loc5`='用過的都說讚!要旅遊就找恰恰開關!', `MaleText_loc7`='¡Jamás he tenido un cliente insatisfecho! ¡Prueba Viajes Cotórrez hoy mismo!' WHERE `ID`=73920;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제 최신 순간이동기가 북부 불모의 땅으로 한 방에 모셔다드릴 거예요. 어떠세요?', `MaleText_loc4`='我的高新传送器可以将你直接送往北贫瘠之地。想试试吗？', `MaleText_loc5`='我有一台最先進的傳送器可以直接把你傳送到北貧瘠之地，你意下如何呢?', `MaleText_loc7`='Mi novedoso teletransporte te llevará directamente a Los Baldíos del Norte. ¿Qué me dices?' WHERE `ID`=73921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='톱니항으로 가고 싶습니다.', `MaleText_loc4`='我要去棘齿城。', `MaleText_loc5`='我想去棘齒城。', `MaleText_loc7`='Quiero viajar a Trinquete.', `FemaleText_loc1`='톱니항으로 가고 싶어요.', `FemaleText_loc4`='我要去棘齿城。', `FemaleText_loc5`='我想去棘齒城。', `FemaleText_loc7`='Quiero viajar a Trinquete.' WHERE `ID`=73922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아요, 어서 올라타세요, $r님. 거기 순간이동기 바로 위에요.', `MaleText_loc4`='很好，过来吧，$r，站到传送器上来。', `MaleText_loc5`='好的，快踏上去吧，$r，站到傳送器上。', `MaleText_loc7`='De acuerdo, sube, $r. Justo ahí en el teletransporte.' WHERE `ID`=73923;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 자, 자! 어서 순간이동기에 올라가세요. 오늘 손님이 아주 많다고요. 그러니까 서둘러주세요!', `MaleText_loc4`='走走走！到那个传送器上去。今天的客人很多，所以请你快一点！', `MaleText_loc5`='快快快!快踏上傳送器!今天還有很多客人，動作快一點!', `MaleText_loc7`='Vamos, vamos. Sube al teletransporte. Tengo un montón de clientes hoy, así que date prisa.' WHERE `ID`=73924;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 순간이동기에 올라가세요. 바로 톱니항으로 보내드리죠!', `MaleText_loc4`='站到那个传送器上去。棘齿城，马上就到！', `MaleText_loc5`='站上傳送器。棘齒城馬上就到!', `MaleText_loc7`='Sube al teletrasporte. Estarás en Trinquete en un periquete.' WHERE `ID`=73925;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 트롤들과 같이 일을 하는 걸 가로쉬의 떨거지들이 못마땅해 하더군.', `MaleText_loc4`='加尔鲁什手下的恶棍不让我继续跟巨魔合作了。', `MaleText_loc5`='卡爾洛斯的走狗不喜歡我跟食人妖打交道。', `MaleText_loc7`='A los peleles de Garrosh no les gustó que siguiese trabajando con trols.', `FemaleText_loc1`='내가 트롤들과 같이 일을 하는 걸 가로쉬의 떨거지들이 못마땅해 하더군.', `FemaleText_loc4`='加尔鲁什手下的恶棍不让我继续跟巨魔合作了。', `FemaleText_loc5`='卡爾洛斯的走狗不喜歡我跟食人妖打交道。', `FemaleText_loc7`='A los peleles de Garrosh no les gustó que siguiese trabajando con trols.' WHERE `ID`=73926;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장은 이견을 가지는 모든 자들을 가두었네. 우리 오크들까지 말이지!', `MaleText_loc4`='酋长把所有不同政见者都关押了起来，包括我们兽人！', `MaleText_loc5`='大酋長把所有反對他的人全都關了起來，連獸人也不例外!', `MaleText_loc7`='El Jefe de Guerra está encerrando a todos los disidentes. ¡Incluso a nosotros, los orcos!', `FemaleText_loc1`='대족장은 이견을 가지는 모든 자들을 가두었네. 우리 오크들까지 말이지!', `FemaleText_loc4`='酋长把所有不同政见者都关押了起来，包括我们兽人！', `FemaleText_loc5`='大酋長把所有反對他的人全都關了起來，連獸人也不例外!', `FemaleText_loc7`='El Jefe de Guerra está encerrando a todos los disidentes. ¡Incluso a nosotros, los orcos!' WHERE `ID`=73927;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬가 우리 오크에게조차 등을 돌리다니!', `MaleText_loc4`='我从没想过加尔鲁什会对兽人下手！', `MaleText_loc5`='沒想到卡爾洛斯竟然會對付獸人!', `MaleText_loc7`='¡Nunca pensé que Garrosh se volviese contra los orcos!', `FemaleText_loc1`='가로쉬가 우리 오크에게조차 등을 돌리다니!', `FemaleText_loc4`='我从没想过加尔鲁什会对兽人下手！', `FemaleText_loc5`='沒想到卡爾洛斯竟然會對付獸人!', `FemaleText_loc7`='¡Nunca pensé que Garrosh se volviese contra los orcos!' WHERE `ID`=73928;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제야 검은창 부족이 왜 반기를 드는지 이해하겠군!', `MaleText_loc4`='现在我明白暗矛部族为什么会反抗了！', `MaleText_loc5`='我終於瞭解暗矛為什麼要反抗了!', `MaleText_loc7`='¡Ahora entiendo por qué atacan los Lanza Negra!', `FemaleText_loc1`='이제야 검은창 부족이 왜 반기를 드는지 이해하겠군!', `FemaleText_loc4`='现在我明白暗矛部族为什么会反抗了！', `FemaleText_loc5`='我終於瞭解暗矛為什麼要反抗了!', `FemaleText_loc7`='¡Ahora entiendo por qué atacan los Lanza Negra!' WHERE `ID`=73929;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='몸으로 공격을 막아내 래시온을 보호하십시오!', `MaleText_loc4`='用你的身体为拉希奥挡住攻击！', `MaleText_loc5`='用你的身軀替怒西昂抵擋接下來的攻擊!', `MaleText_loc7`='¡Usa tu cuerpo como escudo para evitar que los ataques alcancen a Wrathion!' WHERE `ID`=73930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡 위론은 이 판다리아가 품은 지혜의 화신이지. 그녀가 무슨 이야기를 할지 들어보자.', `MaleText_loc4`='青龙是潘达利亚的智慧化身。我们来看看她会怎么说吧。', `MaleText_loc5`='玉蛟是潘達利亞的智慧化身。我們來聽聽她想說什麼吧。', `MaleText_loc7`='El Dragón de Jade es la encarnación de la sabiduría en Pandaria. Veamos lo que tiene para decirnos hoy.' WHERE `ID`=73931;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙의 환영이 래시온에게 시선을 집중하면 도발하십시오!', `MaleText_loc4`='死亡之翼的幻影锁定了拉希奥，快嘲讽他！', `MaleText_loc5`='死亡之翼的幻象在注視怒西昂，快嘲諷他!', `MaleText_loc7`='¡Provoca a la Visión de Alamuerte cuando se fije en Wrathion!' WHERE `ID`=73932;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하수인들아, 이 벌레들을 없애라!', `MaleText_loc4`='我的仆从们，消灭这些爬虫！', `MaleText_loc5`='我的元素們，消滅這些害蟲!', `MaleText_loc7`='¡Esbirros, acaben con estos insectos!' WHERE `ID`=73933;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이미 해당 유물을 획득했습니다! 연계 점수가 초기화됩니다...', `MaleText_loc4`='你已经拥有这件神器了！重置组合链……', `MaleText_loc5`='你已經收集過這個文物了!要重新收集組合獎勵所需的文物了...', `MaleText_loc7`='¡Ya tenías ese artefacto! Cadena de combo reiniciada...', `FemaleText_loc1`='이미 해당 유물을 획득했습니다! 연계 점수가 초기화됩니다...', `FemaleText_loc4`='你已经拥有这件神器了！重置组合链……', `FemaleText_loc5`='你已經收集過這個文物了!要重新收集組合獎勵所需的文物了...', `FemaleText_loc7`='¡Ya tenías ese artefacto! Cadena de combo reiniciada...' WHERE `ID`=73934;
