UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 개들이 배에 오르고 있다! 놈들을 몰아내!', `MaleText_loc4`='这些部落狗要爬上来了。击退他们！', `MaleText_loc5`='這些部落畜生盪到船上來了，擊退他們。', `MaleText_loc7`='Esos perros de la Horda nos están abordando. ¡Acabemos con ellos!' WHERE `ID`=73940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스 돼지들이 배에 오르고 있다! 놈들을 몰아내!', `MaleText_loc4`='这些联盟猪要爬上来了。击退他们！', `MaleText_loc5`='這些聯盟畜生盪到船上來了，擊退他們。', `MaleText_loc7`='Esos cerdos de la Alianza nos están abordando. ¡Acabemos con ellos!' WHERE `ID`=73941;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 버러지들이 함선에 올라 우리 보물을 훔쳐간다. 놈들을 쫓아내!', `MaleText_loc4`='这些恶棍要爬上来偷我们的财宝了。击退他们！', `MaleText_loc5`='這些惡徒盪到船上想偷走我們的財寶，快擊退他們!', `MaleText_loc7`='Esos rufianes nos están abordando para robar nuestro tesoro. ¡Acabemos con ellos!' WHERE `ID`=73942;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 더 오는군. 뜨거운 맛을 보여줘라!', `MaleText_loc4`='又有人上来了。挡住他们！', `MaleText_loc5`='更多敵人攻上船了，阻止他們!', `MaleText_loc7`='Llegan más a bordo. ¡Hay que detenerlos!' WHERE `ID`=73943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 부관이 온다. 놈을 막아!', `MaleText_loc4`='敌方上尉要登船了，击退他！', `MaleText_loc5`='敵人的中尉攻上船了，擊退他!', `MaleText_loc7`='Teniente enemigo tratando de abordar. ¡A por él!' WHERE `ID`=73944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어딜 도망가려고...', `MaleText_loc4`='稳住……', `MaleText_loc5`='沒有想像中的快嘛...', `MaleText_loc7`='No tan rápido...' WHERE `ID`=73945;
