UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적을 적함까지 밀어붙였군. 뱃머리를 돌리고 놈들의 폭탄을 훔쳐 적함을 산산조각 내라!', `MaleText_loc4`='我们把他们赶回自己船上去了。快跳过去，偷走他们的炸药，把他们的船炸成碎片！', `MaleText_loc5`='我們已經把敵人逼回他們的船上了。快盪過去偷他們的爆裂物，然後把他們炸成碎片!', `MaleText_loc7`='Los hemos hecho retroceder a su barco. ¡Es el momento idóneo para robar sus explosivos y hacerlos saltar por los aires!' WHERE `ID`=73948;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 정도면 정신 좀 차렸겠지! 이제 저 대포를 타고 놈들의 기함으로 이동해!', `MaleText_loc4`='总算狠狠教训了他们！现在，跳进那座火炮里去，集中瞄准他们的旗舰！', `MaleText_loc5`='知道厲害了吧!現在跳進那座火砲，前去集中攻擊他們的旗艦!', `MaleText_loc7`='¡Así aprenderán! ¡Ahora solo falta subir al cañón y apuntar a su nave principal!' WHERE `ID`=73949;
