UPDATE `locales_broadcast_text` SET `MaleText_loc1`='총알이 떨어졌어!', `MaleText_loc4`='我没弹药啦！', `MaleText_loc5`='我沒炸藥了!', `MaleText_loc7`='¡Me largo!' WHERE `ID`=73952;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 효과가 있는지 한 번 보자고!', `MaleText_loc4`='让我们看看这玩意儿有什么用吧！', `MaleText_loc5`='我們來試試這個的威力如何!', `MaleText_loc7`='¡Veamos cómo funciona esto!' WHERE `ID`=73953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드 놈들이 우리 함선에 침입했다. 모두 쓸어버려!', `MaleText_loc4`='停下，这些部落恶棍爬到我们船上来了。去解决他们！', `MaleText_loc5`='注意，這些部落雜碎已經登上我們的船了，殺光他們!', `MaleText_loc7`='Arrr, esos marineros de agua dulce de la Horda han conseguido subir al barco. ¡Encargaos de ellos!' WHERE `ID`=73954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이놈들이 우리 함선에 침입했다. 모두 쓸어버려!', `MaleText_loc4`='停下，这些恶棍爬到我们船上来了。去解决他们！', `MaleText_loc5`='注意，這些雜碎已經登上我們的船了，殺光他們!', `MaleText_loc7`='Arrr, esos marineros de agua dulce han conseguido subir al barco. ¡Encargaos de ellos!' WHERE `ID`=73955;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 여기 이 막힌 벽에서 일하던 중이었는데... 어, 젠장, 기억도 안 나네. 그런데 넌 누구야? 기어슬립은 어디 갔어?', `MaleText_loc4`='当时我们正在这里对付这堵墙，然后……额，我不记得了。那么，你是谁？轮滑去哪儿了？', `MaleText_loc5`='我們本來在想辦法搞定這面牆，接著..呃...我也記不得了。你到底是誰?輪滑人呢?', `MaleText_loc7`='Estábamos trabajando en este muro y... Bueno, la verdad es que no me acuerdo. De todos modos, ¿tú quién eres? ¿Dónde está Engranasuelto?' WHERE `ID`=73956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자, 이제는 아무 이상 없습니다. 설명해야 할 게 많습니다만...', `MaleText_loc4`='一切都很好。你瞧，要解释起来话可就长了……', `MaleText_loc5`='一切都很好，聽著，事情是這樣的...', `MaleText_loc7`='Todo está bien. Mira, hay demasiado que explicar...', `FemaleText_loc1`='저, 이제는 아무 이상 없어요. 설명해야 할 게 많은데요...', `FemaleText_loc4`='一切都很好。你瞧，要解释起来话可就长了……', `FemaleText_loc5`='一切都很好，聽著，事情是這樣的...', `FemaleText_loc7`='Todo está bien. Mira, hay demasiado que explicar...' WHERE `ID`=73957;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그럼 다 괜찮아진 거야?', `MaleText_loc4`='那么，警报解除了吗？', `MaleText_loc5`='問題都解決了嗎?', `MaleText_loc7`='¿Está todo claro ahora?' WHERE `ID`=73958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거 참 굉장한 폭발인데! 가서 확인해 보자고.', `MaleText_loc4`='这炸药可真够劲！我们进去检查一下吧。', `MaleText_loc5`='剛才爆炸的威力還真大!我們來去瞧瞧。', `MaleText_loc7`='¡Qué explosión! Vayamos a ver.' WHERE `ID`=73959;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무슨 커다란 상자 같아... 아마 골드가 가득 들어 있을 거야. 그게 다 우리 거라고!', `MaleText_loc4`='看起来像某种巨型箱子……可能还装满了金币。全归我们啦！', `MaleText_loc5`='這看起來是個超巨大的寶箱...裡頭可能裝滿了黃金，而且它是我們的!', `MaleText_loc7`='Parece una especie de cofre gigante... probablemente lleno de oro. ¡Y es todo nuestro!' WHERE `ID`=73960;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐... 어떻게 된 거지? 내 머리... 속에... 뭔가...', `MaleText_loc4`='出……什么事了？我脑子里……有某种……东西……', `MaleText_loc5`='發...發生了什麼事?我的...頭裡...似乎有...', `MaleText_loc7`='¿Qué... qué está pasando? Algo... en... mi cabeza...' WHERE `ID`=73961;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아아아아아아!', `MaleText_loc4`='啊啊啊！！！', `MaleText_loc5`='啊啊啊啊啊啊!', `MaleText_loc7`='¡Aaaaaaaaaaaaaaaaah!' WHERE `ID`=73962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번 참사에서 입은 손해를 회복하지 않으면, 난 알거지가 되고 말 거야.', `MaleText_loc4`='要是不能挽回在这次灾难中造成的损失，那我就要变成穷光蛋了。', `MaleText_loc5`='要是我沒有把這場災難中的損失給賺回來的話，我就要破產了。', `MaleText_loc7`='Me quedaré sin nada si no recupero las pérdidas de este desastre.' WHERE `ID`=73963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고블린을 도와서 멋진 유물들을 좀 가져와 봐. 그동안 내 친구들이 광산 입구를 정리하고 있을 테니까.', `MaleText_loc4`='帮帮我这个可怜的地精，为我收集一些珍贵遗物吧。与此同时，我的人会去清理矿洞入口的。', `MaleText_loc5`='幫幫哥布林的忙，快來挑幾樣高貴不貴的古董吧。我的手下會趁你在挑貨的時候幫忙清出通往礦坑的路。', `MaleText_loc7`='Ayuda a un goblin y recoge algunos artefactos elegantes. Mientras tanto, mis chicos limpiarán la entrada a la mina.' WHERE `ID`=73964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시간이 없어... 이 벽을 박살내 버리자!', `MaleText_loc4`='不能再浪费时间了……让我们把这堵墙炸成碎片吧！', `MaleText_loc5`='沒時間可浪費了...我們快炸毀這面牆!', `MaleText_loc7`='No hay tiempo que perder... ¡Volemos todo esto por los aires!' WHERE `ID`=73965;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='그 고양이 변장으로 젠타브라를 속일 수 있다고 생각하나? 기억하고 있겠네, $r.', `FemaleText_loc4`='你休想用那套猫皮伪装骗过老岑塔布拉。我会记住你的，$r。', `FemaleText_loc5`='靠那個貓咪偽裝騙不了贊塔布拉。$r，我會記住的。', `FemaleText_loc7`='No vas a engañar a la vieja Zen''tabra con eh''te disfraz de gato. Más vale que lo recuerdes, $r.' WHERE `ID`=73966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 도망가면 됩니다. 뛰세요!', `MaleText_loc4`='逃跑的机会来了。快跑啊！', `MaleText_loc5`='現在是你逃走的好時機，快跑!', `MaleText_loc7`='Es tu oportunidad de escapar. ¡Corre sin mirar atrás!', `FemaleText_loc1`='이제 도망가면 돼요. 뛰세요!', `FemaleText_loc4`='逃跑的机会来了。快跑啊！', `FemaleText_loc5`='現在是你逃走的好時機，快跑!', `FemaleText_loc7`='Es tu oportunidad de escapar. ¡Corre sin mirar atrás!' WHERE `ID`=73967;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='얼라이언스가 검은창 부족을 돕겠다고? 이런 날이 올 줄은 꿈에도 몰랐군.', `FemaleText_loc4`='联盟愿意帮助暗矛部族？我从未想过自己能活着看到这一天。', `FemaleText_loc5`='聯盟會幫助暗矛部族?沒想到竟然會有這麼一天。', `FemaleText_loc7`='¿La Alianza quiere ayudar a los Lanza Negra? Nunca pensé que viviría para ver eh''to.' WHERE `ID`=73968;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='고맙네, $r. 자네가 해준 일을 결코 잊지 않겠네.', `FemaleText_loc4`='我要感谢你，$r。我不会忘记你所做的一切。', `FemaleText_loc5`='謝了，$r。我不會忘記的。', `FemaleText_loc7`='Te lo agradezco, $r. No lo olvidaré.' WHERE `ID`=73969;
