UPDATE `locales_broadcast_text` SET `MaleText_loc1`='데스윙의 환영이 래시온에게 시선을 집중합니다. 그를 치유하십시오!', `MaleText_loc4`='死亡之翼的幻影锁定了拉希奥，快为他治疗！', `MaleText_loc5`='死亡之翼的幻象注視著怒西昂，快治療他!', `MaleText_loc7`='La Visión de Alamuerte se fija en Wrathion. ¡Sánalo!' WHERE `ID`=73989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 사령관이 전장에 나타났습니다.', `MaleText_loc4`='一名库卡隆指挥官出现在了战场上。', `MaleText_loc5`='柯爾克隆指揮官出現在戰場。', `MaleText_loc7`='Un comandante Kor''kron ha aparecido en el campo de batalla.', `FemaleText_loc1`='코르크론 사령관이 전장에 나타났습니다.', `FemaleText_loc4`='一名库卡隆指挥官出现在了战场上。', `FemaleText_loc5`='柯爾克隆指揮官出現在戰場。', `FemaleText_loc7`='Un comandante Kor''kron ha aparecido en el campo de batalla.' WHERE `ID`=73990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 날뛰는군.', `MaleText_loc4`='万灵非常不安。', `MaleText_loc5`='靈魂並不安份。', `MaleText_loc7`='Los eh''píritus eh''tán inquietos.' WHERE `ID`=73991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<볼진의 저항군이 주둔하고 있는 임시 기지에서 참을 수 없는 악취가 납니다. 트롤의 지도자는 당신에게 먼저 말을 꺼내도록 허락합니다. 그의 경비병들이 당신을 날카롭게 바라봅니다.>', `MaleText_loc4`='<沃金的临时义军营地里散发着令人难以忍受的恶臭。巨魔首领示意你先开口，而他的护卫们则警惕地盯着你。>', `MaleText_loc5`='<沃金臨時營地周圍的臭味令人難以忍受。這名食人妖首領讓你先說話，他的守衛同時在留意你的舉動。>', `MaleText_loc7`='<La pestilencia que rodea el improvisado campamento revolucionario de Vol''jin es insoportable. El líder trol te permite hablar en primer lugar. Mientras tanto sus guardias te observan atentamente.>' WHERE `ID`=73992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왜 검은창 부족이 가로쉬와 맞서고 있는 겁니까?', `MaleText_loc4`='暗矛部族为什么要反叛加尔鲁什？', `MaleText_loc5`='暗矛部族為什麼要反抗卡爾洛斯?', `MaleText_loc7`='¿Por qué se han rebelado los Lanza Negra contra Garrosh?', `FemaleText_loc1`='왜 검은창 부족이 가로쉬와 맞서고 있는 거죠?', `FemaleText_loc4`='暗矛部族为什么要反叛加尔鲁什？', `FemaleText_loc5`='暗矛部族為什麼要反抗卡爾洛斯?', `FemaleText_loc7`='¿Por qué se han rebelado los Lanza Negra contra Garrosh?' WHERE `ID`=73993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림은요? 그에게 호드란 뭡니까?', `MaleText_loc4`='地狱咆哮呢？部落对他来说意味着什么？', `MaleText_loc5`='那地獄吼呢?對他來說，部落算是什麼?', `MaleText_loc7`='¿Y qué hay de Grito Infernal? ¿Qué significa la Horda para él?', `FemaleText_loc1`='헬스크림은요? 그에게 호드란 뭐죠?', `FemaleText_loc4`='地狱咆哮呢？部落对他来说意味着什么？', `FemaleText_loc5`='那地獄吼呢?對他來說，部落算是什麼?', `FemaleText_loc7`='¿Y qué hay de Grito Infernal? ¿Qué significa la Horda para él?' WHERE `ID`=73994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 왜 당신을 도와야 합니까? 불모의 땅의 물자들을 우리가 가져가면요?', `MaleText_loc4`='我们为什么要帮助你？要是我们把贫瘠之地的补给都留给自己又会怎样？', `MaleText_loc5`='我們為什麼要幫你?你難道不怕我們就這樣拿走貧瘠之地的補給品嗎?', `MaleText_loc7`='¿Por qué debería ayudarles? ¿Y si nos quedamos con los suministros de los Baldíos para nosotros?', `FemaleText_loc1`='우리가 왜 당신을 도와야 하죠? 불모의 땅의 물자들을 우리가 가져가면요?', `FemaleText_loc4`='我们为什么要帮助你？要是我们把贫瘠之地的补给都留给自己又会怎样？', `FemaleText_loc5`='我們為什麼要幫你?你難道不怕我們就這樣拿走貧瘠之地的補給品嗎?', `FemaleText_loc7`='¿Por qué debería ayudarles? ¿Y si nos quedamos con los suministros de los Baldíos para nosotros?' WHERE `ID`=73995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<표정이 일그러지는 볼진>$b$b아무것도 모르는군. 자네에게 호드란 뭔가, $r? 병자? 돌연변이? 배신자? 악마의 피를 물려받은 자? 짐승? 난 자네들이 우리에 대해 어떻게 생각하는지 잘 안다네.$b$b내가 자네에게 진정한 호드가 뭔지 알려주지. 나와 스랄이 탄생시킨 호드를 말이야. 호드는 가족이라네. 그 어떤 역경 속에서도 가족은 서로를 돕는 법이지.$b$b헬스크림은 호드를 가족이라 생각하지 않네. 애초부터 그랬지.', `MaleText_loc4`='<沃金的脸愤怒地扭曲了起来。>$b$b你不明白。部落在你们眼里是什么？嗯？一群病夫？怪胎？叛徒？魔崽子？野兽？我知道你们是怎么说我们的。$b$b我来告诉你们部落是什么。部落是我和萨尔一手建立起来的。它是一个大家庭。当全世界都试图消灭我们时，这个家庭向我们伸出了援手。$b$b而地狱咆哮，他不懂这个家庭的意义。所以他也得不到家人的支持。', `MaleText_loc5`='<沃金面露怒容。>$b$b你不了解。$r，對你來說部落是什麼?嗯?身染重病的患者?外星人?背叛者?留著惡魔之血的傢伙?還是野獸?我知道你們是怎麼說我們的。$b$b我會告訴你，部落到底是什麼。我和索爾建立的部落，是個大家庭，是個大家族。當全世界想消滅我們的時候，這個大家庭接納我們，為我們撐腰。$b$b但是地獄吼他不把部落當成家人看待，從來沒有過。', `MaleText_loc7`='<Vol''jin frunce el ceño.>$b$bNo lo comprenderías. ¿Qué es para ti la Horda, $r? ¿Eh? ¿Enfermos? ¿Extranjeros? ¿Traidores? ¿Criaturas con sangre demoníaca? ¿Beh''tias? Sé lo que nos llaman.$b$bTe diré lo que es la Horda. La horda que Thrall y yo construimos. Es una familia. Cuando todo el mundo trata de acabar con nosotros, la familia viene a apoyarnos.$b$bGrito Infernal, él no lo entiende como una familia. Nunca tuvo una.' WHERE `ID`=73996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그에게 호드는 곧 오크이고, 오크의 힘을 기르는 수단일 뿐일세. 그는 마치 방금 어둠의 문을 통과한 듯한 사고방식을 지니고 있지. 자신의 앞을 가로막거나 자신과 다르다고 여기는 것들은 모조리 죽여버린다네.$b$b<세 손가락으로 자신의 흉터를 만지는 볼진>$b$b마치 미친 개와 같지. 그래, 그의 곁에서 싸운 적이 있기는 하지. 하지만 놈을 지도자로 인정하라고? 그건 곧 화를 불러오는 길일세. 가로쉬는 자신히 원하는 자들만을 골라 전쟁을 시작했지. 나와 우리 형제들을 옆으로 밀어내고 말이야. 다른 자들은 필요 없다고 생각하지. 하지만 그는 틀렸다네.$b$b곧 가로쉬는 알게 될 걸세. 가족을 배신하면 어떻게 되는지.', `MaleText_loc4`='对他来说，部落的全部意义便是兽人，以及如何壮大兽人的力量。他就像是刚刚穿过黑暗之门。任何挡他路的人，任何与他意见相左的人，都得闭嘴。$b$b<沃金用只有三根手指的手摸了摸身上的刀疤。>$b$b他就像一条疯狗。噢，没错，我是与地狱咆哮并肩战斗过。但要让他来掌管一切？你简直是在自找麻烦。他热衷于搞自己的小团体，发动他自己的战争，将我们这些老兄弟丢在一边……他觉得自己用不着任何人帮忙。但是，他错了。$b$b他会明白：一个人永远无法与这个大家庭对抗。', `MaleText_loc5`='對他來說，部落只是獸人建立勢力的手段，就好像他剛從傳送門過來一樣。只要有人敢擋住他的路，有人想法不一樣，他就會讓那些人閉嘴。$b$b<沃金伸出那隻只有三根指頭的手撫摸自己的傷疤。>$b$b他就像隻瘋狗一樣。喔，我當然會和他並肩作戰，不過讓他掌權?那是在自找麻煩。他只依個人好惡開戰，把我的兄弟擠到一旁...他不覺得他需要任何人，但是他錯了。$b$b他會學到教訓的:千萬不要招惹家人。', `MaleText_loc7`='Pa'' él, la Horda solo tiene que ver con los orcos, y con aumentar el poder de los orcos. Como si acabase de salir del poh''tal. Si alguien se opone a él o piensa de modo diferente, lo encierra.$b$b<Vol''jin se pasa la mano de tres dedos por la cicatriz.>$b$bEs igual que un perro rabioso. Oh, he luchado junto a Grito Infernal en la guerra, desde luego. ¿Pero poneh''lo al mando? Eso es buscar problemas. Elige a sus favoritos, comienza su guerra, apah''ta a mis hermanos... Cree que no necesita a nadie más. Pues se equivoca.$b$bY va a aprender la lección: nunca enfades a la familia.' WHERE `ID`=73997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<역겹고 뜨거운 숨결을 뱉으며 미친 듯 웃는 볼진>$b$b오, 그래 다른 계획이 있다고? 나도 다른 계획이 있다네. 네놈들 혼자 오그리마를 공격하게 내버려두는 거지. 얼마나 고생할지 한번 보고 싶군. 그리고 도시에 시체가 즐비할 때 내 어둠사냥꾼들이 들이닥치는 거지. 코르크론이든 얼라이언스든 모두 죽인 다음에 실바나스에게 넘기면 되겠군. 흠! 우리 부족에서는 사상자가 훨씬 덜 발생하겠어!$B$B음? 이 계획이 마음에 안 드나? 그럼 처음 계획으로 가는 수밖에. 함께 힘을 합치는 거지.$b$b서로를 좋아할 필요도 없고 말이야.', `MaleText_loc4`='<沃金笑了起来，带着恶臭的灼热呼吸直往你的鼻孔里钻。>$b$b噢，你有其他方案？我这儿正好也有一个备用方案。我就让你们自己去围攻奥格瑞玛。看看你们能打成什么样。等到城里堆满了尸体时，我再派出暗影猎手攻进去，干掉剩下的人，包括库卡隆和联盟，然后把你们的死者交给希尔瓦娜斯。哼！这么一来，我还可以保住许多暗矛部族同胞的性命。$B$B嗯？你不喜欢这个方案？那我们还是来谈谈第一个方案吧。我们合作。$b$b这并不需要我们喜欢彼此。', `MaleText_loc5`='<沃金咯咯地笑著，他呼出滿嘴的溫熱臭氣刺痛你的鼻子。>$b$b喔，有其他建議嗎?我也想到一個計畫。我讓你們自己去攻打奧格瑪，看看你們有多少能耐。等滿城滿谷的屍體堆積如山，我再派暗影獵手殺光剩下的人，像是柯爾克隆呀聯盟呀，最後把你們的屍體交給希瓦娜斯。喔喔!這樣一來我就能保存暗矛部族的兵力!$B$B啊?你不喜歡這個計畫?那這樣好了，還是照原本說的去做，我們聯手吧。$b$b我們沒什麼必要去喜歡彼此。', `MaleText_loc7`='<Vol''jin suelta una carcajada, y la pestilencia de su aliento llega hasta tus fosas nasales.>$b$bOh, ¿tienes otro plan? Yo también. dejo que asedien Orgrimmar solos. A ver lo que consiguen. Y una vez que la ciudad eh''té llena de cadáveres, entonces entran mis cazadores de las Sombras. Nos llevamos lo que quede y matamos a los Kor''kron y a la Alianza indih''tintamente. Entrego sus cadáveres a Sylvanas. ¡Mmm! ¡Salvo muchas vidas Lanza Negra con este plan!$B$B¿Mmnn? ¿No te guh''ta? Entonces seguimos con el primer plan. Trabajamos juntos.$b$bNi siquiera tenemos que guh''tarnos mutuamente.' WHERE `ID`=73998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에서 당신에게 무슨 일이 일어났습니까?', `MaleText_loc4`='你在潘达利亚发生了什么事？', `MaleText_loc5`='你在潘達利亞遭遇了什麼事情?', `MaleText_loc7`='¿Qué te pasó en Pandaria?', `FemaleText_loc1`='판다리아에서 당신에게 무슨 일이 일어났죠?', `FemaleText_loc4`='你在潘达利亚发生了什么事？', `FemaleText_loc5`='你在潘達利亞遭遇了什麼事情?', `FemaleText_loc7`='¿Qué te pasó en Pandaria?' WHERE `ID`=73999;
