UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 움직임이 안 좋았어, 친구. 아아아주우 안 좋았다고.', `MaleText_loc4`='噢，这种行为可不好，伙计。非常不好。', `MaleText_loc5`='兄弟，那樣真的很糟糕。超爛爛爛爛的。', `MaleText_loc7`='Esa ha sido una maniobra muy mala. Muuuuy mala.' WHERE `ID`=74017;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 개의 성소에서 다시 만나자, 용사여.', `MaleText_loc4`='我会在祭坛那里等你的，勇士。', `MaleText_loc5`='我會在四位天尊的寺廟跟你碰面，勇士。 ', `MaleText_loc7`='Me encontraré contigo en cada uno de los cuatro altares.' WHERE `ID`=74018;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기억해라. 성소 네 곳을 모두 찾아가야 하지만, 시험은 네 개 중 하나만 통과하면 된다는 걸.', `MaleText_loc4`='记住，我们要拜访所有四个祭坛，但只要完成一个挑战就够了。', `MaleText_loc5`='記住，我們必須參訪全部四座寺廟，但我們只需要完成四個挑戰的其中之一。', `MaleText_loc7`='Recuerda: debemos visitar los cuatro pero solo necesitamos completar UNO de los cuatro desafíos.' WHERE `ID`=74019;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그러니 네가 가진 능력에 가장 어울리는 시험을 선택해라.', `MaleText_loc4`='所以，选择最适合你天赋的挑战吧。', `MaleText_loc5`='選擇一個最適合你獨特天賦的挑戰吧。', `MaleText_loc7`='Elige el desafío más apropiado para tus habilidades particulares.' WHERE `ID`=74020;
