UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가서 일해! 이 하찮은 그런트 놈아! 반란군 떨거지들과 나약해 빠진 얼라이언스 놈들은 우릴 막을 수 없다!', `MaleText_loc4`='快回去干活，你们这些可悲的畜生！一小撮叛徒和联盟懦夫阻挡不了我们！', `MaleText_loc5`='你們這群可憐的蠻兵，快去幹活兒!一大群叛軍跟聯盟肉腳是擋不住我們的!', `MaleText_loc7`='¡Volved al trabajo, patéticos brutos! ¡Un puñado de rebeldes y de flojos de la Alianza no va a detenernos!' WHERE `ID`=74046;
