UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF0000FF피로 얼룩진 설원 대기열에 등록합니다.|r', `MaleText_loc4`='|cFF0000FF排队等待雪山血战场景战役。|r', `MaleText_loc5`='加入|cFF0000FF血染滄雪|r佇列。', `MaleText_loc7`='|cFF0000FFHaz cola para Sangre en la Nieve.|r', `FemaleText_loc1`='|cFF0000FF피로 얼룩진 설원 대기열에 등록합니다.|r', `FemaleText_loc4`='|cFF0000FF排队等待雪山血战场景战役。|r', `FemaleText_loc5`='加入|cFF0000FF血染滄雪|r佇列。', `FemaleText_loc7`='|cFF0000FFHaz cola para Sangre en la Nieve.|r' WHERE `ID`=74083;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFF0000FF판다리아의 검은 심장 대기열에 등록합니다.|r', `MaleText_loc4`='|cFF0000FF排队等待潘达利亚的黑暗之心场景战役。|r', `MaleText_loc5`='加入|cFF0000FF潘達利亞的黑暗之心|r佇列。', `MaleText_loc7`='|cFF0000FFHaz cola para el Corazón Oscuro de Pandaria.|r', `FemaleText_loc1`='|cFF0000FF판다리아의 검은 심장 대기열에 등록합니다.|r', `FemaleText_loc4`='|cFF0000FF排队等待潘达利亚的黑暗之心场景战役。|r', `FemaleText_loc5`='加入|cFF0000FF潘達利亞的黑暗之心|r佇列。', `FemaleText_loc7`='|cFF0000FFHaz cola para el Corazón Oscuro de Pandaria.|r' WHERE `ID`=74084;
