UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신과 설리는 왜 여기에 있습니까?', `MaleText_loc4`='你和苏利来这里做什么？', `MaleText_loc5`='你跟蘇利為什麼跑來這裡?', `MaleText_loc7`='¿Por qué están aquí fuera Sully y tú?', `FemaleText_loc1`='당신과 설리는 왜 여기에 있죠?', `FemaleText_loc4`='你和苏利来这里做什么？', `FemaleText_loc5`='你跟蘇利為什麼跑來這裡?', `FemaleText_loc7`='¿Por qué están aquí fuera Sully y tú?' WHERE `ID`=74086;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='국왕 폐하께서는 가로쉬의 정신나간 계획을 반드시 저지하라고 하셨습니다. 무고한 사람들이 계속해서 죽어가고 있습니다.$b$b우리는 오그리마 방어선의 취약점을 탐색하고 있습니다. 얼라이언스 군대가 이득을 얻을 수 있을 취약점 말이죠.$b$b하지만 아쉽게도, 가로쉬가 준비를 철저히 해둔 것 같군요. 코르크론의 수를 크게 늘렸고 놈들을 사나운 전쟁 기계로 만들고 있습니다.', `FemaleText_loc4`='国王陛下不想让加尔鲁什继续他那疯狂的战役了。它已经吞噬了太多无辜的生命。$b$b我们是来寻找奥格瑞玛的防线弱点的，那种能够为联盟部队所用的弱点。$b$b不幸的是，加尔鲁什显然也没闲着。他已经加快了库卡隆的征兵速度，并将他们变成了彻头彻尾的战争机器。', `FemaleText_loc5`='大君主不打算讓卡爾洛斯這場狂亂的戰爭繼續下去。已經有太多無辜的性命死去。$b$b我們來此是要找出奧格瑪防禦上的弱點，找出能讓聯盟部隊佔有優勢的缺口。$b$b不幸的是，看來卡爾洛斯也不是笨蛋，他加快動作為柯爾克隆招募了許多新血，還把他們變成全副武裝的悍將。', `FemaleText_loc7`='Su Majestad no tiene ninguna intención de permitir que Garrosh continúe con su campaña demencial. Está costando demasiadas vidas inocentes.$b$bEstamos buscando puntos vulnerables en las defensas de Orgrimmar. El tipo de puntos débiles de los que el ejército de la Alianza podría sacar provecho.$b$bPor desgracia, parece que Garrosh no ha estado precisamente desocupado. Ha aumentado el número de reclutas Kor''kron y los ha convertido en máquinas de guerra impecables.' WHERE `ID`=74087;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='코르크론은 원래 대족장을 수호하고 그의 명령을 수행하는 정예 오크들이었습니다.$b$b하지만 이제 저들은 그저 뛰어난 학살자일 뿐이죠. 가로쉬의 사병으로서요.', `FemaleText_loc4`='他们原本是一支由精锐兽人组成的卫队，负责保护酋长的安全并执行他的命令。$b$b而现在，他们变成了一支由训练有素的屠夫组成的军队，加尔鲁什的私人军队。', `FemaleText_loc5`='柯爾克隆原本是直屬大酋長的獸人精英集團，擔任護衛之職，同時是大酋長的命令執行人。$b$b如今，他們受過嚴密訓練，變成難以想像的毀滅者，成為卡爾洛斯個人的私兵。', `FemaleText_loc7`='Eran una banda de élite orca creada para servir al Jefe de Guerra como protectores y sicarios a sus órdenes.$b$bAhora son un ejército de destructores entrenados a la perfección. La legión personal de Garrosh.' WHERE `ID`=74088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론이 뭡니까?', `MaleText_loc4`='库卡隆是什么？', `MaleText_loc5`='什麼是柯爾克隆?', `MaleText_loc7`='¿Qué son los Kor''kron?', `FemaleText_loc1`='코르크론이 뭔가요?', `FemaleText_loc4`='库卡隆是什么？', `FemaleText_loc5`='什麼是柯爾克隆?', `FemaleText_loc7`='¿Qué son los Kor''kron?' WHERE `ID`=74089;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은폐 닭이 오작동하면 큰일인데. 요 근래에 계속 말썽이라서 말이야.', `MaleText_loc4`='但愿这只隐身小鸡不会出什么岔子。她最近不太对劲。', `MaleText_loc5`='這台老舊的隱蔽力場雞最近才開始熱身，希望別在這時出問題。', `MaleText_loc7`='Más vale que este pollo de invisibilidad no falle. Últimamente está raro.' WHERE `ID`=74090;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='왕과 의회 이야기를 다시 듣고 싶습니다...', `MaleText_loc4`='再跟我说说国王与议会的故事吧……', `MaleText_loc5`='再告訴我關於王者與議會的事情...', `MaleText_loc7`='Vuelve a contarme lo del Rey y el Consejo...', `FemaleText_loc1`='왕과 의회 이야기를 다시 듣고 싶어요...', `FemaleText_loc4`='再跟我说说国王与议会的故事吧……', `FemaleText_loc5`='再告訴我關於王者與議會的事情...', `FemaleText_loc7`='Vuelve a contarme lo del Rey y el Consejo...' WHERE `ID`=74091;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='트롤들이 쇠사슬에 묶인 채 호송당하는 걸 봤네. 왜 오크들이 트롤들을 수감해놓고 있는 거지?', `MaleText_loc4`='我好像看见一些带着镣铐的巨魔被押走了。兽人为什么要给巨魔戴镣铐，还要押着他们走呢？', `MaleText_loc5`='我剛剛好像看到有食人妖被鐵鍊拴住押送到什麼地方去。獸人怎麼會這樣子對待食人妖呀?', `MaleText_loc7`='Creo que he visto trols acarreados y encadenados. ¿Por qué querrían los orcos encadenar a los trols?' WHERE `ID`=74092;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='은폐 닭 하나에 의지해서 적 진영의 한가운데에 있는 처지라. 이런 상황에 익숙해지려고 하는걸.', `MaleText_loc4`='藏身于敌军腹地，只靠这只隐身小鸡来保护我们。这已经变成我最新的日常工作了！', `MaleText_loc5`='身處敵軍陣營深處，然後身邊只有這隻隱蔽力場雞在保護我們。這就是我的新人生常態啊!', `MaleText_loc7`='Sentarme en el medio de las fuerzas enemigas sin más defensa que este pollo de invisibilidad se ha convertido en lo más normal últimamente.' WHERE `ID`=74093;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장과 어둠 이야기를 다시 듣고 싶습니다...', `MaleText_loc4`='再跟我说说酋长与黑暗的故事吧……', `MaleText_loc5`='再告訴我關於大酋長與黑暗的事情...', `MaleText_loc7`='Vuelve a contarme lo del Jefe de Guerra y la Oscuridad...', `FemaleText_loc1`='대족장과 어둠 이야기를 다시 듣고 싶어요...', `FemaleText_loc4`='再跟我说说酋长与黑暗的故事吧……', `FemaleText_loc5`='再告訴我關於大酋長與黑暗的事情...', `FemaleText_loc7`='Vuelve a contarme lo del Jefe de Guerra y la Oscuridad...' WHERE `ID`=74094;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드가 호젠을 데리고 왔다고? 판다리아에서 놈들을 지겹도록 만났을 텐데?', `MaleText_loc4`='部落带回来一只猢狲？！他们在潘达利亚还没有受够那些家伙吗？', `MaleText_loc5`='部落帶了隻猴人回來!?他們在潘達利亞做的還不夠嗎?', `MaleText_loc7`='¡¿La Horda se ha traído un hozen?! ¿No tenían bastante con los que encontraron en Pandaria?' WHERE `ID`=74095;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 장소에 이렇게나 많은 코르크론이 모인 것은 처음 봤다네!$b$b정말 사납고 화나 보이는군. 징집령을 확대시킨 모양이야.', `MaleText_loc4`='我以前从没在一个地方见过那么多库卡隆！$b$b那些兽人总是又暴躁又愤怒。他们肯定扩大了征兵规模。', `MaleText_loc5`='我從未看過這麼多柯爾克隆部隊聚集在同一個地方!$b$b這些獸人看起來渾身怒意、兇悍無比，想必是大幅提高了募兵人數。', `MaleText_loc7`='¡Nunca había visto tantos Kor''kron juntos!$b$bEsos orcos son lo más feroz que existe, y siempre están enfadados. Deben de haber mejorado su programa de reclutamiento.' WHERE `ID`=74096;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='프로젝트 C4T는 어디에서 온 겁니까?', `MaleText_loc4`='C4T计划是从哪儿来的？', `MaleText_loc5`='專案C4T是從哪冒出來的?', `MaleText_loc7`='¿De dónde vino Proyecto G4T0?', `FemaleText_loc1`='프로젝트 C4T는 어디에서 온 건가요?', `FemaleText_loc4`='C4T计划是从哪儿来的？', `FemaleText_loc5`='專案C4T是從哪冒出來的?', `FemaleText_loc7`='¿De dónde vino Proyecto G4T0?' WHERE `ID`=74097;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='장화?! 나만의 걸작이지. 양말이 다음으로 말이야. 양말이가 저 세상에서 편히 쉬기를. 좀 더 내구성이 높은 친구가 필요했거든.$b$b앰버가 장화를 이번 임무에서 사용하자고 결정했네. 그러니 실수로 망가뜨리거나 하지 말게!', `MaleText_loc4`='老靴子？！它可是我的杰作。自从袜子死后，愿它安息，我需要一个更加耐用的小伙伴。$b$b都是安玻想出来要用它来执行这个任务的，所以你千万别把它炸坏了！', `MaleText_loc5`='你是說鞋貓嗎?!它可是我的作品喔。在襪子之後，我需要更強壯的夥伴，願牠能安息。$b$b現在是琥珀決定要在我們的任務中使用鞋貓，所以你在操縱的時候別把它給炸了!', `MaleText_loc7`='¡¿El viejo Botas?! Es una creación exclusivamente mía. Después de Calcetines, descanse en paz, necesitaba un compañero más duradero.$b$bFue Amber la que decidió que lo usásemos para nuestra misión, ¡así que trata de no volarlo por los aires!' WHERE `ID`=74098;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 망할!', `FemaleText_loc4`='终于解脱了！', `FemaleText_loc5`='太好了!', `FemaleText_loc7`='¡Hasta nunca!' WHERE `ID`=74099;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나랄리는 더욱 고통스럽게 죽어 마땅한데!', `MaleText_loc4`='纳拉利死不足惜！', `MaleText_loc5`='納拉里真是糟透了!', `MaleText_loc7`='¡Narali se merecía algo peor!' WHERE `ID`=74100;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잘 왔다, 용사여!', `MaleText_loc4`='欢迎回来，英雄！', `MaleText_loc5`='歡迎歸來，勇士!', `MaleText_loc7`='¡Te doy la bienvenida otra vez!' WHERE `ID`=74101;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천신과의 일은 정말 잘 되었군. 그들이 얼마나 수다스러운지 봤나?', `MaleText_loc4`='你表现得很好。没想到至尊天神居然都这么啰嗦。', `MaleText_loc5`='在天尊們那裡表現得很好。沒想到祂們那麼嘮叨吧?', `MaleText_loc7`='Excelente trabajo con los Celestiales. ¿Puedes creer que hablaran tanto?' WHERE `ID`=74102;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 그냥 천신들이 조용히 축복을 내려주길 바랐는데, 참 끝도 없이 재잘거리더군.', `MaleText_loc4`='我以为他们会给我们奖励，结果他们一直唠叨个不停。', `MaleText_loc5`='我只希望祂們趕快把獎勵給我們，但是祂們就一直說一直說一直說。', `MaleText_loc7`='Yo nada más quería que nos dieran nuestra recompensa, pero ellos no paraban de hablar y hablar y hablar y hablar.' WHERE `ID`=74103;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 미안하다... 어디까지 얘기했지? 아, 그래! 선물이 있다.', `MaleText_loc4`='抱歉——我们说到哪儿了？噢，对了！我有东西要给你：', `MaleText_loc5`='抱歉，我說到哪了?噢對，我有東西要給你:', `MaleText_loc7`='Lo siento... ¿En qué estábamos? ¡Ah, sí! Tengo algo para ti:' WHERE `ID`=74104;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 판다리아의 천신들이 우리의 원대한 성전을 지원한다! 보아라...', `MaleText_loc4`='潘达利亚的诸神支持着我们伟大的事业！看看吧：', `MaleText_loc5`='潘達利亞的靈魂們都支援我們的偉大聖戰!看好了:', `MaleText_loc7`='¡Los espíritus mismos de Pandaria nos apoyan en esta gran cruzada! Contempla:' WHERE `ID`=74105;
