UPDATE `locales_broadcast_text` SET `MaleText_loc1`='옥룡에게서 지혜를 얻었다...', `MaleText_loc4`='青龙之智。', `MaleText_loc5`='來自玉蛟的智慧。', `MaleText_loc7`='La sabiduría del Dragón de Jade.' WHERE `ID`=74107;
