UPDATE `locales_broadcast_text` SET `MaleText_loc1`='주학은... 빛나는 희망을 우리에게 허락했지! 더 나은 세상을 위해!', `MaleText_loc4`='还有朱鹤的，对一个更美好世界的希望寄托！', `MaleText_loc5`='至於來自紅鶴的則是一盞希望世界更好的明燈!', `MaleText_loc7`='Y de la Gran Grulla, ¡un faro luminoso de esperanza por un mundo mejor!' WHERE `ID`=74109;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리의 세상을 위해.', `MaleText_loc4`='我们的世界。', `MaleText_loc5`='我們的世界。', `MaleText_loc7`='Nuestro mundo.' WHERE `ID`=74110;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 준비됐다!', `MaleText_loc4`='瞧！它近在咫尺。', `MaleText_loc5`='來吧!已經完成了。', `MaleText_loc7`='¡Ya! Está listo.' WHERE `ID`=74111;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 보급품을 추가로 얻으려면 짐마차를 호위하십시오!', `MaleText_loc4`='护送车队以获取额外的库卡隆补给品！', `MaleText_loc5`='護送車隊，獲得更多柯爾克隆補給品!', `MaleText_loc7`='¡Escolta caravanas para ganar suministros Kor''kron adicionales!' WHERE `ID`=74113;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론 보급품을 추가로 얻으려면 적군의 지휘관을 처치하십시오!', `MaleText_loc4`='击败敌方指挥官以获取额外的库卡隆补给品！', `MaleText_loc5`='擊敗敵方指揮官，獲得更多柯爾克隆補給品!', `MaleText_loc7`='¡Derrota a comandantes enemigos para ganar suministros Kor''kron adicionales!' WHERE `ID`=74114;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스가 올라탄다! 갑판으로 가서 명예를 걸고 싸워라!', `MaleText_loc4`='联盟要登船了！快到甲板上去，为荣耀而战吧！', `MaleText_loc5`='聯盟登上船了!快去甲板支援，為了榮耀而戰!', `MaleText_loc7`='¡La Alianza nos está abordando! ¡A cubierta! ¡Debemos defender nuestro honor!' WHERE `ID`=74115;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 시험을 받아들이겠다면 징을 울려라. 그게 아니라면 여기 더는 볼일이 없다.', `MaleText_loc4`='如果你想接受挑战，就去敲响挑战之锣吧。否则，我们就到此为止吧。', `MaleText_loc5`='如果你接受這項挑戰，那就敲鑼。不接受的話，那這邊沒我們的事情了。', `MaleText_loc7`='Haz sonar el gong si quieres aceptar el desafío. Si no, hemos terminado por ahora.' WHERE `ID`=74116;
