UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어라, 너는 그 냄새나는 염소가 아니잖아! 킬렉에게 원하는 게 뭐야?', `MaleText_loc4`='嘿，你不是那只臭山羊！你找基尔里克做什么？', `MaleText_loc5`='喂，你不是那頭臭山羊!你找基瑞克幹嘛?', `MaleText_loc7`='¡Eh, no eres tan cabra apestosa! ¿Qué quieres de Kil''rek?' WHERE `ID`=74119;
