UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전시물에는 손대지 마십시오.', `MaleText_loc4`='不许触摸展品。', `MaleText_loc5`='不許觸摸展品。', `MaleText_loc7`='No toques la exposición.' WHERE `ID`=74121;
