UPDATE `locales_broadcast_text` SET `MaleText_loc1`='관람 규칙을 엄격히 준수해 주십시오.', `MaleText_loc4`='画廊的规定必须严格遵守。', `MaleText_loc5`='請嚴格遵守畫廊的規定。', `MaleText_loc7`='Las normas de la galería se cumplirán sin excepción.' WHERE `ID`=74123;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 얼라이언스 쓰레기들을 처치해라! 호드를 위하여!', `MaleText_loc4`='干掉这些联盟渣滓！为了部落！', `MaleText_loc5`='殺掉這些聯盟廢物!為了部落而戰!', `MaleText_loc7`='¡Muerte a esa escoria de la Alianza! ¡Por la Horda!' WHERE `ID`=74124;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이봐 일꾼, 여기 얼쩡거리지 마라!', `MaleText_loc4`='滚开，乡巴佬！', `MaleText_loc5`='賤民，別擋路!', `MaleText_loc7`='¡Aparta de mi camino, campesino!' WHERE `ID`=74125;
