UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드가 온 아제로스를 지배하리라.', `MaleText_loc4`='真正的部落将统治全艾泽拉斯。', `MaleText_loc5`='正統部落會統治整個艾澤拉斯。', `MaleText_loc7`='La auténtica Horda gobernará todo Azeroth.' WHERE `ID`=74127;
