UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리는 우리 거야! 대포에 올라 계속 공격해!', `MaleText_loc4`='我们胜利了！快到火炮那里去，加强攻势！', `MaleText_loc5`='我們贏了!現在跳進去大砲，趁勝追擊!', `MaleText_loc7`='¡La victoria es nuestra! ¡El cañón nos servirá para reforzar el ataque!' WHERE `ID`=74129;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 일은 아직 끝나지 않았다. 이 망토는 너에게 천신의 힘을 허락할 것이야.', `MaleText_loc4`='我还没有全部完成。这件斗篷能带给你至尊天神的力量。', `MaleText_loc5`='我的作品還沒完全做好。這件披風能賦予你天尊的力量。', `MaleText_loc7`='Mi trabajo no está terminado aún. Esta capa te dará el poder de los celestiales.' WHERE `ID`=74130;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그리고 조금만 기다리면, 내가 지닌 용의 힘으로 그 망토를 한층 더 강화할 수 있을 것이다.', `MaleText_loc4`='用不了多久，我们就能用我强大的巨龙之力强化你的斗篷了。', `MaleText_loc5`='很快，我們就能用我自己的強大龍力來強化你的披風。', `MaleText_loc7`='Muy pronto podremos potenciar tu capa con mis poderes dragónicos formidables.' WHERE `ID`=74131;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='계속해서 너의 동맹들을 도와라. 빠른 시일 내에 연락하마!', `MaleText_loc4`='继续帮助你的盟友作战吧。我稍后再联络你！', `MaleText_loc5`='繼續在戰爭中幫助你的盟友。我很快就會聯繫你!', `MaleText_loc7`='Sigue ayudando a tus aliados en esta guerra. ¡Me comunicaré contigo en poco tiempo!' WHERE `ID`=74132;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='예언자 하오 팜 루가 당신에게 등산용 밧줄을 건넵니다. 밧줄 걸이에 걸어서 그가 산을 오르는 것을 도와주십시오!', `MaleText_loc4`='先知昊梵舟将爬绳的一端交到你手中。将它绑在下一个绳锚上，帮助昊梵舟爬上山顶！', `MaleText_loc5`='先知昊范州把他那條登山繩的一端交給你，綁在繩索木樁上幫助他攀爬這座山!', `MaleText_loc7`='El vidente Hao Fan Ru te da el extremo de su cuerda de escalada. ¡Átala en la siguiente ancla de cuerda y ayúdale a escalar la montaña!' WHERE `ID`=74133;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='$C님! 이 지역에는 코르크론 놈들이 날뛰고 있습니다. 우리를 도와주시겠습니까?', `MaleText_loc4`='$C！这里挤满了库卡隆。帮我们个忙吧？', `MaleText_loc5`='$C!這裡面的柯爾克隆部隊都快滿出來了。幫個忙吧?', `MaleText_loc7`='¡$C! Esta zona está plagada de Kor''kron. ¿Nos echas una mano?', `FemaleText_loc1`='$C님! 이 지역에는 코르크론 놈들이 날뛰고 있어요. 우리를 도와주시겠어요?', `FemaleText_loc4`='$C！这里挤满了库卡隆。帮我们个忙吧？', `FemaleText_loc5`='$C!這裡面的柯爾克隆部隊都快滿出來了。幫個忙吧?', `FemaleText_loc7`='¡$C! Esta zona está plagada de Kor''kron. ¿Nos echas una mano?' WHERE `ID`=74134;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두 처치했군! 이제 함선의 바닥으로 가서 저 폭발물을 설치하라고!', `MaleText_loc4`='最后一个也拿到了！快到船底去，放下这些炸药！', `MaleText_loc5`='好，清光了!快去船隻底層安裝炸藥!', `MaleText_loc7`='¡Ese era el último! Hay que plantar los explosivos en la parte baja del barco.' WHERE `ID`=74135;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그가 적을 쓰러뜨릴 때 검이나 마법 따윈 필요하지 않습니다. 우리의 다음 도전자는 끝내주는 기하학의 힘으로 적을 제압하니까요! 여러분, 헥소스입니다!', `MaleText_loc4`='接下来这位，他无需刀剑与魔法就能打败敌人。我们的下一位挑战者，海克索斯，使用强大的几何之力克敌制胜的战士！', `MaleText_loc5`='他不需要靠劍或魔法來打敗敵人。下一位挑戰者大眼怪會用驚奇的幾何學進行戰鬥!', `MaleText_loc7`='No le hacen falta armas ni magia para derrotar a sus enemigos. ¡Nuestro siguiente contendiente, Hexos, se enfrenta a sus enemigos con los alucinantes poderes de la GEOMETRÍA!' WHERE `ID`=74136;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='새가슴이라고 만만히 보지 마십시오. 사실 싸움 좀 하는 친구거든요. 타이슨 샌더스를 소개합니다!', `MaleText_loc4`='虽然他就像是一只大公鸡，但他仍然要奋勇战斗。他就是，泰森·山德士！', `MaleText_loc5`='雖然他就像是一隻雞，一隻巨大的雞，但是他打起架可毫不馬虎。歡迎泰森·桑德斯上場!', `MaleText_loc7`='Puede que no sea más que una enorme gallina, pero no dará la batalla por perdida. ¡Es Tyson Sanders!' WHERE `ID`=74137;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그에겐 두 가지 모드 밖에 없습니다. 그런데 두 모드 다 "살인"용이라죠? T440을 위해 우리 모두 박수!', `MaleText_loc4`='他有两种模式，每一种都被贴上了“屠夫”的标签。让我们欢迎，T440！', `MaleText_loc5`='「是誰具有兩種『殺殺殺』模式可供切換?沒錯，現在歡迎T440登場!」', `MaleText_loc7`='Tiene dos modos. Y en ambos modos el objetivo es "MATAR". ¡Un aplauso para T440!' WHERE `ID`=74138;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='바싹 구워진 싸움꾼들이 마음에 드실지 모르겠네요! 무연탄 정령을 소개합니다!!', `MaleText_loc4`='但愿大家都喜欢自己的拳手特脆饼干！现在进场的是，硬煤！！', `MaleText_loc5`='大家喜不喜歡香脆可口的鬥陣香酥脆?現在無煙煤要登場啦!!', `MaleText_loc7`='¡Espero que les gusten sus contendientes bien crujientes! ¡¡Aquí viene Antracita!!' WHERE `ID`=74139;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 폭탄보다 좋은 건 뭘까요? 당연히 더 큰 폭탄이겠죠! 이번 상대는 두두둥 쾅입니다!!', `MaleText_loc4`='还有什么能比一场大爆炸更刺激呢？那当然是很多很多大爆炸啦！这边进场的是，大型雷震天！！', `MaleText_loc5`='有什麼東西比爆炸更讚?沒錯，那就是超多超多的爆炸!在這個角落登場的，正是大轟噠彈!!', `MaleText_loc7`='¿Qué hay mejor que una explosión? Un montón de explosiones, por supuesto! ¡¡En esta esquina, Gran Badabum!!' WHERE `ID`=74140;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 이 작고 깜찍한 뱀 좀 보십시오. 야금뱀입니다! 요놈이 당신 발가락을 야금야금 깨물게 놔둬 보세요. 그냥 무슨 일이 일어나는지 한 번 보자고요.', `MaleText_loc4`='噢……看看这条可爱的小蛇，噬人蛇！上啊，让它咬一口你的脚趾。让我们看看会发生什么事。', `MaleText_loc5`='啊...看看這條小可愛，囓屍大蛇來啦!上吧，讓牠一點一點咬掉你的腳趾頭。咱們來看看事情接下來會如何發展。', `MaleText_loc7`='Oh, miren a esta asombrosa serpiente: ¡Níbilis! Vamos, deja que se te acerque. A ver qué pasa.' WHERE `ID`=74141;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진짜 의사는 아닙니다. 하지만 적의 얼굴을 예쁘게 손봐주시겠다는군요! 다음 상대를 소개합니다! 의사 갈퀴손!', `MaleText_loc4`='他不是真正的医生，但他将要给他的下一个对手做点整容手术。让我们欢迎，铁拳医师！', `MaleText_loc5`='雖然他不是真正的醫生，不過他要來動些面部重建手術。當然是幫他的對手動手術啦。讓我們歡迎拳頭醫師!', `MaleText_loc7`='No es doctor de verdad, pero va a intentar llevar a cabo cirugía de reconstrucción facial... en su próximo adversario. ¡Bienvenido, Doctor Zarpas!' WHERE `ID`=74142;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복덩이의 먼지를 터십시오. 이번엔 복이 필요할테니까요. 이번 상대는 할아범 투덜피리입니다!', `MaleText_loc4`='擦亮你的幸运符吧，你会用得上它的。接下来进场的是，老爹土笛子！', `MaleText_loc5`='拍拍幸運星，因為你接下來真的需要點運氣。歡迎寶笛爺爺!', `MaleText_loc7`='Sácale brillo al grisgrís, porque te va a hacer falta. ¡Es el abuelo Chiriflauta!' WHERE `ID`=74143;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀라운 우리 도전자의 모습, 감히 말로 형언할 수 없군요. 곰과 달곰한 아가씨를 보고 마음껏 즐겨 주십시오!', `MaleText_loc4`='接下来这对挑战者难以用语言来形容。就请大家自己好好欣赏吧，巨熊与淑女！', `MaleText_loc5`='沒有任何開場白能為我們挑戰者辯駁，睜大雙眼，熊與夫人出場啦!', `MaleText_loc7`='No hay presentación posible que haga justicia a nuestros próximos contendientes. ¡Disfrutad del Oso y la Doncella!' WHERE `ID`=74144;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠시 무기는 내려놓고 장갑을 끼세요. 간만에 권투 시합이 벌어질 예정입니다. 타이타르에게 한 방 맞을 준비를 하십시오!', `MaleText_loc4`='扔掉你的武器，拿起拳套吧。接下来将有一场精彩的传统拳击赛。做好被泰塔尔击倒的准备吧！', `MaleText_loc5`='放下手上的武器，戴上拳擊手套，來場老派的拳擊比賽!準備感受泰薩爾帶來的震撼!', `MaleText_loc7`='Tira el arma y ponte unos guantes. Ha llegado el momento de disfrutar de un poco de boxeo clásico. ¡Prepárate a besar el suelo ante Ty''thar!' WHERE `ID`=74145;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳 싸움굴에서 모셨던 싸움꾼 중 가장 무시무시한 자가 아닐까 싶습니다. 불행하게도, 여긴 그가 놀던 물이 아니라는군요. 여러분, 모두 서슬아귀를 위해 건배!', `MaleText_loc4`='他可能是我们搏击俱乐部有史以来最危险的拳手。遗憾的是，他的元素好像有点不够用了。请大家举杯欢迎，锋齿！', `MaleText_loc5`='他可說是鬥陣俱樂部有史以來最危險的對手。不幸的是，就是腦袋少根筋。大家舉杯，敬獰齒鯊!', `MaleText_loc7`='Puede que se trate del luchador más mortífero que hemos tenido en el Club de Lucha. Por desgracia, no está en su elemento. ¡Levanten sus jarras por Muecafilada!' WHERE `ID`=74146;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸울가르 투기장의 역전용사분들은 자가복제 수액괴물 브랏을 기억하실 겁니다. 오늘! 여러분께 그보다 훨씬 가혹하고, 못 생긴 누나, 스플랏을 소개합니다!', `MaleText_loc4`='搏击俱乐部的老手们可能还记得那个能自我复制的软泥怪，布拉特。今天，我们将迎来他这位更卑鄙、更丑陋的姐姐：斯普拉特！', `MaleText_loc5`='在鬥陣競技場待過一段時間的老手應該還記得會自我複製的吞齧怪吧?今天來到現場的，是他那更醜更老更難纏的姊姊:血泥怪!', `MaleText_loc7`='Los veteranos de Liza''gar recordarán a Blat, el moco replicante. Hoy nos enfrentamos con su hermana mayor, más mala y más fea: ¡Splat!' WHERE `ID`=74147;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이게 누구야? 브루스가 돌아왔습니다! 더 힘세고 강해져서 돌아온 브루스! 기계브루스입니다! 만세!!', `MaleText_loc4`='这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！耶！！！', `MaleText_loc5`='咦，怎麼回事?布魯斯回來了!更強、更壯、更快!機械布魯斯!!喔耶!!', `MaleText_loc7`='¿Pero qué es esto? ¡Bruce ha vuelto! ¡Un Bruce mejor, más rápido y más fuerte! ¡Es MECA-BRUCE! ¡¡Yujuuuu!!' WHERE `ID`=74148;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='머리가 없습니다. 팔꿈치도 없습니다. 하지만 누가 뭐래도 그는 뛰어난 전술가입니다! 여러분, 묵치파를 소개합니다! 박수!', `MaleText_loc4`='他是一位战略大师，他甚至都没有脑袋，也没有肘子。他就是，猜拳手！让我们为他拍拍手吧！', `MaleText_loc5`='這是名戰略專家，雖然連顆腦袋或根眉毛都沒有。讓我們為剪刀石頭布歡呼!', `MaleText_loc7`='Es un genio de la estrategia, y ni siquiera tiene cerebro. Claro que tampoco tiene codos. ¡Es Ro Shambo! ¡Un aplauso!' WHERE `ID`=74149;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 한물 간 로봇들로 뭘 하냐고요? 당연히 유혈이 난무하는 검투사 투기장으로 보내 죽을 때까지 싸우게 하죠! 여러분, 블링트론 3000입니다!', `MaleText_loc4`='想知道我们是怎么处理报废机器人的吗？当然是把他们送到血腥的竞技场来送死了！现在进场的是，布林顿3000！', `MaleText_loc5`='你是否想過，要怎麼處理不要的機器人?當然是派它們到血腥的競技場送死呀!歡迎布靈登3000型登場!', `MaleText_loc7`='¿Se han preguntado alguna vez qué se hace con los robots obsoletos? Los mandamos a morir a sangrientas arenas de gladiadores, por supuesto. ¡Les presento al Joyatrón 3000!' WHERE `ID`=74150;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그는 자신이 이기지 못할 상대는 본 적이 없습니다. 아, 정정하겠습니다. 그는 상대를 본 적이 없습니다. 눈먼 영웅을 소개합니다!', `MaleText_loc4`='他从未见过战胜不了的对手。呃，小小地纠正一下：应该说，他从未见过对手。他就是，盲眼英雄！', `MaleText_loc5`='他從未見過打不過的對手。啊，稍微更正一下，他從未見過任何對手，因為他是盲大俠!', `MaleText_loc7`='Oponente que ve, oponente que machaca. Bueno, técnicamente, nunca ha visto a un oponente. ¡Es el héroe ciego!' WHERE `ID`=74151;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용매처럼 날아서, 전갈처럼 쏴라!', `MaleText_loc4`='像龙鹰一样漂移，像蝎子一样蜇人！', `MaleText_loc5`='翔如龍鷹，刺如蠍!', `MaleText_loc7`='¡Flota como un dracohalcón, pica como un escórpido!' WHERE `ID`=74152;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 내가 사상 최고의 싸움꾼이야!', `MaleText_loc4`='没错，伙计！我是最强的拳手！', `MaleText_loc5`='嘿，老兄!我可是這裡最棒的!', `MaleText_loc7`='¡Sí, colega! Soy el mejor de los mejores.' WHERE `ID`=74153;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='엄니에 한 방 맞으면, 작전이고 뭐고 다 소용 없는 짓이지...', `MaleText_loc4`='每个人都有自己的小心思，直到他们的獠牙上被揍了这么一拳……', `MaleText_loc5`='大家在被打得滿地找牙前都覺得自己是有備而來...', `MaleText_loc7`='Todo el mundo tiene un plan, hah''ta que le pegan un buen puñetazo en los colmillos.' WHERE `ID`=74154;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이번엔 그냥 누워 있어!', `MaleText_loc4`='这次，你就给我乖乖躺下吧！', `MaleText_loc5`='這次就乖乖躺在地上吧!', `MaleText_loc7`='¡Y eh''ta vez no te levantes!' WHERE `ID`=74155;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 바닥은 타이타르가 꽉 잡고 있지!', `MaleText_loc4`='这是泰塔尔的地盘！', `MaleText_loc5`='這可是泰薩爾的地盤!', `MaleText_loc7`='¡Eh''ta es la casa de Ty''thar!' WHERE `ID`=74156;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이렇게 빠른 공격은 처음 보는군...', `MaleText_loc4`='我以前从没见过这么快的速度……', `MaleText_loc5`='我從沒見過如此的速度...', `MaleText_loc7`='Nunca había vih''to semejante velocidad...' WHERE `ID`=74157;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 반짝반짝한... 데...', `MaleText_loc4`='我的零件被打坏了……', `MaleText_loc5`='布靈登閃亮亮...', `MaleText_loc7`='He perdido mi brillo...' WHERE `ID`=74158;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 두개골을 고고학 유물로 만들어주겠소!', `MaleText_loc4`='尝尝我的锄头吧，$g小子:丫头;！', `MaleText_loc5`='$g小夥子:姑娘;，我要把你的顱骨當成考古材料!', `MaleText_loc7`='¡Te voy a arqueologizar el cráneo, $gchaval:chavala;!' WHERE `ID`=74159;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마지막 황제의 흔적을 찾는 이 늙은이를 도와주겠는가?', `MaleText_loc4`='你愿意帮助一位老人重走末代皇帝之路吗？', `MaleText_loc5`='你願意協助老人家追尋末代皇帝的足跡嗎?', `MaleText_loc7`='¿Ayudarás a un viejo a recorrer los pasos del último emperador?' WHERE `ID`=74160;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='산을 오르는 데 도움을 드리겠습니다.', `MaleText_loc4`='我准备好了，我们出发吧。', `MaleText_loc5`='我準備好了，一路上有我幫忙。', `MaleText_loc7`='Estoy preparado para ayudarte a recorrer el camino.', `FemaleText_loc1`='산을 오르는 데 도움을 드릴게요.', `FemaleText_loc4`='我准备好了，我们出发吧。', `FemaleText_loc5`='我準備好了，一路上有我幫忙。', `FemaleText_loc7`='Estoy preparada para ayudarte a recorrer el camino.' WHERE `ID`=74161;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 내 삽과 함께 묻어 주시오...
진짜로...', `MaleText_loc4`='用我的铲子把我埋了吧……
我是说真的……', `MaleText_loc5`='用我的鏟子埋了我...
就字面上的意思而已...', `MaleText_loc7`='Entiérrenme con mi pala...
Literalmente...' WHERE `ID`=74162;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 삽 맛이 어떠냐?!?', `MaleText_loc4`='你能挖到它吗？！？', `MaleText_loc5`='你會挖嗎?!?', `MaleText_loc7`='¡Lo voy a celebrar con CAVA!' WHERE `ID`=74163;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 누가 고물인지 알겠어?', `MaleText_loc4`='现在，谁才是该退市的产品？', `MaleText_loc5`='現在誰才是別人不要的?', `MaleText_loc7`='¿Quién está obsoleto ahora?' WHERE `ID`=74164;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 울고 있는 것 같습니다.', `MaleText_loc4`='%s似乎在哭泣。', `MaleText_loc5`='%s看起來在哭。', `MaleText_loc7`='%s parece estar sollozando.' WHERE `ID`=74165;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='널 찾아낼 테다...', `MaleText_loc4`='我会找到你的……', `MaleText_loc5`='我會找到你的...', `MaleText_loc7`='Te encontraré...' WHERE `ID`=74166;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죽음의 소리가... 내겐 무척이나 달콤하지...', `MaleText_loc4`='死亡的声音……在我听来是如此甜蜜……', `MaleText_loc5`='死亡之聲...多美妙啊...', `MaleText_loc7`='El sonido de la muerte... tan agradable a mis oídos...' WHERE `ID`=74167;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 느낌은... 뭐지...? 이건... 빛인가...?', `MaleText_loc4`='这是什么感觉？那是……光吗……？', `MaleText_loc5`='這種感覺是...?那是...那是光嗎...?', `MaleText_loc7`='¿Qué es esta sensación? ¿Es una... una luz?' WHERE `ID`=74168;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 불안정해 보입니다.', `MaleText_loc4`='%s似乎不太稳定……', `MaleText_loc5`='%s似乎不太穩定。', `MaleText_loc7`='%s parece inestable.' WHERE `ID`=74169;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='의사는 망했다...', `MaleText_loc4`='医师不在了……', `MaleText_loc5`='博士出局...', `MaleText_loc7`='El doctor está fuera...' WHERE `ID`=74170;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가진 게 손밖에 없을 때는 죄다 얼굴로 보이지.', `MaleText_loc4`='当你只剩下拳头的时候，你就会觉得看什么都像脸……', `MaleText_loc5`='當你壯得只剩下拳頭，在你眼中所有事物都像張臉。', `MaleText_loc7`='Cuando lo único que tienes son tus puños, todo te parecen caras.' WHERE `ID`=74171;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 심판을 받을 것이다.', `MaleText_loc4`='你将受到审判。', `MaleText_loc5`='現在要來審判你了。', `MaleText_loc7`='Empieza tu juicio.' WHERE `ID`=74172;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는... 빛을 부린다!', `MaleText_loc4`='我掌握着……圣光！', `MaleText_loc5`='聖光就是...我的力量!', `MaleText_loc7`='¡Yo manejo... la LUZ!' WHERE `ID`=74173;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 신념을 시험하는구나.', `MaleText_loc4`='你在挑战我的信仰。', `MaleText_loc5`='你在考驗我的虔誠度。', `MaleText_loc7`='Pones a prueba mi fe.' WHERE `ID`=74174;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 나의 방패다.', `MaleText_loc4`='圣光就是我的护盾。', `MaleText_loc5`='聖光即是吾盾!', `MaleText_loc7`='La Luz es mi escudo.' WHERE `ID`=74175;
