UPDATE `locales_broadcast_text` SET `MaleText_loc1`='파멸이 네 눈앞에 있다.', `MaleText_loc4`='现在，直面你的末日吧。', `MaleText_loc5`='來面對你的死期吧。', `MaleText_loc7`='Ahora te enfrentas a tu final.' WHERE `ID`=74177;
