UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 이 얼라이언스 개들을 몰아내야 해!', `MaleText_loc4`='帮我们击退这些联盟狗！', `MaleText_loc5`='幫我們擊退聯盟畜生!', `MaleText_loc7`='¡Hay que detener a estos perros de la Alianza!' WHERE `ID`=74182;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 넘어온다! 마지막 놈들인 것 같군!', `MaleText_loc4`='又有人荡过来了。看来这是最后一批了！', `MaleText_loc5`='又有人盪過來了。看來是最後一批了!', `MaleText_loc7`='Quedan unos cuantos. Parece que son los últimos.' WHERE `ID`=74183;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미풍은 당신의 이동 속도를 증가시킵니다. 예언자 하오 팜 루의 곁에 서서 이 효과를 공유하십시오.', `MaleText_loc4`='微风提高了你的移动速度——走到先知昊梵舟身边，与他分享此效果。', `MaleText_loc5`='微風提高了你的移動速度，走到先知昊范州旁邊，和他分享這個效果。', `MaleText_loc7`='El Céfiro aumenta tu velocidad de movimiento. Camina al lado del vidente Hao Fan Ru para compartir el efecto.', `FemaleText_loc1`='미풍은 당신의 이동 속도를 증가시킵니다. 예언자 하오 팜 루의 곁에 서서 이 효과를 공유하십시오.', `FemaleText_loc4`='微风提高了你的移动速度——走到先知昊梵舟身边，与他分享此效果。', `FemaleText_loc5`='微風提高了你的移動速度，走到先知昊范州旁邊，和他分享這個效果。', `FemaleText_loc7`='El Céfiro aumenta tu velocidad de movimiento. Camina al lado del vidente Hao Fan Ru para compartir el efecto.' WHERE `ID`=74184;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='목소리를 낮춰주시오, $r님. 바인 블러드후프가 나를 여기로 보냈소. 이 골짜기에서 일어나는 일을 감시하기 위해서 말이오.', `MaleText_loc4`='拜托你小声点，$r。是贝恩·血蹄派我来监视锦绣谷动向的。', `MaleText_loc5`='$r，拜託你小聲點。貝恩·血蹄派我來觀察恆春谷發生的事件。', `MaleText_loc7`='Por favor, no levantes la voz, $r. Me ha enviado Baine Pezuña de Sangre para estar pendiente de los acontecimientos del Valle.' WHERE `ID`=74185;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 그저 단순한 타우렌일 뿐이오. 바인과 나는 아주 오래전부터 친구였소.', `MaleText_loc4`='我是个头脑简单的牛头人。贝恩和我是老朋友了。', `MaleText_loc5`='我只是個牛頭人，我和貝恩是認識很久的好朋友。', `MaleText_loc7`='Soy un tauren corriente y moliente. Baine y yo somos amigos desde hace mucho tiempo.' WHERE `ID`=74186;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순순히 따라와라, 멍청이. 피를 보기 싫다면.', `MaleText_loc4`='跟我们走，笨蛋，如果你不想见血的话。', `MaleText_loc5`='笨蛋，跟我們走，不然場面將會很血腥。', `MaleText_loc7`='Ven con nosotros, vamos. No querrás que esto se ponga sangriento.', `FemaleText_loc1`='순순히 따라와라, 멍청이. 피를 보기 싫다면.', `FemaleText_loc4`='跟我们走，笨蛋，如果你不想见血的话。', `FemaleText_loc5`='笨蛋，跟我們走，不然場面將會很血腥。', `FemaleText_loc7`='Ven con nosotros, vamos. No querrás que esto se ponga sangriento.' WHERE `ID`=74187;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='등에 도끼가 꽂히기 싫으면 무기를 내려놓아라. 지금 당장.', `MaleText_loc4`='你这是在自讨苦吃。立刻放下武器。', `MaleText_loc5`='你是在自尋死路。馬上放下武器。', `MaleText_loc7`='Estas pidiendo a gritos que te claven un hacha en la espalda. Vamos, tira el arma.', `FemaleText_loc1`='등에 도끼가 꽂히기 싫으면 무기를 내려놓아라. 지금 당장.', `FemaleText_loc4`='你这是在自讨苦吃。立刻放下武器。', `FemaleText_loc5`='你是在自尋死路。馬上放下武器。', `FemaleText_loc7`='Estas pidiendo a gritos que te claven un hacha en la espalda. Vamos, tira el arma.' WHERE `ID`=74188;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도망갈 곳이 있다고 생각하나? 코르크론이 이 도시를 점거했다.', `MaleText_loc4`='你以为你能跑到哪儿去？库卡隆已经控制了这座城市。', `MaleText_loc5`='你想逃到哪去?整座城市都在柯爾克隆的掌握之中。', `MaleText_loc7`='¿Dónde pretendes huir? Los Kor''kron controlan esta ciudad.', `FemaleText_loc1`='도망갈 곳이 있다고 생각하나? 코르크론이 이 도시를 점거했다.', `FemaleText_loc4`='你以为你能跑到哪儿去？库卡隆已经控制了这座城市。', `FemaleText_loc5`='你想逃到哪去?整座城市都在柯爾克隆的掌握之中。', `FemaleText_loc7`='¿Dónde pretendes huir? Los Kor''kron controlan esta ciudad.' WHERE `ID`=74189;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님의 철권에 대적하고 싶지는 않겠지.', `MaleText_loc4`='你最好不要逼酋长动手。', `MaleText_loc5`='你不會想對大酋長的部下動手。', `MaleText_loc7`='No creo que quieras poner a prueba la paciencia del Jefe de Guerra.', `FemaleText_loc1`='대족장님의 철권에 대적하고 싶지는 않겠지.', `FemaleText_loc4`='你最好不要逼酋长动手。', `FemaleText_loc5`='你不會想對大酋長的部下動手。', `FemaleText_loc7`='No creo que quieras poner a prueba la paciencia del Jefe de Guerra.' WHERE `ID`=74190;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 비천한 족속을 봐라. 건초 냄새가 코를 찌르는군.', `MaleText_loc4`='看看这个下贱的家伙，满身的稻草味儿。', `MaleText_loc5`='看看這個可恥的傢伙，聞起來真臭。', `MaleText_loc7`='Mira a esta criatura sin honor. Hueles a paja.', `FemaleText_loc1`='이 비천한 족속을 봐라. 건초 냄새가 코를 찌르는군.', `FemaleText_loc4`='看看这个下贱的家伙，满身的稻草味儿。', `FemaleText_loc5`='看看這個可恥的傢伙，聞起來真臭。', `FemaleText_loc7`='Mira a esta criatura sin honor. Hueles a paja.' WHERE `ID`=74191;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기쁜 마음으로 네놈의 영혼을 짓이겨주지.', `MaleText_loc4`='我会很乐意碾碎你的灵魂的。', `MaleText_loc5`='我會好好享受碾碎你靈魂的感覺。', `MaleText_loc7`='Voy a disfrutar de lo lindo destrozándote el espíritu.', `FemaleText_loc1`='기쁜 마음으로 네놈의 영혼을 짓이겨주지.', `FemaleText_loc4`='我会很乐意碾碎你的灵魂的。', `FemaleText_loc5`='我會好好享受碾碎你靈魂的感覺。', `FemaleText_loc7`='Voy a disfrutar de lo lindo destrozándote el espíritu.' WHERE `ID`=74192;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 정해진 시간 안에 적들을 모두 처치하십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标开启：在时间耗尽前击败所有敌人！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標進行中:在時間內擊敗所有敵人!', `MaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t Objetivo de bonificación comenzado: ¡Derrota a todos los enemigos antes de que se acabe el tiempo!' WHERE `ID`=74193;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 보상 타이머 시작!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励计时器启动！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵計時器已啟動!', `MaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t ¡Temporizador de bonificación en marcha!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 보상 타이머 시작!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励计时器启动！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵計時器已啟動!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t ¡Temporizador de bonificación en marcha!' WHERE `ID`=74194;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전 연습해야 해요.
 
<연장을 손에 든 채로 당신을 가리키는 하너커>
 
당신도 연습을 안하고 있다면 연습하는 게 좋을 거예요. 그러니 연습하세요.
 
연습만이 뭐든 잘하게 되는 비결이에요. 뭐든지요.
 
연습. 연습. 연습', `MaleText_loc4`='我得练习一下。
 
<指指你手中的工具。>
 
如果你没有练过，那最好先练练。一定要坚持练习。
 
不管你要做什么，这是都进步的唯一方法。
 
练习，练习，练习。', `MaleText_loc5`='我得練習一下。
 
<指著你手上的工具。>
 
如果你不常練習的話，就該開始練習。多做多練就是了。
 
只有這樣，你才會進步，在各方面變得更好。
 
多練、多做、多熟悉。', `MaleText_loc7`='Tengo que practicar.
 
<Te señala con la herramienta en la mano.>
 
Si no estás practicando, deberías hacerlo. Así que, sigue practicando. 
 
Es la única forma de que mejores, de que mejores en lo que sea. 
 
Práctica. Práctica. Práctica.' WHERE `ID`=74195;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='제가 자라면요, 저는 세상에서 가장 강하고 강력한 주술사가 될 거예요!', `MaleText_loc4`='等我长大以后，我要成为世界上最杰出的萨满！', `MaleText_loc5`='等我長大，我要成為這世上最傑出的薩滿!', `MaleText_loc7`='¡Cuando sea mayor, quiero ser el mejor chamán del mundo!' WHERE `ID`=74196;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포의 황무지에서 두 줄기로 나 있는 샤의 타락은 거의 직선에 가깝군요. 어디로 향하는 걸까요? 흥미롭군요.', `MaleText_loc4`='煞魔侵蚀恐惧废土的两条路线似乎就是两条笔直的线。我很好奇它们会通向哪里？真是太奇怪了。', `MaleText_loc5`='從煞在悚然荒野留下的腐化痕跡來看，這兩條路徑都是呈直線前進。我在想它們到底要去哪裡?真奇怪。', `MaleText_loc7`='Los dos caminos de la corrupción del sha en el Desierto del Pavor parecen seguir líneas rectas. Me pregunto hasta dónde llevarán. Qué curioso.' WHERE `ID`=74197;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어떤 일들은 누군가가 그런 일이 일어났을 거라고 말해서 일어난 게 되어버리죠. 그래서 역사라는 것이 제대로 기록하기 어려운 것이고요... 하지만 우리는 최선을 다하고 있습니다.', `MaleText_loc4`='有些事，不过是人们口口相传的留言罢了。这使得我们揭示历史真相时变得有些困难……但我们也只能将就一下了。', `MaleText_loc5`='有時候，會發生一些情況是因為有人說必須要這樣，所以就這樣發生了，因此很少會有完全可靠的歷史紀錄...不過我們就湊合點用吧。', `MaleText_loc7`='Algunas veces las cosas pasan porque alguien había dicho que tenían que pasar. Así es difícil que la historia sea algo comprensible... pero nos apañamos.' WHERE `ID`=74198;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상을 떠난 친구나 동료에 대해 너무 오래 슬퍼하지 마세요. 그들과 함께 있는 특권을 누렸다는 걸 감사하게 여기는 것이 어떻게 보면 가장 현명한 처사입니다.', `MaleText_loc4`='不要过于怀念逝去的朋友和同伴。也许最好的解决办法就是为你能与他们有过一段交情感到荣幸。', `MaleText_loc5`='別因為失去好友和夥伴而消沉太久。你和他們擁有共同的經驗和回憶，這是值得驕傲的，這樣去想會比較好。', `MaleText_loc7`='No te detengas demasiado en los amigos o compañeros perdidos. Tal vez sea mejor sentirse honrado por haber tenido la oportunidad de compartir y vivir experiencias con ellos.' WHERE `ID`=74199;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥의 섬에 관해 들어보셨나요? 그곳의 어두운 기운이 여기마저 더럽히는군요.', `MaleText_loc4`='你听说过雷神岛吗？连身处此地的我们都收到了黑暗的预兆。', `MaleText_loc5`='你知道雷王島嗎?即使在這都能感受到黑暗來臨的前兆。', `MaleText_loc7`='¿Has oído hablar de la Isla del Trueno? Hasta aquí nos alcanzan los portentos oscuros.' WHERE `ID`=74200;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥왕의 군대는 거대하고 강력하다고 하지요. 전쟁의 여파가 이곳까지 몰려올까요?', `MaleText_loc4`='据说雷电之王的军队庞大且强悍。你觉得战火会波及到这里吗？', `MaleText_loc5`='據說雷王擁有為數眾多的強悍大軍。你覺得戰火會蔓延到我們這邊嗎?', `MaleText_loc7`='Se dice que los ejércitos del Rey del Trueno son numerosos y poderosos. ¿Crees que la batalla llegará hasta aquí en algún momento?' WHERE `ID`=74201;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 평화로운 사람들이죠. 하지만 우리 내면에 잠든 전사의 혼을 깨운다면 싸우겠습니다.', `MaleText_loc4`='我们是和平的人民，可一旦我们心中那属于战士的热血被唤醒，我们也会奋起一战的。', `MaleText_loc5`='雖然我們愛好和平，但是只要喚醒沉睡在內心的戰士，我們也會奮戰。', `MaleText_loc7`='Somos gente pacífica, pero si despiertas a los guerreros que llevamos dentro, lucharemos.' WHERE `ID`=74202;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천둥의 섬에는 무시무시한 적들이 여럿 있다고 합니다. 매일마다 다른 놈들이 나타난다고 하는군요.', `MaleText_loc4`='我听说雷神岛上有许多危险的敌人和生物。看来，外部的威胁每天都在发生变化。', `MaleText_loc5`='聽說在雷王島上有很多危險的敵人和生物，看來每天都有不同的威脅。', `MaleText_loc7`='He oído hablar de todo tipo de enemigos peligrosos y criaturas que habitan la Isla del Trueno. Parece que cada día, surge una amenaza diferente.' WHERE `ID`=74203;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도와줘! 이 호드 돼지들을 몰아내야 해!', `MaleText_loc4`='帮我们击退这些部落猪！', `MaleText_loc5`='幫我們擊退部落豬玀!', `MaleText_loc7`='¡Hay que detener a estos cerdos de la Horda!' WHERE `ID`=74204;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='더 넘어온다! 이게 마지막 놈들인 것 같군!', `MaleText_loc4`='又有人荡过来了。看来这是最后一批了！', `MaleText_loc5`='又有人盪過來了。看來是最後一批了!', `MaleText_loc7`='Llegan más a bordo. Parece que son los últimos.' WHERE `ID`=74205;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아에 온 낯선 여행자들에게서 좋은 말을 배웠습니다. "화약은 뜨겁게, 맥주는 차갑게!"', `MaleText_loc4`='我就是靠那些初至潘达利亚的旅客过活的。记得保持火药干燥。还有，啤酒需要冷藏！！', `MaleText_loc5`='我照著潘達利亞新訪客的生活方式過活:「火藥粉要乾，酒要夠涼!!」。', `MaleText_loc7`='Vivo según la filosofía de los nuevos viajeros de Pandaria. "¡¡Mantén la pólvora seca y la cerveza fría!!"' WHERE `ID`=74206;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 로켓을 타면 아주 멀리 떨어진 황야의 땅으로 이동합니다. 정말 가시겠습니까?', `MaleText_loc4`='这架火箭能把你送去遥远的荒芜之地。你确定吗？', `MaleText_loc5`='這枚火箭會一路直達荒蕪之地，這條路可是相當漫長喔。你確定嗎?', `MaleText_loc7`='Este cohete te llevará hasta las Tierras Inhóspitas, que están muy lejos. ¿Seguro?', `FemaleText_loc1`='이 로켓을 타면 아주 멀리 떨어진 황야의 땅으로 이동합니다. 정말 가시겠습니까?', `FemaleText_loc4`='这架火箭能把你送去遥远的荒芜之地。你确定吗？', `FemaleText_loc5`='這枚火箭會一路直達荒蕪之地，這條路可是相當漫長喔。你確定嗎?', `FemaleText_loc7`='Este cohete te llevará hasta las Tierras Inhóspitas, que están muy lejos. ¿Seguro?' WHERE `ID`=74207;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 모든 정찰병을 구출하고, 소환된 눈폭풍을 멈추십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：救出所有的斥候并终止巨魔召唤来的风暴！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:救出所有斥候，阻止被召喚出來的風暴!', `MaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t Objetivo de bonificación: ¡Rescata a todos los exploradores y detén la tormenta!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 모든 정찰병을 구출하고, 소환된 눈폭풍을 멈추십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：救出所有的斥候并终止巨魔召唤来的风暴！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:救出所有斥候，阻止被召喚出來的風暴!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t Objetivo de bonificación: ¡Rescata a todos los exploradores y detén la tormenta!' WHERE `ID`=74208;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 파괴자 보로쿨라를 처치하십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败毁灭者波罗库拉！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:擊敗『毀滅者』波羅庫拉!', `MaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t Objetivo de bonificación: ¡Derrota a Borokhula el Destructor!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 파괴자 보로쿨라를 처치하십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败毁灭者波罗库拉！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:擊敗『毀滅者』波羅庫拉!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t Objetivo de bonificación: ¡Derrota a Borokhula el Destructor!' WHERE `ID`=74209;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 분노의 흉물을 처치하십시오!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败怒煞畸体！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:擊敗憤怒的憎惡獸!', `MaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t ¡Objetivo de bonificación: Derrota a la abominación de ira!', `FemaleText_loc1`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t 추가 목표: 분노의 흉물을 처치하십시오!', `FemaleText_loc4`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t奖励目标：击败怒煞畸体！', `FemaleText_loc5`='|TInterface\\Icons\\inv_misc_pocketwatch_01:20|t獎勵目標:擊敗憤怒的憎惡獸!', `FemaleText_loc7`='|TInterfaceIconsinv_misc_pocketwatch_01:20|t ¡Objetivo de bonificación: Derrota a la abominación de ira!' WHERE `ID`=74210;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음악을 즐기게나, 친구!', `MaleText_loc4`='好好享受这摇滚乐吧，伙计！', `MaleText_loc5`='老兄，好好享受我的歌聲吧!', `MaleText_loc7`='¡Disfruta la roca, colega!' WHERE `ID`=74211;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가.', `MaleText_loc4`='你好，朋友。', `MaleText_loc5`='幸會啊朋友。', `MaleText_loc7`='Hola.' WHERE `ID`=74212;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저는 평생 동안 낮에는 일을 하지 않았습니다. 야행성인 사람이 누릴 수 있는 수많은 혜택 중 하나지요!', `MaleText_loc4`='我这辈子从没干过一整天的活儿。这只是做夜猫子的诸多好处之一。', `MaleText_loc5`='我這輩子從來沒在白天工作過。晝伏夜出好處多多，這不過是其中一個好處罷了!', `MaleText_loc7`='No he trabajado ni un solo día en mi vida. Es una de las ventajas de ser nocturno.' WHERE `ID`=74213;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='차라리 책을 읽겠어요!', `FemaleText_loc4`='我宁可去看看书！', `FemaleText_loc5`='我寧可去讀書!', `FemaleText_loc7`='¡Preferiría estar leyendo!' WHERE `ID`=74214;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요즘 호젠어를 배우고 있어요. 구리구리한 응가들! 재선 디 포가 내 미끈고기를 다 먹어치웠어요. 엉덩이를 우낏해버릴 거예요!', `MaleText_loc4`='我正在学说猢狲语，该死的蠢蛋！公孙镝甫吃光了我的鱼。我要狠狠揍他一顿。', `MaleText_loc5`='我正在學猴人語，該死的怪怪人!加善狄佛把我的滑魚全部吃光光了，我把打爆他的屁屁!', `MaleText_loc7`='Estoy aprendiendo a hablar hozen: ¡dingues makakus! Jae Sun Di Fo se komió toda mi manduka. Por eso, yo le jeringa en los mikos.' WHERE `ID`=74215;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님을 위하여!', `MaleText_loc4`='为了地狱咆哮！', `MaleText_loc5`='為了地獄吼而戰!', `MaleText_loc7`='¡Por Grito Infernal!', `FemaleText_loc1`='헬스크림 님을 위하여!', `FemaleText_loc4`='为了地狱咆哮！', `FemaleText_loc5`='為了地獄吼而戰!', `FemaleText_loc7`='¡Por Grito Infernal!' WHERE `ID`=74216;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드의 적에게 죽음을!', `MaleText_loc4`='正统部落的敌人统统要死！', `MaleText_loc5`='正統部落的敵人都該死!', `MaleText_loc7`='¡Muerte a los enemigos de la verdadera Horda!', `FemaleText_loc1`='진정한 호드의 적에게 죽음을!', `FemaleText_loc4`='正统部落的敌人统统要死！', `FemaleText_loc5`='正統部落的敵人都該死!', `FemaleText_loc7`='¡Muerte a los enemigos de la verdadera Horda!' WHERE `ID`=74217;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 누구도 우리의 강대함에 맞서지 못할 거다!', `MaleText_loc4`='我们的力量无人能挡！', `MaleText_loc5`='我們的威猛無人能敵!', `MaleText_loc7`='¡Nadie podrá contra nuestro poder!', `FemaleText_loc1`='그 누구도 우리의 강대함에 맞서지 못할 거야!', `FemaleText_loc4`='我们的力量无人能挡！', `FemaleText_loc5`='我們的威猛無人能敵!', `FemaleText_loc7`='¡Nadie podrá contra nuestro poder!' WHERE `ID`=74218;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 이 땅을 정화할 것이다!', `MaleText_loc4`='我们将净化这片土地！', `MaleText_loc5`='我們要淨化這片土地!', `MaleText_loc7`='¡Purgaremos esta tierra!', `FemaleText_loc1`='우리가 이 땅을 정화할 거야!', `FemaleText_loc4`='我们将净化这片土地！', `FemaleText_loc5`='我們要淨化這片土地!', `FemaleText_loc7`='¡Purgaremos esta tierra!' WHERE `ID`=74219;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림 님께서 우리를 지켜보고 계신다!', `MaleText_loc4`='地狱咆哮之眼在注视着我们！', `MaleText_loc5`='地獄吼的雙眼在盯著我們!', `MaleText_loc7`='¡Los ojos de Grito Infernal nos observan!', `FemaleText_loc1`='헬스크림 님께서 우리를 지켜보고 계신다!', `FemaleText_loc4`='地狱咆哮之眼在注视着我们！', `FemaleText_loc5`='地獄吼的雙眼在盯著我們!', `FemaleText_loc7`='¡Los ojos de Grito Infernal nos observan!' WHERE `ID`=74220;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='승리가 아니면 죽음뿐!', `MaleText_loc4`='非胜即死！', `MaleText_loc5`='不勝即亡!', `MaleText_loc7`='¡Victoria o muerte!', `FemaleText_loc1`='승리가 아니면 죽음뿐이야!', `FemaleText_loc4`='非胜即死！', `FemaleText_loc5`='不勝即亡!', `FemaleText_loc7`='¡Victoria o muerte!' WHERE `ID`=74221;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='발로 자근자근 짓밟아주겠다!', `MaleText_loc4`='我们会将你们踩在脚下！', `MaleText_loc5`='我們要用腳跟踩扁你!', `MaleText_loc7`='¡Te aplastaremos bajo nuestras ruedas!', `FemaleText_loc1`='발로 자근자근 짓밟아주겠어!', `FemaleText_loc4`='我们会将你们踩在脚下！', `FemaleText_loc5`='我們要用腳跟踩扁你!', `FemaleText_loc7`='¡Te aplastaremos bajo nuestras ruedas!' WHERE `ID`=74222;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약해빠진 놈. 넌 살 가치도 없다.', `MaleText_loc4`='你不配活着，懦夫。', `MaleText_loc5`='你這個弱者不配活著。', `MaleText_loc7`='No mereces vivir, débil.', `FemaleText_loc1`='약해빠진 놈. 넌 살 가치도 없어.', `FemaleText_loc4`='你不配活着，懦夫。', `FemaleText_loc5`='你這個弱者不配活著。', `FemaleText_loc7`='No mereces vivir, débil.' WHERE `ID`=74223;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='볼진과 그 동맹에 죽음을!', `MaleText_loc4`='让沃金和他所有的同谋都去死吧！', `MaleText_loc5`='殺死沃金和他的盟友!', `MaleText_loc7`='¡Muerte a Vol''jin y a todos sus aliados!', `FemaleText_loc1`='볼진과 그 동맹에 죽음을!', `FemaleText_loc4`='让沃金和他所有的同谋都去死吧！', `FemaleText_loc5`='殺死沃金和他的盟友!', `FemaleText_loc7`='¡Muerte a Vol''jin y a todos sus aliados!' WHERE `ID`=74224;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드를 위하여!', `MaleText_loc4`='为了正统部落！', `MaleText_loc5`='為正統部落而戰!', `MaleText_loc7`='¡Por la verdadera Horda!', `FemaleText_loc1`='진정한 호드를 위하여!', `FemaleText_loc4`='为了正统部落！', `FemaleText_loc5`='為正統部落而戰!', `FemaleText_loc7`='¡Por la verdadera Horda!' WHERE `ID`=74225;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 흥미로운 문이네요.', `FemaleText_loc4`='这门真有意思。', `FemaleText_loc5`='這道門真有趣。', `FemaleText_loc7`='Qué puerta tan interesante.' WHERE `ID`=74226;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런 세상은 상상조차 못 했어요.', `FemaleText_loc4`='我从没想过会有这样一个世界。', `FemaleText_loc5`='我從來沒想像像這樣子的世界是怎樣。', `FemaleText_loc7`='Nunca imaginé un mundo así.' WHERE `ID`=74227;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다시 만나 반갑네요. 근데... 우리 전에 본 적 있나요?', `FemaleText_loc4`='很高兴再次见到你。我们见过吗？', `FemaleText_loc5`='很高興再見到你。咦?我們見過嗎?', `FemaleText_loc7`='Me alegro de volver a verte. ¿Nos conocemos?' WHERE `ID`=74228;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 의외의 결과군요.', `FemaleText_loc4`='这结果真奇怪。', `FemaleText_loc5`='這結局真奇怪。', `FemaleText_loc7`='Qué final tan extraño.' WHERE `ID`=74229;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이 세상은 너무 달라요.', `FemaleText_loc4`='这个世界真是太与众不同了。', `FemaleText_loc5`='這個世界如此不同。', `FemaleText_loc7`='Este mundo es tan diferente.' WHERE `ID`=74230;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가야겠어요. 아직 볼 게 많거든요.', `FemaleText_loc4`='我得走了，还有好多东西要看呢。', `FemaleText_loc5`='我得走了，有太多東西要看。', `FemaleText_loc7`='Tengo que irme, hay tantas cosas por ver.' WHERE `ID`=74231;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가능성은 무한해요.', `FemaleText_loc4`='一切皆有可能。', `FemaleText_loc5`='機會無限。', `FemaleText_loc7`='Las posibilidades son infinitas.' WHERE `ID`=74232;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='저요? 전 여기 사람 아니에요.', `FemaleText_loc4`='我？噢，我不是本地人。', `FemaleText_loc5`='我?喔，我不是這邊的人。', `FemaleText_loc7`='¿Yo? Oh, no soy de por aquí.' WHERE `ID`=74233;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_creature_poison_04:20|t%s|1이;가; 자기 단검에 |cFFFF0000|Hspell:143224|h[순간 효과 독]|h|r을 바릅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_creature_poison_04:20|t%s在他的匕首上涂抹了|cFFFF0000|Hspell:143224|h[速效药膏]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_creature_poison_04:20|t%s ˙在他的匕首上塗抹了|cFFFF0000|Hspell:143224|h[速效毒藥]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_creature_poison_04:20|t¡%s cubre sus dagas de |cFFFF0000|Hspell:143224|h[Veneno instantáneo]|h|r!' WHERE `ID`=74234;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_rogue_deviouspoisons:20|t%s|1이;가; 자기 단검에 |cFFFF0000|Hspell:143239|h[맹독]|h|r을 바릅니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_rogue_deviouspoisons:20|t%s在他的匕首上涂抹了|cFFFF0000|Hspell:143239|h[致命剧毒]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_rogue_deviouspoisons:20|t%s 在他的匕首上塗抹了|cFFFF0000|Hspell:143239|h[致命劇毒]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_rogue_deviouspoisons:20|t¡%s cubre sus dagas de |cFFFF0000|Hspell:143239|h[Veneno nocivo]|h|r!' WHERE `ID`=74235;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도관이 에너지로 가득 차자, 레이 션이 도관을 끊어버립니다!', `MaleText_loc4`='导管能量已满，雷神断开了链接！', `MaleText_loc5`='導雷管能量全滿，雷神與之分離!', `MaleText_loc7`='¡El conducto está a su máxima energía y Lei Shen desconecta!' WHERE `ID`=74238;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='긴급 상황인 것 같습니다, 카드라크. 분명 다른 방법이 있을 겁니다!', `MaleText_loc4`='这似乎很紧急，卡德拉克。肯定还有其他办法的！', `MaleText_loc5`='卡德拉克，看來事態緊急，一定有其它方法可行!', `MaleText_loc7`='Parece urgente, Kadrak. Tiene que haber otro modo.', `FemaleText_loc1`='긴급 상황인 것 같군요, 카드라크. 분명 다른 방법이 있을 거예요!', `FemaleText_loc4`='这似乎很紧急，卡德拉克。肯定还有其他办法的！', `FemaleText_loc5`='卡德拉克，看來事態緊急，一定有其它方法可行!', `FemaleText_loc7`='Parece urgente, Kadrak. Tiene que haber otro modo.' WHERE `ID`=74240;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='알겠네, $n. 그럼 거기서 보지.', `MaleText_loc4`='很好，$n。我会到那里等你的。', `MaleText_loc5`='很好$n，我會在那裡和你碰面。', `MaleText_loc7`='Muy bien, $n. Me reuniré contigo allí.' WHERE `ID`=74241;
