UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 승리가 눈앞에 있습니다!', `MaleText_loc4`='部落离胜利不远了！', `MaleText_loc5`='部落快要獲勝了!', `MaleText_loc7`='¡La Horda se acerca a la victoria!' WHERE `ID`=74243;
