UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 당신들이 오그리마를 공격하는 걸 우리가 지켜보고, 나중에 당신들의 시체를 쓸어담는 것은 어떻게 생각하십니까?', `MaleText_loc4`='[虚张声势]我们何不坐等你们去攻击奥格瑞玛，然后来一个渔翁得利？', `MaleText_loc5`='[虛張聲勢]那我們等你攻打奧格瑪，再過去幫你收屍不就好了?', `MaleText_loc7`='[Responde a su engaño] ¿Por qué no esperamos hasta que USTEDES ataquen Orgrimmar, y después recogemos a SUS muertos?', `FemaleText_loc1`='그렇다면 당신들이 오그리마를 공격하는 걸 우리가 지켜보고, 나중에 당신들의 시체를 쓸어담는 것은 어떻게 생각하시나요?', `FemaleText_loc4`='[虚张声势]我们何不坐等你们去攻击奥格瑞玛，然后来一个渔翁得利？', `FemaleText_loc5`='[虛張聲勢]那我們等你攻打奧格瑪，再過去幫你收屍不就好了?', `FemaleText_loc7`='[Responde a su engaño] ¿Por qué no esperamos hasta que USTEDES ataquen Orgrimmar, y después recogemos a SUS muertos?' WHERE `ID`=74253;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<기회를 놓치는 것을 염려하여 손을 드는 볼진>$b$b기다리게, $r! 오그리마는 요새라네. 우리만으로는 오그리마를 함락시킬 수 없겠지. 여기에서 우리가 얼마나 버티겠나? 며칠? 몇 주? 나도 장담할 수 없다네.$b$b물자를 공급해준다면 내가 장담하건대 더 많은 코르크론이 쓰러질걸세. 자네들의 군대가 상륙하기도 전에 말이야! 자네 손에는 핏방울 하나 묻히지 않는 것이지! 단지 고기 몇 상자로 얻는 이득치곤 괜찮지 않은가?', `MaleText_loc4`='<沃金发现自己的机会正在溜走。他举起了手。>$b$b等等，$r！奥格瑞玛是一座坚城。我的人，我们不可能自己啃下这块硬骨头。我们又能在这里坚持多久呢？几天？几周？沃金可说不准。$b$b只要你们能源源不断地提供补给，我保证，我们一定能干掉更多的库卡隆，而且是在你们的部队登陆之前！你们的人甚至都不用流血牺牲！这应该能值几箱肉吧？', `MaleText_loc5`='<沃金眼看就要錯失良機，雙手緊握著。>$b$b等等，$r!奧格瑪可是座要塞，只靠我的人連片城牆都拆不掉。我們要耗上多久時間才行?好幾天?好幾個禮拜?沃金不知道。$b$b只要你能確保補給源源不斷，我就能保證柯爾克隆的死傷會越來越慘重。你們的人還沒落地就能看到他們的屍體!甚至不用讓你們的人流血!這樣用幾箱肉作為代價應該值得吧?', `MaleText_loc7`='<Vol''jin comprende que se le escapa su oportunidad. Levanta las manos.>$b$b¡Eh''pera, $r! Orgrimmar será una fortaleza. Mi pueblo no conseguirá entrar sin ayuda. ¿Cuánto tiempo duraremos aquí? ¿Días? ¿Semanas? Vol''jin no lo sabe.$b$bSigue proporcionándonos suminih''tros y te prometo que morirán más Kor''kron. ¡Antes incluso de que sus tropas tomen tierra! ¡Ni siquiera tienen que derramar su propia sangre! ¡Eso tiene que valer unos cuantos carros de carne!' WHERE `ID`=74254;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋습니다, $r. 당신 덕분에 수많은 코르크론이 쓰러지겠군요.', `MaleText_loc4`='很好，$r。感谢你帮助，许多库卡隆都将因此丧命。', `MaleText_loc5`='很好，$r。有你的幫助，我們就能殺掉許多柯爾克隆部隊。', `MaleText_loc7`='Bien, $r. Muchos Kor''kron morirán gracias a tu ayuda.' WHERE `ID`=74256;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이걸로 저항군은 더 오래 버틸겁니다. 오그리마는 반드시 무너질 것입니다!', `MaleText_loc4`='这可以让起义军再多坚持一段时间。奥格瑞玛必将陷落！', `MaleText_loc5`='這樣一來，反抗行動就能再持續一小段時間，奧格瑪會陷落的!', `MaleText_loc7`='Eh''to le dará algo más de tiempo a la rebelión. ¡Orgrimmar caerá!' WHERE `ID`=74257;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 날이 올 줄은 몰랐지만... 고맙습니다, $r. 이걸로 코르크론 놈들의 피를 마음껏 흩뿌릴 수 있을 겁니다.', `MaleText_loc4`='这真是个诡异的时代……谢谢你，$r。有了这些东西，我们就能让更多的库卡隆血洒疆场。', `MaleText_loc5`='這是個奇妙的年代...謝了，$r。有了這些，我們就能多殺幾個柯爾克隆。', `MaleText_loc7`='Eh''tos son tiempos extraños... Gracias, $r. Derramaremos mucha sangre Kor''kron con eh''to.' WHERE `ID`=74258;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='물자를 더 많이 가져왔군요! 얼라이언스는 마치 기계와도 같군요. 머지않아 가로쉬의 협잡꾼들을 쓸어버릴 겁니다... 많은 오크들이 잘못된 선택을 했군요.', `MaleText_loc4`='又是补给！联盟真像一架机器。很快我们就能在加尔鲁什手下的恶棍中杀出一条血路……许多兽人都站错了队。', `MaleText_loc5`='又有補給品!你們聯盟真像機器一樣。我們很快就會讓卡爾洛斯手下那群暴徒的數量減少許多...站錯邊的獸人可不少。', `MaleText_loc7`='¡Más suministros! La Alianza es igual que una máquina. Pronto llegaremos hasta los canallas de Garrosh... Muchos orcos han elegido el bando equivocado.' WHERE `ID`=74259;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='꽤 하는군요, $r! 이걸로 우리는 가로쉬의 군대를 박살낼겁니다!', `MaleText_loc4`='你很好，$r！有了这些，我们就能横扫加尔鲁什的部队！', `MaleText_loc5`='你真厲害，$r!有了這些我們就能擊潰卡爾洛斯的部隊!', `MaleText_loc7`='¡Bien, $r! ¡Aplah''taremos al ejército de Garrosh con eh''to!' WHERE `ID`=74260;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='리엔 파너를 찾으십시오. 그라면 어떤 전문 기술도 다 가르칠 수 있을 겁니다.', `MaleText_loc4`='去找莱恩·法尔娜。他可以教你任何的专业技能。', `MaleText_loc5`='去找里恩·法諾爾，他能傳授你所有的專業技能。', `MaleText_loc7`='Busca a Lien Farner. Él podrá formarte en cualquier profesión.', `FemaleText_loc1`='리엔 파너를 찾으십시오. 그라면 어떤 전문 기술도 다 가르칠 수 있을 겁니다', `FemaleText_loc4`='去找莱恩·法尔娜。他可以教你任何的专业技能。', `FemaleText_loc5`='去找里恩·法諾爾，他能傳授你所有的專業技能。', `FemaleText_loc7`='Busca a Lien Farner. Él podrá formarte en cualquier profesión.' WHERE `ID`=74264;
