UPDATE `locales_broadcast_text` SET `MaleText_loc1`='울타지스의 죽음과 함께 남은 정령들이 크게 약화되었습니다!', `MaleText_loc4`='乌萨吉之死重创了剩余的元素生物！', `MaleText_loc5`='厄薩寂的死亡，大大地傷害到剩下的元素。', `MaleText_loc7`='¡La muerte de Urtharges hiere de gravedad a los demás elementales!', `FemaleText_loc1`='울타지스의 죽음과 함께 남은 정령들이 크게 약화되었습니다!', `FemaleText_loc4`='乌萨吉之死重创了剩余的元素生物！', `FemaleText_loc5`='厄薩寂的死亡，大大地傷害到剩下的元素。', `FemaleText_loc7`='¡La muerte de Urtharges hiere de gravedad a los demás elementales!' WHERE `ID`=74268;
