UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:141423|h[헤키마의 지혜]|h|r로 자신을 치유하기 시작합니다.', `MaleText_loc4`='%s开始用 |cFFFF0000|Hspell:141423|h[哈基玛的智慧]|h|r为自己治疗。', `MaleText_loc5`='%s開始以|cFFFF0000|Hspell:141423|h[郝其瑪的智慧]|h|r治療自己。', `MaleText_loc7`='%s empieza a sanarse con |cFFFF0000|Hspell:141423|h[Sabiduría de Hekima]|h|r.' WHERE `ID`=74270;
