UPDATE `locales_broadcast_text` SET `MaleText_loc1`='경주용 산양 한 마리만 더 주시겠습니까?', `MaleText_loc4`='能再给我一头赛羊吗？', `MaleText_loc5`='可以再給我一頭競速山羊嗎?', `MaleText_loc7`='¿Me puedes dar otro carnero de carreras?', `FemaleText_loc1`='경주용 산양 한 마리만 더 주시겠어요?', `FemaleText_loc4`='能再给我一头赛羊吗？', `FemaleText_loc5`='可以再給我一頭競速山羊嗎?', `FemaleText_loc7`='¿Me puedes dar otro carnero de carreras?' WHERE `ID`=74294;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술통을 받으려면 경주용 산양에 타고 있어야 하네! 닐 람스타인에게 돌아가서 다시 한 마리 달라고 하게.', `MaleText_loc4`='你得骑着赛羊才能拿到酒桶！快去找尼尔·拉姆斯登再要一头吧。', `MaleText_loc5`='你必須在競速山羊上面才能收到桶子!回去找奈爾·拉姆斯登再要一頭。', `MaleText_loc7`='¡Para recibir un barril tienes que ir a lomos de un carnero de carreras! Vuelve con Neill Ramstein y pídele otro.' WHERE `ID`=74297;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='술통을 받으려면 경주용 산양에 타고 있어야 하네! 산양 조련사 레이에게 돌아가서 다시 한 마리 달라고 하게.', `MaleText_loc4`='你得骑着赛羊才能拿到酒桶！快去找赛羊管理员雷恩再要一头吧。', `MaleText_loc5`='你必須在競速山羊上面才能收到桶子!回去找奈爾·拉姆斯登再要一頭。', `MaleText_loc7`='¡Para recibir un barril tienes que ir a lomos de un carnero de carreras! Vuelve con el maestro de carneros Rayo y pídele otro.' WHERE `ID`=74298;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "아군이 정신 지배 당하면 전 죽여주려고 정말 열심히 노력해요."', `MaleText_loc4`='[%s]忏悔：当我的盟友被精神控制时，我总会很努力地干掉他们。', `MaleText_loc5`='[%s]坦承:當我的隊友被心控時，我真的很努力想要殺死他們。', `MaleText_loc7`='[%s] confiesa: Cuando alguien controla mentalmente a mis aliados, hago lo posible por matarlos.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "아군이 정신 지배 당하면 전 죽여주려고 정말 열심히 노력해요."', `FemaleText_loc4`='[%s]忏悔：当我的盟友被精神控制时，我总会很努力地干掉他们。', `FemaleText_loc5`='[%s]坦承:當我的隊友被心控時，我真的很努力想要殺死他們。', `FemaleText_loc7`='[%s] confiesa: Cuando alguien controla mentalmente a mis aliados, hago lo posible por matarlos.' WHERE `ID`=74300;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 강한 전투 애완동물을 쓰지 않아요. 귀여운 녀석을 쓰죠."', `MaleText_loc4`='[%s]忏悔：我从不使用最强的战斗宠物，只用最萌的。', `MaleText_loc5`='[%s]坦承:我並沒有使用最強的戰寵。我都只用最可愛的那幾隻。', `MaleText_loc7`='[%s] confiesa: No elijo a las mascotas de duelo más fuertes, sino a las más monas.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 강한 전투 애완동물을 쓰지 않아요. 귀여운 녀석을 쓰죠."', `FemaleText_loc4`='[%s]忏悔：我从不使用最强的战斗宠物，只用最萌的。', `FemaleText_loc5`='[%s]坦承:我並沒有使用最強的戰寵。我都只用最可愛的那幾隻。', `FemaleText_loc7`='[%s] confiesa: No elijo a las mascotas de duelo más fuertes, sino a las más monas.' WHERE `ID`=74301;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "전 가끔 야생의 싹이 다른 야생의 싹하고 헷갈려요."', `MaleText_loc4`='[%s]忏悔：我总是把两个野性之心搞混。', `MaleText_loc5`='[%s]坦承:我都會把野性之心跟另一種野性之心搞混。', `MaleText_loc7`='[%s] confiesa: Siempre me confundo entre Corazón de lo salvaje y Marca de lo salvaje.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "전 가끔 야생의 싹이 다른 야생의 싹하고 헷갈려요."', `FemaleText_loc4`='[%s]忏悔：我总是把两个野性之心搞混。', `FemaleText_loc5`='[%s]坦承:我都會把野性之心跟另一種野性之心搞混。', `FemaleText_loc7`='[%s] confiesa: Siempre me confundo entre Corazón de lo salvaje y Marca de lo salvaje.' WHERE `ID`=74302;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "전 항상 다른 사람한테 제 장비를 어떻게 재연마해야 하는지 물어봐요."', `MaleText_loc4`='[%s]忏悔：每次重铸装备时，我都要请教别人。', `MaleText_loc5`='[%s]坦承:我都會問別人怎樣重鑄裝備比較好。', `MaleText_loc7`='[%s] confiesa: Siempre pregunto cómo reforjar mi equipo.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "전 항상 다른 사람한테 제 장비를 어떻게 재연마해야 하는지 물어봐요."', `FemaleText_loc4`='[%s]忏悔：每次重铸装备时，我都要请教别人。', `FemaleText_loc5`='[%s]坦承:我都會問別人怎樣重鑄裝備比較好。', `FemaleText_loc7`='[%s] confiesa: Siempre pregunto cómo reforjar mi equipo.' WHERE `ID`=74303;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "전 다른 이들이 절 조사하는지 보려고 그들을 조사해요."', `MaleText_loc4`='[%s]忏悔：我常常观察别人，看他们有没有在观察我。', `MaleText_loc5`='[%s]坦承:我都會點別人看他們有沒有在偷看我的裝備。', `MaleText_loc7`='[%s] confiesa: Inspecciono a la gente para ver si me están inspeccionando a mí.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "전 다른 이들이 절 조사하는지 보려고 그들을 조사해요."', `FemaleText_loc4`='[%s]忏悔：我常常观察别人，看他们有没有在观察我。', `FemaleText_loc5`='[%s]坦承:我都會點別人看他們有沒有在偷看我的裝備。', `FemaleText_loc7`='[%s] confiesa: Inspecciono a la gente para ver si me están inspeccionando a mí.' WHERE `ID`=74304;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "판다렌이 처어어언 처어언 히이이이라고 충고할 때마다 주먹으로 얼굴을 갈기고 싶어요."', `MaleText_loc4`='[%s]忏悔：每当有熊猫人让我放慢脚步时，我就想揍他们一顿。', `MaleText_loc5`='[%s]坦承:每次熊貓人說慢...慢...來...我都想賞他們一拳。', `MaleText_loc7`='[%s] confiesa: Cuando los pandaren me dicen "¡Relájate!", me entran ganas de darles una bofetada.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "판다렌이 처어어언 처어언 히이이이라고 충고할 때마다 주먹으로 얼굴을 갈기고 싶어요."', `FemaleText_loc4`='[%s]忏悔：每当有熊猫人让我放慢脚步时，我就想揍他们一顿。', `FemaleText_loc5`='[%s]坦承:每次熊貓人說慢...慢...來...我都想賞他們一拳。', `FemaleText_loc7`='[%s] confiesa: Cuando los pandaren me dicen "¡Relájate!", me entran ganas de darles una bofetada.' WHERE `ID`=74305;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 항상 같은 상인한테 장비를 팔아요. 그 사람은 정말 돈이 많은가 봐요."', `MaleText_loc4`='[%s]忏悔：我总是把所有的旧装备都卖给同一个商人。有钱人的怪癖吧。', `MaleText_loc5`='[%s]坦承:我每次都把不要的裝備都賣給同一個商人。他大概真的很有錢。', `MaleText_loc7`='[%s] confiesa: Siempre vendo mi equipo antiguo al mismo vendedor. Ese tipo tiene que estar forrado.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 항상 같은 상인한테 장비를 팔아요. 그 사람은 정말 돈이 많은가 봐요."', `FemaleText_loc4`='[%s]忏悔：我总是把所有的旧装备都卖给同一个商人。有钱人的怪癖吧。', `FemaleText_loc5`='[%s]坦承:我每次都把不要的裝備都賣給同一個商人。他大概真的很有錢。', `FemaleText_loc7`='[%s] confiesa: Siempre vendo mi equipo antiguo al mismo vendedor. Ese tipo tiene que estar forrado.' WHERE `ID`=74306;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 장비 업그레이드보다 장비 변형에 더 관심이 많아요."', `MaleText_loc4`='[%s]忏悔：相比升级装备，我更喜欢幻化装备。', `MaleText_loc5`='[%s]坦承:對我來說，塑形裝備比升級裝備重要。', `MaleText_loc7`='[%s] confiesa: Me importa más transfigurar mi equipo que mejorarlo.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 장비 업그레이드보다 장비 변형에 더 관심이 많아요."', `FemaleText_loc4`='[%s]忏悔：相比升级装备，我更喜欢幻化装备。', `FemaleText_loc5`='[%s]坦承:對我來說，塑形裝備比升級裝備重要。', `FemaleText_loc7`='[%s] confiesa: Me importa más transfigurar mi equipo que mejorarlo.' WHERE `ID`=74307;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 호드와 얼라이언스 중에 선택을 못하겠어요. 호드에는 네 갈래 머리의 고블린 마법사가 있는 반면에 얼라이언스에는 비비 땋은 머리의 드워프 사제가 있죠."', `MaleText_loc4`='[%s]忏悔：我很难在部落和联盟间做出选择。部落有四根辫子的地精法师，联盟也有麻花辫的矮人牧师。', `MaleText_loc5`='[%s]坦承:我很難選要部落還是聯盟。部落有綁四個馬尾的哥布林法師，但聯盟的矮人牧師綁著性感的小辮子。', `MaleText_loc7`='[%s] confiesa: No me decido entre la Horda y la Alianza. La Horda tiene magas goblin con cuatro coletas, pero la Alianza tiene sacerdotisas enanas con moños trenzados.', `FemaleText_loc1`='[%s]|1이;가; 고해합니다. "저는 호드와 얼라이언스 중에 선택을 못하겠어요. 호드에는 네 갈래 머리의 고블린 마법사가 있는 반면에 얼라이언스에는 비비 땋은 머리의 드워프 사제가 있죠."', `FemaleText_loc4`='[%s]忏悔：我很难在部落和联盟间做出选择。部落有四根辫子的地精法师，联盟也有麻花辫的矮人牧师。', `FemaleText_loc5`='[%s]坦承:我很難選要部落還是聯盟。部落有綁四個馬尾的哥布林法師，但聯盟的矮人牧師綁著性感的小辮子。', `FemaleText_loc7`='[%s] confiesa: No me decido entre la Horda y la Alianza. La Horda tiene magas goblin con cuatro coletas, pero la Alianza tiene sacerdotisas enanas con moños trenzados.' WHERE `ID`=74308;
