UPDATE `locales_broadcast_text` SET `MaleText_loc1`='벼와 쌀을 분리해주지! 어, 잠깐만... 이게 아니었는데...', `MaleText_loc4`='有时你就得对不守规矩的鬼魂狠一点。', `MaleText_loc5`='有時候你對任意妄為的鬼魂要硬一點。', `MaleText_loc7`='Sé que hablo mucho, ¡pero es que me gusta darle a la sin hueso!' WHERE `ID`=74474;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈 빠지게 일해봤자 남는 것도 없더라고.', `MaleText_loc4`='我以前是很幽默的。', `MaleText_loc5`='我以前比較幽默。', `MaleText_loc7`='De mayor siempre quise ser artrónomo.' WHERE `ID`=74475;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='싸움에 잔뼈가 꽤 굵나본데?', `MaleText_loc4`='想听笑话吗？白痴。', `MaleText_loc5`='想聽笑話嗎?「笑話」。', `MaleText_loc7`='Cuando llueve, me calo hasta los huesos.' WHERE `ID`=74476;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='늙어서 그런지 요즘 계속 뼈가 시려.', `MaleText_loc4`='只要你的笑话行得通，谁还需要身体呢？', `MaleText_loc5`='夏天最適合聽冷笑話解暑了，對吧?', `MaleText_loc7`='Esta situación me trae de cabeza.' WHERE `ID`=74477;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심장이 두근거리는데! 아, 있었으면 그랬겠지.', `MaleText_loc4`='你瞧……我的心思真的不在这里。', `MaleText_loc5`='我一直在想有沒有會讓人心跳加快的恐怖笑話。', `MaleText_loc7`='Creo que no tengo estómago para esto.' WHERE `ID`=74478;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 현란한 발놀림을 봐 줘! 안 보인다고? 에이, 그럴리가.', `MaleText_loc4`='他们连一条腿都没给我留下！', `MaleText_loc5`='他們連一條用來站的腿都沒留給我!', `MaleText_loc7`='¡A mover el esqueleto!' WHERE `ID`=74479;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='유령들은 얼마나 추울까. 바람을 막아줄 몸이 없잖아!', `MaleText_loc4`='鬼魂肯定都很冷。因为风能直接穿透他们！', `MaleText_loc5`='鬼魂一定都會覺得冷。風會直接穿過他們!', `MaleText_loc7`='¿A los fantasmas no les dará frío llevar toda la esencia al aire?' WHERE `ID`=74480;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 장기 좀 기증해줄 사람?', `MaleText_loc4`='我一直很想弹风琴。', `MaleText_loc5`='沒有骨頭只有肉，還是只有骨頭沒有肉比較可怕呢?', `MaleText_loc7`='Siempre quise tocar el órgano... ¡el que fuera!' WHERE `ID`=74481;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골수에 맺힌 원한을 이제야 푸는구나!', `MaleText_loc4`='我要把你的骨头都装到我自己身上！', `MaleText_loc5`='我用全身的骨頭在愛你!', `MaleText_loc7`='Morir, hay que fallecer...' WHERE `ID`=74482;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈도 못 추릴 줄 알아!', `MaleText_loc4`='我正在钻研我的灵魂知识。', `MaleText_loc5`='我正在收集各式各樣的冷笑話。', `MaleText_loc7`='Contigo me parto la caja... ¡torácica!' WHERE `ID`=74483;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가끔 거울을 보면 소름이 돋는 다니까.', `MaleText_loc4`='不管你说什么，都不可能让我刻骨铭心！', `MaleText_loc5`='我一點都不怕肉麻，因為我沒有雞皮疙瘩可以掉了!', `MaleText_loc7`='Un fantasma me ha llamado cabeza hueca...' WHERE `ID`=74484;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다이어트? 그게 뭐야, 먹는 거야? 아하, 안 먹는 거구나!', `MaleText_loc4`='棍棒和石头可能会敲碎我的骨头……', `MaleText_loc5`='老骨頭就是比較脆...', `MaleText_loc7`='¡No siento las piernas!' WHERE `ID`=74485;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그녀에게 데이트 신청을 못한 걸 뼈저리게 후회하고 있지.', `MaleText_loc4`='我很想约她出去，可我没那个胆。', `MaleText_loc5`='我本來想約她出去，可惜我沒有膽子。', `MaleText_loc7`='Me gustaría trabajar en el circo, pero no tengo trapecio...' WHERE `ID`=74486;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='속이 텅 빈 기분이야...', `MaleText_loc4`='我恐怕对此没什么胃口……', `MaleText_loc5`='如果我有胃的話，可能會想吐...', `MaleText_loc7`='Tengo genio, pero me dejé la figura en la sepultura.' WHERE `ID`=74487;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어이, 고깃덩어리! 5분만 나랑 얘기하지 않을래? 다들 도망가기 바쁘더라고!', `MaleText_loc4`='嘿，肉袋子！如果你有时间，就来跟我谈谈吧！我好空虚！', `MaleText_loc5`='喂，有肉的傢伙!花個五分鐘來跟我說話!我沒有身體!', `MaleText_loc7`='¡Oye, saco de carne! Ven a hablar conmigo ahora mismo. No tengo cuerpo para tonterías.' WHERE `ID`=74488;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적절한 거래인걸. 영혼의 세계에 온 걸 환영해. 상자들을 열어보는 게 어때? 어쩌면 내 몸뚱아리도 있을 거야!', `MaleText_loc4`='成交。欢迎来到灵魂世界。从某种程度来说这里也算是啦。让我们翻翻这些箱子，看看你能不能找到我的身体吧！', `MaleText_loc5`='很好。歡迎來到靈魂世界。應該吧。我們來找找這些箱子裡有沒有什麼好東西，順便看看你能不能在哪找到我的身體!', `MaleText_loc7`='Hola. Ahora estás en el mundo de los espíritus. Bueno, más o menos. Vamos a buscar cofres del tesoro, y de paso, a ver si encuentras mi cuerpo por algún lado.' WHERE `ID`=74489;
