UPDATE `locales_broadcast_text` SET `MaleText_loc1`='돌머리는 시소 타는 거 좋아한다!', `MaleText_loc4`='隆克喜欢玩跷跷板！', `MaleText_loc5`='郎克愛玩蹺蹺板!', `MaleText_loc7`='¡A Ñoño gusta jugar en balancín!' WHERE `ID`=74538;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다른 사람에게도 기회를 줘, 돌머리.', `MaleText_loc4`='隆克，让其他人也玩玩吧。', `MaleText_loc5`='郎克，請換人玩。', `MaleText_loc7`='Ñoño, deja subir a los demás.', `FemaleText_loc1`='다른 사람에게도 기회를 줘, 돌머리.', `FemaleText_loc4`='隆克，让其他人也玩玩吧。', `FemaleText_loc5`='郎克，請換人玩。', `FemaleText_loc7`='Ñoño, deja subir a los demás.' WHERE `ID`=74539;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 다가오자 석상이 조용히 웅웅거립니다.', `MaleText_loc4`='当你靠近时，雕像发出了柔和的嗡鸣声。', `MaleText_loc5`='在你接近的時候，雕像開始發出輕聲的哼唱。', `MaleText_loc7`='La estatua emite un sonido leve cuando te acercas.', `FemaleText_loc1`='당신이 다가오자 석상이 조용히 웅웅거립니다.', `FemaleText_loc4`='当你靠近时，雕像发出了柔和的嗡鸣声。', `FemaleText_loc5`='在你接近的時候，雕像開始發出輕聲的哼唱。', `FemaleText_loc7`='La estatua emite un sonido leve cuando te acercas.' WHERE `ID`=74540;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석상이 움직이지 않습니다.', `MaleText_loc4`='雕像进入了休眠状态。', `MaleText_loc5`='雕像靜止不動。', `MaleText_loc7`='La estatua está inerte.', `FemaleText_loc1`='석상이 움직이지 않습니다.', `FemaleText_loc4`='雕像进入了休眠状态。', `FemaleText_loc5`='雕像靜止不動。', `FemaleText_loc7`='La estatua está inerte.' WHERE `ID`=74541;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='석상을 만집니다.', `MaleText_loc4`='触摸雕像。', `MaleText_loc5`='觸摸雕像。', `MaleText_loc7`='Toca la estatua.', `FemaleText_loc1`='석상을 만집니다.', `FemaleText_loc4`='触摸雕像。', `FemaleText_loc5`='觸摸雕像。', `FemaleText_loc7`='Toca la estatua.' WHERE `ID`=74542;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='사각사각한 당근은 준비됐나요?', `FemaleText_loc4`='我们预定的爽脆胡萝卜可以提货了吗？', `FemaleText_loc5`='我們的脆嫩多汁胡蘿蔔是否可以收貨了?', `FemaleText_loc7`='¿Ya está listo nuestro pedido de zanahorias Jugoasaz?' WHERE `ID`=74544;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가져오셨군요! 정말 맛있겠네요, $n 님. 키린 토 선봉대가 당신에게 빚을 졌네요.', `FemaleText_loc4`='终于送来了！这些胡萝卜很不错，$n。肯瑞托远征军欠你一份人情。', `FemaleText_loc5`='它們到了!真美啊，$n。祈倫托先遣軍欠了你的人情。', `FemaleText_loc7`='¡Aquí están! Son estupendas, $n. La Ofensiva del Kirin Tor está en deuda contigo.' WHERE `ID`=74545;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='주문한 파 때문에 왔네.', `FemaleText_loc4`='我是来取预定的小葱的。', `FemaleText_loc5`='我來接收我們訂的青蔥。', `FemaleText_loc7`='He venido a recoger nuestro pedido de cebolletas.' WHERE `ID`=74546;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='기대 이상의 결과군. 선리버 돌격대를 대신해 감사하네.', `FemaleText_loc4`='这些小葱的品质超出了我的预期，$c。夺日者先锋军感谢你的帮助。', `FemaleText_loc5`='這比我預期的還多，$c。奪日者先鋒軍感謝你。', `FemaleText_loc7`='Esto es más de lo que esperaba, $c. El Embate de los Atracasol te lo agradece.' WHERE `ID`=74547;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='독한 마음의 자릴이 적에게 던질 흰색 촉매 물약 여러 개를 준비합니다.', `MaleText_loc4`='毒心者夏克里尔调制了一些白色催化药剂掷向他的敌人！', `MaleText_loc5`='『毒化心智』薩瑞爾準備了一些白色催化藥劑投擲敵人!', `MaleText_loc7`='¡Xaril, la Mente Envenenada, prepara varios catalizadores blancos para lanzárselos a sus enemigos!' WHERE `ID`=74548;
