UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t 공성기술자 블랙퓨즈가 당신을 향해 |cFFFF0000|Hspell:143266|h[톱날 발사]|h|r를 준비합니다!', `MaleText_loc4`='|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t攻城匠师黑索转向你并准备|cFFFF0000|Hspell:143266|h[发射锯刃]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\inv_misc_sawblade_01.blp:20|t 攻城機匠黑引信面對你並準備|cFFFF0000|Hspell:143266|h[投擲鋸刃]|h|r!', `MaleText_loc7`='|TInterfaceIconsinv_misc_sawblade_01.blp:20|t ¡El asediador Mechanegra te mira y se prepara para |cFFFF0000|Hspell:143266|h[Lanzar sierra]|h|r!' WHERE `ID`=74553;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수정에 다가가자 잠재된 힘이 느껴집니다. 주변에 있는 요마들이 당신을 불안한 모습으로 바라봅니다.', `MaleText_loc4`='当靠近水晶时，你感受到了其中潜在的能量。附近的一些幽灵怀疑地向你看了过来。', `MaleText_loc5`='當你靠近水晶時，你能感覺到它強大的能量。附近的一些精魂狐疑地朝你的方向看來。', `MaleText_loc7`='Cuando te acercas al cristal, sientes la fuerza de su energía. Unos duendes cercanos te lanzan miradas inquietas.', `FemaleText_loc1`='수정에 다가가자 잠재된 힘이 느껴집니다. 주변에 있는 요마들이 당신을 불안한 모습으로 바라봅니다.', `FemaleText_loc4`='当靠近水晶时，你能感受到其中潜在的能量。附近的一些幽灵怀疑地向你看了过来。', `FemaleText_loc5`='當你靠近水晶時，你能感覺到它強大的能量。附近的一些精魂狐疑地朝你的方向看來。', `FemaleText_loc7`='Cuando te acercas al cristal, sientes la fuerza de su energía. Unos duendes cercanos te lanzan miradas inquietas.' WHERE `ID`=74554;
