UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너처럼 나도 이 오랜 판다렌 전통에 동참할 기회를 놓칠 수가 없더군. 준비가 되면, 네가 애완동물을 전투에서 얼마나 잘 이끌 수 있는지 보여다오.', `MaleText_loc4`='和你一样，我很难抗拒这个体验熊猫人古老传统的机会。当你准备好之后，就让我们看看你指挥宠物作战的本领吧。', `MaleText_loc5`='我和你一樣，沒辦法抗拒親身參與這個古老潘達利亞傳統的機會。等你準備好了，讓我們來瞧瞧你領導寵物作戰的本領。', `MaleText_loc7`='Al igual que tú, he aprovechado para participar en esta antigua tradición pandaren. Cuando te hayas preparado, demuéstrame cómo diriges a tus mascotas en combate.' WHERE `ID`=74564;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $n 님. 저는 오리아나입니다. 이 시합에서 애완동물들이 너무 심한 부상을 입지 않도록 보살피고, 시합의 규칙을 설명하는 역할을 맡고 있죠.

시합을 진행하는 동안 당신은 애완동물을 되살리거나 치유할 수 없답니다. 전투에 내보낼 애완동물이 없어지면 시합을 포기하고 나중에 다시 도전할 수 있어요.

다른 도전자에게 패배하더라도 그 도전자와 나중에 다시 싸울 수 있습니다.', `FemaleText_loc4`='你好啊，$n。我是奥利安娜，我负责救治重伤的宠物，并为参赛者解释规则。

你不能在比武大会期间治疗或复活宠物。如果你没有能够出战的宠物了，可以离开然后再次进入比武大会。

如果你输给某个挑战者，就需要与其重新比赛。', `FemaleText_loc5`='你好，$n。我是奧莉安娜，我來出席聯賽確保寵物不會傷重而亡，並解釋規則。

你在聯賽中不能治療或復活你的寵物。如果你已經沒有寵物能使用，你可以離開並重新加入聯賽。

如果你敗給一位挑戰者，你可以重新跟他們作戰。', `FemaleText_loc7`='Hola, $n. Me llamo Oriana y soy la encargada de vigilar que ninguna mascota quede gravemente herida y de explicar las reglas.

No puedes sanar ni revivir mascotas durante el torneo. Si te quedas sin mascotas con las que luchar, puedes abandonar el torneo y volver a entrar.

Si pierdes contra un oponente, puedes volver a desafiarlo.' WHERE `ID`=74565;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물을 치유하면 시나리오의 진척도가 초기화되고, 상대와 다시 싸워 나가야 합니다. 그래도 진행하시겠습니까?', `MaleText_loc4`='治疗宠物会使你失去当前场景战役的进度，而你也得与对手重新比试。你确定吗？', `MaleText_loc5`='治療你的寵物會使你在這個事件的進度無效，你將必須與這些對手重新對戰。你確定嗎?', `MaleText_loc7`='Sanar a tus mascotas eliminará tu progreso actual en la gesta y tendrás que volver a luchar contra todos los oponentes. ¿Seguro que quieres continuar?', `FemaleText_loc1`='애완동물을 치유하면 시나리오의 진척도가 초기화되고, 상대와 다시 싸워 나가야 합니다. 그래도 진행하시겠습니까?', `FemaleText_loc4`='治疗宠物会使你失去当前场景战役的进度，而你也得与对手重新比试。你确定吗？', `FemaleText_loc5`='治療你的寵物會使你在這個事件的進度無效，你將必須與這些對手重新對戰。你確定嗎?', `FemaleText_loc7`='Sanar a tus mascotas eliminará tu progreso actual en la gesta y tendrás que volver a luchar contra todos los oponentes. ¿Seguro que quieres continuar?' WHERE `ID`=74566;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원의 주화 5개로 쿠쿠루의 보관함 열쇠를 구매합니다.', `MaleText_loc4`='支付5枚永恒铸币换取1把库库鲁的宝箱钥匙。', `MaleText_loc5`='支付5枚永恆硬幣兌換一把庫庫魯的貯物箱鑰匙。', `MaleText_loc7`='Paga 5 monedas intemporales a cambio de la llave del alijo de Kukuru.', `FemaleText_loc1`='영원의 주화 5개로 쿠쿠루의 보관함 열쇠를 구매합니다.', `FemaleText_loc4`='支付5枚永恒铸币换取1把库库鲁的宝箱钥匙。', `FemaleText_loc5`='支付5枚永恆硬幣兌換一把庫庫魯的貯物箱鑰匙。', `FemaleText_loc7`='Paga 5 monedas intemporales a cambio de la llave del alijo de Kukuru.' WHERE `ID`=74567;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원의 주화 5개를 지불하겠습니까?', `MaleText_loc4`='支付5枚永恒铸币？', `MaleText_loc5`='支付5枚永恆硬幣?', `MaleText_loc7`='¿Pagar 5 monedas intemporales?', `FemaleText_loc1`='영원의 주화 5개를 지불하겠습니까?', `FemaleText_loc4`='支付5枚永恒铸币？', `FemaleText_loc5`='支付5枚永恆硬幣?', `FemaleText_loc7`='¿Pagar 5 monedas intemporales?' WHERE `ID`=74568;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 반짝이는 모든 것이 금은 아니다. 하지만 금은 물론 반짝인다. 반짝이는 건 좋은 거다.', `MaleText_loc4`='聪明的猢狲说了：发光的不都是金子。但是金子总会发光。', `MaleText_loc5`='有智慧的猴人說:不是全部閃亮亮的東西都是黃金。除非是真的黃金。那它就會閃亮亮的。', `MaleText_loc7`='Hozen sabio dice: No es oro todo lo ke reluce. Salvo si es oro. Entonces reluce.' WHERE `ID`=74569;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 부를 원하면 자신의 내면을 들여다 보라. 아니면 이 상자들 안을 들여다 보든가.', `MaleText_loc4`='聪明的猢狲说了：财富就在你的内心深处，或者在这些箱子中。', `MaleText_loc5`='有智慧的猴人說:要發財，要先看看自己。或打開那些箱子瞧瞧。', `MaleText_loc7`='Hozen sabio dice: Si makaku kiere rikeza, buska en tu korazón. O en un kofre del tesoro.' WHERE `ID`=74571;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 보이는 것이 전부가 아니다. 특히나 시력이 나쁘다면.', `MaleText_loc4`='聪明的猢狲说了：外表充满了欺骗性，尤其是当你的眼神不好时。', `MaleText_loc5`='有智慧的猴人說:不可以貌取人，特別是如果你的視力很差。', `MaleText_loc7`='Hozen sabio dice: Las apariencias engañan. Especialmente si makaku es miope.' WHERE `ID`=74572;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 먹을 수 있을 만큼만 입에 넣어라. 하지만 주위에 배고픈 호젠이 있을 때는 얘기가 달라진다.', `MaleText_loc4`='聪明的猢狲说了：有多大胃口吃多少东西，除非附近有其他饥饿的猢狲。', `MaleText_loc5`='有智慧的猴人說:別吃你吃不下的東西，除非附近有其他的猴人。', `MaleText_loc7`='Hozen sabio dice: En boka cerrada no entran moskas. Pero tampoko manduka...' WHERE `ID`=74573;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 말보다 행동이 중요하다. 하지만 목소리가 큰 사람의 말은 예외다.', `MaleText_loc4`='聪明的猢狲说了：行动比言语更加振聋发聩，除非那家伙在大喊大叫。', `MaleText_loc5`='有智慧的猴人說:言語的力量比不上行動，除非你用喊的。', `MaleText_loc7`='Hozen sabio dice: Una imagen vale mil palabras. A no ser que makaku grite...' WHERE `ID`=74574;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 실패는 성공의 어머니다. 어쨌든 성공은 아니라는 거다.', `MaleText_loc4`='聪明的猢狲说了：如果你第一次失败了，就找别人来帮你做。', `MaleText_loc5`='有智慧的猴人說:如果你第一次沒有成功，就找別人幫你做。', `MaleText_loc7`='Hozen sabio dice: Ojos ke no ven... kartera ke te roban.' WHERE `ID`=74575;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='현명한 호젠이 말하길, 오늘 할 일을... 아, 귀찮다. 다음 부분은 내일 말해줄게.', `MaleText_loc4`='聪明的猢狲说了：今日事今日毕……噢，算了，后半句我下次再告诉你吧。', `MaleText_loc5`='有智慧的猴人說:今日事今日...噢，剩下的我明天再說吧。', `MaleText_loc7`='Hozen sabio dice: Makaku no deja para mañana lo que... Da igual, yo te lo kuenta luego.' WHERE `ID`=74576;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='환영해, 여행자! 난 세계 곳곳의 보물을 많이 가지고 있어.$B$B운을 시험해 볼 테야? 영원의 주화 몇 개만 있으면 열쇠를 줄게.', `MaleText_loc4`='欢迎，旅行者！我这里有来自世界各地的宝物。$B$B想来试试手气吗？几个永恒铸币就能换一把钥匙了！', `MaleText_loc5`='歡迎，旅行者!我有來自世界各地的寶藏。$B$B你想試試自己的手氣嗎?只要幾枚永恆硬幣就能換一把鑰匙。', `MaleText_loc7`='¡Hola, makaku! Yo tiene tesoros de todo el mundo.$b$b¿Tú kiere probar suerte? Yo te da una llave a kambio de monedas intemporales.' WHERE `ID`=74577;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='안녕하세요, $N 님! 다시 뵈니 좋군요. 사람들이 아직까지도 당신이 승리한 지난 시합에 대해 이야기한답니다... 제가 경기를 보진 못했지만, 당신이 상대한 애완동물들의 화상이나 멍을 얼마나 많이 치료했다고요. 아, 걱정하진 마세요. 그 동물들은 이제 멀쩡하니까요!', `FemaleText_loc4`='嗨，$N！很高兴再次见到你。大家还在议论你上次赢得比武大会的事呢……我没能从头看到尾，因为有太多伤员需要我来治疗了。但不用担心，他们现在都好了！', `FemaleText_loc5`='哈囉，$n!很高興又見到你。大家都還在討論你上次贏得競賽的事情...我沒觀賞到全程，但是我治療了不少你們弄出來的瘀青和燒傷。不用擔心，牠們都好了!', `FemaleText_loc7`='¡Hola, $n! Me alegro de volver a verte. Todo el mundo habla de la última vez que ganaste el torneo... Yo no lo vi entero, pero tuve que sanar muchas quemaduras y contusiones. No te preocupes, ¡no fue nada grave!' WHERE `ID`=74578;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='%s|1이;가; |cFFFF0000|Hspell:144590|h[달송곳니의 저주]|h|r를 시전합니다.', `FemaleText_loc4`='%s开始施放|cFFFF0000|Hspell:144590|h[月牙的诅咒]|h|r。', `FemaleText_loc5`='%s開始施放|cFFFF0000|Hspell:144590|h[月牙的詛咒]|h|r。', `FemaleText_loc7`='%s empieza a lanzar |cFFFF0000|Hspell:144590|h[Maldición de Dienteluna]|h|r.' WHERE `ID`=74580;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 다시 맹공 모드로 전환합니다!', `MaleText_loc4`='%s切回了突击模式！', `MaleText_loc5`='%s切換回猛擊模式!', `MaleText_loc7`='¡%s entra en modo asalto!' WHERE `ID`=74584;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; 공성 모드로 전환합니다!', `MaleText_loc4`='%s切换至强攻模式！', `MaleText_loc5`='%s切換到攻城模式!', `MaleText_loc7`='¡%s entra en modo asedio!' WHERE `ID`=74585;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000공성 기술자|r들이 측면에서 나타나 |cFFFF0000|Hspell:144616|h[강철의 별 작동]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000攻城技师|r出现在两侧并开始施放|cFFFF0000|Hspell:144616|h[钢铁之星充能]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000攻城工程師|r在側廳出現並開始施放|cFFFF0000|Hspell:144616|h[鋼鐵之星充能]|h|r!', `MaleText_loc7`='|TInterfaceIconsability_mage_firestarter.blp:20|t¡Unos |cFFFF0000ingenieros de asedio|r entran por un lateral y empiezan a lanzar |cFFFF0000|Hspell:144616|h[Potenciar estrella de hierro]|h|r!' WHERE `ID`=74586;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='다들 무장하라! 놈들이 갑판 위로 온다!', `MaleText_loc4`='守住，伙计们！敌人登上甲板了！', `MaleText_loc5`='大夥兒拿起武器!有敵人登船了!', `MaleText_loc7`='¡Preparaos, muchachos! ¡Vienen al abordaje!' WHERE `ID`=74587;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하라! 또 몰려온다!', `MaleText_loc4`='小心！又有敌人冲过来了！', `MaleText_loc5`='小心!又有一波敵人來了!', `MaleText_loc7`='¡Atención! ¡Otra oleada!' WHERE `ID`=74588;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='온 힘을 다해 싸워라, 이놈들아! 우리는 조가비호와 운명을 같이 한다!', `MaleText_loc4`='想活命的就得先拼命，伙计们！如果藤壶号沉了，我们都得去喂鱼！', `MaleText_loc5`='為生命而戰，兄弟們!如果藤壺號會沉沒，我們就隨她一起沉沒吧!', `MaleText_loc7`='¡Luchen por sus vidas, muchachos! Si el Percebe se hunde, ¡nosotros vamos detrás!' WHERE `ID`=74589;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치에서 온기가 느껴집니다.', `MaleText_loc4`='这把锤子摸上去热乎乎的。', `MaleText_loc5`='錘子摸起來暖暖的。', `MaleText_loc7`='El martillo es cálido al tacto.', `FemaleText_loc1`='망치에서 온기가 느껴집니다.', `FemaleText_loc4`='这把锤子摸上去热乎乎的。', `FemaleText_loc5`='錘子摸起來暖暖的。', `FemaleText_loc7`='El martillo es cálido al tacto.' WHERE `ID`=74590;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='망치를 들어 올립니다.', `MaleText_loc4`='拿起锤子。', `MaleText_loc5`='拿起錘子。', `MaleText_loc7`='Coge el martillo.', `FemaleText_loc1`='망치를 들어 올립니다.', `FemaleText_loc4`='拿起锤子。', `FemaleText_loc5`='拿起錘子。', `FemaleText_loc7`='Coge el martillo.' WHERE `ID`=74591;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피랄론의 수염이여! 저게 도대체 뭐지? 없애 버려!', `MaleText_loc4`='菲尔拉伦的胡子啊，那是什么？杀了它！', `MaleText_loc5`='菲爾拉倫的鬍子啊，那是什麼東西?殺死它!', `MaleText_loc7`='¡Por las barbas de Firallon! ¿Qué es eso? ¡Mátalo!' WHERE `ID`=74592;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리가 해냈다. 조가비호를 지켜냈어! 마침내, 이 저주받을 안개에 갇힌 이후 처음으로 휴식을 취할 수 있겠군. 뱃머리를 돌려라, 형제여. 집으로 돌아가자!', `MaleText_loc4`='我们成功了，伙计们，我们拯救了藤壶号！自从进入这片隔绝一切的迷雾以来，我们总算能休息一会儿了。扬帆，伙计们。我们要回家啦！', `MaleText_loc5`='我們成功了，我們保住了藤壺號!自從我們踏入這片被遺忘的迷霧以來，終於可以休息一下了。調轉船帆，我們要回家了!', `MaleText_loc7`='¡Lo hemos conseguido, muchachos! ¡Hemos salvado al Percebe! Por fin, un respiro por primera vez desde que entramos en la maldita niebla. Icen las velas. ¡Nos marchamos!' WHERE `ID`=74593;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|cFFFF0000주의:|r 달송곳니 공포울음이 숲 속을 돌아다닙니다!', `FemaleText_loc4`='|cFFFF0000小心：|r月牙恐嚎者正在树林中徘徊！', `FemaleText_loc5`='|cFFFF0000小心:|r月牙恐貉開始在森林裡出沒!', `FemaleText_loc7`='|cFFFF0000ALERTA:|r ¡Aullidos de Pavor Dienteluna acechan por el bosque!' WHERE `ID`=74594;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|cFFFF0000BEWARE:|r 무리 어미 달송곳니가 숲 속에 나타났습니다!', `FemaleText_loc4`='|cFFFF0000小心：|r暗月巢母月牙出现在了树林中！', `FemaleText_loc5`='|cFFFF0000小心:|r月牙巢母出現在森林裡!', `FemaleText_loc7`='|cFFFF0000ALERtA:|r ¡La madre del cubil Dienteluna ha aparecido en el bosque!' WHERE `ID`=74595;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='다크문 섬의 무리 어미 달송곳니가 죽었습니다!', `FemaleText_loc4`='暗月巢母月牙被击杀了！', `FemaleText_loc5`='月牙，暗月島的巢母，被殺死了!', `FemaleText_loc7`='¡Dienteluna, madre del cubil de la Isla de la Luna Negra, ha muerto!' WHERE `ID`=74596;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멀리서 애절한 울음 소리가 들려옵니다.', `MaleText_loc4`='你听到远处传来一声凄凉的哀嚎。', `MaleText_loc5`='你聽到遠方傳來一陣悲傷的嚎叫聲。', `MaleText_loc7`='Oyes un aullido lastimero a lo lejos.' WHERE `ID`=74599;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황혼 속에 고통스런 울음 소리가 메아리칩니다.', `MaleText_loc4`='痛苦的哀嚎在暮色中回荡。', `MaleText_loc5`='一陣悲痛的嚎叫聲在暮光中迴盪。', `MaleText_loc7`='Un aullido de angustia resuena en el crepúsculo.' WHERE `ID`=74600;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='숲 속에 슬픈 울음 소리가 떠돕니다.', `MaleText_loc4`='森林中回荡着悲伤的低吼。', `MaleText_loc5`='一陣悲哀的嚎叫聲在森林中飄蕩。', `MaleText_loc7`='Un aullido pesaroso recorre el bosque.' WHERE `ID`=74601;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='깊은 숲 속에 고통스런 울음 소리가 울려 퍼집니다.', `MaleText_loc4`='树林深处传出了一声痛苦的嚎叫。', `MaleText_loc5`='有一陣痛苦的嚎叫聲從森林的深處傳出來。', `MaleText_loc7`='Se oye un aullido de dolor en lo más profundo del bosque.' WHERE `ID`=74602;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제... 조금만... 더...', `MaleText_loc4`='马上……就……好……', `MaleText_loc5`='幾乎...成功...了...', `MaleText_loc7`='Ya... casi... está...' WHERE `ID`=74603;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 이건 예상치 못했는데!', `MaleText_loc4`='噢，这可真是出人意料！', `MaleText_loc5`='嗯，真是沒想到!', `MaleText_loc7`='¡Eso no me lo esperaba!' WHERE `ID`=74604;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='어어... 이건 자네가 처리하게. 괜찮겠지?', `MaleText_loc4`='呃……你能搞定它的，对吧？', `MaleText_loc5`='呃...你可以解決這個的，對吧?', `MaleText_loc7`='Eh... ¿Puedes con esto?' WHERE `ID`=74605;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안녕하신가! 지금 입질이 막 온 참이네. 월척이 걸린 모양이야!', `MaleText_loc4`='噢，你好啊！我正打算收线呢。我有预感，这是个大家伙！', `MaleText_loc5`='噢，哈囉!我正準備把這次的戰利品拉起來。我有預感這會是個好東西!', `MaleText_loc7`='¡Ah, hola! Estaba a punto de tirar del pez. ¡Seguro que va a ser pan comido!' WHERE `ID`=74606;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭘 기다리고 있습니까? 한 번 봅시다!', `MaleText_loc4`='那你还等什么呢？！快让我们看看！', `MaleText_loc5`='你還在等什麼?咱們看看吧!', `MaleText_loc7`='¿A qué estás esperando? ¡Vamos a verlo!', `FemaleText_loc1`='뭘 기다리고 있어요? 한 번 보죠!', `FemaleText_loc4`='那你还等什么呢？！快让我们看看！', `FemaleText_loc5`='你還在等什麼?咱們看看吧!', `FemaleText_loc7`='¿A qué estás esperando? ¡Vamos a verlo!' WHERE `ID`=74607;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋아! 자네만 믿고 있겠네!', `MaleText_loc4`='好！那它就交给你了！', `MaleText_loc5`='很好!我會讓你來解決!', `MaleText_loc7`='¡Muy bien! ¡Todo tuyo!' WHERE `ID`=74608;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노. 증오. 공포! 이게 바로 전쟁의 무기다. 대족장이 써야 할 도구다!', `MaleText_loc4`='愤怒、仇恨、恐惧！这是战争的武器——酋长的工具！', `MaleText_loc5`='憤怒。仇恨。恐懼!它們是戰爭的武器，大酋長的工具!', `MaleText_loc7`='Ira. Odio. ¡¡Miedo!! Esas son las armas de la guerra: ¡las herramientas de un Jefe de Guerra! ' WHERE `ID`=74610;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래... 그래, 이제 보인다... 이 세계의 미래가 보인다... 호드가 지배하는... 나의 호드가 지배하는 세계가...', `MaleText_loc4`='啊，是的……我看见了……这世界的未来……由部落统治的世界……我的部落。', `MaleText_loc5`='是的...我看到...我看到了...這個世界的未來...由部落所統治...我的部落。', `MaleText_loc7`='Sí... sí, ya lo veo... Veo el futuro de este mundo... Un mundo reinado por la horda... MI horda.' WHERE `ID`=74616;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 세계로 들어와라.', `MaleText_loc4`='进入我的国度。', `MaleText_loc5`='進入我的領域。', `MaleText_loc7`='Entra en mi reino.' WHERE `ID`=74617;
