UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|cFFFF0000|Hspell:144985|h[소용돌이치는 타락]|h|r에 의해 목숨을 잃었습니다. 받는 피해를 줄이려면 가로쉬로부터 멀리 떨어지십시오.', `MaleText_loc4`='你被|cFFFF0000|Hspell:144985|h[腐蚀漩涡]|h|r击杀了。远离加尔鲁什可降低受到的伤害。', `MaleText_loc5`='你被|cFFFF0000|Hspell:144985|h[迴旋腐化]|h|r殺死了。遠離卡爾洛斯以減少所受的傷害。', `MaleText_loc7`='|cFFFF0000|Hspell:144985|h[Torbellino de corrupción]|h|r te ha matado. Aléjate de Garrosh para reducir el daño recibido.' WHERE `ID`=74621;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나의 영원한 경계가 교만의 타락을 궁지에 몰아 넣었다. 이 타락에 맞서려면 불타는 빛으로 몸을 정화시켜야 한다. 쉽지 않은 과정일 거다.

준비됐나?', `MaleText_loc4`='我不眠不休的监视将傲慢的腐蚀困锁于此。要想亲身面对这种腐蚀，你们就必须在熊熊燃烧的光明中净化自己。这个过程可不容易。

你们准备好了吗？', `MaleText_loc5`='我永恆的警戒使得驕傲的腐化無法侵襲。想要面對這樣的腐化，你必須先在燃燒的光明中淨化自己。這個過程並不容易。

你準備好了嗎?', `MaleText_loc7`='Mi vigilia eterna ha controlado a la corrupción del orgullo. Si quieren enfrentarse a ella, antes deberán purificarse en la luz abrasadora. Será un proceso doloroso.

¿Están preparados?' WHERE `ID`=74622;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='준비됐습니다.', `MaleText_loc4`='我们准备好了，守护者。', `MaleText_loc5`='我們準備好了，看守者。', `MaleText_loc7`='Lo estamos, vigía.', `FemaleText_loc1`='준비됐어요.', `FemaleText_loc4`='我们准备好了，守护者。', `FemaleText_loc5`='我們準備好了，看守者。', `FemaleText_loc7`='Lo estamos, vigía.' WHERE `ID`=74623;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='노루셴 전투를 시작하시겠습니까?', `MaleText_loc4`='确定要开启诺鲁什之战吗？', `MaleText_loc5`='你想要開始與諾努衫的戰鬥嗎?', `MaleText_loc7`='¿Deseas comenzar el encuentro de Norushen?', `FemaleText_loc1`='노루셴 전투를 시작하시겠습니까?', `FemaleText_loc4`='确定要开启诺鲁什之战吗？', `FemaleText_loc5`='你想要開始與諾努衫的戰鬥嗎?', `FemaleText_loc7`='¿Deseas comenzar el encuentro de Norushen?' WHERE `ID`=74624;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장님 무기고의 최신 병기, 강철의 별을 소개하지!', `MaleText_loc4`='这是酋长的最新武器：钢铁之星，大家喜欢吗？！', `MaleText_loc5`='看看你們怎麼應付大酋長最新的兵器:鋼鐵之星!', `MaleText_loc7`='Veamos qué les parece la nueva adición al arsenal del Jefe de Guerra: ¡la Estrella de Hierro!' WHERE `ID`=74625;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='요것 봐라. 내 거대괴수를 박살 낸 놈들이구나.', `MaleText_loc4`='噢，看看谁来了。就是你们毁了我的战蝎。', `MaleText_loc5`='噢，看看。就是你們把我的破滅邪神打爛的。', `MaleText_loc7`='Uy, miren. Ustedes fueron quienes aplastaron a mi Gigante.' WHERE `ID`=74626;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='일에 쾌락을 곁들일 시간이군.', `MaleText_loc4`='这将是工作和娱乐的完美结合。', `MaleText_loc5`='是時候寓工作於娛樂了。', `MaleText_loc7`='Hora de mezclar los negocios con placer.' WHERE `ID`=74627;
