UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 부족의 힘이 그대와 함께할 걸세.', `MaleText_loc4`='我的族人可以帮你们作战。我发誓。', `MaleText_loc5`='我們的部族會幫助你們。我發誓。', `MaleText_loc7`='La fuerza de mi clan estará con ustedes. Lo juro. Tú abre esta puerta.' WHERE `ID`=74629;
