UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이제 길을 잃었던 때로 돌아갑니다. 정말... 친절한 분이시군요.', `FemaleText_loc4`='我们又找回了失去的方向。你们是……好人。', `FemaleText_loc5`='我們找回了失去的方向。你們...非常仁慈。', `FemaleText_loc7`='Volvemos adonde perdimos el camino. Eres... muy amable.' WHERE `ID`=74637;
