UPDATE `locales_broadcast_text` SET `MaleText_loc1`='미안하지만 지금은 얘기할 기분이 아니네. 그냥 좀 내버려두게.', `MaleText_loc4`='我很抱歉，$n，可我不想聊天。请让我安静一会儿。', `MaleText_loc5`='很抱歉，$n，但是我現在真的不想聊天。別來煩我。', `MaleText_loc7`='Perdona, $n, pero no me apetece hablar. Déjame a solas.' WHERE `ID`=74649;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너무 많은 희생을 치렀는데, 전투는 계속되고 있어요. 이 전투는 제 영혼까지 지치게 하네요...', `FemaleText_loc4`='我们做出了这么多牺牲，可战斗依然久拖不决。这些战斗足以消磨我的意志……', `FemaleText_loc5`='我們做出了許多犧牲，但戰鬥還在持續著。這些戰鬥使我的靈魂感到無比的疲倦...', `FemaleText_loc7`='Hemos sacrificado tanto... Y la lucha continúa. Estas batallas me atormentan.' WHERE `ID`=74650;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='마음 단단히 먹으라고. 사랑하는 이들을 소중히 여기고. 우리가 세상에 얼마나 머물지 그 누구도 알 수 없으니까.', `MaleText_loc4`='坚强点，$c。珍惜你所爱的人。我们永远不知道自己能在这个世界上停留多久。', `MaleText_loc5`='振作起來，$c。想想你愛的那些人。我們都不知道我們還能在這個世界上活多久。', `MaleText_loc7`='No flaquees, $c. Aférrate a tus seres queridos. No sabemos cuánto tiempo nos queda en este mundo.' WHERE `ID`=74651;
