UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_monk_ringofpeace:20|t%s|1이;가; |cFFFF0000|Hspell:143955|h[고통, 슬픔, 그리고 우울]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_monk_ringofpeace:20|t%s施放了|cFFFF0000|Hspell:143955|h[祸不单行]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_monk_ringofpeace:20|t%s呼喚了|cFFFF0000|Hspell:143955|h[苦難，悔恨，憂鬱]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_monk_ringofpeace:20|t¡%s lanza |cFFFF0000|Hspell:143955|h[Desgracia, pena y tristeza]|h|r!' WHERE `ID`=74658;
