UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 이쁜이 ST-03 충격파 미사일 포탑을 소개하지!', `MaleText_loc4`='为各位送上——精美的ST-03震波飞弹炮台！', `MaleText_loc5`='來看看全新的ST-03衝擊波飛彈砲台!', `MaleText_loc7`='¡Presento la hermosa, la nueva, torreta de Misil de Ola de choque ST-03!' WHERE `ID`=74663;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그냥 폭탄은 시시하지. 폭탄 안에 폭탄이 두 개!', `MaleText_loc4`='知道有什么东西比炸弹更好吗？！答案是内含两颗炸弹的炸弹！', `MaleText_loc5`='有什麼比炸彈更好?裡面有兩顆炸彈的炸彈!', `MaleText_loc7`='¡¿Qué es mejor que una bomba?! ¡Una bomba con dos bombas dentro!' WHERE `ID`=74664;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='LT-403 증발 광선 맛을 봐라. 내 자랑거리지.', `MaleText_loc4`='来见识一下LT-403汽化激光炮。这可是鄙人的杰作。', `MaleText_loc5`='見識見識LT-403蒸發雷射。個人驕傲的傑作。', `MaleText_loc7`='Te presento el láser de Evaporación LT-403. Estoy particularmente orgulloso de él.' WHERE `ID`=74665;
