UPDATE `locales_broadcast_text` SET `MaleText_loc1`='청량음료를 마실 시간!', `MaleText_loc4`='吞下所有的苦酒吧！', `MaleText_loc5`='把所有飲料喝光的時候到了!', `MaleText_loc7`='TIME TO DRINK ALL THE  KOOL-AID!' WHERE `ID`=74697;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아직 늦지 않았다, 가로쉬. 대족장이라는 짐을 내려놓거라. 지금, 여기서 끝내자. 피를 흘릴 필요는 없다.', `MaleText_loc4`='现在还不迟，加尔鲁什。卸下酋长的包袱吧。我们可以就此结束这场流血冲突。', `MaleText_loc5`='卡爾洛斯，現在還不遲。放下大酋長的權力。我們可以在此時此地就結束，停止流血。', `MaleText_loc7`='No es demasiado tarde, Garrosh. Depón el manto de Jefe de Guerra. Podemos terminar con esto aquí, ahora, sin más derramamiento de sangre.' WHERE `ID`=74698;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그렇다면 나도 어쩔 수 없구나. 오래 전 저질렀던 실수를 이제는 바로잡아야겠다. 바람과 대지, 물의 정령이여, 내 부름에 답하라! 나를 도와다오!', `MaleText_loc4`='这是你逼我的。我要纠正过去犯下的错误。狂风、大地、流水之灵，听从我的召唤！请帮助我！', `MaleText_loc5`='你這樣讓我別無選擇了。我會改正許久之前犯下的錯。風，土，水之靈啊，傾聽我的呼喚!前來協助我!', `MaleText_loc7`='Entonces me has forzado a atacar.  Corregiré el error que cometí hace mucho tiempo.  ¡Espíritus del viento, la tierra, el agua: atiendan mi llamado!  ¡Vengan a ayudarme!' WHERE `ID`=74699;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬, 나는 약하지 않고, 혼자도 아니다.', `MaleText_loc4`='我或许很软弱。但我不是一个人。', `MaleText_loc5`='也許我是無能。但我並非孤軍奮戰。', `MaleText_loc7`='El poder me pudo haber abandonado, pero no estoy solo.' WHERE `ID`=74700;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하! 명예가 뭔지 기억이나 하나? 전장의 영광은? 인간 따위와 협상이나 하고, 우리 발밑에서 흑마법사들이 어둠의 마법을 주물럭거리게 내버려 두는 너 따위가 그런 걸 알 리가 없지. 넌 약하다.', `MaleText_loc4`='哈！你心中还有荣誉和战场的荣耀吗？你这个与人类媾和，允许术士在我们眼皮底下施行黑暗魔法的家伙。你这个懦夫。', `MaleText_loc5`='哈!你完全忘記榮譽了嗎?或者戰場上的榮耀?你會跟人類妥協，還讓術士在我們眼底使用他們的黑暗魔法。你這個弱者。', `MaleText_loc7`='¡Ja! ¿No recuerdas nada del Honor? ¿De la gloria en el campo de batalla?  Tú que dialogas con los humanos, que permites que los brujos practiquen sus magias oscuras bajo nuestros pies.  Eres débil.' WHERE `ID`=74701;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 오크 호드, 진정한 호드다. 전쟁터에서 피를 쏟으며 죽을 때까지 발버둥치지. 오크는 그런 존재다.', `MaleText_loc4`='我们是兽人的部落，是正统部落。我们会像真正的兽人那样，战死沙场，流血牺牲。', `MaleText_loc5`='我們是獸人的部落，正統的部落。我們若要死，就鮮血淋漓地死在戰場上，這才是獸人的活法。', `MaleText_loc7`='Somos la Horda de Orcos, la verdadera Horda.  Morimos ensangrentados y luchando en el campo de batalla, como DEBEN HACERLO los orcos de verdad.' WHERE `ID`=74702;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너는 이제 오크가 아니다. 네 말을 따를 자도 없어. 넌 부질없는 동맹을 맺는다는 이유로 우리를 배신했다. 내가 기꺼이 그 동맹이란 걸 갈기갈기 찢어 주마.', `MaleText_loc4`='你不配当一个兽人，你只能代表你自己。你背叛了我们的人民，来打造你那脆弱的同盟，能一手毁掉它是我的荣幸。', `MaleText_loc5`='你已經不是獸人，除了自己不再為任何人發言。你背叛了我們的人民締造脆弱的聯盟，而我會很高興地把它撕碎。', `MaleText_loc7`='Tú ya no eres un Orco y no representas a ninguno. Traicionaste a nuestra gente para forjar tus alianzas frágiles y disfrutaré mucho haciéndolas pedazos.' WHERE `ID`=74703;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멍청하긴. 내 암흑주술사들이 주위의 모든 정령들을 뒤틀고 고문했다. 놈들은 이제 네 말을 듣지 못해. 네가 얼마나 약하고 미천한 존재인지, 다시 한 번 보여주는구나.', `MaleText_loc4`='蠢货。我的黑暗萨满已经扭曲了这附近的元素。它们听不到你的召唤了。这再次证明了你是多么软弱，一事无成。', `MaleText_loc5`='愚蠢。我的黑暗薩滿已經折磨了幾里之內的元素。它們已經無法聽到你了。你再次證明你太過軟弱無能，什麼事都做不了。', `MaleText_loc7`='Iluso. Mi Chamán Oscuro ha retorcido y torturado a los elementos a kilómetros a la redonda. Ya no pueden oírte. Una vez más, has demostrado que eres  demasiado débil e impotente para hacer algo al respecto.' WHERE `ID`=74704;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 진정한 오크의 대족장에게 대들겠다는 건가. 멋대로 해 봐라.', `MaleText_loc4`='看来，你们想要挑战一位真正的兽人酋长。那好吧。', `MaleText_loc5`='看來你們想要跟真正的獸人大酋長敵對。如你們所願。', `MaleText_loc7`='Así que deseas enfrentar a un verdadero Jefe de Guerra Orco.  Que así sea.' WHERE `ID`=74705;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리 오크는 1차 대전쟁 때 이 세상을 차지해야 했다. 하지만 모두 타락에 빠졌고, 그 연약함 때문에 저 아제로스의 쓰레기 종족들을 호드에 받아들였다. 난 그들이 실패한 위업을 이뤄내겠다. 이 세상 어떤 힘도, 날 막을 수는 없다!', `MaleText_loc4`='早在第一次战争时，我的人民就该统治这个世界。可他们堕落了。他们软弱地允许艾泽拉斯的下等种族加入部落。我要完成他们未竟的事业，谁都别想阻止我！', `MaleText_loc5`='我們早在第一次獸人戰爭就該征服這個世界。但是他們被腐化影響。因為他們的軟弱，而讓艾澤拉斯其他的可悲種族加入了部落。我會完成他們無法達成的偉業，這個世界無人能阻止我!', `MaleText_loc7`='Mi gente debió haber tomado este mundo hace mucho tiempo durante la Primera Guerra. Pero cayeron bajo la corrupción. En su debilidad, permitieron que las razas patéticas de Azeroth se unieran a la horda. Yo triunfaré en donde ellos fracasaron ¡y ningún poder de este mundo podrá detenerme!' WHERE `ID`=74706;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드의 무기를 똑똑히 봐라!', `MaleText_loc4`='看看正统部落的军事实力吧！', `MaleText_loc5`='見證正統部落的實力吧!', `MaleText_loc7`='¡Contemplen el poder del arsenal de la verdadera Horda!' WHERE `ID`=74707;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강철과 불길로 이 세상을 정화해 주마!', `MaleText_loc4`='我们要用铁与火净化这个世界！', `MaleText_loc5`='我們會用鋼鐵及火焰淨化這個世界!', `MaleText_loc7`='¡Purificaremos este mundo con acero y fuego!' WHERE `ID`=74708;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전쟁인도자, 칼에 피를 묻혀라! 록타르 오가르!', `MaleText_loc4`='蛮兵们，染红你们的刀刃吧！Lok''tar Ogar！', `MaleText_loc5`='蠻兵們，用血染紅刀刃!Lok''tar Ogar!', `MaleText_loc7`='Belisarios, ¡bañen sus cuchillas en sangre!  ¡Lok''tar Ogar!' WHERE `ID`=74709;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='션견자, 우리를 치료하라!', `MaleText_loc4`='先知们，为我们治疗！', `MaleText_loc5`='先知們，治療我們的傷口!', `MaleText_loc7`='Clarividentes: ¡atiendan nuestras heridas!' WHERE `ID`=74710;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='명예롭게 죽어라!', `MaleText_loc4`='为荣耀而死！', `MaleText_loc5`='為了榮耀而死!', `MaleText_loc7`='¡Mueran con honor!' WHERE `ID`=74711;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='피바람을 불러 일으키자!', `MaleText_loc4`='鲜血与雷鸣！', `MaleText_loc5`='鮮血與雷霆!', `MaleText_loc7`='¡Sangre y trueno!' WHERE `ID`=74712;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드를 위하여!', `MaleText_loc4`='为了正统部落！', `MaleText_loc5`='為了正統的部落!', `MaleText_loc7`='¡Por la verdadera Horda!' WHERE `ID`=74713;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 안에 힘이 넘쳐 흐른다! 으아아!', `MaleText_loc4`='我充满了力量！', `MaleText_loc5`='我充滿了力量!', `MaleText_loc7`='¡El poder fluye por mi cuerpo!' WHERE `ID`=74714;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 힘으로 너의 세계와 모든 것을 부숴 주마!', `MaleText_loc4`='这力量将碾碎你们的世界，抹杀一切！', `MaleText_loc5`='我的力量能摧毀你的世界，殺光一切生物!', `MaleText_loc7`='¡El poder para aplastar su mundo y todo lo que hay en él!' WHERE `ID`=74715;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='헬스크림의 이름 앞에 모두가 쓰러지리라!', `MaleText_loc4`='以地狱咆哮之名，毁灭一切！', `MaleText_loc5`='以地獄吼之名，全都倒下吧!', `MaleText_loc7`='¡Todo caerá en el nombre de Grito Infernal!' WHERE `ID`=74716;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='약한 것.', `MaleText_loc4`='懦夫。', `MaleText_loc5`='弱者。', `MaleText_loc7`='Débil.' WHERE `ID`=74717;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='쳇, 가엾군.', `MaleText_loc4`='可怜虫。', `MaleText_loc5`='可悲。', `MaleText_loc7`='Lamentable.' WHERE `ID`=74718;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 내 세계에서 너희가 있을 곳을 알았겠지.', `MaleText_loc4`='你们在我的新世界中一文不值。', `MaleText_loc5`='知道自己在新世界裡面的地位了嗎?', `MaleText_loc7`='Ahora conoces tu lugar en mi nuevo mundo.' WHERE `ID`=74719;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고대 신이 너를 부른다!', `MaleText_loc4`='上古尊者在召唤！', `MaleText_loc5`='上古之神在召喚你!', `MaleText_loc7`='¡El Antiguo los llama!' WHERE `ID`=74720;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 심장이 널 없앨 것이다!', `MaleText_loc4`='亚煞极之心就是你们的末日！', `MaleText_loc5`='古神之心會消滅你們!', `MaleText_loc7`='¡El Corazón será su fin!' WHERE `ID`=74721;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='공포와 절망, 의심의 모습을 네 눈으로 직접 확인해라!', `MaleText_loc4`='跟我一起看清恐惧，绝望与猜忌的幻象吧！', `MaleText_loc5`='跟我一樣，看看恐懼、絕望和懷疑的面目吧!', `MaleText_loc7`='¡Vean las visiones de miedo, desesperación y duda que yo he visto!' WHERE `ID`=74722;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='세상이 끝날 때까지 가둬 주마!', `MaleText_loc4`='你们将被永远禁锢于此！', `MaleText_loc5`='你們會被永遠地禁錮!', `MaleText_loc7`='¡Quedarán atrapados para toda la eternidad!' WHERE `ID`=74723;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진정한 호드가 태어날 것이다. 나는 그 모습을 봤다. 그것이 내게 보여줬다. 해골의 산과 피의 강을 분명히 봤다. 이제 나는... 내 세계를... 손에 넣을 것이다!', `MaleText_loc4`='正统部落必将诞生。我看到了。它让我看到了。我看到尸山血海。我将……拥有……我的……世界！', `MaleText_loc5`='正統部落將會獲勝。我已經見過了。它讓我看過。我看到骨山血河。我...會...得到...我的...世界!', `MaleText_loc7`='La verdadera Horda PASARÁ. Yo lo VI.  ME LO MOSTRÓ. VI MONTAÑAS DE CRÁNEOS Y RÍOS DE SANGRE. ¡Y YO... TENDRÉ... MI... MUNDO!' WHERE `ID`=74724;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='로도라고 하오.', `MaleText_loc4`='鲁铎。', `MaleText_loc5`='羅道。', `MaleText_loc7`='Rodoh.' WHERE `ID`=74728;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시합에 참가하고 싶습니다.', `MaleText_loc4`='我想参加比武大会。', `MaleText_loc5`='我想參加武道會。', `MaleText_loc7`='Me gustaría participar en el torneo.', `FemaleText_loc1`='시합에 참가하고 싶습니다.', `FemaleText_loc4`='我想参加比武大会。', `FemaleText_loc5`='我想參加武道會。', `FemaleText_loc7`='Me gustaría participar en el torneo.' WHERE `ID`=74729;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저도 시합에 참가할 수 있나요?', `MaleText_loc4`='我能参加比武大会吗？', `MaleText_loc5`='我可以參加武道會嗎?', `MaleText_loc7`='¿Puedo entrar en el torneo?', `FemaleText_loc1`='저도 시합에 참가할 수 있나요?', `FemaleText_loc4`='我能参加比武大会吗？', `FemaleText_loc5`='我可以參加武道會嗎?', `FemaleText_loc7`='¿Puedo entrar en el torneo?' WHERE `ID`=74730;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신이 지금까지 혼자서 잘해 왔단 건 알고 있소. 하지만 천신의 시합에 참가하려면 당신이 강력한 지도자임을 증명해야 하오. 전투 애완동물 15마리를 최고 레벨까지 키우면, 시합에 참가할 자격을 얻을 수 있을 거요.', `MaleText_loc4`='我能看得出来，你的个人实力很强。但要想参加天神比武大会，你还必须证明自己的领导能力。只有等你将十五只战斗宠物练到满级之后，才能面对这里的挑战。', `MaleText_loc5`='我看得出來，你還挺有本事的。可是想參加天尊武道會，你得證明自己足以成為領袖。等你把15個戰鬥寵物的等級升到最高，你就可以參加那些等待著你的試煉。', `MaleText_loc7`='Veo que te las arreglas muy bien por tu cuenta, pero para entrar en el Torneo Celestial hace falta demostrar competencias de liderazgo. Cuando hayas subido a quince mascotas de duelo al nivel máximo, podrás enfrentarte a los retos que te esperan aquí.' WHERE `ID`=74731;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='반란군 편은 아니겠지?', `MaleText_loc4`='你不是起义者吧？', `MaleText_loc5`='你不是跟那些革命軍一夥的，對吧?', `MaleText_loc7`='Tú no apoyas a los revolucionarios, ¿verdad?', `FemaleText_loc1`='반란군 편은 아니겠지?', `FemaleText_loc4`='你不是起义者吧？', `FemaleText_loc5`='你不是跟那些革命軍一夥的，對吧?', `FemaleText_loc7`='Tú no apoyas a los revolucionarios, ¿verdad?' WHERE `ID`=74754;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='용건이 있으면 빨리 말하게, $r. 자네 같은 자를 보면 짜증이 나네.', `MaleText_loc4`='快点，$r，你们真让我恶心。', `MaleText_loc5`='動作快點，$r，你讓我有點想吐。', `MaleText_loc7`='Que sea rápido, $r. Tu especie me da náuseas.', `FemaleText_loc1`='용건이 있으면 빨리 말하게, $r. 자네 같은 자를 보면 짜증이 나네.', `FemaleText_loc4`='快点，$r，你们真让我恶心。', `FemaleText_loc5`='動作快點，$r，你讓我有點想吐。', `FemaleText_loc7`='Que sea rápido, $r. Tu especie me da náuseas.' WHERE `ID`=74755;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='수련의 장 진입', `MaleText_loc4`='进入试炼场。', `MaleText_loc5`='進入試煉場。', `MaleText_loc7`='Entrar en el Terreno de Pruebas', `FemaleText_loc1`='수련의 장 진입', `FemaleText_loc4`='进入试炼场。', `FemaleText_loc5`='進入試煉場。', `FemaleText_loc7`='Entrar en el Terreno de Pruebas' WHERE `ID`=74757;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='애완동물 전투석을 거래하고 싶습니다만?', `MaleText_loc4`='想要兑换你的战斗石吗？', `MaleText_loc5`='有興趣做點寵物戰鬥石的交易嗎?', `MaleText_loc7`='¿Te interesa intercambiar piedras de duelo?', `FemaleText_loc1`='애완동물 전투석을 거래하고 싶은데요?', `FemaleText_loc4`='想要兑换你的战斗石吗？', `FemaleText_loc5`='有興趣做點寵物戰鬥石的交易嗎?', `FemaleText_loc7`='¿Te interesa intercambiar piedras de duelo?' WHERE `ID`=74772;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 방식은 절대 실패하지 않는다!', `MaleText_loc4`='我的方法是绝不会失败的！', `MaleText_loc5`='我的方法不會錯!', `MaleText_loc7`='¡Mis métodos nunca fallan!' WHERE `ID`=74775;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 방식에 의문을 가질 순 있지만 결과를 부인할 순 없다.', `MaleText_loc4`='很多人都质疑我的方法，但没人能否认我的成果。', `MaleText_loc5`='有人會質疑我的手段，但沒人能否認我的成果。', `MaleText_loc7`='Hay quien cuestiona mis métodos, pero los resultados son innegables.' WHERE `ID`=74776;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고통은 혀를 풀어 준다. 내 말을 믿어라.', `MaleText_loc4`='相信我吧，$r。酷刑能撬开所有人的嘴巴。', `MaleText_loc5`='苦痛會讓嘴巴變得不牢。相信我，$r。', `MaleText_loc7`='El sufrimiento suelta la lengua. Créeme, $r.' WHERE `ID`=74777;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='모두가 나처럼 칼 같이 일할 순 없지.$b$b<심문관 사이프가 칼을 갑니다.>$b$b칼 같이 말이야.', `MaleText_loc4`='我这活儿可不是人人都能干的。$b$b<折磨者赛普磨着他的小刀。>$b$b天赋，明白吗？噢，我真是个天才。', `MaleText_loc5`='不是每個人都能做我做的工作。$b$b<折磨者席普正在磨他的刀。>$b$b不是每個人都是這塊料，懂嗎?哈哈，我真幽默。', `MaleText_loc7`='A mucha gente la da corte este trabajo.$b$b<El torturador Sipe afila su hoja.>$b$bCorte... ¿lo pillas? Muero de la risa.' WHERE `ID`=74778;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저 트롤은 나한테 알고 있는 얘기를 털어놓을 생각이 없는 것 같은데. $c, 네가 한번 찔러 보겠나?', `MaleText_loc4`='那个巨魔似乎并不打算开口。你想拿他来练练手吗，$c？', `MaleText_loc5`='那個食人妖看樣子是不想告訴我他知道的事情了。你想戳他一刀嗎，$c?', `MaleText_loc7`='Ese trol no quiere contarme lo que sabe. ¿Quieres probar a darle un corte, $c?' WHERE `ID`=74779;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 모든 싸움이 끝나면, 난 듀로타에 가서 쉴까 한다.$b$b언덕에 작은 집을 짓고 말이야. 마당도 조금 있으면 좋겠군.$b$b그래, 이거 참 좋은 생각이군.', `MaleText_loc4`='等这场战争结束后，我打算回杜隆塔尔去。$b$b在山上造一座小房子，或许还带一个小花园。$b$b嗯，听起来不错。', `MaleText_loc5`='當戰火逼近時，我想我會退隱到杜洛塔。$b$b到山丘上的一幢小房子裡，或許還有個小花園。$b$b是啊，聽起來很不錯。', `MaleText_loc7`='Cuando todo este conflicto haya terminado, creo que me jubilaré en Durotar.$b$bUna cabaña en una colina. Un jardín, tal vez.$b$bSí, suena bien.' WHERE `ID`=74780;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려. 오늘이 끝나기 전에 저 트롤이 노래를 부르게 만들 테니.', `MaleText_loc4`='等一会儿，我马上就让那个巨魔尖叫到半夜。', `MaleText_loc5`='等著看吧，太陽下山前我會把那個食人妖打得唉唉叫。', `MaleText_loc7`='Ya verás, ese trol cantará antes de que se ponga el sol.' WHERE `ID`=74781;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='천막 안에 있는 랄룸 다크메인을 찾아가십시오.', `MaleText_loc4`='去村里的主帐篷里找拉鲁姆·黑鬃吧。', `MaleText_loc5`='去找菈盧姆·黑鬃，就在村子裡的主帳篷裡。', `MaleText_loc7`='Busca a Lalum Crinoscura. Está en el tipi principal de la aldea.', `FemaleText_loc1`='천막 안에 있는 랄룸 다크메인을 찾아가십시오.', `FemaleText_loc4`='去村里的主帐篷里找拉鲁姆·黑鬃吧。', `FemaleText_loc5`='去找菈盧姆·黑鬃，就在村子裡的主帳篷裡。', `FemaleText_loc7`='Busca a Lalum Crinoscura. Está en el tipi principal de la aldea.' WHERE `ID`=74782;
