UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\sha_spell_warlock_demonsoul.blp:20|t %s|1이;가; |cFFF00000|Hspell:144400|h[팽창하는 교만]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\sha_spell_warlock_demonsoul.blp:20|t%s开始施放|cFFF00000|Hspell:144400|h[傲气冲天]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\sha_spell_warlock_demonsoul.blp:20|t%s開始施展|cFFF00000|Hspell:144400|h[傲氣凌人]|h|r!', `MaleText_loc7`='|TInterfaceIconssha_spell_warlock_demonsoul.blp:20|t ¡%s empieza a lanzar |cFFF00000|Hspell:144400|h[Orgullo henchido]|h|r!', `FemaleText_loc1`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t %s|1이;가; |cFFF00000|Hspell:144400|h[팽창하는 교만]|h|r을 시전합니다!', `FemaleText_loc4`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s开始施放|cFFF00000|Hspell:144400|h[傲气冲天]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s開始施展|cFFF00000|Hspell:144400|h[傲氣凌人]|h|r!', `FemaleText_loc7`='|TInterfaceIconssha_spell_warlock_demonsoul.blp:20|t ¡%s empieza a lanzar |cFFF00000|Hspell:144400|h[Orgullo henchido]|h|r!' WHERE `ID`=74792;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='드디어 적들이 도착했구나! 파괴전차, 공격!', `MaleText_loc4`='敌人终于来了！投石车，自由射击！', `MaleText_loc5`='敵人終於來了!石毀車，自由開火!', `MaleText_loc7`='¡Al fin han llegado nuestros enemigos!  Demoledores: ¡disparen a discreción!' WHERE `ID`=74795;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<늑대가 현명한 눈으로 당신을 봅니다.>', `MaleText_loc4`='<这头狼用充满智慧的眼睛看着你。>', `MaleText_loc5`='<那匹狼以睿智的雙眼望著你。>', `MaleText_loc7`='<El lobo te observa con una mirada sabia.>' WHERE `ID`=74798;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='|TInterface\\Icons\\ability_priest_halo_shadow:20|t%s|1이;가; |cFFFF0000|Hspell:143491|h[재앙]|h|r을 시전합니다!', `FemaleText_loc4`='|TInterface\\Icons\\ability_priest_halo_shadow:20|t%s开始施放|cFFFF0000|Hspell:143491|h[灾祸]|h|r！', `FemaleText_loc5`='|TInterface\\Icons\\ability_priest_halo_shadow:20|t%s開始施放|cFFFF0000|Hspell:143491|h[災禍]|h|r!', `FemaleText_loc7`='|TInterfaceIconsability_priest_halo_shadow:20|t¡%s empieza a lanzar |cFFFF0000|Hspell:143491|h[Calamidad]|h|r!' WHERE `ID`=74799;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t 활성화된 레이저 포탑이 당신을 조준합니다!', `MaleText_loc4`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t一座激活的激光炮台锁定了你！', `MaleText_loc5`='|TInterface\\Icons\\Ability_Siege_Engineer_Superheated.blp:20|t啟動的雷射砲台已經鎖定你了!', `MaleText_loc7`='|TInterfaceIconsAbility_Siege_Engineer_Superheated.blp:20|t ¡Una torreta láser activada te ha seleccionado como objetivo!' WHERE `ID`=74800;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\Ability_Siege_Engineer_Detonate.blp:20|t 거미 지뢰가 당신을 대상으로 포착합니다!', `MaleText_loc4`='|TInterface\\Icons\\Ability_Siege_Engineer_Detonate.blp:20|t一个蛛形地雷瞄准了你！', `MaleText_loc5`='|TInterface\\Icons\\Ability_Siege_Engineer_Detonate.blp:20|t爬行者地雷已經瞄準你了!', `MaleText_loc7`='|TInterfaceIconsAbility_Siege_Engineer_Detonate.blp:20|t¡Una mina reptadora te ha seleccionado como objetivo!' WHERE `ID`=74801;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워! 이제 여기서 빠져나가야겠어!', `MaleText_loc4`='谢谢！我这就离开这儿！', `MaleText_loc5`='謝謝!我在想辦法離開這裡!', `MaleText_loc7`='¡Gracias! ¡Me largo de aquí!', `FemaleText_loc1`='고마워요! 여기서 빠져나가야겠어요!', `FemaleText_loc4`='谢谢！我这就离开这儿！', `FemaleText_loc5`='謝謝!我在想辦法離開這裡!', `FemaleText_loc7`='¡Gracias! ¡Me largo de aquí!' WHERE `ID`=74802;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으아! 으아아아아아아!', `MaleText_loc4`='啊！啊啊啊！', `MaleText_loc5`='啊!啊啊!!!', `MaleText_loc7`='¡Aah! ¡Aaaaaaaaaaaah!', `FemaleText_loc1`='으아! 으아아아아아아!', `FemaleText_loc4`='啊！啊啊啊！', `FemaleText_loc5`='啊!啊啊!!!', `FemaleText_loc7`='¡Aah! ¡Aaaaaaaaaaaah!' WHERE `ID`=74803;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이곳은 이제 지긋지긋해! 망할 오크놈들. 오크가 언제나 문제야!', `MaleText_loc4`='我得离开这儿！白痴兽人，我最讨厌兽人了！', `MaleText_loc5`='我要走了!蠢獸人，最討厭獸人了!', `MaleText_loc7`='¡Me retiro! ¡Estúpidos orcos! ¡Siempre he odiado a los orcos!', `FemaleText_loc1`='이곳은 이제 지긋지긋해요! 망할 오크놈들. 오크가 언제나 문제라고요!', `FemaleText_loc4`='我得离开这儿！白痴兽人，我最讨厌兽人了！', `FemaleText_loc5`='我要走了!蠢獸人，最討厭獸人了!', `FemaleText_loc7`='¡Me retiro! ¡Estúpidos orcos! ¡Siempre he odiado a los orcos!' WHERE `ID`=74804;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='넌 내 생명의 은인이야!', `MaleText_loc4`='我欠你一条命！', `MaleText_loc5`='我欠你一條命!', `MaleText_loc7`='¡Te debo la vida!', `FemaleText_loc1`='당신은 제 생명의 은인이세요!', `FemaleText_loc4`='我欠你一条命！', `FemaleText_loc5`='我欠你一條命!', `FemaleText_loc7`='¡Te debo la vida!' WHERE `ID`=74805;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고마워!', `MaleText_loc4`='谢谢！', `MaleText_loc5`='謝謝!', `MaleText_loc7`='¡Gracias!', `FemaleText_loc1`='고마워요!', `FemaleText_loc4`='谢谢！', `FemaleText_loc5`='謝謝!', `FemaleText_loc7`='¡Gracias!' WHERE `ID`=74806;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네가 최고야!', `MaleText_loc4`='你是最棒的！', `MaleText_loc5`='你是最棒的!', `MaleText_loc7`='¡Eres lo mejor!', `FemaleText_loc1`='당신이 최고예요!', `FemaleText_loc4`='你是最棒的！', `FemaleText_loc5`='你是最棒的!', `FemaleText_loc7`='¡Eres lo mejor!' WHERE `ID`=74807;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런 곳 따위 개나 줘버려!', `MaleText_loc4`='这该死的鬼地方！', `MaleText_loc5`='這個地方真是差勁透了! ', `MaleText_loc7`='¡Al infierno con este sitio!', `FemaleText_loc1`='이런 곳 따위 개나 줘버려!', `FemaleText_loc4`='这该死的鬼地方！', `FemaleText_loc5`='這個地方真是差勁透了! ', `FemaleText_loc7`='¡Al infierno con este sitio!' WHERE `ID`=74808;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 내버려 둬!', `MaleText_loc4`='别碰我！！', `MaleText_loc5`='走開!不要管我!', `MaleText_loc7`='¡Déjenme todos en paz!', `FemaleText_loc1`='날 내버려 둬요!', `FemaleText_loc4`='别碰我！！', `FemaleText_loc5`='走開!不要管我!', `FemaleText_loc7`='¡Déjenme todos en paz!' WHERE `ID`=74809;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이여, 제 부름에 답해 쓰러진 전사를 도와주십시오!', `MaleText_loc4`='万灵，请听从我的召唤！帮助这位倒下的战士吧！', `MaleText_loc5`='靈魂啊，聽從我的號令，幫助這位倒下的戰士!', `MaleText_loc7`='Espíritus, ¡escuchen mi llamada! ¡Ayuden a este guerrero caído!' WHERE `ID`=74812;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='움직이지 말게.', `MaleText_loc4`='别动。', `MaleText_loc5`='穩住。', `MaleText_loc7`='No te muevas.' WHERE `ID`=74813;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='최전선에 계신 볼진 님께는 자네가 필요하다네.', `MaleText_loc4`='前线的沃金需要你！', `MaleText_loc5`='沃金需要你在前線作戰!', `MaleText_loc7`='¡Vol''jin te necesita en el frente!' WHERE `ID`=74814;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='정령들이 당신과 함께하길.', `MaleText_loc4`='愿万灵保佑你。', `MaleText_loc5`='願靈魂助你一臂之力。', `MaleText_loc7`='Que los espíritus te ayuden.' WHERE `ID`=74815;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이야, 고마워! 여기 온 김에, 내 물건들을 한 번 보겠어? 판다리아에서 갓 들여온 신상품이라고! 저렴하진 않을 거야. 전쟁 중이라서 말이야. 알지?', `MaleText_loc4`='嘿，谢谢！在我离开之前，你要看看我的货物吗？都是刚从潘达利亚运来的新鲜货色。东西是不便宜，你也知道，现在可是战争时期。', `MaleText_loc5`='嘿，謝謝!既然我在這裡，你要不要看看我的貨品?剛從潘達利亞進貨的。價錢不便宜，兵荒馬亂嘛，你懂的。', `MaleText_loc7`='¡Muchas gracias! Ya que estamos, ¿quieres echar un vistazo a mi mercancía? Tengo cosas recién llegadas de Pandaria. No son baratas, pero claro, estamos en guerra...' WHERE `ID`=74816;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 다른 이들처럼 불타지 않을 것이다! 반역자여, 너의 공포인 악마를 맞이해라!', `MaleText_loc4`='我是不会像其他人那样坐以待毙的！面对你们最惧怕的恶魔吧，叛徒', `MaleText_loc5`='我可不會像其他人一樣被燒得慘兮兮!面對你的恐懼，叛徒!', `MaleText_loc7`='¡Yo no arderé como los demás! ¡Enfréntense a sus demonios, traidores!' WHERE `ID`=74817;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대족장은 내 조언을 무시했네. 결국 성난불길의 동굴 아래 주둔지를 만들고야 말았지.', `MaleText_loc4`='酋长无视了我的议会。我发现他在怒焰裂谷的洞穴下造了个基地。', `MaleText_loc5`='大酋長無視我的建議。我發現他在怒焰裂谷底下建了一個基地。', `MaleText_loc7`='El Jefe de Guerra ignoró mi consejo. Descubrí que estaba construyendo un complejo debajo de las cavernas de Furia Ardiente.' WHERE `ID`=74822;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='스랄과 사울팽은 먼저 내려갔네.', `MaleText_loc4`='萨尔和萨鲁法尔已经下去了。', `MaleText_loc5`='索爾和薩魯法爾已經先下去了。', `MaleText_loc7`='Thrall y Colmillosauro ya han descendido.' WHERE `ID`=74823;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='조심하게. 가로쉬는 저 밑에 온갖 병기들을 모아놨어. 고블린 용병, 판다렌 유물, 그리고 내 영혼 깊은 곳까지 느껴지는 어두운 무언가까지...', `MaleText_loc4`='小心点。地狱咆哮把下面变成了一座兵工厂——里面有地精佣兵，熊猫人神器，我感觉到，还有某种黑暗存在。', `MaleText_loc5`='小心前進。地獄吼在下面準備了不少東西 - 有哥布林傭兵，熊貓人神器，還有我的靈魂都能感覺到的某種黑暗之物。', `MaleText_loc7`='Vayan con cuidado.  Grito Infernal ha estado reuniendo un arsenal allí abajo: mercenarios goblin, artefactos pandaren y alguna especie de oscuridad que puedo sentir en mi mismísima alma.' WHERE `ID`=74824;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='무서워요!', `MaleText_loc4`='我害怕！', `MaleText_loc5`='我好怕!', `MaleText_loc7`='¡Tengo miedo!', `FemaleText_loc1`='무서워요!', `FemaleText_loc4`='我害怕！', `FemaleText_loc5`='我好怕!', `FemaleText_loc7`='¡Tengo miedo!' WHERE `ID`=74825;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='뒤에 바짝 붙어요! 머리를 숙이고!', `FemaleText_loc4`='呆在我们后面！把头低下！', `FemaleText_loc5`='躲在我們身後!把頭低下來!', `FemaleText_loc7`='¡Quédense detrás! ¡Bajen la cabeza!' WHERE `ID`=74826;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자동 분쇄기가 다가옵니다!', `MaleText_loc4`='一台自动伐木机正在靠近！', `MaleText_loc5`='有個自動化伐木機靠近了!', `MaleText_loc7`='¡Una trituradora automática se acerca!' WHERE `ID`=74827;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론은 준비됐다. 적에게 와서 칼 맛을 보라고 전해라!', `MaleText_loc4`='库卡隆已经蓄势待发了。让他们来尝尝铁与血的滋味吧！', `MaleText_loc5`='柯爾克隆軍已準備就緒，讓他們來嘗嘗我們的厲害!', `MaleText_loc7`='Los Kor''kron están listos. ¡Que vengan y prueben nuestro acero!', `FemaleText_loc1`='코르크론은 준비됐다. 적에게 와서 칼 맛을 보라고 전해라!', `FemaleText_loc4`='库卡隆已经蓄势待发了。让他们来尝尝铁与血的滋味吧！', `FemaleText_loc5`='柯爾克隆軍已準備就緒，讓他們來嘗嘗我們的厲害!', `FemaleText_loc7`='Los Kor''kron están listos. ¡Que vengan y prueben nuestro acero!' WHERE `ID`=74830;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 군대가 거의 도착했네.', `MaleText_loc4`='几乎所有的部队都在这儿了。', `MaleText_loc5`='所有部隊現在幾乎都在這裡。', `MaleText_loc7`='Ya casi eh''tán todas las tropas.' WHERE `ID`=74831;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 마음이 편치가 않다네, 친구.', `MaleText_loc4`='我有点不安，老朋友。', `MaleText_loc5`='我很不安，老朋友。', `MaleText_loc7`='Estoy inquieto, viejo amigo.' WHERE `ID`=74832;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나도 마찬가지일세. 가로쉬가 처음부터 이럴 작정이었을 줄이야. 놈의 꿍꿍이를 전혀 몰랐지.', `MaleText_loc4`='我也是。我们完全不知道加尔鲁什到底有什么阴谋，也不知道究竟有什么在等着我们。', `MaleText_loc5`='我也是。我們不知道卡爾洛斯這段時間都在謀劃什麼，準備了什麼東西對付我們。', `MaleText_loc7`='Yo también. No sabemos qué se trae Garrosh entre manos. No sabemos lo que ha eh''tado haciendo...' WHERE `ID`=74833;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='호드의 안전이 걱정되는군.', `MaleText_loc4`='我很担心族人的安全。', `MaleText_loc5`='我為我們的安全擔憂。', `MaleText_loc7`='Temo por la seguridad de nuestra gente.' WHERE `ID`=74834;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='살아남지 못하는 이들도 있겠지.', `MaleText_loc4`='这场战争过后，许多人都会死去。', `MaleText_loc5`='不是每個人都能活著從這裡出來。', `MaleText_loc7`='No todos saldrán con vida de eh''ta batalla.' WHERE `ID`=74835;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 희생이 무얼 위한 건가? 호드가 이런 행위에서 얻은 것이 무엇인가? 가로쉬는 멍청이에다 배신자일세. 오래전 놈이 우리 아버지를 배신했을 때 죽여 버렸어야 했어.', `MaleText_loc4`='这有什么意义呢？部落到底能从中得到什么？加尔鲁什是个蠢货，叛徒。我早就该杀了他，就在他背叛我父亲时。', `MaleText_loc5`='那是為什麼?部落能從這些行動中得到什麼?卡爾洛斯不但是個蠢蛋，還是個叛徒。早在他背叛我父親的時候，我就該把他宰了。', `MaleText_loc7`='¿Y todo para qué? ¿Qué ha ganado la Horda con estos actos? Garrosh es un necio y un traidor. Debería haberlo matado hace mucho, cuando traicionó a mi padre.' WHERE `ID`=74836;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='곧 기회가 올 걸세, 친구. 하지만 우선은 오그리마를 빼앗아야지.', `MaleText_loc4`='你会有机会的，伙计。但首先我们得攻破这座城。', `MaleText_loc5`='你會有機會的，老兄。但是我們必須先把城給攻下來。', `MaleText_loc7`='Tendrás tu oportunidad, colega. Pero antes hay que tomar la ciudad.' WHERE `ID`=74837;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='인간들과는 이야기를 해 보았나?', `MaleText_loc4`='你跟人类沟通过了吗？', `MaleText_loc5`='你有跟人類溝通過嗎?', `MaleText_loc7`='¿Has sabido algo de los humanos?' WHERE `ID`=74838;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='얼라이언스와 호드 모두 함대를 끌고 항구로 오고 있다네. 병력을 나눠서 정문을 공격해야 하네.', `MaleText_loc4`='联盟和部落都已经向港口派出了舰队。我们得分出一些部队来进攻前门。', `MaleText_loc5`='聯盟和部落都派船到港口了。我們要分散他們的兵力，攻打前門。', `MaleText_loc7`='Hay naves de la Alianza y de la Horda de camino al puerto. Nos dividiremos y asaltaremos las puertas frontales.' WHERE `ID`=74839;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대담한 계획이로군. 놀랄 일이 없기만을 바라세.', `MaleText_loc4`='这计划很大胆。但愿我们不会遇到什么意外。', `MaleText_loc5`='大膽的計劃，但願我們不會遇到什麼始料未及的事。', `MaleText_loc7`='Es un plan audaz. Esperemos que no haya ninguna sorpresa.' WHERE `ID`=74840;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='있어도 별 도리가 없다네, 친구.', `MaleText_loc4`='恐怕我们别无选择，伙计。', `MaleText_loc5`='我不認為我們有選擇的餘地，老兄。', `MaleText_loc7`='Creo que no tenemos elección, colega.' WHERE `ID`=74841;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우린 가로쉬를 꺾고 호드를 일으킬 겁니다!', `MaleText_loc4`='我们要击败加尔鲁什，重建部落！', `MaleText_loc5`='我們會擊敗卡爾洛斯，重振部落!', `MaleText_loc7`='¡Derrotaremos a Garrosh y restauraremos la Horda!', `FemaleText_loc1`='우린 가로쉬를 꺾고 호드를 일으킬 거예요!', `FemaleText_loc4`='我们要击败加尔鲁什，重建部落！', `FemaleText_loc5`='我們會擊敗卡爾洛斯，重振部落!', `FemaleText_loc7`='¡Derrotaremos a Garrosh y restauraremos la Horda!' WHERE `ID`=74844;
