UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='우리는 오그리마의 타락을 뿌리 뽑을 것이다.', `FemaleText_loc4`='我们要根除奥格瑞玛的一切腐败。', `FemaleText_loc5`='我們會把奧格瑪的腐化全都清除掉。', `FemaleText_loc7`='Purgaremos toda la corrupción de Orgrimmar.' WHERE `ID`=74876;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='너희 족속이 풍기는 악취는 어마어마하군. 너는 악마와 교류하는 모든 자들과 함께 대가를 치를 것이다.', `FemaleText_loc4`='你们这些家伙身上的恶臭真让人作呕。你将和其他勾结恶魔的家伙一起付出代价。', `FemaleText_loc5`='你們這些傢伙散發的臭味真令人難以忍受。你會跟其他與惡魔交易的傢伙一樣付出代價。', `FemaleText_loc7`='La peste de tu especie es insoportable. Te castigaremos igual que a todos los amigos de los demonios.' WHERE `ID`=74877;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='코르크론을 준비시키는 것이 내 일이요.', `MaleText_loc4`='只有我才能把这些库卡隆变成合格的战士。', `MaleText_loc5`='柯爾克隆們就緒了沒，是我說了算。', `MaleText_loc7`='Mi trabajo es asegurarme de que los Kor''kron están listos.', `FemaleText_loc1`='코르크론을 준비시키는 것이 내 일이에요.', `FemaleText_loc4`='只有我才能把这些库卡隆变成合格的战士。', `FemaleText_loc5`='柯爾克隆們就緒了沒，是我說了算。', `FemaleText_loc7`='Mi trabajo es asegurarme de que los Kor''kron están listos.' WHERE `ID`=74878;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='전투가 시작되면 내가 닦달했던 걸 고마워할 거요.', `MaleText_loc4`='等战斗打响时，他们就会感激我的严格训练了。', `MaleText_loc5`='等戰鬥開始，他們會謝謝我這麼嚴厲地訓練他們的。', `MaleText_loc7`='Cuando la batalla comience, me agradecerán haber sido tan duro con ellos.', `FemaleText_loc1`='전투가 시작되면 내가 닦달했던 걸 고마워할걸요.', `FemaleText_loc4`='等战斗打响时，他们就会感激我的严格训练了。', `FemaleText_loc5`='等戰鬥開始，他們會謝謝我這麼嚴厲地訓練他們的。', `FemaleText_loc7`='Cuando la batalla comience, me agradecerán haber sido tan duro con ellos.' WHERE `ID`=74879;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='당신 계획을 알고 있소. 당신이 공격할 때면 코르크론도 준비가 돼 있을 거요.', `MaleText_loc4`='我知道你在想什么，等你进攻时，这些库卡隆会做好准备的。', `MaleText_loc5`='我知道你在計劃什麼，你展開攻擊的時候，這些柯爾克隆也準備好了。', `MaleText_loc7`='Sé lo que estás planeando. Los Kor''kron estarán listos cuando ataques.', `FemaleText_loc1`='당신 계획을 알아요. 당신이 공격할 때면 코르크론도 준비가 돼 있을 거예요.', `FemaleText_loc4`='我知道你在想什么，等你进攻时，这些库卡隆会做好准备的。', `FemaleText_loc5`='我知道你在計劃什麼，你展開攻擊的時候，這些柯爾克隆也準備好了。', `FemaleText_loc7`='Sé lo que estás planeando. Los Kor''kron estarán listos cuando ataques.' WHERE `ID`=74880;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='막강한 코르크론과 싸울 생각이라면 다시 생각하시오.', `MaleText_loc4`='在面对库卡隆的力量时，你最好三思而后行。', `MaleText_loc5`='在跟強大的柯爾克隆作對之前最好先想清楚。', `MaleText_loc7`='Piénsatelo bien antes de desatar la ira de los Kor''kron.', `FemaleText_loc1`='막강한 코르크론과 싸울 생각이라면 다시 생각하세요.', `FemaleText_loc4`='在面对库卡隆的力量时，你最好三思而后行。', `FemaleText_loc5`='在跟強大的柯爾克隆作對之前最好先想清楚。', `FemaleText_loc7`='Piénsatelo bien antes de desatar la ira de los Kor''kron.' WHERE `ID`=74881;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋았어! 한 번 더!', `MaleText_loc4`='很好！再来！', `MaleText_loc5`='很好!再來!', `MaleText_loc7`='¡Bien! ¡Otra vez!', `FemaleText_loc1`='좋았어! 한 번 더!', `FemaleText_loc4`='很好！再来！', `FemaleText_loc5`='很好!再來!', `FemaleText_loc7`='¡Bien! ¡Otra vez!' WHERE `ID`=74884;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님께서는 실패를 용서치 않으실 것이다. 한 번 더!', `MaleText_loc4`='加尔鲁什绝不容许失败。再来！', `MaleText_loc5`='卡爾洛斯絕不容許失敗，再來!', `MaleText_loc7`='Garrosh no tolera el fracaso. ¡OTRA VEZ!', `FemaleText_loc1`='가로쉬 님께서는 실패를 용서치 않으실 것이다. 한 번 더!', `FemaleText_loc4`='加尔鲁什绝不容许失败。再来！', `FemaleText_loc5`='卡爾洛斯絕不容許失敗，再來!', `FemaleText_loc7`='Garrosh no tolera el fracaso. ¡OTRA VEZ!' WHERE `ID`=74885;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가로쉬 님께서 너희가 축적한 부를 내놓으라 하신다. 당장 금고를 열어라!', `MaleText_loc4`='加尔鲁什需要你们积累的财富。让我进入金库！', `MaleText_loc5`='卡爾洛斯要你交出你的積蓄。把進入寶庫的方法交出來!', `MaleText_loc7`='Garrosh exige la fortuna que haz acumulado. ¡Dame acceso a la cámara!' WHERE `ID`=74886;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뼈가 부러져도 그렇게 반항할 수 있는지 보자.', `MaleText_loc4`='让我们看看，你被打断骨头之后还能不能这么目中无人。', `MaleText_loc5`='我們倒要看看等我們開始碾碎你的骨頭時，你是不是還這麼嘴硬。', `MaleText_loc7`='Ya veremos si sigues pensando lo mismo cuando empecemos a romperte huesos.' WHERE `ID`=74887;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아... 안 돼! 싫어!', `MaleText_loc4`='我……我不能！不行！', `MaleText_loc5`='我...我不要!我絕對不要!', `MaleText_loc7`='No... ¡no puedo! ¡Me niego!' WHERE `ID`=74888;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='가로쉬 님께서는 오그리마의 벽 안에서 악마 숭배가 이루어지는 걸 허용하지 않으실 것이다. 항복하지 않으면 죽이겠다.', `FemaleText_loc4`='加尔鲁什绝不容许在奥格瑞玛的城墙之内进行恶魔崇拜。你们必须立刻投降并接受羁押，否则就得死。', `FemaleText_loc5`='卡爾洛斯不會忍受奧格瑪的城牆內有惡魔崇拜的行為。你們最好臣服並接受拘留，不然就會被殺死。', `FemaleText_loc7`='Garrosh no tolera la adoración de demonios en los confines de Orgrimmar. Ríndete y deja que te arrestemos, o prepárate para morir.' WHERE `ID`=74889;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구, 우릴 도와주게! 열쇠를 찾아봐!', `MaleText_loc4`='嘿，伙计，救救我们！快去找钥匙！', `MaleText_loc5`='嘿老兄，幫幫忙!找出鑰匙!', `MaleText_loc7`='¡Ey, amigo, ayúdanos!  ¡Busca la llave!' WHERE `ID`=74890;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='고맙네! 이 은혜는 꼭 갚겠네.', `MaleText_loc4`='谢了，伙计，我们会记住你的。', `MaleText_loc5`='謝了老兄，我們不會忘記你的。', `MaleText_loc7`='Gracias, amigo, no olvidaremos esto.' WHERE `ID`=74891;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='도요다가 당신을 돕기 위해 저항 토템을 소환합니다!', `MaleText_loc4`='多尤达放置了一个抗性图腾来协助你！', `MaleText_loc5`='多尤達施放抗性圖騰來幫助你!', `MaleText_loc7`='¡Doyo''da coloca un tótem de resistencia para ayudarlos!' WHERE `ID`=74892;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='여기 저희 좀 꺼내주십시오! 열쇠가 근처에 있을 겁니다!', `MaleText_loc4`='在这儿！放我们出去！钥匙就在这附近！', `MaleText_loc5`='這裡!幫幫我們!鑰匙就在這附近!', `MaleText_loc7`='¡Aquí!  ¡Por favor, sácanos de aquí!  ¡La llave tiene que estar por ahí!' WHERE `ID`=74893;
