UPDATE `locales_broadcast_text` SET `MaleText_loc1`='뭔가 할 말이 있나, 판다렌?', `MaleText_loc4`='你还有什么要说的吗，熊猫人？', `MaleText_loc5`='還有什麼想說的嗎，熊貓人?', `MaleText_loc7`='¿Algo para decir en tu defensa, pandaren?' WHERE `ID`=74921;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 촛불이 보이나? 이게 다 타기 전까지 판다렌 유물에 대해 실토해라. 안 그러면 네놈은 죽은 목숨이다.', `MaleText_loc4`='看到这根蜡烛了吗？你最好在它烧完之前，说出熊猫人神器的秘密！快点说出来！', `MaleText_loc5`='看到這根蠟燭了嗎?在它燒完之前告訴我們熊貓人神器的秘密!快說!', `MaleText_loc7`='¿Ves esta vela encendida? ¡Tienes hasta que se consuma para contarnos todo sobre los artefactos Pandaren!  ¡Habla!' WHERE `ID`=74922;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='좋다. 말을 하지 않겠다면, 그 머리는 이제 필요가 없겠군.', `MaleText_loc4`='很好，你要是不说，那留着你的脑袋也没用了。', `MaleText_loc5`='很好，你不想說，留著你的腦袋就沒用了。', `MaleText_loc7`='Muy bien, si no vas a hablar, ya no necesitarás tu cabeza.' WHERE `ID`=74923;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지를 찾아야 해요! 여기 어디 있을 거예요.', `FemaleText_loc4`='季肯定在这附近，我要找到他！', `FemaleText_loc5`='紀一定在這附近，我得找到他!', `FemaleText_loc7`='Ji tiene que estar por aquí, ¡tengo que encontrarlo!' WHERE `ID`=74924;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='이런! 놈들이 지를 처형하려고 해요!', `FemaleText_loc4`='噢，不，季！他们要砍掉他的头！', `FemaleText_loc5`='噢不，紀!他們要處決他!', `FemaleText_loc7`='¡Oh, no! ¡Ji! ¡Lo van a ejecutar!' WHERE `ID`=74925;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='놈들이 지를 반쯤 죽여놨어요! 제가 수를 써야 하는데!', `FemaleText_loc4`='他被他们打晕了！我得赶快做点什么！', `FemaleText_loc5`='他們把他打到不省人事了!我必須做點什麼!', `FemaleText_loc7`='¡Casi lo dejan inconsciente de tantos golpes!  ¡Tengo que hacer algo!' WHERE `ID`=74926;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지! 안 돼! 죽여버리겠어!', `FemaleText_loc4`='季！不！我要杀了你们！', `FemaleText_loc5`='紀!不!我要殺了你們!', `FemaleText_loc7`='¡Ji! ¡No!  ¡Te mataré!' WHERE `ID`=74927;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지... 미안해요...', `FemaleText_loc4`='季……对不起……', `FemaleText_loc5`='紀...對不起...', `FemaleText_loc7`='Ji... Lo siento...' WHERE `ID`=74928;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='정말 미안해요. 이제 우린 함께에요. 그러니까, 같이 거북이로 돌아가요. 제발 죽지 말아요.', `FemaleText_loc4`='季，真是对不起，现在我们可以在一起了，我们回迷踪岛吧，你不要死。', `FemaleText_loc5`='紀，對不起，我們現在可以在一起了，讓我們一起回去神真子那裡，拜託不要死。', `FemaleText_loc7`='Ji, lo siento tanto, ahora podemos estar juntos, por favor, volvamos a la tortuga, no te mueras, por favor.' WHERE `ID`=74929;
UPDATE `locales_broadcast_text` SET `FemaleText_loc1`='지는 제가 데리고 나갈게요.', `FemaleText_loc4`='我要带他离开这里。', `FemaleText_loc5`='我要把他救出去。', `FemaleText_loc7`='Lo sacaré de aquí.' WHERE `ID`=74930;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으윽... 고맙소...', `MaleText_loc4`='呼……谢谢你……', `MaleText_loc5`='嗯...謝謝你...', `MaleText_loc7`='Nnnnff... Gra... Gracias.' WHERE `ID`=74937;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 비록 멍들고 다쳤지만, 속에선 아직도 증오가 끓어오르오.', `MaleText_loc4`='我的身躯已满是伤痕，可我的心中翻滚着仇恨。', `MaleText_loc5`='我也許傷痕累累，但仇恨在我心中熊熊燃燒。', `MaleText_loc7`='Estaré lastimado y vencido pero el odio hierve en mi interior.' WHERE `ID`=74938;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='난 오크의 손에 수없이 쓰러졌소. 그리고 그만큼 다시 일어서야 했지.', `MaleText_loc4`='我一次又一次倒在兽人手下，一次又一次地站了起来。', `MaleText_loc5`='我多次在獸人手中倒下，但我一次次地爬了起來。', `MaleText_loc7`='He caído muchas veces a manos de un Orco y muchas veces he vuelto a levantarme.' WHERE `ID`=74939;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하지만 더는 아니오.', `MaleText_loc4`='以后再也不会了。', `MaleText_loc5`='但我不會再忍了。', `MaleText_loc7`='Pero nunca más.' WHERE `ID`=74940;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='날 공격했던 오크놈 하나 당, 천 명의 머리통을 쪼개버릴테니!', `MaleText_loc4`='每一个欺负过我的兽人，我都要让他们加倍地偿还！', `MaleText_loc5`='只要一個獸人敢再打我，我會劈開一千個獸人的頭顱!', `MaleText_loc7`='Por cada orco que me golpeó, ¡le abriré la cabeza a mil de ellos!' WHERE `ID`=74941;
