UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나, 가몬이 모두를 구할 거요!', `MaleText_loc4`='我，加摩尔，会拯救大家！', `MaleText_loc5`='我，加摩爾，會保護大家的!', `MaleText_loc7`='¡Yo, Gamon, nos salvaré!' WHERE `ID`=74943;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 도끼를 받아라!', `MaleText_loc4`='尝尝我的斧头吧！', `MaleText_loc5`='嚐嚐我的斧頭!', `MaleText_loc7`='¡Prueben mi hacha!' WHERE `ID`=74944;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='죗값을 치러라!', `MaleText_loc4`='付出代价吧！', `MaleText_loc5`='為你的罪行付出代價!', `MaleText_loc7`='¡Paguen por sus crímenes!' WHERE `ID`=74945;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 고통의 폭풍이다!', `MaleText_loc4`='我是痛苦的风暴！', `MaleText_loc5`='我是苦痛的風暴!', `MaleText_loc7`='¡Soy una tormenta de dolor!' WHERE `ID`=74946;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영원꽃 골짜기에서 끔찍한 일들이 있어났소. 하지만 우리에게 가장 큰 비극은 이제 그곳이 낚시하기에도 좋지 않은 곳이 되어버렸단 사실이지. 그 많던 보석 열대어가! 모두 사라졌소!$b $b하지만 운 좋게도, 동부 해안 너머에는 아직도 보석 열대어가 낚이는 섬이 하나 있다더군. 소문이 사실이라면 그 섬으로 가면 보석 열대어가 가득한 호수를 찾을 수 있을 거요.', `MaleText_loc4`='锦绣谷发生了一些可怕的事，但真正的悲剧在于，那里已经完全不适合钓鱼了。所有的珍宝斑马鱼！都完了！$b $b但你很走运，我听说东部海岸附近的一座岛上还能钓到珍宝斑马鱼。如果传言属实的话，你可以在那儿找到满满一湖的鱼。', `MaleText_loc5`='恒春谷曾發生過可怕的事，但最慘的莫過於這裡再也不是釣魚的好去處了。 珠寶斑馬魚啊，都沒了!$b $b你算走運的，我聽說東海岸遠處有個小島，你還能在那裡釣到珠寶斑馬魚。如果傳言屬實，你應該能找到那個滿是珠寶斑馬魚的湖。', `MaleText_loc7`='Han pasado cosas terribles en el Valle de la Flor Eterna, pero la verdadera tragedia es que ya no se puede pescar allí. Todos esos danios enjoyados... ¡desaparecidos!$b$bAfortunadamente para ti, he oído hablar de una isla al este donde aún se pueden pescar danios enjoyados. Si los rumores son ciertos, allí encontrarás un lago lleno de ellos.' WHERE `ID`=74949;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소문이 사실이라면 여기서 보석 열대어를 찾을 수 있을 거요.$b$b<벤이 지도에서 한 곳을 표시합니다.>$b$b', `MaleText_loc4`='如果传言属实的话，你应该可以在这里找到珍宝斑马鱼。$b$b<班宏在你的地图上做了一个标记。>$b$b', `MaleText_loc5`='如果傳言屬實，你應該可以在這裡找到珠寶斑馬魚。$b$b<班在你的地圖上做了標記。>$b$b', `MaleText_loc7`='Si los rumores son ciertos, encontrarás danios enjoyados aquí.$b$b<Ben marca un punto en tu mapa.>' WHERE `ID`=74950;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='가지가지 판다렌 그림 문자로 뒤덮인 오래된 두루마리입니다. 하지만 내용을 더 읽으려면 사원 내에서 샤의 기운을 정화해야 할 것 같습니다.', `MaleText_loc4`='一个写满了熊猫人象形文字的古老卷轴。你怀疑只有在净化了寺院中煞能腐蚀之后，才能继续研究里面的内容。', `MaleText_loc5`='一個寫著各種熊貓人象形文字的古老卷軸。你懷疑只有把寺廟裡的煞之腐敗全數淨化，才能看到更進一步的內容。', `MaleText_loc7`='Un antiguo pergamino cubierto de pictogramas pandaren. Sospechas que no podrás seguir leyendo el contenido hasta que se haya purificado la corrupción sha del templo.' WHERE `ID`=74953;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='두루마리를 읽습니다.', `MaleText_loc4`='阅读卷轴。', `MaleText_loc5`='閱讀卷軸。', `MaleText_loc7`='Lee el pergamino.', `FemaleText_loc1`='두루마리를 읽습니다.', `FemaleText_loc4`='阅读卷轴。', `FemaleText_loc5`='閱讀卷軸。', `FemaleText_loc7`='Lee el pergamino.' WHERE `ID`=74954;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='분노가 힘이다!', `MaleText_loc4`='怒火就是力量！', `MaleText_loc5`='憤怒就是力量!', `MaleText_loc7`='¡La ira es poder!' WHERE `ID`=74956;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너흰 심판을 받아들이고 스스로 가치를 증명해 보였다. 하지만 주의하라, 이 앞에 도사린 것이 너희 영혼을 극한까지 몰아붙일 테니까. 준비가 끝나면 방에 들어가도 좋다.', `MaleText_loc4`='你们接受了审判，证明了自己的价值。但要小心，接下来，你们的灵魂将受到极限的考验。准备好之后，你们就能进入大厅了。', `MaleText_loc5`='你們接受了審判並證明了價值。我警告你們，你們的靈魂將會在接下來受到最大的考驗。等準備好，你們就進入大廳吧。', `MaleText_loc7`='Ustedes han sido juzgados y probaron que eran merecedores. Pero tengan cuidado: lo que les espera pondrá a prueba sus almas como nunca.  Cuando estén totalmente preparados, pueden entrar a la cámara.' WHERE `ID`=74958;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락이 증폭되고 있다. 그 힘이 너무 강해지기 전에 조각들을 모두 정화해야 한다.', `MaleText_loc4`='腐蚀正在扩大。在它变得不可收拾之前，必须净化这些碎片。', `MaleText_loc5`='腐化正在蔓延。必須在不可收拾之前淨化碎片。', `MaleText_loc7`='La corrupción se amplifica.  Hay que purificar los fragmentos antes de que la corrupción sea demasiada.' WHERE `ID`=74962;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='소용이 없었군. 온다. 마음을 굳게 먹고 너희 영혼을 다잡아라.', `MaleText_loc4`='没有关系，它来了。坚定你们的心智，做好准备。', `MaleText_loc5`='無所謂，它來了。讓你們的靈魂和心靈做好準備吧。', `MaleText_loc7`='No importó. Está en camino.  Fortifiquen sus corazones y preparen sus almas.' WHERE `ID`=74963;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저것을... 억제해야... 한다...', `MaleText_loc4`='你们……必须……阻止……它……', `MaleText_loc5`='你們...必須...阻止...它...', `MaleText_loc7`='Tienen... que... contenerlo...' WHERE `ID`=74964;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='겸손해질지어다!', `MaleText_loc4`='保持谦卑。', `MaleText_loc5`='要謙卑。', `MaleText_loc7`='Sean humildes.' WHERE `ID`=74965;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오만을 떨쳐 버려라.', `MaleText_loc4`='远离傲慢。', `MaleText_loc5`='遠離傲慢。', `MaleText_loc7`='Líbrense de la arrogancia.' WHERE `ID`=74966;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 또 한 번 함께 모험을 하겠군. 안타까운 일이네만, 이번엔 상황이 무척이나 심각한 모양이네.', `MaleText_loc4`='啊，我们又要一起冒险了，但是，这次的局势恐怕会更加危险。', `MaleText_loc5`='啊，我們又一起冒險了，只是這次的情況恐怕是相當的危險啊。', `MaleText_loc7`='Ah, juntos otra vez hacia la aventura, solo que esta vez me temo que las circunstancias son mucho más funestas.' WHERE `ID`=74968;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='오, 영원꽃 골짜기가 어떻게 된 걸까?', `MaleText_loc4`='噢，锦绣谷怎么成这样了？', `MaleText_loc5`='噢，恆春谷怎麼會變成這樣呢?', `MaleText_loc7`='Oh, ¿qué pasó con el Valle?' WHERE `ID`=74969;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='대지는 잿빛으로 물들고, 사시사철 무성하던 초목도 시들었네. 이제 호수의 물도 모두 말라 버렸어.', `MaleText_loc4`='这片土地遭受了重创，水流干涸，盛开的鲜花、葱郁的草木纷纷枯萎凋零。', `MaleText_loc5`='大地傷痕滿佈，泉水乾涸枯竭，永遠盛開的花草樹木也都隨之死去。', `MaleText_loc7`='La tierra muestra grietas, los árboles y plantas perennes se marchitan y mueren a medida que el agua de los estanques se drena.' WHERE `ID`=74970;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이리 오게. 가로쉬가 이 땅에서 어떤 끔찍한 짓을 했는지 함께 보세.', `MaleText_loc4`='来，让我们看看，加尔鲁什还引来了哪些噩梦。', `MaleText_loc5`='來，讓我們看看卡爾洛斯在我們土地上還做了什麼恐怖的事情。', `MaleText_loc7`='Vamos a ver qué otros horrores ha desatado Garrosh sobre nuestra tierra.' WHERE `ID`=74971;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한때, 티탄은 생명을 주는 이 물로 판다리아의 모든 생명체를 만들고 다듬었어.', `MaleText_loc4`='泰坦们曾用这些生命之水创造了潘达利亚所有的物种。', `MaleText_loc5`='泰坦曾經用這些賦予生命的水來創造及塑造潘達利亞上的所有生命。', `MaleText_loc7`='En un entonces, los Titanes usaron estas aguas de vida para crear y dar forma a toda la vida en Pandaria.' WHERE `ID`=74972;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 골짜기에 꽃을 피운 건 바로 이 물이네. 물은 네 바람의 계곡으로 흘러들어, 이 세계에서 가장 풍요로운 땅을 만들었지.', `MaleText_loc4`='是它们令锦绣谷四季长春，又在流入四风谷后形成了全世界最肥沃的农田！', `MaleText_loc5`='是這些水讓恆春谷能百花盛開。流入四風峽的水創造出全世界最肥沃的農田!', `MaleText_loc7`='Son estas aguas las que mantuvieron el Valle en plena flor. ¡Su flujo hacia el Valle de los Cuatro Vientos creó la tierra de cultivo más fértil del mundo!' WHERE `ID`=74973;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='허나 지금 이 순간, 고대 신의 끔찍한 종양이 이 물 속에 번지고 있네.', `MaleText_loc4`='而现在，邪恶的上古之神寄生在这些水中。', `MaleText_loc5`='現在，上古之神的惡毒在這些水中成形了。', `MaleText_loc7`='Y ahora, la malicia del dios antiguo se ha manifestado en las aguas.' WHERE `ID`=74974;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이토록 끔찍하고 또 끔찍한 존재라니. 파괴하게. 대지로 스며 들어가 판다리아 전체를 타락시키기 전에!', `MaleText_loc4`='这污秽的东西——消灭它，别让它渗入泥土，污染整个潘达利亚。', `MaleText_loc5`='如此邪惡的東西 - 摧毀它，別讓它深入污染土壤並腐化整個潘達利亞!', `MaleText_loc7`='Qué cosa tan terrible... ¡Destrúyela antes de que se filtre hasta lo profundo del suelo y corrompa a toda Pandaria!' WHERE `ID`=74975;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 역시 해냈군! 골짜기의 물이 다시 깨끗해졌네.', `MaleText_loc4`='啊，你成功了！水流恢复了洁净。', `MaleText_loc5`='啊，你成功了!水又再次純淨了。', `MaleText_loc7`='Ah, ¡lo lograste!  Las aguas son puras otra vez.' WHERE `ID`=74976;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='생명을 주는 힘이 자네를 통해 흐르는게 느껴지는가?', `MaleText_loc4`='感受到它们所蕴含的生命活力了吗？', `MaleText_loc5`='你能感受到他們賦予生命的能量流過身體嗎?', `MaleText_loc7`='¿Puedes sentir las energías de vida atravesándote?' WHERE `ID`=74977;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='골짜기가 회복되려면 오랜 시간이 필요하겠지만, 자네가 희망을 주었네!', `MaleText_loc4`='锦绣谷还要很久才能复原，但是你给了我们希望！', `MaleText_loc5`='恆春谷需要很長的時間復原，但你給了我們希望!', `MaleText_loc7`='Tomará mucho tiempo para que el Valle sane, ¡pero nos has dado esperanzas!' WHERE `ID`=74978;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='저건 혹시...? 아, 아니, 안 돼, 안 돼...', `MaleText_loc4`='这不是……？噢，不不不。', `MaleText_loc5`='難道這就是...?噢不不不不。', `MaleText_loc7`='¿Será posible…?  Ay, no, no, no, no, no.' WHERE `ID`=74979;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='황금 연꽃은... 이 땅을 지키기 위해 그 목숨을 바쳤는데...', `MaleText_loc4`='金莲教……他们曾经誓死保卫这片土地。', `MaleText_loc5`='金蓮會...可是...他們誓言以生命守護這裡。', `MaleText_loc7`='El Loto Dorado... Juraron defender este lugar con sus vidas.' WHERE `ID`=74980;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 루크 스톤토! 날 기억하는군! 자네... 어떻게 된 건가?', `MaleText_loc4`='没错！鲁克·石趾！你还记得我！你怎么了？', `MaleText_loc5`='對!茹克·石趾!你記得我!你發生了什麼事?', `MaleText_loc7`='¡Sí!  ¡Rook Mano Dura!  ¿Me recuerdas?  ¿Qué te ha sucedido?' WHERE `ID`=74981;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이제 알았네. 샤가 그들의 영혼을 여기 가두고, 영원히 실패를 되새기게 하는 모양이야. 저들의 절망으로 배를 채우려는 거지.', `MaleText_loc4`='我明白了。煞魔禁锢了他们的灵魂，汲取由他们的失败而产生的绝望。', `MaleText_loc5`='我懂了。這股煞能禁錮了他們的靈魂，不斷重複經歷他們的失敗。它吸食他們的絕望。', `MaleText_loc7`='Ya veo. Esta energía sha atrapó a los espíritus aquí para que revivan eternamente su fracaso. Se alimenta de su desesperación.' WHERE `ID`=74982;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이건 죽음보다 끔찍한 운명이로군. 영웅들이여! 부디 저들의 영혼을 풀어 주게!', `MaleText_loc4`='这比死亡更可怕——英雄们，请解救他们的灵魂！', `MaleText_loc5`='這是比死亡更慘的命運 - 拜託了，英雄們!釋放他們的靈魂!', `MaleText_loc7`='Esto es un destino peor que la muerte... ¡Por favor, héroes!  ¡Liberen sus almas!' WHERE `ID`=74984;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안식을 찾게, 친구들.', `MaleText_loc4`='安息吧，我的朋友们。', `MaleText_loc5`='安息吧，親愛的朋友們。', `MaleText_loc7`='Descansen en paz, mis queridos amigos.' WHERE `ID`=74985;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자네들의 영혼이, 그 소중한 목숨을 바쳐 지켜낸 이 땅과 하나가 되길...', `MaleText_loc4`='愿你们的灵魂融入这片你们誓死守卫的土地。', `MaleText_loc5`='希望你們的靈魂能與獻出生命保護的大地合而為一。', `MaleText_loc7`='Que sus almas se vuelvan una con la tierra que protegieron con sus vidas.' WHERE `ID`=74986;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놀랍군! 이 방도 그 "티탄"이라는 존재들이 만든 것 같아!', `MaleText_loc4`='太惊人了！又一座由这些“泰坦”建造的殿堂。', `MaleText_loc5`='太驚人了!看來又是一間這些「泰坦」建造的殿堂!', `MaleText_loc7`='¡Qué asombroso! Otra cámara que parece haberse originado de estos "Titanes".' WHERE `ID`=74987;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='역사가 기록되기 전부터 감춰져 있었던 모양이네. 그럴 만도 하지!', `MaleText_loc4`='它早在有史可考之前就被隐藏了起来。这一定是有原因的！', `MaleText_loc5`='一定是史前時代就隱藏在這裡。而且有著很好的理由!', `MaleText_loc7`='Debe de haber estado escondida desde mucho antes de la prehistoria. ¡Y por una buena razón!' WHERE `ID`=74988;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이 앞의 방에는, 우리 평화로운 대지 아래에서 잠자는, 고대 신의 심장이 있네!', `MaleText_loc4`='在前面的大厅里，在我们祥和的土地下，沉睡着古神之心。', `MaleText_loc5`='在前面的廳堂中，我們平靜的大地下，上古之神的心臟沉睡著。', `MaleText_loc7`='En la siguiente cámara, bajo nuestra tierra pacífica, duerme el corazón de un dios antiguo.' WHERE `ID`=74989;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='이런! 이건 뭐지? 반갑네! 난 전승지기 초라고 하네!', `MaleText_loc4`='噢！什么？你好！我是游学者周卓！', `MaleText_loc5`='天啊，這是什麼?你好，我是博學行者阿洲!', `MaleText_loc7`='¡Cielos! ¿Qué es esto? ¡Hola! ¡Soy el Eremita Cho!' WHERE `ID`=74990;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락의 존재라니? 아니, 우리는 타락을 멈추고 판다리아를 구하러 왔네!', `MaleText_loc4`='深度腐蚀者？不，我们是来阻止腐蚀，拯救潘达利亚的！', `MaleText_loc5`='更多腐化?不，我們是來阻止腐化，拯救潘達利亞的!', `MaleText_loc7`='¿Corrupción?  ¡No! Estamos aquí para detener la corrupción y salvar a Pandaria.' WHERE `ID`=74991;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래! 우릴 보내 주게!', `MaleText_loc4`='是的！请让我们过去！', `MaleText_loc5`='是的!請讓我們通過!', `MaleText_loc7`='¡Sí! ¡Déjanos pasar, por favor!' WHERE `ID`=74992;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타란 주!', `MaleText_loc4`='祝踏岚！', `MaleText_loc5`='塔蘭·祝!', `MaleText_loc7`='¡Taran Zhu!' WHERE `ID`=74993;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 아니, 아무 말도 하지 말게. 내가 치유사들에게 데려다 주겠네.', `MaleText_loc4`='别说话，朋友，我马上送你去找大夫。', `MaleText_loc5`='好了好了，別說話了，朋友，我帶你去找治療師。', `MaleText_loc7`='No hables, amigo, te llevaré con los sanadores.' WHERE `ID`=74994;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내가 도움을 요청하겠네! 어떻게든 샤를 막아내 보게!', `MaleText_loc4`='我这就去找援军！你要坚持挡住煞魔！', `MaleText_loc5`='我會尋求幫助!盡可能地把煞纏住!', `MaleText_loc7`='¡Buscaré ayuda! ¡Intenta contener al Sha todo el tiempo que puedas!' WHERE `ID`=74995;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅들이여! 살아 있군. 도와줄 이를 데려왔네.', `MaleText_loc4`='英雄们，你们还好吗？援军来了。', `MaleText_loc5`='英雄們!你們還活著。我帶援軍來了。', `MaleText_loc7`='¡Valientes! Siguen con vida. Les traje ayuda.' WHERE `ID`=74996;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='<콜록 콜록> 으으으으...', `MaleText_loc4`='不……', `MaleText_loc5`='*咳嗽*呃...', `MaleText_loc7`='*Cof cof* Nyyyunnngggg...' WHERE `ID`=74997;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='초 님... 외부인들이... 한 짓입니다... 그들을 받아들이지 말았어야...', `MaleText_loc4`='周卓……外来者……这都怪他们……真不该让他们进来……', `MaleText_loc5`='阿洲...外來者...是他們害的...我們不該讓他們進來...', `MaleText_loc7`='Cho... los forasteros... ELLOS hicieron esto... Nunca debimos dejarlos entrar...' WHERE `ID`=74998;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네 뼈를 먹이로 주지!', `MaleText_loc4`='不！我要拿你们的骨头去喂她的小崽子！！！', `MaleText_loc5`='不!我會拿你的骨頭去餵她的幼崽!', `MaleText_loc7`='¡NO! ¡¡Alimentaré a sus cachorros con sus huesos!!' WHERE `ID`=75022;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='%s|1이;가; |cFFFF0404|Hspell:144485|h[진동 충격파]|h|r를 준비합니다!', `MaleText_loc4`='%s正准备发动|cFFFF0404|Hspell:144485|h[地震冲击]|h|r！', `MaleText_loc5`='%s準備施放|cFFFF0404|Hspell:144485|h[震波衝擊]|h|r!', `MaleText_loc7`='¡%s prepara un |cFFFF0404|Hspell:144485|h[Pulso de choque]|h|r!' WHERE `ID`=75023;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='시작합시다!', `MaleText_loc4`='我们动手吧！', `MaleText_loc5`='開始吧!', `MaleText_loc7`='¡Vamos allá!', `FemaleText_loc1`='시작합시다!', `FemaleText_loc4`='我们动手吧！', `FemaleText_loc5`='開始吧!', `FemaleText_loc7`='¡Vamos allá!' WHERE `ID`=75024;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='나는 오늘 천신에게 도전할 수 없게 되었지만, 앞으로의 네 경기를 기대하마. 행운을 빈다, $n.', `MaleText_loc4`='我今天没有机会挑战至尊天神，但我期待看到你的进步。祝你好运，$n。', `MaleText_loc5`='我現在還無法挑戰天尊，但我期待看到你的進步。祝你好運，$n。', `MaleText_loc7`='Hoy no puedo desafiar a los celestiales, pero será un placer seguir tu progreso. Buena suerte, $n.' WHERE `ID`=75025;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='멈춰라!', `MaleText_loc4`='站住！', `MaleText_loc5`='停步!', `MaleText_loc7`='¡Alto!' WHERE `ID`=75026;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='심장의 방에 타락의 존재가 들어갈 수는 없다!', `MaleText_loc4`='深度腐蚀者严禁进入中央大厅！', `MaleText_loc5`='不能再讓更多腐化侵入心臟的大廳!', `MaleText_loc7`='¡No entrará más corrupción a la cámara del corazón!' WHERE `ID`=75027;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='타락을 정화하고자 하는가?', `MaleText_loc4`='你们想要净化腐蚀？', `MaleText_loc5`='你們想要把腐化給淨化嗎?', `MaleText_loc7`='¿Desean purificar la corrupción?' WHERE `ID`=75028;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='지금 이 순간, 이대로 문을 지난다면, 너희는 실패할 것이다. 너희는 모두 자신도 모르게 교만이라는 질병에 오염되고 타락했다.', `MaleText_loc4`='如果就这样让你们进去，你们一定会失败的。你们，全都被名为“傲慢”的恶疾腐蚀了。', `MaleText_loc5`='如果你們在這個時間穿過這道門，你們會失敗。你們所有人都被陰險的「驕傲」給腐化了。', `MaleText_loc7`='Si atraviesan esta puerta en este momento, fallarán.  Todos ustedes están corrompidos por esa plaga pérfida conocida como Orgullo.' WHERE `ID`=75029;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너희 안의 악마를 마주할 준비가 되면 내게 다시 말해라.', `MaleText_loc4`='当你们准备好面对自己的心魔，再来跟我说话吧。', `MaleText_loc5`='等你們準備好面對內心的惡魔，再來跟我說話。', `MaleText_loc7`='Vuelvan a hablar conmigo cuando estén preparados para enfrentar a sus demonios internos.' WHERE `ID`=75030;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 좋다. 너희 타락을 가두어 둘 공간을 만들겠다.', `MaleText_loc4`='很好，我会制造一个空间来隔离你们的腐蚀。', `MaleText_loc5`='很好，我會創造一個力場隔離你們的腐化。', `MaleText_loc7`='Muy bien, crearé un campo que mantendrá su corrupción en cuarentena.' WHERE `ID`=75031;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내게 너희 가치를 증명한다면, 너희를 보내 주겠다.', `MaleText_loc4`='证明自己吧，那我才能让你们通过。', `MaleText_loc5`='證明你們的價值，我就讓你們過去。', `MaleText_loc7`='Prueben que son dignos y los dejaré pasar.' WHERE `ID`=75032;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s|1이;가; |cFFF00000|Hspell:142842|h[이샤라즈의 숨결]|h|r을 시전합니다!', `MaleText_loc4`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s开始施放|cFFF00000|Hspell:142842|h[亚煞极之息]|h|r！', `MaleText_loc5`='|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s開始施放|cFFF00000|Hspell:142842|h[亞煞拉懼之息]|h|r!', `MaleText_loc7`='|TInterfaceIconsspell_shadow_shadesofdarkness.blp:20|t¡%s empieza a lanzar |cFFF00000|Hspell:142842|h[Aliento de Y''Shaarj]|h|r!' WHERE `ID`=75033;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛이 너희를 씻어 주겠지만, 상냥하지는 않을 거다. 정화에 대비하라!', `MaleText_loc4`='光明净化一切，但它绝不温和。做好准备，接受净化吧！', `MaleText_loc5`='光明能淨化，但絕不溫和。準備好，接受淨化吧!', `MaleText_loc7`='La luz limpia pero no es delicada.  ¡Prepárense para ser purificados!' WHERE `ID`=75034;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내면을 들여다보고 그 안의 어둠을 씻어내라.', `MaleText_loc4`='看清你的内心，净化其中的黑暗。', `MaleText_loc5`='看清內心的黑暗並淨化它吧。', `MaleText_loc7`='Miren en su interior y limpien la oscuridad que habita adentro.' WHERE `ID`=75035;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내면의 악마를 마주하라!', `MaleText_loc4`='面对你们的心魔吧！', `MaleText_loc5`='面對內心的惡魔!', `MaleText_loc7`='¡Enfrenten a sus demonios internos!' WHERE `ID`=75036;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛 속에서 정화되어라!', `MaleText_loc4`='在光明中得到净化吧！', `MaleText_loc5`='讓光明淨化吧!', `MaleText_loc7`='¡Sean purificados por la luz!' WHERE `ID`=75037;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한심하군.', `MaleText_loc4`='不值一提。', `MaleText_loc5`='不值一提。', `MaleText_loc7`='No son dignos.' WHERE `ID`=75038;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='순수한 마음만 통과할 수 있다!', `MaleText_loc4`='只有纯洁的心灵才能通过！', `MaleText_loc5`='只有最純淨的心靈能通過!', `MaleText_loc7`='¡Solo aquellos de corazón puro pueden pasar!' WHERE `ID`=75039;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='빛은 네 더러움을 용납하지 않아!', `MaleText_loc4`='光明不会被你们玷污。', `MaleText_loc5`='光明不會被你們玷污。', `MaleText_loc7`='Ustedes no profanarán la luz.' WHERE `ID`=75040;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='', `MaleText_loc4`='', `MaleText_loc5`='', `MaleText_loc7`='' WHERE `ID`=75041;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='자! 내 용사가 도착했군!', `MaleText_loc4`='啊！我的勇士来了！', `MaleText_loc5`='來了!我的勇士到了!', `MaleText_loc7`='¡Aquí llega mi valiente!' WHERE `ID`=75045;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아, 그럼 그렇지! 비취 숲에서 만났던 친구로군!', `MaleText_loc4`='啊！我来自翡翠林的老朋友！', `MaleText_loc5`='啊，當然了!我在翠玉林的老朋友!', `MaleText_loc7`='¡Ah, por supuesto! ¡Mi viejo amigo del Bosque de Jade!' WHERE `ID`=75046;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='아니, 잠깐. 내가 제대로 적어 두는 게 좋겠네.', `MaleText_loc4`='等等，等等——我可不能把故事搞错了。', `MaleText_loc5`='等一下等一下。我得確保故事的正確性。', `MaleText_loc7`='Un momentito, un momentito... Déjame ver si entendí bien la historia.' WHERE `ID`=75047;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다렌들이 대대손손 늘어놓을 이야기니까!', `MaleText_loc4`='这个传奇将在熊猫人中代代相传！', `MaleText_loc5`='熊貓人會世代傳頌這段傳奇!', `MaleText_loc7`='¡Los Pandaren contarán esta historia por generaciones!' WHERE `ID`=75050;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='한 영웅이 있었다.', `MaleText_loc4`='它由一位英雄谱写。', `MaleText_loc5`='這得從一位英雄說起。', `MaleText_loc7`='Todo comienza con un valiente.' WHERE `ID`=75052;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='안개 너머에서 온 외지인이었지!', `MaleText_loc4`='一个来自迷雾之外的陌生人！', `MaleText_loc5`='一位迷霧彼端的外來者!', `MaleText_loc7`='¡Un extranjero, llegado de más allá de la niebla!' WHERE `ID`=75054;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='기이한 미지의 대륙을 정복하고!', `MaleText_loc4`='征服了陌生的新大陆！', `MaleText_loc5`='征服了一塊神秘的新天地!', `MaleText_loc7`='¡Que conquista una tierra nueva y extraña!' WHERE `ID`=75056;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='거기 꼭 "정복"이라는 말을 써야 하나?', `MaleText_loc4`='一定要用“征服”这个词吗？', `MaleText_loc5`='我們非得用「征服」這個字眼嗎?', `MaleText_loc7`='¿Tenemos que usar esa palabra, "conquistar"?' WHERE `ID`=75058;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잊혀진 금고를 탐험하고...', `MaleText_loc4`='深入被遗忘的宝库……', `MaleText_loc5`='探索了被遺忘的寶庫...', `MaleText_loc7`='Que se aventura en zonas olvidadas…' WHERE `ID`=75059;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='사마귀와 모구까지, 모두 영웅의 분노에 무릎을 꿇었지.', `MaleText_loc4`='用怒火折服了螳螂妖和魔古族。', `MaleText_loc5`='螳螂人跟魔古都在英雄之怒下低頭。', `MaleText_loc7`='Tanto Mántide como Mogu fueron derrotados por la furia de nuestro valiente.' WHERE `ID`=75061;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그들의 힘과 지혜는 더 큰 영광을 위해 이용되었다!', `MaleText_loc4`='凭力量和智慧攫取了更光辉的荣耀！', `MaleText_loc5`='為更遠大的榮耀奪取了他們的力量與智慧!', `MaleText_loc7`='¡Su poder y sabiduría fueron tomados a la fuerza para una gloria mayor!' WHERE `ID`=75064;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='판다리아의 해안에 전쟁의 파도가 밀려오고, 영웅은 일어섰네.', `MaleText_loc4`='当战火降临，我们的英雄早有准备。', `MaleText_loc5`='當潘達利亞的海岸陷入戰爭，我們的英雄已經就緒。', `MaleText_loc7`='Cuando la guerra llegó a las costas de Pandaria, nuestro valiente ya estaba ahí.' WHERE `ID`=75066;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='진영의 대표자, 동족에겐 사랑받는 영웅, 적에겐 공포의 대상으로서.', `MaleText_loc4`='这位万众爱戴的英勇先驱，让敌人望风披靡。', `MaleText_loc5`='身為陣營的旗手，人們愛戴他，敵人恐懼他。', `MaleText_loc7`='Un portador de confalón de facción, amado por el pueblo y temido por sus enemigos.' WHERE `ID`=75067;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='강대한 천둥왕도 용사의 힘 앞에 쓰러질 수밖에 없었고.', `MaleText_loc4`='就连雷电之王，都倒在这位勇士的脚下。', `MaleText_loc5`='連強大的雷王也倒在我們勇士的腳下。', `MaleText_loc7`='Hasta el poderoso Rey del Trueno cayó frente a la fuerza de nuestro valiente.' WHERE `ID`=75068;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='하나씩 하나씩, 고대 제국의 비밀이 만천하에 드러났지.', `MaleText_loc4`='雷神那古老帝国的秘密也被一一破解。', `MaleText_loc5`='古老帝國的秘密一個又一個的被揭開。', `MaleText_loc7`='Uno a uno, los secretos de un imperio ancestral quedaron expuestos.' WHERE `ID`=75069;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그래, 우린 세상을 널리 이롭게 할 지식을 밝혀냈어.', `MaleText_loc4`='发现了令全世界受益的知识。', `MaleText_loc5`='為了世界更美好而挖掘知識。', `MaleText_loc7`='Un conocimiento descubierto para el beneficio del mundo.' WHERE `ID`=75070;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='영웅은 전쟁과 정복을 위한 힘을 얻었지!', `MaleText_loc4`='获得了战争与征服的力量！', `MaleText_loc5`='為了戰爭與征服而取得力量!', `MaleText_loc7`='¡PODER adquirido para la GUERRA y la CONQUISTA!' WHERE `ID`=75071;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='그 후엔 고대 신께서 사마귀를 위해 이 세상을 재창조하시리라!', `MaleText_loc4`='然后，上古尊者会将这个世界赐予螳螂妖！', `MaleText_loc5`='然後上古之神會為螳螂人重建這個世界!', `MaleText_loc7`='¡Y luego el Antiguo reconstruirá este mundo para los Mántides!' WHERE `ID`=75072;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='네놈들 피를 마시겠다!', `MaleText_loc4`='我要畅饮你的鲜血！', `MaleText_loc5`='我會飲你們的血!', `MaleText_loc7`='¡Beberé su sangre!' WHERE `ID`=75073;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='잠깐만 기다려 보게... 지금 어떤 영웅 얘기를 하고 있는 건가?', `MaleText_loc4`='等等，不太对劲——这是我所说的那个英雄吗？', `MaleText_loc5`='我們先停一會兒-我們在說的是哪位英雄啊?', `MaleText_loc7`='Detengámonos un momento... ¿de qué clase de valiente estamos hablando?' WHERE `ID`=75074;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='적의 피로 포식해라!', `MaleText_loc4`='享用敌人的鲜血吧！', `MaleText_loc5`='暢飲敵人的鮮血吧!', `MaleText_loc7`='¡Me daré un festín con la sangre de nuestros enemigos!' WHERE `ID`=75075;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='검에 또 금을 새겨야겠군.', `MaleText_loc4`='我的刀上又多了一个缺口。', `MaleText_loc5`='我的刀又砍出一個缺口了。', `MaleText_loc7`='Otra muesca para mi espada.' WHERE `ID`=75076;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='복수를 부탁하네, 형제들이여!', `MaleText_loc4`='兄弟们，为我复仇！', `MaleText_loc5`='替我報仇，兄弟們!', `MaleText_loc7`='¡Vénguenme, hermanos!' WHERE `ID`=75077;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='내 의지에 따라 만들어진 파괴의 대리인, 아제로스의 모습을 영원히 바꿀 자이지!', `MaleText_loc4`='我亲手造就的毁灭使者，他将永远改变艾泽拉斯的面貌。', `MaleText_loc5`='毀滅的使者，由我的意志塑造來永遠改變艾澤拉斯的面貌。', `MaleText_loc7`='Un agente de la destrucción, forjado por mi voluntad para cambiar por siempre la faz de Azeroth.' WHERE `ID`=75078;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 옛날 판다렌을 처치했듯이 쉽게 너희를 처치할 것이다.', `MaleText_loc4`='干掉你们简直易如反掌，就像过去屠杀熊猫人一样。', `MaleText_loc5`='我們會像以前屠殺熊貓人一樣輕易殺死你們。', `MaleText_loc7`='Te mataremos con la facilidad que matamos a los Pandaren de la antigüedad.' WHERE `ID`=75079;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 느리구나. 그래서 먹이는 어떻게 잡지?', `MaleText_loc4`='你们的速度太慢了，这副德性还怎么捕猎？', `MaleText_loc5`='你們如此緩慢，你們是怎麼抓到獵物的?', `MaleText_loc7`='Qué lento se mueven, ¿cómo hace tu especie para atrapar a sus presas?' WHERE `ID`=75080;
