UPDATE `locales_broadcast_text` SET `MaleText_loc1`='음하하하하하하하!', `MaleText_loc4`='啊哈哈哈哈！', `MaleText_loc5`='哈哈哈哈!', `MaleText_loc7`='¡Muajajajajaja!' WHERE `ID`=75082;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='친구여, 자네가 이 세상에 어떤 유산을 남길지 잘 생각해 보게.', `MaleText_loc4`='我的朋友，请认真考虑要为后人留下什么。', `MaleText_loc5`='朋友，請小心思考你留給後世的價值。', `MaleText_loc7`='Mi amigo, piensa cuidadosamente en el legado que dejarás.' WHERE `ID`=75083;
