UPDATE `locales_broadcast_text` SET `MaleText_loc1`='보아라! 잠들어 있던 티탄의 힘을! 내가 지닌 용의 정수로 강화되고, 판다렌 천신들의 지혜로 단련되었지.', `MaleText_loc4`='看呐！它暗藏泰坦之力，注入了我的巨龙精华，由睿智的熊猫人天神淬炼。', `MaleText_loc5`='看啊!潛藏的泰坦力量，注入了我的龍族精華，還有熊貓人天尊智慧的洗煉。', `MaleText_loc7`='¡Contemplen! Poder titánico latente, empapado con mi propia esencia dracónica, moldeado por la sabiduría de los celestiales Pandaren.' WHERE `ID`=75085;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='너무 느리군.', `MaleText_loc4`='太慢了。', `MaleText_loc5`='真是慢啊。', `MaleText_loc7`='Demasiado lento.' WHERE `ID`=75086;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='놈들이 쓰러지는 꼴이 꼭 바람에 흩날리는 풀잎 같구나.', `MaleText_loc4`='看看他们倒下的样子，活像狂风中的杂草。', `MaleText_loc5`='看他們倒下的樣子，像風中被吹散的雜草。', `MaleText_loc7`='Miren cómo caen, como hojas de pasto en el viento.' WHERE `ID`=75087;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='으, 망할 갑각 때문에 빨리 움직일 수가 없었어!', `MaleText_loc4`='这该死的甲壳，我还不够快！', `MaleText_loc5`='這該死的甲殼，我還不夠快!', `MaleText_loc7`='¡Maldita sea esta coraza quitinosa! ¡Me quitó velocidad!' WHERE `ID`=75088;
UPDATE `locales_broadcast_text` SET `MaleText_loc1`='압도적인 힘! 이 힘으로 치유하거나 파괴하라! 보호하거나 말살시켜라!', `MaleText_loc4`='它无所不能。守护还是毁灭，尽在你的掌握！', `MaleText_loc5`='無比強大的力量。用它來治療或摧毀!來保護或消滅!', `MaleText_loc7`='Poder abrumador. ¡Úsalo para sanar o destruir! ¡Para proteger o aniquilar!' WHERE `ID`=75089;
