UPDATE `locales_broadcast_text` SET `MaleText_loc1`='우리는 강탈자들과 그 자손을 이겼고, 고대 신의 실종을 견뎠다. 이제 너희 차례다.', `MaleText_loc4`='我们忍受着篡位者和他子民的行径，熬过了上古尊者的陨落，很快……就轮到你们了。', `MaleText_loc5`='我們經歷了篡位者和他們的孩子，還有上古之神的消失，你們也將成為過去。', `MaleText_loc7`='Hemos resistido a los Usurpadores, a sus hijos, a la pérdida del Antiguo y pronto... a ti.' WHERE `ID`=75099;
